import type { QuestionBank } from '../lib/questions/types';

export const aiQuestions: QuestionBank = {"escape-rhythms-sinus-dysfunction":[{"id":"escape-rhythms-sinus-dysfunction~ai-0","moduleId":"escape-rhythms-sinus-dysfunction","stem":"What is the primary pacemaker of the heart under normal conditions?","options":[{"id":"a","text":"Atrioventricular node"},{"id":"b","text":"Bundle of His"},{"id":"c","text":"Sinoatrial node"},{"id":"d","text":"Ventricular myocardium"}],"answerId":"c","explanation":"The sinoatrial node (SA node) is the primary pacemaker, setting the heart rate at 60-100 bpm.","kind":"recall","origin":"ai"},{"id":"escape-rhythms-sinus-dysfunction~ai-1","moduleId":"escape-rhythms-sinus-dysfunction","stem":"In a patient with sinus arrest, what is the expected ECG finding during the pause?","options":[{"id":"a","text":"Narrow QRS complex"},{"id":"b","text":"Dropped P wave"},{"id":"c","text":"Wide QRS complex"},{"id":"d","text":"ST elevation"}],"answerId":"b","explanation":"During a sinus arrest, there is a failure of the SA node to fire, leading to a dropped P wave and subsequent pause.","kind":"recall","origin":"ai"},{"id":"escape-rhythms-sinus-dysfunction~ai-2","moduleId":"escape-rhythms-sinus-dysfunction","stem":"What mechanism allows a junctional escape rhythm to take over when the SA node fails?","options":[{"id":"a","text":"Increased vagal tone"},{"id":"b","text":"Overdrive suppression"},{"id":"c","text":"Intrinsic pacing of the AV node"},{"id":"d","text":"Reentry circuit formation"}],"answerId":"c","explanation":"The AV node can act as a backup pacemaker, intrinsic pacing at 40-60 bpm when the SA node fails.","kind":"mechanism","origin":"ai"},{"id":"escape-rhythms-sinus-dysfunction~ai-3","moduleId":"escape-rhythms-sinus-dysfunction","stem":"Which of the following is a potential consequence of suppressing a ventricular escape rhythm?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Asystole"},{"id":"c","text":"Atrial fibrillation"},{"id":"d","text":"Ventricular tachycardia"}],"answerId":"b","explanation":"Suppressing a ventricular escape rhythm can lead to asystole, as it is a life-saving backup pacemaker.","kind":"trap","origin":"ai"},{"id":"escape-rhythms-sinus-dysfunction~ai-4","moduleId":"escape-rhythms-sinus-dysfunction","stem":"What is the expected QRS morphology in a junctional escape rhythm?","options":[{"id":"a","text":"Narrow QRS complex"},{"id":"b","text":"Wide QRS complex"},{"id":"c","text":"Bifascicular block"},{"id":"d","text":"Normal QRS complex"}],"answerId":"a","explanation":"A junctional escape rhythm is characterized by a narrow QRS complex (40-60 bpm).","kind":"recall","origin":"ai"},{"id":"escape-rhythms-sinus-dysfunction~ai-5","moduleId":"escape-rhythms-sinus-dysfunction","stem":"How does atropine help in the management of symptomatic bradycardia?","options":[{"id":"a","text":"Increases vagal tone"},{"id":"b","text":"Increases heart rate by blocking parasympathetic effects"},{"id":"c","text":"Directly stimulates the SA node"},{"id":"d","text":"Increases myocardial contractility"}],"answerId":"b","explanation":"Atropine blocks parasympathetic effects, leading to an increase in heart rate.","kind":"mechanism","origin":"ai"},{"id":"escape-rhythms-sinus-dysfunction~ai-6","moduleId":"escape-rhythms-sinus-dysfunction","stem":"In a patient with a wide QRS escape rhythm, which of the following is the most likely origin of the escape pacemaker?","options":[{"id":"a","text":"Sinoatrial node"},{"id":"b","text":"Atrioventricular node"},{"id":"c","text":"Ventricular myocardium"},{"id":"d","text":"Bundle of His"}],"answerId":"c","explanation":"A wide QRS escape rhythm indicates that the pacemaker is originating from the ventricular myocardium.","kind":"integration","linkedModuleIds":["bundle-branch-block"],"origin":"ai"},{"id":"escape-rhythms-sinus-dysfunction~ai-7","moduleId":"escape-rhythms-sinus-dysfunction","stem":"How might a junctional escape rhythm affect the interpretation of an ECG in the context of a STEMI?","options":[{"id":"a","text":"It may mimic ST elevation"},{"id":"b","text":"It can obscure Q waves"},{"id":"c","text":"It can cause reciprocal changes"},{"id":"d","text":"It may lead to misinterpretation of heart rate"}],"answerId":"d","explanation":"A junctional escape rhythm can lead to misinterpretation of heart rate on an ECG, complicating the assessment of STEMI.","kind":"integration","linkedModuleIds":["stemi-localization"],"origin":"ai"}],"vsd":[{"id":"vsd~ai-0","moduleId":"vsd","stem":"What is the most common type of Ventricular Septal Defect (VSD)?","options":[{"id":"a","text":"Muscular VSD"},{"id":"b","text":"Inlet VSD"},{"id":"c","text":"Subpulmonic VSD"},{"id":"d","text":"Perimembranous VSD"}],"answerId":"d","explanation":"Perimembranous VSD is the most common type, accounting for approximately 50% of cases.","kind":"recall","origin":"ai"},{"id":"vsd~ai-1","moduleId":"vsd","stem":"What is the primary hemodynamic consequence of a large Ventricular Septal Defect?","options":[{"id":"a","text":"Right-to-left shunt"},{"id":"b","text":"Increased systemic vascular resistance"},{"id":"c","text":"Increased pulmonary blood flow"},{"id":"d","text":"Decreased left ventricular volume"}],"answerId":"c","explanation":"A large VSD causes a left-to-right shunt, leading to increased pulmonary blood flow and potential heart failure.","kind":"mechanism","origin":"ai"},{"id":"vsd~ai-2","moduleId":"vsd","stem":"Which clinical finding is characteristic of a large Ventricular Septal Defect?","options":[{"id":"a","text":"Ejection systolic murmur at the upper sternal border"},{"id":"b","text":"Harsh pansystolic murmur at the left lower sternal border"},{"id":"c","text":"Diastolic murmur at the right sternal border"},{"id":"d","text":"Systolic click at the apex"}],"answerId":"b","explanation":"A harsh pansystolic murmur at the left lower sternal border is characteristic of VSD due to high-pressure flow from the left ventricle to the right ventricle.","kind":"clinical","origin":"ai"},{"id":"vsd~ai-3","moduleId":"vsd","stem":"What is the expected change in murmur intensity as a VSD defect size increases?","options":[{"id":"a","text":"Murmur becomes louder"},{"id":"b","text":"Murmur remains unchanged"},{"id":"c","text":"Murmur becomes softer"},{"id":"d","text":"Murmur disappears completely"}],"answerId":"c","explanation":"As the defect size increases, the murmur becomes softer due to equalization of pressures and reduced turbulence.","kind":"trap","origin":"ai"},{"id":"vsd~ai-4","moduleId":"vsd","stem":"What symptom typically appears in infants with a Ventricular Septal Defect around 4-6 weeks of age?","options":[{"id":"a","text":"Cyanosis"},{"id":"b","text":"Heart failure"},{"id":"c","text":"Murmur"},{"id":"d","text":"Clubbing"}],"answerId":"b","explanation":"Symptoms of heart failure, such as tachypnea and poor feeding, typically appear around 4-6 weeks as pulmonary vascular resistance decreases.","kind":"recall","origin":"ai"},{"id":"vsd~ai-5","moduleId":"vsd","stem":"How does a Ventricular Septal Defect relate to Congenital Adrenal Hyperplasia in clinical management?","options":[{"id":"a","text":"Both require surgical intervention immediately after birth"},{"id":"b","text":"Both can lead to heart failure"},{"id":"c","text":"Both are associated with increased pulmonary blood flow"},{"id":"d","text":"Both can present with cyanosis"}],"answerId":"b","explanation":"Both conditions can lead to heart failure, requiring careful monitoring and management of symptoms.","kind":"integration","linkedModuleIds":["congenital-adrenal-hyperplasia"],"origin":"ai"},{"id":"vsd~ai-6","moduleId":"vsd","stem":"Which developmental abnormality is directly related to the formation of a Ventricular Septal Defect?","options":[{"id":"a","text":"Atrial septal defect"},{"id":"b","text":"Failure of septation of the heart tube"},{"id":"c","text":"Transposition of the great vessels"},{"id":"d","text":"Coarctation of the aorta"}],"answerId":"b","explanation":"Ventricular Septal Defects arise from failures in the septation process during heart development.","kind":"integration","linkedModuleIds":["heart-tube-looping-septation"],"origin":"ai"}],"premature-contractions":[{"id":"premature-contractions~ai-0","moduleId":"premature-contractions","stem":"What is the characteristic ECG finding of a premature atrial contraction (PAC)?","options":[{"id":"a","text":"Early abnormal P wave with a normal narrow QRS"},{"id":"b","text":"Early wide bizarre QRS with no preceding P wave"},{"id":"c","text":"Normal P wave followed by a wide QRS"},{"id":"d","text":"Prolonged QT interval"}],"answerId":"a","explanation":"PACs are identified by an early abnormal P wave followed by a normal narrow QRS complex.","kind":"recall","origin":"ai"},{"id":"premature-contractions~ai-1","moduleId":"premature-contractions","stem":"What is the mechanism behind the compensatory pause following a premature ventricular contraction (PVC)?","options":[{"id":"a","text":"Resetting of the SA node"},{"id":"b","text":"Increased vagal tone"},{"id":"c","text":"Decreased stroke volume"},{"id":"d","text":"Normal conduction through the AV node"}],"answerId":"a","explanation":"A PVC does not reset the SA node, resulting in a full compensatory pause as the next sinus beat arrives on schedule.","kind":"mechanism","origin":"ai"},{"id":"premature-contractions~ai-2","moduleId":"premature-contractions","stem":"Which of the following is a potential danger associated with premature ventricular contractions?","options":[{"id":"a","text":"Always requires antiarrhythmic treatment"},{"id":"b","text":"Can trigger ventricular fibrillation if it occurs on the T wave"},{"id":"c","text":"Always leads to symptomatic bradycardia"},{"id":"d","text":"Is indicative of underlying coronary artery disease"}],"answerId":"b","explanation":"The danger of PVCs lies in the potential for them to occur on the T wave, which can trigger ventricular fibrillation.","kind":"trap","origin":"ai"},{"id":"premature-contractions~ai-3","moduleId":"premature-contractions","stem":"A patient reports feeling palpitations and a 'skipped beat.' What is the likely explanation for this sensation?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Compensatory pause after a premature beat"},{"id":"c","text":"Decreased cardiac output"},{"id":"d","text":"Atrial fibrillation"}],"answerId":"b","explanation":"The sensation of a 'skipped beat' is typically due to a premature beat followed by a compensatory pause.","kind":"clinical","origin":"ai"},{"id":"premature-contractions~ai-4","moduleId":"premature-contractions","stem":"In the context of premature contractions, what distinguishes a PAC from a PVC in terms of pause?","options":[{"id":"a","text":"PAC causes a full compensatory pause"},{"id":"b","text":"PVC causes a non-compensatory pause"},{"id":"c","text":"PAC usually resets the SA node, while PVC does not"},{"id":"d","text":"Both cause the same type of pause"}],"answerId":"c","explanation":"PACs usually reset the SA node and result in a non-compensatory pause, while PVCs lead to a full compensatory pause.","kind":"trap","origin":"ai"},{"id":"premature-contractions~ai-5","moduleId":"premature-contractions","stem":"How does the management of symptomatic PVCs relate to the treatment of ventricular tachycardia (VT)?","options":[{"id":"a","text":"Both require immediate defibrillation"},{"id":"b","text":"Both can be treated with beta-blockers"},{"id":"c","text":"Management of PVCs does not relate to VT"},{"id":"d","text":"Only VT requires antiarrhythmic medication"}],"answerId":"b","explanation":"Symptomatic PVCs can be managed with beta-blockers, similar to the treatment approach for ventricular tachycardia.","kind":"integration","linkedModuleIds":["ventricular-tachycardia"],"origin":"ai"},{"id":"premature-contractions~ai-6","moduleId":"premature-contractions","stem":"What is the relationship between premature contractions and the risk of developing ventricular fibrillation?","options":[{"id":"a","text":"All premature contractions lead to ventricular fibrillation"},{"id":"b","text":"Only PACs can trigger ventricular fibrillation"},{"id":"c","text":"PVCs can trigger ventricular fibrillation during the vulnerable T wave period"},{"id":"d","text":"Ventricular fibrillation is unrelated to premature contractions"}],"answerId":"c","explanation":"PVCs can trigger ventricular fibrillation if they occur during the vulnerable period of the T wave.","kind":"integration","linkedModuleIds":["ventricular-fibrillation"],"origin":"ai"}],"stemi-localization":[{"id":"stemi-localization~ai-0","moduleId":"stemi-localization","stem":"Which leads indicate an inferior STEMI?","options":[{"id":"a","text":"I, II, III"},{"id":"b","text":"V1–V4"},{"id":"c","text":"II, III, aVF"},{"id":"d","text":"V5–V6"}],"answerId":"c","explanation":"Leads II, III, and aVF correspond to the inferior wall of the heart, indicating RCA or LCx territory involvement.","kind":"recall","origin":"ai"},{"id":"stemi-localization~ai-1","moduleId":"stemi-localization","stem":"What is the mechanism behind ST elevation in STEMI?","options":[{"id":"a","text":"Coronary occlusion leads to ischemia"},{"id":"b","text":"Increased heart rate causes ST elevation"},{"id":"c","text":"Territory injury current causes ST elevation"},{"id":"d","text":"Electrolyte imbalances lead to ST elevation"}],"answerId":"c","explanation":"ST elevation occurs due to territory injury current resulting from coronary occlusion.","kind":"mechanism","origin":"ai"},{"id":"stemi-localization~ai-2","moduleId":"stemi-localization","stem":"In a patient with an inferior STEMI, which finding would indicate right ventricular involvement?","options":[{"id":"a","text":"ST elevation in V1"},{"id":"b","text":"ST depression in V5"},{"id":"c","text":"ST elevation in V4R"},{"id":"d","text":"ST elevation in V7"}],"answerId":"c","explanation":"ST elevation in V4R indicates right ventricular involvement in the context of an inferior STEMI.","kind":"recall","origin":"ai"},{"id":"stemi-localization~ai-3","moduleId":"stemi-localization","stem":"What is the appropriate management for an inferior STEMI with suspected RV involvement?","options":[{"id":"a","text":"Administer nitrates"},{"id":"b","text":"Give fluids"},{"id":"c","text":"Perform immediate angioplasty"},{"id":"d","text":"Monitor without intervention"}],"answerId":"b","explanation":"In cases of RV involvement, fluids should be given to maintain preload, while nitrates should be avoided.","kind":"clinical","origin":"ai"},{"id":"stemi-localization~ai-4","moduleId":"stemi-localization","stem":"Which of the following is a trap regarding lead territories in STEMI?","options":[{"id":"a","text":"ST elevation in V1–V4 indicates inferior MI"},{"id":"b","text":"ST elevation in II, III, aVF indicates anterior MI"},{"id":"c","text":"ST elevation in V5–V6 indicates lateral MI"},{"id":"d","text":"ST elevation in II, III, aVF indicates inferior MI"}],"answerId":"d","explanation":"ST elevation in II, III, and aVF indicates an inferior MI; mixing these up with anterior leads can lead to incorrect management.","kind":"trap","origin":"ai"},{"id":"stemi-localization~ai-5","moduleId":"stemi-localization","stem":"How does a new left bundle branch block (LBBB) relate to STEMI?","options":[{"id":"a","text":"It is a benign finding"},{"id":"b","text":"It indicates a prior myocardial infarction"},{"id":"c","text":"It is considered a STEMI-equivalent"},{"id":"d","text":"It has no clinical significance"}],"answerId":"c","explanation":"A new LBBB in the presence of ischemic symptoms is considered a STEMI-equivalent, warranting urgent evaluation.","kind":"recall","origin":"ai"},{"id":"stemi-localization~ai-6","moduleId":"stemi-localization","stem":"How does STEMI localization relate to coronary supply?","options":[{"id":"a","text":"Lateral MI corresponds to RCA supply"},{"id":"b","text":"Inferior MI corresponds to LAD supply"},{"id":"c","text":"Anterior MI corresponds to LCx supply"},{"id":"d","text":"Inferior MI corresponds to RCA/LCx supply"}],"answerId":"d","explanation":"Inferior STEMI is associated with RCA or LCx supply, while anterior MI correlates with LAD supply.","kind":"integration","linkedModuleIds":["heart-valves-coronary-supply"],"origin":"ai"},{"id":"stemi-localization~ai-7","moduleId":"stemi-localization","stem":"What is the significance of reciprocal ST depression in STEMI diagnosis?","options":[{"id":"a","text":"It confirms a false positive"},{"id":"b","text":"It indicates a prior MI"},{"id":"c","text":"It supports the diagnosis of STEMI"},{"id":"d","text":"It has no diagnostic value"}],"answerId":"c","explanation":"Reciprocal ST depression in leads opposite to the ST elevation supports the diagnosis of a true STEMI.","kind":"integration","linkedModuleIds":["ecg-systematic-interpretation"],"origin":"ai"}],"ventricular-fibrillation":[{"id":"ventricular-fibrillation~ai-0","moduleId":"ventricular-fibrillation","stem":"What is the primary mechanism underlying ventricular fibrillation?","options":[{"id":"a","text":"Re-entry"},{"id":"b","text":"Increased vagal tone"},{"id":"c","text":"Myocardial ischemia"},{"id":"d","text":"Electrolyte imbalance"}],"answerId":"a","explanation":"Ventricular fibrillation is primarily caused by re-entry mechanisms leading to disorganized electrical activity.","kind":"mechanism","origin":"ai"},{"id":"ventricular-fibrillation~ai-1","moduleId":"ventricular-fibrillation","stem":"Which ECG finding is characteristic of ventricular fibrillation?","options":[{"id":"a","text":"Regular narrow QRS complexes"},{"id":"b","text":"Chaotic baseline with no distinct waves"},{"id":"c","text":"Wide QRS complexes with ST elevation"},{"id":"d","text":"P waves followed by QRS complexes"}],"answerId":"b","explanation":"Ventricular fibrillation presents with a chaotic baseline and no identifiable P, QRS, or T waves.","kind":"recall","origin":"ai"},{"id":"ventricular-fibrillation~ai-2","moduleId":"ventricular-fibrillation","stem":"What is the immediate treatment for a patient in ventricular fibrillation?","options":[{"id":"a","text":"Synchronized cardioversion"},{"id":"b","text":"Unsynchronized defibrillation"},{"id":"c","text":"Amiodarone infusion"},{"id":"d","text":"Magnesium sulfate administration"}],"answerId":"b","explanation":"The only effective treatment for ventricular fibrillation is immediate unsynchronized defibrillation.","kind":"recall","origin":"ai"},{"id":"ventricular-fibrillation~ai-3","moduleId":"ventricular-fibrillation","stem":"Which of the following best describes a clinical finding in a patient with ventricular fibrillation?","options":[{"id":"a","text":"Bradycardia with hypotension"},{"id":"b","text":"Unresponsive, pulseless, apneic"},{"id":"c","text":"Regular heart sounds with normal blood pressure"},{"id":"d","text":"Tachycardia with chest pain"}],"answerId":"b","explanation":"Patients in ventricular fibrillation are unresponsive, pulseless, and apneic due to lack of cardiac output.","kind":"clinical","origin":"ai"},{"id":"ventricular-fibrillation~ai-4","moduleId":"ventricular-fibrillation","stem":"What initiates ventricular fibrillation during the cardiac cycle?","options":[{"id":"a","text":"Any PVC"},{"id":"b","text":"PVC during the vulnerable period"},{"id":"c","text":"Atrial contraction"},{"id":"d","text":"Prolonged QT interval"}],"answerId":"b","explanation":"A PVC occurring during the vulnerable period (R-on-T phenomenon) can trigger ventricular fibrillation.","kind":"trap","origin":"ai"},{"id":"ventricular-fibrillation~ai-5","moduleId":"ventricular-fibrillation","stem":"How does ventricular fibrillation relate to atrial fibrillation?","options":[{"id":"a","text":"Both are caused by re-entry mechanisms"},{"id":"b","text":"VF can be a consequence of untreated AF"},{"id":"c","text":"AF is always a precursor to VF"},{"id":"d","text":"Both present with distinct P waves"}],"answerId":"b","explanation":"Ventricular fibrillation can occur as a consequence of untreated atrial fibrillation due to rapid ventricular rates.","kind":"integration","linkedModuleIds":["atrial-fibrillation"],"origin":"ai"},{"id":"ventricular-fibrillation~ai-6","moduleId":"ventricular-fibrillation","stem":"Which treatment strategy for ventricular fibrillation is similar to that for atrial flutter?","options":[{"id":"a","text":"Unsynchronized defibrillation"},{"id":"b","text":"Synchronized cardioversion"},{"id":"c","text":"Antiarrhythmic medication"},{"id":"d","text":"Vagal maneuvers"}],"answerId":"b","explanation":"Synchronized cardioversion is used for atrial flutter, while unsynchronized defibrillation is used for ventricular fibrillation.","kind":"integration","linkedModuleIds":["atrial-flutter"],"origin":"ai"}],"asd":[{"id":"asd~ai-0","moduleId":"asd","stem":"What is the most common type of atrial septal defect (ASD)?","options":[{"id":"a","text":"Primum ASD"},{"id":"b","text":"Secundum ASD"},{"id":"c","text":"Sinus venosus ASD"},{"id":"d","text":"Coronary sinus ASD"}],"answerId":"b","explanation":"Secundum ASD accounts for approximately 75% of all ASDs, making it the most common type.","kind":"recall","origin":"ai"},{"id":"asd~ai-1","moduleId":"asd","stem":"What is the hallmark auscultatory finding in atrial septal defect (ASD)?","options":[{"id":"a","text":"Loud single S2"},{"id":"b","text":"Widely fixed split S2"},{"id":"c","text":"Systolic ejection murmur at LUSB"},{"id":"d","text":"Mid-diastolic tricuspid rumble"}],"answerId":"b","explanation":"A widely fixed split S2 is characteristic of ASD due to right ventricular volume overload.","kind":"recall","origin":"ai"},{"id":"asd~ai-2","moduleId":"asd","stem":"Which mechanism explains the widely fixed split S2 in ASD?","options":[{"id":"a","text":"Increased left atrial pressure"},{"id":"b","text":"Right ventricular volume overload"},{"id":"c","text":"Pulmonary valve stenosis"},{"id":"d","text":"Increased systemic vascular resistance"}],"answerId":"b","explanation":"Right ventricular volume overload keeps the RV ejection time constant, leading to a fixed split S2.","kind":"mechanism","origin":"ai"},{"id":"asd~ai-3","moduleId":"asd","stem":"In atrial septal defect (ASD), what causes the systolic ejection murmur at the left upper sternal border (LUSB)?","options":[{"id":"a","text":"Flow across the ASD"},{"id":"b","text":"Relative pulmonary stenosis"},{"id":"c","text":"Tricuspid regurgitation"},{"id":"d","text":"Aortic stenosis"}],"answerId":"b","explanation":"The systolic ejection murmur is due to relative pulmonary stenosis from increased flow across a normal pulmonary valve.","kind":"mechanism","origin":"ai"},{"id":"asd~ai-4","moduleId":"asd","stem":"A 30-year-old patient with a history of ASD presents with new-onset atrial fibrillation. What is the most likely underlying cause?","options":[{"id":"a","text":"Increased left atrial pressure"},{"id":"b","text":"Right ventricular hypertrophy"},{"id":"c","text":"Pulmonary hypertension"},{"id":"d","text":"Paradoxical embolism"}],"answerId":"c","explanation":"Pulmonary hypertension can develop due to increased pulmonary blood flow from the left-to-right shunt, leading to atrial fibrillation.","kind":"clinical","origin":"ai"},{"id":"asd~ai-5","moduleId":"asd","stem":"Which of the following findings would be incorrectly attributed to an atrial septal defect (ASD)?","options":[{"id":"a","text":"Widely fixed split S2"},{"id":"b","text":"Loud single S2"},{"id":"c","text":"Systolic ejection murmur at LUSB"},{"id":"d","text":"Mid-diastolic tricuspid rumble"}],"answerId":"b","explanation":"A loud single S2 is not characteristic of ASD; the correct finding is a widely fixed split S2.","kind":"trap","origin":"ai"},{"id":"asd~ai-6","moduleId":"asd","stem":"How does the presence of a patent ductus arteriosus (PDA) affect the hemodynamics in a patient with an atrial septal defect (ASD)?","options":[{"id":"a","text":"Increases left-to-right shunt"},{"id":"b","text":"Decreases pulmonary blood flow"},{"id":"c","text":"Causes right-to-left shunt"},{"id":"d","text":"Reduces right atrial pressure"}],"answerId":"a","explanation":"A PDA increases the left-to-right shunt, exacerbating volume overload in the right heart.","kind":"integration","linkedModuleIds":["pda"],"origin":"ai"},{"id":"asd~ai-7","moduleId":"asd","stem":"In a patient with both ASD and Tetralogy of Fallot (TOF), which finding would be most indicative of the ASD component?","options":[{"id":"a","text":"Cyanosis"},{"id":"b","text":"Widely fixed split S2"},{"id":"c","text":"Systolic ejection murmur at LUSB"},{"id":"d","text":"Right ventricular outflow obstruction"}],"answerId":"b","explanation":"A widely fixed split S2 is indicative of ASD, while cyanosis and right ventricular outflow obstruction are more characteristic of TOF.","kind":"integration","linkedModuleIds":["tetralogy-of-fallot"],"origin":"ai"}],"av-block":[{"id":"av-block~ai-0","moduleId":"av-block","stem":"What is the characteristic finding in 1° AV block?","options":[{"id":"a","text":"PR interval >200 ms with every P wave conducting"},{"id":"b","text":"Progressive PR lengthening with dropped QRS"},{"id":"c","text":"Constant PR interval with sudden dropped QRS"},{"id":"d","text":"Complete dissociation between P waves and QRS complexes"}],"answerId":"a","explanation":"In 1° AV block, the PR interval is prolonged but every P wave is followed by a QRS complex.","kind":"recall","origin":"ai"},{"id":"av-block~ai-1","moduleId":"av-block","stem":"Which type of AV block is characterized by progressive PR interval lengthening followed by a dropped QRS complex?","options":[{"id":"a","text":"1° AV block"},{"id":"b","text":"Mobitz I (Wenckebach)"},{"id":"c","text":"Mobitz II"},{"id":"d","text":"Complete AV block"}],"answerId":"b","explanation":"Mobitz I (Wenckebach) is defined by progressive PR lengthening leading to a dropped QRS.","kind":"recall","origin":"ai"},{"id":"av-block~ai-2","moduleId":"av-block","stem":"In which type of AV block is the PR interval constant, but there is a risk of sudden dropped QRS complexes?","options":[{"id":"a","text":"1° AV block"},{"id":"b","text":"Mobitz I"},{"id":"c","text":"Mobitz II"},{"id":"d","text":"Complete AV block"}],"answerId":"c","explanation":"Mobitz II is characterized by a constant PR interval with the risk of sudden drops in QRS complexes.","kind":"recall","origin":"ai"},{"id":"av-block~ai-3","moduleId":"av-block","stem":"What is a common clinical finding in complete AV block?","options":[{"id":"a","text":"Cannon A waves in the JVP"},{"id":"b","text":"Fixed PR interval"},{"id":"c","text":"Bradycardia with progressive PR lengthening"},{"id":"d","text":"Variable-intensity S1"}],"answerId":"a","explanation":"Cannon A waves occur due to atrial contractions against closed AV valves during AV dissociation.","kind":"clinical","origin":"ai"},{"id":"av-block~ai-4","moduleId":"av-block","stem":"Why is atropine ineffective in Mobitz II and complete AV block?","options":[{"id":"a","text":"It increases vagal tone"},{"id":"b","text":"It only affects the His-Purkinje system"},{"id":"c","text":"It does not improve conduction through infranodal blocks"},{"id":"d","text":"It is contraindicated in bradycardia"}],"answerId":"c","explanation":"Atropine helps with AV nodal blocks but does not improve conduction in infranodal blocks like Mobitz II and complete block.","kind":"trap","origin":"ai"},{"id":"av-block~ai-5","moduleId":"av-block","stem":"Which type of AV block requires a pacemaker due to high risk of progression?","options":[{"id":"a","text":"1° AV block"},{"id":"b","text":"Mobitz I"},{"id":"c","text":"Mobitz II"},{"id":"d","text":"Complete AV block"}],"answerId":"c","explanation":"Mobitz II is a high-risk block that typically requires a pacemaker due to the risk of sudden complete block.","kind":"recall","origin":"ai"},{"id":"av-block~ai-6","moduleId":"av-block","stem":"How does the histology of the conduction system relate to Mobitz II block?","options":[{"id":"a","text":"It shows degeneration of AV node cells"},{"id":"b","text":"It reveals fibrosis in His-Purkinje fibers"},{"id":"c","text":"It indicates inflammation in atrial tissues"},{"id":"d","text":"It demonstrates hypertrophy of ventricular myocardium"}],"answerId":"b","explanation":"Mobitz II often involves degeneration or fibrosis in the His-Purkinje system, leading to conduction failure.","kind":"integration","linkedModuleIds":["heart-wall-cardiac-histology"],"origin":"ai"},{"id":"av-block~ai-7","moduleId":"av-block","stem":"What is the connection between atrial fibrillation and AV block?","options":[{"id":"a","text":"Both can cause cannon A waves"},{"id":"b","text":"Atrial fibrillation can lead to Mobitz I block"},{"id":"c","text":"AV block can result in irregular ventricular response in AF"},{"id":"d","text":"Both require the same treatment approach"}],"answerId":"c","explanation":"AV block can lead to an irregular ventricular response in patients with atrial fibrillation due to impaired conduction.","kind":"integration","linkedModuleIds":["atrial-fibrillation"],"origin":"ai"}],"ventricular-tachycardia":[{"id":"ventricular-tachycardia~ai-0","moduleId":"ventricular-tachycardia","stem":"What is the most common mechanism of monomorphic ventricular tachycardia?","options":[{"id":"a","text":"Re-entry around an MI scar"},{"id":"b","text":"Increased automaticity"},{"id":"c","text":"Triggered activity"},{"id":"d","text":"Electrolyte imbalance"}],"answerId":"a","explanation":"Monomorphic VT is most commonly due to re-entry circuits formed around myocardial infarction scars.","kind":"recall","origin":"ai"},{"id":"ventricular-tachycardia~ai-1","moduleId":"ventricular-tachycardia","stem":"A patient presents with a wide-complex tachycardia at a rate of 150 bpm. What is the first step in management?","options":[{"id":"a","text":"Administer adenosine"},{"id":"b","text":"Perform synchronized DC cardioversion"},{"id":"c","text":"Start intravenous amiodarone"},{"id":"d","text":"Observe and monitor"}],"answerId":"b","explanation":"In a regular wide-complex tachycardia, it should be treated as VT until proven otherwise, necessitating synchronized DC cardioversion if unstable.","kind":"clinical","origin":"ai"},{"id":"ventricular-tachycardia~ai-2","moduleId":"ventricular-tachycardia","stem":"Which clinical finding is most indicative of ventricular tachycardia over supraventricular tachycardia?","options":[{"id":"a","text":"Narrow QRS complex"},{"id":"b","text":"Cannon A waves"},{"id":"c","text":"Regular rhythm"},{"id":"d","text":"Palpitations"}],"answerId":"b","explanation":"Cannon A waves suggest independent atrial and ventricular activity, which is characteristic of VT.","kind":"recall","origin":"ai"},{"id":"ventricular-tachycardia~ai-3","moduleId":"ventricular-tachycardia","stem":"In Torsades de Pointes, which electrolyte abnormality is most commonly associated?","options":[{"id":"a","text":"Hyperkalemia"},{"id":"b","text":"Hypomagnesemia"},{"id":"c","text":"Hypercalcemia"},{"id":"d","text":"Hyponatremia"}],"answerId":"b","explanation":"Torsades de Pointes is often precipitated by hypomagnesemia, which can lead to prolonged QT interval.","kind":"recall","origin":"ai"},{"id":"ventricular-tachycardia~ai-4","moduleId":"ventricular-tachycardia","stem":"What is the appropriate first-line treatment for Torsades de Pointes?","options":[{"id":"a","text":"Amiodarone"},{"id":"b","text":"Magnesium sulfate"},{"id":"c","text":"Synchronized cardioversion"},{"id":"d","text":"Beta-blockers"}],"answerId":"b","explanation":"Magnesium sulfate is the first-line treatment for Torsades de Pointes, as it helps stabilize the cardiac membrane.","kind":"mechanism","origin":"ai"},{"id":"ventricular-tachycardia~ai-5","moduleId":"ventricular-tachycardia","stem":"A patient with a history of myocardial infarction presents with a wide-complex tachycardia. What is the most critical initial step?","options":[{"id":"a","text":"Administer verapamil"},{"id":"b","text":"Perform immediate defibrillation"},{"id":"c","text":"Obtain an ECG"},{"id":"d","text":"Assess hemodynamic stability"}],"answerId":"d","explanation":"Assessing hemodynamic stability is crucial before deciding on the treatment approach for wide-complex tachycardia.","kind":"trap","origin":"ai"},{"id":"ventricular-tachycardia~ai-6","moduleId":"ventricular-tachycardia","stem":"How does ventricular tachycardia differ from atrial fibrillation in terms of QRS morphology?","options":[{"id":"a","text":"Narrow QRS in VT"},{"id":"b","text":"Wide QRS in AF"},{"id":"c","text":"Monomorphic QRS in VT"},{"id":"d","text":"Irregular QRS in VT"}],"answerId":"c","explanation":"Ventricular tachycardia typically presents with a monomorphic wide QRS complex, while atrial fibrillation has narrow QRS complexes.","kind":"integration","linkedModuleIds":["atrial-fibrillation"],"origin":"ai"},{"id":"ventricular-tachycardia~ai-7","moduleId":"ventricular-tachycardia","stem":"What is a common characteristic of both ventricular tachycardia and ventricular fibrillation?","options":[{"id":"a","text":"Regular rhythm"},{"id":"b","text":"Narrow QRS complexes"},{"id":"c","text":"Rapid heart rate"},{"id":"d","text":"Presence of P waves"}],"answerId":"c","explanation":"Both ventricular tachycardia and ventricular fibrillation can present with a rapid heart rate, but they differ in rhythm regularity and QRS morphology.","kind":"integration","linkedModuleIds":["ventricular-fibrillation"],"origin":"ai"}],"atrial-fibrillation":[{"id":"atrial-fibrillation~ai-0","moduleId":"atrial-fibrillation","stem":"What is the most characteristic ECG finding in atrial fibrillation?","options":[{"id":"a","text":"Regular P waves"},{"id":"b","text":"Irregularly irregular rhythm"},{"id":"c","text":"Sawtooth F waves"},{"id":"d","text":"Narrow QRS complexes"}],"answerId":"b","explanation":"Atrial fibrillation is characterized by an irregularly irregular rhythm with no discrete P waves.","kind":"recall","origin":"ai"},{"id":"atrial-fibrillation~ai-1","moduleId":"atrial-fibrillation","stem":"Which mechanism primarily leads to the irregular ventricular response in atrial fibrillation?","options":[{"id":"a","text":"Increased vagal tone"},{"id":"b","text":"Disorganized atrial activation"},{"id":"c","text":"Enhanced sympathetic stimulation"},{"id":"d","text":"Conduction block in the AV node"}],"answerId":"b","explanation":"Disorganized atrial activation results in chaotic electrical impulses that lead to an irregular ventricular response.","kind":"mechanism","origin":"ai"},{"id":"atrial-fibrillation~ai-2","moduleId":"atrial-fibrillation","stem":"A patient presents with an irregularly irregular pulse and absent a-waves in the JVP. What is the most likely diagnosis?","options":[{"id":"a","text":"Atrial flutter"},{"id":"b","text":"Atrial fibrillation"},{"id":"c","text":"Ventricular tachycardia"},{"id":"d","text":"Supraventricular tachycardia"}],"answerId":"b","explanation":"The combination of an irregularly irregular pulse and absent a-waves is characteristic of atrial fibrillation.","kind":"clinical","origin":"ai"},{"id":"atrial-fibrillation~ai-3","moduleId":"atrial-fibrillation","stem":"In a patient with atrial fibrillation and Wolff-Parkinson-White syndrome, which treatment should be avoided?","options":[{"id":"a","text":"Procainamide"},{"id":"b","text":"Cardioversion"},{"id":"c","text":"Digoxin"},{"id":"d","text":"Amiodarone"}],"answerId":"c","explanation":"AV-nodal blockers like digoxin can lead to rapid conduction down the accessory pathway, increasing the risk of ventricular fibrillation.","kind":"trap","origin":"ai"},{"id":"atrial-fibrillation~ai-4","moduleId":"atrial-fibrillation","stem":"What is a potential consequence of untreated atrial fibrillation?","options":[{"id":"a","text":"Increased atrial contractility"},{"id":"b","text":"Decreased risk of stroke"},{"id":"c","text":"Tachycardia-induced cardiomyopathy"},{"id":"d","text":"Improved cardiac output"}],"answerId":"c","explanation":"Untreated atrial fibrillation can lead to tachycardia-induced cardiomyopathy due to persistent rapid heart rates.","kind":"recall","origin":"ai"},{"id":"atrial-fibrillation~ai-5","moduleId":"atrial-fibrillation","stem":"How does atrial fibrillation differ from atrial flutter in terms of ECG findings?","options":[{"id":"a","text":"Flutter shows irregularly irregular rhythm"},{"id":"b","text":"Flutter has organized sawtooth F waves"},{"id":"c","text":"AF has regular P waves"},{"id":"d","text":"AF shows narrow QRS complexes"}],"answerId":"b","explanation":"Atrial flutter is characterized by organized sawtooth F waves, while atrial fibrillation shows no organized atrial activity.","kind":"trap","origin":"ai"},{"id":"atrial-fibrillation~ai-6","moduleId":"atrial-fibrillation","stem":"Which of the following conditions is most likely to be exacerbated by atrial fibrillation?","options":[{"id":"a","text":"Hypotension"},{"id":"b","text":"Pulmonary embolism"},{"id":"c","text":"Heart failure"},{"id":"d","text":"Myocardial infarction"}],"answerId":"c","explanation":"Atrial fibrillation can lead to loss of atrial kick, worsening heart failure due to decreased cardiac output.","kind":"integration","linkedModuleIds":["ventricular-tachycardia"],"origin":"ai"},{"id":"atrial-fibrillation~ai-7","moduleId":"atrial-fibrillation","stem":"In patients with atrial fibrillation, which physiological change is most directly linked to the risk of embolic stroke?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Loss of atrial contraction"},{"id":"c","text":"Decreased ventricular filling"},{"id":"d","text":"Increased systemic vascular resistance"}],"answerId":"b","explanation":"The loss of coordinated atrial contraction can lead to thrombus formation in the left atrium, increasing the risk of embolic stroke.","kind":"integration","linkedModuleIds":["av-block"],"origin":"ai"}],"pda":[{"id":"pda~ai-0","moduleId":"pda","stem":"What is the primary mechanism of a patent ductus arteriosus (PDA)?","options":[{"id":"a","text":"Left-to-right shunt from aorta to pulmonary artery"},{"id":"b","text":"Right-to-left shunt from pulmonary artery to aorta"},{"id":"c","text":"Obstruction of blood flow in the aorta"},{"id":"d","text":"Increased systemic vascular resistance"}],"answerId":"a","explanation":"A PDA creates a left-to-right shunt, allowing blood to flow from the aorta into the pulmonary artery.","kind":"mechanism","origin":"ai"},{"id":"pda~ai-1","moduleId":"pda","stem":"Which physical exam finding is characteristic of a patent ductus arteriosus?","options":[{"id":"a","text":"Pansystolic murmur at the apex"},{"id":"b","text":"Continuous 'machinery' murmur at the left upper sternal border"},{"id":"c","text":"Diastolic murmur at the left infraclavicular area"},{"id":"d","text":"Systolic ejection murmur at the right sternal border"}],"answerId":"b","explanation":"A continuous 'machinery' murmur is a hallmark of PDA due to blood flow from the aorta to the pulmonary artery throughout the cardiac cycle.","kind":"recall","origin":"ai"},{"id":"pda~ai-2","moduleId":"pda","stem":"What pharmacological agent is used to close a patent ductus arteriosus?","options":[{"id":"a","text":"Prostaglandin E1"},{"id":"b","text":"Indomethacin"},{"id":"c","text":"Aspirin"},{"id":"d","text":"Furosemide"}],"answerId":"b","explanation":"Indomethacin is used to promote closure of the PDA by inhibiting prostaglandin synthesis.","kind":"recall","origin":"ai"},{"id":"pda~ai-3","moduleId":"pda","stem":"A neonate presents with a continuous murmur and bounding pulses. What is the most likely diagnosis?","options":[{"id":"a","text":"Atrial septal defect"},{"id":"b","text":"Ventricular septal defect"},{"id":"c","text":"Patent ductus arteriosus"},{"id":"d","text":"Coarctation of the aorta"}],"answerId":"c","explanation":"The continuous murmur and bounding pulses are classic signs of a patent ductus arteriosus.","kind":"clinical","origin":"ai"},{"id":"pda~ai-4","moduleId":"pda","stem":"Which of the following statements about patent ductus arteriosus is false?","options":[{"id":"a","text":"It can lead to pulmonary hypertension."},{"id":"b","text":"It is commonly found in preterm infants."},{"id":"c","text":"It presents with a pansystolic murmur."},{"id":"d","text":"Indomethacin can be used to close it."}],"answerId":"c","explanation":"A PDA presents with a continuous 'machinery' murmur, not a pansystolic murmur.","kind":"trap","origin":"ai"},{"id":"pda~ai-5","moduleId":"pda","stem":"How does a ventricular septal defect (VSD) differ from a patent ductus arteriosus (PDA) in terms of blood flow?","options":[{"id":"a","text":"VSD has a left-to-right shunt only in diastole"},{"id":"b","text":"PDA has a left-to-right shunt throughout the cardiac cycle"},{"id":"c","text":"VSD causes right-to-left shunting"},{"id":"d","text":"PDA leads to increased systemic vascular resistance"}],"answerId":"b","explanation":"A PDA allows continuous left-to-right shunting throughout both systole and diastole, unlike a VSD which may have varying flow depending on pressure differences.","kind":"integration","linkedModuleIds":["vsd"],"origin":"ai"},{"id":"pda~ai-6","moduleId":"pda","stem":"In a patient with a patent ductus arteriosus, which finding would you expect to be similar to that of an atrial septal defect (ASD)?","options":[{"id":"a","text":"Increased right ventricular pressure"},{"id":"b","text":"Wide pulse pressure"},{"id":"c","text":"Left-to-right shunt"},{"id":"d","text":"Cyanosis in early life"}],"answerId":"c","explanation":"Both PDA and ASD typically present with a left-to-right shunt, leading to increased pulmonary blood flow.","kind":"integration","linkedModuleIds":["asd"],"origin":"ai"}],"atrial-flutter":[{"id":"atrial-flutter~ai-0","moduleId":"atrial-flutter","stem":"What is the typical atrial rate in atrial flutter?","options":[{"id":"a","text":"150-250/min"},{"id":"b","text":"250-350/min"},{"id":"c","text":"350-450/min"},{"id":"d","text":"450-550/min"}],"answerId":"b","explanation":"Atrial flutter typically presents with an atrial rate of 250-350 beats per minute.","kind":"recall","origin":"ai"},{"id":"atrial-flutter~ai-1","moduleId":"atrial-flutter","stem":"Which ECG finding is characteristic of atrial flutter?","options":[{"id":"a","text":"Irregularly irregular rhythm"},{"id":"b","text":"Sawtooth flutter waves"},{"id":"c","text":"Wide QRS complexes"},{"id":"d","text":"Inverted P waves"}],"answerId":"b","explanation":"Atrial flutter is characterized by sawtooth flutter waves, often referred to as F-waves.","kind":"recall","origin":"ai"},{"id":"atrial-flutter~ai-2","moduleId":"atrial-flutter","stem":"What is the mechanism of atrial flutter?","options":[{"id":"a","text":"Reentrant circuit in the left atrium"},{"id":"b","text":"Macro-reentry in the right atrium"},{"id":"c","text":"Focal ectopic activity"},{"id":"d","text":"AV nodal reentry"}],"answerId":"b","explanation":"Atrial flutter is caused by macro-reentry in the right atrium, typically around the cavotricuspid isthmus.","kind":"mechanism","origin":"ai"},{"id":"atrial-flutter~ai-3","moduleId":"atrial-flutter","stem":"A patient presents with a regular tachycardia at a rate of 150/min. What should be considered before diagnosing sinus tachycardia?","options":[{"id":"a","text":"Atrial fibrillation"},{"id":"b","text":"Atrial flutter with 2:1 block"},{"id":"c","text":"Ventricular tachycardia"},{"id":"d","text":"Sinus bradycardia"}],"answerId":"b","explanation":"A regular tachycardia at ~150/min should prompt consideration of atrial flutter with 2:1 block, as it can mimic sinus tachycardia.","kind":"trap","origin":"ai"},{"id":"atrial-flutter~ai-4","moduleId":"atrial-flutter","stem":"What distinguishes atrial flutter from atrial fibrillation?","options":[{"id":"a","text":"Flutter is irregularly irregular"},{"id":"b","text":"Flutter has organized waves"},{"id":"c","text":"Flutter has no ventricular response"},{"id":"d","text":"Flutter is always rapid"}],"answerId":"b","explanation":"Atrial flutter is characterized by organized reentrant activity, resulting in regular flutter waves, unlike the chaotic rhythm of atrial fibrillation.","kind":"trap","origin":"ai"},{"id":"atrial-flutter~ai-5","moduleId":"atrial-flutter","stem":"In a patient with atrial flutter, what is the expected ventricular response if there is a 2:1 AV block?","options":[{"id":"a","text":"75/min"},{"id":"b","text":"150/min"},{"id":"c","text":"300/min"},{"id":"d","text":"450/min"}],"answerId":"b","explanation":"With a 2:1 AV block, the ventricular rate is typically half of the atrial rate, leading to a ventricular response of ~150/min.","kind":"clinical","origin":"ai"},{"id":"atrial-flutter~ai-6","moduleId":"atrial-flutter","stem":"How does atrial flutter relate to atrial fibrillation in terms of rhythm organization?","options":[{"id":"a","text":"Both are organized rhythms"},{"id":"b","text":"Flutter is organized, AF is chaotic"},{"id":"c","text":"Both are chaotic rhythms"},{"id":"d","text":"Flutter is irregular, AF is regular"}],"answerId":"b","explanation":"Atrial flutter is characterized by organized reentrant circuits, while atrial fibrillation is chaotic and irregular.","kind":"integration","linkedModuleIds":["atrial-fibrillation"],"origin":"ai"},{"id":"atrial-flutter~ai-7","moduleId":"atrial-flutter","stem":"Which treatment is effective for atrial flutter but not typically used for atrial fibrillation?","options":[{"id":"a","text":"Anticoagulation"},{"id":"b","text":"Rate control"},{"id":"c","text":"Low-energy cardioversion"},{"id":"d","text":"Adenosine"}],"answerId":"c","explanation":"Low-energy cardioversion is particularly effective for atrial flutter due to its organized nature, unlike the chaotic atrial fibrillation.","kind":"integration","linkedModuleIds":["atrial-fibrillation"],"origin":"ai"}],"bundle-branch-block":[{"id":"bundle-branch-block~ai-0","moduleId":"bundle-branch-block","stem":"What is the defining criterion for Bundle Branch Block (BBB)?","options":[{"id":"a","text":"QRS duration < 120 ms"},{"id":"b","text":"QRS duration ≥ 120 ms"},{"id":"c","text":"QRS duration = 100 ms"},{"id":"d","text":"QRS duration = 140 ms"}],"answerId":"b","explanation":"A QRS duration of ≥ 120 ms indicates delayed sequential activation characteristic of Bundle Branch Block.","kind":"recall","origin":"ai"},{"id":"bundle-branch-block~ai-1","moduleId":"bundle-branch-block","stem":"In a patient with right bundle branch block (RBBB), which of the following ECG findings is expected?","options":[{"id":"a","text":"Broad notched R in V6"},{"id":"b","text":"rSR′ pattern in V1"},{"id":"c","text":"Deep QS in V1"},{"id":"d","text":"Wide slurred S in V1"}],"answerId":"b","explanation":"The rSR′ pattern in V1 is characteristic of RBBB, indicating late right ventricular activation.","kind":"recall","origin":"ai"},{"id":"bundle-branch-block~ai-2","moduleId":"bundle-branch-block","stem":"What does a new left bundle branch block (LBBB) with ischemic symptoms indicate?","options":[{"id":"a","text":"Normal variant"},{"id":"b","text":"STEMI-equivalent"},{"id":"c","text":"Unrelated to ischemia"},{"id":"d","text":"Benign condition"}],"answerId":"b","explanation":"New LBBB with ischemic symptoms is considered a STEMI-equivalent and requires immediate evaluation.","kind":"clinical","origin":"ai"},{"id":"bundle-branch-block~ai-3","moduleId":"bundle-branch-block","stem":"Which of the following correctly describes the mechanism of Bundle Branch Block?","options":[{"id":"a","text":"Simultaneous activation of both ventricles"},{"id":"b","text":"Sequential activation of ventricles"},{"id":"c","text":"Increased heart rate"},{"id":"d","text":"Decreased conduction velocity"}],"answerId":"b","explanation":"Bundle Branch Block results in sequential activation of the ventricles due to blockage in one of the bundles.","kind":"mechanism","origin":"ai"},{"id":"bundle-branch-block~ai-4","moduleId":"bundle-branch-block","stem":"In which scenario would you apply the Sgarbossa criteria?","options":[{"id":"a","text":"Normal ECG findings"},{"id":"b","text":"New LBBB with chest pain"},{"id":"c","text":"RBBB with no symptoms"},{"id":"d","text":"LBBB without any symptoms"}],"answerId":"b","explanation":"The Sgarbossa criteria are used to assess for myocardial infarction in the presence of new LBBB with chest pain.","kind":"trap","origin":"ai"},{"id":"bundle-branch-block~ai-5","moduleId":"bundle-branch-block","stem":"Which finding is characteristic of left bundle branch block (LBBB)?","options":[{"id":"a","text":"rSR′ in V1"},{"id":"b","text":"Deep QS in V1"},{"id":"c","text":"Wide S in V6"},{"id":"d","text":"M-shaped QRS in V1"}],"answerId":"b","explanation":"LBBB typically presents with a deep QS in V1 and a broad notched R in V6, indicating late left ventricular activation.","kind":"recall","origin":"ai"},{"id":"bundle-branch-block~ai-6","moduleId":"bundle-branch-block","stem":"How does Bundle Branch Block relate to the cardiac conduction system?","options":[{"id":"a","text":"It indicates normal conduction"},{"id":"b","text":"It results from a block in the AV node"},{"id":"c","text":"It involves delayed activation of the ventricles"},{"id":"d","text":"It is unrelated to conduction pathways"}],"answerId":"c","explanation":"Bundle Branch Block results from a block in the conduction pathways, leading to delayed activation of the ventricles.","kind":"integration","linkedModuleIds":["pacemaker-conduction-system"],"origin":"ai"},{"id":"bundle-branch-block~ai-7","moduleId":"bundle-branch-block","stem":"What is the significance of recognizing STEMI localization in the context of LBBB?","options":[{"id":"a","text":"LBBB is always benign"},{"id":"b","text":"LBBB obscures MI criteria"},{"id":"c","text":"LBBB indicates a normal variant"},{"id":"d","text":"LBBB has no impact on STEMI localization"}],"answerId":"b","explanation":"LBBB can obscure traditional criteria for diagnosing myocardial infarction, making STEMI localization critical.","kind":"integration","linkedModuleIds":["stemi-localization"],"origin":"ai"}],"arteriosclerosis-patterns":[{"id":"arteriosclerosis-patterns~ai-0","moduleId":"arteriosclerosis-patterns","stem":"What is the primary pathological feature of hyaline arteriolosclerosis?","options":[{"id":"a","text":"Lipid accumulation in the intima"},{"id":"b","text":"Pink homogeneous wall thickening"},{"id":"c","text":"Onion-skin appearance"},{"id":"d","text":"Calcium deposits in the media"}],"answerId":"b","explanation":"Hyaline arteriolosclerosis is characterized by pink homogeneous wall thickening due to plasma protein leakage and smooth muscle cell proliferation.","kind":"recall","origin":"ai"},{"id":"arteriosclerosis-patterns~ai-1","moduleId":"arteriosclerosis-patterns","stem":"Which condition is most commonly associated with hyperplastic arteriolosclerosis?","options":[{"id":"a","text":"Benign hypertension"},{"id":"b","text":"Malignant hypertension"},{"id":"c","text":"Diabetes mellitus"},{"id":"d","text":"Aging"}],"answerId":"b","explanation":"Hyperplastic arteriolosclerosis is typically seen in cases of malignant hypertension, characterized by an 'onion-skin' appearance of the vessel walls.","kind":"recall","origin":"ai"},{"id":"arteriosclerosis-patterns~ai-2","moduleId":"arteriosclerosis-patterns","stem":"What is a key clinical finding associated with Mönckeberg medial calcific sclerosis?","options":[{"id":"a","text":"Severe limb ischemia"},{"id":"b","text":"Incidental arterial calcification on X-ray"},{"id":"c","text":"Fibrinoid necrosis"},{"id":"d","text":"Renal failure"}],"answerId":"b","explanation":"Mönckeberg medial calcific sclerosis is characterized by incidental calcification in the media of muscular arteries, which does not obstruct the lumen.","kind":"recall","origin":"ai"},{"id":"arteriosclerosis-patterns~ai-3","moduleId":"arteriosclerosis-patterns","stem":"Which mechanism underlies the damage seen in benign nephrosclerosis due to hyaline arteriolosclerosis?","options":[{"id":"a","text":"Increased vascular permeability"},{"id":"b","text":"Smooth muscle cell proliferation"},{"id":"c","text":"Lipid deposition"},{"id":"d","text":"Fibrin deposition"}],"answerId":"a","explanation":"Hyaline arteriolosclerosis leads to increased vascular permeability, resulting in plasma protein leakage and subsequent wall thickening.","kind":"mechanism","origin":"ai"},{"id":"arteriosclerosis-patterns~ai-4","moduleId":"arteriosclerosis-patterns","stem":"Which statement about Mönckeberg medial calcific sclerosis is true?","options":[{"id":"a","text":"It causes significant ischemia"},{"id":"b","text":"It is associated with malignant hypertension"},{"id":"c","text":"It is usually clinically insignificant"},{"id":"d","text":"It leads to renal failure"}],"answerId":"c","explanation":"Mönckeberg medial calcific sclerosis is typically clinically insignificant as it does not obstruct the lumen of the artery.","kind":"trap","origin":"ai"},{"id":"arteriosclerosis-patterns~ai-5","moduleId":"arteriosclerosis-patterns","stem":"How does hyperplastic arteriolosclerosis contribute to the risk of aortic dissection?","options":[{"id":"a","text":"By causing medial degeneration"},{"id":"b","text":"By leading to severe hypertension"},{"id":"c","text":"By promoting atherosclerosis"},{"id":"d","text":"By inducing thrombus formation"}],"answerId":"b","explanation":"Hyperplastic arteriolosclerosis is associated with severe hypertension, which increases the risk of complications such as aortic dissection.","kind":"integration","linkedModuleIds":["aortic-dissection"],"origin":"ai"},{"id":"arteriosclerosis-patterns~ai-6","moduleId":"arteriosclerosis-patterns","stem":"What is the relationship between hyaline arteriolosclerosis and aortic aneurysms?","options":[{"id":"a","text":"Hyaline arteriolosclerosis directly causes aneurysms"},{"id":"b","text":"It is a risk factor for aneurysm rupture"},{"id":"c","text":"It contributes to vascular remodeling"},{"id":"d","text":"It has no relation to aneurysms"}],"answerId":"c","explanation":"Hyaline arteriolosclerosis contributes to vascular remodeling, which can affect the stability of arterial walls and potentially lead to aneurysm formation.","kind":"integration","linkedModuleIds":["aortic-aneurysm"],"origin":"ai"}],"aortic-aneurysm":[{"id":"aortic-aneurysm~ai-0","moduleId":"aortic-aneurysm","stem":"What is the most common cause of abdominal aortic aneurysm (AAA)?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Atherosclerosis"},{"id":"c","text":"Marfan syndrome"},{"id":"d","text":"Bicuspid aortic valve"}],"answerId":"b","explanation":"Atherosclerosis is the primary cause of AAA, particularly in the infrarenal segment.","kind":"recall","origin":"ai"},{"id":"aortic-aneurysm~ai-1","moduleId":"aortic-aneurysm","stem":"Which of the following findings is characteristic of a ruptured abdominal aortic aneurysm?","options":[{"id":"a","text":"Pulsatile abdominal mass"},{"id":"b","text":"Sudden severe pain + hypotension"},{"id":"c","text":"Back pain"},{"id":"d","text":"Cough and hoarseness"}],"answerId":"b","explanation":"Rupture of an AAA typically presents with sudden severe abdominal pain and hypotension.","kind":"clinical","origin":"ai"},{"id":"aortic-aneurysm~ai-2","moduleId":"aortic-aneurysm","stem":"What is the primary pathological change seen in thoracic aortic aneurysms (TAA)?","options":[{"id":"a","text":"Atherosclerosis"},{"id":"b","text":"Cystic medial degeneration"},{"id":"c","text":"Fibromuscular dysplasia"},{"id":"d","text":"Calcification of the media"}],"answerId":"b","explanation":"Cystic medial degeneration characterized by elastic fiber fragmentation is the key pathological change in TAA.","kind":"mechanism","origin":"ai"},{"id":"aortic-aneurysm~ai-3","moduleId":"aortic-aneurysm","stem":"Which statement about aortic aneurysms is true?","options":[{"id":"a","text":"All aortic aneurysms are caused by atherosclerosis"},{"id":"b","text":"AAA is typically infrarenal"},{"id":"c","text":"TAA is primarily due to atherosclerosis"},{"id":"d","text":"AAA is associated with Marfan syndrome"}],"answerId":"b","explanation":"AAA is typically found in the infrarenal region and is most commonly caused by atherosclerosis.","kind":"trap","origin":"ai"},{"id":"aortic-aneurysm~ai-4","moduleId":"aortic-aneurysm","stem":"A patient presents with back pain and dyspnea. Which complication of TAA should be suspected?","options":[{"id":"a","text":"Rupture"},{"id":"b","text":"Dissection"},{"id":"c","text":"Embolism"},{"id":"d","text":"Branch obstruction"}],"answerId":"a","explanation":"Back pain and dyspnea in TAA may indicate rupture, which is a surgical emergency.","kind":"clinical","origin":"ai"},{"id":"aortic-aneurysm~ai-5","moduleId":"aortic-aneurysm","stem":"How does aortic dissection differ from aortic aneurysm in terms of presentation?","options":[{"id":"a","text":"Both present with a pulsatile mass"},{"id":"b","text":"Dissection typically presents with tearing chest pain"},{"id":"c","text":"Aneurysm presents with hypotension"},{"id":"d","text":"Dissection is always asymptomatic"}],"answerId":"b","explanation":"Aortic dissection typically presents with sudden, severe, tearing chest pain, distinguishing it from aneurysm presentations.","kind":"integration","linkedModuleIds":["aortic-dissection"],"origin":"ai"},{"id":"aortic-aneurysm~ai-6","moduleId":"aortic-aneurysm","stem":"Which of the following is a common risk factor for both aortic aneurysm and atherosclerosis?","options":[{"id":"a","text":"Marfan syndrome"},{"id":"b","text":"Hypertension"},{"id":"c","text":"Bicuspid aortic valve"},{"id":"d","text":"Diabetes mellitus"}],"answerId":"b","explanation":"Hypertension is a common risk factor that contributes to both aortic aneurysm formation and atherosclerosis.","kind":"integration","linkedModuleIds":["atherosclerosis"],"origin":"ai"}],"ihd-overview":[{"id":"ihd-overview~ai-0","moduleId":"ihd-overview","stem":"What is the primary cause of ischemic heart disease (IHD)?","options":[{"id":"a","text":"Coronary artery vasospasm"},{"id":"b","text":"Coronary atherosclerosis"},{"id":"c","text":"Myocardial hypertrophy"},{"id":"d","text":"Coronary embolism"}],"answerId":"b","explanation":"IHD is primarily caused by an imbalance between coronary supply and myocardial demand, with over 90% of cases attributed to coronary atherosclerosis.","kind":"recall","origin":"ai"},{"id":"ihd-overview~ai-1","moduleId":"ihd-overview","stem":"Which type of angina is characterized by pain at rest and not relieved by nitrates?","options":[{"id":"a","text":"Stable angina"},{"id":"b","text":"Unstable angina"},{"id":"c","text":"Prinzmetal angina"},{"id":"d","text":"Exertional angina"}],"answerId":"b","explanation":"Unstable angina is defined by rest pain that is not relieved, indicating acute plaque change and a higher risk for myocardial infarction.","kind":"recall","origin":"ai"},{"id":"ihd-overview~ai-2","moduleId":"ihd-overview","stem":"What mechanism underlies stable angina?","options":[{"id":"a","text":"Acute plaque rupture"},{"id":"b","text":"Coronary vasospasm"},{"id":"c","text":"Demand ischemia across a fixed stenosis"},{"id":"d","text":"Myocardial infarction"}],"answerId":"c","explanation":"Stable angina occurs due to demand ischemia when myocardial oxygen demand exceeds supply across a fixed stenosis.","kind":"mechanism","origin":"ai"},{"id":"ihd-overview~ai-3","moduleId":"ihd-overview","stem":"A patient presents with chest pain that occurs at rest and lasts longer than 20 minutes. What is the most likely diagnosis?","options":[{"id":"a","text":"Stable angina"},{"id":"b","text":"Unstable angina"},{"id":"c","text":"Prinzmetal angina"},{"id":"d","text":"Myocardial infarction"}],"answerId":"b","explanation":"The presentation of chest pain at rest lasting longer than 20 minutes is characteristic of unstable angina.","kind":"clinical","origin":"ai"},{"id":"ihd-overview~ai-4","moduleId":"ihd-overview","stem":"Which statement correctly differentiates stable from unstable angina?","options":[{"id":"a","text":"Stable angina is relieved by nitrates; unstable is not."},{"id":"b","text":"Unstable angina occurs only during exertion."},{"id":"c","text":"Stable angina presents with rest pain."},{"id":"d","text":"Unstable angina is always relieved by rest."}],"answerId":"a","explanation":"Stable angina is characterized by exertional pain relieved by rest or nitrates, while unstable angina presents with pain at rest.","kind":"trap","origin":"ai"},{"id":"ihd-overview~ai-5","moduleId":"ihd-overview","stem":"How does myocardial infarction (MI) relate to unstable angina?","options":[{"id":"a","text":"Both are caused by stable plaques."},{"id":"b","text":"Unstable angina can precede MI due to plaque instability."},{"id":"c","text":"MI is a type of stable angina."},{"id":"d","text":"Unstable angina is always followed by MI."}],"answerId":"b","explanation":"Unstable angina is caused by acute plaque changes and can precede myocardial infarction, indicating a higher risk for acute events.","kind":"integration","linkedModuleIds":["mi-complications"],"origin":"ai"},{"id":"ihd-overview~ai-6","moduleId":"ihd-overview","stem":"What is a common complication of myocardial infarction that can lead to unstable angina?","options":[{"id":"a","text":"Coronary vasospasm"},{"id":"b","text":"Acute plaque rupture"},{"id":"c","text":"Stable plaque formation"},{"id":"d","text":"Chronic heart failure"}],"answerId":"b","explanation":"Acute plaque rupture during or after a myocardial infarction can lead to unstable angina due to thrombus formation.","kind":"integration","linkedModuleIds":["myocardial-infarction-pathology"],"origin":"ai"}],"myocardial-infarction-pathology":[{"id":"myocardial-infarction-pathology~ai-0","moduleId":"myocardial-infarction-pathology","stem":"What is the most common cause of myocardial infarction?","options":[{"id":"a","text":"Coronary artery spasm"},{"id":"b","text":"Acute plaque change and thrombus occlusion"},{"id":"c","text":"Vasculitis"},{"id":"d","text":"Aortic dissection"}],"answerId":"b","explanation":"Acute plaque change and thrombus occlusion are the most common causes of myocardial infarction, leading to ischemia.","kind":"recall","origin":"ai"},{"id":"myocardial-infarction-pathology~ai-1","moduleId":"myocardial-infarction-pathology","stem":"Which type of myocardial infarction is characterized by full thickness necrosis?","options":[{"id":"a","text":"Subendocardial infarction"},{"id":"b","text":"Transmural infarction"},{"id":"c","text":"Silent myocardial infarction"},{"id":"d","text":"Recurrent myocardial infarction"}],"answerId":"b","explanation":"Transmural infarction occurs due to total occlusion of a coronary artery, leading to full thickness necrosis.","kind":"recall","origin":"ai"},{"id":"myocardial-infarction-pathology~ai-2","moduleId":"myocardial-infarction-pathology","stem":"In the first 3 days post-myocardial infarction, which inflammatory cells are primarily involved?","options":[{"id":"a","text":"Lymphocytes"},{"id":"b","text":"Neutrophils"},{"id":"c","text":"Macrophages"},{"id":"d","text":"Fibroblasts"}],"answerId":"b","explanation":"Neutrophils are the predominant inflammatory cells present in the first 1-3 days following myocardial infarction.","kind":"recall","origin":"ai"},{"id":"myocardial-infarction-pathology~ai-3","moduleId":"myocardial-infarction-pathology","stem":"A patient presents with chest pain, rapid weak pulse, and sweating. What is the underlying mechanism?","options":[{"id":"a","text":"Increased vagal tone"},{"id":"b","text":"Ischemia and sympathetic activation"},{"id":"c","text":"Decreased cardiac output"},{"id":"d","text":"Pulmonary congestion"}],"answerId":"b","explanation":"The symptoms are due to ischemia leading to sympathetic activation, causing chest pain and a rapid weak pulse.","kind":"clinical","origin":"ai"},{"id":"myocardial-infarction-pathology~ai-4","moduleId":"myocardial-infarction-pathology","stem":"Which statement about myocardial infarction is true?","options":[{"id":"a","text":"All MIs are full-thickness"},{"id":"b","text":"Subendocardial infarction occurs with total occlusion"},{"id":"c","text":"Transmural infarction is the only type that can be silent"},{"id":"d","text":"Partial occlusion leads to subendocardial infarction"}],"answerId":"d","explanation":"Partial occlusion or global hypoperfusion results in subendocardial infarction, while total occlusion leads to transmural infarction.","kind":"trap","origin":"ai"},{"id":"myocardial-infarction-pathology~ai-5","moduleId":"myocardial-infarction-pathology","stem":"How does myocardial infarction relate to necrosis patterns?","options":[{"id":"a","text":"All necrosis patterns are the same"},{"id":"b","text":"Myocardial infarction is a type of coagulative necrosis"},{"id":"c","text":"Necrosis patterns do not apply to myocardial infarction"},{"id":"d","text":"Only liquefactive necrosis is relevant"}],"answerId":"b","explanation":"Myocardial infarction typically results in coagulative necrosis, which is a key necrosis pattern.","kind":"integration","linkedModuleIds":["necrosis-patterns"],"origin":"ai"},{"id":"myocardial-infarction-pathology~ai-6","moduleId":"myocardial-infarction-pathology","stem":"What is a common complication of myocardial infarction that can lead to shock?","options":[{"id":"a","text":"Aortic dissection"},{"id":"b","text":"Cardiogenic shock"},{"id":"c","text":"Pulmonary embolism"},{"id":"d","text":"Pericarditis"}],"answerId":"b","explanation":"Cardiogenic shock is a common complication following myocardial infarction due to reduced cardiac output.","kind":"integration","linkedModuleIds":["infarction-shock"],"origin":"ai"}],"tetralogy-of-fallot":[{"id":"tetralogy-of-fallot~ai-0","moduleId":"tetralogy-of-fallot","stem":"What is the most common genetic association with Tetralogy of Fallot?","options":[{"id":"a","text":"Turner syndrome"},{"id":"b","text":"22q11.2 microdeletion"},{"id":"c","text":"Down syndrome"},{"id":"d","text":"Marfan syndrome"}],"answerId":"b","explanation":"Tetralogy of Fallot is most commonly associated with 22q11.2 microdeletion, also known as DiGeorge syndrome.","kind":"recall","origin":"ai"},{"id":"tetralogy-of-fallot~ai-1","moduleId":"tetralogy-of-fallot","stem":"Which of the following best explains the mechanism of cyanosis in Tetralogy of Fallot?","options":[{"id":"a","text":"Increased pulmonary blood flow"},{"id":"b","text":"Right-to-left shunt"},{"id":"c","text":"Left-to-right shunt"},{"id":"d","text":"Obstruction of the aorta"}],"answerId":"b","explanation":"Cyanosis in Tetralogy of Fallot occurs due to a right-to-left shunt across the VSD caused by RVOT obstruction.","kind":"mechanism","origin":"ai"},{"id":"tetralogy-of-fallot~ai-2","moduleId":"tetralogy-of-fallot","stem":"What clinical finding is most characteristic of Tetralogy of Fallot?","options":[{"id":"a","text":"Diastolic murmur at the apex"},{"id":"b","text":"Systolic ejection murmur at LUSB"},{"id":"c","text":"Continuous murmur at the left infraclavicular area"},{"id":"d","text":"Loud P2 on auscultation"}],"answerId":"b","explanation":"A systolic ejection murmur at the left upper sternal border is characteristic due to pulmonary stenosis.","kind":"clinical","origin":"ai"},{"id":"tetralogy-of-fallot~ai-3","moduleId":"tetralogy-of-fallot","stem":"In Tetralogy of Fallot, what does a softer or absent murmur during a tet spell indicate?","options":[{"id":"a","text":"Improved RVOT obstruction"},{"id":"b","text":"Worsened RVOT obstruction"},{"id":"c","text":"Increased pulmonary blood flow"},{"id":"d","text":"Decreased right-to-left shunting"}],"answerId":"b","explanation":"A softer or absent murmur during a tet spell indicates worsened RVOT obstruction, leading to less flow across the pulmonary outflow tract.","kind":"trap","origin":"ai"},{"id":"tetralogy-of-fallot~ai-4","moduleId":"tetralogy-of-fallot","stem":"Why is heart failure typically absent in patients with Tetralogy of Fallot?","options":[{"id":"a","text":"Increased systemic resistance"},{"id":"b","text":"Decreased pulmonary blood flow"},{"id":"c","text":"Increased left atrial pressure"},{"id":"d","text":"Right ventricular hypertrophy"}],"answerId":"b","explanation":"Heart failure is typically absent in Tetralogy of Fallot because RVOT obstruction limits pulmonary blood flow, preventing volume overload.","kind":"trap","origin":"ai"},{"id":"tetralogy-of-fallot~ai-5","moduleId":"tetralogy-of-fallot","stem":"How does Tetralogy of Fallot relate to Ventricular Septal Defect (VSD)?","options":[{"id":"a","text":"VSD is a separate condition with no relation"},{"id":"b","text":"VSD is a component of Tetralogy of Fallot"},{"id":"c","text":"VSD causes left-to-right shunt"},{"id":"d","text":"VSD is more common than TOF"}],"answerId":"b","explanation":"Ventricular Septal Defect is one of the four components of Tetralogy of Fallot.","kind":"integration","linkedModuleIds":["vsd"],"origin":"ai"},{"id":"tetralogy-of-fallot~ai-6","moduleId":"tetralogy-of-fallot","stem":"Which feature of Tetralogy of Fallot is also commonly seen in Atrial Septal Defect (ASD)?","options":[{"id":"a","text":"Cyanosis"},{"id":"b","text":"Right ventricular hypertrophy"},{"id":"c","text":"Increased pulmonary blood flow"},{"id":"d","text":"Presence of a shunt"}],"answerId":"d","explanation":"Both Tetralogy of Fallot and Atrial Septal Defect involve the presence of a shunt, although the direction and consequences differ.","kind":"integration","linkedModuleIds":["asd"],"origin":"ai"}],"antiarrhythmic-drugs":[{"id":"antiarrhythmic-drugs~ai-0","moduleId":"antiarrhythmic-drugs","stem":"Which class of antiarrhythmic drugs primarily works by blocking sodium channels?","options":[{"id":"a","text":"Class I"},{"id":"b","text":"Class II"},{"id":"c","text":"Class III"},{"id":"d","text":"Class IV"}],"answerId":"a","explanation":"Class I antiarrhythmics are sodium channel blockers, while Class II, III, and IV target beta receptors, potassium channels, and calcium channels respectively.","kind":"recall","origin":"ai"},{"id":"antiarrhythmic-drugs~ai-1","moduleId":"antiarrhythmic-drugs","stem":"What is a common side effect of procainamide?","options":[{"id":"a","text":"Pulmonary fibrosis"},{"id":"b","text":"Drug-induced lupus"},{"id":"c","text":"Cinchonism"},{"id":"d","text":"Bradycardia"}],"answerId":"b","explanation":"Procainamide can cause a drug-induced lupus erythematosus-like syndrome as a chronic toxicity.","kind":"recall","origin":"ai"},{"id":"antiarrhythmic-drugs~ai-2","moduleId":"antiarrhythmic-drugs","stem":"Which antiarrhythmic drug is contraindicated in patients with structural heart disease due to increased mortality risk?","options":[{"id":"a","text":"Amiodarone"},{"id":"b","text":"Flecainide"},{"id":"c","text":"Lidocaine"},{"id":"d","text":"Adenosine"}],"answerId":"b","explanation":"Flecainide is a Class IC antiarrhythmic that has been shown to increase mortality in patients with structural or ischemic heart disease.","kind":"trap","origin":"ai"},{"id":"antiarrhythmic-drugs~ai-3","moduleId":"antiarrhythmic-drugs","stem":"What is the mechanism of action of amiodarone?","options":[{"id":"a","text":"Sodium channel blockade"},{"id":"b","text":"Calcium channel blockade"},{"id":"c","text":"Potassium channel blockade"},{"id":"d","text":"Beta-adrenergic blockade"}],"answerId":"c","explanation":"Amiodarone primarily acts as a potassium channel blocker, prolonging the action potential and refractory period.","kind":"mechanism","origin":"ai"},{"id":"antiarrhythmic-drugs~ai-4","moduleId":"antiarrhythmic-drugs","stem":"Which of the following is the first-line treatment for acute AV nodal reentrant tachycardia (AVNRT)?","options":[{"id":"a","text":"Amiodarone"},{"id":"b","text":"Adenosine"},{"id":"c","text":"Lidocaine"},{"id":"d","text":"Procainamide"}],"answerId":"b","explanation":"Adenosine is the first-line treatment for acute AVNRT as it transiently blocks the AV node.","kind":"clinical","origin":"ai"},{"id":"antiarrhythmic-drugs~ai-5","moduleId":"antiarrhythmic-drugs","stem":"How do sodium channel blockers affect the action potential duration?","options":[{"id":"a","text":"Prolong it"},{"id":"b","text":"Shorten it"},{"id":"c","text":"No effect"},{"id":"d","text":"Depend on the class"}],"answerId":"a","explanation":"Sodium channel blockers can prolong the action potential duration, particularly Class IA agents.","kind":"mechanism","origin":"ai"},{"id":"antiarrhythmic-drugs~ai-6","moduleId":"antiarrhythmic-drugs","stem":"Which ion channel's gating mechanism is crucial for understanding the action of antiarrhythmic drugs?","options":[{"id":"a","text":"Potassium channels"},{"id":"b","text":"Sodium channels"},{"id":"c","text":"Calcium channels"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"Understanding the gating mechanisms of sodium, potassium, and calcium channels is essential for grasping how antiarrhythmic drugs function.","kind":"integration","linkedModuleIds":["ion-channels-structure-gating"],"origin":"ai"},{"id":"antiarrhythmic-drugs~ai-7","moduleId":"antiarrhythmic-drugs","stem":"What statistical concept is important when evaluating the safety of antiarrhythmic drugs in clinical trials?","options":[{"id":"a","text":"Confidence intervals"},{"id":"b","text":"Standard deviation"},{"id":"c","text":"Sample size"},{"id":"d","text":"Mean"}],"answerId":"a","explanation":"Confidence intervals are crucial for assessing the reliability of the estimated effects and safety of antiarrhythmic drugs in clinical studies.","kind":"integration","linkedModuleIds":["inferential-stats-p-value"],"origin":"ai"}],"atherosclerosis":[{"id":"atherosclerosis~ai-0","moduleId":"atherosclerosis","stem":"What is the primary mechanism driving atherosclerosis?","options":[{"id":"a","text":"Endothelial injury leading to LDL accumulation"},{"id":"b","text":"Increased blood viscosity"},{"id":"c","text":"Chronic inflammation of the vessel wall"},{"id":"d","text":"Vasospasm of coronary arteries"}],"answerId":"a","explanation":"Atherosclerosis primarily results from endothelial injury that leads to LDL accumulation and subsequent plaque formation.","kind":"mechanism","origin":"ai"},{"id":"atherosclerosis~ai-1","moduleId":"atherosclerosis","stem":"Which of the following is a characteristic of unstable (vulnerable) plaques?","options":[{"id":"a","text":"Thick fibrous cap"},{"id":"b","text":"Small lipid core"},{"id":"c","text":"Thin fibrous cap with large lipid core"},{"id":"d","text":"Stable luminal narrowing"}],"answerId":"c","explanation":"Unstable plaques are characterized by a thin fibrous cap and a large lipid core, making them prone to rupture.","kind":"recall","origin":"ai"},{"id":"atherosclerosis~ai-2","moduleId":"atherosclerosis","stem":"A 62-year-old male presents with chest pain and is found to have a non-critical stenosis in a coronary artery. What is the most likely cause of his acute coronary syndrome?","options":[{"id":"a","text":"Rupture of a thin-cap vulnerable plaque"},{"id":"b","text":"Severe stenosis of the artery"},{"id":"c","text":"Coronary vasospasm"},{"id":"d","text":"Myocardial ischemia due to anemia"}],"answerId":"a","explanation":"Acute coronary syndrome often arises from the rupture of a thin-cap vulnerable plaque, not necessarily from the degree of stenosis.","kind":"clinical","origin":"ai"},{"id":"atherosclerosis~ai-3","moduleId":"atherosclerosis","stem":"Which of the following findings is most indicative of significant atherosclerotic disease?","options":[{"id":"a","text":"Diminished peripheral pulses"},{"id":"b","text":"Normal blood pressure"},{"id":"c","text":"Absence of arterial bruits"},{"id":"d","text":"Normal cholesterol levels"}],"answerId":"a","explanation":"Diminished peripheral pulses suggest flow-limiting plaque due to significant atherosclerotic disease.","kind":"recall","origin":"ai"},{"id":"atherosclerosis~ai-4","moduleId":"atherosclerosis","stem":"Which of the following is a major modifiable risk factor for atherosclerosis?","options":[{"id":"a","text":"Age"},{"id":"b","text":"Family history"},{"id":"c","text":"Hypertension"},{"id":"d","text":"Male gender"}],"answerId":"c","explanation":"Hypertension is a major modifiable risk factor for the development of atherosclerosis.","kind":"recall","origin":"ai"},{"id":"atherosclerosis~ai-5","moduleId":"atherosclerosis","stem":"How does LDL contribute to the development of atherosclerosis?","options":[{"id":"a","text":"Increases blood viscosity"},{"id":"b","text":"Promotes endothelial repair"},{"id":"c","text":"Accumulates in the arterial wall"},{"id":"d","text":"Enhances vasodilation"}],"answerId":"c","explanation":"LDL accumulates in the arterial wall after endothelial injury, leading to plaque formation.","kind":"mechanism","origin":"ai"},{"id":"atherosclerosis~ai-6","moduleId":"atherosclerosis","stem":"How does atherosclerosis relate to the development of aortic aneurysms?","options":[{"id":"a","text":"Atherosclerosis weakens the arterial wall leading to aneurysm formation"},{"id":"b","text":"Aneurysms cause atherosclerosis"},{"id":"c","text":"Both are unrelated conditions"},{"id":"d","text":"Atherosclerosis only affects peripheral arteries"}],"answerId":"a","explanation":"Atherosclerosis weakens the arterial wall, which can lead to the formation of aortic aneurysms.","kind":"integration","linkedModuleIds":["aortic-aneurysm"],"origin":"ai"},{"id":"atherosclerosis~ai-7","moduleId":"atherosclerosis","stem":"What role do lipoproteins play in atherogenesis?","options":[{"id":"a","text":"They promote vasodilation"},{"id":"b","text":"They transport cholesterol to arterial walls"},{"id":"c","text":"They enhance endothelial repair"},{"id":"d","text":"They reduce inflammation in arteries"}],"answerId":"b","explanation":"Lipoproteins, particularly LDL, transport cholesterol to arterial walls, contributing to atherogenesis.","kind":"integration","linkedModuleIds":["lipoproteins-atherogenesis"],"origin":"ai"}],"aortic-dissection":[{"id":"aortic-dissection~ai-0","moduleId":"aortic-dissection","stem":"What is the most common etiology of aortic dissection?","options":[{"id":"a","text":"Connective tissue disorders"},{"id":"b","text":"Hypertension"},{"id":"c","text":"Atherosclerosis"},{"id":"d","text":"Trauma"}],"answerId":"b","explanation":"Hypertension accounts for over 90% of cases of aortic dissection, particularly in men aged 40-60.","kind":"recall","origin":"ai"},{"id":"aortic-dissection~ai-1","moduleId":"aortic-dissection","stem":"Which physical exam finding is most indicative of ascending aortic dissection?","options":[{"id":"a","text":"Inter-arm blood pressure differential"},{"id":"b","text":"Early diastolic murmur"},{"id":"c","text":"Tachycardia"},{"id":"d","text":"Hypotension"}],"answerId":"b","explanation":"An early diastolic murmur indicates acute aortic regurgitation due to ascending aortic involvement.","kind":"recall","origin":"ai"},{"id":"aortic-dissection~ai-2","moduleId":"aortic-dissection","stem":"What mechanism leads to the formation of a false lumen in aortic dissection?","options":[{"id":"a","text":"Rupture of the vasa vasorum"},{"id":"b","text":"Intimal tear"},{"id":"c","text":"Atherosclerotic plaque rupture"},{"id":"d","text":"Increased blood pressure"}],"answerId":"b","explanation":"An intimal tear allows blood to enter the media, creating a false lumen.","kind":"mechanism","origin":"ai"},{"id":"aortic-dissection~ai-3","moduleId":"aortic-dissection","stem":"A patient presents with sudden, severe chest pain radiating to the back. What is the most likely diagnosis?","options":[{"id":"a","text":"Myocardial infarction"},{"id":"b","text":"Pulmonary embolism"},{"id":"c","text":"Aortic dissection"},{"id":"d","text":"Pneumothorax"}],"answerId":"c","explanation":"The classic presentation of aortic dissection includes sudden, severe tearing chest pain that often radiates to the back.","kind":"clinical","origin":"ai"},{"id":"aortic-dissection~ai-4","moduleId":"aortic-dissection","stem":"In a case of aortic dissection, what finding would suggest rupture into the pericardium?","options":[{"id":"a","text":"Inter-arm BP differential"},{"id":"b","text":"Beck's triad"},{"id":"c","text":"Early diastolic murmur"},{"id":"d","text":"Tachycardia"}],"answerId":"b","explanation":"Beck's triad (hypotension, muffled heart sounds, and jugular venous distension) indicates cardiac tamponade due to rupture.","kind":"clinical","origin":"ai"},{"id":"aortic-dissection~ai-5","moduleId":"aortic-dissection","stem":"Which of the following is a trap in diagnosing aortic dissection?","options":[{"id":"a","text":"Early diastolic murmur"},{"id":"b","text":"Tachycardia"},{"id":"c","text":"Inter-arm BP differential"},{"id":"d","text":"Hypotension"}],"answerId":"b","explanation":"Tachycardia is a non-specific response and does not localize the dissection, unlike the early diastolic murmur.","kind":"trap","origin":"ai"},{"id":"aortic-dissection~ai-6","moduleId":"aortic-dissection","stem":"How does aortic dissection relate to aortic aneurysm?","options":[{"id":"a","text":"Both are caused by trauma"},{"id":"b","text":"Both involve the aortic wall"},{"id":"c","text":"Both present with similar chest pain"},{"id":"d","text":"Both require surgical intervention"}],"answerId":"b","explanation":"Aortic dissection and aneurysm both involve structural changes in the aortic wall, though their mechanisms and management differ.","kind":"integration","linkedModuleIds":["aortic-aneurysm"],"origin":"ai"},{"id":"aortic-dissection~ai-7","moduleId":"aortic-dissection","stem":"What heart sound is associated with aortic regurgitation due to aortic dissection?","options":[{"id":"a","text":"S1"},{"id":"b","text":"S2"},{"id":"c","text":"Early diastolic murmur"},{"id":"d","text":"S3 gallop"}],"answerId":"c","explanation":"An early diastolic murmur indicates aortic regurgitation, which can occur with ascending aortic dissection.","kind":"integration","linkedModuleIds":["heart-sounds-murmurs-auscultation"],"origin":"ai"}],"mi-complications":[{"id":"mi-complications~ai-0","moduleId":"mi-complications","stem":"What is the most common cause of early death following a myocardial infarction?","options":[{"id":"a","text":"Cardiogenic shock"},{"id":"b","text":"Ventricular fibrillation"},{"id":"c","text":"Free wall rupture"},{"id":"d","text":"Acute pericarditis"}],"answerId":"b","explanation":"Ventricular fibrillation is the most common arrhythmia leading to early death post-MI, occurring shortly after the event.","kind":"recall","origin":"ai"},{"id":"mi-complications~ai-1","moduleId":"mi-complications","stem":"Which complication of myocardial infarction typically occurs 2-3 days post-event?","options":[{"id":"a","text":"Acute mitral regurgitation"},{"id":"b","text":"Fibrinous pericarditis"},{"id":"c","text":"Ventricular septal rupture"},{"id":"d","text":"Ventricular aneurysm"}],"answerId":"b","explanation":"Fibrinous pericarditis is a common complication that arises 2-3 days after myocardial infarction.","kind":"recall","origin":"ai"},{"id":"mi-complications~ai-2","moduleId":"mi-complications","stem":"A patient presents with hypotension, elevated JVP, and muffled heart sounds 5 days after an MI. What is the likely diagnosis?","options":[{"id":"a","text":"Acute mitral regurgitation"},{"id":"b","text":"Ventricular aneurysm"},{"id":"c","text":"Cardiac tamponade"},{"id":"d","text":"Dressler's syndrome"}],"answerId":"c","explanation":"The combination of hypotension, elevated JVP, and muffled heart sounds suggests cardiac tamponade due to free wall rupture.","kind":"clinical","origin":"ai"},{"id":"mi-complications~ai-3","moduleId":"mi-complications","stem":"What mechanism primarily leads to papillary muscle rupture after myocardial infarction?","options":[{"id":"a","text":"Ischemic necrosis"},{"id":"b","text":"Increased myocardial oxygen demand"},{"id":"c","text":"Inflammatory response"},{"id":"d","text":"Mechanical stress from ventricular dilation"}],"answerId":"a","explanation":"Ischemic necrosis of the muscle leads to papillary muscle rupture, resulting in acute mitral regurgitation.","kind":"mechanism","origin":"ai"},{"id":"mi-complications~ai-4","moduleId":"mi-complications","stem":"A new holosystolic murmur is heard in a patient 6 days post-MI. What is the most likely cause?","options":[{"id":"a","text":"Recurrent ischemia"},{"id":"b","text":"Ventricular aneurysm"},{"id":"c","text":"Papillary muscle rupture"},{"id":"d","text":"Dressler's syndrome"}],"answerId":"c","explanation":"A new holosystolic murmur at this time indicates papillary muscle rupture, a mechanical complication of MI.","kind":"trap","origin":"ai"},{"id":"mi-complications~ai-5","moduleId":"mi-complications","stem":"Which finding is characteristic of a ventricular aneurysm weeks after a myocardial infarction?","options":[{"id":"a","text":"New holosystolic murmur"},{"id":"b","text":"Persistent ST elevation with dyskinetic segment"},{"id":"c","text":"Pericardial friction rub"},{"id":"d","text":"Hypotension and elevated JVP"}],"answerId":"b","explanation":"Persistent ST elevation with a dyskinetic segment is indicative of a ventricular aneurysm developing after an MI.","kind":"recall","origin":"ai"},{"id":"mi-complications~ai-6","moduleId":"mi-complications","stem":"How does the timing of myocardial infarction complications relate to the healing process?","options":[{"id":"a","text":"Complications are random"},{"id":"b","text":"Complications occur uniformly over time"},{"id":"c","text":"Complications are time-dependent based on healing phases"},{"id":"d","text":"Complications are only related to initial ischemia"}],"answerId":"c","explanation":"Complications of myocardial infarction are time-dependent and correlate with the phases of healing, particularly the macrophage phase.","kind":"integration","linkedModuleIds":["myocardial-infarction-pathology"],"origin":"ai"},{"id":"mi-complications~ai-7","moduleId":"mi-complications","stem":"In a patient with cardiogenic shock due to myocardial infarction, which complication is most likely if the infarct involves ≥40% of the left ventricle?","options":[{"id":"a","text":"Acute pericarditis"},{"id":"b","text":"Ventricular septal rupture"},{"id":"c","text":"Dressler's syndrome"},{"id":"d","text":"Papillary muscle rupture"}],"answerId":"b","explanation":"Infarcts involving ≥40% of the left ventricle can lead to cardiogenic shock and are associated with mechanical complications like ventricular septal rupture.","kind":"integration","linkedModuleIds":["infarction-shock"],"origin":"ai"}],"anticoagulants":[{"id":"anticoagulants~ai-0","moduleId":"anticoagulants","stem":"What is the primary mechanism of action of heparin?","options":[{"id":"a","text":"Inhibits vitamin K-dependent factors"},{"id":"b","text":"Activates antithrombin III"},{"id":"c","text":"Inhibits platelet aggregation"},{"id":"d","text":"Directly inhibits thrombin"}],"answerId":"b","explanation":"Heparin primarily activates antithrombin III, leading to the inactivation of thrombin and factor Xa.","kind":"mechanism","origin":"ai"},{"id":"anticoagulants~ai-1","moduleId":"anticoagulants","stem":"Which laboratory test is used to monitor heparin therapy?","options":[{"id":"a","text":"INR"},{"id":"b","text":"PT"},{"id":"c","text":"aPTT"},{"id":"d","text":"CBC"}],"answerId":"c","explanation":"Heparin therapy is monitored using the activated partial thromboplastin time (aPTT).","kind":"recall","origin":"ai"},{"id":"anticoagulants~ai-2","moduleId":"anticoagulants","stem":"A patient on warfarin presents with skin necrosis. What is the likely mechanism?","options":[{"id":"a","text":"Increased thrombin activity"},{"id":"b","text":"Transient protein C depletion"},{"id":"c","text":"Vitamin K overdose"},{"id":"d","text":"Heparin-induced thrombocytopenia"}],"answerId":"b","explanation":"Warfarin skin necrosis occurs due to transient depletion of protein C, leading to a pro-coagulation state.","kind":"mechanism","origin":"ai"},{"id":"anticoagulants~ai-3","moduleId":"anticoagulants","stem":"Which of the following is a risk associated with unfractionated heparin (UFH)?","options":[{"id":"a","text":"Fetal warfarin syndrome"},{"id":"b","text":"Thrombocytopenia with paradoxical thrombosis"},{"id":"c","text":"Skin necrosis"},{"id":"d","text":"Gastrointestinal bleeding"}],"answerId":"b","explanation":"Unfractionated heparin can cause heparin-induced thrombocytopenia (HIT), characterized by thrombocytopenia and paradoxical thrombosis.","kind":"recall","origin":"ai"},{"id":"anticoagulants~ai-4","moduleId":"anticoagulants","stem":"In which situation should warfarin be preferred over DOACs?","options":[{"id":"a","text":"Non-valvular atrial fibrillation"},{"id":"b","text":"Mechanical heart valve"},{"id":"c","text":"Pulmonary embolism"},{"id":"d","text":"Deep vein thrombosis"}],"answerId":"b","explanation":"Warfarin is preferred in patients with mechanical heart valves due to the contraindication of DOACs in this setting.","kind":"trap","origin":"ai"},{"id":"anticoagulants~ai-5","moduleId":"anticoagulants","stem":"A patient with a history of venous thromboembolism is started on rivaroxaban. What is a key advantage of this medication?","options":[{"id":"a","text":"Requires frequent INR monitoring"},{"id":"b","text":"Fixed dosing without routine monitoring"},{"id":"c","text":"Reversal with protamine"},{"id":"d","text":"Lower risk of bleeding compared to warfarin"}],"answerId":"b","explanation":"Rivaroxaban is an oral anticoagulant that allows for fixed dosing without the need for routine monitoring.","kind":"recall","origin":"ai"},{"id":"anticoagulants~ai-6","moduleId":"anticoagulants","stem":"How does the mechanism of action of antiplatelet drugs differ from anticoagulants?","options":[{"id":"a","text":"Antiplatelets inhibit thrombin"},{"id":"b","text":"Anticoagulants inhibit platelet aggregation"},{"id":"c","text":"Antiplatelets block vitamin K"},{"id":"d","text":"Anticoagulants act on the coagulation cascade"}],"answerId":"d","explanation":"Anticoagulants target the coagulation cascade, while antiplatelet drugs primarily inhibit platelet aggregation.","kind":"integration","linkedModuleIds":["antiplatelets"],"origin":"ai"},{"id":"anticoagulants~ai-7","moduleId":"anticoagulants","stem":"Which anticoagulant is contraindicated in patients with significant mitral stenosis?","options":[{"id":"a","text":"Dabigatran"},{"id":"b","text":"Apixaban"},{"id":"c","text":"Warfarin"},{"id":"d","text":"Enoxaparin"}],"answerId":"c","explanation":"Warfarin is required in patients with significant mitral stenosis, as DOACs are contraindicated in this condition.","kind":"integration","linkedModuleIds":["hemostasis-thrombosis-embolism"],"origin":"ai"}],"fibrinolytics":[{"id":"fibrinolytics~ai-0","moduleId":"fibrinolytics","stem":"What is the primary mechanism of action of fibrinolytics?","options":[{"id":"a","text":"Activate thrombin to convert fibrinogen to fibrin"},{"id":"b","text":"Activate plasminogen to plasmin, leading to fibrin lysis"},{"id":"c","text":"Inhibit platelet aggregation"},{"id":"d","text":"Inhibit factor Xa"}],"answerId":"b","explanation":"Fibrinolytics convert plasminogen to plasmin, which then lyses fibrin, facilitating clot breakdown.","kind":"mechanism","origin":"ai"},{"id":"fibrinolytics~ai-1","moduleId":"fibrinolytics","stem":"Which of the following is a major risk associated with the use of fibrinolytics?","options":[{"id":"a","text":"Thrombosis"},{"id":"b","text":"Hypertension"},{"id":"c","text":"Bleeding, including intracranial hemorrhage"},{"id":"d","text":"Arrhythmias"}],"answerId":"c","explanation":"The main risk of fibrinolytics is bleeding, particularly intracranial hemorrhage due to systemic fibrinolysis.","kind":"trap","origin":"ai"},{"id":"fibrinolytics~ai-2","moduleId":"fibrinolytics","stem":"In which scenario is the use of fibrinolytics indicated for STEMI?","options":[{"id":"a","text":"Symptoms lasting more than 12 hours"},{"id":"b","text":"Primary PCI achievable within 120 minutes"},{"id":"c","text":"Symptoms less than 12 hours with delayed PCI"},{"id":"d","text":"Patient with contraindications to anticoagulants"}],"answerId":"c","explanation":"Fibrinolytics are indicated if symptoms are less than 12 hours and primary PCI is not timely.","kind":"recall","origin":"ai"},{"id":"fibrinolytics~ai-3","moduleId":"fibrinolytics","stem":"Streptokinase is known to be non-fibrin-specific. What is a consequence of this characteristic?","options":[{"id":"a","text":"Increased risk of systemic fibrinolysis and bleeding"},{"id":"b","text":"Decreased efficacy in clot lysis"},{"id":"c","text":"Higher specificity for coronary clots"},{"id":"d","text":"Reduced antigenicity compared to tPA"}],"answerId":"a","explanation":"Streptokinase's non-fibrin-specific nature leads to systemic fibrinolysis, increasing the risk of bleeding.","kind":"mechanism","origin":"ai"},{"id":"fibrinolytics~ai-4","moduleId":"fibrinolytics","stem":"What is the preferred reperfusion strategy for STEMI if achievable within 120 minutes?","options":[{"id":"a","text":"Fibrinolytics"},{"id":"b","text":"Coronary artery bypass grafting"},{"id":"c","text":"Primary PCI"},{"id":"d","text":"Anticoagulants"}],"answerId":"c","explanation":"Primary PCI is preferred for reperfusion in STEMI if it can be performed within 120 minutes.","kind":"trap","origin":"ai"},{"id":"fibrinolytics~ai-5","moduleId":"fibrinolytics","stem":"How does the mechanism of action of tPA differ from that of streptokinase?","options":[{"id":"a","text":"tPA is fibrin-specific, while streptokinase is not"},{"id":"b","text":"tPA activates factor Xa, while streptokinase activates thrombin"},{"id":"c","text":"tPA is an anticoagulant, while streptokinase is a pro-coagulant"},{"id":"d","text":"tPA is used for venous thromboembolism, while streptokinase is not"}],"answerId":"a","explanation":"tPA acts specifically on the plasminogen-fibrin complex, while streptokinase is non-fibrin-specific.","kind":"mechanism","origin":"ai"},{"id":"fibrinolytics~ai-6","moduleId":"fibrinolytics","stem":"Which anticoagulant mechanism is most relevant when considering the use of fibrinolytics in STEMI?","options":[{"id":"a","text":"Inhibition of thrombin"},{"id":"b","text":"Inhibition of factor Xa"},{"id":"c","text":"Activation of plasminogen"},{"id":"d","text":"Inhibition of platelet aggregation"}],"answerId":"c","explanation":"Activation of plasminogen to plasmin is crucial for the action of fibrinolytics, linking to the anticoagulant module's focus on thrombus resolution.","kind":"integration","linkedModuleIds":["anticoagulants"],"origin":"ai"},{"id":"fibrinolytics~ai-7","moduleId":"fibrinolytics","stem":"What is the role of antiplatelet drugs in conjunction with fibrinolytics for STEMI management?","options":[{"id":"a","text":"They enhance the effect of fibrinolytics"},{"id":"b","text":"They are contraindicated"},{"id":"c","text":"They prevent re-thrombosis after fibrinolysis"},{"id":"d","text":"They replace the need for fibrinolytics"}],"answerId":"c","explanation":"Antiplatelet drugs are used to prevent re-thrombosis after fibrinolysis, complementing the action of fibrinolytics.","kind":"integration","linkedModuleIds":["antiplatelets"],"origin":"ai"}],"antiplatelets":[{"id":"antiplatelets~ai-0","moduleId":"antiplatelets","stem":"What is the primary mechanism of action of aspirin as an antiplatelet agent?","options":[{"id":"a","text":"Inhibition of thromboxane A₂ synthesis"},{"id":"b","text":"Inhibition of phosphodiesterase"},{"id":"c","text":"Inhibition of platelet glycoprotein IIb/IIIa"},{"id":"d","text":"Inhibition of ADP receptors"}],"answerId":"a","explanation":"Aspirin irreversibly acetylates COX-1, leading to decreased thromboxane A₂ production, which is crucial for platelet aggregation.","kind":"mechanism","origin":"ai"},{"id":"antiplatelets~ai-1","moduleId":"antiplatelets","stem":"Which of the following is a reversible P2Y12 inhibitor?","options":[{"id":"a","text":"Clopidogrel"},{"id":"b","text":"Prasugrel"},{"id":"c","text":"Ticagrelor"},{"id":"d","text":"Aspirin"}],"answerId":"c","explanation":"Ticagrelor is a reversible allosteric inhibitor of the P2Y12 receptor, unlike clopidogrel and prasugrel which are irreversible.","kind":"recall","origin":"ai"},{"id":"antiplatelets~ai-2","moduleId":"antiplatelets","stem":"A patient on aspirin presents with gastrointestinal bleeding. What is the most likely mechanism?","options":[{"id":"a","text":"Inhibition of platelet aggregation"},{"id":"b","text":"Inhibition of protective COX-1"},{"id":"c","text":"Inhibition of thrombin"},{"id":"d","text":"Inhibition of fibrinogen"}],"answerId":"b","explanation":"Aspirin inhibits COX-1, which reduces the production of protective prostaglandins in the gastric mucosa, leading to ulceration and bleeding.","kind":"clinical","origin":"ai"},{"id":"antiplatelets~ai-3","moduleId":"antiplatelets","stem":"Which antiplatelet drug requires metabolic activation by CYP2C19?","options":[{"id":"a","text":"Aspirin"},{"id":"b","text":"Ticagrelor"},{"id":"c","text":"Clopidogrel"},{"id":"d","text":"Abciximab"}],"answerId":"c","explanation":"Clopidogrel is a prodrug that requires activation by CYP2C19 to exert its antiplatelet effects.","kind":"recall","origin":"ai"},{"id":"antiplatelets~ai-4","moduleId":"antiplatelets","stem":"Which of the following statements about antiplatelet drugs is true?","options":[{"id":"a","text":"All antiplatelet drugs are reversible"},{"id":"b","text":"Aspirin irreversibly inhibits COX-1"},{"id":"c","text":"Ticagrelor is a prodrug"},{"id":"d","text":"Clopidogrel is a reversible inhibitor"}],"answerId":"b","explanation":"Aspirin irreversibly acetylates COX-1, leading to long-lasting effects on platelet function.","kind":"trap","origin":"ai"},{"id":"antiplatelets~ai-5","moduleId":"antiplatelets","stem":"How does the mechanism of action of ticagrelor differ from that of clopidogrel?","options":[{"id":"a","text":"Ticagrelor is irreversible, clopidogrel is reversible"},{"id":"b","text":"Ticagrelor is a prodrug, clopidogrel is not"},{"id":"c","text":"Ticagrelor is reversible, clopidogrel is irreversible"},{"id":"d","text":"Both are irreversible inhibitors"}],"answerId":"c","explanation":"Ticagrelor is a reversible P2Y12 inhibitor, while clopidogrel irreversibly blocks the same receptor.","kind":"mechanism","origin":"ai"},{"id":"antiplatelets~ai-6","moduleId":"antiplatelets","stem":"A patient with a history of myocardial infarction is prescribed ticagrelor. Which side effect should the clinician monitor for?","options":[{"id":"a","text":"Gastrointestinal bleeding"},{"id":"b","text":"Dyspnea"},{"id":"c","text":"Thrombocytopenia"},{"id":"d","text":"Rash"}],"answerId":"b","explanation":"Dyspnea is a known side effect of ticagrelor due to its mechanism of action.","kind":"clinical","origin":"ai"},{"id":"antiplatelets~ai-7","moduleId":"antiplatelets","stem":"How do antiplatelet drugs relate to the process of hemostasis?","options":[{"id":"a","text":"They enhance platelet aggregation"},{"id":"b","text":"They inhibit fibrinolysis"},{"id":"c","text":"They prevent arterial thrombus formation"},{"id":"d","text":"They promote clotting factor activation"}],"answerId":"c","explanation":"Antiplatelet drugs prevent arterial thrombus formation by inhibiting platelet activation and aggregation, which is essential in hemostasis.","kind":"integration","linkedModuleIds":["hemostasis-thrombosis-embolism"],"origin":"ai"},{"id":"antiplatelets~ai-8","moduleId":"antiplatelets","stem":"In the context of treating thromboembolic events, how do antiplatelet drugs differ from anticoagulants?","options":[{"id":"a","text":"Both inhibit platelet aggregation"},{"id":"b","text":"Antiplatelets act on the coagulation cascade"},{"id":"c","text":"Anticoagulants prevent fibrin formation, while antiplatelets inhibit platelet function"},{"id":"d","text":"Both are irreversible"}],"answerId":"c","explanation":"Anticoagulants prevent fibrin formation in the coagulation cascade, while antiplatelet drugs specifically inhibit platelet function.","kind":"integration","linkedModuleIds":["anticoagulants"],"origin":"ai"}],"infective-endocarditis":[{"id":"infective-endocarditis~ai-0","moduleId":"infective-endocarditis","stem":"What is the most common organism causing acute infective endocarditis in a patient with normal heart valves?","options":[{"id":"a","text":"Streptococcus viridans"},{"id":"b","text":"Enterococcus faecalis"},{"id":"c","text":"Staphylococcus aureus"},{"id":"d","text":"HACEK organisms"}],"answerId":"c","explanation":"Staphylococcus aureus is the most common cause of acute infective endocarditis, particularly in patients with normal heart valves.","kind":"recall","origin":"ai"},{"id":"infective-endocarditis~ai-1","moduleId":"infective-endocarditis","stem":"Which clinical finding is characteristic of immune complex deposition in infective endocarditis?","options":[{"id":"a","text":"Janeway lesions"},{"id":"b","text":"Osler nodes"},{"id":"c","text":"Splinter hemorrhages"},{"id":"d","text":"Roth spots"}],"answerId":"b","explanation":"Osler nodes are painful lesions associated with immune complex deposition in infective endocarditis.","kind":"clinical","origin":"ai"},{"id":"infective-endocarditis~ai-2","moduleId":"infective-endocarditis","stem":"What is the mechanism by which vegetations form on heart valves in infective endocarditis?","options":[{"id":"a","text":"Bacterial toxins damage the valve"},{"id":"b","text":"Bacteremia leads to colonization and fibrin deposition"},{"id":"c","text":"Autoimmune response to valve tissue"},{"id":"d","text":"Direct invasion of valve by bacteria"}],"answerId":"b","explanation":"Vegetations form due to bacteremia leading to microbial colonization and fibrin deposition on the valve surface.","kind":"mechanism","origin":"ai"},{"id":"infective-endocarditis~ai-3","moduleId":"infective-endocarditis","stem":"Which of the following is a distinguishing feature of subacute infective endocarditis?","options":[{"id":"a","text":"Rapid onset of symptoms"},{"id":"b","text":"High virulence organism"},{"id":"c","text":"Presence of Janeway lesions"},{"id":"d","text":"Involvement of normal valves"}],"answerId":"c","explanation":"Janeway lesions are associated with subacute infective endocarditis and are caused by septic emboli.","kind":"trap","origin":"ai"},{"id":"infective-endocarditis~ai-4","moduleId":"infective-endocarditis","stem":"A patient with a history of intravenous drug use presents with fever and a new pansystolic murmur. Which valve is most likely affected?","options":[{"id":"a","text":"Mitral valve"},{"id":"b","text":"Aortic valve"},{"id":"c","text":"Tricuspid valve"},{"id":"d","text":"Pulmonary valve"}],"answerId":"c","explanation":"Infective endocarditis in intravenous drug users commonly affects the tricuspid valve due to direct venous access.","kind":"clinical","origin":"ai"},{"id":"infective-endocarditis~ai-5","moduleId":"infective-endocarditis","stem":"How does infective endocarditis relate to aortic stenosis in terms of risk factors?","options":[{"id":"a","text":"Both are caused by bacterial infections"},{"id":"b","text":"Both involve immune complex deposition"},{"id":"c","text":"Aortic stenosis increases risk of endocarditis due to turbulent flow"},{"id":"d","text":"Both present with similar peripheral stigmata"}],"answerId":"c","explanation":"Aortic stenosis can lead to turbulent blood flow, which increases the risk of bacterial colonization and subsequent infective endocarditis.","kind":"integration","linkedModuleIds":["aortic-stenosis"],"origin":"ai"},{"id":"infective-endocarditis~ai-6","moduleId":"infective-endocarditis","stem":"Which of the following best explains the relationship between infective endocarditis and Streptococcus viridans?","options":[{"id":"a","text":"Streptococcus viridans causes acute endocarditis"},{"id":"b","text":"Streptococcus viridans is associated with normal valves"},{"id":"c","text":"Streptococcus viridans typically causes subacute endocarditis on damaged valves"},{"id":"d","text":"Streptococcus viridans is a common cause of tricuspid endocarditis"}],"answerId":"c","explanation":"Streptococcus viridans is a low-virulence organism that typically causes subacute infective endocarditis on previously damaged valves.","kind":"integration","linkedModuleIds":["streptococcus-pneumoniae-enterococci"],"origin":"ai"}],"dilated-cardiomyopathy":[{"id":"dilated-cardiomyopathy~ai-0","moduleId":"dilated-cardiomyopathy","stem":"What is the most common cause of dilated cardiomyopathy?","options":[{"id":"a","text":"Alcohol abuse"},{"id":"b","text":"Genetic mutations"},{"id":"c","text":"Myocarditis"},{"id":"d","text":"Idiopathic"}],"answerId":"d","explanation":"The majority of dilated cardiomyopathy cases are idiopathic, despite genetic factors being significant.","kind":"recall","origin":"ai"},{"id":"dilated-cardiomyopathy~ai-1","moduleId":"dilated-cardiomyopathy","stem":"Which of the following findings is characteristic of dilated cardiomyopathy?","options":[{"id":"a","text":"S4 gallop"},{"id":"b","text":"Displaced diffuse apex + S3 gallop"},{"id":"c","text":"Muffled heart sounds"},{"id":"d","text":"Friction rub"}],"answerId":"b","explanation":"A displaced diffuse apex and S3 gallop indicate volume overload due to dilated left ventricle.","kind":"recall","origin":"ai"},{"id":"dilated-cardiomyopathy~ai-2","moduleId":"dilated-cardiomyopathy","stem":"Which mechanism leads to the development of heart failure in dilated cardiomyopathy?","options":[{"id":"a","text":"Increased contractility"},{"id":"b","text":"Weak contraction leading to dilation"},{"id":"c","text":"Increased preload"},{"id":"d","text":"Decreased afterload"}],"answerId":"b","explanation":"Weak contraction results in dilation of the heart, leading to low-output heart failure.","kind":"mechanism","origin":"ai"},{"id":"dilated-cardiomyopathy~ai-3","moduleId":"dilated-cardiomyopathy","stem":"What is the inheritance pattern of dystrophin-related dilated cardiomyopathy?","options":[{"id":"a","text":"Autosomal dominant"},{"id":"b","text":"Autosomal recessive"},{"id":"c","text":"X-linked"},{"id":"d","text":"Mitochondrial"}],"answerId":"c","explanation":"Dystrophin mutations causing dilated cardiomyopathy are X-linked, as seen in Duchenne and Becker muscular dystrophies.","kind":"trap","origin":"ai"},{"id":"dilated-cardiomyopathy~ai-4","moduleId":"dilated-cardiomyopathy","stem":"In a patient with dilated cardiomyopathy, which of the following is a common clinical finding?","options":[{"id":"a","text":"Bradycardia"},{"id":"b","text":"Raised JVP"},{"id":"c","text":"Hypotension"},{"id":"d","text":"Cyanosis"}],"answerId":"b","explanation":"Raised JVP is indicative of congestive heart failure, which is common in dilated cardiomyopathy.","kind":"clinical","origin":"ai"},{"id":"dilated-cardiomyopathy~ai-5","moduleId":"dilated-cardiomyopathy","stem":"How does myocarditis contribute to the development of dilated cardiomyopathy?","options":[{"id":"a","text":"By causing myocardial hypertrophy"},{"id":"b","text":"By leading to myocardial inflammation and damage"},{"id":"c","text":"By increasing cardiac output"},{"id":"d","text":"By decreasing heart rate"}],"answerId":"b","explanation":"Myocarditis causes inflammation and damage to the myocardium, which can lead to dilation and heart failure.","kind":"integration","linkedModuleIds":["myocarditis"],"origin":"ai"},{"id":"dilated-cardiomyopathy~ai-6","moduleId":"dilated-cardiomyopathy","stem":"Which type of cardiomyopathy is characterized by systolic dysfunction and chamber dilation?","options":[{"id":"a","text":"Hypertrophic cardiomyopathy"},{"id":"b","text":"Restrictive cardiomyopathy"},{"id":"c","text":"Dilated cardiomyopathy"},{"id":"d","text":"Arrhythmogenic right ventricular cardiomyopathy"}],"answerId":"c","explanation":"Dilated cardiomyopathy is defined by systolic dysfunction and dilation of all heart chambers.","kind":"integration","linkedModuleIds":["cardiomyopathy-overview"],"origin":"ai"}],"restrictive-cardiomyopathy":[{"id":"restrictive-cardiomyopathy~ai-0","moduleId":"restrictive-cardiomyopathy","stem":"What is the most common cause of restrictive cardiomyopathy?","options":[{"id":"a","text":"Hypertensive heart disease"},{"id":"b","text":"Amyloidosis"},{"id":"c","text":"Ischemic heart disease"},{"id":"d","text":"Valvular heart disease"}],"answerId":"b","explanation":"Amyloidosis is the most common cause of restrictive cardiomyopathy, leading to myocardial infiltration.","kind":"recall","origin":"ai"},{"id":"restrictive-cardiomyopathy~ai-1","moduleId":"restrictive-cardiomyopathy","stem":"Which of the following findings is characteristic of restrictive cardiomyopathy?","options":[{"id":"a","text":"S3 gallop"},{"id":"b","text":"Kussmaul sign"},{"id":"c","text":"Pulsus paradoxus"},{"id":"d","text":"Wide pulse pressure"}],"answerId":"b","explanation":"Kussmaul sign, where JVP rises on inspiration, is indicative of restricted filling in restrictive cardiomyopathy.","kind":"recall","origin":"ai"},{"id":"restrictive-cardiomyopathy~ai-2","moduleId":"restrictive-cardiomyopathy","stem":"What is the primary mechanism underlying the diastolic dysfunction seen in restrictive cardiomyopathy?","options":[{"id":"a","text":"Myocardial ischemia"},{"id":"b","text":"Infiltration or fibrosis"},{"id":"c","text":"Increased preload"},{"id":"d","text":"Decreased contractility"}],"answerId":"b","explanation":"Infiltration or fibrosis leads to a stiff ventricle, impairing filling and causing diastolic dysfunction.","kind":"mechanism","origin":"ai"},{"id":"restrictive-cardiomyopathy~ai-3","moduleId":"restrictive-cardiomyopathy","stem":"In which condition would you expect biatrial dilation with normal-sized ventricles?","options":[{"id":"a","text":"Dilated cardiomyopathy"},{"id":"b","text":"Restrictive cardiomyopathy"},{"id":"c","text":"Hypertrophic cardiomyopathy"},{"id":"d","text":"Constrictive pericarditis"}],"answerId":"b","explanation":"Restrictive cardiomyopathy is characterized by biatrial dilation while the ventricles remain normal-sized.","kind":"clinical","origin":"ai"},{"id":"restrictive-cardiomyopathy~ai-4","moduleId":"restrictive-cardiomyopathy","stem":"Which of the following is a distinguishing feature of restrictive cardiomyopathy compared to constrictive pericarditis?","options":[{"id":"a","text":"Normal-sized heart"},{"id":"b","text":"Kussmaul sign"},{"id":"c","text":"Elevated JVP"},{"id":"d","text":"Hepatomegaly"}],"answerId":"a","explanation":"Both conditions can present with right heart failure and normal-sized ventricles, but restrictive cardiomyopathy is due to intrinsic myocardial stiffening.","kind":"trap","origin":"ai"},{"id":"restrictive-cardiomyopathy~ai-5","moduleId":"restrictive-cardiomyopathy","stem":"How does cardiac amyloidosis lead to restrictive cardiomyopathy?","options":[{"id":"a","text":"Increased myocardial contractility"},{"id":"b","text":"Myocardial infiltration causing stiffness"},{"id":"c","text":"Coronary artery obstruction"},{"id":"d","text":"Increased heart rate"}],"answerId":"b","explanation":"Cardiac amyloidosis causes infiltration of the myocardium, leading to stiffness and impaired filling, characteristic of restrictive cardiomyopathy.","kind":"mechanism","origin":"ai"},{"id":"restrictive-cardiomyopathy~ai-6","moduleId":"restrictive-cardiomyopathy","stem":"A patient with restrictive cardiomyopathy presents with signs of systemic amyloidosis. What is the most likely underlying condition?","options":[{"id":"a","text":"Multiple myeloma"},{"id":"b","text":"Hypertension"},{"id":"c","text":"Coronary artery disease"},{"id":"d","text":"Diabetes mellitus"}],"answerId":"a","explanation":"AL amyloidosis, associated with multiple myeloma, is a common cause of cardiac amyloidosis leading to restrictive cardiomyopathy.","kind":"integration","linkedModuleIds":["cardiomyopathy-overview"],"origin":"ai"},{"id":"restrictive-cardiomyopathy~ai-7","moduleId":"restrictive-cardiomyopathy","stem":"Which of the following is a common clinical finding in both restrictive cardiomyopathy and dilated cardiomyopathy?","options":[{"id":"a","text":"Systolic dysfunction"},{"id":"b","text":"Right-sided heart failure"},{"id":"c","text":"Kussmaul sign"},{"id":"d","text":"Normal-sized ventricles"}],"answerId":"b","explanation":"Both restrictive and dilated cardiomyopathy can lead to right-sided heart failure, although their mechanisms differ.","kind":"integration","linkedModuleIds":["dilated-cardiomyopathy"],"origin":"ai"}],"acs-spectrum":[{"id":"acs-spectrum~ai-0","moduleId":"acs-spectrum","stem":"What is the primary mechanism leading to acute coronary syndrome (ACS)?","options":[{"id":"a","text":"Coronary vasospasm"},{"id":"b","text":"Plaque rupture"},{"id":"c","text":"Coronary artery dissection"},{"id":"d","text":"Myocardial hypertrophy"}],"answerId":"b","explanation":"ACS primarily results from plaque rupture, leading to thrombus formation and subsequent ischemia.","kind":"mechanism","origin":"ai"},{"id":"acs-spectrum~ai-1","moduleId":"acs-spectrum","stem":"Which of the following findings is characteristic of ST elevation myocardial infarction (STEMI)?","options":[{"id":"a","text":"Troponin elevation without ST elevation"},{"id":"b","text":"ST elevation in a coronary territory"},{"id":"c","text":"Normal ECG with chest pain"},{"id":"d","text":"T-wave inversion only"}],"answerId":"b","explanation":"STEMI is defined by ST elevation in a specific coronary territory, indicating transmural myocardial injury.","kind":"recall","origin":"ai"},{"id":"acs-spectrum~ai-2","moduleId":"acs-spectrum","stem":"A patient presents with chest pain and ST elevation in leads II, III, and aVF. Which coronary artery is most likely occluded?","options":[{"id":"a","text":"Left anterior descending artery"},{"id":"b","text":"Right coronary artery"},{"id":"c","text":"Left circumflex artery"},{"id":"d","text":"Diagonal artery"}],"answerId":"b","explanation":"ST elevation in leads II, III, and aVF indicates inferior wall involvement, typically due to right coronary artery occlusion.","kind":"clinical","origin":"ai"},{"id":"acs-spectrum~ai-3","moduleId":"acs-spectrum","stem":"Which of the following is a common trap in diagnosing STEMI?","options":[{"id":"a","text":"Any ST elevation indicates STEMI"},{"id":"b","text":"Troponin levels are always elevated in UA"},{"id":"c","text":"ST depression is specific for NSTEMI"},{"id":"d","text":"Reciprocal ST changes confirm UA"}],"answerId":"a","explanation":"Assuming any ST elevation indicates STEMI can lead to inappropriate thrombolysis; other conditions like pericarditis can mimic this finding.","kind":"trap","origin":"ai"},{"id":"acs-spectrum~ai-4","moduleId":"acs-spectrum","stem":"What is the role of troponin in the diagnosis of acute coronary syndrome?","options":[{"id":"a","text":"It is only elevated in STEMI"},{"id":"b","text":"It confirms the presence of myocardial ischemia"},{"id":"c","text":"It differentiates between UA and NSTEMI"},{"id":"d","text":"It is not useful in ACS diagnosis"}],"answerId":"c","explanation":"Troponin elevation is crucial for distinguishing NSTEMI from unstable angina, as it indicates myocardial injury.","kind":"recall","origin":"ai"},{"id":"acs-spectrum~ai-5","moduleId":"acs-spectrum","stem":"A patient with suspected ACS has elevated troponin levels but no ST elevation on ECG. What is the likely diagnosis?","options":[{"id":"a","text":"Unstable angina"},{"id":"b","text":"STEMI"},{"id":"c","text":"NSTEMI"},{"id":"d","text":"Coronary vasospasm"}],"answerId":"c","explanation":"Elevated troponin without ST elevation suggests NSTEMI, indicating myocardial injury without full thickness damage.","kind":"clinical","origin":"ai"},{"id":"acs-spectrum~ai-6","moduleId":"acs-spectrum","stem":"How does the management of ACS relate to cardiac biomarkers?","options":[{"id":"a","text":"Biomarkers are irrelevant in management"},{"id":"b","text":"Biomarkers guide the timing of reperfusion therapy"},{"id":"c","text":"Biomarkers are used only for diagnosis"},{"id":"d","text":"Biomarkers indicate the need for surgery"}],"answerId":"b","explanation":"Cardiac biomarkers help determine the timing and necessity of reperfusion therapy in ACS management.","kind":"integration","linkedModuleIds":["cardiac-biomarkers-acs"],"origin":"ai"},{"id":"acs-spectrum~ai-7","moduleId":"acs-spectrum","stem":"What is the significance of reciprocal changes on an ECG in the context of ACS?","options":[{"id":"a","text":"They confirm the diagnosis of UA"},{"id":"b","text":"They indicate a non-occlusive thrombus"},{"id":"c","text":"They help localize the area of ischemia"},{"id":"d","text":"They are irrelevant to ACS diagnosis"}],"answerId":"c","explanation":"Reciprocal changes on ECG help localize the area of ischemia, supporting the diagnosis of STEMI.","kind":"integration","linkedModuleIds":["cardiac-biomarkers-acs"],"origin":"ai"}],"hypertrophic-cardiomyopathy":[{"id":"hypertrophic-cardiomyopathy~ai-0","moduleId":"hypertrophic-cardiomyopathy","stem":"What is the most common genetic mutation associated with hypertrophic cardiomyopathy?","options":[{"id":"a","text":"β-myosin heavy chain"},{"id":"b","text":"Troponin I"},{"id":"c","text":"Cardiac actin"},{"id":"d","text":"Myosin light chain"}],"answerId":"a","explanation":"The most common genetic mutations in hypertrophic cardiomyopathy are found in the β-myosin heavy chain and myosin-binding protein C.","kind":"recall","origin":"ai"},{"id":"hypertrophic-cardiomyopathy~ai-1","moduleId":"hypertrophic-cardiomyopathy","stem":"Which of the following findings is characteristic of hypertrophic cardiomyopathy during physical examination?","options":[{"id":"a","text":"Systolic ejection murmur that softens with Valsalva"},{"id":"b","text":"Diastolic murmur"},{"id":"c","text":"Harsh mid-systolic ejection murmur that increases with Valsalva"},{"id":"d","text":"Continuous murmur"}],"answerId":"c","explanation":"In hypertrophic cardiomyopathy, the mid-systolic ejection murmur becomes louder with decreased preload, such as during Valsalva maneuver.","kind":"recall","origin":"ai"},{"id":"hypertrophic-cardiomyopathy~ai-2","moduleId":"hypertrophic-cardiomyopathy","stem":"What is the primary mechanism leading to diastolic dysfunction in hypertrophic cardiomyopathy?","options":[{"id":"a","text":"Increased left ventricular volume"},{"id":"b","text":"Myofiber disarray"},{"id":"c","text":"Decreased compliance of the left ventricle"},{"id":"d","text":"Increased heart rate"}],"answerId":"c","explanation":"Diastolic dysfunction in hypertrophic cardiomyopathy is primarily due to decreased compliance of the hypertrophied left ventricle.","kind":"mechanism","origin":"ai"},{"id":"hypertrophic-cardiomyopathy~ai-3","moduleId":"hypertrophic-cardiomyopathy","stem":"A 20-year-old athlete collapses during a game. What is the most likely cause of his sudden cardiac death?","options":[{"id":"a","text":"Coronary artery disease"},{"id":"b","text":"Hypertrophic cardiomyopathy"},{"id":"c","text":"Arrhythmogenic right ventricular cardiomyopathy"},{"id":"d","text":"Dilated cardiomyopathy"}],"answerId":"b","explanation":"Hypertrophic cardiomyopathy is the most common cause of sudden cardiac death in young athletes due to the risk of ventricular arrhythmias.","kind":"clinical","origin":"ai"},{"id":"hypertrophic-cardiomyopathy~ai-4","moduleId":"hypertrophic-cardiomyopathy","stem":"In hypertrophic cardiomyopathy, which statement about the murmur is true?","options":[{"id":"a","text":"It is similar to aortic stenosis murmur"},{"id":"b","text":"It softens with decreased preload"},{"id":"c","text":"It is a continuous murmur"},{"id":"d","text":"It increases with decreased preload"}],"answerId":"d","explanation":"The murmur in hypertrophic cardiomyopathy increases with decreased preload because less left ventricular volume leads to more outflow obstruction.","kind":"trap","origin":"ai"},{"id":"hypertrophic-cardiomyopathy~ai-5","moduleId":"hypertrophic-cardiomyopathy","stem":"How does the mechanism of hypertrophic cardiomyopathy relate to mutations in sarcomere proteins?","options":[{"id":"a","text":"Mutations lead to increased calcium sensitivity"},{"id":"b","text":"Mutations cause myofiber disarray"},{"id":"c","text":"Mutations result in decreased contractility"},{"id":"d","text":"Mutations cause ventricular dilation"}],"answerId":"b","explanation":"Mutations in sarcomere proteins lead to myofiber disarray, which contributes to the hypertrophy seen in hypertrophic cardiomyopathy.","kind":"integration","linkedModuleIds":["skeletal-muscle-sarcomere"],"origin":"ai"},{"id":"hypertrophic-cardiomyopathy~ai-6","moduleId":"hypertrophic-cardiomyopathy","stem":"Which of the following best describes the relationship between hypertrophic cardiomyopathy and the risk of sudden cardiac death?","options":[{"id":"a","text":"It is primarily due to coronary artery disease"},{"id":"b","text":"It is related to ventricular arrhythmias from structural changes"},{"id":"c","text":"It is due to valvular heart disease"},{"id":"d","text":"It is unrelated to genetic factors"}],"answerId":"b","explanation":"The risk of sudden cardiac death in hypertrophic cardiomyopathy is related to ventricular arrhythmias that arise from structural changes in the heart.","kind":"integration","linkedModuleIds":["cardiomyopathy-overview"],"origin":"ai"}],"aortic-stenosis":[{"id":"aortic-stenosis~ai-0","moduleId":"aortic-stenosis","stem":"What is the most common cause of aortic stenosis in elderly patients?","options":[{"id":"a","text":"Bicuspid aortic valve"},{"id":"b","text":"Rheumatic fever"},{"id":"c","text":"Calcific degeneration"},{"id":"d","text":"Infective endocarditis"}],"answerId":"c","explanation":"Calcific degeneration is the most common cause of aortic stenosis in elderly patients.","kind":"recall","origin":"ai"},{"id":"aortic-stenosis~ai-1","moduleId":"aortic-stenosis","stem":"What is the characteristic heart sound associated with severe aortic stenosis?","options":[{"id":"a","text":"Loud S1"},{"id":"b","text":"Soft/absent S2"},{"id":"c","text":"Split S2"},{"id":"d","text":"S3 gallop"}],"answerId":"b","explanation":"In severe aortic stenosis, the second heart sound (S2) is often soft or absent due to reduced ejection.","kind":"recall","origin":"ai"},{"id":"aortic-stenosis~ai-2","moduleId":"aortic-stenosis","stem":"Which of the following findings is most indicative of aortic stenosis during physical examination?","options":[{"id":"a","text":"Pulsus bisferiens"},{"id":"b","text":"Pulsus parvus et tardus"},{"id":"c","text":"Bounding pulses"},{"id":"d","text":"Water-hammer pulse"}],"answerId":"b","explanation":"Pulsus parvus et tardus indicates a slow-rising pulse due to reduced cardiac output in aortic stenosis.","kind":"clinical","origin":"ai"},{"id":"aortic-stenosis~ai-3","moduleId":"aortic-stenosis","stem":"What is the primary hemodynamic consequence of fixed outflow obstruction in aortic stenosis?","options":[{"id":"a","text":"Increased stroke volume"},{"id":"b","text":"Decreased cardiac output"},{"id":"c","text":"Pressure overload"},{"id":"d","text":"Volume overload"}],"answerId":"c","explanation":"Fixed outflow obstruction leads to pressure overload on the left ventricle in aortic stenosis.","kind":"mechanism","origin":"ai"},{"id":"aortic-stenosis~ai-4","moduleId":"aortic-stenosis","stem":"A patient presents with exertional syncope. Which mechanism explains this symptom in aortic stenosis?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Fixed cardiac output"},{"id":"c","text":"Decreased preload"},{"id":"d","text":"Increased afterload"}],"answerId":"b","explanation":"In aortic stenosis, fixed cardiac output cannot meet the increased demand during exertion, leading to syncope.","kind":"mechanism","origin":"ai"},{"id":"aortic-stenosis~ai-5","moduleId":"aortic-stenosis","stem":"Which murmur is incorrectly associated with aortic stenosis?","options":[{"id":"a","text":"Ejection systolic murmur at the right 2nd ICS"},{"id":"b","text":"Murmur radiating to the carotids"},{"id":"c","text":"Crescendo-decrescendo shape"},{"id":"d","text":"Holosystolic murmur at the apex"}],"answerId":"d","explanation":"A holosystolic murmur at the apex suggests mitral regurgitation, not aortic stenosis.","kind":"trap","origin":"ai"},{"id":"aortic-stenosis~ai-6","moduleId":"aortic-stenosis","stem":"How does aortic stenosis potentially lead to hypertensive target-organ damage?","options":[{"id":"a","text":"Increased stroke volume"},{"id":"b","text":"Pressure overload on the left ventricle"},{"id":"c","text":"Decreased systemic vascular resistance"},{"id":"d","text":"Increased heart rate"}],"answerId":"b","explanation":"Pressure overload on the left ventricle in aortic stenosis can lead to hypertensive target-organ damage over time.","kind":"integration","linkedModuleIds":["hypertensive-target-organ-damage"],"origin":"ai"},{"id":"aortic-stenosis~ai-7","moduleId":"aortic-stenosis","stem":"Which finding in aortic stenosis would be most relevant when examining a patient for infective endocarditis?","options":[{"id":"a","text":"Ejection systolic murmur"},{"id":"b","text":"Soft S2"},{"id":"c","text":"Pulsus parvus et tardus"},{"id":"d","text":"Sustained apex beat"}],"answerId":"a","explanation":"The ejection systolic murmur is a key finding in aortic stenosis and can be relevant in assessing for infective endocarditis.","kind":"integration","linkedModuleIds":["infective-endocarditis"],"origin":"ai"}],"nonbacterial-endocarditis":[{"id":"nonbacterial-endocarditis~ai-0","moduleId":"nonbacterial-endocarditis","stem":"What is the primary characteristic of nonbacterial thrombotic endocarditis (NBTE)?","options":[{"id":"a","text":"Presence of bacteria in blood cultures"},{"id":"b","text":"Sterile vegetations on heart valves"},{"id":"c","text":"Vegetations on only one side of the valve"},{"id":"d","text":"Large, infected vegetations"}],"answerId":"b","explanation":"NBTE is characterized by sterile vegetations, which distinguishes it from infective endocarditis where bacteria are present.","kind":"recall","origin":"ai"},{"id":"nonbacterial-endocarditis~ai-1","moduleId":"nonbacterial-endocarditis","stem":"Which condition is most commonly associated with Libman-Sacks endocarditis?","options":[{"id":"a","text":"Diabetes mellitus"},{"id":"b","text":"Systemic lupus erythematosus"},{"id":"c","text":"Rheumatic fever"},{"id":"d","text":"Hypertension"}],"answerId":"b","explanation":"Libman-Sacks endocarditis is primarily associated with systemic lupus erythematosus (SLE).","kind":"recall","origin":"ai"},{"id":"nonbacterial-endocarditis~ai-2","moduleId":"nonbacterial-endocarditis","stem":"In a patient with a history of pancreatic adenocarcinoma, which finding would suggest nonbacterial thrombotic endocarditis?","options":[{"id":"a","text":"Positive blood cultures"},{"id":"b","text":"Embolic stroke with negative cultures"},{"id":"c","text":"Fever and chills"},{"id":"d","text":"Murmur of aortic regurgitation"}],"answerId":"b","explanation":"An embolic stroke with negative cultures in a cancer patient indicates nonbacterial thrombotic endocarditis.","kind":"clinical","origin":"ai"},{"id":"nonbacterial-endocarditis~ai-3","moduleId":"nonbacterial-endocarditis","stem":"What is the mechanism behind the sterile vegetations seen in Libman-Sacks endocarditis?","options":[{"id":"a","text":"Bacterial infection"},{"id":"b","text":"Immune complex deposition"},{"id":"c","text":"Direct endothelial injury"},{"id":"d","text":"Hypercoagulable state"}],"answerId":"b","explanation":"Libman-Sacks vegetations are formed due to immune complex deposition associated with SLE.","kind":"mechanism","origin":"ai"},{"id":"nonbacterial-endocarditis~ai-4","moduleId":"nonbacterial-endocarditis","stem":"A patient presents with a stroke and negative blood cultures. Which of the following is the most likely diagnosis?","options":[{"id":"a","text":"Infective endocarditis"},{"id":"b","text":"Nonbacterial thrombotic endocarditis"},{"id":"c","text":"Aortic stenosis"},{"id":"d","text":"Libman-Sacks endocarditis"}],"answerId":"b","explanation":"Negative blood cultures and an embolic event suggest nonbacterial thrombotic endocarditis, especially in the context of malignancy.","kind":"trap","origin":"ai"},{"id":"nonbacterial-endocarditis~ai-5","moduleId":"nonbacterial-endocarditis","stem":"Which test is most appropriate for evaluating a patient suspected of having Libman-Sacks endocarditis?","options":[{"id":"a","text":"Blood culture"},{"id":"b","text":"Echocardiogram"},{"id":"c","text":"ANA/anti-dsDNA"},{"id":"d","text":"CT scan of the abdomen"}],"answerId":"c","explanation":"ANA/anti-dsDNA testing is essential for diagnosing systemic lupus erythematosus, which is associated with Libman-Sacks endocarditis.","kind":"clinical","origin":"ai"},{"id":"nonbacterial-endocarditis~ai-6","moduleId":"nonbacterial-endocarditis","stem":"How does nonbacterial thrombotic endocarditis differ from infective endocarditis in terms of vegetations?","options":[{"id":"a","text":"NBTE vegetations are larger"},{"id":"b","text":"NBTE vegetations are sterile"},{"id":"c","text":"Infective endocarditis has no vegetations"},{"id":"d","text":"Infective endocarditis vegetations are always sterile"}],"answerId":"b","explanation":"NBTE is characterized by sterile vegetations, while infective endocarditis involves vegetations that contain organisms.","kind":"integration","linkedModuleIds":["infective-endocarditis"],"origin":"ai"},{"id":"nonbacterial-endocarditis~ai-7","moduleId":"nonbacterial-endocarditis","stem":"Which of the following findings would most likely be present in both Libman-Sacks endocarditis and infective endocarditis?","options":[{"id":"a","text":"Sterile vegetations"},{"id":"b","text":"Embolic events"},{"id":"c","text":"Positive blood cultures"},{"id":"d","text":"Vegetations on only one side of the valve"}],"answerId":"b","explanation":"Both conditions can lead to embolic events, but the nature of the vegetations and blood cultures differs.","kind":"integration","linkedModuleIds":["infective-endocarditis"],"origin":"ai"}],"cardiomyopathy-overview":[{"id":"cardiomyopathy-overview~ai-0","moduleId":"cardiomyopathy-overview","stem":"What is the primary characteristic of dilated cardiomyopathy (DCM)?","options":[{"id":"a","text":"Diastolic dysfunction with preserved ejection fraction"},{"id":"b","text":"Systolic dysfunction with ejection fraction <40%"},{"id":"c","text":"Arrhythmias due to structural disarray"},{"id":"d","text":"Right heart failure with stiff ventricles"}],"answerId":"b","explanation":"DCM is defined by systolic dysfunction, typically with an ejection fraction less than 40%.","kind":"recall","origin":"ai"},{"id":"cardiomyopathy-overview~ai-1","moduleId":"cardiomyopathy-overview","stem":"Which of the following is a common clinical finding in hypertrophic cardiomyopathy (HCM)?","options":[{"id":"a","text":"Functional mitral regurgitation"},{"id":"b","text":"Ejection murmur"},{"id":"c","text":"Stiff ventricle"},{"id":"d","text":"Right heart failure"}],"answerId":"b","explanation":"HCM is characterized by an ejection murmur due to left ventricular outflow tract obstruction.","kind":"clinical","origin":"ai"},{"id":"cardiomyopathy-overview~ai-2","moduleId":"cardiomyopathy-overview","stem":"What is the mechanism behind the symptoms of restrictive cardiomyopathy (RCM)?","options":[{"id":"a","text":"Chamber dilation"},{"id":"b","text":"Stiff ventricle"},{"id":"c","text":"Myocardial disarray"},{"id":"d","text":"Ischemic damage"}],"answerId":"b","explanation":"RCM is characterized by a stiff ventricle, leading to impaired filling and symptoms of heart failure.","kind":"mechanism","origin":"ai"},{"id":"cardiomyopathy-overview~ai-3","moduleId":"cardiomyopathy-overview","stem":"Which of the following conditions must be excluded to diagnose primary cardiomyopathy?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Coronary artery disease"},{"id":"c","text":"Valvular disease"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"Primary cardiomyopathy requires exclusion of secondary causes such as hypertension, CAD, and valvular disease.","kind":"trap","origin":"ai"},{"id":"cardiomyopathy-overview~ai-4","moduleId":"cardiomyopathy-overview","stem":"In the context of cardiomyopathy, what does the MOGE(S) classification stand for?","options":[{"id":"a","text":"Morphofunctional, Organ, Genetic, Etiology, Stage"},{"id":"b","text":"Morphological, Organism, Genetic, Etiology, Severity"},{"id":"c","text":"Myocardial, Organ, Genetic, Etiology, Stage"},{"id":"d","text":"Morphofunctional, Organ, Genetic, Environment, Stage"}],"answerId":"a","explanation":"MOGE(S) is a classification system that describes the phenotype and genotype of cardiomyopathies.","kind":"recall","origin":"ai"},{"id":"cardiomyopathy-overview~ai-5","moduleId":"cardiomyopathy-overview","stem":"Which of the following is a potential secondary mimic of dilated cardiomyopathy?","options":[{"id":"a","text":"Hypertrophic cardiomyopathy"},{"id":"b","text":"Ischemic heart disease"},{"id":"c","text":"Arrhythmogenic right ventricular cardiomyopathy"},{"id":"d","text":"Restrictive cardiomyopathy"}],"answerId":"b","explanation":"Ischemic heart disease can lead to dilation of the heart but is not classified as primary dilated cardiomyopathy.","kind":"trap","origin":"ai"},{"id":"cardiomyopathy-overview~ai-6","moduleId":"cardiomyopathy-overview","stem":"How does arrhythmogenic right ventricular cardiomyopathy (ARVC) primarily affect the heart?","options":[{"id":"a","text":"Causes left ventricular hypertrophy"},{"id":"b","text":"Leads to right ventricular dilation and arrhythmias"},{"id":"c","text":"Results in myocardial stiffness"},{"id":"d","text":"Causes ischemic changes in the myocardium"}],"answerId":"b","explanation":"ARVC primarily affects the right ventricle, leading to dilation and arrhythmias due to myocardial replacement with fibrofatty tissue.","kind":"integration","linkedModuleIds":["arvc"],"origin":"ai"},{"id":"cardiomyopathy-overview~ai-7","moduleId":"cardiomyopathy-overview","stem":"Which type of cardiomyopathy is most commonly associated with systolic dysfunction?","options":[{"id":"a","text":"Hypertrophic cardiomyopathy"},{"id":"b","text":"Restrictive cardiomyopathy"},{"id":"c","text":"Dilated cardiomyopathy"},{"id":"d","text":"Arrhythmogenic right ventricular cardiomyopathy"}],"answerId":"c","explanation":"Dilated cardiomyopathy is characterized by systolic dysfunction, leading to reduced ejection fraction.","kind":"integration","linkedModuleIds":["dilated-cardiomyopathy"],"origin":"ai"}],"mitral-stenosis":[{"id":"mitral-stenosis~ai-0","moduleId":"mitral-stenosis","stem":"What is the most common cause of mitral stenosis?","options":[{"id":"a","text":"Congenital malformation"},{"id":"b","text":"Degenerative calcification"},{"id":"c","text":"Rheumatic fever"},{"id":"d","text":"Infective endocarditis"}],"answerId":"c","explanation":"Mitral stenosis is almost always caused by rheumatic fever, leading to commissural fusion and valve thickening.","kind":"recall","origin":"ai"},{"id":"mitral-stenosis~ai-1","moduleId":"mitral-stenosis","stem":"Which of the following findings is characteristic of mitral stenosis?","options":[{"id":"a","text":"Systolic ejection murmur"},{"id":"b","text":"Loud S1 + opening snap"},{"id":"c","text":"Diastolic murmur at the left sternal border"},{"id":"d","text":"Pansystolic murmur at the apex"}],"answerId":"b","explanation":"Mitral stenosis is characterized by a loud S1 and an opening snap followed by a low-pitched mid-diastolic rumble.","kind":"recall","origin":"ai"},{"id":"mitral-stenosis~ai-2","moduleId":"mitral-stenosis","stem":"Which mechanism explains the development of atrial fibrillation in mitral stenosis?","options":[{"id":"a","text":"Increased left atrial pressure"},{"id":"b","text":"Decreased left ventricular output"},{"id":"c","text":"Pulmonary hypertension"},{"id":"d","text":"Right heart failure"}],"answerId":"a","explanation":"Increased left atrial pressure due to stenosis leads to left atrial enlargement, which predisposes to atrial fibrillation.","kind":"mechanism","origin":"ai"},{"id":"mitral-stenosis~ai-3","moduleId":"mitral-stenosis","stem":"What is the most likely symptom in a patient with severe mitral stenosis?","options":[{"id":"a","text":"Chest pain"},{"id":"b","text":"Syncope"},{"id":"c","text":"Dyspnea"},{"id":"d","text":"Palpitations"}],"answerId":"c","explanation":"Dyspnea is a common symptom due to pulmonary congestion resulting from elevated left atrial pressure.","kind":"clinical","origin":"ai"},{"id":"mitral-stenosis~ai-4","moduleId":"mitral-stenosis","stem":"Which of the following is a trap regarding mitral stenosis murmurs?","options":[{"id":"a","text":"Mitral stenosis causes a systolic murmur"},{"id":"b","text":"Mitral stenosis is associated with a diastolic rumble"},{"id":"c","text":"Mitral regurgitation causes a diastolic murmur"},{"id":"d","text":"Mitral stenosis has no associated sounds"}],"answerId":"a","explanation":"Mitral stenosis is characterized by a mid-diastolic rumble, while mitral regurgitation presents with a systolic murmur.","kind":"trap","origin":"ai"},{"id":"mitral-stenosis~ai-5","moduleId":"mitral-stenosis","stem":"In a patient with mitral stenosis, which of the following findings would you expect to see on examination?","options":[{"id":"a","text":"Loud S1 + opening snap + mid-diastolic rumble"},{"id":"b","text":"Diastolic murmur at the left sternal border"},{"id":"c","text":"Systolic murmur with a thrill"},{"id":"d","text":"Continuous murmur"}],"answerId":"a","explanation":"The classic examination findings in mitral stenosis include a loud S1, opening snap, and a mid-diastolic rumble.","kind":"recall","origin":"ai"},{"id":"mitral-stenosis~ai-6","moduleId":"mitral-stenosis","stem":"How does mitral stenosis relate to rheumatic heart disease?","options":[{"id":"a","text":"It is a consequence of untreated rheumatic fever"},{"id":"b","text":"It is unrelated to rheumatic heart disease"},{"id":"c","text":"It is a type of infective endocarditis"},{"id":"d","text":"It is a congenital defect"}],"answerId":"a","explanation":"Mitral stenosis is often a consequence of rheumatic fever, which damages the mitral valve.","kind":"integration","linkedModuleIds":["rheumatic-heart-disease"],"origin":"ai"},{"id":"mitral-stenosis~ai-7","moduleId":"mitral-stenosis","stem":"Which of the following conditions can lead to similar symptoms as mitral stenosis?","options":[{"id":"a","text":"Aortic stenosis"},{"id":"b","text":"Hypertrophic cardiomyopathy"},{"id":"c","text":"Mitral regurgitation"},{"id":"d","text":"Pulmonary embolism"}],"answerId":"a","explanation":"Aortic stenosis can present with similar symptoms due to left ventricular outflow obstruction and resultant heart failure.","kind":"integration","linkedModuleIds":["aortic-stenosis"],"origin":"ai"}],"acs-management":[{"id":"acs-management~ai-0","moduleId":"acs-management","stem":"What is the initial dose of aspirin recommended for an ACS patient?","options":[{"id":"a","text":"75 mg"},{"id":"b","text":"150–300 mg"},{"id":"c","text":"325 mg"},{"id":"d","text":"600 mg"}],"answerId":"b","explanation":"The initial dose of aspirin for ACS is 150–300 mg chewed to ensure rapid absorption.","kind":"recall","origin":"ai"},{"id":"acs-management~ai-1","moduleId":"acs-management","stem":"Which P2Y12 inhibitor is preferred if fibrinolysis is planned in STEMI?","options":[{"id":"a","text":"Ticagrelor"},{"id":"b","text":"Prasugrel"},{"id":"c","text":"Clopidogrel"},{"id":"d","text":"Abciximab"}],"answerId":"c","explanation":"Clopidogrel is the preferred P2Y12 inhibitor if fibrinolysis is planned.","kind":"recall","origin":"ai"},{"id":"acs-management~ai-2","moduleId":"acs-management","stem":"In a patient with inferior STEMI, what should be checked to assess for RV infarct?","options":[{"id":"a","text":"V1 lead"},{"id":"b","text":"V4 lead"},{"id":"c","text":"V4R lead"},{"id":"d","text":"V5 lead"}],"answerId":"c","explanation":"The V4R lead is used to assess for right ventricular infarction in inferior STEMI.","kind":"recall","origin":"ai"},{"id":"acs-management~ai-3","moduleId":"acs-management","stem":"What is the primary reason to avoid nitrates in inferior STEMI with RV infarct?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Decreased preload"},{"id":"c","text":"Increased blood pressure"},{"id":"d","text":"Decreased oxygen supply"}],"answerId":"b","explanation":"Nitrates decrease preload, which can lead to profound hypotension in patients with RV infarct.","kind":"mechanism","origin":"ai"},{"id":"acs-management~ai-4","moduleId":"acs-management","stem":"What is the primary goal of reperfusion therapy in STEMI?","options":[{"id":"a","text":"Reduce pain"},{"id":"b","text":"Increase heart rate"},{"id":"c","text":"Salvage myocardium"},{"id":"d","text":"Lower blood pressure"}],"answerId":"c","explanation":"The primary goal of reperfusion therapy is to salvage myocardium by restoring blood flow.","kind":"mechanism","origin":"ai"},{"id":"acs-management~ai-5","moduleId":"acs-management","stem":"A patient with ongoing ischemic pain presents within 12 hours of symptom onset. What is the best management?","options":[{"id":"a","text":"Immediate PCI"},{"id":"b","text":"Fibrinolysis"},{"id":"c","text":"Observation"},{"id":"d","text":"Nitrates"}],"answerId":"a","explanation":"Immediate PCI is preferred if achievable within 120 minutes for ongoing ischemic pain within 12 hours.","kind":"clinical","origin":"ai"},{"id":"acs-management~ai-6","moduleId":"acs-management","stem":"In a patient with ACS and SpO₂ <90%, what is the appropriate intervention?","options":[{"id":"a","text":"Administer high-flow oxygen"},{"id":"b","text":"Administer oxygen only if needed"},{"id":"c","text":"Do not administer oxygen"},{"id":"d","text":"Administer oxygen at all times"}],"answerId":"b","explanation":"Oxygen should only be administered if SpO₂ is <90% or if the patient is in respiratory distress.","kind":"trap","origin":"ai"},{"id":"acs-management~ai-7","moduleId":"acs-management","stem":"How does the management of ACS relate to cardiac biomarkers?","options":[{"id":"a","text":"Biomarkers are not relevant"},{"id":"b","text":"Biomarkers guide reperfusion therapy"},{"id":"c","text":"Biomarkers confirm diagnosis"},{"id":"d","text":"Biomarkers dictate medication choice"}],"answerId":"c","explanation":"Cardiac biomarkers are crucial for confirming the diagnosis of ACS and assessing myocardial injury.","kind":"integration","linkedModuleIds":["cardiac-biomarkers-acs"],"origin":"ai"},{"id":"acs-management~ai-8","moduleId":"acs-management","stem":"What is the relationship between ACS management and the ACS spectrum?","options":[{"id":"a","text":"ACS spectrum is unrelated to management"},{"id":"b","text":"Management varies by ACS type"},{"id":"c","text":"All ACS types require the same management"},{"id":"d","text":"ACS spectrum only includes STEMI"}],"answerId":"b","explanation":"Management strategies vary depending on the specific type of ACS within the spectrum.","kind":"integration","linkedModuleIds":["acs-spectrum"],"origin":"ai"}],"rheumatic-heart-disease":[{"id":"rheumatic-heart-disease~ai-0","moduleId":"rheumatic-heart-disease","stem":"Which organism is primarily responsible for rheumatic fever following pharyngitis?","options":[{"id":"a","text":"Staphylococcus aureus"},{"id":"b","text":"Group A β-hemolytic streptococcus"},{"id":"c","text":"Group B streptococcus"},{"id":"d","text":"Escherichia coli"}],"answerId":"b","explanation":"Rheumatic fever is a complication of infection with Group A β-hemolytic streptococcus following pharyngitis.","kind":"recall","origin":"ai"},{"id":"rheumatic-heart-disease~ai-1","moduleId":"rheumatic-heart-disease","stem":"What is the pathognomonic histological finding in acute rheumatic carditis?","options":[{"id":"a","text":"Aschoff bodies"},{"id":"b","text":"Anitschkow cells"},{"id":"c","text":"Fibrinous exudate"},{"id":"d","text":"Lymphocytic infiltration"}],"answerId":"a","explanation":"Aschoff bodies are granulomas found in the myocardium and are pathognomonic for acute rheumatic carditis.","kind":"recall","origin":"ai"},{"id":"rheumatic-heart-disease~ai-2","moduleId":"rheumatic-heart-disease","stem":"Which of the following is a major criterion for diagnosing rheumatic fever according to the Jones criteria?","options":[{"id":"a","text":"Fever"},{"id":"b","text":"Migratory polyarthritis"},{"id":"c","text":"Elevated ASO titer"},{"id":"d","text":"Subcutaneous nodules"}],"answerId":"b","explanation":"Migratory polyarthritis is one of the major criteria in the Jones criteria for diagnosing rheumatic fever.","kind":"recall","origin":"ai"},{"id":"rheumatic-heart-disease~ai-3","moduleId":"rheumatic-heart-disease","stem":"In rheumatic fever, what mechanism leads to cardiac damage?","options":[{"id":"a","text":"Direct bacterial invasion"},{"id":"b","text":"Type I hypersensitivity"},{"id":"c","text":"Type II hypersensitivity via molecular mimicry"},{"id":"d","text":"Autoantibody formation against cardiac tissue"}],"answerId":"c","explanation":"Rheumatic fever involves type II hypersensitivity due to molecular mimicry between streptococcal antigens and cardiac tissue.","kind":"mechanism","origin":"ai"},{"id":"rheumatic-heart-disease~ai-4","moduleId":"rheumatic-heart-disease","stem":"A patient presents with fever and a recent sore throat. Which finding is most indicative of rheumatic fever?","options":[{"id":"a","text":"Erythema marginatum"},{"id":"b","text":"Erythema nodosum"},{"id":"c","text":"Lichen planus"},{"id":"d","text":"Kawasaki disease"}],"answerId":"a","explanation":"Erythema marginatum is a characteristic skin manifestation of rheumatic fever.","kind":"clinical","origin":"ai"},{"id":"rheumatic-heart-disease~ai-5","moduleId":"rheumatic-heart-disease","stem":"What is the most common chronic complication of rheumatic fever?","options":[{"id":"a","text":"Aortic regurgitation"},{"id":"b","text":"Mitral stenosis"},{"id":"c","text":"Tricuspid regurgitation"},{"id":"d","text":"Pulmonary stenosis"}],"answerId":"b","explanation":"Mitral stenosis is the most common chronic complication following rheumatic fever.","kind":"recall","origin":"ai"},{"id":"rheumatic-heart-disease~ai-6","moduleId":"rheumatic-heart-disease","stem":"How does rheumatic fever relate to Group A streptococcus infections?","options":[{"id":"a","text":"It is caused by skin infections"},{"id":"b","text":"It follows pharyngeal infections"},{"id":"c","text":"It is unrelated to streptococcal infections"},{"id":"d","text":"It is a direct infection of the heart"}],"answerId":"b","explanation":"Rheumatic fever follows Group A β-hemolytic streptococcal pharyngitis, not skin infections.","kind":"trap","origin":"ai"},{"id":"rheumatic-heart-disease~ai-7","moduleId":"rheumatic-heart-disease","stem":"Which of the following findings is consistent with mitral stenosis in a patient with a history of rheumatic fever?","options":[{"id":"a","text":"Opening snap + mid-diastolic rumble"},{"id":"b","text":"Systolic ejection murmur"},{"id":"c","text":"Holosystolic murmur"},{"id":"d","text":"Diastolic murmur of aortic regurgitation"}],"answerId":"a","explanation":"Mitral stenosis is characterized by an opening snap followed by a mid-diastolic rumble.","kind":"clinical","linkedModuleIds":["mitral-stenosis"],"origin":"ai"},{"id":"rheumatic-heart-disease~ai-8","moduleId":"rheumatic-heart-disease","stem":"How does rheumatic fever relate to the mechanisms of autoimmunity?","options":[{"id":"a","text":"It is a direct autoimmune disease"},{"id":"b","text":"It involves molecular mimicry"},{"id":"c","text":"It is caused by environmental factors"},{"id":"d","text":"It does not involve immune mechanisms"}],"answerId":"b","explanation":"Rheumatic fever involves molecular mimicry, where antibodies against streptococcal antigens cross-react with cardiac tissue.","kind":"integration","linkedModuleIds":["tolerance-autoimmunity-mechanisms"],"origin":"ai"}],"mitral-valve-prolapse":[{"id":"mitral-valve-prolapse~ai-0","moduleId":"mitral-valve-prolapse","stem":"What is the most common valve abnormality associated with myxomatous degeneration?","options":[{"id":"a","text":"Aortic regurgitation"},{"id":"b","text":"Mitral valve prolapse"},{"id":"c","text":"Tricuspid regurgitation"},{"id":"d","text":"Pulmonary stenosis"}],"answerId":"b","explanation":"Mitral valve prolapse is the most common valve abnormality and is characterized by myxomatous degeneration leading to floppy leaflets.","kind":"recall","origin":"ai"},{"id":"mitral-valve-prolapse~ai-1","moduleId":"mitral-valve-prolapse","stem":"Which finding is characteristic of mitral valve prolapse during auscultation?","options":[{"id":"a","text":"Systolic ejection murmur"},{"id":"b","text":"Mid-systolic click"},{"id":"c","text":"Diastolic murmur"},{"id":"d","text":"Opening snap"}],"answerId":"b","explanation":"A mid-systolic click is a hallmark finding in mitral valve prolapse due to the sudden tensing of the prolapsing leaflet.","kind":"recall","origin":"ai"},{"id":"mitral-valve-prolapse~ai-2","moduleId":"mitral-valve-prolapse","stem":"How does standing or performing a Valsalva maneuver affect the click in mitral valve prolapse?","options":[{"id":"a","text":"Makes it softer"},{"id":"b","text":"Delays its occurrence"},{"id":"c","text":"Makes it earlier"},{"id":"d","text":"Eliminates it"}],"answerId":"c","explanation":"Decreased preload from standing or Valsalva leads to earlier prolapse, causing the click to occur sooner.","kind":"mechanism","origin":"ai"},{"id":"mitral-valve-prolapse~ai-3","moduleId":"mitral-valve-prolapse","stem":"Which genetic condition is most commonly associated with mitral valve prolapse?","options":[{"id":"a","text":"Cystic fibrosis"},{"id":"b","text":"Marfan syndrome"},{"id":"c","text":"Ehlers-Danlos syndrome"},{"id":"d","text":"Turner syndrome"}],"answerId":"b","explanation":"Mitral valve prolapse is frequently associated with Marfan syndrome, which involves a defect in fibrillin-1.","kind":"recall","origin":"ai"},{"id":"mitral-valve-prolapse~ai-4","moduleId":"mitral-valve-prolapse","stem":"A patient with mitral valve prolapse presents with sudden onset dyspnea. What complication should be considered?","options":[{"id":"a","text":"Aortic dissection"},{"id":"b","text":"Acute mitral regurgitation"},{"id":"c","text":"Pulmonary embolism"},{"id":"d","text":"Pericarditis"}],"answerId":"b","explanation":"Chordae rupture can occur in mitral valve prolapse, leading to acute mitral regurgitation and sudden dyspnea.","kind":"clinical","origin":"ai"},{"id":"mitral-valve-prolapse~ai-5","moduleId":"mitral-valve-prolapse","stem":"Which of the following is a trap regarding the genetic basis of mitral valve prolapse?","options":[{"id":"a","text":"It is caused by a beta-myosin mutation"},{"id":"b","text":"It is linked to fibrillin-1 mutation"},{"id":"c","text":"It is associated with a collagen type I defect"},{"id":"d","text":"It is due to a desmin mutation"}],"answerId":"b","explanation":"Mitral valve prolapse is associated with myxomatous degeneration linked to fibrillin-1 mutations in Marfan syndrome, not beta-myosin mutations.","kind":"trap","origin":"ai"},{"id":"mitral-valve-prolapse~ai-6","moduleId":"mitral-valve-prolapse","stem":"In a patient with mitral valve prolapse, what heart sound might you expect to hear during a physical exam?","options":[{"id":"a","text":"S3 gallop"},{"id":"b","text":"S4 gallop"},{"id":"c","text":"Mid-systolic click"},{"id":"d","text":"Continuous murmur"}],"answerId":"c","explanation":"A mid-systolic click is expected in mitral valve prolapse due to the sudden tensing of the prolapsing leaflet.","kind":"recall","origin":"ai"},{"id":"mitral-valve-prolapse~ai-7","moduleId":"mitral-valve-prolapse","stem":"How does mitral valve prolapse relate to the risk of infective endocarditis?","options":[{"id":"a","text":"It increases risk due to turbulent flow"},{"id":"b","text":"It decreases risk due to valve rigidity"},{"id":"c","text":"It has no relation"},{"id":"d","text":"It increases risk due to valve calcification"}],"answerId":"a","explanation":"Mitral valve prolapse can lead to turbulent flow, which increases the risk of infective endocarditis.","kind":"integration","linkedModuleIds":["infective-endocarditis"],"origin":"ai"},{"id":"mitral-valve-prolapse~ai-8","moduleId":"mitral-valve-prolapse","stem":"What is the relationship between mitral valve prolapse and heart sounds during auscultation?","options":[{"id":"a","text":"Both produce a diastolic murmur"},{"id":"b","text":"Both are characterized by a mid-systolic click"},{"id":"c","text":"Both are associated with a loud S1"},{"id":"d","text":"Both produce a continuous murmur"}],"answerId":"b","explanation":"Mitral valve prolapse is characterized by a mid-systolic click, which is a key auscultation finding.","kind":"integration","linkedModuleIds":["heart-sounds-murmurs-auscultation"],"origin":"ai"}],"scai-shock-classification":[{"id":"scai-shock-classification~ai-0","moduleId":"scai-shock-classification","stem":"What is the primary characteristic of SCAI Stage A shock?","options":[{"id":"a","text":"Altered mentation"},{"id":"b","text":"Hypotension and tachycardia"},{"id":"c","text":"No signs of hypoperfusion"},{"id":"d","text":"Cold and mottled skin"}],"answerId":"c","explanation":"Stage A shock is defined as 'At risk' with no signs of hypoperfusion.","kind":"recall","origin":"ai"},{"id":"scai-shock-classification~ai-1","moduleId":"scai-shock-classification","stem":"In SCAI shock classification, which stage is characterized by lactate levels greater than 2?","options":[{"id":"a","text":"Stage A"},{"id":"b","text":"Stage B"},{"id":"c","text":"Stage C"},{"id":"d","text":"Stage D"}],"answerId":"c","explanation":"Lactate >2 indicates hypoperfusion, which is characteristic of Stage C shock.","kind":"recall","origin":"ai"},{"id":"scai-shock-classification~ai-2","moduleId":"scai-shock-classification","stem":"What is the expected mortality rate in SCAI Stage E shock?","options":[{"id":"a","text":"~0.6%"},{"id":"b","text":"~21%"},{"id":"c","text":"~50%"},{"id":"d","text":"~90%"}],"answerId":"d","explanation":"Stage E shock has a mortality rate of approximately 90%.","kind":"recall","origin":"ai"},{"id":"scai-shock-classification~ai-3","moduleId":"scai-shock-classification","stem":"Which finding indicates a patient is in SCAI Stage C shock?","options":[{"id":"a","text":"Normal lactate and warm skin"},{"id":"b","text":"Lactate >2 and altered mentation"},{"id":"c","text":"Hypotension without hypoperfusion"},{"id":"d","text":"Cold extremities with normal mentation"}],"answerId":"b","explanation":"Stage C shock is characterized by hypoperfusion markers such as lactate >2 and altered mentation.","kind":"clinical","origin":"ai"},{"id":"scai-shock-classification~ai-4","moduleId":"scai-shock-classification","stem":"A patient presents with hypotension but normal lactate and mentation. What is the SCAI stage?","options":[{"id":"a","text":"Stage A"},{"id":"b","text":"Stage B"},{"id":"c","text":"Stage C"},{"id":"d","text":"Stage D"}],"answerId":"b","explanation":"This presentation indicates Stage B shock, where there is hemodynamic instability without hypoperfusion.","kind":"trap","origin":"ai"},{"id":"scai-shock-classification~ai-5","moduleId":"scai-shock-classification","stem":"How does cardiogenic shock relate to SCAI shock classification?","options":[{"id":"a","text":"It is a type of Stage A shock"},{"id":"b","text":"It can progress through SCAI stages"},{"id":"c","text":"It is unrelated to SCAI classification"},{"id":"d","text":"It only occurs in Stage E shock"}],"answerId":"b","explanation":"Cardiogenic shock can progress through the SCAI stages based on severity and hypoperfusion.","kind":"integration","linkedModuleIds":["cardiogenic-shock"],"origin":"ai"},{"id":"scai-shock-classification~ai-6","moduleId":"scai-shock-classification","stem":"What is the significance of lactate levels in the context of shock classification?","options":[{"id":"a","text":"They indicate the presence of Stage A shock"},{"id":"b","text":"They help differentiate between stages of shock"},{"id":"c","text":"They are irrelevant in shock classification"},{"id":"d","text":"They only indicate Stage E shock"}],"answerId":"b","explanation":"Lactate levels are crucial for differentiating between the stages of shock, particularly indicating hypoperfusion.","kind":"integration","linkedModuleIds":["infarction-shock"],"origin":"ai"}],"hfref-systolic":[{"id":"hfref-systolic~ai-0","moduleId":"hfref-systolic","stem":"What is the primary mechanism leading to heart failure with reduced ejection fraction (HFrEF)?","options":[{"id":"a","text":"Increased preload"},{"id":"b","text":"Neurohormonal activation"},{"id":"c","text":"Decreased afterload"},{"id":"d","text":"Increased contractility"}],"answerId":"b","explanation":"Neurohormonal activation drives maladaptive remodeling in HFrEF, leading to worsening heart function.","kind":"mechanism","origin":"ai"},{"id":"hfref-systolic~ai-1","moduleId":"hfref-systolic","stem":"Which of the following findings is most characteristic of HFrEF during physical examination?","options":[{"id":"a","text":"S4 gallop"},{"id":"b","text":"S3 gallop"},{"id":"c","text":"Muffled heart sounds"},{"id":"d","text":"Pulsus paradoxus"}],"answerId":"b","explanation":"An S3 gallop is indicative of volume overload and is commonly heard in patients with HFrEF.","kind":"recall","origin":"ai"},{"id":"hfref-systolic~ai-2","moduleId":"hfref-systolic","stem":"Which treatment is considered the cornerstone of therapy for HFrEF?","options":[{"id":"a","text":"Calcium channel blockers"},{"id":"b","text":"ACE inhibitors"},{"id":"c","text":"Diuretics"},{"id":"d","text":"Digoxin"}],"answerId":"b","explanation":"ACE inhibitors are essential in HFrEF management as they block maladaptive neurohormonal activation.","kind":"recall","origin":"ai"},{"id":"hfref-systolic~ai-3","moduleId":"hfref-systolic","stem":"Why is chronic activation of the RAAS and sympathetic nervous system considered maladaptive in HFrEF?","options":[{"id":"a","text":"They improve cardiac output"},{"id":"b","text":"They maintain blood pressure acutely"},{"id":"c","text":"They lead to cardiac remodeling"},{"id":"d","text":"They enhance diastolic function"}],"answerId":"c","explanation":"Chronic activation of RAAS and SNS contributes to cardiac remodeling and progression of heart failure.","kind":"trap","origin":"ai"},{"id":"hfref-systolic~ai-4","moduleId":"hfref-systolic","stem":"In HFrEF, which biomarker is primarily used to assess myocardial stretch?","options":[{"id":"a","text":"Troponin"},{"id":"b","text":"Creatinine"},{"id":"c","text":"BNP"},{"id":"d","text":"C-reactive protein"}],"answerId":"c","explanation":"BNP levels rise due to myocardial stretch in heart failure and are used for diagnosis and prognosis.","kind":"recall","origin":"ai"},{"id":"hfref-systolic~ai-5","moduleId":"hfref-systolic","stem":"How does HFrEF differ from HFpEF in terms of ejection fraction?","options":[{"id":"a","text":"HFrEF has EF > 40%"},{"id":"b","text":"HFpEF has EF < 40%"},{"id":"c","text":"HFrEF has EF < 40%"},{"id":"d","text":"HFpEF has EF = 40%"}],"answerId":"c","explanation":"HFrEF is characterized by an ejection fraction of 40% or less due to impaired contractility.","kind":"integration","linkedModuleIds":["hfpef-diastolic"],"origin":"ai"},{"id":"hfref-systolic~ai-6","moduleId":"hfref-systolic","stem":"Which of the following findings would be more pronounced in right-sided heart failure compared to HFrEF?","options":[{"id":"a","text":"Pulmonary congestion"},{"id":"b","text":"Peripheral edema"},{"id":"c","text":"S3 gallop"},{"id":"d","text":"Increased BNP"}],"answerId":"b","explanation":"Peripheral edema is a hallmark of right-sided heart failure, often more prominent than in HFrEF.","kind":"integration","linkedModuleIds":["right-sided-hf"],"origin":"ai"}],"myocarditis":[{"id":"myocarditis~ai-0","moduleId":"myocarditis","stem":"What is the most common viral cause of myocarditis?","options":[{"id":"a","text":"Coxsackie B virus"},{"id":"b","text":"HIV"},{"id":"c","text":"CMV"},{"id":"d","text":"Influenza virus"}],"answerId":"a","explanation":"Coxsackie B virus is the most common viral agent associated with myocarditis.","kind":"recall","origin":"ai"},{"id":"myocarditis~ai-1","moduleId":"myocarditis","stem":"Which histological finding is most commonly associated with myocarditis?","options":[{"id":"a","text":"Eosinophilic infiltration"},{"id":"b","text":"Lymphocytic infiltration"},{"id":"c","text":"Giant cell formation"},{"id":"d","text":"Fibrosis"}],"answerId":"b","explanation":"Lymphocytic infiltration is the most common histological finding in myocarditis.","kind":"recall","origin":"ai"},{"id":"myocarditis~ai-2","moduleId":"myocarditis","stem":"In myocarditis, how does the troponin elevation pattern differ from that of acute myocardial infarction (AMI)?","options":[{"id":"a","text":"Troponin rises and falls sharply"},{"id":"b","text":"Troponin rises slower and stays elevated longer"},{"id":"c","text":"Troponin is not elevated"},{"id":"d","text":"Troponin levels are always normal"}],"answerId":"b","explanation":"In myocarditis, troponin rises slower and remains elevated longer compared to the sharp rise-and-fall pattern seen in AMI.","kind":"trap","origin":"ai"},{"id":"myocarditis~ai-3","moduleId":"myocarditis","stem":"A patient presents with tachycardia out of proportion to fever. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Increased metabolic demand"},{"id":"b","text":"Myocardial irritation"},{"id":"c","text":"Dehydration"},{"id":"d","text":"Anxiety"}],"answerId":"b","explanation":"Tachycardia out of proportion to fever in myocarditis is primarily due to myocardial irritation.","kind":"clinical","origin":"ai"},{"id":"myocarditis~ai-4","moduleId":"myocarditis","stem":"Which of the following is the gold standard for diagnosing myocarditis?","options":[{"id":"a","text":"Echocardiogram"},{"id":"b","text":"Endomyocardial biopsy"},{"id":"c","text":"Cardiac MRI"},{"id":"d","text":"Troponin levels"}],"answerId":"b","explanation":"Endomyocardial biopsy is considered the gold standard for diagnosing myocarditis despite the risk of sampling error.","kind":"recall","origin":"ai"},{"id":"myocarditis~ai-5","moduleId":"myocarditis","stem":"How does myocarditis relate to cardiomyopathy?","options":[{"id":"a","text":"It is a type of restrictive cardiomyopathy"},{"id":"b","text":"It can lead to dilated cardiomyopathy"},{"id":"c","text":"It is always asymptomatic"},{"id":"d","text":"It is unrelated to cardiomyopathy"}],"answerId":"b","explanation":"Myocarditis can lead to dilated cardiomyopathy due to ongoing myocardial inflammation and injury.","kind":"integration","linkedModuleIds":["cardiomyopathy-overview"],"origin":"ai"},{"id":"myocarditis~ai-6","moduleId":"myocarditis","stem":"Which of the following findings would suggest myocarditis rather than arrhythmogenic right ventricular cardiomyopathy (ARVC)?","options":[{"id":"a","text":"Family history of sudden cardiac death"},{"id":"b","text":"Tachycardia out of proportion to fever"},{"id":"c","text":"Right ventricular dilation"},{"id":"d","text":"Ventricular arrhythmias"}],"answerId":"b","explanation":"Tachycardia out of proportion to fever is more indicative of myocarditis, while ARVC typically presents with structural changes and familial patterns.","kind":"integration","linkedModuleIds":["arvc"],"origin":"ai"}],"cardiac-arrest":[{"id":"cardiac-arrest~ai-0","moduleId":"cardiac-arrest","stem":"What is the primary goal in the management of cardiac arrest?","options":[{"id":"a","text":"Defibrillate immediately"},{"id":"b","text":"Identify and treat reversible causes"},{"id":"c","text":"Administer high-dose epinephrine"},{"id":"d","text":"Perform intubation"}],"answerId":"b","explanation":"The primary goal is to identify and treat reversible causes while providing high-quality CPR.","kind":"recall","origin":"ai"},{"id":"cardiac-arrest~ai-1","moduleId":"cardiac-arrest","stem":"Which of the following is a reversible cause of cardiac arrest?","options":[{"id":"a","text":"Hypovolemia"},{"id":"b","text":"Aortic dissection"},{"id":"c","text":"Myocardial hypertrophy"},{"id":"d","text":"Sepsis"}],"answerId":"a","explanation":"Hypovolemia is one of the 5 H's that can lead to cardiac arrest and is reversible.","kind":"recall","origin":"ai"},{"id":"cardiac-arrest~ai-2","moduleId":"cardiac-arrest","stem":"In a patient with tension pneumothorax, which clinical finding is most likely?","options":[{"id":"a","text":"Bradycardia"},{"id":"b","text":"Distended neck veins"},{"id":"c","text":"Hypotension"},{"id":"d","text":"Fever"}],"answerId":"b","explanation":"Distended neck veins are a classic sign of tension pneumothorax due to increased intrathoracic pressure.","kind":"recall","origin":"ai"},{"id":"cardiac-arrest~ai-3","moduleId":"cardiac-arrest","stem":"What is the appropriate management for a patient in asystole?","options":[{"id":"a","text":"Defibrillation"},{"id":"b","text":"High-dose epinephrine"},{"id":"c","text":"CPR and epinephrine"},{"id":"d","text":"Immediate intubation"}],"answerId":"c","explanation":"The correct management for asystole is CPR and epinephrine; defibrillation is not indicated.","kind":"trap","origin":"ai"},{"id":"cardiac-arrest~ai-4","moduleId":"cardiac-arrest","stem":"Which of the following mechanisms leads to cardiac arrest in hypoxia?","options":[{"id":"a","text":"Decreased myocardial contractility"},{"id":"b","text":"Increased systemic vascular resistance"},{"id":"c","text":"Decreased oxygen delivery to tissues"},{"id":"d","text":"Increased heart rate"}],"answerId":"c","explanation":"Hypoxia leads to decreased oxygen delivery to tissues, which can result in cardiac arrest.","kind":"mechanism","origin":"ai"},{"id":"cardiac-arrest~ai-5","moduleId":"cardiac-arrest","stem":"How does cardiac arrest relate to cellular injury mechanisms?","options":[{"id":"a","text":"Increased ATP production"},{"id":"b","text":"Cellular apoptosis"},{"id":"c","text":"Reversible cellular injury"},{"id":"d","text":"Necrosis due to ischemia"}],"answerId":"d","explanation":"Cardiac arrest leads to ischemia, which can result in necrosis of cardiac cells due to lack of oxygen and nutrients.","kind":"integration","linkedModuleIds":["cell-injury-mechanisms"],"origin":"ai"},{"id":"cardiac-arrest~ai-6","moduleId":"cardiac-arrest","stem":"What is a common consequence of cardiac arrest that may lead to cardiogenic shock?","options":[{"id":"a","text":"Increased stroke volume"},{"id":"b","text":"Myocardial ischemia"},{"id":"c","text":"Decreased systemic vascular resistance"},{"id":"d","text":"Increased heart rate"}],"answerId":"b","explanation":"Myocardial ischemia is a common consequence of cardiac arrest that can lead to cardiogenic shock.","kind":"integration","linkedModuleIds":["cardiogenic-shock"],"origin":"ai"}],"antianginal-principles":[{"id":"antianginal-principles~ai-0","moduleId":"antianginal-principles","stem":"What is the primary mechanism by which antianginal drugs alleviate angina?","options":[{"id":"a","text":"Increase oxygen supply"},{"id":"b","text":"Reduce oxygen demand"},{"id":"c","text":"Enhance myocardial contractility"},{"id":"d","text":"Decrease heart rate variability"}],"answerId":"b","explanation":"Antianginal drugs primarily work by reducing oxygen demand, which is influenced by preload, afterload, heart rate, and contractility.","kind":"mechanism","origin":"ai"},{"id":"antianginal-principles~ai-1","moduleId":"antianginal-principles","stem":"Which type of angina is characterized by chest pain that occurs at rest and is relieved by nitrates?","options":[{"id":"a","text":"Chronic stable angina"},{"id":"b","text":"Prinzmetal angina"},{"id":"c","text":"Unstable angina"},{"id":"d","text":"Silent ischemia"}],"answerId":"b","explanation":"Prinzmetal angina is caused by coronary vasospasm and typically presents with rest pain that is relieved by nitrates.","kind":"recall","origin":"ai"},{"id":"antianginal-principles~ai-2","moduleId":"antianginal-principles","stem":"A patient with chronic stable angina is experiencing increased frequency of chest pain. Which medication should be added for immediate relief?","options":[{"id":"a","text":"Long-acting beta-blocker"},{"id":"b","text":"Short-acting nitrate"},{"id":"c","text":"Calcium channel blocker"},{"id":"d","text":"Statin"}],"answerId":"b","explanation":"Short-acting nitrates are recommended for immediate relief of angina symptoms.","kind":"clinical","origin":"ai"},{"id":"antianginal-principles~ai-3","moduleId":"antianginal-principles","stem":"Which of the following is a determinant of oxygen demand that antianginal drugs primarily target?","options":[{"id":"a","text":"Coronary artery diameter"},{"id":"b","text":"Heart rate"},{"id":"c","text":"Myocardial oxygen extraction"},{"id":"d","text":"Coronary blood flow"}],"answerId":"b","explanation":"Antianginal drugs primarily reduce oxygen demand by lowering heart rate, preload, afterload, and contractility.","kind":"trap","origin":"ai"},{"id":"antianginal-principles~ai-4","moduleId":"antianginal-principles","stem":"In a patient with vasospastic angina, which class of medication is considered first-line treatment?","options":[{"id":"a","text":"Beta-blockers"},{"id":"b","text":"Calcium channel blockers"},{"id":"c","text":"Organic nitrates"},{"id":"d","text":"ACE inhibitors"}],"answerId":"b","explanation":"Calcium channel blockers are the first-line treatment for vasospastic angina due to their ability to relieve coronary vasospasm.","kind":"recall","origin":"ai"},{"id":"antianginal-principles~ai-5","moduleId":"antianginal-principles","stem":"How do beta-blockers contribute to the management of chronic stable angina?","options":[{"id":"a","text":"Increase myocardial oxygen supply"},{"id":"b","text":"Decrease heart rate and contractility"},{"id":"c","text":"Enhance coronary blood flow"},{"id":"d","text":"Prevent coronary artery spasm"}],"answerId":"b","explanation":"Beta-blockers primarily decrease heart rate and contractility, thereby reducing myocardial oxygen demand.","kind":"integration","linkedModuleIds":["beta-blockers-ccb-angina"],"origin":"ai"},{"id":"antianginal-principles~ai-6","moduleId":"antianginal-principles","stem":"Which of the following is a common side effect of organic nitrates used in angina management?","options":[{"id":"a","text":"Bradycardia"},{"id":"b","text":"Hypotension"},{"id":"c","text":"Constipation"},{"id":"d","text":"Hyperglycemia"}],"answerId":"b","explanation":"Hypotension is a common side effect of organic nitrates due to their vasodilatory effects.","kind":"integration","linkedModuleIds":["organic-nitrates"],"origin":"ai"}],"heart-failure-overview":[{"id":"heart-failure-overview~ai-0","moduleId":"heart-failure-overview","stem":"What is the primary characteristic of heart failure with preserved ejection fraction (HFpEF)?","options":[{"id":"a","text":"Low ejection fraction"},{"id":"b","text":"Diastolic dysfunction"},{"id":"c","text":"Systolic dysfunction"},{"id":"d","text":"Increased heart rate"}],"answerId":"b","explanation":"HFpEF is characterized by a preserved ejection fraction (≥50%) with impaired filling due to diastolic dysfunction.","kind":"recall","origin":"ai"},{"id":"heart-failure-overview~ai-1","moduleId":"heart-failure-overview","stem":"Which of the following findings is most indicative of backward failure in heart failure?","options":[{"id":"a","text":"Fatigue"},{"id":"b","text":"Pulmonary rales"},{"id":"c","text":"Decreased cardiac output"},{"id":"d","text":"Increased heart rate"}],"answerId":"b","explanation":"Pulmonary rales indicate pulmonary congestion, a hallmark of backward failure due to venous congestion.","kind":"clinical","origin":"ai"},{"id":"heart-failure-overview~ai-2","moduleId":"heart-failure-overview","stem":"In heart failure, what does the term 'forward failure' primarily refer to?","options":[{"id":"a","text":"Increased venous pressure"},{"id":"b","text":"Fatigue and hypoperfusion"},{"id":"c","text":"Pulmonary congestion"},{"id":"d","text":"Edema and ascites"}],"answerId":"b","explanation":"Forward failure refers to decreased cardiac output leading to symptoms like fatigue and hypoperfusion.","kind":"mechanism","origin":"ai"},{"id":"heart-failure-overview~ai-3","moduleId":"heart-failure-overview","stem":"Which of the following is a common sign of heart failure?","options":[{"id":"a","text":"Bradycardia"},{"id":"b","text":"Hypotension"},{"id":"c","text":"Displaced apex beat"},{"id":"d","text":"Normal JVP"}],"answerId":"c","explanation":"A displaced apex beat is indicative of ventricular dysfunction commonly seen in heart failure.","kind":"recall","origin":"ai"},{"id":"heart-failure-overview~ai-4","moduleId":"heart-failure-overview","stem":"What is a common misconception regarding heart failure with preserved ejection fraction (HFpEF)?","options":[{"id":"a","text":"It has a low ejection fraction"},{"id":"b","text":"It is associated with diastolic dysfunction"},{"id":"c","text":"It can present with pulmonary congestion"},{"id":"d","text":"It is a type of heart failure"}],"answerId":"a","explanation":"A common misconception is that all heart failure presents with a low ejection fraction; HFpEF has a preserved EF.","kind":"trap","origin":"ai"},{"id":"heart-failure-overview~ai-5","moduleId":"heart-failure-overview","stem":"How does heart failure relate to esophageal motility disorders?","options":[{"id":"a","text":"Both can cause peripheral edema"},{"id":"b","text":"Both involve impaired muscle function"},{"id":"c","text":"Both are primarily caused by ischemia"},{"id":"d","text":"Both lead to increased heart rate"}],"answerId":"b","explanation":"Heart failure and esophageal motility disorders both involve impaired muscle function, affecting their respective systems.","kind":"integration","linkedModuleIds":["esophageal-peristalsis-sphincters"],"origin":"ai"},{"id":"heart-failure-overview~ai-6","moduleId":"heart-failure-overview","stem":"What is the relationship between heart failure and diastolic dysfunction in the context of HFpEF?","options":[{"id":"a","text":"HFpEF is caused by systolic dysfunction"},{"id":"b","text":"Diastolic dysfunction leads to preserved ejection fraction"},{"id":"c","text":"Diastolic dysfunction is not present in HFpEF"},{"id":"d","text":"HFpEF is unrelated to cardiac output"}],"answerId":"b","explanation":"In HFpEF, diastolic dysfunction occurs while maintaining a preserved ejection fraction, affecting filling rather than pumping.","kind":"integration","linkedModuleIds":["hfpef-diastolic"],"origin":"ai"}],"cardiogenic-shock":[{"id":"cardiogenic-shock~ai-0","moduleId":"cardiogenic-shock","stem":"What is the primary mechanism of cardiogenic shock?","options":[{"id":"a","text":"Increased vascular resistance"},{"id":"b","text":"Decreased cardiac output"},{"id":"c","text":"Increased blood volume"},{"id":"d","text":"Decreased systemic vascular resistance"}],"answerId":"b","explanation":"Cardiogenic shock is characterized by pump failure leading to decreased cardiac output.","kind":"mechanism","origin":"ai"},{"id":"cardiogenic-shock~ai-1","moduleId":"cardiogenic-shock","stem":"Which of the following is a common cause of cardiogenic shock?","options":[{"id":"a","text":"Severe dehydration"},{"id":"b","text":"Myocardial infarction"},{"id":"c","text":"Septicemia"},{"id":"d","text":"Anaphylaxis"}],"answerId":"b","explanation":"Myocardial infarction is the most common cause of cardiogenic shock due to impaired heart contraction.","kind":"recall","origin":"ai"},{"id":"cardiogenic-shock~ai-2","moduleId":"cardiogenic-shock","stem":"A patient presents with cold, clammy skin and hypotension. Which additional finding would most likely indicate cardiogenic shock?","options":[{"id":"a","text":"Increased urine output"},{"id":"b","text":"Elevated jugular venous pressure"},{"id":"c","text":"Warm extremities"},{"id":"d","text":"Bradycardia"}],"answerId":"b","explanation":"Elevated jugular venous pressure indicates congestion, which is characteristic of cardiogenic shock.","kind":"clinical","origin":"ai"},{"id":"cardiogenic-shock~ai-3","moduleId":"cardiogenic-shock","stem":"In cardiogenic shock, which of the following findings is expected?","options":[{"id":"a","text":"High urine output"},{"id":"b","text":"Warm, dry skin"},{"id":"c","text":"Altered mentation"},{"id":"d","text":"Bradycardia"}],"answerId":"c","explanation":"Altered mentation occurs due to end-organ hypoperfusion in cardiogenic shock.","kind":"recall","origin":"ai"},{"id":"cardiogenic-shock~ai-4","moduleId":"cardiogenic-shock","stem":"A patient with cardiogenic shock is likely to exhibit which of the following?","options":[{"id":"a","text":"Increased stroke volume"},{"id":"b","text":"Decreased heart rate"},{"id":"c","text":"Cold and clammy skin"},{"id":"d","text":"Increased blood pressure"}],"answerId":"c","explanation":"Cold and clammy skin results from intense vasoconstriction and low cardiac output.","kind":"trap","origin":"ai"},{"id":"cardiogenic-shock~ai-5","moduleId":"cardiogenic-shock","stem":"How does cardiogenic shock differ from hypovolemic shock?","options":[{"id":"a","text":"Both have high filling pressures"},{"id":"b","text":"Both present with warm skin"},{"id":"c","text":"Cardiogenic shock has congestion"},{"id":"d","text":"Hypovolemic shock has high cardiac output"}],"answerId":"c","explanation":"Cardiogenic shock presents with congestion (e.g., elevated JVP), while hypovolemic shock does not.","kind":"trap","origin":"ai"},{"id":"cardiogenic-shock~ai-6","moduleId":"cardiogenic-shock","stem":"In the context of cardiogenic shock, which classification is most relevant for determining treatment options?","options":[{"id":"a","text":"SCAI Shock Classification"},{"id":"b","text":"New York Heart Association Classification"},{"id":"c","text":"Killip Classification"},{"id":"d","text":"American College of Cardiology Classification"}],"answerId":"a","explanation":"The SCAI Shock Classification helps in assessing the severity and guiding management of shock states.","kind":"integration","linkedModuleIds":["scai-shock-classification"],"origin":"ai"},{"id":"cardiogenic-shock~ai-7","moduleId":"cardiogenic-shock","stem":"Which condition must be ruled out when diagnosing cardiogenic shock?","options":[{"id":"a","text":"Pulmonary embolism"},{"id":"b","text":"Acute kidney injury"},{"id":"c","text":"Sepsis"},{"id":"d","text":"Chronic obstructive pulmonary disease"}],"answerId":"a","explanation":"Pulmonary embolism can cause similar symptoms and must be differentiated from cardiogenic shock.","kind":"integration","linkedModuleIds":["cardiac-arrest"],"origin":"ai"}],"beta-blockers-ccb-angina":[{"id":"beta-blockers-ccb-angina~ai-0","moduleId":"beta-blockers-ccb-angina","stem":"What is the primary mechanism by which beta-blockers reduce myocardial oxygen demand?","options":[{"id":"a","text":"Decrease heart rate and contractility"},{"id":"b","text":"Increase diastolic perfusion time"},{"id":"c","text":"Decrease afterload"},{"id":"d","text":"Increase oxygen supply"}],"answerId":"a","explanation":"Beta-blockers primarily reduce myocardial oxygen demand by decreasing heart rate and contractility.","kind":"mechanism","origin":"ai"},{"id":"beta-blockers-ccb-angina~ai-1","moduleId":"beta-blockers-ccb-angina","stem":"Which of the following is a common side effect of dihydropyridine calcium channel blockers?","options":[{"id":"a","text":"Bradycardia"},{"id":"b","text":"Constipation"},{"id":"c","text":"Flushing"},{"id":"d","text":"AV block"}],"answerId":"c","explanation":"Dihydropyridine calcium channel blockers, such as nifedipine, commonly cause flushing due to their potent vasodilatory effects.","kind":"recall","origin":"ai"},{"id":"beta-blockers-ccb-angina~ai-2","moduleId":"beta-blockers-ccb-angina","stem":"In a patient with vasospastic angina, which medication is contraindicated?","options":[{"id":"a","text":"Amlodipine"},{"id":"b","text":"Verapamil"},{"id":"c","text":"Propranolol"},{"id":"d","text":"Nitroglycerin"}],"answerId":"c","explanation":"Beta-blockers like propranolol can worsen vasospasm in vasospastic angina by leaving unopposed alpha-mediated vasoconstriction.","kind":"trap","origin":"ai"},{"id":"beta-blockers-ccb-angina~ai-3","moduleId":"beta-blockers-ccb-angina","stem":"Which combination of medications is most appropriate for a patient with chronic stable angina who experiences reflex tachycardia on a dihydropyridine calcium channel blocker?","options":[{"id":"a","text":"Beta-blocker alone"},{"id":"b","text":"DHP CCB alone"},{"id":"c","text":"Non-DHP CCB alone"},{"id":"d","text":"Beta-blocker + DHP CCB"}],"answerId":"d","explanation":"Combining a beta-blocker with a DHP CCB can mitigate the reflex tachycardia caused by the DHP.","kind":"clinical","origin":"ai"},{"id":"beta-blockers-ccb-angina~ai-4","moduleId":"beta-blockers-ccb-angina","stem":"How do non-dihydropyridine calcium channel blockers differ from dihydropyridine CCBs?","options":[{"id":"a","text":"They only decrease afterload"},{"id":"b","text":"They decrease heart rate and contractility"},{"id":"c","text":"They cause more peripheral edema"},{"id":"d","text":"They are less effective in angina"}],"answerId":"b","explanation":"Non-DHP CCBs like verapamil and diltiazem decrease heart rate and contractility, unlike DHPs which primarily cause vasodilation.","kind":"mechanism","origin":"ai"},{"id":"beta-blockers-ccb-angina~ai-5","moduleId":"beta-blockers-ccb-angina","stem":"A patient with chronic stable angina is also suffering from migraines. Which medication could serve both purposes?","options":[{"id":"a","text":"Propranolol"},{"id":"b","text":"Amlodipine"},{"id":"c","text":"Nitroglycerin"},{"id":"d","text":"Verapamil"}],"answerId":"a","explanation":"Propranolol is effective for both chronic stable angina and migraine prophylaxis.","kind":"integration","linkedModuleIds":["migraine-prophylaxis"],"origin":"ai"},{"id":"beta-blockers-ccb-angina~ai-6","moduleId":"beta-blockers-ccb-angina","stem":"Which hemodynamic change is primarily targeted by calcium channel blockers in the management of angina?","options":[{"id":"a","text":"Increased preload"},{"id":"b","text":"Decreased afterload"},{"id":"c","text":"Increased cardiac output"},{"id":"d","text":"Decreased heart rate"}],"answerId":"b","explanation":"Calcium channel blockers primarily decrease afterload, which reduces myocardial oxygen demand.","kind":"integration","linkedModuleIds":["hemodynamics-preload-afterload-cardiac-output"],"origin":"ai"}],"organic-nitrates":[{"id":"organic-nitrates~ai-0","moduleId":"organic-nitrates","stem":"What is the primary mechanism of action of organic nitrates in treating angina?","options":[{"id":"a","text":"Inhibition of platelet aggregation"},{"id":"b","text":"Increased myocardial oxygen supply"},{"id":"c","text":"Conversion to nitric oxide leading to increased cGMP"},{"id":"d","text":"Direct vasoconstriction of coronary arteries"}],"answerId":"c","explanation":"Organic nitrates are converted to nitric oxide, which increases cGMP levels, leading to vasodilation and decreased preload.","kind":"mechanism","origin":"ai"},{"id":"organic-nitrates~ai-1","moduleId":"organic-nitrates","stem":"Which of the following is a common side effect of nitrates?","options":[{"id":"a","text":"Bradycardia"},{"id":"b","text":"Hypokalemia"},{"id":"c","text":"Headache"},{"id":"d","text":"Hypertension"}],"answerId":"c","explanation":"Headache is a common side effect due to systemic vasodilation caused by nitrates.","kind":"recall","origin":"ai"},{"id":"organic-nitrates~ai-2","moduleId":"organic-nitrates","stem":"A patient experiences relief of anginal pain within minutes after taking sublingual nitroglycerin. What is the underlying mechanism?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Rapid venodilation"},{"id":"c","text":"Decreased myocardial contractility"},{"id":"d","text":"Increased coronary blood flow"}],"answerId":"b","explanation":"Sublingual nitroglycerin causes rapid venodilation, which relieves anginal pain.","kind":"clinical","origin":"ai"},{"id":"organic-nitrates~ai-3","moduleId":"organic-nitrates","stem":"Which statement regarding the use of nitrates is FALSE?","options":[{"id":"a","text":"Nitrates can cause reflex tachycardia."},{"id":"b","text":"Nitrates should be used with PDE5 inhibitors for angina."},{"id":"c","text":"Nitrates require a nitrate-free interval to prevent tolerance."},{"id":"d","text":"Nitrates predominantly relax large veins."}],"answerId":"b","explanation":"It is FALSE that nitrates can be used with PDE5 inhibitors; this combination can lead to severe hypotension.","kind":"trap","origin":"ai"},{"id":"organic-nitrates~ai-4","moduleId":"organic-nitrates","stem":"What is the effect of organic nitrates on venous capacitance?","options":[{"id":"a","text":"Increases venous capacitance"},{"id":"b","text":"Decreases venous capacitance"},{"id":"c","text":"No effect on venous capacitance"},{"id":"d","text":"Increases arterial capacitance"}],"answerId":"a","explanation":"Organic nitrates increase venous capacitance by causing venodilation, which decreases preload.","kind":"recall","origin":"ai"},{"id":"organic-nitrates~ai-5","moduleId":"organic-nitrates","stem":"How do nitrates interact with PDE5 inhibitors, and what is the clinical significance?","options":[{"id":"a","text":"Both increase cGMP, leading to severe hypotension"},{"id":"b","text":"Both decrease cGMP, leading to increased blood pressure"},{"id":"c","text":"Both have no interaction"},{"id":"d","text":"Both cause reflex tachycardia"}],"answerId":"a","explanation":"Nitrates and PDE5 inhibitors both increase cGMP, leading to profound vasodilation and potentially life-threatening hypotension.","kind":"integration","linkedModuleIds":["hrp1-erectile-physiology-evaluation"],"origin":"ai"},{"id":"organic-nitrates~ai-6","moduleId":"organic-nitrates","stem":"In a patient with coronary artery disease, which medication would be contraindicated if they are taking nitrates?","options":[{"id":"a","text":"Beta-blockers"},{"id":"b","text":"Calcium channel blockers"},{"id":"c","text":"Sildenafil"},{"id":"d","text":"Aspirin"}],"answerId":"c","explanation":"Sildenafil is contraindicated with nitrates due to the risk of severe hypotension from combined effects on cGMP.","kind":"integration","linkedModuleIds":["mcad-diagnosis-prevention"],"origin":"ai"}],"right-sided-hf":[{"id":"right-sided-hf~ai-0","moduleId":"right-sided-hf","stem":"What is the most common cause of right-sided heart failure?","options":[{"id":"a","text":"Cor pulmonale"},{"id":"b","text":"Left heart failure"},{"id":"c","text":"Myocardial infarction"},{"id":"d","text":"Pulmonary embolism"}],"answerId":"b","explanation":"Left heart failure raises pulmonary pressures, leading to right heart failure, making it the most common cause.","kind":"recall","origin":"ai"},{"id":"right-sided-hf~ai-1","moduleId":"right-sided-hf","stem":"Which clinical finding is most indicative of systemic venous congestion in right-sided heart failure?","options":[{"id":"a","text":"Pulmonary crackles"},{"id":"b","text":"Hepatomegaly"},{"id":"c","text":"S3 heart sound"},{"id":"d","text":"Cyanosis"}],"answerId":"b","explanation":"Hepatomegaly is a direct result of systemic venous congestion due to right-sided heart failure.","kind":"recall","origin":"ai"},{"id":"right-sided-hf~ai-2","moduleId":"right-sided-hf","stem":"How does acute pulmonary embolism lead to right-sided heart failure?","options":[{"id":"a","text":"Increased left atrial pressure"},{"id":"b","text":"Decreased systemic vascular resistance"},{"id":"c","text":"Acute right ventricular pressure overload"},{"id":"d","text":"Increased pulmonary blood flow"}],"answerId":"c","explanation":"Acute pulmonary embolism causes sudden obstruction, leading to acute right ventricular pressure overload.","kind":"mechanism","origin":"ai"},{"id":"right-sided-hf~ai-3","moduleId":"right-sided-hf","stem":"What physical exam finding is associated with right ventricular pressure overload?","options":[{"id":"a","text":"Systolic murmur"},{"id":"b","text":"Parasternal heave"},{"id":"c","text":"Gallop rhythm"},{"id":"d","text":"Pulsus paradoxus"}],"answerId":"b","explanation":"A parasternal heave indicates right ventricular hypertrophy or overload due to pressure changes.","kind":"recall","origin":"ai"},{"id":"right-sided-hf~ai-4","moduleId":"right-sided-hf","stem":"In right-sided heart failure, which of the following is a consequence of ventricular interdependence?","options":[{"id":"a","text":"Increased left ventricular compliance"},{"id":"b","text":"D-shaped left ventricle"},{"id":"c","text":"Decreased right ventricular preload"},{"id":"d","text":"Increased systemic vascular resistance"}],"answerId":"b","explanation":"D-shaped left ventricle occurs due to right ventricular dilation affecting left ventricular filling.","kind":"mechanism","origin":"ai"},{"id":"right-sided-hf~ai-5","moduleId":"right-sided-hf","stem":"Which statement about the causes of right-sided heart failure is true?","options":[{"id":"a","text":"It is primarily due to lung disease."},{"id":"b","text":"It is often caused by left heart failure."},{"id":"c","text":"It is always secondary to myocardial infarction."},{"id":"d","text":"It cannot occur without left-sided heart failure."}],"answerId":"b","explanation":"Right-sided heart failure is most commonly a consequence of left heart failure due to increased pulmonary pressures.","kind":"trap","origin":"ai"},{"id":"right-sided-hf~ai-6","moduleId":"right-sided-hf","stem":"How does left heart failure contribute to right-sided heart failure?","options":[{"id":"a","text":"By decreasing systemic venous return"},{"id":"b","text":"By increasing pulmonary venous pressure"},{"id":"c","text":"By causing right ventricular hypertrophy"},{"id":"d","text":"By reducing cardiac output"}],"answerId":"b","explanation":"Left heart failure increases pulmonary venous pressure, leading to right ventricular overload and failure.","kind":"integration","linkedModuleIds":["hfref-systolic"],"origin":"ai"},{"id":"right-sided-hf~ai-7","moduleId":"right-sided-hf","stem":"What is a common clinical presentation of right-sided heart failure that can be linked to left heart failure?","options":[{"id":"a","text":"Pulmonary edema"},{"id":"b","text":"Ascites"},{"id":"c","text":"Orthopnea"},{"id":"d","text":"Paroxysmal nocturnal dyspnea"}],"answerId":"b","explanation":"Ascites is a manifestation of systemic venous congestion in right-sided heart failure, often secondary to left heart failure.","kind":"integration","linkedModuleIds":["hfpef-diastolic"],"origin":"ai"}],"hfpef-diastolic":[{"id":"hfpef-diastolic~ai-0","moduleId":"hfpef-diastolic","stem":"What is the primary characteristic of HFpEF?","options":[{"id":"a","text":"EF < 50%"},{"id":"b","text":"Elevated LVEDP"},{"id":"c","text":"S3 gallop"},{"id":"d","text":"Dilated left ventricle"}],"answerId":"b","explanation":"HFpEF is characterized by preserved ejection fraction (EF ≥50%) but impaired filling due to a stiff, non-compliant ventricle, leading to elevated left ventricular end-diastolic pressure (LVEDP).","kind":"recall","origin":"ai"},{"id":"hfpef-diastolic~ai-1","moduleId":"hfpef-diastolic","stem":"What is the mechanism leading to concentric left ventricular hypertrophy in HFpEF?","options":[{"id":"a","text":"Volume overload"},{"id":"b","text":"Pressure overload"},{"id":"c","text":"Myocardial infarction"},{"id":"d","text":"Increased heart rate"}],"answerId":"b","explanation":"Concentric left ventricular hypertrophy in HFpEF is primarily due to pressure overload, often from chronic hypertension.","kind":"mechanism","origin":"ai"},{"id":"hfpef-diastolic~ai-2","moduleId":"hfpef-diastolic","stem":"Which clinical finding is most indicative of HFpEF?","options":[{"id":"a","text":"S3 gallop"},{"id":"b","text":"S4 gallop"},{"id":"c","text":"Elevated jugular venous pressure"},{"id":"d","text":"Pulsus alternans"}],"answerId":"b","explanation":"An S4 gallop is indicative of HFpEF, as it reflects atrial contraction against a stiff ventricle, characteristic of diastolic dysfunction.","kind":"clinical","origin":"ai"},{"id":"hfpef-diastolic~ai-3","moduleId":"hfpef-diastolic","stem":"In HFpEF, why does atrial fibrillation worsen symptoms?","options":[{"id":"a","text":"Increased stroke volume"},{"id":"b","text":"Loss of atrial kick"},{"id":"c","text":"Decreased heart rate"},{"id":"d","text":"Increased preload"}],"answerId":"b","explanation":"Atrial fibrillation reduces diastolic filling time and eliminates the atrial kick, which is crucial for filling a stiff ventricle in HFpEF.","kind":"mechanism","origin":"ai"},{"id":"hfpef-diastolic~ai-4","moduleId":"hfpef-diastolic","stem":"Which of the following is a common trap regarding heart sounds in HFpEF?","options":[{"id":"a","text":"S4 indicates volume overload"},{"id":"b","text":"S3 is present in diastolic dysfunction"},{"id":"c","text":"S4 indicates a stiff ventricle"},{"id":"d","text":"S3 is always present in heart failure"}],"answerId":"c","explanation":"An S4 gallop indicates a stiff ventricle in HFpEF, while an S3 suggests volume overload and is more associated with systolic heart failure.","kind":"trap","origin":"ai"},{"id":"hfpef-diastolic~ai-5","moduleId":"hfpef-diastolic","stem":"How does HFpEF differ from HFrEF in terms of heart sounds?","options":[{"id":"a","text":"Both have an S3 gallop"},{"id":"b","text":"HFpEF has an S4 gallop"},{"id":"c","text":"HFrEF has a sustained apex"},{"id":"d","text":"HFpEF has a dilated left ventricle"}],"answerId":"b","explanation":"HFpEF is characterized by an S4 gallop due to a stiff ventricle, while HFrEF typically presents with an S3 gallop due to volume overload.","kind":"integration","linkedModuleIds":["hfref-systolic"],"origin":"ai"},{"id":"hfpef-diastolic~ai-6","moduleId":"hfpef-diastolic","stem":"What is the relationship between HFpEF and heart sounds?","options":[{"id":"a","text":"S3 indicates diastolic dysfunction"},{"id":"b","text":"S4 suggests systolic failure"},{"id":"c","text":"S4 indicates a stiff left ventricle"},{"id":"d","text":"S3 is normal in HFpEF"}],"answerId":"c","explanation":"In HFpEF, the S4 sound indicates a stiff left ventricle due to diastolic dysfunction, while an S3 sound is more indicative of systolic heart failure.","kind":"integration","linkedModuleIds":["heart-sounds-murmurs-auscultation"],"origin":"ai"}],"arvc":[{"id":"arvc~ai-0","moduleId":"arvc","stem":"What is the most common genetic mutation associated with Arrhythmogenic RV Cardiomyopathy (ARVC)?","options":[{"id":"a","text":"Plakoglobin mutation"},{"id":"b","text":"Troponin I mutation"},{"id":"c","text":"Lamin A/C mutation"},{"id":"d","text":"Desmin mutation"}],"answerId":"a","explanation":"Plakoglobin mutations are the most frequently identified genetic defects in ARVC, affecting desmosomal proteins.","kind":"recall","origin":"ai"},{"id":"arvc~ai-1","moduleId":"arvc","stem":"Which clinical finding is most indicative of Arrhythmogenic RV Cardiomyopathy (ARVC)?","options":[{"id":"a","text":"Left ventricular hypertrophy"},{"id":"b","text":"Palpitations and syncope in a young person"},{"id":"c","text":"Elevated BNP levels"},{"id":"d","text":"S3 heart sound"}],"answerId":"b","explanation":"Palpitations and syncope in a young person are classic presentations of ARVC due to RV electrical instability.","kind":"clinical","origin":"ai"},{"id":"arvc~ai-2","moduleId":"arvc","stem":"What is the primary pathological mechanism leading to arrhythmias in ARVC?","options":[{"id":"a","text":"Myocyte hypertrophy"},{"id":"b","text":"Fibrofatty replacement of the right ventricle"},{"id":"c","text":"Coronary artery disease"},{"id":"d","text":"Myocardial ischemia"}],"answerId":"b","explanation":"Fibrofatty replacement of the right ventricle is the key pathological change that leads to electrical instability and arrhythmias in ARVC.","kind":"mechanism","origin":"ai"},{"id":"arvc~ai-3","moduleId":"arvc","stem":"Which of the following is a distinguishing feature of Naxos syndrome associated with ARVC?","options":[{"id":"a","text":"Dilated cardiomyopathy"},{"id":"b","text":"Palmoplantar hyperkeratosis"},{"id":"c","text":"Hypertrophic cardiomyopathy"},{"id":"d","text":"Aortic stenosis"}],"answerId":"b","explanation":"Naxos syndrome is characterized by palmoplantar hyperkeratosis and woolly hair, in addition to ARVC.","kind":"recall","origin":"ai"},{"id":"arvc~ai-4","moduleId":"arvc","stem":"A 20-year-old athlete collapses during a game and is found to have ventricular fibrillation. Which condition should be considered as a differential diagnosis?","options":[{"id":"a","text":"Hypertrophic cardiomyopathy"},{"id":"b","text":"Arrhythmogenic RV cardiomyopathy"},{"id":"c","text":"Dilated cardiomyopathy"},{"id":"d","text":"Myocarditis"}],"answerId":"b","explanation":"Arrhythmogenic RV cardiomyopathy is a key differential for sudden cardiac death in young athletes due to its association with ventricular arrhythmias.","kind":"trap","origin":"ai"},{"id":"arvc~ai-5","moduleId":"arvc","stem":"How does ARVC differ from dilated cardiomyopathy in terms of affected heart chambers?","options":[{"id":"a","text":"Primarily affects the left ventricle"},{"id":"b","text":"Primarily affects the right ventricle"},{"id":"c","text":"Affects both ventricles equally"},{"id":"d","text":"Affects the atria more than the ventricles"}],"answerId":"b","explanation":"ARVC predominantly affects the right ventricle, while dilated cardiomyopathy typically involves both ventricles.","kind":"integration","linkedModuleIds":["dilated-cardiomyopathy"],"origin":"ai"},{"id":"arvc~ai-6","moduleId":"arvc","stem":"Which of the following statements best describes the relationship between ARVC and general cardiomyopathy classification?","options":[{"id":"a","text":"ARVC is a type of hypertrophic cardiomyopathy"},{"id":"b","text":"ARVC is classified under restrictive cardiomyopathy"},{"id":"c","text":"ARVC is a specific form of arrhythmogenic cardiomyopathy"},{"id":"d","text":"ARVC is unrelated to cardiomyopathy classifications"}],"answerId":"c","explanation":"ARVC is classified as a specific form of arrhythmogenic cardiomyopathy, distinct from other types like dilated or hypertrophic cardiomyopathy.","kind":"integration","linkedModuleIds":["cardiomyopathy-overview"],"origin":"ai"}],"hypertensive-target-organ-damage":[{"id":"hypertensive-target-organ-damage~ai-0","moduleId":"hypertensive-target-organ-damage","stem":"What is the primary mechanism by which sustained hypertension leads to left ventricular hypertrophy?","options":[{"id":"a","text":"Increased preload"},{"id":"b","text":"Increased afterload"},{"id":"c","text":"Myocardial ischemia"},{"id":"d","text":"Valvular heart disease"}],"answerId":"b","explanation":"Sustained hypertension increases afterload, leading to concentric left ventricular hypertrophy.","kind":"mechanism","origin":"ai"},{"id":"hypertensive-target-organ-damage~ai-1","moduleId":"hypertensive-target-organ-damage","stem":"Which of the following findings is most indicative of hypertensive retinopathy?","options":[{"id":"a","text":"S4 heart sound"},{"id":"b","text":"AV nicking"},{"id":"c","text":"Wide pulse pressure"},{"id":"d","text":"Elevated creatinine"}],"answerId":"b","explanation":"AV nicking is a classic sign of retinal vascular damage due to hypertension.","kind":"recall","origin":"ai"},{"id":"hypertensive-target-organ-damage~ai-2","moduleId":"hypertensive-target-organ-damage","stem":"A 65-year-old patient presents with exertional dyspnea and a sustained heaving apex on examination. What is the most likely underlying cause?","options":[{"id":"a","text":"Aortic stenosis"},{"id":"b","text":"Concentric left ventricular hypertrophy"},{"id":"c","text":"Coronary artery disease"},{"id":"d","text":"Dilated cardiomyopathy"}],"answerId":"b","explanation":"The sustained heaving apex suggests concentric left ventricular hypertrophy due to pressure overload from hypertension.","kind":"clinical","origin":"ai"},{"id":"hypertensive-target-organ-damage~ai-3","moduleId":"hypertensive-target-organ-damage","stem":"Which of the following is a common complication of untreated hypertension?","options":[{"id":"a","text":"Aortic regurgitation"},{"id":"b","text":"Ischemic stroke"},{"id":"c","text":"Mitral stenosis"},{"id":"d","text":"Pulmonary embolism"}],"answerId":"b","explanation":"Untreated hypertension significantly increases the risk of ischemic stroke due to vascular damage.","kind":"recall","origin":"ai"},{"id":"hypertensive-target-organ-damage~ai-4","moduleId":"hypertensive-target-organ-damage","stem":"In a patient with hypertension, which of the following findings would suggest the presence of target-organ damage?","options":[{"id":"a","text":"Normal blood pressure"},{"id":"b","text":"Microalbuminuria"},{"id":"c","text":"Elevated LDL cholesterol"},{"id":"d","text":"Increased heart rate"}],"answerId":"b","explanation":"Microalbuminuria is an indicator of kidney damage, a common target-organ damage in hypertension.","kind":"trap","origin":"ai"},{"id":"hypertensive-target-organ-damage~ai-5","moduleId":"hypertensive-target-organ-damage","stem":"How does hypertension contribute to the development of aortic stenosis?","options":[{"id":"a","text":"By causing aortic dilation"},{"id":"b","text":"By increasing left ventricular workload"},{"id":"c","text":"By promoting valvular calcification"},{"id":"d","text":"By decreasing coronary perfusion"}],"answerId":"c","explanation":"Hypertension can lead to increased shear stress and calcification of the aortic valve, contributing to aortic stenosis.","kind":"integration","linkedModuleIds":["aortic-stenosis"],"origin":"ai"},{"id":"hypertensive-target-organ-damage~ai-6","moduleId":"hypertensive-target-organ-damage","stem":"Which of the following best describes the relationship between hypertension and heart failure with preserved ejection fraction (HFpEF)?","options":[{"id":"a","text":"Hypertension causes systolic dysfunction first"},{"id":"b","text":"Hypertension leads to concentric LVH and diastolic dysfunction"},{"id":"c","text":"Hypertension has no effect on heart failure"},{"id":"d","text":"Hypertension only affects the right heart"}],"answerId":"b","explanation":"Hypertension leads to concentric left ventricular hypertrophy, which results in diastolic dysfunction and contributes to HFpEF.","kind":"integration","linkedModuleIds":["htn-pathophysiology"],"origin":"ai"}],"hf-organ-pathology":[{"id":"hf-organ-pathology~ai-0","moduleId":"hf-organ-pathology","stem":"What is the most common cause of right heart failure?","options":[{"id":"a","text":"Cor pulmonale"},{"id":"b","text":"Isolated right heart failure"},{"id":"c","text":"Left heart failure"},{"id":"d","text":"Pulmonary embolism"}],"answerId":"c","explanation":"Left heart failure is the most common cause of right heart failure due to increased pressure and volume overload.","kind":"recall","origin":"ai"},{"id":"hf-organ-pathology~ai-1","moduleId":"hf-organ-pathology","stem":"Which clinical finding is associated with left heart failure?","options":[{"id":"a","text":"Pitting edema"},{"id":"b","text":"Tender hepatomegaly"},{"id":"c","text":"Bibasal crepitations"},{"id":"d","text":"Ascites"}],"answerId":"c","explanation":"Bibasal crepitations indicate pulmonary congestion due to left heart failure.","kind":"recall","origin":"ai"},{"id":"hf-organ-pathology~ai-2","moduleId":"hf-organ-pathology","stem":"What mechanism leads to the development of heart failure cells in the lungs?","options":[{"id":"a","text":"Increased pulmonary blood flow"},{"id":"b","text":"Chronic pulmonary congestion"},{"id":"c","text":"Acute lung injury"},{"id":"d","text":"Pulmonary embolism"}],"answerId":"b","explanation":"Heart failure cells are hemosiderin-laden macrophages resulting from chronic pulmonary congestion due to left heart failure.","kind":"mechanism","origin":"ai"},{"id":"hf-organ-pathology~ai-3","moduleId":"hf-organ-pathology","stem":"Which of the following is a complication of heart failure?","options":[{"id":"a","text":"Pulmonary embolism"},{"id":"b","text":"Cardiorenal syndrome"},{"id":"c","text":"Aortic dissection"},{"id":"d","text":"Myocardial infarction"}],"answerId":"b","explanation":"Cardiorenal syndrome is a recognized complication of heart failure due to impaired renal perfusion.","kind":"recall","origin":"ai"},{"id":"hf-organ-pathology~ai-4","moduleId":"hf-organ-pathology","stem":"In right heart failure, which finding is indicative of systemic venous congestion?","options":[{"id":"a","text":"Pulmonary edema"},{"id":"b","text":"JVD"},{"id":"c","text":"Orthopnea"},{"id":"d","text":"Paroxysmal nocturnal dyspnea"}],"answerId":"b","explanation":"Jugular venous distension (JVD) is a classic sign of systemic venous congestion in right heart failure.","kind":"recall","origin":"ai"},{"id":"hf-organ-pathology~ai-5","moduleId":"hf-organ-pathology","stem":"Heart failure cells in the lungs indicate which condition?","options":[{"id":"a","text":"Acute respiratory distress syndrome"},{"id":"b","text":"Chronic left heart failure"},{"id":"c","text":"Right heart failure"},{"id":"d","text":"Pneumonia"}],"answerId":"b","explanation":"Heart failure cells are indicative of chronic left heart failure due to pulmonary congestion.","kind":"trap","origin":"ai"},{"id":"hf-organ-pathology~ai-6","moduleId":"hf-organ-pathology","stem":"How does chronic passive hepatic congestion relate to heart failure?","options":[{"id":"a","text":"It causes systemic hypertension"},{"id":"b","text":"It leads to pulmonary edema"},{"id":"c","text":"It results from right heart failure"},{"id":"d","text":"It is a direct cause of myocardial infarction"}],"answerId":"c","explanation":"Chronic passive hepatic congestion is a consequence of right heart failure due to systemic venous congestion.","kind":"integration","linkedModuleIds":["hf-pathology-overview"],"origin":"ai"},{"id":"hf-organ-pathology~ai-7","moduleId":"hf-organ-pathology","stem":"Which finding in heart failure correlates with edema and congestion mechanisms?","options":[{"id":"a","text":"Increased cardiac output"},{"id":"b","text":"Decreased venous return"},{"id":"c","text":"Increased hydrostatic pressure"},{"id":"d","text":"Decreased oncotic pressure"}],"answerId":"c","explanation":"Increased hydrostatic pressure in the capillaries leads to edema and congestion in heart failure.","kind":"integration","linkedModuleIds":["edema-hyperemia-congestion"],"origin":"ai"}],"vasopressors-inotropes":[{"id":"vasopressors-inotropes~ai-0","moduleId":"vasopressors-inotropes","stem":"Which vasopressor is considered first-line treatment for septic shock?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"Epinephrine"},{"id":"c","text":"Norepinephrine"},{"id":"d","text":"Phenylephrine"}],"answerId":"c","explanation":"Norepinephrine is the first-line vasopressor in septic shock due to better survival rates and fewer arrhythmias compared to dopamine.","kind":"recall","origin":"ai"},{"id":"vasopressors-inotropes~ai-1","moduleId":"vasopressors-inotropes","stem":"What is the primary mechanism of action of norepinephrine?","options":[{"id":"a","text":"β1 inotropy"},{"id":"b","text":"α1 vasoconstriction"},{"id":"c","text":"β2 vasodilation"},{"id":"d","text":"Dopaminergic effects"}],"answerId":"b","explanation":"Norepinephrine primarily acts on α1 receptors to cause vasoconstriction, increasing mean arterial pressure.","kind":"mechanism","origin":"ai"},{"id":"vasopressors-inotropes~ai-2","moduleId":"vasopressors-inotropes","stem":"Which of the following is a common side effect of epinephrine?","options":[{"id":"a","text":"Reflex bradycardia"},{"id":"b","text":"Hypoglycemia"},{"id":"c","text":"Tremor"},{"id":"d","text":"Digital ischemia"}],"answerId":"c","explanation":"Epinephrine can cause tremors due to its β-adrenergic effects.","kind":"recall","origin":"ai"},{"id":"vasopressors-inotropes~ai-3","moduleId":"vasopressors-inotropes","stem":"What is the effect of dopamine at high doses?","options":[{"id":"a","text":"Increased renal perfusion"},{"id":"b","text":"Increased heart rate"},{"id":"c","text":"Vasodilation"},{"id":"d","text":"Vasoconstriction"}],"answerId":"d","explanation":"At high doses, dopamine primarily stimulates α1 receptors, leading to vasoconstriction.","kind":"mechanism","origin":"ai"},{"id":"vasopressors-inotropes~ai-4","moduleId":"vasopressors-inotropes","stem":"Which vasopressor is most likely to cause tachyarrhythmias?","options":[{"id":"a","text":"Norepinephrine"},{"id":"b","text":"Epinephrine"},{"id":"c","text":"Dopamine"},{"id":"d","text":"Dobutamine"}],"answerId":"c","explanation":"Dopamine is associated with a higher incidence of tachyarrhythmias compared to other vasopressors.","kind":"trap","origin":"ai"},{"id":"vasopressors-inotropes~ai-5","moduleId":"vasopressors-inotropes","stem":"How does norepinephrine affect heart rate during septic shock treatment?","options":[{"id":"a","text":"Increases heart rate"},{"id":"b","text":"Decreases heart rate"},{"id":"c","text":"No effect on heart rate"},{"id":"d","text":"Causes bradycardia"}],"answerId":"b","explanation":"Norepinephrine can cause reflex bradycardia due to increased mean arterial pressure.","kind":"recall","origin":"ai"},{"id":"vasopressors-inotropes~ai-6","moduleId":"vasopressors-inotropes","stem":"In the context of shock mechanisms, which type of shock is most effectively treated with norepinephrine?","options":[{"id":"a","text":"Hypovolemic shock"},{"id":"b","text":"Cardiogenic shock"},{"id":"c","text":"Septic shock"},{"id":"d","text":"Neurogenic shock"}],"answerId":"c","explanation":"Norepinephrine is the preferred vasopressor in septic shock due to its efficacy in increasing mean arterial pressure.","kind":"integration","linkedModuleIds":["shock-mechanisms-types"],"origin":"ai"},{"id":"vasopressors-inotropes~ai-7","moduleId":"vasopressors-inotropes","stem":"Which statistical method would best assess the effectiveness of norepinephrine in septic shock compared to dopamine?","options":[{"id":"a","text":"Chi-square test"},{"id":"b","text":"T-test"},{"id":"c","text":"ANOVA"},{"id":"d","text":"Regression analysis"}],"answerId":"b","explanation":"A T-test would be appropriate to compare the means of two groups, such as outcomes with norepinephrine versus dopamine.","kind":"integration","linkedModuleIds":["inferential-stats-p-value"],"origin":"ai"}],"antihypertensive-overview":[{"id":"antihypertensive-overview~ai-0","moduleId":"antihypertensive-overview","stem":"Which class of antihypertensive is preferred as first-line therapy for a young non-Black patient?","options":[{"id":"a","text":"ACE inhibitors"},{"id":"b","text":"Thiazide diuretics"},{"id":"c","text":"Calcium channel blockers"},{"id":"d","text":"Beta-blockers"}],"answerId":"a","explanation":"ACE inhibitors are preferred for young non-Black patients due to more active RAAS.","kind":"recall","origin":"ai"},{"id":"antihypertensive-overview~ai-1","moduleId":"antihypertensive-overview","stem":"What is the primary mechanism by which antihypertensive drugs lower blood pressure?","options":[{"id":"a","text":"Decrease cardiac output"},{"id":"b","text":"Increase vascular resistance"},{"id":"c","text":"Increase heart rate"},{"id":"d","text":"Enhance renal perfusion"}],"answerId":"a","explanation":"Antihypertensive drugs primarily lower blood pressure by decreasing cardiac output and/or peripheral vascular resistance.","kind":"mechanism","origin":"ai"},{"id":"antihypertensive-overview~ai-2","moduleId":"antihypertensive-overview","stem":"A patient on an ACE inhibitor presents with a persistent dry cough. What is the most likely explanation?","options":[{"id":"a","text":"Increased bradykinin levels"},{"id":"b","text":"Decreased aldosterone secretion"},{"id":"c","text":"Increased angiotensin II"},{"id":"d","text":"Decreased renal blood flow"}],"answerId":"a","explanation":"ACE inhibitors increase bradykinin levels, which can lead to a dry cough.","kind":"recall","origin":"ai"},{"id":"antihypertensive-overview~ai-3","moduleId":"antihypertensive-overview","stem":"Which antihypertensive class is associated with first-dose postural hypotension?","options":[{"id":"a","text":"Thiazide diuretics"},{"id":"b","text":"Alpha-blockers"},{"id":"c","text":"Calcium channel blockers"},{"id":"d","text":"ACE inhibitors"}],"answerId":"b","explanation":"Alpha-blockers can cause significant first-dose postural hypotension due to their vasodilatory effects.","kind":"recall","origin":"ai"},{"id":"antihypertensive-overview~ai-4","moduleId":"antihypertensive-overview","stem":"In treating hypertension, which combination is least likely to be effective in a young non-Black patient?","options":[{"id":"a","text":"ACE inhibitor and thiazide"},{"id":"b","text":"Calcium channel blocker and beta-blocker"},{"id":"c","text":"Thiazide and ACE inhibitor"},{"id":"d","text":"Beta-blocker and alpha-blocker"}],"answerId":"d","explanation":"Beta-blockers and alpha-blockers are less effective as first-line treatments in this demographic.","kind":"trap","origin":"ai"},{"id":"antihypertensive-overview~ai-5","moduleId":"antihypertensive-overview","stem":"How do thiazide diuretics primarily affect electrolyte levels?","options":[{"id":"a","text":"Cause hyperkalemia"},{"id":"b","text":"Cause hypokalemia"},{"id":"c","text":"Increase sodium retention"},{"id":"d","text":"Decrease calcium excretion"}],"answerId":"b","explanation":"Thiazide diuretics are known to cause hypokalemia as they promote potassium excretion.","kind":"recall","origin":"ai"},{"id":"antihypertensive-overview~ai-6","moduleId":"antihypertensive-overview","stem":"Which antihypertensive class is most appropriate for a patient with chronic kidney disease?","options":[{"id":"a","text":"Thiazide diuretics"},{"id":"b","text":"ACE inhibitors"},{"id":"c","text":"Calcium channel blockers"},{"id":"d","text":"Beta-blockers"}],"answerId":"b","explanation":"ACE inhibitors are recommended for patients with chronic kidney disease due to their renal protective effects.","kind":"integration","linkedModuleIds":["htn-diuretics-raas"],"origin":"ai"},{"id":"antihypertensive-overview~ai-7","moduleId":"antihypertensive-overview","stem":"In a patient with hypertension and heart failure, which class of antihypertensive is indicated?","options":[{"id":"a","text":"Calcium channel blockers"},{"id":"b","text":"Thiazide diuretics"},{"id":"c","text":"ACE inhibitors"},{"id":"d","text":"Alpha-blockers"}],"answerId":"c","explanation":"ACE inhibitors are indicated in patients with heart failure due to their benefits in reducing morbidity and mortality.","kind":"integration","linkedModuleIds":["htn-ccb-sympatholytics"],"origin":"ai"}],"cardiac-hypertrophy-remodeling":[{"id":"cardiac-hypertrophy-remodeling~ai-0","moduleId":"cardiac-hypertrophy-remodeling","stem":"What type of cardiac hypertrophy is primarily caused by chronic hypertension?","options":[{"id":"a","text":"Eccentric hypertrophy"},{"id":"b","text":"Concentric hypertrophy"},{"id":"c","text":"Physiological hypertrophy"},{"id":"d","text":"Pathological hypertrophy"}],"answerId":"b","explanation":"Chronic hypertension leads to pressure overload, resulting in concentric hypertrophy characterized by thickened walls and a smaller chamber size.","kind":"recall","origin":"ai"},{"id":"cardiac-hypertrophy-remodeling~ai-1","moduleId":"cardiac-hypertrophy-remodeling","stem":"Which histological finding is characteristic of cardiac hypertrophy?","options":[{"id":"a","text":"Decreased myocyte size"},{"id":"b","text":"Increased capillary density"},{"id":"c","text":"Interstitial fibrosis"},{"id":"d","text":"Decreased myocyte apoptosis"}],"answerId":"c","explanation":"Cardiac hypertrophy is associated with enlarged myocytes and interstitial fibrosis, reflecting maladaptive remodeling.","kind":"recall","origin":"ai"},{"id":"cardiac-hypertrophy-remodeling~ai-2","moduleId":"cardiac-hypertrophy-remodeling","stem":"What is the primary mechanism leading to concentric hypertrophy in response to pressure overload?","options":[{"id":"a","text":"Increased preload"},{"id":"b","text":"Increased afterload"},{"id":"c","text":"Decreased contractility"},{"id":"d","text":"Increased heart rate"}],"answerId":"b","explanation":"Increased afterload due to conditions like hypertension causes the heart to thicken its walls, leading to concentric hypertrophy.","kind":"mechanism","origin":"ai"},{"id":"cardiac-hypertrophy-remodeling~ai-3","moduleId":"cardiac-hypertrophy-remodeling","stem":"A patient presents with a sustained heaving apex and an S4 heart sound. What type of hypertrophy is likely present?","options":[{"id":"a","text":"Eccentric hypertrophy"},{"id":"b","text":"Concentric hypertrophy"},{"id":"c","text":"Physiological hypertrophy"},{"id":"d","text":"Dilated cardiomyopathy"}],"answerId":"b","explanation":"The sustained heaving apex and S4 sound indicate concentric hypertrophy, commonly seen in pressure overload conditions.","kind":"clinical","origin":"ai"},{"id":"cardiac-hypertrophy-remodeling~ai-4","moduleId":"cardiac-hypertrophy-remodeling","stem":"Which of the following statements about cardiac hypertrophy is true?","options":[{"id":"a","text":"Hypertension causes eccentric hypertrophy."},{"id":"b","text":"Volume overload leads to concentric hypertrophy."},{"id":"c","text":"Aortic stenosis results in concentric hypertrophy."},{"id":"d","text":"Mitral regurgitation causes thickened ventricular walls."}],"answerId":"c","explanation":"Aortic stenosis causes pressure overload, leading to concentric hypertrophy, while hypertension also leads to the same pattern.","kind":"trap","origin":"ai"},{"id":"cardiac-hypertrophy-remodeling~ai-5","moduleId":"cardiac-hypertrophy-remodeling","stem":"How does eccentric hypertrophy differ from concentric hypertrophy in terms of chamber size?","options":[{"id":"a","text":"Eccentric hypertrophy has a smaller chamber size."},{"id":"b","text":"Concentric hypertrophy has a larger chamber size."},{"id":"c","text":"Both have similar chamber sizes."},{"id":"d","text":"Eccentric hypertrophy has a larger chamber size."}],"answerId":"d","explanation":"Eccentric hypertrophy is characterized by dilated chambers, while concentric hypertrophy has a smaller chamber size due to wall thickening.","kind":"trap","origin":"ai"},{"id":"cardiac-hypertrophy-remodeling~ai-6","moduleId":"cardiac-hypertrophy-remodeling","stem":"In a patient with heart failure due to aortic regurgitation, which type of hypertrophy is expected?","options":[{"id":"a","text":"Concentric hypertrophy"},{"id":"b","text":"Eccentric hypertrophy"},{"id":"c","text":"Physiological hypertrophy"},{"id":"d","text":"None of the above"}],"answerId":"b","explanation":"Aortic regurgitation leads to volume overload, resulting in eccentric hypertrophy characterized by a dilated chamber.","kind":"integration","linkedModuleIds":["hf-pathology-overview"],"origin":"ai"},{"id":"cardiac-hypertrophy-remodeling~ai-7","moduleId":"cardiac-hypertrophy-remodeling","stem":"What is the expected histological change in a patient with dilated cardiomyopathy?","options":[{"id":"a","text":"Increased myocyte size"},{"id":"b","text":"Decreased interstitial fibrosis"},{"id":"c","text":"Increased apoptosis"},{"id":"d","text":"Decreased capillary density"}],"answerId":"c","explanation":"Dilated cardiomyopathy is associated with increased apoptosis of myocytes, leading to a decrease in overall heart function.","kind":"integration","linkedModuleIds":["hf-organ-pathology"],"origin":"ai"}],"hf-other-drugs":[{"id":"hf-other-drugs~ai-0","moduleId":"hf-other-drugs","stem":"What is the primary mechanism of action of loop diuretics like furosemide?","options":[{"id":"a","text":"Inhibition of sodium reabsorption in the distal tubule"},{"id":"b","text":"Inhibition of sodium-potassium-chloride co-transporter in the loop of Henle"},{"id":"c","text":"Inhibition of aldosterone secretion"},{"id":"d","text":"Inhibition of carbonic anhydrase"}],"answerId":"b","explanation":"Loop diuretics inhibit the Na-K-2Cl co-transporter in the thick ascending limb of the loop of Henle, leading to increased diuresis.","kind":"mechanism","origin":"ai"},{"id":"hf-other-drugs~ai-1","moduleId":"hf-other-drugs","stem":"Which of the following is a common side effect of thiazide diuretics?","options":[{"id":"a","text":"Hyperkalemia"},{"id":"b","text":"Hypokalemia"},{"id":"c","text":"Hyponatremia"},{"id":"d","text":"Hypercalcemia"}],"answerId":"b","explanation":"Thiazide diuretics can cause hypokalemia due to increased potassium excretion in the distal nephron.","kind":"recall","origin":"ai"},{"id":"hf-other-drugs~ai-2","moduleId":"hf-other-drugs","stem":"What is the clinical significance of using ivabradine in heart failure?","options":[{"id":"a","text":"It improves survival in all heart failure patients"},{"id":"b","text":"It reduces heart rate without affecting myocardial contractility"},{"id":"c","text":"It increases cardiac output significantly"},{"id":"d","text":"It is used as a first-line treatment for acute heart failure"}],"answerId":"b","explanation":"Ivabradine selectively inhibits the If current in the SA node, reducing heart rate without impacting contractility.","kind":"clinical","origin":"ai"},{"id":"hf-other-drugs~ai-3","moduleId":"hf-other-drugs","stem":"Which of the following statements about diuretics in heart failure is true?","options":[{"id":"a","text":"Diuretics improve survival in heart failure"},{"id":"b","text":"Diuretics relieve symptoms of congestion"},{"id":"c","text":"Diuretics are first-line for all heart failure patients"},{"id":"d","text":"Diuretics are used to increase cardiac output"}],"answerId":"b","explanation":"Diuretics are effective for relieving symptoms of congestion but do not improve survival in heart failure.","kind":"trap","origin":"ai"},{"id":"hf-other-drugs~ai-4","moduleId":"hf-other-drugs","stem":"What is the mechanism of action of hydralazine in heart failure?","options":[{"id":"a","text":"Venous dilation"},{"id":"b","text":"Arteriolar dilation"},{"id":"c","text":"Inhibition of angiotensin II"},{"id":"d","text":"Inhibition of aldosterone"}],"answerId":"b","explanation":"Hydralazine primarily acts as an arteriolar dilator, reducing afterload in heart failure patients.","kind":"mechanism","origin":"ai"},{"id":"hf-other-drugs~ai-5","moduleId":"hf-other-drugs","stem":"In which patient population is the combination of hydralazine and isosorbide dinitrate particularly beneficial?","options":[{"id":"a","text":"Patients with preserved ejection fraction"},{"id":"b","text":"Patients with heart failure and reduced ejection fraction who are intolerant to ACE inhibitors"},{"id":"c","text":"Patients with acute heart failure"},{"id":"d","text":"Patients with diuretic-resistant edema"}],"answerId":"b","explanation":"This combination is particularly beneficial in HFrEF patients who are ACEi/ARB intolerant, especially in Black patients.","kind":"recall","origin":"ai"},{"id":"hf-other-drugs~ai-6","moduleId":"hf-other-drugs","stem":"How does ivabradine's mechanism relate to heart failure management?","options":[{"id":"a","text":"It increases contractility"},{"id":"b","text":"It decreases heart rate to improve diastolic filling"},{"id":"c","text":"It enhances diuretic effect"},{"id":"d","text":"It directly dilates blood vessels"}],"answerId":"b","explanation":"By decreasing heart rate, ivabradine allows for improved diastolic filling time, which is crucial in heart failure management.","kind":"integration","linkedModuleIds":["hf-pharmacology-pillars"],"origin":"ai"},{"id":"hf-other-drugs~ai-7","moduleId":"hf-other-drugs","stem":"Which of the following best describes the role of diuretics in the context of the four pillars of heart failure treatment?","options":[{"id":"a","text":"They are part of the four pillars"},{"id":"b","text":"They improve survival"},{"id":"c","text":"They relieve symptoms but do not improve mortality"},{"id":"d","text":"They are first-line therapy for all heart failure patients"}],"answerId":"c","explanation":"Diuretics are essential for symptom relief but do not contribute to improved survival, which is achieved through the four pillars.","kind":"integration","linkedModuleIds":["hf-pharmacology-pillars"],"origin":"ai"}],"hf-pathology-overview":[{"id":"hf-pathology-overview~ai-0","moduleId":"hf-pathology-overview","stem":"What is the primary definition of heart failure (HF)?","options":[{"id":"a","text":"A clinical syndrome from structural/functional impairment of ventricular filling or ejection"},{"id":"b","text":"A condition characterized solely by reduced ejection fraction"},{"id":"c","text":"A type of cardiac dysfunction without symptoms"},{"id":"d","text":"A reversible state of myocardial ischemia"}],"answerId":"a","explanation":"Heart failure is defined as a clinical syndrome resulting from any structural or functional impairment of ventricular filling or ejection.","kind":"recall","origin":"ai"},{"id":"hf-pathology-overview~ai-1","moduleId":"hf-pathology-overview","stem":"Which of the following best describes HFrEF?","options":[{"id":"a","text":"LVEF ≤40% with systolic dysfunction"},{"id":"b","text":"LVEF ≥50% with diastolic dysfunction"},{"id":"c","text":"LVEF 41-49% with mixed dysfunction"},{"id":"d","text":"Normal LVEF with symptoms of heart failure"}],"answerId":"a","explanation":"HFrEF stands for heart failure with reduced ejection fraction, defined as LVEF ≤40%.","kind":"recall","origin":"ai"},{"id":"hf-pathology-overview~ai-2","moduleId":"hf-pathology-overview","stem":"What is the significance of NYHA functional classification?","options":[{"id":"a","text":"It categorizes heart failure based on structural changes"},{"id":"b","text":"It assesses the severity of symptoms and their impact on daily activities"},{"id":"c","text":"It predicts the risk of developing heart failure"},{"id":"d","text":"It determines the ejection fraction of the heart"}],"answerId":"b","explanation":"The NYHA classification grades heart failure based on the severity of symptoms and their impact on physical activity.","kind":"recall","origin":"ai"},{"id":"hf-pathology-overview~ai-3","moduleId":"hf-pathology-overview","stem":"Which clinical finding is most indicative of volume overload in heart failure?","options":[{"id":"a","text":"S3 gallop"},{"id":"b","text":"Bradycardia"},{"id":"c","text":"Hypotension"},{"id":"d","text":"Normal JVP"}],"answerId":"a","explanation":"An S3 gallop is a common clinical finding in heart failure that indicates volume overload due to left ventricular dysfunction.","kind":"recall","origin":"ai"},{"id":"hf-pathology-overview~ai-4","moduleId":"hf-pathology-overview","stem":"In which stage of heart failure would a patient with asymptomatic left ventricular dysfunction be classified?","options":[{"id":"a","text":"Stage A"},{"id":"b","text":"Stage B"},{"id":"c","text":"Stage C"},{"id":"d","text":"Stage D"}],"answerId":"b","explanation":"Patients with asymptomatic left ventricular dysfunction are classified as Stage B heart failure.","kind":"trap","origin":"ai"},{"id":"hf-pathology-overview~ai-5","moduleId":"hf-pathology-overview","stem":"What is the primary mechanism behind dyspnea in heart failure?","options":[{"id":"a","text":"Increased cardiac output"},{"id":"b","text":"Decreased pulmonary blood flow"},{"id":"c","text":"Congestion and low cardiac output"},{"id":"d","text":"Increased systemic vascular resistance"}],"answerId":"c","explanation":"Dyspnea in heart failure is primarily caused by congestion and low cardiac output, leading to pulmonary congestion.","kind":"mechanism","origin":"ai"},{"id":"hf-pathology-overview~ai-6","moduleId":"hf-pathology-overview","stem":"How does cardiac hypertrophy relate to heart failure?","options":[{"id":"a","text":"It is a compensatory mechanism that prevents heart failure"},{"id":"b","text":"It is a direct cause of heart failure"},{"id":"c","text":"It can lead to structural changes contributing to heart failure"},{"id":"d","text":"It has no relation to heart failure"}],"answerId":"c","explanation":"Cardiac hypertrophy can lead to structural changes that contribute to the development of heart failure.","kind":"integration","linkedModuleIds":["cardiac-hypertrophy-remodeling"],"origin":"ai"},{"id":"hf-pathology-overview~ai-7","moduleId":"hf-pathology-overview","stem":"Which of the following findings would most likely indicate right-sided heart failure?","options":[{"id":"a","text":"Pulmonary edema"},{"id":"b","text":"Peripheral edema"},{"id":"c","text":"S3 gallop"},{"id":"d","text":"Decreased JVP"}],"answerId":"b","explanation":"Peripheral edema is a common finding in right-sided heart failure due to systemic venous congestion.","kind":"recall","origin":"ai"},{"id":"hf-pathology-overview~ai-8","moduleId":"hf-pathology-overview","stem":"What is the relationship between heart failure and organ pathology?","options":[{"id":"a","text":"Heart failure leads to reversible organ damage"},{"id":"b","text":"Organ pathology is a consequence of heart failure"},{"id":"c","text":"Heart failure has no impact on organ function"},{"id":"d","text":"Organ pathology is unrelated to heart failure severity"}],"answerId":"b","explanation":"Organ pathology can result from heart failure due to inadequate perfusion and congestion, affecting organ function.","kind":"integration","linkedModuleIds":["hf-organ-pathology"],"origin":"ai"}],"htn-pathophysiology":[{"id":"htn-pathophysiology~ai-0","moduleId":"htn-pathophysiology","stem":"What is the primary mechanism by which primary aldosteronism causes hypertension?","options":[{"id":"a","text":"Increased cardiac output"},{"id":"b","text":"Increased peripheral vascular resistance"},{"id":"c","text":"Increased blood volume"},{"id":"d","text":"Increased heart rate"}],"answerId":"c","explanation":"Primary aldosteronism leads to increased sodium reabsorption, resulting in increased blood volume and hypertension.","kind":"mechanism","origin":"ai"},{"id":"htn-pathophysiology~ai-1","moduleId":"htn-pathophysiology","stem":"Which of the following findings is most indicative of renovascular hypertension?","options":[{"id":"a","text":"Cushingoid features"},{"id":"b","text":"Abdominal bruit"},{"id":"c","text":"Episodic headaches"},{"id":"d","text":"Spontaneous hypokalemia"}],"answerId":"b","explanation":"An abdominal bruit suggests renal artery stenosis, a common cause of renovascular hypertension.","kind":"recall","origin":"ai"},{"id":"htn-pathophysiology~ai-2","moduleId":"htn-pathophysiology","stem":"A 35-year-old woman presents with hypertension and spontaneous hypokalemia. What is the most likely diagnosis?","options":[{"id":"a","text":"Cushing syndrome"},{"id":"b","text":"Pheochromocytoma"},{"id":"c","text":"Primary aldosteronism"},{"id":"d","text":"Renovascular hypertension"}],"answerId":"c","explanation":"Spontaneous hypokalemia in the context of hypertension is highly suggestive of primary aldosteronism.","kind":"clinical","origin":"ai"},{"id":"htn-pathophysiology~ai-3","moduleId":"htn-pathophysiology","stem":"Which of the following is a common driver of primary hypertension in young adults?","options":[{"id":"a","text":"Renin-angiotensin-aldosterone system"},{"id":"b","text":"Vasoactive substances"},{"id":"c","text":"Obstructive sleep apnea"},{"id":"d","text":"Chronic kidney disease"}],"answerId":"b","explanation":"Vasoactive substances, such as endothelin and nitric oxide, are significant contributors to primary hypertension in younger populations.","kind":"recall","origin":"ai"},{"id":"htn-pathophysiology~ai-4","moduleId":"htn-pathophysiology","stem":"In a patient with episodic hypertension, headaches, and palpitations, which condition should be suspected?","options":[{"id":"a","text":"Primary aldosteronism"},{"id":"b","text":"Cushing syndrome"},{"id":"c","text":"Pheochromocytoma"},{"id":"d","text":"Renovascular hypertension"}],"answerId":"c","explanation":"These symptoms are characteristic of pheochromocytoma, which causes episodic hypertension.","kind":"clinical","origin":"ai"},{"id":"htn-pathophysiology~ai-5","moduleId":"htn-pathophysiology","stem":"How does hypertension relate to target organ damage in the context of the linked module?","options":[{"id":"a","text":"It causes renal artery stenosis"},{"id":"b","text":"It leads to increased cardiac output"},{"id":"c","text":"It can result in left ventricular hypertrophy"},{"id":"d","text":"It prevents atherosclerosis"}],"answerId":"c","explanation":"Chronic hypertension can lead to left ventricular hypertrophy as a form of target organ damage.","kind":"integration","linkedModuleIds":["htn-classification"],"origin":"ai"},{"id":"htn-pathophysiology~ai-6","moduleId":"htn-pathophysiology","stem":"Which of the following is a critical factor in the classification of hypertension as discussed in the linked module?","options":[{"id":"a","text":"Age of onset"},{"id":"b","text":"Presence of secondary causes"},{"id":"c","text":"Family history"},{"id":"d","text":"Lifestyle factors"}],"answerId":"b","explanation":"Identifying secondary causes is essential for the accurate classification of hypertension.","kind":"integration","linkedModuleIds":["htn-classification"],"origin":"ai"}],"htn-classification":[{"id":"htn-classification~ai-0","moduleId":"htn-classification","stem":"What is the threshold for hypertension according to the 2017 ACC/AHA guidelines?","options":[{"id":"a","text":"≥120/80 mmHg"},{"id":"b","text":"≥130/80 mmHg"},{"id":"c","text":"≥140/90 mmHg"},{"id":"d","text":"≥150/90 mmHg"}],"answerId":"b","explanation":"The 2017 ACC/AHA guidelines define hypertension as a blood pressure of ≥130/80 mmHg.","kind":"recall","origin":"ai"},{"id":"htn-classification~ai-1","moduleId":"htn-classification","stem":"Which type of hypertension is characterized by high office blood pressure but normal out-of-office readings?","options":[{"id":"a","text":"Masked hypertension"},{"id":"b","text":"White coat hypertension"},{"id":"c","text":"Isolated systolic hypertension"},{"id":"d","text":"Secondary hypertension"}],"answerId":"b","explanation":"White coat hypertension occurs when patients have elevated blood pressure readings in a clinical setting but normal readings outside of it.","kind":"recall","origin":"ai"},{"id":"htn-classification~ai-2","moduleId":"htn-classification","stem":"What is a common clinical finding in elderly patients with isolated systolic hypertension?","options":[{"id":"a","text":"Narrow pulse pressure"},{"id":"b","text":"Wide pulse pressure"},{"id":"c","text":"Hypokalemia"},{"id":"d","text":"Bradycardia"}],"answerId":"b","explanation":"Elderly patients with isolated systolic hypertension often present with a wide pulse pressure due to arterial stiffness.","kind":"recall","origin":"ai"},{"id":"htn-classification~ai-3","moduleId":"htn-classification","stem":"Which mechanism is primarily responsible for the 'silent' nature of hypertension until target-organ damage occurs?","options":[{"id":"a","text":"Increased cardiac output"},{"id":"b","text":"Vascular remodeling"},{"id":"c","text":"Endothelial dysfunction"},{"id":"d","text":"Asymptomatic nature of elevated blood pressure"}],"answerId":"d","explanation":"Hypertension is often asymptomatic until it causes damage to target organs, making it a 'silent' disease.","kind":"mechanism","origin":"ai"},{"id":"htn-classification~ai-4","moduleId":"htn-classification","stem":"What is the risk associated with masked hypertension?","options":[{"id":"a","text":"No risk, as office BP is normal"},{"id":"b","text":"Increased risk of cardiovascular events"},{"id":"c","text":"Only risk of secondary hypertension"},{"id":"d","text":"Lower risk than white coat hypertension"}],"answerId":"b","explanation":"Masked hypertension is associated with an increased risk of cardiovascular events despite normal office blood pressure readings.","kind":"trap","origin":"ai"},{"id":"htn-classification~ai-5","moduleId":"htn-classification","stem":"How does arterial stiffness contribute to isolated systolic hypertension in the elderly?","options":[{"id":"a","text":"Increases diastolic pressure"},{"id":"b","text":"Decreases systolic pressure"},{"id":"c","text":"Increases systolic pressure"},{"id":"d","text":"Decreases pulse pressure"}],"answerId":"c","explanation":"Arterial stiffness leads to increased systolic pressure due to reduced compliance of the arterial walls.","kind":"mechanism","origin":"ai"},{"id":"htn-classification~ai-6","moduleId":"htn-classification","stem":"How can ambulatory blood pressure monitoring (ABPM) help differentiate between masked and white coat hypertension?","options":[{"id":"a","text":"It only measures office BP"},{"id":"b","text":"It provides 24-hour BP profiles"},{"id":"c","text":"It is less accurate than office BP"},{"id":"d","text":"It cannot detect hypertension"}],"answerId":"b","explanation":"ABPM provides a comprehensive 24-hour blood pressure profile, allowing for the identification of masked hypertension.","kind":"integration","linkedModuleIds":["blood-pressure-measurement-abpm"],"origin":"ai"},{"id":"htn-classification~ai-7","moduleId":"htn-classification","stem":"Which finding would suggest a secondary cause of hypertension during a clinical examination?","options":[{"id":"a","text":"Normal renal function tests"},{"id":"b","text":"Presence of a bruit"},{"id":"c","text":"Normal potassium levels"},{"id":"d","text":"Consistent high office BP only"}],"answerId":"b","explanation":"The presence of a bruit may indicate renal artery stenosis or other secondary causes of hypertension.","kind":"integration","linkedModuleIds":["htn-pathophysiology"],"origin":"ai"}],"hf-pharmacology-pillars":[{"id":"hf-pharmacology-pillars~ai-0","moduleId":"hf-pharmacology-pillars","stem":"Which medication is part of the four pillars of HFrEF GDMT that specifically targets the RAAS?","options":[{"id":"a","text":"Beta-blocker"},{"id":"b","text":"SGLT2 inhibitor"},{"id":"c","text":"MRA"},{"id":"d","text":"ARNi"}],"answerId":"d","explanation":"ARNi (Angiotensin Receptor Neprilysin Inhibitor) directly targets the RAAS, improving survival in HFrEF.","kind":"recall","origin":"ai"},{"id":"hf-pharmacology-pillars~ai-1","moduleId":"hf-pharmacology-pillars","stem":"What is the primary mechanism of action of beta-blockers in heart failure?","options":[{"id":"a","text":"Increase cardiac output"},{"id":"b","text":"Negative chronotropy"},{"id":"c","text":"Reduce preload"},{"id":"d","text":"Enhance diuresis"}],"answerId":"b","explanation":"Beta-blockers exert negative chronotropic effects, reducing heart rate and myocardial oxygen demand.","kind":"mechanism","origin":"ai"},{"id":"hf-pharmacology-pillars~ai-2","moduleId":"hf-pharmacology-pillars","stem":"A patient on an ACE inhibitor presents with a persistent dry cough. What is the most likely mechanism behind this side effect?","options":[{"id":"a","text":"Increased aldosterone"},{"id":"b","text":"Bradykinin accumulation"},{"id":"c","text":"Decreased angiotensin II"},{"id":"d","text":"Increased renin release"}],"answerId":"b","explanation":"ACE inhibitors increase bradykinin levels, which can cause a dry cough.","kind":"recall","origin":"ai"},{"id":"hf-pharmacology-pillars~ai-3","moduleId":"hf-pharmacology-pillars","stem":"Which of the following is a common side effect of spironolactone?","options":[{"id":"a","text":"Hypokalemia"},{"id":"b","text":"Gynecomastia"},{"id":"c","text":"Bradycardia"},{"id":"d","text":"Dry cough"}],"answerId":"b","explanation":"Spironolactone, an MRA, can cause gynecomastia due to its anti-androgen effects.","kind":"recall","origin":"ai"},{"id":"hf-pharmacology-pillars~ai-4","moduleId":"hf-pharmacology-pillars","stem":"What is a critical contraindication when prescribing ARNi?","options":[{"id":"a","text":"Combination with beta-blockers"},{"id":"b","text":"Combination with diuretics"},{"id":"c","text":"Combination with ACE inhibitors"},{"id":"d","text":"Combination with SGLT2 inhibitors"}],"answerId":"c","explanation":"ARNi should never be combined with ACE inhibitors due to the increased risk of angioedema from bradykinin.","kind":"trap","origin":"ai"},{"id":"hf-pharmacology-pillars~ai-5","moduleId":"hf-pharmacology-pillars","stem":"How do SGLT2 inhibitors contribute to heart failure management?","options":[{"id":"a","text":"Increase sodium retention"},{"id":"b","text":"Promote glycosuria and osmotic diuresis"},{"id":"c","text":"Enhance RAAS activity"},{"id":"d","text":"Decrease heart rate"}],"answerId":"b","explanation":"SGLT2 inhibitors promote glycosuria, leading to osmotic diuresis, which helps manage fluid overload.","kind":"mechanism","origin":"ai"},{"id":"hf-pharmacology-pillars~ai-6","moduleId":"hf-pharmacology-pillars","stem":"Which diuretic mechanism is most relevant when considering the pharmacological management of heart failure?","options":[{"id":"a","text":"Inhibition of aldosterone"},{"id":"b","text":"Inhibition of sodium reabsorption"},{"id":"c","text":"Inhibition of angiotensin II"},{"id":"d","text":"Inhibition of neprilysin"}],"answerId":"b","explanation":"Diuretics primarily work by inhibiting sodium reabsorption in the renal tubules, leading to increased urine output.","kind":"integration","linkedModuleIds":["hf-other-drugs"],"origin":"ai"},{"id":"hf-pharmacology-pillars~ai-7","moduleId":"hf-pharmacology-pillars","stem":"In a patient with heart failure, which drug class can be added to improve outcomes regardless of diabetes status?","options":[{"id":"a","text":"Beta-blockers"},{"id":"b","text":"Diuretics"},{"id":"c","text":"SGLT2 inhibitors"},{"id":"d","text":"Digoxin"}],"answerId":"c","explanation":"SGLT2 inhibitors can be added to heart failure treatment to improve outcomes, even in non-diabetic patients.","kind":"integration","linkedModuleIds":["digoxin-inotropes"],"origin":"ai"}],"digoxin-inotropes":[{"id":"digoxin-inotropes~ai-0","moduleId":"digoxin-inotropes","stem":"What is the primary mechanism by which digoxin increases cardiac contractility?","options":[{"id":"a","text":"Inhibition of phosphodiesterase"},{"id":"b","text":"Inhibition of Na⁺/K⁺-ATPase"},{"id":"c","text":"Activation of β1-adrenergic receptors"},{"id":"d","text":"Inhibition of calcium channels"}],"answerId":"b","explanation":"Digoxin inhibits Na⁺/K⁺-ATPase, leading to increased intracellular calcium and enhanced contractility.","kind":"mechanism","origin":"ai"},{"id":"digoxin-inotropes~ai-1","moduleId":"digoxin-inotropes","stem":"Which of the following is a common symptom of digoxin toxicity?","options":[{"id":"a","text":"Hypotension"},{"id":"b","text":"Yellow-green vision"},{"id":"c","text":"Bradycardia"},{"id":"d","text":"Chest pain"}],"answerId":"b","explanation":"Yellow-green vision is a classic sign of digoxin toxicity due to its effects on the visual system.","kind":"recall","origin":"ai"},{"id":"digoxin-inotropes~ai-2","moduleId":"digoxin-inotropes","stem":"In a patient with heart failure, which condition would most likely exacerbate digoxin toxicity?","options":[{"id":"a","text":"Hyperkalemia"},{"id":"b","text":"Hypokalemia"},{"id":"c","text":"Hypercalcemia"},{"id":"d","text":"Hypomagnesemia"}],"answerId":"b","explanation":"Hypokalemia potentiates digoxin toxicity by freeing the Na⁺/K⁺-ATPase binding site for digoxin.","kind":"trap","origin":"ai"},{"id":"digoxin-inotropes~ai-3","moduleId":"digoxin-inotropes","stem":"What is the primary use of digoxin in heart failure patients?","options":[{"id":"a","text":"To improve survival rates"},{"id":"b","text":"To reduce hospitalizations"},{"id":"c","text":"To increase exercise capacity"},{"id":"d","text":"To decrease blood pressure"}],"answerId":"b","explanation":"Digoxin is used to reduce hospitalizations in symptomatic heart failure despite guideline-directed medical therapy.","kind":"recall","origin":"ai"},{"id":"digoxin-inotropes~ai-4","moduleId":"digoxin-inotropes","stem":"Which of the following inotropic agents is a β1-adrenergic agonist used in acute heart failure?","options":[{"id":"a","text":"Milrinone"},{"id":"b","text":"Dobutamine"},{"id":"c","text":"Digoxin"},{"id":"d","text":"Amiodarone"}],"answerId":"b","explanation":"Dobutamine is a β1-adrenergic agonist that increases cardiac contractility and is used in acute heart failure.","kind":"recall","origin":"ai"},{"id":"digoxin-inotropes~ai-5","moduleId":"digoxin-inotropes","stem":"How does hypokalemia affect the action of digoxin?","options":[{"id":"a","text":"Decreases digoxin efficacy"},{"id":"b","text":"Increases digoxin clearance"},{"id":"c","text":"Potentiates digoxin toxicity"},{"id":"d","text":"Reduces digoxin absorption"}],"answerId":"c","explanation":"Hypokalemia potentiates digoxin toxicity by increasing the binding of digoxin to Na⁺/K⁺-ATPase.","kind":"trap","origin":"ai"},{"id":"digoxin-inotropes~ai-6","moduleId":"digoxin-inotropes","stem":"How might renal function impact the use of digoxin in heart failure patients?","options":[{"id":"a","text":"Increased digoxin metabolism"},{"id":"b","text":"Decreased renal clearance of digoxin"},{"id":"c","text":"Increased risk of hyperkalemia"},{"id":"d","text":"Decreased risk of toxicity"}],"answerId":"b","explanation":"Impaired renal function decreases the clearance of digoxin, increasing the risk of toxicity.","kind":"integration","linkedModuleIds":["tubular-reabsorption-secretion"],"origin":"ai"},{"id":"digoxin-inotropes~ai-7","moduleId":"digoxin-inotropes","stem":"Which class of drugs can be used alongside digoxin to manage heart failure symptoms?","options":[{"id":"a","text":"ACE inhibitors"},{"id":"b","text":"Calcium channel blockers"},{"id":"c","text":"Anticoagulants"},{"id":"d","text":"Antibiotics"}],"answerId":"a","explanation":"ACE inhibitors are commonly used in conjunction with digoxin to manage heart failure symptoms and improve outcomes.","kind":"integration","linkedModuleIds":["hf-other-drugs"],"origin":"ai"}],"shock-mechanisms-types":[{"id":"shock-mechanisms-types~ai-0","moduleId":"shock-mechanisms-types","stem":"What is the primary mechanism leading to organ failure in shock?","options":[{"id":"a","text":"Increased cardiac output"},{"id":"b","text":"Decreased tissue perfusion"},{"id":"c","text":"Increased oxygen delivery"},{"id":"d","text":"Decreased metabolic rate"}],"answerId":"b","explanation":"Shock leads to decreased tissue perfusion, resulting in anaerobic metabolism and subsequent organ failure.","kind":"recall","origin":"ai"},{"id":"shock-mechanisms-types~ai-1","moduleId":"shock-mechanisms-types","stem":"Which type of shock is characterized by warm skin and hypotension?","options":[{"id":"a","text":"Hypovolemic shock"},{"id":"b","text":"Cardiogenic shock"},{"id":"c","text":"Distributive shock"},{"id":"d","text":"Obstructive shock"}],"answerId":"c","explanation":"Distributive shock, such as early septic shock, presents with warm, flushed skin due to vasodilation.","kind":"recall","origin":"ai"},{"id":"shock-mechanisms-types~ai-2","moduleId":"shock-mechanisms-types","stem":"In a patient with cold, clammy skin and hypotension, which type of shock is most likely?","options":[{"id":"a","text":"Septic shock"},{"id":"b","text":"Hypovolemic shock"},{"id":"c","text":"Neurogenic shock"},{"id":"d","text":"Anaphylactic shock"}],"answerId":"b","explanation":"Cold, clammy skin is indicative of hypovolemic shock, which is associated with vasoconstriction.","kind":"clinical","origin":"ai"},{"id":"shock-mechanisms-types~ai-3","moduleId":"shock-mechanisms-types","stem":"Which sign is most indicative of global hypoperfusion in shock?","options":[{"id":"a","text":"Increased jugular venous pressure"},{"id":"b","text":"Tachycardia"},{"id":"c","text":"Fever"},{"id":"d","text":"Rash"}],"answerId":"b","explanation":"Tachycardia is a compensatory response to global hypoperfusion, commonly seen in shock.","kind":"recall","origin":"ai"},{"id":"shock-mechanisms-types~ai-4","moduleId":"shock-mechanisms-types","stem":"What is the first step in managing a patient in shock?","options":[{"id":"a","text":"Administer vasopressors"},{"id":"b","text":"Identify the cause"},{"id":"c","text":"Start antibiotics"},{"id":"d","text":"Initiate fluid resuscitation"}],"answerId":"b","explanation":"Identifying the cause of shock is crucial before initiating treatment to restore perfusion.","kind":"trap","origin":"ai"},{"id":"shock-mechanisms-types~ai-5","moduleId":"shock-mechanisms-types","stem":"How does hypovolemic shock differ from cardiogenic shock in terms of skin temperature?","options":[{"id":"a","text":"Both present with warm skin"},{"id":"b","text":"Both present with cold skin"},{"id":"c","text":"Hypovolemic shock is warm, cardiogenic is cold"},{"id":"d","text":"Hypovolemic shock is cold, cardiogenic is warm"}],"answerId":"b","explanation":"Both hypovolemic and cardiogenic shock typically present with cold, clammy skin due to vasoconstriction.","kind":"trap","origin":"ai"},{"id":"shock-mechanisms-types~ai-6","moduleId":"shock-mechanisms-types","stem":"In a patient with septic shock, which treatment is most appropriate to restore perfusion?","options":[{"id":"a","text":"Fluid resuscitation"},{"id":"b","text":"Inotropic agents"},{"id":"c","text":"Vasopressors only"},{"id":"d","text":"Antibiotics only"}],"answerId":"a","explanation":"Fluid resuscitation is the first-line treatment for septic shock to restore intravascular volume and perfusion.","kind":"integration","linkedModuleIds":["vasopressors-inotropes"],"origin":"ai"},{"id":"shock-mechanisms-types~ai-7","moduleId":"shock-mechanisms-types","stem":"What is the role of vasopressors in the management of shock?","options":[{"id":"a","text":"Increase cardiac output"},{"id":"b","text":"Increase systemic vascular resistance"},{"id":"c","text":"Decrease heart rate"},{"id":"d","text":"Increase oxygen consumption"}],"answerId":"b","explanation":"Vasopressors are used to increase systemic vascular resistance, helping to improve blood pressure in shock.","kind":"integration","linkedModuleIds":["vasopressors-inotropes"],"origin":"ai"}],"small-vessel-and-venous":[{"id":"small-vessel-and-venous~ai-0","moduleId":"small-vessel-and-venous","stem":"What is the primary ANCA associated with Granulomatosis with polyangiitis (GPA)?","options":[{"id":"a","text":"MPO-ANCA"},{"id":"b","text":"PR3-ANCA"},{"id":"c","text":"c-ANCA"},{"id":"d","text":"p-ANCA"}],"answerId":"b","explanation":"Granulomatosis with polyangiitis (GPA) is primarily associated with PR3-ANCA (c-ANCA).","kind":"recall","origin":"ai"},{"id":"small-vessel-and-venous~ai-1","moduleId":"small-vessel-and-venous","stem":"Which clinical finding is characteristic of microscopic polyangiitis?","options":[{"id":"a","text":"Saddle-nose deformity"},{"id":"b","text":"Hemoptysis"},{"id":"c","text":"Nasal ulcers"},{"id":"d","text":"Leukocytoclastic vasculitis"}],"answerId":"d","explanation":"Microscopic polyangiitis is characterized by leukocytoclastic vasculitis without nasopharyngeal involvement.","kind":"recall","origin":"ai"},{"id":"small-vessel-and-venous~ai-2","moduleId":"small-vessel-and-venous","stem":"What mechanism primarily causes Raynaud phenomenon?","options":[{"id":"a","text":"Venous stasis"},{"id":"b","text":"Cold-induced vasospasm"},{"id":"c","text":"Granulomatous inflammation"},{"id":"d","text":"Hypercoagulability"}],"answerId":"b","explanation":"Raynaud phenomenon is primarily caused by cold-induced vasospasm leading to tri-color changes in digits.","kind":"mechanism","origin":"ai"},{"id":"small-vessel-and-venous~ai-3","moduleId":"small-vessel-and-venous","stem":"A patient presents with migratory thrombophlebitis. What should be suspected?","options":[{"id":"a","text":"IV cannula irritation"},{"id":"b","text":"Pancreatic cancer"},{"id":"c","text":"Deep vein thrombosis"},{"id":"d","text":"Varicose veins"}],"answerId":"b","explanation":"Migratory thrombophlebitis (Trousseau sign) is a paraneoplastic phenomenon often associated with occult visceral malignancy, especially pancreatic cancer.","kind":"clinical","origin":"ai"},{"id":"small-vessel-and-venous~ai-4","moduleId":"small-vessel-and-venous","stem":"Which of the following is a common cause of varicose veins?","options":[{"id":"a","text":"Increased venous pressure"},{"id":"b","text":"Arterial occlusion"},{"id":"c","text":"Lymphatic obstruction"},{"id":"d","text":"Vasospasm"}],"answerId":"a","explanation":"Varicose veins are commonly caused by increased venous pressure due to valve incompetence.","kind":"trap","origin":"ai"},{"id":"small-vessel-and-venous~ai-5","moduleId":"small-vessel-and-venous","stem":"How does Granulomatosis with polyangiitis typically present on a chest radiograph?","options":[{"id":"a","text":"Pleural effusion"},{"id":"b","text":"Consolidation"},{"id":"c","text":"Nodules"},{"id":"d","text":"Atelectasis"}],"answerId":"c","explanation":"Granulomatosis with polyangiitis can present with nodules on chest radiograph due to pulmonary involvement.","kind":"integration","linkedModuleIds":["chest-radiograph-interpretation"],"origin":"ai"},{"id":"small-vessel-and-venous~ai-6","moduleId":"small-vessel-and-venous","stem":"What is a potential complication of pancreatic carcinoma related to venous disease?","options":[{"id":"a","text":"Deep vein thrombosis"},{"id":"b","text":"Pulmonary embolism"},{"id":"c","text":"Migratory thrombophlebitis"},{"id":"d","text":"Varicose veins"}],"answerId":"c","explanation":"Pancreatic carcinoma can lead to migratory thrombophlebitis due to paraneoplastic hypercoagulability.","kind":"integration","linkedModuleIds":["pancreatic-carcinoma"],"origin":"ai"}],"large-medium-vasculitis":[{"id":"large-medium-vasculitis~ai-0","moduleId":"large-medium-vasculitis","stem":"What is the most common age group affected by Giant Cell Arteritis (GCA)?","options":[{"id":"a","text":"<50 years"},{"id":"b","text":"50-70 years"},{"id":"c","text":"70-90 years"},{"id":"d","text":">90 years"}],"answerId":"b","explanation":"Giant Cell Arteritis typically affects individuals over 50 years of age.","kind":"recall","origin":"ai"},{"id":"large-medium-vasculitis~ai-1","moduleId":"large-medium-vasculitis","stem":"Which of the following findings is characteristic of Takayasu arteritis?","options":[{"id":"a","text":"Jaw claudication"},{"id":"b","text":"Absent upper-limb pulses"},{"id":"c","text":"Strawberry tongue"},{"id":"d","text":"Fibrinoid necrosis"}],"answerId":"b","explanation":"Takayasu arteritis is associated with absent or weak upper-limb pulses due to aortic arch involvement.","kind":"recall","origin":"ai"},{"id":"large-medium-vasculitis~ai-2","moduleId":"large-medium-vasculitis","stem":"What is the primary mechanism of injury in Giant Cell Arteritis?","options":[{"id":"a","text":"Thrombosis"},{"id":"b","text":"Granulomatous inflammation"},{"id":"c","text":"Vasospasm"},{"id":"d","text":"Autoimmune destruction"}],"answerId":"b","explanation":"Giant Cell Arteritis is characterized by granulomatous inflammation affecting large and medium-sized arteries.","kind":"mechanism","origin":"ai"},{"id":"large-medium-vasculitis~ai-3","moduleId":"large-medium-vasculitis","stem":"In suspected Giant Cell Arteritis, what is the immediate management step?","options":[{"id":"a","text":"Start high-dose corticosteroids"},{"id":"b","text":"Perform a temporal artery biopsy"},{"id":"c","text":"Initiate aspirin therapy"},{"id":"d","text":"Refer to rheumatology"}],"answerId":"a","explanation":"High-dose corticosteroids should be started immediately to prevent irreversible vision loss in suspected GCA.","kind":"trap","origin":"ai"},{"id":"large-medium-vasculitis~ai-4","moduleId":"large-medium-vasculitis","stem":"Which clinical finding is associated with Kawasaki disease?","options":[{"id":"a","text":"Pulseless disease"},{"id":"b","text":"Strawberry tongue"},{"id":"c","text":"Fibrinoid necrosis"},{"id":"d","text":"Jaw claudication"}],"answerId":"b","explanation":"Kawasaki disease is characterized by mucocutaneous symptoms including strawberry tongue.","kind":"recall","origin":"ai"},{"id":"large-medium-vasculitis~ai-5","moduleId":"large-medium-vasculitis","stem":"How does Polyarteritis Nodosa (PAN) primarily differ from small vessel vasculitis?","options":[{"id":"a","text":"Affects pulmonary arteries"},{"id":"b","text":"Involves medium-sized muscular arteries"},{"id":"c","text":"Is associated with ANCA positivity"},{"id":"d","text":"Primarily affects the skin"}],"answerId":"b","explanation":"PAN affects medium-sized muscular arteries and does not involve pulmonary arteries.","kind":"integration","linkedModuleIds":["small-vessel-and-venous"],"origin":"ai"},{"id":"large-medium-vasculitis~ai-6","moduleId":"large-medium-vasculitis","stem":"Which of the following is a common complication of untreated Kawasaki disease?","options":[{"id":"a","text":"Pulmonary embolism"},{"id":"b","text":"Coronary artery aneurysm"},{"id":"c","text":"Renal failure"},{"id":"d","text":"Visual loss"}],"answerId":"b","explanation":"Untreated Kawasaki disease can lead to coronary artery aneurysms, which are a serious complication.","kind":"integration","linkedModuleIds":["vasculitis-overview"],"origin":"ai"}],"rhabdomyoma-and-tumors":[{"id":"rhabdomyoma-and-tumors~ai-0","moduleId":"rhabdomyoma-and-tumors","stem":"What is the most common primary cardiac tumor in infants?","options":[{"id":"a","text":"Myxoma"},{"id":"b","text":"Rhabdomyoma"},{"id":"c","text":"Angiosarcoma"},{"id":"d","text":"Papillary fibroelastoma"}],"answerId":"b","explanation":"Rhabdomyoma is the most common primary cardiac tumor in infants and is strongly associated with tuberous sclerosis.","kind":"recall","origin":"ai"},{"id":"rhabdomyoma-and-tumors~ai-1","moduleId":"rhabdomyoma-and-tumors","stem":"Which cardiac tumor is characterized by 'spider cells'?","options":[{"id":"a","text":"Myxoma"},{"id":"b","text":"Rhabdomyoma"},{"id":"c","text":"Angiosarcoma"},{"id":"d","text":"Lipoma"}],"answerId":"b","explanation":"Rhabdomyoma is identified by the presence of 'spider cells', which are characteristic of this tumor.","kind":"recall","origin":"ai"},{"id":"rhabdomyoma-and-tumors~ai-2","moduleId":"rhabdomyoma-and-tumors","stem":"A 6-month-old infant presents with seizures and ash-leaf spots. What cardiac tumor is most likely present?","options":[{"id":"a","text":"Myxoma"},{"id":"b","text":"Rhabdomyoma"},{"id":"c","text":"Papillary fibroelastoma"},{"id":"d","text":"Angiosarcoma"}],"answerId":"b","explanation":"The combination of seizures, ash-leaf spots, and age suggests rhabdomyoma, which is associated with tuberous sclerosis.","kind":"clinical","origin":"ai"},{"id":"rhabdomyoma-and-tumors~ai-3","moduleId":"rhabdomyoma-and-tumors","stem":"What is the mechanism of embolic stroke from a cardiac tumor?","options":[{"id":"a","text":"Tumor invasion"},{"id":"b","text":"Fragmentation of a valve lesion"},{"id":"c","text":"Direct extension"},{"id":"d","text":"Hematogenous spread"}],"answerId":"b","explanation":"Embolic strokes can occur when fragments of a papillary fibroelastoma break off and travel to the brain.","kind":"mechanism","origin":"ai"},{"id":"rhabdomyoma-and-tumors~ai-4","moduleId":"rhabdomyoma-and-tumors","stem":"Which of the following is a common presentation of angiosarcoma?","options":[{"id":"a","text":"Asymptomatic with incidental finding"},{"id":"b","text":"Right heart failure with hemorrhagic pericardial effusion"},{"id":"c","text":"Seizures and ash-leaf spots"},{"id":"d","text":"Embolic stroke"}],"answerId":"b","explanation":"Angiosarcoma often presents with right heart failure and can lead to hemorrhagic pericardial effusion due to its aggressive nature.","kind":"recall","origin":"ai"},{"id":"rhabdomyoma-and-tumors~ai-5","moduleId":"rhabdomyoma-and-tumors","stem":"What is the most common primary malignant cardiac tumor?","options":[{"id":"a","text":"Myxoma"},{"id":"b","text":"Rhabdomyoma"},{"id":"c","text":"Angiosarcoma"},{"id":"d","text":"Papillary fibroelastoma"}],"answerId":"c","explanation":"Angiosarcoma is the most common primary malignant cardiac tumor, typically found in the right atrium.","kind":"recall","origin":"ai"},{"id":"rhabdomyoma-and-tumors~ai-6","moduleId":"rhabdomyoma-and-tumors","stem":"A 30-year-old patient presents with a cardiac mass and has a history of breast cancer. Which type of cardiac tumor is most likely?","options":[{"id":"a","text":"Rhabdomyoma"},{"id":"b","text":"Angiosarcoma"},{"id":"c","text":"Myxoma"},{"id":"d","text":"Secondary metastatic tumor"}],"answerId":"d","explanation":"Secondary metastatic tumors can reach the heart via hematogenous spread, especially from breast cancer.","kind":"integration","linkedModuleIds":["cardiac-tumors-overview"],"origin":"ai"},{"id":"rhabdomyoma-and-tumors~ai-7","moduleId":"rhabdomyoma-and-tumors","stem":"In adults, which cardiac tumor is most frequently encountered?","options":[{"id":"a","text":"Rhabdomyoma"},{"id":"b","text":"Myxoma"},{"id":"c","text":"Angiosarcoma"},{"id":"d","text":"Papillary fibroelastoma"}],"answerId":"b","explanation":"Myxoma is the most common primary cardiac tumor in adults, contrasting with rhabdomyoma in children.","kind":"integration","linkedModuleIds":["cardiac-myxoma"],"origin":"ai"}],"vasculitis-overview":[{"id":"vasculitis-overview~ai-0","moduleId":"vasculitis-overview","stem":"What is the primary mechanism of injury in vasculitis?","options":[{"id":"a","text":"Direct infection of blood vessels"},{"id":"b","text":"Immune-mediated inflammation"},{"id":"c","text":"Mechanical obstruction of vessels"},{"id":"d","text":"Vascular smooth muscle hypertrophy"}],"answerId":"b","explanation":"Vasculitis is characterized by immune-mediated inflammation leading to vessel wall injury.","kind":"recall","origin":"ai"},{"id":"vasculitis-overview~ai-1","moduleId":"vasculitis-overview","stem":"Which ANCA type is associated with Granulomatosis with Polyangiitis (GPA)?","options":[{"id":"a","text":"p-ANCA"},{"id":"b","text":"c-ANCA"},{"id":"c","text":"anti-endothelial antibodies"},{"id":"d","text":"anti-nuclear antibodies"}],"answerId":"b","explanation":"c-ANCA, specifically PR3-ANCA, is associated with GPA.","kind":"recall","origin":"ai"},{"id":"vasculitis-overview~ai-2","moduleId":"vasculitis-overview","stem":"A patient presents with fever, fatigue, and palpable purpura. What is the likely underlying mechanism?","options":[{"id":"a","text":"Vascular smooth muscle contraction"},{"id":"b","text":"Cutaneous leukocytoclastic vasculitis"},{"id":"c","text":"Vascular endothelial proliferation"},{"id":"d","text":"Increased blood viscosity"}],"answerId":"b","explanation":"Palpable purpura results from cutaneous leukocytoclastic vasculitis, indicating small-vessel involvement.","kind":"clinical","origin":"ai"},{"id":"vasculitis-overview~ai-3","moduleId":"vasculitis-overview","stem":"In which type of vasculitis would you expect to find MPO-ANCA?","options":[{"id":"a","text":"Giant cell arteritis"},{"id":"b","text":"Takayasu arteritis"},{"id":"c","text":"Microscopic polyangiitis"},{"id":"d","text":"Buerger's disease"}],"answerId":"c","explanation":"MPO-ANCA is associated with microscopic polyangiitis and eosinophilic GPA.","kind":"recall","origin":"ai"},{"id":"vasculitis-overview~ai-4","moduleId":"vasculitis-overview","stem":"Which of the following findings is NOT typically associated with vasculitis?","options":[{"id":"a","text":"Organ-specific ischemia"},{"id":"b","text":"Palpable purpura"},{"id":"c","text":"Elevated blood pressure"},{"id":"d","text":"Systemic inflammation"}],"answerId":"c","explanation":"Elevated blood pressure is not a direct finding of vasculitis; it may occur secondary to other factors.","kind":"trap","origin":"ai"},{"id":"vasculitis-overview~ai-5","moduleId":"vasculitis-overview","stem":"How does cutaneous vasculitis differ from systemic vasculitis in terms of clinical presentation?","options":[{"id":"a","text":"Only affects small vessels"},{"id":"b","text":"Primarily causes systemic symptoms"},{"id":"c","text":"Leads to organ ischemia"},{"id":"d","text":"Is always associated with ANCA positivity"}],"answerId":"a","explanation":"Cutaneous vasculitis primarily affects small vessels and presents with skin manifestations rather than systemic symptoms.","kind":"integration","linkedModuleIds":["cutaneous-vasculitis"],"origin":"ai"},{"id":"vasculitis-overview~ai-6","moduleId":"vasculitis-overview","stem":"What is a common clinical feature shared between large vessel vasculitis and small vessel vasculitis?","options":[{"id":"a","text":"Palpable purpura"},{"id":"b","text":"Fever and malaise"},{"id":"c","text":"Organ-specific ischemia"},{"id":"d","text":"ANCA positivity"}],"answerId":"b","explanation":"Both large and small vessel vasculitis can present with systemic symptoms like fever and malaise.","kind":"integration","linkedModuleIds":["large-medium-vasculitis"],"origin":"ai"}],"pericarditis":[{"id":"pericarditis~ai-0","moduleId":"pericarditis","stem":"What is the most common type of pericarditis associated with uremia and post-MI?","options":[{"id":"a","text":"Serous"},{"id":"b","text":"Fibrinous"},{"id":"c","text":"Purulent"},{"id":"d","text":"Caseous"}],"answerId":"b","explanation":"Fibrinous pericarditis is the most common type associated with uremia and post-MI.","kind":"recall","origin":"ai"},{"id":"pericarditis~ai-1","moduleId":"pericarditis","stem":"Which ECG finding is characteristic of acute pericarditis?","options":[{"id":"a","text":"Convex ST elevation with reciprocal changes"},{"id":"b","text":"Diffuse concave ST elevation + PR depression"},{"id":"c","text":"Isolated T wave inversion"},{"id":"d","text":"Normal ECG"}],"answerId":"b","explanation":"Acute pericarditis is characterized by diffuse concave ST elevation and PR depression without reciprocal changes.","kind":"recall","origin":"ai"},{"id":"pericarditis~ai-2","moduleId":"pericarditis","stem":"What mechanism leads to pleuritic chest pain in acute pericarditis?","options":[{"id":"a","text":"Visceral pleura irritation"},{"id":"b","text":"Inflamed pericardial layers"},{"id":"c","text":"Myocardial ischemia"},{"id":"d","text":"Pulmonary embolism"}],"answerId":"b","explanation":"Pleuritic chest pain in acute pericarditis is due to the inflammation of the pericardial layers.","kind":"mechanism","origin":"ai"},{"id":"pericarditis~ai-3","moduleId":"pericarditis","stem":"A patient presents with chest pain relieved by sitting forward. What is the most likely diagnosis?","options":[{"id":"a","text":"Pulmonary embolism"},{"id":"b","text":"Acute pericarditis"},{"id":"c","text":"Myocardial infarction"},{"id":"d","text":"Aortic dissection"}],"answerId":"b","explanation":"Chest pain that improves when leaning forward is characteristic of acute pericarditis.","kind":"clinical","origin":"ai"},{"id":"pericarditis~ai-4","moduleId":"pericarditis","stem":"Which statement correctly differentiates pericarditis from STEMI regarding ST elevation?","options":[{"id":"a","text":"Both have convex ST elevation"},{"id":"b","text":"Pericarditis has no PR depression"},{"id":"c","text":"Pericarditis shows diffuse concave ST elevation + PR depression"},{"id":"d","text":"ST elevation is always indicative of STEMI"}],"answerId":"c","explanation":"Pericarditis is characterized by diffuse concave ST elevation and PR depression, unlike STEMI which shows convex ST elevation with reciprocal changes.","kind":"trap","origin":"ai"},{"id":"pericarditis~ai-5","moduleId":"pericarditis","stem":"How does acute inflammation relate to the pathophysiology of acute pericarditis?","options":[{"id":"a","text":"It causes myocardial necrosis"},{"id":"b","text":"It triggers pericardial inflammation leading to fibrinous exudate"},{"id":"c","text":"It leads to coronary artery occlusion"},{"id":"d","text":"It results in pulmonary edema"}],"answerId":"b","explanation":"Acute inflammation triggers the inflammatory response in the pericardium, leading to fibrinous exudate.","kind":"integration","linkedModuleIds":["acute-inflammation"],"origin":"ai"},{"id":"pericarditis~ai-6","moduleId":"pericarditis","stem":"In which condition would you expect to find caseous pericarditis?","options":[{"id":"a","text":"Rheumatoid arthritis"},{"id":"b","text":"Tuberculosis"},{"id":"c","text":"Uremia"},{"id":"d","text":"Dressler syndrome"}],"answerId":"b","explanation":"Caseous pericarditis is typically associated with tuberculosis.","kind":"integration","linkedModuleIds":["constrictive-tuberculous-pericarditis"],"origin":"ai"}],"constrictive-tuberculous-pericarditis":[{"id":"constrictive-tuberculous-pericarditis~ai-0","moduleId":"constrictive-tuberculous-pericarditis","stem":"What is the most common cause of tuberculous pericarditis in HIV patients?","options":[{"id":"a","text":"M. tuberculosis"},{"id":"b","text":"Staphylococcus aureus"},{"id":"c","text":"Coxsackievirus"},{"id":"d","text":"HIV itself"}],"answerId":"a","explanation":"M. tuberculosis is the most common cause of pericardial disease in HIV patients, particularly in Africa.","kind":"recall","origin":"ai"},{"id":"constrictive-tuberculous-pericarditis~ai-1","moduleId":"constrictive-tuberculous-pericarditis","stem":"Which finding is characteristic of constrictive pericarditis?","options":[{"id":"a","text":"Kussmaul sign"},{"id":"b","text":"S3 gallop"},{"id":"c","text":"Murmur of mitral regurgitation"},{"id":"d","text":"Pulsus paradoxus"}],"answerId":"a","explanation":"Kussmaul sign, which is the rise of JVP during inspiration, is a hallmark of constrictive pericarditis.","kind":"recall","origin":"ai"},{"id":"constrictive-tuberculous-pericarditis~ai-2","moduleId":"constrictive-tuberculous-pericarditis","stem":"What mechanism leads to the pericardial knock in constrictive pericarditis?","options":[{"id":"a","text":"Increased myocardial contractility"},{"id":"b","text":"Abrupt halt to ventricular filling"},{"id":"c","text":"Increased heart rate"},{"id":"d","text":"Decreased venous return"}],"answerId":"b","explanation":"The pericardial knock occurs due to the abrupt halt to ventricular filling caused by the rigid pericardium.","kind":"mechanism","origin":"ai"},{"id":"constrictive-tuberculous-pericarditis~ai-3","moduleId":"constrictive-tuberculous-pericarditis","stem":"Which of the following is a complication of tuberculous pericarditis that must be prevented?","options":[{"id":"a","text":"Cardiac tamponade"},{"id":"b","text":"Constrictive pericarditis"},{"id":"c","text":"Myocardial infarction"},{"id":"d","text":"Atrial fibrillation"}],"answerId":"b","explanation":"Constrictive pericarditis is a major complication of tuberculous pericarditis that can be prevented with appropriate treatment.","kind":"trap","origin":"ai"},{"id":"constrictive-tuberculous-pericarditis~ai-4","moduleId":"constrictive-tuberculous-pericarditis","stem":"In constrictive pericarditis, what does the presence of pericardial calcification indicate?","options":[{"id":"a","text":"Acute inflammation"},{"id":"b","text":"Chronic constriction"},{"id":"c","text":"Myocardial ischemia"},{"id":"d","text":"Ventricular hypertrophy"}],"answerId":"b","explanation":"Pericardial calcification is indicative of chronic constriction due to fibrosis and inflammation.","kind":"recall","origin":"ai"},{"id":"constrictive-tuberculous-pericarditis~ai-5","moduleId":"constrictive-tuberculous-pericarditis","stem":"How does constrictive pericarditis differ from restrictive cardiomyopathy?","options":[{"id":"a","text":"Both are caused by myocardial ischemia"},{"id":"b","text":"Constrictive pericarditis is surgically curable"},{"id":"c","text":"Restrictive cardiomyopathy has pericardial calcification"},{"id":"d","text":"Both present with dilated hearts"}],"answerId":"b","explanation":"Constrictive pericarditis is a pericardial issue that can often be surgically treated, while restrictive cardiomyopathy is a myocardial problem.","kind":"trap","origin":"ai"},{"id":"constrictive-tuberculous-pericarditis~ai-6","moduleId":"constrictive-tuberculous-pericarditis","stem":"What is the relationship between constrictive pericarditis and acute pericarditis?","options":[{"id":"a","text":"Acute pericarditis always leads to constrictive pericarditis"},{"id":"b","text":"Constrictive pericarditis can develop after untreated acute pericarditis"},{"id":"c","text":"They are unrelated conditions"},{"id":"d","text":"Acute pericarditis is a complication of constrictive pericarditis"}],"answerId":"b","explanation":"Untreated or inadequately treated acute pericarditis can lead to the development of constrictive pericarditis.","kind":"integration","linkedModuleIds":["pericarditis"],"origin":"ai"},{"id":"constrictive-tuberculous-pericarditis~ai-7","moduleId":"constrictive-tuberculous-pericarditis","stem":"Which finding would suggest cardiac tamponade rather than constrictive pericarditis?","options":[{"id":"a","text":"Kussmaul sign"},{"id":"b","text":"Pericardial knock"},{"id":"c","text":"Pulsus paradoxus"},{"id":"d","text":"Pericardial calcification"}],"answerId":"c","explanation":"Pulsus paradoxus is more indicative of cardiac tamponade, while Kussmaul sign and pericardial knock are associated with constrictive pericarditis.","kind":"integration","linkedModuleIds":["cardiac-tamponade"],"origin":"ai"}],"cardiac-tamponade":[{"id":"cardiac-tamponade~ai-0","moduleId":"cardiac-tamponade","stem":"What is the primary physiological consequence of cardiac tamponade?","options":[{"id":"a","text":"Increased venous return"},{"id":"b","text":"Decreased diastolic filling"},{"id":"c","text":"Increased stroke volume"},{"id":"d","text":"Decreased heart rate"}],"answerId":"b","explanation":"Cardiac tamponade leads to increased intrapericardial pressure, which decreases diastolic filling of the heart.","kind":"recall","origin":"ai"},{"id":"cardiac-tamponade~ai-1","moduleId":"cardiac-tamponade","stem":"Which of the following is a classic finding in cardiac tamponade?","options":[{"id":"a","text":"Kussmaul's sign"},{"id":"b","text":"Beck triad"},{"id":"c","text":"Friction rub"},{"id":"d","text":"S3 gallop"}],"answerId":"b","explanation":"Beck triad consists of hypotension, increased JVP, and muffled heart sounds, which are indicative of cardiac tamponade.","kind":"recall","origin":"ai"},{"id":"cardiac-tamponade~ai-2","moduleId":"cardiac-tamponade","stem":"In cardiac tamponade, what does pulsus paradoxus indicate?","options":[{"id":"a","text":"Increased cardiac output"},{"id":"b","text":"Interventricular dependence"},{"id":"c","text":"Decreased heart rate"},{"id":"d","text":"Increased preload"}],"answerId":"b","explanation":"Pulsus paradoxus is due to interventricular dependence in a fixed pericardial volume, leading to a drop in systolic blood pressure during inspiration.","kind":"mechanism","origin":"ai"},{"id":"cardiac-tamponade~ai-3","moduleId":"cardiac-tamponade","stem":"What is the most appropriate initial treatment for cardiac tamponade?","options":[{"id":"a","text":"Diuretics"},{"id":"b","text":"Vasodilators"},{"id":"c","text":"Pericardiocentesis"},{"id":"d","text":"Beta-blockers"}],"answerId":"c","explanation":"Urgent pericardiocentesis is the treatment of choice to relieve the pressure caused by fluid accumulation in cardiac tamponade.","kind":"clinical","origin":"ai"},{"id":"cardiac-tamponade~ai-4","moduleId":"cardiac-tamponade","stem":"Which statement about the volume of fluid in cardiac tamponade is true?","options":[{"id":"a","text":"A large effusion is always required"},{"id":"b","text":"Rate of effusion is more critical than volume"},{"id":"c","text":"Tamponade only occurs with chronic effusions"},{"id":"d","text":"Fluid must exceed 500 mL to cause tamponade"}],"answerId":"b","explanation":"In cardiac tamponade, the rate of fluid accumulation is more critical than the volume; a small, rapidly accumulating effusion can cause tamponade.","kind":"trap","origin":"ai"},{"id":"cardiac-tamponade~ai-5","moduleId":"cardiac-tamponade","stem":"How does cardiac tamponade affect heart sounds during auscultation?","options":[{"id":"a","text":"Increased intensity"},{"id":"b","text":"Decreased intensity"},{"id":"c","text":"Normal intensity"},{"id":"d","text":"Variable intensity"}],"answerId":"b","explanation":"Muffled heart sounds are a characteristic finding in cardiac tamponade due to the insulating effect of the fluid around the heart.","kind":"recall","origin":"ai"},{"id":"cardiac-tamponade~ai-6","moduleId":"cardiac-tamponade","stem":"How might acute pericarditis lead to cardiac tamponade?","options":[{"id":"a","text":"By causing myocardial infarction"},{"id":"b","text":"Through rapid accumulation of inflammatory fluid"},{"id":"c","text":"By inducing arrhythmias"},{"id":"d","text":"By increasing heart rate significantly"}],"answerId":"b","explanation":"Acute pericarditis can lead to rapid accumulation of inflammatory fluid, which may result in cardiac tamponade.","kind":"integration","linkedModuleIds":["pericarditis"],"origin":"ai"},{"id":"cardiac-tamponade~ai-7","moduleId":"cardiac-tamponade","stem":"What is a potential complication of constrictive pericarditis that relates to cardiac tamponade?","options":[{"id":"a","text":"Decreased heart rate"},{"id":"b","text":"Fixed diastolic filling"},{"id":"c","text":"Increased stroke volume"},{"id":"d","text":"Normal venous return"}],"answerId":"b","explanation":"Constrictive pericarditis can lead to fixed diastolic filling, which may mimic or contribute to the effects seen in cardiac tamponade.","kind":"integration","linkedModuleIds":["constrictive-tuberculous-pericarditis"],"origin":"ai"}],"cardiac-tumors-overview":[{"id":"cardiac-tumors-overview~ai-0","moduleId":"cardiac-tumors-overview","stem":"What is the most common primary cardiac tumor in adults?","options":[{"id":"a","text":"Rhabdomyoma"},{"id":"b","text":"Angiosarcoma"},{"id":"c","text":"Myxoma"},{"id":"d","text":"Lymphoma"}],"answerId":"c","explanation":"Myxoma is the most common primary cardiac tumor in adults, while rhabdomyoma is more common in children.","kind":"recall","origin":"ai"},{"id":"cardiac-tumors-overview~ai-1","moduleId":"cardiac-tumors-overview","stem":"Which of the following is the most common cause of cardiac malignancy?","options":[{"id":"a","text":"Angiosarcoma"},{"id":"b","text":"Myxoma"},{"id":"c","text":"Metastatic tumors"},{"id":"d","text":"Lymphoma"}],"answerId":"c","explanation":"Metastatic tumors are the most common cardiac malignancy, significantly outnumbering primary tumors.","kind":"recall","origin":"ai"},{"id":"cardiac-tumors-overview~ai-2","moduleId":"cardiac-tumors-overview","stem":"What is a characteristic feature of angiosarcoma?","options":[{"id":"a","text":"Most common benign tumor"},{"id":"b","text":"Typically affects the left heart"},{"id":"c","text":"Aggressive nature"},{"id":"d","text":"Small size (<5 cm)"}],"answerId":"c","explanation":"Angiosarcoma is the most common primary cardiac malignancy and is known for its aggressive nature.","kind":"mechanism","origin":"ai"},{"id":"cardiac-tumors-overview~ai-3","moduleId":"cardiac-tumors-overview","stem":"A patient presents with symptoms of obstruction and embolic phenomena. What is the most likely type of cardiac mass?","options":[{"id":"a","text":"Myxoma"},{"id":"b","text":"Rhabdomyoma"},{"id":"c","text":"Metastatic tumor"},{"id":"d","text":"Thrombus"}],"answerId":"d","explanation":"Thrombus is the most common intracavitary mass and can cause obstruction and embolic phenomena.","kind":"clinical","origin":"ai"},{"id":"cardiac-tumors-overview~ai-4","moduleId":"cardiac-tumors-overview","stem":"Which of the following findings is associated with metastatic pericardial spread?","options":[{"id":"a","text":"Myxoma"},{"id":"b","text":"Pericardial effusion"},{"id":"c","text":"Rhabdomyoma"},{"id":"d","text":"Thrombus"}],"answerId":"b","explanation":"Pericardial effusion can occur due to metastatic pericardial spread, leading to tamponade.","kind":"mechanism","origin":"ai"},{"id":"cardiac-tumors-overview~ai-5","moduleId":"cardiac-tumors-overview","stem":"Which of the following statements is true regarding cardiac tumors?","options":[{"id":"a","text":"Myxoma is the most common cardiac malignancy"},{"id":"b","text":"Metastatic tumors are more common than primary tumors"},{"id":"c","text":"Rhabdomyoma is the most common primary tumor in adults"},{"id":"d","text":"Angiosarcoma is benign"}],"answerId":"b","explanation":"Metastatic tumors are indeed the most common cardiac malignancy, while myxoma is the most common primary benign tumor.","kind":"trap","origin":"ai"},{"id":"cardiac-tumors-overview~ai-6","moduleId":"cardiac-tumors-overview","stem":"How does the presence of a cardiac myxoma relate to potential embolic events?","options":[{"id":"a","text":"It is always symptomatic"},{"id":"b","text":"It can fragment and cause emboli"},{"id":"c","text":"It is only found in children"},{"id":"d","text":"It is benign and does not cause issues"}],"answerId":"b","explanation":"Cardiac myxomas can fragment and lead to embolic events, which may cause obstruction or ischemia.","kind":"integration","linkedModuleIds":["cardiac-myxoma"],"origin":"ai"},{"id":"cardiac-tumors-overview~ai-7","moduleId":"cardiac-tumors-overview","stem":"In which cardiac condition would you expect to see pericardial effusion due to lymphatic obstruction?","options":[{"id":"a","text":"Myxoma"},{"id":"b","text":"Angiosarcoma"},{"id":"c","text":"Rhabdomyoma"},{"id":"d","text":"Metastatic tumors"}],"answerId":"d","explanation":"Metastatic tumors can lead to pericardial effusion due to lymphatic obstruction, causing symptoms of tamponade.","kind":"integration","linkedModuleIds":["cardiac-myxoma"],"origin":"ai"}],"htn-diuretics-raas":[{"id":"htn-diuretics-raas~ai-0","moduleId":"htn-diuretics-raas","stem":"Which diuretic primarily acts on the distal convoluted tubule (DCT)?","options":[{"id":"a","text":"Furosemide"},{"id":"b","text":"Hydrochlorothiazide"},{"id":"c","text":"Spironolactone"},{"id":"d","text":"Amiloride"}],"answerId":"b","explanation":"Hydrochlorothiazide is a thiazide diuretic that acts on the NCC in the DCT.","kind":"recall","origin":"ai"},{"id":"htn-diuretics-raas~ai-1","moduleId":"htn-diuretics-raas","stem":"What is the primary adverse effect of loop diuretics like furosemide?","options":[{"id":"a","text":"Hyperkalemia"},{"id":"b","text":"Ototoxicity"},{"id":"c","text":"Hypocalcemia"},{"id":"d","text":"Gynecomastia"}],"answerId":"b","explanation":"Loop diuretics, such as furosemide, can cause ototoxicity as a significant adverse effect.","kind":"recall","origin":"ai"},{"id":"htn-diuretics-raas~ai-2","moduleId":"htn-diuretics-raas","stem":"Which mechanism explains the hypokalemia seen with thiazide diuretics?","options":[{"id":"a","text":"Increased potassium reabsorption"},{"id":"b","text":"Decreased potassium secretion"},{"id":"c","text":"Distal K⁺ wasting"},{"id":"d","text":"Inhibition of aldosterone"}],"answerId":"c","explanation":"Thiazide diuretics cause distal K⁺ wasting, leading to hypokalemia.","kind":"mechanism","origin":"ai"},{"id":"htn-diuretics-raas~ai-3","moduleId":"htn-diuretics-raas","stem":"A patient develops a dry cough after starting an ACE inhibitor. What is the best management strategy?","options":[{"id":"a","text":"Add an antitussive and continue the ACEi"},{"id":"b","text":"Switch to a thiazide diuretic"},{"id":"c","text":"Switch to an ARB"},{"id":"d","text":"Increase the ACEi dose"}],"answerId":"c","explanation":"The dry cough is due to bradykinin accumulation; switching to an ARB resolves this issue.","kind":"trap","origin":"ai"},{"id":"htn-diuretics-raas~ai-4","moduleId":"htn-diuretics-raas","stem":"What is the primary action of spironolactone?","options":[{"id":"a","text":"Inhibition of NKCC2"},{"id":"b","text":"Aldosterone receptor antagonism"},{"id":"c","text":"Inhibition of NCC"},{"id":"d","text":"Inhibition of ACE"}],"answerId":"b","explanation":"Spironolactone acts as an aldosterone receptor antagonist, which leads to potassium retention.","kind":"recall","origin":"ai"},{"id":"htn-diuretics-raas~ai-5","moduleId":"htn-diuretics-raas","stem":"Which of the following findings is associated with spironolactone use?","options":[{"id":"a","text":"Hypokalemia"},{"id":"b","text":"Hyperuricemia"},{"id":"c","text":"Gynecomastia"},{"id":"d","text":"Dry cough"}],"answerId":"c","explanation":"Spironolactone can cause gynecomastia due to its androgen-receptor antagonism.","kind":"recall","origin":"ai"},{"id":"htn-diuretics-raas~ai-6","moduleId":"htn-diuretics-raas","stem":"How does the RAAS system interact with diuretics in managing hypertension?","options":[{"id":"a","text":"Diuretics increase renin release"},{"id":"b","text":"Diuretics decrease aldosterone levels"},{"id":"c","text":"RAAS inhibitors enhance diuretic efficacy"},{"id":"d","text":"Diuretics block angiotensin II formation"}],"answerId":"c","explanation":"RAAS inhibitors like ACEi and ARBs enhance the efficacy of diuretics by counteracting fluid retention.","kind":"integration","linkedModuleIds":["antihypertensive-overview"],"origin":"ai"},{"id":"htn-diuretics-raas~ai-7","moduleId":"htn-diuretics-raas","stem":"What is a common adverse effect shared by both ACE inhibitors and ARBs?","options":[{"id":"a","text":"Dry cough"},{"id":"b","text":"Hyperkalemia"},{"id":"c","text":"Ototoxicity"},{"id":"d","text":"Gynecomastia"}],"answerId":"b","explanation":"Both ACE inhibitors and ARBs can cause hyperkalemia due to their effects on renal potassium handling.","kind":"integration","linkedModuleIds":["htn-ccb-sympatholytics"],"origin":"ai"}],"pericardial-effusion":[{"id":"pericardial-effusion~ai-0","moduleId":"pericardial-effusion","stem":"What is the normal volume of pericardial fluid in a healthy individual?","options":[{"id":"a","text":"15–50 mL"},{"id":"b","text":"50–100 mL"},{"id":"c","text":"100–150 mL"},{"id":"d","text":"150–200 mL"}],"answerId":"a","explanation":"Normal pericardial fluid volume ranges from 15 to 50 mL.","kind":"recall","origin":"ai"},{"id":"pericardial-effusion~ai-1","moduleId":"pericardial-effusion","stem":"Which of the following is a characteristic finding on ECG in pericardial effusion?","options":[{"id":"a","text":"ST elevation"},{"id":"b","text":"Low voltage + electrical alternans"},{"id":"c","text":"Q waves"},{"id":"d","text":"T wave inversion"}],"answerId":"b","explanation":"ECG findings in pericardial effusion typically include low voltage and electrical alternans due to the insulating effect of the fluid.","kind":"recall","origin":"ai"},{"id":"pericardial-effusion~ai-2","moduleId":"pericardial-effusion","stem":"What distinguishes an exudate from a transudate in pericardial effusion?","options":[{"id":"a","text":"Fluid LDH < 300 U/L"},{"id":"b","text":"Pericardial/serum protein > 0.5"},{"id":"c","text":"Pericardial/serum albumin < 1.1"},{"id":"d","text":"Fluid appearance is clear"}],"answerId":"b","explanation":"An exudate is defined by Light's criteria, which includes a pericardial/serum protein ratio greater than 0.5.","kind":"mechanism","origin":"ai"},{"id":"pericardial-effusion~ai-3","moduleId":"pericardial-effusion","stem":"A patient presents with muffled heart sounds and dyspnea. What is the most likely cause of these findings?","options":[{"id":"a","text":"Aortic dissection"},{"id":"b","text":"Pericardial effusion"},{"id":"c","text":"Pulmonary embolism"},{"id":"d","text":"Myocardial infarction"}],"answerId":"b","explanation":"Muffled heart sounds and dyspnea are classic signs of pericardial effusion due to fluid accumulation compressing the heart.","kind":"clinical","origin":"ai"},{"id":"pericardial-effusion~ai-4","moduleId":"pericardial-effusion","stem":"In a patient with suspected pericardial effusion, which of the following findings would indicate a tuberculous etiology?","options":[{"id":"a","text":"Fluid LDH > 300 U/L"},{"id":"b","text":"Pericardial/serum protein ratio > 0.5"},{"id":"c","text":"ADA > 40 U/L"},{"id":"d","text":"Serosanguineous fluid appearance"}],"answerId":"c","explanation":"An ADA level greater than 40 U/L in pericardial fluid is suggestive of tuberculous pericarditis.","kind":"recall","origin":"ai"},{"id":"pericardial-effusion~ai-5","moduleId":"pericardial-effusion","stem":"Which of the following mechanisms explains the presence of dyspnea in pericardial effusion?","options":[{"id":"a","text":"Increased pulmonary vascular resistance"},{"id":"b","text":"Compression of the lung"},{"id":"c","text":"Decreased cardiac output"},{"id":"d","text":"Increased intrathoracic pressure"}],"answerId":"b","explanation":"Dyspnea in pericardial effusion can occur due to compression of the lung by the accumulated fluid.","kind":"mechanism","origin":"ai"},{"id":"pericardial-effusion~ai-6","moduleId":"pericardial-effusion","stem":"How does pericardial effusion relate to acute inflammation?","options":[{"id":"a","text":"It is a direct result of myocardial infarction."},{"id":"b","text":"It is characterized by increased hydrostatic pressure."},{"id":"c","text":"It can result from inflammatory processes leading to fluid accumulation."},{"id":"d","text":"It is always a transudate."}],"answerId":"c","explanation":"Pericardial effusion can result from inflammatory processes, which lead to fluid accumulation in the pericardial space.","kind":"integration","linkedModuleIds":["acute-inflammation"],"origin":"ai"},{"id":"pericardial-effusion~ai-7","moduleId":"pericardial-effusion","stem":"Which of the following findings would suggest a diagnosis of cardiac tamponade rather than pericardial effusion alone?","options":[{"id":"a","text":"Muffled heart sounds"},{"id":"b","text":"Electrical alternans"},{"id":"c","text":"Hypotension"},{"id":"d","text":"Dyspnea"}],"answerId":"c","explanation":"Hypotension is a key finding in cardiac tamponade, indicating compromised cardiac output due to the pressure from fluid accumulation.","kind":"integration","linkedModuleIds":["cardiac-tamponade"],"origin":"ai"}],"cardiac-myxoma":[{"id":"cardiac-myxoma~ai-0","moduleId":"cardiac-myxoma","stem":"What is the most common primary cardiac tumor in adults?","options":[{"id":"a","text":"Rhabdomyoma"},{"id":"b","text":"Cardiac myxoma"},{"id":"c","text":"Fibroma"},{"id":"d","text":"Hemangioma"}],"answerId":"b","explanation":"Cardiac myxoma is the most common primary cardiac tumor in adults.","kind":"recall","origin":"ai"},{"id":"cardiac-myxoma~ai-1","moduleId":"cardiac-myxoma","stem":"Where do most cardiac myxomas typically arise?","options":[{"id":"a","text":"Right atrium"},{"id":"b","text":"Left atrium"},{"id":"c","text":"Ventricles"},{"id":"d","text":"Pericardium"}],"answerId":"b","explanation":"Approximately 90% of cardiac myxomas arise in the left atrium.","kind":"recall","origin":"ai"},{"id":"cardiac-myxoma~ai-2","moduleId":"cardiac-myxoma","stem":"What is the mechanism of intermittent obstruction caused by a pedunculated cardiac myxoma?","options":[{"id":"a","text":"Fixed obstruction of the mitral valve"},{"id":"b","text":"Ball-valve obstruction during diastole"},{"id":"c","text":"Aortic stenosis"},{"id":"d","text":"Pulmonary embolism"}],"answerId":"b","explanation":"A pedunculated mass can prolapse across the mitral valve during diastole, causing intermittent ball-valve obstruction.","kind":"mechanism","origin":"ai"},{"id":"cardiac-myxoma~ai-3","moduleId":"cardiac-myxoma","stem":"Which clinical finding is characteristic of a cardiac myxoma?","options":[{"id":"a","text":"Continuous murmur"},{"id":"b","text":"Diastolic murmur with a tumor plop"},{"id":"c","text":"Systolic ejection murmur"},{"id":"d","text":"Pulsus paradoxus"}],"answerId":"b","explanation":"A diastolic murmur with a 'tumor plop' is indicative of a mobile mass causing obstruction.","kind":"clinical","origin":"ai"},{"id":"cardiac-myxoma~ai-4","moduleId":"cardiac-myxoma","stem":"What distinguishes a cardiac myxoma from rheumatic mitral stenosis in terms of obstruction?","options":[{"id":"a","text":"Fixed obstruction"},{"id":"b","text":"Positional/intermittent obstruction with a tumor plop"},{"id":"c","text":"Systolic obstruction"},{"id":"d","text":"No associated symptoms"}],"answerId":"b","explanation":"Cardiac myxoma causes positional/intermittent obstruction with a characteristic 'tumor plop', unlike fixed obstruction seen in rheumatic mitral stenosis.","kind":"trap","origin":"ai"},{"id":"cardiac-myxoma~ai-5","moduleId":"cardiac-myxoma","stem":"What is a common systemic symptom associated with cardiac myxoma?","options":[{"id":"a","text":"Chest pain"},{"id":"b","text":"Fever and weight loss"},{"id":"c","text":"Palpitations"},{"id":"d","text":"Hypertension"}],"answerId":"b","explanation":"Constitutional symptoms such as fever and weight loss are commonly associated with cardiac myxomas due to IL-6 secretion.","kind":"recall","origin":"ai"},{"id":"cardiac-myxoma~ai-6","moduleId":"cardiac-myxoma","stem":"How does a cardiac myxoma relate to the auscultation of heart sounds?","options":[{"id":"a","text":"It causes a continuous murmur"},{"id":"b","text":"It creates a diastolic murmur with a tumor plop"},{"id":"c","text":"It produces a systolic murmur"},{"id":"d","text":"It has no effect on heart sounds"}],"answerId":"b","explanation":"A cardiac myxoma can cause a diastolic murmur with a characteristic 'tumor plop' sound during auscultation.","kind":"integration","linkedModuleIds":["heart-sounds-murmurs-auscultation"],"origin":"ai"},{"id":"cardiac-myxoma~ai-7","moduleId":"cardiac-myxoma","stem":"Which histological feature is characteristic of cardiac myxoma?","options":[{"id":"a","text":"Fibrous tissue"},{"id":"b","text":"Stellate/globular myxoma cells"},{"id":"c","text":"Calcification"},{"id":"d","text":"Lymphoid aggregates"}],"answerId":"b","explanation":"Cardiac myxomas are characterized by stellate/globular myxoma cells in a myxoid background.","kind":"recall","origin":"ai"},{"id":"cardiac-myxoma~ai-8","moduleId":"cardiac-myxoma","stem":"How does the presence of a cardiac myxoma relate to other cardiac tumors like rhabdomyoma?","options":[{"id":"a","text":"Both are benign tumors"},{"id":"b","text":"Only myxomas cause obstruction"},{"id":"c","text":"Rhabdomyomas are more common in adults"},{"id":"d","text":"Both are malignant tumors"}],"answerId":"a","explanation":"Both cardiac myxomas and rhabdomyomas are considered benign tumors, though they differ in prevalence and demographics.","kind":"integration","linkedModuleIds":["rhabdomyoma-and-tumors"],"origin":"ai"}],"htn-ccb-sympatholytics":[{"id":"htn-ccb-sympatholytics~ai-0","moduleId":"htn-ccb-sympatholytics","stem":"What is the primary mechanism of action of dihydropyridine calcium channel blockers (DHP-CCBs) in treating hypertension?","options":[{"id":"a","text":"Increased cardiac output"},{"id":"b","text":"Decreased peripheral vascular resistance"},{"id":"c","text":"Increased heart rate"},{"id":"d","text":"Decreased renal blood flow"}],"answerId":"b","explanation":"DHP-CCBs primarily decrease peripheral vascular resistance by blocking calcium channels in vascular smooth muscle.","kind":"mechanism","origin":"ai"},{"id":"htn-ccb-sympatholytics~ai-1","moduleId":"htn-ccb-sympatholytics","stem":"Which side effect is commonly associated with dihydropyridine calcium channel blockers?","options":[{"id":"a","text":"Bradycardia"},{"id":"b","text":"First-dose hypotension"},{"id":"c","text":"Ankle edema"},{"id":"d","text":"Constipation"}],"answerId":"c","explanation":"DHP-CCBs can cause ankle edema due to precapillary arteriolar vasodilation, not fluid overload.","kind":"trap","origin":"ai"},{"id":"htn-ccb-sympatholytics~ai-2","moduleId":"htn-ccb-sympatholytics","stem":"What is a potential adverse effect of non-dihydropyridine calcium channel blockers?","options":[{"id":"a","text":"Reflex tachycardia"},{"id":"b","text":"Peripheral edema"},{"id":"c","text":"Bradycardia"},{"id":"d","text":"Postural hypotension"}],"answerId":"c","explanation":"Non-DHP-CCBs like verapamil and diltiazem can cause bradycardia due to their effects on the heart.","kind":"recall","origin":"ai"},{"id":"htn-ccb-sympatholytics~ai-3","moduleId":"htn-ccb-sympatholytics","stem":"What is the mechanism of action of α1-blockers in hypertension management?","options":[{"id":"a","text":"Inhibition of renin release"},{"id":"b","text":"Decreased heart rate"},{"id":"c","text":"Decreased peripheral vascular resistance"},{"id":"d","text":"Increased venous return"}],"answerId":"c","explanation":"α1-blockers decrease peripheral vascular resistance by causing vasodilation.","kind":"mechanism","origin":"ai"},{"id":"htn-ccb-sympatholytics~ai-4","moduleId":"htn-ccb-sympatholytics","stem":"A patient on a DHP-CCB develops bilateral pedal edema. What is the best management strategy?","options":[{"id":"a","text":"Increase the DHP-CCB dose"},{"id":"b","text":"Add a diuretic"},{"id":"c","text":"Switch to a non-DHP-CCB"},{"id":"d","text":"Reduce the DHP-CCB dose or add an ACE inhibitor"}],"answerId":"d","explanation":"The edema is due to precapillary vasodilation, not fluid overload; thus, diuretics are ineffective.","kind":"trap","origin":"ai"},{"id":"htn-ccb-sympatholytics~ai-5","moduleId":"htn-ccb-sympatholytics","stem":"Which antihypertensive class is contraindicated in pregnancy?","options":[{"id":"a","text":"ACE inhibitors"},{"id":"b","text":"Calcium channel blockers"},{"id":"c","text":"β-blockers"},{"id":"d","text":"α1-blockers"}],"answerId":"a","explanation":"ACE inhibitors are contraindicated in pregnancy due to potential teratogenic effects.","kind":"recall","origin":"ai"},{"id":"htn-ccb-sympatholytics~ai-6","moduleId":"htn-ccb-sympatholytics","stem":"How do sympatholytics like clonidine lead to rebound hypertension upon withdrawal?","options":[{"id":"a","text":"Increased renin release"},{"id":"b","text":"Increased sympathetic outflow"},{"id":"c","text":"Decreased peripheral resistance"},{"id":"d","text":"Increased heart rate"}],"answerId":"b","explanation":"Clonidine withdrawal leads to increased sympathetic outflow, causing rebound hypertension.","kind":"mechanism","origin":"ai"},{"id":"htn-ccb-sympatholytics~ai-7","moduleId":"htn-ccb-sympatholytics","stem":"How do calcium channel blockers relate to diuretics in managing hypertension?","options":[{"id":"a","text":"Both increase renal blood flow"},{"id":"b","text":"Both decrease peripheral vascular resistance"},{"id":"c","text":"Both are first-line agents for all patients"},{"id":"d","text":"Both can cause electrolyte imbalances"}],"answerId":"b","explanation":"Both calcium channel blockers and diuretics decrease peripheral vascular resistance, but they act through different mechanisms.","kind":"integration","linkedModuleIds":["htn-diuretics-raas"],"origin":"ai"},{"id":"htn-ccb-sympatholytics~ai-8","moduleId":"htn-ccb-sympatholytics","stem":"What is the main difference in action between DHP-CCBs and non-DHP-CCBs?","options":[{"id":"a","text":"DHP-CCBs affect heart rate, non-DHP-CCBs do not"},{"id":"b","text":"DHP-CCBs primarily affect vascular smooth muscle, non-DHP-CCBs affect the heart"},{"id":"c","text":"DHP-CCBs are more effective in heart failure"},{"id":"d","text":"DHP-CCBs are contraindicated in pregnancy"}],"answerId":"b","explanation":"DHP-CCBs primarily target vascular smooth muscle, while non-DHP-CCBs also affect heart rate and contractility.","kind":"integration","linkedModuleIds":["antihypertensive-overview"],"origin":"ai"}],"vestibular-system-reflexes":[{"id":"vestibular-system-reflexes~ai-0","moduleId":"vestibular-system-reflexes","stem":"Which structure in the vestibular system is responsible for sensing linear acceleration?","options":[{"id":"a","text":"Semicircular canals"},{"id":"b","text":"Utricle"},{"id":"c","text":"Saccule"},{"id":"d","text":"Cochlea"}],"answerId":"b","explanation":"The utricle and saccule are otolith organs that detect linear acceleration and gravity.","kind":"recall","origin":"ai"},{"id":"vestibular-system-reflexes~ai-1","moduleId":"vestibular-system-reflexes","stem":"What is the primary function of the vestibulo-ocular reflex (VOR)?","options":[{"id":"a","text":"Maintain balance during standing"},{"id":"b","text":"Stabilize gaze during head movement"},{"id":"c","text":"Detect sound vibrations"},{"id":"d","text":"Control eye movements in darkness"}],"answerId":"b","explanation":"The VOR helps keep the gaze stable by coordinating eye movements with head movements.","kind":"mechanism","origin":"ai"},{"id":"vestibular-system-reflexes~ai-2","moduleId":"vestibular-system-reflexes","stem":"A patient presents with positional vertigo and fatigable nystagmus during the Dix-Hallpike maneuver. What is the most likely diagnosis?","options":[{"id":"a","text":"Vestibular neuritis"},{"id":"b","text":"Benign paroxysmal positional vertigo (BPPV)"},{"id":"c","text":"Ménière's disease"},{"id":"d","text":"Central vertigo"}],"answerId":"b","explanation":"Fatigable nystagmus with positional vertigo is characteristic of BPPV.","kind":"clinical","origin":"ai"},{"id":"vestibular-system-reflexes~ai-3","moduleId":"vestibular-system-reflexes","stem":"In a comatose patient, the absence of the Doll's-eye reflex suggests which of the following?","options":[{"id":"a","text":"Normal brain function"},{"id":"b","text":"Peripheral vestibular dysfunction"},{"id":"c","text":"Brainstem lesion"},{"id":"d","text":"Cerebellar dysfunction"}],"answerId":"c","explanation":"An absent Doll's-eye reflex indicates a lesion in the brainstem, specifically in the midbrain or pons.","kind":"clinical","origin":"ai"},{"id":"vestibular-system-reflexes~ai-4","moduleId":"vestibular-system-reflexes","stem":"Which of the following findings would suggest a central cause of vertigo?","options":[{"id":"a","text":"Unidirectional nystagmus"},{"id":"b","text":"Fatigable nystagmus"},{"id":"c","text":"Direction-changing nystagmus"},{"id":"d","text":"Normal head-impulse test"}],"answerId":"c","explanation":"Direction-changing nystagmus, especially with other neurological signs, suggests a central cause.","kind":"trap","origin":"ai"},{"id":"vestibular-system-reflexes~ai-5","moduleId":"vestibular-system-reflexes","stem":"How does the vestibular system integrate with the extraocular muscles during head movement?","options":[{"id":"a","text":"Through the cochlear nucleus"},{"id":"b","text":"Via the oculomotor nerve only"},{"id":"c","text":"Through the vestibular nuclei"},{"id":"d","text":"By direct connections to the retina"}],"answerId":"c","explanation":"The vestibular nuclei communicate with the extraocular muscle nuclei to coordinate eye movements during head motion.","kind":"integration","linkedModuleIds":["extraocular-muscles"],"origin":"ai"},{"id":"vestibular-system-reflexes~ai-6","moduleId":"vestibular-system-reflexes","stem":"In a patient with central vertigo, which additional neurological sign is most likely to be present?","options":[{"id":"a","text":"Hearing loss"},{"id":"b","text":"Tinnitus"},{"id":"c","text":"Ataxia"},{"id":"d","text":"Nausea only"}],"answerId":"c","explanation":"Central vertigo often presents with additional neurological signs such as ataxia, which is not typical of peripheral causes.","kind":"integration","linkedModuleIds":["gaze-pathways-ino"],"origin":"ai"}],"basal-ganglia-cerebellum":[{"id":"basal-ganglia-cerebellum~ai-0","moduleId":"basal-ganglia-cerebellum","stem":"What is the primary neurotransmitter lost in Parkinson's disease affecting the basal ganglia?","options":[{"id":"a","text":"Serotonin"},{"id":"b","text":"Norepinephrine"},{"id":"c","text":"Dopamine"},{"id":"d","text":"Acetylcholine"}],"answerId":"c","explanation":"Dopamine loss from the substantia nigra is the hallmark of Parkinson's disease, leading to motor symptoms.","kind":"recall","origin":"ai"},{"id":"basal-ganglia-cerebellum~ai-1","moduleId":"basal-ganglia-cerebellum","stem":"A patient presents with intention tremor and dysmetria. Which part of the brain is most likely affected?","options":[{"id":"a","text":"Basal ganglia"},{"id":"b","text":"Cerebellum"},{"id":"c","text":"Frontal lobe"},{"id":"d","text":"Brainstem"}],"answerId":"b","explanation":"Intention tremor and dysmetria are indicative of a neocerebellar lesion.","kind":"mechanism","origin":"ai"},{"id":"basal-ganglia-cerebellum~ai-2","moduleId":"basal-ganglia-cerebellum","stem":"Which clinical finding is characteristic of hemiballismus?","options":[{"id":"a","text":"Resting tremor"},{"id":"b","text":"Dysdiadochokinesia"},{"id":"c","text":"Unilateral wild flinging"},{"id":"d","text":"Cogwheel rigidity"}],"answerId":"c","explanation":"Hemiballismus is characterized by unilateral wild flinging movements due to a contralateral subthalamic nucleus lesion.","kind":"recall","origin":"ai"},{"id":"basal-ganglia-cerebellum~ai-3","moduleId":"basal-ganglia-cerebellum","stem":"A patient exhibits a resting tremor that eases with movement. This finding is most consistent with which condition?","options":[{"id":"a","text":"Cerebellar ataxia"},{"id":"b","text":"Parkinson's disease"},{"id":"c","text":"Huntington's disease"},{"id":"d","text":"Essential tremor"}],"answerId":"b","explanation":"A resting tremor that improves with movement is characteristic of Parkinson's disease.","kind":"trap","origin":"ai"},{"id":"basal-ganglia-cerebellum~ai-4","moduleId":"basal-ganglia-cerebellum","stem":"In a patient with a lesion in the posterior lobe of the cerebellum, which symptom would you expect?","options":[{"id":"a","text":"Postural instability"},{"id":"b","text":"Ataxia"},{"id":"c","text":"Bradykinesia"},{"id":"d","text":"Pill-rolling tremor"}],"answerId":"b","explanation":"Lesions in the posterior lobe of the cerebellum typically result in ataxia and intention tremors.","kind":"clinical","origin":"ai"},{"id":"basal-ganglia-cerebellum~ai-5","moduleId":"basal-ganglia-cerebellum","stem":"A patient with a basal ganglia lesion presents with bradykinesia and rigidity. Which linked module's concepts are most relevant to understanding this patient's symptoms?","options":[{"id":"a","text":"Brainstem Syndromes"},{"id":"b","text":"Cerebral Cortex & Stroke Syndromes"},{"id":"c","text":"Basal Ganglia Circuitry"},{"id":"d","text":"Spinal Cord Syndromes"}],"answerId":"c","explanation":"The basal ganglia circuitry module provides essential insights into the mechanisms of movement disorders like bradykinesia and rigidity.","kind":"integration","linkedModuleIds":["basal-ganglia-circuitry"],"origin":"ai"},{"id":"basal-ganglia-cerebellum~ai-6","moduleId":"basal-ganglia-cerebellum","stem":"A patient with a subthalamic nucleus lesion exhibits wild flinging movements. Which other module's findings could help in managing this patient?","options":[{"id":"a","text":"Cerebral Cortex & Stroke Syndromes"},{"id":"b","text":"Brainstem Syndromes"},{"id":"c","text":"Neuro Localization Framework"},{"id":"d","text":"Spinal Cord Syndromes"}],"answerId":"b","explanation":"Understanding brainstem syndromes can provide insight into the motor pathways affected by basal ganglia lesions.","kind":"integration","linkedModuleIds":["brainstem-syndromes"],"origin":"ai"}],"extraocular-muscles":[{"id":"extraocular-muscles~ai-0","moduleId":"extraocular-muscles","stem":"Which cranial nerve is responsible for innervating the lateral rectus muscle?","options":[{"id":"a","text":"CN III"},{"id":"b","text":"CN IV"},{"id":"c","text":"CN V"},{"id":"d","text":"CN VI"}],"answerId":"d","explanation":"The lateral rectus muscle is innervated by CN VI (abducens nerve).","kind":"recall","origin":"ai"},{"id":"extraocular-muscles~ai-1","moduleId":"extraocular-muscles","stem":"What is the primary action of the superior oblique muscle?","options":[{"id":"a","text":"Elevation"},{"id":"b","text":"Depression"},{"id":"c","text":"Intorsion"},{"id":"d","text":"Abduction"}],"answerId":"c","explanation":"The superior oblique muscle primarily intorts the eye.","kind":"recall","origin":"ai"},{"id":"extraocular-muscles~ai-2","moduleId":"extraocular-muscles","stem":"A patient presents with a 'down-and-out' eye, ptosis, and a fixed dilated pupil. Which cranial nerve is likely affected?","options":[{"id":"a","text":"CN II"},{"id":"b","text":"CN III"},{"id":"c","text":"CN IV"},{"id":"d","text":"CN VI"}],"answerId":"b","explanation":"These symptoms are characteristic of a CN III palsy.","kind":"clinical","origin":"ai"},{"id":"extraocular-muscles~ai-3","moduleId":"extraocular-muscles","stem":"In which position should the eye be placed to isolate the action of the superior oblique muscle during testing?","options":[{"id":"a","text":"Abducted and looking down"},{"id":"b","text":"Adducted and looking down"},{"id":"c","text":"Abducted and looking up"},{"id":"d","text":"Adducted and looking up"}],"answerId":"b","explanation":"The superior oblique's action is isolated when the eye is adducted and looking down.","kind":"trap","origin":"ai"},{"id":"extraocular-muscles~ai-4","moduleId":"extraocular-muscles","stem":"A patient with CN IV palsy presents with vertical diplopia and compensatory head tilt. Which clinical test would best demonstrate the affected muscle's function?","options":[{"id":"a","text":"Looking straight ahead"},{"id":"b","text":"Looking down and out"},{"id":"c","text":"Looking down and in"},{"id":"d","text":"Looking up and in"}],"answerId":"c","explanation":"The superior oblique muscle's function is best tested by having the patient look down and in.","kind":"clinical","origin":"ai"},{"id":"extraocular-muscles~ai-5","moduleId":"extraocular-muscles","stem":"Which cranial nerve palsy would result in an inability to abduct the eye, leading to esotropia at rest?","options":[{"id":"a","text":"CN II"},{"id":"b","text":"CN III"},{"id":"c","text":"CN IV"},{"id":"d","text":"CN VI"}],"answerId":"d","explanation":"CN VI palsy results in an inability to abduct the eye, causing esotropia.","kind":"clinical","origin":"ai"},{"id":"extraocular-muscles~ai-6","moduleId":"extraocular-muscles","stem":"How does the function of the extraocular muscles relate to the pupillary reflex?","options":[{"id":"a","text":"Both are controlled by CN III"},{"id":"b","text":"Both involve CN VI"},{"id":"c","text":"Both are tested by eye movement"},{"id":"d","text":"Both affect facial symmetry"}],"answerId":"a","explanation":"The pupillary reflex involves parasympathetic fibers from CN III, which also innervates most extraocular muscles.","kind":"integration","linkedModuleIds":["pupillary-reflexes-horner"],"origin":"ai"},{"id":"extraocular-muscles~ai-7","moduleId":"extraocular-muscles","stem":"Which cranial nerve pathway is essential for coordinating eye movements and could be affected in a patient with extraocular muscle dysfunction?","options":[{"id":"a","text":"Corticobulbar tract"},{"id":"b","text":"Medial longitudinal fasciculus"},{"id":"c","text":"Optic tract"},{"id":"d","text":"Trigeminal nerve pathway"}],"answerId":"b","explanation":"The medial longitudinal fasciculus coordinates eye movements and could be affected in disorders involving extraocular muscles.","kind":"integration","linkedModuleIds":["gaze-pathways-ino"],"origin":"ai"}],"spinal-cord-syndromes":[{"id":"spinal-cord-syndromes~ai-0","moduleId":"spinal-cord-syndromes","stem":"What is the primary function of the dorsal columns in the spinal cord?","options":[{"id":"a","text":"Pain sensation"},{"id":"b","text":"Temperature sensation"},{"id":"c","text":"Touch and proprioception"},{"id":"d","text":"Motor control"}],"answerId":"c","explanation":"The dorsal columns are responsible for transmitting touch and proprioception sensations.","kind":"recall","origin":"ai"},{"id":"spinal-cord-syndromes~ai-1","moduleId":"spinal-cord-syndromes","stem":"In a Brown-Séquard syndrome, which of the following findings is expected?","options":[{"id":"a","text":"Contralateral loss of touch sensation"},{"id":"b","text":"Ipsilateral loss of pain sensation"},{"id":"c","text":"Ipsilateral weakness at the level of the lesion"},{"id":"d","text":"Contralateral weakness below the lesion"}],"answerId":"c","explanation":"Brown-Séquard syndrome presents with ipsilateral weakness at the level of the lesion due to corticospinal tract involvement.","kind":"clinical","origin":"ai"},{"id":"spinal-cord-syndromes~ai-2","moduleId":"spinal-cord-syndromes","stem":"What is the mechanism behind contralateral pain and temperature loss in spinal cord lesions?","options":[{"id":"a","text":"Dorsal column involvement"},{"id":"b","text":"Spinothalamic fibers have crossed"},{"id":"c","text":"Corticospinal tract involvement"},{"id":"d","text":"Peripheral nerve damage"}],"answerId":"b","explanation":"Pain and temperature sensations are carried by spinothalamic fibers that cross shortly after entering the spinal cord.","kind":"mechanism","origin":"ai"},{"id":"spinal-cord-syndromes~ai-3","moduleId":"spinal-cord-syndromes","stem":"Which syndrome is characterized by loss of motor function and pain/temperature sensation below the level of the lesion, with preserved touch and proprioception?","options":[{"id":"a","text":"Brown-Séquard syndrome"},{"id":"b","text":"Anterior cord syndrome"},{"id":"c","text":"Central cord syndrome"},{"id":"d","text":"Subacute combined degeneration"}],"answerId":"b","explanation":"Anterior cord syndrome results in loss of motor function and pain/temperature sensation below the lesion, while dorsal columns remain intact.","kind":"recall","origin":"ai"},{"id":"spinal-cord-syndromes~ai-4","moduleId":"spinal-cord-syndromes","stem":"In a patient with a hemicord lesion, where would you expect to find the loss of pain and temperature sensation?","options":[{"id":"a","text":"On the same side as the lesion"},{"id":"b","text":"Contralateral to the lesion"},{"id":"c","text":"At the level of the lesion"},{"id":"d","text":"No loss expected"}],"answerId":"b","explanation":"In hemicord lesions, pain and temperature loss occurs contralaterally due to the crossing of spinothalamic fibers.","kind":"trap","origin":"ai"},{"id":"spinal-cord-syndromes~ai-5","moduleId":"spinal-cord-syndromes","stem":"A patient presents with cape-like sensory loss. Which spinal cord syndrome is most likely?","options":[{"id":"a","text":"Brown-Séquard syndrome"},{"id":"b","text":"Anterior cord syndrome"},{"id":"c","text":"Central cord syndrome"},{"id":"d","text":"Syringomyelia"}],"answerId":"c","explanation":"Cape-like sensory loss is characteristic of central cord syndrome, often associated with syringomyelia.","kind":"recall","origin":"ai"},{"id":"spinal-cord-syndromes~ai-6","moduleId":"spinal-cord-syndromes","stem":"How does anterior cord syndrome affect the corticospinal and spinothalamic tracts?","options":[{"id":"a","text":"Both are spared"},{"id":"b","text":"Only corticospinal is affected"},{"id":"c","text":"Only spinothalamic is affected"},{"id":"d","text":"Both are affected"}],"answerId":"d","explanation":"Anterior cord syndrome affects both the corticospinal and spinothalamic tracts, leading to motor and pain/temperature loss.","kind":"integration","linkedModuleIds":["somatosensory-ascending-pathways"],"origin":"ai"},{"id":"spinal-cord-syndromes~ai-7","moduleId":"spinal-cord-syndromes","stem":"Which pathway is primarily responsible for proprioception and vibration sensation?","options":[{"id":"a","text":"Spinothalamic tract"},{"id":"b","text":"Dorsal columns"},{"id":"c","text":"Corticospinal tract"},{"id":"d","text":"Lateral spinothalamic tract"}],"answerId":"b","explanation":"The dorsal columns are responsible for proprioception and vibration sensation.","kind":"integration","linkedModuleIds":["neuro-localization-framework"],"origin":"ai"}],"cortex-and-stroke":[{"id":"cortex-and-stroke~ai-0","moduleId":"cortex-and-stroke","stem":"Which artery is primarily affected in a patient presenting with contralateral face and arm weakness with expressive aphasia?","options":[{"id":"a","text":"Anterior cerebral artery (ACA)"},{"id":"b","text":"Middle cerebral artery (MCA)"},{"id":"c","text":"Posterior cerebral artery (PCA)"},{"id":"d","text":"Basilar artery"}],"answerId":"b","explanation":"The middle cerebral artery (MCA) supplies the regions of the brain responsible for motor function of the face and arm, and is associated with expressive aphasia when the dominant hemisphere is affected.","kind":"recall","origin":"ai"},{"id":"cortex-and-stroke~ai-1","moduleId":"cortex-and-stroke","stem":"What is the primary mechanism of contralateral homonymous hemianopia in PCA strokes?","options":[{"id":"a","text":"Disruption of the optic chiasm"},{"id":"b","text":"Infarction of the occipital cortex"},{"id":"c","text":"Compression of the optic nerve"},{"id":"d","text":"Damage to the lateral geniculate nucleus"}],"answerId":"b","explanation":"Infarction of the occipital cortex (BA17) leads to contralateral homonymous hemianopia due to loss of visual processing.","kind":"mechanism","origin":"ai"},{"id":"cortex-and-stroke~ai-2","moduleId":"cortex-and-stroke","stem":"A patient exhibits contralateral leg weakness greater than arm weakness. Which artery is likely occluded?","options":[{"id":"a","text":"Middle cerebral artery (MCA)"},{"id":"b","text":"Anterior cerebral artery (ACA)"},{"id":"c","text":"Posterior cerebral artery (PCA)"},{"id":"d","text":"Vertebral artery"}],"answerId":"b","explanation":"Leg-predominant weakness indicates an anterior cerebral artery (ACA) stroke, affecting the medial motor strip responsible for leg movement.","kind":"clinical","origin":"ai"},{"id":"cortex-and-stroke~ai-3","moduleId":"cortex-and-stroke","stem":"Which of the following findings is most consistent with a dominant hemisphere MCA stroke?","options":[{"id":"a","text":"Contralateral leg weakness"},{"id":"b","text":"Contralateral homonymous hemianopia"},{"id":"c","text":"Contralateral face and arm weakness with aphasia"},{"id":"d","text":"Contralateral sensory loss of the leg"}],"answerId":"c","explanation":"Contralateral face and arm weakness with aphasia is characteristic of a dominant hemisphere MCA stroke.","kind":"recall","origin":"ai"},{"id":"cortex-and-stroke~ai-4","moduleId":"cortex-and-stroke","stem":"In a patient with a dense hemiparesis affecting the leg most, which artery is likely involved?","options":[{"id":"a","text":"Middle cerebral artery (MCA)"},{"id":"b","text":"Anterior cerebral artery (ACA)"},{"id":"c","text":"Posterior cerebral artery (PCA)"},{"id":"d","text":"Internal carotid artery"}],"answerId":"b","explanation":"Leg-predominant weakness points to the ACA, as the motor homunculus indicates the leg is represented on the medial surface of the brain.","kind":"trap","origin":"ai"},{"id":"cortex-and-stroke~ai-5","moduleId":"cortex-and-stroke","stem":"A patient with a PCA stroke presents with visual agnosia. Which linked module is most relevant for understanding this symptom?","options":[{"id":"a","text":"Higher Cortical & Integrative Functions"},{"id":"b","text":"Brain Energy Metabolism & Blood–Brain Barrier"},{"id":"c","text":"The Cardiovascular Physical Examination"},{"id":"d","text":"Neuro Localization Framework"}],"answerId":"a","explanation":"Visual agnosia relates to higher cortical functions, particularly in processing visual information, which is affected by PCA strokes.","kind":"integration","linkedModuleIds":["higher-cortical-functions"],"origin":"ai"},{"id":"cortex-and-stroke~ai-6","moduleId":"cortex-and-stroke","stem":"How does a stroke in the ACA territory primarily affect motor function compared to an MCA stroke?","options":[{"id":"a","text":"ACA affects face/arm, MCA affects leg"},{"id":"b","text":"ACA affects leg, MCA affects face/arm"},{"id":"c","text":"Both affect leg equally"},{"id":"d","text":"Both affect face equally"}],"answerId":"b","explanation":"The ACA primarily affects the leg due to its supply of the medial motor strip, while the MCA affects the face and arm.","kind":"integration","linkedModuleIds":["neuro-localization-framework"],"origin":"ai"}],"neuro-localization-framework":[{"id":"neuro-localization-framework~ai-0","moduleId":"neuro-localization-framework","stem":"A patient presents with spastic weakness, hyperreflexia, and a positive Babinski sign. Where is the likely lesion located?","options":[{"id":"a","text":"Peripheral nerve"},{"id":"b","text":"Anterior horn"},{"id":"c","text":"Cortex"},{"id":"d","text":"Brainstem"}],"answerId":"c","explanation":"These findings indicate an upper motor neuron lesion, which is typically located in the cortex.","kind":"recall","origin":"ai"},{"id":"neuro-localization-framework~ai-1","moduleId":"neuro-localization-framework","stem":"Which of the following is a characteristic finding in lower motor neuron lesions?","options":[{"id":"a","text":"Spasticity"},{"id":"b","text":"Hyperreflexia"},{"id":"c","text":"Atrophy"},{"id":"d","text":"Clonus"}],"answerId":"c","explanation":"Atrophy is a hallmark of lower motor neuron lesions due to denervation of muscles.","kind":"recall","origin":"ai"},{"id":"neuro-localization-framework~ai-2","moduleId":"neuro-localization-framework","stem":"A 65-year-old man has weakness and atrophy of the right hand muscles, along with fasciculations. What is the most likely diagnosis?","options":[{"id":"a","text":"Multiple sclerosis"},{"id":"b","text":"Amyotrophic lateral sclerosis"},{"id":"c","text":"Stroke"},{"id":"d","text":"Peripheral neuropathy"}],"answerId":"b","explanation":"The combination of weakness, atrophy, and fasciculations suggests a lower motor neuron disease like amyotrophic lateral sclerosis.","kind":"clinical","origin":"ai"},{"id":"neuro-localization-framework~ai-3","moduleId":"neuro-localization-framework","stem":"A patient exhibits crossed signs with right-sided facial weakness and left-sided hemiparesis. What is the likely location of the lesion?","options":[{"id":"a","text":"Cortex"},{"id":"b","text":"Spinal cord"},{"id":"c","text":"Brainstem"},{"id":"d","text":"Peripheral nerve"}],"answerId":"c","explanation":"Crossed signs indicate a brainstem lesion affecting cranial nerve nuclei and descending motor pathways.","kind":"clinical","origin":"ai"},{"id":"neuro-localization-framework~ai-4","moduleId":"neuro-localization-framework","stem":"Which of the following findings would indicate an upper motor neuron lesion rather than a lower motor neuron lesion?","options":[{"id":"a","text":"Flaccid weakness"},{"id":"b","text":"Hyporeflexia"},{"id":"c","text":"Hypertonia"},{"id":"d","text":"Fasciculations"}],"answerId":"c","explanation":"Hypertonia is indicative of upper motor neuron lesions, while flaccid weakness and fasciculations suggest lower motor neuron involvement.","kind":"trap","origin":"ai"},{"id":"neuro-localization-framework~ai-5","moduleId":"neuro-localization-framework","stem":"A patient with a stroke exhibits right-sided hemiparesis and a positive Babinski sign. Which module's concepts can help localize the lesion?","options":[{"id":"a","text":"Reflex Types & Clinical Testing"},{"id":"b","text":"Brainstem Syndromes"},{"id":"c","text":"Cerebral Cortex & Stroke Syndromes"},{"id":"d","text":"Synthesis, Citation & the Conceptual Framework"}],"answerId":"c","explanation":"The concepts from the Cerebral Cortex & Stroke Syndromes module directly relate to the localization of lesions causing hemiparesis.","kind":"integration","linkedModuleIds":["cortex-and-stroke"],"origin":"ai"},{"id":"neuro-localization-framework~ai-6","moduleId":"neuro-localization-framework","stem":"A patient presents with bilateral facial weakness and dysphagia. Which module's knowledge is essential for understanding the cranial nerve involvement?","options":[{"id":"a","text":"Reflex Types & Clinical Testing"},{"id":"b","text":"Brainstem Syndromes"},{"id":"c","text":"Cerebral Cortex & Stroke Syndromes"},{"id":"d","text":"Synthesis, Citation & the Conceptual Framework"}],"answerId":"b","explanation":"Understanding brainstem syndromes is crucial for localizing lesions affecting cranial nerves that cause facial weakness and dysphagia.","kind":"integration","linkedModuleIds":["brainstem-syndromes"],"origin":"ai"}],"external-ear-disorders":[{"id":"external-ear-disorders~ai-0","moduleId":"external-ear-disorders","stem":"What is the most common cause of acute otitis externa?","options":[{"id":"a","text":"Bacterial infection"},{"id":"b","text":"Fungal infection"},{"id":"c","text":"Allergic reaction"},{"id":"d","text":"Trauma"}],"answerId":"a","explanation":"Acute otitis externa is most commonly caused by bacterial infections, particularly Pseudomonas and Staphylococcus species.","kind":"recall","origin":"ai"},{"id":"external-ear-disorders~ai-1","moduleId":"external-ear-disorders","stem":"A diabetic patient presents with severe ear pain and granulation tissue in the ear canal. What is the most likely diagnosis?","options":[{"id":"a","text":"Acute otitis media"},{"id":"b","text":"Malignant otitis externa"},{"id":"c","text":"Otitis media with effusion"},{"id":"d","text":"Chronic otitis externa"}],"answerId":"b","explanation":"The presence of granulation tissue and severe pain in a diabetic patient suggests malignant otitis externa, which is a medical emergency.","kind":"clinical","origin":"ai"},{"id":"external-ear-disorders~ai-2","moduleId":"external-ear-disorders","stem":"Which of the following best describes the mechanism of action of ototopical antibiotics?","options":[{"id":"a","text":"Inhibition of bacterial protein synthesis"},{"id":"b","text":"Disruption of bacterial cell wall synthesis"},{"id":"c","text":"Inhibition of DNA replication"},{"id":"d","text":"Interference with bacterial metabolism"}],"answerId":"b","explanation":"Ototopical antibiotics typically disrupt bacterial cell wall synthesis, leading to cell lysis and death.","kind":"mechanism","linkedModuleIds":["ototopical-drugs"],"origin":"ai"},{"id":"external-ear-disorders~ai-3","moduleId":"external-ear-disorders","stem":"What clinical finding is most indicative of Ramsay Hunt syndrome?","options":[{"id":"a","text":"Pinna swelling"},{"id":"b","text":"Vesicles in the ear"},{"id":"c","text":"Purulent discharge"},{"id":"d","text":"Hearing loss"}],"answerId":"b","explanation":"Vesicles in the ear along with facial palsy are characteristic of Ramsay Hunt syndrome, caused by VZV reactivation.","kind":"recall","origin":"ai"},{"id":"external-ear-disorders~ai-4","moduleId":"external-ear-disorders","stem":"A patient presents with ear pain and a history of swimming. On examination, there is tenderness on tragal pressure. What is the likely diagnosis?","options":[{"id":"a","text":"Acute otitis media"},{"id":"b","text":"Chronic otitis externa"},{"id":"c","text":"Otitis externa"},{"id":"d","text":"Malignant otitis externa"}],"answerId":"c","explanation":"Tenderness on tragal pressure is a classic sign of otitis externa, often associated with a history of water exposure.","kind":"clinical","origin":"ai"},{"id":"external-ear-disorders~ai-5","moduleId":"external-ear-disorders","stem":"Which of the following conditions is characterized by a facial nerve palsy and vesicular rash in the ear?","options":[{"id":"a","text":"Bell's palsy"},{"id":"b","text":"Ramsay Hunt syndrome"},{"id":"c","text":"Chronic otitis externa"},{"id":"d","text":"Acute otitis media"}],"answerId":"b","explanation":"Ramsay Hunt syndrome is characterized by facial nerve palsy and vesicular rash in the ear, distinguishing it from Bell's palsy.","kind":"trap","origin":"ai"},{"id":"external-ear-disorders~ai-6","moduleId":"external-ear-disorders","stem":"How does the mechanism of action of glucocorticoids in otitis externa relate to the inflammatory process?","options":[{"id":"a","text":"Inhibition of leukocyte migration"},{"id":"b","text":"Stimulation of cerumen production"},{"id":"c","text":"Enhancement of bacterial growth"},{"id":"d","text":"Promotion of epithelial healing"}],"answerId":"a","explanation":"Glucocorticoids inhibit leukocyte migration and reduce inflammation, aiding in the treatment of otitis externa.","kind":"integration","linkedModuleIds":["ototopical-drugs"],"origin":"ai"},{"id":"external-ear-disorders~ai-7","moduleId":"external-ear-disorders","stem":"What is the primary mechanism by which impacted cerumen causes conductive hearing loss?","options":[{"id":"a","text":"Infection of the middle ear"},{"id":"b","text":"Obstruction of sound transmission"},{"id":"c","text":"Eustachian tube dysfunction"},{"id":"d","text":"Damage to the cochlea"}],"answerId":"b","explanation":"Impacted cerumen causes conductive hearing loss by obstructing the external auditory canal, preventing sound transmission.","kind":"mechanism","origin":"ai"}],"limbic-hypothalamus":[{"id":"limbic-hypothalamus~ai-0","moduleId":"limbic-hypothalamus","stem":"Which structure is primarily involved in the consolidation of short-term to long-term memory?","options":[{"id":"a","text":"Amygdala"},{"id":"b","text":"Hippocampus"},{"id":"c","text":"Thalamus"},{"id":"d","text":"Cingulate gyrus"}],"answerId":"b","explanation":"The hippocampus is essential for memory consolidation, particularly in the Papez circuit.","kind":"recall","origin":"ai"},{"id":"limbic-hypothalamus~ai-1","moduleId":"limbic-hypothalamus","stem":"A patient with a lesion in the ventromedial hypothalamus is likely to exhibit which of the following symptoms?","options":[{"id":"a","text":"Increased appetite"},{"id":"b","text":"Decreased appetite"},{"id":"c","text":"Hyperactivity"},{"id":"d","text":"Weight loss"}],"answerId":"a","explanation":"Lesions in the ventromedial hypothalamus lead to hyperphagia and obesity due to loss of satiety signaling.","kind":"mechanism","origin":"ai"},{"id":"limbic-hypothalamus~ai-2","moduleId":"limbic-hypothalamus","stem":"A 45-year-old man presents with anterograde amnesia and confabulation. Which area of the brain is most likely damaged?","options":[{"id":"a","text":"Amygdala"},{"id":"b","text":"Hippocampus"},{"id":"c","text":"Mammillary bodies"},{"id":"d","text":"Cingulate gyrus"}],"answerId":"c","explanation":"Damage to the mammillary bodies is associated with Korsakoff syndrome, leading to anterograde amnesia and confabulation.","kind":"recall","origin":"ai"},{"id":"limbic-hypothalamus~ai-3","moduleId":"limbic-hypothalamus","stem":"A patient presents with bitemporal hemianopia. Which condition is most likely causing this finding?","options":[{"id":"a","text":"Pituitary adenoma"},{"id":"b","text":"Hypothalamic lesion"},{"id":"c","text":"Thalamic stroke"},{"id":"d","text":"Meningioma"}],"answerId":"a","explanation":"A pituitary adenoma can compress the optic chiasm, resulting in bitemporal hemianopia.","kind":"clinical","origin":"ai"},{"id":"limbic-hypothalamus~ai-4","moduleId":"limbic-hypothalamus","stem":"Which of the following statements about hypothalamic feeding nuclei is correct?","options":[{"id":"a","text":"Lateral hypothalamic lesions cause obesity"},{"id":"b","text":"Ventromedial lesions lead to anorexia"},{"id":"c","text":"Lateral hypothalamus is the satiety center"},{"id":"d","text":"Ventromedial lesions cause hyperphagia"}],"answerId":"d","explanation":"Ventromedial hypothalamic lesions disrupt satiety signaling, leading to hyperphagia and obesity.","kind":"trap","origin":"ai"},{"id":"limbic-hypothalamus~ai-5","moduleId":"limbic-hypothalamus","stem":"How does the hypothalamus influence the HPA axis?","options":[{"id":"a","text":"By secreting insulin"},{"id":"b","text":"By regulating circadian rhythms"},{"id":"c","text":"By releasing corticotropin-releasing hormone"},{"id":"d","text":"By controlling body temperature"}],"answerId":"c","explanation":"The hypothalamus releases corticotropin-releasing hormone (CRH), which stimulates the pituitary to release ACTH, thus influencing the HPA axis.","kind":"mechanism","origin":"ai"},{"id":"limbic-hypothalamus~ai-6","moduleId":"limbic-hypothalamus","stem":"A patient with a history of alcohol abuse presents with memory issues. Which linked module's content is relevant for understanding his symptoms?","options":[{"id":"a","text":"Hypothalamic Anatomy, Regions & Nuclei"},{"id":"b","text":"Limbic System: Emotion & Memory"},{"id":"c","text":"Anterior Pituitary Hormones & Axis Control"},{"id":"d","text":"Diencephalon: Thalamus & Hypothalamus"}],"answerId":"b","explanation":"The limbic system, particularly the hippocampus, is crucial for memory, and its dysfunction can explain the patient's symptoms.","kind":"integration","linkedModuleIds":["limbic-system-emotion-memory"],"origin":"ai"},{"id":"limbic-hypothalamus~ai-7","moduleId":"limbic-hypothalamus","stem":"Which hypothalamic function is directly linked to the regulation of the circadian rhythm?","options":[{"id":"a","text":"Thermoregulation"},{"id":"b","text":"Feeding behavior"},{"id":"c","text":"Stress response"},{"id":"d","text":"Suprachiasmatic nucleus activity"}],"answerId":"d","explanation":"The suprachiasmatic nucleus (SCN) in the hypothalamus is the primary regulator of circadian rhythms.","kind":"integration","linkedModuleIds":["hen1-anterior-pituitary-axes"],"origin":"ai"}],"pupillary-reflexes-horner":[{"id":"pupillary-reflexes-horner~ai-0","moduleId":"pupillary-reflexes-horner","stem":"What is the pathway for the light reflex?","options":[{"id":"a","text":"Afferent CN II → pretectal nucleus → Edinger-Westphal nuclei → CN III → ciliary ganglion → sphincter"},{"id":"b","text":"Afferent CN III → pretectal nucleus → Edinger-Westphal nuclei → CN II → ciliary ganglion → sphincter"},{"id":"c","text":"Afferent CN II → pretectal nucleus → Edinger-Westphal nuclei → CN V → ciliary ganglion → sphincter"},{"id":"d","text":"Afferent CN II → lateral geniculate nucleus → Edinger-Westphal nuclei → CN III → ciliary ganglion → sphincter"}],"answerId":"a","explanation":"The light reflex pathway involves afferent input via CN II and efferent output via CN III, leading to bilateral miosis.","kind":"recall","origin":"ai"},{"id":"pupillary-reflexes-horner~ai-1","moduleId":"pupillary-reflexes-horner","stem":"Which finding is characteristic of Horner syndrome?","options":[{"id":"a","text":"Mydriasis and severe ptosis"},{"id":"b","text":"Miosis and mild ptosis"},{"id":"c","text":"Bilateral miosis with no ptosis"},{"id":"d","text":"Anisocoria with no other symptoms"}],"answerId":"b","explanation":"Horner syndrome is characterized by miosis, mild ptosis, and potential anhidrosis due to sympathetic nerve damage.","kind":"recall","origin":"ai"},{"id":"pupillary-reflexes-horner~ai-2","moduleId":"pupillary-reflexes-horner","stem":"In a swinging-light test, which pupil response indicates an afferent defect?","options":[{"id":"a","text":"Both pupils constrict equally"},{"id":"b","text":"Affected pupil dilates when light is swung to it"},{"id":"c","text":"Affected pupil constricts more than the unaffected pupil"},{"id":"d","text":"Both pupils dilate equally"}],"answerId":"b","explanation":"In an afferent defect (RAPD), the affected pupil paradoxically dilates when light is directed towards it.","kind":"recall","origin":"ai"},{"id":"pupillary-reflexes-horner~ai-3","moduleId":"pupillary-reflexes-horner","stem":"What is the mechanism behind light-near dissociation in Argyll Robertson pupils?","options":[{"id":"a","text":"Loss of sympathetic innervation"},{"id":"b","text":"Loss of parasympathetic innervation"},{"id":"c","text":"Dorsal midbrain lesion affecting the pretectal area"},{"id":"d","text":"Optic nerve damage affecting light reflex only"}],"answerId":"c","explanation":"Light-near dissociation occurs due to a lesion in the dorsal midbrain affecting the pathways for light reflex while preserving near reflex.","kind":"mechanism","origin":"ai"},{"id":"pupillary-reflexes-horner~ai-4","moduleId":"pupillary-reflexes-horner","stem":"A patient presents with ptosis and a small pupil. What is the most likely diagnosis?","options":[{"id":"a","text":"Cranial nerve III palsy"},{"id":"b","text":"Horner syndrome"},{"id":"c","text":"Adie's tonic pupil"},{"id":"d","text":"Argyll Robertson pupil"}],"answerId":"b","explanation":"Ptosis with a small pupil suggests Horner syndrome; CN III palsy would present with severe ptosis and a dilated pupil.","kind":"trap","origin":"ai"},{"id":"pupillary-reflexes-horner~ai-5","moduleId":"pupillary-reflexes-horner","stem":"How does Horner syndrome relate to the autonomic nervous system?","options":[{"id":"a","text":"It involves parasympathetic overactivity"},{"id":"b","text":"It results from sympathetic pathway disruption"},{"id":"c","text":"It indicates a cranial nerve III lesion"},{"id":"d","text":"It causes bilateral miosis due to parasympathetic loss"}],"answerId":"b","explanation":"Horner syndrome is due to disruption of the sympathetic pathway, leading to signs like miosis and ptosis.","kind":"integration","linkedModuleIds":["autonomic-nervous-system"],"origin":"ai"},{"id":"pupillary-reflexes-horner~ai-6","moduleId":"pupillary-reflexes-horner","stem":"Which cranial nerve is primarily involved in the light reflex pathway?","options":[{"id":"a","text":"CN II"},{"id":"b","text":"CN III"},{"id":"c","text":"CN IV"},{"id":"d","text":"CN V"}],"answerId":"a","explanation":"CN II is the afferent limb of the light reflex pathway, transmitting sensory information from the retina.","kind":"integration","linkedModuleIds":["cranial-nerves-overview"],"origin":"ai"}],"hearing-balance-basics":[{"id":"hearing-balance-basics~ai-0","moduleId":"hearing-balance-basics","stem":"What type of hearing loss is indicated when Rinne test shows BC > AC in the affected ear?","options":[{"id":"a","text":"Sensorineural hearing loss"},{"id":"b","text":"Normal hearing"},{"id":"c","text":"Conductive hearing loss"},{"id":"d","text":"Mixed hearing loss"}],"answerId":"c","explanation":"BC > AC indicates that bone conduction is better than air conduction, which is characteristic of conductive hearing loss.","kind":"recall","origin":"ai"},{"id":"hearing-balance-basics~ai-1","moduleId":"hearing-balance-basics","stem":"In a patient with conductive hearing loss, where will the Weber test lateralize?","options":[{"id":"a","text":"To the affected ear"},{"id":"b","text":"To the unaffected ear"},{"id":"c","text":"To both ears equally"},{"id":"d","text":"Not lateralize at all"}],"answerId":"a","explanation":"In conductive hearing loss, the Weber test lateralizes to the affected ear because it hears bone conduction better due to reduced ambient noise.","kind":"mechanism","origin":"ai"},{"id":"hearing-balance-basics~ai-2","moduleId":"hearing-balance-basics","stem":"A patient presents with otalgia and a history of ear infections. Rinne test shows AC > BC. What is the most likely diagnosis?","options":[{"id":"a","text":"Conductive hearing loss"},{"id":"b","text":"Sensorineural hearing loss"},{"id":"c","text":"Normal hearing"},{"id":"d","text":"Mixed hearing loss"}],"answerId":"d","explanation":"The presence of otalgia and the Rinne test result suggest that the patient may have mixed hearing loss, as there is a history of ear infections.","kind":"clinical","origin":"ai"},{"id":"hearing-balance-basics~ai-3","moduleId":"hearing-balance-basics","stem":"Which of the following findings is consistent with sensorineural hearing loss?","options":[{"id":"a","text":"Weber lateralizes to the affected ear"},{"id":"b","text":"Rinne test shows BC > AC"},{"id":"c","text":"Weber lateralizes to the better ear"},{"id":"d","text":"Rinne test shows AC > BC in the affected ear"}],"answerId":"c","explanation":"In sensorineural hearing loss, the Weber test lateralizes to the better ear, indicating that the affected ear has a problem with sensory or neural components.","kind":"recall","origin":"ai"},{"id":"hearing-balance-basics~ai-4","moduleId":"hearing-balance-basics","stem":"Which mechanism explains why Weber test lateralizes to the good ear in sensorineural hearing loss?","options":[{"id":"a","text":"Bone conduction is impaired"},{"id":"b","text":"Air conduction is impaired"},{"id":"c","text":"Ambient noise is reduced"},{"id":"d","text":"Cochlear function is compromised"}],"answerId":"d","explanation":"In sensorineural hearing loss, the cochlear function is compromised, leading to lateralization of sound to the better ear during the Weber test.","kind":"mechanism","origin":"ai"},{"id":"hearing-balance-basics~ai-5","moduleId":"hearing-balance-basics","stem":"A patient with a history of noise exposure presents with hearing loss. Rinne test shows AC > BC, and Weber lateralizes to the unaffected ear. What is the most likely type of hearing loss?","options":[{"id":"a","text":"Conductive hearing loss"},{"id":"b","text":"Normal hearing"},{"id":"c","text":"Sensorineural hearing loss"},{"id":"d","text":"Mixed hearing loss"}],"answerId":"c","explanation":"The findings suggest sensorineural hearing loss due to noise exposure, as indicated by the Rinne and Weber test results.","kind":"clinical","origin":"ai"},{"id":"hearing-balance-basics~ai-6","moduleId":"hearing-balance-basics","stem":"How does conductive hearing loss affect the results of the Rinne test compared to sensorineural hearing loss?","options":[{"id":"a","text":"Both show AC > BC"},{"id":"b","text":"Both show BC > AC"},{"id":"c","text":"Conductive shows BC > AC; sensorineural shows AC > BC"},{"id":"d","text":"Conductive shows AC > BC; sensorineural shows BC > AC"}],"answerId":"c","explanation":"In conductive hearing loss, Rinne shows BC > AC, while in sensorineural loss, Rinne shows AC > BC.","kind":"integration","linkedModuleIds":["auditory-physiology-hearing"],"origin":"ai"},{"id":"hearing-balance-basics~ai-7","moduleId":"hearing-balance-basics","stem":"Which of the following statements correctly describes the relationship between the outer ear and conductive hearing loss?","options":[{"id":"a","text":"The outer ear is not involved in conductive hearing loss"},{"id":"b","text":"The outer ear amplifies sound waves"},{"id":"c","text":"The outer ear transmits sound to the cochlea"},{"id":"d","text":"The outer ear can be a site of obstruction leading to conductive hearing loss"}],"answerId":"d","explanation":"The outer ear can be a site of obstruction (e.g., cerumen impaction) leading to conductive hearing loss.","kind":"integration","linkedModuleIds":["ear-external-middle-internal"],"origin":"ai"}],"brainstem-syndromes":[{"id":"brainstem-syndromes~ai-0","moduleId":"brainstem-syndromes","stem":"A patient presents with right-sided facial weakness and left-sided hemiplegia. Which brainstem syndrome is most likely responsible for these findings?","options":[{"id":"a","text":"Wallenberg syndrome"},{"id":"b","text":"Weber syndrome"},{"id":"c","text":"Medial medullary syndrome"},{"id":"d","text":"Lateral pontine syndrome"}],"answerId":"b","explanation":"The combination of right facial weakness (ipsilateral) and left hemiplegia (contralateral) indicates a midbrain lesion affecting CN III and the motor pathway, consistent with Weber syndrome.","kind":"clinical","origin":"ai"},{"id":"brainstem-syndromes~ai-1","moduleId":"brainstem-syndromes","stem":"In Wallenberg syndrome, which of the following findings is NOT typically present?","options":[{"id":"a","text":"Ipsilateral Horner's syndrome"},{"id":"b","text":"Contralateral body pain and temperature loss"},{"id":"c","text":"Ipsilateral facial pain and temperature loss"},{"id":"d","text":"Contralateral facial weakness"}],"answerId":"d","explanation":"Wallenberg syndrome presents with ipsilateral facial pain and temperature loss and contralateral body pain and temperature loss, but does not cause contralateral facial weakness.","kind":"trap","origin":"ai"},{"id":"brainstem-syndromes~ai-2","moduleId":"brainstem-syndromes","stem":"What is the mechanism behind the crossed sensory loss seen in lateral brainstem syndromes?","options":[{"id":"a","text":"Cranial nerve damage only"},{"id":"b","text":"Long-tract damage only"},{"id":"c","text":"Both cranial nerve and long-tract damage"},{"id":"d","text":"Cranial nerve damage with preserved long-tract function"}],"answerId":"c","explanation":"In lateral brainstem syndromes, both the spinal trigeminal tract (ipsilateral face) and the spinothalamic tract (contralateral body) are affected, leading to crossed sensory loss.","kind":"mechanism","origin":"ai"},{"id":"brainstem-syndromes~ai-3","moduleId":"brainstem-syndromes","stem":"A patient with a lateral medullary infarct presents with dysphagia and hoarseness. Which cranial nerve is primarily affected?","options":[{"id":"a","text":"CN VII"},{"id":"b","text":"CN IX"},{"id":"c","text":"CN X"},{"id":"d","text":"CN XII"}],"answerId":"c","explanation":"Dysphagia and hoarseness are indicative of involvement of the nucleus ambiguus, which is innervated by CN X.","kind":"recall","origin":"ai"},{"id":"brainstem-syndromes~ai-4","moduleId":"brainstem-syndromes","stem":"A 65-year-old man presents with vertigo, ataxia, and right-sided facial pain. His left arm and leg have decreased pain and temperature sensation. Which syndrome does he likely have?","options":[{"id":"a","text":"Weber syndrome"},{"id":"b","text":"Wallenberg syndrome"},{"id":"c","text":"Medial medullary syndrome"},{"id":"d","text":"Lateral pontine syndrome"}],"answerId":"b","explanation":"This presentation is characteristic of Wallenberg syndrome, where there is ipsilateral facial pain and contralateral body pain/temperature loss due to lateral medullary infarction.","kind":"clinical","origin":"ai"},{"id":"brainstem-syndromes~ai-5","moduleId":"brainstem-syndromes","stem":"Which of the following findings would help localize a brainstem lesion to the medial medulla?","options":[{"id":"a","text":"Ipsilateral facial pain and contralateral body weakness"},{"id":"b","text":"Tongue deviating toward the lesion with contralateral hemiplegia"},{"id":"c","text":"Ipsilateral Horner's syndrome with vertigo"},{"id":"d","text":"Contralateral facial weakness with ipsilateral arm weakness"}],"answerId":"b","explanation":"The tongue deviating toward the lesion along with contralateral hemiplegia indicates a medial medullary syndrome affecting CN XII and the motor pathway.","kind":"recall","origin":"ai"},{"id":"brainstem-syndromes~ai-6","moduleId":"brainstem-syndromes","stem":"How does the understanding of brainstem syndromes integrate with knowledge of descending motor tracts?","options":[{"id":"a","text":"It clarifies the role of cranial nerves in motor function"},{"id":"b","text":"It helps identify the location of lesions based on motor deficits"},{"id":"c","text":"It explains the sensory pathways in the brainstem"},{"id":"d","text":"It highlights the importance of cerebellar function"}],"answerId":"b","explanation":"Understanding the descending motor tracts aids in localizing lesions based on the pattern of motor deficits observed in brainstem syndromes.","kind":"integration","linkedModuleIds":["brainstem-descending-motor-tracts"],"origin":"ai"},{"id":"brainstem-syndromes~ai-7","moduleId":"brainstem-syndromes","stem":"Which clinical finding in a patient with a brainstem lesion would suggest involvement of the spinal trigeminal tract?","options":[{"id":"a","text":"Contralateral arm weakness"},{"id":"b","text":"Ipsilateral facial pain and temperature loss"},{"id":"c","text":"Contralateral facial weakness"},{"id":"d","text":"Ipsilateral tongue deviation"}],"answerId":"b","explanation":"Ipsilateral facial pain and temperature loss indicates involvement of the spinal trigeminal tract, which is affected in lateral brainstem lesions.","kind":"integration","linkedModuleIds":["neuro-localization-framework"],"origin":"ai"}],"gaze-pathways-ino":[{"id":"gaze-pathways-ino~ai-0","moduleId":"gaze-pathways-ino","stem":"What is the primary anatomical site affected in internuclear ophthalmoplegia (INO)?","options":[{"id":"a","text":"Frontal eye field"},{"id":"b","text":"Abducens nucleus"},{"id":"c","text":"Medial longitudinal fasciculus"},{"id":"d","text":"Optic nerve"}],"answerId":"c","explanation":"INO is characterized by a lesion in the medial longitudinal fasciculus, which disrupts communication between the abducens nucleus and the oculomotor nucleus.","kind":"recall","origin":"ai"},{"id":"gaze-pathways-ino~ai-1","moduleId":"gaze-pathways-ino","stem":"During a neurological examination, a patient is unable to adduct the left eye while the right eye exhibits nystagmus when looking to the right. What is the likely diagnosis?","options":[{"id":"a","text":"Left CN III palsy"},{"id":"b","text":"Right abducens nucleus lesion"},{"id":"c","text":"Left internuclear ophthalmoplegia"},{"id":"d","text":"Right internuclear ophthalmoplegia"}],"answerId":"c","explanation":"The findings are consistent with left internuclear ophthalmoplegia, where the left eye fails to adduct and the right eye shows nystagmus.","kind":"clinical","origin":"ai"},{"id":"gaze-pathways-ino~ai-2","moduleId":"gaze-pathways-ino","stem":"Which of the following findings would suggest a lesion in the PPRF or abducens nucleus?","options":[{"id":"a","text":"Failure of adduction of one eye"},{"id":"b","text":"Both eyes cannot look toward one side"},{"id":"c","text":"Nystagmus in the adducting eye"},{"id":"d","text":"Preserved convergence"}],"answerId":"b","explanation":"A lesion in the PPRF or abducens nucleus results in both eyes being unable to gaze toward the side of the lesion.","kind":"recall","origin":"ai"},{"id":"gaze-pathways-ino~ai-3","moduleId":"gaze-pathways-ino","stem":"In a patient with internuclear ophthalmoplegia, which eye movement is preserved?","options":[{"id":"a","text":"Convergence"},{"id":"b","text":"Saccades"},{"id":"c","text":"Smooth pursuit"},{"id":"d","text":"Vestibulo-ocular reflex"}],"answerId":"a","explanation":"Convergence is preserved in internuclear ophthalmoplegia because the oculomotor nucleus is intact.","kind":"recall","origin":"ai"},{"id":"gaze-pathways-ino~ai-4","moduleId":"gaze-pathways-ino","stem":"What is the mechanism behind the failure of adduction in internuclear ophthalmoplegia?","options":[{"id":"a","text":"CN III palsy"},{"id":"b","text":"Lesion in the abducens nucleus"},{"id":"c","text":"Disruption of the medial longitudinal fasciculus"},{"id":"d","text":"Frontal eye field dysfunction"}],"answerId":"c","explanation":"The failure of adduction in INO is due to a disruption in the medial longitudinal fasciculus, which connects the abducens and oculomotor nuclei.","kind":"mechanism","origin":"ai"},{"id":"gaze-pathways-ino~ai-5","moduleId":"gaze-pathways-ino","stem":"A patient presents with bilateral INO. What is the most likely underlying condition?","options":[{"id":"a","text":"Stroke"},{"id":"b","text":"Multiple sclerosis"},{"id":"c","text":"Brain tumor"},{"id":"d","text":"Traumatic brain injury"}],"answerId":"b","explanation":"Bilateral internuclear ophthalmoplegia in a young patient is often associated with multiple sclerosis.","kind":"clinical","origin":"ai"},{"id":"gaze-pathways-ino~ai-6","moduleId":"gaze-pathways-ino","stem":"How does a CN III palsy differ from internuclear ophthalmoplegia regarding convergence?","options":[{"id":"a","text":"Both have preserved convergence"},{"id":"b","text":"CN III palsy has preserved convergence"},{"id":"c","text":"Internuclear ophthalmoplegia has preserved convergence"},{"id":"d","text":"Neither has preserved convergence"}],"answerId":"c","explanation":"In CN III palsy, convergence is impaired due to the involvement of the oculomotor nucleus, while in INO, convergence remains intact.","kind":"trap","origin":"ai"},{"id":"gaze-pathways-ino~ai-7","moduleId":"gaze-pathways-ino","stem":"Which cranial nerve is primarily responsible for adduction of the eye?","options":[{"id":"a","text":"CN II"},{"id":"b","text":"CN III"},{"id":"c","text":"CN IV"},{"id":"d","text":"CN VI"}],"answerId":"b","explanation":"The oculomotor nerve (CN III) innervates the medial rectus muscle, which is responsible for adduction of the eye.","kind":"recall","origin":"ai"},{"id":"gaze-pathways-ino~ai-8","moduleId":"gaze-pathways-ino","stem":"In a patient with a right MLF lesion, which direction will the eyes deviate when attempting to look left?","options":[{"id":"a","text":"Both eyes left"},{"id":"b","text":"Both eyes right"},{"id":"c","text":"Right eye left, left eye right"},{"id":"d","text":"Right eye right, left eye left"}],"answerId":"b","explanation":"In a right MLF lesion, the eyes will deviate to the right when attempting to look left due to the failure of adduction of the left eye.","kind":"integration","linkedModuleIds":["cranial-nerves-overview"],"origin":"ai"},{"id":"gaze-pathways-ino~ai-9","moduleId":"gaze-pathways-ino","stem":"What is the role of the abducens nucleus in horizontal gaze?","options":[{"id":"a","text":"Controls convergence"},{"id":"b","text":"Innervates lateral rectus muscle"},{"id":"c","text":"Coordinates saccades"},{"id":"d","text":"Facilitates smooth pursuit"}],"answerId":"b","explanation":"The abducens nucleus innervates the lateral rectus muscle, which is essential for horizontal gaze to the side of the nucleus.","kind":"integration","linkedModuleIds":["extraocular-muscles"],"origin":"ai"}],"cns-cellular-reactions":[{"id":"cns-cellular-reactions~ai-0","moduleId":"cns-cellular-reactions","stem":"What is the earliest histological marker of neuronal necrosis following acute hypoxia?","options":[{"id":"a","text":"Red neurons"},{"id":"b","text":"Rosenthal fibers"},{"id":"c","text":"GFAP-positive astrocytes"},{"id":"d","text":"Microglial nodules"}],"answerId":"a","explanation":"Red neurons appear 6–12 hours after irreversible injury and indicate acute hypoxic-ischemic necrosis.","kind":"recall","origin":"ai"},{"id":"cns-cellular-reactions~ai-1","moduleId":"cns-cellular-reactions","stem":"Which process describes the degeneration of an axon distal to the site of injury?","options":[{"id":"a","text":"Central chromatolysis"},{"id":"b","text":"Wallerian degeneration"},{"id":"c","text":"Axonal spheroids"},{"id":"d","text":"Gliosis"}],"answerId":"b","explanation":"Wallerian degeneration is the term for the degeneration of the axon distal to the injury site.","kind":"recall","origin":"ai"},{"id":"cns-cellular-reactions~ai-2","moduleId":"cns-cellular-reactions","stem":"What histological change is characterized by hypertrophic astrocytes expressing GFAP?","options":[{"id":"a","text":"Red neurons"},{"id":"b","text":"Microglial nodules"},{"id":"c","text":"Gliosis"},{"id":"d","text":"Axonal spheroids"}],"answerId":"c","explanation":"Gliosis, marked by GFAP-positive hypertrophic astrocytes, is a non-specific marker of CNS injury.","kind":"recall","origin":"ai"},{"id":"cns-cellular-reactions~ai-3","moduleId":"cns-cellular-reactions","stem":"What is the mechanism behind the formation of Rosenthal fibers?","options":[{"id":"a","text":"Acute hypoxic-ischemic necrosis"},{"id":"b","text":"Chronic gliosis"},{"id":"c","text":"Axonal injury"},{"id":"d","text":"Microglial activation"}],"answerId":"b","explanation":"Rosenthal fibers are associated with chronic gliosis and pilocytic astrocytoma.","kind":"mechanism","origin":"ai"},{"id":"cns-cellular-reactions~ai-4","moduleId":"cns-cellular-reactions","stem":"Which of the following is a common misconception regarding CNS injury healing?","options":[{"id":"a","text":"CNS heals by gliosis"},{"id":"b","text":"Fibroblastic scarring occurs in CNS"},{"id":"c","text":"Astrocytes proliferate after injury"},{"id":"d","text":"Microglia respond to injury"}],"answerId":"b","explanation":"The CNS heals by gliosis, not by fibroblastic scarring, which is a feature of peripheral tissue healing.","kind":"trap","origin":"ai"},{"id":"cns-cellular-reactions~ai-5","moduleId":"cns-cellular-reactions","stem":"In the context of traumatic brain injury, which cell type is primarily responsible for the inflammatory response?","options":[{"id":"a","text":"Neurons"},{"id":"b","text":"Astrocytes"},{"id":"c","text":"Microglia"},{"id":"d","text":"Oligodendrocytes"}],"answerId":"c","explanation":"Microglia are the resident macrophages of the CNS and play a key role in the inflammatory response to injury.","kind":"clinical","linkedModuleIds":["traumatic-brain-spinal-injury"],"origin":"ai"},{"id":"cns-cellular-reactions~ai-6","moduleId":"cns-cellular-reactions","stem":"How does gliosis differ from healing in peripheral tissues after injury?","options":[{"id":"a","text":"It involves collagen formation"},{"id":"b","text":"It is mediated by fibroblasts"},{"id":"c","text":"It leads to scar tissue formation"},{"id":"d","text":"It involves astrocyte proliferation"}],"answerId":"d","explanation":"Gliosis involves astrocyte proliferation and hypertrophy, unlike the fibroblastic scarring seen in peripheral tissues.","kind":"integration","linkedModuleIds":["neurons-glia-neurohistology"],"origin":"ai"}],"amd-diabetic-retinopathy":[{"id":"amd-diabetic-retinopathy~ai-0","moduleId":"amd-diabetic-retinopathy","stem":"What is the primary cause of vision loss in diabetic retinopathy?","options":[{"id":"a","text":"Neovascularization"},{"id":"b","text":"Macular edema"},{"id":"c","text":"Vitreous hemorrhage"},{"id":"d","text":"Tractional retinal detachment"}],"answerId":"b","explanation":"Macular edema is the leading cause of vision loss in diabetic retinopathy, as it directly affects central vision.","kind":"trap","origin":"ai"},{"id":"amd-diabetic-retinopathy~ai-1","moduleId":"amd-diabetic-retinopathy","stem":"Which of the following findings is characteristic of non-proliferative diabetic retinopathy?","options":[{"id":"a","text":"New vessels at the disc"},{"id":"b","text":"Microaneurysms"},{"id":"c","text":"Geographic atrophy"},{"id":"d","text":"Central scotoma"}],"answerId":"b","explanation":"Microaneurysms are a hallmark of non-proliferative diabetic retinopathy.","kind":"recall","origin":"ai"},{"id":"amd-diabetic-retinopathy~ai-2","moduleId":"amd-diabetic-retinopathy","stem":"What is the mechanism by which ischemia leads to neovascularization in diabetic retinopathy?","options":[{"id":"a","text":"Increased VEGF production"},{"id":"b","text":"Decreased blood flow"},{"id":"c","text":"Increased oxidative stress"},{"id":"d","text":"Loss of pericytes"}],"answerId":"a","explanation":"Ischemia leads to increased VEGF production, which drives neovascularization.","kind":"mechanism","origin":"ai"},{"id":"amd-diabetic-retinopathy~ai-3","moduleId":"amd-diabetic-retinopathy","stem":"Which treatment is most appropriate for a patient with proliferative diabetic retinopathy?","options":[{"id":"a","text":"Intravitreal anti-VEGF"},{"id":"b","text":"Antioxidant supplements"},{"id":"c","text":"Focal laser therapy"},{"id":"d","text":"Observation"}],"answerId":"a","explanation":"Intravitreal anti-VEGF is a key treatment for proliferative diabetic retinopathy.","kind":"recall","origin":"ai"},{"id":"amd-diabetic-retinopathy~ai-4","moduleId":"amd-diabetic-retinopathy","stem":"In age-related macular degeneration, which of the following is a common symptom associated with wet AMD?","options":[{"id":"a","text":"Central scotoma"},{"id":"b","text":"Microaneurysms"},{"id":"c","text":"Hard exudates"},{"id":"d","text":"Geographic atrophy"}],"answerId":"a","explanation":"Central scotoma is a common symptom in wet AMD due to choroidal neovascularization.","kind":"recall","origin":"ai"},{"id":"amd-diabetic-retinopathy~ai-5","moduleId":"amd-diabetic-retinopathy","stem":"How does diabetic retinopathy relate to retinal vascular occlusions?","options":[{"id":"a","text":"Both are caused by hypertension"},{"id":"b","text":"Both lead to neovascularization"},{"id":"c","text":"Both involve microvascular damage"},{"id":"d","text":"Both result in central scotoma"}],"answerId":"c","explanation":"Diabetic retinopathy and retinal vascular occlusions both involve microvascular damage.","kind":"integration","linkedModuleIds":["retinal-vascular-occlusions"],"origin":"ai"},{"id":"amd-diabetic-retinopathy~ai-6","moduleId":"amd-diabetic-retinopathy","stem":"What is a common clinical finding in both diabetic retinopathy and optic nerve disorders?","options":[{"id":"a","text":"Neovascularization"},{"id":"b","text":"Central scotoma"},{"id":"c","text":"Vitreous hemorrhage"},{"id":"d","text":"Hard exudates"}],"answerId":"b","explanation":"Central scotoma can be a finding in both diabetic retinopathy and optic nerve disorders due to macular involvement.","kind":"integration","linkedModuleIds":["optic-nerve-disc-edema"],"origin":"ai"}],"traumatic-brain-spinal-injury":[{"id":"traumatic-brain-spinal-injury~ai-0","moduleId":"traumatic-brain-spinal-injury","stem":"What is the primary mechanism of injury in a concussion?","options":[{"id":"a","text":"Direct tissue damage"},{"id":"b","text":"Force leading to primary injury"},{"id":"c","text":"Vascular injury"},{"id":"d","text":"Penetrating trauma"}],"answerId":"b","explanation":"A concussion is primarily caused by force that leads to a transient, reversible alteration in neurological function without structural damage.","kind":"mechanism","origin":"ai"},{"id":"traumatic-brain-spinal-injury~ai-1","moduleId":"traumatic-brain-spinal-injury","stem":"Which of the following findings is characteristic of a coup contusion?","options":[{"id":"a","text":"Focal deficit opposite the impact site"},{"id":"b","text":"Transient loss of consciousness"},{"id":"c","text":"Focal deficit matching a contused gyral crest"},{"id":"d","text":"Complete loss of motor function"}],"answerId":"c","explanation":"A coup contusion occurs at the site of impact, leading to focal deficits that correspond to the contused area of the brain.","kind":"recall","origin":"ai"},{"id":"traumatic-brain-spinal-injury~ai-2","moduleId":"traumatic-brain-spinal-injury","stem":"Which statement correctly differentiates concussion from contusion?","options":[{"id":"a","text":"Both involve structural brain damage"},{"id":"b","text":"Concussion has no fixed deficits"},{"id":"c","text":"Contusion is always associated with loss of consciousness"},{"id":"d","text":"Concussion is a permanent condition"}],"answerId":"b","explanation":"Concussion is characterized by transient neurological dysfunction without structural lesions, while contusions involve visible parenchymal damage.","kind":"trap","origin":"ai"},{"id":"traumatic-brain-spinal-injury~ai-3","moduleId":"traumatic-brain-spinal-injury","stem":"What is the most likely neurological finding in a patient with a spinal cord injury at the cervical level?","options":[{"id":"a","text":"Loss of consciousness"},{"id":"b","text":"Bilateral upper and lower limb weakness"},{"id":"c","text":"Focal sensory loss in one limb"},{"id":"d","text":"Cognitive decline"}],"answerId":"b","explanation":"Injuries at the cervical level can lead to quadriplegia, affecting both upper and lower limbs.","kind":"recall","origin":"ai"},{"id":"traumatic-brain-spinal-injury~ai-4","moduleId":"traumatic-brain-spinal-injury","stem":"What is the hallmark pathology of chronic traumatic encephalopathy (CTE)?","options":[{"id":"a","text":"Neurofibrillary tangles"},{"id":"b","text":"Cerebral edema"},{"id":"c","text":"Vascular malformations"},{"id":"d","text":"Meningeal scarring"}],"answerId":"a","explanation":"CTE is characterized by the presence of tau tangles and brain atrophy, particularly in the frontal and temporal lobes.","kind":"recall","origin":"ai"},{"id":"traumatic-brain-spinal-injury~ai-5","moduleId":"traumatic-brain-spinal-injury","stem":"How does the brain's energy metabolism relate to traumatic brain injury?","options":[{"id":"a","text":"Increased glucose uptake post-injury"},{"id":"b","text":"Decreased oxygen demand"},{"id":"c","text":"Altered mitochondrial function"},{"id":"d","text":"Enhanced blood-brain barrier permeability"}],"answerId":"c","explanation":"Traumatic brain injury can lead to altered mitochondrial function, affecting energy metabolism and recovery processes.","kind":"integration","linkedModuleIds":["brain-energy-metabolism"],"origin":"ai"},{"id":"traumatic-brain-spinal-injury~ai-6","moduleId":"traumatic-brain-spinal-injury","stem":"Which psychological response is commonly observed following traumatic brain injury?","options":[{"id":"a","text":"Acute stress disorder"},{"id":"b","text":"Chronic pain syndrome"},{"id":"c","text":"Dementia"},{"id":"d","text":"Schizophrenia"}],"answerId":"a","explanation":"Acute stress disorder is a common psychological response following trauma, including traumatic brain injuries.","kind":"integration","linkedModuleIds":["hrp1-trauma-asd-ptsd-first-aid"],"origin":"ai"}],"optic-nerve-disc-edema":[{"id":"optic-nerve-disc-edema~ai-0","moduleId":"optic-nerve-disc-edema","stem":"What is the most common cause of bilateral disc swelling in a young obese woman?","options":[{"id":"a","text":"Optic neuritis"},{"id":"b","text":"Papilledema"},{"id":"c","text":"Anterior ischemic optic neuropathy"},{"id":"d","text":"Glaucomatous optic neuropathy"}],"answerId":"b","explanation":"Papilledema is commonly seen in young obese women due to idiopathic intracranial hypertension (IIH).","kind":"recall","origin":"ai"},{"id":"optic-nerve-disc-edema~ai-1","moduleId":"optic-nerve-disc-edema","stem":"Which clinical finding is characteristic of optic neuritis?","options":[{"id":"a","text":"Bilateral disc swelling"},{"id":"b","text":"RAPD and pain on eye movement"},{"id":"c","text":"Mid-dilated fixed pupil"},{"id":"d","text":"Hazy cornea"}],"answerId":"b","explanation":"Optic neuritis typically presents with relative afferent pupillary defect (RAPD) and pain on eye movement.","kind":"recall","origin":"ai"},{"id":"optic-nerve-disc-edema~ai-2","moduleId":"optic-nerve-disc-edema","stem":"What is the immediate treatment for arteritic anterior ischemic optic neuropathy?","options":[{"id":"a","text":"Observation"},{"id":"b","text":"Oral corticosteroids"},{"id":"c","text":"Intravenous steroids"},{"id":"d","text":"Antihypertensives"}],"answerId":"c","explanation":"Intravenous steroids are required urgently to prevent vision loss in arteritic AION due to giant cell arteritis.","kind":"mechanism","origin":"ai"},{"id":"optic-nerve-disc-edema~ai-3","moduleId":"optic-nerve-disc-edema","stem":"Which of the following is a classic symptom of acute angle-closure glaucoma?","options":[{"id":"a","text":"Painless visual loss"},{"id":"b","text":"Mid-dilated fixed pupil"},{"id":"c","text":"Bilateral disc swelling"},{"id":"d","text":"Transient visual obscurations"}],"answerId":"b","explanation":"Acute angle-closure glaucoma typically presents with a mid-dilated fixed pupil and is associated with severe pain.","kind":"recall","origin":"ai"},{"id":"optic-nerve-disc-edema~ai-4","moduleId":"optic-nerve-disc-edema","stem":"In a patient with sudden painless visual loss and a swollen disc, what should be prioritized?","options":[{"id":"a","text":"Blood pressure control"},{"id":"b","text":"Check ESR/CRP"},{"id":"c","text":"Optic nerve imaging"},{"id":"d","text":"Referral to ophthalmology"}],"answerId":"b","explanation":"Checking ESR/CRP is crucial to rule out arteritic AION, which requires immediate treatment.","kind":"trap","origin":"ai"},{"id":"optic-nerve-disc-edema~ai-5","moduleId":"optic-nerve-disc-edema","stem":"How does increased intracranial pressure lead to papilledema?","options":[{"id":"a","text":"Increased blood flow to the optic nerve"},{"id":"b","text":"Compression of the optic nerve"},{"id":"c","text":"Increased fluid in the optic nerve sheath"},{"id":"d","text":"Inflammation of the optic nerve"}],"answerId":"c","explanation":"Increased intracranial pressure causes fluid accumulation in the optic nerve sheath, leading to disc swelling.","kind":"mechanism","origin":"ai"},{"id":"optic-nerve-disc-edema~ai-6","moduleId":"optic-nerve-disc-edema","stem":"Which condition is characterized by both retinal vascular occlusion and disc edema?","options":[{"id":"a","text":"Diabetic retinopathy"},{"id":"b","text":"Papilledema"},{"id":"c","text":"Optic neuritis"},{"id":"d","text":"Acute angle-closure glaucoma"}],"answerId":"a","explanation":"Diabetic retinopathy can lead to retinal vascular occlusions and is associated with disc edema.","kind":"integration","linkedModuleIds":["amd-diabetic-retinopathy"],"origin":"ai"},{"id":"optic-nerve-disc-edema~ai-7","moduleId":"optic-nerve-disc-edema","stem":"What common mechanism links papilledema and retinal vascular occlusions?","options":[{"id":"a","text":"Increased vascular permeability"},{"id":"b","text":"Increased intracranial pressure"},{"id":"c","text":"Ischemia"},{"id":"d","text":"Inflammation"}],"answerId":"b","explanation":"Both conditions can arise from increased intracranial pressure affecting the optic nerve and retinal vasculature.","kind":"integration","linkedModuleIds":["retinal-vascular-occlusions"],"origin":"ai"}],"visual-pathway-fields":[{"id":"visual-pathway-fields~ai-0","moduleId":"visual-pathway-fields","stem":"What type of visual field defect is most commonly associated with a pituitary tumor?","options":[{"id":"a","text":"Bitemporal hemianopia"},{"id":"b","text":"Contralateral homonymous hemianopia"},{"id":"c","text":"Superior quadrantanopia"},{"id":"d","text":"Inferior quadrantanopia"}],"answerId":"a","explanation":"Bitemporal hemianopia occurs due to compression of the optic chiasm, which is often caused by pituitary tumors.","kind":"recall","origin":"ai"},{"id":"visual-pathway-fields~ai-1","moduleId":"visual-pathway-fields","stem":"Which visual field defect is characterized by a 'pie in the sky' appearance?","options":[{"id":"a","text":"Bitemporal hemianopia"},{"id":"b","text":"Superior quadrantanopia"},{"id":"c","text":"Inferior quadrantanopia"},{"id":"d","text":"Contralateral homonymous hemianopia"}],"answerId":"b","explanation":"Superior quadrantanopia, or 'pie in the sky', results from lesions affecting the temporal lobe's optic radiation (Meyer’s loop).","kind":"recall","origin":"ai"},{"id":"visual-pathway-fields~ai-2","moduleId":"visual-pathway-fields","stem":"A patient presents with a right homonymous hemianopia. Where is the likely location of the lesion?","options":[{"id":"a","text":"Optic nerve"},{"id":"b","text":"Optic chiasm"},{"id":"c","text":"Right optic tract"},{"id":"d","text":"Left occipital lobe"}],"answerId":"d","explanation":"A right homonymous hemianopia indicates a lesion in the left occipital lobe, affecting the visual field from the right side.","kind":"clinical","origin":"ai"},{"id":"visual-pathway-fields~ai-3","moduleId":"visual-pathway-fields","stem":"Which mechanism explains the presence of macular sparing in a contralateral homonymous hemianopia?","options":[{"id":"a","text":"Dual blood supply to the occipital pole"},{"id":"b","text":"Compression of the optic chiasm"},{"id":"c","text":"Lesion in the optic nerve"},{"id":"d","text":"Involvement of the optic tract"}],"answerId":"a","explanation":"Macular sparing occurs due to the dual blood supply from the MCA and PCA to the occipital pole.","kind":"mechanism","origin":"ai"},{"id":"visual-pathway-fields~ai-4","moduleId":"visual-pathway-fields","stem":"A patient has a bitemporal hemianopia. Which of the following statements is true?","options":[{"id":"a","text":"It indicates a retrochiasmal lesion."},{"id":"b","text":"It is caused by a lesion in the optic nerve."},{"id":"c","text":"It localizes to the optic chiasm."},{"id":"d","text":"It is always associated with macular sparing."}],"answerId":"c","explanation":"Bitemporal hemianopia specifically indicates a lesion at the optic chiasm, affecting the crossing nasal fibers.","kind":"trap","origin":"ai"},{"id":"visual-pathway-fields~ai-5","moduleId":"visual-pathway-fields","stem":"In the context of diabetic retinopathy, which visual pathway defect might be observed?","options":[{"id":"a","text":"Bitemporal hemianopia"},{"id":"b","text":"Contralateral homonymous hemianopia"},{"id":"c","text":"Superior quadrantanopia"},{"id":"d","text":"Monocular field loss"}],"answerId":"d","explanation":"Diabetic retinopathy can lead to monocular field loss due to optic nerve damage or retinal issues.","kind":"integration","linkedModuleIds":["amd-diabetic-retinopathy"],"origin":"ai"},{"id":"visual-pathway-fields~ai-6","moduleId":"visual-pathway-fields","stem":"How might optic nerve disorders affect visual field defects in a patient with a history of optic neuritis?","options":[{"id":"a","text":"Bitemporal hemianopia"},{"id":"b","text":"Monocular field loss"},{"id":"c","text":"Superior quadrantanopia"},{"id":"d","text":"Contralateral homonymous hemianopia"}],"answerId":"b","explanation":"Optic neuritis typically results in monocular field loss, often accompanied by a relative afferent pupillary defect (RAPD).","kind":"integration","linkedModuleIds":["optic-nerve-disc-edema"],"origin":"ai"}],"raised-icp-herniation":[{"id":"raised-icp-herniation~ai-0","moduleId":"raised-icp-herniation","stem":"What is the primary consequence of added volume in the rigid skull?","options":[{"id":"a","text":"Increased cerebral perfusion"},{"id":"b","text":"Decreased intracranial pressure"},{"id":"c","text":"Raised intracranial pressure"},{"id":"d","text":"Improved brain function"}],"answerId":"c","explanation":"Added volume in the skull leads to increased intracranial pressure, which can result in various neurological symptoms.","kind":"recall","origin":"ai"},{"id":"raised-icp-herniation~ai-1","moduleId":"raised-icp-herniation","stem":"Which type of cerebral edema is characterized by breakdown of the blood-brain barrier?","options":[{"id":"a","text":"Cytotoxic edema"},{"id":"b","text":"Vasogenic edema"},{"id":"c","text":"Interstitial edema"},{"id":"d","text":"Hydrocephalus"}],"answerId":"b","explanation":"Vasogenic edema occurs due to blood-brain barrier breakdown, leading to extracellular fluid accumulation.","kind":"recall","origin":"ai"},{"id":"raised-icp-herniation~ai-2","moduleId":"raised-icp-herniation","stem":"What clinical finding is associated with uncal herniation?","options":[{"id":"a","text":"Bilateral fixed pupils"},{"id":"b","text":"Contralateral hemiparesis"},{"id":"c","text":"Bilateral motor weakness"},{"id":"d","text":"Cerebellar ataxia"}],"answerId":"b","explanation":"Uncal herniation typically presents with ipsilateral fixed dilated pupil and contralateral hemiparesis due to compression of CN III and the cerebral peduncle.","kind":"clinical","origin":"ai"},{"id":"raised-icp-herniation~ai-3","moduleId":"raised-icp-herniation","stem":"What is the Cushing response indicative of in a patient with raised ICP?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Hypotension"},{"id":"c","text":"Hypertension and bradycardia"},{"id":"d","text":"Decreased respiratory rate"}],"answerId":"c","explanation":"The Cushing response is characterized by hypertension, bradycardia, and irregular respiration as a compensatory mechanism to maintain cerebral perfusion.","kind":"mechanism","origin":"ai"},{"id":"raised-icp-herniation~ai-4","moduleId":"raised-icp-herniation","stem":"Which of the following statements about cerebral edema is true?","options":[{"id":"a","text":"All cerebral edema is due to blood-brain barrier leakage"},{"id":"b","text":"Vasogenic edema is intracellular"},{"id":"c","text":"Cytotoxic edema responds to steroids"},{"id":"d","text":"Vasogenic edema is extracellular"}],"answerId":"d","explanation":"Vasogenic edema is characterized by extracellular fluid accumulation due to blood-brain barrier breakdown, while cytotoxic edema is intracellular.","kind":"trap","origin":"ai"},{"id":"raised-icp-herniation~ai-5","moduleId":"raised-icp-herniation","stem":"In a patient with tonsillar herniation, which vital center is most likely compromised?","options":[{"id":"a","text":"Cardiac center"},{"id":"b","text":"Respiratory center"},{"id":"c","text":"Vasomotor center"},{"id":"d","text":"Cerebellar center"}],"answerId":"b","explanation":"Tonsillar herniation compresses the brainstem, particularly affecting the respiratory center, which can lead to respiratory failure.","kind":"clinical","origin":"ai"},{"id":"raised-icp-herniation~ai-6","moduleId":"raised-icp-herniation","stem":"How does vasogenic edema differ from cytotoxic edema in terms of treatment response?","options":[{"id":"a","text":"Both respond to steroids"},{"id":"b","text":"Only cytotoxic edema responds to steroids"},{"id":"c","text":"Only vasogenic edema responds to steroids"},{"id":"d","text":"Neither responds to steroids"}],"answerId":"c","explanation":"Vasogenic edema responds to steroids due to its nature of extracellular fluid accumulation, while cytotoxic edema does not respond to steroids.","kind":"integration","linkedModuleIds":["brain-energy-metabolism"],"origin":"ai"},{"id":"raised-icp-herniation~ai-7","moduleId":"raised-icp-herniation","stem":"Which type of herniation is most likely to cause ipsilateral CN III palsy?","options":[{"id":"a","text":"Subfalcine herniation"},{"id":"b","text":"Tonsillar herniation"},{"id":"c","text":"Uncal herniation"},{"id":"d","text":"Central herniation"}],"answerId":"c","explanation":"Uncal herniation compresses the oculomotor nerve (CN III), leading to ipsilateral pupil dilation and other neurological deficits.","kind":"integration","linkedModuleIds":["epidural-subdural-hematoma"],"origin":"ai"}],"retinal-vascular-occlusions":[{"id":"retinal-vascular-occlusions~ai-0","moduleId":"retinal-vascular-occlusions","stem":"What is the most characteristic fundoscopic finding in central retinal artery occlusion (CRAO)?","options":[{"id":"a","text":"Pale retina with a cherry-red spot"},{"id":"b","text":"Diffuse retinal hemorrhages"},{"id":"c","text":"Cotton-wool spots"},{"id":"d","text":"Optic disc edema"}],"answerId":"a","explanation":"CRAO is characterized by a pale retina with a cherry-red spot due to the intact choroidal circulation.","kind":"recall","origin":"ai"},{"id":"retinal-vascular-occlusions~ai-1","moduleId":"retinal-vascular-occlusions","stem":"Which of the following is a common risk factor for central retinal vein occlusion (CRVO)?","options":[{"id":"a","text":"Myopia"},{"id":"b","text":"Hyperlipidemia"},{"id":"c","text":"Retinal detachment"},{"id":"d","text":"Uveitis"}],"answerId":"b","explanation":"Hyperlipidemia is a recognized risk factor for CRVO, along with hypertension and diabetes.","kind":"recall","origin":"ai"},{"id":"retinal-vascular-occlusions~ai-2","moduleId":"retinal-vascular-occlusions","stem":"What is the primary mechanism leading to visual loss in CRAO?","options":[{"id":"a","text":"Increased intraocular pressure"},{"id":"b","text":"Retinal ischemia due to arterial occlusion"},{"id":"c","text":"Inflammation of the optic nerve"},{"id":"d","text":"Venous thrombosis"}],"answerId":"b","explanation":"CRAO causes retinal ischemia due to occlusion of the central retinal artery.","kind":"mechanism","origin":"ai"},{"id":"retinal-vascular-occlusions~ai-3","moduleId":"retinal-vascular-occlusions","stem":"A patient presents with sudden painless monocular vision loss and a cherry-red spot on fundoscopic examination. What is the most likely diagnosis?","options":[{"id":"a","text":"Central retinal vein occlusion"},{"id":"b","text":"Optic neuritis"},{"id":"c","text":"Central retinal artery occlusion"},{"id":"d","text":"Retinal detachment"}],"answerId":"c","explanation":"The presentation is classic for CRAO, characterized by sudden painless vision loss and a cherry-red spot.","kind":"clinical","origin":"ai"},{"id":"retinal-vascular-occlusions~ai-4","moduleId":"retinal-vascular-occlusions","stem":"Which of the following statements correctly differentiates CRAO from optic neuritis?","options":[{"id":"a","text":"Both conditions present with painful vision loss."},{"id":"b","text":"CRAO is associated with a cherry-red spot, while optic neuritis is not."},{"id":"c","text":"CRAO typically occurs in younger patients than optic neuritis."},{"id":"d","text":"Optic neuritis is caused by emboli."}],"answerId":"b","explanation":"CRAO is characterized by a cherry-red spot, while optic neuritis presents with pain and is often seen in younger patients.","kind":"trap","origin":"ai"},{"id":"retinal-vascular-occlusions~ai-5","moduleId":"retinal-vascular-occlusions","stem":"How does central retinal vein occlusion (CRVO) typically appear on fundoscopic examination?","options":[{"id":"a","text":"Cherry-red spot"},{"id":"b","text":"Diffuse retinal hemorrhages and dilated veins"},{"id":"c","text":"Pale retina"},{"id":"d","text":"Optic disc pallor"}],"answerId":"b","explanation":"CRVO is characterized by a 'blood-and-thunder' appearance with diffuse retinal hemorrhages and dilated tortuous veins.","kind":"recall","origin":"ai"},{"id":"retinal-vascular-occlusions~ai-6","moduleId":"retinal-vascular-occlusions","stem":"In patients with diabetic retinopathy, what is a potential complication that can also occur in CRVO?","options":[{"id":"a","text":"Optic disc edema"},{"id":"b","text":"Neovascularization"},{"id":"c","text":"Retinal detachment"},{"id":"d","text":"Macular hole"}],"answerId":"b","explanation":"Neovascularization can occur in both diabetic retinopathy and CRVO due to retinal ischemia.","kind":"integration","linkedModuleIds":["amd-diabetic-retinopathy"],"origin":"ai"},{"id":"retinal-vascular-occlusions~ai-7","moduleId":"retinal-vascular-occlusions","stem":"Which condition shares similar risk factors with CRAO and is also relevant when assessing visual loss?","options":[{"id":"a","text":"Optic neuritis"},{"id":"b","text":"Central retinal vein occlusion"},{"id":"c","text":"Retinal detachment"},{"id":"d","text":"Age-related macular degeneration"}],"answerId":"b","explanation":"CRVO shares similar risk factors such as hypertension and diabetes with CRAO, making it relevant in the assessment of visual loss.","kind":"integration","linkedModuleIds":["optic-nerve-disc-edema"],"origin":"ai"}],"inner-ear-disorders":[{"id":"inner-ear-disorders~ai-0","moduleId":"inner-ear-disorders","stem":"What is the most common cause of vertigo in adults?","options":[{"id":"a","text":"Vestibular neuritis"},{"id":"b","text":"Labyrinthitis"},{"id":"c","text":"Benign paroxysmal positional vertigo (BPPV)"},{"id":"d","text":"Ménière disease"}],"answerId":"c","explanation":"BPPV is the most common cause of vertigo due to displaced otoconia in the posterior semicircular canal.","kind":"recall","origin":"ai"},{"id":"inner-ear-disorders~ai-1","moduleId":"inner-ear-disorders","stem":"Which clinical finding is characteristic of Ménière disease?","options":[{"id":"a","text":"Brief positional vertigo"},{"id":"b","text":"Unilateral fluctuating sensorineural hearing loss"},{"id":"c","text":"Fatigable nystagmus"},{"id":"d","text":"Bilateral high-frequency hearing loss"}],"answerId":"b","explanation":"Ménière disease presents with a triad of recurrent vertigo, fluctuating sensorineural hearing loss, and tinnitus.","kind":"recall","origin":"ai"},{"id":"inner-ear-disorders~ai-2","moduleId":"inner-ear-disorders","stem":"What is the mechanism behind the vertigo experienced in BPPV?","options":[{"id":"a","text":"Endolymphatic hydrops"},{"id":"b","text":"Displaced otoconia"},{"id":"c","text":"Vestibular nerve inflammation"},{"id":"d","text":"Labyrinthine infection"}],"answerId":"b","explanation":"BPPV is caused by displaced otoconia that disrupt normal fluid movement in the semicircular canals.","kind":"mechanism","origin":"ai"},{"id":"inner-ear-disorders~ai-3","moduleId":"inner-ear-disorders","stem":"A patient presents with days of vertigo but intact hearing. What is the most likely diagnosis?","options":[{"id":"a","text":"Labyrinthitis"},{"id":"b","text":"Vestibular neuritis"},{"id":"c","text":"Ménière disease"},{"id":"d","text":"Acoustic neuroma"}],"answerId":"b","explanation":"Vestibular neuritis causes prolonged vertigo without hearing loss, distinguishing it from labyrinthitis.","kind":"clinical","origin":"ai"},{"id":"inner-ear-disorders~ai-4","moduleId":"inner-ear-disorders","stem":"Which of the following is a common complication of ototoxicity?","options":[{"id":"a","text":"Bilateral low-frequency hearing loss"},{"id":"b","text":"Unilateral high-frequency hearing loss"},{"id":"c","text":"Fluctuating vertigo"},{"id":"d","text":"Tinnitus with aural fullness"}],"answerId":"b","explanation":"Ototoxicity typically leads to high-frequency hearing loss, affecting outer hair cells first.","kind":"trap","origin":"ai"},{"id":"inner-ear-disorders~ai-5","moduleId":"inner-ear-disorders","stem":"How does labyrinthitis differ from vestibular neuritis in terms of clinical presentation?","options":[{"id":"a","text":"Labyrinthitis involves hearing loss, vestibular neuritis does not"},{"id":"b","text":"Labyrinthitis is bilateral, vestibular neuritis is unilateral"},{"id":"c","text":"Labyrinthitis has a longer duration of vertigo"},{"id":"d","text":"Labyrinthitis is caused by ototoxic drugs"}],"answerId":"a","explanation":"Labyrinthitis presents with both vertigo and hearing loss, while vestibular neuritis spares hearing.","kind":"trap","origin":"ai"},{"id":"inner-ear-disorders~ai-6","moduleId":"inner-ear-disorders","stem":"How does the mechanism of hearing loss in Ménière disease relate to inner ear disorders?","options":[{"id":"a","text":"It results from cochlear nerve damage"},{"id":"b","text":"It is due to endolymphatic hydrops affecting hair cells"},{"id":"c","text":"It is caused by ototoxic medications"},{"id":"d","text":"It is related to temporal bone fractures"}],"answerId":"b","explanation":"Ménière disease involves endolymphatic hydrops leading to hair cell damage and fluctuating hearing loss.","kind":"integration","linkedModuleIds":["hearing-balance-basics"],"origin":"ai"},{"id":"inner-ear-disorders~ai-7","moduleId":"inner-ear-disorders","stem":"Which condition shares a similar pathophysiological mechanism with vestibular neuritis?","options":[{"id":"a","text":"Acoustic neuroma"},{"id":"b","text":"Labyrinthitis"},{"id":"c","text":"BPPV"},{"id":"d","text":"Post-viral vestibular dysfunction"}],"answerId":"d","explanation":"Post-viral vestibular dysfunction is similar to vestibular neuritis as both can follow viral infections and present with vertigo.","kind":"integration","linkedModuleIds":["external-ear-disorders"],"origin":"ai"}],"middle-ear-disorders":[{"id":"middle-ear-disorders~ai-0","moduleId":"middle-ear-disorders","stem":"What is the most common organism causing acute otitis media (AOM)?","options":[{"id":"a","text":"Streptococcus pneumoniae"},{"id":"b","text":"Haemophilus influenzae"},{"id":"c","text":"Moraxella catarrhalis"},{"id":"d","text":"Pseudomonas aeruginosa"}],"answerId":"a","explanation":"Streptococcus pneumoniae is the most prevalent pathogen in cases of acute otitis media.","kind":"recall","origin":"ai"},{"id":"middle-ear-disorders~ai-1","moduleId":"middle-ear-disorders","stem":"What is the primary mechanism leading to otitis media?","options":[{"id":"a","text":"Eustachian tube dysfunction"},{"id":"b","text":"Viral infection"},{"id":"c","text":"Allergic rhinitis"},{"id":"d","text":"Chronic sinusitis"}],"answerId":"a","explanation":"Eustachian tube dysfunction is the core mechanism that leads to fluid accumulation and infection in the middle ear.","kind":"mechanism","origin":"ai"},{"id":"middle-ear-disorders~ai-2","moduleId":"middle-ear-disorders","stem":"A 25-year-old presents with progressive conductive hearing loss and a normal tympanic membrane. What is the likely diagnosis?","options":[{"id":"a","text":"Acute otitis media"},{"id":"b","text":"Chronic otitis media"},{"id":"c","text":"Otosclerosis"},{"id":"d","text":"Eustachian tube dysfunction"}],"answerId":"c","explanation":"The presentation is consistent with otosclerosis, where the stapes footplate is fixed despite a normal tympanic membrane.","kind":"clinical","origin":"ai"},{"id":"middle-ear-disorders~ai-3","moduleId":"middle-ear-disorders","stem":"Which finding is characteristic of acute otitis media?","options":[{"id":"a","text":"Normal tympanic membrane"},{"id":"b","text":"Bulging, erythematous tympanic membrane"},{"id":"c","text":"Conductive hearing loss with a normal drum"},{"id":"d","text":"Clear middle ear effusion"}],"answerId":"b","explanation":"A bulging, erythematous tympanic membrane indicates the presence of pus in the middle ear, typical of acute otitis media.","kind":"recall","origin":"ai"},{"id":"middle-ear-disorders~ai-4","moduleId":"middle-ear-disorders","stem":"What complication should be suspected in a patient with postauricular swelling and facial weakness?","options":[{"id":"a","text":"Otosclerosis"},{"id":"b","text":"Mastoiditis"},{"id":"c","text":"Acute otitis media"},{"id":"d","text":"Eustachian tube dysfunction"}],"answerId":"b","explanation":"Postauricular swelling and facial weakness suggest mastoiditis, a serious complication of otitis media.","kind":"clinical","origin":"ai"},{"id":"middle-ear-disorders~ai-5","moduleId":"middle-ear-disorders","stem":"How does otitic barotrauma occur during air travel?","options":[{"id":"a","text":"Infection of the middle ear"},{"id":"b","text":"Eustachian tube obstruction"},{"id":"c","text":"Increased atmospheric pressure"},{"id":"d","text":"Decreased middle ear pressure"}],"answerId":"b","explanation":"Otitic barotrauma occurs due to Eustachian tube obstruction leading to pressure mismatch during changes in altitude.","kind":"mechanism","origin":"ai"},{"id":"middle-ear-disorders~ai-6","moduleId":"middle-ear-disorders","stem":"How does otosclerosis affect hearing, and what audiogram finding is typical?","options":[{"id":"a","text":"Mixed hearing loss; flat audiogram"},{"id":"b","text":"Conductive hearing loss; Carhart notch"},{"id":"c","text":"Sensorineural hearing loss; sloping audiogram"},{"id":"d","text":"Normal hearing; no findings"}],"answerId":"b","explanation":"Otosclerosis typically causes conductive hearing loss, and the audiogram shows a Carhart notch at 2000 Hz.","kind":"integration","linkedModuleIds":["hearing-balance-basics"],"origin":"ai"},{"id":"middle-ear-disorders~ai-7","moduleId":"middle-ear-disorders","stem":"Which condition is most likely to cause conductive hearing loss with a normal tympanic membrane?","options":[{"id":"a","text":"Acute otitis media"},{"id":"b","text":"Otosclerosis"},{"id":"c","text":"Chronic otitis media"},{"id":"d","text":"Eustachian tube dysfunction"}],"answerId":"b","explanation":"Otosclerosis can cause conductive hearing loss while the tympanic membrane appears normal.","kind":"integration","linkedModuleIds":["auditory-physiology-hearing"],"origin":"ai"}],"pediatric-infective-retina":[{"id":"pediatric-infective-retina~ai-0","moduleId":"pediatric-infective-retina","stem":"What is the most common primary intraocular malignancy in children?","options":[{"id":"a","text":"Retinoblastoma"},{"id":"b","text":"Choroidal melanoma"},{"id":"c","text":"Optic nerve glioma"},{"id":"d","text":"Wilms tumor"}],"answerId":"a","explanation":"Retinoblastoma is the most common primary intraocular malignancy in children, typically presenting before the age of 5.","kind":"recall","origin":"ai"},{"id":"pediatric-infective-retina~ai-1","moduleId":"pediatric-infective-retina","stem":"Which gene mutation is most commonly associated with hereditary retinoblastoma?","options":[{"id":"a","text":"TP53"},{"id":"b","text":"RB1"},{"id":"c","text":"BRCA1"},{"id":"d","text":"PTEN"}],"answerId":"b","explanation":"The RB1 gene mutation is associated with hereditary retinoblastoma, located on chromosome 13q14.","kind":"recall","origin":"ai"},{"id":"pediatric-infective-retina~ai-2","moduleId":"pediatric-infective-retina","stem":"A premature infant develops abnormal retinal neovascularization. What is the most likely diagnosis?","options":[{"id":"a","text":"Retinoblastoma"},{"id":"b","text":"Retinopathy of prematurity"},{"id":"c","text":"Endophthalmitis"},{"id":"d","text":"Congenital cataract"}],"answerId":"b","explanation":"Retinopathy of prematurity occurs in premature infants and is characterized by abnormal retinal neovascularization.","kind":"recall","origin":"ai"},{"id":"pediatric-infective-retina~ai-3","moduleId":"pediatric-infective-retina","stem":"What is the primary treatment for advanced retinoblastoma?","options":[{"id":"a","text":"Laser therapy"},{"id":"b","text":"Enucleation"},{"id":"c","text":"Observation"},{"id":"d","text":"Topical steroids"}],"answerId":"b","explanation":"Enucleation is indicated for advanced retinoblastoma when the tumor is not amenable to other treatments.","kind":"recall","origin":"ai"},{"id":"pediatric-infective-retina~ai-4","moduleId":"pediatric-infective-retina","stem":"A child presents with leukocoria and strabismus. What is the most critical next step?","options":[{"id":"a","text":"Schedule an eye exam in 6 months"},{"id":"b","text":"Refer to a pediatric ophthalmologist"},{"id":"c","text":"Perform a fundus examination"},{"id":"d","text":"Order a CT scan of the head"}],"answerId":"c","explanation":"A fundus examination is critical to rule out retinoblastoma, which is a life-threatening condition.","kind":"clinical","origin":"ai"},{"id":"pediatric-infective-retina~ai-5","moduleId":"pediatric-infective-retina","stem":"What is the most likely cause of painful red eye and hypopyon after ocular surgery?","options":[{"id":"a","text":"Retinoblastoma"},{"id":"b","text":"Endophthalmitis"},{"id":"c","text":"Uveitis"},{"id":"d","text":"Conjunctivitis"}],"answerId":"b","explanation":"Endophthalmitis is characterized by painful red eye and hypopyon, especially following surgery.","kind":"clinical","origin":"ai"},{"id":"pediatric-infective-retina~ai-6","moduleId":"pediatric-infective-retina","stem":"How does retinopathy of prematurity (ROP) primarily develop?","options":[{"id":"a","text":"Increased intraocular pressure"},{"id":"b","text":"Oxygen exposure"},{"id":"c","text":"Genetic mutations"},{"id":"d","text":"Viral infections"}],"answerId":"b","explanation":"ROP primarily develops due to abnormal retinal neovascularization related to oxygen exposure in premature infants.","kind":"mechanism","origin":"ai"},{"id":"pediatric-infective-retina~ai-7","moduleId":"pediatric-infective-retina","stem":"A child with leukocoria is suspected to have retinoblastoma. Which of the following conditions must be urgently ruled out?","options":[{"id":"a","text":"Congenital cataract"},{"id":"b","text":"Retinal detachment"},{"id":"c","text":"Vitreous hemorrhage"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"Leukocoria can be caused by several conditions, but retinoblastoma is life-threatening and must be ruled out urgently.","kind":"trap","origin":"ai"},{"id":"pediatric-infective-retina~ai-8","moduleId":"pediatric-infective-retina","stem":"How is diabetic retinopathy related to retinopathy of prematurity?","options":[{"id":"a","text":"Both are caused by genetic mutations"},{"id":"b","text":"Both involve abnormal retinal neovascularization"},{"id":"c","text":"Both present with leukocoria"},{"id":"d","text":"Both are treated with enucleation"}],"answerId":"b","explanation":"Both diabetic retinopathy and retinopathy of prematurity involve abnormal retinal neovascularization, though their causes differ.","kind":"integration","linkedModuleIds":["amd-diabetic-retinopathy"],"origin":"ai"}],"epidural-subdural-hematoma":[{"id":"epidural-subdural-hematoma~ai-0","moduleId":"epidural-subdural-hematoma","stem":"What is the most common vessel involved in an epidural hematoma?","options":[{"id":"a","text":"Middle meningeal artery"},{"id":"b","text":"Anterior cerebral artery"},{"id":"c","text":"Vertebral artery"},{"id":"d","text":"Superficial temporal artery"}],"answerId":"a","explanation":"The middle meningeal artery is the vessel most commonly ruptured in epidural hematomas, typically due to temporal bone fractures.","kind":"recall","origin":"ai"},{"id":"epidural-subdural-hematoma~ai-1","moduleId":"epidural-subdural-hematoma","stem":"Which CT finding is characteristic of a subdural hematoma?","options":[{"id":"a","text":"Biconvex shape"},{"id":"b","text":"Crescent shape"},{"id":"c","text":"Linear shape"},{"id":"d","text":"Mass effect with midline shift"}],"answerId":"b","explanation":"A subdural hematoma appears as a crescent-shaped collection on CT, crossing suture lines but not the midline.","kind":"recall","origin":"ai"},{"id":"epidural-subdural-hematoma~ai-2","moduleId":"epidural-subdural-hematoma","stem":"A patient presents with a lucid interval followed by rapid neurological decline after a head injury. What is the likely diagnosis?","options":[{"id":"a","text":"Subdural hematoma"},{"id":"b","text":"Epidural hematoma"},{"id":"c","text":"Chronic subdural hematoma"},{"id":"d","text":"Intracerebral hemorrhage"}],"answerId":"b","explanation":"The classic presentation of an epidural hematoma includes a lucid interval followed by rapid deterioration.","kind":"clinical","origin":"ai"},{"id":"epidural-subdural-hematoma~ai-3","moduleId":"epidural-subdural-hematoma","stem":"In which scenario is a subdural hematoma most likely to occur?","options":[{"id":"a","text":"In a young athlete after a concussion"},{"id":"b","text":"In an elderly patient with brain atrophy"},{"id":"c","text":"After a skull fracture in a child"},{"id":"d","text":"Following a penetrating head injury"}],"answerId":"b","explanation":"Subdural hematomas are more common in the elderly due to brain atrophy that stretches bridging veins.","kind":"clinical","origin":"ai"},{"id":"epidural-subdural-hematoma~ai-4","moduleId":"epidural-subdural-hematoma","stem":"Which statement correctly distinguishes between epidural and subdural hematomas?","options":[{"id":"a","text":"Both are arterial bleeds"},{"id":"b","text":"Epidural hematomas cross suture lines"},{"id":"c","text":"Subdural hematomas are crescent-shaped"},{"id":"d","text":"Epidural hematomas are venous bleeds"}],"answerId":"c","explanation":"Subdural hematomas are crescent-shaped and can cross suture lines, while epidural hematomas are biconvex and do not cross sutures.","kind":"trap","origin":"ai"},{"id":"epidural-subdural-hematoma~ai-5","moduleId":"epidural-subdural-hematoma","stem":"How does an epidural hematoma typically present on CT imaging?","options":[{"id":"a","text":"Crescent-shaped collection"},{"id":"b","text":"Biconvex collection"},{"id":"c","text":"Linear collection"},{"id":"d","text":"Mass effect with midline shift"}],"answerId":"b","explanation":"An epidural hematoma appears as a biconvex (lens-shaped) collection on CT, which does not cross suture lines.","kind":"recall","origin":"ai"},{"id":"epidural-subdural-hematoma~ai-6","moduleId":"epidural-subdural-hematoma","stem":"How might an epidural hematoma lead to herniation?","options":[{"id":"a","text":"By causing increased venous pressure"},{"id":"b","text":"By creating mass effect and raising ICP"},{"id":"c","text":"By disrupting the blood-brain barrier"},{"id":"d","text":"By inducing vasogenic edema"}],"answerId":"b","explanation":"Epidural hematomas create mass effect, leading to increased intracranial pressure (ICP) and potential herniation.","kind":"mechanism","origin":"ai"},{"id":"epidural-subdural-hematoma~ai-7","moduleId":"epidural-subdural-hematoma","stem":"In a patient with a subdural hematoma, which other condition should be considered due to its potential overlap?","options":[{"id":"a","text":"Epidural hematoma"},{"id":"b","text":"Intracerebral hemorrhage"},{"id":"c","text":"Meningitis"},{"id":"d","text":"Cerebral venous sinus thrombosis"}],"answerId":"a","explanation":"Epidural hematomas can present similarly to subdural hematomas, especially in cases of head trauma.","kind":"integration","linkedModuleIds":["traumatic-brain-spinal-injury"],"origin":"ai"},{"id":"epidural-subdural-hematoma~ai-8","moduleId":"epidural-subdural-hematoma","stem":"Which complication of a subdural hematoma may relate to the management of raised ICP?","options":[{"id":"a","text":"Herniation"},{"id":"b","text":"Seizures"},{"id":"c","text":"Cerebral edema"},{"id":"d","text":"Chronic headache"}],"answerId":"a","explanation":"Herniation is a serious complication of raised ICP, which can occur due to mass effect from a subdural hematoma.","kind":"integration","linkedModuleIds":["raised-icp-herniation"],"origin":"ai"}],"sah-aneurysm-avm-iph":[{"id":"sah-aneurysm-avm-iph~ai-0","moduleId":"sah-aneurysm-avm-iph","stem":"What is the most common cause of subarachnoid hemorrhage (SAH)?","options":[{"id":"a","text":"Traumatic injury"},{"id":"b","text":"Ruptured saccular aneurysm"},{"id":"c","text":"Arteriovenous malformation"},{"id":"d","text":"Cerebral amyloid angiopathy"}],"answerId":"b","explanation":"Ruptured saccular (berry) aneurysms are the most common cause of SAH, particularly at the Circle of Willis.","kind":"recall","origin":"ai"},{"id":"sah-aneurysm-avm-iph~ai-1","moduleId":"sah-aneurysm-avm-iph","stem":"Which of the following conditions is most commonly associated with berry aneurysms?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Ehlers-Danlos syndrome"},{"id":"c","text":"Diabetes mellitus"},{"id":"d","text":"Atherosclerosis"}],"answerId":"b","explanation":"Ehlers-Danlos syndrome, particularly type IV, is associated with the development of berry aneurysms due to connective tissue abnormalities.","kind":"recall","origin":"ai"},{"id":"sah-aneurysm-avm-iph~ai-2","moduleId":"sah-aneurysm-avm-iph","stem":"A 65-year-old man presents with sudden onset of a severe headache and confusion. A CT scan shows a lobar hemorrhage. What is the most likely underlying cause?","options":[{"id":"a","text":"Hypertensive microaneurysm"},{"id":"b","text":"Cerebral amyloid angiopathy"},{"id":"c","text":"Ruptured aneurysm"},{"id":"d","text":"Arteriovenous malformation"}],"answerId":"b","explanation":"Lobar hemorrhages in elderly patients are typically due to cerebral amyloid angiopathy, rather than hypertensive bleeds which are deep.","kind":"clinical","origin":"ai"},{"id":"sah-aneurysm-avm-iph~ai-3","moduleId":"sah-aneurysm-avm-iph","stem":"What mechanism primarily leads to intraparenchymal hemorrhage in hypertensive patients?","options":[{"id":"a","text":"Rupture of large cerebral arteries"},{"id":"b","text":"Rupture of Charcot-Bouchard microaneurysms"},{"id":"c","text":"Cerebral amyloid deposition"},{"id":"d","text":"Trauma"}],"answerId":"b","explanation":"Hypertensive intraparenchymal hemorrhage is often due to the rupture of Charcot-Bouchard microaneurysms affecting small penetrating arteries.","kind":"mechanism","origin":"ai"},{"id":"sah-aneurysm-avm-iph~ai-4","moduleId":"sah-aneurysm-avm-iph","stem":"A 30-year-old woman presents with seizures and a 'tangle of wormlike vessels' on imaging. What is the most likely diagnosis?","options":[{"id":"a","text":"Cerebral amyloid angiopathy"},{"id":"b","text":"Arteriovenous malformation"},{"id":"c","text":"Berry aneurysm"},{"id":"d","text":"Subdural hematoma"}],"answerId":"b","explanation":"The description of 'tangle of wormlike vessels' is characteristic of an arteriovenous malformation (AVM).","kind":"recall","origin":"ai"},{"id":"sah-aneurysm-avm-iph~ai-5","moduleId":"sah-aneurysm-avm-iph","stem":"In a patient with a history of chronic hypertension, which location is most likely for an intraparenchymal hemorrhage?","options":[{"id":"a","text":"Frontal lobe"},{"id":"b","text":"Cerebellum"},{"id":"c","text":"Temporal lobe"},{"id":"d","text":"Occipital lobe"}],"answerId":"b","explanation":"Hypertensive hemorrhages typically occur in deep structures such as the basal ganglia, thalamus, pons, and cerebellum.","kind":"trap","origin":"ai"},{"id":"sah-aneurysm-avm-iph~ai-6","moduleId":"sah-aneurysm-avm-iph","stem":"How does cerebral amyloid angiopathy differ from hypertensive hemorrhage in terms of bleeding location?","options":[{"id":"a","text":"Both cause deep hemorrhages"},{"id":"b","text":"Both cause lobar hemorrhages"},{"id":"c","text":"Hypertensive causes deep, amyloid causes lobar"},{"id":"d","text":"Amyloid causes deep, hypertensive causes lobar"}],"answerId":"c","explanation":"Hypertensive bleeds are typically deep, while lobar hemorrhages in the elderly suggest cerebral amyloid angiopathy.","kind":"integration","linkedModuleIds":["raised-icp-herniation"],"origin":"ai"},{"id":"sah-aneurysm-avm-iph~ai-7","moduleId":"sah-aneurysm-avm-iph","stem":"Which of the following findings would most likely indicate a subdural hematoma rather than a subarachnoid hemorrhage?","options":[{"id":"a","text":"Thunderclap headache"},{"id":"b","text":"Altered level of consciousness"},{"id":"c","text":"Crescent-shaped mass on CT"},{"id":"d","text":"Meningismus"}],"answerId":"c","explanation":"A crescent-shaped mass on CT is characteristic of a subdural hematoma, while SAH typically presents with a thunderclap headache and meningeal signs.","kind":"integration","linkedModuleIds":["epidural-subdural-hematoma"],"origin":"ai"}],"altered-mental-status-coma":[{"id":"altered-mental-status-coma~ai-0","moduleId":"altered-mental-status-coma","stem":"What is the primary function of the ascending reticular activating system (ARAS)?","options":[{"id":"a","text":"Regulate blood pressure"},{"id":"b","text":"Drive wakefulness"},{"id":"c","text":"Control motor function"},{"id":"d","text":"Process sensory information"}],"answerId":"b","explanation":"The ARAS is crucial for maintaining wakefulness and alertness.","kind":"recall","origin":"ai"},{"id":"altered-mental-status-coma~ai-1","moduleId":"altered-mental-status-coma","stem":"Which clinical finding is most indicative of metabolic/toxic encephalopathy?","options":[{"id":"a","text":"Focal weakness"},{"id":"b","text":"Neck stiffness"},{"id":"c","text":"Symmetric exam with preserved brainstem reflexes"},{"id":"d","text":"Gaze deviation"}],"answerId":"c","explanation":"A symmetric exam with preserved brainstem reflexes and no focal signs suggests a metabolic or toxic cause.","kind":"recall","origin":"ai"},{"id":"altered-mental-status-coma~ai-2","moduleId":"altered-mental-status-coma","stem":"In a patient with altered mental status, which initial step should be taken?","options":[{"id":"a","text":"Perform a CT scan"},{"id":"b","text":"Check glucose levels"},{"id":"c","text":"Administer intravenous fluids"},{"id":"d","text":"Obtain a lumbar puncture"}],"answerId":"b","explanation":"Checking glucose levels is a critical first step to rule out hypoglycemia as a cause of altered mental status.","kind":"clinical","origin":"ai"},{"id":"altered-mental-status-coma~ai-3","moduleId":"altered-mental-status-coma","stem":"Which of the following is a common cause of coma that does not present with focal neurological signs?","options":[{"id":"a","text":"Subarachnoid hemorrhage"},{"id":"b","text":"Stroke"},{"id":"c","text":"Metabolic derangement"},{"id":"d","text":"Brain tumor"}],"answerId":"c","explanation":"Metabolic derangements are a common cause of coma without focal neurological signs.","kind":"trap","origin":"ai"},{"id":"altered-mental-status-coma~ai-4","moduleId":"altered-mental-status-coma","stem":"What finding would most likely indicate meningitis in a patient with altered mental status?","options":[{"id":"a","text":"Symmetric neurological exam"},{"id":"b","text":"Neck stiffness with fever"},{"id":"c","text":"Bradycardia"},{"id":"d","text":"Hypotension"}],"answerId":"b","explanation":"Neck stiffness accompanied by fever is a classic sign of meningitis.","kind":"recall","origin":"ai"},{"id":"altered-mental-status-coma~ai-5","moduleId":"altered-mental-status-coma","stem":"In which condition would you expect to see elevated ammonia levels leading to altered mental status?","options":[{"id":"a","text":"Hepatic encephalopathy"},{"id":"b","text":"Wernicke's encephalopathy"},{"id":"c","text":"Uremic encephalopathy"},{"id":"d","text":"Subdural hematoma"}],"answerId":"a","explanation":"Hepatic encephalopathy is characterized by elevated ammonia levels due to liver dysfunction.","kind":"integration","linkedModuleIds":["hepatic-uremic-encephalopathy"],"origin":"ai"},{"id":"altered-mental-status-coma~ai-6","moduleId":"altered-mental-status-coma","stem":"A patient presents with altered mental status and a history of alcohol use. Which condition should be considered?","options":[{"id":"a","text":"Hepatic encephalopathy"},{"id":"b","text":"Wernicke's encephalopathy"},{"id":"c","text":"Uremic encephalopathy"},{"id":"d","text":"Metabolic syndrome"}],"answerId":"b","explanation":"Wernicke's encephalopathy is associated with thiamine deficiency, often seen in chronic alcohol users.","kind":"integration","linkedModuleIds":["wernicke-korsakoff"],"origin":"ai"}],"aeds-broad-spectrum":[{"id":"aeds-broad-spectrum~ai-0","moduleId":"aeds-broad-spectrum","stem":"Which of the following is a common side effect of valproate?","options":[{"id":"a","text":"Weight loss"},{"id":"b","text":"Alopecia"},{"id":"c","text":"Kidney stones"},{"id":"d","text":"Hypertension"}],"answerId":"b","explanation":"Alopecia is a known side effect of valproate, while weight loss and kidney stones are associated with topiramate.","kind":"recall","origin":"ai"},{"id":"aeds-broad-spectrum~ai-1","moduleId":"aeds-broad-spectrum","stem":"What is the primary mechanism of action of topiramate?","options":[{"id":"a","text":"Inhibition of NMDA receptors"},{"id":"b","text":"Inhibition of AMPA receptors"},{"id":"c","text":"Sodium channel blockade"},{"id":"d","text":"Inhibition of GABA transaminase"}],"answerId":"c","explanation":"Topiramate primarily acts by blocking sodium channels, in addition to enhancing GABA and inhibiting glutamate.","kind":"mechanism","origin":"ai"},{"id":"aeds-broad-spectrum~ai-2","moduleId":"aeds-broad-spectrum","stem":"A patient on levetiracetam presents with increased irritability. What is the most likely cause?","options":[{"id":"a","text":"Hepatotoxicity"},{"id":"b","text":"Behavioral side effect"},{"id":"c","text":"Renal failure"},{"id":"d","text":"Drug interaction"}],"answerId":"b","explanation":"Levetiracetam can cause mood and behavioral changes, which is a known side effect of this medication.","kind":"clinical","origin":"ai"},{"id":"aeds-broad-spectrum~ai-3","moduleId":"aeds-broad-spectrum","stem":"Which of the following AEDs is contraindicated in women of childbearing age due to teratogenic effects?","options":[{"id":"a","text":"Topiramate"},{"id":"b","text":"Levetiracetam"},{"id":"c","text":"Valproate"},{"id":"d","text":"Lamotrigine"}],"answerId":"c","explanation":"Valproate is highly teratogenic and should be avoided in women who may become pregnant.","kind":"trap","origin":"ai"},{"id":"aeds-broad-spectrum~ai-4","moduleId":"aeds-broad-spectrum","stem":"What is the mechanism of action of perampanel?","options":[{"id":"a","text":"AMPA receptor antagonist"},{"id":"b","text":"NMDA receptor antagonist"},{"id":"c","text":"GABA receptor agonist"},{"id":"d","text":"Sodium channel blocker"}],"answerId":"a","explanation":"Perampanel acts as an AMPA receptor antagonist, which can lead to behavioral and psychiatric effects.","kind":"mechanism","origin":"ai"},{"id":"aeds-broad-spectrum~ai-5","moduleId":"aeds-broad-spectrum","stem":"Which AED is most likely to cause kidney stones and cognitive slowing?","options":[{"id":"a","text":"Valproate"},{"id":"b","text":"Topiramate"},{"id":"c","text":"Levetiracetam"},{"id":"d","text":"Brivaracetam"}],"answerId":"b","explanation":"Topiramate is associated with kidney stones and cognitive slowing due to its carbonic anhydrase inhibition.","kind":"recall","origin":"ai"},{"id":"aeds-broad-spectrum~ai-6","moduleId":"aeds-broad-spectrum","stem":"How does the mechanism of action of valproate contribute to its broad-spectrum efficacy?","options":[{"id":"a","text":"Inhibition of sodium channels only"},{"id":"b","text":"Inhibition of glutamate only"},{"id":"c","text":"Multiple targets including sodium and calcium channels"},{"id":"d","text":"Selective GABA enhancement only"}],"answerId":"c","explanation":"Valproate hits multiple targets, including sodium and calcium channels, which contributes to its efficacy against various seizure types.","kind":"integration","linkedModuleIds":["aeds-gaba-and-absence"],"origin":"ai"},{"id":"aeds-broad-spectrum~ai-7","moduleId":"aeds-broad-spectrum","stem":"Which neurotransmitter system is primarily affected by the action of levetiracetam?","options":[{"id":"a","text":"Dopaminergic system"},{"id":"b","text":"GABAergic system"},{"id":"c","text":"Glutamatergic system"},{"id":"d","text":"Cholinergic system"}],"answerId":"c","explanation":"Levetiracetam primarily affects the glutamatergic system by binding to SV2A, influencing synaptic vesicle release.","kind":"integration","linkedModuleIds":["cns-neurotransmission-systems"],"origin":"ai"}],"aeds-principles-targets":[{"id":"aeds-principles-targets~ai-0","moduleId":"aeds-principles-targets","stem":"What is the primary mechanism by which antiepileptic drugs (AEDs) reduce neuronal excitability?","options":[{"id":"a","text":"Blocking voltage-gated ion channels"},{"id":"b","text":"Increasing sodium influx"},{"id":"c","text":"Enhancing glutamate transmission"},{"id":"d","text":"Decreasing GABA activity"}],"answerId":"a","explanation":"AEDs primarily reduce neuronal excitability by blocking voltage-gated ion channels, thereby preventing excessive neuronal firing.","kind":"mechanism","origin":"ai"},{"id":"aeds-principles-targets~ai-1","moduleId":"aeds-principles-targets","stem":"Which of the following is the first-line treatment for status epilepticus?","options":[{"id":"a","text":"Phenytoin"},{"id":"b","text":"Ethosuximide"},{"id":"c","text":"Lorazepam"},{"id":"d","text":"Carbamazepine"}],"answerId":"c","explanation":"Lorazepam is the first-line treatment for status epilepticus, providing rapid control of seizures.","kind":"recall","origin":"ai"},{"id":"aeds-principles-targets~ai-2","moduleId":"aeds-principles-targets","stem":"A patient presents with brief staring spells and 3-Hz spike-wave discharges on EEG. What type of seizure is this?","options":[{"id":"a","text":"Tonic-clonic seizure"},{"id":"b","text":"Focal seizure"},{"id":"c","text":"Absence seizure"},{"id":"d","text":"Myoclonic seizure"}],"answerId":"c","explanation":"The described EEG pattern is characteristic of absence seizures, which are typically brief and involve staring spells.","kind":"recall","origin":"ai"},{"id":"aeds-principles-targets~ai-3","moduleId":"aeds-principles-targets","stem":"Which of the following medications is contraindicated in a patient with absence seizures?","options":[{"id":"a","text":"Ethosuximide"},{"id":"b","text":"Valproate"},{"id":"c","text":"Carbamazepine"},{"id":"d","text":"Lamotrigine"}],"answerId":"c","explanation":"Carbamazepine is contraindicated in absence seizures as it can worsen the condition; ethosuximide and valproate are preferred.","kind":"trap","origin":"ai"},{"id":"aeds-principles-targets~ai-4","moduleId":"aeds-principles-targets","stem":"How do GABAergic agents primarily exert their effect in the treatment of epilepsy?","options":[{"id":"a","text":"By enhancing excitatory neurotransmission"},{"id":"b","text":"By blocking sodium channels"},{"id":"c","text":"By increasing GABA receptor activity"},{"id":"d","text":"By decreasing calcium influx"}],"answerId":"c","explanation":"GABAergic agents enhance inhibitory neurotransmission by increasing GABA receptor activity, thereby reducing neuronal excitability.","kind":"mechanism","origin":"ai"},{"id":"aeds-principles-targets~ai-5","moduleId":"aeds-principles-targets","stem":"Which antiepileptic drug is specifically indicated for absence seizures?","options":[{"id":"a","text":"Phenytoin"},{"id":"b","text":"Ethosuximide"},{"id":"c","text":"Gabapentin"},{"id":"d","text":"Carbamazepine"}],"answerId":"b","explanation":"Ethosuximide is specifically indicated for absence seizures and is effective in reducing their frequency.","kind":"recall","origin":"ai"},{"id":"aeds-principles-targets~ai-6","moduleId":"aeds-principles-targets","stem":"How might thiamine deficiency relate to seizure management in alcohol withdrawal?","options":[{"id":"a","text":"It increases GABAergic activity"},{"id":"b","text":"It can precipitate seizures"},{"id":"c","text":"It enhances excitatory neurotransmission"},{"id":"d","text":"It decreases sodium channel activity"}],"answerId":"b","explanation":"Thiamine deficiency can precipitate seizures, particularly in alcohol withdrawal, necessitating its management alongside seizure treatment.","kind":"integration","linkedModuleIds":["thiamine-wernicke-recovery"],"origin":"ai"},{"id":"aeds-principles-targets~ai-7","moduleId":"aeds-principles-targets","stem":"Which of the following AEDs would be inappropriate for a patient with both absence seizures and a history of focal seizures?","options":[{"id":"a","text":"Valproate"},{"id":"b","text":"Lamotrigine"},{"id":"c","text":"Carbamazepine"},{"id":"d","text":"Ethosuximide"}],"answerId":"c","explanation":"Carbamazepine is inappropriate for absence seizures as it can worsen them, despite being effective for focal seizures.","kind":"integration","linkedModuleIds":["aeds-broad-spectrum"],"origin":"ai"}],"aeds-sodium-channel-blockers":[{"id":"aeds-sodium-channel-blockers~ai-0","moduleId":"aeds-sodium-channel-blockers","stem":"Which of the following antiepileptic drugs primarily enhances Na⁺-channel inactivation?","options":[{"id":"a","text":"Phenytoin"},{"id":"b","text":"Lamotrigine"},{"id":"c","text":"Lacosamide"},{"id":"d","text":"Carbamazepine"}],"answerId":"a","explanation":"Phenytoin is a sodium channel blocker that enhances Na⁺-channel inactivation, making it effective for focal and tonic-clonic seizures.","kind":"recall","origin":"ai"},{"id":"aeds-sodium-channel-blockers~ai-1","moduleId":"aeds-sodium-channel-blockers","stem":"What is the primary mechanism by which sodium channel blockers suppress seizure activity?","options":[{"id":"a","text":"Enhance Na⁺ influx"},{"id":"b","text":"Stabilize inactivated Na⁺ channels"},{"id":"c","text":"Increase glutamate release"},{"id":"d","text":"Inhibit GABA metabolism"}],"answerId":"b","explanation":"Sodium channel blockers stabilize inactivated Na⁺ channels, which suppresses rapid neuronal firing associated with seizures.","kind":"mechanism","origin":"ai"},{"id":"aeds-sodium-channel-blockers~ai-2","moduleId":"aeds-sodium-channel-blockers","stem":"A patient on phenytoin presents with gingival hyperplasia and hirsutism. What is the most likely cause?","options":[{"id":"a","text":"Chronic phenytoin use"},{"id":"b","text":"Hypersensitivity reaction"},{"id":"c","text":"Drug interaction"},{"id":"d","text":"Underlying genetic condition"}],"answerId":"a","explanation":"Gingival hyperplasia and hirsutism are well-known chronic effects of phenytoin therapy.","kind":"clinical","origin":"ai"},{"id":"aeds-sodium-channel-blockers~ai-3","moduleId":"aeds-sodium-channel-blockers","stem":"Which of the following statements about phenytoin dosing is correct?","options":[{"id":"a","text":"Doubling the dose will double the serum level"},{"id":"b","text":"It has first-order kinetics at all doses"},{"id":"c","text":"Small dose increases can lead to large increases in serum level"},{"id":"d","text":"It is completely eliminated at therapeutic doses"}],"answerId":"c","explanation":"Phenytoin exhibits zero-order kinetics, meaning small increases in dose can lead to disproportionately large increases in serum levels.","kind":"trap","origin":"ai"},{"id":"aeds-sodium-channel-blockers~ai-4","moduleId":"aeds-sodium-channel-blockers","stem":"A patient with a history of carbamazepine use presents with hyponatremia and a rash. What genetic screening is recommended?","options":[{"id":"a","text":"HLA-B*1502"},{"id":"b","text":"HLA-DRB1"},{"id":"c","text":"HLA-A*0201"},{"id":"d","text":"HLA-C*0602"}],"answerId":"a","explanation":"Patients of Asian descent should be screened for HLA-B*1502 due to the risk of Stevens-Johnson syndrome associated with carbamazepine.","kind":"clinical","origin":"ai"},{"id":"aeds-sodium-channel-blockers~ai-5","moduleId":"aeds-sodium-channel-blockers","stem":"How does the mechanism of action of lamotrigine differ from that of phenytoin?","options":[{"id":"a","text":"It enhances Na⁺ influx"},{"id":"b","text":"It blocks Na⁺ channels and decreases glutamate release"},{"id":"c","text":"It only affects GABA receptors"},{"id":"d","text":"It has no effect on Na⁺ channels"}],"answerId":"b","explanation":"Lamotrigine blocks Na⁺ channels and decreases glutamate release, differing from phenytoin's primary action of stabilizing inactivated Na⁺ channels.","kind":"integration","linkedModuleIds":["aeds-principles-targets"],"origin":"ai"},{"id":"aeds-sodium-channel-blockers~ai-6","moduleId":"aeds-sodium-channel-blockers","stem":"Which electrolyte imbalance is most commonly associated with carbamazepine therapy?","options":[{"id":"a","text":"Hyperkalemia"},{"id":"b","text":"Hyponatremia"},{"id":"c","text":"Hypercalcemia"},{"id":"d","text":"Hypomagnesemia"}],"answerId":"b","explanation":"Carbamazepine can cause hyponatremia due to its effect on antidiuretic hormone, leading to SIADH.","kind":"integration","linkedModuleIds":["sodium-water-disorders"],"origin":"ai"}],"cns-neurotransmitters":[{"id":"cns-neurotransmitters~ai-0","moduleId":"cns-neurotransmitters","stem":"Which neurotransmitter is primarily responsible for excitatory signaling in the central nervous system?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"GABA"},{"id":"c","text":"Glutamate"},{"id":"d","text":"Serotonin"}],"answerId":"c","explanation":"Glutamate is the main excitatory neurotransmitter in the CNS, while GABA is the primary inhibitory neurotransmitter.","kind":"recall","origin":"ai"},{"id":"cns-neurotransmitters~ai-1","moduleId":"cns-neurotransmitters","stem":"What is the mechanism of action of benzodiazepines?","options":[{"id":"a","text":"Block GABA_A receptors"},{"id":"b","text":"Enhance GABA_A receptor activity"},{"id":"c","text":"Inhibit GABA_B receptors"},{"id":"d","text":"Increase glutamate release"}],"answerId":"b","explanation":"Benzodiazepines enhance the activity of GABA_A receptors, leading to increased inhibitory signaling.","kind":"mechanism","origin":"ai"},{"id":"cns-neurotransmitters~ai-2","moduleId":"cns-neurotransmitters","stem":"A patient on antipsychotic medication develops galactorrhea. Which pathway is likely affected?","options":[{"id":"a","text":"Mesolimbic pathway"},{"id":"b","text":"Nigrostriatal pathway"},{"id":"c","text":"Tuberoinfundibular pathway"},{"id":"d","text":"Corticostriatal pathway"}],"answerId":"c","explanation":"Galactorrhea is associated with tuberoinfundibular D2 blockade, leading to hyperprolactinemia.","kind":"clinical","origin":"ai"},{"id":"cns-neurotransmitters~ai-3","moduleId":"cns-neurotransmitters","stem":"Which of the following is a common side effect of D2 antagonism in antipsychotic treatment?","options":[{"id":"a","text":"Increased appetite"},{"id":"b","text":"Extrapyramidal symptoms"},{"id":"c","text":"Sedation"},{"id":"d","text":"Weight loss"}],"answerId":"b","explanation":"D2 antagonism can lead to extrapyramidal symptoms due to effects on the nigrostriatal pathway.","kind":"trap","origin":"ai"},{"id":"cns-neurotransmitters~ai-4","moduleId":"cns-neurotransmitters","stem":"Which drug class is used to treat depression by increasing serotonin levels?","options":[{"id":"a","text":"Dopamine agonists"},{"id":"b","text":"SSRIs"},{"id":"c","text":"Benzodiazepines"},{"id":"d","text":"Triptans"}],"answerId":"b","explanation":"SSRIs (Selective Serotonin Reuptake Inhibitors) increase serotonin levels in the synaptic cleft to alleviate depression.","kind":"recall","origin":"ai"},{"id":"cns-neurotransmitters~ai-5","moduleId":"cns-neurotransmitters","stem":"How do triptans alleviate migraine symptoms?","options":[{"id":"a","text":"Agonizing 5-HT1B/1D receptors"},{"id":"b","text":"Blocking D2 receptors"},{"id":"c","text":"Increasing dopamine release"},{"id":"d","text":"Inhibiting GABA_A receptors"}],"answerId":"a","explanation":"Triptans are 5-HT1B/1D agonists that help constrict blood vessels and reduce inflammation in migraines.","kind":"mechanism","origin":"ai"},{"id":"cns-neurotransmitters~ai-6","moduleId":"cns-neurotransmitters","stem":"How does the mechanism of action of stimulants relate to neurotransmitter balance?","options":[{"id":"a","text":"They inhibit GABA release"},{"id":"b","text":"They enhance dopamine and norepinephrine release"},{"id":"c","text":"They block serotonin receptors"},{"id":"d","text":"They reduce glutamate activity"}],"answerId":"b","explanation":"Stimulants enhance the release of dopamine and norepinephrine, correcting the imbalance in neurotransmitter signaling.","kind":"integration","linkedModuleIds":["cns-stimulants"],"origin":"ai"},{"id":"cns-neurotransmitters~ai-7","moduleId":"cns-neurotransmitters","stem":"What is the primary effect of GABA_A receptor activation?","options":[{"id":"a","text":"Increased neuronal excitability"},{"id":"b","text":"Increased chloride ion influx"},{"id":"c","text":"Increased dopamine release"},{"id":"d","text":"Decreased serotonin levels"}],"answerId":"b","explanation":"Activation of GABA_A receptors leads to increased chloride ion influx, resulting in hyperpolarization and decreased neuronal excitability.","kind":"recall","origin":"ai"}],"wernicke-korsakoff":[{"id":"wernicke-korsakoff~ai-0","moduleId":"wernicke-korsakoff","stem":"What is the primary cause of Wernicke encephalopathy?","options":[{"id":"a","text":"Thiamine (B1) deficiency"},{"id":"b","text":"Vitamin B12 deficiency"},{"id":"c","text":"Folate deficiency"},{"id":"d","text":"Iron deficiency"}],"answerId":"a","explanation":"Wernicke encephalopathy is primarily caused by thiamine (B1) deficiency, often due to chronic alcohol use.","kind":"recall","origin":"ai"},{"id":"wernicke-korsakoff~ai-1","moduleId":"wernicke-korsakoff","stem":"Which of the following is part of the classic triad of Wernicke encephalopathy?","options":[{"id":"a","text":"Severe headache"},{"id":"b","text":"Confusion"},{"id":"c","text":"Seizures"},{"id":"d","text":"Dysphagia"}],"answerId":"b","explanation":"The classic triad of Wernicke encephalopathy includes confusion, oculomotor dysfunction, and gait ataxia.","kind":"recall","origin":"ai"},{"id":"wernicke-korsakoff~ai-2","moduleId":"wernicke-korsakoff","stem":"What is the mechanism by which thiamine deficiency leads to Wernicke encephalopathy?","options":[{"id":"a","text":"Inhibition of glucose metabolism"},{"id":"b","text":"Decreased neurotransmitter synthesis"},{"id":"c","text":"Midline necrosis of the brain"},{"id":"d","text":"Increased oxidative stress"}],"answerId":"c","explanation":"Thiamine deficiency leads to midline necrosis of the brain structures, resulting in the symptoms of Wernicke encephalopathy.","kind":"mechanism","origin":"ai"},{"id":"wernicke-korsakoff~ai-3","moduleId":"wernicke-korsakoff","stem":"A patient presents with confusion, horizontal nystagmus, and ataxic gait. What is the most appropriate initial treatment?","options":[{"id":"a","text":"IV glucose"},{"id":"b","text":"Oral thiamine"},{"id":"c","text":"IV thiamine"},{"id":"d","text":"IV dextrose with thiamine"}],"answerId":"c","explanation":"The most appropriate initial treatment is IV thiamine to prevent worsening of Wernicke encephalopathy before administering glucose.","kind":"clinical","origin":"ai"},{"id":"wernicke-korsakoff~ai-4","moduleId":"wernicke-korsakoff","stem":"Which of the following findings is characteristic of Korsakoff syndrome?","options":[{"id":"a","text":"Severe headache"},{"id":"b","text":"Anterograde amnesia with confabulation"},{"id":"c","text":"Visual hallucinations"},{"id":"d","text":"Severe ataxia"}],"answerId":"b","explanation":"Korsakoff syndrome is characterized by anterograde amnesia and confabulation due to damage to the mammillary bodies.","kind":"recall","origin":"ai"},{"id":"wernicke-korsakoff~ai-5","moduleId":"wernicke-korsakoff","stem":"In a patient with suspected Wernicke encephalopathy, which history is most relevant?","options":[{"id":"a","text":"Recent head trauma"},{"id":"b","text":"History of chronic alcohol use"},{"id":"c","text":"Recent viral infection"},{"id":"d","text":"Family history of dementia"}],"answerId":"b","explanation":"A history of chronic alcohol use is highly relevant as it is a common cause of thiamine deficiency leading to Wernicke encephalopathy.","kind":"trap","origin":"ai"},{"id":"wernicke-korsakoff~ai-6","moduleId":"wernicke-korsakoff","stem":"How does thiamine administration impact recovery from Wernicke encephalopathy?","options":[{"id":"a","text":"It reverses all neurological deficits"},{"id":"b","text":"It prevents further brain damage"},{"id":"c","text":"It increases glucose metabolism"},{"id":"d","text":"It enhances vitamin B12 absorption"}],"answerId":"b","explanation":"Thiamine administration prevents further brain damage by addressing the deficiency that causes Wernicke encephalopathy.","kind":"integration","linkedModuleIds":["thiamine-wernicke-recovery"],"origin":"ai"},{"id":"wernicke-korsakoff~ai-7","moduleId":"wernicke-korsakoff","stem":"Which of the following conditions shares a common risk factor with Wernicke encephalopathy?","options":[{"id":"a","text":"Hepatic encephalopathy"},{"id":"b","text":"Diabetic ketoacidosis"},{"id":"c","text":"Cirrhosis"},{"id":"d","text":"Hyperglycemia"}],"answerId":"a","explanation":"Hepatic encephalopathy shares a common risk factor of malnutrition and alcohol use, similar to Wernicke encephalopathy.","kind":"integration","linkedModuleIds":["hepatic-uremic-encephalopathy"],"origin":"ai"}],"aeds-gaba-and-absence":[{"id":"aeds-gaba-and-absence~ai-0","moduleId":"aeds-gaba-and-absence","stem":"What is the primary mechanism of action of ethosuximide in treating absence seizures?","options":[{"id":"a","text":"Inhibition of GABA transaminase"},{"id":"b","text":"Blockade of T-type Ca²⁺ channels"},{"id":"c","text":"Enhancement of GABA_A receptors"},{"id":"d","text":"Inhibition of sodium channels"}],"answerId":"b","explanation":"Ethosuximide primarily blocks T-type Ca²⁺ channels in thalamic neurons, which is crucial for controlling absence seizures.","kind":"mechanism","origin":"ai"},{"id":"aeds-gaba-and-absence~ai-1","moduleId":"aeds-gaba-and-absence","stem":"Which AED is known to cause peripheral visual field constriction as a side effect?","options":[{"id":"a","text":"Phenobarbital"},{"id":"b","text":"Ethosuximide"},{"id":"c","text":"Vigabatrin"},{"id":"d","text":"Gabapentin"}],"answerId":"c","explanation":"Vigabatrin is associated with peripheral visual field constriction due to its irreversible inhibition of GABA transaminase.","kind":"recall","origin":"ai"},{"id":"aeds-gaba-and-absence~ai-2","moduleId":"aeds-gaba-and-absence","stem":"What is a significant side effect of long-term use of benzodiazepines in seizure management?","options":[{"id":"a","text":"Hepatic toxicity"},{"id":"b","text":"Sedation"},{"id":"c","text":"Visual disturbances"},{"id":"d","text":"Renal toxicity"}],"answerId":"b","explanation":"Benzodiazepines enhance GABA_A receptors, leading to sedation, which is a common side effect.","kind":"trap","origin":"ai"},{"id":"aeds-gaba-and-absence~ai-3","moduleId":"aeds-gaba-and-absence","stem":"Which of the following AEDs is contraindicated in absence seizures?","options":[{"id":"a","text":"Tiagabine"},{"id":"b","text":"Ethosuximide"},{"id":"c","text":"Phenobarbital"},{"id":"d","text":"Clonazepam"}],"answerId":"a","explanation":"Tiagabine is contraindicated in absence seizures as it can worsen the condition.","kind":"recall","origin":"ai"},{"id":"aeds-gaba-and-absence~ai-4","moduleId":"aeds-gaba-and-absence","stem":"Gabapentin and pregabalin primarily act on which subunit of voltage-gated calcium channels?","options":[{"id":"a","text":"α1"},{"id":"b","text":"α2"},{"id":"c","text":"α2δ"},{"id":"d","text":"β"}],"answerId":"c","explanation":"Gabapentin and pregabalin act at the α2δ subunit of voltage-gated calcium channels, not on GABA receptors.","kind":"mechanism","origin":"ai"},{"id":"aeds-gaba-and-absence~ai-5","moduleId":"aeds-gaba-and-absence","stem":"Which AED is first-line for status epilepticus?","options":[{"id":"a","text":"Ethosuximide"},{"id":"b","text":"Phenobarbital"},{"id":"c","text":"Vigabatrin"},{"id":"d","text":"Tiagabine"}],"answerId":"b","explanation":"Phenobarbital is a first-line treatment for status epilepticus due to its GABA_A enhancing effects.","kind":"recall","origin":"ai"},{"id":"aeds-gaba-and-absence~ai-6","moduleId":"aeds-gaba-and-absence","stem":"How do ethosuximide and gabapentin differ in their mechanisms of action?","options":[{"id":"a","text":"Both enhance GABA_A receptors"},{"id":"b","text":"Both block T-type Ca²⁺ channels"},{"id":"c","text":"Ethosuximide blocks T-type Ca²⁺ channels while gabapentin acts on α2δ subunit"},{"id":"d","text":"Gabapentin enhances GABA_A receptors while ethosuximide does not"}],"answerId":"c","explanation":"Ethosuximide blocks T-type Ca²⁺ channels, while gabapentin acts on the α2δ subunit of voltage-gated calcium channels.","kind":"integration","linkedModuleIds":["aeds-principles-targets"],"origin":"ai"},{"id":"aeds-gaba-and-absence~ai-7","moduleId":"aeds-gaba-and-absence","stem":"Which AED is effective for both absence seizures and myoclonic seizures?","options":[{"id":"a","text":"Clonazepam"},{"id":"b","text":"Ethosuximide"},{"id":"c","text":"Phenobarbital"},{"id":"d","text":"Vigabatrin"}],"answerId":"a","explanation":"Clonazepam is effective for myoclonic seizures and can also be used for absence seizures.","kind":"integration","linkedModuleIds":["aeds-broad-spectrum"],"origin":"ai"}],"levodopa-and-adjuncts":[{"id":"levodopa-and-adjuncts~ai-0","moduleId":"levodopa-and-adjuncts","stem":"What is the primary mechanism of action of levodopa in treating Parkinson's disease?","options":[{"id":"a","text":"Inhibits peripheral DOPA-decarboxylase"},{"id":"b","text":"Increases dopamine release from neurons"},{"id":"c","text":"Crosses the blood-brain barrier and is converted to dopamine"},{"id":"d","text":"Inhibits acetylcholine release"}],"answerId":"c","explanation":"Levodopa crosses the blood-brain barrier and is decarboxylated to dopamine, replenishing central dopamine levels.","kind":"mechanism","origin":"ai"},{"id":"levodopa-and-adjuncts~ai-1","moduleId":"levodopa-and-adjuncts","stem":"Which of the following is a common side effect of initiating levodopa therapy?","options":[{"id":"a","text":"Dysphagia"},{"id":"b","text":"Nausea"},{"id":"c","text":"Tachycardia"},{"id":"d","text":"Hyperglycemia"}],"answerId":"b","explanation":"Nausea is a common side effect due to peripheral dopamine activity before carbidopa is added.","kind":"recall","origin":"ai"},{"id":"levodopa-and-adjuncts~ai-2","moduleId":"levodopa-and-adjuncts","stem":"What is the purpose of adding carbidopa to levodopa therapy?","options":[{"id":"a","text":"To enhance dopamine receptor sensitivity"},{"id":"b","text":"To prevent levodopa from being converted to dopamine in the periphery"},{"id":"c","text":"To increase the half-life of levodopa"},{"id":"d","text":"To improve the absorption of levodopa in the intestines"}],"answerId":"b","explanation":"Carbidopa inhibits peripheral DOPA-decarboxylase, allowing more levodopa to reach the brain and reducing peripheral side effects.","kind":"trap","origin":"ai"},{"id":"levodopa-and-adjuncts~ai-3","moduleId":"levodopa-and-adjuncts","stem":"What is the most likely cause of 'wearing-off' phenomenon in a patient on long-term levodopa?","options":[{"id":"a","text":"Increased peripheral metabolism of levodopa"},{"id":"b","text":"Decreased central dopamine receptor sensitivity"},{"id":"c","text":"Fluctuating levels of levodopa in the bloodstream"},{"id":"d","text":"Development of antibodies against levodopa"}],"answerId":"c","explanation":"'Wearing-off' occurs due to fluctuating levels of levodopa, leading to periods of reduced efficacy.","kind":"clinical","origin":"ai"},{"id":"levodopa-and-adjuncts~ai-4","moduleId":"levodopa-and-adjuncts","stem":"Which of the following adjunct therapies can prolong the effect of levodopa?","options":[{"id":"a","text":"Selegiline"},{"id":"b","text":"Haloperidol"},{"id":"c","text":"Buspirone"},{"id":"d","text":"Amitriptyline"}],"answerId":"a","explanation":"Selegiline is a MAO-B inhibitor that raises dopamine levels and can prolong the effects of levodopa.","kind":"recall","origin":"ai"},{"id":"levodopa-and-adjuncts~ai-5","moduleId":"levodopa-and-adjuncts","stem":"In a patient with Parkinson's disease, which symptom is most likely to improve with levodopa treatment?","options":[{"id":"a","text":"Postural instability"},{"id":"b","text":"Resting tremor"},{"id":"c","text":"Cognitive decline"},{"id":"d","text":"Dysphagia"}],"answerId":"b","explanation":"Levodopa is particularly effective in improving bradykinesia and rigidity, but resting tremor can also improve.","kind":"recall","origin":"ai"},{"id":"levodopa-and-adjuncts~ai-6","moduleId":"levodopa-and-adjuncts","stem":"How does the mechanism of action of MAO-B inhibitors relate to the treatment of Parkinson's disease?","options":[{"id":"a","text":"They directly stimulate dopamine receptors"},{"id":"b","text":"They increase the degradation of dopamine"},{"id":"c","text":"They inhibit the breakdown of dopamine, enhancing its availability"},{"id":"d","text":"They block acetylcholine receptors"}],"answerId":"c","explanation":"MAO-B inhibitors prevent the breakdown of dopamine, increasing its availability in the synaptic cleft.","kind":"integration","linkedModuleIds":["cns-neurotransmission-systems"],"origin":"ai"},{"id":"levodopa-and-adjuncts~ai-7","moduleId":"levodopa-and-adjuncts","stem":"Which basal ganglia circuit alteration is primarily responsible for the symptoms of Parkinson's disease?","options":[{"id":"a","text":"Increased direct pathway activity"},{"id":"b","text":"Decreased indirect pathway activity"},{"id":"c","text":"Decreased dopamine input to the striatum"},{"id":"d","text":"Increased GABAergic output from the globus pallidus"}],"answerId":"c","explanation":"The loss of dopaminergic input to the striatum leads to increased inhibition of the thalamus, resulting in motor symptoms.","kind":"integration","linkedModuleIds":["basal-ganglia-circuitry"],"origin":"ai"}],"periodic-paralysis":[{"id":"periodic-paralysis~ai-0","moduleId":"periodic-paralysis","stem":"What is the primary characteristic of periodic paralysis?","options":[{"id":"a","text":"Episodic spastic weakness"},{"id":"b","text":"Episodic flaccid weakness"},{"id":"c","text":"Constant muscle weakness"},{"id":"d","text":"Progressive muscle atrophy"}],"answerId":"b","explanation":"Periodic paralysis is defined by episodes of flaccid weakness with normal strength between attacks.","kind":"recall","origin":"ai"},{"id":"periodic-paralysis~ai-1","moduleId":"periodic-paralysis","stem":"Which of the following triggers hypokalemic periodic paralysis?","options":[{"id":"a","text":"Fasting"},{"id":"b","text":"Heavy carbohydrate meals"},{"id":"c","text":"Cold exposure"},{"id":"d","text":"Intense exercise"}],"answerId":"b","explanation":"Hypokalemic periodic paralysis attacks are often triggered by heavy carbohydrate meals.","kind":"mechanism","origin":"ai"},{"id":"periodic-paralysis~ai-2","moduleId":"periodic-paralysis","stem":"A 25-year-old man presents with episodic flaccid weakness after heavy meals. His potassium level during an attack is low. What is the most likely diagnosis?","options":[{"id":"a","text":"Hyperkalemic periodic paralysis"},{"id":"b","text":"Hypokalemic periodic paralysis"},{"id":"c","text":"Myasthenia gravis"},{"id":"d","text":"Guillain-Barré syndrome"}],"answerId":"b","explanation":"The patient's symptoms and low potassium level during an attack are characteristic of hypokalemic periodic paralysis.","kind":"clinical","origin":"ai"},{"id":"periodic-paralysis~ai-3","moduleId":"periodic-paralysis","stem":"Which finding is characteristic of hyperkalemic periodic paralysis?","options":[{"id":"a","text":"Low potassium levels during attacks"},{"id":"b","text":"Myotonia"},{"id":"c","text":"Prolonged episodes lasting days"},{"id":"d","text":"Family history of myopathy"}],"answerId":"b","explanation":"Myotonia is a common feature associated with hyperkalemic periodic paralysis.","kind":"recall","origin":"ai"},{"id":"periodic-paralysis~ai-4","moduleId":"periodic-paralysis","stem":"A patient presents with episodic weakness and a family history of similar symptoms. What should be prioritized in the workup?","options":[{"id":"a","text":"Psychiatric evaluation"},{"id":"b","text":"Thyroid function tests"},{"id":"c","text":"Electromyography"},{"id":"d","text":"MRI of the brain"}],"answerId":"b","explanation":"Thyroid function tests are crucial to rule out thyrotoxic periodic paralysis, a treatable condition.","kind":"trap","origin":"ai"},{"id":"periodic-paralysis~ai-5","moduleId":"periodic-paralysis","stem":"In a patient with periodic paralysis, which electrolyte disturbance is most likely during an attack of hypokalemic periodic paralysis?","options":[{"id":"a","text":"Hypercalcemia"},{"id":"b","text":"Hypernatremia"},{"id":"c","text":"Hypokalemia"},{"id":"d","text":"Hyperphosphatemia"}],"answerId":"c","explanation":"Hypokalemia is the hallmark electrolyte disturbance observed during an attack of hypokalemic periodic paralysis.","kind":"recall","origin":"ai"},{"id":"periodic-paralysis~ai-6","moduleId":"periodic-paralysis","stem":"How can periodic paralysis be differentiated from other causes of episodic weakness?","options":[{"id":"a","text":"By the presence of atrophy"},{"id":"b","text":"By the pattern of weakness and potassium levels"},{"id":"c","text":"By the age of onset"},{"id":"d","text":"By the presence of sensory symptoms"}],"answerId":"b","explanation":"Periodic paralysis is characterized by episodic weakness with specific potassium level changes, distinguishing it from other conditions.","kind":"trap","origin":"ai"},{"id":"periodic-paralysis~ai-7","moduleId":"periodic-paralysis","stem":"A patient with periodic paralysis experiences confusion and altered mental status during an episode. Which linked condition should be considered?","options":[{"id":"a","text":"Hepatic encephalopathy"},{"id":"b","text":"Uremic encephalopathy"},{"id":"c","text":"Thyrotoxic crisis"},{"id":"d","text":"Seizure disorder"}],"answerId":"a","explanation":"Altered mental status can occur in hepatic encephalopathy, which may be linked to electrolyte imbalances in periodic paralysis.","kind":"integration","linkedModuleIds":["altered-mental-status-coma"],"origin":"ai"},{"id":"periodic-paralysis~ai-8","moduleId":"periodic-paralysis","stem":"In a case of periodic paralysis, which condition could lead to a similar presentation of weakness and altered mental status?","options":[{"id":"a","text":"Hypoglycemia"},{"id":"b","text":"Thyrotoxicosis"},{"id":"c","text":"Multiple sclerosis"},{"id":"d","text":"Cerebral hemorrhage"}],"answerId":"b","explanation":"Thyrotoxicosis can cause weakness and altered mental status, similar to periodic paralysis, especially in thyrotoxic periodic paralysis.","kind":"integration","linkedModuleIds":["hepatic-uremic-encephalopathy"],"origin":"ai"}],"cns-pharmacology-foundations":[{"id":"cns-pharmacology-foundations~ai-0","moduleId":"cns-pharmacology-foundations","stem":"Which type of receptor is responsible for the rapid inhibitory response in the CNS?","options":[{"id":"a","text":"Metabotropic GPCR"},{"id":"b","text":"Ionotropic receptor"},{"id":"c","text":"Voltage-gated channel"},{"id":"d","text":"Transporter protein"}],"answerId":"b","explanation":"Ionotropic receptors, such as GABA_A, mediate fast inhibitory responses by opening Cl⁻ channels.","kind":"recall","origin":"ai"},{"id":"cns-pharmacology-foundations~ai-1","moduleId":"cns-pharmacology-foundations","stem":"Why is L-DOPA preferred over dopamine for treating Parkinson's disease?","options":[{"id":"a","text":"Dopamine is more effective than L-DOPA"},{"id":"b","text":"Dopamine can cross the blood-brain barrier"},{"id":"c","text":"L-DOPA can be converted to dopamine in the brain"},{"id":"d","text":"L-DOPA has fewer side effects than dopamine"}],"answerId":"c","explanation":"L-DOPA can cross the blood-brain barrier via an amino-acid transporter and is converted to dopamine in the brain.","kind":"trap","origin":"ai"},{"id":"cns-pharmacology-foundations~ai-2","moduleId":"cns-pharmacology-foundations","stem":"What is the primary mechanism of action for amphetamines in the CNS?","options":[{"id":"a","text":"Inhibition of reuptake"},{"id":"b","text":"Inhibition of metabolism"},{"id":"c","text":"Promotion of release"},{"id":"d","text":"Blockade of receptors"}],"answerId":"c","explanation":"Amphetamines primarily promote the release of neurotransmitters, increasing their availability in the synaptic cleft.","kind":"mechanism","origin":"ai"},{"id":"cns-pharmacology-foundations~ai-3","moduleId":"cns-pharmacology-foundations","stem":"What clinical finding would indicate a drug's poor CNS penetration?","options":[{"id":"a","text":"Rapid onset of action"},{"id":"b","text":"Increased sedation"},{"id":"c","text":"Delayed therapeutic effect"},{"id":"d","text":"Presence of side effects"}],"answerId":"c","explanation":"A delayed therapeutic effect suggests poor CNS penetration, often due to the drug's hydrophilicity and inability to cross the blood-brain barrier.","kind":"recall","origin":"ai"},{"id":"cns-pharmacology-foundations~ai-4","moduleId":"cns-pharmacology-foundations","stem":"Which neurotransmitter's action is primarily mediated by metabotropic receptors?","options":[{"id":"a","text":"GABA"},{"id":"b","text":"Glutamate"},{"id":"c","text":"Dopamine"},{"id":"d","text":"Acetylcholine"}],"answerId":"c","explanation":"Dopamine primarily acts through metabotropic GPCRs, leading to slower, modulatory effects.","kind":"recall","origin":"ai"},{"id":"cns-pharmacology-foundations~ai-5","moduleId":"cns-pharmacology-foundations","stem":"How does the blood-brain barrier affect drug design for CNS conditions?","options":[{"id":"a","text":"Encourages hydrophilic drugs"},{"id":"b","text":"Requires lipophilic drugs or transporters"},{"id":"c","text":"Allows all drugs to enter freely"},{"id":"d","text":"Only affects small molecules"}],"answerId":"b","explanation":"The blood-brain barrier restricts entry, necessitating the design of lipophilic drugs or those that can utilize transporters.","kind":"mechanism","origin":"ai"},{"id":"cns-pharmacology-foundations~ai-6","moduleId":"cns-pharmacology-foundations","stem":"How do EPSPs and IPSPs contribute to neuronal firing?","options":[{"id":"a","text":"EPSPs inhibit action potentials, while IPSPs excite them"},{"id":"b","text":"EPSPs and IPSPs both depolarize neurons"},{"id":"c","text":"EPSPs depolarize and IPSPs hyperpolarize, summing to determine firing"},{"id":"d","text":"Only EPSPs contribute to firing"}],"answerId":"c","explanation":"EPSPs cause depolarization and IPSPs cause hyperpolarization; their summation determines whether the neuron reaches the firing threshold.","kind":"integration","linkedModuleIds":["synaptic-transmission-epsp-ipsp"],"origin":"ai"},{"id":"cns-pharmacology-foundations~ai-7","moduleId":"cns-pharmacology-foundations","stem":"Which mechanism explains the effect of ketamine as an NMDA antagonist?","options":[{"id":"a","text":"Inhibition of neurotransmitter release"},{"id":"b","text":"Blockade of sodium channels"},{"id":"c","text":"Inhibition of excitatory synaptic transmission"},{"id":"d","text":"Activation of inhibitory receptors"}],"answerId":"c","explanation":"Ketamine blocks NMDA receptors, inhibiting excitatory synaptic transmission and leading to its anesthetic effects.","kind":"integration","linkedModuleIds":["cns-neurotransmitters"],"origin":"ai"}],"cns-stimulants":[{"id":"cns-stimulants~ai-0","moduleId":"cns-stimulants","stem":"What is the primary mechanism of action of amphetamines?","options":[{"id":"a","text":"Blocking dopamine reuptake"},{"id":"b","text":"Inhibiting MAO"},{"id":"c","text":"Reversing DAT/NET"},{"id":"d","text":"Activating nicotinic receptors"}],"answerId":"c","explanation":"Amphetamines primarily reverse the dopamine and norepinephrine transporters, leading to increased release of these neurotransmitters.","kind":"mechanism","origin":"ai"},{"id":"cns-stimulants~ai-1","moduleId":"cns-stimulants","stem":"Which of the following is a common clinical finding in cocaine toxicity?","options":[{"id":"a","text":"Bradycardia"},{"id":"b","text":"Miosis"},{"id":"c","text":"Nasal septal perforation"},{"id":"d","text":"Hypotension"}],"answerId":"c","explanation":"Cocaine use, especially via nasal administration, can lead to nasal septal perforation due to its vasoconstrictive properties.","kind":"recall","origin":"ai"},{"id":"cns-stimulants~ai-2","moduleId":"cns-stimulants","stem":"What is the drug of choice for ADHD?","options":[{"id":"a","text":"Cocaine"},{"id":"b","text":"Modafinil"},{"id":"c","text":"Methylphenidate"},{"id":"d","text":"Amphetamine"}],"answerId":"c","explanation":"Methylphenidate is considered the first-line treatment for ADHD due to its efficacy and safety profile.","kind":"recall","origin":"ai"},{"id":"cns-stimulants~ai-3","moduleId":"cns-stimulants","stem":"Which of the following symptoms is most characteristic of chronic amphetamine use?","options":[{"id":"a","text":"Euphoria"},{"id":"b","text":"Formication"},{"id":"c","text":"Bradycardia"},{"id":"d","text":"Hypothermia"}],"answerId":"b","explanation":"Chronic use of amphetamines can lead to formication, a sensation of insects crawling on or under the skin.","kind":"recall","origin":"ai"},{"id":"cns-stimulants~ai-4","moduleId":"cns-stimulants","stem":"What distinguishes the mechanism of action of cocaine from that of amphetamines?","options":[{"id":"a","text":"Cocaine increases dopamine release"},{"id":"b","text":"Cocaine blocks reuptake of dopamine"},{"id":"c","text":"Cocaine activates nicotinic receptors"},{"id":"d","text":"Cocaine inhibits MAO"}],"answerId":"b","explanation":"Cocaine primarily blocks the reuptake of dopamine, while amphetamines actively promote the release of dopamine.","kind":"trap","origin":"ai"},{"id":"cns-stimulants~ai-5","moduleId":"cns-stimulants","stem":"How does nicotine primarily exert its effects on the CNS?","options":[{"id":"a","text":"By blocking adenosine receptors"},{"id":"b","text":"By activating nicotinic ACh receptors"},{"id":"c","text":"By inhibiting MAO"},{"id":"d","text":"By reversing DAT"}],"answerId":"b","explanation":"Nicotine activates nicotinic acetylcholine receptors, leading to increased dopamine release in the brain.","kind":"mechanism","origin":"ai"},{"id":"cns-stimulants~ai-6","moduleId":"cns-stimulants","stem":"Which neurotransmitter system is primarily affected by both amphetamines and cocaine?","options":[{"id":"a","text":"Serotonin"},{"id":"b","text":"GABA"},{"id":"c","text":"Dopamine"},{"id":"d","text":"Norepinephrine"}],"answerId":"c","explanation":"Both amphetamines and cocaine primarily affect the dopamine system, leading to increased dopamine levels in the synaptic cleft.","kind":"integration","linkedModuleIds":["cns-neurotransmitters"],"origin":"ai"},{"id":"cns-stimulants~ai-7","moduleId":"cns-stimulants","stem":"Which of the following CNS stimulants is most likely to cause nasal septal perforation when used intranasally?","options":[{"id":"a","text":"Methylphenidate"},{"id":"b","text":"Caffeine"},{"id":"c","text":"Cocaine"},{"id":"d","text":"Nicotine"}],"answerId":"c","explanation":"Cocaine's vasoconstrictive effects can lead to nasal septal perforation when snorted.","kind":"integration","linkedModuleIds":["cns-pharmacology-foundations"],"origin":"ai"}],"hepatic-uremic-encephalopathy":[{"id":"hepatic-uremic-encephalopathy~ai-0","moduleId":"hepatic-uremic-encephalopathy","stem":"What is the most characteristic clinical finding in hepatic encephalopathy?","options":[{"id":"a","text":"Asterixis"},{"id":"b","text":"Seizures"},{"id":"c","text":"Confusion"},{"id":"d","text":"Myoclonus"}],"answerId":"a","explanation":"Asterixis, or flapping tremor, is a hallmark sign of hepatic encephalopathy due to liver failure.","kind":"recall","origin":"ai"},{"id":"hepatic-uremic-encephalopathy~ai-1","moduleId":"hepatic-uremic-encephalopathy","stem":"Which of the following is a common precipitant of hepatic encephalopathy?","options":[{"id":"a","text":"Hypokalemia"},{"id":"b","text":"Hyperkalemia"},{"id":"c","text":"Hyponatremia"},{"id":"d","text":"Hypernatremia"}],"answerId":"a","explanation":"Hypokalemia is a known precipitant of hepatic encephalopathy, often exacerbating the condition.","kind":"recall","origin":"ai"},{"id":"hepatic-uremic-encephalopathy~ai-2","moduleId":"hepatic-uremic-encephalopathy","stem":"What is the primary mechanism leading to uremic encephalopathy?","options":[{"id":"a","text":"Accumulation of ammonia"},{"id":"b","text":"Accumulation of urea and other toxins"},{"id":"c","text":"Decreased cerebral blood flow"},{"id":"d","text":"Electrolyte imbalances"}],"answerId":"b","explanation":"Uremic encephalopathy is primarily caused by the accumulation of urea and other toxins due to renal failure.","kind":"mechanism","origin":"ai"},{"id":"hepatic-uremic-encephalopathy~ai-3","moduleId":"hepatic-uremic-encephalopathy","stem":"What EEG finding is commonly associated with hepatic encephalopathy?","options":[{"id":"a","text":"Biphasic waves"},{"id":"b","text":"Triphasic waves"},{"id":"c","text":"Theta waves"},{"id":"d","text":"Delta waves"}],"answerId":"b","explanation":"EEG in hepatic encephalopathy typically shows triphasic waves, indicative of metabolic encephalopathy.","kind":"recall","origin":"ai"},{"id":"hepatic-uremic-encephalopathy~ai-4","moduleId":"hepatic-uremic-encephalopathy","stem":"In managing hepatic encephalopathy, what is the most important step besides lowering ammonia levels?","options":[{"id":"a","text":"Restricting protein intake"},{"id":"b","text":"Searching for and treating precipitating factors"},{"id":"c","text":"Administering sedatives"},{"id":"d","text":"Increasing dietary protein"}],"answerId":"b","explanation":"It is crucial to identify and treat precipitating factors in addition to managing ammonia levels in hepatic encephalopathy.","kind":"trap","origin":"ai"},{"id":"hepatic-uremic-encephalopathy~ai-5","moduleId":"hepatic-uremic-encephalopathy","stem":"What is the primary treatment for uremic encephalopathy?","options":[{"id":"a","text":"Lactulose"},{"id":"b","text":"Dialysis"},{"id":"c","text":"Rifaximin"},{"id":"d","text":"Protein restriction"}],"answerId":"b","explanation":"Dialysis is the primary treatment for uremic encephalopathy, as it removes accumulated toxins.","kind":"recall","origin":"ai"},{"id":"hepatic-uremic-encephalopathy~ai-6","moduleId":"hepatic-uremic-encephalopathy","stem":"How does hepatic encephalopathy relate to alcohol metabolism disorders?","options":[{"id":"a","text":"It is caused by alcohol-induced liver failure."},{"id":"b","text":"It is unrelated to alcohol metabolism."},{"id":"c","text":"It is a direct result of ALDH2 deficiency."},{"id":"d","text":"It is a complication of acute alcohol intoxication."}],"answerId":"a","explanation":"Hepatic encephalopathy can occur due to liver failure from chronic alcohol abuse, linking it to alcohol metabolism disorders.","kind":"integration","linkedModuleIds":["alcohol-aldh2-cirrhosis"],"origin":"ai"},{"id":"hepatic-uremic-encephalopathy~ai-7","moduleId":"hepatic-uremic-encephalopathy","stem":"Which condition shares similar clinical features with hepatic encephalopathy, particularly in altered mental status?","options":[{"id":"a","text":"Wernicke's encephalopathy"},{"id":"b","text":"Uremic encephalopathy"},{"id":"c","text":"Korsakoff syndrome"},{"id":"d","text":"Hypoglycemic coma"}],"answerId":"b","explanation":"Uremic encephalopathy presents with altered mental status and can be confused with hepatic encephalopathy due to similar symptoms.","kind":"integration","linkedModuleIds":["altered-mental-status-coma"],"origin":"ai"}],"disorders-of-consciousness":[{"id":"disorders-of-consciousness~ai-0","moduleId":"disorders-of-consciousness","stem":"What is the primary anatomical structure responsible for maintaining arousal?","options":[{"id":"a","text":"Cerebral cortex"},{"id":"b","text":"Thalamus"},{"id":"c","text":"Ascending reticular activating system (ARAS)"},{"id":"d","text":"Basal ganglia"}],"answerId":"c","explanation":"The ascending reticular activating system (ARAS) is crucial for maintaining arousal and wakefulness.","kind":"recall","origin":"ai"},{"id":"disorders-of-consciousness~ai-1","moduleId":"disorders-of-consciousness","stem":"A patient presents with a fixed dilated pupil and decreased consciousness. What is the most likely cause?","options":[{"id":"a","text":"Meningitis"},{"id":"b","text":"Uncal herniation"},{"id":"c","text":"Toxic-metabolic encephalopathy"},{"id":"d","text":"Subarachnoid hemorrhage"}],"answerId":"b","explanation":"A fixed dilated pupil indicates midbrain dysfunction, often due to uncal herniation.","kind":"clinical","origin":"ai"},{"id":"disorders-of-consciousness~ai-2","moduleId":"disorders-of-consciousness","stem":"Which combination of findings suggests a toxic-metabolic cause of altered consciousness?","options":[{"id":"a","text":"Focal neurological signs and neck stiffness"},{"id":"b","text":"Symmetric exam with no focal signs"},{"id":"c","text":"Fixed dilated pupils and decerebrate posturing"},{"id":"d","text":"Altered consciousness with fever and neck stiffness"}],"answerId":"b","explanation":"A symmetric exam with no focal signs typically indicates a toxic-metabolic encephalopathy.","kind":"trap","origin":"ai"},{"id":"disorders-of-consciousness~ai-3","moduleId":"disorders-of-consciousness","stem":"What is the mechanism by which a unilateral hemisphere lesion can lead to coma?","options":[{"id":"a","text":"Direct damage to the cortex"},{"id":"b","text":"Compression of the brainstem"},{"id":"c","text":"Disruption of the ARAS"},{"id":"d","text":"Bilateral cortical involvement"}],"answerId":"b","explanation":"A unilateral hemisphere lesion can cause coma only if it leads to mass effect that compresses the brainstem.","kind":"mechanism","origin":"ai"},{"id":"disorders-of-consciousness~ai-4","moduleId":"disorders-of-consciousness","stem":"In a patient with altered consciousness and neck stiffness, which condition is most likely?","options":[{"id":"a","text":"Stroke"},{"id":"b","text":"Toxic-metabolic encephalopathy"},{"id":"c","text":"Subarachnoid hemorrhage"},{"id":"d","text":"Meningitis"}],"answerId":"d","explanation":"Neck stiffness with altered consciousness suggests meningitis or subarachnoid hemorrhage.","kind":"clinical","origin":"ai"},{"id":"disorders-of-consciousness~ai-5","moduleId":"disorders-of-consciousness","stem":"How does the reticular activating system relate to consciousness?","options":[{"id":"a","text":"It regulates blood flow to the brain."},{"id":"b","text":"It modulates sensory input to the cortex."},{"id":"c","text":"It is essential for arousal and wakefulness."},{"id":"d","text":"It processes emotional responses."}],"answerId":"c","explanation":"The reticular activating system is essential for arousal and wakefulness, forming a key component of consciousness.","kind":"integration","linkedModuleIds":["reticular-activating-system-consciousness"],"origin":"ai"},{"id":"disorders-of-consciousness~ai-6","moduleId":"disorders-of-consciousness","stem":"Which of the following findings would most likely indicate a metabolic cause of altered consciousness?","options":[{"id":"a","text":"Focal neurological deficits"},{"id":"b","text":"Fixed pupils"},{"id":"c","text":"Symmetric motor response"},{"id":"d","text":"Neck stiffness"}],"answerId":"c","explanation":"A symmetric motor response without focal deficits often indicates a metabolic cause of altered consciousness.","kind":"integration","linkedModuleIds":["altered-mental-status-coma"],"origin":"ai"}],"dopamine-agonists-antimuscarinics":[{"id":"dopamine-agonists-antimuscarinics~ai-0","moduleId":"dopamine-agonists-antimuscarinics","stem":"Which of the following dopamine agonists is known for causing 'sleep attacks'?","options":[{"id":"a","text":"Pramipexole"},{"id":"b","text":"Bromocriptine"},{"id":"c","text":"Amantadine"},{"id":"d","text":"Benztropine"}],"answerId":"a","explanation":"Pramipexole, a non-ergot dopamine agonist, is associated with the side effect of sudden sleep attacks.","kind":"recall","origin":"ai"},{"id":"dopamine-agonists-antimuscarinics~ai-1","moduleId":"dopamine-agonists-antimuscarinics","stem":"What is the primary mechanism of action of amantadine in treating Parkinson's disease?","options":[{"id":"a","text":"Dopamine receptor agonism"},{"id":"b","text":"Dopamine reuptake inhibition"},{"id":"c","text":"NMDA receptor antagonism"},{"id":"d","text":"Anticholinergic activity"}],"answerId":"c","explanation":"Amantadine acts as an NMDA receptor antagonist and also mildly boosts dopamine release.","kind":"mechanism","origin":"ai"},{"id":"dopamine-agonists-antimuscarinics~ai-2","moduleId":"dopamine-agonists-antimuscarinics","stem":"A patient develops parkinsonism after starting an antipsychotic. What is the best treatment?","options":[{"id":"a","text":"Increase antipsychotic dose"},{"id":"b","text":"Add levodopa"},{"id":"c","text":"Use benztropine"},{"id":"d","text":"Switch to a different antipsychotic"}],"answerId":"c","explanation":"Drug-induced parkinsonism from antipsychotics should be treated with a central antimuscarinic like benztropine, not levodopa.","kind":"trap","origin":"ai"},{"id":"dopamine-agonists-antimuscarinics~ai-3","moduleId":"dopamine-agonists-antimuscarinics","stem":"Which finding is characteristic of amantadine use?","options":[{"id":"a","text":"Livedo reticularis"},{"id":"b","text":"Tardive dyskinesia"},{"id":"c","text":"Bradykinesia"},{"id":"d","text":"Dystonia"}],"answerId":"a","explanation":"Livedo reticularis is a notable side effect associated with amantadine treatment.","kind":"recall","origin":"ai"},{"id":"dopamine-agonists-antimuscarinics~ai-4","moduleId":"dopamine-agonists-antimuscarinics","stem":"What is the mechanism of action of central antimuscarinics in treating drug-induced parkinsonism?","options":[{"id":"a","text":"Increase dopamine release"},{"id":"b","text":"Block D2 receptors"},{"id":"c","text":"Rebalance ACh and dopamine"},{"id":"d","text":"Inhibit NMDA receptors"}],"answerId":"c","explanation":"Central antimuscarinics help rebalance the ACh-dopamine ratio, alleviating symptoms of drug-induced parkinsonism.","kind":"mechanism","origin":"ai"},{"id":"dopamine-agonists-antimuscarinics~ai-5","moduleId":"dopamine-agonists-antimuscarinics","stem":"How does the mechanism of action of dopamine agonists differ from that of levodopa?","options":[{"id":"a","text":"Dopamine agonists directly stimulate receptors, while levodopa is converted to dopamine"},{"id":"b","text":"Dopamine agonists inhibit dopamine reuptake, while levodopa does not"},{"id":"c","text":"Dopamine agonists have no side effects, while levodopa does"},{"id":"d","text":"Dopamine agonists are less effective than levodopa"}],"answerId":"a","explanation":"Dopamine agonists directly stimulate dopamine receptors, whereas levodopa must be converted into dopamine in the brain.","kind":"integration","linkedModuleIds":["levodopa-and-adjuncts"],"origin":"ai"},{"id":"dopamine-agonists-antimuscarinics~ai-6","moduleId":"dopamine-agonists-antimuscarinics","stem":"Which drug class is primarily used to treat tremors in drug-induced parkinsonism?","options":[{"id":"a","text":"Dopamine agonists"},{"id":"b","text":"Levodopa"},{"id":"c","text":"Antimuscarinics"},{"id":"d","text":"MAO-B inhibitors"}],"answerId":"c","explanation":"Antimuscarinics are the drug of choice for treating tremors associated with drug-induced parkinsonism.","kind":"integration","linkedModuleIds":["antimuscarinic-anticholinergic-drugs"],"origin":"ai"}],"alzheimer-and-dementias":[{"id":"alzheimer-and-dementias~ai-0","moduleId":"alzheimer-and-dementias","stem":"What is the most common pathological finding in Alzheimer disease?","options":[{"id":"a","text":"Intracellular tau neurofibrillary tangles"},{"id":"b","text":"Extracellular amyloid-β plaques"},{"id":"c","text":"Vascular lesions"},{"id":"d","text":"Lewy bodies"}],"answerId":"b","explanation":"Alzheimer disease is characterized by the presence of extracellular amyloid-β plaques and intracellular tau neurofibrillary tangles.","kind":"recall","origin":"ai"},{"id":"alzheimer-and-dementias~ai-1","moduleId":"alzheimer-and-dementias","stem":"Which of the following is a key early symptom of Alzheimer disease?","options":[{"id":"a","text":"Visual hallucinations"},{"id":"b","text":"Episodic memory loss"},{"id":"c","text":"Aphasia"},{"id":"d","text":"Apraxia"}],"answerId":"b","explanation":"Early episodic memory loss is a hallmark symptom of Alzheimer disease due to hippocampal involvement.","kind":"recall","origin":"ai"},{"id":"alzheimer-and-dementias~ai-2","moduleId":"alzheimer-and-dementias","stem":"How does amyloid-β contribute to neuronal loss in Alzheimer disease?","options":[{"id":"a","text":"By promoting neuroinflammation"},{"id":"b","text":"By causing oxidative stress"},{"id":"c","text":"By disrupting synaptic function"},{"id":"d","text":"By forming neurofibrillary tangles"}],"answerId":"a","explanation":"Amyloid-β accumulation leads to neuroinflammation, which contributes to neuronal loss in Alzheimer disease.","kind":"mechanism","origin":"ai"},{"id":"alzheimer-and-dementias~ai-3","moduleId":"alzheimer-and-dementias","stem":"Which imaging finding is most characteristic of Alzheimer disease?","options":[{"id":"a","text":"Frontal lobe atrophy"},{"id":"b","text":"Hippocampal atrophy"},{"id":"c","text":"Cerebellar atrophy"},{"id":"d","text":"Basal ganglia atrophy"}],"answerId":"b","explanation":"Hippocampal atrophy is a characteristic finding in Alzheimer disease, reflecting the disease's impact on memory.","kind":"recall","origin":"ai"},{"id":"alzheimer-and-dementias~ai-4","moduleId":"alzheimer-and-dementias","stem":"Which statement about APOE4 and Alzheimer disease is true?","options":[{"id":"a","text":"APOE4 guarantees Alzheimer disease development"},{"id":"b","text":"APOE4 is a risk factor, not deterministic"},{"id":"c","text":"APOE4 is only relevant in early-onset cases"},{"id":"d","text":"APOE4 is protective against Alzheimer disease"}],"answerId":"b","explanation":"APOE4 is a risk factor for late-onset Alzheimer disease but does not guarantee its development.","kind":"trap","origin":"ai"},{"id":"alzheimer-and-dementias~ai-5","moduleId":"alzheimer-and-dementias","stem":"Which cognitive domain is primarily affected in the early stages of Alzheimer disease?","options":[{"id":"a","text":"Visuospatial skills"},{"id":"b","text":"Language"},{"id":"c","text":"Episodic memory"},{"id":"d","text":"Executive function"}],"answerId":"c","explanation":"Episodic memory is the first cognitive domain affected in Alzheimer disease due to hippocampal damage.","kind":"recall","origin":"ai"},{"id":"alzheimer-and-dementias~ai-6","moduleId":"alzheimer-and-dementias","stem":"How does Alzheimer disease differ from vascular dementia in terms of clinical presentation?","options":[{"id":"a","text":"Stepwise decline in function"},{"id":"b","text":"Gradual progressive decline"},{"id":"c","text":"Presence of visual hallucinations"},{"id":"d","text":"Rapid onset of symptoms"}],"answerId":"b","explanation":"Alzheimer disease typically presents with a gradual progressive decline, whereas vascular dementia may show a stepwise decline due to cerebrovascular events.","kind":"integration","linkedModuleIds":["cognitive-domains-dementia-workup"],"origin":"ai"},{"id":"alzheimer-and-dementias~ai-7","moduleId":"alzheimer-and-dementias","stem":"Which of the following mechanisms is common to both Alzheimer disease and protein misfolding disorders?","options":[{"id":"a","text":"Neuroinflammation"},{"id":"b","text":"Vascular damage"},{"id":"c","text":"Neurotransmitter depletion"},{"id":"d","text":"Mitochondrial dysfunction"}],"answerId":"a","explanation":"Neuroinflammation is a common mechanism in both Alzheimer disease and other protein misfolding disorders.","kind":"integration","linkedModuleIds":["protein-misfolding-amyloid"],"origin":"ai"}],"meningioma-schwannoma-pituitary":[{"id":"meningioma-schwannoma-pituitary~ai-0","moduleId":"meningioma-schwannoma-pituitary","stem":"What is the most common primary brain tumor overall?","options":[{"id":"a","text":"Schwannoma"},{"id":"b","text":"Pituitary adenoma"},{"id":"c","text":"Meningioma"},{"id":"d","text":"Astrocytoma"}],"answerId":"c","explanation":"Meningioma is the most common primary brain tumor, arising from arachnoid cap cells.","kind":"recall","origin":"ai"},{"id":"meningioma-schwannoma-pituitary~ai-1","moduleId":"meningioma-schwannoma-pituitary","stem":"Which histological feature is characteristic of meningiomas?","options":[{"id":"a","text":"Palisading cells"},{"id":"b","text":"Whorls and psammoma bodies"},{"id":"c","text":"Myxoid stroma"},{"id":"d","text":"Necrosis"}],"answerId":"b","explanation":"Meningiomas are characterized by whorls and psammoma bodies on histology.","kind":"recall","origin":"ai"},{"id":"meningioma-schwannoma-pituitary~ai-2","moduleId":"meningioma-schwannoma-pituitary","stem":"What clinical finding is associated with vestibular schwannoma?","options":[{"id":"a","text":"Bitemporal hemianopia"},{"id":"b","text":"Unilateral sensorineural hearing loss"},{"id":"c","text":"Visual field defect"},{"id":"d","text":"Cushing's syndrome"}],"answerId":"b","explanation":"Vestibular schwannoma typically causes unilateral sensorineural hearing loss and tinnitus.","kind":"clinical","origin":"ai"},{"id":"meningioma-schwannoma-pituitary~ai-3","moduleId":"meningioma-schwannoma-pituitary","stem":"How do extra-axial tumors like meningiomas primarily cause harm?","options":[{"id":"a","text":"By invading brain tissue"},{"id":"b","text":"By compressing adjacent structures"},{"id":"c","text":"By causing inflammation"},{"id":"d","text":"By obstructing cerebrospinal fluid flow"}],"answerId":"b","explanation":"Extra-axial tumors like meningiomas primarily cause harm by compressing adjacent structures.","kind":"mechanism","origin":"ai"},{"id":"meningioma-schwannoma-pituitary~ai-4","moduleId":"meningioma-schwannoma-pituitary","stem":"Bilateral vestibular schwannomas are diagnostic of which condition?","options":[{"id":"a","text":"Sporadic schwannomas"},{"id":"b","text":"Neurofibromatosis type 1"},{"id":"c","text":"Neurofibromatosis type 2"},{"id":"d","text":"Li-Fraumeni syndrome"}],"answerId":"c","explanation":"Bilateral vestibular schwannomas are essentially diagnostic of neurofibromatosis type 2 (NF2).","kind":"trap","origin":"ai"},{"id":"meningioma-schwannoma-pituitary~ai-5","moduleId":"meningioma-schwannoma-pituitary","stem":"A 45-year-old woman presents with bitemporal hemianopia. What is the most likely diagnosis?","options":[{"id":"a","text":"Meningioma"},{"id":"b","text":"Vestibular schwannoma"},{"id":"c","text":"Pituitary adenoma"},{"id":"d","text":"Astrocytoma"}],"answerId":"c","explanation":"Bitemporal hemianopia is commonly caused by a pituitary adenoma compressing the optic chiasm.","kind":"clinical","origin":"ai"},{"id":"meningioma-schwannoma-pituitary~ai-6","moduleId":"meningioma-schwannoma-pituitary","stem":"How might a pituitary adenoma affect the hypothalamic-pituitary axis?","options":[{"id":"a","text":"Increase in cortisol production"},{"id":"b","text":"Decrease in growth hormone secretion"},{"id":"c","text":"Increase in prolactin secretion"},{"id":"d","text":"Decrease in thyroid hormone production"}],"answerId":"c","explanation":"Functioning pituitary adenomas can lead to increased prolactin secretion, causing hyperprolactinemia.","kind":"integration","linkedModuleIds":["pituitary-adenomas-hyperpituitarism"],"origin":"ai"},{"id":"meningioma-schwannoma-pituitary~ai-7","moduleId":"meningioma-schwannoma-pituitary","stem":"Which embryological structure is primarily affected in the development of schwannomas?","options":[{"id":"a","text":"Neural crest cells"},{"id":"b","text":"Somites"},{"id":"c","text":"Ectoderm"},{"id":"d","text":"Mesoderm"}],"answerId":"a","explanation":"Schwannomas arise from Schwann cells, which originate from neural crest cells during embryogenesis.","kind":"integration","linkedModuleIds":["msk-embryo-somites"],"origin":"ai"}],"cognitive-domains-dementia-workup":[{"id":"cognitive-domains-dementia-workup~ai-0","moduleId":"cognitive-domains-dementia-workup","stem":"Which cognitive domain is primarily affected in Alzheimer's disease during early stages?","options":[{"id":"a","text":"Language"},{"id":"b","text":"Episodic memory"},{"id":"c","text":"Visuospatial skills"},{"id":"d","text":"Executive function"}],"answerId":"b","explanation":"Episodic memory, associated with the medial temporal lobe, is typically the first cognitive domain affected in Alzheimer's disease.","kind":"recall","origin":"ai"},{"id":"cognitive-domains-dementia-workup~ai-1","moduleId":"cognitive-domains-dementia-workup","stem":"What is the primary mechanism for diagnosing dementia?","options":[{"id":"a","text":"Neuroimaging"},{"id":"b","text":"Cognitive testing"},{"id":"c","text":"Genetic testing"},{"id":"d","text":"Blood tests"}],"answerId":"b","explanation":"Cognitive testing is essential for diagnosing dementia, assessing various cognitive domains and functional impairment.","kind":"mechanism","origin":"ai"},{"id":"cognitive-domains-dementia-workup~ai-2","moduleId":"cognitive-domains-dementia-workup","stem":"A patient presents with acute confusion and fluctuating attention. What is the most likely diagnosis?","options":[{"id":"a","text":"Dementia"},{"id":"b","text":"Delirium"},{"id":"c","text":"Mild cognitive impairment"},{"id":"d","text":"Normal aging"}],"answerId":"b","explanation":"The acute and fluctuating nature of the symptoms is characteristic of delirium, not dementia.","kind":"clinical","origin":"ai"},{"id":"cognitive-domains-dementia-workup~ai-3","moduleId":"cognitive-domains-dementia-workup","stem":"Which of the following conditions must be excluded before diagnosing dementia?","options":[{"id":"a","text":"Mild cognitive impairment"},{"id":"b","text":"Delirium"},{"id":"c","text":"Normal aging"},{"id":"d","text":"Age-related memory decline"}],"answerId":"b","explanation":"Delirium must be excluded as it can mimic dementia but has a different underlying cause and treatment.","kind":"trap","origin":"ai"},{"id":"cognitive-domains-dementia-workup~ai-4","moduleId":"cognitive-domains-dementia-workup","stem":"In the context of dementia workup, what does the acronym 'VITAMINS' represent?","options":[{"id":"a","text":"Vascular, Infection, Toxic-metabolic, Autoimmune, Malignancy, Iatrogenic, Neurodegenerative, Systemic"},{"id":"b","text":"Vascular, Inflammatory, Tumor, Autoimmune, Metabolic, Infections, Neurological, Surgical"},{"id":"c","text":"Vascular, Infection, Trauma, Autoimmune, Malignancy, Iatrogenic, Nutritional, Systemic"},{"id":"d","text":"Vascular, Infection, Toxic, Autoimmune, Malignancy, Iatrogenic, Neurodegenerative, Stress"}],"answerId":"a","explanation":"'VITAMINS' is a mnemonic for conditions that can cause rapidly progressive dementia, highlighting the need for urgent workup.","kind":"recall","origin":"ai"},{"id":"cognitive-domains-dementia-workup~ai-5","moduleId":"cognitive-domains-dementia-workup","stem":"A patient with mild cognitive impairment is still able to manage their daily activities. What does this indicate?","options":[{"id":"a","text":"They have dementia"},{"id":"b","text":"They have normal aging"},{"id":"c","text":"They have preserved functional independence"},{"id":"d","text":"They are experiencing delirium"}],"answerId":"c","explanation":"Preserved activities of daily living indicate that the patient has mild cognitive impairment, not dementia.","kind":"trap","origin":"ai"},{"id":"cognitive-domains-dementia-workup~ai-6","moduleId":"cognitive-domains-dementia-workup","stem":"How does the cognitive decline in Alzheimer's disease relate to the findings in the 'Alzheimer Disease & Dementia Subtypes' module?","options":[{"id":"a","text":"Both modules discuss reversible causes of dementia"},{"id":"b","text":"Both modules emphasize the role of the hippocampus in memory"},{"id":"c","text":"Both modules focus on acute confusion as a symptom"},{"id":"d","text":"Both modules highlight the importance of genetic testing"}],"answerId":"b","explanation":"The hippocampus is crucial for episodic memory, which is impaired in Alzheimer's disease, linking both modules.","kind":"integration","linkedModuleIds":["alzheimer-and-dementias"],"origin":"ai"},{"id":"cognitive-domains-dementia-workup~ai-7","moduleId":"cognitive-domains-dementia-workup","stem":"Which of the following is a common finding in both dementia workup and disorders of consciousness?","options":[{"id":"a","text":"Fluctuating attention"},{"id":"b","text":"Impaired episodic memory"},{"id":"c","text":"Altered consciousness"},{"id":"d","text":"Preserved ADLs"}],"answerId":"c","explanation":"Altered consciousness is a key feature in disorders of consciousness, while dementia primarily involves cognitive decline without altered consciousness.","kind":"integration","linkedModuleIds":["disorders-of-consciousness"],"origin":"ai"}],"cns-lymphoma-metastases":[{"id":"cns-lymphoma-metastases~ai-0","moduleId":"cns-lymphoma-metastases","stem":"What is the most common type of primary CNS lymphoma in immunosuppressed patients?","options":[{"id":"a","text":"Follicular lymphoma"},{"id":"b","text":"Diffuse large B-cell lymphoma"},{"id":"c","text":"Burkitt lymphoma"},{"id":"d","text":"Mantle cell lymphoma"}],"answerId":"b","explanation":"Primary CNS lymphoma in immunosuppressed patients is typically diffuse large B-cell lymphoma (DLBCL), often associated with EBV.","kind":"recall","origin":"ai"},{"id":"cns-lymphoma-metastases~ai-1","moduleId":"cns-lymphoma-metastases","stem":"Which imaging finding is most characteristic of CNS metastases?","options":[{"id":"a","text":"Solid mass in the brainstem"},{"id":"b","text":"Multiple ring-enhancing lesions at the gray-white junction"},{"id":"c","text":"Single enhancing lesion in the cerebellum"},{"id":"d","text":"Homogeneous mass in the frontal lobe"}],"answerId":"b","explanation":"CNS metastases typically present as multiple ring-enhancing lesions at the gray-white matter junction due to hematogenous spread.","kind":"recall","origin":"ai"},{"id":"cns-lymphoma-metastases~ai-2","moduleId":"cns-lymphoma-metastases","stem":"What is the primary mechanism by which CNS lymphoma spreads?","options":[{"id":"a","text":"Direct extension from adjacent structures"},{"id":"b","text":"Hematogenous spread"},{"id":"c","text":"Lymphatic spread"},{"id":"d","text":"Seeding from the cerebrospinal fluid"}],"answerId":"b","explanation":"CNS lymphoma spreads hematogenously, often leading to multifocal lesions in the brain.","kind":"mechanism","origin":"ai"},{"id":"cns-lymphoma-metastases~ai-3","moduleId":"cns-lymphoma-metastases","stem":"In a patient with suspected CNS lymphoma, what is the most appropriate management before biopsy?","options":[{"id":"a","text":"Administer corticosteroids immediately"},{"id":"b","text":"Perform a lumbar puncture"},{"id":"c","text":"Obtain imaging studies"},{"id":"d","text":"Avoid corticosteroids until after biopsy"}],"answerId":"d","explanation":"Corticosteroids should be avoided before biopsy in suspected CNS lymphoma, as they can shrink the tumor and obscure the diagnosis.","kind":"trap","origin":"ai"},{"id":"cns-lymphoma-metastases~ai-4","moduleId":"cns-lymphoma-metastases","stem":"Which of the following primary cancers is least likely to cause CNS metastases?","options":[{"id":"a","text":"Lung cancer"},{"id":"b","text":"Breast cancer"},{"id":"c","text":"Choriocarcinoma"},{"id":"d","text":"Prostate cancer"}],"answerId":"c","explanation":"Choriocarcinoma is rare but high-risk for CNS metastases; however, it is less common than lung or breast cancer.","kind":"recall","origin":"ai"},{"id":"cns-lymphoma-metastases~ai-5","moduleId":"cns-lymphoma-metastases","stem":"How does the presence of cranial neuropathies relate to CNS lymphoma and metastases?","options":[{"id":"a","text":"Indicates a benign process"},{"id":"b","text":"Suggests meningeal carcinomatosis"},{"id":"c","text":"Confirms primary CNS lymphoma"},{"id":"d","text":"Is unrelated to CNS tumors"}],"answerId":"b","explanation":"Cranial neuropathies can indicate meningeal carcinomatosis, which may occur with both CNS lymphoma and metastases.","kind":"integration","linkedModuleIds":["cancer-spread-staging-clinical"],"origin":"ai"},{"id":"cns-lymphoma-metastases~ai-6","moduleId":"cns-lymphoma-metastases","stem":"What histological feature is most indicative of primary CNS lymphoma?","options":[{"id":"a","text":"High mitotic index"},{"id":"b","text":"Presence of necrosis"},{"id":"c","text":"Perivascular clustering of malignant B-cells"},{"id":"d","text":"Calcifications within the tumor"}],"answerId":"c","explanation":"Primary CNS lymphoma is characterized by the clustering of malignant B-cells around blood vessels (perivascular), a hallmark finding.","kind":"mechanism","origin":"ai"},{"id":"cns-lymphoma-metastases~ai-7","moduleId":"cns-lymphoma-metastases","stem":"Which of the following is a common clinical presentation of CNS metastases?","options":[{"id":"a","text":"Severe headache without neurological deficits"},{"id":"b","text":"Focal neurological deficits and seizures"},{"id":"c","text":"Progressive memory loss without focal signs"},{"id":"d","text":"Visual disturbances without other symptoms"}],"answerId":"b","explanation":"CNS metastases often present with focal neurological deficits and seizures due to mass effect or increased intracranial pressure.","kind":"clinical","origin":"ai"}],"vertigo-vestibular-drugs":[{"id":"vertigo-vestibular-drugs~ai-0","moduleId":"vertigo-vestibular-drugs","stem":"Which class of drugs is primarily used for acute motion sickness?","options":[{"id":"a","text":"Antihistamines"},{"id":"b","text":"Benzodiazepines"},{"id":"c","text":"Anticholinergics"},{"id":"d","text":"Cinnarizine"}],"answerId":"c","explanation":"Anticholinergics, such as scopolamine, are effective for motion sickness, especially when used preventively.","kind":"recall","origin":"ai"},{"id":"vertigo-vestibular-drugs~ai-1","moduleId":"vertigo-vestibular-drugs","stem":"What is the main mechanism of action of betahistine in treating Ménière disease?","options":[{"id":"a","text":"H1 agonism"},{"id":"b","text":"H3 antagonism"},{"id":"c","text":"Inhibition of vestibular nuclei"},{"id":"d","text":"Increased inner-ear blood flow"}],"answerId":"d","explanation":"Betahistine acts as a histamine analog, promoting inner-ear blood flow and inhibiting vestibular nuclei activity.","kind":"mechanism","origin":"ai"},{"id":"vertigo-vestibular-drugs~ai-2","moduleId":"vertigo-vestibular-drugs","stem":"A patient presents with acute spinning vertigo and nausea. Which medication class should be used for immediate relief?","options":[{"id":"a","text":"Benzodiazepines"},{"id":"b","text":"Antihistamines"},{"id":"c","text":"Anticholinergics"},{"id":"d","text":"Ototopical drugs"}],"answerId":"b","explanation":"Antihistamines are effective for acute vestibular symptoms like spinning vertigo and nausea.","kind":"clinical","origin":"ai"},{"id":"vertigo-vestibular-drugs~ai-3","moduleId":"vertigo-vestibular-drugs","stem":"Which of the following is a potential side effect of long-term use of vestibular suppressants?","options":[{"id":"a","text":"Improved vestibular compensation"},{"id":"b","text":"Increased inner-ear blood flow"},{"id":"c","text":"Sedation"},{"id":"d","text":"Decreased tinnitus"}],"answerId":"c","explanation":"Long-term use of vestibular suppressants can lead to sedation and impair vestibular compensation.","kind":"trap","origin":"ai"},{"id":"vertigo-vestibular-drugs~ai-4","moduleId":"vertigo-vestibular-drugs","stem":"A patient with recurrent vertigo, fluctuating sensorineural hearing loss, and tinnitus is diagnosed with Ménière disease. Which drug is the mainstay of treatment?","options":[{"id":"a","text":"Promethazine"},{"id":"b","text":"Betahistine"},{"id":"c","text":"Meclizine"},{"id":"d","text":"Cinnarizine"}],"answerId":"b","explanation":"Betahistine is the mainstay treatment for Ménière disease due to its effects on inner-ear blood flow.","kind":"recall","origin":"ai"},{"id":"vertigo-vestibular-drugs~ai-5","moduleId":"vertigo-vestibular-drugs","stem":"How do vestibular suppressants affect vestibular compensation when used long-term?","options":[{"id":"a","text":"Enhance compensation"},{"id":"b","text":"Prevent compensation"},{"id":"c","text":"Have no effect"},{"id":"d","text":"Facilitate recovery"}],"answerId":"b","explanation":"Long-term use of vestibular suppressants prevents the brain from recalibrating, impairing vestibular compensation.","kind":"trap","origin":"ai"},{"id":"vertigo-vestibular-drugs~ai-6","moduleId":"vertigo-vestibular-drugs","stem":"Which vestibular drug class is most likely to cause dry mouth as a side effect?","options":[{"id":"a","text":"Benzodiazepines"},{"id":"b","text":"Antihistamines"},{"id":"c","text":"Anticholinergics"},{"id":"d","text":"Betahistine"}],"answerId":"c","explanation":"Anticholinergics are known to cause dry mouth due to their anticholinergic effects.","kind":"recall","origin":"ai"},{"id":"vertigo-vestibular-drugs~ai-7","moduleId":"vertigo-vestibular-drugs","stem":"How does the mechanism of action of betahistine relate to the physiology of the vestibular system?","options":[{"id":"a","text":"It blocks H1 receptors"},{"id":"b","text":"It enhances endolymphatic flow"},{"id":"c","text":"It inhibits vestibular nuclei"},{"id":"d","text":"It suppresses the vestibular signal"}],"answerId":"b","explanation":"Betahistine enhances endolymphatic flow, which is crucial for maintaining balance and reducing symptoms of Ménière disease.","kind":"integration","linkedModuleIds":["vestibular-system-physiology"],"origin":"ai"},{"id":"vertigo-vestibular-drugs~ai-8","moduleId":"vertigo-vestibular-drugs","stem":"Which vestibular drug class would be least effective in treating acute vertigo symptoms?","options":[{"id":"a","text":"Benzodiazepines"},{"id":"b","text":"Antihistamines"},{"id":"c","text":"Anticholinergics"},{"id":"d","text":"Ginkgo biloba"}],"answerId":"d","explanation":"Ginkgo biloba is not a recognized treatment for acute vertigo symptoms compared to the other options.","kind":"integration","linkedModuleIds":["ototopical-drugs"],"origin":"ai"}],"astrocytoma-glioblastoma":[{"id":"astrocytoma-glioblastoma~ai-0","moduleId":"astrocytoma-glioblastoma","stem":"What is the most common primary intraparenchymal brain tumor?","options":[{"id":"a","text":"Meningioma"},{"id":"b","text":"Astrocytoma"},{"id":"c","text":"Oligodendroglioma"},{"id":"d","text":"Ependymoma"}],"answerId":"b","explanation":"Astrocytomas are the most common primary intraparenchymal brain tumors.","kind":"recall","origin":"ai"},{"id":"astrocytoma-glioblastoma~ai-1","moduleId":"astrocytoma-glioblastoma","stem":"Which mutation is commonly associated with diffuse astrocytoma, IDH-mutant?","options":[{"id":"a","text":"TP53 mutation"},{"id":"b","text":"EGFR amplification"},{"id":"c","text":"IDH1/IDH2 mutation"},{"id":"d","text":"TERT-promoter mutation"}],"answerId":"c","explanation":"Diffuse astrocytoma, IDH-mutant is characterized by IDH1/IDH2 mutations.","kind":"mechanism","origin":"ai"},{"id":"astrocytoma-glioblastoma~ai-2","moduleId":"astrocytoma-glioblastoma","stem":"A 60-year-old patient presents with new-onset seizures and progressive headaches. MRI shows a ring-enhancing mass crossing the corpus callosum. What is the most likely diagnosis?","options":[{"id":"a","text":"Oligodendroglioma"},{"id":"b","text":"Ependymoma"},{"id":"c","text":"Glioblastoma"},{"id":"d","text":"Pilocytic astrocytoma"}],"answerId":"c","explanation":"The presentation is characteristic of glioblastoma, particularly the butterfly glioma appearance.","kind":"clinical","origin":"ai"},{"id":"astrocytoma-glioblastoma~ai-3","moduleId":"astrocytoma-glioblastoma","stem":"Which of the following findings is NOT typical for glioblastoma?","options":[{"id":"a","text":"Microvascular proliferation"},{"id":"b","text":"Pseudopalisading necrosis"},{"id":"c","text":"GFAP positivity"},{"id":"d","text":"Metastasis to the lungs"}],"answerId":"d","explanation":"Glioblastomas rarely metastasize outside the CNS; they primarily cause harm through local infiltration.","kind":"trap","origin":"ai"},{"id":"astrocytoma-glioblastoma~ai-4","moduleId":"astrocytoma-glioblastoma","stem":"In a patient with a glioblastoma, which molecular alteration is most commonly observed?","options":[{"id":"a","text":"1p/19q co-deletion"},{"id":"b","text":"EGFR amplification"},{"id":"c","text":"TP53 mutation"},{"id":"d","text":"NF1 mutation"}],"answerId":"b","explanation":"EGFR amplification is a common molecular alteration seen in glioblastoma, IDH-wildtype.","kind":"mechanism","origin":"ai"},{"id":"astrocytoma-glioblastoma~ai-5","moduleId":"astrocytoma-glioblastoma","stem":"How does the prognosis of diffuse astrocytoma, IDH-mutant compare to IDH-wildtype?","options":[{"id":"a","text":"Better prognosis for IDH-wildtype"},{"id":"b","text":"Similar prognosis"},{"id":"c","text":"Worse prognosis for IDH-mutant"},{"id":"d","text":"Better prognosis for IDH-mutant"}],"answerId":"d","explanation":"Diffuse astrocytoma, IDH-mutant generally has a better prognosis than IDH-wildtype glioblastoma.","kind":"recall","origin":"ai"},{"id":"astrocytoma-glioblastoma~ai-6","moduleId":"astrocytoma-glioblastoma","stem":"A patient with a glioblastoma is being evaluated for potential treatment options. Which of the following is most relevant when considering the risk of metastasis?","options":[{"id":"a","text":"CNS lymphomas typically metastasize to the liver"},{"id":"b","text":"Primary CNS tumors rarely metastasize outside the CNS"},{"id":"c","text":"Oligodendrogliomas have high metastatic potential"},{"id":"d","text":"Ependymomas commonly spread to the lungs"}],"answerId":"b","explanation":"Primary CNS tumors, including glioblastomas, rarely metastasize outside the CNS; they primarily cause harm through local infiltration.","kind":"integration","linkedModuleIds":["cns-lymphoma-metastases"],"origin":"ai"},{"id":"astrocytoma-glioblastoma~ai-7","moduleId":"astrocytoma-glioblastoma","stem":"Which of the following brain tumors is characterized by 1p/19q co-deletion?","options":[{"id":"a","text":"Glioblastoma"},{"id":"b","text":"Oligodendroglioma"},{"id":"c","text":"Astrocytoma"},{"id":"d","text":"Ependymoma"}],"answerId":"b","explanation":"Oligodendrogliomas are characterized by 1p/19q co-deletion, which is a key molecular feature.","kind":"integration","linkedModuleIds":["other-gliomas"],"origin":"ai"}],"pediatric-embryonal-tumors":[{"id":"pediatric-embryonal-tumors~ai-0","moduleId":"pediatric-embryonal-tumors","stem":"What is the most common location for medulloblastoma in children?","options":[{"id":"a","text":"Frontal lobe"},{"id":"b","text":"Cerebellum"},{"id":"c","text":"Temporal lobe"},{"id":"d","text":"Brainstem"}],"answerId":"b","explanation":"Medulloblastoma is exclusively found in the cerebellum in children.","kind":"recall","origin":"ai"},{"id":"pediatric-embryonal-tumors~ai-1","moduleId":"pediatric-embryonal-tumors","stem":"What histological feature is characteristic of medulloblastoma?","options":[{"id":"a","text":"Homer-Wright rosettes"},{"id":"b","text":"Calcifications"},{"id":"c","text":"Mitosis"},{"id":"d","text":"Pleomorphic cells"}],"answerId":"a","explanation":"Medulloblastoma is characterized by small round blue cells with Homer-Wright rosettes.","kind":"recall","origin":"ai"},{"id":"pediatric-embryonal-tumors~ai-2","moduleId":"pediatric-embryonal-tumors","stem":"A child presents with ataxia, morning headaches, and vomiting. What is the likely cause?","options":[{"id":"a","text":"Temporal lobe epilepsy"},{"id":"b","text":"Choroid plexus papilloma"},{"id":"c","text":"Medulloblastoma"},{"id":"d","text":"Ganglioglioma"}],"answerId":"c","explanation":"These symptoms suggest a cerebellar mass causing obstructive hydrocephalus, typical of medulloblastoma.","kind":"clinical","origin":"ai"},{"id":"pediatric-embryonal-tumors~ai-3","moduleId":"pediatric-embryonal-tumors","stem":"Which mechanism explains the spread of medulloblastoma?","options":[{"id":"a","text":"Hematogenous spread"},{"id":"b","text":"Lymphatic spread"},{"id":"c","text":"CSF dissemination"},{"id":"d","text":"Direct invasion"}],"answerId":"c","explanation":"Medulloblastoma spreads via the CSF, leading to drop metastases along the neuraxis.","kind":"mechanism","origin":"ai"},{"id":"pediatric-embryonal-tumors~ai-4","moduleId":"pediatric-embryonal-tumors","stem":"A young patient has drug-resistant temporal-lobe epilepsy. What is the most likely diagnosis?","options":[{"id":"a","text":"Medulloblastoma"},{"id":"b","text":"Ganglioglioma"},{"id":"c","text":"Choroid plexus papilloma"},{"id":"d","text":"Astrocytoma"}],"answerId":"b","explanation":"Ganglioglioma is the most common neuronal CNS tumor and often presents with epilepsy.","kind":"clinical","origin":"ai"},{"id":"pediatric-embryonal-tumors~ai-5","moduleId":"pediatric-embryonal-tumors","stem":"What is the primary complication of a choroid plexus papilloma in children?","options":[{"id":"a","text":"Seizures"},{"id":"b","text":"Hydrocephalus"},{"id":"c","text":"Ataxia"},{"id":"d","text":"Cerebral edema"}],"answerId":"b","explanation":"Choroid plexus papilloma can cause hydrocephalus due to obstruction and CSF overproduction.","kind":"recall","origin":"ai"},{"id":"pediatric-embryonal-tumors~ai-6","moduleId":"pediatric-embryonal-tumors","stem":"How does the spread pattern of medulloblastoma differ from that of other malignant brain tumors?","options":[{"id":"a","text":"It metastasizes hematogenously"},{"id":"b","text":"It spreads through CSF"},{"id":"c","text":"It invades surrounding tissues"},{"id":"d","text":"It does not metastasize"}],"answerId":"b","explanation":"Medulloblastoma uniquely spreads through CSF pathways, unlike many other malignant brain tumors.","kind":"trap","origin":"ai"},{"id":"pediatric-embryonal-tumors~ai-7","moduleId":"pediatric-embryonal-tumors","stem":"How might a medulloblastoma affect a child's neurological function compared to a ganglioglioma?","options":[{"id":"a","text":"More likely to cause seizures"},{"id":"b","text":"More likely to cause obstructive hydrocephalus"},{"id":"c","text":"More likely to metastasize"},{"id":"d","text":"More likely to present with headaches"}],"answerId":"b","explanation":"Medulloblastoma is more likely to cause obstructive hydrocephalus due to its location in the cerebellum.","kind":"integration","linkedModuleIds":["astrocytoma-glioblastoma"],"origin":"ai"},{"id":"pediatric-embryonal-tumors~ai-8","moduleId":"pediatric-embryonal-tumors","stem":"In a child with a medulloblastoma, what would be the expected finding on a CSF analysis?","options":[{"id":"a","text":"Elevated protein with lymphocytic pleocytosis"},{"id":"b","text":"Normal protein with neutrophilic pleocytosis"},{"id":"c","text":"Elevated protein with eosinophilic pleocytosis"},{"id":"d","text":"Normal protein with no pleocytosis"}],"answerId":"a","explanation":"CSF analysis in medulloblastoma typically shows elevated protein and lymphocytic pleocytosis due to tumor spread.","kind":"integration","linkedModuleIds":["cns-lymphoma-metastases"],"origin":"ai"}],"ototopical-drugs":[{"id":"ototopical-drugs~ai-0","moduleId":"ototopical-drugs","stem":"Which ototopical drug class is safest for use in patients with a suspected tympanic membrane perforation?","options":[{"id":"a","text":"Aminoglycosides"},{"id":"b","text":"Quinolones"},{"id":"c","text":"Polymyxins"},{"id":"d","text":"Chloramphenicol"}],"answerId":"b","explanation":"Quinolones are safe for use with potential tympanic membrane perforation as they do not cause inner-ear toxicity.","kind":"recall","origin":"ai"},{"id":"ototopical-drugs~ai-1","moduleId":"ototopical-drugs","stem":"What is the primary mechanism of action of antifungal ear drops like clotrimazole?","options":[{"id":"a","text":"Inhibit bacterial cell wall synthesis"},{"id":"b","text":"Block ergosterol synthesis"},{"id":"c","text":"Disrupt protein synthesis"},{"id":"d","text":"Inhibit DNA replication"}],"answerId":"b","explanation":"Azole antifungals like clotrimazole block ergosterol synthesis, which is essential for fungal cell membrane integrity.","kind":"mechanism","origin":"ai"},{"id":"ototopical-drugs~ai-2","moduleId":"ototopical-drugs","stem":"A patient presents with an itchy, damp ear and debris consistent with otomycosis. Which ototopical agent is most appropriate?","options":[{"id":"a","text":"Ofloxacin"},{"id":"b","text":"Clotrimazole"},{"id":"c","text":"Hydrogen peroxide"},{"id":"d","text":"Gentamicin"}],"answerId":"b","explanation":"Clotrimazole is effective against fungal infections like otomycosis, while other options are not suitable for this condition.","kind":"clinical","origin":"ai"},{"id":"ototopical-drugs~ai-3","moduleId":"ototopical-drugs","stem":"Which of the following findings is most indicative of bacterial otitis externa?","options":[{"id":"a","text":"Itchy ear with fungal debris"},{"id":"b","text":"Painful, swollen, discharging canal"},{"id":"c","text":"New onset vertigo"},{"id":"d","text":"Dry ear canal"}],"answerId":"b","explanation":"A painful, swollen, discharging canal is characteristic of bacterial otitis externa, particularly from Pseudomonas or S. aureus.","kind":"recall","origin":"ai"},{"id":"ototopical-drugs~ai-4","moduleId":"ototopical-drugs","stem":"What is the risk associated with using aminoglycoside ear drops in a patient with a perforated tympanic membrane?","options":[{"id":"a","text":"Systemic toxicity"},{"id":"b","text":"Ototoxicity"},{"id":"c","text":"Allergic reaction"},{"id":"d","text":"Superinfection"}],"answerId":"b","explanation":"Aminoglycosides can cause ototoxicity if they reach the inner ear through a perforated tympanic membrane.","kind":"trap","origin":"ai"},{"id":"ototopical-drugs~ai-5","moduleId":"ototopical-drugs","stem":"A patient with a history of vertigo is prescribed ototopical drops. Which class of drugs should be avoided due to potential exacerbation of vestibular symptoms?","options":[{"id":"a","text":"Quinolones"},{"id":"b","text":"Steroids"},{"id":"c","text":"Aminoglycosides"},{"id":"d","text":"Cerumenolytics"}],"answerId":"c","explanation":"Aminoglycosides can cause ototoxicity, which may exacerbate vestibular symptoms in patients with a history of vertigo.","kind":"integration","linkedModuleIds":["vertigo-vestibular-drugs"],"origin":"ai"},{"id":"ototopical-drugs~ai-6","moduleId":"ototopical-drugs","stem":"In patients with recurrent otitis externa, which ototopical agent can help restore the acidic pH of the ear canal?","options":[{"id":"a","text":"Ofloxacin"},{"id":"b","text":"Acetic acid"},{"id":"c","text":"Clotrimazole"},{"id":"d","text":"Hydrogen peroxide"}],"answerId":"b","explanation":"Acetic acid is an acidifying agent that helps restore the acidic pH of the ear canal, preventing recurrent infections.","kind":"clinical","origin":"ai"},{"id":"ototopical-drugs~ai-7","moduleId":"ototopical-drugs","stem":"Which ototopical agent should be avoided in a patient with a suspected perforation of the tympanic membrane?","options":[{"id":"a","text":"Ciprofloxacin"},{"id":"b","text":"Docusate"},{"id":"c","text":"Neomycin"},{"id":"d","text":"Miconazole"}],"answerId":"c","explanation":"Neomycin is ototoxic and should be avoided in cases of suspected tympanic membrane perforation.","kind":"trap","origin":"ai"},{"id":"ototopical-drugs~ai-8","moduleId":"ototopical-drugs","stem":"A swimmer develops otitis externa. Which ototopical agent is most appropriate for prevention of recurrence?","options":[{"id":"a","text":"Hydrogen peroxide"},{"id":"b","text":"Acetic acid"},{"id":"c","text":"Ofloxacin"},{"id":"d","text":"Clotrimazole"}],"answerId":"b","explanation":"Acetic acid helps maintain the acidic environment of the ear canal, preventing recurrent otitis externa in swimmers.","kind":"integration","linkedModuleIds":["external-ear-disorders"],"origin":"ai"}],"other-gliomas":[{"id":"other-gliomas~ai-0","moduleId":"other-gliomas","stem":"What is the molecular hallmark required for the diagnosis of oligodendroglioma?","options":[{"id":"a","text":"IDH-mutant AND 1p/19q whole-arm codeletion"},{"id":"b","text":"TP53 mutation"},{"id":"c","text":"EGFR amplification"},{"id":"d","text":"MGMT promoter methylation"}],"answerId":"a","explanation":"Oligodendroglioma is characterized by IDH mutations and 1p/19q codeletion, which are essential for diagnosis and predict chemosensitivity.","kind":"recall","origin":"ai"},{"id":"other-gliomas~ai-1","moduleId":"other-gliomas","stem":"Which histological feature is characteristic of oligodendroglioma?","options":[{"id":"a","text":"Bipolar GFAP+ cells"},{"id":"b","text":"Fried-egg cells"},{"id":"c","text":"Perivascular pseudorosettes"},{"id":"d","text":"Eosinophilic granular bodies"}],"answerId":"b","explanation":"Oligodendrogliomas are identified histologically by the presence of fried-egg cells and a chicken-wire capillary network.","kind":"recall","origin":"ai"},{"id":"other-gliomas~ai-2","moduleId":"other-gliomas","stem":"A child presents with a cerebellar cyst and a mural nodule. What is the most likely diagnosis?","options":[{"id":"a","text":"Ependymoma"},{"id":"b","text":"Oligodendroglioma"},{"id":"c","text":"Pilocytic astrocytoma"},{"id":"d","text":"Medulloblastoma"}],"answerId":"c","explanation":"The clinical presentation is typical of pilocytic astrocytoma, which is often well-circumscribed and can be cured by resection.","kind":"clinical","origin":"ai"},{"id":"other-gliomas~ai-3","moduleId":"other-gliomas","stem":"What is the typical location for ependymoma in children?","options":[{"id":"a","text":"Cerebellum"},{"id":"b","text":"Frontal lobe"},{"id":"c","text":"4th ventricle"},{"id":"d","text":"Temporal lobe"}],"answerId":"c","explanation":"Ependymomas commonly arise near the ventricular system, particularly in the 4th ventricle in children, leading to hydrocephalus.","kind":"recall","origin":"ai"},{"id":"other-gliomas~ai-4","moduleId":"other-gliomas","stem":"Which statement correctly differentiates pilocytic astrocytoma from other gliomas?","options":[{"id":"a","text":"All gliomas are aggressive and infiltrative."},{"id":"b","text":"Pilocytic astrocytoma is a well-circumscribed WHO grade 1 tumor."},{"id":"c","text":"Pilocytic astrocytoma is always associated with hydrocephalus."},{"id":"d","text":"Pilocytic astrocytoma has a poor prognosis."}],"answerId":"b","explanation":"Pilocytic astrocytoma is a low-grade, well-circumscribed tumor that is often curable by resection, unlike more aggressive gliomas.","kind":"trap","origin":"ai"},{"id":"other-gliomas~ai-5","moduleId":"other-gliomas","stem":"How does the histology of ependymoma differ from that of oligodendroglioma?","options":[{"id":"a","text":"Ependymoma shows fried-egg cells."},{"id":"b","text":"Oligodendroglioma shows perivascular pseudorosettes."},{"id":"c","text":"Ependymoma has true ependymal rosettes."},{"id":"d","text":"Oligodendroglioma has eosinophilic granular bodies."}],"answerId":"c","explanation":"Ependymomas are characterized by true ependymal rosettes and perivascular pseudorosettes, while oligodendrogliomas show fried-egg cells.","kind":"mechanism","origin":"ai"},{"id":"other-gliomas~ai-6","moduleId":"other-gliomas","stem":"A 5-year-old child presents with hydrocephalus and a mass in the 4th ventricle. Which tumor type should be considered?","options":[{"id":"a","text":"Pilocytic astrocytoma"},{"id":"b","text":"Oligodendroglioma"},{"id":"c","text":"Ependymoma"},{"id":"d","text":"Medulloblastoma"}],"answerId":"c","explanation":"Ependymomas commonly present in the 4th ventricle in children and can lead to hydrocephalus due to obstruction of cerebrospinal fluid flow.","kind":"clinical","origin":"ai"},{"id":"other-gliomas~ai-7","moduleId":"other-gliomas","stem":"Which tumor is associated with IDH mutations and is typically found in adults?","options":[{"id":"a","text":"Pilocytic astrocytoma"},{"id":"b","text":"Ependymoma"},{"id":"c","text":"Oligodendroglioma"},{"id":"d","text":"Medulloblastoma"}],"answerId":"c","explanation":"Oligodendrogliomas are characterized by IDH mutations and are more common in adults, particularly in the 4th to 5th decades of life.","kind":"recall","origin":"ai"},{"id":"other-gliomas~ai-8","moduleId":"other-gliomas","stem":"How does pilocytic astrocytoma differ from glioblastoma in terms of prognosis?","options":[{"id":"a","text":"Both have poor prognosis."},{"id":"b","text":"Pilocytic astrocytoma is often curable by resection."},{"id":"c","text":"Both are well-circumscribed tumors."},{"id":"d","text":"Pilocytic astrocytoma is more aggressive."}],"answerId":"b","explanation":"Pilocytic astrocytoma is a low-grade tumor with a good prognosis, often curable by resection, while glioblastoma is aggressive and has a poor prognosis.","kind":"integration","linkedModuleIds":["astrocytoma-glioblastoma"],"origin":"ai"}],"migraine-pathophysiology-acute":[{"id":"migraine-pathophysiology-acute~ai-0","moduleId":"migraine-pathophysiology-acute","stem":"What is the primary neurotransmitter involved in the trigeminovascular activation during a migraine attack?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"CGRP"},{"id":"c","text":"Serotonin"},{"id":"d","text":"Substance P"}],"answerId":"b","explanation":"Calcitonin gene-related peptide (CGRP) is released during trigeminovascular activation, contributing to neurogenic inflammation and vasodilation.","kind":"recall","origin":"ai"},{"id":"migraine-pathophysiology-acute~ai-1","moduleId":"migraine-pathophysiology-acute","stem":"Which acute treatment for migraine is contraindicated in patients with coronary artery disease?","options":[{"id":"a","text":"Ibuprofen"},{"id":"b","text":"Rimegepant"},{"id":"c","text":"Lasmiditan"},{"id":"d","text":"Sumatriptan"}],"answerId":"d","explanation":"Sumatriptan, a triptan, can cause coronary vasospasm and is contraindicated in patients with coronary artery disease.","kind":"trap","origin":"ai"},{"id":"migraine-pathophysiology-acute~ai-2","moduleId":"migraine-pathophysiology-acute","stem":"What is the mechanism of action of triptans in treating migraines?","options":[{"id":"a","text":"Dopamine receptor antagonism"},{"id":"b","text":"CGRP receptor antagonism"},{"id":"c","text":"5-HT1B/1D receptor agonism"},{"id":"d","text":"Prostaglandin inhibition"}],"answerId":"c","explanation":"Triptans act as agonists at 5-HT1B and 5-HT1D receptors, leading to vasoconstriction and inhibition of pro-inflammatory neuropeptides.","kind":"mechanism","origin":"ai"},{"id":"migraine-pathophysiology-acute~ai-3","moduleId":"migraine-pathophysiology-acute","stem":"A patient experiences a scintillating scotoma before a migraine. What is the underlying pathophysiological mechanism?","options":[{"id":"a","text":"Cortical spreading depression"},{"id":"b","text":"Trigeminal nerve activation"},{"id":"c","text":"Vasodilation"},{"id":"d","text":"Neurogenic inflammation"}],"answerId":"a","explanation":"Scintillating scotoma is caused by cortical spreading depression, which is a wave of depolarization in the visual cortex.","kind":"recall","origin":"ai"},{"id":"migraine-pathophysiology-acute~ai-4","moduleId":"migraine-pathophysiology-acute","stem":"Which medication would be safest for treating a migraine in a patient with a history of hypertension?","options":[{"id":"a","text":"Ergotamine"},{"id":"b","text":"Ibuprofen"},{"id":"c","text":"Lasmiditan"},{"id":"d","text":"Sumatriptan"}],"answerId":"c","explanation":"Lasmiditan is a 5-HT1F agonist that does not cause vasoconstriction, making it safe for patients with hypertension.","kind":"trap","origin":"ai"},{"id":"migraine-pathophysiology-acute~ai-5","moduleId":"migraine-pathophysiology-acute","stem":"How does the mechanism of action of gepants differ from that of triptans?","options":[{"id":"a","text":"Gepants inhibit prostaglandins"},{"id":"b","text":"Gepants are CGRP receptor antagonists"},{"id":"c","text":"Gepants are 5-HT1B agonists"},{"id":"d","text":"Gepants cause vasoconstriction"}],"answerId":"b","explanation":"Gepants are CGRP receptor antagonists, while triptans are 5-HT1B/1D agonists that can cause vasoconstriction.","kind":"mechanism","origin":"ai"},{"id":"migraine-pathophysiology-acute~ai-6","moduleId":"migraine-pathophysiology-acute","stem":"Which of the following is a common prophylactic treatment for migraines that may be linked to hypertension?","options":[{"id":"a","text":"Propranolol"},{"id":"b","text":"Rimegepant"},{"id":"c","text":"Lasmiditan"},{"id":"d","text":"Ibuprofen"}],"answerId":"a","explanation":"Propranolol is a beta-blocker commonly used for migraine prophylaxis and is also effective in managing hypertension.","kind":"integration","linkedModuleIds":["htn-pathophysiology"],"origin":"ai"},{"id":"migraine-pathophysiology-acute~ai-7","moduleId":"migraine-pathophysiology-acute","stem":"In a patient with frequent migraines, which prophylactic treatment could also help manage their hypertension?","options":[{"id":"a","text":"Topiramate"},{"id":"b","text":"Amitriptyline"},{"id":"c","text":"Verapamil"},{"id":"d","text":"Divalproex"}],"answerId":"c","explanation":"Verapamil is a calcium channel blocker that can be used for both hypertension and migraine prophylaxis.","kind":"integration","linkedModuleIds":["htn-pathophysiology"],"origin":"ai"}],"opioid-effects-toxicity":[{"id":"opioid-effects-toxicity~ai-0","moduleId":"opioid-effects-toxicity","stem":"What is the most dangerous effect of opioid overdose?","options":[{"id":"a","text":"Respiratory depression"},{"id":"b","text":"Pinpoint miosis"},{"id":"c","text":"Coma"},{"id":"d","text":"Constipation"}],"answerId":"a","explanation":"Respiratory depression is the leading cause of mortality in opioid overdose cases.","kind":"recall","origin":"ai"},{"id":"opioid-effects-toxicity~ai-1","moduleId":"opioid-effects-toxicity","stem":"Which of the following is a key diagnostic clue for opioid overdose?","options":[{"id":"a","text":"Mydriasis"},{"id":"b","text":"Pinpoint miosis"},{"id":"c","text":"Tachycardia"},{"id":"d","text":"Hyperreflexia"}],"answerId":"b","explanation":"Pinpoint miosis is a classic sign of opioid overdose.","kind":"recall","origin":"ai"},{"id":"opioid-effects-toxicity~ai-2","moduleId":"opioid-effects-toxicity","stem":"Which opioid effect does NOT develop tolerance with chronic use?","options":[{"id":"a","text":"Analgesia"},{"id":"b","text":"Euphoria"},{"id":"c","text":"Constipation"},{"id":"d","text":"Respiratory depression"}],"answerId":"c","explanation":"Tolerance does not develop to constipation, making it a persistent side effect.","kind":"trap","origin":"ai"},{"id":"opioid-effects-toxicity~ai-3","moduleId":"opioid-effects-toxicity","stem":"What is the mechanism of action of naloxone?","options":[{"id":"a","text":"Agonist at μ receptors"},{"id":"b","text":"Competitive antagonist at μ receptors"},{"id":"c","text":"Inhibitor of CYP2D6"},{"id":"d","text":"Non-selective opioid receptor agonist"}],"answerId":"b","explanation":"Naloxone acts as a competitive antagonist at μ receptors, reversing opioid effects.","kind":"mechanism","origin":"ai"},{"id":"opioid-effects-toxicity~ai-4","moduleId":"opioid-effects-toxicity","stem":"A patient presents with mydriasis, piloerection, and diarrhea after stopping opioid use. What is this presentation indicative of?","options":[{"id":"a","text":"Opioid overdose"},{"id":"b","text":"Opioid withdrawal"},{"id":"c","text":"Opioid tolerance"},{"id":"d","text":"Opioid dependence"}],"answerId":"b","explanation":"These symptoms are characteristic of opioid withdrawal.","kind":"clinical","origin":"ai"},{"id":"opioid-effects-toxicity~ai-5","moduleId":"opioid-effects-toxicity","stem":"How does the mechanism of opioid receptors relate to their analgesic effects?","options":[{"id":"a","text":"Inhibition of serotonin reuptake"},{"id":"b","text":"Activation of μ receptors leading to decreased pain perception"},{"id":"c","text":"Inhibition of prostaglandin synthesis"},{"id":"d","text":"Stimulation of dopamine release"}],"answerId":"b","explanation":"Opioids activate μ receptors, which decreases pain perception in the CNS.","kind":"integration","linkedModuleIds":["opioid-receptors-mechanism"],"origin":"ai"},{"id":"opioid-effects-toxicity~ai-6","moduleId":"opioid-effects-toxicity","stem":"In the context of opioid overdose, which finding would be most consistent with the triad of symptoms?","options":[{"id":"a","text":"Elevated blood pressure"},{"id":"b","text":"Pinpoint pupils"},{"id":"c","text":"Tachycardia"},{"id":"d","text":"Hyperactive reflexes"}],"answerId":"b","explanation":"The triad of opioid overdose includes pinpoint pupils, respiratory depression, and coma.","kind":"integration","linkedModuleIds":["acetaminophen-overdose-pattern"],"origin":"ai"}],"antipsychotics-dopamine-eps":[{"id":"antipsychotics-dopamine-eps~ai-0","moduleId":"antipsychotics-dopamine-eps","stem":"What is the primary mechanism of action of typical antipsychotics?","options":[{"id":"a","text":"Block 5-HT2A receptors"},{"id":"b","text":"Block D2 receptors"},{"id":"c","text":"Block α1 adrenergic receptors"},{"id":"d","text":"Block M receptors"}],"answerId":"b","explanation":"Typical antipsychotics primarily block D2 receptors to treat psychosis.","kind":"mechanism","origin":"ai"},{"id":"antipsychotics-dopamine-eps~ai-1","moduleId":"antipsychotics-dopamine-eps","stem":"Which extrapyramidal symptom is characterized by sustained muscle contractions?","options":[{"id":"a","text":"Akathisia"},{"id":"b","text":"Acute dystonia"},{"id":"c","text":"Tardive dyskinesia"},{"id":"d","text":"Parkinsonism"}],"answerId":"b","explanation":"Acute dystonia presents with sustained muscle contractions and can occur shortly after starting antipsychotic treatment.","kind":"recall","origin":"ai"},{"id":"antipsychotics-dopamine-eps~ai-2","moduleId":"antipsychotics-dopamine-eps","stem":"A patient develops fever, rigidity, and altered mental status after starting an antipsychotic. What is the most likely diagnosis?","options":[{"id":"a","text":"Serotonin syndrome"},{"id":"b","text":"Neuroleptic malignant syndrome"},{"id":"c","text":"Acute dystonia"},{"id":"d","text":"Tardive dyskinesia"}],"answerId":"b","explanation":"These symptoms are characteristic of neuroleptic malignant syndrome, a serious reaction to antipsychotic medications.","kind":"clinical","origin":"ai"},{"id":"antipsychotics-dopamine-eps~ai-3","moduleId":"antipsychotics-dopamine-eps","stem":"What is the most appropriate treatment for akathisia caused by antipsychotics?","options":[{"id":"a","text":"Dantrolene"},{"id":"b","text":"Propranolol"},{"id":"c","text":"Anticholinergics"},{"id":"d","text":"Amantadine"}],"answerId":"b","explanation":"Propranolol is effective for managing akathisia, which is characterized by a feeling of inner restlessness.","kind":"recall","origin":"ai"},{"id":"antipsychotics-dopamine-eps~ai-4","moduleId":"antipsychotics-dopamine-eps","stem":"Which of the following symptoms differentiates neuroleptic malignant syndrome from serotonin syndrome?","options":[{"id":"a","text":"Hyperreflexia"},{"id":"b","text":"Lead-pipe rigidity"},{"id":"c","text":"Choreoathetoid movements"},{"id":"d","text":"Oculogyric crisis"}],"answerId":"b","explanation":"Lead-pipe rigidity is a hallmark of neuroleptic malignant syndrome, while hyperreflexia is seen in serotonin syndrome.","kind":"trap","origin":"ai"},{"id":"antipsychotics-dopamine-eps~ai-5","moduleId":"antipsychotics-dopamine-eps","stem":"How do atypical antipsychotics differ from typical antipsychotics in their receptor activity?","options":[{"id":"a","text":"They block D2 receptors more effectively"},{"id":"b","text":"They block 5-HT2A receptors more than D2"},{"id":"c","text":"They do not cause EPS"},{"id":"d","text":"They are less effective for positive symptoms"}],"answerId":"b","explanation":"Atypical antipsychotics primarily block 5-HT2A receptors more than D2, leading to a better balance of treating negative symptoms and fewer motor side effects.","kind":"integration","linkedModuleIds":["atypical-antipsychotic-agents"],"origin":"ai"},{"id":"antipsychotics-dopamine-eps~ai-6","moduleId":"antipsychotics-dopamine-eps","stem":"Which pathway is primarily affected leading to negative symptoms in schizophrenia?","options":[{"id":"a","text":"Mesolimbic pathway"},{"id":"b","text":"Nigrostriatal pathway"},{"id":"c","text":"Mesocortical pathway"},{"id":"d","text":"Tuberoinfundibular pathway"}],"answerId":"c","explanation":"The mesocortical pathway is associated with negative symptoms, as decreased dopamine activity in this area can lead to symptoms like flat affect and avolition.","kind":"integration","linkedModuleIds":["atypical-antipsychotic-agents"],"origin":"ai"}],"sedative-hypnotics-benzodiazepines":[{"id":"sedative-hypnotics-benzodiazepines~ai-0","moduleId":"sedative-hypnotics-benzodiazepines","stem":"What is the primary mechanism of action of benzodiazepines?","options":[{"id":"a","text":"Inhibit GABA_A receptor"},{"id":"b","text":"Enhance GABA_A receptor activity"},{"id":"c","text":"Block NMDA receptors"},{"id":"d","text":"Inhibit serotonin reuptake"}],"answerId":"b","explanation":"Benzodiazepines enhance GABA_A receptor activity, leading to increased inhibition in the CNS.","kind":"mechanism","origin":"ai"},{"id":"sedative-hypnotics-benzodiazepines~ai-1","moduleId":"sedative-hypnotics-benzodiazepines","stem":"Which benzodiazepine is safest for an elderly patient with liver disease?","options":[{"id":"a","text":"Diazepam"},{"id":"b","text":"Lorazepam"},{"id":"c","text":"Alprazolam"},{"id":"d","text":"Clonazepam"}],"answerId":"b","explanation":"Lorazepam is preferred as it undergoes glucuronidation and does not have active metabolites, minimizing the risk of accumulation.","kind":"trap","origin":"ai"},{"id":"sedative-hypnotics-benzodiazepines~ai-2","moduleId":"sedative-hypnotics-benzodiazepines","stem":"What effect would you expect from a benzodiazepine overdose?","options":[{"id":"a","text":"Severe hypertension"},{"id":"b","text":"Respiratory depression"},{"id":"c","text":"Increased muscle tone"},{"id":"d","text":"Hyperactivity"}],"answerId":"b","explanation":"Benzodiazepine overdose typically leads to respiratory depression due to excessive CNS inhibition.","kind":"clinical","origin":"ai"},{"id":"sedative-hypnotics-benzodiazepines~ai-3","moduleId":"sedative-hypnotics-benzodiazepines","stem":"Which of the following is a common side effect of benzodiazepines?","options":[{"id":"a","text":"Euphoria"},{"id":"b","text":"Anterograde amnesia"},{"id":"c","text":"Increased alertness"},{"id":"d","text":"Hallucinations"}],"answerId":"b","explanation":"Anterograde amnesia is a well-known side effect of benzodiazepines due to their effects on memory formation.","kind":"recall","origin":"ai"},{"id":"sedative-hypnotics-benzodiazepines~ai-4","moduleId":"sedative-hypnotics-benzodiazepines","stem":"What distinguishes Z-drugs from benzodiazepines?","options":[{"id":"a","text":"Z-drugs have no sedative effect"},{"id":"b","text":"Z-drugs selectively bind to α1-GABA_A subunits"},{"id":"c","text":"Z-drugs are not reversible by flumazenil"},{"id":"d","text":"Z-drugs have longer half-lives"}],"answerId":"b","explanation":"Z-drugs selectively bind to the α1 subunit of the GABA_A receptor, providing hypnotic effects with fewer side effects.","kind":"mechanism","origin":"ai"},{"id":"sedative-hypnotics-benzodiazepines~ai-5","moduleId":"sedative-hypnotics-benzodiazepines","stem":"How do benzodiazepines affect pain perception in patients with anxiety?","options":[{"id":"a","text":"Increase pain perception"},{"id":"b","text":"Decrease pain perception"},{"id":"c","text":"No effect on pain perception"},{"id":"d","text":"Alter pain threshold"}],"answerId":"b","explanation":"Benzodiazepines can decrease pain perception by reducing anxiety, which may enhance the overall pain experience.","kind":"integration","linkedModuleIds":["pain-nociception-modulation"],"origin":"ai"},{"id":"sedative-hypnotics-benzodiazepines~ai-6","moduleId":"sedative-hypnotics-benzodiazepines","stem":"Which of the following is true about the metabolism of barbiturates compared to benzodiazepines?","options":[{"id":"a","text":"Barbiturates have no active metabolites"},{"id":"b","text":"Barbiturates are safer in liver disease"},{"id":"c","text":"Benzodiazepines are metabolized by phase-1 oxidation"},{"id":"d","text":"Barbiturates enhance GABA_A receptor frequency"}],"answerId":"c","explanation":"Benzodiazepines are primarily metabolized by hepatic CYP phase-1 oxidation, while barbiturates have a different metabolic pathway.","kind":"integration","linkedModuleIds":["barbiturates-and-anxiolytics"],"origin":"ai"}],"tca-maoi-atypical-antidepressants":[{"id":"tca-maoi-atypical-antidepressants~ai-0","moduleId":"tca-maoi-atypical-antidepressants","stem":"Which of the following is a common side effect of tricyclic antidepressants (TCAs)?","options":[{"id":"a","text":"Dry mouth"},{"id":"b","text":"Increased libido"},{"id":"c","text":"Nausea"},{"id":"d","text":"Tremors"}],"answerId":"a","explanation":"TCAs commonly cause anticholinergic side effects such as dry mouth due to their muscarinic receptor antagonism.","kind":"recall","origin":"ai"},{"id":"tca-maoi-atypical-antidepressants~ai-1","moduleId":"tca-maoi-atypical-antidepressants","stem":"What is the mechanism of action of monoamine oxidase inhibitors (MAOIs)?","options":[{"id":"a","text":"Inhibit serotonin reuptake"},{"id":"b","text":"Block norepinephrine receptors"},{"id":"c","text":"Inhibit monoamine oxidase"},{"id":"d","text":"Antagonize dopamine receptors"}],"answerId":"c","explanation":"MAOIs inhibit monoamine oxidase, leading to increased levels of serotonin, norepinephrine, and dopamine.","kind":"mechanism","origin":"ai"},{"id":"tca-maoi-atypical-antidepressants~ai-2","moduleId":"tca-maoi-atypical-antidepressants","stem":"A patient on phenelzine develops severe hypertension after eating aged cheese. What is the likely cause?","options":[{"id":"a","text":"Serotonin syndrome"},{"id":"b","text":"Tyramine hypertensive crisis"},{"id":"c","text":"Drug interaction with SSRIs"},{"id":"d","text":"Withdrawal symptoms"}],"answerId":"b","explanation":"The ingestion of tyramine-rich foods while on MAOIs can lead to a hypertensive crisis due to excessive norepinephrine release.","kind":"recall","origin":"ai"},{"id":"tca-maoi-atypical-antidepressants~ai-3","moduleId":"tca-maoi-atypical-antidepressants","stem":"Which antidepressant is contraindicated in patients with a history of seizures?","options":[{"id":"a","text":"Mirtazapine"},{"id":"b","text":"Bupropion"},{"id":"c","text":"Amitriptyline"},{"id":"d","text":"Fluoxetine"}],"answerId":"b","explanation":"Bupropion lowers the seizure threshold and is contraindicated in individuals with seizure disorders.","kind":"trap","origin":"ai"},{"id":"tca-maoi-atypical-antidepressants~ai-4","moduleId":"tca-maoi-atypical-antidepressants","stem":"A patient with depression, insomnia, and poor appetite is prescribed mirtazapine. What is the expected benefit of this medication?","options":[{"id":"a","text":"Increased energy"},{"id":"b","text":"Decreased anxiety"},{"id":"c","text":"Improved sleep and appetite"},{"id":"d","text":"Weight loss"}],"answerId":"c","explanation":"Mirtazapine is known to improve sleep and appetite due to its sedative effects and appetite stimulation.","kind":"clinical","origin":"ai"},{"id":"tca-maoi-atypical-antidepressants~ai-5","moduleId":"tca-maoi-atypical-antidepressants","stem":"How does the mechanism of action of bupropion differ from that of SSRIs?","options":[{"id":"a","text":"Bupropion inhibits serotonin reuptake"},{"id":"b","text":"Bupropion blocks dopamine and norepinephrine reuptake"},{"id":"c","text":"Bupropion is an MAOI"},{"id":"d","text":"Bupropion is a serotonin receptor antagonist"}],"answerId":"b","explanation":"Bupropion primarily blocks the reuptake of dopamine and norepinephrine, while SSRIs specifically inhibit serotonin reuptake.","kind":"integration","linkedModuleIds":["antidepressants-ssri-snri"],"origin":"ai"},{"id":"tca-maoi-atypical-antidepressants~ai-6","moduleId":"tca-maoi-atypical-antidepressants","stem":"Which of the following best explains the mechanism of action of MAOIs in the treatment of depression?","options":[{"id":"a","text":"Inhibition of serotonin reuptake"},{"id":"b","text":"Inhibition of monoamine oxidase"},{"id":"c","text":"Inhibition of norepinephrine reuptake"},{"id":"d","text":"Antagonism of serotonin receptors"}],"answerId":"b","explanation":"MAOIs work by inhibiting monoamine oxidase, leading to increased levels of neurotransmitters like serotonin, norepinephrine, and dopamine.","kind":"integration","linkedModuleIds":["antidepressants-ssri-snri"],"origin":"ai"}],"antidepressants-ssri-snri":[{"id":"antidepressants-ssri-snri~ai-0","moduleId":"antidepressants-ssri-snri","stem":"What is the primary mechanism of action of SSRIs?","options":[{"id":"a","text":"Inhibit monoamine oxidase"},{"id":"b","text":"Block serotonin reuptake"},{"id":"c","text":"Increase dopamine release"},{"id":"d","text":"Antagonize serotonin receptors"}],"answerId":"b","explanation":"SSRIs primarily block the serotonin transporter (SERT), leading to increased serotonin levels in the synaptic cleft.","kind":"mechanism","origin":"ai"},{"id":"antidepressants-ssri-snri~ai-1","moduleId":"antidepressants-ssri-snri","stem":"Which SSRI is known for having the longest half-life?","options":[{"id":"a","text":"Sertraline"},{"id":"b","text":"Citalopram"},{"id":"c","text":"Fluoxetine"},{"id":"d","text":"Paroxetine"}],"answerId":"c","explanation":"Fluoxetine has a long half-life, making it unique among SSRIs.","kind":"recall","origin":"ai"},{"id":"antidepressants-ssri-snri~ai-2","moduleId":"antidepressants-ssri-snri","stem":"A patient presents with clonus, hyperreflexia, and altered mental status after starting an SSRI. What condition is most likely?","options":[{"id":"a","text":"Serotonin syndrome"},{"id":"b","text":"Neuroleptic malignant syndrome"},{"id":"c","text":"Withdrawal syndrome"},{"id":"d","text":"Antidepressant discontinuation syndrome"}],"answerId":"a","explanation":"These symptoms are characteristic of serotonin syndrome, which can occur with excessive serotonergic activity.","kind":"clinical","origin":"ai"},{"id":"antidepressants-ssri-snri~ai-3","moduleId":"antidepressants-ssri-snri","stem":"What is a common side effect of SSRIs that can occur early in treatment?","options":[{"id":"a","text":"Weight gain"},{"id":"b","text":"Nausea"},{"id":"c","text":"Sedation"},{"id":"d","text":"Hypertension"}],"answerId":"b","explanation":"Nausea is a common serotonergic side effect experienced early in SSRI therapy.","kind":"recall","origin":"ai"},{"id":"antidepressants-ssri-snri~ai-4","moduleId":"antidepressants-ssri-snri","stem":"Which of the following statements about the timing of antidepressant response is true?","options":[{"id":"a","text":"SSRIs should show improvement within a few days"},{"id":"b","text":"Antidepressants require 2–4 weeks for full effect"},{"id":"c","text":"Immediate mood improvement indicates efficacy"},{"id":"d","text":"Switching SSRIs is recommended after one week"}],"answerId":"b","explanation":"Antidepressants typically require 2–4 weeks for full therapeutic effect, regardless of early synaptic changes.","kind":"trap","origin":"ai"},{"id":"antidepressants-ssri-snri~ai-5","moduleId":"antidepressants-ssri-snri","stem":"How do SNRIs differ from SSRIs in their mechanism of action?","options":[{"id":"a","text":"SNRIs block only serotonin reuptake"},{"id":"b","text":"SNRIs block both serotonin and norepinephrine reuptake"},{"id":"c","text":"SNRIs have no effect on norepinephrine"},{"id":"d","text":"SNRIs primarily increase dopamine levels"}],"answerId":"b","explanation":"SNRIs block the reuptake of both serotonin and norepinephrine, differentiating them from SSRIs.","kind":"mechanism","origin":"ai"},{"id":"antidepressants-ssri-snri~ai-6","moduleId":"antidepressants-ssri-snri","stem":"Which of the following is a potential interaction when combining an SSRI with an MAOI?","options":[{"id":"a","text":"Increased serotonin reuptake"},{"id":"b","text":"Serotonin syndrome"},{"id":"c","text":"Decreased antidepressant effect"},{"id":"d","text":"Increased norepinephrine activity"}],"answerId":"b","explanation":"Combining an SSRI with an MAOI can lead to serotonin syndrome due to excessive serotonergic activity.","kind":"integration","linkedModuleIds":["tca-maoi-atypical-antidepressants"],"origin":"ai"},{"id":"antidepressants-ssri-snri~ai-7","moduleId":"antidepressants-ssri-snri","stem":"How might the mechanism of SSRIs relate to synaptic plasticity in the context of mood disorders?","options":[{"id":"a","text":"They directly enhance synaptic plasticity"},{"id":"b","text":"They increase dopamine levels affecting memory"},{"id":"c","text":"They promote neuroadaptation over time"},{"id":"d","text":"They inhibit long-term depression"}],"answerId":"c","explanation":"SSRIs promote neuroadaptation over time, which is crucial for their delayed mood-lifting effects.","kind":"integration","linkedModuleIds":["synaptic-plasticity-ltd-memory"],"origin":"ai"}],"migraine-prophylaxis":[{"id":"migraine-prophylaxis~ai-0","moduleId":"migraine-prophylaxis","stem":"What is the primary indication for migraine prophylaxis?","options":[{"id":"a","text":"To abort a single migraine attack"},{"id":"b","text":"For infrequent mild migraines"},{"id":"c","text":"For frequent or disabling migraines"},{"id":"d","text":"To treat acute migraine symptoms"}],"answerId":"c","explanation":"Migraine prophylaxis is indicated for patients with frequent or disabling migraines to reduce attack frequency and severity.","kind":"recall","origin":"ai"},{"id":"migraine-prophylaxis~ai-1","moduleId":"migraine-prophylaxis","stem":"Which medication is considered first-line for migraine prophylaxis in a patient with hypertension?","options":[{"id":"a","text":"Topiramate"},{"id":"b","text":"Amitriptyline"},{"id":"c","text":"Propranolol"},{"id":"d","text":"Venlafaxine"}],"answerId":"c","explanation":"Propranolol, a beta-blocker, is first-line for migraine prophylaxis, especially in patients with comorbid hypertension.","kind":"recall","origin":"ai"},{"id":"migraine-prophylaxis~ai-2","moduleId":"migraine-prophylaxis","stem":"What is a common side effect of topiramate used for migraine prophylaxis?","options":[{"id":"a","text":"Weight gain"},{"id":"b","text":"Cognitive slowing"},{"id":"c","text":"Hypertension"},{"id":"d","text":"Nausea"}],"answerId":"b","explanation":"Topiramate is known to cause cognitive slowing and weight loss, making it distinct from other migraine prophylactic agents.","kind":"recall","origin":"ai"},{"id":"migraine-prophylaxis~ai-3","moduleId":"migraine-prophylaxis","stem":"A patient with chronic migraine presents with 18 headache days per month. Which treatment is indicated?","options":[{"id":"a","text":"Propranolol"},{"id":"b","text":"OnabotulinumtoxinA"},{"id":"c","text":"Amitriptyline"},{"id":"d","text":"Topiramate"}],"answerId":"b","explanation":"OnabotulinumtoxinA (Botox) is indicated for chronic migraine defined as 15 or more headache days per month.","kind":"recall","origin":"ai"},{"id":"migraine-prophylaxis~ai-4","moduleId":"migraine-prophylaxis","stem":"Which of the following statements about migraine prophylaxis is FALSE?","options":[{"id":"a","text":"Prophylactic medications are taken daily"},{"id":"b","text":"Prophylaxis is effective immediately"},{"id":"c","text":"CGRP monoclonal antibodies are used for prevention"},{"id":"d","text":"Beta-blockers can be used if the patient has hypertension"}],"answerId":"b","explanation":"Prophylactic medications do not provide immediate relief; they require weeks to show effectiveness.","kind":"trap","origin":"ai"},{"id":"migraine-prophylaxis~ai-5","moduleId":"migraine-prophylaxis","stem":"How do CGRP monoclonal antibodies work in migraine prophylaxis?","options":[{"id":"a","text":"Increase cortical excitability"},{"id":"b","text":"Inhibit CGRP signaling"},{"id":"c","text":"Enhance vasodilation"},{"id":"d","text":"Block serotonin receptors"}],"answerId":"b","explanation":"CGRP monoclonal antibodies inhibit CGRP signaling, which is involved in the pathophysiology of migraines.","kind":"mechanism","origin":"ai"},{"id":"migraine-prophylaxis~ai-6","moduleId":"migraine-prophylaxis","stem":"A patient with migraines and depression is being treated with venlafaxine. What is the rationale for this choice?","options":[{"id":"a","text":"Venlafaxine is a first-line acute treatment"},{"id":"b","text":"It addresses both migraines and depression"},{"id":"c","text":"It is a beta-blocker"},{"id":"d","text":"It has no side effects"}],"answerId":"b","explanation":"Venlafaxine is used for migraine prophylaxis when coexisting depression is present, addressing both conditions.","kind":"integration","linkedModuleIds":["migraine-pathophysiology-acute"],"origin":"ai"},{"id":"migraine-prophylaxis~ai-7","moduleId":"migraine-prophylaxis","stem":"Which of the following is a common comorbidity that influences the choice of migraine prophylaxis?","options":[{"id":"a","text":"Asthma"},{"id":"b","text":"Diabetes"},{"id":"c","text":"Hypertension"},{"id":"d","text":"Hypothyroidism"}],"answerId":"c","explanation":"Hypertension is a common comorbidity that influences the selection of beta-blockers for migraine prophylaxis.","kind":"integration","linkedModuleIds":["beta-blockers-ccb-angina"],"origin":"ai"}],"opioid-receptors-mechanism":[{"id":"opioid-receptors-mechanism~ai-0","moduleId":"opioid-receptors-mechanism","stem":"What is the primary mechanism of action for μ-opioid receptors?","options":[{"id":"a","text":"Inhibition of adenylate cyclase"},{"id":"b","text":"Activation of phospholipase C"},{"id":"c","text":"Opening of Na⁺ channels"},{"id":"d","text":"Inhibition of K⁺ channels"}],"answerId":"a","explanation":"μ-opioid receptors are Gi/o-protein-coupled receptors that inhibit adenylate cyclase, leading to decreased cAMP levels and hyperpolarization.","kind":"mechanism","origin":"ai"},{"id":"opioid-receptors-mechanism~ai-1","moduleId":"opioid-receptors-mechanism","stem":"Which of the following is a common side effect of μ-opioid receptor activation?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Miosis"},{"id":"c","text":"Diarrhea"},{"id":"d","text":"Hyperthermia"}],"answerId":"b","explanation":"Activation of μ-opioid receptors typically causes miosis, along with other effects like analgesia and constipation.","kind":"recall","origin":"ai"},{"id":"opioid-receptors-mechanism~ai-2","moduleId":"opioid-receptors-mechanism","stem":"What is the effect of buprenorphine when added to a patient on a full μ-opioid agonist?","options":[{"id":"a","text":"Increased analgesia"},{"id":"b","text":"Decreased respiratory depression"},{"id":"c","text":"Precipitation of withdrawal"},{"id":"d","text":"Enhanced euphoria"}],"answerId":"c","explanation":"Buprenorphine, a partial agonist, can displace the full agonist, leading to decreased receptor activation and precipitating withdrawal symptoms.","kind":"trap","origin":"ai"},{"id":"opioid-receptors-mechanism~ai-3","moduleId":"opioid-receptors-mechanism","stem":"Which opioid receptor is primarily associated with dysphoria and hallucinations?","options":[{"id":"a","text":"μ receptor"},{"id":"b","text":"κ receptor"},{"id":"c","text":"δ receptor"},{"id":"d","text":"NOP receptor"}],"answerId":"b","explanation":"The κ receptor is associated with dysphoria and hallucinations when activated.","kind":"recall","origin":"ai"},{"id":"opioid-receptors-mechanism~ai-4","moduleId":"opioid-receptors-mechanism","stem":"What is the primary clinical use of methadone?","options":[{"id":"a","text":"Acute pain relief"},{"id":"b","text":"Chronic pain management"},{"id":"c","text":"Opioid dependence treatment"},{"id":"d","text":"Anesthesia"}],"answerId":"c","explanation":"Methadone is primarily used in the treatment of opioid dependence due to its long-acting μ-agonist properties.","kind":"recall","origin":"ai"},{"id":"opioid-receptors-mechanism~ai-5","moduleId":"opioid-receptors-mechanism","stem":"How does the mechanism of opioid receptors relate to their effects on pain signaling?","options":[{"id":"a","text":"They enhance neurotransmitter release"},{"id":"b","text":"They inhibit descending pain pathways"},{"id":"c","text":"They hyperpolarize neurons, reducing pain transmission"},{"id":"d","text":"They activate ascending pain pathways"}],"answerId":"c","explanation":"Opioid receptors hyperpolarize neurons, which reduces pain signaling by inhibiting the transmission of nociceptive signals.","kind":"integration","linkedModuleIds":["opioid-effects-toxicity"],"origin":"ai"},{"id":"opioid-receptors-mechanism~ai-6","moduleId":"opioid-receptors-mechanism","stem":"Which of the following best describes the role of endogenous opioids in pain modulation?","options":[{"id":"a","text":"They increase pain perception"},{"id":"b","text":"They act as antagonists at opioid receptors"},{"id":"c","text":"They activate opioid receptors to inhibit pain transmission"},{"id":"d","text":"They exclusively act on δ receptors"}],"answerId":"c","explanation":"Endogenous opioids activate opioid receptors, leading to inhibition of pain transmission and modulation of pain perception.","kind":"integration","linkedModuleIds":["opioid-effects-toxicity"],"origin":"ai"}],"mood-stabilizers-bipolar":[{"id":"mood-stabilizers-bipolar~ai-0","moduleId":"mood-stabilizers-bipolar","stem":"What is the first-line treatment for acute mania in bipolar disorder?","options":[{"id":"a","text":"Valproate"},{"id":"b","text":"Carbamazepine"},{"id":"c","text":"Lithium"},{"id":"d","text":"Lamotrigine"}],"answerId":"c","explanation":"Lithium is the first-line treatment for acute mania due to its efficacy in stabilizing mood.","kind":"recall","origin":"ai"},{"id":"mood-stabilizers-bipolar~ai-1","moduleId":"mood-stabilizers-bipolar","stem":"Which of the following is a common adverse effect of lithium therapy?","options":[{"id":"a","text":"Hyponatremia"},{"id":"b","text":"Tremor"},{"id":"c","text":"Agranulocytosis"},{"id":"d","text":"Serotonin syndrome"}],"answerId":"b","explanation":"Tremor is a well-known side effect of lithium, particularly at therapeutic levels.","kind":"recall","origin":"ai"},{"id":"mood-stabilizers-bipolar~ai-2","moduleId":"mood-stabilizers-bipolar","stem":"What is the mechanism of action of valproate in the treatment of bipolar disorder?","options":[{"id":"a","text":"Inhibition of GSK-3"},{"id":"b","text":"Increased GABA levels"},{"id":"c","text":"Na⁺ channel blockade"},{"id":"d","text":"Dopamine receptor antagonism"}],"answerId":"b","explanation":"Valproate increases GABA levels, which helps stabilize mood in bipolar disorder.","kind":"mechanism","origin":"ai"},{"id":"mood-stabilizers-bipolar~ai-3","moduleId":"mood-stabilizers-bipolar","stem":"A patient on lamotrigine develops a serious rash. What is the most likely diagnosis?","options":[{"id":"a","text":"Stevens-Johnson syndrome"},{"id":"b","text":"Toxic epidermal necrolysis"},{"id":"c","text":"Erythema multiforme"},{"id":"d","text":"Contact dermatitis"}],"answerId":"a","explanation":"A serious rash in a patient taking lamotrigine is indicative of Stevens-Johnson syndrome, a known risk.","kind":"recall","origin":"ai"},{"id":"mood-stabilizers-bipolar~ai-4","moduleId":"mood-stabilizers-bipolar","stem":"Why should antidepressants not be used as monotherapy in bipolar depression?","options":[{"id":"a","text":"They are ineffective in bipolar disorder"},{"id":"b","text":"They can trigger manic episodes"},{"id":"c","text":"They cause severe side effects"},{"id":"d","text":"They worsen depressive symptoms"}],"answerId":"b","explanation":"Antidepressants can precipitate a manic switch in patients with bipolar disorder, making mood stabilizers essential.","kind":"trap","origin":"ai"},{"id":"mood-stabilizers-bipolar~ai-5","moduleId":"mood-stabilizers-bipolar","stem":"Which mood stabilizer is associated with the risk of neural tube defects if used during pregnancy?","options":[{"id":"a","text":"Lithium"},{"id":"b","text":"Valproate"},{"id":"c","text":"Lamotrigine"},{"id":"d","text":"Carbamazepine"}],"answerId":"b","explanation":"Valproate is teratogenic and associated with neural tube defects when used during pregnancy.","kind":"recall","origin":"ai"},{"id":"mood-stabilizers-bipolar~ai-6","moduleId":"mood-stabilizers-bipolar","stem":"How does the mechanism of SSRIs differ from that of mood stabilizers in treating bipolar disorder?","options":[{"id":"a","text":"SSRIs increase serotonin; mood stabilizers stabilize mood"},{"id":"b","text":"SSRIs block Na⁺ channels; mood stabilizers increase GABA"},{"id":"c","text":"SSRIs inhibit GSK-3; mood stabilizers block dopamine receptors"},{"id":"d","text":"SSRIs decrease norepinephrine; mood stabilizers increase glutamate"}],"answerId":"a","explanation":"SSRIs primarily increase serotonin levels, while mood stabilizers aim to stabilize mood without triggering mania.","kind":"integration","linkedModuleIds":["antidepressants-ssri-snri"],"origin":"ai"},{"id":"mood-stabilizers-bipolar~ai-7","moduleId":"mood-stabilizers-bipolar","stem":"Which of the following best describes the relationship between mood stabilizers and atypical antidepressants in bipolar disorder management?","options":[{"id":"a","text":"Both are first-line treatments for mania"},{"id":"b","text":"Mood stabilizers prevent manic switches; atypical antidepressants can be adjunctive"},{"id":"c","text":"Atypical antidepressants are preferred over mood stabilizers"},{"id":"d","text":"Mood stabilizers are only for depressive episodes"}],"answerId":"b","explanation":"Mood stabilizers are essential to prevent manic switches, while atypical antidepressants can be used as adjunctive therapy.","kind":"integration","linkedModuleIds":["tca-maoi-atypical-antidepressants"],"origin":"ai"}],"barbiturates-and-anxiolytics":[{"id":"barbiturates-and-anxiolytics~ai-0","moduleId":"barbiturates-and-anxiolytics","stem":"What is the primary mechanism by which barbiturates exert their effects?","options":[{"id":"a","text":"Inhibit GABA_A receptor activity"},{"id":"b","text":"Increase GABA_A receptor Cl⁻ channel opening duration"},{"id":"c","text":"Block NMDA receptors"},{"id":"d","text":"Enhance serotonin receptor activity"}],"answerId":"b","explanation":"Barbiturates increase the duration of GABA_A Cl⁻ channel opening, leading to their sedative effects.","kind":"mechanism","origin":"ai"},{"id":"barbiturates-and-anxiolytics~ai-1","moduleId":"barbiturates-and-anxiolytics","stem":"Which of the following is a significant risk associated with barbiturate overdose?","options":[{"id":"a","text":"Severe hypertension"},{"id":"b","text":"Respiratory and cardiac depression"},{"id":"c","text":"Seizures"},{"id":"d","text":"Anxiety exacerbation"}],"answerId":"b","explanation":"Barbiturate overdose can lead to respiratory and cardiac depression due to their low therapeutic index.","kind":"clinical","origin":"ai"},{"id":"barbiturates-and-anxiolytics~ai-2","moduleId":"barbiturates-and-anxiolytics","stem":"Which sedative-hypnotic has no available antagonist for overdose reversal?","options":[{"id":"a","text":"Benzodiazepines"},{"id":"b","text":"Z-drugs"},{"id":"c","text":"Barbiturates"},{"id":"d","text":"Buspirone"}],"answerId":"c","explanation":"Barbiturates have no specific antagonist; supportive care is required in case of overdose.","kind":"trap","origin":"ai"},{"id":"barbiturates-and-anxiolytics~ai-3","moduleId":"barbiturates-and-anxiolytics","stem":"Which of the following is a contraindication for barbiturate use?","options":[{"id":"a","text":"Chronic anxiety disorders"},{"id":"b","text":"Acute intermittent porphyria"},{"id":"c","text":"Insomnia"},{"id":"d","text":"Severe depression"}],"answerId":"b","explanation":"Barbiturates are contraindicated in acute intermittent porphyria as they induce ALA synthase, worsening the condition.","kind":"recall","origin":"ai"},{"id":"barbiturates-and-anxiolytics~ai-4","moduleId":"barbiturates-and-anxiolytics","stem":"Buspirone is primarily indicated for which condition?","options":[{"id":"a","text":"Acute insomnia"},{"id":"b","text":"Generalized anxiety disorder"},{"id":"c","text":"Panic disorder"},{"id":"d","text":"Severe depression"}],"answerId":"b","explanation":"Buspirone is used for generalized anxiety disorder and has a slow onset of action.","kind":"recall","origin":"ai"},{"id":"barbiturates-and-anxiolytics~ai-5","moduleId":"barbiturates-and-anxiolytics","stem":"How does the mechanism of action of buspirone differ from that of barbiturates?","options":[{"id":"a","text":"Buspirone enhances GABA_A activity"},{"id":"b","text":"Buspirone is a 5-HT1A partial agonist"},{"id":"c","text":"Buspirone directly opens Cl⁻ channels"},{"id":"d","text":"Buspirone induces CYP450 enzymes"}],"answerId":"b","explanation":"Buspirone acts as a 5-HT1A partial agonist, unlike barbiturates which enhance GABA_A receptor activity.","kind":"mechanism","origin":"ai"},{"id":"barbiturates-and-anxiolytics~ai-6","moduleId":"barbiturates-and-anxiolytics","stem":"Which of the following statements correctly contrasts barbiturates with benzodiazepines?","options":[{"id":"a","text":"Both have high therapeutic indices"},{"id":"b","text":"Benzodiazepines have no risk of dependence"},{"id":"c","text":"Barbiturates have a higher risk of overdose"},{"id":"d","text":"Both can be reversed by flumazenil"}],"answerId":"c","explanation":"Barbiturates have a lower therapeutic index and a higher risk of overdose compared to benzodiazepines.","kind":"trap","origin":"ai"},{"id":"barbiturates-and-anxiolytics~ai-7","moduleId":"barbiturates-and-anxiolytics","stem":"What is a common pharmacodynamic effect of both barbiturates and benzodiazepines?","options":[{"id":"a","text":"Directly inhibit serotonin receptors"},{"id":"b","text":"Enhance GABAergic transmission"},{"id":"c","text":"Block adrenergic receptors"},{"id":"d","text":"Increase dopamine release"}],"answerId":"b","explanation":"Both barbiturates and benzodiazepines enhance GABAergic transmission, leading to their sedative effects.","kind":"integration","linkedModuleIds":["sedative-hypnotics-benzodiazepines"],"origin":"ai"},{"id":"barbiturates-and-anxiolytics~ai-8","moduleId":"barbiturates-and-anxiolytics","stem":"In a patient with acute intermittent porphyria, which medication should be avoided?","options":[{"id":"a","text":"Buspirone"},{"id":"b","text":"Phenobarbital"},{"id":"c","text":"Alprazolam"},{"id":"d","text":"Diazepam"}],"answerId":"b","explanation":"Phenobarbital should be avoided in acute intermittent porphyria as it induces ALA synthase, worsening the condition.","kind":"integration","linkedModuleIds":["colon-molecular-workup-therapy"],"origin":"ai"}],"subacute-chronic-meningitis":[{"id":"subacute-chronic-meningitis~ai-0","moduleId":"subacute-chronic-meningitis","stem":"What is the most characteristic CSF finding in tuberculous meningitis?","options":[{"id":"a","text":"High lymphocyte count"},{"id":"b","text":"Low glucose"},{"id":"c","text":"High eosinophil count"},{"id":"d","text":"Normal protein level"}],"answerId":"b","explanation":"Tuberculous meningitis typically presents with a lymphocytic predominance, very high protein, and low glucose in the CSF.","kind":"recall","origin":"ai"},{"id":"subacute-chronic-meningitis~ai-1","moduleId":"subacute-chronic-meningitis","stem":"Which organism is primarily responsible for cryptococcal meningitis?","options":[{"id":"a","text":"Corynebacterium diphtheriae"},{"id":"b","text":"Cryptococcus neoformans"},{"id":"c","text":"Neisseria meningitidis"},{"id":"d","text":"Streptococcus pneumoniae"}],"answerId":"b","explanation":"Cryptococcus neoformans is the causative agent of cryptococcal meningitis, especially in immunocompromised individuals.","kind":"recall","origin":"ai"},{"id":"subacute-chronic-meningitis~ai-2","moduleId":"subacute-chronic-meningitis","stem":"What is the mechanism by which Cryptococcus neoformans causes increased intracranial pressure?","options":[{"id":"a","text":"Direct invasion of brain tissue"},{"id":"b","text":"Production of a thick capsule"},{"id":"c","text":"Release of neurotoxins"},{"id":"d","text":"Induction of inflammatory cytokines"}],"answerId":"b","explanation":"Cryptococcus neoformans has a thick capsule that contributes to increased intracranial pressure by obstructing CSF flow.","kind":"mechanism","origin":"ai"},{"id":"subacute-chronic-meningitis~ai-3","moduleId":"subacute-chronic-meningitis","stem":"A patient presents with eosinophilic meningitis after consuming raw snails. What is the most likely causative agent?","options":[{"id":"a","text":"Angiostrongylus cantonensis"},{"id":"b","text":"Gnathostoma spinigerum"},{"id":"c","text":"Toxocara canis"},{"id":"d","text":"Strongyloides stercoralis"}],"answerId":"a","explanation":"Angiostrongylus cantonensis is known to cause eosinophilic meningitis, particularly after ingestion of raw snails.","kind":"recall","origin":"ai"},{"id":"subacute-chronic-meningitis~ai-4","moduleId":"subacute-chronic-meningitis","stem":"In managing cryptococcal meningitis, what is a critical component of treatment aside from antifungal therapy?","options":[{"id":"a","text":"Antibiotics"},{"id":"b","text":"Aggressive management of intracranial pressure"},{"id":"c","text":"Corticosteroids alone"},{"id":"d","text":"Surgical intervention"}],"answerId":"b","explanation":"Aggressive management of raised intracranial pressure is essential in cryptococcal meningitis to prevent complications.","kind":"trap","origin":"ai"},{"id":"subacute-chronic-meningitis~ai-5","moduleId":"subacute-chronic-meningitis","stem":"A patient with HIV presents with meningitis and high opening pressure. What test is most sensitive for diagnosing cryptococcal meningitis?","options":[{"id":"a","text":"CSF culture"},{"id":"b","text":"India ink preparation"},{"id":"c","text":"Cryptococcal antigen test"},{"id":"d","text":"CSF cell count"}],"answerId":"c","explanation":"The cryptococcal antigen test is highly sensitive and specific for diagnosing cryptococcal meningitis.","kind":"recall","origin":"ai"},{"id":"subacute-chronic-meningitis~ai-6","moduleId":"subacute-chronic-meningitis","stem":"How does eosinophilic meningitis differ from tuberculous meningitis in CSF findings?","options":[{"id":"a","text":"Higher protein levels"},{"id":"b","text":"Presence of eosinophils"},{"id":"c","text":"Lower glucose levels"},{"id":"d","text":"Higher lymphocyte count"}],"answerId":"b","explanation":"Eosinophilic meningitis is characterized by a predominance of eosinophils in the CSF, unlike tuberculous meningitis.","kind":"integration","linkedModuleIds":["angiostrongyliasis-eosinophilic-meningitis"],"origin":"ai"},{"id":"subacute-chronic-meningitis~ai-7","moduleId":"subacute-chronic-meningitis","stem":"Which of the following findings would most likely indicate tuberculous meningitis rather than cryptococcal meningitis?","options":[{"id":"a","text":"Very high protein with low glucose"},{"id":"b","text":"Presence of a thick capsule"},{"id":"c","text":"High eosinophil count"},{"id":"d","text":"Normal lymphocyte count"}],"answerId":"a","explanation":"Very high protein with low glucose is characteristic of tuberculous meningitis, while cryptococcal meningitis typically has normal glucose.","kind":"integration","linkedModuleIds":["bacterial-meningitis"],"origin":"ai"}],"bacterial-meningitis":[{"id":"bacterial-meningitis~ai-0","moduleId":"bacterial-meningitis","stem":"What is the most common causative organism of acute bacterial meningitis in adults?","options":[{"id":"a","text":"Streptococcus pneumoniae"},{"id":"b","text":"Neisseria meningitidis"},{"id":"c","text":"Haemophilus influenzae"},{"id":"d","text":"Listeria monocytogenes"}],"answerId":"a","explanation":"Streptococcus pneumoniae is the most common organism responsible for acute bacterial meningitis in adults.","kind":"recall","origin":"ai"},{"id":"bacterial-meningitis~ai-1","moduleId":"bacterial-meningitis","stem":"Which CSF finding is characteristic of bacterial meningitis?","options":[{"id":"a","text":"Increased lymphocytes, normal glucose"},{"id":"b","text":"Increased neutrophils, elevated protein, low glucose"},{"id":"c","text":"Normal cell count, normal glucose"},{"id":"d","text":"Increased eosinophils, low protein"}],"answerId":"b","explanation":"Bacterial meningitis is characterized by increased neutrophils, elevated protein, and low glucose in the CSF.","kind":"recall","origin":"ai"},{"id":"bacterial-meningitis~ai-2","moduleId":"bacterial-meningitis","stem":"A patient presents with fever, neck stiffness, and altered mental status. Which sign would most likely be positive?","options":[{"id":"a","text":"Kernig's sign"},{"id":"b","text":"Babinski's sign"},{"id":"c","text":"Hoffman's sign"},{"id":"d","text":"Romberg test"}],"answerId":"a","explanation":"Kernig's sign is a classic sign of meningeal irritation, commonly seen in cases of meningitis.","kind":"clinical","origin":"ai"},{"id":"bacterial-meningitis~ai-3","moduleId":"bacterial-meningitis","stem":"In bacterial meningitis, what is the primary mechanism leading to the classic triad of symptoms?","options":[{"id":"a","text":"Viral invasion of neurons"},{"id":"b","text":"Bacterial invasion of the subarachnoid space"},{"id":"c","text":"Toxin production by bacteria"},{"id":"d","text":"Autoimmune response"}],"answerId":"b","explanation":"Bacterial invasion of the subarachnoid space leads to inflammation, resulting in the classic triad of symptoms.","kind":"mechanism","origin":"ai"},{"id":"bacterial-meningitis~ai-4","moduleId":"bacterial-meningitis","stem":"Which of the following statements about CSF glucose levels in meningitis is correct?","options":[{"id":"a","text":"Low CSF glucose confirms bacterial meningitis"},{"id":"b","text":"Low CSF glucose is exclusive to bacterial meningitis"},{"id":"c","text":"Low CSF glucose can occur in both bacterial and TB meningitis"},{"id":"d","text":"Low CSF glucose is not relevant in meningitis diagnosis"}],"answerId":"c","explanation":"Low CSF glucose can occur in both bacterial and TB meningitis; the predominant white-cell type distinguishes them.","kind":"trap","origin":"ai"},{"id":"bacterial-meningitis~ai-5","moduleId":"bacterial-meningitis","stem":"A patient with suspected bacterial meningitis is being treated with ceftriaxone and vancomycin. What adjunctive therapy should be considered?","options":[{"id":"a","text":"Dexamethasone"},{"id":"b","text":"Acyclovir"},{"id":"c","text":"Amphotericin B"},{"id":"d","text":"Rifampin"}],"answerId":"a","explanation":"Dexamethasone is recommended as adjunctive therapy in suspected pneumococcal meningitis to reduce neurologic sequelae.","kind":"recall","origin":"ai"},{"id":"bacterial-meningitis~ai-6","moduleId":"bacterial-meningitis","stem":"Which organism is most likely responsible for meningitis in an immunocompromised patient?","options":[{"id":"a","text":"Streptococcus pneumoniae"},{"id":"b","text":"Neisseria meningitidis"},{"id":"c","text":"Listeria monocytogenes"},{"id":"d","text":"Cryptococcus neoformans"}],"answerId":"c","explanation":"Listeria monocytogenes is a common cause of meningitis in immunocompromised patients, particularly the elderly.","kind":"recall","origin":"ai"},{"id":"bacterial-meningitis~ai-7","moduleId":"bacterial-meningitis","stem":"How does the CSF profile in tuberculous meningitis differ from that in bacterial meningitis?","options":[{"id":"a","text":"Higher glucose, lower protein"},{"id":"b","text":"Higher lymphocytes, higher protein, lower glucose"},{"id":"c","text":"Higher neutrophils, normal glucose"},{"id":"d","text":"Normal cell count, elevated glucose"}],"answerId":"b","explanation":"Tuberculous meningitis typically shows higher lymphocytes, higher protein, and lower glucose compared to bacterial meningitis.","kind":"integration","linkedModuleIds":["subacute-chronic-meningitis"],"origin":"ai"},{"id":"bacterial-meningitis~ai-8","moduleId":"bacterial-meningitis","stem":"In a patient with encephalitis, which CSF finding would help differentiate it from bacterial meningitis?","options":[{"id":"a","text":"Increased neutrophils, low glucose"},{"id":"b","text":"Increased lymphocytes, normal glucose"},{"id":"c","text":"Decreased protein, normal glucose"},{"id":"d","text":"Increased eosinophils, low glucose"}],"answerId":"b","explanation":"Increased lymphocytes with normal glucose is characteristic of viral encephalitis, distinguishing it from bacterial meningitis.","kind":"integration","linkedModuleIds":["encephalitis-myelitis"],"origin":"ai"}],"atypical-antipsychotic-agents":[{"id":"atypical-antipsychotic-agents~ai-0","moduleId":"atypical-antipsychotic-agents","stem":"Which atypical antipsychotic is primarily used for treatment-resistant schizophrenia?","options":[{"id":"a","text":"Olanzapine"},{"id":"b","text":"Quetiapine"},{"id":"c","text":"Clozapine"},{"id":"d","text":"Risperidone"}],"answerId":"c","explanation":"Clozapine is specifically indicated for treatment-resistant schizophrenia due to its unique efficacy profile.","kind":"recall","origin":"ai"},{"id":"atypical-antipsychotic-agents~ai-1","moduleId":"atypical-antipsychotic-agents","stem":"What is a major side effect of Olanzapine?","options":[{"id":"a","text":"Extrapyramidal symptoms"},{"id":"b","text":"Agranulocytosis"},{"id":"c","text":"Weight gain"},{"id":"d","text":"QT prolongation"}],"answerId":"c","explanation":"Olanzapine is associated with significant weight gain and metabolic syndrome.","kind":"recall","origin":"ai"},{"id":"atypical-antipsychotic-agents~ai-2","moduleId":"atypical-antipsychotic-agents","stem":"Which mechanism underlies the risk of agranulocytosis with Clozapine?","options":[{"id":"a","text":"Dopamine receptor blockade"},{"id":"b","text":"Histamine receptor blockade"},{"id":"c","text":"Bone marrow suppression"},{"id":"d","text":"Serotonin receptor modulation"}],"answerId":"c","explanation":"Clozapine can cause bone marrow suppression, leading to agranulocytosis, necessitating regular CBC monitoring.","kind":"mechanism","origin":"ai"},{"id":"atypical-antipsychotic-agents~ai-3","moduleId":"atypical-antipsychotic-agents","stem":"A patient on Ziprasidone presents with an ECG showing QT prolongation. What is the most appropriate management?","options":[{"id":"a","text":"Discontinue Ziprasidone"},{"id":"b","text":"Add a beta-blocker"},{"id":"c","text":"Monitor ECG and electrolytes"},{"id":"d","text":"Switch to Clozapine"}],"answerId":"c","explanation":"Monitoring ECG and electrolytes is essential to manage the risk of arrhythmias associated with QT prolongation.","kind":"clinical","origin":"ai"},{"id":"atypical-antipsychotic-agents~ai-4","moduleId":"atypical-antipsychotic-agents","stem":"Which of the following statements about Clozapine is true?","options":[{"id":"a","text":"It is a first-line treatment for schizophrenia."},{"id":"b","text":"It has a low risk of metabolic side effects."},{"id":"c","text":"Regular CBC monitoring is required."},{"id":"d","text":"It is less effective than typical antipsychotics."}],"answerId":"c","explanation":"Clozapine requires regular CBC monitoring due to the risk of agranulocytosis, making it a second-line treatment.","kind":"trap","origin":"ai"},{"id":"atypical-antipsychotic-agents~ai-5","moduleId":"atypical-antipsychotic-agents","stem":"How does the mechanism of action of atypical antipsychotics differ from typical antipsychotics?","options":[{"id":"a","text":"Atypicals primarily block serotonin receptors"},{"id":"b","text":"Atypicals have no dopamine receptor activity"},{"id":"c","text":"Typical antipsychotics are more effective"},{"id":"d","text":"Atypicals cause more EPS than typicals"}],"answerId":"a","explanation":"Atypical antipsychotics primarily block serotonin receptors in addition to dopamine receptors, reducing the risk of EPS.","kind":"mechanism","origin":"ai"},{"id":"atypical-antipsychotic-agents~ai-6","moduleId":"atypical-antipsychotic-agents","stem":"Which neurotransmitter is primarily affected by atypical antipsychotics, leading to their therapeutic effects?","options":[{"id":"a","text":"Acetylcholine"},{"id":"b","text":"Dopamine"},{"id":"c","text":"Serotonin"},{"id":"d","text":"Norepinephrine"}],"answerId":"b","explanation":"Atypical antipsychotics primarily target dopamine receptors to alleviate symptoms of psychosis.","kind":"integration","linkedModuleIds":["neurotransmitters-types-lifecycle"],"origin":"ai"},{"id":"atypical-antipsychotic-agents~ai-7","moduleId":"atypical-antipsychotic-agents","stem":"What is the relationship between dopamine pathways and the side effects of antipsychotics?","options":[{"id":"a","text":"Dopamine antagonism causes metabolic syndrome"},{"id":"b","text":"Dopamine blockade leads to EPS"},{"id":"c","text":"Dopamine modulation reduces weight gain"},{"id":"d","text":"Dopamine enhances efficacy of all antipsychotics"}],"answerId":"b","explanation":"Dopamine blockade in certain pathways is responsible for the extrapyramidal symptoms (EPS) seen with antipsychotic use.","kind":"integration","linkedModuleIds":["antipsychotics-dopamine-eps"],"origin":"ai"}],"amino-acids-proteins-structure":[{"id":"amino-acids-proteins-structure~ai-0","moduleId":"amino-acids-proteins-structure","stem":"Which amino acid is considered the '21st' amino acid due to its unique coding mechanism?","options":[{"id":"a","text":"Selenocysteine"},{"id":"b","text":"Cysteine"},{"id":"c","text":"Tyrosine"},{"id":"d","text":"Glutamine"}],"answerId":"a","explanation":"Selenocysteine is incorporated into proteins via a recoded UGA codon, distinguishing it from the standard 20 amino acids.","kind":"recall","origin":"ai"},{"id":"amino-acids-proteins-structure~ai-1","moduleId":"amino-acids-proteins-structure","stem":"What type of bond stabilizes the tertiary structure of proteins?","options":[{"id":"a","text":"Ionic bonds"},{"id":"b","text":"Peptide bonds"},{"id":"c","text":"Disulfide bonds"},{"id":"d","text":"Hydrogen bonds"}],"answerId":"c","explanation":"Disulfide bonds formed between cysteine residues play a crucial role in stabilizing the three-dimensional structure of proteins.","kind":"mechanism","origin":"ai"},{"id":"amino-acids-proteins-structure~ai-2","moduleId":"amino-acids-proteins-structure","stem":"Which of the following statements about protein denaturation is correct?","options":[{"id":"a","text":"Denaturation breaks peptide bonds."},{"id":"b","text":"Denaturation alters the primary sequence."},{"id":"c","text":"Denaturation disrupts non-covalent interactions."},{"id":"d","text":"Denaturation is irreversible for all proteins."}],"answerId":"c","explanation":"Denaturation disrupts non-covalent interactions such as hydrogen bonds and hydrophobic interactions, but does not break peptide bonds.","kind":"trap","origin":"ai"},{"id":"amino-acids-proteins-structure~ai-3","moduleId":"amino-acids-proteins-structure","stem":"In electrophoresis, which property of proteins is primarily utilized for their separation?","options":[{"id":"a","text":"Molecular weight"},{"id":"b","text":"Charge"},{"id":"c","text":"Hydrophobicity"},{"id":"d","text":"Solubility"}],"answerId":"b","explanation":"Electrophoresis separates proteins based on their net charge at a given pH, allowing for differentiation based on their R-group characteristics.","kind":"recall","origin":"ai"},{"id":"amino-acids-proteins-structure~ai-4","moduleId":"amino-acids-proteins-structure","stem":"Which level of protein structure is characterized by the sequence of amino acids?","options":[{"id":"a","text":"Primary structure"},{"id":"b","text":"Secondary structure"},{"id":"c","text":"Tertiary structure"},{"id":"d","text":"Quaternary structure"}],"answerId":"a","explanation":"The primary structure of a protein refers to the linear sequence of amino acids that make up the polypeptide chain.","kind":"recall","origin":"ai"},{"id":"amino-acids-proteins-structure~ai-5","moduleId":"amino-acids-proteins-structure","stem":"How does the structure of collagen relate to its function in connective tissues?","options":[{"id":"a","text":"It forms a rigid structure."},{"id":"b","text":"It is highly soluble in water."},{"id":"c","text":"It provides tensile strength due to its triple helix."},{"id":"d","text":"It has a globular shape."}],"answerId":"c","explanation":"Collagen's triple helix structure provides tensile strength and structural support, making it essential for connective tissues.","kind":"integration","linkedModuleIds":["collagen-elastin"],"origin":"ai"},{"id":"amino-acids-proteins-structure~ai-6","moduleId":"amino-acids-proteins-structure","stem":"What is the primary consequence of a mutation that leads to the misfolding of a protein, such as in sickle cell disease?","options":[{"id":"a","text":"Increased solubility of hemoglobin"},{"id":"b","text":"Altered oxygen transport capacity"},{"id":"c","text":"Enhanced enzymatic activity"},{"id":"d","text":"Improved structural integrity"}],"answerId":"b","explanation":"In sickle cell disease, a mutation causes hemoglobin to misfold, leading to altered oxygen transport capacity and sickle-shaped red blood cells.","kind":"integration","linkedModuleIds":["hemoglobin-myoglobin"],"origin":"ai"}],"enzyme-kinetics":[{"id":"enzyme-kinetics~ai-0","moduleId":"enzyme-kinetics","stem":"What does a high Km value indicate about an enzyme's affinity for its substrate?","options":[{"id":"a","text":"High affinity for substrate"},{"id":"b","text":"Low affinity for substrate"},{"id":"c","text":"Optimal substrate concentration"},{"id":"d","text":"Increased enzyme concentration"}],"answerId":"b","explanation":"A high Km indicates that a higher substrate concentration is needed to reach half-maximal velocity, reflecting low affinity.","kind":"recall","origin":"ai"},{"id":"enzyme-kinetics~ai-1","moduleId":"enzyme-kinetics","stem":"In Michaelis-Menten kinetics, what happens to the reaction rate as substrate concentration increases beyond Km?","options":[{"id":"a","text":"It increases linearly"},{"id":"b","text":"It decreases"},{"id":"c","text":"It remains constant"},{"id":"d","text":"It becomes first-order"}],"answerId":"c","explanation":"At substrate concentrations much greater than Km, the reaction rate becomes zero-order and remains constant.","kind":"mechanism","origin":"ai"},{"id":"enzyme-kinetics~ai-2","moduleId":"enzyme-kinetics","stem":"Which of the following is true regarding the Lineweaver-Burk plot?","options":[{"id":"a","text":"Slope is equal to Vmax/Km"},{"id":"b","text":"Y-intercept is equal to Km"},{"id":"c","text":"X-intercept is equal to -1/Vmax"},{"id":"d","text":"Y-intercept is equal to 1/Vmax"}],"answerId":"d","explanation":"The y-intercept of the Lineweaver-Burk plot represents 1/Vmax.","kind":"recall","origin":"ai"},{"id":"enzyme-kinetics~ai-3","moduleId":"enzyme-kinetics","stem":"A researcher observes that an enzyme's activity sharply declines above a certain temperature. What is the most likely reason?","options":[{"id":"a","text":"Increased substrate concentration"},{"id":"b","text":"Enzyme denaturation"},{"id":"c","text":"Increased Km"},{"id":"d","text":"Decreased Vmax"}],"answerId":"b","explanation":"Enzymes typically denature at high temperatures, leading to a sharp decline in activity.","kind":"mechanism","origin":"ai"},{"id":"enzyme-kinetics~ai-4","moduleId":"enzyme-kinetics","stem":"In the context of enzyme kinetics, what does kcat measure?","options":[{"id":"a","text":"Substrate concentration"},{"id":"b","text":"Enzyme concentration"},{"id":"c","text":"Turnover number"},{"id":"d","text":"Affinity for substrate"}],"answerId":"c","explanation":"kcat, or turnover number, measures the number of substrate molecules converted to product per enzyme per second.","kind":"recall","origin":"ai"},{"id":"enzyme-kinetics~ai-5","moduleId":"enzyme-kinetics","stem":"How does the presence of a competitive inhibitor affect Km and Vmax?","options":[{"id":"a","text":"Increases Km, decreases Vmax"},{"id":"b","text":"Decreases Km, increases Vmax"},{"id":"c","text":"Increases Km, no change in Vmax"},{"id":"d","text":"No change in Km, decreases Vmax"}],"answerId":"c","explanation":"Competitive inhibitors increase Km (lower affinity) but do not affect Vmax.","kind":"trap","origin":"ai"},{"id":"enzyme-kinetics~ai-6","moduleId":"enzyme-kinetics","stem":"How can enzyme kinetics be applied to interpret cardiac biomarkers in acute coronary syndrome?","options":[{"id":"a","text":"To determine enzyme concentration only"},{"id":"b","text":"To assess substrate availability"},{"id":"c","text":"To evaluate enzyme activity changes"},{"id":"d","text":"To measure Km values directly"}],"answerId":"c","explanation":"Understanding enzyme kinetics helps interpret changes in enzyme activity related to cardiac biomarkers in acute coronary syndrome.","kind":"integration","linkedModuleIds":["cardiac-biomarkers-acs"],"origin":"ai"},{"id":"enzyme-kinetics~ai-7","moduleId":"enzyme-kinetics","stem":"Which coenzyme is essential for the activity of many dehydrogenases, influencing enzyme kinetics?","options":[{"id":"a","text":"NAD+"},{"id":"b","text":"FAD"},{"id":"c","text":"CoA"},{"id":"d","text":"Biotin"}],"answerId":"a","explanation":"NAD+ is a crucial coenzyme for many dehydrogenases, affecting their kinetics and overall metabolic pathways.","kind":"integration","linkedModuleIds":["coenzymes-cofactors"],"origin":"ai"}],"enzyme-inhibition-regulation":[{"id":"enzyme-inhibition-regulation~ai-0","moduleId":"enzyme-inhibition-regulation","stem":"What effect does a competitive inhibitor have on Km and Vmax?","options":[{"id":"a","text":"↑ Km, unchanged Vmax"},{"id":"b","text":"↑ Vmax, unchanged Km"},{"id":"c","text":"Unchanged Km, ↓ Vmax"},{"id":"d","text":"Unchanged Km, unchanged Vmax"}],"answerId":"a","explanation":"A competitive inhibitor increases Km (decreases affinity) while Vmax remains unchanged because the maximum reaction rate can still be achieved with sufficient substrate.","kind":"recall","origin":"ai"},{"id":"enzyme-inhibition-regulation~ai-1","moduleId":"enzyme-inhibition-regulation","stem":"Which of the following statements about noncompetitive inhibition is true?","options":[{"id":"a","text":"Inhibition can be overcome by increasing substrate concentration"},{"id":"b","text":"Vmax is decreased, Km remains unchanged"},{"id":"c","text":"It binds only to the active site"},{"id":"d","text":"It increases the enzyme's affinity for the substrate"}],"answerId":"b","explanation":"Noncompetitive inhibitors decrease Vmax without affecting Km, as they bind to an allosteric site instead of the active site.","kind":"recall","origin":"ai"},{"id":"enzyme-inhibition-regulation~ai-2","moduleId":"enzyme-inhibition-regulation","stem":"Which enzyme is activated by irreversible cleavage from its zymogen form?","options":[{"id":"a","text":"Trypsinogen"},{"id":"b","text":"Chymotrypsinogen"},{"id":"c","text":"Prothrombin"},{"id":"d","text":"Pepsinogen"}],"answerId":"a","explanation":"Trypsinogen is activated to trypsin by enteropeptidase through irreversible cleavage.","kind":"recall","origin":"ai"},{"id":"enzyme-inhibition-regulation~ai-3","moduleId":"enzyme-inhibition-regulation","stem":"A patient presents with elevated serum ALT and AST levels. What does this indicate?","options":[{"id":"a","text":"Increased enzyme activity"},{"id":"b","text":"Enzyme leakage from damaged tissue"},{"id":"c","text":"Competitive inhibition"},{"id":"d","text":"Noncompetitive inhibition"}],"answerId":"b","explanation":"Elevated serum ALT and AST levels indicate enzyme leakage from damaged liver tissue, not inhibition.","kind":"clinical","origin":"ai"},{"id":"enzyme-inhibition-regulation~ai-4","moduleId":"enzyme-inhibition-regulation","stem":"Which statement best describes feedback inhibition?","options":[{"id":"a","text":"End product activates an early enzyme"},{"id":"b","text":"End product inhibits an early enzyme"},{"id":"c","text":"Substrate concentration affects enzyme activity"},{"id":"d","text":"Inhibitor binds at the active site"}],"answerId":"b","explanation":"Feedback inhibition occurs when the end product of a metabolic pathway inhibits an enzyme involved in its synthesis.","kind":"recall","origin":"ai"},{"id":"enzyme-inhibition-regulation~ai-5","moduleId":"enzyme-inhibition-regulation","stem":"How does the presence of a competitive inhibitor affect the efficacy of coenzymes?","options":[{"id":"a","text":"Increases coenzyme activity"},{"id":"b","text":"Decreases coenzyme activity"},{"id":"c","text":"No effect on coenzyme activity"},{"id":"d","text":"Coenzymes become competitive inhibitors"}],"answerId":"b","explanation":"Competitive inhibitors can decrease the overall efficacy of coenzymes by reducing the enzyme's activity at the active site.","kind":"integration","linkedModuleIds":["coenzymes-cofactors"],"origin":"ai"},{"id":"enzyme-inhibition-regulation~ai-6","moduleId":"enzyme-inhibition-regulation","stem":"Which mechanism of enzyme regulation is primarily affected by phosphorylation?","options":[{"id":"a","text":"Competitive inhibition"},{"id":"b","text":"Allosteric regulation"},{"id":"c","text":"Covalent modification"},{"id":"d","text":"Zymogen activation"}],"answerId":"c","explanation":"Phosphorylation is a form of covalent modification that can activate or deactivate enzymes.","kind":"integration","linkedModuleIds":["enzyme-catalysis-classification"],"origin":"ai"},{"id":"enzyme-inhibition-regulation~ai-7","moduleId":"enzyme-inhibition-regulation","stem":"What is the primary mechanism by which noncompetitive inhibitors affect enzyme kinetics?","options":[{"id":"a","text":"Increase Km"},{"id":"b","text":"Decrease Vmax"},{"id":"c","text":"Increase Vmax"},{"id":"d","text":"Decrease Km"}],"answerId":"b","explanation":"Noncompetitive inhibitors decrease Vmax without affecting Km, as they do not compete with the substrate for the active site.","kind":"trap","origin":"ai"}],"encephalitis-myelitis":[{"id":"encephalitis-myelitis~ai-0","moduleId":"encephalitis-myelitis","stem":"What is the most common cause of sporadic viral encephalitis?","options":[{"id":"a","text":"West Nile Virus"},{"id":"b","text":"Cytomegalovirus"},{"id":"c","text":"Herpes Simplex Virus type 1"},{"id":"d","text":"Enterovirus"}],"answerId":"c","explanation":"Herpes Simplex Virus type 1 is the most common cause of sporadic viral encephalitis, particularly affecting the temporal lobes.","kind":"recall","origin":"ai"},{"id":"encephalitis-myelitis~ai-1","moduleId":"encephalitis-myelitis","stem":"Which MRI finding is characteristic of HSV-1 encephalitis?","options":[{"id":"a","text":"Bilateral frontal lobe edema"},{"id":"b","text":"Temporal lobe abnormalities"},{"id":"c","text":"Cerebellar atrophy"},{"id":"d","text":"Basal ganglia calcifications"}],"answerId":"b","explanation":"Temporal lobe abnormalities on MRI are characteristic of HSV-1 encephalitis.","kind":"recall","origin":"ai"},{"id":"encephalitis-myelitis~ai-2","moduleId":"encephalitis-myelitis","stem":"A 25-year-old woman presents with psychosis, seizures, and movement disorders. Which antibody is likely involved?","options":[{"id":"a","text":"Anti-GAD65"},{"id":"b","text":"Anti-NMDAR"},{"id":"c","text":"Anti-LGI1"},{"id":"d","text":"Anti-MuSK"}],"answerId":"b","explanation":"Anti-NMDAR antibodies are associated with autoimmune encephalitis presenting with psychiatric symptoms and seizures.","kind":"clinical","origin":"ai"},{"id":"encephalitis-myelitis~ai-3","moduleId":"encephalitis-myelitis","stem":"What is the appropriate initial treatment for suspected HSV encephalitis?","options":[{"id":"a","text":"Oral acyclovir"},{"id":"b","text":"IV acyclovir"},{"id":"c","text":"Steroids"},{"id":"d","text":"Observation"}],"answerId":"b","explanation":"Empiric IV acyclovir should be started immediately in suspected HSV encephalitis to prevent irreversible damage.","kind":"trap","origin":"ai"},{"id":"encephalitis-myelitis~ai-4","moduleId":"encephalitis-myelitis","stem":"A patient presents with bilateral weakness and a sensory level. What is the most likely diagnosis?","options":[{"id":"a","text":"Multiple sclerosis"},{"id":"b","text":"Transverse myelitis"},{"id":"c","text":"Guillain-Barré syndrome"},{"id":"d","text":"Amyotrophic lateral sclerosis"}],"answerId":"b","explanation":"Bilateral weakness with a sensory level is indicative of transverse myelitis.","kind":"recall","origin":"ai"},{"id":"encephalitis-myelitis~ai-5","moduleId":"encephalitis-myelitis","stem":"In a patient with suspected encephalitis, which CSF finding would most likely indicate a viral etiology?","options":[{"id":"a","text":"Elevated protein with neutrophilic pleocytosis"},{"id":"b","text":"Elevated protein with lymphocytic pleocytosis"},{"id":"c","text":"Normal protein with neutrophilic pleocytosis"},{"id":"d","text":"Normal protein with lymphocytic pleocytosis"}],"answerId":"b","explanation":"Elevated protein with lymphocytic pleocytosis is typical of viral infections, including encephalitis.","kind":"mechanism","origin":"ai"},{"id":"encephalitis-myelitis~ai-6","moduleId":"encephalitis-myelitis","stem":"How does transverse myelitis differ from bacterial meningitis in clinical presentation?","options":[{"id":"a","text":"Presence of fever"},{"id":"b","text":"Bilateral motor deficits"},{"id":"c","text":"Neck stiffness"},{"id":"d","text":"Photophobia"}],"answerId":"b","explanation":"Transverse myelitis presents with bilateral motor deficits and sensory levels, while bacterial meningitis typically presents with fever and neck stiffness.","kind":"integration","linkedModuleIds":["bacterial-meningitis"],"origin":"ai"},{"id":"encephalitis-myelitis~ai-7","moduleId":"encephalitis-myelitis","stem":"Which of the following conditions can lead to similar CSF findings as viral encephalitis?","options":[{"id":"a","text":"Bacterial meningitis"},{"id":"b","text":"Tuberculous meningitis"},{"id":"c","text":"Cryptococcal meningitis"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"All listed conditions can present with elevated protein and lymphocytic pleocytosis, complicating diagnosis.","kind":"integration","linkedModuleIds":["subacute-chronic-meningitis"],"origin":"ai"}],"nucleotides-structure-roles":[{"id":"nucleotides-structure-roles~ai-0","moduleId":"nucleotides-structure-roles","stem":"Which of the following correctly defines a nucleotide?","options":[{"id":"a","text":"Nitrogenous base + pentose sugar + phosphate"},{"id":"b","text":"Nitrogenous base + pentose sugar"},{"id":"c","text":"Pentose sugar + phosphate"},{"id":"d","text":"Nitrogenous base + phosphate"}],"answerId":"a","explanation":"A nucleotide is composed of a nitrogenous base, a pentose sugar, and a phosphate group.","kind":"recall","origin":"ai"},{"id":"nucleotides-structure-roles~ai-1","moduleId":"nucleotides-structure-roles","stem":"What type of bond links nucleotides in a DNA strand?","options":[{"id":"a","text":"Hydrogen bonds"},{"id":"b","text":"Ionic bonds"},{"id":"c","text":"Phosphodiester bonds"},{"id":"d","text":"Peptide bonds"}],"answerId":"c","explanation":"Nucleotides in a DNA strand are linked by phosphodiester bonds between the phosphate of one nucleotide and the sugar of the next.","kind":"mechanism","origin":"ai"},{"id":"nucleotides-structure-roles~ai-2","moduleId":"nucleotides-structure-roles","stem":"Which of the following statements about purines and pyrimidines is true?","options":[{"id":"a","text":"Purines have a single ring structure"},{"id":"b","text":"Pyrimidines include adenine and guanine"},{"id":"c","text":"Purines include adenine and guanine"},{"id":"d","text":"Pyrimidines have a double ring structure"}],"answerId":"c","explanation":"Purines, which include adenine and guanine, have a double ring structure, while pyrimidines have a single ring.","kind":"recall","origin":"ai"},{"id":"nucleotides-structure-roles~ai-3","moduleId":"nucleotides-structure-roles","stem":"Which of the following best describes the role of ATP in cellular processes?","options":[{"id":"a","text":"It serves as a genetic template"},{"id":"b","text":"It acts as a high-energy carrier"},{"id":"c","text":"It is a structural component of DNA"},{"id":"d","text":"It functions as a second messenger"}],"answerId":"b","explanation":"ATP serves as a high-energy carrier due to its phosphoanhydride bonds, which release energy upon hydrolysis.","kind":"mechanism","origin":"ai"},{"id":"nucleotides-structure-roles~ai-4","moduleId":"nucleotides-structure-roles","stem":"Which of the following is a distinguishing feature of nucleotides compared to nucleosides?","options":[{"id":"a","text":"Nucleotides contain ribose"},{"id":"b","text":"Nucleotides have a nitrogenous base"},{"id":"c","text":"Nucleotides have a phosphate group"},{"id":"d","text":"Nucleotides are always purines"}],"answerId":"c","explanation":"Nucleotides are distinguished from nucleosides by the presence of a phosphate group.","kind":"trap","origin":"ai"},{"id":"nucleotides-structure-roles~ai-5","moduleId":"nucleotides-structure-roles","stem":"How does cAMP function as a second messenger in signaling pathways?","options":[{"id":"a","text":"It directly activates genes"},{"id":"b","text":"It hydrolyzes ATP"},{"id":"c","text":"It amplifies the signal from a receptor"},{"id":"d","text":"It forms phosphodiester bonds"}],"answerId":"c","explanation":"cAMP amplifies the signal from a receptor by activating protein kinases, leading to a cellular response.","kind":"mechanism","origin":"ai"},{"id":"nucleotides-structure-roles~ai-6","moduleId":"nucleotides-structure-roles","stem":"Which nucleotide is primarily involved in energy transfer within cells?","options":[{"id":"a","text":"GTP"},{"id":"b","text":"ATP"},{"id":"c","text":"CTP"},{"id":"d","text":"UTP"}],"answerId":"b","explanation":"ATP is the primary nucleotide involved in energy transfer due to its high-energy phosphate bonds.","kind":"recall","origin":"ai"},{"id":"nucleotides-structure-roles~ai-7","moduleId":"nucleotides-structure-roles","stem":"How are nucleotides related to the structure of DNA, as discussed in the linked module?","options":[{"id":"a","text":"They form the backbone of DNA"},{"id":"b","text":"They are the only components of chromatin"},{"id":"c","text":"They are not involved in DNA structure"},{"id":"d","text":"They are only found in RNA"}],"answerId":"a","explanation":"Nucleotides form the backbone of DNA through phosphodiester bonds, linking the sugar and phosphate groups.","kind":"integration","linkedModuleIds":["dna-structure-forms"],"origin":"ai"},{"id":"nucleotides-structure-roles~ai-8","moduleId":"nucleotides-structure-roles","stem":"Which component of nucleotides is crucial for their role in signaling pathways, as discussed in the linked module?","options":[{"id":"a","text":"Nitrogenous base"},{"id":"b","text":"Pentose sugar"},{"id":"c","text":"Phosphate group"},{"id":"d","text":"Ribose sugar"}],"answerId":"c","explanation":"The phosphate group is crucial for the signaling role of nucleotides, as seen in second messengers like cAMP.","kind":"integration","linkedModuleIds":["rna-types"],"origin":"ai"}],"enzyme-catalysis-classification":[{"id":"enzyme-catalysis-classification~ai-0","moduleId":"enzyme-catalysis-classification","stem":"What is the primary role of enzymes in biochemical reactions?","options":[{"id":"a","text":"Increase the equilibrium constant"},{"id":"b","text":"Lower the activation energy"},{"id":"c","text":"Change the reaction products"},{"id":"d","text":"Alter the free energy change"}],"answerId":"b","explanation":"Enzymes function as catalysts that lower the activation energy, thus speeding up reactions without changing the equilibrium.","kind":"recall","origin":"ai"},{"id":"enzyme-catalysis-classification~ai-1","moduleId":"enzyme-catalysis-classification","stem":"Which class of enzymes transfers a phosphate group from ATP to a substrate?","options":[{"id":"a","text":"Hydrolase"},{"id":"b","text":"Lyase"},{"id":"c","text":"Transferase"},{"id":"d","text":"Isomerase"}],"answerId":"c","explanation":"Transferases are enzymes that catalyze the transfer of functional groups, such as phosphate groups from ATP.","kind":"recall","origin":"ai"},{"id":"enzyme-catalysis-classification~ai-2","moduleId":"enzyme-catalysis-classification","stem":"What happens to an enzyme's activity when its cofactor is removed?","options":[{"id":"a","text":"Increases significantly"},{"id":"b","text":"Decreases or becomes inactive"},{"id":"c","text":"Remains unchanged"},{"id":"d","text":"Becomes irreversible"}],"answerId":"b","explanation":"The removal of a cofactor from an enzyme typically results in a loss of activity, as the apoenzyme alone is inactive.","kind":"recall","origin":"ai"},{"id":"enzyme-catalysis-classification~ai-3","moduleId":"enzyme-catalysis-classification","stem":"How do enzymes achieve substrate specificity?","options":[{"id":"a","text":"By altering the substrate structure"},{"id":"b","text":"By changing the reaction conditions"},{"id":"c","text":"Through active-site shape and charge complementarity"},{"id":"d","text":"By increasing the temperature"}],"answerId":"c","explanation":"Enzymes achieve substrate specificity through the complementarity of their active sites to the shape and charge of the substrate.","kind":"recall","origin":"ai"},{"id":"enzyme-catalysis-classification~ai-4","moduleId":"enzyme-catalysis-classification","stem":"Which statement correctly describes the effect of enzymes on reaction thermodynamics?","options":[{"id":"a","text":"Enzymes change ΔG of the reaction"},{"id":"b","text":"Enzymes speed up the reaction without altering ΔG"},{"id":"c","text":"Enzymes make unfavorable reactions favorable"},{"id":"d","text":"Enzymes alter the position of equilibrium"}],"answerId":"b","explanation":"Enzymes only lower the activation energy and do not change the free energy change (ΔG) or the position of equilibrium.","kind":"trap","origin":"ai"},{"id":"enzyme-catalysis-classification~ai-5","moduleId":"enzyme-catalysis-classification","stem":"Which of the following is a characteristic of holoenzymes?","options":[{"id":"a","text":"They are always inactive"},{"id":"b","text":"They consist of an apoenzyme and a cofactor"},{"id":"c","text":"They do not require cofactors"},{"id":"d","text":"They are only found in bacteria"}],"answerId":"b","explanation":"Holoenzymes are active enzymes that consist of an apoenzyme (protein) and a cofactor (inorganic or organic).","kind":"recall","origin":"ai"},{"id":"enzyme-catalysis-classification~ai-6","moduleId":"enzyme-catalysis-classification","stem":"How do coenzymes differ from cofactors?","options":[{"id":"a","text":"Coenzymes are always inorganic"},{"id":"b","text":"Cofactors are always proteins"},{"id":"c","text":"Coenzymes are organic molecules, while cofactors can be inorganic or organic"},{"id":"d","text":"Cofactors are specific to one enzyme only"}],"answerId":"c","explanation":"Coenzymes are organic molecules that assist enzymes, while cofactors can be either inorganic ions or organic molecules.","kind":"integration","linkedModuleIds":["coenzymes-cofactors"],"origin":"ai"},{"id":"enzyme-catalysis-classification~ai-7","moduleId":"enzyme-catalysis-classification","stem":"Which mechanism describes how enzymes stabilize the transition state?","options":[{"id":"a","text":"By increasing substrate concentration"},{"id":"b","text":"By lowering the activation energy"},{"id":"c","text":"By altering product formation"},{"id":"d","text":"By changing the equilibrium constant"}],"answerId":"b","explanation":"Enzymes stabilize the transition state, which lowers the activation energy required for the reaction to proceed.","kind":"mechanism","origin":"ai"},{"id":"enzyme-catalysis-classification~ai-8","moduleId":"enzyme-catalysis-classification","stem":"How does enzyme inhibition affect the rate of reaction?","options":[{"id":"a","text":"Increases the reaction rate"},{"id":"b","text":"Decreases the reaction rate"},{"id":"c","text":"Has no effect on the reaction rate"},{"id":"d","text":"Changes the equilibrium constant"}],"answerId":"b","explanation":"Enzyme inhibition decreases the rate of reaction by preventing the enzyme from catalyzing the reaction effectively.","kind":"integration","linkedModuleIds":["enzyme-inhibition-regulation"],"origin":"ai"}],"coenzymes-cofactors":[{"id":"coenzymes-cofactors~ai-0","moduleId":"coenzymes-cofactors","stem":"Which vitamin is a precursor for the coenzyme involved in oxidative decarboxylation reactions?","options":[{"id":"a","text":"Thiamine (B1)"},{"id":"b","text":"Riboflavin (B2)"},{"id":"c","text":"Niacin (B3)"},{"id":"d","text":"Pantothenic acid (B5)"}],"answerId":"a","explanation":"Thiamine (B1) is converted to thiamine pyrophosphate (TPP), which is essential for oxidative decarboxylation.","kind":"recall","origin":"ai"},{"id":"coenzymes-cofactors~ai-1","moduleId":"coenzymes-cofactors","stem":"What is the primary function of NAD+ in cellular metabolism?","options":[{"id":"a","text":"Electron carrier in redox reactions"},{"id":"b","text":"Acyl group carrier"},{"id":"c","text":"Carboxylation reactions"},{"id":"d","text":"One-carbon transfer"}],"answerId":"a","explanation":"NAD+ functions as an electron carrier in redox reactions, facilitating the transfer of electrons in metabolic pathways.","kind":"mechanism","origin":"ai"},{"id":"coenzymes-cofactors~ai-2","moduleId":"coenzymes-cofactors","stem":"A patient presents with dermatitis, diarrhea, and dementia. Which vitamin deficiency is most likely responsible?","options":[{"id":"a","text":"Vitamin B1"},{"id":"b","text":"Vitamin B3"},{"id":"c","text":"Vitamin B6"},{"id":"d","text":"Vitamin B12"}],"answerId":"b","explanation":"These symptoms are characteristic of niacin (B3) deficiency, leading to pellagra.","kind":"recall","origin":"ai"},{"id":"coenzymes-cofactors~ai-3","moduleId":"coenzymes-cofactors","stem":"Which of the following statements about cofactors and coenzymes is correct?","options":[{"id":"a","text":"All cofactors are coenzymes."},{"id":"b","text":"Cofactors are exclusively organic molecules."},{"id":"c","text":"Coenzymes are a subset of cofactors."},{"id":"d","text":"Cofactors and coenzymes are identical."}],"answerId":"c","explanation":"Coenzymes are indeed a subset of cofactors, which include both organic and inorganic molecules.","kind":"trap","origin":"ai"},{"id":"coenzymes-cofactors~ai-4","moduleId":"coenzymes-cofactors","stem":"A patient with megaloblastic anemia is found to have low levels of both folate and vitamin B12. Which coenzyme is directly involved in DNA synthesis?","options":[{"id":"a","text":"Tetrahydrofolate"},{"id":"b","text":"Thiamine pyrophosphate"},{"id":"c","text":"Pyridoxal phosphate"},{"id":"d","text":"Coenzyme A"}],"answerId":"a","explanation":"Tetrahydrofolate, derived from folate (B9), is crucial for nucleotide synthesis and thus DNA synthesis.","kind":"integration","linkedModuleIds":["enzyme-catalysis-classification"],"origin":"ai"},{"id":"coenzymes-cofactors~ai-5","moduleId":"coenzymes-cofactors","stem":"Which coenzyme is involved in the transamination of amino acids?","options":[{"id":"a","text":"Thiamine pyrophosphate"},{"id":"b","text":"Pyridoxal phosphate"},{"id":"c","text":"Biotin"},{"id":"d","text":"Folate"}],"answerId":"b","explanation":"Pyridoxal phosphate (derived from vitamin B6) is the coenzyme that facilitates transamination reactions.","kind":"recall","origin":"ai"},{"id":"coenzymes-cofactors~ai-6","moduleId":"coenzymes-cofactors","stem":"How does a deficiency in vitamin B12 affect the complement system?","options":[{"id":"a","text":"Increased complement activation"},{"id":"b","text":"Impaired DNA synthesis in immune cells"},{"id":"c","text":"Enhanced phagocytosis"},{"id":"d","text":"No effect on complement function"}],"answerId":"b","explanation":"Vitamin B12 deficiency leads to impaired DNA synthesis, affecting the proliferation of immune cells, including those involved in the complement system.","kind":"integration","linkedModuleIds":["complement-functions-regulation"],"origin":"ai"}],"neurotoxins-facial-palsy":[{"id":"neurotoxins-facial-palsy~ai-0","moduleId":"neurotoxins-facial-palsy","stem":"What is the primary mechanism of action of tetanospasmin in tetanus?","options":[{"id":"a","text":"Inhibition of acetylcholine release"},{"id":"b","text":"Inhibition of GABA and glycine release"},{"id":"c","text":"Stimulation of motor neurons"},{"id":"d","text":"Destruction of peripheral nerves"}],"answerId":"b","explanation":"Tetanospasmin blocks the release of inhibitory neurotransmitters GABA and glycine, leading to disinhibition and muscle rigidity.","kind":"mechanism","origin":"ai"},{"id":"neurotoxins-facial-palsy~ai-1","moduleId":"neurotoxins-facial-palsy","stem":"Which clinical finding is characteristic of botulism?","options":[{"id":"a","text":"Trismus"},{"id":"b","text":"Symmetric descending flaccid paralysis"},{"id":"c","text":"Facial droop with spared forehead"},{"id":"d","text":"Hyperreflexia"}],"answerId":"b","explanation":"Botulism presents with symmetric descending flaccid paralysis, typically without fever or sensory loss.","kind":"recall","origin":"ai"},{"id":"neurotoxins-facial-palsy~ai-2","moduleId":"neurotoxins-facial-palsy","stem":"In Bell's palsy, which of the following is true regarding facial weakness?","options":[{"id":"a","text":"Forehead sparing indicates Bell's palsy"},{"id":"b","text":"It is a lower motor neuron lesion"},{"id":"c","text":"It is associated with fever"},{"id":"d","text":"It spares the entire ipsilateral face"}],"answerId":"b","explanation":"Bell's palsy is a lower motor neuron lesion affecting the entire half of the face, including the forehead.","kind":"trap","origin":"ai"},{"id":"neurotoxins-facial-palsy~ai-3","moduleId":"neurotoxins-facial-palsy","stem":"What is the first-line treatment for tetanus?","options":[{"id":"a","text":"Corticosteroids"},{"id":"b","text":"Human tetanus immunoglobulin"},{"id":"c","text":"Antibiotics only"},{"id":"d","text":"Supportive care only"}],"answerId":"b","explanation":"Human tetanus immunoglobulin is administered to neutralize the toxin, along with antibiotics and supportive care.","kind":"recall","origin":"ai"},{"id":"neurotoxins-facial-palsy~ai-4","moduleId":"neurotoxins-facial-palsy","stem":"Which of the following is a common source of botulism in infants?","options":[{"id":"a","text":"Home-canned food"},{"id":"b","text":"Wounds from IV drug use"},{"id":"c","text":"Raw honey"},{"id":"d","text":"Contaminated water"}],"answerId":"c","explanation":"Raw honey is a known source of botulism spores that can cause illness in infants.","kind":"recall","origin":"ai"},{"id":"neurotoxins-facial-palsy~ai-5","moduleId":"neurotoxins-facial-palsy","stem":"How does the mechanism of tetanospasmin differ from that of botulinum toxin?","options":[{"id":"a","text":"Both block acetylcholine release"},{"id":"b","text":"Tetanospasmin blocks GABA release, botulinum blocks ACh release"},{"id":"c","text":"Both cause flaccid paralysis"},{"id":"d","text":"Tetanospasmin causes muscle weakness, botulinum causes rigidity"}],"answerId":"b","explanation":"Tetanospasmin blocks GABA release leading to rigidity, while botulinum toxin blocks ACh release causing flaccid paralysis.","kind":"mechanism","origin":"ai"},{"id":"neurotoxins-facial-palsy~ai-6","moduleId":"neurotoxins-facial-palsy","stem":"Which cranial nerve is primarily affected in Bell's palsy?","options":[{"id":"a","text":"CN III"},{"id":"b","text":"CN V"},{"id":"c","text":"CN VII"},{"id":"d","text":"CN X"}],"answerId":"c","explanation":"Bell's palsy involves the facial nerve (CN VII), leading to unilateral facial weakness.","kind":"recall","origin":"ai"},{"id":"neurotoxins-facial-palsy~ai-7","moduleId":"neurotoxins-facial-palsy","stem":"How does the presentation of Bell's palsy differ from a stroke affecting the facial nerve?","options":[{"id":"a","text":"Bell's palsy spares the forehead"},{"id":"b","text":"Stroke affects both sides of the face"},{"id":"c","text":"Bell's palsy involves the entire half of the face"},{"id":"d","text":"Stroke presents with fever"}],"answerId":"c","explanation":"Bell's palsy involves the entire ipsilateral face, while a stroke typically spares the forehead due to bilateral cortical input.","kind":"trap","origin":"ai"},{"id":"neurotoxins-facial-palsy~ai-8","moduleId":"neurotoxins-facial-palsy","stem":"In the context of facial nerve innervation, how does Bell's palsy relate to the anatomy of the facial muscles?","options":[{"id":"a","text":"It affects only the upper face"},{"id":"b","text":"It involves the entire face including the forehead"},{"id":"c","text":"It is an upper motor neuron lesion"},{"id":"d","text":"It does not affect facial expression"}],"answerId":"b","explanation":"Bell's palsy is a lower motor neuron lesion affecting the entire ipsilateral face, including the forehead.","kind":"integration","linkedModuleIds":["face-muscles-innervation"],"origin":"ai"},{"id":"neurotoxins-facial-palsy~ai-9","moduleId":"neurotoxins-facial-palsy","stem":"How does understanding the mechanism of clostridial toxins enhance the management of patients with facial nerve palsy?","options":[{"id":"a","text":"It helps in diagnosing Bell's palsy"},{"id":"b","text":"It provides insight into potential respiratory complications"},{"id":"c","text":"It aids in distinguishing between UMN and LMN lesions"},{"id":"d","text":"It informs the choice of antibiotics"}],"answerId":"c","explanation":"Understanding the mechanisms of clostridial toxins helps differentiate between upper and lower motor neuron lesions, which is crucial for diagnosis.","kind":"integration","linkedModuleIds":["cranial-nerves-overview"],"origin":"ai"}],"collagen-elastin":[{"id":"collagen-elastin~ai-0","moduleId":"collagen-elastin","stem":"What is the primary amino acid sequence pattern in collagen?","options":[{"id":"a","text":"Gly-Pro-Hyp"},{"id":"b","text":"Ala-Gly-Pro"},{"id":"c","text":"Gly-X-Y"},{"id":"d","text":"Pro-Hyp-Lys"}],"answerId":"c","explanation":"Collagen's structure is characterized by the repeating sequence Gly-X-Y, where X is often proline and Y is often hydroxyproline.","kind":"recall","origin":"ai"},{"id":"collagen-elastin~ai-1","moduleId":"collagen-elastin","stem":"Which vitamin is essential for the stability of collagen's triple helix?","options":[{"id":"a","text":"Vitamin A"},{"id":"b","text":"Vitamin C"},{"id":"c","text":"Vitamin D"},{"id":"d","text":"Vitamin K"}],"answerId":"b","explanation":"Vitamin C is required as a cofactor for prolyl hydroxylase, which hydroxylates proline residues, stabilizing the collagen triple helix.","kind":"recall","origin":"ai"},{"id":"collagen-elastin~ai-2","moduleId":"collagen-elastin","stem":"A patient presents with bleeding gums and bruising. Which deficiency is most likely responsible?","options":[{"id":"a","text":"Vitamin K deficiency"},{"id":"b","text":"Vitamin C deficiency"},{"id":"c","text":"Vitamin D deficiency"},{"id":"d","text":"Iron deficiency"}],"answerId":"b","explanation":"Vitamin C deficiency leads to defective collagen synthesis, resulting in symptoms like bleeding gums and bruising.","kind":"recall","origin":"ai"},{"id":"collagen-elastin~ai-3","moduleId":"collagen-elastin","stem":"What is the mechanism by which α1-antitrypsin deficiency leads to emphysema?","options":[{"id":"a","text":"Increased elastase activity"},{"id":"b","text":"Decreased collagen synthesis"},{"id":"c","text":"Increased collagen degradation"},{"id":"d","text":"Decreased elastin production"}],"answerId":"a","explanation":"α1-antitrypsin deficiency results in unopposed elastase activity, which degrades alveolar elastin, leading to emphysema.","kind":"mechanism","origin":"ai"},{"id":"collagen-elastin~ai-4","moduleId":"collagen-elastin","stem":"Which of the following statements about vitamin C's role in collagen synthesis is correct?","options":[{"id":"a","text":"Vitamin C is needed to synthesize the collagen amino-acid sequence itself."},{"id":"b","text":"Vitamin C is a cofactor for prolyl hydroxylase."},{"id":"c","text":"Vitamin C directly forms the triple helix structure."},{"id":"d","text":"Vitamin C is required for collagen cross-linking."}],"answerId":"b","explanation":"Vitamin C acts as a cofactor for prolyl hydroxylase, enabling the post-translational hydroxylation necessary for collagen stability.","kind":"trap","origin":"ai"},{"id":"collagen-elastin~ai-5","moduleId":"collagen-elastin","stem":"A 30-year-old non-smoker presents with early-onset panlobular emphysema. What is the most likely underlying condition?","options":[{"id":"a","text":"Cystic fibrosis"},{"id":"b","text":"α1-antitrypsin deficiency"},{"id":"c","text":"Chronic bronchitis"},{"id":"d","text":"Asthma"}],"answerId":"b","explanation":"Early-onset panlobular emphysema in a non-smoker is characteristic of α1-antitrypsin deficiency, which leads to unopposed elastase activity.","kind":"recall","origin":"ai"},{"id":"collagen-elastin~ai-6","moduleId":"collagen-elastin","stem":"How does the misfolding of α1-antitrypsin lead to liver disease?","options":[{"id":"a","text":"Increased elastase activity"},{"id":"b","text":"Accumulation of misfolded protein in hepatocytes"},{"id":"c","text":"Decreased collagen synthesis"},{"id":"d","text":"Increased collagen degradation"}],"answerId":"b","explanation":"Misfolded α1-antitrypsin accumulates in hepatocytes, leading to liver disease such as cirrhosis.","kind":"mechanism","origin":"ai"},{"id":"collagen-elastin~ai-7","moduleId":"collagen-elastin","stem":"How does collagen structure relate to protein folding principles discussed in amino acids and protein structure?","options":[{"id":"a","text":"Collagen is a simple linear protein."},{"id":"b","text":"Collagen's triple helix is stabilized by hydrogen bonds."},{"id":"c","text":"Collagen does not require post-translational modifications."},{"id":"d","text":"Collagen is solely composed of non-polar amino acids."}],"answerId":"b","explanation":"Collagen's triple helix structure is stabilized by hydrogen bonds formed between hydroxylated proline residues, illustrating key protein folding principles.","kind":"integration","linkedModuleIds":["amino-acids-proteins-structure"],"origin":"ai"},{"id":"collagen-elastin~ai-8","moduleId":"collagen-elastin","stem":"Which aspect of collagen's structure is crucial for its mechanical properties as discussed in protein misfolding?","options":[{"id":"a","text":"Presence of disulfide bonds"},{"id":"b","text":"Hydrogen bonding in the triple helix"},{"id":"c","text":"Hydrophobic interactions"},{"id":"d","text":"Ionic bonding between chains"}],"answerId":"b","explanation":"The hydrogen bonding in collagen's triple helix is essential for its tensile strength and mechanical properties, linking to principles of protein misfolding.","kind":"integration","linkedModuleIds":["protein-misfolding-amyloid"],"origin":"ai"}],"dna-structure-forms":[{"id":"dna-structure-forms~ai-0","moduleId":"dna-structure-forms","stem":"What is the primary reason for the higher melting temperature (Tm) of GC-rich DNA compared to AT-rich DNA?","options":[{"id":"a","text":"Increased length of GC-rich DNA"},{"id":"b","text":"Higher number of hydrogen bonds"},{"id":"c","text":"Presence of more base pairs"},{"id":"d","text":"Increased salt concentration"}],"answerId":"b","explanation":"GC-rich DNA has three hydrogen bonds per G-C pair, compared to two for A-T pairs, leading to greater stability and higher melting temperature.","kind":"recall","origin":"ai"},{"id":"dna-structure-forms~ai-1","moduleId":"dna-structure-forms","stem":"Which DNA form is primarily found in physiological conditions?","options":[{"id":"a","text":"A-DNA"},{"id":"b","text":"B-DNA"},{"id":"c","text":"Z-DNA"},{"id":"d","text":"C-DNA"}],"answerId":"b","explanation":"B-DNA is the predominant form of DNA under physiological conditions, characterized by its right-handed helical structure.","kind":"recall","origin":"ai"},{"id":"dna-structure-forms~ai-2","moduleId":"dna-structure-forms","stem":"What is the effect of heating DNA on its UV absorbance at 260 nm?","options":[{"id":"a","text":"Decreases absorbance"},{"id":"b","text":"No change in absorbance"},{"id":"c","text":"Increases absorbance"},{"id":"d","text":"Fluctuates unpredictably"}],"answerId":"c","explanation":"Heating DNA causes strand separation, exposing bases and resulting in increased UV absorbance at 260 nm, known as hyperchromicity.","kind":"mechanism","origin":"ai"},{"id":"dna-structure-forms~ai-3","moduleId":"dna-structure-forms","stem":"Which statement about the structure of DNA is correct?","options":[{"id":"a","text":"DNA strands are parallel"},{"id":"b","text":"A-T pairs form three hydrogen bonds"},{"id":"c","text":"Major and minor grooves are due to asymmetric base attachment"},{"id":"d","text":"Z-DNA is the most common form in cells"}],"answerId":"c","explanation":"The major and minor grooves arise from the asymmetrical attachment of bases to the sugar-phosphate backbone, facilitating protein recognition.","kind":"trap","origin":"ai"},{"id":"dna-structure-forms~ai-4","moduleId":"dna-structure-forms","stem":"What is the role of topoisomerases in DNA structure?","options":[{"id":"a","text":"Stabilizing hydrogen bonds"},{"id":"b","text":"Relieving supercoiling"},{"id":"c","text":"Facilitating base pairing"},{"id":"d","text":"Enhancing UV absorbance"}],"answerId":"b","explanation":"Topoisomerases relieve supercoiling in DNA, which is crucial during replication and transcription.","kind":"mechanism","origin":"ai"},{"id":"dna-structure-forms~ai-5","moduleId":"dna-structure-forms","stem":"How does the structure of DNA relate to its function in CO₂ transport in blood?","options":[{"id":"a","text":"DNA encodes proteins for CO₂ transport"},{"id":"b","text":"DNA directly transports CO₂"},{"id":"c","text":"DNA stabilizes hemoglobin structure"},{"id":"d","text":"DNA regulates blood pH"}],"answerId":"a","explanation":"DNA encodes the proteins, including hemoglobin, that are essential for CO₂ transport in blood.","kind":"integration","linkedModuleIds":["co2-transport-blood"],"origin":"ai"},{"id":"dna-structure-forms~ai-6","moduleId":"dna-structure-forms","stem":"Which feature of DNA structure is important for chromatin packaging?","options":[{"id":"a","text":"Antiparallel strands"},{"id":"b","text":"Major and minor grooves"},{"id":"c","text":"Hydrophobic base stacking"},{"id":"d","text":"B-DNA form"}],"answerId":"b","explanation":"The major and minor grooves of DNA provide binding sites for proteins that facilitate chromatin packaging and regulation.","kind":"integration","linkedModuleIds":["chromatin-packaging"],"origin":"ai"}],"protein-misfolding-amyloid":[{"id":"protein-misfolding-amyloid~ai-0","moduleId":"protein-misfolding-amyloid","stem":"What is the primary structural change in proteins that leads to amyloid formation?","options":[{"id":"a","text":"Conversion from β-sheet to α-helix"},{"id":"b","text":"Conversion from α-helix to β-sheet"},{"id":"c","text":"Loss of tertiary structure"},{"id":"d","text":"Formation of disulfide bonds"}],"answerId":"b","explanation":"Amyloid formation involves the conversion of proteins from their native α-helical structure to a β-sheet configuration, leading to insoluble fibril formation.","kind":"mechanism","origin":"ai"},{"id":"protein-misfolding-amyloid~ai-1","moduleId":"protein-misfolding-amyloid","stem":"Which of the following is a characteristic finding in Alzheimer disease?","options":[{"id":"a","text":"Cerebral β-amyloid plaques"},{"id":"b","text":"Monoclonal light chains"},{"id":"c","text":"Insulin amyloid deposits"},{"id":"d","text":"Prion protein aggregates"}],"answerId":"a","explanation":"Alzheimer disease is characterized by the presence of cerebral β-amyloid plaques, which are a hallmark of the disease.","kind":"recall","origin":"ai"},{"id":"protein-misfolding-amyloid~ai-2","moduleId":"protein-misfolding-amyloid","stem":"In which condition do misfolded proteins lead to restrictive cardiomyopathy?","options":[{"id":"a","text":"Alzheimer disease"},{"id":"b","text":"AL amyloidosis"},{"id":"c","text":"Parkinson disease"},{"id":"d","text":"Prion disease"}],"answerId":"b","explanation":"AL amyloidosis is associated with the deposition of monoclonal light chains, leading to restrictive cardiomyopathy.","kind":"clinical","origin":"ai"},{"id":"protein-misfolding-amyloid~ai-3","moduleId":"protein-misfolding-amyloid","stem":"Which of the following correctly describes prion diseases?","options":[{"id":"a","text":"Caused by viral infection"},{"id":"b","text":"Involves misfolded proteins only"},{"id":"c","text":"Requires nucleic acid for transmission"},{"id":"d","text":"Characterized by α-helix formation"}],"answerId":"b","explanation":"Prion diseases are caused by misfolded proteins (PrPˢᶜ) that induce normal proteins to misfold, with no nucleic acid involved.","kind":"trap","origin":"ai"},{"id":"protein-misfolding-amyloid~ai-4","moduleId":"protein-misfolding-amyloid","stem":"What is the mechanism of action of β-amyloid in Alzheimer's disease?","options":[{"id":"a","text":"Inhibition of neurotransmitter release"},{"id":"b","text":"Formation of neurofibrillary tangles"},{"id":"c","text":"Induction of neuroinflammation"},{"id":"d","text":"Formation of insoluble fibrils leading to neuronal death"}],"answerId":"d","explanation":"β-amyloid aggregates form insoluble fibrils that disrupt neuronal function and contribute to cell death in Alzheimer's disease.","kind":"mechanism","origin":"ai"},{"id":"protein-misfolding-amyloid~ai-5","moduleId":"protein-misfolding-amyloid","stem":"How does the mechanism of amyloid formation relate to protein structure?","options":[{"id":"a","text":"It involves the loss of primary structure"},{"id":"b","text":"It leads to increased solubility of proteins"},{"id":"c","text":"It is characterized by the conversion of α-helix to β-sheet"},{"id":"d","text":"It results in the formation of disulfide bridges"}],"answerId":"c","explanation":"Amyloid formation is characterized by the conversion of proteins from their native α-helical structure to a β-sheet configuration, leading to aggregation.","kind":"integration","linkedModuleIds":["amino-acids-proteins-structure"],"origin":"ai"},{"id":"protein-misfolding-amyloid~ai-6","moduleId":"protein-misfolding-amyloid","stem":"Which type of amyloid is associated with type 2 diabetes?","options":[{"id":"a","text":"β-amyloid"},{"id":"b","text":"α-synuclein"},{"id":"c","text":"IAPP"},{"id":"d","text":"Ig light chains"}],"answerId":"c","explanation":"IAPP (islet amyloid polypeptide) is associated with amyloid deposits in type 2 diabetes.","kind":"recall","origin":"ai"},{"id":"protein-misfolding-amyloid~ai-7","moduleId":"protein-misfolding-amyloid","stem":"Which clinical finding is associated with prion disease?","options":[{"id":"a","text":"Progressive dementia with β-amyloid plaques"},{"id":"b","text":"Rapidly progressive dementia with myoclonus"},{"id":"c","text":"Restrictive cardiomyopathy"},{"id":"d","text":"Monoclonal light chains in urine"}],"answerId":"b","explanation":"Prion disease is characterized by rapidly progressive dementia and myoclonus, distinguishing it from other conditions.","kind":"clinical","origin":"ai"}],"hemoglobin-myoglobin":[{"id":"hemoglobin-myoglobin~ai-0","moduleId":"hemoglobin-myoglobin","stem":"What is the primary function of myoglobin in muscle tissue?","options":[{"id":"a","text":"Oxygen transport in blood"},{"id":"b","text":"Oxygen storage"},{"id":"c","text":"Carbon dioxide transport"},{"id":"d","text":"Carbon monoxide binding"}],"answerId":"b","explanation":"Myoglobin primarily serves as an oxygen storage protein in muscle tissue, allowing for a reserve of oxygen during periods of high demand.","kind":"recall","origin":"ai"},{"id":"hemoglobin-myoglobin~ai-1","moduleId":"hemoglobin-myoglobin","stem":"Which structural feature of hemoglobin allows for cooperative binding of oxygen?","options":[{"id":"a","text":"Single subunit structure"},{"id":"b","text":"Tetrameric structure with multiple subunits"},{"id":"c","text":"Presence of heme groups"},{"id":"d","text":"High affinity for oxygen at all pO₂ levels"}],"answerId":"b","explanation":"Hemoglobin's tetrameric structure allows for cooperative binding, where the binding of one oxygen molecule increases the affinity of the remaining sites.","kind":"mechanism","origin":"ai"},{"id":"hemoglobin-myoglobin~ai-2","moduleId":"hemoglobin-myoglobin","stem":"What is the result of the missense mutation in the β-globin gene in sickle cell disease?","options":[{"id":"a","text":"Increased oxygen affinity"},{"id":"b","text":"Decreased oxygen affinity"},{"id":"c","text":"Polymerization of deoxygenated hemoglobin"},{"id":"d","text":"Increased solubility of hemoglobin"}],"answerId":"c","explanation":"The mutation leads to the polymerization of deoxygenated hemoglobin (HbS), causing sickling of red blood cells.","kind":"mechanism","origin":"ai"},{"id":"hemoglobin-myoglobin~ai-3","moduleId":"hemoglobin-myoglobin","stem":"What would you expect to see on hemoglobin electrophoresis in a patient with sickle cell disease?","options":[{"id":"a","text":"Normal HbA bands"},{"id":"b","text":"A shift towards HbF bands"},{"id":"c","text":"An abnormal band representing HbS"},{"id":"d","text":"No bands present"}],"answerId":"c","explanation":"Patients with sickle cell disease will show an abnormal band on electrophoresis due to the charge change from Glu to Val in HbS.","kind":"recall","origin":"ai"},{"id":"hemoglobin-myoglobin~ai-4","moduleId":"hemoglobin-myoglobin","stem":"Why is hemoglobin's oxygen binding curve sigmoidal?","options":[{"id":"a","text":"It binds oxygen with high affinity at all pO₂ levels"},{"id":"b","text":"It reflects cooperative binding between subunits"},{"id":"c","text":"It is a characteristic of myoglobin"},{"id":"d","text":"It indicates low oxygen delivery to tissues"}],"answerId":"b","explanation":"The sigmoidal shape of hemoglobin's oxygen binding curve indicates cooperative binding, where the binding of one oxygen molecule increases the affinity of the others.","kind":"trap","origin":"ai"},{"id":"hemoglobin-myoglobin~ai-5","moduleId":"hemoglobin-myoglobin","stem":"How does the mutation in sickle cell disease affect the physical properties of red blood cells?","options":[{"id":"a","text":"Increases flexibility"},{"id":"b","text":"Decreases viscosity"},{"id":"c","text":"Causes sickling and vaso-occlusive events"},{"id":"d","text":"Enhances oxygen carrying capacity"}],"answerId":"c","explanation":"The polymerization of deoxygenated HbS leads to the sickling of red blood cells, causing vaso-occlusive pain and other complications.","kind":"clinical","origin":"ai"},{"id":"hemoglobin-myoglobin~ai-6","moduleId":"hemoglobin-myoglobin","stem":"How does the structure of hemoglobin relate to its function in oxygen transport, as compared to myoglobin?","options":[{"id":"a","text":"Both are monomers"},{"id":"b","text":"Hemoglobin has a higher affinity for oxygen than myoglobin"},{"id":"c","text":"Hemoglobin's quaternary structure allows for cooperative binding"},{"id":"d","text":"Myoglobin can transport oxygen in the blood"}],"answerId":"c","explanation":"Hemoglobin's quaternary structure allows for cooperative binding, which is essential for its function in oxygen transport, unlike myoglobin's monomeric structure.","kind":"integration","linkedModuleIds":["amino-acids-proteins-structure"],"origin":"ai"},{"id":"hemoglobin-myoglobin~ai-7","moduleId":"hemoglobin-myoglobin","stem":"In what way does the cooperative binding of hemoglobin enhance oxygen delivery compared to myoglobin?","options":[{"id":"a","text":"Myoglobin releases oxygen more readily"},{"id":"b","text":"Hemoglobin can load oxygen more efficiently in the lungs"},{"id":"c","text":"Myoglobin binds oxygen in a sigmoidal manner"},{"id":"d","text":"Hemoglobin has a lower overall oxygen capacity"}],"answerId":"b","explanation":"Hemoglobin's cooperative binding allows it to load oxygen efficiently in the lungs and unload it effectively in tissues, unlike myoglobin.","kind":"integration","linkedModuleIds":["membrane-transport-passive"],"origin":"ai"}],"mutations-dna-damage":[{"id":"mutations-dna-damage~ai-0","moduleId":"mutations-dna-damage","stem":"What type of mutation results in a premature stop codon?","options":[{"id":"a","text":"Silent mutation"},{"id":"b","text":"Missense mutation"},{"id":"c","text":"Nonsense mutation"},{"id":"d","text":"Frameshift mutation"}],"answerId":"c","explanation":"A nonsense mutation introduces a premature stop codon, leading to truncated proteins.","kind":"recall","origin":"ai"},{"id":"mutations-dna-damage~ai-1","moduleId":"mutations-dna-damage","stem":"Which type of mutation is characterized by a shift in the reading frame?","options":[{"id":"a","text":"Point mutation"},{"id":"b","text":"Nonsense mutation"},{"id":"c","text":"Frameshift mutation"},{"id":"d","text":"Translocation"}],"answerId":"c","explanation":"Frameshift mutations occur due to insertions or deletions that shift the reading frame.","kind":"mechanism","origin":"ai"},{"id":"mutations-dna-damage~ai-2","moduleId":"mutations-dna-damage","stem":"What is the primary effect of UV radiation on DNA?","options":[{"id":"a","text":"Base oxidation"},{"id":"b","text":"Pyrimidine dimers"},{"id":"c","text":"Strand breaks"},{"id":"d","text":"Crosslinking"}],"answerId":"b","explanation":"UV radiation primarily causes the formation of pyrimidine dimers, particularly thymine dimers.","kind":"mechanism","origin":"ai"},{"id":"mutations-dna-damage~ai-3","moduleId":"mutations-dna-damage","stem":"Which of the following mutations does NOT change the amino acid sequence?","options":[{"id":"a","text":"Silent mutation"},{"id":"b","text":"Missense mutation"},{"id":"c","text":"Nonsense mutation"},{"id":"d","text":"Frameshift mutation"}],"answerId":"a","explanation":"Silent mutations change the codon but do not alter the amino acid due to the degeneracy of the genetic code.","kind":"trap","origin":"ai"},{"id":"mutations-dna-damage~ai-4","moduleId":"mutations-dna-damage","stem":"What type of mutation is most likely to result from oxidative damage to guanine?","options":[{"id":"a","text":"Transition"},{"id":"b","text":"Transversion"},{"id":"c","text":"Frameshift"},{"id":"d","text":"Deletion"}],"answerId":"b","explanation":"Oxidative damage to guanine can lead to 8-oxoguanine, which mispairs with adenine, causing G:T transversions.","kind":"mechanism","origin":"ai"},{"id":"mutations-dna-damage~ai-5","moduleId":"mutations-dna-damage","stem":"How might a mutation in a gene related to DNA repair mechanisms affect hypertrophic cardiomyopathy?","options":[{"id":"a","text":"Increase contractility"},{"id":"b","text":"Decrease myocardial oxygen demand"},{"id":"c","text":"Promote cardiac hypertrophy"},{"id":"d","text":"Enhance electrical conduction"}],"answerId":"c","explanation":"Mutations affecting DNA repair can lead to cellular dysfunction and contribute to the pathophysiology of hypertrophic cardiomyopathy.","kind":"integration","linkedModuleIds":["hypertrophic-cardiomyopathy"],"origin":"ai"},{"id":"mutations-dna-damage~ai-6","moduleId":"mutations-dna-damage","stem":"Which type of mutation could lead to an increased risk of developing certain cancers due to impaired DNA repair mechanisms?","options":[{"id":"a","text":"Nonsense mutation"},{"id":"b","text":"Frameshift mutation"},{"id":"c","text":"Missense mutation"},{"id":"d","text":"Large-scale chromosomal mutation"}],"answerId":"b","explanation":"Frameshift mutations can disrupt critical DNA repair genes, leading to genomic instability and increased cancer risk.","kind":"integration","linkedModuleIds":["dna-repair-mechanisms"],"origin":"ai"}],"transcription-mechanism":[{"id":"transcription-mechanism~ai-0","moduleId":"transcription-mechanism","stem":"What is the primary function of RNA polymerase during transcription?","options":[{"id":"a","text":"Synthesize RNA from a DNA template"},{"id":"b","text":"Synthesize DNA from an RNA template"},{"id":"c","text":"Modify RNA after synthesis"},{"id":"d","text":"Degrade RNA molecules"}],"answerId":"a","explanation":"RNA polymerase synthesizes RNA by reading the DNA template strand in the 5′ to 3′ direction.","kind":"recall","origin":"ai"},{"id":"transcription-mechanism~ai-1","moduleId":"transcription-mechanism","stem":"Which sequence is recognized by prokaryotic RNA polymerase to initiate transcription?","options":[{"id":"a","text":"TATA box"},{"id":"b","text":"Pribnow box"},{"id":"c","text":"Enhancer region"},{"id":"d","text":"Polyadenylation signal"}],"answerId":"b","explanation":"The Pribnow box (−10 region) is a key promoter sequence recognized by prokaryotic RNA polymerase.","kind":"recall","origin":"ai"},{"id":"transcription-mechanism~ai-2","moduleId":"transcription-mechanism","stem":"What is the effect of rifampin on bacterial cells?","options":[{"id":"a","text":"Inhibits DNA replication"},{"id":"b","text":"Inhibits RNA transcription"},{"id":"c","text":"Inhibits protein synthesis"},{"id":"d","text":"Inhibits cell wall synthesis"}],"answerId":"b","explanation":"Rifampin specifically inhibits bacterial RNA polymerase, thereby blocking RNA transcription.","kind":"mechanism","origin":"ai"},{"id":"transcription-mechanism~ai-3","moduleId":"transcription-mechanism","stem":"Which of the following statements about RNA synthesis is true?","options":[{"id":"a","text":"RNA is synthesized in the 3′ to 5′ direction"},{"id":"b","text":"RNA is identical to the template strand"},{"id":"c","text":"RNA is synthesized from ribonucleotides"},{"id":"d","text":"RNA synthesis requires a primer"}],"answerId":"c","explanation":"RNA is synthesized from ribonucleotides in the 5′ to 3′ direction, and does not require a primer.","kind":"trap","origin":"ai"},{"id":"transcription-mechanism~ai-4","moduleId":"transcription-mechanism","stem":"A patient presents with symptoms of α-amanitin poisoning. Which transcription process is primarily affected?","options":[{"id":"a","text":"Prokaryotic mRNA synthesis"},{"id":"b","text":"Eukaryotic rRNA synthesis"},{"id":"c","text":"Eukaryotic mRNA synthesis"},{"id":"d","text":"Eukaryotic tRNA synthesis"}],"answerId":"c","explanation":"α-amanitin specifically inhibits eukaryotic RNA polymerase II, which is responsible for mRNA synthesis.","kind":"clinical","origin":"ai"},{"id":"transcription-mechanism~ai-5","moduleId":"transcription-mechanism","stem":"How does the mechanism of transcription relate to the processing of mRNA in eukaryotes?","options":[{"id":"a","text":"Transcription occurs in the cytoplasm"},{"id":"b","text":"mRNA is synthesized without introns"},{"id":"c","text":"Transcription occurs in the nucleus, followed by mRNA processing"},{"id":"d","text":"RNA polymerase II is not involved in mRNA synthesis"}],"answerId":"c","explanation":"Transcription occurs in the nucleus, and the resulting mRNA undergoes processing before it can be translated.","kind":"integration","linkedModuleIds":["rna-processing"],"origin":"ai"},{"id":"transcription-mechanism~ai-6","moduleId":"transcription-mechanism","stem":"Which antiviral mechanism is employed by drugs targeting herpesviruses?","options":[{"id":"a","text":"Inhibition of DNA polymerase"},{"id":"b","text":"Inhibition of RNA polymerase"},{"id":"c","text":"Inhibition of reverse transcriptase"},{"id":"d","text":"Inhibition of ribosomal function"}],"answerId":"a","explanation":"Antivirals for herpesviruses primarily inhibit viral DNA polymerase, preventing viral replication.","kind":"integration","linkedModuleIds":["herpesvirus-cmv-antivirals"],"origin":"ai"}],"human-genome-organization":[{"id":"human-genome-organization~ai-0","moduleId":"human-genome-organization","stem":"What percentage of the human genome is composed of protein-coding genes?","options":[{"id":"a","text":"1.5%"},{"id":"b","text":"10%"},{"id":"c","text":"25%"},{"id":"d","text":"50%"}],"answerId":"a","explanation":"Only about 1.5% of the human genome is made up of protein-coding genes, with the majority being non-coding sequences.","kind":"recall","origin":"ai"},{"id":"human-genome-organization~ai-1","moduleId":"human-genome-organization","stem":"Which of the following best describes the inheritance pattern of mitochondrial DNA?","options":[{"id":"a","text":"Autosomal dominant"},{"id":"b","text":"Autosomal recessive"},{"id":"c","text":"X-linked"},{"id":"d","text":"Maternal inheritance"}],"answerId":"d","explanation":"Mitochondrial DNA is inherited exclusively from the mother, following a maternal inheritance pattern.","kind":"mechanism","origin":"ai"},{"id":"human-genome-organization~ai-2","moduleId":"human-genome-organization","stem":"What is the primary mechanism by which DNA transposons operate?","options":[{"id":"a","text":"Copy-and-paste"},{"id":"b","text":"Cut-and-paste"},{"id":"c","text":"Replication fork stalling"},{"id":"d","text":"Base excision repair"}],"answerId":"b","explanation":"DNA transposons utilize a cut-and-paste mechanism to move within the genome.","kind":"mechanism","origin":"ai"},{"id":"human-genome-organization~ai-3","moduleId":"human-genome-organization","stem":"A researcher discovers a single-base variant present in 0.5% of the population. How should this variant be classified?","options":[{"id":"a","text":"Polymorphism"},{"id":"b","text":"Mutation"},{"id":"c","text":"SNP"},{"id":"d","text":"Allele"}],"answerId":"b","explanation":"Variants present in less than 1% of the population are classified as mutations.","kind":"trap","origin":"ai"},{"id":"human-genome-organization~ai-4","moduleId":"human-genome-organization","stem":"Which chromosome feature is associated with silenced genes?","options":[{"id":"a","text":"Euchromatin"},{"id":"b","text":"Telomeres"},{"id":"c","text":"Heterochromatin"},{"id":"d","text":"Centromere"}],"answerId":"c","explanation":"Genes located in heterochromatin are typically silenced due to the condensed nature of this chromatin.","kind":"recall","origin":"ai"},{"id":"human-genome-organization~ai-5","moduleId":"human-genome-organization","stem":"How do short tandem repeats (STRs) contribute to DNA fingerprinting?","options":[{"id":"a","text":"They are coding regions"},{"id":"b","text":"They are unique per individual"},{"id":"c","text":"They are located in heterochromatin"},{"id":"d","text":"They are mutations"}],"answerId":"b","explanation":"STRs vary in number between individuals, making them useful for DNA fingerprinting.","kind":"clinical","origin":"ai"},{"id":"human-genome-organization~ai-6","moduleId":"human-genome-organization","stem":"How are mutations related to DNA damage classified in the context of the human genome?","options":[{"id":"a","text":"All mutations are due to DNA damage"},{"id":"b","text":"Only SNPs are considered mutations"},{"id":"c","text":"Mutations can arise from replication errors"},{"id":"d","text":"Mutations are always inherited"}],"answerId":"c","explanation":"Mutations can arise from various mechanisms, including replication errors and DNA damage, and are not exclusively inherited.","kind":"integration","linkedModuleIds":["mutations-dna-damage"],"origin":"ai"},{"id":"human-genome-organization~ai-7","moduleId":"human-genome-organization","stem":"Which of the following best connects the regulation of gene expression to developmental processes?","options":[{"id":"a","text":"Protein-coding genes are the only regulators"},{"id":"b","text":"Non-coding regions have no role"},{"id":"c","text":"Gene regulation is crucial for development"},{"id":"d","text":"All genes are expressed equally during development"}],"answerId":"c","explanation":"Gene regulation is essential for proper development, influencing when and how genes are expressed.","kind":"integration","linkedModuleIds":["developmental-genetic-regulation"],"origin":"ai"}],"eukaryotic-replication-telomeres":[{"id":"eukaryotic-replication-telomeres~ai-0","moduleId":"eukaryotic-replication-telomeres","stem":"What is the primary reason for telomere shortening in somatic cells?","options":[{"id":"a","text":"Active degradation by nucleases during cell division"},{"id":"b","text":"Inability of DNA polymerase to fully replicate the lagging strand"},{"id":"c","text":"Increased activity of telomerase in somatic cells"},{"id":"d","text":"Excessive DNA damage repair mechanisms"}],"answerId":"b","explanation":"Telomere shortening occurs due to the end-replication problem where the lagging-strand terminus cannot be fully copied after primer removal.","kind":"trap","origin":"ai"},{"id":"eukaryotic-replication-telomeres~ai-1","moduleId":"eukaryotic-replication-telomeres","stem":"Which enzyme is responsible for adding telomeric sequences to chromosome ends?","options":[{"id":"a","text":"DNA polymerase"},{"id":"b","text":"Telomerase"},{"id":"c","text":"RNA polymerase"},{"id":"d","text":"Ligase"}],"answerId":"b","explanation":"Telomerase is a reverse transcriptase that adds repetitive telomeric sequences to the ends of chromosomes.","kind":"recall","origin":"ai"},{"id":"eukaryotic-replication-telomeres~ai-2","moduleId":"eukaryotic-replication-telomeres","stem":"During which phase of the cell cycle does DNA replication occur?","options":[{"id":"a","text":"G1 phase"},{"id":"b","text":"S phase"},{"id":"c","text":"G2 phase"},{"id":"d","text":"M phase"}],"answerId":"b","explanation":"DNA replication occurs during the S phase of the cell cycle.","kind":"recall","origin":"ai"},{"id":"eukaryotic-replication-telomeres~ai-3","moduleId":"eukaryotic-replication-telomeres","stem":"What is a hallmark of cancer related to telomeres?","options":[{"id":"a","text":"Increased telomere shortening"},{"id":"b","text":"Telomerase reactivation"},{"id":"c","text":"Decreased cell division"},{"id":"d","text":"Loss of chromosomal integrity"}],"answerId":"b","explanation":"Telomerase reactivation is a hallmark of cancer, allowing tumor cells to maintain telomere length and avoid senescence.","kind":"recall","origin":"ai"},{"id":"eukaryotic-replication-telomeres~ai-4","moduleId":"eukaryotic-replication-telomeres","stem":"Which statement best describes the role of cyclins and CDKs in the cell cycle?","options":[{"id":"a","text":"They initiate DNA replication at telomeres."},{"id":"b","text":"They regulate the timing of cell cycle progression."},{"id":"c","text":"They repair DNA damage during replication."},{"id":"d","text":"They synthesize RNA primers for DNA replication."}],"answerId":"b","explanation":"Cyclins and cyclin-dependent kinases (CDKs) regulate the timing of progression through the cell cycle.","kind":"mechanism","origin":"ai"},{"id":"eukaryotic-replication-telomeres~ai-5","moduleId":"eukaryotic-replication-telomeres","stem":"How does the end-replication problem relate to cellular aging?","options":[{"id":"a","text":"It leads to increased DNA repair mechanisms."},{"id":"b","text":"It results in progressive telomere shortening."},{"id":"c","text":"It activates telomerase in somatic cells."},{"id":"d","text":"It enhances cellular replication rates."}],"answerId":"b","explanation":"The end-replication problem causes progressive telomere shortening, contributing to cellular aging and senescence.","kind":"integration","linkedModuleIds":["cellular-aging-theories"],"origin":"ai"},{"id":"eukaryotic-replication-telomeres~ai-6","moduleId":"eukaryotic-replication-telomeres","stem":"Which of the following best explains the mechanism of telomerase?","options":[{"id":"a","text":"It synthesizes DNA from an RNA template."},{"id":"b","text":"It removes RNA primers from lagging strands."},{"id":"c","text":"It repairs DNA damage at telomeres."},{"id":"d","text":"It prevents the formation of Okazaki fragments."}],"answerId":"a","explanation":"Telomerase synthesizes DNA using its own RNA template, allowing it to extend telomeres.","kind":"mechanism","origin":"ai"},{"id":"eukaryotic-replication-telomeres~ai-7","moduleId":"eukaryotic-replication-telomeres","stem":"What clinical implication arises from telomerase activity in cancer cells?","options":[{"id":"a","text":"Increased susceptibility to DNA damage"},{"id":"b","text":"Enhanced replicative capacity and immortality"},{"id":"c","text":"Decreased cell proliferation"},{"id":"d","text":"Inhibition of tumor growth"}],"answerId":"b","explanation":"Telomerase activity in cancer cells enhances their replicative capacity, contributing to cellular immortality.","kind":"integration","linkedModuleIds":["sodium-water-disorders"],"origin":"ai"}],"rna-processing":[{"id":"rna-processing~ai-0","moduleId":"rna-processing","stem":"What is the primary function of the 5' cap added to eukaryotic pre-mRNA?","options":[{"id":"a","text":"It facilitates splicing of introns"},{"id":"b","text":"It stabilizes the mRNA and aids in translation initiation"},{"id":"c","text":"It signals for nuclear export"},{"id":"d","text":"It adds a poly-A tail"}],"answerId":"b","explanation":"The 5' cap stabilizes the mRNA and is essential for the initiation of translation.","kind":"recall","origin":"ai"},{"id":"rna-processing~ai-1","moduleId":"rna-processing","stem":"Which of the following is a consequence of a mutation that creates a cryptic splice site in β-globin?","options":[{"id":"a","text":"Increased production of normal β-globin"},{"id":"b","text":"Decreased production of β-globin due to aberrant splicing"},{"id":"c","text":"No effect on β-globin production"},{"id":"d","text":"Increased production of α-globin"}],"answerId":"b","explanation":"A cryptic splice site can lead to aberrant splicing, resulting in reduced normal β-globin production.","kind":"mechanism","origin":"ai"},{"id":"rna-processing~ai-2","moduleId":"rna-processing","stem":"What is removed during the splicing of pre-mRNA?","options":[{"id":"a","text":"Exons"},{"id":"b","text":"Introns"},{"id":"c","text":"Both exons and introns"},{"id":"d","text":"Neither exons nor introns"}],"answerId":"b","explanation":"Splicing removes introns (non-coding sequences) and joins exons (coding sequences) to form mature mRNA.","kind":"trap","origin":"ai"},{"id":"rna-processing~ai-3","moduleId":"rna-processing","stem":"What is the role of poly-A polymerase in mRNA processing?","options":[{"id":"a","text":"To add a 5' cap"},{"id":"b","text":"To splice introns"},{"id":"c","text":"To add a poly-A tail"},{"id":"d","text":"To degrade mRNA"}],"answerId":"c","explanation":"Poly-A polymerase adds a poly-A tail to the 3' end of mRNA, which stabilizes it and aids in nuclear export.","kind":"recall","origin":"ai"},{"id":"rna-processing~ai-4","moduleId":"rna-processing","stem":"How does nusinersen treat spinal muscular atrophy (SMA)?","options":[{"id":"a","text":"By enhancing translation of SMN1"},{"id":"b","text":"By redirecting SMN2 splicing"},{"id":"c","text":"By increasing SMN1 expression"},{"id":"d","text":"By degrading mutant SMN2 mRNA"}],"answerId":"b","explanation":"Nusinersen is an antisense oligonucleotide that redirects splicing of the SMN2 gene to produce functional SMN protein.","kind":"mechanism","origin":"ai"},{"id":"rna-processing~ai-5","moduleId":"rna-processing","stem":"Which process is directly affected by defects in splicing mechanisms?","options":[{"id":"a","text":"Transcription initiation"},{"id":"b","text":"Translation elongation"},{"id":"c","text":"Protein folding"},{"id":"d","text":"Gene expression regulation"}],"answerId":"a","explanation":"Defects in splicing can lead to improper mRNA production, affecting gene expression and protein synthesis.","kind":"clinical","origin":"ai"},{"id":"rna-processing~ai-6","moduleId":"rna-processing","stem":"How does the mechanism of RNA processing relate to antigen presentation pathways?","options":[{"id":"a","text":"Both processes involve protein degradation"},{"id":"b","text":"Both processes require RNA splicing"},{"id":"c","text":"RNA processing affects the expression of antigens"},{"id":"d","text":"Both processes occur in the cytoplasm"}],"answerId":"c","explanation":"RNA processing affects the expression of antigens by ensuring proper mRNA is translated into proteins that can be presented by MHC molecules.","kind":"integration","linkedModuleIds":["antigen-processing-presentation"],"origin":"ai"},{"id":"rna-processing~ai-7","moduleId":"rna-processing","stem":"Which step in RNA processing is most similar to the mechanisms of transcription initiation?","options":[{"id":"a","text":"5' capping"},{"id":"b","text":"Splicing"},{"id":"c","text":"Polyadenylation"},{"id":"d","text":"Intron removal"}],"answerId":"a","explanation":"5' capping is similar to transcription initiation as both processes are crucial for mRNA stability and translation initiation.","kind":"integration","linkedModuleIds":["transcription-mechanism"],"origin":"ai"}],"nucleotide-drugs-disorders":[{"id":"nucleotide-drugs-disorders~ai-0","moduleId":"nucleotide-drugs-disorders","stem":"Which drug inhibits dihydrofolate reductase, thereby blocking nucleotide synthesis?","options":[{"id":"a","text":"Methotrexate"},{"id":"b","text":"5-Fluorouracil"},{"id":"c","text":"Hydroxyurea"},{"id":"d","text":"6-Mercaptopurine"}],"answerId":"a","explanation":"Methotrexate inhibits dihydrofolate reductase, leading to decreased levels of tetrahydrofolate and subsequent reduction in purine and dTMP synthesis.","kind":"recall","origin":"ai"},{"id":"nucleotide-drugs-disorders~ai-1","moduleId":"nucleotide-drugs-disorders","stem":"What is the primary mechanism of action of mycophenolate?","options":[{"id":"a","text":"Inhibition of thymidylate synthase"},{"id":"b","text":"Inhibition of IMP dehydrogenase"},{"id":"c","text":"Inhibition of ribonucleotide reductase"},{"id":"d","text":"Inhibition of dihydrofolate reductase"}],"answerId":"b","explanation":"Mycophenolate inhibits IMP dehydrogenase, which decreases GMP synthesis, crucial for lymphocyte proliferation.","kind":"mechanism","origin":"ai"},{"id":"nucleotide-drugs-disorders~ai-2","moduleId":"nucleotide-drugs-disorders","stem":"A 2-month-old infant presents with recurrent infections and failure to thrive. Laboratory tests show elevated dATP levels. What is the most likely diagnosis?","options":[{"id":"a","text":"Orotic aciduria"},{"id":"b","text":"Adenosine deaminase deficiency"},{"id":"c","text":"Severe combined immunodeficiency"},{"id":"d","text":"Hyperimmunoglobulin E syndrome"}],"answerId":"b","explanation":"The accumulation of dATP due to adenosine deaminase deficiency inhibits ribonucleotide reductase, leading to severe combined immunodeficiency.","kind":"clinical","origin":"ai"},{"id":"nucleotide-drugs-disorders~ai-3","moduleId":"nucleotide-drugs-disorders","stem":"Which condition is characterized by megaloblastic anemia unresponsive to B12/folate and orotic acid in the urine?","options":[{"id":"a","text":"Adenosine deaminase deficiency"},{"id":"b","text":"Orotic aciduria"},{"id":"c","text":"Sideroblastic anemia"},{"id":"d","text":"Iron deficiency anemia"}],"answerId":"b","explanation":"Orotic aciduria is due to UMP synthase deficiency, leading to megaloblastic anemia that does not respond to B12 or folate.","kind":"clinical","origin":"ai"},{"id":"nucleotide-drugs-disorders~ai-4","moduleId":"nucleotide-drugs-disorders","stem":"In a patient with orotic aciduria, which of the following findings would help distinguish it from ornithine transcarbamylase deficiency?","options":[{"id":"a","text":"Hyperammonemia"},{"id":"b","text":"Megaloblastic anemia"},{"id":"c","text":"Elevated dATP"},{"id":"d","text":"Recurrent infections"}],"answerId":"a","explanation":"Ornithine transcarbamylase deficiency is associated with hyperammonemia, while orotic aciduria does not present with this finding.","kind":"trap","origin":"ai"},{"id":"nucleotide-drugs-disorders~ai-5","moduleId":"nucleotide-drugs-disorders","stem":"How does hydroxyurea exert its therapeutic effect in cancer treatment?","options":[{"id":"a","text":"Inhibits thymidylate synthase"},{"id":"b","text":"Inhibits ribonucleotide reductase"},{"id":"c","text":"Inhibits dihydrofolate reductase"},{"id":"d","text":"Inhibits IMP dehydrogenase"}],"answerId":"b","explanation":"Hydroxyurea inhibits ribonucleotide reductase, leading to a decrease in deoxyribonucleotides and thus affecting DNA synthesis in rapidly dividing cells.","kind":"mechanism","origin":"ai"},{"id":"nucleotide-drugs-disorders~ai-6","moduleId":"nucleotide-drugs-disorders","stem":"Which nucleotide drug is commonly used as a DMARD in rheumatoid arthritis?","options":[{"id":"a","text":"Methotrexate"},{"id":"b","text":"Mycophenolate"},{"id":"c","text":"5-Fluorouracil"},{"id":"d","text":"Hydroxyurea"}],"answerId":"a","explanation":"Methotrexate is a commonly used disease-modifying antirheumatic drug (DMARD) that inhibits nucleotide synthesis.","kind":"integration","linkedModuleIds":["rheumatoid-arthritis-drugs"],"origin":"ai"},{"id":"nucleotide-drugs-disorders~ai-7","moduleId":"nucleotide-drugs-disorders","stem":"What is the role of nucleotide analogs in antiviral therapy?","options":[{"id":"a","text":"Inhibit ribonucleotide reductase"},{"id":"b","text":"Inhibit dihydrofolate reductase"},{"id":"c","text":"Mimic natural nucleotides"},{"id":"d","text":"Inhibit thymidylate synthase"}],"answerId":"c","explanation":"Nucleotide analogs mimic natural nucleotides and are used to inhibit viral replication by interfering with nucleic acid synthesis.","kind":"integration","linkedModuleIds":["nucleotide-degradation-gout"],"origin":"ai"}],"dna-replication-machinery":[{"id":"dna-replication-machinery~ai-0","moduleId":"dna-replication-machinery","stem":"Which enzyme is responsible for synthesizing RNA primers during DNA replication?","options":[{"id":"a","text":"DNA polymerase I"},{"id":"b","text":"Helicase"},{"id":"c","text":"Primase"},{"id":"d","text":"Ligase"}],"answerId":"c","explanation":"Primase lays down RNA primers necessary for DNA polymerase to initiate synthesis.","kind":"recall","origin":"ai"},{"id":"dna-replication-machinery~ai-1","moduleId":"dna-replication-machinery","stem":"What is the primary role of DNA polymerase III during DNA replication?","options":[{"id":"a","text":"Removing RNA primers"},{"id":"b","text":"Synthesizing DNA"},{"id":"c","text":"Unwinding the DNA helix"},{"id":"d","text":"Sealing nicks in the DNA"}],"answerId":"b","explanation":"DNA polymerase III is the main enzyme responsible for synthesizing new DNA strands.","kind":"recall","origin":"ai"},{"id":"dna-replication-machinery~ai-2","moduleId":"dna-replication-machinery","stem":"Which statement correctly describes the direction of DNA synthesis?","options":[{"id":"a","text":"DNA polymerase synthesizes in the 3′→5′ direction"},{"id":"b","text":"DNA synthesis occurs in both directions from the origin"},{"id":"c","text":"DNA polymerase ALWAYS synthesizes 5′→3′"},{"id":"d","text":"Okazaki fragments are synthesized in the 3′→5′ direction"}],"answerId":"c","explanation":"DNA polymerase can only add nucleotides in the 5′→3′ direction, regardless of the strand being synthesized.","kind":"trap","origin":"ai"},{"id":"dna-replication-machinery~ai-3","moduleId":"dna-replication-machinery","stem":"What mechanism allows DNA polymerase to maintain high fidelity during replication?","options":[{"id":"a","text":"Proofreading with 5′→3′ exonuclease activity"},{"id":"b","text":"Proofreading with 3′→5′ exonuclease activity"},{"id":"c","text":"Use of RNA primers"},{"id":"d","text":"Formation of Okazaki fragments"}],"answerId":"b","explanation":"DNA polymerase has 3′→5′ exonuclease activity that allows it to excise incorrectly incorporated nucleotides.","kind":"mechanism","origin":"ai"},{"id":"dna-replication-machinery~ai-4","moduleId":"dna-replication-machinery","stem":"In E. coli, what is the role of topoisomerase during DNA replication?","options":[{"id":"a","text":"Unwinds the DNA double helix"},{"id":"b","text":"Relieves supercoiling ahead of the replication fork"},{"id":"c","text":"Synthesizes RNA primers"},{"id":"d","text":"Seals nicks between Okazaki fragments"}],"answerId":"b","explanation":"Topoisomerase relieves the torsional strain generated ahead of the replication fork by introducing negative supercoils.","kind":"recall","origin":"ai"},{"id":"dna-replication-machinery~ai-5","moduleId":"dna-replication-machinery","stem":"How does the mechanism of DNA replication differ between prokaryotes and eukaryotes?","options":[{"id":"a","text":"Eukaryotes use RNA primers, prokaryotes do not"},{"id":"b","text":"Eukaryotic replication involves telomeres, prokaryotic does not"},{"id":"c","text":"Prokaryotes have multiple origins of replication, eukaryotes have one"},{"id":"d","text":"Eukaryotic DNA polymerases have no proofreading ability"}],"answerId":"b","explanation":"Eukaryotic replication involves telomeres to prevent loss of DNA at the ends of linear chromosomes, while prokaryotic DNA is circular and does not have this issue.","kind":"integration","linkedModuleIds":["eukaryotic-replication-telomeres"],"origin":"ai"},{"id":"dna-replication-machinery~ai-6","moduleId":"dna-replication-machinery","stem":"What is a key difference in the synthesis of leading and lagging strands during DNA replication?","options":[{"id":"a","text":"Leading strand is synthesized in fragments, lagging strand continuously"},{"id":"b","text":"Leading strand requires RNA primers, lagging strand does not"},{"id":"c","text":"Leading strand is synthesized continuously, lagging strand in fragments"},{"id":"d","text":"Leading strand synthesis occurs in the 3′→5′ direction"}],"answerId":"c","explanation":"The leading strand is synthesized continuously in the 5′→3′ direction, while the lagging strand is synthesized in short 5′→3′ Okazaki fragments.","kind":"integration","linkedModuleIds":["eukaryotic-replication-telomeres"],"origin":"ai"}],"chromatin-packaging":[{"id":"chromatin-packaging~ai-0","moduleId":"chromatin-packaging","stem":"What is the primary function of histone proteins in chromatin packaging?","options":[{"id":"a","text":"To provide energy for DNA replication"},{"id":"b","text":"To bind and compact DNA"},{"id":"c","text":"To catalyze transcription"},{"id":"d","text":"To repair DNA damage"}],"answerId":"b","explanation":"Histone proteins bind to DNA and help compact it into nucleosomes, facilitating chromatin structure.","kind":"recall","origin":"ai"},{"id":"chromatin-packaging~ai-1","moduleId":"chromatin-packaging","stem":"Which histone is known as the linker histone in the nucleosome structure?","options":[{"id":"a","text":"H2A"},{"id":"b","text":"H2B"},{"id":"c","text":"H3"},{"id":"d","text":"H1"}],"answerId":"d","explanation":"Histone H1 is the linker histone that helps compact the nucleosome structure into higher-order chromatin.","kind":"recall","origin":"ai"},{"id":"chromatin-packaging~ai-2","moduleId":"chromatin-packaging","stem":"What is the characteristic feature of euchromatin?","options":[{"id":"a","text":"Highly condensed and transcriptionally inactive"},{"id":"b","text":"Decondensed and transcriptionally active"},{"id":"c","text":"Rich in repetitive sequences"},{"id":"d","text":"Located at the centromere of chromosomes"}],"answerId":"b","explanation":"Euchromatin is characterized by its decondensed structure, allowing for active transcription.","kind":"recall","origin":"ai"},{"id":"chromatin-packaging~ai-3","moduleId":"chromatin-packaging","stem":"Which of the following best describes heterochromatin?","options":[{"id":"a","text":"Transcriptionally active regions of the genome"},{"id":"b","text":"Condensed regions with silenced genes"},{"id":"c","text":"Regions rich in histone H1"},{"id":"d","text":"Areas involved in DNA replication"}],"answerId":"b","explanation":"Heterochromatin is condensed and typically associated with silenced genes, contrasting with euchromatin.","kind":"recall","origin":"ai"},{"id":"chromatin-packaging~ai-4","moduleId":"chromatin-packaging","stem":"What is the composition of the nucleosome core octamer?","options":[{"id":"a","text":"Two copies each of H2A, H2B, H3, H4"},{"id":"b","text":"One copy each of H1, H2A, H2B, H3, H4"},{"id":"c","text":"Two copies of H1 and one each of H2A, H2B, H3, H4"},{"id":"d","text":"Four copies of H2A and two of H3"}],"answerId":"a","explanation":"The nucleosome core octamer consists of two copies each of histones H2A, H2B, H3, and H4.","kind":"trap","origin":"ai"},{"id":"chromatin-packaging~ai-5","moduleId":"chromatin-packaging","stem":"Which structure is formed by the looping of chromatin fibers anchored to scaffold proteins?","options":[{"id":"a","text":"Nucleosome"},{"id":"b","text":"30-nm fiber"},{"id":"c","text":"Chromosome"},{"id":"d","text":"Euchromatin"}],"answerId":"c","explanation":"Looped domains of chromatin fibers anchored to scaffold proteins form the structural organization of chromosomes.","kind":"recall","origin":"ai"},{"id":"chromatin-packaging~ai-6","moduleId":"chromatin-packaging","stem":"How does chromatin packaging affect gene expression?","options":[{"id":"a","text":"Tightly packed DNA is more accessible for transcription"},{"id":"b","text":"Decondensed chromatin allows for active transcription"},{"id":"c","text":"Histones inhibit all transcription processes"},{"id":"d","text":"Euchromatin is always silenced"}],"answerId":"b","explanation":"Decondensed chromatin (euchromatin) allows for active transcription, while condensed chromatin (heterochromatin) typically silences genes.","kind":"clinical","origin":"ai"},{"id":"chromatin-packaging~ai-7","moduleId":"chromatin-packaging","stem":"How does chromatin packaging relate to DNA structure?","options":[{"id":"a","text":"Chromatin is a form of RNA"},{"id":"b","text":"Chromatin is composed of proteins only"},{"id":"c","text":"Chromatin packaging is essential for DNA replication"},{"id":"d","text":"Chromatin allows DNA to fit within the nucleus"}],"answerId":"d","explanation":"Chromatin packaging condenses DNA to fit within the nucleus while maintaining gene accessibility, linking DNA structure to cellular organization.","kind":"integration","linkedModuleIds":["dna-structure-forms"],"origin":"ai"},{"id":"chromatin-packaging~ai-8","moduleId":"chromatin-packaging","stem":"What role does chromatin play in the nucleus's function?","options":[{"id":"a","text":"It serves as a barrier to transcription"},{"id":"b","text":"It facilitates DNA repair processes"},{"id":"c","text":"It organizes DNA for efficient replication and transcription"},{"id":"d","text":"It is involved in protein synthesis"}],"answerId":"c","explanation":"Chromatin organizes DNA in the nucleus, allowing for efficient replication and transcription, linking chromatin packaging to nuclear function.","kind":"integration","linkedModuleIds":["nucleus-chromatin-nucleolus"],"origin":"ai"}],"purine-pyrimidine-synthesis":[{"id":"purine-pyrimidine-synthesis~ai-0","moduleId":"purine-pyrimidine-synthesis","stem":"Which enzyme catalyzes the first step in purine de novo synthesis?","options":[{"id":"a","text":"PRPP synthetase"},{"id":"b","text":"Glutamine-PRPP amidotransferase"},{"id":"c","text":"Adenylosuccinate synthetase"},{"id":"d","text":"Thymidylate synthase"}],"answerId":"b","explanation":"Glutamine-PRPP amidotransferase catalyzes the conversion of PRPP to 5-phosphoribosylamine, the first committed step in purine synthesis.","kind":"recall","origin":"ai"},{"id":"purine-pyrimidine-synthesis~ai-1","moduleId":"purine-pyrimidine-synthesis","stem":"What is the primary role of ribonucleotide reductase?","options":[{"id":"a","text":"Convert ribonucleotides to deoxyribonucleotides"},{"id":"b","text":"Synthesize purine nucleotides"},{"id":"c","text":"Methylate dUMP to dTMP"},{"id":"d","text":"Reattach bases to PRPP"}],"answerId":"a","explanation":"Ribonucleotide reductase reduces ribonucleotides (NDPs) to deoxyribonucleotides (dNDPs), crucial for DNA synthesis.","kind":"mechanism","origin":"ai"},{"id":"purine-pyrimidine-synthesis~ai-2","moduleId":"purine-pyrimidine-synthesis","stem":"In pyrimidine synthesis, which compound is formed first before attaching to ribose?","options":[{"id":"a","text":"UMP"},{"id":"b","text":"OMP"},{"id":"c","text":"Orotate"},{"id":"d","text":"CTP"}],"answerId":"c","explanation":"In pyrimidine synthesis, orotate is formed first and then attached to ribose to form UMP.","kind":"recall","origin":"ai"},{"id":"purine-pyrimidine-synthesis~ai-3","moduleId":"purine-pyrimidine-synthesis","stem":"Which of the following statements about purine and pyrimidine synthesis is correct?","options":[{"id":"a","text":"Both pathways build the ring on PRPP"},{"id":"b","text":"Purine rings are built on PRPP, pyrimidine rings are built first"},{"id":"c","text":"Pyrimidine synthesis requires ATP for all steps"},{"id":"d","text":"AMP and GMP do not inhibit their own synthesis"}],"answerId":"b","explanation":"Purine rings are assembled on PRPP, while pyrimidine rings are synthesized first and then attached to PRPP.","kind":"trap","origin":"ai"},{"id":"purine-pyrimidine-synthesis~ai-4","moduleId":"purine-pyrimidine-synthesis","stem":"What is the feedback mechanism for AMP and GMP synthesis?","options":[{"id":"a","text":"AMP inhibits PRPP synthetase"},{"id":"b","text":"GMP inhibits adenylosuccinate synthetase"},{"id":"c","text":"Both AMP and GMP inhibit their own synthesis"},{"id":"d","text":"IMP activates GMP synthesis"}],"answerId":"c","explanation":"AMP and GMP both inhibit their own synthesis, maintaining balanced nucleotide pools.","kind":"recall","origin":"ai"},{"id":"purine-pyrimidine-synthesis~ai-5","moduleId":"purine-pyrimidine-synthesis","stem":"How does folate contribute to thymidylate synthesis?","options":[{"id":"a","text":"It donates ribose"},{"id":"b","text":"It donates a methyl group"},{"id":"c","text":"It is a substrate for dUMP"},{"id":"d","text":"It activates dTMP"}],"answerId":"b","explanation":"Folate, in the form of N⁵,N¹⁰-methylene-THF, donates a methyl group to convert dUMP to dTMP.","kind":"mechanism","origin":"ai"},{"id":"purine-pyrimidine-synthesis~ai-6","moduleId":"purine-pyrimidine-synthesis","stem":"Which of the following best explains the connection between purine metabolism and gout?","options":[{"id":"a","text":"Increased PRPP leads to uric acid overproduction"},{"id":"b","text":"AMP synthesis is inhibited"},{"id":"c","text":"Decreased salvage pathway activity"},{"id":"d","text":"Increased dTMP synthesis"}],"answerId":"a","explanation":"In gout, increased PRPP levels promote excessive purine degradation, leading to elevated uric acid levels.","kind":"integration","linkedModuleIds":["nucleotide-degradation-gout"],"origin":"ai"},{"id":"purine-pyrimidine-synthesis~ai-7","moduleId":"purine-pyrimidine-synthesis","stem":"Which drug targets the salvage pathway for purine nucleotides?","options":[{"id":"a","text":"Methotrexate"},{"id":"b","text":"Allopurinol"},{"id":"c","text":"5-Fluorouracil"},{"id":"d","text":"Adenosine"}],"answerId":"b","explanation":"Allopurinol inhibits xanthine oxidase, reducing uric acid production and affecting purine metabolism.","kind":"integration","linkedModuleIds":["nucleotide-drugs-disorders"],"origin":"ai"}],"rna-types":[{"id":"rna-types~ai-0","moduleId":"rna-types","stem":"Which of the following statements correctly describes a key difference between RNA and DNA?","options":[{"id":"a","text":"RNA contains deoxyribose, while DNA contains ribose."},{"id":"b","text":"RNA is typically double-stranded, while DNA is single-stranded."},{"id":"c","text":"RNA uses uracil instead of thymine, while DNA uses thymine."},{"id":"d","text":"RNA is more stable than DNA."}],"answerId":"c","explanation":"RNA contains uracil in place of thymine, which is a distinguishing feature from DNA.","kind":"recall","origin":"ai"},{"id":"rna-types~ai-1","moduleId":"rna-types","stem":"What is the primary function of mRNA in the cell?","options":[{"id":"a","text":"To provide structural support in ribosomes."},{"id":"b","text":"To deliver amino acids to the ribosome."},{"id":"c","text":"To carry genetic information from DNA to the ribosome."},{"id":"d","text":"To regulate gene expression."}],"answerId":"c","explanation":"mRNA serves as the messenger carrying genetic information from DNA to the ribosome for protein synthesis.","kind":"recall","origin":"ai"},{"id":"rna-types~ai-2","moduleId":"rna-types","stem":"Which type of RNA is primarily responsible for the catalytic activity during protein synthesis?","options":[{"id":"a","text":"mRNA"},{"id":"b","text":"tRNA"},{"id":"c","text":"rRNA"},{"id":"d","text":"snRNA"}],"answerId":"c","explanation":"rRNA is the catalytic component of the ribosome, facilitating peptide bond formation during translation.","kind":"recall","origin":"ai"},{"id":"rna-types~ai-3","moduleId":"rna-types","stem":"A patient presents with a genetic disorder due to a mutation affecting splicing. Which type of RNA is most likely involved?","options":[{"id":"a","text":"mRNA"},{"id":"b","text":"tRNA"},{"id":"c","text":"rRNA"},{"id":"d","text":"snRNA"}],"answerId":"d","explanation":"snRNA is involved in the splicing of pre-mRNA, and mutations affecting this process can lead to splicing disorders.","kind":"clinical","origin":"ai"},{"id":"rna-types~ai-4","moduleId":"rna-types","stem":"Which of the following statements about rRNA is true?","options":[{"id":"a","text":"rRNA is the most abundant RNA in the cell."},{"id":"b","text":"rRNA is responsible for transporting amino acids."},{"id":"c","text":"rRNA is primarily involved in gene regulation."},{"id":"d","text":"rRNA is synthesized in the cytoplasm."}],"answerId":"a","explanation":"rRNA constitutes the majority of RNA in the cell, forming the core of ribosomes, which are essential for protein synthesis.","kind":"trap","origin":"ai"},{"id":"rna-types~ai-5","moduleId":"rna-types","stem":"How does the structure of RNA contribute to its diverse functions?","options":[{"id":"a","text":"Its double-stranded nature allows for stable storage of genetic information."},{"id":"b","text":"Its single-stranded form enables self-complementary pairing and diverse secondary structures."},{"id":"c","text":"Its linear structure prevents interactions with proteins."},{"id":"d","text":"Its ribose sugar enhances its stability compared to DNA."}],"answerId":"b","explanation":"The single-stranded nature of RNA allows it to fold into various secondary structures, which is crucial for its multiple functions.","kind":"mechanism","origin":"ai"},{"id":"rna-types~ai-6","moduleId":"rna-types","stem":"How are RNA types integrated with nucleotide structure and roles?","options":[{"id":"a","text":"All RNA types are synthesized from ribonucleotides containing deoxyribose."},{"id":"b","text":"RNA types differ in their nucleotide sequences but share the same ribose sugar."},{"id":"c","text":"Only mRNA contains uracil, while tRNA and rRNA contain thymine."},{"id":"d","text":"Nucleotides in RNA do not play a role in its secondary structure."}],"answerId":"b","explanation":"All RNA types are synthesized from ribonucleotides, which contain ribose, and their sequences determine their specific functions.","kind":"integration","linkedModuleIds":["nucleotides-structure-roles"],"origin":"ai"},{"id":"rna-types~ai-7","moduleId":"rna-types","stem":"Which RNA type's function is most directly related to sensory receptor signaling pathways?","options":[{"id":"a","text":"mRNA"},{"id":"b","text":"tRNA"},{"id":"c","text":"miRNA"},{"id":"d","text":"rRNA"}],"answerId":"c","explanation":"miRNA plays a role in regulating gene expression, which can influence sensory receptor signaling pathways.","kind":"integration","linkedModuleIds":["sensory-receptors-transduction"],"origin":"ai"}],"dna-repair-mechanisms":[{"id":"dna-repair-mechanisms~ai-0","moduleId":"dna-repair-mechanisms","stem":"Which DNA repair mechanism is primarily responsible for fixing single abnormal bases?","options":[{"id":"a","text":"Base-excision repair (BER)"},{"id":"b","text":"Nucleotide-excision repair (NER)"},{"id":"c","text":"Mismatch repair (MMR)"},{"id":"d","text":"Homologous recombination (HR)"}],"answerId":"a","explanation":"Base-excision repair (BER) specifically targets and repairs single abnormal bases in DNA.","kind":"recall","origin":"ai"},{"id":"dna-repair-mechanisms~ai-1","moduleId":"dna-repair-mechanisms","stem":"What is the primary defect in Xeroderma pigmentosum?","options":[{"id":"a","text":"Mismatch repair"},{"id":"b","text":"Base-excision repair"},{"id":"c","text":"Nucleotide-excision repair"},{"id":"d","text":"Translesion synthesis"}],"answerId":"c","explanation":"Xeroderma pigmentosum is caused by defects in nucleotide-excision repair (NER), leading to an inability to repair UV-induced DNA damage.","kind":"recall","origin":"ai"},{"id":"dna-repair-mechanisms~ai-2","moduleId":"dna-repair-mechanisms","stem":"Which mechanism is error-prone and operates primarily in the G1 phase of the cell cycle?","options":[{"id":"a","text":"Homologous recombination"},{"id":"b","text":"Nucleotide-excision repair"},{"id":"c","text":"Non-homologous end-joining"},{"id":"d","text":"Base-excision repair"}],"answerId":"c","explanation":"Non-homologous end-joining (NHEJ) is an error-prone repair mechanism that operates primarily during the G1 phase.","kind":"recall","origin":"ai"},{"id":"dna-repair-mechanisms~ai-3","moduleId":"dna-repair-mechanisms","stem":"A patient presents with early colorectal cancer and microsatellite instability. Which DNA repair defect is most likely responsible?","options":[{"id":"a","text":"Xeroderma pigmentosum"},{"id":"b","text":"Lynch syndrome"},{"id":"c","text":"Cockayne syndrome"},{"id":"d","text":"BRCA1/2 mutation"}],"answerId":"b","explanation":"Lynch syndrome is characterized by early colorectal cancer and is caused by defects in mismatch repair (MMR).","kind":"clinical","origin":"ai"},{"id":"dna-repair-mechanisms~ai-4","moduleId":"dna-repair-mechanisms","stem":"What is the primary role of translesion synthesis (TLS) in DNA repair?","options":[{"id":"a","text":"Accurate repair of double-strand breaks"},{"id":"b","text":"Repair of single abnormal bases"},{"id":"c","text":"Replication past DNA lesions"},{"id":"d","text":"Removal of bulky DNA adducts"}],"answerId":"c","explanation":"Translesion synthesis (TLS) allows specialized polymerases to replicate past DNA lesions, although it is error-prone.","kind":"mechanism","origin":"ai"},{"id":"dna-repair-mechanisms~ai-5","moduleId":"dna-repair-mechanisms","stem":"Which statement correctly differentiates homologous recombination from non-homologous end-joining?","options":[{"id":"a","text":"Both are equally accurate in repairing double-strand breaks"},{"id":"b","text":"Homologous recombination uses the sister chromatid, while NHEJ does not"},{"id":"c","text":"NHEJ is more accurate than homologous recombination"},{"id":"d","text":"Both mechanisms operate in the S phase"}],"answerId":"b","explanation":"Homologous recombination is accurate as it uses the sister chromatid as a template, while non-homologous end-joining is error-prone.","kind":"trap","origin":"ai"},{"id":"dna-repair-mechanisms~ai-6","moduleId":"dna-repair-mechanisms","stem":"How does a defect in BRCA1/2 lead to hereditary breast cancer?","options":[{"id":"a","text":"Impaired base-excision repair"},{"id":"b","text":"Defective homologous recombination"},{"id":"c","text":"Ineffective nucleotide-excision repair"},{"id":"d","text":"Faulty translesion synthesis"}],"answerId":"b","explanation":"BRCA1/2 mutations impair homologous recombination, leading to an increased risk of breast and ovarian cancers.","kind":"recall","origin":"ai"},{"id":"dna-repair-mechanisms~ai-7","moduleId":"dna-repair-mechanisms","stem":"Which DNA repair mechanism is linked to mutations in the human genome that cause hereditary colorectal cancer?","options":[{"id":"a","text":"Nucleotide-excision repair"},{"id":"b","text":"Mismatch repair"},{"id":"c","text":"Base-excision repair"},{"id":"d","text":"Translesion synthesis"}],"answerId":"b","explanation":"Defects in mismatch repair (MMR) are associated with hereditary colorectal cancer, specifically Lynch syndrome.","kind":"integration","linkedModuleIds":["mutations-dna-damage"],"origin":"ai"},{"id":"dna-repair-mechanisms~ai-8","moduleId":"dna-repair-mechanisms","stem":"Which DNA repair mechanism is most affected by UV-induced damage, leading to skin cancer?","options":[{"id":"a","text":"Base-excision repair"},{"id":"b","text":"Nucleotide-excision repair"},{"id":"c","text":"Mismatch repair"},{"id":"d","text":"Homologous recombination"}],"answerId":"b","explanation":"Nucleotide-excision repair (NER) is crucial for repairing UV-induced lesions, and its defect leads to conditions like Xeroderma pigmentosum.","kind":"integration","linkedModuleIds":["human-genome-organization"],"origin":"ai"}],"nucleotide-degradation-gout":[{"id":"nucleotide-degradation-gout~ai-0","moduleId":"nucleotide-degradation-gout","stem":"What is the primary metabolic pathway for purine degradation leading to uric acid?","options":[{"id":"a","text":"Adenosine → Inosine → Hypoxanthine → Xanthine → Uric acid"},{"id":"b","text":"Adenosine → AMP → IMP → Uric acid"},{"id":"c","text":"Hypoxanthine → Xanthine → Uric acid"},{"id":"d","text":"Guanosine → GMP → Uric acid"}],"answerId":"a","explanation":"Purines degrade through the pathway: adenosine → inosine → hypoxanthine → xanthine → uric acid.","kind":"recall","origin":"ai"},{"id":"nucleotide-degradation-gout~ai-1","moduleId":"nucleotide-degradation-gout","stem":"Which of the following is the most common cause of hyperuricemia?","options":[{"id":"a","text":"Overproduction of uric acid"},{"id":"b","text":"Underexcretion of urate"},{"id":"c","text":"Dietary purine intake"},{"id":"d","text":"Increased xanthine oxidase activity"}],"answerId":"b","explanation":"Underexcretion of urate is the most common cause of hyperuricemia, while overproduction is less common.","kind":"trap","origin":"ai"},{"id":"nucleotide-degradation-gout~ai-2","moduleId":"nucleotide-degradation-gout","stem":"Which clinical finding is characteristic of acute gout?","options":[{"id":"a","text":"Bilateral knee swelling"},{"id":"b","text":"Acute monoarthritis of the first MTP joint"},{"id":"c","text":"Chronic joint pain"},{"id":"d","text":"Erythema over the elbow"}],"answerId":"b","explanation":"Acute gout typically presents as acute monoarthritis, often affecting the first MTP joint (podagra).","kind":"clinical","origin":"ai"},{"id":"nucleotide-degradation-gout~ai-3","moduleId":"nucleotide-degradation-gout","stem":"What type of crystals are found in joint fluid during a gout attack?","options":[{"id":"a","text":"Positively birefringent needle-shaped crystals"},{"id":"b","text":"Negatively birefringent needle-shaped crystals"},{"id":"c","text":"Rhomboid-shaped crystals"},{"id":"d","text":"Amorphous urate crystals"}],"answerId":"b","explanation":"Gout is characterized by negatively birefringent needle-shaped crystals of monosodium urate in joint fluid.","kind":"recall","origin":"ai"},{"id":"nucleotide-degradation-gout~ai-4","moduleId":"nucleotide-degradation-gout","stem":"In Lesch-Nyhan syndrome, what is the primary defect?","options":[{"id":"a","text":"Xanthine oxidase deficiency"},{"id":"b","text":"Adenosine deaminase deficiency"},{"id":"c","text":"HGPRT deficiency"},{"id":"d","text":"PRPP synthetase overactivity"}],"answerId":"c","explanation":"Lesch-Nyhan syndrome is caused by a deficiency of HGPRT, leading to increased uric acid production.","kind":"recall","origin":"ai"},{"id":"nucleotide-degradation-gout~ai-5","moduleId":"nucleotide-degradation-gout","stem":"How does allopurinol help in the management of chronic gout?","options":[{"id":"a","text":"Increases urate excretion"},{"id":"b","text":"Inhibits xanthine oxidase"},{"id":"c","text":"Stimulates purine synthesis"},{"id":"d","text":"Reduces inflammation"}],"answerId":"b","explanation":"Allopurinol inhibits xanthine oxidase, decreasing uric acid production and helping manage chronic gout.","kind":"mechanism","origin":"ai"},{"id":"nucleotide-degradation-gout~ai-6","moduleId":"nucleotide-degradation-gout","stem":"Which drug class is used to increase renal excretion of urate in gout management?","options":[{"id":"a","text":"Xanthine oxidase inhibitors"},{"id":"b","text":"Uricosurics"},{"id":"c","text":"NSAIDs"},{"id":"d","text":"Corticosteroids"}],"answerId":"b","explanation":"Uricosurics, such as probenecid, increase renal excretion of urate, helping to manage gout.","kind":"clinical","origin":"ai"},{"id":"nucleotide-degradation-gout~ai-7","moduleId":"nucleotide-degradation-gout","stem":"How does the mechanism of gout relate to purine synthesis disorders?","options":[{"id":"a","text":"Increased purine synthesis leads to decreased uric acid"},{"id":"b","text":"Decreased purine synthesis causes hyperuricemia"},{"id":"c","text":"Increased purine degradation leads to uric acid accumulation"},{"id":"d","text":"Defective purine salvage pathways can lead to gout"}],"answerId":"d","explanation":"Defective purine salvage pathways, such as in HGPRT deficiency, lead to increased de novo purine synthesis and subsequent hyperuricemia.","kind":"integration","linkedModuleIds":["purine-pyrimidine-synthesis"],"origin":"ai"},{"id":"nucleotide-degradation-gout~ai-8","moduleId":"nucleotide-degradation-gout","stem":"What is the relationship between lactic acidosis and hyperuricemia in gout?","options":[{"id":"a","text":"Lactic acidosis increases urate excretion"},{"id":"b","text":"Lactic acidosis decreases urate production"},{"id":"c","text":"Lactic acidosis leads to decreased renal excretion of urate"},{"id":"d","text":"Lactic acidosis has no effect on urate levels"}],"answerId":"c","explanation":"Lactic acidosis can decrease renal excretion of urate, contributing to hyperuricemia in gout.","kind":"integration","linkedModuleIds":["hfi-metabolic-complications"],"origin":"ai"}],"cloning-pcr-sequencing":[{"id":"cloning-pcr-sequencing~ai-0","moduleId":"cloning-pcr-sequencing","stem":"What is the primary purpose of using Taq polymerase in PCR?","options":[{"id":"a","text":"To reverse transcribe RNA into cDNA"},{"id":"b","text":"To amplify DNA segments"},{"id":"c","text":"To cut DNA at specific sites"},{"id":"d","text":"To label DNA fragments with fluorescent dyes"}],"answerId":"b","explanation":"Taq polymerase is a heat-stable enzyme that synthesizes new DNA strands during the amplification process in PCR.","kind":"recall","origin":"ai"},{"id":"cloning-pcr-sequencing~ai-1","moduleId":"cloning-pcr-sequencing","stem":"Which step in PCR involves the binding of primers to the target DNA?","options":[{"id":"a","text":"Denaturation"},{"id":"b","text":"Extension"},{"id":"c","text":"Annealing"},{"id":"d","text":"Amplification"}],"answerId":"c","explanation":"During the annealing step, primers bind to the complementary sequences on the target DNA.","kind":"mechanism","origin":"ai"},{"id":"cloning-pcr-sequencing~ai-2","moduleId":"cloning-pcr-sequencing","stem":"What is the result of performing STR analysis?","options":[{"id":"a","text":"Amplified RNA segments"},{"id":"b","text":"Recombinant DNA"},{"id":"c","text":"Individual-specific DNA profile"},{"id":"d","text":"Quantified viral load"}],"answerId":"c","explanation":"STR analysis generates a unique DNA profile for individuals based on variations in microsatellite loci.","kind":"recall","origin":"ai"},{"id":"cloning-pcr-sequencing~ai-3","moduleId":"cloning-pcr-sequencing","stem":"Which statement correctly describes the use of RT-PCR?","options":[{"id":"a","text":"It amplifies DNA directly from RNA"},{"id":"b","text":"It requires reverse transcription of RNA to cDNA"},{"id":"c","text":"It is used solely for DNA profiling"},{"id":"d","text":"It cannot quantify RNA levels"}],"answerId":"b","explanation":"RT-PCR is specifically designed to convert RNA into cDNA before amplification, allowing for RNA detection.","kind":"trap","origin":"ai"},{"id":"cloning-pcr-sequencing~ai-4","moduleId":"cloning-pcr-sequencing","stem":"How does Sanger sequencing determine the DNA sequence?","options":[{"id":"a","text":"By using fluorescently labeled dideoxynucleotides"},{"id":"b","text":"By amplifying DNA segments with Taq polymerase"},{"id":"c","text":"By analyzing RNA transcripts"},{"id":"d","text":"By cutting DNA with restriction enzymes"}],"answerId":"a","explanation":"Sanger sequencing employs chain-terminating dideoxynucleotides to generate fragments of varying lengths for sequence determination.","kind":"mechanism","origin":"ai"},{"id":"cloning-pcr-sequencing~ai-5","moduleId":"cloning-pcr-sequencing","stem":"In the context of gene therapy, which technique is primarily used to edit genes?","options":[{"id":"a","text":"PCR"},{"id":"b","text":"Sanger sequencing"},{"id":"c","text":"CRISPR-Cas9"},{"id":"d","text":"STR analysis"}],"answerId":"c","explanation":"CRISPR-Cas9 is a revolutionary gene-editing technology used in gene therapy to modify specific DNA sequences.","kind":"integration","linkedModuleIds":["gene-therapy-crispr"],"origin":"ai"},{"id":"cloning-pcr-sequencing~ai-6","moduleId":"cloning-pcr-sequencing","stem":"Which technique would be most appropriate for quantifying viral load in a patient with COVID-19?","options":[{"id":"a","text":"Standard PCR"},{"id":"b","text":"Real-time RT-PCR"},{"id":"c","text":"Sanger sequencing"},{"id":"d","text":"STR analysis"}],"answerId":"b","explanation":"Real-time RT-PCR quantifies viral RNA by measuring the cycle threshold (Ct) during amplification.","kind":"integration","linkedModuleIds":["ecg-systematic-interpretation"],"origin":"ai"}],"epigenetics-transcriptional-control":[{"id":"epigenetics-transcriptional-control~ai-0","moduleId":"epigenetics-transcriptional-control","stem":"What is the primary function of DNA methylation at CpG islands?","options":[{"id":"a","text":"Activate transcription"},{"id":"b","text":"Silence transcription"},{"id":"c","text":"Enhance DNA replication"},{"id":"d","text":"Promote histone acetylation"}],"answerId":"b","explanation":"DNA methylation at CpG islands leads to transcriptional silencing by promoting heterochromatin formation.","kind":"recall","origin":"ai"},{"id":"epigenetics-transcriptional-control~ai-1","moduleId":"epigenetics-transcriptional-control","stem":"Which enzyme is responsible for adding methyl groups to DNA?","options":[{"id":"a","text":"Histone acetyltransferase"},{"id":"b","text":"DNA methyltransferase"},{"id":"c","text":"RNA polymerase"},{"id":"d","text":"Histone deacetylase"}],"answerId":"b","explanation":"DNA methyltransferase (DNMT) adds methyl groups to cytosine residues in DNA.","kind":"recall","origin":"ai"},{"id":"epigenetics-transcriptional-control~ai-2","moduleId":"epigenetics-transcriptional-control","stem":"A patient shows reactivation of a silenced gene after treatment with an HDAC inhibitor. What is the underlying mechanism?","options":[{"id":"a","text":"Increased DNA methylation"},{"id":"b","text":"Decreased histone acetylation"},{"id":"c","text":"Increased histone acetylation"},{"id":"d","text":"Decreased DNA replication"}],"answerId":"c","explanation":"HDAC inhibitors prevent histone deacetylation, leading to increased histone acetylation and active transcription.","kind":"mechanism","origin":"ai"},{"id":"epigenetics-transcriptional-control~ai-3","moduleId":"epigenetics-transcriptional-control","stem":"Which of the following best describes the effect of steroid hormones on gene expression?","options":[{"id":"a","text":"They bind to membrane receptors"},{"id":"b","text":"They act as transcription factors"},{"id":"c","text":"They inhibit RNA polymerase"},{"id":"d","text":"They promote DNA replication"}],"answerId":"b","explanation":"Steroid hormones cross the membrane and bind to intracellular receptors, acting directly as transcription factors.","kind":"mechanism","origin":"ai"},{"id":"epigenetics-transcriptional-control~ai-4","moduleId":"epigenetics-transcriptional-control","stem":"Which statement correctly distinguishes epigenetic changes from genetic mutations?","options":[{"id":"a","text":"Epigenetic changes are permanent and irreversible"},{"id":"b","text":"Epigenetic changes alter the DNA sequence"},{"id":"c","text":"Epigenetic changes can be influenced by environmental factors"},{"id":"d","text":"Epigenetic changes do not affect gene expression"}],"answerId":"c","explanation":"Epigenetic changes are reversible and can be influenced by environmental factors, unlike genetic mutations.","kind":"trap","origin":"ai"},{"id":"epigenetics-transcriptional-control~ai-5","moduleId":"epigenetics-transcriptional-control","stem":"How does DNA methylation contribute to colon cancer development?","options":[{"id":"a","text":"By enhancing tumor suppressor gene expression"},{"id":"b","text":"By silencing oncogenes"},{"id":"c","text":"By silencing tumor suppressor genes"},{"id":"d","text":"By promoting DNA repair mechanisms"}],"answerId":"c","explanation":"DNA methylation can silence tumor suppressor genes, contributing to the development of colon cancer.","kind":"integration","linkedModuleIds":["colon-cancer-epigenetic-silencing"],"origin":"ai"},{"id":"epigenetics-transcriptional-control~ai-6","moduleId":"epigenetics-transcriptional-control","stem":"In the context of colon cancer, how might HDAC inhibitors be therapeutically beneficial?","options":[{"id":"a","text":"They promote DNA methylation"},{"id":"b","text":"They enhance tumor suppressor gene expression"},{"id":"c","text":"They inhibit oncogene expression"},{"id":"d","text":"They prevent histone acetylation"}],"answerId":"b","explanation":"HDAC inhibitors can enhance the expression of tumor suppressor genes by promoting histone acetylation.","kind":"integration","linkedModuleIds":["colon-molecular-workup-therapy"],"origin":"ai"}],"gene-therapy-crispr":[{"id":"gene-therapy-crispr~ai-0","moduleId":"gene-therapy-crispr","stem":"Which gene therapy vector is associated with a lower risk of insertional mutagenesis?","options":[{"id":"a","text":"Adenovirus"},{"id":"b","text":"Lentivirus"},{"id":"c","text":"Adeno-associated virus"},{"id":"d","text":"Retrovirus"}],"answerId":"a","explanation":"Adenovirus is a non-integrating vector, which reduces the risk of insertional mutagenesis compared to integrating vectors like lentivirus.","kind":"recall","origin":"ai"},{"id":"gene-therapy-crispr~ai-1","moduleId":"gene-therapy-crispr","stem":"What is the primary mechanism by which CRISPR-Cas9 induces gene knock-out?","options":[{"id":"a","text":"Homology-directed repair"},{"id":"b","text":"Base editing"},{"id":"c","text":"Non-homologous end joining"},{"id":"d","text":"RNA interference"}],"answerId":"c","explanation":"CRISPR-Cas9 induces gene knock-out primarily through non-homologous end joining (NHEJ) after creating a double-strand break.","kind":"mechanism","origin":"ai"},{"id":"gene-therapy-crispr~ai-2","moduleId":"gene-therapy-crispr","stem":"Which of the following statements about somatic and germline gene therapy is correct?","options":[{"id":"a","text":"Somatic therapy alters inherited traits"},{"id":"b","text":"Germline therapy is not heritable"},{"id":"c","text":"Somatic therapy affects only the treated individual"},{"id":"d","text":"Germline therapy is safer than somatic therapy"}],"answerId":"c","explanation":"Somatic gene therapy affects only the treated individual and does not alter inherited traits, while germline therapy is heritable.","kind":"trap","origin":"ai"},{"id":"gene-therapy-crispr~ai-3","moduleId":"gene-therapy-crispr","stem":"What is the role of the PAM sequence in CRISPR-Cas9 technology?","options":[{"id":"a","text":"It enhances the binding of guide RNA"},{"id":"b","text":"It is required for Cas9 nuclease activity"},{"id":"c","text":"It facilitates DNA repair"},{"id":"d","text":"It prevents off-target effects"}],"answerId":"b","explanation":"The PAM sequence is essential for Cas9 nuclease activity, as it allows the Cas9 to recognize and bind to the target DNA.","kind":"mechanism","origin":"ai"},{"id":"gene-therapy-crispr~ai-4","moduleId":"gene-therapy-crispr","stem":"Which CRISPR-based diagnostic method utilizes collateral cleavage for detection?","options":[{"id":"a","text":"LAMP"},{"id":"b","text":"DETECTR"},{"id":"c","text":"Sanger sequencing"},{"id":"d","text":"PCR"}],"answerId":"b","explanation":"DETECTR is a CRISPR-based diagnostic method that uses collateral cleavage of a fluorescent reporter for nucleic acid detection.","kind":"recall","origin":"ai"},{"id":"gene-therapy-crispr~ai-5","moduleId":"gene-therapy-crispr","stem":"How can CRISPR technology be integrated with cloning techniques for therapeutic applications?","options":[{"id":"a","text":"By using CRISPR to enhance PCR efficiency"},{"id":"b","text":"By employing CRISPR for precise gene editing in cloned embryos"},{"id":"c","text":"By utilizing CRISPR for sequencing accuracy"},{"id":"d","text":"By applying CRISPR to improve cell culture methods"}],"answerId":"b","explanation":"CRISPR can be used for precise gene editing in cloned embryos, which enhances the therapeutic potential of cloning.","kind":"integration","linkedModuleIds":["cloning-pcr-sequencing"],"origin":"ai"},{"id":"gene-therapy-crispr~ai-6","moduleId":"gene-therapy-crispr","stem":"What potential application does CRISPR have in the context of female reproductive health?","options":[{"id":"a","text":"Gene therapy for ovarian cancer"},{"id":"b","text":"Cloning of reproductive cells"},{"id":"c","text":"PCR amplification of genetic material"},{"id":"d","text":"Sequencing of reproductive hormones"}],"answerId":"a","explanation":"CRISPR can be applied in gene therapy for conditions such as ovarian cancer, which is relevant to female reproductive health.","kind":"integration","linkedModuleIds":["hrp1-female-pelvis-neurovascular"],"origin":"ai"}],"cholesterol-steroids-lipoproteins":[{"id":"cholesterol-steroids-lipoproteins~ai-0","moduleId":"cholesterol-steroids-lipoproteins","stem":"What is the primary role of bile acids in digestion?","options":[{"id":"a","text":"Emulsification of dietary fat"},{"id":"b","text":"Cholesterol transport"},{"id":"c","text":"Triglyceride synthesis"},{"id":"d","text":"Protein digestion"}],"answerId":"a","explanation":"Bile acids act as emulsifiers, aiding in the absorption of dietary fats.","kind":"recall","origin":"ai"},{"id":"cholesterol-steroids-lipoproteins~ai-1","moduleId":"cholesterol-steroids-lipoproteins","stem":"Which lipoprotein is primarily responsible for reverse cholesterol transport?","options":[{"id":"a","text":"Chylomicrons"},{"id":"b","text":"VLDL"},{"id":"c","text":"LDL"},{"id":"d","text":"HDL"}],"answerId":"d","explanation":"HDL is known as 'good' cholesterol because it facilitates reverse cholesterol transport.","kind":"recall","origin":"ai"},{"id":"cholesterol-steroids-lipoproteins~ai-2","moduleId":"cholesterol-steroids-lipoproteins","stem":"Which of the following lipoproteins has the highest protein content?","options":[{"id":"a","text":"Chylomicrons"},{"id":"b","text":"VLDL"},{"id":"c","text":"LDL"},{"id":"d","text":"HDL"}],"answerId":"d","explanation":"HDL has the highest protein content, making it the densest lipoprotein.","kind":"recall","origin":"ai"},{"id":"cholesterol-steroids-lipoproteins~ai-3","moduleId":"cholesterol-steroids-lipoproteins","stem":"How does high LDL cholesterol contribute to atherosclerosis?","options":[{"id":"a","text":"Increases bile acid synthesis"},{"id":"b","text":"Delivers cholesterol to vessels"},{"id":"c","text":"Enhances HDL function"},{"id":"d","text":"Promotes triglyceride breakdown"}],"answerId":"b","explanation":"High LDL cholesterol delivers cholesterol to blood vessels, contributing to plaque formation.","kind":"mechanism","origin":"ai"},{"id":"cholesterol-steroids-lipoproteins~ai-4","moduleId":"cholesterol-steroids-lipoproteins","stem":"A patient presents with high levels of HDL cholesterol. What is the likely clinical significance?","options":[{"id":"a","text":"Increased risk of atherosclerosis"},{"id":"b","text":"Decreased risk of cardiovascular disease"},{"id":"c","text":"Impaired fat absorption"},{"id":"d","text":"Increased triglyceride levels"}],"answerId":"b","explanation":"High levels of HDL cholesterol are associated with a decreased risk of cardiovascular disease due to its role in reverse cholesterol transport.","kind":"clinical","origin":"ai"},{"id":"cholesterol-steroids-lipoproteins~ai-5","moduleId":"cholesterol-steroids-lipoproteins","stem":"Which hormone is derived from cholesterol and primarily involved in stress response?","options":[{"id":"a","text":"Testosterone"},{"id":"b","text":"Cortisol"},{"id":"c","text":"Aldosterone"},{"id":"d","text":"Estradiol"}],"answerId":"b","explanation":"Cortisol is a steroid hormone derived from cholesterol that plays a key role in the stress response.","kind":"recall","origin":"ai"},{"id":"cholesterol-steroids-lipoproteins~ai-6","moduleId":"cholesterol-steroids-lipoproteins","stem":"How does the mechanism of LDL differ from HDL in cholesterol transport?","options":[{"id":"a","text":"LDL transports cholesterol to tissues; HDL transports it away"},{"id":"b","text":"LDL is synthesized in the liver; HDL is not"},{"id":"c","text":"LDL is more dense than HDL"},{"id":"d","text":"LDL carries triglycerides; HDL carries phospholipids"}],"answerId":"a","explanation":"LDL delivers cholesterol to tissues, while HDL facilitates reverse transport of cholesterol back to the liver.","kind":"integration","linkedModuleIds":["hrp1-sex-steroid-synthesis-action"],"origin":"ai"},{"id":"cholesterol-steroids-lipoproteins~ai-7","moduleId":"cholesterol-steroids-lipoproteins","stem":"What is the primary source of steroid hormones in the body?","options":[{"id":"a","text":"Triglycerides"},{"id":"b","text":"Phospholipids"},{"id":"c","text":"Cholesterol"},{"id":"d","text":"Fat-soluble vitamins"}],"answerId":"c","explanation":"Steroid hormones are primarily derived from cholesterol, which serves as their precursor.","kind":"integration","linkedModuleIds":["cholesterol-bile-steroids"],"origin":"ai"}],"developmental-anatomy-periods-terms":[{"id":"developmental-anatomy-periods-terms~ai-0","moduleId":"developmental-anatomy-periods-terms","stem":"What is the primary focus of teratology in developmental anatomy?","options":[{"id":"a","text":"Study of normal development"},{"id":"b","text":"Study of abnormal development and birth defects"},{"id":"c","text":"Study of fertilization processes"},{"id":"d","text":"Study of organ maturation"}],"answerId":"b","explanation":"Teratology specifically investigates abnormal development and the resulting birth defects.","kind":"recall","origin":"ai"},{"id":"developmental-anatomy-periods-terms~ai-1","moduleId":"developmental-anatomy-periods-terms","stem":"Which period of prenatal development is characterized by organogenesis?","options":[{"id":"a","text":"Pre-embryonic period"},{"id":"b","text":"Embryonic period"},{"id":"c","text":"Fetal period"},{"id":"d","text":"Postnatal period"}],"answerId":"b","explanation":"The embryonic period (weeks 3-8) is when the organ plan is established.","kind":"recall","origin":"ai"},{"id":"developmental-anatomy-periods-terms~ai-2","moduleId":"developmental-anatomy-periods-terms","stem":"During which weeks of gestation is the risk of major structural defects highest?","options":[{"id":"a","text":"Weeks 1-2"},{"id":"b","text":"Weeks 3-8"},{"id":"c","text":"Weeks 9-12"},{"id":"d","text":"Weeks 13-16"}],"answerId":"b","explanation":"Weeks 3-8 are critical for organ development, making them the most susceptible to structural defects.","kind":"recall","origin":"ai"},{"id":"developmental-anatomy-periods-terms~ai-3","moduleId":"developmental-anatomy-periods-terms","stem":"A patient presents with a pregnancy dated at 10 weeks gestational age. What is the approximate fertilization age of the embryo?","options":[{"id":"a","text":"10 weeks"},{"id":"b","text":"8 weeks"},{"id":"c","text":"6 weeks"},{"id":"d","text":"4 weeks"}],"answerId":"b","explanation":"Fertilization age is typically about 2 weeks less than gestational age, making it approximately 8 weeks.","kind":"trap","origin":"ai"},{"id":"developmental-anatomy-periods-terms~ai-4","moduleId":"developmental-anatomy-periods-terms","stem":"Which directional terminology is preferred in embryology to describe the position of structures?","options":[{"id":"a","text":"Superior/inferior"},{"id":"b","text":"Anterior/posterior"},{"id":"c","text":"Cranial/caudal"},{"id":"d","text":"Medial/lateral"}],"answerId":"c","explanation":"Cranial/caudal terminology is used in embryology to describe the orientation of structures.","kind":"recall","origin":"ai"},{"id":"developmental-anatomy-periods-terms~ai-5","moduleId":"developmental-anatomy-periods-terms","stem":"How does the embryonic period differ from the fetal period in terms of development?","options":[{"id":"a","text":"Organogenesis vs. growth and maturation"},{"id":"b","text":"Fertilization vs. implantation"},{"id":"c","text":"Cell division vs. differentiation"},{"id":"d","text":"Neural development vs. muscular development"}],"answerId":"a","explanation":"The embryonic period focuses on organogenesis, while the fetal period is primarily about growth and maturation.","kind":"mechanism","origin":"ai"},{"id":"developmental-anatomy-periods-terms~ai-6","moduleId":"developmental-anatomy-periods-terms","stem":"How is the embryonic development timeline related to complications of myocardial infarction?","options":[{"id":"a","text":"Both involve organogenesis"},{"id":"b","text":"Both require gestational age assessment"},{"id":"c","text":"Both are influenced by maternal health"},{"id":"d","text":"Both are affected by genetic regulation"}],"answerId":"c","explanation":"Maternal health during pregnancy can impact both embryonic development and the risk of complications in myocardial infarction.","kind":"integration","linkedModuleIds":["mi-complications"],"origin":"ai"},{"id":"developmental-anatomy-periods-terms~ai-7","moduleId":"developmental-anatomy-periods-terms","stem":"Which concept connects embryonic development and genetic regulation?","options":[{"id":"a","text":"Fertilization age"},{"id":"b","text":"Organ maturation"},{"id":"c","text":"Developmental signaling pathways"},{"id":"d","text":"Gestational age assessment"}],"answerId":"c","explanation":"Developmental signaling pathways are crucial for regulating embryonic development and are influenced by genetic factors.","kind":"integration","linkedModuleIds":["developmental-genetic-regulation"],"origin":"ai"}],"post-transcriptional-translational-control":[{"id":"post-transcriptional-translational-control~ai-0","moduleId":"post-transcriptional-translational-control","stem":"What is the primary mechanism by which alternative splicing generates multiple protein isoforms from a single gene?","options":[{"id":"a","text":"Differential promoter usage"},{"id":"b","text":"Exon skipping"},{"id":"c","text":"RNA editing"},{"id":"d","text":"Polyadenylation"}],"answerId":"b","explanation":"Alternative splicing allows different combinations of exons to be included or excluded, leading to multiple protein isoforms.","kind":"recall","origin":"ai"},{"id":"post-transcriptional-translational-control~ai-1","moduleId":"post-transcriptional-translational-control","stem":"Which process involves the conversion of cytidine to uridine in mRNA, resulting in a truncated protein?","options":[{"id":"a","text":"RNA splicing"},{"id":"b","text":"RNA editing"},{"id":"c","text":"RNA interference"},{"id":"d","text":"Translational control"}],"answerId":"b","explanation":"RNA editing, specifically by cytidine deaminase, converts cytidine to uridine, creating a stop codon in apoB mRNA.","kind":"recall","origin":"ai"},{"id":"post-transcriptional-translational-control~ai-2","moduleId":"post-transcriptional-translational-control","stem":"How does low iron concentration affect ferritin and transferrin receptor mRNA translation?","options":[{"id":"a","text":"Increases ferritin, decreases transferrin receptor"},{"id":"b","text":"Decreases both ferritin and transferrin receptor"},{"id":"c","text":"Decreases ferritin, increases transferrin receptor"},{"id":"d","text":"No effect on either"}],"answerId":"a","explanation":"Low iron causes aconitase to bind to IREs on ferritin mRNA, blocking translation, while stabilizing transferrin receptor mRNA to increase uptake.","kind":"mechanism","origin":"ai"},{"id":"post-transcriptional-translational-control~ai-3","moduleId":"post-transcriptional-translational-control","stem":"Which statement correctly distinguishes between siRNA and miRNA?","options":[{"id":"a","text":"Both bind with partial complementarity and only repress translation"},{"id":"b","text":"siRNA cleaves its target mRNA, miRNA represses multiple targets"},{"id":"c","text":"siRNA and miRNA both cleave mRNA"},{"id":"d","text":"miRNA has 100% complementarity and cleaves its target"}],"answerId":"b","explanation":"siRNA has perfect complementarity and cleaves its target mRNA, while miRNA binds partially and can regulate multiple mRNAs.","kind":"trap","origin":"ai"},{"id":"post-transcriptional-translational-control~ai-4","moduleId":"post-transcriptional-translational-control","stem":"In response to stress, how does phosphorylation of eIF-2 affect protein synthesis?","options":[{"id":"a","text":"Increases initiation of translation"},{"id":"b","text":"Decreases initiation of translation"},{"id":"c","text":"Increases elongation of translation"},{"id":"d","text":"Decreases elongation of translation"}],"answerId":"b","explanation":"Phosphorylation of eIF-2 inhibits the initiation of translation, which is a cellular response to stress conditions.","kind":"mechanism","origin":"ai"},{"id":"post-transcriptional-translational-control~ai-5","moduleId":"post-transcriptional-translational-control","stem":"How does the regulation of gene expression through post-transcriptional control relate to epigenetic modifications?","options":[{"id":"a","text":"Both involve changes in DNA sequence"},{"id":"b","text":"Both can affect mRNA stability and translation"},{"id":"c","text":"Only epigenetics involves histone modification"},{"id":"d","text":"Only post-transcriptional control affects protein synthesis"}],"answerId":"b","explanation":"Both post-transcriptional control and epigenetic modifications can influence gene expression outcomes, including mRNA stability and translation efficiency.","kind":"integration","linkedModuleIds":["epigenetics-transcriptional-control"],"origin":"ai"},{"id":"post-transcriptional-translational-control~ai-6","moduleId":"post-transcriptional-translational-control","stem":"Which mechanism of gene regulation would most directly impact the production of tissue-specific protein isoforms during development?","options":[{"id":"a","text":"RNA interference"},{"id":"b","text":"Translational control"},{"id":"c","text":"Alternative splicing"},{"id":"d","text":"DNA methylation"}],"answerId":"c","explanation":"Alternative splicing allows for the generation of different protein isoforms from the same gene, which is crucial for tissue specificity during development.","kind":"integration","linkedModuleIds":["developmental-genetic-regulation"],"origin":"ai"}],"carbohydrate-structure-isomerism":[{"id":"carbohydrate-structure-isomerism~ai-0","moduleId":"carbohydrate-structure-isomerism","stem":"Which of the following carbohydrates is a ketose?","options":[{"id":"a","text":"Glucose"},{"id":"b","text":"Galactose"},{"id":"c","text":"Fructose"},{"id":"d","text":"Mannose"}],"answerId":"c","explanation":"Fructose is a ketose, while glucose, galactose, and mannose are aldoses.","kind":"recall","origin":"ai"},{"id":"carbohydrate-structure-isomerism~ai-1","moduleId":"carbohydrate-structure-isomerism","stem":"What type of isomerism do glucose and galactose exhibit?","options":[{"id":"a","text":"Enantiomerism"},{"id":"b","text":"Epimerism"},{"id":"c","text":"Anomerism"},{"id":"d","text":"Stereoisomerism"}],"answerId":"b","explanation":"Glucose and galactose are epimers because they differ at one carbon (C4).","kind":"recall","origin":"ai"},{"id":"carbohydrate-structure-isomerism~ai-2","moduleId":"carbohydrate-structure-isomerism","stem":"What is the mechanism of mutarotation in sugars?","options":[{"id":"a","text":"Formation of glycosidic bonds"},{"id":"b","text":"Interconversion of α and β anomers"},{"id":"c","text":"Conversion of ketoses to aldoses"},{"id":"d","text":"Cyclization of sugars to form furanoses"}],"answerId":"b","explanation":"Mutarotation refers to the interconversion of α and β anomers through the open-chain form.","kind":"mechanism","origin":"ai"},{"id":"carbohydrate-structure-isomerism~ai-3","moduleId":"carbohydrate-structure-isomerism","stem":"Which of the following statements is true regarding sucrose?","options":[{"id":"a","text":"It is a reducing sugar"},{"id":"b","text":"It has a free anomeric carbon"},{"id":"c","text":"It does not reduce Benedict's reagent"},{"id":"d","text":"It is an aldose"}],"answerId":"c","explanation":"Sucrose does not reduce Benedict's reagent because it has no free anomeric carbon and is thus a non-reducing sugar.","kind":"recall","origin":"ai"},{"id":"carbohydrate-structure-isomerism~ai-4","moduleId":"carbohydrate-structure-isomerism","stem":"Glucose and mannose differ at which carbon position?","options":[{"id":"a","text":"C1"},{"id":"b","text":"C2"},{"id":"c","text":"C3"},{"id":"d","text":"C4"}],"answerId":"b","explanation":"Glucose and mannose are C2 epimers, differing at the second carbon.","kind":"recall","origin":"ai"},{"id":"carbohydrate-structure-isomerism~ai-5","moduleId":"carbohydrate-structure-isomerism","stem":"Which of the following is a common trap in carbohydrate chemistry?","options":[{"id":"a","text":"Glucose and galactose are enantiomers"},{"id":"b","text":"Fructose is an aldose"},{"id":"c","text":"Mannose is a ketose"},{"id":"d","text":"Sucrose is a reducing sugar"}],"answerId":"a","explanation":"Glucose and galactose are epimers, not enantiomers; this is a common misconception.","kind":"trap","origin":"ai"},{"id":"carbohydrate-structure-isomerism~ai-6","moduleId":"carbohydrate-structure-isomerism","stem":"How do glycosidic bonds relate to carbohydrate structure?","options":[{"id":"a","text":"They form between amino acids"},{"id":"b","text":"They link monosaccharides to form polysaccharides"},{"id":"c","text":"They are involved in lipid metabolism"},{"id":"d","text":"They are only found in nucleic acids"}],"answerId":"b","explanation":"Glycosidic bonds link monosaccharides together to form polysaccharides.","kind":"integration","linkedModuleIds":["glycosidic-bonds-polysaccharides"],"origin":"ai"},{"id":"carbohydrate-structure-isomerism~ai-7","moduleId":"carbohydrate-structure-isomerism","stem":"Which type of carbohydrate is most likely to undergo mutarotation?","options":[{"id":"a","text":"Non-reducing sugars"},{"id":"b","text":"Aldoses"},{"id":"c","text":"Ketones"},{"id":"d","text":"Disaccharides"}],"answerId":"b","explanation":"Aldoses can undergo mutarotation due to their free anomeric carbon, allowing interconversion between anomers.","kind":"integration","linkedModuleIds":["glycosidic-bonds-polysaccharides"],"origin":"ai"}],"developmental-genetic-regulation":[{"id":"developmental-genetic-regulation~ai-0","moduleId":"developmental-genetic-regulation","stem":"What is the primary role of HOX genes in development?","options":[{"id":"a","text":"Regulating cell cycle progression"},{"id":"b","text":"Establishing regional body patterns"},{"id":"c","text":"Controlling apoptosis"},{"id":"d","text":"Facilitating nutrient absorption"}],"answerId":"b","explanation":"HOX genes are crucial for establishing the anterior-posterior body axis and regional identity during embryonic development.","kind":"recall","origin":"ai"},{"id":"developmental-genetic-regulation~ai-1","moduleId":"developmental-genetic-regulation","stem":"Which mechanism primarily mediates the effect of SHH signaling during embryonic development?","options":[{"id":"a","text":"Histone acetylation"},{"id":"b","text":"Transcription factor activation"},{"id":"c","text":"DNA replication"},{"id":"d","text":"Protein degradation"}],"answerId":"b","explanation":"SHH signaling activates specific transcription factors that regulate gene expression necessary for patterning and midline development.","kind":"mechanism","origin":"ai"},{"id":"developmental-genetic-regulation~ai-2","moduleId":"developmental-genetic-regulation","stem":"A patient presents with a regional body-pattern abnormality. Which genetic mechanism is most likely disrupted?","options":[{"id":"a","text":"SRY gene function"},{"id":"b","text":"HOX gene expression"},{"id":"c","text":"Notch signaling pathway"},{"id":"d","text":"FGF receptor activation"}],"answerId":"b","explanation":"HOX genes are essential for proper regional body patterning; disruption leads to abnormalities in body structure.","kind":"clinical","origin":"ai"},{"id":"developmental-genetic-regulation~ai-3","moduleId":"developmental-genetic-regulation","stem":"Which of the following statements about epigenetic regulation is true?","options":[{"id":"a","text":"It always involves changes to the DNA sequence."},{"id":"b","text":"It can lead to heritable changes in gene expression."},{"id":"c","text":"It only occurs during embryonic development."},{"id":"d","text":"It is irreversible once established."}],"answerId":"b","explanation":"Epigenetic regulation can lead to heritable changes in gene expression without altering the underlying DNA sequence.","kind":"trap","origin":"ai"},{"id":"developmental-genetic-regulation~ai-4","moduleId":"developmental-genetic-regulation","stem":"A child with 46,XX karyotype presents with testicular development. Which gene is likely responsible for this phenotype?","options":[{"id":"a","text":"HOX"},{"id":"b","text":"SRY"},{"id":"c","text":"PAX"},{"id":"d","text":"FGF"}],"answerId":"b","explanation":"The SRY gene initiates the testis-determining pathway, leading to male development despite the XX karyotype.","kind":"clinical","origin":"ai"},{"id":"developmental-genetic-regulation~ai-5","moduleId":"developmental-genetic-regulation","stem":"How does epigenetic regulation differ from genetic mutations in terms of inheritance?","options":[{"id":"a","text":"Epigenetic changes cannot be inherited."},{"id":"b","text":"Genetic mutations are always expressed."},{"id":"c","text":"Epigenetic marks can be inherited without altering DNA sequence."},{"id":"d","text":"Genetic mutations affect only somatic cells."}],"answerId":"c","explanation":"Epigenetic marks can be passed to the next generation while maintaining the original DNA sequence.","kind":"trap","origin":"ai"},{"id":"developmental-genetic-regulation~ai-6","moduleId":"developmental-genetic-regulation","stem":"In the context of developmental bone disorders, which signaling pathway is crucial for bone growth and differentiation?","options":[{"id":"a","text":"WNT signaling"},{"id":"b","text":"Notch signaling"},{"id":"c","text":"SHH signaling"},{"id":"d","text":"FGF signaling"}],"answerId":"a","explanation":"WNT signaling plays a significant role in bone development and homeostasis, influencing osteoblast differentiation.","kind":"integration","linkedModuleIds":["developmental-bone-disorders"],"origin":"ai"},{"id":"developmental-genetic-regulation~ai-7","moduleId":"developmental-genetic-regulation","stem":"Which developmental signal is most relevant in the context of differences in sex development (DSD)?","options":[{"id":"a","text":"FGF"},{"id":"b","text":"SHH"},{"id":"c","text":"Notch"},{"id":"d","text":"SRY"}],"answerId":"d","explanation":"The SRY gene is critical for initiating male sex determination and is directly linked to DSD.","kind":"integration","linkedModuleIds":["hrp1-dsd-reproductive-anomalies"],"origin":"ai"}],"genetic-code-translation":[{"id":"genetic-code-translation~ai-0","moduleId":"genetic-code-translation","stem":"What is the primary function of tRNA in protein synthesis?","options":[{"id":"a","text":"To catalyze peptide bond formation"},{"id":"b","text":"To carry amino acids to the ribosome"},{"id":"c","text":"To decode mRNA into amino acids"},{"id":"d","text":"To provide energy for translation"}],"answerId":"b","explanation":"tRNA's main role is to transport specific amino acids to the ribosome during translation.","kind":"recall","origin":"ai"},{"id":"genetic-code-translation~ai-1","moduleId":"genetic-code-translation","stem":"Which of the following antibiotics targets the 50S subunit of the bacterial ribosome?","options":[{"id":"a","text":"Tetracycline"},{"id":"b","text":"Chloramphenicol"},{"id":"c","text":"Streptomycin"},{"id":"d","text":"Erythromycin"}],"answerId":"b","explanation":"Chloramphenicol inhibits protein synthesis by binding to the 50S subunit of the bacterial ribosome.","kind":"recall","origin":"ai"},{"id":"genetic-code-translation~ai-2","moduleId":"genetic-code-translation","stem":"What type of mutation results in a premature stop codon?","options":[{"id":"a","text":"Missense mutation"},{"id":"b","text":"Nonsense mutation"},{"id":"c","text":"Silent mutation"},{"id":"d","text":"Frameshift mutation"}],"answerId":"b","explanation":"A nonsense mutation introduces a stop codon, leading to truncated proteins.","kind":"mechanism","origin":"ai"},{"id":"genetic-code-translation~ai-3","moduleId":"genetic-code-translation","stem":"Which process is directly affected by the wobble hypothesis in tRNA?","options":[{"id":"a","text":"Amino acid activation"},{"id":"b","text":"Peptide bond formation"},{"id":"c","text":"Codon-anticodon pairing"},{"id":"d","text":"Ribosome assembly"}],"answerId":"c","explanation":"The wobble hypothesis explains how the third base of a codon can pair loosely with the corresponding base in the tRNA anticodon.","kind":"mechanism","origin":"ai"},{"id":"genetic-code-translation~ai-4","moduleId":"genetic-code-translation","stem":"Which statement accurately describes the role of rRNA in the ribosome?","options":[{"id":"a","text":"rRNA serves only as a structural component"},{"id":"b","text":"rRNA catalyzes peptide bond formation"},{"id":"c","text":"rRNA carries amino acids"},{"id":"d","text":"rRNA decodes mRNA"}],"answerId":"b","explanation":"rRNA has catalytic activity, specifically peptidyltransferase, which forms peptide bonds during protein synthesis.","kind":"trap","origin":"ai"},{"id":"genetic-code-translation~ai-5","moduleId":"genetic-code-translation","stem":"How does a frameshift mutation affect protein synthesis?","options":[{"id":"a","text":"It alters the amino acid sequence from the mutation point onward"},{"id":"b","text":"It introduces a stop codon prematurely"},{"id":"c","text":"It has no effect on the protein produced"},{"id":"d","text":"It only affects the first amino acid"}],"answerId":"a","explanation":"Frameshift mutations change the reading frame, altering all subsequent amino acids in the protein sequence.","kind":"mechanism","origin":"ai"},{"id":"genetic-code-translation~ai-6","moduleId":"genetic-code-translation","stem":"Which mechanism of antibiotic resistance is most likely to affect the action of aminoglycosides?","options":[{"id":"a","text":"Modification of the ribosomal RNA"},{"id":"b","text":"Efflux pumps"},{"id":"c","text":"Enzymatic degradation of the antibiotic"},{"id":"d","text":"Alteration of the target site"}],"answerId":"c","explanation":"Aminoglycosides can be inactivated by specific enzymes, leading to resistance.","kind":"integration","linkedModuleIds":["antibiotic-resistance-mechanisms"],"origin":"ai"},{"id":"genetic-code-translation~ai-7","moduleId":"genetic-code-translation","stem":"What is the role of eIF-4E in eukaryotic translation initiation?","options":[{"id":"a","text":"It binds to the ribosome"},{"id":"b","text":"It recognizes the start codon"},{"id":"c","text":"It facilitates mRNA cap recognition"},{"id":"d","text":"It delivers aminoacyl-tRNA"}],"answerId":"c","explanation":"eIF-4E is essential for recognizing the 5' cap of mRNA, initiating translation.","kind":"integration","linkedModuleIds":["protein-targeting-ptm"],"origin":"ai"}],"glycosidic-bonds-polysaccharides":[{"id":"glycosidic-bonds-polysaccharides~ai-0","moduleId":"glycosidic-bonds-polysaccharides","stem":"What type of glycosidic bond is found in cellulose?","options":[{"id":"a","text":"α-1,4"},{"id":"b","text":"α-1,6"},{"id":"c","text":"β-1,4"},{"id":"d","text":"β-1,6"}],"answerId":"c","explanation":"Cellulose consists of β-1,4 glycosidic bonds between glucose units, making it indigestible for humans.","kind":"recall","origin":"ai"},{"id":"glycosidic-bonds-polysaccharides~ai-1","moduleId":"glycosidic-bonds-polysaccharides","stem":"Which disaccharide is formed from glucose and galactose?","options":[{"id":"a","text":"Maltose"},{"id":"b","text":"Lactose"},{"id":"c","text":"Sucrose"},{"id":"d","text":"Trehalose"}],"answerId":"b","explanation":"Lactose is composed of glucose and galactose linked by a β-1,4 glycosidic bond.","kind":"recall","origin":"ai"},{"id":"glycosidic-bonds-polysaccharides~ai-2","moduleId":"glycosidic-bonds-polysaccharides","stem":"What is the primary structural difference between starch and glycogen?","options":[{"id":"a","text":"Starch is more branched than glycogen"},{"id":"b","text":"Glycogen has more α-1,6 branches than starch"},{"id":"c","text":"Starch contains β-1,4 bonds"},{"id":"d","text":"Glycogen is a disaccharide"}],"answerId":"b","explanation":"Glycogen is more highly branched than starch, allowing for quicker mobilization of glucose.","kind":"mechanism","origin":"ai"},{"id":"glycosidic-bonds-polysaccharides~ai-3","moduleId":"glycosidic-bonds-polysaccharides","stem":"Why can humans not digest cellulose?","options":[{"id":"a","text":"It is a different sugar than starch"},{"id":"b","text":"It contains α-1,4 bonds"},{"id":"c","text":"It contains β-1,4 bonds"},{"id":"d","text":"It is a disaccharide"}],"answerId":"c","explanation":"Humans lack the enzyme to hydrolyze the β-1,4 glycosidic bonds found in cellulose.","kind":"trap","origin":"ai"},{"id":"glycosidic-bonds-polysaccharides~ai-4","moduleId":"glycosidic-bonds-polysaccharides","stem":"Which of the following statements about heparin is true?","options":[{"id":"a","text":"It is a type of starch"},{"id":"b","text":"It is a glycoprotein"},{"id":"c","text":"It is a sulfated glycosaminoglycan"},{"id":"d","text":"It is a reducing sugar"}],"answerId":"c","explanation":"Heparin is a sulfated glycosaminoglycan that acts as an anticoagulant in clinical settings.","kind":"recall","origin":"ai"},{"id":"glycosidic-bonds-polysaccharides~ai-5","moduleId":"glycosidic-bonds-polysaccharides","stem":"How does the structure of amylose allow it to be detected by iodine?","options":[{"id":"a","text":"Iodine binds to α-1,6 bonds"},{"id":"b","text":"Iodine binds to the helical structure"},{"id":"c","text":"Iodine reacts with glucose"},{"id":"d","text":"Iodine forms a covalent bond with amylose"}],"answerId":"b","explanation":"Iodine forms a complex with the helical structure of amylose, resulting in a blue color.","kind":"mechanism","origin":"ai"},{"id":"glycosidic-bonds-polysaccharides~ai-6","moduleId":"glycosidic-bonds-polysaccharides","stem":"How does the structure of glucose affect its isomerism and polysaccharide formation?","options":[{"id":"a","text":"Only linear forms can form glycosidic bonds"},{"id":"b","text":"Cyclic forms are more stable and form polysaccharides"},{"id":"c","text":"Isomerism does not affect polysaccharide formation"},{"id":"d","text":"All isomers can form polysaccharides equally"}],"answerId":"b","explanation":"Cyclic forms of glucose are more stable and are the predominant forms that participate in polysaccharide formation.","kind":"integration","linkedModuleIds":["carbohydrate-structure-isomerism"],"origin":"ai"},{"id":"glycosidic-bonds-polysaccharides~ai-7","moduleId":"glycosidic-bonds-polysaccharides","stem":"Which type of glycosidic bond is primarily responsible for the structural integrity of chitin?","options":[{"id":"a","text":"α-1,4"},{"id":"b","text":"α-1,6"},{"id":"c","text":"β-1,4"},{"id":"d","text":"β-1,6"}],"answerId":"c","explanation":"Chitin consists of β-1,4 glycosidic bonds between N-acetylglucosamine units, providing structural integrity.","kind":"recall","origin":"ai"}],"fatty-acids-membranes":[{"id":"fatty-acids-membranes~ai-0","moduleId":"fatty-acids-membranes","stem":"Which of the following fatty acids is essential and must be obtained from the diet?","options":[{"id":"a","text":"Palmitic acid"},{"id":"b","text":"Stearic acid"},{"id":"c","text":"Linoleic acid"},{"id":"d","text":"Arachidonic acid"}],"answerId":"c","explanation":"Linoleic acid is an essential fatty acid that cannot be synthesized by the body and must be ingested.","kind":"recall","origin":"ai"},{"id":"fatty-acids-membranes~ai-1","moduleId":"fatty-acids-membranes","stem":"What is the primary structural difference between saturated and unsaturated fatty acids?","options":[{"id":"a","text":"Presence of hydroxyl groups"},{"id":"b","text":"Number of carbon atoms"},{"id":"c","text":"Presence of double bonds"},{"id":"d","text":"Length of the hydrocarbon chain"}],"answerId":"c","explanation":"The primary structural difference is the presence of double bonds in unsaturated fatty acids, which affects their physical properties.","kind":"mechanism","origin":"ai"},{"id":"fatty-acids-membranes~ai-2","moduleId":"fatty-acids-membranes","stem":"What effect do cis double bonds have on the melting point of fatty acids?","options":[{"id":"a","text":"Increase melting point"},{"id":"b","text":"Decrease melting point"},{"id":"c","text":"No effect on melting point"},{"id":"d","text":"Only affect saturated fats"}],"answerId":"b","explanation":"Cis double bonds introduce kinks in the fatty acid chain, preventing tight packing and lowering the melting point.","kind":"mechanism","origin":"ai"},{"id":"fatty-acids-membranes~ai-3","moduleId":"fatty-acids-membranes","stem":"Which of the following statements about trans fatty acids is correct?","options":[{"id":"a","text":"They are naturally occurring in high amounts in fish."},{"id":"b","text":"They have a lower melting point than unsaturated fats."},{"id":"c","text":"They are straight-chain and can raise cardiovascular risk."},{"id":"d","text":"They are essential fatty acids."}],"answerId":"c","explanation":"Trans fatty acids are artificially created, straight-chain fats that can increase cardiovascular risk.","kind":"trap","origin":"ai"},{"id":"fatty-acids-membranes~ai-4","moduleId":"fatty-acids-membranes","stem":"In a clinical setting, which finding would suggest a diet high in unsaturated fats?","options":[{"id":"a","text":"Increased blood viscosity"},{"id":"b","text":"Lower serum cholesterol levels"},{"id":"c","text":"Solid fats at room temperature"},{"id":"d","text":"Increased triglyceride levels"}],"answerId":"b","explanation":"A diet high in unsaturated fats is associated with lower serum cholesterol levels due to their beneficial effects on lipid profiles.","kind":"clinical","origin":"ai"},{"id":"fatty-acids-membranes~ai-5","moduleId":"fatty-acids-membranes","stem":"How does the structure of phospholipids contribute to their function in cell membranes?","options":[{"id":"a","text":"They are hydrophobic and repel water."},{"id":"b","text":"They form a bilayer due to their amphipathic nature."},{"id":"c","text":"They contain only saturated fatty acids."},{"id":"d","text":"They are rigid and prevent fluidity."}],"answerId":"b","explanation":"Phospholipids are amphipathic, allowing them to form a bilayer that is essential for cell membrane structure and function.","kind":"mechanism","origin":"ai"},{"id":"fatty-acids-membranes~ai-6","moduleId":"fatty-acids-membranes","stem":"How does the metabolism of fatty acids relate to the synthesis of eicosanoids?","options":[{"id":"a","text":"Fatty acids are converted to glucose for energy."},{"id":"b","text":"Eicosanoids are derived from essential fatty acids."},{"id":"c","text":"Fatty acids inhibit eicosanoid synthesis."},{"id":"d","text":"Eicosanoids are synthesized from carbohydrates."}],"answerId":"b","explanation":"Eicosanoids are signaling molecules derived from essential fatty acids, linking fatty acid metabolism to inflammatory and immune responses.","kind":"integration","linkedModuleIds":["fatty-acid-synthesis-eicosanoids"],"origin":"ai"},{"id":"fatty-acids-membranes~ai-7","moduleId":"fatty-acids-membranes","stem":"What role do fatty acids play in the structure of cell membranes, particularly in relation to the epidermis?","options":[{"id":"a","text":"They provide rigidity to the membrane."},{"id":"b","text":"They are precursors for steroid hormones."},{"id":"c","text":"They contribute to membrane fluidity and barrier function."},{"id":"d","text":"They are only found in the cytoplasm."}],"answerId":"c","explanation":"Fatty acids contribute to the fluidity and barrier function of cell membranes, including those in the epidermis.","kind":"integration","linkedModuleIds":["membranes-and-epidermis"],"origin":"ai"}],"protein-targeting-ptm":[{"id":"protein-targeting-ptm~ai-0","moduleId":"protein-targeting-ptm","stem":"What is the primary role of the signal recognition particle (SRP) in protein targeting?","options":[{"id":"a","text":"To modify proteins post-translationally"},{"id":"b","text":"To transport proteins to the mitochondria"},{"id":"c","text":"To bind to the ribosome and direct it to the ER"},{"id":"d","text":"To degrade misfolded proteins"}],"answerId":"c","explanation":"The SRP binds to the ribosome and directs it to the ER translocon for co-translational import of proteins with an N-terminal signal sequence.","kind":"recall","origin":"ai"},{"id":"protein-targeting-ptm~ai-1","moduleId":"protein-targeting-ptm","stem":"Which post-translational modification involves the addition of an oligosaccharide to asparagine residues?","options":[{"id":"a","text":"Phosphorylation"},{"id":"b","text":"Glycosylation"},{"id":"c","text":"Hydroxylation"},{"id":"d","text":"Proteolytic trimming"}],"answerId":"b","explanation":"N-linked glycosylation adds an oligosaccharide to asparagine residues in the endoplasmic reticulum.","kind":"recall","origin":"ai"},{"id":"protein-targeting-ptm~ai-2","moduleId":"protein-targeting-ptm","stem":"A patient presents with lysosomal enzymes found in their blood instead of lysosomes. What is the underlying mechanism?","options":[{"id":"a","text":"Deficiency of a single lysosomal enzyme"},{"id":"b","text":"Phosphotransferase defect leading to M6P tagging failure"},{"id":"c","text":"Excessive proteasomal degradation"},{"id":"d","text":"Increased protein aggregation in the cytosol"}],"answerId":"b","explanation":"The defect in phosphotransferase prevents the addition of mannose-6-phosphate, leading to mis-sorting of all lysosomal enzymes.","kind":"mechanism","origin":"ai"},{"id":"protein-targeting-ptm~ai-3","moduleId":"protein-targeting-ptm","stem":"In Huntington disease, what is the primary pathological mechanism?","options":[{"id":"a","text":"Increased proteasomal degradation of HTT"},{"id":"b","text":"Toxic aggregation of polyglutamine-expanded HTT"},{"id":"c","text":"Defective lysosomal enzyme activity"},{"id":"d","text":"Impaired glycosylation of proteins"}],"answerId":"b","explanation":"Huntington disease is characterized by toxic aggregation of the HTT protein due to CAG repeat expansion.","kind":"mechanism","origin":"ai"},{"id":"protein-targeting-ptm~ai-4","moduleId":"protein-targeting-ptm","stem":"What is a common clinical finding in cystic fibrosis related to the CFTR mutation?","options":[{"id":"a","text":"Lysosomal enzyme deficiency"},{"id":"b","text":"Thick secretions due to defective chloride transport"},{"id":"c","text":"Progressive chorea"},{"id":"d","text":"Increased serum mannose-6-phosphate"}],"answerId":"b","explanation":"The ΔF508 CFTR mutation leads to misprocessing of the chloride channel, resulting in thick secretions.","kind":"recall","origin":"ai"},{"id":"protein-targeting-ptm~ai-5","moduleId":"protein-targeting-ptm","stem":"How does I-cell disease differ from a single lysosomal enzyme deficiency?","options":[{"id":"a","text":"It affects only one enzyme"},{"id":"b","text":"It results from a phosphotransferase defect affecting all enzymes"},{"id":"c","text":"It is caused by a genetic mutation in a single lysosomal enzyme"},{"id":"d","text":"It does not involve lysosomal enzymes"}],"answerId":"b","explanation":"I-cell disease is due to a phosphotransferase defect that prevents the tagging of all lysosomal enzymes, leading to their secretion.","kind":"trap","origin":"ai"},{"id":"protein-targeting-ptm~ai-6","moduleId":"protein-targeting-ptm","stem":"Which post-translational modification is essential for the proper targeting of proteins to lysosomes?","options":[{"id":"a","text":"Glycosylation"},{"id":"b","text":"Ubiquitination"},{"id":"c","text":"Phosphorylation"},{"id":"d","text":"Mannose-6-phosphate tagging"}],"answerId":"d","explanation":"Mannose-6-phosphate tagging is crucial for directing lysosomal enzymes to their correct cellular location.","kind":"recall","origin":"ai"},{"id":"protein-targeting-ptm~ai-7","moduleId":"protein-targeting-ptm","stem":"How is the process of protein targeting related to antigen presentation pathways?","options":[{"id":"a","text":"Both involve the degradation of misfolded proteins"},{"id":"b","text":"Both require co-translational modifications"},{"id":"c","text":"Both are dependent on the endoplasmic reticulum for processing"},{"id":"d","text":"Both utilize ubiquitin for tagging proteins"}],"answerId":"c","explanation":"Protein targeting and antigen presentation both involve processing in the endoplasmic reticulum before being presented on cell surfaces.","kind":"integration","linkedModuleIds":["antigen-processing-presentation"],"origin":"ai"},{"id":"protein-targeting-ptm~ai-8","moduleId":"protein-targeting-ptm","stem":"What common mechanism links protein targeting and the translation of genetic code?","options":[{"id":"a","text":"Both processes involve the ribosome"},{"id":"b","text":"Both require post-translational modifications"},{"id":"c","text":"Both utilize chaperones for protein folding"},{"id":"d","text":"Both are influenced by lysosomal enzyme activity"}],"answerId":"a","explanation":"Both protein targeting and translation occur at the ribosome, where proteins are synthesized and directed to their final destinations.","kind":"integration","linkedModuleIds":["genetic-code-translation"],"origin":"ai"}],"germ-layer-derivatives-folding":[{"id":"germ-layer-derivatives-folding~ai-0","moduleId":"germ-layer-derivatives-folding","stem":"Which structure is derived from the paraxial mesoderm?","options":[{"id":"a","text":"Epidermis"},{"id":"b","text":"Skeletal muscle"},{"id":"c","text":"Liver"},{"id":"d","text":"Lungs"}],"answerId":"b","explanation":"Skeletal muscle is derived from the myotome of the paraxial mesoderm.","kind":"recall","origin":"ai"},{"id":"germ-layer-derivatives-folding~ai-1","moduleId":"germ-layer-derivatives-folding","stem":"What is the primary role of lateral plate mesoderm during embryonic development?","options":[{"id":"a","text":"Forms the CNS"},{"id":"b","text":"Contributes to body wall connective tissues"},{"id":"c","text":"Creates the epidermis"},{"id":"d","text":"Develops the urogenital system"}],"answerId":"b","explanation":"The lateral plate mesoderm contributes to body wall and limb connective tissues.","kind":"recall","origin":"ai"},{"id":"germ-layer-derivatives-folding~ai-2","moduleId":"germ-layer-derivatives-folding","stem":"Which embryonic structure gives rise to the respiratory epithelium?","options":[{"id":"a","text":"Ectoderm"},{"id":"b","text":"Endoderm"},{"id":"c","text":"Mesoderm"},{"id":"d","text":"Neural crest"}],"answerId":"b","explanation":"The respiratory epithelium is derived from the endoderm.","kind":"recall","origin":"ai"},{"id":"germ-layer-derivatives-folding~ai-3","moduleId":"germ-layer-derivatives-folding","stem":"During embryonic folding, which structure is internalized to form the foregut?","options":[{"id":"a","text":"Lateral plate mesoderm"},{"id":"b","text":"Endoderm"},{"id":"c","text":"Neural crest"},{"id":"d","text":"Ectoderm"}],"answerId":"b","explanation":"The endoderm is internalized to form the foregut during embryonic folding.","kind":"mechanism","origin":"ai"},{"id":"germ-layer-derivatives-folding~ai-4","moduleId":"germ-layer-derivatives-folding","stem":"A patient presents with a congenital defect affecting the development of the kidney. Which germ layer is primarily responsible for this structure?","options":[{"id":"a","text":"Ectoderm"},{"id":"b","text":"Endoderm"},{"id":"c","text":"Paraxial mesoderm"},{"id":"d","text":"Intermediate mesoderm"}],"answerId":"d","explanation":"The kidney develops from the intermediate mesoderm.","kind":"clinical","origin":"ai"},{"id":"germ-layer-derivatives-folding~ai-5","moduleId":"germ-layer-derivatives-folding","stem":"Which of the following statements about organ development is true?","options":[{"id":"a","text":"All components of an organ are derived from the same germ layer."},{"id":"b","text":"Epithelial linings are always mesodermal."},{"id":"c","text":"Muscle and connective tissues can derive from different germ layers."},{"id":"d","text":"Endoderm exclusively forms the entire organ."}],"answerId":"c","explanation":"Muscle and connective tissues can derive from mesoderm, while the epithelial lining may be endodermal.","kind":"trap","origin":"ai"},{"id":"germ-layer-derivatives-folding~ai-6","moduleId":"germ-layer-derivatives-folding","stem":"How does the development of the esophagus relate to germ layer derivatives?","options":[{"id":"a","text":"It is entirely ectodermal."},{"id":"b","text":"It has a mesodermal muscular layer and endodermal lining."},{"id":"c","text":"It is derived solely from the endoderm."},{"id":"d","text":"It is formed from the lateral plate mesoderm."}],"answerId":"b","explanation":"The esophagus has a muscular layer derived from mesoderm and an epithelial lining from endoderm.","kind":"integration","linkedModuleIds":["gi-wall-esophagus-histology"],"origin":"ai"},{"id":"germ-layer-derivatives-folding~ai-7","moduleId":"germ-layer-derivatives-folding","stem":"Which embryonic process is essential for the proper positioning of the cardiogenic field?","options":[{"id":"a","text":"Gastrulation"},{"id":"b","text":"Neurulation"},{"id":"c","text":"Lateral folding"},{"id":"d","text":"Cranio-caudal folding"}],"answerId":"d","explanation":"Cranio-caudal folding is essential for repositioning the cardiogenic field during development.","kind":"integration","linkedModuleIds":["gastrulation-body-axis"],"origin":"ai"}],"cleavage-blastocyst-implantation":[{"id":"cleavage-blastocyst-implantation~ai-0","moduleId":"cleavage-blastocyst-implantation","stem":"What is the primary event that occurs during the cleavage stage of embryonic development?","options":[{"id":"a","text":"Cell growth and differentiation"},{"id":"b","text":"Repeated mitosis without overall growth"},{"id":"c","text":"Formation of the blastocyst cavity"},{"id":"d","text":"Implantation into the endometrium"}],"answerId":"b","explanation":"Cleavage involves repeated mitosis that increases cell number without increasing the overall size of the embryo.","kind":"recall","origin":"ai"},{"id":"cleavage-blastocyst-implantation~ai-1","moduleId":"cleavage-blastocyst-implantation","stem":"At which stage does compaction occur, establishing cell polarity?","options":[{"id":"a","text":"2-cell stage"},{"id":"b","text":"4-cell stage"},{"id":"c","text":"8-cell stage"},{"id":"d","text":"Morula stage"}],"answerId":"c","explanation":"Compaction occurs at the 8-cell stage, leading to the differentiation of embryoblast and trophoblast lineages.","kind":"recall","origin":"ai"},{"id":"cleavage-blastocyst-implantation~ai-2","moduleId":"cleavage-blastocyst-implantation","stem":"What is the consequence of hatching failure in the blastocyst?","options":[{"id":"a","text":"Normal implantation occurs"},{"id":"b","text":"Blastocyst cannot implant"},{"id":"c","text":"Embryoblast forms incorrectly"},{"id":"d","text":"Trophoblast invades the wrong tissue"}],"answerId":"b","explanation":"Hatching failure prevents the blastocyst from making contact with the endometrium, inhibiting normal implantation.","kind":"mechanism","origin":"ai"},{"id":"cleavage-blastocyst-implantation~ai-3","moduleId":"cleavage-blastocyst-implantation","stem":"Which finding indicates successful implantation in the uterine fundus?","options":[{"id":"a","text":"Blastocyst remains enclosed by zona pellucida"},{"id":"b","text":"Endometrial stromal cells enlarge"},{"id":"c","text":"Trophoblast invades the myometrium"},{"id":"d","text":"Embryoblast forms a bilaminar disc"}],"answerId":"b","explanation":"Enlargement of endometrial stromal cells is a sign of decidualization, which supports implantation.","kind":"recall","origin":"ai"},{"id":"cleavage-blastocyst-implantation~ai-4","moduleId":"cleavage-blastocyst-implantation","stem":"Which statement correctly describes the growth during cleavage?","options":[{"id":"a","text":"The embryo enlarges with every cleavage division"},{"id":"b","text":"Total conceptus size stays constrained by the zona pellucida"},{"id":"c","text":"Cell number decreases while size increases"},{"id":"d","text":"All cells become identical in size"}],"answerId":"b","explanation":"During cleavage, the total size of the conceptus remains constrained by the zona pellucida, while the number of cells increases.","kind":"trap","origin":"ai"},{"id":"cleavage-blastocyst-implantation~ai-5","moduleId":"cleavage-blastocyst-implantation","stem":"How does the process of capacitation relate to the cleavage stage of embryonic development?","options":[{"id":"a","text":"It prepares sperm for fertilization"},{"id":"b","text":"It initiates cleavage divisions"},{"id":"c","text":"It forms the blastocyst"},{"id":"d","text":"It triggers implantation"}],"answerId":"a","explanation":"Capacitation is a prerequisite for fertilization, which must occur before cleavage can begin.","kind":"integration","linkedModuleIds":["capacitation-fertilization"],"origin":"ai"},{"id":"cleavage-blastocyst-implantation~ai-6","moduleId":"cleavage-blastocyst-implantation","stem":"What is the significance of the inner cell mass in the blastocyst?","options":[{"id":"a","text":"It forms the trophoblast"},{"id":"b","text":"It develops into the embryo"},{"id":"c","text":"It initiates implantation"},{"id":"d","text":"It provides nutrients to the endometrium"}],"answerId":"b","explanation":"The inner cell mass differentiates into the embryo, while the outer trophoblast contributes to placental structures.","kind":"recall","origin":"ai"},{"id":"cleavage-blastocyst-implantation~ai-7","moduleId":"cleavage-blastocyst-implantation","stem":"How does the bilaminar disc relate to the implantation process?","options":[{"id":"a","text":"It forms during the cleavage stage"},{"id":"b","text":"It develops from the inner cell mass"},{"id":"c","text":"It is involved in trophoblast invasion"},{"id":"d","text":"It prevents hatching of the blastocyst"}],"answerId":"b","explanation":"The bilaminar disc forms from the inner cell mass after implantation, marking the beginning of embryonic development.","kind":"integration","linkedModuleIds":["bilaminar-disc-week-two"],"origin":"ai"}],"bilaminar-disc-week-two":[{"id":"bilaminar-disc-week-two~ai-0","moduleId":"bilaminar-disc-week-two","stem":"What is the primary function of syncytiotrophoblast during the second week of development?","options":[{"id":"a","text":"Secretes hCG"},{"id":"b","text":"Forms the bilaminar disc"},{"id":"c","text":"Provides nutrients to the embryo"},{"id":"d","text":"Develops the amniotic cavity"}],"answerId":"a","explanation":"Syncytiotrophoblast is responsible for secreting hCG, which is crucial for maintaining the early pregnancy.","kind":"recall","origin":"ai"},{"id":"bilaminar-disc-week-two~ai-1","moduleId":"bilaminar-disc-week-two","stem":"Which structure is formed from the inner cell mass during the second week of development?","options":[{"id":"a","text":"Chorionic cavity"},{"id":"b","text":"Amniotic cavity"},{"id":"c","text":"Bilaminar disc"},{"id":"d","text":"Yolk sac"}],"answerId":"c","explanation":"The inner cell mass differentiates into the bilaminar disc, consisting of epiblast and hypoblast.","kind":"recall","origin":"ai"},{"id":"bilaminar-disc-week-two~ai-2","moduleId":"bilaminar-disc-week-two","stem":"What is the role of the cytotrophoblast in early embryonic development?","options":[{"id":"a","text":"Forms the amniotic cavity"},{"id":"b","text":"Supplies cells to the syncytium"},{"id":"c","text":"Creates the yolk sac"},{"id":"d","text":"Secretes hCG"}],"answerId":"b","explanation":"Cytotrophoblast is mitotically active and provides cells to the syncytiotrophoblast layer.","kind":"mechanism","origin":"ai"},{"id":"bilaminar-disc-week-two~ai-3","moduleId":"bilaminar-disc-week-two","stem":"Which of the following findings is characteristic of syncytiotrophoblast?","options":[{"id":"a","text":"Mononuclear cells"},{"id":"b","text":"Multinucleated invasive layer"},{"id":"c","text":"Cuboidal cells"},{"id":"d","text":"Columnar cells"}],"answerId":"b","explanation":"Syncytiotrophoblast is a multinucleated layer that invades the uterine lining.","kind":"recall","origin":"ai"},{"id":"bilaminar-disc-week-two~ai-4","moduleId":"bilaminar-disc-week-two","stem":"The connecting stalk serves what purpose during the second week of development?","options":[{"id":"a","text":"Forms the amniotic cavity"},{"id":"b","text":"Links the embryo to the chorionic cavity"},{"id":"c","text":"Creates the yolk sac"},{"id":"d","text":"Develops the placenta"}],"answerId":"b","explanation":"The connecting stalk is the only bridge across the chorionic cavity, linking the embryo to the trophoblast.","kind":"clinical","origin":"ai"},{"id":"bilaminar-disc-week-two~ai-5","moduleId":"bilaminar-disc-week-two","stem":"Which statement correctly describes the origin of the bilaminar disc?","options":[{"id":"a","text":"Cytotrophoblast and syncytiotrophoblast form the bilaminar disc"},{"id":"b","text":"Epiblast and hypoblast form the bilaminar disc"},{"id":"c","text":"Only the epiblast contributes to the bilaminar disc"},{"id":"d","text":"The bilaminar disc forms from extraembryonic mesoderm"}],"answerId":"b","explanation":"The bilaminar disc is formed from the epiblast and hypoblast, while trophoblast layers are separate.","kind":"trap","origin":"ai"},{"id":"bilaminar-disc-week-two~ai-6","moduleId":"bilaminar-disc-week-two","stem":"How does the formation of the bilaminar disc relate to fertilization processes?","options":[{"id":"a","text":"It occurs immediately after fertilization"},{"id":"b","text":"It is influenced by sperm capacitation"},{"id":"c","text":"It is a result of cleavage divisions"},{"id":"d","text":"It is independent of fertilization events"}],"answerId":"c","explanation":"The bilaminar disc forms after cleavage divisions of the fertilized egg, linking it to fertilization processes.","kind":"integration","linkedModuleIds":["capacitation-fertilization"],"origin":"ai"},{"id":"bilaminar-disc-week-two~ai-7","moduleId":"bilaminar-disc-week-two","stem":"What is the significance of the yolk sac in relation to the bilaminar disc?","options":[{"id":"a","text":"It provides nutrients to the embryo"},{"id":"b","text":"It forms the amniotic cavity"},{"id":"c","text":"It is derived from the epiblast"},{"id":"d","text":"It is remodeled into the chorionic cavity"}],"answerId":"a","explanation":"The yolk sac provides early nutritional support to the embryo before the placenta is fully functional.","kind":"integration","linkedModuleIds":["cleavage-blastocyst-implantation"],"origin":"ai"}],"gastrulation-body-axis":[{"id":"gastrulation-body-axis~ai-0","moduleId":"gastrulation-body-axis","stem":"What is the primary outcome of gastrulation during week 3 of embryonic development?","options":[{"id":"a","text":"Formation of the heart"},{"id":"b","text":"Establishment of the trilaminar disc"},{"id":"c","text":"Development of the neural tube"},{"id":"d","text":"Differentiation of the placenta"}],"answerId":"b","explanation":"Gastrulation converts the bilaminar disc into a trilaminar disc, establishing the three germ layers.","kind":"recall","origin":"ai"},{"id":"gastrulation-body-axis~ai-1","moduleId":"gastrulation-body-axis","stem":"Which structure is responsible for organizing epiblast cell migration during gastrulation?","options":[{"id":"a","text":"Primitive streak"},{"id":"b","text":"Notochord"},{"id":"c","text":"Somites"},{"id":"d","text":"Neural plate"}],"answerId":"a","explanation":"The primitive streak is crucial for organizing the migration of epiblast cells.","kind":"mechanism","origin":"ai"},{"id":"gastrulation-body-axis~ai-2","moduleId":"gastrulation-body-axis","stem":"What is the definitive endoderm derived from during embryonic development?","options":[{"id":"a","text":"Hypoblast"},{"id":"b","text":"Mesoderm"},{"id":"c","text":"Epiblast"},{"id":"d","text":"Ectoderm"}],"answerId":"c","explanation":"Definitive endoderm is formed when epiblast cells replace the hypoblast.","kind":"trap","origin":"ai"},{"id":"gastrulation-body-axis~ai-3","moduleId":"gastrulation-body-axis","stem":"Which of the following findings indicates that gastrulation has completed?","options":[{"id":"a","text":"Presence of a bilaminar disc"},{"id":"b","text":"Formation of the trilaminar disc"},{"id":"c","text":"Development of somites"},{"id":"d","text":"Closure of the neural tube"}],"answerId":"b","explanation":"The formation of the trilaminar disc indicates that gastrulation has been completed.","kind":"recall","origin":"ai"},{"id":"gastrulation-body-axis~ai-4","moduleId":"gastrulation-body-axis","stem":"What is a consequence of disrupted axis signaling during gastrulation?","options":[{"id":"a","text":"Normal organ arrangement"},{"id":"b","text":"Abnormal left-right organ arrangement"},{"id":"c","text":"Increased mesoderm formation"},{"id":"d","text":"Failure of neural tube closure"}],"answerId":"b","explanation":"Disrupted axis signaling can lead to abnormal left-right organ arrangement.","kind":"recall","origin":"ai"},{"id":"gastrulation-body-axis~ai-5","moduleId":"gastrulation-body-axis","stem":"How does the mesoderm relate to the oropharyngeal membrane during gastrulation?","options":[{"id":"a","text":"It contributes to the membrane"},{"id":"b","text":"It is absent at the membrane"},{"id":"c","text":"It forms the ectoderm layer"},{"id":"d","text":"It becomes the definitive endoderm"}],"answerId":"b","explanation":"The mesoderm does not intervene at the oropharyngeal membrane, where ectoderm and endoderm remain apposed.","kind":"mechanism","origin":"ai"},{"id":"gastrulation-body-axis~ai-6","moduleId":"gastrulation-body-axis","stem":"How does gastrulation relate to cardiac development?","options":[{"id":"a","text":"It establishes the electrical axis of the heart"},{"id":"b","text":"It forms the cardiac mesoderm"},{"id":"c","text":"It influences heart rate"},{"id":"d","text":"It develops the cardiac valves"}],"answerId":"b","explanation":"Gastrulation is critical for forming the cardiac mesoderm, which gives rise to heart structures.","kind":"integration","linkedModuleIds":["cardiac-electrical-axis-vectors"],"origin":"ai"},{"id":"gastrulation-body-axis~ai-7","moduleId":"gastrulation-body-axis","stem":"Which germ layer is primarily responsible for developing the parathyroid glands?","options":[{"id":"a","text":"Ectoderm"},{"id":"b","text":"Mesoderm"},{"id":"c","text":"Endoderm"},{"id":"d","text":"Hypoblast"}],"answerId":"c","explanation":"The parathyroid glands develop from the endoderm layer during embryogenesis.","kind":"integration","linkedModuleIds":["hen1-parathyroid-anatomy-development-histology"],"origin":"ai"}],"teratogenesis-critical-periods":[{"id":"teratogenesis-critical-periods~ai-0","moduleId":"teratogenesis-critical-periods","stem":"What is the critical period for major structural malformations due to teratogen exposure?","options":[{"id":"a","text":"Weeks 1-2"},{"id":"b","text":"Weeks 3-8"},{"id":"c","text":"Weeks 9-12"},{"id":"d","text":"Weeks 13-16"}],"answerId":"b","explanation":"Weeks 3-8 are maximally sensitive for major structural malformations as organ primordia are forming.","kind":"recall","origin":"ai"},{"id":"teratogenesis-critical-periods~ai-1","moduleId":"teratogenesis-critical-periods","stem":"Which of the following best describes a teratogen?","options":[{"id":"a","text":"Any substance that causes birth defects"},{"id":"b","text":"A substance that causes genetic mutations"},{"id":"c","text":"A substance whose effects depend on timing and dose"},{"id":"d","text":"Any drug taken during pregnancy"}],"answerId":"c","explanation":"A teratogen's effects depend on the timing, dose, and the genotype of the embryo.","kind":"mechanism","origin":"ai"},{"id":"teratogenesis-critical-periods~ai-2","moduleId":"teratogenesis-critical-periods","stem":"A mother takes a medication during pregnancy. What factor is least likely to influence the teratogenic outcome?","options":[{"id":"a","text":"Timing of exposure"},{"id":"b","text":"Genotype of the embryo"},{"id":"c","text":"Maternal age"},{"id":"d","text":"Dose of the drug"}],"answerId":"c","explanation":"While maternal age can influence pregnancy outcomes, it is less directly related to teratogenic effects compared to timing, genotype, and dose.","kind":"trap","origin":"ai"},{"id":"teratogenesis-critical-periods~ai-3","moduleId":"teratogenesis-critical-periods","stem":"Which clinical finding is most consistent with teratogenic exposure during the fetal period?","options":[{"id":"a","text":"Major organ malformation"},{"id":"b","text":"Functional CNS deficit"},{"id":"c","text":"All-or-none effect"},{"id":"d","text":"Growth restriction"}],"answerId":"b","explanation":"During the fetal period, exposures often lead to functional CNS deficits as the CNS remains vulnerable.","kind":"clinical","origin":"ai"},{"id":"teratogenesis-critical-periods~ai-4","moduleId":"teratogenesis-critical-periods","stem":"What is a common outcome of teratogen exposure during weeks 1-2 of pregnancy?","options":[{"id":"a","text":"Major organ malformation"},{"id":"b","text":"Functional CNS deficit"},{"id":"c","text":"Embryonic death or all-or-none effect"},{"id":"d","text":"Minor anomalies"}],"answerId":"c","explanation":"Very early exposure may lead to embryonic death or an all-or-none effect.","kind":"recall","origin":"ai"},{"id":"teratogenesis-critical-periods~ai-5","moduleId":"teratogenesis-critical-periods","stem":"How does the timing of teratogen exposure affect its outcome?","options":[{"id":"a","text":"It does not affect the outcome"},{"id":"b","text":"It only affects the severity of the defect"},{"id":"c","text":"It can lead to different anomalies based on developmental stage"},{"id":"d","text":"It is only relevant for genetic teratogens"}],"answerId":"c","explanation":"The same exposure can produce different outcomes depending on the timing of exposure during development.","kind":"mechanism","origin":"ai"},{"id":"teratogenesis-critical-periods~ai-6","moduleId":"teratogenesis-critical-periods","stem":"Which teratogenic effect might be classified under congenital anomalies?","options":[{"id":"a","text":"Cleft lip"},{"id":"b","text":"Maternal diabetes"},{"id":"c","text":"Fetal alcohol syndrome"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"All listed options represent congenital anomalies that can arise from teratogenic exposures.","kind":"integration","linkedModuleIds":["congenital-anomaly-classification"],"origin":"ai"},{"id":"teratogenesis-critical-periods~ai-7","moduleId":"teratogenesis-critical-periods","stem":"How does teratogenesis relate to action potential propagation in neural development?","options":[{"id":"a","text":"Both are unaffected by timing"},{"id":"b","text":"Teratogens can disrupt neural signaling"},{"id":"c","text":"Action potentials are only relevant post-birth"},{"id":"d","text":"Teratogens do not affect the CNS"}],"answerId":"b","explanation":"Teratogens can disrupt neural signaling and development, affecting action potential propagation in the CNS.","kind":"integration","linkedModuleIds":["action-potential-propagation-refractory"],"origin":"ai"}],"congenital-anomaly-classification":[{"id":"congenital-anomaly-classification~ai-0","moduleId":"congenital-anomaly-classification","stem":"What is the primary mechanism behind a congenital anomaly caused by amniotic band syndrome?","options":[{"id":"a","text":"Malformation"},{"id":"b","text":"Disruption"},{"id":"c","text":"Deformation"},{"id":"d","text":"Dysplasia"}],"answerId":"b","explanation":"Amniotic band syndrome results from the extrinsic destruction of tissue that had initially developed normally, classifying it as a disruption.","kind":"mechanism","origin":"ai"},{"id":"congenital-anomaly-classification~ai-1","moduleId":"congenital-anomaly-classification","stem":"Which of the following best describes a sequence in congenital anomalies?","options":[{"id":"a","text":"A nonrandom cluster of anomalies"},{"id":"b","text":"A cascade from one initiating defect"},{"id":"c","text":"A recognizable set caused by one defined etiology"},{"id":"d","text":"An intrinsic error of formation"}],"answerId":"b","explanation":"A sequence refers to a cascade of anomalies stemming from a single initiating defect, such as oligohydramnios leading to Potter sequence.","kind":"recall","origin":"ai"},{"id":"congenital-anomaly-classification~ai-2","moduleId":"congenital-anomaly-classification","stem":"Which of the following is an example of a malformation?","options":[{"id":"a","text":"Amniotic band syndrome"},{"id":"b","text":"Potter sequence"},{"id":"c","text":"Syndactyly"},{"id":"d","text":"Ectopia cordis"}],"answerId":"c","explanation":"Syndactyly is an intrinsic error of formation where there is failure of separation of digits, making it a malformation.","kind":"recall","origin":"ai"},{"id":"congenital-anomaly-classification~ai-3","moduleId":"congenital-anomaly-classification","stem":"A newborn presents with Potter facies and limb positioning abnormalities. What is the likely mechanism involved?","options":[{"id":"a","text":"Malformation"},{"id":"b","text":"Disruption"},{"id":"c","text":"Deformation"},{"id":"d","text":"Dysplasia"}],"answerId":"c","explanation":"The limb positioning abnormalities are due to mechanical forces acting on the fetus, classifying this as a deformation.","kind":"mechanism","origin":"ai"},{"id":"congenital-anomaly-classification~ai-4","moduleId":"congenital-anomaly-classification","stem":"Which of the following statements about congenital anomalies is correct?","options":[{"id":"a","text":"All congenital structural defects are malformations."},{"id":"b","text":"Disruption is intrinsic damage to tissue."},{"id":"c","text":"Dysplasia refers to abnormal cellular organization."},{"id":"d","text":"A sequence is a nonrandom cluster of anomalies."}],"answerId":"c","explanation":"Dysplasia specifically refers to abnormal cellular organization within a tissue, distinguishing it from malformations and disruptions.","kind":"trap","origin":"ai"},{"id":"congenital-anomaly-classification~ai-5","moduleId":"congenital-anomaly-classification","stem":"How does a congenital anomaly of the kidney relate to teratogenesis?","options":[{"id":"a","text":"Both can be caused by genetic mutations."},{"id":"b","text":"Both arise from mechanical forces during development."},{"id":"c","text":"Both can result from disruptions during critical periods."},{"id":"d","text":"Both are classified as syndromes."}],"answerId":"c","explanation":"Congenital anomalies of the kidney can arise from disruptions during critical periods of development, linking them to teratogenesis.","kind":"integration","linkedModuleIds":["teratogenesis-critical-periods"],"origin":"ai"},{"id":"congenital-anomaly-classification~ai-6","moduleId":"congenital-anomaly-classification","stem":"Which of the following congenital anomalies is most likely to be classified as a syndrome?","options":[{"id":"a","text":"Spina bifida"},{"id":"b","text":"Potter sequence"},{"id":"c","text":"Trisomy 21"},{"id":"d","text":"Syndactyly"}],"answerId":"c","explanation":"Trisomy 21 is a recognizable set of anomalies caused by a defined chromosomal etiology, thus classified as a syndrome.","kind":"integration","linkedModuleIds":["kub-congenital-anomalies"],"origin":"ai"}],"placenta-development-circulation":[{"id":"placenta-development-circulation~ai-0","moduleId":"placenta-development-circulation","stem":"Which hormone is primarily produced by the placenta to maintain pregnancy?","options":[{"id":"a","text":"Estrogen"},{"id":"b","text":"hCG"},{"id":"c","text":"Progesterone"},{"id":"d","text":"hPL"}],"answerId":"c","explanation":"Progesterone is crucial for maintaining the uterine lining and preventing contractions during pregnancy.","kind":"recall","origin":"ai"},{"id":"placenta-development-circulation~ai-1","moduleId":"placenta-development-circulation","stem":"What is the primary fetal component of the placenta?","options":[{"id":"a","text":"Decidua basalis"},{"id":"b","text":"Chorion frondosum"},{"id":"c","text":"Chorion laeve"},{"id":"d","text":"Amnion"}],"answerId":"b","explanation":"The chorion frondosum is the fetal component that forms the functional part of the placenta.","kind":"recall","origin":"ai"},{"id":"placenta-development-circulation~ai-2","moduleId":"placenta-development-circulation","stem":"Which structure is responsible for the attachment of the placenta to the uterine wall?","options":[{"id":"a","text":"Chorionic plate"},{"id":"b","text":"Cytotrophoblastic shell"},{"id":"c","text":"Decidual septa"},{"id":"d","text":"Umbilical cord"}],"answerId":"b","explanation":"The cytotrophoblastic shell anchors the placenta by embedding into the maternal decidua.","kind":"mechanism","origin":"ai"},{"id":"placenta-development-circulation~ai-3","moduleId":"placenta-development-circulation","stem":"What is the mechanism by which maternal blood enters the intervillous space?","options":[{"id":"a","text":"Through umbilical arteries"},{"id":"b","text":"Via spiral arteries"},{"id":"c","text":"From the chorionic plate"},{"id":"d","text":"Through the amniotic cavity"}],"answerId":"b","explanation":"Maternal blood enters the intervillous space through spiral arteries, providing nutrients and oxygen to the fetus.","kind":"mechanism","origin":"ai"},{"id":"placenta-development-circulation~ai-4","moduleId":"placenta-development-circulation","stem":"A pregnant woman presents with a smooth shiny fetal surface on ultrasound. What does this indicate?","options":[{"id":"a","text":"Normal placental development"},{"id":"b","text":"Decidual septa formation"},{"id":"c","text":"Chorionic villi maturation"},{"id":"d","text":"Umbilical cord abnormalities"}],"answerId":"a","explanation":"A smooth shiny fetal surface indicates a normal amnion-covered chorionic plate, typical of healthy placental development.","kind":"recall","origin":"ai"},{"id":"placenta-development-circulation~ai-5","moduleId":"placenta-development-circulation","stem":"Which of the following statements about the placental circulation is true?","options":[{"id":"a","text":"Maternal and fetal blood mix in the intervillous space"},{"id":"b","text":"Fetal blood is oxygenated in the umbilical arteries"},{"id":"c","text":"Maternal blood enters through the umbilical vein"},{"id":"d","text":"Oxygenated fetal blood returns through the umbilical vein"}],"answerId":"d","explanation":"Oxygenated fetal blood returns to the fetus via the umbilical vein after passing through the placenta.","kind":"trap","origin":"ai"},{"id":"placenta-development-circulation~ai-6","moduleId":"placenta-development-circulation","stem":"How does the placenta contribute to maternal metabolic adaptation during pregnancy?","options":[{"id":"a","text":"By producing insulin"},{"id":"b","text":"By secreting hPL"},{"id":"c","text":"By increasing maternal blood volume"},{"id":"d","text":"By enhancing glucose uptake in the liver"}],"answerId":"b","explanation":"hPL (human placental lactogen) plays a key role in maternal metabolic adaptation by modulating maternal glucose and lipid metabolism.","kind":"integration","linkedModuleIds":["hrp1-hpl-placental-gh-crh"],"origin":"ai"},{"id":"placenta-development-circulation~ai-7","moduleId":"placenta-development-circulation","stem":"Which placental structure is crucial for the exchange of gases and nutrients between maternal and fetal blood?","options":[{"id":"a","text":"Chorionic villi"},{"id":"b","text":"Decidua basalis"},{"id":"c","text":"Umbilical cord"},{"id":"d","text":"Amnion"}],"answerId":"a","explanation":"Chorionic villi are the sites of exchange between maternal and fetal blood, facilitating nutrient and gas transfer.","kind":"integration","linkedModuleIds":["hrp1-placenta-villi-barrier-circulation"],"origin":"ai"}],"notochord-neurulation-neural-crest":[{"id":"notochord-neurulation-neural-crest~ai-0","moduleId":"notochord-neurulation-neural-crest","stem":"What is the embryologic origin of the nucleus pulposus in the intervertebral disc?","options":[{"id":"a","text":"Sclerotome"},{"id":"b","text":"Notochord"},{"id":"c","text":"Mesoderm"},{"id":"d","text":"Neural crest"}],"answerId":"b","explanation":"The nucleus pulposus is a remnant of the notochord, while the sclerotome contributes to the surrounding vertebral structures.","kind":"recall","origin":"ai"},{"id":"notochord-neurulation-neural-crest~ai-1","moduleId":"notochord-neurulation-neural-crest","stem":"Which structure induces the overlying ectoderm to form the neural plate?","options":[{"id":"a","text":"Notochord"},{"id":"b","text":"Sclerotome"},{"id":"c","text":"Neural crest"},{"id":"d","text":"Somites"}],"answerId":"a","explanation":"The notochord acts as an axial organizer and induces the ectoderm to differentiate into neuroectoderm.","kind":"mechanism","origin":"ai"},{"id":"notochord-neurulation-neural-crest~ai-2","moduleId":"notochord-neurulation-neural-crest","stem":"What is a clinical consequence of failed closure of the caudal neuropore?","options":[{"id":"a","text":"Spina bifida"},{"id":"b","text":"Anencephaly"},{"id":"c","text":"Hydrocephalus"},{"id":"d","text":"Craniosynostosis"}],"answerId":"a","explanation":"Failure of the caudal neuropore to close can lead to spina bifida, a type of neural tube defect.","kind":"clinical","origin":"ai"},{"id":"notochord-neurulation-neural-crest~ai-3","moduleId":"notochord-neurulation-neural-crest","stem":"Neural crest cells contribute to which of the following structures?","options":[{"id":"a","text":"Vertebral bodies"},{"id":"b","text":"Peripheral ganglia"},{"id":"c","text":"Nucleus pulposus"},{"id":"d","text":"Neural tube"}],"answerId":"b","explanation":"Neural crest cells migrate to form various structures, including peripheral and autonomic ganglia.","kind":"recall","origin":"ai"},{"id":"notochord-neurulation-neural-crest~ai-4","moduleId":"notochord-neurulation-neural-crest","stem":"Which of the following findings indicates a failure of dorsal neural tube closure?","options":[{"id":"a","text":"Nucleus pulposus presence"},{"id":"b","text":"Cranial neuropore closure"},{"id":"c","text":"Spina bifida"},{"id":"d","text":"Neural crest migration"}],"answerId":"c","explanation":"Spina bifida is a direct result of failed dorsal neural tube closure.","kind":"recall","origin":"ai"},{"id":"notochord-neurulation-neural-crest~ai-5","moduleId":"notochord-neurulation-neural-crest","stem":"How does the notochord contribute to the formation of the neural tube?","options":[{"id":"a","text":"By forming the neural crest"},{"id":"b","text":"By inducing ectoderm to become neuroectoderm"},{"id":"c","text":"By creating the vertebral column"},{"id":"d","text":"By closing the neuropores"}],"answerId":"b","explanation":"The notochord induces the overlying ectoderm to differentiate into neuroectoderm, leading to neural tube formation.","kind":"mechanism","origin":"ai"},{"id":"notochord-neurulation-neural-crest~ai-6","moduleId":"notochord-neurulation-neural-crest","stem":"A child presents with pigment, peripheral ganglion, and adrenal-medulla defects. What is the most likely cause?","options":[{"id":"a","text":"Notochord defect"},{"id":"b","text":"Neural crest defect"},{"id":"c","text":"Sclerotome defect"},{"id":"d","text":"Ectoderm defect"}],"answerId":"b","explanation":"These defects are indicative of a failure in neural crest cell migration and differentiation.","kind":"clinical","origin":"ai"},{"id":"notochord-neurulation-neural-crest~ai-7","moduleId":"notochord-neurulation-neural-crest","stem":"Which embryonic structure is essential for the development of the adrenal medulla?","options":[{"id":"a","text":"Notochord"},{"id":"b","text":"Neural crest"},{"id":"c","text":"Somites"},{"id":"d","text":"Endoderm"}],"answerId":"b","explanation":"Neural crest cells migrate to form the adrenal medulla, among other structures.","kind":"integration","linkedModuleIds":["hen1-adrenal-development"],"origin":"ai"},{"id":"notochord-neurulation-neural-crest~ai-8","moduleId":"notochord-neurulation-neural-crest","stem":"What is a common embryologic origin for both neural crest cells and structures of the peripheral nervous system?","options":[{"id":"a","text":"Mesoderm"},{"id":"b","text":"Ectoderm"},{"id":"c","text":"Endoderm"},{"id":"d","text":"Sclerotome"}],"answerId":"b","explanation":"Both neural crest cells and the peripheral nervous system derive from ectoderm.","kind":"integration","linkedModuleIds":["neuroblastoma"],"origin":"ai"}],"preembryonic-clinical-applications":[{"id":"preembryonic-clinical-applications~ai-0","moduleId":"preembryonic-clinical-applications","stem":"What is the most common site for ectopic pregnancy?","options":[{"id":"a","text":"Ovary"},{"id":"b","text":"Uterine tube"},{"id":"c","text":"Cervix"},{"id":"d","text":"Abdominal cavity"}],"answerId":"b","explanation":"Ectopic pregnancies most commonly occur in the uterine tube due to the obstruction of normal transport of the fertilized egg.","kind":"recall","origin":"ai"},{"id":"preembryonic-clinical-applications~ai-1","moduleId":"preembryonic-clinical-applications","stem":"Which assisted reproductive technique involves the direct injection of sperm into an oocyte?","options":[{"id":"a","text":"In vitro fertilization"},{"id":"b","text":"Artificial insemination"},{"id":"c","text":"Intracytoplasmic sperm injection"},{"id":"d","text":"Gamete intrafallopian transfer"}],"answerId":"c","explanation":"Intracytoplasmic sperm injection (ICSI) directly injects a single sperm into an oocyte to facilitate fertilization.","kind":"recall","origin":"ai"},{"id":"preembryonic-clinical-applications~ai-2","moduleId":"preembryonic-clinical-applications","stem":"A patient presents with positive hCG, pelvic pain, and no visible intrauterine pregnancy on ultrasound. What is the most likely diagnosis?","options":[{"id":"a","text":"Complete hydatidiform mole"},{"id":"b","text":"Ectopic pregnancy"},{"id":"c","text":"Normal intrauterine pregnancy"},{"id":"d","text":"Partial hydatidiform mole"}],"answerId":"b","explanation":"The combination of positive hCG, pelvic pain, and absence of an intrauterine pregnancy suggests an ectopic pregnancy until proven otherwise.","kind":"clinical","origin":"ai"},{"id":"preembryonic-clinical-applications~ai-3","moduleId":"preembryonic-clinical-applications","stem":"What is the primary mechanism by which hCG supports early pregnancy?","options":[{"id":"a","text":"Stimulating uterine contractions"},{"id":"b","text":"Maintaining corpus luteum function"},{"id":"c","text":"Promoting fetal tissue growth"},{"id":"d","text":"Inhibiting trophoblast differentiation"}],"answerId":"b","explanation":"hCG maintains the corpus luteum, which is crucial for progesterone production in early pregnancy.","kind":"mechanism","origin":"ai"},{"id":"preembryonic-clinical-applications~ai-4","moduleId":"preembryonic-clinical-applications","stem":"A patient has a positive pregnancy test but presents with severe abdominal pain. What is the most critical next step in management?","options":[{"id":"a","text":"Administer pain relief"},{"id":"b","text":"Order a transvaginal ultrasound"},{"id":"c","text":"Perform a serum hCG quantification"},{"id":"d","text":"Refer for genetic counseling"}],"answerId":"b","explanation":"Transvaginal ultrasound is essential to localize the pregnancy and rule out ectopic pregnancy.","kind":"clinical","origin":"ai"},{"id":"preembryonic-clinical-applications~ai-5","moduleId":"preembryonic-clinical-applications","stem":"Which of the following statements about hydatidiform moles is true?","options":[{"id":"a","text":"Complete moles contain fetal tissue."},{"id":"b","text":"Partial moles are typically diploid."},{"id":"c","text":"Complete moles are usually androgenetic."},{"id":"d","text":"Partial moles are always triploid."}],"answerId":"c","explanation":"Complete hydatidiform moles are typically androgenetic and do not contain fetal tissue, while partial moles can contain fetal tissue and are often triploid.","kind":"trap","origin":"ai"},{"id":"preembryonic-clinical-applications~ai-6","moduleId":"preembryonic-clinical-applications","stem":"How does fertilization age differ from gestational age, and why is this important in clinical practice?","options":[{"id":"a","text":"Fertilization age is 2 weeks more than gestational age."},{"id":"b","text":"Gestational age is counted from fertilization, while fertilization age is from LMP."},{"id":"c","text":"Gestational age is counted from LMP, which adds about 2 weeks to fertilization age."},{"id":"d","text":"Fertilization age is used for dating pregnancies in all cases."}],"answerId":"c","explanation":"Gestational age is calculated from the last menstrual period (LMP), which is approximately 2 weeks longer than the actual fertilization age.","kind":"integration","linkedModuleIds":["capacitation-fertilization"],"origin":"ai"},{"id":"preembryonic-clinical-applications~ai-7","moduleId":"preembryonic-clinical-applications","stem":"In the context of ectopic pregnancy, how does the mechanism of implantation differ from normal uterine implantation?","options":[{"id":"a","text":"Ectopic implantation occurs in the endometrium."},{"id":"b","text":"Ectopic implantation is always associated with abnormal hCG levels."},{"id":"c","text":"Ectopic implantation can occur in the uterine tube, leading to different clinical outcomes."},{"id":"d","text":"Ectopic implantation does not involve trophoblasts."}],"answerId":"c","explanation":"Ectopic implantation occurs outside the endometrium, most commonly in the uterine tube, leading to different clinical presentations and outcomes.","kind":"integration","linkedModuleIds":["cleavage-blastocyst-implantation"],"origin":"ai"}],"gastrulation-clinical-stem-cells":[{"id":"gastrulation-clinical-stem-cells~ai-0","moduleId":"gastrulation-clinical-stem-cells","stem":"What is the primary consequence of persistence of primitive-streak cells during gastrulation?","options":[{"id":"a","text":"Formation of a sacrococcygeal teratoma"},{"id":"b","text":"Development of situs inversus"},{"id":"c","text":"Caudal regression syndrome"},{"id":"d","text":"Creation of a unipotent stem cell"}],"answerId":"a","explanation":"Persistence of primitive-streak cells can lead to the formation of a sacrococcygeal teratoma, which contains tissues from multiple germ layers due to the cells' retained developmental potential.","kind":"recall","origin":"ai"},{"id":"gastrulation-clinical-stem-cells~ai-1","moduleId":"gastrulation-clinical-stem-cells","stem":"Which type of stem cell can give rise to all embryonic tissues but not extraembryonic tissues?","options":[{"id":"a","text":"Totipotent stem cell"},{"id":"b","text":"Pluripotent stem cell"},{"id":"c","text":"Multipotent stem cell"},{"id":"d","text":"Unipotent stem cell"}],"answerId":"b","explanation":"Pluripotent stem cells can differentiate into all three germ layers but cannot form extraembryonic tissues, which is the defining feature of totipotent cells.","kind":"recall","origin":"ai"},{"id":"gastrulation-clinical-stem-cells~ai-2","moduleId":"gastrulation-clinical-stem-cells","stem":"A newborn presents with lower-limb and lumbosacral defects. Which condition is most likely responsible?","options":[{"id":"a","text":"Situs inversus"},{"id":"b","text":"Caudal regression syndrome"},{"id":"c","text":"Sacrococcygeal teratoma"},{"id":"d","text":"Primitive streak persistence"}],"answerId":"b","explanation":"Caudal regression syndrome is associated with defects in the caudal mesoderm during gastrulation, leading to lower-limb and lumbosacral anomalies.","kind":"clinical","origin":"ai"},{"id":"gastrulation-clinical-stem-cells~ai-3","moduleId":"gastrulation-clinical-stem-cells","stem":"Which signaling pathway is disrupted in cases of situs inversus?","options":[{"id":"a","text":"Wnt signaling"},{"id":"b","text":"Nodal/Lefty/Pitx2 pathways"},{"id":"c","text":"Hedgehog signaling"},{"id":"d","text":"Notch signaling"}],"answerId":"b","explanation":"Disordered left-right signaling, particularly involving the Nodal/Lefty/Pitx2 pathways, can result in situs inversus or heterotaxy.","kind":"mechanism","origin":"ai"},{"id":"gastrulation-clinical-stem-cells~ai-4","moduleId":"gastrulation-clinical-stem-cells","stem":"What is the key distinction between totipotent and pluripotent stem cells?","options":[{"id":"a","text":"Totipotent cells can form all embryonic tissues only"},{"id":"b","text":"Pluripotent cells can form extraembryonic tissues"},{"id":"c","text":"Totipotent cells can form both embryonic and extraembryonic tissues"},{"id":"d","text":"Pluripotent cells are restricted to one lineage"}],"answerId":"c","explanation":"Totipotent cells have the ability to form both embryonic and extraembryonic tissues, while pluripotent cells can only form embryonic tissues.","kind":"trap","origin":"ai"},{"id":"gastrulation-clinical-stem-cells~ai-5","moduleId":"gastrulation-clinical-stem-cells","stem":"How does caudal regression syndrome relate to gastrulation defects?","options":[{"id":"a","text":"It results from abnormal left-right axis formation."},{"id":"b","text":"It is caused by failure of mesodermal differentiation."},{"id":"c","text":"It arises from abnormal development of the caudal mesoderm."},{"id":"d","text":"It is linked to improper formation of the primitive streak."}],"answerId":"c","explanation":"Caudal regression syndrome is directly related to abnormal development of the caudal mesoderm during gastrulation.","kind":"integration","linkedModuleIds":["gastrulation-body-axis"],"origin":"ai"},{"id":"gastrulation-clinical-stem-cells~ai-6","moduleId":"gastrulation-clinical-stem-cells","stem":"Which embryological defect can lead to complications in fetal circulation due to abnormal positioning of organs?","options":[{"id":"a","text":"Sacrococcygeal teratoma"},{"id":"b","text":"Caudal regression syndrome"},{"id":"c","text":"Situs inversus"},{"id":"d","text":"Primitive streak persistence"}],"answerId":"c","explanation":"Situs inversus can lead to abnormal organ positioning, which may complicate fetal circulation and shunting mechanisms.","kind":"integration","linkedModuleIds":["fetal-circulation-shunts"],"origin":"ai"}],"gametogenesis-female-tract":[{"id":"gametogenesis-female-tract~ai-0","moduleId":"gametogenesis-female-tract","stem":"What is the primary outcome of meiosis in oogenesis?","options":[{"id":"a","text":"Two diploid cells"},{"id":"b","text":"One diploid cell and one haploid cell"},{"id":"c","text":"One haploid cell and two polar bodies"},{"id":"d","text":"Four haploid cells"}],"answerId":"c","explanation":"Meiosis in oogenesis results in one definitive haploid ovum and two or three polar bodies, which are non-functional.","kind":"recall","origin":"ai"},{"id":"gametogenesis-female-tract~ai-1","moduleId":"gametogenesis-female-tract","stem":"At what stage does the primary oocyte remain arrested until ovulation?","options":[{"id":"a","text":"Prophase I"},{"id":"b","text":"Metaphase I"},{"id":"c","text":"Metaphase II"},{"id":"d","text":"Anaphase II"}],"answerId":"a","explanation":"Primary oocytes are arrested in prophase I until the onset of puberty and subsequent ovulation.","kind":"recall","origin":"ai"},{"id":"gametogenesis-female-tract~ai-2","moduleId":"gametogenesis-female-tract","stem":"What structure is primarily responsible for fertilization in the female reproductive tract?","options":[{"id":"a","text":"Uterus"},{"id":"b","text":"Cervix"},{"id":"c","text":"Ampulla of the uterine tube"},{"id":"d","text":"Fimbriae"}],"answerId":"c","explanation":"Fertilization typically occurs in the ampulla of the uterine tube, where the sperm meets the ovulated secondary oocyte.","kind":"recall","origin":"ai"},{"id":"gametogenesis-female-tract~ai-3","moduleId":"gametogenesis-female-tract","stem":"Which statement correctly describes the ovulated female gamete?","options":[{"id":"a","text":"It is a fully mature ovum ready for fertilization."},{"id":"b","text":"It is a secondary oocyte arrested in metaphase II."},{"id":"c","text":"It has completed meiosis II prior to ovulation."},{"id":"d","text":"It is a primary oocyte ready for fertilization."}],"answerId":"b","explanation":"The ovulated female gamete is a secondary oocyte that is arrested in metaphase II and completes meiosis II only upon fertilization.","kind":"trap","origin":"ai"},{"id":"gametogenesis-female-tract~ai-4","moduleId":"gametogenesis-female-tract","stem":"What is the fate of the secondary oocyte if fertilization does not occur?","options":[{"id":"a","text":"It completes meiosis II and becomes a mature ovum."},{"id":"b","text":"It degenerates and is absorbed by the body."},{"id":"c","text":"It is expelled during menstruation."},{"id":"d","text":"It continues to develop into a zygote."}],"answerId":"b","explanation":"If fertilization does not occur, the secondary oocyte degenerates and is eventually absorbed by the body.","kind":"clinical","origin":"ai"},{"id":"gametogenesis-female-tract~ai-5","moduleId":"gametogenesis-female-tract","stem":"How does the process of oogenesis ensure genetic diversity?","options":[{"id":"a","text":"Through mitosis"},{"id":"b","text":"By random fertilization"},{"id":"c","text":"Through crossing over during meiosis"},{"id":"d","text":"By producing multiple ovum"}],"answerId":"c","explanation":"Genetic diversity in oogenesis is primarily achieved through crossing over during meiosis, which allows for the exchange of genetic material.","kind":"mechanism","origin":"ai"},{"id":"gametogenesis-female-tract~ai-6","moduleId":"gametogenesis-female-tract","stem":"During which developmental period does oogenesis begin?","options":[{"id":"a","text":"At birth"},{"id":"b","text":"At puberty"},{"id":"c","text":"Prenatally"},{"id":"d","text":"Postnatally"}],"answerId":"c","explanation":"Oogenesis begins prenatally, with primary oocytes forming and arresting in prophase I until puberty.","kind":"recall","origin":"ai"},{"id":"gametogenesis-female-tract~ai-7","moduleId":"gametogenesis-female-tract","stem":"How does the uterine tube anatomy relate to fertilization?","options":[{"id":"a","text":"The infundibulum captures the ovulated oocyte."},{"id":"b","text":"The isthmus is the site of fertilization."},{"id":"c","text":"The ampulla transports sperm to the ovary."},{"id":"d","text":"The fimbriae support implantation."}],"answerId":"a","explanation":"The infundibulum of the uterine tube has fimbriae that help capture the ovulated oocyte, facilitating fertilization.","kind":"integration","linkedModuleIds":["hrp1-uterine-tube-ovary-lymph"],"origin":"ai"},{"id":"gametogenesis-female-tract~ai-8","moduleId":"gametogenesis-female-tract","stem":"What is the relationship between spermatogenesis and oogenesis in terms of timing?","options":[{"id":"a","text":"Both processes begin at puberty."},{"id":"b","text":"Spermatogenesis begins prenatally, while oogenesis begins at puberty."},{"id":"c","text":"Oogenesis begins prenatally, while spermatogenesis begins at puberty."},{"id":"d","text":"Both processes are completed before birth."}],"answerId":"c","explanation":"Oogenesis begins prenatally and continues into adulthood, while spermatogenesis starts at puberty.","kind":"integration","linkedModuleIds":["hrp1-seminiferous-epithelium-spermatogenesis"],"origin":"ai"}],"capacitation-fertilization":[{"id":"capacitation-fertilization~ai-0","moduleId":"capacitation-fertilization","stem":"Where does fertilization typically occur in the female reproductive system?","options":[{"id":"a","text":"Ovary"},{"id":"b","text":"Ampulla of the uterine tube"},{"id":"c","text":"Uterus"},{"id":"d","text":"Cervix"}],"answerId":"b","explanation":"Fertilization most commonly occurs in the ampulla of the uterine tube, where the sperm meets the ovulated oocyte.","kind":"recall","origin":"ai"},{"id":"capacitation-fertilization~ai-1","moduleId":"capacitation-fertilization","stem":"What is the primary role of capacitation in sperm function?","options":[{"id":"a","text":"To enable sperm motility"},{"id":"b","text":"To modify sperm-surface coatings"},{"id":"c","text":"To facilitate sperm-oocyte fusion"},{"id":"d","text":"To enhance sperm lifespan"}],"answerId":"b","explanation":"Capacitation modifies the sperm-surface coatings, making sperm competent to bind to the zona pellucida.","kind":"mechanism","origin":"ai"},{"id":"capacitation-fertilization~ai-2","moduleId":"capacitation-fertilization","stem":"What occurs immediately after sperm entry into the oocyte?","options":[{"id":"a","text":"Sperm undergoes meiosis"},{"id":"b","text":"Oocyte completes meiosis II"},{"id":"c","text":"Cortical granules are released"},{"id":"d","text":"Zona pellucida thickens"}],"answerId":"b","explanation":"Sperm entry triggers the completion of meiosis II in the oocyte, resulting in the formation of the female pronucleus.","kind":"clinical","origin":"ai"},{"id":"capacitation-fertilization~ai-3","moduleId":"capacitation-fertilization","stem":"What is the consequence of a failed cortical reaction during fertilization?","options":[{"id":"a","text":"Increased sperm motility"},{"id":"b","text":"Polyspermy"},{"id":"c","text":"Incomplete meiosis"},{"id":"d","text":"Sperm cannot bind to zona"}],"answerId":"b","explanation":"A failed cortical reaction allows multiple sperm to enter the oocyte, leading to polyspermy.","kind":"trap","origin":"ai"},{"id":"capacitation-fertilization~ai-4","moduleId":"capacitation-fertilization","stem":"Which of the following best describes the mechanism of the acrosomal reaction?","options":[{"id":"a","text":"Sperm releases enzymes to digest the zona"},{"id":"b","text":"Sperm binds to the oocyte membrane"},{"id":"c","text":"Sperm undergoes capacitation"},{"id":"d","text":"Oocyte completes meiosis"}],"answerId":"a","explanation":"The acrosomal reaction involves the release of enzymes from the sperm that help it penetrate the zona pellucida.","kind":"mechanism","origin":"ai"},{"id":"capacitation-fertilization~ai-5","moduleId":"capacitation-fertilization","stem":"How does fertilization relate to the development of the bilaminar disc?","options":[{"id":"a","text":"It initiates cleavage stages"},{"id":"b","text":"It determines the sex of the embryo"},{"id":"c","text":"It triggers implantation"},{"id":"d","text":"It forms the placenta"}],"answerId":"a","explanation":"Fertilization initiates the cleavage stages that lead to the formation of the bilaminar disc in subsequent development.","kind":"integration","linkedModuleIds":["bilaminar-disc-week-two"],"origin":"ai"},{"id":"capacitation-fertilization~ai-6","moduleId":"capacitation-fertilization","stem":"What is the significance of the cortical reaction in preventing polyspermy?","options":[{"id":"a","text":"It digests the zona pellucida"},{"id":"b","text":"It modifies the zona pellucida"},{"id":"c","text":"It enhances sperm motility"},{"id":"d","text":"It triggers oocyte activation"}],"answerId":"b","explanation":"The cortical reaction modifies the zona pellucida after sperm fusion, preventing additional sperm from entering the oocyte.","kind":"trap","origin":"ai"},{"id":"capacitation-fertilization~ai-7","moduleId":"capacitation-fertilization","stem":"Which phase of fertilization involves the sperm penetrating the zona pellucida?","options":[{"id":"a","text":"Capacitation"},{"id":"b","text":"Acrosomal reaction"},{"id":"c","text":"Cortical reaction"},{"id":"d","text":"Oocyte activation"}],"answerId":"b","explanation":"The acrosomal reaction is the phase where sperm release enzymes to penetrate the zona pellucida.","kind":"mechanism","origin":"ai"},{"id":"capacitation-fertilization~ai-8","moduleId":"capacitation-fertilization","stem":"How does fertilization influence the outcomes of chromosomal sex determination?","options":[{"id":"a","text":"It restores diploid number"},{"id":"b","text":"It activates the zygote"},{"id":"c","text":"It mixes parental genomes"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"Fertilization restores the diploid chromosome number, determines chromosomal sex, and mixes parental genomes.","kind":"integration","linkedModuleIds":["preembryonic-clinical-applications"],"origin":"ai"}],"chromosome-copy-structure-abnormalities":[{"id":"chromosome-copy-structure-abnormalities~ai-0","moduleId":"chromosome-copy-structure-abnormalities","stem":"What is the primary consequence of a deletion in a chromosome?","options":[{"id":"a","text":"Increased gene dosage"},{"id":"b","text":"Loss of genetic material"},{"id":"c","text":"Formation of a ring chromosome"},{"id":"d","text":"Creation of an isochromosome"}],"answerId":"b","explanation":"A deletion results in the loss of genetic material, which can lead to partial monosomy.","kind":"recall","origin":"ai"},{"id":"chromosome-copy-structure-abnormalities~ai-1","moduleId":"chromosome-copy-structure-abnormalities","stem":"Which of the following describes an isochromosome?","options":[{"id":"a","text":"A chromosome with two centromeres"},{"id":"b","text":"A chromosome that has lost one arm and duplicated the other"},{"id":"c","text":"A circular chromosome with terminal deletions"},{"id":"d","text":"A chromosome with mirror-image arms"}],"answerId":"b","explanation":"An isochromosome is formed when one arm is lost and the other is duplicated, leading to partial trisomy and monosomy.","kind":"mechanism","origin":"ai"},{"id":"chromosome-copy-structure-abnormalities~ai-2","moduleId":"chromosome-copy-structure-abnormalities","stem":"Which clinical finding is associated with a deletion on chromosome 5p?","options":[{"id":"a","text":"Mirror-image chromosome arms"},{"id":"b","text":"Cri-du-chat syndrome"},{"id":"c","text":"Ring chromosome formation"},{"id":"d","text":"Acentric fragment loss"}],"answerId":"b","explanation":"Terminal loss from 5p is characteristic of cri-du-chat syndrome, which results from a deletion.","kind":"recall","origin":"ai"},{"id":"chromosome-copy-structure-abnormalities~ai-3","moduleId":"chromosome-copy-structure-abnormalities","stem":"What is a key characteristic of a dicentric chromosome?","options":[{"id":"a","text":"It has two centromeres"},{"id":"b","text":"It has no centromere"},{"id":"c","text":"It is always stable"},{"id":"d","text":"It is a type of isochromosome"}],"answerId":"a","explanation":"A dicentric chromosome contains two centromeres and is mechanically unstable, often leading to problems during cell division.","kind":"trap","origin":"ai"},{"id":"chromosome-copy-structure-abnormalities~ai-4","moduleId":"chromosome-copy-structure-abnormalities","stem":"How does a ring chromosome typically form?","options":[{"id":"a","text":"By duplication of both ends"},{"id":"b","text":"By fusion of broken ends after terminal deletions"},{"id":"c","text":"By isochromosome formation"},{"id":"d","text":"By centromere division"}],"answerId":"b","explanation":"A ring chromosome forms when both ends of a chromosome break and the remaining ends fuse, often after terminal deletions.","kind":"recall","origin":"ai"},{"id":"chromosome-copy-structure-abnormalities~ai-5","moduleId":"chromosome-copy-structure-abnormalities","stem":"In patients with gastric carcinoma, which chromosomal abnormality might be observed?","options":[{"id":"a","text":"Aneuploidy"},{"id":"b","text":"Isochromosome formation"},{"id":"c","text":"Ring chromosomes"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"Gastric carcinoma can be associated with various chromosomal abnormalities, including aneuploidy, isochromosomes, and ring chromosomes.","kind":"integration","linkedModuleIds":["gastric-carcinoma-lymphoma"],"origin":"ai"},{"id":"chromosome-copy-structure-abnormalities~ai-6","moduleId":"chromosome-copy-structure-abnormalities","stem":"Which chromosomal abnormality is likely to affect gene dosage in gastric MALT lymphoma?","options":[{"id":"a","text":"Deletion"},{"id":"b","text":"Duplication"},{"id":"c","text":"Isochromosome"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"All these abnormalities can alter gene dosage, which is relevant in the context of gastric MALT lymphoma.","kind":"integration","linkedModuleIds":["gastric-carcinoma-lymphoma"],"origin":"ai"}],"karyotype-chromosome-analysis":[{"id":"karyotype-chromosome-analysis~ai-0","moduleId":"karyotype-chromosome-analysis","stem":"What is the primary purpose of performing a karyotype analysis?","options":[{"id":"a","text":"To identify single nucleotide polymorphisms"},{"id":"b","text":"To detect chromosomal abnormalities"},{"id":"c","text":"To assess gene expression levels"},{"id":"d","text":"To evaluate protein function"}],"answerId":"b","explanation":"Karyotype analysis is primarily used to detect chromosomal abnormalities that may be associated with various genetic disorders.","kind":"recall","origin":"ai"},{"id":"karyotype-chromosome-analysis~ai-1","moduleId":"karyotype-chromosome-analysis","stem":"Which of the following is a characteristic of G-banding in karyotype analysis?","options":[{"id":"a","text":"It produces a fluorescent pattern"},{"id":"b","text":"It highlights GC-rich regions"},{"id":"c","text":"It uses trypsin and Giemsa staining"},{"id":"d","text":"It is used for prenatal specimens only"}],"answerId":"c","explanation":"G-banding utilizes trypsin and Giemsa staining to produce a distinct banding pattern on chromosomes.","kind":"mechanism","origin":"ai"},{"id":"karyotype-chromosome-analysis~ai-2","moduleId":"karyotype-chromosome-analysis","stem":"A karyotype shows 46,XY. What does this indicate?","options":[{"id":"a","text":"Normal female chromosome count"},{"id":"b","text":"Normal male chromosome count"},{"id":"c","text":"Presence of a chromosomal abnormality"},{"id":"d","text":"Indeterminate sex chromosome status"}],"answerId":"b","explanation":"The notation 46,XY indicates a normal male chromosome count and sex-chromosome complement.","kind":"recall","origin":"ai"},{"id":"karyotype-chromosome-analysis~ai-3","moduleId":"karyotype-chromosome-analysis","stem":"What is a limitation of a normal karyotype result?","options":[{"id":"a","text":"It confirms the absence of all genetic disorders"},{"id":"b","text":"It can miss small copy-number changes"},{"id":"c","text":"It only detects large chromosomal deletions"},{"id":"d","text":"It is not useful for prenatal diagnosis"}],"answerId":"b","explanation":"A normal karyotype can miss small copy-number changes and sequence variants that are below its resolution.","kind":"trap","origin":"ai"},{"id":"karyotype-chromosome-analysis~ai-4","moduleId":"karyotype-chromosome-analysis","stem":"Which specimen type is NOT typically used for postnatal karyotyping?","options":[{"id":"a","text":"Peripheral-blood lymphocytes"},{"id":"b","text":"Skin fibroblasts"},{"id":"c","text":"Amniocytes"},{"id":"d","text":"Tumor tissue"}],"answerId":"c","explanation":"Amniocytes are typically used for prenatal karyotyping, not postnatal.","kind":"recall","origin":"ai"},{"id":"karyotype-chromosome-analysis~ai-5","moduleId":"karyotype-chromosome-analysis","stem":"How does karyotype analysis relate to mammary development and lactogenesis?","options":[{"id":"a","text":"It helps identify hormonal influences on lactation"},{"id":"b","text":"It assesses genetic factors affecting breast cancer risk"},{"id":"c","text":"It determines chromosomal abnormalities in lactation disorders"},{"id":"d","text":"It evaluates genetic predisposition to mammary gland development"}],"answerId":"d","explanation":"Karyotype analysis can evaluate genetic predisposition to mammary gland development, which is relevant in the context of lactogenesis.","kind":"integration","linkedModuleIds":["hrp1-mammary-development-lactogenesis"],"origin":"ai"},{"id":"karyotype-chromosome-analysis~ai-6","moduleId":"karyotype-chromosome-analysis","stem":"What chromosomal feature is assessed in both karyotype analysis and chromosome structure studies?","options":[{"id":"a","text":"Gene expression levels"},{"id":"b","text":"Chromosome number"},{"id":"c","text":"Protein synthesis"},{"id":"d","text":"Cell cycle phases"}],"answerId":"b","explanation":"Both karyotype analysis and chromosome structure studies assess chromosome number, which is crucial for understanding genetic stability.","kind":"integration","linkedModuleIds":["chromosome-structure-chromatin"],"origin":"ai"}],"numerical-chromosome-abnormalities":[{"id":"numerical-chromosome-abnormalities~ai-0","moduleId":"numerical-chromosome-abnormalities","stem":"What is the chromosomal composition of a male with Down syndrome?","options":[{"id":"a","text":"47,XY,+21"},{"id":"b","text":"46,XY"},{"id":"c","text":"45,X"},{"id":"d","text":"47,XXY"}],"answerId":"a","explanation":"Down syndrome is characterized by trisomy 21, resulting in a total of 47 chromosomes with an extra chromosome 21.","kind":"recall","origin":"ai"},{"id":"numerical-chromosome-abnormalities~ai-1","moduleId":"numerical-chromosome-abnormalities","stem":"Which mechanism primarily leads to trisomy 21?","options":[{"id":"a","text":"Nondisjunction in meiosis I"},{"id":"b","text":"Nondisjunction in meiosis II"},{"id":"c","text":"Premature sister-chromatid separation"},{"id":"d","text":"Anaphase lag"}],"answerId":"a","explanation":"Nondisjunction in meiosis I results in gametes with an extra chromosome, leading to trisomy when fertilization occurs.","kind":"mechanism","origin":"ai"},{"id":"numerical-chromosome-abnormalities~ai-2","moduleId":"numerical-chromosome-abnormalities","stem":"A patient presents with a karyotype of 45,X. What condition is this indicative of?","options":[{"id":"a","text":"Down syndrome"},{"id":"b","text":"Turner syndrome"},{"id":"c","text":"Klinefelter syndrome"},{"id":"d","text":"Patau syndrome"}],"answerId":"b","explanation":"A karyotype of 45,X indicates Turner syndrome, which is characterized by monosomy X.","kind":"recall","origin":"ai"},{"id":"numerical-chromosome-abnormalities~ai-3","moduleId":"numerical-chromosome-abnormalities","stem":"Which of the following describes the outcome of meiosis II nondisjunction?","options":[{"id":"a","text":"Two disomic and two nullisomic gametes"},{"id":"b","text":"Two normal and one disomic and one nullisomic gamete"},{"id":"c","text":"All gametes are normal"},{"id":"d","text":"Four disomic gametes"}],"answerId":"b","explanation":"Meiosis II nondisjunction results in two normal gametes, one disomic, and one nullisomic.","kind":"mechanism","origin":"ai"},{"id":"numerical-chromosome-abnormalities~ai-4","moduleId":"numerical-chromosome-abnormalities","stem":"Which statement correctly differentiates meiosis I from meiosis II nondisjunction?","options":[{"id":"a","text":"Both errors produce the same four gametes"},{"id":"b","text":"Meiosis I affects homologs, while meiosis II affects sister chromatids"},{"id":"c","text":"Only meiosis I can lead to trisomy"},{"id":"d","text":"Meiosis II always results in normal gametes"}],"answerId":"b","explanation":"Meiosis I nondisjunction affects homolog segregation, while meiosis II affects only one pair of sister chromatids.","kind":"trap","origin":"ai"},{"id":"numerical-chromosome-abnormalities~ai-5","moduleId":"numerical-chromosome-abnormalities","stem":"What is the chromosomal composition of a triploid individual?","options":[{"id":"a","text":"46 chromosomes"},{"id":"b","text":"47 chromosomes"},{"id":"c","text":"69 chromosomes"},{"id":"d","text":"92 chromosomes"}],"answerId":"c","explanation":"Triploidy is characterized by having three complete sets of chromosomes, totaling 69 chromosomes.","kind":"recall","origin":"ai"},{"id":"numerical-chromosome-abnormalities~ai-6","moduleId":"numerical-chromosome-abnormalities","stem":"How does mosaicism relate to aneuploidy?","options":[{"id":"a","text":"It is a form of polyploidy"},{"id":"b","text":"It results from postzygotic mitotic errors"},{"id":"c","text":"It is always associated with Turner syndrome"},{"id":"d","text":"It only occurs in males"}],"answerId":"b","explanation":"Mosaicism arises from postzygotic mitotic errors, leading to a mixture of normal and aneuploid cells.","kind":"integration","linkedModuleIds":["mosaicism-chimerism"],"origin":"ai"},{"id":"numerical-chromosome-abnormalities~ai-7","moduleId":"numerical-chromosome-abnormalities","stem":"Which condition is most likely to be associated with a partial molar placenta?","options":[{"id":"a","text":"Down syndrome"},{"id":"b","text":"Triploidy"},{"id":"c","text":"Turner syndrome"},{"id":"d","text":"Klinefelter syndrome"}],"answerId":"b","explanation":"Triploidy, often resulting from dispermy, is associated with the presence of a partial molar placenta.","kind":"integration","linkedModuleIds":["autosomal-trisomies"],"origin":"ai"}],"extraembryonic-membranes-cord":[{"id":"extraembryonic-membranes-cord~ai-0","moduleId":"extraembryonic-membranes-cord","stem":"What is the normal composition of a mature umbilical cord?","options":[{"id":"a","text":"One umbilical artery and one umbilical vein"},{"id":"b","text":"Two umbilical arteries and one umbilical vein"},{"id":"c","text":"Three umbilical arteries"},{"id":"d","text":"Two umbilical veins and one umbilical artery"}],"answerId":"b","explanation":"A mature umbilical cord typically contains two umbilical arteries and one umbilical vein, which are embedded in Wharton jelly.","kind":"recall","origin":"ai"},{"id":"extraembryonic-membranes-cord~ai-1","moduleId":"extraembryonic-membranes-cord","stem":"What is the primary function of amniotic fluid?","options":[{"id":"a","text":"Nutrient transport to the fetus"},{"id":"b","text":"Cushioning and protecting the fetus"},{"id":"c","text":"Facilitating gas exchange"},{"id":"d","text":"Providing structural support to the placenta"}],"answerId":"b","explanation":"Amniotic fluid cushions the fetus, allows for movement, and helps maintain temperature control.","kind":"recall","origin":"ai"},{"id":"extraembryonic-membranes-cord~ai-2","moduleId":"extraembryonic-membranes-cord","stem":"Which structure is responsible for early blood formation and bladder development?","options":[{"id":"a","text":"Yolk sac"},{"id":"b","text":"Amnion"},{"id":"c","text":"Allantois"},{"id":"d","text":"Umbilical cord"}],"answerId":"c","explanation":"The allantois contributes to early blood formation and bladder development, eventually becoming the urachus.","kind":"recall","origin":"ai"},{"id":"extraembryonic-membranes-cord~ai-3","moduleId":"extraembryonic-membranes-cord","stem":"A newborn presents with urine draining from the umbilicus. What is the likely diagnosis?","options":[{"id":"a","text":"Patent urachus"},{"id":"b","text":"Meckel diverticulum"},{"id":"c","text":"Umbilical hernia"},{"id":"d","text":"Omphalocele"}],"answerId":"a","explanation":"Urine draining from the umbilicus indicates a patent urachus, a condition where the allantois fails to close properly.","kind":"clinical","origin":"ai"},{"id":"extraembryonic-membranes-cord~ai-4","moduleId":"extraembryonic-membranes-cord","stem":"Which statement correctly describes umbilical vessel function?","options":[{"id":"a","text":"Umbilical arteries carry oxygenated blood"},{"id":"b","text":"Umbilical vein carries deoxygenated blood"},{"id":"c","text":"Umbilical arteries carry deoxygenated blood"},{"id":"d","text":"Umbilical vein carries oxygenated blood to the fetus"}],"answerId":"c","explanation":"Umbilical arteries carry deoxygenated blood from the fetus to the placenta, while the umbilical vein returns oxygenated blood to the fetus.","kind":"trap","origin":"ai"},{"id":"extraembryonic-membranes-cord~ai-5","moduleId":"extraembryonic-membranes-cord","stem":"How does the yolk sac contribute to fetal development?","options":[{"id":"a","text":"Forms the placenta"},{"id":"b","text":"Produces amniotic fluid"},{"id":"c","text":"Gives rise to primordial germ cells"},{"id":"d","text":"Develops into the umbilical cord"}],"answerId":"c","explanation":"The yolk sac contributes to early blood vessels and primordial germ cells, and is incorporated into the primitive gut.","kind":"recall","origin":"ai"},{"id":"extraembryonic-membranes-cord~ai-6","moduleId":"extraembryonic-membranes-cord","stem":"How does the development of the umbilical cord relate to the process of embryonic folding?","options":[{"id":"a","text":"It forms the placenta"},{"id":"b","text":"It carries nutrients to the fetus"},{"id":"c","text":"It encases the connecting stalk"},{"id":"d","text":"It produces amniotic fluid"}],"answerId":"c","explanation":"Embryonic folding carries the amnion around the connecting stalk, forming the outer covering of the umbilical cord.","kind":"integration","linkedModuleIds":["placenta-development-circulation"],"origin":"ai"},{"id":"extraembryonic-membranes-cord~ai-7","moduleId":"extraembryonic-membranes-cord","stem":"What is the clinical significance of a persistent vitelline duct?","options":[{"id":"a","text":"It leads to a patent urachus"},{"id":"b","text":"It can result in Meckel diverticulum"},{"id":"c","text":"It causes umbilical hernia"},{"id":"d","text":"It affects placental attachment"}],"answerId":"b","explanation":"A persistent vitelline duct can result in Meckel diverticulum, which is an ileal diverticulum at the antimesenteric border.","kind":"integration","linkedModuleIds":["placenta-clinical-abnormalities"],"origin":"ai"}],"meiosis-recombination":[{"id":"meiosis-recombination~ai-0","moduleId":"meiosis-recombination","stem":"What is the primary event occurring during pachytene of prophase I in meiosis?","options":[{"id":"a","text":"Homologous chromosomes separate"},{"id":"b","text":"Crossing over occurs"},{"id":"c","text":"Chiasmata become visible"},{"id":"d","text":"Sister chromatids disjoin"}],"answerId":"b","explanation":"Pachytene is characterized by the occurrence of crossing over between homologous chromosomes.","kind":"recall","origin":"ai"},{"id":"meiosis-recombination~ai-1","moduleId":"meiosis-recombination","stem":"Which of the following statements is true regarding meiosis I?","options":[{"id":"a","text":"Sister chromatids separate at anaphase I"},{"id":"b","text":"Homologous chromosomes separate at anaphase I"},{"id":"c","text":"Centromeres split during anaphase I"},{"id":"d","text":"Meiosis I produces diploid cells"}],"answerId":"b","explanation":"In meiosis I, homologous chromosomes separate, while sister chromatids remain joined until meiosis II.","kind":"trap","origin":"ai"},{"id":"meiosis-recombination~ai-2","moduleId":"meiosis-recombination","stem":"During which stage of meiosis are chiasmata visible?","options":[{"id":"a","text":"Leptotene"},{"id":"b","text":"Zygotene"},{"id":"c","text":"Pachytene"},{"id":"d","text":"Diplotene"}],"answerId":"d","explanation":"Chiasmata become visible during the diplotene stage after crossing over has occurred.","kind":"recall","origin":"ai"},{"id":"meiosis-recombination~ai-3","moduleId":"meiosis-recombination","stem":"What is the result of abnormal recombination involving the SRY gene?","options":[{"id":"a","text":"46,XX male"},{"id":"b","text":"46,XY female"},{"id":"c","text":"Turner syndrome"},{"id":"d","text":"Klinefelter syndrome"}],"answerId":"a","explanation":"Abnormal recombination can lead to an SRY-positive 46,XX male due to translocation of the SRY gene.","kind":"mechanism","origin":"ai"},{"id":"meiosis-recombination~ai-4","moduleId":"meiosis-recombination","stem":"What is the main purpose of meiosis II?","options":[{"id":"a","text":"To separate homologous chromosomes"},{"id":"b","text":"To separate sister chromatids"},{"id":"c","text":"To reduce chromosome number"},{"id":"d","text":"To facilitate crossing over"}],"answerId":"b","explanation":"Meiosis II is primarily focused on separating sister chromatids without further reduction of chromosome number.","kind":"recall","origin":"ai"},{"id":"meiosis-recombination~ai-5","moduleId":"meiosis-recombination","stem":"How does meiosis contribute to genetic diversity?","options":[{"id":"a","text":"By producing identical daughter cells"},{"id":"b","text":"Through independent assortment and crossing over"},{"id":"c","text":"By duplicating chromosomes"},{"id":"d","text":"By reducing chromosome number only"}],"answerId":"b","explanation":"Meiosis increases genetic diversity through independent assortment of chromosomes and crossing over during prophase I.","kind":"mechanism","origin":"ai"},{"id":"meiosis-recombination~ai-6","moduleId":"meiosis-recombination","stem":"How does the process of meiosis relate to drug dosing in patients with kidney disease?","options":[{"id":"a","text":"Meiosis affects drug metabolism"},{"id":"b","text":"Drug dosing does not relate to meiosis"},{"id":"c","text":"Meiosis impacts renal clearance"},{"id":"d","text":"Genetic variations from meiosis can affect drug response"}],"answerId":"d","explanation":"Genetic variations resulting from meiosis can influence individual responses to medications, particularly in conditions like kidney disease.","kind":"integration","linkedModuleIds":["drug-dosing-ckd"],"origin":"ai"},{"id":"meiosis-recombination~ai-7","moduleId":"meiosis-recombination","stem":"Which aspect of chromosome structure is most relevant to understanding meiosis?","options":[{"id":"a","text":"Chromatin condensation"},{"id":"b","text":"Sister chromatid cohesion"},{"id":"c","text":"Histone modification"},{"id":"d","text":"Telomere length"}],"answerId":"b","explanation":"Sister chromatid cohesion is crucial for the proper separation of chromatids during meiosis, particularly in anaphase II.","kind":"integration","linkedModuleIds":["chromosome-structure-chromatin"],"origin":"ai"}],"mitosis-cell-cycle-checkpoints":[{"id":"mitosis-cell-cycle-checkpoints~ai-0","moduleId":"mitosis-cell-cycle-checkpoints","stem":"What is the correct order of phases in the somatic cell cycle?","options":[{"id":"a","text":"G1 -> S -> G2 -> M"},{"id":"b","text":"S -> G1 -> M -> G2"},{"id":"c","text":"M -> G2 -> S -> G1"},{"id":"d","text":"G2 -> M -> S -> G1"}],"answerId":"a","explanation":"The somatic cell cycle progresses through G1, S, G2, and M phases in that specific order.","kind":"recall","origin":"ai"},{"id":"mitosis-cell-cycle-checkpoints~ai-1","moduleId":"mitosis-cell-cycle-checkpoints","stem":"Which checkpoint ensures that DNA replication is complete before mitosis begins?","options":[{"id":"a","text":"G1/S checkpoint"},{"id":"b","text":"G2/M checkpoint"},{"id":"c","text":"Spindle checkpoint"},{"id":"d","text":"Metaphase checkpoint"}],"answerId":"b","explanation":"The G2/M checkpoint verifies that DNA replication is complete and intact before the cell enters mitosis.","kind":"recall","origin":"ai"},{"id":"mitosis-cell-cycle-checkpoints~ai-2","moduleId":"mitosis-cell-cycle-checkpoints","stem":"What occurs during anaphase of mitosis?","options":[{"id":"a","text":"Chromosomes align at the equatorial plate"},{"id":"b","text":"Sister chromatids move to opposite poles"},{"id":"c","text":"DNA replication occurs"},{"id":"d","text":"Cytokinesis begins"}],"answerId":"b","explanation":"During anaphase, sister chromatids separate and move to opposite poles of the cell.","kind":"recall","origin":"ai"},{"id":"mitosis-cell-cycle-checkpoints~ai-3","moduleId":"mitosis-cell-cycle-checkpoints","stem":"Which statement correctly describes the spindle checkpoint?","options":[{"id":"a","text":"Anaphase begins as soon as one chromosome attaches to spindle fibers"},{"id":"b","text":"All chromosomes must be correctly attached before sister-chromatid separation"},{"id":"c","text":"Chromosomes align at the equatorial plate"},{"id":"d","text":"Sister chromatids are replicated during this phase"}],"answerId":"b","explanation":"The spindle checkpoint ensures that all chromosomes are correctly attached to spindle fibers before allowing anaphase to proceed.","kind":"trap","origin":"ai"},{"id":"mitosis-cell-cycle-checkpoints~ai-4","moduleId":"mitosis-cell-cycle-checkpoints","stem":"What is the primary role of cyclins and cyclin-dependent kinases in the cell cycle?","options":[{"id":"a","text":"To initiate DNA replication"},{"id":"b","text":"To drive phase transitions"},{"id":"c","text":"To promote apoptosis"},{"id":"d","text":"To repair DNA damage"}],"answerId":"b","explanation":"Cyclins and cyclin-dependent kinases are crucial for regulating and driving transitions between different phases of the cell cycle.","kind":"recall","origin":"ai"},{"id":"mitosis-cell-cycle-checkpoints~ai-5","moduleId":"mitosis-cell-cycle-checkpoints","stem":"How does the G1/S checkpoint contribute to genomic integrity?","options":[{"id":"a","text":"It checks for DNA damage before replication"},{"id":"b","text":"It ensures proper chromosome alignment"},{"id":"c","text":"It prevents cytokinesis from occurring"},{"id":"d","text":"It initiates DNA repair mechanisms"}],"answerId":"a","explanation":"The G1/S checkpoint assesses DNA integrity and ensures that cells do not proceed to DNA replication if damage is present.","kind":"mechanism","origin":"ai"},{"id":"mitosis-cell-cycle-checkpoints~ai-6","moduleId":"mitosis-cell-cycle-checkpoints","stem":"How might the cell cycle checkpoints relate to targeted cancer therapy (linkedModuleIds: [\"targeted-cancer-therapy\"])?","options":[{"id":"a","text":"Targeted therapies enhance checkpoint function"},{"id":"b","text":"Cancer cells often bypass checkpoints, leading to therapy resistance"},{"id":"c","text":"Checkpoints are not relevant to targeted therapies"},{"id":"d","text":"Targeted therapies only affect the M phase"}],"answerId":"b","explanation":"Cancer cells frequently bypass cell cycle checkpoints, which can contribute to their resistance to targeted therapies.","kind":"integration","linkedModuleIds":["targeted-cancer-therapy"],"origin":"ai"},{"id":"mitosis-cell-cycle-checkpoints~ai-7","moduleId":"mitosis-cell-cycle-checkpoints","stem":"What is a potential consequence of failing the G2/M checkpoint in relation to tumor immune evasion (linkedModuleIds: [\"tumor-evasion-immunotherapy\"])?","options":[{"id":"a","text":"Increased apoptosis of tumor cells"},{"id":"b","text":"Increased mutation rates leading to immune evasion"},{"id":"c","text":"Enhanced immune response against the tumor"},{"id":"d","text":"Decreased tumor growth"}],"answerId":"b","explanation":"Failure of the G2/M checkpoint can lead to increased mutation rates, which may enhance the tumor's ability to evade the immune system.","kind":"integration","linkedModuleIds":["tumor-evasion-immunotherapy"],"origin":"ai"}],"mosaicism-chimerism":[{"id":"mosaicism-chimerism~ai-0","moduleId":"mosaicism-chimerism","stem":"What is the primary distinction between mosaicism and chimerism?","options":[{"id":"a","text":"Mosaicism arises from one fertilization event, while chimerism involves multiple events."},{"id":"b","text":"Mosaicism is always associated with Turner syndrome, while chimerism is not."},{"id":"c","text":"Mosaicism results in a single phenotype, while chimerism results in multiple phenotypes."},{"id":"d","text":"Mosaicism only affects somatic cells, while chimerism affects germ cells."}],"answerId":"a","explanation":"Mosaicism involves genetically different cell lines from a single zygote, whereas chimerism involves lines from multiple zygotes.","kind":"recall","origin":"ai"},{"id":"mosaicism-chimerism~ai-1","moduleId":"mosaicism-chimerism","stem":"In a patient presenting with 45,X/46,XX cell lines, what is the most likely underlying mechanism?","options":[{"id":"a","text":"Tetragametic chimerism"},{"id":"b","text":"Postzygotic mitotic nondisjunction"},{"id":"c","text":"Anaphase lag during meiosis"},{"id":"d","text":"Confined placental mosaicism"}],"answerId":"b","explanation":"The presence of two different cell lines in one individual suggests a postzygotic error leading to mosaicism.","kind":"mechanism","origin":"ai"},{"id":"mosaicism-chimerism~ai-2","moduleId":"mosaicism-chimerism","stem":"Which of the following findings would suggest confined placental mosaicism?","options":[{"id":"a","text":"Abnormal chorionic villus sampling but normal amniocytes"},{"id":"b","text":"Mosaic Turner pattern in blood cells"},{"id":"c","text":"Tetragametic chimerism in skin biopsy"},{"id":"d","text":"Normal karyotype in both placenta and fetus"}],"answerId":"a","explanation":"Confined placental mosaicism results in discrepancies between placental and fetal cell lines.","kind":"clinical","origin":"ai"},{"id":"mosaicism-chimerism~ai-3","moduleId":"mosaicism-chimerism","stem":"A patient has two genetically distinct cell lines, one from a fertilization event and another from a different embryo. This condition is best described as:","options":[{"id":"a","text":"Mosaicism"},{"id":"b","text":"Chimerism"},{"id":"c","text":"Aneuploidy"},{"id":"d","text":"Polyploidy"}],"answerId":"b","explanation":"Chimerism involves genetically distinct lines from separate fertilization events.","kind":"recall","origin":"ai"},{"id":"mosaicism-chimerism~ai-4","moduleId":"mosaicism-chimerism","stem":"Which of the following statements about mosaicism is FALSE?","options":[{"id":"a","text":"It can arise from anaphase lag."},{"id":"b","text":"It can involve multiple tissues if the error occurs early."},{"id":"c","text":"It always results in a phenotypically normal individual."},{"id":"d","text":"It can be detected by specific karyotyping techniques."}],"answerId":"c","explanation":"Mosaicism can lead to phenotypic abnormalities depending on the affected tissues.","kind":"trap","origin":"ai"},{"id":"mosaicism-chimerism~ai-5","moduleId":"mosaicism-chimerism","stem":"How does mosaicism relate to aneuploidy in terms of genetic origin?","options":[{"id":"a","text":"Both arise from multiple fertilization events."},{"id":"b","text":"Mosaicism can result from aneuploidy occurring postzygotically."},{"id":"c","text":"Aneuploidy is always a result of mosaicism."},{"id":"d","text":"Mosaicism does not involve chromosomal abnormalities."}],"answerId":"b","explanation":"Mosaicism can arise from postzygotic errors leading to aneuploid cell lines.","kind":"integration","linkedModuleIds":["numerical-chromosome-abnormalities"],"origin":"ai"},{"id":"mosaicism-chimerism~ai-6","moduleId":"mosaicism-chimerism","stem":"A patient with chimerism presents with two distinct karyotypes. How is this condition related to chromosomal structure abnormalities?","options":[{"id":"a","text":"Chimerism is a type of chromosomal deletion."},{"id":"b","text":"Chimerism can involve structural abnormalities from each zygote."},{"id":"c","text":"Chimerism is unrelated to chromosomal abnormalities."},{"id":"d","text":"Chimerism always results in aneuploidy."}],"answerId":"b","explanation":"Chimerism can involve different chromosomal structures from each zygote, leading to distinct karyotypes.","kind":"integration","linkedModuleIds":["chromosome-copy-structure-abnormalities"],"origin":"ai"}],"placenta-clinical-abnormalities":[{"id":"placenta-clinical-abnormalities~ai-0","moduleId":"placenta-clinical-abnormalities","stem":"What is the most likely cause of painless late-pregnancy bleeding?","options":[{"id":"a","text":"Placenta accreta"},{"id":"b","text":"Placenta previa"},{"id":"c","text":"Placenta percreta"},{"id":"d","text":"Placental abruption"}],"answerId":"b","explanation":"Placenta previa is characterized by painless bleeding in the third trimester due to its location over the cervical os.","kind":"clinical","origin":"ai"},{"id":"placenta-clinical-abnormalities~ai-1","moduleId":"placenta-clinical-abnormalities","stem":"Which condition involves the placenta invading through the myometrium?","options":[{"id":"a","text":"Placenta accreta"},{"id":"b","text":"Placenta increta"},{"id":"c","text":"Placenta percreta"},{"id":"d","text":"Placenta previa"}],"answerId":"c","explanation":"Placenta percreta is defined by the invasion of the placenta through the myometrium to the serosa or adjacent organs.","kind":"recall","origin":"ai"},{"id":"placenta-clinical-abnormalities~ai-2","moduleId":"placenta-clinical-abnormalities","stem":"What is a common complication associated with velamentous cord insertion?","options":[{"id":"a","text":"Fetal growth restriction"},{"id":"b","text":"Painless bleeding"},{"id":"c","text":"Vasa previa"},{"id":"d","text":"Fetal vessel rupture"}],"answerId":"d","explanation":"Velamentous cord insertion can lead to fetal vessel rupture, which is a significant risk during labor.","kind":"clinical","origin":"ai"},{"id":"placenta-clinical-abnormalities~ai-3","moduleId":"placenta-clinical-abnormalities","stem":"Which of the following is true regarding non-invasive prenatal testing (NIPT)?","options":[{"id":"a","text":"It provides a definitive fetal karyotype"},{"id":"b","text":"It is a screening test requiring confirmation"},{"id":"c","text":"It is 100% accurate"},{"id":"d","text":"It can replace all other prenatal tests"}],"answerId":"b","explanation":"NIPT is a screening tool and should be confirmed with diagnostic tests when necessary.","kind":"trap","origin":"ai"},{"id":"placenta-clinical-abnormalities~ai-4","moduleId":"placenta-clinical-abnormalities","stem":"What abnormal placental shape is characterized by two lobes connected by a thin membrane?","options":[{"id":"a","text":"Circumvallate placenta"},{"id":"b","text":"Accessory lobe placenta"},{"id":"c","text":"Bilobed placenta"},{"id":"d","text":"Horseshoe placenta"}],"answerId":"c","explanation":"A bilobed placenta consists of two lobes that are connected, which can complicate pregnancy.","kind":"recall","origin":"ai"},{"id":"placenta-clinical-abnormalities~ai-5","moduleId":"placenta-clinical-abnormalities","stem":"How does oligohydramnios affect fetal development?","options":[{"id":"a","text":"Increases risk of congenital anomalies"},{"id":"b","text":"Promotes fetal growth"},{"id":"c","text":"Causes polyhydramnios"},{"id":"d","text":"Induces labor"}],"answerId":"a","explanation":"Oligohydramnios can lead to increased risk of congenital anomalies due to reduced amniotic fluid surrounding the fetus.","kind":"mechanism","origin":"ai"},{"id":"placenta-clinical-abnormalities~ai-6","moduleId":"placenta-clinical-abnormalities","stem":"How does the placenta facilitate maternal-fetal circulation?","options":[{"id":"a","text":"By direct blood transfer"},{"id":"b","text":"Through the placental barrier"},{"id":"c","text":"By secreting hormones"},{"id":"d","text":"By forming amniotic fluid"}],"answerId":"b","explanation":"The placental barrier allows for nutrient and gas exchange while preventing direct blood mixing between mother and fetus.","kind":"integration","linkedModuleIds":["hrp1-placenta-villi-barrier-circulation"],"origin":"ai"},{"id":"placenta-clinical-abnormalities~ai-7","moduleId":"placenta-clinical-abnormalities","stem":"What is the significance of a single umbilical artery in prenatal diagnosis?","options":[{"id":"a","text":"Indicates normal fetal development"},{"id":"b","text":"Associated with congenital anomalies"},{"id":"c","text":"Suggests placental insufficiency"},{"id":"d","text":"Confirms fetal well-being"}],"answerId":"b","explanation":"A single umbilical artery is associated with an increased risk of congenital anomalies and should prompt further evaluation.","kind":"integration","linkedModuleIds":["hrp1-prenatal-care-risk-screening"],"origin":"ai"}],"translocations-inversions":[{"id":"translocations-inversions~ai-0","moduleId":"translocations-inversions","stem":"What is the primary risk associated with a balanced reciprocal translocation during meiosis?","options":[{"id":"a","text":"Formation of unbalanced gametes"},{"id":"b","text":"Increased chromosome number"},{"id":"c","text":"Development of cancer"},{"id":"d","text":"Reduced fertility"}],"answerId":"a","explanation":"Balanced reciprocal translocation carriers can produce unbalanced gametes due to improper segregation during meiosis.","kind":"mechanism","origin":"ai"},{"id":"translocations-inversions~ai-1","moduleId":"translocations-inversions","stem":"Which of the following is a characteristic of a balanced Robertsonian translocation?","options":[{"id":"a","text":"Presence of 46 chromosomes"},{"id":"b","text":"Loss of short arms of acrocentric chromosomes"},{"id":"c","text":"Increased risk of Down syndrome in all offspring"},{"id":"d","text":"Phenotypically abnormal carrier"}],"answerId":"b","explanation":"A balanced Robertsonian translocation typically results in a carrier having 45 chromosomes with the loss of short arms but maintaining essential genetic material.","kind":"recall","origin":"ai"},{"id":"translocations-inversions~ai-2","moduleId":"translocations-inversions","stem":"A patient presents with recurrent miscarriages. Which genetic abnormality should be suspected?","options":[{"id":"a","text":"Balanced Robertsonian translocation"},{"id":"b","text":"Aneuploidy"},{"id":"c","text":"Pericentric inversion"},{"id":"d","text":"Monosomy"}],"answerId":"a","explanation":"Recurrent miscarriages can be indicative of a balanced translocation carrier producing unbalanced gametes.","kind":"clinical","origin":"ai"},{"id":"translocations-inversions~ai-3","moduleId":"translocations-inversions","stem":"In a pericentric inversion, which of the following statements is true?","options":[{"id":"a","text":"It excludes the centromere"},{"id":"b","text":"It includes the centromere"},{"id":"c","text":"It results in monosomy"},{"id":"d","text":"It is always unbalanced"}],"answerId":"b","explanation":"A pericentric inversion includes the centromere, which can lead to unbalanced gametes if crossover occurs within the inversion loop.","kind":"recall","origin":"ai"},{"id":"translocations-inversions~ai-4","moduleId":"translocations-inversions","stem":"What is the expected chromosome count in a balanced carrier of a Robertsonian translocation?","options":[{"id":"a","text":"46 chromosomes"},{"id":"b","text":"45 chromosomes"},{"id":"c","text":"47 chromosomes"},{"id":"d","text":"44 chromosomes"}],"answerId":"b","explanation":"A balanced carrier of a Robertsonian translocation typically has 45 chromosomes due to the fusion of two acrocentric chromosomes.","kind":"recall","origin":"ai"},{"id":"translocations-inversions~ai-5","moduleId":"translocations-inversions","stem":"How does a balanced Robertsonian translocation relate to aneuploidy?","options":[{"id":"a","text":"It increases the risk of aneuploidy in all offspring"},{"id":"b","text":"It is a form of aneuploidy"},{"id":"c","text":"It can produce unbalanced gametes leading to aneuploidy"},{"id":"d","text":"It prevents aneuploidy completely"}],"answerId":"c","explanation":"Balanced Robertsonian translocations can lead to unbalanced gametes, increasing the risk of aneuploidy in offspring.","kind":"integration","linkedModuleIds":["numerical-chromosome-abnormalities"],"origin":"ai"},{"id":"translocations-inversions~ai-6","moduleId":"translocations-inversions","stem":"What is a common clinical finding in patients with a pericentric inversion?","options":[{"id":"a","text":"Normal karyotype"},{"id":"b","text":"Increased risk of Down syndrome"},{"id":"c","text":"Recurrent miscarriages"},{"id":"d","text":"Balanced chromosome count"}],"answerId":"c","explanation":"Patients with a pericentric inversion may experience recurrent miscarriages due to the risk of producing unbalanced gametes.","kind":"integration","linkedModuleIds":["numerical-chromosome-abnormalities"],"origin":"ai"},{"id":"translocations-inversions~ai-7","moduleId":"translocations-inversions","stem":"Which of the following statements is a trap regarding balanced Robertsonian translocation carriers?","options":[{"id":"a","text":"They can have a normal phenotype"},{"id":"b","text":"They always have 46 chromosomes"},{"id":"c","text":"They are at high risk for severe phenotypes"},{"id":"d","text":"They cannot produce viable offspring"}],"answerId":"a","explanation":"Balanced Robertsonian translocation carriers can be phenotypically normal despite having 45 chromosomes.","kind":"trap","origin":"ai"}],"chromosome-structure-chromatin":[{"id":"chromosome-structure-chromatin~ai-0","moduleId":"chromosome-structure-chromatin","stem":"What is the basic unit of chromatin structure?","options":[{"id":"a","text":"Nucleosome"},{"id":"b","text":"Chromatid"},{"id":"c","text":"Chromosome"},{"id":"d","text":"Centromere"}],"answerId":"a","explanation":"The nucleosome is the fundamental unit of chromatin, consisting of DNA wrapped around histone proteins.","kind":"recall","origin":"ai"},{"id":"chromosome-structure-chromatin~ai-1","moduleId":"chromosome-structure-chromatin","stem":"Which type of chromatin is typically transcriptionally active?","options":[{"id":"a","text":"Heterochromatin"},{"id":"b","text":"Euchromatin"},{"id":"c","text":"Chromatid"},{"id":"d","text":"Centromeric DNA"}],"answerId":"b","explanation":"Euchromatin is less condensed and is associated with active transcription of genes.","kind":"recall","origin":"ai"},{"id":"chromosome-structure-chromatin~ai-2","moduleId":"chromosome-structure-chromatin","stem":"What occurs to the chromosome number after DNA replication?","options":[{"id":"a","text":"It doubles"},{"id":"b","text":"It halves"},{"id":"c","text":"It remains the same"},{"id":"d","text":"It becomes undetectable"}],"answerId":"c","explanation":"The chromosome number remains the same after DNA replication; the number of chromatids doubles.","kind":"trap","origin":"ai"},{"id":"chromosome-structure-chromatin~ai-3","moduleId":"chromosome-structure-chromatin","stem":"What structure forms when two identical DNA molecules are joined at a centromere?","options":[{"id":"a","text":"Chromosome"},{"id":"b","text":"Chromatid"},{"id":"c","text":"Nucleosome"},{"id":"d","text":"Telomere"}],"answerId":"b","explanation":"Two identical DNA molecules joined at a centromere are referred to as sister chromatids.","kind":"recall","origin":"ai"},{"id":"chromosome-structure-chromatin~ai-4","moduleId":"chromosome-structure-chromatin","stem":"Which of the following best describes the structure of a metaphase chromosome?","options":[{"id":"a","text":"Two sister chromatids joined at a centromere"},{"id":"b","text":"One continuous DNA strand"},{"id":"c","text":"A single nucleosome"},{"id":"d","text":"A 30-nm chromatin fiber"}],"answerId":"a","explanation":"A metaphase chromosome consists of two sister chromatids that are joined at the centromere.","kind":"recall","origin":"ai"},{"id":"chromosome-structure-chromatin~ai-5","moduleId":"chromosome-structure-chromatin","stem":"How does the structure of euchromatin differ from heterochromatin?","options":[{"id":"a","text":"Euchromatin is more condensed"},{"id":"b","text":"Heterochromatin is transcriptionally active"},{"id":"c","text":"Euchromatin is transcriptionally active"},{"id":"d","text":"Heterochromatin is less stable"}],"answerId":"c","explanation":"Euchromatin is less condensed and transcriptionally active, while heterochromatin is more condensed and inactive.","kind":"mechanism","origin":"ai"},{"id":"chromosome-structure-chromatin~ai-6","moduleId":"chromosome-structure-chromatin","stem":"Which chromatin structure is primarily involved in the formation of the karyotype?","options":[{"id":"a","text":"Nucleosome"},{"id":"b","text":"Euchromatin"},{"id":"c","text":"Metaphase chromosome"},{"id":"d","text":"Heterochromatin"}],"answerId":"c","explanation":"The karyotype is formed from metaphase chromosomes, which are highly condensed and visible during cell division.","kind":"integration","linkedModuleIds":["karyotype-chromosome-analysis"],"origin":"ai"},{"id":"chromosome-structure-chromatin~ai-7","moduleId":"chromosome-structure-chromatin","stem":"What is the primary function of histone H1 in chromatin?","options":[{"id":"a","text":"Stabilizes nucleosome structure"},{"id":"b","text":"Links adjacent nucleosomes"},{"id":"c","text":"Facilitates transcription"},{"id":"d","text":"Binds to centromeres"}],"answerId":"b","explanation":"Histone H1 binds to linker DNA between nucleosomes, helping to stabilize the overall structure of chromatin.","kind":"mechanism","origin":"ai"},{"id":"chromosome-structure-chromatin~ai-8","moduleId":"chromosome-structure-chromatin","stem":"Which of the following is a characteristic of the chromatin structure in the nucleus?","options":[{"id":"a","text":"All chromatin is transcriptionally inactive"},{"id":"b","text":"Nucleosomes are only found in heterochromatin"},{"id":"c","text":"Euchromatin is more accessible for transcription"},{"id":"d","text":"Chromatin is uniformly condensed"}],"answerId":"c","explanation":"Euchromatin is more accessible and transcriptionally active, while heterochromatin is more condensed and inactive.","kind":"integration","linkedModuleIds":["nucleus-chromatin-nucleolus"],"origin":"ai"}],"cytogenetic-nomenclature-basics":[{"id":"cytogenetic-nomenclature-basics~ai-0","moduleId":"cytogenetic-nomenclature-basics","stem":"What is the correct karyotype notation for a male with Down syndrome?","options":[{"id":"a","text":"46,XY,+21"},{"id":"b","text":"47,XY,+21"},{"id":"c","text":"47,XY,21+"},{"id":"d","text":"45,XY,+21"}],"answerId":"b","explanation":"The correct notation for a male with trisomy 21 is 47,XY,+21, where the + sign precedes the chromosome number.","kind":"recall","origin":"ai"},{"id":"cytogenetic-nomenclature-basics~ai-1","moduleId":"cytogenetic-nomenclature-basics","stem":"Which of the following correctly describes the structure of a karyotype?","options":[{"id":"a","text":"Sex chromosomes come after autosomes."},{"id":"b","text":"Numerical changes are written after structural changes."},{"id":"c","text":"The total chromosome number is written first."},{"id":"d","text":"Abnormalities are listed before sex chromosomes."}],"answerId":"c","explanation":"In a karyotype, the total chromosome number is always written first, followed by sex chromosomes and then abnormalities.","kind":"mechanism","origin":"ai"},{"id":"cytogenetic-nomenclature-basics~ai-2","moduleId":"cytogenetic-nomenclature-basics","stem":"A karyotype shows 45,X. What condition does this indicate?","options":[{"id":"a","text":"Klinefelter syndrome"},{"id":"b","text":"Down syndrome"},{"id":"c","text":"Turner syndrome"},{"id":"d","text":"Normal female"}],"answerId":"c","explanation":"The karyotype 45,X indicates Turner syndrome, characterized by monosomy X.","kind":"recall","origin":"ai"},{"id":"cytogenetic-nomenclature-basics~ai-3","moduleId":"cytogenetic-nomenclature-basics","stem":"In karyotype notation, what does the notation '47,XXY' represent?","options":[{"id":"a","text":"Normal male"},{"id":"b","text":"Klinefelter syndrome"},{"id":"c","text":"Turner syndrome"},{"id":"d","text":"Down syndrome"}],"answerId":"b","explanation":"'47,XXY' indicates Klinefelter syndrome, which is characterized by an extra X chromosome in males.","kind":"recall","origin":"ai"},{"id":"cytogenetic-nomenclature-basics~ai-4","moduleId":"cytogenetic-nomenclature-basics","stem":"Which of the following is a common trap in writing karyotypes?","options":[{"id":"a","text":"Placing the + sign after the chromosome number."},{"id":"b","text":"Using commas instead of semicolons."},{"id":"c","text":"Listing sex chromosomes after autosomes."},{"id":"d","text":"Omitting the total chromosome number."}],"answerId":"a","explanation":"A common mistake is placing the + sign after the chromosome number; it should precede the number for whole-chromosome changes.","kind":"trap","origin":"ai"},{"id":"cytogenetic-nomenclature-basics~ai-5","moduleId":"cytogenetic-nomenclature-basics","stem":"How would you denote a mosaic karyotype with 10 cells showing trisomy 21 and 5 normal cells?","options":[{"id":"a","text":"47,XX,+21[10]/46,XX[5]"},{"id":"b","text":"46,XX,+21[10]/45,XX[5]"},{"id":"c","text":"47,XX,+21;46,XX"},{"id":"d","text":"45,XX,+21[10]/46,XX[5]"}],"answerId":"a","explanation":"The correct notation for a mosaic karyotype is 47,XX,+21[10]/46,XX[5], indicating the proportion of each cell type.","kind":"recall","origin":"ai"},{"id":"cytogenetic-nomenclature-basics~ai-6","moduleId":"cytogenetic-nomenclature-basics","stem":"How does the ISCN karyotype notation relate to blood gas interpretation?","options":[{"id":"a","text":"Both use numerical values to indicate abnormalities."},{"id":"b","text":"Karyotypes can influence acid-base balance."},{"id":"c","text":"Karyotype notation does not relate to blood gas interpretation."},{"id":"d","text":"Both require understanding of cellular structures."}],"answerId":"a","explanation":"Both karyotype notation and blood gas interpretation involve numerical values that indicate specific abnormalities in the body.","kind":"integration","linkedModuleIds":["blood-gas-anion-gap"],"origin":"ai"},{"id":"cytogenetic-nomenclature-basics~ai-7","moduleId":"cytogenetic-nomenclature-basics","stem":"Which of the following karyotype notations would be relevant when discussing structural rearrangements?","options":[{"id":"a","text":"47,XY,+21"},{"id":"b","text":"45,X"},{"id":"c","text":"47,XY,inv(7)(p14q34)"},{"id":"d","text":"46,XX"}],"answerId":"c","explanation":"The notation 47,XY,inv(7)(p14q34) indicates a structural rearrangement involving chromosome 7.","kind":"integration","linkedModuleIds":["structural-rearrangement-nomenclature"],"origin":"ai"}],"structural-rearrangement-nomenclature":[{"id":"structural-rearrangement-nomenclature~ai-0","moduleId":"structural-rearrangement-nomenclature","stem":"What is the correct notation for a deletion on chromosome 4 at the short arm?","options":[{"id":"a","text":"46,XY,del(4)(p14)"},{"id":"b","text":"46,XY,del(4p)"},{"id":"c","text":"46,XY,del(4)(q14)"},{"id":"d","text":"46,XY,del(4)(p10)"}],"answerId":"a","explanation":"The notation 46,XY,del(4)(p14) specifies a deletion at the short arm of chromosome 4 at the 14 position.","kind":"recall","origin":"ai"},{"id":"structural-rearrangement-nomenclature~ai-1","moduleId":"structural-rearrangement-nomenclature","stem":"Which of the following describes a balanced Robertsonian translocation?","options":[{"id":"a","text":"46,XY,t(14;21)(q10;q10)"},{"id":"b","text":"45,XY,der(14;21)(q10;q10)"},{"id":"c","text":"46,XY,t(21;14)(q10;q10)"},{"id":"d","text":"45,XY,t(14;21)(q10;q10)"}],"answerId":"b","explanation":"A balanced Robertsonian translocation results in a chromosome count of 45 due to the fusion of two acrocentric chromosomes.","kind":"recall","origin":"ai"},{"id":"structural-rearrangement-nomenclature~ai-2","moduleId":"structural-rearrangement-nomenclature","stem":"What is the karyotype for a patient with an isochromosome of the X chromosome?","options":[{"id":"a","text":"46,X,i(X)(q10)"},{"id":"b","text":"45,X,i(X)(q10)"},{"id":"c","text":"46,XX,i(X)(p10)"},{"id":"d","text":"46,XY,i(X)(q10)"}],"answerId":"a","explanation":"The karyotype 46,X,i(X)(q10) indicates one normal X chromosome and an isochromosome of the long arm of X.","kind":"recall","origin":"ai"},{"id":"structural-rearrangement-nomenclature~ai-3","moduleId":"structural-rearrangement-nomenclature","stem":"In mosaic Turner syndrome, what is the karyotype representation?","options":[{"id":"a","text":"46,XX"},{"id":"b","text":"45,X"},{"id":"c","text":"mos 45,X[12]/46,XX[8]"},{"id":"d","text":"46,X,i(X)(q10)"}],"answerId":"c","explanation":"Mosaic Turner syndrome is represented as mos 45,X[12]/46,XX[8], indicating two cell lines with different chromosome counts.","kind":"recall","origin":"ai"},{"id":"structural-rearrangement-nomenclature~ai-4","moduleId":"structural-rearrangement-nomenclature","stem":"Which of the following is a common misconception about balanced Robertsonian translocation carriers?","options":[{"id":"a","text":"They have 46 chromosomes"},{"id":"b","text":"They are phenotypically normal"},{"id":"c","text":"They have a higher risk of Down syndrome"},{"id":"d","text":"They cannot have children"}],"answerId":"a","explanation":"A balanced Robertsonian translocation carrier has 45 chromosomes due to the fusion of two acrocentric chromosomes, despite being phenotypically normal.","kind":"trap","origin":"ai"},{"id":"structural-rearrangement-nomenclature~ai-5","moduleId":"structural-rearrangement-nomenclature","stem":"How does a deletion on chromosome 13 manifest in a karyotype?","options":[{"id":"a","text":"46,XY,del(13)(q12q14)"},{"id":"b","text":"46,XY,del(13)(p12)"},{"id":"c","text":"46,XY,del(13)(q14)"},{"id":"d","text":"45,XY,del(13)(q12q14)"}],"answerId":"a","explanation":"The notation 46,XY,del(13)(q12q14) indicates an interstitial deletion on chromosome 13 between the specified breakpoints.","kind":"recall","origin":"ai"},{"id":"structural-rearrangement-nomenclature~ai-6","moduleId":"structural-rearrangement-nomenclature","stem":"How does the structural rearrangement of chromosomes relate to metabolic disorders?","options":[{"id":"a","text":"They do not affect metabolism"},{"id":"b","text":"They can lead to insulin resistance"},{"id":"c","text":"They always cause obesity"},{"id":"d","text":"They only affect growth"}],"answerId":"b","explanation":"Structural rearrangements can disrupt genes involved in metabolic pathways, potentially leading to insulin resistance.","kind":"integration","linkedModuleIds":["hen1-insulin-signaling-fed-metabolism"],"origin":"ai"},{"id":"structural-rearrangement-nomenclature~ai-7","moduleId":"structural-rearrangement-nomenclature","stem":"What is the significance of understanding structural rearrangements in the context of clinical genetics?","options":[{"id":"a","text":"They are irrelevant to patient care"},{"id":"b","text":"They help predict treatment responses"},{"id":"c","text":"They only affect physical traits"},{"id":"d","text":"They are only important in prenatal diagnosis"}],"answerId":"b","explanation":"Understanding structural rearrangements can help predict treatment responses and guide management in various genetic conditions.","kind":"integration","linkedModuleIds":["hen1-insulin-signaling-fed-metabolism"],"origin":"ai"}],"fuel-nutrients-energy-balance":[{"id":"fuel-nutrients-energy-balance~ai-0","moduleId":"fuel-nutrients-energy-balance","stem":"Which macronutrient yields the highest energy per gram?","options":[{"id":"a","text":"Carbohydrate"},{"id":"b","text":"Protein"},{"id":"c","text":"Fat"},{"id":"d","text":"Alcohol"}],"answerId":"c","explanation":"Fat yields 9 kcal/g, making it the most energy-dense macronutrient.","kind":"recall","origin":"ai"},{"id":"fuel-nutrients-energy-balance~ai-1","moduleId":"fuel-nutrients-energy-balance","stem":"What is the primary role of dietary protein in the body?","options":[{"id":"a","text":"Energy source"},{"id":"b","text":"Amino acid supply for synthesis and repair"},{"id":"c","text":"Storage of energy"},{"id":"d","text":"Vitamin carrier"}],"answerId":"b","explanation":"Dietary protein primarily supplies amino acids necessary for synthesis and repair.","kind":"recall","origin":"ai"},{"id":"fuel-nutrients-energy-balance~ai-2","moduleId":"fuel-nutrients-energy-balance","stem":"What occurs during a negative nitrogen balance?","options":[{"id":"a","text":"Protein synthesis exceeds breakdown"},{"id":"b","text":"Protein breakdown exceeds synthesis"},{"id":"c","text":"Stable protein levels"},{"id":"d","text":"Increased fat storage"}],"answerId":"b","explanation":"A negative nitrogen balance indicates that protein breakdown exceeds protein synthesis.","kind":"mechanism","origin":"ai"},{"id":"fuel-nutrients-energy-balance~ai-3","moduleId":"fuel-nutrients-energy-balance","stem":"Which statement about energy density is correct?","options":[{"id":"a","text":"Protein gives more energy per gram than fat"},{"id":"b","text":"Fat is the most energy-dense macronutrient"},{"id":"c","text":"Carbohydrates yield more energy than protein"},{"id":"d","text":"Alcohol is the least energy-dense macronutrient"}],"answerId":"b","explanation":"Fat is the most energy-dense macronutrient, yielding 9 kcal/g.","kind":"trap","origin":"ai"},{"id":"fuel-nutrients-energy-balance~ai-4","moduleId":"fuel-nutrients-energy-balance","stem":"How does the body achieve energy balance?","options":[{"id":"a","text":"By increasing protein intake"},{"id":"b","text":"By matching energy intake with expenditure"},{"id":"c","text":"By decreasing carbohydrate intake"},{"id":"d","text":"By increasing fat storage"}],"answerId":"b","explanation":"Energy balance is achieved when energy intake equals energy expenditure.","kind":"clinical","origin":"ai"},{"id":"fuel-nutrients-energy-balance~ai-5","moduleId":"fuel-nutrients-energy-balance","stem":"Which monosaccharide is primarily absorbed in the intestine?","options":[{"id":"a","text":"Fructose"},{"id":"b","text":"Galactose"},{"id":"c","text":"Glucose"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"All of the listed monosaccharides are absorbed in the intestine.","kind":"integration","linkedModuleIds":["carbohydrate-digestion-absorption"],"origin":"ai"},{"id":"fuel-nutrients-energy-balance~ai-6","moduleId":"fuel-nutrients-energy-balance","stem":"What is the primary function of chylomicrons in lipid digestion?","options":[{"id":"a","text":"Transport of glucose"},{"id":"b","text":"Transport of fatty acids"},{"id":"c","text":"Transport of vitamins"},{"id":"d","text":"Transport of amino acids"}],"answerId":"b","explanation":"Chylomicrons primarily transport dietary fatty acids from the intestine to other tissues.","kind":"integration","linkedModuleIds":["lipid-digestion-chylomicrons"],"origin":"ai"}],"sex-chromosome-aneuploidies":[{"id":"sex-chromosome-aneuploidies~ai-0","moduleId":"sex-chromosome-aneuploidies","stem":"What is the most common cause of male hypogonadism?","options":[{"id":"a","text":"Turner syndrome (45,X)"},{"id":"b","text":"Klinefelter syndrome (47,XXY)"},{"id":"c","text":"Jacobs syndrome (47,XYY)"},{"id":"d","text":"Triple X syndrome (47,XXX)"}],"answerId":"b","explanation":"Klinefelter syndrome is the most common cause of male hypogonadism, characterized by tall stature and small firm testes.","kind":"recall","origin":"ai"},{"id":"sex-chromosome-aneuploidies~ai-1","moduleId":"sex-chromosome-aneuploidies","stem":"Which of the following is a characteristic finding in Turner syndrome?","options":[{"id":"a","text":"Tall stature"},{"id":"b","text":"Webbed neck"},{"id":"c","text":"Gynecomastia"},{"id":"d","text":"Azoospermia"}],"answerId":"b","explanation":"Webbed neck is a classic physical finding in Turner syndrome, while the other options are associated with different conditions.","kind":"recall","origin":"ai"},{"id":"sex-chromosome-aneuploidies~ai-2","moduleId":"sex-chromosome-aneuploidies","stem":"What is the mechanism leading to sex chromosome aneuploidies?","options":[{"id":"a","text":"Translocation"},{"id":"b","text":"Nondisjunction"},{"id":"c","text":"Deletion"},{"id":"d","text":"Inversion"}],"answerId":"b","explanation":"Nondisjunction during meiosis leads to sex chromosome aneuploidies such as Turner and Klinefelter syndromes.","kind":"mechanism","origin":"ai"},{"id":"sex-chromosome-aneuploidies~ai-3","moduleId":"sex-chromosome-aneuploidies","stem":"In Klinefelter syndrome, what is the expected laboratory finding for FSH and LH?","options":[{"id":"a","text":"Low FSH and LH"},{"id":"b","text":"Normal FSH and LH"},{"id":"c","text":"High FSH and low LH"},{"id":"d","text":"High FSH and LH"}],"answerId":"d","explanation":"Klinefelter syndrome results in primary hypogonadism, leading to elevated FSH and LH levels due to gonadal failure.","kind":"trap","origin":"ai"},{"id":"sex-chromosome-aneuploidies~ai-4","moduleId":"sex-chromosome-aneuploidies","stem":"A 15-year-old girl presents with short stature and primary amenorrhea. Which condition is most likely?","options":[{"id":"a","text":"Klinefelter syndrome"},{"id":"b","text":"Turner syndrome"},{"id":"c","text":"Jacobs syndrome"},{"id":"d","text":"Triple X syndrome"}],"answerId":"b","explanation":"Short stature and primary amenorrhea are classic features of Turner syndrome (45,X).","kind":"clinical","origin":"ai"},{"id":"sex-chromosome-aneuploidies~ai-5","moduleId":"sex-chromosome-aneuploidies","stem":"How does Turner syndrome relate to disorders of sex development?","options":[{"id":"a","text":"Both involve X-inactivation"},{"id":"b","text":"Both are caused by maternal age"},{"id":"c","text":"Both result in infertility"},{"id":"d","text":"Both are due to Y chromosome abnormalities"}],"answerId":"a","explanation":"Turner syndrome and disorders of sex development both involve mechanisms related to X-inactivation and sex chromosome abnormalities.","kind":"integration","linkedModuleIds":["dsd-fragile-x"],"origin":"ai"},{"id":"sex-chromosome-aneuploidies~ai-6","moduleId":"sex-chromosome-aneuploidies","stem":"Which of the following findings can indicate Klinefelter syndrome in a patient with suspected disorders of sex development?","options":[{"id":"a","text":"Presence of Barr bodies"},{"id":"b","text":"Short stature"},{"id":"c","text":"Cystic hygroma"},{"id":"d","text":"Primary amenorrhea"}],"answerId":"a","explanation":"The presence of Barr bodies is indicative of Klinefelter syndrome (47,XXY) and is a key finding in the evaluation of sex chromosome aneuploidies.","kind":"integration","linkedModuleIds":["x-inactivation-sex-determination"],"origin":"ai"}],"autosomal-deletion-syndromes":[{"id":"autosomal-deletion-syndromes~ai-0","moduleId":"autosomal-deletion-syndromes","stem":"What is the chromosomal deletion associated with Cri-du-chat syndrome?","options":[{"id":"a","text":"Deletion of the long arm of chromosome 5"},{"id":"b","text":"Deletion of the short arm of chromosome 5"},{"id":"c","text":"Deletion of the short arm of chromosome 4"},{"id":"d","text":"Deletion of the long arm of chromosome 4"}],"answerId":"b","explanation":"Cri-du-chat syndrome is caused by a deletion of the short arm of chromosome 5 (5p−).","kind":"recall","origin":"ai"},{"id":"autosomal-deletion-syndromes~ai-1","moduleId":"autosomal-deletion-syndromes","stem":"Which of the following features is characteristic of Wolf-Hirschhorn syndrome?","options":[{"id":"a","text":"High-pitched cat-like cry"},{"id":"b","text":"\"Greek warrior helmet\" facies"},{"id":"c","text":"Low-set ears"},{"id":"d","text":"Severe heart defects"}],"answerId":"b","explanation":"Wolf-Hirschhorn syndrome is characterized by the \"Greek warrior helmet\" facies and other features like microcephaly and growth retardation.","kind":"recall","origin":"ai"},{"id":"autosomal-deletion-syndromes~ai-2","moduleId":"autosomal-deletion-syndromes","stem":"What is the mechanism behind the symptoms of Cri-du-chat syndrome?","options":[{"id":"a","text":"Loss of a short-arm segment"},{"id":"b","text":"Gain of function mutation"},{"id":"c","text":"Increased gene dosage"},{"id":"d","text":"Translocation of chromosome segments"}],"answerId":"a","explanation":"The symptoms of Cri-du-chat syndrome arise from the loss of a short-arm segment of chromosome 5, leading to a contiguous-gene syndrome.","kind":"mechanism","origin":"ai"},{"id":"autosomal-deletion-syndromes~ai-3","moduleId":"autosomal-deletion-syndromes","stem":"A child presents with a high-pitched cry, microcephaly, and hypertelorism. Which condition is most likely?","options":[{"id":"a","text":"Wolf-Hirschhorn syndrome"},{"id":"b","text":"Cri-du-chat syndrome"},{"id":"c","text":"Down syndrome"},{"id":"d","text":"Turner syndrome"}],"answerId":"b","explanation":"These features are classic for Cri-du-chat syndrome, which includes a high-pitched cry and distinct facial features.","kind":"clinical","origin":"ai"},{"id":"autosomal-deletion-syndromes~ai-4","moduleId":"autosomal-deletion-syndromes","stem":"In a family with a history of Wolf-Hirschhorn syndrome, what genetic factor should be considered for recurrence risk?","options":[{"id":"a","text":"Balanced translocation in the mother"},{"id":"b","text":"Unbalanced translocation in the father"},{"id":"c","text":"Single nucleotide mutation"},{"id":"d","text":"Autosomal dominant inheritance"}],"answerId":"a","explanation":"Approximately 45-50% of Wolf-Hirschhorn cases arise from an unbalanced translocation, so parental karyotyping is important for counseling.","kind":"trap","origin":"ai"},{"id":"autosomal-deletion-syndromes~ai-5","moduleId":"autosomal-deletion-syndromes","stem":"How does Cri-du-chat syndrome relate to gas exchange abnormalities in infants?","options":[{"id":"a","text":"Increased lung compliance"},{"id":"b","text":"Decreased respiratory drive"},{"id":"c","text":"Impaired gas exchange due to heart defects"},{"id":"d","text":"Normal gas exchange"}],"answerId":"c","explanation":"Infants with Cri-du-chat syndrome may have heart defects that can impair gas exchange, leading to respiratory issues.","kind":"integration","linkedModuleIds":["gas-exchange-diffusion"],"origin":"ai"},{"id":"autosomal-deletion-syndromes~ai-6","moduleId":"autosomal-deletion-syndromes","stem":"Which of the following syndromes can be compared to Wolf-Hirschhorn syndrome in terms of genetic deletion?","options":[{"id":"a","text":"Cri-du-chat syndrome"},{"id":"b","text":"Down syndrome"},{"id":"c","text":"Turner syndrome"},{"id":"d","text":"Klinefelter syndrome"}],"answerId":"a","explanation":"Cri-du-chat syndrome and Wolf-Hirschhorn syndrome are both characterized by chromosomal deletions and share similar clinical features.","kind":"integration","linkedModuleIds":["microdeletion-imprinting-syndromes"],"origin":"ai"}],"microdeletion-imprinting-syndromes":[{"id":"microdeletion-imprinting-syndromes~ai-0","moduleId":"microdeletion-imprinting-syndromes","stem":"What is the primary mechanism leading to the different phenotypes of Prader-Willi and Angelman syndromes?","options":[{"id":"a","text":"Maternal deletion of 15q11-q13"},{"id":"b","text":"Paternal deletion of 15q11-q13"},{"id":"c","text":"Imprinting defect on chromosome 15"},{"id":"d","text":"Uniparental disomy of chromosome 15"}],"answerId":"c","explanation":"Both syndromes arise from deletions at the same locus, but the parent of origin (maternal vs paternal) determines the phenotype due to genomic imprinting.","kind":"mechanism","origin":"ai"},{"id":"microdeletion-imprinting-syndromes~ai-1","moduleId":"microdeletion-imprinting-syndromes","stem":"Which clinical finding is characteristic of Prader-Willi syndrome?","options":[{"id":"a","text":"Ataxic gait"},{"id":"b","text":"Neonatal hypotonia"},{"id":"c","text":"Supravalvular aortic stenosis"},{"id":"d","text":"Absent speech"}],"answerId":"b","explanation":"Prader-Willi syndrome is characterized by neonatal hypotonia, which later progresses to hyperphagia and obesity.","kind":"clinical","origin":"ai"},{"id":"microdeletion-imprinting-syndromes~ai-2","moduleId":"microdeletion-imprinting-syndromes","stem":"Which of the following is NOT a feature of Angelman syndrome?","options":[{"id":"a","text":"Severe intellectual disability"},{"id":"b","text":"Inappropriate laughter"},{"id":"c","text":"Hyperphagia"},{"id":"d","text":"Ataxic gait"}],"answerId":"c","explanation":"Hyperphagia is characteristic of Prader-Willi syndrome, not Angelman syndrome.","kind":"trap","origin":"ai"},{"id":"microdeletion-imprinting-syndromes~ai-3","moduleId":"microdeletion-imprinting-syndromes","stem":"What is the genetic basis of Williams syndrome?","options":[{"id":"a","text":"Deletion of 15q11-q13"},{"id":"b","text":"Deletion of 7q11.23"},{"id":"c","text":"Uniparental disomy of chromosome 7"},{"id":"d","text":"Imprinting defect on chromosome 7"}],"answerId":"b","explanation":"Williams syndrome is caused by a deletion at 7q11.23, which includes the elastin gene.","kind":"recall","origin":"ai"},{"id":"microdeletion-imprinting-syndromes~ai-4","moduleId":"microdeletion-imprinting-syndromes","stem":"In Prader-Willi syndrome, which genetic alteration is most commonly observed?","options":[{"id":"a","text":"Maternal uniparental disomy"},{"id":"b","text":"Paternal deletion of 15q11-q13"},{"id":"c","text":"Maternal deletion of 15q11-q13"},{"id":"d","text":"Imprinting defect on chromosome 15"}],"answerId":"b","explanation":"The majority of cases of Prader-Willi syndrome are due to a paternal deletion of the 15q11-q13 region.","kind":"recall","origin":"ai"},{"id":"microdeletion-imprinting-syndromes~ai-5","moduleId":"microdeletion-imprinting-syndromes","stem":"How does Prader-Willi syndrome relate to the sex steroid synthesis module?","options":[{"id":"a","text":"It involves hypogonadism affecting steroid synthesis"},{"id":"b","text":"It is caused by a mutation in a steroid receptor"},{"id":"c","text":"It leads to increased estrogen production"},{"id":"d","text":"It is unrelated to steroid synthesis"}],"answerId":"a","explanation":"Prader-Willi syndrome includes hypogonadism, which can affect sex steroid synthesis and lead to various endocrine abnormalities.","kind":"integration","linkedModuleIds":["hrp1-sex-steroid-synthesis-action"],"origin":"ai"},{"id":"microdeletion-imprinting-syndromes~ai-6","moduleId":"microdeletion-imprinting-syndromes","stem":"Which feature of DiGeorge syndrome is also relevant to the understanding of microdeletion syndromes?","options":[{"id":"a","text":"Thymic hypoplasia"},{"id":"b","text":"Supravalvular aortic stenosis"},{"id":"c","text":"Hypercalcemia"},{"id":"d","text":"Severe intellectual disability"}],"answerId":"a","explanation":"Thymic hypoplasia is a key feature of DiGeorge syndrome, which is also a microdeletion syndrome, highlighting the impact of chromosomal deletions on development.","kind":"integration","linkedModuleIds":["autosomal-deletion-syndromes"],"origin":"ai"}],"prenatal-screening-diagnosis":[{"id":"prenatal-screening-diagnosis~ai-0","moduleId":"prenatal-screening-diagnosis","stem":"What is the primary purpose of serum screening tests in prenatal care?","options":[{"id":"a","text":"To confirm fetal aneuploidy"},{"id":"b","text":"To estimate risk of fetal abnormalities"},{"id":"c","text":"To provide a definitive karyotype"},{"id":"d","text":"To diagnose gestational diabetes"}],"answerId":"b","explanation":"Serum screening tests are designed to estimate the risk of fetal abnormalities, not to provide definitive diagnoses.","kind":"recall","origin":"ai"},{"id":"prenatal-screening-diagnosis~ai-1","moduleId":"prenatal-screening-diagnosis","stem":"Which of the following patterns on a quad screen is most indicative of Down syndrome?","options":[{"id":"a","text":"↑AFP, ↓uE3, ↑hCG, ↑inhibin A"},{"id":"b","text":"↓AFP, ↓uE3, ↑hCG, ↑inhibin A"},{"id":"c","text":"↓AFP, ↑uE3, ↑hCG, ↓inhibin A"},{"id":"d","text":"↑AFP, ↑uE3, ↓hCG, ↓inhibin A"}],"answerId":"b","explanation":"The classic quad screen pattern for Down syndrome includes ↓AFP, ↓uE3, ↑hCG, and ↑inhibin A.","kind":"mechanism","origin":"ai"},{"id":"prenatal-screening-diagnosis~ai-2","moduleId":"prenatal-screening-diagnosis","stem":"What is the risk associated with chorionic villus sampling (CVS) when performed very early?","options":[{"id":"a","text":"Higher risk of miscarriage"},{"id":"b","text":"Lower accuracy of karyotyping"},{"id":"c","text":"Increased risk of neural tube defects"},{"id":"d","text":"Higher risk of limb abnormalities"}],"answerId":"a","explanation":"CVS performed very early carries a slightly higher risk of miscarriage compared to later procedures.","kind":"trap","origin":"ai"},{"id":"prenatal-screening-diagnosis~ai-3","moduleId":"prenatal-screening-diagnosis","stem":"Which test is recommended for confirming a positive non-invasive prenatal test (NIPT) result?","options":[{"id":"a","text":"Amniocentesis"},{"id":"b","text":"Chorionic villus sampling"},{"id":"c","text":"Ultrasound"},{"id":"d","text":"Quad screen"}],"answerId":"a","explanation":"A positive NIPT result must be confirmed with amniocentesis or CVS to obtain a definitive karyotype.","kind":"clinical","origin":"ai"},{"id":"prenatal-screening-diagnosis~ai-4","moduleId":"prenatal-screening-diagnosis","stem":"In the context of prenatal screening, what does a positive quad screen indicate?","options":[{"id":"a","text":"Confirmed Down syndrome"},{"id":"b","text":"Increased risk of fetal abnormalities"},{"id":"c","text":"Normal fetal development"},{"id":"d","text":"Immediate need for invasive testing"}],"answerId":"b","explanation":"A positive quad screen indicates an increased risk of fetal abnormalities, but does not confirm any condition.","kind":"trap","origin":"ai"},{"id":"prenatal-screening-diagnosis~ai-5","moduleId":"prenatal-screening-diagnosis","stem":"How does advanced maternal age influence prenatal screening recommendations?","options":[{"id":"a","text":"It eliminates the need for screening tests"},{"id":"b","text":"It is a risk factor for aneuploidy"},{"id":"c","text":"It guarantees a positive NIPT result"},{"id":"d","text":"It requires immediate diagnostic testing"}],"answerId":"b","explanation":"Advanced maternal age is a known risk factor for aneuploidy, prompting recommendations for screening.","kind":"integration","linkedModuleIds":["hrp1-prenatal-care-risk-screening"],"origin":"ai"},{"id":"prenatal-screening-diagnosis~ai-6","moduleId":"prenatal-screening-diagnosis","stem":"Which prenatal screening test is most sensitive for detecting trisomy 21?","options":[{"id":"a","text":"Quad screen"},{"id":"b","text":"Amniocentesis"},{"id":"c","text":"NIPT"},{"id":"d","text":"CVS"}],"answerId":"c","explanation":"NIPT is the most sensitive screening test for detecting trisomy 21, but positive results require confirmation.","kind":"recall","origin":"ai"},{"id":"prenatal-screening-diagnosis~ai-7","moduleId":"prenatal-screening-diagnosis","stem":"What is the relationship between thalassemia carrier screening and prenatal care?","options":[{"id":"a","text":"It is unrelated to prenatal screening"},{"id":"b","text":"It is performed only after positive NIPT"},{"id":"c","text":"It helps identify couples at risk for affected offspring"},{"id":"d","text":"It is a diagnostic test for fetal conditions"}],"answerId":"c","explanation":"Thalassemia carrier screening helps identify couples at risk for having affected children, which is relevant in prenatal care.","kind":"integration","linkedModuleIds":["thalassemia-prevention-screening"],"origin":"ai"}],"mendelian-inheritance-patterns":[{"id":"mendelian-inheritance-patterns~ai-0","moduleId":"mendelian-inheritance-patterns","stem":"What is the recurrence risk of an autosomal recessive disorder if both parents are carriers?","options":[{"id":"a","text":"0%"},{"id":"b","text":"25%"},{"id":"c","text":"50%"},{"id":"d","text":"100%"}],"answerId":"b","explanation":"If both parents are carriers, there is a 25% chance that their child will inherit both mutant alleles and express the disorder.","kind":"recall","origin":"ai"},{"id":"mendelian-inheritance-patterns~ai-1","moduleId":"mendelian-inheritance-patterns","stem":"Which of the following is a hallmark of X-linked recessive inheritance?","options":[{"id":"a","text":"Affected males can transmit the disorder to their sons."},{"id":"b","text":"Both sexes are equally affected."},{"id":"c","text":"Carrier females do not express the disease."},{"id":"d","text":"Affected females transmit the disorder to all their sons."}],"answerId":"c","explanation":"In X-linked recessive inheritance, carrier females typically do not express the disease, while affected males transmit the disorder to all their daughters but not to their sons.","kind":"recall","origin":"ai"},{"id":"mendelian-inheritance-patterns~ai-2","moduleId":"mendelian-inheritance-patterns","stem":"A family presents with a genetic disorder affecting males predominantly, but affected males have unaffected fathers. What is the most likely inheritance pattern?","options":[{"id":"a","text":"Autosomal dominant"},{"id":"b","text":"Autosomal recessive"},{"id":"c","text":"X-linked recessive"},{"id":"d","text":"Mitochondrial inheritance"}],"answerId":"c","explanation":"The absence of affected fathers in a family with predominantly affected males suggests X-linked recessive inheritance.","kind":"clinical","origin":"ai"},{"id":"mendelian-inheritance-patterns~ai-3","moduleId":"mendelian-inheritance-patterns","stem":"Which of the following patterns of inheritance is characterized by the presence of affected individuals in every generation?","options":[{"id":"a","text":"Autosomal dominant"},{"id":"b","text":"Autosomal recessive"},{"id":"c","text":"X-linked dominant"},{"id":"d","text":"Mitochondrial inheritance"}],"answerId":"a","explanation":"Autosomal dominant disorders are typically seen in every generation due to the presence of at least one affected allele.","kind":"recall","origin":"ai"},{"id":"mendelian-inheritance-patterns~ai-4","moduleId":"mendelian-inheritance-patterns","stem":"A mother with a mitochondrial disorder has two children. What is the likelihood that both children will inherit the disorder?","options":[{"id":"a","text":"0%"},{"id":"b","text":"25%"},{"id":"c","text":"50%"},{"id":"d","text":"100%"}],"answerId":"d","explanation":"All children of an affected mother will inherit the mitochondrial disorder, as it is passed maternally.","kind":"recall","origin":"ai"},{"id":"mendelian-inheritance-patterns~ai-5","moduleId":"mendelian-inheritance-patterns","stem":"In a pedigree showing a genetic disorder with male-to-male transmission, which inheritance pattern can be excluded?","options":[{"id":"a","text":"Autosomal dominant"},{"id":"b","text":"Autosomal recessive"},{"id":"c","text":"X-linked recessive"},{"id":"d","text":"Mitochondrial inheritance"}],"answerId":"c","explanation":"Male-to-male transmission excludes X-linked recessive inheritance, as affected males cannot pass the X chromosome to their sons.","kind":"trap","origin":"ai"},{"id":"mendelian-inheritance-patterns~ai-6","moduleId":"mendelian-inheritance-patterns","stem":"A patient with Tetralogy of Fallot (TOF) has a family history of similar congenital heart defects. Considering Mendelian patterns, what is the most likely inheritance pattern observed?","options":[{"id":"a","text":"Autosomal dominant"},{"id":"b","text":"Autosomal recessive"},{"id":"c","text":"X-linked dominant"},{"id":"d","text":"Mitochondrial inheritance"}],"answerId":"a","explanation":"Congenital heart defects like TOF often follow an autosomal dominant inheritance pattern, especially with a family history.","kind":"integration","linkedModuleIds":["tetralogy-of-fallot"],"origin":"ai"},{"id":"mendelian-inheritance-patterns~ai-7","moduleId":"mendelian-inheritance-patterns","stem":"In a family with a history of cystic fibrosis, which inheritance pattern is most likely responsible for the disease's transmission?","options":[{"id":"a","text":"Autosomal dominant"},{"id":"b","text":"Autosomal recessive"},{"id":"c","text":"X-linked recessive"},{"id":"d","text":"Mitochondrial inheritance"}],"answerId":"b","explanation":"Cystic fibrosis is an autosomal recessive disorder, requiring both parents to be carriers for a child to be affected.","kind":"integration","linkedModuleIds":["inheritance-modifiers"],"origin":"ai"}],"autosomal-trisomies":[{"id":"autosomal-trisomies~ai-0","moduleId":"autosomal-trisomies","stem":"What is the most common autosomal trisomy that survives to birth?","options":[{"id":"a","text":"Trisomy 18"},{"id":"b","text":"Trisomy 21"},{"id":"c","text":"Trisomy 13"},{"id":"d","text":"Trisomy 16"}],"answerId":"b","explanation":"Trisomy 21, or Down syndrome, is the most common autosomal trisomy that survives to birth, occurring in approximately 1 in 850 live births.","kind":"recall","origin":"ai"},{"id":"autosomal-trisomies~ai-1","moduleId":"autosomal-trisomies","stem":"Which of the following findings is characteristic of Edwards syndrome (trisomy 18)?","options":[{"id":"a","text":"Cleft lip and palate"},{"id":"b","text":"Clenched fists with overlapping fingers"},{"id":"c","text":"Hypotonia and flat facies"},{"id":"d","text":"Single palmar crease"}],"answerId":"b","explanation":"Clenched fists with overlapping fingers is a classic finding in Edwards syndrome (trisomy 18).","kind":"recall","origin":"ai"},{"id":"autosomal-trisomies~ai-2","moduleId":"autosomal-trisomies","stem":"What is the mechanism leading to Down syndrome (trisomy 21)?","options":[{"id":"a","text":"Robertsonian translocation"},{"id":"b","text":"Nondisjunction"},{"id":"c","text":"Deletion"},{"id":"d","text":"Inversion"}],"answerId":"b","explanation":"Down syndrome is primarily caused by nondisjunction during meiosis, leading to an extra chromosome 21.","kind":"mechanism","origin":"ai"},{"id":"autosomal-trisomies~ai-3","moduleId":"autosomal-trisomies","stem":"Which statement about recurrence risk in Down syndrome is correct?","options":[{"id":"a","text":"Every Down syndrome pregnancy carries a high recurrence risk"},{"id":"b","text":"Only translocation Down syndrome has a high recurrence risk"},{"id":"c","text":"Free trisomy 21 has a recurrence risk of 50%"},{"id":"d","text":"All Down syndrome cases are inherited"}],"answerId":"b","explanation":"Only translocation Down syndrome has a high recurrence risk; free trisomy 21 recurs at approximately 1%.","kind":"trap","origin":"ai"},{"id":"autosomal-trisomies~ai-4","moduleId":"autosomal-trisomies","stem":"Which of the following is a common complication of Down syndrome?","options":[{"id":"a","text":"Rocker-bottom feet"},{"id":"b","text":"Holoprosencephaly"},{"id":"c","text":"Congenital heart disease"},{"id":"d","text":"Micrognathia"}],"answerId":"c","explanation":"Congenital heart disease is a common complication in individuals with Down syndrome, affecting 40-45% of cases.","kind":"clinical","origin":"ai"},{"id":"autosomal-trisomies~ai-5","moduleId":"autosomal-trisomies","stem":"Which feature is associated with Patau syndrome (trisomy 13)?","options":[{"id":"a","text":"Upslanting palpebral fissures"},{"id":"b","text":"Polydactyly"},{"id":"c","text":"Single palmar crease"},{"id":"d","text":"Clenched fists"}],"answerId":"b","explanation":"Polydactyly is a characteristic feature of Patau syndrome (trisomy 13).","kind":"recall","origin":"ai"},{"id":"autosomal-trisomies~ai-6","moduleId":"autosomal-trisomies","stem":"How does the mechanism of Down syndrome differ from that of autosomal deletion syndromes?","options":[{"id":"a","text":"Down syndrome is caused by deletion"},{"id":"b","text":"Down syndrome involves an extra chromosome"},{"id":"c","text":"Deletion syndromes are always inherited"},{"id":"d","text":"Both involve chromosomal abnormalities"}],"answerId":"b","explanation":"Down syndrome is caused by an extra chromosome (trisomy), while deletion syndromes involve the loss of genetic material.","kind":"integration","linkedModuleIds":["autosomal-deletion-syndromes"],"origin":"ai"},{"id":"autosomal-trisomies~ai-7","moduleId":"autosomal-trisomies","stem":"What is the relationship between maternal age and the risk of Down syndrome?","options":[{"id":"a","text":"Increased risk with younger mothers"},{"id":"b","text":"No relationship"},{"id":"c","text":"Increased risk with older mothers"},{"id":"d","text":"Constant risk regardless of age"}],"answerId":"c","explanation":"The risk of Down syndrome increases with maternal age due to meiotic nondisjunction, particularly in maternal meiosis I.","kind":"integration","linkedModuleIds":["numerical-chromosome-abnormalities"],"origin":"ai"}],"x-inactivation-sex-determination":[{"id":"x-inactivation-sex-determination~ai-0","moduleId":"x-inactivation-sex-determination","stem":"What is the expected number of Barr bodies in a 47,XXX individual?","options":[{"id":"a","text":"2"},{"id":"b","text":"1"},{"id":"c","text":"0"},{"id":"d","text":"3"}],"answerId":"a","explanation":"The number of Barr bodies is calculated as (number of X chromosomes - 1), so 47,XXX has 2 Barr bodies.","kind":"recall","origin":"ai"},{"id":"x-inactivation-sex-determination~ai-1","moduleId":"x-inactivation-sex-determination","stem":"Which gene is responsible for initiating X-inactivation?","options":[{"id":"a","text":"SRY"},{"id":"b","text":"XIST"},{"id":"c","text":"SHOX"},{"id":"d","text":"AMH"}],"answerId":"b","explanation":"The XIST gene at the X-inactivation center is responsible for initiating X-inactivation.","kind":"mechanism","origin":"ai"},{"id":"x-inactivation-sex-determination~ai-2","moduleId":"x-inactivation-sex-determination","stem":"A 45,X individual presents with short stature. What is the underlying mechanism?","options":[{"id":"a","text":"Haploinsufficiency of SHOX"},{"id":"b","text":"Excessive growth hormone"},{"id":"c","text":"Increased estrogen levels"},{"id":"d","text":"Deficiency of testosterone"}],"answerId":"a","explanation":"Short stature in Turner syndrome (45,X) is due to haploinsufficiency of the SHOX gene.","kind":"mechanism","origin":"ai"},{"id":"x-inactivation-sex-determination~ai-3","moduleId":"x-inactivation-sex-determination","stem":"A 47,XXY male is found to have one Barr body. What is the reason for this?","options":[{"id":"a","text":"He has an extra Y chromosome"},{"id":"b","text":"Barr bodies depend on X count, not sex"},{"id":"c","text":"He has a deletion on the Y chromosome"},{"id":"d","text":"He is a mosaic with 46,XY cells"}],"answerId":"b","explanation":"Barr bodies are determined by the number of X chromosomes; 47,XXY has two X chromosomes, resulting in one Barr body.","kind":"trap","origin":"ai"},{"id":"x-inactivation-sex-determination~ai-4","moduleId":"x-inactivation-sex-determination","stem":"What is the role of the SRY gene in sex determination?","options":[{"id":"a","text":"Inhibits Barr body formation"},{"id":"b","text":"Encodes Testis-Determining Factor"},{"id":"c","text":"Promotes X-inactivation"},{"id":"d","text":"Activates the SHOX gene"}],"answerId":"b","explanation":"The SRY gene encodes Testis-Determining Factor (TDF), which is crucial for male sex determination.","kind":"recall","origin":"ai"},{"id":"x-inactivation-sex-determination~ai-5","moduleId":"x-inactivation-sex-determination","stem":"How does the presence of the SRY gene affect gonadal development?","options":[{"id":"a","text":"Promotes ovarian development"},{"id":"b","text":"Inhibits testosterone production"},{"id":"c","text":"Initiates testis formation"},{"id":"d","text":"Causes X-inactivation"}],"answerId":"c","explanation":"The SRY gene initiates the formation of testes, leading to male development.","kind":"mechanism","origin":"ai"},{"id":"x-inactivation-sex-determination~ai-6","moduleId":"x-inactivation-sex-determination","stem":"In a patient with Turner syndrome (45,X), which of the following would be a relevant consideration when evaluating for acid-base disorders?","options":[{"id":"a","text":"Potential respiratory acidosis due to hypoventilation"},{"id":"b","text":"Risk of metabolic alkalosis from excessive vomiting"},{"id":"c","text":"Possible renal tubular acidosis due to kidney malformations"},{"id":"d","text":"Increased risk of respiratory alkalosis from hyperventilation"}],"answerId":"c","explanation":"Patients with Turner syndrome may have renal anomalies, which can lead to renal tubular acidosis.","kind":"integration","linkedModuleIds":["acid-base-disorders"],"origin":"ai"},{"id":"x-inactivation-sex-determination~ai-7","moduleId":"x-inactivation-sex-determination","stem":"How might the SHOX gene's function relate to acid-base balance in a patient with sex chromosome aneuploidy?","options":[{"id":"a","text":"SHOX regulates bicarbonate reabsorption"},{"id":"b","text":"SHOX affects growth hormone levels"},{"id":"c","text":"SHOX is involved in respiratory drive"},{"id":"d","text":"SHOX influences renal function and growth"}],"answerId":"d","explanation":"The SHOX gene influences skeletal growth and may indirectly affect renal function, which can relate to acid-base balance.","kind":"integration","linkedModuleIds":["acid-base-disorders"],"origin":"ai"}],"inheritance-modifiers":[{"id":"inheritance-modifiers~ai-0","moduleId":"inheritance-modifiers","stem":"What is the definition of incomplete penetrance?","options":[{"id":"a","text":"All individuals with the genotype express the phenotype."},{"id":"b","text":"Some individuals with the genotype do not express the phenotype."},{"id":"c","text":"The severity of the phenotype varies among individuals with the same genotype."},{"id":"d","text":"The phenotype appears later in life for some individuals."}],"answerId":"b","explanation":"Incomplete penetrance occurs when not all individuals with a disease genotype show the expected phenotype.","kind":"recall","origin":"ai"},{"id":"inheritance-modifiers~ai-1","moduleId":"inheritance-modifiers","stem":"Which condition is an example of pleiotropy?","options":[{"id":"a","text":"Huntington disease"},{"id":"b","text":"Marfan syndrome"},{"id":"c","text":"Cystic fibrosis"},{"id":"d","text":"Sickle cell disease"}],"answerId":"b","explanation":"Marfan syndrome is characterized by a single mutation affecting multiple organ systems, including the eyes, skeleton, and cardiovascular system.","kind":"recall","origin":"ai"},{"id":"inheritance-modifiers~ai-2","moduleId":"inheritance-modifiers","stem":"A family has a history of Huntington disease. The affected individuals show earlier onset and more severe symptoms in each generation. This phenomenon is known as:","options":[{"id":"a","text":"Variable expressivity"},{"id":"b","text":"Incomplete penetrance"},{"id":"c","text":"Anticipation"},{"id":"d","text":"Locus heterogeneity"}],"answerId":"c","explanation":"Anticipation refers to the worsening of symptoms and earlier onset of disease in successive generations, commonly seen in trinucleotide repeat disorders.","kind":"recall","origin":"ai"},{"id":"inheritance-modifiers~ai-3","moduleId":"inheritance-modifiers","stem":"An unaffected individual is found to be an obligate carrier of a genetic disorder. This scenario exemplifies which concept?","options":[{"id":"a","text":"Variable expressivity"},{"id":"b","text":"Incomplete penetrance"},{"id":"c","text":"Pleiotropy"},{"id":"d","text":"Genomic imprinting"}],"answerId":"b","explanation":"This scenario illustrates incomplete penetrance, where the carrier genotype does not result in the expected phenotype.","kind":"clinical","origin":"ai"},{"id":"inheritance-modifiers~ai-4","moduleId":"inheritance-modifiers","stem":"Which statement correctly differentiates penetrance from expressivity?","options":[{"id":"a","text":"Penetrance is about severity; expressivity is all-or-none."},{"id":"b","text":"Both are the same concept."},{"id":"c","text":"Penetrance is whether a phenotype appears; expressivity is the severity of the phenotype."},{"id":"d","text":"Penetrance only applies to dominant disorders."}],"answerId":"c","explanation":"Penetrance refers to whether the phenotype appears at all, while expressivity refers to the severity of the phenotype when it does appear.","kind":"trap","origin":"ai"},{"id":"inheritance-modifiers~ai-5","moduleId":"inheritance-modifiers","stem":"How does genomic imprinting affect inheritance patterns?","options":[{"id":"a","text":"It causes all alleles to be expressed equally."},{"id":"b","text":"It leads to parent-of-origin specific expression of alleles."},{"id":"c","text":"It results in all offspring being affected."},{"id":"d","text":"It eliminates the effects of environmental factors."}],"answerId":"b","explanation":"Genomic imprinting results in the expression of genes depending on whether they are inherited from the mother or the father.","kind":"mechanism","origin":"ai"},{"id":"inheritance-modifiers~ai-6","moduleId":"inheritance-modifiers","stem":"A patient presents with symptoms of Marfan syndrome. Which of the following findings would best illustrate the concept of pleiotropy?","options":[{"id":"a","text":"A family history of the same mutation causing different diseases."},{"id":"b","text":"Multiple organ systems affected by a single mutation."},{"id":"c","text":"A mutation that only affects the cardiovascular system."},{"id":"d","text":"Variable severity of symptoms among family members."}],"answerId":"b","explanation":"Pleiotropy is demonstrated when a single mutation leads to effects in multiple organ systems, as seen in Marfan syndrome.","kind":"integration","linkedModuleIds":["tetralogy-of-fallot"],"origin":"ai"},{"id":"inheritance-modifiers~ai-7","moduleId":"inheritance-modifiers","stem":"Which of the following best connects the concepts of incomplete penetrance and multifactorial inheritance?","options":[{"id":"a","text":"Both involve single-gene disorders."},{"id":"b","text":"Both can affect the same phenotype."},{"id":"c","text":"Incomplete penetrance can complicate the assessment of multifactorial traits."},{"id":"d","text":"Both are examples of Mendelian inheritance."}],"answerId":"c","explanation":"Incomplete penetrance can complicate the assessment of traits that are influenced by multiple genetic and environmental factors in multifactorial inheritance.","kind":"integration","linkedModuleIds":["multifactorial-population-genetics"],"origin":"ai"}],"thalassemia-prevention-screening":[{"id":"thalassemia-prevention-screening~ai-0","moduleId":"thalassemia-prevention-screening","stem":"What is the primary goal of Thailand's national thalassemia-prevention program?","options":[{"id":"a","text":"To eliminate thalassemia completely"},{"id":"b","text":"To identify at-risk carrier couples"},{"id":"c","text":"To provide free blood transfusions"},{"id":"d","text":"To increase public awareness of thalassemia"}],"answerId":"b","explanation":"The program aims to identify at-risk carrier couples and offer prenatal diagnosis to prevent severe thalassemia phenotypes.","kind":"recall","origin":"ai"},{"id":"thalassemia-prevention-screening~ai-1","moduleId":"thalassemia-prevention-screening","stem":"Which laboratory finding is indicative of β-thalassemia trait?","options":[{"id":"a","text":"Low MCV with normal iron studies"},{"id":"b","text":"HbA₂ > 4%"},{"id":"c","text":"Positive DCIP test"},{"id":"d","text":"Low MCV with high iron studies"}],"answerId":"b","explanation":"An HbA₂ level greater than 4% is a hallmark of β-thalassemia trait.","kind":"recall","origin":"ai"},{"id":"thalassemia-prevention-screening~ai-2","moduleId":"thalassemia-prevention-screening","stem":"In thalassemia screening, what does a low MCV indicate?","options":[{"id":"a","text":"Iron deficiency only"},{"id":"b","text":"Possible thalassemia trait"},{"id":"c","text":"Normal red blood cell production"},{"id":"d","text":"High iron stores"}],"answerId":"b","explanation":"A low MCV flags a possible thalassemia trait, necessitating further confirmatory testing.","kind":"trap","origin":"ai"},{"id":"thalassemia-prevention-screening~ai-3","moduleId":"thalassemia-prevention-screening","stem":"Which of the following tests is used to confirm α-thalassemia-1 trait?","options":[{"id":"a","text":"Hb typing"},{"id":"b","text":"PCR for α-thal-1"},{"id":"c","text":"DCIP test"},{"id":"d","text":"Iron studies"}],"answerId":"b","explanation":"PCR for α-thal-1 is the confirmatory test when a low MCV is detected.","kind":"mechanism","origin":"ai"},{"id":"thalassemia-prevention-screening~ai-4","moduleId":"thalassemia-prevention-screening","stem":"If both partners are carriers of compatible thalassemia traits, what is the next step?","options":[{"id":"a","text":"Reassure them and schedule a follow-up"},{"id":"b","text":"Offer prenatal diagnosis"},{"id":"c","text":"Start iron supplementation"},{"id":"d","text":"Conduct a family history assessment"}],"answerId":"b","explanation":"When both partners are carriers, prenatal diagnosis is offered to detect an affected fetus.","kind":"clinical","origin":"ai"},{"id":"thalassemia-prevention-screening~ai-5","moduleId":"thalassemia-prevention-screening","stem":"How does thalassemia screening relate to prenatal care risk screening?","options":[{"id":"a","text":"Both involve genetic testing"},{"id":"b","text":"Both assess for iron deficiency"},{"id":"c","text":"Both require Hb typing"},{"id":"d","text":"Both focus on maternal health only"}],"answerId":"a","explanation":"Thalassemia screening and prenatal care risk screening both involve genetic testing to identify risks to the fetus.","kind":"integration","linkedModuleIds":["hrp1-prenatal-care-risk-screening"],"origin":"ai"},{"id":"thalassemia-prevention-screening~ai-6","moduleId":"thalassemia-prevention-screening","stem":"What is a common clinical finding in a patient with Hb E trait?","options":[{"id":"a","text":"Low MCV with normal iron studies"},{"id":"b","text":"HbA₂ > 4%"},{"id":"c","text":"Positive DCIP with an Hb E band"},{"id":"d","text":"High ferritin levels"}],"answerId":"c","explanation":"A positive DCIP test with an Hb E band indicates the presence of Hb E trait.","kind":"recall","origin":"ai"},{"id":"thalassemia-prevention-screening~ai-7","moduleId":"thalassemia-prevention-screening","stem":"Which of the following is NOT a severe phenotype targeted by thalassemia prevention programs?","options":[{"id":"a","text":"Hb Bart's hydrops fetalis"},{"id":"b","text":"Homozygous β-thalassemia"},{"id":"c","text":"Hb E disease"},{"id":"d","text":"Sickle cell disease"}],"answerId":"d","explanation":"Sickle cell disease is not one of the severe phenotypes targeted by thalassemia prevention programs in Thailand.","kind":"trap","origin":"ai"},{"id":"thalassemia-prevention-screening~ai-8","moduleId":"thalassemia-prevention-screening","stem":"What is the relationship between thalassemia screening and prenatal screening & diagnosis?","options":[{"id":"a","text":"Both are unrelated"},{"id":"b","text":"Both aim to prevent genetic disorders"},{"id":"c","text":"Both focus on maternal health"},{"id":"d","text":"Both require invasive procedures"}],"answerId":"b","explanation":"Both thalassemia screening and prenatal screening & diagnosis aim to prevent genetic disorders in offspring.","kind":"integration","linkedModuleIds":["prenatal-screening-diagnosis"],"origin":"ai"}],"dsd-fragile-x":[{"id":"dsd-fragile-x~ai-0","moduleId":"dsd-fragile-x","stem":"What is the primary genetic cause of Fragile X syndrome?","options":[{"id":"a","text":"Expansion of CGG repeats in FMR1"},{"id":"b","text":"Deletion of the SRY gene"},{"id":"c","text":"Mutation in the AR gene"},{"id":"d","text":"Translocation of SRY to the X chromosome"}],"answerId":"a","explanation":"Fragile X syndrome is caused by an expansion of CGG repeats in the FMR1 gene, leading to gene silencing.","kind":"recall","origin":"ai"},{"id":"dsd-fragile-x~ai-1","moduleId":"dsd-fragile-x","stem":"A 46,XY individual presents with primary amenorrhea and absent uterus. What is the most likely diagnosis?","options":[{"id":"a","text":"Complete androgen insensitivity syndrome"},{"id":"b","text":"Swyer syndrome"},{"id":"c","text":"Klinefelter syndrome"},{"id":"d","text":"46,XX testicular DSD"}],"answerId":"a","explanation":"This presentation is characteristic of complete androgen insensitivity syndrome, where the individual has male testes but female external genitalia and no uterus.","kind":"clinical","origin":"ai"},{"id":"dsd-fragile-x~ai-2","moduleId":"dsd-fragile-x","stem":"In which condition would you expect to find a 46,XX male with small testes and gynecomastia?","options":[{"id":"a","text":"Klinefelter syndrome"},{"id":"b","text":"Complete androgen insensitivity"},{"id":"c","text":"46,XX testicular DSD"},{"id":"d","text":"Turner syndrome"}],"answerId":"c","explanation":"46,XX testicular DSD occurs when SRY is translocated to the X chromosome, leading to male phenotype with testicular development.","kind":"recall","origin":"ai"},{"id":"dsd-fragile-x~ai-3","moduleId":"dsd-fragile-x","stem":"What is the mechanism by which complete androgen insensitivity syndrome leads to female external genitalia?","options":[{"id":"a","text":"Lack of testosterone production"},{"id":"b","text":"Inability to respond to testosterone"},{"id":"c","text":"Absence of AMH"},{"id":"d","text":"Mutation in the SRY gene"}],"answerId":"b","explanation":"In CAIS, the androgen receptor mutation prevents the body from responding to testosterone, resulting in female external genitalia despite the presence of testes.","kind":"mechanism","origin":"ai"},{"id":"dsd-fragile-x~ai-4","moduleId":"dsd-fragile-x","stem":"A 10-year-old boy with macro-orchidism and intellectual disability is evaluated. Which genetic test would confirm the diagnosis of Fragile X syndrome?","options":[{"id":"a","text":"Karyotype analysis"},{"id":"b","text":"FMR1 CGG repeat analysis"},{"id":"c","text":"SRY gene sequencing"},{"id":"d","text":"Androgen receptor gene testing"}],"answerId":"b","explanation":"FMR1 CGG repeat analysis is the definitive test for diagnosing Fragile X syndrome due to the characteristic repeat expansion.","kind":"recall","origin":"ai"},{"id":"dsd-fragile-x~ai-5","moduleId":"dsd-fragile-x","stem":"How does the presence of AMH affect the development of Müllerian structures in complete androgen insensitivity syndrome?","options":[{"id":"a","text":"Promotes their development"},{"id":"b","text":"Has no effect"},{"id":"c","text":"Causes their regression"},{"id":"d","text":"Stimulates testosterone production"}],"answerId":"c","explanation":"AMH causes regression of Müllerian ducts, leading to the absence of uterine structures in CAIS despite the presence of testes.","kind":"mechanism","origin":"ai"},{"id":"dsd-fragile-x~ai-6","moduleId":"dsd-fragile-x","stem":"A 46,XY individual with complete androgen insensitivity syndrome is evaluated. What finding would you NOT expect?","options":[{"id":"a","text":"Absent uterus"},{"id":"b","text":"Blind-ending vagina"},{"id":"c","text":"Testes in the inguinal canal"},{"id":"d","text":"Normal Müllerian structures"}],"answerId":"d","explanation":"In CAIS, the uterus is absent due to AMH action, and Müllerian structures do not develop.","kind":"trap","origin":"ai"},{"id":"dsd-fragile-x~ai-7","moduleId":"dsd-fragile-x","stem":"How does the mechanism of X-inactivation relate to the expression of Fragile X syndrome?","options":[{"id":"a","text":"It silences the FMR1 gene"},{"id":"b","text":"It enhances FMRP production"},{"id":"c","text":"It prevents CGG repeat expansion"},{"id":"d","text":"It affects only males"}],"answerId":"a","explanation":"X-inactivation can silence the FMR1 gene, which is crucial in understanding the expression of Fragile X syndrome in females.","kind":"integration","linkedModuleIds":["x-inactivation-sex-determination"],"origin":"ai"},{"id":"dsd-fragile-x~ai-8","moduleId":"dsd-fragile-x","stem":"Which condition's clinical features can be linked to sex chromosome aneuploidies?","options":[{"id":"a","text":"Complete androgen insensitivity syndrome"},{"id":"b","text":"Klinefelter syndrome"},{"id":"c","text":"Fragile X syndrome"},{"id":"d","text":"Swyer syndrome"}],"answerId":"b","explanation":"Klinefelter syndrome is a type of sex chromosome aneuploidy characterized by the presence of an extra X chromosome in males.","kind":"integration","linkedModuleIds":["sex-chromosome-aneuploidies"],"origin":"ai"}],"multifactorial-population-genetics":[{"id":"multifactorial-population-genetics~ai-0","moduleId":"multifactorial-population-genetics","stem":"What is the recurrence risk for first-degree relatives of a proband with a multifactorial condition like cleft lip?","options":[{"id":"a","text":"0.5%"},{"id":"b","text":"2–4%"},{"id":"c","text":"10%"},{"id":"d","text":"25%"}],"answerId":"b","explanation":"The recurrence risk for first-degree relatives of a proband with a multifactorial condition is typically 2–4%.","kind":"recall","origin":"ai"},{"id":"multifactorial-population-genetics~ai-1","moduleId":"multifactorial-population-genetics","stem":"In the Hardy-Weinberg equilibrium, if the incidence of a recessive disease is 1/2500, what is the carrier frequency?","options":[{"id":"a","text":"1/50"},{"id":"b","text":"1/25"},{"id":"c","text":"1/100"},{"id":"d","text":"1/500"}],"answerId":"b","explanation":"For a disease incidence of 1/2500, the carrier frequency can be calculated as approximately 1/25.","kind":"mechanism","origin":"ai"},{"id":"multifactorial-population-genetics~ai-2","moduleId":"multifactorial-population-genetics","stem":"Which of the following best describes the liability-threshold model?","options":[{"id":"a","text":"Disease is caused by a single gene mutation."},{"id":"b","text":"Environmental factors have no role in disease development."},{"id":"c","text":"A threshold of liability must be crossed for disease to manifest."},{"id":"d","text":"All individuals have the same risk of developing the disease."}],"answerId":"c","explanation":"The liability-threshold model states that many genes and environmental factors contribute to a continuous liability, and disease appears once a threshold is crossed.","kind":"mechanism","origin":"ai"},{"id":"multifactorial-population-genetics~ai-3","moduleId":"multifactorial-population-genetics","stem":"What is the correct interpretation of q² in the context of Hardy-Weinberg equilibrium?","options":[{"id":"a","text":"Carrier frequency equals disease incidence."},{"id":"b","text":"q² represents the incidence of homozygous recessive individuals."},{"id":"c","text":"q² is the total population frequency of the recessive allele."},{"id":"d","text":"q² is the frequency of carriers in the population."}],"answerId":"b","explanation":"In Hardy-Weinberg equilibrium, q² represents the incidence of homozygous recessive individuals, while the carrier frequency is approximately 2q.","kind":"trap","origin":"ai"},{"id":"multifactorial-population-genetics~ai-4","moduleId":"multifactorial-population-genetics","stem":"Which of the following conditions demonstrates a high carrier frequency due to heterozygote advantage?","options":[{"id":"a","text":"Cystic fibrosis"},{"id":"b","text":"Sickle cell disease"},{"id":"c","text":"Tay-Sachs disease"},{"id":"d","text":"Hemophilia"}],"answerId":"b","explanation":"Sickle cell disease shows a high carrier frequency in malaria-endemic areas due to the heterozygote advantage.","kind":"recall","origin":"ai"},{"id":"multifactorial-population-genetics~ai-5","moduleId":"multifactorial-population-genetics","stem":"How does the heritability estimate for a trait like height relate to twin studies?","options":[{"id":"a","text":"It is derived from the difference in height between identical twins."},{"id":"b","text":"It is calculated from the concordance rates of monozygotic and dizygotic twins."},{"id":"c","text":"It indicates that height is solely determined by genetics."},{"id":"d","text":"It shows that environmental factors have no impact on height."}],"answerId":"b","explanation":"Heritability estimates are derived from twin concordance rates, comparing monozygotic and dizygotic twins.","kind":"recall","origin":"ai"},{"id":"multifactorial-population-genetics~ai-6","moduleId":"multifactorial-population-genetics","stem":"A patient with a family history of diabetes presents with symptoms. What is the expected recurrence risk for their first-degree relatives?","options":[{"id":"a","text":"0.5%"},{"id":"b","text":"2–4%"},{"id":"c","text":"10%"},{"id":"d","text":"25%"}],"answerId":"b","explanation":"The recurrence risk for first-degree relatives of a proband with a multifactorial condition like diabetes is typically 2–4%.","kind":"integration","linkedModuleIds":["mendelian-inheritance-patterns"],"origin":"ai"},{"id":"multifactorial-population-genetics~ai-7","moduleId":"multifactorial-population-genetics","stem":"In a population with a known incidence of a recessive genetic disorder, how can the carrier frequency be estimated?","options":[{"id":"a","text":"By using the formula q² = incidence to find q."},{"id":"b","text":"By calculating the average age of onset."},{"id":"c","text":"By assessing the phenotypic expression in the population."},{"id":"d","text":"By determining the environmental factors affecting the population."}],"answerId":"a","explanation":"The carrier frequency can be estimated using the formula q² = incidence to find q, then applying it to calculate 2pq.","kind":"integration","linkedModuleIds":["mendelian-inheritance-patterns"],"origin":"ai"}],"etc-inhibitors-uncoupling-shuttles":[{"id":"etc-inhibitors-uncoupling-shuttles~ai-0","moduleId":"etc-inhibitors-uncoupling-shuttles","stem":"Which of the following inhibitors specifically targets Complex I of the electron transport chain?","options":[{"id":"a","text":"Rotenone"},{"id":"b","text":"Antimycin A"},{"id":"c","text":"Cyanide"},{"id":"d","text":"Oligomycin"}],"answerId":"a","explanation":"Rotenone is known to inhibit Complex I, while the others target different complexes.","kind":"recall","origin":"ai"},{"id":"etc-inhibitors-uncoupling-shuttles~ai-1","moduleId":"etc-inhibitors-uncoupling-shuttles","stem":"What is the primary effect of uncouplers on oxidative phosphorylation?","options":[{"id":"a","text":"Increase ATP production"},{"id":"b","text":"Decrease oxygen consumption"},{"id":"c","text":"Increase heat production"},{"id":"d","text":"Decrease electron transport"}],"answerId":"c","explanation":"Uncouplers dissipate the proton gradient, leading to increased heat production while decreasing ATP synthesis.","kind":"mechanism","origin":"ai"},{"id":"etc-inhibitors-uncoupling-shuttles~ai-2","moduleId":"etc-inhibitors-uncoupling-shuttles","stem":"A patient presents with severe lactic acidosis and high venous O₂ levels after exposure to smoke. What is the likely cause?","options":[{"id":"a","text":"Cyanide poisoning"},{"id":"b","text":"Oligomycin administration"},{"id":"c","text":"Antimycin A exposure"},{"id":"d","text":"Uncoupler ingestion"}],"answerId":"a","explanation":"Cyanide blocks Complex IV, preventing oxygen utilization and leading to lactic acidosis.","kind":"clinical","origin":"ai"},{"id":"etc-inhibitors-uncoupling-shuttles~ai-3","moduleId":"etc-inhibitors-uncoupling-shuttles","stem":"Which statement correctly differentiates between ETC inhibitors and uncouplers?","options":[{"id":"a","text":"Both decrease oxygen consumption"},{"id":"b","text":"ETC inhibitors increase ATP production"},{"id":"c","text":"Uncouplers decrease oxygen consumption"},{"id":"d","text":"ETC inhibitors decrease oxygen use"}],"answerId":"d","explanation":"ETC inhibitors block electron flow, decreasing oxygen consumption, while uncouplers increase oxygen consumption by dissipating the proton gradient.","kind":"trap","origin":"ai"},{"id":"etc-inhibitors-uncoupling-shuttles~ai-4","moduleId":"etc-inhibitors-uncoupling-shuttles","stem":"How does the malate-aspartate shuttle differ from the glycerol-3-phosphate shuttle in terms of ATP yield?","options":[{"id":"a","text":"Both yield the same ATP"},{"id":"b","text":"Malate-aspartate yields more ATP"},{"id":"c","text":"Glycerol-3-phosphate yields more ATP"},{"id":"d","text":"Neither shuttle yields ATP"}],"answerId":"b","explanation":"The malate-aspartate shuttle preserves NADH yield, resulting in more ATP compared to the glycerol-3-phosphate shuttle.","kind":"recall","origin":"ai"},{"id":"etc-inhibitors-uncoupling-shuttles~ai-5","moduleId":"etc-inhibitors-uncoupling-shuttles","stem":"In a patient with alcoholic ketoacidosis, what is the primary metabolic disturbance affecting oxidative phosphorylation?","options":[{"id":"a","text":"Increased NADH levels"},{"id":"b","text":"Decreased ATP synthesis"},{"id":"c","text":"Increased proton gradient"},{"id":"d","text":"Decreased oxygen consumption"}],"answerId":"a","explanation":"Alcohol metabolism increases NADH levels, which can disrupt the balance of oxidative phosphorylation.","kind":"integration","linkedModuleIds":["alcoholic-ketoacidosis-redox"],"origin":"ai"},{"id":"etc-inhibitors-uncoupling-shuttles~ai-6","moduleId":"etc-inhibitors-uncoupling-shuttles","stem":"How does cyanide poisoning relate to the principles of oxidative phosphorylation?","options":[{"id":"a","text":"It acts as an uncoupler"},{"id":"b","text":"It inhibits ATP synthase"},{"id":"c","text":"It blocks electron transport at Complex IV"},{"id":"d","text":"It enhances oxygen consumption"}],"answerId":"c","explanation":"Cyanide inhibits Complex IV, preventing electron transport and oxygen utilization.","kind":"integration","linkedModuleIds":["electron-transport-oxphos"],"origin":"ai"}],"lipid-digestion-chylomicrons":[{"id":"lipid-digestion-chylomicrons~ai-0","moduleId":"lipid-digestion-chylomicrons","stem":"What is the primary function of bile salts in lipid digestion?","options":[{"id":"a","text":"Emulsify dietary fat"},{"id":"b","text":"Hydrolyze TAG"},{"id":"c","text":"Re-esterify fatty acids"},{"id":"d","text":"Absorb fat-soluble vitamins"}],"answerId":"a","explanation":"Bile salts emulsify dietary fat, increasing the surface area for pancreatic lipase action.","kind":"recall","origin":"ai"},{"id":"lipid-digestion-chylomicrons~ai-1","moduleId":"lipid-digestion-chylomicrons","stem":"Which component is primarily responsible for the hydrolysis of triglycerides in the intestine?","options":[{"id":"a","text":"Bile salts"},{"id":"b","text":"Colipase"},{"id":"c","text":"Pancreatic lipase"},{"id":"d","text":"Chylomicrons"}],"answerId":"c","explanation":"Pancreatic lipase, aided by colipase, hydrolyzes triglycerides to free fatty acids and monoacylglycerol.","kind":"mechanism","origin":"ai"},{"id":"lipid-digestion-chylomicrons~ai-2","moduleId":"lipid-digestion-chylomicrons","stem":"What clinical finding is indicative of fat malabsorption?","options":[{"id":"a","text":"Prolonged PT"},{"id":"b","text":"Bulky, greasy stool"},{"id":"c","text":"Elevated liver enzymes"},{"id":"d","text":"Decreased serum albumin"}],"answerId":"b","explanation":"Bulky, greasy stools are characteristic of steatorrhea due to excess fecal fat.","kind":"recall","origin":"ai"},{"id":"lipid-digestion-chylomicrons~ai-3","moduleId":"lipid-digestion-chylomicrons","stem":"In the enterocyte, which of the following correctly describes the fate of lipid products?","options":[{"id":"a","text":"They are absorbed whole from micelles"},{"id":"b","text":"They are re-esterified into triglycerides"},{"id":"c","text":"They are directly released into the bloodstream"},{"id":"d","text":"They remain in the lumen for recycling"}],"answerId":"b","explanation":"Lipid products leave the micelle and enter the enterocyte, where they are re-esterified into triglycerides.","kind":"trap","origin":"ai"},{"id":"lipid-digestion-chylomicrons~ai-4","moduleId":"lipid-digestion-chylomicrons","stem":"What is the consequence of a deficiency in bile salts?","options":[{"id":"a","text":"Increased absorption of fat-soluble vitamins"},{"id":"b","text":"Steatorrhea and vitamin deficiencies"},{"id":"c","text":"Enhanced triglyceride synthesis"},{"id":"d","text":"Decreased chylomicron formation"}],"answerId":"b","explanation":"Deficient bile salts lead to impaired fat digestion, causing steatorrhea and potential deficiencies in vitamins A, D, E, and K.","kind":"recall","origin":"ai"},{"id":"lipid-digestion-chylomicrons~ai-5","moduleId":"lipid-digestion-chylomicrons","stem":"How do mixed micelles facilitate lipid absorption in the intestine?","options":[{"id":"a","text":"By being absorbed intact"},{"id":"b","text":"By delivering lipid products to the brush border"},{"id":"c","text":"By hydrolyzing triglycerides"},{"id":"d","text":"By forming chylomicrons"}],"answerId":"b","explanation":"Mixed micelles deliver lipid products and fat-soluble vitamins to the brush border for absorption.","kind":"mechanism","origin":"ai"},{"id":"lipid-digestion-chylomicrons~ai-6","moduleId":"lipid-digestion-chylomicrons","stem":"How does fat malabsorption relate to vitamin K deficiency?","options":[{"id":"a","text":"Increased bile salt recycling"},{"id":"b","text":"Decreased γ-carboxylation of clotting factors"},{"id":"c","text":"Enhanced intestinal absorption of vitamin K"},{"id":"d","text":"Increased triglyceride synthesis"}],"answerId":"b","explanation":"Fat malabsorption leads to vitamin K deficiency, which reduces γ-carboxylation of clotting factors, prolonging PT.","kind":"integration","linkedModuleIds":["hgb-lipid-digestion-absorption"],"origin":"ai"},{"id":"lipid-digestion-chylomicrons~ai-7","moduleId":"lipid-digestion-chylomicrons","stem":"Which of the following best explains the relationship between bile salt deficiency and malabsorption?","options":[{"id":"a","text":"Increased fat absorption"},{"id":"b","text":"Decreased fat emulsification"},{"id":"c","text":"Enhanced chylomicron formation"},{"id":"d","text":"Increased bile salt synthesis"}],"answerId":"b","explanation":"Bile salt deficiency decreases fat emulsification, leading to malabsorption of lipids and fat-soluble vitamins.","kind":"integration","linkedModuleIds":["enterohepatic-bile-circulation"],"origin":"ai"}],"pdh-tca-cycle":[{"id":"pdh-tca-cycle~ai-0","moduleId":"pdh-tca-cycle","stem":"What is the primary product of the pyruvate dehydrogenase (PDH) complex reaction?","options":[{"id":"a","text":"Acetyl-CoA"},{"id":"b","text":"Lactate"},{"id":"c","text":"Oxaloacetate"},{"id":"d","text":"Citrate"}],"answerId":"a","explanation":"The PDH complex converts pyruvate to acetyl-CoA, producing CO₂ and NADH.","kind":"recall","origin":"ai"},{"id":"pdh-tca-cycle~ai-1","moduleId":"pdh-tca-cycle","stem":"Which cofactor is NOT required by the pyruvate dehydrogenase complex?","options":[{"id":"a","text":"Thiamine (B1)"},{"id":"b","text":"Lipoate"},{"id":"c","text":"Coenzyme A (B5)"},{"id":"d","text":"Vitamin C (C)"}],"answerId":"d","explanation":"Vitamin C (ascorbic acid) is not a cofactor for the PDH complex.","kind":"recall","origin":"ai"},{"id":"pdh-tca-cycle~ai-2","moduleId":"pdh-tca-cycle","stem":"What is the effect of high ATP/NADH levels on the TCA cycle?","options":[{"id":"a","text":"Stimulates the cycle"},{"id":"b","text":"Inhibits the cycle"},{"id":"c","text":"No effect"},{"id":"d","text":"Increases lactate production"}],"answerId":"b","explanation":"High ATP/NADH levels inhibit the TCA cycle by slowing down key enzymes.","kind":"mechanism","origin":"ai"},{"id":"pdh-tca-cycle~ai-3","moduleId":"pdh-tca-cycle","stem":"A patient presents with lactic acidosis and neurologic dysfunction after a carbohydrate load. What is the most likely underlying issue?","options":[{"id":"a","text":"PDH deficiency"},{"id":"b","text":"TCA cycle blockage"},{"id":"c","text":"NADH shuttle defect"},{"id":"d","text":"Mitochondrial dysfunction"}],"answerId":"a","explanation":"PDH deficiency leads to the diversion of pyruvate to lactate, causing lactic acidosis.","kind":"clinical","origin":"ai"},{"id":"pdh-tca-cycle~ai-4","moduleId":"pdh-tca-cycle","stem":"Which statement about the TCA cycle's oxygen dependence is true?","options":[{"id":"a","text":"It directly consumes molecular oxygen"},{"id":"b","text":"It requires oxygen for substrate-level phosphorylation"},{"id":"c","text":"It does not use O₂ but stops without it"},{"id":"d","text":"It produces O₂ as a byproduct"}],"answerId":"c","explanation":"The TCA cycle does not directly use O₂ but requires it indirectly for the regeneration of NAD⁺ and FAD.","kind":"trap","origin":"ai"},{"id":"pdh-tca-cycle~ai-5","moduleId":"pdh-tca-cycle","stem":"How does a ketogenic diet improve symptoms in patients with PDH deficiency?","options":[{"id":"a","text":"Increases lactate production"},{"id":"b","text":"Bypasses the blocked pyruvate-to-acetyl-CoA step"},{"id":"c","text":"Enhances TCA cycle activity"},{"id":"d","text":"Decreases fatty acid oxidation"}],"answerId":"b","explanation":"Ketones can be converted to acetyl-CoA, bypassing the PDH block.","kind":"mechanism","origin":"ai"},{"id":"pdh-tca-cycle~ai-6","moduleId":"pdh-tca-cycle","stem":"How is the TCA cycle linked to oxidative phosphorylation?","options":[{"id":"a","text":"Produces ATP directly"},{"id":"b","text":"Generates NADH and FADH₂ for the ETC"},{"id":"c","text":"Utilizes O₂ directly"},{"id":"d","text":"Regenerates ADP from ATP"}],"answerId":"b","explanation":"The TCA cycle generates NADH and FADH₂, which are used in the electron transport chain for ATP production.","kind":"integration","linkedModuleIds":["electron-transport-oxphos"],"origin":"ai"},{"id":"pdh-tca-cycle~ai-7","moduleId":"pdh-tca-cycle","stem":"What role does the TCA cycle play in anaplerosis?","options":[{"id":"a","text":"It generates ATP"},{"id":"b","text":"It provides intermediates for biosynthesis"},{"id":"c","text":"It directly consumes O₂"},{"id":"d","text":"It produces lactate"}],"answerId":"b","explanation":"The TCA cycle provides intermediates that are essential for various biosynthetic pathways.","kind":"integration","linkedModuleIds":["tca-amphibolic-anaplerosis"],"origin":"ai"}],"electron-transport-oxphos":[{"id":"electron-transport-oxphos~ai-0","moduleId":"electron-transport-oxphos","stem":"Which complex of the electron transport chain does NOT pump protons?","options":[{"id":"a","text":"Complex I"},{"id":"b","text":"Complex II"},{"id":"c","text":"Complex III"},{"id":"d","text":"Complex IV"}],"answerId":"b","explanation":"Complex II, also known as succinate dehydrogenase, transfers electrons to CoQ without pumping protons.","kind":"recall","origin":"ai"},{"id":"electron-transport-oxphos~ai-1","moduleId":"electron-transport-oxphos","stem":"What is the terminal electron acceptor in the electron transport chain?","options":[{"id":"a","text":"NAD+"},{"id":"b","text":"FAD"},{"id":"c","text":"O₂"},{"id":"d","text":"CoQ"}],"answerId":"c","explanation":"Oxygen (O₂) is the final electron acceptor in the electron transport chain, forming water.","kind":"recall","origin":"ai"},{"id":"electron-transport-oxphos~ai-2","moduleId":"electron-transport-oxphos","stem":"Why does NADH yield more ATP than FADH₂?","options":[{"id":"a","text":"NADH enters at complex II"},{"id":"b","text":"FADH₂ bypasses complex I"},{"id":"c","text":"NADH donates electrons to CoQ"},{"id":"d","text":"FADH₂ is less efficient"}],"answerId":"b","explanation":"FADH₂ bypasses complex I, resulting in fewer protons being pumped and less ATP generated.","kind":"mechanism","origin":"ai"},{"id":"electron-transport-oxphos~ai-3","moduleId":"electron-transport-oxphos","stem":"Inhibition of which complex would directly reduce ATP synthesis by decreasing the proton gradient?","options":[{"id":"a","text":"Complex I"},{"id":"b","text":"Complex II"},{"id":"c","text":"Complex III"},{"id":"d","text":"Complex IV"}],"answerId":"d","explanation":"Inhibition of Complex IV would prevent electrons from reaching oxygen, halting the proton gradient and ATP synthesis.","kind":"clinical","origin":"ai"},{"id":"electron-transport-oxphos~ai-4","moduleId":"electron-transport-oxphos","stem":"Which statement about electron carriers is true?","options":[{"id":"a","text":"CoQ pumps protons"},{"id":"b","text":"Cytochrome c pumps protons"},{"id":"c","text":"CoQ and cytochrome c are mobile carriers"},{"id":"d","text":"Complexes I, III, and IV are mobile carriers"}],"answerId":"c","explanation":"CoQ and cytochrome c are mobile electron carriers, while complexes I, III, and IV are the proton pumps.","kind":"trap","origin":"ai"},{"id":"electron-transport-oxphos~ai-5","moduleId":"electron-transport-oxphos","stem":"How does uncoupling affect ATP synthesis?","options":[{"id":"a","text":"Increases ATP production"},{"id":"b","text":"Decreases proton gradient"},{"id":"c","text":"Increases electron transport"},{"id":"d","text":"Decreases oxygen consumption"}],"answerId":"b","explanation":"Uncoupling dissipates the proton gradient, reducing ATP synthesis despite continued electron transport.","kind":"mechanism","origin":"ai"},{"id":"electron-transport-oxphos~ai-6","moduleId":"electron-transport-oxphos","stem":"How does the P/O ratio relate to ATP production from NADH and FADH₂?","options":[{"id":"a","text":"Both have the same P/O ratio"},{"id":"b","text":"NADH has a higher P/O ratio"},{"id":"c","text":"FADH₂ has a higher P/O ratio"},{"id":"d","text":"P/O ratio is irrelevant"}],"answerId":"b","explanation":"NADH has a higher P/O ratio than FADH₂ because it contributes to more proton pumping.","kind":"integration","linkedModuleIds":["etc-inhibitors-uncoupling-shuttles"],"origin":"ai"},{"id":"electron-transport-oxphos~ai-7","moduleId":"electron-transport-oxphos","stem":"What is the effect of NADH shuttles on ATP yield?","options":[{"id":"a","text":"Increase ATP yield"},{"id":"b","text":"Decrease ATP yield"},{"id":"c","text":"No effect on ATP yield"},{"id":"d","text":"Only affect FADH₂ yield"}],"answerId":"b","explanation":"NADH shuttles can decrease the overall ATP yield due to the bypassing of complex I.","kind":"integration","linkedModuleIds":["free-energy-atp-coupling"],"origin":"ai"}],"free-energy-atp-coupling":[{"id":"free-energy-atp-coupling~ai-0","moduleId":"free-energy-atp-coupling","stem":"What is the sign of ΔG for a spontaneous reaction?","options":[{"id":"a","text":"Negative"},{"id":"b","text":"Positive"},{"id":"c","text":"Zero"},{"id":"d","text":"Undefined"}],"answerId":"a","explanation":"A spontaneous reaction is characterized by a negative ΔG, indicating it can proceed without external energy input.","kind":"recall","origin":"ai"},{"id":"free-energy-atp-coupling~ai-1","moduleId":"free-energy-atp-coupling","stem":"How does ATP hydrolysis drive unfavorable reactions?","options":[{"id":"a","text":"By increasing the activation energy"},{"id":"b","text":"By coupling to an exergonic reaction"},{"id":"c","text":"By decreasing product concentration"},{"id":"d","text":"By shifting equilibrium to the right"}],"answerId":"b","explanation":"ATP hydrolysis has a strongly negative ΔG and can couple with endergonic reactions to drive them forward.","kind":"mechanism","origin":"ai"},{"id":"free-energy-atp-coupling~ai-2","moduleId":"free-energy-atp-coupling","stem":"Which of the following statements is true regarding ΔG?","options":[{"id":"a","text":"ΔG indicates reaction speed"},{"id":"b","text":"ΔG = 0 means the reaction is fast"},{"id":"c","text":"ΔG < 0 means the reaction is thermodynamically favorable"},{"id":"d","text":"ΔG > 0 guarantees product formation"}],"answerId":"c","explanation":"A negative ΔG indicates that a reaction is thermodynamically favorable, but does not provide information about the speed of the reaction.","kind":"trap","origin":"ai"},{"id":"free-energy-atp-coupling~ai-3","moduleId":"free-energy-atp-coupling","stem":"What occurs at equilibrium in a chemical reaction?","options":[{"id":"a","text":"ΔG is negative"},{"id":"b","text":"Forward and reverse reactions are equal"},{"id":"c","text":"Reactants are completely converted to products"},{"id":"d","text":"The reaction stops completely"}],"answerId":"b","explanation":"At equilibrium, the rates of the forward and reverse reactions are equal, resulting in ΔG = 0.","kind":"clinical","origin":"ai"},{"id":"free-energy-atp-coupling~ai-4","moduleId":"free-energy-atp-coupling","stem":"Which process primarily produces ATP during intense exercise?","options":[{"id":"a","text":"Oxidative phosphorylation"},{"id":"b","text":"Substrate-level phosphorylation"},{"id":"c","text":"Fermentation"},{"id":"d","text":"Photosynthesis"}],"answerId":"b","explanation":"During intense exercise, substrate-level phosphorylation is a key process for rapid ATP production.","kind":"recall","origin":"ai"},{"id":"free-energy-atp-coupling~ai-5","moduleId":"free-energy-atp-coupling","stem":"How does ATP hydrolysis relate to the electron transport chain?","options":[{"id":"a","text":"It directly powers the ETC"},{"id":"b","text":"It provides energy for proton pumping"},{"id":"c","text":"It is a product of the ETC"},{"id":"d","text":"It inhibits the ETC"}],"answerId":"b","explanation":"ATP hydrolysis provides energy that can be used to drive processes, including the proton pumping in the electron transport chain.","kind":"integration","linkedModuleIds":["electron-transport-oxphos"],"origin":"ai"},{"id":"free-energy-atp-coupling~ai-6","moduleId":"free-energy-atp-coupling","stem":"In the context of atrial fibrillation, how does ATP play a role in cardiac muscle function?","options":[{"id":"a","text":"It decreases heart rate"},{"id":"b","text":"It provides energy for contraction"},{"id":"c","text":"It inhibits electrical conduction"},{"id":"d","text":"It promotes arrhythmias directly"}],"answerId":"b","explanation":"ATP is essential for cardiac muscle contraction, providing the energy necessary for the heart to function effectively.","kind":"integration","linkedModuleIds":["atrial-fibrillation"],"origin":"ai"}],"glycogen-synthesis-breakdown":[{"id":"glycogen-synthesis-breakdown~ai-0","moduleId":"glycogen-synthesis-breakdown","stem":"What enzyme is responsible for adding glucose units to the growing glycogen chain?","options":[{"id":"a","text":"Glycogen phosphorylase"},{"id":"b","text":"Glycogen synthase"},{"id":"c","text":"Branching enzyme"},{"id":"d","text":"Debranching enzyme"}],"answerId":"b","explanation":"Glycogen synthase extends α-1,4 chains using UDP-glucose.","kind":"recall","origin":"ai"},{"id":"glycogen-synthesis-breakdown~ai-1","moduleId":"glycogen-synthesis-breakdown","stem":"Which hormone promotes glycogen synthesis in the liver?","options":[{"id":"a","text":"Glucagon"},{"id":"b","text":"Epinephrine"},{"id":"c","text":"Insulin"},{"id":"d","text":"Cortisol"}],"answerId":"c","explanation":"Insulin favors dephosphorylation, activating glycogen synthase.","kind":"mechanism","origin":"ai"},{"id":"glycogen-synthesis-breakdown~ai-2","moduleId":"glycogen-synthesis-breakdown","stem":"A patient presents with exercise intolerance and muscle cramps but no rise in lactate during exercise. What is the likely diagnosis?","options":[{"id":"a","text":"Glycogen synthase deficiency"},{"id":"b","text":"McArdle disease"},{"id":"c","text":"Cori disease"},{"id":"d","text":"Von Gierke disease"}],"answerId":"b","explanation":"This presentation is characteristic of muscle glycogen phosphorylase deficiency (McArdle disease).","kind":"clinical","origin":"ai"},{"id":"glycogen-synthesis-breakdown~ai-3","moduleId":"glycogen-synthesis-breakdown","stem":"Which of the following statements about muscle glycogen is true?","options":[{"id":"a","text":"It directly raises blood glucose levels."},{"id":"b","text":"It is converted to free glucose by glucose-6-phosphatase."},{"id":"c","text":"It supplies ATP for local muscle activity."},{"id":"d","text":"It is stored for long-term energy needs."}],"answerId":"c","explanation":"Muscle glycogen is primarily used for local glycolysis and does not directly raise blood glucose.","kind":"trap","origin":"ai"},{"id":"glycogen-synthesis-breakdown~ai-4","moduleId":"glycogen-synthesis-breakdown","stem":"What is the primary role of glycogen phosphorylase in glycogen metabolism?","options":[{"id":"a","text":"To synthesize glycogen from glucose"},{"id":"b","text":"To cleave α-1,4 bonds in glycogen"},{"id":"c","text":"To create α-1,6 branches"},{"id":"d","text":"To release free glucose from glycogen"}],"answerId":"b","explanation":"Glycogen phosphorylase cleaves α-1,4 bonds, releasing glucose-1-phosphate.","kind":"mechanism","origin":"ai"},{"id":"glycogen-synthesis-breakdown~ai-5","moduleId":"glycogen-synthesis-breakdown","stem":"How does glucagon affect glycogen metabolism in the liver?","options":[{"id":"a","text":"Increases glycogen synthesis"},{"id":"b","text":"Inhibits glycogen breakdown"},{"id":"c","text":"Stimulates glycogen breakdown"},{"id":"d","text":"Has no effect on glycogen metabolism"}],"answerId":"c","explanation":"Glucagon stimulates glycogen breakdown to increase blood glucose levels.","kind":"mechanism","origin":"ai"},{"id":"glycogen-synthesis-breakdown~ai-6","moduleId":"glycogen-synthesis-breakdown","stem":"How does the regulation of glycogen metabolism relate to blood glucose homeostasis?","options":[{"id":"a","text":"Glycogen synthesis is independent of insulin"},{"id":"b","text":"Muscle glycogen can release glucose to the bloodstream"},{"id":"c","text":"Liver glycogen helps maintain blood glucose levels during fasting"},{"id":"d","text":"Insulin inhibits glycogen breakdown in muscle only"}],"answerId":"c","explanation":"Liver glycogen buffers blood glucose between meals by releasing free glucose.","kind":"integration","linkedModuleIds":["blood-glucose-homeostasis"],"origin":"ai"},{"id":"glycogen-synthesis-breakdown~ai-7","moduleId":"glycogen-synthesis-breakdown","stem":"What is the relationship between glycogen metabolism and hormonal control of volume and water balance?","options":[{"id":"a","text":"Both processes are regulated by insulin"},{"id":"b","text":"Glycogen breakdown affects blood volume directly"},{"id":"c","text":"Hormones like glucagon and epinephrine influence both systems"},{"id":"d","text":"Glycogen synthesis is unrelated to water balance"}],"answerId":"c","explanation":"Hormones like glucagon and epinephrine play roles in both glycogen metabolism and water balance regulation.","kind":"integration","linkedModuleIds":["volume-water-balance-hormones"],"origin":"ai"}],"glucose-transport-glycolysis":[{"id":"glucose-transport-glycolysis~ai-0","moduleId":"glucose-transport-glycolysis","stem":"Which glucose transporter is primarily responsible for glucose uptake in skeletal muscle and adipose tissue in response to insulin?","options":[{"id":"a","text":"GLUT1"},{"id":"b","text":"GLUT2"},{"id":"c","text":"GLUT3"},{"id":"d","text":"GLUT4"}],"answerId":"d","explanation":"GLUT4 is the insulin-responsive glucose transporter that facilitates glucose uptake in skeletal muscle and adipose tissue.","kind":"recall","origin":"ai"},{"id":"glucose-transport-glycolysis~ai-1","moduleId":"glucose-transport-glycolysis","stem":"What is the primary product of glycolysis under anaerobic conditions?","options":[{"id":"a","text":"Acetyl-CoA"},{"id":"b","text":"Lactate"},{"id":"c","text":"Pyruvate"},{"id":"d","text":"Glucose"}],"answerId":"b","explanation":"Under anaerobic conditions, glycolysis converts glucose to lactate, regenerating NAD⁺ for continued glycolysis.","kind":"recall","origin":"ai"},{"id":"glucose-transport-glycolysis~ai-2","moduleId":"glucose-transport-glycolysis","stem":"Which enzyme is the rate-limiting step in glycolysis?","options":[{"id":"a","text":"Hexokinase"},{"id":"b","text":"Phosphofructokinase-1"},{"id":"c","text":"Pyruvate kinase"},{"id":"d","text":"Lactate dehydrogenase"}],"answerId":"b","explanation":"Phosphofructokinase-1 (PFK-1) is the committed, rate-limiting enzyme in glycolysis.","kind":"recall","origin":"ai"},{"id":"glucose-transport-glycolysis~ai-3","moduleId":"glucose-transport-glycolysis","stem":"In the liver, what effect does glucagon have on glycolysis?","options":[{"id":"a","text":"Increases F-2,6-BP"},{"id":"b","text":"Inhibits PFK-1"},{"id":"c","text":"Stimulates pyruvate kinase"},{"id":"d","text":"Promotes lactate formation"}],"answerId":"b","explanation":"Glucagon lowers F-2,6-BP, which inhibits PFK-1 and suppresses glycolysis in the liver.","kind":"mechanism","origin":"ai"},{"id":"glucose-transport-glycolysis~ai-4","moduleId":"glucose-transport-glycolysis","stem":"A patient presents with muscle fatigue and elevated lactate levels during exercise. Which mechanism explains this finding?","options":[{"id":"a","text":"Increased mitochondrial activity"},{"id":"b","text":"Decreased glucose uptake"},{"id":"c","text":"Anaerobic glycolysis predominance"},{"id":"d","text":"Enhanced fatty acid oxidation"}],"answerId":"c","explanation":"Elevated lactate levels during exercise indicate that anaerobic glycolysis is predominating due to insufficient oxygen supply.","kind":"clinical","origin":"ai"},{"id":"glucose-transport-glycolysis~ai-5","moduleId":"glucose-transport-glycolysis","stem":"Which statement correctly describes the role of insulin in glucose uptake?","options":[{"id":"a","text":"Insulin is required for glucose uptake into every tissue."},{"id":"b","text":"Insulin recruits GLUT4 in muscle and adipose tissues only."},{"id":"c","text":"Insulin stimulates GLUT1 in neurons."},{"id":"d","text":"Insulin enhances glucose uptake in RBCs."}],"answerId":"b","explanation":"Insulin chiefly recruits GLUT4 in skeletal muscle and adipose; brain and RBCs utilize insulin-independent GLUTs.","kind":"trap","origin":"ai"},{"id":"glucose-transport-glycolysis~ai-6","moduleId":"glucose-transport-glycolysis","stem":"How does glucose metabolism in skeletal muscle during exercise relate to energy systems?","options":[{"id":"a","text":"It relies solely on aerobic respiration."},{"id":"b","text":"It uses anaerobic glycolysis for quick energy."},{"id":"c","text":"It does not utilize glucose."},{"id":"d","text":"It primarily depends on fatty acid oxidation."}],"answerId":"b","explanation":"During intense exercise, skeletal muscle primarily uses anaerobic glycolysis for rapid ATP production from glucose.","kind":"integration","linkedModuleIds":["muscle-energy-systems"],"origin":"ai"},{"id":"glucose-transport-glycolysis~ai-7","moduleId":"glucose-transport-glycolysis","stem":"What is the role of lactate in glucose homeostasis during intense exercise?","options":[{"id":"a","text":"It inhibits glycolysis."},{"id":"b","text":"It serves as a substrate for gluconeogenesis."},{"id":"c","text":"It decreases insulin sensitivity."},{"id":"d","text":"It promotes fatty acid oxidation."}],"answerId":"b","explanation":"Lactate can be converted back to glucose in the liver via gluconeogenesis, helping to maintain blood glucose levels during intense exercise.","kind":"integration","linkedModuleIds":["gluconeogenesis-cori-alanine"],"origin":"ai"}],"malabsorption-patterns":[{"id":"malabsorption-patterns~ai-0","moduleId":"malabsorption-patterns","stem":"What is the primary cause of steatorrhea in pancreatic insufficiency?","options":[{"id":"a","text":"Inadequate bile salts"},{"id":"b","text":"Defective enterocyte transport"},{"id":"c","text":"Insufficient pancreatic enzymes"},{"id":"d","text":"Intestinal mucosal injury"}],"answerId":"c","explanation":"Steatorrhea occurs due to the inability to properly digest fats, primarily caused by insufficient pancreatic enzymes.","kind":"recall","origin":"ai"},{"id":"malabsorption-patterns~ai-1","moduleId":"malabsorption-patterns","stem":"Which vitamin deficiency is most likely in a patient with fat malabsorption?","options":[{"id":"a","text":"Vitamin A"},{"id":"b","text":"Vitamin B12"},{"id":"c","text":"Vitamin C"},{"id":"d","text":"Vitamin K"}],"answerId":"d","explanation":"Fat malabsorption leads to the loss of fat-soluble vitamins, including vitamin K, which is essential for coagulation.","kind":"recall","origin":"ai"},{"id":"malabsorption-patterns~ai-2","moduleId":"malabsorption-patterns","stem":"A patient presents with watery, acidic diarrhea after consuming lactose. What is the most likely underlying issue?","options":[{"id":"a","text":"Pancreatic insufficiency"},{"id":"b","text":"Bacterial overgrowth"},{"id":"c","text":"Lactase deficiency"},{"id":"d","text":"Celiac disease"}],"answerId":"c","explanation":"The symptoms indicate a selective carbohydrate malabsorption due to lactase deficiency, leading to fermentation and gas production.","kind":"clinical","origin":"ai"},{"id":"malabsorption-patterns~ai-3","moduleId":"malabsorption-patterns","stem":"In a patient with chronic diarrhea and weight loss, which finding would suggest diffuse enteritis rather than a selective transporter defect?","options":[{"id":"a","text":"Isolated vitamin B12 deficiency"},{"id":"b","text":"Multiple nutrient deficiencies"},{"id":"c","text":"Normal stool fat content"},{"id":"d","text":"Localized abdominal pain"}],"answerId":"b","explanation":"Diffuse enteritis typically results in multiple nutrient deficiencies due to widespread damage to the intestinal mucosa.","kind":"clinical","origin":"ai"},{"id":"malabsorption-patterns~ai-4","moduleId":"malabsorption-patterns","stem":"Which of the following mechanisms best explains the pathophysiology of malabsorption in celiac disease?","options":[{"id":"a","text":"Inadequate bile salts"},{"id":"b","text":"Intestinal mucosal injury"},{"id":"c","text":"Pancreatic enzyme deficiency"},{"id":"d","text":"Selective transporter defect"}],"answerId":"b","explanation":"Celiac disease causes injury to the intestinal mucosa, leading to malabsorption of multiple nutrients.","kind":"mechanism","origin":"ai"},{"id":"malabsorption-patterns~ai-5","moduleId":"malabsorption-patterns","stem":"How does pancreatic insufficiency differ from malabsorption in terms of nutrient failure?","options":[{"id":"a","text":"Both involve enterocyte transporter defects"},{"id":"b","text":"Pancreatic failure prevents luminal digestion"},{"id":"c","text":"Only malabsorption affects fat-soluble vitamins"},{"id":"d","text":"Pancreatic insufficiency is reversible"}],"answerId":"b","explanation":"Pancreatic insufficiency leads to maldigestion, preventing nutrients from reaching the absorptive transporters in the intestine.","kind":"trap","origin":"ai"},{"id":"malabsorption-patterns~ai-6","moduleId":"malabsorption-patterns","stem":"In a patient with suspected malabsorption, which test would most directly assess pancreatic function?","options":[{"id":"a","text":"Stool fat analysis"},{"id":"b","text":"Serum vitamin levels"},{"id":"c","text":"Lactose tolerance test"},{"id":"d","text":"Fecal elastase test"}],"answerId":"d","explanation":"Fecal elastase test measures pancreatic enzyme output and is a direct indicator of pancreatic function.","kind":"integration","linkedModuleIds":["gastric-enzymes-intrinsic-barrier"],"origin":"ai"},{"id":"malabsorption-patterns~ai-7","moduleId":"malabsorption-patterns","stem":"Which condition is most likely to cause both fat and carbohydrate malabsorption?","options":[{"id":"a","text":"Celiac disease"},{"id":"b","text":"Chronic pancreatitis"},{"id":"c","text":"Lactose intolerance"},{"id":"d","text":"Irritable bowel syndrome"}],"answerId":"b","explanation":"Chronic pancreatitis leads to insufficient production of enzymes necessary for the digestion of both fats and carbohydrates.","kind":"integration","linkedModuleIds":["lipid-digestion-chylomicrons"],"origin":"ai"}],"protein-digestion-amino-acid-absorption":[{"id":"protein-digestion-amino-acid-absorption~ai-0","moduleId":"protein-digestion-amino-acid-absorption","stem":"What is the primary function of gastric acid in protein digestion?","options":[{"id":"a","text":"Activates pancreatic zymogens"},{"id":"b","text":"Denatures proteins"},{"id":"c","text":"Hydrolyzes peptide bonds"},{"id":"d","text":"Stimulates bile secretion"}],"answerId":"b","explanation":"Gastric acid denatures proteins, making them more accessible to enzymatic digestion.","kind":"recall","origin":"ai"},{"id":"protein-digestion-amino-acid-absorption~ai-1","moduleId":"protein-digestion-amino-acid-absorption","stem":"Which enzyme is activated by enteropeptidase in the small intestine?","options":[{"id":"a","text":"Pepsin"},{"id":"b","text":"Chymotrypsin"},{"id":"c","text":"Trypsin"},{"id":"d","text":"Carboxypeptidase"}],"answerId":"c","explanation":"Enteropeptidase activates trypsinogen to trypsin, initiating the activation cascade of pancreatic zymogens.","kind":"recall","origin":"ai"},{"id":"protein-digestion-amino-acid-absorption~ai-2","moduleId":"protein-digestion-amino-acid-absorption","stem":"A patient presents with protein maldigestion due to pancreatic insufficiency. What is the underlying mechanism?","options":[{"id":"a","text":"Increased gastric acid secretion"},{"id":"b","text":"Reduced delivery of proteases"},{"id":"c","text":"Defective amino acid transport"},{"id":"d","text":"Excessive intestinal motility"}],"answerId":"b","explanation":"Pancreatic insufficiency leads to reduced delivery of proteases and other digestive enzymes necessary for protein digestion.","kind":"mechanism","origin":"ai"},{"id":"protein-digestion-amino-acid-absorption~ai-3","moduleId":"protein-digestion-amino-acid-absorption","stem":"Which transporter is primarily responsible for the absorption of di- and tripeptides in the intestine?","options":[{"id":"a","text":"Na⁺-dependent carrier"},{"id":"b","text":"H⁺-dependent PepT1"},{"id":"c","text":"Facilitated diffusion"},{"id":"d","text":"Lipid transporter"}],"answerId":"b","explanation":"Di- and tripeptides are absorbed through the H⁺-dependent PepT1 transporter in the brush border of enterocytes.","kind":"recall","origin":"ai"},{"id":"protein-digestion-amino-acid-absorption~ai-4","moduleId":"protein-digestion-amino-acid-absorption","stem":"A patient with Hartnup disorder presents with neutral aminoaciduria. What is the underlying defect?","options":[{"id":"a","text":"Defective enteropeptidase"},{"id":"b","text":"Impaired pancreatic enzyme secretion"},{"id":"c","text":"Defective neutral amino acid transporter"},{"id":"d","text":"Increased intestinal absorption"}],"answerId":"c","explanation":"Hartnup disorder is caused by a defect in the neutral amino acid transporter, leading to aminoaciduria.","kind":"recall","origin":"ai"},{"id":"protein-digestion-amino-acid-absorption~ai-5","moduleId":"protein-digestion-amino-acid-absorption","stem":"In a patient with protein maldigestion, which finding would most likely be observed on urinalysis?","options":[{"id":"a","text":"Ketones"},{"id":"b","text":"Glucose"},{"id":"c","text":"Neutral amino acids"},{"id":"d","text":"Fatty acids"}],"answerId":"c","explanation":"Neutral aminoaciduria occurs due to defects in amino acid transport, as seen in conditions like Hartnup disorder.","kind":"recall","origin":"ai"},{"id":"protein-digestion-amino-acid-absorption~ai-6","moduleId":"protein-digestion-amino-acid-absorption","stem":"How does the mechanism of protein absorption differ from that of carbohydrates?","options":[{"id":"a","text":"Both use Na⁺-dependent carriers"},{"id":"b","text":"Proteins are absorbed as whole molecules"},{"id":"c","text":"Carbohydrates are absorbed as monosaccharides"},{"id":"d","text":"Proteins require bile salts for absorption"}],"answerId":"c","explanation":"Carbohydrates are absorbed as monosaccharides, while proteins are absorbed as free amino acids or small peptides.","kind":"integration","linkedModuleIds":["carbohydrate-digestion-absorption"],"origin":"ai"},{"id":"protein-digestion-amino-acid-absorption~ai-7","moduleId":"protein-digestion-amino-acid-absorption","stem":"What is a common clinical finding in patients with lipid malabsorption compared to protein malabsorption?","options":[{"id":"a","text":"Weight loss"},{"id":"b","text":"Fatty stools"},{"id":"c","text":"Edema"},{"id":"d","text":"Anemia"}],"answerId":"b","explanation":"Fatty stools (steatorrhea) are characteristic of lipid malabsorption, whereas protein malabsorption may lead to different findings.","kind":"integration","linkedModuleIds":["lipid-digestion-chylomicrons"],"origin":"ai"}],"tca-amphibolic-anaplerosis":[{"id":"tca-amphibolic-anaplerosis~ai-0","moduleId":"tca-amphibolic-anaplerosis","stem":"Which of the following is a primary function of the TCA cycle?","options":[{"id":"a","text":"Synthesis of glucose"},{"id":"b","text":"Oxidation of fatty acids"},{"id":"c","text":"Oxidation of acetyl-CoA for energy"},{"id":"d","text":"Production of lactate"}],"answerId":"c","explanation":"The TCA cycle primarily oxidizes acetyl-CoA to generate energy in the form of ATP.","kind":"recall","origin":"ai"},{"id":"tca-amphibolic-anaplerosis~ai-1","moduleId":"tca-amphibolic-anaplerosis","stem":"What is the role of pyruvate carboxylase in the TCA cycle?","options":[{"id":"a","text":"Converts pyruvate to acetyl-CoA"},{"id":"b","text":"Converts pyruvate to oxaloacetate"},{"id":"c","text":"Converts oxaloacetate to citrate"},{"id":"d","text":"Converts citrate to isocitrate"}],"answerId":"b","explanation":"Pyruvate carboxylase catalyzes the conversion of pyruvate to oxaloacetate, which is crucial for TCA cycle function.","kind":"mechanism","origin":"ai"},{"id":"tca-amphibolic-anaplerosis~ai-2","moduleId":"tca-amphibolic-anaplerosis","stem":"A patient presents with biotin deficiency. Which metabolic process is most likely impaired?","options":[{"id":"a","text":"Glycolysis"},{"id":"b","text":"Anaplerosis"},{"id":"c","text":"Beta-oxidation"},{"id":"d","text":"Gluconeogenesis"}],"answerId":"b","explanation":"Biotin is a cofactor for pyruvate carboxylase, which is essential for anaplerosis in the TCA cycle.","kind":"clinical","origin":"ai"},{"id":"tca-amphibolic-anaplerosis~ai-3","moduleId":"tca-amphibolic-anaplerosis","stem":"Which statement about acetyl-CoA in the TCA cycle is correct?","options":[{"id":"a","text":"Abundant acetyl-CoA guarantees rapid TCA oxidation"},{"id":"b","text":"Acetyl-CoA can only enter the TCA cycle in the presence of oxaloacetate"},{"id":"c","text":"Acetyl-CoA is produced exclusively from glucose"},{"id":"d","text":"Acetyl-CoA is not involved in gluconeogenesis"}],"answerId":"b","explanation":"Acetyl-CoA requires sufficient oxaloacetate and other intermediates for effective oxidation in the TCA cycle.","kind":"trap","origin":"ai"},{"id":"tca-amphibolic-anaplerosis~ai-4","moduleId":"tca-amphibolic-anaplerosis","stem":"Which TCA cycle intermediate is primarily involved in amino acid synthesis?","options":[{"id":"a","text":"Citrate"},{"id":"b","text":"Succinyl-CoA"},{"id":"c","text":"α-Ketoglutarate"},{"id":"d","text":"Malate"}],"answerId":"c","explanation":"α-Ketoglutarate is a key intermediate that serves as a precursor for several amino acids.","kind":"recall","origin":"ai"},{"id":"tca-amphibolic-anaplerosis~ai-5","moduleId":"tca-amphibolic-anaplerosis","stem":"How does high acetyl-CoA concentration affect pyruvate carboxylase activity?","options":[{"id":"a","text":"Inhibits it"},{"id":"b","text":"Activates it"},{"id":"c","text":"Has no effect"},{"id":"d","text":"Decreases its substrate availability"}],"answerId":"b","explanation":"High levels of acetyl-CoA activate pyruvate carboxylase to produce oxaloacetate, supporting TCA cycle flux.","kind":"mechanism","origin":"ai"},{"id":"tca-amphibolic-anaplerosis~ai-6","moduleId":"tca-amphibolic-anaplerosis","stem":"Which process is directly linked to the TCA cycle through pyruvate dehydrogenase?","options":[{"id":"a","text":"Glycogenesis"},{"id":"b","text":"Lipid synthesis"},{"id":"c","text":"Conversion of pyruvate to acetyl-CoA"},{"id":"d","text":"Urea cycle"}],"answerId":"c","explanation":"Pyruvate dehydrogenase converts pyruvate into acetyl-CoA, linking glycolysis to the TCA cycle.","kind":"integration","linkedModuleIds":["pdh-tca-cycle"],"origin":"ai"},{"id":"tca-amphibolic-anaplerosis~ai-7","moduleId":"tca-amphibolic-anaplerosis","stem":"What is the consequence of oxaloacetate withdrawal during fasting?","options":[{"id":"a","text":"Increased TCA cycle activity"},{"id":"b","text":"Increased ketogenesis"},{"id":"c","text":"Decreased fatty acid synthesis"},{"id":"d","text":"Decreased gluconeogenesis"}],"answerId":"b","explanation":"Withdrawal of oxaloacetate for gluconeogenesis diverts acetyl-CoA towards ketogenesis during fasting.","kind":"integration","linkedModuleIds":["pdh-tca-cycle"],"origin":"ai"}],"carbohydrate-digestion-absorption":[{"id":"carbohydrate-digestion-absorption~ai-0","moduleId":"carbohydrate-digestion-absorption","stem":"Which enzyme is primarily responsible for the initial digestion of starch in the mouth?","options":[{"id":"a","text":"Salivary amylase"},{"id":"b","text":"Pancreatic amylase"},{"id":"c","text":"Lactase"},{"id":"d","text":"Maltase"}],"answerId":"a","explanation":"Salivary amylase initiates starch digestion by cleaving α-1,4 bonds.","kind":"recall","origin":"ai"},{"id":"carbohydrate-digestion-absorption~ai-1","moduleId":"carbohydrate-digestion-absorption","stem":"What is the role of SGLT1 in monosaccharide absorption?","options":[{"id":"a","text":"Facilitates passive diffusion of glucose"},{"id":"b","text":"Cotransports glucose with Na⁺"},{"id":"c","text":"Exports fructose out of the cell"},{"id":"d","text":"Hydrolyzes disaccharides into monosaccharides"}],"answerId":"b","explanation":"SGLT1 cotransports glucose and galactose with sodium ions across the intestinal apical membrane.","kind":"mechanism","origin":"ai"},{"id":"carbohydrate-digestion-absorption~ai-2","moduleId":"carbohydrate-digestion-absorption","stem":"A patient presents with watery diarrhea and bloating after consuming dairy products. What is the most likely underlying cause?","options":[{"id":"a","text":"Lactase deficiency"},{"id":"b","text":"Celiac disease"},{"id":"c","text":"Fructose malabsorption"},{"id":"d","text":"Cholecystitis"}],"answerId":"a","explanation":"Lactase deficiency leads to unabsorbed lactose in the lumen, causing osmotic diarrhea and fermentation.","kind":"clinical","origin":"ai"},{"id":"carbohydrate-digestion-absorption~ai-3","moduleId":"carbohydrate-digestion-absorption","stem":"Which of the following statements about monosaccharide transport is true?","options":[{"id":"a","text":"Fructose uses SGLT1 for absorption"},{"id":"b","text":"Glucose and galactose exit the cell via GLUT5"},{"id":"c","text":"All monosaccharides are absorbed via GLUT2"},{"id":"d","text":"Fructose is absorbed via GLUT5"}],"answerId":"d","explanation":"Fructose is specifically absorbed via the apical transporter GLUT5, while glucose and galactose use SGLT1.","kind":"trap","origin":"ai"},{"id":"carbohydrate-digestion-absorption~ai-4","moduleId":"carbohydrate-digestion-absorption","stem":"After consuming a glucose-galactose solution, a patient shows improvement in dehydration. What mechanism explains this?","options":[{"id":"a","text":"Increased GLUT2 activity"},{"id":"b","text":"SGLT1-mediated water absorption"},{"id":"c","text":"Enhanced pancreatic amylase secretion"},{"id":"d","text":"Inhibition of lactase activity"}],"answerId":"b","explanation":"The intact Na⁺-glucose cotransport via SGLT1 drives water absorption, improving dehydration.","kind":"clinical","origin":"ai"},{"id":"carbohydrate-digestion-absorption~ai-5","moduleId":"carbohydrate-digestion-absorption","stem":"How does the Na⁺/K⁺-ATPase contribute to carbohydrate absorption?","options":[{"id":"a","text":"Facilitates glucose diffusion"},{"id":"b","text":"Maintains Na⁺ gradient for SGLT1"},{"id":"c","text":"Directly transports monosaccharides"},{"id":"d","text":"Inhibits lactase activity"}],"answerId":"b","explanation":"The Na⁺/K⁺-ATPase maintains the sodium gradient essential for SGLT1 function.","kind":"mechanism","origin":"ai"},{"id":"carbohydrate-digestion-absorption~ai-6","moduleId":"carbohydrate-digestion-absorption","stem":"A patient with malabsorption presents with symptoms after carbohydrate intake. Which linked module could provide insights into their condition?","options":[{"id":"a","text":"Fuel Nutrients & Energy Balance"},{"id":"b","text":"Clinical Patterns of Maldigestion & Malabsorption"},{"id":"c","text":"Carbohydrate Digestion & Monosaccharide Absorption"},{"id":"d","text":"Anatomy of the Digestive System"}],"answerId":"b","explanation":"The Clinical Patterns of Maldigestion & Malabsorption module would help understand the malabsorption symptoms.","kind":"integration","linkedModuleIds":["malabsorption-patterns"],"origin":"ai"},{"id":"carbohydrate-digestion-absorption~ai-7","moduleId":"carbohydrate-digestion-absorption","stem":"Which process is directly affected by lactase deficiency in carbohydrate metabolism?","options":[{"id":"a","text":"Absorption of glucose"},{"id":"b","text":"Digestion of starch"},{"id":"c","text":"Fermentation of lactose"},{"id":"d","text":"Transport of fructose"}],"answerId":"c","explanation":"Lactase deficiency results in unabsorbed lactose that is fermented by bacteria, leading to gas and diarrhea.","kind":"integration","linkedModuleIds":["hgb-carbohydrate-digestion-absorption"],"origin":"ai"}],"pentose-fructose-galactose":[{"id":"pentose-fructose-galactose~ai-0","moduleId":"pentose-fructose-galactose","stem":"What is the rate-limiting enzyme of the oxidative pentose phosphate pathway?","options":[{"id":"a","text":"Aldolase B"},{"id":"b","text":"Glucose-6-phosphate dehydrogenase"},{"id":"c","text":"Galactose-1-phosphate uridyltransferase"},{"id":"d","text":"Fructokinase"}],"answerId":"b","explanation":"Glucose-6-phosphate dehydrogenase (G6PD) is the rate-limiting enzyme of the oxidative pentose phosphate pathway, producing NADPH.","kind":"recall","origin":"ai"},{"id":"pentose-fructose-galactose~ai-1","moduleId":"pentose-fructose-galactose","stem":"What is the primary consequence of G6PD deficiency in red blood cells?","options":[{"id":"a","text":"Increased glycolysis"},{"id":"b","text":"Decreased NADPH production"},{"id":"c","text":"Increased hemoglobin synthesis"},{"id":"d","text":"Decreased ATP production"}],"answerId":"b","explanation":"G6PD deficiency leads to decreased NADPH production, impairing the ability of RBCs to maintain reduced glutathione, resulting in oxidative damage.","kind":"mechanism","origin":"ai"},{"id":"pentose-fructose-galactose~ai-2","moduleId":"pentose-fructose-galactose","stem":"A patient presents with jaundice and cataracts in infancy. Which enzyme deficiency is most likely responsible?","options":[{"id":"a","text":"Fructokinase"},{"id":"b","text":"Galactose-1-phosphate uridyltransferase"},{"id":"c","text":"Aldolase B"},{"id":"d","text":"Glucose-6-phosphate dehydrogenase"}],"answerId":"b","explanation":"Galactose-1-phosphate uridyltransferase (GALT) deficiency causes classic galactosemia, leading to jaundice and cataracts.","kind":"clinical","origin":"ai"},{"id":"pentose-fructose-galactose~ai-3","moduleId":"pentose-fructose-galactose","stem":"Which finding is characteristic of G6PD deficiency after exposure to oxidative stress?","options":[{"id":"a","text":"Bite cells"},{"id":"b","text":"Microcytic anemia"},{"id":"c","text":"Spherocytes"},{"id":"d","text":"Target cells"}],"answerId":"a","explanation":"Bite cells are formed due to the splenic removal of Heinz bodies in G6PD deficiency after oxidative stress.","kind":"recall","origin":"ai"},{"id":"pentose-fructose-galactose~ai-4","moduleId":"pentose-fructose-galactose","stem":"What is the primary metabolic consequence of aldolase B deficiency?","options":[{"id":"a","text":"Increased fructose-1-phosphate"},{"id":"b","text":"Increased glucose-6-phosphate"},{"id":"c","text":"Decreased lactate production"},{"id":"d","text":"Increased galactose-1-phosphate"}],"answerId":"a","explanation":"Aldolase B deficiency leads to the accumulation of fructose-1-phosphate, causing hypoglycemia.","kind":"mechanism","origin":"ai"},{"id":"pentose-fructose-galactose~ai-5","moduleId":"pentose-fructose-galactose","stem":"Which statement is true regarding fructose metabolism?","options":[{"id":"a","text":"All fructose enzyme defects cause severe fasting hypoglycemia"},{"id":"b","text":"Fructokinase deficiency is benign"},{"id":"c","text":"Aldolase B deficiency is benign"},{"id":"d","text":"Fructose-1-phosphate is converted to glucose"}],"answerId":"b","explanation":"Fructokinase deficiency causes benign essential fructosuria, while aldolase B deficiency is severe due to phosphate trapping.","kind":"trap","origin":"ai"},{"id":"pentose-fructose-galactose~ai-6","moduleId":"pentose-fructose-galactose","stem":"How does G6PD deficiency relate to oxidative hemolysis?","options":[{"id":"a","text":"It causes increased ATP production"},{"id":"b","text":"It leads to decreased NADPH, impairing antioxidant defense"},{"id":"c","text":"It results in increased glycolysis"},{"id":"d","text":"It enhances glutathione synthesis"}],"answerId":"b","explanation":"G6PD deficiency results in decreased NADPH production, impairing the antioxidant defense and leading to oxidative hemolysis.","kind":"integration","linkedModuleIds":["g6pd-oxidative-hemolysis"],"origin":"ai"},{"id":"pentose-fructose-galactose~ai-7","moduleId":"pentose-fructose-galactose","stem":"How does aldolase B deficiency affect blood glucose homeostasis after fruit intake?","options":[{"id":"a","text":"It increases glucose production"},{"id":"b","text":"It leads to hypoglycemia due to phosphate trapping"},{"id":"c","text":"It enhances gluconeogenesis"},{"id":"d","text":"It decreases insulin sensitivity"}],"answerId":"b","explanation":"Aldolase B deficiency traps phosphate as fructose-1-phosphate, leading to hypoglycemia after fruit intake.","kind":"integration","linkedModuleIds":["blood-glucose-homeostasis"],"origin":"ai"}],"blood-glucose-homeostasis":[{"id":"blood-glucose-homeostasis~ai-0","moduleId":"blood-glucose-homeostasis","stem":"What is the primary action of insulin after a meal?","options":[{"id":"a","text":"Increases hepatic glucose output"},{"id":"b","text":"Promotes lipolysis in adipose tissue"},{"id":"c","text":"Stimulates GLUT4 uptake in muscle and adipose tissue"},{"id":"d","text":"Inhibits glycogen synthesis in the liver"}],"answerId":"c","explanation":"Insulin primarily promotes glucose uptake via GLUT4 in muscle and adipose tissue, while also stimulating glycogenesis and lipogenesis.","kind":"recall","origin":"ai"},{"id":"blood-glucose-homeostasis~ai-1","moduleId":"blood-glucose-homeostasis","stem":"Which hormone primarily raises blood glucose during fasting?","options":[{"id":"a","text":"Insulin"},{"id":"b","text":"Cortisol"},{"id":"c","text":"Glucagon"},{"id":"d","text":"Epinephrine"}],"answerId":"c","explanation":"Glucagon is the primary hormone that increases hepatic glucose output during fasting through glycogenolysis and gluconeogenesis.","kind":"recall","origin":"ai"},{"id":"blood-glucose-homeostasis~ai-2","moduleId":"blood-glucose-homeostasis","stem":"What is the mechanism by which epinephrine counter-regulates hypoglycemia?","options":[{"id":"a","text":"Increases insulin secretion"},{"id":"b","text":"Stimulates hepatic glycogenolysis"},{"id":"c","text":"Inhibits gluconeogenesis"},{"id":"d","text":"Promotes glucose uptake in muscle"}],"answerId":"b","explanation":"Epinephrine stimulates hepatic glycogenolysis, thereby increasing blood glucose levels during hypoglycemia.","kind":"mechanism","origin":"ai"},{"id":"blood-glucose-homeostasis~ai-3","moduleId":"blood-glucose-homeostasis","stem":"Which statement about glucagon is correct?","options":[{"id":"a","text":"It directly stimulates skeletal muscle glycogenolysis"},{"id":"b","text":"It primarily acts on liver cells"},{"id":"c","text":"It promotes lipogenesis in adipose tissue"},{"id":"d","text":"It decreases hepatic glucose output"}],"answerId":"b","explanation":"Glucagon primarily acts on liver cells to increase glucose output; it does not directly affect skeletal muscle glycogenolysis.","kind":"trap","origin":"ai"},{"id":"blood-glucose-homeostasis~ai-4","moduleId":"blood-glucose-homeostasis","stem":"What clinical finding is expected during hypoglycemia?","options":[{"id":"a","text":"Increased blood glucose levels"},{"id":"b","text":"Neuroglycopenic symptoms"},{"id":"c","text":"Decreased epinephrine secretion"},{"id":"d","text":"Increased insulin sensitivity"}],"answerId":"b","explanation":"Neuroglycopenic symptoms occur due to a shortage of glucose for brain metabolism during hypoglycemia.","kind":"clinical","origin":"ai"},{"id":"blood-glucose-homeostasis~ai-5","moduleId":"blood-glucose-homeostasis","stem":"How does gluconeogenesis relate to fasting metabolism?","options":[{"id":"a","text":"It is suppressed during fasting"},{"id":"b","text":"It becomes more important as glycogen stores deplete"},{"id":"c","text":"It occurs only in the kidneys"},{"id":"d","text":"It is stimulated by insulin"}],"answerId":"b","explanation":"Gluconeogenesis becomes progressively more important during fasting as glycogen stores are depleted.","kind":"integration","linkedModuleIds":["hen1-glucagon-fasting-metabolism"],"origin":"ai"},{"id":"blood-glucose-homeostasis~ai-6","moduleId":"blood-glucose-homeostasis","stem":"Which process is primarily responsible for postprandial glucose homeostasis?","options":[{"id":"a","text":"Glycogenolysis"},{"id":"b","text":"Gluconeogenesis"},{"id":"c","text":"Insulin-mediated glucose disposal"},{"id":"d","text":"Epinephrine secretion"}],"answerId":"c","explanation":"Insulin-mediated glucose disposal is crucial for returning postprandial glucose levels toward baseline.","kind":"integration","linkedModuleIds":["integrated-meal-response"],"origin":"ai"}],"beta-oxidation-carnitine":[{"id":"beta-oxidation-carnitine~ai-0","moduleId":"beta-oxidation-carnitine","stem":"What is the primary product of one cycle of β-oxidation of a saturated fatty acid?","options":[{"id":"a","text":"Acetyl-CoA"},{"id":"b","text":"Propionyl-CoA"},{"id":"c","text":"Dicarboxylic acids"},{"id":"d","text":"Malonyl-CoA"}],"answerId":"a","explanation":"Each cycle of β-oxidation releases one molecule of acetyl-CoA from the fatty acid chain.","kind":"recall","origin":"ai"},{"id":"beta-oxidation-carnitine~ai-1","moduleId":"beta-oxidation-carnitine","stem":"Which enzyme is inhibited by malonyl-CoA during fatty acid oxidation?","options":[{"id":"a","text":"CPT I"},{"id":"b","text":"CPT II"},{"id":"c","text":"Acyl-CoA synthetase"},{"id":"d","text":"Carnitine translocase"}],"answerId":"a","explanation":"Malonyl-CoA inhibits CPT I, preventing the transport of long-chain fatty acids into the mitochondria.","kind":"mechanism","origin":"ai"},{"id":"beta-oxidation-carnitine~ai-2","moduleId":"beta-oxidation-carnitine","stem":"A child presents with hypoketotic hypoglycemia after fasting. Which condition is most likely?","options":[{"id":"a","text":"MCAD deficiency"},{"id":"b","text":"CPT II deficiency"},{"id":"c","text":"Carnitine deficiency"},{"id":"d","text":"LCHAD deficiency"}],"answerId":"a","explanation":"MCAD deficiency leads to impaired fatty acid oxidation, resulting in hypoketotic hypoglycemia due to lack of acetyl-CoA for ketogenesis.","kind":"clinical","origin":"ai"},{"id":"beta-oxidation-carnitine~ai-3","moduleId":"beta-oxidation-carnitine","stem":"What is a key finding in the urine of a patient with impaired β-oxidation?","options":[{"id":"a","text":"Ketonuria"},{"id":"b","text":"Dicarboxylic aciduria"},{"id":"c","text":"Glucosuria"},{"id":"d","text":"Aminoaciduria"}],"answerId":"b","explanation":"Dicarboxylic aciduria occurs as a compensatory mechanism when β-oxidation is impaired.","kind":"recall","origin":"ai"},{"id":"beta-oxidation-carnitine~ai-4","moduleId":"beta-oxidation-carnitine","stem":"In a fasting state, which metabolic pathway is primarily affected in MCAD deficiency?","options":[{"id":"a","text":"Glycolysis"},{"id":"b","text":"Ketogenesis"},{"id":"c","text":"Gluconeogenesis"},{"id":"d","text":"Citric acid cycle"}],"answerId":"b","explanation":"MCAD deficiency impairs the ability to produce ketones from fatty acids, leading to hypoketotic hypoglycemia.","kind":"trap","origin":"ai"},{"id":"beta-oxidation-carnitine~ai-5","moduleId":"beta-oxidation-carnitine","stem":"How does the metabolism of odd-chain fatty acids differ from even-chain fatty acids?","options":[{"id":"a","text":"They produce more ATP"},{"id":"b","text":"They end as propionyl-CoA"},{"id":"c","text":"They do not enter the mitochondria"},{"id":"d","text":"They are exclusively oxidized in peroxisomes"}],"answerId":"b","explanation":"Odd-chain fatty acids end their metabolism as propionyl-CoA, which can be converted to succinyl-CoA.","kind":"integration","linkedModuleIds":["alternative-fatty-acid-oxidation"],"origin":"ai"},{"id":"beta-oxidation-carnitine~ai-6","moduleId":"beta-oxidation-carnitine","stem":"Which condition would lead to an inability to produce ketones during fasting?","options":[{"id":"a","text":"MCAD deficiency"},{"id":"b","text":"CPT I deficiency"},{"id":"c","text":"Carnitine deficiency"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"All these conditions impair fatty acid oxidation, preventing the production of acetyl-CoA necessary for ketogenesis.","kind":"integration","linkedModuleIds":["ketone-body-metabolism"],"origin":"ai"}],"ketone-body-metabolism":[{"id":"ketone-body-metabolism~ai-0","moduleId":"ketone-body-metabolism","stem":"What is the rate-limiting enzyme in ketogenesis?","options":[{"id":"a","text":"HMG-CoA synthase"},{"id":"b","text":"Acetyl-CoA carboxylase"},{"id":"c","text":"Carnitine acyltransferase"},{"id":"d","text":"β-Hydroxybutyrate dehydrogenase"}],"answerId":"a","explanation":"HMG-CoA synthase is the key enzyme that catalyzes the formation of HMG-CoA from acetyl-CoA in the process of ketogenesis.","kind":"recall","origin":"ai"},{"id":"ketone-body-metabolism~ai-1","moduleId":"ketone-body-metabolism","stem":"Which ketone body predominates in diabetic ketoacidosis (DKA)?","options":[{"id":"a","text":"Acetoacetate"},{"id":"b","text":"Acetone"},{"id":"c","text":"β-Hydroxybutyrate"},{"id":"d","text":"Butyric acid"}],"answerId":"c","explanation":"In DKA, β-hydroxybutyrate predominates due to the high levels of fatty acid oxidation and low insulin.","kind":"recall","origin":"ai"},{"id":"ketone-body-metabolism~ai-2","moduleId":"ketone-body-metabolism","stem":"Why can't the liver utilize its own ketone bodies?","options":[{"id":"a","text":"It lacks the enzymes for ketogenesis"},{"id":"b","text":"It lacks thiophorase"},{"id":"c","text":"It has insufficient oxygen"},{"id":"d","text":"It prefers glucose as fuel"}],"answerId":"b","explanation":"The liver lacks thiophorase, which is necessary for the utilization of ketone bodies, thus it exports them instead.","kind":"mechanism","origin":"ai"},{"id":"ketone-body-metabolism~ai-3","moduleId":"ketone-body-metabolism","stem":"What clinical finding is associated with diabetic ketoacidosis?","options":[{"id":"a","text":"Kussmaul respirations and fruity breath"},{"id":"b","text":"Bradycardia and hypotension"},{"id":"c","text":"Jaundice and ascites"},{"id":"d","text":"Tachycardia and fever"}],"answerId":"a","explanation":"Kussmaul respirations and fruity breath are classic signs of metabolic acidosis in DKA due to the presence of acetone.","kind":"clinical","origin":"ai"},{"id":"ketone-body-metabolism~ai-4","moduleId":"ketone-body-metabolism","stem":"In diabetic ketoacidosis, which urine ketone test is likely to underestimate the severity?","options":[{"id":"a","text":"Acetoacetate"},{"id":"b","text":"β-Hydroxybutyrate"},{"id":"c","text":"Acetone"},{"id":"d","text":"Lactate"}],"answerId":"b","explanation":"The nitroprusside test primarily detects acetoacetate, leading to underestimation of β-hydroxybutyrate in severe DKA.","kind":"trap","origin":"ai"},{"id":"ketone-body-metabolism~ai-5","moduleId":"ketone-body-metabolism","stem":"How does glucagon signaling affect ketogenesis during fasting?","options":[{"id":"a","text":"Inhibits lipolysis"},{"id":"b","text":"Stimulates glycogenesis"},{"id":"c","text":"Promotes lipolysis and ketogenesis"},{"id":"d","text":"Inhibits ketogenesis"}],"answerId":"c","explanation":"Glucagon signaling during fasting promotes lipolysis and ketogenesis, leading to increased ketone body production.","kind":"integration","linkedModuleIds":["hen1-glucagon-fasting-metabolism"],"origin":"ai"},{"id":"ketone-body-metabolism~ai-6","moduleId":"ketone-body-metabolism","stem":"Which process is directly linked to the supply of acetyl-CoA for ketogenesis?","options":[{"id":"a","text":"Glycogenolysis"},{"id":"b","text":"Fatty acid β-oxidation"},{"id":"c","text":"Gluconeogenesis"},{"id":"d","text":"Protein catabolism"}],"answerId":"b","explanation":"Fatty acid β-oxidation provides acetyl-CoA, which is essential for the synthesis of ketone bodies during fasting.","kind":"integration","linkedModuleIds":["beta-oxidation-carnitine"],"origin":"ai"}],"amino-acid-derived-products":[{"id":"amino-acid-derived-products~ai-0","moduleId":"amino-acid-derived-products","stem":"Which amino acid is a precursor for serotonin?","options":[{"id":"a","text":"Tyrosine"},{"id":"b","text":"Tryptophan"},{"id":"c","text":"Glutamate"},{"id":"d","text":"Histidine"}],"answerId":"b","explanation":"Tryptophan is the amino acid that is converted into serotonin.","kind":"recall","origin":"ai"},{"id":"amino-acid-derived-products~ai-1","moduleId":"amino-acid-derived-products","stem":"What is the primary function of glutathione in the body?","options":[{"id":"a","text":"Energy production"},{"id":"b","text":"Detoxification of peroxides"},{"id":"c","text":"Protein synthesis"},{"id":"d","text":"Neurotransmitter synthesis"}],"answerId":"b","explanation":"Glutathione plays a crucial role in detoxifying peroxides, protecting cells from oxidative stress.","kind":"recall","origin":"ai"},{"id":"amino-acid-derived-products~ai-2","moduleId":"amino-acid-derived-products","stem":"Which enzyme is responsible for regenerating reduced glutathione (GSH) from oxidized glutathione (GSSG)?","options":[{"id":"a","text":"Glutathione peroxidase"},{"id":"b","text":"Glutathione reductase"},{"id":"c","text":"NADPH oxidase"},{"id":"d","text":"Catalase"}],"answerId":"b","explanation":"Glutathione reductase uses NADPH to regenerate GSH from GSSG.","kind":"mechanism","origin":"ai"},{"id":"amino-acid-derived-products~ai-3","moduleId":"amino-acid-derived-products","stem":"A patient presents with hemolysis under oxidative stress. Which deficiency is most likely responsible?","options":[{"id":"a","text":"Vitamin C"},{"id":"b","text":"NADPH"},{"id":"c","text":"Glutathione reductase"},{"id":"d","text":"Creatine kinase"}],"answerId":"b","explanation":"A deficiency in NADPH impairs the regeneration of glutathione, leading to hemolysis under oxidative stress.","kind":"clinical","origin":"ai"},{"id":"amino-acid-derived-products~ai-4","moduleId":"amino-acid-derived-products","stem":"What is the primary metabolic fate of creatine in the body?","options":[{"id":"a","text":"Conversion to ATP"},{"id":"b","text":"Formation of creatinine"},{"id":"c","text":"Synthesis of neurotransmitters"},{"id":"d","text":"Degradation to urea"}],"answerId":"b","explanation":"Creatine spontaneously cyclizes to form creatinine, which is a marker of muscle mass and renal function.","kind":"recall","origin":"ai"},{"id":"amino-acid-derived-products~ai-5","moduleId":"amino-acid-derived-products","stem":"How does N-acetylcysteine (NAC) help in cases of acetaminophen overdose?","options":[{"id":"a","text":"It directly detoxifies acetaminophen"},{"id":"b","text":"It replenishes glutathione stores"},{"id":"c","text":"It enhances renal clearance"},{"id":"d","text":"It inhibits cytochrome P450 enzymes"}],"answerId":"b","explanation":"N-acetylcysteine replenishes glutathione stores, which are depleted in acetaminophen overdose, allowing for detoxification.","kind":"integration","linkedModuleIds":["napqi-glutathione-nac"],"origin":"ai"},{"id":"amino-acid-derived-products~ai-6","moduleId":"amino-acid-derived-products","stem":"Which amino acid-derived product is synthesized from glycine and arginine?","options":[{"id":"a","text":"Serotonin"},{"id":"b","text":"Creatine"},{"id":"c","text":"Histamine"},{"id":"d","text":"Dopamine"}],"answerId":"b","explanation":"Creatine is synthesized from glycine and arginine, highlighting the role of amino acids in energy metabolism.","kind":"integration","linkedModuleIds":["amino-carbon-skeleton-disorders"],"origin":"ai"}],"gluconeogenesis-cori-alanine":[{"id":"gluconeogenesis-cori-alanine~ai-0","moduleId":"gluconeogenesis-cori-alanine","stem":"Which substrate is primarily used for gluconeogenesis during fasting?","options":[{"id":"a","text":"Lactate"},{"id":"b","text":"Acetyl-CoA"},{"id":"c","text":"Fructose"},{"id":"d","text":"Glycerol"}],"answerId":"a","explanation":"Lactate is a key substrate for gluconeogenesis, especially during fasting, as it is converted to glucose in the liver.","kind":"recall","origin":"ai"},{"id":"gluconeogenesis-cori-alanine~ai-1","moduleId":"gluconeogenesis-cori-alanine","stem":"What is the role of acetyl-CoA in gluconeogenesis?","options":[{"id":"a","text":"Activates pyruvate carboxylase"},{"id":"b","text":"Inhibits glucose-6-phosphatase"},{"id":"c","text":"Stimulates fructose-1,6-bisphosphatase"},{"id":"d","text":"Provides carbon for glucose synthesis"}],"answerId":"a","explanation":"Acetyl-CoA activates pyruvate carboxylase, which is essential for initiating gluconeogenesis.","kind":"mechanism","origin":"ai"},{"id":"gluconeogenesis-cori-alanine~ai-2","moduleId":"gluconeogenesis-cori-alanine","stem":"Which of the following inhibits fructose-1,6-bisphosphatase?","options":[{"id":"a","text":"Glucagon"},{"id":"b","text":"ATP"},{"id":"c","text":"Citrate"},{"id":"d","text":"AMP"}],"answerId":"d","explanation":"AMP inhibits fructose-1,6-bisphosphatase, signaling a low energy state and favoring glycolysis over gluconeogenesis.","kind":"mechanism","origin":"ai"},{"id":"gluconeogenesis-cori-alanine~ai-3","moduleId":"gluconeogenesis-cori-alanine","stem":"A patient presents with hypoglycemia and lactic acidosis after fasting. What is the underlying mechanism?","options":[{"id":"a","text":"Increased gluconeogenesis"},{"id":"b","text":"High NADH levels"},{"id":"c","text":"Excess glucose production"},{"id":"d","text":"Decreased lactate production"}],"answerId":"b","explanation":"High NADH levels inhibit the entry of lactate and alanine into gluconeogenesis, leading to hypoglycemia and lactic acidosis.","kind":"clinical","origin":"ai"},{"id":"gluconeogenesis-cori-alanine~ai-4","moduleId":"gluconeogenesis-cori-alanine","stem":"Which statement about even-chain fatty acids is correct?","options":[{"id":"a","text":"They can provide net glucose"},{"id":"b","text":"They are converted to lactate"},{"id":"c","text":"They cannot produce net glucose"},{"id":"d","text":"They contribute to gluconeogenesis directly"}],"answerId":"c","explanation":"Even-chain fatty acids cannot provide net glucose in humans due to the irreversible nature of the PDH reaction.","kind":"trap","origin":"ai"},{"id":"gluconeogenesis-cori-alanine~ai-5","moduleId":"gluconeogenesis-cori-alanine","stem":"How does the glucose-alanine cycle function during muscle proteolysis?","options":[{"id":"a","text":"Transports lactate to the liver"},{"id":"b","text":"Carries amino nitrogen to the liver"},{"id":"c","text":"Increases glucose uptake in muscles"},{"id":"d","text":"Stimulates gluconeogenesis directly"}],"answerId":"b","explanation":"The glucose-alanine cycle transports amino nitrogen from muscle to the liver, where it can be used for gluconeogenesis.","kind":"recall","origin":"ai"},{"id":"gluconeogenesis-cori-alanine~ai-6","moduleId":"gluconeogenesis-cori-alanine","stem":"How does gluconeogenesis relate to blood glucose homeostasis during fasting?","options":[{"id":"a","text":"It decreases glucose levels"},{"id":"b","text":"It maintains glucose levels"},{"id":"c","text":"It increases insulin secretion"},{"id":"d","text":"It enhances glycolysis"}],"answerId":"b","explanation":"Gluconeogenesis is crucial for maintaining blood glucose levels during fasting by producing glucose from non-carbohydrate sources.","kind":"integration","linkedModuleIds":["blood-glucose-homeostasis"],"origin":"ai"},{"id":"gluconeogenesis-cori-alanine~ai-7","moduleId":"gluconeogenesis-cori-alanine","stem":"What is the connection between gluconeogenesis and renal metabolism?","options":[{"id":"a","text":"Both occur exclusively in the liver"},{"id":"b","text":"Renal gluconeogenesis is less important"},{"id":"c","text":"Kidneys can contribute to glucose production"},{"id":"d","text":"Only liver gluconeogenesis is regulated"}],"answerId":"c","explanation":"The kidneys can also perform gluconeogenesis, especially during prolonged fasting, contributing to overall glucose homeostasis.","kind":"integration","linkedModuleIds":["renal-metabolism-gluconeogenesis"],"origin":"ai"}],"fatty-acid-synthesis-eicosanoids":[{"id":"fatty-acid-synthesis-eicosanoids~ai-0","moduleId":"fatty-acid-synthesis-eicosanoids","stem":"What is the rate-limiting enzyme in fatty acid synthesis?","options":[{"id":"a","text":"Fatty-acid synthase"},{"id":"b","text":"Acetyl-CoA carboxylase"},{"id":"c","text":"Citrate lyase"},{"id":"d","text":"Malic enzyme"}],"answerId":"b","explanation":"Acetyl-CoA carboxylase (ACC) is the biotin-dependent rate-limiting enzyme that converts acetyl-CoA to malonyl-CoA.","kind":"recall","origin":"ai"},{"id":"fatty-acid-synthesis-eicosanoids~ai-1","moduleId":"fatty-acid-synthesis-eicosanoids","stem":"Which of the following statements about malonyl-CoA is true?","options":[{"id":"a","text":"It is produced during fasting."},{"id":"b","text":"It inhibits fatty acid synthesis."},{"id":"c","text":"It rises in the fed state."},{"id":"d","text":"It is derived from β-oxidation."}],"answerId":"c","explanation":"Malonyl-CoA levels rise in the fed state due to insulin activation of ACC, promoting fatty acid synthesis.","kind":"recall","origin":"ai"},{"id":"fatty-acid-synthesis-eicosanoids~ai-2","moduleId":"fatty-acid-synthesis-eicosanoids","stem":"How does insulin affect fatty acid synthesis?","options":[{"id":"a","text":"Inhibits ACC"},{"id":"b","text":"Activates CPT I"},{"id":"c","text":"Stimulates ACC"},{"id":"d","text":"Inhibits fatty-acid synthase"}],"answerId":"c","explanation":"Insulin activates acetyl-CoA carboxylase (ACC), promoting fatty acid synthesis.","kind":"mechanism","origin":"ai"},{"id":"fatty-acid-synthesis-eicosanoids~ai-3","moduleId":"fatty-acid-synthesis-eicosanoids","stem":"What clinical finding is associated with essential fatty acid deficiency?","options":[{"id":"a","text":"Scaly dermatitis"},{"id":"b","text":"Ketoacidosis"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Hyperlipidemia"}],"answerId":"a","explanation":"Scaly dermatitis is a common clinical finding due to impaired barrier lipids and eicosanoid precursors in essential fatty acid deficiency.","kind":"recall","origin":"ai"},{"id":"fatty-acid-synthesis-eicosanoids~ai-4","moduleId":"fatty-acid-synthesis-eicosanoids","stem":"What is the primary effect of malonyl-CoA on fatty acid metabolism?","options":[{"id":"a","text":"Promotes β-oxidation"},{"id":"b","text":"Inhibits CPT I"},{"id":"c","text":"Stimulates ketogenesis"},{"id":"d","text":"Enhances lipolysis"}],"answerId":"b","explanation":"Malonyl-CoA inhibits carnitine palmitoyltransferase I (CPT I), preventing simultaneous fatty acid synthesis and β-oxidation.","kind":"trap","origin":"ai"},{"id":"fatty-acid-synthesis-eicosanoids~ai-5","moduleId":"fatty-acid-synthesis-eicosanoids","stem":"Which essential fatty acid is a precursor to arachidonic acid?","options":[{"id":"a","text":"α-linolenic acid"},{"id":"b","text":"Linoleic acid"},{"id":"c","text":"Palmitic acid"},{"id":"d","text":"Stearic acid"}],"answerId":"b","explanation":"Linoleic acid (ω-6) is an essential fatty acid that is converted to arachidonic acid, a precursor for eicosanoids.","kind":"recall","origin":"ai"},{"id":"fatty-acid-synthesis-eicosanoids~ai-6","moduleId":"fatty-acid-synthesis-eicosanoids","stem":"How does fatty acid synthesis relate to ketogenesis?","options":[{"id":"a","text":"Both occur simultaneously in the liver."},{"id":"b","text":"Fatty acid synthesis is inhibited during ketogenesis."},{"id":"c","text":"Ketogenesis promotes fatty acid synthesis."},{"id":"d","text":"Both use the same substrates."}],"answerId":"b","explanation":"Fatty acid synthesis is inhibited during ketogenesis due to low insulin levels and high glucagon levels.","kind":"integration","linkedModuleIds":["ketone-body-metabolism"],"origin":"ai"},{"id":"fatty-acid-synthesis-eicosanoids~ai-7","moduleId":"fatty-acid-synthesis-eicosanoids","stem":"What is the relationship between fatty acid synthesis and triacylglycerol storage?","options":[{"id":"a","text":"Both processes are activated by glucagon."},{"id":"b","text":"Fatty acid synthesis provides substrates for triacylglycerol."},{"id":"c","text":"Triacylglycerol storage inhibits fatty acid synthesis."},{"id":"d","text":"Both occur in the mitochondria."}],"answerId":"b","explanation":"Fatty acid synthesis provides the fatty acids that are esterified to glycerol to form triacylglycerol for storage.","kind":"integration","linkedModuleIds":["tag-storage-mobilization"],"origin":"ai"}],"tag-storage-mobilization":[{"id":"tag-storage-mobilization~ai-0","moduleId":"tag-storage-mobilization","stem":"What is the primary role of insulin in adipose tissue regarding triacylglycerol (TAG) storage?","options":[{"id":"a","text":"Increases lipolysis"},{"id":"b","text":"Decreases glucose uptake"},{"id":"c","text":"Promotes TAG synthesis"},{"id":"d","text":"Inhibits glycerol-3-phosphate availability"}],"answerId":"c","explanation":"Insulin promotes TAG synthesis by increasing glucose uptake and glycerol-3-phosphate availability in adipose tissue.","kind":"recall","origin":"ai"},{"id":"tag-storage-mobilization~ai-1","moduleId":"tag-storage-mobilization","stem":"Which enzyme is primarily responsible for mobilizing stored triacylglycerols in adipose tissue during fasting?","options":[{"id":"a","text":"Lipoprotein lipase"},{"id":"b","text":"Hormone-sensitive lipase"},{"id":"c","text":"Acyl-CoA synthetase"},{"id":"d","text":"Glycerol kinase"}],"answerId":"b","explanation":"Hormone-sensitive lipase is activated during fasting to hydrolyze stored TAG into free fatty acids and glycerol.","kind":"mechanism","origin":"ai"},{"id":"tag-storage-mobilization~ai-2","moduleId":"tag-storage-mobilization","stem":"What clinical finding is expected in a patient with low insulin and high catecholamines?","options":[{"id":"a","text":"Increased glucose uptake"},{"id":"b","text":"Decreased plasma free fatty acids"},{"id":"c","text":"Increased plasma free fatty acids"},{"id":"d","text":"Decreased lipolysis"}],"answerId":"c","explanation":"Low insulin and high catecholamines stimulate adipose lipolysis, leading to increased plasma free fatty acids.","kind":"recall","origin":"ai"},{"id":"tag-storage-mobilization~ai-3","moduleId":"tag-storage-mobilization","stem":"Which statement correctly differentiates the roles of lipoprotein lipase (LPL) and hormone-sensitive lipase (HSL)?","options":[{"id":"a","text":"LPL mobilizes stored TAG; HSL acts on circulating TAG"},{"id":"b","text":"HSL acts on circulating TAG; LPL mobilizes stored TAG"},{"id":"c","text":"Both enzymes act in the same compartment"},{"id":"d","text":"LPL is activated by catecholamines"}],"answerId":"b","explanation":"HSL mobilizes stored TAG in adipocytes, while LPL hydrolyzes TAG in circulating chylomicrons and VLDL.","kind":"trap","origin":"ai"},{"id":"tag-storage-mobilization~ai-4","moduleId":"tag-storage-mobilization","stem":"Which of the following statements about glycerol metabolism in adipose tissue is true?","options":[{"id":"a","text":"Adipose tissue has high glycerol kinase activity"},{"id":"b","text":"Glycerol is primarily utilized in the liver"},{"id":"c","text":"Glycerol is converted to glucose in adipose tissue"},{"id":"d","text":"Glycerol is stored as TAG in adipose tissue"}],"answerId":"b","explanation":"Adipose tissue has low glycerol kinase activity, so glycerol mainly travels to the liver for gluconeogenesis.","kind":"recall","origin":"ai"},{"id":"tag-storage-mobilization~ai-5","moduleId":"tag-storage-mobilization","stem":"How does insulin signaling affect fatty acid synthesis in the liver?","options":[{"id":"a","text":"Increases fatty acid oxidation"},{"id":"b","text":"Inhibits glucose uptake"},{"id":"c","text":"Stimulates fatty acid synthesis"},{"id":"d","text":"Decreases glycerol-3-phosphate availability"}],"answerId":"c","explanation":"Insulin signaling promotes fatty acid synthesis in the liver by enhancing glucose uptake and increasing glycerol-3-phosphate availability.","kind":"integration","linkedModuleIds":["hen1-insulin-signaling-fed-metabolism"],"origin":"ai"},{"id":"tag-storage-mobilization~ai-6","moduleId":"tag-storage-mobilization","stem":"What is the relationship between triacylglycerol mobilization and β-oxidation during fasting?","options":[{"id":"a","text":"Increased TAG storage decreases β-oxidation"},{"id":"b","text":"Mobilized free fatty acids are substrates for β-oxidation"},{"id":"c","text":"Insulin promotes both processes equally"},{"id":"d","text":"Glycerol is the main substrate for β-oxidation"}],"answerId":"b","explanation":"During fasting, mobilized free fatty acids from TAG are transported to the liver and other tissues for β-oxidation.","kind":"integration","linkedModuleIds":["beta-oxidation-carnitine"],"origin":"ai"}],"one-carbon-carriers":[{"id":"one-carbon-carriers~ai-0","moduleId":"one-carbon-carriers","stem":"What is the primary function of S-adenosylmethionine (SAM) in cellular metabolism?","options":[{"id":"a","text":"It serves as a cofactor for enzyme activation."},{"id":"b","text":"It acts as a major methyl donor."},{"id":"c","text":"It is involved in the synthesis of ATP."},{"id":"d","text":"It facilitates the absorption of vitamin B₁₂."}],"answerId":"b","explanation":"SAM is the principal methyl donor in biological methylation reactions.","kind":"recall","origin":"ai"},{"id":"one-carbon-carriers~ai-1","moduleId":"one-carbon-carriers","stem":"Which vitamin deficiency leads to the accumulation of N⁵-methyl-THF?","options":[{"id":"a","text":"Vitamin B₁₂"},{"id":"b","text":"Vitamin B₆"},{"id":"c","text":"Vitamin C"},{"id":"d","text":"Folate"}],"answerId":"a","explanation":"Vitamin B₁₂ deficiency prevents the conversion of N⁵-methyl-THF to methionine, causing its accumulation.","kind":"recall","origin":"ai"},{"id":"one-carbon-carriers~ai-2","moduleId":"one-carbon-carriers","stem":"A patient presents with megaloblastic anemia and neurological symptoms. Which test would best differentiate between folate and vitamin B₁₂ deficiency?","options":[{"id":"a","text":"Serum folate levels"},{"id":"b","text":"Methylmalonic acid levels"},{"id":"c","text":"Complete blood count"},{"id":"d","text":"Homocysteine levels"}],"answerId":"b","explanation":"Elevated methylmalonic acid levels are indicative of vitamin B₁₂ deficiency.","kind":"clinical","origin":"ai"},{"id":"one-carbon-carriers~ai-3","moduleId":"one-carbon-carriers","stem":"How does vitamin B₁₂ deficiency affect DNA synthesis?","options":[{"id":"a","text":"It inhibits purine synthesis."},{"id":"b","text":"It prevents the conversion of dUMP to dTMP."},{"id":"c","text":"It disrupts the synthesis of RNA."},{"id":"d","text":"It enhances the activity of methionine synthase."}],"answerId":"b","explanation":"Vitamin B₁₂ is necessary for the conversion of dUMP to dTMP, crucial for DNA synthesis.","kind":"mechanism","origin":"ai"},{"id":"one-carbon-carriers~ai-4","moduleId":"one-carbon-carriers","stem":"In a patient with B₁₂ deficiency, what is the expected effect of administering folate alone?","options":[{"id":"a","text":"Complete resolution of neurological symptoms"},{"id":"b","text":"Normalization of blood count without neurological improvement"},{"id":"c","text":"Improvement in both hematologic and neurologic symptoms"},{"id":"d","text":"No change in symptoms"}],"answerId":"b","explanation":"Folate can improve hematologic parameters but does not resolve neurological damage in B₁₂ deficiency.","kind":"trap","origin":"ai"},{"id":"one-carbon-carriers~ai-5","moduleId":"one-carbon-carriers","stem":"Which of the following best describes the relationship between vitamin B₁₂ absorption and its clinical implications?","options":[{"id":"a","text":"Vitamin B₁₂ absorption is independent of intrinsic factor."},{"id":"b","text":"Deficiency leads to only hematologic abnormalities."},{"id":"c","text":"Absorption issues can lead to neurological deficits."},{"id":"d","text":"Vitamin B₁₂ is absorbed primarily in the stomach."}],"answerId":"c","explanation":"Vitamin B₁₂ absorption requires intrinsic factor and deficiency can cause both hematologic and neurological issues.","kind":"integration","linkedModuleIds":["vitamin-absorption"],"origin":"ai"},{"id":"one-carbon-carriers~ai-6","moduleId":"one-carbon-carriers","stem":"How does impaired methionine synthesis relate to amino acid metabolism disorders?","options":[{"id":"a","text":"It leads to increased transamination reactions."},{"id":"b","text":"It causes elevated levels of homocysteine."},{"id":"c","text":"It enhances the synthesis of neurotransmitters."},{"id":"d","text":"It decreases the availability of one-carbon units."}],"answerId":"b","explanation":"Impaired methionine synthesis results in elevated homocysteine levels, linking it to amino acid metabolism disorders.","kind":"integration","linkedModuleIds":["amino-nitrogen-handling"],"origin":"ai"}],"amino-nitrogen-handling":[{"id":"amino-nitrogen-handling~ai-0","moduleId":"amino-nitrogen-handling","stem":"What is the primary role of glutamate in amino acid nitrogen handling?","options":[{"id":"a","text":"Transporting nitrogen to the liver"},{"id":"b","text":"Serving as a neurotransmitter"},{"id":"c","text":"Releasing NH₄⁺ through oxidative deamination"},{"id":"d","text":"Synthesis of non-essential amino acids"}],"answerId":"c","explanation":"Glutamate acts as a key intermediary in amino nitrogen handling, facilitating the release of NH₄⁺ through oxidative deamination.","kind":"recall","origin":"ai"},{"id":"amino-nitrogen-handling~ai-1","moduleId":"amino-nitrogen-handling","stem":"Which aminotransferase is primarily elevated in liver injury involving alanine?","options":[{"id":"a","text":"AST"},{"id":"b","text":"ALT"},{"id":"c","text":"ALP"},{"id":"d","text":"GGT"}],"answerId":"b","explanation":"Alanine aminotransferase (ALT) is predominantly released from injured hepatocytes, marking liver injury.","kind":"recall","origin":"ai"},{"id":"amino-nitrogen-handling~ai-2","moduleId":"amino-nitrogen-handling","stem":"A patient presents with negative nitrogen balance due to major burns. What is the underlying mechanism?","options":[{"id":"a","text":"Increased protein synthesis"},{"id":"b","text":"Catabolic protein loss exceeds synthesis"},{"id":"c","text":"Decreased dietary protein intake"},{"id":"d","text":"Increased urea production"}],"answerId":"b","explanation":"In major burns, the catabolic process leads to protein loss that exceeds the body's ability to synthesize new proteins, resulting in negative nitrogen balance.","kind":"clinical","origin":"ai"},{"id":"amino-nitrogen-handling~ai-3","moduleId":"amino-nitrogen-handling","stem":"What does an elevation in aminotransferases primarily indicate?","options":[{"id":"a","text":"Increased protein synthesis"},{"id":"b","text":"Hepatocellular injury"},{"id":"c","text":"Improved liver function"},{"id":"d","text":"Increased urea production"}],"answerId":"b","explanation":"Elevated aminotransferases, such as ALT and AST, primarily indicate hepatocellular injury rather than increased protein synthesis.","kind":"trap","origin":"ai"},{"id":"amino-nitrogen-handling~ai-4","moduleId":"amino-nitrogen-handling","stem":"Which amino acid is primarily responsible for transporting nitrogen from peripheral tissues to the liver?","options":[{"id":"a","text":"Glutamate"},{"id":"b","text":"Alanine"},{"id":"c","text":"Aspartate"},{"id":"d","text":"Serine"}],"answerId":"b","explanation":"Alanine serves as a key nitrogen carrier from muscle to the liver, where it can be converted back to glucose and urea.","kind":"recall","origin":"ai"},{"id":"amino-nitrogen-handling~ai-5","moduleId":"amino-nitrogen-handling","stem":"How does the renal handling of potassium relate to amino acid nitrogen handling?","options":[{"id":"a","text":"Both processes involve urea synthesis"},{"id":"b","text":"Both involve transport of nitrogenous waste"},{"id":"c","text":"Both are regulated by the same hormones"},{"id":"d","text":"Both involve amino acid metabolism"}],"answerId":"b","explanation":"Both renal handling of potassium and amino acid nitrogen handling involve the transport and excretion of nitrogenous waste products, highlighting their interconnected roles in metabolism.","kind":"integration","linkedModuleIds":["renal-potassium-handling"],"origin":"ai"},{"id":"amino-nitrogen-handling~ai-6","moduleId":"amino-nitrogen-handling","stem":"In the context of amino acid-derived products, how does glutamine function in nitrogen transport?","options":[{"id":"a","text":"It is a direct precursor for urea"},{"id":"b","text":"It carries ammonia safely in the bloodstream"},{"id":"c","text":"It is converted to glucose in the liver"},{"id":"d","text":"It is a neurotransmitter in the brain"}],"answerId":"b","explanation":"Glutamine safely carries ammonia in the bloodstream to the liver, where it can be converted to urea for excretion.","kind":"integration","linkedModuleIds":["amino-acid-derived-products"],"origin":"ai"}],"cholesterol-bile-steroids":[{"id":"cholesterol-bile-steroids~ai-0","moduleId":"cholesterol-bile-steroids","stem":"What is the rate-limiting enzyme in cholesterol synthesis?","options":[{"id":"a","text":"HMG-CoA reductase"},{"id":"b","text":"Cholesterol 7α-hydroxylase"},{"id":"c","text":"Acetyl-CoA carboxylase"},{"id":"d","text":"Fatty acid synthase"}],"answerId":"a","explanation":"HMG-CoA reductase is the key regulatory enzyme in the cholesterol biosynthetic pathway.","kind":"recall","origin":"ai"},{"id":"cholesterol-bile-steroids~ai-1","moduleId":"cholesterol-bile-steroids","stem":"How does low cellular cholesterol affect HMG-CoA reductase activity?","options":[{"id":"a","text":"Inhibits it"},{"id":"b","text":"Activates it"},{"id":"c","text":"No effect"},{"id":"d","text":"Decreases LDL receptor expression"}],"answerId":"b","explanation":"Low cellular cholesterol activates SREBP-2, which increases HMG-CoA reductase activity.","kind":"mechanism","origin":"ai"},{"id":"cholesterol-bile-steroids~ai-2","moduleId":"cholesterol-bile-steroids","stem":"A patient with ileal disease presents with steatorrhea. What is the underlying mechanism?","options":[{"id":"a","text":"Increased bile acid synthesis"},{"id":"b","text":"Decreased bile acid recycling"},{"id":"c","text":"Increased cholesterol absorption"},{"id":"d","text":"Decreased LDL receptor activity"}],"answerId":"b","explanation":"Ileal disease disrupts enterohepatic recycling of bile acids, leading to bile acid loss and impaired fat absorption.","kind":"clinical","origin":"ai"},{"id":"cholesterol-bile-steroids~ai-3","moduleId":"cholesterol-bile-steroids","stem":"Which of the following correctly describes the fate of cytosolic HMG-CoA?","options":[{"id":"a","text":"Always enters ketogenesis"},{"id":"b","text":"Feeds cholesterol synthesis"},{"id":"c","text":"Converts to acetoacetate"},{"id":"d","text":"Inhibits cholesterol synthesis"}],"answerId":"b","explanation":"Cytosolic HMG-CoA is directed towards cholesterol synthesis, while mitochondrial HMG-CoA is involved in ketogenesis.","kind":"trap","origin":"ai"},{"id":"cholesterol-bile-steroids~ai-4","moduleId":"cholesterol-bile-steroids","stem":"Which enzyme is responsible for the rate-limiting step in bile acid synthesis?","options":[{"id":"a","text":"Cholesterol 7α-hydroxylase"},{"id":"b","text":"HMG-CoA reductase"},{"id":"c","text":"Acetyl-CoA carboxylase"},{"id":"d","text":"Fatty acid synthase"}],"answerId":"a","explanation":"Cholesterol 7α-hydroxylase catalyzes the first step in bile acid synthesis, making it the rate-limiting enzyme.","kind":"recall","origin":"ai"},{"id":"cholesterol-bile-steroids~ai-5","moduleId":"cholesterol-bile-steroids","stem":"How does statin therapy primarily lower LDL cholesterol levels?","options":[{"id":"a","text":"Increases bile acid synthesis"},{"id":"b","text":"Inhibits HMG-CoA reductase"},{"id":"c","text":"Decreases LDL receptor expression"},{"id":"d","text":"Increases cholesterol absorption"}],"answerId":"b","explanation":"Statins inhibit HMG-CoA reductase, leading to decreased hepatic cholesterol and increased LDL receptor expression, lowering LDL levels.","kind":"mechanism","origin":"ai"},{"id":"cholesterol-bile-steroids~ai-6","moduleId":"cholesterol-bile-steroids","stem":"Which of the following best describes the relationship between cholesterol synthesis and fatty acid synthesis?","options":[{"id":"a","text":"Both occur in the mitochondria"},{"id":"b","text":"Both are regulated by insulin"},{"id":"c","text":"Cholesterol synthesis is dependent on fatty acid oxidation"},{"id":"d","text":"Fatty acid synthesis inhibits cholesterol synthesis"}],"answerId":"b","explanation":"Both cholesterol and fatty acid synthesis are regulated by insulin, linking their metabolic pathways.","kind":"integration","linkedModuleIds":["fatty-acid-synthesis-eicosanoids"],"origin":"ai"},{"id":"cholesterol-bile-steroids~ai-7","moduleId":"cholesterol-bile-steroids","stem":"What is the consequence of impaired bile acid synthesis on fat digestion?","options":[{"id":"a","text":"Increased fat absorption"},{"id":"b","text":"Decreased fat absorption"},{"id":"c","text":"No effect on digestion"},{"id":"d","text":"Increased cholesterol synthesis"}],"answerId":"b","explanation":"Impaired bile acid synthesis reduces the formation of micelles, leading to decreased fat absorption.","kind":"integration","linkedModuleIds":["bile-composition-acid-synthesis"],"origin":"ai"}],"amino-carbon-skeleton-disorders":[{"id":"amino-carbon-skeleton-disorders~ai-0","moduleId":"amino-carbon-skeleton-disorders","stem":"What is the primary enzyme deficient in phenylketonuria (PKU)?","options":[{"id":"a","text":"Phenylalanine hydroxylase"},{"id":"b","text":"Tyrosine hydroxylase"},{"id":"c","text":"Dihydropteridine reductase"},{"id":"d","text":"Cystathionine β-synthase"}],"answerId":"a","explanation":"Phenylketonuria is primarily caused by a deficiency in phenylalanine hydroxylase, leading to phenylalanine accumulation.","kind":"recall","origin":"ai"},{"id":"amino-carbon-skeleton-disorders~ai-1","moduleId":"amino-carbon-skeleton-disorders","stem":"Which amino acid is exclusively ketogenic?","options":[{"id":"a","text":"Leucine"},{"id":"b","text":"Isoleucine"},{"id":"c","text":"Valine"},{"id":"d","text":"Tyrosine"}],"answerId":"a","explanation":"Leucine is one of the two exclusively ketogenic amino acids, meaning it is converted into ketone bodies.","kind":"recall","origin":"ai"},{"id":"amino-carbon-skeleton-disorders~ai-2","moduleId":"amino-carbon-skeleton-disorders","stem":"In maple syrup urine disease, which metabolic pathway is disrupted?","options":[{"id":"a","text":"Branched-chain amino acid metabolism"},{"id":"b","text":"Urea cycle"},{"id":"c","text":"TCA cycle"},{"id":"d","text":"Glycolysis"}],"answerId":"a","explanation":"Maple syrup urine disease results from a deficiency in branched-chain α-ketoacid dehydrogenase, disrupting the metabolism of branched-chain amino acids.","kind":"mechanism","origin":"ai"},{"id":"amino-carbon-skeleton-disorders~ai-3","moduleId":"amino-carbon-skeleton-disorders","stem":"A child presents with a musty odor, eczema, and fair skin. Which condition is most likely?","options":[{"id":"a","text":"Maple syrup urine disease"},{"id":"b","text":"Phenylketonuria"},{"id":"c","text":"Homocystinuria"},{"id":"d","text":"Cystinuria"}],"answerId":"b","explanation":"These clinical findings are characteristic of phenylketonuria (PKU) due to phenylalanine accumulation.","kind":"clinical","origin":"ai"},{"id":"amino-carbon-skeleton-disorders~ai-4","moduleId":"amino-carbon-skeleton-disorders","stem":"Classic homocystinuria is caused by a deficiency in which enzyme?","options":[{"id":"a","text":"Cystathionine β-synthase"},{"id":"b","text":"Phenylalanine hydroxylase"},{"id":"c","text":"Branched-chain α-ketoacid dehydrogenase"},{"id":"d","text":"Arginase"}],"answerId":"a","explanation":"Cystathionine β-synthase deficiency leads to classic homocystinuria, resulting in various clinical manifestations.","kind":"recall","origin":"ai"},{"id":"amino-carbon-skeleton-disorders~ai-5","moduleId":"amino-carbon-skeleton-disorders","stem":"Maternal PKU can affect a fetus even if the fetus has normal PAH genes. Why?","options":[{"id":"a","text":"Maternal phenylalanine is teratogenic"},{"id":"b","text":"Fetal metabolism is independent of maternal levels"},{"id":"c","text":"Fetal PAH gene expression is suppressed"},{"id":"d","text":"Maternal diet does not influence fetal development"}],"answerId":"a","explanation":"Poorly controlled maternal phenylalanine levels are teratogenic, affecting fetal development regardless of the fetus's genotype.","kind":"trap","origin":"ai"},{"id":"amino-carbon-skeleton-disorders~ai-6","moduleId":"amino-carbon-skeleton-disorders","stem":"How does homocystinuria relate to one-carbon metabolism?","options":[{"id":"a","text":"It involves the conversion of homocysteine to methionine"},{"id":"b","text":"It affects the synthesis of neurotransmitters"},{"id":"c","text":"It disrupts the urea cycle"},{"id":"d","text":"It leads to increased ammonia levels"}],"answerId":"a","explanation":"Homocystinuria is linked to one-carbon metabolism as it involves the conversion of homocysteine to methionine, which is dependent on vitamin B12 and folate.","kind":"integration","linkedModuleIds":["one-carbon-carriers"],"origin":"ai"},{"id":"amino-carbon-skeleton-disorders~ai-7","moduleId":"amino-carbon-skeleton-disorders","stem":"Which condition can lead to increased risk of thrombosis due to amino acid metabolism?","options":[{"id":"a","text":"Maple syrup urine disease"},{"id":"b","text":"Phenylketonuria"},{"id":"c","text":"Homocystinuria"},{"id":"d","text":"Urea cycle disorders"}],"answerId":"c","explanation":"Homocystinuria is associated with increased homocysteine levels, which can lead to a higher risk of thrombosis.","kind":"integration","linkedModuleIds":["urea-cycle-hyperammonemia"],"origin":"ai"}],"urea-cycle-hyperammonemia":[{"id":"urea-cycle-hyperammonemia~ai-0","moduleId":"urea-cycle-hyperammonemia","stem":"What is the primary function of the urea cycle?","options":[{"id":"a","text":"Convert ammonia to urea"},{"id":"b","text":"Synthesize amino acids"},{"id":"c","text":"Produce glucose from amino acids"},{"id":"d","text":"Regulate blood pH"}],"answerId":"a","explanation":"The urea cycle's main role is to convert toxic ammonia into urea for excretion.","kind":"recall","origin":"ai"},{"id":"urea-cycle-hyperammonemia~ai-1","moduleId":"urea-cycle-hyperammonemia","stem":"Which enzyme is the rate-limiting step in the urea cycle?","options":[{"id":"a","text":"Arginase"},{"id":"b","text":"Carbamoyl phosphate synthetase I"},{"id":"c","text":"Ornithine transcarbamylase"},{"id":"d","text":"Argininosuccinate synthetase"}],"answerId":"b","explanation":"Carbamoyl phosphate synthetase I (CPS I) is the rate-limiting enzyme and requires N-acetylglutamate.","kind":"mechanism","origin":"ai"},{"id":"urea-cycle-hyperammonemia~ai-2","moduleId":"urea-cycle-hyperammonemia","stem":"A neonate presents with vomiting, lethargy, and low blood urea nitrogen (BUN). What is the likely cause?","options":[{"id":"a","text":"Urea cycle defect"},{"id":"b","text":"Acute liver failure"},{"id":"c","text":"Inborn error of metabolism"},{"id":"d","text":"Renal failure"}],"answerId":"a","explanation":"These symptoms suggest a urea cycle defect, as ammonia cannot be converted to urea, leading to hyperammonemia.","kind":"clinical","origin":"ai"},{"id":"urea-cycle-hyperammonemia~ai-3","moduleId":"urea-cycle-hyperammonemia","stem":"In ornithine transcarbamylase (OTC) deficiency, which of the following lab findings is expected?","options":[{"id":"a","text":"High urine orotic acid"},{"id":"b","text":"High blood urea nitrogen"},{"id":"c","text":"Low ammonia levels"},{"id":"d","text":"High serum glucose"}],"answerId":"a","explanation":"OTC deficiency leads to high urine orotic acid due to the overflow of carbamoyl phosphate into pyrimidine synthesis.","kind":"recall","origin":"ai"},{"id":"urea-cycle-hyperammonemia~ai-4","moduleId":"urea-cycle-hyperammonemia","stem":"Which statement differentiates OTC deficiency from UMP-synthase deficiency?","options":[{"id":"a","text":"Both cause hyperammonemia"},{"id":"b","text":"Only OTC deficiency causes megaloblastic anemia"},{"id":"c","text":"OTC deficiency does not cause megaloblastic anemia"},{"id":"d","text":"Both are X-linked disorders"}],"answerId":"c","explanation":"OTC deficiency causes hyperammonemia without megaloblastic anemia, while UMP-synthase deficiency causes megaloblastic anemia without hyperammonemia.","kind":"trap","origin":"ai"},{"id":"urea-cycle-hyperammonemia~ai-5","moduleId":"urea-cycle-hyperammonemia","stem":"How does hyperammonemia lead to cerebral edema?","options":[{"id":"a","text":"Increased glutamate levels"},{"id":"b","text":"Decreased α-ketoglutarate"},{"id":"c","text":"Increased astrocyte glutamine"},{"id":"d","text":"Decreased blood flow to the brain"}],"answerId":"c","explanation":"Hyperammonemia raises astrocyte glutamine, leading to osmotic imbalance and cerebral edema.","kind":"mechanism","origin":"ai"},{"id":"urea-cycle-hyperammonemia~ai-6","moduleId":"urea-cycle-hyperammonemia","stem":"How does the urea cycle relate to amino acid nitrogen handling?","options":[{"id":"a","text":"Both involve the conversion of ammonia to urea"},{"id":"b","text":"Both are regulated by insulin"},{"id":"c","text":"Both produce glucose from amino acids"},{"id":"d","text":"Both occur in the mitochondria"}],"answerId":"a","explanation":"The urea cycle is a key pathway in amino acid nitrogen handling, converting ammonia to urea for excretion.","kind":"integration","linkedModuleIds":["amino-nitrogen-handling"],"origin":"ai"},{"id":"urea-cycle-hyperammonemia~ai-7","moduleId":"urea-cycle-hyperammonemia","stem":"What is the clinical significance of understanding the urea cycle in hepatic encephalopathy?","options":[{"id":"a","text":"It helps in diagnosing liver cirrhosis"},{"id":"b","text":"It explains the mechanism of ammonia toxicity"},{"id":"c","text":"It guides insulin therapy"},{"id":"d","text":"It is unrelated to hepatic function"}],"answerId":"b","explanation":"Understanding the urea cycle is crucial in hepatic encephalopathy as it explains how ammonia accumulation leads to neurological symptoms.","kind":"integration","linkedModuleIds":["hepatic-encephalopathy-ammonia"],"origin":"ai"}],"hepatic-encephalopathy-ammonia":[{"id":"hepatic-encephalopathy-ammonia~ai-0","moduleId":"hepatic-encephalopathy-ammonia","stem":"What is the primary mechanism by which hepatic encephalopathy develops in cirrhosis?","options":[{"id":"a","text":"Increased ammonia production in the gut"},{"id":"b","text":"Decreased urea cycle detoxification"},{"id":"c","text":"Increased blood-brain barrier permeability"},{"id":"d","text":"Decreased cerebral blood flow"}],"answerId":"b","explanation":"In cirrhosis, the liver's ability to detoxify ammonia via the urea cycle is impaired, leading to increased levels of ammonia in the bloodstream.","kind":"mechanism","origin":"ai"},{"id":"hepatic-encephalopathy-ammonia~ai-1","moduleId":"hepatic-encephalopathy-ammonia","stem":"Which clinical finding is most indicative of hepatic encephalopathy?","options":[{"id":"a","text":"Elevated serum creatinine"},{"id":"b","text":"Asterixis"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Elevated liver enzymes"}],"answerId":"b","explanation":"Asterixis is a characteristic sign of hepatic encephalopathy, indicating metabolic dysfunction.","kind":"recall","origin":"ai"},{"id":"hepatic-encephalopathy-ammonia~ai-2","moduleId":"hepatic-encephalopathy-ammonia","stem":"What is a common precipitant of hepatic encephalopathy?","options":[{"id":"a","text":"Hyperglycemia"},{"id":"b","text":"Hypotension"},{"id":"c","text":"GI bleeding"},{"id":"d","text":"Hypocalcemia"}],"answerId":"c","explanation":"GI bleeding is a common precipitant of hepatic encephalopathy due to increased nitrogen load from protein breakdown.","kind":"recall","origin":"ai"},{"id":"hepatic-encephalopathy-ammonia~ai-3","moduleId":"hepatic-encephalopathy-ammonia","stem":"Which statement about ammonia levels in hepatic encephalopathy is true?","options":[{"id":"a","text":"A normal ammonia level rules out hepatic encephalopathy"},{"id":"b","text":"Ammonia levels correlate perfectly with clinical severity"},{"id":"c","text":"Ammonia levels can be misleading in diagnosis"},{"id":"d","text":"Elevated ammonia levels confirm hepatic encephalopathy"}],"answerId":"c","explanation":"Ammonia levels can be misleading; hepatic encephalopathy is primarily a clinical diagnosis.","kind":"trap","origin":"ai"},{"id":"hepatic-encephalopathy-ammonia~ai-4","moduleId":"hepatic-encephalopathy-ammonia","stem":"In the context of hepatic encephalopathy, how does astrocyte dysfunction contribute to symptoms?","options":[{"id":"a","text":"Increased neurotransmitter release"},{"id":"b","text":"Decreased glutamine synthesis"},{"id":"c","text":"Osmotic swelling from glutamine accumulation"},{"id":"d","text":"Increased ammonia detoxification"}],"answerId":"c","explanation":"Astrocytes convert ammonia to glutamine, and its accumulation leads to osmotic swelling, contributing to cerebral dysfunction.","kind":"mechanism","origin":"ai"},{"id":"hepatic-encephalopathy-ammonia~ai-5","moduleId":"hepatic-encephalopathy-ammonia","stem":"How does hepatic encephalopathy differ from uremic encephalopathy in terms of pathophysiology?","options":[{"id":"a","text":"Both involve ammonia accumulation"},{"id":"b","text":"Only hepatic encephalopathy is reversible"},{"id":"c","text":"Uremic encephalopathy is caused by electrolyte imbalance"},{"id":"d","text":"Only hepatic encephalopathy involves portosystemic shunting"}],"answerId":"d","explanation":"Hepatic encephalopathy involves portosystemic shunting, allowing ammonia to bypass detoxification, while uremic encephalopathy is primarily due to renal failure.","kind":"integration","linkedModuleIds":["hepatic-uremic-encephalopathy"],"origin":"ai"},{"id":"hepatic-encephalopathy-ammonia~ai-6","moduleId":"hepatic-encephalopathy-ammonia","stem":"What is a key difference in the management of hepatic encephalopathy compared to alcohol-related liver disease?","options":[{"id":"a","text":"Hepatic encephalopathy requires immediate dialysis"},{"id":"b","text":"Alcohol-related liver disease does not involve ammonia"},{"id":"c","text":"Hepatic encephalopathy management focuses on reducing ammonia levels"},{"id":"d","text":"Alcohol-related liver disease is always reversible"}],"answerId":"c","explanation":"Management of hepatic encephalopathy focuses on reducing ammonia levels and addressing precipitating factors.","kind":"integration","linkedModuleIds":["alcohol-aldh2-cirrhosis"],"origin":"ai"}],"cholangitis-bile-vitamin-loss":[{"id":"cholangitis-bile-vitamin-loss~ai-0","moduleId":"cholangitis-bile-vitamin-loss","stem":"What is the primary cause of ascending cholangitis?","options":[{"id":"a","text":"Bacterial infection of the liver"},{"id":"b","text":"Obstruction of the biliary tree"},{"id":"c","text":"Viral hepatitis"},{"id":"d","text":"Gallbladder inflammation"}],"answerId":"b","explanation":"Ascending cholangitis is primarily caused by obstruction of the biliary tree, leading to infection.","kind":"recall","origin":"ai"},{"id":"cholangitis-bile-vitamin-loss~ai-1","moduleId":"cholangitis-bile-vitamin-loss","stem":"Which of the following is part of the Charcot triad in ascending cholangitis?","options":[{"id":"a","text":"Hypotension"},{"id":"b","text":"Jaundice"},{"id":"c","text":"Abdominal distension"},{"id":"d","text":"Diarrhea"}],"answerId":"b","explanation":"The Charcot triad consists of fever, right upper quadrant pain, and jaundice.","kind":"recall","origin":"ai"},{"id":"cholangitis-bile-vitamin-loss~ai-2","moduleId":"cholangitis-bile-vitamin-loss","stem":"How does bile obstruction lead to vitamin deficiency?","options":[{"id":"a","text":"Increased absorption of vitamins"},{"id":"b","text":"Reduced bile salts impair micelle formation"},{"id":"c","text":"Increased bile salt production"},{"id":"d","text":"Decreased intestinal motility"}],"answerId":"b","explanation":"Obstruction reduces bile salts, impairing micelle formation, which is essential for fat-soluble vitamin absorption.","kind":"mechanism","origin":"ai"},{"id":"cholangitis-bile-vitamin-loss~ai-3","moduleId":"cholangitis-bile-vitamin-loss","stem":"A patient presents with fever, RUQ pain, and jaundice. What is the most likely finding on examination?","options":[{"id":"a","text":"Hepatomegaly"},{"id":"b","text":"Splenomegaly"},{"id":"c","text":"Ascites"},{"id":"d","text":"Palpable gallbladder"}],"answerId":"a","explanation":"Hepatomegaly is common in cholangitis due to liver involvement and inflammation.","kind":"clinical","origin":"ai"},{"id":"cholangitis-bile-vitamin-loss~ai-4","moduleId":"cholangitis-bile-vitamin-loss","stem":"What is the most appropriate initial management for severe ascending cholangitis?","options":[{"id":"a","text":"Immediate surgery"},{"id":"b","text":"Antibiotics alone"},{"id":"c","text":"Urgent biliary decompression and antibiotics"},{"id":"d","text":"Observation and follow-up"}],"answerId":"c","explanation":"Severe cholangitis requires urgent biliary decompression along with antibiotics to address the infection and obstruction.","kind":"trap","origin":"ai"},{"id":"cholangitis-bile-vitamin-loss~ai-5","moduleId":"cholangitis-bile-vitamin-loss","stem":"In a patient with cholestatic jaundice, which vitamin deficiency is most likely to cause a bleeding tendency?","options":[{"id":"a","text":"Vitamin A"},{"id":"b","text":"Vitamin D"},{"id":"c","text":"Vitamin E"},{"id":"d","text":"Vitamin K"}],"answerId":"d","explanation":"Vitamin K deficiency due to cholestasis impairs the γ-carboxylation of clotting factors, leading to bleeding.","kind":"recall","origin":"ai"},{"id":"cholangitis-bile-vitamin-loss~ai-6","moduleId":"cholangitis-bile-vitamin-loss","stem":"How does ascending cholangitis relate to fat-soluble vitamin absorption issues?","options":[{"id":"a","text":"Increased bile salt production enhances absorption"},{"id":"b","text":"Obstruction leads to bile salt deficiency"},{"id":"c","text":"Infection enhances vitamin absorption"},{"id":"d","text":"Bile acids are not involved in absorption"}],"answerId":"b","explanation":"Obstruction of the biliary tree leads to reduced bile salts, impairing the absorption of fat-soluble vitamins.","kind":"integration","linkedModuleIds":["fat-soluble-vitamins"],"origin":"ai"},{"id":"cholangitis-bile-vitamin-loss~ai-7","moduleId":"cholangitis-bile-vitamin-loss","stem":"Which laboratory finding would you expect in a patient with ascending cholangitis?","options":[{"id":"a","text":"Elevated AST and ALT"},{"id":"b","text":"Elevated alkaline phosphatase"},{"id":"c","text":"Low bilirubin levels"},{"id":"d","text":"Decreased white blood cell count"}],"answerId":"b","explanation":"Elevated alkaline phosphatase is typical in cholestatic conditions like ascending cholangitis.","kind":"integration","linkedModuleIds":["cholestatic-lab-pattern"],"origin":"ai"}],"acetaminophen-overdose-pattern":[{"id":"acetaminophen-overdose-pattern~ai-0","moduleId":"acetaminophen-overdose-pattern","stem":"What is the earliest symptom of acetaminophen overdose?","options":[{"id":"a","text":"Jaundice"},{"id":"b","text":"Nausea"},{"id":"c","text":"Right-upper-quadrant pain"},{"id":"d","text":"Encephalopathy"}],"answerId":"b","explanation":"Nausea is often the first symptom of acetaminophen overdose, occurring before more severe symptoms develop.","kind":"recall","origin":"ai"},{"id":"acetaminophen-overdose-pattern~ai-1","moduleId":"acetaminophen-overdose-pattern","stem":"Which laboratory finding is characteristic of severe acetaminophen toxicity?","options":[{"id":"a","text":"Elevated bilirubin"},{"id":"b","text":"High AST/ALT"},{"id":"c","text":"Low glucose"},{"id":"d","text":"Increased creatinine"}],"answerId":"b","explanation":"Severe acetaminophen toxicity is characterized by very high AST/ALT levels due to hepatocellular injury.","kind":"recall","origin":"ai"},{"id":"acetaminophen-overdose-pattern~ai-2","moduleId":"acetaminophen-overdose-pattern","stem":"In acetaminophen overdose, what does a rising INR indicate?","options":[{"id":"a","text":"Improving liver function"},{"id":"b","text":"Decreasing hepatocyte injury"},{"id":"c","text":"Synthetic liver failure"},{"id":"d","text":"Decreased bilirubin production"}],"answerId":"c","explanation":"A rising INR indicates synthetic liver failure due to loss of viable hepatocytes, despite potentially falling AST/ALT levels.","kind":"clinical","origin":"ai"},{"id":"acetaminophen-overdose-pattern~ai-3","moduleId":"acetaminophen-overdose-pattern","stem":"What is the correct use of the Rumack-Matthew nomogram?","options":[{"id":"a","text":"For any acetaminophen concentration"},{"id":"b","text":"For chronic ingestion cases"},{"id":"c","text":"For a single acute ingestion with known time"},{"id":"d","text":"For patients with liver disease"}],"answerId":"c","explanation":"The Rumack-Matthew nomogram is only valid for a single acute ingestion with a known time.","kind":"trap","origin":"ai"},{"id":"acetaminophen-overdose-pattern~ai-4","moduleId":"acetaminophen-overdose-pattern","stem":"What is the mechanism of hepatotoxicity in acetaminophen overdose?","options":[{"id":"a","text":"Direct hepatocyte injury"},{"id":"b","text":"Glutathione depletion"},{"id":"c","text":"Increased bilirubin production"},{"id":"d","text":"Viral hepatitis activation"}],"answerId":"b","explanation":"Hepatotoxicity occurs primarily due to the depletion of glutathione, leading to the accumulation of the toxic metabolite NAPQI.","kind":"mechanism","origin":"ai"},{"id":"acetaminophen-overdose-pattern~ai-5","moduleId":"acetaminophen-overdose-pattern","stem":"How does N-acetylcysteine (NAC) mitigate acetaminophen toxicity?","options":[{"id":"a","text":"Increases bilirubin excretion"},{"id":"b","text":"Restores glutathione levels"},{"id":"c","text":"Inhibits NAPQI formation"},{"id":"d","text":"Enhances liver regeneration"}],"answerId":"b","explanation":"N-acetylcysteine acts as a precursor to glutathione, helping to restore its levels and detoxify NAPQI.","kind":"integration","linkedModuleIds":["napqi-glutathione-nac"],"origin":"ai"},{"id":"acetaminophen-overdose-pattern~ai-6","moduleId":"acetaminophen-overdose-pattern","stem":"Which symptom may indicate progression to acute liver failure in acetaminophen overdose?","options":[{"id":"a","text":"Mild abdominal discomfort"},{"id":"b","text":"Elevated AST/ALT"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Nausea"}],"answerId":"c","explanation":"Hypoglycemia is a concerning symptom that can indicate progression to acute liver failure in the context of acetaminophen overdose.","kind":"clinical","origin":"ai"}],"exercise-stress-fuel-integration":[{"id":"exercise-stress-fuel-integration~ai-0","moduleId":"exercise-stress-fuel-integration","stem":"What is the primary fuel source utilized during immediate intense exercise?","options":[{"id":"a","text":"Muscle glycogen"},{"id":"b","text":"Stored ATP and phosphocreatine"},{"id":"c","text":"Fatty acids"},{"id":"d","text":"Blood glucose"}],"answerId":"b","explanation":"Immediate intense work primarily relies on stored ATP and phosphocreatine for energy.","kind":"recall","origin":"ai"},{"id":"exercise-stress-fuel-integration~ai-1","moduleId":"exercise-stress-fuel-integration","stem":"Which hormone is primarily responsible for stimulating glycogenolysis during exercise?","options":[{"id":"a","text":"Cortisol"},{"id":"b","text":"Insulin"},{"id":"c","text":"Epinephrine"},{"id":"d","text":"Glucagon"}],"answerId":"c","explanation":"Epinephrine rapidly stimulates both muscle and liver glycogenolysis during exercise.","kind":"mechanism","origin":"ai"},{"id":"exercise-stress-fuel-integration~ai-2","moduleId":"exercise-stress-fuel-integration","stem":"What mechanism allows muscle glucose uptake during exercise despite low insulin levels?","options":[{"id":"a","text":"Insulin-dependent GLUT4 translocation"},{"id":"b","text":"Contraction-triggered GLUT4 translocation"},{"id":"c","text":"Increased blood flow"},{"id":"d","text":"Enhanced insulin sensitivity"}],"answerId":"b","explanation":"Muscle contraction independently recruits GLUT4, facilitating glucose uptake during exercise.","kind":"mechanism","origin":"ai"},{"id":"exercise-stress-fuel-integration~ai-3","moduleId":"exercise-stress-fuel-integration","stem":"During prolonged moderate exercise, which metabolic process is primarily responsible for maintaining blood glucose levels?","options":[{"id":"a","text":"Glycogenolysis in muscle"},{"id":"b","text":"Gluconeogenesis in liver"},{"id":"c","text":"Lipolysis in adipose tissue"},{"id":"d","text":"Protein catabolism"}],"answerId":"b","explanation":"The liver maintains blood glucose through glycogenolysis and gluconeogenesis during prolonged exercise.","kind":"recall","origin":"ai"},{"id":"exercise-stress-fuel-integration~ai-4","moduleId":"exercise-stress-fuel-integration","stem":"A patient presents with low insulin levels but high blood glucose during exercise. What explains this phenomenon?","options":[{"id":"a","text":"Insulin resistance"},{"id":"b","text":"Increased gluconeogenesis"},{"id":"c","text":"Muscle contraction recruiting GLUT4"},{"id":"d","text":"Increased lipolysis"}],"answerId":"c","explanation":"Muscle contraction recruits GLUT4 independently of insulin, allowing glucose uptake despite low insulin levels.","kind":"trap","origin":"ai"},{"id":"exercise-stress-fuel-integration~ai-5","moduleId":"exercise-stress-fuel-integration","stem":"How does cortisol support the body during prolonged stress?","options":[{"id":"a","text":"Increases insulin sensitivity"},{"id":"b","text":"Promotes lipolysis and gluconeogenesis"},{"id":"c","text":"Stimulates glycogen synthesis"},{"id":"d","text":"Enhances muscle protein synthesis"}],"answerId":"b","explanation":"Cortisol increases proteolysis, lipolysis, and gluconeogenic enzyme expression to support energy needs during stress.","kind":"mechanism","origin":"ai"},{"id":"exercise-stress-fuel-integration~ai-6","moduleId":"exercise-stress-fuel-integration","stem":"How does epinephrine affect adipose tissue during exercise?","options":[{"id":"a","text":"Stimulates insulin release"},{"id":"b","text":"Inhibits lipolysis"},{"id":"c","text":"Stimulates lipolysis"},{"id":"d","text":"Increases glucose uptake"}],"answerId":"c","explanation":"Epinephrine stimulates lipolysis in adipose tissue, providing free fatty acids for energy during exercise.","kind":"mechanism","origin":"ai"},{"id":"exercise-stress-fuel-integration~ai-7","moduleId":"exercise-stress-fuel-integration","stem":"Which of the following best describes the relationship between exercise and cortisol levels?","options":[{"id":"a","text":"Cortisol decreases during exercise"},{"id":"b","text":"Cortisol has no effect on exercise"},{"id":"c","text":"Cortisol increases to support prolonged exercise"},{"id":"d","text":"Cortisol only affects anaerobic exercise"}],"answerId":"c","explanation":"Cortisol levels increase during prolonged exercise to support metabolic needs.","kind":"integration","linkedModuleIds":["hen1-cortisol-systemic-actions"],"origin":"ai"},{"id":"exercise-stress-fuel-integration~ai-8","moduleId":"exercise-stress-fuel-integration","stem":"What is the role of lactate during intense exercise?","options":[{"id":"a","text":"It is a waste product only"},{"id":"b","text":"It provides energy directly to muscles"},{"id":"c","text":"It is recycled to glucose in the liver"},{"id":"d","text":"It inhibits glycolysis"}],"answerId":"c","explanation":"Lactate produced during intense exercise is recycled to glucose in the liver via Cori cycling.","kind":"integration","linkedModuleIds":["metabolic-junction-points"],"origin":"ai"}],"metabolic-junction-points":[{"id":"metabolic-junction-points~ai-0","moduleId":"metabolic-junction-points","stem":"Which of the following pathways can glucose-6-phosphate enter?","options":[{"id":"a","text":"Glycolysis"},{"id":"b","text":"Citric Acid Cycle"},{"id":"c","text":"Urea Cycle"},{"id":"d","text":"Beta-Oxidation"}],"answerId":"a","explanation":"Glucose-6-phosphate can enter glycolysis, glycogen synthesis, or the pentose phosphate pathway, but not the citric acid cycle directly.","kind":"recall","origin":"ai"},{"id":"metabolic-junction-points~ai-1","moduleId":"metabolic-junction-points","stem":"What is the primary irreversible step in converting pyruvate to acetyl-CoA?","options":[{"id":"a","text":"Pyruvate carboxylase"},{"id":"b","text":"Pyruvate dehydrogenase"},{"id":"c","text":"Lactate dehydrogenase"},{"id":"d","text":"Alanine transaminase"}],"answerId":"b","explanation":"The conversion of pyruvate to acetyl-CoA by pyruvate dehydrogenase is irreversible.","kind":"mechanism","origin":"ai"},{"id":"metabolic-junction-points~ai-2","moduleId":"metabolic-junction-points","stem":"Which statement about acetyl-CoA is true?","options":[{"id":"a","text":"It can be converted to glucose in humans."},{"id":"b","text":"It is a substrate for fatty acid synthesis."},{"id":"c","text":"It is exclusively ketogenic."},{"id":"d","text":"It can directly enter gluconeogenesis."}],"answerId":"b","explanation":"Acetyl-CoA is a key substrate for fatty acid synthesis but cannot be converted to glucose in humans.","kind":"trap","origin":"ai"},{"id":"metabolic-junction-points~ai-3","moduleId":"metabolic-junction-points","stem":"What is the clinical significance of elevated lactate in a patient?","options":[{"id":"a","text":"Indicates increased gluconeogenesis"},{"id":"b","text":"Suggests anaerobic metabolism"},{"id":"c","text":"Confirms fatty acid oxidation"},{"id":"d","text":"Reflects normal pyruvate metabolism"}],"answerId":"b","explanation":"Elevated lactate indicates increased anaerobic metabolism, often due to insufficient oxygen supply.","kind":"clinical","origin":"ai"},{"id":"metabolic-junction-points~ai-4","moduleId":"metabolic-junction-points","stem":"Which of the following is a consequence of fasting on acetyl-CoA metabolism?","options":[{"id":"a","text":"Increased gluconeogenesis from acetyl-CoA"},{"id":"b","text":"Decreased ketogenesis"},{"id":"c","text":"Increased fatty acid oxidation"},{"id":"d","text":"Increased glucose production from TCA cycle"}],"answerId":"c","explanation":"During fasting, fatty acid oxidation increases, leading to elevated acetyl-CoA and ketogenesis, but not glucose production from acetyl-CoA.","kind":"trap","origin":"ai"},{"id":"metabolic-junction-points~ai-5","moduleId":"metabolic-junction-points","stem":"How does the mechanism of pyruvate carboxylase differ from that of pyruvate dehydrogenase?","options":[{"id":"a","text":"Both are reversible"},{"id":"b","text":"Pyruvate carboxylase is irreversible"},{"id":"c","text":"Pyruvate dehydrogenase is reversible"},{"id":"d","text":"Pyruvate carboxylase produces glucose"}],"answerId":"a","explanation":"Pyruvate carboxylase is reversible in gluconeogenesis, while pyruvate dehydrogenase is not.","kind":"mechanism","origin":"ai"},{"id":"metabolic-junction-points~ai-6","moduleId":"metabolic-junction-points","stem":"How does exercise affect fuel metabolism in relation to acetyl-CoA?","options":[{"id":"a","text":"Increases glucose production from acetyl-CoA"},{"id":"b","text":"Promotes fatty acid oxidation"},{"id":"c","text":"Decreases ketone body production"},{"id":"d","text":"Reduces reliance on anaerobic metabolism"}],"answerId":"b","explanation":"During exercise, there is an increased reliance on fatty acid oxidation, which elevates acetyl-CoA levels.","kind":"integration","linkedModuleIds":["exercise-stress-fuel-integration"],"origin":"ai"},{"id":"metabolic-junction-points~ai-7","moduleId":"metabolic-junction-points","stem":"In a fasting state, which metabolic pathway is primarily activated to manage energy needs?","options":[{"id":"a","text":"Glycolysis"},{"id":"b","text":"Gluconeogenesis"},{"id":"c","text":"Fatty acid synthesis"},{"id":"d","text":"Citric Acid Cycle"}],"answerId":"b","explanation":"In fasting, gluconeogenesis is primarily activated to maintain blood glucose levels.","kind":"integration","linkedModuleIds":["fed-fasting-starvation"],"origin":"ai"}],"organ-specific-fuel-metabolism":[{"id":"organ-specific-fuel-metabolism~ai-0","moduleId":"organ-specific-fuel-metabolism","stem":"Which organ is primarily responsible for gluconeogenesis during fasting?","options":[{"id":"a","text":"Liver"},{"id":"b","text":"Kidney"},{"id":"c","text":"Skeletal muscle"},{"id":"d","text":"Adipose tissue"}],"answerId":"a","explanation":"The liver plays a central role in gluconeogenesis, especially during fasting states.","kind":"recall","origin":"ai"},{"id":"organ-specific-fuel-metabolism~ai-1","moduleId":"organ-specific-fuel-metabolism","stem":"What is the primary fuel source for red blood cells?","options":[{"id":"a","text":"Fatty acids"},{"id":"b","text":"Glucose"},{"id":"c","text":"Ketones"},{"id":"d","text":"Lactate"}],"answerId":"b","explanation":"Red blood cells lack mitochondria and rely exclusively on glucose for energy, converting it to lactate.","kind":"recall","origin":"ai"},{"id":"organ-specific-fuel-metabolism~ai-2","moduleId":"organ-specific-fuel-metabolism","stem":"During prolonged starvation, which fuel does the brain predominantly utilize?","options":[{"id":"a","text":"Glucose"},{"id":"b","text":"Fatty acids"},{"id":"c","text":"Ketone bodies"},{"id":"d","text":"Lactate"}],"answerId":"c","explanation":"The brain adapts to prolonged starvation by increasing its use of ketone bodies while still requiring some glucose.","kind":"mechanism","origin":"ai"},{"id":"organ-specific-fuel-metabolism~ai-3","moduleId":"organ-specific-fuel-metabolism","stem":"What metabolic product do skeletal muscles primarily export during anaerobic glycolysis?","options":[{"id":"a","text":"Glucose"},{"id":"b","text":"Alanine"},{"id":"c","text":"Lactate"},{"id":"d","text":"Fatty acids"}],"answerId":"c","explanation":"Skeletal muscles convert glucose to lactate during anaerobic conditions and export lactate into the bloodstream.","kind":"recall","origin":"ai"},{"id":"organ-specific-fuel-metabolism~ai-4","moduleId":"organ-specific-fuel-metabolism","stem":"Which of the following statements about brain metabolism during starvation is true?","options":[{"id":"a","text":"The brain switches mainly to free fatty acids."},{"id":"b","text":"The brain uses ketone bodies while retaining some glucose requirement."},{"id":"c","text":"The brain exclusively uses lactate."},{"id":"d","text":"The brain does not utilize any glucose."}],"answerId":"b","explanation":"During starvation, the brain increases its use of ketone bodies while still maintaining a requirement for glucose.","kind":"trap","origin":"ai"},{"id":"organ-specific-fuel-metabolism~ai-5","moduleId":"organ-specific-fuel-metabolism","stem":"How does the kidney contribute to metabolism during prolonged fasting?","options":[{"id":"a","text":"Increases glucose uptake"},{"id":"b","text":"Decreases ammonia production"},{"id":"c","text":"Contributes to gluconeogenesis"},{"id":"d","text":"Increases fatty acid oxidation"}],"answerId":"c","explanation":"The kidney contributes to gluconeogenesis and ammoniagenesis, especially during prolonged fasting.","kind":"recall","origin":"ai"},{"id":"organ-specific-fuel-metabolism~ai-6","moduleId":"organ-specific-fuel-metabolism","stem":"Which organ's metabolic functions are most affected by exercise and stress hormones?","options":[{"id":"a","text":"Liver"},{"id":"b","text":"Brain"},{"id":"c","text":"Adipose tissue"},{"id":"d","text":"Skeletal muscle"}],"answerId":"d","explanation":"Skeletal muscle metabolism is significantly influenced by exercise and stress hormones, adjusting its fuel usage accordingly.","kind":"integration","linkedModuleIds":["exercise-stress-fuel-integration"],"origin":"ai"},{"id":"organ-specific-fuel-metabolism~ai-7","moduleId":"organ-specific-fuel-metabolism","stem":"What is the primary role of the liver in fuel metabolism during stress?","options":[{"id":"a","text":"Store glucose"},{"id":"b","text":"Export VLDL"},{"id":"c","text":"Produce ketones"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"The liver coordinates multiple metabolic functions including glucose storage, VLDL export, and ketone production during stress.","kind":"integration","linkedModuleIds":["exercise-stress-fuel-integration"],"origin":"ai"}],"fed-fasting-starvation":[{"id":"fed-fasting-starvation~ai-0","moduleId":"fed-fasting-starvation","stem":"What is the primary hormonal change that occurs during early fasting?","options":[{"id":"a","text":"Increased insulin"},{"id":"b","text":"Decreased glucagon"},{"id":"c","text":"Decreased insulin"},{"id":"d","text":"Increased cortisol"}],"answerId":"c","explanation":"During early fasting, insulin levels decrease while glucagon levels increase to promote glycogenolysis and gluconeogenesis.","kind":"recall","origin":"ai"},{"id":"fed-fasting-starvation~ai-1","moduleId":"fed-fasting-starvation","stem":"Which metabolic process begins early in fasting and increases as glycogen stores deplete?","options":[{"id":"a","text":"Glycolysis"},{"id":"b","text":"Glycogenolysis"},{"id":"c","text":"Gluconeogenesis"},{"id":"d","text":"Lipolysis"}],"answerId":"c","explanation":"Gluconeogenesis begins early in fasting and increases as glycogenolysis declines, contrary to the misconception that it starts only after glycogen is depleted.","kind":"trap","origin":"ai"},{"id":"fed-fasting-starvation~ai-2","moduleId":"fed-fasting-starvation","stem":"What is the primary fuel source for the brain during prolonged starvation?","options":[{"id":"a","text":"Glucose"},{"id":"b","text":"Fatty acids"},{"id":"c","text":"Ketones"},{"id":"d","text":"Amino acids"}],"answerId":"c","explanation":"During prolonged starvation, the brain adapts to use ketones as a primary fuel source, reducing its reliance on glucose.","kind":"recall","origin":"ai"},{"id":"fed-fasting-starvation~ai-3","moduleId":"fed-fasting-starvation","stem":"What clinical finding indicates adaptation to prolonged starvation?","options":[{"id":"a","text":"Increased urinary nitrogen"},{"id":"b","text":"Decreased ketone bodies"},{"id":"c","text":"Falling urinary nitrogen"},{"id":"d","text":"Increased glucose levels"}],"answerId":"c","explanation":"Falling urinary nitrogen indicates that the body is preserving muscle protein by reducing amino acid demand for gluconeogenesis during prolonged starvation.","kind":"recall","origin":"ai"},{"id":"fed-fasting-starvation~ai-4","moduleId":"fed-fasting-starvation","stem":"How does low insulin and high glucagon affect liver metabolism during fasting?","options":[{"id":"a","text":"Promotes glycolysis"},{"id":"b","text":"Inhibits ketogenesis"},{"id":"c","text":"Stimulates gluconeogenesis"},{"id":"d","text":"Increases glycogen synthesis"}],"answerId":"c","explanation":"Low insulin and high glucagon stimulate gluconeogenesis and ketogenesis in the liver during fasting.","kind":"mechanism","origin":"ai"},{"id":"fed-fasting-starvation~ai-5","moduleId":"fed-fasting-starvation","stem":"In the context of metabolic acidosis, which state is characterized by elevated ketones and low-normal glucose?","options":[{"id":"a","text":"Diabetic ketoacidosis"},{"id":"b","text":"Starvation ketosis"},{"id":"c","text":"Lactic acidosis"},{"id":"d","text":"Renal failure"}],"answerId":"b","explanation":"Starvation ketosis is characterized by elevated ketones while glucose levels remain low-normal due to low insulin and high glucagon.","kind":"integration","linkedModuleIds":["high-anion-gap-metabolic-acidosis"],"origin":"ai"},{"id":"fed-fasting-starvation~ai-6","moduleId":"fed-fasting-starvation","stem":"Which metabolic pathway is primarily responsible for supplying acetyl-CoA during prolonged fasting?","options":[{"id":"a","text":"Glycolysis"},{"id":"b","text":"Glycogenolysis"},{"id":"c","text":"β-oxidation"},{"id":"d","text":"Gluconeogenesis"}],"answerId":"c","explanation":"Hepatic β-oxidation of fatty acids provides acetyl-CoA, which is crucial for ketogenesis during prolonged fasting.","kind":"recall","origin":"ai"},{"id":"fed-fasting-starvation~ai-7","moduleId":"fed-fasting-starvation","stem":"How does the body adapt to prolonged fasting in terms of protein metabolism?","options":[{"id":"a","text":"Increases protein synthesis"},{"id":"b","text":"Decreases protein breakdown"},{"id":"c","text":"Increases amino acid demand"},{"id":"d","text":"Decreases urinary nitrogen loss"}],"answerId":"d","explanation":"During prolonged fasting, the body adapts by decreasing urinary nitrogen loss, indicating reduced amino acid demand for gluconeogenesis.","kind":"clinical","origin":"ai"},{"id":"fed-fasting-starvation~ai-8","moduleId":"fed-fasting-starvation","stem":"Which metabolic adaptation occurs when transitioning from a fed state to fasting?","options":[{"id":"a","text":"Increased glucose uptake by muscle"},{"id":"b","text":"Increased fatty acid synthesis"},{"id":"c","text":"Increased ketogenesis"},{"id":"d","text":"Decreased gluconeogenesis"}],"answerId":"c","explanation":"As the body transitions from a fed state to fasting, ketogenesis increases to provide an alternative fuel source for tissues, particularly the brain.","kind":"integration","linkedModuleIds":["ketogenic-fasting-exercise-adaptation"],"origin":"ai"}],"cholestatic-lab-pattern":[{"id":"cholestatic-lab-pattern~ai-0","moduleId":"cholestatic-lab-pattern","stem":"What laboratory finding is most characteristic of extrahepatic biliary obstruction?","options":[{"id":"a","text":"Elevated AST/ALT"},{"id":"b","text":"Elevated alkaline phosphatase and GGT"},{"id":"c","text":"Elevated unconjugated bilirubin"},{"id":"d","text":"Normal liver enzymes"}],"answerId":"b","explanation":"In extrahepatic biliary obstruction, alkaline phosphatase and GGT rise disproportionately compared to AST and ALT.","kind":"recall","origin":"ai"},{"id":"cholestatic-lab-pattern~ai-1","moduleId":"cholestatic-lab-pattern","stem":"Which of the following findings is indicative of conjugated hyperbilirubinemia?","options":[{"id":"a","text":"Pale stool"},{"id":"b","text":"Dark urine"},{"id":"c","text":"Elevated AST"},{"id":"d","text":"Normal urine color"}],"answerId":"b","explanation":"Conjugated bilirubin is water-soluble and can enter urine, leading to dark urine.","kind":"recall","origin":"ai"},{"id":"cholestatic-lab-pattern~ai-2","moduleId":"cholestatic-lab-pattern","stem":"What mechanism leads to elevated alkaline phosphatase in cholestatic liver disease?","options":[{"id":"a","text":"Hepatocyte necrosis"},{"id":"b","text":"Bile-duct epithelial induction"},{"id":"c","text":"Increased bilirubin production"},{"id":"d","text":"Decreased bile acid synthesis"}],"answerId":"b","explanation":"Bile-duct epithelial cells undergo induction in response to bile retention, leading to elevated alkaline phosphatase.","kind":"mechanism","origin":"ai"},{"id":"cholestatic-lab-pattern~ai-3","moduleId":"cholestatic-lab-pattern","stem":"A patient presents with jaundice, dark urine, and pale stools. Which test should be performed first to assess for biliary obstruction?","options":[{"id":"a","text":"Liver biopsy"},{"id":"b","text":"CT scan"},{"id":"c","text":"Ultrasound"},{"id":"d","text":"ERCP"}],"answerId":"c","explanation":"Ultrasound is the first-line imaging modality to evaluate for duct dilation and gallstones in suspected biliary obstruction.","kind":"clinical","origin":"ai"},{"id":"cholestatic-lab-pattern~ai-4","moduleId":"cholestatic-lab-pattern","stem":"Why does unconjugated bilirubin not appear in urine?","options":[{"id":"a","text":"It is not water-soluble"},{"id":"b","text":"It is filtered by the kidneys"},{"id":"c","text":"It is conjugated in the liver"},{"id":"d","text":"It is bound to albumin"}],"answerId":"d","explanation":"Unconjugated bilirubin is bound to albumin, preventing it from being filtered by the kidneys and appearing in urine.","kind":"trap","origin":"ai"},{"id":"cholestatic-lab-pattern~ai-5","moduleId":"cholestatic-lab-pattern","stem":"In a patient with cholestatic jaundice, which of the following is most likely to be elevated?","options":[{"id":"a","text":"Serum albumin"},{"id":"b","text":"Serum AST"},{"id":"c","text":"Serum alkaline phosphatase"},{"id":"d","text":"Serum creatinine"}],"answerId":"c","explanation":"In cholestatic jaundice, alkaline phosphatase levels rise significantly due to bile duct obstruction.","kind":"recall","origin":"ai"},{"id":"cholestatic-lab-pattern~ai-6","moduleId":"cholestatic-lab-pattern","stem":"How does cholestatic liver disease affect fat-soluble vitamin absorption?","options":[{"id":"a","text":"Increases absorption of vitamin K"},{"id":"b","text":"Decreases absorption of vitamin D"},{"id":"c","text":"Increases absorption of vitamin A"},{"id":"d","text":"Decreases absorption of vitamin E"}],"answerId":"d","explanation":"Cholestasis leads to impaired absorption of fat-soluble vitamins, including vitamin E, due to reduced bile flow.","kind":"integration","linkedModuleIds":["cholangitis-bile-vitamin-loss"],"origin":"ai"},{"id":"cholestatic-lab-pattern~ai-7","moduleId":"cholestatic-lab-pattern","stem":"A patient with obstructive jaundice has elevated alkaline phosphatase and GGT. Which linked condition may also be present?","options":[{"id":"a","text":"Hepatitis"},{"id":"b","text":"Cholecystitis"},{"id":"c","text":"Hemolytic anemia"},{"id":"d","text":"Pancreatitis"}],"answerId":"b","explanation":"Cholecystitis can occur alongside obstructive jaundice due to gallstone obstruction of the bile duct.","kind":"integration","linkedModuleIds":["gallstones-cholecystitis-cholangitis"],"origin":"ai"}],"lipoproteins-atherogenesis":[{"id":"lipoproteins-atherogenesis~ai-0","moduleId":"lipoproteins-atherogenesis","stem":"What is the primary function of apoC-II in lipoprotein metabolism?","options":[{"id":"a","text":"Activates lipoprotein lipase"},{"id":"b","text":"Binds to LDL receptors"},{"id":"c","text":"Facilitates cholesterol esterification"},{"id":"d","text":"Mediates remnant uptake"}],"answerId":"a","explanation":"ApoC-II is essential for activating lipoprotein lipase, which hydrolyzes triglycerides in lipoproteins.","kind":"recall","origin":"ai"},{"id":"lipoproteins-atherogenesis~ai-1","moduleId":"lipoproteins-atherogenesis","stem":"Which lipoprotein is primarily responsible for delivering dietary triglycerides to tissues?","options":[{"id":"a","text":"LDL"},{"id":"b","text":"VLDL"},{"id":"c","text":"Chylomicrons"},{"id":"d","text":"HDL"}],"answerId":"c","explanation":"Chylomicrons are the lipoproteins that transport dietary triglycerides from the intestines to peripheral tissues.","kind":"recall","origin":"ai"},{"id":"lipoproteins-atherogenesis~ai-2","moduleId":"lipoproteins-atherogenesis","stem":"In familial hypercholesterolemia, what is the primary defect affecting LDL levels?","options":[{"id":"a","text":"Impaired LPL activity"},{"id":"b","text":"Defective apoE binding"},{"id":"c","text":"Impaired LDL receptor clearance"},{"id":"d","text":"Increased HDL synthesis"}],"answerId":"c","explanation":"Familial hypercholesterolemia is characterized by a defect in the LDL receptor pathway, leading to elevated LDL levels.","kind":"mechanism","origin":"ai"},{"id":"lipoproteins-atherogenesis~ai-3","moduleId":"lipoproteins-atherogenesis","stem":"What clinical finding is associated with severe chylomicronemia?","options":[{"id":"a","text":"Tendon xanthomas"},{"id":"b","text":"Eruptive xanthomas"},{"id":"c","text":"Corneal arcus"},{"id":"d","text":"Xanthelasma"}],"answerId":"b","explanation":"Eruptive xanthomas are a classic finding in severe chylomicronemia due to impaired lipoprotein lipase activity.","kind":"clinical","origin":"ai"},{"id":"lipoproteins-atherogenesis~ai-4","moduleId":"lipoproteins-atherogenesis","stem":"Which apolipoprotein is the ligand for the LDL receptor?","options":[{"id":"a","text":"ApoB-48"},{"id":"b","text":"ApoB-100"},{"id":"c","text":"ApoE"},{"id":"d","text":"ApoA-I"}],"answerId":"b","explanation":"ApoB-100 is the primary ligand for the LDL receptor, allowing for receptor-mediated endocytosis of LDL.","kind":"trap","origin":"ai"},{"id":"lipoproteins-atherogenesis~ai-5","moduleId":"lipoproteins-atherogenesis","stem":"How does HDL contribute to reverse cholesterol transport?","options":[{"id":"a","text":"By delivering cholesterol to tissues"},{"id":"b","text":"By activating lipoprotein lipase"},{"id":"c","text":"By mediating remnant uptake"},{"id":"d","text":"By facilitating cholesterol esterification"}],"answerId":"d","explanation":"HDL supports reverse cholesterol transport primarily through the action of LCAT, which esterifies cholesterol for transport back to the liver.","kind":"mechanism","origin":"ai"},{"id":"lipoproteins-atherogenesis~ai-6","moduleId":"lipoproteins-atherogenesis","stem":"How does the mechanism of atherosclerosis relate to lipoprotein metabolism?","options":[{"id":"a","text":"Increased HDL levels lead to plaque formation"},{"id":"b","text":"LDL retention in the arterial intima causes inflammation"},{"id":"c","text":"Chylomicrons promote endothelial repair"},{"id":"d","text":"VLDL is protective against atherosclerosis"}],"answerId":"b","explanation":"Retention of apoB-containing lipoproteins like LDL in the arterial intima triggers inflammation and plaque formation, linking lipoprotein metabolism to atherosclerosis.","kind":"integration","linkedModuleIds":["atherosclerosis"],"origin":"ai"},{"id":"lipoproteins-atherogenesis~ai-7","moduleId":"lipoproteins-atherogenesis","stem":"What role does apoE play in lipoprotein metabolism and its connection to atherosclerosis?","options":[{"id":"a","text":"Facilitates LDL receptor binding"},{"id":"b","text":"Activates lipoprotein lipase"},{"id":"c","text":"Mediates remnant uptake by the liver"},{"id":"d","text":"Increases HDL levels"}],"answerId":"c","explanation":"ApoE is crucial for the hepatic uptake of remnant lipoproteins, and its dysfunction can contribute to atherosclerotic processes.","kind":"integration","linkedModuleIds":["atherosclerosis"],"origin":"ai"}],"alternative-fatty-acid-oxidation":[{"id":"alternative-fatty-acid-oxidation~ai-0","moduleId":"alternative-fatty-acid-oxidation","stem":"What is the primary defect in X-linked adrenoleukodystrophy?","options":[{"id":"a","text":"Defective mitochondrial β-oxidation"},{"id":"b","text":"Impaired peroxisomal VLCFA import"},{"id":"c","text":"Deficiency of phytanoyl-CoA hydroxylase"},{"id":"d","text":"Inability to synthesize essential fatty acids"}],"answerId":"b","explanation":"X-linked adrenoleukodystrophy is caused by a defect in the ABCD1 gene, which impairs the import of very-long-chain fatty acids into peroxisomes.","kind":"recall","origin":"ai"},{"id":"alternative-fatty-acid-oxidation~ai-1","moduleId":"alternative-fatty-acid-oxidation","stem":"Which fatty acid oxidation pathway is responsible for handling branched-chain fatty acids like phytanic acid?","options":[{"id":"a","text":"β-oxidation"},{"id":"b","text":"α-oxidation"},{"id":"c","text":"ω-oxidation"},{"id":"d","text":"Peroxisomal oxidation"}],"answerId":"b","explanation":"α-Oxidation specifically handles branched-chain fatty acids that cannot undergo standard β-oxidation.","kind":"recall","origin":"ai"},{"id":"alternative-fatty-acid-oxidation~ai-2","moduleId":"alternative-fatty-acid-oxidation","stem":"A 5-year-old boy presents with progressive neurologic decline and adrenal insufficiency. Which fatty acid accumulation is most likely responsible?","options":[{"id":"a","text":"Palmitic acid"},{"id":"b","text":"Stearic acid"},{"id":"c","text":"Very-long-chain fatty acids"},{"id":"d","text":"Phytanic acid"}],"answerId":"c","explanation":"The symptoms are indicative of X-linked adrenoleukodystrophy, which involves the accumulation of very-long-chain fatty acids due to impaired peroxisomal import.","kind":"clinical","origin":"ai"},{"id":"alternative-fatty-acid-oxidation~ai-3","moduleId":"alternative-fatty-acid-oxidation","stem":"What is the end product of odd-chain fatty acid β-oxidation?","options":[{"id":"a","text":"Acetyl-CoA"},{"id":"b","text":"Propionyl-CoA"},{"id":"c","text":"Methylmalonyl-CoA"},{"id":"d","text":"Succinyl-CoA"}],"answerId":"d","explanation":"Odd-chain fatty acid β-oxidation ends with succinyl-CoA after conversion from propionyl-CoA and methylmalonyl-CoA.","kind":"recall","origin":"ai"},{"id":"alternative-fatty-acid-oxidation~ai-4","moduleId":"alternative-fatty-acid-oxidation","stem":"Which statement about peroxisomal β-oxidation is correct?","options":[{"id":"a","text":"It produces ATP directly from the first oxidation step."},{"id":"b","text":"It produces hydrogen peroxide instead of ATP."},{"id":"c","text":"It is the primary energy source for cells."},{"id":"d","text":"It occurs exclusively in mitochondria."}],"answerId":"b","explanation":"Peroxisomal acyl-CoA oxidase passes electrons directly to oxygen, producing hydrogen peroxide rather than ATP.","kind":"trap","origin":"ai"},{"id":"alternative-fatty-acid-oxidation~ai-5","moduleId":"alternative-fatty-acid-oxidation","stem":"In Refsum disease, which clinical finding is most characteristic?","options":[{"id":"a","text":"Adrenal insufficiency"},{"id":"b","text":"Retinitis pigmentosa"},{"id":"c","text":"Neurologic white matter disease"},{"id":"d","text":"Very-long-chain fatty acid accumulation"}],"answerId":"b","explanation":"Refsum disease is characterized by retinitis pigmentosa, neuropathy, and ataxia due to defective α-oxidation of phytanic acid.","kind":"clinical","origin":"ai"},{"id":"alternative-fatty-acid-oxidation~ai-6","moduleId":"alternative-fatty-acid-oxidation","stem":"How does peroxisomal β-oxidation differ from mitochondrial β-oxidation?","options":[{"id":"a","text":"It produces ATP directly."},{"id":"b","text":"It handles branched-chain fatty acids."},{"id":"c","text":"It generates hydrogen peroxide."},{"id":"d","text":"It occurs in the cytoplasm."}],"answerId":"c","explanation":"Peroxisomal β-oxidation generates hydrogen peroxide instead of ATP during the first oxidation step.","kind":"mechanism","origin":"ai"},{"id":"alternative-fatty-acid-oxidation~ai-7","moduleId":"alternative-fatty-acid-oxidation","stem":"Which of the following pathways is closely related to the metabolism of fatty acids and could be affected in patients with VLCFA accumulation?","options":[{"id":"a","text":"Gustatory pathway"},{"id":"b","text":"Carnitine shuttle"},{"id":"c","text":"Auditory pathway"},{"id":"d","text":"Eicosanoid synthesis"}],"answerId":"b","explanation":"The carnitine shuttle is essential for transporting fatty acids into mitochondria for β-oxidation, which is affected in conditions like VLCFA accumulation.","kind":"integration","linkedModuleIds":["beta-oxidation-carnitine"],"origin":"ai"},{"id":"alternative-fatty-acid-oxidation~ai-8","moduleId":"alternative-fatty-acid-oxidation","stem":"Which module would provide insight into the synthesis of fatty acids that could be disrupted in metabolic disorders involving fatty acid oxidation?","options":[{"id":"a","text":"Auditory pathway"},{"id":"b","text":"Gustatory pathway"},{"id":"c","text":"Fatty-acid synthesis and eicosanoids"},{"id":"d","text":"Beta-oxidation and carnitine"}],"answerId":"c","explanation":"The fatty-acid synthesis and eicosanoids module would provide relevant information on the synthesis pathways that could be disrupted in fatty acid metabolism disorders.","kind":"integration","linkedModuleIds":["fatty-acid-synthesis-eicosanoids"],"origin":"ai"}],"napqi-glutathione-nac":[{"id":"napqi-glutathione-nac~ai-0","moduleId":"napqi-glutathione-nac","stem":"What is the primary mechanism by which acetaminophen overdose leads to liver injury?","options":[{"id":"a","text":"Inhibition of cyclooxygenase"},{"id":"b","text":"Formation of NAPQI due to CYP2E1 activity"},{"id":"c","text":"Increased production of prostaglandins"},{"id":"d","text":"Direct hepatocyte toxicity from acetaminophen"}],"answerId":"b","explanation":"Acetaminophen overdose primarily leads to liver injury through the formation of the reactive metabolite NAPQI via CYP2E1 activity.","kind":"mechanism","origin":"ai"},{"id":"napqi-glutathione-nac~ai-1","moduleId":"napqi-glutathione-nac","stem":"Which clinical finding is most characteristic of acetaminophen-induced liver injury?","options":[{"id":"a","text":"Centrilobular hepatic necrosis"},{"id":"b","text":"Portal hypertension"},{"id":"c","text":"Fatty liver infiltration"},{"id":"d","text":"Chronic hepatitis"}],"answerId":"a","explanation":"Centrilobular hepatic necrosis is characteristic due to high CYP2E1 activity and low oxygen tension in zone 3 of the liver.","kind":"recall","origin":"ai"},{"id":"napqi-glutathione-nac~ai-2","moduleId":"napqi-glutathione-nac","stem":"In which scenario is a patient at higher risk for acetaminophen toxicity?","options":[{"id":"a","text":"Chronic use of NSAIDs"},{"id":"b","text":"Malnutrition"},{"id":"c","text":"Regular exercise"},{"id":"d","text":"High protein diet"}],"answerId":"b","explanation":"Malnutrition decreases glutathione reserves, increasing the risk for acetaminophen toxicity.","kind":"trap","origin":"ai"},{"id":"napqi-glutathione-nac~ai-3","moduleId":"napqi-glutathione-nac","stem":"What is the role of N-acetylcysteine (NAC) in acetaminophen overdose management?","options":[{"id":"a","text":"It directly detoxifies acetaminophen"},{"id":"b","text":"It replenishes glutathione and reduces NAPQI"},{"id":"c","text":"It enhances CYP2E1 activity"},{"id":"d","text":"It prevents protein synthesis"}],"answerId":"b","explanation":"NAC replenishes glutathione levels and can directly reduce NAPQI, thus mitigating liver injury.","kind":"mechanism","origin":"ai"},{"id":"napqi-glutathione-nac~ai-4","moduleId":"napqi-glutathione-nac","stem":"Why can N-acetylcysteine still be beneficial even after liver injury is established?","options":[{"id":"a","text":"It prevents further NAPQI formation"},{"id":"b","text":"It can still improve antioxidant capacity and outcomes"},{"id":"c","text":"It reverses all liver damage"},{"id":"d","text":"It only works if given within 8 hours"}],"answerId":"b","explanation":"NAC can improve antioxidant capacity and outcomes even in established acetaminophen liver injury.","kind":"trap","origin":"ai"},{"id":"napqi-glutathione-nac~ai-5","moduleId":"napqi-glutathione-nac","stem":"How does chronic alcohol use affect the risk of acetaminophen toxicity?","options":[{"id":"a","text":"It decreases CYP2E1 activity"},{"id":"b","text":"It increases glutathione levels"},{"id":"c","text":"It induces CYP2E1 and depletes glutathione"},{"id":"d","text":"It has no effect on acetaminophen metabolism"}],"answerId":"c","explanation":"Chronic alcohol use induces CYP2E1 and depletes glutathione, increasing the risk of acetaminophen toxicity.","kind":"clinical","origin":"ai"},{"id":"napqi-glutathione-nac~ai-6","moduleId":"napqi-glutathione-nac","stem":"How does the mechanism of NAPQI formation relate to acetaminophen overdose patterns?","options":[{"id":"a","text":"NAPQI is formed only in chronic use"},{"id":"b","text":"NAPQI formation is independent of liver function"},{"id":"c","text":"Overdose leads to saturation of glucuronidation and sulfation pathways"},{"id":"d","text":"NAPQI is a product of phase I metabolism only"}],"answerId":"c","explanation":"In overdose, the glucuronidation and sulfation pathways become saturated, leading to increased NAPQI formation.","kind":"integration","linkedModuleIds":["acetaminophen-overdose-pattern"],"origin":"ai"},{"id":"napqi-glutathione-nac~ai-7","moduleId":"napqi-glutathione-nac","stem":"What is the consequence of glutathione depletion in the context of acetaminophen overdose?","options":[{"id":"a","text":"Increased detoxification of NAPQI"},{"id":"b","text":"Increased binding of NAPQI to cellular proteins"},{"id":"c","text":"Decreased formation of acetaminophen"},{"id":"d","text":"Increased liver regeneration"}],"answerId":"b","explanation":"Glutathione depletion allows NAPQI to bind to cellular and mitochondrial proteins, leading to liver injury.","kind":"integration","linkedModuleIds":["nsaid-acetaminophen-safety"],"origin":"ai"}],"alcohol-aldh2-cirrhosis":[{"id":"alcohol-aldh2-cirrhosis~ai-0","moduleId":"alcohol-aldh2-cirrhosis","stem":"What is the primary enzyme responsible for converting ethanol to acetaldehyde?","options":[{"id":"a","text":"Alcohol dehydrogenase"},{"id":"b","text":"Aldehyde dehydrogenase"},{"id":"c","text":"Acetaldehyde dehydrogenase"},{"id":"d","text":"Cytochrome P450"}],"answerId":"a","explanation":"Alcohol dehydrogenase is the key enzyme that catalyzes the oxidation of ethanol to acetaldehyde.","kind":"recall","origin":"ai"},{"id":"alcohol-aldh2-cirrhosis~ai-1","moduleId":"alcohol-aldh2-cirrhosis","stem":"In ALDH2 deficiency, what is the primary cause of facial flushing after alcohol consumption?","options":[{"id":"a","text":"Increased acetaldehyde levels"},{"id":"b","text":"Decreased ethanol metabolism"},{"id":"c","text":"Increased NADH production"},{"id":"d","text":"Decreased blood flow"}],"answerId":"a","explanation":"Facial flushing occurs due to the accumulation of acetaldehyde, which is not efficiently metabolized in ALDH2 deficiency.","kind":"mechanism","origin":"ai"},{"id":"alcohol-aldh2-cirrhosis~ai-2","moduleId":"alcohol-aldh2-cirrhosis","stem":"Which finding is characteristic of chronic alcohol-related liver injury?","options":[{"id":"a","text":"ALT greater than AST"},{"id":"b","text":"AST greater than ALT"},{"id":"c","text":"Normal AST and ALT"},{"id":"d","text":"Elevated alkaline phosphatase"}],"answerId":"b","explanation":"In chronic alcohol injury, AST levels are typically greater than ALT levels due to mitochondrial injury.","kind":"recall","origin":"ai"},{"id":"alcohol-aldh2-cirrhosis~ai-3","moduleId":"alcohol-aldh2-cirrhosis","stem":"What is the consequence of high NADH levels in alcohol metabolism?","options":[{"id":"a","text":"Increased gluconeogenesis"},{"id":"b","text":"Inhibition of fatty acid oxidation"},{"id":"c","text":"Increased lactate production"},{"id":"d","text":"Decreased glycerol-3-phosphate accumulation"}],"answerId":"b","explanation":"High NADH levels inhibit fatty acid oxidation and promote the accumulation of glycerol-3-phosphate, leading to fatty liver.","kind":"mechanism","origin":"ai"},{"id":"alcohol-aldh2-cirrhosis~ai-4","moduleId":"alcohol-aldh2-cirrhosis","stem":"Which statement about ALDH2 deficiency is true?","options":[{"id":"a","text":"Flushing completely protects against alcohol-related diseases"},{"id":"b","text":"Acetaldehyde exposure is toxic despite flushing"},{"id":"c","text":"ALDH2 deficiency is harmless"},{"id":"d","text":"Flushing indicates safe alcohol consumption"}],"answerId":"b","explanation":"Flushing may reduce drinking but does not eliminate the toxic effects of acetaldehyde, which can still cause harm.","kind":"trap","origin":"ai"},{"id":"alcohol-aldh2-cirrhosis~ai-5","moduleId":"alcohol-aldh2-cirrhosis","stem":"How does chronic alcohol consumption lead to cirrhosis?","options":[{"id":"a","text":"By activating hepatocytes"},{"id":"b","text":"By promoting stellate cell activation and collagen deposition"},{"id":"c","text":"By increasing bile acid production"},{"id":"d","text":"By enhancing detoxification pathways"}],"answerId":"b","explanation":"Chronic alcohol consumption activates stellate cells, leading to collagen deposition and fibrosis, which contributes to cirrhosis.","kind":"mechanism","origin":"ai"},{"id":"alcohol-aldh2-cirrhosis~ai-6","moduleId":"alcohol-aldh2-cirrhosis","stem":"How does hyperammonemia relate to ALDH2 deficiency in patients with cirrhosis?","options":[{"id":"a","text":"Increased ammonia detoxification"},{"id":"b","text":"Decreased ammonia production"},{"id":"c","text":"Impaired ammonia detoxification"},{"id":"d","text":"Normal ammonia levels"}],"answerId":"c","explanation":"Cirrhosis impairs the liver's ability to detoxify ammonia, leading to hyperammonemia, which is exacerbated in patients with ALDH2 deficiency due to liver dysfunction.","kind":"integration","linkedModuleIds":["hepatic-encephalopathy-ammonia"],"origin":"ai"},{"id":"alcohol-aldh2-cirrhosis~ai-7","moduleId":"alcohol-aldh2-cirrhosis","stem":"What is a potential neurological consequence of chronic alcohol use related to ALDH2 deficiency?","options":[{"id":"a","text":"Wernicke's encephalopathy"},{"id":"b","text":"Hepatic encephalopathy"},{"id":"c","text":"Korsakoff syndrome"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"Chronic alcohol use can lead to various neurological conditions, including Wernicke's encephalopathy and Korsakoff syndrome, particularly in the context of ALDH2 deficiency.","kind":"integration","linkedModuleIds":["wernicke-korsakoff"],"origin":"ai"}],"aldolase-b-phosphate-trap":[{"id":"aldolase-b-phosphate-trap~ai-0","moduleId":"aldolase-b-phosphate-trap","stem":"What is the inheritance pattern of hereditary fructose intolerance due to aldolase B deficiency?","options":[{"id":"a","text":"Autosomal dominant"},{"id":"b","text":"Autosomal recessive"},{"id":"c","text":"X-linked recessive"},{"id":"d","text":"Mitochondrial"}],"answerId":"b","explanation":"Hereditary fructose intolerance is inherited in an autosomal recessive manner due to ALDOB deficiency.","kind":"recall","origin":"ai"},{"id":"aldolase-b-phosphate-trap~ai-1","moduleId":"aldolase-b-phosphate-trap","stem":"Which of the following best describes the mechanism of fructose-1-phosphate accumulation in aldolase B deficiency?","options":[{"id":"a","text":"Increased gluconeogenesis"},{"id":"b","text":"Inhibition of fructokinase"},{"id":"c","text":"Unopposed fructokinase activity"},{"id":"d","text":"Enhanced glycogenolysis"}],"answerId":"c","explanation":"In aldolase B deficiency, unopposed fructokinase activity leads to the accumulation of fructose-1-phosphate.","kind":"mechanism","origin":"ai"},{"id":"aldolase-b-phosphate-trap~ai-2","moduleId":"aldolase-b-phosphate-trap","stem":"A child presents with vomiting and hypoglycemia after consuming fruit. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Increased hepatic glucose production"},{"id":"b","text":"Fructose-1-phosphate trapping"},{"id":"c","text":"Enhanced ATP synthesis"},{"id":"d","text":"Decreased insulin secretion"}],"answerId":"b","explanation":"Fructose-1-phosphate trapping blocks hepatic glucose production, leading to hypoglycemia.","kind":"clinical","origin":"ai"},{"id":"aldolase-b-phosphate-trap~ai-3","moduleId":"aldolase-b-phosphate-trap","stem":"Which of the following is a common clinical finding in patients with hereditary fructose intolerance?","options":[{"id":"a","text":"Lifelong aversion to sweets"},{"id":"b","text":"Increased appetite for carbohydrates"},{"id":"c","text":"Persistent hyperglycemia"},{"id":"d","text":"Frequent urination"}],"answerId":"a","explanation":"Patients often develop a lifelong aversion to sweets due to conditioned illness after fructose consumption.","kind":"recall","origin":"ai"},{"id":"aldolase-b-phosphate-trap~ai-4","moduleId":"aldolase-b-phosphate-trap","stem":"Why is an oral fructose challenge not recommended for diagnosing hereditary fructose intolerance?","options":[{"id":"a","text":"It is too expensive"},{"id":"b","text":"It can cause severe hypoglycemia and liver injury"},{"id":"c","text":"It does not provide conclusive results"},{"id":"d","text":"It is only useful in adults"}],"answerId":"b","explanation":"An oral fructose challenge can provoke severe hypoglycemia and liver injury in patients with hereditary fructose intolerance.","kind":"trap","origin":"ai"},{"id":"aldolase-b-phosphate-trap~ai-5","moduleId":"aldolase-b-phosphate-trap","stem":"How does the mechanism of aldolase B deficiency relate to thyroid hormone synthesis?","options":[{"id":"a","text":"Both involve ATP depletion"},{"id":"b","text":"Both are regulated by fructose metabolism"},{"id":"c","text":"Both lead to hypoglycemia"},{"id":"d","text":"Both affect liver function"}],"answerId":"a","explanation":"Both aldolase B deficiency and thyroid hormone synthesis can involve ATP depletion, affecting metabolic processes.","kind":"integration","linkedModuleIds":["hen1-thyroid-hormone-synthesis"],"origin":"ai"},{"id":"aldolase-b-phosphate-trap~ai-6","moduleId":"aldolase-b-phosphate-trap","stem":"In patients with hereditary fructose intolerance, which metabolic complication is most likely to occur due to ATP depletion?","options":[{"id":"a","text":"Lactic acidosis"},{"id":"b","text":"Hyperuricemia"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Ketoacidosis"}],"answerId":"a","explanation":"ATP depletion in hereditary fructose intolerance can lead to lactic acidosis as a metabolic complication.","kind":"integration","linkedModuleIds":["hfi-metabolic-complications"],"origin":"ai"}],"mcad-diagnosis-prevention":[{"id":"mcad-diagnosis-prevention~ai-0","moduleId":"mcad-diagnosis-prevention","stem":"What is the primary method for confirming MCAD deficiency after newborn screening?","options":[{"id":"a","text":"Plasma acylcarnitines"},{"id":"b","text":"Urine organic acids"},{"id":"c","text":"Biallelic ACADM variants"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"Confirmation of MCAD deficiency involves analyzing plasma acylcarnitines, urine organic acids, and identifying biallelic ACADM variants.","kind":"recall","origin":"ai"},{"id":"mcad-diagnosis-prevention~ai-1","moduleId":"mcad-diagnosis-prevention","stem":"Which complication is most associated with prolonged fasting in MCAD deficiency?","options":[{"id":"a","text":"Seizures"},{"id":"b","text":"Hypoglycemic brain injury"},{"id":"c","text":"Hepatic dysfunction"},{"id":"d","text":"Arrhythmia"}],"answerId":"b","explanation":"Hypoglycemic brain injury is a critical complication that can occur due to prolonged fasting in patients with MCAD deficiency.","kind":"recall","origin":"ai"},{"id":"mcad-diagnosis-prevention~ai-2","moduleId":"mcad-diagnosis-prevention","stem":"During a metabolic crisis, which exam finding is most likely in a patient with MCAD deficiency?","options":[{"id":"a","text":"Normal development"},{"id":"b","text":"Rapid deterioration after vomiting"},{"id":"c","text":"Stable glucose levels"},{"id":"d","text":"Elevated ketones"}],"answerId":"b","explanation":"Patients with MCAD deficiency typically show rapid deterioration after a vomiting illness due to glycogen depletion and failed fat utilization.","kind":"recall","origin":"ai"},{"id":"mcad-diagnosis-prevention~ai-3","moduleId":"mcad-diagnosis-prevention","stem":"What is the primary mechanism of action for preventing complications in MCAD deficiency?","options":[{"id":"a","text":"Dietary fat restriction"},{"id":"b","text":"Avoiding fasting"},{"id":"c","text":"Increased protein intake"},{"id":"d","text":"Frequent high-fat meals"}],"answerId":"b","explanation":"Avoiding fasting is crucial in preventing catabolism and subsequent complications in MCAD deficiency.","kind":"mechanism","origin":"ai"},{"id":"mcad-diagnosis-prevention~ai-4","moduleId":"mcad-diagnosis-prevention","stem":"Which of the following statements about dietary management in MCAD deficiency is true?","options":[{"id":"a","text":"All dietary fat must be eliminated"},{"id":"b","text":"Balanced nutrition is essential"},{"id":"c","text":"High carbohydrate intake is discouraged"},{"id":"d","text":"Protein should be the primary energy source"}],"answerId":"b","explanation":"Balanced nutrition, guided by the metabolic team, is essential for managing MCAD deficiency, as essential fats are still important.","kind":"trap","origin":"ai"},{"id":"mcad-diagnosis-prevention~ai-5","moduleId":"mcad-diagnosis-prevention","stem":"How does MCAD deficiency relate to fatty-acid β-oxidation?","options":[{"id":"a","text":"It enhances β-oxidation"},{"id":"b","text":"It inhibits β-oxidation"},{"id":"c","text":"It has no relation"},{"id":"d","text":"It only affects carnitine transport"}],"answerId":"b","explanation":"MCAD deficiency inhibits the β-oxidation of fatty acids, leading to metabolic crises during catabolic stress.","kind":"integration","linkedModuleIds":["beta-oxidation-carnitine"],"origin":"ai"},{"id":"mcad-diagnosis-prevention~ai-6","moduleId":"mcad-diagnosis-prevention","stem":"What is the connection between MCAD deficiency and hypoketotic hypoglycemia?","options":[{"id":"a","text":"Both result from excess ketone production"},{"id":"b","text":"Both involve impaired fatty acid metabolism"},{"id":"c","text":"Both are caused by carbohydrate overload"},{"id":"d","text":"Both lead to increased ketone bodies"}],"answerId":"b","explanation":"MCAD deficiency and hypoketotic hypoglycemia both involve impaired fatty acid metabolism, leading to hypoglycemic episodes.","kind":"integration","linkedModuleIds":["mcad-hypoketotic-hypoglycemia"],"origin":"ai"}],"hemolysis-workup-triggers":[{"id":"hemolysis-workup-triggers~ai-0","moduleId":"hemolysis-workup-triggers","stem":"What laboratory finding is most indicative of intravascular hemolysis?","options":[{"id":"a","text":"High haptoglobin"},{"id":"b","text":"High unconjugated bilirubin"},{"id":"c","text":"Hemoglobinuria"},{"id":"d","text":"Low LDH"}],"answerId":"c","explanation":"Hemoglobinuria is a key indicator of intravascular hemolysis due to the release of free hemoglobin into the urine.","kind":"recall","origin":"ai"},{"id":"hemolysis-workup-triggers~ai-1","moduleId":"hemolysis-workup-triggers","stem":"Which oxidative trigger is commonly associated with G6PD deficiency?","options":[{"id":"a","text":"Chloroquine"},{"id":"b","text":"Dapsone"},{"id":"c","text":"Ibuprofen"},{"id":"d","text":"Aspirin"}],"answerId":"b","explanation":"Dapsone is known to trigger hemolysis in patients with G6PD deficiency due to its oxidative properties.","kind":"recall","origin":"ai"},{"id":"hemolysis-workup-triggers~ai-2","moduleId":"hemolysis-workup-triggers","stem":"In a patient with G6PD deficiency, what would you expect to find on a urine dipstick?","options":[{"id":"a","text":"Positive for bilirubin"},{"id":"b","text":"Positive for blood with few RBCs"},{"id":"c","text":"Negative for blood"},{"id":"d","text":"Positive for glucose"}],"answerId":"b","explanation":"The urine dipstick may show positive for blood due to hemoglobinuria, even when few RBCs are present.","kind":"recall","origin":"ai"},{"id":"hemolysis-workup-triggers~ai-3","moduleId":"hemolysis-workup-triggers","stem":"What is the primary mechanism behind reticulocytosis observed in hemolysis?","options":[{"id":"a","text":"Increased RBC destruction"},{"id":"b","text":"Marrow compensation for RBC loss"},{"id":"c","text":"Decreased erythropoietin levels"},{"id":"d","text":"Increased iron availability"}],"answerId":"b","explanation":"Reticulocytosis occurs as the bone marrow compensates for the shortened lifespan of red blood cells due to hemolysis.","kind":"mechanism","origin":"ai"},{"id":"hemolysis-workup-triggers~ai-4","moduleId":"hemolysis-workup-triggers","stem":"Which of the following statements about dark urine in hemolysis is true?","options":[{"id":"a","text":"It always indicates liver disease"},{"id":"b","text":"It can be due to hemoglobinuria"},{"id":"c","text":"It is always associated with high conjugated bilirubin"},{"id":"d","text":"It indicates renal failure"}],"answerId":"b","explanation":"Dark urine in acute hemolysis may be due to hemoglobinuria rather than true hematuria or liver disease.","kind":"trap","origin":"ai"},{"id":"hemolysis-workup-triggers~ai-5","moduleId":"hemolysis-workup-triggers","stem":"How does G6PD deficiency relate to bilirubin metabolism?","options":[{"id":"a","text":"It increases conjugated bilirubin production"},{"id":"b","text":"It leads to increased hemolysis and unconjugated bilirubin"},{"id":"c","text":"It causes liver dysfunction"},{"id":"d","text":"It decreases bilirubin excretion"}],"answerId":"b","explanation":"G6PD deficiency leads to increased hemolysis, resulting in elevated unconjugated bilirubin levels due to the breakdown of red blood cells.","kind":"integration","linkedModuleIds":["bilirubin-metabolism-jaundice"],"origin":"ai"},{"id":"hemolysis-workup-triggers~ai-6","moduleId":"hemolysis-workup-triggers","stem":"What is the effect of oxidative stress on red blood cells in G6PD deficiency?","options":[{"id":"a","text":"Increased hemoglobin synthesis"},{"id":"b","text":"Decreased RBC lifespan"},{"id":"c","text":"Increased haptoglobin levels"},{"id":"d","text":"Decreased reticulocyte count"}],"answerId":"b","explanation":"Oxidative stress leads to decreased RBC lifespan in individuals with G6PD deficiency due to hemolysis.","kind":"integration","linkedModuleIds":["g6pd-oxidative-hemolysis"],"origin":"ai"}],"galactokinase-cataracts":[{"id":"galactokinase-cataracts~ai-0","moduleId":"galactokinase-cataracts","stem":"What is the primary enzyme deficiency in galactokinase deficiency?","options":[{"id":"a","text":"Galactose-1-phosphate uridyltransferase"},{"id":"b","text":"Galactokinase"},{"id":"c","text":"Aldose reductase"},{"id":"d","text":"Lactase"}],"answerId":"b","explanation":"Galactokinase deficiency is caused by a lack of the enzyme galactokinase, which is essential for converting galactose to galactose-1-phosphate.","kind":"recall","origin":"ai"},{"id":"galactokinase-cataracts~ai-1","moduleId":"galactokinase-cataracts","stem":"Which mechanism explains the formation of cataracts in galactokinase deficiency?","options":[{"id":"a","text":"Accumulation of galactose-1-phosphate"},{"id":"b","text":"Conversion of galactose to galactitol"},{"id":"c","text":"Increased oxidative stress from glucose"},{"id":"d","text":"Decreased lens hydration"}],"answerId":"b","explanation":"Excess galactose is converted to galactitol by aldose reductase, which accumulates in the lens and draws water in, leading to cataract formation.","kind":"mechanism","origin":"ai"},{"id":"galactokinase-cataracts~ai-2","moduleId":"galactokinase-cataracts","stem":"A 3-month-old infant presents with bilateral cataracts after milk exposure. Urine analysis shows reducing sugars but a negative glucose dipstick. What is the most likely diagnosis?","options":[{"id":"a","text":"Classic galactosemia"},{"id":"b","text":"Galactokinase deficiency"},{"id":"c","text":"Lactose intolerance"},{"id":"d","text":"Fructose intolerance"}],"answerId":"b","explanation":"The presence of reducing sugars with a negative glucose dipstick indicates galactose, supporting a diagnosis of galactokinase deficiency.","kind":"clinical","origin":"ai"},{"id":"galactokinase-cataracts~ai-3","moduleId":"galactokinase-cataracts","stem":"Which finding differentiates galactokinase deficiency from classic galactosemia?","options":[{"id":"a","text":"Severe liver disease"},{"id":"b","text":"Elevated galactose-1-phosphate"},{"id":"c","text":"Bilateral cataracts"},{"id":"d","text":"Galactosuria"}],"answerId":"b","explanation":"Classic galactosemia is characterized by elevated galactose-1-phosphate, while galactokinase deficiency typically does not present with severe liver disease or high levels of this metabolite.","kind":"trap","origin":"ai"},{"id":"galactokinase-cataracts~ai-4","moduleId":"galactokinase-cataracts","stem":"In the context of neonatal skin conditions, which complication could arise from galactokinase deficiency?","options":[{"id":"a","text":"Erythema toxicum"},{"id":"b","text":"Candidiasis"},{"id":"c","text":"Seborrheic dermatitis"},{"id":"d","text":"Cataracts"}],"answerId":"d","explanation":"Cataracts can develop in infants with galactokinase deficiency due to galactose exposure, which is relevant in the context of neonatal skin conditions.","kind":"integration","linkedModuleIds":["neonatal-skin-conditions"],"origin":"ai"},{"id":"galactokinase-cataracts~ai-5","moduleId":"galactokinase-cataracts","stem":"How does the dietary management of galactosemia differ between classic GALT deficiency and galactokinase deficiency?","options":[{"id":"a","text":"Both require complete galactose restriction"},{"id":"b","text":"Only GALT deficiency requires lactose restriction"},{"id":"c","text":"Galactokinase deficiency allows for some galactose intake"},{"id":"d","text":"Both can consume galactose without restrictions"}],"answerId":"c","explanation":"Dietary management for galactokinase deficiency is less stringent than for classic GALT deficiency, allowing for some galactose intake.","kind":"integration","linkedModuleIds":["galactosemia-differential-diet"],"origin":"ai"}],"galactosemia-differential-diet":[{"id":"galactosemia-differential-diet~ai-0","moduleId":"galactosemia-differential-diet","stem":"What is the primary metabolic defect in classic galactosemia?","options":[{"id":"a","text":"Galactokinase deficiency"},{"id":"b","text":"Galactose-1-phosphate uridyltransferase deficiency"},{"id":"c","text":"Galactose epimerase deficiency"},{"id":"d","text":"Galactose-6-phosphate dehydrogenase deficiency"}],"answerId":"b","explanation":"Classic galactosemia is caused by a deficiency in galactose-1-phosphate uridyltransferase (GALT), leading to toxic accumulation of galactose-1-phosphate.","kind":"recall","origin":"ai"},{"id":"galactosemia-differential-diet~ai-1","moduleId":"galactosemia-differential-diet","stem":"Which clinical finding is most characteristic of GALK deficiency?","options":[{"id":"a","text":"Hepatomegaly"},{"id":"b","text":"Cataracts without liver dysfunction"},{"id":"c","text":"Jaundice"},{"id":"d","text":"Failure to thrive"}],"answerId":"b","explanation":"GALK deficiency primarily presents with cataracts due to galactitol accumulation, while liver function remains preserved.","kind":"clinical","origin":"ai"},{"id":"galactosemia-differential-diet~ai-2","moduleId":"galactosemia-differential-diet","stem":"What is the mechanism behind the jaundice seen in classic galactosemia?","options":[{"id":"a","text":"Increased bilirubin production"},{"id":"b","text":"Toxic accumulation of galactose-1-phosphate"},{"id":"c","text":"Inhibition of hepatic enzymes"},{"id":"d","text":"Hemolysis due to galactose"}],"answerId":"b","explanation":"Jaundice in classic galactosemia is due to the toxic accumulation of galactose-1-phosphate, which affects liver function.","kind":"mechanism","origin":"ai"},{"id":"galactosemia-differential-diet~ai-3","moduleId":"galactosemia-differential-diet","stem":"Which of the following is a common trap in diagnosing galactosemia?","options":[{"id":"a","text":"Positive urine reducing substance test indicates GALT deficiency"},{"id":"b","text":"Galactose levels in urine confirm GALK deficiency"},{"id":"c","text":"Elevated Gal-1-P is diagnostic for all types of galactosemia"},{"id":"d","text":"Cataracts are exclusive to GALK deficiency"}],"answerId":"a","explanation":"A positive urine reducing substance test cannot distinguish between different enzyme deficiencies and does not confirm GALT deficiency specifically.","kind":"trap","origin":"ai"},{"id":"galactosemia-differential-diet~ai-4","moduleId":"galactosemia-differential-diet","stem":"In a newborn with suspected classic galactosemia, which test is most definitive for diagnosis?","options":[{"id":"a","text":"Urine reducing substance test"},{"id":"b","text":"Plasma galactose level"},{"id":"c","text":"Galactose-1-phosphate assay"},{"id":"d","text":"Liver function tests"}],"answerId":"c","explanation":"The galactose-1-phosphate assay is definitive for diagnosing classic galactosemia by identifying the accumulation of this toxic metabolite.","kind":"recall","origin":"ai"},{"id":"galactosemia-differential-diet~ai-5","moduleId":"galactosemia-differential-diet","stem":"How does GALK deficiency differ from classic GALT deficiency in terms of clinical presentation?","options":[{"id":"a","text":"GALK presents with jaundice, GALT does not"},{"id":"b","text":"GALK presents with cataracts, GALT presents with hepatomegaly"},{"id":"c","text":"GALT presents with cataracts, GALK does not"},{"id":"d","text":"GALT presents with E. coli sepsis, GALK does not"}],"answerId":"b","explanation":"GALK deficiency primarily presents with cataracts without liver dysfunction, while classic GALT deficiency presents with hepatomegaly and other systemic symptoms.","kind":"integration","linkedModuleIds":["galactokinase-cataracts"],"origin":"ai"},{"id":"galactosemia-differential-diet~ai-6","moduleId":"galactosemia-differential-diet","stem":"What is the relationship between classic galactosemia and E. coli infections?","options":[{"id":"a","text":"E. coli infections are common due to immunosuppression"},{"id":"b","text":"E. coli infections are due to liver dysfunction"},{"id":"c","text":"E. coli infections are linked to galactose-1-phosphate accumulation"},{"id":"d","text":"E. coli infections are unrelated to galactose metabolism"}],"answerId":"c","explanation":"Classic galactosemia increases the risk of E. coli sepsis due to the accumulation of galactose-1-phosphate, which impairs immune function.","kind":"integration","linkedModuleIds":["enterobacterales-ecoli-klebsiella"],"origin":"ai"}],"g6pd-oxidative-hemolysis":[{"id":"g6pd-oxidative-hemolysis~ai-0","moduleId":"g6pd-oxidative-hemolysis","stem":"What is the primary role of G6PD in red blood cells?","options":[{"id":"a","text":"To produce ATP"},{"id":"b","text":"To generate NADPH"},{"id":"c","text":"To synthesize hemoglobin"},{"id":"d","text":"To detoxify ammonia"}],"answerId":"b","explanation":"G6PD is crucial for generating NADPH, which is necessary for maintaining reduced glutathione levels in red blood cells.","kind":"recall","origin":"ai"},{"id":"g6pd-oxidative-hemolysis~ai-1","moduleId":"g6pd-oxidative-hemolysis","stem":"Which of the following findings is characteristic of G6PD deficiency after exposure to fava beans?","options":[{"id":"a","text":"Spherocytes on blood smear"},{"id":"b","text":"Bite cells on blood smear"},{"id":"c","text":"Schistocytes on blood smear"},{"id":"d","text":"Reticulocytosis"}],"answerId":"b","explanation":"Bite cells are formed when the spleen removes Heinz bodies from red blood cells in G6PD deficiency.","kind":"recall","origin":"ai"},{"id":"g6pd-oxidative-hemolysis~ai-2","moduleId":"g6pd-oxidative-hemolysis","stem":"What is the mechanism by which G6PD deficiency leads to hemolysis?","options":[{"id":"a","text":"Increased ATP production"},{"id":"b","text":"Decreased NADPH production"},{"id":"c","text":"Increased oxidative stress"},{"id":"d","text":"Decreased glutathione synthesis"}],"answerId":"c","explanation":"The lack of NADPH in G6PD deficiency leads to increased oxidative stress, resulting in hemolysis.","kind":"mechanism","origin":"ai"},{"id":"g6pd-oxidative-hemolysis~ai-3","moduleId":"g6pd-oxidative-hemolysis","stem":"During a hemolytic crisis in G6PD deficiency, why might a G6PD assay appear normal?","options":[{"id":"a","text":"Reticulocytes have higher G6PD levels"},{"id":"b","text":"Older deficient cells have lysed"},{"id":"c","text":"Heinz bodies are not detectable"},{"id":"d","text":"Hemolysis does not affect G6PD levels"}],"answerId":"b","explanation":"Older red blood cells that are deficient in G6PD may have already lysed, leading to a falsely normal assay result.","kind":"trap","origin":"ai"},{"id":"g6pd-oxidative-hemolysis~ai-4","moduleId":"g6pd-oxidative-hemolysis","stem":"A patient presents with jaundice and dark urine after consuming fava beans. What is the expected laboratory finding?","options":[{"id":"a","text":"Elevated bilirubin"},{"id":"b","text":"Decreased reticulocyte count"},{"id":"c","text":"Increased haptoglobin"},{"id":"d","text":"Normal hemoglobin levels"}],"answerId":"a","explanation":"Jaundice and dark urine indicate hemolysis, which typically results in elevated bilirubin levels.","kind":"clinical","origin":"ai"},{"id":"g6pd-oxidative-hemolysis~ai-5","moduleId":"g6pd-oxidative-hemolysis","stem":"How does the pentose phosphate pathway relate to G6PD deficiency?","options":[{"id":"a","text":"It produces ATP for red blood cells"},{"id":"b","text":"It generates NADPH for antioxidant defense"},{"id":"c","text":"It synthesizes heme for hemoglobin"},{"id":"d","text":"It converts glucose to fructose"}],"answerId":"b","explanation":"The pentose phosphate pathway, which includes G6PD, is responsible for generating NADPH, essential for antioxidant defense in red blood cells.","kind":"integration","linkedModuleIds":["pentose-fructose-galactose"],"origin":"ai"},{"id":"g6pd-oxidative-hemolysis~ai-6","moduleId":"g6pd-oxidative-hemolysis","stem":"Which clinical application is relevant for managing patients with G6PD deficiency?","options":[{"id":"a","text":"Use of metformin"},{"id":"b","text":"Administration of thiazolidinediones"},{"id":"c","text":"Avoidance of oxidant drugs"},{"id":"d","text":"Increased dietary fructose"}],"answerId":"c","explanation":"Patients with G6PD deficiency should avoid oxidant drugs to prevent hemolytic crises.","kind":"integration","linkedModuleIds":["metformin-thiazolidinediones"],"origin":"ai"}],"ldl-retention-xanthomas":[{"id":"ldl-retention-xanthomas~ai-0","moduleId":"ldl-retention-xanthomas","stem":"What is the primary mechanism by which modified LDL contributes to atherosclerosis?","options":[{"id":"a","text":"It promotes vasodilation."},{"id":"b","text":"It is taken up by macrophages without feedback control."},{"id":"c","text":"It enhances HDL function."},{"id":"d","text":"It reduces inflammation."}],"answerId":"b","explanation":"Modified LDL is taken up by macrophages via scavenger receptors, which lack normal feedback control, leading to foam cell formation and atherosclerosis.","kind":"mechanism","origin":"ai"},{"id":"ldl-retention-xanthomas~ai-1","moduleId":"ldl-retention-xanthomas","stem":"Which clinical finding is most indicative of cumulative LDL exposure?","options":[{"id":"a","text":"Coronary artery stenosis"},{"id":"b","text":"Tendon xanthomas"},{"id":"c","text":"Elevated triglycerides"},{"id":"d","text":"Hypertension"}],"answerId":"b","explanation":"Tendon xanthomas are visible markers of cumulative LDL exposure due to cholesterol-laden macrophages in connective tissue.","kind":"recall","origin":"ai"},{"id":"ldl-retention-xanthomas~ai-2","moduleId":"ldl-retention-xanthomas","stem":"In the context of LDL retention, what is the role of lipoprotein(a)?","options":[{"id":"a","text":"It decreases LDL levels."},{"id":"b","text":"It resembles plasminogen and carries cholesterol into the arterial wall."},{"id":"c","text":"It enhances HDL function."},{"id":"d","text":"It promotes LDL receptor activity."}],"answerId":"b","explanation":"Lipoprotein(a) resembles plasminogen and carries cholesterol into the arterial wall, contributing to atherogenic risk.","kind":"recall","origin":"ai"},{"id":"ldl-retention-xanthomas~ai-3","moduleId":"ldl-retention-xanthomas","stem":"Why does modified-LDL uptake by macrophages lead to progressive foam-cell formation?","options":[{"id":"a","text":"It is regulated by LDL receptor feedback."},{"id":"b","text":"It occurs without normal cholesterol feedback control."},{"id":"c","text":"It enhances cholesterol efflux."},{"id":"d","text":"It promotes apoptosis in macrophages."}],"answerId":"b","explanation":"Modified-LDL uptake by macrophages lacks the feedback control of the LDL receptor, allowing for continuous foam-cell formation.","kind":"trap","origin":"ai"},{"id":"ldl-retention-xanthomas~ai-4","moduleId":"ldl-retention-xanthomas","stem":"What is a common clinical symptom of premature atherosclerosis due to high LDL levels?","options":[{"id":"a","text":"Chronic cough"},{"id":"b","text":"Tendon pain"},{"id":"c","text":"Heart failure symptoms"},{"id":"d","text":"Skin rash"}],"answerId":"c","explanation":"Premature edema and heart-failure symptoms can arise from severe ischemic heart disease due to lifelong high LDL levels.","kind":"clinical","origin":"ai"},{"id":"ldl-retention-xanthomas~ai-5","moduleId":"ldl-retention-xanthomas","stem":"How does homozygous familial hypercholesterolemia relate to LDL retention and xanthomas?","options":[{"id":"a","text":"It causes increased HDL levels."},{"id":"b","text":"It leads to excessive LDL accumulation and early xanthoma formation."},{"id":"c","text":"It prevents foam cell formation."},{"id":"d","text":"It reduces cardiovascular risk."}],"answerId":"b","explanation":"Homozygous familial hypercholesterolemia results in excessive LDL accumulation, leading to early xanthoma formation and increased cardiovascular risk.","kind":"integration","linkedModuleIds":["homozygous-familial-hypercholesterolemia"],"origin":"ai"},{"id":"ldl-retention-xanthomas~ai-6","moduleId":"ldl-retention-xanthomas","stem":"What is a potential consequence of untreated secondary hyperparathyroidism in CKD related to LDL retention?","options":[{"id":"a","text":"Increased HDL production"},{"id":"b","text":"Decreased LDL levels"},{"id":"c","text":"Worsening cardiovascular disease due to elevated LDL"},{"id":"d","text":"Improved bone health"}],"answerId":"c","explanation":"Untreated secondary hyperparathyroidism can exacerbate cardiovascular disease by maintaining high LDL levels, contributing to atherosclerosis.","kind":"integration","linkedModuleIds":["secondary-hyperparathyroidism-ckd"],"origin":"ai"}],"familial-chylomicronemia-lpl":[{"id":"familial-chylomicronemia-lpl~ai-0","moduleId":"familial-chylomicronemia-lpl","stem":"What is the primary genetic defect in familial chylomicronemia syndrome?","options":[{"id":"a","text":"Defect in LDL receptor"},{"id":"b","text":"Defect in LPL or its cofactors"},{"id":"c","text":"Defect in hepatic triglyceride lipase"},{"id":"d","text":"Defect in apolipoprotein B"}],"answerId":"b","explanation":"Familial chylomicronemia syndrome is primarily caused by defects in lipoprotein lipase (LPL) or its required cofactors.","kind":"recall","origin":"ai"},{"id":"familial-chylomicronemia-lpl~ai-1","moduleId":"familial-chylomicronemia-lpl","stem":"Which clinical finding is most characteristic of familial chylomicronemia?","options":[{"id":"a","text":"Eruptive xanthomas"},{"id":"b","text":"Xanthelasma"},{"id":"c","text":"Corneal arcus"},{"id":"d","text":"Atherosclerotic plaques"}],"answerId":"a","explanation":"Eruptive xanthomas are a hallmark of familial chylomicronemia due to high triglyceride levels.","kind":"recall","origin":"ai"},{"id":"familial-chylomicronemia-lpl~ai-2","moduleId":"familial-chylomicronemia-lpl","stem":"How does apoC-II contribute to lipid metabolism?","options":[{"id":"a","text":"Inhibits LPL activity"},{"id":"b","text":"Activates endothelial LPL"},{"id":"c","text":"Promotes chylomicron synthesis"},{"id":"d","text":"Facilitates HDL formation"}],"answerId":"b","explanation":"ApoC-II is essential for activating endothelial lipoprotein lipase (LPL), which hydrolyzes triglycerides in chylomicrons.","kind":"mechanism","origin":"ai"},{"id":"familial-chylomicronemia-lpl~ai-3","moduleId":"familial-chylomicronemia-lpl","stem":"What is the primary risk associated with familial chylomicronemia syndrome?","options":[{"id":"a","text":"Premature atherosclerosis"},{"id":"b","text":"Recurrent pancreatitis"},{"id":"c","text":"Myocardial infarction"},{"id":"d","text":"Stroke"}],"answerId":"b","explanation":"Recurrent pancreatitis is the defining risk in familial chylomicronemia due to persistent chylomicronemia.","kind":"trap","origin":"ai"},{"id":"familial-chylomicronemia-lpl~ai-4","moduleId":"familial-chylomicronemia-lpl","stem":"A child presents with milky fasting serum and eruptive xanthomas. What is the most likely triglyceride level?","options":[{"id":"a","text":"<200 mg/dL"},{"id":"b","text":"200-500 mg/dL"},{"id":"c","text":"1000-2000 mg/dL"},{"id":"d","text":">2000 mg/dL"}],"answerId":"c","explanation":"Children with familial chylomicronemia typically present with triglyceride levels exceeding 1000-2000 mg/dL.","kind":"clinical","origin":"ai"},{"id":"familial-chylomicronemia-lpl~ai-5","moduleId":"familial-chylomicronemia-lpl","stem":"How does hypertriglyceridemic pancreatitis relate to familial chylomicronemia?","options":[{"id":"a","text":"It is caused by low HDL levels"},{"id":"b","text":"It results from chylomicron accumulation"},{"id":"c","text":"It is unrelated to triglyceride levels"},{"id":"d","text":"It primarily affects LDL metabolism"}],"answerId":"b","explanation":"Hypertriglyceridemic pancreatitis is directly related to the accumulation of chylomicrons in familial chylomicronemia.","kind":"integration","linkedModuleIds":["fcs-pancreatitis-mct"],"origin":"ai"},{"id":"familial-chylomicronemia-lpl~ai-6","moduleId":"familial-chylomicronemia-lpl","stem":"In familial chylomicronemia, why might LDL-C levels remain normal despite high triglycerides?","options":[{"id":"a","text":"Increased VLDL production"},{"id":"b","text":"Reduced LDL receptor activity"},{"id":"c","text":"Selective accumulation of large TAG-rich particles"},{"id":"d","text":"Enhanced HDL synthesis"}],"answerId":"c","explanation":"LDL-C levels may remain normal due to the selective accumulation of large triglyceride-rich particles rather than an increase in LDL.","kind":"integration","linkedModuleIds":["fcs-pancreatitis-mct"],"origin":"ai"}],"homozygous-familial-hypercholesterolemia":[{"id":"homozygous-familial-hypercholesterolemia~ai-0","moduleId":"homozygous-familial-hypercholesterolemia","stem":"What is the primary defect in homozygous familial hypercholesterolemia?","options":[{"id":"a","text":"Impaired hepatic clearance of apoB-containing LDL"},{"id":"b","text":"Increased triglyceride production"},{"id":"c","text":"Enhanced HDL metabolism"},{"id":"d","text":"Decreased cholesterol absorption"}],"answerId":"a","explanation":"The primary defect is impaired hepatic clearance of apoB-containing LDL, primarily due to LDL receptor mutations.","kind":"recall","origin":"ai"},{"id":"homozygous-familial-hypercholesterolemia~ai-1","moduleId":"homozygous-familial-hypercholesterolemia","stem":"Which clinical finding is most indicative of homozygous familial hypercholesterolemia in a child?","options":[{"id":"a","text":"Elevated triglycerides"},{"id":"b","text":"Tendon xanthomas"},{"id":"c","text":"Normal LDL levels"},{"id":"d","text":"Family history of diabetes"}],"answerId":"b","explanation":"Tendon xanthomas are a hallmark clinical finding in homozygous familial hypercholesterolemia due to cholesterol deposition.","kind":"clinical","origin":"ai"},{"id":"homozygous-familial-hypercholesterolemia~ai-2","moduleId":"homozygous-familial-hypercholesterolemia","stem":"What mechanism leads to accelerated atherosclerosis in homozygous familial hypercholesterolemia?","options":[{"id":"a","text":"Increased HDL clearance"},{"id":"b","text":"Macrophage cholesterol deposition"},{"id":"c","text":"Decreased LDL receptor activity"},{"id":"d","text":"Increased triglyceride levels"}],"answerId":"c","explanation":"Decreased LDL receptor activity leads to increased levels of LDL, which contributes to accelerated atherosclerosis.","kind":"mechanism","origin":"ai"},{"id":"homozygous-familial-hypercholesterolemia~ai-3","moduleId":"homozygous-familial-hypercholesterolemia","stem":"A 13-year-old presents with LDL >600 mg/dL and tendon xanthomas. What is the most likely diagnosis?","options":[{"id":"a","text":"Lifestyle hypercholesterolemia"},{"id":"b","text":"Homozygous familial hypercholesterolemia"},{"id":"c","text":"Familial combined hyperlipidemia"},{"id":"d","text":"Secondary hyperlipidemia"}],"answerId":"b","explanation":"The extreme LDL levels and presence of xanthomas suggest a monogenic clearance disorder rather than lifestyle-related hypercholesterolemia.","kind":"trap","origin":"ai"},{"id":"homozygous-familial-hypercholesterolemia~ai-4","moduleId":"homozygous-familial-hypercholesterolemia","stem":"Which of the following is a common consequence of untreated homozygous familial hypercholesterolemia?","options":[{"id":"a","text":"Decreased risk of cardiovascular disease"},{"id":"b","text":"Aortic-root stenosis in adolescence"},{"id":"c","text":"Normal cholesterol levels in adulthood"},{"id":"d","text":"Increased HDL cholesterol"}],"answerId":"b","explanation":"Untreated homozygous familial hypercholesterolemia often leads to aortic-root stenosis and other cardiovascular issues at a young age.","kind":"clinical","origin":"ai"},{"id":"homozygous-familial-hypercholesterolemia~ai-5","moduleId":"homozygous-familial-hypercholesterolemia","stem":"How does the mechanism of LDL retention relate to the formation of xanthomas?","options":[{"id":"a","text":"Increased HDL levels lead to xanthoma formation"},{"id":"b","text":"Cholesterol deposition in macrophages causes xanthomas"},{"id":"c","text":"Xanthomas are formed from triglyceride accumulation"},{"id":"d","text":"Xanthomas result from decreased LDL production"}],"answerId":"b","explanation":"Cholesterol deposition in macrophages due to lifelong extreme LDL levels leads to the formation of xanthomas.","kind":"integration","linkedModuleIds":["ldl-retention-xanthomas"],"origin":"ai"},{"id":"homozygous-familial-hypercholesterolemia~ai-6","moduleId":"homozygous-familial-hypercholesterolemia","stem":"What is the relationship between LDL retention and early cardiovascular disease in homozygous familial hypercholesterolemia?","options":[{"id":"a","text":"LDL retention decreases cardiovascular risk"},{"id":"b","text":"Early cardiovascular disease is unrelated to LDL levels"},{"id":"c","text":"Increased LDL retention accelerates plaque formation"},{"id":"d","text":"LDL retention leads to increased HDL levels"}],"answerId":"c","explanation":"Increased LDL retention due to receptor defects accelerates plaque formation, leading to early cardiovascular disease.","kind":"integration","linkedModuleIds":["ldl-retention-xanthomas"],"origin":"ai"}],"hfi-metabolic-complications":[{"id":"hfi-metabolic-complications~ai-0","moduleId":"hfi-metabolic-complications","stem":"What is the primary metabolic consequence of ATP depletion in hereditary fructose intolerance (HFI)?","options":[{"id":"a","text":"Increased lactate production"},{"id":"b","text":"Increased gluconeogenesis"},{"id":"c","text":"Decreased uric acid production"},{"id":"d","text":"Increased fatty acid synthesis"}],"answerId":"a","explanation":"ATP depletion leads to increased lactate production due to the shift of pyruvate towards lactate in the absence of sufficient energy.","kind":"mechanism","origin":"ai"},{"id":"hfi-metabolic-complications~ai-1","moduleId":"hfi-metabolic-complications","stem":"Which laboratory finding is characteristic of hereditary fructose intolerance after fructose ingestion?","options":[{"id":"a","text":"Hyperglycemia"},{"id":"b","text":"Lactic acidosis"},{"id":"c","text":"Hypokalemia"},{"id":"d","text":"Increased insulin levels"}],"answerId":"b","explanation":"Lactic acidosis is a hallmark finding due to impaired gluconeogenesis and ATP loss in HFI.","kind":"recall","origin":"ai"},{"id":"hfi-metabolic-complications~ai-2","moduleId":"hfi-metabolic-complications","stem":"What is the mechanism behind hyperuricemia in patients with hereditary fructose intolerance?","options":[{"id":"a","text":"Increased uric acid production from purine metabolism"},{"id":"b","text":"Decreased renal excretion of uric acid due to lactate"},{"id":"c","text":"Increased renal excretion of uric acid"},{"id":"d","text":"Decreased production of lactate"}],"answerId":"b","explanation":"Lactate competes with urate for renal excretion, leading to hyperuricemia in the context of ATP depletion.","kind":"mechanism","origin":"ai"},{"id":"hfi-metabolic-complications~ai-3","moduleId":"hfi-metabolic-complications","stem":"A patient presents with hepatomegaly and elevated transaminases after dietary weaning from fructose. What is the most likely underlying cause?","options":[{"id":"a","text":"Increased fatty acid synthesis"},{"id":"b","text":"Hepatocyte injury from energy depletion"},{"id":"c","text":"Increased insulin resistance"},{"id":"d","text":"Decreased bile production"}],"answerId":"b","explanation":"Persistent fructose-1-P and energy depletion injure hepatocytes, causing hepatomegaly and elevated liver enzymes.","kind":"clinical","origin":"ai"},{"id":"hfi-metabolic-complications~ai-4","moduleId":"hfi-metabolic-complications","stem":"Which of the following statements correctly differentiates fructose malabsorption from hereditary fructose intolerance?","options":[{"id":"a","text":"A positive breath test indicates ALDOB deficiency"},{"id":"b","text":"Breath hydrogen reflects intestinal fructose malabsorption"},{"id":"c","text":"HFI is diagnosed by dietary history alone"},{"id":"d","text":"Both conditions present with hypoglycemia"}],"answerId":"b","explanation":"Breath hydrogen reflects intestinal fructose malabsorption, while ALDOB deficiency is a systemic metabolic block.","kind":"trap","origin":"ai"},{"id":"hfi-metabolic-complications~ai-5","moduleId":"hfi-metabolic-complications","stem":"How does the mechanism of ATP depletion in hereditary fructose intolerance relate to the pathophysiology of gout?","options":[{"id":"a","text":"Both conditions involve increased uric acid production"},{"id":"b","text":"Both conditions result from insulin resistance"},{"id":"c","text":"Both conditions lead to hypoglycemia"},{"id":"d","text":"Both conditions are caused by lactate accumulation"}],"answerId":"a","explanation":"In both conditions, increased uric acid production occurs due to disrupted purine metabolism and ATP depletion.","kind":"integration","linkedModuleIds":["nucleotide-degradation-gout"],"origin":"ai"},{"id":"hfi-metabolic-complications~ai-6","moduleId":"hfi-metabolic-complications","stem":"In patients with hereditary fructose intolerance, how does ATP depletion affect glucose metabolism compared to insulin sensitizers like metformin?","options":[{"id":"a","text":"Both increase glucose uptake"},{"id":"b","text":"Both decrease gluconeogenesis"},{"id":"c","text":"HFI leads to impaired glucose metabolism"},{"id":"d","text":"Both enhance ATP production"}],"answerId":"c","explanation":"In HFI, ATP depletion impairs glucose metabolism, contrasting with metformin's role in enhancing insulin sensitivity and promoting glucose uptake.","kind":"integration","linkedModuleIds":["metformin-thiazolidinediones"],"origin":"ai"}],"mcad-hypoketotic-hypoglycemia":[{"id":"mcad-hypoketotic-hypoglycemia~ai-0","moduleId":"mcad-hypoketotic-hypoglycemia","stem":"What is the primary metabolic defect in MCAD deficiency?","options":[{"id":"a","text":"Inhibition of pyruvate dehydrogenase"},{"id":"b","text":"Blockage of medium-chain acyl-CoA dehydrogenase"},{"id":"c","text":"Deficiency of carnitine"},{"id":"d","text":"Failure of the TCA cycle"}],"answerId":"b","explanation":"MCAD deficiency is due to a genetic defect that inhibits medium-chain acyl-CoA dehydrogenase, impairing fatty acid oxidation.","kind":"recall","origin":"ai"},{"id":"mcad-hypoketotic-hypoglycemia~ai-1","moduleId":"mcad-hypoketotic-hypoglycemia","stem":"Which clinical finding is characteristic of hypoketotic hypoglycemia in MCAD deficiency?","options":[{"id":"a","text":"High levels of ketones"},{"id":"b","text":"Normal blood glucose"},{"id":"c","text":"Low blood glucose with low ketones"},{"id":"d","text":"Elevated dicarboxylic acids"}],"answerId":"c","explanation":"In MCAD deficiency, fasting leads to low blood glucose and low ketones due to impaired fatty acid oxidation.","kind":"clinical","origin":"ai"},{"id":"mcad-hypoketotic-hypoglycemia~ai-2","moduleId":"mcad-hypoketotic-hypoglycemia","stem":"How does low acetyl-CoA contribute to hypoketotic hypoglycemia?","options":[{"id":"a","text":"Inhibits gluconeogenesis"},{"id":"b","text":"Stimulates glycolysis"},{"id":"c","text":"Enhances ketogenesis"},{"id":"d","text":"Promotes fatty acid synthesis"}],"answerId":"a","explanation":"Low acetyl-CoA levels inhibit pyruvate carboxylase, reducing gluconeogenesis and contributing to hypoglycemia.","kind":"mechanism","origin":"ai"},{"id":"mcad-hypoketotic-hypoglycemia~ai-3","moduleId":"mcad-hypoketotic-hypoglycemia","stem":"During a metabolic crisis in MCAD deficiency, which of the following is most likely to occur?","options":[{"id":"a","text":"Increased ketone production"},{"id":"b","text":"Elevated blood glucose"},{"id":"c","text":"Severe hypoglycemia"},{"id":"d","text":"Decreased dicarboxylic acids"}],"answerId":"c","explanation":"A metabolic crisis leads to severe hypoglycemia due to the inability to oxidize fatty acids for energy.","kind":"trap","origin":"ai"},{"id":"mcad-hypoketotic-hypoglycemia~ai-4","moduleId":"mcad-hypoketotic-hypoglycemia","stem":"What is the expected urinary finding in a patient with MCAD deficiency?","options":[{"id":"a","text":"Increased ketones"},{"id":"b","text":"Dicarboxylic aciduria"},{"id":"c","text":"Elevated glucose"},{"id":"d","text":"Normal fatty acids"}],"answerId":"b","explanation":"Dicarboxylic aciduria occurs due to compensatory ω-oxidation of accumulating medium-chain fatty acids.","kind":"recall","origin":"ai"},{"id":"mcad-hypoketotic-hypoglycemia~ai-5","moduleId":"mcad-hypoketotic-hypoglycemia","stem":"How does MCAD deficiency affect the metabolism of fatty acids compared to normal physiology?","options":[{"id":"a","text":"Increased β-oxidation"},{"id":"b","text":"Decreased ω-oxidation"},{"id":"c","text":"Increased ketogenesis"},{"id":"d","text":"Decreased fatty acid oxidation"}],"answerId":"d","explanation":"MCAD deficiency leads to decreased fatty acid oxidation, resulting in hypoketotic hypoglycemia.","kind":"mechanism","origin":"ai"},{"id":"mcad-hypoketotic-hypoglycemia~ai-6","moduleId":"mcad-hypoketotic-hypoglycemia","stem":"In the context of MCAD deficiency, how does impaired fatty acid oxidation relate to glucose metabolism?","options":[{"id":"a","text":"Increased gluconeogenesis"},{"id":"b","text":"Decreased insulin sensitivity"},{"id":"c","text":"Inhibition of glycolysis"},{"id":"d","text":"Failure to switch from glucose to fat metabolism"}],"answerId":"d","explanation":"Impaired fatty acid oxidation prevents the body from switching from glucose to fat metabolism during fasting.","kind":"integration","linkedModuleIds":["beta-oxidation-carnitine"],"origin":"ai"},{"id":"mcad-hypoketotic-hypoglycemia~ai-7","moduleId":"mcad-hypoketotic-hypoglycemia","stem":"What is the relationship between MCAD deficiency and the TCA cycle?","options":[{"id":"a","text":"Increased acetyl-CoA availability"},{"id":"b","text":"Decreased pyruvate production"},{"id":"c","text":"Inhibition of the TCA cycle"},{"id":"d","text":"Enhanced energy production from glucose"}],"answerId":"c","explanation":"MCAD deficiency leads to decreased acetyl-CoA production, which can inhibit the TCA cycle due to lack of substrates.","kind":"integration","linkedModuleIds":["pdh-tca-cycle"],"origin":"ai"}],"fcs-pancreatitis-mct":[{"id":"fcs-pancreatitis-mct~ai-0","moduleId":"fcs-pancreatitis-mct","stem":"What is the primary mechanism by which extreme triglyceride levels lead to acute pancreatitis?","options":[{"id":"a","text":"Inhibition of pancreatic lipase"},{"id":"b","text":"Toxicity of unbound fatty acids"},{"id":"c","text":"Increased bile acid secretion"},{"id":"d","text":"Decreased insulin secretion"}],"answerId":"b","explanation":"Extreme triglyceride levels result in the release of unbound fatty acids, which are toxic to pancreatic acinar cells.","kind":"mechanism","origin":"ai"},{"id":"fcs-pancreatitis-mct~ai-1","moduleId":"fcs-pancreatitis-mct","stem":"Which dietary component is primarily responsible for reducing chylomicron burden in patients with hypertriglyceridemic pancreatitis?","options":[{"id":"a","text":"Long-chain fatty acids"},{"id":"b","text":"Medium-chain triglycerides"},{"id":"c","text":"Carbohydrates"},{"id":"d","text":"Proteins"}],"answerId":"b","explanation":"Medium-chain triglycerides (MCT) enter the portal circulation directly, reducing reliance on chylomicron transport.","kind":"recall","origin":"ai"},{"id":"fcs-pancreatitis-mct~ai-2","moduleId":"fcs-pancreatitis-mct","stem":"A patient presents with epigastric pain and vomiting. Laboratory tests show very high triglyceride levels. What is the most likely diagnosis?","options":[{"id":"a","text":"Cholecystitis"},{"id":"b","text":"Acute pancreatitis"},{"id":"c","text":"Peptic ulcer disease"},{"id":"d","text":"Gastritis"}],"answerId":"b","explanation":"Very high triglyceride levels are associated with hypertriglyceridemic acute pancreatitis.","kind":"clinical","origin":"ai"},{"id":"fcs-pancreatitis-mct~ai-3","moduleId":"fcs-pancreatitis-mct","stem":"What effect can lipemic serum samples have on sodium measurement?","options":[{"id":"a","text":"Increase measured sodium"},{"id":"b","text":"Decrease measured sodium"},{"id":"c","text":"No effect on sodium"},{"id":"d","text":"Increase potassium levels"}],"answerId":"b","explanation":"Lipemic samples can cause pseudohyponatremia, artifactually lowering the measured sodium concentration.","kind":"recall","origin":"ai"},{"id":"fcs-pancreatitis-mct~ai-4","moduleId":"fcs-pancreatitis-mct","stem":"Why do medium-chain triglycerides (MCT) help in managing hypertriglyceridemic pancreatitis?","options":[{"id":"a","text":"MCT activates defective LPL"},{"id":"b","text":"MCT reduces dependence on intestinal chylomicron transport"},{"id":"c","text":"MCT increases bile acid production"},{"id":"d","text":"MCT enhances insulin sensitivity"}],"answerId":"b","explanation":"MCT bypasses the blocked transport step by entering the portal circulation more directly, rather than repairing the enzyme.","kind":"trap","origin":"ai"},{"id":"fcs-pancreatitis-mct~ai-5","moduleId":"fcs-pancreatitis-mct","stem":"How does the management of hypertriglyceridemic pancreatitis relate to familial chylomicronemia?","options":[{"id":"a","text":"Both require insulin therapy"},{"id":"b","text":"Both involve dietary fat restriction"},{"id":"c","text":"Both are caused by defective LPL"},{"id":"d","text":"Both lead to increased blood viscosity"}],"answerId":"c","explanation":"Familial chylomicronemia is characterized by defective lipoprotein lipase (LPL), leading to severe hypertriglyceridemia similar to that seen in hypertriglyceridemic pancreatitis.","kind":"integration","linkedModuleIds":["familial-chylomicronemia-lpl"],"origin":"ai"},{"id":"fcs-pancreatitis-mct~ai-6","moduleId":"fcs-pancreatitis-mct","stem":"What is a common nutritional consideration when managing patients with hypertriglyceridemic pancreatitis?","options":[{"id":"a","text":"Complete elimination of all fats"},{"id":"b","text":"Increased intake of long-chain fatty acids"},{"id":"c","text":"Provision of essential long-chain fatty acids and vitamins"},{"id":"d","text":"High carbohydrate intake"}],"answerId":"c","explanation":"While dietary fat restriction is important, it is crucial to still provide essential long-chain fatty acids and fat-soluble vitamins.","kind":"integration","linkedModuleIds":["fatty-acids-membranes"],"origin":"ai"}],"nutritional-ketosis-vs-ketoacidosis":[{"id":"nutritional-ketosis-vs-ketoacidosis~ai-0","moduleId":"nutritional-ketosis-vs-ketoacidosis","stem":"What is the primary hormonal change that initiates nutritional ketosis?","options":[{"id":"a","text":"Increased insulin secretion"},{"id":"b","text":"Decreased glucagon levels"},{"id":"c","text":"Decreased insulin levels"},{"id":"d","text":"Increased cortisol levels"}],"answerId":"c","explanation":"Low carbohydrate intake leads to decreased insulin levels, which promotes lipolysis and ketogenesis.","kind":"recall","origin":"ai"},{"id":"nutritional-ketosis-vs-ketoacidosis~ai-1","moduleId":"nutritional-ketosis-vs-ketoacidosis","stem":"In nutritional ketosis, what happens to blood pH and bicarbonate levels?","options":[{"id":"a","text":"Both decrease significantly"},{"id":"b","text":"Bicarbonate decreases, pH remains normal"},{"id":"c","text":"Both remain near normal"},{"id":"d","text":"Bicarbonate increases, pH decreases"}],"answerId":"c","explanation":"In nutritional ketosis, ketone levels rise modestly while bicarbonate and blood pH remain near normal.","kind":"recall","origin":"ai"},{"id":"nutritional-ketosis-vs-ketoacidosis~ai-2","moduleId":"nutritional-ketosis-vs-ketoacidosis","stem":"Which clinical finding is indicative of severe metabolic ketoacidosis?","options":[{"id":"a","text":"Positive urine ketones"},{"id":"b","text":"Kussmaul breathing"},{"id":"c","text":"Normal blood glucose"},{"id":"d","text":"Elevated bicarbonate levels"}],"answerId":"b","explanation":"Kussmaul breathing is a compensatory response to severe metabolic acidosis, including ketoacidosis.","kind":"recall","origin":"ai"},{"id":"nutritional-ketosis-vs-ketoacidosis~ai-3","moduleId":"nutritional-ketosis-vs-ketoacidosis","stem":"What distinguishes ketoacidosis from nutritional ketosis?","options":[{"id":"a","text":"Presence of urine ketones"},{"id":"b","text":"High insulin levels"},{"id":"c","text":"Acid-base disturbance"},{"id":"d","text":"Normal blood glucose levels"}],"answerId":"c","explanation":"Ketoacidosis is characterized by an acid-base disturbance, whereas nutritional ketosis does not have this disturbance.","kind":"trap","origin":"ai"},{"id":"nutritional-ketosis-vs-ketoacidosis~ai-4","moduleId":"nutritional-ketosis-vs-ketoacidosis","stem":"Which of the following is a key mechanism in the development of ketoacidosis?","options":[{"id":"a","text":"Increased insulin sensitivity"},{"id":"b","text":"Excessive ketone production"},{"id":"c","text":"Decreased glucagon secretion"},{"id":"d","text":"Increased glucose utilization"}],"answerId":"b","explanation":"In ketoacidosis, insulin is absent or ineffective, leading to excessive ketone production that overwhelms utilization.","kind":"mechanism","origin":"ai"},{"id":"nutritional-ketosis-vs-ketoacidosis~ai-5","moduleId":"nutritional-ketosis-vs-ketoacidosis","stem":"How does nutritional ketosis differ from ketoacidosis in terms of insulin levels?","options":[{"id":"a","text":"Insulin is absent in both"},{"id":"b","text":"Insulin is elevated in nutritional ketosis"},{"id":"c","text":"Insulin is low in nutritional ketosis"},{"id":"d","text":"Insulin is high in ketoacidosis"}],"answerId":"c","explanation":"Nutritional ketosis occurs with low insulin levels, while ketoacidosis occurs in the absence or ineffectiveness of insulin.","kind":"integration","linkedModuleIds":["insulin-therapy-regimens"],"origin":"ai"},{"id":"nutritional-ketosis-vs-ketoacidosis~ai-6","moduleId":"nutritional-ketosis-vs-ketoacidosis","stem":"What is a common clinical application of understanding nutritional ketosis?","options":[{"id":"a","text":"Managing hyperglycemia"},{"id":"b","text":"Implementing insulin therapy"},{"id":"c","text":"Designing ketogenic diets"},{"id":"d","text":"Treating acute kidney injury"}],"answerId":"c","explanation":"Understanding nutritional ketosis is essential for designing ketogenic diets for weight loss or metabolic health.","kind":"integration","linkedModuleIds":["ketogenic-fasting-exercise-adaptation"],"origin":"ai"}],"alcoholic-ketoacidosis-redox":[{"id":"alcoholic-ketoacidosis-redox~ai-0","moduleId":"alcoholic-ketoacidosis-redox","stem":"What is the primary metabolic consequence of ethanol oxidation in alcoholic ketoacidosis?","options":[{"id":"a","text":"Increased gluconeogenesis"},{"id":"b","text":"Elevated NADH/NAD+ ratio"},{"id":"c","text":"Enhanced fatty acid oxidation"},{"id":"d","text":"Decreased lactate production"}],"answerId":"b","explanation":"Ethanol oxidation raises the NADH/NAD+ ratio, which inhibits gluconeogenesis and promotes lactate production.","kind":"mechanism","origin":"ai"},{"id":"alcoholic-ketoacidosis-redox~ai-1","moduleId":"alcoholic-ketoacidosis-redox","stem":"Which laboratory finding is most characteristic of alcoholic ketoacidosis?","options":[{"id":"a","text":"Marked hyperglycemia"},{"id":"b","text":"High β-hydroxybutyrate"},{"id":"c","text":"Elevated serum insulin"},{"id":"d","text":"Low anion gap"}],"answerId":"b","explanation":"High β-hydroxybutyrate levels are a hallmark of alcoholic ketoacidosis due to the redox state shift.","kind":"recall","origin":"ai"},{"id":"alcoholic-ketoacidosis-redox~ai-2","moduleId":"alcoholic-ketoacidosis-redox","stem":"A patient presents with tachypnea and abdominal pain after binge drinking. What is a likely finding on their metabolic panel?","options":[{"id":"a","text":"Normal glucose levels"},{"id":"b","text":"Low lactate levels"},{"id":"c","text":"High anion gap"},{"id":"d","text":"Elevated serum insulin"}],"answerId":"c","explanation":"High anion gap metabolic acidosis is expected due to the accumulation of ketoacids.","kind":"clinical","origin":"ai"},{"id":"alcoholic-ketoacidosis-redox~ai-3","moduleId":"alcoholic-ketoacidosis-redox","stem":"Why might urine ketone tests underestimate ketone levels in alcoholic ketoacidosis?","options":[{"id":"a","text":"Acetoacetate is not produced"},{"id":"b","text":"β-hydroxybutyrate predominates"},{"id":"c","text":"Insulin inhibits ketogenesis"},{"id":"d","text":"Lactate interferes with the test"}],"answerId":"b","explanation":"Urine tests primarily detect acetoacetate, while β-hydroxybutyrate is the predominant ketone in this condition.","kind":"trap","origin":"ai"},{"id":"alcoholic-ketoacidosis-redox~ai-4","moduleId":"alcoholic-ketoacidosis-redox","stem":"In a patient with alcoholic ketoacidosis, which hormonal change is most likely contributing to lipolysis?","options":[{"id":"a","text":"Increased insulin"},{"id":"b","text":"Increased glucagon"},{"id":"c","text":"Decreased cortisol"},{"id":"d","text":"Decreased epinephrine"}],"answerId":"b","explanation":"Increased glucagon levels promote lipolysis, contributing to fatty acid delivery to the liver.","kind":"mechanism","origin":"ai"},{"id":"alcoholic-ketoacidosis-redox~ai-5","moduleId":"alcoholic-ketoacidosis-redox","stem":"How does the pathophysiology of alcoholic ketoacidosis relate to starvation states?","options":[{"id":"a","text":"Both increase insulin levels"},{"id":"b","text":"Both promote gluconeogenesis"},{"id":"c","text":"Both involve elevated ketone bodies"},{"id":"d","text":"Both suppress fatty acid oxidation"}],"answerId":"c","explanation":"Both conditions lead to elevated ketone bodies due to increased fatty acid oxidation and ketogenesis.","kind":"integration","linkedModuleIds":["fed-fasting-starvation"],"origin":"ai"},{"id":"alcoholic-ketoacidosis-redox~ai-6","moduleId":"alcoholic-ketoacidosis-redox","stem":"What is a common clinical finding in both alcoholic ketoacidosis and high anion gap metabolic acidosis?","options":[{"id":"a","text":"Low blood glucose"},{"id":"b","text":"High lactate levels"},{"id":"c","text":"Decreased ketone production"},{"id":"d","text":"Increased serum bicarbonate"}],"answerId":"b","explanation":"Both conditions can present with elevated lactate levels due to metabolic acidosis.","kind":"integration","linkedModuleIds":["high-anion-gap-metabolic-acidosis"],"origin":"ai"}],"brca1-tnbc-homologous-repair":[{"id":"brca1-tnbc-homologous-repair~ai-0","moduleId":"brca1-tnbc-homologous-repair","stem":"What is the primary function of the BRCA1 protein in cells?","options":[{"id":"a","text":"Repair of single-strand DNA breaks"},{"id":"b","text":"Coordination of homologous recombination repair"},{"id":"c","text":"Activation of apoptosis pathways"},{"id":"d","text":"Regulation of cell metabolism"}],"answerId":"b","explanation":"BRCA1 is crucial for coordinating the repair of double-strand DNA breaks through homologous recombination.","kind":"recall","origin":"ai"},{"id":"brca1-tnbc-homologous-repair~ai-1","moduleId":"brca1-tnbc-homologous-repair","stem":"Which of the following best describes the genetic inheritance pattern of BRCA1 mutations?","options":[{"id":"a","text":"Autosomal recessive"},{"id":"b","text":"X-linked dominant"},{"id":"c","text":"Autosomal dominant"},{"id":"d","text":"Mitochondrial inheritance"}],"answerId":"c","explanation":"BRCA1 mutations are inherited in an autosomal dominant manner, meaning one altered allele can increase cancer risk.","kind":"recall","origin":"ai"},{"id":"brca1-tnbc-homologous-repair~ai-2","moduleId":"brca1-tnbc-homologous-repair","stem":"In a patient with triple-negative breast cancer, which finding is most indicative of BRCA1 deficiency?","options":[{"id":"a","text":"Positive HER2 status"},{"id":"b","text":"ER-positive status"},{"id":"c","text":"PR-positive status"},{"id":"d","text":"ER-negative / PR-negative / HER2-negative"}],"answerId":"d","explanation":"Triple-negative breast cancer is characterized by the absence of ER, PR, and HER2, often associated with BRCA1 deficiency.","kind":"recall","origin":"ai"},{"id":"brca1-tnbc-homologous-repair~ai-3","moduleId":"brca1-tnbc-homologous-repair","stem":"What is the mechanism by which loss of BRCA1 leads to genomic instability?","options":[{"id":"a","text":"Increased apoptosis"},{"id":"b","text":"Defective homologous recombination"},{"id":"c","text":"Enhanced DNA repair"},{"id":"d","text":"Inhibition of cell cycle checkpoints"}],"answerId":"b","explanation":"Loss of BRCA1 impairs homologous recombination repair of double-strand breaks, leading to genomic instability.","kind":"mechanism","origin":"ai"},{"id":"brca1-tnbc-homologous-repair~ai-4","moduleId":"brca1-tnbc-homologous-repair","stem":"A patient with a family history of breast and ovarian cancer is found to have a BRCA1 mutation. What is the most appropriate next step?","options":[{"id":"a","text":"Immediate surgical intervention"},{"id":"b","text":"Genetic counseling and testing for family members"},{"id":"c","text":"Start chemotherapy"},{"id":"d","text":"Regular mammograms only"}],"answerId":"b","explanation":"Genetic counseling and testing for family members is crucial for assessing hereditary cancer risk.","kind":"clinical","origin":"ai"},{"id":"brca1-tnbc-homologous-repair~ai-5","moduleId":"brca1-tnbc-homologous-repair","stem":"Which of the following statements about BRCA1-associated tumors is true?","options":[{"id":"a","text":"They are typically HER2-positive"},{"id":"b","text":"They are often hormone receptor-positive"},{"id":"c","text":"They are usually triple-negative"},{"id":"d","text":"They arise from a single-hit mutation"}],"answerId":"c","explanation":"BRCA1-associated tumors are often triple-negative, lacking ER, PR, and HER2 expression.","kind":"trap","origin":"ai"},{"id":"brca1-tnbc-homologous-repair~ai-6","moduleId":"brca1-tnbc-homologous-repair","stem":"How does BRCA1 deficiency relate to the concept of synthetic lethality in cancer treatment?","options":[{"id":"a","text":"It enhances the effectiveness of chemotherapy"},{"id":"b","text":"It increases reliance on PARP inhibitors"},{"id":"c","text":"It leads to increased tumor heterogeneity"},{"id":"d","text":"It promotes immune evasion"}],"answerId":"b","explanation":"BRCA1 deficiency makes tumors more susceptible to PARP inhibitors due to their reliance on alternative DNA repair pathways.","kind":"integration","linkedModuleIds":["parp-synthetic-lethality"],"origin":"ai"},{"id":"brca1-tnbc-homologous-repair~ai-7","moduleId":"brca1-tnbc-homologous-repair","stem":"What role does homologous recombination play in meiosis, and how is it related to BRCA1 function?","options":[{"id":"a","text":"It prevents chromosomal crossover"},{"id":"b","text":"It facilitates genetic diversity through crossover"},{"id":"c","text":"It is unrelated to BRCA1 function"},{"id":"d","text":"It occurs only in somatic cells"}],"answerId":"b","explanation":"Homologous recombination during meiosis facilitates genetic diversity, a process in which BRCA1 is also critically involved for DNA repair.","kind":"integration","linkedModuleIds":["meiosis-recombination"],"origin":"ai"}],"colon-cancer-epigenetic-silencing":[{"id":"colon-cancer-epigenetic-silencing~ai-0","moduleId":"colon-cancer-epigenetic-silencing","stem":"What is the primary mechanism by which DNA methyltransferases silence tumor-suppressor genes?","options":[{"id":"a","text":"Increased transcription factor binding"},{"id":"b","text":"Promoter methylation closes chromatin"},{"id":"c","text":"Histone acetylation"},{"id":"d","text":"DNA replication inhibition"}],"answerId":"b","explanation":"DNA methyltransferases add methyl groups to CpG sites, leading to chromatin condensation and gene silencing.","kind":"mechanism","origin":"ai"},{"id":"colon-cancer-epigenetic-silencing~ai-1","moduleId":"colon-cancer-epigenetic-silencing","stem":"Which of the following findings is most indicative of a colon adenocarcinoma?","options":[{"id":"a","text":"Weight loss and fatigue"},{"id":"b","text":"Altered bowel habits and blood in stool"},{"id":"c","text":"Abdominal pain and bloating"},{"id":"d","text":"Nausea and vomiting"}],"answerId":"b","explanation":"Altered bowel habits and blood in stool are classic signs of colon adenocarcinoma.","kind":"recall","origin":"ai"},{"id":"colon-cancer-epigenetic-silencing~ai-2","moduleId":"colon-cancer-epigenetic-silencing","stem":"What is the consequence of APC promoter methylation in colon cancer?","options":[{"id":"a","text":"Increased apoptosis"},{"id":"b","text":"β-catenin accumulation"},{"id":"c","text":"Enhanced DNA repair"},{"id":"d","text":"Decreased cell proliferation"}],"answerId":"b","explanation":"APC promoter methylation leads to loss of APC function, allowing β-catenin accumulation and increased cell proliferation.","kind":"mechanism","origin":"ai"},{"id":"colon-cancer-epigenetic-silencing~ai-3","moduleId":"colon-cancer-epigenetic-silencing","stem":"Which statement is true regarding MLH1 promoter methylation and its implications for MMR status?","options":[{"id":"a","text":"It guarantees MSI-high status"},{"id":"b","text":"It indicates functional loss must be confirmed"},{"id":"c","text":"It is always associated with a coding mutation"},{"id":"d","text":"It is reversible with treatment"}],"answerId":"b","explanation":"MLH1 promoter methylation does not automatically prove MSI-high disease; functional loss must be confirmed with MMR IHC/MSI testing.","kind":"trap","origin":"ai"},{"id":"colon-cancer-epigenetic-silencing~ai-4","moduleId":"colon-cancer-epigenetic-silencing","stem":"How does epigenetic silencing differ from DNA mutations in colon cancer?","options":[{"id":"a","text":"Epigenetic changes are irreversible"},{"id":"b","text":"DNA mutations are reversible"},{"id":"c","text":"Epigenetic changes can be reversible"},{"id":"d","text":"DNA mutations affect transcription directly"}],"answerId":"c","explanation":"Epigenetic lesions are clonally heritable but potentially reversible, unlike fixed DNA-sequence mutations.","kind":"mechanism","origin":"ai"},{"id":"colon-cancer-epigenetic-silencing~ai-5","moduleId":"colon-cancer-epigenetic-silencing","stem":"How does the mechanism of DNA methylation relate to transcriptional control?","options":[{"id":"a","text":"It enhances transcription factor binding"},{"id":"b","text":"It promotes chromatin accessibility"},{"id":"c","text":"It represses transcription by closing chromatin"},{"id":"d","text":"It directly alters DNA sequence"}],"answerId":"c","explanation":"DNA methylation represses transcription by closing chromatin, making it less accessible for transcription factors.","kind":"integration","linkedModuleIds":["epigenetics-transcriptional-control"],"origin":"ai"},{"id":"colon-cancer-epigenetic-silencing~ai-6","moduleId":"colon-cancer-epigenetic-silencing","stem":"What is the role of mismatch repair (MMR) in the context of colon cancer and epigenetic changes?","options":[{"id":"a","text":"It is unaffected by methylation"},{"id":"b","text":"It is enhanced by promoter methylation"},{"id":"c","text":"It is impaired by functional MLH1 silencing"},{"id":"d","text":"It prevents chromatin condensation"}],"answerId":"c","explanation":"Functional MLH1 silencing impairs mismatch repair, leading to microsatellite instability, a hallmark of certain colon cancers.","kind":"integration","origin":"ai"}],"obesity-insulin-resistance":[{"id":"obesity-insulin-resistance~ai-0","moduleId":"obesity-insulin-resistance","stem":"What is the primary mechanism by which visceral fat contributes to insulin resistance?","options":[{"id":"a","text":"Increased insulin secretion from pancreatic β cells"},{"id":"b","text":"Conversion of excess nutrients into impaired insulin signaling"},{"id":"c","text":"Enhanced glucose uptake in peripheral tissues"},{"id":"d","text":"Decreased free fatty acid release into circulation"}],"answerId":"b","explanation":"Visceral fat converts nutrient excess into impaired insulin signaling, leading to insulin resistance.","kind":"mechanism","origin":"ai"},{"id":"obesity-insulin-resistance~ai-1","moduleId":"obesity-insulin-resistance","stem":"Which of the following findings is most characteristic of insulin resistance?","options":[{"id":"a","text":"Acanthosis nigricans"},{"id":"b","text":"Hypoglycemia"},{"id":"c","text":"Increased HDL levels"},{"id":"d","text":"Decreased triglycerides"}],"answerId":"a","explanation":"Acanthosis nigricans is associated with high insulin levels and is a common clinical finding in insulin resistance.","kind":"recall","origin":"ai"},{"id":"obesity-insulin-resistance~ai-2","moduleId":"obesity-insulin-resistance","stem":"What effect does exercise have on GLUT4 translocation in muscle cells?","options":[{"id":"a","text":"It requires insulin to function effectively."},{"id":"b","text":"It is mediated through contraction and AMPK pathways."},{"id":"c","text":"It decreases mitochondrial capacity."},{"id":"d","text":"It has no effect on glucose uptake."}],"answerId":"b","explanation":"Exercise recruits GLUT4 through contraction and AMPK pathways independent of insulin, enhancing glucose uptake.","kind":"mechanism","origin":"ai"},{"id":"obesity-insulin-resistance~ai-3","moduleId":"obesity-insulin-resistance","stem":"Which statement about HOMA-IR is true?","options":[{"id":"a","text":"It is a universal standalone diagnosis for insulin resistance."},{"id":"b","text":"One cutoff value applies to all patients regardless of population."},{"id":"c","text":"HOMA-IR is population- and assay-dependent."},{"id":"d","text":"It does not correlate with clinical risk."}],"answerId":"c","explanation":"HOMA-IR is population- and assay-dependent and should not be used as a universal standalone diagnosis.","kind":"trap","origin":"ai"},{"id":"obesity-insulin-resistance~ai-4","moduleId":"obesity-insulin-resistance","stem":"How does ectopic lipid accumulation affect insulin signaling?","options":[{"id":"a","text":"It enhances PI3K–Akt signaling."},{"id":"b","text":"It promotes serine phosphorylation of IRS proteins."},{"id":"c","text":"It increases GLUT4 translocation."},{"id":"d","text":"It decreases free fatty acid flux."}],"answerId":"b","explanation":"Ectopic lipid intermediates such as DAG activate stress/PKC pathways that promote inhibitory serine phosphorylation of IRS proteins, reducing insulin signaling.","kind":"mechanism","origin":"ai"},{"id":"obesity-insulin-resistance~ai-5","moduleId":"obesity-insulin-resistance","stem":"Which of the following is a potential consequence of sustained weight loss in insulin-resistant individuals?","options":[{"id":"a","text":"Increased ectopic fat accumulation"},{"id":"b","text":"Decreased inflammatory signaling"},{"id":"c","text":"Higher insulin secretion from β cells"},{"id":"d","text":"Worsening of glucose tolerance"}],"answerId":"b","explanation":"Sustained weight loss lowers ectopic fat and inflammatory signaling, improving insulin sensitivity.","kind":"clinical","origin":"ai"},{"id":"obesity-insulin-resistance~ai-6","moduleId":"obesity-insulin-resistance","stem":"How does the understanding of insulin resistance relate to the management of prediabetes?","options":[{"id":"a","text":"Insulin resistance does not affect prediabetes management."},{"id":"b","text":"Weight loss and exercise can improve insulin sensitivity in prediabetes."},{"id":"c","text":"Prediabetes is solely determined by genetic factors."},{"id":"d","text":"Insulin therapy is the first-line treatment for all prediabetes cases."}],"answerId":"b","explanation":"Weight loss and exercise improve insulin sensitivity, which is crucial in managing prediabetes.","kind":"integration","linkedModuleIds":["prediabetes-ogtt-hba1c"],"origin":"ai"},{"id":"obesity-insulin-resistance~ai-7","moduleId":"obesity-insulin-resistance","stem":"What role do adipokines play in the context of obesity and insulin resistance?","options":[{"id":"a","text":"They exclusively promote insulin sensitivity."},{"id":"b","text":"They have no impact on metabolic processes."},{"id":"c","text":"They can contribute to inflammation and insulin resistance."},{"id":"d","text":"They only affect lipid metabolism."}],"answerId":"c","explanation":"Adipokines can contribute to inflammation and insulin resistance, linking obesity to metabolic dysfunction.","kind":"integration","linkedModuleIds":["hen1-adipokines-obesity-insulin-resistance"],"origin":"ai"}],"parp-synthetic-lethality":[{"id":"parp-synthetic-lethality~ai-0","moduleId":"parp-synthetic-lethality","stem":"What is the primary mechanism by which PARP inhibitors exert their therapeutic effect in BRCA1-deficient tumors?","options":[{"id":"a","text":"They inhibit all DNA repair mechanisms indiscriminately."},{"id":"b","text":"They trap PARP on DNA, preventing repair of single-strand breaks."},{"id":"c","text":"They enhance homologous recombination repair."},{"id":"d","text":"They directly induce double-strand DNA breaks."}],"answerId":"b","explanation":"PARP inhibitors trap PARP on DNA, preventing the repair of single-strand breaks, which is particularly lethal in BRCA1-deficient cells.","kind":"mechanism","origin":"ai"},{"id":"parp-synthetic-lethality~ai-1","moduleId":"parp-synthetic-lethality","stem":"Which of the following best describes synthetic lethality in the context of PARP inhibition?","options":[{"id":"a","text":"It occurs when two independent genetic defects lead to cell death."},{"id":"b","text":"It is the result of PARP inhibitors being toxic to all cells."},{"id":"c","text":"It requires both BRCA1 mutation and PARP inhibition to be lethal."},{"id":"d","text":"It is a phenomenon where normal cells are also killed by PARP inhibitors."}],"answerId":"c","explanation":"Synthetic lethality occurs when two independent defects, such as BRCA1 mutation and PARP inhibition, lead to cell death, while either defect alone is survivable.","kind":"trap","origin":"ai"},{"id":"parp-synthetic-lethality~ai-2","moduleId":"parp-synthetic-lethality","stem":"In a patient with BRCA1-mutant breast cancer treated with a PARP inhibitor, what is a likely mechanism of acquired resistance?","options":[{"id":"a","text":"Increased PARP expression."},{"id":"b","text":"Restoration of homologous recombination."},{"id":"c","text":"Enhanced drug absorption."},{"id":"d","text":"Decreased DNA damage."}],"answerId":"b","explanation":"Acquired resistance can occur through restoration of homologous recombination, allowing the cancer cells to repair DNA damage effectively.","kind":"clinical","origin":"ai"},{"id":"parp-synthetic-lethality~ai-3","moduleId":"parp-synthetic-lethality","stem":"Which clinical finding would suggest a vulnerability to PARP inhibition in a breast cancer patient?","options":[{"id":"a","text":"HER2-positive status."},{"id":"b","text":"Presence of BRCA1 mutation."},{"id":"c","text":"High levels of PARP expression."},{"id":"d","text":"Lack of lymphatic spread."}],"answerId":"b","explanation":"A BRCA1 mutation indicates a homologous-recombination vulnerability, making the tumor susceptible to PARP inhibition.","kind":"recall","origin":"ai"},{"id":"parp-synthetic-lethality~ai-4","moduleId":"parp-synthetic-lethality","stem":"How does the presence of BRCA1 mutation affect the response to PARP inhibitors?","options":[{"id":"a","text":"It makes the tumor resistant to PARP inhibitors."},{"id":"b","text":"It enhances the effectiveness of PARP inhibitors."},{"id":"c","text":"It has no effect on the response to PARP inhibitors."},{"id":"d","text":"It leads to increased side effects from PARP inhibitors."}],"answerId":"b","explanation":"BRCA1 mutation enhances the effectiveness of PARP inhibitors due to the reliance on PARP for repair of single-strand breaks in these cells.","kind":"integration","linkedModuleIds":["brca1-tnbc-homologous-repair"],"origin":"ai"},{"id":"parp-synthetic-lethality~ai-5","moduleId":"parp-synthetic-lethality","stem":"What is the role of homologous recombination in the context of PARP inhibition and BRCA1 mutations?","options":[{"id":"a","text":"It is enhanced by PARP inhibitors."},{"id":"b","text":"It is the primary pathway for repairing double-strand breaks."},{"id":"c","text":"It is inhibited by BRCA1 mutations."},{"id":"d","text":"It is irrelevant to the effects of PARP inhibitors."}],"answerId":"b","explanation":"Homologous recombination is the primary pathway for repairing double-strand breaks, and BRCA1 mutations impair this repair, making cells more susceptible to PARP inhibitors.","kind":"integration","linkedModuleIds":["brca1-tnbc-homologous-repair"],"origin":"ai"}],"osimertinib-resistance":[{"id":"osimertinib-resistance~ai-0","moduleId":"osimertinib-resistance","stem":"What is the primary mechanism of action of osimertinib?","options":[{"id":"a","text":"It inhibits EGFR phosphorylation by occupying the ATP-binding site."},{"id":"b","text":"It induces apoptosis in cancer cells directly."},{"id":"c","text":"It enhances immune response against tumor cells."},{"id":"d","text":"It prevents angiogenesis in tumors."}],"answerId":"a","explanation":"Osimertinib is an irreversible EGFR inhibitor that occupies the ATP-binding region, suppressing phosphorylation-dependent signaling.","kind":"mechanism","origin":"ai"},{"id":"osimertinib-resistance~ai-1","moduleId":"osimertinib-resistance","stem":"Which mutation is commonly associated with resistance to osimertinib?","options":[{"id":"a","text":"EGFR L858R"},{"id":"b","text":"EGFR T790M"},{"id":"c","text":"EGFR C797S"},{"id":"d","text":"KRAS G12C"}],"answerId":"c","explanation":"The EGFR C797S mutation is a known mechanism of resistance to osimertinib.","kind":"recall","origin":"ai"},{"id":"osimertinib-resistance~ai-2","moduleId":"osimertinib-resistance","stem":"What does the emergence of resistant clones after initial response to EGFR TKI indicate?","options":[{"id":"a","text":"The original EGFR mutation was not present."},{"id":"b","text":"The treatment has failed completely."},{"id":"c","text":"Cancer evolves under targeted-therapy pressure."},{"id":"d","text":"The tumor is now sensitive to other therapies."}],"answerId":"c","explanation":"The emergence of resistant clones indicates that cancer evolves under the selective pressure of targeted therapy.","kind":"trap","origin":"ai"},{"id":"osimertinib-resistance~ai-3","moduleId":"osimertinib-resistance","stem":"What is a common clinical finding in patients who develop resistance to osimertinib?","options":[{"id":"a","text":"Complete remission of the tumor"},{"id":"b","text":"New progression after initial major response"},{"id":"c","text":"Increased tumor size without any treatment"},{"id":"d","text":"Improved quality of life without further treatment"}],"answerId":"b","explanation":"New progression after an initial major response indicates acquired resistance through target alteration or bypass signaling.","kind":"clinical","origin":"ai"},{"id":"osimertinib-resistance~ai-4","moduleId":"osimertinib-resistance","stem":"In the context of EGFR-mutant lung adenocarcinoma, what should be done upon disease progression after osimertinib treatment?","options":[{"id":"a","text":"Continue the same treatment indefinitely"},{"id":"b","text":"Recharacterize the tumor for new mutations"},{"id":"c","text":"Switch to a chemotherapy regimen immediately"},{"id":"d","text":"Increase the dose of osimertinib"}],"answerId":"b","explanation":"Upon progression, the tumor should be recharacterized to identify new mutations or resistance mechanisms.","kind":"integration","linkedModuleIds":["egfr-mutant-lung-adenocarcinoma"],"origin":"ai"},{"id":"osimertinib-resistance~ai-5","moduleId":"osimertinib-resistance","stem":"How does the insulin receptor signaling pathway relate to the treatment of EGFR-mutant lung adenocarcinoma?","options":[{"id":"a","text":"It directly enhances the efficacy of osimertinib."},{"id":"b","text":"It is unrelated to cancer treatment."},{"id":"c","text":"It may influence metabolic adaptations in resistant tumors."},{"id":"d","text":"It provides a mechanism for tumor growth independent of EGFR."}],"answerId":"c","explanation":"Insulin signaling may influence metabolic adaptations that allow resistant tumors to survive despite EGFR inhibition.","kind":"integration","linkedModuleIds":["hen1-insulin-signaling-fed-metabolism"],"origin":"ai"},{"id":"osimertinib-resistance~ai-6","moduleId":"osimertinib-resistance","stem":"Which of the following is NOT a mechanism of resistance to osimertinib?","options":[{"id":"a","text":"EGFR C797S mutation"},{"id":"b","text":"MET amplification"},{"id":"c","text":"Histologic transformation"},{"id":"d","text":"Increased apoptosis sensitivity"}],"answerId":"d","explanation":"Increased apoptosis sensitivity is not a mechanism of resistance; it would rather indicate a potential response to treatment.","kind":"trap","origin":"ai"}],"egfr-mutant-lung-adenocarcinoma":[{"id":"egfr-mutant-lung-adenocarcinoma~ai-0","moduleId":"egfr-mutant-lung-adenocarcinoma","stem":"What is the primary mechanism of action for EGFR in lung adenocarcinoma?","options":[{"id":"a","text":"Inhibition of apoptosis"},{"id":"b","text":"Receptor dimerization and autophosphorylation"},{"id":"c","text":"Activation of immune response"},{"id":"d","text":"Inhibition of angiogenesis"}],"answerId":"b","explanation":"EGFR functions as a receptor tyrosine kinase, where ligand-induced dimerization and autophosphorylation activate downstream signaling pathways.","kind":"mechanism","origin":"ai"},{"id":"egfr-mutant-lung-adenocarcinoma~ai-1","moduleId":"egfr-mutant-lung-adenocarcinoma","stem":"Which histological finding is characteristic of EGFR-mutant lung adenocarcinoma?","options":[{"id":"a","text":"Squamous cell carcinoma"},{"id":"b","text":"Small cell carcinoma"},{"id":"c","text":"Adenocarcinoma"},{"id":"d","text":"Large cell carcinoma"}],"answerId":"c","explanation":"EGFR mutations are primarily associated with adenocarcinoma histology in non-small-cell lung cancer.","kind":"recall","origin":"ai"},{"id":"egfr-mutant-lung-adenocarcinoma~ai-2","moduleId":"egfr-mutant-lung-adenocarcinoma","stem":"A patient presents with a persistent cough, weight loss, and a focal upper-lobe lesion. What is the most likely diagnosis?","options":[{"id":"a","text":"Pulmonary fibrosis"},{"id":"b","text":"Lung adenocarcinoma"},{"id":"c","text":"Tuberculosis"},{"id":"d","text":"Pneumonia"}],"answerId":"b","explanation":"The combination of symptoms and the focal lesion is suggestive of lung adenocarcinoma, particularly in the context of EGFR mutations.","kind":"clinical","origin":"ai"},{"id":"egfr-mutant-lung-adenocarcinoma~ai-3","moduleId":"egfr-mutant-lung-adenocarcinoma","stem":"What is the significance of an EGFR exon 19 deletion in lung adenocarcinoma?","options":[{"id":"a","text":"It indicates a poor prognosis"},{"id":"b","text":"It is a driver mutation that promotes oncogene addiction"},{"id":"c","text":"It suggests a squamous cell carcinoma subtype"},{"id":"d","text":"It is a marker for immunotherapy response"}],"answerId":"b","explanation":"An EGFR exon 19 deletion is an activating driver mutation that stabilizes kinase signaling, leading to oncogene addiction.","kind":"recall","origin":"ai"},{"id":"egfr-mutant-lung-adenocarcinoma~ai-4","moduleId":"egfr-mutant-lung-adenocarcinoma","stem":"In the context of lung adenocarcinoma treatment, why is PD-L1 testing not a substitute for EGFR mutation testing?","options":[{"id":"a","text":"PD-L1 testing is more sensitive"},{"id":"b","text":"Driver mutation testing and PD-L1 answer different treatment questions"},{"id":"c","text":"EGFR mutations are irrelevant in treatment decisions"},{"id":"d","text":"PD-L1 is only useful in squamous cell carcinoma"}],"answerId":"b","explanation":"Driver mutation testing identifies actionable oncogenic kinases that can dominate therapy selection, regardless of PD-L1 status.","kind":"trap","origin":"ai"},{"id":"egfr-mutant-lung-adenocarcinoma~ai-5","moduleId":"egfr-mutant-lung-adenocarcinoma","stem":"How does osimertinib resistance relate to EGFR-mutant lung adenocarcinoma?","options":[{"id":"a","text":"It is caused by immune evasion"},{"id":"b","text":"It involves secondary mutations in EGFR"},{"id":"c","text":"It leads to increased PD-L1 expression"},{"id":"d","text":"It is unrelated to initial treatment response"}],"answerId":"b","explanation":"Resistance to osimertinib often occurs due to secondary mutations in the EGFR gene, which alter the drug's binding affinity.","kind":"integration","linkedModuleIds":["osimertinib-resistance"],"origin":"ai"},{"id":"egfr-mutant-lung-adenocarcinoma~ai-6","moduleId":"egfr-mutant-lung-adenocarcinoma","stem":"Which of the following best describes the relationship between EGFR mutations and the prognosis of lung adenocarcinoma?","options":[{"id":"a","text":"EGFR mutations are always associated with poor prognosis"},{"id":"b","text":"EGFR mutations indicate a favorable response to targeted therapy"},{"id":"c","text":"EGFR mutations have no impact on prognosis"},{"id":"d","text":"EGFR mutations are only relevant in early-stage disease"}],"answerId":"b","explanation":"EGFR mutations are associated with a favorable response to targeted therapies, improving prognosis in patients with lung adenocarcinoma.","kind":"integration","linkedModuleIds":["non-small-cell-lung-carcinoma"],"origin":"ai"}],"prediabetes-ogtt-hba1c":[{"id":"prediabetes-ogtt-hba1c~ai-0","moduleId":"prediabetes-ogtt-hba1c","stem":"What is the HbA1c range that indicates prediabetes?","options":[{"id":"a","text":"4.5% - 5.6%"},{"id":"b","text":"5.7% - 6.4%"},{"id":"c","text":"6.5% - 7.0%"},{"id":"d","text":"≥7.0%"}],"answerId":"b","explanation":"An HbA1c of 5.7% to 6.4% is classified as prediabetes, indicating increased risk for developing type 2 diabetes.","kind":"recall","origin":"ai"},{"id":"prediabetes-ogtt-hba1c~ai-1","moduleId":"prediabetes-ogtt-hba1c","stem":"Which of the following findings is indicative of insulin resistance?","options":[{"id":"a","text":"Normal waist circumference with hypertension"},{"id":"b","text":"Large waist with hypertension"},{"id":"c","text":"Low fasting glucose levels"},{"id":"d","text":"Normal lipid profile"}],"answerId":"b","explanation":"A large waist circumference along with hypertension is a classic sign of insulin resistance and metabolic syndrome.","kind":"recall","origin":"ai"},{"id":"prediabetes-ogtt-hba1c~ai-2","moduleId":"prediabetes-ogtt-hba1c","stem":"What is the mechanism by which HbA1c levels can be misleading?","options":[{"id":"a","text":"Increased dietary glucose intake"},{"id":"b","text":"Variability in RBC lifespan"},{"id":"c","text":"Decreased insulin sensitivity"},{"id":"d","text":"Increased physical activity"}],"answerId":"b","explanation":"HbA1c levels can be misleading if the lifespan of red blood cells is altered, affecting the glycation process.","kind":"mechanism","origin":"ai"},{"id":"prediabetes-ogtt-hba1c~ai-3","moduleId":"prediabetes-ogtt-hba1c","stem":"A patient has normal fasting glucose but an abnormal 2-hour OGTT. What does this indicate?","options":[{"id":"a","text":"Diabetes mellitus"},{"id":"b","text":"Impaired fasting glucose"},{"id":"c","text":"Postprandial dysglycemia"},{"id":"d","text":"Normal glucose metabolism"}],"answerId":"c","explanation":"Abnormal 2-hour OGTT results indicate postprandial dysglycemia, which can precede fasting hyperglycemia.","kind":"clinical","origin":"ai"},{"id":"prediabetes-ogtt-hba1c~ai-4","moduleId":"prediabetes-ogtt-hba1c","stem":"Which of the following is a trap regarding HbA1c interpretation?","options":[{"id":"a","text":"HbA1c is always accurate regardless of RBC lifespan"},{"id":"b","text":"Fasting is necessary for HbA1c testing"},{"id":"c","text":"HbA1c is less reliable in patients with anemia"},{"id":"d","text":"HbA1c reflects glucose levels over 1 month"}],"answerId":"a","explanation":"HbA1c accuracy can be compromised by variations in RBC lifespan, making it unreliable in certain conditions.","kind":"trap","origin":"ai"},{"id":"prediabetes-ogtt-hba1c~ai-5","moduleId":"prediabetes-ogtt-hba1c","stem":"How does obesity contribute to insulin resistance?","options":[{"id":"a","text":"By decreasing physical activity"},{"id":"b","text":"By increasing visceral fat and inflammation"},{"id":"c","text":"By enhancing insulin receptor sensitivity"},{"id":"d","text":"By lowering blood glucose levels"}],"answerId":"b","explanation":"Obesity, particularly visceral fat accumulation, leads to increased inflammation and insulin resistance.","kind":"mechanism","origin":"ai"},{"id":"prediabetes-ogtt-hba1c~ai-6","moduleId":"prediabetes-ogtt-hba1c","stem":"What is the relationship between obesity and prediabetes in terms of insulin resistance?","options":[{"id":"a","text":"Obesity does not affect insulin sensitivity"},{"id":"b","text":"Obesity leads to decreased insulin secretion"},{"id":"c","text":"Obesity increases the risk of developing insulin resistance"},{"id":"d","text":"Obesity only affects lipid metabolism"}],"answerId":"c","explanation":"Obesity is a significant risk factor for developing insulin resistance, which can lead to prediabetes and type 2 diabetes.","kind":"integration","linkedModuleIds":["obesity-insulin-resistance"],"origin":"ai"},{"id":"prediabetes-ogtt-hba1c~ai-7","moduleId":"prediabetes-ogtt-hba1c","stem":"In assessing a patient for diabetes, which test would be most direct for evaluating post-load glucose disposal?","options":[{"id":"a","text":"Fasting plasma glucose"},{"id":"b","text":"HbA1c"},{"id":"c","text":"2-hour OGTT"},{"id":"d","text":"Random plasma glucose"}],"answerId":"c","explanation":"The 2-hour OGTT directly measures glucose disposal after a glucose load, making it the most informative for postprandial assessment.","kind":"integration","linkedModuleIds":["diabetes-diagnostic-criteria-gdm"],"origin":"ai"}],"colon-molecular-workup-therapy":[{"id":"colon-molecular-workup-therapy~ai-0","moduleId":"colon-molecular-workup-therapy","stem":"What is the first step in the workup of suspected colon cancer?","options":[{"id":"a","text":"CT scan of the abdomen"},{"id":"b","text":"Colonoscopy with biopsy"},{"id":"c","text":"Tumor marker testing"},{"id":"d","text":"Genetic testing for Lynch syndrome"}],"answerId":"b","explanation":"Colonoscopy with biopsy is essential for histological confirmation of colon cancer.","kind":"recall","origin":"ai"},{"id":"colon-molecular-workup-therapy~ai-1","moduleId":"colon-molecular-workup-therapy","stem":"Which molecular test is crucial for assessing hereditary risk in colorectal cancer?","options":[{"id":"a","text":"KRAS mutation analysis"},{"id":"b","text":"BRAF mutation analysis"},{"id":"c","text":"MMR deficiency testing"},{"id":"d","text":"MLH1 methylation testing"}],"answerId":"c","explanation":"MMR deficiency testing is critical for identifying Lynch syndrome and assessing hereditary risk.","kind":"recall","origin":"ai"},{"id":"colon-molecular-workup-therapy~ai-2","moduleId":"colon-molecular-workup-therapy","stem":"A patient with colon cancer shows loss of MLH1 and PMS2 expression. What is the next best step?","options":[{"id":"a","text":"Start chemotherapy immediately"},{"id":"b","text":"Perform BRAF V600E testing"},{"id":"c","text":"Refer for genetic counseling"},{"id":"d","text":"Order a CT scan"}],"answerId":"b","explanation":"BRAF V600E testing helps distinguish between sporadic cases and Lynch syndrome.","kind":"mechanism","origin":"ai"},{"id":"colon-molecular-workup-therapy~ai-3","moduleId":"colon-molecular-workup-therapy","stem":"Which treatment regimen is commonly used for Stage III colon cancer?","options":[{"id":"a","text":"FOLFOX"},{"id":"b","text":"Bevacizumab alone"},{"id":"c","text":"Radiation therapy"},{"id":"d","text":"Surgical resection only"}],"answerId":"a","explanation":"FOLFOX is a standard chemotherapy regimen used in conjunction with surgical resection for Stage III colon cancer.","kind":"recall","origin":"ai"},{"id":"colon-molecular-workup-therapy~ai-4","moduleId":"colon-molecular-workup-therapy","stem":"A patient presents with blood in stool and a change in bowel habits. What does this suggest?","options":[{"id":"a","text":"Hemorrhoids"},{"id":"b","text":"Colorectal cancer"},{"id":"c","text":"Irritable bowel syndrome"},{"id":"d","text":"Diverticulitis"}],"answerId":"b","explanation":"Blood in stool with persistent bowel habit change is a classic sign of colorectal cancer.","kind":"recall","origin":"ai"},{"id":"colon-molecular-workup-therapy~ai-5","moduleId":"colon-molecular-workup-therapy","stem":"Which of the following statements about epigenetic therapy in colon cancer is true?","options":[{"id":"a","text":"All hypermethylated tumors should receive DNMT inhibitors"},{"id":"b","text":"Promoter methylation can guide treatment decisions"},{"id":"c","text":"Epigenetic changes are reversible without clinical evidence"},{"id":"d","text":"Methylation status is irrelevant for treatment planning"}],"answerId":"b","explanation":"While promoter methylation explains the mechanism, treatment requires evidence for that drug in that cancer and disease setting.","kind":"trap","origin":"ai"},{"id":"colon-molecular-workup-therapy~ai-6","moduleId":"colon-molecular-workup-therapy","stem":"How does the TNM staging system relate to molecular workup in colon cancer?","options":[{"id":"a","text":"TNM stage determines the need for molecular testing"},{"id":"b","text":"Molecular tests replace TNM staging"},{"id":"c","text":"TNM stage is irrelevant for treatment decisions"},{"id":"d","text":"Molecular tests refine treatment based on TNM stage"}],"answerId":"d","explanation":"Molecular tests refine treatment options based on the TNM stage but do not replace it.","kind":"integration","linkedModuleIds":["cancer-spread-staging-clinical"],"origin":"ai"},{"id":"colon-molecular-workup-therapy~ai-7","moduleId":"colon-molecular-workup-therapy","stem":"What is the significance of KRAS and BRAF status in metastatic colon cancer?","options":[{"id":"a","text":"They are used to determine the TNM stage"},{"id":"b","text":"They guide targeted therapy choices"},{"id":"c","text":"They indicate the need for surgery"},{"id":"d","text":"They predict overall survival regardless of treatment"}],"answerId":"b","explanation":"KRAS and BRAF status are critical in guiding targeted therapy choices for metastatic colon cancer.","kind":"integration","linkedModuleIds":["pharmacodynamics-receptors-dose-response"],"origin":"ai"}],"ketogenic-fasting-exercise-adaptation":[{"id":"ketogenic-fasting-exercise-adaptation~ai-0","moduleId":"ketogenic-fasting-exercise-adaptation","stem":"What is the primary source of energy during prolonged fasting?","options":[{"id":"a","text":"Glucose from glycogen"},{"id":"b","text":"Fatty acids and ketones"},{"id":"c","text":"Amino acids from muscle"},{"id":"d","text":"Lactate from anaerobic metabolism"}],"answerId":"b","explanation":"During prolonged fasting, the body primarily utilizes fatty acids and ketones for energy as glycogen stores are depleted.","kind":"recall","origin":"ai"},{"id":"ketogenic-fasting-exercise-adaptation~ai-1","moduleId":"ketogenic-fasting-exercise-adaptation","stem":"Which of the following best explains the rapid weight loss in the first week of a ketogenic diet?","options":[{"id":"a","text":"Increased fat oxidation"},{"id":"b","text":"Glycogen depletion and water loss"},{"id":"c","text":"Enhanced muscle protein synthesis"},{"id":"d","text":"Decreased appetite and caloric intake"}],"answerId":"b","explanation":"The initial weight loss is largely due to glycogen depletion, which releases water associated with glycogen stores.","kind":"mechanism","origin":"ai"},{"id":"ketogenic-fasting-exercise-adaptation~ai-2","moduleId":"ketogenic-fasting-exercise-adaptation","stem":"A patient on a ketogenic diet shows an increase in muscle percentage but a decrease in absolute muscle mass. What is the most likely reason for this observation?","options":[{"id":"a","text":"Increased muscle hypertrophy"},{"id":"b","text":"Decreased fat mass"},{"id":"c","text":"Inadequate protein intake"},{"id":"d","text":"Fluid retention in muscles"}],"answerId":"b","explanation":"The percentage of muscle can increase when fat mass decreases faster than muscle mass, even if absolute muscle mass is lost.","kind":"trap","origin":"ai"},{"id":"ketogenic-fasting-exercise-adaptation~ai-3","moduleId":"ketogenic-fasting-exercise-adaptation","stem":"What is the effect of resistance exercise on muscle mass during a ketogenic diet?","options":[{"id":"a","text":"Always increases absolute muscle mass"},{"id":"b","text":"May decrease absolute muscle mass with inadequate protein"},{"id":"c","text":"Has no effect on muscle mass"},{"id":"d","text":"Increases fat mass instead of muscle mass"}],"answerId":"b","explanation":"Resistance exercise can stimulate muscle-protein synthesis, but without adequate protein intake, absolute muscle mass may decrease.","kind":"clinical","origin":"ai"},{"id":"ketogenic-fasting-exercise-adaptation~ai-4","moduleId":"ketogenic-fasting-exercise-adaptation","stem":"How does a ketogenic diet affect fuel partitioning in the body?","options":[{"id":"a","text":"Increases reliance on carbohydrates"},{"id":"b","text":"Promotes fat oxidation and ketone production"},{"id":"c","text":"Reduces protein synthesis"},{"id":"d","text":"Increases glycogen storage"}],"answerId":"b","explanation":"A ketogenic diet promotes the use of fat and ketones as primary energy sources, altering fuel partitioning.","kind":"mechanism","origin":"ai"},{"id":"ketogenic-fasting-exercise-adaptation~ai-5","moduleId":"ketogenic-fasting-exercise-adaptation","stem":"During fasting, what physiological change helps maintain blood glucose levels?","options":[{"id":"a","text":"Increased insulin secretion"},{"id":"b","text":"Glycogenolysis"},{"id":"c","text":"Gluconeogenesis"},{"id":"d","text":"Decreased metabolic rate"}],"answerId":"c","explanation":"Gluconeogenesis is the process that helps maintain blood glucose levels during fasting by synthesizing glucose from non-carbohydrate sources.","kind":"recall","origin":"ai"},{"id":"ketogenic-fasting-exercise-adaptation~ai-6","moduleId":"ketogenic-fasting-exercise-adaptation","stem":"How does the body adapt to exercise during a ketogenic diet, in relation to stress hormones?","options":[{"id":"a","text":"Increased insulin sensitivity"},{"id":"b","text":"Enhanced glucagon secretion"},{"id":"c","text":"Decreased cortisol levels"},{"id":"d","text":"Increased catecholamine release"}],"answerId":"d","explanation":"During exercise on a ketogenic diet, there is an increase in catecholamine release, which helps mobilize fatty acids for energy.","kind":"integration","linkedModuleIds":["exercise-stress-fuel-integration"],"origin":"ai"},{"id":"ketogenic-fasting-exercise-adaptation~ai-7","moduleId":"ketogenic-fasting-exercise-adaptation","stem":"What is a potential complication of prolonged nutritional ketosis compared to ketoacidosis?","options":[{"id":"a","text":"Severe hypoglycemia"},{"id":"b","text":"Metabolic acidosis"},{"id":"c","text":"Dehydration from diuresis"},{"id":"d","text":"Increased muscle mass"}],"answerId":"c","explanation":"Prolonged nutritional ketosis can lead to dehydration due to increased diuresis associated with ketone production.","kind":"integration","linkedModuleIds":["nutritional-ketosis-vs-ketoacidosis"],"origin":"ai"}],"thiamine-wernicke-recovery":[{"id":"thiamine-wernicke-recovery~ai-0","moduleId":"thiamine-wernicke-recovery","stem":"What is the primary biochemical role of thiamine pyrophosphate in cellular metabolism?","options":[{"id":"a","text":"It acts as a cofactor for ATP synthesis."},{"id":"b","text":"It is required for the decarboxylation of pyruvate."},{"id":"c","text":"It facilitates the conversion of glucose to lactate."},{"id":"d","text":"It is essential for the synthesis of fatty acids."}],"answerId":"b","explanation":"Thiamine pyrophosphate is a cofactor for several key enzymes, including pyruvate dehydrogenase, which decarboxylates pyruvate.","kind":"recall","origin":"ai"},{"id":"thiamine-wernicke-recovery~ai-1","moduleId":"thiamine-wernicke-recovery","stem":"Which symptom is NOT typically associated with Wernicke encephalopathy?","options":[{"id":"a","text":"Confusion"},{"id":"b","text":"Ophthalmoplegia"},{"id":"c","text":"Gait ataxia"},{"id":"d","text":"Severe headache"}],"answerId":"d","explanation":"Severe headache is not a classic symptom of Wernicke encephalopathy, which is characterized by confusion, ophthalmoplegia, and gait ataxia.","kind":"trap","origin":"ai"},{"id":"thiamine-wernicke-recovery~ai-2","moduleId":"thiamine-wernicke-recovery","stem":"What is the immediate treatment for a patient suspected of Wernicke encephalopathy who presents with hypoglycemia?","options":[{"id":"a","text":"Administer glucose only"},{"id":"b","text":"Give thiamine before glucose"},{"id":"c","text":"Treat hypoglycemia immediately with glucose"},{"id":"d","text":"Delay treatment until thiamine is available"}],"answerId":"c","explanation":"Hypoglycemia must be treated immediately to prevent further complications, and thiamine should be given as soon as possible thereafter.","kind":"trap","origin":"ai"},{"id":"thiamine-wernicke-recovery~ai-3","moduleId":"thiamine-wernicke-recovery","stem":"What is the mechanism by which thiamine deficiency leads to neuronal energy failure?","options":[{"id":"a","text":"Inhibition of glycolysis"},{"id":"b","text":"Increased oxidative stress"},{"id":"c","text":"Impaired citric acid cycle function"},{"id":"d","text":"Reduced ATP synthesis from fatty acids"}],"answerId":"c","explanation":"Thiamine deficiency impairs the function of key enzymes in the citric acid cycle, leading to decreased ATP production and neuronal energy failure.","kind":"mechanism","origin":"ai"},{"id":"thiamine-wernicke-recovery~ai-4","moduleId":"thiamine-wernicke-recovery","stem":"Which of the following findings is characteristic of Korsakoff syndrome?","options":[{"id":"a","text":"Gait ataxia"},{"id":"b","text":"Ophthalmoplegia"},{"id":"c","text":"Confabulation"},{"id":"d","text":"Nystagmus"}],"answerId":"c","explanation":"Confabulation is a hallmark of Korsakoff syndrome, which results from chronic thiamine deficiency and diencephalic injury.","kind":"recall","origin":"ai"},{"id":"thiamine-wernicke-recovery~ai-5","moduleId":"thiamine-wernicke-recovery","stem":"How does chronic alcohol consumption contribute to thiamine deficiency?","options":[{"id":"a","text":"Increased renal excretion of thiamine"},{"id":"b","text":"Decreased dietary intake and absorption"},{"id":"c","text":"Enhanced thiamine utilization"},{"id":"d","text":"Inhibition of thiamine synthesis"}],"answerId":"b","explanation":"Chronic alcohol use leads to decreased dietary intake and absorption of thiamine, contributing to deficiency.","kind":"mechanism","origin":"ai"},{"id":"thiamine-wernicke-recovery~ai-6","moduleId":"thiamine-wernicke-recovery","stem":"How does Wernicke encephalopathy relate to alcoholic ketoacidosis?","options":[{"id":"a","text":"Both are caused by thiamine deficiency."},{"id":"b","text":"Wernicke encephalopathy can occur after treating alcoholic ketoacidosis."},{"id":"c","text":"Alcoholic ketoacidosis prevents the development of Wernicke encephalopathy."},{"id":"d","text":"Both conditions involve impaired glucose metabolism."}],"answerId":"d","explanation":"Both Wernicke encephalopathy and alcoholic ketoacidosis involve impaired glucose metabolism due to the effects of alcohol on energy production.","kind":"integration","linkedModuleIds":["alcoholic-ketoacidosis-redox"],"origin":"ai"},{"id":"thiamine-wernicke-recovery~ai-7","moduleId":"thiamine-wernicke-recovery","stem":"What is the relationship between Wernicke encephalopathy and the hepatic redox shift in alcoholics?","options":[{"id":"a","text":"Wernicke encephalopathy exacerbates the hepatic redox shift."},{"id":"b","text":"The hepatic redox shift causes Wernicke encephalopathy."},{"id":"c","text":"Both conditions result from thiamine deficiency."},{"id":"d","text":"Wernicke encephalopathy is a complication of the hepatic redox shift."}],"answerId":"a","explanation":"Wernicke encephalopathy can exacerbate the hepatic redox shift by further impairing energy metabolism in the context of alcohol use.","kind":"integration","linkedModuleIds":["alcoholic-ketoacidosis-redox"],"origin":"ai"}],"hen1-endocrine-signaling-glands":[{"id":"hen1-endocrine-signaling-glands~ai-0","moduleId":"hen1-endocrine-signaling-glands","stem":"Which of the following glands is primarily responsible for regulating metabolism through hormone secretion?","options":[{"id":"a","text":"Adrenal gland"},{"id":"b","text":"Thyroid gland"},{"id":"c","text":"Pituitary gland"},{"id":"d","text":"Pancreas"}],"answerId":"b","explanation":"The thyroid gland secretes hormones like thyroxine that regulate metabolism.","kind":"recall","origin":"ai"},{"id":"hen1-endocrine-signaling-glands~ai-1","moduleId":"hen1-endocrine-signaling-glands","stem":"What is the primary mechanism by which hormones exert their effects on target cells?","options":[{"id":"a","text":"Direct cell division"},{"id":"b","text":"Receptor-mediated signal transduction"},{"id":"c","text":"Intracellular protein synthesis"},{"id":"d","text":"Cell membrane permeability alteration"}],"answerId":"b","explanation":"Hormones bind to specific receptors on target cells, initiating a signal transduction pathway.","kind":"mechanism","origin":"ai"},{"id":"hen1-endocrine-signaling-glands~ai-2","moduleId":"hen1-endocrine-signaling-glands","stem":"A patient presents with normal insulin levels but elevated blood glucose. What is the likely underlying issue?","options":[{"id":"a","text":"Insulin resistance"},{"id":"b","text":"Insulin deficiency"},{"id":"c","text":"Excess glucagon"},{"id":"d","text":"Increased cortisol"}],"answerId":"a","explanation":"Insulin resistance means that target cells do not respond effectively to normal insulin levels.","kind":"recall","origin":"ai"},{"id":"hen1-endocrine-signaling-glands~ai-3","moduleId":"hen1-endocrine-signaling-glands","stem":"Which of the following statements about endocrine signaling is FALSE?","options":[{"id":"a","text":"Hormones can act on distant target organs."},{"id":"b","text":"Only receptor-bearing cells respond to hormones."},{"id":"c","text":"All cells exposed to a hormone will respond."},{"id":"d","text":"Hormones can have multiple effects on different organs."}],"answerId":"c","explanation":"Only cells with functional receptors respond to hormones, not all exposed cells.","kind":"trap","origin":"ai"},{"id":"hen1-endocrine-signaling-glands~ai-4","moduleId":"hen1-endocrine-signaling-glands","stem":"How does negative feedback regulate hormone levels in the endocrine system?","options":[{"id":"a","text":"By increasing hormone production when levels are high"},{"id":"b","text":"By decreasing hormone production when levels are high"},{"id":"c","text":"By maintaining constant hormone levels"},{"id":"d","text":"By amplifying hormone effects on target organs"}],"answerId":"b","explanation":"Negative feedback decreases hormone production when levels are elevated to maintain homeostasis.","kind":"mechanism","linkedModuleIds":["hen1-endocrine-feedback-loops"],"origin":"ai"},{"id":"hen1-endocrine-signaling-glands~ai-5","moduleId":"hen1-endocrine-signaling-glands","stem":"Which hormone is primarily responsible for the 'fight or flight' response?","options":[{"id":"a","text":"Insulin"},{"id":"b","text":"Cortisol"},{"id":"c","text":"Epinephrine"},{"id":"d","text":"Thyroxine"}],"answerId":"c","explanation":"Epinephrine, released by the adrenal glands, is crucial for the 'fight or flight' response.","kind":"recall","origin":"ai"},{"id":"hen1-endocrine-signaling-glands~ai-6","moduleId":"hen1-endocrine-signaling-glands","stem":"In what way do peptide hormones differ from steroid hormones in their mechanism of action?","options":[{"id":"a","text":"Peptide hormones are lipid-soluble"},{"id":"b","text":"Peptide hormones act on intracellular receptors"},{"id":"c","text":"Peptide hormones bind to cell surface receptors"},{"id":"d","text":"Peptide hormones have longer half-lives"}],"answerId":"c","explanation":"Peptide hormones typically bind to cell surface receptors, while steroid hormones are lipid-soluble and pass through the cell membrane.","kind":"integration","linkedModuleIds":["hen1-peptide-catecholamine-hormones"],"origin":"ai"}],"hen1-oxytocin-reflexes":[{"id":"hen1-oxytocin-reflexes~ai-0","moduleId":"hen1-oxytocin-reflexes","stem":"Where is oxytocin synthesized in the body?","options":[{"id":"a","text":"Posterior pituitary"},{"id":"b","text":"Hypothalamus"},{"id":"c","text":"Adrenal cortex"},{"id":"d","text":"Thyroid gland"}],"answerId":"b","explanation":"Oxytocin is synthesized in the hypothalamus and then transported to the posterior pituitary for release.","kind":"recall","origin":"ai"},{"id":"hen1-oxytocin-reflexes~ai-1","moduleId":"hen1-oxytocin-reflexes","stem":"What triggers the release of oxytocin during breastfeeding?","options":[{"id":"a","text":"Milk production"},{"id":"b","text":"Nipple stimulation"},{"id":"c","text":"Infant crying"},{"id":"d","text":"Maternal stress"}],"answerId":"b","explanation":"Nipple stimulation activates sensory pathways that trigger the pulsatile release of oxytocin.","kind":"mechanism","origin":"ai"},{"id":"hen1-oxytocin-reflexes~ai-2","moduleId":"hen1-oxytocin-reflexes","stem":"What is the mechanism of action of oxytocin on myoepithelial cells?","options":[{"id":"a","text":"Inhibition of adenylate cyclase"},{"id":"b","text":"Activation of Gs protein"},{"id":"c","text":"Increase in intracellular Ca²⁺"},{"id":"d","text":"Blocking of calcium channels"}],"answerId":"c","explanation":"Oxytocin receptors are Gq-coupled, leading to an increase in intracellular Ca²⁺ in myoepithelial cells.","kind":"mechanism","origin":"ai"},{"id":"hen1-oxytocin-reflexes~ai-3","moduleId":"hen1-oxytocin-reflexes","stem":"A woman is unable to eject milk despite adequate production. What is the most likely cause?","options":[{"id":"a","text":"Prolactin deficiency"},{"id":"b","text":"Oxytocin reflex impairment"},{"id":"c","text":"Myoepithelial cell dysfunction"},{"id":"d","text":"Nipple trauma"}],"answerId":"b","explanation":"Milk production is intact, but the impairment of the oxytocin reflex prevents milk ejection.","kind":"clinical","origin":"ai"},{"id":"hen1-oxytocin-reflexes~ai-4","moduleId":"hen1-oxytocin-reflexes","stem":"During labor, cervical stretch activates which reflex to enhance uterine contractions?","options":[{"id":"a","text":"Ferguson reflex"},{"id":"b","text":"Moro reflex"},{"id":"c","text":"Rooting reflex"},{"id":"d","text":"Palmar grasp reflex"}],"answerId":"a","explanation":"The Ferguson reflex is a positive-feedback loop that enhances uterine contractions during labor.","kind":"recall","origin":"ai"},{"id":"hen1-oxytocin-reflexes~ai-5","moduleId":"hen1-oxytocin-reflexes","stem":"Oxytocin is released from which part of the pituitary gland?","options":[{"id":"a","text":"Pars distalis"},{"id":"b","text":"Pars tuberalis"},{"id":"c","text":"Pars nervosa"},{"id":"d","text":"Pars intermedia"}],"answerId":"c","explanation":"Oxytocin is released from the posterior pituitary, specifically the pars nervosa.","kind":"trap","origin":"ai"},{"id":"hen1-oxytocin-reflexes~ai-6","moduleId":"hen1-oxytocin-reflexes","stem":"How does the action of oxytocin relate to the feedback mechanisms in homeostasis?","options":[{"id":"a","text":"It inhibits negative feedback loops"},{"id":"b","text":"It enhances positive feedback during childbirth"},{"id":"c","text":"It regulates blood pressure"},{"id":"d","text":"It decreases hormone secretion"}],"answerId":"b","explanation":"Oxytocin enhances positive feedback during childbirth, exemplifying a homeostatic mechanism.","kind":"integration","linkedModuleIds":["homeostasis-feedback-control"],"origin":"ai"},{"id":"hen1-oxytocin-reflexes~ai-7","moduleId":"hen1-oxytocin-reflexes","stem":"In what way does oxytocin's role in lactation connect to the mechanisms of prolactin?","options":[{"id":"a","text":"Both are synthesized in the same location"},{"id":"b","text":"Both are released in response to suckling"},{"id":"c","text":"Both inhibit milk production"},{"id":"d","text":"Both act on the same receptors"}],"answerId":"b","explanation":"Both oxytocin and prolactin are released in response to suckling, facilitating lactation.","kind":"integration","linkedModuleIds":["hrp1-suckling-prolactin-oxytocin"],"origin":"ai"}],"hen1-prolactin-lactation":[{"id":"hen1-prolactin-lactation~ai-0","moduleId":"hen1-prolactin-lactation","stem":"What is the primary role of prolactin in lactation?","options":[{"id":"a","text":"Milk ejection"},{"id":"b","text":"Milk synthesis"},{"id":"c","text":"Mammary gland development"},{"id":"d","text":"Uterine contraction"}],"answerId":"b","explanation":"Prolactin is primarily responsible for milk synthesis, while oxytocin is responsible for milk ejection.","kind":"recall","origin":"ai"},{"id":"hen1-prolactin-lactation~ai-1","moduleId":"hen1-prolactin-lactation","stem":"Which hormone predominantly inhibits prolactin secretion?","options":[{"id":"a","text":"Estrogen"},{"id":"b","text":"Progesterone"},{"id":"c","text":"Dopamine"},{"id":"d","text":"Oxytocin"}],"answerId":"c","explanation":"Dopamine is the dominant inhibitor of prolactin secretion from lactotrophs.","kind":"recall","origin":"ai"},{"id":"hen1-prolactin-lactation~ai-2","moduleId":"hen1-prolactin-lactation","stem":"A woman presents with galactorrhea and amenorrhea. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Increased estrogen levels"},{"id":"b","text":"Increased prolactin levels"},{"id":"c","text":"Decreased oxytocin levels"},{"id":"d","text":"Increased GnRH levels"}],"answerId":"b","explanation":"Hyperprolactinemia stimulates breast secretion and suppresses GnRH, leading to menstrual disturbances.","kind":"clinical","origin":"ai"},{"id":"hen1-prolactin-lactation~ai-3","moduleId":"hen1-prolactin-lactation","stem":"What is the mechanism by which suckling increases prolactin levels?","options":[{"id":"a","text":"Increased dopamine release"},{"id":"b","text":"Decreased dopamine inhibition"},{"id":"c","text":"Increased estrogen secretion"},{"id":"d","text":"Decreased oxytocin levels"}],"answerId":"b","explanation":"Suckling reduces dopaminergic inhibition, leading to increased prolactin pulses.","kind":"mechanism","origin":"ai"},{"id":"hen1-prolactin-lactation~ai-4","moduleId":"hen1-prolactin-lactation","stem":"In Sheehan syndrome, what is the primary consequence of anterior pituitary damage?","options":[{"id":"a","text":"Increased prolactin secretion"},{"id":"b","text":"Decreased growth hormone secretion"},{"id":"c","text":"Inability to lactate"},{"id":"d","text":"Increased ACTH secretion"}],"answerId":"c","explanation":"Sheehan syndrome leads to damage of prolactin-secreting cells, resulting in an inability to lactate after severe postpartum hemorrhage.","kind":"clinical","origin":"ai"},{"id":"hen1-prolactin-lactation~ai-5","moduleId":"hen1-prolactin-lactation","stem":"Which statement correctly differentiates the roles of prolactin and oxytocin in lactation?","options":[{"id":"a","text":"Both are responsible for milk synthesis"},{"id":"b","text":"Prolactin is for milk ejection, oxytocin for synthesis"},{"id":"c","text":"Prolactin synthesizes milk, oxytocin ejects it"},{"id":"d","text":"Oxytocin inhibits prolactin secretion"}],"answerId":"c","explanation":"Prolactin is responsible for milk synthesis, while oxytocin contracts myoepithelial cells for milk ejection.","kind":"trap","origin":"ai"},{"id":"hen1-prolactin-lactation~ai-6","moduleId":"hen1-prolactin-lactation","stem":"How does hyperprolactinemia affect the hypothalamic-pituitary-gonadal axis?","options":[{"id":"a","text":"Increases GnRH secretion"},{"id":"b","text":"Increases LH and FSH levels"},{"id":"c","text":"Suppresses GnRH secretion"},{"id":"d","text":"Increases estrogen levels"}],"answerId":"c","explanation":"High prolactin levels suppress GnRH, leading to lower LH and FSH levels.","kind":"integration","linkedModuleIds":["hen1-anterior-pituitary-axes"],"origin":"ai"},{"id":"hen1-prolactin-lactation~ai-7","moduleId":"hen1-prolactin-lactation","stem":"Which drug class is most likely to be used in the treatment of hyperprolactinemia?","options":[{"id":"a","text":"Growth hormone secretagogues"},{"id":"b","text":"Dopamine agonists"},{"id":"c","text":"Estrogen receptor modulators"},{"id":"d","text":"Oxytocin analogs"}],"answerId":"b","explanation":"Dopamine agonists are commonly used to treat hyperprolactinemia by enhancing dopaminergic inhibition of prolactin secretion.","kind":"integration","linkedModuleIds":["growth-hormone-prolactin-drugs"],"origin":"ai"}],"hen1-peptide-catecholamine-hormones":[{"id":"hen1-peptide-catecholamine-hormones~ai-0","moduleId":"hen1-peptide-catecholamine-hormones","stem":"What is the primary mechanism by which peptide hormones exert their effects on target cells?","options":[{"id":"a","text":"Directly activate nuclear receptors"},{"id":"b","text":"Signal through cell-surface receptors"},{"id":"c","text":"Diffuse across the cell membrane"},{"id":"d","text":"Inhibit enzyme activity directly"}],"answerId":"b","explanation":"Peptide hormones signal through cell-surface receptors because they cannot cross lipid membranes.","kind":"mechanism","origin":"ai"},{"id":"hen1-peptide-catecholamine-hormones~ai-1","moduleId":"hen1-peptide-catecholamine-hormones","stem":"Which of the following statements about catecholamines is true?","options":[{"id":"a","text":"They are stored in the nucleus"},{"id":"b","text":"They have long half-lives in circulation"},{"id":"c","text":"They are derived from tyrosine"},{"id":"d","text":"They act through intracellular receptors"}],"answerId":"c","explanation":"Catecholamines are derived from tyrosine and are stored in vesicles for rapid release.","kind":"recall","origin":"ai"},{"id":"hen1-peptide-catecholamine-hormones~ai-2","moduleId":"hen1-peptide-catecholamine-hormones","stem":"What is a characteristic clinical finding associated with peptide hormone secretion?","options":[{"id":"a","text":"Prolonged hormonal response"},{"id":"b","text":"Rapid onset and short-lived response"},{"id":"c","text":"Increased blood viscosity"},{"id":"d","text":"Decreased metabolic rate"}],"answerId":"b","explanation":"Peptide hormones are released quickly and have a rapid onset with short-lived effects.","kind":"recall","origin":"ai"},{"id":"hen1-peptide-catecholamine-hormones~ai-3","moduleId":"hen1-peptide-catecholamine-hormones","stem":"Which of the following is a trap regarding peptide hormone synthesis?","options":[{"id":"a","text":"Peptide hormones are stored for rapid release"},{"id":"b","text":"Peptide hormones are synthesized only when needed"},{"id":"c","text":"Peptide hormones diffuse out immediately"},{"id":"d","text":"Peptide hormones are released by passive diffusion"}],"answerId":"b","explanation":"Peptide hormones are synthesized in advance, stored in granules, and released by exocytosis, contrary to the trap statement.","kind":"trap","origin":"ai"},{"id":"hen1-peptide-catecholamine-hormones~ai-4","moduleId":"hen1-peptide-catecholamine-hormones","stem":"In a patient with pheochromocytoma, which catecholamine is most likely to be elevated?","options":[{"id":"a","text":"Insulin"},{"id":"b","text":"Epinephrine"},{"id":"c","text":"Cortisol"},{"id":"d","text":"Thyroxine"}],"answerId":"b","explanation":"Pheochromocytoma typically leads to elevated levels of catecholamines, particularly epinephrine.","kind":"integration","linkedModuleIds":["pheochromocytoma-paraganglioma"],"origin":"ai"},{"id":"hen1-peptide-catecholamine-hormones~ai-5","moduleId":"hen1-peptide-catecholamine-hormones","stem":"What is the role of C-peptide in evaluating insulin secretion?","options":[{"id":"a","text":"Indicates insulin resistance"},{"id":"b","text":"Serves as a marker of endogenous insulin production"},{"id":"c","text":"Inhibits glucagon release"},{"id":"d","text":"Stimulates glucogenesis"}],"answerId":"b","explanation":"C-peptide is released in equimolar amounts with insulin and serves as a marker of endogenous insulin production.","kind":"recall","origin":"ai"},{"id":"hen1-peptide-catecholamine-hormones~ai-6","moduleId":"hen1-peptide-catecholamine-hormones","stem":"How do peptide hormones differ from catecholamines in terms of their signaling mechanism?","options":[{"id":"a","text":"Peptide hormones act through nuclear receptors"},{"id":"b","text":"Catecholamines are stored in the nucleus"},{"id":"c","text":"Peptide hormones signal through cell-surface receptors"},{"id":"d","text":"Catecholamines diffuse across the cell membrane"}],"answerId":"c","explanation":"Peptide hormones signal through cell-surface receptors, while catecholamines also act through membrane receptors but are derived from a different precursor.","kind":"integration","linkedModuleIds":["hen1-endocrine-signaling-glands"],"origin":"ai"}],"hen1-anterior-pituitary-axes":[{"id":"hen1-anterior-pituitary-axes~ai-0","moduleId":"hen1-anterior-pituitary-axes","stem":"Which hormone is primarily responsible for stimulating the adrenal cortex to produce cortisol?","options":[{"id":"a","text":"TSH"},{"id":"b","text":"ACTH"},{"id":"c","text":"LH"},{"id":"d","text":"FSH"}],"answerId":"b","explanation":"ACTH (Adrenocorticotropic hormone) stimulates the adrenal cortex to produce cortisol.","kind":"recall","origin":"ai"},{"id":"hen1-anterior-pituitary-axes~ai-1","moduleId":"hen1-anterior-pituitary-axes","stem":"What is the primary mechanism by which GHRH influences growth hormone secretion?","options":[{"id":"a","text":"Inhibits somatostatin release"},{"id":"b","text":"Stimulates GH release directly"},{"id":"c","text":"Inhibits dopamine release"},{"id":"d","text":"Stimulates GH release indirectly via IGF-1"}],"answerId":"b","explanation":"GHRH directly stimulates the anterior pituitary to release growth hormone.","kind":"mechanism","origin":"ai"},{"id":"hen1-anterior-pituitary-axes~ai-2","moduleId":"hen1-anterior-pituitary-axes","stem":"A patient presents with low levels of T3 and T4 after a sellar injury. What is the most likely cause?","options":[{"id":"a","text":"Thyroid gland failure"},{"id":"b","text":"Anterior pituitary damage"},{"id":"c","text":"Hypothalamic dysfunction"},{"id":"d","text":"Increased TRH levels"}],"answerId":"b","explanation":"Sellar injury can damage the anterior pituitary, disrupting the secretion of TSH and consequently lowering T3 and T4 levels.","kind":"clinical","origin":"ai"},{"id":"hen1-anterior-pituitary-axes~ai-3","moduleId":"hen1-anterior-pituitary-axes","stem":"Which statement about prolactin regulation is true?","options":[{"id":"a","text":"It is primarily stimulated by hypothalamic releasing hormones."},{"id":"b","text":"It is under tonic inhibition by hypothalamic dopamine."},{"id":"c","text":"It has no feedback mechanism."},{"id":"d","text":"It is primarily regulated by somatostatin."}],"answerId":"b","explanation":"Prolactin is primarily under tonic inhibition by hypothalamic dopamine, meaning its levels increase when dopamine is blocked.","kind":"trap","origin":"ai"},{"id":"hen1-anterior-pituitary-axes~ai-4","moduleId":"hen1-anterior-pituitary-axes","stem":"How does somatostatin affect growth hormone levels?","options":[{"id":"a","text":"Stimulates GH release"},{"id":"b","text":"Inhibits GH release"},{"id":"c","text":"Has no effect on GH"},{"id":"d","text":"Increases IGF-1 levels"}],"answerId":"b","explanation":"Somatostatin inhibits the release of growth hormone from the anterior pituitary.","kind":"mechanism","origin":"ai"},{"id":"hen1-anterior-pituitary-axes~ai-5","moduleId":"hen1-anterior-pituitary-axes","stem":"How does the feedback mechanism of cortisol affect ACTH secretion?","options":[{"id":"a","text":"Cortisol stimulates ACTH release"},{"id":"b","text":"Cortisol has no effect on ACTH"},{"id":"c","text":"Cortisol inhibits ACTH release"},{"id":"d","text":"Cortisol increases CRH levels"}],"answerId":"c","explanation":"Cortisol exerts long-loop negative feedback on ACTH secretion from the anterior pituitary.","kind":"mechanism","origin":"ai"},{"id":"hen1-anterior-pituitary-axes~ai-6","moduleId":"hen1-anterior-pituitary-axes","stem":"In a patient with growth hormone deficiency, which hormone's levels would most likely be low?","options":[{"id":"a","text":"IGF-1"},{"id":"b","text":"Prolactin"},{"id":"c","text":"Cortisol"},{"id":"d","text":"TSH"}],"answerId":"a","explanation":"Growth hormone deficiency typically leads to low levels of IGF-1, which is stimulated by growth hormone.","kind":"integration","linkedModuleIds":["hen1-growth-hormone-igf1"],"origin":"ai"},{"id":"hen1-anterior-pituitary-axes~ai-7","moduleId":"hen1-anterior-pituitary-axes","stem":"A patient with hyperprolactinemia is treated with a dopamine agonist. What is the expected outcome?","options":[{"id":"a","text":"Increased prolactin levels"},{"id":"b","text":"Decreased prolactin levels"},{"id":"c","text":"No change in prolactin levels"},{"id":"d","text":"Increased GH levels"}],"answerId":"b","explanation":"Dopamine agonists decrease prolactin levels by enhancing the tonic inhibition of prolactin secretion.","kind":"integration","linkedModuleIds":["hen1-prolactin-lactation"],"origin":"ai"}],"hen1-hypothalamus-anatomy-nuclei":[{"id":"hen1-hypothalamus-anatomy-nuclei~ai-0","moduleId":"hen1-hypothalamus-anatomy-nuclei","stem":"Which structure forms the inferolateral walls of the third ventricle?","options":[{"id":"a","text":"Thalamus"},{"id":"b","text":"Hypothalamus"},{"id":"c","text":"Pineal gland"},{"id":"d","text":"Subthalamic nucleus"}],"answerId":"b","explanation":"The hypothalamus forms the inferolateral walls and floor of the third ventricle.","kind":"recall","origin":"ai"},{"id":"hen1-hypothalamus-anatomy-nuclei~ai-1","moduleId":"hen1-hypothalamus-anatomy-nuclei","stem":"What is the primary function of parvocellular neurons in the hypothalamus?","options":[{"id":"a","text":"Synthesize ADH"},{"id":"b","text":"Release oxytocin"},{"id":"c","text":"Regulate anterior pituitary cells"},{"id":"d","text":"Control body temperature"}],"answerId":"c","explanation":"Parvocellular neurons release factors into the median-eminence portal circulation to regulate anterior pituitary cells.","kind":"mechanism","origin":"ai"},{"id":"hen1-hypothalamus-anatomy-nuclei~ai-2","moduleId":"hen1-hypothalamus-anatomy-nuclei","stem":"A patient presents with polyuria after a hypothalamic injury. What is the most likely cause?","options":[{"id":"a","text":"Increased ADH synthesis"},{"id":"b","text":"Disrupted ADH synthesis"},{"id":"c","text":"Increased thirst response"},{"id":"d","text":"Decreased aldosterone secretion"}],"answerId":"b","explanation":"Disrupted ADH synthesis or axonal transport causes central diabetes insipidus, leading to polyuria.","kind":"clinical","origin":"ai"},{"id":"hen1-hypothalamus-anatomy-nuclei~ai-3","moduleId":"hen1-hypothalamus-anatomy-nuclei","stem":"Which statement about the posterior pituitary is correct?","options":[{"id":"a","text":"It synthesizes ADH and oxytocin"},{"id":"b","text":"It stores and releases hormones"},{"id":"c","text":"It regulates appetite"},{"id":"d","text":"It integrates autonomic functions"}],"answerId":"b","explanation":"The posterior pituitary stores and releases ADH and oxytocin, which are synthesized by hypothalamic neurons.","kind":"trap","origin":"ai"},{"id":"hen1-hypothalamus-anatomy-nuclei~ai-4","moduleId":"hen1-hypothalamus-anatomy-nuclei","stem":"How do hypothalamic neurons convert neural information into endocrine output?","options":[{"id":"a","text":"By direct secretion into the bloodstream"},{"id":"b","text":"By synaptic transmission to the pituitary"},{"id":"c","text":"By axonal transport of hormones"},{"id":"d","text":"By stimulating the adrenal gland"}],"answerId":"c","explanation":"Hypothalamic neurons synthesize hormones and transport them axonally to the posterior pituitary for release.","kind":"mechanism","origin":"ai"},{"id":"hen1-hypothalamus-anatomy-nuclei~ai-5","moduleId":"hen1-hypothalamus-anatomy-nuclei","stem":"Which hypothalamic function is most directly related to circadian rhythms?","options":[{"id":"a","text":"Temperature regulation"},{"id":"b","text":"Appetite control"},{"id":"c","text":"Stress response"},{"id":"d","text":"Sleep-wake cycle regulation"}],"answerId":"d","explanation":"The hypothalamus plays a crucial role in regulating the sleep-wake cycle, which is tied to circadian rhythms.","kind":"recall","origin":"ai"},{"id":"hen1-hypothalamus-anatomy-nuclei~ai-6","moduleId":"hen1-hypothalamus-anatomy-nuclei","stem":"How does the hypothalamus interact with the limbic system?","options":[{"id":"a","text":"It inhibits limbic activity"},{"id":"b","text":"It processes sensory information"},{"id":"c","text":"It regulates emotional responses"},{"id":"d","text":"It controls motor functions"}],"answerId":"c","explanation":"The hypothalamus integrates with the limbic system to regulate emotional responses and behaviors.","kind":"integration","linkedModuleIds":["limbic-hypothalamus"],"origin":"ai"},{"id":"hen1-hypothalamus-anatomy-nuclei~ai-7","moduleId":"hen1-hypothalamus-anatomy-nuclei","stem":"What is the role of the hypothalamus in the stress response?","options":[{"id":"a","text":"Secretes cortisol directly"},{"id":"b","text":"Activates the autonomic nervous system"},{"id":"c","text":"Inhibits the immune response"},{"id":"d","text":"Regulates blood glucose levels"}],"answerId":"b","explanation":"The hypothalamus activates the autonomic nervous system as part of the body's stress response.","kind":"clinical","origin":"ai"},{"id":"hen1-hypothalamus-anatomy-nuclei~ai-8","moduleId":"hen1-hypothalamus-anatomy-nuclei","stem":"Which hormone is primarily affected by damage to the hypothalamus?","options":[{"id":"a","text":"Insulin"},{"id":"b","text":"Cortisol"},{"id":"c","text":"ADH"},{"id":"d","text":"Thyroxine"}],"answerId":"c","explanation":"Damage to the hypothalamus can disrupt the synthesis and release of ADH, leading to conditions like diabetes insipidus.","kind":"clinical","origin":"ai"}],"hen1-pituitary-histology":[{"id":"hen1-pituitary-histology~ai-0","moduleId":"hen1-pituitary-histology","stem":"Which cell type in the pars distalis is responsible for producing growth hormone?","options":[{"id":"a","text":"Somatotrophs"},{"id":"b","text":"Corticotrophs"},{"id":"c","text":"Thyrotrophs"},{"id":"d","text":"Gonadotrophs"}],"answerId":"a","explanation":"Somatotrophs are the acidophils in the pars distalis that produce growth hormone.","kind":"recall","origin":"ai"},{"id":"hen1-pituitary-histology~ai-1","moduleId":"hen1-pituitary-histology","stem":"What histological feature is characteristic of the pars nervosa?","options":[{"id":"a","text":"Colloid-filled cysts"},{"id":"b","text":"Eosinophilic cells"},{"id":"c","text":"Herring bodies"},{"id":"d","text":"Fenestrated capillaries"}],"answerId":"c","explanation":"Herring bodies are dilated axon terminals in the pars nervosa that store neurosecretory granules.","kind":"recall","origin":"ai"},{"id":"hen1-pituitary-histology~ai-2","moduleId":"hen1-pituitary-histology","stem":"Which of the following best describes the function of Herring bodies?","options":[{"id":"a","text":"They produce hormones in the posterior pituitary."},{"id":"b","text":"They are dilated axon terminals storing neurosecretory products."},{"id":"c","text":"They are endocrine cells in the pars distalis."},{"id":"d","text":"They are remnants of Rathke's pouch."}],"answerId":"b","explanation":"Herring bodies are dilated axon terminals in the pars nervosa that store neurosecretory products from the hypothalamus.","kind":"trap","origin":"ai"},{"id":"hen1-pituitary-histology~ai-3","moduleId":"hen1-pituitary-histology","stem":"What is the primary role of the pars intermedia in the pituitary gland?","options":[{"id":"a","text":"Production of growth hormone"},{"id":"b","text":"Secretion of ACTH"},{"id":"c","text":"Containment of colloid-filled remnants"},{"id":"d","text":"Storage of oxytocin"}],"answerId":"c","explanation":"The pars intermedia may contain colloid-filled remnants of Rathke's pouch.","kind":"recall","origin":"ai"},{"id":"hen1-pituitary-histology~ai-4","moduleId":"hen1-pituitary-histology","stem":"Which structure wraps around the infundibulum?","options":[{"id":"a","text":"Pars distalis"},{"id":"b","text":"Pars intermedia"},{"id":"c","text":"Pars tuberalis"},{"id":"d","text":"Pars nervosa"}],"answerId":"c","explanation":"The pars tuberalis is the part of the adenohypophysis that wraps around the infundibulum.","kind":"recall","origin":"ai"},{"id":"hen1-pituitary-histology~ai-5","moduleId":"hen1-pituitary-histology","stem":"How does the histological appearance of the anterior pituitary differ from the posterior pituitary?","options":[{"id":"a","text":"More cellular in anterior pituitary"},{"id":"b","text":"Presence of Herring bodies in anterior pituitary"},{"id":"c","text":"Unmyelinated axons in anterior pituitary"},{"id":"d","text":"Colloid-filled cysts in posterior pituitary"}],"answerId":"a","explanation":"The anterior pituitary (pars distalis) is more cellular due to the presence of various hormone-producing cells.","kind":"mechanism","origin":"ai"},{"id":"hen1-pituitary-histology~ai-6","moduleId":"hen1-pituitary-histology","stem":"How does the hypothalamus influence the anterior pituitary?","options":[{"id":"a","text":"Direct secretion of hormones"},{"id":"b","text":"Via the hypophyseal portal system"},{"id":"c","text":"Through neural connections only"},{"id":"d","text":"By regulating blood flow to the posterior pituitary"}],"answerId":"b","explanation":"The hypothalamus influences the anterior pituitary via the hypophyseal portal system, allowing for the delivery of releasing hormones.","kind":"integration","linkedModuleIds":["hen1-pituitary-portal-blood-supply"],"origin":"ai"},{"id":"hen1-pituitary-histology~ai-7","moduleId":"hen1-pituitary-histology","stem":"Which hypothalamic nuclei are primarily involved in regulating the secretion of hormones from the posterior pituitary?","options":[{"id":"a","text":"Supraoptic and paraventricular nuclei"},{"id":"b","text":"Ventromedial and arcuate nuclei"},{"id":"c","text":"Lateral and preoptic nuclei"},{"id":"d","text":"Dorsomedial and posterior nuclei"}],"answerId":"a","explanation":"The supraoptic and paraventricular nuclei are responsible for synthesizing oxytocin and vasopressin, which are stored in the posterior pituitary.","kind":"integration","linkedModuleIds":["hen1-hypothalamus-anatomy-nuclei"],"origin":"ai"}],"hen1-pituitary-portal-blood-supply":[{"id":"hen1-pituitary-portal-blood-supply~ai-0","moduleId":"hen1-pituitary-portal-blood-supply","stem":"What is the primary function of the portal veins in the pituitary blood supply?","options":[{"id":"a","text":"To supply oxygenated blood to the anterior pituitary"},{"id":"b","text":"To transport hypothalamic hormones directly to the anterior pituitary"},{"id":"c","text":"To drain blood from the anterior pituitary into systemic circulation"},{"id":"d","text":"To connect the anterior and posterior pituitary lobes"}],"answerId":"b","explanation":"The portal veins carry hypothalamic releasing and inhibiting hormones directly to the anterior pituitary, allowing for high concentrations without dilution.","kind":"recall","origin":"ai"},{"id":"hen1-pituitary-portal-blood-supply~ai-1","moduleId":"hen1-pituitary-portal-blood-supply","stem":"Which artery primarily supplies the posterior lobe of the pituitary gland?","options":[{"id":"a","text":"Superior hypophyseal artery"},{"id":"b","text":"Inferior hypophyseal artery"},{"id":"c","text":"Middle cerebral artery"},{"id":"d","text":"Anterior communicating artery"}],"answerId":"b","explanation":"The inferior hypophyseal arteries chiefly supply the posterior lobe, where neurosecretory terminals release hormones into systemic circulation.","kind":"recall","origin":"ai"},{"id":"hen1-pituitary-portal-blood-supply~ai-2","moduleId":"hen1-pituitary-portal-blood-supply","stem":"What is the effect of pituitary stalk interruption on prolactin levels?","options":[{"id":"a","text":"All anterior-pituitary hormones decrease, including prolactin"},{"id":"b","text":"Prolactin levels remain unchanged"},{"id":"c","text":"Prolactin levels increase due to loss of dopamine inhibition"},{"id":"d","text":"Prolactin levels decrease due to loss of stimulation"}],"answerId":"c","explanation":"Interruption of the stalk removes dopamine's inhibitory effect on prolactin, leading to increased levels.","kind":"trap","origin":"ai"},{"id":"hen1-pituitary-portal-blood-supply~ai-3","moduleId":"hen1-pituitary-portal-blood-supply","stem":"What clinical finding is associated with anterior pituitary ischemia after severe postpartum hemorrhage?","options":[{"id":"a","text":"Hyperprolactinemia"},{"id":"b","text":"Cushing's syndrome"},{"id":"c","text":"Hypothyroidism"},{"id":"d","text":"Adrenal insufficiency"}],"answerId":"a","explanation":"Anterior pituitary ischemia can lead to hyperprolactinemia due to the loss of normal hormonal regulation.","kind":"clinical","origin":"ai"},{"id":"hen1-pituitary-portal-blood-supply~ai-4","moduleId":"hen1-pituitary-portal-blood-supply","stem":"Which of the following statements about the pituitary portal system is true?","options":[{"id":"a","text":"It allows systemic circulation to deliver hormones to the anterior pituitary."},{"id":"b","text":"It provides a direct connection between the hypothalamus and the posterior pituitary."},{"id":"c","text":"It ensures high concentrations of hypothalamic hormones reach the anterior pituitary."},{"id":"d","text":"It connects the anterior pituitary to the adrenal glands."}],"answerId":"c","explanation":"The portal system is designed to deliver high concentrations of releasing and inhibiting hormones directly to the anterior pituitary.","kind":"mechanism","origin":"ai"},{"id":"hen1-pituitary-portal-blood-supply~ai-5","moduleId":"hen1-pituitary-portal-blood-supply","stem":"How does the blood supply of the pituitary gland compare to that of the gastrointestinal tract?","options":[{"id":"a","text":"Both have a similar portal system structure."},{"id":"b","text":"The pituitary has a single capillary bed, while the GI tract has two."},{"id":"c","text":"The GI tract has a higher concentration of hormones in systemic circulation."},{"id":"d","text":"Both systems are regulated by the same hormones."}],"answerId":"a","explanation":"Both the pituitary and gastrointestinal systems utilize a two-capillary portal system to efficiently deliver hormones.","kind":"integration","linkedModuleIds":["gi-blood-supply-portal-system"],"origin":"ai"},{"id":"hen1-pituitary-portal-blood-supply~ai-6","moduleId":"hen1-pituitary-portal-blood-supply","stem":"Which hormone is primarily affected by the interruption of dopamine delivery in the pituitary stalk?","options":[{"id":"a","text":"Thyroid-stimulating hormone (TSH)"},{"id":"b","text":"Adrenocorticotropic hormone (ACTH)"},{"id":"c","text":"Luteinizing hormone (LH)"},{"id":"d","text":"Prolactin"}],"answerId":"d","explanation":"Dopamine normally inhibits prolactin secretion; thus, its interruption leads to increased prolactin levels.","kind":"integration","linkedModuleIds":["hen1-hypothalamus-anatomy-nuclei"],"origin":"ai"}],"hen1-steroid-thyroid-hormone-biology":[{"id":"hen1-steroid-thyroid-hormone-biology~ai-0","moduleId":"hen1-steroid-thyroid-hormone-biology","stem":"What is the primary source of steroid hormones in the body?","options":[{"id":"a","text":"Cholesterol"},{"id":"b","text":"Fatty acids"},{"id":"c","text":"Amino acids"},{"id":"d","text":"Glucose"}],"answerId":"a","explanation":"Steroid hormones are synthesized from cholesterol, which serves as their precursor.","kind":"recall","origin":"ai"},{"id":"hen1-steroid-thyroid-hormone-biology~ai-1","moduleId":"hen1-steroid-thyroid-hormone-biology","stem":"Which of the following best describes the mechanism of action of thyroid hormones?","options":[{"id":"a","text":"They bind to cell surface receptors."},{"id":"b","text":"They alter gene transcription by binding intracellular receptors."},{"id":"c","text":"They act as neurotransmitters."},{"id":"d","text":"They inhibit protein synthesis."}],"answerId":"b","explanation":"Thyroid hormones bind to intracellular receptors, regulating gene transcription and producing long-lasting effects.","kind":"mechanism","origin":"ai"},{"id":"hen1-steroid-thyroid-hormone-biology~ai-2","moduleId":"hen1-steroid-thyroid-hormone-biology","stem":"A patient shows elevated total T4 levels but normal free T4 levels and no symptoms. What is the most likely explanation?","options":[{"id":"a","text":"Increased thyroid hormone production"},{"id":"b","text":"Increased binding protein concentration"},{"id":"c","text":"Decreased thyroid hormone clearance"},{"id":"d","text":"Thyroid hormone resistance"}],"answerId":"b","explanation":"Increased binding protein concentration can elevate total hormone levels without affecting the free fraction.","kind":"trap","origin":"ai"},{"id":"hen1-steroid-thyroid-hormone-biology~ai-3","moduleId":"hen1-steroid-thyroid-hormone-biology","stem":"What is the primary function of the enzyme converting T4 to T3?","options":[{"id":"a","text":"To increase thyroid hormone storage"},{"id":"b","text":"To activate thyroid hormone"},{"id":"c","text":"To inactivate thyroid hormone"},{"id":"d","text":"To transport thyroid hormone"}],"answerId":"b","explanation":"The conversion of T4 to T3 activates the thyroid hormone, enhancing its biological activity.","kind":"mechanism","origin":"ai"},{"id":"hen1-steroid-thyroid-hormone-biology~ai-4","moduleId":"hen1-steroid-thyroid-hormone-biology","stem":"Which of the following findings would suggest a delayed but sustained response to hormone therapy?","options":[{"id":"a","text":"Rapid onset of symptoms"},{"id":"b","text":"Immediate changes in hormone levels"},{"id":"c","text":"Changes in gene expression over hours to days"},{"id":"d","text":"Short-lived effects"}],"answerId":"c","explanation":"Hormones that mediate their effects through transcription and new protein synthesis typically show delayed but sustained responses.","kind":"clinical","origin":"ai"},{"id":"hen1-steroid-thyroid-hormone-biology~ai-5","moduleId":"hen1-steroid-thyroid-hormone-biology","stem":"How does the free fraction of steroid hormones differ from the bound fraction?","options":[{"id":"a","text":"The free fraction is less active."},{"id":"b","text":"The bound fraction is bioavailable."},{"id":"c","text":"The free fraction readily enters cells."},{"id":"d","text":"The bound fraction is more stable."}],"answerId":"c","explanation":"Only unbound or free hormone can readily cross cell membranes and exert biological effects.","kind":"trap","origin":"ai"},{"id":"hen1-steroid-thyroid-hormone-biology~ai-6","moduleId":"hen1-steroid-thyroid-hormone-biology","stem":"How do thyroid hormones influence the feedback mechanisms in the endocrine system?","options":[{"id":"a","text":"They primarily act on the adrenal glands."},{"id":"b","text":"They regulate the hypothalamic-pituitary axis."},{"id":"c","text":"They only affect peripheral tissues."},{"id":"d","text":"They inhibit steroid hormone production."}],"answerId":"b","explanation":"Thyroid hormones play a crucial role in regulating the hypothalamic-pituitary axis through feedback mechanisms.","kind":"integration","linkedModuleIds":["hen1-endocrine-feedback-loops"],"origin":"ai"},{"id":"hen1-steroid-thyroid-hormone-biology~ai-7","moduleId":"hen1-steroid-thyroid-hormone-biology","stem":"Which hormone's action is directly linked to changes in gene transcription and is influenced by binding proteins?","options":[{"id":"a","text":"Insulin"},{"id":"b","text":"Thyroid hormone"},{"id":"c","text":"Epinephrine"},{"id":"d","text":"Glucagon"}],"answerId":"b","explanation":"Thyroid hormones act through gene transcription and are significantly affected by binding proteins in circulation.","kind":"integration","linkedModuleIds":["hen1-endocrine-signaling-glands"],"origin":"ai"}],"hen1-growth-hormone-igf1":[{"id":"hen1-growth-hormone-igf1~ai-0","moduleId":"hen1-growth-hormone-igf1","stem":"What stimulates the secretion of Growth Hormone (GH)?","options":[{"id":"a","text":"Somatostatin"},{"id":"b","text":"Hyperglycemia"},{"id":"c","text":"GHRH"},{"id":"d","text":"IGF-1"}],"answerId":"c","explanation":"GHRH stimulates GH secretion, while somatostatin and IGF-1 inhibit it.","kind":"recall","origin":"ai"},{"id":"hen1-growth-hormone-igf1~ai-1","moduleId":"hen1-growth-hormone-igf1","stem":"Which mechanism primarily mediates the growth effects of GH?","options":[{"id":"a","text":"Direct action on muscle cells"},{"id":"b","text":"Activation of JAK2-STAT signaling"},{"id":"c","text":"Inhibition of insulin secretion"},{"id":"d","text":"Promotion of fatty acid synthesis"}],"answerId":"b","explanation":"GH receptor activation leads to JAK2-STAT signaling, which mediates growth effects.","kind":"mechanism","origin":"ai"},{"id":"hen1-growth-hormone-igf1~ai-2","moduleId":"hen1-growth-hormone-igf1","stem":"A 25-year-old male presents with coarse facial features and enlarged hands. What is the most likely diagnosis?","options":[{"id":"a","text":"Acromegaly"},{"id":"b","text":"Gigantism"},{"id":"c","text":"Proportionate short stature"},{"id":"d","text":"Cushing's syndrome"}],"answerId":"a","explanation":"These features are characteristic of acromegaly due to GH excess after epiphyseal closure.","kind":"clinical","origin":"ai"},{"id":"hen1-growth-hormone-igf1~ai-3","moduleId":"hen1-growth-hormone-igf1","stem":"Why is IGF-1 preferred over random GH levels for diagnosing acromegaly?","options":[{"id":"a","text":"IGF-1 is always elevated in acromegaly"},{"id":"b","text":"GH secretion is pulsatile"},{"id":"c","text":"IGF-1 is easier to measure"},{"id":"d","text":"IGF-1 levels do not fluctuate"}],"answerId":"b","explanation":"GH secretion is pulsatile, making a single random level unreliable for diagnosis.","kind":"trap","origin":"ai"},{"id":"hen1-growth-hormone-igf1~ai-4","moduleId":"hen1-growth-hormone-igf1","stem":"What is the primary effect of GH on glucose metabolism?","options":[{"id":"a","text":"Increases insulin sensitivity"},{"id":"b","text":"Promotes lipogenesis"},{"id":"c","text":"Increases insulin resistance"},{"id":"d","text":"Decreases hepatic glucose output"}],"answerId":"c","explanation":"GH increases insulin resistance, which helps maintain glucose levels during fasting.","kind":"mechanism","origin":"ai"},{"id":"hen1-growth-hormone-igf1~ai-5","moduleId":"hen1-growth-hormone-igf1","stem":"How does GH excess after epiphyseal closure primarily affect bone structure?","options":[{"id":"a","text":"Increases length of long bones"},{"id":"b","text":"Increases density of cortical bone"},{"id":"c","text":"Expands soft tissue and membranous bone"},{"id":"d","text":"Decreases bone mineral density"}],"answerId":"c","explanation":"GH excess leads to expansion of soft tissue and membranous bone, characteristic of acromegaly.","kind":"clinical","origin":"ai"},{"id":"hen1-growth-hormone-igf1~ai-6","moduleId":"hen1-growth-hormone-igf1","stem":"How might GH and IGF-1 levels be relevant in the context of pituitary adenomas?","options":[{"id":"a","text":"They inhibit tumor growth"},{"id":"b","text":"They are used to assess pituitary function"},{"id":"c","text":"They can indicate hyperpituitarism"},{"id":"d","text":"They directly cause acromegaly"}],"answerId":"c","explanation":"Elevated GH and IGF-1 levels can indicate hyperpituitarism due to pituitary adenomas.","kind":"integration","linkedModuleIds":["pituitary-adenomas-hyperpituitarism"],"origin":"ai"},{"id":"hen1-growth-hormone-igf1~ai-7","moduleId":"hen1-growth-hormone-igf1","stem":"What is the relationship between GH and the anterior pituitary hormones?","options":[{"id":"a","text":"GH inhibits ACTH secretion"},{"id":"b","text":"GH is secreted in response to TSH"},{"id":"c","text":"GH acts independently of other hormones"},{"id":"d","text":"GH is regulated by GHRH from the hypothalamus"}],"answerId":"d","explanation":"GH secretion is regulated by GHRH from the hypothalamus, linking it to anterior pituitary function.","kind":"integration","linkedModuleIds":["hen1-anterior-pituitary-axes"],"origin":"ai"}],"hen1-endocrine-feedback-loops":[{"id":"hen1-endocrine-feedback-loops~ai-0","moduleId":"hen1-endocrine-feedback-loops","stem":"What is the primary mechanism of negative feedback in endocrine regulation?","options":[{"id":"a","text":"Final output feeds back to restrain upstream drive"},{"id":"b","text":"Upstream hormones stimulate downstream glands"},{"id":"c","text":"External factors directly influence hormone levels"},{"id":"d","text":"Hormones exert effects through positive feedback loops"}],"answerId":"a","explanation":"Negative feedback involves the final output inhibiting the secretion of upstream hormones, stabilizing the regulated variable.","kind":"mechanism","origin":"ai"},{"id":"hen1-endocrine-feedback-loops~ai-1","moduleId":"hen1-endocrine-feedback-loops","stem":"In primary adrenal insufficiency, what would you expect to find in hormone levels?","options":[{"id":"a","text":"High cortisol with low ACTH"},{"id":"b","text":"Low cortisol with high ACTH"},{"id":"c","text":"Low cortisol with low ACTH"},{"id":"d","text":"Normal cortisol with high ACTH"}],"answerId":"b","explanation":"In primary adrenal insufficiency, the adrenal glands fail to produce cortisol, leading to high ACTH due to loss of negative feedback.","kind":"recall","origin":"ai"},{"id":"hen1-endocrine-feedback-loops~ai-2","moduleId":"hen1-endocrine-feedback-loops","stem":"Which scenario best illustrates a positive feedback mechanism?","options":[{"id":"a","text":"Insulin secretion in response to high blood glucose"},{"id":"b","text":"Oxytocin release during labor contractions"},{"id":"c","text":"Thyroid hormone regulation by TSH"},{"id":"d","text":"Cortisol release in response to stress"}],"answerId":"b","explanation":"Oxytocin release during labor is a classic example of positive feedback, amplifying contractions until delivery.","kind":"recall","origin":"ai"},{"id":"hen1-endocrine-feedback-loops~ai-3","moduleId":"hen1-endocrine-feedback-loops","stem":"What finding suggests pituitary dysfunction in hormone regulation?","options":[{"id":"a","text":"Low target hormone with high tropic hormone"},{"id":"b","text":"Low target hormone with low tropic hormone"},{"id":"c","text":"Normal target hormone with high tropic hormone"},{"id":"d","text":"High target hormone with low tropic hormone"}],"answerId":"b","explanation":"Low target hormone with low tropic hormone indicates a failure in the pituitary or hypothalamus, as there is no appropriate stimulation.","kind":"recall","origin":"ai"},{"id":"hen1-endocrine-feedback-loops~ai-4","moduleId":"hen1-endocrine-feedback-loops","stem":"A patient presents with low thyroid hormone levels but normal TSH. What is the likely diagnosis?","options":[{"id":"a","text":"Primary hyperthyroidism"},{"id":"b","text":"Secondary hypothyroidism"},{"id":"c","text":"Primary hypothyroidism"},{"id":"d","text":"Pituitary dysfunction"}],"answerId":"d","explanation":"Normal TSH with low thyroid hormone suggests pituitary dysfunction, as TSH is not appropriately stimulating the thyroid.","kind":"trap","origin":"ai"},{"id":"hen1-endocrine-feedback-loops~ai-5","moduleId":"hen1-endocrine-feedback-loops","stem":"How does the RAAS system regulate blood volume?","options":[{"id":"a","text":"By increasing insulin secretion"},{"id":"b","text":"By promoting sodium excretion"},{"id":"c","text":"By stimulating aldosterone release"},{"id":"d","text":"By decreasing blood pressure"}],"answerId":"c","explanation":"The RAAS system regulates blood volume primarily by stimulating aldosterone release, which promotes sodium and water retention.","kind":"mechanism","origin":"ai"},{"id":"hen1-endocrine-feedback-loops~ai-6","moduleId":"hen1-endocrine-feedback-loops","stem":"How does insulin feedback relate to glucagon secretion in glucose homeostasis?","options":[{"id":"a","text":"Insulin decreases glucagon secretion"},{"id":"b","text":"Glucagon decreases insulin secretion"},{"id":"c","text":"Both hormones have no effect on each other"},{"id":"d","text":"Insulin increases glucagon secretion"}],"answerId":"a","explanation":"Insulin inhibits glucagon secretion, which is part of the negative feedback loop that regulates blood glucose levels.","kind":"integration","linkedModuleIds":["hrp1-cycle-feedback-gonadotropins"],"origin":"ai"},{"id":"hen1-endocrine-feedback-loops~ai-7","moduleId":"hen1-endocrine-feedback-loops","stem":"What is the relationship between hypothalamic hormones and anterior pituitary function?","options":[{"id":"a","text":"Hypothalamic hormones directly stimulate target organs"},{"id":"b","text":"Anterior pituitary hormones feedback to inhibit hypothalamic hormones"},{"id":"c","text":"Hypothalamic hormones regulate anterior pituitary hormone secretion"},{"id":"d","text":"Anterior pituitary hormones have no feedback effect"}],"answerId":"c","explanation":"Hypothalamic hormones regulate the secretion of anterior pituitary hormones, forming an essential part of endocrine feedback loops.","kind":"integration","linkedModuleIds":["homeostasis-feedback-control"],"origin":"ai"}],"hen1-pituitary-anatomy-development":[{"id":"hen1-pituitary-anatomy-development~ai-0","moduleId":"hen1-pituitary-anatomy-development","stem":"Which structure connects the pituitary gland to the hypothalamus?","options":[{"id":"a","text":"Optic chiasm"},{"id":"b","text":"Infundibulum"},{"id":"c","text":"Sella turcica"},{"id":"d","text":"Cavernous sinus"}],"answerId":"b","explanation":"The infundibulum is the stalk that connects the pituitary gland to the hypothalamus.","kind":"recall","origin":"ai"},{"id":"hen1-pituitary-anatomy-development~ai-1","moduleId":"hen1-pituitary-anatomy-development","stem":"What embryological origin does the adenohypophysis derive from?","options":[{"id":"a","text":"Neural ectoderm"},{"id":"b","text":"Oral ectoderm"},{"id":"c","text":"Mesoderm"},{"id":"d","text":"Endoderm"}],"answerId":"b","explanation":"The adenohypophysis develops from oral ectoderm of Rathke pouch.","kind":"recall","origin":"ai"},{"id":"hen1-pituitary-anatomy-development~ai-2","moduleId":"hen1-pituitary-anatomy-development","stem":"A patient presents with bitemporal hemianopia. What is the most likely cause?","options":[{"id":"a","text":"Pituitary adenoma"},{"id":"b","text":"Craniopharyngioma"},{"id":"c","text":"Optic neuritis"},{"id":"d","text":"Meningioma"}],"answerId":"a","explanation":"Bitemporal hemianopia is commonly caused by a sellar mass, such as a pituitary adenoma, compressing the optic chiasm.","kind":"clinical","origin":"ai"},{"id":"hen1-pituitary-anatomy-development~ai-3","moduleId":"hen1-pituitary-anatomy-development","stem":"Which of the following structures is derived from neural ectoderm?","options":[{"id":"a","text":"Pars distalis"},{"id":"b","text":"Pars intermedia"},{"id":"c","text":"Pars nervosa"},{"id":"d","text":"Infundibulum"}],"answerId":"c","explanation":"The neurohypophysis, including the pars nervosa, derives from neural ectoderm.","kind":"recall","origin":"ai"},{"id":"hen1-pituitary-anatomy-development~ai-4","moduleId":"hen1-pituitary-anatomy-development","stem":"What is the mechanism behind the development of the pituitary gland?","options":[{"id":"a","text":"Fusion of two mesodermal structures"},{"id":"b","text":"Meeting of two ectodermal primordia"},{"id":"c","text":"Migration of neural crest cells"},{"id":"d","text":"Induction by the notochord"}],"answerId":"b","explanation":"The pituitary gland forms from the meeting of two ectodermal primordia: the oral ectoderm and neural ectoderm.","kind":"mechanism","origin":"ai"},{"id":"hen1-pituitary-anatomy-development~ai-5","moduleId":"hen1-pituitary-anatomy-development","stem":"A child presents with a suprasellar mass and calcifications. What is the most likely diagnosis?","options":[{"id":"a","text":"Pituitary adenoma"},{"id":"b","text":"Craniopharyngioma"},{"id":"c","text":"Meningioma"},{"id":"d","text":"Astrocytoma"}],"answerId":"b","explanation":"Craniopharyngioma is a common childhood tumor that can present with calcifications and a suprasellar mass.","kind":"clinical","origin":"ai"},{"id":"hen1-pituitary-anatomy-development~ai-6","moduleId":"hen1-pituitary-anatomy-development","stem":"How does the development of the adenohypophysis differ from the neurohypophysis?","options":[{"id":"a","text":"Both develop from the same neural ectoderm"},{"id":"b","text":"Adenohypophysis is oral ectoderm; neurohypophysis is neural ectoderm"},{"id":"c","text":"Both are derived from mesoderm"},{"id":"d","text":"Neurohypophysis develops from Rathke pouch"}],"answerId":"b","explanation":"The adenohypophysis and neurohypophysis have distinct embryological origins, which explains their different functions.","kind":"trap","origin":"ai"},{"id":"hen1-pituitary-anatomy-development~ai-7","moduleId":"hen1-pituitary-anatomy-development","stem":"How does the pituitary gland's function relate to the hypothalamus?","options":[{"id":"a","text":"It produces all hormones independently"},{"id":"b","text":"It regulates hormone release based on hypothalamic signals"},{"id":"c","text":"It has no functional relationship"},{"id":"d","text":"It stores hormones produced by the hypothalamus"}],"answerId":"b","explanation":"The pituitary gland regulates hormone release based on signals received from the hypothalamus.","kind":"integration","linkedModuleIds":["hen1-hypothalamus-anatomy-nuclei"],"origin":"ai"},{"id":"hen1-pituitary-anatomy-development~ai-8","moduleId":"hen1-pituitary-anatomy-development","stem":"What is the relationship between craniopharyngioma and the development of the pituitary gland?","options":[{"id":"a","text":"Both arise from the same embryonic layer"},{"id":"b","text":"Craniopharyngioma can arise from Rathke pouch remnants"},{"id":"c","text":"They are unrelated tumors"},{"id":"d","text":"Both are derived from neural ectoderm"}],"answerId":"b","explanation":"Craniopharyngiomas are thought to arise from remnants of Rathke pouch, which is involved in pituitary development.","kind":"integration","linkedModuleIds":["craniopharyngioma"],"origin":"ai"}],"hen1-calcium-phosphate-pools":[{"id":"hen1-calcium-phosphate-pools~ai-0","moduleId":"hen1-calcium-phosphate-pools","stem":"What form of calcium is primarily responsible for physiological activity in the body?","options":[{"id":"a","text":"Total calcium"},{"id":"b","text":"Ionized calcium"},{"id":"c","text":"Calcium bound to albumin"},{"id":"d","text":"Calcium complexed with anions"}],"answerId":"b","explanation":"Ionized calcium (Ca²⁺) is the only form that is biologically active and directly sensed by the body.","kind":"recall","origin":"ai"},{"id":"hen1-calcium-phosphate-pools~ai-1","moduleId":"hen1-calcium-phosphate-pools","stem":"Which condition can cause hypocalcemia due to increased albumin binding?","options":[{"id":"a","text":"Acidosis"},{"id":"b","text":"Respiratory alkalosis"},{"id":"c","text":"Hypercapnia"},{"id":"d","text":"Hypoxia"}],"answerId":"b","explanation":"Respiratory alkalosis increases albumin binding, which lowers the levels of ionized calcium, leading to hypocalcemia.","kind":"mechanism","origin":"ai"},{"id":"hen1-calcium-phosphate-pools~ai-2","moduleId":"hen1-calcium-phosphate-pools","stem":"A patient presents with carpopedal spasm after hyperventilation. What is the underlying mechanism?","options":[{"id":"a","text":"Increased ionized calcium"},{"id":"b","text":"Decreased ionized calcium due to respiratory alkalosis"},{"id":"c","text":"Increased total calcium"},{"id":"d","text":"Decreased total calcium"}],"answerId":"b","explanation":"Hyperventilation causes respiratory alkalosis, which increases albumin binding and decreases ionized calcium, leading to neuromuscular excitability.","kind":"clinical","origin":"ai"},{"id":"hen1-calcium-phosphate-pools~ai-3","moduleId":"hen1-calcium-phosphate-pools","stem":"What is a common finding in hypercalcemia?","options":[{"id":"a","text":"Prolonged QT interval"},{"id":"b","text":"Shortened QT interval"},{"id":"c","text":"Increased neuromuscular excitability"},{"id":"d","text":"Tetany"}],"answerId":"b","explanation":"Hypercalcemia shortens the QT interval due to elevated extracellular calcium affecting cardiac action potentials.","kind":"recall","origin":"ai"},{"id":"hen1-calcium-phosphate-pools~ai-4","moduleId":"hen1-calcium-phosphate-pools","stem":"Which statement about total calcium and ionized calcium is correct?","options":[{"id":"a","text":"Total calcium is always active"},{"id":"b","text":"Ionized calcium can change independently of total calcium"},{"id":"c","text":"Total calcium equals ionized calcium"},{"id":"d","text":"Ionized calcium is not affected by pH"}],"answerId":"b","explanation":"Ionized calcium is the active form and can vary independently from total calcium due to changes in albumin or pH.","kind":"trap","origin":"ai"},{"id":"hen1-calcium-phosphate-pools~ai-5","moduleId":"hen1-calcium-phosphate-pools","stem":"How does parathyroid hormone (PTH) affect calcium levels in the body?","options":[{"id":"a","text":"Increases renal calcium excretion"},{"id":"b","text":"Increases intestinal calcium absorption"},{"id":"c","text":"Decreases bone resorption"},{"id":"d","text":"Decreases serum calcium levels"}],"answerId":"b","explanation":"PTH increases intestinal calcium absorption, thereby raising serum calcium levels.","kind":"integration","linkedModuleIds":["hen1-pth-regulation-actions"],"origin":"ai"},{"id":"hen1-calcium-phosphate-pools~ai-6","moduleId":"hen1-calcium-phosphate-pools","stem":"What role does calcitonin play in calcium homeostasis?","options":[{"id":"a","text":"Increases bone resorption"},{"id":"b","text":"Inhibits renal calcium excretion"},{"id":"c","text":"Decreases serum calcium levels"},{"id":"d","text":"Increases intestinal calcium absorption"}],"answerId":"c","explanation":"Calcitonin decreases serum calcium levels by inhibiting osteoclast activity and promoting bone formation.","kind":"integration","linkedModuleIds":["hen1-calcitonin-mineral-integration"],"origin":"ai"}],"hen1-parathyroid-anatomy-development-histology":[{"id":"hen1-parathyroid-anatomy-development-histology~ai-0","moduleId":"hen1-parathyroid-anatomy-development-histology","stem":"From which embryonic structure do the superior parathyroid glands derive?","options":[{"id":"a","text":"Dorsal third pouch"},{"id":"b","text":"Dorsal fourth pouch"},{"id":"c","text":"Ventral third pouch"},{"id":"d","text":"Ventral fourth pouch"}],"answerId":"b","explanation":"The superior parathyroid glands originate from the dorsal fourth pouch.","kind":"recall","origin":"ai"},{"id":"hen1-parathyroid-anatomy-development-histology~ai-1","moduleId":"hen1-parathyroid-anatomy-development-histology","stem":"What is the primary functional cell type in the parathyroid glands?","options":[{"id":"a","text":"Oxyphil cells"},{"id":"b","text":"Chief cells"},{"id":"c","text":"Follicular cells"},{"id":"d","text":"C cells"}],"answerId":"b","explanation":"Chief cells are the dominant functional cells in the parathyroid glands, responsible for secreting parathyroid hormone (PTH).","kind":"recall","origin":"ai"},{"id":"hen1-parathyroid-anatomy-development-histology~ai-2","moduleId":"hen1-parathyroid-anatomy-development-histology","stem":"What histological feature distinguishes oxyphil cells in the parathyroid glands?","options":[{"id":"a","text":"High mitotic activity"},{"id":"b","text":"Increased lipid content"},{"id":"c","text":"Rich in mitochondria"},{"id":"d","text":"Presence of colloid"}],"answerId":"c","explanation":"Oxyphil cells are characterized by their high mitochondrial content, which increases with age.","kind":"recall","origin":"ai"},{"id":"hen1-parathyroid-anatomy-development-histology~ai-3","moduleId":"hen1-parathyroid-anatomy-development-histology","stem":"A patient presents with an ectopic mediastinal parathyroid adenoma. What is the likely reason for its location?","options":[{"id":"a","text":"Superior gland migration"},{"id":"b","text":"Inferior gland thymic descent"},{"id":"c","text":"Thyroid gland enlargement"},{"id":"d","text":"Developmental anomaly of the thyroid"}],"answerId":"b","explanation":"Ectopic mediastinal parathyroid adenomas occur when inferior glands follow thymic descent beyond their usual position.","kind":"clinical","origin":"ai"},{"id":"hen1-parathyroid-anatomy-development-histology~ai-4","moduleId":"hen1-parathyroid-anatomy-development-histology","stem":"Which of the following statements about parathyroid gland anatomy is true?","options":[{"id":"a","text":"Superior glands are more variable in position than inferior glands"},{"id":"b","text":"Inferior glands descend with the thymus"},{"id":"c","text":"Oxyphil cells are the primary secretory cells"},{"id":"d","text":"Adipose tissue is absent in adult parathyroid glands"}],"answerId":"b","explanation":"Inferior parathyroid glands descend with the thymus, leading to variability in their position.","kind":"trap","origin":"ai"},{"id":"hen1-parathyroid-anatomy-development-histology~ai-5","moduleId":"hen1-parathyroid-anatomy-development-histology","stem":"How does the embryonic origin of parathyroid glands relate to their clinical presentation?","options":[{"id":"a","text":"Pouch number correlates with hormone secretion"},{"id":"b","text":"Migration distance affects gland position"},{"id":"c","text":"Developmental anomalies are linked to pouch origin"},{"id":"d","text":"Histology is determined by embryonic origin"}],"answerId":"b","explanation":"The distance of migration from their pouch origin affects the final position of the parathyroid glands, which can lead to ectopic locations.","kind":"integration","linkedModuleIds":["hen1-thyroid-development-anomalies"],"origin":"ai"},{"id":"hen1-parathyroid-anatomy-development-histology~ai-6","moduleId":"hen1-parathyroid-anatomy-development-histology","stem":"Which embryonic structure is linked to both thyroid and parathyroid gland development?","options":[{"id":"a","text":"Dorsal third pouch"},{"id":"b","text":"Dorsal fourth pouch"},{"id":"c","text":"Thymus"},{"id":"d","text":"Branchial arches"}],"answerId":"a","explanation":"Both the thyroid and inferior parathyroid glands derive from the third pouch, linking their developmental origins.","kind":"integration","linkedModuleIds":["hen1-thyroid-development-anomalies"],"origin":"ai"}],"hen1-thyroid-gross-anatomy":[{"id":"hen1-thyroid-gross-anatomy~ai-0","moduleId":"hen1-thyroid-gross-anatomy","stem":"What is the typical anatomical location of the thyroid isthmus?","options":[{"id":"a","text":"Over the first tracheal ring"},{"id":"b","text":"Over the second to fourth tracheal rings"},{"id":"c","text":"Over the fifth to seventh tracheal rings"},{"id":"d","text":"Over the cricoid cartilage"}],"answerId":"b","explanation":"The thyroid isthmus is usually located over the second to fourth tracheal rings.","kind":"recall","origin":"ai"},{"id":"hen1-thyroid-gross-anatomy~ai-1","moduleId":"hen1-thyroid-gross-anatomy","stem":"Which artery typically supplies the inferior thyroid gland?","options":[{"id":"a","text":"External carotid artery"},{"id":"b","text":"Thyrocervical trunk"},{"id":"c","text":"Internal carotid artery"},{"id":"d","text":"Subclavian artery"}],"answerId":"b","explanation":"The inferior thyroid artery usually arises from the thyrocervical trunk.","kind":"recall","origin":"ai"},{"id":"hen1-thyroid-gross-anatomy~ai-2","moduleId":"hen1-thyroid-gross-anatomy","stem":"What is the risk associated with injury to the recurrent laryngeal nerve during thyroid surgery?","options":[{"id":"a","text":"Loss of sensation in the throat"},{"id":"b","text":"Hoarseness due to impaired vocal-fold movement"},{"id":"c","text":"Difficulty swallowing"},{"id":"d","text":"Loss of taste in the anterior two-thirds of the tongue"}],"answerId":"b","explanation":"Injury to the recurrent laryngeal nerve can lead to hoarseness due to impaired vocal-fold movement.","kind":"recall","origin":"ai"},{"id":"hen1-thyroid-gross-anatomy~ai-3","moduleId":"hen1-thyroid-gross-anatomy","stem":"Which nerve is at risk when the superior pole of the thyroid is manipulated?","options":[{"id":"a","text":"Recurrent laryngeal nerve"},{"id":"b","text":"External branch of the superior laryngeal nerve"},{"id":"c","text":"Vagus nerve"},{"id":"d","text":"Hypoglossal nerve"}],"answerId":"b","explanation":"The external branch of the superior laryngeal nerve is closely related to the superior-pole vessels.","kind":"trap","origin":"ai"},{"id":"hen1-thyroid-gross-anatomy~ai-4","moduleId":"hen1-thyroid-gross-anatomy","stem":"What anatomical structure is typically found near the inferior thyroid artery?","options":[{"id":"a","text":"Superior laryngeal nerve"},{"id":"b","text":"Recurrent laryngeal nerve"},{"id":"c","text":"Thyroid ima artery"},{"id":"d","text":"Internal jugular vein"}],"answerId":"b","explanation":"The recurrent laryngeal nerve runs near the inferior thyroid artery and the posterior aspect of the gland.","kind":"mechanism","origin":"ai"},{"id":"hen1-thyroid-gross-anatomy~ai-5","moduleId":"hen1-thyroid-gross-anatomy","stem":"How does the anatomy of the thyroid relate to the anterior triangle of the neck?","options":[{"id":"a","text":"The thyroid is located posterior to the carotid arteries"},{"id":"b","text":"The thyroid is located within the carotid sheath"},{"id":"c","text":"The thyroid is located anterior to the trachea"},{"id":"d","text":"The thyroid is a part of the carotid system"}],"answerId":"c","explanation":"The thyroid gland is located anterior to the trachea, which is situated within the anterior triangle of the neck.","kind":"integration","linkedModuleIds":["anterior-triangle-carotid"],"origin":"ai"},{"id":"hen1-thyroid-gross-anatomy~ai-6","moduleId":"hen1-thyroid-gross-anatomy","stem":"Which developmental anomaly might affect the position of the thyroid gland?","options":[{"id":"a","text":"Thyroglossal duct cyst"},{"id":"b","text":"Ectopic thyroid tissue"},{"id":"c","text":"Parathyroid adenoma"},{"id":"d","text":"Branchial cleft cyst"}],"answerId":"b","explanation":"Ectopic thyroid tissue can lead to abnormal positioning of the thyroid gland.","kind":"integration","linkedModuleIds":["hen1-thyroid-development-anomalies"],"origin":"ai"}],"hen1-hpt-axis-thyroid-patterns":[{"id":"hen1-hpt-axis-thyroid-patterns~ai-0","moduleId":"hen1-hpt-axis-thyroid-patterns","stem":"What is the primary action of TSH on thyroid follicular cells?","options":[{"id":"a","text":"Stimulates free T4 secretion"},{"id":"b","text":"Inhibits thyroid hormone synthesis"},{"id":"c","text":"Activates a Gs/cAMP receptor"},{"id":"d","text":"Promotes thyroid follicle destruction"}],"answerId":"c","explanation":"TSH activates a Gs/cAMP receptor on follicular cells, which supports synthesis and secretion of thyroid hormones.","kind":"recall","origin":"ai"},{"id":"hen1-hpt-axis-thyroid-patterns~ai-1","moduleId":"hen1-hpt-axis-thyroid-patterns","stem":"In primary hypothyroidism, what would you expect to find in laboratory results?","options":[{"id":"a","text":"Low free T4 and high TSH"},{"id":"b","text":"High free T4 and low TSH"},{"id":"c","text":"Normal free T4 and high TSH"},{"id":"d","text":"High free T4 and normal TSH"}],"answerId":"a","explanation":"Primary hypothyroidism is characterized by low free T4 levels with elevated TSH due to lack of negative feedback.","kind":"recall","origin":"ai"},{"id":"hen1-hpt-axis-thyroid-patterns~ai-2","moduleId":"hen1-hpt-axis-thyroid-patterns","stem":"Which condition is characterized by diffuse goiter and eye findings?","options":[{"id":"a","text":"Hashimoto's thyroiditis"},{"id":"b","text":"Graves' disease"},{"id":"c","text":"Subacute thyroiditis"},{"id":"d","text":"Thyroid cancer"}],"answerId":"b","explanation":"Graves' disease is associated with diffuse goiter and ocular symptoms due to TSH-receptor antibodies.","kind":"recall","origin":"ai"},{"id":"hen1-hpt-axis-thyroid-patterns~ai-3","moduleId":"hen1-hpt-axis-thyroid-patterns","stem":"What is the mechanism behind the suppressed TSH in primary hyperthyroidism?","options":[{"id":"a","text":"Increased TRH secretion"},{"id":"b","text":"Negative feedback from high T3/T4"},{"id":"c","text":"Inhibition of TSH receptors"},{"id":"d","text":"Destruction of pituitary tissue"}],"answerId":"b","explanation":"High levels of T3 and T4 provide negative feedback to the pituitary, suppressing TSH secretion.","kind":"mechanism","origin":"ai"},{"id":"hen1-hpt-axis-thyroid-patterns~ai-4","moduleId":"hen1-hpt-axis-thyroid-patterns","stem":"In the context of central hypothyroidism, why might TSH levels be normal despite low free T4?","options":[{"id":"a","text":"Inadequate TRH production"},{"id":"b","text":"Increased TSH receptor sensitivity"},{"id":"c","text":"Pituitary failure to respond to low T4"},{"id":"d","text":"Thyroid hormone resistance"}],"answerId":"c","explanation":"In central hypothyroidism, the pituitary may not adequately respond to low free T4, resulting in normal TSH levels.","kind":"trap","origin":"ai"},{"id":"hen1-hpt-axis-thyroid-patterns~ai-5","moduleId":"hen1-hpt-axis-thyroid-patterns","stem":"How does thyroid hormone influence metabolism?","options":[{"id":"a","text":"Increases glucose uptake"},{"id":"b","text":"Decreases basal metabolic rate"},{"id":"c","text":"Enhances protein synthesis"},{"id":"d","text":"Inhibits lipolysis"}],"answerId":"c","explanation":"Thyroid hormone enhances protein synthesis and overall metabolic activity.","kind":"integration","linkedModuleIds":["hen1-thyroid-physiologic-actions"],"origin":"ai"},{"id":"hen1-hpt-axis-thyroid-patterns~ai-6","moduleId":"hen1-hpt-axis-thyroid-patterns","stem":"What is the primary role of TSH in thyroid hormone synthesis?","options":[{"id":"a","text":"Stimulates iodide uptake"},{"id":"b","text":"Inhibits thyroglobulin synthesis"},{"id":"c","text":"Promotes hormone storage"},{"id":"d","text":"Facilitates hormone release"}],"answerId":"a","explanation":"TSH stimulates iodide uptake, which is essential for the synthesis of thyroid hormones.","kind":"integration","linkedModuleIds":["hen1-thyroid-hormone-synthesis"],"origin":"ai"}],"hen1-adh-water-balance":[{"id":"hen1-adh-water-balance~ai-0","moduleId":"hen1-adh-water-balance","stem":"What triggers the release of ADH (vasopressin)?","options":[{"id":"a","text":"Decreased plasma osmolality"},{"id":"b","text":"Increased plasma osmolality"},{"id":"c","text":"Increased blood volume"},{"id":"d","text":"Decreased blood pressure"}],"answerId":"b","explanation":"ADH release is primarily stimulated by increased plasma osmolality, indicating dehydration.","kind":"recall","origin":"ai"},{"id":"hen1-adh-water-balance~ai-1","moduleId":"hen1-adh-water-balance","stem":"Which mechanism describes how ADH concentrates urine?","options":[{"id":"a","text":"Inhibition of aquaporin-2"},{"id":"b","text":"Activation of renal V2 receptors"},{"id":"c","text":"Increased renal blood flow"},{"id":"d","text":"Decreased sodium reabsorption"}],"answerId":"b","explanation":"ADH activates V2 receptors, leading to the insertion of aquaporin-2 channels in the collecting duct, allowing water reabsorption.","kind":"mechanism","origin":"ai"},{"id":"hen1-adh-water-balance~ai-2","moduleId":"hen1-adh-water-balance","stem":"A patient presents with large-volume dilute urine and hypernatremia. What is the most likely diagnosis?","options":[{"id":"a","text":"Central diabetes insipidus"},{"id":"b","text":"Nephrogenic diabetes insipidus"},{"id":"c","text":"Syndrome of inappropriate ADH secretion"},{"id":"d","text":"Diabetes mellitus"}],"answerId":"a","explanation":"The symptoms are indicative of central diabetes insipidus, characterized by a deficiency of ADH.","kind":"clinical","origin":"ai"},{"id":"hen1-adh-water-balance~ai-3","moduleId":"hen1-adh-water-balance","stem":"Which of the following findings would support a diagnosis of nephrogenic diabetes insipidus?","options":[{"id":"a","text":"Urine concentrates after desmopressin administration"},{"id":"b","text":"Urine remains dilute after desmopressin administration"},{"id":"c","text":"Low plasma osmolality"},{"id":"d","text":"High urine osmolality"}],"answerId":"b","explanation":"Nephrogenic DI is characterized by an inability of the kidneys to respond to ADH, thus urine remains dilute despite desmopressin.","kind":"clinical","origin":"ai"},{"id":"hen1-adh-water-balance~ai-4","moduleId":"hen1-adh-water-balance","stem":"Which statement correctly differentiates central from nephrogenic diabetes insipidus?","options":[{"id":"a","text":"Both respond to desmopressin"},{"id":"b","text":"Only central DI responds to desmopressin"},{"id":"c","text":"Both have high urine osmolality"},{"id":"d","text":"Nephrogenic DI has excess ADH"}],"answerId":"b","explanation":"Central DI results from ADH deficiency and responds to desmopressin, while nephrogenic DI does not respond due to receptor resistance.","kind":"trap","origin":"ai"},{"id":"hen1-adh-water-balance~ai-5","moduleId":"hen1-adh-water-balance","stem":"How does chronic kidney disease (CKD) relate to the regulation of ADH and water balance?","options":[{"id":"a","text":"Increased ADH secretion leads to hypervolemia"},{"id":"b","text":"Decreased renal response to ADH leads to polyuria"},{"id":"c","text":"Increased aquaporin-2 expression"},{"id":"d","text":"Decreased plasma osmolality leads to ADH suppression"}],"answerId":"b","explanation":"In CKD, the kidneys may become resistant to ADH, leading to polyuria despite high ADH levels.","kind":"integration","linkedModuleIds":["secondary-hyperparathyroidism-ckd"],"origin":"ai"},{"id":"hen1-adh-water-balance~ai-6","moduleId":"hen1-adh-water-balance","stem":"What is the relationship between ADH and the anterior pituitary hormones?","options":[{"id":"a","text":"ADH is produced in the anterior pituitary"},{"id":"b","text":"ADH release is inhibited by ACTH"},{"id":"c","text":"ADH secretion is regulated by hypothalamic hormones"},{"id":"d","text":"ADH stimulates growth hormone release"}],"answerId":"c","explanation":"ADH is synthesized in the hypothalamus and released from the posterior pituitary, regulated by hypothalamic signals.","kind":"integration","linkedModuleIds":["hen1-anterior-pituitary-axes"],"origin":"ai"}],"hen1-pth-regulation-actions":[{"id":"hen1-pth-regulation-actions~ai-0","moduleId":"hen1-pth-regulation-actions","stem":"What is the primary effect of parathyroid hormone (PTH) on renal phosphate handling?","options":[{"id":"a","text":"Increases phosphate reabsorption"},{"id":"b","text":"Decreases phosphate reabsorption"},{"id":"c","text":"No effect on phosphate"},{"id":"d","text":"Increases phosphate excretion"}],"answerId":"b","explanation":"PTH decreases proximal phosphate reabsorption, leading to increased phosphate excretion.","kind":"recall","origin":"ai"},{"id":"hen1-pth-regulation-actions~ai-1","moduleId":"hen1-pth-regulation-actions","stem":"Which of the following mechanisms describes how low ionized calcium affects PTH secretion?","options":[{"id":"a","text":"Increases CaSR signaling"},{"id":"b","text":"Decreases CaSR signaling"},{"id":"c","text":"Stimulates calcitonin release"},{"id":"d","text":"Inhibits renal 1α-hydroxylase"}],"answerId":"b","explanation":"Low ionized calcium reduces CaSR signaling, which rapidly increases PTH secretion.","kind":"mechanism","origin":"ai"},{"id":"hen1-pth-regulation-actions~ai-2","moduleId":"hen1-pth-regulation-actions","stem":"A patient presents with hypercalcemia and hypophosphatemia. Which hormone is most likely responsible for these findings?","options":[{"id":"a","text":"Calcitonin"},{"id":"b","text":"Parathyroid hormone"},{"id":"c","text":"Vitamin D"},{"id":"d","text":"Growth hormone"}],"answerId":"b","explanation":"PTH raises calcium levels while driving renal phosphate loss, resulting in hypercalcemia and hypophosphatemia.","kind":"clinical","origin":"ai"},{"id":"hen1-pth-regulation-actions~ai-3","moduleId":"hen1-pth-regulation-actions","stem":"What is the indirect effect of PTH on osteoclast activity?","options":[{"id":"a","text":"Direct activation of osteoclasts"},{"id":"b","text":"Inhibition of osteoblasts"},{"id":"c","text":"Increased RANKL and decreased OPG"},{"id":"d","text":"Decreased calcium release from bones"}],"answerId":"c","explanation":"PTH acts on osteoblast-lineage cells to increase RANKL and reduce OPG, promoting osteoclast formation.","kind":"mechanism","origin":"ai"},{"id":"hen1-pth-regulation-actions~ai-4","moduleId":"hen1-pth-regulation-actions","stem":"In chronic hyperparathyroidism, which finding is most likely to be observed on bone imaging?","options":[{"id":"a","text":"Increased bone density"},{"id":"b","text":"Subperiosteal bone resorption"},{"id":"c","text":"Normal bone structure"},{"id":"d","text":"Increased trabecular thickness"}],"answerId":"b","explanation":"Chronic PTH excess leads to subperiosteal bone resorption due to RANKL-mediated osteoclast activation.","kind":"recall","origin":"ai"},{"id":"hen1-pth-regulation-actions~ai-5","moduleId":"hen1-pth-regulation-actions","stem":"How does PTH indirectly affect calcium levels in the body?","options":[{"id":"a","text":"By directly stimulating osteoclasts"},{"id":"b","text":"By increasing renal calcium reabsorption"},{"id":"c","text":"By decreasing intestinal calcium absorption"},{"id":"d","text":"By inhibiting renal 1α-hydroxylase"}],"answerId":"b","explanation":"PTH increases distal renal calcium reabsorption, thereby raising plasma calcium levels.","kind":"trap","origin":"ai"},{"id":"hen1-pth-regulation-actions~ai-6","moduleId":"hen1-pth-regulation-actions","stem":"How does PTH interact with vitamin D in calcium homeostasis?","options":[{"id":"a","text":"PTH inhibits vitamin D activation"},{"id":"b","text":"PTH promotes vitamin D synthesis"},{"id":"c","text":"PTH has no effect on vitamin D"},{"id":"d","text":"PTH decreases intestinal calcium absorption"}],"answerId":"b","explanation":"PTH stimulates renal 1α-hydroxylase, promoting the activation of vitamin D, which increases intestinal absorption of calcium.","kind":"integration","linkedModuleIds":["hen1-vitamin-d-metabolism-actions"],"origin":"ai"},{"id":"hen1-pth-regulation-actions~ai-7","moduleId":"hen1-pth-regulation-actions","stem":"In the context of nutritional ketosis, how does PTH function in calcium regulation?","options":[{"id":"a","text":"Increases calcium absorption"},{"id":"b","text":"Decreases renal calcium excretion"},{"id":"c","text":"Increases bone resorption"},{"id":"d","text":"Inhibits PTH secretion"}],"answerId":"c","explanation":"In nutritional ketosis, PTH increases bone resorption to maintain calcium levels despite potential dietary deficiencies.","kind":"integration","linkedModuleIds":["nutritional-ketosis-vs-ketoacidosis"],"origin":"ai"}],"hen1-thyroid-physiologic-actions":[{"id":"hen1-thyroid-physiologic-actions~ai-0","moduleId":"hen1-thyroid-physiologic-actions","stem":"What is the primary effect of thyroid hormone on basal metabolic rate?","options":[{"id":"a","text":"Decreases it"},{"id":"b","text":"Increases it"},{"id":"c","text":"Has no effect"},{"id":"d","text":"Fluctuates it"}],"answerId":"b","explanation":"Thyroid hormone is known to raise the basal metabolic rate, leading to increased energy expenditure.","kind":"recall","origin":"ai"},{"id":"hen1-thyroid-physiologic-actions~ai-1","moduleId":"hen1-thyroid-physiologic-actions","stem":"Which mechanism explains the increased cardiac output in hyperthyroidism?","options":[{"id":"a","text":"Increased blood volume"},{"id":"b","text":"Increased β-adrenergic receptor expression"},{"id":"c","text":"Decreased peripheral resistance"},{"id":"d","text":"Increased heart size"}],"answerId":"b","explanation":"Thyroid hormone increases β-adrenergic receptor expression, enhancing cardiac responsiveness.","kind":"mechanism","origin":"ai"},{"id":"hen1-thyroid-physiologic-actions~ai-2","moduleId":"hen1-thyroid-physiologic-actions","stem":"A patient presents with cold intolerance, bradycardia, and constipation. What is the likely thyroid hormone status?","options":[{"id":"a","text":"Hyperthyroid"},{"id":"b","text":"Hypothyroid"},{"id":"c","text":"Euthyroid"},{"id":"d","text":"Thyroid storm"}],"answerId":"b","explanation":"These symptoms are characteristic of hypothyroidism, indicating low thyroid hormone levels.","kind":"clinical","origin":"ai"},{"id":"hen1-thyroid-physiologic-actions~ai-3","moduleId":"hen1-thyroid-physiologic-actions","stem":"In a patient with hyperthyroidism, which of the following findings would you expect?","options":[{"id":"a","text":"Cold skin"},{"id":"b","text":"Bradycardia"},{"id":"c","text":"Tremor"},{"id":"d","text":"Constipation"}],"answerId":"c","explanation":"Hyperthyroidism typically presents with warm skin, tremors, tachycardia, and increased metabolic activity.","kind":"recall","origin":"ai"},{"id":"hen1-thyroid-physiologic-actions~ai-4","moduleId":"hen1-thyroid-physiologic-actions","stem":"What is a common misconception about the action of thyroid hormone on the heart?","options":[{"id":"a","text":"It directly acts as a catecholamine"},{"id":"b","text":"It increases heart rate"},{"id":"c","text":"It enhances contractility"},{"id":"d","text":"It upregulates β-adrenergic receptors"}],"answerId":"a","explanation":"Thyroid hormone does not act as a catecholamine; it increases tissue responsiveness by upregulating β-adrenergic receptors.","kind":"trap","origin":"ai"},{"id":"hen1-thyroid-physiologic-actions~ai-5","moduleId":"hen1-thyroid-physiologic-actions","stem":"How does thyroid hormone deficiency affect cognitive function?","options":[{"id":"a","text":"Improves it"},{"id":"b","text":"Has no effect"},{"id":"c","text":"Slows it"},{"id":"d","text":"Accelerates it"}],"answerId":"c","explanation":"Thyroid hormone deficiency slows cognitive function, which can lead to developmental issues if severe.","kind":"recall","origin":"ai"},{"id":"hen1-thyroid-physiologic-actions~ai-6","moduleId":"hen1-thyroid-physiologic-actions","stem":"How does thyroid hormone synthesis relate to its physiologic actions?","options":[{"id":"a","text":"It is independent of its actions"},{"id":"b","text":"It determines the rate of metabolism"},{"id":"c","text":"It only affects growth"},{"id":"d","text":"It has no impact on CNS development"}],"answerId":"b","explanation":"Thyroid hormone synthesis directly influences its metabolic effects and is crucial for growth and CNS development.","kind":"integration","linkedModuleIds":["hen1-thyroid-hormone-synthesis"],"origin":"ai"},{"id":"hen1-thyroid-physiologic-actions~ai-7","moduleId":"hen1-thyroid-physiologic-actions","stem":"Which thyroid hormone pattern would you expect in a patient with increased heart rate and tremors?","options":[{"id":"a","text":"Hypothyroidism"},{"id":"b","text":"Euthyroidism"},{"id":"c","text":"Hyperthyroidism"},{"id":"d","text":"Thyroiditis"}],"answerId":"c","explanation":"Increased heart rate and tremors are indicative of hyperthyroidism, where thyroid hormone levels are elevated.","kind":"integration","linkedModuleIds":["hen1-hpt-axis-thyroid-patterns"],"origin":"ai"}],"hen1-thyroid-transport-conversion-action":[{"id":"hen1-thyroid-transport-conversion-action~ai-0","moduleId":"hen1-thyroid-transport-conversion-action","stem":"What is the primary protein that binds T4 in circulation?","options":[{"id":"a","text":"Albumin"},{"id":"b","text":"Thyroxine-binding globulin"},{"id":"c","text":"Transferrin"},{"id":"d","text":"Lipoprotein"}],"answerId":"b","explanation":"Thyroxine-binding globulin (TBG) is the main protein that binds T4 in the bloodstream.","kind":"recall","origin":"ai"},{"id":"hen1-thyroid-transport-conversion-action~ai-1","moduleId":"hen1-thyroid-transport-conversion-action","stem":"Which enzyme is responsible for converting T4 to the more active T3?","options":[{"id":"a","text":"5'-deiodinase"},{"id":"b","text":"5-deiodinase"},{"id":"c","text":"Thyroid peroxidase"},{"id":"d","text":"Aromatase"}],"answerId":"a","explanation":"5'-deiodinase converts T4 to T3, the active form of thyroid hormone.","kind":"mechanism","origin":"ai"},{"id":"hen1-thyroid-transport-conversion-action~ai-2","moduleId":"hen1-thyroid-transport-conversion-action","stem":"A pregnant woman presents with high total T4 but normal TSH and free T4 levels. What is the most likely explanation?","options":[{"id":"a","text":"Hyperthyroidism"},{"id":"b","text":"Increased TBG due to estrogen"},{"id":"c","text":"Thyroid cancer"},{"id":"d","text":"Pituitary adenoma"}],"answerId":"b","explanation":"Estrogen increases TBG levels, leading to elevated total T4 without affecting free T4 or TSH.","kind":"clinical","origin":"ai"},{"id":"hen1-thyroid-transport-conversion-action~ai-3","moduleId":"hen1-thyroid-transport-conversion-action","stem":"In severe illness, low T3 levels are often accompanied by increased reverse T3. What is the underlying mechanism?","options":[{"id":"a","text":"Increased TBG"},{"id":"b","text":"Decreased peripheral deiodination"},{"id":"c","text":"Increased conversion of T4 to T3"},{"id":"d","text":"Increased thyroid hormone receptor sensitivity"}],"answerId":"b","explanation":"In severe illness, peripheral deiodination shifts away from active T3, resulting in low T3 and increased reverse T3.","kind":"mechanism","origin":"ai"},{"id":"hen1-thyroid-transport-conversion-action~ai-4","moduleId":"hen1-thyroid-transport-conversion-action","stem":"Which of the following is a common misconception regarding total T4 levels?","options":[{"id":"a","text":"High total T4 indicates hyperthyroidism"},{"id":"b","text":"Total T4 is affected by TBG levels"},{"id":"c","text":"Free T4 is the active form of thyroid hormone"},{"id":"d","text":"T4 has a longer half-life than T3"}],"answerId":"a","explanation":"High total T4 does not always indicate hyperthyroidism; it can be due to increased TBG levels while free T4 remains normal.","kind":"trap","origin":"ai"},{"id":"hen1-thyroid-transport-conversion-action~ai-5","moduleId":"hen1-thyroid-transport-conversion-action","stem":"How does T3 exert its effects at the cellular level?","options":[{"id":"a","text":"By binding to cytoplasmic receptors"},{"id":"b","text":"By altering ion channel activity"},{"id":"c","text":"By binding to nuclear thyroid hormone receptors"},{"id":"d","text":"By inhibiting protein synthesis"}],"answerId":"c","explanation":"T3 binds to nuclear thyroid hormone receptors, which then regulate gene expression.","kind":"mechanism","origin":"ai"},{"id":"hen1-thyroid-transport-conversion-action~ai-6","moduleId":"hen1-thyroid-transport-conversion-action","stem":"Which thyroid hormone action is most directly linked to its receptor signaling mechanisms?","options":[{"id":"a","text":"Increased basal metabolic rate"},{"id":"b","text":"Regulation of calcium levels"},{"id":"c","text":"Stimulation of adrenal cortex"},{"id":"d","text":"Inhibition of insulin secretion"}],"answerId":"a","explanation":"Thyroid hormones increase the basal metabolic rate through their actions on nuclear receptors that regulate metabolism-related genes.","kind":"integration","linkedModuleIds":["hen1-thyroid-physiologic-actions"],"origin":"ai"},{"id":"hen1-thyroid-transport-conversion-action~ai-7","moduleId":"hen1-thyroid-transport-conversion-action","stem":"What is the relationship between thyroid hormone action and receptor signal transduction?","options":[{"id":"a","text":"Thyroid hormones act only through membrane receptors"},{"id":"b","text":"Thyroid hormones do not require receptor binding"},{"id":"c","text":"Thyroid hormones modulate gene expression via nuclear receptors"},{"id":"d","text":"Thyroid hormones primarily affect neurotransmitter release"}],"answerId":"c","explanation":"Thyroid hormones modulate gene expression by binding to nuclear receptors, which is a key aspect of receptor signal transduction.","kind":"integration","linkedModuleIds":["drug-receptor-signal-transduction"],"origin":"ai"}],"hen1-pancreatic-islet-development-histology":[{"id":"hen1-pancreatic-islet-development-histology~ai-0","moduleId":"hen1-pancreatic-islet-development-histology","stem":"Which embryonic structure contributes to the formation of the uncinate process of the pancreas?","options":[{"id":"a","text":"Dorsal bud"},{"id":"b","text":"Ventral bud"},{"id":"c","text":"Both dorsal and ventral buds"},{"id":"d","text":"Neither bud"}],"answerId":"b","explanation":"The ventral bud migrates posteriorly and forms the uncinate process.","kind":"recall","origin":"ai"},{"id":"hen1-pancreatic-islet-development-histology~ai-1","moduleId":"hen1-pancreatic-islet-development-histology","stem":"What is the primary function of beta cells in the pancreatic islets?","options":[{"id":"a","text":"Secretion of glucagon"},{"id":"b","text":"Secretion of insulin"},{"id":"c","text":"Secretion of somatostatin"},{"id":"d","text":"Secretion of pancreatic polypeptide"}],"answerId":"b","explanation":"Beta cells are responsible for the secretion of insulin, which regulates blood glucose levels.","kind":"recall","origin":"ai"},{"id":"hen1-pancreatic-islet-development-histology~ai-2","moduleId":"hen1-pancreatic-islet-development-histology","stem":"Which histological feature distinguishes pancreatic islets from exocrine acini?","options":[{"id":"a","text":"Rich vascularization"},{"id":"b","text":"Presence of ductal cells"},{"id":"c","text":"Cytoplasmic granules"},{"id":"d","text":"Serous acinar cells"}],"answerId":"a","explanation":"Pancreatic islets are pale, richly vascularized structures compared to the darker exocrine acini.","kind":"recall","origin":"ai"},{"id":"hen1-pancreatic-islet-development-histology~ai-3","moduleId":"hen1-pancreatic-islet-development-histology","stem":"What clinical finding is associated with abnormal ventral-bud migration in the pancreas?","options":[{"id":"a","text":"Annular pancreas"},{"id":"b","text":"Pancreatic pseudocyst"},{"id":"c","text":"Pancreatic adenocarcinoma"},{"id":"d","text":"Diabetes mellitus"}],"answerId":"a","explanation":"Abnormal ventral-bud migration leads to the formation of an annular pancreas, encircling the duodenum.","kind":"clinical","origin":"ai"},{"id":"hen1-pancreatic-islet-development-histology~ai-4","moduleId":"hen1-pancreatic-islet-development-histology","stem":"Which statement about pancreatic embryology is correct?","options":[{"id":"a","text":"The dorsal bud forms the uncinate process"},{"id":"b","text":"The ventral bud contributes to the head and body"},{"id":"c","text":"The dorsal bud contributes to the uncinate process"},{"id":"d","text":"The ventral bud forms the entire pancreas"}],"answerId":"b","explanation":"The ventral bud contributes to the uncinate process and inferior head, while the dorsal bud forms the remaining parts.","kind":"trap","origin":"ai"},{"id":"hen1-pancreatic-islet-development-histology~ai-5","moduleId":"hen1-pancreatic-islet-development-histology","stem":"How does the development of the pancreas relate to the development of the foregut?","options":[{"id":"a","text":"Both derive from mesoderm"},{"id":"b","text":"Both develop from the same endodermal layer"},{"id":"c","text":"Both are innervated by the same nerve"},{"id":"d","text":"Both are vascularized by the same artery"}],"answerId":"b","explanation":"The pancreas and foregut structures both arise from the endoderm during embryonic development.","kind":"integration","linkedModuleIds":["foregut-accessory-development"],"origin":"ai"},{"id":"hen1-pancreatic-islet-development-histology~ai-6","moduleId":"hen1-pancreatic-islet-development-histology","stem":"Which hormone secreted by pancreatic islets is involved in glucose homeostasis?","options":[{"id":"a","text":"Insulin"},{"id":"b","text":"Glucagon"},{"id":"c","text":"Somatostatin"},{"id":"d","text":"Pancreatic polypeptide"}],"answerId":"a","explanation":"Insulin is the primary hormone secreted by beta cells that helps regulate glucose levels in the blood.","kind":"recall","origin":"ai"},{"id":"hen1-pancreatic-islet-development-histology~ai-7","moduleId":"hen1-pancreatic-islet-development-histology","stem":"What is the role of fenestrated capillaries in the pancreatic islets?","options":[{"id":"a","text":"Transport exocrine secretions"},{"id":"b","text":"Facilitate nutrient absorption"},{"id":"c","text":"Allow endocrine products to enter circulation"},{"id":"d","text":"Support acinar cell function"}],"answerId":"c","explanation":"Fenestrated capillaries allow the direct entry of endocrine products from the islets into the bloodstream.","kind":"mechanism","origin":"ai"}],"hen1-thyroid-development-anomalies":[{"id":"hen1-thyroid-development-anomalies~ai-0","moduleId":"hen1-thyroid-development-anomalies","stem":"What is the embryological origin of thyroid follicular cells?","options":[{"id":"a","text":"Neural crest cells"},{"id":"b","text":"Mesodermal derivatives"},{"id":"c","text":"Median endodermal diverticulum"},{"id":"d","text":"Ectodermal structures"}],"answerId":"c","explanation":"Thyroid follicular cells originate from the median endodermal diverticulum during development.","kind":"recall","origin":"ai"},{"id":"hen1-thyroid-development-anomalies~ai-1","moduleId":"hen1-thyroid-development-anomalies","stem":"What clinical finding is associated with a thyroglossal duct cyst?","options":[{"id":"a","text":"Mass at the base of the tongue"},{"id":"b","text":"Midline neck mass moving with swallowing"},{"id":"c","text":"Ectopic thyroid tissue in the axilla"},{"id":"d","text":"Absence of cervical thyroid tissue"}],"answerId":"b","explanation":"A thyroglossal duct cyst presents as a midline neck mass that moves with swallowing due to its connection along the descent tract.","kind":"clinical","origin":"ai"},{"id":"hen1-thyroid-development-anomalies~ai-2","moduleId":"hen1-thyroid-development-anomalies","stem":"Which structure is responsible for the development of C cells in the thyroid?","options":[{"id":"a","text":"Thyroglossal duct"},{"id":"b","text":"Ultimobranchial body"},{"id":"c","text":"Median endodermal diverticulum"},{"id":"d","text":"Fourth pharyngeal pouch"}],"answerId":"b","explanation":"C cells derive from neural-crest-associated cells that enter through the ultimobranchial body.","kind":"recall","origin":"ai"},{"id":"hen1-thyroid-development-anomalies~ai-3","moduleId":"hen1-thyroid-development-anomalies","stem":"What is the consequence of failure of thyroid descent during embryogenesis?","options":[{"id":"a","text":"Thyroglossal duct cyst"},{"id":"b","text":"Lingual thyroid"},{"id":"c","text":"Pyramidal lobe"},{"id":"d","text":"Ectopic thyroid tissue"}],"answerId":"b","explanation":"Failure of thyroid descent results in a lingual thyroid, which may be the only functioning thyroid tissue.","kind":"mechanism","origin":"ai"},{"id":"hen1-thyroid-development-anomalies~ai-4","moduleId":"hen1-thyroid-development-anomalies","stem":"Which of the following statements is true regarding thyroid embryology?","options":[{"id":"a","text":"All thyroid cells derive from the median endodermal diverticulum"},{"id":"b","text":"C cells originate from the same lineage as follicular cells"},{"id":"c","text":"Follicular cells are endodermal; C cells enter through the ultimobranchial body"},{"id":"d","text":"Thyroglossal duct cysts are always symptomatic"}],"answerId":"c","explanation":"Follicular cells are endodermal, while C cells have a different developmental lineage, entering through the ultimobranchial body.","kind":"trap","origin":"ai"},{"id":"hen1-thyroid-development-anomalies~ai-5","moduleId":"hen1-thyroid-development-anomalies","stem":"How does a lingual thyroid present clinically?","options":[{"id":"a","text":"Mass in the anterior neck"},{"id":"b","text":"Mass at the base of the tongue with absent cervical thyroid"},{"id":"c","text":"Thyroglossal duct cyst in the midline"},{"id":"d","text":"Pyramidal lobe of the thyroid gland"}],"answerId":"b","explanation":"A lingual thyroid presents as a mass at the base of the tongue, often with absent cervical thyroid tissue.","kind":"clinical","origin":"ai"},{"id":"hen1-thyroid-development-anomalies~ai-6","moduleId":"hen1-thyroid-development-anomalies","stem":"Which embryological structure is involved in the development of both the thyroid and parathyroid glands?","options":[{"id":"a","text":"Fourth pharyngeal pouch"},{"id":"b","text":"Ultimobranchial body"},{"id":"c","text":"Median endodermal diverticulum"},{"id":"d","text":"Thyroglossal duct"}],"answerId":"a","explanation":"The fourth pharyngeal pouch contributes to the development of both the thyroid and parathyroid glands.","kind":"integration","linkedModuleIds":["hen1-parathyroid-anatomy-development-histology"],"origin":"ai"},{"id":"hen1-thyroid-development-anomalies~ai-7","moduleId":"hen1-thyroid-development-anomalies","stem":"Which embryological defect could lead to ectopic thyroid tissue in the neck?","options":[{"id":"a","text":"Failure of the thyroglossal duct to involute"},{"id":"b","text":"Abnormal migration of the median endodermal diverticulum"},{"id":"c","text":"Persistence of the ultimobranchial body"},{"id":"d","text":"Failure of the fourth pharyngeal pouch to develop"}],"answerId":"b","explanation":"Abnormal migration of the median endodermal diverticulum can lead to ectopic thyroid tissue in the neck.","kind":"integration","linkedModuleIds":["hen1-thyroid-gross-anatomy"],"origin":"ai"}],"hen1-thyroid-hormone-synthesis":[{"id":"hen1-thyroid-hormone-synthesis~ai-0","moduleId":"hen1-thyroid-hormone-synthesis","stem":"Which protein is responsible for trapping iodide in the thyroid follicular cells?","options":[{"id":"a","text":"Thyroid peroxidase (TPO)"},{"id":"b","text":"Sodium/Iodide symporter (NIS)"},{"id":"c","text":"Pendrin"},{"id":"d","text":"Thyroglobulin"}],"answerId":"b","explanation":"The Sodium/Iodide symporter (NIS) is responsible for the basolateral trapping of iodide in thyroid follicular cells.","kind":"recall","origin":"ai"},{"id":"hen1-thyroid-hormone-synthesis~ai-1","moduleId":"hen1-thyroid-hormone-synthesis","stem":"What is the primary product of thyroid hormone synthesis?","options":[{"id":"a","text":"Triiodothyronine (T3)"},{"id":"b","text":"Thyroxine (T4)"},{"id":"c","text":"Monoiodotyrosine (MIT)"},{"id":"d","text":"Diiodotyrosine (DIT)"}],"answerId":"b","explanation":"Thyroxine (T4) is the major secreted product of thyroid hormone synthesis.","kind":"recall","origin":"ai"},{"id":"hen1-thyroid-hormone-synthesis~ai-2","moduleId":"hen1-thyroid-hormone-synthesis","stem":"Which of the following statements about thyroid hormone synthesis is true?","options":[{"id":"a","text":"TPO transports iodide across the basolateral membrane"},{"id":"b","text":"NIS traps iodide basolaterally"},{"id":"c","text":"Iodide is coupled with thyroglobulin in the cytoplasm"},{"id":"d","text":"T4 is synthesized from MIT and DIT in the cytoplasm"}],"answerId":"b","explanation":"NIS traps iodide basolaterally; TPO oxidizes, organifies, and couples iodide apically.","kind":"trap","origin":"ai"},{"id":"hen1-thyroid-hormone-synthesis~ai-3","moduleId":"hen1-thyroid-hormone-synthesis","stem":"What is the role of TSH in thyroid hormone synthesis?","options":[{"id":"a","text":"Inhibits iodide uptake"},{"id":"b","text":"Stimulates nearly every step of synthesis"},{"id":"c","text":"Decreases T4 release"},{"id":"d","text":"Inhibits TPO activity"}],"answerId":"b","explanation":"TSH stimulates nearly every step of thyroid hormone synthesis, including iodide uptake and T4 release.","kind":"mechanism","origin":"ai"},{"id":"hen1-thyroid-hormone-synthesis~ai-4","moduleId":"hen1-thyroid-hormone-synthesis","stem":"A patient presents with low uptake of radioiodine after administration of a NIS inhibitor. What is the underlying mechanism?","options":[{"id":"a","text":"Increased TPO activity"},{"id":"b","text":"Follicular cells cannot efficiently trap iodide"},{"id":"c","text":"Increased deiodination of MIT"},{"id":"d","text":"Decreased T4 synthesis"}],"answerId":"b","explanation":"Inhibition of NIS prevents follicular cells from efficiently trapping iodide, leading to low radioiodine uptake.","kind":"clinical","origin":"ai"},{"id":"hen1-thyroid-hormone-synthesis~ai-5","moduleId":"hen1-thyroid-hormone-synthesis","stem":"How does T4 convert to T3 in peripheral tissues?","options":[{"id":"a","text":"Deiodination"},{"id":"b","text":"Iodination"},{"id":"c","text":"Coupling"},{"id":"d","text":"Oxidation"}],"answerId":"a","explanation":"T4 is converted to the active form T3 through deiodination in peripheral tissues.","kind":"mechanism","origin":"ai"},{"id":"hen1-thyroid-hormone-synthesis~ai-6","moduleId":"hen1-thyroid-hormone-synthesis","stem":"How does thyroid hormone synthesis relate to the HPT axis?","options":[{"id":"a","text":"TSH is produced by the thyroid gland"},{"id":"b","text":"Thyroid hormones feedback to inhibit TRH"},{"id":"c","text":"T3 stimulates TSH production"},{"id":"d","text":"NIS is regulated by TRH"}],"answerId":"b","explanation":"Thyroid hormones provide negative feedback to inhibit the release of TRH from the hypothalamus, thus affecting TSH levels.","kind":"integration","linkedModuleIds":["hen1-hpt-axis-thyroid-patterns"],"origin":"ai"},{"id":"hen1-thyroid-hormone-synthesis~ai-7","moduleId":"hen1-thyroid-hormone-synthesis","stem":"Which mechanism links thyroid hormone synthesis to drug absorption?","options":[{"id":"a","text":"NIS affects drug transport"},{"id":"b","text":"T4 enhances drug metabolism"},{"id":"c","text":"T3 alters gastrointestinal motility"},{"id":"d","text":"TSH increases drug absorption"}],"answerId":"c","explanation":"T3 can influence gastrointestinal motility, which may affect the absorption rates of orally administered drugs.","kind":"integration","linkedModuleIds":["drug-absorption-routes"],"origin":"ai"}],"hen1-thyroid-histology":[{"id":"hen1-thyroid-histology~ai-0","moduleId":"hen1-thyroid-histology","stem":"What is the primary component stored in the colloid of thyroid follicles?","options":[{"id":"a","text":"Thyroid hormones T3 and T4"},{"id":"b","text":"Thyroglobulin"},{"id":"c","text":"Calcitonin"},{"id":"d","text":"Iodine"}],"answerId":"b","explanation":"The colloid of thyroid follicles primarily stores thyroglobulin, which is the precursor for thyroid hormones.","kind":"recall","origin":"ai"},{"id":"hen1-thyroid-histology~ai-1","moduleId":"hen1-thyroid-histology","stem":"Which of the following best describes the appearance of follicular cells in an actively stimulated thyroid gland?","options":[{"id":"a","text":"Flattened cells with abundant colloid"},{"id":"b","text":"Cuboidal to columnar cells with scalloped colloid"},{"id":"c","text":"Tall columnar cells with no colloid"},{"id":"d","text":"Simple squamous cells with dense colloid"}],"answerId":"b","explanation":"Active thyroid follicles exhibit cuboidal to columnar follicular cells with scalloped colloid due to active resorption.","kind":"recall","origin":"ai"},{"id":"hen1-thyroid-histology~ai-2","moduleId":"hen1-thyroid-histology","stem":"What is the primary function of parafollicular C cells in the thyroid?","options":[{"id":"a","text":"Secretion of thyroid hormones"},{"id":"b","text":"Secretion of calcitonin"},{"id":"c","text":"Storage of thyroglobulin"},{"id":"d","text":"Regulation of iodine uptake"}],"answerId":"b","explanation":"Parafollicular C cells secrete calcitonin, which helps regulate calcium levels in the blood.","kind":"recall","origin":"ai"},{"id":"hen1-thyroid-histology~ai-3","moduleId":"hen1-thyroid-histology","stem":"Which mechanism explains the polarity of follicular cells in thyroid follicles?","options":[{"id":"a","text":"Facilitated diffusion of iodine"},{"id":"b","text":"Synthesis and retrieval of hormones"},{"id":"c","text":"Endocytosis of colloid"},{"id":"d","text":"Exocytosis of calcitonin"}],"answerId":"b","explanation":"Follicular polarity supports the synthesis of thyroid hormones into colloid and their retrieval during hormone release.","kind":"mechanism","origin":"ai"},{"id":"hen1-thyroid-histology~ai-4","moduleId":"hen1-thyroid-histology","stem":"In a patient with hyperthyroidism, which histological finding is expected in the thyroid gland?","options":[{"id":"a","text":"Tall crowded follicular cells with scalloped colloid"},{"id":"b","text":"Pale parafollicular cells"},{"id":"c","text":"Flattened follicular cells"},{"id":"d","text":"Dense colloid with few follicular cells"}],"answerId":"a","explanation":"In hyperthyroidism, the thyroid gland shows tall crowded follicular cells with scalloped colloid due to active resorption.","kind":"recall","origin":"ai"},{"id":"hen1-thyroid-histology~ai-5","moduleId":"hen1-thyroid-histology","stem":"Which of the following statements about thyroid hormone storage is correct?","options":[{"id":"a","text":"T3 and T4 are stored in intracellular secretory granules"},{"id":"b","text":"Iodinated hormone residues are stored extracellularly within thyroglobulin in colloid"},{"id":"c","text":"Thyroid hormones are synthesized in the nucleus"},{"id":"d","text":"Colloid is primarily composed of calcitonin"}],"answerId":"b","explanation":"Thyroid follicles uniquely maintain a large extracellular hormone reserve, storing iodinated residues in colloid.","kind":"trap","origin":"ai"},{"id":"hen1-thyroid-histology~ai-6","moduleId":"hen1-thyroid-histology","stem":"How does the structure of thyroid follicles relate to their function in hormone synthesis?","options":[{"id":"a","text":"Follicular cells are flat to maximize colloid storage"},{"id":"b","text":"The spherical shape allows for efficient blood supply"},{"id":"c","text":"Polarity supports synthesis into and retrieval from colloid"},{"id":"d","text":"C cells enhance follicular hormone production"}],"answerId":"c","explanation":"The polarity of follicular cells is crucial for the synthesis of thyroid hormones into colloid and their retrieval during secretion.","kind":"integration","linkedModuleIds":["hen1-thyroid-development-anomalies"],"origin":"ai"},{"id":"hen1-thyroid-histology~ai-7","moduleId":"hen1-thyroid-histology","stem":"What is the relationship between thyroid histology and the development of goiter?","options":[{"id":"a","text":"Goiter is caused by excess calcitonin secretion"},{"id":"b","text":"Hyperplasia of follicular cells leads to increased colloid production"},{"id":"c","text":"Follicular cell atrophy results in decreased hormone synthesis"},{"id":"d","text":"C cells proliferate in response to low thyroid hormone levels"}],"answerId":"b","explanation":"Goiter often results from hyperplasia of follicular cells, leading to increased colloid production in response to low thyroid hormone levels.","kind":"integration","linkedModuleIds":["hypothyroidism-goiter"],"origin":"ai"}],"hen1-glucagon-fasting-metabolism":[{"id":"hen1-glucagon-fasting-metabolism~ai-0","moduleId":"hen1-glucagon-fasting-metabolism","stem":"What is the primary effect of glucagon on hepatic metabolism during fasting?","options":[{"id":"a","text":"Increases glycogen synthesis"},{"id":"b","text":"Increases gluconeogenesis"},{"id":"c","text":"Increases glycolysis"},{"id":"d","text":"Increases lipogenesis"}],"answerId":"b","explanation":"Glucagon primarily increases gluconeogenesis, promoting glucose production from non-carbohydrate sources during fasting.","kind":"recall","origin":"ai"},{"id":"hen1-glucagon-fasting-metabolism~ai-1","moduleId":"hen1-glucagon-fasting-metabolism","stem":"Which receptor type mediates glucagon's effects in the liver?","options":[{"id":"a","text":"Gs-coupled receptor"},{"id":"b","text":"Gi-coupled receptor"},{"id":"c","text":"Tyrosine kinase receptor"},{"id":"d","text":"Nuclear receptor"}],"answerId":"a","explanation":"The hepatic glucagon receptor is Gs-coupled, leading to increased cAMP and activation of protein kinase A.","kind":"mechanism","origin":"ai"},{"id":"hen1-glucagon-fasting-metabolism~ai-2","moduleId":"hen1-glucagon-fasting-metabolism","stem":"During prolonged fasting, what metabolic state is characterized by elevated ketone bodies?","options":[{"id":"a","text":"Hypoglycemia"},{"id":"b","text":"Ketosis"},{"id":"c","text":"Hyperglycemia"},{"id":"d","text":"Lactic acidosis"}],"answerId":"b","explanation":"Ketosis occurs during prolonged fasting due to increased fatty acid oxidation and ketogenesis in the liver.","kind":"recall","origin":"ai"},{"id":"hen1-glucagon-fasting-metabolism~ai-3","moduleId":"hen1-glucagon-fasting-metabolism","stem":"What is the primary reason glucagon does not stimulate glycogenolysis in skeletal muscle?","options":[{"id":"a","text":"Skeletal muscle lacks glucagon receptors"},{"id":"b","text":"Skeletal muscle has high insulin sensitivity"},{"id":"c","text":"Skeletal muscle responds to epinephrine"},{"id":"d","text":"Skeletal muscle does not store glycogen"}],"answerId":"a","explanation":"Skeletal muscle has little meaningful glucagon-receptor response, relying instead on epinephrine and local energy signals.","kind":"trap","origin":"ai"},{"id":"hen1-glucagon-fasting-metabolism~ai-4","moduleId":"hen1-glucagon-fasting-metabolism","stem":"How does a low insulin-to-glucagon ratio affect liver metabolism?","options":[{"id":"a","text":"Promotes glycogen storage"},{"id":"b","text":"Stimulates fuel mobilization"},{"id":"c","text":"Inhibits ketogenesis"},{"id":"d","text":"Enhances glycolysis"}],"answerId":"b","explanation":"A low insulin-to-glucagon ratio signals the liver to switch from storage to fuel mobilization, enhancing gluconeogenesis and ketogenesis.","kind":"mechanism","origin":"ai"},{"id":"hen1-glucagon-fasting-metabolism~ai-5","moduleId":"hen1-glucagon-fasting-metabolism","stem":"Which hormone primarily counteracts the effects of glucagon during the fed state?","options":[{"id":"a","text":"Cortisol"},{"id":"b","text":"Epinephrine"},{"id":"c","text":"Insulin"},{"id":"d","text":"Growth hormone"}],"answerId":"c","explanation":"Insulin primarily counteracts glucagon's effects by promoting glycogen synthesis and inhibiting gluconeogenesis.","kind":"integration","linkedModuleIds":["hen1-insulin-signaling-fed-metabolism"],"origin":"ai"},{"id":"hen1-glucagon-fasting-metabolism~ai-6","moduleId":"hen1-glucagon-fasting-metabolism","stem":"In what way does glucagon signaling relate to blood glucose homeostasis during fasting?","options":[{"id":"a","text":"Increases insulin secretion"},{"id":"b","text":"Decreases gluconeogenesis"},{"id":"c","text":"Stimulates glycogenolysis"},{"id":"d","text":"Increases blood glucose levels"}],"answerId":"d","explanation":"Glucagon increases blood glucose levels by stimulating gluconeogenesis and glycogenolysis in the liver during fasting.","kind":"integration","linkedModuleIds":["blood-glucose-homeostasis"],"origin":"ai"}],"hen1-insulin-signaling-fed-metabolism":[{"id":"hen1-insulin-signaling-fed-metabolism~ai-0","moduleId":"hen1-insulin-signaling-fed-metabolism","stem":"What is the primary mechanism by which insulin promotes glucose uptake in skeletal muscle?","options":[{"id":"a","text":"Inhibition of glycogenolysis"},{"id":"b","text":"GLUT4 translocation to the membrane"},{"id":"c","text":"Activation of gluconeogenesis"},{"id":"d","text":"Increased lipolysis"}],"answerId":"b","explanation":"Insulin stimulates the translocation of GLUT4 to the cell membrane in skeletal muscle, enhancing glucose uptake.","kind":"mechanism","origin":"ai"},{"id":"hen1-insulin-signaling-fed-metabolism~ai-1","moduleId":"hen1-insulin-signaling-fed-metabolism","stem":"Which of the following metabolic processes is inhibited by insulin?","options":[{"id":"a","text":"Glycogen synthesis"},{"id":"b","text":"Gluconeogenesis"},{"id":"c","text":"Protein synthesis"},{"id":"d","text":"Fatty acid synthesis"}],"answerId":"b","explanation":"Insulin suppresses gluconeogenesis while promoting glycogen synthesis, protein synthesis, and fatty acid synthesis.","kind":"recall","origin":"ai"},{"id":"hen1-insulin-signaling-fed-metabolism~ai-2","moduleId":"hen1-insulin-signaling-fed-metabolism","stem":"What is the effect of insulin on ketone production?","options":[{"id":"a","text":"Increases ketogenesis"},{"id":"b","text":"No effect on ketogenesis"},{"id":"c","text":"Inhibits ketogenesis"},{"id":"d","text":"Stimulates fatty acid oxidation"}],"answerId":"c","explanation":"Insulin inhibits lipolysis and hepatic fatty acid oxidation, leading to decreased ketone production.","kind":"clinical","origin":"ai"},{"id":"hen1-insulin-signaling-fed-metabolism~ai-3","moduleId":"hen1-insulin-signaling-fed-metabolism","stem":"Which glucose transporter is primarily responsible for glucose uptake in the liver?","options":[{"id":"a","text":"GLUT1"},{"id":"b","text":"GLUT2"},{"id":"c","text":"GLUT4"},{"id":"d","text":"GLUT3"}],"answerId":"b","explanation":"GLUT2 is the main glucose transporter in the liver, while GLUT4 is specific to skeletal muscle and adipose tissue.","kind":"trap","origin":"ai"},{"id":"hen1-insulin-signaling-fed-metabolism~ai-4","moduleId":"hen1-insulin-signaling-fed-metabolism","stem":"How does insulin affect malonyl-CoA levels in the fed state?","options":[{"id":"a","text":"Increases malonyl-CoA"},{"id":"b","text":"Decreases malonyl-CoA"},{"id":"c","text":"No effect on malonyl-CoA"},{"id":"d","text":"Malonyl-CoA is unrelated to insulin"}],"answerId":"a","explanation":"Insulin increases malonyl-CoA levels, which inhibits fatty acid entry into mitochondria, promoting fat storage.","kind":"mechanism","origin":"ai"},{"id":"hen1-insulin-signaling-fed-metabolism~ai-5","moduleId":"hen1-insulin-signaling-fed-metabolism","stem":"How does insulin signaling relate to glucose transport and glycolysis?","options":[{"id":"a","text":"Insulin decreases glycolysis by inhibiting glucose transport"},{"id":"b","text":"Insulin enhances glycolysis by promoting glucose transport"},{"id":"c","text":"Insulin has no effect on glycolysis"},{"id":"d","text":"Insulin only affects glucose transport, not glycolysis"}],"answerId":"b","explanation":"Insulin enhances glycolysis by promoting glucose transport into cells, where it can be metabolized.","kind":"integration","linkedModuleIds":["glucose-transport-glycolysis"],"origin":"ai"},{"id":"hen1-insulin-signaling-fed-metabolism~ai-6","moduleId":"hen1-insulin-signaling-fed-metabolism","stem":"What role do adipokines play in insulin resistance as discussed in the context of insulin signaling?","options":[{"id":"a","text":"Adipokines enhance insulin sensitivity"},{"id":"b","text":"Adipokines have no effect on insulin signaling"},{"id":"c","text":"Adipokines promote insulin resistance"},{"id":"d","text":"Adipokines only affect glucose transport"}],"answerId":"c","explanation":"Adipokines can promote insulin resistance, impacting the effectiveness of insulin signaling in metabolism.","kind":"integration","linkedModuleIds":["hen1-adipokines-obesity-insulin-resistance"],"origin":"ai"}],"hen1-insulin-synthesis-secretion":[{"id":"hen1-insulin-synthesis-secretion~ai-0","moduleId":"hen1-insulin-synthesis-secretion","stem":"What is the primary product of proinsulin cleavage in pancreatic beta cells?","options":[{"id":"a","text":"Insulin"},{"id":"b","text":"C-peptide"},{"id":"c","text":"Glucagon"},{"id":"d","text":"Somatostatin"}],"answerId":"a","explanation":"Proinsulin is cleaved into insulin and C-peptide, with insulin being the primary product.","kind":"recall","origin":"ai"},{"id":"hen1-insulin-synthesis-secretion~ai-1","moduleId":"hen1-insulin-synthesis-secretion","stem":"Which mechanism describes how glucose stimulates insulin secretion in beta cells?","options":[{"id":"a","text":"Inhibition of KATP channels"},{"id":"b","text":"Activation of GLP-1 receptors"},{"id":"c","text":"Increased cAMP levels"},{"id":"d","text":"Decreased ATP/ADP ratio"}],"answerId":"a","explanation":"Glucose metabolism increases the ATP/ADP ratio, which leads to the closure of KATP channels and subsequent depolarization.","kind":"mechanism","origin":"ai"},{"id":"hen1-insulin-synthesis-secretion~ai-2","moduleId":"hen1-insulin-synthesis-secretion","stem":"A patient presents with hypoglycemia and high insulin levels but low C-peptide. What is the most likely explanation?","options":[{"id":"a","text":"Endogenous insulin production"},{"id":"b","text":"Insulinoma"},{"id":"c","text":"Injected insulin"},{"id":"d","text":"Incretin effect"}],"answerId":"c","explanation":"Injected insulin does not contain C-peptide, leading to high insulin levels with low C-peptide during hypoglycemia.","kind":"clinical","origin":"ai"},{"id":"hen1-insulin-synthesis-secretion~ai-3","moduleId":"hen1-insulin-synthesis-secretion","stem":"Which of the following statements about incretin hormones is true?","options":[{"id":"a","text":"They are secreted in response to IV glucose."},{"id":"b","text":"They enhance insulin secretion in a glucose-dependent manner."},{"id":"c","text":"They decrease the ATP/ADP ratio in beta cells."},{"id":"d","text":"They inhibit glucagon release."}],"answerId":"b","explanation":"Incretin hormones like GLP-1 enhance insulin secretion in a glucose-dependent manner, contributing to the incretin effect.","kind":"trap","origin":"ai"},{"id":"hen1-insulin-synthesis-secretion~ai-4","moduleId":"hen1-insulin-synthesis-secretion","stem":"What is the effect of sulfonylureas on insulin secretion?","options":[{"id":"a","text":"They enhance incretin signaling."},{"id":"b","text":"They increase KATP channel activity."},{"id":"c","text":"They close KATP channels."},{"id":"d","text":"They stimulate glucagon release."}],"answerId":"c","explanation":"Sulfonylureas close KATP channels, leading to depolarization and increased insulin secretion from beta cells.","kind":"mechanism","origin":"ai"},{"id":"hen1-insulin-synthesis-secretion~ai-5","moduleId":"hen1-insulin-synthesis-secretion","stem":"How does oral glucose administration differ from IV glucose in terms of insulin secretion?","options":[{"id":"a","text":"Oral glucose leads to lower insulin levels."},{"id":"b","text":"IV glucose stimulates incretin release."},{"id":"c","text":"Oral glucose results in a greater insulin response."},{"id":"d","text":"Both produce equal insulin responses."}],"answerId":"c","explanation":"Oral glucose produces a larger insulin response due to the action of gut incretins, which amplify secretion.","kind":"integration","linkedModuleIds":["incretin-based-therapy"],"origin":"ai"},{"id":"hen1-insulin-synthesis-secretion~ai-6","moduleId":"hen1-insulin-synthesis-secretion","stem":"Which of the following best explains the role of C-peptide in assessing endogenous insulin production?","options":[{"id":"a","text":"C-peptide is released only with injected insulin."},{"id":"b","text":"C-peptide levels rise with oral glucose administration."},{"id":"c","text":"C-peptide indicates the presence of exogenous insulin."},{"id":"d","text":"C-peptide is absent when insulin is injected."}],"answerId":"d","explanation":"C-peptide is absent from injected insulin, making it a marker for endogenous proinsulin processing.","kind":"integration","linkedModuleIds":["insulin-secretagogues"],"origin":"ai"}],"hen1-calcitonin-mineral-integration":[{"id":"hen1-calcitonin-mineral-integration~ai-0","moduleId":"hen1-calcitonin-mineral-integration","stem":"What is the primary physiological role of calcitonin in adults?","options":[{"id":"a","text":"Rapidly increases serum calcium levels"},{"id":"b","text":"Inhibits osteoclast activity"},{"id":"c","text":"Stimulates renal calcium reabsorption"},{"id":"d","text":"Enhances intestinal calcium absorption"}],"answerId":"b","explanation":"Calcitonin primarily inhibits osteoclast activity, thus reducing bone resorption and lowering serum calcium levels.","kind":"recall","origin":"ai"},{"id":"hen1-calcitonin-mineral-integration~ai-1","moduleId":"hen1-calcitonin-mineral-integration","stem":"Which hormone is primarily responsible for increasing serum calcium levels in response to hypocalcemia?","options":[{"id":"a","text":"Calcitonin"},{"id":"b","text":"Parathyroid hormone (PTH)"},{"id":"c","text":"Vitamin D"},{"id":"d","text":"Fibroblast growth factor 23 (FGF23)"}],"answerId":"b","explanation":"Parathyroid hormone (PTH) is the key hormone that increases serum calcium levels in response to low calcium.","kind":"recall","origin":"ai"},{"id":"hen1-calcitonin-mineral-integration~ai-2","moduleId":"hen1-calcitonin-mineral-integration","stem":"A patient presents with a thyroid nodule and markedly elevated calcitonin levels. What is the most likely diagnosis?","options":[{"id":"a","text":"Primary hyperparathyroidism"},{"id":"b","text":"Medullary thyroid carcinoma"},{"id":"c","text":"Thyroid adenoma"},{"id":"d","text":"Papillary thyroid carcinoma"}],"answerId":"b","explanation":"Markedly elevated calcitonin levels with a thyroid nodule suggest medullary thyroid carcinoma, which arises from calcitonin-producing C cells.","kind":"clinical","origin":"ai"},{"id":"hen1-calcitonin-mineral-integration~ai-3","moduleId":"hen1-calcitonin-mineral-integration","stem":"How does calcitonin affect renal calcium excretion?","options":[{"id":"a","text":"Increases calcium reabsorption"},{"id":"b","text":"Decreases calcium reabsorption"},{"id":"c","text":"Has no effect on calcium excretion"},{"id":"d","text":"Increases phosphate excretion"}],"answerId":"b","explanation":"Calcitonin promotes renal calcium excretion by decreasing calcium reabsorption in the kidneys.","kind":"mechanism","origin":"ai"},{"id":"hen1-calcitonin-mineral-integration~ai-4","moduleId":"hen1-calcitonin-mineral-integration","stem":"Which statement about calcitonin is true?","options":[{"id":"a","text":"It is the main regulator of calcium homeostasis in adults."},{"id":"b","text":"Its loss leads to severe chronic hypocalcemia."},{"id":"c","text":"It plays a minor role compared to PTH and vitamin D."},{"id":"d","text":"It is the primary hormone for phosphate regulation."}],"answerId":"c","explanation":"Calcitonin has a smaller physiological role in calcium homeostasis compared to PTH and vitamin D; its loss does not cause severe chronic hypocalcemia.","kind":"trap","origin":"ai"},{"id":"hen1-calcitonin-mineral-integration~ai-5","moduleId":"hen1-calcitonin-mineral-integration","stem":"Calcitonin's role in mineral homeostasis is most closely related to which other hormone's function?","options":[{"id":"a","text":"Insulin"},{"id":"b","text":"Parathyroid hormone (PTH)"},{"id":"c","text":"Aldosterone"},{"id":"d","text":"Glucagon"}],"answerId":"b","explanation":"Calcitonin works in opposition to parathyroid hormone (PTH), which increases serum calcium levels, while calcitonin decreases it.","kind":"integration","linkedModuleIds":["hen1-pth-regulation-actions"],"origin":"ai"},{"id":"hen1-calcitonin-mineral-integration~ai-6","moduleId":"hen1-calcitonin-mineral-integration","stem":"In the context of chronic kidney disease (CKD), how does calcitonin interact with other mineral hormones?","options":[{"id":"a","text":"It compensates for PTH deficiency"},{"id":"b","text":"It enhances vitamin D activation"},{"id":"c","text":"It has no significant role"},{"id":"d","text":"It promotes phosphate retention"}],"answerId":"c","explanation":"In CKD, calcitonin has limited significance compared to PTH and vitamin D, which play more dominant roles in mineral balance.","kind":"integration","linkedModuleIds":["ckd-mineral-bone-disorder"],"origin":"ai"}],"hen1-islet-hormones-paracrine":[{"id":"hen1-islet-hormones-paracrine~ai-0","moduleId":"hen1-islet-hormones-paracrine","stem":"Which hormone is primarily secreted by pancreatic beta cells?","options":[{"id":"a","text":"Insulin"},{"id":"b","text":"Glucagon"},{"id":"c","text":"Somatostatin"},{"id":"d","text":"Pancreatic Polypeptide"}],"answerId":"a","explanation":"Beta cells in the islets of Langerhans are responsible for the secretion of insulin.","kind":"recall","origin":"ai"},{"id":"hen1-islet-hormones-paracrine~ai-1","moduleId":"hen1-islet-hormones-paracrine","stem":"What is the primary effect of somatostatin in the islet microenvironment?","options":[{"id":"a","text":"Stimulates glucagon release"},{"id":"b","text":"Inhibits insulin and glucagon release"},{"id":"c","text":"Enhances insulin sensitivity"},{"id":"d","text":"Promotes glycogenolysis"}],"answerId":"b","explanation":"Somatostatin inhibits the release of both insulin and glucagon, regulating the islet hormone balance.","kind":"mechanism","origin":"ai"},{"id":"hen1-islet-hormones-paracrine~ai-2","moduleId":"hen1-islet-hormones-paracrine","stem":"A patient presents with hyperglycemia due to beta-cell failure. What is the underlying mechanism?","options":[{"id":"a","text":"Increased glucagon secretion"},{"id":"b","text":"Decreased hepatic glucose output"},{"id":"c","text":"Increased insulin sensitivity"},{"id":"d","text":"Decreased peripheral glucose uptake"}],"answerId":"d","explanation":"Loss of insulin action leads to decreased peripheral glucose uptake and increased hepatic glucose output, resulting in hyperglycemia.","kind":"clinical","origin":"ai"},{"id":"hen1-islet-hormones-paracrine~ai-3","moduleId":"hen1-islet-hormones-paracrine","stem":"Which statement about islet cell function is correct?","options":[{"id":"a","text":"Each islet cell functions independently"},{"id":"b","text":"Islet hormones exert important local paracrine effects"},{"id":"c","text":"Insulin and glucagon are released simultaneously"},{"id":"d","text":"All islet cells secrete the same hormones"}],"answerId":"b","explanation":"Islet hormones exert important local paracrine effects on neighboring cells, coordinating their function.","kind":"trap","origin":"ai"},{"id":"hen1-islet-hormones-paracrine~ai-4","moduleId":"hen1-islet-hormones-paracrine","stem":"In a patient with long-standing diabetes, what is the likely cause of impaired glucagon counterregulation?","options":[{"id":"a","text":"Increased insulin secretion"},{"id":"b","text":"Alpha-cell dysregulation"},{"id":"c","text":"Decreased somatostatin levels"},{"id":"d","text":"Enhanced beta-cell function"}],"answerId":"b","explanation":"Alpha-cell response can become dysregulated with islet failure, impairing glucagon counterregulation.","kind":"clinical","origin":"ai"},{"id":"hen1-islet-hormones-paracrine~ai-5","moduleId":"hen1-islet-hormones-paracrine","stem":"How does insulin suppress glucagon secretion in the islet?","options":[{"id":"a","text":"By increasing blood glucose levels"},{"id":"b","text":"By paracrine signaling from beta to alpha cells"},{"id":"c","text":"By stimulating somatostatin release"},{"id":"d","text":"By enhancing hepatic glucose production"}],"answerId":"b","explanation":"Insulin suppresses glucagon release through paracrine signaling from beta cells to neighboring alpha cells.","kind":"mechanism","origin":"ai"},{"id":"hen1-islet-hormones-paracrine~ai-6","moduleId":"hen1-islet-hormones-paracrine","stem":"In the context of type 1 diabetes, what is the primary defect affecting insulin secretion?","options":[{"id":"a","text":"Insulin resistance"},{"id":"b","text":"Autoimmune destruction of beta cells"},{"id":"c","text":"Increased glucagon secretion"},{"id":"d","text":"Diminished somatostatin release"}],"answerId":"b","explanation":"Type 1 diabetes is characterized by autoimmune destruction of pancreatic beta cells, leading to insulin deficiency.","kind":"integration","linkedModuleIds":["type1-diabetes-pathogenesis"],"origin":"ai"},{"id":"hen1-islet-hormones-paracrine~ai-7","moduleId":"hen1-islet-hormones-paracrine","stem":"Which mechanism is primarily responsible for the increased glucose levels in a patient with glucagonoma?","options":[{"id":"a","text":"Increased insulin secretion"},{"id":"b","text":"Increased hepatic glucose production"},{"id":"c","text":"Decreased glucagon levels"},{"id":"d","text":"Increased somatostatin levels"}],"answerId":"b","explanation":"Glucagonoma leads to excessive glucagon secretion, which increases hepatic glucose production and results in hyperglycemia.","kind":"integration","linkedModuleIds":["hen1-glucagon-fasting-metabolism"],"origin":"ai"}],"hen1-diabetes-types-pathogenesis":[{"id":"hen1-diabetes-types-pathogenesis~ai-0","moduleId":"hen1-diabetes-types-pathogenesis","stem":"What is the primary mechanism underlying Type 1 diabetes?","options":[{"id":"a","text":"Insulin resistance"},{"id":"b","text":"Immune-mediated beta-cell destruction"},{"id":"c","text":"Obesity-related hyperinsulinemia"},{"id":"d","text":"Genetic predisposition alone"}],"answerId":"b","explanation":"Type 1 diabetes is characterized by immune-mediated destruction of pancreatic beta cells, leading to absolute insulin deficiency.","kind":"recall","origin":"ai"},{"id":"hen1-diabetes-types-pathogenesis~ai-1","moduleId":"hen1-diabetes-types-pathogenesis","stem":"Which clinical finding is most indicative of Type 2 diabetes?","options":[{"id":"a","text":"Lean patient with rapid onset of symptoms"},{"id":"b","text":"Acanthosis nigricans with central adiposity"},{"id":"c","text":"Presence of autoantibodies"},{"id":"d","text":"Low C-peptide levels"}],"answerId":"b","explanation":"Acanthosis nigricans is commonly associated with insulin resistance, which is a hallmark of Type 2 diabetes.","kind":"clinical","origin":"ai"},{"id":"hen1-diabetes-types-pathogenesis~ai-2","moduleId":"hen1-diabetes-types-pathogenesis","stem":"What effect does hyperglycemia have on beta-cell function?","options":[{"id":"a","text":"Enhances insulin secretion"},{"id":"b","text":"Worsens beta-cell function"},{"id":"c","text":"Stimulates glucagon release"},{"id":"d","text":"Increases insulin sensitivity"}],"answerId":"b","explanation":"Hyperglycemia leads to glucotoxicity, which can impair beta-cell function and worsen insulin sensitivity.","kind":"mechanism","origin":"ai"},{"id":"hen1-diabetes-types-pathogenesis~ai-3","moduleId":"hen1-diabetes-types-pathogenesis","stem":"Which of the following statements about diabetes classification is true?","options":[{"id":"a","text":"Adult onset automatically means type 2 diabetes"},{"id":"b","text":"Type 1 diabetes can present in adults"},{"id":"c","text":"Obesity is the sole cause of Type 2 diabetes"},{"id":"d","text":"All patients with diabetes are insulin resistant"}],"answerId":"b","explanation":"Type 1 diabetes can indeed present in adults, and classification should consider physiology and biomarkers rather than age alone.","kind":"trap","origin":"ai"},{"id":"hen1-diabetes-types-pathogenesis~ai-4","moduleId":"hen1-diabetes-types-pathogenesis","stem":"What is the primary defect in Type 2 diabetes pathogenesis?","options":[{"id":"a","text":"Autoimmune destruction of beta cells"},{"id":"b","text":"Inadequate insulin secretion due to beta-cell failure"},{"id":"c","text":"Increased insulin sensitivity"},{"id":"d","text":"Defective glucagon secretion"}],"answerId":"b","explanation":"Type 2 diabetes begins with insulin resistance followed by inadequate insulin secretion due to progressive beta-cell failure.","kind":"recall","origin":"ai"},{"id":"hen1-diabetes-types-pathogenesis~ai-5","moduleId":"hen1-diabetes-types-pathogenesis","stem":"How does glucotoxicity contribute to the progression of Type 2 diabetes?","options":[{"id":"a","text":"It enhances insulin sensitivity"},{"id":"b","text":"It leads to increased insulin secretion"},{"id":"c","text":"It worsens beta-cell function"},{"id":"d","text":"It reduces insulin resistance"}],"answerId":"c","explanation":"Glucotoxicity impairs beta-cell function, contributing to the progression of Type 2 diabetes.","kind":"mechanism","origin":"ai"},{"id":"hen1-diabetes-types-pathogenesis~ai-6","moduleId":"hen1-diabetes-types-pathogenesis","stem":"In a patient with suspected Type 1 diabetes, which test result would most likely support the diagnosis?","options":[{"id":"a","text":"High C-peptide levels"},{"id":"b","text":"Presence of GAD65 autoantibodies"},{"id":"c","text":"Low fasting glucose levels"},{"id":"d","text":"Normal BMI"}],"answerId":"b","explanation":"The presence of GAD65 autoantibodies is indicative of autoimmune Type 1 diabetes.","kind":"integration","linkedModuleIds":["type1-diabetes-pathogenesis"],"origin":"ai"},{"id":"hen1-diabetes-types-pathogenesis~ai-7","moduleId":"hen1-diabetes-types-pathogenesis","stem":"Which of the following findings would suggest a patient is more likely to have Type 2 diabetes rather than Type 1?","options":[{"id":"a","text":"Ketosis-prone with rapid onset"},{"id":"b","text":"Acanthosis nigricans"},{"id":"c","text":"Presence of islet autoantibodies"},{"id":"d","text":"Young age at diagnosis"}],"answerId":"b","explanation":"Acanthosis nigricans is associated with insulin resistance, which is more characteristic of Type 2 diabetes.","kind":"integration","linkedModuleIds":["insulin-resistance-type2-diabetes"],"origin":"ai"}],"hen1-gestational-diabetes-diagnosis":[{"id":"hen1-gestational-diabetes-diagnosis~ai-0","moduleId":"hen1-gestational-diabetes-diagnosis","stem":"What is the primary diagnostic test for gestational diabetes at 24-28 weeks of pregnancy?","options":[{"id":"a","text":"Fasting plasma glucose test"},{"id":"b","text":"75-g oral glucose tolerance test"},{"id":"c","text":"Hemoglobin A1c"},{"id":"d","text":"Random plasma glucose test"}],"answerId":"b","explanation":"The 75-g oral glucose tolerance test is the standard diagnostic test for gestational diabetes during this period.","kind":"recall","origin":"ai"},{"id":"hen1-gestational-diabetes-diagnosis~ai-1","moduleId":"hen1-gestational-diabetes-diagnosis","stem":"Which of the following values indicates a diagnosis of gestational diabetes during a 75-g OGTT?","options":[{"id":"a","text":"Fasting > 100 mg/dL"},{"id":"b","text":"1-hour > 160 mg/dL"},{"id":"c","text":"2-hour > 153 mg/dL"},{"id":"d","text":"3-hour > 140 mg/dL"}],"answerId":"c","explanation":"A 2-hour value of > 153 mg/dL during a 75-g OGTT meets the criteria for diagnosing gestational diabetes.","kind":"recall","origin":"ai"},{"id":"hen1-gestational-diabetes-diagnosis~ai-2","moduleId":"hen1-gestational-diabetes-diagnosis","stem":"What mechanism contributes to insulin resistance during pregnancy?","options":[{"id":"a","text":"Increased insulin secretion"},{"id":"b","text":"Decreased placental hormone levels"},{"id":"c","text":"Increased placental hormones"},{"id":"d","text":"Decreased maternal fat stores"}],"answerId":"c","explanation":"Increased placental hormones lead to greater insulin resistance as pregnancy progresses.","kind":"mechanism","origin":"ai"},{"id":"hen1-gestational-diabetes-diagnosis~ai-3","moduleId":"hen1-gestational-diabetes-diagnosis","stem":"A 28-year-old woman presents with hyperglycemia first detected at 26 weeks of gestation. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Increased insulin production"},{"id":"b","text":"Decreased insulin sensitivity"},{"id":"c","text":"Increased glucose excretion"},{"id":"d","text":"Decreased placental hormone levels"}],"answerId":"b","explanation":"The underlying mechanism is decreased insulin sensitivity due to increased placental hormones during pregnancy.","kind":"clinical","origin":"ai"},{"id":"hen1-gestational-diabetes-diagnosis~ai-4","moduleId":"hen1-gestational-diabetes-diagnosis","stem":"Which of the following is a common trap in gestational diabetes testing?","options":[{"id":"a","text":"Using fasting glucose criteria for diagnosis"},{"id":"b","text":"Requiring A1c testing for all pregnant women"},{"id":"c","text":"Using the same thresholds as nonpregnant diabetes"},{"id":"d","text":"Performing OGTT only if symptoms are present"}],"answerId":"a","explanation":"Using fasting glucose criteria for diagnosis is incorrect, as pregnancy requires specific glucose-load strategies and thresholds.","kind":"trap","origin":"ai"},{"id":"hen1-gestational-diabetes-diagnosis~ai-5","moduleId":"hen1-gestational-diabetes-diagnosis","stem":"How does gestational diabetes relate to future diabetes risk?","options":[{"id":"a","text":"It has no impact on future diabetes risk"},{"id":"b","text":"It predicts future type 1 diabetes"},{"id":"c","text":"It predicts future type 2 diabetes"},{"id":"d","text":"It only affects the current pregnancy"}],"answerId":"c","explanation":"Gestational diabetes is a predictor of future type 2 diabetes due to underlying metabolic risk.","kind":"recall","origin":"ai"},{"id":"hen1-gestational-diabetes-diagnosis~ai-6","moduleId":"hen1-gestational-diabetes-diagnosis","stem":"How does gestational diabetes screening differ from nonpregnant diabetes screening?","options":[{"id":"a","text":"Only fasting glucose is used"},{"id":"b","text":"Specific glucose-load strategies are employed"},{"id":"c","text":"A1c is the primary test"},{"id":"d","text":"No screening is performed during pregnancy"}],"answerId":"b","explanation":"Gestational diabetes screening employs specific glucose-load strategies and thresholds that differ from nonpregnant diabetes screening.","kind":"integration","linkedModuleIds":["diabetes-diagnostic-criteria-gdm"],"origin":"ai"},{"id":"hen1-gestational-diabetes-diagnosis~ai-7","moduleId":"hen1-gestational-diabetes-diagnosis","stem":"Which of the following findings would suggest a need for postpartum testing after gestational diabetes?","options":[{"id":"a","text":"Normal glucose levels during pregnancy"},{"id":"b","text":"History of gestational diabetes"},{"id":"c","text":"No family history of diabetes"},{"id":"d","text":"Age under 25 years"}],"answerId":"b","explanation":"A history of gestational diabetes indicates a need for postpartum testing due to increased risk of future type 2 diabetes.","kind":"integration","linkedModuleIds":["diabetes-diagnostic-criteria-gdm"],"origin":"ai"}],"hen1-adrenal-gross-anatomy-vasculature":[{"id":"hen1-adrenal-gross-anatomy-vasculature~ai-0","moduleId":"hen1-adrenal-gross-anatomy-vasculature","stem":"Which artery supplies the adrenal gland from the inferior phrenic artery?","options":[{"id":"a","text":"Inferior suprarenal artery"},{"id":"b","text":"Middle suprarenal artery"},{"id":"c","text":"Superior suprarenal artery"},{"id":"d","text":"Renal artery"}],"answerId":"c","explanation":"The superior suprarenal artery arises from the inferior phrenic artery and supplies the adrenal gland.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-gross-anatomy-vasculature~ai-1","moduleId":"hen1-adrenal-gross-anatomy-vasculature","stem":"What is the primary drainage pathway for the right adrenal vein?","options":[{"id":"a","text":"Left renal vein"},{"id":"b","text":"Inferior phrenic vein"},{"id":"c","text":"Inferior vena cava"},{"id":"d","text":"Aorta"}],"answerId":"c","explanation":"The right adrenal vein drains directly into the inferior vena cava, which is a key anatomical feature.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-gross-anatomy-vasculature~ai-2","moduleId":"hen1-adrenal-gross-anatomy-vasculature","stem":"Why is there a greater operative risk associated with the right adrenal vein?","options":[{"id":"a","text":"Longer length for mobilization"},{"id":"b","text":"Direct drainage into IVC"},{"id":"c","text":"Symmetrical drainage pattern"},{"id":"d","text":"Proximity to the pancreas"}],"answerId":"b","explanation":"The right adrenal vein drains directly into the IVC with little mobilization length, increasing surgical risk.","kind":"clinical","origin":"ai"},{"id":"hen1-adrenal-gross-anatomy-vasculature~ai-3","moduleId":"hen1-adrenal-gross-anatomy-vasculature","stem":"Which of the following statements about the left adrenal gland is true?","options":[{"id":"a","text":"It is pyramidal in shape."},{"id":"b","text":"It drains into the inferior vena cava."},{"id":"c","text":"It is semilunar in shape."},{"id":"d","text":"It has no arterial supply from the aorta."}],"answerId":"c","explanation":"The left adrenal gland is semilunar in shape and is located near the stomach, pancreas, and spleen.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-gross-anatomy-vasculature~ai-4","moduleId":"hen1-adrenal-gross-anatomy-vasculature","stem":"What is the significance of the asymmetrical drainage of the adrenal veins?","options":[{"id":"a","text":"It affects hormone secretion."},{"id":"b","text":"It is a major surgical landmark."},{"id":"c","text":"It indicates a developmental anomaly."},{"id":"d","text":"It influences blood supply."}],"answerId":"b","explanation":"The asymmetrical drainage pattern of the adrenal veins is a crucial surgical landmark during procedures involving the adrenal glands.","kind":"trap","origin":"ai"},{"id":"hen1-adrenal-gross-anatomy-vasculature~ai-5","moduleId":"hen1-adrenal-gross-anatomy-vasculature","stem":"How does the arterial supply of the adrenal glands relate to their function?","options":[{"id":"a","text":"It provides oxygen-rich blood for hormone synthesis."},{"id":"b","text":"It drains waste products from the medulla."},{"id":"c","text":"It regulates blood pressure."},{"id":"d","text":"It influences renal function."}],"answerId":"a","explanation":"Rich arterial inflow is essential for providing oxygen-rich blood necessary for hormone synthesis in the adrenal glands.","kind":"mechanism","origin":"ai"},{"id":"hen1-adrenal-gross-anatomy-vasculature~ai-6","moduleId":"hen1-adrenal-gross-anatomy-vasculature","stem":"How does the anatomy of the adrenal glands relate to the GI blood supply?","options":[{"id":"a","text":"Adrenal glands receive blood from the portal vein."},{"id":"b","text":"Adrenal glands are supplied by branches of the renal arteries."},{"id":"c","text":"Adrenal glands are influenced by the hepatic artery."},{"id":"d","text":"Adrenal glands are located near the inferior mesenteric artery."}],"answerId":"b","explanation":"The adrenal glands receive blood from the renal arteries, linking their vascular supply to the GI blood supply indirectly.","kind":"integration","linkedModuleIds":["gi-blood-supply-portal-system"],"origin":"ai"},{"id":"hen1-adrenal-gross-anatomy-vasculature~ai-7","moduleId":"hen1-adrenal-gross-anatomy-vasculature","stem":"Which anatomical relationship of the adrenal glands is crucial for understanding their surgical approach?","options":[{"id":"a","text":"Proximity to the liver and IVC for the right gland."},{"id":"b","text":"Proximity to the stomach for the left gland."},{"id":"c","text":"Both glands have symmetrical shapes."},{"id":"d","text":"Both glands drain into the same vein."}],"answerId":"a","explanation":"The right adrenal gland's proximity to the liver and IVC is crucial for surgical approaches, highlighting its unique anatomy.","kind":"integration","linkedModuleIds":["hen1-adrenal-cortex-histology-zones"],"origin":"ai"}],"hen1-glycemic-markers-emergencies":[{"id":"hen1-glycemic-markers-emergencies~ai-0","moduleId":"hen1-glycemic-markers-emergencies","stem":"What is the primary limitation of using A1C in patients with anemia?","options":[{"id":"a","text":"A1C is unaffected by anemia or red-cell lifespan"},{"id":"b","text":"A1C reflects average blood glucose over 1 month"},{"id":"c","text":"A1C is only valid in patients without kidney disease"},{"id":"d","text":"A1C cannot be used in pregnant women"}],"answerId":"a","explanation":"Any process changing erythrocyte survival can bias A1C, making it unreliable in anemia.","kind":"trap","origin":"ai"},{"id":"hen1-glycemic-markers-emergencies~ai-1","moduleId":"hen1-glycemic-markers-emergencies","stem":"Which biomarker is preferred for detecting significant ketoacidosis?","options":[{"id":"a","text":"Serum glucose"},{"id":"b","text":"Serum beta-hydroxybutyrate"},{"id":"c","text":"Urine ketones"},{"id":"d","text":"Fructosamine"}],"answerId":"b","explanation":"Serum beta-hydroxybutyrate is preferred as it directly indicates ketone levels in the blood.","kind":"recall","origin":"ai"},{"id":"hen1-glycemic-markers-emergencies~ai-2","moduleId":"hen1-glycemic-markers-emergencies","stem":"What clinical finding is characteristic of diabetic ketoacidosis (DKA)?","options":[{"id":"a","text":"Severe hyperosmolality"},{"id":"b","text":"Kussmaul breathing"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Normal anion gap"}],"answerId":"b","explanation":"Kussmaul breathing occurs due to metabolic acidosis from ketone accumulation in DKA.","kind":"recall","origin":"ai"},{"id":"hen1-glycemic-markers-emergencies~ai-3","moduleId":"hen1-glycemic-markers-emergencies","stem":"In hyperglycemic hyperosmolar state (HHS), which of the following is most prominent?","options":[{"id":"a","text":"Ketonemia"},{"id":"b","text":"Metabolic acidosis"},{"id":"c","text":"Severe hyperosmolality"},{"id":"d","text":"Hypokalemia"}],"answerId":"c","explanation":"HHS is characterized by extreme hyperglycemia and hyperosmolality with little or no major ketoacidosis.","kind":"clinical","origin":"ai"},{"id":"hen1-glycemic-markers-emergencies~ai-4","moduleId":"hen1-glycemic-markers-emergencies","stem":"How does fructosamine differ from A1C in clinical use?","options":[{"id":"a","text":"Fructosamine reflects glycemia over 2-3 months"},{"id":"b","text":"Fructosamine is affected by red-cell turnover"},{"id":"c","text":"Fructosamine reflects glycated albumin over 2-3 weeks"},{"id":"d","text":"Fructosamine requires fasting"}],"answerId":"c","explanation":"Fructosamine mainly reflects glycated albumin over about 2-3 weeks, making it useful for short-term glycemic control assessment.","kind":"mechanism","origin":"ai"},{"id":"hen1-glycemic-markers-emergencies~ai-5","moduleId":"hen1-glycemic-markers-emergencies","stem":"A patient presents with severe dehydration and altered mental status. Which condition should be suspected?","options":[{"id":"a","text":"Diabetic ketoacidosis"},{"id":"b","text":"Hyperglycemic hyperosmolar state"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Lactic acidosis"}],"answerId":"b","explanation":"Severe neurologic changes with profound hyperosmolality suggest HHS, which is characterized by extreme hyperglycemia and dehydration.","kind":"clinical","origin":"ai"},{"id":"hen1-glycemic-markers-emergencies~ai-6","moduleId":"hen1-glycemic-markers-emergencies","stem":"How does the understanding of DKA and HHS relate to the management of diabetes?","options":[{"id":"a","text":"Both conditions require immediate insulin therapy"},{"id":"b","text":"Only DKA requires fluid resuscitation"},{"id":"c","text":"HHS is primarily managed with oral hypoglycemics"},{"id":"d","text":"DKA is less severe than HHS"}],"answerId":"a","explanation":"Both DKA and HHS require immediate insulin therapy to manage hyperglycemia and associated complications.","kind":"integration","linkedModuleIds":["dka-hhs-recognition"],"origin":"ai"},{"id":"hen1-glycemic-markers-emergencies~ai-7","moduleId":"hen1-glycemic-markers-emergencies","stem":"Which test is most useful for evaluating glycemic control in a patient with fluctuating hemoglobin levels?","options":[{"id":"a","text":"A1C"},{"id":"b","text":"Fructosamine"},{"id":"c","text":"Serum glucose"},{"id":"d","text":"Urine ketones"}],"answerId":"b","explanation":"Fructosamine is less affected by hemoglobin variations and reflects glycemia over a shorter period.","kind":"integration","linkedModuleIds":["hba1c-fructosamine"],"origin":"ai"}],"hen1-diabetes-diagnostic-criteria":[{"id":"hen1-diabetes-diagnostic-criteria~ai-0","moduleId":"hen1-diabetes-diagnostic-criteria","stem":"What is the fasting plasma glucose threshold for diagnosing diabetes?","options":[{"id":"a","text":"100 mg/dL"},{"id":"b","text":"110 mg/dL"},{"id":"c","text":"126 mg/dL"},{"id":"d","text":"140 mg/dL"}],"answerId":"c","explanation":"A fasting plasma glucose of ≥126 mg/dL is one of the diagnostic criteria for diabetes.","kind":"recall","origin":"ai"},{"id":"hen1-diabetes-diagnostic-criteria~ai-1","moduleId":"hen1-diabetes-diagnostic-criteria","stem":"Which of the following findings is diagnostic for diabetes in a symptomatic patient?","options":[{"id":"a","text":"A1C of 5.9%"},{"id":"b","text":"Fasting glucose of 120 mg/dL"},{"id":"c","text":"Random glucose of 240 mg/dL"},{"id":"d","text":"2-hour glucose of 180 mg/dL"}],"answerId":"c","explanation":"A random plasma glucose of ≥200 mg/dL with classic symptoms confirms a diabetes diagnosis.","kind":"clinical","origin":"ai"},{"id":"hen1-diabetes-diagnostic-criteria~ai-2","moduleId":"hen1-diabetes-diagnostic-criteria","stem":"What is the A1C range that indicates prediabetes?","options":[{"id":"a","text":"5.0–5.6%"},{"id":"b","text":"5.7–6.4%"},{"id":"c","text":"6.5–6.9%"},{"id":"d","text":"7.0–7.5%"}],"answerId":"b","explanation":"Prediabetes is defined by an A1C of 5.7–6.4%.","kind":"recall","origin":"ai"},{"id":"hen1-diabetes-diagnostic-criteria~ai-3","moduleId":"hen1-diabetes-diagnostic-criteria","stem":"Which statement about diabetes diagnosis is correct?","options":[{"id":"a","text":"A single mildly abnormal result confirms diabetes."},{"id":"b","text":"Two abnormal results are needed for diagnosis."},{"id":"c","text":"Symptoms alone are sufficient for diagnosis."},{"id":"d","text":"A1C testing is not valid for diagnosis."}],"answerId":"b","explanation":"Diagnosis requires two abnormal results unless there is unequivocal hyperglycemia.","kind":"trap","origin":"ai"},{"id":"hen1-diabetes-diagnostic-criteria~ai-4","moduleId":"hen1-diabetes-diagnostic-criteria","stem":"In a patient with an A1C of 6.6% and no hyperglycemic symptoms, what is the next step?","options":[{"id":"a","text":"Diagnose diabetes immediately"},{"id":"b","text":"Repeat A1C testing"},{"id":"c","text":"Perform a fasting glucose test"},{"id":"d","text":"Conduct a 75-g OGTT"}],"answerId":"b","explanation":"Without unequivocal hyperglycemia, a repeat A1C test is necessary for confirmation.","kind":"mechanism","origin":"ai"},{"id":"hen1-diabetes-diagnostic-criteria~ai-5","moduleId":"hen1-diabetes-diagnostic-criteria","stem":"How does the 75-g OGTT relate to diabetes diagnosis?","options":[{"id":"a","text":"It is only used for gestational diabetes."},{"id":"b","text":"It can confirm diabetes with a 2-hour glucose ≥200 mg/dL."},{"id":"c","text":"It is less reliable than A1C testing."},{"id":"d","text":"It is used to diagnose type 1 diabetes only."}],"answerId":"b","explanation":"A 2-hour plasma glucose of ≥200 mg/dL during a 75-g OGTT is a diagnostic criterion for diabetes.","kind":"integration","linkedModuleIds":["diabetes-diagnostic-criteria-gdm"],"origin":"ai"},{"id":"hen1-diabetes-diagnostic-criteria~ai-6","moduleId":"hen1-diabetes-diagnostic-criteria","stem":"Which of the following is a common symptom of diabetes that may prompt testing?","options":[{"id":"a","text":"Weight gain"},{"id":"b","text":"Polyuria"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Nausea"}],"answerId":"b","explanation":"Polyuria is a classic symptom of diabetes that often leads to further testing.","kind":"clinical","origin":"ai"},{"id":"hen1-diabetes-diagnostic-criteria~ai-7","moduleId":"hen1-diabetes-diagnostic-criteria","stem":"What is the significance of confirming diabetes with two abnormal results?","options":[{"id":"a","text":"It reduces the risk of misdiagnosis."},{"id":"b","text":"It is not necessary if symptoms are present."},{"id":"c","text":"It is only required for type 2 diabetes."},{"id":"d","text":"It allows for immediate treatment initiation."}],"answerId":"a","explanation":"Confirming with two abnormal results minimizes the risk of false positives due to biological variation.","kind":"trap","origin":"ai"},{"id":"hen1-diabetes-diagnostic-criteria~ai-8","moduleId":"hen1-diabetes-diagnostic-criteria","stem":"What is the relationship between obesity and prediabetes as assessed by OGTT?","options":[{"id":"a","text":"Obesity does not affect OGTT results."},{"id":"b","text":"Obesity is a risk factor for developing prediabetes."},{"id":"c","text":"OGTT is not influenced by body weight."},{"id":"d","text":"Weight loss has no effect on glucose tolerance."}],"answerId":"b","explanation":"Obesity is a significant risk factor for developing prediabetes, which can be assessed using OGTT.","kind":"integration","linkedModuleIds":["prediabetes-ogtt-hba1c"],"origin":"ai"}],"hen1-adipokines-obesity-insulin-resistance":[{"id":"hen1-adipokines-obesity-insulin-resistance~ai-0","moduleId":"hen1-adipokines-obesity-insulin-resistance","stem":"What is the primary role of adiponectin in the context of obesity?","options":[{"id":"a","text":"Promotes appetite"},{"id":"b","text":"Increases insulin sensitivity"},{"id":"c","text":"Stimulates lipogenesis"},{"id":"d","text":"Inhibits fatty acid oxidation"}],"answerId":"b","explanation":"Adiponectin enhances insulin sensitivity and fatty acid oxidation, which is often reduced in obesity.","kind":"recall","origin":"ai"},{"id":"hen1-adipokines-obesity-insulin-resistance~ai-1","moduleId":"hen1-adipokines-obesity-insulin-resistance","stem":"Which mechanism primarily contributes to insulin resistance in obesity?","options":[{"id":"a","text":"Increased leptin secretion"},{"id":"b","text":"Adipocyte hypertrophy and inflammation"},{"id":"c","text":"Decreased glucagon levels"},{"id":"d","text":"Enhanced fatty acid synthesis"}],"answerId":"b","explanation":"Adipocyte hypertrophy and inflammation lead to impaired insulin signaling, contributing to insulin resistance.","kind":"mechanism","origin":"ai"},{"id":"hen1-adipokines-obesity-insulin-resistance~ai-2","moduleId":"hen1-adipokines-obesity-insulin-resistance","stem":"A patient with obesity presents with high leptin levels. What does this indicate?","options":[{"id":"a","text":"Leptin deficiency"},{"id":"b","text":"Leptin resistance"},{"id":"c","text":"Normal leptin sensitivity"},{"id":"d","text":"Increased appetite"}],"answerId":"b","explanation":"In common obesity, high leptin levels indicate leptin resistance rather than deficiency.","kind":"trap","origin":"ai"},{"id":"hen1-adipokines-obesity-insulin-resistance~ai-3","moduleId":"hen1-adipokines-obesity-insulin-resistance","stem":"Which clinical finding is commonly associated with metabolic syndrome in obesity?","options":[{"id":"a","text":"Low insulin levels"},{"id":"b","text":"Fatty liver"},{"id":"c","text":"Increased muscle mass"},{"id":"d","text":"Decreased waist circumference"}],"answerId":"b","explanation":"Fatty liver is a common finding in individuals with metabolic syndrome due to ectopic lipid accumulation.","kind":"clinical","origin":"ai"},{"id":"hen1-adipokines-obesity-insulin-resistance~ai-4","moduleId":"hen1-adipokines-obesity-insulin-resistance","stem":"How does leptin function in the hypothalamus regarding energy balance?","options":[{"id":"a","text":"Stimulates appetite"},{"id":"b","text":"Inhibits energy expenditure"},{"id":"c","text":"Signals energy sufficiency"},{"id":"d","text":"Promotes fat storage"}],"answerId":"c","explanation":"Leptin signals energy sufficiency to the hypothalamus, reducing appetite and supporting energy expenditure.","kind":"mechanism","origin":"ai"},{"id":"hen1-adipokines-obesity-insulin-resistance~ai-5","moduleId":"hen1-adipokines-obesity-insulin-resistance","stem":"In patients with obesity-driven insulin resistance, which adipokine is often found at reduced levels?","options":[{"id":"a","text":"Leptin"},{"id":"b","text":"Adiponectin"},{"id":"c","text":"Resistin"},{"id":"d","text":"Ghrelin"}],"answerId":"b","explanation":"Adiponectin levels typically decrease with visceral obesity, contributing to insulin resistance.","kind":"recall","origin":"ai"},{"id":"hen1-adipokines-obesity-insulin-resistance~ai-6","moduleId":"hen1-adipokines-obesity-insulin-resistance","stem":"How does obesity influence insulin receptor signaling pathways?","options":[{"id":"a","text":"Enhances insulin receptor sensitivity"},{"id":"b","text":"Inhibits glucose uptake"},{"id":"c","text":"Promotes insulin receptor expression"},{"id":"d","text":"Stimulates glycogen synthesis"}],"answerId":"b","explanation":"Obesity leads to insulin resistance, inhibiting glucose uptake despite the presence of insulin.","kind":"integration","linkedModuleIds":["hen1-insulin-signaling-fed-metabolism"],"origin":"ai"},{"id":"hen1-adipokines-obesity-insulin-resistance~ai-7","moduleId":"hen1-adipokines-obesity-insulin-resistance","stem":"Which of the following best describes the relationship between adipokines and insulin resistance?","options":[{"id":"a","text":"Adipokines have no effect on insulin signaling"},{"id":"b","text":"All adipokines promote insulin sensitivity"},{"id":"c","text":"Certain adipokines can impair insulin signaling"},{"id":"d","text":"Adipokines only affect appetite regulation"}],"answerId":"c","explanation":"Certain adipokines, particularly those secreted by inflamed adipose tissue, can impair insulin signaling and promote resistance.","kind":"integration","linkedModuleIds":["obesity-insulin-resistance"],"origin":"ai"}],"hen1-vitamin-d-metabolism-actions":[{"id":"hen1-vitamin-d-metabolism-actions~ai-0","moduleId":"hen1-vitamin-d-metabolism-actions","stem":"What is the primary form of vitamin D circulating in the blood?","options":[{"id":"a","text":"1,25-(OH)₂ vitamin D"},{"id":"b","text":"25-OH vitamin D"},{"id":"c","text":"Vitamin D2"},{"id":"d","text":"7-dehydrocholesterol"}],"answerId":"b","explanation":"25-OH vitamin D is the main circulating storage form of vitamin D and is used to assess vitamin D status.","kind":"recall","origin":"ai"},{"id":"hen1-vitamin-d-metabolism-actions~ai-1","moduleId":"hen1-vitamin-d-metabolism-actions","stem":"Which hormone stimulates the conversion of 25-OH vitamin D to its active form?","options":[{"id":"a","text":"Calcitonin"},{"id":"b","text":"Parathyroid hormone (PTH)"},{"id":"c","text":"Fibroblast growth factor 23 (FGF23)"},{"id":"d","text":"Insulin"}],"answerId":"b","explanation":"PTH stimulates the renal 1α-hydroxylase enzyme to convert 25-OH vitamin D to 1,25-(OH)₂ vitamin D.","kind":"mechanism","origin":"ai"},{"id":"hen1-vitamin-d-metabolism-actions~ai-2","moduleId":"hen1-vitamin-d-metabolism-actions","stem":"A child presents with bowed legs and a rachitic rosary. What is the likely underlying cause?","options":[{"id":"a","text":"Excess vitamin D"},{"id":"b","text":"Vitamin D deficiency"},{"id":"c","text":"Calcium excess"},{"id":"d","text":"Phosphate deficiency"}],"answerId":"b","explanation":"Vitamin D deficiency impairs mineralization, leading to rickets, which presents with bowed legs and rachitic rosary.","kind":"clinical","origin":"ai"},{"id":"hen1-vitamin-d-metabolism-actions~ai-3","moduleId":"hen1-vitamin-d-metabolism-actions","stem":"What is the best test to assess vitamin D stores in a patient?","options":[{"id":"a","text":"1,25-(OH)₂ vitamin D"},{"id":"b","text":"25-OH vitamin D"},{"id":"c","text":"Vitamin D2 levels"},{"id":"d","text":"Calcium levels"}],"answerId":"b","explanation":"25-OH vitamin D is the best indicator of vitamin D stores, while 1,25-(OH)₂ vitamin D is tightly regulated.","kind":"trap","origin":"ai"},{"id":"hen1-vitamin-d-metabolism-actions~ai-4","moduleId":"hen1-vitamin-d-metabolism-actions","stem":"How does calcitriol affect intestinal absorption?","options":[{"id":"a","text":"Decreases calcium absorption"},{"id":"b","text":"Increases phosphate absorption"},{"id":"c","text":"Inhibits calcium absorption"},{"id":"d","text":"Decreases phosphate absorption"}],"answerId":"b","explanation":"Calcitriol increases intestinal absorption of both calcium and phosphate, essential for bone health.","kind":"mechanism","origin":"ai"},{"id":"hen1-vitamin-d-metabolism-actions~ai-5","moduleId":"hen1-vitamin-d-metabolism-actions","stem":"How does vitamin D deficiency lead to secondary hyperparathyroidism?","options":[{"id":"a","text":"Increased calcium absorption"},{"id":"b","text":"Decreased calcium levels"},{"id":"c","text":"Increased phosphate levels"},{"id":"d","text":"Decreased PTH secretion"}],"answerId":"b","explanation":"Vitamin D deficiency leads to decreased calcium levels, stimulating PTH secretion to compensate.","kind":"mechanism","origin":"ai"},{"id":"hen1-vitamin-d-metabolism-actions~ai-6","moduleId":"hen1-vitamin-d-metabolism-actions","stem":"What is the relationship between vitamin D metabolism and calcium homeostasis?","options":[{"id":"a","text":"Vitamin D decreases calcium absorption"},{"id":"b","text":"Calcium regulates vitamin D synthesis"},{"id":"c","text":"Vitamin D enhances calcium absorption"},{"id":"d","text":"Calcium inhibits vitamin D activation"}],"answerId":"c","explanation":"Vitamin D enhances intestinal absorption of calcium, crucial for maintaining calcium homeostasis.","kind":"integration","linkedModuleIds":["hen1-calcium-phosphate-pools"],"origin":"ai"},{"id":"hen1-vitamin-d-metabolism-actions~ai-7","moduleId":"hen1-vitamin-d-metabolism-actions","stem":"How does parathyroid hormone (PTH) interact with vitamin D in calcium regulation?","options":[{"id":"a","text":"PTH inhibits vitamin D activation"},{"id":"b","text":"PTH stimulates vitamin D synthesis"},{"id":"c","text":"PTH has no effect on vitamin D"},{"id":"d","text":"PTH decreases calcium absorption"}],"answerId":"b","explanation":"PTH stimulates the conversion of 25-OH vitamin D to its active form, enhancing calcium absorption.","kind":"integration","linkedModuleIds":["hen1-pth-regulation-actions"],"origin":"ai"}],"gi-wall-esophagus-histology":[{"id":"gi-wall-esophagus-histology~ai-0","moduleId":"gi-wall-esophagus-histology","stem":"What type of epithelium lines the esophagus?","options":[{"id":"a","text":"Simple cuboidal epithelium"},{"id":"b","text":"Nonkeratinized stratified squamous epithelium"},{"id":"c","text":"Keratinized stratified squamous epithelium"},{"id":"d","text":"Columnar epithelium"}],"answerId":"b","explanation":"The esophagus is lined by nonkeratinized stratified squamous epithelium to protect against abrasion from food.","kind":"recall","origin":"ai"},{"id":"gi-wall-esophagus-histology~ai-1","moduleId":"gi-wall-esophagus-histology","stem":"Which plexus is responsible for regulating motility in the esophagus?","options":[{"id":"a","text":"Meissner submucosal plexus"},{"id":"b","text":"Auerbach myenteric plexus"},{"id":"c","text":"Dorsal vagal nucleus"},{"id":"d","text":"Celiac plexus"}],"answerId":"b","explanation":"The Auerbach myenteric plexus lies between the circular and longitudinal muscle layers and regulates motility.","kind":"recall","origin":"ai"},{"id":"gi-wall-esophagus-histology~ai-2","moduleId":"gi-wall-esophagus-histology","stem":"What is the primary function of the nonkeratinized stratified squamous epithelium in the esophagus?","options":[{"id":"a","text":"Absorption of nutrients"},{"id":"b","text":"Protection from food abrasion"},{"id":"c","text":"Secretion of mucus"},{"id":"d","text":"Facilitation of peristalsis"}],"answerId":"b","explanation":"This type of epithelium protects the esophagus from abrasion caused by food.","kind":"mechanism","origin":"ai"},{"id":"gi-wall-esophagus-histology~ai-3","moduleId":"gi-wall-esophagus-histology","stem":"In which part of the esophagus does the muscularis externa transition from skeletal to smooth muscle?","options":[{"id":"a","text":"Upper third"},{"id":"b","text":"Middle third"},{"id":"c","text":"Lower third"},{"id":"d","text":"Entire length"}],"answerId":"b","explanation":"The muscularis externa transitions from skeletal muscle in the upper third to smooth muscle in the lower third.","kind":"recall","origin":"ai"},{"id":"gi-wall-esophagus-histology~ai-4","moduleId":"gi-wall-esophagus-histology","stem":"Where is the Auerbach myenteric plexus located?","options":[{"id":"a","text":"In the lamina propria"},{"id":"b","text":"Between the circular and longitudinal muscle layers"},{"id":"c","text":"In the submucosa"},{"id":"d","text":"In the serosa"}],"answerId":"b","explanation":"The Auerbach plexus is situated between the circular and longitudinal layers of the muscularis externa, facilitating coordinated motility.","kind":"trap","origin":"ai"},{"id":"gi-wall-esophagus-histology~ai-5","moduleId":"gi-wall-esophagus-histology","stem":"How does the histological structure of the esophagus relate to its function in food transport?","options":[{"id":"a","text":"It has a thick muscularis externa for absorption"},{"id":"b","text":"It has a nonkeratinized epithelium for protection"},{"id":"c","text":"It has numerous goblet cells for lubrication"},{"id":"d","text":"It has a serosa for structural support"}],"answerId":"b","explanation":"The nonkeratinized stratified squamous epithelium protects the esophagus from abrasion during food transport.","kind":"integration","linkedModuleIds":["oral-mucosa-tongue-taste"],"origin":"ai"},{"id":"gi-wall-esophagus-histology~ai-6","moduleId":"gi-wall-esophagus-histology","stem":"What embryonic layer gives rise to the epithelium of the esophagus?","options":[{"id":"a","text":"Ectoderm"},{"id":"b","text":"Mesoderm"},{"id":"c","text":"Endoderm"},{"id":"d","text":"Neuroectoderm"}],"answerId":"c","explanation":"The epithelium of the esophagus is derived from the endoderm during embryonic development.","kind":"integration","linkedModuleIds":["germ-layer-derivatives-folding"],"origin":"ai"}],"hen1-cortisol-hpa-axis":[{"id":"hen1-cortisol-hpa-axis~ai-0","moduleId":"hen1-cortisol-hpa-axis","stem":"What is the primary function of ACTH in cortisol synthesis?","options":[{"id":"a","text":"Stimulates cholesterol delivery to adrenal cortex"},{"id":"b","text":"Inhibits cortisol production"},{"id":"c","text":"Promotes cortisol degradation"},{"id":"d","text":"Increases aldosterone secretion"}],"answerId":"a","explanation":"ACTH stimulates acute cholesterol delivery to the adrenal cortex, which is essential for cortisol synthesis.","kind":"recall","origin":"ai"},{"id":"hen1-cortisol-hpa-axis~ai-1","moduleId":"hen1-cortisol-hpa-axis","stem":"Which of the following statements about cortisol's circadian rhythm is true?","options":[{"id":"a","text":"Cortisol levels peak at midnight"},{"id":"b","text":"Cortisol is secreted in a constant manner"},{"id":"c","text":"Cortisol levels peak near waking"},{"id":"d","text":"Cortisol secretion is not influenced by stress"}],"answerId":"c","explanation":"Cortisol levels typically peak near waking and reach a nadir near midnight, influenced by circadian rhythms.","kind":"recall","origin":"ai"},{"id":"hen1-cortisol-hpa-axis~ai-2","moduleId":"hen1-cortisol-hpa-axis","stem":"What is the consequence of abrupt withdrawal from chronic glucocorticoid therapy?","options":[{"id":"a","text":"Increased ACTH levels"},{"id":"b","text":"Adrenal crisis due to suppressed HPA axis"},{"id":"c","text":"Enhanced cortisol production"},{"id":"d","text":"Cushing syndrome development"}],"answerId":"b","explanation":"Abrupt withdrawal leads to adrenal crisis as the suppressed HPA axis cannot promptly restore endogenous cortisol levels.","kind":"clinical","origin":"ai"},{"id":"hen1-cortisol-hpa-axis~ai-3","moduleId":"hen1-cortisol-hpa-axis","stem":"How does chronic glucocorticoid therapy affect the adrenal cortex?","options":[{"id":"a","text":"Causes adrenal hyperplasia"},{"id":"b","text":"Stimulates ACTH production"},{"id":"c","text":"Leads to fasciculata and reticularis atrophy"},{"id":"d","text":"Increases cortisol synthesis"}],"answerId":"c","explanation":"Chronic glucocorticoid therapy suppresses ACTH, leading to atrophy of the fasciculata and reticularis layers of the adrenal cortex.","kind":"trap","origin":"ai"},{"id":"hen1-cortisol-hpa-axis~ai-4","moduleId":"hen1-cortisol-hpa-axis","stem":"Which mechanism explains low ACTH levels after long-term glucocorticoid treatment?","options":[{"id":"a","text":"Increased adrenal stimulation"},{"id":"b","text":"Negative feedback from exogenous glucocorticoids"},{"id":"c","text":"Enhanced ACTH production"},{"id":"d","text":"Adrenal gland hyperactivity"}],"answerId":"b","explanation":"Exogenous glucocorticoids exert negative feedback on the pituitary, reducing ACTH levels and leading to adrenal atrophy.","kind":"mechanism","origin":"ai"},{"id":"hen1-cortisol-hpa-axis~ai-5","moduleId":"hen1-cortisol-hpa-axis","stem":"How does cortisol influence the immune response?","options":[{"id":"a","text":"Enhances inflammation"},{"id":"b","text":"Suppresses immune function"},{"id":"c","text":"Increases antibody production"},{"id":"d","text":"Stimulates T-cell activation"}],"answerId":"b","explanation":"Cortisol has anti-inflammatory actions and suppresses immune function, which is crucial in stress responses.","kind":"integration","linkedModuleIds":["hen1-cortisol-systemic-actions"],"origin":"ai"},{"id":"hen1-cortisol-hpa-axis~ai-6","moduleId":"hen1-cortisol-hpa-axis","stem":"What is the relationship between cortisol and circadian rhythms?","options":[{"id":"a","text":"Cortisol levels are constant throughout the day"},{"id":"b","text":"Cortisol secretion is independent of sleep cycles"},{"id":"c","text":"Cortisol peaks in the early morning"},{"id":"d","text":"Cortisol is not influenced by stress"}],"answerId":"c","explanation":"Cortisol levels follow a circadian rhythm, peaking in the early morning and influenced by sleep cycles and stress.","kind":"integration","linkedModuleIds":["sleep-circadian-rhythms"],"origin":"ai"}],"hen1-adrenal-medulla-innervation":[{"id":"hen1-adrenal-medulla-innervation~ai-0","moduleId":"hen1-adrenal-medulla-innervation","stem":"What type of cells in the adrenal medulla are responsible for catecholamine production?","options":[{"id":"a","text":"Chromaffin cells"},{"id":"b","text":"Adrenal cortical cells"},{"id":"c","text":"Medullary epithelial cells"},{"id":"d","text":"Sympathetic ganglion cells"}],"answerId":"a","explanation":"Chromaffin cells are specialized cells in the adrenal medulla that produce catecholamines.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-medulla-innervation~ai-1","moduleId":"hen1-adrenal-medulla-innervation","stem":"Which neurotransmitter is released by preganglionic sympathetic fibers onto chromaffin cells?","options":[{"id":"a","text":"Norepinephrine"},{"id":"b","text":"Epinephrine"},{"id":"c","text":"Acetylcholine"},{"id":"d","text":"Dopamine"}],"answerId":"c","explanation":"Preganglionic sympathetic fibers release acetylcholine onto nicotinic receptors of chromaffin cells.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-medulla-innervation~ai-2","moduleId":"hen1-adrenal-medulla-innervation","stem":"What is the primary effect of cortisol on catecholamine production in the adrenal medulla?","options":[{"id":"a","text":"Inhibits catecholamine synthesis"},{"id":"b","text":"Stimulates PNMT activity"},{"id":"c","text":"Promotes norepinephrine release"},{"id":"d","text":"Increases sympathetic tone"}],"answerId":"b","explanation":"Cortisol stimulates PNMT, which converts norepinephrine to epinephrine in the adrenal medulla.","kind":"mechanism","origin":"ai"},{"id":"hen1-adrenal-medulla-innervation~ai-3","moduleId":"hen1-adrenal-medulla-innervation","stem":"A patient presents with episodic palpitations and sweating. What is the most likely cause?","options":[{"id":"a","text":"Chronic anxiety"},{"id":"b","text":"Adrenal medulla tumor"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Hyperthyroidism"}],"answerId":"b","explanation":"Episodic palpitations and sweating are indicative of intermittent catecholamine release from a chromaffin-cell tumor.","kind":"clinical","origin":"ai"},{"id":"hen1-adrenal-medulla-innervation~ai-4","moduleId":"hen1-adrenal-medulla-innervation","stem":"Which statement about chromaffin cells is true?","options":[{"id":"a","text":"They receive postganglionic noradrenergic fibers"},{"id":"b","text":"They are derived from ectoderm"},{"id":"c","text":"They are modified postganglionic sympathetic neurons"},{"id":"d","text":"They release dopamine as a primary catecholamine"}],"answerId":"c","explanation":"Chromaffin cells are modified postganglionic sympathetic neurons that produce catecholamines.","kind":"trap","origin":"ai"},{"id":"hen1-adrenal-medulla-innervation~ai-5","moduleId":"hen1-adrenal-medulla-innervation","stem":"How does the adrenal cortex influence the adrenal medulla's function?","options":[{"id":"a","text":"By directly innervating chromaffin cells"},{"id":"b","text":"By regulating blood flow to the medulla"},{"id":"c","text":"By producing cortisol that stimulates PNMT"},{"id":"d","text":"By releasing catecholamines into the bloodstream"}],"answerId":"c","explanation":"Cortisol produced by the adrenal cortex stimulates PNMT in the adrenal medulla, enhancing epinephrine production.","kind":"integration","linkedModuleIds":["hen1-adrenal-cortex-histology-zones"],"origin":"ai"},{"id":"hen1-adrenal-medulla-innervation~ai-6","moduleId":"hen1-adrenal-medulla-innervation","stem":"Which developmental aspect is crucial for the formation of chromaffin cells in the adrenal medulla?","options":[{"id":"a","text":"Mesodermal origin"},{"id":"b","text":"Neural crest cell migration"},{"id":"c","text":"Endodermal differentiation"},{"id":"d","text":"Ectodermal signaling"}],"answerId":"b","explanation":"Chromaffin cells are derived from neural crest cells during development.","kind":"integration","linkedModuleIds":["hen1-adrenal-development"],"origin":"ai"}],"hen1-cortisol-systemic-actions":[{"id":"hen1-cortisol-systemic-actions~ai-0","moduleId":"hen1-cortisol-systemic-actions","stem":"What is the primary mechanism by which cortisol exerts its metabolic effects?","options":[{"id":"a","text":"Inhibition of insulin secretion"},{"id":"b","text":"Activation of glucagon receptors"},{"id":"c","text":"Binding to intracellular glucocorticoid receptors"},{"id":"d","text":"Stimulation of growth hormone release"}],"answerId":"c","explanation":"Cortisol binds to intracellular glucocorticoid receptors, leading to changes in gene expression that mediate its metabolic effects.","kind":"mechanism","origin":"ai"},{"id":"hen1-cortisol-systemic-actions~ai-1","moduleId":"hen1-cortisol-systemic-actions","stem":"Which of the following is a common clinical finding in patients with chronic excess cortisol?","options":[{"id":"a","text":"Hypoglycemia"},{"id":"b","text":"Proximal muscle weakness"},{"id":"c","text":"Lymphocytosis"},{"id":"d","text":"Hyperkalemia"}],"answerId":"b","explanation":"Chronic excess cortisol leads to muscle wasting, which manifests as proximal muscle weakness.","kind":"recall","origin":"ai"},{"id":"hen1-cortisol-systemic-actions~ai-2","moduleId":"hen1-cortisol-systemic-actions","stem":"Cortisol primarily raises blood glucose levels through which mechanism?","options":[{"id":"a","text":"Glycogenolysis"},{"id":"b","text":"Gluconeogenesis"},{"id":"c","text":"Increased insulin sensitivity"},{"id":"d","text":"Decreased lipolysis"}],"answerId":"b","explanation":"Cortisol raises blood glucose levels primarily through hepatic gluconeogenesis.","kind":"recall","origin":"ai"},{"id":"hen1-cortisol-systemic-actions~ai-3","moduleId":"hen1-cortisol-systemic-actions","stem":"What is a key effect of cortisol on the immune system?","options":[{"id":"a","text":"Increased lymphocyte proliferation"},{"id":"b","text":"Decreased neutrophil count"},{"id":"c","text":"Inhibition of cytokine production"},{"id":"d","text":"Enhancement of macrophage activity"}],"answerId":"c","explanation":"Cortisol suppresses inflammatory responses by inhibiting cytokine production.","kind":"mechanism","origin":"ai"},{"id":"hen1-cortisol-systemic-actions~ai-4","moduleId":"hen1-cortisol-systemic-actions","stem":"Which of the following statements about cortisol's cardiovascular effects is true?","options":[{"id":"a","text":"Cortisol lowers blood pressure by blocking catecholamines"},{"id":"b","text":"Cortisol enhances vascular responsiveness to catecholamines"},{"id":"c","text":"Cortisol directly increases heart rate"},{"id":"d","text":"Cortisol causes vasodilation in peripheral vessels"}],"answerId":"b","explanation":"Cortisol permits vascular catecholamine responsiveness, supporting blood pressure maintenance during stress.","kind":"trap","origin":"ai"},{"id":"hen1-cortisol-systemic-actions~ai-5","moduleId":"hen1-cortisol-systemic-actions","stem":"How does chronic cortisol excess contribute to osteoporosis?","options":[{"id":"a","text":"Increased calcium absorption"},{"id":"b","text":"Inhibition of osteoclast activity"},{"id":"c","text":"Increased protein catabolism and impaired collagen formation"},{"id":"d","text":"Stimulation of osteoblast proliferation"}],"answerId":"c","explanation":"Chronic cortisol excess leads to increased protein catabolism and impaired collagen formation, contributing to osteoporosis.","kind":"clinical","origin":"ai"},{"id":"hen1-cortisol-systemic-actions~ai-6","moduleId":"hen1-cortisol-systemic-actions","stem":"During exercise, which hormone's action is enhanced by cortisol to support energy metabolism?","options":[{"id":"a","text":"Insulin"},{"id":"b","text":"Glucagon"},{"id":"c","text":"Epinephrine"},{"id":"d","text":"Growth hormone"}],"answerId":"b","explanation":"Cortisol enhances glucagon's action, promoting gluconeogenesis and mobilization of energy stores during exercise.","kind":"integration","linkedModuleIds":["exercise-stress-fuel-integration"],"origin":"ai"},{"id":"hen1-cortisol-systemic-actions~ai-7","moduleId":"hen1-cortisol-systemic-actions","stem":"In adrenal insufficiency, which of the following would be expected in a patient’s laboratory findings?","options":[{"id":"a","text":"Hyperglycemia"},{"id":"b","text":"Hyponatremia"},{"id":"c","text":"Lymphocytopenia"},{"id":"d","text":"Increased cortisol levels"}],"answerId":"b","explanation":"Adrenal insufficiency leads to decreased cortisol production, resulting in hyponatremia due to impaired aldosterone secretion.","kind":"integration","linkedModuleIds":["adrenal-insufficiency"],"origin":"ai"}],"oral-mucosa-tongue-taste":[{"id":"oral-mucosa-tongue-taste~ai-0","moduleId":"oral-mucosa-tongue-taste","stem":"Which type of mucosa is found on the hard palate?","options":[{"id":"a","text":"Lining mucosa"},{"id":"b","text":"Masticatory mucosa"},{"id":"c","text":"Specialized mucosa"},{"id":"d","text":"Non-keratinized mucosa"}],"answerId":"b","explanation":"The hard palate is covered by masticatory mucosa, which is keratinized to resist abrasion during mastication.","kind":"recall","origin":"ai"},{"id":"oral-mucosa-tongue-taste~ai-1","moduleId":"oral-mucosa-tongue-taste","stem":"What is the primary function of filiform papillae on the tongue?","options":[{"id":"a","text":"Taste sensation"},{"id":"b","text":"Mechanical grip"},{"id":"c","text":"Secretion of saliva"},{"id":"d","text":"Absorption of nutrients"}],"answerId":"b","explanation":"Filiform papillae are primarily mechanical and help grip food rather than tasting.","kind":"trap","origin":"ai"},{"id":"oral-mucosa-tongue-taste~ai-2","moduleId":"oral-mucosa-tongue-taste","stem":"Which papillae contain taste buds and are located anterior to the sulcus terminalis?","options":[{"id":"a","text":"Fungiform papillae"},{"id":"b","text":"Foliate papillae"},{"id":"c","text":"Circumvallate papillae"},{"id":"d","text":"Filiform papillae"}],"answerId":"c","explanation":"Circumvallate papillae contain taste buds and are positioned anterior to the sulcus terminalis.","kind":"recall","origin":"ai"},{"id":"oral-mucosa-tongue-taste~ai-3","moduleId":"oral-mucosa-tongue-taste","stem":"What is the role of von Ebner glands associated with circumvallate papillae?","options":[{"id":"a","text":"Secretion of mucus"},{"id":"b","text":"Flushing of taste pores"},{"id":"c","text":"Production of keratin"},{"id":"d","text":"Absorption of tastants"}],"answerId":"b","explanation":"Von Ebner glands secrete serous fluid that flushes the trenches of circumvallate papillae, aiding in taste sensation.","kind":"mechanism","origin":"ai"},{"id":"oral-mucosa-tongue-taste~ai-4","moduleId":"oral-mucosa-tongue-taste","stem":"Which cells in taste buds are responsible for detecting tastants?","options":[{"id":"a","text":"Basal cells"},{"id":"b","text":"Supporting cells"},{"id":"c","text":"Receptor cells"},{"id":"d","text":"Serous cells"}],"answerId":"c","explanation":"Receptor cells in taste buds are responsible for detecting dissolved tastants.","kind":"recall","origin":"ai"},{"id":"oral-mucosa-tongue-taste~ai-5","moduleId":"oral-mucosa-tongue-taste","stem":"How does the keratinized stratified squamous epithelium on the gingiva function?","options":[{"id":"a","text":"Facilitates taste sensation"},{"id":"b","text":"Resists abrasion from mastication"},{"id":"c","text":"Promotes absorption of nutrients"},{"id":"d","text":"Secretes saliva"}],"answerId":"b","explanation":"Keratinized stratified squamous epithelium on the gingiva resists abrasion from chewing.","kind":"mechanism","origin":"ai"},{"id":"oral-mucosa-tongue-taste~ai-6","moduleId":"oral-mucosa-tongue-taste","stem":"How do taste pathways integrate with olfactory pathways in sensory perception?","options":[{"id":"a","text":"Both rely on mechanical stimulation"},{"id":"b","text":"Both involve similar receptor cells"},{"id":"c","text":"Both are processed in the same brain region"},{"id":"d","text":"Both contribute to flavor perception"}],"answerId":"d","explanation":"Taste and olfactory pathways both contribute to the overall perception of flavor, integrating sensory information.","kind":"integration","linkedModuleIds":["gustatory-olfactory-pathways"],"origin":"ai"},{"id":"oral-mucosa-tongue-taste~ai-7","moduleId":"oral-mucosa-tongue-taste","stem":"What histological feature distinguishes the masticatory mucosa from lining mucosa?","options":[{"id":"a","text":"Presence of taste buds"},{"id":"b","text":"Keratinization of epithelium"},{"id":"c","text":"Thickness of the epithelium"},{"id":"d","text":"Type of connective tissue"}],"answerId":"b","explanation":"Masticatory mucosa is characterized by keratinization, unlike the non-keratinized lining mucosa.","kind":"integration","linkedModuleIds":["gi-wall-esophagus-histology"],"origin":"ai"}],"hen1-adrenal-androgens":[{"id":"hen1-adrenal-androgens~ai-0","moduleId":"hen1-adrenal-androgens","stem":"Which hormone is primarily produced by the zona reticularis of the adrenal gland?","options":[{"id":"a","text":"Cortisol"},{"id":"b","text":"Aldosterone"},{"id":"c","text":"DHEA"},{"id":"d","text":"Epinephrine"}],"answerId":"c","explanation":"The zona reticularis primarily produces adrenal androgens such as DHEA.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-androgens~ai-1","moduleId":"hen1-adrenal-androgens","stem":"What is the primary action of DHEAS in the body?","options":[{"id":"a","text":"Directly stimulates spermatogenesis"},{"id":"b","text":"Serves as a precursor for sex steroids"},{"id":"c","text":"Increases blood pressure"},{"id":"d","text":"Regulates electrolyte balance"}],"answerId":"b","explanation":"DHEAS serves as a peripheral precursor for testosterone and estrogens.","kind":"mechanism","origin":"ai"},{"id":"hen1-adrenal-androgens~ai-2","moduleId":"hen1-adrenal-androgens","stem":"A 14-year-old girl presents with rapid virilization and elevated DHEAS levels. What is the most likely diagnosis?","options":[{"id":"a","text":"Polycystic ovary syndrome"},{"id":"b","text":"Congenital adrenal hyperplasia"},{"id":"c","text":"Ovarian tumor"},{"id":"d","text":"Cushing's syndrome"}],"answerId":"b","explanation":"Marked androgen excess in a female suggests congenital adrenal hyperplasia or an androgen-secreting adrenal lesion.","kind":"clinical","origin":"ai"},{"id":"hen1-adrenal-androgens~ai-3","moduleId":"hen1-adrenal-androgens","stem":"Which of the following is a common clinical finding in adrenarche?","options":[{"id":"a","text":"Increased cortisol levels"},{"id":"b","text":"Development of pubic hair"},{"id":"c","text":"Elevated aldosterone"},{"id":"d","text":"Decreased testosterone levels"}],"answerId":"b","explanation":"Adrenarche is characterized by the maturation of the zona reticularis, leading to increased adrenal androgen output and development of pubic hair.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-androgens~ai-4","moduleId":"hen1-adrenal-androgens","stem":"What is the primary source of DHEAS in the body?","options":[{"id":"a","text":"Ovaries"},{"id":"b","text":"Adrenal glands"},{"id":"c","text":"Testes"},{"id":"d","text":"Pituitary gland"}],"answerId":"b","explanation":"DHEAS is predominantly produced by the adrenal glands, making it useful for localizing androgen excess to adrenal tissue.","kind":"trap","origin":"ai"},{"id":"hen1-adrenal-androgens~ai-5","moduleId":"hen1-adrenal-androgens","stem":"How do adrenal androgens contribute to sexual development in females?","options":[{"id":"a","text":"Directly stimulate ovulation"},{"id":"b","text":"Increase libido and body hair growth"},{"id":"c","text":"Enhance estrogen production"},{"id":"d","text":"Inhibit testosterone synthesis"}],"answerId":"b","explanation":"Adrenal androgens contribute to libido and the development of pubic and axillary hair in females.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-androgens~ai-6","moduleId":"hen1-adrenal-androgens","stem":"Which adrenal hormone's synthesis is closely related to the action of ACTH?","options":[{"id":"a","text":"Cortisol"},{"id":"b","text":"DHEA"},{"id":"c","text":"Aldosterone"},{"id":"d","text":"Epinephrine"}],"answerId":"b","explanation":"ACTH stimulates the zona reticularis to produce DHEA and other adrenal androgens.","kind":"integration","linkedModuleIds":["hen1-adrenal-catecholamines"],"origin":"ai"},{"id":"hen1-adrenal-androgens~ai-7","moduleId":"hen1-adrenal-androgens","stem":"What is the relationship between adrenal androgens and catecholamines?","options":[{"id":"a","text":"Both are produced in the zona glomerulosa"},{"id":"b","text":"Both are regulated by ACTH"},{"id":"c","text":"Both are secreted in response to stress"},{"id":"d","text":"Both are derived from cholesterol"}],"answerId":"c","explanation":"Both adrenal androgens and catecholamines are secreted in response to stress, but they originate from different zones of the adrenal gland.","kind":"integration","linkedModuleIds":["hen1-adrenal-catecholamines"],"origin":"ai"}],"hen1-adrenal-cortex-histology-zones":[{"id":"hen1-adrenal-cortex-histology-zones~ai-0","moduleId":"hen1-adrenal-cortex-histology-zones","stem":"Which zone of the adrenal cortex is primarily responsible for aldosterone production?","options":[{"id":"a","text":"Zona glomerulosa"},{"id":"b","text":"Zona fasciculata"},{"id":"c","text":"Zona reticularis"},{"id":"d","text":"Medulla"}],"answerId":"a","explanation":"The zona glomerulosa produces aldosterone, primarily regulated by angiotensin II and potassium levels.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-cortex-histology-zones~ai-1","moduleId":"hen1-adrenal-cortex-histology-zones","stem":"What is the primary hormone produced by the zona fasciculata?","options":[{"id":"a","text":"Aldosterone"},{"id":"b","text":"Cortisol"},{"id":"c","text":"DHEA"},{"id":"d","text":"Epinephrine"}],"answerId":"b","explanation":"The zona fasciculata is known for producing cortisol, which is involved in stress response and metabolism.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-cortex-histology-zones~ai-2","moduleId":"hen1-adrenal-cortex-histology-zones","stem":"Which histological feature is characteristic of the zona fasciculata?","options":[{"id":"a","text":"Thin subcapsular cell clusters"},{"id":"b","text":"Vacuolated pale cells"},{"id":"c","text":"Anastomosing eosinophilic cells"},{"id":"d","text":"Chromaffin cells"}],"answerId":"b","explanation":"The zona fasciculata contains vacuolated pale cells, which are lipid-rich spongiocytes supporting steroid synthesis.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-cortex-histology-zones~ai-3","moduleId":"hen1-adrenal-cortex-histology-zones","stem":"Which statement about the zona glomerulosa is correct?","options":[{"id":"a","text":"It produces cortisol under ACTH control."},{"id":"b","text":"It lacks CYP17 activity."},{"id":"c","text":"It is the broadest zone of the adrenal cortex."},{"id":"d","text":"It produces adrenal androgens."}],"answerId":"b","explanation":"The zona glomerulosa lacks CYP17 activity and primarily produces aldosterone, not cortisol.","kind":"trap","origin":"ai"},{"id":"hen1-adrenal-cortex-histology-zones~ai-4","moduleId":"hen1-adrenal-cortex-histology-zones","stem":"What is the primary function of the zona reticularis?","options":[{"id":"a","text":"Mineralocorticoid production"},{"id":"b","text":"Glucocorticoid production"},{"id":"c","text":"Adrenal androgen production"},{"id":"d","text":"Catecholamine production"}],"answerId":"c","explanation":"The zona reticularis is responsible for producing adrenal androgens, such as DHEA.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-cortex-histology-zones~ai-5","moduleId":"hen1-adrenal-cortex-histology-zones","stem":"How does the adrenal cortex's enzyme expression change from the capsule to the medulla?","options":[{"id":"a","text":"Increases in CYP17 activity"},{"id":"b","text":"Decreases in aldosterone production"},{"id":"c","text":"Increases in glucocorticoid production"},{"id":"d","text":"Decreases in mineralocorticoid production"}],"answerId":"a","explanation":"Cortical enzyme expression changes from the capsule to the medulla, with increasing CYP17 activity as you move inward.","kind":"mechanism","origin":"ai"},{"id":"hen1-adrenal-cortex-histology-zones~ai-6","moduleId":"hen1-adrenal-cortex-histology-zones","stem":"How does the adrenal cortex relate to nucleotide metabolism?","options":[{"id":"a","text":"Cortisol regulates nucleotide synthesis."},{"id":"b","text":"Aldosterone affects nucleotide transport."},{"id":"c","text":"Adrenal androgens influence nucleotide degradation."},{"id":"d","text":"Zona fasciculata produces nucleotides."}],"answerId":"a","explanation":"Cortisol, produced by the zona fasciculata, plays a role in regulating various metabolic processes, including nucleotide synthesis.","kind":"integration","linkedModuleIds":["nucleotides-structure-roles"],"origin":"ai"},{"id":"hen1-adrenal-cortex-histology-zones~ai-7","moduleId":"hen1-adrenal-cortex-histology-zones","stem":"What developmental aspect of the adrenal cortex is crucial for its function?","options":[{"id":"a","text":"Formation of the medulla"},{"id":"b","text":"Differentiation of the zona glomerulosa"},{"id":"c","text":"Development of adrenal vasculature"},{"id":"d","text":"Regulation of cortisol levels"}],"answerId":"b","explanation":"The differentiation of the zona glomerulosa is crucial for the adrenal cortex's ability to produce aldosterone and respond to regulatory signals.","kind":"integration","linkedModuleIds":["hen1-adrenal-development"],"origin":"ai"}],"hen1-aldosterone-raas":[{"id":"hen1-aldosterone-raas~ai-0","moduleId":"hen1-aldosterone-raas","stem":"What is the primary stimulus for aldosterone secretion?","options":[{"id":"a","text":"ACTH"},{"id":"b","text":"Angiotensin II"},{"id":"c","text":"Cortisol"},{"id":"d","text":"Atrial natriuretic peptide"}],"answerId":"b","explanation":"Angiotensin II and high plasma potassium are the major stimulators of aldosterone secretion.","kind":"recall","origin":"ai"},{"id":"hen1-aldosterone-raas~ai-1","moduleId":"hen1-aldosterone-raas","stem":"Which mechanism describes how aldosterone increases sodium reabsorption in the kidney?","options":[{"id":"a","text":"Inhibition of ENaC"},{"id":"b","text":"Activation of Na⁺/K⁺-ATPase"},{"id":"c","text":"Inhibition of K⁺ secretion"},{"id":"d","text":"Decreased H⁺ secretion"}],"answerId":"b","explanation":"Aldosterone binds to mineralocorticoid receptors, leading to increased activity of ENaC and Na⁺/K⁺-ATPase, enhancing sodium reabsorption.","kind":"mechanism","origin":"ai"},{"id":"hen1-aldosterone-raas~ai-2","moduleId":"hen1-aldosterone-raas","stem":"A patient presents with hypertension, hypokalemia, and metabolic alkalosis. Which condition is most likely?","options":[{"id":"a","text":"Primary adrenal insufficiency"},{"id":"b","text":"Cushing's syndrome"},{"id":"c","text":"Primary hyperaldosteronism"},{"id":"d","text":"Secondary hyperaldosteronism"}],"answerId":"c","explanation":"These findings are characteristic of primary hyperaldosteronism due to excess aldosterone action.","kind":"clinical","origin":"ai"},{"id":"hen1-aldosterone-raas~ai-3","moduleId":"hen1-aldosterone-raas","stem":"Which statement about aldosterone regulation is FALSE?","options":[{"id":"a","text":"Angiotensin II is a major regulator."},{"id":"b","text":"High plasma K⁺ stimulates aldosterone secretion."},{"id":"c","text":"ACTH is the principal long-term regulator."},{"id":"d","text":"Aldosterone secretion is influenced by volume status."}],"answerId":"c","explanation":"ACTH has only a minor transient role in aldosterone regulation; angiotensin II and potassium are the dominant regulators.","kind":"trap","origin":"ai"},{"id":"hen1-aldosterone-raas~ai-4","moduleId":"hen1-aldosterone-raas","stem":"What is the role of 11β-HSD2 in aldosterone action?","options":[{"id":"a","text":"Converts cortisone to cortisol"},{"id":"b","text":"Inactivates aldosterone"},{"id":"c","text":"Converts cortisol to cortisone"},{"id":"d","text":"Activates mineralocorticoid receptors"}],"answerId":"c","explanation":"11β-HSD2 converts cortisol to cortisone, protecting the mineralocorticoid receptor from cortisol's effects.","kind":"mechanism","origin":"ai"},{"id":"hen1-aldosterone-raas~ai-5","moduleId":"hen1-aldosterone-raas","stem":"How does primary hyperaldosteronism affect potassium levels?","options":[{"id":"a","text":"Increases potassium levels"},{"id":"b","text":"Decreases potassium levels"},{"id":"c","text":"No effect on potassium levels"},{"id":"d","text":"Causes potassium retention"}],"answerId":"b","explanation":"Primary hyperaldosteronism leads to increased potassium secretion, resulting in hypokalemia.","kind":"clinical","origin":"ai"},{"id":"hen1-aldosterone-raas~ai-6","moduleId":"hen1-aldosterone-raas","stem":"How does aldosterone interact with the RAAS in the context of blood pressure regulation?","options":[{"id":"a","text":"Inhibits renin release"},{"id":"b","text":"Promotes sodium retention"},{"id":"c","text":"Decreases angiotensin II levels"},{"id":"d","text":"Increases blood volume without effect on pressure"}],"answerId":"b","explanation":"Aldosterone promotes sodium retention, which increases blood volume and contributes to blood pressure regulation.","kind":"integration","linkedModuleIds":["long-term-bp-raas"],"origin":"ai"},{"id":"hen1-aldosterone-raas~ai-7","moduleId":"hen1-aldosterone-raas","stem":"In the context of adrenal insufficiency, how does aldosterone deficiency affect electrolyte balance?","options":[{"id":"a","text":"Causes hyperkalemia"},{"id":"b","text":"Causes hypokalemia"},{"id":"c","text":"No effect on electrolytes"},{"id":"d","text":"Causes hyponatremia"}],"answerId":"a","explanation":"Aldosterone deficiency leads to decreased potassium secretion, resulting in hyperkalemia.","kind":"integration","linkedModuleIds":["adrenal-insufficiency"],"origin":"ai"}],"hen1-adrenal-development":[{"id":"hen1-adrenal-development~ai-0","moduleId":"hen1-adrenal-development","stem":"Which embryonic origin contributes to the adrenal cortex?","options":[{"id":"a","text":"Neural crest"},{"id":"b","text":"Coelomic mesothelium"},{"id":"c","text":"Endoderm"},{"id":"d","text":"Ectoderm"}],"answerId":"b","explanation":"The adrenal cortex derives from coelomic mesothelium/mesoderm, while the medulla is derived from neural crest.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-development~ai-1","moduleId":"hen1-adrenal-development","stem":"What is the primary function of the fetal zone of the adrenal cortex?","options":[{"id":"a","text":"Production of cortisol"},{"id":"b","text":"Synthesis of aldosterone"},{"id":"c","text":"Production of androgen precursors"},{"id":"d","text":"Secretion of catecholamines"}],"answerId":"c","explanation":"The fetal zone produces androgen precursors that are used by the placenta for estrogen synthesis.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-development~ai-2","moduleId":"hen1-adrenal-development","stem":"After birth, which zone of the adrenal cortex matures first?","options":[{"id":"a","text":"Zona reticularis"},{"id":"b","text":"Zona fasciculata"},{"id":"c","text":"Zona glomerulosa"},{"id":"d","text":"Fetal zone"}],"answerId":"c","explanation":"The adult zona glomerulosa and fasciculata mature first after the fetal zone involutes.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-development~ai-3","moduleId":"hen1-adrenal-development","stem":"What is the mechanism of adrenal medullary chromaffin cell development?","options":[{"id":"a","text":"Mesodermal steroidogenic cells envelop neural crest"},{"id":"b","text":"Neural crest cells migrate to the cortex"},{"id":"c","text":"Mesodermal cells differentiate into chromaffin cells"},{"id":"d","text":"Neural crest-derived cells invade mesoderm"}],"answerId":"a","explanation":"Mesodermal steroidogenic cells envelop migrating neural-crest chromaffin cells during development.","kind":"mechanism","origin":"ai"},{"id":"hen1-adrenal-development~ai-4","moduleId":"hen1-adrenal-development","stem":"A patient presents with a large fetal adrenal cortex. What is the most likely consequence of this finding?","options":[{"id":"a","text":"Increased cortisol production"},{"id":"b","text":"Increased DHEA-S for estrogen synthesis"},{"id":"c","text":"Increased catecholamine secretion"},{"id":"d","text":"Decreased aldosterone levels"}],"answerId":"b","explanation":"A large fetal adrenal cortex indicates increased production of DHEA-S, which is a precursor for placental estrogen synthesis.","kind":"clinical","origin":"ai"},{"id":"hen1-adrenal-development~ai-5","moduleId":"hen1-adrenal-development","stem":"Which statement about adrenal gland development is true?","options":[{"id":"a","text":"The entire adrenal gland derives from neural crest"},{"id":"b","text":"Only the medulla is neural crest-derived"},{"id":"c","text":"Cortex and medulla develop from the same embryonic layer"},{"id":"d","text":"Fetal zone persists into adulthood"}],"answerId":"b","explanation":"Only the medulla is derived from neural crest, while the cortex is mesodermal, highlighting the dual embryonic origin of the adrenal gland.","kind":"trap","origin":"ai"},{"id":"hen1-adrenal-development~ai-6","moduleId":"hen1-adrenal-development","stem":"How does the development of the adrenal medulla relate to neural crest cells?","options":[{"id":"a","text":"Cortex develops from neural crest"},{"id":"b","text":"Medulla is derived from mesoderm"},{"id":"c","text":"Neural crest cells migrate to form medullary chromaffin cells"},{"id":"d","text":"Cortex and medulla develop simultaneously from the same layer"}],"answerId":"c","explanation":"Medullary chromaffin cells are derived from migrating neural crest cells, illustrating their role in adrenal development.","kind":"integration","linkedModuleIds":["notochord-neurulation-neural-crest"],"origin":"ai"},{"id":"hen1-adrenal-development~ai-7","moduleId":"hen1-adrenal-development","stem":"Which adrenal structure is primarily responsible for producing androgens during fetal development?","options":[{"id":"a","text":"Zona glomerulosa"},{"id":"b","text":"Zona fasciculata"},{"id":"c","text":"Fetal zone"},{"id":"d","text":"Medulla"}],"answerId":"c","explanation":"The fetal zone of the adrenal cortex is responsible for producing androgens during fetal development.","kind":"integration","linkedModuleIds":["hen1-adrenal-cortex-histology-zones"],"origin":"ai"}],"hen1-adrenal-catecholamines":[{"id":"hen1-adrenal-catecholamines~ai-0","moduleId":"hen1-adrenal-catecholamines","stem":"What is the rate-limiting enzyme in catecholamine synthesis?","options":[{"id":"a","text":"DOPA decarboxylase"},{"id":"b","text":"Tyrosine hydroxylase"},{"id":"c","text":"Phenylethanolamine N-methyltransferase"},{"id":"d","text":"Catechol-O-methyltransferase"}],"answerId":"b","explanation":"Tyrosine hydroxylase is the rate-limiting enzyme that catalyzes the conversion of tyrosine to DOPA in catecholamine synthesis.","kind":"recall","origin":"ai"},{"id":"hen1-adrenal-catecholamines~ai-1","moduleId":"hen1-adrenal-catecholamines","stem":"Which receptor type is primarily responsible for vasoconstriction in response to catecholamines?","options":[{"id":"a","text":"Beta-1"},{"id":"b","text":"Beta-2"},{"id":"c","text":"Alpha-1"},{"id":"d","text":"Alpha-2"}],"answerId":"c","explanation":"Alpha-1 adrenergic receptors mediate vasoconstriction when activated by catecholamines.","kind":"mechanism","origin":"ai"},{"id":"hen1-adrenal-catecholamines~ai-2","moduleId":"hen1-adrenal-catecholamines","stem":"A patient presents with episodic headache, sweating, and palpitations. Which mechanism explains these symptoms?","options":[{"id":"a","text":"Increased insulin secretion"},{"id":"b","text":"Catecholamine surge"},{"id":"c","text":"Decreased blood glucose"},{"id":"d","text":"Vasodilation"}],"answerId":"b","explanation":"These symptoms are due to catecholamine surges activating alpha- and beta-adrenergic systems.","kind":"clinical","origin":"ai"},{"id":"hen1-adrenal-catecholamines~ai-3","moduleId":"hen1-adrenal-catecholamines","stem":"In a patient with pheochromocytoma, what is the correct order of pharmacologic intervention for managing hypertension?","options":[{"id":"a","text":"Start beta blocker, then alpha blocker"},{"id":"b","text":"Start alpha blocker, then beta blocker"},{"id":"c","text":"Start calcium channel blocker"},{"id":"d","text":"Start diuretic"}],"answerId":"b","explanation":"Establishing alpha blockade before beta blockade prevents unopposed alpha activity, which can worsen hypertension.","kind":"trap","origin":"ai"},{"id":"hen1-adrenal-catecholamines~ai-4","moduleId":"hen1-adrenal-catecholamines","stem":"Which metabolic change is expected during a catecholamine surge?","options":[{"id":"a","text":"Increased insulin sensitivity"},{"id":"b","text":"Decreased gluconeogenesis"},{"id":"c","text":"Increased glycogenolysis"},{"id":"d","text":"Decreased heart rate"}],"answerId":"c","explanation":"Catecholamine surges lead to increased glycogenolysis and gluconeogenesis, resulting in hyperglycemia.","kind":"clinical","origin":"ai"},{"id":"hen1-adrenal-catecholamines~ai-5","moduleId":"hen1-adrenal-catecholamines","stem":"How does cortisol influence catecholamine synthesis in the adrenal medulla?","options":[{"id":"a","text":"Inhibits PNMT"},{"id":"b","text":"Stimulates DOPA production"},{"id":"c","text":"Induces PNMT activity"},{"id":"d","text":"Decreases tyrosine availability"}],"answerId":"c","explanation":"Cortisol induces the activity of phenylethanolamine N-methyltransferase (PNMT), enhancing epinephrine synthesis.","kind":"mechanism","origin":"ai"},{"id":"hen1-adrenal-catecholamines~ai-6","moduleId":"hen1-adrenal-catecholamines","stem":"Which adrenergic drug class would be most effective in treating a patient with anaphylaxis?","options":[{"id":"a","text":"Alpha-1 agonists"},{"id":"b","text":"Beta-1 agonists"},{"id":"c","text":"Beta-2 agonists"},{"id":"d","text":"Mixed alpha and beta agonists"}],"answerId":"d","explanation":"Mixed alpha and beta agonists, such as epinephrine, are effective in treating anaphylaxis due to their vasoconstrictive and bronchodilatory effects.","kind":"integration","linkedModuleIds":["adrenergic-drugs"],"origin":"ai"},{"id":"hen1-adrenal-catecholamines~ai-7","moduleId":"hen1-adrenal-catecholamines","stem":"In a patient with pheochromocytoma, which diagnostic marker is most useful for confirming the diagnosis?","options":[{"id":"a","text":"Plasma glucose"},{"id":"b","text":"Urinary catecholamines"},{"id":"c","text":"Serum cortisol"},{"id":"d","text":"Plasma metanephrines"}],"answerId":"d","explanation":"Plasma metanephrines are stable diagnostic markers that indicate catecholamine excess, aiding in the diagnosis of pheochromocytoma.","kind":"integration","linkedModuleIds":["pheochromocytoma-paraganglioma"],"origin":"ai"}],"stomach-glands-histology":[{"id":"stomach-glands-histology~ai-0","moduleId":"stomach-glands-histology","stem":"Which cell type in the gastric fundus is responsible for secreting hydrochloric acid?","options":[{"id":"a","text":"Parietal cells"},{"id":"b","text":"Chief cells"},{"id":"c","text":"Mucous neck cells"},{"id":"d","text":"G cells"}],"answerId":"a","explanation":"Parietal cells secrete hydrochloric acid and intrinsic factor, essential for digestion and vitamin B12 absorption.","kind":"recall","origin":"ai"},{"id":"stomach-glands-histology~ai-1","moduleId":"stomach-glands-histology","stem":"What is the primary function of chief cells in the gastric glands?","options":[{"id":"a","text":"Secretion of HCl"},{"id":"b","text":"Secretion of pepsinogen"},{"id":"c","text":"Secretion of gastrin"},{"id":"d","text":"Secretion of mucus"}],"answerId":"b","explanation":"Chief cells primarily secrete pepsinogen, which is activated to pepsin in the acidic environment of the stomach.","kind":"recall","origin":"ai"},{"id":"stomach-glands-histology~ai-2","moduleId":"stomach-glands-histology","stem":"What histological feature distinguishes the pyloric region of the stomach?","options":[{"id":"a","text":"Short pits and long glands"},{"id":"b","text":"Deep pits and mucous glands"},{"id":"c","text":"Absence of gastric pits"},{"id":"d","text":"Presence of villi"}],"answerId":"b","explanation":"The pyloric region has deeper pits and predominantly mucous glands, which help protect the stomach lining.","kind":"recall","origin":"ai"},{"id":"stomach-glands-histology~ai-3","moduleId":"stomach-glands-histology","stem":"Which finding is characteristic of parietal cells in gastric histology?","options":[{"id":"a","text":"Basophilic cytoplasm with granules"},{"id":"b","text":"Eosinophilic cytoplasm with a central nucleus"},{"id":"c","text":"Pseudostratified epithelium"},{"id":"d","text":"Presence of villi"}],"answerId":"b","explanation":"Parietal cells are large and eosinophilic due to their abundant mitochondria, which are involved in acid production.","kind":"recall","origin":"ai"},{"id":"stomach-glands-histology~ai-4","moduleId":"stomach-glands-histology","stem":"Which statement about gastric rugae is correct?","options":[{"id":"a","text":"They are microscopic villi."},{"id":"b","text":"They are gross folds involving mucosa/submucosa."},{"id":"c","text":"They are found only in the pyloric region."},{"id":"d","text":"They increase surface area for absorption."}],"answerId":"b","explanation":"Rugae are large folds of the gastric mucosa and submucosa that allow for expansion of the stomach, not villi.","kind":"trap","origin":"ai"},{"id":"stomach-glands-histology~ai-5","moduleId":"stomach-glands-histology","stem":"How do surface mucous cells protect the gastric epithelium?","options":[{"id":"a","text":"By secreting pepsinogen"},{"id":"b","text":"By producing a bicarbonate-rich gel"},{"id":"c","text":"By secreting hydrochloric acid"},{"id":"d","text":"By forming gastric pits"}],"answerId":"b","explanation":"Surface mucous cells secrete a bicarbonate-rich gel that forms a protective barrier against gastric acid.","kind":"mechanism","origin":"ai"},{"id":"stomach-glands-histology~ai-6","moduleId":"stomach-glands-histology","stem":"How does the histology of the stomach relate to the esophagus in terms of epithelial type?","options":[{"id":"a","text":"Both have stratified squamous epithelium."},{"id":"b","text":"Both have simple columnar epithelium."},{"id":"c","text":"Stomach has simple cuboidal, esophagus has simple columnar."},{"id":"d","text":"Stomach has stratified cuboidal, esophagus has simple squamous."}],"answerId":"b","explanation":"The stomach has simple columnar epithelium, while the esophagus has stratified squamous epithelium to protect against abrasion.","kind":"integration","linkedModuleIds":["gi-wall-esophagus-histology"],"origin":"ai"},{"id":"stomach-glands-histology~ai-7","moduleId":"stomach-glands-histology","stem":"What is the primary difference in glandular structure between the stomach and the small intestine?","options":[{"id":"a","text":"Stomach has villi, small intestine does not."},{"id":"b","text":"Small intestine has crypts, stomach has gastric pits."},{"id":"c","text":"Both have similar glandular structures."},{"id":"d","text":"Stomach has deeper pits than small intestine."}],"answerId":"b","explanation":"The small intestine has crypts of Lieberkühn while the stomach has gastric pits leading to gastric glands.","kind":"integration","linkedModuleIds":["intestinal-anal-histology"],"origin":"ai"}],"intestinal-anal-histology":[{"id":"intestinal-anal-histology~ai-0","moduleId":"intestinal-anal-histology","stem":"Which structure is primarily responsible for increasing the surface area of the small intestine?","options":[{"id":"a","text":"Villi"},{"id":"b","text":"Crypts"},{"id":"c","text":"Brunner glands"},{"id":"d","text":"Taeniae coli"}],"answerId":"a","explanation":"Villi are finger-like projections that increase the surface area for absorption in the small intestine.","kind":"recall","origin":"ai"},{"id":"intestinal-anal-histology~ai-1","moduleId":"intestinal-anal-histology","stem":"What is the primary function of Brunner glands found in the duodenum?","options":[{"id":"a","text":"Secreting digestive enzymes"},{"id":"b","text":"Neutralizing gastric acid"},{"id":"c","text":"Producing mucus"},{"id":"d","text":"Absorbing nutrients"}],"answerId":"b","explanation":"Brunner glands secrete alkaline mucus to neutralize gastric acid entering the duodenum.","kind":"mechanism","origin":"ai"},{"id":"intestinal-anal-histology~ai-2","moduleId":"intestinal-anal-histology","stem":"What is a key histological feature distinguishing the ileum from the jejunum?","options":[{"id":"a","text":"Tall villi"},{"id":"b","text":"Brunner glands"},{"id":"c","text":"Aggregated Peyer patches"},{"id":"d","text":"Absence of goblet cells"}],"answerId":"c","explanation":"The ileum is characterized by the presence of aggregated Peyer patches, which are absent in the jejunum.","kind":"recall","origin":"ai"},{"id":"intestinal-anal-histology~ai-3","moduleId":"intestinal-anal-histology","stem":"In which part of the gastrointestinal tract would you expect to find numerous goblet cells?","options":[{"id":"a","text":"Esophagus"},{"id":"b","text":"Stomach"},{"id":"c","text":"Colon"},{"id":"d","text":"Duodenum"}],"answerId":"c","explanation":"The colon contains abundant goblet cells that secrete mucus to facilitate stool passage.","kind":"recall","origin":"ai"},{"id":"intestinal-anal-histology~ai-4","moduleId":"intestinal-anal-histology","stem":"Where are Paneth cells located within the intestinal crypts?","options":[{"id":"a","text":"At the villus tips"},{"id":"b","text":"At the crypt bases"},{"id":"c","text":"In the lamina propria"},{"id":"d","text":"In the submucosa"}],"answerId":"b","explanation":"Paneth cells are located at the bases of the crypts and release antimicrobial substances.","kind":"trap","origin":"ai"},{"id":"intestinal-anal-histology~ai-5","moduleId":"intestinal-anal-histology","stem":"How does the histological structure of the anal canal differ from that of the colon?","options":[{"id":"a","text":"Presence of villi"},{"id":"b","text":"Stratified squamous epithelium"},{"id":"c","text":"Brunner glands"},{"id":"d","text":"Absence of crypts"}],"answerId":"b","explanation":"The anal canal transitions to stratified squamous epithelium, unlike the colon which has simple columnar epithelium.","kind":"clinical","origin":"ai"},{"id":"intestinal-anal-histology~ai-6","moduleId":"intestinal-anal-histology","stem":"How does the histology of the appendix support its role in mucosal immunity?","options":[{"id":"a","text":"Presence of Brunner glands"},{"id":"b","text":"Numerous lymphoid follicles"},{"id":"c","text":"Absence of goblet cells"},{"id":"d","text":"Tall villi"}],"answerId":"b","explanation":"The appendix contains numerous lymphoid follicles that contribute to its role in mucosal immunity.","kind":"mechanism","origin":"ai"},{"id":"intestinal-anal-histology~ai-7","moduleId":"intestinal-anal-histology","stem":"Which histological feature connects the small intestine module to the large intestine module?","options":[{"id":"a","text":"Absence of villi"},{"id":"b","text":"Presence of Paneth cells"},{"id":"c","text":"Brunner glands"},{"id":"d","text":"Shorter crypts"}],"answerId":"a","explanation":"The absence of villi is a key feature that connects the histology of the small intestine to that of the large intestine.","kind":"integration","linkedModuleIds":["small-large-intestine"],"origin":"ai"},{"id":"intestinal-anal-histology~ai-8","moduleId":"intestinal-anal-histology","stem":"What histological change occurs from the small intestine to the colon?","options":[{"id":"a","text":"Increase in villi height"},{"id":"b","text":"Decrease in goblet cells"},{"id":"c","text":"Increase in crypt depth"},{"id":"d","text":"Transition from simple columnar to stratified squamous epithelium"}],"answerId":"c","explanation":"The colon has deeper crypts compared to the small intestine, which is characterized by villi.","kind":"integration","linkedModuleIds":["small-large-intestine"],"origin":"ai"}],"mastication-mechanics-reflex":[{"id":"mastication-mechanics-reflex~ai-0","moduleId":"mastication-mechanics-reflex","stem":"Which muscle is primarily responsible for elevating the mandible during mastication?","options":[{"id":"a","text":"Lateral pterygoid"},{"id":"b","text":"Masseter"},{"id":"c","text":"Temporalis"},{"id":"d","text":"Medial pterygoid"}],"answerId":"b","explanation":"The masseter is the primary muscle responsible for elevating the mandible during chewing.","kind":"recall","origin":"ai"},{"id":"mastication-mechanics-reflex~ai-1","moduleId":"mastication-mechanics-reflex","stem":"What is the primary mechanism by which the chewing reflex operates?","options":[{"id":"a","text":"Cortical control of jaw muscles"},{"id":"b","text":"Rhythmic jaw opening and closing"},{"id":"c","text":"Inhibition of lateral pterygoid"},{"id":"d","text":"Stretch reflex of the tongue"}],"answerId":"b","explanation":"The chewing reflex is characterized by rhythmic jaw opening and closing in response to bolus contact.","kind":"mechanism","origin":"ai"},{"id":"mastication-mechanics-reflex~ai-2","moduleId":"mastication-mechanics-reflex","stem":"A patient presents with weakness in jaw closure and deviation of the jaw to the right. Which cranial nerve is likely affected?","options":[{"id":"a","text":"CN VII"},{"id":"b","text":"CN V3"},{"id":"c","text":"CN IX"},{"id":"d","text":"CN XII"}],"answerId":"b","explanation":"Weakness in jaw closure with deviation indicates dysfunction of the motor branch of CN V3, which innervates the muscles of mastication.","kind":"clinical","origin":"ai"},{"id":"mastication-mechanics-reflex~ai-3","moduleId":"mastication-mechanics-reflex","stem":"Which of the following statements about the lateral pterygoid muscle is true?","options":[{"id":"a","text":"It is a powerful jaw closer."},{"id":"b","text":"It assists in jaw opening."},{"id":"c","text":"It elevates the mandible."},{"id":"d","text":"It primarily retracts the jaw."}],"answerId":"b","explanation":"The lateral pterygoid muscle assists in opening the jaw and protruding the mandible, rather than closing it.","kind":"trap","origin":"ai"},{"id":"mastication-mechanics-reflex~ai-4","moduleId":"mastication-mechanics-reflex","stem":"What clinical finding would suggest poor bolus formation during mastication?","options":[{"id":"a","text":"Weakness in jaw closure"},{"id":"b","text":"Dry mouth"},{"id":"c","text":"Increased salivation"},{"id":"d","text":"Jaw deviation"}],"answerId":"b","explanation":"Poor bolus formation is often associated with dry mouth, which impairs lubrication necessary for efficient chewing.","kind":"recall","origin":"ai"},{"id":"mastication-mechanics-reflex~ai-5","moduleId":"mastication-mechanics-reflex","stem":"How does mastication relate to swallowing phases in terms of reflex control?","options":[{"id":"a","text":"Both rely on the same cranial nerves"},{"id":"b","text":"Both involve rhythmic muscle contractions"},{"id":"c","text":"Both are voluntary processes"},{"id":"d","text":"Both are controlled by the same brain centers"}],"answerId":"b","explanation":"Mastication and swallowing both involve rhythmic muscle contractions that are essential for processing food and moving it through the digestive tract.","kind":"integration","linkedModuleIds":["swallowing-phases-reflex"],"origin":"ai"},{"id":"mastication-mechanics-reflex~ai-6","moduleId":"mastication-mechanics-reflex","stem":"Which muscle's dysfunction can lead to impaired jaw opening and subsequently affect swallowing?","options":[{"id":"a","text":"Masseter"},{"id":"b","text":"Medial pterygoid"},{"id":"c","text":"Lateral pterygoid"},{"id":"d","text":"Temporalis"}],"answerId":"c","explanation":"Dysfunction of the lateral pterygoid can impair jaw opening, which is critical for the swallowing process.","kind":"integration","linkedModuleIds":["swallowing-phases-reflex"],"origin":"ai"}],"liver-acinus-gallbladder":[{"id":"liver-acinus-gallbladder~ai-0","moduleId":"liver-acinus-gallbladder","stem":"Which zone of the hepatic acinus is most susceptible to ischemia?","options":[{"id":"a","text":"Zone 1"},{"id":"b","text":"Zone 2"},{"id":"c","text":"Zone 3"},{"id":"d","text":"Zone 4"}],"answerId":"c","explanation":"Zone 3 is the most distal from the portal triad and has the lowest oxygen tension, making it vulnerable to ischemic damage.","kind":"recall","origin":"ai"},{"id":"liver-acinus-gallbladder~ai-1","moduleId":"liver-acinus-gallbladder","stem":"What is the primary function of cholangiocytes in the biliary tree?","options":[{"id":"a","text":"Secretion of bile acids"},{"id":"b","text":"Modification of bile composition"},{"id":"c","text":"Storage of bile"},{"id":"d","text":"Absorption of nutrients"}],"answerId":"b","explanation":"Cholangiocytes line the bile ducts and are responsible for modifying the composition of bile as it passes through the biliary tree.","kind":"mechanism","origin":"ai"},{"id":"liver-acinus-gallbladder~ai-2","moduleId":"liver-acinus-gallbladder","stem":"Which histological feature is characteristic of the gallbladder?","options":[{"id":"a","text":"Presence of submucosa"},{"id":"b","text":"Tall simple columnar epithelium"},{"id":"c","text":"Stratified squamous epithelium"},{"id":"d","text":"Muscularis mucosae"}],"answerId":"b","explanation":"The gallbladder is lined with tall simple columnar epithelium that is specialized for absorption.","kind":"recall","origin":"ai"},{"id":"liver-acinus-gallbladder~ai-3","moduleId":"liver-acinus-gallbladder","stem":"What is the significance of Rokitansky-Aschoff sinuses in the gallbladder?","options":[{"id":"a","text":"They are sites of bile storage"},{"id":"b","text":"They are involved in bile secretion"},{"id":"c","text":"They represent mucosal outpouchings into the muscle layer"},{"id":"d","text":"They are indicative of gallbladder cancer"}],"answerId":"c","explanation":"Rokitansky-Aschoff sinuses are mucosal outpouchings that extend into the muscular layer of the gallbladder.","kind":"clinical","origin":"ai"},{"id":"liver-acinus-gallbladder~ai-4","moduleId":"liver-acinus-gallbladder","stem":"Which of the following statements about the gallbladder wall is true?","options":[{"id":"a","text":"It has a standard four-layer structure"},{"id":"b","text":"It lacks a muscularis mucosae"},{"id":"c","text":"It contains a submucosa"},{"id":"d","text":"It has a thick muscularis externa"}],"answerId":"b","explanation":"The gallbladder lacks a muscularis mucosae and submucosa; its mucosa is directly on irregular smooth muscle.","kind":"trap","origin":"ai"},{"id":"liver-acinus-gallbladder~ai-5","moduleId":"liver-acinus-gallbladder","stem":"How does the hepatic acinus relate to the concept of portal hypertension?","options":[{"id":"a","text":"It is unrelated to portal hypertension"},{"id":"b","text":"Zone 1 is primarily affected by portal hypertension"},{"id":"c","text":"Zone 3 is primarily affected by portal hypertension"},{"id":"d","text":"The acinus does not influence bile flow"}],"answerId":"c","explanation":"In portal hypertension, Zone 3 can be affected due to increased pressure in the hepatic sinusoids, leading to ischemia and necrosis.","kind":"integration","linkedModuleIds":["gi-blood-supply-portal-system"],"origin":"ai"},{"id":"liver-acinus-gallbladder~ai-6","moduleId":"liver-acinus-gallbladder","stem":"What is the role of the hepatic acinus in the metabolism of fat-soluble vitamins?","options":[{"id":"a","text":"It stores fat-soluble vitamins"},{"id":"b","text":"It modifies bile for fat absorption"},{"id":"c","text":"It regulates the flow of bile acids"},{"id":"d","text":"It influences the absorption of fat-soluble vitamins"}],"answerId":"b","explanation":"The hepatic acinus plays a role in bile modification, which is essential for the absorption of fat-soluble vitamins.","kind":"integration","linkedModuleIds":["cholangitis-bile-vitamin-loss"],"origin":"ai"}],"salivary-gland-histology":[{"id":"salivary-gland-histology~ai-0","moduleId":"salivary-gland-histology","stem":"Which type of salivary gland is predominantly serous and contains adipocytes?","options":[{"id":"a","text":"Sublingual gland"},{"id":"b","text":"Submandibular gland"},{"id":"c","text":"Parotid gland"},{"id":"d","text":"Minor salivary glands"}],"answerId":"c","explanation":"The parotid gland is primarily serous and is known to contain adipose tissue.","kind":"recall","origin":"ai"},{"id":"salivary-gland-histology~ai-1","moduleId":"salivary-gland-histology","stem":"What is the primary function of striated ducts in salivary glands?","options":[{"id":"a","text":"Secrete digestive enzymes"},{"id":"b","text":"Modify electrolyte composition of saliva"},{"id":"c","text":"Produce mucous secretions"},{"id":"d","text":"Store saliva"}],"answerId":"b","explanation":"Striated ducts primarily modify the electrolyte composition of saliva, making it hypotonic.","kind":"mechanism","origin":"ai"},{"id":"salivary-gland-histology~ai-2","moduleId":"salivary-gland-histology","stem":"In which salivary gland would you expect to find pale mucous units with serous demilunes?","options":[{"id":"a","text":"Parotid gland"},{"id":"b","text":"Sublingual gland"},{"id":"c","text":"Submandibular gland"},{"id":"d","text":"Minor salivary glands"}],"answerId":"c","explanation":"The submandibular gland is a mixed gland that contains both mucous and serous components, including serous demilunes.","kind":"recall","origin":"ai"},{"id":"salivary-gland-histology~ai-3","moduleId":"salivary-gland-histology","stem":"What distinguishes serous acini from mucous tubules histologically?","options":[{"id":"a","text":"Serous acini are pale with flattened nuclei"},{"id":"b","text":"Mucous tubules are dark and round"},{"id":"c","text":"Serous acini are dark, round, enzyme-rich"},{"id":"d","text":"Mucous tubules have small lumina"}],"answerId":"c","explanation":"Serous acini are characterized by being dark, round, and rich in enzymes, while mucous tubules are pale.","kind":"recall","origin":"ai"},{"id":"salivary-gland-histology~ai-4","moduleId":"salivary-gland-histology","stem":"Which statement correctly describes the function of acini and striated ducts in salivary glands?","options":[{"id":"a","text":"Acini produce enzymes; striated ducts chiefly modify electrolyte composition"},{"id":"b","text":"Both acini and striated ducts produce enzymes"},{"id":"c","text":"Acini secrete mucous; striated ducts are inactive"},{"id":"d","text":"Striated ducts produce saliva; acini modify it"}],"answerId":"a","explanation":"Acini are responsible for enzyme production, while striated ducts modify the electrolyte composition of saliva.","kind":"trap","origin":"ai"},{"id":"salivary-gland-histology~ai-5","moduleId":"salivary-gland-histology","stem":"How does the histological structure of the pancreas relate to salivary gland function?","options":[{"id":"a","text":"Both have serous acini that produce digestive enzymes"},{"id":"b","text":"Both contain striated ducts for electrolyte modification"},{"id":"c","text":"Both have mucous tubules for secretion"},{"id":"d","text":"Both are primarily composed of adipose tissue"}],"answerId":"a","explanation":"The pancreas and salivary glands both contain serous acini that produce digestive enzymes, highlighting their exocrine function.","kind":"integration","linkedModuleIds":["pancreas-histology"],"origin":"ai"},{"id":"salivary-gland-histology~ai-6","moduleId":"salivary-gland-histology","stem":"What is a common histological feature of both salivary glands and the liver acinus?","options":[{"id":"a","text":"Presence of mucous tubules"},{"id":"b","text":"Presence of serous acini"},{"id":"c","text":"Presence of striated ducts"},{"id":"d","text":"Presence of adipose tissue"}],"answerId":"b","explanation":"Both salivary glands and the liver acinus contain serous acini, which are involved in secretion.","kind":"integration","linkedModuleIds":["liver-acinus-gallbladder"],"origin":"ai"}],"swallowing-phases-reflex":[{"id":"swallowing-phases-reflex~ai-0","moduleId":"swallowing-phases-reflex","stem":"Which cranial nerves are primarily involved in the reflexive phases of swallowing?","options":[{"id":"a","text":"CN V, VII, IX, X"},{"id":"b","text":"CN V, IX, X"},{"id":"c","text":"CN VII, IX, X"},{"id":"d","text":"CN V, VIII, X"}],"answerId":"b","explanation":"Cranial nerves V, IX, and X are responsible for the sensory and motor functions during the pharyngeal and esophageal phases of swallowing.","kind":"recall","origin":"ai"},{"id":"swallowing-phases-reflex~ai-1","moduleId":"swallowing-phases-reflex","stem":"What is the primary mechanism that triggers the pharyngeal swallowing reflex?","options":[{"id":"a","text":"Voluntary tongue movement"},{"id":"b","text":"Bolus stimulation of the oropharynx"},{"id":"c","text":"Laryngeal elevation"},{"id":"d","text":"Soft palate elevation"}],"answerId":"b","explanation":"The pharyngeal swallowing reflex is triggered by bolus stimulation of the oropharynx, activating the medullary swallowing program.","kind":"mechanism","origin":"ai"},{"id":"swallowing-phases-reflex~ai-2","moduleId":"swallowing-phases-reflex","stem":"A patient coughs immediately after swallowing. What does this indicate?","options":[{"id":"a","text":"Normal swallowing function"},{"id":"b","text":"Esophageal dysphagia"},{"id":"c","text":"Oropharyngeal dysphagia"},{"id":"d","text":"Delayed swallowing reflex"}],"answerId":"c","explanation":"Coughing immediately after swallowing indicates oropharyngeal dysphagia and potential aspiration, not esophageal issues.","kind":"clinical","origin":"ai"},{"id":"swallowing-phases-reflex~ai-3","moduleId":"swallowing-phases-reflex","stem":"Which of the following findings suggests incomplete soft-palate closure during the pharyngeal phase?","options":[{"id":"a","text":"Coughing immediately after swallowing"},{"id":"b","text":"Nasal regurgitation"},{"id":"c","text":"Difficulty initiating swallowing"},{"id":"d","text":"Sensation of food sticking in the throat"}],"answerId":"b","explanation":"Nasal regurgitation occurs when the soft palate fails to close properly, allowing food to escape into the nasal cavity.","kind":"recall","origin":"ai"},{"id":"swallowing-phases-reflex~ai-4","moduleId":"swallowing-phases-reflex","stem":"Which of the following is a trap regarding dysphagia localization?","options":[{"id":"a","text":"Coughing at swallow onset indicates oropharyngeal dysphagia"},{"id":"b","text":"Immediate coughing points to esophageal dysphagia"},{"id":"c","text":"Coughing after swallowing indicates aspiration"},{"id":"d","text":"Nasal regurgitation suggests esophageal issues"}],"answerId":"b","explanation":"Coughing at swallow onset typically indicates oropharyngeal dysphagia, while immediate coughing points to aspiration, not esophageal dysphagia.","kind":"trap","origin":"ai"},{"id":"swallowing-phases-reflex~ai-5","moduleId":"swallowing-phases-reflex","stem":"How does the swallowing mechanism integrate with esophageal peristalsis?","options":[{"id":"a","text":"The oral phase triggers esophageal contraction"},{"id":"b","text":"Pharyngeal reflex inhibits esophageal activity"},{"id":"c","text":"Esophageal peristalsis is independent of swallowing"},{"id":"d","text":"Soft palate elevation initiates peristalsis"}],"answerId":"a","explanation":"The oral phase of swallowing triggers a coordinated response that includes esophageal contraction to facilitate bolus passage.","kind":"integration","linkedModuleIds":["esophageal-peristalsis-sphincters"],"origin":"ai"},{"id":"swallowing-phases-reflex~ai-6","moduleId":"swallowing-phases-reflex","stem":"What role does mastication play in the swallowing process?","options":[{"id":"a","text":"It initiates the pharyngeal reflex"},{"id":"b","text":"It prepares the bolus for swallowing"},{"id":"c","text":"It closes the upper esophageal sphincter"},{"id":"d","text":"It prevents aspiration during swallowing"}],"answerId":"b","explanation":"Mastication is essential for preparing the bolus, making it easier to swallow and facilitating the swallowing process.","kind":"integration","linkedModuleIds":["mastication-mechanics-reflex"],"origin":"ai"}],"foregut-accessory-development":[{"id":"foregut-accessory-development~ai-0","moduleId":"foregut-accessory-development","stem":"Which structure is primarily responsible for forming the epithelial lining of the gastrointestinal tract?","options":[{"id":"a","text":"Ectoderm"},{"id":"b","text":"Mesoderm"},{"id":"c","text":"Endoderm"},{"id":"d","text":"Neuroectoderm"}],"answerId":"c","explanation":"The endoderm is the germ layer that forms the epithelial lining of the gastrointestinal tract.","kind":"recall","origin":"ai"},{"id":"foregut-accessory-development~ai-1","moduleId":"foregut-accessory-development","stem":"What is the primary blood supply to the foregut structures?","options":[{"id":"a","text":"Superior mesenteric artery"},{"id":"b","text":"Inferior mesenteric artery"},{"id":"c","text":"Celiac trunk"},{"id":"d","text":"Renal arteries"}],"answerId":"c","explanation":"The celiac trunk supplies blood to the foregut structures including the esophagus, stomach, and proximal duodenum.","kind":"recall","origin":"ai"},{"id":"foregut-accessory-development~ai-2","moduleId":"foregut-accessory-development","stem":"What is the mechanism behind polyhydramnios in cases of esophageal atresia?","options":[{"id":"a","text":"Increased fetal swallowing"},{"id":"b","text":"Decreased fetal swallowing"},{"id":"c","text":"Increased amniotic fluid production"},{"id":"d","text":"Decreased placental function"}],"answerId":"b","explanation":"Esophageal atresia prevents normal fetal swallowing, leading to an accumulation of amniotic fluid (polyhydramnios).","kind":"mechanism","origin":"ai"},{"id":"foregut-accessory-development~ai-3","moduleId":"foregut-accessory-development","stem":"Which embryological event is responsible for the formation of the definitive pancreas?","options":[{"id":"a","text":"Ventral pancreatic bud fusion with the dorsal bud"},{"id":"b","text":"Dorsal pancreatic bud elongation"},{"id":"c","text":"Lateral pancreatic bud separation"},{"id":"d","text":"Ventral pancreatic bud migration anteriorly"}],"answerId":"a","explanation":"The definitive pancreas is formed by the fusion of the ventral pancreatic bud with the dorsal bud.","kind":"mechanism","origin":"ai"},{"id":"foregut-accessory-development~ai-4","moduleId":"foregut-accessory-development","stem":"A newborn presents with bilious vomiting and failure to thrive. Imaging shows pancreatic tissue encircling the second part of the duodenum. What is the likely diagnosis?","options":[{"id":"a","text":"Esophageal atresia"},{"id":"b","text":"Annular pancreas"},{"id":"c","text":"Duodenal atresia"},{"id":"d","text":"Pyloric stenosis"}],"answerId":"b","explanation":"The presence of pancreatic tissue encircling the duodenum is characteristic of an annular pancreas.","kind":"clinical","origin":"ai"},{"id":"foregut-accessory-development~ai-5","moduleId":"foregut-accessory-development","stem":"Which of the following statements about pancreatic embryology is correct?","options":[{"id":"a","text":"The dorsal bud rotates around the duodenum"},{"id":"b","text":"The ventral bud fuses with the dorsal bud anteriorly"},{"id":"c","text":"The ventral pancreatic bud rotates posteriorly to fuse with the dorsal bud"},{"id":"d","text":"The dorsal bud develops from the bile duct"}],"answerId":"c","explanation":"The ventral pancreatic bud rotates posteriorly to fuse with the dorsal bud, establishing the definitive pancreas.","kind":"trap","origin":"ai"},{"id":"foregut-accessory-development~ai-6","moduleId":"foregut-accessory-development","stem":"How does the development of the foregut relate to the blood supply provided by the celiac trunk?","options":[{"id":"a","text":"The celiac trunk supplies the hindgut"},{"id":"b","text":"The foregut develops independently of vascular supply"},{"id":"c","text":"The celiac trunk provides blood to structures formed from the foregut"},{"id":"d","text":"The foregut is supplied by the inferior mesenteric artery"}],"answerId":"c","explanation":"The celiac trunk is the primary blood supply for structures that develop from the foregut, including the esophagus and stomach.","kind":"integration","linkedModuleIds":["gi-blood-supply-portal-system"],"origin":"ai"},{"id":"foregut-accessory-development~ai-7","moduleId":"foregut-accessory-development","stem":"Which embryological process is essential for understanding congenital anomalies of the hindgut?","options":[{"id":"a","text":"Foregut folding"},{"id":"b","text":"Ventral pancreatic rotation"},{"id":"c","text":"Hindgut development"},{"id":"d","text":"Midgut rotation"}],"answerId":"c","explanation":"Understanding hindgut development is crucial for recognizing congenital anomalies such as anorectal malformations.","kind":"integration","linkedModuleIds":["hindgut-anorectal-development"],"origin":"ai"}],"hindgut-anorectal-development":[{"id":"hindgut-anorectal-development~ai-0","moduleId":"hindgut-anorectal-development","stem":"Which artery supplies the hindgut?","options":[{"id":"a","text":"Superior mesenteric artery"},{"id":"b","text":"Inferior mesenteric artery"},{"id":"c","text":"Celiac trunk"},{"id":"d","text":"Internal iliac artery"}],"answerId":"b","explanation":"The hindgut is primarily supplied by the inferior mesenteric artery.","kind":"recall","origin":"ai"},{"id":"hindgut-anorectal-development~ai-1","moduleId":"hindgut-anorectal-development","stem":"What embryological structure partitions the cloaca into the anorectal canal and urogenital sinus?","options":[{"id":"a","text":"Urorectal septum"},{"id":"b","text":"Mesonephric duct"},{"id":"c","text":"Allantois"},{"id":"d","text":"Hindgut"}],"answerId":"a","explanation":"The urorectal septum is responsible for partitioning the cloaca.","kind":"recall","origin":"ai"},{"id":"hindgut-anorectal-development~ai-2","moduleId":"hindgut-anorectal-development","stem":"In Hirschsprung disease, what is the primary defect?","options":[{"id":"a","text":"Excessive neural-crest migration"},{"id":"b","text":"Failed neural-crest migration"},{"id":"c","text":"Abnormal cloacal partitioning"},{"id":"d","text":"Inadequate blood supply to the hindgut"}],"answerId":"b","explanation":"Hirschsprung disease results from failed neural-crest migration, leading to a lack of enteric ganglion cells.","kind":"mechanism","origin":"ai"},{"id":"hindgut-anorectal-development~ai-3","moduleId":"hindgut-anorectal-development","stem":"A newborn presents with delayed meconium passage and abdominal distension. What is the most likely diagnosis?","options":[{"id":"a","text":"Anorectal malformation"},{"id":"b","text":"Hirschsprung disease"},{"id":"c","text":"Meconium ileus"},{"id":"d","text":"Imperforate anus"}],"answerId":"b","explanation":"These symptoms are classic for Hirschsprung disease due to the aganglionic segment causing obstruction.","kind":"clinical","origin":"ai"},{"id":"hindgut-anorectal-development~ai-4","moduleId":"hindgut-anorectal-development","stem":"Which statement about the anal canal is correct?","options":[{"id":"a","text":"The entire anal canal is derived from endoderm"},{"id":"b","text":"The upper anal canal is endodermal, lower is ectodermal"},{"id":"c","text":"Both parts are ectodermal"},{"id":"d","text":"The anal canal has no embryological significance"}],"answerId":"b","explanation":"The upper anal canal is derived from endoderm, while the lower anal canal comes from ectoderm, marked by the pectinate line.","kind":"trap","origin":"ai"},{"id":"hindgut-anorectal-development~ai-5","moduleId":"hindgut-anorectal-development","stem":"What clinical finding is associated with abnormal cloacal partitioning?","options":[{"id":"a","text":"Delayed meconium"},{"id":"b","text":"Anorectal fistula"},{"id":"c","text":"Hirschsprung disease"},{"id":"d","text":"Meconium ileus"}],"answerId":"b","explanation":"Anorectal fistula results from abnormal development during cloacal partitioning.","kind":"clinical","origin":"ai"},{"id":"hindgut-anorectal-development~ai-6","moduleId":"hindgut-anorectal-development","stem":"How does the blood supply of the hindgut relate to congenital anomalies of the kidney?","options":[{"id":"a","text":"Both derive from the same arterial source"},{"id":"b","text":"Both involve neural crest cells"},{"id":"c","text":"Both are affected by cloacal anomalies"},{"id":"d","text":"Both are supplied by the celiac trunk"}],"answerId":"a","explanation":"Both the hindgut and kidneys are supplied by branches of the abdominal aorta, linking their vascular development.","kind":"integration","linkedModuleIds":["kub-congenital-anomalies"],"origin":"ai"},{"id":"hindgut-anorectal-development~ai-7","moduleId":"hindgut-anorectal-development","stem":"Which embryological defect could lead to both respiratory and gastrointestinal anomalies?","options":[{"id":"a","text":"Neural crest cell migration failure"},{"id":"b","text":"Cloacal membrane rupture"},{"id":"c","text":"Urorectal septum malformation"},{"id":"d","text":"Mesodermal dysgenesis"}],"answerId":"c","explanation":"Malformation of the urorectal septum can lead to both respiratory and gastrointestinal anomalies due to shared embryological origins.","kind":"integration","linkedModuleIds":["respiratory-congenital-anomalies"],"origin":"ai"}],"pancreas-histology":[{"id":"pancreas-histology~ai-0","moduleId":"pancreas-histology","stem":"What type of gland is the exocrine pancreas classified as?","options":[{"id":"a","text":"Simple tubular gland"},{"id":"b","text":"Compound serous acinar gland"},{"id":"c","text":"Compound tubuloalveolar gland"},{"id":"d","text":"Simple acinar gland"}],"answerId":"b","explanation":"The exocrine pancreas is a compound serous acinar gland characterized by acinar cells.","kind":"recall","origin":"ai"},{"id":"pancreas-histology~ai-1","moduleId":"pancreas-histology","stem":"Which cells mark the beginning of the duct system in the pancreas?","options":[{"id":"a","text":"Acinar cells"},{"id":"b","text":"Centroacinar cells"},{"id":"c","text":"Islet cells"},{"id":"d","text":"Ductal cells"}],"answerId":"b","explanation":"Centroacinar cells are located at the beginning of the intercalated ducts within an acinus.","kind":"recall","origin":"ai"},{"id":"pancreas-histology~ai-2","moduleId":"pancreas-histology","stem":"What is the primary function of acinar cells in the pancreas?","options":[{"id":"a","text":"Secrete insulin"},{"id":"b","text":"Secrete digestive enzymes"},{"id":"c","text":"Secrete bicarbonate-rich fluid"},{"id":"d","text":"Secrete somatostatin"}],"answerId":"b","explanation":"Acinar cells are responsible for the secretion of digestive enzymes and zymogens.","kind":"recall","origin":"ai"},{"id":"pancreas-histology~ai-3","moduleId":"pancreas-histology","stem":"Which of the following is a distinguishing feature of the pancreas compared to the parotid gland?","options":[{"id":"a","text":"Presence of striated ducts"},{"id":"b","text":"Presence of centroacinar cells"},{"id":"c","text":"Presence of myoepithelial cells"},{"id":"d","text":"Presence of mucous acini"}],"answerId":"b","explanation":"The pancreas has centroacinar cells and lacks striated ducts, which are present in the parotid gland.","kind":"trap","origin":"ai"},{"id":"pancreas-histology~ai-4","moduleId":"pancreas-histology","stem":"What is the appearance of the islets of Langerhans in the pancreas?","options":[{"id":"a","text":"Dark and densely packed"},{"id":"b","text":"Pale and highly vascular"},{"id":"c","text":"Fibrous and irregular"},{"id":"d","text":"Granular and opaque"}],"answerId":"b","explanation":"Islets of Langerhans are pale and highly vascular, distinguishing them from the surrounding exocrine tissue.","kind":"recall","origin":"ai"},{"id":"pancreas-histology~ai-5","moduleId":"pancreas-histology","stem":"How do beta cells in the islets of Langerhans primarily function?","options":[{"id":"a","text":"Secretion of glucagon"},{"id":"b","text":"Secretion of insulin"},{"id":"c","text":"Secretion of somatostatin"},{"id":"d","text":"Secretion of pancreatic polypeptide"}],"answerId":"b","explanation":"Beta cells are responsible for the secretion of insulin, which regulates glucose metabolism.","kind":"recall","origin":"ai"},{"id":"pancreas-histology~ai-6","moduleId":"pancreas-histology","stem":"How does the endocrine pancreas interact with the exocrine pancreas in terms of hormone regulation?","options":[{"id":"a","text":"Endocrine hormones inhibit exocrine enzyme secretion"},{"id":"b","text":"Exocrine secretions enhance endocrine hormone production"},{"id":"c","text":"Endocrine hormones have no effect on exocrine function"},{"id":"d","text":"Exocrine secretions directly regulate hormone release"}],"answerId":"a","explanation":"Endocrine hormones, such as somatostatin, can inhibit exocrine enzyme secretion, demonstrating their regulatory role.","kind":"integration","linkedModuleIds":["hen1-islet-hormones-paracrine"],"origin":"ai"},{"id":"pancreas-histology~ai-7","moduleId":"pancreas-histology","stem":"Which histological feature differentiates the pancreas from other glands such as the salivary glands?","options":[{"id":"a","text":"Presence of serous acini"},{"id":"b","text":"Presence of centroacinar cells"},{"id":"c","text":"Presence of mucous acini"},{"id":"d","text":"Presence of striated ducts"}],"answerId":"b","explanation":"Centroacinar cells are unique to the pancreas and mark the beginning of the duct system, unlike salivary glands.","kind":"integration","linkedModuleIds":["salivary-gland-histology"],"origin":"ai"}],"gi-smooth-muscle-electrical-activity":[{"id":"gi-smooth-muscle-electrical-activity~ai-0","moduleId":"gi-smooth-muscle-electrical-activity","stem":"Which cells are primarily responsible for generating and propagating slow waves in the GI smooth muscle?","options":[{"id":"a","text":"Enteric neurons"},{"id":"b","text":"Interstitial cells of Cajal"},{"id":"c","text":"Smooth muscle cells"},{"id":"d","text":"Myenteric plexus"}],"answerId":"b","explanation":"Interstitial cells of Cajal (ICC) act as pacemakers in the GI tract, generating slow waves.","kind":"recall","origin":"ai"},{"id":"gi-smooth-muscle-electrical-activity~ai-1","moduleId":"gi-smooth-muscle-electrical-activity","stem":"What is the primary effect of acetylcholine on GI smooth muscle activity?","options":[{"id":"a","text":"Inhibits contraction"},{"id":"b","text":"Increases spike potentials"},{"id":"c","text":"Decreases slow wave frequency"},{"id":"d","text":"Hyperpolarizes the membrane"}],"answerId":"b","explanation":"Acetylcholine depolarizes the membrane, increasing the number of spike potentials and enhancing contraction.","kind":"mechanism","origin":"ai"},{"id":"gi-smooth-muscle-electrical-activity~ai-2","moduleId":"gi-smooth-muscle-electrical-activity","stem":"What clinical finding indicates that slow waves have not reached spike threshold in GI smooth muscle?","options":[{"id":"a","text":"Increased contraction strength"},{"id":"b","text":"Rhythmic membrane oscillations without contraction"},{"id":"c","text":"Sustained contraction"},{"id":"d","text":"Absence of slow waves"}],"answerId":"b","explanation":"Rhythmic membrane oscillations without contraction suggest that slow waves are present but have not reached the threshold for spike potentials.","kind":"clinical","origin":"ai"},{"id":"gi-smooth-muscle-electrical-activity~ai-3","moduleId":"gi-smooth-muscle-electrical-activity","stem":"Which statement correctly describes the relationship between slow waves and contraction in GI smooth muscle?","options":[{"id":"a","text":"Every slow wave leads to contraction"},{"id":"b","text":"Slow waves set the rhythm, but spikes trigger contraction"},{"id":"c","text":"Slow waves are equivalent to action potentials"},{"id":"d","text":"Contraction occurs independently of slow waves"}],"answerId":"b","explanation":"Slow waves set the membrane potential rhythm, while spikes that cross threshold are responsible for actual contraction.","kind":"trap","origin":"ai"},{"id":"gi-smooth-muscle-electrical-activity~ai-4","moduleId":"gi-smooth-muscle-electrical-activity","stem":"How does sympathetic input affect GI smooth muscle activity?","options":[{"id":"a","text":"Increases contraction"},{"id":"b","text":"Hyperpolarizes the membrane"},{"id":"c","text":"Enhances spike potential frequency"},{"id":"d","text":"Stimulates interstitial cells of Cajal"}],"answerId":"b","explanation":"Sympathetic input generally hyperpolarizes GI smooth muscle, inhibiting contraction.","kind":"mechanism","origin":"ai"},{"id":"gi-smooth-muscle-electrical-activity~ai-5","moduleId":"gi-smooth-muscle-electrical-activity","stem":"How do slow waves in GI smooth muscle compare to graded potentials in cardiac muscle?","options":[{"id":"a","text":"Both can trigger contraction directly"},{"id":"b","text":"Slow waves do not cause contraction, while graded potentials do"},{"id":"c","text":"Both are influenced by neurotransmitters"},{"id":"d","text":"Slow waves are action potentials, graded potentials are not"}],"answerId":"b","explanation":"Slow waves in GI smooth muscle do not directly cause contraction, whereas graded potentials in cardiac muscle can lead to contraction.","kind":"integration","linkedModuleIds":["cardiac-smooth-muscle"],"origin":"ai"},{"id":"gi-smooth-muscle-electrical-activity~ai-6","moduleId":"gi-smooth-muscle-electrical-activity","stem":"What role do interstitial cells of Cajal play in the context of enteric nervous system control?","options":[{"id":"a","text":"They inhibit smooth muscle contraction"},{"id":"b","text":"They generate slow waves independent of neuronal input"},{"id":"c","text":"They are responsible for neurotransmitter release"},{"id":"d","text":"They directly mediate reflex actions"}],"answerId":"b","explanation":"Interstitial cells of Cajal generate slow waves that can modulate smooth muscle contraction, acting independently of direct neuronal input.","kind":"integration","linkedModuleIds":["enteric-autonomic-reflex-control"],"origin":"ai"}],"esophageal-peristalsis-sphincters":[{"id":"esophageal-peristalsis-sphincters~ai-0","moduleId":"esophageal-peristalsis-sphincters","stem":"What is the primary function of the lower esophageal sphincter (LES)?","options":[{"id":"a","text":"Prevent air entry into the esophagus"},{"id":"b","text":"Facilitate peristalsis"},{"id":"c","text":"Maintain tonic pressure to prevent reflux"},{"id":"d","text":"Trigger swallowing reflex"}],"answerId":"c","explanation":"The LES maintains tonic pressure to prevent gastroesophageal reflux.","kind":"recall","origin":"ai"},{"id":"esophageal-peristalsis-sphincters~ai-1","moduleId":"esophageal-peristalsis-sphincters","stem":"Which neurotransmitters mediate relaxation of the lower esophageal sphincter?","options":[{"id":"a","text":"Acetylcholine and substance P"},{"id":"b","text":"Norepinephrine and dopamine"},{"id":"c","text":"Nitric oxide and vasoactive intestinal peptide"},{"id":"d","text":"Serotonin and histamine"}],"answerId":"c","explanation":"Nitric oxide and vasoactive intestinal peptide are responsible for mediating relaxation of the LES.","kind":"mechanism","origin":"ai"},{"id":"esophageal-peristalsis-sphincters~ai-2","moduleId":"esophageal-peristalsis-sphincters","stem":"A patient presents with progressive dysphagia to solids and liquids. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Increased LES tone"},{"id":"b","text":"Impaired LES relaxation"},{"id":"c","text":"Esophageal obstruction"},{"id":"d","text":"Increased peristaltic activity"}],"answerId":"b","explanation":"Impaired LES relaxation in conditions like achalasia leads to dysphagia.","kind":"clinical","origin":"ai"},{"id":"esophageal-peristalsis-sphincters~ai-3","moduleId":"esophageal-peristalsis-sphincters","stem":"Which of the following is a common clinical finding in gastroesophageal reflux disease (GERD)?","options":[{"id":"a","text":"Dysphagia to solids only"},{"id":"b","text":"Heartburn and acid regurgitation"},{"id":"c","text":"Chest pain unrelated to meals"},{"id":"d","text":"Weight loss due to malnutrition"}],"answerId":"b","explanation":"Heartburn and acid regurgitation are hallmark symptoms of GERD.","kind":"clinical","origin":"ai"},{"id":"esophageal-peristalsis-sphincters~ai-4","moduleId":"esophageal-peristalsis-sphincters","stem":"Achalasia is characterized by the loss of which type of neurons?","options":[{"id":"a","text":"Excitatory myenteric neurons"},{"id":"b","text":"Inhibitory myenteric neurons"},{"id":"c","text":"Sensory neurons"},{"id":"d","text":"Vagal motor neurons"}],"answerId":"b","explanation":"Achalasia reflects the loss of inhibitory myenteric neurons, leading to impaired LES relaxation.","kind":"trap","origin":"ai"},{"id":"esophageal-peristalsis-sphincters~ai-5","moduleId":"esophageal-peristalsis-sphincters","stem":"How does transient LES relaxation contribute to gastroesophageal reflux?","options":[{"id":"a","text":"It increases esophageal peristalsis"},{"id":"b","text":"It allows gastric contents to enter the esophagus"},{"id":"c","text":"It strengthens the antireflux barrier"},{"id":"d","text":"It decreases intra-abdominal pressure"}],"answerId":"b","explanation":"Transient LES relaxations allow gastric contents to reflux into the esophagus.","kind":"mechanism","origin":"ai"},{"id":"esophageal-peristalsis-sphincters~ai-6","moduleId":"esophageal-peristalsis-sphincters","stem":"How does the mechanism of esophageal peristalsis relate to swallowing phases?","options":[{"id":"a","text":"Both involve the same neural pathways"},{"id":"b","text":"Both are primarily voluntary processes"},{"id":"c","text":"Both are regulated by the LES"},{"id":"d","text":"Both are influenced by vagal stimulation"}],"answerId":"d","explanation":"Both esophageal peristalsis and swallowing phases are influenced by vagal stimulation.","kind":"integration","linkedModuleIds":["swallowing-phases-reflex"],"origin":"ai"},{"id":"esophageal-peristalsis-sphincters~ai-7","moduleId":"esophageal-peristalsis-sphincters","stem":"What is a shared feature between achalasia and heart failure that affects swallowing?","options":[{"id":"a","text":"Increased LES tone"},{"id":"b","text":"Impaired relaxation mechanisms"},{"id":"c","text":"Esophageal obstruction"},{"id":"d","text":"Neuromuscular dysfunction"}],"answerId":"b","explanation":"Both conditions can involve impaired relaxation mechanisms affecting esophageal function.","kind":"integration","linkedModuleIds":["heart-failure-overview"],"origin":"ai"}],"enteric-autonomic-reflex-control":[{"id":"enteric-autonomic-reflex-control~ai-0","moduleId":"enteric-autonomic-reflex-control","stem":"Which plexus primarily regulates gastrointestinal motility?","options":[{"id":"a","text":"Submucosal (Meissner) plexus"},{"id":"b","text":"Myenteric (Auerbach) plexus"},{"id":"c","text":"Celiac plexus"},{"id":"d","text":"Pelvic plexus"}],"answerId":"b","explanation":"The myenteric (Auerbach) plexus is chiefly responsible for regulating motility within the gastrointestinal tract.","kind":"recall","origin":"ai"},{"id":"enteric-autonomic-reflex-control~ai-1","moduleId":"enteric-autonomic-reflex-control","stem":"What is the primary effect of parasympathetic stimulation on the gastrointestinal tract?","options":[{"id":"a","text":"Inhibition of motility"},{"id":"b","text":"Promotion of secretion"},{"id":"c","text":"Contraction of sphincters"},{"id":"d","text":"Decreased blood flow to the gut"}],"answerId":"b","explanation":"Parasympathetic stimulation generally promotes gastrointestinal activity, including increased secretion.","kind":"mechanism","origin":"ai"},{"id":"enteric-autonomic-reflex-control~ai-2","moduleId":"enteric-autonomic-reflex-control","stem":"A patient presents with a defecation urge after eating. Which reflex is primarily responsible for this phenomenon?","options":[{"id":"a","text":"Gastrocolic reflex"},{"id":"b","text":"Enterogastric reflex"},{"id":"c","text":"Vasoactive intestinal peptide reflex"},{"id":"d","text":"Peristaltic reflex"}],"answerId":"a","explanation":"The gastrocolic reflex increases colonic mass movement in response to food intake, leading to a defecation urge.","kind":"clinical","origin":"ai"},{"id":"enteric-autonomic-reflex-control~ai-3","moduleId":"enteric-autonomic-reflex-control","stem":"Which statement about the enteric nervous system (ENS) is true?","options":[{"id":"a","text":"The ENS cannot function without vagal input"},{"id":"b","text":"The ENS can execute short local reflexes independently"},{"id":"c","text":"The ENS only responds to sympathetic input"},{"id":"d","text":"The ENS lacks sensory neurons"}],"answerId":"b","explanation":"The ENS can organize local reflexes independently, utilizing its own sensory, interneuron, and motor circuits.","kind":"trap","origin":"ai"},{"id":"enteric-autonomic-reflex-control~ai-4","moduleId":"enteric-autonomic-reflex-control","stem":"How does the enteric nervous system respond to luminal stretch?","options":[{"id":"a","text":"Inhibits peristalsis"},{"id":"b","text":"Promotes secretion and motility"},{"id":"c","text":"Contracts sphincters"},{"id":"d","text":"Reduces blood flow to the gut"}],"answerId":"b","explanation":"Luminal stretch activates sensory neurons that promote coordinated secretion and motility via the ENS.","kind":"mechanism","origin":"ai"},{"id":"enteric-autonomic-reflex-control~ai-5","moduleId":"enteric-autonomic-reflex-control","stem":"Which neurotransmitter is primarily associated with parasympathetic stimulation of the gastrointestinal tract?","options":[{"id":"a","text":"Norepinephrine"},{"id":"b","text":"Acetylcholine"},{"id":"c","text":"Dopamine"},{"id":"d","text":"Serotonin"}],"answerId":"b","explanation":"Acetylcholine is the primary neurotransmitter used by the parasympathetic nervous system to stimulate gastrointestinal activity.","kind":"recall","origin":"ai"},{"id":"enteric-autonomic-reflex-control~ai-6","moduleId":"enteric-autonomic-reflex-control","stem":"How does the gastrocolic reflex integrate with the autonomic nervous system during a meal?","options":[{"id":"a","text":"It inhibits sympathetic activity"},{"id":"b","text":"It enhances vagal tone"},{"id":"c","text":"It promotes sphincter contraction"},{"id":"d","text":"It decreases motility"}],"answerId":"b","explanation":"The gastrocolic reflex enhances vagal tone, promoting gastrointestinal motility and secretion in response to food intake.","kind":"integration","linkedModuleIds":["autonomic-sympathetic-parasympathetic"],"origin":"ai"},{"id":"enteric-autonomic-reflex-control~ai-7","moduleId":"enteric-autonomic-reflex-control","stem":"Which mechanism links the enteric nervous system with hormonal responses during digestion?","options":[{"id":"a","text":"Sympathetic inhibition"},{"id":"b","text":"Vagal stimulation"},{"id":"c","text":"Local reflexes"},{"id":"d","text":"Hormonal feedback"}],"answerId":"d","explanation":"Hormonal feedback mechanisms are crucial for integrating enteric nervous system activity with overall digestive responses.","kind":"integration","linkedModuleIds":["gi-hormones-paracrines-neurocrines"],"origin":"ai"}],"midgut-rotation-fixation":[{"id":"midgut-rotation-fixation~ai-0","moduleId":"midgut-rotation-fixation","stem":"What is the primary artery supplying the midgut?","options":[{"id":"a","text":"Inferior mesenteric artery"},{"id":"b","text":"Celiac trunk"},{"id":"c","text":"Superior mesenteric artery"},{"id":"d","text":"Gastroduodenal artery"}],"answerId":"c","explanation":"The superior mesenteric artery supplies the midgut, which includes structures from the distal duodenum to the proximal two-thirds of the transverse colon.","kind":"recall","origin":"ai"},{"id":"midgut-rotation-fixation~ai-1","moduleId":"midgut-rotation-fixation","stem":"During midgut rotation, the bowel rotates around which structure?","options":[{"id":"a","text":"Inferior mesenteric artery"},{"id":"b","text":"Celiac trunk"},{"id":"c","text":"Superior mesenteric artery"},{"id":"d","text":"Aorta"}],"answerId":"c","explanation":"The midgut rotates 270° counterclockwise around the superior mesenteric artery during development.","kind":"mechanism","origin":"ai"},{"id":"midgut-rotation-fixation~ai-2","moduleId":"midgut-rotation-fixation","stem":"A child presents with painless lower GI bleeding. What is the most likely cause?","options":[{"id":"a","text":"Meckel diverticulum"},{"id":"b","text":"Intussusception"},{"id":"c","text":"Appendicitis"},{"id":"d","text":"Hirschsprung disease"}],"answerId":"a","explanation":"Ectopic gastric mucosa in a Meckel diverticulum can ulcerate the adjacent ileum, leading to painless lower GI bleeding.","kind":"clinical","origin":"ai"},{"id":"midgut-rotation-fixation~ai-3","moduleId":"midgut-rotation-fixation","stem":"Which of the following correctly describes omphalocele and gastroschisis?","options":[{"id":"a","text":"Both are covered defects"},{"id":"b","text":"Omphalocele is an uncovered defect"},{"id":"c","text":"Gastroschisis is covered and related to failed return"},{"id":"d","text":"Omphalocele is covered and related to failed return"}],"answerId":"d","explanation":"Omphalocele is a covered defect related to failed return of the midgut, while gastroschisis is an uncovered abdominal-wall defect.","kind":"trap","origin":"ai"},{"id":"midgut-rotation-fixation~ai-4","moduleId":"midgut-rotation-fixation","stem":"What complication arises from midgut malrotation?","options":[{"id":"a","text":"Meckel diverticulum"},{"id":"b","text":"Volvulus"},{"id":"c","text":"Intestinal atresia"},{"id":"d","text":"Hirschsprung disease"}],"answerId":"b","explanation":"Malrotation can lead to midgut volvulus, which may cause ischemia due to compromised blood supply.","kind":"recall","origin":"ai"},{"id":"midgut-rotation-fixation~ai-5","moduleId":"midgut-rotation-fixation","stem":"How does midgut rotation relate to the development of the hindgut?","options":[{"id":"a","text":"It influences the descent of the cecum"},{"id":"b","text":"It determines the blood supply to the hindgut"},{"id":"c","text":"It affects the formation of the cloaca"},{"id":"d","text":"It has no relation to hindgut development"}],"answerId":"a","explanation":"The rotation of the midgut influences the descent of the cecum into the right lower quadrant, which is part of the hindgut development.","kind":"integration","linkedModuleIds":["hindgut-anorectal-development"],"origin":"ai"},{"id":"midgut-rotation-fixation~ai-6","moduleId":"midgut-rotation-fixation","stem":"What is the consequence of a narrow mesenteric base due to malrotation?","options":[{"id":"a","text":"Increased blood flow"},{"id":"b","text":"Risk of volvulus"},{"id":"c","text":"Decreased intestinal motility"},{"id":"d","text":"Formation of diverticula"}],"answerId":"b","explanation":"A narrow mesenteric base increases the risk of midgut volvulus, which can lead to ischemia.","kind":"trap","origin":"ai"},{"id":"midgut-rotation-fixation~ai-7","moduleId":"midgut-rotation-fixation","stem":"Which embryological process is essential for midgut elongation and return?","options":[{"id":"a","text":"Gastrulation"},{"id":"b","text":"Neurulation"},{"id":"c","text":"Lateral body wall folding"},{"id":"d","text":"Physiologic umbilical herniation"}],"answerId":"d","explanation":"Physiologic umbilical herniation is a necessary step for the elongation and eventual return of the midgut to the abdominal cavity.","kind":"mechanism","origin":"ai"},{"id":"midgut-rotation-fixation~ai-8","moduleId":"midgut-rotation-fixation","stem":"How does the blood supply to the midgut relate to the portal system?","options":[{"id":"a","text":"It drains into the inferior vena cava"},{"id":"b","text":"It is supplied by the celiac trunk"},{"id":"c","text":"It is drained by the superior mesenteric vein"},{"id":"d","text":"It has no connection to the portal system"}],"answerId":"c","explanation":"The midgut is drained by the superior mesenteric vein, which contributes to the portal system.","kind":"integration","linkedModuleIds":["gi-blood-supply-portal-system"],"origin":"ai"}],"liver-lobule-sinusoid":[{"id":"liver-lobule-sinusoid~ai-0","moduleId":"liver-lobule-sinusoid","stem":"What is the primary function of Kupffer cells in the liver?","options":[{"id":"a","text":"Produce bile"},{"id":"b","text":"Store vitamin A"},{"id":"c","text":"Clear microbes from portal blood"},{"id":"d","text":"Regulate blood flow"}],"answerId":"c","explanation":"Kupffer cells are specialized macrophages that clear microbes and debris from the portal blood.","kind":"recall","origin":"ai"},{"id":"liver-lobule-sinusoid~ai-1","moduleId":"liver-lobule-sinusoid","stem":"Which structure is responsible for the flow of bile in the liver?","options":[{"id":"a","text":"Central vein"},{"id":"b","text":"Hepatic artery"},{"id":"c","text":"Canaliculi"},{"id":"d","text":"Sinusoids"}],"answerId":"c","explanation":"Bile flows through canaliculi formed by hepatocytes, moving toward the portal bile ductules.","kind":"recall","origin":"ai"},{"id":"liver-lobule-sinusoid~ai-2","moduleId":"liver-lobule-sinusoid","stem":"In chronic liver injury, which cells contribute to fibrosis?","options":[{"id":"a","text":"Hepatocytes"},{"id":"b","text":"Kupffer cells"},{"id":"c","text":"Stellate cells"},{"id":"d","text":"Endothelial cells"}],"answerId":"c","explanation":"Activated stellate cells in the space of Disse produce collagen, leading to hepatic fibrosis.","kind":"recall","origin":"ai"},{"id":"liver-lobule-sinusoid~ai-3","moduleId":"liver-lobule-sinusoid","stem":"What is the direction of blood flow in the hepatic sinusoids?","options":[{"id":"a","text":"Toward the portal triad"},{"id":"b","text":"Toward the central vein"},{"id":"c","text":"Toward the bile canaliculi"},{"id":"d","text":"Toward the hepatic artery"}],"answerId":"b","explanation":"Blood flows through the sinusoids toward the central vein after mixing from the portal vein and hepatic artery.","kind":"recall","origin":"ai"},{"id":"liver-lobule-sinusoid~ai-4","moduleId":"liver-lobule-sinusoid","stem":"Which statement about bile flow is correct?","options":[{"id":"a","text":"Bile flows toward the central vein"},{"id":"b","text":"Bile flows through sinusoids"},{"id":"c","text":"Bile flows in the opposite direction to blood"},{"id":"d","text":"Bile is produced in the sinusoids"}],"answerId":"c","explanation":"Bile flows through canaliculi toward the portal bile ductules, opposite to the direction of blood in the sinusoids.","kind":"trap","origin":"ai"},{"id":"liver-lobule-sinusoid~ai-5","moduleId":"liver-lobule-sinusoid","stem":"How do hepatocytes contribute to bile formation?","options":[{"id":"a","text":"By secreting bile directly into sinusoids"},{"id":"b","text":"By forming tight junctions in canaliculi"},{"id":"c","text":"By storing bile in the central vein"},{"id":"d","text":"By filtering blood in the space of Disse"}],"answerId":"b","explanation":"Hepatocytes form tight junctions that create bile canaliculi, allowing bile to flow toward the bile ducts.","kind":"mechanism","origin":"ai"},{"id":"liver-lobule-sinusoid~ai-6","moduleId":"liver-lobule-sinusoid","stem":"Which cell type in the liver is primarily responsible for vitamin A storage?","options":[{"id":"a","text":"Hepatocytes"},{"id":"b","text":"Kupffer cells"},{"id":"c","text":"Stellate cells"},{"id":"d","text":"Endothelial cells"}],"answerId":"c","explanation":"Stellate cells (Ito cells) in the space of Disse store vitamin A and can transform into collagen-producing myofibroblasts.","kind":"recall","origin":"ai"},{"id":"liver-lobule-sinusoid~ai-7","moduleId":"liver-lobule-sinusoid","stem":"How does the hepatic portal system relate to the liver's function?","options":[{"id":"a","text":"It supplies oxygen-rich blood"},{"id":"b","text":"It drains bile from the liver"},{"id":"c","text":"It delivers nutrient-rich blood from the GI tract"},{"id":"d","text":"It carries waste products from the liver"}],"answerId":"c","explanation":"The hepatic portal system delivers nutrient-rich blood from the gastrointestinal tract to the liver for processing.","kind":"integration","linkedModuleIds":["gi-blood-supply-portal-system"],"origin":"ai"},{"id":"liver-lobule-sinusoid~ai-8","moduleId":"liver-lobule-sinusoid","stem":"What is the significance of the space of Disse in liver function?","options":[{"id":"a","text":"It stores bile"},{"id":"b","text":"It allows for nutrient exchange between blood and hepatocytes"},{"id":"c","text":"It contains Kupffer cells"},{"id":"d","text":"It is where blood enters the liver"}],"answerId":"b","explanation":"The space of Disse facilitates the exchange of nutrients and waste products between the blood and hepatocytes.","kind":"integration","linkedModuleIds":["connective-tissue-cells"],"origin":"ai"}],"gastric-enzymes-intrinsic-barrier":[{"id":"gastric-enzymes-intrinsic-barrier~ai-0","moduleId":"gastric-enzymes-intrinsic-barrier","stem":"What is the primary function of intrinsic factor secreted by parietal cells?","options":[{"id":"a","text":"Facilitates iron absorption"},{"id":"b","text":"Enables vitamin B12 absorption"},{"id":"c","text":"Stimulates gastric acid secretion"},{"id":"d","text":"Activates pepsinogen"}],"answerId":"b","explanation":"Intrinsic factor is essential for the absorption of vitamin B12 in the terminal ileum.","kind":"recall","origin":"ai"},{"id":"gastric-enzymes-intrinsic-barrier~ai-1","moduleId":"gastric-enzymes-intrinsic-barrier","stem":"Which cell type is responsible for the secretion of pepsinogen?","options":[{"id":"a","text":"Parietal cells"},{"id":"b","text":"G cells"},{"id":"c","text":"Chief cells"},{"id":"d","text":"Mucous cells"}],"answerId":"c","explanation":"Chief cells release pepsinogen, which is activated to pepsin in the acidic environment of the stomach.","kind":"recall","origin":"ai"},{"id":"gastric-enzymes-intrinsic-barrier~ai-2","moduleId":"gastric-enzymes-intrinsic-barrier","stem":"What is the mechanism by which NSAIDs increase the risk of gastric ulcers?","options":[{"id":"a","text":"Inhibition of pepsinogen secretion"},{"id":"b","text":"Reduction of gastric acid secretion"},{"id":"c","text":"Inhibition of protective prostaglandins"},{"id":"d","text":"Stimulation of mucous secretion"}],"answerId":"c","explanation":"NSAIDs inhibit cyclooxygenase (COX), leading to decreased production of protective prostaglandins, which increases ulcer risk.","kind":"mechanism","origin":"ai"},{"id":"gastric-enzymes-intrinsic-barrier~ai-3","moduleId":"gastric-enzymes-intrinsic-barrier","stem":"A patient presents with macrocytic anemia. Which underlying condition is most likely related to intrinsic factor deficiency?","options":[{"id":"a","text":"Chronic gastritis"},{"id":"b","text":"Celiac disease"},{"id":"c","text":"Pernicious anemia"},{"id":"d","text":"Crohn's disease"}],"answerId":"c","explanation":"Pernicious anemia is an autoimmune condition that leads to destruction of parietal cells, resulting in intrinsic factor deficiency.","kind":"clinical","origin":"ai"},{"id":"gastric-enzymes-intrinsic-barrier~ai-4","moduleId":"gastric-enzymes-intrinsic-barrier","stem":"Which of the following statements about vitamin B12 absorption is correct?","options":[{"id":"a","text":"Intrinsic factor binds dietary B12 immediately in the stomach"},{"id":"b","text":"B12 is absorbed in the stomach"},{"id":"c","text":"R protein binds B12 in the duodenum"},{"id":"d","text":"Pancreatic enzymes are required for B12 absorption"}],"answerId":"d","explanation":"Pancreatic proteases are necessary to free vitamin B12 from R protein, allowing it to bind intrinsic factor in the duodenum.","kind":"trap","origin":"ai"},{"id":"gastric-enzymes-intrinsic-barrier~ai-5","moduleId":"gastric-enzymes-intrinsic-barrier","stem":"How does the gastric mucosal defense mechanism relate to malabsorption patterns?","options":[{"id":"a","text":"Mucosal integrity is unrelated to nutrient absorption"},{"id":"b","text":"Increased gastric acid enhances nutrient absorption"},{"id":"c","text":"Defective mucosal defense can lead to malabsorption"},{"id":"d","text":"Intrinsic factor deficiency is a malabsorption pattern"}],"answerId":"c","explanation":"Defective gastric mucosal defenses can lead to damage and malabsorption of nutrients.","kind":"integration","linkedModuleIds":["malabsorption-patterns"],"origin":"ai"},{"id":"gastric-enzymes-intrinsic-barrier~ai-6","moduleId":"gastric-enzymes-intrinsic-barrier","stem":"What role does gastric acid play in the context of gastric mucosal defense and malabsorption?","options":[{"id":"a","text":"It enhances intrinsic factor secretion"},{"id":"b","text":"It activates pepsinogen"},{"id":"c","text":"It protects the mucosa from pathogens"},{"id":"d","text":"It has no role in malabsorption"}],"answerId":"b","explanation":"Gastric acid is crucial for activating pepsinogen, which is important for protein digestion and overall gastric function.","kind":"integration","linkedModuleIds":["gastric-acid-mechanism-control"],"origin":"ai"}],"gastric-accommodation-mixing":[{"id":"gastric-accommodation-mixing~ai-0","moduleId":"gastric-accommodation-mixing","stem":"What physiological mechanism allows the proximal stomach to accommodate a meal without significant pressure increase?","options":[{"id":"a","text":"Vagovagal reflex"},{"id":"b","text":"Peristaltic contraction"},{"id":"c","text":"Pyloric closure"},{"id":"d","text":"Retropulsion"}],"answerId":"a","explanation":"The vagovagal reflex triggers receptive relaxation, allowing the stomach to accommodate food without a rise in intragastric pressure.","kind":"mechanism","origin":"ai"},{"id":"gastric-accommodation-mixing~ai-1","moduleId":"gastric-accommodation-mixing","stem":"Which of the following statements about gastric mixing is true?","options":[{"id":"a","text":"Every antral contraction empties most of its contents into the duodenum."},{"id":"b","text":"Pyloric narrowing sends most antral contents backward by retropulsion."},{"id":"c","text":"Liquids pass through the pylorus more slowly than solids."},{"id":"d","text":"Retropulsion occurs only during fasting."}],"answerId":"b","explanation":"Pyloric narrowing directs most antral contents backward through retropulsion, which is essential for mixing.","kind":"trap","origin":"ai"},{"id":"gastric-accommodation-mixing~ai-2","moduleId":"gastric-accommodation-mixing","stem":"What is the primary role of retropulsion in the gastric mixing process?","options":[{"id":"a","text":"Facilitates gastric emptying"},{"id":"b","text":"Reduces particle size"},{"id":"c","text":"Increases gastric pressure"},{"id":"d","text":"Promotes gastric accommodation"}],"answerId":"b","explanation":"Retropulsion helps grind and mix the gastric contents, reducing particle size before they pass into the duodenum.","kind":"clinical","origin":"ai"},{"id":"gastric-accommodation-mixing~ai-3","moduleId":"gastric-accommodation-mixing","stem":"In which condition would you expect to find early satiety due to impaired gastric accommodation?","options":[{"id":"a","text":"Gastric ulcer"},{"id":"b","text":"Vagal dysfunction"},{"id":"c","text":"Gastroesophageal reflux"},{"id":"d","text":"Peptic esophagitis"}],"answerId":"b","explanation":"Vagal dysfunction impairs the stomach's ability to accommodate food, leading to increased intragastric pressure and early satiety.","kind":"recall","origin":"ai"},{"id":"gastric-accommodation-mixing~ai-4","moduleId":"gastric-accommodation-mixing","stem":"How does the pylorus function during the fed state?","options":[{"id":"a","text":"It remains fully open to allow all contents to pass."},{"id":"b","text":"It selectively allows liquids and small particles to pass."},{"id":"c","text":"It contracts to prevent any gastric emptying."},{"id":"d","text":"It facilitates rapid emptying of solid food."}],"answerId":"b","explanation":"During the fed state, the pylorus selectively allows only liquids and sufficiently small particles to pass into the duodenum.","kind":"recall","origin":"ai"},{"id":"gastric-accommodation-mixing~ai-5","moduleId":"gastric-accommodation-mixing","stem":"How does gastric accommodation relate to gastric emptying feedback mechanisms?","options":[{"id":"a","text":"Increased accommodation leads to faster gastric emptying."},{"id":"b","text":"Impaired accommodation can trigger feedback to slow gastric emptying."},{"id":"c","text":"Accommodation has no effect on gastric emptying."},{"id":"d","text":"Feedback mechanisms only occur during fasting."}],"answerId":"b","explanation":"Impaired gastric accommodation raises intragastric pressure, which can trigger feedback mechanisms that slow gastric emptying.","kind":"integration","linkedModuleIds":["gastric-emptying-feedback"],"origin":"ai"},{"id":"gastric-accommodation-mixing~ai-6","moduleId":"gastric-accommodation-mixing","stem":"What is the relationship between gastric mixing and colonic motility?","options":[{"id":"a","text":"Both processes are independent of each other."},{"id":"b","text":"Gastric mixing enhances colonic mass movements."},{"id":"c","text":"Colonic motility affects gastric mixing efficiency."},{"id":"d","text":"Both involve similar neural control mechanisms."}],"answerId":"d","explanation":"Both gastric mixing and colonic motility are influenced by similar neural control mechanisms, including the enteric nervous system.","kind":"integration","linkedModuleIds":["colonic-motility-defecation"],"origin":"ai"}],"gastric-emptying-feedback":[{"id":"gastric-emptying-feedback~ai-0","moduleId":"gastric-emptying-feedback","stem":"Which factor primarily inhibits gastric emptying?","options":[{"id":"a","text":"Gastric distension"},{"id":"b","text":"Duodenal acid"},{"id":"c","text":"Gastrin"},{"id":"d","text":"Proximal gastric tone"}],"answerId":"b","explanation":"Duodenal acid is a key factor that inhibits gastric emptying to allow for proper digestion.","kind":"recall","origin":"ai"},{"id":"gastric-emptying-feedback~ai-1","moduleId":"gastric-emptying-feedback","stem":"What is the role of CCK in gastric emptying?","options":[{"id":"a","text":"Accelerates gastric emptying"},{"id":"b","text":"Inhibits gastric emptying"},{"id":"c","text":"Has no effect on gastric emptying"},{"id":"d","text":"Stimulates gastric acid secretion"}],"answerId":"b","explanation":"CCK inhibits gastric emptying while promoting pancreatic enzyme release and gallbladder contraction.","kind":"mechanism","origin":"ai"},{"id":"gastric-emptying-feedback~ai-2","moduleId":"gastric-emptying-feedback","stem":"A patient experiences early dumping syndrome after gastric surgery. What is the underlying mechanism?","options":[{"id":"a","text":"Loss of pyloric control"},{"id":"b","text":"Increased gastric acid secretion"},{"id":"c","text":"Enhanced gastric emptying"},{"id":"d","text":"Decreased duodenal motility"}],"answerId":"a","explanation":"Early dumping syndrome is caused by the loss of pyloric control, leading to rapid delivery of hyperosmotic chyme to the duodenum.","kind":"clinical","origin":"ai"},{"id":"gastric-emptying-feedback~ai-3","moduleId":"gastric-emptying-feedback","stem":"Which of the following meals would empty the slowest from the stomach?","options":[{"id":"a","text":"Carbohydrate solution"},{"id":"b","text":"Protein-rich meal"},{"id":"c","text":"Fatty meal"},{"id":"d","text":"Clear liquid"}],"answerId":"c","explanation":"A fatty meal empties more slowly due to strong CCK release and inhibitory feedback.","kind":"recall","origin":"ai"},{"id":"gastric-emptying-feedback~ai-4","moduleId":"gastric-emptying-feedback","stem":"Which statement about gastric emptying is true?","options":[{"id":"a","text":"Liquids empty slower than solids"},{"id":"b","text":"Gastric distension inhibits gastric emptying"},{"id":"c","text":"Duodenal fat accelerates gastric emptying"},{"id":"d","text":"Gastrin inhibits pyloric pump activity"}],"answerId":"b","explanation":"Gastric distension promotes gastric emptying, while duodenal fat and other factors inhibit it.","kind":"trap","origin":"ai"},{"id":"gastric-emptying-feedback~ai-5","moduleId":"gastric-emptying-feedback","stem":"How does gastric emptying relate to small intestinal motility?","options":[{"id":"a","text":"Gastric emptying is independent of small intestinal motility"},{"id":"b","text":"Increased gastric emptying enhances small intestinal segmentation"},{"id":"c","text":"Slow gastric emptying promotes peristalsis in the small intestine"},{"id":"d","text":"Rapid gastric emptying decreases small intestinal motility"}],"answerId":"b","explanation":"Increased gastric emptying allows for enhanced segmentation and mixing in the small intestine, optimizing digestion.","kind":"integration","linkedModuleIds":["small-intestinal-motility"],"origin":"ai"},{"id":"gastric-emptying-feedback~ai-6","moduleId":"gastric-emptying-feedback","stem":"What feedback mechanism regulates gastric emptying based on duodenal contents?","options":[{"id":"a","text":"Neural reflexes only"},{"id":"b","text":"Hormonal feedback only"},{"id":"c","text":"Combined neural and hormonal feedback"},{"id":"d","text":"No feedback mechanism exists"}],"answerId":"c","explanation":"Both neural and hormonal feedback mechanisms, especially involving CCK, regulate gastric emptying based on duodenal contents.","kind":"integration","linkedModuleIds":["gastric-accommodation-mixing"],"origin":"ai"}],"integrated-meal-response":[{"id":"integrated-meal-response~ai-0","moduleId":"integrated-meal-response","stem":"What initiates the cephalic phase of digestion?","options":[{"id":"a","text":"Gastric distension"},{"id":"b","text":"Vagal signals from sight and smell"},{"id":"c","text":"Presence of food in the duodenum"},{"id":"d","text":"Release of CCK"}],"answerId":"b","explanation":"The cephalic phase is triggered by sensory stimuli such as sight, smell, and taste, which activate vagal signals.","kind":"recall","origin":"ai"},{"id":"integrated-meal-response~ai-1","moduleId":"integrated-meal-response","stem":"Which hormone is primarily responsible for stimulating gallbladder contraction?","options":[{"id":"a","text":"Gastrin"},{"id":"b","text":"Secretin"},{"id":"c","text":"CCK"},{"id":"d","text":"GIP"}],"answerId":"c","explanation":"Cholecystokinin (CCK) stimulates gallbladder contraction and bile release in response to fats in the intestine.","kind":"mechanism","origin":"ai"},{"id":"integrated-meal-response~ai-2","moduleId":"integrated-meal-response","stem":"What is the primary mechanism by which CCK reduces gastric emptying?","options":[{"id":"a","text":"Increased gastric acid secretion"},{"id":"b","text":"Inhibition of gastric motility"},{"id":"c","text":"Stimulation of gastric distension"},{"id":"d","text":"Promotion of insulin release"}],"answerId":"b","explanation":"CCK inhibits gastric motility, leading to reduced gastric emptying, especially after fat ingestion.","kind":"mechanism","origin":"ai"},{"id":"integrated-meal-response~ai-3","moduleId":"integrated-meal-response","stem":"Which of the following findings would indicate reduced gastric emptying?","options":[{"id":"a","text":"Increased gastric acid secretion"},{"id":"b","text":"Increased CCK levels"},{"id":"c","text":"Increased gastric distension"},{"id":"d","text":"Increased insulin response"}],"answerId":"b","explanation":"Increased levels of CCK after fat intake signal reduced gastric emptying to match digestive capacity.","kind":"recall","origin":"ai"},{"id":"integrated-meal-response~ai-4","moduleId":"integrated-meal-response","stem":"After a meal, long-chain lipids are absorbed into the body through which structure?","options":[{"id":"a","text":"Portal capillaries"},{"id":"b","text":"Lacteals"},{"id":"c","text":"Intestinal capillaries"},{"id":"d","text":"Hepatic veins"}],"answerId":"b","explanation":"Long-chain lipids are packaged into chylomicrons and enter the lymphatic system via lacteals before reaching the bloodstream.","kind":"trap","origin":"ai"},{"id":"integrated-meal-response~ai-5","moduleId":"integrated-meal-response","stem":"How does the incretin effect influence insulin secretion?","options":[{"id":"a","text":"Increases insulin secretion after IV glucose"},{"id":"b","text":"Decreases insulin secretion after oral glucose"},{"id":"c","text":"Increases insulin secretion after oral glucose"},{"id":"d","text":"No effect on insulin secretion"}],"answerId":"c","explanation":"The incretin effect refers to the greater insulin response to oral glucose compared to IV glucose, mediated by GIP and GLP-1.","kind":"clinical","origin":"ai"},{"id":"integrated-meal-response~ai-6","moduleId":"integrated-meal-response","stem":"Which hormone's action is primarily involved in the feedback inhibition of gastric emptying during the intestinal phase?","options":[{"id":"a","text":"Gastrin"},{"id":"b","text":"Secretin"},{"id":"c","text":"CCK"},{"id":"d","text":"GIP"}],"answerId":"c","explanation":"CCK plays a key role in feedback inhibition of gastric emptying during the intestinal phase, especially in response to fats.","kind":"integration","linkedModuleIds":["blood-glucose-homeostasis"],"origin":"ai"},{"id":"integrated-meal-response~ai-7","moduleId":"integrated-meal-response","stem":"Which process is primarily responsible for the absorption of glucose in the intestine?","options":[{"id":"a","text":"Facilitated diffusion"},{"id":"b","text":"Active transport"},{"id":"c","text":"Simple diffusion"},{"id":"d","text":"Endocytosis"}],"answerId":"b","explanation":"Glucose is primarily absorbed via active transport mechanisms in the intestinal epithelium, often coupled with sodium.","kind":"integration","linkedModuleIds":["blood-glucose-homeostasis"],"origin":"ai"}],"salivary-esophageal-mucus-secretion":[{"id":"salivary-esophageal-mucus-secretion~ai-0","moduleId":"salivary-esophageal-mucus-secretion","stem":"What is the primary function of acinar cells in salivary glands?","options":[{"id":"a","text":"Secretion of mucins"},{"id":"b","text":"Production of isotonic primary saliva"},{"id":"c","text":"Reabsorption of sodium"},{"id":"d","text":"Secretion of bicarbonate"}],"answerId":"b","explanation":"Acinar cells produce an isotonic primary saliva containing various enzymes and ions.","kind":"recall","origin":"ai"},{"id":"salivary-esophageal-mucus-secretion~ai-1","moduleId":"salivary-esophageal-mucus-secretion","stem":"Which of the following statements about final saliva is true?","options":[{"id":"a","text":"It is hypertonic due to high NaCl concentration."},{"id":"b","text":"It is isotonic due to equal reabsorption of water and solutes."},{"id":"c","text":"It is hypotonic due to ductal reabsorption of Na⁺/Cl⁻."},{"id":"d","text":"It is always rich in bicarbonate."}],"answerId":"c","explanation":"Final saliva is hypotonic because ducts absorb Na⁺/Cl⁻ but are poorly permeable to water.","kind":"trap","origin":"ai"},{"id":"salivary-esophageal-mucus-secretion~ai-2","moduleId":"salivary-esophageal-mucus-secretion","stem":"What effect does parasympathetic stimulation have on salivary secretion?","options":[{"id":"a","text":"Increases protein-rich secretion"},{"id":"b","text":"Decreases saliva production"},{"id":"c","text":"Increases copious watery secretion"},{"id":"d","text":"Increases mucin secretion only"}],"answerId":"c","explanation":"Parasympathetic stimulation leads to copious watery secretion from salivary glands.","kind":"mechanism","origin":"ai"},{"id":"salivary-esophageal-mucus-secretion~ai-3","moduleId":"salivary-esophageal-mucus-secretion","stem":"A patient presents with dry mouth and difficulty swallowing. What is the most likely underlying cause?","options":[{"id":"a","text":"Increased salivary flow"},{"id":"b","text":"Loss of salivary lubrication"},{"id":"c","text":"Increased mucin secretion"},{"id":"d","text":"Decreased sodium reabsorption"}],"answerId":"b","explanation":"Dry mouth is caused by loss of salivary lubrication, buffering, and antimicrobial protection.","kind":"clinical","origin":"ai"},{"id":"salivary-esophageal-mucus-secretion~ai-4","moduleId":"salivary-esophageal-mucus-secretion","stem":"During high salivary flow, which electrolyte concentration is likely to be higher in saliva?","options":[{"id":"a","text":"Potassium"},{"id":"b","text":"Bicarbonate"},{"id":"c","text":"Sodium"},{"id":"d","text":"Calcium"}],"answerId":"c","explanation":"Higher salivary Na⁺ concentration occurs at high flow due to rapid transit and less time for ductal reabsorption.","kind":"recall","origin":"ai"},{"id":"salivary-esophageal-mucus-secretion~ai-5","moduleId":"salivary-esophageal-mucus-secretion","stem":"How does salivary secretion relate to gastric acid secretion?","options":[{"id":"a","text":"Both are stimulated by sympathetic nervous system."},{"id":"b","text":"Both involve ductal modification of secretions."},{"id":"c","text":"Both are primarily regulated by hormonal control."},{"id":"d","text":"Both provide lubrication to the digestive tract."}],"answerId":"d","explanation":"Both salivary and gastric secretions provide lubrication and protection to the digestive tract.","kind":"integration","linkedModuleIds":["gastric-acid-mechanism-control"],"origin":"ai"},{"id":"salivary-esophageal-mucus-secretion~ai-6","moduleId":"salivary-esophageal-mucus-secretion","stem":"Which mechanism is shared between salivary and gastric secretions?","options":[{"id":"a","text":"Both secrete mucins."},{"id":"b","text":"Both are isotonic at final secretion."},{"id":"c","text":"Both are influenced by parasympathetic stimulation."},{"id":"d","text":"Both involve acinar cell secretion."}],"answerId":"c","explanation":"Both salivary and gastric secretions are influenced by parasympathetic stimulation to increase secretion.","kind":"integration","linkedModuleIds":["gastric-acid-mechanism-control"],"origin":"ai"}],"hgb-carbohydrate-digestion-absorption":[{"id":"hgb-carbohydrate-digestion-absorption~ai-0","moduleId":"hgb-carbohydrate-digestion-absorption","stem":"What enzyme is responsible for hydrolyzing internal α-1,4 bonds in starch during carbohydrate digestion?","options":[{"id":"a","text":"Salivary amylase"},{"id":"b","text":"Lactase"},{"id":"c","text":"Sucrase-isomaltase"},{"id":"d","text":"Maltase-glucoamylase"}],"answerId":"a","explanation":"Salivary amylase initiates the digestion of starch by breaking down internal α-1,4 bonds.","kind":"recall","origin":"ai"},{"id":"hgb-carbohydrate-digestion-absorption~ai-1","moduleId":"hgb-carbohydrate-digestion-absorption","stem":"Which transporter is responsible for the absorption of glucose and galactose in the intestinal epithelium?","options":[{"id":"a","text":"GLUT2"},{"id":"b","text":"GLUT5"},{"id":"c","text":"SGLT1"},{"id":"d","text":"MCT1"}],"answerId":"c","explanation":"SGLT1 is a sodium-dependent transporter that cotransports glucose and galactose along with Na⁺.","kind":"mechanism","origin":"ai"},{"id":"hgb-carbohydrate-digestion-absorption~ai-2","moduleId":"hgb-carbohydrate-digestion-absorption","stem":"A patient presents with bloating and acidic diarrhea after consuming dairy products. What is the most likely cause?","options":[{"id":"a","text":"Fructose malabsorption"},{"id":"b","text":"Lactase deficiency"},{"id":"c","text":"Celiac disease"},{"id":"d","text":"Irritable bowel syndrome"}],"answerId":"b","explanation":"Lactase deficiency leads to undigested lactose, resulting in osmotic diarrhea and fermentation.","kind":"clinical","origin":"ai"},{"id":"hgb-carbohydrate-digestion-absorption~ai-3","moduleId":"hgb-carbohydrate-digestion-absorption","stem":"Which statement correctly describes the absorption of fructose in the intestine?","options":[{"id":"a","text":"Fructose enters by Na⁺-coupled SGLT1"},{"id":"b","text":"Fructose enters through facilitative GLUT5"},{"id":"c","text":"Fructose is absorbed via active transport"},{"id":"d","text":"Fructose requires insulin for absorption"}],"answerId":"b","explanation":"Fructose is absorbed through the facilitative transporter GLUT5, not SGLT1.","kind":"trap","origin":"ai"},{"id":"hgb-carbohydrate-digestion-absorption~ai-4","moduleId":"hgb-carbohydrate-digestion-absorption","stem":"What is the primary consequence of undigested carbohydrates in the colon?","options":[{"id":"a","text":"Increased glucose absorption"},{"id":"b","text":"Osmotic diarrhea and fermentation"},{"id":"c","text":"Decreased gas production"},{"id":"d","text":"Enhanced mineral absorption"}],"answerId":"b","explanation":"Undigested carbohydrates lead to osmotic diarrhea and fermentation, causing gas and bloating.","kind":"recall","origin":"ai"},{"id":"hgb-carbohydrate-digestion-absorption~ai-5","moduleId":"hgb-carbohydrate-digestion-absorption","stem":"How does fasting affect diarrhea caused by undigested carbohydrates?","options":[{"id":"a","text":"Worsens the condition"},{"id":"b","text":"Improves diarrhea by reducing osmotic load"},{"id":"c","text":"Has no effect"},{"id":"d","text":"Increases fermentation"}],"answerId":"b","explanation":"Fasting removes the unabsorbed osmole, thereby reducing osmotic diarrhea.","kind":"clinical","origin":"ai"},{"id":"hgb-carbohydrate-digestion-absorption~ai-6","moduleId":"hgb-carbohydrate-digestion-absorption","stem":"Which process is primarily affected in a patient with lactase deficiency when consuming dairy products?","options":[{"id":"a","text":"Absorption of glucose"},{"id":"b","text":"Absorption of lactose"},{"id":"c","text":"Absorption of fructose"},{"id":"d","text":"Absorption of galactose"}],"answerId":"b","explanation":"Lactase deficiency specifically impairs the digestion and absorption of lactose, leading to symptoms.","kind":"integration","linkedModuleIds":["hgb-lipid-digestion-absorption"],"origin":"ai"},{"id":"hgb-carbohydrate-digestion-absorption~ai-7","moduleId":"hgb-carbohydrate-digestion-absorption","stem":"In the context of carbohydrate digestion, what is the role of GLUT2?","options":[{"id":"a","text":"Transport of glucose into the intestinal lumen"},{"id":"b","text":"Transport of monosaccharides into portal circulation"},{"id":"c","text":"Facilitating fructose absorption"},{"id":"d","text":"Cotransport of glucose with Na⁺"}],"answerId":"b","explanation":"GLUT2 is responsible for transporting monosaccharides from the intestinal cells into the portal blood.","kind":"integration","linkedModuleIds":["mineral-water-absorption"],"origin":"ai"}],"intestinal-fluid-secretion":[{"id":"intestinal-fluid-secretion~ai-0","moduleId":"intestinal-fluid-secretion","stem":"What is the primary mechanism by which crypt cells in the intestine secrete chloride?","options":[{"id":"a","text":"Active transport via Na⁺/K⁺ ATPase"},{"id":"b","text":"Facilitated diffusion through ion channels"},{"id":"c","text":"Apical CFTR channel activity"},{"id":"d","text":"Paracellular movement of ions"}],"answerId":"c","explanation":"Crypt cells secrete Cl⁻ through the apical CFTR channel, which is crucial for fluid secretion.","kind":"mechanism","origin":"ai"},{"id":"intestinal-fluid-secretion~ai-1","moduleId":"intestinal-fluid-secretion","stem":"Which of the following findings is characteristic of secretory diarrhea?","options":[{"id":"a","text":"Dehydration due to water loss"},{"id":"b","text":"Large-volume watery diarrhea despite fasting"},{"id":"c","text":"Presence of blood in stool"},{"id":"d","text":"Decreased bowel sounds"}],"answerId":"b","explanation":"Secretory diarrhea is characterized by large-volume watery diarrhea that persists even during fasting.","kind":"recall","origin":"ai"},{"id":"intestinal-fluid-secretion~ai-2","moduleId":"intestinal-fluid-secretion","stem":"What is the role of bicarbonate in colonic mucus secretion?","options":[{"id":"a","text":"Enhances nutrient absorption"},{"id":"b","text":"Neutralizes bacterial acids"},{"id":"c","text":"Stimulates chloride secretion"},{"id":"d","text":"Increases water reabsorption"}],"answerId":"b","explanation":"Bicarbonate in colonic mucus helps neutralize bacterial acids, protecting the intestinal lining.","kind":"recall","origin":"ai"},{"id":"intestinal-fluid-secretion~ai-3","moduleId":"intestinal-fluid-secretion","stem":"Which of the following statements about oral rehydration therapy is true?","options":[{"id":"a","text":"Plain water is sufficient for rehydration"},{"id":"b","text":"Glucose–electrolyte solutions exploit SGLT1-mediated uptake"},{"id":"c","text":"Electrolytes alone are adequate"},{"id":"d","text":"Rehydration is ineffective during ongoing secretion"}],"answerId":"b","explanation":"Glucose–electrolyte solutions utilize SGLT1-mediated sodium uptake, providing an effective osmotic route for water recovery.","kind":"trap","origin":"ai"},{"id":"intestinal-fluid-secretion~ai-4","moduleId":"intestinal-fluid-secretion","stem":"Which second messenger is NOT typically involved in enhancing intestinal fluid secretion?","options":[{"id":"a","text":"cAMP"},{"id":"b","text":"cGMP"},{"id":"c","text":"Calcium ions"},{"id":"d","text":"Inositol trisphosphate"}],"answerId":"d","explanation":"While cAMP, cGMP, and calcium ions enhance secretion, inositol trisphosphate is not a primary second messenger in this context.","kind":"mechanism","origin":"ai"},{"id":"intestinal-fluid-secretion~ai-5","moduleId":"intestinal-fluid-secretion","stem":"How does enterotoxin-induced diarrhea persist during fasting?","options":[{"id":"a","text":"Increased absorption of nutrients"},{"id":"b","text":"Locking of second-messenger pathways"},{"id":"c","text":"Decreased secretion of electrolytes"},{"id":"d","text":"Increased mucus production"}],"answerId":"b","explanation":"Enterotoxins can lock second-messenger pathways, leading to persistent high-volume secretion despite fasting.","kind":"mechanism","origin":"ai"},{"id":"intestinal-fluid-secretion~ai-6","moduleId":"intestinal-fluid-secretion","stem":"How does the mechanism of fluid secretion in the intestines relate to gastric acid secretion?","options":[{"id":"a","text":"Both involve the same ion channels"},{"id":"b","text":"Both are regulated by the same hormones"},{"id":"c","text":"Both utilize Na⁺/K⁺ ATPase for secretion"},{"id":"d","text":"Both involve paracellular transport mechanisms"}],"answerId":"a","explanation":"Fluid secretion in the intestines and gastric acid secretion both involve ion channels, although the specific channels differ.","kind":"integration","linkedModuleIds":["gastric-acid-mechanism-control"],"origin":"ai"},{"id":"intestinal-fluid-secretion~ai-7","moduleId":"intestinal-fluid-secretion","stem":"What common mechanism links the absorption processes in the intestines and the secretion of gastric enzymes?","options":[{"id":"a","text":"Active transport of sodium"},{"id":"b","text":"Facilitated diffusion of glucose"},{"id":"c","text":"Paracellular absorption of water"},{"id":"d","text":"Endocytosis of nutrients"}],"answerId":"a","explanation":"Both intestinal absorption and gastric enzyme secretion rely on active transport mechanisms, particularly involving sodium.","kind":"integration","linkedModuleIds":["gastric-enzymes-intrinsic-barrier"],"origin":"ai"}],"gi-hormones-paracrines-neurocrines":[{"id":"gi-hormones-paracrines-neurocrines~ai-0","moduleId":"gi-hormones-paracrines-neurocrines","stem":"What is the primary action of gastrin in the gastrointestinal tract?","options":[{"id":"a","text":"Stimulates insulin release"},{"id":"b","text":"Increases gastric acid secretion"},{"id":"c","text":"Inhibits gastric motility"},{"id":"d","text":"Stimulates bile production"}],"answerId":"b","explanation":"Gastrin primarily stimulates gastric acid secretion and promotes mucosal growth.","kind":"recall","origin":"ai"},{"id":"gi-hormones-paracrines-neurocrines~ai-1","moduleId":"gi-hormones-paracrines-neurocrines","stem":"Which hormone is released in response to duodenal acid and stimulates bicarbonate secretion?","options":[{"id":"a","text":"Gastrin"},{"id":"b","text":"Secretin"},{"id":"c","text":"Cholecystokinin"},{"id":"d","text":"Motilin"}],"answerId":"b","explanation":"Secretin is released by S cells in the duodenum in response to acidic chyme and stimulates bicarbonate secretion from the pancreas.","kind":"recall","origin":"ai"},{"id":"gi-hormones-paracrines-neurocrines~ai-2","moduleId":"gi-hormones-paracrines-neurocrines","stem":"What is the mechanism of action of cholecystokinin (CCK)?","options":[{"id":"a","text":"Inhibits gastric emptying"},{"id":"b","text":"Stimulates gastric acid secretion"},{"id":"c","text":"Increases motility of the small intestine"},{"id":"d","text":"Inhibits bile secretion"}],"answerId":"a","explanation":"CCK slows gastric emptying while stimulating gallbladder contraction and pancreatic enzyme secretion.","kind":"mechanism","origin":"ai"},{"id":"gi-hormones-paracrines-neurocrines~ai-3","moduleId":"gi-hormones-paracrines-neurocrines","stem":"A patient presents with abdominal pain after eating a fatty meal. Which finding would indicate normal gallbladder function?","options":[{"id":"a","text":"Increased gastric acid secretion"},{"id":"b","text":"Gallbladder contraction"},{"id":"c","text":"Decreased pancreatic enzyme secretion"},{"id":"d","text":"Increased gastric motility"}],"answerId":"b","explanation":"Gallbladder contraction after a fatty meal is a normal response mediated by CCK.","kind":"clinical","origin":"ai"},{"id":"gi-hormones-paracrines-neurocrines~ai-4","moduleId":"gi-hormones-paracrines-neurocrines","stem":"Which of the following statements about GIP is true?","options":[{"id":"a","text":"GIP stimulates insulin release regardless of blood glucose levels"},{"id":"b","text":"GIP enhances glucose-dependent insulin secretion"},{"id":"c","text":"GIP inhibits gastric acid secretion"},{"id":"d","text":"GIP is released in response to gastric distension"}],"answerId":"b","explanation":"GIP enhances glucose-dependent insulin secretion after oral nutrient intake, limiting insulin release when glycemia is low.","kind":"trap","origin":"ai"},{"id":"gi-hormones-paracrines-neurocrines~ai-5","moduleId":"gi-hormones-paracrines-neurocrines","stem":"How does motilin affect gastrointestinal motility?","options":[{"id":"a","text":"Increases gastric acid secretion"},{"id":"b","text":"Stimulates the migrating motor complex"},{"id":"c","text":"Inhibits intestinal peristalsis"},{"id":"d","text":"Stimulates insulin secretion"}],"answerId":"b","explanation":"Motilin organizes the fasting migrating motor complex, enhancing gastrointestinal motility during fasting.","kind":"recall","origin":"ai"},{"id":"gi-hormones-paracrines-neurocrines~ai-6","moduleId":"gi-hormones-paracrines-neurocrines","stem":"How does the enteric nervous system influence GI hormone release?","options":[{"id":"a","text":"By directly stimulating gastric acid secretion"},{"id":"b","text":"By modulating the secretion of hormones like gastrin and CCK"},{"id":"c","text":"By inhibiting pancreatic enzyme release"},{"id":"d","text":"By promoting bile synthesis in the liver"}],"answerId":"b","explanation":"The enteric nervous system modulates hormone secretion, including gastrin and CCK, in response to luminal nutrients.","kind":"integration","linkedModuleIds":["enteric-autonomic-reflex-control"],"origin":"ai"},{"id":"gi-hormones-paracrines-neurocrines~ai-7","moduleId":"gi-hormones-paracrines-neurocrines","stem":"What role do slow waves play in gastrointestinal motility?","options":[{"id":"a","text":"They directly stimulate hormone release"},{"id":"b","text":"They coordinate the contraction of smooth muscle"},{"id":"c","text":"They inhibit gastric acid secretion"},{"id":"d","text":"They enhance bile production"}],"answerId":"b","explanation":"Slow waves coordinate the contraction of smooth muscle in the GI tract, facilitating motility.","kind":"integration","linkedModuleIds":["gi-smooth-muscle-electrical-activity"],"origin":"ai"}],"protein-nucleic-acid-digestion":[{"id":"protein-nucleic-acid-digestion~ai-0","moduleId":"protein-nucleic-acid-digestion","stem":"Which enzyme initiates protein digestion in the stomach?","options":[{"id":"a","text":"Pepsin"},{"id":"b","text":"Trypsin"},{"id":"c","text":"Chymotrypsin"},{"id":"d","text":"Carboxypeptidase"}],"answerId":"a","explanation":"Pepsin is the primary enzyme that begins the digestion of proteins in the acidic environment of the stomach.","kind":"recall","origin":"ai"},{"id":"protein-nucleic-acid-digestion~ai-1","moduleId":"protein-nucleic-acid-digestion","stem":"What activates trypsinogen in the small intestine?","options":[{"id":"a","text":"Pepsin"},{"id":"b","text":"Enteropeptidase"},{"id":"c","text":"Chymotrypsin"},{"id":"d","text":"Carboxypeptidase"}],"answerId":"b","explanation":"Enteropeptidase is responsible for converting trypsinogen to its active form, trypsin, in the small intestine.","kind":"mechanism","origin":"ai"},{"id":"protein-nucleic-acid-digestion~ai-2","moduleId":"protein-nucleic-acid-digestion","stem":"Which of the following statements about protein absorption is true?","options":[{"id":"a","text":"Only free amino acids cross the apical enterocyte membrane"},{"id":"b","text":"PepT1 absorbs di- and tripeptides"},{"id":"c","text":"Amino acids are absorbed exclusively via passive diffusion"},{"id":"d","text":"All peptides are hydrolyzed before absorption"}],"answerId":"b","explanation":"PepT1 is a transporter that efficiently absorbs di- and tripeptides in addition to amino acids.","kind":"trap","origin":"ai"},{"id":"protein-nucleic-acid-digestion~ai-3","moduleId":"protein-nucleic-acid-digestion","stem":"What is the primary consequence of pancreatic exocrine failure?","options":[{"id":"a","text":"Increased protein absorption"},{"id":"b","text":"Protein maldigestion"},{"id":"c","text":"Enhanced lipid digestion"},{"id":"d","text":"Decreased nucleic acid absorption"}],"answerId":"b","explanation":"Pancreatic exocrine failure leads to reduced delivery of proteases, resulting in protein maldigestion.","kind":"clinical","origin":"ai"},{"id":"protein-nucleic-acid-digestion~ai-4","moduleId":"protein-nucleic-acid-digestion","stem":"Which pancreatic enzyme is activated by trypsin?","options":[{"id":"a","text":"Chymotrypsinogen"},{"id":"b","text":"Proelastase"},{"id":"c","text":"Procarboxypeptidase"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"Trypsin activates multiple zymogens, including chymotrypsinogen, proelastase, and procarboxypeptidases.","kind":"mechanism","origin":"ai"},{"id":"protein-nucleic-acid-digestion~ai-5","moduleId":"protein-nucleic-acid-digestion","stem":"How do pancreatic nucleases contribute to nucleic acid digestion?","options":[{"id":"a","text":"They hydrolyze proteins"},{"id":"b","text":"They reduce nucleic acids to bases and sugars"},{"id":"c","text":"They activate proteases"},{"id":"d","text":"They absorb nucleotides directly"}],"answerId":"b","explanation":"Pancreatic nucleases break down nucleic acids into absorbable components such as bases, pentoses, and phosphate.","kind":"recall","origin":"ai"},{"id":"protein-nucleic-acid-digestion~ai-6","moduleId":"protein-nucleic-acid-digestion","stem":"How does protein digestion relate to carbohydrate digestion in the small intestine?","options":[{"id":"a","text":"Both processes rely on the same enzymes"},{"id":"b","text":"Both involve zymogen activation"},{"id":"c","text":"Both are primarily absorbed as monosaccharides"},{"id":"d","text":"Both processes are facilitated by brush-border enzymes"}],"answerId":"d","explanation":"Both protein and carbohydrate digestion involve brush-border enzymes that facilitate the final steps of digestion and absorption.","kind":"integration","linkedModuleIds":["hgb-carbohydrate-digestion-absorption"],"origin":"ai"},{"id":"protein-nucleic-acid-digestion~ai-7","moduleId":"protein-nucleic-acid-digestion","stem":"What is a common feature of protein and lipid digestion in the small intestine?","options":[{"id":"a","text":"Both are initiated in the stomach"},{"id":"b","text":"Both processes require bile salts"},{"id":"c","text":"Both involve zymogen activation"},{"id":"d","text":"Both are absorbed as free monomers only"}],"answerId":"c","explanation":"Both protein and lipid digestion involve the activation of zymogens to their active forms in the small intestine.","kind":"integration","linkedModuleIds":["hgb-lipid-digestion-absorption"],"origin":"ai"}],"small-intestinal-motility":[{"id":"small-intestinal-motility~ai-0","moduleId":"small-intestinal-motility","stem":"What is the primary function of segmentation in the small intestine?","options":[{"id":"a","text":"Propulsion of chyme aborally"},{"id":"b","text":"Mixing chyme with digestive secretions"},{"id":"c","text":"Absorption of nutrients"},{"id":"d","text":"Regulation of gastric emptying"}],"answerId":"b","explanation":"Segmentation primarily serves to mix chyme with digestive secretions and expose it to the absorptive mucosa.","kind":"recall","origin":"ai"},{"id":"small-intestinal-motility~ai-1","moduleId":"small-intestinal-motility","stem":"Which mechanism triggers peristalsis in the small intestine?","options":[{"id":"a","text":"Increased motilin levels"},{"id":"b","text":"Ileal distension"},{"id":"c","text":"Gastric emptying"},{"id":"d","text":"Cyclic fasting contractions"}],"answerId":"b","explanation":"Ileal distension promotes peristalsis by triggering contraction behind and relaxation ahead of a bolus.","kind":"mechanism","origin":"ai"},{"id":"small-intestinal-motility~ai-2","moduleId":"small-intestinal-motility","stem":"What clinical finding is associated with segmentation in the small intestine?","options":[{"id":"a","text":"Continuous forward transit of contents"},{"id":"b","text":"Alternating contractions without major forward transit"},{"id":"c","text":"Increased tone of the ileocecal sphincter"},{"id":"d","text":"Absence of chyme mixing"}],"answerId":"b","explanation":"Segmentation is characterized by alternating contractions that mix chyme locally without significant forward transit.","kind":"recall","origin":"ai"},{"id":"small-intestinal-motility~ai-3","moduleId":"small-intestinal-motility","stem":"During fasting, what is the role of the migrating motor complex (MMC)?","options":[{"id":"a","text":"Facilitates absorption of nutrients"},{"id":"b","text":"Promotes segmentation of chyme"},{"id":"c","text":"Sweeps residual material and bacteria distally"},{"id":"d","text":"Increases gastric emptying rate"}],"answerId":"c","explanation":"The MMC sweeps residual material and bacteria distally about every 90–120 minutes during fasting.","kind":"recall","origin":"ai"},{"id":"small-intestinal-motility~ai-4","moduleId":"small-intestinal-motility","stem":"What is a common misconception about segmentation in the small intestine?","options":[{"id":"a","text":"It is the main rapid propulsive pattern"},{"id":"b","text":"It primarily mixes chyme"},{"id":"c","text":"It occurs only during fasting"},{"id":"d","text":"It is triggered by gastric emptying"}],"answerId":"a","explanation":"Segmentation mainly mixes chyme; peristalsis and the MMC are responsible for propulsion.","kind":"trap","origin":"ai"},{"id":"small-intestinal-motility~ai-5","moduleId":"small-intestinal-motility","stem":"How does the ileocecal sphincter respond to ileal distension?","options":[{"id":"a","text":"Increases its tone"},{"id":"b","text":"Relaxes"},{"id":"c","text":"Remains unchanged"},{"id":"d","text":"Contracts vigorously"}],"answerId":"b","explanation":"Ileal distension promotes relaxation of the ileocecal sphincter to allow passage into the cecum.","kind":"mechanism","origin":"ai"},{"id":"small-intestinal-motility~ai-6","moduleId":"small-intestinal-motility","stem":"How does small intestinal motility relate to colonic motility during digestion?","options":[{"id":"a","text":"Segmentation is the main propulsive mechanism in both"},{"id":"b","text":"Peristalsis in the small intestine is absent in the colon"},{"id":"c","text":"The MMC in the small intestine influences mass movements in the colon"},{"id":"d","text":"Ileocecal sphincter tone is irrelevant to colonic function"}],"answerId":"c","explanation":"The MMC in the small intestine helps regulate the timing and initiation of mass movements in the colon.","kind":"integration","linkedModuleIds":["colonic-motility-defecation"],"origin":"ai"},{"id":"small-intestinal-motility~ai-7","moduleId":"small-intestinal-motility","stem":"What is the relationship between small intestinal motility and gastric emptying?","options":[{"id":"a","text":"Segmentation enhances gastric emptying"},{"id":"b","text":"Peristalsis slows gastric emptying"},{"id":"c","text":"The MMC affects gastric emptying timing"},{"id":"d","text":"Ileocecal sphincter regulates gastric emptying"}],"answerId":"c","explanation":"The MMC affects the timing of gastric emptying by coordinating the digestive processes between the stomach and small intestine.","kind":"integration","linkedModuleIds":["gastric-emptying-feedback"],"origin":"ai"}],"colonic-motility-defecation":[{"id":"colonic-motility-defecation~ai-0","moduleId":"colonic-motility-defecation","stem":"What type of contraction primarily facilitates water and electrolyte absorption in the colon?","options":[{"id":"a","text":"Haustral contractions"},{"id":"b","text":"Peristaltic contractions"},{"id":"c","text":"Mass movements"},{"id":"d","text":"Segmenting contractions"}],"answerId":"a","explanation":"Haustral contractions mix colonic contents and enhance absorption of water and electrolytes.","kind":"recall","origin":"ai"},{"id":"colonic-motility-defecation~ai-1","moduleId":"colonic-motility-defecation","stem":"Which reflex is triggered by rectal distension during defecation?","options":[{"id":"a","text":"Gastrocolic reflex"},{"id":"b","text":"Rectoanal inhibitory reflex"},{"id":"c","text":"Duodenocolic reflex"},{"id":"d","text":"Peritoneal reflex"}],"answerId":"b","explanation":"The rectoanal inhibitory reflex allows for the relaxation of the internal anal sphincter during defecation.","kind":"recall","origin":"ai"},{"id":"colonic-motility-defecation~ai-2","moduleId":"colonic-motility-defecation","stem":"What is the primary muscle type of the internal anal sphincter?","options":[{"id":"a","text":"Skeletal muscle"},{"id":"b","text":"Smooth muscle"},{"id":"c","text":"Cardiac muscle"},{"id":"d","text":"Striated muscle"}],"answerId":"b","explanation":"The internal anal sphincter is composed of smooth muscle, which is under involuntary control.","kind":"recall","origin":"ai"},{"id":"colonic-motility-defecation~ai-3","moduleId":"colonic-motility-defecation","stem":"In Hirschsprung disease, what is the consequence of absent rectoanal inhibitory reflex?","options":[{"id":"a","text":"Increased colonic motility"},{"id":"b","text":"Inability to relax the internal sphincter"},{"id":"c","text":"Loss of voluntary control of defecation"},{"id":"d","text":"Decreased rectal sensation"}],"answerId":"b","explanation":"Absence of the rectoanal inhibitory reflex leads to failure of internal sphincter relaxation, causing obstruction.","kind":"clinical","origin":"ai"},{"id":"colonic-motility-defecation~ai-4","moduleId":"colonic-motility-defecation","stem":"Which statement about anal sphincter control is correct?","options":[{"id":"a","text":"Both anal sphincters are smooth muscle under autonomic control"},{"id":"b","text":"The internal sphincter is skeletal muscle"},{"id":"c","text":"The external sphincter is smooth muscle under pudendal control"},{"id":"d","text":"The external sphincter is skeletal muscle under pudendal control"}],"answerId":"d","explanation":"The external anal sphincter is skeletal muscle and is under voluntary control via the pudendal nerve.","kind":"trap","origin":"ai"},{"id":"colonic-motility-defecation~ai-5","moduleId":"colonic-motility-defecation","stem":"How does a meal influence colonic motility?","options":[{"id":"a","text":"Inhibits mass movements"},{"id":"b","text":"Stimulates the gastrocolic reflex"},{"id":"c","text":"Decreases rectal pressure"},{"id":"d","text":"Increases segmentation contractions only"}],"answerId":"b","explanation":"A meal stimulates the gastrocolic reflex, which increases colonic mass movements to facilitate defecation.","kind":"mechanism","origin":"ai"},{"id":"colonic-motility-defecation~ai-6","moduleId":"colonic-motility-defecation","stem":"How does colonic motility relate to small intestinal motility during digestion?","options":[{"id":"a","text":"Colonic motility is independent of small intestinal motility"},{"id":"b","text":"Both are regulated by the same neural pathways"},{"id":"c","text":"Colonic motility decreases after small intestinal absorption"},{"id":"d","text":"Colonic motility is enhanced by small intestinal segmentation"}],"answerId":"c","explanation":"Colonic motility increases after small intestinal absorption, as the colon prepares for the next phase of digestion.","kind":"integration","linkedModuleIds":["small-intestinal-motility"],"origin":"ai"},{"id":"colonic-motility-defecation~ai-7","moduleId":"colonic-motility-defecation","stem":"What is the relationship between gastric mixing and colonic mass movements?","options":[{"id":"a","text":"Gastric mixing decreases colonic mass movements"},{"id":"b","text":"Gastric mixing has no effect on colonic motility"},{"id":"c","text":"Gastric mixing enhances colonic mass movements"},{"id":"d","text":"Gastric mixing is solely responsible for initiating colonic contractions"}],"answerId":"c","explanation":"Gastric mixing and retropulsion can enhance colonic mass movements through reflex pathways.","kind":"integration","linkedModuleIds":["gastric-accommodation-mixing"],"origin":"ai"}],"gastric-acid-mechanism-control":[{"id":"gastric-acid-mechanism-control~ai-0","moduleId":"gastric-acid-mechanism-control","stem":"What is the primary mechanism by which histamine stimulates gastric acid secretion?","options":[{"id":"a","text":"Directly opens an apical proton channel"},{"id":"b","text":"Activates H2–Gs–cAMP signaling"},{"id":"c","text":"Inhibits somatostatin release"},{"id":"d","text":"Increases bicarbonate secretion"}],"answerId":"b","explanation":"Histamine activates H2 receptors, which stimulate cAMP production, enhancing H⁺/K⁺-ATPase activity for acid secretion.","kind":"mechanism","origin":"ai"},{"id":"gastric-acid-mechanism-control~ai-1","moduleId":"gastric-acid-mechanism-control","stem":"Which of the following substances inhibits gastric acid secretion?","options":[{"id":"a","text":"Gastrin"},{"id":"b","text":"Acetylcholine"},{"id":"c","text":"Somatostatin"},{"id":"d","text":"Histamine"}],"answerId":"c","explanation":"Somatostatin inhibits gastric acid secretion by acting on parietal cells and reducing histamine release.","kind":"recall","origin":"ai"},{"id":"gastric-acid-mechanism-control~ai-2","moduleId":"gastric-acid-mechanism-control","stem":"What clinical finding indicates a postprandial alkaline tide?","options":[{"id":"a","text":"Increased gastric acid secretion"},{"id":"b","text":"Postprandial rise in gastric venous bicarbonate"},{"id":"c","text":"Decreased gastric pH"},{"id":"d","text":"Increased gastric mucosal blood flow"}],"answerId":"b","explanation":"The postprandial rise in gastric venous bicarbonate is due to Cl⁻/HCO₃⁻ exchange in parietal cells.","kind":"clinical","origin":"ai"},{"id":"gastric-acid-mechanism-control~ai-3","moduleId":"gastric-acid-mechanism-control","stem":"Which statement about proton-pump inhibitors is true?","options":[{"id":"a","text":"They directly neutralize gastric acid"},{"id":"b","text":"They inhibit H⁺/K⁺-ATPase activity"},{"id":"c","text":"They stimulate gastrin release"},{"id":"d","text":"They increase gastric mucosal blood flow"}],"answerId":"b","explanation":"Proton-pump inhibitors block the H⁺/K⁺-ATPase, leading to marked acid suppression.","kind":"trap","origin":"ai"},{"id":"gastric-acid-mechanism-control~ai-4","moduleId":"gastric-acid-mechanism-control","stem":"Which of the following is a consequence of increased gastric acid secretion?","options":[{"id":"a","text":"Increased duodenal pH"},{"id":"b","text":"Decreased gastric mucosal blood flow"},{"id":"c","text":"Increased gastric motility"},{"id":"d","text":"Increased bicarbonate secretion"}],"answerId":"c","explanation":"Increased gastric acid secretion can enhance gastric motility as part of digestive processes.","kind":"clinical","origin":"ai"},{"id":"gastric-acid-mechanism-control~ai-5","moduleId":"gastric-acid-mechanism-control","stem":"How does the mechanism of gastric acid secretion relate to the function of the pleura?","options":[{"id":"a","text":"Both involve secretion of fluids"},{"id":"b","text":"Both are regulated by neural signals"},{"id":"c","text":"Both are affected by pH changes"},{"id":"d","text":"Both involve bicarbonate transport"}],"answerId":"a","explanation":"Both gastric acid secretion and pleural fluid dynamics involve the secretion of fluids that are crucial for their respective functions.","kind":"integration","linkedModuleIds":["pleura-pleural-cavity"],"origin":"ai"},{"id":"gastric-acid-mechanism-control~ai-6","moduleId":"gastric-acid-mechanism-control","stem":"What is the role of prostaglandins in gastric acid secretion?","options":[{"id":"a","text":"Stimulate H⁺/K⁺-ATPase"},{"id":"b","text":"Inhibit acid secretion"},{"id":"c","text":"Enhance gastrin release"},{"id":"d","text":"Increase histamine production"}],"answerId":"b","explanation":"Prostaglandins inhibit gastric acid secretion and promote mucosal defense mechanisms.","kind":"recall","origin":"ai"},{"id":"gastric-acid-mechanism-control~ai-7","moduleId":"gastric-acid-mechanism-control","stem":"Which mechanism links gastric acid secretion to the function of intrinsic factor?","options":[{"id":"a","text":"Both are secreted by parietal cells"},{"id":"b","text":"Both are inhibited by somatostatin"},{"id":"c","text":"Both are stimulated by gastrin"},{"id":"d","text":"Both involve bicarbonate exchange"}],"answerId":"a","explanation":"Intrinsic factor and gastric acid are both secreted by parietal cells, essential for vitamin B12 absorption.","kind":"integration","linkedModuleIds":["gastric-enzymes-intrinsic-barrier"],"origin":"ai"}],"mineral-water-absorption":[{"id":"mineral-water-absorption~ai-0","moduleId":"mineral-water-absorption","stem":"Where is the primary site of iron absorption in the gastrointestinal tract?","options":[{"id":"a","text":"Stomach"},{"id":"b","text":"Duodenum"},{"id":"c","text":"Ileum"},{"id":"d","text":"Colon"}],"answerId":"b","explanation":"Iron is primarily absorbed in the duodenum, where DMT1 facilitates its uptake.","kind":"recall","origin":"ai"},{"id":"mineral-water-absorption~ai-1","moduleId":"mineral-water-absorption","stem":"What mechanism does calcitriol use to enhance calcium absorption?","options":[{"id":"a","text":"Increased paracellular transport"},{"id":"b","text":"Increased transcellular transport"},{"id":"c","text":"Decreased renal excretion"},{"id":"d","text":"Increased dietary intake"}],"answerId":"b","explanation":"Calcitriol enhances calcium absorption via increased transcellular transport, especially when dietary intake is low.","kind":"mechanism","origin":"ai"},{"id":"mineral-water-absorption~ai-2","moduleId":"mineral-water-absorption","stem":"What is the effect of hepcidin on iron absorption during inflammation?","options":[{"id":"a","text":"Increases ferroportin activity"},{"id":"b","text":"Decreases ferroportin activity"},{"id":"c","text":"Increases DMT1 expression"},{"id":"d","text":"Decreases iron storage"}],"answerId":"b","explanation":"Hepcidin decreases ferroportin activity, leading to reduced iron absorption during inflammation.","kind":"trap","origin":"ai"},{"id":"mineral-water-absorption~ai-3","moduleId":"mineral-water-absorption","stem":"Which of the following findings indicates reduced iron absorption?","options":[{"id":"a","text":"Increased serum ferritin"},{"id":"b","text":"Decreased serum iron"},{"id":"c","text":"Increased transferrin saturation"},{"id":"d","text":"Decreased hepcidin levels"}],"answerId":"b","explanation":"Decreased serum iron is a key indicator of reduced iron absorption, particularly during inflammatory states.","kind":"recall","origin":"ai"},{"id":"mineral-water-absorption~ai-4","moduleId":"mineral-water-absorption","stem":"How does sodium absorption in the GI tract affect water absorption?","options":[{"id":"a","text":"Increases osmotic pressure"},{"id":"b","text":"Decreases osmotic pressure"},{"id":"c","text":"Has no effect on water absorption"},{"id":"d","text":"Increases water secretion"}],"answerId":"a","explanation":"Sodium absorption creates an osmotic gradient that drives water absorption in the gastrointestinal tract.","kind":"mechanism","origin":"ai"},{"id":"mineral-water-absorption~ai-5","moduleId":"mineral-water-absorption","stem":"How does glucose-salt solution improve hydration during diarrhea?","options":[{"id":"a","text":"Increases water secretion"},{"id":"b","text":"Decreases sodium absorption"},{"id":"c","text":"Enhances SGLT1-mediated Na+ uptake"},{"id":"d","text":"Reduces osmotic pressure in the intestines"}],"answerId":"c","explanation":"Glucose-salt solution enhances SGLT1-mediated Na+ uptake, which drives water absorption and improves hydration.","kind":"clinical","origin":"ai"},{"id":"mineral-water-absorption~ai-6","moduleId":"mineral-water-absorption","stem":"Which electrolyte disturbance might be observed in a patient with chronic diarrhea?","options":[{"id":"a","text":"Hyperkalemia"},{"id":"b","text":"Hyponatremia"},{"id":"c","text":"Hypercalcemia"},{"id":"d","text":"Hypomagnesemia"}],"answerId":"b","explanation":"Chronic diarrhea can lead to hyponatremia due to excessive sodium loss.","kind":"integration","linkedModuleIds":["fluid-electrolyte-disorders"],"origin":"ai"},{"id":"mineral-water-absorption~ai-7","moduleId":"mineral-water-absorption","stem":"What is the relationship between calcium homeostasis and vitamin D?","options":[{"id":"a","text":"Vitamin D decreases calcium absorption"},{"id":"b","text":"Vitamin D enhances calcium absorption"},{"id":"c","text":"Vitamin D has no effect on calcium"},{"id":"d","text":"Vitamin D only affects phosphorus levels"}],"answerId":"b","explanation":"Vitamin D enhances calcium absorption in the intestines, playing a crucial role in calcium homeostasis.","kind":"integration","linkedModuleIds":["calcium-homeostasis-hormones"],"origin":"ai"}],"hrp1-uterus-vagina-support":[{"id":"hrp1-uterus-vagina-support~ai-0","moduleId":"hrp1-uterus-vagina-support","stem":"Which structure primarily supports the uterus in the pelvic cavity?","options":[{"id":"a","text":"Broad ligament"},{"id":"b","text":"Cardinal ligament"},{"id":"c","text":"Round ligament"},{"id":"d","text":"Ovarian ligament"}],"answerId":"b","explanation":"The cardinal ligament provides major support to the uterus, while the broad ligament is a peritoneal fold and not a strong suspensory structure.","kind":"recall","origin":"ai"},{"id":"hrp1-uterus-vagina-support~ai-1","moduleId":"hrp1-uterus-vagina-support","stem":"What is the anatomical relationship of the uterine artery to the ureter?","options":[{"id":"a","text":"Ureter passes superior to the artery"},{"id":"b","text":"Ureter passes inferior to the artery"},{"id":"c","text":"Ureter and artery are parallel"},{"id":"d","text":"Ureter is lateral to the artery"}],"answerId":"b","explanation":"The uterine artery crosses superior to the ureter, leading to the mnemonic 'water under the bridge'.","kind":"mechanism","origin":"ai"},{"id":"hrp1-uterus-vagina-support~ai-2","moduleId":"hrp1-uterus-vagina-support","stem":"A patient presents with uterine prolapse. What is the underlying mechanism?","options":[{"id":"a","text":"Increased intra-abdominal pressure"},{"id":"b","text":"Failure of pelvic floor support"},{"id":"c","text":"Uterine artery ligation"},{"id":"d","text":"Excessive round ligament tension"}],"answerId":"b","explanation":"Uterine prolapse occurs due to failure of the pelvic floor and apical fascial support, allowing the uterus to descend.","kind":"clinical","origin":"ai"},{"id":"hrp1-uterus-vagina-support~ai-3","moduleId":"hrp1-uterus-vagina-support","stem":"During a hysterectomy, the surgeon inadvertently injures the ureter. What is the most likely reason for this injury?","options":[{"id":"a","text":"Ureter passes anterior to the uterus"},{"id":"b","text":"Ureter passes inferior to the uterine artery"},{"id":"c","text":"Ureter is located lateral to the cervix"},{"id":"d","text":"Ureter is embedded in the broad ligament"}],"answerId":"b","explanation":"The ureter passes immediately inferior to the uterine artery, making it susceptible to injury during surgical procedures involving the artery.","kind":"recall","origin":"ai"},{"id":"hrp1-uterus-vagina-support~ai-4","moduleId":"hrp1-uterus-vagina-support","stem":"Which of the following statements about uterine support is FALSE?","options":[{"id":"a","text":"Cardinal ligaments provide major support"},{"id":"b","text":"Uterosacral ligaments assist in support"},{"id":"c","text":"Broad ligament is the principal load-bearing support"},{"id":"d","text":"Pelvic floor muscles contribute to support"}],"answerId":"c","explanation":"The broad ligament is a peritoneal fold and not a strong suspensory structure; the cardinal and uterosacral ligaments are the primary supports.","kind":"trap","origin":"ai"},{"id":"hrp1-uterus-vagina-support~ai-5","moduleId":"hrp1-uterus-vagina-support","stem":"How does the anatomy of the female pelvis relate to the function of the ureters?","options":[{"id":"a","text":"Ureters are lateral to the ovaries"},{"id":"b","text":"Ureters pass superior to the uterine artery"},{"id":"c","text":"Ureters are supported by the pelvic floor"},{"id":"d","text":"Ureters are anterior to the vagina"}],"answerId":"c","explanation":"The ureters are supported by the pelvic floor, which is crucial for maintaining their position and function.","kind":"integration","linkedModuleIds":["kidney-ureter-anatomy"],"origin":"ai"},{"id":"hrp1-uterus-vagina-support~ai-6","moduleId":"hrp1-uterus-vagina-support","stem":"Which pelvic structure is most likely to be affected in a patient with a uterine prolapse?","options":[{"id":"a","text":"Ovarian ligament"},{"id":"b","text":"Round ligament"},{"id":"c","text":"Pelvic floor muscles"},{"id":"d","text":"Uterosacral ligament"}],"answerId":"c","explanation":"The pelvic floor muscles are primarily responsible for supporting the uterus, and their failure leads to prolapse.","kind":"integration","linkedModuleIds":["hrp1-female-pelvis-neurovascular"],"origin":"ai"}],"hrp1-oviduct-uterus-cycle-histology":[{"id":"hrp1-oviduct-uterus-cycle-histology~ai-0","moduleId":"hrp1-oviduct-uterus-cycle-histology","stem":"Which hormone is primarily responsible for the development of straight proliferative glands in the endometrium?","options":[{"id":"a","text":"Progesterone"},{"id":"b","text":"Estrogen"},{"id":"c","text":"Luteinizing hormone"},{"id":"d","text":"Follicle-stimulating hormone"}],"answerId":"b","explanation":"Estrogen stimulates the proliferation of endometrial glands during the follicular phase.","kind":"recall","origin":"ai"},{"id":"hrp1-oviduct-uterus-cycle-histology~ai-1","moduleId":"hrp1-oviduct-uterus-cycle-histology","stem":"What histological feature is characteristic of a progesterone-dominant secretory endometrium?","options":[{"id":"a","text":"Straight glands with frequent mitoses"},{"id":"b","text":"Coiled glands with subnuclear vacuoles"},{"id":"c","text":"Thickened myometrium"},{"id":"d","text":"Ciliated columnar cells"}],"answerId":"b","explanation":"Coiled glands with subnuclear vacuoles indicate a secretory phase influenced by progesterone.","kind":"recall","origin":"ai"},{"id":"hrp1-oviduct-uterus-cycle-histology~ai-2","moduleId":"hrp1-oviduct-uterus-cycle-histology","stem":"Which statement about the endometrial cycle is true?","options":[{"id":"a","text":"The entire endometrium is shed every month"},{"id":"b","text":"The functional layer sheds; basal layer remains to regenerate it"},{"id":"c","text":"The basal layer is shed during menstruation"},{"id":"d","text":"The functional layer does not regenerate after shedding"}],"answerId":"b","explanation":"Only the functional layer sheds during menstruation; the basal layer remains intact to regenerate it.","kind":"trap","origin":"ai"},{"id":"hrp1-oviduct-uterus-cycle-histology~ai-3","moduleId":"hrp1-oviduct-uterus-cycle-histology","stem":"What is the primary function of the ciliated cells in the oviduct?","options":[{"id":"a","text":"Secretion of hormones"},{"id":"b","text":"Transport of ova"},{"id":"c","text":"Nutrient absorption"},{"id":"d","text":"Protection against pathogens"}],"answerId":"b","explanation":"Ciliated cells in the oviduct help transport the ova towards the uterus.","kind":"mechanism","origin":"ai"},{"id":"hrp1-oviduct-uterus-cycle-histology~ai-4","moduleId":"hrp1-oviduct-uterus-cycle-histology","stem":"How do ovarian hormones affect the endometrium during the menstrual cycle?","options":[{"id":"a","text":"They maintain a constant structure"},{"id":"b","text":"They induce apoptosis in the basal layer"},{"id":"c","text":"They remodel the functional layer each cycle"},{"id":"d","text":"They inhibit glandular development"}],"answerId":"c","explanation":"Ovarian hormones, particularly estrogen and progesterone, remodel the functional endometrium each cycle.","kind":"mechanism","origin":"ai"},{"id":"hrp1-oviduct-uterus-cycle-histology~ai-5","moduleId":"hrp1-oviduct-uterus-cycle-histology","stem":"Which histological feature would you expect to see in the cervix during the proliferative phase of the menstrual cycle?","options":[{"id":"a","text":"Thickened squamous epithelium"},{"id":"b","text":"Ciliated columnar cells"},{"id":"c","text":"Coiled endometrial glands"},{"id":"d","text":"Subnuclear vacuoles"}],"answerId":"a","explanation":"The cervix exhibits a thickened squamous epithelium during the proliferative phase due to estrogen influence.","kind":"integration","linkedModuleIds":["hrp1-cervix-vagina-histology"],"origin":"ai"},{"id":"hrp1-oviduct-uterus-cycle-histology~ai-6","moduleId":"hrp1-oviduct-uterus-cycle-histology","stem":"What histological change occurs in the ovarian follicles during the luteal phase?","options":[{"id":"a","text":"Increased follicular atresia"},{"id":"b","text":"Formation of a corpus luteum"},{"id":"c","text":"Development of Graafian follicles"},{"id":"d","text":"Increased estrogen production"}],"answerId":"b","explanation":"During the luteal phase, the ruptured follicle transforms into the corpus luteum, which produces progesterone.","kind":"integration","linkedModuleIds":["hrp1-ovarian-follicle-histology"],"origin":"ai"}],"vitamin-absorption":[{"id":"vitamin-absorption~ai-0","moduleId":"vitamin-absorption","stem":"Which fat-soluble vitamin requires normal lipid digestion for absorption?","options":[{"id":"a","text":"Vitamin A"},{"id":"b","text":"Vitamin B12"},{"id":"c","text":"Vitamin C"},{"id":"d","text":"Vitamin D"}],"answerId":"a","explanation":"Fat-soluble vitamins, including Vitamin A, depend on lipid digestion for absorption through mixed micelles.","kind":"recall","origin":"ai"},{"id":"vitamin-absorption~ai-1","moduleId":"vitamin-absorption","stem":"What is the primary site of absorption for folate in the small intestine?","options":[{"id":"a","text":"Distal ileum"},{"id":"b","text":"Proximal small intestine"},{"id":"c","text":"Duodenum"},{"id":"d","text":"Jejunum"}],"answerId":"b","explanation":"Folate is chiefly absorbed in the proximal small intestine after deconjugation.","kind":"recall","origin":"ai"},{"id":"vitamin-absorption~ai-2","moduleId":"vitamin-absorption","stem":"A patient presents with neuropathy and macrocytic anemia. Which vitamin deficiency is most likely responsible?","options":[{"id":"a","text":"Vitamin A"},{"id":"b","text":"Vitamin B12"},{"id":"c","text":"Vitamin K"},{"id":"d","text":"Folate"}],"answerId":"b","explanation":"Vitamin B12 deficiency causes both macrocytic anemia and characteristic neurologic deficits.","kind":"clinical","origin":"ai"},{"id":"vitamin-absorption~ai-3","moduleId":"vitamin-absorption","stem":"Which mechanism is primarily disrupted in vitamin B12 deficiency?","options":[{"id":"a","text":"Chylomicron export"},{"id":"b","text":"Intrinsic factor binding"},{"id":"c","text":"Carrier-mediated uptake"},{"id":"d","text":"Micellar absorption"}],"answerId":"b","explanation":"Vitamin B12 requires intrinsic factor binding for receptor-mediated uptake in the terminal ileum.","kind":"mechanism","origin":"ai"},{"id":"vitamin-absorption~ai-4","moduleId":"vitamin-absorption","stem":"What clinical finding is associated with vitamin K deficiency?","options":[{"id":"a","text":"Neuropathy"},{"id":"b","text":"Easy bruising"},{"id":"c","text":"Macrocytic anemia"},{"id":"d","text":"Fatigue"}],"answerId":"b","explanation":"Vitamin K deficiency can lead to easy bruising due to impaired coagulation.","kind":"recall","origin":"ai"},{"id":"vitamin-absorption~ai-5","moduleId":"vitamin-absorption","stem":"Which condition can impair both vitamin B12 and bile-salt absorption?","options":[{"id":"a","text":"Pancreatic failure"},{"id":"b","text":"Ileal disease"},{"id":"c","text":"Celiac disease"},{"id":"d","text":"Chronic gastritis"}],"answerId":"b","explanation":"Ileal disease or resection affects the absorption of both vitamin B12 and bile salts.","kind":"trap","origin":"ai"},{"id":"vitamin-absorption~ai-6","moduleId":"vitamin-absorption","stem":"How does vitamin B12 deficiency differ from folate deficiency in terms of neurological effects?","options":[{"id":"a","text":"Both cause similar neurologic deficits"},{"id":"b","text":"Only B12 causes neuropathy"},{"id":"c","text":"Only folate affects DNA synthesis"},{"id":"d","text":"Both affect myelin synthesis equally"}],"answerId":"b","explanation":"Vitamin B12 deficiency causes characteristic neurologic injury, while folate deficiency does not.","kind":"trap","origin":"ai"},{"id":"vitamin-absorption~ai-7","moduleId":"vitamin-absorption","stem":"Which vitamin's absorption is directly linked to the function of intrinsic factor?","options":[{"id":"a","text":"Vitamin A"},{"id":"b","text":"Vitamin D"},{"id":"c","text":"Vitamin B12"},{"id":"d","text":"Vitamin K"}],"answerId":"c","explanation":"Intrinsic factor is essential for the absorption of vitamin B12 in the terminal ileum.","kind":"integration","linkedModuleIds":["one-carbon-carriers"],"origin":"ai"},{"id":"vitamin-absorption~ai-8","moduleId":"vitamin-absorption","stem":"What is the primary consequence of pancreatic failure on vitamin absorption?","options":[{"id":"a","text":"Increased absorption of fat-soluble vitamins"},{"id":"b","text":"Impaired transfer of vitamin B12"},{"id":"c","text":"Enhanced absorption of folate"},{"id":"d","text":"Reduced absorption of water-soluble vitamins"}],"answerId":"b","explanation":"Pancreatic failure disrupts the transfer of vitamin B12 and affects fat-soluble vitamin uptake.","kind":"integration","linkedModuleIds":["hgb-lipid-digestion-absorption"],"origin":"ai"}],"hrp1-uterine-tube-ovary-lymph":[{"id":"hrp1-uterine-tube-ovary-lymph~ai-0","moduleId":"hrp1-uterine-tube-ovary-lymph","stem":"Which segment of the uterine tube is most commonly the site of fertilization?","options":[{"id":"a","text":"Infundibulum"},{"id":"b","text":"Ampulla"},{"id":"c","text":"Isthmus"},{"id":"d","text":"Intramural part"}],"answerId":"b","explanation":"Fertilization most often occurs in the ampulla of the uterine tube.","kind":"recall","origin":"ai"},{"id":"hrp1-uterine-tube-ovary-lymph~ai-1","moduleId":"hrp1-uterine-tube-ovary-lymph","stem":"What is the primary blood supply to the ovaries?","options":[{"id":"a","text":"Uterine artery"},{"id":"b","text":"Ovarian artery"},{"id":"c","text":"Internal iliac artery"},{"id":"d","text":"External iliac artery"}],"answerId":"b","explanation":"The ovaries are primarily supplied by the ovarian arteries, which arise from the aorta.","kind":"recall","origin":"ai"},{"id":"hrp1-uterine-tube-ovary-lymph~ai-2","moduleId":"hrp1-uterine-tube-ovary-lymph","stem":"A patient presents with sudden unilateral pelvic pain and an enlarged ovary. What is the most likely diagnosis?","options":[{"id":"a","text":"Ectopic pregnancy"},{"id":"b","text":"Ovarian torsion"},{"id":"c","text":"Ruptured cyst"},{"id":"d","text":"Pelvic inflammatory disease"}],"answerId":"b","explanation":"Sudden unilateral pain with an enlarged ovary is characteristic of ovarian torsion.","kind":"clinical","origin":"ai"},{"id":"hrp1-uterine-tube-ovary-lymph~ai-3","moduleId":"hrp1-uterine-tube-ovary-lymph","stem":"Which statement about ovarian lymphatic drainage is correct?","options":[{"id":"a","text":"Drains to superficial inguinal nodes"},{"id":"b","text":"Drains to para-aortic nodes"},{"id":"c","text":"Drains to external iliac nodes"},{"id":"d","text":"Drains to sacral nodes"}],"answerId":"b","explanation":"Ovarian lymph follows gonadal vessels to para-aortic nodes, not primarily to superficial inguinal nodes.","kind":"trap","origin":"ai"},{"id":"hrp1-uterine-tube-ovary-lymph~ai-4","moduleId":"hrp1-uterine-tube-ovary-lymph","stem":"What mechanism allows fimbriae to assist in capturing the oocyte?","options":[{"id":"a","text":"Ciliary movement"},{"id":"b","text":"Peristaltic contractions"},{"id":"c","text":"Hormonal signaling"},{"id":"d","text":"Suction effect"}],"answerId":"a","explanation":"Fimbriae use ciliary movement to capture the oocyte and guide it toward the uterus.","kind":"mechanism","origin":"ai"},{"id":"hrp1-uterine-tube-ovary-lymph~ai-5","moduleId":"hrp1-uterine-tube-ovary-lymph","stem":"In a patient with a ruptured ectopic pregnancy, which clinical finding is most likely?","options":[{"id":"a","text":"Positive pregnancy test and free fluid"},{"id":"b","text":"Unilateral adnexal mass"},{"id":"c","text":"Bilateral pelvic pain"},{"id":"d","text":"Menorrhagia"}],"answerId":"a","explanation":"Acute pelvic pain with a positive pregnancy test and free fluid indicates a ruptured tubal ectopic pregnancy.","kind":"recall","origin":"ai"},{"id":"hrp1-uterine-tube-ovary-lymph~ai-6","moduleId":"hrp1-uterine-tube-ovary-lymph","stem":"How does the anatomy of the ovarian ligament relate to the ovarian blood supply?","options":[{"id":"a","text":"It carries lymphatic vessels"},{"id":"b","text":"It attaches to the uterine artery"},{"id":"c","text":"It connects the ovary to the lateral pelvic wall"},{"id":"d","text":"It carries the ovarian vessels"}],"answerId":"d","explanation":"The ovarian ligament connects the ovary to the uterus and carries the ovarian vessels.","kind":"integration","linkedModuleIds":["hrp1-female-pelvis-neurovascular"],"origin":"ai"},{"id":"hrp1-uterine-tube-ovary-lymph~ai-7","moduleId":"hrp1-uterine-tube-ovary-lymph","stem":"Which of the following conditions could lead to a clinical scenario requiring knowledge of both ovarian anatomy and gametogenesis?","options":[{"id":"a","text":"Ovarian torsion"},{"id":"b","text":"Ectopic pregnancy"},{"id":"c","text":"Polycystic ovary syndrome"},{"id":"d","text":"Infertility treatments"}],"answerId":"d","explanation":"Infertility treatments require understanding both ovarian anatomy and the process of gametogenesis.","kind":"integration","linkedModuleIds":["gametogenesis-female-tract"],"origin":"ai"}],"bile-formation-gallbladder-emptying":[{"id":"bile-formation-gallbladder-emptying~ai-0","moduleId":"bile-formation-gallbladder-emptying","stem":"Which substance is primarily responsible for gallbladder contraction after a fatty meal?","options":[{"id":"a","text":"Secretin"},{"id":"b","text":"Cholecystokinin (CCK)"},{"id":"c","text":"Gastrin"},{"id":"d","text":"Insulin"}],"answerId":"b","explanation":"Cholecystokinin (CCK) is released in response to duodenal fat and stimulates gallbladder contraction.","kind":"recall","origin":"ai"},{"id":"bile-formation-gallbladder-emptying~ai-1","moduleId":"bile-formation-gallbladder-emptying","stem":"What is the primary function of cholangiocytes in bile formation?","options":[{"id":"a","text":"Secretion of bile salts"},{"id":"b","text":"Modification of bile composition"},{"id":"c","text":"Addition of bicarbonate-rich fluid"},{"id":"d","text":"Contraction of the gallbladder"}],"answerId":"c","explanation":"Cholangiocytes add bicarbonate-rich fluid to bile, especially in response to secretin, increasing bile volume and alkalinity.","kind":"mechanism","origin":"ai"},{"id":"bile-formation-gallbladder-emptying~ai-2","moduleId":"bile-formation-gallbladder-emptying","stem":"What clinical finding is indicative of complete biliary obstruction?","options":[{"id":"a","text":"Dark urine and pale stool"},{"id":"b","text":"Jaundice without pale stool"},{"id":"c","text":"Elevated alkaline phosphatase"},{"id":"d","text":"Increased conjugated bilirubin in serum"}],"answerId":"a","explanation":"In complete biliary obstruction, conjugated bilirubin is excreted in urine, leading to dark urine and pale stool due to lack of bilirubin reaching the intestine.","kind":"clinical","origin":"ai"},{"id":"bile-formation-gallbladder-emptying~ai-3","moduleId":"bile-formation-gallbladder-emptying","stem":"Which statement correctly describes the role of secretin in bile formation?","options":[{"id":"a","text":"Stimulates gallbladder contraction"},{"id":"b","text":"Increases bicarbonate secretion from ductal cells"},{"id":"c","text":"Increases bile salt synthesis"},{"id":"d","text":"Decreases bile volume"}],"answerId":"b","explanation":"Secretin primarily stimulates bicarbonate-rich fluid secretion from cholangiocytes, not gallbladder contraction.","kind":"trap","origin":"ai"},{"id":"bile-formation-gallbladder-emptying~ai-4","moduleId":"bile-formation-gallbladder-emptying","stem":"How does the gallbladder concentrate bile?","options":[{"id":"a","text":"By secreting bile salts"},{"id":"b","text":"By absorbing NaCl and water"},{"id":"c","text":"By increasing bile acid synthesis"},{"id":"d","text":"By releasing CCK"}],"answerId":"b","explanation":"The gallbladder epithelium absorbs NaCl and water to concentrate organic solutes in bile.","kind":"mechanism","origin":"ai"},{"id":"bile-formation-gallbladder-emptying~ai-5","moduleId":"bile-formation-gallbladder-emptying","stem":"Which hormone is primarily responsible for stimulating bicarbonate secretion in the bile duct?","options":[{"id":"a","text":"Cholecystokinin (CCK)"},{"id":"b","text":"Gastrin"},{"id":"c","text":"Secretin"},{"id":"d","text":"Insulin"}],"answerId":"c","explanation":"Secretin stimulates the secretion of bicarbonate-rich fluid from cholangiocytes in the bile duct.","kind":"recall","origin":"ai"},{"id":"bile-formation-gallbladder-emptying~ai-6","moduleId":"bile-formation-gallbladder-emptying","stem":"How does enterohepatic circulation of bile salts relate to bile formation?","options":[{"id":"a","text":"It enhances bile salt synthesis in hepatocytes"},{"id":"b","text":"It promotes gallbladder contraction"},{"id":"c","text":"It increases the volume of bile produced"},{"id":"d","text":"It reduces the need for dietary bile salts"}],"answerId":"a","explanation":"Enterohepatic circulation allows for the recycling of bile salts, enhancing their synthesis in hepatocytes.","kind":"integration","linkedModuleIds":["enterohepatic-bile-circulation"],"origin":"ai"},{"id":"bile-formation-gallbladder-emptying~ai-7","moduleId":"bile-formation-gallbladder-emptying","stem":"What is the relationship between bile composition and gallbladder emptying?","options":[{"id":"a","text":"Bile composition affects gallbladder contraction"},{"id":"b","text":"Gallbladder emptying alters bile composition"},{"id":"c","text":"Bile salts inhibit gallbladder contraction"},{"id":"d","text":"Gallbladder emptying decreases bile salt concentration"}],"answerId":"a","explanation":"The composition of bile, particularly the presence of fats, influences the release of CCK, which coordinates gallbladder contraction.","kind":"integration","linkedModuleIds":["bile-composition-acid-synthesis"],"origin":"ai"}],"bile-composition-acid-synthesis":[{"id":"bile-composition-acid-synthesis~ai-0","moduleId":"bile-composition-acid-synthesis","stem":"What is the primary component of bile that aids in fat digestion?","options":[{"id":"a","text":"Bile salts"},{"id":"b","text":"Cholesterol"},{"id":"c","text":"Bilirubin"},{"id":"d","text":"Electrolytes"}],"answerId":"a","explanation":"Bile salts are amphipathic molecules that emulsify fats, facilitating their digestion.","kind":"recall","origin":"ai"},{"id":"bile-composition-acid-synthesis~ai-1","moduleId":"bile-composition-acid-synthesis","stem":"Which enzyme is the rate-limiting step in the synthesis of primary bile acids?","options":[{"id":"a","text":"Cholesterol 7α-hydroxylase"},{"id":"b","text":"HMG-CoA reductase"},{"id":"c","text":"Apolipoprotein B"},{"id":"d","text":"Lecithin-cholesterol acyltransferase"}],"answerId":"a","explanation":"Cholesterol 7α-hydroxylase (CYP7A1) catalyzes the conversion of cholesterol to bile acids.","kind":"mechanism","origin":"ai"},{"id":"bile-composition-acid-synthesis~ai-2","moduleId":"bile-composition-acid-synthesis","stem":"A patient presents with steatorrhea and deficiencies in fat-soluble vitamins. What is the likely underlying mechanism?","options":[{"id":"a","text":"Excess bile salts"},{"id":"b","text":"Insufficient bile salts"},{"id":"c","text":"Pancreatic enzyme deficiency"},{"id":"d","text":"Intestinal malabsorption"}],"answerId":"b","explanation":"Insufficient bile salts impair mixed micelle formation, leading to fat malabsorption.","kind":"clinical","origin":"ai"},{"id":"bile-composition-acid-synthesis~ai-3","moduleId":"bile-composition-acid-synthesis","stem":"Which statement about bile salts is correct?","options":[{"id":"a","text":"They enzymatically hydrolyze triglycerides."},{"id":"b","text":"They emulsify lipids and form micelles."},{"id":"c","text":"They are synthesized from amino acids."},{"id":"d","text":"They are primarily composed of cholesterol."}],"answerId":"b","explanation":"Bile salts act as physical detergents that emulsify lipids; pancreatic lipase performs hydrolysis.","kind":"trap","origin":"ai"},{"id":"bile-composition-acid-synthesis~ai-4","moduleId":"bile-composition-acid-synthesis","stem":"How do gut bacteria affect bile acids?","options":[{"id":"a","text":"They convert primary bile acids to secondary bile acids."},{"id":"b","text":"They synthesize bile acids from cholesterol."},{"id":"c","text":"They inhibit bile acid reabsorption."},{"id":"d","text":"They increase bile acid solubility."}],"answerId":"a","explanation":"Gut bacteria convert primary bile acids into secondary bile acids, altering their function.","kind":"mechanism","origin":"ai"},{"id":"bile-composition-acid-synthesis~ai-5","moduleId":"bile-composition-acid-synthesis","stem":"Which bile acid is formed from cholesterol via the action of hepatic cholesterol 7α-hydroxylase?","options":[{"id":"a","text":"Cholic acid"},{"id":"b","text":"Deoxycholic acid"},{"id":"c","text":"Lithocholic acid"},{"id":"d","text":"Ursodeoxycholic acid"}],"answerId":"a","explanation":"Cholesterol 7α-hydroxylase converts cholesterol to cholic acid, a primary bile acid.","kind":"recall","origin":"ai"},{"id":"bile-composition-acid-synthesis~ai-6","moduleId":"bile-composition-acid-synthesis","stem":"How does the enterohepatic circulation of bile salts relate to bile composition?","options":[{"id":"a","text":"It decreases bile salt concentration in the liver."},{"id":"b","text":"It enhances the synthesis of bile acids."},{"id":"c","text":"It recycles bile salts back to the intestine."},{"id":"d","text":"It prevents the formation of secondary bile acids."}],"answerId":"c","explanation":"Enterohepatic circulation recycles bile salts from the intestine back to the liver, maintaining bile composition.","kind":"integration","linkedModuleIds":["enterohepatic-bile-circulation"],"origin":"ai"},{"id":"bile-composition-acid-synthesis~ai-7","moduleId":"bile-composition-acid-synthesis","stem":"What is the role of bile salts in the absorption of fat-soluble vitamins?","options":[{"id":"a","text":"They hydrolyze triglycerides."},{"id":"b","text":"They form micelles with fats."},{"id":"c","text":"They transport vitamins in the bloodstream."},{"id":"d","text":"They convert vitamins to active forms."}],"answerId":"b","explanation":"Bile salts emulsify fats and form micelles, which are essential for the absorption of fat-soluble vitamins.","kind":"integration","linkedModuleIds":["cholesterol-bile-steroids"],"origin":"ai"}],"hrp1-female-pelvis-neurovascular":[{"id":"hrp1-female-pelvis-neurovascular~ai-0","moduleId":"hrp1-female-pelvis-neurovascular","stem":"Which nerve primarily provides somatic sensation to the perineum?","options":[{"id":"a","text":"Pelvic splanchnic nerve"},{"id":"b","text":"Pudendal nerve"},{"id":"c","text":"Hypogastric nerve"},{"id":"d","text":"Ilioinguinal nerve"}],"answerId":"b","explanation":"The pudendal nerve (S2–S4) is responsible for somatic sensation in the perineum.","kind":"recall","origin":"ai"},{"id":"hrp1-female-pelvis-neurovascular~ai-1","moduleId":"hrp1-female-pelvis-neurovascular","stem":"What is the primary function of pelvic splanchnic nerves?","options":[{"id":"a","text":"Somatic motor control"},{"id":"b","text":"Sympathetic innervation"},{"id":"c","text":"Parasympathetic innervation"},{"id":"d","text":"Sensory innervation"}],"answerId":"c","explanation":"Pelvic splanchnic nerves (S2–S4) carry parasympathetic fibers to pelvic organs.","kind":"mechanism","origin":"ai"},{"id":"hrp1-female-pelvis-neurovascular~ai-2","moduleId":"hrp1-female-pelvis-neurovascular","stem":"A patient presents with perineal sensory loss and sphincter weakness. Which nerve injury is most likely?","options":[{"id":"a","text":"Hypogastric nerve"},{"id":"b","text":"Pudendal nerve"},{"id":"c","text":"Pelvic splanchnic nerve"},{"id":"d","text":"Ilioinguinal nerve"}],"answerId":"b","explanation":"Injury to the pudendal nerve affects S2–S4 functions, leading to sensory loss and sphincter weakness.","kind":"clinical","origin":"ai"},{"id":"hrp1-female-pelvis-neurovascular~ai-3","moduleId":"hrp1-female-pelvis-neurovascular","stem":"Which statement about pelvic innervation is correct?","options":[{"id":"a","text":"The pudendal nerve provides parasympathetic supply to pelvic organs."},{"id":"b","text":"Pelvic splanchnics arise from T12-L2."},{"id":"c","text":"The hypogastric nerve is purely somatic."},{"id":"d","text":"Pudendal nerve is somatic; pelvic splanchnics carry parasympathetics."}],"answerId":"d","explanation":"The pudendal nerve is somatic, while pelvic splanchnics provide parasympathetic innervation.","kind":"trap","origin":"ai"},{"id":"hrp1-female-pelvis-neurovascular~ai-4","moduleId":"hrp1-female-pelvis-neurovascular","stem":"How do pelvic autonomics influence bladder function?","options":[{"id":"a","text":"Increase detrusor contraction"},{"id":"b","text":"Inhibit sphincter contraction"},{"id":"c","text":"Decrease blood flow to bladder"},{"id":"d","text":"Stimulate somatic control of urination"}],"answerId":"a","explanation":"Pelvic autonomics, particularly parasympathetic fibers, increase detrusor muscle contraction, facilitating bladder emptying.","kind":"mechanism","origin":"ai"},{"id":"hrp1-female-pelvis-neurovascular~ai-5","moduleId":"hrp1-female-pelvis-neurovascular","stem":"Which structure is primarily responsible for supporting the uterus and vagina?","options":[{"id":"a","text":"Pelvic diaphragm"},{"id":"b","text":"Uterosacral ligament"},{"id":"c","text":"Round ligament"},{"id":"d","text":"Broad ligament"}],"answerId":"b","explanation":"The uterosacral ligament provides crucial support to the uterus and vagina.","kind":"recall","origin":"ai"},{"id":"hrp1-female-pelvis-neurovascular~ai-6","moduleId":"hrp1-female-pelvis-neurovascular","stem":"How is pelvic pain related to the autonomic nervous system?","options":[{"id":"a","text":"Only sympathetic fibers are involved"},{"id":"b","text":"Parasympathetic fibers exclusively transmit pain"},{"id":"c","text":"Both sympathetic and parasympathetic fibers can mediate pain"},{"id":"d","text":"Somatic nerves are the only pain pathways"}],"answerId":"c","explanation":"Both sympathetic and parasympathetic fibers can mediate pelvic pain, reflecting the complexity of pelvic autonomics.","kind":"integration","linkedModuleIds":["hrp1-uterus-vagina-support"],"origin":"ai"},{"id":"hrp1-female-pelvis-neurovascular~ai-7","moduleId":"hrp1-female-pelvis-neurovascular","stem":"What is the consequence of hypogastric plexus injury on sexual function?","options":[{"id":"a","text":"Increased libido"},{"id":"b","text":"Erectile dysfunction"},{"id":"c","text":"Enhanced orgasm"},{"id":"d","text":"Normal sexual function"}],"answerId":"b","explanation":"Injury to the hypogastric plexus can lead to erectile dysfunction due to disrupted autonomic control.","kind":"integration","linkedModuleIds":["hrp1-uterine-tube-ovary-lymph"],"origin":"ai"}],"hrp1-ovarian-follicle-histology":[{"id":"hrp1-ovarian-follicle-histology~ai-0","moduleId":"hrp1-ovarian-follicle-histology","stem":"What structure is characteristic of a mature preovulatory follicle?","options":[{"id":"a","text":"Large fluid-filled antrum"},{"id":"b","text":"Multiple layers of theca externa"},{"id":"c","text":"Presence of a primary oocyte"},{"id":"d","text":"Absence of granulosa cells"}],"answerId":"a","explanation":"A mature preovulatory follicle is defined by its large fluid-filled antrum and an eccentric oocyte.","kind":"recall","origin":"ai"},{"id":"hrp1-ovarian-follicle-histology~ai-1","moduleId":"hrp1-ovarian-follicle-histology","stem":"Which cell type in the theca interna is primarily responsible for steroid hormone production?","options":[{"id":"a","text":"Granulosa cells"},{"id":"b","text":"Theca externa cells"},{"id":"c","text":"Theca interna cells"},{"id":"d","text":"Oocyte"}],"answerId":"c","explanation":"Theca interna cells are steroidogenic and produce androgens that are converted to estrogens by granulosa cells.","kind":"mechanism","origin":"ai"},{"id":"hrp1-ovarian-follicle-histology~ai-2","moduleId":"hrp1-ovarian-follicle-histology","stem":"What is the primary finding in a histological section of a collapsed follicle undergoing atresia?","options":[{"id":"a","text":"Large antrum with a viable oocyte"},{"id":"b","text":"Pyknotic oocyte and granulosa cells"},{"id":"c","text":"Multiple layers of granulosa cells"},{"id":"d","text":"Presence of cumulus oophorus"}],"answerId":"b","explanation":"A collapsed follicle undergoing atresia typically shows a pyknotic oocyte and degenerating granulosa cells.","kind":"recall","origin":"ai"},{"id":"hrp1-ovarian-follicle-histology~ai-3","moduleId":"hrp1-ovarian-follicle-histology","stem":"Which statement about oocyte maturation is correct?","options":[{"id":"a","text":"Mature follicles contain completed ova before the LH surge"},{"id":"b","text":"Primary oocytes complete meiosis I at ovulation"},{"id":"c","text":"Secondary oocytes complete meiosis II at ovulation"},{"id":"d","text":"Oocytes remain arrested in meiosis II until fertilization"}],"answerId":"b","explanation":"Primary oocytes complete meiosis I around the LH surge and are released as secondary oocytes.","kind":"trap","origin":"ai"},{"id":"hrp1-ovarian-follicle-histology~ai-4","moduleId":"hrp1-ovarian-follicle-histology","stem":"How does the structure of the ovarian cortex differ from the medulla?","options":[{"id":"a","text":"Cortex contains loose connective tissue, medulla contains follicles"},{"id":"b","text":"Cortex contains follicles, medulla contains loose connective tissue"},{"id":"c","text":"Cortex is avascular, medulla is highly vascularized"},{"id":"d","text":"Cortex contains only primordial follicles"}],"answerId":"b","explanation":"The ovarian cortex contains follicles, while the medulla consists of loose connective tissue, blood vessels, and nerves.","kind":"recall","origin":"ai"},{"id":"hrp1-ovarian-follicle-histology~ai-5","moduleId":"hrp1-ovarian-follicle-histology","stem":"What histological feature indicates the presence of a secondary follicle?","options":[{"id":"a","text":"Presence of a zona pellucida"},{"id":"b","text":"Formation of an antrum"},{"id":"c","text":"Multiple layers of theca externa"},{"id":"d","text":"Presence of cumulus oophorus"}],"answerId":"b","explanation":"The formation of an antrum is a defining feature of secondary follicles.","kind":"recall","origin":"ai"},{"id":"hrp1-ovarian-follicle-histology~ai-6","moduleId":"hrp1-ovarian-follicle-histology","stem":"Which histological change occurs in the corpus luteum after ovulation?","options":[{"id":"a","text":"Increased granulosa cell apoptosis"},{"id":"b","text":"Formation of a large antrum"},{"id":"c","text":"Luteinization of theca interna cells"},{"id":"d","text":"Expansion of the zona pellucida"}],"answerId":"c","explanation":"After ovulation, the theca interna cells undergo luteinization to form the corpus luteum.","kind":"integration","linkedModuleIds":["hrp1-ovulation-corpus-luteum-histology"],"origin":"ai"},{"id":"hrp1-ovarian-follicle-histology~ai-7","moduleId":"hrp1-ovarian-follicle-histology","stem":"How does the histology of the oviduct relate to follicular development?","options":[{"id":"a","text":"Oviduct epithelium changes during follicular atresia"},{"id":"b","text":"Oviduct supports fertilization post-ovulation"},{"id":"c","text":"Follicular development occurs in the oviduct"},{"id":"d","text":"Oviduct histology is unaffected by ovarian cycles"}],"answerId":"b","explanation":"The oviduct's histology supports fertilization and transport of the oocyte post-ovulation.","kind":"integration","linkedModuleIds":["hrp1-oviduct-uterus-cycle-histology"],"origin":"ai"}],"hgb-lipid-digestion-absorption":[{"id":"hgb-lipid-digestion-absorption~ai-0","moduleId":"hgb-lipid-digestion-absorption","stem":"What is the primary function of bile salts in lipid digestion?","options":[{"id":"a","text":"Emulsify lipids to increase surface area"},{"id":"b","text":"Hydrolyze triacylglycerols"},{"id":"c","text":"Transport lipids to the liver"},{"id":"d","text":"Absorb fat-soluble vitamins"}],"answerId":"a","explanation":"Bile salts emulsify lipids, increasing their surface area for enzymatic action.","kind":"recall","origin":"ai"},{"id":"hgb-lipid-digestion-absorption~ai-1","moduleId":"hgb-lipid-digestion-absorption","stem":"Which product is primarily formed by pancreatic lipase during lipid digestion?","options":[{"id":"a","text":"Cholesterol"},{"id":"b","text":"2-monoacylglycerol"},{"id":"c","text":"Phospholipids"},{"id":"d","text":"Fat-soluble vitamins"}],"answerId":"b","explanation":"Pancreatic lipase hydrolyzes triacylglycerols mainly to 2-monoacylglycerol and free fatty acids.","kind":"recall","origin":"ai"},{"id":"hgb-lipid-digestion-absorption~ai-2","moduleId":"hgb-lipid-digestion-absorption","stem":"What is the fate of bile salts after lipid absorption in the intestine?","options":[{"id":"a","text":"They are absorbed into the bloodstream"},{"id":"b","text":"They are excreted in urine"},{"id":"c","text":"They remain in the lumen for ileal recovery"},{"id":"d","text":"They are converted to cholesterol"}],"answerId":"c","explanation":"Bile salts remain in the lumen for ileal recycling after facilitating lipid absorption.","kind":"recall","origin":"ai"},{"id":"hgb-lipid-digestion-absorption~ai-3","moduleId":"hgb-lipid-digestion-absorption","stem":"Which clinical finding is indicative of fat malabsorption?","options":[{"id":"a","text":"Bulky oily stool"},{"id":"b","text":"Hypoglycemia"},{"id":"c","text":"Dehydration"},{"id":"d","text":"Hyperlipidemia"}],"answerId":"a","explanation":"Bulky oily stools are a sign of fat malabsorption due to impaired lipolysis or mucosal uptake.","kind":"clinical","origin":"ai"},{"id":"hgb-lipid-digestion-absorption~ai-4","moduleId":"hgb-lipid-digestion-absorption","stem":"What is the mechanism by which short- and medium-chain fatty acids are absorbed?","options":[{"id":"a","text":"They require chylomicron assembly"},{"id":"b","text":"They pass directly into portal blood"},{"id":"c","text":"They are packaged into micelles"},{"id":"d","text":"They are absorbed through active transport"}],"answerId":"b","explanation":"Short- and medium-chain fatty acids can pass directly into portal blood bound to albumin without requiring chylomicron assembly.","kind":"mechanism","origin":"ai"},{"id":"hgb-lipid-digestion-absorption~ai-5","moduleId":"hgb-lipid-digestion-absorption","stem":"What happens to lipid products after they leave the mixed micelle at the brush border?","options":[{"id":"a","text":"They are endocytosed into the enterocyte"},{"id":"b","text":"They remain in the intestinal lumen"},{"id":"c","text":"They are transported to the liver directly"},{"id":"d","text":"They are re-esterified and packaged into chylomicrons"}],"answerId":"d","explanation":"After leaving the mixed micelle, lipid products are re-esterified and packaged into chylomicrons in enterocytes.","kind":"trap","origin":"ai"},{"id":"hgb-lipid-digestion-absorption~ai-6","moduleId":"hgb-lipid-digestion-absorption","stem":"How does impaired chylomicron assembly affect lipid absorption?","options":[{"id":"a","text":"Increases bile salt recycling"},{"id":"b","text":"Decreases fat-soluble vitamin absorption"},{"id":"c","text":"Leads to low apoB-containing chylomicrons"},{"id":"d","text":"Enhances short-chain fatty acid absorption"}],"answerId":"c","explanation":"Impaired chylomicron assembly leads to low levels of apoB-containing chylomicrons after a fatty meal.","kind":"clinical","origin":"ai"},{"id":"hgb-lipid-digestion-absorption~ai-7","moduleId":"hgb-lipid-digestion-absorption","stem":"How does lipid digestion relate to carbohydrate absorption in the intestine?","options":[{"id":"a","text":"Both processes occur in the stomach"},{"id":"b","text":"Both require bile salts for absorption"},{"id":"c","text":"Both involve micelle formation"},{"id":"d","text":"Both are dependent on enterocyte function"}],"answerId":"d","explanation":"Both lipid and carbohydrate absorption depend on the proper function of enterocytes in the intestinal lining.","kind":"integration","linkedModuleIds":["hgb-carbohydrate-digestion-absorption"],"origin":"ai"},{"id":"hgb-lipid-digestion-absorption~ai-8","moduleId":"hgb-lipid-digestion-absorption","stem":"What is a common consequence of impaired lipid digestion on water absorption?","options":[{"id":"a","text":"Increased water absorption"},{"id":"b","text":"Decreased electrolyte absorption"},{"id":"c","text":"Fat malabsorption leading to diarrhea"},{"id":"d","text":"Enhanced absorption of fat-soluble vitamins"}],"answerId":"c","explanation":"Impaired lipid digestion can lead to fat malabsorption, which often results in diarrhea due to unabsorbed fats in the intestine.","kind":"integration","linkedModuleIds":["mineral-water-absorption"],"origin":"ai"}],"hrp1-ovulation-corpus-luteum-histology":[{"id":"hrp1-ovulation-corpus-luteum-histology~ai-0","moduleId":"hrp1-ovulation-corpus-luteum-histology","stem":"What is the primary hormone responsible for the luteinization of granulosa and theca cells during ovulation?","options":[{"id":"a","text":"Follicle-stimulating hormone (FSH)"},{"id":"b","text":"Luteinizing hormone (LH)"},{"id":"c","text":"Estrogen"},{"id":"d","text":"Progesterone"}],"answerId":"b","explanation":"Luteinizing hormone (LH) surge triggers ovulation and the subsequent luteinization of granulosa and theca cells.","kind":"recall","origin":"ai"},{"id":"hrp1-ovulation-corpus-luteum-histology~ai-1","moduleId":"hrp1-ovulation-corpus-luteum-histology","stem":"Which cells in the corpus luteum primarily produce progesterone?","options":[{"id":"a","text":"Theca lutein cells"},{"id":"b","text":"Granulosa lutein cells"},{"id":"c","text":"Oocyte cells"},{"id":"d","text":"Interstitial cells"}],"answerId":"b","explanation":"Granulosa lutein cells are responsible for producing progesterone and estrogen in the corpus luteum.","kind":"recall","origin":"ai"},{"id":"hrp1-ovulation-corpus-luteum-histology~ai-2","moduleId":"hrp1-ovulation-corpus-luteum-histology","stem":"What is the fate of the corpus luteum if pregnancy does not occur?","options":[{"id":"a","text":"It becomes a corpus albicans"},{"id":"b","text":"It continues to produce hormones indefinitely"},{"id":"c","text":"It transforms into a follicle"},{"id":"d","text":"It undergoes hyperplasia"}],"answerId":"a","explanation":"Without pregnancy, the corpus luteum regresses and becomes a fibrous corpus albicans.","kind":"recall","origin":"ai"},{"id":"hrp1-ovulation-corpus-luteum-histology~ai-3","moduleId":"hrp1-ovulation-corpus-luteum-histology","stem":"What histological feature characterizes a regressed corpus luteum?","options":[{"id":"a","text":"Highly vascular folded structure"},{"id":"b","text":"Hyalinized scar in ovarian cortex"},{"id":"c","text":"Presence of oocytes"},{"id":"d","text":"Thickened theca externa"}],"answerId":"b","explanation":"A regressed corpus luteum forms a hyalinized scar known as the corpus albicans in the ovarian cortex.","kind":"recall","origin":"ai"},{"id":"hrp1-ovulation-corpus-luteum-histology~ai-4","moduleId":"hrp1-ovulation-corpus-luteum-histology","stem":"Which statement regarding early pregnancy support is correct?","options":[{"id":"a","text":"Placental progesterone replaces corpus luteum immediately after fertilization"},{"id":"b","text":"hCG maintains the corpus luteum until placental steroid production is sufficient"},{"id":"c","text":"The corpus luteum is unnecessary after implantation"},{"id":"d","text":"Progesterone is not required for early pregnancy"}],"answerId":"b","explanation":"hCG is crucial for maintaining the corpus luteum until the placenta can produce sufficient progesterone.","kind":"trap","origin":"ai"},{"id":"hrp1-ovulation-corpus-luteum-histology~ai-5","moduleId":"hrp1-ovulation-corpus-luteum-histology","stem":"How does obesity-driven insulin resistance affect ovarian function?","options":[{"id":"a","text":"Increases LH production"},{"id":"b","text":"Decreases follicular atresia"},{"id":"c","text":"Impairs ovulation and luteal function"},{"id":"d","text":"Enhances progesterone secretion"}],"answerId":"c","explanation":"Obesity-driven insulin resistance can impair ovulation and luteal function, affecting overall reproductive health.","kind":"integration","linkedModuleIds":["obesity-insulin-resistance"],"origin":"ai"},{"id":"hrp1-ovulation-corpus-luteum-histology~ai-6","moduleId":"hrp1-ovulation-corpus-luteum-histology","stem":"What role does the corpus luteum play in the menstrual cycle in relation to the endometrium?","options":[{"id":"a","text":"Stimulates follicular development"},{"id":"b","text":"Supports the secretory phase of the endometrium"},{"id":"c","text":"Inhibits ovulation"},{"id":"d","text":"Promotes menstruation"}],"answerId":"b","explanation":"The corpus luteum produces hormones that support the secretory phase of the endometrium, essential for implantation.","kind":"integration","linkedModuleIds":["hrp1-oviduct-uterus-cycle-histology"],"origin":"ai"}],"enterohepatic-bile-circulation":[{"id":"enterohepatic-bile-circulation~ai-0","moduleId":"enterohepatic-bile-circulation","stem":"What transporter is primarily responsible for reclaiming bile salts in the terminal ileum?","options":[{"id":"a","text":"Sodium-glucose cotransporter"},{"id":"b","text":"Apical sodium-dependent bile acid transporter (ASBT)"},{"id":"c","text":"Organic anion transporter"},{"id":"d","text":"Multidrug resistance protein 2"}],"answerId":"b","explanation":"The apical sodium-dependent bile acid transporter (ASBT) is responsible for the reclamation of bile salts in the terminal ileum.","kind":"recall","origin":"ai"},{"id":"enterohepatic-bile-circulation~ai-1","moduleId":"enterohepatic-bile-circulation","stem":"What is the primary consequence of ileal resection on bile acid metabolism?","options":[{"id":"a","text":"Increased bile acid synthesis"},{"id":"b","text":"Decreased bile acid reabsorption"},{"id":"c","text":"Increased bile acid secretion into the urine"},{"id":"d","text":"Decreased hepatic bile acid extraction"}],"answerId":"b","explanation":"Ileal resection leads to decreased reabsorption of bile acids, resulting in their loss in the feces.","kind":"recall","origin":"ai"},{"id":"enterohepatic-bile-circulation~ai-2","moduleId":"enterohepatic-bile-circulation","stem":"How does ileal FXR activation affect bile acid synthesis?","options":[{"id":"a","text":"Increases CYP7A1 activity"},{"id":"b","text":"Inhibits CYP7A1 activity"},{"id":"c","text":"Stimulates bile acid secretion"},{"id":"d","text":"Enhances bile acid absorption"}],"answerId":"b","explanation":"Ileal FXR activation leads to the release of FGF19, which inhibits CYP7A1 and reduces bile acid synthesis.","kind":"mechanism","origin":"ai"},{"id":"enterohepatic-bile-circulation~ai-3","moduleId":"enterohepatic-bile-circulation","stem":"A patient with limited terminal ileal disease presents with watery diarrhea. What is the underlying mechanism?","options":[{"id":"a","text":"Increased bile acid synthesis"},{"id":"b","text":"Unabsorbed bile acids in the colon"},{"id":"c","text":"Increased colonic absorption of bile acids"},{"id":"d","text":"Decreased bile acid secretion"}],"answerId":"b","explanation":"Unabsorbed bile acids in the colon stimulate colonic electrolyte and water secretion, leading to diarrhea.","kind":"clinical","origin":"ai"},{"id":"enterohepatic-bile-circulation~ai-4","moduleId":"enterohepatic-bile-circulation","stem":"What is a potential complication of extensive ileal resection related to bile salt depletion?","options":[{"id":"a","text":"Cholecystitis"},{"id":"b","text":"Steatorrhea"},{"id":"c","text":"Cholestasis"},{"id":"d","text":"Biliary colic"}],"answerId":"b","explanation":"Steatorrhea occurs due to inadequate micelle formation from bile-salt pool depletion after extensive ileal resection.","kind":"clinical","origin":"ai"},{"id":"enterohepatic-bile-circulation~ai-5","moduleId":"enterohepatic-bile-circulation","stem":"In patients with ileal bile acid loss, how might a bile-acid sequestrant affect their symptoms?","options":[{"id":"a","text":"Always improves diarrhea"},{"id":"b","text":"Worsens steatorrhea"},{"id":"c","text":"Has no effect on symptoms"},{"id":"d","text":"Improves both diarrhea and steatorrhea"}],"answerId":"b","explanation":"A bile-acid sequestrant may help with diarrhea but can worsen steatorrhea if the bile-salt pool is profoundly depleted.","kind":"trap","origin":"ai"},{"id":"enterohepatic-bile-circulation~ai-6","moduleId":"enterohepatic-bile-circulation","stem":"How does bile acid reabsorption in the terminal ileum relate to lipid digestion?","options":[{"id":"a","text":"Bile acids are not involved in lipid digestion"},{"id":"b","text":"Bile acids enhance micelle formation for lipid absorption"},{"id":"c","text":"Bile acids inhibit lipid digestion"},{"id":"d","text":"Bile acids are only important for cholesterol absorption"}],"answerId":"b","explanation":"Bile acids are crucial for forming micelles, which facilitate the absorption of lipids in the intestine.","kind":"integration","linkedModuleIds":["lipid-digestion-chylomicrons"],"origin":"ai"},{"id":"enterohepatic-bile-circulation~ai-7","moduleId":"enterohepatic-bile-circulation","stem":"What is the relationship between bile acid synthesis and lipid digestion?","options":[{"id":"a","text":"Increased bile acid synthesis enhances lipid absorption"},{"id":"b","text":"Decreased bile acid synthesis improves lipid absorption"},{"id":"c","text":"Bile acid synthesis is independent of lipid digestion"},{"id":"d","text":"Bile acids inhibit lipid absorption"}],"answerId":"a","explanation":"Increased bile acid synthesis enhances lipid absorption by increasing the availability of bile acids for micelle formation.","kind":"integration","linkedModuleIds":["lipid-digestion-chylomicrons"],"origin":"ai"}],"hrp1-sertoli-leydig-histology":[{"id":"hrp1-sertoli-leydig-histology~ai-0","moduleId":"hrp1-sertoli-leydig-histology","stem":"What is the primary function of Sertoli cells in the seminiferous tubules?","options":[{"id":"a","text":"Phagocytose residual bodies"},{"id":"b","text":"Synthesize testosterone"},{"id":"c","text":"Form tight junctions"},{"id":"d","text":"Propel luminal fluid"}],"answerId":"a","explanation":"Sertoli cells support germ cells and phagocytose residual bodies during spermatogenesis.","kind":"recall","origin":"ai"},{"id":"hrp1-sertoli-leydig-histology~ai-1","moduleId":"hrp1-sertoli-leydig-histology","stem":"Which hormone primarily stimulates Leydig cells to produce testosterone?","options":[{"id":"a","text":"FSH"},{"id":"b","text":"LH"},{"id":"c","text":"Inhibin B"},{"id":"d","text":"ABP"}],"answerId":"b","explanation":"Luteinizing hormone (LH) stimulates Leydig cells to synthesize testosterone.","kind":"recall","origin":"ai"},{"id":"hrp1-sertoli-leydig-histology~ai-2","moduleId":"hrp1-sertoli-leydig-histology","stem":"What is a key feature of the blood-testis barrier formed by Sertoli cells?","options":[{"id":"a","text":"Separates basal from adluminal compartments"},{"id":"b","text":"Allows all immune cells access"},{"id":"c","text":"Facilitates sperm maturation"},{"id":"d","text":"Inhibits testosterone synthesis"}],"answerId":"a","explanation":"The blood-testis barrier separates the basal from the adluminal compartments, limiting immune exposure to meiotic antigens.","kind":"recall","origin":"ai"},{"id":"hrp1-sertoli-leydig-histology~ai-3","moduleId":"hrp1-sertoli-leydig-histology","stem":"Which of the following findings is characteristic of Leydig cells in histological sections?","options":[{"id":"a","text":"Pale Sertoli nucleus"},{"id":"b","text":"Eosinophilic interstitial clusters"},{"id":"c","text":"Dense cytoplasmic granules"},{"id":"d","text":"Basophilic cytoplasm"}],"answerId":"b","explanation":"Leydig cells are identified by eosinophilic interstitial clusters due to their steroidogenic nature.","kind":"recall","origin":"ai"},{"id":"hrp1-sertoli-leydig-histology~ai-4","moduleId":"hrp1-sertoli-leydig-histology","stem":"What is a potential consequence of exogenous testosterone therapy?","options":[{"id":"a","text":"Increased sperm production"},{"id":"b","text":"Suppression of gonadotropins"},{"id":"c","text":"Enhanced Sertoli cell function"},{"id":"d","text":"Increased Leydig cell number"}],"answerId":"b","explanation":"Exogenous testosterone can suppress gonadotropins, leading to reduced intratesticular testosterone and impaired sperm production.","kind":"trap","origin":"ai"},{"id":"hrp1-sertoli-leydig-histology~ai-5","moduleId":"hrp1-sertoli-leydig-histology","stem":"How does the function of Sertoli cells relate to spermatogenesis?","options":[{"id":"a","text":"They produce testosterone"},{"id":"b","text":"They phagocytose excess sperm"},{"id":"c","text":"They provide nourishment to germ cells"},{"id":"d","text":"They form the blood-testis barrier"}],"answerId":"c","explanation":"Sertoli cells provide nourishment and support to germ cells, which is essential for spermatogenesis.","kind":"integration","linkedModuleIds":["hrp1-seminiferous-epithelium-spermatogenesis"],"origin":"ai"},{"id":"hrp1-sertoli-leydig-histology~ai-6","moduleId":"hrp1-sertoli-leydig-histology","stem":"Which mechanism connects Leydig cell function to testosterone synthesis?","options":[{"id":"a","text":"Inhibition by FSH"},{"id":"b","text":"Stimulation by LH"},{"id":"c","text":"Support from Sertoli cells"},{"id":"d","text":"Direct action of inhibin B"}],"answerId":"b","explanation":"Leydig cells synthesize testosterone in response to stimulation by luteinizing hormone (LH).","kind":"integration","linkedModuleIds":["gene-therapy-crispr"],"origin":"ai"}],"hrp1-testis-epididymis-vas-anatomy":[{"id":"hrp1-testis-epididymis-vas-anatomy~ai-0","moduleId":"hrp1-testis-epididymis-vas-anatomy","stem":"What structure covers the testis and provides a protective layer?","options":[{"id":"a","text":"Tunica albuginea"},{"id":"b","text":"Tunica vaginalis"},{"id":"c","text":"Spermatic cord"},{"id":"d","text":"Efferent ductules"}],"answerId":"b","explanation":"The tunica vaginalis is a serous membrane that covers the testis, providing protection and lubrication.","kind":"recall","origin":"ai"},{"id":"hrp1-testis-epididymis-vas-anatomy~ai-1","moduleId":"hrp1-testis-epididymis-vas-anatomy","stem":"Which part of the epididymis is primarily responsible for sperm maturation?","options":[{"id":"a","text":"Head"},{"id":"b","text":"Body"},{"id":"c","text":"Tail"},{"id":"d","text":"Rete testis"}],"answerId":"b","explanation":"The body of the epididymis is where sperm undergo maturation processes.","kind":"recall","origin":"ai"},{"id":"hrp1-testis-epididymis-vas-anatomy~ai-2","moduleId":"hrp1-testis-epididymis-vas-anatomy","stem":"A patient presents with sudden severe testicular pain and a high-riding testis. What is the most likely diagnosis?","options":[{"id":"a","text":"Epididymitis"},{"id":"b","text":"Testicular torsion"},{"id":"c","text":"Varicocele"},{"id":"d","text":"Hydrocele"}],"answerId":"b","explanation":"These findings are classic for testicular torsion, where compromised blood flow leads to severe pain.","kind":"clinical","origin":"ai"},{"id":"hrp1-testis-epididymis-vas-anatomy~ai-3","moduleId":"hrp1-testis-epididymis-vas-anatomy","stem":"What is the primary mechanism behind spermatic cord torsion?","options":[{"id":"a","text":"Increased venous return"},{"id":"b","text":"Compromised arterial flow"},{"id":"c","text":"Increased lymphatic drainage"},{"id":"d","text":"Increased testicular temperature"}],"answerId":"b","explanation":"Spermatic cord torsion compromises venous flow first, leading to arterial compromise and severe pain.","kind":"mechanism","origin":"ai"},{"id":"hrp1-testis-epididymis-vas-anatomy~ai-4","moduleId":"hrp1-testis-epididymis-vas-anatomy","stem":"Which of the following statements about lymphatic drainage of the testis is correct?","options":[{"id":"a","text":"Testis drains to superficial inguinal nodes"},{"id":"b","text":"Testis drains to para-aortic nodes"},{"id":"c","text":"Scrotal skin drains to para-aortic nodes"},{"id":"d","text":"Both testis and scrotum drain to superficial inguinal nodes"}],"answerId":"b","explanation":"The testis drains to para-aortic nodes due to its embryological descent from the abdominal cavity.","kind":"trap","origin":"ai"},{"id":"hrp1-testis-epididymis-vas-anatomy~ai-5","moduleId":"hrp1-testis-epididymis-vas-anatomy","stem":"How does the anatomy of the spermatic cord relate to the function of the testis?","options":[{"id":"a","text":"It regulates temperature for sperm production"},{"id":"b","text":"It provides hormonal support to the testis"},{"id":"c","text":"It facilitates lymphatic drainage from the testis"},{"id":"d","text":"It connects the testis to the bladder"}],"answerId":"a","explanation":"The spermatic cord contains structures that help regulate temperature, crucial for optimal sperm production.","kind":"integration","linkedModuleIds":["hrp1-male-perineal-pudendal-anatomy"],"origin":"ai"},{"id":"hrp1-testis-epididymis-vas-anatomy~ai-6","moduleId":"hrp1-testis-epididymis-vas-anatomy","stem":"Which anatomical feature of the male reproductive system is crucial for sperm storage before ejaculation?","options":[{"id":"a","text":"Seminal vesicles"},{"id":"b","text":"Prostate gland"},{"id":"c","text":"Epididymis tail"},{"id":"d","text":"Bulbourethral glands"}],"answerId":"c","explanation":"The tail of the epididymis is specifically designed for storing mature sperm until ejaculation.","kind":"integration","linkedModuleIds":["hrp1-male-accessory-glands-anatomy"],"origin":"ai"}],"hrp1-pelvic-diaphragm":[{"id":"hrp1-pelvic-diaphragm~ai-0","moduleId":"hrp1-pelvic-diaphragm","stem":"Which muscle primarily forms the pelvic diaphragm?","options":[{"id":"a","text":"Coccygeus"},{"id":"b","text":"Puborectalis"},{"id":"c","text":"Iliococcygeus"},{"id":"d","text":"Pubococcygeus"}],"answerId":"b","explanation":"The pelvic diaphragm is mainly formed by the levator ani group, which includes the puborectalis muscle.","kind":"recall","origin":"ai"},{"id":"hrp1-pelvic-diaphragm~ai-1","moduleId":"hrp1-pelvic-diaphragm","stem":"What is the primary function of the puborectalis muscle?","options":[{"id":"a","text":"Support pelvic organs"},{"id":"b","text":"Maintain fecal continence"},{"id":"c","text":"Facilitate childbirth"},{"id":"d","text":"Control urinary flow"}],"answerId":"b","explanation":"The puborectalis muscle forms a sling around the anorectal junction, maintaining the anorectal angle crucial for fecal continence.","kind":"mechanism","origin":"ai"},{"id":"hrp1-pelvic-diaphragm~ai-2","moduleId":"hrp1-pelvic-diaphragm","stem":"A patient presents with pelvic organ prolapse after childbirth. What is the most likely mechanism involved?","options":[{"id":"a","text":"Increased intra-abdominal pressure"},{"id":"b","text":"Disruption of muscle/fascial support"},{"id":"c","text":"Increased pelvic floor contraction"},{"id":"d","text":"Excessive puborectalis activity"}],"answerId":"b","explanation":"Pelvic organ prolapse occurs due to the disruption of muscle and fascial support following obstetric injury.","kind":"clinical","origin":"ai"},{"id":"hrp1-pelvic-diaphragm~ai-3","moduleId":"hrp1-pelvic-diaphragm","stem":"During defecation, which of the following is true regarding the puborectalis muscle?","options":[{"id":"a","text":"It must remain contracted"},{"id":"b","text":"It must relax to allow fecal passage"},{"id":"c","text":"It contracts to increase anorectal angle"},{"id":"d","text":"It has no role in defecation"}],"answerId":"b","explanation":"The puborectalis muscle must relax in coordination with the sphincters to facilitate defecation.","kind":"trap","origin":"ai"},{"id":"hrp1-pelvic-diaphragm~ai-4","moduleId":"hrp1-pelvic-diaphragm","stem":"What clinical finding indicates pelvic-floor weakness?","options":[{"id":"a","text":"Increased anorectal angle"},{"id":"b","text":"Loss of anorectal angle"},{"id":"c","text":"Increased pelvic organ support"},{"id":"d","text":"Decreased intra-abdominal pressure"}],"answerId":"b","explanation":"Loss of the anorectal angle during pelvic-floor weakness indicates that the puborectalis sling is not maintaining the angle.","kind":"recall","origin":"ai"},{"id":"hrp1-pelvic-diaphragm~ai-5","moduleId":"hrp1-pelvic-diaphragm","stem":"How does the pelvic diaphragm relate to the perineal triangles?","options":[{"id":"a","text":"It forms the base of the triangles"},{"id":"b","text":"It is innervated by the same nerves"},{"id":"c","text":"It supports the triangles during contraction"},{"id":"d","text":"It is a part of the triangles' fascia"}],"answerId":"a","explanation":"The pelvic diaphragm forms the base of the perineal triangles, providing structural support.","kind":"integration","linkedModuleIds":["hrp1-perineal-spaces-triangles"],"origin":"ai"},{"id":"hrp1-pelvic-diaphragm~ai-6","moduleId":"hrp1-pelvic-diaphragm","stem":"Which structure is primarily responsible for the erectile function of the external genitalia in relation to pelvic diaphragm support?","options":[{"id":"a","text":"Puborectalis"},{"id":"b","text":"Coccygeus"},{"id":"c","text":"Iliococcygeus"},{"id":"d","text":"Pudendal nerve"}],"answerId":"d","explanation":"The pudendal nerve is crucial for the erectile function of external genitalia, linking it to pelvic diaphragm support.","kind":"integration","linkedModuleIds":["hrp1-pudendal-erectile-external-genitalia"],"origin":"ai"}],"hrp1-male-perineal-pudendal-anatomy":[{"id":"hrp1-male-perineal-pudendal-anatomy~ai-0","moduleId":"hrp1-male-perineal-pudendal-anatomy","stem":"Which structure is a key landmark for pudendal nerve block?","options":[{"id":"a","text":"Ischial spine"},{"id":"b","text":"Pubic symphysis"},{"id":"c","text":"Coccyx"},{"id":"d","text":"Greater sciatic notch"}],"answerId":"a","explanation":"The ischial spine is a critical landmark for identifying the location of the pudendal nerve during a nerve block.","kind":"recall","origin":"ai"},{"id":"hrp1-male-perineal-pudendal-anatomy~ai-1","moduleId":"hrp1-male-perineal-pudendal-anatomy","stem":"What is the primary mechanism of perineal anesthesia after ischial-spine injection?","options":[{"id":"a","text":"Local anesthetic blocks sacral roots"},{"id":"b","text":"Local anesthetic reaches pudendal nerve"},{"id":"c","text":"Local anesthetic affects pelvic floor muscles"},{"id":"d","text":"Local anesthetic targets the inferior rectal nerve"}],"answerId":"b","explanation":"The local anesthetic reaches the pudendal nerve near the sacrospinous ligament, providing perineal anesthesia.","kind":"mechanism","origin":"ai"},{"id":"hrp1-male-perineal-pudendal-anatomy~ai-2","moduleId":"hrp1-male-perineal-pudendal-anatomy","stem":"Which statement correctly describes the course of the pudendal nerve?","options":[{"id":"a","text":"It remains inside the pelvis to reach the perineum"},{"id":"b","text":"It exits and re-enters through the greater and lesser sciatic foramina"},{"id":"c","text":"It travels through the inguinal canal"},{"id":"d","text":"It follows the inferior gluteal artery"}],"answerId":"b","explanation":"The pudendal nerve exits the pelvis and loops around the ischial spine before re-entering the perineum.","kind":"trap","origin":"ai"},{"id":"hrp1-male-perineal-pudendal-anatomy~ai-3","moduleId":"hrp1-male-perineal-pudendal-anatomy","stem":"A patient presents with perineal pain worsened by sitting. Which condition is likely?","options":[{"id":"a","text":"Pudendal nerve entrapment"},{"id":"b","text":"Prostatitis"},{"id":"c","text":"Hernia"},{"id":"d","text":"Coccydynia"}],"answerId":"a","explanation":"Pudendal nerve entrapment often presents with pain that worsens with sitting due to nerve compression.","kind":"clinical","origin":"ai"},{"id":"hrp1-male-perineal-pudendal-anatomy~ai-4","moduleId":"hrp1-male-perineal-pudendal-anatomy","stem":"Which structure is found in the superficial perineal pouch?","options":[{"id":"a","text":"External urethral sphincter"},{"id":"b","text":"Bulbourethral glands"},{"id":"c","text":"Proximal urethra"},{"id":"d","text":"Rectum"}],"answerId":"b","explanation":"The bulbourethral glands are located in the superficial perineal pouch, while the external urethral sphincter is in the deep pouch.","kind":"recall","origin":"ai"},{"id":"hrp1-male-perineal-pudendal-anatomy~ai-5","moduleId":"hrp1-male-perineal-pudendal-anatomy","stem":"How does the anatomy of the pudendal nerve relate to the inguinal canal?","options":[{"id":"a","text":"It passes through the inguinal canal"},{"id":"b","text":"It is a branch of the ilioinguinal nerve"},{"id":"c","text":"It exits the pelvis and does not enter the inguinal canal"},{"id":"d","text":"It innervates structures within the inguinal canal"}],"answerId":"c","explanation":"The pudendal nerve exits the pelvis and does not pass through the inguinal canal, which is a common misconception.","kind":"integration","linkedModuleIds":["inguinal-canal-hernias"],"origin":"ai"},{"id":"hrp1-male-perineal-pudendal-anatomy~ai-6","moduleId":"hrp1-male-perineal-pudendal-anatomy","stem":"Which gland's anatomy is closely related to the pudendal nerve's course?","options":[{"id":"a","text":"Prostate gland"},{"id":"b","text":"Seminal vesicles"},{"id":"c","text":"Epididymis"},{"id":"d","text":"Testis"}],"answerId":"a","explanation":"The prostate gland's anatomy is closely related to the pudendal nerve's course, especially in terms of nerve innervation and potential entrapment.","kind":"integration","linkedModuleIds":["hrp1-male-accessory-glands-anatomy"],"origin":"ai"}],"hrp1-cervix-vagina-histology":[{"id":"hrp1-cervix-vagina-histology~ai-0","moduleId":"hrp1-cervix-vagina-histology","stem":"What type of epithelium lines the endocervix?","options":[{"id":"a","text":"Nonkeratinized stratified squamous epithelium"},{"id":"b","text":"Simple columnar epithelium"},{"id":"c","text":"Keratinized stratified squamous epithelium"},{"id":"d","text":"Transitional epithelium"}],"answerId":"b","explanation":"The endocervix is lined by mucus-secreting simple columnar epithelium.","kind":"recall","origin":"ai"},{"id":"hrp1-cervix-vagina-histology~ai-1","moduleId":"hrp1-cervix-vagina-histology","stem":"Which area is most susceptible to HPV-related dysplasia?","options":[{"id":"a","text":"Endocervix"},{"id":"b","text":"Ectocervix"},{"id":"c","text":"Transformation zone"},{"id":"d","text":"Vagina"}],"answerId":"c","explanation":"The transformation zone around the squamocolumnar junction is the key site for HPV-related dysplasia.","kind":"recall","origin":"ai"},{"id":"hrp1-cervix-vagina-histology~ai-2","moduleId":"hrp1-cervix-vagina-histology","stem":"What is the primary source of lubrication in the vagina?","options":[{"id":"a","text":"Vaginal mucosal glands"},{"id":"b","text":"Cervical mucus"},{"id":"c","text":"Transudate"},{"id":"d","text":"Vestibular glands"}],"answerId":"b","explanation":"Vaginal lubrication primarily comes from cervical mucus, transudate, and vestibular glands, not from vaginal mucosal glands.","kind":"trap","origin":"ai"},{"id":"hrp1-cervix-vagina-histology~ai-3","moduleId":"hrp1-cervix-vagina-histology","stem":"What is the primary function of lactobacilli in the vagina?","options":[{"id":"a","text":"Produce estrogen"},{"id":"b","text":"Metabolize glycogen to lactic acid"},{"id":"c","text":"Secrete mucus"},{"id":"d","text":"Enhance sperm motility"}],"answerId":"b","explanation":"Lactobacilli metabolize epithelial glycogen to lactic acid, maintaining an acidic vaginal pH.","kind":"mechanism","origin":"ai"},{"id":"hrp1-cervix-vagina-histology~ai-4","moduleId":"hrp1-cervix-vagina-histology","stem":"Which histological feature is absent in the vagina?","options":[{"id":"a","text":"Nonkeratinized stratified squamous epithelium"},{"id":"b","text":"Smooth muscle wall"},{"id":"c","text":"Glands"},{"id":"d","text":"Elastic adventitia"}],"answerId":"c","explanation":"The vagina has no glands; lubrication is derived from cervical mucus and transudate.","kind":"recall","origin":"ai"},{"id":"hrp1-cervix-vagina-histology~ai-5","moduleId":"hrp1-cervix-vagina-histology","stem":"How does the transformation zone adapt to the vaginal environment?","options":[{"id":"a","text":"By increasing glandular secretion"},{"id":"b","text":"Through metaplasia"},{"id":"c","text":"By thickening the epithelium"},{"id":"d","text":"By increasing vascularity"}],"answerId":"b","explanation":"The transformation zone undergoes metaplasia to adapt to the vaginal environment, making it vulnerable to HPV dysplasia.","kind":"mechanism","origin":"ai"},{"id":"hrp1-cervix-vagina-histology~ai-6","moduleId":"hrp1-cervix-vagina-histology","stem":"How does glycogen metabolism relate to vaginal health?","options":[{"id":"a","text":"Increases estrogen levels"},{"id":"b","text":"Supports acidic pH via lactic acid"},{"id":"c","text":"Enhances immune response"},{"id":"d","text":"Promotes glandular secretion"}],"answerId":"b","explanation":"Glycogen metabolism by lactobacilli produces lactic acid, which supports an acidic vaginal pH, crucial for preventing infections.","kind":"integration","linkedModuleIds":["glycogen-synthesis-breakdown"],"origin":"ai"},{"id":"hrp1-cervix-vagina-histology~ai-7","moduleId":"hrp1-cervix-vagina-histology","stem":"What is the role of estrogen in the vaginal epithelium?","options":[{"id":"a","text":"Stimulates glycogen production"},{"id":"b","text":"Increases glandular secretion"},{"id":"c","text":"Enhances keratinization"},{"id":"d","text":"Reduces lactobacilli growth"}],"answerId":"a","explanation":"Estrogen stimulates glycogen production in the vaginal epithelium, which is then metabolized by lactobacilli.","kind":"integration","linkedModuleIds":["glycogen-synthesis-breakdown"],"origin":"ai"}],"hrp1-placenta-villi-barrier-circulation":[{"id":"hrp1-placenta-villi-barrier-circulation~ai-0","moduleId":"hrp1-placenta-villi-barrier-circulation","stem":"What is the primary function of the syncytiotrophoblast in the placenta?","options":[{"id":"a","text":"To provide structural support to fetal tissues"},{"id":"b","text":"To facilitate nutrient and gas exchange with maternal blood"},{"id":"c","text":"To form the fetal blood vessels within the villi"},{"id":"d","text":"To produce hormones for fetal development"}],"answerId":"b","explanation":"The syncytiotrophoblast is responsible for direct contact with maternal blood, facilitating nutrient and gas exchange.","kind":"recall","origin":"ai"},{"id":"hrp1-placenta-villi-barrier-circulation~ai-1","moduleId":"hrp1-placenta-villi-barrier-circulation","stem":"Which statement accurately describes the development of tertiary villi?","options":[{"id":"a","text":"They contain only trophoblast cells."},{"id":"b","text":"They develop fetal capillaries within the villous structure."},{"id":"c","text":"They are formed exclusively from maternal tissue."},{"id":"d","text":"They do not contribute to the placental barrier."}],"answerId":"b","explanation":"Tertiary villi develop fetal capillaries, allowing for efficient exchange with maternal blood.","kind":"recall","origin":"ai"},{"id":"hrp1-placenta-villi-barrier-circulation~ai-2","moduleId":"hrp1-placenta-villi-barrier-circulation","stem":"What occurs to the placental barrier as gestation progresses?","options":[{"id":"a","text":"It thickens to prevent maternal blood exposure."},{"id":"b","text":"It remains unchanged throughout pregnancy."},{"id":"c","text":"It thins to enhance diffusion of nutrients."},{"id":"d","text":"It becomes impermeable to all substances."}],"answerId":"c","explanation":"The placental barrier thins with gestation, improving diffusion while preventing direct mixing of maternal and fetal blood.","kind":"mechanism","origin":"ai"},{"id":"hrp1-placenta-villi-barrier-circulation~ai-3","moduleId":"hrp1-placenta-villi-barrier-circulation","stem":"Which clinical finding indicates maturation of the placenta near term?","options":[{"id":"a","text":"Increased number of fetal capillaries"},{"id":"b","text":"Presence of syncytial knots"},{"id":"c","text":"Decreased trophoblast cell layers"},{"id":"d","text":"Thickening of the placental barrier"}],"answerId":"b","explanation":"Syncytial knots increase near term, reflecting the maturation of the syncytiotrophoblast.","kind":"recall","origin":"ai"},{"id":"hrp1-placenta-villi-barrier-circulation~ai-4","moduleId":"hrp1-placenta-villi-barrier-circulation","stem":"Which of the following is a common misconception about placental circulation?","options":[{"id":"a","text":"Maternal blood nourishes the fetus directly."},{"id":"b","text":"Fetal blood is oxygenated in the placenta."},{"id":"c","text":"The placenta acts as a barrier to all maternal substances."},{"id":"d","text":"Maternal and fetal blood mix freely in the intervillous space."}],"answerId":"d","explanation":"Maternal and fetal blood remain separated by the placental barrier, which prevents direct mixing.","kind":"trap","origin":"ai"},{"id":"hrp1-placenta-villi-barrier-circulation~ai-5","moduleId":"hrp1-placenta-villi-barrier-circulation","stem":"How does fetal circulation relate to placental function?","options":[{"id":"a","text":"Fetal circulation is independent of placental exchange."},{"id":"b","text":"Fetal shunts bypass the lungs and liver, relying on placental oxygenation."},{"id":"c","text":"Fetal blood is fully oxygenated in the placenta."},{"id":"d","text":"Fetal circulation does not require maternal blood supply."}],"answerId":"b","explanation":"Fetal shunts allow blood to bypass non-functional organs, relying on the placenta for oxygenation.","kind":"integration","linkedModuleIds":["fetal-circulation-shunts"],"origin":"ai"},{"id":"hrp1-placenta-villi-barrier-circulation~ai-6","moduleId":"hrp1-placenta-villi-barrier-circulation","stem":"What is the role of maternal spiral arteries in placental circulation?","options":[{"id":"a","text":"They supply oxygenated blood directly to the fetus."},{"id":"b","text":"They deliver blood to the intervillous space for exchange."},{"id":"c","text":"They connect directly to fetal capillaries."},{"id":"d","text":"They are responsible for fetal waste removal."}],"answerId":"b","explanation":"Maternal spiral arteries deliver blood around the villi, facilitating exchange without direct mixing.","kind":"integration","linkedModuleIds":["placenta-development-circulation"],"origin":"ai"}],"hrp1-male-accessory-glands-anatomy":[{"id":"hrp1-male-accessory-glands-anatomy~ai-0","moduleId":"hrp1-male-accessory-glands-anatomy","stem":"Which structure contributes a fructose-rich alkaline fluid to semen?","options":[{"id":"a","text":"Prostate gland"},{"id":"b","text":"Seminal vesicles"},{"id":"c","text":"Bulbourethral glands"},{"id":"d","text":"Ejaculatory duct"}],"answerId":"b","explanation":"The seminal vesicles produce a fructose-rich alkaline fluid that nourishes sperm.","kind":"recall","origin":"ai"},{"id":"hrp1-male-accessory-glands-anatomy~ai-1","moduleId":"hrp1-male-accessory-glands-anatomy","stem":"What is the most common site for prostate carcinoma?","options":[{"id":"a","text":"Transition zone"},{"id":"b","text":"Peripheral zone"},{"id":"c","text":"Central zone"},{"id":"d","text":"Bulbourethral glands"}],"answerId":"b","explanation":"Prostate carcinoma commonly arises in the peripheral zone, which is palpable on examination.","kind":"recall","origin":"ai"},{"id":"hrp1-male-accessory-glands-anatomy~ai-2","moduleId":"hrp1-male-accessory-glands-anatomy","stem":"A patient presents with a weak urinary stream and difficulty urinating. Which condition is likely affecting the prostatic urethra?","options":[{"id":"a","text":"Prostate carcinoma"},{"id":"b","text":"BPH"},{"id":"c","text":"Seminal vesiculitis"},{"id":"d","text":"Ejaculatory duct obstruction"}],"answerId":"b","explanation":"Benign prostatic hyperplasia (BPH) compresses the prostatic urethra, leading to urinary symptoms.","kind":"clinical","origin":"ai"},{"id":"hrp1-male-accessory-glands-anatomy~ai-3","moduleId":"hrp1-male-accessory-glands-anatomy","stem":"Which gland adds mucus-rich pre-ejaculate to the urethra?","options":[{"id":"a","text":"Prostate gland"},{"id":"b","text":"Seminal vesicles"},{"id":"c","text":"Bulbourethral glands"},{"id":"d","text":"Ejaculatory duct"}],"answerId":"c","explanation":"The bulbourethral glands secrete a mucus-rich fluid that serves as pre-ejaculate.","kind":"recall","origin":"ai"},{"id":"hrp1-male-accessory-glands-anatomy~ai-4","moduleId":"hrp1-male-accessory-glands-anatomy","stem":"During a rectal examination, a firm irregular nodule is palpated in the posterior prostate. What is the most likely diagnosis?","options":[{"id":"a","text":"Benign prostatic hyperplasia"},{"id":"b","text":"Prostate carcinoma"},{"id":"c","text":"Prostatitis"},{"id":"d","text":"Seminal vesiculitis"}],"answerId":"b","explanation":"A firm irregular nodule in the posterior prostate is suggestive of prostate carcinoma.","kind":"clinical","origin":"ai"},{"id":"hrp1-male-accessory-glands-anatomy~ai-5","moduleId":"hrp1-male-accessory-glands-anatomy","stem":"Which statement correctly describes the zones of the prostate in relation to BPH and carcinoma?","options":[{"id":"a","text":"Both BPH and carcinoma arise in the peripheral zone"},{"id":"b","text":"BPH arises in the transition zone; carcinoma in the peripheral zone"},{"id":"c","text":"Carcinoma arises in the transition zone; BPH in the central zone"},{"id":"d","text":"BPH is always asymptomatic, while carcinoma is symptomatic"}],"answerId":"b","explanation":"BPH typically affects the transition zone, while prostate carcinoma commonly arises in the peripheral zone.","kind":"trap","origin":"ai"},{"id":"hrp1-male-accessory-glands-anatomy~ai-6","moduleId":"hrp1-male-accessory-glands-anatomy","stem":"How does the secretion of the seminal vesicles relate to the transport of sperm in the male reproductive system?","options":[{"id":"a","text":"It provides nutrients for sperm motility"},{"id":"b","text":"It neutralizes vaginal acidity"},{"id":"c","text":"It facilitates sperm transport through the vas deferens"},{"id":"d","text":"It enhances sperm production in the testes"}],"answerId":"a","explanation":"The fructose-rich fluid from seminal vesicles provides energy for sperm motility during transport.","kind":"integration","linkedModuleIds":["hrp1-testis-epididymis-vas-anatomy"],"origin":"ai"},{"id":"hrp1-male-accessory-glands-anatomy~ai-7","moduleId":"hrp1-male-accessory-glands-anatomy","stem":"What is the role of the bulbourethral glands in relation to the urethra during ejaculation?","options":[{"id":"a","text":"They produce sperm"},{"id":"b","text":"They provide lubrication"},{"id":"c","text":"They secrete fructose"},{"id":"d","text":"They neutralize urine acidity"}],"answerId":"b","explanation":"Bulbourethral glands secrete a mucus-rich fluid that lubricates the urethra prior to ejaculation.","kind":"integration","linkedModuleIds":["hrp1-male-perineal-pudendal-anatomy"],"origin":"ai"}],"hrp1-perineal-spaces-triangles":[{"id":"hrp1-perineal-spaces-triangles~ai-0","moduleId":"hrp1-perineal-spaces-triangles","stem":"What structure forms the key boundary between the superficial and deep perineal pouches?","options":[{"id":"a","text":"Colles fascia"},{"id":"b","text":"Perineal membrane"},{"id":"c","text":"Ischiocavernosus muscle"},{"id":"d","text":"Bulbospongiosus muscle"}],"answerId":"b","explanation":"The perineal membrane serves as the crucial boundary separating the superficial pouch from the deep pouch.","kind":"recall","origin":"ai"},{"id":"hrp1-perineal-spaces-triangles~ai-1","moduleId":"hrp1-perineal-spaces-triangles","stem":"In the case of a spongy urethral rupture, where would urine extravasation most likely be found?","options":[{"id":"a","text":"Thigh"},{"id":"b","text":"Superficial perineum"},{"id":"c","text":"Deep perineal pouch"},{"id":"d","text":"Abdominal cavity"}],"answerId":"b","explanation":"Urine from a spongy urethral rupture tracks within the superficial fascia, leading to extravasation in the superficial perineum.","kind":"recall","origin":"ai"},{"id":"hrp1-perineal-spaces-triangles~ai-2","moduleId":"hrp1-perineal-spaces-triangles","stem":"Which of the following correctly describes the spread of fluid in perineal injuries?","options":[{"id":"a","text":"Fluid spreads freely into the thigh"},{"id":"b","text":"Fluid is contained within the deep pouch"},{"id":"c","text":"Fluid spreads along fascial planes"},{"id":"d","text":"Fluid is limited to the superficial pouch"}],"answerId":"c","explanation":"Fluid spread is determined by fascial attachments that channel the fluid rather than allowing random dispersion.","kind":"trap","origin":"ai"},{"id":"hrp1-perineal-spaces-triangles~ai-3","moduleId":"hrp1-perineal-spaces-triangles","stem":"What clinical finding is associated with ischioanal abscesses?","options":[{"id":"a","text":"Fluid in the scrotum"},{"id":"b","text":"Urine in the abdominal cavity"},{"id":"c","text":"Foul-smelling discharge from the anal canal"},{"id":"d","text":"Swelling in the posterior perineum"}],"answerId":"d","explanation":"Ischioanal abscesses typically present as swelling in the posterior perineum due to the communication of fat-filled fossae around the anal canal.","kind":"recall","origin":"ai"},{"id":"hrp1-perineal-spaces-triangles~ai-4","moduleId":"hrp1-perineal-spaces-triangles","stem":"Which muscle is primarily responsible for maintaining erection by compressing the erectile tissues?","options":[{"id":"a","text":"Bulbospongiosus"},{"id":"b","text":"Ischiocavernosus"},{"id":"c","text":"External urethral sphincter"},{"id":"d","text":"Levator ani"}],"answerId":"b","explanation":"The ischiocavernosus muscle compresses the erectile tissues, aiding in the maintenance of an erection.","kind":"mechanism","origin":"ai"},{"id":"hrp1-perineal-spaces-triangles~ai-5","moduleId":"hrp1-perineal-spaces-triangles","stem":"How does the perineal membrane relate to the pelvic diaphragm?","options":[{"id":"a","text":"It is a continuation of the pelvic diaphragm"},{"id":"b","text":"It separates the pelvic cavity from the perineum"},{"id":"c","text":"It forms the floor of the deep pouch"},{"id":"d","text":"It is attached to the pelvic diaphragm"}],"answerId":"b","explanation":"The perineal membrane separates the pelvic cavity from the perineum, providing a boundary between the two regions.","kind":"integration","linkedModuleIds":["hrp1-pelvic-diaphragm"],"origin":"ai"},{"id":"hrp1-perineal-spaces-triangles~ai-6","moduleId":"hrp1-perineal-spaces-triangles","stem":"What is the clinical significance of the fascial attachments in the perineum?","options":[{"id":"a","text":"They allow for free movement of urine"},{"id":"b","text":"They prevent infection spread"},{"id":"c","text":"They channel fluid spread in injuries"},{"id":"d","text":"They support pelvic organs"}],"answerId":"c","explanation":"Fascial attachments in the perineum channel fluid spread in cases of injury, influencing the clinical management of such injuries.","kind":"integration","linkedModuleIds":["hrp1-pudendal-erectile-external-genitalia"],"origin":"ai"}],"hrp1-breast-gross-lymphatic-anatomy":[{"id":"hrp1-breast-gross-lymphatic-anatomy~ai-0","moduleId":"hrp1-breast-gross-lymphatic-anatomy","stem":"Which structure primarily supports the breast tissue and connects it to the underlying fascia?","options":[{"id":"a","text":"Lactiferous ducts"},{"id":"b","text":"Cooper ligaments"},{"id":"c","text":"Pectoralis major"},{"id":"d","text":"Serratus anterior"}],"answerId":"b","explanation":"Cooper ligaments, or suspensory ligaments, connect the dermis of the breast to the deep fascia, providing structural support.","kind":"recall","origin":"ai"},{"id":"hrp1-breast-gross-lymphatic-anatomy~ai-1","moduleId":"hrp1-breast-gross-lymphatic-anatomy","stem":"What is the primary lymphatic drainage pathway for the breast?","options":[{"id":"a","text":"Internal mammary nodes"},{"id":"b","text":"Supraclavicular nodes"},{"id":"c","text":"Axillary nodes"},{"id":"d","text":"Cervical nodes"}],"answerId":"c","explanation":"Most lymphatic drainage from the breast occurs through the axillary nodes, particularly the pectoral/anterior group.","kind":"recall","origin":"ai"},{"id":"hrp1-breast-gross-lymphatic-anatomy~ai-2","moduleId":"hrp1-breast-gross-lymphatic-anatomy","stem":"A patient presents with skin dimpling over a breast mass. What is the underlying mechanism?","options":[{"id":"a","text":"Increased lymphatic drainage"},{"id":"b","text":"Tumor infiltration of Cooper ligaments"},{"id":"c","text":"Fibrosis of breast tissue"},{"id":"d","text":"Inflammatory changes"}],"answerId":"b","explanation":"Skin dimpling occurs when a tumor infiltrates Cooper ligaments, causing them to shorten and pull the skin inward.","kind":"mechanism","origin":"ai"},{"id":"hrp1-breast-gross-lymphatic-anatomy~ai-3","moduleId":"hrp1-breast-gross-lymphatic-anatomy","stem":"After an axillary dissection, a patient develops a winged scapula. Which nerve is primarily injured?","options":[{"id":"a","text":"Axillary nerve"},{"id":"b","text":"Thoracodorsal nerve"},{"id":"c","text":"Long thoracic nerve"},{"id":"d","text":"Medial pectoral nerve"}],"answerId":"c","explanation":"The long thoracic nerve innervates the serratus anterior muscle, and its injury leads to winging of the scapula.","kind":"clinical","origin":"ai"},{"id":"hrp1-breast-gross-lymphatic-anatomy~ai-4","moduleId":"hrp1-breast-gross-lymphatic-anatomy","stem":"Which of the following is a common misconception regarding nerve injuries during axillary surgery?","options":[{"id":"a","text":"Axillary nerve injury causes winged scapula"},{"id":"b","text":"Long thoracic nerve supplies the serratus anterior"},{"id":"c","text":"Thoracodorsal nerve affects latissimus dorsi"},{"id":"d","text":"Medial pectoral nerve affects pectoralis major"}],"answerId":"a","explanation":"Axillary nerve injury does not cause winged scapula; this condition is due to long thoracic nerve injury affecting the serratus anterior.","kind":"trap","origin":"ai"},{"id":"hrp1-breast-gross-lymphatic-anatomy~ai-5","moduleId":"hrp1-breast-gross-lymphatic-anatomy","stem":"How does the lymphatic drainage of the medial quadrants of the breast differ from the lateral quadrants?","options":[{"id":"a","text":"Medial quadrants drain to axillary nodes"},{"id":"b","text":"Medial quadrants drain to cervical nodes"},{"id":"c","text":"Medial quadrants drain to parasternal nodes"},{"id":"d","text":"Medial quadrants have no lymphatic drainage"}],"answerId":"c","explanation":"Medial quadrants of the breast primarily drain to parasternal nodes, while lateral quadrants drain to axillary nodes.","kind":"recall","origin":"ai"},{"id":"hrp1-breast-gross-lymphatic-anatomy~ai-6","moduleId":"hrp1-breast-gross-lymphatic-anatomy","stem":"In patients with BRCA1 mutations, what is the significance of understanding breast lymphatic anatomy?","options":[{"id":"a","text":"It helps in predicting tumor size"},{"id":"b","text":"It aids in surgical planning for mastectomy"},{"id":"c","text":"It determines the need for chemotherapy"},{"id":"d","text":"It influences radiation therapy techniques"}],"answerId":"b","explanation":"Understanding breast lymphatic anatomy is crucial for surgical planning, especially in patients with BRCA1 mutations who may undergo mastectomy.","kind":"integration","linkedModuleIds":["brca1-tnbc-homologous-repair"],"origin":"ai"},{"id":"hrp1-breast-gross-lymphatic-anatomy~ai-7","moduleId":"hrp1-breast-gross-lymphatic-anatomy","stem":"How does the knowledge of breast lymphatics assist in staging breast cancer?","options":[{"id":"a","text":"It predicts tumor grade"},{"id":"b","text":"It identifies distant metastasis"},{"id":"c","text":"It determines lymph node involvement"},{"id":"d","text":"It assesses hormone receptor status"}],"answerId":"c","explanation":"Knowledge of breast lymphatics is essential for determining lymph node involvement, which is a key factor in cancer staging.","kind":"integration","linkedModuleIds":["cancer-spread-staging-clinical"],"origin":"ai"}],"hrp1-mammary-gland-histology":[{"id":"hrp1-mammary-gland-histology~ai-0","moduleId":"hrp1-mammary-gland-histology","stem":"What type of gland is the mammary gland classified as?","options":[{"id":"a","text":"Merocrine gland"},{"id":"b","text":"Holocrine gland"},{"id":"c","text":"Modified tubuloalveolar gland"},{"id":"d","text":"Apocrine gland"}],"answerId":"c","explanation":"The mammary gland is classified as a modified tubuloalveolar gland due to its structure and function.","kind":"recall","origin":"ai"},{"id":"hrp1-mammary-gland-histology~ai-1","moduleId":"hrp1-mammary-gland-histology","stem":"Which hormone is primarily responsible for the ductal branching during pregnancy?","options":[{"id":"a","text":"Prolactin"},{"id":"b","text":"Estrogen"},{"id":"c","text":"Oxytocin"},{"id":"d","text":"Progesterone"}],"answerId":"b","explanation":"Estrogen is primarily responsible for ductal branching during pregnancy.","kind":"mechanism","origin":"ai"},{"id":"hrp1-mammary-gland-histology~ai-2","moduleId":"hrp1-mammary-gland-histology","stem":"What is the primary mechanism of protein secretion in lactating alveolar cells?","options":[{"id":"a","text":"Apocrine secretion"},{"id":"b","text":"Merocrine exocytosis"},{"id":"c","text":"Holocrine secretion"},{"id":"d","text":"Endocytosis"}],"answerId":"b","explanation":"Lactating alveolar cells secrete protein primarily by merocrine exocytosis.","kind":"recall","origin":"ai"},{"id":"hrp1-mammary-gland-histology~ai-3","moduleId":"hrp1-mammary-gland-histology","stem":"Which of the following findings is characteristic of an inactive nonpregnant breast?","options":[{"id":"a","text":"Numerous distended alveoli with secretory material"},{"id":"b","text":"Mostly ducts embedded in dense/adipose stroma"},{"id":"c","text":"Prominent lobuloalveolar structures"},{"id":"d","text":"Increased myoepithelial cell activity"}],"answerId":"b","explanation":"An inactive nonpregnant breast is characterized by mostly ducts embedded in dense/adipose stroma.","kind":"recall","origin":"ai"},{"id":"hrp1-mammary-gland-histology~ai-4","moduleId":"hrp1-mammary-gland-histology","stem":"What occurs to the mammary gland after weaning?","options":[{"id":"a","text":"Increased secretory activity"},{"id":"b","text":"Involution of secretory alveoli"},{"id":"c","text":"Ductal branching"},{"id":"d","text":"Formation of new lobules"}],"answerId":"b","explanation":"After weaning, involution occurs, which removes many secretory alveoli and restores a more inactive pattern.","kind":"recall","origin":"ai"},{"id":"hrp1-mammary-gland-histology~ai-5","moduleId":"hrp1-mammary-gland-histology","stem":"How does the secretion of lipid in milk differ from that of protein?","options":[{"id":"a","text":"Both use identical secretory mechanisms"},{"id":"b","text":"Lipid uses merocrine exocytosis; protein buds apically"},{"id":"c","text":"Protein uses merocrine exocytosis; lipid buds apically"},{"id":"d","text":"Both are secreted by apocrine mechanisms"}],"answerId":"c","explanation":"Lipid is secreted by apocrine-like budding while protein uses merocrine exocytosis, highlighting their distinct secretion mechanisms.","kind":"trap","origin":"ai"},{"id":"hrp1-mammary-gland-histology~ai-6","moduleId":"hrp1-mammary-gland-histology","stem":"Which anatomical feature is essential for understanding lymphatic drainage of the breast?","options":[{"id":"a","text":"Mammary ducts"},{"id":"b","text":"Lobules"},{"id":"c","text":"Lymph nodes"},{"id":"d","text":"Alveoli"}],"answerId":"c","explanation":"Understanding lymphatic drainage of the breast is essential for clinical assessments and is closely tied to lymph nodes.","kind":"integration","linkedModuleIds":["hrp1-breast-gross-lymphatic-anatomy"],"origin":"ai"},{"id":"hrp1-mammary-gland-histology~ai-7","moduleId":"hrp1-mammary-gland-histology","stem":"What is the role of the placenta in relation to mammary gland development during pregnancy?","options":[{"id":"a","text":"Produces milk"},{"id":"b","text":"Supplies hormones influencing mammary growth"},{"id":"c","text":"Facilitates lactation"},{"id":"d","text":"Regulates myoepithelial contraction"}],"answerId":"b","explanation":"The placenta supplies hormones that influence mammary gland growth and development during pregnancy.","kind":"integration","linkedModuleIds":["hrp1-placenta-villi-barrier-circulation"],"origin":"ai"}],"hrp1-male-duct-gland-penis-histology":[{"id":"hrp1-male-duct-gland-penis-histology~ai-0","moduleId":"hrp1-male-duct-gland-penis-histology","stem":"Which structure in the male reproductive system is characterized by a pseudostratified epithelium with stereocilia?","options":[{"id":"a","text":"Vas deferens"},{"id":"b","text":"Epididymis"},{"id":"c","text":"Seminal vesicle"},{"id":"d","text":"Prostate gland"}],"answerId":"b","explanation":"The epididymis has a pseudostratified epithelium with stereocilia, which aids in the absorption and modification of luminal fluid.","kind":"recall","origin":"ai"},{"id":"hrp1-male-duct-gland-penis-histology~ai-1","moduleId":"hrp1-male-duct-gland-penis-histology","stem":"What is the primary function of the seminal vesicles?","options":[{"id":"a","text":"Sperm storage"},{"id":"b","text":"Semen production"},{"id":"c","text":"Sperm maturation"},{"id":"d","text":"Sperm transport"}],"answerId":"b","explanation":"The seminal vesicles produce a significant portion of the seminal fluid, contributing to semen production.","kind":"recall","origin":"ai"},{"id":"hrp1-male-duct-gland-penis-histology~ai-2","moduleId":"hrp1-male-duct-gland-penis-histology","stem":"Which histological feature distinguishes the vas deferens?","options":[{"id":"a","text":"Highly folded mucosa"},{"id":"b","text":"Pseudostratified epithelium"},{"id":"c","text":"Narrow folded lumen with thick muscular wall"},{"id":"d","text":"Tubuloalveolar glands"}],"answerId":"c","explanation":"The vas deferens is characterized by a narrow folded lumen and an exceptionally thick three-layer muscular wall, essential for sperm emission.","kind":"recall","origin":"ai"},{"id":"hrp1-male-duct-gland-penis-histology~ai-3","moduleId":"hrp1-male-duct-gland-penis-histology","stem":"What is the role of the tunica albuginea in the penis?","options":[{"id":"a","text":"Facilitates erection"},{"id":"b","text":"Provides structural support"},{"id":"c","text":"Aids in sperm transport"},{"id":"d","text":"Secretes seminal fluid"}],"answerId":"b","explanation":"The tunica albuginea provides structural support to the penis, enclosing the corpora cavernosa and corpus spongiosum.","kind":"recall","origin":"ai"},{"id":"hrp1-male-duct-gland-penis-histology~ai-4","moduleId":"hrp1-male-duct-gland-penis-histology","stem":"Which of the following statements about epididymal stereocilia is correct?","options":[{"id":"a","text":"They are motile cilia"},{"id":"b","text":"They are nonmotile microvilli"},{"id":"c","text":"They propel sperm"},{"id":"d","text":"They are involved in sperm storage"}],"answerId":"b","explanation":"Epididymal stereocilia are long nonmotile microvilli that function in absorption and secretion, not in propulsion.","kind":"trap","origin":"ai"},{"id":"hrp1-male-duct-gland-penis-histology~ai-5","moduleId":"hrp1-male-duct-gland-penis-histology","stem":"How does the vas deferens contribute to male fertility?","options":[{"id":"a","text":"By producing sperm"},{"id":"b","text":"By storing sperm"},{"id":"c","text":"By transporting sperm during ejaculation"},{"id":"d","text":"By nourishing sperm"}],"answerId":"c","explanation":"The vas deferens transports sperm from the epididymis to the ejaculatory duct during ejaculation.","kind":"mechanism","origin":"ai"},{"id":"hrp1-male-duct-gland-penis-histology~ai-6","moduleId":"hrp1-male-duct-gland-penis-histology","stem":"Which structure is primarily responsible for the blood-testis barrier?","options":[{"id":"a","text":"Sertoli cells"},{"id":"b","text":"Leydig cells"},{"id":"c","text":"Epididymis"},{"id":"d","text":"Seminal vesicles"}],"answerId":"a","explanation":"Sertoli cells form the blood-testis barrier, which protects developing sperm from the immune system.","kind":"integration","linkedModuleIds":["hrp1-sertoli-leydig-histology"],"origin":"ai"},{"id":"hrp1-male-duct-gland-penis-histology~ai-7","moduleId":"hrp1-male-duct-gland-penis-histology","stem":"What is the relationship between spermatogenesis and the structures of the male reproductive system?","options":[{"id":"a","text":"Spermatogenesis occurs in the seminal vesicles"},{"id":"b","text":"Spermatogenesis is independent of the epididymis"},{"id":"c","text":"Spermatogenesis is supported by Sertoli cells in the seminiferous tubules"},{"id":"d","text":"Spermatogenesis is completed in the vas deferens"}],"answerId":"c","explanation":"Sertoli cells in the seminiferous tubules support spermatogenesis by providing nourishment and forming the blood-testis barrier.","kind":"integration","linkedModuleIds":["hrp1-seminiferous-epithelium-spermatogenesis"],"origin":"ai"}],"hrp1-seminiferous-epithelium-spermatogenesis":[{"id":"hrp1-seminiferous-epithelium-spermatogenesis~ai-0","moduleId":"hrp1-seminiferous-epithelium-spermatogenesis","stem":"Which cell type in the seminiferous tubules is responsible for supporting and nourishing developing sperm?","options":[{"id":"a","text":"Spermatogonia"},{"id":"b","text":"Sertoli cells"},{"id":"c","text":"Leydig cells"},{"id":"d","text":"Spermatids"}],"answerId":"b","explanation":"Sertoli cells provide structural and nutritional support to developing sperm cells.","kind":"recall","origin":"ai"},{"id":"hrp1-seminiferous-epithelium-spermatogenesis~ai-1","moduleId":"hrp1-seminiferous-epithelium-spermatogenesis","stem":"What is the primary event occurring during meiosis I in primary spermatocytes?","options":[{"id":"a","text":"Spermiogenesis"},{"id":"b","text":"Chromosomal crossover"},{"id":"c","text":"Reduction of chromosome number"},{"id":"d","text":"Formation of spermatids"}],"answerId":"c","explanation":"Meiosis I in primary spermatocytes results in the reduction of chromosome number from diploid to haploid.","kind":"mechanism","origin":"ai"},{"id":"hrp1-seminiferous-epithelium-spermatogenesis~ai-2","moduleId":"hrp1-seminiferous-epithelium-spermatogenesis","stem":"Which of the following findings would indicate the presence of late spermatids in the seminiferous epithelium?","options":[{"id":"a","text":"Large cells with coarse meiotic chromatin"},{"id":"b","text":"Elongated dense nuclei near the lumen"},{"id":"c","text":"Spherical cells with prominent nucleoli"},{"id":"d","text":"Clusters of spermatogonia at the base"}],"answerId":"b","explanation":"Late spermatids are characterized by elongated dense nuclei as they undergo spermiogenesis.","kind":"recall","origin":"ai"},{"id":"hrp1-seminiferous-epithelium-spermatogenesis~ai-3","moduleId":"hrp1-seminiferous-epithelium-spermatogenesis","stem":"What is the primary difference between spermiogenesis and spermatogenesis?","options":[{"id":"a","text":"Spermiogenesis involves meiosis"},{"id":"b","text":"Spermatogenesis includes multiple divisions"},{"id":"c","text":"Spermiogenesis is structural remodeling"},{"id":"d","text":"Spermatogenesis produces motile sperm"}],"answerId":"c","explanation":"Spermiogenesis is a process of structural remodeling of haploid spermatids without further division.","kind":"trap","origin":"ai"},{"id":"hrp1-seminiferous-epithelium-spermatogenesis~ai-4","moduleId":"hrp1-seminiferous-epithelium-spermatogenesis","stem":"During which phase do spermatids undergo the formation of the acrosome?","options":[{"id":"a","text":"Spermatogenesis"},{"id":"b","text":"Spermiogenesis"},{"id":"c","text":"Meiosis I"},{"id":"d","text":"Meiosis II"}],"answerId":"b","explanation":"The formation of the acrosome occurs during spermiogenesis, which is the final stage of sperm development.","kind":"mechanism","origin":"ai"},{"id":"hrp1-seminiferous-epithelium-spermatogenesis~ai-5","moduleId":"hrp1-seminiferous-epithelium-spermatogenesis","stem":"How does spermiation differ from spermatogenesis?","options":[{"id":"a","text":"Spermiation is a meiotic division"},{"id":"b","text":"Spermiation releases mature sperm"},{"id":"c","text":"Spermiation is the release of sperm into the lumen"},{"id":"d","text":"Spermiation occurs in the epididymis"}],"answerId":"c","explanation":"Spermiation refers to the release of immature sperm into the lumen of the seminiferous tubules.","kind":"trap","origin":"ai"},{"id":"hrp1-seminiferous-epithelium-spermatogenesis~ai-6","moduleId":"hrp1-seminiferous-epithelium-spermatogenesis","stem":"How does the process of spermatogenesis relate to oogenesis in females?","options":[{"id":"a","text":"Both processes involve meiosis II"},{"id":"b","text":"Both processes produce haploid gametes"},{"id":"c","text":"Spermatogenesis occurs in the ovaries"},{"id":"d","text":"Oogenesis occurs in the seminiferous tubules"}],"answerId":"b","explanation":"Both spermatogenesis and oogenesis involve meiosis to produce haploid gametes, though they differ in timing and structure.","kind":"integration","linkedModuleIds":["gametogenesis-female-tract"],"origin":"ai"},{"id":"hrp1-seminiferous-epithelium-spermatogenesis~ai-7","moduleId":"hrp1-seminiferous-epithelium-spermatogenesis","stem":"What is a key histological feature of Sertoli cells that distinguishes them from Leydig cells?","options":[{"id":"a","text":"Presence of testosterone"},{"id":"b","text":"Location in the interstitial space"},{"id":"c","text":"Support of germ cell development"},{"id":"d","text":"Production of spermatozoa"}],"answerId":"c","explanation":"Sertoli cells are located within the seminiferous tubules and support germ cell development, while Leydig cells are interstitial and produce testosterone.","kind":"integration","linkedModuleIds":["hrp1-sertoli-leydig-histology"],"origin":"ai"}],"hrp1-ovarian-steroid-two-cell-model":[{"id":"hrp1-ovarian-steroid-two-cell-model~ai-0","moduleId":"hrp1-ovarian-steroid-two-cell-model","stem":"Which hormone stimulates theca interna cells to synthesize androgens from cholesterol?","options":[{"id":"a","text":"FSH"},{"id":"b","text":"LH"},{"id":"c","text":"Estrogen"},{"id":"d","text":"Progesterone"}],"answerId":"b","explanation":"LH stimulates theca interna cells to convert cholesterol into androgens, which are then used by granulosa cells.","kind":"recall","origin":"ai"},{"id":"hrp1-ovarian-steroid-two-cell-model~ai-1","moduleId":"hrp1-ovarian-steroid-two-cell-model","stem":"What is the primary role of FSH in the ovarian two-cell model?","options":[{"id":"a","text":"Stimulates theca cells to produce androgens"},{"id":"b","text":"Promotes aromatization of androgens to estradiol"},{"id":"c","text":"Inhibits progesterone synthesis"},{"id":"d","text":"Enhances androgen synthesis in theca cells"}],"answerId":"b","explanation":"FSH promotes the conversion of androgens to estradiol by stimulating aromatase in granulosa cells.","kind":"mechanism","origin":"ai"},{"id":"hrp1-ovarian-steroid-two-cell-model~ai-2","moduleId":"hrp1-ovarian-steroid-two-cell-model","stem":"Which of the following findings indicates rising estradiol levels during follicular growth?","options":[{"id":"a","text":"Increased FSH levels"},{"id":"b","text":"Increased granulosa cell mass"},{"id":"c","text":"Decreased LH levels"},{"id":"d","text":"Increased theca cell activity"}],"answerId":"b","explanation":"Rising estradiol levels correlate with an increase in granulosa cell mass and aromatase activity.","kind":"recall","origin":"ai"},{"id":"hrp1-ovarian-steroid-two-cell-model~ai-3","moduleId":"hrp1-ovarian-steroid-two-cell-model","stem":"In the ovarian two-cell model, which statement is true regarding theca and granulosa cells?","options":[{"id":"a","text":"Granulosa cells synthesize all androgen de novo"},{"id":"b","text":"Theca cells lack aromatase"},{"id":"c","text":"Both cell types produce progesterone before luteinization"},{"id":"d","text":"Granulosa cells respond to LH directly"}],"answerId":"b","explanation":"Theca cells lack sufficient aromatase and provide androgens to granulosa cells for conversion to estradiol.","kind":"trap","origin":"ai"},{"id":"hrp1-ovarian-steroid-two-cell-model~ai-4","moduleId":"hrp1-ovarian-steroid-two-cell-model","stem":"What effect does inhibin have on FSH secretion?","options":[{"id":"a","text":"Stimulates FSH secretion"},{"id":"b","text":"Inhibits FSH secretion"},{"id":"c","text":"Has no effect on FSH"},{"id":"d","text":"Promotes LH secretion"}],"answerId":"b","explanation":"Inhibin specifically suppresses FSH secretion from the anterior pituitary.","kind":"recall","origin":"ai"},{"id":"hrp1-ovarian-steroid-two-cell-model~ai-5","moduleId":"hrp1-ovarian-steroid-two-cell-model","stem":"How does the two-cell model of ovarian steroidogenesis relate to the action of GnRH agonists?","options":[{"id":"a","text":"They directly stimulate granulosa cells"},{"id":"b","text":"They increase LH and FSH secretion"},{"id":"c","text":"They inhibit theca cell function"},{"id":"d","text":"They promote estradiol synthesis from cholesterol"}],"answerId":"b","explanation":"GnRH agonists stimulate the pituitary to release LH and FSH, which are crucial for the two-cell model's function.","kind":"integration","linkedModuleIds":["gnrh-gonadotropin-drugs"],"origin":"ai"},{"id":"hrp1-ovarian-steroid-two-cell-model~ai-6","moduleId":"hrp1-ovarian-steroid-two-cell-model","stem":"During which phase of the ovarian cycle does the two-cell model primarily operate?","options":[{"id":"a","text":"Follicular phase"},{"id":"b","text":"Ovulatory phase"},{"id":"c","text":"Luteal phase"},{"id":"d","text":"Menstrual phase"}],"answerId":"a","explanation":"The two-cell model is most active during the follicular phase when estradiol is being synthesized.","kind":"integration","linkedModuleIds":["hrp1-ovarian-cycle-ovulation"],"origin":"ai"}],"hrp1-peripheral-precocious-puberty":[{"id":"hrp1-peripheral-precocious-puberty~ai-0","moduleId":"hrp1-peripheral-precocious-puberty","stem":"What is the primary cause of peripheral precocious puberty?","options":[{"id":"a","text":"Central GnRH secretion"},{"id":"b","text":"Exogenous steroid exposure"},{"id":"c","text":"Increased FSH levels"},{"id":"d","text":"Genetic mutations in the HPG axis"}],"answerId":"b","explanation":"Peripheral precocious puberty is caused by sex-steroid production independent of central GnRH, often due to adrenal or gonadal disorders.","kind":"recall","origin":"ai"},{"id":"hrp1-peripheral-precocious-puberty~ai-1","moduleId":"hrp1-peripheral-precocious-puberty","stem":"Which laboratory finding is typically suppressed in peripheral precocious puberty?","options":[{"id":"a","text":"Testosterone"},{"id":"b","text":"LH"},{"id":"c","text":"DHEAS"},{"id":"d","text":"FSH"}],"answerId":"b","explanation":"LH is generally suppressed in peripheral precocious puberty due to the presence of extragonadal androgens.","kind":"recall","origin":"ai"},{"id":"hrp1-peripheral-precocious-puberty~ai-2","moduleId":"hrp1-peripheral-precocious-puberty","stem":"A 5-year-old boy presents with unilateral testicular enlargement. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Increased LH secretion"},{"id":"b","text":"Local Leydig-cell lesion"},{"id":"c","text":"Excessive FSH production"},{"id":"d","text":"Testicular torsion"}],"answerId":"b","explanation":"Unilateral testicular enlargement in this context is likely due to a local Leydig-cell lesion producing androgen.","kind":"clinical","origin":"ai"},{"id":"hrp1-peripheral-precocious-puberty~ai-3","moduleId":"hrp1-peripheral-precocious-puberty","stem":"Which of the following is a common clinical finding in peripheral precocious puberty?","options":[{"id":"a","text":"Delayed bone age"},{"id":"b","text":"Virilization with small testes"},{"id":"c","text":"Increased FSH and LH"},{"id":"d","text":"Breast development in boys"}],"answerId":"b","explanation":"Virilization with small testes occurs because extragonadal androgen suppresses LH/FSH without stimulating seminiferous growth.","kind":"recall","origin":"ai"},{"id":"hrp1-peripheral-precocious-puberty~ai-4","moduleId":"hrp1-peripheral-precocious-puberty","stem":"What is the appropriate management for a child diagnosed with peripheral precocious puberty due to an adrenal tumor?","options":[{"id":"a","text":"Long-acting GnRH agonist"},{"id":"b","text":"Surgical removal of the tumor"},{"id":"c","text":"Observation only"},{"id":"d","text":"Estrogen therapy"}],"answerId":"b","explanation":"Treatment should focus on addressing the steroid source, such as surgical removal of the tumor causing excess steroid production.","kind":"trap","origin":"ai"},{"id":"hrp1-peripheral-precocious-puberty~ai-5","moduleId":"hrp1-peripheral-precocious-puberty","stem":"How does peripheral precocious puberty differ from central precocious puberty in terms of hormonal response?","options":[{"id":"a","text":"Peripheral has elevated LH, central has suppressed LH"},{"id":"b","text":"Peripheral has suppressed LH, central has elevated LH"},{"id":"c","text":"Both have elevated LH"},{"id":"d","text":"Both have suppressed LH"}],"answerId":"b","explanation":"In peripheral precocious puberty, LH is suppressed due to the presence of extragonadal steroids, while central precocious puberty typically has elevated LH.","kind":"integration","linkedModuleIds":["hrp1-central-precocious-puberty"],"origin":"ai"},{"id":"hrp1-peripheral-precocious-puberty~ai-6","moduleId":"hrp1-peripheral-precocious-puberty","stem":"Which adrenal pathology could lead to peripheral precocious puberty?","options":[{"id":"a","text":"Adrenal adenoma"},{"id":"b","text":"Congenital adrenal hyperplasia"},{"id":"c","text":"Adrenal insufficiency"},{"id":"d","text":"Cushing's syndrome"}],"answerId":"b","explanation":"Congenital adrenal hyperplasia can cause excess adrenal androgens, leading to peripheral precocious puberty.","kind":"integration","linkedModuleIds":["adrenal-cushing-pathology"],"origin":"ai"}],"hrp1-delayed-puberty":[{"id":"hrp1-delayed-puberty~ai-0","moduleId":"hrp1-delayed-puberty","stem":"Which of the following is a classic cause of primary gonadal failure in females?","options":[{"id":"a","text":"Klinefelter syndrome"},{"id":"b","text":"Turner syndrome"},{"id":"c","text":"Androgen insensitivity syndrome"},{"id":"d","text":"Congenital adrenal hyperplasia"}],"answerId":"b","explanation":"Turner syndrome is characterized by gonadal dysgenesis leading to primary hypogonadism.","kind":"recall","origin":"ai"},{"id":"hrp1-delayed-puberty~ai-1","moduleId":"hrp1-delayed-puberty","stem":"In constitutional delay of puberty, which of the following findings is most likely?","options":[{"id":"a","text":"Absent family history of delayed puberty"},{"id":"b","text":"Delayed bone age"},{"id":"c","text":"Elevated LH and FSH levels"},{"id":"d","text":"Normal growth potential"}],"answerId":"b","explanation":"Constitutional delay typically presents with delayed bone age and a family history of similar patterns.","kind":"clinical","origin":"ai"},{"id":"hrp1-delayed-puberty~ai-2","moduleId":"hrp1-delayed-puberty","stem":"What is the expected gonadotropin profile in primary gonadal failure?","options":[{"id":"a","text":"Low LH and FSH"},{"id":"b","text":"High LH and FSH"},{"id":"c","text":"Normal LH and low FSH"},{"id":"d","text":"Normal LH and high FSH"}],"answerId":"b","explanation":"Primary gonadal failure results in low sex steroids and high LH/FSH due to lack of feedback inhibition.","kind":"mechanism","origin":"ai"},{"id":"hrp1-delayed-puberty~ai-3","moduleId":"hrp1-delayed-puberty","stem":"A 14-year-old girl presents with absent breast development and a webbed neck. What is the most likely diagnosis?","options":[{"id":"a","text":"Klinefelter syndrome"},{"id":"b","text":"Turner syndrome"},{"id":"c","text":"Hypothalamic amenorrhea"},{"id":"d","text":"Polycystic ovary syndrome"}],"answerId":"b","explanation":"The combination of absent breast development and webbed neck is characteristic of Turner syndrome.","kind":"clinical","origin":"ai"},{"id":"hrp1-delayed-puberty~ai-4","moduleId":"hrp1-delayed-puberty","stem":"Which of the following statements about delayed puberty is true?","options":[{"id":"a","text":"All low LH/FSH results indicate permanent pituitary disease"},{"id":"b","text":"Functional suppression can lower gonadotropins"},{"id":"c","text":"Constitutional delay requires treatment"},{"id":"d","text":"Delayed puberty is always pathological"}],"answerId":"b","explanation":"Functional suppression and constitutional delay can lower gonadotropins without indicating permanent disease.","kind":"trap","origin":"ai"},{"id":"hrp1-delayed-puberty~ai-5","moduleId":"hrp1-delayed-puberty","stem":"How does delayed puberty relate to normal puberty development?","options":[{"id":"a","text":"It is always pathological"},{"id":"b","text":"It can be a variant of normal maturation"},{"id":"c","text":"It indicates a failure of the HPG axis"},{"id":"d","text":"It requires immediate intervention"}],"answerId":"b","explanation":"Delayed puberty can be a normal variant of maturation, especially in constitutional delay.","kind":"integration","linkedModuleIds":["hrp1-normal-puberty-tanner"],"origin":"ai"},{"id":"hrp1-delayed-puberty~ai-6","moduleId":"hrp1-delayed-puberty","stem":"Which condition would most likely present with low sex steroids and low LH/FSH?","options":[{"id":"a","text":"Turner syndrome"},{"id":"b","text":"Klinefelter syndrome"},{"id":"c","text":"Hypogonadotropic hypogonadism"},{"id":"d","text":"Primary ovarian insufficiency"}],"answerId":"c","explanation":"Hypogonadotropic hypogonadism is characterized by low sex steroids and low LH/FSH due to insufficient stimulation from the hypothalamus or pituitary.","kind":"integration","linkedModuleIds":["hrp1-central-precocious-puberty"],"origin":"ai"}],"hrp1-cycle-feedback-gonadotropins":[{"id":"hrp1-cycle-feedback-gonadotropins~ai-0","moduleId":"hrp1-cycle-feedback-gonadotropins","stem":"What initiates the LH surge during the menstrual cycle?","options":[{"id":"a","text":"Increased FSH levels"},{"id":"b","text":"Sustained high estradiol levels"},{"id":"c","text":"Decreased inhibin levels"},{"id":"d","text":"Follicular rupture"}],"answerId":"b","explanation":"Sustained high estradiol from the dominant follicle switches feedback to positive, triggering the LH surge.","kind":"recall","origin":"ai"},{"id":"hrp1-cycle-feedback-gonadotropins~ai-1","moduleId":"hrp1-cycle-feedback-gonadotropins","stem":"During the follicular phase, what effect does estradiol have on FSH levels?","options":[{"id":"a","text":"Increases FSH levels"},{"id":"b","text":"Decreases FSH levels"},{"id":"c","text":"Has no effect on FSH levels"},{"id":"d","text":"Increases LH levels instead"}],"answerId":"b","explanation":"Estradiol and inhibin suppress FSH levels, allowing only the dominant follicle to grow.","kind":"mechanism","origin":"ai"},{"id":"hrp1-cycle-feedback-gonadotropins~ai-2","moduleId":"hrp1-cycle-feedback-gonadotropins","stem":"Which hormone is primarily responsible for completing oocyte meiosis I?","options":[{"id":"a","text":"FSH"},{"id":"b","text":"LH"},{"id":"c","text":"Estradiol"},{"id":"d","text":"Progesterone"}],"answerId":"b","explanation":"The LH surge is crucial for completing oocyte meiosis I and initiating ovulation.","kind":"recall","origin":"ai"},{"id":"hrp1-cycle-feedback-gonadotropins~ai-3","moduleId":"hrp1-cycle-feedback-gonadotropins","stem":"What is the primary feedback mechanism of estradiol during most of the menstrual cycle?","options":[{"id":"a","text":"Positive feedback"},{"id":"b","text":"Negative feedback"},{"id":"c","text":"No feedback"},{"id":"d","text":"Inhibitory feedback"}],"answerId":"b","explanation":"Estradiol provides negative feedback on gonadotropins until the dominant follicle's high levels switch to positive feedback.","kind":"recall","origin":"ai"},{"id":"hrp1-cycle-feedback-gonadotropins~ai-4","moduleId":"hrp1-cycle-feedback-gonadotropins","stem":"Which of the following findings is indicative of the LH surge?","options":[{"id":"a","text":"Increased FSH levels"},{"id":"b","text":"Urinary LH rise"},{"id":"c","text":"Decreased estradiol levels"},{"id":"d","text":"Increased inhibin levels"}],"answerId":"b","explanation":"A rise in urinary LH levels is a direct indicator of the LH surge before ovulation.","kind":"recall","origin":"ai"},{"id":"hrp1-cycle-feedback-gonadotropins~ai-5","moduleId":"hrp1-cycle-feedback-gonadotropins","stem":"What occurs to FSH levels as the dominant follicle grows?","options":[{"id":"a","text":"FSH levels increase"},{"id":"b","text":"FSH levels decrease"},{"id":"c","text":"FSH levels remain constant"},{"id":"d","text":"FSH levels fluctuate unpredictably"}],"answerId":"b","explanation":"As the dominant follicle grows, estradiol and inhibin suppress FSH levels, leading to a decrease.","kind":"clinical","origin":"ai"},{"id":"hrp1-cycle-feedback-gonadotropins~ai-6","moduleId":"hrp1-cycle-feedback-gonadotropins","stem":"How does the mechanism of feedback in the ovarian cycle relate to homeostasis?","options":[{"id":"a","text":"It regulates blood glucose levels"},{"id":"b","text":"It maintains fluid balance"},{"id":"c","text":"It ensures hormonal balance for ovulation"},{"id":"d","text":"It controls heart rate"}],"answerId":"c","explanation":"The feedback mechanisms in the ovarian cycle are crucial for maintaining hormonal balance necessary for ovulation, reflecting principles of homeostasis.","kind":"integration","linkedModuleIds":["homeostasis-feedback-control"],"origin":"ai"},{"id":"hrp1-cycle-feedback-gonadotropins~ai-7","moduleId":"hrp1-cycle-feedback-gonadotropins","stem":"Which feedback mechanism is involved in the transition from the follicular phase to ovulation?","options":[{"id":"a","text":"Negative feedback from progesterone"},{"id":"b","text":"Positive feedback from estradiol"},{"id":"c","text":"Inhibitory feedback from FSH"},{"id":"d","text":"Constant feedback from inhibin"}],"answerId":"b","explanation":"The transition to ovulation is marked by positive feedback from sustained high levels of estradiol, leading to the LH surge.","kind":"integration","linkedModuleIds":["hen1-endocrine-feedback-loops"],"origin":"ai"}],"hrp1-normal-puberty-tanner":[{"id":"hrp1-normal-puberty-tanner~ai-0","moduleId":"hrp1-normal-puberty-tanner","stem":"What is the first physical sign of puberty in boys?","options":[{"id":"a","text":"Pubic hair development"},{"id":"b","text":"Testicular enlargement"},{"id":"c","text":"Penile growth"},{"id":"d","text":"Axillary hair development"}],"answerId":"b","explanation":"Testicular enlargement is the first sign of puberty in boys, marking the onset of gonadarche.","kind":"recall","origin":"ai"},{"id":"hrp1-normal-puberty-tanner~ai-1","moduleId":"hrp1-normal-puberty-tanner","stem":"Which hormone initiates the reactivation of the HPG axis during puberty?","options":[{"id":"a","text":"Estrogen"},{"id":"b","text":"Testosterone"},{"id":"c","text":"Gonadotropin-releasing hormone (GnRH)"},{"id":"d","text":"Luteinizing hormone (LH)"}],"answerId":"c","explanation":"Gonadotropin-releasing hormone (GnRH) is responsible for the reactivation of the HPG axis during puberty.","kind":"mechanism","origin":"ai"},{"id":"hrp1-normal-puberty-tanner~ai-2","moduleId":"hrp1-normal-puberty-tanner","stem":"A 10-year-old girl presents with pubic hair development but no breast enlargement. What does this indicate?","options":[{"id":"a","text":"Central puberty has started"},{"id":"b","text":"Adrenarche has occurred"},{"id":"c","text":"Delayed puberty"},{"id":"d","text":"Precocious puberty"}],"answerId":"b","explanation":"Pubic hair development without breast enlargement suggests adrenarche, which can occur independently of central puberty.","kind":"clinical","origin":"ai"},{"id":"hrp1-normal-puberty-tanner~ai-3","moduleId":"hrp1-normal-puberty-tanner","stem":"Which of the following findings is consistent with central gonadal activation?","options":[{"id":"a","text":"Bilateral testicular enlargement"},{"id":"b","text":"Isolated pubic hair growth"},{"id":"c","text":"Breast development without testicular enlargement"},{"id":"d","text":"No change in growth velocity"}],"answerId":"a","explanation":"Bilateral testicular enlargement indicates central gonadal activation due to increased gonadotropin levels.","kind":"recall","origin":"ai"},{"id":"hrp1-normal-puberty-tanner~ai-4","moduleId":"hrp1-normal-puberty-tanner","stem":"What is the primary mechanism by which puberty leads to growth acceleration?","options":[{"id":"a","text":"Increased adrenal androgens"},{"id":"b","text":"Central pulsatile GnRH release"},{"id":"c","text":"Increased estrogen levels"},{"id":"d","text":"Increased insulin sensitivity"}],"answerId":"b","explanation":"Central pulsatile GnRH release stimulates the gonads, leading to growth acceleration during puberty.","kind":"mechanism","origin":"ai"},{"id":"hrp1-normal-puberty-tanner~ai-5","moduleId":"hrp1-normal-puberty-tanner","stem":"A 9-year-old girl shows signs of adrenarche but has not developed breasts. What is the most likely explanation?","options":[{"id":"a","text":"Normal puberty onset"},{"id":"b","text":"Central precocious puberty"},{"id":"c","text":"Isolated adrenarche"},{"id":"d","text":"Delayed puberty"}],"answerId":"c","explanation":"Isolated adrenarche can occur without the activation of the HPG axis, hence no breast development.","kind":"trap","origin":"ai"},{"id":"hrp1-normal-puberty-tanner~ai-6","moduleId":"hrp1-normal-puberty-tanner","stem":"How does the onset of puberty relate to the development of DNA viruses, such as herpesviruses?","options":[{"id":"a","text":"Increased immune response"},{"id":"b","text":"Hormonal changes affecting viral latency"},{"id":"c","text":"Higher incidence of viral infections"},{"id":"d","text":"Decreased risk of viral transmission"}],"answerId":"b","explanation":"Hormonal changes during puberty can affect the immune response and the latency of certain viruses, including herpesviruses.","kind":"integration","linkedModuleIds":["dna-viruses-herpesviruses"],"origin":"ai"},{"id":"hrp1-normal-puberty-tanner~ai-7","moduleId":"hrp1-normal-puberty-tanner","stem":"What common feature of delayed puberty may also influence the onset of central precocious puberty?","options":[{"id":"a","text":"Genetic factors"},{"id":"b","text":"Nutrition status"},{"id":"c","text":"Chronic diseases"},{"id":"d","text":"Growth velocity"}],"answerId":"a","explanation":"Genetic factors can influence both delayed and precocious puberty, affecting the timing of HPG axis activation.","kind":"integration","linkedModuleIds":["hrp1-delayed-puberty"],"origin":"ai"}],"hrp1-pudendal-erectile-external-genitalia":[{"id":"hrp1-pudendal-erectile-external-genitalia~ai-0","moduleId":"hrp1-pudendal-erectile-external-genitalia","stem":"Which nerve is primarily responsible for sensation in the external genitalia?","options":[{"id":"a","text":"Inferior rectal nerve"},{"id":"b","text":"Dorsal nerve of the penis/clitoris"},{"id":"c","text":"Perineal nerve"},{"id":"d","text":"Pelvic splanchnic nerve"}],"answerId":"b","explanation":"The dorsal nerve of the penis/clitoris is a terminal branch of the pudendal nerve that provides sensory innervation to the external genitalia.","kind":"recall","origin":"ai"},{"id":"hrp1-pudendal-erectile-external-genitalia~ai-1","moduleId":"hrp1-pudendal-erectile-external-genitalia","stem":"What is the primary mechanism by which parasympathetic cavernous nerves induce erection?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Vasodilation via nitric oxide"},{"id":"c","text":"Contraction of pelvic floor muscles"},{"id":"d","text":"Inhibition of sympathetic activity"}],"answerId":"b","explanation":"Parasympathetic cavernous nerves release nitric oxide, leading to vasodilation and filling of the erectile tissues.","kind":"mechanism","origin":"ai"},{"id":"hrp1-pudendal-erectile-external-genitalia~ai-2","moduleId":"hrp1-pudendal-erectile-external-genitalia","stem":"A patient presents with loss of genital sensation after a pelvic injury. Which nerve is most likely affected?","options":[{"id":"a","text":"Inferior rectal nerve"},{"id":"b","text":"Dorsal nerve of the penis/clitoris"},{"id":"c","text":"Pelvic splanchnic nerve"},{"id":"d","text":"Ilioinguinal nerve"}],"answerId":"b","explanation":"The dorsal nerve of the penis/clitoris, a terminal branch of the pudendal nerve, is responsible for genital sensation.","kind":"clinical","origin":"ai"},{"id":"hrp1-pudendal-erectile-external-genitalia~ai-3","moduleId":"hrp1-pudendal-erectile-external-genitalia","stem":"Which of the following statements about erection is true?","options":[{"id":"a","text":"Pudendal somatic fibers alone initiate cavernosal vasodilation"},{"id":"b","text":"Parasympathetic cavernous nerves initiate NO-mediated erection"},{"id":"c","text":"Sympathetic nerves are solely responsible for erection"},{"id":"d","text":"Erection occurs only during REM sleep"}],"answerId":"b","explanation":"Parasympathetic cavernous nerves are responsible for initiating erection through NO-mediated vasodilation.","kind":"trap","origin":"ai"},{"id":"hrp1-pudendal-erectile-external-genitalia~ai-4","moduleId":"hrp1-pudendal-erectile-external-genitalia","stem":"During a pelvic autonomic injury, which function is most likely impaired?","options":[{"id":"a","text":"Sensation in the perineum"},{"id":"b","text":"Erection"},{"id":"c","text":"Urination"},{"id":"d","text":"Defecation"}],"answerId":"b","explanation":"Pelvic autonomic injury disrupts the parasympathetic pathways responsible for initiating erection.","kind":"clinical","origin":"ai"},{"id":"hrp1-pudendal-erectile-external-genitalia~ai-5","moduleId":"hrp1-pudendal-erectile-external-genitalia","stem":"How do the pudendal nerve and pelvic diaphragm interact in the context of erectile function?","options":[{"id":"a","text":"Pudendal nerve provides sensation, pelvic diaphragm supports erectile tissues"},{"id":"b","text":"Pelvic diaphragm initiates erection, pudendal nerve provides sensation"},{"id":"c","text":"Both nerves are involved in vasodilation"},{"id":"d","text":"Pudendal nerve controls ejaculation, pelvic diaphragm controls erection"}],"answerId":"a","explanation":"The pudendal nerve supplies sensation while the pelvic diaphragm supports the erectile tissues during erection.","kind":"integration","linkedModuleIds":["hrp1-pelvic-diaphragm"],"origin":"ai"},{"id":"hrp1-pudendal-erectile-external-genitalia~ai-6","moduleId":"hrp1-pudendal-erectile-external-genitalia","stem":"What is the relationship between the pudendal nerve and the perineal triangles in erectile function?","options":[{"id":"a","text":"Pudendal nerve provides motor control to perineal muscles"},{"id":"b","text":"Perineal triangles enhance pudendal nerve function"},{"id":"c","text":"Pudendal nerve is irrelevant to perineal triangles"},{"id":"d","text":"Perineal triangles inhibit pudendal nerve activity"}],"answerId":"a","explanation":"The pudendal nerve provides motor control to the perineal muscles, which play a role in erectile function.","kind":"integration","linkedModuleIds":["hrp1-perineal-spaces-triangles"],"origin":"ai"}],"hrp1-estrogen-progesterone-actions":[{"id":"hrp1-estrogen-progesterone-actions~ai-0","moduleId":"hrp1-estrogen-progesterone-actions","stem":"What is the primary action of estradiol in the reproductive tract?","options":[{"id":"a","text":"Promotes endometrial secretory phase"},{"id":"b","text":"Stimulates cervical mucus thickening"},{"id":"c","text":"Facilitates reproductive tract growth"},{"id":"d","text":"Inhibits LH secretion"}],"answerId":"c","explanation":"Estradiol is known to promote the growth of the reproductive tract, including the endometrium and breast tissue.","kind":"recall","origin":"ai"},{"id":"hrp1-estrogen-progesterone-actions~ai-1","moduleId":"hrp1-estrogen-progesterone-actions","stem":"Which hormone is responsible for the postovulatory rise in basal body temperature?","options":[{"id":"a","text":"Estrogen"},{"id":"b","text":"Luteinizing hormone"},{"id":"c","text":"Progesterone"},{"id":"d","text":"Follicle-stimulating hormone"}],"answerId":"c","explanation":"Progesterone acts thermogenically, leading to an increase in basal body temperature after ovulation.","kind":"recall","origin":"ai"},{"id":"hrp1-estrogen-progesterone-actions~ai-2","moduleId":"hrp1-estrogen-progesterone-actions","stem":"What effect does sustained high levels of estradiol have on LH secretion?","options":[{"id":"a","text":"Inhibits LH secretion"},{"id":"b","text":"Stimulates FSH secretion"},{"id":"c","text":"Causes a surge in LH secretion"},{"id":"d","text":"Has no effect on LH secretion"}],"answerId":"c","explanation":"Sustained high preovulatory estradiol creates positive feedback, resulting in an LH surge.","kind":"mechanism","origin":"ai"},{"id":"hrp1-estrogen-progesterone-actions~ai-3","moduleId":"hrp1-estrogen-progesterone-actions","stem":"What is the consequence of chronic unopposed estrogen in a woman with an intact uterus?","options":[{"id":"a","text":"Increased bone density"},{"id":"b","text":"Reduced risk of endometrial cancer"},{"id":"c","text":"Endometrial hyperplasia"},{"id":"d","text":"Improved menstrual regularity"}],"answerId":"c","explanation":"Chronic unopposed estrogen increases the risk of endometrial hyperplasia and cancer due to lack of progesterone's protective effects.","kind":"trap","origin":"ai"},{"id":"hrp1-estrogen-progesterone-actions~ai-4","moduleId":"hrp1-estrogen-progesterone-actions","stem":"Which finding is expected in a patient during ovulation due to estrogen's effects?","options":[{"id":"a","text":"Thick cervical mucus"},{"id":"b","text":"Thin watery cervical mucus"},{"id":"c","text":"Increased basal body temperature"},{"id":"d","text":"Decreased libido"}],"answerId":"b","explanation":"Estrogen facilitates the production of thin, watery cervical mucus to aid sperm passage during ovulation.","kind":"recall","origin":"ai"},{"id":"hrp1-estrogen-progesterone-actions~ai-5","moduleId":"hrp1-estrogen-progesterone-actions","stem":"How does progesterone contribute to mammary gland development?","options":[{"id":"a","text":"Stimulates ductal growth"},{"id":"b","text":"Promotes lobuloalveolar development"},{"id":"c","text":"Inhibits estrogen action"},{"id":"d","text":"Enhances milk production"}],"answerId":"b","explanation":"Progesterone promotes lobuloalveolar development in the mammary glands, preparing them for potential lactation.","kind":"mechanism","origin":"ai"},{"id":"hrp1-estrogen-progesterone-actions~ai-6","moduleId":"hrp1-estrogen-progesterone-actions","stem":"How do estrogen and progesterone interact with the male HPG axis?","options":[{"id":"a","text":"Estrogen inhibits testosterone production"},{"id":"b","text":"Progesterone enhances spermatogenesis"},{"id":"c","text":"Estrogen regulates Leydig cell function"},{"id":"d","text":"Progesterone has no role in male physiology"}],"answerId":"a","explanation":"Estrogen can inhibit testosterone production in males by affecting the feedback mechanisms in the HPG axis.","kind":"integration","linkedModuleIds":["hrp1-male-hpg-axis"],"origin":"ai"},{"id":"hrp1-estrogen-progesterone-actions~ai-7","moduleId":"hrp1-estrogen-progesterone-actions","stem":"Which hormone's action is crucial for the synthesis of sex steroids in both males and females?","options":[{"id":"a","text":"LH"},{"id":"b","text":"FSH"},{"id":"c","text":"Progesterone"},{"id":"d","text":"Estradiol"}],"answerId":"a","explanation":"LH is essential for the synthesis of sex steroids in both males and females, stimulating steroidogenesis in gonadal tissues.","kind":"integration","linkedModuleIds":["hrp1-sex-steroid-synthesis-action"],"origin":"ai"}],"hrp1-ovarian-cycle-ovulation":[{"id":"hrp1-ovarian-cycle-ovulation~ai-0","moduleId":"hrp1-ovarian-cycle-ovulation","stem":"What hormone surge triggers ovulation during the menstrual cycle?","options":[{"id":"a","text":"Follicle-stimulating hormone (FSH)"},{"id":"b","text":"Luteinizing hormone (LH)"},{"id":"c","text":"Estrogen"},{"id":"d","text":"Progesterone"}],"answerId":"b","explanation":"The LH surge is crucial for triggering ovulation by promoting oocyte maturation and follicular rupture.","kind":"recall","origin":"ai"},{"id":"hrp1-ovarian-cycle-ovulation~ai-1","moduleId":"hrp1-ovarian-cycle-ovulation","stem":"Which phase of the ovarian cycle is primarily characterized by high levels of progesterone?","options":[{"id":"a","text":"Follicular phase"},{"id":"b","text":"Ovulatory phase"},{"id":"c","text":"Luteal phase"},{"id":"d","text":"Menstrual phase"}],"answerId":"c","explanation":"The luteal phase is dominated by progesterone secretion from the corpus luteum.","kind":"recall","origin":"ai"},{"id":"hrp1-ovarian-cycle-ovulation~ai-2","moduleId":"hrp1-ovarian-cycle-ovulation","stem":"What is the primary function of inhibin A secreted by the corpus luteum?","options":[{"id":"a","text":"Stimulate FSH release"},{"id":"b","text":"Inhibit FSH release"},{"id":"c","text":"Promote ovulation"},{"id":"d","text":"Enhance estrogen production"}],"answerId":"b","explanation":"Inhibin A primarily serves to inhibit FSH release from the anterior pituitary.","kind":"mechanism","origin":"ai"},{"id":"hrp1-ovarian-cycle-ovulation~ai-3","moduleId":"hrp1-ovarian-cycle-ovulation","stem":"During which phase is the follicular phase most variable in length?","options":[{"id":"a","text":"Luteal phase"},{"id":"b","text":"Ovulatory phase"},{"id":"c","text":"Menstrual phase"},{"id":"d","text":"Follicular phase"}],"answerId":"d","explanation":"The follicular phase length varies significantly among individuals, while the luteal phase is more consistent.","kind":"trap","origin":"ai"},{"id":"hrp1-ovarian-cycle-ovulation~ai-4","moduleId":"hrp1-ovarian-cycle-ovulation","stem":"What clinical finding is associated with ovulation and can present as unilateral pain?","options":[{"id":"a","text":"Dysmenorrhea"},{"id":"b","text":"Mittelschmerz"},{"id":"c","text":"Amenorrhea"},{"id":"d","text":"Menorrhagia"}],"answerId":"b","explanation":"Mittelschmerz refers to the midcycle pain that occurs due to follicular rupture during ovulation.","kind":"clinical","origin":"ai"},{"id":"hrp1-ovarian-cycle-ovulation~ai-5","moduleId":"hrp1-ovarian-cycle-ovulation","stem":"How does the corpus luteum affect basal body temperature post-ovulation?","options":[{"id":"a","text":"Decreases temperature"},{"id":"b","text":"No effect"},{"id":"c","text":"Increases temperature"},{"id":"d","text":"Fluctuates temperature"}],"answerId":"c","explanation":"The progesterone secreted by the corpus luteum has a thermogenic effect, leading to an increase in basal body temperature.","kind":"clinical","origin":"ai"},{"id":"hrp1-ovarian-cycle-ovulation~ai-6","moduleId":"hrp1-ovarian-cycle-ovulation","stem":"How does the feedback mechanism of estrogen and progesterone influence gonadotropin release in the luteal phase?","options":[{"id":"a","text":"Increases FSH and LH release"},{"id":"b","text":"Inhibits FSH and LH release"},{"id":"c","text":"Has no effect on gonadotropins"},{"id":"d","text":"Stimulates only LH release"}],"answerId":"b","explanation":"High levels of estrogen and progesterone during the luteal phase inhibit the release of FSH and LH through negative feedback.","kind":"integration","linkedModuleIds":["hrp1-cycle-feedback-gonadotropins"],"origin":"ai"},{"id":"hrp1-ovarian-cycle-ovulation~ai-7","moduleId":"hrp1-ovarian-cycle-ovulation","stem":"What role do the two-cell model and gonadotropins play in the ovarian cycle?","options":[{"id":"a","text":"Only FSH is involved in estrogen production"},{"id":"b","text":"LH stimulates theca cells to produce androgens"},{"id":"c","text":"FSH is responsible for ovulation"},{"id":"d","text":"Estrogen has no role in the follicular phase"}],"answerId":"b","explanation":"In the two-cell model, LH stimulates theca cells to produce androgens, which are then converted to estrogen by granulosa cells under FSH influence.","kind":"integration","linkedModuleIds":["hrp1-ovarian-steroid-two-cell-model"],"origin":"ai"}],"hrp1-sex-steroid-synthesis-action":[{"id":"hrp1-sex-steroid-synthesis-action~ai-0","moduleId":"hrp1-sex-steroid-synthesis-action","stem":"What is the primary precursor for sex steroid synthesis?","options":[{"id":"a","text":"Cholesterol"},{"id":"b","text":"Phospholipids"},{"id":"c","text":"Triglycerides"},{"id":"d","text":"Fatty acids"}],"answerId":"a","explanation":"Sex steroids are synthesized from cholesterol, which serves as the main precursor.","kind":"recall","origin":"ai"},{"id":"hrp1-sex-steroid-synthesis-action~ai-1","moduleId":"hrp1-sex-steroid-synthesis-action","stem":"Which enzyme converts testosterone to dihydrotestosterone (DHT)?","options":[{"id":"a","text":"Aromatase"},{"id":"b","text":"5α-reductase"},{"id":"c","text":"17β-hydroxysteroid dehydrogenase"},{"id":"d","text":"3β-hydroxysteroid dehydrogenase"}],"answerId":"b","explanation":"5α-reductase is responsible for the conversion of testosterone to dihydrotestosterone (DHT).","kind":"mechanism","origin":"ai"},{"id":"hrp1-sex-steroid-synthesis-action~ai-2","moduleId":"hrp1-sex-steroid-synthesis-action","stem":"A patient has normal total testosterone levels but presents with symptoms of androgen deficiency. What is a likely explanation?","options":[{"id":"a","text":"Increased SHBG levels"},{"id":"b","text":"Decreased aromatase activity"},{"id":"c","text":"Increased 5α-reductase activity"},{"id":"d","text":"Decreased cholesterol availability"}],"answerId":"a","explanation":"Increased SHBG can bind more testosterone, reducing the free fraction and leading to symptoms of deficiency despite normal total levels.","kind":"clinical","origin":"ai"},{"id":"hrp1-sex-steroid-synthesis-action~ai-3","moduleId":"hrp1-sex-steroid-synthesis-action","stem":"Which statement about sex steroid storage is correct?","options":[{"id":"a","text":"They are stored in secretory vesicles."},{"id":"b","text":"They are synthesized on demand."},{"id":"c","text":"They are stored in lipid droplets."},{"id":"d","text":"They are retained in the endoplasmic reticulum."}],"answerId":"b","explanation":"Sex steroids are synthesized on demand and diffuse out of the cells, rather than being stored in vesicles.","kind":"trap","origin":"ai"},{"id":"hrp1-sex-steroid-synthesis-action~ai-4","moduleId":"hrp1-sex-steroid-synthesis-action","stem":"What is the main action of estrogen on target tissues?","options":[{"id":"a","text":"Inhibition of apoptosis"},{"id":"b","text":"Stimulation of lipolysis"},{"id":"c","text":"Promotion of protein synthesis"},{"id":"d","text":"Inhibition of cell proliferation"}],"answerId":"a","explanation":"Estrogen primarily acts to inhibit apoptosis and promote cell survival in target tissues.","kind":"mechanism","origin":"ai"},{"id":"hrp1-sex-steroid-synthesis-action~ai-5","moduleId":"hrp1-sex-steroid-synthesis-action","stem":"How does local expression of aromatase affect testosterone action in tissues?","options":[{"id":"a","text":"Increases testosterone levels"},{"id":"b","text":"Converts testosterone to estradiol"},{"id":"c","text":"Decreases SHBG levels"},{"id":"d","text":"Inhibits androgen receptor activity"}],"answerId":"b","explanation":"Local expression of aromatase converts testosterone to estradiol, affecting its action in tissues.","kind":"mechanism","origin":"ai"},{"id":"hrp1-sex-steroid-synthesis-action~ai-6","moduleId":"hrp1-sex-steroid-synthesis-action","stem":"How are sex steroid actions integrated with cholesterol metabolism?","options":[{"id":"a","text":"Cholesterol is converted to amino acids"},{"id":"b","text":"Sex steroids are derived from cholesterol"},{"id":"c","text":"Cholesterol enhances steroid receptor activity"},{"id":"d","text":"Cholesterol is stored in the adrenal glands"}],"answerId":"b","explanation":"Sex steroids are synthesized from cholesterol, linking their actions directly to cholesterol metabolism.","kind":"integration","linkedModuleIds":["cholesterol-steroids-lipoproteins"],"origin":"ai"},{"id":"hrp1-sex-steroid-synthesis-action~ai-7","moduleId":"hrp1-sex-steroid-synthesis-action","stem":"What is the relationship between testosterone and estradiol in male physiology?","options":[{"id":"a","text":"Testosterone is converted to estradiol by aromatase"},{"id":"b","text":"Estradiol inhibits testosterone production"},{"id":"c","text":"Testosterone and estradiol have no interaction"},{"id":"d","text":"Estradiol is a precursor to testosterone"}],"answerId":"a","explanation":"In males, testosterone can be converted to estradiol by the enzyme aromatase, linking their physiological roles.","kind":"integration","linkedModuleIds":["hrp1-estrogen-progesterone-actions"],"origin":"ai"}],"hrp1-male-hpg-axis":[{"id":"hrp1-male-hpg-axis~ai-0","moduleId":"hrp1-male-hpg-axis","stem":"What is the effect of continuous GnRH administration on gonadotropin secretion?","options":[{"id":"a","text":"Stimulates LH and FSH secretion"},{"id":"b","text":"Inhibits LH and FSH secretion"},{"id":"c","text":"Has no effect on LH and FSH"},{"id":"d","text":"Increases testosterone production"}],"answerId":"b","explanation":"Continuous GnRH exposure downregulates the pituitary GnRH receptors, leading to decreased LH and FSH secretion.","kind":"trap","origin":"ai"},{"id":"hrp1-male-hpg-axis~ai-1","moduleId":"hrp1-male-hpg-axis","stem":"Which hormone primarily stimulates Leydig cells to produce testosterone?","options":[{"id":"a","text":"FSH"},{"id":"b","text":"LH"},{"id":"c","text":"Inhibin B"},{"id":"d","text":"GnRH"}],"answerId":"b","explanation":"LH directly stimulates Leydig cells to synthesize testosterone.","kind":"recall","origin":"ai"},{"id":"hrp1-male-hpg-axis~ai-2","moduleId":"hrp1-male-hpg-axis","stem":"A patient presents with small firm testes and elevated LH and FSH levels. What is the most likely diagnosis?","options":[{"id":"a","text":"Primary testicular failure"},{"id":"b","text":"Central gonadotropin deficiency"},{"id":"c","text":"Hypogonadotropic hypogonadism"},{"id":"d","text":"Hypergonadotropic hypogonadism"}],"answerId":"a","explanation":"The clinical finding of small firm testes with high LH/FSH indicates primary testicular failure.","kind":"clinical","origin":"ai"},{"id":"hrp1-male-hpg-axis~ai-3","moduleId":"hrp1-male-hpg-axis","stem":"What role does Sertoli cell inhibin B play in the male reproductive axis?","options":[{"id":"a","text":"Stimulates LH secretion"},{"id":"b","text":"Inhibits FSH secretion"},{"id":"c","text":"Stimulates testosterone production"},{"id":"d","text":"Inhibits GnRH secretion"}],"answerId":"b","explanation":"Inhibin B selectively suppresses FSH secretion from the pituitary gland.","kind":"mechanism","origin":"ai"},{"id":"hrp1-male-hpg-axis~ai-4","moduleId":"hrp1-male-hpg-axis","stem":"In a patient with central gonadotropin deficiency, what would you expect testosterone and gonadotropin levels to be?","options":[{"id":"a","text":"High testosterone, high LH/FSH"},{"id":"b","text":"Low testosterone, low LH/FSH"},{"id":"c","text":"Low testosterone, high LH/FSH"},{"id":"d","text":"Normal testosterone, normal LH/FSH"}],"answerId":"b","explanation":"Central gonadotropin deficiency results in low testosterone and low/inappropriately normal gonadotropins.","kind":"recall","origin":"ai"},{"id":"hrp1-male-hpg-axis~ai-5","moduleId":"hrp1-male-hpg-axis","stem":"How does pulsatile GnRH administration affect the male reproductive system?","options":[{"id":"a","text":"Inhibits testosterone production"},{"id":"b","text":"Stimulates gonadotropin secretion"},{"id":"c","text":"Suppresses spermatogenesis"},{"id":"d","text":"Increases inhibin B levels"}],"answerId":"b","explanation":"Pulsatile GnRH stimulates the secretion of LH and FSH, promoting testosterone production and spermatogenesis.","kind":"mechanism","origin":"ai"},{"id":"hrp1-male-hpg-axis~ai-6","moduleId":"hrp1-male-hpg-axis","stem":"How does testosterone feedback affect the hypothalamus and pituitary gland?","options":[{"id":"a","text":"Increases GnRH secretion"},{"id":"b","text":"Decreases LH and FSH secretion"},{"id":"c","text":"Increases FSH secretion"},{"id":"d","text":"Has no effect on gonadotropins"}],"answerId":"b","explanation":"Testosterone and estradiol provide negative feedback to the hypothalamus and pituitary, decreasing LH and FSH secretion.","kind":"integration","linkedModuleIds":["hrp1-sex-steroid-synthesis-action"],"origin":"ai"},{"id":"hrp1-male-hpg-axis~ai-7","moduleId":"hrp1-male-hpg-axis","stem":"Which drug class can be used to stimulate gonadotropin release in cases of hypogonadotropic hypogonadism?","options":[{"id":"a","text":"GnRH agonists"},{"id":"b","text":"GnRH antagonists"},{"id":"c","text":"Testosterone replacement"},{"id":"d","text":"FSH analogs"}],"answerId":"a","explanation":"GnRH agonists can stimulate the release of gonadotropins from the pituitary gland in cases of hypogonadotropic hypogonadism.","kind":"integration","linkedModuleIds":["gnrh-gonadotropin-drugs"],"origin":"ai"}],"hrp1-testosterone-dht-estrogen-actions":[{"id":"hrp1-testosterone-dht-estrogen-actions~ai-0","moduleId":"hrp1-testosterone-dht-estrogen-actions","stem":"What is the primary physiological role of testosterone in males?","options":[{"id":"a","text":"Stimulating ovulation"},{"id":"b","text":"Supporting Wolffian derivatives"},{"id":"c","text":"Promoting lactation"},{"id":"d","text":"Regulating menstrual cycles"}],"answerId":"b","explanation":"Testosterone primarily supports the development of Wolffian derivatives, muscle, bone, libido, erythropoiesis, and spermatogenesis in males.","kind":"recall","origin":"ai"},{"id":"hrp1-testosterone-dht-estrogen-actions~ai-1","moduleId":"hrp1-testosterone-dht-estrogen-actions","stem":"Which enzyme is responsible for converting testosterone to dihydrotestosterone (DHT)?","options":[{"id":"a","text":"Aromatase"},{"id":"b","text":"5α-reductase"},{"id":"c","text":"17β-hydroxysteroid dehydrogenase"},{"id":"d","text":"CYP19"}],"answerId":"b","explanation":"5α-reductase is the enzyme that converts testosterone to dihydrotestosterone (DHT), which is crucial for male external genital development.","kind":"mechanism","origin":"ai"},{"id":"hrp1-testosterone-dht-estrogen-actions~ai-2","moduleId":"hrp1-testosterone-dht-estrogen-actions","stem":"A male patient presents with undervirilized external genitalia but has normal internal male ducts. What is the most likely deficiency?","options":[{"id":"a","text":"Testosterone"},{"id":"b","text":"Aromatase"},{"id":"c","text":"5α-reductase"},{"id":"d","text":"Luteinizing hormone"}],"answerId":"c","explanation":"5α-reductase deficiency leads to reduced DHT levels, resulting in undervirilized external genitalia while preserving testosterone-mediated Wolffian development.","kind":"clinical","origin":"ai"},{"id":"hrp1-testosterone-dht-estrogen-actions~ai-3","moduleId":"hrp1-testosterone-dht-estrogen-actions","stem":"Which statement about estradiol in males is true?","options":[{"id":"a","text":"It has no significant role"},{"id":"b","text":"It promotes spermatogenesis"},{"id":"c","text":"It is essential for bone maturation"},{"id":"d","text":"It inhibits testosterone production"}],"answerId":"c","explanation":"Estradiol is crucial for male bone maturation and epiphyseal closure, highlighting its importance in male physiology.","kind":"trap","origin":"ai"},{"id":"hrp1-testosterone-dht-estrogen-actions~ai-4","moduleId":"hrp1-testosterone-dht-estrogen-actions","stem":"What is the primary mechanism by which testosterone exerts its effects on target tissues?","options":[{"id":"a","text":"Directly activating ion channels"},{"id":"b","text":"Binding to cell surface receptors"},{"id":"c","text":"Being converted to organ-selective ligands"},{"id":"d","text":"Inhibiting protein synthesis"}],"answerId":"c","explanation":"Testosterone is either distributed or locally converted to organ-selective ligands that mediate its effects on target tissues.","kind":"mechanism","origin":"ai"},{"id":"hrp1-testosterone-dht-estrogen-actions~ai-5","moduleId":"hrp1-testosterone-dht-estrogen-actions","stem":"How does estradiol affect male bone density?","options":[{"id":"a","text":"Increases bone resorption"},{"id":"b","text":"Promotes bone formation"},{"id":"c","text":"Has no effect"},{"id":"d","text":"Inhibits calcium absorption"}],"answerId":"b","explanation":"Estradiol plays a significant role in promoting bone formation and maintaining bone density in males.","kind":"clinical","origin":"ai"},{"id":"hrp1-testosterone-dht-estrogen-actions~ai-6","moduleId":"hrp1-testosterone-dht-estrogen-actions","stem":"How does testosterone influence the male HPG axis?","options":[{"id":"a","text":"Inhibits GnRH release"},{"id":"b","text":"Stimulates FSH production"},{"id":"c","text":"Enhances LH sensitivity"},{"id":"d","text":"Promotes estradiol synthesis"}],"answerId":"a","explanation":"Testosterone exerts negative feedback on the hypothalamus to inhibit GnRH release, thereby regulating the male HPG axis.","kind":"integration","linkedModuleIds":["hrp1-male-hpg-axis"],"origin":"ai"},{"id":"hrp1-testosterone-dht-estrogen-actions~ai-7","moduleId":"hrp1-testosterone-dht-estrogen-actions","stem":"What effect does dihydrotestosterone (DHT) have on male external genitalia development?","options":[{"id":"a","text":"Promotes spermatogenesis"},{"id":"b","text":"Stimulates Wolffian duct development"},{"id":"c","text":"Is essential for external genitalia formation"},{"id":"d","text":"Inhibits prostate growth"}],"answerId":"c","explanation":"DHT is essential for the proper development of male external genitalia, differentiating it from testosterone's role in internal structures.","kind":"integration","linkedModuleIds":["hrp1-estrogen-progesterone-actions"],"origin":"ai"}],"hrp1-central-precocious-puberty":[{"id":"hrp1-central-precocious-puberty~ai-0","moduleId":"hrp1-central-precocious-puberty","stem":"What is the primary mechanism driving central precocious puberty?","options":[{"id":"a","text":"Increased estrogen production"},{"id":"b","text":"Early GnRH pulsatility"},{"id":"c","text":"Increased LH sensitivity"},{"id":"d","text":"Excessive testosterone secretion"}],"answerId":"b","explanation":"Central precocious puberty is characterized by early activation of the hypothalamic-pituitary-gonadal (HPG) axis due to increased pulsatility of GnRH.","kind":"mechanism","origin":"ai"},{"id":"hrp1-central-precocious-puberty~ai-1","moduleId":"hrp1-central-precocious-puberty","stem":"Which of the following findings is most indicative of central precocious puberty in a young boy?","options":[{"id":"a","text":"Asymmetric testicular enlargement"},{"id":"b","text":"Delayed bone age"},{"id":"c","text":"Symmetric testicular enlargement"},{"id":"d","text":"Normal testicular size"}],"answerId":"c","explanation":"Symmetric testicular enlargement in a young boy suggests central precocious puberty due to gonadotropin stimulation.","kind":"recall","origin":"ai"},{"id":"hrp1-central-precocious-puberty~ai-2","moduleId":"hrp1-central-precocious-puberty","stem":"What is the expected effect of continuous GnRH therapy in a patient with central precocious puberty?","options":[{"id":"a","text":"Increased testosterone levels"},{"id":"b","text":"Downregulation of pituitary GnRH receptors"},{"id":"c","text":"Enhanced pubertal development"},{"id":"d","text":"Increased LH secretion"}],"answerId":"b","explanation":"Continuous GnRH exposure leads to downregulation of pituitary GnRH receptors, contrasting with the effects of pulsatile GnRH.","kind":"trap","origin":"ai"},{"id":"hrp1-central-precocious-puberty~ai-3","moduleId":"hrp1-central-precocious-puberty","stem":"A 7-year-old girl presents with breast development and advanced bone age. What is the most likely diagnosis?","options":[{"id":"a","text":"Peripheral precocious puberty"},{"id":"b","text":"Central precocious puberty"},{"id":"c","text":"Normal puberty"},{"id":"d","text":"Delayed puberty"}],"answerId":"b","explanation":"The presence of breast development and advanced bone age in a young girl is indicative of central precocious puberty.","kind":"clinical","origin":"ai"},{"id":"hrp1-central-precocious-puberty~ai-4","moduleId":"hrp1-central-precocious-puberty","stem":"In the context of central precocious puberty, which hormone is primarily responsible for stimulating testicular enlargement?","options":[{"id":"a","text":"FSH"},{"id":"b","text":"LH"},{"id":"c","text":"Testosterone"},{"id":"d","text":"GnRH"}],"answerId":"b","explanation":"LH stimulates the testes, leading to enlargement and testosterone production during central precocious puberty.","kind":"mechanism","origin":"ai"},{"id":"hrp1-central-precocious-puberty~ai-5","moduleId":"hrp1-central-precocious-puberty","stem":"How does central precocious puberty differ from peripheral precocious puberty in terms of hormonal regulation?","options":[{"id":"a","text":"Peripheral is due to excess estrogen, central is due to GnRH"},{"id":"b","text":"Both are due to GnRH but differ in timing"},{"id":"c","text":"Central is due to GnRH, peripheral is independent of HPG axis"},{"id":"d","text":"Both are due to excess testosterone"}],"answerId":"c","explanation":"Central precocious puberty involves early activation of the HPG axis, while peripheral precocious puberty occurs independently of this axis.","kind":"integration","linkedModuleIds":["hrp1-peripheral-precocious-puberty"],"origin":"ai"},{"id":"hrp1-central-precocious-puberty~ai-6","moduleId":"hrp1-central-precocious-puberty","stem":"Which of the following is a common consequence of central precocious puberty related to growth?","options":[{"id":"a","text":"Increased final adult height"},{"id":"b","text":"Decreased growth velocity"},{"id":"c","text":"Advanced bone age"},{"id":"d","text":"Delayed epiphyseal closure"}],"answerId":"c","explanation":"Advanced bone age is a common consequence of central precocious puberty, leading to potential shortening of final adult height.","kind":"trap","origin":"ai"},{"id":"hrp1-central-precocious-puberty~ai-7","moduleId":"hrp1-central-precocious-puberty","stem":"What is the relationship between central precocious puberty and normal puberty in terms of HPG axis activation?","options":[{"id":"a","text":"Both have abnormal timing but normal sequence"},{"id":"b","text":"Both have normal timing and sequence"},{"id":"c","text":"Central has early activation while normal has delayed activation"},{"id":"d","text":"Central has normal activation but abnormal sequence"}],"answerId":"a","explanation":"Both conditions exhibit a normal sequence of puberty but with abnormal timing in central precocious puberty.","kind":"integration","linkedModuleIds":["hrp1-normal-puberty-tanner"],"origin":"ai"}],"hrp1-mammary-development-lactogenesis":[{"id":"hrp1-mammary-development-lactogenesis~ai-0","moduleId":"hrp1-mammary-development-lactogenesis","stem":"Which hormone primarily drives the differentiation of mammary glands during pregnancy?","options":[{"id":"a","text":"Estrogen"},{"id":"b","text":"Prolactin"},{"id":"c","text":"Progesterone"},{"id":"d","text":"Oxytocin"}],"answerId":"c","explanation":"Progesterone is crucial for lobuloalveolar development in the mammary glands during pregnancy.","kind":"recall","origin":"ai"},{"id":"hrp1-mammary-development-lactogenesis~ai-1","moduleId":"hrp1-mammary-development-lactogenesis","stem":"What is the primary mechanism by which lactogenesis II is initiated postpartum?","options":[{"id":"a","text":"Increased prolactin levels"},{"id":"b","text":"Decreased estrogen and progesterone"},{"id":"c","text":"Suckling stimulus"},{"id":"d","text":"Increased cortisol levels"}],"answerId":"b","explanation":"The withdrawal of placental steroids (estrogen and progesterone) is essential for the activation of lactogenesis II.","kind":"mechanism","origin":"ai"},{"id":"hrp1-mammary-development-lactogenesis~ai-2","moduleId":"hrp1-mammary-development-lactogenesis","stem":"A patient experiences delayed milk production after delivery due to retained placenta. What is the underlying mechanism?","options":[{"id":"a","text":"Prolactin deficiency"},{"id":"b","text":"Persistent placental steroids"},{"id":"c","text":"Oxytocin deficiency"},{"id":"d","text":"Insufficient suckling"}],"answerId":"b","explanation":"Persistent placental steroids inhibit the secretory activation necessary for milk production.","kind":"recall","origin":"ai"},{"id":"hrp1-mammary-development-lactogenesis~ai-3","moduleId":"hrp1-mammary-development-lactogenesis","stem":"Which of the following statements about prolactin during pregnancy is true?","options":[{"id":"a","text":"It causes full-volume milk secretion."},{"id":"b","text":"It is the only hormone needed for lactogenesis."},{"id":"c","text":"High levels are present but do not induce milk secretion."},{"id":"d","text":"It decreases after delivery."}],"answerId":"c","explanation":"High estrogen and progesterone levels during pregnancy inhibit full milk secretion despite high prolactin levels.","kind":"trap","origin":"ai"},{"id":"hrp1-mammary-development-lactogenesis~ai-4","moduleId":"hrp1-mammary-development-lactogenesis","stem":"What role does frequent milk removal play in lactation?","options":[{"id":"a","text":"Increases estrogen levels"},{"id":"b","text":"Enhances prolactin signaling"},{"id":"c","text":"Decreases milk production"},{"id":"d","text":"Inhibits oxytocin release"}],"answerId":"b","explanation":"Frequent milk removal stimulates prolactin signaling, which is essential for maintaining milk production.","kind":"clinical","origin":"ai"},{"id":"hrp1-mammary-development-lactogenesis~ai-5","moduleId":"hrp1-mammary-development-lactogenesis","stem":"How does the composition of human milk benefit infant health?","options":[{"id":"a","text":"High protein content"},{"id":"b","text":"Presence of antibodies"},{"id":"c","text":"Low fat content"},{"id":"d","text":"High sugar content"}],"answerId":"b","explanation":"Human milk contains antibodies that provide immune protection to the infant.","kind":"integration","linkedModuleIds":["hrp1-human-milk-composition-benefits"],"origin":"ai"},{"id":"hrp1-mammary-development-lactogenesis~ai-6","moduleId":"hrp1-mammary-development-lactogenesis","stem":"Which hormone is primarily responsible for the let-down reflex during breastfeeding?","options":[{"id":"a","text":"Estrogen"},{"id":"b","text":"Prolactin"},{"id":"c","text":"Oxytocin"},{"id":"d","text":"Cortisol"}],"answerId":"c","explanation":"Oxytocin is responsible for the let-down reflex, facilitating milk ejection during breastfeeding.","kind":"integration","linkedModuleIds":["hrp1-suckling-prolactin-oxytocin"],"origin":"ai"}],"hrp1-placenta-endocrine-hcg":[{"id":"hrp1-placenta-endocrine-hcg~ai-0","moduleId":"hrp1-placenta-endocrine-hcg","stem":"What is the primary function of hCG during early pregnancy?","options":[{"id":"a","text":"Stimulate fetal growth"},{"id":"b","text":"Rescue the corpus luteum"},{"id":"c","text":"Promote uterine contractions"},{"id":"d","text":"Inhibit maternal immune response"}],"answerId":"b","explanation":"hCG binds to LH receptors, rescuing the corpus luteum to maintain progesterone production until the placenta takes over.","kind":"recall","origin":"ai"},{"id":"hrp1-placenta-endocrine-hcg~ai-1","moduleId":"hrp1-placenta-endocrine-hcg","stem":"Which placental tissue is primarily responsible for hCG secretion?","options":[{"id":"a","text":"Chorion"},{"id":"b","text":"Syncytiotrophoblast"},{"id":"c","text":"Cytotrophoblast"},{"id":"d","text":"Decidua"}],"answerId":"b","explanation":"The syncytiotrophoblast is the major endocrine tissue of the placenta that secretes hCG.","kind":"recall","origin":"ai"},{"id":"hrp1-placenta-endocrine-hcg~ai-2","moduleId":"hrp1-placenta-endocrine-hcg","stem":"What is a common clinical finding associated with abnormal hCG trends?","options":[{"id":"a","text":"Increased fetal heart rate"},{"id":"b","text":"Positive pregnancy test"},{"id":"c","text":"Pelvic pain and bleeding"},{"id":"d","text":"Elevated maternal blood pressure"}],"answerId":"c","explanation":"Abnormal hCG trends, especially when accompanied by pain or bleeding, may indicate issues with pregnancy location or viability.","kind":"clinical","origin":"ai"},{"id":"hrp1-placenta-endocrine-hcg~ai-3","moduleId":"hrp1-placenta-endocrine-hcg","stem":"Which statement about hCG levels during pregnancy is true?","options":[{"id":"a","text":"hCG levels remain constant throughout pregnancy"},{"id":"b","text":"hCG peaks at the end of the second trimester"},{"id":"c","text":"hCG rises rapidly and peaks in the first trimester"},{"id":"d","text":"hCG is only produced in the first trimester"}],"answerId":"c","explanation":"hCG levels rise rapidly early in pregnancy, peak near the end of the first trimester, and then decline to a plateau.","kind":"recall","origin":"ai"},{"id":"hrp1-placenta-endocrine-hcg~ai-4","moduleId":"hrp1-placenta-endocrine-hcg","stem":"Which of the following is a trap regarding hCG and pregnancy diagnosis?","options":[{"id":"a","text":"A positive hCG confirms an intrauterine pregnancy"},{"id":"b","text":"hCG can be produced in ectopic pregnancies"},{"id":"c","text":"hCG levels are always indicative of fetal health"},{"id":"d","text":"hCG is only produced by the placenta"}],"answerId":"a","explanation":"A positive hCG test indicates trophoblastic hormone production but does not confirm the location of the pregnancy, as ectopic pregnancies can also produce hCG.","kind":"trap","origin":"ai"},{"id":"hrp1-placenta-endocrine-hcg~ai-5","moduleId":"hrp1-placenta-endocrine-hcg","stem":"How does hCG relate to the metabolic adaptations during pregnancy?","options":[{"id":"a","text":"It regulates maternal blood sugar levels"},{"id":"b","text":"It stimulates maternal insulin resistance"},{"id":"c","text":"It enhances fetal nutrient absorption"},{"id":"d","text":"It decreases maternal metabolic rate"}],"answerId":"b","explanation":"hCG plays a role in promoting maternal insulin resistance, which is crucial for ensuring adequate nutrient supply to the fetus.","kind":"integration","linkedModuleIds":["hrp1-hpl-placental-gh-crh"],"origin":"ai"},{"id":"hrp1-placenta-endocrine-hcg~ai-6","moduleId":"hrp1-placenta-endocrine-hcg","stem":"What role does hCG play in the context of placental hormone interactions?","options":[{"id":"a","text":"It inhibits progesterone production"},{"id":"b","text":"It stimulates the production of placental GH"},{"id":"c","text":"It enhances estrogen synthesis"},{"id":"d","text":"It directly regulates hPL secretion"}],"answerId":"b","explanation":"hCG is involved in signaling pathways that stimulate the production of placental GH, which is important for maternal metabolic adaptation.","kind":"integration","linkedModuleIds":["hrp1-gestational-progesterone-estrogen"],"origin":"ai"}],"hrp1-prenatal-care-risk-screening":[{"id":"hrp1-prenatal-care-risk-screening~ai-0","moduleId":"hrp1-prenatal-care-risk-screening","stem":"What is the earliest positive confirmation of pregnancy?","options":[{"id":"a","text":"Fetal cardiac activity on ultrasound"},{"id":"b","text":"Amenorrhea"},{"id":"c","text":"Nausea"},{"id":"d","text":"Breast tenderness"}],"answerId":"a","explanation":"Fetal cardiac activity on ultrasound is a definitive sign of pregnancy, confirming the presence of a viable fetus.","kind":"recall","origin":"ai"},{"id":"hrp1-prenatal-care-risk-screening~ai-1","moduleId":"hrp1-prenatal-care-risk-screening","stem":"Which of the following is a presumptive sign of pregnancy?","options":[{"id":"a","text":"Fetal movement"},{"id":"b","text":"Amenorrhea"},{"id":"c","text":"Positive pregnancy test"},{"id":"d","text":"Fetal cardiac activity"}],"answerId":"b","explanation":"Amenorrhea is a common presumptive sign of pregnancy but not definitive.","kind":"recall","origin":"ai"},{"id":"hrp1-prenatal-care-risk-screening~ai-2","moduleId":"hrp1-prenatal-care-risk-screening","stem":"What is the primary purpose of early prenatal screening?","options":[{"id":"a","text":"To confirm a fetal diagnosis"},{"id":"b","text":"To estimate risk for conditions"},{"id":"c","text":"To replace diagnostic testing"},{"id":"d","text":"To provide treatment options"}],"answerId":"b","explanation":"Early prenatal screening is designed to estimate risk for various conditions, not to confirm diagnoses.","kind":"mechanism","origin":"ai"},{"id":"hrp1-prenatal-care-risk-screening~ai-3","moduleId":"hrp1-prenatal-care-risk-screening","stem":"Which of the following statements about screening tests is true?","options":[{"id":"a","text":"They provide definitive diagnoses"},{"id":"b","text":"They are always accurate"},{"id":"c","text":"They may lead to diagnostic testing"},{"id":"d","text":"They are invasive procedures"}],"answerId":"c","explanation":"Screening tests change the probability of a condition and may lead to further diagnostic testing if results are positive.","kind":"trap","origin":"ai"},{"id":"hrp1-prenatal-care-risk-screening~ai-4","moduleId":"hrp1-prenatal-care-risk-screening","stem":"A pregnant woman presents with nausea and breast tenderness. What is the significance of these symptoms?","options":[{"id":"a","text":"They confirm pregnancy"},{"id":"b","text":"They are presumptive signs"},{"id":"c","text":"They indicate fetal distress"},{"id":"d","text":"They suggest ectopic pregnancy"}],"answerId":"b","explanation":"Nausea and breast tenderness are common hormonal symptoms that are presumptive signs of pregnancy.","kind":"clinical","origin":"ai"},{"id":"hrp1-prenatal-care-risk-screening~ai-5","moduleId":"hrp1-prenatal-care-risk-screening","stem":"How does early prenatal care impact maternal and fetal risk assessment?","options":[{"id":"a","text":"It eliminates all risks"},{"id":"b","text":"It opens a timed pathway for assessment"},{"id":"c","text":"It is only for maternal health"},{"id":"d","text":"It focuses solely on fetal health"}],"answerId":"b","explanation":"Early prenatal care establishes a framework for timely assessment of both maternal and fetal risks.","kind":"mechanism","origin":"ai"},{"id":"hrp1-prenatal-care-risk-screening~ai-6","moduleId":"hrp1-prenatal-care-risk-screening","stem":"Which screening test is most relevant for assessing risk of gestational diabetes in pregnancy?","options":[{"id":"a","text":"Ultrasound"},{"id":"b","text":"Blood glucose test"},{"id":"c","text":"Amniocentesis"},{"id":"d","text":"Chorionic villus sampling"}],"answerId":"b","explanation":"A blood glucose test is crucial for screening gestational diabetes, which is assessed later in pregnancy.","kind":"integration","linkedModuleIds":["diabetes-diagnostic-criteria-gdm"],"origin":"ai"},{"id":"hrp1-prenatal-care-risk-screening~ai-7","moduleId":"hrp1-prenatal-care-risk-screening","stem":"What is a common screening test for aneuploidy during pregnancy?","options":[{"id":"a","text":"Blood pressure measurement"},{"id":"b","text":"Ultrasound"},{"id":"c","text":"Amniocentesis"},{"id":"d","text":"Nuchal translucency screening"}],"answerId":"d","explanation":"Nuchal translucency screening is a common non-invasive test used to assess the risk of aneuploidy in the first trimester.","kind":"integration","linkedModuleIds":["prenatal-screening-diagnosis"],"origin":"ai"}],"hrp1-uterine-cycle-fertility-signs":[{"id":"hrp1-uterine-cycle-fertility-signs~ai-0","moduleId":"hrp1-uterine-cycle-fertility-signs","stem":"What hormone is primarily responsible for the thickening of cervical mucus during the luteal phase?","options":[{"id":"a","text":"Estrogen"},{"id":"b","text":"Progesterone"},{"id":"c","text":"LH"},{"id":"d","text":"FSH"}],"answerId":"b","explanation":"Progesterone thickens cervical mucus, making it less permeable to sperm during the luteal phase.","kind":"recall","origin":"ai"},{"id":"hrp1-uterine-cycle-fertility-signs~ai-1","moduleId":"hrp1-uterine-cycle-fertility-signs","stem":"Which finding indicates successful ovulation has occurred?","options":[{"id":"a","text":"Positive LH surge"},{"id":"b","text":"Increased estrogen levels"},{"id":"c","text":"Sustained rise in basal body temperature"},{"id":"d","text":"Thick cervical mucus"}],"answerId":"c","explanation":"A sustained rise in basal body temperature confirms progesterone exposure, indicating that ovulation has occurred.","kind":"clinical","origin":"ai"},{"id":"hrp1-uterine-cycle-fertility-signs~ai-2","moduleId":"hrp1-uterine-cycle-fertility-signs","stem":"What is the primary mechanism by which combined hormonal contraception prevents ovulation?","options":[{"id":"a","text":"Inhibiting estrogen production"},{"id":"b","text":"Suppressing FSH and LH secretion"},{"id":"c","text":"Increasing progesterone levels"},{"id":"d","text":"Thickening cervical mucus"}],"answerId":"b","explanation":"Combined hormonal contraception primarily works by suppressing FSH and LH secretion, preventing ovulation.","kind":"mechanism","origin":"ai"},{"id":"hrp1-uterine-cycle-fertility-signs~ai-3","moduleId":"hrp1-uterine-cycle-fertility-signs","stem":"What does a positive LH test predict regarding ovulation?","options":[{"id":"a","text":"Successful ovulation will definitely occur"},{"id":"b","text":"Ovulation may occur within 24-36 hours"},{"id":"c","text":"It confirms ovulation has already happened"},{"id":"d","text":"It indicates high estrogen levels"}],"answerId":"b","explanation":"A positive LH test predicts that ovulation may occur within 24-36 hours, but does not guarantee it.","kind":"trap","origin":"ai"},{"id":"hrp1-uterine-cycle-fertility-signs~ai-4","moduleId":"hrp1-uterine-cycle-fertility-signs","stem":"How does estrogen affect cervical mucus during the preovulatory phase?","options":[{"id":"a","text":"Makes it thick and sticky"},{"id":"b","text":"Increases salt and water content"},{"id":"c","text":"Decreases its volume"},{"id":"d","text":"Inhibits sperm passage"}],"answerId":"b","explanation":"Estrogen increases the salt and water content of cervical mucus, making it thin and stretchy, facilitating sperm passage.","kind":"mechanism","origin":"ai"},{"id":"hrp1-uterine-cycle-fertility-signs~ai-5","moduleId":"hrp1-uterine-cycle-fertility-signs","stem":"How does the uterine cycle relate to the ovarian cycle during the menstrual cycle?","options":[{"id":"a","text":"They are independent processes"},{"id":"b","text":"The uterine cycle is a direct result of ovarian hormone changes"},{"id":"c","text":"The ovarian cycle is regulated by uterine signals"},{"id":"d","text":"They occur at different times during the cycle"}],"answerId":"b","explanation":"The uterine cycle is directly influenced by the hormonal changes occurring in the ovarian cycle, particularly estrogen and progesterone.","kind":"integration","linkedModuleIds":["hrp1-ovarian-cycle-ovulation"],"origin":"ai"},{"id":"hrp1-uterine-cycle-fertility-signs~ai-6","moduleId":"hrp1-uterine-cycle-fertility-signs","stem":"What is the relationship between the midcycle surge of LH and the uterine cycle?","options":[{"id":"a","text":"It triggers menstruation"},{"id":"b","text":"It leads to the secretory phase"},{"id":"c","text":"It initiates the proliferative phase"},{"id":"d","text":"It causes ovulation and subsequent endometrial changes"}],"answerId":"d","explanation":"The midcycle surge of LH triggers ovulation, which leads to changes in the endometrium necessary for potential implantation.","kind":"integration","linkedModuleIds":["hrp1-cycle-feedback-gonadotropins"],"origin":"ai"}],"hrp1-menopause-therapy":[{"id":"hrp1-menopause-therapy~ai-0","moduleId":"hrp1-menopause-therapy","stem":"What is the primary reason for prescribing progestogen alongside systemic estrogen in postmenopausal women with an intact uterus?","options":[{"id":"a","text":"To enhance estrogen's efficacy"},{"id":"b","text":"To prevent endometrial hyperplasia"},{"id":"c","text":"To reduce vasomotor symptoms"},{"id":"d","text":"To improve bone density"}],"answerId":"b","explanation":"Progestogen is necessary to counteract the proliferative effects of estrogen on the endometrium in women with an intact uterus.","kind":"recall","origin":"ai"},{"id":"hrp1-menopause-therapy~ai-1","moduleId":"hrp1-menopause-therapy","stem":"Which of the following is a common local treatment for isolated vaginal dryness in postmenopausal women?","options":[{"id":"a","text":"Systemic estrogen therapy"},{"id":"b","text":"Low-dose vaginal estrogen"},{"id":"c","text":"Progestogen therapy"},{"id":"d","text":"Selective serotonin reuptake inhibitors"}],"answerId":"b","explanation":"Low-dose vaginal estrogen directly targets the affected tissue with minimal systemic absorption.","kind":"recall","origin":"ai"},{"id":"hrp1-menopause-therapy~ai-2","moduleId":"hrp1-menopause-therapy","stem":"A 55-year-old woman presents with postmenopausal bleeding. What is the most appropriate next step in management?","options":[{"id":"a","text":"Assume benign hormonal changes"},{"id":"b","text":"Perform a transvaginal ultrasound"},{"id":"c","text":"Start systemic estrogen therapy"},{"id":"d","text":"Reassure the patient"}],"answerId":"b","explanation":"Postmenopausal bleeding requires evaluation to rule out potential malignancy rather than assuming it is benign.","kind":"clinical","origin":"ai"},{"id":"hrp1-menopause-therapy~ai-3","moduleId":"hrp1-menopause-therapy","stem":"What is the mechanism by which systemic estrogen therapy alleviates vasomotor symptoms in menopause?","options":[{"id":"a","text":"Increases serotonin levels"},{"id":"b","text":"Inhibits hypothalamic thermoregulation"},{"id":"c","text":"Enhances blood flow to the skin"},{"id":"d","text":"Stimulates endorphin release"}],"answerId":"b","explanation":"Estrogen acts on the hypothalamus to stabilize thermoregulation, reducing the frequency and severity of vasomotor symptoms.","kind":"mechanism","origin":"ai"},{"id":"hrp1-menopause-therapy~ai-4","moduleId":"hrp1-menopause-therapy","stem":"Which of the following statements about hormone therapy in menopause is true?","options":[{"id":"a","text":"Systemic estrogen alone is safe for all women"},{"id":"b","text":"Progestogen is needed for endometrial protection"},{"id":"c","text":"Hormone therapy is always the first-line treatment"},{"id":"d","text":"Local estrogen therapy is ineffective for vaginal dryness"}],"answerId":"b","explanation":"Unopposed estrogen can lead to endometrial hyperplasia, making progestogen necessary for women with an intact uterus.","kind":"trap","origin":"ai"},{"id":"hrp1-menopause-therapy~ai-5","moduleId":"hrp1-menopause-therapy","stem":"How does the menopause axis definition relate to the management of menopausal symptoms?","options":[{"id":"a","text":"It defines the age of menopause onset"},{"id":"b","text":"It explains the hormonal changes affecting symptoms"},{"id":"c","text":"It identifies the need for surgical intervention"},{"id":"d","text":"It outlines the risks of hormone therapy"}],"answerId":"b","explanation":"Understanding the hormonal changes during menopause helps tailor symptom management strategies effectively.","kind":"integration","linkedModuleIds":["hrp1-menopause-axis-definition"],"origin":"ai"},{"id":"hrp1-menopause-therapy~ai-6","moduleId":"hrp1-menopause-therapy","stem":"Which long-term effects of menopause should be considered when discussing hormone therapy options?","options":[{"id":"a","text":"Increased risk of cardiovascular disease"},{"id":"b","text":"Decreased risk of osteoporosis"},{"id":"c","text":"Improved cognitive function"},{"id":"d","text":"Reduced risk of breast cancer"}],"answerId":"a","explanation":"Menopause is associated with an increased risk of cardiovascular disease, which must be weighed against the benefits of hormone therapy.","kind":"integration","linkedModuleIds":["hrp1-menopause-symptoms-health-effects"],"origin":"ai"}],"hrp1-hpl-placental-gh-crh":[{"id":"hrp1-hpl-placental-gh-crh~ai-0","moduleId":"hrp1-hpl-placental-gh-crh","stem":"What is the primary role of human placental lactogen (hPL) during pregnancy?","options":[{"id":"a","text":"Promotes fetal lung development"},{"id":"b","text":"Supports mammary gland development"},{"id":"c","text":"Increases maternal metabolic rate"},{"id":"d","text":"Enhances maternal calcium absorption"}],"answerId":"b","explanation":"hPL primarily supports mammary gland development and promotes lipolysis, contributing to maternal insulin resistance.","kind":"recall","origin":"ai"},{"id":"hrp1-hpl-placental-gh-crh~ai-1","moduleId":"hrp1-hpl-placental-gh-crh","stem":"How does placental growth hormone (GH) affect maternal metabolism?","options":[{"id":"a","text":"Decreases insulin sensitivity"},{"id":"b","text":"Increases glucose uptake by maternal tissues"},{"id":"c","text":"Stimulates maternal protein synthesis"},{"id":"d","text":"Reduces maternal fat stores"}],"answerId":"a","explanation":"Placental GH decreases insulin sensitivity, leading to increased maternal insulin resistance.","kind":"mechanism","origin":"ai"},{"id":"hrp1-hpl-placental-gh-crh~ai-2","moduleId":"hrp1-hpl-placental-gh-crh","stem":"What clinical finding is expected in a pregnant woman as insulin resistance increases?","options":[{"id":"a","text":"Decreased fasting glucose levels"},{"id":"b","text":"Increased insulin requirement"},{"id":"c","text":"Decreased postprandial glucose levels"},{"id":"d","text":"Increased lipid storage"}],"answerId":"b","explanation":"As insulin resistance increases during pregnancy, the insulin requirement also increases to maintain glucose homeostasis.","kind":"recall","origin":"ai"},{"id":"hrp1-hpl-placental-gh-crh~ai-3","moduleId":"hrp1-hpl-placental-gh-crh","stem":"Which statement correctly describes the metabolic adaptation in pregnancy?","options":[{"id":"a","text":"Insulin levels decrease to enhance glucose availability"},{"id":"b","text":"Maternal fasting leads to increased glucose production"},{"id":"c","text":"Lipolysis is suppressed to conserve energy"},{"id":"d","text":"Glucose is preferentially used by the fetus"}],"answerId":"b","explanation":"During pregnancy, maternal fasting leads to increased glucose production while lipolysis is promoted to provide energy for the mother.","kind":"trap","origin":"ai"},{"id":"hrp1-hpl-placental-gh-crh~ai-4","moduleId":"hrp1-hpl-placental-gh-crh","stem":"What is the consequence of insufficient beta-cell compensation during pregnancy?","options":[{"id":"a","text":"Increased insulin sensitivity"},{"id":"b","text":"Gestational diabetes mellitus"},{"id":"c","text":"Decreased maternal weight gain"},{"id":"d","text":"Enhanced fetal growth"}],"answerId":"b","explanation":"Insufficient beta-cell compensation for increased insulin resistance results in gestational diabetes mellitus.","kind":"clinical","origin":"ai"},{"id":"hrp1-hpl-placental-gh-crh~ai-5","moduleId":"hrp1-hpl-placental-gh-crh","stem":"How does placental CRH contribute to fetal development?","options":[{"id":"a","text":"Increases maternal appetite"},{"id":"b","text":"Stimulates fetal adrenal development"},{"id":"c","text":"Enhances maternal insulin secretion"},{"id":"d","text":"Inhibits fetal growth"}],"answerId":"b","explanation":"Placental CRH plays a role in fetal HPA axis maturation and timing of parturition, stimulating fetal adrenal development.","kind":"recall","origin":"ai"},{"id":"hrp1-hpl-placental-gh-crh~ai-6","moduleId":"hrp1-hpl-placental-gh-crh","stem":"Which placental hormone is primarily responsible for increasing insulin resistance in pregnancy?","options":[{"id":"a","text":"hCG"},{"id":"b","text":"Estrogen"},{"id":"c","text":"hPL"},{"id":"d","text":"Progesterone"}],"answerId":"c","explanation":"Human placental lactogen (hPL) is primarily responsible for increasing insulin resistance during pregnancy.","kind":"mechanism","origin":"ai"},{"id":"hrp1-hpl-placental-gh-crh~ai-7","moduleId":"hrp1-hpl-placental-gh-crh","stem":"How does the role of placental hormones in pregnancy relate to the development of gestational diabetes?","options":[{"id":"a","text":"They decrease insulin production"},{"id":"b","text":"They increase insulin sensitivity"},{"id":"c","text":"They promote insulin resistance"},{"id":"d","text":"They enhance glucose utilization by the mother"}],"answerId":"c","explanation":"Placental hormones promote insulin resistance, and when beta-cell compensation is insufficient, gestational diabetes can develop.","kind":"integration","linkedModuleIds":["hen1-gestational-diabetes-diagnosis"],"origin":"ai"},{"id":"hrp1-hpl-placental-gh-crh~ai-8","moduleId":"hrp1-hpl-placental-gh-crh","stem":"What is the relationship between placental hormones and maternal metabolic adaptation?","options":[{"id":"a","text":"Placental hormones decrease maternal energy expenditure"},{"id":"b","text":"They redirect maternal fuel towards fetal growth"},{"id":"c","text":"They inhibit fetal nutrient transfer"},{"id":"d","text":"They promote maternal weight loss"}],"answerId":"b","explanation":"Placental hormones redirect maternal fuel toward fetal growth, facilitating the metabolic adaptations necessary for pregnancy.","kind":"integration","linkedModuleIds":["exercise-stress-fuel-integration"],"origin":"ai"}],"hrp1-menopause-symptoms-health-effects":[{"id":"hrp1-menopause-symptoms-health-effects~ai-0","moduleId":"hrp1-menopause-symptoms-health-effects","stem":"What physiological change primarily causes vasomotor symptoms during menopause?","options":[{"id":"a","text":"Increased estrogen levels"},{"id":"b","text":"Decreased estrogen levels"},{"id":"c","text":"Increased progesterone levels"},{"id":"d","text":"Decreased progesterone levels"}],"answerId":"b","explanation":"Vasomotor symptoms are primarily due to decreased estrogen levels affecting thermoregulation.","kind":"recall","origin":"ai"},{"id":"hrp1-menopause-symptoms-health-effects~ai-1","moduleId":"hrp1-menopause-symptoms-health-effects","stem":"Which of the following findings is characteristic of the genitourinary syndrome of menopause?","options":[{"id":"a","text":"Increased vaginal acidity"},{"id":"b","text":"Thickened vaginal epithelium"},{"id":"c","text":"Vaginal dryness"},{"id":"d","text":"Increased libido"}],"answerId":"c","explanation":"Vaginal dryness is a key feature of the genitourinary syndrome of menopause due to low estrogen.","kind":"recall","origin":"ai"},{"id":"hrp1-menopause-symptoms-health-effects~ai-2","moduleId":"hrp1-menopause-symptoms-health-effects","stem":"How does estrogen deficiency affect bone health in postmenopausal women?","options":[{"id":"a","text":"Increases osteoblast activity"},{"id":"b","text":"Decreases osteoclast activity"},{"id":"c","text":"Increases bone resorption"},{"id":"d","text":"Decreases calcium absorption"}],"answerId":"c","explanation":"Estrogen deficiency leads to increased bone resorption by reducing the restraint on osteoclasts.","kind":"mechanism","origin":"ai"},{"id":"hrp1-menopause-symptoms-health-effects~ai-3","moduleId":"hrp1-menopause-symptoms-health-effects","stem":"A 52-year-old woman reports hot flashes and night sweats. What is the underlying mechanism?","options":[{"id":"a","text":"Increased thermoregulatory set point"},{"id":"b","text":"Decreased hypothalamic thermoneutral zone"},{"id":"c","text":"Increased sympathetic nervous system activity"},{"id":"d","text":"Decreased peripheral vasodilation"}],"answerId":"b","explanation":"Hot flashes are due to a narrowed hypothalamic thermoneutral zone, causing instability in thermoregulation.","kind":"mechanism","origin":"ai"},{"id":"hrp1-menopause-symptoms-health-effects~ai-4","moduleId":"hrp1-menopause-symptoms-health-effects","stem":"Which symptom should NOT be automatically attributed to menopause without further evaluation?","options":[{"id":"a","text":"Hot flashes"},{"id":"b","text":"Vaginal dryness"},{"id":"c","text":"Depression"},{"id":"d","text":"Irregular periods"}],"answerId":"c","explanation":"Depression can have multiple causes and should be evaluated separately from menopause symptoms.","kind":"trap","origin":"ai"},{"id":"hrp1-menopause-symptoms-health-effects~ai-5","moduleId":"hrp1-menopause-symptoms-health-effects","stem":"How does the decline in estrogen during menopause affect sleep patterns?","options":[{"id":"a","text":"Increases REM sleep"},{"id":"b","text":"Decreases sleep latency"},{"id":"c","text":"Impairs sleep quality"},{"id":"d","text":"Enhances deep sleep"}],"answerId":"c","explanation":"Estrogen decline can impair sleep quality, contributing to insomnia and other sleep disturbances.","kind":"clinical","origin":"ai"},{"id":"hrp1-menopause-symptoms-health-effects~ai-6","moduleId":"hrp1-menopause-symptoms-health-effects","stem":"Which of the following menopause symptoms is most closely related to changes in thermoregulation?","options":[{"id":"a","text":"Vaginal dryness"},{"id":"b","text":"Hot flashes"},{"id":"c","text":"Mood swings"},{"id":"d","text":"Urinary incontinence"}],"answerId":"b","explanation":"Hot flashes are directly related to thermoregulation changes due to estrogen decline.","kind":"integration","linkedModuleIds":["skin-physiology-thermoregulation"],"origin":"ai"},{"id":"hrp1-menopause-symptoms-health-effects~ai-7","moduleId":"hrp1-menopause-symptoms-health-effects","stem":"What is a common long-term effect of menopause that may overlap with other conditions?","options":[{"id":"a","text":"Increased risk of osteoporosis"},{"id":"b","text":"Improved cardiovascular health"},{"id":"c","text":"Decreased risk of depression"},{"id":"d","text":"Increased fertility"}],"answerId":"a","explanation":"Increased risk of osteoporosis is a well-documented long-term effect of menopause that can overlap with other health issues.","kind":"integration","linkedModuleIds":["hrp1-menopause-therapy"],"origin":"ai"}],"hrp1-menopause-axis-definition":[{"id":"hrp1-menopause-axis-definition~ai-0","moduleId":"hrp1-menopause-axis-definition","stem":"What is the primary hormonal change that characterizes natural menopause?","options":[{"id":"a","text":"Increased estradiol"},{"id":"b","text":"Decreased inhibin B"},{"id":"c","text":"Increased progesterone"},{"id":"d","text":"Stable FSH levels"}],"answerId":"b","explanation":"Decreased inhibin B occurs due to follicle depletion, leading to increased FSH levels.","kind":"recall","origin":"ai"},{"id":"hrp1-menopause-axis-definition~ai-1","moduleId":"hrp1-menopause-axis-definition","stem":"Which of the following findings is indicative of hypergonadotropic ovarian failure?","options":[{"id":"a","text":"Low FSH with high estradiol"},{"id":"b","text":"High FSH with low estradiol"},{"id":"c","text":"Normal FSH with normal estradiol"},{"id":"d","text":"Low FSH with low estradiol"}],"answerId":"b","explanation":"High FSH with low estradiol is characteristic of hypergonadotropic ovarian failure, as seen in menopause.","kind":"recall","origin":"ai"},{"id":"hrp1-menopause-axis-definition~ai-2","moduleId":"hrp1-menopause-axis-definition","stem":"What is the correct definition of perimenopause?","options":[{"id":"a","text":"12 months of amenorrhea"},{"id":"b","text":"The time leading up to menopause"},{"id":"c","text":"A phase of stable hormone levels"},{"id":"d","text":"A period of increased fertility"}],"answerId":"b","explanation":"Perimenopause refers to the transitional phase leading up to menopause, characterized by irregular cycles.","kind":"recall","origin":"ai"},{"id":"hrp1-menopause-axis-definition~ai-3","moduleId":"hrp1-menopause-axis-definition","stem":"Which statement about the diagnosis of natural menopause is true?","options":[{"id":"a","text":"One high FSH value confirms menopause"},{"id":"b","text":"Menopause is diagnosed after 12 months of amenorrhea"},{"id":"c","text":"Menopause can be diagnosed with a single estradiol measurement"},{"id":"d","text":"Menopause is always symptomatic"}],"answerId":"b","explanation":"Natural menopause is diagnosed retrospectively after 12 months of amenorrhea without another cause.","kind":"trap","origin":"ai"},{"id":"hrp1-menopause-axis-definition~ai-4","moduleId":"hrp1-menopause-axis-definition","stem":"What is the predominant estrogen produced after menopause?","options":[{"id":"a","text":"Estradiol"},{"id":"b","text":"Estrone"},{"id":"c","text":"Estriol"},{"id":"d","text":"Testosterone"}],"answerId":"b","explanation":"After menopause, estrone from peripheral aromatization becomes the predominant estrogen.","kind":"recall","origin":"ai"},{"id":"hrp1-menopause-axis-definition~ai-5","moduleId":"hrp1-menopause-axis-definition","stem":"How does follicle depletion lead to increased FSH levels?","options":[{"id":"a","text":"Increased estrogen feedback"},{"id":"b","text":"Decreased inhibin B production"},{"id":"c","text":"Increased luteinizing hormone"},{"id":"d","text":"Decreased follicle-stimulating hormone receptors"}],"answerId":"b","explanation":"Follicle depletion decreases inhibin B, removing its negative feedback on FSH, leading to increased levels.","kind":"mechanism","origin":"ai"},{"id":"hrp1-menopause-axis-definition~ai-6","moduleId":"hrp1-menopause-axis-definition","stem":"How might the management of menopause symptoms relate to ovarian axis changes?","options":[{"id":"a","text":"Hormone therapy is contraindicated in all cases"},{"id":"b","text":"Hormone therapy can mitigate symptoms due to decreased estrogen"},{"id":"c","text":"Menopause symptoms are unrelated to hormonal changes"},{"id":"d","text":"Hormone therapy is only effective before menopause"}],"answerId":"b","explanation":"Hormone therapy can alleviate symptoms resulting from decreased estrogen levels due to ovarian axis changes.","kind":"integration","linkedModuleIds":["hrp1-menopause-therapy"],"origin":"ai"},{"id":"hrp1-menopause-axis-definition~ai-7","moduleId":"hrp1-menopause-axis-definition","stem":"What long-term health effects should be monitored in postmenopausal women?","options":[{"id":"a","text":"Increased fertility"},{"id":"b","text":"Decreased cardiovascular risk"},{"id":"c","text":"Increased osteoporosis risk"},{"id":"d","text":"Stable hormonal levels"}],"answerId":"c","explanation":"Postmenopausal women are at increased risk for osteoporosis due to decreased estrogen levels.","kind":"integration","linkedModuleIds":["hrp1-menopause-symptoms-health-effects"],"origin":"ai"}],"hrp1-human-milk-composition-benefits":[{"id":"hrp1-human-milk-composition-benefits~ai-0","moduleId":"hrp1-human-milk-composition-benefits","stem":"What is the primary immunological component found in colostrum?","options":[{"id":"a","text":"Lactoferrin"},{"id":"b","text":"IgA"},{"id":"c","text":"Oligosaccharides"},{"id":"d","text":"Leukocytes"}],"answerId":"b","explanation":"Colostrum is particularly rich in immunoglobulin A (IgA), which plays a crucial role in mucosal immunity.","kind":"recall","origin":"ai"},{"id":"hrp1-human-milk-composition-benefits~ai-1","moduleId":"hrp1-human-milk-composition-benefits","stem":"Which nutrient is essential for milk synthesis during lactation?","options":[{"id":"a","text":"Vitamin D"},{"id":"b","text":"Calcium"},{"id":"c","text":"Glucose"},{"id":"d","text":"Iron"}],"answerId":"c","explanation":"Glucose is a critical energy source for milk synthesis, along with other nutrients like amino acids and lipids.","kind":"mechanism","origin":"ai"},{"id":"hrp1-human-milk-composition-benefits~ai-2","moduleId":"hrp1-human-milk-composition-benefits","stem":"What clinical sign may indicate inadequate milk transfer despite frequent breastfeeding?","options":[{"id":"a","text":"Excessive weight gain"},{"id":"b","text":"Infant dehydration"},{"id":"c","text":"Frequent feeding"},{"id":"d","text":"Normal urine output"}],"answerId":"b","explanation":"Infant dehydration and poor weight gain can suggest inadequate milk transfer, even if the infant is feeding frequently.","kind":"clinical","origin":"ai"},{"id":"hrp1-human-milk-composition-benefits~ai-3","moduleId":"hrp1-human-milk-composition-benefits","stem":"Which of the following is a common misconception about breastfeeding adequacy?","options":[{"id":"a","text":"Weight gain indicates adequate intake"},{"id":"b","text":"Frequent feeding ensures sufficient milk"},{"id":"c","text":"Breastfeeding is always sufficient"},{"id":"d","text":"All infants gain weight similarly"}],"answerId":"b","explanation":"Frequent feeding does not guarantee adequate intake; effective transfer should be assessed through weight and output.","kind":"trap","origin":"ai"},{"id":"hrp1-human-milk-composition-benefits~ai-4","moduleId":"hrp1-human-milk-composition-benefits","stem":"What is a key benefit of breastfeeding for mothers postpartum?","options":[{"id":"a","text":"Increased risk of postpartum depression"},{"id":"b","text":"Enhanced uterine contraction"},{"id":"c","text":"Reduced energy expenditure"},{"id":"d","text":"Decreased milk supply"}],"answerId":"b","explanation":"Breastfeeding promotes uterine contractions, which can help reduce postpartum bleeding and aid recovery.","kind":"recall","origin":"ai"},{"id":"hrp1-human-milk-composition-benefits~ai-5","moduleId":"hrp1-human-milk-composition-benefits","stem":"How does the composition of human milk change over time postpartum?","options":[{"id":"a","text":"Increases in fat content only"},{"id":"b","text":"Decreases in protein content only"},{"id":"c","text":"Transitions from colostrum to mature milk"},{"id":"d","text":"Remains constant throughout lactation"}],"answerId":"c","explanation":"Human milk transitions from colostrum to transitional and then mature milk, with changes in nutrient composition over time.","kind":"mechanism","origin":"ai"},{"id":"hrp1-human-milk-composition-benefits~ai-6","moduleId":"hrp1-human-milk-composition-benefits","stem":"How does lactation affect maternal metabolism, particularly in relation to energy use?","options":[{"id":"a","text":"Increases fat storage"},{"id":"b","text":"Decreases caloric needs"},{"id":"c","text":"Shifts to higher energy expenditure"},{"id":"d","text":"Reduces nutrient absorption"}],"answerId":"c","explanation":"Lactation shifts maternal metabolism to increase energy expenditure to support milk production.","kind":"integration","linkedModuleIds":["ketogenic-fasting-exercise-adaptation"],"origin":"ai"},{"id":"hrp1-human-milk-composition-benefits~ai-7","moduleId":"hrp1-human-milk-composition-benefits","stem":"What is the role of oligosaccharides in human milk?","options":[{"id":"a","text":"Provide energy"},{"id":"b","text":"Act as prebiotics"},{"id":"c","text":"Enhance protein synthesis"},{"id":"d","text":"Increase fat absorption"}],"answerId":"b","explanation":"Oligosaccharides in human milk serve as prebiotics, promoting the growth of beneficial gut bacteria in infants.","kind":"integration","linkedModuleIds":["hrp1-mammary-development-lactogenesis"],"origin":"ai"}],"hrp1-maternal-adaptation-pregnancy":[{"id":"hrp1-maternal-adaptation-pregnancy~ai-0","moduleId":"hrp1-maternal-adaptation-pregnancy","stem":"What physiological change occurs in maternal blood volume during pregnancy?","options":[{"id":"a","text":"Decreases by 10%"},{"id":"b","text":"Increases by 30-50%"},{"id":"c","text":"Remains unchanged"},{"id":"d","text":"Increases by 10%"}],"answerId":"b","explanation":"During pregnancy, maternal blood volume increases by 30-50% to support fetal growth and prepare for delivery.","kind":"recall","origin":"ai"},{"id":"hrp1-maternal-adaptation-pregnancy~ai-1","moduleId":"hrp1-maternal-adaptation-pregnancy","stem":"What is the primary mechanism for the increased cardiac output observed in pregnant women?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Increased stroke volume"},{"id":"c","text":"Decreased systemic vascular resistance"},{"id":"d","text":"Decreased blood viscosity"}],"answerId":"c","explanation":"Increased cardiac output during pregnancy is primarily due to decreased systemic vascular resistance, allowing for higher blood flow.","kind":"mechanism","origin":"ai"},{"id":"hrp1-maternal-adaptation-pregnancy~ai-2","moduleId":"hrp1-maternal-adaptation-pregnancy","stem":"A pregnant woman presents with unilateral leg swelling. What is the most concerning condition to rule out?","options":[{"id":"a","text":"Physiologic edema"},{"id":"b","text":"Deep vein thrombosis"},{"id":"c","text":"Varicose veins"},{"id":"d","text":"Lymphedema"}],"answerId":"b","explanation":"Unilateral leg swelling in pregnancy is not routine and should prompt evaluation for deep vein thrombosis due to increased thromboembolic risk.","kind":"clinical","origin":"ai"},{"id":"hrp1-maternal-adaptation-pregnancy~ai-3","moduleId":"hrp1-maternal-adaptation-pregnancy","stem":"Which of the following statements about hemoglobin levels in pregnancy is true?","options":[{"id":"a","text":"Every fall indicates iron deficiency"},{"id":"b","text":"Physiologic hemodilution occurs"},{"id":"c","text":"Hemoglobin levels remain constant"},{"id":"d","text":"Increased hemoglobin indicates dehydration"}],"answerId":"b","explanation":"In pregnancy, plasma volume expansion leads to physiologic hemodilution, which can lower hemoglobin levels without indicating true iron deficiency.","kind":"trap","origin":"ai"},{"id":"hrp1-maternal-adaptation-pregnancy~ai-4","moduleId":"hrp1-maternal-adaptation-pregnancy","stem":"How does increased tidal volume during pregnancy affect blood gas levels?","options":[{"id":"a","text":"Causes metabolic acidosis"},{"id":"b","text":"Leads to respiratory alkalosis"},{"id":"c","text":"Results in respiratory acidosis"},{"id":"d","text":"Has no effect on blood gas levels"}],"answerId":"b","explanation":"Increased tidal volume during pregnancy leads to compensated mild respiratory alkalosis due to enhanced ventilation.","kind":"mechanism","origin":"ai"},{"id":"hrp1-maternal-adaptation-pregnancy~ai-5","moduleId":"hrp1-maternal-adaptation-pregnancy","stem":"Which adaptation helps support fetal growth by increasing insulin resistance during pregnancy?","options":[{"id":"a","text":"Increased glucose uptake"},{"id":"b","text":"Increased lipid metabolism"},{"id":"c","text":"Decreased metabolic rate"},{"id":"d","text":"Decreased appetite"}],"answerId":"b","explanation":"Increased lipid metabolism and insulin resistance during pregnancy ensure adequate energy supply for fetal growth.","kind":"recall","origin":"ai"},{"id":"hrp1-maternal-adaptation-pregnancy~ai-6","moduleId":"hrp1-maternal-adaptation-pregnancy","stem":"How does maternal adaptation during pregnancy relate to prenatal care risk screening?","options":[{"id":"a","text":"It reduces the need for prenatal visits"},{"id":"b","text":"It complicates the assessment of maternal health"},{"id":"c","text":"It eliminates the risk of gestational diabetes"},{"id":"d","text":"It ensures all pregnancies are low-risk"}],"answerId":"b","explanation":"Maternal adaptations can complicate the assessment of maternal health, making prenatal care and risk screening essential to identify potential complications.","kind":"integration","linkedModuleIds":["hrp1-prenatal-care-risk-screening"],"origin":"ai"},{"id":"hrp1-maternal-adaptation-pregnancy~ai-7","moduleId":"hrp1-maternal-adaptation-pregnancy","stem":"What is the significance of increased venous stasis in pregnancy when considering labor stages?","options":[{"id":"a","text":"It indicates a need for immediate labor induction"},{"id":"b","text":"It can increase the risk of thromboembolism during labor"},{"id":"c","text":"It has no impact on labor mechanics"},{"id":"d","text":"It improves uterine contractions"}],"answerId":"b","explanation":"Increased venous stasis during pregnancy raises the risk of thromboembolism, which is a critical consideration during labor stages.","kind":"integration","linkedModuleIds":["hrp1-labor-stages-mechanics"],"origin":"ai"}],"hrp1-suckling-prolactin-oxytocin":[{"id":"hrp1-suckling-prolactin-oxytocin~ai-0","moduleId":"hrp1-suckling-prolactin-oxytocin","stem":"What is the primary effect of nipple stimulation during breastfeeding?","options":[{"id":"a","text":"Increases dopamine release"},{"id":"b","text":"Increases prolactin secretion"},{"id":"c","text":"Decreases oxytocin levels"},{"id":"d","text":"Inhibits milk synthesis"}],"answerId":"b","explanation":"Nipple stimulation reduces hypothalamic dopamine, leading to increased prolactin secretion for milk synthesis.","kind":"recall","origin":"ai"},{"id":"hrp1-suckling-prolactin-oxytocin~ai-1","moduleId":"hrp1-suckling-prolactin-oxytocin","stem":"Which hormone is responsible for milk ejection during breastfeeding?","options":[{"id":"a","text":"Prolactin"},{"id":"b","text":"Estrogen"},{"id":"c","text":"Oxytocin"},{"id":"d","text":"Progesterone"}],"answerId":"c","explanation":"Oxytocin causes the contraction of myoepithelial cells, leading to milk ejection.","kind":"recall","origin":"ai"},{"id":"hrp1-suckling-prolactin-oxytocin~ai-2","moduleId":"hrp1-suckling-prolactin-oxytocin","stem":"A breastfeeding mother experiences stress and notices her baby is not transferring much milk. What is the likely underlying mechanism?","options":[{"id":"a","text":"Increased prolactin levels"},{"id":"b","text":"Decreased oxytocin release"},{"id":"c","text":"Increased dopamine activity"},{"id":"d","text":"Decreased milk synthesis"}],"answerId":"b","explanation":"Stress can inhibit oxytocin release, affecting milk ejection despite adequate milk production.","kind":"clinical","origin":"ai"},{"id":"hrp1-suckling-prolactin-oxytocin~ai-3","moduleId":"hrp1-suckling-prolactin-oxytocin","stem":"Prolactin's role in lactation includes which of the following?","options":[{"id":"a","text":"Stimulating milk ejection"},{"id":"b","text":"Suppressing GnRH release"},{"id":"c","text":"Increasing oxytocin production"},{"id":"d","text":"Enhancing myoepithelial contraction"}],"answerId":"b","explanation":"Prolactin suppresses pulsatile GnRH, which can lead to lactational amenorrhea.","kind":"recall","origin":"ai"},{"id":"hrp1-suckling-prolactin-oxytocin~ai-4","moduleId":"hrp1-suckling-prolactin-oxytocin","stem":"Which statement correctly describes the relationship between prolactin and oxytocin during breastfeeding?","options":[{"id":"a","text":"Both hormones are released from the same source"},{"id":"b","text":"Prolactin is responsible for milk ejection"},{"id":"c","text":"Oxytocin supports milk synthesis"},{"id":"d","text":"Prolactin and oxytocin have separate but parallel functions"}],"answerId":"d","explanation":"Prolactin supports milk synthesis while oxytocin is responsible for milk ejection.","kind":"trap","origin":"ai"},{"id":"hrp1-suckling-prolactin-oxytocin~ai-5","moduleId":"hrp1-suckling-prolactin-oxytocin","stem":"During exclusive breastfeeding, a mother experiences amenorrhea. This is primarily due to which mechanism?","options":[{"id":"a","text":"Increased estrogen levels"},{"id":"b","text":"Decreased GnRH pulsatility"},{"id":"c","text":"Increased progesterone"},{"id":"d","text":"Increased oxytocin levels"}],"answerId":"b","explanation":"Prolactin suppresses pulsatile GnRH, leading to amenorrhea during frequent breastfeeding.","kind":"recall","origin":"ai"},{"id":"hrp1-suckling-prolactin-oxytocin~ai-6","moduleId":"hrp1-suckling-prolactin-oxytocin","stem":"How does the suckling reflex relate to the action of oxytocin in parturition?","options":[{"id":"a","text":"Both involve dopamine inhibition"},{"id":"b","text":"Both stimulate myoepithelial contraction"},{"id":"c","text":"Both are regulated by the same hypothalamic nuclei"},{"id":"d","text":"Both promote milk synthesis"}],"answerId":"c","explanation":"Both the suckling reflex and parturition involve oxytocin release from the hypothalamus, regulated by similar neural pathways.","kind":"integration","linkedModuleIds":["hen1-oxytocin-reflexes"],"origin":"ai"},{"id":"hrp1-suckling-prolactin-oxytocin~ai-7","moduleId":"hrp1-suckling-prolactin-oxytocin","stem":"Which of the following best connects the role of prolactin in lactation to its effects on growth hormone regulation?","options":[{"id":"a","text":"Prolactin enhances growth hormone secretion"},{"id":"b","text":"Prolactin suppresses growth hormone release"},{"id":"c","text":"Prolactin has no effect on growth hormone"},{"id":"d","text":"Prolactin and growth hormone are released simultaneously"}],"answerId":"b","explanation":"Prolactin can suppress pulsatile GnRH, which indirectly affects growth hormone regulation.","kind":"integration","linkedModuleIds":["growth-hormone-prolactin-drugs"],"origin":"ai"}],"hrp1-gestational-progesterone-estrogen":[{"id":"hrp1-gestational-progesterone-estrogen~ai-0","moduleId":"hrp1-gestational-progesterone-estrogen","stem":"What is the primary role of progesterone during pregnancy?","options":[{"id":"a","text":"Stimulates uterine contractions"},{"id":"b","text":"Maintains decidua and supports immune tolerance"},{"id":"c","text":"Promotes fetal growth directly"},{"id":"d","text":"Increases maternal metabolic rate"}],"answerId":"b","explanation":"Progesterone is crucial for maintaining the decidua, supporting immune tolerance, and reducing myometrial excitability.","kind":"recall","origin":"ai"},{"id":"hrp1-gestational-progesterone-estrogen~ai-1","moduleId":"hrp1-gestational-progesterone-estrogen","stem":"Which fetal precursor is essential for placental estrogen production?","options":[{"id":"a","text":"Maternal estradiol"},{"id":"b","text":"Fetal DHEA-S"},{"id":"c","text":"Maternal progesterone"},{"id":"d","text":"Fetal cortisol"}],"answerId":"b","explanation":"Fetal DHEA-S is a key precursor for the placenta to synthesize estrogens.","kind":"recall","origin":"ai"},{"id":"hrp1-gestational-progesterone-estrogen~ai-2","moduleId":"hrp1-gestational-progesterone-estrogen","stem":"How does progesterone contribute to uterine quiescence during pregnancy?","options":[{"id":"a","text":"By increasing oxytocin receptor expression"},{"id":"b","text":"By reducing contractile signaling"},{"id":"c","text":"By promoting prostaglandin synthesis"},{"id":"d","text":"By enhancing uterine blood flow"}],"answerId":"b","explanation":"Progesterone reduces contractile signaling, leading to uterine quiescence.","kind":"mechanism","origin":"ai"},{"id":"hrp1-gestational-progesterone-estrogen~ai-3","moduleId":"hrp1-gestational-progesterone-estrogen","stem":"Which of the following statements about placental estrogen production is true?","options":[{"id":"a","text":"The placenta synthesizes all estrogen precursors independently."},{"id":"b","text":"The placenta relies heavily on fetal/maternal androgen precursors."},{"id":"c","text":"Estrogen production is solely dependent on maternal cholesterol."},{"id":"d","text":"The placenta can produce sufficient CYP17 for precursor synthesis."}],"answerId":"b","explanation":"The placenta relies on fetal/maternal androgen precursors due to its limited CYP17 activity.","kind":"trap","origin":"ai"},{"id":"hrp1-gestational-progesterone-estrogen~ai-4","moduleId":"hrp1-gestational-progesterone-estrogen","stem":"What clinical finding is associated with high levels of gestational estrogen?","options":[{"id":"a","text":"Decreased uterine blood flow"},{"id":"b","text":"Progressive uterine and breast growth"},{"id":"c","text":"Increased myometrial excitability"},{"id":"d","text":"Reduced breast ductal development"}],"answerId":"b","explanation":"High levels of gestational estrogen drive uterine and breast growth.","kind":"clinical","origin":"ai"},{"id":"hrp1-gestational-progesterone-estrogen~ai-5","moduleId":"hrp1-gestational-progesterone-estrogen","stem":"How does the placenta utilize maternal cholesterol?","options":[{"id":"a","text":"To synthesize all steroid hormones independently"},{"id":"b","text":"As a precursor for progesterone synthesis"},{"id":"c","text":"To produce fetal adrenal hormones"},{"id":"d","text":"For direct fetal energy metabolism"}],"answerId":"b","explanation":"The placenta uses maternal cholesterol primarily to synthesize progesterone.","kind":"mechanism","origin":"ai"},{"id":"hrp1-gestational-progesterone-estrogen~ai-6","moduleId":"hrp1-gestational-progesterone-estrogen","stem":"Which hormone's role in maternal metabolic adaptation is directly linked to placental function?","options":[{"id":"a","text":"Cortisol"},{"id":"b","text":"hCG"},{"id":"c","text":"hPL"},{"id":"d","text":"Progesterone"}],"answerId":"c","explanation":"hPL (human placental lactogen) plays a significant role in maternal metabolic adaptation during pregnancy.","kind":"integration","linkedModuleIds":["hrp1-hpl-placental-gh-crh"],"origin":"ai"},{"id":"hrp1-gestational-progesterone-estrogen~ai-7","moduleId":"hrp1-gestational-progesterone-estrogen","stem":"What is a key relationship between placental development and its endocrine function?","options":[{"id":"a","text":"Placental growth is independent of fetal development."},{"id":"b","text":"Endocrine function is solely dependent on maternal hormones."},{"id":"c","text":"Placental development influences the synthesis of pregnancy hormones."},{"id":"d","text":"Fetal adrenal function does not affect placental hormone production."}],"answerId":"c","explanation":"Placental development is crucial for the synthesis of hormones necessary for maintaining pregnancy.","kind":"integration","linkedModuleIds":["hrp1-placenta-endocrine-hcg"],"origin":"ai"}],"hrp1-trauma-asd-ptsd-first-aid":[{"id":"hrp1-trauma-asd-ptsd-first-aid~ai-0","moduleId":"hrp1-trauma-asd-ptsd-first-aid","stem":"What is a key feature distinguishing acute stress disorder from PTSD?","options":[{"id":"a","text":"Symptoms last longer than one month"},{"id":"b","text":"Presence of dissociation"},{"id":"c","text":"Symptoms develop immediately after trauma"},{"id":"d","text":"Re-experiencing the trauma"}],"answerId":"a","explanation":"Acute stress disorder occurs within the first month after trauma, while PTSD requires symptoms to persist beyond one month.","kind":"recall","origin":"ai"},{"id":"hrp1-trauma-asd-ptsd-first-aid~ai-1","moduleId":"hrp1-trauma-asd-ptsd-first-aid","stem":"Which of the following is a primary goal of psychological first aid?","options":[{"id":"a","text":"Encourage detailed recounting of the trauma"},{"id":"b","text":"Provide safety and support"},{"id":"c","text":"Facilitate immediate therapy"},{"id":"d","text":"Assess for long-term mental health needs"}],"answerId":"b","explanation":"Psychological first aid focuses on providing safety and support without forcing individuals to disclose trauma details.","kind":"trap","origin":"ai"},{"id":"hrp1-trauma-asd-ptsd-first-aid~ai-2","moduleId":"hrp1-trauma-asd-ptsd-first-aid","stem":"What symptom cluster is most indicative of PTSD?","options":[{"id":"a","text":"Temporary distress"},{"id":"b","text":"Hyperarousal"},{"id":"c","text":"Avoidance"},{"id":"d","text":"Dissociation"}],"answerId":"b","explanation":"Hyperarousal is a persistent symptom of PTSD, which includes heightened alertness and reactivity.","kind":"clinical","origin":"ai"},{"id":"hrp1-trauma-asd-ptsd-first-aid~ai-3","moduleId":"hrp1-trauma-asd-ptsd-first-aid","stem":"Which developmental factor is crucial in assessing trauma in children?","options":[{"id":"a","text":"Cognitive ability"},{"id":"b","text":"Play behavior"},{"id":"c","text":"Physical health"},{"id":"d","text":"Family income"}],"answerId":"b","explanation":"Children express trauma through play and behavior, which are important indicators of their psychological state.","kind":"recall","origin":"ai"},{"id":"hrp1-trauma-asd-ptsd-first-aid~ai-4","moduleId":"hrp1-trauma-asd-ptsd-first-aid","stem":"What is the mechanism behind persistent trauma symptoms?","options":[{"id":"a","text":"Increased cortisol production"},{"id":"b","text":"Threat memory and arousal persistence"},{"id":"c","text":"Dopamine dysregulation"},{"id":"d","text":"Neurotransmitter depletion"}],"answerId":"b","explanation":"Threat memory and arousal can persist even after the danger has ended, leading to ongoing symptoms.","kind":"mechanism","origin":"ai"},{"id":"hrp1-trauma-asd-ptsd-first-aid~ai-5","moduleId":"hrp1-trauma-asd-ptsd-first-aid","stem":"How does acute stress disorder differ from child maltreatment responses?","options":[{"id":"a","text":"Both require immediate therapy"},{"id":"b","text":"Only child maltreatment involves avoidance"},{"id":"c","text":"Acute stress disorder symptoms are temporary"},{"id":"d","text":"Child maltreatment is always identifiable"}],"answerId":"c","explanation":"Acute stress disorder symptoms are typically temporary, while child maltreatment responses can be more complex and long-lasting.","kind":"integration","linkedModuleIds":["hrp1-child-maltreatment-recognition"],"origin":"ai"},{"id":"hrp1-trauma-asd-ptsd-first-aid~ai-6","moduleId":"hrp1-trauma-asd-ptsd-first-aid","stem":"In the context of trauma, how can knowledge of drug absorption routes be relevant?","options":[{"id":"a","text":"To determine the best route for trauma medications"},{"id":"b","text":"To assess psychological effects of drugs"},{"id":"c","text":"To evaluate long-term drug impacts"},{"id":"d","text":"To understand drug interactions in trauma care"}],"answerId":"a","explanation":"Understanding drug absorption routes is essential for selecting the most effective administration method for medications in trauma care.","kind":"integration","linkedModuleIds":["drug-absorption-routes"],"origin":"ai"}],"hrp1-male-hypogonadism-evaluation":[{"id":"hrp1-male-hypogonadism-evaluation~ai-0","moduleId":"hrp1-male-hypogonadism-evaluation","stem":"What is the most reliable method to confirm a diagnosis of hypogonadism?","options":[{"id":"a","text":"One random afternoon testosterone measurement"},{"id":"b","text":"Repeated morning testosterone measurements"},{"id":"c","text":"Single evening testosterone measurement"},{"id":"d","text":"24-hour urine testosterone collection"}],"answerId":"b","explanation":"Hypogonadism requires consistent low testosterone levels measured in the morning, as testosterone levels vary throughout the day.","kind":"recall","origin":"ai"},{"id":"hrp1-male-hypogonadism-evaluation~ai-1","moduleId":"hrp1-male-hypogonadism-evaluation","stem":"In a patient with low testosterone and elevated LH and FSH, what is the likely cause of hypogonadism?","options":[{"id":"a","text":"Hypothalamic dysfunction"},{"id":"b","text":"Pituitary adenoma"},{"id":"c","text":"Primary testicular failure"},{"id":"d","text":"Functional suppression due to obesity"}],"answerId":"c","explanation":"Elevated LH and FSH indicate that the testes are not responding to gonadotropins, suggesting primary testicular failure.","kind":"mechanism","origin":"ai"},{"id":"hrp1-male-hypogonadism-evaluation~ai-2","moduleId":"hrp1-male-hypogonadism-evaluation","stem":"Which of the following symptoms is most consistent with androgen deficiency?","options":[{"id":"a","text":"Increased libido"},{"id":"b","text":"Weight gain"},{"id":"c","text":"Low libido"},{"id":"d","text":"Increased energy levels"}],"answerId":"c","explanation":"Low libido is a classic symptom of androgen deficiency in men.","kind":"recall","origin":"ai"},{"id":"hrp1-male-hypogonadism-evaluation~ai-3","moduleId":"hrp1-male-hypogonadism-evaluation","stem":"What is a potential consequence of testosterone therapy in a man seeking fertility?","options":[{"id":"a","text":"Increased sperm production"},{"id":"b","text":"Suppression of spermatogenesis"},{"id":"c","text":"Enhanced libido"},{"id":"d","text":"Improved testicular size"}],"answerId":"b","explanation":"Testosterone therapy can suppress LH and FSH, leading to decreased spermatogenesis and infertility.","kind":"trap","origin":"ai"},{"id":"hrp1-male-hypogonadism-evaluation~ai-4","moduleId":"hrp1-male-hypogonadism-evaluation","stem":"How does testosterone therapy affect hematocrit levels?","options":[{"id":"a","text":"Decreases hematocrit"},{"id":"b","text":"No effect on hematocrit"},{"id":"c","text":"Increases hematocrit"},{"id":"d","text":"Causes hemolysis"}],"answerId":"c","explanation":"Testosterone therapy can stimulate erythropoiesis, leading to increased hematocrit levels.","kind":"mechanism","origin":"ai"},{"id":"hrp1-male-hypogonadism-evaluation~ai-5","moduleId":"hrp1-male-hypogonadism-evaluation","stem":"A 45-year-old man presents with erectile dysfunction and low testosterone. Which treatment option is most appropriate considering his condition?","options":[{"id":"a","text":"Testosterone replacement therapy"},{"id":"b","text":"Sildenafil"},{"id":"c","text":"Clomiphene citrate"},{"id":"d","text":"Vacuum erection device"}],"answerId":"b","explanation":"Sildenafil is a PDE5 inhibitor that can improve erectile function, especially in the context of low testosterone.","kind":"integration","linkedModuleIds":["hrp1-ed-treatment-pde5"],"origin":"ai"},{"id":"hrp1-male-hypogonadism-evaluation~ai-6","moduleId":"hrp1-male-hypogonadism-evaluation","stem":"In a patient with hypogonadism, which finding would suggest a primary testicular cause?","options":[{"id":"a","text":"Low testosterone with high LH and FSH"},{"id":"b","text":"Low testosterone with low LH and FSH"},{"id":"c","text":"Normal testosterone with low LH and FSH"},{"id":"d","text":"Normal testosterone with high LH and FSH"}],"answerId":"a","explanation":"High LH and FSH with low testosterone indicates that the testes are not producing testosterone adequately, suggesting primary testicular failure.","kind":"integration","linkedModuleIds":["hrp1-erectile-physiology-evaluation"],"origin":"ai"}],"hrp1-erectile-physiology-evaluation":[{"id":"hrp1-erectile-physiology-evaluation~ai-0","moduleId":"hrp1-erectile-physiology-evaluation","stem":"What is the primary mechanism by which nitric oxide (NO) induces penile erection?","options":[{"id":"a","text":"Inhibition of phosphodiesterase-5"},{"id":"b","text":"Activation of guanylyl cyclase"},{"id":"c","text":"Increased sympathetic tone"},{"id":"d","text":"Decreased arterial inflow"}],"answerId":"b","explanation":"Nitric oxide activates guanylyl cyclase, leading to increased cGMP and smooth muscle relaxation, which facilitates erection.","kind":"mechanism","origin":"ai"},{"id":"hrp1-erectile-physiology-evaluation~ai-1","moduleId":"hrp1-erectile-physiology-evaluation","stem":"Which of the following is a common psychological contributor to erectile dysfunction?","options":[{"id":"a","text":"Diabetes mellitus"},{"id":"b","text":"Hypertension"},{"id":"c","text":"Anxiety"},{"id":"d","text":"Hyperlipidemia"}],"answerId":"c","explanation":"Anxiety is a recognized psychological factor that can contribute to erectile dysfunction.","kind":"recall","origin":"ai"},{"id":"hrp1-erectile-physiology-evaluation~ai-2","moduleId":"hrp1-erectile-physiology-evaluation","stem":"A patient presents with gradual erectile dysfunction and has a history of hypertension and hyperlipidemia. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Psychogenic factors"},{"id":"b","text":"Endothelial dysfunction"},{"id":"c","text":"Hormonal imbalance"},{"id":"d","text":"Structural abnormalities"}],"answerId":"b","explanation":"Endothelial dysfunction due to vascular risk factors like hypertension and hyperlipidemia is a common cause of gradual erectile dysfunction.","kind":"clinical","origin":"ai"},{"id":"hrp1-erectile-physiology-evaluation~ai-3","moduleId":"hrp1-erectile-physiology-evaluation","stem":"Which of the following findings suggests a psychogenic component to erectile dysfunction?","options":[{"id":"a","text":"Preserved spontaneous erections"},{"id":"b","text":"Gradual onset of ED"},{"id":"c","text":"Presence of metabolic syndrome"},{"id":"d","text":"History of prostate surgery"}],"answerId":"a","explanation":"Preserved spontaneous erections with situational difficulty indicates a psychogenic or contextual component to erectile dysfunction.","kind":"clinical","origin":"ai"},{"id":"hrp1-erectile-physiology-evaluation~ai-4","moduleId":"hrp1-erectile-physiology-evaluation","stem":"What is a common misconception regarding the causes of erectile dysfunction?","options":[{"id":"a","text":"All ED is purely psychological"},{"id":"b","text":"ED can be caused by medications"},{"id":"c","text":"ED can indicate cardiovascular disease"},{"id":"d","text":"ED can have mixed etiologies"}],"answerId":"a","explanation":"It is a misconception that all erectile dysfunction is purely psychological; most cases have biopsychosocial and vascular contributors.","kind":"trap","origin":"ai"},{"id":"hrp1-erectile-physiology-evaluation~ai-5","moduleId":"hrp1-erectile-physiology-evaluation","stem":"How do organic nitrates affect erectile function, particularly in patients using PDE5 inhibitors?","options":[{"id":"a","text":"They enhance the effects of PDE5 inhibitors"},{"id":"b","text":"They can cause severe hypotension"},{"id":"c","text":"They have no effect on erectile function"},{"id":"d","text":"They increase cGMP levels directly"}],"answerId":"b","explanation":"Organic nitrates can cause severe hypotension when used with PDE5 inhibitors due to their vasodilatory effects.","kind":"integration","linkedModuleIds":["organic-nitrates"],"origin":"ai"},{"id":"hrp1-erectile-physiology-evaluation~ai-6","moduleId":"hrp1-erectile-physiology-evaluation","stem":"In assessing a patient with erectile dysfunction, which factor is most important to evaluate for cardiovascular risk?","options":[{"id":"a","text":"Psychological history"},{"id":"b","text":"Blood pressure"},{"id":"c","text":"Penile structural abnormalities"},{"id":"d","text":"Hormonal levels"}],"answerId":"b","explanation":"Blood pressure is a critical factor to assess as erectile dysfunction can be an early marker of cardiovascular disease.","kind":"integration","linkedModuleIds":["hrp1-male-hypogonadism-evaluation"],"origin":"ai"}],"hrp1-ed-treatment-pde5":[{"id":"hrp1-ed-treatment-pde5~ai-0","moduleId":"hrp1-ed-treatment-pde5","stem":"What is the primary mechanism of action of PDE5 inhibitors in treating erectile dysfunction?","options":[{"id":"a","text":"They increase testosterone levels."},{"id":"b","text":"They inhibit cGMP breakdown."},{"id":"c","text":"They directly stimulate nitric oxide release."},{"id":"d","text":"They enhance libido."}],"answerId":"b","explanation":"PDE5 inhibitors work by inhibiting the breakdown of cGMP, thus prolonging its effects in the presence of nitric oxide during sexual stimulation.","kind":"mechanism","origin":"ai"},{"id":"hrp1-ed-treatment-pde5~ai-1","moduleId":"hrp1-ed-treatment-pde5","stem":"Which of the following is a common side effect of PDE5 inhibitors?","options":[{"id":"a","text":"Severe hypotension"},{"id":"b","text":"Nausea"},{"id":"c","text":"Headache"},{"id":"d","text":"Bradycardia"}],"answerId":"c","explanation":"Headache is a well-documented side effect of PDE5 inhibitors due to vasodilation effects.","kind":"recall","origin":"ai"},{"id":"hrp1-ed-treatment-pde5~ai-2","moduleId":"hrp1-ed-treatment-pde5","stem":"Why are nitrates contraindicated in patients taking PDE5 inhibitors?","options":[{"id":"a","text":"They cause increased libido."},{"id":"b","text":"They can lead to severe hypotension."},{"id":"c","text":"They enhance PDE5 inhibitor efficacy."},{"id":"d","text":"They block cGMP production."}],"answerId":"b","explanation":"Concurrent use of nitrates with PDE5 inhibitors can cause profound hypotension due to excessive vasodilation.","kind":"trap","origin":"ai"},{"id":"hrp1-ed-treatment-pde5~ai-3","moduleId":"hrp1-ed-treatment-pde5","stem":"What clinical finding would suggest a patient is not responding to PDE5 inhibitors due to lack of sexual stimulation?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Severe headache"},{"id":"c","text":"No erection despite medication"},{"id":"d","text":"Flushing of the face"}],"answerId":"c","explanation":"PDE5 inhibitors amplify the cGMP response to nitric oxide, which requires sexual stimulation; without it, there is no erection.","kind":"clinical","origin":"ai"},{"id":"hrp1-ed-treatment-pde5~ai-4","moduleId":"hrp1-ed-treatment-pde5","stem":"Which treatment option is appropriate for a patient who does not respond to oral PDE5 inhibitors?","options":[{"id":"a","text":"Increased dosage of PDE5 inhibitor"},{"id":"b","text":"Intracavernosal therapy"},{"id":"c","text":"Testosterone replacement therapy"},{"id":"d","text":"Counseling alone"}],"answerId":"b","explanation":"Intracavernosal therapy is an alternative treatment for patients who do not respond to oral PDE5 inhibitors.","kind":"recall","origin":"ai"},{"id":"hrp1-ed-treatment-pde5~ai-5","moduleId":"hrp1-ed-treatment-pde5","stem":"How does the mechanism of PDE5 inhibitors relate to the physiological evaluation of erectile dysfunction?","options":[{"id":"a","text":"They directly stimulate the erectile tissue."},{"id":"b","text":"They enhance the cGMP response to nitric oxide."},{"id":"c","text":"They increase blood flow to the penis without stimulation."},{"id":"d","text":"They are effective regardless of sexual stimulation."}],"answerId":"b","explanation":"PDE5 inhibitors enhance the cGMP response to nitric oxide, which is crucial in the physiological evaluation of erectile dysfunction.","kind":"integration","linkedModuleIds":["hrp1-erectile-physiology-evaluation"],"origin":"ai"},{"id":"hrp1-ed-treatment-pde5~ai-6","moduleId":"hrp1-ed-treatment-pde5","stem":"Which anatomical consideration is important when discussing PDE5 inhibitors and erectile function?","options":[{"id":"a","text":"Prostate size"},{"id":"b","text":"Blood supply to the rectus sheath"},{"id":"c","text":"Nerve supply to the penis"},{"id":"d","text":"Testicular volume"}],"answerId":"c","explanation":"The nerve supply to the penis is critical for the physiological response that PDE5 inhibitors amplify.","kind":"integration","linkedModuleIds":["abdominal-wall-rectus-sheath"],"origin":"ai"}],"hrp1-premature-ejaculation":[{"id":"hrp1-premature-ejaculation~ai-0","moduleId":"hrp1-premature-ejaculation","stem":"What is a key characteristic of premature ejaculation (PE)?","options":[{"id":"a","text":"Persistently short latency"},{"id":"b","text":"Inability to achieve erection"},{"id":"c","text":"Increased sexual desire"},{"id":"d","text":"Prolonged ejaculation time"}],"answerId":"a","explanation":"Premature ejaculation is defined by persistently short latency, reduced perceived control, and associated distress.","kind":"recall","origin":"ai"},{"id":"hrp1-premature-ejaculation~ai-1","moduleId":"hrp1-premature-ejaculation","stem":"Which of the following is a common treatment for acquired premature ejaculation?","options":[{"id":"a","text":"Topical anesthetics"},{"id":"b","text":"Increased sexual frequency"},{"id":"c","text":"Hormonal therapy"},{"id":"d","text":"Surgical intervention"}],"answerId":"a","explanation":"Topical anesthetics are commonly used to help manage acquired premature ejaculation.","kind":"recall","origin":"ai"},{"id":"hrp1-premature-ejaculation~ai-2","moduleId":"hrp1-premature-ejaculation","stem":"What mechanism underlies the ejaculatory reflex in premature ejaculation?","options":[{"id":"a","text":"Increased testosterone levels"},{"id":"b","text":"Neurobiological factors"},{"id":"c","text":"Enhanced blood flow"},{"id":"d","text":"Psychological stress"}],"answerId":"b","explanation":"The ejaculatory reflex timing is influenced by neurobiology, arousal, control, and context.","kind":"mechanism","origin":"ai"},{"id":"hrp1-premature-ejaculation~ai-3","moduleId":"hrp1-premature-ejaculation","stem":"A patient presents with new rapid ejaculation after previously normal function. What should be evaluated?","options":[{"id":"a","text":"Normal sexual variability"},{"id":"b","text":"Psychosexual factors"},{"id":"c","text":"Increased libido"},{"id":"d","text":"Surgical history"}],"answerId":"b","explanation":"Acquired premature ejaculation warrants evaluation for new medical or psychosexual factors.","kind":"clinical","origin":"ai"},{"id":"hrp1-premature-ejaculation~ai-4","moduleId":"hrp1-premature-ejaculation","stem":"Which of the following statements about the diagnosis of PE is true?","options":[{"id":"a","text":"A short measured latency alone is sufficient"},{"id":"b","text":"Control and context are also required"},{"id":"c","text":"It is always lifelong"},{"id":"d","text":"It cannot be treated with medications"}],"answerId":"b","explanation":"Diagnosis of premature ejaculation requires consideration of control, persistence, distress, and context, not just latency.","kind":"trap","origin":"ai"},{"id":"hrp1-premature-ejaculation~ai-5","moduleId":"hrp1-premature-ejaculation","stem":"How might premature ejaculation relate to erectile dysfunction treatment?","options":[{"id":"a","text":"Both conditions are treated with the same medications"},{"id":"b","text":"PE can be a side effect of ED medications"},{"id":"c","text":"PE is unrelated to erectile function"},{"id":"d","text":"Both conditions share psychological factors"}],"answerId":"d","explanation":"Both premature ejaculation and erectile dysfunction can be influenced by psychological factors, necessitating a comprehensive approach to treatment.","kind":"integration","linkedModuleIds":["hrp1-ed-treatment-pde5"],"origin":"ai"},{"id":"hrp1-premature-ejaculation~ai-6","moduleId":"hrp1-premature-ejaculation","stem":"What common factor should be assessed in both premature ejaculation and erectile dysfunction?","options":[{"id":"a","text":"Hormonal levels"},{"id":"b","text":"Psychosexual factors"},{"id":"c","text":"Anatomical abnormalities"},{"id":"d","text":"Age-related changes"}],"answerId":"b","explanation":"Psychosexual factors are important to consider in both conditions as they can significantly impact sexual function.","kind":"integration","linkedModuleIds":["hrp1-erectile-physiology-evaluation"],"origin":"ai"}],"hrp1-sexual-response-models":[{"id":"hrp1-sexual-response-models~ai-0","moduleId":"hrp1-sexual-response-models","stem":"Which phase of the sexual response model includes subjective release and rhythmic pelvic contractions?","options":[{"id":"a","text":"Excitement"},{"id":"b","text":"Plateau"},{"id":"c","text":"Orgasm"},{"id":"d","text":"Resolution"}],"answerId":"c","explanation":"The orgasm phase is characterized by rhythmic pelvic contractions and a subjective feeling of release.","kind":"recall","origin":"ai"},{"id":"hrp1-sexual-response-models~ai-1","moduleId":"hrp1-sexual-response-models","stem":"What is a key feature of the male refractory period after orgasm?","options":[{"id":"a","text":"Increased sexual desire"},{"id":"b","text":"Temporary reduced responsiveness"},{"id":"c","text":"Enhanced genital sensitivity"},{"id":"d","text":"Immediate ability to achieve erection"}],"answerId":"b","explanation":"The male refractory period is characterized by a temporary reduction in sexual responsiveness following orgasm.","kind":"recall","origin":"ai"},{"id":"hrp1-sexual-response-models~ai-2","moduleId":"hrp1-sexual-response-models","stem":"Which model emphasizes the importance of desire in the sexual response?","options":[{"id":"a","text":"Masters–Johnson"},{"id":"b","text":"Kaplan"},{"id":"c","text":"Bancroft"},{"id":"d","text":"Meston"}],"answerId":"b","explanation":"Kaplan's model emphasizes the phases of desire, arousal, and orgasm in sexual response.","kind":"recall","origin":"ai"},{"id":"hrp1-sexual-response-models~ai-3","moduleId":"hrp1-sexual-response-models","stem":"Which statement best describes the variability of sexual responses?","options":[{"id":"a","text":"They always follow a linear sequence."},{"id":"b","text":"They are identical for all individuals."},{"id":"c","text":"They can vary based on context and individual differences."},{"id":"d","text":"They are solely determined by physiological factors."}],"answerId":"c","explanation":"Sexual responses are variable and context-dependent, influenced by numerous biopsychosocial factors.","kind":"trap","origin":"ai"},{"id":"hrp1-sexual-response-models~ai-4","moduleId":"hrp1-sexual-response-models","stem":"How does central desire interact with genital responses during arousal?","options":[{"id":"a","text":"It inhibits genital vasocongestion."},{"id":"b","text":"It solely dictates the level of lubrication."},{"id":"c","text":"It combines with autonomic responses to enhance arousal."},{"id":"d","text":"It has no effect on genital responses."}],"answerId":"c","explanation":"Central desire interacts with autonomic responses to facilitate genital vasocongestion and lubrication during arousal.","kind":"mechanism","origin":"ai"},{"id":"hrp1-sexual-response-models~ai-5","moduleId":"hrp1-sexual-response-models","stem":"A patient presents with erectile dysfunction and low sexual desire. Which treatment approach should be considered based on biopsychosocial factors?","options":[{"id":"a","text":"Only pharmacological treatment"},{"id":"b","text":"Only psychological counseling"},{"id":"c","text":"Combination of pharmacological and psychological approaches"},{"id":"d","text":"Surgical intervention only"}],"answerId":"c","explanation":"A comprehensive approach that includes both pharmacological and psychological treatment is essential for addressing erectile dysfunction and low sexual desire.","kind":"integration","linkedModuleIds":["hrp1-ed-treatment-pde5"],"origin":"ai"},{"id":"hrp1-sexual-response-models~ai-6","moduleId":"hrp1-sexual-response-models","stem":"In evaluating erectile dysfunction, which aspect should be assessed alongside physiological factors?","options":[{"id":"a","text":"Only medical history"},{"id":"b","text":"Only physical examination"},{"id":"c","text":"Psychosocial factors"},{"id":"d","text":"Age alone"}],"answerId":"c","explanation":"Psychosocial factors are crucial in the evaluation of erectile dysfunction, as they can significantly impact sexual health.","kind":"integration","linkedModuleIds":["hrp1-erectile-physiology-evaluation"],"origin":"ai"}],"hrp1-labor-stages-mechanics":[{"id":"hrp1-labor-stages-mechanics~ai-0","moduleId":"hrp1-labor-stages-mechanics","stem":"What defines true labor?","options":[{"id":"a","text":"Regular painful contractions"},{"id":"b","text":"Cervical dilation only"},{"id":"c","text":"Fetal movement"},{"id":"d","text":"Maternal fatigue"}],"answerId":"a","explanation":"True labor is characterized by regular painful contractions that lead to progressive cervical change.","kind":"recall","origin":"ai"},{"id":"hrp1-labor-stages-mechanics~ai-1","moduleId":"hrp1-labor-stages-mechanics","stem":"During which stage of labor does full cervical dilation occur?","options":[{"id":"a","text":"First stage"},{"id":"b","text":"Second stage"},{"id":"c","text":"Third stage"},{"id":"d","text":"Fourth stage"}],"answerId":"a","explanation":"The first stage of labor extends to full cervical dilation.","kind":"recall","origin":"ai"},{"id":"hrp1-labor-stages-mechanics~ai-2","moduleId":"hrp1-labor-stages-mechanics","stem":"What is the primary mechanism by which contractions aid in labor?","options":[{"id":"a","text":"Increased blood flow"},{"id":"b","text":"Coordinated uterine force"},{"id":"c","text":"Fetal positioning"},{"id":"d","text":"Maternal pushing effort"}],"answerId":"b","explanation":"Coordinated uterine force moves the fetal head through the pelvic axis during labor.","kind":"mechanism","origin":"ai"},{"id":"hrp1-labor-stages-mechanics~ai-3","moduleId":"hrp1-labor-stages-mechanics","stem":"Which cardinal movement occurs immediately after fetal extension during delivery?","options":[{"id":"a","text":"Engagement"},{"id":"b","text":"Descent"},{"id":"c","text":"Restitution"},{"id":"d","text":"Expulsion"}],"answerId":"c","explanation":"Restitution follows extension as the fetal head rotates to align with the back and front of the pelvis.","kind":"recall","origin":"ai"},{"id":"hrp1-labor-stages-mechanics~ai-4","moduleId":"hrp1-labor-stages-mechanics","stem":"What is a common trap in diagnosing true labor?","options":[{"id":"a","text":"Painful contractions alone indicate true labor"},{"id":"b","text":"Cervical effacement is not necessary"},{"id":"c","text":"Fetal heart rate is not relevant"},{"id":"d","text":"Maternal anxiety affects contractions"}],"answerId":"a","explanation":"Painful contractions alone do not confirm true labor; progressive cervical change is essential.","kind":"trap","origin":"ai"},{"id":"hrp1-labor-stages-mechanics~ai-5","moduleId":"hrp1-labor-stages-mechanics","stem":"Which sign indicates true labor during examination?","options":[{"id":"a","text":"Leopold maneuvers"},{"id":"b","text":"Progressive cervical dilation"},{"id":"c","text":"Fetal heart rate monitoring"},{"id":"d","text":"Maternal blood pressure"}],"answerId":"b","explanation":"Progressive cervical dilation is a key sign of true labor.","kind":"recall","origin":"ai"},{"id":"hrp1-labor-stages-mechanics~ai-6","moduleId":"hrp1-labor-stages-mechanics","stem":"How does maternal adaptation during pregnancy relate to labor mechanics?","options":[{"id":"a","text":"Increased blood volume affects contractions"},{"id":"b","text":"Hormonal changes enhance fetal movement"},{"id":"c","text":"Pelvic changes facilitate labor"},{"id":"d","text":"Nutritional status impacts fetal size"}],"answerId":"c","explanation":"Maternal anatomic changes, including pelvic adjustments, facilitate the mechanics of labor.","kind":"integration","linkedModuleIds":["hrp1-maternal-adaptation-pregnancy"],"origin":"ai"},{"id":"hrp1-labor-stages-mechanics~ai-7","moduleId":"hrp1-labor-stages-mechanics","stem":"What role does acute inflammation play in the labor process?","options":[{"id":"a","text":"Increases uterine contractions"},{"id":"b","text":"Promotes cervical dilation"},{"id":"c","text":"Enhances fetal positioning"},{"id":"d","text":"Facilitates placental delivery"}],"answerId":"b","explanation":"Acute inflammation can promote cervical dilation, which is crucial for the progression of labor.","kind":"integration","linkedModuleIds":["acute-inflammation"],"origin":"ai"}],"hrp1-puerperium-postpartum-care":[{"id":"hrp1-puerperium-postpartum-care~ai-0","moduleId":"hrp1-puerperium-postpartum-care","stem":"What is the typical progression of lochia after childbirth?","options":[{"id":"a","text":"Rubra → serosa → alba"},{"id":"b","text":"Alba → serosa → rubra"},{"id":"c","text":"Serosa → alba → rubra"},{"id":"d","text":"Rubra → alba → serosa"}],"answerId":"a","explanation":"Lochia progresses from rubra (red) to serosa (pink) to alba (white) after delivery.","kind":"recall","origin":"ai"},{"id":"hrp1-puerperium-postpartum-care~ai-1","moduleId":"hrp1-puerperium-postpartum-care","stem":"Which of the following is a common cause of postpartum hemorrhage?","options":[{"id":"a","text":"Uterine atony"},{"id":"b","text":"Placenta previa"},{"id":"c","text":"Ectopic pregnancy"},{"id":"d","text":"Cervical laceration"}],"answerId":"a","explanation":"Uterine atony is the most common cause of postpartum hemorrhage due to failure of the uterus to contract effectively.","kind":"recall","origin":"ai"},{"id":"hrp1-puerperium-postpartum-care~ai-2","moduleId":"hrp1-puerperium-postpartum-care","stem":"A patient presents with a boggy enlarged uterus and heavy bleeding 24 hours postpartum. What is the most likely diagnosis?","options":[{"id":"a","text":"Uterine atony"},{"id":"b","text":"Retained placental tissue"},{"id":"c","text":"Uterine infection"},{"id":"d","text":"Cervical laceration"}],"answerId":"a","explanation":"A boggy uterus with heavy bleeding indicates uterine atony, which fails to compress vessels at the placental site.","kind":"clinical","origin":"ai"},{"id":"hrp1-puerperium-postpartum-care~ai-3","moduleId":"hrp1-puerperium-postpartum-care","stem":"What is the mechanism by which uterine contractions help prevent postpartum hemorrhage?","options":[{"id":"a","text":"Increase blood flow to the uterus"},{"id":"b","text":"Compress placental-site vessels"},{"id":"c","text":"Enhance uterine infection clearance"},{"id":"d","text":"Promote uterine relaxation"}],"answerId":"b","explanation":"Uterine contractions compress the vessels at the placental site to prevent excessive bleeding.","kind":"mechanism","origin":"ai"},{"id":"hrp1-puerperium-postpartum-care~ai-4","moduleId":"hrp1-puerperium-postpartum-care","stem":"Which of the following statements about postpartum bleeding is true?","options":[{"id":"a","text":"All postpartum bleeding is normal lochia"},{"id":"b","text":"Heavy bleeding requires urgent evaluation"},{"id":"c","text":"Lochia should always be foul-smelling"},{"id":"d","text":"Postpartum bleeding should not be monitored"}],"answerId":"b","explanation":"Heavy, increasing, or symptomatic bleeding requires urgent evaluation as it may indicate complications.","kind":"trap","origin":"ai"},{"id":"hrp1-puerperium-postpartum-care~ai-5","moduleId":"hrp1-puerperium-postpartum-care","stem":"How does the maternal cardiovascular system adapt during the puerperium to manage fluid shifts?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Decreased blood volume"},{"id":"c","text":"Increased systemic vascular resistance"},{"id":"d","text":"Increased plasma volume"}],"answerId":"a","explanation":"Increased heart rate helps to manage fluid shifts and maintain adequate perfusion during the postpartum period.","kind":"integration","linkedModuleIds":["hrp1-maternal-adaptation-pregnancy"],"origin":"ai"},{"id":"hrp1-puerperium-postpartum-care~ai-6","moduleId":"hrp1-puerperium-postpartum-care","stem":"What is a potential complication of postpartum infection that can affect the healing process?","options":[{"id":"a","text":"Increased uterine involution"},{"id":"b","text":"Delayed placental site healing"},{"id":"c","text":"Enhanced lactation"},{"id":"d","text":"Decreased risk of thrombosis"}],"answerId":"b","explanation":"Postpartum infection can delay the healing of the placental site, leading to complications.","kind":"integration","linkedModuleIds":["hrp1-labor-stages-mechanics"],"origin":"ai"}],"hrp1-neglect-emotional-abuse-safeguarding":[{"id":"hrp1-neglect-emotional-abuse-safeguarding~ai-0","moduleId":"hrp1-neglect-emotional-abuse-safeguarding","stem":"What is the primary characteristic of neglect in a caregiving context?","options":[{"id":"a","text":"Failure to provide emotional support"},{"id":"b","text":"Failure to meet basic physical needs"},{"id":"c","text":"Failure to ensure educational opportunities"},{"id":"d","text":"Failure to supervise adequately"}],"answerId":"b","explanation":"Neglect is defined as the persistent failure to meet basic physical, medical, educational, emotional, or safety needs.","kind":"recall","origin":"ai"},{"id":"hrp1-neglect-emotional-abuse-safeguarding~ai-1","moduleId":"hrp1-neglect-emotional-abuse-safeguarding","stem":"Which of the following is a sign of emotional abuse in children?","options":[{"id":"a","text":"Frequent physical injuries"},{"id":"b","text":"Poor academic performance"},{"id":"c","text":"Reports of persistent degradation"},{"id":"d","text":"Inconsistent attendance at school"}],"answerId":"c","explanation":"Children who experience emotional abuse may report persistent degradation or threats, which can occur without physical injury.","kind":"recall","origin":"ai"},{"id":"hrp1-neglect-emotional-abuse-safeguarding~ai-2","moduleId":"hrp1-neglect-emotional-abuse-safeguarding","stem":"How does repeated unmet needs in children lead to developmental issues?","options":[{"id":"a","text":"By causing immediate physical injuries"},{"id":"b","text":"By creating cumulative physical and developmental injury"},{"id":"c","text":"By fostering strong attachment to caregivers"},{"id":"d","text":"By promoting resilience in adverse conditions"}],"answerId":"b","explanation":"Repeated unmet needs can create cumulative physical and developmental injury, affecting a child's growth and emotional health.","kind":"mechanism","origin":"ai"},{"id":"hrp1-neglect-emotional-abuse-safeguarding~ai-3","moduleId":"hrp1-neglect-emotional-abuse-safeguarding","stem":"Which statement best describes the relationship between poverty and neglect?","options":[{"id":"a","text":"All poverty-related hardships indicate neglect"},{"id":"b","text":"Poverty is a form of neglect"},{"id":"c","text":"Neglect must be assessed independently of poverty"},{"id":"d","text":"Poverty always leads to neglect"}],"answerId":"c","explanation":"While poverty can contribute to neglect, it is essential to assess caregiver capacity, access, behavior, and available support to determine neglect.","kind":"trap","origin":"ai"},{"id":"hrp1-neglect-emotional-abuse-safeguarding~ai-4","moduleId":"hrp1-neglect-emotional-abuse-safeguarding","stem":"A child presents with growth faltering and missed care. What should be assessed first?","options":[{"id":"a","text":"Child's emotional state"},{"id":"b","text":"Caregiver's financial status"},{"id":"c","text":"Caregiver's capacity and access to resources"},{"id":"d","text":"Child's school attendance"}],"answerId":"c","explanation":"Assessing the caregiver's capacity and access to resources is crucial to understanding the context of the child's growth faltering.","kind":"clinical","origin":"ai"},{"id":"hrp1-neglect-emotional-abuse-safeguarding~ai-5","moduleId":"hrp1-neglect-emotional-abuse-safeguarding","stem":"In the context of child maltreatment, which of the following is a key consideration when assessing emotional abuse?","options":[{"id":"a","text":"Physical injuries present"},{"id":"b","text":"Child's academic performance"},{"id":"c","text":"Child's reports of threats and humiliation"},{"id":"d","text":"Caregiver's socioeconomic status"}],"answerId":"c","explanation":"The child's reports of threats and humiliation are critical indicators of emotional abuse, regardless of physical injuries.","kind":"integration","linkedModuleIds":["hrp1-child-maltreatment-recognition"],"origin":"ai"},{"id":"hrp1-neglect-emotional-abuse-safeguarding~ai-6","moduleId":"hrp1-neglect-emotional-abuse-safeguarding","stem":"When considering safeguarding pathways, which factor is most important to evaluate in cases of potential neglect?","options":[{"id":"a","text":"Child's age"},{"id":"b","text":"Caregiver's intent and capacity"},{"id":"c","text":"Community resources available"},{"id":"d","text":"Child's school performance"}],"answerId":"b","explanation":"Evaluating the caregiver's intent and capacity is essential to determine if neglect is occurring and how to best support the child.","kind":"integration","linkedModuleIds":["hrp1-child-sexual-abuse-response"],"origin":"ai"}],"hrp1-child-sexual-abuse-response":[{"id":"hrp1-child-sexual-abuse-response~ai-0","moduleId":"hrp1-child-sexual-abuse-response","stem":"Which of the following statements about child sexual abuse is true?","options":[{"id":"a","text":"A normal physical examination rules out sexual abuse."},{"id":"b","text":"Sexual abuse includes only contact acts."},{"id":"c","text":"Many abusive acts leave no visible injury."},{"id":"d","text":"All children who disclose abuse show behavioral changes."}],"answerId":"c","explanation":"Many abusive acts do not cause visible injuries, and a normal examination does not exclude the possibility of abuse.","kind":"trap","origin":"ai"},{"id":"hrp1-child-sexual-abuse-response~ai-1","moduleId":"hrp1-child-sexual-abuse-response","stem":"What is the most appropriate initial response when a child discloses sexual abuse?","options":[{"id":"a","text":"Promise confidentiality to the child."},{"id":"b","text":"Question the child repeatedly for details."},{"id":"c","text":"Reassure the child that they did the right thing by telling."},{"id":"d","text":"Dismiss the disclosure as a misunderstanding."}],"answerId":"c","explanation":"The child should be reassured that they did the right thing, and that adults will work to keep them safe.","kind":"clinical","origin":"ai"},{"id":"hrp1-child-sexual-abuse-response~ai-2","moduleId":"hrp1-child-sexual-abuse-response","stem":"Which of the following is a common finding in children who have experienced sexual abuse?","options":[{"id":"a","text":"Visible genital injuries."},{"id":"b","text":"Normal genital examination."},{"id":"c","text":"Consistent behavioral changes."},{"id":"d","text":"Pregnancy or STI symptoms."}],"answerId":"b","explanation":"A normal genital examination is common in cases of sexual abuse, as many acts do not leave visible injuries.","kind":"recall","origin":"ai"},{"id":"hrp1-child-sexual-abuse-response~ai-3","moduleId":"hrp1-child-sexual-abuse-response","stem":"What is the mechanism of trauma-informed response to a child disclosing abuse?","options":[{"id":"a","text":"Immediate reporting to authorities."},{"id":"b","text":"Belief, safety, minimal questioning, and specialist care."},{"id":"c","text":"Detailed forensic examination without delay."},{"id":"d","text":"Avoiding any emotional engagement with the child."}],"answerId":"b","explanation":"A trauma-informed response involves believing the child, ensuring their safety, and minimizing questioning to avoid further trauma.","kind":"mechanism","origin":"ai"},{"id":"hrp1-child-sexual-abuse-response~ai-4","moduleId":"hrp1-child-sexual-abuse-response","stem":"In the context of child sexual abuse, which of the following is a critical aspect of the clinical response?","options":[{"id":"a","text":"Providing a detailed explanation of the examination process."},{"id":"b","text":"Using open-ended prompts that are developmentally appropriate."},{"id":"c","text":"Encouraging the child to forget the incident."},{"id":"d","text":"Conducting a thorough interrogation of the child."}],"answerId":"b","explanation":"Using calm, nonjudgmental, and developmentally appropriate open-ended prompts is essential in responding to disclosures of abuse.","kind":"clinical","origin":"ai"},{"id":"hrp1-child-sexual-abuse-response~ai-5","moduleId":"hrp1-child-sexual-abuse-response","stem":"How does understanding child maltreatment types enhance the response to child sexual abuse?","options":[{"id":"a","text":"It allows for a more aggressive questioning approach."},{"id":"b","text":"It helps in identifying signs of abuse that may not be visible."},{"id":"c","text":"It reduces the need for mental health assessments."},{"id":"d","text":"It ensures that all disclosures are treated as false."}],"answerId":"b","explanation":"Understanding the various types of child maltreatment aids in recognizing signs of abuse that may not be immediately apparent.","kind":"integration","linkedModuleIds":["hrp1-child-maltreatment-recognition"],"origin":"ai"},{"id":"hrp1-child-sexual-abuse-response~ai-6","moduleId":"hrp1-child-sexual-abuse-response","stem":"What is a key consideration when assessing a child for sexual abuse in relation to their mental health?","options":[{"id":"a","text":"Mental health issues are irrelevant in abuse cases."},{"id":"b","text":"Assessing for suicidality is crucial."},{"id":"c","text":"Children will always exhibit clear signs of distress."},{"id":"d","text":"Mental health assessments can be postponed."}],"answerId":"b","explanation":"Assessing for mental health issues, including suicidality, is critical when evaluating a child for potential sexual abuse.","kind":"integration","linkedModuleIds":["hrp1-neglect-emotional-abuse-safeguarding"],"origin":"ai"}],"hrp1-child-maltreatment-recognition":[{"id":"hrp1-child-maltreatment-recognition~ai-0","moduleId":"hrp1-child-maltreatment-recognition","stem":"Which of the following is NOT a type of child maltreatment?","options":[{"id":"a","text":"Physical abuse"},{"id":"b","text":"Emotional abuse"},{"id":"c","text":"Educational neglect"},{"id":"d","text":"Sexual exploitation"}],"answerId":"c","explanation":"Educational neglect is not classified as a type of maltreatment; it falls under broader neglect categories.","kind":"recall","origin":"ai"},{"id":"hrp1-child-maltreatment-recognition~ai-1","moduleId":"hrp1-child-maltreatment-recognition","stem":"What is a common red flag indicating potential child maltreatment?","options":[{"id":"a","text":"Consistent injury history"},{"id":"b","text":"Injury incompatible with stated mechanism"},{"id":"c","text":"Age-appropriate growth"},{"id":"d","text":"Stable family dynamics"}],"answerId":"b","explanation":"Injuries that do not match the child's developmental stage or the explanation provided are red flags for maltreatment.","kind":"recall","origin":"ai"},{"id":"hrp1-child-maltreatment-recognition~ai-2","moduleId":"hrp1-child-maltreatment-recognition","stem":"Which mechanism explains the concern when a child presents with multiple injuries of different ages?","options":[{"id":"a","text":"Single traumatic event"},{"id":"b","text":"Inconsistent reporting"},{"id":"c","text":"Repeated trauma"},{"id":"d","text":"Normal developmental variations"}],"answerId":"c","explanation":"Multiple injuries of different ages may suggest repeated trauma, warranting further investigation.","kind":"mechanism","origin":"ai"},{"id":"hrp1-child-maltreatment-recognition~ai-3","moduleId":"hrp1-child-maltreatment-recognition","stem":"Why is it important to avoid concluding maltreatment based solely on risk factors?","options":[{"id":"a","text":"Risk factors are definitive proof"},{"id":"b","text":"Bias can harm families"},{"id":"c","text":"All risk factors indicate abuse"},{"id":"d","text":"Risk factors are always visible"}],"answerId":"b","explanation":"Risk factors guide vigilance but do not provide proof; misinterpretation can lead to unnecessary harm.","kind":"trap","origin":"ai"},{"id":"hrp1-child-maltreatment-recognition~ai-4","moduleId":"hrp1-child-maltreatment-recognition","stem":"In assessing a child for potential maltreatment, which approach is recommended?","options":[{"id":"a","text":"Immediate intervention without assessment"},{"id":"b","text":"Involve multidisciplinary safeguarding teams"},{"id":"c","text":"Focus solely on caregiver history"},{"id":"d","text":"Document findings only if abuse is suspected"}],"answerId":"b","explanation":"Involving trained multidisciplinary safeguarding teams ensures a comprehensive and sensitive approach to assessment.","kind":"clinical","origin":"ai"},{"id":"hrp1-child-maltreatment-recognition~ai-5","moduleId":"hrp1-child-maltreatment-recognition","stem":"How might knowledge of nutritional injury (linkedModuleIds: ['physical-nutritional-injury']) inform the assessment of a child suspected of maltreatment?","options":[{"id":"a","text":"It provides definitive proof of abuse"},{"id":"b","text":"It helps identify potential neglect in dietary needs"},{"id":"c","text":"It eliminates the need for a physical examination"},{"id":"d","text":"It focuses solely on physical injuries"}],"answerId":"b","explanation":"Understanding nutritional injury can help identify neglect in dietary needs, which is a form of maltreatment.","kind":"integration","linkedModuleIds":["physical-nutritional-injury"],"origin":"ai"},{"id":"hrp1-child-maltreatment-recognition~ai-6","moduleId":"hrp1-child-maltreatment-recognition","stem":"What is a key consideration when responding to suspected child sexual abuse (linkedModuleIds: ['hrp1-child-sexual-abuse-response'])?","options":[{"id":"a","text":"Immediate confrontation of the caregiver"},{"id":"b","text":"Trauma-informed clinical response"},{"id":"c","text":"Avoiding documentation of findings"},{"id":"d","text":"Assuming all allegations are false"}],"answerId":"b","explanation":"A trauma-informed clinical response is crucial in addressing the needs of the child and ensuring their safety.","kind":"integration","linkedModuleIds":["hrp1-child-sexual-abuse-response"],"origin":"ai"}],"hrp1-gender-sexuality-terminology":[{"id":"hrp1-gender-sexuality-terminology~ai-0","moduleId":"hrp1-gender-sexuality-terminology","stem":"What term describes a person whose gender identity aligns with the sex assigned at birth?","options":[{"id":"a","text":"Cisgender"},{"id":"b","text":"Transgender"},{"id":"c","text":"Nonbinary"},{"id":"d","text":"Genderqueer"}],"answerId":"a","explanation":"Cisgender refers to individuals whose gender identity matches their sex assigned at birth.","kind":"recall","origin":"ai"},{"id":"hrp1-gender-sexuality-terminology~ai-1","moduleId":"hrp1-gender-sexuality-terminology","stem":"Which of the following statements about sexual orientation is true?","options":[{"id":"a","text":"It is determined by gender identity."},{"id":"b","text":"It is distinct from gender identity."},{"id":"c","text":"It only applies to heterosexual individuals."},{"id":"d","text":"It is fixed and unchangeable."}],"answerId":"b","explanation":"Sexual orientation is a separate dimension from gender identity and can vary independently.","kind":"recall","origin":"ai"},{"id":"hrp1-gender-sexuality-terminology~ai-2","moduleId":"hrp1-gender-sexuality-terminology","stem":"A patient avoids healthcare due to previous discrimination. What is the primary mechanism behind this behavior?","options":[{"id":"a","text":"Lack of knowledge about healthcare options."},{"id":"b","text":"Stigma and misgendering creating barriers."},{"id":"c","text":"Fear of medical procedures."},{"id":"d","text":"Preference for alternative medicine."}],"answerId":"b","explanation":"Stigma and misgendering contribute to minority stress, leading to avoidance of healthcare.","kind":"recall","origin":"ai"},{"id":"hrp1-gender-sexuality-terminology~ai-3","moduleId":"hrp1-gender-sexuality-terminology","stem":"Which of the following best describes nonbinary identities?","options":[{"id":"a","text":"They fit strictly into male or female categories."},{"id":"b","text":"They may include identities outside the male/female binary."},{"id":"c","text":"They are synonymous with transgender identities."},{"id":"d","text":"They are a temporary phase for most individuals."}],"answerId":"b","explanation":"Nonbinary identities encompass a range of gender identities that do not fit strictly into male or female categories.","kind":"recall","origin":"ai"},{"id":"hrp1-gender-sexuality-terminology~ai-4","moduleId":"hrp1-gender-sexuality-terminology","stem":"Why is it important to ask about names and pronouns respectfully?","options":[{"id":"a","text":"To avoid legal issues."},{"id":"b","text":"To ensure accurate medical records."},{"id":"c","text":"To respect individual identity and expression."},{"id":"d","text":"To conform to societal norms."}],"answerId":"c","explanation":"Respectful inquiry about names and pronouns acknowledges and affirms individual identity and expression.","kind":"clinical","origin":"ai"},{"id":"hrp1-gender-sexuality-terminology~ai-5","moduleId":"hrp1-gender-sexuality-terminology","stem":"How does gender identity relate to sexual orientation?","options":[{"id":"a","text":"They are the same dimension."},{"id":"b","text":"Gender identity determines sexual orientation."},{"id":"c","text":"They are distinct dimensions."},{"id":"d","text":"Only cisgender individuals have a defined sexual orientation."}],"answerId":"c","explanation":"Gender identity and sexual orientation are separate dimensions; individuals can have any sexual orientation regardless of their gender identity.","kind":"trap","origin":"ai"},{"id":"hrp1-gender-sexuality-terminology~ai-6","moduleId":"hrp1-gender-sexuality-terminology","stem":"In assessing a patient with gender dysphoria, which aspect is crucial for providing affirming care?","options":[{"id":"a","text":"Assuming their preferred pronouns."},{"id":"b","text":"Understanding the distinction between gender identity and sexual orientation."},{"id":"c","text":"Focusing solely on their physical appearance."},{"id":"d","text":"Encouraging them to conform to societal gender norms."}],"answerId":"b","explanation":"Recognizing the distinction between gender identity and sexual orientation is essential for providing appropriate affirming care.","kind":"integration","linkedModuleIds":["hrp1-gender-dysphoria-affirming-care"],"origin":"ai"},{"id":"hrp1-gender-sexuality-terminology~ai-7","moduleId":"hrp1-gender-sexuality-terminology","stem":"Which communication strategy is most effective when discussing sexual orientation with patients?","options":[{"id":"a","text":"Using technical jargon."},{"id":"b","text":"Assuming their orientation based on appearance."},{"id":"c","text":"Asking open-ended questions respectfully."},{"id":"d","text":"Focusing only on heterosexual relationships."}],"answerId":"c","explanation":"Open-ended questions allow for respectful and inclusive communication about sexual orientation.","kind":"integration","linkedModuleIds":["hrp1-inclusive-communication-sex-education"],"origin":"ai"}],"hrp1-semen-morphology-interpretation":[{"id":"hrp1-semen-morphology-interpretation~ai-0","moduleId":"hrp1-semen-morphology-interpretation","stem":"What is the primary purpose of evaluating sperm morphology?","options":[{"id":"a","text":"To determine the volume of semen produced"},{"id":"b","text":"To assess the presence of antisperm antibodies"},{"id":"c","text":"To evaluate the shape and structure of sperm"},{"id":"d","text":"To measure sperm motility"}],"answerId":"c","explanation":"Sperm morphology evaluation focuses on the shape and structure of sperm, which is crucial for assessing fertility potential.","kind":"recall","origin":"ai"},{"id":"hrp1-semen-morphology-interpretation~ai-1","moduleId":"hrp1-semen-morphology-interpretation","stem":"Which parameter is NOT typically included in a standard semen analysis?","options":[{"id":"a","text":"Sperm count"},{"id":"b","text":"Sperm motility"},{"id":"c","text":"Sperm morphology"},{"id":"d","text":"Semen color"}],"answerId":"d","explanation":"While semen color may be noted, it is not a standard quantitative parameter in semen analysis.","kind":"trap","origin":"ai"},{"id":"hrp1-semen-morphology-interpretation~ai-2","moduleId":"hrp1-semen-morphology-interpretation","stem":"What does the presence of many round cells in a semen sample suggest?","options":[{"id":"a","text":"High sperm motility"},{"id":"b","text":"Possible leukocytes or immature germ cells"},{"id":"c","text":"Normal sperm morphology"},{"id":"d","text":"Presence of antisperm antibodies"}],"answerId":"b","explanation":"Many round cells may indicate either leukocytes or immature germ cells, necessitating further differentiation.","kind":"recall","origin":"ai"},{"id":"hrp1-semen-morphology-interpretation~ai-3","moduleId":"hrp1-semen-morphology-interpretation","stem":"Which of the following findings would most likely indicate male-factor subfertility?","options":[{"id":"a","text":"Single abnormal sperm morphology"},{"id":"b","text":"Normal sperm motility"},{"id":"c","text":"Multiple abnormal parameters on repeat samples"},{"id":"d","text":"High sperm count"}],"answerId":"c","explanation":"Multiple abnormal parameters on repeat samples raise the likelihood of clinically significant male-factor subfertility.","kind":"clinical","origin":"ai"},{"id":"hrp1-semen-morphology-interpretation~ai-4","moduleId":"hrp1-semen-morphology-interpretation","stem":"How does sperm morphology relate to overall fertility assessment?","options":[{"id":"a","text":"It is the sole determinant of fertility"},{"id":"b","text":"It is one of many probabilistic parameters"},{"id":"c","text":"It guarantees successful conception"},{"id":"d","text":"It is irrelevant in the context of other parameters"}],"answerId":"b","explanation":"Sperm morphology is one of several probabilistic parameters that contribute to a couple-level fertility assessment.","kind":"trap","origin":"ai"},{"id":"hrp1-semen-morphology-interpretation~ai-5","moduleId":"hrp1-semen-morphology-interpretation","stem":"In evaluating semen quality, which parameter should be considered alongside morphology for a comprehensive assessment?","options":[{"id":"a","text":"Semen color"},{"id":"b","text":"Sperm vitality"},{"id":"c","text":"Semen viscosity"},{"id":"d","text":"Semen odor"}],"answerId":"b","explanation":"Sperm vitality is crucial to assess alongside morphology to evaluate overall semen quality and fertility potential.","kind":"integration","linkedModuleIds":["hrp1-semen-macroscopic-chemistry"],"origin":"ai"},{"id":"hrp1-semen-morphology-interpretation~ai-6","moduleId":"hrp1-semen-morphology-interpretation","stem":"When interpreting semen analysis results, which factor should be integrated with sperm morphology?","options":[{"id":"a","text":"Semen collection method"},{"id":"b","text":"Semen odor"},{"id":"c","text":"Semen viscosity"},{"id":"d","text":"Semen temperature"}],"answerId":"a","explanation":"The method of semen collection can significantly affect the results and should be considered alongside sperm morphology.","kind":"integration","linkedModuleIds":["hrp1-semen-composition-collection"],"origin":"ai"}],"hrp1-semen-macroscopic-chemistry":[{"id":"hrp1-semen-macroscopic-chemistry~ai-0","moduleId":"hrp1-semen-macroscopic-chemistry","stem":"What is the primary role of prostatic enzymes in semen liquefaction?","options":[{"id":"a","text":"To increase semen viscosity"},{"id":"b","text":"To facilitate sperm motility"},{"id":"c","text":"To neutralize vaginal acidity"},{"id":"d","text":"To provide nutrients for sperm"}],"answerId":"b","explanation":"Prostatic enzymes are crucial for liquefying the coagulated semen, which enhances sperm motility.","kind":"mechanism","origin":"ai"},{"id":"hrp1-semen-macroscopic-chemistry~ai-1","moduleId":"hrp1-semen-macroscopic-chemistry","stem":"A semen sample shows low volume, acidic pH, and absent fructose. What is the most likely diagnosis?","options":[{"id":"a","text":"Prostate obstruction"},{"id":"b","text":"Seminal vesicle obstruction"},{"id":"c","text":"Ejaculatory duct obstruction"},{"id":"d","text":"Testicular failure"}],"answerId":"b","explanation":"These findings suggest a lack of seminal vesicle contribution, indicative of obstruction.","kind":"clinical","origin":"ai"},{"id":"hrp1-semen-macroscopic-chemistry~ai-2","moduleId":"hrp1-semen-macroscopic-chemistry","stem":"Which finding is most indicative of impaired sperm motility due to semen viscosity?","options":[{"id":"a","text":"High fructose levels"},{"id":"b","text":"Persistent viscosity"},{"id":"c","text":"Normal pH"},{"id":"d","text":"Increased volume"}],"answerId":"b","explanation":"Persistently viscous semen can hinder motility assessment and sperm progression.","kind":"recall","origin":"ai"},{"id":"hrp1-semen-macroscopic-chemistry~ai-3","moduleId":"hrp1-semen-macroscopic-chemistry","stem":"What is a critical factor to consider when interpreting abnormal semen pH?","options":[{"id":"a","text":"Sperm morphology alone"},{"id":"b","text":"Volume and fructose levels"},{"id":"c","text":"Ejaculatory history"},{"id":"d","text":"Patient age"}],"answerId":"b","explanation":"Abnormal pH must be interpreted in conjunction with volume, fructose, and sperm findings due to multiple gland contributions.","kind":"trap","origin":"ai"},{"id":"hrp1-semen-macroscopic-chemistry~ai-4","moduleId":"hrp1-semen-macroscopic-chemistry","stem":"Which of the following is a primary component of seminal vesicle secretion?","options":[{"id":"a","text":"Fructose"},{"id":"b","text":"Prostate-specific antigen"},{"id":"c","text":"Sodium bicarbonate"},{"id":"d","text":"Testosterone"}],"answerId":"a","explanation":"Fructose is a major component of seminal vesicle fluid, providing energy for sperm.","kind":"recall","origin":"ai"},{"id":"hrp1-semen-macroscopic-chemistry~ai-5","moduleId":"hrp1-semen-macroscopic-chemistry","stem":"How does seminal vesicle dysfunction affect semen analysis?","options":[{"id":"a","text":"Increases sperm count"},{"id":"b","text":"Decreases semen volume and fructose"},{"id":"c","text":"Increases semen viscosity"},{"id":"d","text":"Decreases sperm motility only"}],"answerId":"b","explanation":"Dysfunction leads to low volume and fructose levels, affecting overall semen quality.","kind":"integration","linkedModuleIds":["hrp1-semen-morphology-interpretation"],"origin":"ai"},{"id":"hrp1-semen-macroscopic-chemistry~ai-6","moduleId":"hrp1-semen-macroscopic-chemistry","stem":"What semen characteristic is most affected by prostatic fluid contribution?","options":[{"id":"a","text":"Volume"},{"id":"b","text":"pH"},{"id":"c","text":"Fructose"},{"id":"d","text":"Viscosity"}],"answerId":"b","explanation":"Prostatic fluid is relatively acidic, thus influencing the overall pH of the semen.","kind":"integration","linkedModuleIds":["hrp1-semen-composition-collection"],"origin":"ai"}],"hrp1-semen-composition-collection":[{"id":"hrp1-semen-composition-collection~ai-0","moduleId":"hrp1-semen-composition-collection","stem":"What is the primary contribution of the seminal vesicles to semen?","options":[{"id":"a","text":"Sperm cells"},{"id":"b","text":"Fructose-rich alkaline fluid"},{"id":"c","text":"Prostate-specific antigen"},{"id":"d","text":"Zinc and citrate"}],"answerId":"b","explanation":"The seminal vesicles primarily contribute a fructose-rich alkaline fluid that provides energy for sperm.","kind":"recall","origin":"ai"},{"id":"hrp1-semen-composition-collection~ai-1","moduleId":"hrp1-semen-composition-collection","stem":"Which pre-analytic error can lead to falsely low sperm concentration in a semen analysis?","options":[{"id":"a","text":"Transport delay"},{"id":"b","text":"Incomplete collection"},{"id":"c","text":"Abstinence mismatch"},{"id":"d","text":"Low ambient temperature"}],"answerId":"b","explanation":"Incomplete collection may result in the loss of the sperm-rich first fraction, leading to an inaccurate low concentration.","kind":"trap","origin":"ai"},{"id":"hrp1-semen-composition-collection~ai-2","moduleId":"hrp1-semen-composition-collection","stem":"What is the role of zinc in semen?","options":[{"id":"a","text":"Energy source for sperm motility"},{"id":"b","text":"Antioxidant protection for sperm"},{"id":"c","text":"Stabilization of sperm DNA"},{"id":"d","text":"Enhancement of sperm capacitation"}],"answerId":"c","explanation":"Zinc plays a role in stabilizing sperm DNA and is important for sperm maturation.","kind":"mechanism","origin":"ai"},{"id":"hrp1-semen-composition-collection~ai-3","moduleId":"hrp1-semen-composition-collection","stem":"A semen analysis shows low-volume acidic semen with absent fructose. What condition should be suspected?","options":[{"id":"a","text":"Testicular failure"},{"id":"b","text":"Ejaculatory duct obstruction"},{"id":"c","text":"Prostate cancer"},{"id":"d","text":"Varicocele"}],"answerId":"b","explanation":"Low-volume acidic semen with absent fructose suggests possible ejaculatory duct obstruction or absent seminal vesicle contribution.","kind":"clinical","origin":"ai"},{"id":"hrp1-semen-composition-collection~ai-4","moduleId":"hrp1-semen-composition-collection","stem":"Which of the following factors is critical for accurate semen analysis results?","options":[{"id":"a","text":"Age of the patient"},{"id":"b","text":"Timing of ejaculation"},{"id":"c","text":"Duration of abstinence"},{"id":"d","text":"Volume of the sample"}],"answerId":"c","explanation":"Duration of abstinence is crucial as it affects sperm concentration and overall semen quality.","kind":"trap","origin":"ai"},{"id":"hrp1-semen-composition-collection~ai-5","moduleId":"hrp1-semen-composition-collection","stem":"How does the collection method of semen relate to pathology in the urinary system?","options":[{"id":"a","text":"Both require sterile techniques"},{"id":"b","text":"Both are affected by hydration status"},{"id":"c","text":"Both can indicate systemic infections"},{"id":"d","text":"Both rely on pre-analytic conditions"}],"answerId":"d","explanation":"Both semen and urine analyses are highly sensitive to pre-analytic conditions, affecting the reliability of results.","kind":"integration","linkedModuleIds":["urinalysis-urine-examination"],"origin":"ai"},{"id":"hrp1-semen-composition-collection~ai-6","moduleId":"hrp1-semen-composition-collection","stem":"In assessing semen quality, which parameter is most directly affected by the collection technique?","options":[{"id":"a","text":"Sperm motility"},{"id":"b","text":"Sperm morphology"},{"id":"c","text":"Sperm concentration"},{"id":"d","text":"Semen volume"}],"answerId":"c","explanation":"Sperm concentration can be significantly impacted by the collection technique, particularly if the first fraction is missed.","kind":"integration","linkedModuleIds":["hrp1-semen-concentration-motility"],"origin":"ai"}],"hrp1-gender-dysphoria-affirming-care":[{"id":"hrp1-gender-dysphoria-affirming-care~ai-0","moduleId":"hrp1-gender-dysphoria-affirming-care","stem":"What is the primary focus of gender dysphoria assessment?","options":[{"id":"a","text":"Identifying a psychiatric disorder"},{"id":"b","text":"Exploring clinically significant distress related to incongruence"},{"id":"c","text":"Determining the need for surgery"},{"id":"d","text":"Assessing family history of mental illness"}],"answerId":"b","explanation":"The assessment focuses on the distress or impairment caused by the incongruence between gender identity and assigned sex.","kind":"recall","origin":"ai"},{"id":"hrp1-gender-dysphoria-affirming-care~ai-1","moduleId":"hrp1-gender-dysphoria-affirming-care","stem":"Which of the following is NOT a component of gender dysphoria assessment?","options":[{"id":"a","text":"Duration of distress"},{"id":"b","text":"Body-related distress"},{"id":"c","text":"Family history of psychiatric disorders"},{"id":"d","text":"Personal goals"}],"answerId":"c","explanation":"While family history may be relevant, it is not a direct component of the assessment for gender dysphoria.","kind":"trap","origin":"ai"},{"id":"hrp1-gender-dysphoria-affirming-care~ai-2","moduleId":"hrp1-gender-dysphoria-affirming-care","stem":"How does an affirming environment impact individuals with gender dysphoria?","options":[{"id":"a","text":"Increases stigma"},{"id":"b","text":"Reduces distress"},{"id":"c","text":"Mandates surgical intervention"},{"id":"d","text":"Enforces gender norms"}],"answerId":"b","explanation":"An affirming environment can lower distress by providing support and reducing stigma.","kind":"mechanism","origin":"ai"},{"id":"hrp1-gender-dysphoria-affirming-care~ai-3","moduleId":"hrp1-gender-dysphoria-affirming-care","stem":"What is a common coexisting condition in individuals with gender dysphoria?","options":[{"id":"a","text":"Bipolar disorder"},{"id":"b","text":"Obsessive-compulsive disorder"},{"id":"c","text":"Anxiety"},{"id":"d","text":"Schizophrenia"}],"answerId":"c","explanation":"Anxiety is commonly seen alongside gender dysphoria and should be treated appropriately.","kind":"recall","origin":"ai"},{"id":"hrp1-gender-dysphoria-affirming-care~ai-4","moduleId":"hrp1-gender-dysphoria-affirming-care","stem":"Which statement correctly describes gender diversity?","options":[{"id":"a","text":"It is a psychiatric illness."},{"id":"b","text":"It is a natural variation of human experience."},{"id":"c","text":"It requires treatment to be valid."},{"id":"d","text":"It is always associated with mental health issues."}],"answerId":"b","explanation":"Gender diversity itself is not a mental disorder; it is a natural variation of human experience.","kind":"trap","origin":"ai"},{"id":"hrp1-gender-dysphoria-affirming-care~ai-5","moduleId":"hrp1-gender-dysphoria-affirming-care","stem":"How can nutritional support be integrated into care for individuals with gender dysphoria?","options":[{"id":"a","text":"By enforcing weight loss protocols"},{"id":"b","text":"By addressing nutritional deficiencies that may arise from stress"},{"id":"c","text":"By promoting high-calorie diets"},{"id":"d","text":"By avoiding discussions about nutrition"}],"answerId":"b","explanation":"Nutritional support can help address deficiencies that may arise due to stress or other factors related to gender dysphoria.","kind":"integration","linkedModuleIds":["nutritional-assessment-support"],"origin":"ai"},{"id":"hrp1-gender-dysphoria-affirming-care~ai-6","moduleId":"hrp1-gender-dysphoria-affirming-care","stem":"What role does inclusive communication play in affirming care for gender-diverse individuals?","options":[{"id":"a","text":"It is irrelevant to care."},{"id":"b","text":"It can enhance understanding and support."},{"id":"c","text":"It complicates treatment protocols."},{"id":"d","text":"It should only focus on medical terms."}],"answerId":"b","explanation":"Inclusive communication fosters understanding and support, which is crucial in affirming care for gender-diverse individuals.","kind":"integration","linkedModuleIds":["hrp1-inclusive-communication-sex-education"],"origin":"ai"}],"hrp1-gonadal-descent":[{"id":"hrp1-gonadal-descent~ai-0","moduleId":"hrp1-gonadal-descent","stem":"What is the primary role of the gubernaculum during gonadal descent?","options":[{"id":"a","text":"To produce hormones for testicular descent"},{"id":"b","text":"To guide the descent of the gonads"},{"id":"c","text":"To form the tunica vaginalis"},{"id":"d","text":"To close the processus vaginalis"}],"answerId":"b","explanation":"The gubernaculum serves as a guiding structure for the descent of the testes and ovaries.","kind":"recall","origin":"ai"},{"id":"hrp1-gonadal-descent~ai-1","moduleId":"hrp1-gonadal-descent","stem":"Which structure precedes the testis during its descent into the scrotum?","options":[{"id":"a","text":"Gubernaculum"},{"id":"b","text":"Tunica vaginalis"},{"id":"c","text":"Processus vaginalis"},{"id":"d","text":"Inguinal canal"}],"answerId":"c","explanation":"The processus vaginalis precedes the testis and normally closes after descent.","kind":"recall","origin":"ai"},{"id":"hrp1-gonadal-descent~ai-2","moduleId":"hrp1-gonadal-descent","stem":"A patient presents with a fluctuating scrotal swelling. What is the most likely underlying cause?","options":[{"id":"a","text":"Undescended testis"},{"id":"b","text":"Hydrocele"},{"id":"c","text":"Patent processus vaginalis"},{"id":"d","text":"Inguinal hernia"}],"answerId":"c","explanation":"A patent processus vaginalis can communicate with the peritoneal cavity, leading to a fluctuating scrotal swelling.","kind":"clinical","origin":"ai"},{"id":"hrp1-gonadal-descent~ai-3","moduleId":"hrp1-gonadal-descent","stem":"What is the consequence of failure of the processus vaginalis to close?","options":[{"id":"a","text":"Undescended testis"},{"id":"b","text":"Direct inguinal hernia"},{"id":"c","text":"Indirect inguinal hernia"},{"id":"d","text":"Ovarian torsion"}],"answerId":"c","explanation":"Failure of closure can lead to an indirect inguinal hernia or communicating hydrocele.","kind":"trap","origin":"ai"},{"id":"hrp1-gonadal-descent~ai-4","moduleId":"hrp1-gonadal-descent","stem":"Which of the following structures is derived from the gubernaculum in females?","options":[{"id":"a","text":"Round ligament of the uterus"},{"id":"b","text":"Ovarian ligament"},{"id":"c","text":"Both A and B"},{"id":"d","text":"None of the above"}],"answerId":"c","explanation":"Both the ovarian ligament and round ligament are remnants of the gubernaculum, separated by the attachment to the uterus.","kind":"recall","origin":"ai"},{"id":"hrp1-gonadal-descent~ai-5","moduleId":"hrp1-gonadal-descent","stem":"How does the descent of the testes relate to differences of sex development?","options":[{"id":"a","text":"It is unrelated to sex development"},{"id":"b","text":"It influences the formation of external genitalia"},{"id":"c","text":"It can lead to reproductive anomalies"},{"id":"d","text":"It affects hormonal levels only"}],"answerId":"c","explanation":"Abnormalities in gonadal descent can result in differences of sex development and reproductive anomalies.","kind":"integration","linkedModuleIds":["hrp1-dsd-reproductive-anomalies"],"origin":"ai"},{"id":"hrp1-gonadal-descent~ai-6","moduleId":"hrp1-gonadal-descent","stem":"What is the significance of the gubernaculum in the context of external genital differentiation?","options":[{"id":"a","text":"It has no role in differentiation"},{"id":"b","text":"It determines the sex of the fetus"},{"id":"c","text":"It aids in the positioning of external genitalia"},{"id":"d","text":"It influences hormonal secretion"}],"answerId":"c","explanation":"The gubernaculum helps position the external genitalia during development, linking it to differentiation processes.","kind":"integration","linkedModuleIds":["hrp1-external-genital-differentiation"],"origin":"ai"}],"hrp1-gonadal-differentiation":[{"id":"hrp1-gonadal-differentiation~ai-0","moduleId":"hrp1-gonadal-differentiation","stem":"What is the primary role of SRY in gonadal differentiation?","options":[{"id":"a","text":"Promotes ovarian development"},{"id":"b","text":"Inhibits testosterone production"},{"id":"c","text":"Triggers testis differentiation"},{"id":"d","text":"Stimulates AMH production"}],"answerId":"c","explanation":"SRY initiates testis differentiation by activating downstream genes like SOX9.","kind":"recall","origin":"ai"},{"id":"hrp1-gonadal-differentiation~ai-1","moduleId":"hrp1-gonadal-differentiation","stem":"Which hormone is produced by Leydig cells during male gonadal development?","options":[{"id":"a","text":"Estrogen"},{"id":"b","text":"Progesterone"},{"id":"c","text":"Testosterone"},{"id":"d","text":"AMH"}],"answerId":"c","explanation":"Leydig cells are responsible for producing testosterone, which is crucial for male reproductive tract development.","kind":"recall","origin":"ai"},{"id":"hrp1-gonadal-differentiation~ai-2","moduleId":"hrp1-gonadal-differentiation","stem":"What is the consequence of AMH production by Sertoli cells?","options":[{"id":"a","text":"Development of external genitalia"},{"id":"b","text":"Regression of Müllerian ducts"},{"id":"c","text":"Stimulation of Wolffian ducts"},{"id":"d","text":"Promotion of ovarian follicle development"}],"answerId":"b","explanation":"AMH produced by Sertoli cells leads to the regression of Müllerian ducts during male development.","kind":"mechanism","origin":"ai"},{"id":"hrp1-gonadal-differentiation~ai-3","moduleId":"hrp1-gonadal-differentiation","stem":"Which of the following statements about gonadal differentiation is correct?","options":[{"id":"a","text":"One hormone dictates all reproductive structures"},{"id":"b","text":"Gonadal and ductal differentiation are distinct processes"},{"id":"c","text":"Chromosomal sex determines external genitalia exclusively"},{"id":"d","text":"All individuals follow the same developmental pathway"}],"answerId":"b","explanation":"Gonadal and ductal differentiation are distinct processes that depend on various factors.","kind":"trap","origin":"ai"},{"id":"hrp1-gonadal-differentiation~ai-4","moduleId":"hrp1-gonadal-differentiation","stem":"In the absence of SRY, which signaling pathway promotes ovarian differentiation?","options":[{"id":"a","text":"WNT4/RSPO1"},{"id":"b","text":"SOX9"},{"id":"c","text":"AMH"},{"id":"d","text":"Testosterone"}],"answerId":"a","explanation":"WNT4 and RSPO1 promote ovarian differentiation when SRY is absent.","kind":"recall","origin":"ai"},{"id":"hrp1-gonadal-differentiation~ai-5","moduleId":"hrp1-gonadal-differentiation","stem":"How does testosterone influence the development of the Wolffian ducts?","options":[{"id":"a","text":"Inhibits their development"},{"id":"b","text":"Stimulates their differentiation"},{"id":"c","text":"Promotes Müllerian duct development"},{"id":"d","text":"Has no effect on them"}],"answerId":"b","explanation":"Testosterone is essential for the differentiation and maintenance of the Wolffian ducts.","kind":"mechanism","origin":"ai"},{"id":"hrp1-gonadal-differentiation~ai-6","moduleId":"hrp1-gonadal-differentiation","stem":"How does the differentiation of external genitalia relate to gonadal differentiation?","options":[{"id":"a","text":"It occurs independently of gonadal signals"},{"id":"b","text":"It is solely determined by chromosomal sex"},{"id":"c","text":"It is influenced by hormones produced by the gonads"},{"id":"d","text":"It is determined by environmental factors only"}],"answerId":"c","explanation":"External genital differentiation is influenced by hormones like testosterone produced by the developing gonads.","kind":"integration","linkedModuleIds":["hrp1-external-genital-differentiation"],"origin":"ai"},{"id":"hrp1-gonadal-differentiation~ai-7","moduleId":"hrp1-gonadal-differentiation","stem":"What is a common outcome of differences in sex development (DSD) related to gonadal differentiation?","options":[{"id":"a","text":"Uniform development of reproductive structures"},{"id":"b","text":"Variability in external genitalia and internal ducts"},{"id":"c","text":"Consistent hormonal profiles across all individuals"},{"id":"d","text":"Exclusive reliance on chromosomal sex for phenotype"}],"answerId":"b","explanation":"DSD can lead to variability in the development of external genitalia and internal reproductive structures due to disruptions in gonadal differentiation.","kind":"integration","linkedModuleIds":["hrp1-dsd-reproductive-anomalies"],"origin":"ai"}],"hrp1-semen-concentration-motility":[{"id":"hrp1-semen-concentration-motility~ai-0","moduleId":"hrp1-semen-concentration-motility","stem":"What is the definition of sperm concentration?","options":[{"id":"a","text":"Total sperm count in the ejaculate"},{"id":"b","text":"Sperm per unit volume of semen"},{"id":"c","text":"Percentage of motile sperm"},{"id":"d","text":"Sperm vitality percentage"}],"answerId":"b","explanation":"Sperm concentration refers to the number of sperm per unit volume of semen.","kind":"recall","origin":"ai"},{"id":"hrp1-semen-concentration-motility~ai-1","moduleId":"hrp1-semen-concentration-motility","stem":"Which method is essential for accurate sperm counting?","options":[{"id":"a","text":"Visual inspection under a microscope"},{"id":"b","text":"Using a validated counting chamber"},{"id":"c","text":"Manual counting without dilution"},{"id":"d","text":"Only assessing motility"}],"answerId":"b","explanation":"A validated counting chamber ensures accurate sperm counting by minimizing sampling errors.","kind":"recall","origin":"ai"},{"id":"hrp1-semen-concentration-motility~ai-2","moduleId":"hrp1-semen-concentration-motility","stem":"What does low motility with preserved vitality indicate?","options":[{"id":"a","text":"Sperm are dead"},{"id":"b","text":"Sperm are alive but immobile"},{"id":"c","text":"Sperm concentration is low"},{"id":"d","text":"Semen volume is reduced"}],"answerId":"b","explanation":"Low motility with preserved vitality indicates that while the sperm are alive, their movement is impaired.","kind":"clinical","origin":"ai"},{"id":"hrp1-semen-concentration-motility~ai-3","moduleId":"hrp1-semen-concentration-motility","stem":"Which statement about WHO reference limits is correct?","options":[{"id":"a","text":"They define absolute sterility"},{"id":"b","text":"They are diagnostic boundaries"},{"id":"c","text":"They estimate distribution in a fertile population"},{"id":"d","text":"They apply only to total sperm count"}],"answerId":"c","explanation":"WHO reference limits estimate distribution and should be integrated with clinical context and repeat testing.","kind":"trap","origin":"ai"},{"id":"hrp1-semen-concentration-motility~ai-4","moduleId":"hrp1-semen-concentration-motility","stem":"What is the mechanism behind representative sampling in semen analysis?","options":[{"id":"a","text":"It increases sperm motility"},{"id":"b","text":"It converts heterogeneous specimens into interpretable counts"},{"id":"c","text":"It reduces the need for dilution"},{"id":"d","text":"It eliminates sampling errors completely"}],"answerId":"b","explanation":"Representative sampling helps convert a heterogeneous specimen into counts that can be interpreted accurately.","kind":"mechanism","origin":"ai"},{"id":"hrp1-semen-concentration-motility~ai-5","moduleId":"hrp1-semen-concentration-motility","stem":"How does sperm concentration relate to total sperm count?","options":[{"id":"a","text":"Total count is independent of concentration"},{"id":"b","text":"Concentration is total count divided by volume"},{"id":"c","text":"Total count is concentration multiplied by volume"},{"id":"d","text":"They are synonymous terms"}],"answerId":"c","explanation":"Total sperm count is calculated as concentration multiplied by the ejaculate volume.","kind":"recall","origin":"ai"},{"id":"hrp1-semen-concentration-motility~ai-6","moduleId":"hrp1-semen-concentration-motility","stem":"How does X-inactivation relate to sperm production?","options":[{"id":"a","text":"It affects sperm motility"},{"id":"b","text":"It is unrelated to sperm function"},{"id":"c","text":"It influences sex determination and can affect fertility"},{"id":"d","text":"It determines sperm concentration"}],"answerId":"c","explanation":"X-inactivation is crucial in sex determination, which can indirectly influence fertility outcomes.","kind":"integration","linkedModuleIds":["x-inactivation-sex-determination"],"origin":"ai"},{"id":"hrp1-semen-concentration-motility~ai-7","moduleId":"hrp1-semen-concentration-motility","stem":"What role does potassium play in sperm function?","options":[{"id":"a","text":"It is essential for sperm motility"},{"id":"b","text":"It has no effect on sperm"},{"id":"c","text":"It only affects sperm concentration"},{"id":"d","text":"It is involved in semen volume regulation"}],"answerId":"a","explanation":"Potassium is essential for various cellular functions, including sperm motility.","kind":"integration","linkedModuleIds":["potassium-disorders"],"origin":"ai"}],"hrp1-dsd-reproductive-anomalies":[{"id":"hrp1-dsd-reproductive-anomalies~ai-0","moduleId":"hrp1-dsd-reproductive-anomalies","stem":"What is the typical external anatomy in complete androgen insensitivity syndrome?","options":[{"id":"a","text":"Male external genitalia with a penis"},{"id":"b","text":"Typical female external anatomy with absent uterus"},{"id":"c","text":"Ambiguous genitalia"},{"id":"d","text":"Normal male external genitalia with cryptorchidism"}],"answerId":"b","explanation":"In complete androgen insensitivity, individuals have typical female external anatomy due to the inability of tissues to respond to androgens.","kind":"recall","origin":"ai"},{"id":"hrp1-dsd-reproductive-anomalies~ai-1","moduleId":"hrp1-dsd-reproductive-anomalies","stem":"Which mechanism explains the absence of Müllerian structures in complete androgen insensitivity?","options":[{"id":"a","text":"Absence of testosterone"},{"id":"b","text":"AMH-mediated regression"},{"id":"c","text":"Increased estrogen production"},{"id":"d","text":"Defective androgen receptor"}],"answerId":"b","explanation":"Anti-Müllerian hormone (AMH) secreted by testes leads to the regression of Müllerian ducts, resulting in absent uterus.","kind":"mechanism","origin":"ai"},{"id":"hrp1-dsd-reproductive-anomalies~ai-2","moduleId":"hrp1-dsd-reproductive-anomalies","stem":"A newborn presents with hypospadias and an undescended testis. What should be the next step in management?","options":[{"id":"a","text":"Immediate surgical repair of hypospadias"},{"id":"b","text":"Assessment for broader differences of sex development"},{"id":"c","text":"Observation for spontaneous descent"},{"id":"d","text":"Referral to urology for routine follow-up"}],"answerId":"b","explanation":"The combination of hypospadias and undescended testis warrants further assessment for broader differences of sex development rather than isolated repair.","kind":"clinical","origin":"ai"},{"id":"hrp1-dsd-reproductive-anomalies~ai-3","moduleId":"hrp1-dsd-reproductive-anomalies","stem":"Which of the following conditions is characterized by a failure of Müllerian duct fusion?","options":[{"id":"a","text":"Complete androgen insensitivity"},{"id":"b","text":"Turner syndrome"},{"id":"c","text":"Mayer-Rokitansky-Küster-Hauser syndrome"},{"id":"d","text":"Klinefelter syndrome"}],"answerId":"c","explanation":"Mayer-Rokitansky-Küster-Hauser syndrome is specifically due to the failure of Müllerian duct fusion, leading to absent uterus.","kind":"recall","origin":"ai"},{"id":"hrp1-dsd-reproductive-anomalies~ai-4","moduleId":"hrp1-dsd-reproductive-anomalies","stem":"What is a common urinary tract anomaly associated with Müllerian duct anomalies?","options":[{"id":"a","text":"Hydronephrosis"},{"id":"b","text":"Bilateral renal agenesis"},{"id":"c","text":"Ureter duplication"},{"id":"d","text":"Vesicoureteral reflux"}],"answerId":"d","explanation":"Urinary tract anomalies often coexist with Müllerian duct anomalies due to their close developmental pathways, with vesicoureteral reflux being a common finding.","kind":"trap","origin":"ai"},{"id":"hrp1-dsd-reproductive-anomalies~ai-5","moduleId":"hrp1-dsd-reproductive-anomalies","stem":"How does the presence of a Y chromosome influence sexual differentiation?","options":[{"id":"a","text":"It leads to the development of ovaries"},{"id":"b","text":"It promotes the formation of testes and AMH secretion"},{"id":"c","text":"It results in female external genitalia"},{"id":"d","text":"It has no effect on sexual differentiation"}],"answerId":"b","explanation":"The presence of a Y chromosome typically leads to the development of testes, which secrete AMH and testosterone, influencing sexual differentiation.","kind":"integration","linkedModuleIds":["developmental-genetic-regulation"],"origin":"ai"},{"id":"hrp1-dsd-reproductive-anomalies~ai-6","moduleId":"hrp1-dsd-reproductive-anomalies","stem":"Which genetic mechanism is crucial for the development of male external genitalia?","options":[{"id":"a","text":"Inhibition of AMH"},{"id":"b","text":"Action of dihydrotestosterone"},{"id":"c","text":"Presence of two X chromosomes"},{"id":"d","text":"Absence of testosterone"}],"answerId":"b","explanation":"Dihydrotestosterone (DHT) is essential for the development of male external genitalia from the genital tubercle.","kind":"integration","linkedModuleIds":["hrp1-external-genital-differentiation"],"origin":"ai"}],"bone-biology-remodeling":[{"id":"bone-biology-remodeling~ai-0","moduleId":"bone-biology-remodeling","stem":"What is the primary component of bone matrix?","options":[{"id":"a","text":"Type I collagen"},{"id":"b","text":"Hydroxyapatite"},{"id":"c","text":"Osteoprotegerin"},{"id":"d","text":"Wnt proteins"}],"answerId":"a","explanation":"Type I collagen makes up approximately 35% of the bone matrix, providing structural support.","kind":"recall","origin":"ai"},{"id":"bone-biology-remodeling~ai-1","moduleId":"bone-biology-remodeling","stem":"Which process describes the formation of flat bones?","options":[{"id":"a","text":"Endochondral ossification"},{"id":"b","text":"Intramembranous ossification"},{"id":"c","text":"Bone remodeling"},{"id":"d","text":"Appositional growth"}],"answerId":"b","explanation":"Flat bones form through intramembranous ossification, which does not involve a cartilage model.","kind":"recall","origin":"ai"},{"id":"bone-biology-remodeling~ai-2","moduleId":"bone-biology-remodeling","stem":"What is the role of osteoprotegerin (OPG) in bone remodeling?","options":[{"id":"a","text":"Activates osteoclasts"},{"id":"b","text":"Inhibits osteoclast activation"},{"id":"c","text":"Stimulates osteoblast proliferation"},{"id":"d","text":"Promotes mineralization"}],"answerId":"b","explanation":"OPG acts as a decoy receptor that binds RANKL, preventing it from activating osteoclasts and thus inhibiting bone resorption.","kind":"mechanism","origin":"ai"},{"id":"bone-biology-remodeling~ai-3","moduleId":"bone-biology-remodeling","stem":"A patient presents with woven bone in an adult. What does this finding indicate?","options":[{"id":"a","text":"Normal bone remodeling"},{"id":"b","text":"Pathological bone formation"},{"id":"c","text":"Healthy bone structure"},{"id":"d","text":"Increased osteoblast activity"}],"answerId":"b","explanation":"Woven bone is always pathological in adults, indicating rapid and disorganized bone formation.","kind":"recall","origin":"ai"},{"id":"bone-biology-remodeling~ai-4","moduleId":"bone-biology-remodeling","stem":"Which hormone is known to promote osteoclast activity and increase bone turnover?","options":[{"id":"a","text":"Estrogen"},{"id":"b","text":"Testosterone"},{"id":"c","text":"Parathyroid hormone (PTH)"},{"id":"d","text":"Bone morphogenetic proteins (BMPs)"}],"answerId":"c","explanation":"Parathyroid hormone (PTH) is a systemic regulator that promotes osteoclast activity and increases bone turnover.","kind":"recall","origin":"ai"},{"id":"bone-biology-remodeling~ai-5","moduleId":"bone-biology-remodeling","stem":"How does estrogen influence bone remodeling?","options":[{"id":"a","text":"Increases RANKL production"},{"id":"b","text":"Decreases OPG levels"},{"id":"c","text":"Promotes osteoclast activity"},{"id":"d","text":"Increases OPG production"}],"answerId":"d","explanation":"Estrogen increases OPG production, which helps to inhibit osteoclast activity and reduce bone resorption.","kind":"mechanism","origin":"ai"},{"id":"bone-biology-remodeling~ai-6","moduleId":"bone-biology-remodeling","stem":"In a patient with a developmental bone disorder, which mechanism is likely impaired?","options":[{"id":"a","text":"Osteoblast differentiation"},{"id":"b","text":"Osteoclast activation"},{"id":"c","text":"Mineralization of osteoid"},{"id":"d","text":"Matrix metalloproteinase activity"}],"answerId":"a","explanation":"Developmental bone disorders often involve impaired osteoblast differentiation, affecting bone formation.","kind":"integration","linkedModuleIds":["developmental-bone-disorders"],"origin":"ai"},{"id":"bone-biology-remodeling~ai-7","moduleId":"bone-biology-remodeling","stem":"Which metabolic bone disease is characterized by increased osteoclast activity and decreased bone density?","options":[{"id":"a","text":"Osteoporosis"},{"id":"b","text":"Osteomalacia"},{"id":"c","text":"Paget's disease"},{"id":"d","text":"Rickets"}],"answerId":"a","explanation":"Osteoporosis is characterized by increased osteoclast activity leading to decreased bone density.","kind":"integration","linkedModuleIds":["metabolic-bone-disease"],"origin":"ai"}],"hrp1-genital-duct-differentiation":[{"id":"hrp1-genital-duct-differentiation~ai-0","moduleId":"hrp1-genital-duct-differentiation","stem":"What hormone is responsible for the regression of the paramesonephric ducts in male differentiation?","options":[{"id":"a","text":"Testosterone"},{"id":"b","text":"Estrogen"},{"id":"c","text":"Anti-Müllerian Hormone (AMH)"},{"id":"d","text":"Luteinizing Hormone (LH)"}],"answerId":"c","explanation":"AMH, produced by fetal Sertoli cells, causes the regression of the paramesonephric ducts during male differentiation.","kind":"recall","origin":"ai"},{"id":"hrp1-genital-duct-differentiation~ai-1","moduleId":"hrp1-genital-duct-differentiation","stem":"Which structure is derived from the mesonephric duct in males?","options":[{"id":"a","text":"Uterus"},{"id":"b","text":"Epididymis"},{"id":"c","text":"Ovary"},{"id":"d","text":"Vagina"}],"answerId":"b","explanation":"The mesonephric duct develops into the epididymis, ductus deferens, seminal vesicle, and ejaculatory duct in males.","kind":"recall","origin":"ai"},{"id":"hrp1-genital-duct-differentiation~ai-2","moduleId":"hrp1-genital-duct-differentiation","stem":"A 46,XY individual presents with persistent Müllerian structures. What is the most likely underlying issue?","options":[{"id":"a","text":"Excess estrogen production"},{"id":"b","text":"Impaired AMH production"},{"id":"c","text":"Increased testosterone levels"},{"id":"d","text":"Normal androgen receptor function"}],"answerId":"b","explanation":"Persistent Müllerian structures suggest impaired AMH production or receptor signaling, preventing normal regression of the paramesonephric ducts.","kind":"clinical","origin":"ai"},{"id":"hrp1-genital-duct-differentiation~ai-3","moduleId":"hrp1-genital-duct-differentiation","stem":"In a male fetus, what effect does testosterone have on the mesonephric ducts?","options":[{"id":"a","text":"Causes regression"},{"id":"b","text":"Stimulates growth"},{"id":"c","text":"Inhibits growth"},{"id":"d","text":"No effect"}],"answerId":"b","explanation":"Testosterone stabilizes and promotes the growth of the mesonephric ducts, leading to the formation of male reproductive structures.","kind":"mechanism","origin":"ai"},{"id":"hrp1-genital-duct-differentiation~ai-4","moduleId":"hrp1-genital-duct-differentiation","stem":"Which of the following statements about the embryologic origin of the vagina is correct?","options":[{"id":"a","text":"The entire vagina is derived from the Müllerian duct"},{"id":"b","text":"The upper vagina is derived from the urogenital sinus"},{"id":"c","text":"The lower vagina develops from the urogenital sinus"},{"id":"d","text":"The vagina has a single embryologic origin"}],"answerId":"c","explanation":"The vaginal canal has dual embryologic origins; the upper vagina is from the Müllerian duct, while the lower vagina develops from the urogenital sinus.","kind":"trap","origin":"ai"},{"id":"hrp1-genital-duct-differentiation~ai-5","moduleId":"hrp1-genital-duct-differentiation","stem":"How does the absence of AMH affect the development of female reproductive structures?","options":[{"id":"a","text":"Promotes the development of male structures"},{"id":"b","text":"Inhibits the development of female structures"},{"id":"c","text":"Allows the paramesonephric ducts to persist"},{"id":"d","text":"Causes the regression of the mesonephric ducts"}],"answerId":"c","explanation":"In the absence of AMH, the paramesonephric ducts persist and develop into female reproductive structures such as the uterus and upper vagina.","kind":"mechanism","origin":"ai"},{"id":"hrp1-genital-duct-differentiation~ai-6","moduleId":"hrp1-genital-duct-differentiation","stem":"A patient with a 46,XY karyotype has a uterus and functioning testes. What is the likely explanation?","options":[{"id":"a","text":"Excess AMH production"},{"id":"b","text":"Defective androgen receptor signaling"},{"id":"c","text":"Normal AMH signaling"},{"id":"d","text":"Insufficient testosterone levels"}],"answerId":"b","explanation":"The presence of a uterus in a 46,XY individual suggests defective androgen receptor signaling, preventing normal male differentiation despite the presence of testes.","kind":"integration","linkedModuleIds":["hrp1-dsd-reproductive-anomalies"],"origin":"ai"},{"id":"hrp1-genital-duct-differentiation~ai-7","moduleId":"hrp1-genital-duct-differentiation","stem":"In a case of androgen insensitivity syndrome, which duct system is likely to be affected?","options":[{"id":"a","text":"Paramesonephric ducts"},{"id":"b","text":"Mesonephric ducts"},{"id":"c","text":"Both duct systems"},{"id":"d","text":"Neither duct system"}],"answerId":"b","explanation":"Androgen insensitivity syndrome affects the mesonephric ducts, leading to their regression and the persistence of paramesonephric structures in a genetically male individual.","kind":"integration","linkedModuleIds":["hrp1-external-genital-differentiation"],"origin":"ai"}],"hrp1-inclusive-communication-sex-education":[{"id":"hrp1-inclusive-communication-sex-education~ai-0","moduleId":"hrp1-inclusive-communication-sex-education","stem":"What is the primary goal of creating a safe clinical space for patients discussing sexual health?","options":[{"id":"a","text":"To gather maximum information quickly"},{"id":"b","text":"To ensure patient confidentiality and comfort"},{"id":"c","text":"To promote clinician authority"},{"id":"d","text":"To encourage family involvement"}],"answerId":"b","explanation":"A safe clinical space prioritizes patient confidentiality and comfort, allowing for open discussions about sensitive topics.","kind":"recall","origin":"ai"},{"id":"hrp1-inclusive-communication-sex-education~ai-1","moduleId":"hrp1-inclusive-communication-sex-education","stem":"Which of the following is a key component of comprehensive sexual education?","options":[{"id":"a","text":"Focus solely on anatomy"},{"id":"b","text":"Teach only about contraception"},{"id":"c","text":"Include discussions on consent and relationships"},{"id":"d","text":"Avoid discussions on diversity"}],"answerId":"c","explanation":"Comprehensive sexual education includes consent, relationships, anatomy, and diversity among other topics.","kind":"recall","origin":"ai"},{"id":"hrp1-inclusive-communication-sex-education~ai-2","moduleId":"hrp1-inclusive-communication-sex-education","stem":"In a clinical setting, what is the best approach when a patient discloses their sexual orientation?","options":[{"id":"a","text":"Announce their identity to family for support"},{"id":"b","text":"Respect their privacy and autonomy"},{"id":"c","text":"Encourage them to come out to others"},{"id":"d","text":"Dismiss the topic to avoid discomfort"}],"answerId":"b","explanation":"Respecting a patient's privacy and autonomy is crucial; disclosure should be patient-led unless safety is at risk.","kind":"trap","origin":"ai"},{"id":"hrp1-inclusive-communication-sex-education~ai-3","moduleId":"hrp1-inclusive-communication-sex-education","stem":"What mechanism contributes to reduced disclosure of sensitive health information in judgmental settings?","options":[{"id":"a","text":"Increased trust"},{"id":"b","text":"Anticipated stigma"},{"id":"c","text":"Enhanced communication"},{"id":"d","text":"Improved clinician rapport"}],"answerId":"b","explanation":"Anticipated stigma in judgmental settings leads to withholding information, reducing access to care.","kind":"mechanism","origin":"ai"},{"id":"hrp1-inclusive-communication-sex-education~ai-4","moduleId":"hrp1-inclusive-communication-sex-education","stem":"What is a potential safety risk associated with involuntary outing of a patient?","options":[{"id":"a","text":"Increased social support"},{"id":"b","text":"Enhanced patient trust"},{"id":"c","text":"Exposure to violence or rejection"},{"id":"d","text":"Improved health outcomes"}],"answerId":"c","explanation":"Involuntary outing can expose individuals to significant risks, including violence or rejection from their community.","kind":"recall","origin":"ai"},{"id":"hrp1-inclusive-communication-sex-education~ai-5","moduleId":"hrp1-inclusive-communication-sex-education","stem":"How does understanding cell signaling contribute to inclusive sexual education?","options":[{"id":"a","text":"It provides insight into hormonal changes"},{"id":"b","text":"It explains the biological basis of sexual orientation"},{"id":"c","text":"It helps in understanding communication between individuals"},{"id":"d","text":"It focuses on reproductive health only"}],"answerId":"c","explanation":"Understanding cell signaling enhances communication skills, which are vital in discussing sensitive topics in sexual education.","kind":"integration","linkedModuleIds":["cell-signaling-modes-receptors"],"origin":"ai"},{"id":"hrp1-inclusive-communication-sex-education~ai-6","moduleId":"hrp1-inclusive-communication-sex-education","stem":"Why is it important to connect patients with supportive services after discussing sexual health?","options":[{"id":"a","text":"To ensure they follow medical advice"},{"id":"b","text":"To provide them with additional resources and support"},{"id":"c","text":"To encourage them to disclose more information"},{"id":"d","text":"To limit their options for care"}],"answerId":"b","explanation":"Connecting patients with supportive services helps them access resources that can aid in their overall well-being and care.","kind":"clinical","origin":"ai"},{"id":"hrp1-inclusive-communication-sex-education~ai-7","moduleId":"hrp1-inclusive-communication-sex-education","stem":"What role does understanding gender dysphoria play in inclusive sexual education?","options":[{"id":"a","text":"It is unrelated to sexual health"},{"id":"b","text":"It helps tailor discussions to individual experiences"},{"id":"c","text":"It focuses solely on medical interventions"},{"id":"d","text":"It discourages open conversations about identity"}],"answerId":"b","explanation":"Understanding gender dysphoria allows for tailored discussions that respect individual experiences and identities in sexual education.","kind":"integration","linkedModuleIds":["hrp1-gender-dysphoria-affirming-care"],"origin":"ai"}],"hrp1-external-genital-differentiation":[{"id":"hrp1-external-genital-differentiation~ai-0","moduleId":"hrp1-external-genital-differentiation","stem":"What is the primary androgen responsible for external genital differentiation in males?","options":[{"id":"a","text":"Testosterone"},{"id":"b","text":"Dihydrotestosterone (DHT)"},{"id":"c","text":"Dehydroepiandrosterone (DHEA)"},{"id":"d","text":"Androstenedione"}],"answerId":"b","explanation":"DHT is the principal androgen that promotes the development of male external genitalia.","kind":"recall","origin":"ai"},{"id":"hrp1-external-genital-differentiation~ai-1","moduleId":"hrp1-external-genital-differentiation","stem":"Which structure develops from the labioscrotal swellings in males?","options":[{"id":"a","text":"Clitoris"},{"id":"b","text":"Labia majora"},{"id":"c","text":"Scrotum"},{"id":"d","text":"Urethra"}],"answerId":"c","explanation":"In males, the labioscrotal swellings fuse to form the scrotum.","kind":"recall","origin":"ai"},{"id":"hrp1-external-genital-differentiation~ai-2","moduleId":"hrp1-external-genital-differentiation","stem":"What is the clinical significance of hypospadias?","options":[{"id":"a","text":"It indicates a complete absence of the penis."},{"id":"b","text":"It results from incomplete fusion of urethral folds."},{"id":"c","text":"It is always associated with cryptorchidism."},{"id":"d","text":"It is a common variant of normal anatomy."}],"answerId":"b","explanation":"Hypospadias occurs due to incomplete ventral urethral-fold fusion, leading to a proximal meatus.","kind":"clinical","origin":"ai"},{"id":"hrp1-external-genital-differentiation~ai-3","moduleId":"hrp1-external-genital-differentiation","stem":"How does DHT contribute to male external genital development?","options":[{"id":"a","text":"By promoting testicular descent"},{"id":"b","text":"By elongating the genital tubercle"},{"id":"c","text":"By inhibiting AMH production"},{"id":"d","text":"By stimulating Leydig cell function"}],"answerId":"b","explanation":"DHT promotes the elongation of the genital tubercle during male development.","kind":"mechanism","origin":"ai"},{"id":"hrp1-external-genital-differentiation~ai-4","moduleId":"hrp1-external-genital-differentiation","stem":"Which of the following statements about external genital differentiation is false?","options":[{"id":"a","text":"Testosterone is converted to DHT by 5α-reductase."},{"id":"b","text":"DHT is crucial for the fusion of urethral folds."},{"id":"c","text":"The genital tubercle forms the penis in males."},{"id":"d","text":"Testosterone directly controls all external masculinization."}],"answerId":"d","explanation":"Testosterone does not directly control all external masculinization; DHT is the more potent androgen responsible for this process.","kind":"trap","origin":"ai"},{"id":"hrp1-external-genital-differentiation~ai-5","moduleId":"hrp1-external-genital-differentiation","stem":"A newborn presents with typical external female anatomy but has an absent uterus. Which hormonal action is likely responsible?","options":[{"id":"a","text":"Excess testosterone"},{"id":"b","text":"Insufficient AMH"},{"id":"c","text":"Insufficient androgen action"},{"id":"d","text":"Excess DHT"}],"answerId":"c","explanation":"Typical external female anatomy with an absent uterus can occur when AMH acted but androgen action did not.","kind":"clinical","origin":"ai"},{"id":"hrp1-external-genital-differentiation~ai-6","moduleId":"hrp1-external-genital-differentiation","stem":"How does the knowledge of external genital differentiation relate to differences in sex development (DSD)?","options":[{"id":"a","text":"It helps in understanding the role of AMH."},{"id":"b","text":"It clarifies the embryonic origins of genital structures."},{"id":"c","text":"It explains the effects of maternal hormones."},{"id":"d","text":"It is unrelated to DSD."}],"answerId":"b","explanation":"Understanding external genital differentiation is crucial for analyzing how variations in hormonal signaling can lead to DSD.","kind":"integration","linkedModuleIds":["hrp1-dsd-reproductive-anomalies"],"origin":"ai"},{"id":"hrp1-external-genital-differentiation~ai-7","moduleId":"hrp1-external-genital-differentiation","stem":"What is the relationship between external genital differentiation and gonadal differentiation?","options":[{"id":"a","text":"They occur independently of each other."},{"id":"b","text":"Gonadal differentiation precedes external genital differentiation."},{"id":"c","text":"They are both influenced by the same hormonal signals."},{"id":"d","text":"External genital differentiation is a result of gonadal differentiation."}],"answerId":"c","explanation":"Both processes are influenced by hormonal signals, particularly androgens and AMH, during embryonic development.","kind":"integration","linkedModuleIds":["hrp1-gonadal-differentiation"],"origin":"ai"}],"metabolic-bone-disease":[{"id":"metabolic-bone-disease~ai-0","moduleId":"metabolic-bone-disease","stem":"What is the primary mechanism of action of bisphosphonates in treating osteoporosis?","options":[{"id":"a","text":"Inhibit osteoblast activity"},{"id":"b","text":"Promote osteoclast apoptosis"},{"id":"c","text":"Increase calcium absorption"},{"id":"d","text":"Stimulate bone formation"}],"answerId":"b","explanation":"Bisphosphonates primarily work by inducing apoptosis in osteoclasts, thereby reducing bone resorption.","kind":"mechanism","origin":"ai"},{"id":"metabolic-bone-disease~ai-1","moduleId":"metabolic-bone-disease","stem":"A 65-year-old woman presents with a fragility fracture of the distal radius. What is the most likely underlying condition?","options":[{"id":"a","text":"Osteomalacia"},{"id":"b","text":"Osteoporosis"},{"id":"c","text":"Hyperparathyroidism"},{"id":"d","text":"Renal osteodystrophy"}],"answerId":"b","explanation":"The presentation of a fragility fracture in an older woman is characteristic of osteoporosis, which is associated with decreased bone mass.","kind":"clinical","origin":"ai"},{"id":"metabolic-bone-disease~ai-2","moduleId":"metabolic-bone-disease","stem":"Which of the following findings is characteristic of rickets in children?","options":[{"id":"a","text":"Osteoporosis"},{"id":"b","text":"Bowed legs"},{"id":"c","text":"Brown tumors"},{"id":"d","text":"Increased bone density"}],"answerId":"b","explanation":"Bowed legs are a classic clinical finding in rickets due to vitamin D deficiency, resulting in inadequate mineralization.","kind":"recall","origin":"ai"},{"id":"metabolic-bone-disease~ai-3","moduleId":"metabolic-bone-disease","stem":"What distinguishes osteoporosis from osteomalacia?","options":[{"id":"a","text":"Both have normal mineralization"},{"id":"b","text":"Osteoporosis has decreased bone mass"},{"id":"c","text":"Osteomalacia has increased bone density"},{"id":"d","text":"Osteoporosis is due to vitamin D deficiency"}],"answerId":"b","explanation":"Osteoporosis is characterized by a reduction in the quantity of normally mineralized bone, while osteomalacia involves inadequate mineralization.","kind":"trap","origin":"ai"},{"id":"metabolic-bone-disease~ai-4","moduleId":"metabolic-bone-disease","stem":"A patient with chronic kidney disease develops bone pain and fractures. What is the most likely diagnosis?","options":[{"id":"a","text":"Osteoporosis"},{"id":"b","text":"Osteomalacia"},{"id":"c","text":"Primary hyperparathyroidism"},{"id":"d","text":"Renal osteodystrophy"}],"answerId":"d","explanation":"Renal osteodystrophy is characterized by skeletal changes due to chronic kidney disease, including secondary hyperparathyroidism and osteomalacia.","kind":"clinical","origin":"ai"},{"id":"metabolic-bone-disease~ai-5","moduleId":"metabolic-bone-disease","stem":"How does vitamin D deficiency lead to osteomalacia?","options":[{"id":"a","text":"Increased osteoclast activity"},{"id":"b","text":"Decreased calcium absorption"},{"id":"c","text":"Increased bone formation"},{"id":"d","text":"Normal mineralization of bone"}],"answerId":"b","explanation":"Vitamin D deficiency leads to decreased calcium absorption, resulting in inadequate mineralization of bone.","kind":"mechanism","origin":"ai"},{"id":"metabolic-bone-disease~ai-6","moduleId":"metabolic-bone-disease","stem":"Which process is primarily responsible for bone remodeling?","options":[{"id":"a","text":"Osteoblast activity"},{"id":"b","text":"Osteoclast activity"},{"id":"c","text":"Chondrocyte activity"},{"id":"d","text":"Fibroblast activity"}],"answerId":"b","explanation":"Osteoclast activity is crucial for bone resorption during the remodeling process.","kind":"integration","linkedModuleIds":["bone-biology-remodeling"],"origin":"ai"},{"id":"metabolic-bone-disease~ai-7","moduleId":"metabolic-bone-disease","stem":"In which developmental bone disorder would you expect to see a failure of normal mineralization?","options":[{"id":"a","text":"Osteogenesis imperfecta"},{"id":"b","text":"Achondroplasia"},{"id":"c","text":"Rickets"},{"id":"d","text":"Paget's disease"}],"answerId":"c","explanation":"Rickets is characterized by a failure of normal mineralization due to vitamin D deficiency, affecting bone growth and development.","kind":"integration","linkedModuleIds":["developmental-bone-disorders"],"origin":"ai"}],"neurogenic-muscular-dystrophy":[{"id":"neurogenic-muscular-dystrophy~ai-0","moduleId":"neurogenic-muscular-dystrophy","stem":"What is the primary histological finding in Duchenne muscular dystrophy (DMD)?","options":[{"id":"a","text":"Central nuclei and degeneration/regeneration"},{"id":"b","text":"Increased type I fibers"},{"id":"c","text":"Lymphocytic infiltration"},{"id":"d","text":"Necrosis of muscle fibers"}],"answerId":"a","explanation":"DMD is characterized by variable fiber size, central nuclei, and degeneration/regeneration of muscle fibers.","kind":"recall","origin":"ai"},{"id":"neurogenic-muscular-dystrophy~ai-1","moduleId":"neurogenic-muscular-dystrophy","stem":"Which of the following best describes the mechanism of muscle weakness in spinal muscular atrophy (SMA)?","options":[{"id":"a","text":"Disruption of neuromuscular junction"},{"id":"b","text":"Anterior horn cell death"},{"id":"c","text":"Dystrophin deficiency"},{"id":"d","text":"Myofibrillar disarray"}],"answerId":"b","explanation":"SMA is caused by anterior horn cell death leading to muscle weakness.","kind":"mechanism","origin":"ai"},{"id":"neurogenic-muscular-dystrophy~ai-2","moduleId":"neurogenic-muscular-dystrophy","stem":"A 6-year-old boy presents with difficulty climbing stairs and a waddling gait. Which sign is most characteristic of Duchenne muscular dystrophy?","options":[{"id":"a","text":"Babinski sign"},{"id":"b","text":"Gowers sign"},{"id":"c","text":"Hoffman sign"},{"id":"d","text":"Tinel sign"}],"answerId":"b","explanation":"Gowers sign is indicative of proximal muscle weakness, commonly seen in Duchenne muscular dystrophy.","kind":"recall","origin":"ai"},{"id":"neurogenic-muscular-dystrophy~ai-3","moduleId":"neurogenic-muscular-dystrophy","stem":"In Duchenne muscular dystrophy, what does calf pseudohypertrophy indicate?","options":[{"id":"a","text":"Strong muscle development"},{"id":"b","text":"Fatty and fibrous replacement of muscle"},{"id":"c","text":"Increased muscle fiber size"},{"id":"d","text":"Normal muscle regeneration"}],"answerId":"b","explanation":"Calf pseudohypertrophy in DMD results from fatty and fibrous replacement of degenerated muscle, not true muscle growth.","kind":"trap","origin":"ai"},{"id":"neurogenic-muscular-dystrophy~ai-4","moduleId":"neurogenic-muscular-dystrophy","stem":"Which of the following findings is associated with neurogenic atrophy?","options":[{"id":"a","text":"Fiber-type grouping"},{"id":"b","text":"Increased creatine kinase"},{"id":"c","text":"Myofibrillar degeneration"},{"id":"d","text":"Lymphocytic infiltration"}],"answerId":"a","explanation":"Neurogenic atrophy is characterized by fiber-type grouping due to denervation and subsequent reinnervation.","kind":"recall","origin":"ai"},{"id":"neurogenic-muscular-dystrophy~ai-5","moduleId":"neurogenic-muscular-dystrophy","stem":"How does Duchenne muscular dystrophy relate to cellular adaptations?","options":[{"id":"a","text":"It demonstrates hypertrophy of muscle fibers"},{"id":"b","text":"It shows atrophy due to muscle degeneration"},{"id":"c","text":"It involves hyperplasia of muscle fibers"},{"id":"d","text":"It indicates increased muscle strength"}],"answerId":"b","explanation":"Duchenne muscular dystrophy leads to muscle atrophy due to degeneration and loss of functional muscle fibers.","kind":"integration","linkedModuleIds":["cellular-adaptations-growth"],"origin":"ai"},{"id":"neurogenic-muscular-dystrophy~ai-6","moduleId":"neurogenic-muscular-dystrophy","stem":"What is a common clinical feature of both Duchenne muscular dystrophy and neurogenic bladder disorders?","options":[{"id":"a","text":"Muscle weakness"},{"id":"b","text":"Increased muscle tone"},{"id":"c","text":"Urinary incontinence"},{"id":"d","text":"Calf pseudohypertrophy"}],"answerId":"a","explanation":"Both conditions involve muscle weakness, although the underlying mechanisms differ.","kind":"integration","linkedModuleIds":["neurogenic-bladder-disorders"],"origin":"ai"}],"rheumatoid-arthritis-drugs":[{"id":"rheumatoid-arthritis-drugs~ai-0","moduleId":"rheumatoid-arthritis-drugs","stem":"What is the primary mechanism of action of methotrexate in rheumatoid arthritis?","options":[{"id":"a","text":"Inhibition of dihydrofolate reductase"},{"id":"b","text":"Inhibition of cyclooxygenase"},{"id":"c","text":"Inhibition of interleukin-1"},{"id":"d","text":"Inhibition of tumor necrosis factor"}],"answerId":"a","explanation":"Methotrexate inhibits dihydrofolate reductase, leading to decreased lymphocyte proliferation.","kind":"mechanism","origin":"ai"},{"id":"rheumatoid-arthritis-drugs~ai-1","moduleId":"rheumatoid-arthritis-drugs","stem":"Which of the following is a common adverse effect of methotrexate?","options":[{"id":"a","text":"Retinopathy"},{"id":"b","text":"Hepatotoxicity"},{"id":"c","text":"Thromboembolism"},{"id":"d","text":"Osteoporosis"}],"answerId":"b","explanation":"Methotrexate is associated with hepatotoxicity among other side effects.","kind":"trap","origin":"ai"},{"id":"rheumatoid-arthritis-drugs~ai-2","moduleId":"rheumatoid-arthritis-drugs","stem":"Which DMARD should be avoided in pregnancy due to its teratogenic effects?","options":[{"id":"a","text":"Hydroxychloroquine"},{"id":"b","text":"Sulfasalazine"},{"id":"c","text":"Methotrexate"},{"id":"d","text":"Leflunomide"}],"answerId":"c","explanation":"Methotrexate is contraindicated in pregnancy due to its teratogenic effects.","kind":"recall","origin":"ai"},{"id":"rheumatoid-arthritis-drugs~ai-3","moduleId":"rheumatoid-arthritis-drugs","stem":"What is the risk associated with starting a TNF inhibitor in a patient with rheumatoid arthritis?","options":[{"id":"a","text":"Increased risk of retinopathy"},{"id":"b","text":"Reactivation of latent tuberculosis"},{"id":"c","text":"Increased risk of hepatotoxicity"},{"id":"d","text":"Increased risk of thromboembolism"}],"answerId":"b","explanation":"TNF inhibitors can reactivate latent tuberculosis, necessitating screening before initiation.","kind":"clinical","origin":"ai"},{"id":"rheumatoid-arthritis-drugs~ai-4","moduleId":"rheumatoid-arthritis-drugs","stem":"Which DMARD is known to cause retinopathy with long-term use?","options":[{"id":"a","text":"Methotrexate"},{"id":"b","text":"Sulfasalazine"},{"id":"c","text":"Hydroxychloroquine"},{"id":"d","text":"Leflunomide"}],"answerId":"c","explanation":"Hydroxychloroquine can cause retinopathy, especially with prolonged use.","kind":"recall","origin":"ai"},{"id":"rheumatoid-arthritis-drugs~ai-5","moduleId":"rheumatoid-arthritis-drugs","stem":"How does tofacitinib function as a DMARD in rheumatoid arthritis?","options":[{"id":"a","text":"Inhibits dihydrofolate reductase"},{"id":"b","text":"Blocks JAK-STAT signaling"},{"id":"c","text":"Inhibits TNF-alpha"},{"id":"d","text":"Inhibits interleukin-6"}],"answerId":"b","explanation":"Tofacitinib is a JAK inhibitor that blocks the JAK-STAT signaling pathway involved in inflammation.","kind":"mechanism","origin":"ai"},{"id":"rheumatoid-arthritis-drugs~ai-6","moduleId":"rheumatoid-arthritis-drugs","stem":"Which of the following drugs used in rheumatoid arthritis is also relevant in the treatment of gout?","options":[{"id":"a","text":"Methotrexate"},{"id":"b","text":"Sulfasalazine"},{"id":"c","text":"Hydroxychloroquine"},{"id":"d","text":"Leflunomide"}],"answerId":"d","explanation":"Leflunomide is a pyrimidine synthesis inhibitor that can have effects relevant to gout treatment.","kind":"integration","linkedModuleIds":["gout-drugs"],"origin":"ai"},{"id":"rheumatoid-arthritis-drugs~ai-7","moduleId":"rheumatoid-arthritis-drugs","stem":"What is a common mechanism of action shared between methotrexate and certain nucleotide drugs?","options":[{"id":"a","text":"Inhibition of dihydrofolate reductase"},{"id":"b","text":"Inhibition of purine synthesis"},{"id":"c","text":"Inhibition of pyrimidine synthesis"},{"id":"d","text":"Inhibition of cytokine signaling"}],"answerId":"a","explanation":"Both methotrexate and some nucleotide drugs inhibit dihydrofolate reductase, affecting nucleotide synthesis.","kind":"integration","linkedModuleIds":["nucleotide-drugs-disorders"],"origin":"ai"}],"osteoarthritis-rheumatoid":[{"id":"osteoarthritis-rheumatoid~ai-0","moduleId":"osteoarthritis-rheumatoid","stem":"Which of the following findings is characteristic of osteoarthritis?","options":[{"id":"a","text":"Symmetric MCP swelling"},{"id":"b","text":"Heberden nodes at DIP"},{"id":"c","text":"Prolonged morning stiffness"},{"id":"d","text":"Subcutaneous rheumatoid nodules"}],"answerId":"b","explanation":"Heberden nodes at the distal interphalangeal joints are a classic sign of osteoarthritis, distinguishing it from rheumatoid arthritis.","kind":"recall","origin":"ai"},{"id":"osteoarthritis-rheumatoid~ai-1","moduleId":"osteoarthritis-rheumatoid","stem":"What is the primary mechanism underlying rheumatoid arthritis?","options":[{"id":"a","text":"Chondrocyte injury"},{"id":"b","text":"Immune-mediated synovitis"},{"id":"c","text":"Mechanical wear and tear"},{"id":"d","text":"Subchondral bone cyst formation"}],"answerId":"b","explanation":"Rheumatoid arthritis is primarily driven by an immune-mediated process that leads to synovitis and joint erosion.","kind":"mechanism","origin":"ai"},{"id":"osteoarthritis-rheumatoid~ai-2","moduleId":"osteoarthritis-rheumatoid","stem":"Which clinical feature is most indicative of rheumatoid arthritis?","options":[{"id":"a","text":"Heberden nodes"},{"id":"b","text":"Swan-neck deformity"},{"id":"c","text":"Eburnation of bone"},{"id":"d","text":"Subchondral cysts"}],"answerId":"b","explanation":"Swan-neck deformity is a classic clinical finding associated with rheumatoid arthritis, reflecting joint instability.","kind":"clinical","origin":"ai"},{"id":"osteoarthritis-rheumatoid~ai-3","moduleId":"osteoarthritis-rheumatoid","stem":"In osteoarthritis, which of the following is a common radiological finding?","options":[{"id":"a","text":"Pannus formation"},{"id":"b","text":"Subchondral sclerosis"},{"id":"c","text":"Erosions of bone"},{"id":"d","text":"Synovial fluid accumulation"}],"answerId":"b","explanation":"Subchondral sclerosis is a common finding in osteoarthritis due to increased stress on the underlying bone.","kind":"trap","origin":"ai"},{"id":"osteoarthritis-rheumatoid~ai-4","moduleId":"osteoarthritis-rheumatoid","stem":"Which of the following statements about rheumatoid arthritis is true?","options":[{"id":"a","text":"It primarily affects the distal interphalangeal joints."},{"id":"b","text":"It is characterized by prolonged morning stiffness."},{"id":"c","text":"It has no systemic features."},{"id":"d","text":"It is more common in males."}],"answerId":"b","explanation":"Rheumatoid arthritis is known for prolonged morning stiffness and affects the small joints of the hands and feet symmetrically.","kind":"recall","origin":"ai"},{"id":"osteoarthritis-rheumatoid~ai-5","moduleId":"osteoarthritis-rheumatoid","stem":"How does the joint involvement in osteoarthritis differ from that in rheumatoid arthritis?","options":[{"id":"a","text":"OA spares the MCP joints while RA spares the DIP joints."},{"id":"b","text":"OA involves the DIP joints while RA spares them."},{"id":"c","text":"Both conditions affect the same joints equally."},{"id":"d","text":"RA primarily affects weight-bearing joints."}],"answerId":"b","explanation":"Osteoarthritis typically involves the DIP joints (Heberden nodes), while rheumatoid arthritis spares them and favors the MCP and PIP joints.","kind":"trap","origin":"ai"},{"id":"osteoarthritis-rheumatoid~ai-6","moduleId":"osteoarthritis-rheumatoid","stem":"Which of the following is a common feature of both osteoarthritis and rheumatoid arthritis?","options":[{"id":"a","text":"Morning stiffness"},{"id":"b","text":"DIP joint involvement"},{"id":"c","text":"Joint swelling"},{"id":"d","text":"Subcutaneous nodules"}],"answerId":"c","explanation":"Joint swelling can occur in both osteoarthritis and rheumatoid arthritis, though the underlying mechanisms differ.","kind":"integration","linkedModuleIds":["joint-anatomy-synovial-fluid"],"origin":"ai"},{"id":"osteoarthritis-rheumatoid~ai-7","moduleId":"osteoarthritis-rheumatoid","stem":"What is a shared characteristic of osteoarthritis and rheumatoid arthritis regarding joint pathology?","options":[{"id":"a","text":"Both involve immune-mediated damage."},{"id":"b","text":"Both lead to cartilage loss."},{"id":"c","text":"Both primarily affect the same joints."},{"id":"d","text":"Both have a female predominance."}],"answerId":"b","explanation":"Both conditions ultimately lead to cartilage loss, although through different mechanisms: mechanical wear in OA and immune-mediated damage in RA.","kind":"integration","linkedModuleIds":["spondyloarthropathies-crystal-arthritis"],"origin":"ai"}],"inflammatory-myopathies":[{"id":"inflammatory-myopathies~ai-0","moduleId":"inflammatory-myopathies","stem":"Which antibody is commonly associated with dermatomyositis?","options":[{"id":"a","text":"Anti-Jo-1"},{"id":"b","text":"Anti-Mi-2"},{"id":"c","text":"Anti-HMGCR"},{"id":"d","text":"Anti-SRP"}],"answerId":"b","explanation":"Anti-Mi-2 antibodies are specifically linked to dermatomyositis, distinguishing it from other myopathies.","kind":"recall","origin":"ai"},{"id":"inflammatory-myopathies~ai-1","moduleId":"inflammatory-myopathies","stem":"What is the primary mechanism of muscle damage in polymyositis?","options":[{"id":"a","text":"Complement-mediated microvasculopathy"},{"id":"b","text":"CD8⁺ T cell invasion"},{"id":"c","text":"Statin toxicity"},{"id":"d","text":"Autoantibody-mediated necrosis"}],"answerId":"b","explanation":"Polymyositis is characterized by CD8⁺ cytotoxic T cell invasion of non-necrotic muscle fibers.","kind":"mechanism","origin":"ai"},{"id":"inflammatory-myopathies~ai-2","moduleId":"inflammatory-myopathies","stem":"A 65-year-old man presents with asymmetric weakness of finger flexors and knee extensors. What is the most likely diagnosis?","options":[{"id":"a","text":"Dermatomyositis"},{"id":"b","text":"Inclusion body myositis"},{"id":"c","text":"Polymyositis"},{"id":"d","text":"Immune-mediated necrotizing myopathy"}],"answerId":"b","explanation":"Inclusion body myositis typically presents with asymmetric weakness in older adults, particularly affecting finger flexors and knee extensors.","kind":"clinical","origin":"ai"},{"id":"inflammatory-myopathies~ai-3","moduleId":"inflammatory-myopathies","stem":"Which finding is characteristic of immune-mediated necrotizing myopathy?","options":[{"id":"a","text":"Heliotrope rash"},{"id":"b","text":"Rimmed vacuoles"},{"id":"c","text":"Scattered necrosis with few lymphocytes"},{"id":"d","text":"Proximal muscle weakness"}],"answerId":"c","explanation":"Immune-mediated necrotizing myopathy is characterized by scattered necrosis with few inflammatory cells and specific antibodies.","kind":"recall","origin":"ai"},{"id":"inflammatory-myopathies~ai-4","moduleId":"inflammatory-myopathies","stem":"Why is malignancy screening essential in adult-onset dermatomyositis?","options":[{"id":"a","text":"It is always associated with statin use"},{"id":"b","text":"It is frequently paraneoplastic"},{"id":"c","text":"It has no associated antibodies"},{"id":"d","text":"It presents with severe muscle pain"}],"answerId":"b","explanation":"Adult dermatomyositis is often associated with underlying malignancies, making screening crucial for early detection.","kind":"trap","origin":"ai"},{"id":"inflammatory-myopathies~ai-5","moduleId":"inflammatory-myopathies","stem":"How does inclusion body myositis differ from polymyositis in terms of muscle biopsy findings?","options":[{"id":"a","text":"Presence of rimmed vacuoles"},{"id":"b","text":"Infiltration of eosinophils"},{"id":"c","text":"Perifascicular atrophy"},{"id":"d","text":"High levels of CK"}],"answerId":"a","explanation":"Inclusion body myositis is characterized by rimmed vacuoles on biopsy, unlike polymyositis.","kind":"mechanism","origin":"ai"},{"id":"inflammatory-myopathies~ai-6","moduleId":"inflammatory-myopathies","stem":"Which energy system is most affected in patients with inflammatory myopathies during prolonged exercise?","options":[{"id":"a","text":"Phosphagen system"},{"id":"b","text":"Anaerobic glycolysis"},{"id":"c","text":"Aerobic respiration"},{"id":"d","text":"Lipid metabolism"}],"answerId":"c","explanation":"Inflammatory myopathies impair muscle function, particularly affecting aerobic respiration during prolonged activities.","kind":"integration","linkedModuleIds":["muscle-energy-systems"],"origin":"ai"},{"id":"inflammatory-myopathies~ai-7","moduleId":"inflammatory-myopathies","stem":"In patients with dermatomyositis, which muscle pathology is most likely to be observed on biopsy?","options":[{"id":"a","text":"Necrotizing fibers with eosinophilic infiltrate"},{"id":"b","text":"Perifascicular atrophy"},{"id":"c","text":"Rimmed vacuoles"},{"id":"d","text":"Fibrosis without inflammation"}],"answerId":"b","explanation":"Dermatomyositis typically shows perifascicular atrophy on muscle biopsy due to complement-mediated damage.","kind":"integration","linkedModuleIds":["skeletal-muscle-sarcomere"],"origin":"ai"}],"osteomyelitis-avn-paget":[{"id":"osteomyelitis-avn-paget~ai-0","moduleId":"osteomyelitis-avn-paget","stem":"What is the most common organism causing pyogenic osteomyelitis in adults?","options":[{"id":"a","text":"Staphylococcus aureus"},{"id":"b","text":"Salmonella"},{"id":"c","text":"Escherichia coli"},{"id":"d","text":"Pseudomonas aeruginosa"}],"answerId":"a","explanation":"Staphylococcus aureus is the predominant pathogen in pyogenic osteomyelitis, especially in adults.","kind":"recall","origin":"ai"},{"id":"osteomyelitis-avn-paget~ai-1","moduleId":"osteomyelitis-avn-paget","stem":"Which histological finding is characteristic of avascular necrosis?","options":[{"id":"a","text":"Sequestrum"},{"id":"b","text":"Empty osteocyte lacunae"},{"id":"c","text":"Granulomatous inflammation"},{"id":"d","text":"Osteoclast hyperactivity"}],"answerId":"b","explanation":"Empty osteocyte lacunae indicate dead osteocytes, which is a hallmark of avascular necrosis.","kind":"recall","origin":"ai"},{"id":"osteomyelitis-avn-paget~ai-2","moduleId":"osteomyelitis-avn-paget","stem":"In Paget disease, what is the mechanism leading to the characteristic bone changes?","options":[{"id":"a","text":"Increased osteoclast activity"},{"id":"b","text":"Decreased blood flow"},{"id":"c","text":"Infection"},{"id":"d","text":"Genetic mutation affecting remodeling"}],"answerId":"d","explanation":"Paget disease is associated with genetic mutations (e.g., SQSTM1) that disrupt normal bone remodeling.","kind":"mechanism","origin":"ai"},{"id":"osteomyelitis-avn-paget~ai-3","moduleId":"osteomyelitis-avn-paget","stem":"Which imaging finding is associated with chronic pyogenic osteomyelitis?","options":[{"id":"a","text":"Cotton-wool spots"},{"id":"b","text":"Sequestrum and involucrum"},{"id":"c","text":"Empty lacunae"},{"id":"d","text":"Bowed legs"}],"answerId":"b","explanation":"Sequestrum and involucrum are classic findings in chronic pyogenic osteomyelitis seen on imaging.","kind":"recall","origin":"ai"},{"id":"osteomyelitis-avn-paget~ai-4","moduleId":"osteomyelitis-avn-paget","stem":"What is a common complication of Paget disease?","options":[{"id":"a","text":"Osteosarcoma"},{"id":"b","text":"Osteomyelitis"},{"id":"c","text":"Avascular necrosis"},{"id":"d","text":"Fractures"}],"answerId":"a","explanation":"Paget disease increases the risk of osteosarcoma due to disordered bone remodeling.","kind":"trap","origin":"ai"},{"id":"osteomyelitis-avn-paget~ai-5","moduleId":"osteomyelitis-avn-paget","stem":"How does Salmonella cause osteomyelitis in sickle cell disease patients?","options":[{"id":"a","text":"By hematogenous spread"},{"id":"b","text":"By direct invasion"},{"id":"c","text":"By opportunistic infection"},{"id":"d","text":"By secondary infection"}],"answerId":"a","explanation":"Salmonella can cause osteomyelitis through hematogenous spread, particularly in patients with sickle cell disease.","kind":"trap","origin":"ai"},{"id":"osteomyelitis-avn-paget~ai-6","moduleId":"osteomyelitis-avn-paget","stem":"How does the mechanism of bone remodeling relate to Paget disease?","options":[{"id":"a","text":"Increased osteoblast activity"},{"id":"b","text":"Increased osteoclast activity"},{"id":"c","text":"Decreased blood supply"},{"id":"d","text":"Increased mineralization"}],"answerId":"b","explanation":"Paget disease involves increased osteoclast activity leading to abnormal bone remodeling.","kind":"integration","linkedModuleIds":["bone-biology-remodeling"],"origin":"ai"},{"id":"osteomyelitis-avn-paget~ai-7","moduleId":"osteomyelitis-avn-paget","stem":"What is the relationship between osteomyelitis and the transport mechanisms in bone?","options":[{"id":"a","text":"Osteomyelitis is caused by impaired diffusion"},{"id":"b","text":"Infection alters ion transport"},{"id":"c","text":"Bone remodeling affects nutrient transport"},{"id":"d","text":"Osteomyelitis leads to increased vascular permeability"}],"answerId":"d","explanation":"Infection in osteomyelitis can lead to increased vascular permeability, affecting nutrient transport to the bone.","kind":"integration","linkedModuleIds":["plasma-membrane-transport"],"origin":"ai"}],"developmental-bone-disorders":[{"id":"developmental-bone-disorders~ai-0","moduleId":"developmental-bone-disorders","stem":"What is the most common skeletal dysplasia associated with a gain-of-function mutation in FGFR3?","options":[{"id":"a","text":"Osteogenesis imperfecta"},{"id":"b","text":"Achondroplasia"},{"id":"c","text":"Cleidocranial dysplasia"},{"id":"d","text":"Osteopetrosis"}],"answerId":"b","explanation":"Achondroplasia is the most common skeletal dysplasia caused by a gain-of-function mutation in FGFR3, leading to inhibited endochondral growth.","kind":"recall","origin":"ai"},{"id":"developmental-bone-disorders~ai-1","moduleId":"developmental-bone-disorders","stem":"Which of the following findings is characteristic of osteogenesis imperfecta?","options":[{"id":"a","text":"Short-limbed dwarfism"},{"id":"b","text":"Multiple fractures and blue sclerae"},{"id":"c","text":"Absent clavicles"},{"id":"d","text":"Dense bones that fracture easily"}],"answerId":"b","explanation":"Osteogenesis imperfecta is characterized by multiple fractures, blue sclerae, and hearing loss due to defective type I collagen.","kind":"recall","origin":"ai"},{"id":"developmental-bone-disorders~ai-2","moduleId":"developmental-bone-disorders","stem":"What is the underlying defect in osteopetrosis?","options":[{"id":"a","text":"Defective type I collagen"},{"id":"b","text":"Defective osteoclast function"},{"id":"c","text":"Loss-of-function of RUNX2"},{"id":"d","text":"Gain-of-function of FGFR3"}],"answerId":"b","explanation":"Osteopetrosis results from defective osteoclast function, leading to dense but brittle bones.","kind":"mechanism","origin":"ai"},{"id":"developmental-bone-disorders~ai-3","moduleId":"developmental-bone-disorders","stem":"Which skeletal disorder is associated with absent or hypoplastic clavicles?","options":[{"id":"a","text":"Achondroplasia"},{"id":"b","text":"Osteogenesis imperfecta"},{"id":"c","text":"Cleidocranial dysplasia"},{"id":"d","text":"Osteopetrosis"}],"answerId":"c","explanation":"Cleidocranial dysplasia is characterized by absent or hypoplastic clavicles and dental anomalies due to RUNX2 loss-of-function.","kind":"recall","origin":"ai"},{"id":"developmental-bone-disorders~ai-4","moduleId":"developmental-bone-disorders","stem":"In achondroplasia, the FGFR3 mutation leads to which of the following?","options":[{"id":"a","text":"Increased chondrocyte proliferation"},{"id":"b","text":"Decreased endochondral bone growth"},{"id":"c","text":"Increased bone density"},{"id":"d","text":"Normal limb proportions"}],"answerId":"b","explanation":"The gain-of-function mutation in FGFR3 inhibits chondrocyte proliferation, resulting in decreased endochondral bone growth.","kind":"trap","origin":"ai"},{"id":"developmental-bone-disorders~ai-5","moduleId":"developmental-bone-disorders","stem":"How does osteopetrosis relate to metabolic bone disease?","options":[{"id":"a","text":"Both involve collagen defects"},{"id":"b","text":"Both result in increased bone density"},{"id":"c","text":"Both are caused by FGFR3 mutations"},{"id":"d","text":"Both lead to short stature"}],"answerId":"b","explanation":"Osteopetrosis is a metabolic bone disease characterized by increased bone density due to defective osteoclast function.","kind":"integration","linkedModuleIds":["metabolic-bone-disease"],"origin":"ai"},{"id":"developmental-bone-disorders~ai-6","moduleId":"developmental-bone-disorders","stem":"Which condition shares a genetic basis with developmental genetic regulation?","options":[{"id":"a","text":"Osteogenesis imperfecta"},{"id":"b","text":"Achondroplasia"},{"id":"c","text":"Cleidocranial dysplasia"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"All listed conditions involve genetic mutations that affect skeletal development and regulation.","kind":"integration","linkedModuleIds":["developmental-genetic-regulation"],"origin":"ai"}],"cox-pathway-nsaids":[{"id":"cox-pathway-nsaids~ai-0","moduleId":"cox-pathway-nsaids","stem":"What is the primary mechanism by which low-dose aspirin exerts its antiplatelet effect?","options":[{"id":"a","text":"Inhibition of thromboxane A₂ synthesis"},{"id":"b","text":"Inhibition of prostacyclin synthesis"},{"id":"c","text":"Activation of platelet receptors"},{"id":"d","text":"Inhibition of phospholipase A₂"}],"answerId":"a","explanation":"Low-dose aspirin irreversibly inhibits COX-1 in platelets, leading to decreased thromboxane A₂ production, which is crucial for platelet aggregation.","kind":"mechanism","origin":"ai"},{"id":"cox-pathway-nsaids~ai-1","moduleId":"cox-pathway-nsaids","stem":"Which of the following is a characteristic of COX-2 selective inhibitors (coxibs)?","options":[{"id":"a","text":"Increased gastrointestinal bleeding risk"},{"id":"b","text":"Decreased cardiovascular risk"},{"id":"c","text":"Reduced pain and inflammation"},{"id":"d","text":"Inhibition of platelet thromboxane A₂"}],"answerId":"c","explanation":"Coxibs reduce pain and inflammation by selectively inhibiting COX-2, while sparing COX-1, which is responsible for gastrointestinal protection.","kind":"trap","origin":"ai"},{"id":"cox-pathway-nsaids~ai-2","moduleId":"cox-pathway-nsaids","stem":"What is the effect of traditional NSAIDs on COX enzymes?","options":[{"id":"a","text":"Irreversible inhibition of COX-1 only"},{"id":"b","text":"Reversible inhibition of both COX-1 and COX-2"},{"id":"c","text":"Selective inhibition of COX-2"},{"id":"d","text":"Activation of COX-1"}],"answerId":"b","explanation":"Traditional NSAIDs like ibuprofen and naproxen reversibly inhibit both COX-1 and COX-2, providing anti-inflammatory effects.","kind":"recall","origin":"ai"},{"id":"cox-pathway-nsaids~ai-3","moduleId":"cox-pathway-nsaids","stem":"Why do coxibs increase cardiovascular risk compared to traditional NSAIDs?","options":[{"id":"a","text":"They promote platelet aggregation"},{"id":"b","text":"They inhibit both COX-1 and COX-2"},{"id":"c","text":"They spare COX-1 while blocking COX-2"},{"id":"d","text":"They enhance prostacyclin production"}],"answerId":"c","explanation":"Coxibs block endothelial COX-2, reducing protective prostacyclin while sparing platelet COX-1, leading to a pro-thrombotic state.","kind":"trap","origin":"ai"},{"id":"cox-pathway-nsaids~ai-4","moduleId":"cox-pathway-nsaids","stem":"Which autacoids are primarily produced via the COX pathway?","options":[{"id":"a","text":"Leukotrienes"},{"id":"b","text":"Prostaglandins"},{"id":"c","text":"Histamines"},{"id":"d","text":"Serotonins"}],"answerId":"b","explanation":"Prostaglandins are the primary autacoids produced through the COX pathway, while leukotrienes are produced via the LOX pathway.","kind":"recall","origin":"ai"},{"id":"cox-pathway-nsaids~ai-5","moduleId":"cox-pathway-nsaids","stem":"How does the mechanism of action of low-dose aspirin differ from that of clopidogrel?","options":[{"id":"a","text":"Both irreversibly inhibit platelet aggregation"},{"id":"b","text":"Aspirin inhibits COX-1; clopidogrel inhibits ADP receptors"},{"id":"c","text":"Both are COX-2 inhibitors"},{"id":"d","text":"Clopidogrel is an irreversible COX inhibitor"}],"answerId":"b","explanation":"Aspirin irreversibly inhibits COX-1, reducing thromboxane A₂, while clopidogrel inhibits ADP receptors on platelets, preventing aggregation.","kind":"integration","linkedModuleIds":["antiplatelets"],"origin":"ai"},{"id":"cox-pathway-nsaids~ai-6","moduleId":"cox-pathway-nsaids","stem":"What is the primary reason for using NSAIDs over acetaminophen in inflammatory conditions?","options":[{"id":"a","text":"NSAIDs have a higher safety profile"},{"id":"b","text":"NSAIDs provide anti-inflammatory effects"},{"id":"c","text":"Acetaminophen is more effective for pain relief"},{"id":"d","text":"NSAIDs do not affect COX enzymes"}],"answerId":"b","explanation":"NSAIDs are preferred in inflammatory conditions because they provide anti-inflammatory effects by inhibiting COX enzymes, unlike acetaminophen.","kind":"integration","linkedModuleIds":["nsaid-acetaminophen-safety"],"origin":"ai"}],"joint-anatomy-synovial-fluid":[{"id":"joint-anatomy-synovial-fluid~ai-0","moduleId":"joint-anatomy-synovial-fluid","stem":"Which type of joint is characterized as a synarthrosis?","options":[{"id":"a","text":"Suture joints"},{"id":"b","text":"Knee joints"},{"id":"c","text":"Shoulder joints"},{"id":"d","text":"Hip joints"}],"answerId":"a","explanation":"Suture joints are classified as synarthroses, which are immovable joints.","kind":"recall","origin":"ai"},{"id":"joint-anatomy-synovial-fluid~ai-1","moduleId":"joint-anatomy-synovial-fluid","stem":"What is the primary function of type B synoviocytes in the synovial membrane?","options":[{"id":"a","text":"Phagocytosis of debris"},{"id":"b","text":"Production of hyaluronic acid"},{"id":"c","text":"Regeneration of cartilage"},{"id":"d","text":"Secretion of synovial fluid"}],"answerId":"b","explanation":"Type B synoviocytes are responsible for producing hyaluronic acid, which contributes to the viscosity of synovial fluid.","kind":"mechanism","origin":"ai"},{"id":"joint-anatomy-synovial-fluid~ai-2","moduleId":"joint-anatomy-synovial-fluid","stem":"A patient presents with cloudy joint fluid containing WBC >50,000 and >75% neutrophils. What is the most likely diagnosis?","options":[{"id":"a","text":"Osteoarthritis"},{"id":"b","text":"Rheumatoid arthritis"},{"id":"c","text":"Septic arthritis"},{"id":"d","text":"Gout"}],"answerId":"c","explanation":"The findings are indicative of septic arthritis, characterized by a high WBC count with a predominance of neutrophils.","kind":"clinical","origin":"ai"},{"id":"joint-anatomy-synovial-fluid~ai-3","moduleId":"joint-anatomy-synovial-fluid","stem":"What is the reason for the poor healing capacity of articular cartilage?","options":[{"id":"a","text":"It is bathed in nutrient-rich synovial fluid"},{"id":"b","text":"It has a rich blood supply"},{"id":"c","text":"It is avascular and aneural"},{"id":"d","text":"It regenerates rapidly after injury"}],"answerId":"c","explanation":"Articular cartilage is avascular and aneural, limiting its capacity to regenerate after injury.","kind":"trap","origin":"ai"},{"id":"joint-anatomy-synovial-fluid~ai-4","moduleId":"joint-anatomy-synovial-fluid","stem":"In a newborn, limited hip abduction is noted. What condition should be suspected?","options":[{"id":"a","text":"Developmental dysplasia of the hip"},{"id":"b","text":"Clubfoot"},{"id":"c","text":"Septic arthritis"},{"id":"d","text":"Osteoarthritis"}],"answerId":"a","explanation":"Limited hip abduction in an infant is suggestive of developmental dysplasia of the hip.","kind":"clinical","origin":"ai"},{"id":"joint-anatomy-synovial-fluid~ai-5","moduleId":"joint-anatomy-synovial-fluid","stem":"Which of the following findings is typical for non-inflammatory joint fluid analysis?","options":[{"id":"a","text":"Cloudy fluid with WBC >50,000"},{"id":"b","text":"Clear, viscous fluid with WBC <2,000"},{"id":"c","text":"Cloudy fluid with WBC 2,000–50,000"},{"id":"d","text":"Clear fluid with >75% neutrophils"}],"answerId":"b","explanation":"Non-inflammatory joint fluid is typically clear and viscous with a WBC count less than 2,000.","kind":"recall","origin":"ai"},{"id":"joint-anatomy-synovial-fluid~ai-6","moduleId":"joint-anatomy-synovial-fluid","stem":"How does synovial fluid analysis help differentiate between osteoarthritis and rheumatoid arthritis?","options":[{"id":"a","text":"By measuring joint temperature"},{"id":"b","text":"By assessing synovial fluid viscosity"},{"id":"c","text":"By determining WBC count and differential"},{"id":"d","text":"By evaluating joint mobility"}],"answerId":"c","explanation":"Synovial fluid analysis, particularly WBC count and differential, helps distinguish between osteoarthritis and inflammatory conditions like rheumatoid arthritis.","kind":"integration","linkedModuleIds":["osteoarthritis-rheumatoid"],"origin":"ai"},{"id":"joint-anatomy-synovial-fluid~ai-7","moduleId":"joint-anatomy-synovial-fluid","stem":"What is a common synovial fluid finding in gout compared to septic arthritis?","options":[{"id":"a","text":"Higher WBC count"},{"id":"b","text":"Presence of monosodium urate crystals"},{"id":"c","text":"Clear fluid appearance"},{"id":"d","text":"Increased viscosity"}],"answerId":"b","explanation":"Gout is characterized by the presence of monosodium urate crystals in the synovial fluid, unlike septic arthritis.","kind":"integration","linkedModuleIds":["spondyloarthropathies-crystal-arthritis"],"origin":"ai"}],"metabolic-toxic-nmj-myopathy":[{"id":"metabolic-toxic-nmj-myopathy~ai-0","moduleId":"metabolic-toxic-nmj-myopathy","stem":"What is the primary defect in McArdle disease?","options":[{"id":"a","text":"Deficiency of myophosphorylase"},{"id":"b","text":"Deficiency of acid maltase"},{"id":"c","text":"Deficiency of carnitine"},{"id":"d","text":"Deficiency of ATP synthase"}],"answerId":"a","explanation":"McArdle disease is caused by a deficiency of myophosphorylase, leading to impaired glycogen breakdown in muscle.","kind":"recall","origin":"ai"},{"id":"metabolic-toxic-nmj-myopathy~ai-1","moduleId":"metabolic-toxic-nmj-myopathy","stem":"Which finding is characteristic of myasthenia gravis?","options":[{"id":"a","text":"Proximal weakness improving with use"},{"id":"b","text":"Fatigable ptosis"},{"id":"c","text":"Ragged-red fibers"},{"id":"d","text":"Myoglobinuria after exercise"}],"answerId":"b","explanation":"Fatigable ptosis is a classic symptom of myasthenia gravis due to the postsynaptic nature of the disorder.","kind":"recall","origin":"ai"},{"id":"metabolic-toxic-nmj-myopathy~ai-2","moduleId":"metabolic-toxic-nmj-myopathy","stem":"What mechanism underlies the weakness in Lambert-Eaton myasthenic syndrome?","options":[{"id":"a","text":"Inhibition of postsynaptic ACh receptors"},{"id":"b","text":"Deficiency of calcium channels"},{"id":"c","text":"Inhibition of presynaptic calcium channels"},{"id":"d","text":"Destruction of muscle fibers"}],"answerId":"c","explanation":"LEMS is characterized by antibodies that inhibit presynaptic voltage-gated calcium channels, reducing acetylcholine release.","kind":"mechanism","origin":"ai"},{"id":"metabolic-toxic-nmj-myopathy~ai-3","moduleId":"metabolic-toxic-nmj-myopathy","stem":"In which condition do patients experience exercise-induced cramps and myoglobinuria?","options":[{"id":"a","text":"Pompe disease"},{"id":"b","text":"McArdle disease"},{"id":"c","text":"Myasthenia gravis"},{"id":"d","text":"Lambert-Eaton syndrome"}],"answerId":"b","explanation":"McArdle disease is associated with exercise-induced cramps and myoglobinuria due to impaired glycogen metabolism.","kind":"recall","origin":"ai"},{"id":"metabolic-toxic-nmj-myopathy~ai-4","moduleId":"metabolic-toxic-nmj-myopathy","stem":"Which statement correctly differentiates myasthenia gravis from Lambert-Eaton syndrome?","options":[{"id":"a","text":"Both improve with cholinesterase inhibitors"},{"id":"b","text":"Both worsen with sustained activity"},{"id":"c","text":"MG fatigues with use, LEMS improves with use"},{"id":"d","text":"LEMS has no autonomic symptoms"}],"answerId":"c","explanation":"Myasthenia gravis fatigues with use due to postsynaptic receptor loss, while LEMS improves with repeated use due to presynaptic calcium channel effects.","kind":"trap","origin":"ai"},{"id":"metabolic-toxic-nmj-myopathy~ai-5","moduleId":"metabolic-toxic-nmj-myopathy","stem":"How does mitochondrial myopathy typically present on muscle biopsy?","options":[{"id":"a","text":"Ragged-red fibers"},{"id":"b","text":"Type II fiber atrophy"},{"id":"c","text":"Necrotic fibers"},{"id":"d","text":"Inflammatory infiltrates"}],"answerId":"a","explanation":"Mitochondrial myopathy is characterized by the presence of ragged-red fibers on muscle biopsy.","kind":"recall","origin":"ai"},{"id":"metabolic-toxic-nmj-myopathy~ai-6","moduleId":"metabolic-toxic-nmj-myopathy","stem":"How does a deficiency in carnitine affect muscle metabolism?","options":[{"id":"a","text":"Increases glycogen storage"},{"id":"b","text":"Decreases fatty acid oxidation"},{"id":"c","text":"Increases ATP production"},{"id":"d","text":"Decreases glucose uptake"}],"answerId":"b","explanation":"Carnitine deficiency impairs fatty acid oxidation, leading to lipid myopathy and exertional myonecrosis.","kind":"mechanism","origin":"ai"},{"id":"metabolic-toxic-nmj-myopathy~ai-7","moduleId":"metabolic-toxic-nmj-myopathy","stem":"How does the energy system knowledge from the Energy Systems of Skeletal Muscle module relate to McArdle disease?","options":[{"id":"a","text":"Both involve mitochondrial dysfunction"},{"id":"b","text":"Both involve impaired glycogen metabolism"},{"id":"c","text":"Both are caused by autoimmune mechanisms"},{"id":"d","text":"Both lead to muscle wasting"}],"answerId":"b","explanation":"McArdle disease is a glycogen storage disorder, directly linking to the energy metabolism discussed in the Energy Systems module.","kind":"integration","linkedModuleIds":["muscle-energy-systems"],"origin":"ai"},{"id":"metabolic-toxic-nmj-myopathy~ai-8","moduleId":"metabolic-toxic-nmj-myopathy","stem":"What common symptom connects myasthenia gravis and Lambert-Eaton syndrome as discussed in the NMJ Pharmacology & Disorders module?","options":[{"id":"a","text":"Fatigable weakness"},{"id":"b","text":"Proximal muscle weakness"},{"id":"c","text":"Ocular symptoms"},{"id":"d","text":"Improvement with cholinesterase inhibitors"}],"answerId":"a","explanation":"Both conditions present with fatigable weakness, although the mechanisms and responses to treatment differ significantly.","kind":"integration","linkedModuleIds":["nmj-drugs-disorders"],"origin":"ai"}],"nsaid-acetaminophen-safety":[{"id":"nsaid-acetaminophen-safety~ai-0","moduleId":"nsaid-acetaminophen-safety","stem":"What is the primary mechanism by which NSAIDs can lead to acute kidney injury when combined with an ACE inhibitor and diuretic?","options":[{"id":"a","text":"Inhibition of COX-2"},{"id":"b","text":"Inhibition of prostaglandin synthesis"},{"id":"c","text":"Increased renal blood flow"},{"id":"d","text":"Decreased glomerular filtration rate"}],"answerId":"b","explanation":"NSAIDs inhibit prostaglandin synthesis, which is crucial for maintaining renal blood flow, leading to decreased glomerular filtration rate and potential acute kidney injury.","kind":"mechanism","origin":"ai"},{"id":"nsaid-acetaminophen-safety~ai-1","moduleId":"nsaid-acetaminophen-safety","stem":"Which of the following is a contraindication for NSAID use during pregnancy?","options":[{"id":"a","text":"First-trimester use"},{"id":"b","text":"Third-trimester use"},{"id":"c","text":"Use in preterm infants"},{"id":"d","text":"Use in patients with asthma"}],"answerId":"b","explanation":"NSAIDs are contraindicated in the third trimester due to the risk of premature closure of the ductus arteriosus.","kind":"recall","origin":"ai"},{"id":"nsaid-acetaminophen-safety~ai-2","moduleId":"nsaid-acetaminophen-safety","stem":"A child presents with encephalopathy and hepatic dysfunction after receiving aspirin for fever. What condition is this most likely indicative of?","options":[{"id":"a","text":"Acetaminophen toxicity"},{"id":"b","text":"Reye syndrome"},{"id":"c","text":"Salicylate overdose"},{"id":"d","text":"Acute liver failure"}],"answerId":"b","explanation":"These symptoms are characteristic of Reye syndrome, which occurs in children given aspirin during viral illnesses.","kind":"recall","origin":"ai"},{"id":"nsaid-acetaminophen-safety~ai-3","moduleId":"nsaid-acetaminophen-safety","stem":"What is the antidote for acetaminophen toxicity?","options":[{"id":"a","text":"Activated charcoal"},{"id":"b","text":"N-acetylcysteine"},{"id":"c","text":"Flumazenil"},{"id":"d","text":"Atropine"}],"answerId":"b","explanation":"N-acetylcysteine replenishes glutathione and is the specific antidote for acetaminophen toxicity.","kind":"recall","origin":"ai"},{"id":"nsaid-acetaminophen-safety~ai-4","moduleId":"nsaid-acetaminophen-safety","stem":"Which statement about acetaminophen in inflammatory diseases is correct?","options":[{"id":"a","text":"It can replace NSAIDs for pain relief"},{"id":"b","text":"It has significant anti-inflammatory effects"},{"id":"c","text":"It is safe for chronic use in rheumatoid arthritis"},{"id":"d","text":"It is not an adequate substitute for NSAIDs in inflammatory joint disease"}],"answerId":"d","explanation":"Acetaminophen has minimal anti-inflammatory activity and is not a substitute for NSAIDs in inflammatory joint disease.","kind":"trap","origin":"ai"},{"id":"nsaid-acetaminophen-safety~ai-5","moduleId":"nsaid-acetaminophen-safety","stem":"In a patient with acetaminophen overdose, which laboratory finding would you expect?","options":[{"id":"a","text":"Increased serum creatinine"},{"id":"b","text":"Increased serum transaminases"},{"id":"c","text":"Decreased blood glucose"},{"id":"d","text":"Increased blood urea nitrogen"}],"answerId":"b","explanation":"Acetaminophen overdose leads to hepatotoxicity, which is reflected by increased serum transaminases.","kind":"recall","origin":"ai"},{"id":"nsaid-acetaminophen-safety~ai-6","moduleId":"nsaid-acetaminophen-safety","stem":"How does NAPQI contribute to acetaminophen toxicity?","options":[{"id":"a","text":"It enhances glutathione synthesis"},{"id":"b","text":"It depletes glutathione stores"},{"id":"c","text":"It increases hepatic blood flow"},{"id":"d","text":"It inhibits cytochrome P450 enzymes"}],"answerId":"b","explanation":"NAPQI is a toxic metabolite that depletes glutathione, leading to hepatotoxicity in acetaminophen overdose.","kind":"mechanism","origin":"ai"},{"id":"nsaid-acetaminophen-safety~ai-7","moduleId":"nsaid-acetaminophen-safety","stem":"Which of the following is a potential complication of NSAID use in patients with renal impairment?","options":[{"id":"a","text":"Decreased risk of GI bleeding"},{"id":"b","text":"Increased glomerular filtration rate"},{"id":"c","text":"Acute kidney injury"},{"id":"d","text":"Enhanced renal perfusion"}],"answerId":"c","explanation":"NSAIDs can lead to acute kidney injury, especially in patients with renal impairment due to their effect on prostaglandin synthesis.","kind":"integration","linkedModuleIds":["nephrotoxic-drugs"],"origin":"ai"},{"id":"nsaid-acetaminophen-safety~ai-8","moduleId":"nsaid-acetaminophen-safety","stem":"What is a common finding in patients with acetaminophen overdose that links to hepatic injury?","options":[{"id":"a","text":"Increased creatinine"},{"id":"b","text":"Elevated bilirubin"},{"id":"c","text":"Decreased albumin"},{"id":"d","text":"Increased INR"}],"answerId":"d","explanation":"Increased INR indicates impaired liver function due to hepatotoxicity from acetaminophen overdose.","kind":"integration","linkedModuleIds":["napqi-glutathione-nac"],"origin":"ai"}],"spondyloarthropathies-crystal-arthritis":[{"id":"spondyloarthropathies-crystal-arthritis~ai-0","moduleId":"spondyloarthropathies-crystal-arthritis","stem":"A 28-year-old man presents with inflammatory back pain and morning stiffness. Imaging reveals bilateral sacroiliitis and a 'bamboo spine' appearance. What is the most likely diagnosis?","options":[{"id":"a","text":"Reactive arthritis"},{"id":"b","text":"Ankylosing spondylitis"},{"id":"c","text":"Psoriatic arthritis"},{"id":"d","text":"Gout"}],"answerId":"b","explanation":"The symptoms and imaging findings are characteristic of ankylosing spondylitis, particularly in a young male with HLA-B27 positivity.","kind":"clinical","origin":"ai"},{"id":"spondyloarthropathies-crystal-arthritis~ai-1","moduleId":"spondyloarthropathies-crystal-arthritis","stem":"Which of the following crystals is associated with gout?","options":[{"id":"a","text":"Rhomboid, positively birefringent"},{"id":"b","text":"Needle-shaped, negatively birefringent"},{"id":"c","text":"Rhomboid, negatively birefringent"},{"id":"d","text":"Needle-shaped, positively birefringent"}],"answerId":"b","explanation":"Gout is characterized by monosodium urate crystals that are needle-shaped and negatively birefringent under polarized light.","kind":"recall","origin":"ai"},{"id":"spondyloarthropathies-crystal-arthritis~ai-2","moduleId":"spondyloarthropathies-crystal-arthritis","stem":"A patient presents with knee pain and chondrocalcinosis on X-ray. Joint aspiration reveals rhomboid, positively birefringent crystals. What is the most likely diagnosis?","options":[{"id":"a","text":"Gout"},{"id":"b","text":"Pseudogout"},{"id":"c","text":"Ankylosing spondylitis"},{"id":"d","text":"Reactive arthritis"}],"answerId":"b","explanation":"The presence of rhomboid, positively birefringent crystals and chondrocalcinosis indicates pseudogout (calcium pyrophosphate dihydrate crystal deposition).","kind":"clinical","origin":"ai"},{"id":"spondyloarthropathies-crystal-arthritis~ai-3","moduleId":"spondyloarthropathies-crystal-arthritis","stem":"Which of the following is a common risk factor for developing gout?","options":[{"id":"a","text":"Hypothyroidism"},{"id":"b","text":"Obesity"},{"id":"c","text":"Hemochromatosis"},{"id":"d","text":"Hyperparathyroidism"}],"answerId":"b","explanation":"Obesity is a well-known risk factor for hyperuricemia and gout due to increased production of uric acid.","kind":"recall","origin":"ai"},{"id":"spondyloarthropathies-crystal-arthritis~ai-4","moduleId":"spondyloarthropathies-crystal-arthritis","stem":"In a patient with a hot, swollen joint, which of the following pathogens is most commonly associated with acute suppurative arthritis?","options":[{"id":"a","text":"Staphylococcus aureus"},{"id":"b","text":"Mycobacterium tuberculosis"},{"id":"c","text":"Chlamydia trachomatis"},{"id":"d","text":"Salmonella"}],"answerId":"a","explanation":"Staphylococcus aureus is the most common cause of acute suppurative arthritis, necessitating joint aspiration for diagnosis.","kind":"recall","origin":"ai"},{"id":"spondyloarthropathies-crystal-arthritis~ai-5","moduleId":"spondyloarthropathies-crystal-arthritis","stem":"A 50-year-old woman with a history of hyperparathyroidism presents with knee pain and swelling. Joint fluid analysis shows rhomboid, positively birefringent crystals. Which condition is most likely?","options":[{"id":"a","text":"Gout"},{"id":"b","text":"Pseudogout"},{"id":"c","text":"Ankylosing spondylitis"},{"id":"d","text":"Reactive arthritis"}],"answerId":"b","explanation":"The combination of hyperparathyroidism and the presence of rhomboid, positively birefringent crystals suggests pseudogout (CPPD).","kind":"integration","linkedModuleIds":["osteoarthritis-rheumatoid"],"origin":"ai"},{"id":"spondyloarthropathies-crystal-arthritis~ai-6","moduleId":"spondyloarthropathies-crystal-arthritis","stem":"A patient with a history of inflammatory back pain is found to have HLA-B27 positivity. Which other joint condition could this patient be at risk for?","options":[{"id":"a","text":"Osteoarthritis"},{"id":"b","text":"Rheumatoid arthritis"},{"id":"c","text":"Gout"},{"id":"d","text":"Reactive arthritis"}],"answerId":"d","explanation":"HLA-B27 positivity is associated with several spondyloarthropathies, including reactive arthritis, which can occur after infections.","kind":"integration","linkedModuleIds":["joint-anatomy-synovial-fluid"],"origin":"ai"},{"id":"spondyloarthropathies-crystal-arthritis~ai-7","moduleId":"spondyloarthropathies-crystal-arthritis","stem":"Which of the following statements about crystal birefringence is true?","options":[{"id":"a","text":"Positively birefringent needle-shaped crystals indicate gout"},{"id":"b","text":"Negatively birefringent rhomboid crystals indicate gout"},{"id":"c","text":"Needle-shaped crystals are always associated with pseudogout"},{"id":"d","text":"Negatively birefringent needle-shaped crystals indicate gout"}],"answerId":"d","explanation":"Gout is characterized by negatively birefringent needle-shaped crystals, while pseudogout is associated with positively birefringent rhomboid crystals.","kind":"trap","origin":"ai"}],"rehab-thermotherapy-electrotherapy":[{"id":"rehab-thermotherapy-electrotherapy~ai-0","moduleId":"rehab-thermotherapy-electrotherapy","stem":"What is the primary mechanism by which heat therapy alleviates chronic muscle pain?","options":[{"id":"a","text":"Vasoconstriction"},{"id":"b","text":"Increased blood flow"},{"id":"c","text":"Decreased nerve conduction"},{"id":"d","text":"Reduced inflammation"}],"answerId":"b","explanation":"Heat therapy increases blood flow, which enhances tissue healing and reduces muscle stiffness.","kind":"mechanism","origin":"ai"},{"id":"rehab-thermotherapy-electrotherapy~ai-1","moduleId":"rehab-thermotherapy-electrotherapy","stem":"Which of the following is a contraindication for the use of electrotherapy?","options":[{"id":"a","text":"Chronic pain"},{"id":"b","text":"Pregnancy"},{"id":"c","text":"Muscle disuse"},{"id":"d","text":"Myofascial pain"}],"answerId":"b","explanation":"Electrotherapy is contraindicated over the pregnant abdomen/pelvis due to potential risks to the fetus.","kind":"trap","origin":"ai"},{"id":"rehab-thermotherapy-electrotherapy~ai-2","moduleId":"rehab-thermotherapy-electrotherapy","stem":"In the first 24-48 hours following an acute ankle sprain, which modality is recommended?","options":[{"id":"a","text":"Heat therapy"},{"id":"b","text":"Cryotherapy"},{"id":"c","text":"Ultrasound"},{"id":"d","text":"TENS"}],"answerId":"b","explanation":"Cryotherapy is recommended to reduce swelling and inflammation during the acute phase.","kind":"recall","origin":"ai"},{"id":"rehab-thermotherapy-electrotherapy~ai-3","moduleId":"rehab-thermotherapy-electrotherapy","stem":"What is the mechanism by which TENS alleviates pain?","options":[{"id":"a","text":"Increased blood flow"},{"id":"b","text":"Endogenous opioid release"},{"id":"c","text":"Vasoconstriction"},{"id":"d","text":"Muscle contraction"}],"answerId":"b","explanation":"TENS works by activating large Aβ fibers and promoting the release of endogenous opioids.","kind":"mechanism","origin":"ai"},{"id":"rehab-thermotherapy-electrotherapy~ai-4","moduleId":"rehab-thermotherapy-electrotherapy","stem":"A patient presents with chronic stiffness in an arthritic joint. Which treatment is most appropriate?","options":[{"id":"a","text":"Cryotherapy"},{"id":"b","text":"Heat therapy"},{"id":"c","text":"Iontophoresis"},{"id":"d","text":"NMES"}],"answerId":"b","explanation":"Heat therapy is effective for chronic stiffness as it increases blood flow and tissue extensibility.","kind":"clinical","origin":"ai"},{"id":"rehab-thermotherapy-electrotherapy~ai-5","moduleId":"rehab-thermotherapy-electrotherapy","stem":"When selecting a modality for a patient with muscle disuse atrophy, which is the best choice?","options":[{"id":"a","text":"Cryotherapy"},{"id":"b","text":"Heat therapy"},{"id":"c","text":"NMES"},{"id":"d","text":"TENS"}],"answerId":"c","explanation":"NMES is effective in stimulating muscle contraction to prevent disuse atrophy.","kind":"clinical","origin":"ai"},{"id":"rehab-thermotherapy-electrotherapy~ai-6","moduleId":"rehab-thermotherapy-electrotherapy","stem":"How does the choice of modality differ between acute and chronic injuries?","options":[{"id":"a","text":"Both require heat therapy"},{"id":"b","text":"Acute injuries use heat, chronic use cold"},{"id":"c","text":"Acute injuries use cold, chronic use heat"},{"id":"d","text":"Both require cryotherapy"}],"answerId":"c","explanation":"Acute injuries benefit from cryotherapy to reduce inflammation, while chronic injuries benefit from heat to enhance blood flow.","kind":"integration","linkedModuleIds":["rehab-modalities-selection"],"origin":"ai"},{"id":"rehab-thermotherapy-electrotherapy~ai-7","moduleId":"rehab-thermotherapy-electrotherapy","stem":"Which of the following modalities is contraindicated in a patient with a pacemaker?","options":[{"id":"a","text":"Cryotherapy"},{"id":"b","text":"TENS"},{"id":"c","text":"Heat therapy"},{"id":"d","text":"NMES"}],"answerId":"b","explanation":"TENS is contraindicated in patients with pacemakers due to the risk of interference with cardiac devices.","kind":"trap","origin":"ai"}],"posterior-pituitary-syndromes":[{"id":"posterior-pituitary-syndromes~ai-0","moduleId":"posterior-pituitary-syndromes","stem":"What is the primary cause of central diabetes insipidus?","options":[{"id":"a","text":"ADH receptor resistance"},{"id":"b","text":"ADH deficiency"},{"id":"c","text":"Excessive ADH secretion"},{"id":"d","text":"Increased renal clearance of water"}],"answerId":"b","explanation":"Central diabetes insipidus is primarily due to a deficiency of ADH, often resulting from trauma or tumors affecting the hypothalamus or pituitary gland.","kind":"recall","origin":"ai"},{"id":"posterior-pituitary-syndromes~ai-1","moduleId":"posterior-pituitary-syndromes","stem":"In SIADH, what is the expected urine osmolality compared to serum osmolality?","options":[{"id":"a","text":"Lower than serum osmolality"},{"id":"b","text":"Equal to serum osmolality"},{"id":"c","text":"Higher than serum osmolality"},{"id":"d","text":"Unpredictable compared to serum osmolality"}],"answerId":"c","explanation":"In SIADH, urine osmolality is higher than serum osmolality due to excessive reabsorption of water, leading to concentrated urine.","kind":"mechanism","origin":"ai"},{"id":"posterior-pituitary-syndromes~ai-2","moduleId":"posterior-pituitary-syndromes","stem":"A patient presents with polyuria that does not improve with desmopressin. What condition is most likely?","options":[{"id":"a","text":"Central diabetes insipidus"},{"id":"b","text":"Nephrogenic diabetes insipidus"},{"id":"c","text":"SIADH"},{"id":"d","text":"Psychogenic polydipsia"}],"answerId":"b","explanation":"Polyuria that does not respond to desmopressin indicates nephrogenic diabetes insipidus, where the kidneys are unresponsive to ADH.","kind":"clinical","origin":"ai"},{"id":"posterior-pituitary-syndromes~ai-3","moduleId":"posterior-pituitary-syndromes","stem":"Which of the following correctly describes the serum sodium levels in diabetes insipidus?","options":[{"id":"a","text":"Low due to water loss"},{"id":"b","text":"Normal due to compensatory mechanisms"},{"id":"c","text":"High due to free-water loss"},{"id":"d","text":"Variable depending on fluid intake"}],"answerId":"c","explanation":"In diabetes insipidus, serum sodium levels are high due to free-water loss, leading to hypernatremia.","kind":"trap","origin":"ai"},{"id":"posterior-pituitary-syndromes~ai-4","moduleId":"posterior-pituitary-syndromes","stem":"What is the most common cause of SIADH?","options":[{"id":"a","text":"CNS trauma"},{"id":"b","text":"Small-cell lung carcinoma"},{"id":"c","text":"Medications"},{"id":"d","text":"Chronic kidney disease"}],"answerId":"b","explanation":"The most common cause of SIADH is ectopic ADH secretion from small-cell lung carcinoma.","kind":"recall","origin":"ai"},{"id":"posterior-pituitary-syndromes~ai-5","moduleId":"posterior-pituitary-syndromes","stem":"How does the mechanism of water balance differ between diabetes insipidus and SIADH?","options":[{"id":"a","text":"DI involves excess ADH, while SIADH involves deficiency"},{"id":"b","text":"DI involves deficiency of ADH, while SIADH involves excess"},{"id":"c","text":"Both involve normal ADH levels"},{"id":"d","text":"DI affects renal function, while SIADH does not"}],"answerId":"b","explanation":"Diabetes insipidus is characterized by a deficiency of ADH, leading to water loss, while SIADH is characterized by excess ADH, leading to water retention.","kind":"integration","linkedModuleIds":["sodium-water-disorders"],"origin":"ai"},{"id":"posterior-pituitary-syndromes~ai-6","moduleId":"posterior-pituitary-syndromes","stem":"In a patient with SIADH, what would you expect the serum osmolality to be?","options":[{"id":"a","text":"Increased"},{"id":"b","text":"Decreased"},{"id":"c","text":"Normal"},{"id":"d","text":"Variable"}],"answerId":"a","explanation":"In SIADH, serum osmolality is decreased due to dilution from excess water retention.","kind":"integration","linkedModuleIds":["body-fluid-compartments-renal"],"origin":"ai"}],"tumor-classification-grading":[{"id":"tumor-classification-grading~ai-0","moduleId":"tumor-classification-grading","stem":"What suffix is used to denote a benign tumor of fat?","options":[{"id":"a","text":"-oma"},{"id":"b","text":"-sarcoma"},{"id":"c","text":"-carcinoma"},{"id":"d","text":"-blastoma"}],"answerId":"a","explanation":"The suffix '-oma' indicates a benign tumor, such as lipoma for fat.","kind":"recall","origin":"ai"},{"id":"tumor-classification-grading~ai-1","moduleId":"tumor-classification-grading","stem":"Which feature is NOT characteristic of intermediate tumors?","options":[{"id":"a","text":"Locally aggressive"},{"id":"b","text":"Recurs"},{"id":"c","text":"Metastasizes"},{"id":"d","text":"Rarely metastasizes"}],"answerId":"c","explanation":"Intermediate tumors, like desmoid fibromatosis, are locally aggressive and recur but rarely metastasize.","kind":"trap","origin":"ai"},{"id":"tumor-classification-grading~ai-2","moduleId":"tumor-classification-grading","stem":"A biopsy shows high mitotic count and necrosis. What is the FNCLCC grade likely to be?","options":[{"id":"a","text":"Grade 1"},{"id":"b","text":"Grade 2"},{"id":"c","text":"Grade 3"},{"id":"d","text":"Not applicable"}],"answerId":"c","explanation":"High mitotic count and necrosis indicate a high FNCLCC grade, which correlates with worse prognosis.","kind":"mechanism","origin":"ai"},{"id":"tumor-classification-grading~ai-3","moduleId":"tumor-classification-grading","stem":"A 45-year-old presents with a deep, large mass in the extremity. What is the most concerning diagnosis?","options":[{"id":"a","text":"Lipoma"},{"id":"b","text":"Desmoid fibromatosis"},{"id":"c","text":"Soft-tissue sarcoma"},{"id":"d","text":"Hemangioma"}],"answerId":"c","explanation":"A deep, large mass in the extremity raises concern for a soft-tissue sarcoma, which can be malignant.","kind":"clinical","origin":"ai"},{"id":"tumor-classification-grading~ai-4","moduleId":"tumor-classification-grading","stem":"Which of the following features indicates a poor prognosis in tumors?","options":[{"id":"a","text":"Young age"},{"id":"b","text":"Small size"},{"id":"c","text":"Low grade"},{"id":"d","text":"Metastasis"}],"answerId":"d","explanation":"Metastasis is a poor-prognosis feature, indicating advanced disease.","kind":"recall","origin":"ai"},{"id":"tumor-classification-grading~ai-5","moduleId":"tumor-classification-grading","stem":"How does the FNCLCC grading system influence prognosis in soft-tissue sarcomas?","options":[{"id":"a","text":"It determines the tumor's size"},{"id":"b","text":"It assesses the risk of metastasis"},{"id":"c","text":"It evaluates the patient's age"},{"id":"d","text":"It classifies the tumor as benign or malignant"}],"answerId":"b","explanation":"The FNCLCC grading system assesses differentiation, mitotic count, and necrosis, which directly influence metastatic risk and prognosis.","kind":"integration","linkedModuleIds":["neoplasia-differentiation-invasion"],"origin":"ai"},{"id":"tumor-classification-grading~ai-6","moduleId":"tumor-classification-grading","stem":"What is the primary distinction between benign and malignant tumors based on behavior?","options":[{"id":"a","text":"Benign tumors are always encapsulated"},{"id":"b","text":"Malignant tumors invade surrounding tissues"},{"id":"c","text":"Benign tumors can metastasize"},{"id":"d","text":"Malignant tumors are always larger"}],"answerId":"b","explanation":"Malignant tumors are characterized by their ability to invade surrounding tissues, distinguishing them from benign tumors.","kind":"integration","linkedModuleIds":["neoplasia-nomenclature"],"origin":"ai"}],"osteoporosis-drugs":[{"id":"osteoporosis-drugs~ai-0","moduleId":"osteoporosis-drugs","stem":"What is the first-line treatment for osteoporosis?","options":[{"id":"a","text":"Calcium and vitamin D"},{"id":"b","text":"Denosumab"},{"id":"c","text":"Bisphosphonates"},{"id":"d","text":"Teriparatide"}],"answerId":"c","explanation":"Bisphosphonates are the first-line treatment for osteoporosis due to their efficacy in reducing fracture risk.","kind":"recall","origin":"ai"},{"id":"osteoporosis-drugs~ai-1","moduleId":"osteoporosis-drugs","stem":"Which mechanism describes the action of bisphosphonates?","options":[{"id":"a","text":"Inhibit osteoblast activity"},{"id":"b","text":"Stimulate osteoclast apoptosis"},{"id":"c","text":"Increase calcium absorption"},{"id":"d","text":"Enhance vitamin D metabolism"}],"answerId":"b","explanation":"Bisphosphonates are pyrophosphate analogs that are taken up by osteoclasts, leading to their apoptosis.","kind":"mechanism","origin":"ai"},{"id":"osteoporosis-drugs~ai-2","moduleId":"osteoporosis-drugs","stem":"A patient on bisphosphonates presents with a non-healing jaw wound after dental work. What is the likely diagnosis?","options":[{"id":"a","text":"Atypical femoral fracture"},{"id":"b","text":"Osteonecrosis of the jaw"},{"id":"c","text":"Venous thromboembolism"},{"id":"d","text":"Esophagitis"}],"answerId":"b","explanation":"The presentation is consistent with osteonecrosis of the jaw, a known complication of bisphosphonate therapy.","kind":"clinical","origin":"ai"},{"id":"osteoporosis-drugs~ai-3","moduleId":"osteoporosis-drugs","stem":"Which of the following is a common adverse effect of SERMs like raloxifene?","options":[{"id":"a","text":"Osteonecrosis of the jaw"},{"id":"b","text":"Venous thromboembolism"},{"id":"c","text":"Atypical femoral fracture"},{"id":"d","text":"Gastritis"}],"answerId":"b","explanation":"SERMs can increase the risk of venous thromboembolism due to their estrogen-like effects.","kind":"trap","origin":"ai"},{"id":"osteoporosis-drugs~ai-4","moduleId":"osteoporosis-drugs","stem":"What is the correct way to take oral bisphosphonates?","options":[{"id":"a","text":"With food and lying down"},{"id":"b","text":"On an empty stomach and sitting upright"},{"id":"c","text":"With calcium supplements"},{"id":"d","text":"Any time during the day"}],"answerId":"b","explanation":"Oral bisphosphonates should be taken on an empty stomach with water and the patient should remain upright for 30–60 minutes to prevent esophagitis.","kind":"trap","origin":"ai"},{"id":"osteoporosis-drugs~ai-5","moduleId":"osteoporosis-drugs","stem":"How does denosumab exert its effects in osteoporosis treatment?","options":[{"id":"a","text":"Inhibits osteoblasts"},{"id":"b","text":"Inhibits RANKL"},{"id":"c","text":"Stimulates osteoclasts"},{"id":"d","text":"Enhances calcium absorption"}],"answerId":"b","explanation":"Denosumab is an anti-RANKL monoclonal antibody that decreases osteoclast formation, similar to the action of OPG.","kind":"mechanism","origin":"ai"},{"id":"osteoporosis-drugs~ai-6","moduleId":"osteoporosis-drugs","stem":"Which hormone is primarily responsible for increasing serum calcium levels?","options":[{"id":"a","text":"Calcitonin"},{"id":"b","text":"Parathyroid hormone"},{"id":"c","text":"Estrogen"},{"id":"d","text":"Vitamin D"}],"answerId":"b","explanation":"Parathyroid hormone (PTH) increases serum calcium levels by stimulating osteoclast activity and enhancing renal calcium reabsorption.","kind":"integration","linkedModuleIds":["calcium-homeostasis-hormones"],"origin":"ai"},{"id":"osteoporosis-drugs~ai-7","moduleId":"osteoporosis-drugs","stem":"What is the role of vitamin D in the context of osteoporosis treatment?","options":[{"id":"a","text":"Increases osteoclast activity"},{"id":"b","text":"Enhances calcium absorption"},{"id":"c","text":"Inhibits bone resorption"},{"id":"d","text":"Stimulates osteoblast proliferation"}],"answerId":"b","explanation":"Vitamin D enhances calcium absorption in the intestines, which is crucial for maintaining bone health.","kind":"integration","linkedModuleIds":["calcium-homeostasis-hormones"],"origin":"ai"}],"bone-tumors":[{"id":"bone-tumors~ai-0","moduleId":"bone-tumors","stem":"What is the most common primary malignant bone tumor in adolescents?","options":[{"id":"a","text":"Osteosarcoma"},{"id":"b","text":"Ewing sarcoma"},{"id":"c","text":"Chondrosarcoma"},{"id":"d","text":"Giant cell tumor"}],"answerId":"a","explanation":"Osteosarcoma is the most common primary malignant bone tumor, particularly in the second decade of life.","kind":"recall","origin":"ai"},{"id":"bone-tumors~ai-1","moduleId":"bone-tumors","stem":"Which radiological finding is characteristic of Ewing sarcoma?","options":[{"id":"a","text":"Soap-bubble appearance"},{"id":"b","text":"Onion-skin periosteal reaction"},{"id":"c","text":"Codman triangle"},{"id":"d","text":"Sunburst pattern"}],"answerId":"b","explanation":"Ewing sarcoma typically presents with an onion-skin periosteal reaction on X-ray.","kind":"recall","origin":"ai"},{"id":"bone-tumors~ai-2","moduleId":"bone-tumors","stem":"A 25-year-old presents with a soap-bubble lytic lesion around the knee. What is the most likely diagnosis?","options":[{"id":"a","text":"Osteosarcoma"},{"id":"b","text":"Giant cell tumor"},{"id":"c","text":"Chondrosarcoma"},{"id":"d","text":"Metastatic carcinoma"}],"answerId":"b","explanation":"A soap-bubble appearance in the epiphysis of long bones is characteristic of a giant cell tumor.","kind":"clinical","origin":"ai"},{"id":"bone-tumors~ai-3","moduleId":"bone-tumors","stem":"Which of the following statements is true regarding bone tumors?","options":[{"id":"a","text":"Osteosarcoma is the most common malignant tumor found in bone"},{"id":"b","text":"Metastasis is the most common malignant bone tumor overall"},{"id":"c","text":"Chondrosarcoma is the most common primary malignant bone tumor"},{"id":"d","text":"Giant cell tumor is a benign tumor with no risk of malignancy"}],"answerId":"b","explanation":"Metastasis is indeed the most common malignant bone tumor overall, while osteosarcoma is the most common primary malignant bone tumor.","kind":"trap","origin":"ai"},{"id":"bone-tumors~ai-4","moduleId":"bone-tumors","stem":"What is the primary treatment modality for osteosarcoma?","options":[{"id":"a","text":"Radiation therapy"},{"id":"b","text":"Chemotherapy and surgery"},{"id":"c","text":"Observation"},{"id":"d","text":"Targeted therapy"}],"answerId":"b","explanation":"Osteosarcoma is primarily treated with a combination of chemotherapy and surgical resection.","kind":"recall","origin":"ai"},{"id":"bone-tumors~ai-5","moduleId":"bone-tumors","stem":"A patient with a history of breast cancer presents with bone pain. Which type of bone lesion is most likely?","options":[{"id":"a","text":"Osteosarcoma"},{"id":"b","text":"Metastatic carcinoma"},{"id":"c","text":"Giant cell tumor"},{"id":"d","text":"Ewing sarcoma"}],"answerId":"b","explanation":"Metastatic carcinoma is the most common malignant bone tumor overall, especially from breast cancer.","kind":"clinical","origin":"ai"},{"id":"bone-tumors~ai-6","moduleId":"bone-tumors","stem":"How does the grading of bone tumors relate to their prognosis?","options":[{"id":"a","text":"Higher grade indicates better prognosis"},{"id":"b","text":"Grading has no impact on prognosis"},{"id":"c","text":"Lower grade indicates better prognosis"},{"id":"d","text":"All bone tumors are graded the same"}],"answerId":"c","explanation":"Lower grade tumors typically indicate a better prognosis compared to higher grade tumors, which are more aggressive.","kind":"integration","linkedModuleIds":["tumor-classification-grading"],"origin":"ai"},{"id":"bone-tumors~ai-7","moduleId":"bone-tumors","stem":"Which type of tumor is most likely to present with a diaphyseal location in children?","options":[{"id":"a","text":"Osteosarcoma"},{"id":"b","text":"Ewing sarcoma"},{"id":"c","text":"Giant cell tumor"},{"id":"d","text":"Chondrosarcoma"}],"answerId":"b","explanation":"Ewing sarcoma is known to occur in the diaphysis of long bones, particularly in children.","kind":"integration","linkedModuleIds":["soft-tissue-tumors"],"origin":"ai"}],"rehab-modalities-selection":[{"id":"rehab-modalities-selection~ai-0","moduleId":"rehab-modalities-selection","stem":"Which modality is FDA-approved for treating established non-union fractures?","options":[{"id":"a","text":"Extracorporeal shockwave therapy"},{"id":"b","text":"Therapeutic massage"},{"id":"c","text":"Pulsed electromagnetic field therapy"},{"id":"d","text":"Transcutaneous electrical nerve stimulation"}],"answerId":"c","explanation":"Pulsed electromagnetic field therapy stimulates osteogenesis, making it suitable for non-union fractures.","kind":"recall","origin":"ai"},{"id":"rehab-modalities-selection~ai-1","moduleId":"rehab-modalities-selection","stem":"What is the primary mechanism of action of extracorporeal shockwave therapy (ESWT)?","options":[{"id":"a","text":"Increases muscle strength"},{"id":"b","text":"Stimulates neovascularization"},{"id":"c","text":"Reduces inflammation"},{"id":"d","text":"Enhances lymphatic drainage"}],"answerId":"b","explanation":"ESWT primarily stimulates neovascularization, which aids in healing conditions like calcific tendinitis.","kind":"mechanism","origin":"ai"},{"id":"rehab-modalities-selection~ai-2","moduleId":"rehab-modalities-selection","stem":"In which condition is spinal traction contraindicated?","options":[{"id":"a","text":"Acute sprain"},{"id":"b","text":"Ankylosing spondylitis"},{"id":"c","text":"Chronic osteoarthritis"},{"id":"d","text":"Plantar fasciitis"}],"answerId":"b","explanation":"Spinal traction is contraindicated in ankylosing spondylitis due to the risk of injury to the inflamed, ossified spine.","kind":"trap","origin":"ai"},{"id":"rehab-modalities-selection~ai-3","moduleId":"rehab-modalities-selection","stem":"Which modality is most appropriate for treating recalcitrant calcific supraspinatus tendinitis?","options":[{"id":"a","text":"Therapeutic massage"},{"id":"b","text":"Pulsed electromagnetic field therapy"},{"id":"c","text":"Extracorporeal shockwave therapy"},{"id":"d","text":"Transcutaneous electrical nerve stimulation"}],"answerId":"c","explanation":"Extracorporeal shockwave therapy has the best evidence for treating calcific tendinitis.","kind":"recall","origin":"ai"},{"id":"rehab-modalities-selection~ai-4","moduleId":"rehab-modalities-selection","stem":"What is the best initial treatment for a patient experiencing an acute gout flare?","options":[{"id":"a","text":"Heat therapy"},{"id":"b","text":"Cold therapy"},{"id":"c","text":"Therapeutic massage"},{"id":"d","text":"Spinal traction"}],"answerId":"b","explanation":"Cold therapy is recommended for acute gout flares to reduce inflammation and pain.","kind":"clinical","origin":"ai"},{"id":"rehab-modalities-selection~ai-5","moduleId":"rehab-modalities-selection","stem":"Which modality should be avoided in a patient with a pacemaker?","options":[{"id":"a","text":"Transcutaneous electrical nerve stimulation"},{"id":"b","text":"Therapeutic massage"},{"id":"c","text":"Pulsed electromagnetic field therapy"},{"id":"d","text":"Cold therapy"}],"answerId":"a","explanation":"Transcutaneous electrical nerve stimulation should be avoided in patients with pacemakers due to potential interference.","kind":"trap","origin":"ai"},{"id":"rehab-modalities-selection~ai-6","moduleId":"rehab-modalities-selection","stem":"How does the management of ankylosing spondylitis differ from that of chronic osteoarthritis?","options":[{"id":"a","text":"Both require heat therapy"},{"id":"b","text":"Both can use spinal traction"},{"id":"c","text":"Ankylosing spondylitis requires avoidance of traction"},{"id":"d","text":"Chronic osteoarthritis requires cold therapy"}],"answerId":"c","explanation":"Ankylosing spondylitis requires avoidance of traction due to the risk of injury to the spine.","kind":"integration","linkedModuleIds":["cranial-nerves-overview"],"origin":"ai"},{"id":"rehab-modalities-selection~ai-7","moduleId":"rehab-modalities-selection","stem":"What is a key difference in treatment modalities for acute sprains versus chronic osteoarthritis?","options":[{"id":"a","text":"Both use heat therapy"},{"id":"b","text":"Acute sprains benefit from cold therapy"},{"id":"c","text":"Chronic osteoarthritis requires traction"},{"id":"d","text":"Acute sprains should avoid TENS"}],"answerId":"b","explanation":"Acute sprains benefit from cold therapy, while chronic osteoarthritis typically requires heat therapy.","kind":"integration","linkedModuleIds":["rehab-thermotherapy-electrotherapy"],"origin":"ai"}],"soft-tissue-tumors":[{"id":"soft-tissue-tumors~ai-0","moduleId":"soft-tissue-tumors","stem":"What is the most common benign soft-tissue tumor?","options":[{"id":"a","text":"Liposarcoma"},{"id":"b","text":"Rhabdomyosarcoma"},{"id":"c","text":"Lipoma"},{"id":"d","text":"Neurofibroma"}],"answerId":"c","explanation":"Lipoma is the most common benign soft-tissue tumor, composed of mature adipocytes.","kind":"recall","origin":"ai"},{"id":"soft-tissue-tumors~ai-1","moduleId":"soft-tissue-tumors","stem":"Which cell type is characteristic of rhabdomyosarcoma?","options":[{"id":"a","text":"Liposarcoma"},{"id":"b","text":"Rhabdomyoblast"},{"id":"c","text":"Schwann cell"},{"id":"d","text":"Fibroblast"}],"answerId":"b","explanation":"Rhabdomyosarcoma is characterized by the presence of rhabdomyoblasts, which may show cross-striations.","kind":"mechanism","origin":"ai"},{"id":"soft-tissue-tumors~ai-2","moduleId":"soft-tissue-tumors","stem":"A 10-year-old boy presents with a soft-tissue mass containing rhabdomyoblasts. What is the likely diagnosis?","options":[{"id":"a","text":"Liposarcoma"},{"id":"b","text":"Rhabdomyosarcoma"},{"id":"c","text":"Neurofibroma"},{"id":"d","text":"Angiosarcoma"}],"answerId":"b","explanation":"Rhabdomyosarcoma is the most common soft-tissue sarcoma in children and is identified by rhabdomyoblasts.","kind":"clinical","origin":"ai"},{"id":"soft-tissue-tumors~ai-3","moduleId":"soft-tissue-tumors","stem":"A patient with neurofibromatosis type 1 develops a malignant nerve-sheath tumor. What is this tumor called?","options":[{"id":"a","text":"Schwannoma"},{"id":"b","text":"Neurofibroma"},{"id":"c","text":"Malignant peripheral nerve sheath tumor"},{"id":"d","text":"Rhabdomyosarcoma"}],"answerId":"c","explanation":"Malignant peripheral nerve sheath tumor (MPNST) is associated with neurofibromatosis type 1.","kind":"recall","origin":"ai"},{"id":"soft-tissue-tumors~ai-4","moduleId":"soft-tissue-tumors","stem":"Which of the following is a common risk factor for angiosarcoma?","options":[{"id":"a","text":"Chronic lymphedema"},{"id":"b","text":"Radiation exposure"},{"id":"c","text":"HIV infection"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"Angiosarcoma can arise from chronic lymphedema, radiation exposure, and is associated with HIV infection (Kaposi sarcoma).","kind":"trap","origin":"ai"},{"id":"soft-tissue-tumors~ai-5","moduleId":"soft-tissue-tumors","stem":"What is the hallmark histological feature of synovial sarcoma?","options":[{"id":"a","text":"Verocay bodies"},{"id":"b","text":"Biphasic pattern"},{"id":"c","text":"Spider cells"},{"id":"d","text":"Cross-striations"}],"answerId":"b","explanation":"Synovial sarcoma is characterized by a biphasic histology with both spindle and epithelial cells.","kind":"mechanism","origin":"ai"},{"id":"soft-tissue-tumors~ai-6","moduleId":"soft-tissue-tumors","stem":"How does rhabdomyosarcoma differ from liposarcoma in terms of patient demographics?","options":[{"id":"a","text":"Rhabdomyosarcoma occurs mainly in adults"},{"id":"b","text":"Liposarcoma is more common in children"},{"id":"c","text":"Rhabdomyosarcoma is the most common in children"},{"id":"d","text":"Both are equally common in adults and children"}],"answerId":"c","explanation":"Rhabdomyosarcoma is the most common soft-tissue sarcoma in children, while liposarcoma primarily occurs in adults.","kind":"integration","linkedModuleIds":["neoplasia-nomenclature"],"origin":"ai"},{"id":"soft-tissue-tumors~ai-7","moduleId":"soft-tissue-tumors","stem":"Which tumor type is associated with the presence of lipoblasts?","options":[{"id":"a","text":"Liposarcoma"},{"id":"b","text":"Rhabdomyosarcoma"},{"id":"c","text":"Neurofibroma"},{"id":"d","text":"Angiosarcoma"}],"answerId":"a","explanation":"Liposarcoma is characterized by the presence of lipoblasts, which are the hallmark cells of this tumor.","kind":"integration","linkedModuleIds":["bone-tumors"],"origin":"ai"}],"calcium-homeostasis-hormones":[{"id":"calcium-homeostasis-hormones~ai-0","moduleId":"calcium-homeostasis-hormones","stem":"What is the primary effect of parathyroid hormone (PTH) on renal function?","options":[{"id":"a","text":"Increases phosphate reabsorption"},{"id":"b","text":"Increases calcium reabsorption"},{"id":"c","text":"Decreases calcium reabsorption"},{"id":"d","text":"Decreases phosphate excretion"}],"answerId":"b","explanation":"PTH increases calcium reabsorption in the renal tubules, which helps to raise serum calcium levels.","kind":"recall","origin":"ai"},{"id":"calcium-homeostasis-hormones~ai-1","moduleId":"calcium-homeostasis-hormones","stem":"How does intermittent low-dose PTH (teriparatide) affect bone metabolism?","options":[{"id":"a","text":"Increases osteoclast activity"},{"id":"b","text":"Stimulates osteoblast activity"},{"id":"c","text":"Inhibits bone formation"},{"id":"d","text":"Decreases calcium absorption in the gut"}],"answerId":"b","explanation":"Intermittent low-dose PTH stimulates osteoblasts, leading to increased bone formation.","kind":"mechanism","origin":"ai"},{"id":"calcium-homeostasis-hormones~ai-2","moduleId":"calcium-homeostasis-hormones","stem":"Which hormone opposes the action of parathyroid hormone (PTH) in calcium homeostasis?","options":[{"id":"a","text":"Calcitonin"},{"id":"b","text":"Vitamin D"},{"id":"c","text":"Estrogen"},{"id":"d","text":"Cortisol"}],"answerId":"a","explanation":"Calcitonin, produced by the thyroid C cells, lowers serum calcium levels by inhibiting osteoclast activity, opposing PTH.","kind":"recall","origin":"ai"},{"id":"calcium-homeostasis-hormones~ai-3","moduleId":"calcium-homeostasis-hormones","stem":"A postmenopausal woman presents with bone pain and increased fracture risk. What is the underlying mechanism of her condition?","options":[{"id":"a","text":"Increased osteoclast activity due to estrogen deficiency"},{"id":"b","text":"Increased osteoblast activity"},{"id":"c","text":"Decreased calcium absorption"},{"id":"d","text":"Increased calcitonin secretion"}],"answerId":"a","explanation":"Estrogen deficiency leads to increased osteoclast activity, resulting in bone resorption and osteoporosis.","kind":"clinical","origin":"ai"},{"id":"calcium-homeostasis-hormones~ai-4","moduleId":"calcium-homeostasis-hormones","stem":"What is the effect of high, continuous levels of PTH on bone?","options":[{"id":"a","text":"Stimulates bone formation"},{"id":"b","text":"Inhibits osteoclast activity"},{"id":"c","text":"Increases bone resorption"},{"id":"d","text":"Decreases serum calcium"}],"answerId":"c","explanation":"High, continuous levels of PTH stimulate osteoclasts, leading to increased bone resorption.","kind":"trap","origin":"ai"},{"id":"calcium-homeostasis-hormones~ai-5","moduleId":"calcium-homeostasis-hormones","stem":"How does calcitonin affect calcium levels in the body?","options":[{"id":"a","text":"Increases renal calcium reabsorption"},{"id":"b","text":"Inhibits osteoclast activity"},{"id":"c","text":"Stimulates osteoblast activity"},{"id":"d","text":"Increases intestinal calcium absorption"}],"answerId":"b","explanation":"Calcitonin lowers serum calcium levels by inhibiting osteoclast activity, thus reducing bone resorption.","kind":"recall","origin":"ai"},{"id":"calcium-homeostasis-hormones~ai-6","moduleId":"calcium-homeostasis-hormones","stem":"How does vitamin D interact with calcium homeostasis and phosphate metabolism?","options":[{"id":"a","text":"Increases renal phosphate reabsorption"},{"id":"b","text":"Decreases intestinal calcium absorption"},{"id":"c","text":"Increases intestinal absorption of calcium and phosphate"},{"id":"d","text":"Inhibits PTH secretion"}],"answerId":"c","explanation":"Vitamin D enhances the intestinal absorption of both calcium and phosphate, which is crucial for bone mineralization.","kind":"integration","linkedModuleIds":["hen1-calcitonin-mineral-integration"],"origin":"ai"},{"id":"calcium-homeostasis-hormones~ai-7","moduleId":"calcium-homeostasis-hormones","stem":"What is the role of estrogen in bone health, particularly in postmenopausal women?","options":[{"id":"a","text":"Stimulates osteoclast activity"},{"id":"b","text":"Inhibits osteoblast apoptosis"},{"id":"c","text":"Increases PTH secretion"},{"id":"d","text":"Decreases calcium absorption"}],"answerId":"b","explanation":"Estrogen helps maintain bone density by inhibiting osteoblast apoptosis, thus preventing bone loss.","kind":"integration","linkedModuleIds":["osteoporosis-drugs"],"origin":"ai"}],"hypopituitarism":[{"id":"hypopituitarism~ai-0","moduleId":"hypopituitarism","stem":"What is the most common cause of hypopituitarism?","options":[{"id":"a","text":"Pituitary apoplexy"},{"id":"b","text":"Traumatic brain injury"},{"id":"c","text":"Sheehan syndrome"},{"id":"d","text":"Empty sella syndrome"}],"answerId":"b","explanation":"Traumatic brain injury is the most common cause of hypopituitarism, often leading to significant damage to the anterior pituitary.","kind":"recall","origin":"ai"},{"id":"hypopituitarism~ai-1","moduleId":"hypopituitarism","stem":"In Sheehan syndrome, which hormone deficiency is typically the earliest sign?","options":[{"id":"a","text":"Adrenocorticotropic hormone (ACTH)"},{"id":"b","text":"Thyroid-stimulating hormone (TSH)"},{"id":"c","text":"Growth hormone (GH)"},{"id":"d","text":"Prolactin"}],"answerId":"d","explanation":"Failure to lactate due to low prolactin levels is the earliest sign of Sheehan syndrome.","kind":"recall","origin":"ai"},{"id":"hypopituitarism~ai-2","moduleId":"hypopituitarism","stem":"What is the mechanism of action for hypopituitarism due to destruction of the anterior pituitary?","options":[{"id":"a","text":"Increased target-gland hormone secretion"},{"id":"b","text":"Decreased anterior pituitary hormone secretion"},{"id":"c","text":"Increased hypothalamic stimulation"},{"id":"d","text":"Decreased feedback inhibition"}],"answerId":"b","explanation":"Destruction of the anterior pituitary leads to decreased secretion of its hormones, resulting in hypopituitarism.","kind":"mechanism","origin":"ai"},{"id":"hypopituitarism~ai-3","moduleId":"hypopituitarism","stem":"A patient presents with fatigue, cold intolerance, and hypotension after a head injury. What is the likely diagnosis?","options":[{"id":"a","text":"Sheehan syndrome"},{"id":"b","text":"Panhypopituitarism"},{"id":"c","text":"Empty sella syndrome"},{"id":"d","text":"Pituitary apoplexy"}],"answerId":"b","explanation":"These symptoms suggest panhypopituitarism, particularly secondary hypothyroidism and adrenal insufficiency following a head injury.","kind":"clinical","origin":"ai"},{"id":"hypopituitarism~ai-4","moduleId":"hypopituitarism","stem":"In the management of panhypopituitarism, which hormone replacement should be initiated first?","options":[{"id":"a","text":"Levothyroxine"},{"id":"b","text":"Testosterone"},{"id":"c","text":"Hydrocortisone"},{"id":"d","text":"Desmopressin"}],"answerId":"c","explanation":"Glucocorticoids must be given first to prevent adrenal crisis before initiating thyroid hormone replacement.","kind":"trap","origin":"ai"},{"id":"hypopituitarism~ai-5","moduleId":"hypopituitarism","stem":"A patient with a craniopharyngioma presents with visual disturbances and hormonal deficiencies. Which pituitary hormone is most likely to be affected first?","options":[{"id":"a","text":"Adrenocorticotropic hormone (ACTH)"},{"id":"b","text":"Thyroid-stimulating hormone (TSH)"},{"id":"c","text":"Growth hormone (GH)"},{"id":"d","text":"Luteinizing hormone (LH)"}],"answerId":"c","explanation":"In craniopharyngiomas, growth hormone deficiency often appears first due to the location of the tumor affecting the anterior pituitary.","kind":"integration","linkedModuleIds":["craniopharyngioma"],"origin":"ai"},{"id":"hypopituitarism~ai-6","moduleId":"hypopituitarism","stem":"How does hypopituitarism relate to the management of pituitary adenomas?","options":[{"id":"a","text":"Both conditions require immediate thyroid hormone replacement"},{"id":"b","text":"Pituitary adenomas can cause hyperpituitarism, while hypopituitarism results from destruction"},{"id":"c","text":"Both conditions are managed with the same surgical approach"},{"id":"d","text":"Hypopituitarism is a direct result of pituitary adenomas only"}],"answerId":"b","explanation":"Pituitary adenomas typically cause hyperpituitarism, while hypopituitarism results from damage or destruction of the pituitary gland.","kind":"integration","linkedModuleIds":["pituitary-adenomas-hyperpituitarism"],"origin":"ai"}],"gout-drugs":[{"id":"gout-drugs~ai-0","moduleId":"gout-drugs","stem":"Which medication is contraindicated in acute gout due to its urate-retaining properties?","options":[{"id":"a","text":"Indomethacin"},{"id":"b","text":"Colchicine"},{"id":"c","text":"Aspirin"},{"id":"d","text":"Naproxen"}],"answerId":"c","explanation":"Aspirin at low doses causes urate retention, worsening gout symptoms, and should be avoided.","kind":"trap","origin":"ai"},{"id":"gout-drugs~ai-1","moduleId":"gout-drugs","stem":"What is the mechanism of action of colchicine in treating acute gout?","options":[{"id":"a","text":"Inhibits xanthine oxidase"},{"id":"b","text":"Inhibits microtubule formation"},{"id":"c","text":"Increases renal urate excretion"},{"id":"d","text":"Degrades urate to allantoin"}],"answerId":"b","explanation":"Colchicine binds to tubulin, inhibiting microtubule formation and neutrophil migration.","kind":"mechanism","origin":"ai"},{"id":"gout-drugs~ai-2","moduleId":"gout-drugs","stem":"Which drug is the first-line treatment for chronic gout management?","options":[{"id":"a","text":"Febuxostat"},{"id":"b","text":"Probenecid"},{"id":"c","text":"Allopurinol"},{"id":"d","text":"Colchicine"}],"answerId":"c","explanation":"Allopurinol is the first-line urate-lowering therapy for chronic gout.","kind":"recall","origin":"ai"},{"id":"gout-drugs~ai-3","moduleId":"gout-drugs","stem":"A patient develops severe cutaneous reactions after starting allopurinol. What is the most likely underlying cause?","options":[{"id":"a","text":"Colchicine toxicity"},{"id":"b","text":"HLA-B*58:01 hypersensitivity"},{"id":"c","text":"Uric acid nephropathy"},{"id":"d","text":"Tumor lysis syndrome"}],"answerId":"b","explanation":"Severe cutaneous reactions like SJS/TEN are associated with HLA-B*58:01 hypersensitivity to allopurinol.","kind":"recall","origin":"ai"},{"id":"gout-drugs~ai-4","moduleId":"gout-drugs","stem":"In a patient with acute gout, which of the following is a common side effect of colchicine?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Diarrhea"},{"id":"c","text":"Weight gain"},{"id":"d","text":"Headache"}],"answerId":"b","explanation":"Colchicine can cause gastrointestinal upset, including diarrhea, especially at higher doses.","kind":"recall","origin":"ai"},{"id":"gout-drugs~ai-5","moduleId":"gout-drugs","stem":"How does probenecid function in the management of gout?","options":[{"id":"a","text":"Inhibits xanthine oxidase"},{"id":"b","text":"Inhibits URAT1 to increase urate excretion"},{"id":"c","text":"Degrades urate to allantoin"},{"id":"d","text":"Inhibits NLRP3 inflammasome"}],"answerId":"b","explanation":"Probenecid inhibits URAT1, leading to increased renal excretion of urate.","kind":"mechanism","origin":"ai"},{"id":"gout-drugs~ai-6","moduleId":"gout-drugs","stem":"Which of the following statements best connects gout treatment to renal handling of urate?","options":[{"id":"a","text":"Allopurinol increases urate excretion by the kidneys."},{"id":"b","text":"Colchicine enhances renal tubular reabsorption of urate."},{"id":"c","text":"Probenecid inhibits URAT1, promoting urate excretion."},{"id":"d","text":"Febuxostat directly increases urate production."}],"answerId":"c","explanation":"Probenecid inhibits URAT1, which increases renal excretion of urate, linking gout treatment to renal handling.","kind":"integration","linkedModuleIds":["renal-calcium-phosphate-handling"],"origin":"ai"},{"id":"gout-drugs~ai-7","moduleId":"gout-drugs","stem":"Which mechanism explains the use of allopurinol in patients undergoing chemotherapy for tumor lysis syndrome?","options":[{"id":"a","text":"Inhibits renal urate reabsorption"},{"id":"b","text":"Inhibits xanthine oxidase"},{"id":"c","text":"Degrades urate to allantoin"},{"id":"d","text":"Stimulates urate production"}],"answerId":"b","explanation":"Allopurinol inhibits xanthine oxidase, reducing uric acid production and preventing hyperuricemia in tumor lysis syndrome.","kind":"integration","linkedModuleIds":["nucleotide-degradation-gout"],"origin":"ai"}],"craniopharyngioma":[{"id":"craniopharyngioma~ai-0","moduleId":"craniopharyngioma","stem":"What is the most common age group for the presentation of craniopharyngioma?","options":[{"id":"a","text":"0-5 years"},{"id":"b","text":"5-15 years"},{"id":"c","text":"25-35 years"},{"id":"d","text":"≥65 years"}],"answerId":"b","explanation":"Craniopharyngioma typically presents in two age groups: children aged 5-15 years and adults aged ≥65 years.","kind":"recall","origin":"ai"},{"id":"craniopharyngioma~ai-1","moduleId":"craniopharyngioma","stem":"Which histological feature is characteristic of the adamantinomatous variant of craniopharyngioma?","options":[{"id":"a","text":"Solid sheets of non-keratinizing epithelium"},{"id":"b","text":"Palisading of nuclei"},{"id":"c","text":"Cystic spaces without keratin"},{"id":"d","text":"Absence of calcification"}],"answerId":"b","explanation":"The adamantinomatous variant is characterized by peripheral palisading of nuclei and the presence of 'wet keratin'.","kind":"mechanism","origin":"ai"},{"id":"craniopharyngioma~ai-2","moduleId":"craniopharyngioma","stem":"A 10-year-old boy presents with headaches and bitemporal hemianopsia. Imaging shows a calcified suprasellar mass. What is the most likely diagnosis?","options":[{"id":"a","text":"Pituitary adenoma"},{"id":"b","text":"Craniopharyngioma"},{"id":"c","text":"Meningioma"},{"id":"d","text":"Hypothalamic tumor"}],"answerId":"b","explanation":"The combination of age, symptoms, and imaging findings strongly suggests a craniopharyngioma, particularly the adamantinomatous variant.","kind":"clinical","origin":"ai"},{"id":"craniopharyngioma~ai-3","moduleId":"craniopharyngioma","stem":"Which of the following findings would most likely be seen in a craniopharyngioma on imaging?","options":[{"id":"a","text":"Hyperdense solid mass"},{"id":"b","text":"Calcified cystic mass"},{"id":"c","text":"Hypodense solid mass"},{"id":"d","text":"Enhancing meningeal thickening"}],"answerId":"b","explanation":"Craniopharyngiomas often present as calcified cystic masses on imaging, especially in children.","kind":"recall","origin":"ai"},{"id":"craniopharyngioma~ai-4","moduleId":"craniopharyngioma","stem":"What is the mechanism by which craniopharyngiomas arise?","options":[{"id":"a","text":"Neoplastic transformation of pituitary cells"},{"id":"b","text":"Remnants of Rathke pouch"},{"id":"c","text":"Developmental errors in the hypothalamus"},{"id":"d","text":"Infection of the pituitary gland"}],"answerId":"b","explanation":"Craniopharyngiomas arise from vestigial remnants of Rathke pouch, leading to suprasellar tumors.","kind":"mechanism","origin":"ai"},{"id":"craniopharyngioma~ai-5","moduleId":"craniopharyngioma","stem":"In a child with a suprasellar mass, which finding would differentiate craniopharyngioma from a pituitary adenoma?","options":[{"id":"a","text":"Presence of calcification"},{"id":"b","text":"Age of the patient"},{"id":"c","text":"Size of the mass"},{"id":"d","text":"Location of the mass"}],"answerId":"a","explanation":"Calcification and cystic changes are more indicative of craniopharyngioma, while pituitary adenomas are typically solid and not calcified.","kind":"trap","origin":"ai"},{"id":"craniopharyngioma~ai-6","moduleId":"craniopharyngioma","stem":"How does craniopharyngioma relate to hypopituitarism?","options":[{"id":"a","text":"It causes hypersecretion of pituitary hormones"},{"id":"b","text":"It can lead to pituitary gland compression"},{"id":"c","text":"It is a type of pituitary adenoma"},{"id":"d","text":"It has no relation to pituitary function"}],"answerId":"b","explanation":"Craniopharyngiomas can compress the pituitary gland, leading to hypopituitarism due to decreased hormone production.","kind":"integration","linkedModuleIds":["hypopituitarism"],"origin":"ai"},{"id":"craniopharyngioma~ai-7","moduleId":"craniopharyngioma","stem":"Which embryological remnant is associated with the development of craniopharyngioma and is also relevant in understanding pituitary anatomy?","options":[{"id":"a","text":"Neural crest cells"},{"id":"b","text":"Rathke pouch"},{"id":"c","text":"Mesodermal derivatives"},{"id":"d","text":"Ectodermal layers"}],"answerId":"b","explanation":"Craniopharyngiomas arise from remnants of Rathke pouch, which is crucial in the embryological development of the pituitary gland.","kind":"integration","linkedModuleIds":["hen1-pituitary-anatomy-development"],"origin":"ai"}],"pituitary-adenomas-hyperpituitarism":[{"id":"pituitary-adenomas-hyperpituitarism~ai-0","moduleId":"pituitary-adenomas-hyperpituitarism","stem":"What is the most common functional pituitary adenoma?","options":[{"id":"a","text":"Lactotroph adenoma"},{"id":"b","text":"Somatotroph adenoma"},{"id":"c","text":"Corticotroph adenoma"},{"id":"d","text":"Gonadotroph adenoma"}],"answerId":"a","explanation":"Lactotroph adenoma, or prolactinoma, is the most common functional pituitary adenoma, leading to hyperprolactinemia.","kind":"recall","origin":"ai"},{"id":"pituitary-adenomas-hyperpituitarism~ai-1","moduleId":"pituitary-adenomas-hyperpituitarism","stem":"Which clinical finding is characteristic of acromegaly?","options":[{"id":"a","text":"Bitemporal hemianopsia"},{"id":"b","text":"Amenorrhea"},{"id":"c","text":"Coarse facial features"},{"id":"d","text":"Galactorrhea"}],"answerId":"c","explanation":"Acromegaly is characterized by coarse features and enlargement of hands and feet due to excess growth hormone.","kind":"recall","origin":"ai"},{"id":"pituitary-adenomas-hyperpituitarism~ai-2","moduleId":"pituitary-adenomas-hyperpituitarism","stem":"What is the first-line treatment for a prolactinoma?","options":[{"id":"a","text":"Surgical resection"},{"id":"b","text":"Radiation therapy"},{"id":"c","text":"Dopamine agonist"},{"id":"d","text":"Observation only"}],"answerId":"c","explanation":"Dopamine agonists like cabergoline or bromocriptine are the first-line treatment as they lower prolactin levels and shrink the tumor.","kind":"trap","origin":"ai"},{"id":"pituitary-adenomas-hyperpituitarism~ai-3","moduleId":"pituitary-adenomas-hyperpituitarism","stem":"Which of the following is a potential consequence of pituitary apoplexy?","options":[{"id":"a","text":"Visual field loss"},{"id":"b","text":"Weight gain"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Hypertension"}],"answerId":"a","explanation":"Pituitary apoplexy can lead to sudden visual field loss due to compression of the optic chiasm.","kind":"recall","origin":"ai"},{"id":"pituitary-adenomas-hyperpituitarism~ai-4","moduleId":"pituitary-adenomas-hyperpituitarism","stem":"Which hormone is primarily secreted by somatotroph adenomas?","options":[{"id":"a","text":"Prolactin"},{"id":"b","text":"Cortisol"},{"id":"c","text":"Growth hormone"},{"id":"d","text":"Thyroid-stimulating hormone"}],"answerId":"c","explanation":"Somatotroph adenomas primarily secrete growth hormone, leading to conditions like acromegaly.","kind":"recall","origin":"ai"},{"id":"pituitary-adenomas-hyperpituitarism~ai-5","moduleId":"pituitary-adenomas-hyperpituitarism","stem":"A patient with a pituitary adenoma presents with bitemporal hemianopsia. What is the mechanism behind this finding?","options":[{"id":"a","text":"Compression of optic tracts"},{"id":"b","text":"Compression of optic nerves"},{"id":"c","text":"Compression of the optic chiasm"},{"id":"d","text":"Increased intracranial pressure"}],"answerId":"c","explanation":"Bitemporal hemianopsia occurs due to compression of the optic chiasm by a macroadenoma affecting the crossing fibers.","kind":"mechanism","origin":"ai"},{"id":"pituitary-adenomas-hyperpituitarism~ai-6","moduleId":"pituitary-adenomas-hyperpituitarism","stem":"How does hyperprolactinemia from a prolactinoma affect menstrual cycles in women?","options":[{"id":"a","text":"Causes increased fertility"},{"id":"b","text":"Leads to amenorrhea"},{"id":"c","text":"Results in heavy menstrual bleeding"},{"id":"d","text":"Induces early menopause"}],"answerId":"b","explanation":"Hyperprolactinemia commonly leads to amenorrhea due to its inhibitory effect on gonadotropin-releasing hormone.","kind":"clinical","origin":"ai"},{"id":"pituitary-adenomas-hyperpituitarism~ai-7","moduleId":"pituitary-adenomas-hyperpituitarism","stem":"How does the management of a prolactinoma differ from other pituitary adenomas?","options":[{"id":"a","text":"Surgery is always first-line"},{"id":"b","text":"Dopamine agonists are first-line"},{"id":"c","text":"Radiation is preferred"},{"id":"d","text":"Observation is sufficient"}],"answerId":"b","explanation":"Dopamine agonists are the first-line treatment for prolactinomas, unlike other adenomas where surgery is often prioritized.","kind":"trap","origin":"ai"},{"id":"pituitary-adenomas-hyperpituitarism~ai-8","moduleId":"pituitary-adenomas-hyperpituitarism","stem":"A patient with acromegaly is evaluated for growth hormone excess. Which linked module's concepts are most relevant for understanding the effects of growth hormone?","options":[{"id":"a","text":"Meningioma, Schwannoma & Pituitary Adenoma"},{"id":"b","text":"Craniopharyngioma & Suprasellar Tumors"},{"id":"c","text":"Growth Hormone, IGF-1 & Growth Disorders"},{"id":"d","text":"Pituitary Apoplexy"}],"answerId":"c","explanation":"The module on Growth Hormone, IGF-1 & Growth Disorders provides essential insights into the effects and mechanisms of growth hormone excess.","kind":"integration","linkedModuleIds":["hen1-growth-hormone-igf1"],"origin":"ai"}],"multiple-endocrine-neoplasia":[{"id":"multiple-endocrine-neoplasia~ai-0","moduleId":"multiple-endocrine-neoplasia","stem":"What is the most common endocrine manifestation in MEN 1?","options":[{"id":"a","text":"Medullary thyroid carcinoma"},{"id":"b","text":"Primary hyperparathyroidism"},{"id":"c","text":"Pheochromocytoma"},{"id":"d","text":"Insulinoma"}],"answerId":"b","explanation":"Primary hyperparathyroidism is the most common manifestation of MEN 1, often presenting first.","kind":"recall","origin":"ai"},{"id":"multiple-endocrine-neoplasia~ai-1","moduleId":"multiple-endocrine-neoplasia","stem":"Which gene mutation is associated with MEN 2A?","options":[{"id":"a","text":"MEN1"},{"id":"b","text":"RET"},{"id":"c","text":"CDKN1B"},{"id":"d","text":"TP53"}],"answerId":"b","explanation":"The RET proto-oncogene mutation is associated with MEN 2A.","kind":"recall","origin":"ai"},{"id":"multiple-endocrine-neoplasia~ai-2","moduleId":"multiple-endocrine-neoplasia","stem":"In MEN 2A, what should be screened for before surgery if medullary thyroid carcinoma and parathyroid disease are present?","options":[{"id":"a","text":"Prolactinoma"},{"id":"b","text":"Pheochromocytoma"},{"id":"c","text":"Insulinoma"},{"id":"d","text":"Gastrinoma"}],"answerId":"b","explanation":"Pheochromocytoma should be screened for due to the risk of a catecholamine crisis during surgery.","kind":"trap","origin":"ai"},{"id":"multiple-endocrine-neoplasia~ai-3","moduleId":"multiple-endocrine-neoplasia","stem":"What is a key clinical feature of MEN 2B?","options":[{"id":"a","text":"Parathyroid hyperplasia"},{"id":"b","text":"Mucosal neuromas"},{"id":"c","text":"Gastrinoma"},{"id":"d","text":"Prolactinoma"}],"answerId":"b","explanation":"Mucosal neuromas are a characteristic feature of MEN 2B, along with medullary thyroid carcinoma.","kind":"clinical","origin":"ai"},{"id":"multiple-endocrine-neoplasia~ai-4","moduleId":"multiple-endocrine-neoplasia","stem":"Which of the following is a mechanism of tumor development in MEN syndromes?","options":[{"id":"a","text":"Viral infection"},{"id":"b","text":"Germline mutation"},{"id":"c","text":"Environmental exposure"},{"id":"d","text":"Hormonal imbalance"}],"answerId":"b","explanation":"MEN syndromes are caused by germline mutations leading to tumors across multiple endocrine glands.","kind":"mechanism","origin":"ai"},{"id":"multiple-endocrine-neoplasia~ai-5","moduleId":"multiple-endocrine-neoplasia","stem":"How does MEN 1 differ from MEN 2A in terms of tumor types?","options":[{"id":"a","text":"MEN 1 includes pheochromocytoma"},{"id":"b","text":"MEN 2A includes insulinoma"},{"id":"c","text":"MEN 1 includes prolactinoma"},{"id":"d","text":"MEN 2A includes gastrinoma"}],"answerId":"c","explanation":"MEN 1 includes prolactinoma, while MEN 2A does not; it is characterized by medullary thyroid carcinoma and pheochromocytoma.","kind":"integration","linkedModuleIds":["pheochromocytoma-paraganglioma"],"origin":"ai"},{"id":"multiple-endocrine-neoplasia~ai-6","moduleId":"multiple-endocrine-neoplasia","stem":"What is the relationship between MEN syndromes and neoplasia nomenclature?","options":[{"id":"a","text":"MEN syndromes are classified as benign tumors"},{"id":"b","text":"MEN syndromes are hereditary cancer syndromes"},{"id":"c","text":"MEN syndromes are exclusively endocrine tumors"},{"id":"d","text":"MEN syndromes are unrelated to neoplasia"}],"answerId":"b","explanation":"MEN syndromes are hereditary cancer syndromes characterized by multiple endocrine neoplasms.","kind":"integration","linkedModuleIds":["neoplasia-nomenclature"],"origin":"ai"}],"pheochromocytoma-paraganglioma":[{"id":"pheochromocytoma-paraganglioma~ai-0","moduleId":"pheochromocytoma-paraganglioma","stem":"What is the most common catecholamine secreted by pheochromocytomas?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"Norepinephrine"},{"id":"c","text":"Epinephrine"},{"id":"d","text":"Serotonin"}],"answerId":"b","explanation":"Pheochromocytomas primarily secrete norepinephrine, with epinephrine being less common.","kind":"recall","origin":"ai"},{"id":"pheochromocytoma-paraganglioma~ai-1","moduleId":"pheochromocytoma-paraganglioma","stem":"Which histological feature is characteristic of pheochromocytomas?","options":[{"id":"a","text":"Nuclear pleomorphism"},{"id":"b","text":"Zellballen pattern"},{"id":"c","text":"Mitoses"},{"id":"d","text":"Necrosis"}],"answerId":"b","explanation":"The Zellballen pattern is a distinctive histological feature of pheochromocytomas.","kind":"recall","origin":"ai"},{"id":"pheochromocytoma-paraganglioma~ai-2","moduleId":"pheochromocytoma-paraganglioma","stem":"A patient presents with episodic headaches, palpitations, and diaphoresis. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Increased cortisol secretion"},{"id":"b","text":"Episodic catecholamine surges"},{"id":"c","text":"Increased aldosterone secretion"},{"id":"d","text":"Decreased insulin sensitivity"}],"answerId":"b","explanation":"Episodic catecholamine surges from a pheochromocytoma lead to these symptoms.","kind":"mechanism","origin":"ai"},{"id":"pheochromocytoma-paraganglioma~ai-3","moduleId":"pheochromocytoma-paraganglioma","stem":"What is the appropriate initial treatment for a patient diagnosed with pheochromocytoma before surgery?","options":[{"id":"a","text":"Start a beta-blocker"},{"id":"b","text":"Start an alpha-blocker"},{"id":"c","text":"Administer calcium channel blockers"},{"id":"d","text":"Administer diuretics"}],"answerId":"b","explanation":"An alpha-blocker should be started first to prevent hypertensive crisis due to unopposed alpha-adrenergic activity.","kind":"trap","origin":"ai"},{"id":"pheochromocytoma-paraganglioma~ai-4","moduleId":"pheochromocytoma-paraganglioma","stem":"Which of the following findings would be most indicative of a carotid-body paraganglioma?","options":[{"id":"a","text":"Pulsatile neck mass"},{"id":"b","text":"Episodic hypertension"},{"id":"c","text":"Zellballen pattern"},{"id":"d","text":"Increased urinary metanephrines"}],"answerId":"a","explanation":"A painless pulsatile neck mass that is mobile horizontally is characteristic of a carotid-body paraganglioma.","kind":"recall","origin":"ai"},{"id":"pheochromocytoma-paraganglioma~ai-5","moduleId":"pheochromocytoma-paraganglioma","stem":"How does pheochromocytoma relate to adrenal catecholamine synthesis?","options":[{"id":"a","text":"It decreases catecholamine synthesis"},{"id":"b","text":"It causes excess catecholamine secretion"},{"id":"c","text":"It inhibits catecholamine metabolism"},{"id":"d","text":"It alters adrenal gland structure"}],"answerId":"b","explanation":"Pheochromocytoma leads to excess catecholamine secretion from adrenal chromaffin cells.","kind":"integration","linkedModuleIds":["hen1-adrenal-catecholamines"],"origin":"ai"},{"id":"pheochromocytoma-paraganglioma~ai-6","moduleId":"pheochromocytoma-paraganglioma","stem":"What is a common familial syndrome associated with pheochromocytoma?","options":[{"id":"a","text":"Cushing's syndrome"},{"id":"b","text":"Multiple Endocrine Neoplasia type 2"},{"id":"c","text":"Hyperparathyroidism"},{"id":"d","text":"Acromegaly"}],"answerId":"b","explanation":"Multiple Endocrine Neoplasia type 2 is a familial syndrome that includes pheochromocytoma.","kind":"integration","linkedModuleIds":["multiple-endocrine-neoplasia"],"origin":"ai"}],"neuroblastoma":[{"id":"neuroblastoma~ai-0","moduleId":"neuroblastoma","stem":"What is the most common site of origin for neuroblastoma?","options":[{"id":"a","text":"Adrenal gland"},{"id":"b","text":"Kidney"},{"id":"c","text":"Liver"},{"id":"d","text":"Lung"}],"answerId":"a","explanation":"Neuroblastoma most commonly arises from the adrenal gland, accounting for approximately 40% of cases.","kind":"recall","origin":"ai"},{"id":"neuroblastoma~ai-1","moduleId":"neuroblastoma","stem":"Which histological feature is characteristic of neuroblastoma?","options":[{"id":"a","text":"Homer-Wright rosettes"},{"id":"b","text":"Giant cells"},{"id":"c","text":"Keratin pearls"},{"id":"d","text":"Fibroblasts"}],"answerId":"a","explanation":"Homer-Wright rosettes are a diagnostic histological feature of neuroblastoma.","kind":"recall","origin":"ai"},{"id":"neuroblastoma~ai-2","moduleId":"neuroblastoma","stem":"A 2-year-old presents with a firm abdominal mass that crosses the midline. What is the most likely diagnosis?","options":[{"id":"a","text":"Wilms tumor"},{"id":"b","text":"Neuroblastoma"},{"id":"c","text":"Hepatoblastoma"},{"id":"d","text":"Rhabdomyosarcoma"}],"answerId":"b","explanation":"Neuroblastoma typically presents as an abdominal mass that crosses the midline, unlike Wilms tumor.","kind":"clinical","origin":"ai"},{"id":"neuroblastoma~ai-3","moduleId":"neuroblastoma","stem":"What is the mechanism of action for the catecholamine metabolites elevated in neuroblastoma?","options":[{"id":"a","text":"Increased catecholamine production"},{"id":"b","text":"Decreased catecholamine degradation"},{"id":"c","text":"Increased renal excretion"},{"id":"d","text":"Decreased adrenal synthesis"}],"answerId":"a","explanation":"Neuroblastoma cells produce catecholamines, leading to elevated urinary VMA and HVA.","kind":"mechanism","origin":"ai"},{"id":"neuroblastoma~ai-4","moduleId":"neuroblastoma","stem":"Which of the following findings is NOT typically associated with neuroblastoma?","options":[{"id":"a","text":"Proptosis"},{"id":"b","text":"Homer-Wright rosettes"},{"id":"c","text":"Elevated VMA"},{"id":"d","text":"Hypertension"}],"answerId":"d","explanation":"Sustained hypertension is uncommon in neuroblastoma, unlike in pheochromocytoma.","kind":"trap","origin":"ai"},{"id":"neuroblastoma~ai-5","moduleId":"neuroblastoma","stem":"A child with neuroblastoma presents with periorbital ecchymosis. Which mechanism explains this finding?","options":[{"id":"a","text":"Orbital metastasis"},{"id":"b","text":"Increased intracranial pressure"},{"id":"c","text":"Allergic reaction"},{"id":"d","text":"Trauma"}],"answerId":"a","explanation":"Periorbital ecchymosis, or 'raccoon eyes', results from orbital metastasis of neuroblastoma.","kind":"clinical","origin":"ai"},{"id":"neuroblastoma~ai-6","moduleId":"neuroblastoma","stem":"Neuroblastoma and pheochromocytoma are both derived from which embryonic structure?","options":[{"id":"a","text":"Notochord"},{"id":"b","text":"Neural crest"},{"id":"c","text":"Mesoderm"},{"id":"d","text":"Ectoderm"}],"answerId":"b","explanation":"Both neuroblastoma and pheochromocytoma originate from neural crest cells.","kind":"integration","linkedModuleIds":["pheochromocytoma-paraganglioma"],"origin":"ai"},{"id":"neuroblastoma~ai-7","moduleId":"neuroblastoma","stem":"How does the clinical presentation of neuroblastoma differ from Wilms tumor?","options":[{"id":"a","text":"Neuroblastoma typically crosses the midline"},{"id":"b","text":"Wilms tumor presents with elevated catecholamines"},{"id":"c","text":"Neuroblastoma is always bilateral"},{"id":"d","text":"Wilms tumor is more common in infants"}],"answerId":"a","explanation":"Neuroblastoma often crosses the midline, while Wilms tumor is usually unilateral and does not cross the midline.","kind":"integration","linkedModuleIds":["notochord-neurulation-neural-crest"],"origin":"ai"}],"adrenal-cushing-pathology":[{"id":"adrenal-cushing-pathology~ai-0","moduleId":"adrenal-cushing-pathology","stem":"What is the most common cause of Cushing syndrome?","options":[{"id":"a","text":"Adrenal adenoma"},{"id":"b","text":"Ectopic ACTH secretion"},{"id":"c","text":"Iatrogenic steroids"},{"id":"d","text":"Cushing disease"}],"answerId":"c","explanation":"Iatrogenic steroids are the most common cause of Cushing syndrome due to their widespread use in medical treatment.","kind":"recall","origin":"ai"},{"id":"adrenal-cushing-pathology~ai-1","moduleId":"adrenal-cushing-pathology","stem":"Which of the following findings is characteristic of adrenal cortical carcinoma?","options":[{"id":"a","text":"Small size and encapsulated"},{"id":"b","text":"Bilateral adrenal atrophy"},{"id":"c","text":"Large size with necrosis"},{"id":"d","text":"Low mitotic activity"}],"answerId":"c","explanation":"Adrenal cortical carcinoma is characterized by its large size, unencapsulated nature, and presence of necrosis.","kind":"recall","origin":"ai"},{"id":"adrenal-cushing-pathology~ai-2","moduleId":"adrenal-cushing-pathology","stem":"What mechanism leads to proximal muscle weakness in Cushing syndrome?","options":[{"id":"a","text":"Increased insulin resistance"},{"id":"b","text":"Glucocorticoid catabolic effect"},{"id":"c","text":"Electrolyte imbalance"},{"id":"d","text":"Increased ACTH levels"}],"answerId":"b","explanation":"The catabolic effects of glucocorticoids lead to muscle wasting and weakness.","kind":"mechanism","origin":"ai"},{"id":"adrenal-cushing-pathology~ai-3","moduleId":"adrenal-cushing-pathology","stem":"Which of the following statements about Cushing syndrome and Cushing disease is true?","options":[{"id":"a","text":"They are synonymous terms"},{"id":"b","text":"Cushing syndrome is caused only by adrenal tumors"},{"id":"c","text":"Cushing disease specifically refers to pituitary adenomas"},{"id":"d","text":"Cushing syndrome is always due to high ACTH levels"}],"answerId":"c","explanation":"Cushing disease refers specifically to hypercortisolism caused by an ACTH-secreting pituitary adenoma, while Cushing syndrome encompasses all causes of hypercortisolism.","kind":"trap","origin":"ai"},{"id":"adrenal-cushing-pathology~ai-4","moduleId":"adrenal-cushing-pathology","stem":"A patient presents with truncal obesity, moon facies, and purple abdominal striae. What is the underlying mechanism for these findings?","options":[{"id":"a","text":"Increased insulin secretion"},{"id":"b","text":"Cortisol-driven fat redistribution"},{"id":"c","text":"Hypothalamic dysfunction"},{"id":"d","text":"Decreased growth hormone levels"}],"answerId":"b","explanation":"Cortisol causes fat redistribution and collagen loss, leading to the characteristic physical findings in Cushing syndrome.","kind":"clinical","origin":"ai"},{"id":"adrenal-cushing-pathology~ai-5","moduleId":"adrenal-cushing-pathology","stem":"In a patient with adrenal insufficiency, which of the following findings would you expect on imaging?","options":[{"id":"a","text":"Bilateral adrenal hyperplasia"},{"id":"b","text":"Bilateral adrenal atrophy"},{"id":"c","text":"Adrenal adenoma"},{"id":"d","text":"Normal adrenal glands"}],"answerId":"b","explanation":"In adrenal insufficiency, especially secondary to exogenous glucocorticoids, you would expect bilateral adrenal atrophy due to suppressed ACTH levels.","kind":"integration","linkedModuleIds":["adrenal-insufficiency"],"origin":"ai"},{"id":"adrenal-cushing-pathology~ai-6","moduleId":"adrenal-cushing-pathology","stem":"How does hypercortisolism affect glucose metabolism?","options":[{"id":"a","text":"Increases insulin sensitivity"},{"id":"b","text":"Decreases gluconeogenesis"},{"id":"c","text":"Increases gluconeogenesis"},{"id":"d","text":"Decreases glycogenolysis"}],"answerId":"c","explanation":"Hypercortisolism increases gluconeogenesis, contributing to hyperglycemia and secondary diabetes.","kind":"integration","linkedModuleIds":["hen1-cortisol-systemic-actions"],"origin":"ai"}],"gnrh-gonadotropin-drugs":[{"id":"gnrh-gonadotropin-drugs~ai-0","moduleId":"gnrh-gonadotropin-drugs","stem":"What is the primary effect of continuous administration of a GnRH agonist like leuprolide?","options":[{"id":"a","text":"Increase LH and FSH levels"},{"id":"b","text":"Suppress LH and FSH levels"},{"id":"c","text":"Stimulate testosterone production"},{"id":"d","text":"Enhance ovarian follicle development"}],"answerId":"b","explanation":"Continuous administration of GnRH agonists downregulates GnRH receptors, leading to suppression of LH and FSH levels.","kind":"mechanism","origin":"ai"},{"id":"gnrh-gonadotropin-drugs~ai-1","moduleId":"gnrh-gonadotropin-drugs","stem":"Which of the following is a key adverse effect of continuous GnRH agonist therapy?","options":[{"id":"a","text":"Ovarian hyperstimulation syndrome"},{"id":"b","text":"Menopausal symptoms"},{"id":"c","text":"Multiple pregnancies"},{"id":"d","text":"Increased libido"}],"answerId":"b","explanation":"Continuous GnRH agonist therapy can lead to menopausal symptoms due to decreased estrogen levels.","kind":"trap","origin":"ai"},{"id":"gnrh-gonadotropin-drugs~ai-2","moduleId":"gnrh-gonadotropin-drugs","stem":"What is the mechanism of action of GnRH antagonists like ganirelix?","options":[{"id":"a","text":"Stimulate LH release"},{"id":"b","text":"Block premature LH surge"},{"id":"c","text":"Increase FSH levels"},{"id":"d","text":"Enhance testosterone production"}],"answerId":"b","explanation":"GnRH antagonists block the premature LH surge, which is crucial during controlled ovarian stimulation.","kind":"mechanism","origin":"ai"},{"id":"gnrh-gonadotropin-drugs~ai-3","moduleId":"gnrh-gonadotropin-drugs","stem":"Which gonadotropin is primarily responsible for triggering final oocyte maturation?","options":[{"id":"a","text":"FSH"},{"id":"b","text":"LH"},{"id":"c","text":"hCG"},{"id":"d","text":"GnRH"}],"answerId":"c","explanation":"hCG is nearly identical to LH and is used to trigger final oocyte maturation in ovulation induction.","kind":"recall","origin":"ai"},{"id":"gnrh-gonadotropin-drugs~ai-4","moduleId":"gnrh-gonadotropin-drugs","stem":"A patient undergoing IVF develops ascites and enlarged ovaries. What is the likely cause?","options":[{"id":"a","text":"Ovarian hyperstimulation syndrome"},{"id":"b","text":"Multiple pregnancy"},{"id":"c","text":"GnRH agonist side effects"},{"id":"d","text":"Infection"}],"answerId":"a","explanation":"Ascites and enlarged ovaries after ovulation induction are classic signs of ovarian hyperstimulation syndrome (OHSS).","kind":"recall","origin":"ai"},{"id":"gnrh-gonadotropin-drugs~ai-5","moduleId":"gnrh-gonadotropin-drugs","stem":"How does the administration of pulsatile GnRH differ from continuous GnRH in terms of gonadotropin release?","options":[{"id":"a","text":"Both stimulate LH and FSH"},{"id":"b","text":"Pulsatile stimulates, continuous suppresses"},{"id":"c","text":"Continuous stimulates, pulsatile suppresses"},{"id":"d","text":"Neither affects LH and FSH"}],"answerId":"b","explanation":"Pulsatile administration stimulates LH and FSH release, while continuous administration suppresses them.","kind":"mechanism","origin":"ai"},{"id":"gnrh-gonadotropin-drugs~ai-6","moduleId":"gnrh-gonadotropin-drugs","stem":"In the context of male reproductive physiology, what is the effect of GnRH agonists on testosterone levels when given continuously?","options":[{"id":"a","text":"Increase testosterone levels"},{"id":"b","text":"Decrease testosterone levels"},{"id":"c","text":"No effect on testosterone levels"},{"id":"d","text":"Increase LH and FSH leading to increased testosterone"}],"answerId":"b","explanation":"Continuous GnRH agonist administration leads to decreased testosterone levels due to downregulation of gonadotropin release.","kind":"integration","linkedModuleIds":["hrp1-male-hpg-axis"],"origin":"ai"},{"id":"gnrh-gonadotropin-drugs~ai-7","moduleId":"gnrh-gonadotropin-drugs","stem":"Which hormonal changes occur in response to pulsatile GnRH administration in females undergoing IVF?","options":[{"id":"a","text":"Increased LH and FSH"},{"id":"b","text":"Decreased LH and FSH"},{"id":"c","text":"Increased estrogen only"},{"id":"d","text":"No change in hormone levels"}],"answerId":"a","explanation":"Pulsatile GnRH administration stimulates the release of LH and FSH, which is essential for ovarian function during IVF.","kind":"integration","linkedModuleIds":["hrp1-ovarian-steroid-two-cell-model"],"origin":"ai"}],"adrenal-insufficiency":[{"id":"adrenal-insufficiency~ai-0","moduleId":"adrenal-insufficiency","stem":"What is the most common cause of primary adrenal insufficiency (Addison's disease)?","options":[{"id":"a","text":"Tuberculosis"},{"id":"b","text":"Autoimmune adrenalitis"},{"id":"c","text":"Adrenal hemorrhage"},{"id":"d","text":"Metastatic cancer"}],"answerId":"b","explanation":"Autoimmune adrenalitis is the most common cause of primary adrenal insufficiency.","kind":"recall","origin":"ai"},{"id":"adrenal-insufficiency~ai-1","moduleId":"adrenal-insufficiency","stem":"In primary adrenal insufficiency, which of the following lab findings is expected?","options":[{"id":"a","text":"High ACTH, low cortisol, normal potassium"},{"id":"b","text":"High ACTH, low cortisol, high potassium"},{"id":"c","text":"Low ACTH, low cortisol, high potassium"},{"id":"d","text":"Normal ACTH, low cortisol, normal potassium"}],"answerId":"b","explanation":"Primary adrenal insufficiency is characterized by high ACTH, low cortisol, and hyperkalemia due to aldosterone deficiency.","kind":"recall","origin":"ai"},{"id":"adrenal-insufficiency~ai-2","moduleId":"adrenal-insufficiency","stem":"Which symptom is a key distinguishing feature of primary adrenal insufficiency compared to secondary adrenal insufficiency?","options":[{"id":"a","text":"Hyponatremia"},{"id":"b","text":"Hyperkalemia"},{"id":"c","text":"Hyperpigmentation"},{"id":"d","text":"Hypoglycemia"}],"answerId":"c","explanation":"Hyperpigmentation occurs in primary adrenal insufficiency due to elevated ACTH, which also stimulates melanocyte activity.","kind":"trap","origin":"ai"},{"id":"adrenal-insufficiency~ai-3","moduleId":"adrenal-insufficiency","stem":"What triggers an acute adrenal crisis in a patient with chronic adrenal insufficiency?","options":[{"id":"a","text":"Increased ACTH secretion"},{"id":"b","text":"Abrupt steroid withdrawal"},{"id":"c","text":"Increased aldosterone production"},{"id":"d","text":"Chronic stress"}],"answerId":"b","explanation":"An acute adrenal crisis can be triggered by abrupt withdrawal of corticosteroids in patients with chronic adrenal insufficiency.","kind":"clinical","origin":"ai"},{"id":"adrenal-insufficiency~ai-4","moduleId":"adrenal-insufficiency","stem":"Which clinical finding is associated with Waterhouse-Friderichsen syndrome?","options":[{"id":"a","text":"Bilateral adrenal hemorrhage"},{"id":"b","text":"Hyperpigmentation"},{"id":"c","text":"Hypokalemia"},{"id":"d","text":"Elevated cortisol levels"}],"answerId":"a","explanation":"Waterhouse-Friderichsen syndrome is characterized by bilateral adrenal hemorrhage, often due to septicemia.","kind":"recall","origin":"ai"},{"id":"adrenal-insufficiency~ai-5","moduleId":"adrenal-insufficiency","stem":"How does primary adrenal insufficiency affect aldosterone levels?","options":[{"id":"a","text":"Aldosterone is elevated"},{"id":"b","text":"Aldosterone is low"},{"id":"c","text":"Aldosterone is normal"},{"id":"d","text":"Aldosterone is variable"}],"answerId":"b","explanation":"In primary adrenal insufficiency, both cortisol and aldosterone levels are low due to adrenal cortex destruction.","kind":"mechanism","origin":"ai"},{"id":"adrenal-insufficiency~ai-6","moduleId":"adrenal-insufficiency","stem":"In a patient with adrenal insufficiency presenting with hypoglycemia, which linked module is most relevant to understand the metabolic implications?","options":[{"id":"a","text":"Aldosterone Synthesis, Action & RAAS Control"},{"id":"b","text":"Cortisol Metabolic, Stress & Anti-inflammatory Actions"},{"id":"c","text":"MCAD Deficiency & Hypoketotic Hypoglycemia"},{"id":"d","text":"Congenital Adrenal Hyperplasia"}],"answerId":"b","explanation":"Cortisol plays a critical role in glucose metabolism and stress response, making this module relevant for understanding hypoglycemia in adrenal insufficiency.","kind":"integration","linkedModuleIds":["hen1-cortisol-systemic-actions"],"origin":"ai"},{"id":"adrenal-insufficiency~ai-7","moduleId":"adrenal-insufficiency","stem":"Which condition can lead to secondary adrenal insufficiency, sparing aldosterone levels?","options":[{"id":"a","text":"Addison's disease"},{"id":"b","text":"Pituitary adenoma"},{"id":"c","text":"Congenital adrenal hyperplasia"},{"id":"d","text":"Cushing's syndrome"}],"answerId":"b","explanation":"Secondary adrenal insufficiency results from pituitary ACTH deficiency, which spares aldosterone production due to RAAS.","kind":"integration","linkedModuleIds":["hyperaldosteronism"],"origin":"ai"}],"congenital-adrenal-hyperplasia":[{"id":"congenital-adrenal-hyperplasia~ai-0","moduleId":"congenital-adrenal-hyperplasia","stem":"What is the most common enzyme deficiency causing congenital adrenal hyperplasia?","options":[{"id":"a","text":"21-hydroxylase"},{"id":"b","text":"11-hydroxylase"},{"id":"c","text":"17-alpha-hydroxylase"},{"id":"d","text":"3-beta-hydroxysteroid dehydrogenase"}],"answerId":"a","explanation":"21-hydroxylase deficiency (CYP21A2) accounts for approximately 90% of congenital adrenal hyperplasia cases.","kind":"recall","origin":"ai"},{"id":"congenital-adrenal-hyperplasia~ai-1","moduleId":"congenital-adrenal-hyperplasia","stem":"In congenital adrenal hyperplasia due to 21-hydroxylase deficiency, what happens to cortisol and aldosterone levels?","options":[{"id":"a","text":"Both increase"},{"id":"b","text":"Both decrease"},{"id":"c","text":"Cortisol decreases, aldosterone increases"},{"id":"d","text":"Cortisol decreases, aldosterone remains normal"}],"answerId":"b","explanation":"21-hydroxylase deficiency leads to decreased cortisol and aldosterone levels due to the enzymatic block.","kind":"mechanism","origin":"ai"},{"id":"congenital-adrenal-hyperplasia~ai-2","moduleId":"congenital-adrenal-hyperplasia","stem":"A newborn girl presents with ambiguous genitalia and a salt-wasting crisis. What is the most likely diagnosis?","options":[{"id":"a","text":"Simple virilizing CAH"},{"id":"b","text":"Classic salt-wasting CAH"},{"id":"c","text":"Late-onset CAH"},{"id":"d","text":"Adrenal insufficiency"}],"answerId":"b","explanation":"The presentation is consistent with classic salt-wasting congenital adrenal hyperplasia due to 21-hydroxylase deficiency.","kind":"clinical","origin":"ai"},{"id":"congenital-adrenal-hyperplasia~ai-3","moduleId":"congenital-adrenal-hyperplasia","stem":"What is a common clinical finding in a young child with 21-hydroxylase deficiency?","options":[{"id":"a","text":"Short stature due to early epiphyseal fusion"},{"id":"b","text":"Hyperpigmentation of the skin"},{"id":"c","text":"Hypertension"},{"id":"d","text":"Hypoglycemia"}],"answerId":"a","explanation":"Androgen excess from 21-hydroxylase deficiency can lead to precocious puberty and early epiphyseal fusion, resulting in short stature.","kind":"recall","origin":"ai"},{"id":"congenital-adrenal-hyperplasia~ai-4","moduleId":"congenital-adrenal-hyperplasia","stem":"Which of the following statements about androgen levels in 21-hydroxylase deficiency is true?","options":[{"id":"a","text":"Androgens are decreased"},{"id":"b","text":"Androgens are normal"},{"id":"c","text":"Androgens are increased"},{"id":"d","text":"Androgens are absent"}],"answerId":"c","explanation":"In 21-hydroxylase deficiency, cortisol and aldosterone are decreased, but androgens are increased due to shunting of precursors.","kind":"trap","origin":"ai"},{"id":"congenital-adrenal-hyperplasia~ai-5","moduleId":"congenital-adrenal-hyperplasia","stem":"How does congenital adrenal hyperplasia relate to cellular adaptations?","options":[{"id":"a","text":"It causes hypertrophy of adrenal glands"},{"id":"b","text":"It leads to atrophy of adrenal glands"},{"id":"c","text":"It induces hyperplasia of adrenal cortex"},{"id":"d","text":"It results in necrosis of adrenal glands"}],"answerId":"c","explanation":"Congenital adrenal hyperplasia leads to adrenal cortex hyperplasia due to increased ACTH stimulation in response to low cortisol levels.","kind":"integration","linkedModuleIds":["cellular-adaptations-growth"],"origin":"ai"},{"id":"congenital-adrenal-hyperplasia~ai-6","moduleId":"congenital-adrenal-hyperplasia","stem":"What is a potential complication of untreated congenital adrenal hyperplasia that relates to adrenal insufficiency?","options":[{"id":"a","text":"Hyperaldosteronism"},{"id":"b","text":"Adrenal crisis"},{"id":"c","text":"Cushing's syndrome"},{"id":"d","text":"Pheochromocytoma"}],"answerId":"b","explanation":"Untreated congenital adrenal hyperplasia can lead to adrenal crisis due to severe cortisol deficiency.","kind":"integration","linkedModuleIds":["adrenal-insufficiency"],"origin":"ai"}],"cushing-management-steroid-withdrawal":[{"id":"cushing-management-steroid-withdrawal~ai-0","moduleId":"cushing-management-steroid-withdrawal","stem":"What is the definitive treatment for Cushing's disease?","options":[{"id":"a","text":"Transsphenoidal resection"},{"id":"b","text":"Radiation therapy"},{"id":"c","text":"Mifepristone administration"},{"id":"d","text":"Ketoconazole therapy"}],"answerId":"a","explanation":"Transsphenoidal resection is the definitive treatment for Cushing's disease, targeting the source of excess cortisol production.","kind":"recall","origin":"ai"},{"id":"cushing-management-steroid-withdrawal~ai-1","moduleId":"cushing-management-steroid-withdrawal","stem":"What is the recommended approach to tapering long-term glucocorticoids?","options":[{"id":"a","text":"Stop abruptly to prevent side effects"},{"id":"b","text":"Taper gradually to a physiologic dose"},{"id":"c","text":"Switch to a higher dose before stopping"},{"id":"d","text":"Maintain the same dose indefinitely"}],"answerId":"b","explanation":"Gradual tapering is essential to allow the adrenal glands to recover and prevent adrenal crisis.","kind":"trap","origin":"ai"},{"id":"cushing-management-steroid-withdrawal~ai-2","moduleId":"cushing-management-steroid-withdrawal","stem":"What does a 9 AM cortisol level <1.8 µg/dL indicate after surgery for Cushing's disease?","options":[{"id":"a","text":"Adrenal crisis"},{"id":"b","text":"Successful removal of the cortisol source"},{"id":"c","text":"Need for continued steroid replacement"},{"id":"d","text":"Failure of surgery"}],"answerId":"b","explanation":"A 9 AM cortisol level <1.8 µg/dL indicates successful removal of the cortisol source and suppression of remaining corticotrophs.","kind":"recall","origin":"ai"},{"id":"cushing-management-steroid-withdrawal~ai-3","moduleId":"cushing-management-steroid-withdrawal","stem":"What is the appropriate management for a patient experiencing shock after stopping long-term prednisolone?","options":[{"id":"a","text":"Immediate reinitiation of prednisolone"},{"id":"b","text":"Hydrocortisone IV administration"},{"id":"c","text":"Increase fluid intake only"},{"id":"d","text":"Observation without intervention"}],"answerId":"b","explanation":"Shock after stopping prednisolone indicates adrenal crisis, requiring immediate hydrocortisone IV administration.","kind":"clinical","origin":"ai"},{"id":"cushing-management-steroid-withdrawal~ai-4","moduleId":"cushing-management-steroid-withdrawal","stem":"Which of the following is a sign of HPA axis recovery after tapering steroids?","options":[{"id":"a","text":"Morning cortisol >18 µg/dL"},{"id":"b","text":"9 AM cortisol <1.8 µg/dL"},{"id":"c","text":"Persistent fatigue"},{"id":"d","text":"Weight gain"}],"answerId":"a","explanation":"A morning cortisol level >18 µg/dL indicates that the HPA axis has recovered and steroid replacement can be stopped.","kind":"recall","origin":"ai"},{"id":"cushing-management-steroid-withdrawal~ai-5","moduleId":"cushing-management-steroid-withdrawal","stem":"How does chronic glucocorticoid therapy affect the adrenal glands?","options":[{"id":"a","text":"Stimulates adrenal hyperplasia"},{"id":"b","text":"Causes adrenal atrophy"},{"id":"c","text":"Enhances cortisol production"},{"id":"d","text":"Increases ACTH secretion"}],"answerId":"b","explanation":"Chronic glucocorticoid therapy suppresses the HPA axis, leading to adrenal atrophy due to lack of stimulation.","kind":"mechanism","origin":"ai"},{"id":"cushing-management-steroid-withdrawal~ai-6","moduleId":"cushing-management-steroid-withdrawal","stem":"What is the relationship between Cushing's management and cortisol's systemic actions?","options":[{"id":"a","text":"Cortisol promotes adrenal recovery"},{"id":"b","text":"Cushing's management aims to reduce cortisol effects"},{"id":"c","text":"Cortisol is irrelevant in Cushing's treatment"},{"id":"d","text":"Cushing's management enhances cortisol's anti-inflammatory actions"}],"answerId":"b","explanation":"Cushing's management focuses on reducing the effects of excess cortisol, which can lead to systemic complications.","kind":"integration","linkedModuleIds":["hen1-cortisol-systemic-actions"],"origin":"ai"},{"id":"cushing-management-steroid-withdrawal~ai-7","moduleId":"cushing-management-steroid-withdrawal","stem":"In patients with Cushing's syndrome, what role does the HPA axis play in steroid withdrawal?","options":[{"id":"a","text":"It enhances cortisol production"},{"id":"b","text":"It must be suppressed before withdrawal"},{"id":"c","text":"It requires monitoring for recovery"},{"id":"d","text":"It is unaffected by steroid therapy"}],"answerId":"c","explanation":"Monitoring the HPA axis recovery is crucial during steroid withdrawal to prevent adrenal crisis.","kind":"integration","linkedModuleIds":["cushing-diagnosis-workup"],"origin":"ai"}],"growth-hormone-prolactin-drugs":[{"id":"growth-hormone-prolactin-drugs~ai-0","moduleId":"growth-hormone-prolactin-drugs","stem":"What is the primary mechanism of action of somatropin in treating GH deficiency?","options":[{"id":"a","text":"Inhibits GH release"},{"id":"b","text":"Stimulates IGF-1 production"},{"id":"c","text":"Blocks GH receptors"},{"id":"d","text":"Increases insulin sensitivity"}],"answerId":"b","explanation":"Somatropin stimulates the liver to produce IGF-1, which mediates growth effects.","kind":"mechanism","origin":"ai"},{"id":"growth-hormone-prolactin-drugs~ai-1","moduleId":"growth-hormone-prolactin-drugs","stem":"Which drug is indicated for patients with severe IGF-1 deficiency unresponsive to GH?","options":[{"id":"a","text":"Octreotide"},{"id":"b","text":"Pegvisomant"},{"id":"c","text":"Mecasermin"},{"id":"d","text":"Cabergoline"}],"answerId":"c","explanation":"Mecasermin is recombinant IGF-1 used when GH therapy fails to raise IGF-1 levels.","kind":"recall","origin":"ai"},{"id":"growth-hormone-prolactin-drugs~ai-2","moduleId":"growth-hormone-prolactin-drugs","stem":"A patient presents with galactorrhea after starting risperidone. What is the most likely cause?","options":[{"id":"a","text":"Prolactinoma"},{"id":"b","text":"Dopamine receptor blockade"},{"id":"c","text":"Pregnancy"},{"id":"d","text":"Hypothyroidism"}],"answerId":"b","explanation":"Risperidone is a dopamine antagonist that can cause hyperprolactinemia and galactorrhea.","kind":"clinical","origin":"ai"},{"id":"growth-hormone-prolactin-drugs~ai-3","moduleId":"growth-hormone-prolactin-drugs","stem":"What is a common side effect of octreotide treatment?","options":[{"id":"a","text":"Hypoglycemia"},{"id":"b","text":"Gallstones"},{"id":"c","text":"Hypertension"},{"id":"d","text":"Weight gain"}],"answerId":"b","explanation":"Octreotide can inhibit gallbladder contraction, leading to gallstone formation.","kind":"recall","origin":"ai"},{"id":"growth-hormone-prolactin-drugs~ai-4","moduleId":"growth-hormone-prolactin-drugs","stem":"Which of the following drugs is a dopamine agonist used to treat hyperprolactinemia?","options":[{"id":"a","text":"Bromocriptine"},{"id":"b","text":"Metoclopramide"},{"id":"c","text":"Pegvisomant"},{"id":"d","text":"Octreotide"}],"answerId":"a","explanation":"Bromocriptine is a dopamine agonist that suppresses prolactin secretion.","kind":"recall","origin":"ai"},{"id":"growth-hormone-prolactin-drugs~ai-5","moduleId":"growth-hormone-prolactin-drugs","stem":"A patient with acromegaly is treated with pegvisomant. What is the expected outcome?","options":[{"id":"a","text":"Increased GH levels"},{"id":"b","text":"Decreased IGF-1 levels"},{"id":"c","text":"Decreased GH receptor signaling"},{"id":"d","text":"Increased insulin sensitivity"}],"answerId":"c","explanation":"Pegvisomant is a GH-receptor antagonist that blocks GH signaling, reducing its effects.","kind":"mechanism","origin":"ai"},{"id":"growth-hormone-prolactin-drugs~ai-6","moduleId":"growth-hormone-prolactin-drugs","stem":"How does GH affect insulin sensitivity compared to IGF-1?","options":[{"id":"a","text":"Both increase insulin sensitivity"},{"id":"b","text":"GH decreases, IGF-1 increases"},{"id":"c","text":"Both decrease insulin sensitivity"},{"id":"d","text":"GH increases, IGF-1 decreases"}],"answerId":"b","explanation":"GH reduces insulin sensitivity leading to hyperglycemia, while IGF-1 has insulin-like effects.","kind":"integration","linkedModuleIds":["hen1-growth-hormone-igf1"],"origin":"ai"},{"id":"growth-hormone-prolactin-drugs~ai-7","moduleId":"growth-hormone-prolactin-drugs","stem":"What is a common cause of drug-induced hyperprolactinemia?","options":[{"id":"a","text":"Dopamine agonists"},{"id":"b","text":"Dopamine antagonists"},{"id":"c","text":"Somatostatin analogs"},{"id":"d","text":"GH-receptor antagonists"}],"answerId":"b","explanation":"Dopamine antagonists, such as antipsychotics, block dopamine's inhibitory effect on prolactin release.","kind":"trap","origin":"ai"},{"id":"growth-hormone-prolactin-drugs~ai-8","moduleId":"growth-hormone-prolactin-drugs","stem":"Which drug class is primarily used to treat acromegaly?","options":[{"id":"a","text":"Dopamine agonists"},{"id":"b","text":"Somatostatin analogs"},{"id":"c","text":"GH-receptor antagonists"},{"id":"d","text":"Insulin sensitizers"}],"answerId":"b","explanation":"Somatostatin analogs like octreotide inhibit GH release and are first-line treatment for acromegaly.","kind":"integration","linkedModuleIds":["gnrh-gonadotropin-drugs"],"origin":"ai"}],"hyperaldosteronism":[{"id":"hyperaldosteronism~ai-0","moduleId":"hyperaldosteronism","stem":"What is the most common cause of primary hyperaldosteronism?","options":[{"id":"a","text":"Aldosterone-producing adenoma"},{"id":"b","text":"Bilateral idiopathic adrenal hyperplasia"},{"id":"c","text":"Renal artery stenosis"},{"id":"d","text":"Cirrhosis"}],"answerId":"b","explanation":"Bilateral idiopathic adrenal hyperplasia is the most common cause of primary hyperaldosteronism, accounting for approximately 60% of cases.","kind":"recall","origin":"ai"},{"id":"hyperaldosteronism~ai-1","moduleId":"hyperaldosteronism","stem":"In primary hyperaldosteronism, what is the expected level of renin?","options":[{"id":"a","text":"High"},{"id":"b","text":"Low"},{"id":"c","text":"Normal"},{"id":"d","text":"Variable"}],"answerId":"b","explanation":"In primary hyperaldosteronism, renin levels are low due to autonomous production of aldosterone by the adrenal glands.","kind":"mechanism","origin":"ai"},{"id":"hyperaldosteronism~ai-2","moduleId":"hyperaldosteronism","stem":"A patient presents with hypertension, hypokalemia, and metabolic alkalosis. Which test would best differentiate primary from secondary hyperaldosteronism?","options":[{"id":"a","text":"Aldosterone suppression test"},{"id":"b","text":"Serum potassium level"},{"id":"c","text":"Aldosterone-to-renin ratio"},{"id":"d","text":"CT scan of the adrenal glands"}],"answerId":"c","explanation":"The aldosterone-to-renin ratio is a key screening test that helps differentiate primary hyperaldosteronism (high ARR) from secondary causes (low ARR).","kind":"clinical","origin":"ai"},{"id":"hyperaldosteronism~ai-3","moduleId":"hyperaldosteronism","stem":"Which histological finding is characteristic of a Conn adenoma after spironolactone treatment?","options":[{"id":"a","text":"Lipid-laden cells"},{"id":"b","text":"Spironolactone bodies"},{"id":"c","text":"Fibrosis"},{"id":"d","text":"Necrosis"}],"answerId":"b","explanation":"Spironolactone bodies are laminated eosinophilic inclusions seen in Conn adenomas after treatment with spironolactone.","kind":"recall","origin":"ai"},{"id":"hyperaldosteronism~ai-4","moduleId":"hyperaldosteronism","stem":"What is the mechanism of hypertension in primary hyperaldosteronism?","options":[{"id":"a","text":"Increased sodium reabsorption"},{"id":"b","text":"Decreased blood volume"},{"id":"c","text":"Increased renin secretion"},{"id":"d","text":"Decreased aldosterone secretion"}],"answerId":"a","explanation":"Hypertension in primary hyperaldosteronism is primarily due to increased sodium reabsorption leading to increased blood volume.","kind":"mechanism","origin":"ai"},{"id":"hyperaldosteronism~ai-5","moduleId":"hyperaldosteronism","stem":"A patient with primary hyperaldosteronism has a high aldosterone level and low renin level. Which condition is most likely causing this?","options":[{"id":"a","text":"Renal artery stenosis"},{"id":"b","text":"Congestive heart failure"},{"id":"c","text":"Adrenal adenoma"},{"id":"d","text":"Cirrhosis"}],"answerId":"c","explanation":"An adrenal adenoma causes autonomous production of aldosterone, leading to high aldosterone and low renin levels in primary hyperaldosteronism.","kind":"trap","origin":"ai"},{"id":"hyperaldosteronism~ai-6","moduleId":"hyperaldosteronism","stem":"How does primary hyperaldosteronism relate to the RAAS system?","options":[{"id":"a","text":"It increases renin production"},{"id":"b","text":"It causes low renin levels"},{"id":"c","text":"It decreases aldosterone secretion"},{"id":"d","text":"It has no effect on RAAS"}],"answerId":"b","explanation":"In primary hyperaldosteronism, autonomous aldosterone production suppresses renin levels, thus uncoupling the normal feedback mechanism of the RAAS.","kind":"integration","linkedModuleIds":["hen1-aldosterone-raas"],"origin":"ai"},{"id":"hyperaldosteronism~ai-7","moduleId":"hyperaldosteronism","stem":"In the context of adrenal insufficiency, how might hyperaldosteronism present differently?","options":[{"id":"a","text":"Increased potassium levels"},{"id":"b","text":"Decreased blood pressure"},{"id":"c","text":"Increased renin levels"},{"id":"d","text":"Decreased aldosterone levels"}],"answerId":"a","explanation":"Adrenal insufficiency typically presents with hyperkalemia, while hyperaldosteronism presents with hypokalemia due to excess aldosterone.","kind":"integration","linkedModuleIds":["adrenal-insufficiency"],"origin":"ai"}],"cushing-diagnosis-workup":[{"id":"cushing-diagnosis-workup~ai-0","moduleId":"cushing-diagnosis-workup","stem":"What is the primary mechanism by which cortisol secretion is regulated in the body?","options":[{"id":"a","text":"Negative feedback on ACTH"},{"id":"b","text":"Positive feedback on CRH"},{"id":"c","text":"HPA axis stimulation"},{"id":"d","text":"Circadian rhythm control"}],"answerId":"c","explanation":"Cortisol secretion is primarily regulated by the hypothalamic-pituitary-adrenal (HPA) axis, which involves CRH stimulating ACTH release, leading to cortisol production.","kind":"mechanism","origin":"ai"},{"id":"cushing-diagnosis-workup~ai-1","moduleId":"cushing-diagnosis-workup","stem":"Which test is essential for confirming hypercortisolism in suspected Cushing syndrome?","options":[{"id":"a","text":"24-hour urinary free cortisol"},{"id":"b","text":"Plasma ACTH levels"},{"id":"c","text":"High-dose dexamethasone suppression test"},{"id":"d","text":"Late-night salivary cortisol"}],"answerId":"a","explanation":"The 24-hour urinary free cortisol test is one of the primary tests used to confirm hypercortisolism in Cushing syndrome.","kind":"recall","origin":"ai"},{"id":"cushing-diagnosis-workup~ai-2","moduleId":"cushing-diagnosis-workup","stem":"In a patient with suspected Cushing disease, which finding on a high-dose dexamethasone suppression test indicates a pituitary source?","options":[{"id":"a","text":"No suppression of cortisol"},{"id":"b","text":"Partial suppression of cortisol"},{"id":"c","text":"Complete suppression of cortisol"},{"id":"d","text":"Increased ACTH levels"}],"answerId":"b","explanation":"Partial suppression of cortisol on high-dose dexamethasone indicates a pituitary source (Cushing disease), as pituitary adenomas retain some feedback sensitivity.","kind":"clinical","origin":"ai"},{"id":"cushing-diagnosis-workup~ai-3","moduleId":"cushing-diagnosis-workup","stem":"A patient presents with very high ACTH levels and no suppression on both low and high-dose dexamethasone tests. What is the most likely diagnosis?","options":[{"id":"a","text":"Cushing disease"},{"id":"b","text":"Ectopic ACTH syndrome"},{"id":"c","text":"Adrenal adenoma"},{"id":"d","text":"Exogenous Cushing syndrome"}],"answerId":"b","explanation":"Very high ACTH levels with no suppression on either dexamethasone test suggests ectopic ACTH syndrome, often associated with small-cell lung cancer.","kind":"clinical","origin":"ai"},{"id":"cushing-diagnosis-workup~ai-4","moduleId":"cushing-diagnosis-workup","stem":"What is a common pitfall when interpreting high-dose dexamethasone suppression test results?","options":[{"id":"a","text":"Assuming all patients with Cushing syndrome will suppress"},{"id":"b","text":"Confusing suppression with adrenal causes"},{"id":"c","text":"Misinterpreting partial suppression as no Cushing disease"},{"id":"d","text":"Ignoring the role of ACTH levels"}],"answerId":"c","explanation":"A common pitfall is misinterpreting partial suppression on high-dose dexamethasone as indicating no Cushing disease, when it actually suggests a pituitary source.","kind":"trap","origin":"ai"},{"id":"cushing-diagnosis-workup~ai-5","moduleId":"cushing-diagnosis-workup","stem":"Which of the following findings would indicate adrenal Cushing syndrome?","options":[{"id":"a","text":"High ACTH, cortisol suppresses on high-dose dex"},{"id":"b","text":"Low ACTH, no suppression on either dose"},{"id":"c","text":"High ACTH, no suppression on either dose"},{"id":"d","text":"Low ACTH, cortisol suppresses on high-dose dex"}],"answerId":"b","explanation":"In adrenal Cushing syndrome, ACTH levels are low and cortisol does not suppress on either low or high-dose dexamethasone tests.","kind":"recall","origin":"ai"},{"id":"cushing-diagnosis-workup~ai-6","moduleId":"cushing-diagnosis-workup","stem":"How does the HPA axis relate to cortisol regulation in Cushing syndrome?","options":[{"id":"a","text":"Cortisol directly stimulates ACTH release"},{"id":"b","text":"CRH is suppressed by high cortisol levels"},{"id":"c","text":"ACTH levels are always elevated in Cushing syndrome"},{"id":"d","text":"Cortisol secretion is independent of the HPA axis in Cushing syndrome"}],"answerId":"b","explanation":"In Cushing syndrome, high cortisol levels suppress CRH release, disrupting the normal feedback mechanism of the HPA axis.","kind":"integration","linkedModuleIds":["hen1-cortisol-hpa-axis"],"origin":"ai"},{"id":"cushing-diagnosis-workup~ai-7","moduleId":"cushing-diagnosis-workup","stem":"What is the relationship between cortisol levels and ACTH in the context of Cushing syndrome management?","options":[{"id":"a","text":"High cortisol always indicates adrenal causes"},{"id":"b","text":"ACTH levels guide the localization of the source"},{"id":"c","text":"Cortisol levels are unaffected by ACTH"},{"id":"d","text":"Management strategies do not depend on ACTH levels"}],"answerId":"b","explanation":"ACTH levels are crucial for localizing the source of hypercortisolism in Cushing syndrome management, differentiating between adrenal and ACTH-dependent causes.","kind":"integration","linkedModuleIds":["cushing-management-steroid-withdrawal"],"origin":"ai"}],"posterior-pituitary-drugs":[{"id":"posterior-pituitary-drugs~ai-0","moduleId":"posterior-pituitary-drugs","stem":"What is the primary mechanism of action of vasopressin (ADH) at the V2 receptor?","options":[{"id":"a","text":"Vasoconstriction of vascular smooth muscle"},{"id":"b","text":"Increased water reabsorption in the renal collecting duct"},{"id":"c","text":"Stimulation of uterine contractions"},{"id":"d","text":"Inhibition of diuresis"}],"answerId":"b","explanation":"Vasopressin acts on V2 receptors in the renal collecting duct to promote water reabsorption, leading to antidiuresis.","kind":"mechanism","origin":"ai"},{"id":"posterior-pituitary-drugs~ai-1","moduleId":"posterior-pituitary-drugs","stem":"Which condition is desmopressin primarily used to treat?","options":[{"id":"a","text":"Nephrogenic diabetes insipidus"},{"id":"b","text":"Central diabetes insipidus"},{"id":"c","text":"Postpartum hemorrhage"},{"id":"d","text":"Hyponatremia due to SIADH"}],"answerId":"b","explanation":"Desmopressin is a selective V2 agonist used to treat central diabetes insipidus by promoting water reabsorption.","kind":"recall","origin":"ai"},{"id":"posterior-pituitary-drugs~ai-2","moduleId":"posterior-pituitary-drugs","stem":"What is a potential adverse effect of oxytocin administration during labor?","options":[{"id":"a","text":"Uterine atony"},{"id":"b","text":"Fetal distress"},{"id":"c","text":"Increased blood pressure"},{"id":"d","text":"Thrombocytopenia"}],"answerId":"b","explanation":"Excessive oxytocin can lead to uterine hyperstimulation, resulting in fetal distress.","kind":"trap","origin":"ai"},{"id":"posterior-pituitary-drugs~ai-3","moduleId":"posterior-pituitary-drugs","stem":"In a patient with central diabetes insipidus, what would you expect after administering desmopressin?","options":[{"id":"a","text":"Increased urine output"},{"id":"b","text":"Decreased serum sodium"},{"id":"c","text":"Decreased urine osmolality"},{"id":"d","text":"Increased urine osmolality"}],"answerId":"d","explanation":"Desmopressin increases water reabsorption, leading to increased urine osmolality in central diabetes insipidus.","kind":"clinical","origin":"ai"},{"id":"posterior-pituitary-drugs~ai-4","moduleId":"posterior-pituitary-drugs","stem":"How does tolvaptan help manage hyponatremia in patients with SIADH?","options":[{"id":"a","text":"Increases free-water retention"},{"id":"b","text":"Inhibits vasopressin secretion"},{"id":"c","text":"Blocks V2 receptors to promote aquaresis"},{"id":"d","text":"Stimulates renal sodium reabsorption"}],"answerId":"c","explanation":"Tolvaptan is a V2 receptor antagonist that promotes free-water excretion, helping to correct hyponatremia.","kind":"mechanism","origin":"ai"},{"id":"posterior-pituitary-drugs~ai-5","moduleId":"posterior-pituitary-drugs","stem":"How does the suckling reflex relate to oxytocin release during breastfeeding?","options":[{"id":"a","text":"Inhibits oxytocin release"},{"id":"b","text":"Stimulates prolactin release"},{"id":"c","text":"Stimulates oxytocin release"},{"id":"d","text":"Inhibits milk letdown"}],"answerId":"c","explanation":"The suckling reflex stimulates the release of oxytocin, which facilitates milk ejection during breastfeeding.","kind":"integration","linkedModuleIds":["hrp1-suckling-prolactin-oxytocin"],"origin":"ai"},{"id":"posterior-pituitary-drugs~ai-6","moduleId":"posterior-pituitary-drugs","stem":"What is the effect of oxytocin on uterine smooth muscle during labor?","options":[{"id":"a","text":"Inhibition of contractions"},{"id":"b","text":"Relaxation of smooth muscle"},{"id":"c","text":"Stimulation of contractions"},{"id":"d","text":"No effect on uterine muscle"}],"answerId":"c","explanation":"Oxytocin stimulates uterine smooth muscle contraction, which is essential for labor progression.","kind":"integration","linkedModuleIds":["hen1-oxytocin-reflexes"],"origin":"ai"}],"hypothyroidism-goiter":[{"id":"hypothyroidism-goiter~ai-0","moduleId":"hypothyroidism-goiter","stem":"What is the most common cause of hypothyroidism worldwide?","options":[{"id":"a","text":"Iodine deficiency"},{"id":"b","text":"Hashimoto thyroiditis"},{"id":"c","text":"Thyroiditis"},{"id":"d","text":"Pituitary adenoma"}],"answerId":"b","explanation":"Hashimoto thyroiditis is the most common cause of hypothyroidism overall, especially in developed countries.","kind":"recall","origin":"ai"},{"id":"hypothyroidism-goiter~ai-1","moduleId":"hypothyroidism-goiter","stem":"Which of the following symptoms is most characteristic of myxedema in adults?","options":[{"id":"a","text":"Heat intolerance"},{"id":"b","text":"Weight loss"},{"id":"c","text":"Cold intolerance"},{"id":"d","text":"Increased heart rate"}],"answerId":"c","explanation":"Cold intolerance is a classic symptom of myxedema due to decreased metabolic activity.","kind":"recall","origin":"ai"},{"id":"hypothyroidism-goiter~ai-2","moduleId":"hypothyroidism-goiter","stem":"What mechanism leads to the development of a simple goiter in iodine-deficient regions?","options":[{"id":"a","text":"Increased T3 production"},{"id":"b","text":"Decreased TSH levels"},{"id":"c","text":"Increased TSH levels"},{"id":"d","text":"Decreased T4 levels"}],"answerId":"c","explanation":"In iodine deficiency, low thyroid hormone levels lead to increased TSH, causing compensatory goiter.","kind":"mechanism","origin":"ai"},{"id":"hypothyroidism-goiter~ai-3","moduleId":"hypothyroidism-goiter","stem":"A patient presents with a diffusely enlarged thyroid gland but normal thyroid hormone levels. What is the most likely diagnosis?","options":[{"id":"a","text":"Hashimoto thyroiditis"},{"id":"b","text":"Simple goiter"},{"id":"c","text":"Multinodular goiter"},{"id":"d","text":"Thyroid carcinoma"}],"answerId":"b","explanation":"A diffusely enlarged thyroid with normal hormone levels suggests a simple (colloid) goiter.","kind":"clinical","origin":"ai"},{"id":"hypothyroidism-goiter~ai-4","moduleId":"hypothyroidism-goiter","stem":"Which of the following statements about simple goiter is true?","options":[{"id":"a","text":"It always indicates hypothyroidism."},{"id":"b","text":"It is associated with high T4 levels."},{"id":"c","text":"Most patients are euthyroid."},{"id":"d","text":"It is always nodular."}],"answerId":"c","explanation":"Most simple goiters are euthyroid due to compensatory mechanisms despite enlargement.","kind":"trap","origin":"ai"},{"id":"hypothyroidism-goiter~ai-5","moduleId":"hypothyroidism-goiter","stem":"How does the mechanism of hyperplasia in a simple goiter differ from that in Hashimoto thyroiditis?","options":[{"id":"a","text":"Both are due to increased TSH"},{"id":"b","text":"Both lead to hypothyroidism"},{"id":"c","text":"Only Hashimoto involves autoimmunity"},{"id":"d","text":"Only simple goiter is reversible"}],"answerId":"a","explanation":"Both conditions involve increased TSH leading to hyperplasia, but Hashimoto also involves autoimmunity.","kind":"integration","linkedModuleIds":["thyroiditis"],"origin":"ai"},{"id":"hypothyroidism-goiter~ai-6","moduleId":"hypothyroidism-goiter","stem":"Which cellular adaptation primarily drives the enlargement of the thyroid gland in a simple goiter?","options":[{"id":"a","text":"Hypertrophy"},{"id":"b","text":"Hyperplasia"},{"id":"c","text":"Atrophy"},{"id":"d","text":"Metaplasia"}],"answerId":"b","explanation":"Hyperplasia of follicular cells in response to increased TSH leads to the enlargement of the thyroid gland in a simple goiter.","kind":"integration","linkedModuleIds":["cellular-adaptations-growth"],"origin":"ai"}],"hyperthyroidism-graves":[{"id":"hyperthyroidism-graves~ai-0","moduleId":"hyperthyroidism-graves","stem":"What is the most common cause of endogenous hyperthyroidism?","options":[{"id":"a","text":"Toxic adenoma"},{"id":"b","text":"Thyroiditis"},{"id":"c","text":"Graves disease"},{"id":"d","text":"Exogenous hormone intake"}],"answerId":"c","explanation":"Graves disease is the most common cause of endogenous hyperthyroidism, characterized by autoantibodies against the TSH receptor.","kind":"recall","origin":"ai"},{"id":"hyperthyroidism-graves~ai-1","moduleId":"hyperthyroidism-graves","stem":"Which of the following findings is characteristic of Graves disease?","options":[{"id":"a","text":"Lid lag"},{"id":"b","text":"Cold intolerance"},{"id":"c","text":"Weight gain"},{"id":"d","text":"Bradycardia"}],"answerId":"a","explanation":"Lid lag is a common sign associated with hyperthyroidism, particularly in Graves disease due to sympathetic overstimulation.","kind":"recall","origin":"ai"},{"id":"hyperthyroidism-graves~ai-2","moduleId":"hyperthyroidism-graves","stem":"What is the mechanism of action of TSH-receptor antibodies in Graves disease?","options":[{"id":"a","text":"Inhibition of TSH secretion"},{"id":"b","text":"Stimulation of hormone synthesis"},{"id":"c","text":"Destruction of thyroid tissue"},{"id":"d","text":"Inhibition of thyroid hormone release"}],"answerId":"b","explanation":"TSH-receptor antibodies stimulate hormone synthesis, leading to hyperthyroidism in Graves disease.","kind":"mechanism","origin":"ai"},{"id":"hyperthyroidism-graves~ai-3","moduleId":"hyperthyroidism-graves","stem":"A patient presents with hyperthyroidism and a low radioactive iodine uptake. What is the most likely diagnosis?","options":[{"id":"a","text":"Graves disease"},{"id":"b","text":"Toxic adenoma"},{"id":"c","text":"Thyroiditis"},{"id":"d","text":"Exogenous hormone intake"}],"answerId":"c","explanation":"Low radioactive iodine uptake indicates thyroiditis or exogenous hormone intake, as opposed to Graves disease or toxic adenoma which have high uptake.","kind":"trap","origin":"ai"},{"id":"hyperthyroidism-graves~ai-4","moduleId":"hyperthyroidism-graves","stem":"Which of the following is NOT part of the Graves triad?","options":[{"id":"a","text":"Hyperthyroidism with diffuse goiter"},{"id":"b","text":"Exophthalmos"},{"id":"c","text":"Pretibial myxedema"},{"id":"d","text":"Weight gain"}],"answerId":"d","explanation":"Weight gain is not part of the Graves triad; patients typically experience weight loss despite increased appetite.","kind":"trap","origin":"ai"},{"id":"hyperthyroidism-graves~ai-5","moduleId":"hyperthyroidism-graves","stem":"How does Graves disease relate to autoimmune diseases?","options":[{"id":"a","text":"It is a systemic autoimmune disease"},{"id":"b","text":"It involves TSH-receptor antibodies"},{"id":"c","text":"It is unrelated to autoimmune mechanisms"},{"id":"d","text":"It causes systemic symptoms only"}],"answerId":"b","explanation":"Graves disease involves autoantibodies against the TSH receptor, classifying it as an organ-specific autoimmune disease.","kind":"integration","linkedModuleIds":["autoimmune-disease-examples"],"origin":"ai"},{"id":"hyperthyroidism-graves~ai-6","moduleId":"hyperthyroidism-graves","stem":"In a patient with hypothyroidism, which finding would help differentiate it from Graves disease?","options":[{"id":"a","text":"Increased radioactive iodine uptake"},{"id":"b","text":"Low TSH levels"},{"id":"c","text":"Weight loss"},{"id":"d","text":"Goiter presence"}],"answerId":"a","explanation":"Increased radioactive iodine uptake is characteristic of hyperthyroid states like Graves disease, while hypothyroidism typically shows low uptake.","kind":"integration","linkedModuleIds":["hypothyroidism-goiter"],"origin":"ai"}],"type1-diabetes-pathogenesis":[{"id":"type1-diabetes-pathogenesis~ai-0","moduleId":"type1-diabetes-pathogenesis","stem":"What is the primary mechanism of type 1 diabetes mellitus (T1DM)?","options":[{"id":"a","text":"Insulin resistance"},{"id":"b","text":"Autoimmune destruction of beta cells"},{"id":"c","text":"Increased insulin production"},{"id":"d","text":"Impaired hepatic glucose output"}],"answerId":"b","explanation":"T1DM is characterized by autoimmune destruction of pancreatic beta cells leading to absolute insulin deficiency.","kind":"mechanism","origin":"ai"},{"id":"type1-diabetes-pathogenesis~ai-1","moduleId":"type1-diabetes-pathogenesis","stem":"Which of the following is a classic symptom of type 1 diabetes?","options":[{"id":"a","text":"Weight gain"},{"id":"b","text":"Polyuria"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Fatigue"}],"answerId":"b","explanation":"Polyuria is a classic symptom due to glucosuria and osmotic diuresis in T1DM.","kind":"recall","origin":"ai"},{"id":"type1-diabetes-pathogenesis~ai-2","moduleId":"type1-diabetes-pathogenesis","stem":"In which stage of type 1 diabetes is a patient likely to have multiple autoantibodies but normal glucose levels?","options":[{"id":"a","text":"Stage 1"},{"id":"b","text":"Stage 2"},{"id":"c","text":"Stage 3"},{"id":"d","text":"Stage 4"}],"answerId":"a","explanation":"Stage 1 T1DM is defined by the presence of multiple autoantibodies with normal glucose levels.","kind":"trap","origin":"ai"},{"id":"type1-diabetes-pathogenesis~ai-3","moduleId":"type1-diabetes-pathogenesis","stem":"What laboratory finding is indicative of autoimmune beta-cell injury in T1DM?","options":[{"id":"a","text":"Increased C-peptide"},{"id":"b","text":"Positive GAD65 antibody"},{"id":"c","text":"Elevated insulin levels"},{"id":"d","text":"Low blood glucose"}],"answerId":"b","explanation":"Positive GAD65 antibody is a marker of autoimmune islet injury in T1DM.","kind":"recall","origin":"ai"},{"id":"type1-diabetes-pathogenesis~ai-4","moduleId":"type1-diabetes-pathogenesis","stem":"What is the consequence of absolute insulin deficiency in T1DM?","options":[{"id":"a","text":"Decreased hepatic glucose output"},{"id":"b","text":"Increased lipogenesis"},{"id":"c","text":"Increased ketogenesis"},{"id":"d","text":"Decreased glucagon secretion"}],"answerId":"c","explanation":"Absolute insulin deficiency leads to unopposed lipolysis and ketogenesis, resulting in ketonemia.","kind":"mechanism","origin":"ai"},{"id":"type1-diabetes-pathogenesis~ai-5","moduleId":"type1-diabetes-pathogenesis","stem":"How does the pathophysiology of type 1 diabetes differ from type 2 diabetes?","options":[{"id":"a","text":"T1DM is caused by insulin resistance"},{"id":"b","text":"T2DM has autoimmune components"},{"id":"c","text":"T1DM involves absolute insulin deficiency"},{"id":"d","text":"T2DM presents with weight loss"}],"answerId":"c","explanation":"T1DM is characterized by absolute insulin deficiency due to autoimmune destruction of beta cells, unlike T2DM which is primarily related to insulin resistance.","kind":"integration","linkedModuleIds":["insulin-resistance-type2-diabetes"],"origin":"ai"},{"id":"type1-diabetes-pathogenesis~ai-6","moduleId":"type1-diabetes-pathogenesis","stem":"Which complication is most likely to occur at the first presentation of type 1 diabetes?","options":[{"id":"a","text":"Hypoglycemia"},{"id":"b","text":"Diabetic ketoacidosis"},{"id":"c","text":"Chronic kidney disease"},{"id":"d","text":"Peripheral neuropathy"}],"answerId":"b","explanation":"Diabetic ketoacidosis (DKA) is a common and serious complication that can occur at the first presentation of T1DM due to absolute insulin deficiency.","kind":"clinical","origin":"ai"}],"hyperparathyroidism":[{"id":"hyperparathyroidism~ai-0","moduleId":"hyperparathyroidism","stem":"What is the most common cause of primary hyperparathyroidism?","options":[{"id":"a","text":"Parathyroid carcinoma"},{"id":"b","text":"Primary hyperplasia of all glands"},{"id":"c","text":"Sporadic solitary parathyroid adenoma"},{"id":"d","text":"Familial multiple endocrine neoplasia (MEN1)"}],"answerId":"c","explanation":"The most common cause of primary hyperparathyroidism is a sporadic solitary parathyroid adenoma, accounting for 85-95% of cases.","kind":"recall","origin":"ai"},{"id":"hyperparathyroidism~ai-1","moduleId":"hyperparathyroidism","stem":"Which clinical finding is characteristic of primary hyperparathyroidism?","options":[{"id":"a","text":"Low PTH with hypercalcemia"},{"id":"b","text":"Kidney stones and bone pain"},{"id":"c","text":"Hypocalcemia and hyperphosphatemia"},{"id":"d","text":"Increased calcitonin levels"}],"answerId":"b","explanation":"Primary hyperparathyroidism is characterized by hypercalcemia, high PTH, kidney stones, and bone pain.","kind":"recall","origin":"ai"},{"id":"hyperparathyroidism~ai-2","moduleId":"hyperparathyroidism","stem":"What mechanism leads to hypercalcemia in primary hyperparathyroidism?","options":[{"id":"a","text":"Increased renal calcium reabsorption"},{"id":"b","text":"Increased bone resorption due to PTH"},{"id":"c","text":"Increased intestinal absorption of calcium"},{"id":"d","text":"Decreased calcitonin secretion"}],"answerId":"b","explanation":"Excess PTH leads to increased bone resorption, which contributes to hypercalcemia.","kind":"mechanism","origin":"ai"},{"id":"hyperparathyroidism~ai-3","moduleId":"hyperparathyroidism","stem":"Which imaging finding is associated with osteitis fibrosa cystica?","options":[{"id":"a","text":"Osteoporosis"},{"id":"b","text":"Brown tumors"},{"id":"c","text":"Nephrocalcinosis"},{"id":"d","text":"Metastatic calcification"}],"answerId":"b","explanation":"Brown tumors are indicative of osteitis fibrosa cystica, a condition resulting from PTH-driven bone resorption.","kind":"recall","origin":"ai"},{"id":"hyperparathyroidism~ai-4","moduleId":"hyperparathyroidism","stem":"In a patient with hypercalcemia and low PTH, what is the likely cause?","options":[{"id":"a","text":"Primary hyperparathyroidism"},{"id":"b","text":"Secondary hyperparathyroidism"},{"id":"c","text":"PTHrP-mediated hypercalcemia"},{"id":"d","text":"Vitamin D intoxication"}],"answerId":"c","explanation":"Low PTH in the presence of hypercalcemia suggests PTHrP-mediated hypercalcemia, often associated with malignancy.","kind":"trap","origin":"ai"},{"id":"hyperparathyroidism~ai-5","moduleId":"hyperparathyroidism","stem":"How does calcitonin function in the context of mineral homeostasis?","options":[{"id":"a","text":"Increases renal calcium reabsorption"},{"id":"b","text":"Inhibits osteoclast activity"},{"id":"c","text":"Stimulates intestinal calcium absorption"},{"id":"d","text":"Increases PTH secretion"}],"answerId":"b","explanation":"Calcitonin inhibits osteoclast activity, thereby reducing bone resorption and lowering blood calcium levels.","kind":"integration","linkedModuleIds":["hen1-calcitonin-mineral-integration"],"origin":"ai"},{"id":"hyperparathyroidism~ai-6","moduleId":"hyperparathyroidism","stem":"What is the relationship between hyperparathyroidism and hypoparathyroidism?","options":[{"id":"a","text":"Both cause hypercalcemia"},{"id":"b","text":"Both involve increased PTH secretion"},{"id":"c","text":"Hyperparathyroidism leads to hypoparathyroidism"},{"id":"d","text":"Hypoparathyroidism can result from parathyroid surgery"}],"answerId":"d","explanation":"Hypoparathyroidism can result from surgical removal of parathyroid glands, which may occur during treatment for hyperparathyroidism.","kind":"integration","linkedModuleIds":["hypoparathyroidism"],"origin":"ai"}],"diabetes-complications-overview":[{"id":"diabetes-complications-overview~ai-0","moduleId":"diabetes-complications-overview","stem":"What is the primary mechanism by which chronic hyperglycemia causes diabetic nephropathy?","options":[{"id":"a","text":"Increased glomerular filtration rate"},{"id":"b","text":"Direct tubular toxicity"},{"id":"c","text":"Microvascular injury"},{"id":"d","text":"Increased insulin resistance"}],"answerId":"c","explanation":"Chronic hyperglycemia leads to microvascular injury in the glomeruli, resulting in nephropathy.","kind":"mechanism","origin":"ai"},{"id":"diabetes-complications-overview~ai-1","moduleId":"diabetes-complications-overview","stem":"Which of the following is a classic finding in diabetic retinopathy?","options":[{"id":"a","text":"Cotton wool spots"},{"id":"b","text":"Exudative retinal detachment"},{"id":"c","text":"Retinal artery occlusion"},{"id":"d","text":"Choroidal neovascularization"}],"answerId":"a","explanation":"Cotton wool spots are indicative of retinal ischemia and are commonly associated with diabetic retinopathy.","kind":"recall","origin":"ai"},{"id":"diabetes-complications-overview~ai-2","moduleId":"diabetes-complications-overview","stem":"A patient with diabetes presents with a painless foot ulcer. What is the most likely underlying cause?","options":[{"id":"a","text":"Peripheral arterial disease"},{"id":"b","text":"Diabetic neuropathy"},{"id":"c","text":"Infection"},{"id":"d","text":"Poor glycemic control"}],"answerId":"b","explanation":"Diabetic neuropathy results in loss of protective sensation, leading to unnoticed trauma and ulceration.","kind":"clinical","origin":"ai"},{"id":"diabetes-complications-overview~ai-3","moduleId":"diabetes-complications-overview","stem":"Which of the following complications is primarily associated with Type 2 diabetes?","options":[{"id":"a","text":"Diabetic ketoacidosis"},{"id":"b","text":"Hyperglycemic hyperosmolar state"},{"id":"c","text":"Diabetic foot syndrome"},{"id":"d","text":"Hypoglycemia"}],"answerId":"b","explanation":"Hyperglycemic hyperosmolar state (HHS) is more commonly associated with Type 2 diabetes due to the presence of some insulin.","kind":"recall","origin":"ai"},{"id":"diabetes-complications-overview~ai-4","moduleId":"diabetes-complications-overview","stem":"Peripheral arterial disease in diabetes is classified as which type of complication?","options":[{"id":"a","text":"Microvascular"},{"id":"b","text":"Macrovascular"},{"id":"c","text":"Neuropathic"},{"id":"d","text":"Endocrine"}],"answerId":"b","explanation":"Peripheral arterial disease is a macrovascular complication due to accelerated atherosclerosis.","kind":"trap","origin":"ai"},{"id":"diabetes-complications-overview~ai-5","moduleId":"diabetes-complications-overview","stem":"How does chronic hyperglycemia contribute to the development of diabetic neuropathy?","options":[{"id":"a","text":"Increased insulin secretion"},{"id":"b","text":"Oxidative stress and inflammation"},{"id":"c","text":"Decreased blood flow"},{"id":"d","text":"Increased sodium retention"}],"answerId":"b","explanation":"Chronic hyperglycemia leads to oxidative stress and inflammation, which damage peripheral nerves.","kind":"mechanism","origin":"ai"},{"id":"diabetes-complications-overview~ai-6","moduleId":"diabetes-complications-overview","stem":"In patients with Type 1 diabetes, which acute complication is most likely to occur due to insulin deficiency?","options":[{"id":"a","text":"Hypoglycemia"},{"id":"b","text":"Diabetic ketoacidosis"},{"id":"c","text":"Hyperglycemic hyperosmolar state"},{"id":"d","text":"Diabetic foot ulcer"}],"answerId":"b","explanation":"Diabetic ketoacidosis is primarily associated with insulin deficiency in Type 1 diabetes.","kind":"integration","linkedModuleIds":["type1-diabetes-pathogenesis"],"origin":"ai"},{"id":"diabetes-complications-overview~ai-7","moduleId":"diabetes-complications-overview","stem":"Which mechanism is shared between Type 2 diabetes and its complications like nephropathy and retinopathy?","options":[{"id":"a","text":"Autoimmune destruction of beta cells"},{"id":"b","text":"Insulin resistance leading to hyperglycemia"},{"id":"c","text":"Increased glucagon secretion"},{"id":"d","text":"Impaired insulin clearance"}],"answerId":"b","explanation":"Insulin resistance leads to chronic hyperglycemia, which is a common pathway for complications in Type 2 diabetes.","kind":"integration","linkedModuleIds":["insulin-resistance-type2-diabetes"],"origin":"ai"}],"corticosteroid-antagonists":[{"id":"corticosteroid-antagonists~ai-0","moduleId":"corticosteroid-antagonists","stem":"What is the primary mechanism of action of metyrapone in the treatment of Cushing syndrome?","options":[{"id":"a","text":"Inhibits cortisol receptor"},{"id":"b","text":"Blocks 11-hydroxylase"},{"id":"c","text":"Inhibits aldosterone synthesis"},{"id":"d","text":"Stimulates ACTH release"}],"answerId":"b","explanation":"Metyrapone blocks the enzyme 11-hydroxylase, leading to decreased cortisol production.","kind":"mechanism","origin":"ai"},{"id":"corticosteroid-antagonists~ai-1","moduleId":"corticosteroid-antagonists","stem":"Which of the following is a common adverse effect of mifepristone?","options":[{"id":"a","text":"Hyperkalemia"},{"id":"b","text":"Vaginal bleeding"},{"id":"c","text":"Gynecomastia"},{"id":"d","text":"Dizziness"}],"answerId":"b","explanation":"Mifepristone can cause vaginal bleeding as a common adverse effect.","kind":"recall","origin":"ai"},{"id":"corticosteroid-antagonists~ai-2","moduleId":"corticosteroid-antagonists","stem":"A patient with Cushing syndrome is treated with spironolactone. What is a likely adverse effect?","options":[{"id":"a","text":"Hypokalemia"},{"id":"b","text":"Weight gain"},{"id":"c","text":"Gynecomastia"},{"id":"d","text":"Decreased libido"}],"answerId":"c","explanation":"Spironolactone can cause gynecomastia due to its antiandrogen effects.","kind":"trap","origin":"ai"},{"id":"corticosteroid-antagonists~ai-3","moduleId":"corticosteroid-antagonists","stem":"In a pregnant patient with Cushing syndrome, which medication is preferred for its safety profile?","options":[{"id":"a","text":"Ketoconazole"},{"id":"b","text":"Metyrapone"},{"id":"c","text":"Mifepristone"},{"id":"d","text":"Spironolactone"}],"answerId":"b","explanation":"Metyrapone is preferred in pregnancy due to its safety profile.","kind":"recall","origin":"ai"},{"id":"corticosteroid-antagonists~ai-4","moduleId":"corticosteroid-antagonists","stem":"What is the primary action of ketoconazole in the context of Cushing syndrome?","options":[{"id":"a","text":"Inhibits glucocorticoid receptor"},{"id":"b","text":"Inhibits cortisol synthesis"},{"id":"c","text":"Stimulates ACTH secretion"},{"id":"d","text":"Inhibits aldosterone synthesis"}],"answerId":"b","explanation":"Ketoconazole primarily inhibits cortisol synthesis by blocking steroidogenesis.","kind":"mechanism","origin":"ai"},{"id":"corticosteroid-antagonists~ai-5","moduleId":"corticosteroid-antagonists","stem":"How does spironolactone lead to hyperkalemia?","options":[{"id":"a","text":"Inhibits potassium reabsorption"},{"id":"b","text":"Blocks aldosterone action"},{"id":"c","text":"Increases renal potassium excretion"},{"id":"d","text":"Stimulates sodium retention"}],"answerId":"b","explanation":"Spironolactone blocks aldosterone, which normally promotes potassium excretion, leading to hyperkalemia.","kind":"mechanism","origin":"ai"},{"id":"corticosteroid-antagonists~ai-6","moduleId":"corticosteroid-antagonists","stem":"How does the action of mifepristone relate to cortisol's effects on metabolism?","options":[{"id":"a","text":"Increases insulin sensitivity"},{"id":"b","text":"Blocks glucocorticoid receptor"},{"id":"c","text":"Stimulates gluconeogenesis"},{"id":"d","text":"Enhances protein catabolism"}],"answerId":"b","explanation":"Mifepristone acts as a glucocorticoid receptor antagonist, counteracting cortisol's metabolic effects.","kind":"integration","linkedModuleIds":["hen1-cortisol-systemic-actions"],"origin":"ai"},{"id":"corticosteroid-antagonists~ai-7","moduleId":"corticosteroid-antagonists","stem":"What is the relationship between spironolactone and sex steroid receptors?","options":[{"id":"a","text":"It enhances estrogen effects"},{"id":"b","text":"It blocks androgen receptors"},{"id":"c","text":"It stimulates testosterone synthesis"},{"id":"d","text":"It has no effect on sex steroids"}],"answerId":"b","explanation":"Spironolactone has antiandrogen effects by blocking androgen receptors, leading to gynecomastia.","kind":"integration","linkedModuleIds":["hrp1-sex-steroid-synthesis-action"],"origin":"ai"}],"insulin-resistance-type2-diabetes":[{"id":"insulin-resistance-type2-diabetes~ai-0","moduleId":"insulin-resistance-type2-diabetes","stem":"What is the primary mechanism by which visceral adiposity contributes to insulin resistance?","options":[{"id":"a","text":"Increased insulin secretion"},{"id":"b","text":"Excess free fatty acids"},{"id":"c","text":"Decreased glucagon levels"},{"id":"d","text":"Increased muscle glucose uptake"}],"answerId":"b","explanation":"Excess free fatty acids from visceral fat impair insulin signaling in liver and muscle, leading to insulin resistance.","kind":"mechanism","origin":"ai"},{"id":"insulin-resistance-type2-diabetes~ai-1","moduleId":"insulin-resistance-type2-diabetes","stem":"Which of the following findings is most indicative of hyperinsulinemia in a patient with insulin resistance?","options":[{"id":"a","text":"Acanthosis nigricans"},{"id":"b","text":"Weight loss"},{"id":"c","text":"Increased thirst"},{"id":"d","text":"Polyuria"}],"answerId":"a","explanation":"Acanthosis nigricans is a skin manifestation associated with hyperinsulinemia, reflecting insulin resistance.","kind":"recall","origin":"ai"},{"id":"insulin-resistance-type2-diabetes~ai-2","moduleId":"insulin-resistance-type2-diabetes","stem":"Which statement accurately describes the natural history of type 2 diabetes mellitus?","options":[{"id":"a","text":"Hyperglycemia begins immediately with insulin resistance"},{"id":"b","text":"Beta cells initially compensate with hyperinsulinemia"},{"id":"c","text":"Insulin resistance is reversible at all stages"},{"id":"d","text":"Fasting hyperglycemia occurs before postprandial hyperglycemia"}],"answerId":"b","explanation":"Beta cells initially compensate with hyperinsulinemia; glucose levels rise only when this compensation becomes inadequate.","kind":"trap","origin":"ai"},{"id":"insulin-resistance-type2-diabetes~ai-3","moduleId":"insulin-resistance-type2-diabetes","stem":"What is the most common clinical finding in metabolic syndrome?","options":[{"id":"a","text":"Low HDL cholesterol"},{"id":"b","text":"Elevated fasting glucose"},{"id":"c","text":"Hypertension"},{"id":"d","text":"Increased waist circumference"}],"answerId":"d","explanation":"Increased waist circumference is a key component of metabolic syndrome and is strongly linked to insulin resistance.","kind":"recall","origin":"ai"},{"id":"insulin-resistance-type2-diabetes~ai-4","moduleId":"insulin-resistance-type2-diabetes","stem":"Which of the following best describes the 'ominous octet' in type 2 diabetes?","options":[{"id":"a","text":"Increased insulin sensitivity"},{"id":"b","text":"Decreased glucagon secretion"},{"id":"c","text":"Increased renal glucose reabsorption"},{"id":"d","text":"Decreased lipolysis"}],"answerId":"c","explanation":"The 'ominous octet' includes factors like increased renal glucose reabsorption that contribute to sustained hyperglycemia.","kind":"mechanism","origin":"ai"},{"id":"insulin-resistance-type2-diabetes~ai-5","moduleId":"insulin-resistance-type2-diabetes","stem":"How does the pathogenesis of type 2 diabetes differ from type 1 diabetes?","options":[{"id":"a","text":"Type 2 is primarily autoimmune"},{"id":"b","text":"Type 1 involves insulin resistance"},{"id":"c","text":"Type 2 involves beta-cell failure after insulin resistance"},{"id":"d","text":"Type 1 has a gradual onset"}],"answerId":"c","explanation":"Type 2 diabetes involves a progressive failure of beta cells following a long period of insulin resistance, unlike type 1 diabetes which is autoimmune.","kind":"integration","linkedModuleIds":["type1-diabetes-pathogenesis"],"origin":"ai"},{"id":"insulin-resistance-type2-diabetes~ai-6","moduleId":"insulin-resistance-type2-diabetes","stem":"What is a common metabolic consequence of MCAD deficiency that can be linked to type 2 diabetes?","options":[{"id":"a","text":"Increased ketone production"},{"id":"b","text":"Hypoglycemia during fasting"},{"id":"c","text":"Increased insulin sensitivity"},{"id":"d","text":"Decreased free fatty acid release"}],"answerId":"b","explanation":"MCAD deficiency leads to hypoketotic hypoglycemia during fasting, which can relate to metabolic dysregulation seen in type 2 diabetes.","kind":"integration","linkedModuleIds":["mcad-hypoketotic-hypoglycemia"],"origin":"ai"}],"thyroid-neoplasms":[{"id":"thyroid-neoplasms~ai-0","moduleId":"thyroid-neoplasms","stem":"What is the most common benign thyroid tumor?","options":[{"id":"a","text":"Follicular adenoma"},{"id":"b","text":"Papillary carcinoma"},{"id":"c","text":"Follicular carcinoma"},{"id":"d","text":"Medullary carcinoma"}],"answerId":"a","explanation":"Follicular adenoma is the most common benign thyroid tumor, often presenting as a solitary encapsulated nodule.","kind":"recall","origin":"ai"},{"id":"thyroid-neoplasms~ai-1","moduleId":"thyroid-neoplasms","stem":"Which histological feature is characteristic of papillary thyroid carcinoma?","options":[{"id":"a","text":"Capsular invasion"},{"id":"b","text":"Orphan-Annie nuclei"},{"id":"c","text":"Amyloid stroma"},{"id":"d","text":"Spindle cells"}],"answerId":"b","explanation":"Papillary thyroid carcinoma is characterized by Orphan-Annie nuclei, which are empty nuclei seen on fine needle aspiration.","kind":"recall","origin":"ai"},{"id":"thyroid-neoplasms~ai-2","moduleId":"thyroid-neoplasms","stem":"What is the mechanism of action for the mutations driving follicular adenoma?","options":[{"id":"a","text":"RET proto-oncogene activation"},{"id":"b","text":"TSH-receptor pathway mutations"},{"id":"c","text":"BRAF mutations"},{"id":"d","text":"TP53 mutations"}],"answerId":"b","explanation":"Follicular adenomas are often driven by mutations in the TSH-receptor pathway, specifically GNAS mutations.","kind":"mechanism","origin":"ai"},{"id":"thyroid-neoplasms~ai-3","moduleId":"thyroid-neoplasms","stem":"A 70-year-old patient presents with a rapidly enlarging neck mass. What is the most likely diagnosis?","options":[{"id":"a","text":"Follicular adenoma"},{"id":"b","text":"Papillary carcinoma"},{"id":"c","text":"Follicular carcinoma"},{"id":"d","text":"Anaplastic carcinoma"}],"answerId":"d","explanation":"Anaplastic carcinoma is characterized by rapid growth and is most common in elderly patients.","kind":"clinical","origin":"ai"},{"id":"thyroid-neoplasms~ai-4","moduleId":"thyroid-neoplasms","stem":"Why can't fine needle aspiration (FNA) distinguish follicular carcinoma from follicular adenoma?","options":[{"id":"a","text":"FNA can assess capsular invasion"},{"id":"b","text":"FNA cannot assess vascular invasion"},{"id":"c","text":"FNA samples are too small"},{"id":"d","text":"FNA is not performed on thyroid nodules"}],"answerId":"b","explanation":"FNA cannot assess capsular or vascular invasion, which are necessary to diagnose follicular carcinoma.","kind":"trap","origin":"ai"},{"id":"thyroid-neoplasms~ai-5","moduleId":"thyroid-neoplasms","stem":"A patient with medullary thyroid carcinoma presents with elevated calcitonin levels. What histological feature would you expect to find?","options":[{"id":"a","text":"Psammoma bodies"},{"id":"b","text":"Orphan-Annie nuclei"},{"id":"c","text":"Amyloid stroma"},{"id":"d","text":"Giant cells"}],"answerId":"c","explanation":"Medullary thyroid carcinoma is characterized by nests of cells with amyloid stroma due to calcitonin secretion.","kind":"recall","origin":"ai"},{"id":"thyroid-neoplasms~ai-6","moduleId":"thyroid-neoplasms","stem":"How does thyroid neoplasm relate to adrenal development in embryology?","options":[{"id":"a","text":"Both arise from ectoderm"},{"id":"b","text":"Both involve the same hormonal pathways"},{"id":"c","text":"Both are derived from neural crest cells"},{"id":"d","text":"Both have similar genetic mutations"}],"answerId":"c","explanation":"Thyroid and adrenal tissues both derive from neural crest cells during embryonic development.","kind":"integration","linkedModuleIds":["hen1-adrenal-development"],"origin":"ai"},{"id":"thyroid-neoplasms~ai-7","moduleId":"thyroid-neoplasms","stem":"What common risk factor for thyroid neoplasms also affects adrenal development?","options":[{"id":"a","text":"Ionizing radiation"},{"id":"b","text":"Genetic mutations"},{"id":"c","text":"Autoimmune conditions"},{"id":"d","text":"Environmental toxins"}],"answerId":"a","explanation":"Ionizing radiation is a recognized risk factor for both thyroid neoplasms and can impact adrenal development.","kind":"integration","linkedModuleIds":["hen1-adrenal-development"],"origin":"ai"}],"hypoparathyroidism":[{"id":"hypoparathyroidism~ai-0","moduleId":"hypoparathyroidism","stem":"What is the most common cause of hypoparathyroidism?","options":[{"id":"a","text":"Autoimmune disease"},{"id":"b","text":"Genetic mutation"},{"id":"c","text":"Surgical removal of parathyroids"},{"id":"d","text":"Chronic kidney disease"}],"answerId":"c","explanation":"The most common cause of hypoparathyroidism is surgical, specifically accidental removal or damage to the parathyroid glands during thyroid surgery.","kind":"recall","origin":"ai"},{"id":"hypoparathyroidism~ai-1","moduleId":"hypoparathyroidism","stem":"Which of the following signs is indicative of neuromuscular irritability due to hypocalcemia?","options":[{"id":"a","text":"Brudzinski sign"},{"id":"b","text":"Chvostek sign"},{"id":"c","text":"Babinski sign"},{"id":"d","text":"Kernig sign"}],"answerId":"b","explanation":"Chvostek sign, which is facial twitching upon tapping the facial nerve, is a classic indicator of neuromuscular irritability due to hypocalcemia.","kind":"recall","origin":"ai"},{"id":"hypoparathyroidism~ai-2","moduleId":"hypoparathyroidism","stem":"In a patient with hypoparathyroidism, what is the primary mechanism leading to neuromuscular irritability?","options":[{"id":"a","text":"High calcium levels"},{"id":"b","text":"Low calcium levels"},{"id":"c","text":"High PTH levels"},{"id":"d","text":"Low PTH levels"}],"answerId":"b","explanation":"Low calcium levels due to deficient PTH lead to increased neuromuscular excitability.","kind":"mechanism","origin":"ai"},{"id":"hypoparathyroidism~ai-3","moduleId":"hypoparathyroidism","stem":"A patient presents with perioral numbness and carpopedal spasm after thyroid surgery. What is the most likely diagnosis?","options":[{"id":"a","text":"Hyperparathyroidism"},{"id":"b","text":"Hypoparathyroidism"},{"id":"c","text":"DiGeorge syndrome"},{"id":"d","text":"Autoimmune polyendocrine syndrome"}],"answerId":"b","explanation":"These symptoms are characteristic of hypoparathyroidism, particularly following thyroid surgery.","kind":"clinical","origin":"ai"},{"id":"hypoparathyroidism~ai-4","moduleId":"hypoparathyroidism","stem":"Which of the following ECG changes is associated with hypocalcemia?","options":[{"id":"a","text":"Shortened QT interval"},{"id":"b","text":"Prolonged QT interval"},{"id":"c","text":"ST elevation"},{"id":"d","text":"Atrial fibrillation"}],"answerId":"b","explanation":"Hypocalcemia is associated with a prolonged QT interval on ECG.","kind":"recall","origin":"ai"},{"id":"hypoparathyroidism~ai-5","moduleId":"hypoparathyroidism","stem":"How does chronic hypocalcemia affect dental health?","options":[{"id":"a","text":"Causes tooth decay"},{"id":"b","text":"Leads to enamel hypoplasia"},{"id":"c","text":"Increases gum disease"},{"id":"d","text":"Promotes tooth sensitivity"}],"answerId":"b","explanation":"Chronic hypocalcemia can lead to dental abnormalities such as enamel hypoplasia.","kind":"trap","origin":"ai"},{"id":"hypoparathyroidism~ai-6","moduleId":"hypoparathyroidism","stem":"How would you manage a patient with hypoparathyroidism who is experiencing seizures due to severe hypocalcemia?","options":[{"id":"a","text":"Increase dietary calcium"},{"id":"b","text":"Administer calcium gluconate"},{"id":"c","text":"Start bisphosphonates"},{"id":"d","text":"Prescribe vitamin D only"}],"answerId":"b","explanation":"In cases of severe hypocalcemia with seizures, immediate administration of calcium gluconate is necessary.","kind":"integration","linkedModuleIds":["hypoparathyroidism-treatment"],"origin":"ai"},{"id":"hypoparathyroidism~ai-7","moduleId":"hypoparathyroidism","stem":"A patient with hypoparathyroidism is at risk for which of the following complications?","options":[{"id":"a","text":"Increased bone density"},{"id":"b","text":"Hypocalcemic seizures"},{"id":"c","text":"Hypercalcemia"},{"id":"d","text":"Thyroid storm"}],"answerId":"b","explanation":"Patients with hypoparathyroidism are at risk for hypocalcemic seizures due to low calcium levels.","kind":"integration","linkedModuleIds":["hyperparathyroidism"],"origin":"ai"}],"corticosteroid-pharmacology":[{"id":"corticosteroid-pharmacology~ai-0","moduleId":"corticosteroid-pharmacology","stem":"What is the primary mechanism of action of glucocorticoids?","options":[{"id":"a","text":"Inhibition of cyclooxygenase"},{"id":"b","text":"Binding to intracellular glucocorticoid receptors"},{"id":"c","text":"Blocking phospholipase C"},{"id":"d","text":"Inhibition of leukotriene synthesis"}],"answerId":"b","explanation":"Glucocorticoids act by binding to intracellular receptors, leading to gene transcription changes that mediate their anti-inflammatory effects.","kind":"mechanism","origin":"ai"},{"id":"corticosteroid-pharmacology~ai-1","moduleId":"corticosteroid-pharmacology","stem":"Which of the following is a common adverse effect of long-term glucocorticoid therapy?","options":[{"id":"a","text":"Hypoglycemia"},{"id":"b","text":"Osteoporosis"},{"id":"c","text":"Bradycardia"},{"id":"d","text":"Hypotension"}],"answerId":"b","explanation":"Long-term glucocorticoid therapy can lead to osteoporosis due to increased bone resorption and decreased osteoblast activity.","kind":"recall","origin":"ai"},{"id":"corticosteroid-pharmacology~ai-2","moduleId":"corticosteroid-pharmacology","stem":"A patient on chronic glucocorticoid therapy presents with a moon face and easy bruising. What is the likely underlying mechanism?","options":[{"id":"a","text":"Increased insulin sensitivity"},{"id":"b","text":"Iatrogenic glucocorticoid excess"},{"id":"c","text":"Decreased cortisol production"},{"id":"d","text":"Increased ACTH levels"}],"answerId":"b","explanation":"These features are indicative of iatrogenic Cushing's syndrome due to excess glucocorticoids.","kind":"clinical","origin":"ai"},{"id":"corticosteroid-pharmacology~ai-3","moduleId":"corticosteroid-pharmacology","stem":"Which of the following statements about glucocorticoids is true?","options":[{"id":"a","text":"They only inhibit prostaglandin synthesis."},{"id":"b","text":"They suppress both prostaglandins and leukotrienes."},{"id":"c","text":"They act exclusively on the immune system."},{"id":"d","text":"They have no metabolic effects."}],"answerId":"b","explanation":"Glucocorticoids inhibit phospholipase A₂, blocking both prostaglandins and leukotrienes, leading to a broader anti-inflammatory effect.","kind":"trap","origin":"ai"},{"id":"corticosteroid-pharmacology~ai-4","moduleId":"corticosteroid-pharmacology","stem":"In a patient with Addison's disease, which medication is used for mineralocorticoid replacement?","options":[{"id":"a","text":"Hydrocortisone"},{"id":"b","text":"Prednisolone"},{"id":"c","text":"Fludrocortisone"},{"id":"d","text":"Dexamethasone"}],"answerId":"c","explanation":"Fludrocortisone is specifically used for mineralocorticoid replacement in Addison's disease.","kind":"recall","origin":"ai"},{"id":"corticosteroid-pharmacology~ai-5","moduleId":"corticosteroid-pharmacology","stem":"How do glucocorticoids contribute to hyperglycemia?","options":[{"id":"a","text":"Increased glucose uptake"},{"id":"b","text":"Decreased gluconeogenesis"},{"id":"c","text":"Increased gluconeogenesis and decreased glucose uptake"},{"id":"d","text":"Increased insulin secretion"}],"answerId":"c","explanation":"Glucocorticoids increase gluconeogenesis while decreasing glucose uptake, leading to hyperglycemia.","kind":"mechanism","origin":"ai"},{"id":"corticosteroid-pharmacology~ai-6","moduleId":"corticosteroid-pharmacology","stem":"What is the primary effect of glucocorticoids on bone health?","options":[{"id":"a","text":"Increased osteoblast activity"},{"id":"b","text":"Decreased osteoclast activity"},{"id":"c","text":"Increased bone resorption and osteoblast apoptosis"},{"id":"d","text":"No effect on bone health"}],"answerId":"c","explanation":"Glucocorticoids promote osteoblast apoptosis and increase bone resorption, leading to osteoporosis.","kind":"integration","linkedModuleIds":["hen1-cortisol-systemic-actions"],"origin":"ai"},{"id":"corticosteroid-pharmacology~ai-7","moduleId":"corticosteroid-pharmacology","stem":"Which of the following is a key difference between glucocorticoids and NSAIDs in their anti-inflammatory actions?","options":[{"id":"a","text":"Both inhibit phospholipase A₂"},{"id":"b","text":"Glucocorticoids act upstream while NSAIDs act downstream"},{"id":"c","text":"Both act on the same receptors"},{"id":"d","text":"NSAIDs have a broader effect than glucocorticoids"}],"answerId":"b","explanation":"Glucocorticoids inhibit phospholipase A₂, acting upstream in the inflammatory cascade, while NSAIDs inhibit cyclooxygenase, acting downstream.","kind":"integration","linkedModuleIds":["nsaid-acetaminophen-safety"],"origin":"ai"}],"thyroid-hormone-replacement":[{"id":"thyroid-hormone-replacement~ai-0","moduleId":"thyroid-hormone-replacement","stem":"What is the primary preparation used for thyroid hormone replacement therapy?","options":[{"id":"a","text":"Liothyronine (L-T3)"},{"id":"b","text":"Levothyroxine (L-T4)"},{"id":"c","text":"Desiccated thyroid"},{"id":"d","text":"Liotrix (T4:T3)"}],"answerId":"b","explanation":"Levothyroxine (L-T4) is the preferred choice due to its stability, cost-effectiveness, and once-daily dosing.","kind":"recall","origin":"ai"},{"id":"thyroid-hormone-replacement~ai-1","moduleId":"thyroid-hormone-replacement","stem":"What is the recommended timing for levothyroxine administration?","options":[{"id":"a","text":"With food"},{"id":"b","text":"Before breakfast"},{"id":"c","text":"At bedtime"},{"id":"d","text":"With calcium supplements"}],"answerId":"b","explanation":"Levothyroxine should be taken before food to optimize absorption.","kind":"recall","origin":"ai"},{"id":"thyroid-hormone-replacement~ai-2","moduleId":"thyroid-hormone-replacement","stem":"Which of the following can decrease the absorption of levothyroxine?","options":[{"id":"a","text":"Calcium supplements"},{"id":"b","text":"Folic acid"},{"id":"c","text":"Vitamin D"},{"id":"d","text":"Magnesium"}],"answerId":"a","explanation":"Calcium supplements can interfere with the absorption of levothyroxine.","kind":"mechanism","origin":"ai"},{"id":"thyroid-hormone-replacement~ai-3","moduleId":"thyroid-hormone-replacement","stem":"A 70-year-old woman develops palpitations after her levothyroxine dose was increased. What is the most likely cause?","options":[{"id":"a","text":"Iatrogenic hyperthyroidism"},{"id":"b","text":"Thyroid storm"},{"id":"c","text":"Anxiety disorder"},{"id":"d","text":"Atrial fibrillation unrelated to medication"}],"answerId":"a","explanation":"Excess thyroid hormone replacement can lead to iatrogenic hyperthyroidism, causing symptoms like palpitations.","kind":"clinical","origin":"ai"},{"id":"thyroid-hormone-replacement~ai-4","moduleId":"thyroid-hormone-replacement","stem":"A patient on levothyroxine reports persistent high TSH levels despite adherence. What should be considered?","options":[{"id":"a","text":"Increase the dose immediately"},{"id":"b","text":"Check for drug interactions"},{"id":"c","text":"Switch to liothyronine"},{"id":"d","text":"Reduce dietary iodine"}],"answerId":"b","explanation":"Drug interactions, such as food or antacids, may be reducing levothyroxine absorption, leading to high TSH levels.","kind":"trap","origin":"ai"},{"id":"thyroid-hormone-replacement~ai-5","moduleId":"thyroid-hormone-replacement","stem":"In a patient with osteoporosis, which thyroid hormone replacement strategy should be avoided?","options":[{"id":"a","text":"Levothyroxine at low doses"},{"id":"b","text":"Levothyroxine at high doses"},{"id":"c","text":"Liothyronine"},{"id":"d","text":"Desiccated thyroid"}],"answerId":"b","explanation":"High doses of levothyroxine can exacerbate bone loss and increase fracture risk in osteoporotic patients.","kind":"trap","origin":"ai"},{"id":"thyroid-hormone-replacement~ai-6","moduleId":"thyroid-hormone-replacement","stem":"How does the pharmacokinetics of levothyroxine affect dosing adjustments?","options":[{"id":"a","text":"Adjust after 1 week"},{"id":"b","text":"Adjust after 2 weeks"},{"id":"c","text":"Adjust after 6-8 weeks"},{"id":"d","text":"Adjust after 12 weeks"}],"answerId":"c","explanation":"Due to its long half-life, levothyroxine dosing adjustments should be made after 6-8 weeks to avoid unnecessary stacking.","kind":"integration","linkedModuleIds":["pharmacokinetics-adme"],"origin":"ai"},{"id":"thyroid-hormone-replacement~ai-7","moduleId":"thyroid-hormone-replacement","stem":"Which of the following best explains the mechanism of action of levothyroxine?","options":[{"id":"a","text":"Increases insulin sensitivity"},{"id":"b","text":"Stimulates catecholamine release"},{"id":"c","text":"Replaces T4 to achieve euthyroidism"},{"id":"d","text":"Inhibits thyroid hormone synthesis"}],"answerId":"c","explanation":"Levothyroxine acts by replacing T4 to stabilize thyroid hormone levels and achieve euthyroidism.","kind":"integration","linkedModuleIds":["hen1-peptide-catecholamine-hormones"],"origin":"ai"}],"thyroiditis":[{"id":"thyroiditis~ai-0","moduleId":"thyroiditis","stem":"What is the most common cause of hypothyroidism in iodine-sufficient areas?","options":[{"id":"a","text":"Subacute granulomatous thyroiditis"},{"id":"b","text":"Hashimoto thyroiditis"},{"id":"c","text":"Riedel thyroiditis"},{"id":"d","text":"Subacute lymphocytic thyroiditis"}],"answerId":"b","explanation":"Hashimoto thyroiditis is the most prevalent cause of hypothyroidism in iodine-sufficient regions, particularly in middle-aged women.","kind":"recall","origin":"ai"},{"id":"thyroiditis~ai-1","moduleId":"thyroiditis","stem":"Which histological finding is characteristic of Hashimoto thyroiditis?","options":[{"id":"a","text":"Non-caseating granulomas"},{"id":"b","text":"Germinal centers and Hürthle cells"},{"id":"c","text":"Multinucleated giant cells"},{"id":"d","text":"Fibrosis with lymphocytic infiltrate"}],"answerId":"b","explanation":"Hashimoto thyroiditis is characterized by the presence of germinal centers and Hürthle cells on histology.","kind":"recall","origin":"ai"},{"id":"thyroiditis~ai-2","moduleId":"thyroiditis","stem":"A patient presents with a painful thyroid gland following a recent viral upper respiratory infection. What is the likely diagnosis?","options":[{"id":"a","text":"Hashimoto thyroiditis"},{"id":"b","text":"Subacute granulomatous thyroiditis"},{"id":"c","text":"Riedel thyroiditis"},{"id":"d","text":"Subacute lymphocytic thyroiditis"}],"answerId":"b","explanation":"Subacute granulomatous thyroiditis, also known as De Quervain thyroiditis, is characterized by pain following a viral infection.","kind":"clinical","origin":"ai"},{"id":"thyroiditis~ai-3","moduleId":"thyroiditis","stem":"Which type of thyroiditis is associated with a hard, fixed thyroid mass that may mimic carcinoma?","options":[{"id":"a","text":"Hashimoto thyroiditis"},{"id":"b","text":"Subacute lymphocytic thyroiditis"},{"id":"c","text":"Subacute granulomatous thyroiditis"},{"id":"d","text":"Riedel thyroiditis"}],"answerId":"d","explanation":"Riedel thyroiditis presents as a hard, fixed mass due to extensive fibrosis, which can be mistaken for thyroid cancer.","kind":"recall","origin":"ai"},{"id":"thyroiditis~ai-4","moduleId":"thyroiditis","stem":"What distinguishes subacute granulomatous thyroiditis from Hashimoto thyroiditis?","options":[{"id":"a","text":"Presence of anti-TPO antibodies"},{"id":"b","text":"Painful thyroid gland"},{"id":"c","text":"Germinal centers on histology"},{"id":"d","text":"Age of onset"}],"answerId":"b","explanation":"Subacute granulomatous thyroiditis is characterized by a painful thyroid gland, unlike the painless Hashimoto thyroiditis.","kind":"trap","origin":"ai"},{"id":"thyroiditis~ai-5","moduleId":"thyroiditis","stem":"A patient with Hashimoto thyroiditis is at increased risk for which of the following?","options":[{"id":"a","text":"Thyroid B-cell lymphoma"},{"id":"b","text":"Thyroid adenoma"},{"id":"c","text":"Graves' disease"},{"id":"d","text":"Thyroid follicular carcinoma"}],"answerId":"a","explanation":"Patients with Hashimoto thyroiditis have an increased risk of developing thyroid B-cell lymphoma.","kind":"recall","origin":"ai"},{"id":"thyroiditis~ai-6","moduleId":"thyroiditis","stem":"How does Hashimoto thyroiditis relate to the development of hypothyroidism?","options":[{"id":"a","text":"Increased TSH secretion"},{"id":"b","text":"Destruction of thyroid follicles"},{"id":"c","text":"Increased thyroid hormone production"},{"id":"d","text":"Autoimmune stimulation of TSH receptors"}],"answerId":"b","explanation":"Hashimoto thyroiditis leads to the destruction of thyroid follicles, resulting in decreased thyroid hormone production and subsequent hypothyroidism.","kind":"mechanism","origin":"ai"},{"id":"thyroiditis~ai-7","moduleId":"thyroiditis","stem":"How might thyroiditis affect the forearm extensor compartment function?","options":[{"id":"a","text":"Increased grip strength"},{"id":"b","text":"Decreased wrist extension"},{"id":"c","text":"Increased forearm pronation"},{"id":"d","text":"Decreased finger flexion"}],"answerId":"b","explanation":"Thyroid dysfunction can lead to muscle weakness, including decreased wrist extension due to forearm extensor compartment involvement.","kind":"integration","linkedModuleIds":["forearm-extensor-compartment-snuffbox"],"origin":"ai"},{"id":"thyroiditis~ai-8","moduleId":"thyroiditis","stem":"What is a common clinical finding in both Hashimoto thyroiditis and hypothyroidism?","options":[{"id":"a","text":"Painless goiter"},{"id":"b","text":"Hyperreflexia"},{"id":"c","text":"Tachycardia"},{"id":"d","text":"Weight loss"}],"answerId":"a","explanation":"A painless goiter is a common clinical finding in both Hashimoto thyroiditis and hypothyroidism.","kind":"integration","linkedModuleIds":["hypothyroidism-goiter"],"origin":"ai"}],"thyroid-storm-recognition-management":[{"id":"thyroid-storm-recognition-management~ai-0","moduleId":"thyroid-storm-recognition-management","stem":"What is the most common trigger of thyroid storm?","options":[{"id":"a","text":"Surgery"},{"id":"b","text":"Infection"},{"id":"c","text":"Radioactive iodine"},{"id":"d","text":"Trauma"}],"answerId":"b","explanation":"Infection is the most common precipitant of thyroid storm.","kind":"recall","origin":"ai"},{"id":"thyroid-storm-recognition-management~ai-1","moduleId":"thyroid-storm-recognition-management","stem":"Which score is used to assess the likelihood of thyroid storm?","options":[{"id":"a","text":"APACHE II"},{"id":"b","text":"Burch-Wartofsky score"},{"id":"c","text":"Glasgow Coma Scale"},{"id":"d","text":"SOFA score"}],"answerId":"b","explanation":"The Burch-Wartofsky score is specifically designed to evaluate the likelihood of thyroid storm.","kind":"recall","origin":"ai"},{"id":"thyroid-storm-recognition-management~ai-2","moduleId":"thyroid-storm-recognition-management","stem":"In thyroid storm, which clinical finding is most indicative of multiorgan decompensation?","options":[{"id":"a","text":"Tachycardia"},{"id":"b","text":"Fever"},{"id":"c","text":"Agitation"},{"id":"d","text":"Heart failure"}],"answerId":"d","explanation":"Heart failure is a key sign of multiorgan decompensation in thyroid storm.","kind":"recall","origin":"ai"},{"id":"thyroid-storm-recognition-management~ai-3","moduleId":"thyroid-storm-recognition-management","stem":"What is the first-line treatment for thyroid storm?","options":[{"id":"a","text":"Iodide"},{"id":"b","text":"Thioamide"},{"id":"c","text":"Beta-blocker"},{"id":"d","text":"Glucocorticoid"}],"answerId":"b","explanation":"Thioamide is the first-line treatment to block thyroid hormone synthesis in thyroid storm.","kind":"mechanism","origin":"ai"},{"id":"thyroid-storm-recognition-management~ai-4","moduleId":"thyroid-storm-recognition-management","stem":"Which of the following is a trap in managing thyroid storm?","options":[{"id":"a","text":"Administer iodide before thioamide"},{"id":"b","text":"Treat based on T4 levels"},{"id":"c","text":"Wait for clinical stabilization"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"All listed options are traps; iodide must follow thioamide, and treatment should be based on clinical presentation, not T4 levels.","kind":"trap","origin":"ai"},{"id":"thyroid-storm-recognition-management~ai-5","moduleId":"thyroid-storm-recognition-management","stem":"A patient presents with hyperglycemia and altered mental status. Which condition could precipitate both thyroid storm and DKA?","options":[{"id":"a","text":"Hypoglycemia"},{"id":"b","text":"Infection"},{"id":"c","text":"Heart failure"},{"id":"d","text":"Trauma"}],"answerId":"b","explanation":"Infection can trigger both thyroid storm and DKA, linking the two conditions.","kind":"integration","linkedModuleIds":["dka-hhs-recognition"],"origin":"ai"},{"id":"thyroid-storm-recognition-management~ai-6","moduleId":"thyroid-storm-recognition-management","stem":"In the context of thyroid storm, which treatment would also be beneficial in managing DKA?","options":[{"id":"a","text":"Thioamide"},{"id":"b","text":"Insulin"},{"id":"c","text":"Iodide"},{"id":"d","text":"Beta-blocker"}],"answerId":"b","explanation":"Insulin is crucial in managing DKA and can also help in controlling hyperglycemia associated with thyroid storm.","kind":"integration","linkedModuleIds":["dka-hhs-management"],"origin":"ai"}],"glucose-specimens-monitoring":[{"id":"glucose-specimens-monitoring~ai-0","moduleId":"glucose-specimens-monitoring","stem":"What is the primary reason for measuring fasting plasma glucose after an 8-12 hour fast?","options":[{"id":"a","text":"To ensure accurate measurement of glucose levels"},{"id":"b","text":"To prevent interference from dietary carbohydrates"},{"id":"c","text":"To assess insulin sensitivity"},{"id":"d","text":"To evaluate renal function"}],"answerId":"a","explanation":"An 8-12 hour fast minimizes the influence of recent food intake, allowing for a more accurate measurement of baseline glucose levels.","kind":"recall","origin":"ai"},{"id":"glucose-specimens-monitoring~ai-1","moduleId":"glucose-specimens-monitoring","stem":"Which method is considered the reference enzymatic method for glucose measurement?","options":[{"id":"a","text":"Glucose oxidase-peroxidase"},{"id":"b","text":"Hexokinase"},{"id":"c","text":"Fructose dehydrogenase"},{"id":"d","text":"Lactate dehydrogenase"}],"answerId":"b","explanation":"The hexokinase method is the reference standard for measuring plasma glucose due to its accuracy and reliability.","kind":"recall","origin":"ai"},{"id":"glucose-specimens-monitoring~ai-2","moduleId":"glucose-specimens-monitoring","stem":"What is the expected effect of delayed separation of blood specimens on glucose measurement?","options":[{"id":"a","text":"Increase in glucose levels"},{"id":"b","text":"Decrease in glucose levels"},{"id":"c","text":"No effect on glucose levels"},{"id":"d","text":"Inconsistent results"}],"answerId":"b","explanation":"Delayed separation leads to ongoing glycolysis, which decreases the measured glucose levels by about 5-10 mg/dL per hour.","kind":"mechanism","origin":"ai"},{"id":"glucose-specimens-monitoring~ai-3","moduleId":"glucose-specimens-monitoring","stem":"A patient presents with hypoglycemic symptoms but has a normal reading on their continuous glucose monitor (CGM). What is the most likely explanation?","options":[{"id":"a","text":"CGM malfunction"},{"id":"b","text":"Rapid changes in blood glucose"},{"id":"c","text":"Insufficient calibration of the CGM"},{"id":"d","text":"Dehydration affecting sensor accuracy"}],"answerId":"b","explanation":"The interstitial glucose measured by CGM lags behind blood glucose levels, especially during rapid changes.","kind":"clinical","origin":"ai"},{"id":"glucose-specimens-monitoring~ai-4","moduleId":"glucose-specimens-monitoring","stem":"Why is a home glucose meter not suitable for diagnosing diabetes?","options":[{"id":"a","text":"It requires a fasting state"},{"id":"b","text":"It can only measure serum glucose"},{"id":"c","text":"Point-of-care meter error is too variable"},{"id":"d","text":"It is not calibrated for accuracy"}],"answerId":"c","explanation":"Home glucose meters are designed for monitoring and have variable accuracy, making them unsuitable for formal diagnosis.","kind":"trap","origin":"ai"},{"id":"glucose-specimens-monitoring~ai-5","moduleId":"glucose-specimens-monitoring","stem":"How does glucose transport relate to glycolysis in the context of glucose monitoring?","options":[{"id":"a","text":"Glucose transport enhances glycolysis"},{"id":"b","text":"Glycolysis occurs independently of glucose transport"},{"id":"c","text":"Glucose transport is inhibited during glycolysis"},{"id":"d","text":"Glycolysis decreases glucose transport efficiency"}],"answerId":"a","explanation":"Effective glucose transport into cells is essential for glycolysis to occur, as glucose must enter the cell to be metabolized.","kind":"integration","linkedModuleIds":["glucose-transport-glycolysis"],"origin":"ai"},{"id":"glucose-specimens-monitoring~ai-6","moduleId":"glucose-specimens-monitoring","stem":"What is the relationship between HbA1c testing and glucose monitoring?","options":[{"id":"a","text":"HbA1c reflects short-term glucose levels"},{"id":"b","text":"HbA1c is a direct measure of current glucose"},{"id":"c","text":"HbA1c provides an average of glucose over time"},{"id":"d","text":"HbA1c is used for acute glucose management"}],"answerId":"c","explanation":"HbA1c testing provides an average of blood glucose levels over the past 2-3 months, helping to assess long-term glucose control.","kind":"integration","linkedModuleIds":["hba1c-fructosamine"],"origin":"ai"}],"secondary-hyperparathyroidism-ckd":[{"id":"secondary-hyperparathyroidism-ckd~ai-0","moduleId":"secondary-hyperparathyroidism-ckd","stem":"What is the primary cause of secondary hyperparathyroidism in chronic kidney disease (CKD)?","options":[{"id":"a","text":"Vitamin D deficiency"},{"id":"b","text":"Hypercalcemia"},{"id":"c","text":"Hypophosphatemia"},{"id":"d","text":"Primary hyperparathyroidism"}],"answerId":"a","explanation":"Vitamin D deficiency leads to decreased intestinal calcium absorption, contributing to secondary hyperparathyroidism in CKD.","kind":"recall","origin":"ai"},{"id":"secondary-hyperparathyroidism-ckd~ai-1","moduleId":"secondary-hyperparathyroidism-ckd","stem":"In CKD, what is the typical laboratory finding associated with secondary hyperparathyroidism?","options":[{"id":"a","text":"High PTH, high calcium, low phosphate"},{"id":"b","text":"High PTH, low calcium, high phosphate"},{"id":"c","text":"Low PTH, low calcium, high phosphate"},{"id":"d","text":"Normal PTH, high calcium, normal phosphate"}],"answerId":"b","explanation":"The typical pattern in CKD is high PTH with low or normal calcium and high or normal phosphate.","kind":"recall","origin":"ai"},{"id":"secondary-hyperparathyroidism-ckd~ai-2","moduleId":"secondary-hyperparathyroidism-ckd","stem":"What is the mechanism by which calcitriol suppresses PTH secretion?","options":[{"id":"a","text":"Increases renal phosphate excretion"},{"id":"b","text":"Increases intestinal calcium absorption"},{"id":"c","text":"Directly inhibits parathyroid gland function"},{"id":"d","text":"Stimulates vitamin D receptor in bone"}],"answerId":"b","explanation":"Calcitriol increases intestinal calcium absorption, which helps to suppress PTH secretion.","kind":"mechanism","origin":"ai"},{"id":"secondary-hyperparathyroidism-ckd~ai-3","moduleId":"secondary-hyperparathyroidism-ckd","stem":"Which treatment is the first-line approach to manage secondary hyperparathyroidism in CKD?","options":[{"id":"a","text":"Calcitriol supplementation"},{"id":"b","text":"Phosphate restriction"},{"id":"c","text":"Cinacalcet administration"},{"id":"d","text":"Surgical parathyroidectomy"}],"answerId":"b","explanation":"Phosphate restriction is essential to remove the stimulus for PTH secretion in secondary hyperparathyroidism.","kind":"recall","origin":"ai"},{"id":"secondary-hyperparathyroidism-ckd~ai-4","moduleId":"secondary-hyperparathyroidism-ckd","stem":"A patient with CKD presents with high PTH, normal calcium, and high phosphate. Which condition does this most likely indicate?","options":[{"id":"a","text":"Primary hyperparathyroidism"},{"id":"b","text":"Secondary hyperparathyroidism"},{"id":"c","text":"Hypoparathyroidism"},{"id":"d","text":"Vitamin D intoxication"}],"answerId":"b","explanation":"The combination of high PTH with normal calcium and high phosphate is characteristic of secondary hyperparathyroidism due to CKD.","kind":"clinical","origin":"ai"},{"id":"secondary-hyperparathyroidism-ckd~ai-5","moduleId":"secondary-hyperparathyroidism-ckd","stem":"How does secondary hyperparathyroidism in CKD relate to renal endocrine functions?","options":[{"id":"a","text":"It decreases renal calcitriol production"},{"id":"b","text":"It increases renal phosphate excretion"},{"id":"c","text":"It enhances renal calcium absorption"},{"id":"d","text":"It reduces renal blood flow"}],"answerId":"a","explanation":"In CKD, secondary hyperparathyroidism is linked to decreased renal calcitriol production, contributing to mineral imbalances.","kind":"integration","linkedModuleIds":["renal-endocrine-functions"],"origin":"ai"},{"id":"secondary-hyperparathyroidism-ckd~ai-6","moduleId":"secondary-hyperparathyroidism-ckd","stem":"What distinguishes secondary hyperparathyroidism from primary hyperparathyroidism in terms of calcium levels?","options":[{"id":"a","text":"Both have high calcium"},{"id":"b","text":"Secondary has low calcium, primary has high calcium"},{"id":"c","text":"Both have low calcium"},{"id":"d","text":"Secondary has normal calcium, primary has low calcium"}],"answerId":"b","explanation":"In secondary hyperparathyroidism, calcium levels are low or normal, while in primary hyperparathyroidism, calcium levels are high.","kind":"trap","origin":"ai"}],"hypoparathyroidism-treatment":[{"id":"hypoparathyroidism-treatment~ai-0","moduleId":"hypoparathyroidism-treatment","stem":"What is the primary laboratory finding in hypoparathyroidism?","options":[{"id":"a","text":"High PTH, low calcium, high phosphate"},{"id":"b","text":"Low PTH, low calcium, high phosphate"},{"id":"c","text":"Normal PTH, normal calcium, normal phosphate"},{"id":"d","text":"High PTH, normal calcium, low phosphate"}],"answerId":"b","explanation":"In hypoparathyroidism, the characteristic laboratory pattern is low PTH, low total/ionized calcium, and high phosphate.","kind":"recall","origin":"ai"},{"id":"hypoparathyroidism-treatment~ai-1","moduleId":"hypoparathyroidism-treatment","stem":"Which sign is characterized by facial twitching upon tapping the facial nerve in hypocalcemia?","options":[{"id":"a","text":"Trousseau sign"},{"id":"b","text":"Chvostek sign"},{"id":"c","text":"Carpopedal spasm"},{"id":"d","text":"Laryngospasm"}],"answerId":"b","explanation":"Chvostek sign is the facial-nerve hyperirritability seen in hypocalcemia.","kind":"recall","origin":"ai"},{"id":"hypoparathyroidism-treatment~ai-2","moduleId":"hypoparathyroidism-treatment","stem":"What is the immediate treatment for acute symptomatic hypocalcemia?","options":[{"id":"a","text":"Oral calcium supplementation"},{"id":"b","text":"Slow IV calcium gluconate"},{"id":"c","text":"Intramuscular vitamin D"},{"id":"d","text":"High-dose thiazide diuretic"}],"answerId":"b","explanation":"Acute symptomatic hypocalcemia requires slow IV calcium gluconate for immediate control.","kind":"trap","origin":"ai"},{"id":"hypoparathyroidism-treatment~ai-3","moduleId":"hypoparathyroidism-treatment","stem":"Which of the following is a symptom of hypocalcemic tetany?","options":[{"id":"a","text":"Bradycardia"},{"id":"b","text":"Hypotension"},{"id":"c","text":"Seizures"},{"id":"d","text":"Hyperglycemia"}],"answerId":"c","explanation":"Seizures can occur as a result of severe hypocalcemic tetany.","kind":"clinical","origin":"ai"},{"id":"hypoparathyroidism-treatment~ai-4","moduleId":"hypoparathyroidism-treatment","stem":"How does hypoparathyroidism lead to neuromuscular irritability?","options":[{"id":"a","text":"Increased calcium levels"},{"id":"b","text":"Decreased calcium levels"},{"id":"c","text":"Increased phosphate levels"},{"id":"d","text":"Decreased phosphate levels"}],"answerId":"b","explanation":"Hypoparathyroidism leads to decreased calcium levels, which causes neuromuscular irritability.","kind":"mechanism","origin":"ai"},{"id":"hypoparathyroidism-treatment~ai-5","moduleId":"hypoparathyroidism-treatment","stem":"In patients with chronic hypoparathyroidism, what medication can help manage urinary calcium excretion?","options":[{"id":"a","text":"Loop diuretics"},{"id":"b","text":"Thiazide diuretics"},{"id":"c","text":"Potassium-sparing diuretics"},{"id":"d","text":"Carbonic anhydrase inhibitors"}],"answerId":"b","explanation":"Thiazide diuretics can be used to reduce urinary calcium excretion in selected patients with chronic hypoparathyroidism.","kind":"recall","origin":"ai"},{"id":"hypoparathyroidism-treatment~ai-6","moduleId":"hypoparathyroidism-treatment","stem":"How does secondary hyperparathyroidism in CKD relate to hypoparathyroidism?","options":[{"id":"a","text":"Both involve high PTH levels"},{"id":"b","text":"Both are caused by vitamin D deficiency"},{"id":"c","text":"Both present with low calcium levels"},{"id":"d","text":"Both require calcium supplementation"}],"answerId":"a","explanation":"Both conditions involve dysregulation of PTH, but secondary hyperparathyroidism typically presents with high PTH levels due to low calcium.","kind":"integration","linkedModuleIds":["secondary-hyperparathyroidism-ckd"],"origin":"ai"},{"id":"hypoparathyroidism-treatment~ai-7","moduleId":"hypoparathyroidism-treatment","stem":"What is a common clinical finding in both hypoparathyroidism and severe hypercalcemia?","options":[{"id":"a","text":"Tetany"},{"id":"b","text":"Bone pain"},{"id":"c","text":"Fatigue"},{"id":"d","text":"Nausea"}],"answerId":"c","explanation":"Fatigue can be a common symptom in both conditions, although the mechanisms differ.","kind":"integration","linkedModuleIds":["severe-hypercalcemia-therapy"],"origin":"ai"}],"thioamides-antithyroid-drugs":[{"id":"thioamides-antithyroid-drugs~ai-0","moduleId":"thioamides-antithyroid-drugs","stem":"What is the primary mechanism of action of methimazole?","options":[{"id":"a","text":"Inhibits T4 to T3 conversion"},{"id":"b","text":"Blocks thyroid peroxidase"},{"id":"c","text":"Inhibits iodide absorption"},{"id":"d","text":"Stimulates thyroid hormone release"}],"answerId":"b","explanation":"Methimazole primarily inhibits thyroid peroxidase, blocking iodide organification and coupling.","kind":"mechanism","origin":"ai"},{"id":"thioamides-antithyroid-drugs~ai-1","moduleId":"thioamides-antithyroid-drugs","stem":"Which of the following is a common side effect of both methimazole and propylthiouracil?","options":[{"id":"a","text":"Hypothyroidism"},{"id":"b","text":"Agranulocytosis"},{"id":"c","text":"Hyperthyroidism"},{"id":"d","text":"Thyroid storm"}],"answerId":"b","explanation":"Agranulocytosis is a dangerous shared toxicity of both methimazole and propylthiouracil.","kind":"trap","origin":"ai"},{"id":"thioamides-antithyroid-drugs~ai-2","moduleId":"thioamides-antithyroid-drugs","stem":"In which situation is propylthiouracil preferred over methimazole?","options":[{"id":"a","text":"In patients with liver disease"},{"id":"b","text":"During the first trimester of pregnancy"},{"id":"c","text":"For chronic management of hyperthyroidism"},{"id":"d","text":"In patients with agranulocytosis history"}],"answerId":"b","explanation":"PTU is preferred during the first trimester of pregnancy due to its safety profile.","kind":"recall","origin":"ai"},{"id":"thioamides-antithyroid-drugs~ai-3","moduleId":"thioamides-antithyroid-drugs","stem":"A patient on propylthiouracil presents with jaundice. What is the most likely cause?","options":[{"id":"a","text":"Agranulocytosis"},{"id":"b","text":"Severe hepatitis"},{"id":"c","text":"Allergic reaction"},{"id":"d","text":"Thyroid storm"}],"answerId":"b","explanation":"Severe hepatitis is a characteristic major toxicity associated with propylthiouracil.","kind":"clinical","origin":"ai"},{"id":"thioamides-antithyroid-drugs~ai-4","moduleId":"thioamides-antithyroid-drugs","stem":"Why do thioamides have a delayed onset of action?","options":[{"id":"a","text":"They block synthesis but not release of stored hormone"},{"id":"b","text":"Their absorption is slow"},{"id":"c","text":"They require metabolic activation"},{"id":"d","text":"They induce thyroid hormone resistance"}],"answerId":"a","explanation":"Thioamides block synthesis but do not prevent the release of preformed thyroid hormone, leading to a delayed clinical effect.","kind":"trap","origin":"ai"},{"id":"thioamides-antithyroid-drugs~ai-5","moduleId":"thioamides-antithyroid-drugs","stem":"How does methimazole's potency compare to propylthiouracil?","options":[{"id":"a","text":"Methimazole is less potent"},{"id":"b","text":"Both are equally potent"},{"id":"c","text":"Methimazole is about 10 times more potent"},{"id":"d","text":"Propylthiouracil is more potent"}],"answerId":"c","explanation":"Methimazole is approximately 10 times more potent than propylthiouracil.","kind":"recall","origin":"ai"},{"id":"thioamides-antithyroid-drugs~ai-6","moduleId":"thioamides-antithyroid-drugs","stem":"Which thioamide is preferred for treating hyperthyroidism in the first trimester of pregnancy?","options":[{"id":"a","text":"Methimazole"},{"id":"b","text":"Propylthiouracil"},{"id":"c","text":"Both are equally preferred"},{"id":"d","text":"Neither is preferred"}],"answerId":"b","explanation":"Propylthiouracil is preferred during the first trimester due to its safety profile.","kind":"integration","linkedModuleIds":["thyroid-hormone-replacement"],"origin":"ai"},{"id":"thioamides-antithyroid-drugs~ai-7","moduleId":"thioamides-antithyroid-drugs","stem":"What is a potential complication of using thioamides in hyperthyroid patients undergoing radioiodine therapy?","options":[{"id":"a","text":"Increased thyroid hormone release"},{"id":"b","text":"Delayed response to treatment"},{"id":"c","text":"Increased risk of thyroid storm"},{"id":"d","text":"Decreased effectiveness of radioiodine"}],"answerId":"d","explanation":"Thioamides can decrease the effectiveness of radioiodine therapy by inhibiting thyroid hormone synthesis.","kind":"integration","linkedModuleIds":["iodide-radioiodine-thyrotoxicosis"],"origin":"ai"}],"hba1c-fructosamine":[{"id":"hba1c-fructosamine~ai-0","moduleId":"hba1c-fructosamine","stem":"What is the primary mechanism by which HbA1c is formed?","options":[{"id":"a","text":"Nonenzymatic glycation of hemoglobin"},{"id":"b","text":"Enzymatic modification of glucose"},{"id":"c","text":"Oxidative stress on red blood cells"},{"id":"d","text":"Binding of glucose to albumin"}],"answerId":"a","explanation":"HbA1c forms when glucose nonenzymatically binds to hemoglobin, specifically the N-terminal valine of the beta chain.","kind":"mechanism","origin":"ai"},{"id":"hba1c-fructosamine~ai-1","moduleId":"hba1c-fructosamine","stem":"In a patient with hemolytic anemia, what would you expect regarding their HbA1c levels?","options":[{"id":"a","text":"Normal HbA1c despite high glucose levels"},{"id":"b","text":"High HbA1c due to increased glycation"},{"id":"c","text":"Low HbA1c due to shortened RBC lifespan"},{"id":"d","text":"Unchanged HbA1c levels"}],"answerId":"c","explanation":"Shortened RBC survival in hemolytic anemia reduces the time available for glycation, leading to falsely low HbA1c levels.","kind":"recall","origin":"ai"},{"id":"hba1c-fructosamine~ai-2","moduleId":"hba1c-fructosamine","stem":"What is the typical diagnostic threshold for diabetes based on HbA1c?","options":[{"id":"a","text":"<5.7%"},{"id":"b","text":"5.7-6.4%"},{"id":"c","text":"6.5% or greater"},{"id":"d","text":"7.0% or greater"}],"answerId":"c","explanation":"A HbA1c of 6.5% or greater is used to diagnose diabetes.","kind":"recall","origin":"ai"},{"id":"hba1c-fructosamine~ai-3","moduleId":"hba1c-fructosamine","stem":"Which condition can falsely elevate HbA1c levels?","options":[{"id":"a","text":"Hemolytic anemia"},{"id":"b","text":"Iron deficiency anemia"},{"id":"c","text":"Chronic kidney disease"},{"id":"d","text":"Acute blood loss"}],"answerId":"b","explanation":"Iron deficiency anemia can alter the RBC population, leading to falsely elevated HbA1c levels.","kind":"trap","origin":"ai"},{"id":"hba1c-fructosamine~ai-4","moduleId":"hba1c-fructosamine","stem":"Fructosamine is particularly useful in monitoring glycemic control in which scenario?","options":[{"id":"a","text":"Long-term diabetes management"},{"id":"b","text":"Rapid changes in therapy"},{"id":"c","text":"Chronic kidney disease"},{"id":"d","text":"Stable diabetes without recent changes"}],"answerId":"b","explanation":"Fructosamine reflects glycemic exposure over 2-3 weeks, making it useful after rapid changes in therapy.","kind":"recall","origin":"ai"},{"id":"hba1c-fructosamine~ai-5","moduleId":"hba1c-fructosamine","stem":"How does fructosamine differ from HbA1c in terms of glycemic exposure time?","options":[{"id":"a","text":"Fructosamine reflects 8-12 weeks, HbA1c reflects 2-3 weeks"},{"id":"b","text":"Fructosamine reflects 2-3 weeks, HbA1c reflects 8-12 weeks"},{"id":"c","text":"Both reflect the same duration"},{"id":"d","text":"HbA1c reflects only short-term glycemia"}],"answerId":"b","explanation":"Fructosamine measures glycated proteins over 2-3 weeks, while HbA1c integrates glycemic exposure over 8-12 weeks.","kind":"integration","linkedModuleIds":["prediabetes-ogtt-hba1c"],"origin":"ai"},{"id":"hba1c-fructosamine~ai-6","moduleId":"hba1c-fructosamine","stem":"In the context of diabetes diagnosis, which test is complementary to HbA1c?","options":[{"id":"a","text":"Fructosamine"},{"id":"b","text":"Random plasma glucose"},{"id":"c","text":"Fasting insulin"},{"id":"d","text":"C-peptide levels"}],"answerId":"b","explanation":"Random plasma glucose can be used alongside HbA1c for diagnosing diabetes, especially in acute settings.","kind":"integration","linkedModuleIds":["diabetes-diagnostic-criteria-gdm"],"origin":"ai"}],"dka-hhs-recognition":[{"id":"dka-hhs-recognition~ai-0","moduleId":"dka-hhs-recognition","stem":"Which of the following is a required criterion for diagnosing DKA?","options":[{"id":"a","text":"Glucose >=600 mg/dL"},{"id":"b","text":"BHB >=3 mmol/L"},{"id":"c","text":"pH >=7.3"},{"id":"d","text":"Urine ketones <2+"}],"answerId":"b","explanation":"DKA requires ketosis, which is indicated by BHB >=3 mmol/L or urine ketones >=2+.","kind":"recall","origin":"ai"},{"id":"dka-hhs-recognition~ai-1","moduleId":"dka-hhs-recognition","stem":"What is the primary mechanism leading to metabolic acidosis in DKA?","options":[{"id":"a","text":"Increased lactic acid production"},{"id":"b","text":"Excessive ketone production"},{"id":"c","text":"Renal failure"},{"id":"d","text":"Decreased bicarbonate reabsorption"}],"answerId":"b","explanation":"In DKA, absolute insulin deficiency leads to increased ketone production, resulting in metabolic acidosis.","kind":"mechanism","origin":"ai"},{"id":"dka-hhs-recognition~ai-2","moduleId":"dka-hhs-recognition","stem":"A patient presents with Kussmaul breathing, fruity breath, and abdominal pain. What is the most likely diagnosis?","options":[{"id":"a","text":"Hyperglycemic hyperosmolar state"},{"id":"b","text":"Diabetic ketoacidosis"},{"id":"c","text":"Acute pancreatitis"},{"id":"d","text":"Chronic kidney disease"}],"answerId":"b","explanation":"These symptoms are classic for diabetic ketoacidosis (DKA).","kind":"clinical","origin":"ai"},{"id":"dka-hhs-recognition~ai-3","moduleId":"dka-hhs-recognition","stem":"Which of the following findings is characteristic of HHS?","options":[{"id":"a","text":"BHB >=3 mmol/L"},{"id":"b","text":"pH <7.3"},{"id":"c","text":"Glucose >=600 mg/dL"},{"id":"d","text":"Kussmaul breathing"}],"answerId":"c","explanation":"HHS is characterized by very high glucose levels (>=600 mg/dL) without significant ketogenesis.","kind":"recall","origin":"ai"},{"id":"dka-hhs-recognition~ai-4","moduleId":"dka-hhs-recognition","stem":"In DKA, why might serum potassium levels be normal or high despite total-body potassium depletion?","options":[{"id":"a","text":"Increased dietary intake"},{"id":"b","text":"Insulin administration"},{"id":"c","text":"Acidosis and insulin deficiency"},{"id":"d","text":"Renal retention"}],"answerId":"c","explanation":"Acidosis and lack of insulin cause potassium to shift out of cells, leading to normal or high serum potassium levels.","kind":"mechanism","origin":"ai"},{"id":"dka-hhs-recognition~ai-5","moduleId":"dka-hhs-recognition","stem":"A patient with diabetes presents with a blood glucose of 180 mg/dL, BHB of 4 mmol/L, and a pH of 7.2. What is the most appropriate diagnosis?","options":[{"id":"a","text":"Euglycemic DKA"},{"id":"b","text":"HHS"},{"id":"c","text":"Normal metabolic state"},{"id":"d","text":"Acute renal failure"}],"answerId":"a","explanation":"Euglycemic DKA can occur with glucose levels below 200 mg/dL if ketosis and metabolic acidosis are present.","kind":"trap","origin":"ai"},{"id":"dka-hhs-recognition~ai-6","moduleId":"dka-hhs-recognition","stem":"How does the presence of hyperglycemia in DKA differ from that in HHS?","options":[{"id":"a","text":"Both have similar glucose levels"},{"id":"b","text":"HHS has higher glucose levels"},{"id":"c","text":"DKA has higher glucose levels"},{"id":"d","text":"Glucose levels are irrelevant in both"}],"answerId":"b","explanation":"HHS typically presents with much higher glucose levels compared to DKA.","kind":"integration","linkedModuleIds":["hen1-glycemic-markers-emergencies"],"origin":"ai"},{"id":"dka-hhs-recognition~ai-7","moduleId":"dka-hhs-recognition","stem":"Which laboratory finding would help differentiate DKA from nutritional ketosis?","options":[{"id":"a","text":"Blood glucose levels"},{"id":"b","text":"BHB levels"},{"id":"c","text":"Urine ketones"},{"id":"d","text":"Serum bicarbonate"}],"answerId":"d","explanation":"Serum bicarbonate levels <18 mmol/L are indicative of metabolic acidosis in DKA, distinguishing it from nutritional ketosis.","kind":"integration","linkedModuleIds":["nutritional-ketosis-vs-ketoacidosis"],"origin":"ai"}],"iodide-radioiodine-thyrotoxicosis":[{"id":"iodide-radioiodine-thyrotoxicosis~ai-0","moduleId":"iodide-radioiodine-thyrotoxicosis","stem":"What is the primary mechanism of high-dose iodide in treating thyroid storm?","options":[{"id":"a","text":"Inhibits thyroid hormone synthesis"},{"id":"b","text":"Reduces thyroid vascularity"},{"id":"c","text":"Blocks thyroid hormone release"},{"id":"d","text":"Increases iodide uptake"}],"answerId":"c","explanation":"High-dose iodide primarily blocks the release of thyroid hormones, providing rapid control in thyroid storm.","kind":"mechanism","origin":"ai"},{"id":"iodide-radioiodine-thyrotoxicosis~ai-1","moduleId":"iodide-radioiodine-thyrotoxicosis","stem":"Which of the following is a common consequence of radioactive iodine-131 therapy?","options":[{"id":"a","text":"Hyperthyroidism"},{"id":"b","text":"Hypothyroidism"},{"id":"c","text":"Thyroid storm"},{"id":"d","text":"Goiter enlargement"}],"answerId":"b","explanation":"Delayed hypothyroidism is a common outcome after definitive treatment with radioactive iodine-131.","kind":"recall","origin":"ai"},{"id":"iodide-radioiodine-thyrotoxicosis~ai-2","moduleId":"iodide-radioiodine-thyrotoxicosis","stem":"In preparation for surgery, which treatment should be administered first in a patient with thyroid storm?","options":[{"id":"a","text":"Iodide"},{"id":"b","text":"Radioactive iodine"},{"id":"c","text":"Thioamide"},{"id":"d","text":"Propranolol"}],"answerId":"c","explanation":"Thioamide should be given first to block hormone synthesis before administering iodide.","kind":"trap","origin":"ai"},{"id":"iodide-radioiodine-thyrotoxicosis~ai-3","moduleId":"iodide-radioiodine-thyrotoxicosis","stem":"What is the duration of action for high-dose iodide therapy?","options":[{"id":"a","text":"24 hours"},{"id":"b","text":"2-8 weeks"},{"id":"c","text":"6 months"},{"id":"d","text":"1 year"}],"answerId":"b","explanation":"The effects of high-dose iodide last approximately 2-8 weeks, necessitating careful management of therapy.","kind":"recall","origin":"ai"},{"id":"iodide-radioiodine-thyrotoxicosis~ai-4","moduleId":"iodide-radioiodine-thyrotoxicosis","stem":"Which adjunctive therapy can relieve adrenergic symptoms in thyroid storm?","options":[{"id":"a","text":"Methimazole"},{"id":"b","text":"Propranolol"},{"id":"c","text":"Diltiazem"},{"id":"d","text":"Glucocorticoids"}],"answerId":"b","explanation":"Propranolol is effective in relieving adrenergic symptoms associated with hyperthyroidism.","kind":"recall","origin":"ai"},{"id":"iodide-radioiodine-thyrotoxicosis~ai-5","moduleId":"iodide-radioiodine-thyrotoxicosis","stem":"How does the administration of iodide before thioamides affect thyroid hormone production?","options":[{"id":"a","text":"Increases hormone production"},{"id":"b","text":"Decreases hormone production"},{"id":"c","text":"Has no effect"},{"id":"d","text":"Inhibits hormone release"}],"answerId":"a","explanation":"Administering iodide before thioamides can provide substrate to the gland, potentially worsening hormone production.","kind":"trap","origin":"ai"},{"id":"iodide-radioiodine-thyrotoxicosis~ai-6","moduleId":"iodide-radioiodine-thyrotoxicosis","stem":"How does iodide therapy relate to thyroid hormone synthesis?","options":[{"id":"a","text":"Iodide enhances synthesis"},{"id":"b","text":"Iodide blocks synthesis"},{"id":"c","text":"Iodide has no effect on synthesis"},{"id":"d","text":"Iodide increases release of hormones"}],"answerId":"b","explanation":"Iodide therapy blocks the synthesis of thyroid hormones, which is crucial in managing conditions like thyroid storm.","kind":"integration","linkedModuleIds":["hen1-thyroid-hormone-synthesis"],"origin":"ai"},{"id":"iodide-radioiodine-thyrotoxicosis~ai-7","moduleId":"iodide-radioiodine-thyrotoxicosis","stem":"What is the effect of thioamides on thyroid hormone levels prior to iodide therapy?","options":[{"id":"a","text":"Increase T4 levels"},{"id":"b","text":"Decrease T4 levels"},{"id":"c","text":"No effect on T4 levels"},{"id":"d","text":"Increase T3 levels"}],"answerId":"b","explanation":"Thioamides decrease T4 levels by inhibiting thyroid hormone synthesis, which is essential before administering iodide.","kind":"integration","linkedModuleIds":["thioamides-antithyroid-drugs"],"origin":"ai"}],"diabetes-ketone-albuminuria-tests":[{"id":"diabetes-ketone-albuminuria-tests~ai-0","moduleId":"diabetes-ketone-albuminuria-tests","stem":"What is the principal ketone body produced during prolonged fasting or diabetic ketoacidosis?","options":[{"id":"a","text":"Acetoacetate"},{"id":"b","text":"Beta-hydroxybutyrate"},{"id":"c","text":"Acetone"},{"id":"d","text":"Lactate"}],"answerId":"b","explanation":"Beta-hydroxybutyrate is the predominant ketone body produced in ketosis, especially during diabetic ketoacidosis.","kind":"recall","origin":"ai"},{"id":"diabetes-ketone-albuminuria-tests~ai-1","moduleId":"diabetes-ketone-albuminuria-tests","stem":"Which urine test is most reliable for detecting ketones in diabetic ketoacidosis?","options":[{"id":"a","text":"Urine nitroprusside strip"},{"id":"b","text":"Urine ketone bodies panel"},{"id":"c","text":"Urine BHB test"},{"id":"d","text":"Urine acetoacetate test"}],"answerId":"c","explanation":"Urine nitroprusside strips primarily detect acetoacetate and may underestimate the severity of DKA; a urine BHB test would be more accurate.","kind":"mechanism","origin":"ai"},{"id":"diabetes-ketone-albuminuria-tests~ai-2","moduleId":"diabetes-ketone-albuminuria-tests","stem":"A patient presents with Kussmaul breathing and abdominal pain. What is the most likely acid-base disturbance?","options":[{"id":"a","text":"Respiratory acidosis"},{"id":"b","text":"Metabolic acidosis"},{"id":"c","text":"Respiratory alkalosis"},{"id":"d","text":"Metabolic alkalosis"}],"answerId":"b","explanation":"Kussmaul breathing is a compensatory mechanism for metabolic acidosis, commonly seen in diabetic ketoacidosis.","kind":"clinical","origin":"ai"},{"id":"diabetes-ketone-albuminuria-tests~ai-3","moduleId":"diabetes-ketone-albuminuria-tests","stem":"What is the significance of a urine albumin-to-creatinine ratio (ACR) of 250 mg/g?","options":[{"id":"a","text":"Normal albuminuria"},{"id":"b","text":"Moderately increased albuminuria"},{"id":"c","text":"Severely increased albuminuria"},{"id":"d","text":"Transient albuminuria"}],"answerId":"b","explanation":"An ACR of 250 mg/g indicates moderately increased albuminuria, which suggests early diabetic kidney injury.","kind":"recall","origin":"ai"},{"id":"diabetes-ketone-albuminuria-tests~ai-4","moduleId":"diabetes-ketone-albuminuria-tests","stem":"In a patient with suspected diabetic ketoacidosis, which finding would best support the diagnosis?","options":[{"id":"a","text":"Normal blood glucose"},{"id":"b","text":"High blood beta-hydroxybutyrate"},{"id":"c","text":"Low urine acetoacetate"},{"id":"d","text":"Normal bicarbonate levels"}],"answerId":"b","explanation":"High blood beta-hydroxybutyrate levels are indicative of ketosis and support the diagnosis of DKA.","kind":"trap","origin":"ai"},{"id":"diabetes-ketone-albuminuria-tests~ai-5","moduleId":"diabetes-ketone-albuminuria-tests","stem":"How does the presence of urinary tract infection (UTI) affect the interpretation of albuminuria in diabetes?","options":[{"id":"a","text":"It confirms diabetic nephropathy"},{"id":"b","text":"It can cause transient albuminuria"},{"id":"c","text":"It indicates chronic kidney disease"},{"id":"d","text":"It has no effect on albumin levels"}],"answerId":"b","explanation":"A UTI can transiently raise albumin levels, necessitating repeat testing for confirmation of albuminuria.","kind":"mechanism","origin":"ai"},{"id":"diabetes-ketone-albuminuria-tests~ai-6","moduleId":"diabetes-ketone-albuminuria-tests","stem":"A patient with hyperglycemia and altered consciousness has minimal ketosis. Which condition is most likely?","options":[{"id":"a","text":"Diabetic ketoacidosis"},{"id":"b","text":"Hyperglycemic hyperosmolar state"},{"id":"c","text":"Lactic acidosis"},{"id":"d","text":"Hypoglycemia"}],"answerId":"b","explanation":"The presentation of extreme hyperglycemia with minimal ketosis suggests hyperglycemic hyperosmolar state (HHS).","kind":"clinical","origin":"ai"},{"id":"diabetes-ketone-albuminuria-tests~ai-7","moduleId":"diabetes-ketone-albuminuria-tests","stem":"How does the management of diabetic ketoacidosis differ from hyperglycemic hyperosmolar state?","options":[{"id":"a","text":"Both require insulin therapy"},{"id":"b","text":"Only DKA requires fluid resuscitation"},{"id":"c","text":"HHS requires more aggressive electrolyte monitoring"},{"id":"d","text":"Only HHS requires bicarbonate therapy"}],"answerId":"a","explanation":"Both conditions require insulin therapy, but their management strategies differ significantly in fluid and electrolyte management.","kind":"integration","linkedModuleIds":["hen1-glycemic-markers-emergencies"],"origin":"ai"},{"id":"diabetes-ketone-albuminuria-tests~ai-8","moduleId":"diabetes-ketone-albuminuria-tests","stem":"Which test is essential for monitoring glycemic control in patients with diabetes and potential kidney complications?","options":[{"id":"a","text":"Urine ketones"},{"id":"b","text":"Urine ACR"},{"id":"c","text":"Blood glucose"},{"id":"d","text":"HbA1c"}],"answerId":"b","explanation":"The urine albumin-to-creatinine ratio (ACR) is crucial for assessing kidney injury in diabetic patients, alongside glycemic control tests.","kind":"integration","linkedModuleIds":["diabetes-diagnostic-criteria-gdm"],"origin":"ai"}],"diabetes-diagnostic-criteria-gdm":[{"id":"diabetes-diagnostic-criteria-gdm~ai-0","moduleId":"diabetes-diagnostic-criteria-gdm","stem":"What is the fasting plasma glucose level that confirms a diagnosis of diabetes?","options":[{"id":"a","text":"100 mg/dL"},{"id":"b","text":"110 mg/dL"},{"id":"c","text":"126 mg/dL"},{"id":"d","text":"140 mg/dL"}],"answerId":"c","explanation":"A fasting plasma glucose level of 126 mg/dL or higher is diagnostic for diabetes.","kind":"recall","origin":"ai"},{"id":"diabetes-diagnostic-criteria-gdm~ai-1","moduleId":"diabetes-diagnostic-criteria-gdm","stem":"Which of the following is a classic symptom of diabetes?","options":[{"id":"a","text":"Weight gain"},{"id":"b","text":"Polyuria"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Bradycardia"}],"answerId":"b","explanation":"Polyuria is one of the classic symptoms associated with diabetes due to osmotic diuresis from hyperglycemia.","kind":"recall","origin":"ai"},{"id":"diabetes-diagnostic-criteria-gdm~ai-2","moduleId":"diabetes-diagnostic-criteria-gdm","stem":"In an asymptomatic patient, when should an abnormal glucose result be confirmed?","options":[{"id":"a","text":"Immediately treat with insulin"},{"id":"b","text":"Repeat testing is not necessary"},{"id":"c","text":"Confirm with repeat testing"},{"id":"d","text":"Diagnose diabetes based on one test"}],"answerId":"c","explanation":"An abnormal result in an asymptomatic patient should be confirmed with repeat testing unless there is unequivocal hyperglycemia.","kind":"trap","origin":"ai"},{"id":"diabetes-diagnostic-criteria-gdm~ai-3","moduleId":"diabetes-diagnostic-criteria-gdm","stem":"What is the threshold for diagnosing GDM using the one-step approach?","options":[{"id":"a","text":"Fasting 90 mg/dL"},{"id":"b","text":"1-hour 160 mg/dL"},{"id":"c","text":"2-hour 140 mg/dL"},{"id":"d","text":"Fasting 92 mg/dL"}],"answerId":"d","explanation":"In the one-step approach for GDM, a fasting glucose level of 92 mg/dL or higher is diagnostic.","kind":"recall","origin":"ai"},{"id":"diabetes-diagnostic-criteria-gdm~ai-4","moduleId":"diabetes-diagnostic-criteria-gdm","stem":"What is the primary mechanism for screening and diagnosing diabetes?","options":[{"id":"a","text":"Symptomatic assessment"},{"id":"b","text":"Genetic testing"},{"id":"c","text":"Screen risk -> confirm dysglycemia -> classify context"},{"id":"d","text":"Dietary evaluation"}],"answerId":"c","explanation":"The mechanism involves screening for risk factors, confirming dysglycemia, and classifying the context of diabetes.","kind":"mechanism","origin":"ai"},{"id":"diabetes-diagnostic-criteria-gdm~ai-5","moduleId":"diabetes-diagnostic-criteria-gdm","stem":"A 25-week pregnant woman has a fasting glucose of 94 mg/dL during a 75-g OGTT. What does this indicate?","options":[{"id":"a","text":"Normal glucose tolerance"},{"id":"b","text":"Diabetes"},{"id":"c","text":"GDM"},{"id":"d","text":"Impaired fasting glucose"}],"answerId":"c","explanation":"A fasting glucose of 94 mg/dL is above the threshold for GDM diagnosis in the one-step approach.","kind":"recall","origin":"ai"},{"id":"diabetes-diagnostic-criteria-gdm~ai-6","moduleId":"diabetes-diagnostic-criteria-gdm","stem":"How does the diagnosis of GDM differ from nonpregnant diabetes?","options":[{"id":"a","text":"GDM requires a higher fasting glucose"},{"id":"b","text":"GDM is diagnosed only with symptoms"},{"id":"c","text":"GDM uses different glucose thresholds"},{"id":"d","text":"GDM does not require confirmation"}],"answerId":"c","explanation":"GDM uses specific glucose thresholds for diagnosis that differ from those used for nonpregnant diabetes.","kind":"integration","linkedModuleIds":["hen1-gestational-diabetes-diagnosis"],"origin":"ai"},{"id":"diabetes-diagnostic-criteria-gdm~ai-7","moduleId":"diabetes-diagnostic-criteria-gdm","stem":"What is the significance of a HbA1c level of 6.0% in a pregnant woman?","options":[{"id":"a","text":"Normal glucose metabolism"},{"id":"b","text":"Prediabetes"},{"id":"c","text":"Diabetes"},{"id":"d","text":"Requires immediate treatment"}],"answerId":"b","explanation":"An HbA1c level of 6.0% indicates prediabetes, which requires monitoring but not immediate treatment.","kind":"integration","linkedModuleIds":["hen1-diabetes-diagnostic-criteria"],"origin":"ai"}],"severe-hypercalcemia-therapy":[{"id":"severe-hypercalcemia-therapy~ai-0","moduleId":"severe-hypercalcemia-therapy","stem":"What is the most common cause of primary hyperparathyroidism?","options":[{"id":"a","text":"Multiple gland hyperplasia"},{"id":"b","text":"Parathyroid carcinoma"},{"id":"c","text":"Solitary adenoma"},{"id":"d","text":"Familial hypocalciuric hypercalcemia"}],"answerId":"c","explanation":"The majority of primary hyperparathyroidism cases are due to a solitary adenoma, accounting for approximately 85% of cases.","kind":"recall","origin":"ai"},{"id":"severe-hypercalcemia-therapy~ai-1","moduleId":"severe-hypercalcemia-therapy","stem":"What is the primary mechanism of action of calcitonin in treating severe hypercalcemia?","options":[{"id":"a","text":"Inhibiting renal calcium reabsorption"},{"id":"b","text":"Promoting osteoclast apoptosis"},{"id":"c","text":"Increasing calcium-sensing receptor sensitivity"},{"id":"d","text":"Inhibiting osteoclast activity"}],"answerId":"d","explanation":"Calcitonin acts by inhibiting osteoclast activity, which reduces bone resorption and lowers serum calcium levels.","kind":"mechanism","origin":"ai"},{"id":"severe-hypercalcemia-therapy~ai-2","moduleId":"severe-hypercalcemia-therapy","stem":"In a patient with severe hypercalcemia and dehydration, what is the initial management step?","options":[{"id":"a","text":"Administer furosemide"},{"id":"b","text":"Start isotonic saline"},{"id":"c","text":"Give calcitonin"},{"id":"d","text":"Use IV bisphosphonates"}],"answerId":"b","explanation":"The first step is to restore intravascular volume with isotonic saline to improve renal perfusion and promote calcium excretion.","kind":"trap","origin":"ai"},{"id":"severe-hypercalcemia-therapy~ai-3","moduleId":"severe-hypercalcemia-therapy","stem":"Which of the following findings is most consistent with severe hypercalcemia?","options":[{"id":"a","text":"Hypotension and bradycardia"},{"id":"b","text":"Stones, bone pain, and psychiatric changes"},{"id":"c","text":"Increased muscle tone and reflexes"},{"id":"d","text":"Decreased urine output and edema"}],"answerId":"b","explanation":"Severe hypercalcemia can lead to a multisystem effect, including stones, bone pain, abdominal symptoms, and psychiatric changes.","kind":"recall","origin":"ai"},{"id":"severe-hypercalcemia-therapy~ai-4","moduleId":"severe-hypercalcemia-therapy","stem":"What is the expected effect of calcitonin on serum calcium levels?","options":[{"id":"a","text":"Calcium levels rise immediately"},{"id":"b","text":"Calcium levels fall rapidly then rebound"},{"id":"c","text":"Calcium levels remain unchanged"},{"id":"d","text":"Calcium levels fall gradually over weeks"}],"answerId":"b","explanation":"Calcitonin causes a rapid decrease in serum calcium levels, but due to tachyphylaxis, levels may rebound shortly after.","kind":"clinical","origin":"ai"},{"id":"severe-hypercalcemia-therapy~ai-5","moduleId":"severe-hypercalcemia-therapy","stem":"How does cinacalcet lower serum calcium levels in hyperparathyroidism?","options":[{"id":"a","text":"Inhibiting osteoclast activity"},{"id":"b","text":"Increasing renal calcium excretion"},{"id":"c","text":"Enhancing calcium-sensing receptor sensitivity"},{"id":"d","text":"Decreasing intestinal calcium absorption"}],"answerId":"c","explanation":"Cinacalcet acts as a calcimimetic, increasing the sensitivity of calcium-sensing receptors, which leads to decreased PTH secretion and lower serum calcium levels.","kind":"mechanism","origin":"ai"},{"id":"severe-hypercalcemia-therapy~ai-6","moduleId":"severe-hypercalcemia-therapy","stem":"How does the treatment of severe hypercalcemia relate to calcium homeostasis?","options":[{"id":"a","text":"It directly increases calcium absorption in the gut"},{"id":"b","text":"It enhances renal calcium excretion through hydration"},{"id":"c","text":"It decreases bone resorption by increasing PTH"},{"id":"d","text":"It promotes calcitriol synthesis in the kidneys"}],"answerId":"b","explanation":"The treatment of severe hypercalcemia focuses on restoring hydration to enhance renal calcium excretion, which is crucial for calcium homeostasis.","kind":"integration","linkedModuleIds":["calcium-homeostasis-hormones"],"origin":"ai"},{"id":"severe-hypercalcemia-therapy~ai-7","moduleId":"severe-hypercalcemia-therapy","stem":"What is the relationship between calcitonin and mineral homeostasis in the context of hypercalcemia?","options":[{"id":"a","text":"Calcitonin increases calcium absorption in the intestines"},{"id":"b","text":"Calcitonin decreases renal phosphate excretion"},{"id":"c","text":"Calcitonin inhibits osteoclasts, lowering serum calcium"},{"id":"d","text":"Calcitonin has no effect on mineral homeostasis"}],"answerId":"c","explanation":"Calcitonin plays a role in mineral homeostasis by inhibiting osteoclasts, which lowers serum calcium levels in hypercalcemia.","kind":"integration","linkedModuleIds":["hen1-calcitonin-mineral-integration"],"origin":"ai"}],"dka-hhs-management":[{"id":"dka-hhs-management~ai-0","moduleId":"dka-hhs-management","stem":"What is the primary initial treatment for a patient with DKA?","options":[{"id":"a","text":"IV crystalloid fluids"},{"id":"b","text":"Insulin therapy"},{"id":"c","text":"Potassium supplementation"},{"id":"d","text":"Bicarbonate administration"}],"answerId":"a","explanation":"The core therapy for DKA includes IV crystalloid fluids to restore circulation and improve renal function.","kind":"recall","origin":"ai"},{"id":"dka-hhs-management~ai-1","moduleId":"dka-hhs-management","stem":"When should insulin therapy be initiated in a patient with DKA?","options":[{"id":"a","text":"Immediately upon diagnosis"},{"id":"b","text":"After initial fluid resuscitation"},{"id":"c","text":"When blood glucose is <250 mg/dL"},{"id":"d","text":"Only if potassium is >5.0 mmol/L"}],"answerId":"b","explanation":"Insulin therapy should be started after initial assessment and resuscitation, particularly after ensuring potassium levels are safe.","kind":"mechanism","origin":"ai"},{"id":"dka-hhs-management~ai-2","moduleId":"dka-hhs-management","stem":"A patient with DKA presents with a potassium level of 3.0 mmol/L. What is the appropriate management?","options":[{"id":"a","text":"Start insulin immediately"},{"id":"b","text":"Administer potassium replacement"},{"id":"c","text":"Continue monitoring potassium"},{"id":"d","text":"Give bicarbonate therapy"}],"answerId":"b","explanation":"In cases of hypokalemia (K < 3.5 mmol/L), potassium must be replaced before starting insulin to prevent complications.","kind":"trap","origin":"ai"},{"id":"dka-hhs-management~ai-3","moduleId":"dka-hhs-management","stem":"What clinical finding indicates that insulin therapy is effective in DKA?","options":[{"id":"a","text":"Decreased blood glucose with persistent acidosis"},{"id":"b","text":"Increased urine output"},{"id":"c","text":"Normalization of blood pressure"},{"id":"d","text":"Improved mental status"}],"answerId":"a","explanation":"In DKA, blood glucose may decrease while acidosis persists; insulin must continue until acidosis resolves.","kind":"recall","origin":"ai"},{"id":"dka-hhs-management~ai-4","moduleId":"dka-hhs-management","stem":"What is the recommended insulin infusion rate for moderate DKA?","options":[{"id":"a","text":"0.05 U/kg/h"},{"id":"b","text":"0.1 U/kg/h"},{"id":"c","text":"0.2 U/kg/h"},{"id":"d","text":"0.3 U/kg/h"}],"answerId":"b","explanation":"The standard infusion rate for moderate DKA is 0.1 U/kg/h to effectively manage the condition.","kind":"recall","origin":"ai"},{"id":"dka-hhs-management~ai-5","moduleId":"dka-hhs-management","stem":"How does fluid resuscitation help in the management of DKA?","options":[{"id":"a","text":"Increases insulin sensitivity"},{"id":"b","text":"Reduces counterregulatory hormones"},{"id":"c","text":"Directly lowers blood glucose levels"},{"id":"d","text":"Prevents hyperkalemia"}],"answerId":"b","explanation":"Fluid resuscitation helps restore perfusion and reduces counterregulatory hormones, aiding in glucose management.","kind":"mechanism","origin":"ai"},{"id":"dka-hhs-management~ai-6","moduleId":"dka-hhs-management","stem":"Which electrolyte management strategy is crucial when starting insulin in DKA?","options":[{"id":"a","text":"Administer calcium supplements"},{"id":"b","text":"Monitor potassium levels closely"},{"id":"c","text":"Increase sodium intake"},{"id":"d","text":"Reduce fluid intake"}],"answerId":"b","explanation":"Monitoring potassium levels is crucial as insulin can cause potassium to shift into cells, leading to hypokalemia.","kind":"trap","origin":"ai"},{"id":"dka-hhs-management~ai-7","moduleId":"dka-hhs-management","stem":"How does the management of DKA relate to body fluid compartments?","options":[{"id":"a","text":"Fluid shifts are not significant in DKA"},{"id":"b","text":"Fluid resuscitation affects intracellular fluid volume"},{"id":"c","text":"Only extracellular fluid is affected"},{"id":"d","text":"Body fluid composition remains unchanged"}],"answerId":"b","explanation":"Fluid resuscitation in DKA affects both extracellular and intracellular fluid volumes, impacting overall fluid balance.","kind":"integration","linkedModuleIds":["body-fluid-compartments-renal"],"origin":"ai"},{"id":"dka-hhs-management~ai-8","moduleId":"dka-hhs-management","stem":"Why is potassium management critical in DKA treatment concerning renal function?","options":[{"id":"a","text":"Renal function has no impact on potassium levels"},{"id":"b","text":"Insulin therapy is safe regardless of renal status"},{"id":"c","text":"Renal function affects potassium excretion"},{"id":"d","text":"Potassium does not shift in DKA"}],"answerId":"c","explanation":"Renal function is crucial as it determines potassium excretion; impaired renal function can lead to hyperkalemia.","kind":"integration","linkedModuleIds":["volume-water-balance-hormones"],"origin":"ai"}],"cubital-fossa":[{"id":"cubital-fossa~ai-0","moduleId":"cubital-fossa","stem":"Which structure is NOT found in the cubital fossa?","options":[{"id":"a","text":"Biceps tendon"},{"id":"b","text":"Brachial artery"},{"id":"c","text":"Median nerve"},{"id":"d","text":"Ulnar nerve"}],"answerId":"d","explanation":"The ulnar nerve is not a structure found in the cubital fossa; it runs posterior to the medial epicondyle.","kind":"recall","origin":"ai"},{"id":"cubital-fossa~ai-1","moduleId":"cubital-fossa","stem":"What is the correct order of structures in the cubital fossa from lateral to medial?","options":[{"id":"a","text":"Median nerve, brachial artery, biceps tendon"},{"id":"b","text":"Brachial artery, median nerve, biceps tendon"},{"id":"c","text":"Biceps tendon, brachial artery, median nerve"},{"id":"d","text":"Biceps tendon, median nerve, brachial artery"}],"answerId":"c","explanation":"The mnemonic TAN helps remember the order: biceps tendon, brachial artery, median nerve.","kind":"trap","origin":"ai"},{"id":"cubital-fossa~ai-2","moduleId":"cubital-fossa","stem":"Which clinical sign indicates the location of the brachial artery in the cubital fossa?","options":[{"id":"a","text":"Brachial pulse medial to the biceps tendon"},{"id":"b","text":"Pain during elbow flexion"},{"id":"c","text":"Numbness in the forearm"},{"id":"d","text":"Weakness in wrist extension"}],"answerId":"a","explanation":"The brachial pulse is palpated medial to the biceps tendon, indicating the position of the brachial artery.","kind":"clinical","origin":"ai"},{"id":"cubital-fossa~ai-3","moduleId":"cubital-fossa","stem":"What is the primary function of the bicipital aponeurosis in the cubital fossa?","options":[{"id":"a","text":"To support the biceps tendon"},{"id":"b","text":"To protect deeper structures"},{"id":"c","text":"To facilitate blood flow"},{"id":"d","text":"To anchor the median nerve"}],"answerId":"b","explanation":"The bicipital aponeurosis serves as a protective layer for the underlying brachial artery and median nerve.","kind":"mechanism","origin":"ai"},{"id":"cubital-fossa~ai-4","moduleId":"cubital-fossa","stem":"In a patient with atrial fibrillation, which anatomical structure in the cubital fossa could be at risk during venipuncture?","options":[{"id":"a","text":"Biceps tendon"},{"id":"b","text":"Median cubital vein"},{"id":"c","text":"Brachial artery"},{"id":"d","text":"Radial nerve"}],"answerId":"c","explanation":"The brachial artery lies deep to the median cubital vein and is at risk during venipuncture.","kind":"integration","linkedModuleIds":["atrial-fibrillation"],"origin":"ai"},{"id":"cubital-fossa~ai-5","moduleId":"cubital-fossa","stem":"A fracture of the humerus could potentially affect which structure in the cubital fossa?","options":[{"id":"a","text":"Median nerve"},{"id":"b","text":"Biceps tendon"},{"id":"c","text":"Brachial artery"},{"id":"d","text":"Radial nerve"}],"answerId":"a","explanation":"A humeral fracture can lead to median nerve injury, which is located in the cubital fossa.","kind":"integration","linkedModuleIds":["arm-compartments-humerus-fractures"],"origin":"ai"}],"insulin-secretagogues":[{"id":"insulin-secretagogues~ai-0","moduleId":"insulin-secretagogues","stem":"What is the primary mechanism by which sulfonylureas stimulate insulin secretion?","options":[{"id":"a","text":"Inhibition of glucagon release"},{"id":"b","text":"Closure of ATP-sensitive K+ channels"},{"id":"c","text":"Activation of GLP-1 receptors"},{"id":"d","text":"Inhibition of hepatic glucose production"}],"answerId":"b","explanation":"Sulfonylureas close ATP-sensitive K+ channels on pancreatic beta cells, leading to depolarization and increased insulin secretion.","kind":"mechanism","origin":"ai"},{"id":"insulin-secretagogues~ai-1","moduleId":"insulin-secretagogues","stem":"Which of the following is a common adverse effect of insulin secretagogues?","options":[{"id":"a","text":"Diarrhea"},{"id":"b","text":"Hypoglycemia"},{"id":"c","text":"Weight loss"},{"id":"d","text":"Nausea"}],"answerId":"b","explanation":"Hypoglycemia is a class-defining adverse effect of insulin secretagogues due to their mechanism of increasing insulin secretion.","kind":"trap","origin":"ai"},{"id":"insulin-secretagogues~ai-2","moduleId":"insulin-secretagogues","stem":"In which condition are insulin secretagogues contraindicated?","options":[{"id":"a","text":"Type 2 Diabetes Mellitus"},{"id":"b","text":"Type 1 Diabetes Mellitus"},{"id":"c","text":"Gestational Diabetes"},{"id":"d","text":"Mild renal impairment"}],"answerId":"b","explanation":"Insulin secretagogues are ineffective in Type 1 Diabetes Mellitus due to the absence of functioning beta cells.","kind":"clinical","origin":"ai"},{"id":"insulin-secretagogues~ai-3","moduleId":"insulin-secretagogues","stem":"What is a potential consequence of using glyburide in a patient with renal impairment?","options":[{"id":"a","text":"Increased insulin sensitivity"},{"id":"b","text":"Prolonged hypoglycemia"},{"id":"c","text":"Enhanced glucagon secretion"},{"id":"d","text":"Increased glucose production"}],"answerId":"b","explanation":"Glyburide can accumulate in renal impairment, leading to an increased risk of prolonged hypoglycemia.","kind":"recall","origin":"ai"},{"id":"insulin-secretagogues~ai-4","moduleId":"insulin-secretagogues","stem":"Why are insulin secretagogues ineffective in treating Type 1 Diabetes Mellitus?","options":[{"id":"a","text":"They require oral administration"},{"id":"b","text":"They stimulate insulin release from non-functional beta cells"},{"id":"c","text":"They can only work in the presence of functioning beta cells"},{"id":"d","text":"They increase insulin resistance"}],"answerId":"c","explanation":"Insulin secretagogues require functioning beta cells to release insulin, which are absent in Type 1 Diabetes Mellitus.","kind":"trap","origin":"ai"},{"id":"insulin-secretagogues~ai-5","moduleId":"insulin-secretagogues","stem":"How do insulin secretagogues relate to the pathophysiology of Type 2 Diabetes Mellitus?","options":[{"id":"a","text":"They directly replace insulin"},{"id":"b","text":"They enhance insulin secretion from remaining beta cells"},{"id":"c","text":"They decrease insulin resistance"},{"id":"d","text":"They inhibit glucagon secretion"}],"answerId":"b","explanation":"Insulin secretagogues enhance insulin secretion from the remaining functional beta cells in Type 2 Diabetes Mellitus.","kind":"integration","linkedModuleIds":["hen1-diabetes-types-pathogenesis"],"origin":"ai"},{"id":"insulin-secretagogues~ai-6","moduleId":"insulin-secretagogues","stem":"Which of the following statements best describes the role of insulin secretagogues in diabetes management?","options":[{"id":"a","text":"They are the first-line treatment for all diabetes types"},{"id":"b","text":"They are used to stimulate insulin release in patients with functional beta cells"},{"id":"c","text":"They are effective in all stages of diabetes"},{"id":"d","text":"They replace the need for insulin therapy"}],"answerId":"b","explanation":"Insulin secretagogues are specifically used to stimulate insulin release in patients with functional beta cells, primarily in Type 2 Diabetes Mellitus.","kind":"integration","linkedModuleIds":["insulin-therapy-regimens"],"origin":"ai"}],"insulin-therapy-regimens":[{"id":"insulin-therapy-regimens~ai-0","moduleId":"insulin-therapy-regimens","stem":"What is the primary mechanism by which insulin decreases blood glucose levels?","options":[{"id":"a","text":"Increases hepatic glucose production"},{"id":"b","text":"Increases GLUT4 translocation"},{"id":"c","text":"Inhibits glucagon secretion"},{"id":"d","text":"Increases renal glucose excretion"}],"answerId":"b","explanation":"Insulin primarily decreases blood glucose by increasing GLUT4 translocation in muscle and adipose tissue, enhancing glucose uptake.","kind":"mechanism","origin":"ai"},{"id":"insulin-therapy-regimens~ai-1","moduleId":"insulin-therapy-regimens","stem":"Which of the following is a common clinical finding in a patient experiencing hypoglycemia?","options":[{"id":"a","text":"Weight gain"},{"id":"b","text":"Tachycardia"},{"id":"c","text":"Hyperventilation"},{"id":"d","text":"Polyuria"}],"answerId":"b","explanation":"Tachycardia is an adrenergic symptom that occurs during hypoglycemia due to the body's response to low glucose levels.","kind":"clinical","origin":"ai"},{"id":"insulin-therapy-regimens~ai-2","moduleId":"insulin-therapy-regimens","stem":"In type 2 diabetes, when should basal insulin be considered?","options":[{"id":"a","text":"When HbA1c is <7%"},{"id":"b","text":"When fasting glucose is normal"},{"id":"c","text":"When catabolism or severe hyperglycemia is present"},{"id":"d","text":"When weight loss occurs"}],"answerId":"c","explanation":"Basal insulin is indicated in T2DM when there is catabolism or severe hyperglycemia, particularly with HbA1c >10% or glucose >=300 mg/dL.","kind":"recall","origin":"ai"},{"id":"insulin-therapy-regimens~ai-3","moduleId":"insulin-therapy-regimens","stem":"What is a potential complication of repeated insulin injections at the same site?","options":[{"id":"a","text":"Hypoglycemia"},{"id":"b","text":"Lipohypertrophy"},{"id":"c","text":"Diabetic ketoacidosis"},{"id":"d","text":"Insulin resistance"}],"answerId":"b","explanation":"Repeated injections at the same site can lead to lipohypertrophy or lipoatrophy, causing lumps or dents in the skin.","kind":"recall","origin":"ai"},{"id":"insulin-therapy-regimens~ai-4","moduleId":"insulin-therapy-regimens","stem":"Which insulin regimen best describes the combination of basal and prandial insulin?","options":[{"id":"a","text":"Only basal insulin for all needs"},{"id":"b","text":"Only prandial insulin for all meals"},{"id":"c","text":"Basal insulin for fasting and prandial for meals"},{"id":"d","text":"Basal insulin for meals and prandial for fasting"}],"answerId":"c","explanation":"A physiologic insulin regimen combines basal insulin for fasting/inter-meal needs with prandial insulin for meals.","kind":"trap","origin":"ai"},{"id":"insulin-therapy-regimens~ai-5","moduleId":"insulin-therapy-regimens","stem":"In the context of insulin therapy, how does ketogenesis relate to insulin deficiency?","options":[{"id":"a","text":"Insulin promotes ketogenesis"},{"id":"b","text":"Insulin suppresses ketogenesis"},{"id":"c","text":"Ketogenesis is unrelated to insulin"},{"id":"d","text":"Insulin increases ketone utilization"}],"answerId":"b","explanation":"Insulin suppresses ketogenesis; its deficiency leads to increased ketone production, especially in uncontrolled diabetes.","kind":"integration","linkedModuleIds":["ketone-body-metabolism"],"origin":"ai"},{"id":"insulin-therapy-regimens~ai-6","moduleId":"insulin-therapy-regimens","stem":"How do insulin secretagogues work in relation to insulin therapy?","options":[{"id":"a","text":"They replace insulin therapy"},{"id":"b","text":"They enhance insulin secretion"},{"id":"c","text":"They inhibit insulin action"},{"id":"d","text":"They promote ketogenesis"}],"answerId":"b","explanation":"Insulin secretagogues stimulate the pancreas to secrete more insulin, complementing insulin therapy in diabetes management.","kind":"integration","linkedModuleIds":["insulin-secretagogues"],"origin":"ai"}],"incretin-based-therapy":[{"id":"incretin-based-therapy~ai-0","moduleId":"incretin-based-therapy","stem":"Which of the following is a common adverse effect of GLP-1 receptor agonists?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Nausea"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Weight gain"}],"answerId":"b","explanation":"Nausea is a common adverse effect associated with GLP-1 receptor agonists.","kind":"recall","origin":"ai"},{"id":"incretin-based-therapy~ai-1","moduleId":"incretin-based-therapy","stem":"What is the primary mechanism of action for DPP-4 inhibitors?","options":[{"id":"a","text":"Increase insulin secretion"},{"id":"b","text":"Enhance incretin signal"},{"id":"c","text":"Decrease glucagon secretion"},{"id":"d","text":"Inhibit gastric emptying"}],"answerId":"b","explanation":"DPP-4 inhibitors work by preventing the degradation of endogenous GLP-1, thereby enhancing the incretin signal.","kind":"mechanism","origin":"ai"},{"id":"incretin-based-therapy~ai-2","moduleId":"incretin-based-therapy","stem":"A patient on a GLP-1 receptor agonist presents with severe abdominal pain. What is the most likely concern?","options":[{"id":"a","text":"Medullary thyroid carcinoma"},{"id":"b","text":"Pancreatitis"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Acute kidney injury"}],"answerId":"b","explanation":"Severe abdominal pain in a patient on GLP-1 therapy raises suspicion for pancreatitis.","kind":"clinical","origin":"ai"},{"id":"incretin-based-therapy~ai-3","moduleId":"incretin-based-therapy","stem":"Which statement correctly differentiates GLP-1 receptor agonists from DPP-4 inhibitors?","options":[{"id":"a","text":"Both classes cause significant weight loss"},{"id":"b","text":"GLP-1 RAs are weight-neutral"},{"id":"c","text":"DPP-4 inhibitors can cause nausea"},{"id":"d","text":"GLP-1 RAs produce meaningful weight loss"}],"answerId":"d","explanation":"GLP-1 receptor agonists are known to produce meaningful weight loss, unlike DPP-4 inhibitors which are generally weight neutral.","kind":"trap","origin":"ai"},{"id":"incretin-based-therapy~ai-4","moduleId":"incretin-based-therapy","stem":"Which incretin-based therapy is most appropriate for a patient with type 2 diabetes and atherosclerotic cardiovascular disease?","options":[{"id":"a","text":"Sitagliptin"},{"id":"b","text":"Liraglutide"},{"id":"c","text":"Alogliptin"},{"id":"d","text":"Linagliptin"}],"answerId":"b","explanation":"Liraglutide is prioritized for patients with type 2 diabetes and cardiovascular risk due to its benefits.","kind":"recall","origin":"ai"},{"id":"incretin-based-therapy~ai-5","moduleId":"incretin-based-therapy","stem":"How does obesity contribute to insulin resistance, impacting incretin-based therapy efficacy?","options":[{"id":"a","text":"Increased GLP-1 secretion"},{"id":"b","text":"Decreased insulin receptor sensitivity"},{"id":"c","text":"Enhanced gastric emptying"},{"id":"d","text":"Increased glucagon secretion"}],"answerId":"b","explanation":"Obesity decreases insulin receptor sensitivity, which can affect the efficacy of incretin-based therapies.","kind":"integration","linkedModuleIds":["obesity-insulin-resistance"],"origin":"ai"},{"id":"incretin-based-therapy~ai-6","moduleId":"incretin-based-therapy","stem":"What role does C-peptide play in assessing the effectiveness of incretin-based therapies?","options":[{"id":"a","text":"Indicates glucagon levels"},{"id":"b","text":"Reflects endogenous insulin secretion"},{"id":"c","text":"Measures gastric emptying rate"},{"id":"d","text":"Assesses weight loss efficacy"}],"answerId":"b","explanation":"C-peptide levels reflect endogenous insulin secretion, which is important in evaluating the response to incretin-based therapies.","kind":"integration","linkedModuleIds":["hen1-insulin-synthesis-secretion"],"origin":"ai"}],"sglt2-alpha-glucosidase-selection":[{"id":"sglt2-alpha-glucosidase-selection~ai-0","moduleId":"sglt2-alpha-glucosidase-selection","stem":"What is the primary mechanism of action of SGLT2 inhibitors?","options":[{"id":"a","text":"Inhibition of intestinal carbohydrate absorption"},{"id":"b","text":"Inhibition of proximal-nephron glucose reabsorption"},{"id":"c","text":"Stimulation of insulin secretion"},{"id":"d","text":"Enhancement of glucagon secretion"}],"answerId":"b","explanation":"SGLT2 inhibitors primarily work by inhibiting glucose reabsorption in the proximal tubule of the kidney, leading to increased glucosuria.","kind":"mechanism","origin":"ai"},{"id":"sglt2-alpha-glucosidase-selection~ai-1","moduleId":"sglt2-alpha-glucosidase-selection","stem":"Which of the following is a common adverse effect of SGLT2 inhibitors?","options":[{"id":"a","text":"Hypoglycemia"},{"id":"b","text":"Genitourinary infections"},{"id":"c","text":"Weight gain"},{"id":"d","text":"Increased blood pressure"}],"answerId":"b","explanation":"SGLT2 inhibitors can cause genitourinary infections due to increased glucose in the urine, which promotes bacterial growth.","kind":"recall","origin":"ai"},{"id":"sglt2-alpha-glucosidase-selection~ai-2","moduleId":"sglt2-alpha-glucosidase-selection","stem":"A patient with type 2 diabetes and heart failure is being considered for medication. Which class of drugs should be prioritized?","options":[{"id":"a","text":"Sulfonylureas"},{"id":"b","text":"SGLT2 inhibitors"},{"id":"c","text":"DPP-4 inhibitors"},{"id":"d","text":"Alpha-glucosidase inhibitors"}],"answerId":"b","explanation":"In patients with heart failure, SGLT2 inhibitors are prioritized due to their proven cardiovascular benefits.","kind":"trap","origin":"ai"},{"id":"sglt2-alpha-glucosidase-selection~ai-3","moduleId":"sglt2-alpha-glucosidase-selection","stem":"What is the expected clinical finding after administering an alpha-glucosidase inhibitor?","options":[{"id":"a","text":"Increased insulin secretion"},{"id":"b","text":"Flatulence and diarrhea"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Weight gain"}],"answerId":"b","explanation":"Alpha-glucosidase inhibitors delay carbohydrate absorption, leading to fermentation in the colon and causing flatulence and diarrhea.","kind":"recall","origin":"ai"},{"id":"sglt2-alpha-glucosidase-selection~ai-4","moduleId":"sglt2-alpha-glucosidase-selection","stem":"In a patient with chronic kidney disease and type 2 diabetes, which medication class is most appropriate?","options":[{"id":"a","text":"Insulin secretagogues"},{"id":"b","text":"SGLT2 inhibitors"},{"id":"c","text":"Alpha-glucosidase inhibitors"},{"id":"d","text":"Thiazolidinediones"}],"answerId":"b","explanation":"SGLT2 inhibitors are beneficial in CKD patients with diabetes due to their renal protective effects and cardiovascular benefits.","kind":"integration","linkedModuleIds":["incretin-based-therapy"],"origin":"ai"},{"id":"sglt2-alpha-glucosidase-selection~ai-5","moduleId":"sglt2-alpha-glucosidase-selection","stem":"Which of the following medications is most effective for lowering postprandial glucose levels?","options":[{"id":"a","text":"Metformin"},{"id":"b","text":"SGLT2 inhibitors"},{"id":"c","text":"Alpha-glucosidase inhibitors"},{"id":"d","text":"GLP-1 receptor agonists"}],"answerId":"c","explanation":"Alpha-glucosidase inhibitors specifically target postprandial glucose by delaying carbohydrate absorption in the intestine.","kind":"recall","origin":"ai"},{"id":"sglt2-alpha-glucosidase-selection~ai-6","moduleId":"sglt2-alpha-glucosidase-selection","stem":"A patient with type 2 diabetes is experiencing dizziness and polyuria after starting a new medication. Which class of drugs is most likely responsible?","options":[{"id":"a","text":"SGLT2 inhibitors"},{"id":"b","text":"Insulin secretagogues"},{"id":"c","text":"DPP-4 inhibitors"},{"id":"d","text":"Thiazolidinediones"}],"answerId":"a","explanation":"Dizziness and polyuria are common side effects of SGLT2 inhibitors due to glucosuria and osmotic diuresis.","kind":"clinical","origin":"ai"},{"id":"sglt2-alpha-glucosidase-selection~ai-7","moduleId":"sglt2-alpha-glucosidase-selection","stem":"In a patient with type 2 diabetes and a history of atherosclerotic cardiovascular disease, which medication should be prioritized for treatment?","options":[{"id":"a","text":"Metformin"},{"id":"b","text":"SGLT2 inhibitors"},{"id":"c","text":"Insulin"},{"id":"d","text":"Sulfonylureas"}],"answerId":"b","explanation":"SGLT2 inhibitors are preferred in patients with ASCVD due to their cardiovascular outcome benefits.","kind":"integration","linkedModuleIds":["insulin-secretagogues"],"origin":"ai"}],"pectoral-girdle-bones":[{"id":"pectoral-girdle-bones~ai-0","moduleId":"pectoral-girdle-bones","stem":"What is the most common site of clavicle fracture?","options":[{"id":"a","text":"Medial end"},{"id":"b","text":"Lateral end"},{"id":"c","text":"Junction of middle and lateral thirds"},{"id":"d","text":"Sternal end"}],"answerId":"c","explanation":"The clavicle typically fractures at the junction of the middle and lateral thirds, which is its weakest point.","kind":"recall","origin":"ai"},{"id":"pectoral-girdle-bones~ai-1","moduleId":"pectoral-girdle-bones","stem":"Which structure is primarily responsible for holding the scapula to the thorax?","options":[{"id":"a","text":"Clavicle"},{"id":"b","text":"Sternum"},{"id":"c","text":"Muscles"},{"id":"d","text":"Ribs"}],"answerId":"c","explanation":"The scapula is held to the thorax primarily by muscles, as there is no bony articulation.","kind":"recall","origin":"ai"},{"id":"pectoral-girdle-bones~ai-2","moduleId":"pectoral-girdle-bones","stem":"During a fall on the shoulder, which physical exam finding is most indicative of a clavicle fracture?","options":[{"id":"a","text":"Bump at the middle-third clavicle"},{"id":"b","text":"Pain over the acromion"},{"id":"c","text":"Limited shoulder abduction"},{"id":"d","text":"Swelling around the glenoid cavity"}],"answerId":"a","explanation":"A bump at the middle-third clavicle is a classic sign of a clavicle fracture.","kind":"recall","origin":"ai"},{"id":"pectoral-girdle-bones~ai-3","moduleId":"pectoral-girdle-bones","stem":"What anatomical feature of the scapula contributes to its mobility but also to its instability?","options":[{"id":"a","text":"Glenoid cavity"},{"id":"b","text":"Coracoid process"},{"id":"c","text":"Scapular spine"},{"id":"d","text":"Acromion"}],"answerId":"a","explanation":"The shallow glenoid cavity allows for greater mobility but also increases instability of the shoulder joint.","kind":"mechanism","origin":"ai"},{"id":"pectoral-girdle-bones~ai-4","moduleId":"pectoral-girdle-bones","stem":"A patient presents with a fractured clavicle. Which muscle is responsible for pulling the medial fragment upwards?","options":[{"id":"a","text":"Pectoralis major"},{"id":"b","text":"Sternocleidomastoid"},{"id":"c","text":"Trapezius"},{"id":"d","text":"Deltoid"}],"answerId":"b","explanation":"The sternocleidomastoid muscle pulls the medial fragment of the clavicle upwards after a fracture.","kind":"mechanism","origin":"ai"},{"id":"pectoral-girdle-bones~ai-5","moduleId":"pectoral-girdle-bones","stem":"How does the anatomy of the pectoral girdle relate to the function of the brachial plexus?","options":[{"id":"a","text":"It provides structural support to the plexus"},{"id":"b","text":"It protects the plexus from injury"},{"id":"c","text":"It facilitates nerve branching from the plexus"},{"id":"d","text":"It anchors the plexus to the thorax"}],"answerId":"c","explanation":"The pectoral girdle's anatomy allows for the branching of the brachial plexus, facilitating innervation of the upper limb.","kind":"integration","linkedModuleIds":["axilla-brachial-plexus"],"origin":"ai"},{"id":"pectoral-girdle-bones~ai-6","moduleId":"pectoral-girdle-bones","stem":"Which muscle's balance is crucial for maintaining scapular position and function?","options":[{"id":"a","text":"Serratus anterior"},{"id":"b","text":"Pectoralis major"},{"id":"c","text":"Latissimus dorsi"},{"id":"d","text":"Rhomboids"}],"answerId":"a","explanation":"The serratus anterior muscle is essential for stabilizing the scapula against the thoracic wall.","kind":"trap","origin":"ai"},{"id":"pectoral-girdle-bones~ai-7","moduleId":"pectoral-girdle-bones","stem":"What is the relationship between the pectoral girdle and the hip joint during upper limb and lower limb coordination?","options":[{"id":"a","text":"Both girdles are stabilized by ligaments"},{"id":"b","text":"Muscle imbalances affect both girdles similarly"},{"id":"c","text":"Both girdles allow for similar ranges of motion"},{"id":"d","text":"They are connected via the axial skeleton"}],"answerId":"b","explanation":"Muscle imbalances can affect the stability and function of both the pectoral girdle and the hip joint.","kind":"integration","linkedModuleIds":["lower-limb-bones-hip-joint"],"origin":"ai"}],"arm-compartments-humerus-fractures":[{"id":"arm-compartments-humerus-fractures~ai-0","moduleId":"arm-compartments-humerus-fractures","stem":"Which nerve is most likely injured in a midshaft humeral fracture?","options":[{"id":"a","text":"Axillary nerve"},{"id":"b","text":"Musculocutaneous nerve"},{"id":"c","text":"Radial nerve"},{"id":"d","text":"Ulnar nerve"}],"answerId":"c","explanation":"The radial nerve is located in the radial groove of the humerus and is at risk during midshaft fractures.","kind":"recall","origin":"ai"},{"id":"arm-compartments-humerus-fractures~ai-1","moduleId":"arm-compartments-humerus-fractures","stem":"What is the primary blood supply to the anterior compartment of the arm?","options":[{"id":"a","text":"Radial artery"},{"id":"b","text":"Ulnar artery"},{"id":"c","text":"Brachial artery"},{"id":"d","text":"Profunda brachii artery"}],"answerId":"c","explanation":"The brachial artery is the main blood supply to the anterior compartment, which includes muscles like biceps brachii.","kind":"recall","origin":"ai"},{"id":"arm-compartments-humerus-fractures~ai-2","moduleId":"arm-compartments-humerus-fractures","stem":"A patient presents with wrist drop after a humeral fracture. Which nerve is affected?","options":[{"id":"a","text":"Median nerve"},{"id":"b","text":"Ulnar nerve"},{"id":"c","text":"Radial nerve"},{"id":"d","text":"Musculocutaneous nerve"}],"answerId":"c","explanation":"Wrist drop indicates radial nerve injury, commonly associated with midshaft humeral fractures.","kind":"clinical","origin":"ai"},{"id":"arm-compartments-humerus-fractures~ai-3","moduleId":"arm-compartments-humerus-fractures","stem":"Which muscle is primarily responsible for forearm flexion in all positions?","options":[{"id":"a","text":"Biceps brachii"},{"id":"b","text":"Brachialis"},{"id":"c","text":"Coracobrachialis"},{"id":"d","text":"Triceps brachii"}],"answerId":"b","explanation":"The brachialis is the main flexor of the forearm, functioning regardless of forearm position.","kind":"recall","origin":"ai"},{"id":"arm-compartments-humerus-fractures~ai-4","moduleId":"arm-compartments-humerus-fractures","stem":"What is the risk associated with a supracondylar humeral fracture?","options":[{"id":"a","text":"Ulnar nerve injury"},{"id":"b","text":"Volkmann ischemic contracture"},{"id":"c","text":"Wrist drop"},{"id":"d","text":"Shoulder dislocation"}],"answerId":"b","explanation":"Supracondylar fractures can injure the brachial artery, leading to Volkmann ischemic contracture.","kind":"trap","origin":"ai"},{"id":"arm-compartments-humerus-fractures~ai-5","moduleId":"arm-compartments-humerus-fractures","stem":"Which structure is at risk during a fracture at the surgical neck of the humerus?","options":[{"id":"a","text":"Radial nerve"},{"id":"b","text":"Brachial artery"},{"id":"c","text":"Axillary nerve"},{"id":"d","text":"Musculocutaneous nerve"}],"answerId":"c","explanation":"The axillary nerve is at risk during surgical neck fractures, leading to deltoid weakness.","kind":"recall","origin":"ai"},{"id":"arm-compartments-humerus-fractures~ai-6","moduleId":"arm-compartments-humerus-fractures","stem":"How does a midshaft humeral fracture affect the radial nerve?","options":[{"id":"a","text":"Causes wrist drop"},{"id":"b","text":"Leads to numbness in the hand"},{"id":"c","text":"Affects forearm supination"},{"id":"d","text":"Causes weakness in elbow extension"}],"answerId":"a","explanation":"A midshaft humeral fracture can injure the radial nerve, resulting in wrist drop due to loss of extensor function.","kind":"mechanism","origin":"ai"},{"id":"arm-compartments-humerus-fractures~ai-7","moduleId":"arm-compartments-humerus-fractures","stem":"A child presents with a humeral fracture. Which classification system is most relevant for understanding the injury?","options":[{"id":"a","text":"Salter-Harris classification"},{"id":"b","text":"AO classification"},{"id":"c","text":"Garden classification"},{"id":"d","text":"Neer classification"}],"answerId":"a","explanation":"The Salter-Harris classification is crucial for pediatric fractures as it describes growth plate involvement.","kind":"integration","linkedModuleIds":["fracture-classification"],"origin":"ai"},{"id":"arm-compartments-humerus-fractures~ai-8","moduleId":"arm-compartments-humerus-fractures","stem":"In assessing a humeral fracture, which aspect of the cubital fossa is important for surgical intervention?","options":[{"id":"a","text":"Brachial artery location"},{"id":"b","text":"Median nerve position"},{"id":"c","text":"Ulnar nerve pathway"},{"id":"d","text":"Radial nerve trajectory"}],"answerId":"a","explanation":"Understanding the brachial artery's location in the cubital fossa is critical for managing humeral fractures.","kind":"integration","linkedModuleIds":["cubital-fossa"],"origin":"ai"}],"metformin-thiazolidinediones":[{"id":"metformin-thiazolidinediones~ai-0","moduleId":"metformin-thiazolidinediones","stem":"What is the primary mechanism of action of metformin in treating type 2 diabetes?","options":[{"id":"a","text":"Increases insulin secretion from the pancreas"},{"id":"b","text":"Inhibits hepatic gluconeogenesis"},{"id":"c","text":"Stimulates glucose uptake in the intestines"},{"id":"d","text":"Increases glucose absorption in the kidneys"}],"answerId":"b","explanation":"Metformin primarily inhibits hepatic gluconeogenesis, which lowers blood glucose levels.","kind":"mechanism","origin":"ai"},{"id":"metformin-thiazolidinediones~ai-1","moduleId":"metformin-thiazolidinediones","stem":"Which of the following is a common side effect of metformin?","options":[{"id":"a","text":"Weight gain"},{"id":"b","text":"Hypoglycemia"},{"id":"c","text":"Diarrhea"},{"id":"d","text":"Fluid retention"}],"answerId":"c","explanation":"Diarrhea is a common gastrointestinal side effect associated with metformin use.","kind":"recall","origin":"ai"},{"id":"metformin-thiazolidinediones~ai-2","moduleId":"metformin-thiazolidinediones","stem":"A patient on long-term metformin therapy presents with macrocytic anemia. What is the most likely cause?","options":[{"id":"a","text":"Iron deficiency"},{"id":"b","text":"Folate deficiency"},{"id":"c","text":"Vitamin B12 deficiency"},{"id":"d","text":"Chronic kidney disease"}],"answerId":"c","explanation":"Long-term use of metformin can lead to vitamin B12 deficiency, resulting in macrocytic anemia.","kind":"clinical","origin":"ai"},{"id":"metformin-thiazolidinediones~ai-3","moduleId":"metformin-thiazolidinediones","stem":"Which of the following statements about thiazolidinediones (TZDs) is true?","options":[{"id":"a","text":"They are safe in patients with heart failure"},{"id":"b","text":"They cause weight loss"},{"id":"c","text":"They activate PPAR-gamma to improve insulin sensitivity"},{"id":"d","text":"They are primarily used for type 1 diabetes"}],"answerId":"c","explanation":"TZDs activate PPAR-gamma, which improves insulin sensitivity, but they should be avoided in heart failure due to fluid retention.","kind":"trap","origin":"ai"},{"id":"metformin-thiazolidinediones~ai-4","moduleId":"metformin-thiazolidinediones","stem":"In the context of gluconeogenesis, which process is directly inhibited by metformin?","options":[{"id":"a","text":"Cori cycle"},{"id":"b","text":"Alanine cycle"},{"id":"c","text":"Glycogenolysis"},{"id":"d","text":"Glycolysis"}],"answerId":"a","explanation":"Metformin inhibits hepatic gluconeogenesis, which is closely related to the Cori cycle.","kind":"integration","linkedModuleIds":["gluconeogenesis-cori-alanine"],"origin":"ai"},{"id":"metformin-thiazolidinediones~ai-5","moduleId":"metformin-thiazolidinediones","stem":"What is a significant risk associated with the use of TZDs in patients with a history of heart failure?","options":[{"id":"a","text":"Increased insulin secretion"},{"id":"b","text":"Fluid retention leading to worsening heart failure"},{"id":"c","text":"Hypoglycemia due to increased insulin sensitivity"},{"id":"d","text":"Increased risk of lactic acidosis"}],"answerId":"b","explanation":"TZDs can cause fluid retention, which may worsen heart failure symptoms.","kind":"integration","linkedModuleIds":["hfi-metabolic-complications"],"origin":"ai"},{"id":"metformin-thiazolidinediones~ai-6","moduleId":"metformin-thiazolidinediones","stem":"What is the recommended eGFR threshold for avoiding metformin use?","options":[{"id":"a","text":"<15 mL/min"},{"id":"b","text":"<30 mL/min"},{"id":"c","text":"<45 mL/min"},{"id":"d","text":"<60 mL/min"}],"answerId":"b","explanation":"Metformin should be avoided in patients with an eGFR <30 mL/min due to the risk of lactic acidosis.","kind":"recall","origin":"ai"},{"id":"metformin-thiazolidinediones~ai-7","moduleId":"metformin-thiazolidinediones","stem":"Which of the following is a contraindication for the use of TZDs?","options":[{"id":"a","text":"Type 2 diabetes"},{"id":"b","text":"Obesity"},{"id":"c","text":"Heart failure"},{"id":"d","text":"Insulin resistance"}],"answerId":"c","explanation":"TZDs should be avoided in patients with heart failure due to the risk of fluid retention.","kind":"trap","origin":"ai"}],"radius-ulna-carpals-fractures":[{"id":"radius-ulna-carpals-fractures~ai-0","moduleId":"radius-ulna-carpals-fractures","stem":"What is the most common carpal bone to fracture due to a fall on an outstretched hand?","options":[{"id":"a","text":"Lunate"},{"id":"b","text":"Scaphoid"},{"id":"c","text":"Triquetrum"},{"id":"d","text":"Pisiform"}],"answerId":"b","explanation":"The scaphoid is the most commonly fractured carpal bone, particularly from a fall on an outstretched hand.","kind":"recall","origin":"ai"},{"id":"radius-ulna-carpals-fractures~ai-1","moduleId":"radius-ulna-carpals-fractures","stem":"Which fracture is characterized by dorsal displacement of the distal radius?","options":[{"id":"a","text":"Smith fracture"},{"id":"b","text":"Colles fracture"},{"id":"c","text":"Scaphoid fracture"},{"id":"d","text":"Galeazzi fracture"}],"answerId":"b","explanation":"A Colles fracture is defined by dorsal displacement of the distal radius, often resulting in a 'dinner-fork' deformity.","kind":"recall","origin":"ai"},{"id":"radius-ulna-carpals-fractures~ai-2","moduleId":"radius-ulna-carpals-fractures","stem":"What is the mechanism of injury for a Colles fracture?","options":[{"id":"a","text":"Direct blow to the wrist"},{"id":"b","text":"Fall on a flexed wrist"},{"id":"c","text":"Fall on an outstretched hand"},{"id":"d","text":"Twisting injury of the wrist"}],"answerId":"c","explanation":"A Colles fracture typically occurs from falling on an outstretched hand (FOOSH).","kind":"mechanism","origin":"ai"},{"id":"radius-ulna-carpals-fractures~ai-3","moduleId":"radius-ulna-carpals-fractures","stem":"A patient presents with tenderness in the anatomical snuffbox after a fall. What should be the next step in management?","options":[{"id":"a","text":"Immediate surgery"},{"id":"b","text":"Wrist immobilization and re-imaging"},{"id":"c","text":"Pain management only"},{"id":"d","text":"Observation without intervention"}],"answerId":"b","explanation":"Tenderness in the anatomical snuffbox suggests a scaphoid fracture, which may not be visible on initial X-rays; immobilization and re-imaging are crucial.","kind":"clinical","origin":"ai"},{"id":"radius-ulna-carpals-fractures~ai-4","moduleId":"radius-ulna-carpals-fractures","stem":"What complication is associated with a scaphoid fracture if not properly managed?","options":[{"id":"a","text":"Nerve compression syndrome"},{"id":"b","text":"Avascular necrosis"},{"id":"c","text":"Joint dislocation"},{"id":"d","text":"Tendon rupture"}],"answerId":"b","explanation":"Scaphoid fractures can lead to avascular necrosis of the proximal fragment due to its unique blood supply.","kind":"trap","origin":"ai"},{"id":"radius-ulna-carpals-fractures~ai-5","moduleId":"radius-ulna-carpals-fractures","stem":"A patient with a distal radius fracture presents with median nerve symptoms. What is the likely cause?","options":[{"id":"a","text":"Fracture of the scaphoid"},{"id":"b","text":"Lunate dislocation"},{"id":"c","text":"Colles fracture"},{"id":"d","text":"Smith fracture"}],"answerId":"b","explanation":"Lunate dislocation can compress the median nerve, leading to acute carpal tunnel syndrome after wrist trauma.","kind":"clinical","origin":"ai"},{"id":"radius-ulna-carpals-fractures~ai-6","moduleId":"radius-ulna-carpals-fractures","stem":"How does a Galeazzi fracture differ from a Monteggia fracture?","options":[{"id":"a","text":"Galeazzi involves the ulna; Monteggia involves the radius"},{"id":"b","text":"Galeazzi involves the distal radius; Monteggia involves the proximal ulna"},{"id":"c","text":"Galeazzi is a wrist fracture; Monteggia is a forearm fracture"},{"id":"d","text":"Galeazzi is a stable fracture; Monteggia is unstable"}],"answerId":"b","explanation":"A Galeazzi fracture involves a fracture of the distal radius with dislocation of the distal radioulnar joint, whereas a Monteggia fracture involves a fracture of the proximal ulna with dislocation of the radial head.","kind":"integration","linkedModuleIds":["fracture-classification"],"origin":"ai"},{"id":"radius-ulna-carpals-fractures~ai-7","moduleId":"radius-ulna-carpals-fractures","stem":"Which of the following findings would suggest a scaphoid fracture in a patient with wrist trauma?","options":[{"id":"a","text":"Dorsal wrist swelling"},{"id":"b","text":"Tenderness over the anatomical snuffbox"},{"id":"c","text":"Palmar wrist swelling"},{"id":"d","text":"Inability to extend fingers"}],"answerId":"b","explanation":"Tenderness over the anatomical snuffbox is a classic sign of a scaphoid fracture following wrist trauma.","kind":"integration","linkedModuleIds":["forearm-extensor-compartment-snuffbox"],"origin":"ai"}],"shoulder-region-rotator-cuff":[{"id":"shoulder-region-rotator-cuff~ai-0","moduleId":"shoulder-region-rotator-cuff","stem":"Which muscle initiates the first 15 degrees of shoulder abduction?","options":[{"id":"a","text":"Deltoid"},{"id":"b","text":"Supraspinatus"},{"id":"c","text":"Infraspinatus"},{"id":"d","text":"Teres minor"}],"answerId":"b","explanation":"The supraspinatus is responsible for initiating the first 0-15° of abduction before the deltoid takes over.","kind":"recall","origin":"ai"},{"id":"shoulder-region-rotator-cuff~ai-1","moduleId":"shoulder-region-rotator-cuff","stem":"What is the most common clinical finding in a supraspinatus tear?","options":[{"id":"a","text":"Weak lateral rotation"},{"id":"b","text":"Painful arc of abduction"},{"id":"c","text":"Flattened shoulder contour"},{"id":"d","text":"Loss of sensation over the arm"}],"answerId":"b","explanation":"A painful arc of 60-120° of abduction is characteristic of supraspinatus impingement or tear.","kind":"recall","origin":"ai"},{"id":"shoulder-region-rotator-cuff~ai-2","moduleId":"shoulder-region-rotator-cuff","stem":"What nerve is most commonly injured in a surgical neck fracture of the humerus?","options":[{"id":"a","text":"Radial nerve"},{"id":"b","text":"Median nerve"},{"id":"c","text":"Musculocutaneous nerve"},{"id":"d","text":"Axillary nerve"}],"answerId":"d","explanation":"The axillary nerve is commonly injured in surgical neck fractures, leading to deltoid paralysis and sensory loss.","kind":"recall","origin":"ai"},{"id":"shoulder-region-rotator-cuff~ai-3","moduleId":"shoulder-region-rotator-cuff","stem":"What is the primary function of the rotator cuff muscles?","options":[{"id":"a","text":"Power shoulder abduction"},{"id":"b","text":"Stabilize the humeral head"},{"id":"c","text":"Medial rotation of the arm"},{"id":"d","text":"Flexion of the shoulder"}],"answerId":"b","explanation":"The rotator cuff muscles dynamically stabilize the humeral head in the shallow glenoid cavity.","kind":"mechanism","origin":"ai"},{"id":"shoulder-region-rotator-cuff~ai-4","moduleId":"shoulder-region-rotator-cuff","stem":"A patient presents with a flattened shoulder contour and loss of sensation over the lower deltoid area after an anterior shoulder dislocation. Which nerve is likely injured?","options":[{"id":"a","text":"Suprascapular nerve"},{"id":"b","text":"Axillary nerve"},{"id":"c","text":"Radial nerve"},{"id":"d","text":"Musculocutaneous nerve"}],"answerId":"b","explanation":"The axillary nerve is injured in anterior shoulder dislocations, causing deltoid paralysis and sensory loss in the 'regimental badge' area.","kind":"clinical","origin":"ai"},{"id":"shoulder-region-rotator-cuff~ai-5","moduleId":"shoulder-region-rotator-cuff","stem":"In a patient with a humeral shaft fracture, which muscle is most likely to be affected due to radial nerve injury?","options":[{"id":"a","text":"Deltoid"},{"id":"b","text":"Supraspinatus"},{"id":"c","text":"Infraspinatus"},{"id":"d","text":"Teres major"}],"answerId":"a","explanation":"The radial nerve innervates the deltoid indirectly through the axillary nerve, and its injury can lead to loss of shoulder abduction.","kind":"integration","linkedModuleIds":["arm-compartments-humerus-fractures"],"origin":"ai"},{"id":"shoulder-region-rotator-cuff~ai-6","moduleId":"shoulder-region-rotator-cuff","stem":"Which anatomical structure is primarily responsible for the painful arc syndrome in shoulder abduction?","options":[{"id":"a","text":"Coraco-acromial arch"},{"id":"b","text":"Subacromial bursa"},{"id":"c","text":"Glenoid labrum"},{"id":"d","text":"Rotator cuff tendons"}],"answerId":"a","explanation":"The coraco-acromial arch can impinge on the supraspinatus tendon during the painful arc of abduction.","kind":"trap","origin":"ai"},{"id":"shoulder-region-rotator-cuff~ai-7","moduleId":"shoulder-region-rotator-cuff","stem":"How does the anatomy of the shoulder region relate to lymphatic drainage in breast cancer?","options":[{"id":"a","text":"Lymphatics drain to the axillary nodes"},{"id":"b","text":"Lymphatics drain to the cervical nodes"},{"id":"c","text":"Lymphatics drain to the thoracic duct"},{"id":"d","text":"Lymphatics drain to the subclavian vein"}],"answerId":"a","explanation":"The lymphatic drainage from the breast primarily goes to the axillary lymph nodes, which are closely associated with the shoulder region.","kind":"integration","linkedModuleIds":["hrp1-breast-gross-lymphatic-anatomy"],"origin":"ai"}],"axilla-brachial-plexus":[{"id":"axilla-brachial-plexus~ai-0","moduleId":"axilla-brachial-plexus","stem":"Which structure divides the axillary artery into three parts?","options":[{"id":"a","text":"Pectoralis major"},{"id":"b","text":"Pectoralis minor"},{"id":"c","text":"Subscapularis"},{"id":"d","text":"Serratus anterior"}],"answerId":"b","explanation":"The axillary artery is divided into three parts by the pectoralis minor.","kind":"recall","origin":"ai"},{"id":"axilla-brachial-plexus~ai-1","moduleId":"axilla-brachial-plexus","stem":"What is the clinical presentation of Erb-Duchenne palsy?","options":[{"id":"a","text":"Clawed hand"},{"id":"b","text":"Adducted, medially rotated arm, pronated forearm"},{"id":"c","text":"Winging of the scapula"},{"id":"d","text":"Loss of sensation in the hand"}],"answerId":"b","explanation":"Erb-Duchenne palsy results in an adducted, medially rotated arm and a pronated forearm, often described as a 'waiter's tip' posture.","kind":"clinical","origin":"ai"},{"id":"axilla-brachial-plexus~ai-2","moduleId":"axilla-brachial-plexus","stem":"Which nerve is most likely affected in a patient with winged scapula after axillary lymph node dissection?","options":[{"id":"a","text":"Musculocutaneous nerve"},{"id":"b","text":"Long thoracic nerve"},{"id":"c","text":"Axillary nerve"},{"id":"d","text":"Thoracodorsal nerve"}],"answerId":"b","explanation":"The long thoracic nerve is responsible for innervating the serratus anterior, and its injury leads to winged scapula.","kind":"trap","origin":"ai"},{"id":"axilla-brachial-plexus~ai-3","moduleId":"axilla-brachial-plexus","stem":"Which of the following correctly describes Klumpke palsy?","options":[{"id":"a","text":"Upper trunk injury causing 'waiter's tip'"},{"id":"b","text":"Lower trunk injury causing claw hand"},{"id":"c","text":"Medial cord injury causing loss of elbow flexion"},{"id":"d","text":"Posterior cord injury causing wrist drop"}],"answerId":"b","explanation":"Klumpke palsy is a lower trunk injury (C8-T1) leading to intrinsic hand muscle loss, resulting in a claw hand.","kind":"trap","origin":"ai"},{"id":"axilla-brachial-plexus~ai-4","moduleId":"axilla-brachial-plexus","stem":"What is the primary function of the brachial plexus?","options":[{"id":"a","text":"Supply blood to the upper limb"},{"id":"b","text":"Provide sensory innervation to the hand"},{"id":"c","text":"Transmit motor signals to shoulder muscles"},{"id":"d","text":"Route nerves to the upper limb"}],"answerId":"d","explanation":"The brachial plexus routes nerves to the upper limb, providing motor and sensory innervation.","kind":"mechanism","origin":"ai"},{"id":"axilla-brachial-plexus~ai-5","moduleId":"axilla-brachial-plexus","stem":"How does the anatomy of the pectoral girdle relate to the brachial plexus?","options":[{"id":"a","text":"It provides structural support for the brachial plexus"},{"id":"b","text":"It is the site of brachial plexus injury"},{"id":"c","text":"It influences the vascular supply to the plexus"},{"id":"d","text":"It affects the range of motion of the upper limb"}],"answerId":"a","explanation":"The pectoral girdle's anatomy provides structural support and is crucial for the positioning of the brachial plexus.","kind":"integration","linkedModuleIds":["pectoral-girdle-bones"],"origin":"ai"},{"id":"axilla-brachial-plexus~ai-6","moduleId":"axilla-brachial-plexus","stem":"Which spinal nerves contribute to the formation of the brachial plexus?","options":[{"id":"a","text":"C1-C4"},{"id":"b","text":"C5-T1"},{"id":"c","text":"T2-T12"},{"id":"d","text":"L1-L5"}],"answerId":"b","explanation":"The brachial plexus is formed from the ventral rami of spinal nerves C5 to T1.","kind":"recall","origin":"ai"},{"id":"axilla-brachial-plexus~ai-7","moduleId":"axilla-brachial-plexus","stem":"What is the relationship between dermatomes and the brachial plexus?","options":[{"id":"a","text":"Dermatomes are unrelated to the brachial plexus"},{"id":"b","text":"Dermatomes are mapped to the roots of the brachial plexus"},{"id":"c","text":"Dermatomes only apply to the lower limb"},{"id":"d","text":"Dermatomes are only relevant for sensory nerves"}],"answerId":"b","explanation":"Dermatomes correspond to the sensory innervation provided by the roots of the brachial plexus.","kind":"integration","linkedModuleIds":["dermatomes-spinal-nerves"],"origin":"ai"}],"superficial-back-pectoral-muscles":[{"id":"superficial-back-pectoral-muscles~ai-0","moduleId":"superficial-back-pectoral-muscles","stem":"Which nerve is primarily responsible for innervating the serratus anterior muscle?","options":[{"id":"a","text":"Long thoracic nerve"},{"id":"b","text":"Thoracodorsal nerve"},{"id":"c","text":"Dorsal scapular nerve"},{"id":"d","text":"Medial pectoral nerve"}],"answerId":"a","explanation":"The long thoracic nerve (C5-C7) innervates the serratus anterior, which is crucial for scapular protraction and upward rotation.","kind":"recall","origin":"ai"},{"id":"superficial-back-pectoral-muscles~ai-1","moduleId":"superficial-back-pectoral-muscles","stem":"A patient presents with a winged scapula when pushing against a wall. Which nerve is likely injured?","options":[{"id":"a","text":"Accessory nerve"},{"id":"b","text":"Long thoracic nerve"},{"id":"c","text":"Dorsal scapular nerve"},{"id":"d","text":"Thoracodorsal nerve"}],"answerId":"b","explanation":"Injury to the long thoracic nerve causes serratus anterior weakness, leading to winging of the scapula.","kind":"clinical","origin":"ai"},{"id":"superficial-back-pectoral-muscles~ai-2","moduleId":"superficial-back-pectoral-muscles","stem":"Which muscle is primarily responsible for the upward rotation of the scapula during arm abduction above 90°?","options":[{"id":"a","text":"Trapezius"},{"id":"b","text":"Rhomboids"},{"id":"c","text":"Serratus anterior"},{"id":"d","text":"Pectoralis major"}],"answerId":"c","explanation":"The serratus anterior is essential for upward rotation of the scapula, allowing for full arm abduction.","kind":"mechanism","origin":"ai"},{"id":"superficial-back-pectoral-muscles~ai-3","moduleId":"superficial-back-pectoral-muscles","stem":"A patient has difficulty elevating their arm and exhibits a drooping shoulder. Which muscle is most likely weakened?","options":[{"id":"a","text":"Serratus anterior"},{"id":"b","text":"Trapezius"},{"id":"c","text":"Pectoralis major"},{"id":"d","text":"Latissimus dorsi"}],"answerId":"b","explanation":"Weakness of the trapezius muscle, innervated by CN XI, leads to shoulder droop and difficulty in arm elevation.","kind":"clinical","origin":"ai"},{"id":"superficial-back-pectoral-muscles~ai-4","moduleId":"superficial-back-pectoral-muscles","stem":"What is the primary action of the pectoralis major muscle?","options":[{"id":"a","text":"Adducts and medially rotates the arm"},{"id":"b","text":"Protracts the scapula"},{"id":"c","text":"Elevates the scapula"},{"id":"d","text":"Extends the arm"}],"answerId":"a","explanation":"The pectoralis major primarily adducts and medially rotates the arm.","kind":"recall","origin":"ai"},{"id":"superficial-back-pectoral-muscles~ai-5","moduleId":"superficial-back-pectoral-muscles","stem":"Which of the following statements about serratus anterior function is true?","options":[{"id":"a","text":"It retracts the scapula"},{"id":"b","text":"It elevates the scapula"},{"id":"c","text":"It protracts the scapula"},{"id":"d","text":"It rotates the scapula downward"}],"answerId":"c","explanation":"The serratus anterior protracts the scapula and holds it against the thorax.","kind":"trap","origin":"ai"},{"id":"superficial-back-pectoral-muscles~ai-6","moduleId":"superficial-back-pectoral-muscles","stem":"How does the pectoralis minor contribute to scapular stability?","options":[{"id":"a","text":"By elevating the scapula"},{"id":"b","text":"By stabilizing and depressing the scapula"},{"id":"c","text":"By protracting the scapula"},{"id":"d","text":"By rotating the scapula upward"}],"answerId":"b","explanation":"The pectoralis minor stabilizes and depresses the scapula, contributing to overall scapular stability.","kind":"mechanism","origin":"ai"},{"id":"superficial-back-pectoral-muscles~ai-7","moduleId":"superficial-back-pectoral-muscles","stem":"In a patient with a long thoracic nerve injury, which of the following findings would you expect?","options":[{"id":"a","text":"Drooping shoulder"},{"id":"b","text":"Inability to abduct arm past 90°"},{"id":"c","text":"Medial scapular border lifts off the thorax"},{"id":"d","text":"Weakness in shoulder flexion"}],"answerId":"c","explanation":"A long thoracic nerve injury leads to serratus anterior weakness, causing the medial scapular border to lift off the thorax.","kind":"clinical","origin":"ai"},{"id":"superficial-back-pectoral-muscles~ai-8","moduleId":"superficial-back-pectoral-muscles","stem":"How does the function of the serratus anterior relate to the brachial plexus?","options":[{"id":"a","text":"It is innervated by the medial cord"},{"id":"b","text":"It is innervated by the long thoracic nerve from C5-C7"},{"id":"c","text":"It is involved in shoulder flexion"},{"id":"d","text":"It stabilizes the humerus during adduction"}],"answerId":"b","explanation":"The serratus anterior is innervated by the long thoracic nerve, which is derived from the brachial plexus (C5-C7).","kind":"integration","linkedModuleIds":["axilla-brachial-plexus"],"origin":"ai"},{"id":"superficial-back-pectoral-muscles~ai-9","moduleId":"superficial-back-pectoral-muscles","stem":"Which muscle's action is crucial for the upward rotation of the scapula during arm elevation, linking it to the pectoral girdle anatomy?","options":[{"id":"a","text":"Trapezius"},{"id":"b","text":"Rhomboids"},{"id":"c","text":"Serratus anterior"},{"id":"d","text":"Pectoralis major"}],"answerId":"c","explanation":"The serratus anterior's action is essential for upward rotation of the scapula, which is a key function of the pectoral girdle.","kind":"integration","linkedModuleIds":["pectoral-girdle-bones"],"origin":"ai"}],"vertebral-column-joints-discs":[{"id":"vertebral-column-joints-discs~ai-0","moduleId":"vertebral-column-joints-discs","stem":"Which structure primarily absorbs shock in the intervertebral disc?","options":[{"id":"a","text":"Annulus fibrosus"},{"id":"b","text":"Nucleus pulposus"},{"id":"c","text":"Anterior longitudinal ligament"},{"id":"d","text":"Posterior longitudinal ligament"}],"answerId":"b","explanation":"The nucleus pulposus is a gelatinous core that acts as a shock absorber within the intervertebral disc.","kind":"recall","origin":"ai"},{"id":"vertebral-column-joints-discs~ai-1","moduleId":"vertebral-column-joints-discs","stem":"What is the most common site for lumbar disc herniation?","options":[{"id":"a","text":"L2–L3"},{"id":"b","text":"L3–L4"},{"id":"c","text":"L4–L5"},{"id":"d","text":"L5–S1"}],"answerId":"c","explanation":"The L4–L5 and L5–S1 levels are the most common sites for lumbar disc herniation, often leading to sciatica.","kind":"recall","origin":"ai"},{"id":"vertebral-column-joints-discs~ai-2","moduleId":"vertebral-column-joints-discs","stem":"A patient presents with low-back pain radiating down the posterior leg. Which nerve root is likely affected if the herniation is at L4–L5?","options":[{"id":"a","text":"L4"},{"id":"b","text":"L5"},{"id":"c","text":"S1"},{"id":"d","text":"S2"}],"answerId":"b","explanation":"An L4–L5 disc herniation typically compresses the L5 nerve root, which is the traversing root below the affected disc.","kind":"clinical","origin":"ai"},{"id":"vertebral-column-joints-discs~ai-3","moduleId":"vertebral-column-joints-discs","stem":"Which ligament resists spinal extension?","options":[{"id":"a","text":"Anterior longitudinal ligament"},{"id":"b","text":"Posterior longitudinal ligament"},{"id":"c","text":"Ligamentum flavum"},{"id":"d","text":"Interspinous ligament"}],"answerId":"a","explanation":"The anterior longitudinal ligament (ALL) is responsible for resisting extension of the spine.","kind":"recall","origin":"ai"},{"id":"vertebral-column-joints-discs~ai-4","moduleId":"vertebral-column-joints-discs","stem":"What is the mechanism of injury in a postero-lateral disc herniation?","options":[{"id":"a","text":"Compression of the spinal cord"},{"id":"b","text":"Compression of the exiting nerve root"},{"id":"c","text":"Compression of the traversing nerve root"},{"id":"d","text":"Tearing of the annulus fibrosus"}],"answerId":"c","explanation":"A postero-lateral disc herniation typically compresses the traversing nerve root numbered for the vertebra below the herniation.","kind":"mechanism","origin":"ai"},{"id":"vertebral-column-joints-discs~ai-5","moduleId":"vertebral-column-joints-discs","stem":"In the context of raised intracranial pressure, which type of herniation is most likely to occur?","options":[{"id":"a","text":"Cingulate herniation"},{"id":"b","text":"Uncal herniation"},{"id":"c","text":"Central herniation"},{"id":"d","text":"Tonsillar herniation"}],"answerId":"d","explanation":"Tonsillar herniation occurs when increased intracranial pressure forces the cerebellar tonsils through the foramen magnum.","kind":"integration","linkedModuleIds":["raised-icp-herniation"],"origin":"ai"},{"id":"vertebral-column-joints-discs~ai-6","moduleId":"vertebral-column-joints-discs","stem":"How does the anatomy of the lumbar spine relate to the risk of disc herniation?","options":[{"id":"a","text":"Weakness of the anterior longitudinal ligament"},{"id":"b","text":"Narrowness of the posterior longitudinal ligament"},{"id":"c","text":"Strength of the interspinous ligaments"},{"id":"d","text":"Flexibility of the facet joints"}],"answerId":"b","explanation":"The narrow and weak posterior longitudinal ligament contributes to the risk of postero-lateral disc herniation in the lumbar spine.","kind":"integration","linkedModuleIds":["midgut-rotation-fixation"],"origin":"ai"}],"intrinsic-back-muscles-suboccipital":[{"id":"intrinsic-back-muscles-suboccipital~ai-0","moduleId":"intrinsic-back-muscles-suboccipital","stem":"Which muscles are primarily responsible for extending the spine?","options":[{"id":"a","text":"Iliocostalis"},{"id":"b","text":"Rectus capitis posterior major"},{"id":"c","text":"Splenius capitis"},{"id":"d","text":"Obliquus capitis inferior"}],"answerId":"a","explanation":"The iliocostalis is part of the erector spinae group, which are the chief extensors of the spine.","kind":"recall","origin":"ai"},{"id":"intrinsic-back-muscles-suboccipital~ai-1","moduleId":"intrinsic-back-muscles-suboccipital","stem":"What is the primary innervation of the intrinsic back muscles?","options":[{"id":"a","text":"Anterior rami of spinal nerves"},{"id":"b","text":"Posterior rami of spinal nerves"},{"id":"c","text":"Cranial nerve XI"},{"id":"d","text":"Thoracic spinal nerves only"}],"answerId":"b","explanation":"Intrinsic back muscles are exclusively innervated by the posterior (dorsal) rami of spinal nerves.","kind":"recall","origin":"ai"},{"id":"intrinsic-back-muscles-suboccipital~ai-2","moduleId":"intrinsic-back-muscles-suboccipital","stem":"Which structure is found in the suboccipital triangle?","options":[{"id":"a","text":"Vertebral artery"},{"id":"b","text":"Greater occipital nerve"},{"id":"c","text":"Cervical plexus"},{"id":"d","text":"Transverse cervical artery"}],"answerId":"a","explanation":"The vertebral artery lies in the suboccipital triangle, along with the suboccipital nerve.","kind":"recall","origin":"ai"},{"id":"intrinsic-back-muscles-suboccipital~ai-3","moduleId":"intrinsic-back-muscles-suboccipital","stem":"A patient presents with occipital headaches. Which nerve is likely involved in the referred pain?","options":[{"id":"a","text":"Suboccipital nerve"},{"id":"b","text":"Greater occipital nerve"},{"id":"c","text":"Lesser occipital nerve"},{"id":"d","text":"Accessory nerve"}],"answerId":"b","explanation":"The greater occipital nerve (dorsal ramus of C2) is responsible for referred pain in occipital headaches.","kind":"clinical","origin":"ai"},{"id":"intrinsic-back-muscles-suboccipital~ai-4","moduleId":"intrinsic-back-muscles-suboccipital","stem":"Which muscle is NOT part of the transversospinalis group?","options":[{"id":"a","text":"Semispinalis"},{"id":"b","text":"Multifidus"},{"id":"c","text":"Rotatores"},{"id":"d","text":"Iliocostalis"}],"answerId":"d","explanation":"Iliocostalis is part of the erector spinae group, not the transversospinalis group.","kind":"trap","origin":"ai"},{"id":"intrinsic-back-muscles-suboccipital~ai-5","moduleId":"intrinsic-back-muscles-suboccipital","stem":"How do the intrinsic back muscles differ from superficial back muscles?","options":[{"id":"a","text":"Innervation by anterior rami"},{"id":"b","text":"Function in limb movement"},{"id":"c","text":"Innervation by posterior rami"},{"id":"d","text":"Location in the back"}],"answerId":"c","explanation":"Intrinsic back muscles are innervated by posterior rami, distinguishing them from superficial back muscles.","kind":"trap","origin":"ai"},{"id":"intrinsic-back-muscles-suboccipital~ai-6","moduleId":"intrinsic-back-muscles-suboccipital","stem":"How can understanding the suboccipital triangle assist in managing lower back pain?","options":[{"id":"a","text":"It helps identify lumbar disc herniation"},{"id":"b","text":"It aids in understanding referred pain patterns"},{"id":"c","text":"It guides injections for lumbar pain"},{"id":"d","text":"It clarifies the role of anterior rami"}],"answerId":"b","explanation":"Knowledge of the suboccipital triangle can aid in understanding referred pain patterns that may affect lower back pain management.","kind":"integration","linkedModuleIds":["vertebral-column-joints-discs"],"origin":"ai"},{"id":"intrinsic-back-muscles-suboccipital~ai-7","moduleId":"intrinsic-back-muscles-suboccipital","stem":"Which aspect of the intrinsic back muscles is crucial for maintaining posture?","options":[{"id":"a","text":"Innervation by anterior rami"},{"id":"b","text":"Extension and rotation of the spine"},{"id":"c","text":"Movement of the limbs"},{"id":"d","text":"Location in the superficial layer"}],"answerId":"b","explanation":"The intrinsic back muscles extend and rotate the spine, which is essential for maintaining posture.","kind":"integration","linkedModuleIds":["hrp1-perineal-spaces-triangles"],"origin":"ai"}],"face-muscles-innervation":[{"id":"face-muscles-innervation~ai-0","moduleId":"face-muscles-innervation","stem":"Which cranial nerve is responsible for the motor innervation of the muscles of facial expression?","options":[{"id":"a","text":"CN V"},{"id":"b","text":"CN VII"},{"id":"c","text":"CN IX"},{"id":"d","text":"CN X"}],"answerId":"b","explanation":"The facial nerve (CN VII) innervates all muscles of facial expression.","kind":"recall","origin":"ai"},{"id":"face-muscles-innervation~ai-1","moduleId":"face-muscles-innervation","stem":"A patient presents with paroxysmal, severe facial pain localized to the cheek. Which condition is most likely?","options":[{"id":"a","text":"Bell's palsy"},{"id":"b","text":"Trigeminal neuralgia"},{"id":"c","text":"Cavernous sinus thrombosis"},{"id":"d","text":"Facial nerve injury"}],"answerId":"b","explanation":"Paroxysmal lightning-like pain in the cheek is characteristic of trigeminal neuralgia.","kind":"clinical","origin":"ai"},{"id":"face-muscles-innervation~ai-2","moduleId":"face-muscles-innervation","stem":"Inability to smile on one side of the face is indicative of which nerve dysfunction?","options":[{"id":"a","text":"Trigeminal nerve (CN V)"},{"id":"b","text":"Facial nerve (CN VII)"},{"id":"c","text":"Accessory nerve (CN XI)"},{"id":"d","text":"Hypoglossal nerve (CN XII)"}],"answerId":"b","explanation":"The facial nerve (CN VII) controls the muscles responsible for smiling.","kind":"recall","origin":"ai"},{"id":"face-muscles-innervation~ai-3","moduleId":"face-muscles-innervation","stem":"Which of the following statements correctly differentiates the functions of CN V and CN VII?","options":[{"id":"a","text":"CN V supplies motor function to facial muscles"},{"id":"b","text":"CN VII provides sensory innervation to the face"},{"id":"c","text":"CN V is sensory to the face, CN VII is motor to facial expression"},{"id":"d","text":"CN VII is sensory to the face, CN V is motor to mastication"}],"answerId":"c","explanation":"CN V provides sensory innervation to the face, while CN VII is motor to the muscles of facial expression.","kind":"trap","origin":"ai"},{"id":"face-muscles-innervation~ai-4","moduleId":"face-muscles-innervation","stem":"A furuncle in the danger triangle of the face can lead to which serious complication?","options":[{"id":"a","text":"Facial nerve paralysis"},{"id":"b","text":"Cavernous sinus thrombosis"},{"id":"c","text":"Trigeminal neuralgia"},{"id":"d","text":"Mastoiditis"}],"answerId":"b","explanation":"Infections in the danger triangle can spread to the cavernous sinus, leading to thrombosis.","kind":"clinical","origin":"ai"},{"id":"face-muscles-innervation~ai-5","moduleId":"face-muscles-innervation","stem":"Which cranial nerve is primarily responsible for the sensory innervation of the face?","options":[{"id":"a","text":"CN VII"},{"id":"b","text":"CN V"},{"id":"c","text":"CN IX"},{"id":"d","text":"CN X"}],"answerId":"b","explanation":"The trigeminal nerve (CN V) is responsible for sensory innervation of the face.","kind":"recall","origin":"ai"},{"id":"face-muscles-innervation~ai-6","moduleId":"face-muscles-innervation","stem":"How does the facial nerve (CN VII) relate to the trigeminal nerve (CN V) in terms of facial function?","options":[{"id":"a","text":"Both are motor nerves"},{"id":"b","text":"CN VII is sensory, CN V is motor"},{"id":"c","text":"CN VII is motor to facial expression, CN V is sensory to the face"},{"id":"d","text":"Both are sensory nerves"}],"answerId":"c","explanation":"CN VII is motor to facial expression, while CN V is sensory to the face.","kind":"integration","linkedModuleIds":["cranial-nerves-overview"],"origin":"ai"},{"id":"face-muscles-innervation~ai-7","moduleId":"face-muscles-innervation","stem":"Which nerve is involved in the reflex control of mastication and how does it relate to facial expression?","options":[{"id":"a","text":"CN V for mastication, CN VII for expression"},{"id":"b","text":"CN VII for both"},{"id":"c","text":"CN V for expression, CN VII for mastication"},{"id":"d","text":"Both are involved in mastication only"}],"answerId":"a","explanation":"CN V is responsible for mastication, while CN VII controls facial expression.","kind":"integration","linkedModuleIds":["mastication-mechanics-reflex"],"origin":"ai"}],"upper-limb-joints":[{"id":"upper-limb-joints~ai-0","moduleId":"upper-limb-joints","stem":"What type of joint is the sternoclavicular joint?","options":[{"id":"a","text":"Saddle-type synovial joint"},{"id":"b","text":"Hinge joint"},{"id":"c","text":"Ball-and-socket joint"},{"id":"d","text":"Plane synovial joint"}],"answerId":"a","explanation":"The sternoclavicular joint is a saddle-type synovial joint, providing stability and allowing for limited movement.","kind":"recall","origin":"ai"},{"id":"upper-limb-joints~ai-1","moduleId":"upper-limb-joints","stem":"Which ligament is primarily responsible for stabilizing the acromioclavicular joint?","options":[{"id":"a","text":"Coracoclavicular ligament"},{"id":"b","text":"Ulnar collateral ligament"},{"id":"c","text":"Radial collateral ligament"},{"id":"d","text":"Anular ligament"}],"answerId":"a","explanation":"The coracoclavicular ligament stabilizes the acromioclavicular joint, preventing separation.","kind":"recall","origin":"ai"},{"id":"upper-limb-joints~ai-2","moduleId":"upper-limb-joints","stem":"A child presents with an arm held in a pronated position after being pulled. What is the likely diagnosis?","options":[{"id":"a","text":"Glenohumeral dislocation"},{"id":"b","text":"Nursemaid's elbow"},{"id":"c","text":"AC joint separation"},{"id":"d","text":"Radial head fracture"}],"answerId":"b","explanation":"The presentation is characteristic of nursemaid's elbow, where the radial head subluxes from the anular ligament.","kind":"clinical","origin":"ai"},{"id":"upper-limb-joints~ai-3","moduleId":"upper-limb-joints","stem":"What is the most common direction of glenohumeral dislocation?","options":[{"id":"a","text":"Posterior"},{"id":"b","text":"Superior"},{"id":"c","text":"Lateral"},{"id":"d","text":"Anterior/inferior"}],"answerId":"d","explanation":"Most glenohumeral dislocations occur anteriorly/inferiorly due to the lack of support in that direction.","kind":"trap","origin":"ai"},{"id":"upper-limb-joints~ai-4","moduleId":"upper-limb-joints","stem":"Which joint allows for pronation and supination of the forearm?","options":[{"id":"a","text":"Humeroulnar joint"},{"id":"b","text":"Radioulnar joint"},{"id":"c","text":"Glenohumeral joint"},{"id":"d","text":"Wrist joint"}],"answerId":"b","explanation":"The radioulnar joints are pivot joints that facilitate pronation and supination of the forearm.","kind":"recall","origin":"ai"},{"id":"upper-limb-joints~ai-5","moduleId":"upper-limb-joints","stem":"What is the mechanism of injury in a toddler with a 'step deformity' over the AC joint?","options":[{"id":"a","text":"Fall on an outstretched hand"},{"id":"b","text":"Direct blow to the shoulder"},{"id":"c","text":"Seizure activity"},{"id":"d","text":"Overhead lifting"}],"answerId":"b","explanation":"A step deformity over the AC joint typically results from an acromioclavicular separation due to a fall on the shoulder.","kind":"clinical","origin":"ai"},{"id":"upper-limb-joints~ai-6","moduleId":"upper-limb-joints","stem":"How does the embryological development of limb joints relate to their stability and injury patterns?","options":[{"id":"a","text":"Joints develop from mesoderm and influence stability"},{"id":"b","text":"Joints are formed from ectoderm and are less stable"},{"id":"c","text":"All joints are equally stable regardless of embryological origin"},{"id":"d","text":"Ligament development has no impact on joint injury patterns"}],"answerId":"a","explanation":"The stability of joints is influenced by their embryological development from mesoderm, affecting their injury patterns.","kind":"integration","linkedModuleIds":["msk-embryo-limb-joints"],"origin":"ai"},{"id":"upper-limb-joints~ai-7","moduleId":"upper-limb-joints","stem":"In what way does understanding the anatomy of the glenohumeral joint assist in diagnosing nerve injuries?","options":[{"id":"a","text":"It helps identify muscle weakness patterns"},{"id":"b","text":"It clarifies the role of ligaments in joint stability"},{"id":"c","text":"It has no relevance to nerve injuries"},{"id":"d","text":"It simplifies the classification of fractures"}],"answerId":"a","explanation":"Knowledge of the glenohumeral joint anatomy aids in identifying muscle weakness patterns related to nerve injuries, particularly the axillary nerve.","kind":"integration","linkedModuleIds":["hand-nerve-lesions"],"origin":"ai"}],"scalp-layers":[{"id":"scalp-layers~ai-0","moduleId":"scalp-layers","stem":"What are the five layers of the scalp represented by the acronym 'SCALP'?","options":[{"id":"a","text":"Skin, Connective tissue, Aponeurosis, Loose areolar tissue, Pericranium"},{"id":"b","text":"Skin, Cartilage, Aponeurosis, Loose areolar tissue, Pericranium"},{"id":"c","text":"Skin, Connective tissue, Aponeurosis, Loose connective tissue, Pericranium"},{"id":"d","text":"Skin, Connective tissue, Aponeurosis, Loose areolar tissue, Periosteum"}],"answerId":"a","explanation":"The correct layers of the scalp are Skin, Connective tissue, Aponeurosis, Loose areolar tissue, and Pericranium.","kind":"recall","origin":"ai"},{"id":"scalp-layers~ai-1","moduleId":"scalp-layers","stem":"Why do scalp wounds bleed profusely?","options":[{"id":"a","text":"Vessels are deeply embedded in the skin"},{"id":"b","text":"Arteries are held open in the dense connective tissue"},{"id":"c","text":"The scalp has a rich nerve supply"},{"id":"d","text":"The aponeurosis prevents retraction of blood vessels"}],"answerId":"b","explanation":"Scalp wounds bleed profusely because the arteries lie in the dense connective tissue layer, which holds the vessels open.","kind":"mechanism","origin":"ai"},{"id":"scalp-layers~ai-2","moduleId":"scalp-layers","stem":"What causes a deep scalp wound to gape widely?","options":[{"id":"a","text":"Cutting through the skin"},{"id":"b","text":"Laceration of the epicranial aponeurosis"},{"id":"c","text":"Severe infection"},{"id":"d","text":"Damage to the underlying bone"}],"answerId":"b","explanation":"A deep scalp wound gapes widely when the epicranial aponeurosis is cut, allowing the opposing muscle bellies to pull the edges apart.","kind":"recall","origin":"ai"},{"id":"scalp-layers~ai-3","moduleId":"scalp-layers","stem":"Which layer of the scalp is referred to as the 'danger area'?","options":[{"id":"a","text":"Skin"},{"id":"b","text":"Dense connective tissue"},{"id":"c","text":"Loose areolar tissue"},{"id":"d","text":"Aponeurosis"}],"answerId":"c","explanation":"The loose areolar layer is known as the 'danger area' because it allows for the spread of infection and connects to intracranial structures.","kind":"recall","origin":"ai"},{"id":"scalp-layers~ai-4","moduleId":"scalp-layers","stem":"In a scalp infection, how can the infection reach the intracranial dural venous sinuses?","options":[{"id":"a","text":"Through emissary veins in the loose areolar layer"},{"id":"b","text":"Via the dense connective tissue"},{"id":"c","text":"By direct extension through the skin"},{"id":"d","text":"Through the aponeurosis"}],"answerId":"a","explanation":"Infections can reach the intracranial dural venous sinuses through the emissary veins that traverse the loose areolar layer.","kind":"mechanism","origin":"ai"},{"id":"scalp-layers~ai-5","moduleId":"scalp-layers","stem":"How does the innervation of the scalp relate to its vascular supply?","options":[{"id":"a","text":"Both are supplied by the external carotid artery"},{"id":"b","text":"Both are derived from the trigeminal nerve"},{"id":"c","text":"Both are affected by scalp infections"},{"id":"d","text":"Both involve branches of the internal carotid artery"}],"answerId":"b","explanation":"The scalp's blood supply and sensory innervation are both derived from branches of the external carotid artery and the trigeminal nerve, respectively.","kind":"integration","linkedModuleIds":["face-muscles-innervation"],"origin":"ai"},{"id":"scalp-layers~ai-6","moduleId":"scalp-layers","stem":"What is the clinical significance of the scalp's rich vascular supply when considering gastrointestinal bleeding?","options":[{"id":"a","text":"Scalp bleeding can mask internal bleeding"},{"id":"b","text":"Scalp injuries can lead to systemic infections"},{"id":"c","text":"Scalp vascularity is unrelated to gastrointestinal bleeding"},{"id":"d","text":"Scalp bleeding can indicate a need for gastrointestinal evaluation"}],"answerId":"a","explanation":"Profuse scalp bleeding can mask signs of internal bleeding, making it important to evaluate both areas in trauma cases.","kind":"integration","linkedModuleIds":["gastrointestinal-bleeding-approach"],"origin":"ai"}],"hand-nerve-lesions":[{"id":"hand-nerve-lesions~ai-0","moduleId":"hand-nerve-lesions","stem":"What is the most common symptom of carpal tunnel syndrome?","options":[{"id":"a","text":"Night-time numbness of the thumb to middle finger"},{"id":"b","text":"Wrist drop"},{"id":"c","text":"Claw hand"},{"id":"d","text":"Thenar wasting"}],"answerId":"a","explanation":"Carpal tunnel syndrome commonly presents with night-time numbness affecting the thumb, index, and middle fingers due to median nerve compression.","kind":"recall","origin":"ai"},{"id":"hand-nerve-lesions~ai-1","moduleId":"hand-nerve-lesions","stem":"Which clinical sign is indicative of ulnar nerve palsy?","options":[{"id":"a","text":"Positive Phalen's test"},{"id":"b","text":"Claw hand"},{"id":"c","text":"Ape hand"},{"id":"d","text":"Wrist drop"}],"answerId":"b","explanation":"Claw hand is a classic sign of ulnar nerve palsy, characterized by hyperextension of the MCP joints and flexion of the IP joints of the 4th and 5th fingers.","kind":"recall","origin":"ai"},{"id":"hand-nerve-lesions~ai-2","moduleId":"hand-nerve-lesions","stem":"What mechanism explains the ulnar paradox?","options":[{"id":"a","text":"Proximal lesions cause more clawing"},{"id":"b","text":"Distal lesions cause more clawing"},{"id":"c","text":"Proximal lesions denervate the medial FDP"},{"id":"d","text":"Distal lesions denervate the medial FDP"}],"answerId":"c","explanation":"The ulnar paradox states that a proximal ulnar lesion results in less visible clawing due to denervation of the medial FDP, which reduces flexion at the IP joints.","kind":"mechanism","origin":"ai"},{"id":"hand-nerve-lesions~ai-3","moduleId":"hand-nerve-lesions","stem":"What is the expected finding in a patient with a radial nerve injury?","options":[{"id":"a","text":"Claw hand"},{"id":"b","text":"Wrist drop"},{"id":"c","text":"Ape hand"},{"id":"d","text":"Thenar wasting"}],"answerId":"b","explanation":"A radial nerve injury results in wrist drop due to loss of wrist and finger extension.","kind":"recall","origin":"ai"},{"id":"hand-nerve-lesions~ai-4","moduleId":"hand-nerve-lesions","stem":"A patient presents with night-time numbness in the thumb and index fingers. Which test would most likely be positive?","options":[{"id":"a","text":"Froment's sign"},{"id":"b","text":"Tinel's sign"},{"id":"c","text":"Phalen's test"},{"id":"d","text":"Allens test"}],"answerId":"b","explanation":"Tinel's sign, which tests for median nerve irritation, would likely be positive in a case of carpal tunnel syndrome.","kind":"clinical","origin":"ai"},{"id":"hand-nerve-lesions~ai-5","moduleId":"hand-nerve-lesions","stem":"In a patient with a proximal ulnar nerve lesion, which of the following findings would be expected?","options":[{"id":"a","text":"More pronounced claw hand"},{"id":"b","text":"Less pronounced claw hand"},{"id":"c","text":"Wrist drop"},{"id":"d","text":"Thenar wasting"}],"answerId":"b","explanation":"A proximal ulnar nerve lesion results in less pronounced clawing due to the denervation of the medial FDP, which reduces flexion at the IP joints.","kind":"trap","origin":"ai"},{"id":"hand-nerve-lesions~ai-6","moduleId":"hand-nerve-lesions","stem":"How do the intrinsic muscles of the palm relate to ulnar nerve function?","options":[{"id":"a","text":"They are all innervated by the median nerve"},{"id":"b","text":"They are all innervated by the radial nerve"},{"id":"c","text":"They include muscles innervated by the ulnar nerve"},{"id":"d","text":"They are not involved in hand function"}],"answerId":"c","explanation":"The intrinsic muscles of the palm, including the interossei and hypothenar muscles, are primarily innervated by the ulnar nerve, which is crucial for hand function.","kind":"integration","linkedModuleIds":["palm-intrinsic-muscles"],"origin":"ai"},{"id":"hand-nerve-lesions~ai-7","moduleId":"hand-nerve-lesions","stem":"What joint movement is affected by a radial nerve injury?","options":[{"id":"a","text":"Flexion of the fingers"},{"id":"b","text":"Extension of the wrist"},{"id":"c","text":"Abduction of the thumb"},{"id":"d","text":"Opposition of the thumb"}],"answerId":"b","explanation":"A radial nerve injury affects the extension of the wrist and fingers, resulting in wrist drop.","kind":"integration","linkedModuleIds":["upper-limb-joints"],"origin":"ai"}],"neck-triangles-fascia":[{"id":"neck-triangles-fascia~ai-0","moduleId":"neck-triangles-fascia","stem":"Which nerve supplies the sternocleidomastoid muscle?","options":[{"id":"a","text":"Vagus nerve (CN X)"},{"id":"b","text":"Accessory nerve (CN XI)"},{"id":"c","text":"Facial nerve (CN VII)"},{"id":"d","text":"Hypoglossal nerve (CN XII)"}],"answerId":"b","explanation":"The sternocleidomastoid is primarily supplied by the accessory nerve (CN XI).","kind":"recall","origin":"ai"},{"id":"neck-triangles-fascia~ai-1","moduleId":"neck-triangles-fascia","stem":"What is the primary action of the sternocleidomastoid muscle when acting unilaterally?","options":[{"id":"a","text":"Flexes the neck"},{"id":"b","text":"Tilts the head toward the same side"},{"id":"c","text":"Rotates the head to the same side"},{"id":"d","text":"Elevates the shoulder"}],"answerId":"b","explanation":"Unilateral contraction of the SCM tilts the head toward the same side and rotates the face to the opposite side.","kind":"mechanism","origin":"ai"},{"id":"neck-triangles-fascia~ai-2","moduleId":"neck-triangles-fascia","stem":"A patient presents with dysphagia and neck stiffness. Imaging reveals a retropharyngeal abscess. What is the most likely anatomical space involved?","options":[{"id":"a","text":"Investing fascia"},{"id":"b","text":"Pretracheal fascia"},{"id":"c","text":"Retropharyngeal space"},{"id":"d","text":"Carotid sheath"}],"answerId":"c","explanation":"The retropharyngeal space is known as the 'danger space' and can lead to serious complications like dysphagia when infected.","kind":"clinical","origin":"ai"},{"id":"neck-triangles-fascia~ai-3","moduleId":"neck-triangles-fascia","stem":"After a posterior triangle lymph node biopsy, a patient exhibits shoulder droop and weakness in head turning. What is the most likely cause?","options":[{"id":"a","text":"Vagus nerve injury"},{"id":"b","text":"Accessory nerve injury"},{"id":"c","text":"Brachial plexus injury"},{"id":"d","text":"Phrenic nerve injury"}],"answerId":"b","explanation":"Shoulder droop and weakness in head turning are indicative of accessory nerve (CN XI) injury.","kind":"recall","origin":"ai"},{"id":"neck-triangles-fascia~ai-4","moduleId":"neck-triangles-fascia","stem":"In congenital torticollis, which direction does the head tilt and the chin point?","options":[{"id":"a","text":"Tilt toward the affected side, chin toward the affected side"},{"id":"b","text":"Tilt toward the affected side, chin away from the affected side"},{"id":"c","text":"Tilt away from the affected side, chin toward the affected side"},{"id":"d","text":"Tilt away from the affected side, chin away from the affected side"}],"answerId":"b","explanation":"In congenital torticollis, the head tilts toward the affected side while the chin points away.","kind":"trap","origin":"ai"},{"id":"neck-triangles-fascia~ai-5","moduleId":"neck-triangles-fascia","stem":"Which structure is NOT found in the posterior triangle of the neck?","options":[{"id":"a","text":"Accessory nerve (CN XI)"},{"id":"b","text":"Phrenic nerve"},{"id":"c","text":"Common carotid artery"},{"id":"d","text":"External jugular vein"}],"answerId":"c","explanation":"The common carotid artery is located in the anterior triangle, not the posterior triangle.","kind":"trap","origin":"ai"},{"id":"neck-triangles-fascia~ai-6","moduleId":"neck-triangles-fascia","stem":"How does the anatomy of the neck fascia relate to surgical approaches in thyroid surgery?","options":[{"id":"a","text":"Investing fascia protects the thyroid gland"},{"id":"b","text":"Pretracheal fascia contains the thyroid gland"},{"id":"c","text":"Carotid sheath contains thyroid vessels"},{"id":"d","text":"Prevertebral fascia allows access to the thyroid gland"}],"answerId":"b","explanation":"The pretracheal fascia encloses the thyroid gland and is important in surgical approaches to avoid damage.","kind":"integration","linkedModuleIds":["hen1-thyroid-gross-anatomy"],"origin":"ai"},{"id":"neck-triangles-fascia~ai-7","moduleId":"neck-triangles-fascia","stem":"What is a potential complication of a retropharyngeal abscess in relation to the neck's fascial planes?","options":[{"id":"a","text":"Infection spreading to the mediastinum"},{"id":"b","text":"Compression of the carotid artery"},{"id":"c","text":"Damage to the phrenic nerve"},{"id":"d","text":"Injury to the brachial plexus"}],"answerId":"a","explanation":"The retropharyngeal space can allow infections to spread into the mediastinum, leading to serious complications.","kind":"integration","linkedModuleIds":["thyroid-root-of-neck"],"origin":"ai"}],"anterior-triangle-carotid":[{"id":"anterior-triangle-carotid~ai-0","moduleId":"anterior-triangle-carotid","stem":"Which structure is NOT found in the carotid triangle?","options":[{"id":"a","text":"Common carotid artery"},{"id":"b","text":"Internal jugular vein"},{"id":"c","text":"Vagus nerve"},{"id":"d","text":"External carotid artery branches"}],"answerId":"d","explanation":"The external carotid artery branches are not contained within the carotid triangle; they branch off after the bifurcation.","kind":"recall","origin":"ai"},{"id":"anterior-triangle-carotid~ai-1","moduleId":"anterior-triangle-carotid","stem":"What is the primary function of the carotid sinus?","options":[{"id":"a","text":"Oxygen sensing"},{"id":"b","text":"Carbon dioxide sensing"},{"id":"c","text":"Blood pressure regulation"},{"id":"d","text":"pH regulation"}],"answerId":"c","explanation":"The carotid sinus acts as a baroreceptor that senses blood pressure.","kind":"mechanism","origin":"ai"},{"id":"anterior-triangle-carotid~ai-2","moduleId":"anterior-triangle-carotid","stem":"A patient presents with bradycardia after carotid sinus massage. Which nerve is primarily involved?","options":[{"id":"a","text":"Vagus nerve (CN X)"},{"id":"b","text":"Glossopharyngeal nerve (CN IX)"},{"id":"c","text":"Hypoglossal nerve (CN XII)"},{"id":"d","text":"Accessory nerve (CN XI)"}],"answerId":"b","explanation":"The glossopharyngeal nerve (CN IX) innervates the carotid sinus and mediates the baroreceptor reflex.","kind":"clinical","origin":"ai"},{"id":"anterior-triangle-carotid~ai-3","moduleId":"anterior-triangle-carotid","stem":"A patient has a submandibular-region injury. Which clinical finding is expected?","options":[{"id":"a","text":"Deviated tongue towards the injured side"},{"id":"b","text":"Deviated tongue away from the injured side"},{"id":"c","text":"Loss of sensation in the anterior tongue"},{"id":"d","text":"Difficulty swallowing"}],"answerId":"a","explanation":"Injury to the hypoglossal nerve (CN XII) causes the tongue to deviate towards the affected side.","kind":"recall","origin":"ai"},{"id":"anterior-triangle-carotid~ai-4","moduleId":"anterior-triangle-carotid","stem":"Which of the following is a common trap regarding the internal carotid artery?","options":[{"id":"a","text":"It branches into the facial artery"},{"id":"b","text":"It has no branches in the neck"},{"id":"c","text":"It supplies the thyroid gland"},{"id":"d","text":"It gives off the lingual artery"}],"answerId":"b","explanation":"The internal carotid artery has no branches in the neck, which is a key distinguishing feature.","kind":"trap","origin":"ai"},{"id":"anterior-triangle-carotid~ai-5","moduleId":"anterior-triangle-carotid","stem":"How does the anatomy of the anterior triangle relate to the thyroid gland's blood supply?","options":[{"id":"a","text":"The thyroid receives blood from the internal carotid"},{"id":"b","text":"The thyroid is supplied by branches of the external carotid"},{"id":"c","text":"The thyroid is located in the carotid triangle"},{"id":"d","text":"The thyroid is innervated by the vagus nerve"}],"answerId":"b","explanation":"The thyroid gland receives blood supply from branches of the external carotid artery, particularly the superior thyroid artery.","kind":"integration","linkedModuleIds":["thyroid-root-of-neck"],"origin":"ai"},{"id":"anterior-triangle-carotid~ai-6","moduleId":"anterior-triangle-carotid","stem":"Which structure's injury would most likely affect the function of the carotid sinus?","options":[{"id":"a","text":"Internal jugular vein"},{"id":"b","text":"Common carotid artery"},{"id":"c","text":"Vagus nerve"},{"id":"d","text":"Hypoglossal nerve"}],"answerId":"c","explanation":"The vagus nerve is involved in the autonomic regulation of heart rate and is connected to the carotid sinus function.","kind":"integration","linkedModuleIds":["escape-rhythms-sinus-dysfunction"],"origin":"ai"}],"palm-intrinsic-muscles":[{"id":"palm-intrinsic-muscles~ai-0","moduleId":"palm-intrinsic-muscles","stem":"Which nerve primarily supplies the majority of the intrinsic muscles of the hand?","options":[{"id":"a","text":"Median nerve"},{"id":"b","text":"Ulnar nerve"},{"id":"c","text":"Radial nerve"},{"id":"d","text":"Musculocutaneous nerve"}],"answerId":"b","explanation":"The deep branch of the ulnar nerve supplies most intrinsic hand muscles, while the median nerve innervates only the thenar muscles and the 1st and 2nd lumbricals.","kind":"recall","origin":"ai"},{"id":"palm-intrinsic-muscles~ai-1","moduleId":"palm-intrinsic-muscles","stem":"What is the primary mechanism of Dupuytren contracture?","options":[{"id":"a","text":"Tendon rupture"},{"id":"b","text":"Palmar aponeurosis thickening"},{"id":"c","text":"Nerve entrapment"},{"id":"d","text":"Joint dislocation"}],"answerId":"b","explanation":"Dupuytren contracture is caused by progressive thickening of the palmar aponeurosis, leading to fixed flexion of the affected fingers.","kind":"mechanism","origin":"ai"},{"id":"palm-intrinsic-muscles~ai-2","moduleId":"palm-intrinsic-muscles","stem":"A patient presents with a finger that catches and locks, then releases with a snap. What is the likely diagnosis?","options":[{"id":"a","text":"Dupuytren contracture"},{"id":"b","text":"Trigger finger"},{"id":"c","text":"Carpal tunnel syndrome"},{"id":"d","text":"Ulnar nerve entrapment"}],"answerId":"b","explanation":"The described symptoms are characteristic of trigger finger, which is due to flexor tenosynovitis.","kind":"clinical","origin":"ai"},{"id":"palm-intrinsic-muscles~ai-3","moduleId":"palm-intrinsic-muscles","stem":"Which of the following muscles is innervated by the median nerve?","options":[{"id":"a","text":"Adductor pollicis"},{"id":"b","text":"Flexor pollicis brevis (superficial head)"},{"id":"c","text":"Dorsal interossei"},{"id":"d","text":"Palmar interossei"}],"answerId":"b","explanation":"The flexor pollicis brevis (superficial head) is innervated by the median nerve, while the other options are innervated by the ulnar nerve.","kind":"trap","origin":"ai"},{"id":"palm-intrinsic-muscles~ai-4","moduleId":"palm-intrinsic-muscles","stem":"What is the primary function of the interossei muscles in the hand?","options":[{"id":"a","text":"Flexion of the MCP joints"},{"id":"b","text":"Extension of the IP joints"},{"id":"c","text":"Abduction and adduction of the fingers"},{"id":"d","text":"Opposition of the thumb"}],"answerId":"c","explanation":"The interossei muscles are responsible for the abduction and adduction of the fingers (DAB/PAD).","kind":"recall","origin":"ai"},{"id":"palm-intrinsic-muscles~ai-5","moduleId":"palm-intrinsic-muscles","stem":"How does the ulnar nerve lesion affect hand function compared to a median nerve lesion?","options":[{"id":"a","text":"Both equally impair thumb function"},{"id":"b","text":"Ulnar lesions affect fine motor control more severely"},{"id":"c","text":"Median lesions cause more pain"},{"id":"d","text":"Ulnar lesions have no impact on grip strength"}],"answerId":"b","explanation":"Ulnar nerve lesions severely impair fine motor control of the hand, while median nerve lesions primarily affect thumb function.","kind":"integration","linkedModuleIds":["hand-nerve-lesions"],"origin":"ai"},{"id":"palm-intrinsic-muscles~ai-6","moduleId":"palm-intrinsic-muscles","stem":"Which structure is primarily responsible for preventing bowstringing of the flexor tendons in the fingers?","options":[{"id":"a","text":"Palmar aponeurosis"},{"id":"b","text":"Flexor sheaths"},{"id":"c","text":"Extensor hood"},{"id":"d","text":"Digital arteries"}],"answerId":"b","explanation":"The fibrous digital sheath forms pulleys that prevent bowstringing of the flexor tendons during finger movement.","kind":"recall","origin":"ai"},{"id":"palm-intrinsic-muscles~ai-7","moduleId":"palm-intrinsic-muscles","stem":"What is the main arterial supply to the intrinsic muscles of the hand?","options":[{"id":"a","text":"Radial artery"},{"id":"b","text":"Ulnar artery"},{"id":"c","text":"Brachial artery"},{"id":"d","text":"Subclavian artery"}],"answerId":"b","explanation":"The ulnar artery primarily supplies the intrinsic muscles of the hand through the superficial and deep palmar arches.","kind":"recall","origin":"ai"}],"parotid-temporal-regions":[{"id":"parotid-temporal-regions~ai-0","moduleId":"parotid-temporal-regions","stem":"Which structure is the most superficial in the parotid gland?","options":[{"id":"a","text":"Retromandibular vein"},{"id":"b","text":"Facial nerve (CN VII)"},{"id":"c","text":"External carotid artery"},{"id":"d","text":"Auriculotemporal nerve"}],"answerId":"b","explanation":"The facial nerve (CN VII) is the most superficial structure in the parotid gland.","kind":"recall","origin":"ai"},{"id":"parotid-temporal-regions~ai-1","moduleId":"parotid-temporal-regions","stem":"What is the primary cause of Bell's palsy?","options":[{"id":"a","text":"Stroke"},{"id":"b","text":"Tumor"},{"id":"c","text":"Idiopathic"},{"id":"d","text":"Trauma"}],"answerId":"c","explanation":"Bell's palsy is often idiopathic, though it can be associated with viral infections like HSV-1.","kind":"recall","origin":"ai"},{"id":"parotid-temporal-regions~ai-2","moduleId":"parotid-temporal-regions","stem":"A patient presents with unilateral facial droop including the forehead. What is the most likely diagnosis?","options":[{"id":"a","text":"Stroke"},{"id":"b","text":"Bell's palsy"},{"id":"c","text":"Trigeminal neuralgia"},{"id":"d","text":"Parotid tumor"}],"answerId":"b","explanation":"Involvement of the forehead indicates a lower-motor-neuron lesion, characteristic of Bell's palsy.","kind":"clinical","origin":"ai"},{"id":"parotid-temporal-regions~ai-3","moduleId":"parotid-temporal-regions","stem":"Which artery is at risk of injury in a fracture at the pterion?","options":[{"id":"a","text":"Facial artery"},{"id":"b","text":"Middle meningeal artery"},{"id":"c","text":"Maxillary artery"},{"id":"d","text":"Superficial temporal artery"}],"answerId":"b","explanation":"The middle meningeal artery runs beneath the pterion and is at risk during fractures in that area, leading to epidural hematoma.","kind":"mechanism","origin":"ai"},{"id":"parotid-temporal-regions~ai-4","moduleId":"parotid-temporal-regions","stem":"What is the result of a parotid tumor invading the facial nerve?","options":[{"id":"a","text":"Bilateral facial weakness"},{"id":"b","text":"Unilateral facial weakness"},{"id":"c","text":"Loss of taste"},{"id":"d","text":"Dry mouth"}],"answerId":"b","explanation":"A parotid tumor can invade the intraparotid facial nerve, leading to unilateral facial weakness.","kind":"clinical","origin":"ai"},{"id":"parotid-temporal-regions~ai-5","moduleId":"parotid-temporal-regions","stem":"How does the facial nerve supply the parotid gland?","options":[{"id":"a","text":"Directly from CN VII"},{"id":"b","text":"Via the glossopharyngeal nerve"},{"id":"c","text":"Through the otic ganglion"},{"id":"d","text":"Via the auriculotemporal nerve"}],"answerId":"c","explanation":"Parasympathetic fibers from the glossopharyngeal nerve synapse in the otic ganglion before reaching the parotid gland.","kind":"mechanism","origin":"ai"},{"id":"parotid-temporal-regions~ai-6","moduleId":"parotid-temporal-regions","stem":"A patient with a parotid mass shows facial weakness. Which nerve is likely affected?","options":[{"id":"a","text":"Trigeminal nerve"},{"id":"b","text":"Facial nerve"},{"id":"c","text":"Glossopharyngeal nerve"},{"id":"d","text":"Vagus nerve"}],"answerId":"b","explanation":"The facial nerve is likely affected due to its proximity to the parotid gland, leading to facial weakness.","kind":"clinical","origin":"ai"},{"id":"parotid-temporal-regions~ai-7","moduleId":"parotid-temporal-regions","stem":"In a patient with Bell's palsy, which of the following findings would you expect?","options":[{"id":"a","text":"Forehead sparing"},{"id":"b","text":"Bilateral facial droop"},{"id":"c","text":"Loss of taste on the anterior 2/3 of the tongue"},{"id":"d","text":"Increased salivation"}],"answerId":"c","explanation":"Bell's palsy can lead to loss of taste on the anterior 2/3 of the tongue due to facial nerve involvement.","kind":"integration","linkedModuleIds":["neurotoxins-facial-palsy"],"origin":"ai"},{"id":"parotid-temporal-regions~ai-8","moduleId":"parotid-temporal-regions","stem":"What is a common complication of a temporal bone fracture affecting the parotid region?","options":[{"id":"a","text":"Epidural hematoma"},{"id":"b","text":"Facial nerve injury"},{"id":"c","text":"Cerebrospinal fluid leak"},{"id":"d","text":"Hearing loss"}],"answerId":"b","explanation":"Temporal bone fractures can injure the facial nerve, leading to facial weakness.","kind":"integration","linkedModuleIds":["inner-ear-disorders"],"origin":"ai"}],"forearm-flexor-compartment":[{"id":"forearm-flexor-compartment~ai-0","moduleId":"forearm-flexor-compartment","stem":"Which nerve primarily innervates the majority of the muscles in the anterior forearm?","options":[{"id":"a","text":"Ulnar nerve"},{"id":"b","text":"Radial nerve"},{"id":"c","text":"Median nerve"},{"id":"d","text":"Musculocutaneous nerve"}],"answerId":"c","explanation":"The median nerve innervates most of the anterior forearm muscles, while the ulnar nerve only supplies flexor carpi ulnaris and part of flexor digitorum profundus.","kind":"recall","origin":"ai"},{"id":"forearm-flexor-compartment~ai-1","moduleId":"forearm-flexor-compartment","stem":"What is the primary motor deficit observed in anterior interosseous nerve (AIN) syndrome?","options":[{"id":"a","text":"Inability to flex the wrist"},{"id":"b","text":"Inability to make an 'OK' sign"},{"id":"c","text":"Loss of sensation in the thumb"},{"id":"d","text":"Weakness of elbow flexion"}],"answerId":"b","explanation":"AIN syndrome results in weakness of the flexor pollicis longus and the lateral half of flexor digitorum profundus, leading to the inability to make a rounded 'OK' sign.","kind":"mechanism","origin":"ai"},{"id":"forearm-flexor-compartment~ai-2","moduleId":"forearm-flexor-compartment","stem":"A patient presents with weakness in wrist flexion and is unable to deviate the wrist ulnarly. Which muscle is most likely affected?","options":[{"id":"a","text":"Flexor carpi radialis"},{"id":"b","text":"Flexor carpi ulnaris"},{"id":"c","text":"Palmaris longus"},{"id":"d","text":"Flexor digitorum superficialis"}],"answerId":"b","explanation":"Weakness in wrist flexion with loss of ulnar deviation indicates an issue with the flexor carpi ulnaris, which is innervated by the ulnar nerve.","kind":"clinical","origin":"ai"},{"id":"forearm-flexor-compartment~ai-3","moduleId":"forearm-flexor-compartment","stem":"A patient with AIN syndrome presents with weakness of thumb and index finger flexion but no sensory loss. What differentiates this from carpal tunnel syndrome?","options":[{"id":"a","text":"Presence of sensory loss"},{"id":"b","text":"Weakness of wrist extension"},{"id":"c","text":"Weakness of thumb abduction"},{"id":"d","text":"Purely motor deficit"}],"answerId":"d","explanation":"AIN syndrome is characterized by a purely motor deficit without sensory loss, while carpal tunnel syndrome involves sensory symptoms due to median nerve compression.","kind":"trap","origin":"ai"},{"id":"forearm-flexor-compartment~ai-4","moduleId":"forearm-flexor-compartment","stem":"Which artery is located beneath the brachioradialis muscle in the forearm?","options":[{"id":"a","text":"Ulnar artery"},{"id":"b","text":"Radial artery"},{"id":"c","text":"Brachial artery"},{"id":"d","text":"Anterior interosseous artery"}],"answerId":"b","explanation":"The radial artery runs deep to the brachioradialis muscle, making it accessible for palpation at the distal lateral forearm.","kind":"recall","origin":"ai"},{"id":"forearm-flexor-compartment~ai-5","moduleId":"forearm-flexor-compartment","stem":"How does the structure of flexor digitorum profundus differ in its innervation?","options":[{"id":"a","text":"Entirely by the median nerve"},{"id":"b","text":"Entirely by the ulnar nerve"},{"id":"c","text":"Medial half by ulnar, lateral half by median"},{"id":"d","text":"Innervated by the radial nerve"}],"answerId":"c","explanation":"The flexor digitorum profundus is innervated by the ulnar nerve for its medial half and by the median nerve for its lateral half.","kind":"mechanism","origin":"ai"},{"id":"forearm-flexor-compartment~ai-6","moduleId":"forearm-flexor-compartment","stem":"In a case of a forearm fracture, which structure is most likely to be affected if the patient exhibits an inability to flex the distal phalanx of the index finger?","options":[{"id":"a","text":"Median nerve"},{"id":"b","text":"Ulnar nerve"},{"id":"c","text":"Anterior interosseous nerve"},{"id":"d","text":"Radial nerve"}],"answerId":"c","explanation":"Inability to flex the distal phalanx of the index finger suggests damage to the anterior interosseous nerve, affecting the flexor pollicis longus and the lateral half of flexor digitorum profundus.","kind":"clinical","origin":"ai"},{"id":"forearm-flexor-compartment~ai-7","moduleId":"forearm-flexor-compartment","stem":"How does the anterior forearm compartment relate to the study of amino acids and protein structure?","options":[{"id":"a","text":"Muscle contraction relies on amino acid metabolism"},{"id":"b","text":"Proteins are synthesized in the forearm"},{"id":"c","text":"Amino acids are not relevant to muscle function"},{"id":"d","text":"Proteins do not influence nerve function"}],"answerId":"a","explanation":"Muscle contraction in the forearm involves proteins that are synthesized from amino acids, highlighting the importance of amino acids in muscle function.","kind":"integration","linkedModuleIds":["amino-acids-proteins-structure"],"origin":"ai"},{"id":"forearm-flexor-compartment~ai-8","moduleId":"forearm-flexor-compartment","stem":"Which anatomical structure in the anterior forearm is crucial for understanding the neurovascular supply in the female pelvis?","options":[{"id":"a","text":"Median nerve"},{"id":"b","text":"Ulnar nerve"},{"id":"c","text":"Radial artery"},{"id":"d","text":"Brachial artery"}],"answerId":"a","explanation":"The median nerve's role in the anterior forearm provides insight into the neurovascular supply that can be applied to the female pelvis, where similar nerve pathways exist.","kind":"integration","linkedModuleIds":["hrp1-female-pelvis-neurovascular"],"origin":"ai"}],"forearm-extensor-compartment-snuffbox":[{"id":"forearm-extensor-compartment-snuffbox~ai-0","moduleId":"forearm-extensor-compartment-snuffbox","stem":"Which nerve is responsible for innervating the extensor muscles of the forearm?","options":[{"id":"a","text":"Median nerve"},{"id":"b","text":"Ulnar nerve"},{"id":"c","text":"Radial nerve"},{"id":"d","text":"Musculocutaneous nerve"}],"answerId":"c","explanation":"The radial nerve innervates all the extensor muscles in the posterior forearm.","kind":"recall","origin":"ai"},{"id":"forearm-extensor-compartment-snuffbox~ai-1","moduleId":"forearm-extensor-compartment-snuffbox","stem":"What is the primary clinical finding in posterior interosseous nerve (PIN) palsy?","options":[{"id":"a","text":"Wrist drop"},{"id":"b","text":"Finger drop"},{"id":"c","text":"Loss of wrist sensation"},{"id":"d","text":"Inability to flex fingers"}],"answerId":"b","explanation":"PIN palsy results in finger drop due to weakness in finger and thumb extension, while wrist extension remains intact.","kind":"clinical","origin":"ai"},{"id":"forearm-extensor-compartment-snuffbox~ai-2","moduleId":"forearm-extensor-compartment-snuffbox","stem":"Which structure forms the floor of the anatomical snuffbox?","options":[{"id":"a","text":"Trapezium"},{"id":"b","text":"Scaphoid"},{"id":"c","text":"Radial artery"},{"id":"d","text":"Extensor pollicis longus"}],"answerId":"b","explanation":"The floor of the anatomical snuffbox is formed by the scaphoid and trapezium bones.","kind":"recall","origin":"ai"},{"id":"forearm-extensor-compartment-snuffbox~ai-3","moduleId":"forearm-extensor-compartment-snuffbox","stem":"What is the mechanism of pain in De Quervain tenosynovitis?","options":[{"id":"a","text":"Inflammation of the extensor retinaculum"},{"id":"b","text":"Inflammation of the 1st dorsal compartment tendons"},{"id":"c","text":"Fracture of the scaphoid"},{"id":"d","text":"Radial nerve injury"}],"answerId":"b","explanation":"De Quervain tenosynovitis involves inflammation of the abductor pollicis longus and extensor pollicis brevis tendons in the first dorsal compartment.","kind":"mechanism","origin":"ai"},{"id":"forearm-extensor-compartment-snuffbox~ai-4","moduleId":"forearm-extensor-compartment-snuffbox","stem":"A patient presents with tenderness in the anatomical snuffbox after a fall. What is the most likely diagnosis?","options":[{"id":"a","text":"De Quervain tenosynovitis"},{"id":"b","text":"Scaphoid fracture"},{"id":"c","text":"Radial nerve injury"},{"id":"d","text":"Tennis elbow"}],"answerId":"b","explanation":"Tenderness in the snuffbox after a fall is highly suggestive of a scaphoid fracture.","kind":"clinical","origin":"ai"},{"id":"forearm-extensor-compartment-snuffbox~ai-5","moduleId":"forearm-extensor-compartment-snuffbox","stem":"In a case of PIN palsy, which of the following statements is true?","options":[{"id":"a","text":"Complete wrist drop occurs"},{"id":"b","text":"Sensory loss is present"},{"id":"c","text":"Wrist extension is preserved"},{"id":"d","text":"All finger movements are lost"}],"answerId":"c","explanation":"In PIN palsy, wrist extension is preserved due to the sparing of the extensor carpi radialis longus.","kind":"trap","origin":"ai"},{"id":"forearm-extensor-compartment-snuffbox~ai-6","moduleId":"forearm-extensor-compartment-snuffbox","stem":"How does the anatomical snuffbox relate to carpal bone fractures?","options":[{"id":"a","text":"It is a site for carpal tunnel syndrome"},{"id":"b","text":"It is the location for scaphoid fractures"},{"id":"c","text":"It is where the ulnar nerve is compressed"},{"id":"d","text":"It is the site of wrist sprains"}],"answerId":"b","explanation":"The anatomical snuffbox is clinically relevant for diagnosing scaphoid fractures, especially after falls.","kind":"integration","linkedModuleIds":["radius-ulna-carpals-fractures"],"origin":"ai"},{"id":"forearm-extensor-compartment-snuffbox~ai-7","moduleId":"forearm-extensor-compartment-snuffbox","stem":"Which muscle is NOT part of the superficial extensor group of the forearm?","options":[{"id":"a","text":"Extensor carpi radialis longus"},{"id":"b","text":"Extensor digitorum"},{"id":"c","text":"Extensor pollicis longus"},{"id":"d","text":"Extensor carpi ulnaris"}],"answerId":"c","explanation":"The extensor pollicis longus is part of the deep extensor group, not the superficial group.","kind":"trap","origin":"ai"},{"id":"forearm-extensor-compartment-snuffbox~ai-8","moduleId":"forearm-extensor-compartment-snuffbox","stem":"Which condition is characterized by radial wrist pain and a positive Finkelstein test?","options":[{"id":"a","text":"Tennis elbow"},{"id":"b","text":"Scaphoid fracture"},{"id":"c","text":"De Quervain tenosynovitis"},{"id":"d","text":"PIN palsy"}],"answerId":"c","explanation":"De Quervain tenosynovitis is specifically associated with radial wrist pain and a positive Finkelstein test.","kind":"clinical","origin":"ai"}],"thoracic-wall-intercostal-space":[{"id":"thoracic-wall-intercostal-space~ai-0","moduleId":"thoracic-wall-intercostal-space","stem":"What is the primary function of the intercostal muscles during respiration?","options":[{"id":"a","text":"Increase thoracic volume"},{"id":"b","text":"Decrease thoracic pressure"},{"id":"c","text":"Stabilize the rib cage"},{"id":"d","text":"Facilitate gas exchange"}],"answerId":"a","explanation":"The intercostal muscles contract to elevate the ribs, increasing thoracic volume and aiding in inhalation.","kind":"mechanism","origin":"ai"},{"id":"thoracic-wall-intercostal-space~ai-1","moduleId":"thoracic-wall-intercostal-space","stem":"Which rib is associated with the sternal angle (angle of Louis)?","options":[{"id":"a","text":"Rib 1"},{"id":"b","text":"Rib 2"},{"id":"c","text":"Rib 3"},{"id":"d","text":"Rib 4"}],"answerId":"b","explanation":"The sternal angle is located at the level of rib 2, marking important anatomical landmarks.","kind":"recall","origin":"ai"},{"id":"thoracic-wall-intercostal-space~ai-2","moduleId":"thoracic-wall-intercostal-space","stem":"A patient presents with numbness at the nipple line. Which intercostal nerve is likely affected?","options":[{"id":"a","text":"T2"},{"id":"b","text":"T3"},{"id":"c","text":"T4"},{"id":"d","text":"T5"}],"answerId":"c","explanation":"The nipple line corresponds to the T4 dermatome, indicating a possible issue with the T4 intercostal nerve.","kind":"clinical","origin":"ai"},{"id":"thoracic-wall-intercostal-space~ai-3","moduleId":"thoracic-wall-intercostal-space","stem":"Where should a chest tube be inserted to avoid damaging the neurovascular bundle?","options":[{"id":"a","text":"Just below the rib"},{"id":"b","text":"Just above the rib"},{"id":"c","text":"In the middle of the intercostal space"},{"id":"d","text":"At the sternal angle"}],"answerId":"b","explanation":"A chest tube should be inserted just above the rib to avoid the neurovascular bundle located in the costal groove.","kind":"trap","origin":"ai"},{"id":"thoracic-wall-intercostal-space~ai-4","moduleId":"thoracic-wall-intercostal-space","stem":"What is the consequence of a cervical rib on the brachial plexus?","options":[{"id":"a","text":"Increased blood flow"},{"id":"b","text":"Compression of the lower plexus"},{"id":"c","text":"Improved nerve conduction"},{"id":"d","text":"Enhanced thoracic expansion"}],"answerId":"b","explanation":"A cervical rib can compress the lower brachial plexus, leading to symptoms of thoracic outlet syndrome.","kind":"clinical","origin":"ai"},{"id":"thoracic-wall-intercostal-space~ai-5","moduleId":"thoracic-wall-intercostal-space","stem":"How does the thoracic wall affect lung volumes during ventilation?","options":[{"id":"a","text":"By altering airway resistance"},{"id":"b","text":"By changing pleural pressure"},{"id":"c","text":"By increasing blood flow to the lungs"},{"id":"d","text":"By facilitating gas exchange in alveoli"}],"answerId":"b","explanation":"The thoracic wall movement alters pleural pressure, which is crucial for lung expansion and ventilation.","kind":"integration","linkedModuleIds":["lung-volumes-ventilation"],"origin":"ai"},{"id":"thoracic-wall-intercostal-space~ai-6","moduleId":"thoracic-wall-intercostal-space","stem":"What is the relationship between rib movement and bundle branch block diagnosis?","options":[{"id":"a","text":"Rib movement affects heart rate"},{"id":"b","text":"Rib movement influences electrical conduction"},{"id":"c","text":"Rib movement aids in auscultation"},{"id":"d","text":"Rib movement does not affect diagnosis"}],"answerId":"c","explanation":"Rib movement can affect lung and heart sounds, aiding in the auscultation necessary for diagnosing bundle branch blocks.","kind":"integration","linkedModuleIds":["bundle-branch-block"],"origin":"ai"}],"heart-chambers-pericardium":[{"id":"heart-chambers-pericardium~ai-0","moduleId":"heart-chambers-pericardium","stem":"What is the primary function of the moderator band in the right ventricle?","options":[{"id":"a","text":"To support the tricuspid valve"},{"id":"b","text":"To carry the right bundle branch"},{"id":"c","text":"To facilitate blood ejection"},{"id":"d","text":"To separate the atrium from the ventricle"}],"answerId":"b","explanation":"The moderator band carries the right bundle branch to the anterior papillary muscle, aiding in rapid conduction.","kind":"mechanism","origin":"ai"},{"id":"heart-chambers-pericardium~ai-1","moduleId":"heart-chambers-pericardium","stem":"Which structure separates the smooth part of the right atrium from the trabeculated part?","options":[{"id":"a","text":"Fossa ovalis"},{"id":"b","text":"Crista terminalis"},{"id":"c","text":"Triangle of Koch"},{"id":"d","text":"Pectinate muscle"}],"answerId":"b","explanation":"The crista terminalis is the ridge that separates the smooth sinus venarum from the pectinate muscle in the right atrium.","kind":"recall","origin":"ai"},{"id":"heart-chambers-pericardium~ai-2","moduleId":"heart-chambers-pericardium","stem":"A patient presents with muffled heart sounds, hypotension, and distended neck veins. What is the most likely diagnosis?","options":[{"id":"a","text":"Heart failure"},{"id":"b","text":"Cardiac tamponade"},{"id":"c","text":"Pulmonary embolism"},{"id":"d","text":"Aortic dissection"}],"answerId":"b","explanation":"These findings are classic for cardiac tamponade, known as Beck's triad.","kind":"clinical","origin":"ai"},{"id":"heart-chambers-pericardium~ai-3","moduleId":"heart-chambers-pericardium","stem":"Where is the apex beat typically palpated?","options":[{"id":"a","text":"Right 5th intercostal space"},{"id":"b","text":"Left 5th intercostal space"},{"id":"c","text":"Left 4th intercostal space"},{"id":"d","text":"Right 4th intercostal space"}],"answerId":"b","explanation":"The apex beat is normally located at the left 5th intercostal space in the midclavicular line.","kind":"recall","origin":"ai"},{"id":"heart-chambers-pericardium~ai-4","moduleId":"heart-chambers-pericardium","stem":"Which of the following structures is NOT a feature of the left ventricle?","options":[{"id":"a","text":"Thick muscular wall"},{"id":"b","text":"Trabeculae carneae"},{"id":"c","text":"Moderator band"},{"id":"d","text":"Aortic outflow tract"}],"answerId":"c","explanation":"The moderator band is a feature of the right ventricle, not the left ventricle.","kind":"trap","origin":"ai"},{"id":"heart-chambers-pericardium~ai-5","moduleId":"heart-chambers-pericardium","stem":"How does the pericardial cavity contribute to heart function?","options":[{"id":"a","text":"Provides structural support"},{"id":"b","text":"Allows for electrical conduction"},{"id":"c","text":"Reduces friction during heart movement"},{"id":"d","text":"Stores blood"}],"answerId":"c","explanation":"The pericardial cavity contains fluid that reduces friction as the heart beats.","kind":"mechanism","origin":"ai"},{"id":"heart-chambers-pericardium~ai-6","moduleId":"heart-chambers-pericardium","stem":"How does the anatomy of the left atrium relate to pulmonary circulation?","options":[{"id":"a","text":"It receives deoxygenated blood from the lungs"},{"id":"b","text":"It receives oxygenated blood from the pulmonary veins"},{"id":"c","text":"It pumps blood to the aorta"},{"id":"d","text":"It contains the moderator band"}],"answerId":"b","explanation":"The left atrium receives oxygenated blood from the four pulmonary veins, connecting it to pulmonary circulation.","kind":"integration","linkedModuleIds":["heart-anatomy-chambers-valves"],"origin":"ai"},{"id":"heart-chambers-pericardium~ai-7","moduleId":"heart-chambers-pericardium","stem":"What is the significance of the triangle of Koch in cardiac anatomy?","options":[{"id":"a","text":"It is a landmark for the left ventricle"},{"id":"b","text":"It marks the location of the AV node"},{"id":"c","text":"It separates the atria from the ventricles"},{"id":"d","text":"It is involved in the pulmonary circulation"}],"answerId":"b","explanation":"The triangle of Koch is an important anatomical landmark that indicates the location of the AV node.","kind":"integration","linkedModuleIds":["heart-anatomy-chambers-valves"],"origin":"ai"}],"mediastinum-divisions-contents":[{"id":"mediastinum-divisions-contents~ai-0","moduleId":"mediastinum-divisions-contents","stem":"Which structure is NOT found in the superior mediastinum?","options":[{"id":"a","text":"Thymus"},{"id":"b","text":"Trachea"},{"id":"c","text":"Esophagus"},{"id":"d","text":"Brachiocephalic veins"}],"answerId":"a","explanation":"The thymus is located in the anterior mediastinum, not the superior mediastinum.","kind":"recall","origin":"ai"},{"id":"mediastinum-divisions-contents~ai-1","moduleId":"mediastinum-divisions-contents","stem":"What is the primary function of the thoracic duct?","options":[{"id":"a","text":"Drain lymph from the right arm"},{"id":"b","text":"Drain lymph from the left side of the body"},{"id":"c","text":"Transport oxygenated blood"},{"id":"d","text":"Transport deoxygenated blood"}],"answerId":"b","explanation":"The thoracic duct drains lymph from the left side of the body and lower limbs into the venous system.","kind":"mechanism","origin":"ai"},{"id":"mediastinum-divisions-contents~ai-2","moduleId":"mediastinum-divisions-contents","stem":"A patient presents with an anterior mediastinal mass. Which of the following is the most likely diagnosis?","options":[{"id":"a","text":"Thymoma"},{"id":"b","text":"Aortic aneurysm"},{"id":"c","text":"Pulmonary embolism"},{"id":"d","text":"Lung carcinoma"}],"answerId":"a","explanation":"The 4 T's of anterior mediastinal masses include Thymoma, Teratoma, Thyroid, and 'Terrible' lymphoma, with Thymoma being the most common.","kind":"clinical","origin":"ai"},{"id":"mediastinum-divisions-contents~ai-3","moduleId":"mediastinum-divisions-contents","stem":"At which vertebral level does the esophagus pass through the diaphragm?","options":[{"id":"a","text":"T8"},{"id":"b","text":"T10"},{"id":"c","text":"T12"},{"id":"d","text":"L1"}],"answerId":"b","explanation":"The esophagus, along with the vagal trunks, passes through the diaphragm at T10.","kind":"trap","origin":"ai"},{"id":"mediastinum-divisions-contents~ai-4","moduleId":"mediastinum-divisions-contents","stem":"Which structure is located in the middle mediastinum?","options":[{"id":"a","text":"Thymus"},{"id":"b","text":"Heart"},{"id":"c","text":"Azygos vein"},{"id":"d","text":"Esophagus"}],"answerId":"b","explanation":"The heart is located in the middle mediastinum, while the thymus is in the anterior mediastinum and the esophagus is in the posterior mediastinum.","kind":"recall","origin":"ai"},{"id":"mediastinum-divisions-contents~ai-5","moduleId":"mediastinum-divisions-contents","stem":"How does the sternal angle relate to the aortic arch?","options":[{"id":"a","text":"It marks the start of the aortic arch"},{"id":"b","text":"It marks the end of the aortic arch"},{"id":"c","text":"It is located at the level of the aortic arch"},{"id":"d","text":"It has no relation to the aortic arch"}],"answerId":"a","explanation":"The sternal angle marks the start of the aortic arch at the T4-T5 level.","kind":"mechanism","origin":"ai"},{"id":"mediastinum-divisions-contents~ai-6","moduleId":"mediastinum-divisions-contents","stem":"How are the great vessels and mediastinal nerves related to the mediastinum's divisions?","options":[{"id":"a","text":"They are only found in the superior mediastinum"},{"id":"b","text":"They are only found in the inferior mediastinum"},{"id":"c","text":"They are found in both the superior and inferior mediastinum"},{"id":"d","text":"They are not related to the mediastinum's divisions"}],"answerId":"c","explanation":"The great vessels are located in both the superior and middle mediastinum, while mediastinal nerves traverse through various divisions.","kind":"integration","linkedModuleIds":["great-vessels-mediastinal-nerves"],"origin":"ai"},{"id":"mediastinum-divisions-contents~ai-7","moduleId":"mediastinum-divisions-contents","stem":"Which of the following best describes the relationship between the heart and the pericardium?","options":[{"id":"a","text":"The heart is anterior to the pericardium"},{"id":"b","text":"The heart is posterior to the pericardium"},{"id":"c","text":"The heart is contained within the pericardium"},{"id":"d","text":"The heart is separate from the pericardium"}],"answerId":"c","explanation":"The heart is contained within the pericardium, which is located in the middle mediastinum.","kind":"integration","linkedModuleIds":["heart-valves-coronary-supply"],"origin":"ai"}],"pleura-pleural-cavity":[{"id":"pleura-pleural-cavity~ai-0","moduleId":"pleura-pleural-cavity","stem":"What is the primary function of the pleural cavity?","options":[{"id":"a","text":"To provide structural support to the lungs"},{"id":"b","text":"To allow for lung expansion and contraction"},{"id":"c","text":"To produce surfactant"},{"id":"d","text":"To facilitate gas exchange"}],"answerId":"b","explanation":"The pleural cavity creates a negative pressure environment that allows for lung expansion during inhalation.","kind":"recall","origin":"ai"},{"id":"pleura-pleural-cavity~ai-1","moduleId":"pleura-pleural-cavity","stem":"Which layer of the pleura is responsible for pleuritic pain?","options":[{"id":"a","text":"Visceral pleura"},{"id":"b","text":"Parietal pleura"},{"id":"c","text":"Pleural cavity"},{"id":"d","text":"Costodiaphragmatic recess"}],"answerId":"b","explanation":"Pleuritic pain arises from the parietal pleura due to its somatic innervation.","kind":"recall","origin":"ai"},{"id":"pleura-pleural-cavity~ai-2","moduleId":"pleura-pleural-cavity","stem":"A patient presents with sharp chest pain that worsens on inspiration and a pleural friction rub is heard on examination. What is the most likely diagnosis?","options":[{"id":"a","text":"Pneumothorax"},{"id":"b","text":"Pleural effusion"},{"id":"c","text":"Parietal pleuritis"},{"id":"d","text":"Visceral pleuritis"}],"answerId":"c","explanation":"The symptoms and findings are characteristic of parietal pleuritis, which is associated with somatic pain.","kind":"clinical","origin":"ai"},{"id":"pleura-pleural-cavity~ai-3","moduleId":"pleura-pleural-cavity","stem":"What is the most common site for pleural effusions to collect?","options":[{"id":"a","text":"Costomediastinal recess"},{"id":"b","text":"Costodiaphragmatic recess"},{"id":"c","text":"Visceral pleura"},{"id":"d","text":"Parietal pleura"}],"answerId":"b","explanation":"The costodiaphragmatic recess is the deepest part of the pleural cavity and is where fluid typically accumulates.","kind":"recall","origin":"ai"},{"id":"pleura-pleural-cavity~ai-4","moduleId":"pleura-pleural-cavity","stem":"During thoracentesis, which anatomical landmark should be avoided to prevent injury to abdominal organs?","options":[{"id":"a","text":"Above the 8th intercostal space"},{"id":"b","text":"Below the 8th intercostal space"},{"id":"c","text":"At the midclavicular line"},{"id":"d","text":"At the posterior axillary line"}],"answerId":"a","explanation":"Thoracentesis should be performed above the 8th intercostal space to avoid damaging the diaphragm and underlying abdominal organs.","kind":"trap","origin":"ai"},{"id":"pleura-pleural-cavity~ai-5","moduleId":"pleura-pleural-cavity","stem":"A patient with a pleural effusion is found to have dullness at the lung base with a meniscus on X-ray. What is the most likely mechanism of this finding?","options":[{"id":"a","text":"Air in the pleural cavity"},{"id":"b","text":"Fluid accumulation in the costodiaphragmatic recess"},{"id":"c","text":"Inflammation of the visceral pleura"},{"id":"d","text":"Consolidation of lung tissue"}],"answerId":"b","explanation":"Dullness and a meniscus on X-ray indicate fluid accumulation in the pleural space, particularly in the costodiaphragmatic recess.","kind":"mechanism","origin":"ai"},{"id":"pleura-pleural-cavity~ai-6","moduleId":"pleura-pleural-cavity","stem":"How does diaphragmatic irritation manifest in terms of referred pain?","options":[{"id":"a","text":"Pain in the chest wall"},{"id":"b","text":"Shoulder-tip pain"},{"id":"c","text":"Abdominal pain"},{"id":"d","text":"Back pain"}],"answerId":"b","explanation":"Irritation of the central diaphragmatic pleura, innervated by the phrenic nerve, refers pain to the shoulder tip.","kind":"clinical","origin":"ai"},{"id":"pleura-pleural-cavity~ai-7","moduleId":"pleura-pleural-cavity","stem":"In a patient with a pneumothorax, which structure is primarily affected?","options":[{"id":"a","text":"Visceral pleura"},{"id":"b","text":"Parietal pleura"},{"id":"c","text":"Pleural cavity"},{"id":"d","text":"Diaphragm"}],"answerId":"a","explanation":"A pneumothorax involves air entering the pleural cavity, affecting the visceral pleura and leading to lung collapse.","kind":"recall","origin":"ai"},{"id":"pleura-pleural-cavity~ai-8","moduleId":"pleura-pleural-cavity","stem":"How does the knowledge of pleural effusion relate to the thoracic wall and intercostal space?","options":[{"id":"a","text":"It helps in understanding the anatomy of the diaphragm"},{"id":"b","text":"It aids in identifying the innervation of the parietal pleura"},{"id":"c","text":"It is crucial for performing thoracentesis safely"},{"id":"d","text":"It explains the mechanics of breathing"}],"answerId":"c","explanation":"Understanding the anatomy of the thoracic wall and intercostal spaces is essential for safely performing thoracentesis in cases of pleural effusion.","kind":"integration","linkedModuleIds":["thoracic-wall-intercostal-space"],"origin":"ai"},{"id":"pleura-pleural-cavity~ai-9","moduleId":"pleura-pleural-cavity","stem":"What is the significance of the visceral pleura being insensitive to pain in the context of pleural disease?","options":[{"id":"a","text":"It indicates that visceral pleura cannot be inflamed"},{"id":"b","text":"It explains why pleuritic pain is sharp"},{"id":"c","text":"It helps differentiate between types of pleuritis"},{"id":"d","text":"It shows that visceral pleura does not participate in gas exchange"}],"answerId":"c","explanation":"The lack of pain sensation in the visceral pleura helps differentiate between parietal and visceral pleuritis, aiding in clinical diagnosis.","kind":"integration","linkedModuleIds":["pleural-effusion-pneumothorax-mesothelioma"],"origin":"ai"}],"skull-bones-sutures":[{"id":"skull-bones-sutures~ai-0","moduleId":"skull-bones-sutures","stem":"Which of the following bones is NOT part of the neurocranium?","options":[{"id":"a","text":"Frontal"},{"id":"b","text":"Parietal"},{"id":"c","text":"Maxilla"},{"id":"d","text":"Occipital"}],"answerId":"c","explanation":"The maxilla is part of the viscerocranium, not the neurocranium.","kind":"recall","origin":"ai"},{"id":"skull-bones-sutures~ai-1","moduleId":"skull-bones-sutures","stem":"What is the clinical significance of the pterion?","options":[{"id":"a","text":"It is the site of the TMJ articulation"},{"id":"b","text":"It is the thinnest part of the skull"},{"id":"c","text":"It contains the anterior fontanelle"},{"id":"d","text":"It is a site of venous drainage"}],"answerId":"b","explanation":"The pterion is the thinnest part of the lateral skull and is at risk for fracture leading to an epidural hematoma.","kind":"mechanism","origin":"ai"},{"id":"skull-bones-sutures~ai-2","moduleId":"skull-bones-sutures","stem":"A 3-month-old infant presents with a bulging anterior fontanelle. What is the most likely underlying cause?","options":[{"id":"a","text":"Dehydration"},{"id":"b","text":"Normal development"},{"id":"c","text":"Raised intracranial pressure"},{"id":"d","text":"Craniosynostosis"}],"answerId":"c","explanation":"A bulging anterior fontanelle typically indicates raised intracranial pressure.","kind":"clinical","origin":"ai"},{"id":"skull-bones-sutures~ai-3","moduleId":"skull-bones-sutures","stem":"Which suture separates the parietal bones?","options":[{"id":"a","text":"Coronal"},{"id":"b","text":"Sagittal"},{"id":"c","text":"Lambdoid"},{"id":"d","text":"Pterion"}],"answerId":"b","explanation":"The sagittal suture runs between the two parietal bones.","kind":"recall","origin":"ai"},{"id":"skull-bones-sutures~ai-4","moduleId":"skull-bones-sutures","stem":"What is the consequence of a fracture at the pterion?","options":[{"id":"a","text":"Tear of the anterior fontanelle"},{"id":"b","text":"Epidural hematoma due to middle meningeal artery injury"},{"id":"c","text":"Injury to the TMJ"},{"id":"d","text":"Fracture of the occipital bone"}],"answerId":"b","explanation":"A fracture at the pterion can tear the middle meningeal artery, leading to an epidural hematoma.","kind":"trap","origin":"ai"},{"id":"skull-bones-sutures~ai-5","moduleId":"skull-bones-sutures","stem":"How does the anterior fontanelle assist in clinical assessment?","options":[{"id":"a","text":"Indicates dehydration"},{"id":"b","text":"Assesses cranial nerve function"},{"id":"c","text":"Monitors intracranial pressure"},{"id":"d","text":"Evaluates facial symmetry"}],"answerId":"c","explanation":"The anterior fontanelle can bulge or sink, indicating changes in intracranial pressure.","kind":"clinical","origin":"ai"},{"id":"skull-bones-sutures~ai-6","moduleId":"skull-bones-sutures","stem":"Which cranial fossa contains the middle meningeal artery?","options":[{"id":"a","text":"Anterior fossa"},{"id":"b","text":"Middle fossa"},{"id":"c","text":"Posterior fossa"},{"id":"d","text":"None of the above"}],"answerId":"b","explanation":"The middle meningeal artery runs through the middle cranial fossa and is at risk during pterion fractures.","kind":"integration","linkedModuleIds":["cranial-fossae-foramina"],"origin":"ai"},{"id":"skull-bones-sutures~ai-7","moduleId":"skull-bones-sutures","stem":"What is the primary function of the dural venous sinuses in relation to the skull?","options":[{"id":"a","text":"Support cranial bones"},{"id":"b","text":"Drain cerebrospinal fluid"},{"id":"c","text":"Drain blood from the brain"},{"id":"d","text":"Protect against skull fractures"}],"answerId":"c","explanation":"Dural venous sinuses primarily drain venous blood from the brain.","kind":"integration","linkedModuleIds":["meninges-dural-sinuses"],"origin":"ai"}],"thyroid-root-of-neck":[{"id":"thyroid-root-of-neck~ai-0","moduleId":"thyroid-root-of-neck","stem":"Which artery supplies the majority of blood to the thyroid gland?","options":[{"id":"a","text":"Superior thyroid artery"},{"id":"b","text":"Inferior thyroid artery"},{"id":"c","text":"Thyroid ima artery"},{"id":"d","text":"Vertebral artery"}],"answerId":"a","explanation":"The superior thyroid artery, a branch of the external carotid artery, primarily supplies blood to the thyroid gland.","kind":"recall","origin":"ai"},{"id":"thyroid-root-of-neck~ai-1","moduleId":"thyroid-root-of-neck","stem":"What is the consequence of unilateral injury to the recurrent laryngeal nerve?","options":[{"id":"a","text":"Stridor"},{"id":"b","text":"Hoarse voice"},{"id":"c","text":"Inability to raise pitch"},{"id":"d","text":"Airway obstruction"}],"answerId":"b","explanation":"Unilateral injury to the recurrent laryngeal nerve results in a hoarse or breathy voice due to impaired vocal cord function.","kind":"clinical","origin":"ai"},{"id":"thyroid-root-of-neck~ai-2","moduleId":"thyroid-root-of-neck","stem":"Which nerve is most at risk during a thyroidectomy due to its proximity to the inferior thyroid artery?","options":[{"id":"a","text":"External laryngeal nerve"},{"id":"b","text":"Vagus nerve"},{"id":"c","text":"Recurrent laryngeal nerve"},{"id":"d","text":"Phrenic nerve"}],"answerId":"c","explanation":"The recurrent laryngeal nerve runs closely to the inferior thyroid artery, making it susceptible to injury during thyroid surgery.","kind":"trap","origin":"ai"},{"id":"thyroid-root-of-neck~ai-3","moduleId":"thyroid-root-of-neck","stem":"What is the primary function of the external laryngeal nerve?","options":[{"id":"a","text":"Sensory innervation to the vocal cords"},{"id":"b","text":"Motor innervation to cricothyroid muscle"},{"id":"c","text":"Motor innervation to all intrinsic laryngeal muscles"},{"id":"d","text":"Sensory innervation above the vocal folds"}],"answerId":"b","explanation":"The external laryngeal nerve provides motor innervation to the cricothyroid muscle, which is essential for pitch modulation.","kind":"recall","origin":"ai"},{"id":"thyroid-root-of-neck~ai-4","moduleId":"thyroid-root-of-neck","stem":"A patient presents with stridor after thyroid surgery. What is the most likely cause?","options":[{"id":"a","text":"Unilateral recurrent laryngeal nerve injury"},{"id":"b","text":"Bilateral recurrent laryngeal nerve injury"},{"id":"c","text":"External laryngeal nerve injury"},{"id":"d","text":"Phrenic nerve injury"}],"answerId":"b","explanation":"Bilateral injury to the recurrent laryngeal nerve can lead to airway obstruction and stridor due to impaired vocal cord function.","kind":"clinical","origin":"ai"},{"id":"thyroid-root-of-neck~ai-5","moduleId":"thyroid-root-of-neck","stem":"How does the thoracic duct's location relate to the root of the neck?","options":[{"id":"a","text":"It ends at the junction of the right subclavian and right internal jugular veins"},{"id":"b","text":"It ends at the junction of the left subclavian and left internal jugular veins"},{"id":"c","text":"It runs anterior to the subclavian artery"},{"id":"d","text":"It is located posterior to the phrenic nerve"}],"answerId":"b","explanation":"The thoracic duct drains into the venous system at the junction of the left subclavian and left internal jugular veins.","kind":"integration","linkedModuleIds":["neck-triangles-fascia"],"origin":"ai"},{"id":"thyroid-root-of-neck~ai-6","moduleId":"thyroid-root-of-neck","stem":"Which structure is closely associated with the cervical sympathetic trunk in the root of the neck?","options":[{"id":"a","text":"Phrenic nerve"},{"id":"b","text":"Vagus nerve"},{"id":"c","text":"Subclavian artery"},{"id":"d","text":"Recurrent laryngeal nerve"}],"answerId":"c","explanation":"The cervical sympathetic trunk runs adjacent to the subclavian artery in the root of the neck, influencing sympathetic innervation.","kind":"integration","linkedModuleIds":["hen1-adrenal-gross-anatomy-vasculature"],"origin":"ai"}],"infratemporal-fossa-nerves-vessels":[{"id":"infratemporal-fossa-nerves-vessels~ai-0","moduleId":"infratemporal-fossa-nerves-vessels","stem":"Which nerve carries general sensation from the anterior 2/3 of the tongue?","options":[{"id":"a","text":"Lingual nerve"},{"id":"b","text":"Chorda tympani"},{"id":"c","text":"Inferior alveolar nerve"},{"id":"d","text":"Auriculotemporal nerve"}],"answerId":"a","explanation":"The lingual nerve (V3) is responsible for general sensation from the anterior 2/3 of the tongue.","kind":"recall","origin":"ai"},{"id":"infratemporal-fossa-nerves-vessels~ai-1","moduleId":"infratemporal-fossa-nerves-vessels","stem":"What is the primary function of the inferior alveolar nerve?","options":[{"id":"a","text":"Taste sensation from the anterior tongue"},{"id":"b","text":"Motor innervation to mastication muscles"},{"id":"c","text":"General sensation from lower teeth"},{"id":"d","text":"Sensory innervation to the parotid gland"}],"answerId":"c","explanation":"The inferior alveolar nerve provides general sensation to the lower teeth.","kind":"recall","origin":"ai"},{"id":"infratemporal-fossa-nerves-vessels~ai-2","moduleId":"infratemporal-fossa-nerves-vessels","stem":"What complication can occur from a posteriorly misplaced inferior alveolar nerve block?","options":[{"id":"a","text":"Trismus"},{"id":"b","text":"Numbness of the lower lip"},{"id":"c","text":"Facial droop"},{"id":"d","text":"Loss of taste in the anterior tongue"}],"answerId":"c","explanation":"A posteriorly misplaced block can anesthetize CN VII in the parotid, leading to facial droop.","kind":"trap","origin":"ai"},{"id":"infratemporal-fossa-nerves-vessels~ai-3","moduleId":"infratemporal-fossa-nerves-vessels","stem":"Which artery is a branch of the maxillary artery's second part?","options":[{"id":"a","text":"Middle meningeal artery"},{"id":"b","text":"Inferior alveolar artery"},{"id":"c","text":"Masseteric artery"},{"id":"d","text":"Buccal artery"}],"answerId":"c","explanation":"The masseteric artery is a muscular branch from the second part of the maxillary artery.","kind":"recall","origin":"ai"},{"id":"infratemporal-fossa-nerves-vessels~ai-4","moduleId":"infratemporal-fossa-nerves-vessels","stem":"How does the chorda tympani contribute to taste sensation?","options":[{"id":"a","text":"Carries general sensation from the anterior tongue"},{"id":"b","text":"Joins the lingual nerve for taste"},{"id":"c","text":"Innervates the parotid gland"},{"id":"d","text":"Provides motor innervation to mastication muscles"}],"answerId":"b","explanation":"The chorda tympani carries taste fibers from the anterior 2/3 of the tongue and joins the lingual nerve.","kind":"mechanism","origin":"ai"},{"id":"infratemporal-fossa-nerves-vessels~ai-5","moduleId":"infratemporal-fossa-nerves-vessels","stem":"A patient presents with loss of taste and sensation in the anterior 2/3 of the tongue. Which nerve is likely affected?","options":[{"id":"a","text":"Lingual nerve"},{"id":"b","text":"Inferior alveolar nerve"},{"id":"c","text":"Chorda tympani"},{"id":"d","text":"Auriculotemporal nerve"}],"answerId":"a","explanation":"The lingual nerve, along with the chorda tympani, is responsible for both general sensation and taste in the anterior 2/3 of the tongue.","kind":"clinical","origin":"ai"},{"id":"infratemporal-fossa-nerves-vessels~ai-6","moduleId":"infratemporal-fossa-nerves-vessels","stem":"How might an inferior alveolar nerve block affect the muscles of mastication?","options":[{"id":"a","text":"Increases muscle tone"},{"id":"b","text":"Causes muscle paralysis"},{"id":"c","text":"Enhances sensory feedback"},{"id":"d","text":"Has no effect on muscles"}],"answerId":"b","explanation":"An inferior alveolar nerve block can lead to temporary paralysis of the muscles of mastication due to loss of motor innervation.","kind":"integration","linkedModuleIds":["tmj-muscles-mastication"],"origin":"ai"},{"id":"infratemporal-fossa-nerves-vessels~ai-7","moduleId":"infratemporal-fossa-nerves-vessels","stem":"What is the relationship between the pterygoid venous plexus and the cavernous sinus?","options":[{"id":"a","text":"Direct arterial supply"},{"id":"b","text":"Valveless communication"},{"id":"c","text":"Sensory innervation"},{"id":"d","text":"Motor control"}],"answerId":"b","explanation":"The pterygoid venous plexus has valveless communication with the cavernous sinus, allowing for potential infection spread.","kind":"integration","linkedModuleIds":["pterygopalatine-fossa"],"origin":"ai"}],"great-vessels-mediastinal-nerves":[{"id":"great-vessels-mediastinal-nerves~ai-0","moduleId":"great-vessels-mediastinal-nerves","stem":"Which of the following structures is NOT a branch of the arch of the aorta?","options":[{"id":"a","text":"Brachiocephalic trunk"},{"id":"b","text":"Left common carotid artery"},{"id":"c","text":"Left subclavian artery"},{"id":"d","text":"Pulmonary artery"}],"answerId":"d","explanation":"The pulmonary artery is not a branch of the arch of the aorta; it arises from the right ventricle.","kind":"recall","origin":"ai"},{"id":"great-vessels-mediastinal-nerves~ai-1","moduleId":"great-vessels-mediastinal-nerves","stem":"What is the primary function of the left recurrent laryngeal nerve?","options":[{"id":"a","text":"Motor innervation to the diaphragm"},{"id":"b","text":"Sensory innervation to the pharynx"},{"id":"c","text":"Motor innervation to the larynx"},{"id":"d","text":"Sensory innervation to the trachea"}],"answerId":"c","explanation":"The left recurrent laryngeal nerve provides motor innervation to the intrinsic muscles of the larynx, except the cricothyroid.","kind":"recall","origin":"ai"},{"id":"great-vessels-mediastinal-nerves~ai-2","moduleId":"great-vessels-mediastinal-nerves","stem":"A patient presents with hoarseness after a lung tumor is discovered near the aortic arch. Which nerve is likely compressed?","options":[{"id":"a","text":"Right recurrent laryngeal nerve"},{"id":"b","text":"Left recurrent laryngeal nerve"},{"id":"c","text":"Phrenic nerve"},{"id":"d","text":"Vagus nerve"}],"answerId":"b","explanation":"The left recurrent laryngeal nerve loops under the aortic arch and can be compressed by a mass in that area, leading to hoarseness.","kind":"clinical","origin":"ai"},{"id":"great-vessels-mediastinal-nerves~ai-3","moduleId":"great-vessels-mediastinal-nerves","stem":"Which nerve provides motor and sensory supply to the diaphragm?","options":[{"id":"a","text":"Vagus nerve"},{"id":"b","text":"Phrenic nerve"},{"id":"c","text":"Left recurrent laryngeal nerve"},{"id":"d","text":"Accessory nerve"}],"answerId":"b","explanation":"The phrenic nerve (C3-C5) is responsible for motor and sensory innervation to the diaphragm.","kind":"recall","origin":"ai"},{"id":"great-vessels-mediastinal-nerves~ai-4","moduleId":"great-vessels-mediastinal-nerves","stem":"A patient presents with distended neck veins and chest wall veins due to SVC obstruction. Which collateral pathway is primarily involved?","options":[{"id":"a","text":"Azygos vein"},{"id":"b","text":"Hemiazygos vein"},{"id":"c","text":"Internal thoracic vein"},{"id":"d","text":"Subclavian vein"}],"answerId":"a","explanation":"The azygos vein provides a collateral pathway for venous drainage in cases of SVC obstruction.","kind":"clinical","origin":"ai"},{"id":"great-vessels-mediastinal-nerves~ai-5","moduleId":"great-vessels-mediastinal-nerves","stem":"In a patient with a mediastinal mass, which nerve is most likely to be affected first if the mass is located near the lung root?","options":[{"id":"a","text":"Vagus nerve"},{"id":"b","text":"Phrenic nerve"},{"id":"c","text":"Left recurrent laryngeal nerve"},{"id":"d","text":"Right recurrent laryngeal nerve"}],"answerId":"b","explanation":"The phrenic nerve passes anterior to the lung root and is likely to be affected first by a mass in that area.","kind":"trap","origin":"ai"},{"id":"great-vessels-mediastinal-nerves~ai-6","moduleId":"great-vessels-mediastinal-nerves","stem":"How does the anatomy of the thoracic duct relate to the great vessels?","options":[{"id":"a","text":"It drains into the right subclavian vein"},{"id":"b","text":"It ascends in the anterior mediastinum"},{"id":"c","text":"It crosses from right to left at T5"},{"id":"d","text":"It is located posterior to the aortic arch"}],"answerId":"c","explanation":"The thoracic duct ascends in the posterior mediastinum and crosses from right to left at approximately T5.","kind":"integration","linkedModuleIds":["mediastinum-divisions-contents"],"origin":"ai"},{"id":"great-vessels-mediastinal-nerves~ai-7","moduleId":"great-vessels-mediastinal-nerves","stem":"Which structure could compress the phrenic nerve leading to an elevated hemidiaphragm?","options":[{"id":"a","text":"Aortic arch aneurysm"},{"id":"b","text":"Lung tumor"},{"id":"c","text":"Esophageal mass"},{"id":"d","text":"Thyroid enlargement"}],"answerId":"b","explanation":"A lung tumor can compress the phrenic nerve, resulting in paralysis of the diaphragm and an elevated hemidiaphragm.","kind":"integration","linkedModuleIds":["mediastinal-masses"],"origin":"ai"}],"trachea-bronchi-lungs":[{"id":"trachea-bronchi-lungs~ai-0","moduleId":"trachea-bronchi-lungs","stem":"What structure marks the bifurcation of the trachea into the main bronchi?","options":[{"id":"a","text":"Cricoid cartilage"},{"id":"b","text":"Carina"},{"id":"c","text":"Sternal angle"},{"id":"d","text":"T4 vertebra"}],"answerId":"b","explanation":"The trachea bifurcates at the carina, which is located at the sternal angle (T4–T5).","kind":"recall","origin":"ai"},{"id":"trachea-bronchi-lungs~ai-1","moduleId":"trachea-bronchi-lungs","stem":"Which feature of the right main bronchus contributes to a higher incidence of aspiration pneumonia in the right lung?","options":[{"id":"a","text":"It is longer than the left bronchus"},{"id":"b","text":"It has a more horizontal orientation"},{"id":"c","text":"It is wider and more vertical"},{"id":"d","text":"It has more cartilage rings"}],"answerId":"c","explanation":"The right main bronchus is wider, shorter, and more vertical, making it the path of least resistance for aspirated objects.","kind":"mechanism","origin":"ai"},{"id":"trachea-bronchi-lungs~ai-2","moduleId":"trachea-bronchi-lungs","stem":"A patient presents with an aspirated object lodged in the right lung. Which anatomical feature explains this finding?","options":[{"id":"a","text":"Left main bronchus is longer"},{"id":"b","text":"Right main bronchus is wider"},{"id":"c","text":"Left lung has more lobes"},{"id":"d","text":"Right lung has more segments"}],"answerId":"b","explanation":"The right main bronchus's wider and more vertical structure predisposes it to receive aspirated objects.","kind":"clinical","origin":"ai"},{"id":"trachea-bronchi-lungs~ai-3","moduleId":"trachea-bronchi-lungs","stem":"Which of the following statements about the bronchopulmonary segments is true?","options":[{"id":"a","text":"Each segment has its own bronchus and artery"},{"id":"b","text":"Segments are not functionally independent"},{"id":"c","text":"There are 10 segments in the left lung"},{"id":"d","text":"All segments must be removed in lung surgery"}],"answerId":"a","explanation":"Each bronchopulmonary segment is a functional unit with its own bronchus and artery, allowing for segmental resections.","kind":"trap","origin":"ai"},{"id":"trachea-bronchi-lungs~ai-4","moduleId":"trachea-bronchi-lungs","stem":"Which structure provides oxygenated blood to the left atrium?","options":[{"id":"a","text":"Pulmonary arteries"},{"id":"b","text":"Bronchial arteries"},{"id":"c","text":"Pulmonary veins"},{"id":"d","text":"Aorta"}],"answerId":"c","explanation":"The four pulmonary veins carry oxygenated blood from the lungs to the left atrium.","kind":"recall","origin":"ai"},{"id":"trachea-bronchi-lungs~ai-5","moduleId":"trachea-bronchi-lungs","stem":"How does the sympathetic innervation affect the bronchial tree?","options":[{"id":"a","text":"Causes bronchoconstriction"},{"id":"b","text":"Increases mucus secretion"},{"id":"c","text":"Promotes bronchodilation"},{"id":"d","text":"Decreases blood flow to lungs"}],"answerId":"c","explanation":"Sympathetic stimulation leads to bronchodilation, allowing for increased airflow.","kind":"mechanism","origin":"ai"},{"id":"trachea-bronchi-lungs~ai-6","moduleId":"trachea-bronchi-lungs","stem":"How does the anatomy of the trachea and bronchi relate to the lymphatic drainage of the lungs?","options":[{"id":"a","text":"Lymphatics drain into the aorta"},{"id":"b","text":"Lymphatics follow the bronchial tree"},{"id":"c","text":"Lymphatics are independent of bronchial structures"},{"id":"d","text":"Lymphatics only drain the right lung"}],"answerId":"b","explanation":"Lymphatic drainage of the lungs follows the bronchial tree, passing through various lymph nodes.","kind":"integration","linkedModuleIds":["hrp1-breast-gross-lymphatic-anatomy"],"origin":"ai"},{"id":"trachea-bronchi-lungs~ai-7","moduleId":"trachea-bronchi-lungs","stem":"What is the significance of the cardiac notch in the left lung?","options":[{"id":"a","text":"It accommodates the right atrium"},{"id":"b","text":"It allows for increased lung volume"},{"id":"c","text":"It is a site for lymphatic drainage"},{"id":"d","text":"It reflects the position of the heart"}],"answerId":"d","explanation":"The cardiac notch is an anatomical feature that reflects the position of the heart bulging into the left hemithorax.","kind":"integration","linkedModuleIds":["pleura-pleural-cavity"],"origin":"ai"}],"heart-valves-coronary-supply":[{"id":"heart-valves-coronary-supply~ai-0","moduleId":"heart-valves-coronary-supply","stem":"Which valve is best auscultated at the left 5th intercostal space midclavicular line?","options":[{"id":"a","text":"Aortic valve"},{"id":"b","text":"Mitral valve"},{"id":"c","text":"Tricuspid valve"},{"id":"d","text":"Pulmonary valve"}],"answerId":"b","explanation":"The mitral valve is best heard at the left 5th intercostal space midclavicular line, which is its auscultation point.","kind":"recall","origin":"ai"},{"id":"heart-valves-coronary-supply~ai-1","moduleId":"heart-valves-coronary-supply","stem":"What is the primary artery supplying the SA node?","options":[{"id":"a","text":"Left anterior descending artery"},{"id":"b","text":"Left circumflex artery"},{"id":"c","text":"Right coronary artery"},{"id":"d","text":"Posterior descending artery"}],"answerId":"c","explanation":"The right coronary artery supplies the SA node in approximately 60% of individuals.","kind":"recall","origin":"ai"},{"id":"heart-valves-coronary-supply~ai-2","moduleId":"heart-valves-coronary-supply","stem":"In which condition would you expect inferior wall ST elevation and bradycardia?","options":[{"id":"a","text":"Anterior MI"},{"id":"b","text":"Inferior MI"},{"id":"c","text":"Aortic stenosis"},{"id":"d","text":"Mitral regurgitation"}],"answerId":"b","explanation":"Inferior MI is associated with RCA occlusion, leading to inferior wall ST elevation and bradycardia due to AV node involvement.","kind":"recall","origin":"ai"},{"id":"heart-valves-coronary-supply~ai-3","moduleId":"heart-valves-coronary-supply","stem":"How does the right coronary artery contribute to cardiac function?","options":[{"id":"a","text":"Supplies the anterior wall"},{"id":"b","text":"Supplies the lateral wall"},{"id":"c","text":"Supplies the inferior wall and AV node"},{"id":"d","text":"Supplies the apex of the heart"}],"answerId":"c","explanation":"The right coronary artery supplies the inferior wall of the heart and the AV node, which is crucial for maintaining normal conduction.","kind":"mechanism","origin":"ai"},{"id":"heart-valves-coronary-supply~ai-4","moduleId":"heart-valves-coronary-supply","stem":"Which of the following statements about valve auscultation is correct?","options":[{"id":"a","text":"Each valve is heard directly over its anatomical location"},{"id":"b","text":"Valves are heard downstream in the direction of blood flow"},{"id":"c","text":"All valves are best heard at the midclavicular line"},{"id":"d","text":"The aortic valve is best heard at the left 5th ICS"}],"answerId":"b","explanation":"Valves are best heard downstream in the direction of blood flow, not directly over their anatomical locations.","kind":"trap","origin":"ai"},{"id":"heart-valves-coronary-supply~ai-5","moduleId":"heart-valves-coronary-supply","stem":"Which artery is primarily affected in a 'widow-maker' myocardial infarction?","options":[{"id":"a","text":"Right coronary artery"},{"id":"b","text":"Left circumflex artery"},{"id":"c","text":"Left anterior descending artery"},{"id":"d","text":"Posterior descending artery"}],"answerId":"c","explanation":"'Widow-maker' refers to occlusion of the left anterior descending artery, which supplies the anterior wall and anterior 2/3 of the septum.","kind":"recall","origin":"ai"},{"id":"heart-valves-coronary-supply~ai-6","moduleId":"heart-valves-coronary-supply","stem":"How does the anatomy of the heart valves relate to the mediastinum's structure?","options":[{"id":"a","text":"Valves are located in the anterior mediastinum"},{"id":"b","text":"Coronary arteries arise from the posterior mediastinum"},{"id":"c","text":"Valves are supported by the fibrous cardiac skeleton in the middle mediastinum"},{"id":"d","text":"The heart is entirely contained within the anterior mediastinum"}],"answerId":"c","explanation":"The heart valves are supported by the fibrous cardiac skeleton, which is located in the middle mediastinum.","kind":"integration","linkedModuleIds":["mediastinum-divisions-contents"],"origin":"ai"},{"id":"heart-valves-coronary-supply~ai-7","moduleId":"heart-valves-coronary-supply","stem":"What is the clinical significance of the left anterior descending artery in relation to heart anatomy?","options":[{"id":"a","text":"It supplies the right ventricle"},{"id":"b","text":"It is the main supply for the left atrium"},{"id":"c","text":"It is crucial for the anterior wall and septum perfusion"},{"id":"d","text":"It drains into the coronary sinus"}],"answerId":"c","explanation":"The left anterior descending artery is crucial for perfusing the anterior wall and anterior 2/3 of the septum, making it vital in myocardial infarctions.","kind":"integration","linkedModuleIds":["heart-anatomy-chambers-valves"],"origin":"ai"}],"tmj-muscles-mastication":[{"id":"tmj-muscles-mastication~ai-0","moduleId":"tmj-muscles-mastication","stem":"Which muscle is primarily responsible for opening the jaw?","options":[{"id":"a","text":"Masseter"},{"id":"b","text":"Temporalis"},{"id":"c","text":"Medial pterygoid"},{"id":"d","text":"Lateral pterygoid"}],"answerId":"d","explanation":"The lateral pterygoid muscle is the primary muscle responsible for opening the jaw by protracting the mandibular head.","kind":"recall","origin":"ai"},{"id":"tmj-muscles-mastication~ai-1","moduleId":"tmj-muscles-mastication","stem":"What is the primary action of the temporalis muscle?","options":[{"id":"a","text":"Depression of the mandible"},{"id":"b","text":"Elevation of the mandible"},{"id":"c","text":"Protrusion of the mandible"},{"id":"d","text":"Retrusion of the mandible"}],"answerId":"b","explanation":"The temporalis muscle primarily elevates the mandible, contributing to the closing of the jaw.","kind":"recall","origin":"ai"},{"id":"tmj-muscles-mastication~ai-2","moduleId":"tmj-muscles-mastication","stem":"A patient presents with a locked jaw after a wide yawn. What is the most likely diagnosis?","options":[{"id":"a","text":"Fractured mandible"},{"id":"b","text":"Anterior TMJ dislocation"},{"id":"c","text":"TMJ arthritis"},{"id":"d","text":"Lateral pterygoid spasm"}],"answerId":"b","explanation":"The presentation of a locked jaw after a wide yawn is characteristic of anterior TMJ dislocation due to the lateral pterygoid muscle's action.","kind":"clinical","origin":"ai"},{"id":"tmj-muscles-mastication~ai-3","moduleId":"tmj-muscles-mastication","stem":"Which nerve innervates the muscles of mastication?","options":[{"id":"a","text":"Facial nerve (CN VII)"},{"id":"b","text":"Maxillary nerve (CN V2)"},{"id":"c","text":"Mandibular nerve (CN V3)"},{"id":"d","text":"Glossopharyngeal nerve (CN IX)"}],"answerId":"c","explanation":"The muscles of mastication are innervated by the mandibular nerve (CN V3), a branch of the trigeminal nerve.","kind":"recall","origin":"ai"},{"id":"tmj-muscles-mastication~ai-4","moduleId":"tmj-muscles-mastication","stem":"In a patient with weakness of the lateral pterygoid muscle, which clinical finding would you expect when the patient opens their mouth?","options":[{"id":"a","text":"Jaw deviates to the strong side"},{"id":"b","text":"Jaw deviates to the weak side"},{"id":"c","text":"Mouth locked open"},{"id":"d","text":"Difficulty chewing food"}],"answerId":"b","explanation":"Weakness of the lateral pterygoid muscle results in the jaw deviating to the weak side during opening.","kind":"recall","origin":"ai"},{"id":"tmj-muscles-mastication~ai-5","moduleId":"tmj-muscles-mastication","stem":"How does the lateral pterygoid muscle contribute to anterior TMJ dislocation?","options":[{"id":"a","text":"By elevating the mandible"},{"id":"b","text":"By retracting the mandible"},{"id":"c","text":"By protracting the mandibular head"},{"id":"d","text":"By stabilizing the articular disc"}],"answerId":"c","explanation":"The lateral pterygoid muscle pulls the mandibular head forward, which can lead to anterior dislocation if the head slips past the articular tubercle.","kind":"mechanism","origin":"ai"},{"id":"tmj-muscles-mastication~ai-6","moduleId":"tmj-muscles-mastication","stem":"Which of the following best describes the relationship between TMJ function and the classification of joint injuries?","options":[{"id":"a","text":"TMJ injuries are classified based on muscle involvement"},{"id":"b","text":"TMJ injuries are classified based on the type of dislocation"},{"id":"c","text":"TMJ injuries are classified based on the degree of movement restriction"},{"id":"d","text":"TMJ injuries are classified based on the type of joint (synovial vs. fibrous)"}],"answerId":"b","explanation":"TMJ injuries, particularly dislocations, are classified based on the type of dislocation and the associated functional impairment.","kind":"integration","linkedModuleIds":["fracture-classification"],"origin":"ai"},{"id":"tmj-muscles-mastication~ai-7","moduleId":"tmj-muscles-mastication","stem":"How does the action of the lateral pterygoid relate to the mechanics of mastication?","options":[{"id":"a","text":"It primarily elevates the mandible"},{"id":"b","text":"It allows for grinding movements"},{"id":"c","text":"It assists in the retraction of the mandible"},{"id":"d","text":"It opens the jaw for food intake"}],"answerId":"d","explanation":"The lateral pterygoid muscle is crucial for opening the jaw, facilitating the intake of food during mastication.","kind":"integration","linkedModuleIds":["mastication-mechanics-reflex"],"origin":"ai"}],"pterygopalatine-fossa":[{"id":"pterygopalatine-fossa~ai-0","moduleId":"pterygopalatine-fossa","stem":"Which structure enters the pterygopalatine fossa through the foramen rotundum?","options":[{"id":"a","text":"Maxillary nerve (CN V2)"},{"id":"b","text":"Mandibular nerve (CN V3)"},{"id":"c","text":"Facial nerve (CN VII)"},{"id":"d","text":"Oculomotor nerve (CN III)"}],"answerId":"a","explanation":"The maxillary nerve (CN V2) is the only structure that enters the pterygopalatine fossa through the foramen rotundum.","kind":"recall","origin":"ai"},{"id":"pterygopalatine-fossa~ai-1","moduleId":"pterygopalatine-fossa","stem":"What is the primary function of the pterygopalatine ganglion?","options":[{"id":"a","text":"Sympathetic innervation to the face"},{"id":"b","text":"Parasympathetic innervation to the lacrimal gland"},{"id":"c","text":"Sensory innervation to the mandible"},{"id":"d","text":"Motor innervation to the muscles of mastication"}],"answerId":"b","explanation":"The pterygopalatine ganglion provides parasympathetic innervation to the lacrimal gland and mucous glands of the nasal cavity and palate.","kind":"recall","origin":"ai"},{"id":"pterygopalatine-fossa~ai-2","moduleId":"pterygopalatine-fossa","stem":"A patient presents with dry eyes and impaired tearing. Which structure is likely affected?","options":[{"id":"a","text":"Maxillary nerve (V2)"},{"id":"b","text":"Pterygopalatine ganglion"},{"id":"c","text":"Sphenopalatine artery"},{"id":"d","text":"Deep petrosal nerve"}],"answerId":"b","explanation":"Impaired tearing indicates a lesion affecting the pterygopalatine ganglion, which supplies the lacrimal gland.","kind":"clinical","origin":"ai"},{"id":"pterygopalatine-fossa~ai-3","moduleId":"pterygopalatine-fossa","stem":"Which artery is the main source of posterior epistaxis?","options":[{"id":"a","text":"Maxillary artery"},{"id":"b","text":"Facial artery"},{"id":"c","text":"Sphenopalatine artery"},{"id":"d","text":"Superficial temporal artery"}],"answerId":"c","explanation":"The sphenopalatine artery is the primary source of posterior epistaxis due to its location and supply to the nasal cavity.","kind":"recall","origin":"ai"},{"id":"pterygopalatine-fossa~ai-4","moduleId":"pterygopalatine-fossa","stem":"What type of fibers does the nerve of the pterygoid canal contain?","options":[{"id":"a","text":"Purely sympathetic"},{"id":"b","text":"Purely parasympathetic"},{"id":"c","text":"Preganglionic parasympathetic and postganglionic sympathetic"},{"id":"d","text":"Sensory only"}],"answerId":"c","explanation":"The nerve of the pterygoid canal contains both preganglionic parasympathetic fibers from the greater petrosal nerve and postganglionic sympathetic fibers from the deep petrosal nerve.","kind":"trap","origin":"ai"},{"id":"pterygopalatine-fossa~ai-5","moduleId":"pterygopalatine-fossa","stem":"How does the pterygopalatine fossa communicate with the infratemporal fossa?","options":[{"id":"a","text":"Via the foramen rotundum"},{"id":"b","text":"Via the pterygomaxillary fissure"},{"id":"c","text":"Via the inferior orbital fissure"},{"id":"d","text":"Via the sphenopalatine foramen"}],"answerId":"b","explanation":"The pterygopalatine fossa communicates with the infratemporal fossa through the pterygomaxillary fissure.","kind":"recall","origin":"ai"},{"id":"pterygopalatine-fossa~ai-6","moduleId":"pterygopalatine-fossa","stem":"A patient with a lesion affecting the maxillary nerve (V2) may exhibit which clinical finding?","options":[{"id":"a","text":"Loss of taste in the anterior two-thirds of the tongue"},{"id":"b","text":"Numbness in the mid-face and upper teeth"},{"id":"c","text":"Difficulty chewing food"},{"id":"d","text":"Impaired shoulder elevation"}],"answerId":"b","explanation":"A lesion affecting the maxillary nerve (V2) would result in numbness in the mid-face and upper teeth due to its sensory innervation.","kind":"clinical","origin":"ai"},{"id":"pterygopalatine-fossa~ai-7","moduleId":"pterygopalatine-fossa","stem":"Which of the following structures is most likely to be affected in a patient with a lesion in the pterygopalatine fossa and concurrent mandibular nerve involvement?","options":[{"id":"a","text":"Lacrimal gland"},{"id":"b","text":"Masseter muscle"},{"id":"c","text":"Palatine glands"},{"id":"d","text":"Temporalis muscle"}],"answerId":"c","explanation":"The palatine glands receive parasympathetic innervation from the pterygopalatine ganglion, which may be affected alongside the mandibular nerve.","kind":"integration","linkedModuleIds":["infratemporal-fossa-nerves-vessels"],"origin":"ai"},{"id":"pterygopalatine-fossa~ai-8","moduleId":"pterygopalatine-fossa","stem":"A patient with a dysfunction in the pterygopalatine ganglion may also experience which of the following issues related to mastication?","options":[{"id":"a","text":"Impaired jaw opening"},{"id":"b","text":"Dry mouth"},{"id":"c","text":"Loss of facial sensation"},{"id":"d","text":"Difficulty in swallowing"}],"answerId":"b","explanation":"Impaired function of the pterygopalatine ganglion can lead to decreased secretion from the salivary glands, resulting in dry mouth.","kind":"integration","linkedModuleIds":["tmj-muscles-mastication"],"origin":"ai"}],"nasal-blood-supply-epistaxis":[{"id":"nasal-blood-supply-epistaxis~ai-0","moduleId":"nasal-blood-supply-epistaxis","stem":"Which artery primarily supplies the Kiesselbach's plexus?","options":[{"id":"a","text":"Sphenopalatine artery"},{"id":"b","text":"Anterior ethmoidal artery"},{"id":"c","text":"Greater palatine artery"},{"id":"d","text":"Superior labial artery"}],"answerId":"b","explanation":"The anterior ethmoidal artery, a branch of the ophthalmic artery, is one of the key contributors to Kiesselbach's plexus.","kind":"recall","origin":"ai"},{"id":"nasal-blood-supply-epistaxis~ai-1","moduleId":"nasal-blood-supply-epistaxis","stem":"What is the most common cause of anterior epistaxis?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Digital trauma"},{"id":"c","text":"Allergic rhinitis"},{"id":"d","text":"Nasal polyps"}],"answerId":"b","explanation":"Digital trauma, such as nose picking, is a common cause of anterior epistaxis due to the location of Kiesselbach's plexus.","kind":"recall","origin":"ai"},{"id":"nasal-blood-supply-epistaxis~ai-2","moduleId":"nasal-blood-supply-epistaxis","stem":"A patient presents with profuse bleeding from the posterior nasal cavity. Which artery is most likely involved?","options":[{"id":"a","text":"Anterior ethmoidal artery"},{"id":"b","text":"Sphenopalatine artery"},{"id":"c","text":"Greater palatine artery"},{"id":"d","text":"Superior labial artery"}],"answerId":"b","explanation":"The sphenopalatine artery, a terminal branch of the maxillary artery, is typically responsible for posterior epistaxis.","kind":"clinical","origin":"ai"},{"id":"nasal-blood-supply-epistaxis~ai-3","moduleId":"nasal-blood-supply-epistaxis","stem":"Which of the following correctly describes the sensory innervation of the nasal cavity?","options":[{"id":"a","text":"V1 supplies the posterior nasal cavity"},{"id":"b","text":"V2 supplies the anterior nasal cavity"},{"id":"c","text":"V1 and V2 both supply the entire nasal cavity"},{"id":"d","text":"V1 supplies the anterosuperior nasal cavity"}],"answerId":"d","explanation":"The trigeminal nerve V1 supplies the anterosuperior nasal cavity, while V2 supplies the posteroinferior region.","kind":"mechanism","origin":"ai"},{"id":"nasal-blood-supply-epistaxis~ai-4","moduleId":"nasal-blood-supply-epistaxis","stem":"What is the most common site for anterior nosebleeds?","options":[{"id":"a","text":"Sphenopalatine artery"},{"id":"b","text":"Kiesselbach's plexus"},{"id":"c","text":"Greater palatine artery"},{"id":"d","text":"Anterior ethmoidal artery"}],"answerId":"b","explanation":"Kiesselbach's plexus is the site of approximately 90% of anterior nosebleeds due to its rich vascular supply.","kind":"trap","origin":"ai"},{"id":"nasal-blood-supply-epistaxis~ai-5","moduleId":"nasal-blood-supply-epistaxis","stem":"How does the anatomy of the nasal cavity relate to the incidence of sinusitis?","options":[{"id":"a","text":"Nasal cavity walls are smooth"},{"id":"b","text":"Meatuses provide drainage pathways"},{"id":"c","text":"Nasal conchae block airflow"},{"id":"d","text":"Sinuses are devoid of blood supply"}],"answerId":"b","explanation":"The meatuses in the nasal cavity provide drainage pathways for the paranasal sinuses, influencing sinusitis incidence.","kind":"integration","linkedModuleIds":["paranasal-sinuses"],"origin":"ai"},{"id":"nasal-blood-supply-epistaxis~ai-6","moduleId":"nasal-blood-supply-epistaxis","stem":"Which structure is most likely affected in a patient with chronic nasal obstruction and recurrent epistaxis?","options":[{"id":"a","text":"Kiesselbach's plexus"},{"id":"b","text":"Sphenopalatine artery"},{"id":"c","text":"Olfactory bulb"},{"id":"d","text":"Greater palatine artery"}],"answerId":"a","explanation":"Chronic nasal obstruction can lead to irritation and bleeding from Kiesselbach's plexus, the most common site for anterior nosebleeds.","kind":"integration","linkedModuleIds":["nasal-cavity-walls-meatuses"],"origin":"ai"}],"orbit-lacrimal-apparatus":[{"id":"orbit-lacrimal-apparatus~ai-0","moduleId":"orbit-lacrimal-apparatus","stem":"Which bone is NOT part of the bony orbit?","options":[{"id":"a","text":"Frontal"},{"id":"b","text":"Zygomatic"},{"id":"c","text":"Temporal"},{"id":"d","text":"Maxilla"}],"answerId":"c","explanation":"The temporal bone is not one of the seven bones that form the bony orbit.","kind":"recall","origin":"ai"},{"id":"orbit-lacrimal-apparatus~ai-1","moduleId":"orbit-lacrimal-apparatus","stem":"What is the primary function of the Meibomian glands?","options":[{"id":"a","text":"Secrete tears"},{"id":"b","text":"Secrete oil"},{"id":"c","text":"Produce mucus"},{"id":"d","text":"Regulate eyelid movement"}],"answerId":"b","explanation":"Meibomian glands secrete oil that helps prevent tear evaporation.","kind":"recall","origin":"ai"},{"id":"orbit-lacrimal-apparatus~ai-2","moduleId":"orbit-lacrimal-apparatus","stem":"A patient presents with restricted upward gaze and diplopia after a blunt trauma to the eye. What is the most likely diagnosis?","options":[{"id":"a","text":"Chalazion"},{"id":"b","text":"Hordeolum"},{"id":"c","text":"Orbital floor blowout fracture"},{"id":"d","text":"Nasolacrimal duct obstruction"}],"answerId":"c","explanation":"These symptoms suggest an orbital floor blowout fracture affecting the inferior rectus muscle.","kind":"clinical","origin":"ai"},{"id":"orbit-lacrimal-apparatus~ai-3","moduleId":"orbit-lacrimal-apparatus","stem":"Which structure carries parasympathetic fibers to the lacrimal gland?","options":[{"id":"a","text":"Optic nerve"},{"id":"b","text":"Maxillary nerve"},{"id":"c","text":"Facial nerve"},{"id":"d","text":"Oculomotor nerve"}],"answerId":"c","explanation":"The facial nerve (CN VII) provides the secretomotor supply to the lacrimal gland.","kind":"mechanism","origin":"ai"},{"id":"orbit-lacrimal-apparatus~ai-4","moduleId":"orbit-lacrimal-apparatus","stem":"A patient has a painless lid lump within the tarsal plate. What is the likely diagnosis?","options":[{"id":"a","text":"Chalazion"},{"id":"b","text":"Hordeolum"},{"id":"c","text":"Conjunctivitis"},{"id":"d","text":"Pterygium"}],"answerId":"a","explanation":"A painless lid lump within the tarsal plate is characteristic of a chalazion.","kind":"clinical","origin":"ai"},{"id":"orbit-lacrimal-apparatus~ai-5","moduleId":"orbit-lacrimal-apparatus","stem":"Tears drain into which structure after leaving the lacrimal gland?","options":[{"id":"a","text":"Maxillary sinus"},{"id":"b","text":"Inferior nasal meatus"},{"id":"c","text":"Conjunctival sac"},{"id":"d","text":"Optic canal"}],"answerId":"b","explanation":"Tears drain via the nasolacrimal duct into the inferior nasal meatus.","kind":"trap","origin":"ai"},{"id":"orbit-lacrimal-apparatus~ai-6","moduleId":"orbit-lacrimal-apparatus","stem":"A patient with a nasolacrimal duct obstruction presents with excessive tearing. Which cranial nerve is primarily responsible for tear production?","options":[{"id":"a","text":"CN II"},{"id":"b","text":"CN V"},{"id":"c","text":"CN VII"},{"id":"d","text":"CN III"}],"answerId":"c","explanation":"Cranial nerve VII (facial nerve) is responsible for the parasympathetic innervation of the lacrimal gland.","kind":"integration","linkedModuleIds":["extraocular-muscles-orbital-nerves"],"origin":"ai"},{"id":"orbit-lacrimal-apparatus~ai-7","moduleId":"orbit-lacrimal-apparatus","stem":"In a case of blowout fracture, which muscle is most likely affected leading to restricted upward gaze?","options":[{"id":"a","text":"Superior oblique"},{"id":"b","text":"Inferior oblique"},{"id":"c","text":"Inferior rectus"},{"id":"d","text":"Medial rectus"}],"answerId":"c","explanation":"The inferior rectus muscle is commonly affected in an orbital floor blowout fracture, causing restricted upward gaze.","kind":"integration","linkedModuleIds":["extraocular-muscles-orbital-nerves"],"origin":"ai"}],"oral-cavity-lips-teeth":[{"id":"oral-cavity-lips-teeth~ai-0","moduleId":"oral-cavity-lips-teeth","stem":"Which nerve provides sensory innervation to the upper lip?","options":[{"id":"a","text":"Inferior alveolar nerve"},{"id":"b","text":"Mental nerve"},{"id":"c","text":"Infraorbital nerve"},{"id":"d","text":"Buccal nerve"}],"answerId":"c","explanation":"The infraorbital nerve, a branch of V2, supplies sensation to the upper lip.","kind":"recall","origin":"ai"},{"id":"oral-cavity-lips-teeth~ai-1","moduleId":"oral-cavity-lips-teeth","stem":"What is the primary function of the buccinator muscle?","options":[{"id":"a","text":"Facilitating mastication"},{"id":"b","text":"Closing the mouth"},{"id":"c","text":"Puffing out the cheeks"},{"id":"d","text":"Elevating the mandible"}],"answerId":"c","explanation":"The buccinator muscle helps in puffing out the cheeks and keeping food between the teeth during chewing.","kind":"mechanism","origin":"ai"},{"id":"oral-cavity-lips-teeth~ai-2","moduleId":"oral-cavity-lips-teeth","stem":"A patient presents with an inability to puff out their cheeks. Which nerve is likely affected?","options":[{"id":"a","text":"Trigeminal nerve"},{"id":"b","text":"Facial nerve"},{"id":"c","text":"Hypoglossal nerve"},{"id":"d","text":"Vagus nerve"}],"answerId":"b","explanation":"Weakness in puffing out the cheeks indicates a lesion of the facial nerve (CN VII), which innervates the buccinator.","kind":"clinical","origin":"ai"},{"id":"oral-cavity-lips-teeth~ai-3","moduleId":"oral-cavity-lips-teeth","stem":"Which of the following statements about dental innervation is correct?","options":[{"id":"a","text":"The upper teeth are supplied by the inferior alveolar nerve"},{"id":"b","text":"The lower teeth are supplied by the maxillary nerve"},{"id":"c","text":"The mandibular teeth are supplied by the inferior alveolar nerve"},{"id":"d","text":"The maxillary teeth are supplied by the inferior alveolar nerve"}],"answerId":"c","explanation":"The mandibular (lower) teeth are indeed supplied by the inferior alveolar nerve, a branch of V3.","kind":"trap","origin":"ai"},{"id":"oral-cavity-lips-teeth~ai-4","moduleId":"oral-cavity-lips-teeth","stem":"What is the primary blood supply to the lips?","options":[{"id":"a","text":"Maxillary artery"},{"id":"b","text":"Facial artery"},{"id":"c","text":"Lingual artery"},{"id":"d","text":"Carotid artery"}],"answerId":"b","explanation":"The blood supply to the lips comes primarily from the superior and inferior labial branches of the facial artery.","kind":"recall","origin":"ai"},{"id":"oral-cavity-lips-teeth~ai-5","moduleId":"oral-cavity-lips-teeth","stem":"A patient with a dental abscess in the lower molars would likely have pain radiating to which nerve area?","options":[{"id":"a","text":"Infraorbital nerve"},{"id":"b","text":"Mental nerve"},{"id":"c","text":"Superior alveolar nerve"},{"id":"d","text":"Inferior alveolar nerve"}],"answerId":"d","explanation":"The inferior alveolar nerve supplies the mandibular teeth, including the lower molars, and would be the source of pain.","kind":"clinical","origin":"ai"},{"id":"oral-cavity-lips-teeth~ai-6","moduleId":"oral-cavity-lips-teeth","stem":"How does the innervation of the tongue relate to the innervation of the teeth?","options":[{"id":"a","text":"Both are innervated by the facial nerve"},{"id":"b","text":"Both are innervated by the trigeminal nerve"},{"id":"c","text":"Tongue is V3 while teeth are V2"},{"id":"d","text":"Tongue is V2 while teeth are V3"}],"answerId":"b","explanation":"Both the tongue (anterior 2/3) and the teeth have sensory innervation from branches of the trigeminal nerve.","kind":"integration","linkedModuleIds":["palate-tongue"],"origin":"ai"},{"id":"oral-cavity-lips-teeth~ai-7","moduleId":"oral-cavity-lips-teeth","stem":"Which structure's dysfunction could lead to impaired mastication and relate to dental health?","options":[{"id":"a","text":"Buccinator muscle"},{"id":"b","text":"Palatine tonsils"},{"id":"c","text":"Sublingual gland"},{"id":"d","text":"Lingual frenulum"}],"answerId":"a","explanation":"Dysfunction of the buccinator muscle can impair mastication, which is directly related to dental health.","kind":"integration","linkedModuleIds":["salivary-glands-oral-clinical"],"origin":"ai"}],"larynx-cartilages-cavity":[{"id":"larynx-cartilages-cavity~ai-0","moduleId":"larynx-cartilages-cavity","stem":"Which cartilage forms the laryngeal prominence commonly known as the 'Adam's apple'?","options":[{"id":"a","text":"Thyroid cartilage"},{"id":"b","text":"Cricoid cartilage"},{"id":"c","text":"Epiglottis"},{"id":"d","text":"Arytenoid cartilage"}],"answerId":"a","explanation":"The thyroid cartilage is responsible for the laryngeal prominence, which is more prominent in males.","kind":"recall","origin":"ai"},{"id":"larynx-cartilages-cavity~ai-1","moduleId":"larynx-cartilages-cavity","stem":"What is the only complete ring in the airway?","options":[{"id":"a","text":"Thyroid cartilage"},{"id":"b","text":"Cricoid cartilage"},{"id":"c","text":"Epiglottis"},{"id":"d","text":"Arytenoid cartilage"}],"answerId":"b","explanation":"The cricoid cartilage is the only complete ring, providing structural integrity to the airway.","kind":"recall","origin":"ai"},{"id":"larynx-cartilages-cavity~ai-2","moduleId":"larynx-cartilages-cavity","stem":"During swallowing, which structure folds down to cover the laryngeal inlet?","options":[{"id":"a","text":"Thyroid cartilage"},{"id":"b","text":"Epiglottis"},{"id":"c","text":"Arytenoid cartilage"},{"id":"d","text":"Cricoid cartilage"}],"answerId":"b","explanation":"The epiglottis folds over the laryngeal inlet to prevent aspiration of food.","kind":"recall","origin":"ai"},{"id":"larynx-cartilages-cavity~ai-3","moduleId":"larynx-cartilages-cavity","stem":"What is the clinical significance of the cricothyroid membrane?","options":[{"id":"a","text":"Site for vocal fold surgery"},{"id":"b","text":"Site for cricothyrotomy"},{"id":"c","text":"Landmark for laryngeal nerve"},{"id":"d","text":"Anchor for vocal ligaments"}],"answerId":"b","explanation":"The cricothyroid membrane is the site for cricothyrotomy, providing access to the airway in emergencies.","kind":"clinical","origin":"ai"},{"id":"larynx-cartilages-cavity~ai-4","moduleId":"larynx-cartilages-cavity","stem":"Which of the following structures is located between the vestibular folds and the vocal folds?","options":[{"id":"a","text":"Vestibule"},{"id":"b","text":"Infraglottic space"},{"id":"c","text":"Ventricle"},{"id":"d","text":"Rima glottidis"}],"answerId":"c","explanation":"The ventricle is the space located between the vestibular and vocal folds.","kind":"recall","origin":"ai"},{"id":"larynx-cartilages-cavity~ai-5","moduleId":"larynx-cartilages-cavity","stem":"Which cartilage is incorrectly described as a complete ring around the airway?","options":[{"id":"a","text":"Thyroid cartilage"},{"id":"b","text":"Cricoid cartilage"},{"id":"c","text":"Epiglottis"},{"id":"d","text":"Arytenoid cartilage"}],"answerId":"a","explanation":"The thyroid cartilage is incomplete posteriorly, while the cricoid cartilage is the only complete ring.","kind":"trap","origin":"ai"},{"id":"larynx-cartilages-cavity~ai-6","moduleId":"larynx-cartilages-cavity","stem":"How does the cricoid cartilage relate to the embryological development of the axial skeleton?","options":[{"id":"a","text":"It is derived from somites"},{"id":"b","text":"It is formed from neural crest cells"},{"id":"c","text":"It is a derivative of the pharyngeal arches"},{"id":"d","text":"It is formed from mesodermal precursors"}],"answerId":"c","explanation":"The cricoid cartilage is derived from the fourth pharyngeal arch during embryological development.","kind":"integration","linkedModuleIds":["msk-embryo-somites"],"origin":"ai"},{"id":"larynx-cartilages-cavity~ai-7","moduleId":"larynx-cartilages-cavity","stem":"Which laryngeal muscle is primarily responsible for tensing the vocal cords?","options":[{"id":"a","text":"Thyroarytenoid"},{"id":"b","text":"Cricothyroid"},{"id":"c","text":"Lateral cricoarytenoid"},{"id":"d","text":"Posterior cricoarytenoid"}],"answerId":"b","explanation":"The cricothyroid muscle tenses the vocal cords, which is crucial for pitch modulation.","kind":"integration","linkedModuleIds":["laryngeal-muscles-nerves"],"origin":"ai"}],"ear-external-middle-internal":[{"id":"ear-external-middle-internal~ai-0","moduleId":"ear-external-middle-internal","stem":"What is the primary function of the Eustachian tube?","options":[{"id":"a","text":"To amplify sound vibrations"},{"id":"b","text":"To equalize middle ear pressure"},{"id":"c","text":"To transmit sound to the cochlea"},{"id":"d","text":"To protect the tympanic membrane"}],"answerId":"b","explanation":"The Eustachian tube connects the middle ear to the nasopharynx, allowing for pressure equalization.","kind":"recall","origin":"ai"},{"id":"ear-external-middle-internal~ai-1","moduleId":"ear-external-middle-internal","stem":"Which structure is responsible for transmitting sound vibrations from the tympanic membrane to the oval window?","options":[{"id":"a","text":"Cochlea"},{"id":"b","text":"Malleus"},{"id":"c","text":"Stapes"},{"id":"d","text":"Eustachian tube"}],"answerId":"c","explanation":"The stapes is the last ossicle in the chain that transmits vibrations to the oval window.","kind":"recall","origin":"ai"},{"id":"ear-external-middle-internal~ai-2","moduleId":"ear-external-middle-internal","stem":"A child presents with a bulging red tympanic membrane and ear pain. What is the most likely diagnosis?","options":[{"id":"a","text":"Chronic otitis media"},{"id":"b","text":"Acute otitis media"},{"id":"c","text":"Otitis externa"},{"id":"d","text":"Eustachian tube dysfunction"}],"answerId":"b","explanation":"The signs are characteristic of acute otitis media, commonly seen in children.","kind":"clinical","origin":"ai"},{"id":"ear-external-middle-internal~ai-3","moduleId":"ear-external-middle-internal","stem":"What mechanism explains the increased incidence of otitis media in children?","options":[{"id":"a","text":"Thinner tympanic membrane"},{"id":"b","text":"Shorter and more horizontal Eustachian tube"},{"id":"c","text":"Weaker immune system"},{"id":"d","text":"Higher exposure to pathogens"}],"answerId":"b","explanation":"Children's Eustachian tubes are shorter and more horizontal, facilitating the ascent of pathogens from the nasopharynx.","kind":"trap","origin":"ai"},{"id":"ear-external-middle-internal~ai-4","moduleId":"ear-external-middle-internal","stem":"Which of the following findings is consistent with conductive hearing loss?","options":[{"id":"a","text":"Normal tympanic membrane with earwax"},{"id":"b","text":"Bulging tympanic membrane with fluid"},{"id":"c","text":"Normal cochlear function"},{"id":"d","text":"Sensorineural hearing loss"}],"answerId":"b","explanation":"A bulging tympanic membrane with fluid indicates a conductive problem, often due to middle ear issues.","kind":"recall","origin":"ai"},{"id":"ear-external-middle-internal~ai-5","moduleId":"ear-external-middle-internal","stem":"How does the cochlea contribute to hearing?","options":[{"id":"a","text":"Transmits vibrations to the tympanic membrane"},{"id":"b","text":"Converts sound waves into electrical signals"},{"id":"c","text":"Amplifies sound through the ossicles"},{"id":"d","text":"Equalizes pressure in the ear"}],"answerId":"b","explanation":"The cochlea converts sound waves into electrical signals for the auditory nerve.","kind":"mechanism","origin":"ai"},{"id":"ear-external-middle-internal~ai-6","moduleId":"ear-external-middle-internal","stem":"How does the anatomy of the Eustachian tube in children relate to auditory physiology?","options":[{"id":"a","text":"It enhances sound conduction"},{"id":"b","text":"It facilitates fluid drainage"},{"id":"c","text":"It predisposes to middle ear infections"},{"id":"d","text":"It protects against noise-induced hearing loss"}],"answerId":"c","explanation":"The anatomical features of the Eustachian tube in children make them more susceptible to middle ear infections.","kind":"integration","linkedModuleIds":["auditory-physiology-hearing"],"origin":"ai"},{"id":"ear-external-middle-internal~ai-7","moduleId":"ear-external-middle-internal","stem":"What is the role of the stapedius muscle in hearing?","options":[{"id":"a","text":"Amplifies sound vibrations"},{"id":"b","text":"Dampens loud sounds"},{"id":"c","text":"Transmits signals to the cochlea"},{"id":"d","text":"Protects the tympanic membrane"}],"answerId":"b","explanation":"The stapedius muscle dampens loud sounds to protect the inner ear.","kind":"mechanism","origin":"ai"},{"id":"ear-external-middle-internal~ai-8","moduleId":"ear-external-middle-internal","stem":"Which structure is primarily affected in sensorineural hearing loss?","options":[{"id":"a","text":"Tympanic membrane"},{"id":"b","text":"Ossicles"},{"id":"c","text":"Cochlea"},{"id":"d","text":"Eustachian tube"}],"answerId":"c","explanation":"Sensorineural hearing loss typically involves damage to the cochlea or auditory nerve.","kind":"recall","origin":"ai"}],"extraocular-muscles-orbital-nerves":[{"id":"extraocular-muscles-orbital-nerves~ai-0","moduleId":"extraocular-muscles-orbital-nerves","stem":"Which cranial nerve innervates the lateral rectus muscle?","options":[{"id":"a","text":"CN III"},{"id":"b","text":"CN IV"},{"id":"c","text":"CN V"},{"id":"d","text":"CN VI"}],"answerId":"d","explanation":"The lateral rectus muscle is innervated by CN VI (abducens).","kind":"recall","origin":"ai"},{"id":"extraocular-muscles-orbital-nerves~ai-1","moduleId":"extraocular-muscles-orbital-nerves","stem":"What is the primary action of the superior oblique muscle?","options":[{"id":"a","text":"Elevates the eye"},{"id":"b","text":"Depresses the adducted eye"},{"id":"c","text":"Abducts the eye"},{"id":"d","text":"Adducts the eye"}],"answerId":"b","explanation":"The superior oblique muscle primarily depresses the adducted eye.","kind":"mechanism","origin":"ai"},{"id":"extraocular-muscles-orbital-nerves~ai-2","moduleId":"extraocular-muscles-orbital-nerves","stem":"A patient presents with horizontal diplopia and their affected eye rests adducted. Which cranial nerve is likely involved?","options":[{"id":"a","text":"CN III"},{"id":"b","text":"CN IV"},{"id":"c","text":"CN V"},{"id":"d","text":"CN VI"}],"answerId":"d","explanation":"This presentation is indicative of CN VI (abducens) palsy.","kind":"clinical","origin":"ai"},{"id":"extraocular-muscles-orbital-nerves~ai-3","moduleId":"extraocular-muscles-orbital-nerves","stem":"What is the consequence of a central retinal artery occlusion?","options":[{"id":"a","text":"Painless monocular vision loss"},{"id":"b","text":"Bilateral vision loss"},{"id":"c","text":"Color vision loss"},{"id":"d","text":"Diplopia"}],"answerId":"a","explanation":"Central retinal artery occlusion leads to sudden painless monocular vision loss.","kind":"recall","origin":"ai"},{"id":"extraocular-muscles-orbital-nerves~ai-4","moduleId":"extraocular-muscles-orbital-nerves","stem":"In CN IV (trochlear) palsy, which compensatory position might a patient adopt?","options":[{"id":"a","text":"Head tilt towards the affected side"},{"id":"b","text":"Head tilt away from the affected side"},{"id":"c","text":"No head tilt"},{"id":"d","text":"Chin up position"}],"answerId":"b","explanation":"Patients with CN IV palsy often tilt their head away from the affected side to compensate for vertical diplopia.","kind":"clinical","origin":"ai"},{"id":"extraocular-muscles-orbital-nerves~ai-5","moduleId":"extraocular-muscles-orbital-nerves","stem":"Which structure relays parasympathetic fibers from CN III to the ciliary muscle?","options":[{"id":"a","text":"Ciliary ganglion"},{"id":"b","text":"Superior orbital fissure"},{"id":"c","text":"Optic nerve"},{"id":"d","text":"Ophthalmic artery"}],"answerId":"a","explanation":"The ciliary ganglion relays parasympathetic fibers from CN III to the ciliary muscle.","kind":"recall","origin":"ai"},{"id":"extraocular-muscles-orbital-nerves~ai-6","moduleId":"extraocular-muscles-orbital-nerves","stem":"How does the superior oblique muscle affect eye movement when tested?","options":[{"id":"a","text":"Looking up and out"},{"id":"b","text":"Looking down and out"},{"id":"c","text":"Looking down and in"},{"id":"d","text":"Looking straight ahead"}],"answerId":"c","explanation":"The superior oblique muscle is best tested by looking down and in, as it depresses the adducted eye.","kind":"trap","origin":"ai"},{"id":"extraocular-muscles-orbital-nerves~ai-7","moduleId":"extraocular-muscles-orbital-nerves","stem":"How does the knowledge of extraocular muscle innervation relate to the understanding of the bony orbit?","options":[{"id":"a","text":"Both involve the optic nerve"},{"id":"b","text":"Both are affected by the same cranial nerves"},{"id":"c","text":"Both are involved in vision"},{"id":"d","text":"Both relate to the lacrimal apparatus"}],"answerId":"b","explanation":"Understanding extraocular muscle innervation is crucial as it relates to the cranial nerves that pass through the bony orbit.","kind":"integration","linkedModuleIds":["orbit-lacrimal-apparatus"],"origin":"ai"},{"id":"extraocular-muscles-orbital-nerves~ai-8","moduleId":"extraocular-muscles-orbital-nerves","stem":"What is the clinical significance of understanding central retinal artery occlusion in relation to extraocular muscle function?","options":[{"id":"a","text":"It helps in diagnosing CN III palsy"},{"id":"b","text":"It aids in understanding visual field defects"},{"id":"c","text":"It explains the role of sympathetic fibers"},{"id":"d","text":"It highlights the importance of blood supply to ocular structures"}],"answerId":"d","explanation":"Understanding central retinal artery occlusion emphasizes the importance of blood supply to ocular structures, which is crucial for muscle function.","kind":"integration","linkedModuleIds":["retinal-vascular-occlusions"],"origin":"ai"}],"nasal-cavity-walls-meatuses":[{"id":"nasal-cavity-walls-meatuses~ai-0","moduleId":"nasal-cavity-walls-meatuses","stem":"Which structure primarily separates the nasal cavity into right and left halves?","options":[{"id":"a","text":"Superior concha"},{"id":"b","text":"Nasal septum"},{"id":"c","text":"Inferior meatus"},{"id":"d","text":"Middle concha"}],"answerId":"b","explanation":"The nasal septum, composed of cartilage and bone, divides the nasal cavity into two halves.","kind":"recall","origin":"ai"},{"id":"nasal-cavity-walls-meatuses~ai-1","moduleId":"nasal-cavity-walls-meatuses","stem":"What is the primary function of the nasal conchae?","options":[{"id":"a","text":"Olfaction"},{"id":"b","text":"Sound resonance"},{"id":"c","text":"Air filtration and humidification"},{"id":"d","text":"Mucus production"}],"answerId":"c","explanation":"The nasal conchae create turbulence in the airflow, which helps to warm, humidify, and filter the air.","kind":"mechanism","origin":"ai"},{"id":"nasal-cavity-walls-meatuses~ai-2","moduleId":"nasal-cavity-walls-meatuses","stem":"A patient presents with clear watery rhinorrhea after a head injury. What is the most likely cause?","options":[{"id":"a","text":"Fracture of the nasal septum"},{"id":"b","text":"Fracture of the cribriform plate"},{"id":"c","text":"Maxillary sinusitis"},{"id":"d","text":"Inferior meatus obstruction"}],"answerId":"b","explanation":"A fracture of the cribriform plate can lead to a CSF leak, resulting in clear watery rhinorrhea.","kind":"clinical","origin":"ai"},{"id":"nasal-cavity-walls-meatuses~ai-3","moduleId":"nasal-cavity-walls-meatuses","stem":"Which sinus drains into the middle meatus?","options":[{"id":"a","text":"Sphenoid sinus"},{"id":"b","text":"Frontal sinus"},{"id":"c","text":"Posterior ethmoidal cells"},{"id":"d","text":"Inferior nasal concha"}],"answerId":"b","explanation":"The frontal sinus drains into the middle meatus via the hiatus semilunaris.","kind":"recall","origin":"ai"},{"id":"nasal-cavity-walls-meatuses~ai-4","moduleId":"nasal-cavity-walls-meatuses","stem":"Which of the following is a common cause of sinusitis related to the middle meatus?","options":[{"id":"a","text":"Infection of the inferior meatus"},{"id":"b","text":"Obstruction of the ostiomeatal complex"},{"id":"c","text":"Injury to the nasal septum"},{"id":"d","text":"Fracture of the nasal bones"}],"answerId":"b","explanation":"Obstruction of the ostiomeatal complex is a common underlying cause of sinusitis, affecting drainage.","kind":"trap","origin":"ai"},{"id":"nasal-cavity-walls-meatuses~ai-5","moduleId":"nasal-cavity-walls-meatuses","stem":"A patient has anosmia following a head injury. Which cranial nerve is most likely affected?","options":[{"id":"a","text":"CN II"},{"id":"b","text":"CN V"},{"id":"c","text":"CN I"},{"id":"d","text":"CN VII"}],"answerId":"c","explanation":"Anosmia indicates damage to the olfactory nerve (CN I), which passes through the cribriform plate.","kind":"clinical","origin":"ai"},{"id":"nasal-cavity-walls-meatuses~ai-6","moduleId":"nasal-cavity-walls-meatuses","stem":"How does the blood supply to the nasal cavity relate to epistaxis?","options":[{"id":"a","text":"Maxillary artery supplies the nasal cavity, leading to anterior epistaxis"},{"id":"b","text":"Ophthalmic artery supplies the nasal cavity, leading to posterior epistaxis"},{"id":"c","text":"Facial artery is the sole supply, causing no epistaxis"},{"id":"d","text":"External carotid artery has no role in nasal supply"}],"answerId":"a","explanation":"The maxillary artery supplies the nasal cavity, and its branches can lead to anterior epistaxis.","kind":"integration","linkedModuleIds":["nasal-blood-supply-epistaxis"],"origin":"ai"},{"id":"nasal-cavity-walls-meatuses~ai-7","moduleId":"nasal-cavity-walls-meatuses","stem":"Which meatus is responsible for draining the nasolacrimal duct?","options":[{"id":"a","text":"Superior meatus"},{"id":"b","text":"Middle meatus"},{"id":"c","text":"Inferior meatus"},{"id":"d","text":"Sphenoethmoidal recess"}],"answerId":"c","explanation":"The nasolacrimal duct drains into the inferior meatus.","kind":"integration","linkedModuleIds":["paranasal-sinuses"],"origin":"ai"}],"cranial-fossae-foramina":[{"id":"cranial-fossae-foramina~ai-0","moduleId":"cranial-fossae-foramina","stem":"Which cranial nerve is transmitted through the cribriform plate?","options":[{"id":"a","text":"CN II"},{"id":"b","text":"CN III"},{"id":"c","text":"CN I"},{"id":"d","text":"CN V"}],"answerId":"c","explanation":"The cribriform plate transmits CN I (olfactory nerve), which is responsible for the sense of smell.","kind":"recall","origin":"ai"},{"id":"cranial-fossae-foramina~ai-1","moduleId":"cranial-fossae-foramina","stem":"What is the primary consequence of a fracture at the cribriform plate?","options":[{"id":"a","text":"Ophthalmoplegia"},{"id":"b","text":"Hoarseness"},{"id":"c","text":"Anosmia"},{"id":"d","text":"Facial paralysis"}],"answerId":"c","explanation":"A fracture at the cribriform plate can lead to anosmia due to injury of CN I.","kind":"clinical","origin":"ai"},{"id":"cranial-fossae-foramina~ai-2","moduleId":"cranial-fossae-foramina","stem":"Which foramen transmits the maxillary nerve (V2)?","options":[{"id":"a","text":"Foramen ovale"},{"id":"b","text":"Foramen spinosum"},{"id":"c","text":"Foramen rotundum"},{"id":"d","text":"Superior orbital fissure"}],"answerId":"c","explanation":"The maxillary nerve (V2) exits through the foramen rotundum, while the mandibular nerve (V3) exits through the foramen ovale.","kind":"trap","origin":"ai"},{"id":"cranial-fossae-foramina~ai-3","moduleId":"cranial-fossae-foramina","stem":"Which structure is associated with superior orbital fissure syndrome?","options":[{"id":"a","text":"CN IX"},{"id":"b","text":"CN VII"},{"id":"c","text":"CN III"},{"id":"d","text":"CN I"}],"answerId":"c","explanation":"Superior orbital fissure syndrome involves CN III, IV, VI, and V1, leading to ophthalmoplegia and sensory loss.","kind":"mechanism","origin":"ai"},{"id":"cranial-fossae-foramina~ai-4","moduleId":"cranial-fossae-foramina","stem":"A patient presents with hoarseness, dysphagia, and shoulder droop. Which cranial foramen is likely involved?","options":[{"id":"a","text":"Jugular foramen"},{"id":"b","text":"Foramen magnum"},{"id":"c","text":"Foramen rotundum"},{"id":"d","text":"Internal acoustic meatus"}],"answerId":"a","explanation":"These symptoms suggest jugular foramen syndrome, which involves CN IX, X, and XI.","kind":"clinical","origin":"ai"},{"id":"cranial-fossae-foramina~ai-5","moduleId":"cranial-fossae-foramina","stem":"How does the anatomy of the cranial fossae relate to brainstem organization?","options":[{"id":"a","text":"They do not relate"},{"id":"b","text":"They influence cranial nerve exit points"},{"id":"c","text":"They affect blood supply"},{"id":"d","text":"They determine brain size"}],"answerId":"b","explanation":"The cranial fossae house the exit points for cranial nerves, which are organized in relation to the brainstem.","kind":"integration","linkedModuleIds":["brainstem-anatomy-organization"],"origin":"ai"},{"id":"cranial-fossae-foramina~ai-6","moduleId":"cranial-fossae-foramina","stem":"Which foramen is associated with the internal carotid artery?","options":[{"id":"a","text":"Foramen lacerum"},{"id":"b","text":"Foramen rotundum"},{"id":"c","text":"Jugular foramen"},{"id":"d","text":"Foramen ovale"}],"answerId":"a","explanation":"The internal carotid artery passes through the carotid canal, which is adjacent to the foramen lacerum.","kind":"recall","origin":"ai"},{"id":"cranial-fossae-foramina~ai-7","moduleId":"cranial-fossae-foramina","stem":"What is the clinical significance of the jugular foramen?","options":[{"id":"a","text":"Transmits CN I"},{"id":"b","text":"Transmits CN IX, X, XI"},{"id":"c","text":"Transmits CN V2"},{"id":"d","text":"Transmits CN III"}],"answerId":"b","explanation":"The jugular foramen transmits CN IX, X, and XI, which are crucial for swallowing and shoulder movement.","kind":"clinical","origin":"ai"},{"id":"cranial-fossae-foramina~ai-8","moduleId":"cranial-fossae-foramina","stem":"Which cranial nerve exits through the foramen ovale?","options":[{"id":"a","text":"CN V1"},{"id":"b","text":"CN V2"},{"id":"c","text":"CN V3"},{"id":"d","text":"CN VII"}],"answerId":"c","explanation":"The mandibular nerve (V3) exits through the foramen ovale, distinguishing it from V1 and V2.","kind":"recall","origin":"ai"}],"paranasal-sinuses":[{"id":"paranasal-sinuses~ai-0","moduleId":"paranasal-sinuses","stem":"Which paranasal sinus is the largest and most commonly infected?","options":[{"id":"a","text":"Frontal sinus"},{"id":"b","text":"Ethmoidal sinus"},{"id":"c","text":"Maxillary sinus"},{"id":"d","text":"Sphenoid sinus"}],"answerId":"c","explanation":"The maxillary sinus is the largest and most clinically significant due to its high ostium, which complicates drainage and makes it prone to infection.","kind":"recall","origin":"ai"},{"id":"paranasal-sinuses~ai-1","moduleId":"paranasal-sinuses","stem":"What is the primary reason for the high incidence of maxillary sinusitis?","options":[{"id":"a","text":"Low drainage ostium"},{"id":"b","text":"High drainage ostium"},{"id":"c","text":"Direct connection to the nasal cavity"},{"id":"d","text":"Large size of the sinus"}],"answerId":"b","explanation":"The maxillary sinus has a high ostium that drains against gravity, making it susceptible to obstruction and infection.","kind":"mechanism","origin":"ai"},{"id":"paranasal-sinuses~ai-2","moduleId":"paranasal-sinuses","stem":"A patient presents with facial pain and pressure over the cheek, worsening when bending forward. What is the most likely diagnosis?","options":[{"id":"a","text":"Frontal sinusitis"},{"id":"b","text":"Maxillary sinusitis"},{"id":"c","text":"Ethmoidal sinusitis"},{"id":"d","text":"Sphenoidal sinusitis"}],"answerId":"b","explanation":"Facial pain/pressure over the cheek that worsens on bending forward is characteristic of maxillary sinusitis due to the dependent ostium.","kind":"clinical","origin":"ai"},{"id":"paranasal-sinuses~ai-3","moduleId":"paranasal-sinuses","stem":"Which finding is most indicative of ethmoidal sinus infection?","options":[{"id":"a","text":"Toothache in upper molars"},{"id":"b","text":"Facial swelling"},{"id":"c","text":"Orbital swelling/cellulitis"},{"id":"d","text":"Nasal obstruction"}],"answerId":"c","explanation":"Orbital swelling or cellulitis can occur due to the close proximity of the ethmoid air cells to the orbit, especially when infected.","kind":"recall","origin":"ai"},{"id":"paranasal-sinuses~ai-4","moduleId":"paranasal-sinuses","stem":"Why is the maxillary sinus particularly vulnerable to infection?","options":[{"id":"a","text":"It drains well due to its ostium position"},{"id":"b","text":"It is the largest sinus"},{"id":"c","text":"Its ostium is high on the medial wall"},{"id":"d","text":"It has a direct connection to the throat"}],"answerId":"c","explanation":"The high position of the maxillary sinus ostium complicates drainage, making it reliant on mucociliary clearance, which can fail, leading to infection.","kind":"trap","origin":"ai"},{"id":"paranasal-sinuses~ai-5","moduleId":"paranasal-sinuses","stem":"How does maxillary sinusitis potentially lead to upper molar toothache?","options":[{"id":"a","text":"Direct nerve involvement"},{"id":"b","text":"Pressure on the maxillary nerve"},{"id":"c","text":"Infection spreading to the tooth roots"},{"id":"d","text":"Inflammation of the nasal cavity"}],"answerId":"c","explanation":"The floor of the maxillary sinus is closely related to the roots of the upper molars; infection can spread from the sinus to the tooth roots, causing pain.","kind":"clinical","origin":"ai"},{"id":"paranasal-sinuses~ai-6","moduleId":"paranasal-sinuses","stem":"In a patient with sinusitis, which linked module's concept is most relevant for understanding potential complications in the orbit?","options":[{"id":"a","text":"Escape Rhythms & Sinus Node Dysfunction"},{"id":"b","text":"Otitis Media, Sinusitis & Epiglottitis"},{"id":"c","text":"Nasal Cavity: Walls, Conchae & Meatuses"},{"id":"d","text":"Nasal Blood Supply & Epistaxis"}],"answerId":"b","explanation":"The module on Otitis Media, Sinusitis & Epiglottitis discusses complications such as orbital cellulitis that can arise from sinus infections.","kind":"integration","linkedModuleIds":["otitis-media-sinusitis-epiglottitis"],"origin":"ai"},{"id":"paranasal-sinuses~ai-7","moduleId":"paranasal-sinuses","stem":"Which anatomical feature is crucial for understanding the drainage of the paranasal sinuses?","options":[{"id":"a","text":"Ostium position"},{"id":"b","text":"Size of the sinus"},{"id":"c","text":"Mucosal lining"},{"id":"d","text":"Nerve supply"}],"answerId":"a","explanation":"The position of the ostium is critical for drainage; for instance, the high ostium of the maxillary sinus complicates its drainage.","kind":"integration","linkedModuleIds":["nasal-cavity-walls-meatuses"],"origin":"ai"}],"laryngeal-muscles-nerves":[{"id":"laryngeal-muscles-nerves~ai-0","moduleId":"laryngeal-muscles-nerves","stem":"Which intrinsic laryngeal muscle is responsible for abducting the vocal folds?","options":[{"id":"a","text":"Lateral cricoarytenoid"},{"id":"b","text":"Transverse arytenoid"},{"id":"c","text":"Posterior cricoarytenoid"},{"id":"d","text":"Thyroarytenoid"}],"answerId":"c","explanation":"The posterior cricoarytenoid is the only muscle that abducts the vocal folds, allowing for airway opening.","kind":"recall","origin":"ai"},{"id":"laryngeal-muscles-nerves~ai-1","moduleId":"laryngeal-muscles-nerves","stem":"What is the primary function of the cricothyroid muscle?","options":[{"id":"a","text":"Abducts the vocal folds"},{"id":"b","text":"Adducts the vocal folds"},{"id":"c","text":"Tenses the vocal cords"},{"id":"d","text":"Relaxes the vocal cords"}],"answerId":"c","explanation":"The cricothyroid muscle tenses and lengthens the vocal cords, which raises the pitch of the voice.","kind":"mechanism","origin":"ai"},{"id":"laryngeal-muscles-nerves~ai-2","moduleId":"laryngeal-muscles-nerves","stem":"A patient presents with hoarseness after undergoing thyroid surgery. What is the most likely cause?","options":[{"id":"a","text":"Bilateral recurrent laryngeal nerve injury"},{"id":"b","text":"Unilateral recurrent laryngeal nerve injury"},{"id":"c","text":"Cricothyroid muscle injury"},{"id":"d","text":"Internal laryngeal nerve injury"}],"answerId":"b","explanation":"Hoarseness after thyroid surgery is typically due to unilateral injury of the recurrent laryngeal nerve.","kind":"clinical","origin":"ai"},{"id":"laryngeal-muscles-nerves~ai-3","moduleId":"laryngeal-muscles-nerves","stem":"Which nerve provides motor innervation to the cricothyroid muscle?","options":[{"id":"a","text":"Recurrent laryngeal nerve"},{"id":"b","text":"Internal laryngeal nerve"},{"id":"c","text":"External laryngeal nerve"},{"id":"d","text":"Vagus nerve"}],"answerId":"c","explanation":"The external laryngeal nerve, a branch of the superior laryngeal nerve, provides motor innervation to the cricothyroid muscle.","kind":"recall","origin":"ai"},{"id":"laryngeal-muscles-nerves~ai-4","moduleId":"laryngeal-muscles-nerves","stem":"What is the consequence of bilateral recurrent laryngeal nerve injury?","options":[{"id":"a","text":"Aspiration due to loss of cough reflex"},{"id":"b","text":"Hoarseness due to vocal cord paralysis"},{"id":"c","text":"Airway obstruction due to adduction of vocal folds"},{"id":"d","text":"Inability to raise pitch"}],"answerId":"c","explanation":"Bilateral recurrent laryngeal nerve injury results in airway obstruction because both abductors are lost, leaving the vocal folds adducted.","kind":"trap","origin":"ai"},{"id":"laryngeal-muscles-nerves~ai-5","moduleId":"laryngeal-muscles-nerves","stem":"In a patient with aspiration due to loss of the cough reflex, which nerve is likely injured?","options":[{"id":"a","text":"Recurrent laryngeal nerve"},{"id":"b","text":"External laryngeal nerve"},{"id":"c","text":"Internal laryngeal nerve"},{"id":"d","text":"Vagus nerve"}],"answerId":"c","explanation":"Injury to the internal laryngeal nerve leads to loss of sensory input from the larynx, resulting in aspiration due to loss of the cough reflex.","kind":"clinical","origin":"ai"},{"id":"laryngeal-muscles-nerves~ai-6","moduleId":"laryngeal-muscles-nerves","stem":"How does the function of the cricothyroid muscle relate to the extraocular muscles?","options":[{"id":"a","text":"Both are innervated by the same nerve"},{"id":"b","text":"Both control tension in their respective structures"},{"id":"c","text":"Both are responsible for abduction"},{"id":"d","text":"Both are involved in airway protection"}],"answerId":"b","explanation":"The cricothyroid muscle adjusts tension in the vocal cords, similar to how extraocular muscles adjust tension in the eye for movement.","kind":"integration","linkedModuleIds":["extraocular-muscles"],"origin":"ai"},{"id":"laryngeal-muscles-nerves~ai-7","moduleId":"laryngeal-muscles-nerves","stem":"Which laryngeal muscle's function is most similar to that of the lateral rectus muscle in the eye?","options":[{"id":"a","text":"Cricothyroid"},{"id":"b","text":"Posterior cricoarytenoid"},{"id":"c","text":"Lateral cricoarytenoid"},{"id":"d","text":"Transverse arytenoid"}],"answerId":"c","explanation":"The lateral cricoarytenoid muscle adducts the vocal folds, similar to how the lateral rectus muscle abducts the eye.","kind":"integration","linkedModuleIds":["extraocular-muscles"],"origin":"ai"}],"pharynx-constrictors-tonsils":[{"id":"pharynx-constrictors-tonsils~ai-0","moduleId":"pharynx-constrictors-tonsils","stem":"Which nerve primarily provides motor innervation to the pharyngeal constrictor muscles?","options":[{"id":"a","text":"CN IX"},{"id":"b","text":"CN X"},{"id":"c","text":"CN XI"},{"id":"d","text":"CN XII"}],"answerId":"b","explanation":"The pharyngeal constrictors are primarily innervated by the vagus nerve (CN X) via the pharyngeal plexus.","kind":"recall","origin":"ai"},{"id":"pharynx-constrictors-tonsils~ai-1","moduleId":"pharynx-constrictors-tonsils","stem":"What is the main artery at risk of bleeding during a tonsillectomy?","options":[{"id":"a","text":"Facial artery"},{"id":"b","text":"Maxillary artery"},{"id":"c","text":"Lingual artery"},{"id":"d","text":"Thyroid artery"}],"answerId":"a","explanation":"The tonsillar branch of the facial artery is the main artery at risk during tonsillectomy.","kind":"recall","origin":"ai"},{"id":"pharynx-constrictors-tonsils~ai-2","moduleId":"pharynx-constrictors-tonsils","stem":"A patient presents with dysphagia, regurgitation of undigested food, and halitosis. What is the likely diagnosis?","options":[{"id":"a","text":"Zenker diverticulum"},{"id":"b","text":"Tonsillitis"},{"id":"c","text":"Pharyngeal cancer"},{"id":"d","text":"Esophageal stricture"}],"answerId":"a","explanation":"These symptoms are characteristic of Zenker diverticulum, which occurs due to a weakness in the pharyngeal wall.","kind":"clinical","origin":"ai"},{"id":"pharynx-constrictors-tonsils~ai-3","moduleId":"pharynx-constrictors-tonsils","stem":"Which structure is located in the piriform recess and is at risk during foreign body removal?","options":[{"id":"a","text":"Internal laryngeal nerve"},{"id":"b","text":"Recurrent laryngeal nerve"},{"id":"c","text":"Vagus nerve"},{"id":"d","text":"Glossopharyngeal nerve"}],"answerId":"a","explanation":"The internal laryngeal nerve runs in the mucosa of the piriform recess and can be injured during foreign body removal.","kind":"recall","origin":"ai"},{"id":"pharynx-constrictors-tonsils~ai-4","moduleId":"pharynx-constrictors-tonsils","stem":"What anatomical feature is associated with the herniation of a pharyngeal diverticulum?","options":[{"id":"a","text":"Killian's dehiscence"},{"id":"b","text":"Vallecula"},{"id":"c","text":"Epiglottis"},{"id":"d","text":"Palatine tonsil fossa"}],"answerId":"a","explanation":"Zenker diverticulum herniates through Killian's dehiscence, a weak area in the inferior constrictor.","kind":"mechanism","origin":"ai"},{"id":"pharynx-constrictors-tonsils~ai-5","moduleId":"pharynx-constrictors-tonsils","stem":"Which nerve is responsible for sensory innervation to the majority of the pharynx?","options":[{"id":"a","text":"CN IX"},{"id":"b","text":"CN X"},{"id":"c","text":"CN V"},{"id":"d","text":"CN XII"}],"answerId":"a","explanation":"The glossopharyngeal nerve (CN IX) provides sensory innervation to the majority of the pharynx.","kind":"recall","origin":"ai"},{"id":"pharynx-constrictors-tonsils~ai-6","moduleId":"pharynx-constrictors-tonsils","stem":"How does the innervation of the pharyngeal constrictors differ from that of the stylopharyngeus muscle?","options":[{"id":"a","text":"Both are innervated by CN IX"},{"id":"b","text":"Stylopharyngeus is innervated by CN X"},{"id":"c","text":"Stylopharyngeus is innervated by CN IX, others by CN X"},{"id":"d","text":"Both are innervated by CN XI"}],"answerId":"c","explanation":"The stylopharyngeus is innervated by CN IX, while the other pharyngeal constrictors are innervated by CN X.","kind":"trap","origin":"ai"},{"id":"pharynx-constrictors-tonsils~ai-7","moduleId":"pharynx-constrictors-tonsils","stem":"Which structure connects the pharynx to the larynx and is involved in sound production?","options":[{"id":"a","text":"Pharyngeal constrictors"},{"id":"b","text":"Laryngeal muscles"},{"id":"c","text":"Palatine tonsils"},{"id":"d","text":"Lingual tonsils"}],"answerId":"b","explanation":"The laryngeal muscles are responsible for sound production and are connected to the pharynx.","kind":"integration","linkedModuleIds":["laryngeal-muscles-nerves"],"origin":"ai"},{"id":"pharynx-constrictors-tonsils~ai-8","moduleId":"pharynx-constrictors-tonsils","stem":"How do the palatine tonsils relate to the pharyngeal constrictors in terms of anatomical location?","options":[{"id":"a","text":"Above the superior constrictor"},{"id":"b","text":"Between the middle and inferior constrictors"},{"id":"c","text":"Lateral to the inferior constrictor"},{"id":"d","text":"Medial to the superior constrictor"}],"answerId":"b","explanation":"The palatine tonsils are located in the tonsillar fossa, which is between the palatoglossal and palatopharyngeal arches, thus between the middle and inferior constrictors.","kind":"integration","linkedModuleIds":["larynx-cartilages-cavity"],"origin":"ai"}],"meninges-dural-sinuses":[{"id":"meninges-dural-sinuses~ai-0","moduleId":"meninges-dural-sinuses","stem":"Which meningeal layer is the toughest and forms two distinct layers?","options":[{"id":"a","text":"Arachnoid mater"},{"id":"b","text":"Pia mater"},{"id":"c","text":"Dura mater"},{"id":"d","text":"Subarachnoid space"}],"answerId":"c","explanation":"The dura mater is the toughest meningeal layer and consists of a periosteal and a meningeal layer.","kind":"recall","origin":"ai"},{"id":"meninges-dural-sinuses~ai-1","moduleId":"meninges-dural-sinuses","stem":"What is the most common source of an epidural hematoma?","options":[{"id":"a","text":"Torn bridging veins"},{"id":"b","text":"Middle meningeal artery"},{"id":"c","text":"Cerebral venous sinus"},{"id":"d","text":"Cavernous sinus"}],"answerId":"b","explanation":"Epidural hematomas are typically caused by arterial bleeding, most commonly from the middle meningeal artery.","kind":"recall","origin":"ai"},{"id":"meninges-dural-sinuses~ai-2","moduleId":"meninges-dural-sinuses","stem":"A patient presents with a crescent-shaped intracranial bleed after a fall. What is the most likely diagnosis?","options":[{"id":"a","text":"Epidural hematoma"},{"id":"b","text":"Subdural hematoma"},{"id":"c","text":"Subarachnoid hemorrhage"},{"id":"d","text":"Intracerebral hemorrhage"}],"answerId":"b","explanation":"A crescent shape indicates a subdural hematoma, typically due to venous bleeding from torn bridging veins.","kind":"clinical","origin":"ai"},{"id":"meninges-dural-sinuses~ai-3","moduleId":"meninges-dural-sinuses","stem":"Which of the following findings is characteristic of subarachnoid hemorrhage?","options":[{"id":"a","text":"Lucid interval"},{"id":"b","text":"Crescent-shaped bleed"},{"id":"c","text":"Thunderclap headache"},{"id":"d","text":"Biconvex shape on CT"}],"answerId":"c","explanation":"Subarachnoid hemorrhage is associated with a sudden, severe headache often described as a 'thunderclap' headache.","kind":"recall","origin":"ai"},{"id":"meninges-dural-sinuses~ai-4","moduleId":"meninges-dural-sinuses","stem":"What is the primary function of arachnoid granulations?","options":[{"id":"a","text":"Produce cerebrospinal fluid"},{"id":"b","text":"Drain CSF into venous blood"},{"id":"c","text":"Protect the brain from trauma"},{"id":"d","text":"Form the blood-brain barrier"}],"answerId":"b","explanation":"Arachnoid granulations are responsible for draining cerebrospinal fluid into the dural venous sinuses.","kind":"mechanism","origin":"ai"},{"id":"meninges-dural-sinuses~ai-5","moduleId":"meninges-dural-sinuses","stem":"How does the shape of an epidural hematoma differ from a subdural hematoma?","options":[{"id":"a","text":"Epidural is crescent-shaped; subdural is biconvex"},{"id":"b","text":"Epidural does not cross sutures; subdural does"},{"id":"c","text":"Both are crescent-shaped"},{"id":"d","text":"Both do not cross sutures"}],"answerId":"b","explanation":"Epidural hematomas are biconvex and do not cross sutures, while subdural hematomas are crescent-shaped and can cross sutures.","kind":"trap","origin":"ai"},{"id":"meninges-dural-sinuses~ai-6","moduleId":"meninges-dural-sinuses","stem":"A patient with a history of hypertension presents with a thunderclap headache and neck stiffness. Which linked condition should be evaluated?","options":[{"id":"a","text":"Epidural hematoma"},{"id":"b","text":"Subdural hematoma"},{"id":"c","text":"Subarachnoid hemorrhage"},{"id":"d","text":"Intracerebral hemorrhage"}],"answerId":"c","explanation":"The symptoms suggest subarachnoid hemorrhage, often associated with ruptured aneurysms, especially in patients with hypertension.","kind":"integration","linkedModuleIds":["ventricles-csf-circulation"],"origin":"ai"},{"id":"meninges-dural-sinuses~ai-7","moduleId":"meninges-dural-sinuses","stem":"A 70-year-old man falls and subsequently develops confusion. A CT scan reveals a crescent-shaped bleed. Which anatomical structure is likely involved?","options":[{"id":"a","text":"Middle meningeal artery"},{"id":"b","text":"Bridging veins"},{"id":"c","text":"Cavernous sinus"},{"id":"d","text":"Superior sagittal sinus"}],"answerId":"b","explanation":"The crescent-shaped bleed indicates a subdural hematoma, commonly caused by torn bridging veins in the elderly.","kind":"integration","linkedModuleIds":["epidural-subdural-hematoma"],"origin":"ai"}],"posterior-abdominal-wall-diaphragm":[{"id":"posterior-abdominal-wall-diaphragm~ai-0","moduleId":"posterior-abdominal-wall-diaphragm","stem":"What is the primary nerve responsible for motor and sensory innervation of the diaphragm?","options":[{"id":"a","text":"Vagus nerve"},{"id":"b","text":"Phrenic nerve"},{"id":"c","text":"Intercostal nerves"},{"id":"d","text":"Lumbar plexus"}],"answerId":"b","explanation":"The phrenic nerve (C3–C5) is the chief nerve supplying the diaphragm.","kind":"recall","origin":"ai"},{"id":"posterior-abdominal-wall-diaphragm~ai-1","moduleId":"posterior-abdominal-wall-diaphragm","stem":"At which vertebral level does the abdominal aorta bifurcate into the common iliac arteries?","options":[{"id":"a","text":"T12"},{"id":"b","text":"L1"},{"id":"c","text":"L3"},{"id":"d","text":"L4"}],"answerId":"d","explanation":"The abdominal aorta bifurcates at L4 into the common iliac arteries.","kind":"recall","origin":"ai"},{"id":"posterior-abdominal-wall-diaphragm~ai-2","moduleId":"posterior-abdominal-wall-diaphragm","stem":"A 70-year-old man presents with a pulsatile abdominal mass and back pain. What is the most likely diagnosis?","options":[{"id":"a","text":"Renal calculi"},{"id":"b","text":"Abdominal aortic aneurysm"},{"id":"c","text":"Pancreatitis"},{"id":"d","text":"Appendicitis"}],"answerId":"b","explanation":"The presentation is consistent with an abdominal aortic aneurysm, especially in an older male.","kind":"clinical","origin":"ai"},{"id":"posterior-abdominal-wall-diaphragm~ai-3","moduleId":"posterior-abdominal-wall-diaphragm","stem":"Which structure passes through the diaphragm at the T8 vertebral level?","options":[{"id":"a","text":"Esophagus"},{"id":"b","text":"Aorta"},{"id":"c","text":"Inferior vena cava"},{"id":"d","text":"Thoracic duct"}],"answerId":"c","explanation":"The inferior vena cava passes through the diaphragm at T8, while the esophagus passes at T10.","kind":"trap","origin":"ai"},{"id":"posterior-abdominal-wall-diaphragm~ai-4","moduleId":"posterior-abdominal-wall-diaphragm","stem":"What is the primary action of the psoas major muscle?","options":[{"id":"a","text":"Lateral trunk flexion"},{"id":"b","text":"Hip flexion"},{"id":"c","text":"Extension of the spine"},{"id":"d","text":"Abduction of the thigh"}],"answerId":"b","explanation":"The psoas major is primarily responsible for flexing the hip.","kind":"mechanism","origin":"ai"},{"id":"posterior-abdominal-wall-diaphragm~ai-5","moduleId":"posterior-abdominal-wall-diaphragm","stem":"A patient presents with referred pain to the shoulder tip. Which nerve is likely irritated?","options":[{"id":"a","text":"Vagus nerve"},{"id":"b","text":"Phrenic nerve"},{"id":"c","text":"Intercostal nerves"},{"id":"d","text":"Accessory nerve"}],"answerId":"b","explanation":"Referred shoulder-tip pain is due to irritation of the phrenic nerve (C3–C5).","kind":"clinical","origin":"ai"},{"id":"posterior-abdominal-wall-diaphragm~ai-6","moduleId":"posterior-abdominal-wall-diaphragm","stem":"How does the anatomy of the diaphragm relate to the function of the pudendal nerve?","options":[{"id":"a","text":"Both are involved in respiration"},{"id":"b","text":"Both innervate structures in the pelvic region"},{"id":"c","text":"Both are crucial for abdominal pressure regulation"},{"id":"d","text":"Both are involved in sensory innervation of the lower body"}],"answerId":"c","explanation":"The diaphragm helps regulate abdominal pressure, which is crucial for functions involving the pudendal nerve.","kind":"integration","linkedModuleIds":["hrp1-pudendal-erectile-external-genitalia"],"origin":"ai"},{"id":"posterior-abdominal-wall-diaphragm~ai-7","moduleId":"posterior-abdominal-wall-diaphragm","stem":"Which structure is NOT a branch of the abdominal aorta?","options":[{"id":"a","text":"Celiac trunk"},{"id":"b","text":"Inferior mesenteric artery"},{"id":"c","text":"Renal artery"},{"id":"d","text":"Femoral artery"}],"answerId":"d","explanation":"The femoral artery is a continuation of the external iliac artery, not a direct branch of the abdominal aorta.","kind":"trap","origin":"ai"}],"gi-blood-supply-portal-system":[{"id":"gi-blood-supply-portal-system~ai-0","moduleId":"gi-blood-supply-portal-system","stem":"Which artery supplies the midgut?","options":[{"id":"a","text":"Celiac trunk"},{"id":"b","text":"Superior mesenteric artery"},{"id":"c","text":"Inferior mesenteric artery"},{"id":"d","text":"Hepatic artery"}],"answerId":"b","explanation":"The superior mesenteric artery supplies the midgut, which includes the mid-duodenum to the proximal two-thirds of the transverse colon.","kind":"recall","origin":"ai"},{"id":"gi-blood-supply-portal-system~ai-1","moduleId":"gi-blood-supply-portal-system","stem":"What is the primary mechanism of pain referral in early appendicitis?","options":[{"id":"a","text":"Visceral pain from the parietal peritoneum"},{"id":"b","text":"Visceral pain from the midgut"},{"id":"c","text":"Somatic pain from the right lower quadrant"},{"id":"d","text":"Referred pain from the hindgut"}],"answerId":"b","explanation":"Early appendicitis causes visceral pain that refers to the periumbilical region due to midgut innervation.","kind":"mechanism","origin":"ai"},{"id":"gi-blood-supply-portal-system~ai-2","moduleId":"gi-blood-supply-portal-system","stem":"A patient presents with hematemesis. Which condition is most likely indicated?","options":[{"id":"a","text":"Peptic ulcer disease"},{"id":"b","text":"Esophageal varices"},{"id":"c","text":"Gastritis"},{"id":"d","text":"Pancreatitis"}],"answerId":"b","explanation":"Hematemeis is commonly associated with esophageal varices due to portal hypertension.","kind":"clinical","origin":"ai"},{"id":"gi-blood-supply-portal-system~ai-3","moduleId":"gi-blood-supply-portal-system","stem":"Which watershed area is most vulnerable to ischemia?","options":[{"id":"a","text":"Celiac trunk and renal artery"},{"id":"b","text":"SMA and IMA"},{"id":"c","text":"Hepatic artery and splenic artery"},{"id":"d","text":"Superior mesenteric artery and inferior mesenteric artery"}],"answerId":"b","explanation":"The watershed area between the SMA and IMA is known as Griffith's point and is particularly susceptible to ischemia.","kind":"recall","origin":"ai"},{"id":"gi-blood-supply-portal-system~ai-4","moduleId":"gi-blood-supply-portal-system","stem":"In portal hypertension, which of the following is a common portosystemic anastomosis?","options":[{"id":"a","text":"Left gastric and splenic vein"},{"id":"b","text":"Inferior mesenteric and renal vein"},{"id":"c","text":"Paraumbilical and epigastric veins"},{"id":"d","text":"Superior rectal and inferior mesenteric vein"}],"answerId":"c","explanation":"In portal hypertension, the paraumbilical and epigastric veins form an anastomosis leading to caput medusae.","kind":"recall","origin":"ai"},{"id":"gi-blood-supply-portal-system~ai-5","moduleId":"gi-blood-supply-portal-system","stem":"How does the anatomy of the liver relate to the portal system?","options":[{"id":"a","text":"The liver receives oxygenated blood exclusively"},{"id":"b","text":"The portal vein carries nutrient-rich blood to the liver"},{"id":"c","text":"The liver is supplied by the inferior mesenteric artery"},{"id":"d","text":"The hepatic artery drains directly into the inferior vena cava"}],"answerId":"b","explanation":"The hepatic portal vein carries nutrient-rich blood from the gastrointestinal tract to the liver for processing.","kind":"integration","linkedModuleIds":["liver-biliary-pancreas"],"origin":"ai"},{"id":"gi-blood-supply-portal-system~ai-6","moduleId":"gi-blood-supply-portal-system","stem":"What is a common complication of appendicitis related to its blood supply?","options":[{"id":"a","text":"Hemorrhage due to splenic artery rupture"},{"id":"b","text":"Ischemia due to appendicular artery occlusion"},{"id":"c","text":"Bowel obstruction due to volvulus"},{"id":"d","text":"Portal hypertension due to liver cirrhosis"}],"answerId":"b","explanation":"The appendicular artery is an end artery, making it susceptible to ischemia and perforation in appendicitis.","kind":"trap","origin":"ai"}],"small-large-intestine":[{"id":"small-large-intestine~ai-0","moduleId":"small-large-intestine","stem":"Which part of the small intestine is primarily responsible for nutrient absorption and has tall, dense plicae circulares?","options":[{"id":"a","text":"Duodenum"},{"id":"b","text":"Jejunum"},{"id":"c","text":"Ileum"},{"id":"d","text":"Cecum"}],"answerId":"b","explanation":"The jejunum is characterized by thicker walls and taller, denser plicae circulares, making it the primary site for nutrient absorption.","kind":"recall","origin":"ai"},{"id":"small-large-intestine~ai-1","moduleId":"small-large-intestine","stem":"What is the main anatomical landmark that divides upper from lower gastrointestinal bleeding?","options":[{"id":"a","text":"Ileocecal junction"},{"id":"b","text":"Suspensory ligament of the duodenum"},{"id":"c","text":"Major duodenal papilla"},{"id":"d","text":"McBurney's point"}],"answerId":"b","explanation":"The suspensory ligament of the duodenum (ligament of Treitz) is the anatomical landmark that divides upper from lower GI bleeding.","kind":"recall","origin":"ai"},{"id":"small-large-intestine~ai-2","moduleId":"small-large-intestine","stem":"A patient presents with periumbilical pain that localizes to the right lower quadrant. What is the most likely diagnosis?","options":[{"id":"a","text":"Cholecystitis"},{"id":"b","text":"Appendicitis"},{"id":"c","text":"Diverticulitis"},{"id":"d","text":"Pancreatitis"}],"answerId":"b","explanation":"The pattern of pain is characteristic of appendicitis, where pain starts periumbilical and then localizes to McBurney's point in the RLQ.","kind":"clinical","origin":"ai"},{"id":"small-large-intestine~ai-3","moduleId":"small-large-intestine","stem":"Which feature is NOT characteristic of the large intestine?","options":[{"id":"a","text":"Teniae coli"},{"id":"b","text":"Plicae circulares"},{"id":"c","text":"Haustra"},{"id":"d","text":"Omental appendices"}],"answerId":"b","explanation":"Plicae circulares are primarily found in the small intestine, while the large intestine is identified by teniae coli, haustra, and omental appendices.","kind":"trap","origin":"ai"},{"id":"small-large-intestine~ai-4","moduleId":"small-large-intestine","stem":"What type of innervation is found above the dentate line of the anal canal?","options":[{"id":"a","text":"Visceral, autonomic, insensate"},{"id":"b","text":"Somatic, pudendal, painful"},{"id":"c","text":"Visceral, somatic, painful"},{"id":"d","text":"Somatic, autonomic, insensate"}],"answerId":"a","explanation":"Above the dentate line, the anal canal is innervated by visceral nerves, which are autonomic and insensate.","kind":"recall","origin":"ai"},{"id":"small-large-intestine~ai-5","moduleId":"small-large-intestine","stem":"In a patient with Crohn's disease affecting the ileum, which histological feature would you expect to find?","options":[{"id":"a","text":"Peyer patches"},{"id":"b","text":"Tall plicae circulares"},{"id":"c","text":"Haustra"},{"id":"d","text":"Teniae coli"}],"answerId":"a","explanation":"Peyer patches are lymphoid follicles found in the ileum and are characteristic of Crohn's disease.","kind":"integration","linkedModuleIds":["intestinal-anal-histology"],"origin":"ai"},{"id":"small-large-intestine~ai-6","moduleId":"small-large-intestine","stem":"Which condition could lead to ischemia of the small intestine due to compromised blood supply?","options":[{"id":"a","text":"Appendicitis"},{"id":"b","text":"Mesenteric ischemia"},{"id":"c","text":"Diverticulitis"},{"id":"d","text":"Cholecystitis"}],"answerId":"b","explanation":"Mesenteric ischemia occurs when blood flow to the intestines is reduced, leading to ischemia, particularly affecting the small intestine.","kind":"integration","linkedModuleIds":["gi-blood-supply-portal-system"],"origin":"ai"}],"kidney-ureter-anatomy":[{"id":"kidney-ureter-anatomy~ai-0","moduleId":"kidney-ureter-anatomy","stem":"What is the primary reason the right kidney is positioned lower than the left kidney?","options":[{"id":"a","text":"It is smaller in size"},{"id":"b","text":"It is pushed down by the liver"},{"id":"c","text":"It has a longer renal vein"},{"id":"d","text":"It is more prone to injury"}],"answerId":"b","explanation":"The right kidney is lower due to the presence of the liver above it, which pushes it down.","kind":"recall","origin":"ai"},{"id":"kidney-ureter-anatomy~ai-1","moduleId":"kidney-ureter-anatomy","stem":"Which structure is NOT found in the renal hilum?","options":[{"id":"a","text":"Renal vein"},{"id":"b","text":"Renal artery"},{"id":"c","text":"Ureter"},{"id":"d","text":"Renal cortex"}],"answerId":"d","explanation":"The renal cortex is part of the kidney's outer layer and does not pass through the renal hilum.","kind":"trap","origin":"ai"},{"id":"kidney-ureter-anatomy~ai-2","moduleId":"kidney-ureter-anatomy","stem":"What is the most common site for ureteric stones to lodge?","options":[{"id":"a","text":"Ureteropelvic junction"},{"id":"b","text":"Pelvic brim"},{"id":"c","text":"Ureterovesical junction"},{"id":"d","text":"Renal pelvis"}],"answerId":"a","explanation":"The ureteropelvic junction is a common site for stones to lodge due to its anatomical constriction.","kind":"recall","origin":"ai"},{"id":"kidney-ureter-anatomy~ai-3","moduleId":"kidney-ureter-anatomy","stem":"What type of pain is typically associated with renal colic due to a ureteric stone?","options":[{"id":"a","text":"Dull abdominal pain"},{"id":"b","text":"Severe colicky flank pain"},{"id":"c","text":"Constant lower back pain"},{"id":"d","text":"Localized pain in the bladder"}],"answerId":"b","explanation":"Renal colic is characterized by severe colicky flank pain that can radiate to the groin.","kind":"recall","origin":"ai"},{"id":"kidney-ureter-anatomy~ai-4","moduleId":"kidney-ureter-anatomy","stem":"Which statement about renal segmental arteries is true?","options":[{"id":"a","text":"They freely anastomose with each other"},{"id":"b","text":"Occlusion of one causes a segmental infarct"},{"id":"c","text":"They are the main supply to the renal cortex"},{"id":"d","text":"They are not involved in renal blood supply"}],"answerId":"b","explanation":"Renal segmental arteries are end arteries with no anastomoses; occlusion of one leads to a segmental infarct.","kind":"mechanism","origin":"ai"},{"id":"kidney-ureter-anatomy~ai-5","moduleId":"kidney-ureter-anatomy","stem":"A patient presents with flank pain radiating to the groin. Which structure's obstruction is most likely causing this symptom?","options":[{"id":"a","text":"Renal artery"},{"id":"b","text":"Ureter"},{"id":"c","text":"Renal vein"},{"id":"d","text":"Bladder"}],"answerId":"b","explanation":"Obstruction of the ureter by a stone typically causes flank pain that radiates to the groin.","kind":"clinical","origin":"ai"},{"id":"kidney-ureter-anatomy~ai-6","moduleId":"kidney-ureter-anatomy","stem":"How does the anatomy of the ureter relate to the development of kidney stones?","options":[{"id":"a","text":"Ureter has no constrictions"},{"id":"b","text":"Ureter's length prevents stones"},{"id":"c","text":"Ureter has three constrictions"},{"id":"d","text":"Ureter is intraperitoneal"}],"answerId":"c","explanation":"The ureter has three anatomical constrictions where stones are more likely to lodge, contributing to stone formation.","kind":"integration","linkedModuleIds":["nephrolithiasis-urolithiasis"],"origin":"ai"},{"id":"kidney-ureter-anatomy~ai-7","moduleId":"kidney-ureter-anatomy","stem":"How does the position of the kidneys relate to the posterior abdominal wall anatomy?","options":[{"id":"a","text":"They are intraperitoneal organs"},{"id":"b","text":"They are retroperitoneal organs"},{"id":"c","text":"They are located in the pelvic cavity"},{"id":"d","text":"They are covered by the diaphragm"}],"answerId":"b","explanation":"The kidneys are retroperitoneal organs, located behind the peritoneum along the posterior abdominal wall.","kind":"integration","linkedModuleIds":["posterior-abdominal-wall-diaphragm"],"origin":"ai"}],"lumbar-plexus":[{"id":"lumbar-plexus~ai-0","moduleId":"lumbar-plexus","stem":"Which nerve is primarily responsible for knee extension?","options":[{"id":"a","text":"Obturator nerve"},{"id":"b","text":"Femoral nerve"},{"id":"c","text":"Lateral femoral cutaneous nerve"},{"id":"d","text":"Genitofemoral nerve"}],"answerId":"b","explanation":"The femoral nerve (L2–L4) innervates the quadriceps muscle, which is responsible for knee extension.","kind":"recall","origin":"ai"},{"id":"lumbar-plexus~ai-1","moduleId":"lumbar-plexus","stem":"A patient presents with burning numbness over the lateral thigh. Which nerve is likely entrapped?","options":[{"id":"a","text":"Femoral nerve"},{"id":"b","text":"Obturator nerve"},{"id":"c","text":"Lateral femoral cutaneous nerve"},{"id":"d","text":"Genitofemoral nerve"}],"answerId":"c","explanation":"The lateral femoral cutaneous nerve (L2–L3) is responsible for sensation in the lateral thigh and can be entrapped, causing meralgia paresthetica.","kind":"clinical","origin":"ai"},{"id":"lumbar-plexus~ai-2","moduleId":"lumbar-plexus","stem":"What is the primary function of the obturator nerve?","options":[{"id":"a","text":"Knee extension"},{"id":"b","text":"Thigh adduction"},{"id":"c","text":"Sensory to the lateral thigh"},{"id":"d","text":"Cremaster reflex"}],"answerId":"b","explanation":"The obturator nerve (L2–L4) primarily innervates the thigh adductor muscles.","kind":"recall","origin":"ai"},{"id":"lumbar-plexus~ai-3","moduleId":"lumbar-plexus","stem":"A patient has weak thigh adduction. Which nerve is most likely injured?","options":[{"id":"a","text":"Femoral nerve"},{"id":"b","text":"Obturator nerve"},{"id":"c","text":"Lateral femoral cutaneous nerve"},{"id":"d","text":"Ilioinguinal nerve"}],"answerId":"b","explanation":"Weak thigh adduction indicates an injury to the obturator nerve (L2–L4), which innervates the adductor muscles.","kind":"clinical","origin":"ai"},{"id":"lumbar-plexus~ai-4","moduleId":"lumbar-plexus","stem":"Which statement correctly distinguishes the functions of the femoral and obturator nerves?","options":[{"id":"a","text":"Both supply knee extensors"},{"id":"b","text":"Femoral nerve supplies adductors, obturator nerve supplies extensors"},{"id":"c","text":"Femoral nerve supplies extensors, obturator nerve supplies adductors"},{"id":"d","text":"Both are purely sensory nerves"}],"answerId":"c","explanation":"The femoral nerve supplies knee extensors (quadriceps), while the obturator nerve supplies thigh adductors.","kind":"trap","origin":"ai"},{"id":"lumbar-plexus~ai-5","moduleId":"lumbar-plexus","stem":"Which muscle is innervated by the femoral nerve?","options":[{"id":"a","text":"Iliacus"},{"id":"b","text":"Adductor longus"},{"id":"c","text":"Gracilis"},{"id":"d","text":"Pectineus"}],"answerId":"a","explanation":"The femoral nerve innervates the iliacus muscle, along with the quadriceps and other anterior thigh muscles.","kind":"recall","origin":"ai"},{"id":"lumbar-plexus~ai-7","moduleId":"lumbar-plexus","stem":"Which structure is NOT supplied by the lumbar plexus?","options":[{"id":"a","text":"Quadriceps muscle"},{"id":"b","text":"Adductor muscles"},{"id":"c","text":"Diaphragm"},{"id":"d","text":"Skin of the medial thigh"}],"answerId":"c","explanation":"The diaphragm is innervated by the phrenic nerve, not the lumbar plexus, which supplies the lower limb and parts of the abdominal wall.","kind":"integration","linkedModuleIds":["kidney-ureter-anatomy"],"origin":"ai"}],"abdominal-wall-rectus-sheath":[{"id":"abdominal-wall-rectus-sheath~ai-0","moduleId":"abdominal-wall-rectus-sheath","stem":"Which layer lies directly beneath the rectus abdominis muscle below the arcuate line?","options":[{"id":"a","text":"Transversalis fascia"},{"id":"b","text":"Posterior rectus sheath"},{"id":"c","text":"Scarpa's fascia"},{"id":"d","text":"Peritoneum"}],"answerId":"a","explanation":"Below the arcuate line, the rectus abdominis lies directly on the transversalis fascia due to the absence of the posterior rectus sheath.","kind":"recall","origin":"ai"},{"id":"abdominal-wall-rectus-sheath~ai-1","moduleId":"abdominal-wall-rectus-sheath","stem":"What is the primary blood supply to the rectus abdominis muscle?","options":[{"id":"a","text":"Inferior epigastric artery"},{"id":"b","text":"Superior epigastric artery"},{"id":"c","text":"External iliac artery"},{"id":"d","text":"Internal thoracic artery"}],"answerId":"b","explanation":"The superior epigastric artery, a branch of the internal thoracic artery, primarily supplies the rectus abdominis muscle.","kind":"recall","origin":"ai"},{"id":"abdominal-wall-rectus-sheath~ai-2","moduleId":"abdominal-wall-rectus-sheath","stem":"Which dermatome corresponds to the umbilicus?","options":[{"id":"a","text":"T7"},{"id":"b","text":"T10"},{"id":"c","text":"L1"},{"id":"d","text":"T12"}],"answerId":"b","explanation":"The umbilicus is innervated by the T10 dermatome.","kind":"recall","origin":"ai"},{"id":"abdominal-wall-rectus-sheath~ai-3","moduleId":"abdominal-wall-rectus-sheath","stem":"What happens to the internal oblique aponeurosis at the arcuate line?","options":[{"id":"a","text":"It becomes absent"},{"id":"b","text":"It splits to enclose the rectus"},{"id":"c","text":"It fuses with the external oblique"},{"id":"d","text":"It thickens significantly"}],"answerId":"b","explanation":"Above the arcuate line, the internal oblique aponeurosis splits to enclose the rectus abdominis, forming both anterior and posterior sheaths.","kind":"mechanism","origin":"ai"},{"id":"abdominal-wall-rectus-sheath~ai-4","moduleId":"abdominal-wall-rectus-sheath","stem":"A patient presents with a rectus sheath hematoma. Which vessel is most likely involved?","options":[{"id":"a","text":"Superior epigastric artery"},{"id":"b","text":"Inferior epigastric artery"},{"id":"c","text":"Internal thoracic artery"},{"id":"d","text":"External iliac artery"}],"answerId":"b","explanation":"Rectus sheath hematomas are commonly associated with tears of the inferior epigastric artery, which lies within the sheath.","kind":"clinical","origin":"ai"},{"id":"abdominal-wall-rectus-sheath~ai-5","moduleId":"abdominal-wall-rectus-sheath","stem":"Which statement is true regarding the rectus sheath below the arcuate line?","options":[{"id":"a","text":"The posterior sheath is complete"},{"id":"b","text":"All three aponeuroses pass anteriorly"},{"id":"c","text":"The rectus is covered by peritoneum"},{"id":"d","text":"The inferior epigastric vessels are absent"}],"answerId":"b","explanation":"Below the arcuate line, all three aponeuroses pass anterior to the rectus abdominis, resulting in an absent posterior sheath.","kind":"trap","origin":"ai"},{"id":"abdominal-wall-rectus-sheath~ai-6","moduleId":"abdominal-wall-rectus-sheath","stem":"How does the rectus sheath relate to the dermatomes of the abdominal wall?","options":[{"id":"a","text":"It provides sensory innervation"},{"id":"b","text":"It serves as a landmark for T10"},{"id":"c","text":"It is innervated by L1"},{"id":"d","text":"It contains the thoraco-abdominal nerves"}],"answerId":"b","explanation":"The rectus sheath serves as a landmark for the T10 dermatome, which corresponds to the umbilicus.","kind":"integration","linkedModuleIds":["dermatomes-spinal-nerves"],"origin":"ai"},{"id":"abdominal-wall-rectus-sheath~ai-7","moduleId":"abdominal-wall-rectus-sheath","stem":"Which structure is most relevant when considering inguinal hernias in relation to the rectus sheath?","options":[{"id":"a","text":"Inferior epigastric artery"},{"id":"b","text":"Transversalis fascia"},{"id":"c","text":"Linea alba"},{"id":"d","text":"Scarpa's fascia"}],"answerId":"a","explanation":"The inferior epigastric artery is a key landmark in the context of inguinal hernias, as it lies adjacent to the rectus abdominis below the arcuate line.","kind":"integration","linkedModuleIds":["inguinal-canal-hernias"],"origin":"ai"}],"peritoneum-stomach":[{"id":"peritoneum-stomach~ai-0","moduleId":"peritoneum-stomach","stem":"Which of the following organs is classified as retroperitoneal?","options":[{"id":"a","text":"Stomach"},{"id":"b","text":"Spleen"},{"id":"c","text":"Kidney"},{"id":"d","text":"Liver"}],"answerId":"c","explanation":"The kidney is a retroperitoneal organ, while the stomach, spleen, and liver are intraperitoneal.","kind":"recall","origin":"ai"},{"id":"peritoneum-stomach~ai-1","moduleId":"peritoneum-stomach","stem":"What is the primary blood supply to the lesser curvature of the stomach?","options":[{"id":"a","text":"Right gastro-omental artery"},{"id":"b","text":"Left gastro-omental artery"},{"id":"c","text":"Right gastric artery"},{"id":"d","text":"Short gastric arteries"}],"answerId":"c","explanation":"The right gastric artery, a branch of the hepatic artery, supplies the lesser curvature of the stomach.","kind":"recall","origin":"ai"},{"id":"peritoneum-stomach~ai-2","moduleId":"peritoneum-stomach","stem":"Which structure is anterior to the omental foramen?","options":[{"id":"a","text":"Hepatoduodenal ligament"},{"id":"b","text":"Greater omentum"},{"id":"c","text":"Lesser omentum"},{"id":"d","text":"Portal vein"}],"answerId":"a","explanation":"The hepatoduodenal ligament is anterior to the omental foramen and contains the portal triad.","kind":"mechanism","origin":"ai"},{"id":"peritoneum-stomach~ai-3","moduleId":"peritoneum-stomach","stem":"A patient presents with epigastric pain and a history of gastric ulcers. Which nerve is primarily responsible for the pain sensation?","options":[{"id":"a","text":"Vagus nerve"},{"id":"b","text":"Phrenic nerve"},{"id":"c","text":"Greater splanchnic nerve"},{"id":"d","text":"Lesser splanchnic nerve"}],"answerId":"c","explanation":"Visceral afferents from the foregut, including the stomach, travel via the greater splanchnic nerve to convey pain.","kind":"clinical","origin":"ai"},{"id":"peritoneum-stomach~ai-4","moduleId":"peritoneum-stomach","stem":"In which part of the duodenum does the peritoneal cavity become retroperitoneal?","options":[{"id":"a","text":"1st part"},{"id":"b","text":"2nd part"},{"id":"c","text":"3rd part"},{"id":"d","text":"4th part"}],"answerId":"b","explanation":"Only the 1st part of the duodenum is intraperitoneal; the 2nd to 4th parts are retroperitoneal.","kind":"trap","origin":"ai"},{"id":"peritoneum-stomach~ai-5","moduleId":"peritoneum-stomach","stem":"Fluid accumulation in the hepatorenal recess is most likely due to which condition?","options":[{"id":"a","text":"Pancreatitis"},{"id":"b","text":"Appendicitis"},{"id":"c","text":"Peritonitis"},{"id":"d","text":"Cholecystitis"}],"answerId":"c","explanation":"The hepatorenal recess is the lowest point in the supine abdomen, where fluid from peritonitis typically collects.","kind":"recall","origin":"ai"},{"id":"peritoneum-stomach~ai-6","moduleId":"peritoneum-stomach","stem":"How does the anatomy of the stomach relate to the adrenal glands?","options":[{"id":"a","text":"Both are supplied by the celiac trunk"},{"id":"b","text":"Both are intraperitoneal organs"},{"id":"c","text":"Both are innervated by the vagus nerve"},{"id":"d","text":"Both have a similar blood supply"}],"answerId":"a","explanation":"Both the stomach and adrenal glands receive blood supply from branches of the celiac trunk, linking their vascular anatomy.","kind":"integration","linkedModuleIds":["hen1-adrenal-gross-anatomy-vasculature"],"origin":"ai"},{"id":"peritoneum-stomach~ai-7","moduleId":"peritoneum-stomach","stem":"What is the significance of the greater omentum in abdominal infections?","options":[{"id":"a","text":"It provides structural support to the liver"},{"id":"b","text":"It can wall off infections"},{"id":"c","text":"It is a major site for nutrient absorption"},{"id":"d","text":"It connects the stomach to the diaphragm"}],"answerId":"b","explanation":"The greater omentum acts as an 'abdominal policeman' by walling off infections and preventing their spread.","kind":"clinical","origin":"ai"}],"salivary-glands-oral-clinical":[{"id":"salivary-glands-oral-clinical~ai-0","moduleId":"salivary-glands-oral-clinical","stem":"Which cranial nerve provides secretomotor fibers to the parotid gland?","options":[{"id":"a","text":"CN VII"},{"id":"b","text":"CN IX"},{"id":"c","text":"CN V"},{"id":"d","text":"CN X"}],"answerId":"b","explanation":"The parotid gland receives secretomotor fibers from CN IX via the lesser petrosal nerve.","kind":"recall","origin":"ai"},{"id":"salivary-glands-oral-clinical~ai-1","moduleId":"salivary-glands-oral-clinical","stem":"What is the primary mechanism for the rapid absorption of sublingual medications?","options":[{"id":"a","text":"Direct lymphatic uptake"},{"id":"b","text":"Rich blood supply from deep lingual veins"},{"id":"c","text":"Mucosal permeability"},{"id":"d","text":"Salivary enzyme activity"}],"answerId":"b","explanation":"Sublingual medications are rapidly absorbed due to the rich blood supply from deep lingual veins.","kind":"mechanism","origin":"ai"},{"id":"salivary-glands-oral-clinical~ai-2","moduleId":"salivary-glands-oral-clinical","stem":"A patient presents with loss of taste and sensation in the anterior two-thirds of the tongue after submandibular gland surgery. What is the likely cause?","options":[{"id":"a","text":"Facial nerve injury"},{"id":"b","text":"Lingual nerve injury"},{"id":"c","text":"Glossopharyngeal nerve injury"},{"id":"d","text":"Vagus nerve injury"}],"answerId":"b","explanation":"Injury to the lingual nerve, which carries the chorda tympani, results in loss of taste and sensation in the anterior two-thirds of the tongue.","kind":"clinical","origin":"ai"},{"id":"salivary-glands-oral-clinical~ai-3","moduleId":"salivary-glands-oral-clinical","stem":"Which of the following is true regarding the innervation of the submandibular gland?","options":[{"id":"a","text":"It receives fibers from CN V"},{"id":"b","text":"It is solely innervated by CN VII"},{"id":"c","text":"It receives fibers from CN IX"},{"id":"d","text":"It is innervated by both CN VII and CN IX"}],"answerId":"b","explanation":"The submandibular gland is innervated by CN VII via the chorda tympani, while the parotid gland is innervated by CN IX.","kind":"trap","origin":"ai"},{"id":"salivary-glands-oral-clinical~ai-4","moduleId":"salivary-glands-oral-clinical","stem":"What is the primary function of the nasopalatine nerve during palatal nerve blocks?","options":[{"id":"a","text":"Anesthetizes the anterior hard palate"},{"id":"b","text":"Anesthetizes the posterior hard palate"},{"id":"c","text":"Provides taste sensation to the tongue"},{"id":"d","text":"Innervates the submandibular gland"}],"answerId":"a","explanation":"The nasopalatine nerve anesthetizes the anterior hard palate, particularly at the incisive papilla.","kind":"recall","origin":"ai"},{"id":"salivary-glands-oral-clinical~ai-5","moduleId":"salivary-glands-oral-clinical","stem":"How does the mechanism of action for glyceryl trinitrate differ when administered sublingually compared to orally?","options":[{"id":"a","text":"Increased first-pass metabolism"},{"id":"b","text":"Rapid systemic absorption"},{"id":"c","text":"Decreased bioavailability"},{"id":"d","text":"Delayed onset of action"}],"answerId":"b","explanation":"Sublingual administration allows for rapid systemic absorption, bypassing first-pass metabolism.","kind":"integration","linkedModuleIds":["salivary-esophageal-mucus-secretion"],"origin":"ai"},{"id":"salivary-glands-oral-clinical~ai-6","moduleId":"salivary-glands-oral-clinical","stem":"Which salivary gland is primarily responsible for serous secretion?","options":[{"id":"a","text":"Sublingual gland"},{"id":"b","text":"Submandibular gland"},{"id":"c","text":"Parotid gland"},{"id":"d","text":"Minor salivary glands"}],"answerId":"c","explanation":"The parotid gland is primarily responsible for serous secretion.","kind":"recall","origin":"ai"},{"id":"salivary-glands-oral-clinical~ai-7","moduleId":"salivary-glands-oral-clinical","stem":"In the context of salivary gland function, what is the role of the chorda tympani?","options":[{"id":"a","text":"Carries taste fibers from the posterior tongue"},{"id":"b","text":"Innervates the parotid gland"},{"id":"c","text":"Carries secretomotor fibers to the submandibular gland"},{"id":"d","text":"Provides sensory innervation to the hard palate"}],"answerId":"c","explanation":"The chorda tympani carries secretomotor fibers to the submandibular and sublingual glands.","kind":"recall","origin":"ai"},{"id":"salivary-glands-oral-clinical~ai-8","moduleId":"salivary-glands-oral-clinical","stem":"What is the clinical significance of the lingual nerve's position relative to the submandibular duct?","options":[{"id":"a","text":"It is at risk during maxillary molar extraction"},{"id":"b","text":"It can be injured during submandibular gland surgery"},{"id":"c","text":"It supplies taste to the posterior tongue"},{"id":"d","text":"It innervates the parotid gland"}],"answerId":"b","explanation":"The lingual nerve is at risk of injury during submandibular gland surgery due to its proximity to the duct.","kind":"trap","origin":"ai"}],"inguinal-canal-hernias":[{"id":"inguinal-canal-hernias~ai-0","moduleId":"inguinal-canal-hernias","stem":"Which structure is found in the spermatic cord?","options":[{"id":"a","text":"Cremasteric muscle"},{"id":"b","text":"Rectus abdominis"},{"id":"c","text":"Inferior epigastric artery"},{"id":"d","text":"Iliohypogastric nerve"}],"answerId":"a","explanation":"The spermatic cord contains the cremasteric muscle, which is derived from the internal oblique muscle.","kind":"recall","origin":"ai"},{"id":"inguinal-canal-hernias~ai-1","moduleId":"inguinal-canal-hernias","stem":"What is the primary mechanism of an indirect inguinal hernia?","options":[{"id":"a","text":"Weakness in the transversalis fascia"},{"id":"b","text":"Failure of the processus vaginalis to close"},{"id":"c","text":"Increased intra-abdominal pressure"},{"id":"d","text":"Trauma to the inguinal region"}],"answerId":"b","explanation":"An indirect inguinal hernia is often due to a patent processus vaginalis, allowing abdominal contents to pass through the deep inguinal ring.","kind":"mechanism","origin":"ai"},{"id":"inguinal-canal-hernias~ai-2","moduleId":"inguinal-canal-hernias","stem":"A patient presents with a groin bulge that is tender and irreducible. What is the most likely diagnosis?","options":[{"id":"a","text":"Indirect inguinal hernia"},{"id":"b","text":"Direct inguinal hernia"},{"id":"c","text":"Strangulated hernia"},{"id":"d","text":"Femoral hernia"}],"answerId":"c","explanation":"A tender, irreducible, non-transilluminating groin lump suggests a strangulated hernia, which is a surgical emergency.","kind":"clinical","origin":"ai"},{"id":"inguinal-canal-hernias~ai-3","moduleId":"inguinal-canal-hernias","stem":"Which of the following statements about direct and indirect inguinal hernias is correct?","options":[{"id":"a","text":"Direct hernias pass lateral to the inferior epigastric artery."},{"id":"b","text":"Indirect hernias occur through Hesselbach's triangle."},{"id":"c","text":"Direct hernias are more common in younger patients."},{"id":"d","text":"Indirect hernias are typically congenital."}],"answerId":"d","explanation":"Indirect inguinal hernias are often congenital and occur lateral to the inferior epigastric artery, while direct hernias are acquired and occur medial to it.","kind":"trap","origin":"ai"},{"id":"inguinal-canal-hernias~ai-4","moduleId":"inguinal-canal-hernias","stem":"What anatomical landmark separates direct from indirect inguinal hernias?","options":[{"id":"a","text":"Inguinal ligament"},{"id":"b","text":"Inferior epigastric artery"},{"id":"c","text":"Rectus abdominis"},{"id":"d","text":"Transversalis fascia"}],"answerId":"b","explanation":"The inferior epigastric artery serves as the key landmark: indirect hernias are lateral and direct hernias are medial to it.","kind":"recall","origin":"ai"},{"id":"inguinal-canal-hernias~ai-5","moduleId":"inguinal-canal-hernias","stem":"How does the anatomy of the inguinal canal relate to the anterior abdominal wall?","options":[{"id":"a","text":"The inguinal canal is formed by the rectus abdominis."},{"id":"b","text":"The inguinal canal is a continuation of the peritoneum."},{"id":"c","text":"The inguinal canal contains the ilioinguinal nerve."},{"id":"d","text":"The inguinal canal is located entirely within the transversalis fascia."}],"answerId":"c","explanation":"The inguinal canal contains the ilioinguinal nerve, which runs through it, highlighting the connection between these structures.","kind":"integration","linkedModuleIds":["abdominal-wall-rectus-sheath"],"origin":"ai"},{"id":"inguinal-canal-hernias~ai-6","moduleId":"inguinal-canal-hernias","stem":"Which hernia type is more likely to occur due to increased intra-abdominal pressure?","options":[{"id":"a","text":"Indirect inguinal hernia"},{"id":"b","text":"Direct inguinal hernia"},{"id":"c","text":"Umbilical hernia"},{"id":"d","text":"Femoral hernia"}],"answerId":"b","explanation":"Direct inguinal hernias are often acquired due to increased intra-abdominal pressure leading to weakness in the abdominal wall.","kind":"integration","linkedModuleIds":["peritoneum-stomach"],"origin":"ai"}],"liver-biliary-pancreas":[{"id":"liver-biliary-pancreas~ai-0","moduleId":"liver-biliary-pancreas","stem":"Which structure is located at the porta hepatis?","options":[{"id":"a","text":"Hepatic artery"},{"id":"b","text":"Cystic duct"},{"id":"c","text":"Inferior vena cava"},{"id":"d","text":"Gallbladder"}],"answerId":"a","explanation":"The porta hepatis contains the hepatic artery, portal vein, and hepatic ducts.","kind":"recall","origin":"ai"},{"id":"liver-biliary-pancreas~ai-1","moduleId":"liver-biliary-pancreas","stem":"What is the primary blood supply to the liver?","options":[{"id":"a","text":"Hepatic artery"},{"id":"b","text":"Hepatic portal vein"},{"id":"c","text":"Celiac trunk"},{"id":"d","text":"Inferior vena cava"}],"answerId":"b","explanation":"The liver receives approximately 75-80% of its blood supply from the hepatic portal vein.","kind":"recall","origin":"ai"},{"id":"liver-biliary-pancreas~ai-2","moduleId":"liver-biliary-pancreas","stem":"During a cholecystectomy, which structure is at risk of injury if the cystic artery is misidentified?","options":[{"id":"a","text":"Common bile duct"},{"id":"b","text":"Hepatic artery"},{"id":"c","text":"Pancreatic duct"},{"id":"d","text":"Portal vein"}],"answerId":"a","explanation":"Injury to the common bile duct can occur if the cystic artery is misidentified in the Calot triangle.","kind":"mechanism","origin":"ai"},{"id":"liver-biliary-pancreas~ai-3","moduleId":"liver-biliary-pancreas","stem":"What clinical finding is associated with portal hypertension?","options":[{"id":"a","text":"Caput medusae"},{"id":"b","text":"Jaundice"},{"id":"c","text":"Ascites"},{"id":"d","text":"Hepatomegaly"}],"answerId":"a","explanation":"Caput medusae is a sign of portal hypertension due to recanalized paraumbilical veins.","kind":"recall","origin":"ai"},{"id":"liver-biliary-pancreas~ai-4","moduleId":"liver-biliary-pancreas","stem":"Which ligament is the remnant of the left umbilical vein?","options":[{"id":"a","text":"Ligamentum venosum"},{"id":"b","text":"Ligamentum teres"},{"id":"c","text":"Falciform ligament"},{"id":"d","text":"Coronary ligament"}],"answerId":"b","explanation":"The ligamentum teres is the remnant of the left umbilical vein, while the ligamentum venosum is from the ductus venosus.","kind":"trap","origin":"ai"},{"id":"liver-biliary-pancreas~ai-5","moduleId":"liver-biliary-pancreas","stem":"What is the consequence of a stone at the hepatopancreatic ampulla?","options":[{"id":"a","text":"Obstructive jaundice"},{"id":"b","text":"Cholecystitis"},{"id":"c","text":"Pancreatitis"},{"id":"d","text":"Hepatitis"}],"answerId":"a","explanation":"A stone at the ampulla can block bile and pancreatic secretions, leading to obstructive jaundice.","kind":"mechanism","origin":"ai"},{"id":"liver-biliary-pancreas~ai-6","moduleId":"liver-biliary-pancreas","stem":"How does the liver's blood supply relate to the GI system?","options":[{"id":"a","text":"It receives blood only from the hepatic artery."},{"id":"b","text":"It filters blood from the portal vein before systemic circulation."},{"id":"c","text":"It has no connection to the portal system."},{"id":"d","text":"It drains directly into the inferior vena cava."}],"answerId":"b","explanation":"The liver filters blood from the portal vein, which carries nutrient-rich blood from the GI tract.","kind":"integration","linkedModuleIds":["gi-blood-supply-portal-system"],"origin":"ai"},{"id":"liver-biliary-pancreas~ai-7","moduleId":"liver-biliary-pancreas","stem":"Which structure is involved in the drainage of bile from the liver to the duodenum?","options":[{"id":"a","text":"Cystic duct"},{"id":"b","text":"Common bile duct"},{"id":"c","text":"Hepatic artery"},{"id":"d","text":"Portal vein"}],"answerId":"b","explanation":"The common bile duct carries bile from the liver to the duodenum, joining with the pancreatic duct.","kind":"integration","linkedModuleIds":["liver-acinus-gallbladder"],"origin":"ai"}],"bladder-urethra":[{"id":"bladder-urethra~ai-0","moduleId":"bladder-urethra","stem":"What is the primary muscle responsible for bladder contraction during micturition?","options":[{"id":"a","text":"Detrusor muscle"},{"id":"b","text":"Internal sphincter"},{"id":"c","text":"External sphincter"},{"id":"d","text":"Trigone muscle"}],"answerId":"a","explanation":"The detrusor muscle contracts to facilitate bladder emptying during micturition.","kind":"recall","origin":"ai"},{"id":"bladder-urethra~ai-1","moduleId":"bladder-urethra","stem":"Which nerve roots are primarily involved in the parasympathetic control of the bladder?","options":[{"id":"a","text":"T11–L2"},{"id":"b","text":"S2–S4"},{"id":"c","text":"L1–L3"},{"id":"d","text":"C1–C3"}],"answerId":"b","explanation":"The pelvic splanchnic nerves from S2 to S4 are responsible for parasympathetic control of bladder contraction.","kind":"recall","origin":"ai"},{"id":"bladder-urethra~ai-2","moduleId":"bladder-urethra","stem":"A 25-year-old woman presents with recurrent urinary tract infections. What anatomical feature predisposes her to this condition?","options":[{"id":"a","text":"Long urethra"},{"id":"b","text":"Short urethra"},{"id":"c","text":"Internal urethral sphincter"},{"id":"d","text":"Trigone muscle"}],"answerId":"b","explanation":"The short female urethra increases susceptibility to urinary tract infections.","kind":"clinical","origin":"ai"},{"id":"bladder-urethra~ai-3","moduleId":"bladder-urethra","stem":"What is the mechanism of action for the sympathetic nervous system in bladder function?","options":[{"id":"a","text":"Contracts the detrusor muscle"},{"id":"b","text":"Relaxes the detrusor muscle"},{"id":"c","text":"Contracts the internal sphincter"},{"id":"d","text":"Stimulates voiding reflex"}],"answerId":"b","explanation":"Sympathetic stimulation relaxes the detrusor muscle, promoting bladder storage.","kind":"mechanism","origin":"ai"},{"id":"bladder-urethra~ai-4","moduleId":"bladder-urethra","stem":"A patient with a pelvic fracture presents with urinary retention and a high-riding prostate. What is the likely diagnosis?","options":[{"id":"a","text":"Bladder rupture"},{"id":"b","text":"Membranous urethral rupture"},{"id":"c","text":"Prostatic hypertrophy"},{"id":"d","text":"Spinal cord injury"}],"answerId":"b","explanation":"Urinary retention and a high-riding prostate suggest a membranous urethral rupture due to pelvic fracture.","kind":"clinical","origin":"ai"},{"id":"bladder-urethra~ai-5","moduleId":"bladder-urethra","stem":"Which part of the male urethra is the narrowest and most easily injured?","options":[{"id":"a","text":"Preprostatic"},{"id":"b","text":"Prostatic"},{"id":"c","text":"Membranous"},{"id":"d","text":"Spongy"}],"answerId":"c","explanation":"The membranous urethra is the narrowest and most susceptible to injury, especially in pelvic fractures.","kind":"recall","origin":"ai"},{"id":"bladder-urethra~ai-6","moduleId":"bladder-urethra","stem":"How does the detrusor muscle respond during the micturition reflex?","options":[{"id":"a","text":"Contracts to void urine"},{"id":"b","text":"Relaxes to store urine"},{"id":"c","text":"Increases tone to prevent leakage"},{"id":"d","text":"Inhibits internal sphincter contraction"}],"answerId":"a","explanation":"During micturition, the detrusor muscle contracts to facilitate the voiding of urine.","kind":"mechanism","origin":"ai"},{"id":"bladder-urethra~ai-7","moduleId":"bladder-urethra","stem":"In a patient with neurogenic bladder, which nerve dysfunction is most likely affecting bladder control?","options":[{"id":"a","text":"Pelvic splanchnics (S2–S4)"},{"id":"b","text":"Lumbar splanchnics (L1–L3)"},{"id":"c","text":"Vagus nerve"},{"id":"d","text":"Thoracic splanchnics (T5–T12)"}],"answerId":"a","explanation":"Neurogenic bladder often results from dysfunction of the pelvic splanchnics which control bladder contraction.","kind":"integration","linkedModuleIds":["neurogenic-bladder-disorders"],"origin":"ai"},{"id":"bladder-urethra~ai-8","moduleId":"bladder-urethra","stem":"Which drug class is commonly used to manage urge incontinence by affecting bladder detrusor activity?","options":[{"id":"a","text":"Anticholinergics"},{"id":"b","text":"Alpha-agonists"},{"id":"c","text":"Beta-blockers"},{"id":"d","text":"Diuretics"}],"answerId":"a","explanation":"Anticholinergics are used to reduce detrusor overactivity in urge incontinence.","kind":"integration","linkedModuleIds":["urinary-incontinence-drugs"],"origin":"ai"}],"palate-tongue":[{"id":"palate-tongue~ai-0","moduleId":"palate-tongue","stem":"Which cranial nerve is responsible for the motor function of all tongue muscles except for the palatoglossus?","options":[{"id":"a","text":"CN V3"},{"id":"b","text":"CN VII"},{"id":"c","text":"CN IX"},{"id":"d","text":"CN XII"}],"answerId":"d","explanation":"The hypoglossal nerve (CN XII) innervates all tongue muscles except for the palatoglossus, which is innervated by CN X.","kind":"recall","origin":"ai"},{"id":"palate-tongue~ai-1","moduleId":"palate-tongue","stem":"A patient presents with a protruded tongue deviating to the left side. Which cranial nerve is likely affected?","options":[{"id":"a","text":"CN V3"},{"id":"b","text":"CN VII"},{"id":"c","text":"CN IX"},{"id":"d","text":"CN XII"}],"answerId":"d","explanation":"A left deviation of the tongue indicates a left hypoglossal nerve (CN XII) lesion, as the intact genioglossus on the right side pushes the tongue toward the weak side.","kind":"clinical","origin":"ai"},{"id":"palate-tongue~ai-2","moduleId":"palate-tongue","stem":"What is the sensory nerve responsible for taste in the anterior two-thirds of the tongue?","options":[{"id":"a","text":"Lingual nerve (V3)"},{"id":"b","text":"Chorda tympani (CN VII)"},{"id":"c","text":"Glossopharyngeal nerve (CN IX)"},{"id":"d","text":"Vagus nerve (CN X)"}],"answerId":"b","explanation":"Taste sensation in the anterior two-thirds of the tongue is provided by the chorda tympani branch of CN VII.","kind":"recall","origin":"ai"},{"id":"palate-tongue~ai-3","moduleId":"palate-tongue","stem":"During a neurological exam, a patient’s uvula deviates to the right when saying 'ahh'. Which cranial nerve is likely affected?","options":[{"id":"a","text":"CN V3"},{"id":"b","text":"CN VII"},{"id":"c","text":"CN IX"},{"id":"d","text":"CN X"}],"answerId":"d","explanation":"Uvula deviation away from the side of the lesion indicates weakness of the levator veli palatini, innervated by CN X.","kind":"clinical","origin":"ai"},{"id":"palate-tongue~ai-4","moduleId":"palate-tongue","stem":"Which muscle of the soft palate is NOT innervated by the vagus nerve?","options":[{"id":"a","text":"Levator veli palatini"},{"id":"b","text":"Tensor veli palatini"},{"id":"c","text":"Palatoglossus"},{"id":"d","text":"Musculus uvulae"}],"answerId":"b","explanation":"The tensor veli palatini is innervated by the mandibular branch of the trigeminal nerve (CN V3), while the others are innervated by CN X.","kind":"recall","origin":"ai"},{"id":"palate-tongue~ai-5","moduleId":"palate-tongue","stem":"A patient with a lesion affecting the chorda tympani presents with loss of taste in which area of the tongue?","options":[{"id":"a","text":"Anterior 1/3"},{"id":"b","text":"Posterior 1/3"},{"id":"c","text":"Vallecula"},{"id":"d","text":"Epiglottis"}],"answerId":"a","explanation":"The chorda tympani provides taste sensation to the anterior two-thirds of the tongue; its lesion results in loss of taste in this area.","kind":"clinical","origin":"ai"},{"id":"palate-tongue~ai-6","moduleId":"palate-tongue","stem":"How does a lesion in the hypoglossal nerve affect the tongue's position during protrusion?","options":[{"id":"a","text":"Deviates away from the lesion"},{"id":"b","text":"Deviates toward the lesion"},{"id":"c","text":"Remains midline"},{"id":"d","text":"Retracts"}],"answerId":"b","explanation":"A hypoglossal nerve lesion causes the tongue to deviate toward the affected side due to unopposed action of the intact genioglossus muscle.","kind":"trap","origin":"ai"},{"id":"palate-tongue~ai-7","moduleId":"palate-tongue","stem":"A patient with a sore throat has difficulty swallowing and a uvula that deviates to the left. Which cranial nerve is likely affected?","options":[{"id":"a","text":"CN V3"},{"id":"b","text":"CN VII"},{"id":"c","text":"CN IX"},{"id":"d","text":"CN X"}],"answerId":"d","explanation":"Uvula deviation to the left suggests a left-sided vagus nerve (CN X) lesion, affecting the muscles of the soft palate.","kind":"clinical","origin":"ai"},{"id":"palate-tongue~ai-8","moduleId":"palate-tongue","stem":"How does the sensory innervation of the tongue relate to oral cavity structures in terms of taste?","options":[{"id":"a","text":"Both anterior and posterior tongue innervated by CN VII"},{"id":"b","text":"Anterior tongue by CN V3, posterior by CN IX"},{"id":"c","text":"Anterior tongue by CN IX, posterior by CN X"},{"id":"d","text":"Only posterior tongue has taste sensation"}],"answerId":"b","explanation":"The anterior two-thirds of the tongue receives general sensation from the lingual nerve (V3) and taste from the chorda tympani (CN VII), while the posterior one-third receives both from CN IX.","kind":"integration","linkedModuleIds":["oral-mucosa-tongue-taste"],"origin":"ai"}],"history-germ-theory-modern-medicine":[{"id":"history-germ-theory-modern-medicine~ai-0","moduleId":"history-germ-theory-modern-medicine","stem":"Who is credited with developing the first vaccine?","options":[{"id":"a","text":"Louis Pasteur"},{"id":"b","text":"Joseph Lister"},{"id":"c","text":"Edward Jenner"},{"id":"d","text":"Alexander Fleming"}],"answerId":"c","explanation":"Edward Jenner developed the first vaccine for smallpox using cowpox in 1796.","kind":"recall","origin":"ai"},{"id":"history-germ-theory-modern-medicine~ai-1","moduleId":"history-germ-theory-modern-medicine","stem":"What is the primary mechanism by which penicillin acts?","options":[{"id":"a","text":"Inhibits protein synthesis"},{"id":"b","text":"Disrupts cell wall synthesis"},{"id":"c","text":"Inhibits nucleic acid synthesis"},{"id":"d","text":"Inhibits metabolic pathways"}],"answerId":"b","explanation":"Penicillin disrupts bacterial cell wall synthesis, leading to cell lysis.","kind":"mechanism","origin":"ai"},{"id":"history-germ-theory-modern-medicine~ai-2","moduleId":"history-germ-theory-modern-medicine","stem":"Which of the following findings supports Koch's postulates?","options":[{"id":"a","text":"Presence of cowpox protects against smallpox"},{"id":"b","text":"Carbolic acid reduces surgical mortality"},{"id":"c","text":"Streptococcus pneumoniae causes pneumonia"},{"id":"d","text":"Penicillium lyses staphylococci"}],"answerId":"c","explanation":"Koch's postulates are used to establish a causal relationship between a microbe and a disease, exemplified by Streptococcus pneumoniae and pneumonia.","kind":"recall","origin":"ai"},{"id":"history-germ-theory-modern-medicine~ai-3","moduleId":"history-germ-theory-modern-medicine","stem":"What was a significant outcome of Joseph Lister's application of germ theory?","options":[{"id":"a","text":"Discovery of penicillin"},{"id":"b","text":"Reduction in surgical mortality"},{"id":"c","text":"Development of the smallpox vaccine"},{"id":"d","text":"Proving the germ theory of disease"}],"answerId":"b","explanation":"Joseph Lister's use of carbolic acid in surgery significantly reduced surgical mortality by applying germ theory.","kind":"clinical","origin":"ai"},{"id":"history-germ-theory-modern-medicine~ai-4","moduleId":"history-germ-theory-modern-medicine","stem":"Which statement correctly differentiates between antibiotics and vaccines?","options":[{"id":"a","text":"Vaccines treat infections, antibiotics prevent them"},{"id":"b","text":"Antibiotics are used for viral infections, vaccines for bacterial"},{"id":"c","text":"Vaccines provide immunity, antibiotics kill bacteria"},{"id":"d","text":"Antibiotics are preventive, vaccines are therapeutic"}],"answerId":"c","explanation":"Vaccines provide immunity against diseases, while antibiotics kill or inhibit the growth of bacteria.","kind":"trap","origin":"ai"},{"id":"history-germ-theory-modern-medicine~ai-5","moduleId":"history-germ-theory-modern-medicine","stem":"How did the introduction of the randomized controlled trial (RCT) impact medical practice?","options":[{"id":"a","text":"It established the first vaccine"},{"id":"b","text":"It replaced anecdotal evidence with scientific evidence"},{"id":"c","text":"It led to the discovery of antibiotics"},{"id":"d","text":"It proved the germ theory of disease"}],"answerId":"b","explanation":"The RCT provided a systematic method to evaluate the efficacy of treatments, thus replacing anecdotal evidence with scientific evidence.","kind":"integration","linkedModuleIds":["vaccines-immunization"],"origin":"ai"},{"id":"history-germ-theory-modern-medicine~ai-6","moduleId":"history-germ-theory-modern-medicine","stem":"Which concept connects the germ theory of disease to modern immunization practices?","options":[{"id":"a","text":"Evidence-based medicine"},{"id":"b","text":"Koch's postulates"},{"id":"c","text":"Antisepsis"},{"id":"d","text":"Randomized controlled trials"}],"answerId":"b","explanation":"Koch's postulates provide a framework for establishing the causative relationship between microbes and diseases, which is foundational for developing vaccines.","kind":"integration","linkedModuleIds":["immunostimulants-biologics"],"origin":"ai"}],"research-question-finer-pico":[{"id":"research-question-finer-pico~ai-0","moduleId":"research-question-finer-pico","stem":"Which of the following best describes the purpose of the FINER criteria in research question formulation?","options":[{"id":"a","text":"To structure the components of a question"},{"id":"b","text":"To evaluate the feasibility and relevance of a question"},{"id":"c","text":"To define the measurable outcomes of a study"},{"id":"d","text":"To identify the population for a study"}],"answerId":"b","explanation":"FINER criteria assess whether a research question is worth pursuing based on feasibility, interest, novelty, ethics, and relevance.","kind":"recall","origin":"ai"},{"id":"research-question-finer-pico~ai-1","moduleId":"research-question-finer-pico","stem":"In the PICO(T) framework, which component refers to the measurable effect of an intervention?","options":[{"id":"a","text":"Population"},{"id":"b","text":"Intervention"},{"id":"c","text":"Comparison"},{"id":"d","text":"Outcome"}],"answerId":"d","explanation":"The 'Outcome' component in PICO(T) specifies the measurable effect or result of the intervention being studied.","kind":"recall","origin":"ai"},{"id":"research-question-finer-pico~ai-2","moduleId":"research-question-finer-pico","stem":"What type of research question is characterized by the absence of a comparison group?","options":[{"id":"a","text":"Comparative"},{"id":"b","text":"Descriptive"},{"id":"c","text":"Causal"},{"id":"d","text":"Relational"}],"answerId":"b","explanation":"Descriptive questions do not involve comparisons and typically focus on prevalence or incidence.","kind":"mechanism","origin":"ai"},{"id":"research-question-finer-pico~ai-3","moduleId":"research-question-finer-pico","stem":"Which of the following is a trap when distinguishing between FINER and PICO?","options":[{"id":"a","text":"FINER assesses question quality, while PICO structures it"},{"id":"b","text":"PICO is only for qualitative questions"},{"id":"c","text":"FINER is only applicable to clinical questions"},{"id":"d","text":"PICO does not consider ethical implications"}],"answerId":"a","explanation":"FINER evaluates the worth of a question, while PICO provides a framework for structuring the question's components.","kind":"trap","origin":"ai"},{"id":"research-question-finer-pico~ai-4","moduleId":"research-question-finer-pico","stem":"In a study examining the effect of a new drug on blood pressure in hypertensive patients, which PICO component does 'hypertensive patients' represent?","options":[{"id":"a","text":"Population"},{"id":"b","text":"Intervention"},{"id":"c","text":"Comparison"},{"id":"d","text":"Outcome"}],"answerId":"a","explanation":"In this context, 'hypertensive patients' is the population being studied.","kind":"clinical","origin":"ai"},{"id":"research-question-finer-pico~ai-5","moduleId":"research-question-finer-pico","stem":"How does the PICO framework enhance the research question regarding sodium disorders?","options":[{"id":"a","text":"It ensures ethical considerations are met"},{"id":"b","text":"It structures the question to include specific measurable outcomes"},{"id":"c","text":"It focuses only on the population aspect"},{"id":"d","text":"It eliminates the need for a control group"}],"answerId":"b","explanation":"PICO structures the question to ensure it includes specific measurable outcomes, which is crucial in studies on sodium disorders.","kind":"integration","linkedModuleIds":["sodium-water-disorders"],"origin":"ai"},{"id":"research-question-finer-pico~ai-6","moduleId":"research-question-finer-pico","stem":"Which of the following best illustrates the transition from a research problem to a research question in the context of sodium disorders?","options":[{"id":"a","text":"How common is hypernatremia in the elderly?"},{"id":"b","text":"Does sodium restriction improve outcomes in heart failure patients?"},{"id":"c","text":"What are the causes of hyponatremia?"},{"id":"d","text":"Is there a relationship between sodium intake and blood pressure?"}],"answerId":"b","explanation":"The question 'Does sodium restriction improve outcomes in heart failure patients?' is specific, measurable, and structured, making it a well-defined research question.","kind":"integration","linkedModuleIds":["hypothesis-objectives"],"origin":"ai"}],"history-ancient-to-renaissance":[{"id":"history-ancient-to-renaissance~ai-0","moduleId":"history-ancient-to-renaissance","stem":"Who is known as the 'Father of Medicine' for emphasizing natural causes of disease?","options":[{"id":"a","text":"Galen"},{"id":"b","text":"Hippocrates"},{"id":"c","text":"Andreas Vesalius"},{"id":"d","text":"William Harvey"}],"answerId":"b","explanation":"Hippocrates is recognized for shifting the focus from supernatural to natural explanations for disease.","kind":"recall","origin":"ai"},{"id":"history-ancient-to-renaissance~ai-1","moduleId":"history-ancient-to-renaissance","stem":"What is the primary mechanism of disease according to Hippocratic humoral theory?","options":[{"id":"a","text":"Infection by pathogens"},{"id":"b","text":"Imbalance of humors"},{"id":"c","text":"Genetic predisposition"},{"id":"d","text":"Environmental factors"}],"answerId":"b","explanation":"Hippocratic humoral theory posits that health is maintained by the balance of four humors.","kind":"mechanism","origin":"ai"},{"id":"history-ancient-to-renaissance~ai-2","moduleId":"history-ancient-to-renaissance","stem":"Which of the following was a significant contribution of Andreas Vesalius?","options":[{"id":"a","text":"Developed the first vaccine"},{"id":"b","text":"Dissected humans to correct Galen's errors"},{"id":"c","text":"Introduced antisepsis"},{"id":"d","text":"Formulated germ theory"}],"answerId":"b","explanation":"Vesalius is credited with founding modern anatomy by conducting human dissections.","kind":"recall","origin":"ai"},{"id":"history-ancient-to-renaissance~ai-3","moduleId":"history-ancient-to-renaissance","stem":"What was the main flaw in Galen's medical teachings?","options":[{"id":"a","text":"He relied on animal dissection"},{"id":"b","text":"He promoted bloodletting"},{"id":"c","text":"He ignored patient observation"},{"id":"d","text":"He used supernatural explanations"}],"answerId":"a","explanation":"Galen's reliance on animal dissection led to many inaccuracies in his anatomical knowledge.","kind":"trap","origin":"ai"},{"id":"history-ancient-to-renaissance~ai-4","moduleId":"history-ancient-to-renaissance","stem":"Which of the following statements about the Hippocratic Oath is true?","options":[{"id":"a","text":"It was the first medical text"},{"id":"b","text":"It emphasizes doing no harm"},{"id":"c","text":"It promotes bloodletting"},{"id":"d","text":"It was written by Galen"}],"answerId":"b","explanation":"The Hippocratic Oath is the first codified set of medical ethics emphasizing the principle of 'do no harm'.","kind":"recall","origin":"ai"},{"id":"history-ancient-to-renaissance~ai-5","moduleId":"history-ancient-to-renaissance","stem":"How did the Renaissance contribute to modern medicine compared to earlier practices?","options":[{"id":"a","text":"Emphasized magical remedies"},{"id":"b","text":"Focused on animal dissection"},{"id":"c","text":"Restored direct human observation"},{"id":"d","text":"Promoted Galenic theories"}],"answerId":"c","explanation":"The Renaissance marked a return to direct observation of human anatomy, correcting previous errors.","kind":"mechanism","origin":"ai"},{"id":"history-ancient-to-renaissance~ai-6","moduleId":"history-ancient-to-renaissance","stem":"How does the concept of natural causes of disease in ancient medicine relate to germ theory?","options":[{"id":"a","text":"Both focus on supernatural explanations"},{"id":"b","text":"Both emphasize observation and evidence"},{"id":"c","text":"Both reject the idea of balance"},{"id":"d","text":"Both were developed in the same era"}],"answerId":"b","explanation":"Both ancient medicine's natural causes and germ theory emphasize observation and evidence in understanding disease.","kind":"integration","linkedModuleIds":["history-germ-theory-modern-medicine"],"origin":"ai"},{"id":"history-ancient-to-renaissance~ai-7","moduleId":"history-ancient-to-renaissance","stem":"Which development in the Renaissance laid the groundwork for modern experimental methods in medicine?","options":[{"id":"a","text":"Hippocratic Oath"},{"id":"b","text":"Bloodletting"},{"id":"c","text":"Human dissection by Vesalius"},{"id":"d","text":"Animal dissection by Galen"}],"answerId":"c","explanation":"Vesalius's human dissections corrected many of Galen's errors and laid the foundation for modern experimental methods.","kind":"integration","linkedModuleIds":["history-germ-theory-modern-medicine"],"origin":"ai"}],"leg-compartments":[{"id":"leg-compartments~ai-0","moduleId":"leg-compartments","stem":"Which nerve is responsible for innervating the dorsiflexors of the foot?","options":[{"id":"a","text":"Tibial nerve"},{"id":"b","text":"Superficial fibular nerve"},{"id":"c","text":"Deep fibular nerve"},{"id":"d","text":"Femoral nerve"}],"answerId":"c","explanation":"The deep fibular nerve innervates the dorsiflexors, including the tibialis anterior.","kind":"recall","origin":"ai"},{"id":"leg-compartments~ai-1","moduleId":"leg-compartments","stem":"What is the earliest sign of acute compartment syndrome?","options":[{"id":"a","text":"Paresthesia"},{"id":"b","text":"Pulselessness"},{"id":"c","text":"Severe pain out of proportion"},{"id":"d","text":"Paralysis"}],"answerId":"c","explanation":"Severe pain out of proportion is the earliest sign of compartment syndrome, while pulselessness is a late sign.","kind":"trap","origin":"ai"},{"id":"leg-compartments~ai-2","moduleId":"leg-compartments","stem":"A patient presents with foot drop and a high-stepping gait after a fibular neck injury. Which nerve is likely affected?","options":[{"id":"a","text":"Tibial nerve"},{"id":"b","text":"Deep fibular nerve"},{"id":"c","text":"Superficial fibular nerve"},{"id":"d","text":"Common fibular nerve"}],"answerId":"d","explanation":"The common fibular nerve is affected in foot drop due to its location near the fibular neck.","kind":"clinical","origin":"ai"},{"id":"leg-compartments~ai-3","moduleId":"leg-compartments","stem":"Which muscle is primarily responsible for eversion of the foot?","options":[{"id":"a","text":"Tibialis anterior"},{"id":"b","text":"Fibularis longus"},{"id":"c","text":"Gastrocnemius"},{"id":"d","text":"Flexor hallucis longus"}],"answerId":"b","explanation":"The fibularis longus is primarily responsible for eversion of the foot.","kind":"recall","origin":"ai"},{"id":"leg-compartments~ai-4","moduleId":"leg-compartments","stem":"In acute compartment syndrome, which of the following findings would be expected?","options":[{"id":"a","text":"Increased distal pulse"},{"id":"b","text":"Severe pain on passive stretch"},{"id":"c","text":"Numbness in the first web space"},{"id":"d","text":"Weak plantarflexion"}],"answerId":"b","explanation":"Severe pain on passive stretch is a classic finding in acute compartment syndrome.","kind":"recall","origin":"ai"},{"id":"leg-compartments~ai-5","moduleId":"leg-compartments","stem":"How does the anatomy of the leg compartments relate to the development of pediatric tumors such as medulloblastoma?","options":[{"id":"a","text":"Tumors arise from muscle compartments"},{"id":"b","text":"Tumors affect nerve supply"},{"id":"c","text":"Compartment syndrome can mimic tumor symptoms"},{"id":"d","text":"Tumors can cause compartment syndrome"}],"answerId":"c","explanation":"Compartment syndrome can mimic symptoms of tumors, highlighting the importance of differential diagnosis.","kind":"integration","linkedModuleIds":["pediatric-embryonal-tumors"],"origin":"ai"},{"id":"leg-compartments~ai-6","moduleId":"leg-compartments","stem":"Which artery supplies the anterior compartment of the leg?","options":[{"id":"a","text":"Posterior tibial artery"},{"id":"b","text":"Anterior tibial artery"},{"id":"c","text":"Fibular artery"},{"id":"d","text":"Popliteal artery"}],"answerId":"b","explanation":"The anterior tibial artery supplies the anterior compartment of the leg.","kind":"recall","origin":"ai"},{"id":"leg-compartments~ai-7","moduleId":"leg-compartments","stem":"What is the primary action of the muscles in the posterior compartment of the leg?","options":[{"id":"a","text":"Dorsiflexion"},{"id":"b","text":"Eversion"},{"id":"c","text":"Plantarflexion"},{"id":"d","text":"Inversion"}],"answerId":"c","explanation":"The primary action of the muscles in the posterior compartment is plantarflexion.","kind":"recall","origin":"ai"},{"id":"leg-compartments~ai-8","moduleId":"leg-compartments","stem":"Which structure is most commonly affected in acute compartment syndrome?","options":[{"id":"a","text":"Lateral compartment"},{"id":"b","text":"Deep posterior compartment"},{"id":"c","text":"Anterior compartment"},{"id":"d","text":"Superficial posterior compartment"}],"answerId":"c","explanation":"The anterior compartment is most commonly affected in acute compartment syndrome due to its anatomical location.","kind":"recall","origin":"ai"}],"posterior-thigh-sciatic":[{"id":"posterior-thigh-sciatic~ai-0","moduleId":"posterior-thigh-sciatic","stem":"Which muscle is NOT part of the hamstrings?","options":[{"id":"a","text":"Semitendinosus"},{"id":"b","text":"Semimembranosus"},{"id":"c","text":"Short head of biceps femoris"},{"id":"d","text":"Long head of biceps femoris"}],"answerId":"c","explanation":"The short head of biceps femoris is not considered part of the hamstrings as it does not arise from the ischial tuberosity.","kind":"recall","origin":"ai"},{"id":"posterior-thigh-sciatic~ai-1","moduleId":"posterior-thigh-sciatic","stem":"What is the primary function of the hamstrings during locomotion?","options":[{"id":"a","text":"Knee extension"},{"id":"b","text":"Hip flexion"},{"id":"c","text":"Knee flexion and hip extension"},{"id":"d","text":"Ankle dorsiflexion"}],"answerId":"c","explanation":"The hamstrings primarily function to flex the knee and extend the hip during locomotion.","kind":"recall","origin":"ai"},{"id":"posterior-thigh-sciatic~ai-2","moduleId":"posterior-thigh-sciatic","stem":"A patient presents with foot drop after a fibular neck injury. Which nerve is most likely affected?","options":[{"id":"a","text":"Tibial nerve"},{"id":"b","text":"Common fibular nerve"},{"id":"c","text":"Femoral nerve"},{"id":"d","text":"Obturator nerve"}],"answerId":"b","explanation":"The common fibular nerve is commonly injured at the fibular neck, leading to foot drop.","kind":"clinical","origin":"ai"},{"id":"posterior-thigh-sciatic~ai-3","moduleId":"posterior-thigh-sciatic","stem":"Which of the following findings is characteristic of a complete sciatic nerve injury?","options":[{"id":"a","text":"Foot drop"},{"id":"b","text":"Weak knee flexion"},{"id":"c","text":"Sensory loss over the medial leg"},{"id":"d","text":"Inability to extend the hip"}],"answerId":"b","explanation":"A complete sciatic nerve injury results in weak knee flexion and sensory loss below the knee, but spares the medial leg.","kind":"recall","origin":"ai"},{"id":"posterior-thigh-sciatic~ai-4","moduleId":"posterior-thigh-sciatic","stem":"What is the mechanism of injury in a hamstring strain?","options":[{"id":"a","text":"Direct blow to the knee"},{"id":"b","text":"Overstretching during sprinting"},{"id":"c","text":"Compression at the popliteal fossa"},{"id":"d","text":"Fracture of the fibula"}],"answerId":"b","explanation":"Hamstring strains often occur due to overstretching during activities like sprinting.","kind":"mechanism","origin":"ai"},{"id":"posterior-thigh-sciatic~ai-5","moduleId":"posterior-thigh-sciatic","stem":"Which division of the sciatic nerve is more commonly injured?","options":[{"id":"a","text":"Tibial division"},{"id":"b","text":"Common fibular division"},{"id":"c","text":"Both equally"},{"id":"d","text":"Neither"}],"answerId":"b","explanation":"The common fibular division is more commonly injured due to its superficial position at the neck of the fibula.","kind":"trap","origin":"ai"},{"id":"posterior-thigh-sciatic~ai-6","moduleId":"posterior-thigh-sciatic","stem":"How does a complete sciatic nerve lesion affect the lower limb?","options":[{"id":"a","text":"Only sensory loss"},{"id":"b","text":"Weakness in hip abduction"},{"id":"c","text":"Paralysis of hamstrings and all muscles below the knee"},{"id":"d","text":"Foot drop only"}],"answerId":"c","explanation":"A complete sciatic nerve lesion results in paralysis of the hamstrings and all muscles below the knee, leading to significant functional impairment.","kind":"integration","linkedModuleIds":["popliteal-fossa"],"origin":"ai"},{"id":"posterior-thigh-sciatic~ai-7","moduleId":"posterior-thigh-sciatic","stem":"Which of the following nerves is most likely to be injured in a tight cast around the knee?","options":[{"id":"a","text":"Tibial nerve"},{"id":"b","text":"Common fibular nerve"},{"id":"c","text":"Femoral nerve"},{"id":"d","text":"Saphenous nerve"}],"answerId":"b","explanation":"The common fibular nerve is vulnerable to injury due to its superficial location, especially in cases of compression from a tight cast.","kind":"integration","linkedModuleIds":["gluteal-region-nerves"],"origin":"ai"}],"gluteal-region-nerves":[{"id":"gluteal-region-nerves~ai-0","moduleId":"gluteal-region-nerves","stem":"Which nerve primarily innervates the gluteus maximus muscle?","options":[{"id":"a","text":"Inferior gluteal nerve"},{"id":"b","text":"Superior gluteal nerve"},{"id":"c","text":"Femoral nerve"},{"id":"d","text":"Obturator nerve"}],"answerId":"a","explanation":"The gluteus maximus is primarily innervated by the inferior gluteal nerve.","kind":"recall","origin":"ai"},{"id":"gluteal-region-nerves~ai-1","moduleId":"gluteal-region-nerves","stem":"What is the primary action of the gluteus medius muscle?","options":[{"id":"a","text":"Hip extension"},{"id":"b","text":"Hip abduction"},{"id":"c","text":"Hip adduction"},{"id":"d","text":"Hip flexion"}],"answerId":"b","explanation":"The gluteus medius is primarily responsible for hip abduction.","kind":"recall","origin":"ai"},{"id":"gluteal-region-nerves~ai-2","moduleId":"gluteal-region-nerves","stem":"A patient presents with a positive Trendelenburg sign. Which nerve is most likely injured?","options":[{"id":"a","text":"Inferior gluteal nerve"},{"id":"b","text":"Superior gluteal nerve"},{"id":"c","text":"Sciatic nerve"},{"id":"d","text":"Pudendal nerve"}],"answerId":"b","explanation":"A positive Trendelenburg sign indicates weakness of the hip abductors, which are innervated by the superior gluteal nerve.","kind":"clinical","origin":"ai"},{"id":"gluteal-region-nerves~ai-3","moduleId":"gluteal-region-nerves","stem":"Which structure exits the greater sciatic foramen above the piriformis muscle?","options":[{"id":"a","text":"Sciatic nerve"},{"id":"b","text":"Inferior gluteal nerve"},{"id":"c","text":"Superior gluteal nerve"},{"id":"d","text":"Pudendal nerve"}],"answerId":"c","explanation":"The superior gluteal nerve exits above the piriformis muscle.","kind":"recall","origin":"ai"},{"id":"gluteal-region-nerves~ai-4","moduleId":"gluteal-region-nerves","stem":"In a positive Trendelenburg sign, which side does the pelvis drop?","options":[{"id":"a","text":"Affected side"},{"id":"b","text":"Opposite side"},{"id":"c","text":"Both sides"},{"id":"d","text":"Neither side"}],"answerId":"b","explanation":"In a positive Trendelenburg sign, the pelvis drops on the opposite side due to weakness of the abductors on the affected side.","kind":"trap","origin":"ai"},{"id":"gluteal-region-nerves~ai-5","moduleId":"gluteal-region-nerves","stem":"A patient experiences weakness in hip abduction and a waddling gait. Which condition is most likely?","options":[{"id":"a","text":"Superior gluteal nerve injury"},{"id":"b","text":"Inferior gluteal nerve injury"},{"id":"c","text":"Sciatic nerve injury"},{"id":"d","text":"Pudendal nerve injury"}],"answerId":"a","explanation":"Weakness in hip abduction and a waddling gait are indicative of superior gluteal nerve injury.","kind":"clinical","origin":"ai"},{"id":"gluteal-region-nerves~ai-6","moduleId":"gluteal-region-nerves","stem":"How does a poorly placed gluteal injection lead to sciatic nerve injury?","options":[{"id":"a","text":"Injection into the superolateral quadrant"},{"id":"b","text":"Injection into the superomedial quadrant"},{"id":"c","text":"Injection into the inferior quadrant"},{"id":"d","text":"Injection into the lateral thigh"}],"answerId":"b","explanation":"Injecting into the superomedial quadrant risks injuring the sciatic nerve, which lies in the lower medial region.","kind":"mechanism","origin":"ai"},{"id":"gluteal-region-nerves~ai-7","moduleId":"gluteal-region-nerves","stem":"How do the gluteal muscles contribute to maintaining pelvic stability during walking?","options":[{"id":"a","text":"By flexing the hip"},{"id":"b","text":"By extending the knee"},{"id":"c","text":"By abducting the hip"},{"id":"d","text":"By rotating the hip"}],"answerId":"c","explanation":"The gluteal muscles, particularly the abductors, help maintain pelvic stability by abducting the hip.","kind":"integration","linkedModuleIds":["posterior-thigh-sciatic"],"origin":"ai"},{"id":"gluteal-region-nerves~ai-8","moduleId":"gluteal-region-nerves","stem":"Which nerve injury could lead to both hip abductor weakness and posterior thigh muscle weakness?","options":[{"id":"a","text":"Inferior gluteal nerve"},{"id":"b","text":"Superior gluteal nerve"},{"id":"c","text":"Sciatic nerve"},{"id":"d","text":"Femoral nerve"}],"answerId":"c","explanation":"The sciatic nerve innervates the posterior thigh muscles and can also affect hip abductor function if injured.","kind":"integration","linkedModuleIds":["popliteal-fossa"],"origin":"ai"}],"femoral-triangle-anterior-thigh":[{"id":"femoral-triangle-anterior-thigh~ai-0","moduleId":"femoral-triangle-anterior-thigh","stem":"What are the boundaries of the femoral triangle?","options":[{"id":"a","text":"Sartorius, inguinal ligament, adductor longus"},{"id":"b","text":"Sartorius, adductor longus, iliopsoas"},{"id":"c","text":"Inguinal ligament, iliopsoas, quadriceps"},{"id":"d","text":"Adductor longus, quadriceps, inguinal ligament"}],"answerId":"a","explanation":"The femoral triangle is bounded by the inguinal ligament (superior), sartorius (lateral), and adductor longus (medial).","kind":"recall","origin":"ai"},{"id":"femoral-triangle-anterior-thigh~ai-1","moduleId":"femoral-triangle-anterior-thigh","stem":"Which structure is NOT contained within the femoral sheath?","options":[{"id":"a","text":"Femoral nerve"},{"id":"b","text":"Femoral artery"},{"id":"c","text":"Femoral vein"},{"id":"d","text":"Femoral canal"}],"answerId":"a","explanation":"The femoral nerve lies outside the femoral sheath, while the artery, vein, and canal are contained within it.","kind":"recall","origin":"ai"},{"id":"femoral-triangle-anterior-thigh~ai-2","moduleId":"femoral-triangle-anterior-thigh","stem":"A patient presents with a groin lump that is below and lateral to the pubic tubercle. What is the most likely diagnosis?","options":[{"id":"a","text":"Inguinal hernia"},{"id":"b","text":"Femoral hernia"},{"id":"c","text":"Lymphadenopathy"},{"id":"d","text":"Varicocele"}],"answerId":"b","explanation":"The described location is characteristic of a femoral hernia, which is more common in women and has a high risk of strangulation.","kind":"clinical","origin":"ai"},{"id":"femoral-triangle-anterior-thigh~ai-3","moduleId":"femoral-triangle-anterior-thigh","stem":"A 30-year-old woman presents with weakness in knee extension and an absent patellar reflex. Which nerve is likely affected?","options":[{"id":"a","text":"Obturator nerve"},{"id":"b","text":"Femoral nerve"},{"id":"c","text":"Sciatic nerve"},{"id":"d","text":"Tibial nerve"}],"answerId":"b","explanation":"Weakness in knee extension and an absent patellar reflex indicate a lesion of the femoral nerve, which innervates the quadriceps.","kind":"clinical","origin":"ai"},{"id":"femoral-triangle-anterior-thigh~ai-4","moduleId":"femoral-triangle-anterior-thigh","stem":"What is the primary action of the quadriceps femoris muscle?","options":[{"id":"a","text":"Hip flexion"},{"id":"b","text":"Knee extension"},{"id":"c","text":"Hip adduction"},{"id":"d","text":"Knee flexion"}],"answerId":"b","explanation":"The quadriceps femoris primarily functions to extend the knee.","kind":"recall","origin":"ai"},{"id":"femoral-triangle-anterior-thigh~ai-5","moduleId":"femoral-triangle-anterior-thigh","stem":"How does a femoral hernia differ from an inguinal hernia in terms of location?","options":[{"id":"a","text":"Both are above the pubic tubercle"},{"id":"b","text":"Femoral is above and medial, inguinal is below and lateral"},{"id":"c","text":"Femoral is below and lateral, inguinal is above and medial"},{"id":"d","text":"Both are below the pubic tubercle"}],"answerId":"c","explanation":"A femoral hernia is located below and lateral to the pubic tubercle, while an inguinal hernia is above and medial to it.","kind":"trap","origin":"ai"},{"id":"femoral-triangle-anterior-thigh~ai-6","moduleId":"femoral-triangle-anterior-thigh","stem":"Which structure passes through the adductor canal?","options":[{"id":"a","text":"Femoral nerve"},{"id":"b","text":"Saphenous nerve"},{"id":"c","text":"Femoral artery"},{"id":"d","text":"Obturator nerve"}],"answerId":"c","explanation":"The femoral artery passes through the adductor canal, along with the femoral vein and saphenous nerve.","kind":"recall","origin":"ai"},{"id":"femoral-triangle-anterior-thigh~ai-7","moduleId":"femoral-triangle-anterior-thigh","stem":"How does the femoral nerve's function relate to the hip joint mechanics?","options":[{"id":"a","text":"It innervates hip adductors"},{"id":"b","text":"It controls hip flexion"},{"id":"c","text":"It powers knee extension"},{"id":"d","text":"It stabilizes the hip joint"}],"answerId":"c","explanation":"The femoral nerve primarily innervates the quadriceps, which are responsible for knee extension, indirectly affecting hip mechanics during movement.","kind":"integration","linkedModuleIds":["lower-limb-bones-hip-joint"],"origin":"ai"},{"id":"femoral-triangle-anterior-thigh~ai-8","moduleId":"femoral-triangle-anterior-thigh","stem":"Which muscle group is primarily responsible for the action of flexing the hip joint?","options":[{"id":"a","text":"Quadriceps"},{"id":"b","text":"Adductors"},{"id":"c","text":"Iliopsoas"},{"id":"d","text":"Hamstrings"}],"answerId":"c","explanation":"The iliopsoas muscle group is primarily responsible for hip flexion.","kind":"integration","linkedModuleIds":["medial-thigh-adductors"],"origin":"ai"}],"ankle-foot-bones-arches":[{"id":"ankle-foot-bones-arches~ai-0","moduleId":"ankle-foot-bones-arches","stem":"Which of the following bones is NOT part of the tarsal group in the foot?","options":[{"id":"a","text":"Talus"},{"id":"b","text":"Calcaneus"},{"id":"c","text":"Cuneiform"},{"id":"d","text":"Metatarsal"}],"answerId":"d","explanation":"Metatarsals are part of the forefoot, while the tarsals include the talus, calcaneus, navicular, cuboid, and cuneiforms.","kind":"recall","origin":"ai"},{"id":"ankle-foot-bones-arches~ai-1","moduleId":"ankle-foot-bones-arches","stem":"What is the primary mechanism of injury for an ankle sprain involving the anterior talofibular ligament?","options":[{"id":"a","text":"Eversion"},{"id":"b","text":"Inversion"},{"id":"c","text":"Dorsiflexion"},{"id":"d","text":"Plantarflexion"}],"answerId":"b","explanation":"The anterior talofibular ligament is most commonly sprained during inversion injuries.","kind":"mechanism","origin":"ai"},{"id":"ankle-foot-bones-arches~ai-2","moduleId":"ankle-foot-bones-arches","stem":"A patient presents with lateral ankle swelling after rolling their ankle. Which ligament is most likely injured?","options":[{"id":"a","text":"Deltoid ligament"},{"id":"b","text":"Calcaneofibular ligament"},{"id":"c","text":"Anterior talofibular ligament"},{"id":"d","text":"Posterior talofibular ligament"}],"answerId":"c","explanation":"The anterior talofibular ligament is the most commonly injured ligament in inversion ankle sprains.","kind":"recall","origin":"ai"},{"id":"ankle-foot-bones-arches~ai-3","moduleId":"ankle-foot-bones-arches","stem":"Which condition is characterized by a collapsed medial longitudinal arch?","options":[{"id":"a","text":"Pes cavus"},{"id":"b","text":"Club foot"},{"id":"c","text":"Pes planus"},{"id":"d","text":"Hallux valgus"}],"answerId":"c","explanation":"Pes planus, or flat foot, is defined by the collapse of the medial longitudinal arch.","kind":"recall","origin":"ai"},{"id":"ankle-foot-bones-arches~ai-4","moduleId":"ankle-foot-bones-arches","stem":"In a patient with progressive flat foot, which sign indicates posterior tibial tendon dysfunction?","options":[{"id":"a","text":"Too many toes sign"},{"id":"b","text":"Hindfoot varus"},{"id":"c","text":"Forefoot adductus"},{"id":"d","text":"Cavus foot"}],"answerId":"a","explanation":"The 'too many toes' sign suggests posterior tibial tendon dysfunction leading to acquired pes planus.","kind":"recall","origin":"ai"},{"id":"ankle-foot-bones-arches~ai-5","moduleId":"ankle-foot-bones-arches","stem":"A patient with high-arched feet and peripheral neuropathy is most likely suffering from which condition?","options":[{"id":"a","text":"Pes planus"},{"id":"b","text":"Charcot-Marie-Tooth disease"},{"id":"c","text":"Hallux valgus"},{"id":"d","text":"Achilles tendonitis"}],"answerId":"b","explanation":"Charcot-Marie-Tooth disease often presents with high-arched feet (pes cavus) and is associated with peripheral neuropathy.","kind":"clinical","origin":"ai"},{"id":"ankle-foot-bones-arches~ai-6","moduleId":"ankle-foot-bones-arches","stem":"How do the arches of the foot contribute to weight distribution?","options":[{"id":"a","text":"They absorb shock"},{"id":"b","text":"They provide stability"},{"id":"c","text":"They distribute load"},{"id":"d","text":"They enhance mobility"}],"answerId":"c","explanation":"The arches of the foot distribute load across the foot, allowing for efficient weight bearing.","kind":"mechanism","origin":"ai"},{"id":"ankle-foot-bones-arches~ai-7","moduleId":"ankle-foot-bones-arches","stem":"Which structure supports the medial longitudinal arch of the foot?","options":[{"id":"a","text":"Plantar aponeurosis"},{"id":"b","text":"Achilles tendon"},{"id":"c","text":"Anterior talofibular ligament"},{"id":"d","text":"Fibularis longus tendon"}],"answerId":"a","explanation":"The plantar aponeurosis is one of the key structures that supports the medial longitudinal arch.","kind":"trap","origin":"ai"},{"id":"ankle-foot-bones-arches~ai-8","moduleId":"ankle-foot-bones-arches","stem":"How does the anatomy of the foot relate to the compartments of the leg?","options":[{"id":"a","text":"The foot has no relation to leg compartments"},{"id":"b","text":"Foot arches are supported by leg muscles"},{"id":"c","text":"Leg compartments contain foot bones"},{"id":"d","text":"Foot injuries are unrelated to leg anatomy"}],"answerId":"b","explanation":"The muscles in the leg compartments, such as the tibialis posterior, support the arches of the foot.","kind":"integration","linkedModuleIds":["leg-compartments"],"origin":"ai"},{"id":"ankle-foot-bones-arches~ai-9","moduleId":"ankle-foot-bones-arches","stem":"What is the clinical significance of the sole of the foot in relation to the arches?","options":[{"id":"a","text":"Sole injuries are unrelated to arches"},{"id":"b","text":"Sole structure supports foot arches"},{"id":"c","text":"Sole has no functional importance"},{"id":"d","text":"Sole injuries only affect the toes"}],"answerId":"b","explanation":"The structure of the sole of the foot is crucial for supporting the arches, which are essential for weight distribution.","kind":"integration","linkedModuleIds":["sole-of-foot"],"origin":"ai"}],"popliteal-fossa":[{"id":"popliteal-fossa~ai-0","moduleId":"popliteal-fossa","stem":"Which structure is the deepest in the popliteal fossa?","options":[{"id":"a","text":"Popliteal artery"},{"id":"b","text":"Popliteal vein"},{"id":"c","text":"Tibial nerve"},{"id":"d","text":"Common fibular nerve"}],"answerId":"a","explanation":"The popliteal artery is the deepest structure in the fossa, located against the joint capsule.","kind":"recall","origin":"ai"},{"id":"popliteal-fossa~ai-1","moduleId":"popliteal-fossa","stem":"What is the most common complication associated with a popliteal artery injury?","options":[{"id":"a","text":"Tibial nerve compression"},{"id":"b","text":"Common fibular nerve injury"},{"id":"c","text":"Popliteal vein thrombosis"},{"id":"d","text":"Distal pulse loss"}],"answerId":"d","explanation":"Injury to the popliteal artery can lead to absent distal pulses due to compromised blood flow.","kind":"mechanism","origin":"ai"},{"id":"popliteal-fossa~ai-2","moduleId":"popliteal-fossa","stem":"A patient presents with a pulsatile mass behind the knee. What is the likely diagnosis?","options":[{"id":"a","text":"Baker cyst"},{"id":"b","text":"Popliteal artery aneurysm"},{"id":"c","text":"Deep vein thrombosis"},{"id":"d","text":"Knee joint effusion"}],"answerId":"b","explanation":"A pulsatile mass in the popliteal fossa is indicative of a popliteal artery aneurysm.","kind":"clinical","origin":"ai"},{"id":"popliteal-fossa~ai-3","moduleId":"popliteal-fossa","stem":"What is the clinical significance of a Baker cyst?","options":[{"id":"a","text":"It is always asymptomatic."},{"id":"b","text":"It can rupture and mimic DVT."},{"id":"c","text":"It is a sign of popliteal artery injury."},{"id":"d","text":"It is a common cause of knee dislocation."}],"answerId":"b","explanation":"A Baker cyst can rupture, leading to soft posterior-knee swelling that may mimic deep vein thrombosis.","kind":"trap","origin":"ai"},{"id":"popliteal-fossa~ai-4","moduleId":"popliteal-fossa","stem":"Which nerve runs along the medial border of the biceps tendon in the popliteal fossa?","options":[{"id":"a","text":"Tibial nerve"},{"id":"b","text":"Common fibular nerve"},{"id":"c","text":"Femoral nerve"},{"id":"d","text":"Sural nerve"}],"answerId":"b","explanation":"The common fibular nerve runs along the medial border of the biceps tendon toward the fibular neck.","kind":"recall","origin":"ai"},{"id":"popliteal-fossa~ai-5","moduleId":"popliteal-fossa","stem":"How does the anatomy of the popliteal fossa relate to the gluteal region?","options":[{"id":"a","text":"Both contain the sciatic nerve."},{"id":"b","text":"Both are involved in knee joint movement."},{"id":"c","text":"Both have major vascular structures."},{"id":"d","text":"Both are innervated by the femoral nerve."}],"answerId":"a","explanation":"The popliteal fossa and gluteal region both contain the sciatic nerve, which is crucial for lower limb function.","kind":"integration","linkedModuleIds":["gluteal-region-nerves"],"origin":"ai"},{"id":"popliteal-fossa~ai-6","moduleId":"popliteal-fossa","stem":"What is the relationship between the popliteal fossa and the posterior thigh?","options":[{"id":"a","text":"Both regions are innervated by the tibial nerve."},{"id":"b","text":"Both contain the popliteal artery."},{"id":"c","text":"Both are involved in hip flexion."},{"id":"d","text":"Both are supplied by the femoral artery."}],"answerId":"a","explanation":"The posterior thigh is innervated by the tibial nerve, which also runs through the popliteal fossa.","kind":"integration","linkedModuleIds":["posterior-thigh-sciatic"],"origin":"ai"}],"sole-of-foot":[{"id":"sole-of-foot~ai-0","moduleId":"sole-of-foot","stem":"What is the primary function of the plantar aponeurosis?","options":[{"id":"a","text":"Support the medial longitudinal arch"},{"id":"b","text":"Facilitate toe flexion"},{"id":"c","text":"Provide sensation to the sole"},{"id":"d","text":"Protect the tibial nerve"}],"answerId":"a","explanation":"The plantar aponeurosis acts as a tie beam supporting the medial longitudinal arch of the foot.","kind":"recall","origin":"ai"},{"id":"sole-of-foot~ai-1","moduleId":"sole-of-foot","stem":"Which nerve primarily supplies the intrinsic muscles of the foot?","options":[{"id":"a","text":"Medial plantar nerve"},{"id":"b","text":"Lateral plantar nerve"},{"id":"c","text":"Tibial nerve"},{"id":"d","text":"Common peroneal nerve"}],"answerId":"b","explanation":"The lateral plantar nerve supplies most of the intrinsic muscles of the foot, similar to the ulnar nerve in the hand.","kind":"recall","origin":"ai"},{"id":"sole-of-foot~ai-2","moduleId":"sole-of-foot","stem":"A patient presents with burning pain and paresthesia in the sole after an ankle injury. Which condition is most likely?","options":[{"id":"a","text":"Plantar fasciitis"},{"id":"b","text":"Tarsal tunnel syndrome"},{"id":"c","text":"Achilles tendon rupture"},{"id":"d","text":"Metatarsal fracture"}],"answerId":"b","explanation":"Burning pain and paresthesia in the sole after trauma suggests tarsal tunnel syndrome due to tibial nerve compression.","kind":"clinical","origin":"ai"},{"id":"sole-of-foot~ai-3","moduleId":"sole-of-foot","stem":"What is the order of structures passing behind the medial malleolus?","options":[{"id":"a","text":"Tom, Dick, ANd Harry"},{"id":"b","text":"Harry, ANd Dick, Tom"},{"id":"c","text":"Dick, Tom, Harry, ANd"},{"id":"d","text":"ANd Harry, Tom, Dick"}],"answerId":"a","explanation":"The mnemonic 'Tom, Dick, ANd Harry' helps remember the order of structures: Tibialis posterior, flexor Digitorum longus, posterior tibial Artery + tibial Nerve, flexor Hallucis longus.","kind":"recall","origin":"ai"},{"id":"sole-of-foot~ai-4","moduleId":"sole-of-foot","stem":"A patient has weakness in toe flexion and clawing of the toes. Which nerve is likely injured?","options":[{"id":"a","text":"Medial plantar nerve"},{"id":"b","text":"Lateral plantar nerve"},{"id":"c","text":"Tibial nerve"},{"id":"d","text":"Common peroneal nerve"}],"answerId":"b","explanation":"Weakness in toe flexion and clawing of the toes indicates a lateral plantar nerve lesion affecting most intrinsic muscles.","kind":"clinical","origin":"ai"},{"id":"sole-of-foot~ai-5","moduleId":"sole-of-foot","stem":"Which condition is characterized by heel pain that is worst on the first steps in the morning?","options":[{"id":"a","text":"Tarsal tunnel syndrome"},{"id":"b","text":"Plantar fasciitis"},{"id":"c","text":"Achilles tendinitis"},{"id":"d","text":"Metatarsalgia"}],"answerId":"b","explanation":"Plantar fasciitis causes sharp heel pain, especially noticeable with the first steps after rest.","kind":"clinical","origin":"ai"},{"id":"sole-of-foot~ai-6","moduleId":"sole-of-foot","stem":"How does the anatomy of the foot relate to the anatomy of the hand?","options":[{"id":"a","text":"Both have similar muscle groups"},{"id":"b","text":"Both have a median and ulnar nerve equivalent"},{"id":"c","text":"Both have the same vascular supply"},{"id":"d","text":"Both have identical bone structures"}],"answerId":"b","explanation":"The medial and lateral plantar nerves in the foot mirror the median and ulnar nerves in the hand, with similar functional distributions.","kind":"integration","linkedModuleIds":["ankle-foot-bones-arches"],"origin":"ai"},{"id":"sole-of-foot~ai-7","moduleId":"sole-of-foot","stem":"What is the primary role of the tibial nerve in the sole of the foot?","options":[{"id":"a","text":"Sensory innervation only"},{"id":"b","text":"Motor innervation to all foot muscles"},{"id":"c","text":"Motor innervation to intrinsic muscles"},{"id":"d","text":"Sensory and motor innervation to the heel"}],"answerId":"c","explanation":"The tibial nerve provides motor innervation to the intrinsic muscles of the foot via its branches, the medial and lateral plantar nerves.","kind":"integration","linkedModuleIds":["leg-compartments"],"origin":"ai"}],"medial-thigh-adductors":[{"id":"medial-thigh-adductors~ai-0","moduleId":"medial-thigh-adductors","stem":"Which muscle is primarily responsible for adducting the thigh at the hip?","options":[{"id":"a","text":"Adductor longus"},{"id":"b","text":"Sartorius"},{"id":"c","text":"Rectus femoris"},{"id":"d","text":"Gluteus maximus"}],"answerId":"a","explanation":"The adductor longus is one of the primary muscles in the medial compartment responsible for thigh adduction.","kind":"recall","origin":"ai"},{"id":"medial-thigh-adductors~ai-1","moduleId":"medial-thigh-adductors","stem":"What is the primary nerve supplying the adductor muscles of the medial thigh?","options":[{"id":"a","text":"Femoral nerve"},{"id":"b","text":"Obturator nerve"},{"id":"c","text":"Sciatic nerve"},{"id":"d","text":"Inferior gluteal nerve"}],"answerId":"b","explanation":"The obturator nerve (L2–L4) primarily supplies the adductor muscles of the medial thigh.","kind":"recall","origin":"ai"},{"id":"medial-thigh-adductors~ai-2","moduleId":"medial-thigh-adductors","stem":"A patient presents with weakness in thigh adduction and numbness over the medial thigh after pelvic surgery. Which nerve is likely injured?","options":[{"id":"a","text":"Femoral nerve"},{"id":"b","text":"Obturator nerve"},{"id":"c","text":"Sciatic nerve"},{"id":"d","text":"Inferior gluteal nerve"}],"answerId":"b","explanation":"Weakness in thigh adduction and sensory loss over the medial thigh are indicative of an obturator nerve injury.","kind":"clinical","origin":"ai"},{"id":"medial-thigh-adductors~ai-3","moduleId":"medial-thigh-adductors","stem":"What is the significance of the adductor hiatus in the thigh?","options":[{"id":"a","text":"Passage for the obturator nerve"},{"id":"b","text":"Passage for the femoral vessels"},{"id":"c","text":"Attachment for adductor magnus"},{"id":"d","text":"Site of adductor magnus innervation"}],"answerId":"b","explanation":"The adductor hiatus allows the femoral vessels to pass from the anterior thigh to the popliteal fossa.","kind":"mechanism","origin":"ai"},{"id":"medial-thigh-adductors~ai-4","moduleId":"medial-thigh-adductors","stem":"Which statement about the adductor magnus is correct?","options":[{"id":"a","text":"It is innervated entirely by the obturator nerve"},{"id":"b","text":"It has dual innervation"},{"id":"c","text":"It is the only adductor muscle crossing the knee"},{"id":"d","text":"It originates from the ischial tuberosity only"}],"answerId":"b","explanation":"The adductor magnus has dual innervation: its adductor part is supplied by the obturator nerve, while the hamstring part is supplied by the tibial nerve.","kind":"trap","origin":"ai"},{"id":"medial-thigh-adductors~ai-5","moduleId":"medial-thigh-adductors","stem":"A patient presents with medial thigh pain and weakness in adduction. Imaging reveals an obturator hernia. Which sign is commonly associated with this condition?","options":[{"id":"a","text":"Trendelenburg sign"},{"id":"b","text":"Howship–Romberg sign"},{"id":"c","text":"Patellar reflex"},{"id":"d","text":"Thigh flexion weakness"}],"answerId":"b","explanation":"The Howship–Romberg sign indicates medial thigh pain due to obturator nerve compression from an obturator hernia.","kind":"clinical","origin":"ai"},{"id":"medial-thigh-adductors~ai-6","moduleId":"medial-thigh-adductors","stem":"How does the function of the adductor magnus relate to the hip joint mechanics?","options":[{"id":"a","text":"It only flexes the hip"},{"id":"b","text":"It extends the hip during adduction"},{"id":"c","text":"It abducts the hip"},{"id":"d","text":"It internally rotates the hip"}],"answerId":"b","explanation":"The hamstring part of the adductor magnus extends the hip during adduction, linking its function to hip joint mechanics.","kind":"integration","linkedModuleIds":["lower-limb-bones-hip-joint"],"origin":"ai"},{"id":"medial-thigh-adductors~ai-7","moduleId":"medial-thigh-adductors","stem":"Which structure passes through the adductor hiatus to reach the popliteal fossa?","options":[{"id":"a","text":"Obturator nerve"},{"id":"b","text":"Femoral artery"},{"id":"c","text":"Sciatic nerve"},{"id":"d","text":"Popliteal vein"}],"answerId":"b","explanation":"The femoral artery and vein pass through the adductor hiatus to become the popliteal artery and vein in the popliteal fossa.","kind":"integration","linkedModuleIds":["lower-limb-bones-hip-joint"],"origin":"ai"}],"lower-limb-bones-hip-joint":[{"id":"lower-limb-bones-hip-joint~ai-0","moduleId":"lower-limb-bones-hip-joint","stem":"Which bones fuse to form the hip bone?","options":[{"id":"a","text":"Ilium, ischium, and pubis"},{"id":"b","text":"Femur, tibia, and fibula"},{"id":"c","text":"Clavicle, scapula, and humerus"},{"id":"d","text":"Radius, ulna, and carpals"}],"answerId":"a","explanation":"The hip bone is formed by the fusion of the ilium, ischium, and pubis at the acetabulum.","kind":"recall","origin":"ai"},{"id":"lower-limb-bones-hip-joint~ai-1","moduleId":"lower-limb-bones-hip-joint","stem":"What is the primary blood supply to the femoral head in adults?","options":[{"id":"a","text":"Artery of the ligamentum teres"},{"id":"b","text":"Medial circumflex femoral artery"},{"id":"c","text":"Lateral femoral circumflex artery"},{"id":"d","text":"Inferior gluteal artery"}],"answerId":"b","explanation":"In adults, the medial circumflex femoral artery is the dominant supply to the femoral head, while the artery of the ligamentum teres is a minor contributor.","kind":"recall","origin":"ai"},{"id":"lower-limb-bones-hip-joint~ai-2","moduleId":"lower-limb-bones-hip-joint","stem":"A patient presents with a shortened, flexed, adducted, and internally rotated limb after a dashboard injury. What is the most likely diagnosis?","options":[{"id":"a","text":"Femoral neck fracture"},{"id":"b","text":"Posterior hip dislocation"},{"id":"c","text":"Anterior hip dislocation"},{"id":"d","text":"Trochanteric bursitis"}],"answerId":"b","explanation":"These findings are characteristic of a posterior hip dislocation, often seen in dashboard injuries.","kind":"clinical","origin":"ai"},{"id":"lower-limb-bones-hip-joint~ai-3","moduleId":"lower-limb-bones-hip-joint","stem":"What is the consequence of an intracapsular fracture of the femoral neck?","options":[{"id":"a","text":"Increased blood supply to the femoral head"},{"id":"b","text":"Avascular necrosis of the femoral head"},{"id":"c","text":"Immediate healing of the fracture"},{"id":"d","text":"No significant complications"}],"answerId":"b","explanation":"An intracapsular fracture disrupts the blood supply from the medial circumflex femoral artery, leading to avascular necrosis of the femoral head.","kind":"mechanism","origin":"ai"},{"id":"lower-limb-bones-hip-joint~ai-4","moduleId":"lower-limb-bones-hip-joint","stem":"Which of the following is a common finding in elderly patients with a femoral neck fracture?","options":[{"id":"a","text":"Leg shortened and externally rotated"},{"id":"b","text":"Leg lengthening and internally rotated"},{"id":"c","text":"No change in limb position"},{"id":"d","text":"Leg shortened and adducted"}],"answerId":"a","explanation":"Elderly patients with a femoral neck fracture typically present with a shortened and externally rotated leg.","kind":"recall","origin":"ai"},{"id":"lower-limb-bones-hip-joint~ai-5","moduleId":"lower-limb-bones-hip-joint","stem":"How does the blood supply to the femoral head differ in adults compared to children?","options":[{"id":"a","text":"Children rely solely on the ligamentum teres"},{"id":"b","text":"Adults have a dominant medial circumflex femoral artery"},{"id":"c","text":"Children have a more robust retinacular supply"},{"id":"d","text":"Adults have no blood supply to the femoral head"}],"answerId":"b","explanation":"In adults, the medial circumflex femoral artery is the main supply, while in children, the artery of the ligamentum teres plays a more significant role.","kind":"trap","origin":"ai"},{"id":"lower-limb-bones-hip-joint~ai-6","moduleId":"lower-limb-bones-hip-joint","stem":"Which embryological process is primarily responsible for the formation of the hip joint?","options":[{"id":"a","text":"Endochondral ossification"},{"id":"b","text":"Intramembranous ossification"},{"id":"c","text":"Apoptosis"},{"id":"d","text":"Mesenchymal condensation"}],"answerId":"a","explanation":"The hip joint is formed through endochondral ossification, where cartilage models are replaced by bone.","kind":"integration","linkedModuleIds":["msk-embryo-limb-joints"],"origin":"ai"},{"id":"lower-limb-bones-hip-joint~ai-7","moduleId":"lower-limb-bones-hip-joint","stem":"Which structure is crucial for the stability of the hip joint?","options":[{"id":"a","text":"Labrum"},{"id":"b","text":"Meniscus"},{"id":"c","text":"Tendon"},{"id":"d","text":"Synovial membrane"}],"answerId":"a","explanation":"The labrum deepens the acetabulum, providing stability to the hip joint.","kind":"integration","linkedModuleIds":["femoral-triangle-anterior-thigh"],"origin":"ai"}],"citation-synthesis-conceptual-framework":[{"id":"citation-synthesis-conceptual-framework~ai-0","moduleId":"citation-synthesis-conceptual-framework","stem":"What is the primary purpose of a synthesis table in a literature review?","options":[{"id":"a","text":"To summarize findings from each study"},{"id":"b","text":"To organize studies by theme for comparison"},{"id":"c","text":"To list all studies reviewed"},{"id":"d","text":"To provide a reference list"}],"answerId":"b","explanation":"A synthesis table organizes studies by theme, allowing for comparison and contrast of findings, rather than just listing them.","kind":"recall","origin":"ai"},{"id":"citation-synthesis-conceptual-framework~ai-1","moduleId":"citation-synthesis-conceptual-framework","stem":"Which of the following best describes self-plagiarism?","options":[{"id":"a","text":"Citing a source without permission"},{"id":"b","text":"Reusing your own prior text without citation"},{"id":"c","text":"Copying text from another author"},{"id":"d","text":"Failing to include a reference for a citation"}],"answerId":"b","explanation":"Self-plagiarism occurs when an author reuses their own previously published text without proper citation.","kind":"recall","origin":"ai"},{"id":"citation-synthesis-conceptual-framework~ai-2","moduleId":"citation-synthesis-conceptual-framework","stem":"What is a key characteristic of a conceptual framework in a literature review?","options":[{"id":"a","text":"It is a bibliography of sources"},{"id":"b","text":"It visualizes the relationship between study variables"},{"id":"c","text":"It summarizes the findings of each study"},{"id":"d","text":"It lists the authors of the studies reviewed"}],"answerId":"b","explanation":"A conceptual framework is a diagram that visualizes the relationships between study variables, operationalizing the hypothesis.","kind":"recall","origin":"ai"},{"id":"citation-synthesis-conceptual-framework~ai-3","moduleId":"citation-synthesis-conceptual-framework","stem":"What common error occurs when an in-text citation is provided without a corresponding reference entry?","options":[{"id":"a","text":"Plagiarism"},{"id":"b","text":"Self-plagiarism"},{"id":"c","text":"Citation mismatch"},{"id":"d","text":"Reference omission"}],"answerId":"c","explanation":"Every in-text citation must have a corresponding reference entry; failing to do so results in a citation mismatch.","kind":"trap","origin":"ai"},{"id":"citation-synthesis-conceptual-framework~ai-4","moduleId":"citation-synthesis-conceptual-framework","stem":"Which tool is recommended for managing citations and references effectively?","options":[{"id":"a","text":"Word processor"},{"id":"b","text":"Reference manager"},{"id":"c","text":"Spreadsheet software"},{"id":"d","text":"Presentation software"}],"answerId":"b","explanation":"Reference managers like EndNote, Zotero, or Mendeley help store PDFs, insert citations, and auto-format reference lists.","kind":"recall","origin":"ai"},{"id":"citation-synthesis-conceptual-framework~ai-5","moduleId":"citation-synthesis-conceptual-framework","stem":"How does a literature review support the development of a conceptual framework?","options":[{"id":"a","text":"By providing a list of references"},{"id":"b","text":"By summarizing each study's findings"},{"id":"c","text":"By mapping out relationships between variables"},{"id":"d","text":"By identifying the most cited authors"}],"answerId":"c","explanation":"A literature review helps build a conceptual framework by mapping out the relationships between variables derived from the literature.","kind":"integration","linkedModuleIds":["literature-review-purpose-search"],"origin":"ai"},{"id":"citation-synthesis-conceptual-framework~ai-6","moduleId":"citation-synthesis-conceptual-framework","stem":"What is the relationship between a conceptual framework and the methodology of a study?","options":[{"id":"a","text":"The framework dictates the study's sample size"},{"id":"b","text":"The framework visualizes the hypothesis and guides variable measurement"},{"id":"c","text":"The framework replaces the need for a literature review"},{"id":"d","text":"The framework is solely for presentation purposes"}],"answerId":"b","explanation":"The conceptual framework visualizes the hypothesis and justifies which variables to measure, directly linking to the study's methodology.","kind":"integration","linkedModuleIds":["literature-review-purpose-search"],"origin":"ai"}],"study-designs-hierarchy":[{"id":"study-designs-hierarchy~ai-0","moduleId":"study-designs-hierarchy","stem":"What type of study design is best for investigating rare diseases?","options":[{"id":"a","text":"Cohort study"},{"id":"b","text":"Case-control study"},{"id":"c","text":"Cross-sectional study"},{"id":"d","text":"Ecological study"}],"answerId":"b","explanation":"Case-control studies are optimal for rare diseases as they start with the outcome and look backward for exposure.","kind":"recall","origin":"ai"},{"id":"study-designs-hierarchy~ai-1","moduleId":"study-designs-hierarchy","stem":"Which measure is derived from a cohort study?","options":[{"id":"a","text":"Odds Ratio"},{"id":"b","text":"Relative Risk"},{"id":"c","text":"Prevalence Ratio"},{"id":"d","text":"Incidence Rate"}],"answerId":"b","explanation":"Cohort studies yield Relative Risk as they follow exposed and unexposed groups over time to determine incidence.","kind":"recall","origin":"ai"},{"id":"study-designs-hierarchy~ai-2","moduleId":"study-designs-hierarchy","stem":"What is the main weakness of case-control studies?","options":[{"id":"a","text":"Loss to follow-up"},{"id":"b","text":"Recall bias"},{"id":"c","text":"Ecological fallacy"},{"id":"d","text":"Randomization bias"}],"answerId":"b","explanation":"Recall bias is a classic weakness of retrospective case-control studies, affecting the accuracy of exposure information.","kind":"trap","origin":"ai"},{"id":"study-designs-hierarchy~ai-3","moduleId":"study-designs-hierarchy","stem":"What is the primary advantage of randomization in RCTs?","options":[{"id":"a","text":"Reduces sample size"},{"id":"b","text":"Balances known confounders"},{"id":"c","text":"Balances known and unknown confounders"},{"id":"d","text":"Eliminates bias completely"}],"answerId":"c","explanation":"Randomization in RCTs balances both known and unknown confounders, making it the strongest design for causal inference.","kind":"mechanism","origin":"ai"},{"id":"study-designs-hierarchy~ai-4","moduleId":"study-designs-hierarchy","stem":"In which study design is the ecological fallacy a concern?","options":[{"id":"a","text":"Cohort study"},{"id":"b","text":"Case-control study"},{"id":"c","text":"Ecological study"},{"id":"d","text":"Cross-sectional study"}],"answerId":"c","explanation":"Ecological studies use group-level data, which can lead to incorrect assumptions about individual-level relationships, known as the ecological fallacy.","kind":"recall","origin":"ai"},{"id":"study-designs-hierarchy~ai-5","moduleId":"study-designs-hierarchy","stem":"How does a case-control study differ from a cohort study in terms of direction of enquiry?","options":[{"id":"a","text":"Cohort studies are prospective; case-control studies are retrospective"},{"id":"b","text":"Case-control studies are prospective; cohort studies are retrospective"},{"id":"c","text":"Both are prospective"},{"id":"d","text":"Both are retrospective"}],"answerId":"a","explanation":"Cohort studies are prospective as they follow subjects forward in time, while case-control studies are retrospective, starting with outcomes.","kind":"integration","linkedModuleIds":["variables-confounding-bias"],"origin":"ai"},{"id":"study-designs-hierarchy~ai-6","moduleId":"study-designs-hierarchy","stem":"Which study design is most appropriate for assessing the effectiveness of a new drug?","options":[{"id":"a","text":"Cohort study"},{"id":"b","text":"Case-control study"},{"id":"c","text":"Randomized Controlled Trial"},{"id":"d","text":"Cross-sectional study"}],"answerId":"c","explanation":"Randomized Controlled Trials (RCTs) are the gold standard for assessing the effectiveness of interventions due to their ability to control for confounding variables.","kind":"recall","origin":"ai"},{"id":"study-designs-hierarchy~ai-7","moduleId":"study-designs-hierarchy","stem":"When would you prefer a cohort study over a case-control study?","options":[{"id":"a","text":"When the disease is rare"},{"id":"b","text":"When the exposure is rare"},{"id":"c","text":"When you need to determine incidence"},{"id":"d","text":"When data collection is limited"}],"answerId":"c","explanation":"Cohort studies are preferred when you need to determine incidence, as they follow participants over time from exposure to outcome.","kind":"integration","linkedModuleIds":["sampling-methods"],"origin":"ai"}],"data-types-descriptive-stats":[{"id":"data-types-descriptive-stats~ai-0","moduleId":"data-types-descriptive-stats","stem":"Which of the following is a characteristic of ordinal data?","options":[{"id":"a","text":"It has a true zero point"},{"id":"b","text":"It can be averaged meaningfully"},{"id":"c","text":"It has a natural order"},{"id":"d","text":"It is always categorical"}],"answerId":"c","explanation":"Ordinal data has a natural order but the intervals between values are not necessarily equal.","kind":"recall","origin":"ai"},{"id":"data-types-descriptive-stats~ai-1","moduleId":"data-types-descriptive-stats","stem":"In a right-skewed distribution, which statement is true?","options":[{"id":"a","text":"Mean < Median < Mode"},{"id":"b","text":"Mean = Median = Mode"},{"id":"c","text":"Mean > Median > Mode"},{"id":"d","text":"Median < Mode < Mean"}],"answerId":"c","explanation":"In a right-skewed distribution, the mean is greater than the median, which is greater than the mode.","kind":"recall","origin":"ai"},{"id":"data-types-descriptive-stats~ai-2","moduleId":"data-types-descriptive-stats","stem":"What is the purpose of the standard error (SE)?","options":[{"id":"a","text":"To describe the spread of individual data points"},{"id":"b","text":"To measure the precision of the mean estimate"},{"id":"c","text":"To determine the mode of a dataset"},{"id":"d","text":"To calculate the variance of a dataset"}],"answerId":"b","explanation":"The standard error measures the precision of the mean estimate, not the spread of individual values.","kind":"mechanism","origin":"ai"},{"id":"data-types-descriptive-stats~ai-3","moduleId":"data-types-descriptive-stats","stem":"Which summary statistic is most appropriate for skewed data?","options":[{"id":"a","text":"Mean ± SD"},{"id":"b","text":"Median (IQR)"},{"id":"c","text":"Mode"},{"id":"d","text":"Mean ± SE"}],"answerId":"b","explanation":"For skewed data, the median and interquartile range (IQR) are preferred as they are more robust to outliers.","kind":"trap","origin":"ai"},{"id":"data-types-descriptive-stats~ai-4","moduleId":"data-types-descriptive-stats","stem":"If a dataset is normally distributed, which of the following is true?","options":[{"id":"a","text":"Mean = Median = Mode"},{"id":"b","text":"Mean > Median > Mode"},{"id":"c","text":"Median is not defined"},{"id":"d","text":"Mode is always zero"}],"answerId":"a","explanation":"In a normal distribution, the mean, median, and mode are all equal due to the symmetry of the distribution.","kind":"recall","origin":"ai"},{"id":"data-types-descriptive-stats~ai-5","moduleId":"data-types-descriptive-stats","stem":"How does the standard deviation (SD) differ from the standard error (SE)?","options":[{"id":"a","text":"SD describes sample variability; SE describes population variability"},{"id":"b","text":"SD is always smaller than SE"},{"id":"c","text":"SD measures spread of data; SE measures precision of the mean"},{"id":"d","text":"SD is used for categorical data; SE for continuous data"}],"answerId":"c","explanation":"Standard deviation measures the spread of individual data points, while standard error measures the precision of the mean estimate.","kind":"trap","origin":"ai"},{"id":"data-types-descriptive-stats~ai-6","moduleId":"data-types-descriptive-stats","stem":"How can understanding data types improve the interpretation of cardiac electrical axis vectors?","options":[{"id":"a","text":"By ensuring correct statistical tests are applied"},{"id":"b","text":"By determining the mean electrical axis"},{"id":"c","text":"By averaging categorical data"},{"id":"d","text":"By identifying outliers in the data"}],"answerId":"a","explanation":"Understanding data types helps in selecting the appropriate statistical tests for analyzing cardiac electrical axis vectors.","kind":"integration","linkedModuleIds":["cardiac-electrical-axis-vectors"],"origin":"ai"},{"id":"data-types-descriptive-stats~ai-7","moduleId":"data-types-descriptive-stats","stem":"Which statistical method would be most appropriate for analyzing the relationship between Likert scale responses and cardiac health outcomes?","options":[{"id":"a","text":"T-test"},{"id":"b","text":"ANOVA"},{"id":"c","text":"Chi-square test"},{"id":"d","text":"Spearman's rank correlation"}],"answerId":"d","explanation":"Spearman's rank correlation is suitable for ordinal data like Likert scales, allowing for analysis of relationships with cardiac health outcomes.","kind":"integration","linkedModuleIds":["inferential-stats-p-value"],"origin":"ai"}],"sampling-methods":[{"id":"sampling-methods~ai-0","moduleId":"sampling-methods","stem":"What is the primary advantage of stratified sampling over cluster sampling?","options":[{"id":"a","text":"Increases precision by sampling all subgroups"},{"id":"b","text":"Reduces cost by sampling whole groups"},{"id":"c","text":"Allows for convenience in sampling"},{"id":"d","text":"Minimizes selection bias completely"}],"answerId":"a","explanation":"Stratified sampling ensures representation from all subgroups, increasing precision, while cluster sampling reduces costs by sampling whole groups.","kind":"trap","origin":"ai"},{"id":"sampling-methods~ai-1","moduleId":"sampling-methods","stem":"Which sampling method is most likely to introduce selection bias?","options":[{"id":"a","text":"Stratified sampling"},{"id":"b","text":"Cluster sampling"},{"id":"c","text":"Convenience sampling"},{"id":"d","text":"Systematic sampling"}],"answerId":"c","explanation":"Convenience sampling is the least rigorous and most prone to selection bias, as it does not ensure a representative sample.","kind":"recall","origin":"ai"},{"id":"sampling-methods~ai-2","moduleId":"sampling-methods","stem":"In systematic sampling, what is the main risk if the list has hidden periodicity?","options":[{"id":"a","text":"Increased cost of sampling"},{"id":"b","text":"Bias in the sample selection"},{"id":"c","text":"Reduced representation of subgroups"},{"id":"d","text":"Higher precision in estimates"}],"answerId":"b","explanation":"Hidden periodicity can lead to biased samples as certain units may be overrepresented or underrepresented.","kind":"mechanism","origin":"ai"},{"id":"sampling-methods~ai-3","moduleId":"sampling-methods","stem":"What is the key characteristic of cluster sampling?","options":[{"id":"a","text":"Sampling from every subgroup"},{"id":"b","text":"Sampling whole groups randomly"},{"id":"c","text":"Ensuring homogeneity within clusters"},{"id":"d","text":"Minimizing selection bias"}],"answerId":"b","explanation":"Cluster sampling involves randomly selecting whole groups, which can reduce costs but may not ensure homogeneity within those groups.","kind":"recall","origin":"ai"},{"id":"sampling-methods~ai-4","moduleId":"sampling-methods","stem":"Which of the following is an example of non-probability sampling?","options":[{"id":"a","text":"Stratified sampling"},{"id":"b","text":"Systematic sampling"},{"id":"c","text":"Snowball sampling"},{"id":"d","text":"Cluster sampling"}],"answerId":"c","explanation":"Snowball sampling is a non-probability method where existing participants recruit future subjects, often used for hard-to-reach populations.","kind":"recall","origin":"ai"},{"id":"sampling-methods~ai-5","moduleId":"sampling-methods","stem":"How does selection bias affect the validity of a study's findings?","options":[{"id":"a","text":"It enhances the generalizability of results"},{"id":"b","text":"It leads to a biased estimate of the population parameter"},{"id":"c","text":"It increases the precision of the sample statistic"},{"id":"d","text":"It ensures that all subgroups are represented"}],"answerId":"b","explanation":"Selection bias results in a sample that is not representative of the population, leading to biased estimates.","kind":"clinical","origin":"ai"},{"id":"sampling-methods~ai-6","moduleId":"sampling-methods","stem":"How does stratified sampling relate to the hierarchy of evidence in study designs?","options":[{"id":"a","text":"It provides the lowest level of evidence"},{"id":"b","text":"It is a method to minimize confounding variables"},{"id":"c","text":"It ensures a representative sample, enhancing validity"},{"id":"d","text":"It is primarily used in qualitative research"}],"answerId":"c","explanation":"Stratified sampling enhances the validity of study findings by ensuring that all subgroups are adequately represented, which is crucial for high-quality evidence.","kind":"integration","linkedModuleIds":["study-designs-hierarchy"],"origin":"ai"},{"id":"sampling-methods~ai-7","moduleId":"sampling-methods","stem":"What is a common pitfall of convenience sampling in relation to confounding variables?","options":[{"id":"a","text":"It guarantees representation across all demographics"},{"id":"b","text":"It may overlook hidden confounding factors"},{"id":"c","text":"It reduces the overall sample size"},{"id":"d","text":"It simplifies the sampling process"}],"answerId":"b","explanation":"Convenience sampling often fails to account for hidden confounding variables, which can skew results and limit generalizability.","kind":"integration","linkedModuleIds":["variables-confounding-bias"],"origin":"ai"}],"research-ethics-history-belmont":[{"id":"research-ethics-history-belmont~ai-0","moduleId":"research-ethics-history-belmont","stem":"What is the cardinal rule of the Nuremberg Code?","options":[{"id":"a","text":"Voluntary consent is absolutely essential"},{"id":"b","text":"Research must maximize societal benefit"},{"id":"c","text":"Animal studies must precede human trials"},{"id":"d","text":"Participants must be compensated for their time"}],"answerId":"a","explanation":"The Nuremberg Code emphasizes that voluntary consent is a fundamental requirement for ethical research.","kind":"recall","origin":"ai"},{"id":"research-ethics-history-belmont~ai-1","moduleId":"research-ethics-history-belmont","stem":"Which principle of the Belmont Report is primarily concerned with informed consent?","options":[{"id":"a","text":"Beneficence"},{"id":"b","text":"Justice"},{"id":"c","text":"Respect for persons"},{"id":"d","text":"Non-maleficence"}],"answerId":"c","explanation":"Informed consent is an application of the principle of Respect for persons, which protects individual autonomy.","kind":"recall","origin":"ai"},{"id":"research-ethics-history-belmont~ai-2","moduleId":"research-ethics-history-belmont","stem":"The Tuskegee Syphilis Study led to which significant regulatory change?","options":[{"id":"a","text":"Nuremberg Code"},{"id":"b","text":"Declaration of Helsinki"},{"id":"c","text":"National Research Act"},{"id":"d","text":"Belmont Report"}],"answerId":"c","explanation":"The unethical practices observed in the Tuskegee Syphilis Study prompted the National Research Act, which established regulations for research ethics.","kind":"recall","origin":"ai"},{"id":"research-ethics-history-belmont~ai-3","moduleId":"research-ethics-history-belmont","stem":"Which principle of the Belmont Report focuses on fair selection of research participants?","options":[{"id":"a","text":"Respect for persons"},{"id":"b","text":"Beneficence"},{"id":"c","text":"Justice"},{"id":"d","text":"Autonomy"}],"answerId":"c","explanation":"The principle of Justice in the Belmont Report emphasizes the fair distribution of research burdens and benefits among participants.","kind":"recall","origin":"ai"},{"id":"research-ethics-history-belmont~ai-4","moduleId":"research-ethics-history-belmont","stem":"In the context of the Belmont Report, which application corresponds with the principle of Beneficence?","options":[{"id":"a","text":"Informed consent"},{"id":"b","text":"Risk/benefit assessment"},{"id":"c","text":"Fair participant selection"},{"id":"d","text":"Right to withdraw"}],"answerId":"b","explanation":"Beneficence relates to assessing risks and benefits to maximize benefits and minimize harm in research.","kind":"trap","origin":"ai"},{"id":"research-ethics-history-belmont~ai-5","moduleId":"research-ethics-history-belmont","stem":"How does the Declaration of Helsinki differ from the Nuremberg Code?","options":[{"id":"a","text":"It is a legally binding document"},{"id":"b","text":"It prioritizes participant welfare over scientific interests"},{"id":"c","text":"It does not require informed consent"},{"id":"d","text":"It was established before the Nuremberg Code"}],"answerId":"b","explanation":"The Declaration of Helsinki emphasizes the welfare of research participants over the interests of science and society.","kind":"mechanism","origin":"ai"},{"id":"research-ethics-history-belmont~ai-6","moduleId":"research-ethics-history-belmont","stem":"How do the Belmont principles apply to child maltreatment research ethics (linked to hrp1-child-maltreatment-recognition)?","options":[{"id":"a","text":"Respect for persons requires mandatory reporting"},{"id":"b","text":"Beneficence necessitates risk assessment for children"},{"id":"c","text":"Justice demands equal treatment of all participants"},{"id":"d","text":"Informed consent is not needed for vulnerable populations"}],"answerId":"b","explanation":"In child maltreatment research, the principle of Beneficence necessitates careful risk assessment to protect vulnerable children.","kind":"integration","linkedModuleIds":["hrp1-child-maltreatment-recognition"],"origin":"ai"},{"id":"research-ethics-history-belmont~ai-7","moduleId":"research-ethics-history-belmont","stem":"What is a key ethical consideration when conducting research on child sexual abuse (linked to hrp1-child-sexual-abuse-response)?","options":[{"id":"a","text":"Informed consent from the child is sufficient"},{"id":"b","text":"Beneficence must prioritize the child's well-being"},{"id":"c","text":"Justice allows for coercive recruitment methods"},{"id":"d","text":"Respect for persons can be waived in emergencies"}],"answerId":"b","explanation":"In research on child sexual abuse, the principle of Beneficence must prioritize the well-being and safety of the child participants.","kind":"integration","linkedModuleIds":["hrp1-child-sexual-abuse-response"],"origin":"ai"}],"informed-consent-irb":[{"id":"informed-consent-irb~ai-0","moduleId":"informed-consent-irb","stem":"What are the three essential elements of informed consent?","options":[{"id":"a","text":"Information, Comprehension, Voluntariness"},{"id":"b","text":"Assent, Permission, Understanding"},{"id":"c","text":"Risk, Benefit, Autonomy"},{"id":"d","text":"Disclosure, Agreement, Withdrawal"}],"answerId":"a","explanation":"Informed consent requires Information, Comprehension, and Voluntariness to be valid.","kind":"recall","origin":"ai"},{"id":"informed-consent-irb~ai-1","moduleId":"informed-consent-irb","stem":"Which review level is appropriate for research involving no more than minimal risk?","options":[{"id":"a","text":"Exempt"},{"id":"b","text":"Expedited"},{"id":"c","text":"Full board"},{"id":"d","text":"Minimal risk"}],"answerId":"b","explanation":"Expedited review is designated for research involving no more than minimal risk.","kind":"recall","origin":"ai"},{"id":"informed-consent-irb~ai-2","moduleId":"informed-consent-irb","stem":"What is required for a child to participate in research?","options":[{"id":"a","text":"Only parental permission"},{"id":"b","text":"Only child’s assent"},{"id":"c","text":"Parental permission plus child’s assent"},{"id":"d","text":"No consent needed for minors"}],"answerId":"c","explanation":"Children require both parental permission and their own assent to participate in research.","kind":"recall","origin":"ai"},{"id":"informed-consent-irb~ai-3","moduleId":"informed-consent-irb","stem":"Which of the following is a misconception about informed consent?","options":[{"id":"a","text":"Assent is sufficient for minors"},{"id":"b","text":"Voluntariness is essential"},{"id":"c","text":"Information must be provided"},{"id":"d","text":"Comprehension is necessary"}],"answerId":"a","explanation":"Assent alone is not sufficient; parental permission is also required for minors.","kind":"trap","origin":"ai"},{"id":"informed-consent-irb~ai-4","moduleId":"informed-consent-irb","stem":"What type of risk is attributable to participating in research?","options":[{"id":"a","text":"Risk of the disease"},{"id":"b","text":"Risk of standard care"},{"id":"c","text":"Risk of research itself"},{"id":"d","text":"Risk of non-participation"}],"answerId":"c","explanation":"Only the risk attributable to the research itself counts against the study's risk-benefit balance.","kind":"recall","origin":"ai"},{"id":"informed-consent-irb~ai-5","moduleId":"informed-consent-irb","stem":"How does the Belmont Report relate to informed consent?","options":[{"id":"a","text":"It defines the elements of consent"},{"id":"b","text":"It provides historical context for ethical standards"},{"id":"c","text":"It outlines the IRB review process"},{"id":"d","text":"It specifies risks associated with research"}],"answerId":"b","explanation":"The Belmont Report provides historical context and ethical principles that underpin informed consent.","kind":"integration","linkedModuleIds":["research-ethics-history-belmont"],"origin":"ai"},{"id":"informed-consent-irb~ai-6","moduleId":"informed-consent-irb","stem":"In the context of child sexual abuse, why is informed consent particularly important?","options":[{"id":"a","text":"To ensure legal compliance"},{"id":"b","text":"To respect the autonomy of the child"},{"id":"c","text":"To minimize psychological risks"},{"id":"d","text":"To facilitate research funding"}],"answerId":"c","explanation":"Informed consent is crucial to minimize psychological risks, especially in vulnerable populations like children.","kind":"integration","linkedModuleIds":["hrp1-child-sexual-abuse-response"],"origin":"ai"}],"hypothesis-objectives":[{"id":"hypothesis-objectives~ai-0","moduleId":"hypothesis-objectives","stem":"What does the null hypothesis (H₀) state?","options":[{"id":"a","text":"There is a difference between groups"},{"id":"b","text":"There is no difference between groups"},{"id":"c","text":"There is an association between variables"},{"id":"d","text":"There is no association between variables"}],"answerId":"b","explanation":"The null hypothesis (H₀) posits that there is no difference or association, serving as the default position in hypothesis testing.","kind":"recall","origin":"ai"},{"id":"hypothesis-objectives~ai-1","moduleId":"hypothesis-objectives","stem":"Which of the following is a characteristic of a SMART objective?","options":[{"id":"a","text":"Vague and broad"},{"id":"b","text":"Specific and measurable"},{"id":"c","text":"Open-ended and flexible"},{"id":"d","text":"Ambiguous and general"}],"answerId":"b","explanation":"SMART objectives are defined as Specific, Measurable, Achievable, Relevant, and Time-bound.","kind":"recall","origin":"ai"},{"id":"hypothesis-objectives~ai-2","moduleId":"hypothesis-objectives","stem":"What is the primary purpose of a hypothesis in research?","options":[{"id":"a","text":"To describe the research findings"},{"id":"b","text":"To test a prediction derived from the research question"},{"id":"c","text":"To summarize the research objectives"},{"id":"d","text":"To provide a conclusion of the study"}],"answerId":"b","explanation":"A hypothesis is a testable, falsifiable prediction that stems from the research question, guiding the research process.","kind":"recall","origin":"ai"},{"id":"hypothesis-objectives~ai-3","moduleId":"hypothesis-objectives","stem":"Which of the following statements about p-values is true?","options":[{"id":"a","text":"A significant p-value proves the alternative hypothesis is true"},{"id":"b","text":"A significant p-value indicates strong evidence against the null hypothesis"},{"id":"c","text":"A significant p-value confirms the null hypothesis"},{"id":"d","text":"A significant p-value guarantees a correct conclusion"}],"answerId":"b","explanation":"A significant p-value provides evidence to reject the null hypothesis, but it does not prove the alternative hypothesis.","kind":"trap","origin":"ai"},{"id":"hypothesis-objectives~ai-4","moduleId":"hypothesis-objectives","stem":"Which of the following is an example of a non-directional hypothesis?","options":[{"id":"a","text":"Drug A reduces blood pressure"},{"id":"b","text":"Drug B has no effect on blood pressure"},{"id":"c","text":"Drug C changes blood pressure"},{"id":"d","text":"Drug D increases blood pressure"}],"answerId":"c","explanation":"A non-directional hypothesis simply states that there is a change or difference without specifying the direction.","kind":"recall","origin":"ai"},{"id":"hypothesis-objectives~ai-5","moduleId":"hypothesis-objectives","stem":"How does a research question relate to the hypothesis and objectives?","options":[{"id":"a","text":"The research question defines the hypothesis and objectives"},{"id":"b","text":"The hypothesis is derived from the objectives"},{"id":"c","text":"The objectives are independent of the hypothesis"},{"id":"d","text":"The hypothesis and objectives do not relate to the research question"}],"answerId":"a","explanation":"The research question guides the formulation of the hypothesis and the subsequent objectives in a study.","kind":"mechanism","origin":"ai"},{"id":"hypothesis-objectives~ai-6","moduleId":"hypothesis-objectives","stem":"In the context of research design, how does the FINER criteria relate to hypothesis formulation?","options":[{"id":"a","text":"It provides a framework for writing hypotheses"},{"id":"b","text":"It defines the statistical methods to be used"},{"id":"c","text":"It outlines the ethical considerations of the study"},{"id":"d","text":"It specifies the sample size required"}],"answerId":"a","explanation":"The FINER criteria help ensure that the research question and resulting hypotheses are feasible, interesting, novel, ethical, and relevant.","kind":"integration","linkedModuleIds":["research-question-finer-pico"],"origin":"ai"},{"id":"hypothesis-objectives~ai-7","moduleId":"hypothesis-objectives","stem":"How can the PICO framework assist in developing a hypothesis?","options":[{"id":"a","text":"It helps in selecting the statistical analysis"},{"id":"b","text":"It clarifies the population, intervention, comparison, and outcome for hypothesis testing"},{"id":"c","text":"It determines the sample size needed for the study"},{"id":"d","text":"It outlines the ethical considerations of the research"}],"answerId":"b","explanation":"The PICO framework aids in structuring the research question, which in turn informs the development of a clear and testable hypothesis.","kind":"integration","linkedModuleIds":["research-question-finer-pico"],"origin":"ai"}],"literature-review-purpose-search":[{"id":"literature-review-purpose-search~ai-0","moduleId":"literature-review-purpose-search","stem":"What is the primary purpose of conducting a literature review in research?","options":[{"id":"a","text":"To justify the research question"},{"id":"b","text":"To collect data"},{"id":"c","text":"To conduct experiments"},{"id":"d","text":"To publish findings"}],"answerId":"a","explanation":"The primary purpose of a literature review is to identify gaps in existing knowledge, which justifies the research question.","kind":"recall","origin":"ai"},{"id":"literature-review-purpose-search~ai-1","moduleId":"literature-review-purpose-search","stem":"Which of the following is considered a primary source in research?","options":[{"id":"a","text":"Systematic review"},{"id":"b","text":"Textbook"},{"id":"c","text":"Original research article"},{"id":"d","text":"Encyclopedia entry"}],"answerId":"c","explanation":"An original research article is classified as a primary source as it presents new data or findings.","kind":"recall","origin":"ai"},{"id":"literature-review-purpose-search~ai-2","moduleId":"literature-review-purpose-search","stem":"What does the Boolean operator 'AND' do in a search strategy?","options":[{"id":"a","text":"Broadens the search"},{"id":"b","text":"Narrows the search"},{"id":"c","text":"Excludes terms"},{"id":"d","text":"Combines all terms"}],"answerId":"b","explanation":"'AND' narrows the search by requiring all specified terms to be present in the results.","kind":"mechanism","origin":"ai"},{"id":"literature-review-purpose-search~ai-3","moduleId":"literature-review-purpose-search","stem":"Which database is considered the gold standard for systematic reviews?","options":[{"id":"a","text":"PubMed"},{"id":"b","text":"Cochrane Library"},{"id":"c","text":"Scopus"},{"id":"d","text":"Google Scholar"}],"answerId":"b","explanation":"The Cochrane Library is recognized as the gold standard for systematic reviews in healthcare.","kind":"recall","origin":"ai"},{"id":"literature-review-purpose-search~ai-4","moduleId":"literature-review-purpose-search","stem":"Using 'OR' in a search strategy will result in what effect?","options":[{"id":"a","text":"Fewer, more relevant results"},{"id":"b","text":"More, broader results"},{"id":"c","text":"No change in results"},{"id":"d","text":"Only exclusive terms"}],"answerId":"b","explanation":"'OR' broadens the search by including results that contain any of the specified terms.","kind":"trap","origin":"ai"},{"id":"literature-review-purpose-search~ai-5","moduleId":"literature-review-purpose-search","stem":"How can Boolean logic enhance the search strategy for a literature review?","options":[{"id":"a","text":"By limiting the number of sources"},{"id":"b","text":"By increasing specificity"},{"id":"c","text":"By combining multiple search terms effectively"},{"id":"d","text":"By excluding irrelevant studies"}],"answerId":"c","explanation":"Boolean logic allows for effective combination of search terms, enhancing the search strategy's comprehensiveness.","kind":"mechanism","origin":"ai"},{"id":"literature-review-purpose-search~ai-6","moduleId":"literature-review-purpose-search","stem":"In what way can literature reviews inform the methodology of a new study?","options":[{"id":"a","text":"By providing a list of authors"},{"id":"b","text":"By identifying gaps in existing research"},{"id":"c","text":"By suggesting statistical software"},{"id":"d","text":"By detailing ethical considerations"}],"answerId":"b","explanation":"Literature reviews inform methodology by identifying gaps that guide the design and tools used in new research.","kind":"integration","linkedModuleIds":["citation-synthesis-conceptual-framework"],"origin":"ai"},{"id":"literature-review-purpose-search~ai-7","moduleId":"literature-review-purpose-search","stem":"How can understanding source hierarchy assist in evaluating research quality?","options":[{"id":"a","text":"By prioritizing primary sources over tertiary sources"},{"id":"b","text":"By ensuring all sources are equally valid"},{"id":"c","text":"By focusing only on secondary sources"},{"id":"d","text":"By disregarding the publication date"}],"answerId":"a","explanation":"Understanding source hierarchy helps prioritize primary sources, which are closer to original data and generally more reliable.","kind":"integration","linkedModuleIds":["antihypertensive-overview"],"origin":"ai"}],"publication-types-imrad":[{"id":"publication-types-imrad~ai-0","moduleId":"publication-types-imrad","stem":"What is the primary purpose of publishing original research articles?","options":[{"id":"a","text":"To provide opinions on existing literature"},{"id":"b","text":"To report the authors’ own empirical study"},{"id":"c","text":"To summarize findings from multiple studies"},{"id":"d","text":"To generate hypotheses from case studies"}],"answerId":"b","explanation":"Original research articles report the authors' own empirical studies and are considered primary sources.","kind":"recall","origin":"ai"},{"id":"publication-types-imrad~ai-1","moduleId":"publication-types-imrad","stem":"In the IMRaD structure, where should interpretation of results be placed?","options":[{"id":"a","text":"In the Introduction"},{"id":"b","text":"In the Methods"},{"id":"c","text":"In the Results"},{"id":"d","text":"In the Discussion"}],"answerId":"d","explanation":"Interpretation, implications, and limitations belong in the Discussion section, not in the Results.","kind":"trap","origin":"ai"},{"id":"publication-types-imrad~ai-2","moduleId":"publication-types-imrad","stem":"Which type of publication provides a rigorous, reproducible methodology to evaluate existing literature?","options":[{"id":"a","text":"Narrative review"},{"id":"b","text":"Systematic review"},{"id":"c","text":"Case report"},{"id":"d","text":"Editorial"}],"answerId":"b","explanation":"A systematic review employs a rigorous methodology to appraise all relevant studies, often culminating in a meta-analysis.","kind":"recall","origin":"ai"},{"id":"publication-types-imrad~ai-3","moduleId":"publication-types-imrad","stem":"What is the main characteristic of a case report?","options":[{"id":"a","text":"It summarizes multiple studies"},{"id":"b","text":"It generates hypotheses from a single patient"},{"id":"c","text":"It provides statistical analysis of findings"},{"id":"d","text":"It critiques existing literature"}],"answerId":"b","explanation":"A case report focuses on a single patient and is considered hypothesis-generating, but low on the evidence hierarchy.","kind":"recall","origin":"ai"},{"id":"publication-types-imrad~ai-4","moduleId":"publication-types-imrad","stem":"Which section of an original research article contains only findings without interpretation?","options":[{"id":"a","text":"Introduction"},{"id":"b","text":"Methods"},{"id":"c","text":"Results"},{"id":"d","text":"Discussion"}],"answerId":"c","explanation":"The Results section presents findings only, while interpretation is reserved for the Discussion.","kind":"recall","origin":"ai"},{"id":"publication-types-imrad~ai-5","moduleId":"publication-types-imrad","stem":"How does a systematic review differ from a narrative review?","options":[{"id":"a","text":"It is less rigorous"},{"id":"b","text":"It includes expert opinions"},{"id":"c","text":"It uses statistical pooling"},{"id":"d","text":"It focuses on a single case"}],"answerId":"c","explanation":"A systematic review utilizes statistical pooling to combine results from multiple studies, making it more rigorous than a narrative review.","kind":"integration","linkedModuleIds":["peer-review-journal-metrics"],"origin":"ai"},{"id":"publication-types-imrad~ai-6","moduleId":"publication-types-imrad","stem":"What is a common error when writing the Results section of a research article?","options":[{"id":"a","text":"Including a detailed methodology"},{"id":"b","text":"Summarizing previous literature"},{"id":"c","text":"Mixing interpretation with findings"},{"id":"d","text":"Providing a clear conclusion"}],"answerId":"c","explanation":"A classic error is mixing interpretation into the Results section, which should only state findings.","kind":"trap","origin":"ai"},{"id":"publication-types-imrad~ai-7","moduleId":"publication-types-imrad","stem":"What is the primary focus of an editorial in a scientific journal?","options":[{"id":"a","text":"To report original research"},{"id":"b","text":"To provide a systematic review"},{"id":"c","text":"To offer expert opinion or commentary"},{"id":"d","text":"To present statistical analysis"}],"answerId":"c","explanation":"An editorial typically presents expert opinions or commentary rather than original data.","kind":"recall","origin":"ai"},{"id":"publication-types-imrad~ai-8","moduleId":"publication-types-imrad","stem":"What type of publication is considered the lowest on the evidence hierarchy?","options":[{"id":"a","text":"Systematic review"},{"id":"b","text":"Original research article"},{"id":"c","text":"Case report"},{"id":"d","text":"Review article"}],"answerId":"c","explanation":"Case reports are low on the evidence hierarchy as they are based on single patient observations.","kind":"recall","origin":"ai"}],"variables-confounding-bias":[{"id":"variables-confounding-bias~ai-0","moduleId":"variables-confounding-bias","stem":"Which of the following best defines a confounder?","options":[{"id":"a","text":"A variable that lies on the causal pathway between exposure and outcome"},{"id":"b","text":"A variable that is associated with both exposure and outcome but is not a risk factor"},{"id":"c","text":"A variable that is associated with the exposure, an independent risk factor for the outcome, and not on the causal pathway"},{"id":"d","text":"A variable that modifies the effect of the exposure on the outcome"}],"answerId":"c","explanation":"A confounder is defined as a variable that meets all three criteria: associated with exposure, an independent risk factor for the outcome, and not on the causal pathway.","kind":"recall","origin":"ai"},{"id":"variables-confounding-bias~ai-1","moduleId":"variables-confounding-bias","stem":"What is the primary purpose of randomization in a clinical trial?","options":[{"id":"a","text":"To ensure equal sample sizes in treatment groups"},{"id":"b","text":"To balance known and unknown confounders across groups"},{"id":"c","text":"To eliminate the need for statistical analysis"},{"id":"d","text":"To control for measurement bias"}],"answerId":"b","explanation":"Randomization helps to balance both known and unknown confounders, making it a powerful method for controlling bias in clinical trials.","kind":"mechanism","origin":"ai"},{"id":"variables-confounding-bias~ai-2","moduleId":"variables-confounding-bias","stem":"In a study examining the effect of exercise on weight loss, which of the following would be considered a mediator?","options":[{"id":"a","text":"Caloric intake"},{"id":"b","text":"Age"},{"id":"c","text":"Metabolism rate"},{"id":"d","text":"Exercise frequency"}],"answerId":"c","explanation":"Metabolism rate is a mediator as it lies on the pathway between exercise and weight loss, explaining how exercise leads to weight loss.","kind":"recall","origin":"ai"},{"id":"variables-confounding-bias~ai-3","moduleId":"variables-confounding-bias","stem":"Which of the following statements about effect modifiers is true?","options":[{"id":"a","text":"They should be adjusted for in multivariable regression"},{"id":"b","text":"They change the strength or direction of the effect of exposure on outcome"},{"id":"c","text":"They are always confounders"},{"id":"d","text":"They are irrelevant in subgroup analyses"}],"answerId":"b","explanation":"Effect modifiers change the strength or direction of the effect of the exposure on the outcome and should be reported in subgroup analyses.","kind":"clinical","origin":"ai"},{"id":"variables-confounding-bias~ai-4","moduleId":"variables-confounding-bias","stem":"A researcher finds that coffee consumption is associated with lung cancer risk, but this association disappears when controlling for smoking. What does this suggest about smoking?","options":[{"id":"a","text":"Smoking is a mediator in the coffee-lung cancer relationship"},{"id":"b","text":"Smoking is a confounder in the coffee-lung cancer relationship"},{"id":"c","text":"Coffee is not a risk factor for lung cancer"},{"id":"d","text":"Lung cancer is not affected by coffee consumption"}],"answerId":"b","explanation":"The disappearance of the association after controlling for smoking suggests that smoking is a confounder in the relationship between coffee consumption and lung cancer risk.","kind":"trap","origin":"ai"},{"id":"variables-confounding-bias~ai-5","moduleId":"variables-confounding-bias","stem":"How should a researcher handle a variable that is a mediator in their analysis?","options":[{"id":"a","text":"Adjust for it to isolate the total effect"},{"id":"b","text":"Do not adjust for it to capture the total effect"},{"id":"c","text":"Include it as a confounder in the model"},{"id":"d","text":"Ignore it as it does not affect the outcome"}],"answerId":"b","explanation":"A mediator should not be adjusted for if the researcher wants to capture the total effect of the exposure on the outcome.","kind":"trap","origin":"ai"},{"id":"variables-confounding-bias~ai-6","moduleId":"variables-confounding-bias","stem":"In a study examining the effect of a new drug on blood pressure, age is found to modify the drug's effect. What should the researchers do?","options":[{"id":"a","text":"Ignore age in their analysis"},{"id":"b","text":"Report the results separately for different age groups"},{"id":"c","text":"Adjust for age as a confounder"},{"id":"d","text":"Include age as a covariate in a single analysis"}],"answerId":"b","explanation":"When age modifies the drug's effect, researchers should report the results separately for different age groups to accurately reflect the effect modification.","kind":"integration","linkedModuleIds":["study-designs-hierarchy"],"origin":"ai"},{"id":"variables-confounding-bias~ai-7","moduleId":"variables-confounding-bias","stem":"When designing a study to assess the impact of diet on heart disease, which method is best for controlling unknown confounders?","options":[{"id":"a","text":"Stratification"},{"id":"b","text":"Multivariable regression"},{"id":"c","text":"Randomization"},{"id":"d","text":"Matching"}],"answerId":"c","explanation":"Randomization is the best method for controlling unknown confounders as it balances both known and unknown variables across groups.","kind":"integration","linkedModuleIds":["sampling-methods"],"origin":"ai"}],"inferential-stats-p-value":[{"id":"inferential-stats-p-value~ai-0","moduleId":"inferential-stats-p-value","stem":"What does a p-value of 0.03 indicate?","options":[{"id":"a","text":"There is a 3% chance the null hypothesis is true."},{"id":"b","text":"If the null hypothesis is true, there is a 3% chance of obtaining data this extreme."},{"id":"c","text":"The result is statistically significant at the 0.05 level."},{"id":"d","text":"The effect size is small."}],"answerId":"b","explanation":"A p-value of 0.03 means that if the null hypothesis were true, there is a 3% chance of observing data as extreme as what was obtained.","kind":"trap","origin":"ai"},{"id":"inferential-stats-p-value~ai-1","moduleId":"inferential-stats-p-value","stem":"Which statistical test is appropriate for comparing the means of three independent groups?","options":[{"id":"a","text":"t-test"},{"id":"b","text":"ANOVA"},{"id":"c","text":"Chi-square test"},{"id":"d","text":"Mann-Whitney U test"}],"answerId":"b","explanation":"ANOVA is used to compare the means of three or more independent groups.","kind":"recall","origin":"ai"},{"id":"inferential-stats-p-value~ai-2","moduleId":"inferential-stats-p-value","stem":"What is the effect of increasing sample size on the confidence interval?","options":[{"id":"a","text":"Wider confidence interval"},{"id":"b","text":"Narrower confidence interval"},{"id":"c","text":"No effect on confidence interval"},{"id":"d","text":"Confidence interval becomes irrelevant"}],"answerId":"b","explanation":"Increasing the sample size decreases the standard error, resulting in a narrower confidence interval.","kind":"mechanism","origin":"ai"},{"id":"inferential-stats-p-value~ai-3","moduleId":"inferential-stats-p-value","stem":"A 95% confidence interval for a population mean is calculated as 10 ± 2. What does this imply?","options":[{"id":"a","text":"The true mean is definitely between 8 and 12."},{"id":"b","text":"There is a 95% chance the true mean lies between 8 and 12."},{"id":"c","text":"If we sampled repeatedly, 95% of the intervals would contain the true mean."},{"id":"d","text":"The sample mean is 10."}],"answerId":"c","explanation":"The interpretation of a 95% confidence interval is that if we were to take many samples, 95% of those intervals would contain the true population mean.","kind":"clinical","origin":"ai"},{"id":"inferential-stats-p-value~ai-4","moduleId":"inferential-stats-p-value","stem":"In a study, a p-value of 0.04 was obtained. What can be concluded?","options":[{"id":"a","text":"The null hypothesis is definitely false."},{"id":"b","text":"There is strong evidence against the null hypothesis."},{"id":"c","text":"The study has a low power."},{"id":"d","text":"The sample size is too small."}],"answerId":"b","explanation":"A p-value of 0.04 indicates that there is statistically significant evidence against the null hypothesis at the 0.05 level.","kind":"clinical","origin":"ai"},{"id":"inferential-stats-p-value~ai-5","moduleId":"inferential-stats-p-value","stem":"Which of the following is a non-parametric test used when data do not meet normality assumptions?","options":[{"id":"a","text":"t-test"},{"id":"b","text":"ANOVA"},{"id":"c","text":"Mann-Whitney U test"},{"id":"d","text":"Pearson correlation"}],"answerId":"c","explanation":"The Mann-Whitney U test is a non-parametric test used for comparing two independent groups when the normality assumption is violated.","kind":"recall","origin":"ai"},{"id":"inferential-stats-p-value~ai-6","moduleId":"inferential-stats-p-value","stem":"How does the concept of effect size relate to confidence intervals?","options":[{"id":"a","text":"Effect size is irrelevant to confidence intervals."},{"id":"b","text":"A confidence interval can provide an estimate of effect size."},{"id":"c","text":"Effect size is always larger than the confidence interval."},{"id":"d","text":"Confidence intervals cannot be calculated without effect size."}],"answerId":"b","explanation":"Confidence intervals can provide an estimate of effect size by indicating the range of values that the true effect size may take.","kind":"integration","linkedModuleIds":["data-types-descriptive-stats"],"origin":"ai"},{"id":"inferential-stats-p-value~ai-7","moduleId":"inferential-stats-p-value","stem":"When interpreting results from a clinical trial, how can p-values inform treatment decisions?","options":[{"id":"a","text":"They indicate the probability that the treatment is effective."},{"id":"b","text":"They help assess the strength of evidence against the null hypothesis."},{"id":"c","text":"They provide the exact effect size of the treatment."},{"id":"d","text":"They replace the need for clinical judgment."}],"answerId":"b","explanation":"P-values help assess the strength of evidence against the null hypothesis, guiding treatment decisions in clinical practice.","kind":"integration","linkedModuleIds":["antiarrhythmic-drugs"],"origin":"ai"}],"outbreak-investigation":[{"id":"outbreak-investigation~ai-0","moduleId":"outbreak-investigation","stem":"What is the correct definition of an outbreak?","options":[{"id":"a","text":"A single case of a disease"},{"id":"b","text":"Cases clearly in excess of the expected baseline"},{"id":"c","text":"An epidemic across countries"},{"id":"d","text":"A continuous common source of infection"}],"answerId":"b","explanation":"An outbreak is defined as cases clearly in excess of the expected baseline level in an area.","kind":"recall","origin":"ai"},{"id":"outbreak-investigation~ai-1","moduleId":"outbreak-investigation","stem":"Which step comes first in an outbreak investigation?","options":[{"id":"a","text":"Establish a case definition"},{"id":"b","text":"Verify the diagnosis"},{"id":"c","text":"Implement control measures"},{"id":"d","text":"Find cases and count"}],"answerId":"b","explanation":"The first step in an outbreak investigation is to verify the diagnosis.","kind":"recall","origin":"ai"},{"id":"outbreak-investigation~ai-2","moduleId":"outbreak-investigation","stem":"What does a single sharp peak in an epidemic curve indicate?","options":[{"id":"a","text":"Propagated outbreak"},{"id":"b","text":"Point-source outbreak"},{"id":"c","text":"Continuous common source"},{"id":"d","text":"Endemic situation"}],"answerId":"b","explanation":"A single sharp peak within one incubation period indicates a point-source outbreak.","kind":"recall","origin":"ai"},{"id":"outbreak-investigation~ai-3","moduleId":"outbreak-investigation","stem":"When should control measures be implemented during an outbreak investigation?","options":[{"id":"a","text":"After the analytic study is completed"},{"id":"b","text":"As soon as a plausible source is identified"},{"id":"c","text":"Only if the outbreak is widespread"},{"id":"d","text":"Only after finding all cases"}],"answerId":"b","explanation":"Control measures can and should begin as soon as a plausible source is identified to prevent further cases.","kind":"trap","origin":"ai"},{"id":"outbreak-investigation~ai-4","moduleId":"outbreak-investigation","stem":"What is the role of vinegar in the management of box jellyfish stings?","options":[{"id":"a","text":"Neutralizes venom"},{"id":"b","text":"Inactivates undischarged nematocysts"},{"id":"c","text":"Reduces pain immediately"},{"id":"d","text":"Prevents further stings"}],"answerId":"b","explanation":"Vinegar inactivates undischarged nematocysts, which is crucial in the management of box jellyfish stings.","kind":"mechanism","origin":"ai"},{"id":"outbreak-investigation~ai-5","moduleId":"outbreak-investigation","stem":"How is the attack rate calculated during an outbreak investigation?","options":[{"id":"a","text":"Total cases divided by total population"},{"id":"b","text":"Number of cases divided by population at risk"},{"id":"c","text":"Number of deaths divided by cases"},{"id":"d","text":"Total cases divided by cases in the control group"}],"answerId":"b","explanation":"The attack rate is calculated as the number of cases divided by the population at risk.","kind":"recall","origin":"ai"},{"id":"outbreak-investigation~ai-6","moduleId":"outbreak-investigation","stem":"How can understanding the oxyhaemoglobin dissociation curve aid in outbreak investigations?","options":[{"id":"a","text":"It helps identify the source of infection"},{"id":"b","text":"It explains the physiological response to hypoxia"},{"id":"c","text":"It assists in determining the incubation period"},{"id":"d","text":"It provides insights into the body's response to toxins"}],"answerId":"d","explanation":"Understanding the oxyhaemoglobin dissociation curve can provide insights into the body's response to toxins, which is relevant in cases of toxic exposure during outbreaks.","kind":"integration","linkedModuleIds":["oxygen-transport-dissociation-curve"],"origin":"ai"},{"id":"outbreak-investigation~ai-7","moduleId":"outbreak-investigation","stem":"What connection exists between the identification of bacterial pathogens and outbreak investigations?","options":[{"id":"a","text":"Bacterial identification is irrelevant to outbreaks"},{"id":"b","text":"Bacterial physiology helps in understanding transmission"},{"id":"c","text":"Bacterial growth rates determine outbreak duration"},{"id":"d","text":"Bacterial identification is only useful post-outbreak"}],"answerId":"b","explanation":"Understanding bacterial physiology and growth is crucial for identifying pathogens involved in outbreaks and understanding their transmission.","kind":"integration","linkedModuleIds":["bacterial-physiology-growth-identification"],"origin":"ai"}],"t-cell-activation":[{"id":"t-cell-activation~ai-0","moduleId":"t-cell-activation","stem":"What is the primary consequence of TCR engagement with antigen without co-stimulation?","options":[{"id":"a","text":"Full activation of T cells"},{"id":"b","text":"Clonal expansion"},{"id":"c","text":"Anergy or tolerance"},{"id":"d","text":"Cytokine release"}],"answerId":"c","explanation":"TCR engagement without co-stimulation leads to anergy or tolerance, preventing inappropriate activation.","kind":"trap","origin":"ai"},{"id":"t-cell-activation~ai-1","moduleId":"t-cell-activation","stem":"Which molecule on T cells binds to B7 on antigen-presenting cells to provide co-stimulatory signal?","options":[{"id":"a","text":"CD3"},{"id":"b","text":"CD28"},{"id":"c","text":"CTLA-4"},{"id":"d","text":"PD-1"}],"answerId":"b","explanation":"CD28 on T cells binds to B7 (CD80/CD86) on APCs to provide the necessary second signal for activation.","kind":"recall","origin":"ai"},{"id":"t-cell-activation~ai-2","moduleId":"t-cell-activation","stem":"What is the role of IL-2 in T-cell activation?","options":[{"id":"a","text":"Inhibits T-cell activation"},{"id":"b","text":"Drives clonal proliferation"},{"id":"c","text":"Provides co-stimulatory signal"},{"id":"d","text":"Promotes anergy"}],"answerId":"b","explanation":"IL-2 is crucial for driving the clonal proliferation of activated T cells.","kind":"mechanism","origin":"ai"},{"id":"t-cell-activation~ai-3","moduleId":"t-cell-activation","stem":"Which of the following statements about CTLA-4 is true?","options":[{"id":"a","text":"It enhances T-cell activation"},{"id":"b","text":"It competes with CD28 for B7 binding"},{"id":"c","text":"It is expressed on naive T cells"},{"id":"d","text":"It promotes cytokine release"}],"answerId":"b","explanation":"CTLA-4 competes with CD28 for B7 binding, serving as an inhibitory checkpoint to dampen T-cell responses.","kind":"clinical","origin":"ai"},{"id":"t-cell-activation~ai-4","moduleId":"t-cell-activation","stem":"In the context of immunotherapy, which mechanism is targeted by anti-PD-1 therapies?","options":[{"id":"a","text":"Enhancing co-stimulation"},{"id":"b","text":"Blocking inhibitory checkpoints"},{"id":"c","text":"Promoting anergy"},{"id":"d","text":"Stimulating IL-2 production"}],"answerId":"b","explanation":"Anti-PD-1 therapies block inhibitory checkpoints, enhancing T-cell activation against tumors.","kind":"integration","linkedModuleIds":["immunotherapy-modulation"],"origin":"ai"},{"id":"t-cell-activation~ai-5","moduleId":"t-cell-activation","stem":"Which of the following best describes the relationship between T-cell activation and self-tolerance mechanisms?","options":[{"id":"a","text":"T-cell activation requires only antigen recognition"},{"id":"b","text":"Self-tolerance is achieved through co-stimulation"},{"id":"c","text":"Anergy prevents T-cell activation in the absence of co-stimulation"},{"id":"d","text":"All T cells are activated in the presence of antigen"}],"answerId":"c","explanation":"Anergy is a mechanism of self-tolerance that occurs when T cells recognize antigen without the necessary co-stimulation.","kind":"integration","linkedModuleIds":["tolerance-autoimmunity-mechanisms"],"origin":"ai"}],"innate-barriers-prr":[{"id":"innate-barriers-prr~ai-0","moduleId":"innate-barriers-prr","stem":"Which of the following is a characteristic of Toll-like receptor 4 (TLR4)?","options":[{"id":"a","text":"It recognizes Gram-positive bacteria"},{"id":"b","text":"It senses viral RNA"},{"id":"c","text":"It detects bacterial lipopolysaccharide"},{"id":"d","text":"It is located exclusively in the cytoplasm"}],"answerId":"c","explanation":"TLR4 is a surface PRR that specifically recognizes lipopolysaccharide (LPS) from Gram-negative bacteria.","kind":"recall","origin":"ai"},{"id":"innate-barriers-prr~ai-1","moduleId":"innate-barriers-prr","stem":"What is the primary signaling outcome of PRR engagement?","options":[{"id":"a","text":"Activation of adaptive immunity"},{"id":"b","text":"Inhibition of inflammation"},{"id":"c","text":"Activation of NF-κB and inflammatory cytokines"},{"id":"d","text":"Direct destruction of pathogens"}],"answerId":"c","explanation":"PRR engagement primarily leads to the activation of NF-κB, resulting in the production of inflammatory cytokines.","kind":"mechanism","origin":"ai"},{"id":"innate-barriers-prr~ai-2","moduleId":"innate-barriers-prr","stem":"Which of the following findings is indicative of acute inflammation?","options":[{"id":"a","text":"Increased antibody production"},{"id":"b","text":"Fever and elevated CRP levels"},{"id":"c","text":"Decreased neutrophil count"},{"id":"d","text":"Chronic tissue remodeling"}],"answerId":"b","explanation":"Fever and elevated CRP levels are hallmark signs of the acute-phase response during acute inflammation.","kind":"recall","origin":"ai"},{"id":"innate-barriers-prr~ai-3","moduleId":"innate-barriers-prr","stem":"What is the role of neutrophils in acute inflammation?","options":[{"id":"a","text":"They produce antibodies"},{"id":"b","text":"They facilitate tissue repair"},{"id":"c","text":"They are the first responders to infection"},{"id":"d","text":"They directly kill all pathogens"}],"answerId":"c","explanation":"Neutrophils are the first responders to sites of infection and play a crucial role in the innate immune response.","kind":"clinical","origin":"ai"},{"id":"innate-barriers-prr~ai-4","moduleId":"innate-barriers-prr","stem":"Which statement correctly describes the specificity of pattern-recognition receptors (PRRs)?","options":[{"id":"a","text":"PRRs are highly specific and clonally rearranged"},{"id":"b","text":"PRRs recognize conserved patterns shared by many pathogens"},{"id":"c","text":"PRRs are only found in adaptive immunity"},{"id":"d","text":"PRRs can mutate to recognize new antigens"}],"answerId":"b","explanation":"PRRs are germline-encoded and recognize conserved patterns (PAMPs), not unique antigens like antibodies.","kind":"trap","origin":"ai"},{"id":"innate-barriers-prr~ai-5","moduleId":"innate-barriers-prr","stem":"How does the innate immune response relate to renal defense mechanisms?","options":[{"id":"a","text":"Both rely on adaptive immunity for pathogen recognition"},{"id":"b","text":"Innate immune cells in the kidney respond to pathogens"},{"id":"c","text":"Renal defense mechanisms are solely chemical barriers"},{"id":"d","text":"Both systems utilize the same types of antibodies"}],"answerId":"b","explanation":"The innate immune response includes immune cells in the kidneys that respond to pathogens, enhancing renal defense mechanisms.","kind":"integration","linkedModuleIds":["renal-defense-mechanisms"],"origin":"ai"},{"id":"innate-barriers-prr~ai-6","moduleId":"innate-barriers-prr","stem":"What is the connection between PRRs and the skin immune system?","options":[{"id":"a","text":"PRRs are only present in the skin"},{"id":"b","text":"Skin PRRs detect pathogens and initiate inflammation"},{"id":"c","text":"The skin immune system does not involve PRRs"},{"id":"d","text":"PRRs are exclusively found in the bloodstream"}],"answerId":"b","explanation":"PRRs in the skin detect pathogens and initiate inflammatory responses, playing a crucial role in skin immunity.","kind":"integration","linkedModuleIds":["skin-immune-system-cells"],"origin":"ai"}],"antibody-classes-functions":[{"id":"antibody-classes-functions~ai-0","moduleId":"antibody-classes-functions","stem":"Which immunoglobulin is the primary antibody produced during the initial stages of a primary immune response?","options":[{"id":"a","text":"IgG"},{"id":"b","text":"IgM"},{"id":"c","text":"IgA"},{"id":"d","text":"IgE"}],"answerId":"b","explanation":"IgM is the first antibody produced in a primary immune response due to its pentameric structure, allowing for effective complement activation.","kind":"recall","origin":"ai"},{"id":"antibody-classes-functions~ai-1","moduleId":"antibody-classes-functions","stem":"What is the main function of IgG antibodies?","options":[{"id":"a","text":"Agglutination"},{"id":"b","text":"Opsonization"},{"id":"c","text":"Complement activation"},{"id":"d","text":"Neutralization"}],"answerId":"c","explanation":"IgG antibodies are excellent at complement activation, particularly in the classical pathway.","kind":"mechanism","origin":"ai"},{"id":"antibody-classes-functions~ai-2","moduleId":"antibody-classes-functions","stem":"Which immunoglobulin is primarily found in breast milk and provides passive immunity to newborns?","options":[{"id":"a","text":"IgM"},{"id":"b","text":"IgA"},{"id":"c","text":"IgE"},{"id":"d","text":"IgG"}],"answerId":"b","explanation":"IgA is the main antibody in breast milk, where it exists as a dimer and helps protect the infant's mucosal surfaces.","kind":"recall","origin":"ai"},{"id":"antibody-classes-functions~ai-3","moduleId":"antibody-classes-functions","stem":"A patient presents with anaphylaxis after exposure to peanuts. Which immunoglobulin is primarily responsible for this reaction?","options":[{"id":"a","text":"IgG"},{"id":"b","text":"IgM"},{"id":"c","text":"IgA"},{"id":"d","text":"IgE"}],"answerId":"d","explanation":"IgE antibodies bind to allergens and trigger degranulation of mast cells, leading to anaphylaxis.","kind":"clinical","origin":"ai"},{"id":"antibody-classes-functions~ai-4","moduleId":"antibody-classes-functions","stem":"A laboratory test shows high levels of IgG with low levels of IgM. What does this indicate?","options":[{"id":"a","text":"Primary immune response"},{"id":"b","text":"Secondary immune response"},{"id":"c","text":"Acute infection"},{"id":"d","text":"Chronic infection"}],"answerId":"b","explanation":"High IgG with low IgM suggests a secondary immune response, indicating past infection and class switching.","kind":"recall","origin":"ai"},{"id":"antibody-classes-functions~ai-5","moduleId":"antibody-classes-functions","stem":"Which immunoglobulin class is best known for its role in opsonization?","options":[{"id":"a","text":"IgA"},{"id":"b","text":"IgM"},{"id":"c","text":"IgE"},{"id":"d","text":"IgG"}],"answerId":"d","explanation":"IgG is the primary antibody involved in opsonization, marking pathogens for phagocytosis.","kind":"trap","origin":"ai"},{"id":"antibody-classes-functions~ai-6","moduleId":"antibody-classes-functions","stem":"How does class switching occur in B cells during the germinal center reaction?","options":[{"id":"a","text":"By changing the antigen specificity"},{"id":"b","text":"By altering the antibody isotype"},{"id":"c","text":"By increasing antibody affinity"},{"id":"d","text":"By enhancing memory B cell formation"}],"answerId":"b","explanation":"Class switching allows B cells to change the antibody isotype while maintaining specificity for the same antigen.","kind":"integration","linkedModuleIds":["germinal-center-antibody-response"],"origin":"ai"},{"id":"antibody-classes-functions~ai-7","moduleId":"antibody-classes-functions","stem":"What is the role of T helper cells in the activation of B cells during the humoral response?","options":[{"id":"a","text":"Directly produce antibodies"},{"id":"b","text":"Provide signals for class switching"},{"id":"c","text":"Enhance phagocytosis"},{"id":"d","text":"Activate cytotoxic T cells"}],"answerId":"b","explanation":"T helper cells provide necessary signals (cytokines) for B cell activation and class switching.","kind":"integration","linkedModuleIds":["humoral-response-b-activation"],"origin":"ai"}],"antibody-structure":[{"id":"antibody-structure~ai-0","moduleId":"antibody-structure","stem":"What is the basic structural unit of an antibody?","options":[{"id":"a","text":"One heavy chain"},{"id":"b","text":"Two heavy chains and two light chains"},{"id":"c","text":"One light chain"},{"id":"d","text":"Two light chains"}],"answerId":"b","explanation":"An antibody is composed of two identical heavy chains and two identical light chains, forming a Y-shaped structure.","kind":"recall","origin":"ai"},{"id":"antibody-structure~ai-1","moduleId":"antibody-structure","stem":"Which part of the antibody is responsible for binding to antigens?","options":[{"id":"a","text":"Fc region"},{"id":"b","text":"Hinge region"},{"id":"c","text":"Fab region"},{"id":"d","text":"Constant region"}],"answerId":"c","explanation":"The Fab region, which consists of the variable regions of the heavy and light chains, is responsible for antigen binding.","kind":"mechanism","origin":"ai"},{"id":"antibody-structure~ai-2","moduleId":"antibody-structure","stem":"What determines the class of an antibody?","options":[{"id":"a","text":"The light chain type"},{"id":"b","text":"The heavy-chain constant region"},{"id":"c","text":"The variable region"},{"id":"d","text":"The hinge region"}],"answerId":"b","explanation":"The class of an antibody is determined by the heavy-chain constant region (isotype), while the light chain type does not define the class.","kind":"trap","origin":"ai"},{"id":"antibody-structure~ai-3","moduleId":"antibody-structure","stem":"Which mechanism generates antibody diversity?","options":[{"id":"a","text":"Somatic hypermutation only"},{"id":"b","text":"V(D)J recombination only"},{"id":"c","text":"Junctional diversity only"},{"id":"d","text":"V(D)J recombination plus junctional diversity and somatic hypermutation"}],"answerId":"d","explanation":"Antibody diversity is generated by V(D)J recombination, junctional diversity, and somatic hypermutation.","kind":"mechanism","origin":"ai"},{"id":"antibody-structure~ai-4","moduleId":"antibody-structure","stem":"In which part of the antibody is the antigen-binding site located?","options":[{"id":"a","text":"Fc region"},{"id":"b","text":"Hinge region"},{"id":"c","text":"Fab region"},{"id":"d","text":"Constant region"}],"answerId":"c","explanation":"The antigen-binding site is located in the Fab region, formed by the variable regions of the heavy and light chains.","kind":"recall","origin":"ai"},{"id":"antibody-structure~ai-5","moduleId":"antibody-structure","stem":"How does the Fc region of an antibody function?","options":[{"id":"a","text":"Binds to antigens"},{"id":"b","text":"Determines the antibody's isotype"},{"id":"c","text":"Mediates complement activation"},{"id":"d","text":"Both B and C"}],"answerId":"d","explanation":"The Fc region mediates effector functions such as complement activation and determines the antibody's isotype.","kind":"mechanism","origin":"ai"},{"id":"antibody-structure~ai-6","moduleId":"antibody-structure","stem":"How does B-cell tolerance relate to antibody specificity?","options":[{"id":"a","text":"It eliminates all B-cells"},{"id":"b","text":"It ensures only high-affinity antibodies are produced"},{"id":"c","text":"It prevents autoreactive B-cells from maturing"},{"id":"d","text":"It enhances V(D)J recombination"}],"answerId":"c","explanation":"B-cell tolerance prevents autoreactive B-cells from maturing, ensuring that only non-self-reactive antibodies are produced.","kind":"integration","linkedModuleIds":["b-cell-development-tolerance"],"origin":"ai"},{"id":"antibody-structure~ai-7","moduleId":"antibody-structure","stem":"Which aspect of antibody structure is crucial for its function in immune response?","options":[{"id":"a","text":"The light chain type"},{"id":"b","text":"The heavy-chain constant region"},{"id":"c","text":"The hinge region flexibility"},{"id":"d","text":"The number of Fab regions"}],"answerId":"b","explanation":"The heavy-chain constant region determines the antibody's class and its effector functions, which are crucial for immune response.","kind":"integration","linkedModuleIds":["antibody-classes-functions"],"origin":"ai"}],"cd4-helper-subsets":[{"id":"cd4-helper-subsets~ai-0","moduleId":"cd4-helper-subsets","stem":"Which cytokine is primarily responsible for the differentiation of naïve CD4⁺ T cells into Th1 cells?","options":[{"id":"a","text":"IL-4"},{"id":"b","text":"IL-12"},{"id":"c","text":"IL-6"},{"id":"d","text":"TGF-β"}],"answerId":"b","explanation":"IL-12 is crucial for Th1 differentiation, promoting the production of IFN-γ.","kind":"recall","origin":"ai"},{"id":"cd4-helper-subsets~ai-1","moduleId":"cd4-helper-subsets","stem":"What is the primary function of Th2 cells in the immune response?","options":[{"id":"a","text":"Activate macrophages"},{"id":"b","text":"Support B-cell class switching"},{"id":"c","text":"Recruit neutrophils"},{"id":"d","text":"Enhance cytotoxic T-cell activity"}],"answerId":"b","explanation":"Th2 cells primarily support B-cell class switching and promote IgE production.","kind":"recall","origin":"ai"},{"id":"cd4-helper-subsets~ai-2","moduleId":"cd4-helper-subsets","stem":"A patient presents with chronic mucocutaneous candidiasis. Which CD4⁺ T-cell subset is most likely defective?","options":[{"id":"a","text":"Th1"},{"id":"b","text":"Th2"},{"id":"c","text":"Th17"},{"id":"d","text":"Treg"}],"answerId":"c","explanation":"Th17 cells are crucial for recruiting neutrophils to combat extracellular fungi like Candida.","kind":"clinical","origin":"ai"},{"id":"cd4-helper-subsets~ai-3","moduleId":"cd4-helper-subsets","stem":"Which transcription factor is associated with Th2 cells?","options":[{"id":"a","text":"T-bet"},{"id":"b","text":"GATA3"},{"id":"c","text":"RORγt"},{"id":"d","text":"Bcl-6"}],"answerId":"b","explanation":"GATA3 is the master transcription factor for Th2 cell differentiation.","kind":"recall","origin":"ai"},{"id":"cd4-helper-subsets~ai-4","moduleId":"cd4-helper-subsets","stem":"What is the primary cytokine secreted by Th1 cells to activate macrophages?","options":[{"id":"a","text":"IL-4"},{"id":"b","text":"IL-5"},{"id":"c","text":"IFN-γ"},{"id":"d","text":"IL-17"}],"answerId":"c","explanation":"IFN-γ is the key cytokine produced by Th1 cells to activate macrophages.","kind":"recall","origin":"ai"},{"id":"cd4-helper-subsets~ai-5","moduleId":"cd4-helper-subsets","stem":"Which of the following statements about Th1 and Th2 cells is correct?","options":[{"id":"a","text":"Th1 cells are responsible for helminth defense."},{"id":"b","text":"Th2 cells activate macrophages against intracellular pathogens."},{"id":"c","text":"Th1 cells secrete IL-4 to promote IgE production."},{"id":"d","text":"Th1 cells are involved in defense against intracellular microbes."}],"answerId":"d","explanation":"Th1 cells are specifically involved in the defense against intracellular microbes.","kind":"trap","origin":"ai"},{"id":"cd4-helper-subsets~ai-6","moduleId":"cd4-helper-subsets","stem":"How do Th1 cells enhance the activity of CD8⁺ T cells?","options":[{"id":"a","text":"By secreting IL-4"},{"id":"b","text":"By producing IFN-γ"},{"id":"c","text":"By activating B cells"},{"id":"d","text":"By recruiting eosinophils"}],"answerId":"b","explanation":"Th1 cells produce IFN-γ, which enhances the cytotoxic activity of CD8⁺ T cells.","kind":"integration","linkedModuleIds":["cd8-ctl-nk-effectors"],"origin":"ai"},{"id":"cd4-helper-subsets~ai-7","moduleId":"cd4-helper-subsets","stem":"In the context of T-cell activation, which cytokine is crucial for Th17 differentiation?","options":[{"id":"a","text":"IL-12"},{"id":"b","text":"IL-4"},{"id":"c","text":"IL-6"},{"id":"d","text":"IFN-γ"}],"answerId":"c","explanation":"IL-6, along with TGF-β, is essential for the differentiation of Th17 cells.","kind":"integration","linkedModuleIds":["t-cell-activation"],"origin":"ai"}],"innate-nk-interferon":[{"id":"innate-nk-interferon~ai-0","moduleId":"innate-nk-interferon","stem":"What is the primary mechanism by which NK cells recognize and kill virus-infected cells?","options":[{"id":"a","text":"Increased MHC class I expression"},{"id":"b","text":"Loss of MHC class I"},{"id":"c","text":"Presence of CD16"},{"id":"d","text":"Secretion of IFN-γ"}],"answerId":"b","explanation":"NK cells identify and kill cells that have down-regulated MHC class I, a phenomenon known as 'missing self'.","kind":"mechanism","origin":"ai"},{"id":"innate-nk-interferon~ai-1","moduleId":"innate-nk-interferon","stem":"Which cytokine is primarily responsible for inducing an antiviral state in neighboring cells during a viral infection?","options":[{"id":"a","text":"IL-12"},{"id":"b","text":"IFN-γ"},{"id":"c","text":"IFN-α"},{"id":"d","text":"TNF-α"}],"answerId":"c","explanation":"Type I interferons (IFN-α/β) are key antiviral cytokines that induce an antiviral state in neighboring cells.","kind":"recall","origin":"ai"},{"id":"innate-nk-interferon~ai-2","moduleId":"innate-nk-interferon","stem":"What is the role of CD16 on NK cells?","options":[{"id":"a","text":"Binding to MHC class I"},{"id":"b","text":"Binding to IgG-coated target cells"},{"id":"c","text":"Secretion of cytokines"},{"id":"d","text":"Activation of macrophages"}],"answerId":"b","explanation":"CD16 (FcγRIII) on NK cells binds to the Fc region of IgG-coated target cells, facilitating antibody-dependent cell-mediated cytotoxicity (ADCC).","kind":"recall","origin":"ai"},{"id":"innate-nk-interferon~ai-3","moduleId":"innate-nk-interferon","stem":"Which statement correctly describes the function of NK cells?","options":[{"id":"a","text":"NK cells require prior sensitization to kill target cells"},{"id":"b","text":"NK cells are inhibited by healthy cells displaying MHC class I"},{"id":"c","text":"NK cells primarily kill cells with high levels of MHC class I"},{"id":"d","text":"NK cells only kill tumor cells"}],"answerId":"b","explanation":"NK cells are inhibited by the presence of MHC class I on healthy cells, allowing them to target cells that have lost MHC class I.","kind":"trap","origin":"ai"},{"id":"innate-nk-interferon~ai-4","moduleId":"innate-nk-interferon","stem":"In the context of skin immune responses, which innate immune cell type is primarily responsible for recognizing and responding to viral infections?","options":[{"id":"a","text":"B cells"},{"id":"b","text":"CD8 T cells"},{"id":"c","text":"NK cells"},{"id":"d","text":"Dendritic cells"}],"answerId":"c","explanation":"NK cells play a crucial role in the innate immune response to viral infections by recognizing and killing infected cells.","kind":"integration","linkedModuleIds":["skin-immune-system-cells"],"origin":"ai"},{"id":"innate-nk-interferon~ai-5","moduleId":"innate-nk-interferon","stem":"How do NK cells and CD8 cytotoxic T cells differ in their recognition of infected cells?","options":[{"id":"a","text":"NK cells require MHC class I, while CD8 T cells do not"},{"id":"b","text":"CD8 T cells kill without prior sensitization, while NK cells require it"},{"id":"c","text":"NK cells kill cells that lose MHC class I, while CD8 T cells require MHC class I"},{"id":"d","text":"Both kill cells through the same mechanism"}],"answerId":"c","explanation":"NK cells kill cells that have down-regulated MHC class I, whereas CD8 T cells require the presence of MHC class I to recognize and kill infected cells.","kind":"integration","linkedModuleIds":["cd8-ctl-nk-effectors"],"origin":"ai"}],"complement-pathways":[{"id":"complement-pathways~ai-0","moduleId":"complement-pathways","stem":"Which complement activation pathway is initiated by antibody binding to an antigen?","options":[{"id":"a","text":"Classical pathway"},{"id":"b","text":"Lectin pathway"},{"id":"c","text":"Alternative pathway"},{"id":"d","text":"C3 tickover"}],"answerId":"a","explanation":"The classical pathway is triggered when antibodies (IgM or IgG) bind to antigens, leading to complement activation.","kind":"recall","origin":"ai"},{"id":"complement-pathways~ai-1","moduleId":"complement-pathways","stem":"What is the primary role of C3 convertase in the complement system?","options":[{"id":"a","text":"Cleaves C5 to initiate MAC formation"},{"id":"b","text":"Cleaves C3 to generate opsonins"},{"id":"c","text":"Activates the lectin pathway"},{"id":"d","text":"Stabilizes C3b on microbial surfaces"}],"answerId":"b","explanation":"C3 convertase cleaves C3 into C3a and C3b, which are crucial for opsonization and further complement activation.","kind":"mechanism","origin":"ai"},{"id":"complement-pathways~ai-2","moduleId":"complement-pathways","stem":"Which of the following findings indicates activation of the lectin pathway?","options":[{"id":"a","text":"Presence of C1 complex"},{"id":"b","text":"Binding of mannose-binding lectin to a microbe"},{"id":"c","text":"Spontaneous C3 tickover"},{"id":"d","text":"Formation of C5 convertase"}],"answerId":"b","explanation":"The lectin pathway is activated when mannose-binding lectin (MBL) recognizes mannose on microbial surfaces.","kind":"recall","origin":"ai"},{"id":"complement-pathways~ai-3","moduleId":"complement-pathways","stem":"What is a common misconception about the complement pathways?","options":[{"id":"a","text":"They all converge at C3"},{"id":"b","text":"The classical pathway requires antibodies"},{"id":"c","text":"The alternative pathway is antibody-dependent"},{"id":"d","text":"C5 convertase is formed from C4b2a"}],"answerId":"c","explanation":"The alternative pathway is initiated independently of antibodies, which is a common misconception.","kind":"trap","origin":"ai"},{"id":"complement-pathways~ai-4","moduleId":"complement-pathways","stem":"What is the mechanism of action for properdin in the alternative pathway?","options":[{"id":"a","text":"Activates C1"},{"id":"b","text":"Stabilizes C3bBb"},{"id":"c","text":"Cleaves C3"},{"id":"d","text":"Forms the MAC"}],"answerId":"b","explanation":"Properdin stabilizes the C3bBb complex in the alternative pathway, enhancing complement activation.","kind":"mechanism","origin":"ai"},{"id":"complement-pathways~ai-5","moduleId":"complement-pathways","stem":"How does complement activation relate to hemolysis in patients with autoimmune disorders?","options":[{"id":"a","text":"Increased C3b leads to hemolysis"},{"id":"b","text":"C1 deficiency prevents hemolysis"},{"id":"c","text":"C5a promotes phagocytosis of RBCs"},{"id":"d","text":"C3 deficiency enhances hemolysis"}],"answerId":"a","explanation":"In autoimmune disorders, antibody-antigen complexes can activate complement, leading to increased C3b and subsequent hemolysis of red blood cells.","kind":"integration","linkedModuleIds":["hemolysis-workup-triggers"],"origin":"ai"},{"id":"complement-pathways~ai-6","moduleId":"complement-pathways","stem":"Which complement component is critical for the formation of the membrane attack complex (MAC)?","options":[{"id":"a","text":"C1"},{"id":"b","text":"C3"},{"id":"c","text":"C5"},{"id":"d","text":"C9"}],"answerId":"c","explanation":"C5b is essential for initiating the assembly of the MAC, which ultimately leads to cell lysis.","kind":"recall","origin":"ai"},{"id":"complement-pathways~ai-7","moduleId":"complement-pathways","stem":"What is the relationship between complement deficiencies and susceptibility to infections?","options":[{"id":"a","text":"Deficiencies in C3 lead to increased susceptibility to pyogenic infections"},{"id":"b","text":"C1 deficiency causes autoimmune diseases"},{"id":"c","text":"C5 deficiency increases viral infections"},{"id":"d","text":"C4 deficiency has no clinical significance"}],"answerId":"a","explanation":"C3 deficiency cripples all three complement pathways, leading to increased susceptibility to pyogenic infections.","kind":"integration","linkedModuleIds":["complement-functions-regulation"],"origin":"ai"}],"peer-review-journal-metrics":[{"id":"peer-review-journal-metrics~ai-0","moduleId":"peer-review-journal-metrics","stem":"What is the primary purpose of peer review in scientific publishing?","options":[{"id":"a","text":"To ensure rapid publication of research"},{"id":"b","text":"To provide expert scrutiny before publication"},{"id":"c","text":"To increase journal impact factors"},{"id":"d","text":"To guarantee acceptance of manuscripts"}],"answerId":"b","explanation":"Peer review serves as a quality control mechanism by allowing independent experts to evaluate the validity and significance of research before publication.","kind":"recall","origin":"ai"},{"id":"peer-review-journal-metrics~ai-1","moduleId":"peer-review-journal-metrics","stem":"Which of the following best describes the journal impact factor (JIF)?","options":[{"id":"a","text":"A measure of the quality of individual articles"},{"id":"b","text":"The average number of citations to articles published in the last two years"},{"id":"c","text":"A ranking of authors based on their publication history"},{"id":"d","text":"A score assigned to authors based on peer reviews"}],"answerId":"b","explanation":"The journal impact factor is calculated as the average number of citations to articles published in a journal over the previous two years, reflecting the journal's influence.","kind":"recall","origin":"ai"},{"id":"peer-review-journal-metrics~ai-2","moduleId":"peer-review-journal-metrics","stem":"What is a hallmark of a predatory journal?","options":[{"id":"a","text":"Rigorous peer review process"},{"id":"b","text":"High journal impact factor"},{"id":"c","text":"Guaranteed rapid acceptance"},{"id":"d","text":"Indexing in reputable databases"}],"answerId":"c","explanation":"Predatory journals often promise guaranteed rapid acceptance, which is a red flag indicating a lack of genuine peer review.","kind":"trap","origin":"ai"},{"id":"peer-review-journal-metrics~ai-3","moduleId":"peer-review-journal-metrics","stem":"Which of the following is a legitimate signal of a journal's credibility?","options":[{"id":"a","text":"Guaranteed acceptance of all submissions"},{"id":"b","text":"Indexing in PubMed or Scopus"},{"id":"c","text":"High article processing charges"},{"id":"d","text":"Frequent unsolicited emails from the journal"}],"answerId":"b","explanation":"Being indexed in reputable databases like PubMed or Scopus is a basic marker of a journal's legitimacy.","kind":"recall","origin":"ai"},{"id":"peer-review-journal-metrics~ai-4","moduleId":"peer-review-journal-metrics","stem":"In a double-blind peer review process, which parties are anonymized?","options":[{"id":"a","text":"Only the authors"},{"id":"b","text":"Only the reviewers"},{"id":"c","text":"Both authors and reviewers"},{"id":"d","text":"Only the journal editors"}],"answerId":"c","explanation":"In double-blind peer review, both the authors and the reviewers remain anonymous to reduce bias in the evaluation process.","kind":"recall","origin":"ai"},{"id":"peer-review-journal-metrics~ai-5","moduleId":"peer-review-journal-metrics","stem":"How does understanding journal metrics enhance the appraisal of research publications?","options":[{"id":"a","text":"It guarantees the quality of every published article"},{"id":"b","text":"It helps assess the credibility and influence of the journal"},{"id":"c","text":"It simplifies the publication process"},{"id":"d","text":"It eliminates the need for peer review"}],"answerId":"b","explanation":"Understanding journal metrics, like impact factor, aids in evaluating the credibility and influence of the journal, but does not guarantee the quality of individual articles.","kind":"integration","linkedModuleIds":["publication-types-imrad"],"origin":"ai"},{"id":"peer-review-journal-metrics~ai-6","moduleId":"peer-review-journal-metrics","stem":"Which of the following statements about predatory journals is accurate?","options":[{"id":"a","text":"They provide rigorous peer review"},{"id":"b","text":"They charge high fees but ensure quality"},{"id":"c","text":"They often have fake metrics and aggressive solicitation"},{"id":"d","text":"They are indexed in reputable databases"}],"answerId":"c","explanation":"Predatory journals are characterized by fake metrics, aggressive solicitation, and lack of genuine peer review.","kind":"trap","origin":"ai"},{"id":"peer-review-journal-metrics~ai-7","moduleId":"peer-review-journal-metrics","stem":"What is the relationship between peer review and the IMRaD structure in research publications?","options":[{"id":"a","text":"Peer review is not related to publication structure"},{"id":"b","text":"IMRaD is a format that enhances peer review quality"},{"id":"c","text":"Peer review assesses the adherence to IMRaD structure"},{"id":"d","text":"IMRaD is only relevant for predatory journals"}],"answerId":"c","explanation":"Peer review often assesses whether research follows the IMRaD structure, which is critical for clarity and organization in scientific communication.","kind":"integration","linkedModuleIds":["publication-types-imrad"],"origin":"ai"}],"complement-functions-regulation":[{"id":"complement-functions-regulation~ai-0","moduleId":"complement-functions-regulation","stem":"Which complement component deficiency is most commonly associated with SLE-like presentations?","options":[{"id":"a","text":"C1"},{"id":"b","text":"C2"},{"id":"c","text":"C3"},{"id":"d","text":"C4"}],"answerId":"b","explanation":"C2 deficiency is the most common early component deficiency leading to impaired clearance of immune complexes, resulting in SLE-like symptoms.","kind":"recall","origin":"ai"},{"id":"complement-functions-regulation~ai-1","moduleId":"complement-functions-regulation","stem":"What is the primary function of C3b in the complement system?","options":[{"id":"a","text":"Mast cell degranulation"},{"id":"b","text":"Opsonization of pathogens"},{"id":"c","text":"Formation of the MAC"},{"id":"d","text":"Chemoattraction of neutrophils"}],"answerId":"b","explanation":"C3b coats microbes and enhances phagocytosis by binding to phagocyte receptors.","kind":"mechanism","origin":"ai"},{"id":"complement-functions-regulation~ai-2","moduleId":"complement-functions-regulation","stem":"A patient presents with recurrent Neisseria infections. Which complement deficiency is most likely responsible?","options":[{"id":"a","text":"C1 inhibitor deficiency"},{"id":"b","text":"C3 deficiency"},{"id":"c","text":"C5–C9 deficiency"},{"id":"d","text":"C2 deficiency"}],"answerId":"c","explanation":"Recurrent Neisseria infections indicate a deficiency in terminal complement components (C5–C9), which are crucial for MAC formation.","kind":"clinical","origin":"ai"},{"id":"complement-functions-regulation~ai-3","moduleId":"complement-functions-regulation","stem":"Which of the following findings is characteristic of hereditary angioedema?","options":[{"id":"a","text":"Recurrent pyogenic infections"},{"id":"b","text":"Recurrent non-pruritic angioedema"},{"id":"c","text":"Complement-mediated hemolysis"},{"id":"d","text":"SLE-like immune complex disease"}],"answerId":"b","explanation":"Hereditary angioedema is due to C1-inhibitor deficiency, leading to recurrent non-pruritic swelling.","kind":"recall","origin":"ai"},{"id":"complement-functions-regulation~ai-4","moduleId":"complement-functions-regulation","stem":"C3 deficiency is associated with which of the following clinical presentations?","options":[{"id":"a","text":"Recurrent Neisseria infections"},{"id":"b","text":"SLE-like immune complex disease"},{"id":"c","text":"Severe recurrent pyogenic infections"},{"id":"d","text":"Hereditary angioedema"}],"answerId":"c","explanation":"C3 deficiency results in severe, recurrent pyogenic infections and immune complex disease due to its central role in the complement system.","kind":"trap","origin":"ai"},{"id":"complement-functions-regulation~ai-5","moduleId":"complement-functions-regulation","stem":"How does C1 inhibitor deficiency lead to angioedema?","options":[{"id":"a","text":"Increased C3b production"},{"id":"b","text":"Unopposed bradykinin activity"},{"id":"c","text":"Inhibition of C5a"},{"id":"d","text":"Decreased C2 levels"}],"answerId":"b","explanation":"C1 inhibitor deficiency leads to unopposed bradykinin activity, causing recurrent non-pruritic angioedema.","kind":"mechanism","origin":"ai"},{"id":"complement-functions-regulation~ai-6","moduleId":"complement-functions-regulation","stem":"In the context of complement deficiencies, which module would provide insights into immune mechanisms of glomerular injury?","options":[{"id":"a","text":"Coenzymes & Cofactors"},{"id":"b","text":"Complement: The Three Activation Pathways"},{"id":"c","text":"Primary Immunodeficiency: Phagocyte & Complement Defects"},{"id":"d","text":"Immune Mechanisms of Glomerular Injury"}],"answerId":"d","explanation":"The module on immune mechanisms of glomerular injury is relevant as it discusses how complement deficiencies can lead to kidney damage.","kind":"integration","linkedModuleIds":["glomerular-disease-immune-mechanisms"],"origin":"ai"},{"id":"complement-functions-regulation~ai-7","moduleId":"complement-functions-regulation","stem":"Which module would help understand the role of complement in immunity to extracellular bacteria?","options":[{"id":"a","text":"Complement: The Three Activation Pathways"},{"id":"b","text":"Primary Immunodeficiency: Phagocyte & Complement Defects"},{"id":"c","text":"Coenzymes & Cofactors"},{"id":"d","text":"Immunity to Bacteria: Extracellular vs Intracellular"}],"answerId":"d","explanation":"The module on immunity to bacteria covers the mechanisms by which the complement system aids in the defense against extracellular pathogens.","kind":"integration","linkedModuleIds":["immunity-bacteria-extracellular-intracellular"],"origin":"ai"}],"immune-system-overview-cells":[{"id":"immune-system-overview-cells~ai-0","moduleId":"immune-system-overview-cells","stem":"Which immune cell is the first responder to acute bacterial infections?","options":[{"id":"a","text":"Monocyte"},{"id":"b","text":"Dendritic cell"},{"id":"c","text":"Neutrophil"},{"id":"d","text":"B cell"}],"answerId":"c","explanation":"Neutrophils are the first cells to arrive at the site of acute bacterial infections due to their rapid response.","kind":"recall","origin":"ai"},{"id":"immune-system-overview-cells~ai-1","moduleId":"immune-system-overview-cells","stem":"What is the primary function of dendritic cells in the immune system?","options":[{"id":"a","text":"Phagocytosis"},{"id":"b","text":"Antibody production"},{"id":"c","text":"Antigen presentation"},{"id":"d","text":"Cytokine secretion"}],"answerId":"c","explanation":"Dendritic cells are the most potent antigen-presenting cells, bridging innate and adaptive immunity.","kind":"mechanism","origin":"ai"},{"id":"immune-system-overview-cells~ai-2","moduleId":"immune-system-overview-cells","stem":"Which of the following statements about immune memory is true?","options":[{"id":"a","text":"Innate immunity develops memory after repeated exposure"},{"id":"b","text":"Only adaptive immunity has classical memory"},{"id":"c","text":"Memory is present in neutrophils"},{"id":"d","text":"Macrophages are responsible for immunological memory"}],"answerId":"b","explanation":"Only adaptive immunity, involving B and T lymphocytes, has classical memory, allowing for faster and stronger responses upon re-exposure.","kind":"trap","origin":"ai"},{"id":"immune-system-overview-cells~ai-3","moduleId":"immune-system-overview-cells","stem":"Which cell type is characterized by the expression of CD4⁺CD25⁺FoxP3⁺?","options":[{"id":"a","text":"Cytotoxic T cell"},{"id":"b","text":"Helper T cell"},{"id":"c","text":"Regulatory T cell"},{"id":"d","text":"B cell"}],"answerId":"c","explanation":"CD4⁺CD25⁺FoxP3⁺ identifies regulatory T cells, which play a crucial role in maintaining self-tolerance.","kind":"recall","origin":"ai"},{"id":"immune-system-overview-cells~ai-4","moduleId":"immune-system-overview-cells","stem":"What is the primary role of B cells in the immune response?","options":[{"id":"a","text":"Cytotoxic activity"},{"id":"b","text":"Antigen presentation"},{"id":"c","text":"Antibody production"},{"id":"d","text":"Phagocytosis"}],"answerId":"c","explanation":"B cells are responsible for producing antibodies, which are essential for humoral immunity against extracellular pathogens.","kind":"recall","origin":"ai"},{"id":"immune-system-overview-cells~ai-5","moduleId":"immune-system-overview-cells","stem":"How do innate immune cells recognize pathogens?","options":[{"id":"a","text":"Through specific antibodies"},{"id":"b","text":"Using pattern recognition receptors (PRRs)"},{"id":"c","text":"By memory cells"},{"id":"d","text":"Through MHC molecules"}],"answerId":"b","explanation":"Innate immune cells recognize pathogens using pattern recognition receptors (PRRs) that detect broad microbial patterns.","kind":"mechanism","origin":"ai"},{"id":"immune-system-overview-cells~ai-6","moduleId":"immune-system-overview-cells","stem":"How does the skin contribute to the immune response?","options":[{"id":"a","text":"By producing antibodies"},{"id":"b","text":"By serving as a physical barrier and housing immune cells"},{"id":"c","text":"By activating T cells"},{"id":"d","text":"By secreting cytokines"}],"answerId":"b","explanation":"The skin acts as a physical barrier and contains immune cells that help to prevent pathogen entry, linking to the skin immune system module.","kind":"integration","linkedModuleIds":["skin-immune-system-cells"],"origin":"ai"},{"id":"immune-system-overview-cells~ai-7","moduleId":"immune-system-overview-cells","stem":"Which immune cells are primarily involved in the response to intracellular pathogens?","options":[{"id":"a","text":"B cells"},{"id":"b","text":"Neutrophils"},{"id":"c","text":"CD8⁺ T cells"},{"id":"d","text":"Dendritic cells"}],"answerId":"c","explanation":"CD8⁺ T cells are primarily responsible for the cell-mediated immune response against intracellular pathogens.","kind":"recall","origin":"ai"},{"id":"immune-system-overview-cells~ai-8","moduleId":"immune-system-overview-cells","stem":"What is the role of regulatory T cells in the immune system?","options":[{"id":"a","text":"Enhancing immune response"},{"id":"b","text":"Killing infected cells"},{"id":"c","text":"Suppressing immune reactions"},{"id":"d","text":"Producing antibodies"}],"answerId":"c","explanation":"Regulatory T cells suppress immune reactions to maintain self-tolerance and prevent autoimmunity.","kind":"mechanism","origin":"ai"}],"lymphoid-organs":[{"id":"lymphoid-organs~ai-0","moduleId":"lymphoid-organs","stem":"Where do B cells mature?","options":[{"id":"a","text":"Thymus"},{"id":"b","text":"Bone marrow"},{"id":"c","text":"Spleen"},{"id":"d","text":"Lymph nodes"}],"answerId":"b","explanation":"B cells mature in the bone marrow, while T cells mature in the thymus.","kind":"trap","origin":"ai"},{"id":"lymphoid-organs~ai-1","moduleId":"lymphoid-organs","stem":"What is the primary function of the spleen?","options":[{"id":"a","text":"Production of red blood cells"},{"id":"b","text":"Filtration of lymph"},{"id":"c","text":"Filtration of blood and immune response"},{"id":"d","text":"Storage of platelets"}],"answerId":"c","explanation":"The spleen filters blood and plays a critical role in the immune response, particularly against encapsulated bacteria.","kind":"recall","origin":"ai"},{"id":"lymphoid-organs~ai-2","moduleId":"lymphoid-organs","stem":"Which lymphoid organ is responsible for T cell maturation?","options":[{"id":"a","text":"Bone marrow"},{"id":"b","text":"Thymus"},{"id":"c","text":"Spleen"},{"id":"d","text":"Lymph nodes"}],"answerId":"b","explanation":"The thymus is the organ where T cells mature through positive and negative selection.","kind":"recall","origin":"ai"},{"id":"lymphoid-organs~ai-3","moduleId":"lymphoid-organs","stem":"What is indicated by the presence of germinal centers in lymphoid follicles?","options":[{"id":"a","text":"Naïve B cell activation"},{"id":"b","text":"Active B cell response"},{"id":"c","text":"T cell activation"},{"id":"d","text":"Macrophage activity"}],"answerId":"b","explanation":"Germinal centers indicate an active B cell response involving affinity maturation and class switching.","kind":"recall","origin":"ai"},{"id":"lymphoid-organs~ai-4","moduleId":"lymphoid-organs","stem":"A patient presents with overwhelming pneumococcal sepsis after splenectomy. What is the underlying mechanism?","options":[{"id":"a","text":"Loss of T cell maturation"},{"id":"b","text":"Loss of B cell activation"},{"id":"c","text":"Loss of splenic clearance of encapsulated bacteria"},{"id":"d","text":"Loss of lymphocyte recirculation"}],"answerId":"c","explanation":"The spleen is critical for clearing encapsulated bacteria, and its absence predisposes to infections.","kind":"recall","origin":"ai"},{"id":"lymphoid-organs~ai-5","moduleId":"lymphoid-organs","stem":"How do follicular helper T (Tfh) cells assist B cells in germinal centers?","options":[{"id":"a","text":"By presenting antigens"},{"id":"b","text":"By inducing apoptosis"},{"id":"c","text":"By promoting class switching and affinity maturation"},{"id":"d","text":"By activating macrophages"}],"answerId":"c","explanation":"Tfh cells help B cells undergo class switching and affinity maturation in germinal centers.","kind":"mechanism","origin":"ai"},{"id":"lymphoid-organs~ai-6","moduleId":"lymphoid-organs","stem":"Which lymphoid organ is primarily involved in filtering lymph and activating immune responses?","options":[{"id":"a","text":"Bone marrow"},{"id":"b","text":"Thymus"},{"id":"c","text":"Spleen"},{"id":"d","text":"Lymph nodes"}],"answerId":"d","explanation":"Lymph nodes filter lymph and are sites where mature lymphocytes meet antigens and become activated.","kind":"recall","origin":"ai"},{"id":"lymphoid-organs~ai-7","moduleId":"lymphoid-organs","stem":"How does the function of lymph nodes relate to the overall immune response?","options":[{"id":"a","text":"They produce red blood cells"},{"id":"b","text":"They filter blood for pathogens"},{"id":"c","text":"They are sites for lymphocyte activation and proliferation"},{"id":"d","text":"They store antibodies"}],"answerId":"c","explanation":"Lymph nodes are critical for lymphocyte activation and proliferation upon encountering antigens.","kind":"integration","linkedModuleIds":["immune-system-overview-cells"],"origin":"ai"},{"id":"lymphoid-organs~ai-8","moduleId":"lymphoid-organs","stem":"What is the consequence of thymic hypoplasia in a patient?","options":[{"id":"a","text":"Increased B cell activation"},{"id":"b","text":"Decreased T cell maturation"},{"id":"c","text":"Increased lymph node size"},{"id":"d","text":"Decreased antibody production"}],"answerId":"b","explanation":"Thymic hypoplasia leads to decreased T cell maturation, resulting in T cell deficiency.","kind":"integration","linkedModuleIds":["immune-system-overview-cells"],"origin":"ai"}],"academic-authorship":[{"id":"academic-authorship~ai-0","moduleId":"academic-authorship","stem":"Which of the following is NOT a requirement for authorship according to ICMJE criteria?","options":[{"id":"a","text":"Substantial contribution to conception or design"},{"id":"b","text":"Drafting or revising the manuscript"},{"id":"c","text":"Final approval of the version to be published"},{"id":"d","text":"Providing funding for the research"}],"answerId":"d","explanation":"Providing funding alone does not meet the ICMJE criteria for authorship.","kind":"recall","origin":"ai"},{"id":"academic-authorship~ai-1","moduleId":"academic-authorship","stem":"What is the primary role of the corresponding author in a research paper?","options":[{"id":"a","text":"To conduct the majority of the research"},{"id":"b","text":"To handle submission and communication"},{"id":"c","text":"To lead the research team"},{"id":"d","text":"To approve the final manuscript"}],"answerId":"b","explanation":"The corresponding author is responsible for handling submission and communication regarding the manuscript.","kind":"recall","origin":"ai"},{"id":"academic-authorship~ai-2","moduleId":"academic-authorship","stem":"Which term describes the unethical practice of crediting someone who did not contribute to the research?","options":[{"id":"a","text":"Ghost authorship"},{"id":"b","text":"Gift authorship"},{"id":"c","text":"Plagiarism"},{"id":"d","text":"Falsification"}],"answerId":"b","explanation":"Gift authorship refers to crediting individuals who did not contribute to the research work.","kind":"recall","origin":"ai"},{"id":"academic-authorship~ai-3","moduleId":"academic-authorship","stem":"In the context of authorship, what does 'ghost authorship' refer to?","options":[{"id":"a","text":"Including a non-contributor as an author"},{"id":"b","text":"Excluding a contributor from the author list"},{"id":"c","text":"Using someone else's ideas without credit"},{"id":"d","text":"Manipulating data to misrepresent findings"}],"answerId":"b","explanation":"Ghost authorship occurs when a real contributor is deliberately left off the author list.","kind":"recall","origin":"ai"},{"id":"academic-authorship~ai-4","moduleId":"academic-authorship","stem":"Which of the following actions would be considered research misconduct under FFP?","options":[{"id":"a","text":"Including all contributors in the acknowledgments"},{"id":"b","text":"Altering data to fit a hypothesis"},{"id":"c","text":"Submitting a manuscript to multiple journals"},{"id":"d","text":"Providing proper citations for borrowed ideas"}],"answerId":"b","explanation":"Altering data to fit a hypothesis is considered falsification, a form of research misconduct.","kind":"recall","origin":"ai"},{"id":"academic-authorship~ai-5","moduleId":"academic-authorship","stem":"How does the ICMJE define the role of a first author?","options":[{"id":"a","text":"The one who contributed the least"},{"id":"b","text":"The one who did the most work"},{"id":"c","text":"The one who handled the manuscript submission"},{"id":"d","text":"The one who approved the final version"}],"answerId":"b","explanation":"The first author is typically the individual who contributed the most work to the research and manuscript.","kind":"recall","origin":"ai"},{"id":"academic-authorship~ai-6","moduleId":"academic-authorship","stem":"How can authorship disputes be prevented according to best practices?","options":[{"id":"a","text":"Agree on authorship roles after submission"},{"id":"b","text":"Discuss and agree on order and roles at the start"},{"id":"c","text":"Assign authorship based on seniority"},{"id":"d","text":"Include all contributors regardless of their input"}],"answerId":"b","explanation":"Preventing authorship disputes involves agreeing on authorship roles and order at the beginning of the project.","kind":"trap","origin":"ai"},{"id":"academic-authorship~ai-7","moduleId":"academic-authorship","stem":"A researcher is diagnosed with diabetes. Which of the following criteria would be relevant for their management according to the linked module on diabetes diagnostic criteria (hen1-diabetes-diagnostic-criteria)?","options":[{"id":"a","text":"Final approval of the manuscript"},{"id":"b","text":"Substantial contribution to research design"},{"id":"c","text":"Fasting blood glucose levels"},{"id":"d","text":"Handling manuscript communication"}],"answerId":"c","explanation":"Fasting blood glucose levels are part of the diagnostic criteria for diabetes management.","kind":"integration","linkedModuleIds":["hen1-diabetes-diagnostic-criteria"],"origin":"ai"},{"id":"academic-authorship~ai-8","moduleId":"academic-authorship","stem":"In a study involving patients with pericardial effusion, which aspect of authorship would be critical to ensure ethical reporting of results according to the linked module on pericardial effusion (pericardial-effusion)?","options":[{"id":"a","text":"Final approval of the manuscript"},{"id":"b","text":"Providing funding for the study"},{"id":"c","text":"Gift authorship of a senior physician"},{"id":"d","text":"Ghost authorship by a medical writer"}],"answerId":"a","explanation":"Final approval of the manuscript is essential to ensure accountability and integrity in reporting results.","kind":"integration","linkedModuleIds":["pericardial-effusion"],"origin":"ai"}],"b-cell-development-tolerance":[{"id":"b-cell-development-tolerance~ai-0","moduleId":"b-cell-development-tolerance","stem":"What is the first step in B-cell receptor gene rearrangement?","options":[{"id":"a","text":"Rearrangement of the light chain"},{"id":"b","text":"Rearrangement of the heavy chain"},{"id":"c","text":"Formation of the pre-BCR"},{"id":"d","text":"Clonal deletion of self-reactive B cells"}],"answerId":"b","explanation":"The heavy chain rearranges first, followed by the light chain, which is essential for the formation of a functional B-cell receptor.","kind":"recall","origin":"ai"},{"id":"b-cell-development-tolerance~ai-1","moduleId":"b-cell-development-tolerance","stem":"Which enzyme complex is crucial for V(D)J recombination in B cells?","options":[{"id":"a","text":"DNA polymerase"},{"id":"b","text":"RAG1/RAG2"},{"id":"c","text":"TdT"},{"id":"d","text":"AID"}],"answerId":"b","explanation":"RAG1 and RAG2 are essential for the V(D)J recombination process that generates diverse B-cell receptors.","kind":"mechanism","origin":"ai"},{"id":"b-cell-development-tolerance~ai-2","moduleId":"b-cell-development-tolerance","stem":"What mechanism allows immature B cells to change their receptor specificity?","options":[{"id":"a","text":"Clonal deletion"},{"id":"b","text":"Receptor editing"},{"id":"c","text":"Class switching"},{"id":"d","text":"Somatic hypermutation"}],"answerId":"b","explanation":"Receptor editing allows immature B cells to rearrange their light chain genes to change their specificity and avoid self-reactivity.","kind":"mechanism","origin":"ai"},{"id":"b-cell-development-tolerance~ai-3","moduleId":"b-cell-development-tolerance","stem":"What is the consequence of failed BTK signaling in B-cell development?","options":[{"id":"a","text":"Increased antibody production"},{"id":"b","text":"Arrest at the pre-B stage"},{"id":"c","text":"Enhanced receptor editing"},{"id":"d","text":"Mature B cell proliferation"}],"answerId":"b","explanation":"Failure of BTK signaling leads to an arrest at the pre-B cell stage, resulting in a lack of mature B cells.","kind":"trap","origin":"ai"},{"id":"b-cell-development-tolerance~ai-4","moduleId":"b-cell-development-tolerance","stem":"Which of the following findings indicates successful heavy chain rearrangement in B-cell development?","options":[{"id":"a","text":"Presence of surface IgD"},{"id":"b","text":"Formation of the pre-BCR"},{"id":"c","text":"Clonal deletion of self-reactive cells"},{"id":"d","text":"Class switching"}],"answerId":"b","explanation":"The formation of the pre-BCR indicates that the heavy chain has successfully rearranged and is functional.","kind":"recall","origin":"ai"},{"id":"b-cell-development-tolerance~ai-5","moduleId":"b-cell-development-tolerance","stem":"How do mature naïve B cells achieve diversity in antibody production?","options":[{"id":"a","text":"Clonal deletion"},{"id":"b","text":"Somatic hypermutation"},{"id":"c","text":"Receptor editing"},{"id":"d","text":"Anergic response"}],"answerId":"b","explanation":"Somatic hypermutation in germinal centers allows mature B cells to increase the affinity of their antibodies.","kind":"mechanism","origin":"ai"},{"id":"b-cell-development-tolerance~ai-6","moduleId":"b-cell-development-tolerance","stem":"Which process is primarily responsible for the generation of memory B cells after antigen exposure?","options":[{"id":"a","text":"Clonal deletion"},{"id":"b","text":"Somatic hypermutation"},{"id":"c","text":"Class switching"},{"id":"d","text":"Receptor editing"}],"answerId":"c","explanation":"Class switching allows B cells to produce different antibody isotypes, which is essential for memory B cell formation.","kind":"integration","linkedModuleIds":["primary-immunodeficiency-antibody-t"],"origin":"ai"},{"id":"b-cell-development-tolerance~ai-7","moduleId":"b-cell-development-tolerance","stem":"What is the role of Tfh cells in B-cell development?","options":[{"id":"a","text":"Inducing clonal deletion"},{"id":"b","text":"Facilitating somatic hypermutation"},{"id":"c","text":"Promoting receptor editing"},{"id":"d","text":"Inhibiting heavy chain rearrangement"}],"answerId":"b","explanation":"Tfh cells provide help for B cells in germinal centers, facilitating somatic hypermutation and class switching.","kind":"integration","linkedModuleIds":["t-cell-development-thymic-selection"],"origin":"ai"}],"immunity-bacteria-extracellular-intracellular":[{"id":"immunity-bacteria-extracellular-intracellular~ai-0","moduleId":"immunity-bacteria-extracellular-intracellular","stem":"Which type of immunity is primarily responsible for combating extracellular bacteria?","options":[{"id":"a","text":"Cell-mediated immunity"},{"id":"b","text":"Humoral immunity"},{"id":"c","text":"Innate immunity"},{"id":"d","text":"Adaptive immunity"}],"answerId":"b","explanation":"Humoral immunity, characterized by antibody production, is the main defense against extracellular bacteria.","kind":"recall","origin":"ai"},{"id":"immunity-bacteria-extracellular-intracellular~ai-1","moduleId":"immunity-bacteria-extracellular-intracellular","stem":"What is the role of IFN-γ in the immune response to intracellular bacteria?","options":[{"id":"a","text":"Promotes antibody production"},{"id":"b","text":"Activates macrophages"},{"id":"c","text":"Enhances neutrophil recruitment"},{"id":"d","text":"Inhibits T-cell activation"}],"answerId":"b","explanation":"IFN-γ is crucial for activating macrophages to enhance their ability to kill intracellular bacteria.","kind":"mechanism","origin":"ai"},{"id":"immunity-bacteria-extracellular-intracellular~ai-2","moduleId":"immunity-bacteria-extracellular-intracellular","stem":"A patient presents with recurrent infections from encapsulated bacteria. What underlying defect is most likely present?","options":[{"id":"a","text":"T-cell deficiency"},{"id":"b","text":"Antibody deficiency"},{"id":"c","text":"Complement deficiency"},{"id":"d","text":"Macrophage dysfunction"}],"answerId":"c","explanation":"Recurrent infections from encapsulated bacteria often indicate a defect in antibody or complement-mediated opsonization.","kind":"clinical","origin":"ai"},{"id":"immunity-bacteria-extracellular-intracellular~ai-3","moduleId":"immunity-bacteria-extracellular-intracellular","stem":"Which of the following findings is indicative of a Th1-mediated immune response?","options":[{"id":"a","text":"Presence of antibodies against toxins"},{"id":"b","text":"Granuloma formation with activated macrophages"},{"id":"c","text":"Increased neutrophil count"},{"id":"d","text":"High levels of IgE"}],"answerId":"b","explanation":"Granuloma formation with activated macrophages is characteristic of a Th1-mediated immune response to intracellular pathogens.","kind":"recall","origin":"ai"},{"id":"immunity-bacteria-extracellular-intracellular~ai-4","moduleId":"immunity-bacteria-extracellular-intracellular","stem":"What is a common consequence of a cytokine storm during Gram-negative sepsis?","options":[{"id":"a","text":"Increased antibody production"},{"id":"b","text":"Septic shock"},{"id":"c","text":"Granuloma formation"},{"id":"d","text":"Decreased neutrophil activity"}],"answerId":"b","explanation":"A cytokine storm can lead to septic shock due to overwhelming inflammatory responses.","kind":"clinical","origin":"ai"},{"id":"immunity-bacteria-extracellular-intracellular~ai-5","moduleId":"immunity-bacteria-extracellular-intracellular","stem":"Which statement about the defense against intracellular bacteria is true?","options":[{"id":"a","text":"Antibodies are the main defense"},{"id":"b","text":"Cell-mediated immunity is essential"},{"id":"c","text":"Neutrophils are the primary responders"},{"id":"d","text":"Complement activation is sufficient"}],"answerId":"b","explanation":"Cell-mediated immunity, particularly through Th1 cells and macrophage activation, is essential for combating intracellular bacteria.","kind":"trap","origin":"ai"},{"id":"immunity-bacteria-extracellular-intracellular~ai-6","moduleId":"immunity-bacteria-extracellular-intracellular","stem":"How does the mechanism of antibody neutralization differ from complement activation in the context of extracellular bacteria?","options":[{"id":"a","text":"Antibody neutralization involves direct lysis"},{"id":"b","text":"Complement activation enhances opsonization"},{"id":"c","text":"Antibody neutralization is ineffective against encapsulated bacteria"},{"id":"d","text":"Complement activation requires T-cell help"}],"answerId":"b","explanation":"Complement activation enhances opsonization and can lead to the lysis of bacteria, while antibody neutralization primarily blocks toxins and adhesion.","kind":"integration","linkedModuleIds":["antibody-classes-functions"],"origin":"ai"},{"id":"immunity-bacteria-extracellular-intracellular~ai-7","moduleId":"immunity-bacteria-extracellular-intracellular","stem":"What role does the complement system play in the defense against extracellular bacteria?","options":[{"id":"a","text":"It activates macrophages"},{"id":"b","text":"It enhances antibody production"},{"id":"c","text":"It opsonizes bacteria for phagocytosis"},{"id":"d","text":"It directly kills intracellular pathogens"}],"answerId":"c","explanation":"The complement system opsonizes extracellular bacteria, facilitating their phagocytosis by immune cells.","kind":"integration","linkedModuleIds":["complement-functions-regulation"],"origin":"ai"}],"antigen-processing-presentation":[{"id":"antigen-processing-presentation~ai-0","moduleId":"antigen-processing-presentation","stem":"Which MHC class presents endogenous antigens to CD8 T cells?","options":[{"id":"a","text":"MHC class I"},{"id":"b","text":"MHC class II"},{"id":"c","text":"MHC class III"},{"id":"d","text":"MHC class IV"}],"answerId":"a","explanation":"Endogenous antigens are presented on MHC class I, which is recognized by CD8 T cells.","kind":"recall","origin":"ai"},{"id":"antigen-processing-presentation~ai-1","moduleId":"antigen-processing-presentation","stem":"What is the role of TAP in antigen processing?","options":[{"id":"a","text":"Degrades peptides in the cytosol"},{"id":"b","text":"Transports peptides into the ER"},{"id":"c","text":"Presents antigens on MHC II"},{"id":"d","text":"Inhibits MHC I expression"}],"answerId":"b","explanation":"TAP (transporter associated with antigen processing) transports peptides into the ER for loading onto MHC class I.","kind":"mechanism","origin":"ai"},{"id":"antigen-processing-presentation~ai-2","moduleId":"antigen-processing-presentation","stem":"A patient presents with absent MHC II expression and low CD4 T cell counts. What condition is likely?","options":[{"id":"a","text":"Bare lymphocyte syndrome type I"},{"id":"b","text":"Bare lymphocyte syndrome type II"},{"id":"c","text":"Severe combined immunodeficiency"},{"id":"d","text":"Acquired immunodeficiency syndrome"}],"answerId":"b","explanation":"Absent MHC II expression and low CD4 counts are indicative of bare lymphocyte syndrome type II.","kind":"clinical","origin":"ai"},{"id":"antigen-processing-presentation~ai-3","moduleId":"antigen-processing-presentation","stem":"Which statement about cross-presentation is true?","options":[{"id":"a","text":"It only occurs in B cells"},{"id":"b","text":"It allows CD4 T cells to recognize endogenous antigens"},{"id":"c","text":"It enables dendritic cells to present exogenous antigens on MHC I"},{"id":"d","text":"It is exclusive to MHC class II"}],"answerId":"c","explanation":"Cross-presentation allows dendritic cells to present exogenous antigens on MHC class I, priming CD8 T cells.","kind":"trap","origin":"ai"},{"id":"antigen-processing-presentation~ai-4","moduleId":"antigen-processing-presentation","stem":"What is the consequence of a viral inhibitor of TAP?","options":[{"id":"a","text":"Increased CD8 T cell activation"},{"id":"b","text":"Enhanced MHC II expression"},{"id":"c","text":"Evasion of CTLs and potential NK targeting"},{"id":"d","text":"Decreased antigen presentation on MHC II"}],"answerId":"c","explanation":"A TAP inhibitor blocks MHC I loading, allowing the virus to evade CTLs but become a target for NK cells due to 'missing self'.","kind":"mechanism","origin":"ai"},{"id":"antigen-processing-presentation~ai-5","moduleId":"antigen-processing-presentation","stem":"How does the MHC class I pathway differ from the MHC class II pathway?","options":[{"id":"a","text":"MHC I presents exogenous antigens, MHC II presents endogenous"},{"id":"b","text":"MHC I is recognized by CD4 T cells, MHC II by CD8 T cells"},{"id":"c","text":"MHC I is loaded in the ER, MHC II in endosomes"},{"id":"d","text":"MHC I is expressed on all nucleated cells, MHC II on professional APCs"}],"answerId":"d","explanation":"MHC class I is expressed on all nucleated cells and presents endogenous antigens, while MHC class II is primarily on professional antigen-presenting cells (APCs) and presents exogenous antigens.","kind":"integration","linkedModuleIds":["cd8-ctl-nk-effectors"],"origin":"ai"},{"id":"antigen-processing-presentation~ai-6","moduleId":"antigen-processing-presentation","stem":"Which T cell subset is primarily activated by MHC class II presentation?","options":[{"id":"a","text":"CD8 T cells"},{"id":"b","text":"CD4 T cells"},{"id":"c","text":"Regulatory T cells"},{"id":"d","text":"Memory T cells"}],"answerId":"b","explanation":"MHC class II molecules present antigens to CD4 T cells, which help coordinate the immune response.","kind":"integration","linkedModuleIds":["cd4-helper-subsets"],"origin":"ai"}],"mhc-structure-genetics":[{"id":"mhc-structure-genetics~ai-0","moduleId":"mhc-structure-genetics","stem":"Which of the following MHC molecules is expressed on all nucleated cells?","options":[{"id":"a","text":"MHC class I"},{"id":"b","text":"MHC class II"},{"id":"c","text":"MHC class III"},{"id":"d","text":"MHC class IV"}],"answerId":"a","explanation":"MHC class I is expressed on all nucleated cells, while MHC class II is restricted to professional antigen-presenting cells.","kind":"recall","origin":"ai"},{"id":"mhc-structure-genetics~ai-1","moduleId":"mhc-structure-genetics","stem":"What is the primary structural component of MHC class I molecules?","options":[{"id":"a","text":"Two chains (α and β)"},{"id":"b","text":"Single α chain and β2-microglobulin"},{"id":"c","text":"Three chains (α, β, and γ)"},{"id":"d","text":"Single β chain only"}],"answerId":"b","explanation":"MHC class I consists of a single α chain and β2-microglobulin, forming a closed peptide-binding groove.","kind":"mechanism","origin":"ai"},{"id":"mhc-structure-genetics~ai-2","moduleId":"mhc-structure-genetics","stem":"Which HLA allele is associated with ankylosing spondylitis?","options":[{"id":"a","text":"HLA-DQ2"},{"id":"b","text":"HLA-DR4"},{"id":"c","text":"HLA-B27"},{"id":"d","text":"HLA-A2"}],"answerId":"c","explanation":"HLA-B27 is strongly associated with ankylosing spondylitis and reactive arthritis.","kind":"recall","origin":"ai"},{"id":"mhc-structure-genetics~ai-3","moduleId":"mhc-structure-genetics","stem":"In which cells is MHC class II primarily expressed?","options":[{"id":"a","text":"All nucleated cells"},{"id":"b","text":"Erythrocytes"},{"id":"c","text":"Professional APCs"},{"id":"d","text":"Neurons"}],"answerId":"c","explanation":"MHC class II is expressed only on professional antigen-presenting cells such as dendritic cells, macrophages, and B cells.","kind":"trap","origin":"ai"},{"id":"mhc-structure-genetics~ai-4","moduleId":"mhc-structure-genetics","stem":"Which of the following best describes the expression of HLA genes?","options":[{"id":"a","text":"Monogenic and recessively expressed"},{"id":"b","text":"Codominantly expressed and polygenic"},{"id":"c","text":"Only expressed in the thymus"},{"id":"d","text":"Expressed only during infection"}],"answerId":"b","explanation":"HLA genes are highly polymorphic, codominantly expressed, and polygenic, allowing for a diverse range of MHC molecules.","kind":"recall","origin":"ai"},{"id":"mhc-structure-genetics~ai-5","moduleId":"mhc-structure-genetics","stem":"How does the diversity of MHC molecules impact transplant matching?","options":[{"id":"a","text":"Increases risk of infection"},{"id":"b","text":"Enhances graft acceptance"},{"id":"c","text":"Reduces immune response"},{"id":"d","text":"Maximizes peptide presentation diversity"}],"answerId":"d","explanation":"The diversity of MHC molecules maximizes the range of peptides that can be presented, which is crucial for effective immune responses and transplant matching.","kind":"mechanism","origin":"ai"},{"id":"mhc-structure-genetics~ai-6","moduleId":"mhc-structure-genetics","stem":"How are T cells restricted in their recognition of antigens?","options":[{"id":"a","text":"By recognizing any peptide"},{"id":"b","text":"By recognizing peptides presented by any MHC"},{"id":"c","text":"By recognizing peptides presented by self-MHC only"},{"id":"d","text":"By recognizing only foreign MHC molecules"}],"answerId":"c","explanation":"T cells are MHC-restricted, meaning they can only recognize their specific peptide when presented by the individual's own MHC.","kind":"integration","linkedModuleIds":["t-cell-development-thymic-selection"],"origin":"ai"},{"id":"mhc-structure-genetics~ai-7","moduleId":"mhc-structure-genetics","stem":"Which process is essential for the presentation of peptides by MHC molecules?","options":[{"id":"a","text":"Transcription"},{"id":"b","text":"Translation"},{"id":"c","text":"Antigen processing"},{"id":"d","text":"Cell division"}],"answerId":"c","explanation":"Antigen processing is critical for the generation of peptides that will be presented by MHC molecules to T cells.","kind":"integration","linkedModuleIds":["antigen-processing-presentation"],"origin":"ai"}],"germinal-center-antibody-response":[{"id":"germinal-center-antibody-response~ai-0","moduleId":"germinal-center-antibody-response","stem":"What is the primary function of somatic hypermutation in B cells?","options":[{"id":"a","text":"Increase antibody production"},{"id":"b","text":"Refine antibody affinity"},{"id":"c","text":"Change antibody isotype"},{"id":"d","text":"Enhance T cell activation"}],"answerId":"b","explanation":"Somatic hypermutation allows B cells to refine the affinity of their antibodies for specific antigens through mutation and selection.","kind":"recall","origin":"ai"},{"id":"germinal-center-antibody-response~ai-1","moduleId":"germinal-center-antibody-response","stem":"Which cytokine is primarily responsible for promoting class switching to IgE?","options":[{"id":"a","text":"IL-4"},{"id":"b","text":"IFN-γ"},{"id":"c","text":"TGF-β"},{"id":"d","text":"IL-10"}],"answerId":"a","explanation":"IL-4 is the key cytokine that drives class switching to IgE and IgG.","kind":"recall","origin":"ai"},{"id":"germinal-center-antibody-response~ai-2","moduleId":"germinal-center-antibody-response","stem":"A patient presents with high levels of IgM and low levels of IgG and IgA, along with absent germinal centers. What is the most likely underlying defect?","options":[{"id":"a","text":"T cell deficiency"},{"id":"b","text":"CD40L deficiency"},{"id":"c","text":"AID deficiency"},{"id":"d","text":"B cell receptor mutation"}],"answerId":"b","explanation":"This presentation is characteristic of a hyper-IgM syndrome, often caused by a defect in CD40L, preventing class switching.","kind":"clinical","origin":"ai"},{"id":"germinal-center-antibody-response~ai-3","moduleId":"germinal-center-antibody-response","stem":"Which statement about class switching is correct?","options":[{"id":"a","text":"It changes the antigen specificity of antibodies"},{"id":"b","text":"It alters the heavy-chain constant region only"},{"id":"c","text":"It affects the variable region of antibodies"},{"id":"d","text":"It occurs without T cell help"}],"answerId":"b","explanation":"Class switching only changes the heavy-chain constant region, maintaining the same antigen specificity.","kind":"trap","origin":"ai"},{"id":"germinal-center-antibody-response~ai-4","moduleId":"germinal-center-antibody-response","stem":"During a secondary immune response, which of the following is most likely to occur?","options":[{"id":"a","text":"High levels of IgM"},{"id":"b","text":"Rapid production of IgG"},{"id":"c","text":"Delayed response"},{"id":"d","text":"No memory B cells present"}],"answerId":"b","explanation":"The secondary immune response is characterized by a rapid and robust production of IgG due to memory B cells.","kind":"recall","origin":"ai"},{"id":"germinal-center-antibody-response~ai-5","moduleId":"germinal-center-antibody-response","stem":"How does the germinal center response contribute to vaccine efficacy?","options":[{"id":"a","text":"By producing IgM antibodies"},{"id":"b","text":"By generating memory B cells"},{"id":"c","text":"By increasing T cell activation"},{"id":"d","text":"By preventing somatic hypermutation"}],"answerId":"b","explanation":"The germinal center response generates memory B cells that provide a faster and stronger response upon re-exposure to the antigen, enhancing vaccine efficacy.","kind":"integration","linkedModuleIds":["vaccines-immunization"],"origin":"ai"},{"id":"germinal-center-antibody-response~ai-6","moduleId":"germinal-center-antibody-response","stem":"What is the role of follicular dendritic cells in the germinal center?","options":[{"id":"a","text":"Activate T cells"},{"id":"b","text":"Present antigens to B cells"},{"id":"c","text":"Induce class switching"},{"id":"d","text":"Produce antibodies"}],"answerId":"b","explanation":"Follicular dendritic cells present antigens to B cells, facilitating selection of high-affinity clones during affinity maturation.","kind":"mechanism","origin":"ai"},{"id":"germinal-center-antibody-response~ai-7","moduleId":"germinal-center-antibody-response","stem":"In the context of antibody classes, which function is primarily associated with IgA?","options":[{"id":"a","text":"Opsonization"},{"id":"b","text":"Mucosal immunity"},{"id":"c","text":"Complement activation"},{"id":"d","text":"Allergic responses"}],"answerId":"b","explanation":"IgA is primarily involved in mucosal immunity, protecting mucosal surfaces from pathogens.","kind":"integration","linkedModuleIds":["antibody-classes-functions"],"origin":"ai"}],"cd8-ctl-nk-effectors":[{"id":"cd8-ctl-nk-effectors~ai-0","moduleId":"cd8-ctl-nk-effectors","stem":"Which MHC class do CD8 cytotoxic T cells recognize for antigen presentation?","options":[{"id":"a","text":"MHC class I"},{"id":"b","text":"MHC class II"},{"id":"c","text":"MHC class III"},{"id":"d","text":"MHC class IV"}],"answerId":"a","explanation":"CD8 CTLs recognize antigens presented on MHC class I, which is found on all nucleated cells.","kind":"recall","origin":"ai"},{"id":"cd8-ctl-nk-effectors~ai-1","moduleId":"cd8-ctl-nk-effectors","stem":"What is the primary mechanism by which CD8 CTLs induce apoptosis in target cells?","options":[{"id":"a","text":"Caspase activation by cytokines"},{"id":"b","text":"Perforin and granzyme release"},{"id":"c","text":"Fas-FasL interaction"},{"id":"d","text":"Complement activation"}],"answerId":"b","explanation":"CD8 CTLs primarily induce apoptosis through the release of perforin and granzyme, which leads to cell death.","kind":"mechanism","origin":"ai"},{"id":"cd8-ctl-nk-effectors~ai-2","moduleId":"cd8-ctl-nk-effectors","stem":"A patient presents with disseminated mycobacterial infection. What is the most likely underlying defect?","options":[{"id":"a","text":"MHC class I deficiency"},{"id":"b","text":"IL-12/IFN-γ axis defect"},{"id":"c","text":"CD4 T cell deficiency"},{"id":"d","text":"B cell dysfunction"}],"answerId":"b","explanation":"Disseminated mycobacterial infections are commonly associated with defects in the IL-12/IFN-γ axis, affecting macrophage activation.","kind":"clinical","origin":"ai"},{"id":"cd8-ctl-nk-effectors~ai-3","moduleId":"cd8-ctl-nk-effectors","stem":"Which finding is characteristic of CD8 CTL-mediated apoptosis?","options":[{"id":"a","text":"Granuloma formation"},{"id":"b","text":"Target-cell apoptosis via perforin and granzyme"},{"id":"c","text":"Increased IgG production"},{"id":"d","text":"Th1 cell activation"}],"answerId":"b","explanation":"CD8 CTLs induce apoptosis in target cells primarily through the perforin and granzyme mechanism.","kind":"recall","origin":"ai"},{"id":"cd8-ctl-nk-effectors~ai-4","moduleId":"cd8-ctl-nk-effectors","stem":"Which of the following best describes the role of NK cells in the immune response?","options":[{"id":"a","text":"Recognizing and killing MHC class II presenting cells"},{"id":"b","text":"Killing cells with low MHC class I expression"},{"id":"c","text":"Producing antibodies against pathogens"},{"id":"d","text":"Activating CD4 T cells"}],"answerId":"b","explanation":"NK cells are responsible for killing 'missing-self' targets, which are characterized by low expression of MHC class I.","kind":"trap","origin":"ai"},{"id":"cd8-ctl-nk-effectors~ai-5","moduleId":"cd8-ctl-nk-effectors","stem":"How do CD8 CTLs and NK cells complement each other in immune defense?","options":[{"id":"a","text":"Both kill via complement activation"},{"id":"b","text":"Both target extracellular pathogens"},{"id":"c","text":"Both can kill cells with low MHC class I expression"},{"id":"d","text":"Both induce apoptosis through perforin and granzyme"}],"answerId":"d","explanation":"Both CD8 CTLs and NK cells can induce apoptosis in target cells through the perforin and granzyme pathway.","kind":"integration","linkedModuleIds":["innate-nk-interferon"],"origin":"ai"},{"id":"cd8-ctl-nk-effectors~ai-6","moduleId":"cd8-ctl-nk-effectors","stem":"What is the role of Th1 cells in enhancing CD8 CTL function?","options":[{"id":"a","text":"Producing antibodies"},{"id":"b","text":"Activating macrophages via IFN-γ"},{"id":"c","text":"Inducing apoptosis directly"},{"id":"d","text":"Inhibiting NK cell activity"}],"answerId":"b","explanation":"Th1 cells enhance CD8 CTL function by activating macrophages through the secretion of IFN-γ.","kind":"integration","linkedModuleIds":["t-cell-activation"],"origin":"ai"}],"t-cell-development-thymic-selection":[{"id":"t-cell-development-thymic-selection~ai-0","moduleId":"t-cell-development-thymic-selection","stem":"What is the primary outcome of positive selection in the thymus?","options":[{"id":"a","text":"Deletion of autoreactive T cells"},{"id":"b","text":"Survival of T cells that weakly bind self-MHC"},{"id":"c","text":"Maturation of T cells into regulatory T cells"},{"id":"d","text":"Exit of T cells to the peripheral circulation"}],"answerId":"b","explanation":"Positive selection ensures that thymocytes that can weakly bind self-MHC survive, allowing for an MHC-restricted T-cell repertoire.","kind":"recall","origin":"ai"},{"id":"t-cell-development-thymic-selection~ai-1","moduleId":"t-cell-development-thymic-selection","stem":"Which process is primarily responsible for the deletion of strongly self-reactive thymocytes?","options":[{"id":"a","text":"Positive selection"},{"id":"b","text":"Negative selection"},{"id":"c","text":"Anergy"},{"id":"d","text":"Peripheral tolerance"}],"answerId":"b","explanation":"Negative selection eliminates thymocytes that bind self-peptides too strongly, promoting central tolerance.","kind":"recall","origin":"ai"},{"id":"t-cell-development-thymic-selection~ai-2","moduleId":"t-cell-development-thymic-selection","stem":"A mutation in the AIRE gene would most likely lead to which clinical finding?","options":[{"id":"a","text":"Increased T-cell maturation"},{"id":"b","text":"Multi-organ autoimmunity"},{"id":"c","text":"Enhanced positive selection"},{"id":"d","text":"Decreased T-cell activation"}],"answerId":"b","explanation":"AIRE mutations impair negative selection, leading to the survival of autoreactive T cells and resulting in multi-organ autoimmunity.","kind":"recall","origin":"ai"},{"id":"t-cell-development-thymic-selection~ai-3","moduleId":"t-cell-development-thymic-selection","stem":"What is the primary mechanism by which regulatory T cells prevent autoimmunity?","options":[{"id":"a","text":"Positive selection"},{"id":"b","text":"Negative selection"},{"id":"c","text":"Anergy"},{"id":"d","text":"Cytokine suppression"}],"answerId":"d","explanation":"Regulatory T cells suppress autoreactive T cells through the release of inhibitory cytokines, contributing to peripheral tolerance.","kind":"mechanism","origin":"ai"},{"id":"t-cell-development-thymic-selection~ai-4","moduleId":"t-cell-development-thymic-selection","stem":"Which statement correctly describes the two-step selection process in T-cell development?","options":[{"id":"a","text":"Positive selection deletes self-reactive T cells"},{"id":"b","text":"Negative selection keeps cells that recognize self-MHC"},{"id":"c","text":"Positive selection keeps cells that recognize self-MHC"},{"id":"d","text":"Negative selection promotes T-cell maturation"}],"answerId":"c","explanation":"Positive selection retains thymocytes that can weakly bind self-MHC, while negative selection removes those that react strongly to self-antigens.","kind":"trap","origin":"ai"},{"id":"t-cell-development-thymic-selection~ai-5","moduleId":"t-cell-development-thymic-selection","stem":"How does the failure of peripheral tolerance mechanisms contribute to autoimmunity?","options":[{"id":"a","text":"By enhancing positive selection"},{"id":"b","text":"By allowing autoreactive T cells to escape deletion"},{"id":"c","text":"By promoting T-cell activation"},{"id":"d","text":"By increasing regulatory T cell numbers"}],"answerId":"b","explanation":"Failure of peripheral tolerance mechanisms allows autoreactive T cells that escaped thymic selection to become activated, leading to autoimmunity.","kind":"clinical","origin":"ai"},{"id":"t-cell-development-thymic-selection~ai-6","moduleId":"t-cell-development-thymic-selection","stem":"Which aspect of T-cell development is directly linked to MHC structure and genetics?","options":[{"id":"a","text":"Positive selection"},{"id":"b","text":"Negative selection"},{"id":"c","text":"T-cell activation"},{"id":"d","text":"Regulatory T-cell formation"}],"answerId":"a","explanation":"Positive selection is dependent on the ability of TCRs to recognize self-MHC, which is determined by MHC structure and genetics.","kind":"integration","linkedModuleIds":["mhc-structure-genetics"],"origin":"ai"},{"id":"t-cell-development-thymic-selection~ai-7","moduleId":"t-cell-development-thymic-selection","stem":"How does thymic selection relate to mechanisms of autoimmunity?","options":[{"id":"a","text":"It prevents all forms of autoimmunity"},{"id":"b","text":"It ensures only non-autoreactive T cells enter circulation"},{"id":"c","text":"It enhances T-cell activation in the periphery"},{"id":"d","text":"It increases the number of autoreactive T cells"}],"answerId":"b","explanation":"Thymic selection aims to eliminate autoreactive T cells, thus ensuring that only non-autoreactive T cells enter the peripheral circulation.","kind":"integration","linkedModuleIds":["tolerance-autoimmunity-mechanisms"],"origin":"ai"}],"immunity-viruses-fungi-parasites":[{"id":"immunity-viruses-fungi-parasites~ai-0","moduleId":"immunity-viruses-fungi-parasites","stem":"What is the primary mechanism by which CD8 cytotoxic T lymphocytes (CTLs) eliminate virus-infected cells?","options":[{"id":"a","text":"Neutralization of free virus"},{"id":"b","text":"MHC I-restricted killing"},{"id":"c","text":"Activation of macrophages"},{"id":"d","text":"Induction of apoptosis in B cells"}],"answerId":"b","explanation":"CD8 CTLs recognize and kill virus-infected cells through MHC I presentation of viral peptides.","kind":"recall","origin":"ai"},{"id":"immunity-viruses-fungi-parasites~ai-1","moduleId":"immunity-viruses-fungi-parasites","stem":"Which cytokines are primarily involved in the Th2 response to helminth infections?","options":[{"id":"a","text":"IL-1, IL-6, IL-12"},{"id":"b","text":"IL-2, IL-4, IL-10"},{"id":"c","text":"IL-4, IL-5, IL-13"},{"id":"d","text":"IFN-γ, TNF-α, IL-17"}],"answerId":"c","explanation":"IL-4, IL-5, and IL-13 are key cytokines that drive the Th2 immune response against helminths.","kind":"recall","origin":"ai"},{"id":"immunity-viruses-fungi-parasites~ai-2","moduleId":"immunity-viruses-fungi-parasites","stem":"What is the clinical significance of non-neutralising antibodies in dengue infections?","options":[{"id":"a","text":"They always provide immunity against reinfection"},{"id":"b","text":"They can enhance severity of secondary infections"},{"id":"c","text":"They prevent viral entry into host cells"},{"id":"d","text":"They are ineffective against all serotypes"}],"answerId":"b","explanation":"Non-neutralising antibodies can enhance the severity of secondary dengue infections through antibody-dependent enhancement (ADE).","kind":"trap","origin":"ai"},{"id":"immunity-viruses-fungi-parasites~ai-3","moduleId":"immunity-viruses-fungi-parasites","stem":"Which immune cells are primarily responsible for antifungal defense against Candida infections?","options":[{"id":"a","text":"B cells"},{"id":"b","text":"Neutrophils"},{"id":"c","text":"CD4 T cells"},{"id":"d","text":"Natural killer cells"}],"answerId":"b","explanation":"Neutrophils are crucial for the defense against invasive fungal infections like Candida.","kind":"recall","origin":"ai"},{"id":"immunity-viruses-fungi-parasites~ai-4","moduleId":"immunity-viruses-fungi-parasites","stem":"A patient presents with eosinophilia and elevated IgE levels. Which type of immune response is likely involved?","options":[{"id":"a","text":"Th1 response"},{"id":"b","text":"Th2 response"},{"id":"c","text":"Innate immune response"},{"id":"d","text":"Cell-mediated immunity"}],"answerId":"b","explanation":"Eosinophilia and high IgE are characteristic of a Th2 immune response, typically seen in helminth infections.","kind":"clinical","origin":"ai"},{"id":"immunity-viruses-fungi-parasites~ai-5","moduleId":"immunity-viruses-fungi-parasites","stem":"How does the influenza virus evade the immune response?","options":[{"id":"a","text":"By inducing apoptosis in T cells"},{"id":"b","text":"Through antigenic drift and shift"},{"id":"c","text":"By blocking phagocytosis"},{"id":"d","text":"By down-regulating MHC II"}],"answerId":"b","explanation":"Influenza evades immunity primarily through antigenic drift and shift, leading to changes in its surface antigens.","kind":"mechanism","origin":"ai"},{"id":"immunity-viruses-fungi-parasites~ai-6","moduleId":"immunity-viruses-fungi-parasites","stem":"Which antiviral drug class is commonly used to treat respiratory viral infections?","options":[{"id":"a","text":"NRTIs"},{"id":"b","text":"Protease inhibitors"},{"id":"c","text":"Neuraminidase inhibitors"},{"id":"d","text":"Integrase inhibitors"}],"answerId":"c","explanation":"Neuraminidase inhibitors are commonly used to treat respiratory infections caused by influenza viruses.","kind":"integration","linkedModuleIds":["respiratory-antiviral-drugs"],"origin":"ai"},{"id":"immunity-viruses-fungi-parasites~ai-7","moduleId":"immunity-viruses-fungi-parasites","stem":"In a patient with a history of severe dengue, which immune mechanism is most likely responsible for their increased risk during a second infection?","options":[{"id":"a","text":"MHC I down-regulation"},{"id":"b","text":"Antibody-dependent enhancement"},{"id":"c","text":"Increased Th1 response"},{"id":"d","text":"Decreased IgE production"}],"answerId":"b","explanation":"Antibody-dependent enhancement (ADE) can lead to severe disease in patients with prior dengue infection due to non-neutralising antibodies.","kind":"integration","linkedModuleIds":["respiratory-antiviral-drugs"],"origin":"ai"}],"secondary-immunodeficiency-hiv":[{"id":"secondary-immunodeficiency-hiv~ai-0","moduleId":"secondary-immunodeficiency-hiv","stem":"What is the primary mechanism by which HIV causes immunodeficiency?","options":[{"id":"a","text":"Direct destruction of CD8+ T cells"},{"id":"b","text":"Depletion of CD4+ T cells"},{"id":"c","text":"Inhibition of B cell activation"},{"id":"d","text":"Increased production of antibodies"}],"answerId":"b","explanation":"HIV primarily infects and depletes CD4+ T cells, leading to a collapse of cell-mediated immunity.","kind":"mechanism","origin":"ai"},{"id":"secondary-immunodeficiency-hiv~ai-1","moduleId":"secondary-immunodeficiency-hiv","stem":"Which of the following is an AIDS-defining illness?","options":[{"id":"a","text":"Chronic bronchitis"},{"id":"b","text":"Pneumocystis jirovecii pneumonia"},{"id":"c","text":"Tuberculosis (latent)"},{"id":"d","text":"Asthma"}],"answerId":"b","explanation":"Pneumocystis jirovecii pneumonia is a classic AIDS-defining illness associated with low CD4 counts.","kind":"recall","origin":"ai"},{"id":"secondary-immunodeficiency-hiv~ai-2","moduleId":"secondary-immunodeficiency-hiv","stem":"A patient with HIV presents with a CD4 count of 150/µL. Which opportunistic infection is he at highest risk for?","options":[{"id":"a","text":"Bacterial pneumonia"},{"id":"b","text":"Toxoplasmosis"},{"id":"c","text":"Pneumocystis jirovecii pneumonia"},{"id":"d","text":"Candidiasis"}],"answerId":"c","explanation":"With a CD4 count below 200/µL, the patient is at high risk for Pneumocystis jirovecii pneumonia.","kind":"clinical","origin":"ai"},{"id":"secondary-immunodeficiency-hiv~ai-3","moduleId":"secondary-immunodeficiency-hiv","stem":"After chemotherapy, a patient develops neutropenic fever. What is the underlying cause of this condition?","options":[{"id":"a","text":"Primary immunodeficiency"},{"id":"b","text":"Acquired loss of neutrophils"},{"id":"c","text":"Increased antibody production"},{"id":"d","text":"Enhanced phagocytic activity"}],"answerId":"b","explanation":"Chemotherapy can lead to neutropenia, resulting in an increased risk of bacterial and fungal infections.","kind":"mechanism","origin":"ai"},{"id":"secondary-immunodeficiency-hiv~ai-4","moduleId":"secondary-immunodeficiency-hiv","stem":"Which of the following statements about secondary immunodeficiency is true?","options":[{"id":"a","text":"It is primarily caused by genetic defects."},{"id":"b","text":"It is less common than primary immunodeficiency."},{"id":"c","text":"Malnutrition is a leading cause worldwide."},{"id":"d","text":"It only occurs in adults."}],"answerId":"c","explanation":"Secondary immunodeficiency is far more common than primary and can be caused by malnutrition, among other factors.","kind":"trap","origin":"ai"},{"id":"secondary-immunodeficiency-hiv~ai-5","moduleId":"secondary-immunodeficiency-hiv","stem":"A patient with a history of splenectomy presents with overwhelming sepsis. Which organism is he most susceptible to?","options":[{"id":"a","text":"Staphylococcus aureus"},{"id":"b","text":"Streptococcus pneumoniae"},{"id":"c","text":"Escherichia coli"},{"id":"d","text":"Mycobacterium tuberculosis"}],"answerId":"b","explanation":"Patients without a spleen are particularly susceptible to encapsulated bacteria, especially Streptococcus pneumoniae.","kind":"clinical","origin":"ai"},{"id":"secondary-immunodeficiency-hiv~ai-6","moduleId":"secondary-immunodeficiency-hiv","stem":"How does the mechanism of immunodeficiency differ between HIV/AIDS and primary antibody deficiencies?","options":[{"id":"a","text":"HIV causes direct B cell dysfunction, while primary deficiencies affect T cells."},{"id":"b","text":"HIV leads to CD4+ T cell depletion, while primary deficiencies involve specific antibody production defects."},{"id":"c","text":"Both conditions result in neutropenia."},{"id":"d","text":"HIV primarily affects phagocytes, while primary deficiencies affect T cells."}],"answerId":"b","explanation":"HIV leads to depletion of CD4+ T cells, while primary antibody deficiencies specifically affect the ability to produce antibodies.","kind":"integration","linkedModuleIds":["primary-immunodeficiency-antibody-t"],"origin":"ai"},{"id":"secondary-immunodeficiency-hiv~ai-7","moduleId":"secondary-immunodeficiency-hiv","stem":"In patients with primary immunodeficiency disorders, what is a common clinical finding that differs from those with secondary immunodeficiency due to HIV?","options":[{"id":"a","text":"Recurrent bacterial infections"},{"id":"b","text":"Opportunistic infections"},{"id":"c","text":"Autoimmune disorders"},{"id":"d","text":"Malignancies"}],"answerId":"a","explanation":"Patients with primary immunodeficiencies often present with recurrent bacterial infections, while those with HIV are more prone to opportunistic infections.","kind":"integration","linkedModuleIds":["primary-immunodeficiency-phagocyte-complement"],"origin":"ai"}],"humoral-response-b-activation":[{"id":"humoral-response-b-activation~ai-0","moduleId":"humoral-response-b-activation","stem":"What is the primary mechanism by which T-dependent B-cell activation occurs?","options":[{"id":"a","text":"BCR cross-linking by repetitive antigens"},{"id":"b","text":"CD40L–CD40 interaction with T cells"},{"id":"c","text":"Direct recognition of antigens by B cells"},{"id":"d","text":"Antigen presentation on MHC I"}],"answerId":"b","explanation":"T-dependent B-cell activation requires CD40L–CD40 interaction for signal 2, alongside antigen recognition.","kind":"mechanism","origin":"ai"},{"id":"humoral-response-b-activation~ai-1","moduleId":"humoral-response-b-activation","stem":"Which type of antibody is primarily produced in response to T-independent antigens?","options":[{"id":"a","text":"IgG"},{"id":"b","text":"IgA"},{"id":"c","text":"IgM"},{"id":"d","text":"IgE"}],"answerId":"c","explanation":"T-independent antigens typically elicit a response dominated by low-affinity IgM antibodies.","kind":"recall","origin":"ai"},{"id":"humoral-response-b-activation~ai-2","moduleId":"humoral-response-b-activation","stem":"Why do plain polysaccharide vaccines have poor immunogenicity in infants?","options":[{"id":"a","text":"Infants cannot produce any antibodies"},{"id":"b","text":"Polysaccharides are T-independent antigens"},{"id":"c","text":"Infants lack B cells"},{"id":"d","text":"Polysaccharides induce only IgG responses"}],"answerId":"b","explanation":"Polysaccharides are T-independent, leading to weak responses without T-cell help, especially in infants.","kind":"trap","origin":"ai"},{"id":"humoral-response-b-activation~ai-3","moduleId":"humoral-response-b-activation","stem":"What is the role of follicular helper T (Tfh) cells in B-cell activation?","options":[{"id":"a","text":"They produce antibodies directly"},{"id":"b","text":"They provide cytokine support and CD40L interaction"},{"id":"c","text":"They present antigens to B cells"},{"id":"d","text":"They enhance phagocytosis of antigens"}],"answerId":"b","explanation":"Tfh cells provide essential signals through cytokines and CD40L for T-dependent B-cell activation.","kind":"mechanism","origin":"ai"},{"id":"humoral-response-b-activation~ai-4","moduleId":"humoral-response-b-activation","stem":"Which of the following vaccines is an example of a conjugate vaccine?","options":[{"id":"a","text":"Pneumococcal polysaccharide vaccine"},{"id":"b","text":"Hib vaccine"},{"id":"c","text":"Influenza vaccine"},{"id":"d","text":"Tetanus toxoid vaccine"}],"answerId":"b","explanation":"The Hib vaccine is a conjugate vaccine that links a polysaccharide to a protein to enhance T-cell help.","kind":"recall","origin":"ai"},{"id":"humoral-response-b-activation~ai-5","moduleId":"humoral-response-b-activation","stem":"How does the germinal center reaction contribute to antibody affinity maturation?","options":[{"id":"a","text":"By promoting class switching only"},{"id":"b","text":"By allowing somatic hypermutation and selection of high-affinity B cells"},{"id":"c","text":"By increasing the number of B cells"},{"id":"d","text":"By enhancing T-cell activation"}],"answerId":"b","explanation":"The germinal center reaction involves somatic hypermutation and selection, leading to higher affinity antibodies.","kind":"mechanism","origin":"ai"},{"id":"humoral-response-b-activation~ai-6","moduleId":"humoral-response-b-activation","stem":"In the context of B-cell activation, how does the linked recognition principle apply to conjugate vaccines?","options":[{"id":"a","text":"B cells recognize polysaccharides only"},{"id":"b","text":"T cells and B cells recognize different epitopes of the same antigen"},{"id":"c","text":"B cells do not require T-cell help"},{"id":"d","text":"T cells provide help only for protein antigens"}],"answerId":"b","explanation":"Linked recognition allows B cells to receive T-cell help by recognizing different epitopes of the same antigen in conjugate vaccines.","kind":"integration","linkedModuleIds":["vaccines-immunization"],"origin":"ai"},{"id":"humoral-response-b-activation~ai-7","moduleId":"humoral-response-b-activation","stem":"Which immunoglobulin class is primarily involved in T-dependent responses and provides long-term immunity?","options":[{"id":"a","text":"IgM"},{"id":"b","text":"IgA"},{"id":"c","text":"IgG"},{"id":"d","text":"IgE"}],"answerId":"c","explanation":"IgG is the main antibody produced in T-dependent responses, providing high affinity and memory.","kind":"integration","linkedModuleIds":["antibody-classes-functions"],"origin":"ai"}],"primary-immunodeficiency-phagocyte-complement":[{"id":"primary-immunodeficiency-phagocyte-complement~ai-0","moduleId":"primary-immunodeficiency-phagocyte-complement","stem":"What is the primary defect in Chronic Granulomatous Disease (CGD)?","options":[{"id":"a","text":"Defective β2-integrin"},{"id":"b","text":"Impaired lysosome fusion"},{"id":"c","text":"Defective NADPH oxidase"},{"id":"d","text":"C1-inhibitor deficiency"}],"answerId":"c","explanation":"CGD is caused by a defect in NADPH oxidase, leading to impaired respiratory burst and susceptibility to catalase-positive organisms.","kind":"recall","origin":"ai"},{"id":"primary-immunodeficiency-phagocyte-complement~ai-1","moduleId":"primary-immunodeficiency-phagocyte-complement","stem":"Which test is used to diagnose Chronic Granulomatous Disease?","options":[{"id":"a","text":"DHR flow test"},{"id":"b","text":"Complement fixation test"},{"id":"c","text":"Skin prick test"},{"id":"d","text":"ELISA for IgG"}],"answerId":"a","explanation":"The DHR (dihydrorhodamine) flow test assesses the respiratory burst in phagocytes, confirming CGD.","kind":"recall","origin":"ai"},{"id":"primary-immunodeficiency-phagocyte-complement~ai-2","moduleId":"primary-immunodeficiency-phagocyte-complement","stem":"A patient presents with recurrent infections and delayed umbilical cord separation. Which condition is most likely?","options":[{"id":"a","text":"Chronic Granulomatous Disease"},{"id":"b","text":"Leukocyte Adhesion Deficiency"},{"id":"c","text":"C1-inhibitor deficiency"},{"id":"d","text":"Chédiak-Higashi syndrome"}],"answerId":"b","explanation":"Delayed umbilical cord separation and recurrent infections without pus are characteristic of Leukocyte Adhesion Deficiency.","kind":"clinical","origin":"ai"},{"id":"primary-immunodeficiency-phagocyte-complement~ai-3","moduleId":"primary-immunodeficiency-phagocyte-complement","stem":"Why are patients with Chronic Granulomatous Disease particularly susceptible to catalase-positive organisms?","options":[{"id":"a","text":"They lack antibodies"},{"id":"b","text":"They have defective phagocyte migration"},{"id":"c","text":"Catalase-positive organisms destroy their own H₂O₂"},{"id":"d","text":"They cannot produce any reactive oxygen species"}],"answerId":"c","explanation":"Catalase-positive organisms can neutralize H₂O₂, which is essential for killing since CGD patients cannot generate it due to NADPH oxidase deficiency.","kind":"trap","origin":"ai"},{"id":"primary-immunodeficiency-phagocyte-complement~ai-4","moduleId":"primary-immunodeficiency-phagocyte-complement","stem":"Which of the following findings is characteristic of Chédiak-Higashi syndrome?","options":[{"id":"a","text":"Giant cytoplasmic granules in leukocytes"},{"id":"b","text":"Recurrent Neisseria infections"},{"id":"c","text":"Delayed umbilical cord separation"},{"id":"d","text":"Negative DHR test"}],"answerId":"a","explanation":"Chédiak-Higashi syndrome is marked by the presence of giant granules in leukocytes due to impaired lysosomal fusion.","kind":"recall","origin":"ai"},{"id":"primary-immunodeficiency-phagocyte-complement~ai-5","moduleId":"primary-immunodeficiency-phagocyte-complement","stem":"A patient with recurrent Neisseria infections is suspected to have a complement deficiency. Which complement component is likely deficient?","options":[{"id":"a","text":"C1"},{"id":"b","text":"C3"},{"id":"c","text":"C5"},{"id":"d","text":"C9"}],"answerId":"c","explanation":"Deficiency in terminal complement components (C5–C9) leads to increased susceptibility to Neisseria infections.","kind":"recall","origin":"ai"},{"id":"primary-immunodeficiency-phagocyte-complement~ai-6","moduleId":"primary-immunodeficiency-phagocyte-complement","stem":"How does complement deficiency relate to antibody deficiencies in primary immunodeficiencies?","options":[{"id":"a","text":"Both lead to recurrent viral infections"},{"id":"b","text":"Both impair opsonization of pathogens"},{"id":"c","text":"Both affect T-cell function"},{"id":"d","text":"Both are caused by genetic mutations"}],"answerId":"b","explanation":"Complement deficiencies impair opsonization, similar to how antibody deficiencies reduce the ability to opsonize pathogens, leading to increased infections.","kind":"integration","linkedModuleIds":["primary-immunodeficiency-antibody-t"],"origin":"ai"},{"id":"primary-immunodeficiency-phagocyte-complement~ai-7","moduleId":"primary-immunodeficiency-phagocyte-complement","stem":"What is the relationship between phagocyte defects and extracellular bacterial infections?","options":[{"id":"a","text":"Phagocyte defects primarily affect viral infections"},{"id":"b","text":"Phagocyte defects increase susceptibility to all bacteria"},{"id":"c","text":"Phagocyte defects lead to recurrent infections with encapsulated bacteria"},{"id":"d","text":"Phagocyte defects specifically predispose to infections with catalase-positive organisms"}],"answerId":"d","explanation":"Phagocyte defects, such as in CGD, specifically increase susceptibility to catalase-positive organisms due to impaired oxidative burst.","kind":"integration","linkedModuleIds":["immunity-bacteria-extracellular-intracellular"],"origin":"ai"}],"primary-immunodeficiency-antibody-t":[{"id":"primary-immunodeficiency-antibody-t~ai-0","moduleId":"primary-immunodeficiency-antibody-t","stem":"A 6-month-old boy presents with recurrent pyogenic infections and laboratory tests reveal absent B cells and low immunoglobulin levels. What is the most likely diagnosis?","options":[{"id":"a","text":"Selective IgA deficiency"},{"id":"b","text":"X-linked agammaglobulinaemia"},{"id":"c","text":"Common Variable Immunodeficiency"},{"id":"d","text":"Hyper-IgM syndrome"}],"answerId":"b","explanation":"The absence of B cells and low immunoglobulin levels in a male infant strongly suggests X-linked agammaglobulinaemia due to a BTK defect.","kind":"recall","origin":"ai"},{"id":"primary-immunodeficiency-antibody-t~ai-1","moduleId":"primary-immunodeficiency-antibody-t","stem":"Which immunological defect is characterized by high levels of IgM and low levels of IgG, IgA, and IgE, along with susceptibility to opportunistic infections?","options":[{"id":"a","text":"Common Variable Immunodeficiency"},{"id":"b","text":"Hyper-IgM syndrome"},{"id":"c","text":"X-linked agammaglobulinaemia"},{"id":"d","text":"Selective IgA deficiency"}],"answerId":"b","explanation":"Hyper-IgM syndrome is due to a CD40L defect leading to impaired class switching, resulting in high IgM and low IgG/A/E levels.","kind":"recall","origin":"ai"},{"id":"primary-immunodeficiency-antibody-t~ai-2","moduleId":"primary-immunodeficiency-antibody-t","stem":"A 3-year-old boy with eczema, recurrent infections, and thrombocytopenia is suspected to have a primary immunodeficiency. Which condition is most likely?","options":[{"id":"a","text":"Wiskott-Aldrich syndrome"},{"id":"b","text":"X-linked agammaglobulinaemia"},{"id":"c","text":"Hyper-IgM syndrome"},{"id":"d","text":"Common Variable Immunodeficiency"}],"answerId":"a","explanation":"Wiskott-Aldrich syndrome is characterized by the triad of eczema, recurrent infections, and thrombocytopenia.","kind":"recall","origin":"ai"},{"id":"primary-immunodeficiency-antibody-t~ai-3","moduleId":"primary-immunodeficiency-antibody-t","stem":"In a patient with DiGeorge syndrome, which of the following findings would you expect?","options":[{"id":"a","text":"High IgM levels"},{"id":"b","text":"Thymic hypoplasia"},{"id":"c","text":"Normal calcium levels"},{"id":"d","text":"Increased B cells"}],"answerId":"b","explanation":"DiGeorge syndrome is associated with thymic hypoplasia leading to T-cell deficiency and often presents with hypocalcaemia.","kind":"recall","origin":"ai"},{"id":"primary-immunodeficiency-antibody-t~ai-4","moduleId":"primary-immunodeficiency-antibody-t","stem":"A patient with selective IgA deficiency experiences anaphylaxis after receiving blood transfusion. What is the underlying mechanism?","options":[{"id":"a","text":"IgA deficiency always leads to severe infections"},{"id":"b","text":"Presence of anti-IgA antibodies"},{"id":"c","text":"Inability to produce IgM"},{"id":"d","text":"Defective T-cell activation"}],"answerId":"b","explanation":"Selective IgA deficiency can lead to anaphylaxis due to the presence of anti-IgA antibodies in individuals receiving IgA-containing products.","kind":"trap","origin":"ai"},{"id":"primary-immunodeficiency-antibody-t~ai-5","moduleId":"primary-immunodeficiency-antibody-t","stem":"A 2-month-old infant presents with failure to thrive, chronic diarrhea, and oral thrush. Laboratory tests show absent T cells. What is the most likely diagnosis?","options":[{"id":"a","text":"Hyper-IgM syndrome"},{"id":"b","text":"X-linked agammaglobulinaemia"},{"id":"c","text":"Severe Combined Immunodeficiency"},{"id":"d","text":"Common Variable Immunodeficiency"}],"answerId":"c","explanation":"The presentation of absent T cells and severe symptoms in infancy is characteristic of Severe Combined Immunodeficiency (SCID).","kind":"recall","origin":"ai"},{"id":"primary-immunodeficiency-antibody-t~ai-6","moduleId":"primary-immunodeficiency-antibody-t","stem":"How does the defect in antigen presentation relate to primary immunodeficiency disorders?","options":[{"id":"a","text":"It leads to increased B cell activation"},{"id":"b","text":"It causes T cell deficiencies"},{"id":"c","text":"It results in autoimmunity"},{"id":"d","text":"It enhances phagocyte function"}],"answerId":"b","explanation":"Defective antigen presentation can lead to T cell deficiencies, as seen in Bare Lymphocyte Syndromes, which are a type of primary immunodeficiency.","kind":"integration","linkedModuleIds":["antigen-processing-presentation"],"origin":"ai"},{"id":"primary-immunodeficiency-antibody-t~ai-7","moduleId":"primary-immunodeficiency-antibody-t","stem":"Which primary immunodeficiency disorder is most likely to affect the humoral immune response due to a defect in B cell activation?","options":[{"id":"a","text":"X-linked agammaglobulinaemia"},{"id":"b","text":"Common Variable Immunodeficiency"},{"id":"c","text":"Hyper-IgM syndrome"},{"id":"d","text":"Wiskott-Aldrich syndrome"}],"answerId":"b","explanation":"Common Variable Immunodeficiency (CVID) primarily affects B cell activation and leads to decreased antibody production.","kind":"integration","linkedModuleIds":["humoral-response-b-activation"],"origin":"ai"}],"mucosal-immune-system":[{"id":"mucosal-immune-system~ai-0","moduleId":"mucosal-immune-system","stem":"What is the primary antibody produced at mucosal surfaces?","options":[{"id":"a","text":"IgG"},{"id":"b","text":"IgM"},{"id":"c","text":"Secretory IgA"},{"id":"d","text":"IgE"}],"answerId":"c","explanation":"Secretory IgA is the most abundantly produced antibody at mucosal surfaces, providing crucial immune exclusion.","kind":"recall","origin":"ai"},{"id":"mucosal-immune-system~ai-1","moduleId":"mucosal-immune-system","stem":"Which cells are responsible for sampling luminal antigens in the gut?","options":[{"id":"a","text":"Dendritic cells"},{"id":"b","text":"M (microfold) cells"},{"id":"c","text":"B cells"},{"id":"d","text":"T cells"}],"answerId":"b","explanation":"M (microfold) cells overlie Peyer's patches and are specialized for sampling luminal antigens.","kind":"mechanism","origin":"ai"},{"id":"mucosal-immune-system~ai-2","moduleId":"mucosal-immune-system","stem":"What mechanism protects secretory IgA from degradation in the gut?","options":[{"id":"a","text":"Transcytosis by pIgR"},{"id":"b","text":"Binding to pathogens"},{"id":"c","text":"Complement activation"},{"id":"d","text":"IgG binding"}],"answerId":"a","explanation":"The polymeric Ig receptor (pIgR) mediates transcytosis of IgA, leaving a secretory component that protects it from proteases.","kind":"mechanism","origin":"ai"},{"id":"mucosal-immune-system~ai-3","moduleId":"mucosal-immune-system","stem":"A patient presents with recurrent gastrointestinal infections. Which immunoglobulin deficiency is most likely responsible?","options":[{"id":"a","text":"IgM deficiency"},{"id":"b","text":"IgA deficiency"},{"id":"c","text":"IgG deficiency"},{"id":"d","text":"IgE deficiency"}],"answerId":"b","explanation":"IgA deficiency leads to a loss of secretory IgA barrier defense, resulting in recurrent mucosal infections.","kind":"clinical","origin":"ai"},{"id":"mucosal-immune-system~ai-4","moduleId":"mucosal-immune-system","stem":"Which pathogen is known to exploit M cells to invade the gut epithelium?","options":[{"id":"a","text":"E. coli"},{"id":"b","text":"Salmonella"},{"id":"c","text":"Shigella"},{"id":"d","text":"Clostridium"}],"answerId":"b","explanation":"Salmonella can invade the gut epithelium by exploiting M cells over Peyer's patches.","kind":"trap","origin":"ai"},{"id":"mucosal-immune-system~ai-5","moduleId":"mucosal-immune-system","stem":"How does secretory IgA contribute to mucosal immunity?","options":[{"id":"a","text":"Activates complement"},{"id":"b","text":"Triggers inflammation"},{"id":"c","text":"Neutralizes and traps microbes"},{"id":"d","text":"Enhances phagocytosis"}],"answerId":"c","explanation":"Secretory IgA works by immune exclusion, neutralizing and trapping microbes without triggering inflammation.","kind":"mechanism","origin":"ai"},{"id":"mucosal-immune-system~ai-6","moduleId":"mucosal-immune-system","stem":"How does exposure to antigens at one mucosal site affect distant mucosal sites?","options":[{"id":"a","text":"Increases IgG production"},{"id":"b","text":"Generates systemic immunity"},{"id":"c","text":"Promotes IgA plasma cell generation"},{"id":"d","text":"Decreases immune response"}],"answerId":"c","explanation":"Antigen exposure at one mucosal site can lead to the generation of IgA plasma cells at distant mucosal sites, a feature of the common mucosal immune system.","kind":"integration","linkedModuleIds":["oral-tolerance-microbiota"],"origin":"ai"},{"id":"mucosal-immune-system~ai-7","moduleId":"mucosal-immune-system","stem":"Which cytokines promote IgA class switching in B cells?","options":[{"id":"a","text":"IL-2 and IL-4"},{"id":"b","text":"TGF-β, APRIL, and BAFF"},{"id":"c","text":"IFN-γ and IL-12"},{"id":"d","text":"TNF-α and IL-6"}],"answerId":"b","explanation":"TGF-β, APRIL, and BAFF are key cytokines that promote IgA class switching in B cells.","kind":"integration","linkedModuleIds":["primary-immunodeficiency-antibody-t"],"origin":"ai"}],"immunoassays-techniques":[{"id":"immunoassays-techniques~ai-0","moduleId":"immunoassays-techniques","stem":"What is the primary purpose of using ELISA in clinical diagnostics?","options":[{"id":"a","text":"To confirm a diagnosis"},{"id":"b","text":"To quantify antigen or antibody levels"},{"id":"c","text":"To visualize cellular structures"},{"id":"d","text":"To separate proteins by size"}],"answerId":"b","explanation":"ELISA is primarily used for quantifying antigen or antibody levels in a sample.","kind":"recall","origin":"ai"},{"id":"immunoassays-techniques~ai-1","moduleId":"immunoassays-techniques","stem":"Which assay is typically used as a confirmatory test after a positive HIV screening?","options":[{"id":"a","text":"ELISA"},{"id":"b","text":"Western blot"},{"id":"c","text":"Immunofluorescence"},{"id":"d","text":"Flow cytometry"}],"answerId":"b","explanation":"Western blot is used as a confirmatory test following a positive ELISA screening for HIV.","kind":"recall","origin":"ai"},{"id":"immunoassays-techniques~ai-2","moduleId":"immunoassays-techniques","stem":"In flow cytometry, what is the role of fluorochrome-labelled antibodies?","options":[{"id":"a","text":"To separate proteins by size"},{"id":"b","text":"To visualize antigen-antibody interactions"},{"id":"c","text":"To quantify cell types"},{"id":"d","text":"To enhance enzyme activity"}],"answerId":"c","explanation":"Fluorochrome-labelled antibodies are used in flow cytometry to quantify and analyze different cell types based on surface markers.","kind":"mechanism","origin":"ai"},{"id":"immunoassays-techniques~ai-3","moduleId":"immunoassays-techniques","stem":"A patient has a positive ANA test. Which technique would help identify specific autoantibodies?","options":[{"id":"a","text":"ELISA"},{"id":"b","text":"Western blot"},{"id":"c","text":"Immunofluorescence"},{"id":"d","text":"Flow cytometry"}],"answerId":"c","explanation":"Immunofluorescence is used to identify specific autoantibodies by visualizing their binding to antigens in tissue sections.","kind":"clinical","origin":"ai"},{"id":"immunoassays-techniques~ai-4","moduleId":"immunoassays-techniques","stem":"What is the correct sequence of tests in the standard HIV testing algorithm?","options":[{"id":"a","text":"Western blot followed by ELISA"},{"id":"b","text":"ELISA followed by Western blot"},{"id":"c","text":"Flow cytometry followed by ELISA"},{"id":"d","text":"Immunofluorescence followed by Western blot"}],"answerId":"b","explanation":"The standard algorithm starts with a sensitive screening test (ELISA) followed by a specific confirmatory test (Western blot).","kind":"trap","origin":"ai"},{"id":"immunoassays-techniques~ai-5","moduleId":"immunoassays-techniques","stem":"How does flow cytometry assist in the diagnosis of leukemia?","options":[{"id":"a","text":"By measuring enzyme activity"},{"id":"b","text":"By counting cells based on size"},{"id":"c","text":"By immunophenotyping using CD markers"},{"id":"d","text":"By visualizing cellular morphology"}],"answerId":"c","explanation":"Flow cytometry assists in leukemia diagnosis by immunophenotyping cells using specific CD markers to identify cell types.","kind":"recall","origin":"ai"},{"id":"immunoassays-techniques~ai-6","moduleId":"immunoassays-techniques","stem":"Which technique would be most appropriate for quantifying CD4 T-cells in an HIV patient?","options":[{"id":"a","text":"ELISA"},{"id":"b","text":"Western blot"},{"id":"c","text":"Immunofluorescence"},{"id":"d","text":"Flow cytometry"}],"answerId":"d","explanation":"Flow cytometry is the most appropriate technique for quantifying CD4 T-cells in HIV patients due to its ability to analyze individual cells.","kind":"integration","linkedModuleIds":["autoimmune-disease-examples"],"origin":"ai"},{"id":"immunoassays-techniques~ai-7","moduleId":"immunoassays-techniques","stem":"Which assay would best help determine the presence of specific autoantibodies in systemic lupus erythematosus (SLE)?","options":[{"id":"a","text":"ELISA"},{"id":"b","text":"Western blot"},{"id":"c","text":"Immunofluorescence"},{"id":"d","text":"Flow cytometry"}],"answerId":"c","explanation":"Immunofluorescence is best for determining specific autoantibodies in SLE by visualizing their binding patterns.","kind":"integration","linkedModuleIds":["diagnostic-pathology-methods"],"origin":"ai"}],"autoimmune-disease-examples":[{"id":"autoimmune-disease-examples~ai-0","moduleId":"autoimmune-disease-examples","stem":"Which autoantibody is most specific for systemic lupus erythematosus (SLE)?","options":[{"id":"a","text":"Anti-dsDNA"},{"id":"b","text":"Anti-CCP"},{"id":"c","text":"Anti-AChR"},{"id":"d","text":"Anti-GBM"}],"answerId":"a","explanation":"Anti-dsDNA is highly specific for SLE and is associated with disease activity.","kind":"recall","origin":"ai"},{"id":"autoimmune-disease-examples~ai-1","moduleId":"autoimmune-disease-examples","stem":"What is the mechanism of action of the stimulating anti-TSH receptor antibody in Graves disease?","options":[{"id":"a","text":"Blocking receptor function"},{"id":"b","text":"Stimulating receptor activity"},{"id":"c","text":"Inducing apoptosis of thyroid cells"},{"id":"d","text":"Inhibiting hormone synthesis"}],"answerId":"b","explanation":"The stimulating anti-TSH receptor antibody activates the receptor, leading to increased thyroid hormone production.","kind":"mechanism","origin":"ai"},{"id":"autoimmune-disease-examples~ai-2","moduleId":"autoimmune-disease-examples","stem":"In myasthenia gravis, which clinical finding is most characteristic?","options":[{"id":"a","text":"Fatigable weakness"},{"id":"b","text":"Joint pain"},{"id":"c","text":"Skin rash"},{"id":"d","text":"Hematuria"}],"answerId":"a","explanation":"Fatigable weakness is the hallmark symptom of myasthenia gravis due to impaired neuromuscular transmission.","kind":"recall","origin":"ai"},{"id":"autoimmune-disease-examples~ai-3","moduleId":"autoimmune-disease-examples","stem":"Which of the following statements about type II antibody-mediated autoimmune diseases is true?","options":[{"id":"a","text":"All type II antibodies destroy target cells"},{"id":"b","text":"Type II antibodies can block or stimulate receptors"},{"id":"c","text":"Type II antibodies only cause inflammation"},{"id":"d","text":"Type II antibodies are always pathogenic"}],"answerId":"b","explanation":"Type II antibodies can either block or stimulate receptor function, exemplified by Graves disease and myasthenia gravis.","kind":"trap","origin":"ai"},{"id":"autoimmune-disease-examples~ai-4","moduleId":"autoimmune-disease-examples","stem":"What is the primary autoantibody involved in Goodpasture syndrome?","options":[{"id":"a","text":"Anti-GBM antibody"},{"id":"b","text":"Anti-dsDNA"},{"id":"c","text":"Anti-CCP"},{"id":"d","text":"Anti-AChR"}],"answerId":"a","explanation":"Anti-GBM antibodies target type IV collagen in the basement membrane of the lungs and kidneys.","kind":"recall","origin":"ai"},{"id":"autoimmune-disease-examples~ai-5","moduleId":"autoimmune-disease-examples","stem":"How does the mechanism of type IV hypersensitivity relate to autoimmune diseases like multiple sclerosis?","options":[{"id":"a","text":"It involves antibody-mediated destruction"},{"id":"b","text":"It is mediated by T-cell activation"},{"id":"c","text":"It causes systemic inflammation"},{"id":"d","text":"It leads to immediate hypersensitivity reactions"}],"answerId":"b","explanation":"Multiple sclerosis is characterized by T-cell mediated destruction of myelin, which is a type IV hypersensitivity reaction.","kind":"integration","origin":"ai"},{"id":"autoimmune-disease-examples~ai-6","moduleId":"autoimmune-disease-examples","stem":"Which autoantibody is associated with rheumatoid arthritis and is used for diagnosis?","options":[{"id":"a","text":"Anti-dsDNA"},{"id":"b","text":"Anti-CCP"},{"id":"c","text":"Anti-GBM"},{"id":"d","text":"Anti-AChR"}],"answerId":"b","explanation":"Anti-CCP antibodies are highly specific for rheumatoid arthritis and are used as a diagnostic marker.","kind":"recall","origin":"ai"},{"id":"autoimmune-disease-examples~ai-7","moduleId":"autoimmune-disease-examples","stem":"In the context of autoimmune diseases, how does the concept of self-tolerance failure relate to type 1 diabetes?","options":[{"id":"a","text":"It leads to receptor activation"},{"id":"b","text":"It results in T-cell destruction of β cells"},{"id":"c","text":"It causes systemic inflammation"},{"id":"d","text":"It induces antibody production against thyroid antigens"}],"answerId":"b","explanation":"In type 1 diabetes, the failure of self-tolerance leads to T-cell mediated destruction of insulin-producing β cells in the pancreas.","kind":"integration","linkedModuleIds":["tolerance-autoimmunity-mechanisms"],"origin":"ai"}],"tumor-evasion-immunotherapy":[{"id":"tumor-evasion-immunotherapy~ai-0","moduleId":"tumor-evasion-immunotherapy","stem":"What mechanism allows tumors to evade T cell recognition by down-regulating MHC I?","options":[{"id":"a","text":"Increased PD-L1 expression"},{"id":"b","text":"Altered antigen presentation"},{"id":"c","text":"Recruitment of Tregs"},{"id":"d","text":"Secretion of IL-10"}],"answerId":"b","explanation":"Down-regulating MHC I reduces the presentation of tumor antigens, preventing recognition by cytotoxic T lymphocytes (CTLs).","kind":"mechanism","origin":"ai"},{"id":"tumor-evasion-immunotherapy~ai-1","moduleId":"tumor-evasion-immunotherapy","stem":"Which of the following therapies works by blocking PD-1 to enhance T cell activity against tumors?","options":[{"id":"a","text":"Rituximab"},{"id":"b","text":"Pembrolizumab"},{"id":"c","text":"Trastuzumab"},{"id":"d","text":"CAR-T therapy"}],"answerId":"b","explanation":"Pembrolizumab is an anti-PD-1 antibody that releases the inhibitory checkpoint on T cells, enhancing their anti-tumor activity.","kind":"recall","origin":"ai"},{"id":"tumor-evasion-immunotherapy~ai-2","moduleId":"tumor-evasion-immunotherapy","stem":"What is a common adverse effect associated with CAR-T cell therapy?","options":[{"id":"a","text":"Tumor lysis syndrome"},{"id":"b","text":"Cytokine release syndrome"},{"id":"c","text":"Immune checkpoint inhibition"},{"id":"d","text":"Autoimmune hemolytic anemia"}],"answerId":"b","explanation":"Cytokine release syndrome occurs due to massive T-cell activation and release of pro-inflammatory cytokines like IL-6.","kind":"recall","origin":"ai"},{"id":"tumor-evasion-immunotherapy~ai-3","moduleId":"tumor-evasion-immunotherapy","stem":"What is the primary mechanism by which checkpoint inhibitors restore T cell function?","options":[{"id":"a","text":"Directly kill tumor cells"},{"id":"b","text":"Block inhibitory checkpoints"},{"id":"c","text":"Enhance antigen presentation"},{"id":"d","text":"Increase T cell proliferation"}],"answerId":"b","explanation":"Checkpoint inhibitors block inhibitory signals (like PD-1/PD-L1), effectively 'releasing the brake' on T cells, allowing them to attack tumors.","kind":"trap","origin":"ai"},{"id":"tumor-evasion-immunotherapy~ai-4","moduleId":"tumor-evasion-immunotherapy","stem":"Which of the following is a characteristic of immune-related adverse events in checkpoint therapy?","options":[{"id":"a","text":"Increased tolerance"},{"id":"b","text":"Autoimmunity-like toxicity"},{"id":"c","text":"Direct tumor cell destruction"},{"id":"d","text":"Reduced T cell activation"}],"answerId":"b","explanation":"Immune-related adverse events arise from loss of tolerance, leading to autoimmunity-like side effects due to reactivated T cells attacking normal tissues.","kind":"recall","origin":"ai"},{"id":"tumor-evasion-immunotherapy~ai-5","moduleId":"tumor-evasion-immunotherapy","stem":"How does CAR-T cell therapy specifically target B-cell malignancies?","options":[{"id":"a","text":"By enhancing MHC I expression"},{"id":"b","text":"By targeting CD19 antigen"},{"id":"c","text":"By blocking PD-1"},{"id":"d","text":"By secreting IL-10"}],"answerId":"b","explanation":"CAR-T cells are engineered to express a chimeric antigen receptor that specifically targets the CD19 antigen found on B cells.","kind":"mechanism","origin":"ai"},{"id":"tumor-evasion-immunotherapy~ai-6","moduleId":"tumor-evasion-immunotherapy","stem":"In the context of T cell activation, how does checkpoint blockade relate to the two-signal rule?","options":[{"id":"a","text":"It provides both signals for T cell activation"},{"id":"b","text":"It enhances the first signal only"},{"id":"c","text":"It removes the inhibitory signal allowing T cell response"},{"id":"d","text":"It directly activates T cells without signals"}],"answerId":"c","explanation":"Checkpoint blockade removes the inhibitory signal, allowing T cells that have received the first signal to respond effectively to their target.","kind":"integration","linkedModuleIds":["t-cell-activation"],"origin":"ai"},{"id":"tumor-evasion-immunotherapy~ai-7","moduleId":"tumor-evasion-immunotherapy","stem":"What role do tumor antigens play in the context of immune evasion and immunotherapy?","options":[{"id":"a","text":"They enhance immune tolerance"},{"id":"b","text":"They are targeted by CAR-T cells"},{"id":"c","text":"They inhibit T cell activation"},{"id":"d","text":"They promote tumor growth"}],"answerId":"b","explanation":"Tumor antigens are crucial for the recognition of cancer cells by immune cells, and therapies like CAR-T cells specifically target these antigens to elicit an immune response.","kind":"integration","linkedModuleIds":["tumor-antigens-immunosurveillance"],"origin":"ai"}],"tumor-antigens-immunosurveillance":[{"id":"tumor-antigens-immunosurveillance~ai-0","moduleId":"tumor-antigens-immunosurveillance","stem":"What type of antigen is specifically unique to tumor cells?","options":[{"id":"a","text":"Tumor-associated antigen (TAA)"},{"id":"b","text":"Tumor-specific antigen (TSA)"},{"id":"c","text":"Oncofetal antigen"},{"id":"d","text":"Differentiation antigen"}],"answerId":"b","explanation":"Tumor-specific antigens (TSA) are unique to tumor cells, including mutated neoantigens and viral antigens.","kind":"recall","origin":"ai"},{"id":"tumor-antigens-immunosurveillance~ai-1","moduleId":"tumor-antigens-immunosurveillance","stem":"Which immune cells are primarily responsible for immunosurveillance against cancer?","options":[{"id":"a","text":"B cells"},{"id":"b","text":"CD8 cytotoxic T lymphocytes (CTLs)"},{"id":"c","text":"Macrophages"},{"id":"d","text":"Neutrophils"}],"answerId":"b","explanation":"CD8 cytotoxic T lymphocytes (CTLs) play a central role in the immunosurveillance and destruction of nascent transformed cells.","kind":"recall","origin":"ai"},{"id":"tumor-antigens-immunosurveillance~ai-2","moduleId":"tumor-antigens-immunosurveillance","stem":"What mechanism allows NK cells to target tumor cells that down-regulate MHC I?","options":[{"id":"a","text":"Antibody-dependent cellular cytotoxicity"},{"id":"b","text":"Missing-self recognition"},{"id":"c","text":"Complement activation"},{"id":"d","text":"Cytokine release"}],"answerId":"b","explanation":"NK cells recognize tumor cells that down-regulate MHC I through a mechanism known as missing-self recognition.","kind":"mechanism","origin":"ai"},{"id":"tumor-antigens-immunosurveillance~ai-3","moduleId":"tumor-antigens-immunosurveillance","stem":"Which of the following findings supports the concept of immunosurveillance?","options":[{"id":"a","text":"Increased cancer incidence in immunosuppressed patients"},{"id":"b","text":"Increased tumor mutation burden in healthy individuals"},{"id":"c","text":"Higher incidence of benign tumors"},{"id":"d","text":"Increased survival in patients with chronic infections"}],"answerId":"a","explanation":"The increased cancer incidence in immunosuppressed patients provides strong evidence that the immune system normally controls tumors.","kind":"recall","origin":"ai"},{"id":"tumor-antigens-immunosurveillance~ai-4","moduleId":"tumor-antigens-immunosurveillance","stem":"What is the first step in cancer immunoediting?","options":[{"id":"a","text":"Equilibrium"},{"id":"b","text":"Elimination"},{"id":"c","text":"Escape"},{"id":"d","text":"Activation"}],"answerId":"b","explanation":"Elimination is the first step in cancer immunoediting, where the immune system destroys tumor cells.","kind":"recall","origin":"ai"},{"id":"tumor-antigens-immunosurveillance~ai-5","moduleId":"tumor-antigens-immunosurveillance","stem":"How does HPV contribute to cervical cancer development?","options":[{"id":"a","text":"By inducing mutations in tumor suppressor genes"},{"id":"b","text":"By presenting viral antigens as tumor-specific antigens"},{"id":"c","text":"By enhancing immune surveillance"},{"id":"d","text":"By promoting apoptosis of infected cells"}],"answerId":"b","explanation":"HPV contributes to cervical cancer by presenting viral antigens as tumor-specific antigens, which can evade immune detection.","kind":"mechanism","origin":"ai"},{"id":"tumor-antigens-immunosurveillance~ai-6","moduleId":"tumor-antigens-immunosurveillance","stem":"Which of the following best explains the increased cancer risk in immunosuppressed patients?","options":[{"id":"a","text":"Increased mutation rates in normal cells"},{"id":"b","text":"Loss of immunosurveillance"},{"id":"c","text":"Increased exposure to carcinogens"},{"id":"d","text":"Enhanced tumor growth rates"}],"answerId":"b","explanation":"The increased cancer risk in immunosuppressed patients is primarily due to the loss of immunosurveillance, allowing tumors to develop.","kind":"trap","origin":"ai"},{"id":"tumor-antigens-immunosurveillance~ai-7","moduleId":"tumor-antigens-immunosurveillance","stem":"How do NK cells relate to tumor immune evasion mechanisms discussed in the Tumour Immune Evasion module?","options":[{"id":"a","text":"They enhance MHC I expression on tumor cells"},{"id":"b","text":"They can target tumors that down-regulate MHC I"},{"id":"c","text":"They are ineffective against virus-associated tumors"},{"id":"d","text":"They require prior sensitization to tumor antigens"}],"answerId":"b","explanation":"NK cells can target tumors that down-regulate MHC I, which is a mechanism of tumor immune evasion.","kind":"integration","linkedModuleIds":["tumor-evasion-immunotherapy"],"origin":"ai"},{"id":"tumor-antigens-immunosurveillance~ai-8","moduleId":"tumor-antigens-immunosurveillance","stem":"Which of the following best connects the role of immunosuppression in cancer risk to the mechanisms of tumor spread discussed in the Cancer Spread module?","options":[{"id":"a","text":"Immunosuppression increases metastasis rates"},{"id":"b","text":"Immunosuppression enhances local tumor growth"},{"id":"c","text":"Immunosuppression allows for immune escape mechanisms"},{"id":"d","text":"Immunosuppression reduces angiogenesis"}],"answerId":"c","explanation":"Immunosuppression allows for immune escape mechanisms, which can facilitate tumor spread and metastasis.","kind":"integration","linkedModuleIds":["cancer-spread-staging-clinical"],"origin":"ai"}],"hypersensitivity-type-1-2":[{"id":"hypersensitivity-type-1-2~ai-0","moduleId":"hypersensitivity-type-1-2","stem":"What is the primary immunoglobulin involved in Type I hypersensitivity reactions?","options":[{"id":"a","text":"IgA"},{"id":"b","text":"IgM"},{"id":"c","text":"IgE"},{"id":"d","text":"IgG"}],"answerId":"c","explanation":"IgE is the primary immunoglobulin involved in Type I hypersensitivity, mediating allergic reactions.","kind":"recall","origin":"ai"},{"id":"hypersensitivity-type-1-2~ai-1","moduleId":"hypersensitivity-type-1-2","stem":"Which mechanism is primarily responsible for tissue damage in Type II hypersensitivity?","options":[{"id":"a","text":"Immune complex deposition"},{"id":"b","text":"Mast cell degranulation"},{"id":"c","text":"Antibody-mediated cytotoxicity"},{"id":"d","text":"T-cell activation"}],"answerId":"c","explanation":"Type II hypersensitivity involves antibody-mediated cytotoxicity against fixed antigens on cells.","kind":"mechanism","origin":"ai"},{"id":"hypersensitivity-type-1-2~ai-2","moduleId":"hypersensitivity-type-1-2","stem":"A patient presents with wheal-and-flare reaction after a skin prick test. What type of hypersensitivity is this indicative of?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"a","explanation":"The wheal-and-flare reaction is characteristic of Type I hypersensitivity due to mast cell histamine release.","kind":"recall","origin":"ai"},{"id":"hypersensitivity-type-1-2~ai-3","moduleId":"hypersensitivity-type-1-2","stem":"Which of the following conditions is an example of Type II hypersensitivity?","options":[{"id":"a","text":"Asthma"},{"id":"b","text":"Graves' disease"},{"id":"c","text":"Anaphylaxis"},{"id":"d","text":"Allergic rhinitis"}],"answerId":"b","explanation":"Graves' disease is a Type II hypersensitivity disorder characterized by antibody-mediated receptor activation.","kind":"recall","origin":"ai"},{"id":"hypersensitivity-type-1-2~ai-4","moduleId":"hypersensitivity-type-1-2","stem":"In which condition would you expect a positive direct antiglobulin (Coombs) test?","options":[{"id":"a","text":"Allergic rhinitis"},{"id":"b","text":"Autoimmune hemolytic anemia"},{"id":"c","text":"Anaphylaxis"},{"id":"d","text":"Asthma"}],"answerId":"b","explanation":"A positive Coombs test indicates the presence of antibodies coating red blood cells, typical of autoimmune hemolytic anemia (Type II).","kind":"recall","origin":"ai"},{"id":"hypersensitivity-type-1-2~ai-5","moduleId":"hypersensitivity-type-1-2","stem":"Type II hypersensitivity primarily targets which type of antigen?","options":[{"id":"a","text":"Soluble circulating antigens"},{"id":"b","text":"Fixed cell/tissue antigens"},{"id":"c","text":"Viral antigens"},{"id":"d","text":"Bacterial antigens"}],"answerId":"b","explanation":"Type II hypersensitivity targets fixed antigens on specific cells or tissues, distinguishing it from Type III.","kind":"trap","origin":"ai"},{"id":"hypersensitivity-type-1-2~ai-6","moduleId":"hypersensitivity-type-1-2","stem":"How does Type II hypersensitivity differ from Type III in terms of antigen location?","options":[{"id":"a","text":"Type II involves soluble antigens; Type III involves fixed antigens"},{"id":"b","text":"Type II involves fixed antigens; Type III involves soluble antigens"},{"id":"c","text":"Both involve fixed antigens"},{"id":"d","text":"Both involve soluble antigens"}],"answerId":"b","explanation":"Type II hypersensitivity involves fixed antigens on cells, while Type III involves soluble immune complexes that deposit in tissues.","kind":"trap","origin":"ai"},{"id":"hypersensitivity-type-1-2~ai-7","moduleId":"hypersensitivity-type-1-2","stem":"A patient with myasthenia gravis has antibodies blocking acetylcholine receptors. What type of hypersensitivity is this?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"b","explanation":"Myasthenia gravis is a Type II hypersensitivity disorder where antibodies block acetylcholine receptors.","kind":"recall","origin":"ai"},{"id":"hypersensitivity-type-1-2~ai-8","moduleId":"hypersensitivity-type-1-2","stem":"Which hypersensitivity type is most likely to be involved in a transfusion reaction?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"b","explanation":"Transfusion reactions are primarily due to Type II hypersensitivity, where antibodies target transfused red blood cells.","kind":"integration","linkedModuleIds":["autoimmune-disease-examples"],"origin":"ai"},{"id":"hypersensitivity-type-1-2~ai-9","moduleId":"hypersensitivity-type-1-2","stem":"In which type of hypersensitivity would you expect eosinophil infiltration during the late phase response?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"a","explanation":"Type I hypersensitivity features eosinophil infiltration during the late phase response, contributing to inflammation.","kind":"integration","linkedModuleIds":["cutaneous-immunology-hypersensitivity"],"origin":"ai"}],"hypersensitivity-type-3-4":[{"id":"hypersensitivity-type-3-4~ai-0","moduleId":"hypersensitivity-type-3-4","stem":"What is the primary mechanism of tissue damage in Type III hypersensitivity?","options":[{"id":"a","text":"T-cell mediated cytotoxicity"},{"id":"b","text":"Antibody-antigen complex deposition"},{"id":"c","text":"Histamine release from mast cells"},{"id":"d","text":"Direct cellular injury by antibodies"}],"answerId":"b","explanation":"Type III hypersensitivity involves the deposition of immune complexes, leading to inflammation and tissue damage.","kind":"recall","origin":"ai"},{"id":"hypersensitivity-type-3-4~ai-1","moduleId":"hypersensitivity-type-3-4","stem":"Which of the following diseases is an example of Type III hypersensitivity?","options":[{"id":"a","text":"Contact dermatitis"},{"id":"b","text":"Systemic lupus erythematosus"},{"id":"c","text":"Type 1 diabetes"},{"id":"d","text":"Tuberculosis"}],"answerId":"b","explanation":"Systemic lupus erythematosus involves immune complex formation, characteristic of Type III hypersensitivity.","kind":"recall","origin":"ai"},{"id":"hypersensitivity-type-3-4~ai-2","moduleId":"hypersensitivity-type-3-4","stem":"What is the expected timing for the peak response in a tuberculin skin test?","options":[{"id":"a","text":"Immediate (within minutes)"},{"id":"b","text":"24 hours"},{"id":"c","text":"48-72 hours"},{"id":"d","text":"One week"}],"answerId":"c","explanation":"The tuberculin skin test is a Type IV hypersensitivity reaction, which peaks at 48-72 hours due to T-cell recruitment.","kind":"recall","origin":"ai"},{"id":"hypersensitivity-type-3-4~ai-3","moduleId":"hypersensitivity-type-3-4","stem":"Which finding is characteristic of serum sickness?","options":[{"id":"a","text":"Immediate urticaria"},{"id":"b","text":"Delayed skin induration"},{"id":"c","text":"Immune complex deposition"},{"id":"d","text":"Eosinophilic infiltration"}],"answerId":"c","explanation":"Serum sickness is characterized by immune complex deposition leading to inflammation and symptoms occurring days after exposure.","kind":"clinical","origin":"ai"},{"id":"hypersensitivity-type-3-4~ai-4","moduleId":"hypersensitivity-type-3-4","stem":"In which hypersensitivity type do T cells play a central role?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"d","explanation":"Type IV hypersensitivity is mediated by T cells without the involvement of antibodies.","kind":"recall","origin":"ai"},{"id":"hypersensitivity-type-3-4~ai-5","moduleId":"hypersensitivity-type-3-4","stem":"A patient presents with contact dermatitis after exposure to poison ivy. What type of hypersensitivity is this?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"d","explanation":"Contact dermatitis is a classic example of Type IV hypersensitivity, mediated by T cells.","kind":"recall","origin":"ai"},{"id":"hypersensitivity-type-3-4~ai-6","moduleId":"hypersensitivity-type-3-4","stem":"How does Type IV hypersensitivity differ from Type III in terms of immune response timing?","options":[{"id":"a","text":"Type IV is immediate, Type III is delayed"},{"id":"b","text":"Type III is immediate, Type IV is delayed"},{"id":"c","text":"Both are immediate"},{"id":"d","text":"Both are delayed"}],"answerId":"b","explanation":"Type III hypersensitivity can occur quickly, but Type IV is specifically delayed, peaking at 48-72 hours.","kind":"trap","origin":"ai"},{"id":"hypersensitivity-type-3-4~ai-7","moduleId":"hypersensitivity-type-3-4","stem":"Which of the following mechanisms is involved in glomerular injury in post-streptococcal glomerulonephritis?","options":[{"id":"a","text":"Cytotoxic T-cell activation"},{"id":"b","text":"Immune complex deposition"},{"id":"c","text":"Direct antibody-mediated damage"},{"id":"d","text":"Complement activation without complexes"}],"answerId":"b","explanation":"Post-streptococcal glomerulonephritis involves immune complex deposition, characteristic of Type III hypersensitivity.","kind":"integration","linkedModuleIds":["glomerular-disease-immune-mechanisms"],"origin":"ai"},{"id":"hypersensitivity-type-3-4~ai-8","moduleId":"hypersensitivity-type-3-4","stem":"What is the primary immune mechanism involved in graft rejection during transplantation?","options":[{"id":"a","text":"IgE-mediated hypersensitivity"},{"id":"b","text":"T-cell mediated response"},{"id":"c","text":"Immune complex formation"},{"id":"d","text":"Antibody-mediated cytotoxicity"}],"answerId":"b","explanation":"Graft rejection primarily involves a Type IV hypersensitivity reaction mediated by T cells.","kind":"integration","linkedModuleIds":["transplant-allorecognition-rejection"],"origin":"ai"}],"antigen-antibody-principles":[{"id":"antigen-antibody-principles~ai-0","moduleId":"antigen-antibody-principles","stem":"What is the primary mechanism by which antibodies facilitate the detection of antigens in serological tests?","options":[{"id":"a","text":"Bind → cross-link → detect"},{"id":"b","text":"Detect → bind → cross-link"},{"id":"c","text":"Cross-link → bind → detect"},{"id":"d","text":"Bind → detect → cross-link"}],"answerId":"a","explanation":"Antibodies bind to antigens, cross-link them, and then facilitate detection through various methods.","kind":"mechanism","origin":"ai"},{"id":"antigen-antibody-principles~ai-1","moduleId":"antigen-antibody-principles","stem":"Which statement correctly describes the difference between affinity and avidity?","options":[{"id":"a","text":"Affinity is the total strength of all binding sites, while avidity is the strength of one binding site."},{"id":"b","text":"Affinity is the strength of one binding site, while avidity is the total strength of all binding sites."},{"id":"c","text":"Affinity and avidity are synonymous terms."},{"id":"d","text":"Avidity is only relevant for IgG antibodies."}],"answerId":"b","explanation":"Affinity refers to the strength of a single antigen-binding site, while avidity is the cumulative strength of all binding sites on an antibody.","kind":"recall","origin":"ai"},{"id":"antigen-antibody-principles~ai-2","moduleId":"antigen-antibody-principles","stem":"What can cause a false-negative result in a precipitation test?","options":[{"id":"a","text":"Excess antigen"},{"id":"b","text":"Excess antibody"},{"id":"c","text":"Low temperature"},{"id":"d","text":"High pH"}],"answerId":"b","explanation":"Excess antibody can prevent the formation of the cross-linked lattice necessary for precipitation, leading to false-negative results.","kind":"trap","origin":"ai"},{"id":"antigen-antibody-principles~ai-3","moduleId":"antigen-antibody-principles","stem":"In a haemagglutination test for blood typing, what is the role of the antibody?","options":[{"id":"a","text":"To lyse red blood cells"},{"id":"b","text":"To cross-link red blood cells into visible clumps"},{"id":"c","text":"To neutralize toxins"},{"id":"d","text":"To enhance phagocytosis"}],"answerId":"b","explanation":"Antibodies cross-link particulate antigens, such as red blood cells, leading to visible agglutination.","kind":"recall","origin":"ai"},{"id":"antigen-antibody-principles~ai-4","moduleId":"antigen-antibody-principles","stem":"A patient shows a four-fold rise in antibody titre. What does this indicate?","options":[{"id":"a","text":"Chronic infection"},{"id":"b","text":"Recent/active infection"},{"id":"c","text":"Previous exposure"},{"id":"d","text":"Vaccine response"}],"answerId":"b","explanation":"A four-fold rise in antibody titre is indicative of a recent or active infection.","kind":"recall","origin":"ai"},{"id":"antigen-antibody-principles~ai-5","moduleId":"antigen-antibody-principles","stem":"How does the avidity of IgM compare to that of IgG?","options":[{"id":"a","text":"IgM has lower avidity due to fewer binding sites."},{"id":"b","text":"IgM has higher avidity due to more binding sites."},{"id":"c","text":"IgM and IgG have equal avidity."},{"id":"d","text":"IgG has higher avidity due to more binding sites."}],"answerId":"b","explanation":"IgM has higher avidity than IgG because it has 10 binding sites, allowing for stronger overall binding despite lower affinity per site.","kind":"recall","origin":"ai"},{"id":"antigen-antibody-principles~ai-6","moduleId":"antigen-antibody-principles","stem":"Which immunoassay technique is most likely to be applied after understanding antigen-antibody principles?","options":[{"id":"a","text":"Western blotting"},{"id":"b","text":"PCR"},{"id":"c","text":"X-ray imaging"},{"id":"d","text":"CT scan"}],"answerId":"a","explanation":"Western blotting is an immunoassay technique that relies on antigen-antibody interactions, making it relevant after studying antigen-antibody principles.","kind":"integration","linkedModuleIds":["immunoassays-techniques"],"origin":"ai"},{"id":"antigen-antibody-principles~ai-7","moduleId":"antigen-antibody-principles","stem":"How might knowledge of antigen-antibody reactions apply to understanding the immune response in meningitis?","options":[{"id":"a","text":"It helps in understanding the role of T cells."},{"id":"b","text":"It is crucial for interpreting serological tests for pathogens."},{"id":"c","text":"It has no relevance to meningitis."},{"id":"d","text":"It only applies to bacterial infections."}],"answerId":"b","explanation":"Understanding antigen-antibody reactions is essential for interpreting serological tests that diagnose various types of meningitis.","kind":"integration","linkedModuleIds":["subacute-chronic-meningitis"],"origin":"ai"}],"transplant-matching-immunosuppression":[{"id":"transplant-matching-immunosuppression~ai-0","moduleId":"transplant-matching-immunosuppression","stem":"What is the primary purpose of HLA typing in organ transplantation?","options":[{"id":"a","text":"To assess ABO compatibility"},{"id":"b","text":"To predict graft survival"},{"id":"c","text":"To evaluate donor age"},{"id":"d","text":"To determine organ size"}],"answerId":"b","explanation":"HLA typing improves graft survival by identifying the best tissue match between donor and recipient.","kind":"recall","origin":"ai"},{"id":"transplant-matching-immunosuppression~ai-1","moduleId":"transplant-matching-immunosuppression","stem":"Which immunosuppressive drug class inhibits IL-2 production?","options":[{"id":"a","text":"Antiproliferatives"},{"id":"b","text":"Corticosteroids"},{"id":"c","text":"Calcineurin inhibitors"},{"id":"d","text":"mTOR inhibitors"}],"answerId":"c","explanation":"Calcineurin inhibitors, such as tacrolimus and ciclosporin, block IL-2 production, crucial for T-cell activation.","kind":"mechanism","origin":"ai"},{"id":"transplant-matching-immunosuppression~ai-2","moduleId":"transplant-matching-immunosuppression","stem":"What does a positive pre-transplant crossmatch indicate?","options":[{"id":"a","text":"Good HLA match"},{"id":"b","text":"High risk of hyperacute rejection"},{"id":"c","text":"Successful immunosuppression"},{"id":"d","text":"Compatibility of donor age"}],"answerId":"b","explanation":"A positive crossmatch indicates recipient antibodies react with donor cells, predicting a high risk of hyperacute rejection.","kind":"trap","origin":"ai"},{"id":"transplant-matching-immunosuppression~ai-3","moduleId":"transplant-matching-immunosuppression","stem":"Which opportunistic infection is most commonly associated with immunosuppression post-transplant?","options":[{"id":"a","text":"HIV"},{"id":"b","text":"CMV"},{"id":"c","text":"Tuberculosis"},{"id":"d","text":"Streptococcus"}],"answerId":"b","explanation":"Cytomegalovirus (CMV) infection is a common opportunistic infection in immunosuppressed transplant recipients.","kind":"clinical","origin":"ai"},{"id":"transplant-matching-immunosuppression~ai-4","moduleId":"transplant-matching-immunosuppression","stem":"What is the inheritance pattern of HLA alleles?","options":[{"id":"a","text":"Autosomal dominant"},{"id":"b","text":"Autosomal recessive"},{"id":"c","text":"Codominant"},{"id":"d","text":"X-linked"}],"answerId":"c","explanation":"HLA alleles are inherited in a codominant manner, allowing for expression of both parental alleles.","kind":"recall","origin":"ai"},{"id":"transplant-matching-immunosuppression~ai-5","moduleId":"transplant-matching-immunosuppression","stem":"How does tacrolimus prevent T-cell activation?","options":[{"id":"a","text":"By blocking IL-2 receptor"},{"id":"b","text":"By inhibiting calcineurin"},{"id":"c","text":"By promoting lymphocyte proliferation"},{"id":"d","text":"By enhancing inflammation"}],"answerId":"b","explanation":"Tacrolimus inhibits calcineurin, leading to decreased IL-2 production and subsequent T-cell activation.","kind":"mechanism","origin":"ai"},{"id":"transplant-matching-immunosuppression~ai-6","moduleId":"transplant-matching-immunosuppression","stem":"Which of the following is a consequence of immunosuppression in transplant patients?","options":[{"id":"a","text":"Increased graft rejection"},{"id":"b","text":"Decreased risk of malignancy"},{"id":"c","text":"Opportunistic infections"},{"id":"d","text":"Enhanced immune response"}],"answerId":"c","explanation":"Immunosuppression increases the risk of opportunistic infections due to a weakened immune system.","kind":"clinical","origin":"ai"},{"id":"transplant-matching-immunosuppression~ai-7","moduleId":"transplant-matching-immunosuppression","stem":"In the context of T-cell activation, what is the significance of the two-signal rule?","options":[{"id":"a","text":"It prevents hyperacute rejection"},{"id":"b","text":"It enhances graft survival"},{"id":"c","text":"It requires both antigen recognition and co-stimulation"},{"id":"d","text":"It reduces the need for immunosuppressants"}],"answerId":"c","explanation":"The two-signal rule states that T-cell activation requires both antigen recognition and a second signal from co-stimulatory molecules.","kind":"integration","linkedModuleIds":["t-cell-activation"],"origin":"ai"},{"id":"transplant-matching-immunosuppression~ai-8","moduleId":"transplant-matching-immunosuppression","stem":"How does understanding immunosuppressant drugs relate to transplant rejection mechanisms?","options":[{"id":"a","text":"It helps predict donor age"},{"id":"b","text":"It clarifies the role of HLA typing"},{"id":"c","text":"It informs strategies to prevent graft rejection"},{"id":"d","text":"It determines the need for dialysis"}],"answerId":"c","explanation":"Knowledge of immunosuppressant drugs aids in developing strategies to prevent graft rejection by targeting T-cell activation.","kind":"integration","linkedModuleIds":["immunosuppressant-drugs"],"origin":"ai"}],"transplant-allorecognition-rejection":[{"id":"transplant-allorecognition-rejection~ai-0","moduleId":"transplant-allorecognition-rejection","stem":"What type of graft is an organ transplanted from one individual to another of the same species?","options":[{"id":"a","text":"Autograft"},{"id":"b","text":"Isograft"},{"id":"c","text":"Allograft"},{"id":"d","text":"Xenograft"}],"answerId":"c","explanation":"An allograft is a transplant between individuals of the same species but genetically different.","kind":"recall","origin":"ai"},{"id":"transplant-allorecognition-rejection~ai-1","moduleId":"transplant-allorecognition-rejection","stem":"Which mechanism primarily drives hyperacute rejection?","options":[{"id":"a","text":"Direct allorecognition"},{"id":"b","text":"Pre-existing antibodies"},{"id":"c","text":"Donor-specific T cells"},{"id":"d","text":"Chronic inflammation"}],"answerId":"b","explanation":"Hyperacute rejection is caused by pre-existing recipient antibodies leading to immediate graft loss.","kind":"mechanism","origin":"ai"},{"id":"transplant-allorecognition-rejection~ai-2","moduleId":"transplant-allorecognition-rejection","stem":"A patient experiences graft loss within minutes after transplantation. What is the most likely cause?","options":[{"id":"a","text":"Acute rejection"},{"id":"b","text":"Chronic rejection"},{"id":"c","text":"Hyperacute rejection"},{"id":"d","text":"Graft-versus-host disease"}],"answerId":"c","explanation":"The rapid onset of graft loss indicates hyperacute rejection due to pre-existing antibodies.","kind":"clinical","origin":"ai"},{"id":"transplant-allorecognition-rejection~ai-3","moduleId":"transplant-allorecognition-rejection","stem":"Which finding is characteristic of acute cellular rejection?","options":[{"id":"a","text":"Graft thrombosis"},{"id":"b","text":"Progressive fibrosis"},{"id":"c","text":"Rash and diarrhea"},{"id":"d","text":"Reversible with steroids"}],"answerId":"d","explanation":"Acute cellular rejection can be reversed with steroids and typically occurs 1-2 weeks post-transplant.","kind":"recall","origin":"ai"},{"id":"transplant-allorecognition-rejection~ai-4","moduleId":"transplant-allorecognition-rejection","stem":"What is the primary mechanism of chronic rejection?","options":[{"id":"a","text":"Acute inflammation"},{"id":"b","text":"Vascular intimal thickening"},{"id":"c","text":"Pre-existing antibodies"},{"id":"d","text":"Direct allorecognition"}],"answerId":"b","explanation":"Chronic rejection is characterized by progressive vascular intimal thickening and fibrosis over time.","kind":"mechanism","origin":"ai"},{"id":"transplant-allorecognition-rejection~ai-5","moduleId":"transplant-allorecognition-rejection","stem":"In graft-versus-host disease (GVHD), which organ is NOT typically affected?","options":[{"id":"a","text":"Skin"},{"id":"b","text":"Liver"},{"id":"c","text":"Heart"},{"id":"d","text":"Gut"}],"answerId":"c","explanation":"GVHD primarily targets the skin, liver, and gut, but not the heart.","kind":"trap","origin":"ai"},{"id":"transplant-allorecognition-rejection~ai-6","moduleId":"transplant-allorecognition-rejection","stem":"How does the mechanism of acute rejection relate to hypersensitivity type IV?","options":[{"id":"a","text":"Both involve pre-existing antibodies"},{"id":"b","text":"Both are mediated by T cells"},{"id":"c","text":"Both occur immediately"},{"id":"d","text":"Both cause immediate graft loss"}],"answerId":"b","explanation":"Acute rejection involves T cells recognizing foreign MHC, similar to the T-cell mediated response in hypersensitivity type IV.","kind":"integration","linkedModuleIds":["hypersensitivity-type-3-4"],"origin":"ai"},{"id":"transplant-allorecognition-rejection~ai-7","moduleId":"transplant-allorecognition-rejection","stem":"What is the relationship between transplant matching and the risk of rejection?","options":[{"id":"a","text":"Increased matching reduces rejection risk"},{"id":"b","text":"Matching has no effect on rejection"},{"id":"c","text":"Decreased matching increases rejection risk"},{"id":"d","text":"Matching only affects hyperacute rejection"}],"answerId":"a","explanation":"Better transplant matching reduces the risk of rejection by minimizing differences in HLA.","kind":"integration","linkedModuleIds":["transplant-matching-immunosuppression"],"origin":"ai"}],"oral-tolerance-microbiota":[{"id":"oral-tolerance-microbiota~ai-0","moduleId":"oral-tolerance-microbiota","stem":"What is the primary mechanism by which oral tolerance is achieved?","options":[{"id":"a","text":"Activation of B cells"},{"id":"b","text":"Regulatory T cell suppression"},{"id":"c","text":"Increased IgE production"},{"id":"d","text":"Th1 cell activation"}],"answerId":"b","explanation":"Oral tolerance is primarily mediated by regulatory T cells that suppress immune responses to ingested antigens.","kind":"mechanism","origin":"ai"},{"id":"oral-tolerance-microbiota~ai-1","moduleId":"oral-tolerance-microbiota","stem":"Which cytokine is most associated with promoting regulatory T cell development in the gut?","options":[{"id":"a","text":"IL-6"},{"id":"b","text":"TGF-β"},{"id":"c","text":"IL-4"},{"id":"d","text":"IFN-γ"}],"answerId":"b","explanation":"TGF-β is crucial for the differentiation and expansion of regulatory T cells in the gut.","kind":"mechanism","origin":"ai"},{"id":"oral-tolerance-microbiota~ai-2","moduleId":"oral-tolerance-microbiota","stem":"What clinical finding indicates successful oral tolerance to food antigens?","options":[{"id":"a","text":"Elevated serum IgE levels"},{"id":"b","text":"Immune non-response to ingested food antigen"},{"id":"c","text":"Increased Th17 cell activity"},{"id":"d","text":"Presence of inflammatory bowel symptoms"}],"answerId":"b","explanation":"Immune non-response to ingested food antigens is a hallmark of successful oral tolerance.","kind":"clinical","origin":"ai"},{"id":"oral-tolerance-microbiota~ai-3","moduleId":"oral-tolerance-microbiota","stem":"Which of the following is a consequence of dysbiosis in the gut microbiota?","options":[{"id":"a","text":"Enhanced colonisation resistance"},{"id":"b","text":"Development of food allergies"},{"id":"c","text":"Increased Treg population"},{"id":"d","text":"Improved immune maturation"}],"answerId":"b","explanation":"Dysbiosis can lead to a loss of tolerance and contribute to the development of food allergies.","kind":"trap","origin":"ai"},{"id":"oral-tolerance-microbiota~ai-4","moduleId":"oral-tolerance-microbiota","stem":"What is the role of short-chain fatty acids (SCFAs) produced by gut microbiota?","options":[{"id":"a","text":"Promote Th1 cell differentiation"},{"id":"b","text":"Enhance IgA production"},{"id":"c","text":"Expand regulatory T cells"},{"id":"d","text":"Increase inflammation"}],"answerId":"c","explanation":"SCFAs, such as butyrate, are known to expand regulatory T cells, promoting tolerance.","kind":"mechanism","origin":"ai"},{"id":"oral-tolerance-microbiota~ai-5","moduleId":"oral-tolerance-microbiota","stem":"How does the gut microbiota contribute to immune system development in germ-free animals?","options":[{"id":"a","text":"By producing antibodies"},{"id":"b","text":"By promoting inflammation"},{"id":"c","text":"By educating the immune system"},{"id":"d","text":"By increasing pathogen resistance"}],"answerId":"c","explanation":"The gut microbiota plays a critical role in educating and maturing the immune system in germ-free animals.","kind":"mechanism","origin":"ai"},{"id":"oral-tolerance-microbiota~ai-6","moduleId":"oral-tolerance-microbiota","stem":"Which mechanism connects oral tolerance to autoimmune conditions?","options":[{"id":"a","text":"Increased IgE production"},{"id":"b","text":"Failure of Treg function"},{"id":"c","text":"Enhanced Th1 response"},{"id":"d","text":"Dysbiosis leading to inflammation"}],"answerId":"b","explanation":"A failure of Treg function can lead to a breakdown in oral tolerance, contributing to autoimmune conditions.","kind":"integration","linkedModuleIds":["tolerance-autoimmunity-mechanisms"],"origin":"ai"},{"id":"oral-tolerance-microbiota~ai-7","moduleId":"oral-tolerance-microbiota","stem":"What finding would suggest a loss of colonisation resistance in a patient after antibiotic treatment?","options":[{"id":"a","text":"Increased butyrate levels"},{"id":"b","text":"C. difficile infection"},{"id":"c","text":"Higher Treg counts"},{"id":"d","text":"Reduced IgA secretion"}],"answerId":"b","explanation":"C. difficile infection is a common consequence of loss of colonisation resistance following antibiotic treatment.","kind":"integration","linkedModuleIds":["mucosal-immune-system"],"origin":"ai"}],"tolerance-autoimmunity-mechanisms":[{"id":"tolerance-autoimmunity-mechanisms~ai-0","moduleId":"tolerance-autoimmunity-mechanisms","stem":"What is the primary mechanism by which autoimmunity occurs?","options":[{"id":"a","text":"Loss of self-tolerance"},{"id":"b","text":"Increased immune tolerance"},{"id":"c","text":"Direct infection of tissues"},{"id":"d","text":"Overactive innate immunity"}],"answerId":"a","explanation":"Autoimmunity arises from a loss of self-tolerance, leading to immune attacks on self-antigens.","kind":"recall","origin":"ai"},{"id":"tolerance-autoimmunity-mechanisms~ai-1","moduleId":"tolerance-autoimmunity-mechanisms","stem":"Which genetic defect is associated with APECED?","options":[{"id":"a","text":"FoxP3 mutation"},{"id":"b","text":"AIRE mutation"},{"id":"c","text":"CTLA-4 polymorphism"},{"id":"d","text":"HLA-B27"}],"answerId":"b","explanation":"APECED is caused by a mutation in the AIRE gene, leading to central tolerance failure.","kind":"recall","origin":"ai"},{"id":"tolerance-autoimmunity-mechanisms~ai-2","moduleId":"tolerance-autoimmunity-mechanisms","stem":"What is the role of Tregs in autoimmunity?","options":[{"id":"a","text":"Promote inflammation"},{"id":"b","text":"Enhance B cell activation"},{"id":"c","text":"Suppress self-reactive T cells"},{"id":"d","text":"Stimulate antigen presentation"}],"answerId":"c","explanation":"Tregs play a crucial role in maintaining peripheral tolerance by suppressing self-reactive T cells.","kind":"mechanism","origin":"ai"},{"id":"tolerance-autoimmunity-mechanisms~ai-3","moduleId":"tolerance-autoimmunity-mechanisms","stem":"A patient presents with multi-organ autoimmunity. Genetic testing reveals a defect in AIRE. What condition is likely?","options":[{"id":"a","text":"Graves' disease"},{"id":"b","text":"Type 1 diabetes"},{"id":"c","text":"APECED"},{"id":"d","text":"Guillain-Barré syndrome"}],"answerId":"c","explanation":"AIRE mutation leads to APECED, characterized by multi-organ autoimmunity due to central tolerance failure.","kind":"clinical","origin":"ai"},{"id":"tolerance-autoimmunity-mechanisms~ai-4","moduleId":"tolerance-autoimmunity-mechanisms","stem":"What is the mechanism behind rheumatic fever following streptococcal infection?","options":[{"id":"a","text":"Direct myocardial infection"},{"id":"b","text":"Molecular mimicry"},{"id":"c","text":"Bystander activation"},{"id":"d","text":"Cryptic antigen release"}],"answerId":"b","explanation":"Rheumatic fever is caused by molecular mimicry, where antibodies against streptococcal M protein cross-react with cardiac antigens.","kind":"trap","origin":"ai"},{"id":"tolerance-autoimmunity-mechanisms~ai-5","moduleId":"tolerance-autoimmunity-mechanisms","stem":"Which HLA type is strongly associated with ankylosing spondylitis?","options":[{"id":"a","text":"HLA-DR3"},{"id":"b","text":"HLA-B27"},{"id":"c","text":"HLA-DQ2"},{"id":"d","text":"HLA-CTLA-4"}],"answerId":"b","explanation":"HLA-B27 is strongly associated with ankylosing spondylitis, indicating a genetic predisposition.","kind":"recall","origin":"ai"},{"id":"tolerance-autoimmunity-mechanisms~ai-6","moduleId":"tolerance-autoimmunity-mechanisms","stem":"How does molecular mimicry contribute to autoimmunity in Guillain-Barré syndrome?","options":[{"id":"a","text":"Direct infection of nerves"},{"id":"b","text":"Cross-reactivity with gangliosides"},{"id":"c","text":"Increased Treg activity"},{"id":"d","text":"Failure of central tolerance"}],"answerId":"b","explanation":"In Guillain-Barré syndrome, molecular mimicry occurs when antibodies to *Campylobacter* cross-react with peripheral nerve gangliosides.","kind":"integration","linkedModuleIds":["rheumatic-heart-disease"],"origin":"ai"},{"id":"tolerance-autoimmunity-mechanisms~ai-7","moduleId":"tolerance-autoimmunity-mechanisms","stem":"Which mechanism is primarily responsible for the development of type 1 diabetes?","options":[{"id":"a","text":"Type II hypersensitivity"},{"id":"b","text":"Type III hypersensitivity"},{"id":"c","text":"Type IV hypersensitivity"},{"id":"d","text":"Molecular mimicry"}],"answerId":"c","explanation":"Type 1 diabetes is primarily mediated by type IV hypersensitivity, involving T cell-mediated destruction of pancreatic beta cells.","kind":"integration","linkedModuleIds":["hypersensitivity-type-3-4"],"origin":"ai"}],"epithelial-classification":[{"id":"epithelial-classification~ai-0","moduleId":"epithelial-classification","stem":"What type of epithelium lines the alveoli of the lungs?","options":[{"id":"a","text":"Simple cuboidal"},{"id":"b","text":"Stratified squamous"},{"id":"c","text":"Simple squamous"},{"id":"d","text":"Pseudostratified columnar"}],"answerId":"c","explanation":"The alveoli are lined by simple squamous epithelium, which facilitates gas exchange.","kind":"recall","origin":"ai"},{"id":"epithelial-classification~ai-1","moduleId":"epithelial-classification","stem":"Which epithelium type is characterized by nuclei at different heights but all cells touching the basement membrane?","options":[{"id":"a","text":"Stratified squamous"},{"id":"b","text":"Simple cuboidal"},{"id":"c","text":"Pseudostratified ciliated columnar"},{"id":"d","text":"Transitional"}],"answerId":"c","explanation":"Pseudostratified ciliated columnar epithelium appears layered due to varying nuclear heights, but is a single layer.","kind":"mechanism","origin":"ai"},{"id":"epithelial-classification~ai-2","moduleId":"epithelial-classification","stem":"Which epithelium type is found in the urinary bladder?","options":[{"id":"a","text":"Simple columnar"},{"id":"b","text":"Simple squamous"},{"id":"c","text":"Transitional"},{"id":"d","text":"Stratified cuboidal"}],"answerId":"c","explanation":"Transitional epithelium accommodates stretching and is found in the bladder.","kind":"recall","origin":"ai"},{"id":"epithelial-classification~ai-3","moduleId":"epithelial-classification","stem":"What is the primary function of simple cuboidal epithelium?","options":[{"id":"a","text":"Absorption"},{"id":"b","text":"Secretion"},{"id":"c","text":"Protection"},{"id":"d","text":"Diffusion"}],"answerId":"b","explanation":"Simple cuboidal epithelium primarily functions in secretion and absorption.","kind":"mechanism","origin":"ai"},{"id":"epithelial-classification~ai-4","moduleId":"epithelial-classification","stem":"Which finding indicates stratified squamous keratinized epithelium?","options":[{"id":"a","text":"Flat single layer lining a blood vessel"},{"id":"b","text":"Dome-shaped umbrella cells"},{"id":"c","text":"Nuclei at many heights"},{"id":"d","text":"Dry, dead surface with keratin"}],"answerId":"d","explanation":"Stratified squamous keratinized epithelium has a dry, keratinized surface, characteristic of the epidermis.","kind":"recall","origin":"ai"},{"id":"epithelial-classification~ai-5","moduleId":"epithelial-classification","stem":"How does pseudostratified epithelium differ from stratified epithelium?","options":[{"id":"a","text":"It has multiple layers"},{"id":"b","text":"All cells touch the basement membrane"},{"id":"c","text":"It is always ciliated"},{"id":"d","text":"It is found only in the respiratory tract"}],"answerId":"b","explanation":"Pseudostratified epithelium is a single layer where all cells contact the basement membrane, unlike stratified epithelium.","kind":"trap","origin":"ai"},{"id":"epithelial-classification~ai-6","moduleId":"epithelial-classification","stem":"Which type of epithelium is primarily involved in absorption and secretion in the gastrointestinal tract?","options":[{"id":"a","text":"Simple squamous"},{"id":"b","text":"Simple cuboidal"},{"id":"c","text":"Simple columnar"},{"id":"d","text":"Transitional"}],"answerId":"c","explanation":"Simple columnar epithelium is specialized for absorption and secretion in the gut.","kind":"integration","linkedModuleIds":["epithelial-surface-basement-membrane"],"origin":"ai"},{"id":"epithelial-classification~ai-7","moduleId":"epithelial-classification","stem":"What is the main role of the basement membrane in epithelial tissues?","options":[{"id":"a","text":"Provide structural support"},{"id":"b","text":"Facilitate absorption"},{"id":"c","text":"Act as a barrier"},{"id":"d","text":"Enhance cell communication"}],"answerId":"a","explanation":"The basement membrane provides structural support and anchorage for epithelial cells.","kind":"integration","linkedModuleIds":["cell-junctions"],"origin":"ai"}],"plasma-membrane-transport":[{"id":"plasma-membrane-transport~ai-0","moduleId":"plasma-membrane-transport","stem":"What is the primary function of the glycocalyx on the cell surface?","options":[{"id":"a","text":"Cell adhesion"},{"id":"b","text":"Energy storage"},{"id":"c","text":"Protein synthesis"},{"id":"d","text":"Signal transduction"}],"answerId":"a","explanation":"The glycocalyx primarily functions in cell recognition and adhesion, providing a protective layer on the cell surface.","kind":"recall","origin":"ai"},{"id":"plasma-membrane-transport~ai-1","moduleId":"plasma-membrane-transport","stem":"Which type of membrane protein can only be removed by disrupting the membrane?","options":[{"id":"a","text":"Peripheral proteins"},{"id":"b","text":"Integral proteins"},{"id":"c","text":"Transitory proteins"},{"id":"d","text":"Glycoproteins"}],"answerId":"b","explanation":"Integral proteins span the membrane and are tightly bound, requiring membrane disruption for removal.","kind":"recall","origin":"ai"},{"id":"plasma-membrane-transport~ai-2","moduleId":"plasma-membrane-transport","stem":"What transport mechanism is used for glucose uptake in the gut against its concentration gradient?","options":[{"id":"a","text":"Simple diffusion"},{"id":"b","text":"Facilitated diffusion"},{"id":"c","text":"Primary active transport"},{"id":"d","text":"Secondary active transport"}],"answerId":"d","explanation":"Glucose uptake in the gut occurs via SGLT, which is a secondary active transport mechanism that couples Na⁺ and glucose transport.","kind":"mechanism","origin":"ai"},{"id":"plasma-membrane-transport~ai-3","moduleId":"plasma-membrane-transport","stem":"Which of the following is a characteristic finding of the plasma membrane on transmission electron microscopy (TEM)?","options":[{"id":"a","text":"Single dense line"},{"id":"b","text":"Trilaminar structure"},{"id":"c","text":"Homogeneous density"},{"id":"d","text":"Absence of proteins"}],"answerId":"b","explanation":"The plasma membrane appears as a trilaminar structure on TEM, consisting of two dense lines of phosphate heads and a lucent lipid core.","kind":"recall","origin":"ai"},{"id":"plasma-membrane-transport~ai-4","moduleId":"plasma-membrane-transport","stem":"Which statement correctly differentiates facilitated diffusion from active transport?","options":[{"id":"a","text":"Both require ATP"},{"id":"b","text":"Facilitated diffusion moves against the gradient"},{"id":"c","text":"Facilitated diffusion does not require ATP"},{"id":"d","text":"Active transport uses channel proteins only"}],"answerId":"c","explanation":"Facilitated diffusion utilizes a protein carrier but does not require ATP, moving substances down their concentration gradient.","kind":"trap","origin":"ai"},{"id":"plasma-membrane-transport~ai-5","moduleId":"plasma-membrane-transport","stem":"How does the Na⁺/K⁺-ATPase contribute to cellular function?","options":[{"id":"a","text":"It generates ATP"},{"id":"b","text":"It maintains membrane potential"},{"id":"c","text":"It facilitates glucose transport"},{"id":"d","text":"It synthesizes proteins"}],"answerId":"b","explanation":"The Na⁺/K⁺-ATPase maintains the membrane potential by pumping 3 Na⁺ out and 2 K⁺ in, crucial for cell excitability.","kind":"mechanism","origin":"ai"},{"id":"plasma-membrane-transport~ai-6","moduleId":"plasma-membrane-transport","stem":"In the context of glucose monitoring, how does the SGLT mechanism relate to glucose absorption?","options":[{"id":"a","text":"It indicates low glucose levels"},{"id":"b","text":"It enhances glucose excretion"},{"id":"c","text":"It facilitates glucose uptake in the intestines"},{"id":"d","text":"It inhibits glucose transport"}],"answerId":"c","explanation":"SGLT facilitates glucose uptake against its gradient in the intestines, which is essential for glucose monitoring and management.","kind":"integration","linkedModuleIds":["glucose-specimens-monitoring"],"origin":"ai"},{"id":"plasma-membrane-transport~ai-7","moduleId":"plasma-membrane-transport","stem":"Which junction type is crucial for maintaining the polarity of epithelial cells, allowing for differential transport?","options":[{"id":"a","text":"Desmosomes"},{"id":"b","text":"Gap junctions"},{"id":"c","text":"Tight junctions"},{"id":"d","text":"Adherens junctions"}],"answerId":"c","explanation":"Tight junctions are essential for maintaining epithelial cell polarity by preventing the free passage of substances between the apical and basolateral surfaces.","kind":"integration","linkedModuleIds":["cell-junctions"],"origin":"ai"}],"actin-microfilaments":[{"id":"actin-microfilaments~ai-0","moduleId":"actin-microfilaments","stem":"What is the primary function of myosin in relation to actin?","options":[{"id":"a","text":"Cell signaling"},{"id":"b","text":"Actin polymerization"},{"id":"c","text":"Motor activity for muscle contraction"},{"id":"d","text":"Cell adhesion"}],"answerId":"c","explanation":"Myosin interacts with actin to generate force, primarily in muscle contraction.","kind":"recall","origin":"ai"},{"id":"actin-microfilaments~ai-1","moduleId":"actin-microfilaments","stem":"Which of the following statements about actin microfilaments is true?","options":[{"id":"a","text":"They are the thickest cytoskeletal filaments."},{"id":"b","text":"They are involved in cilia movement."},{"id":"c","text":"They polymerize from G-actin to F-actin."},{"id":"d","text":"They do not participate in cell motility."}],"answerId":"c","explanation":"Actin microfilaments polymerize from globular G-actin to form filamentous F-actin.","kind":"recall","origin":"ai"},{"id":"actin-microfilaments~ai-2","moduleId":"actin-microfilaments","stem":"What is the mechanism of action of cytochalasin?","options":[{"id":"a","text":"Stabilizes actin filaments"},{"id":"b","text":"Inhibits actin polymerization"},{"id":"c","text":"Enhances myosin activity"},{"id":"d","text":"Promotes microtubule assembly"}],"answerId":"b","explanation":"Cytochalasin blocks actin polymerization, disrupting actin filament dynamics.","kind":"mechanism","origin":"ai"},{"id":"actin-microfilaments~ai-3","moduleId":"actin-microfilaments","stem":"During cytokinesis, which structure is formed by actin and myosin?","options":[{"id":"a","text":"Zonula adherens"},{"id":"b","text":"Cleavage furrow"},{"id":"c","text":"Microvilli"},{"id":"d","text":"Cilia"}],"answerId":"b","explanation":"The cleavage furrow is formed by the contractile ring of actin and myosin during cell division.","kind":"recall","origin":"ai"},{"id":"actin-microfilaments~ai-4","moduleId":"actin-microfilaments","stem":"Which of the following correctly describes the composition of microvilli?","options":[{"id":"a","text":"Microtubules"},{"id":"b","text":"Intermediate filaments"},{"id":"c","text":"Actin filaments"},{"id":"d","text":"Collagen fibers"}],"answerId":"c","explanation":"Microvilli are supported by bundled actin filaments anchored in the terminal web.","kind":"trap","origin":"ai"},{"id":"actin-microfilaments~ai-5","moduleId":"actin-microfilaments","stem":"How do *Listeria* and *Shigella* utilize actin for motility?","options":[{"id":"a","text":"By inhibiting actin polymerization"},{"id":"b","text":"By forming microtubule tracks"},{"id":"c","text":"By hijacking host actin to form comet tails"},{"id":"d","text":"By enhancing myosin activity"}],"answerId":"c","explanation":"These pathogens polymerize host actin to create comet tails for intracellular movement.","kind":"clinical","origin":"ai"},{"id":"actin-microfilaments~ai-6","moduleId":"actin-microfilaments","stem":"How does actin contribute to cell junctions, particularly in epithelial cells?","options":[{"id":"a","text":"By forming tight junctions"},{"id":"b","text":"By linking cadherins to the cytoskeleton"},{"id":"c","text":"By stabilizing microtubules"},{"id":"d","text":"By promoting cilia formation"}],"answerId":"b","explanation":"Actin filaments link cadherins through catenins, forming the zonula adherens in epithelial cells.","kind":"integration","linkedModuleIds":["cell-junctions"],"origin":"ai"},{"id":"actin-microfilaments~ai-7","moduleId":"actin-microfilaments","stem":"Which of the following best explains the role of actin in muscle contraction?","options":[{"id":"a","text":"Actin provides structural support to myofibrils"},{"id":"b","text":"Actin serves as a track for myosin movement"},{"id":"c","text":"Actin stabilizes the sarcomere"},{"id":"d","text":"Actin regulates calcium ion release"}],"answerId":"b","explanation":"Actin serves as a track for myosin to pull on during muscle contraction, facilitating shortening of the sarcomere.","kind":"integration","linkedModuleIds":["skeletal-muscle-sarcomere"],"origin":"ai"}],"immunotherapy-modulation":[{"id":"immunotherapy-modulation~ai-0","moduleId":"immunotherapy-modulation","stem":"What is the primary mechanism of action of anti-TNF biologics like adalimumab?","options":[{"id":"a","text":"Inhibition of IL-2 production"},{"id":"b","text":"Blockade of TNF-alpha"},{"id":"c","text":"Depletion of B cells"},{"id":"d","text":"Activation of T cells"}],"answerId":"b","explanation":"Anti-TNF biologics block the action of tumor necrosis factor-alpha, which is involved in inflammatory processes.","kind":"mechanism","origin":"ai"},{"id":"immunotherapy-modulation~ai-1","moduleId":"immunotherapy-modulation","stem":"Which of the following is a common adverse effect of checkpoint inhibitors like anti-PD-1?","options":[{"id":"a","text":"Increased risk of infection"},{"id":"b","text":"Colitis"},{"id":"c","text":"Hypertension"},{"id":"d","text":"Hyperglycemia"}],"answerId":"b","explanation":"Checkpoint inhibitors can lead to immune-related adverse events, including colitis due to loss of tolerance.","kind":"recall","origin":"ai"},{"id":"immunotherapy-modulation~ai-2","moduleId":"immunotherapy-modulation","stem":"What is the rationale for screening for latent tuberculosis before starting anti-TNF therapy?","options":[{"id":"a","text":"TNF is not involved in tuberculosis"},{"id":"b","text":"TNF blockade can reactivate latent TB"},{"id":"c","text":"Anti-TNF therapy is ineffective in TB"},{"id":"d","text":"Screening is not necessary for any biologics"}],"answerId":"b","explanation":"TNF is essential for granuloma integrity; blocking it can reactivate latent tuberculosis.","kind":"trap","origin":"ai"},{"id":"immunotherapy-modulation~ai-3","moduleId":"immunotherapy-modulation","stem":"Which immunosuppressant directly inhibits IL-2 production?","options":[{"id":"a","text":"Azathioprine"},{"id":"b","text":"Ciclosporin"},{"id":"c","text":"Sirolimus"},{"id":"d","text":"Mycophenolate"}],"answerId":"b","explanation":"Ciclosporin inhibits calcineurin, leading to decreased IL-2 production and T-cell activation.","kind":"recall","origin":"ai"},{"id":"immunotherapy-modulation~ai-4","moduleId":"immunotherapy-modulation","stem":"What is the primary mechanism by which rituximab exerts its therapeutic effect?","options":[{"id":"a","text":"Inhibition of TNF-alpha"},{"id":"b","text":"Depletion of B cells"},{"id":"c","text":"Activation of T cells"},{"id":"d","text":"Blockade of IL-17"}],"answerId":"b","explanation":"Rituximab is a monoclonal antibody that targets CD20 on B cells, leading to their depletion.","kind":"mechanism","origin":"ai"},{"id":"immunotherapy-modulation~ai-5","moduleId":"immunotherapy-modulation","stem":"How does IVIG function in the context of antibody deficiency?","options":[{"id":"a","text":"Stimulates T-cell production"},{"id":"b","text":"Provides passive immunoglobulin replacement"},{"id":"c","text":"Inhibits cytokine production"},{"id":"d","text":"Depletes autoreactive B cells"}],"answerId":"b","explanation":"IVIG provides passive immunoglobulin replacement, helping to bolster the immune response in antibody deficiency.","kind":"mechanism","origin":"ai"},{"id":"immunotherapy-modulation~ai-6","moduleId":"immunotherapy-modulation","stem":"In what way does the mechanism of action of anti-IgE therapy (omalizumab) relate to hypersensitivity reactions?","options":[{"id":"a","text":"It blocks IL-4 signaling"},{"id":"b","text":"It removes free IgE from circulation"},{"id":"c","text":"It inhibits mast cell degranulation"},{"id":"d","text":"It increases IgE production"}],"answerId":"b","explanation":"Omalizumab binds to free IgE, preventing it from binding to mast cells and thus reducing allergic reactions.","kind":"integration","linkedModuleIds":["hypersensitivity-type-1-2"],"origin":"ai"},{"id":"immunotherapy-modulation~ai-7","moduleId":"immunotherapy-modulation","stem":"How does the use of checkpoint inhibitors relate to mechanisms of self-tolerance in autoimmunity?","options":[{"id":"a","text":"They enhance self-tolerance"},{"id":"b","text":"They can break self-tolerance"},{"id":"c","text":"They prevent autoantibody production"},{"id":"d","text":"They stimulate T-regulatory cells"}],"answerId":"b","explanation":"Checkpoint inhibitors can lead to a loss of self-tolerance, resulting in autoimmune-like side effects.","kind":"integration","linkedModuleIds":["tolerance-autoimmunity-mechanisms"],"origin":"ai"}],"intermediate-filaments":[{"id":"intermediate-filaments~ai-0","moduleId":"intermediate-filaments","stem":"Which intermediate filament is primarily found in epithelial cells?","options":[{"id":"a","text":"Vimentin"},{"id":"b","text":"Desmin"},{"id":"c","text":"Keratin"},{"id":"d","text":"Neurofilament"}],"answerId":"c","explanation":"Keratin is the intermediate filament specific to epithelial cells, providing structural support.","kind":"recall","origin":"ai"},{"id":"intermediate-filaments~ai-1","moduleId":"intermediate-filaments","stem":"What is the primary function of intermediate filaments in cells?","options":[{"id":"a","text":"Facilitating cell motility"},{"id":"b","text":"Providing mechanical support"},{"id":"c","text":"Transporting organelles"},{"id":"d","text":"Regulating cell division"}],"answerId":"b","explanation":"Intermediate filaments provide mechanical support and stability to cells, resisting stretch.","kind":"mechanism","origin":"ai"},{"id":"intermediate-filaments~ai-2","moduleId":"intermediate-filaments","stem":"A patient presents with a tumor that is positive for vimentin. What is the likely origin of this tumor?","options":[{"id":"a","text":"Epithelial"},{"id":"b","text":"Mesenchymal"},{"id":"c","text":"Neuronal"},{"id":"d","text":"Muscle"}],"answerId":"b","explanation":"Vimentin positivity indicates a mesenchymal origin, suggesting a sarcoma.","kind":"clinical","origin":"ai"},{"id":"intermediate-filaments~ai-3","moduleId":"intermediate-filaments","stem":"In which condition would you expect to find Mallory bodies in hepatocytes?","options":[{"id":"a","text":"Hepatitis"},{"id":"b","text":"Alcoholic liver disease"},{"id":"c","text":"Non-alcoholic fatty liver disease"},{"id":"d","text":"Hepatocellular carcinoma"}],"answerId":"b","explanation":"Mallory bodies are associated with alcoholic liver disease, representing clumped keratin intermediate filaments.","kind":"clinical","origin":"ai"},{"id":"intermediate-filaments~ai-4","moduleId":"intermediate-filaments","stem":"Which statement about intermediate filaments is true?","options":[{"id":"a","text":"They are dynamic and polar like microtubules."},{"id":"b","text":"They are stable and non-polar."},{"id":"c","text":"They utilize motor proteins for movement."},{"id":"d","text":"They are involved in cell division."}],"answerId":"b","explanation":"Intermediate filaments are stable, non-polar structures that do not use motor proteins.","kind":"trap","origin":"ai"},{"id":"intermediate-filaments~ai-5","moduleId":"intermediate-filaments","stem":"A patient with a glioma shows positive staining for GFAP. What does this indicate?","options":[{"id":"a","text":"Epithelial origin"},{"id":"b","text":"Mesenchymal origin"},{"id":"c","text":"Astrocytic origin"},{"id":"d","text":"Neuronal origin"}],"answerId":"c","explanation":"GFAP positivity indicates the tumor's astrocytic origin, characteristic of gliomas.","kind":"clinical","origin":"ai"},{"id":"intermediate-filaments~ai-6","moduleId":"intermediate-filaments","stem":"How are intermediate filaments related to cell junctions?","options":[{"id":"a","text":"They form tight junctions."},{"id":"b","text":"They anchor desmosomes."},{"id":"c","text":"They are involved in gap junctions."},{"id":"d","text":"They facilitate adherens junctions."}],"answerId":"b","explanation":"Intermediate filaments anchor desmosomes, providing mechanical strength to cell junctions.","kind":"integration","linkedModuleIds":["cell-junctions"],"origin":"ai"},{"id":"intermediate-filaments~ai-7","moduleId":"intermediate-filaments","stem":"Which intermediate filament is associated with neurofibrillary tangles in Alzheimer's disease?","options":[{"id":"a","text":"Keratin"},{"id":"b","text":"Vimentin"},{"id":"c","text":"Desmin"},{"id":"d","text":"Neurofilament"}],"answerId":"d","explanation":"Neurofibrillary tangles contain neurofilaments and tau protein, characteristic of Alzheimer's pathology.","kind":"recall","origin":"ai"},{"id":"intermediate-filaments~ai-8","moduleId":"intermediate-filaments","stem":"How do intermediate filaments differ from actin filaments?","options":[{"id":"a","text":"Intermediate filaments are dynamic and polar."},{"id":"b","text":"Intermediate filaments lack motor proteins."},{"id":"c","text":"Actin filaments are tissue-specific."},{"id":"d","text":"Both provide mechanical support."}],"answerId":"b","explanation":"Unlike actin filaments, intermediate filaments are stable, non-polar, and do not have associated motor proteins.","kind":"trap","origin":"ai"}],"vaccines-immunization":[{"id":"vaccines-immunization~ai-0","moduleId":"vaccines-immunization","stem":"What is the primary mechanism of live-attenuated vaccines?","options":[{"id":"a","text":"Inducing passive immunity"},{"id":"b","text":"Stimulating a strong immune response"},{"id":"c","text":"Providing immediate protection"},{"id":"d","text":"Generating memory through active immunity"}],"answerId":"d","explanation":"Live-attenuated vaccines stimulate a strong immune response and generate memory through active immunity.","kind":"mechanism","origin":"ai"},{"id":"vaccines-immunization~ai-1","moduleId":"vaccines-immunization","stem":"Which of the following vaccines is contraindicated in pregnant women?","options":[{"id":"a","text":"Hepatitis A vaccine"},{"id":"b","text":"Tetanus toxoid vaccine"},{"id":"c","text":"MMR vaccine"},{"id":"d","text":"Inactivated polio vaccine"}],"answerId":"c","explanation":"The MMR vaccine is a live-attenuated vaccine and is contraindicated in pregnancy due to the risk of reversion and disease.","kind":"trap","origin":"ai"},{"id":"vaccines-immunization~ai-2","moduleId":"vaccines-immunization","stem":"What is the primary benefit of conjugate vaccines in infants?","options":[{"id":"a","text":"Immediate protection"},{"id":"b","text":"T-independent response"},{"id":"c","text":"T-dependent response and memory"},{"id":"d","text":"Single-dose effectiveness"}],"answerId":"c","explanation":"Conjugate vaccines provide a T-dependent response and generate memory, which is crucial for infants.","kind":"mechanism","origin":"ai"},{"id":"vaccines-immunization~ai-3","moduleId":"vaccines-immunization","stem":"Which type of vaccine requires boosters due to weaker immune response?","options":[{"id":"a","text":"Live-attenuated vaccines"},{"id":"b","text":"Inactivated vaccines"},{"id":"c","text":"Subunit vaccines"},{"id":"d","text":"Conjugate vaccines"}],"answerId":"b","explanation":"Inactivated vaccines typically require boosters because they elicit a weaker immune response compared to live-attenuated vaccines.","kind":"recall","origin":"ai"},{"id":"vaccines-immunization~ai-4","moduleId":"vaccines-immunization","stem":"A patient presents with a deep laceration. What should be administered to provide immediate protection against tetanus?","options":[{"id":"a","text":"Tetanus toxoid vaccine"},{"id":"b","text":"Tetanus immunoglobulin"},{"id":"c","text":"Live-attenuated tetanus vaccine"},{"id":"d","text":"Inactivated tetanus vaccine"}],"answerId":"b","explanation":"Tetanus immunoglobulin provides immediate protection through passive immunization.","kind":"clinical","origin":"ai"},{"id":"vaccines-immunization~ai-5","moduleId":"vaccines-immunization","stem":"How does herd immunity protect vulnerable populations?","options":[{"id":"a","text":"By providing immediate immunity to all"},{"id":"b","text":"By reducing overall transmission in the community"},{"id":"c","text":"By enhancing individual immune responses"},{"id":"d","text":"By increasing vaccine efficacy"}],"answerId":"b","explanation":"Herd immunity protects vulnerable populations by reducing overall transmission in the community, thereby indirectly protecting those who cannot be vaccinated.","kind":"recall","origin":"ai"},{"id":"vaccines-immunization~ai-6","moduleId":"vaccines-immunization","stem":"Which mechanism is primarily involved in the generation of memory B cells after vaccination?","options":[{"id":"a","text":"Passive immunity"},{"id":"b","text":"Affinity maturation"},{"id":"c","text":"Immediate antibody response"},{"id":"d","text":"T-independent activation"}],"answerId":"b","explanation":"Affinity maturation is a key process in the generation of memory B cells following vaccination, linking to the germinal center response.","kind":"integration","linkedModuleIds":["germinal-center-antibody-response"],"origin":"ai"},{"id":"vaccines-immunization~ai-7","moduleId":"vaccines-immunization","stem":"What is the role of adjuvants in vaccines?","options":[{"id":"a","text":"To provide passive immunity"},{"id":"b","text":"To enhance the innate immune response"},{"id":"c","text":"To induce immediate protection"},{"id":"d","text":"To create live-attenuated vaccines"}],"answerId":"b","explanation":"Adjuvants enhance the innate immune response, thereby strengthening and shaping the adaptive immune response to the vaccine.","kind":"mechanism","origin":"ai"},{"id":"vaccines-immunization~ai-8","moduleId":"vaccines-immunization","stem":"Which type of vaccine is most suitable for an immunocompromised patient?","options":[{"id":"a","text":"Live-attenuated vaccine"},{"id":"b","text":"Inactivated vaccine"},{"id":"c","text":"Conjugate vaccine"},{"id":"d","text":"Subunit vaccine"}],"answerId":"b","explanation":"Inactivated vaccines are safe for immunocompromised patients as they do not contain live pathogens that could cause disease.","kind":"trap","origin":"ai"}],"nucleus-chromatin-nucleolus":[{"id":"nucleus-chromatin-nucleolus~ai-0","moduleId":"nucleus-chromatin-nucleolus","stem":"Which of the following best describes euchromatin?","options":[{"id":"a","text":"Condensed and dark, transcriptionally inactive"},{"id":"b","text":"Loosely packed and pale, transcriptionally active"},{"id":"c","text":"Highly compacted, resistant to transcription"},{"id":"d","text":"Visible as a Barr body in female cells"}],"answerId":"b","explanation":"Euchromatin is characterized by its loose packing and pale appearance, indicating active transcription.","kind":"recall","origin":"ai"},{"id":"nucleus-chromatin-nucleolus~ai-1","moduleId":"nucleus-chromatin-nucleolus","stem":"What is the primary function of the nucleolus?","options":[{"id":"a","text":"DNA replication"},{"id":"b","text":"Ribosomal RNA synthesis"},{"id":"c","text":"Protein degradation"},{"id":"d","text":"Lipid synthesis"}],"answerId":"b","explanation":"The nucleolus is primarily involved in the synthesis of ribosomal RNA and the assembly of ribosomal subunits.","kind":"recall","origin":"ai"},{"id":"nucleus-chromatin-nucleolus~ai-2","moduleId":"nucleus-chromatin-nucleolus","stem":"A female patient presents with neutrophils exhibiting a drumstick appendage. What does this finding indicate?","options":[{"id":"a","text":"Active transcription in neutrophils"},{"id":"b","text":"Presence of Barr body"},{"id":"c","text":"Increased protein synthesis"},{"id":"d","text":"Cellular dysplasia"}],"answerId":"b","explanation":"The drumstick appendage represents a Barr body, indicating the presence of an inactive X chromosome in female neutrophils.","kind":"recall","origin":"ai"},{"id":"nucleus-chromatin-nucleolus~ai-3","moduleId":"nucleus-chromatin-nucleolus","stem":"Which of the following findings would most likely indicate malignancy in a cell?","options":[{"id":"a","text":"Normal nuclear shape and size"},{"id":"b","text":"Enlarged pleomorphic nuclei with a high N:C ratio"},{"id":"c","text":"Presence of a prominent nucleolus"},{"id":"d","text":"Well-defined nuclear membrane"}],"answerId":"b","explanation":"Enlarged pleomorphic nuclei with a high nuclear-to-cytoplasmic ratio are indicative of dysplasia or malignancy.","kind":"clinical","origin":"ai"},{"id":"nucleus-chromatin-nucleolus~ai-4","moduleId":"nucleus-chromatin-nucleolus","stem":"What is the mechanism behind the appearance of a small, dense, hyperchromatic nucleus in lymphocytes?","options":[{"id":"a","text":"High levels of euchromatin"},{"id":"b","text":"Dominance of heterochromatin"},{"id":"c","text":"Active ribosome production"},{"id":"d","text":"Increased DNA replication"}],"answerId":"b","explanation":"The small, dense, hyperchromatic nucleus indicates a dominance of heterochromatin, reflecting transcriptional inactivity.","kind":"mechanism","origin":"ai"},{"id":"nucleus-chromatin-nucleolus~ai-5","moduleId":"nucleus-chromatin-nucleolus","stem":"How does the structure of chromatin relate to its function in gene expression?","options":[{"id":"a","text":"Condensed chromatin is actively transcribed"},{"id":"b","text":"Euchromatin is accessible for transcription"},{"id":"c","text":"Heterochromatin facilitates gene activation"},{"id":"d","text":"Nuclear lamina prevents transcription"}],"answerId":"b","explanation":"Euchromatin is loosely packed and accessible, allowing for active transcription, while heterochromatin is condensed and inactive.","kind":"trap","origin":"ai"},{"id":"nucleus-chromatin-nucleolus~ai-6","moduleId":"nucleus-chromatin-nucleolus","stem":"In a histological examination of thyroid tissue, which feature indicates high protein synthesis activity?","options":[{"id":"a","text":"Presence of multiple Barr bodies"},{"id":"b","text":"Large, pale vesicular nuclei with prominent nucleoli"},{"id":"c","text":"Dense, hyperchromatic nuclei"},{"id":"d","text":"Small, compact nuclei with minimal cytoplasm"}],"answerId":"b","explanation":"Large, pale vesicular nuclei with prominent nucleoli indicate active protein synthesis, typical of cells like thyroid follicular cells.","kind":"integration","linkedModuleIds":["hen1-thyroid-histology"],"origin":"ai"},{"id":"nucleus-chromatin-nucleolus~ai-7","moduleId":"nucleus-chromatin-nucleolus","stem":"Which chromatin feature would you expect to see in a cell undergoing significant transcriptional activity?","options":[{"id":"a","text":"High levels of heterochromatin"},{"id":"b","text":"Pale, dispersed euchromatin"},{"id":"c","text":"Presence of Barr bodies"},{"id":"d","text":"Condensed chromatin structure"}],"answerId":"b","explanation":"Pale, dispersed euchromatin is indicative of active transcription, contrasting with the condensed structure of heterochromatin.","kind":"integration","linkedModuleIds":["chromatin-packaging"],"origin":"ai"}],"histology-methods-staining":[{"id":"histology-methods-staining~ai-0","moduleId":"histology-methods-staining","stem":"What color does haematoxylin stain the nucleus?","options":[{"id":"a","text":"Pink"},{"id":"b","text":"Green"},{"id":"c","text":"Blue"},{"id":"d","text":"Yellow"}],"answerId":"c","explanation":"Haematoxylin is a basic dye that binds to acidic components like DNA, resulting in a blue stain for the nucleus.","kind":"recall","origin":"ai"},{"id":"histology-methods-staining~ai-1","moduleId":"histology-methods-staining","stem":"Which component is primarily responsible for the blue staining of Nissl bodies in neurons?","options":[{"id":"a","text":"Collagen"},{"id":"b","text":"Ribosomal RNA"},{"id":"c","text":"Hemoglobin"},{"id":"d","text":"Mitochondria"}],"answerId":"b","explanation":"Nissl bodies contain abundant ribosomal RNA, which is basophilic and stains blue with haematoxylin.","kind":"mechanism","origin":"ai"},{"id":"histology-methods-staining~ai-2","moduleId":"histology-methods-staining","stem":"What is the primary reason for eosinophilia in muscle cells?","options":[{"id":"a","text":"High lipid content"},{"id":"b","text":"High protein content"},{"id":"c","text":"High nucleic acid content"},{"id":"d","text":"High carbohydrate content"}],"answerId":"b","explanation":"Muscle cells are rich in proteins such as actin and myosin, which are positively charged and bind the acidic dye eosin, resulting in a pink stain.","kind":"mechanism","origin":"ai"},{"id":"histology-methods-staining~ai-3","moduleId":"histology-methods-staining","stem":"A patient sample shows magenta staining of the basement membrane. Which stain was likely used?","options":[{"id":"a","text":"Hematoxylin"},{"id":"b","text":"Eosin"},{"id":"c","text":"PAS"},{"id":"d","text":"Sudan Black"}],"answerId":"c","explanation":"Periodic acid-Schiff (PAS) stain is used to identify carbohydrates, which appear magenta.","kind":"clinical","origin":"ai"},{"id":"histology-methods-staining~ai-4","moduleId":"histology-methods-staining","stem":"Which of the following statements about haematoxylin is correct?","options":[{"id":"a","text":"It stains proteins pink."},{"id":"b","text":"It stains nucleic acids blue."},{"id":"c","text":"It stains lipids black."},{"id":"d","text":"It stains carbohydrates green."}],"answerId":"b","explanation":"Haematoxylin is a basic dye that specifically stains acidic components like nucleic acids blue.","kind":"trap","origin":"ai"},{"id":"histology-methods-staining~ai-5","moduleId":"histology-methods-staining","stem":"How does light microscopy differ from electron microscopy in histology?","options":[{"id":"a","text":"LM shows ultrastructure; TEM shows tissue architecture."},{"id":"b","text":"LM uses basic dyes; TEM uses acidic dyes."},{"id":"c","text":"LM provides a 3-D view; TEM provides a 2-D view."},{"id":"d","text":"LM shows tissue architecture; TEM shows internal ultrastructure."}],"answerId":"d","explanation":"Light microscopy (LM) reveals tissue architecture, while transmission electron microscopy (TEM) reveals internal ultrastructure.","kind":"mechanism","origin":"ai"},{"id":"histology-methods-staining~ai-6","moduleId":"histology-methods-staining","stem":"Which histological method would be most appropriate for rapid intra-operative diagnosis?","options":[{"id":"a","text":"Paraffin section"},{"id":"b","text":"Frozen section"},{"id":"c","text":"Electron microscopy"},{"id":"d","text":"Flow cytometry"}],"answerId":"b","explanation":"Frozen sections are used for rapid intra-operative diagnosis due to their quick preparation time.","kind":"clinical","origin":"ai"},{"id":"histology-methods-staining~ai-7","moduleId":"histology-methods-staining","stem":"How does the staining of the nucleus relate to subcellular alterations in disease?","options":[{"id":"a","text":"Nuclear staining indicates protein levels."},{"id":"b","text":"Nuclear staining reflects lipid accumulation."},{"id":"c","text":"Nuclear staining indicates nucleic acid changes."},{"id":"d","text":"Nuclear staining shows carbohydrate presence."}],"answerId":"c","explanation":"Changes in nuclear staining can indicate alterations in nucleic acids, which may reflect disease processes.","kind":"integration","linkedModuleIds":["subcellular-pathology-alterations"],"origin":"ai"},{"id":"histology-methods-staining~ai-8","moduleId":"histology-methods-staining","stem":"Which staining method would be most relevant when studying chromatin alterations in the nucleus?","options":[{"id":"a","text":"H&E"},{"id":"b","text":"PAS"},{"id":"c","text":"IHC"},{"id":"d","text":"Sudan Black"}],"answerId":"a","explanation":"H&E staining is fundamental for visualizing chromatin and nuclear structure in histological samples.","kind":"integration","linkedModuleIds":["nucleus-chromatin-nucleolus"],"origin":"ai"}],"cell-junctions":[{"id":"cell-junctions~ai-0","moduleId":"cell-junctions","stem":"Which protein is primarily responsible for forming tight junctions?","options":[{"id":"a","text":"Desmoglein"},{"id":"b","text":"Occludin"},{"id":"c","text":"Cadherin"},{"id":"d","text":"Integrin"}],"answerId":"b","explanation":"Occludin is a key component of tight junctions that helps seal the paracellular space.","kind":"recall","origin":"ai"},{"id":"cell-junctions~ai-1","moduleId":"cell-junctions","stem":"What is the primary function of desmosomes in epithelial tissue?","options":[{"id":"a","text":"Cell signaling"},{"id":"b","text":"Mechanical strength"},{"id":"c","text":"Nutrient transport"},{"id":"d","text":"Ion exchange"}],"answerId":"b","explanation":"Desmosomes provide mechanical strength by anchoring intermediate filaments, allowing tissues to withstand stress.","kind":"recall","origin":"ai"},{"id":"cell-junctions~ai-2","moduleId":"cell-junctions","stem":"Which junction type is crucial for electrical coupling in cardiac muscle?","options":[{"id":"a","text":"Tight junction"},{"id":"b","text":"Adherens junction"},{"id":"c","text":"Desmosome"},{"id":"d","text":"Gap junction"}],"answerId":"d","explanation":"Gap junctions allow for direct electrical coupling between cardiac muscle cells, facilitating synchronized contraction.","kind":"recall","origin":"ai"},{"id":"cell-junctions~ai-3","moduleId":"cell-junctions","stem":"In which junction are cadherins linked to actin filaments?","options":[{"id":"a","text":"Tight junction"},{"id":"b","text":"Desmosome"},{"id":"c","text":"Zonula adherens"},{"id":"d","text":"Hemidesmosome"}],"answerId":"c","explanation":"Zonula adherens junctions utilize cadherins to link to actin filaments, providing lateral adhesion.","kind":"recall","origin":"ai"},{"id":"cell-junctions~ai-4","moduleId":"cell-junctions","stem":"What is the primary anchoring filament in desmosomes?","options":[{"id":"a","text":"Actin"},{"id":"b","text":"Keratin"},{"id":"c","text":"Collagen"},{"id":"d","text":"Elastin"}],"answerId":"b","explanation":"Desmosomes anchor to keratin intermediate filaments, while adherens junctions anchor to actin filaments.","kind":"trap","origin":"ai"},{"id":"cell-junctions~ai-5","moduleId":"cell-junctions","stem":"A patient presents with blistering skin lesions. Which junction type is most likely affected?","options":[{"id":"a","text":"Tight junction"},{"id":"b","text":"Desmosome"},{"id":"c","text":"Gap junction"},{"id":"d","text":"Hemidesmosome"}],"answerId":"d","explanation":"Hemidesmosomes anchor cells to the basement membrane, and their failure can lead to blistering conditions like bullous pemphigoid.","kind":"clinical","origin":"ai"},{"id":"cell-junctions~ai-6","moduleId":"cell-junctions","stem":"How do gap junctions facilitate communication between cardiac muscle cells?","options":[{"id":"a","text":"By forming tight seals"},{"id":"b","text":"By anchoring to the basement membrane"},{"id":"c","text":"By allowing ion flow through connexons"},{"id":"d","text":"By linking to actin filaments"}],"answerId":"c","explanation":"Gap junctions consist of connexons that permit the passage of ions and small molecules, enabling electrical coupling.","kind":"mechanism","origin":"ai"},{"id":"cell-junctions~ai-7","moduleId":"cell-junctions","stem":"Which type of junction is primarily involved in maintaining the integrity of the epithelial barrier?","options":[{"id":"a","text":"Zonula adherens"},{"id":"b","text":"Tight junction"},{"id":"c","text":"Desmosome"},{"id":"d","text":"Gap junction"}],"answerId":"b","explanation":"Tight junctions create a seal that prevents leakage between epithelial cells, maintaining barrier integrity.","kind":"recall","origin":"ai"},{"id":"cell-junctions~ai-8","moduleId":"cell-junctions","stem":"How do intermediate filaments relate to desmosomes in epithelial cells?","options":[{"id":"a","text":"They form the tight junctions"},{"id":"b","text":"They anchor the desmosomes"},{"id":"c","text":"They facilitate gap junction communication"},{"id":"d","text":"They are not involved with desmosomes"}],"answerId":"b","explanation":"Intermediate filaments, specifically keratin, anchor desmosomes, providing mechanical stability to epithelial tissues.","kind":"integration","linkedModuleIds":["intermediate-filaments"],"origin":"ai"},{"id":"cell-junctions~ai-9","moduleId":"cell-junctions","stem":"What role do hemidesmosomes play in relation to the basement membrane?","options":[{"id":"a","text":"They create tight seals"},{"id":"b","text":"They anchor cells to the basement membrane"},{"id":"c","text":"They facilitate cell communication"},{"id":"d","text":"They provide mechanical strength"}],"answerId":"b","explanation":"Hemidesmosomes anchor epithelial cells to the basement membrane, crucial for tissue integrity.","kind":"integration","linkedModuleIds":["epithelial-surface-basement-membrane"],"origin":"ai"}],"epithelial-surface-basement-membrane":[{"id":"epithelial-surface-basement-membrane~ai-0","moduleId":"epithelial-surface-basement-membrane","stem":"What type of cytoskeletal structure is found in microvilli?","options":[{"id":"a","text":"Microtubules"},{"id":"b","text":"Actin filaments"},{"id":"c","text":"Intermediate filaments"},{"id":"d","text":"Collagen fibers"}],"answerId":"b","explanation":"Microvilli are composed of an actin filament core, which supports their structure and function in absorption.","kind":"recall","origin":"ai"},{"id":"epithelial-surface-basement-membrane~ai-1","moduleId":"epithelial-surface-basement-membrane","stem":"Which of the following is a characteristic of cilia?","options":[{"id":"a","text":"Non-motile projections"},{"id":"b","text":"Actin core"},{"id":"c","text":"9+2 microtubule arrangement"},{"id":"d","text":"Found in the small intestine"}],"answerId":"c","explanation":"Cilia are motile structures characterized by a 9+2 arrangement of microtubules, allowing them to move fluid across epithelial surfaces.","kind":"recall","origin":"ai"},{"id":"epithelial-surface-basement-membrane~ai-2","moduleId":"epithelial-surface-basement-membrane","stem":"What is the primary function of the basement membrane?","options":[{"id":"a","text":"Absorption of nutrients"},{"id":"b","text":"Selective filtration"},{"id":"c","text":"Mechanical support for cilia"},{"id":"d","text":"Protection against pathogens"}],"answerId":"b","explanation":"The basement membrane serves as a selective filtration barrier, particularly in structures like the glomerulus.","kind":"recall","origin":"ai"},{"id":"epithelial-surface-basement-membrane~ai-3","moduleId":"epithelial-surface-basement-membrane","stem":"Which structure is responsible for anchoring the epithelium to the basement membrane?","options":[{"id":"a","text":"Desmosomes"},{"id":"b","text":"Tight junctions"},{"id":"c","text":"Hemidesmosomes"},{"id":"d","text":"Adherens junctions"}],"answerId":"c","explanation":"Hemidesmosomes are specialized structures that anchor the epithelium to the basement membrane.","kind":"recall","origin":"ai"},{"id":"epithelial-surface-basement-membrane~ai-4","moduleId":"epithelial-surface-basement-membrane","stem":"On electron microscopy, which layer of the basement membrane is characterized by an electron-dense appearance?","options":[{"id":"a","text":"Lamina lucida"},{"id":"b","text":"Reticular lamina"},{"id":"c","text":"Lamina densa"},{"id":"d","text":"Basal lamina"}],"answerId":"c","explanation":"The lamina densa is the electron-dense layer of the basement membrane, primarily composed of type IV collagen.","kind":"recall","origin":"ai"},{"id":"epithelial-surface-basement-membrane~ai-5","moduleId":"epithelial-surface-basement-membrane","stem":"A patient presents with infertility due to impaired sperm maturation. Which structure in the epididymis is likely affected?","options":[{"id":"a","text":"Microvilli"},{"id":"b","text":"Cilia"},{"id":"c","text":"Stereocilia"},{"id":"d","text":"Basement membrane"}],"answerId":"c","explanation":"Stereocilia in the epididymis are involved in sperm maturation and absorption; their dysfunction can lead to infertility.","kind":"clinical","origin":"ai"},{"id":"epithelial-surface-basement-membrane~ai-6","moduleId":"epithelial-surface-basement-membrane","stem":"Which of the following correctly differentiates microvilli from cilia?","options":[{"id":"a","text":"Both are motile and have a microtubule core"},{"id":"b","text":"Microvilli are motile, cilia are non-motile"},{"id":"c","text":"Microvilli have an actin core, cilia have a microtubule core"},{"id":"d","text":"Microvilli are found in the respiratory tract, cilia are found in the intestine"}],"answerId":"c","explanation":"Microvilli have an actin core and are non-motile, while cilia have a microtubule core and are motile, which is a common exam distractor.","kind":"trap","origin":"ai"},{"id":"epithelial-surface-basement-membrane~ai-7","moduleId":"epithelial-surface-basement-membrane","stem":"How do cilia contribute to respiratory health?","options":[{"id":"a","text":"By absorbing nutrients"},{"id":"b","text":"By moving mucus out of the airway"},{"id":"c","text":"By providing structural support"},{"id":"d","text":"By forming a barrier to pathogens"}],"answerId":"b","explanation":"Cilia in the respiratory tract move mucus out of the airway, helping to clear pathogens and debris.","kind":"integration","linkedModuleIds":["microtubules-motors-centrosome"],"origin":"ai"},{"id":"epithelial-surface-basement-membrane~ai-8","moduleId":"epithelial-surface-basement-membrane","stem":"What is the role of the basement membrane in the context of placental villi?","options":[{"id":"a","text":"Facilitating nutrient absorption"},{"id":"b","text":"Providing structural integrity"},{"id":"c","text":"Acting as a barrier to maternal blood"},{"id":"d","text":"Supporting cilia function"}],"answerId":"c","explanation":"The basement membrane in placental villi acts as a barrier to maternal blood, allowing selective nutrient transfer while protecting the fetus.","kind":"integration","linkedModuleIds":["hrp1-placenta-villi-barrier-circulation"],"origin":"ai"}],"cytoplasmic-organelles":[{"id":"cytoplasmic-organelles~ai-0","moduleId":"cytoplasmic-organelles","stem":"What is the primary function of mitochondria in cells?","options":[{"id":"a","text":"Protein synthesis"},{"id":"b","text":"ATP production"},{"id":"c","text":"Lipid synthesis"},{"id":"d","text":"Intracellular digestion"}],"answerId":"b","explanation":"Mitochondria are known as the ATP factories of the cell, responsible for energy production through oxidative phosphorylation.","kind":"recall","origin":"ai"},{"id":"cytoplasmic-organelles~ai-1","moduleId":"cytoplasmic-organelles","stem":"Which organelle is primarily involved in the synthesis of secretory proteins?","options":[{"id":"a","text":"Smooth endoplasmic reticulum"},{"id":"b","text":"Rough endoplasmic reticulum"},{"id":"c","text":"Golgi apparatus"},{"id":"d","text":"Lysosome"}],"answerId":"b","explanation":"The rough endoplasmic reticulum is studded with ribosomes and is responsible for synthesizing membrane-bound and secretory proteins.","kind":"recall","origin":"ai"},{"id":"cytoplasmic-organelles~ai-2","moduleId":"cytoplasmic-organelles","stem":"What type of cytoplasmic inclusions are PAS-positive in hepatocytes?","options":[{"id":"a","text":"Lipid droplets"},{"id":"b","text":"Glycogen"},{"id":"c","text":"Melanin"},{"id":"d","text":"Haemosiderin"}],"answerId":"b","explanation":"Glycogen inclusions in hepatocytes are detected by PAS staining, indicating their carbohydrate content.","kind":"recall","origin":"ai"},{"id":"cytoplasmic-organelles~ai-3","moduleId":"cytoplasmic-organelles","stem":"Which organelle is responsible for breaking down hydrogen peroxide?","options":[{"id":"a","text":"Lysosome"},{"id":"b","text":"Peroxisome"},{"id":"c","text":"Mitochondria"},{"id":"d","text":"Rough endoplasmic reticulum"}],"answerId":"b","explanation":"Peroxisomes contain enzymes like catalase that break down hydrogen peroxide into water and oxygen.","kind":"recall","origin":"ai"},{"id":"cytoplasmic-organelles~ai-4","moduleId":"cytoplasmic-organelles","stem":"A patient presents with brown perinuclear granules in old cells. What do these granules represent?","options":[{"id":"a","text":"Glycogen inclusions"},{"id":"b","text":"Lipid droplets"},{"id":"c","text":"Lipofuscin"},{"id":"d","text":"Melanin"}],"answerId":"c","explanation":"Lipofuscin is a marker of aging and represents residual bodies in cells, often seen as brown granules.","kind":"clinical","origin":"ai"},{"id":"cytoplasmic-organelles~ai-5","moduleId":"cytoplasmic-organelles","stem":"Which of the following statements is true regarding organelles and inclusions?","options":[{"id":"a","text":"Glycogen is an organelle"},{"id":"b","text":"Lipid droplets are metabolically active"},{"id":"c","text":"Inclusions are non-membranous stored materials"},{"id":"d","text":"Mitochondria are inclusions"}],"answerId":"c","explanation":"Inclusions are non-membranous stored materials, while organelles are metabolically active structures.","kind":"trap","origin":"ai"},{"id":"cytoplasmic-organelles~ai-6","moduleId":"cytoplasmic-organelles","stem":"How does the function of the Golgi apparatus relate to the rough endoplasmic reticulum?","options":[{"id":"a","text":"It synthesizes proteins"},{"id":"b","text":"It modifies and sorts proteins"},{"id":"c","text":"It detoxifies substances"},{"id":"d","text":"It stores calcium ions"}],"answerId":"b","explanation":"The Golgi apparatus modifies, sorts, and packages proteins synthesized in the rough endoplasmic reticulum for their final destinations.","kind":"integration","linkedModuleIds":["subcellular-pathology-alterations"],"origin":"ai"},{"id":"cytoplasmic-organelles~ai-7","moduleId":"cytoplasmic-organelles","stem":"What staining method would best highlight ribosomes in a tissue sample?","options":[{"id":"a","text":"H&E staining"},{"id":"b","text":"PAS staining"},{"id":"c","text":"Silver staining"},{"id":"d","text":"Basophilic staining"}],"answerId":"d","explanation":"Basophilic staining highlights ribosomes and rough endoplasmic reticulum due to their high RNA content.","kind":"integration","linkedModuleIds":["histology-methods-staining"],"origin":"ai"}],"microtubules-motors-centrosome":[{"id":"microtubules-motors-centrosome~ai-0","moduleId":"microtubules-motors-centrosome","stem":"What is the primary function of kinesin motor proteins?","options":[{"id":"a","text":"Transporting cargo toward the cell body"},{"id":"b","text":"Transporting cargo toward the axon terminal"},{"id":"c","text":"Stabilizing microtubules"},{"id":"d","text":"Nucleating new microtubules"}],"answerId":"b","explanation":"Kinesin is responsible for anterograde transport, moving cargo from the cell body toward the axon terminal.","kind":"recall","origin":"ai"},{"id":"microtubules-motors-centrosome~ai-1","moduleId":"microtubules-motors-centrosome","stem":"Which structure is characterized by a 9+2 arrangement of microtubules?","options":[{"id":"a","text":"Basal body"},{"id":"b","text":"Motile cilium"},{"id":"c","text":"Primary cilium"},{"id":"d","text":"Centrosome"}],"answerId":"b","explanation":"Motile cilia and flagella exhibit a 9+2 arrangement of microtubules, essential for their movement.","kind":"recall","origin":"ai"},{"id":"microtubules-motors-centrosome~ai-2","moduleId":"microtubules-motors-centrosome","stem":"What is the role of dynein in ciliary movement?","options":[{"id":"a","text":"Stabilizing microtubules"},{"id":"b","text":"Sliding doublets to bend the cilium"},{"id":"c","text":"Transporting cargo to the axon terminal"},{"id":"d","text":"Nucleating new microtubules"}],"answerId":"b","explanation":"Dynein arms slide the outer doublets of microtubules, facilitating the bending motion of cilia.","kind":"mechanism","origin":"ai"},{"id":"microtubules-motors-centrosome~ai-3","moduleId":"microtubules-motors-centrosome","stem":"A patient presents with situs inversus, bronchiectasis, and infertility. What is the likely underlying defect?","options":[{"id":"a","text":"Kinesin malfunction"},{"id":"b","text":"Dynein-arm defect"},{"id":"c","text":"Colchicine exposure"},{"id":"d","text":"Vinca alkaloid toxicity"}],"answerId":"b","explanation":"These symptoms are characteristic of primary ciliary dyskinesia due to a defect in dynein arms.","kind":"clinical","origin":"ai"},{"id":"microtubules-motors-centrosome~ai-4","moduleId":"microtubules-motors-centrosome","stem":"Which of the following statements about microtubules is FALSE?","options":[{"id":"a","text":"They are the thickest filaments in the cytoskeleton."},{"id":"b","text":"They are nucleated at the centrosome."},{"id":"c","text":"They are composed of actin monomers."},{"id":"d","text":"They show dynamic instability."}],"answerId":"c","explanation":"Microtubules are composed of α/β-tubulin dimers, not actin monomers, which are the building blocks of microfilaments.","kind":"trap","origin":"ai"},{"id":"microtubules-motors-centrosome~ai-5","moduleId":"microtubules-motors-centrosome","stem":"How do microtubules differ from intermediate filaments?","options":[{"id":"a","text":"Microtubules are not polar"},{"id":"b","text":"Microtubules are thicker than intermediate filaments"},{"id":"c","text":"Intermediate filaments are hollow"},{"id":"d","text":"Microtubules are composed of keratin"}],"answerId":"b","explanation":"Microtubules are indeed thicker than intermediate filaments, which are more variable in diameter and not hollow.","kind":"integration","linkedModuleIds":["intermediate-filaments"],"origin":"ai"},{"id":"microtubules-motors-centrosome~ai-6","moduleId":"microtubules-motors-centrosome","stem":"What is the primary role of the centrosome in relation to microtubules?","options":[{"id":"a","text":"Transporting vesicles"},{"id":"b","text":"Nucleating new microtubules"},{"id":"c","text":"Stabilizing microtubules"},{"id":"d","text":"Degrading damaged microtubules"}],"answerId":"b","explanation":"The centrosome serves as the microtubule-organizing center (MTOC) and is responsible for nucleating new microtubules.","kind":"recall","origin":"ai"},{"id":"microtubules-motors-centrosome~ai-7","moduleId":"microtubules-motors-centrosome","stem":"Which motor protein is responsible for retrograde transport in neurons?","options":[{"id":"a","text":"Kinesin"},{"id":"b","text":"Myosin"},{"id":"c","text":"Actin"},{"id":"d","text":"Dynein"}],"answerId":"d","explanation":"Dynein is the motor protein that facilitates retrograde transport, moving cargo toward the cell body.","kind":"recall","origin":"ai"},{"id":"microtubules-motors-centrosome~ai-8","moduleId":"microtubules-motors-centrosome","stem":"In the context of epithelial cells, how do microtubules contribute to cell function?","options":[{"id":"a","text":"By forming tight junctions"},{"id":"b","text":"By providing structural support"},{"id":"c","text":"By facilitating ciliary movement"},{"id":"d","text":"By anchoring the basement membrane"}],"answerId":"c","explanation":"Microtubules are crucial for the movement of cilia in epithelial cells, aiding in the clearance of mucus and pathogens.","kind":"integration","linkedModuleIds":["epithelial-surface-basement-membrane"],"origin":"ai"}],"glands-exocrine-endocrine":[{"id":"glands-exocrine-endocrine~ai-0","moduleId":"glands-exocrine-endocrine","stem":"Which type of secretion involves the entire cell disintegrating to release its product?","options":[{"id":"a","text":"Merocrine"},{"id":"b","text":"Apocrine"},{"id":"c","text":"Holocrine"},{"id":"d","text":"Endocrine"}],"answerId":"c","explanation":"Holocrine secretion involves the entire cell breaking down to release its contents, as seen in sebaceous glands.","kind":"recall","origin":"ai"},{"id":"glands-exocrine-endocrine~ai-1","moduleId":"glands-exocrine-endocrine","stem":"What is the primary mode of secretion for salivary glands?","options":[{"id":"a","text":"Holocrine"},{"id":"b","text":"Apocrine"},{"id":"c","text":"Merocrine"},{"id":"d","text":"Endocrine"}],"answerId":"c","explanation":"Salivary glands secrete via merocrine mode, which involves exocytosis while preserving the cell.","kind":"recall","origin":"ai"},{"id":"glands-exocrine-endocrine~ai-2","moduleId":"glands-exocrine-endocrine","stem":"Which gland type is characterized by a duct and secretes its product onto a surface?","options":[{"id":"a","text":"Endocrine"},{"id":"b","text":"Exocrine"},{"id":"c","text":"Holocrine"},{"id":"d","text":"Apocrine"}],"answerId":"b","explanation":"Exocrine glands have ducts and secrete their products onto epithelial surfaces.","kind":"recall","origin":"ai"},{"id":"glands-exocrine-endocrine~ai-3","moduleId":"glands-exocrine-endocrine","stem":"Identify the secretion mode of mammary glands.","options":[{"id":"a","text":"Merocrine"},{"id":"b","text":"Holocrine"},{"id":"c","text":"Apocrine"},{"id":"d","text":"Endocrine"}],"answerId":"c","explanation":"Mammary glands utilize apocrine secretion, where part of the cell's cytoplasm is shed with the secretion.","kind":"recall","origin":"ai"},{"id":"glands-exocrine-endocrine~ai-4","moduleId":"glands-exocrine-endocrine","stem":"What histological feature is indicative of serous secretory cells?","options":[{"id":"a","text":"Pale foamy cytoplasm"},{"id":"b","text":"Basophilic acinar cells with zymogen granules"},{"id":"c","text":"Flattened basal nuclei"},{"id":"d","text":"Unicellular structure"}],"answerId":"b","explanation":"Serous secretory cells are characterized by basophilic cytoplasm and zymogen granules, indicating protein secretion.","kind":"recall","origin":"ai"},{"id":"glands-exocrine-endocrine~ai-5","moduleId":"glands-exocrine-endocrine","stem":"Which gland type is incorrectly matched with its secretion mode? Sebaceous glands - Apocrine.","options":[{"id":"a","text":"True"},{"id":"b","text":"False"},{"id":"c","text":"Not enough information"},{"id":"d","text":"Depends on the context"}],"answerId":"b","explanation":"Sebaceous glands secrete via holocrine mode, not apocrine; this is a common trap.","kind":"trap","origin":"ai"},{"id":"glands-exocrine-endocrine~ai-6","moduleId":"glands-exocrine-endocrine","stem":"How do exocrine glands differ from endocrine glands in terms of secretion?","options":[{"id":"a","text":"Exocrine glands secrete into blood"},{"id":"b","text":"Endocrine glands have ducts"},{"id":"c","text":"Exocrine glands secrete onto surfaces"},{"id":"d","text":"Endocrine glands are unicellular"}],"answerId":"c","explanation":"Exocrine glands secrete onto epithelial surfaces, whereas endocrine glands release hormones directly into the bloodstream.","kind":"integration","linkedModuleIds":["dermis-appendages-glands"],"origin":"ai"},{"id":"glands-exocrine-endocrine~ai-7","moduleId":"glands-exocrine-endocrine","stem":"Which mode of secretion is primarily involved in the release of digestive enzymes from the pancreas?","options":[{"id":"a","text":"Holocrine"},{"id":"b","text":"Merocrine"},{"id":"c","text":"Apocrine"},{"id":"d","text":"Endocrine"}],"answerId":"b","explanation":"The pancreas primarily uses merocrine secretion to release digestive enzymes via exocytosis.","kind":"integration","linkedModuleIds":["pancreas-histology"],"origin":"ai"}],"connective-tissue-cells":[{"id":"connective-tissue-cells~ai-0","moduleId":"connective-tissue-cells","stem":"Which cell type is primarily responsible for synthesizing collagen in connective tissue?","options":[{"id":"a","text":"Mast cell"},{"id":"b","text":"Fibroblast"},{"id":"c","text":"Macrophage"},{"id":"d","text":"Plasma cell"}],"answerId":"b","explanation":"Fibroblasts are the main cells that synthesize collagen and other extracellular matrix components.","kind":"recall","origin":"ai"},{"id":"connective-tissue-cells~ai-1","moduleId":"connective-tissue-cells","stem":"What is the primary function of macrophages in connective tissue?","options":[{"id":"a","text":"Collagen synthesis"},{"id":"b","text":"Antibody production"},{"id":"c","text":"Phagocytosis"},{"id":"d","text":"Histamine release"}],"answerId":"c","explanation":"Macrophages are specialized for phagocytosis and play a key role in the immune response.","kind":"recall","origin":"ai"},{"id":"connective-tissue-cells~ai-2","moduleId":"connective-tissue-cells","stem":"Which of the following cells is characterized by a 'clock-face' nucleus?","options":[{"id":"a","text":"Fibroblast"},{"id":"b","text":"Adipocyte"},{"id":"c","text":"Plasma cell"},{"id":"d","text":"Mast cell"}],"answerId":"c","explanation":"Plasma cells are recognized by their eccentric, 'clock-face' nucleus and basophilic cytoplasm.","kind":"recall","origin":"ai"},{"id":"connective-tissue-cells~ai-3","moduleId":"connective-tissue-cells","stem":"How do mast cells contribute to allergic reactions?","options":[{"id":"a","text":"By producing antibodies"},{"id":"b","text":"By releasing histamine"},{"id":"c","text":"By phagocytosing pathogens"},{"id":"d","text":"By synthesizing collagen"}],"answerId":"b","explanation":"Mast cells release histamine upon IgE cross-linking, leading to vasodilation and inflammation in allergic reactions.","kind":"mechanism","origin":"ai"},{"id":"connective-tissue-cells~ai-4","moduleId":"connective-tissue-cells","stem":"What is the main difference between the origins of plasma cells and macrophages?","options":[{"id":"a","text":"Both derive from monocytes"},{"id":"b","text":"Plasma cells come from B lymphocytes"},{"id":"c","text":"Macrophages come from B lymphocytes"},{"id":"d","text":"Both are derived from fibroblasts"}],"answerId":"b","explanation":"Plasma cells derive from B lymphocytes, while macrophages originate from monocytes.","kind":"trap","origin":"ai"},{"id":"connective-tissue-cells~ai-5","moduleId":"connective-tissue-cells","stem":"Which connective tissue cell type is primarily involved in wound healing?","options":[{"id":"a","text":"Adipocyte"},{"id":"b","text":"Fibroblast"},{"id":"c","text":"Mast cell"},{"id":"d","text":"Macrophage"}],"answerId":"b","explanation":"Fibroblasts play a crucial role in wound healing by synthesizing collagen and other extracellular matrix components.","kind":"clinical","origin":"ai"},{"id":"connective-tissue-cells~ai-6","moduleId":"connective-tissue-cells","stem":"In the context of liver pathology, which resident cell type is responsible for phagocytosis?","options":[{"id":"a","text":"Hepatocyte"},{"id":"b","text":"Kupffer cell"},{"id":"c","text":"Fibroblast"},{"id":"d","text":"Adipocyte"}],"answerId":"b","explanation":"Kupffer cells are specialized macrophages in the liver that perform phagocytosis.","kind":"integration","linkedModuleIds":["liver-lobule-sinusoid"],"origin":"ai"},{"id":"connective-tissue-cells~ai-7","moduleId":"connective-tissue-cells","stem":"Which connective tissue cell type is most likely to be involved in the inflammatory response in the skin?","options":[{"id":"a","text":"Fibroblast"},{"id":"b","text":"Mast cell"},{"id":"c","text":"Plasma cell"},{"id":"d","text":"Adipocyte"}],"answerId":"b","explanation":"Mast cells release histamine and other mediators that are key in the inflammatory response.","kind":"integration","linkedModuleIds":["cutaneous-connective-tissue-diseases"],"origin":"ai"}],"skeletal-muscle-sarcomere":[{"id":"skeletal-muscle-sarcomere~ai-0","moduleId":"skeletal-muscle-sarcomere","stem":"What is the primary role of calcium ions in skeletal muscle contraction?","options":[{"id":"a","text":"To initiate the action potential"},{"id":"b","text":"To bind to troponin and facilitate actin-myosin interaction"},{"id":"c","text":"To energize myosin heads for cross-bridge cycling"},{"id":"d","text":"To shorten the sarcomere"}],"answerId":"b","explanation":"Calcium ions bind to troponin, causing a conformational change that moves tropomyosin and exposes binding sites on actin for myosin.","kind":"mechanism","origin":"ai"},{"id":"skeletal-muscle-sarcomere~ai-1","moduleId":"skeletal-muscle-sarcomere","stem":"Which of the following statements about the sarcomere is true?","options":[{"id":"a","text":"The A band shortens during muscle contraction."},{"id":"b","text":"The I band remains constant during contraction."},{"id":"c","text":"The H zone disappears when the muscle contracts."},{"id":"d","text":"The Z line moves away from the M line during contraction."}],"answerId":"c","explanation":"During contraction, the I band and H zone shorten while the A band remains constant; the Z lines move closer together.","kind":"trap","origin":"ai"},{"id":"skeletal-muscle-sarcomere~ai-2","moduleId":"skeletal-muscle-sarcomere","stem":"What is the structural unit of skeletal muscle contraction?","options":[{"id":"a","text":"Myofibril"},{"id":"b","text":"Sarcomere"},{"id":"c","text":"Muscle fiber"},{"id":"d","text":"Motor unit"}],"answerId":"b","explanation":"The sarcomere is the basic contractile unit of skeletal muscle, defined as the segment between two Z lines.","kind":"recall","origin":"ai"},{"id":"skeletal-muscle-sarcomere~ai-3","moduleId":"skeletal-muscle-sarcomere","stem":"What clinical finding is associated with myasthenia gravis?","options":[{"id":"a","text":"Increased muscle tone"},{"id":"b","text":"Ptosis and diplopia worsening with use"},{"id":"c","text":"Muscle hypertrophy"},{"id":"d","text":"Muscle fasciculations"}],"answerId":"b","explanation":"Myasthenia gravis is characterized by muscle weakness that worsens with activity, leading to symptoms like ptosis and diplopia.","kind":"clinical","origin":"ai"},{"id":"skeletal-muscle-sarcomere~ai-4","moduleId":"skeletal-muscle-sarcomere","stem":"How does botulinum toxin affect skeletal muscle function?","options":[{"id":"a","text":"Inhibits calcium release from the sarcoplasmic reticulum"},{"id":"b","text":"Blocks acetylcholine release at the neuromuscular junction"},{"id":"c","text":"Inhibits myosin ATPase activity"},{"id":"d","text":"Increases troponin sensitivity to calcium"}],"answerId":"b","explanation":"Botulinum toxin prevents the release of acetylcholine from motor neurons, leading to muscle paralysis.","kind":"mechanism","origin":"ai"},{"id":"skeletal-muscle-sarcomere~ai-5","moduleId":"skeletal-muscle-sarcomere","stem":"How does excitation-contraction coupling relate to muscle contraction?","options":[{"id":"a","text":"It involves the sliding of actin over myosin."},{"id":"b","text":"It is the process of converting electrical signals into mechanical contraction."},{"id":"c","text":"It is the mechanism by which ATP is produced in muscle cells."},{"id":"d","text":"It describes the role of myoblasts in muscle fiber formation."}],"answerId":"b","explanation":"Excitation-contraction coupling refers to the process by which an action potential in the muscle fiber leads to muscle contraction through calcium release.","kind":"integration","linkedModuleIds":["excitation-contraction-coupling"],"origin":"ai"},{"id":"skeletal-muscle-sarcomere~ai-6","moduleId":"skeletal-muscle-sarcomere","stem":"What energy system is primarily used during short bursts of high-intensity skeletal muscle contraction?","options":[{"id":"a","text":"Aerobic respiration"},{"id":"b","text":"Anaerobic glycolysis"},{"id":"c","text":"Beta-oxidation"},{"id":"d","text":"Oxidative phosphorylation"}],"answerId":"b","explanation":"Anaerobic glycolysis provides quick energy for short, intense activities by breaking down glucose without oxygen.","kind":"integration","linkedModuleIds":["muscle-energy-systems"],"origin":"ai"}],"neuron-structure-types":[{"id":"neuron-structure-types~ai-0","moduleId":"neuron-structure-types","stem":"Which part of the neuron is responsible for receiving input?","options":[{"id":"a","text":"Soma"},{"id":"b","text":"Axon"},{"id":"c","text":"Dendrites"},{"id":"d","text":"Axon hillock"}],"answerId":"c","explanation":"Dendrites are specialized to receive synaptic input from other neurons.","kind":"recall","origin":"ai"},{"id":"neuron-structure-types~ai-1","moduleId":"neuron-structure-types","stem":"What is the primary function of Nissl bodies in neurons?","options":[{"id":"a","text":"Signal transmission"},{"id":"b","text":"Protein synthesis"},{"id":"c","text":"Action potential generation"},{"id":"d","text":"Axonal transport"}],"answerId":"b","explanation":"Nissl bodies, composed of rough endoplasmic reticulum and ribosomes, are involved in protein synthesis.","kind":"recall","origin":"ai"},{"id":"neuron-structure-types~ai-2","moduleId":"neuron-structure-types","stem":"What is the consequence of chromatolysis in a neuron?","options":[{"id":"a","text":"Increased protein synthesis"},{"id":"b","text":"Axonal injury response"},{"id":"c","text":"Enhanced synaptic transmission"},{"id":"d","text":"Dendritic growth"}],"answerId":"b","explanation":"Chromatolysis indicates a reaction to axonal injury, characterized by dispersed Nissl substance.","kind":"mechanism","origin":"ai"},{"id":"neuron-structure-types~ai-3","moduleId":"neuron-structure-types","stem":"Where are Nissl bodies located in a neuron?","options":[{"id":"a","text":"In the axon only"},{"id":"b","text":"In the soma and dendrites"},{"id":"c","text":"In the axon hillock only"},{"id":"d","text":"Throughout the entire neuron"}],"answerId":"b","explanation":"Nissl bodies are present in the soma and dendrites but absent from the axon and axon hillock.","kind":"trap","origin":"ai"},{"id":"neuron-structure-types~ai-4","moduleId":"neuron-structure-types","stem":"Which type of neuron is characterized by a single process that splits into two branches?","options":[{"id":"a","text":"Multipolar"},{"id":"b","text":"Bipolar"},{"id":"c","text":"Pseudounipolar"},{"id":"d","text":"Unipolar"}],"answerId":"c","explanation":"Pseudounipolar neurons have a single process that bifurcates into central and peripheral branches.","kind":"recall","origin":"ai"},{"id":"neuron-structure-types~ai-5","moduleId":"neuron-structure-types","stem":"How does kinesin function in axonal transport?","options":[{"id":"a","text":"Carries cargo retrograde"},{"id":"b","text":"Carries cargo anterograde"},{"id":"c","text":"Involved in synaptic transmission"},{"id":"d","text":"Regulates protein synthesis"}],"answerId":"b","explanation":"Kinesin is a motor protein that transports cargo from the soma to the axon terminal in an anterograde manner.","kind":"mechanism","origin":"ai"},{"id":"neuron-structure-types~ai-6","moduleId":"neuron-structure-types","stem":"How does the structure of a pseudounipolar neuron relate to its function in sensory pathways?","options":[{"id":"a","text":"Facilitates rapid signal transmission"},{"id":"b","text":"Increases synaptic connections"},{"id":"c","text":"Enhances protein synthesis"},{"id":"d","text":"Supports axonal injury response"}],"answerId":"a","explanation":"The pseudounipolar structure allows for efficient transmission of sensory signals to the central nervous system.","kind":"integration","linkedModuleIds":["action-potential-genesis"],"origin":"ai"},{"id":"neuron-structure-types~ai-7","moduleId":"neuron-structure-types","stem":"What role do microtubules play in neuron function?","options":[{"id":"a","text":"Signal integration"},{"id":"b","text":"Protein synthesis"},{"id":"c","text":"Axonal transport"},{"id":"d","text":"Synaptic transmission"}],"answerId":"c","explanation":"Microtubules are essential for axonal transport, facilitating the movement of organelles and proteins along the axon.","kind":"integration","linkedModuleIds":["microtubules-motors-centrosome"],"origin":"ai"}],"connective-tissue-fibers-types":[{"id":"connective-tissue-fibers-types~ai-0","moduleId":"connective-tissue-fibers-types","stem":"What type of collagen is primarily found in dense regular connective tissue?","options":[{"id":"a","text":"Type I collagen"},{"id":"b","text":"Type II collagen"},{"id":"c","text":"Type III collagen"},{"id":"d","text":"Type IV collagen"}],"answerId":"a","explanation":"Dense regular connective tissue is characterized by parallel bundles of type I collagen, providing strength in one direction.","kind":"recall","origin":"ai"},{"id":"connective-tissue-fibers-types~ai-1","moduleId":"connective-tissue-fibers-types","stem":"Which connective tissue fiber type is primarily responsible for the recoil of arteries?","options":[{"id":"a","text":"Collagen fibers"},{"id":"b","text":"Reticular fibers"},{"id":"c","text":"Elastic fibers"},{"id":"d","text":"Ground substance"}],"answerId":"c","explanation":"Elastic fibers, composed of elastin and fibrillin, allow for the recoil of arteries after stretching.","kind":"mechanism","origin":"ai"},{"id":"connective-tissue-fibers-types~ai-2","moduleId":"connective-tissue-fibers-types","stem":"A biopsy reveals fine branching fibers that stain positively with silver stain in a lymph node. What type of fibers are these?","options":[{"id":"a","text":"Elastic fibers"},{"id":"b","text":"Type I collagen fibers"},{"id":"c","text":"Type III collagen fibers"},{"id":"d","text":"Type IV collagen fibers"}],"answerId":"c","explanation":"The fine branching fibers in lymph nodes are reticular fibers, which are composed of type III collagen and are argyrophilic.","kind":"recall","origin":"ai"},{"id":"connective-tissue-fibers-types~ai-3","moduleId":"connective-tissue-fibers-types","stem":"Which of the following is a characteristic of loose connective tissue?","options":[{"id":"a","text":"Dense bundles of collagen"},{"id":"b","text":"High cellularity and abundant ground substance"},{"id":"c","text":"Poor vascularity"},{"id":"d","text":"High tensile strength"}],"answerId":"b","explanation":"Loose connective tissue is characterized by high cellularity and abundant ground substance, allowing for flexibility and support.","kind":"trap","origin":"ai"},{"id":"connective-tissue-fibers-types~ai-4","moduleId":"connective-tissue-fibers-types","stem":"What is the primary function of ground substance in connective tissue?","options":[{"id":"a","text":"Provides tensile strength"},{"id":"b","text":"Facilitates diffusion and resists compression"},{"id":"c","text":"Stores fat"},{"id":"d","text":"Supports immune cells"}],"answerId":"b","explanation":"Ground substance is a hydrated gel that fills space, resists compression, and serves as a medium for diffusion.","kind":"mechanism","origin":"ai"},{"id":"connective-tissue-fibers-types~ai-5","moduleId":"connective-tissue-fibers-types","stem":"In which type of connective tissue would you find a high concentration of type III collagen?","options":[{"id":"a","text":"Dense regular connective tissue"},{"id":"b","text":"Loose connective tissue"},{"id":"c","text":"Reticular connective tissue"},{"id":"d","text":"Adipose tissue"}],"answerId":"c","explanation":"Reticular connective tissue is characterized by a fine mesh of type III collagen fibers, providing structural support in lymphoid organs.","kind":"recall","origin":"ai"},{"id":"connective-tissue-fibers-types~ai-6","moduleId":"connective-tissue-fibers-types","stem":"How does the composition of connective tissue fibers relate to cutaneous connective tissue diseases?","options":[{"id":"a","text":"Altered collagen types lead to skin fragility"},{"id":"b","text":"Increased elastic fibers cause skin laxity"},{"id":"c","text":"Decreased ground substance results in thickened skin"},{"id":"d","text":"Reticular fibers prevent immune response"}],"answerId":"a","explanation":"Alterations in collagen types can lead to conditions such as Ehlers-Danlos syndrome, which results in skin fragility.","kind":"integration","linkedModuleIds":["cutaneous-connective-tissue-diseases"],"origin":"ai"},{"id":"connective-tissue-fibers-types~ai-7","moduleId":"connective-tissue-fibers-types","stem":"Which type of connective tissue is primarily involved in the formation of the osteon in bone?","options":[{"id":"a","text":"Loose connective tissue"},{"id":"b","text":"Dense irregular connective tissue"},{"id":"c","text":"Cartilage"},{"id":"d","text":"Specialized connective tissue"}],"answerId":"d","explanation":"Bone is considered a specialized connective tissue that forms the osteon structure, providing strength and support.","kind":"integration","linkedModuleIds":["bone-tissue-cells-osteon"],"origin":"ai"}],"neuroglia-cns-pns":[{"id":"neuroglia-cns-pns~ai-0","moduleId":"neuroglia-cns-pns","stem":"Which glial cell type is responsible for forming the blood-brain barrier?","options":[{"id":"a","text":"Oligodendrocyte"},{"id":"b","text":"Astrocyte"},{"id":"c","text":"Microglia"},{"id":"d","text":"Schwann cell"}],"answerId":"b","explanation":"Astrocytes have end-feet that contribute to the formation of the blood-brain barrier.","kind":"recall","origin":"ai"},{"id":"neuroglia-cns-pns~ai-1","moduleId":"neuroglia-cns-pns","stem":"What is the primary function of oligodendrocytes in the CNS?","options":[{"id":"a","text":"Support neuronal cell bodies"},{"id":"b","text":"Myelinate multiple axons"},{"id":"c","text":"Phagocytose debris"},{"id":"d","text":"Produce cerebrospinal fluid"}],"answerId":"b","explanation":"Oligodendrocytes myelinate multiple axons in the CNS, providing insulation.","kind":"mechanism","origin":"ai"},{"id":"neuroglia-cns-pns~ai-2","moduleId":"neuroglia-cns-pns","stem":"A patient presents with demyelination of multiple CNS axons. Which cell type is primarily affected?","options":[{"id":"a","text":"Astrocyte"},{"id":"b","text":"Oligodendrocyte"},{"id":"c","text":"Microglia"},{"id":"d","text":"Schwann cell"}],"answerId":"b","explanation":"Oligodendrocytes are responsible for myelinating CNS axons, and their damage leads to demyelinating diseases like MS.","kind":"clinical","origin":"ai"},{"id":"neuroglia-cns-pns~ai-3","moduleId":"neuroglia-cns-pns","stem":"Which of the following statements regarding Schwann cells is true?","options":[{"id":"a","text":"They myelinate multiple axons"},{"id":"b","text":"They are derived from neuroectoderm"},{"id":"c","text":"They can guide regeneration of PNS axons"},{"id":"d","text":"They are the main immune cells in the PNS"}],"answerId":"c","explanation":"Schwann cells myelinate one internode of one axon and play a role in guiding regeneration.","kind":"trap","origin":"ai"},{"id":"neuroglia-cns-pns~ai-4","moduleId":"neuroglia-cns-pns","stem":"Which glial cell type is the primary phagocyte in the CNS?","options":[{"id":"a","text":"Astrocyte"},{"id":"b","text":"Oligodendrocyte"},{"id":"c","text":"Microglia"},{"id":"d","text":"Ependymal cell"}],"answerId":"c","explanation":"Microglia are the resident immune cells in the CNS responsible for phagocytosis.","kind":"recall","origin":"ai"},{"id":"neuroglia-cns-pns~ai-5","moduleId":"neuroglia-cns-pns","stem":"How do the myelination processes differ between the CNS and PNS?","options":[{"id":"a","text":"CNS uses Schwann cells, PNS uses oligodendrocytes"},{"id":"b","text":"CNS myelinates one axon, PNS myelinates many"},{"id":"c","text":"CNS uses oligodendrocytes for multiple axons, PNS uses Schwann cells for one"},{"id":"d","text":"Both use the same type of cell for myelination"}],"answerId":"c","explanation":"Oligodendrocytes myelinate multiple axons in the CNS, while Schwann cells myelinate one internode of one axon in the PNS.","kind":"trap","origin":"ai"},{"id":"neuroglia-cns-pns~ai-6","moduleId":"neuroglia-cns-pns","stem":"Which ethical principle from the Belmont Report is most relevant when conducting research involving human subjects in neuroglial studies?","options":[{"id":"a","text":"Justice"},{"id":"b","text":"Beneficence"},{"id":"c","text":"Respect for persons"},{"id":"d","text":"Integrity"}],"answerId":"c","explanation":"Respect for persons emphasizes the need for informed consent and autonomy in research involving human subjects.","kind":"integration","linkedModuleIds":["research-ethics-history-belmont"],"origin":"ai"},{"id":"neuroglia-cns-pns~ai-7","moduleId":"neuroglia-cns-pns","stem":"In studying the organization of nerve fibers, which glial cell's role is crucial for the regeneration of peripheral nerves?","options":[{"id":"a","text":"Astrocyte"},{"id":"b","text":"Oligodendrocyte"},{"id":"c","text":"Schwann cell"},{"id":"d","text":"Microglia"}],"answerId":"c","explanation":"Schwann cells play a critical role in the regeneration of peripheral nerves by guiding axonal regrowth.","kind":"integration","linkedModuleIds":["nerve-fiber-myelin-synapse"],"origin":"ai"}],"bone-tissue-cells-osteon":[{"id":"bone-tissue-cells-osteon~ai-0","moduleId":"bone-tissue-cells-osteon","stem":"What is the primary function of osteoblasts in bone tissue?","options":[{"id":"a","text":"Resorb bone"},{"id":"b","text":"Maintain bone matrix"},{"id":"c","text":"Build osteoid and mineralize it"},{"id":"d","text":"Sense mechanical load"}],"answerId":"c","explanation":"Osteoblasts are responsible for the synthesis and mineralization of bone matrix, primarily by producing osteoid.","kind":"recall","origin":"ai"},{"id":"bone-tissue-cells-osteon~ai-1","moduleId":"bone-tissue-cells-osteon","stem":"Which cell type is responsible for bone resorption?","options":[{"id":"a","text":"Osteocyte"},{"id":"b","text":"Osteoblast"},{"id":"c","text":"Osteoclast"},{"id":"d","text":"Osteoprogenitor"}],"answerId":"c","explanation":"Osteoclasts are large multinucleated cells that resorb bone by breaking down the mineralized matrix.","kind":"recall","origin":"ai"},{"id":"bone-tissue-cells-osteon~ai-2","moduleId":"bone-tissue-cells-osteon","stem":"What histological feature characterizes an osteon?","options":[{"id":"a","text":"Lattice structure with marrow"},{"id":"b","text":"Concentric lamellae around a central canal"},{"id":"c","text":"Plump basophilic cells"},{"id":"d","text":"Large multinucleated cells"}],"answerId":"b","explanation":"An osteon, or Haversian system, is defined by its concentric lamellae surrounding a central vascular canal.","kind":"recall","origin":"ai"},{"id":"bone-tissue-cells-osteon~ai-3","moduleId":"bone-tissue-cells-osteon","stem":"Which of the following best describes the origin of osteoclasts?","options":[{"id":"a","text":"Mesenchymal osteoprogenitors"},{"id":"b","text":"Fibroblast lineage"},{"id":"c","text":"Monocyte/macrophage lineage"},{"id":"d","text":"Osteoblast lineage"}],"answerId":"c","explanation":"Osteoclasts originate from the monocyte/macrophage lineage, unlike osteoblasts which come from mesenchymal stem cells.","kind":"trap","origin":"ai"},{"id":"bone-tissue-cells-osteon~ai-4","moduleId":"bone-tissue-cells-osteon","stem":"What is the primary role of osteocytes in bone tissue?","options":[{"id":"a","text":"Resorb bone"},{"id":"b","text":"Synthesize osteoid"},{"id":"c","text":"Maintain bone matrix and sense mechanical load"},{"id":"d","text":"Differentiate into osteoblasts"}],"answerId":"c","explanation":"Osteocytes maintain the bone matrix and are involved in mechanosensing to respond to mechanical loads.","kind":"recall","origin":"ai"},{"id":"bone-tissue-cells-osteon~ai-5","moduleId":"bone-tissue-cells-osteon","stem":"Which type of bone is characterized by a disorganized structure and is typically found in fetal development?","options":[{"id":"a","text":"Compact bone"},{"id":"b","text":"Woven bone"},{"id":"c","text":"Lamellar bone"},{"id":"d","text":"Spongy bone"}],"answerId":"b","explanation":"Woven bone is a type of bone that is rapidly formed and has a disorganized structure, commonly seen in fetal development and fracture repair.","kind":"recall","origin":"ai"},{"id":"bone-tissue-cells-osteon~ai-6","moduleId":"bone-tissue-cells-osteon","stem":"How does the process of endochondral ossification relate to osteoclast function?","options":[{"id":"a","text":"Osteoclasts initiate endochondral ossification"},{"id":"b","text":"Osteoclasts resorb cartilage to allow bone formation"},{"id":"c","text":"Osteoclasts are not involved in endochondral ossification"},{"id":"d","text":"Osteoclasts form new bone during endochondral ossification"}],"answerId":"b","explanation":"During endochondral ossification, osteoclasts resorb the cartilage model to facilitate the formation of bone.","kind":"integration","linkedModuleIds":["ossification"],"origin":"ai"},{"id":"bone-tissue-cells-osteon~ai-7","moduleId":"bone-tissue-cells-osteon","stem":"What distinguishes spongy bone from compact bone in terms of structure?","options":[{"id":"a","text":"Presence of osteons"},{"id":"b","text":"Lattice structure with marrow"},{"id":"c","text":"Higher mineral content"},{"id":"d","text":"More vascularized"}],"answerId":"b","explanation":"Spongy bone is characterized by a lattice-like structure with red marrow in between, unlike the dense structure of compact bone.","kind":"integration","linkedModuleIds":["cartilage-types"],"origin":"ai"}],"cardiac-smooth-muscle":[{"id":"cardiac-smooth-muscle~ai-0","moduleId":"cardiac-smooth-muscle","stem":"What is the primary mechanism of contraction in smooth muscle?","options":[{"id":"a","text":"Calcium binding to troponin"},{"id":"b","text":"Calcium binding to calmodulin"},{"id":"c","text":"Calcium release from the sarcoplasmic reticulum"},{"id":"d","text":"Calcium influx through T-tubules"}],"answerId":"b","explanation":"Smooth muscle contraction is mediated by calcium binding to calmodulin, which activates myosin light-chain kinase (MLCK).","kind":"mechanism","origin":"ai"},{"id":"cardiac-smooth-muscle~ai-1","moduleId":"cardiac-smooth-muscle","stem":"Which histological feature is characteristic of cardiac muscle?","options":[{"id":"a","text":"Multiple peripheral nuclei"},{"id":"b","text":"Central single nucleus"},{"id":"c","text":"Branched striated cells"},{"id":"d","text":"Spindle-shaped cells"}],"answerId":"c","explanation":"Cardiac muscle is characterized by branched striated cells that contain 1-2 central nuclei.","kind":"recall","origin":"ai"},{"id":"cardiac-smooth-muscle~ai-2","moduleId":"cardiac-smooth-muscle","stem":"What is the role of intercalated discs in cardiac muscle?","options":[{"id":"a","text":"Electrical coupling only"},{"id":"b","text":"Mechanical coupling only"},{"id":"c","text":"Both mechanical and electrical coupling"},{"id":"d","text":"No role in contraction"}],"answerId":"c","explanation":"Intercalated discs provide both mechanical coupling (via desmosomes) and electrical coupling (via gap junctions) in cardiac muscle.","kind":"mechanism","origin":"ai"},{"id":"cardiac-smooth-muscle~ai-3","moduleId":"cardiac-smooth-muscle","stem":"Which of the following statements about smooth muscle is FALSE?","options":[{"id":"a","text":"It has a single central nucleus."},{"id":"b","text":"It contracts via the troponin complex."},{"id":"c","text":"It is non-striated."},{"id":"d","text":"It is found in blood vessels."}],"answerId":"b","explanation":"Smooth muscle does not use troponin for contraction; instead, it uses calmodulin to activate myosin light-chain kinase.","kind":"trap","origin":"ai"},{"id":"cardiac-smooth-muscle~ai-4","moduleId":"cardiac-smooth-muscle","stem":"During excitation-contraction coupling in cardiac muscle, what triggers the release of calcium from the sarcoplasmic reticulum?","options":[{"id":"a","text":"Calcium influx through T-tubules"},{"id":"b","text":"Calcium binding to troponin"},{"id":"c","text":"Calcium release from the extracellular space"},{"id":"d","text":"Calcium binding to calmodulin"}],"answerId":"a","explanation":"In cardiac muscle, calcium influx through T-tubules triggers the release of calcium from the sarcoplasmic reticulum via a process known as calcium-induced calcium release.","kind":"mechanism","origin":"ai"},{"id":"cardiac-smooth-muscle~ai-5","moduleId":"cardiac-smooth-muscle","stem":"Which of the following structures is NOT found in smooth muscle?","options":[{"id":"a","text":"Caveolae"},{"id":"b","text":"Dense bodies"},{"id":"c","text":"Intercalated discs"},{"id":"d","text":"Gap junctions"}],"answerId":"c","explanation":"Smooth muscle contains caveolae and dense bodies, but it does not have intercalated discs, which are specific to cardiac muscle.","kind":"trap","origin":"ai"},{"id":"cardiac-smooth-muscle~ai-6","moduleId":"cardiac-smooth-muscle","stem":"How does the contraction mechanism of smooth muscle differ from that of skeletal muscle?","options":[{"id":"a","text":"Smooth muscle uses troponin, skeletal does not."},{"id":"b","text":"Skeletal muscle contraction is faster than smooth muscle."},{"id":"c","text":"Smooth muscle uses calmodulin, skeletal muscle uses troponin."},{"id":"d","text":"Both use the same mechanism."}],"answerId":"c","explanation":"Smooth muscle contraction relies on calmodulin and myosin light-chain kinase, while skeletal muscle contraction involves troponin.","kind":"integration","linkedModuleIds":["skeletal-muscle-sarcomere"],"origin":"ai"},{"id":"cardiac-smooth-muscle~ai-7","moduleId":"cardiac-smooth-muscle","stem":"Which feature distinguishes cardiac muscle from smooth muscle?","options":[{"id":"a","text":"Presence of gap junctions"},{"id":"b","text":"Central nucleus"},{"id":"c","text":"Striations"},{"id":"d","text":"Calmodulin-dependent contraction"}],"answerId":"c","explanation":"Cardiac muscle is striated, while smooth muscle is non-striated, which is a key distinguishing feature.","kind":"integration","linkedModuleIds":["heart-wall-cardiac-histology"],"origin":"ai"}],"cartilage-types":[{"id":"cartilage-types~ai-0","moduleId":"cartilage-types","stem":"What type of collagen is primarily found in hyaline cartilage?","options":[{"id":"a","text":"Type I collagen"},{"id":"b","text":"Type II collagen"},{"id":"c","text":"Type III collagen"},{"id":"d","text":"Type IV collagen"}],"answerId":"b","explanation":"Hyaline cartilage is primarily composed of Type II collagen, which provides its glassy appearance and structural integrity.","kind":"recall","origin":"ai"},{"id":"cartilage-types~ai-1","moduleId":"cartilage-types","stem":"Which cartilage type is characterized by a dark network of elastic fibers?","options":[{"id":"a","text":"Hyaline cartilage"},{"id":"b","text":"Elastic cartilage"},{"id":"c","text":"Fibrocartilage"},{"id":"d","text":"Articular cartilage"}],"answerId":"b","explanation":"Elastic cartilage contains elastic fibers in addition to Type II collagen, allowing it to maintain shape after deformation.","kind":"mechanism","origin":"ai"},{"id":"cartilage-types~ai-2","moduleId":"cartilage-types","stem":"What is the primary distinguishing feature of fibrocartilage?","options":[{"id":"a","text":"Presence of perichondrium"},{"id":"b","text":"Rows of chondrocytes between collagen bundles"},{"id":"c","text":"High water content"},{"id":"d","text":"Glassy matrix appearance"}],"answerId":"b","explanation":"Fibrocartilage is characterized by rows of chondrocytes situated between dense collagen bundles and lacks a perichondrium.","kind":"recall","origin":"ai"},{"id":"cartilage-types~ai-3","moduleId":"cartilage-types","stem":"Which growth mode involves chondrocytes dividing within lacunae?","options":[{"id":"a","text":"Appositional growth"},{"id":"b","text":"Interstitial growth"},{"id":"c","text":"Endochondral growth"},{"id":"d","text":"Intramembranous growth"}],"answerId":"b","explanation":"Interstitial growth occurs when chondrocytes divide within their lacunae, leading to an increase in cartilage size from within.","kind":"mechanism","origin":"ai"},{"id":"cartilage-types~ai-4","moduleId":"cartilage-types","stem":"Which statement about cartilage is FALSE?","options":[{"id":"a","text":"All cartilage is avascular"},{"id":"b","text":"Hyaline cartilage is the most common type"},{"id":"c","text":"Fibrocartilage contains Type II collagen"},{"id":"d","text":"Elastic cartilage retains shape after bending"}],"answerId":"c","explanation":"Fibrocartilage is primarily composed of Type I collagen, not Type II, making this statement false.","kind":"trap","origin":"ai"},{"id":"cartilage-types~ai-5","moduleId":"cartilage-types","stem":"How does cartilage calcification relate to endochondral ossification?","options":[{"id":"a","text":"Cartilage calcification occurs before intramembranous ossification"},{"id":"b","text":"Calcified cartilage serves as a template for bone formation"},{"id":"c","text":"Cartilage does not calcify during ossification"},{"id":"d","text":"Calcification is exclusive to fibrocartilage"}],"answerId":"b","explanation":"During endochondral ossification, cartilage calcifies and serves as a template for the formation of bone.","kind":"integration","linkedModuleIds":["ossification"],"origin":"ai"},{"id":"cartilage-types~ai-6","moduleId":"cartilage-types","stem":"What is the role of proteoglycans in cartilage?","options":[{"id":"a","text":"Provide tensile strength"},{"id":"b","text":"Facilitate nutrient diffusion"},{"id":"c","text":"Maintain hydration and resilience"},{"id":"d","text":"Support chondrocyte division"}],"answerId":"c","explanation":"Proteoglycans help maintain hydration and resilience in cartilage, contributing to its mechanical properties.","kind":"mechanism","origin":"ai"},{"id":"cartilage-types~ai-7","moduleId":"cartilage-types","stem":"Which type of cartilage is found in the intervertebral discs?","options":[{"id":"a","text":"Hyaline cartilage"},{"id":"b","text":"Elastic cartilage"},{"id":"c","text":"Fibrocartilage"},{"id":"d","text":"Articular cartilage"}],"answerId":"c","explanation":"Fibrocartilage is found in intervertebral discs, providing support and resistance to compressive forces.","kind":"recall","origin":"ai"},{"id":"cartilage-types~ai-8","moduleId":"cartilage-types","stem":"What is the primary function of the perichondrium?","options":[{"id":"a","text":"Provide nutrients to cartilage"},{"id":"b","text":"Facilitate chondrocyte division"},{"id":"c","text":"Act as a shock absorber"},{"id":"d","text":"Support bone growth"}],"answerId":"a","explanation":"The perichondrium supplies nutrients to cartilage through diffusion, as cartilage itself is avascular.","kind":"mechanism","origin":"ai"}],"ossification":[{"id":"ossification~ai-0","moduleId":"ossification","stem":"Which type of ossification is responsible for forming the flat bones of the skull?","options":[{"id":"a","text":"Endochondral ossification"},{"id":"b","text":"Intramembranous ossification"},{"id":"c","text":"Appositional growth"},{"id":"d","text":"Cartilage replacement"}],"answerId":"b","explanation":"Flat bones of the skull form through intramembranous ossification, which occurs directly from mesenchyme without a cartilage model.","kind":"recall","origin":"ai"},{"id":"ossification~ai-1","moduleId":"ossification","stem":"What is the primary mechanism by which long bones grow in length?","options":[{"id":"a","text":"Intramembranous ossification"},{"id":"b","text":"Appositional growth"},{"id":"c","text":"Endochondral ossification"},{"id":"d","text":"Bone remodeling"}],"answerId":"c","explanation":"Long bones grow in length through endochondral ossification, which involves the replacement of a hyaline cartilage model.","kind":"mechanism","origin":"ai"},{"id":"ossification~ai-2","moduleId":"ossification","stem":"Which zone of the growth plate is characterized by hypertrophic chondrocytes?","options":[{"id":"a","text":"Reserve zone"},{"id":"b","text":"Proliferation zone"},{"id":"c","text":"Hypertrophy zone"},{"id":"d","text":"Calcification zone"}],"answerId":"c","explanation":"The hypertrophy zone of the growth plate contains enlarged chondrocytes that contribute to bone lengthening.","kind":"recall","origin":"ai"},{"id":"ossification~ai-3","moduleId":"ossification","stem":"A child presents with short limbs but a normal-sized trunk and head. What is the most likely diagnosis?","options":[{"id":"a","text":"Osteogenesis imperfecta"},{"id":"b","text":"Achondroplasia"},{"id":"c","text":"Marfan syndrome"},{"id":"d","text":"Rickets"}],"answerId":"b","explanation":"Achondroplasia is characterized by short-limbed dwarfism due to a defect in endochondral ossification.","kind":"clinical","origin":"ai"},{"id":"ossification~ai-4","moduleId":"ossification","stem":"Which of the following statements about ossification is true?","options":[{"id":"a","text":"All bones form by replacing a cartilage model"},{"id":"b","text":"Intramembranous ossification occurs in long bones"},{"id":"c","text":"Endochondral ossification is responsible for flat skull bones"},{"id":"d","text":"Intramembranous ossification occurs directly from mesenchyme"}],"answerId":"d","explanation":"Intramembranous ossification occurs directly from mesenchyme and is responsible for forming flat bones like those of the skull.","kind":"trap","origin":"ai"},{"id":"ossification~ai-5","moduleId":"ossification","stem":"How does the growth plate contribute to limb development?","options":[{"id":"a","text":"By forming the axial skeleton"},{"id":"b","text":"By facilitating endochondral ossification"},{"id":"c","text":"By promoting intramembranous ossification"},{"id":"d","text":"By resorbing bone at the periosteum"}],"answerId":"b","explanation":"The growth plate facilitates endochondral ossification, which is essential for the lengthening of long bones during limb development.","kind":"integration","linkedModuleIds":["msk-embryo-limb-joints"],"origin":"ai"},{"id":"ossification~ai-6","moduleId":"ossification","stem":"What is the role of osteoblasts during appositional growth?","options":[{"id":"a","text":"Resorb bone at the endosteum"},{"id":"b","text":"Lay down new bone on the periosteum"},{"id":"c","text":"Form cartilage in the growth plate"},{"id":"d","text":"Replace cartilage with bone in the diaphysis"}],"answerId":"b","explanation":"Osteoblasts lay down new bone on the periosteum during appositional growth, contributing to bone width.","kind":"recall","origin":"ai"},{"id":"ossification~ai-7","moduleId":"ossification","stem":"Which type of cartilage is primarily involved in endochondral ossification?","options":[{"id":"a","text":"Elastic cartilage"},{"id":"b","text":"Fibrocartilage"},{"id":"c","text":"Hyaline cartilage"},{"id":"d","text":"Dense irregular connective tissue"}],"answerId":"c","explanation":"Hyaline cartilage serves as the template for bone formation in endochondral ossification.","kind":"mechanism","origin":"ai"},{"id":"ossification~ai-8","moduleId":"ossification","stem":"What is the consequence of FGFR3 gain-of-function mutations in bone development?","options":[{"id":"a","text":"Increased bone density"},{"id":"b","text":"Short-limbed dwarfism"},{"id":"c","text":"Delayed fracture healing"},{"id":"d","text":"Enhanced intramembranous ossification"}],"answerId":"b","explanation":"FGFR3 gain-of-function mutations impair the proliferation of chondrocytes in the growth plate, leading to short-limbed dwarfism.","kind":"clinical","origin":"ai"}],"membranes-and-epidermis":[{"id":"membranes-and-epidermis~ai-0","moduleId":"membranes-and-epidermis","stem":"Which layer of the epidermis contains the mitotically active stem cells?","options":[{"id":"a","text":"Stratum corneum"},{"id":"b","text":"Stratum granulosum"},{"id":"c","text":"Stratum spinosum"},{"id":"d","text":"Stratum basale"}],"answerId":"d","explanation":"The stratum basale is the deepest layer of the epidermis where stem cells divide to replenish the skin.","kind":"recall","origin":"ai"},{"id":"membranes-and-epidermis~ai-1","moduleId":"membranes-and-epidermis","stem":"What is the primary function of melanocytes in the epidermis?","options":[{"id":"a","text":"Produce keratin"},{"id":"b","text":"Provide mechanical strength"},{"id":"c","text":"Synthesize melanin"},{"id":"d","text":"Facilitate cell division"}],"answerId":"c","explanation":"Melanocytes are responsible for synthesizing melanin, which protects against UV radiation.","kind":"recall","origin":"ai"},{"id":"membranes-and-epidermis~ai-2","moduleId":"membranes-and-epidermis","stem":"Which epidermal layer is characterized by the presence of keratohyalin granules?","options":[{"id":"a","text":"Stratum corneum"},{"id":"b","text":"Stratum granulosum"},{"id":"c","text":"Stratum spinosum"},{"id":"d","text":"Stratum basale"}],"answerId":"b","explanation":"The stratum granulosum contains keratohyalin granules that contribute to keratinization.","kind":"recall","origin":"ai"},{"id":"membranes-and-epidermis~ai-3","moduleId":"membranes-and-epidermis","stem":"What type of cell is primarily responsible for antigen presentation in the epidermis?","options":[{"id":"a","text":"Melanocyte"},{"id":"b","text":"Langerhans cell"},{"id":"c","text":"Merkel cell"},{"id":"d","text":"Keratinocyte"}],"answerId":"b","explanation":"Langerhans cells are dendritic cells in the epidermis that present antigens to the immune system.","kind":"recall","origin":"ai"},{"id":"membranes-and-epidermis~ai-4","moduleId":"membranes-and-epidermis","stem":"In which type of skin is the stratum lucidum found?","options":[{"id":"a","text":"Thin skin"},{"id":"b","text":"Thick skin"},{"id":"c","text":"Mucous membranes"},{"id":"d","text":"Serous membranes"}],"answerId":"b","explanation":"The stratum lucidum is present only in thick skin, such as the palms and soles.","kind":"recall","origin":"ai"},{"id":"membranes-and-epidermis~ai-5","moduleId":"membranes-and-epidermis","stem":"Which junctional complex is primarily responsible for mechanical strength in the epidermis?","options":[{"id":"a","text":"Tight junctions"},{"id":"b","text":"Desmosomes"},{"id":"c","text":"Gap junctions"},{"id":"d","text":"Adherens junctions"}],"answerId":"b","explanation":"Desmosomes provide mechanical strength by anchoring adjacent keratinocytes together.","kind":"mechanism","origin":"ai"},{"id":"membranes-and-epidermis~ai-6","moduleId":"membranes-and-epidermis","stem":"A patient presents with a skin biopsy showing anucleate keratin scales. Which layer of the epidermis does this finding represent?","options":[{"id":"a","text":"Stratum basale"},{"id":"b","text":"Stratum spinosum"},{"id":"c","text":"Stratum granulosum"},{"id":"d","text":"Stratum corneum"}],"answerId":"d","explanation":"Anucleate keratin scales are characteristic of the stratum corneum, the outermost layer of the epidermis.","kind":"clinical","origin":"ai"},{"id":"membranes-and-epidermis~ai-7","moduleId":"membranes-and-epidermis","stem":"How does the structure of the epidermis relate to its function as a barrier?","options":[{"id":"a","text":"Thick keratinized layers prevent water loss"},{"id":"b","text":"Melanocytes block UV radiation"},{"id":"c","text":"Desmosomes allow for flexibility"},{"id":"d","text":"Langerhans cells enhance sensation"}],"answerId":"a","explanation":"The thick keratinized layers of the epidermis form a barrier that prevents water loss and protects against environmental damage.","kind":"integration","linkedModuleIds":["skin-anatomy-histology"],"origin":"ai"},{"id":"membranes-and-epidermis~ai-8","moduleId":"membranes-and-epidermis","stem":"What is the role of keratinocytes in the epidermis?","options":[{"id":"a","text":"Produce melanin"},{"id":"b","text":"Facilitate immune response"},{"id":"c","text":"Form the skin barrier"},{"id":"d","text":"Detect touch sensation"}],"answerId":"c","explanation":"Keratinocytes are the primary cells in the epidermis that produce keratin, forming the skin barrier.","kind":"integration","linkedModuleIds":["epidermis-keratinocyte-biology"],"origin":"ai"}],"dermis-sensory-skin-appendages":[{"id":"dermis-sensory-skin-appendages~ai-0","moduleId":"dermis-sensory-skin-appendages","stem":"Which type of mechanoreceptor is primarily responsible for detecting light touch in the skin?","options":[{"id":"a","text":"Meissner corpuscles"},{"id":"b","text":"Pacinian corpuscles"},{"id":"c","text":"Ruffini endings"},{"id":"d","text":"Merkel discs"}],"answerId":"a","explanation":"Meissner corpuscles are located in the dermal papillae and are specialized for light touch sensation.","kind":"recall","origin":"ai"},{"id":"dermis-sensory-skin-appendages~ai-1","moduleId":"dermis-sensory-skin-appendages","stem":"What is the primary function of sebaceous glands?","options":[{"id":"a","text":"Produce sweat for thermoregulation"},{"id":"b","text":"Secrete sebum to lubricate skin and hair"},{"id":"c","text":"Detect deep pressure"},{"id":"d","text":"Provide structural support to hair follicles"}],"answerId":"b","explanation":"Sebaceous glands secrete sebum, which keeps the skin and hair supple.","kind":"recall","origin":"ai"},{"id":"dermis-sensory-skin-appendages~ai-2","moduleId":"dermis-sensory-skin-appendages","stem":"Which structure is responsible for the sensation of deep pressure and vibration?","options":[{"id":"a","text":"Meissner corpuscles"},{"id":"b","text":"Pacinian corpuscles"},{"id":"c","text":"Ruffini endings"},{"id":"d","text":"Free nerve endings"}],"answerId":"b","explanation":"Pacinian corpuscles, located in the deep dermis, are specialized for detecting deep pressure and vibration.","kind":"recall","origin":"ai"},{"id":"dermis-sensory-skin-appendages~ai-3","moduleId":"dermis-sensory-skin-appendages","stem":"A patient presents with an inflamed sebaceous gland. What skin condition is most likely associated with this finding?","options":[{"id":"a","text":"Psoriasis"},{"id":"b","text":"Eczema"},{"id":"c","text":"Acne"},{"id":"d","text":"Dermatitis"}],"answerId":"c","explanation":"Inflamed sebaceous glands are commonly associated with acne due to blockage and inflammation.","kind":"clinical","origin":"ai"},{"id":"dermis-sensory-skin-appendages~ai-4","moduleId":"dermis-sensory-skin-appendages","stem":"Which of the following structures is involved in the sensation of sustained touch?","options":[{"id":"a","text":"Meissner corpuscles"},{"id":"b","text":"Pacinian corpuscles"},{"id":"c","text":"Merkel discs"},{"id":"d","text":"Ruffini endings"}],"answerId":"c","explanation":"Merkel discs are specialized for detecting sustained touch and pressure.","kind":"recall","origin":"ai"},{"id":"dermis-sensory-skin-appendages~ai-5","moduleId":"dermis-sensory-skin-appendages","stem":"How does the structure of the papillary dermis contribute to its function?","options":[{"id":"a","text":"It provides strength through dense collagen"},{"id":"b","text":"It contains mechanoreceptors for deep pressure"},{"id":"c","text":"It interlocks with epidermal ridges to enhance nutrient supply"},{"id":"d","text":"It stores fat for energy"}],"answerId":"c","explanation":"The loose connective tissue of the papillary dermis interlocks with epidermal ridges, enhancing nutrient supply and forming fingerprints.","kind":"mechanism","origin":"ai"},{"id":"dermis-sensory-skin-appendages~ai-6","moduleId":"dermis-sensory-skin-appendages","stem":"In which layer of the skin would you find Pacinian corpuscles?","options":[{"id":"a","text":"Epidermis"},{"id":"b","text":"Papillary dermis"},{"id":"c","text":"Reticular dermis"},{"id":"d","text":"Hypodermis"}],"answerId":"c","explanation":"Pacinian corpuscles are located in the reticular dermis and hypodermis, where they detect deep pressure and vibration.","kind":"recall","origin":"ai"},{"id":"dermis-sensory-skin-appendages~ai-7","moduleId":"dermis-sensory-skin-appendages","stem":"How do eccrine sweat glands differ from apocrine sweat glands?","options":[{"id":"a","text":"Eccrine glands open into hair follicles; apocrine glands open directly onto skin"},{"id":"b","text":"Eccrine glands are activated at puberty; apocrine glands are not"},{"id":"c","text":"Eccrine glands are involved in thermoregulation; apocrine glands are not"},{"id":"d","text":"Eccrine glands secrete oily substances; apocrine glands secrete watery sweat"}],"answerId":"c","explanation":"Eccrine sweat glands are primarily involved in thermoregulation and open directly onto the skin surface.","kind":"trap","origin":"ai"},{"id":"dermis-sensory-skin-appendages~ai-8","moduleId":"dermis-sensory-skin-appendages","stem":"How are the functions of sensory receptors in the dermis related to the epidermis?","options":[{"id":"a","text":"Epidermis contains only pain receptors"},{"id":"b","text":"Epidermis provides structural support for dermal receptors"},{"id":"c","text":"Epidermis is involved in thermoregulation"},{"id":"d","text":"Epidermis and dermis work together to detect various stimuli"}],"answerId":"d","explanation":"The epidermis and dermis collaborate to provide a comprehensive sensory experience, detecting various stimuli through their respective receptors.","kind":"integration","linkedModuleIds":["membranes-and-epidermis"],"origin":"ai"}],"intermediate-filaments-clinical":[{"id":"intermediate-filaments-clinical~ai-0","moduleId":"intermediate-filaments-clinical","stem":"Which intermediate filament type is primarily associated with epithelial tumors?","options":[{"id":"a","text":"Vimentin"},{"id":"b","text":"Desmin"},{"id":"c","text":"Neurofilament"},{"id":"d","text":"Keratin"}],"answerId":"d","explanation":"Keratin is the intermediate filament type that indicates epithelial origin, thus associated with carcinomas.","kind":"recall","origin":"ai"},{"id":"intermediate-filaments-clinical~ai-1","moduleId":"intermediate-filaments-clinical","stem":"What is the primary composition of Mallory bodies seen in alcoholic liver disease?","options":[{"id":"a","text":"Collagen"},{"id":"b","text":"Amyloid"},{"id":"c","text":"Aggregated keratin"},{"id":"d","text":"Desmin"}],"answerId":"c","explanation":"Mallory bodies are composed of aggregated keratin intermediate filaments within hepatocytes.","kind":"trap","origin":"ai"},{"id":"intermediate-filaments-clinical~ai-2","moduleId":"intermediate-filaments-clinical","stem":"In which condition would you expect to find GFAP-positive tumors?","options":[{"id":"a","text":"Carcinoma"},{"id":"b","text":"Sarcoma"},{"id":"c","text":"Glioma"},{"id":"d","text":"Neuroblastoma"}],"answerId":"c","explanation":"GFAP is a marker for astrocytic tumors, specifically gliomas.","kind":"clinical","origin":"ai"},{"id":"intermediate-filaments-clinical~ai-3","moduleId":"intermediate-filaments-clinical","stem":"Which finding is characteristic of neurofibrillary tangles in Alzheimer's disease?","options":[{"id":"a","text":"Aggregated desmin"},{"id":"b","text":"Hyperphosphorylated tau"},{"id":"c","text":"Vimentin clumps"},{"id":"d","text":"Keratin aggregates"}],"answerId":"b","explanation":"Neurofibrillary tangles in Alzheimer's disease are primarily composed of hyperphosphorylated tau protein.","kind":"recall","origin":"ai"},{"id":"intermediate-filaments-clinical~ai-4","moduleId":"intermediate-filaments-clinical","stem":"What is the mechanism behind situs inversus in Kartagener syndrome?","options":[{"id":"a","text":"Defective keratin"},{"id":"b","text":"Ciliary dynein defect"},{"id":"c","text":"Neurofilament dysfunction"},{"id":"d","text":"Desmin mutation"}],"answerId":"b","explanation":"Kartagener syndrome is caused by a defect in ciliary dynein, leading to impaired ciliary movement and situs inversus.","kind":"mechanism","origin":"ai"},{"id":"intermediate-filaments-clinical~ai-5","moduleId":"intermediate-filaments-clinical","stem":"A patient presents with a tumor that is keratin-positive and vimentin-negative. What is the likely diagnosis?","options":[{"id":"a","text":"Sarcoma"},{"id":"b","text":"Carcinoma"},{"id":"c","text":"Lymphoma"},{"id":"d","text":"Glioma"}],"answerId":"b","explanation":"The keratin-positive, vimentin-negative profile indicates an epithelial origin, consistent with carcinoma.","kind":"integration","linkedModuleIds":["cell-junctions"],"origin":"ai"},{"id":"intermediate-filaments-clinical~ai-6","moduleId":"intermediate-filaments-clinical","stem":"Which cytoskeletal abnormality is linked to primary ciliary dyskinesia?","options":[{"id":"a","text":"Defective neurofilaments"},{"id":"b","text":"Abnormal desmin"},{"id":"c","text":"Ciliary dynein defect"},{"id":"d","text":"Keratin aggregation"}],"answerId":"c","explanation":"Primary ciliary dyskinesia is caused by defects in ciliary dynein arms, affecting ciliary function.","kind":"integration","linkedModuleIds":["intermediate-filaments"],"origin":"ai"}],"homeostasis-feedback-control":[{"id":"homeostasis-feedback-control~ai-0","moduleId":"homeostasis-feedback-control","stem":"What is the primary mechanism by which insulin lowers blood glucose levels?","options":[{"id":"a","text":"Positive feedback"},{"id":"b","text":"Negative feedback"},{"id":"c","text":"Feedforward control"},{"id":"d","text":"Homeostatic imbalance"}],"answerId":"b","explanation":"Insulin lowers blood glucose through negative feedback, opposing the rise in glucose levels.","kind":"mechanism","origin":"ai"},{"id":"homeostasis-feedback-control~ai-1","moduleId":"homeostasis-feedback-control","stem":"Which of the following best describes the role of oxytocin during labor?","options":[{"id":"a","text":"Negative feedback"},{"id":"b","text":"Positive feedback"},{"id":"c","text":"Feedforward control"},{"id":"d","text":"Homeostatic regulation"}],"answerId":"b","explanation":"Oxytocin amplifies uterine contractions through positive feedback until delivery occurs.","kind":"mechanism","origin":"ai"},{"id":"homeostasis-feedback-control~ai-2","moduleId":"homeostasis-feedback-control","stem":"What physiological response occurs when body temperature drops?","options":[{"id":"a","text":"Vasodilation"},{"id":"b","text":"Shivering"},{"id":"c","text":"Increased sweating"},{"id":"d","text":"Decreased heart rate"}],"answerId":"b","explanation":"Shivering is a negative feedback response that helps restore core temperature when it drops.","kind":"recall","origin":"ai"},{"id":"homeostasis-feedback-control~ai-3","moduleId":"homeostasis-feedback-control","stem":"Which statement about positive feedback is correct?","options":[{"id":"a","text":"It maintains homeostasis by opposing change."},{"id":"b","text":"It amplifies a change to drive a process to completion."},{"id":"c","text":"It is the primary mechanism for temperature regulation."},{"id":"d","text":"It is used for gradual adjustments in physiological variables."}],"answerId":"b","explanation":"Positive feedback amplifies changes, unlike negative feedback which opposes changes to maintain homeostasis.","kind":"trap","origin":"ai"},{"id":"homeostasis-feedback-control~ai-4","moduleId":"homeostasis-feedback-control","stem":"During exercise, what anticipatory response occurs in the cardiovascular system?","options":[{"id":"a","text":"Decreased heart rate"},{"id":"b","text":"Increased heart rate"},{"id":"c","text":"Decreased blood pressure"},{"id":"d","text":"Increased blood viscosity"}],"answerId":"b","explanation":"Heart rate rises in anticipation of increased metabolic demand during exercise, demonstrating feedforward control.","kind":"mechanism","origin":"ai"},{"id":"homeostasis-feedback-control~ai-5","moduleId":"homeostasis-feedback-control","stem":"How does the body respond to increased plasma osmolality?","options":[{"id":"a","text":"Secretion of glucagon"},{"id":"b","text":"Secretion of insulin"},{"id":"c","text":"Secretion of ADH"},{"id":"d","text":"Increased urine output"}],"answerId":"c","explanation":"Increased plasma osmolality triggers the secretion of ADH, which helps retain water and dilute the plasma, a negative feedback mechanism.","kind":"integration","linkedModuleIds":["osmolarity-tonicity-cell-volume"],"origin":"ai"},{"id":"homeostasis-feedback-control~ai-6","moduleId":"homeostasis-feedback-control","stem":"What feedback mechanism is primarily involved in the regulation of GnRH and LH during the menstrual cycle?","options":[{"id":"a","text":"Positive feedback"},{"id":"b","text":"Negative feedback"},{"id":"c","text":"Feedforward control"},{"id":"d","text":"Homeostatic imbalance"}],"answerId":"a","explanation":"The regulation of GnRH and LH involves positive feedback, particularly during the midcycle surge leading to ovulation.","kind":"integration","linkedModuleIds":["hrp1-cycle-feedback-gonadotropins"],"origin":"ai"}],"membrane-transport-active-vesicular":[{"id":"membrane-transport-active-vesicular~ai-0","moduleId":"membrane-transport-active-vesicular","stem":"Which of the following is an example of primary active transport?","options":[{"id":"a","text":"Na⁺/K⁺-ATPase"},{"id":"b","text":"SGLT"},{"id":"c","text":"Na⁺/Ca²⁺ exchanger"},{"id":"d","text":"Glucose transporter"}],"answerId":"a","explanation":"The Na⁺/K⁺-ATPase directly uses ATP to transport sodium and potassium ions against their gradients.","kind":"recall","origin":"ai"},{"id":"membrane-transport-active-vesicular~ai-1","moduleId":"membrane-transport-active-vesicular","stem":"What is the primary mechanism by which glucose is reabsorbed in the renal tubules?","options":[{"id":"a","text":"Facilitated diffusion"},{"id":"b","text":"Primary active transport"},{"id":"c","text":"Secondary active symport"},{"id":"d","text":"Endocytosis"}],"answerId":"c","explanation":"Glucose reabsorption in the renal tubules occurs via secondary active symport, coupling glucose transport with Na⁺.","kind":"recall","origin":"ai"},{"id":"membrane-transport-active-vesicular~ai-2","moduleId":"membrane-transport-active-vesicular","stem":"Which of the following statements about secondary active transport is true?","options":[{"id":"a","text":"It directly uses ATP."},{"id":"b","text":"It relies on ion gradients established by primary active transport."},{"id":"c","text":"It can occur without any energy input."},{"id":"d","text":"It only involves symport mechanisms."}],"answerId":"b","explanation":"Secondary active transport relies on ion gradients created by primary active transport, such as the Na⁺ gradient.","kind":"trap","origin":"ai"},{"id":"membrane-transport-active-vesicular~ai-3","moduleId":"membrane-transport-active-vesicular","stem":"What clinical finding would suggest inhibition of the H⁺/K⁺-ATPase?","options":[{"id":"a","text":"Increased gastric acid secretion"},{"id":"b","text":"Decreased gastric acid secretion"},{"id":"c","text":"Increased intracellular Ca²⁺"},{"id":"d","text":"Decreased glucose reabsorption"}],"answerId":"b","explanation":"Inhibition of the H⁺/K⁺-ATPase reduces gastric acid secretion, a common effect of proton pump inhibitors.","kind":"clinical","origin":"ai"},{"id":"membrane-transport-active-vesicular~ai-4","moduleId":"membrane-transport-active-vesicular","stem":"In the context of vesicular transport, which process is responsible for neurotransmitter release?","options":[{"id":"a","text":"Endocytosis"},{"id":"b","text":"Exocytosis"},{"id":"c","text":"Phagocytosis"},{"id":"d","text":"Pinocytosis"}],"answerId":"b","explanation":"Neurotransmitter release at synapses occurs via exocytosis, where vesicles fuse with the membrane to release their contents.","kind":"clinical","origin":"ai"},{"id":"membrane-transport-active-vesicular~ai-5","moduleId":"membrane-transport-active-vesicular","stem":"How does the Na⁺/K⁺-ATPase contribute to the resting membrane potential?","options":[{"id":"a","text":"It generates a positive charge inside the cell."},{"id":"b","text":"It maintains a high intracellular Na⁺ concentration."},{"id":"c","text":"It creates an electrochemical gradient."},{"id":"d","text":"It directly produces ATP."}],"answerId":"c","explanation":"The Na⁺/K⁺-ATPase creates an electrochemical gradient by pumping Na⁺ out and K⁺ in, which is crucial for the resting membrane potential.","kind":"integration","linkedModuleIds":["resting-membrane-potential-nernst"],"origin":"ai"},{"id":"membrane-transport-active-vesicular~ai-6","moduleId":"membrane-transport-active-vesicular","stem":"Which type of transport mechanism is primarily involved in the movement of ions during the development of brain vesicles?","options":[{"id":"a","text":"Passive diffusion"},{"id":"b","text":"Primary active transport"},{"id":"c","text":"Secondary active transport"},{"id":"d","text":"Facilitated diffusion"}],"answerId":"b","explanation":"Primary active transport is crucial for establishing ion gradients necessary for the development and function of brain vesicles.","kind":"integration","linkedModuleIds":["brain-vesicles-neural-crest"],"origin":"ai"}],"ecm-fibers-ground-substance":[{"id":"ecm-fibers-ground-substance~ai-0","moduleId":"ecm-fibers-ground-substance","stem":"What type of collagen is primarily found in bone and tendon?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"a","explanation":"Type I collagen is the most abundant collagen type in bone and tendon, providing tensile strength.","kind":"recall","origin":"ai"},{"id":"ecm-fibers-ground-substance~ai-1","moduleId":"ecm-fibers-ground-substance","stem":"Which component of the extracellular matrix is responsible for resisting compression?","options":[{"id":"a","text":"Collagen"},{"id":"b","text":"Elastin"},{"id":"c","text":"Ground substance"},{"id":"d","text":"Fibroblasts"}],"answerId":"c","explanation":"Ground substance, composed of GAGs and proteoglycans, traps water and resists compressive forces.","kind":"mechanism","origin":"ai"},{"id":"ecm-fibers-ground-substance~ai-2","moduleId":"ecm-fibers-ground-substance","stem":"A patient presents with bleeding gums and poor wound healing. What vitamin deficiency is likely responsible?","options":[{"id":"a","text":"Vitamin A"},{"id":"b","text":"Vitamin B12"},{"id":"c","text":"Vitamin C"},{"id":"d","text":"Vitamin D"}],"answerId":"c","explanation":"Vitamin C is essential for the hydroxylation of proline in collagen synthesis; its deficiency leads to weakened collagen.","kind":"clinical","origin":"ai"},{"id":"ecm-fibers-ground-substance~ai-3","moduleId":"ecm-fibers-ground-substance","stem":"Which type of collagen forms the reticular fibers in lymphoid organs?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"c","explanation":"Type III collagen forms reticular fibers, providing a mesh-like structure in lymphoid organs.","kind":"recall","origin":"ai"},{"id":"ecm-fibers-ground-substance~ai-4","moduleId":"ecm-fibers-ground-substance","stem":"A patient with Marfan syndrome presents with tall stature and arachnodactyly. Which ECM component is defective?","options":[{"id":"a","text":"Collagen"},{"id":"b","text":"Elastin"},{"id":"c","text":"Fibrillin"},{"id":"d","text":"GAGs"}],"answerId":"c","explanation":"Marfan syndrome is caused by a defect in fibrillin, which is crucial for the structure of elastic fibers.","kind":"mechanism","origin":"ai"},{"id":"ecm-fibers-ground-substance~ai-5","moduleId":"ecm-fibers-ground-substance","stem":"Which of the following statements about basement membrane collagen is true?","options":[{"id":"a","text":"It is primarily type I collagen."},{"id":"b","text":"It forms a network structure."},{"id":"c","text":"It is found in tendons."},{"id":"d","text":"It is fibrillar."}],"answerId":"b","explanation":"Basement membranes are made of type IV collagen, which forms a non-fibrillar network.","kind":"trap","origin":"ai"},{"id":"ecm-fibers-ground-substance~ai-6","moduleId":"ecm-fibers-ground-substance","stem":"How does collagen turnover relate to osteoporosis management?","options":[{"id":"a","text":"Collagen type I is synthesized."},{"id":"b","text":"CTX-1 levels indicate bone formation."},{"id":"c","text":"Collagen degradation markers are used."},{"id":"d","text":"Vitamin C supplementation is monitored."}],"answerId":"c","explanation":"CTX-1 is a marker of collagen type I degradation, used to monitor bone resorption in osteoporosis.","kind":"integration","linkedModuleIds":["ecm-adhesion-integrins-clinical"],"origin":"ai"},{"id":"ecm-fibers-ground-substance~ai-7","moduleId":"ecm-fibers-ground-substance","stem":"Which extracellular matrix component is crucial for thyroid follicle structure?","options":[{"id":"a","text":"Type I collagen"},{"id":"b","text":"Type II collagen"},{"id":"c","text":"Type IV collagen"},{"id":"d","text":"Elastin"}],"answerId":"c","explanation":"Type IV collagen forms the basement membrane, which is essential for the structural integrity of thyroid follicles.","kind":"integration","linkedModuleIds":["hen1-thyroid-histology"],"origin":"ai"}],"nerve-fiber-myelin-synapse":[{"id":"nerve-fiber-myelin-synapse~ai-0","moduleId":"nerve-fiber-myelin-synapse","stem":"What is the primary function of myelin in nerve fibers?","options":[{"id":"a","text":"To insulate the axon"},{"id":"b","text":"To provide structural support"},{"id":"c","text":"To facilitate neurotransmitter release"},{"id":"d","text":"To connect neurons"}],"answerId":"a","explanation":"Myelin serves to insulate axons, allowing for faster conduction of action potentials.","kind":"recall","origin":"ai"},{"id":"nerve-fiber-myelin-synapse~ai-1","moduleId":"nerve-fiber-myelin-synapse","stem":"Which structure forms the blood-nerve barrier?","options":[{"id":"a","text":"Epineurium"},{"id":"b","text":"Perineurium"},{"id":"c","text":"Endoneurium"},{"id":"d","text":"Myelin sheath"}],"answerId":"b","explanation":"The perineurium wraps each fascicle and forms the blood-nerve barrier.","kind":"recall","origin":"ai"},{"id":"nerve-fiber-myelin-synapse~ai-2","moduleId":"nerve-fiber-myelin-synapse","stem":"What occurs at the nodes of Ranvier during saltatory conduction?","options":[{"id":"a","text":"Neurotransmitter release"},{"id":"b","text":"Action potential propagation"},{"id":"c","text":"Calcium influx"},{"id":"d","text":"Myelination"}],"answerId":"b","explanation":"Nodes of Ranvier are where action potentials propagate by jumping from node to node.","kind":"mechanism","origin":"ai"},{"id":"nerve-fiber-myelin-synapse~ai-3","moduleId":"nerve-fiber-myelin-synapse","stem":"A patient presents with slowed nerve conduction velocity. Which condition is most likely responsible?","options":[{"id":"a","text":"Increased myelination"},{"id":"b","text":"Demyelination"},{"id":"c","text":"Increased axon diameter"},{"id":"d","text":"Enhanced synaptic transmission"}],"answerId":"b","explanation":"Demyelination, as seen in conditions like multiple sclerosis, slows nerve conduction.","kind":"clinical","origin":"ai"},{"id":"nerve-fiber-myelin-synapse~ai-4","moduleId":"nerve-fiber-myelin-synapse","stem":"Which connective tissue layer surrounds individual axons?","options":[{"id":"a","text":"Epineurium"},{"id":"b","text":"Perineurium"},{"id":"c","text":"Endoneurium"},{"id":"d","text":"Fascicle"}],"answerId":"c","explanation":"The endoneurium is the innermost layer that surrounds each individual axon.","kind":"trap","origin":"ai"},{"id":"nerve-fiber-myelin-synapse~ai-5","moduleId":"nerve-fiber-myelin-synapse","stem":"How does myelination affect conduction velocity in nerve fibers?","options":[{"id":"a","text":"Decreases velocity"},{"id":"b","text":"Increases velocity"},{"id":"c","text":"Has no effect"},{"id":"d","text":"Only affects sensory fibers"}],"answerId":"b","explanation":"Increased myelination enhances conduction velocity due to reduced capacitance and increased insulation.","kind":"mechanism","origin":"ai"},{"id":"nerve-fiber-myelin-synapse~ai-6","moduleId":"nerve-fiber-myelin-synapse","stem":"How does the structure of the neuromuscular junction relate to synaptic transmission?","options":[{"id":"a","text":"It lacks neurotransmitter receptors"},{"id":"b","text":"It is a chemical synapse with ACh release"},{"id":"c","text":"It only transmits sensory signals"},{"id":"d","text":"It does not involve calcium channels"}],"answerId":"b","explanation":"The neuromuscular junction is a chemical synapse where acetylcholine is released to transmit signals to muscles.","kind":"integration","linkedModuleIds":["skeletal-muscle-sarcomere"],"origin":"ai"},{"id":"nerve-fiber-myelin-synapse~ai-7","moduleId":"nerve-fiber-myelin-synapse","stem":"What role do voltage-gated Na⁺ channels play in action potential propagation?","options":[{"id":"a","text":"They inhibit neurotransmitter release"},{"id":"b","text":"They allow sodium influx during depolarization"},{"id":"c","text":"They are only present in the CNS"},{"id":"d","text":"They are found exclusively at synapses"}],"answerId":"b","explanation":"Voltage-gated Na⁺ channels open during depolarization, allowing sodium influx that propagates the action potential.","kind":"integration","linkedModuleIds":["action-potential-propagation-refractory"],"origin":"ai"}],"membrane-transport-passive":[{"id":"membrane-transport-passive~ai-0","moduleId":"membrane-transport-passive","stem":"What is the primary mechanism of facilitated diffusion?","options":[{"id":"a","text":"Active transport against the gradient"},{"id":"b","text":"Passive transport down the gradient"},{"id":"c","text":"Endocytosis of solutes"},{"id":"d","text":"Exocytosis of solutes"}],"answerId":"b","explanation":"Facilitated diffusion is a passive process that allows solutes to move down their concentration gradient through a transport protein.","kind":"mechanism","origin":"ai"},{"id":"membrane-transport-passive~ai-1","moduleId":"membrane-transport-passive","stem":"Which of the following statements about channels is true?","options":[{"id":"a","text":"Channels require ATP to function"},{"id":"b","text":"Channels are slower than carriers"},{"id":"c","text":"Channels can be gated"},{"id":"d","text":"Channels transport only large molecules"}],"answerId":"c","explanation":"Channels form water-filled pores that can be gated and allow for rapid transport of ions and water.","kind":"recall","origin":"ai"},{"id":"membrane-transport-passive~ai-2","moduleId":"membrane-transport-passive","stem":"In which scenario would you expect to see carrier saturation?","options":[{"id":"a","text":"When solute concentration is low"},{"id":"b","text":"When all carriers are occupied"},{"id":"c","text":"When the solute is actively transported"},{"id":"d","text":"When the membrane is impermeable"}],"answerId":"b","explanation":"Carrier saturation occurs when all available transporters are occupied, leading to a plateau in transport rate.","kind":"recall","origin":"ai"},{"id":"membrane-transport-passive~ai-3","moduleId":"membrane-transport-passive","stem":"What is the primary defect in cystic fibrosis?","options":[{"id":"a","text":"Defective glucose transporter"},{"id":"b","text":"Defective Cl⁻ channel"},{"id":"c","text":"Defective aquaporin"},{"id":"d","text":"Defective sodium channel"}],"answerId":"b","explanation":"Cystic fibrosis is caused by mutations in the CFTR gene, which encodes a chloride channel.","kind":"recall","origin":"ai"},{"id":"membrane-transport-passive~ai-4","moduleId":"membrane-transport-passive","stem":"Which of the following is a trap regarding facilitated diffusion?","options":[{"id":"a","text":"It requires ATP for transport"},{"id":"b","text":"It is a passive process"},{"id":"c","text":"It can be saturated"},{"id":"d","text":"It involves conformational change of proteins"}],"answerId":"a","explanation":"Facilitated diffusion is passive and does not require ATP; this is a common misconception.","kind":"trap","origin":"ai"},{"id":"membrane-transport-passive~ai-5","moduleId":"membrane-transport-passive","stem":"How does facilitated diffusion differ from active transport?","options":[{"id":"a","text":"Facilitated diffusion requires energy"},{"id":"b","text":"Facilitated diffusion moves solutes against their gradient"},{"id":"c","text":"Facilitated diffusion is passive"},{"id":"d","text":"Facilitated diffusion uses vesicles"}],"answerId":"c","explanation":"Facilitated diffusion is a passive process that moves solutes down their concentration gradient, unlike active transport which requires energy to move solutes against their gradient.","kind":"mechanism","origin":"ai"},{"id":"membrane-transport-passive~ai-6","moduleId":"membrane-transport-passive","stem":"How does the transport of glucose via GLUT relate to the action potential in neurons?","options":[{"id":"a","text":"Both processes require ATP"},{"id":"b","text":"Both involve ion channels"},{"id":"c","text":"Both are examples of facilitated diffusion"},{"id":"d","text":"Both occur in the same cellular compartment"}],"answerId":"c","explanation":"GLUT transporters facilitate glucose entry into cells via facilitated diffusion, similar to how ion channels facilitate ion movement during action potentials.","kind":"integration","linkedModuleIds":["action-potential-genesis"],"origin":"ai"},{"id":"membrane-transport-passive~ai-7","moduleId":"membrane-transport-passive","stem":"What common feature do glucose transport and one-carbon carrier transport share?","options":[{"id":"a","text":"Both are active transport processes"},{"id":"b","text":"Both require ATP"},{"id":"c","text":"Both can exhibit saturation"},{"id":"d","text":"Both are exclusively passive processes"}],"answerId":"c","explanation":"Both glucose transport via GLUT and one-carbon carrier transport can exhibit saturation when all transporters are occupied.","kind":"integration","linkedModuleIds":["one-carbon-carriers"],"origin":"ai"}],"action-potential-genesis":[{"id":"action-potential-genesis~ai-0","moduleId":"action-potential-genesis","stem":"What is the primary mechanism by which an action potential is generated?","options":[{"id":"a","text":"Threshold → Na⁺ influx → K⁺ efflux"},{"id":"b","text":"K⁺ influx → Na⁺ efflux"},{"id":"c","text":"Na⁺/K⁺-ATPase activation"},{"id":"d","text":"K⁺ channel closure"}],"answerId":"a","explanation":"An action potential is generated by the sequential opening of voltage-gated Na⁺ channels followed by K⁺ channels.","kind":"mechanism","origin":"ai"},{"id":"action-potential-genesis~ai-1","moduleId":"action-potential-genesis","stem":"Which of the following findings indicates the repolarization phase of an action potential?","options":[{"id":"a","text":"Na⁺ influx"},{"id":"b","text":"K⁺ efflux"},{"id":"c","text":"Hyperpolarization"},{"id":"d","text":"Threshold reached"}],"answerId":"b","explanation":"Repolarization occurs when Na⁺ channels inactivate and voltage-gated K⁺ channels open, allowing K⁺ to exit the cell.","kind":"recall","origin":"ai"},{"id":"action-potential-genesis~ai-2","moduleId":"action-potential-genesis","stem":"What occurs during the hyperpolarization phase of an action potential?","options":[{"id":"a","text":"Na⁺ influx continues"},{"id":"b","text":"K⁺ channels close slowly"},{"id":"c","text":"Na⁺/K⁺-ATPase is activated"},{"id":"d","text":"Voltage-gated Ca²⁺ channels open"}],"answerId":"b","explanation":"Hyperpolarization is due to the slow closure of K⁺ channels, which causes the membrane potential to briefly overshoot resting levels.","kind":"recall","origin":"ai"},{"id":"action-potential-genesis~ai-3","moduleId":"action-potential-genesis","stem":"A stimulus that does not reach threshold will result in which of the following?","options":[{"id":"a","text":"An action potential with reduced amplitude"},{"id":"b","text":"An action potential with normal amplitude"},{"id":"c","text":"No action potential"},{"id":"d","text":"Increased frequency of action potentials"}],"answerId":"c","explanation":"Only a stimulus that reaches or exceeds the threshold will generate an action potential; sub-threshold stimuli produce none.","kind":"trap","origin":"ai"},{"id":"action-potential-genesis~ai-4","moduleId":"action-potential-genesis","stem":"How does a stronger stimulus affect action potential generation?","options":[{"id":"a","text":"Increases amplitude of AP"},{"id":"b","text":"Increases frequency of AP"},{"id":"c","text":"Decreases Na⁺ influx"},{"id":"d","text":"Decreases K⁺ efflux"}],"answerId":"b","explanation":"The strength of a stimulus is encoded by the frequency of action potentials, not their amplitude.","kind":"clinical","origin":"ai"},{"id":"action-potential-genesis~ai-5","moduleId":"action-potential-genesis","stem":"How is the action potential in cardiac muscle similar to that in neurons?","options":[{"id":"a","text":"Both rely solely on Na⁺ influx"},{"id":"b","text":"Both exhibit a refractory period"},{"id":"c","text":"Both are generated by ligand-gated channels"},{"id":"d","text":"Both have a resting potential of +30 mV"}],"answerId":"b","explanation":"Both cardiac and neuronal action potentials exhibit a refractory period, which is critical for proper function.","kind":"integration","linkedModuleIds":["cardiac-action-potential"],"origin":"ai"},{"id":"action-potential-genesis~ai-6","moduleId":"action-potential-genesis","stem":"What is a key difference between the action potential in neurons and cardiac cells?","options":[{"id":"a","text":"Duration of depolarization"},{"id":"b","text":"Threshold voltage"},{"id":"c","text":"Resting membrane potential"},{"id":"d","text":"Ion channel types involved"}],"answerId":"a","explanation":"The duration of depolarization is significantly longer in cardiac action potentials compared to neuronal action potentials.","kind":"integration","linkedModuleIds":["cardiac-action-potential"],"origin":"ai"}],"ecm-adhesion-integrins-clinical":[{"id":"ecm-adhesion-integrins-clinical~ai-0","moduleId":"ecm-adhesion-integrins-clinical","stem":"Which adhesive glycoprotein primarily anchors cells to the basal lamina?","options":[{"id":"a","text":"Fibronectin"},{"id":"b","text":"Laminin"},{"id":"c","text":"Collagen"},{"id":"d","text":"Elastin"}],"answerId":"b","explanation":"Laminin is the key adhesive protein of the basal lamina, binding integrins and type IV collagen.","kind":"recall","origin":"ai"},{"id":"ecm-adhesion-integrins-clinical~ai-1","moduleId":"ecm-adhesion-integrins-clinical","stem":"What is the primary function of integrins in cell adhesion?","options":[{"id":"a","text":"Signal transduction"},{"id":"b","text":"Cell division"},{"id":"c","text":"Energy production"},{"id":"d","text":"DNA replication"}],"answerId":"a","explanation":"Integrins serve as transmembrane bridges connecting the ECM to the cytoskeleton and facilitating signal transduction.","kind":"mechanism","origin":"ai"},{"id":"ecm-adhesion-integrins-clinical~ai-2","moduleId":"ecm-adhesion-integrins-clinical","stem":"A patient presents with elevated serum CTX-1. What does this indicate?","options":[{"id":"a","text":"Increased osteoblastic activity"},{"id":"b","text":"Decreased collagen synthesis"},{"id":"c","text":"Increased osteoclastic bone resorption"},{"id":"d","text":"Normal bone turnover"}],"answerId":"c","explanation":"Elevated CTX-1 levels indicate increased osteoclastic activity and collagen breakdown, commonly seen in osteoporosis.","kind":"clinical","origin":"ai"},{"id":"ecm-adhesion-integrins-clinical~ai-3","moduleId":"ecm-adhesion-integrins-clinical","stem":"Which of the following processes is primarily mediated by matrix metalloproteinases (MMPs)?","options":[{"id":"a","text":"Cell proliferation"},{"id":"b","text":"Collagen degradation"},{"id":"c","text":"Apoptosis"},{"id":"d","text":"Cell differentiation"}],"answerId":"b","explanation":"MMPs are enzymes responsible for degrading collagen and other ECM components during processes like wound healing and tumor invasion.","kind":"mechanism","origin":"ai"},{"id":"ecm-adhesion-integrins-clinical~ai-4","moduleId":"ecm-adhesion-integrins-clinical","stem":"What is the consequence of a cell losing contact with the ECM?","options":[{"id":"a","text":"Increased proliferation"},{"id":"b","text":"Anoikis"},{"id":"c","text":"Enhanced migration"},{"id":"d","text":"Cellular differentiation"}],"answerId":"b","explanation":"Loss of ECM contact leads to anoikis, a form of programmed cell death due to the loss of integrin-mediated survival signals.","kind":"recall","origin":"ai"},{"id":"ecm-adhesion-integrins-clinical~ai-5","moduleId":"ecm-adhesion-integrins-clinical","stem":"Which statement correctly distinguishes fibronectin from laminin?","options":[{"id":"a","text":"Fibronectin is found in the basal lamina, laminin in connective tissue"},{"id":"b","text":"Laminin is the main adhesive protein in connective tissue"},{"id":"c","text":"Fibronectin links cells to collagen, laminin to the basal lamina"},{"id":"d","text":"Laminin is involved in cell signaling, fibronectin in apoptosis"}],"answerId":"c","explanation":"Fibronectin primarily links cells to collagen in connective tissue, while laminin is the adhesive protein of the basal lamina.","kind":"trap","origin":"ai"},{"id":"ecm-adhesion-integrins-clinical~ai-6","moduleId":"ecm-adhesion-integrins-clinical","stem":"How does the structure of the basement membrane relate to its function in epithelial tissues?","options":[{"id":"a","text":"It provides a barrier to pathogens"},{"id":"b","text":"It facilitates nutrient absorption"},{"id":"c","text":"It anchors epithelial cells and acts as a filtration barrier"},{"id":"d","text":"It stores growth factors"}],"answerId":"c","explanation":"The basement membrane anchors epithelial cells and acts as a filtration barrier, crucial for tissue integrity and function.","kind":"integration","linkedModuleIds":["epithelial-surface-basement-membrane"],"origin":"ai"},{"id":"ecm-adhesion-integrins-clinical~ai-7","moduleId":"ecm-adhesion-integrins-clinical","stem":"How does integrin signaling influence keratinocyte behavior in the epidermis?","options":[{"id":"a","text":"Promotes apoptosis"},{"id":"b","text":"Inhibits migration"},{"id":"c","text":"Enhances adhesion and survival"},{"id":"d","text":"Reduces proliferation"}],"answerId":"c","explanation":"Integrin signaling enhances adhesion and survival of keratinocytes, which is essential for maintaining the epidermal barrier.","kind":"integration","linkedModuleIds":["epidermis-keratinocyte-biology"],"origin":"ai"}],"body-fluid-compartments":[{"id":"body-fluid-compartments~ai-0","moduleId":"body-fluid-compartments","stem":"What percentage of total body water is found in the intracellular fluid (ICF)?","options":[{"id":"a","text":"40%"},{"id":"b","text":"20%"},{"id":"c","text":"60%"},{"id":"d","text":"15%"}],"answerId":"a","explanation":"According to the 60-40-20 rule, approximately 40% of body weight is in the ICF.","kind":"recall","origin":"ai"},{"id":"body-fluid-compartments~ai-1","moduleId":"body-fluid-compartments","stem":"Which mechanism primarily maintains the high intracellular potassium concentration?","options":[{"id":"a","text":"Na⁺/K⁺-ATPase"},{"id":"b","text":"Aquaporins"},{"id":"c","text":"Osmosis"},{"id":"d","text":"Diffusion"}],"answerId":"a","explanation":"The Na⁺/K⁺-ATPase actively pumps K⁺ into cells and Na⁺ out, maintaining the high intracellular K⁺ concentration.","kind":"mechanism","origin":"ai"},{"id":"body-fluid-compartments~ai-2","moduleId":"body-fluid-compartments","stem":"What is the primary reason for the movement of water from the extracellular fluid (ECF) into cells during hyponatraemia?","options":[{"id":"a","text":"Increased intracellular Na⁺"},{"id":"b","text":"Decreased ECF osmolality"},{"id":"c","text":"Increased plasma protein"},{"id":"d","text":"Decreased intracellular K⁺"}],"answerId":"b","explanation":"Hyponatraemia lowers ECF osmolality, causing water to move into cells, leading to swelling.","kind":"clinical","origin":"ai"},{"id":"body-fluid-compartments~ai-3","moduleId":"body-fluid-compartments","stem":"Which of the following statements about body fluid compartments is FALSE?","options":[{"id":"a","text":"Most body water is intracellular."},{"id":"b","text":"ECF is one-third of total body water."},{"id":"c","text":"Plasma is protein-rich."},{"id":"d","text":"Interstitial fluid contains more proteins than plasma."}],"answerId":"d","explanation":"Plasma is protein-rich compared to interstitial fluid, which is nearly protein-impermeable.","kind":"trap","origin":"ai"},{"id":"body-fluid-compartments~ai-4","moduleId":"body-fluid-compartments","stem":"What is the primary role of albumin in the plasma?","options":[{"id":"a","text":"Transport of oxygen"},{"id":"b","text":"Oncotic pressure maintenance"},{"id":"c","text":"Electrolyte balance"},{"id":"d","text":"Cell signaling"}],"answerId":"b","explanation":"Albumin generates oncotic pressure, which helps retain water within the vascular compartment.","kind":"recall","origin":"ai"},{"id":"body-fluid-compartments~ai-5","moduleId":"body-fluid-compartments","stem":"How does the Na⁺/K⁺-ATPase contribute to the resting membrane potential?","options":[{"id":"a","text":"By generating a negative charge inside the cell"},{"id":"b","text":"By allowing Na⁺ influx"},{"id":"c","text":"By facilitating K⁺ efflux"},{"id":"d","text":"By increasing intracellular osmolality"}],"answerId":"a","explanation":"The Na⁺/K⁺-ATPase pumps out 3 Na⁺ for every 2 K⁺ it brings in, creating a negative charge inside the cell.","kind":"mechanism","origin":"ai"},{"id":"body-fluid-compartments~ai-6","moduleId":"body-fluid-compartments","stem":"How does the regulation of body fluid compartments relate to homeostasis?","options":[{"id":"a","text":"It maintains constant blood pressure."},{"id":"b","text":"It regulates body temperature."},{"id":"c","text":"It ensures electrolyte balance."},{"id":"d","text":"It prevents dehydration."}],"answerId":"c","explanation":"Regulation of body fluid compartments is essential for maintaining electrolyte balance, a key aspect of homeostasis.","kind":"integration","linkedModuleIds":["homeostasis-feedback-control"],"origin":"ai"},{"id":"body-fluid-compartments~ai-7","moduleId":"body-fluid-compartments","stem":"What is the clinical significance of understanding fluid compartments in renal function?","options":[{"id":"a","text":"It helps in drug dosing."},{"id":"b","text":"It aids in understanding fluid overload."},{"id":"c","text":"It is irrelevant to renal physiology."},{"id":"d","text":"It determines blood pH."}],"answerId":"b","explanation":"Knowledge of fluid compartments is crucial in managing fluid overload conditions, particularly in renal patients.","kind":"integration","linkedModuleIds":["body-fluid-compartments-renal"],"origin":"ai"}],"diffusion-osmosis-basics":[{"id":"diffusion-osmosis-basics~ai-0","moduleId":"diffusion-osmosis-basics","stem":"What is the primary driving force behind the movement of water during osmosis?","options":[{"id":"a","text":"Concentration gradient of solute"},{"id":"b","text":"Temperature of the solution"},{"id":"c","text":"Pressure applied to the solution"},{"id":"d","text":"Size of the water molecules"}],"answerId":"a","explanation":"Osmosis is driven by the concentration gradient of solute, where water moves toward the area of higher solute concentration.","kind":"recall","origin":"ai"},{"id":"diffusion-osmosis-basics~ai-1","moduleId":"diffusion-osmosis-basics","stem":"According to Fick's law, which factor would NOT increase the rate of diffusion?","options":[{"id":"a","text":"Increased concentration gradient"},{"id":"b","text":"Larger surface area"},{"id":"c","text":"Higher temperature"},{"id":"d","text":"Increased membrane thickness"}],"answerId":"d","explanation":"Increased membrane thickness decreases the rate of diffusion, as it is inversely proportional to distance.","kind":"trap","origin":"ai"},{"id":"diffusion-osmosis-basics~ai-2","moduleId":"diffusion-osmosis-basics","stem":"In a patient with pulmonary fibrosis, what is the expected effect on gas exchange?","options":[{"id":"a","text":"Increased diffusion rate of gases"},{"id":"b","text":"Decreased diffusion rate of gases"},{"id":"c","text":"No effect on diffusion"},{"id":"d","text":"Increased solubility of gases in blood"}],"answerId":"b","explanation":"Pulmonary fibrosis increases membrane thickness, which slows down the diffusion rate of gases like O₂ and CO₂.","kind":"clinical","origin":"ai"},{"id":"diffusion-osmosis-basics~ai-3","moduleId":"diffusion-osmosis-basics","stem":"Which statement correctly describes osmosis?","options":[{"id":"a","text":"Water moves toward lower solute concentration"},{"id":"b","text":"Water moves toward higher solute concentration"},{"id":"c","text":"Water moves equally in both directions"},{"id":"d","text":"Water movement is independent of solute concentration"}],"answerId":"b","explanation":"Osmosis is the movement of water from an area of low solute concentration to an area of high solute concentration.","kind":"trap","origin":"ai"},{"id":"diffusion-osmosis-basics~ai-4","moduleId":"diffusion-osmosis-basics","stem":"How does temperature affect the rate of diffusion?","options":[{"id":"a","text":"Increases rate by reducing molecular motion"},{"id":"b","text":"Decreases rate by increasing viscosity"},{"id":"c","text":"Increases rate by increasing molecular motion"},{"id":"d","text":"Has no effect on diffusion rate"}],"answerId":"c","explanation":"Higher temperatures increase molecular motion, which in turn increases the rate of diffusion.","kind":"mechanism","origin":"ai"},{"id":"diffusion-osmosis-basics~ai-5","moduleId":"diffusion-osmosis-basics","stem":"How does osmotic pressure relate to the number of solute particles in a solution?","options":[{"id":"a","text":"Osmotic pressure decreases with more solute particles"},{"id":"b","text":"Osmotic pressure is independent of solute particles"},{"id":"c","text":"Osmotic pressure increases with more solute particles"},{"id":"d","text":"Osmotic pressure is constant regardless of solute concentration"}],"answerId":"c","explanation":"Osmotic pressure increases with the number of solute particles, as it reflects the tendency of water to move toward higher solute concentrations.","kind":"recall","origin":"ai"},{"id":"diffusion-osmosis-basics~ai-6","moduleId":"diffusion-osmosis-basics","stem":"A patient presents with dehydration. Which physiological process is primarily responsible for water movement in their body?","options":[{"id":"a","text":"Diffusion"},{"id":"b","text":"Active transport"},{"id":"c","text":"Osmosis"},{"id":"d","text":"Facilitated diffusion"}],"answerId":"c","explanation":"In dehydration, water moves through osmosis toward areas of higher solute concentration to maintain fluid balance.","kind":"integration","linkedModuleIds":["osmolarity-tonicity-cell-volume"],"origin":"ai"},{"id":"diffusion-osmosis-basics~ai-7","moduleId":"diffusion-osmosis-basics","stem":"In a scenario where a cell is placed in a hypertonic solution, what will happen to the cell volume?","options":[{"id":"a","text":"Cell will swell"},{"id":"b","text":"Cell will remain the same"},{"id":"c","text":"Cell will shrink"},{"id":"d","text":"Cell will burst"}],"answerId":"c","explanation":"In a hypertonic solution, water moves out of the cell toward the higher solute concentration, causing the cell to shrink.","kind":"integration","linkedModuleIds":["osmolarity-tonicity-cell-volume"],"origin":"ai"}],"osmolarity-tonicity-cell-volume":[{"id":"osmolarity-tonicity-cell-volume~ai-0","moduleId":"osmolarity-tonicity-cell-volume","stem":"What is the primary determinant of tonicity?","options":[{"id":"a","text":"Total solute concentration"},{"id":"b","text":"Penetrating solutes"},{"id":"c","text":"Non-penetrating solutes"},{"id":"d","text":"Temperature of the solution"}],"answerId":"c","explanation":"Tonicity is determined by non-penetrating solutes, as they affect water movement across cell membranes.","kind":"recall","origin":"ai"},{"id":"osmolarity-tonicity-cell-volume~ai-1","moduleId":"osmolarity-tonicity-cell-volume","stem":"Which solution would cause red blood cells to crenate?","options":[{"id":"a","text":"0.9% saline"},{"id":"b","text":"5% dextrose"},{"id":"c","text":"Distilled water"},{"id":"d","text":"3% saline"}],"answerId":"d","explanation":"3% saline is hypertonic, causing water to leave the cells and resulting in crenation.","kind":"clinical","origin":"ai"},{"id":"osmolarity-tonicity-cell-volume~ai-2","moduleId":"osmolarity-tonicity-cell-volume","stem":"What happens to cells placed in an iso-osmotic urea solution?","options":[{"id":"a","text":"Cells swell"},{"id":"b","text":"Cells shrink"},{"id":"c","text":"No change in volume"},{"id":"d","text":"Cells lyse"}],"answerId":"a","explanation":"Urea is a penetrating solute; thus, while the solution is iso-osmotic, it is effectively hypotonic, causing cells to swell.","kind":"mechanism","origin":"ai"},{"id":"osmolarity-tonicity-cell-volume~ai-3","moduleId":"osmolarity-tonicity-cell-volume","stem":"What is the plasma osmolality in a healthy adult?","options":[{"id":"a","text":"250 mOsm/kg"},{"id":"b","text":"290 mOsm/kg"},{"id":"c","text":"310 mOsm/kg"},{"id":"d","text":"350 mOsm/kg"}],"answerId":"b","explanation":"Normal plasma osmolality is approximately 290 mOsm/kg, primarily due to Na⁺ salts, glucose, and urea.","kind":"recall","origin":"ai"},{"id":"osmolarity-tonicity-cell-volume~ai-4","moduleId":"osmolarity-tonicity-cell-volume","stem":"Which of the following statements about osmolarity and tonicity is correct?","options":[{"id":"a","text":"Iso-osmotic solutions are always isotonic"},{"id":"b","text":"Tonicity includes penetrating solutes"},{"id":"c","text":"Hypotonic solutions cause cell swelling"},{"id":"d","text":"Hypertonic solutions do not affect cell volume"}],"answerId":"c","explanation":"Hypotonic solutions lead to cell swelling due to water influx; the other statements are incorrect.","kind":"trap","origin":"ai"},{"id":"osmolarity-tonicity-cell-volume~ai-5","moduleId":"osmolarity-tonicity-cell-volume","stem":"How does mannitol reduce cerebral edema?","options":[{"id":"a","text":"By increasing plasma osmolality"},{"id":"b","text":"By penetrating cell membranes"},{"id":"c","text":"By diluting intracellular solutes"},{"id":"d","text":"By decreasing blood volume"}],"answerId":"a","explanation":"Mannitol is a hypertonic solution that increases plasma osmolality, drawing water out of cells and reducing edema.","kind":"mechanism","origin":"ai"},{"id":"osmolarity-tonicity-cell-volume~ai-6","moduleId":"osmolarity-tonicity-cell-volume","stem":"How does the regulation of blood osmolarity relate to homeostasis?","options":[{"id":"a","text":"It affects blood pressure"},{"id":"b","text":"It regulates body temperature"},{"id":"c","text":"It maintains cell volume"},{"id":"d","text":"It influences respiratory rate"}],"answerId":"c","explanation":"Regulating blood osmolarity is crucial for maintaining cell volume and overall homeostasis.","kind":"integration","linkedModuleIds":["homeostasis-feedback-control"],"origin":"ai"},{"id":"osmolarity-tonicity-cell-volume~ai-7","moduleId":"osmolarity-tonicity-cell-volume","stem":"What role does diffusion play in osmolarity regulation?","options":[{"id":"a","text":"It prevents solute movement"},{"id":"b","text":"It facilitates solute and water movement"},{"id":"c","text":"It only affects non-penetrating solutes"},{"id":"d","text":"It has no effect on osmolarity"}],"answerId":"b","explanation":"Diffusion facilitates the movement of solutes and water, which is essential for regulating osmolarity in body fluids.","kind":"integration","linkedModuleIds":["diffusion-osmosis-basics"],"origin":"ai"}],"subcellular-pathology-alterations":[{"id":"subcellular-pathology-alterations~ai-0","moduleId":"subcellular-pathology-alterations","stem":"What is the primary mechanism behind smooth endoplasmic reticulum (SER) hyperplasia in hepatocytes due to chronic alcohol consumption?","options":[{"id":"a","text":"Increased apoptosis"},{"id":"b","text":"Adaptive enzyme induction"},{"id":"c","text":"Mitochondrial dysfunction"},{"id":"d","text":"Cellular necrosis"}],"answerId":"b","explanation":"Smooth ER hyperplasia is an adaptive response that increases detoxification enzyme production, not a sign of cell death.","kind":"mechanism","origin":"ai"},{"id":"subcellular-pathology-alterations~ai-1","moduleId":"subcellular-pathology-alterations","stem":"Which of the following findings is characteristic of megamitochondria in alcoholic liver disease?","options":[{"id":"a","text":"Increased number of lysosomes"},{"id":"b","text":"Abnormally large mitochondria"},{"id":"c","text":"Decreased mitochondrial DNA"},{"id":"d","text":"Normal mitochondrial morphology"}],"answerId":"b","explanation":"Megamitochondria are abnormally large mitochondria that appear in conditions like alcoholic liver disease.","kind":"recall","origin":"ai"},{"id":"subcellular-pathology-alterations~ai-2","moduleId":"subcellular-pathology-alterations","stem":"What histological change is indicated by the presence of neutrophils infiltrating colonic crypts?","options":[{"id":"a","text":"Hyperplasia"},{"id":"b","text":"Cryptitis"},{"id":"c","text":"Atrophy"},{"id":"d","text":"Parakeratosis"}],"answerId":"b","explanation":"Neutrophil infiltration in colonic crypts is a hallmark of cryptitis, indicating inflammation.","kind":"recall","origin":"ai"},{"id":"subcellular-pathology-alterations~ai-3","moduleId":"subcellular-pathology-alterations","stem":"Which of the following best describes parakeratosis?","options":[{"id":"a","text":"Loss of keratinocytes"},{"id":"b","text":"Retention of nuclei in the stratum corneum"},{"id":"c","text":"Increased apoptosis of epidermal cells"},{"id":"d","text":"Normal keratinization process"}],"answerId":"b","explanation":"Parakeratosis is characterized by the retention of nuclei in the stratum corneum, indicating abnormal keratinocyte proliferation.","kind":"recall","origin":"ai"},{"id":"subcellular-pathology-alterations~ai-4","moduleId":"subcellular-pathology-alterations","stem":"Smooth endoplasmic reticulum hyperplasia is often misinterpreted as irreversible damage. What is the correct interpretation?","options":[{"id":"a","text":"It indicates cell death"},{"id":"b","text":"It is an adaptive, reversible response"},{"id":"c","text":"It signifies malignant transformation"},{"id":"d","text":"It leads to necrosis"}],"answerId":"b","explanation":"Smooth ER hyperplasia is an adaptive, reversible response to increased metabolic demand, not indicative of cell death.","kind":"trap","origin":"ai"},{"id":"subcellular-pathology-alterations~ai-5","moduleId":"subcellular-pathology-alterations","stem":"How does mitochondrial proliferation relate to oncocytomas?","options":[{"id":"a","text":"It indicates necrosis"},{"id":"b","text":"It is a response to increased oxidative stress"},{"id":"c","text":"It leads to decreased ATP production"},{"id":"d","text":"It results in eosinophilic, mitochondria-packed cells"}],"answerId":"d","explanation":"Mitochondrial proliferation in oncocytomas results in eosinophilic, mitochondria-packed cells, characteristic of this tumor type.","kind":"recall","origin":"ai"},{"id":"subcellular-pathology-alterations~ai-6","moduleId":"subcellular-pathology-alterations","stem":"How can changes in nuclear morphology, such as hyperchromasia, be linked to subcellular alterations in disease?","options":[{"id":"a","text":"They indicate mitochondrial dysfunction"},{"id":"b","text":"They reflect chromatin aggregation and malignancy"},{"id":"c","text":"They are unrelated to cellular injury"},{"id":"d","text":"They signify normal cell function"}],"answerId":"b","explanation":"Hyperchromasia is associated with chromatin aggregation, which is a common feature in malignant cells, reflecting subcellular alterations.","kind":"integration","linkedModuleIds":["nucleus-chromatin-nucleolus"],"origin":"ai"},{"id":"subcellular-pathology-alterations~ai-7","moduleId":"subcellular-pathology-alterations","stem":"What is the relationship between mitochondrial alterations and the function of cytoplasmic organelles in disease?","options":[{"id":"a","text":"Mitochondrial dysfunction leads to lysosomal degradation"},{"id":"b","text":"Altered mitochondria affect the function of other organelles"},{"id":"c","text":"Mitochondrial changes are independent of cytoplasmic organelles"},{"id":"d","text":"Mitochondrial proliferation decreases organelle function"}],"answerId":"b","explanation":"Mitochondrial alterations can significantly impact the function of other cytoplasmic organelles, affecting overall cellular health.","kind":"integration","linkedModuleIds":["cytoplasmic-organelles"],"origin":"ai"}],"graded-potentials-cable-properties":[{"id":"graded-potentials-cable-properties~ai-0","moduleId":"graded-potentials-cable-properties","stem":"What characterizes graded potentials?","options":[{"id":"a","text":"All-or-none response"},{"id":"b","text":"Variable amplitude"},{"id":"c","text":"Regenerative propagation"},{"id":"d","text":"Long-distance transmission"}],"answerId":"b","explanation":"Graded potentials vary in amplitude and can summate, unlike action potentials which are all-or-none.","kind":"recall","origin":"ai"},{"id":"graded-potentials-cable-properties~ai-1","moduleId":"graded-potentials-cable-properties","stem":"Which factor increases the length constant (λ) of a neuron?","options":[{"id":"a","text":"Higher axial resistance"},{"id":"b","text":"Lower membrane resistance"},{"id":"c","text":"Larger axon diameter"},{"id":"d","text":"Increased capacitance"}],"answerId":"c","explanation":"A larger axon diameter decreases axial resistance, allowing current to flow more easily and increasing the length constant.","kind":"mechanism","origin":"ai"},{"id":"graded-potentials-cable-properties~ai-2","moduleId":"graded-potentials-cable-properties","stem":"What is the primary reason graded potentials cannot propagate long distances?","options":[{"id":"a","text":"They are all-or-none signals"},{"id":"b","text":"They decay with distance"},{"id":"c","text":"They are too fast"},{"id":"d","text":"They require myelination"}],"answerId":"b","explanation":"Graded potentials decay with distance due to passive spread, preventing them from traveling long distances.","kind":"trap","origin":"ai"},{"id":"graded-potentials-cable-properties~ai-3","moduleId":"graded-potentials-cable-properties","stem":"What is the main role of graded potentials in neuronal signaling?","options":[{"id":"a","text":"To regenerate action potentials"},{"id":"b","text":"To integrate synaptic inputs"},{"id":"c","text":"To propagate signals over long distances"},{"id":"d","text":"To maintain resting membrane potential"}],"answerId":"b","explanation":"Graded potentials integrate synaptic inputs to determine whether the neuron will fire an action potential.","kind":"clinical","origin":"ai"},{"id":"graded-potentials-cable-properties~ai-4","moduleId":"graded-potentials-cable-properties","stem":"How does myelination affect neuronal conduction?","options":[{"id":"a","text":"Increases axial resistance"},{"id":"b","text":"Decreases membrane capacitance"},{"id":"c","text":"Enhances saltatory conduction"},{"id":"d","text":"Lowers action potential threshold"}],"answerId":"c","explanation":"Myelination increases membrane resistance, which enhances saltatory conduction by allowing the action potential to jump between nodes of Ranvier.","kind":"mechanism","origin":"ai"},{"id":"graded-potentials-cable-properties~ai-5","moduleId":"graded-potentials-cable-properties","stem":"How do graded potentials relate to GI smooth muscle activity?","options":[{"id":"a","text":"They generate action potentials directly"},{"id":"b","text":"They modulate slow waves"},{"id":"c","text":"They are unaffected by synaptic inputs"},{"id":"d","text":"They propagate over long distances"}],"answerId":"b","explanation":"Graded potentials modulate the slow waves in GI smooth muscle, influencing contraction patterns.","kind":"integration","linkedModuleIds":["gi-smooth-muscle-electrical-activity"],"origin":"ai"},{"id":"graded-potentials-cable-properties~ai-6","moduleId":"graded-potentials-cable-properties","stem":"What is the relationship between graded potentials and action potentials?","options":[{"id":"a","text":"Graded potentials are all-or-none"},{"id":"b","text":"Graded potentials can travel long distances"},{"id":"c","text":"Graded potentials can summate to trigger action potentials"},{"id":"d","text":"Graded potentials are faster than action potentials"}],"answerId":"c","explanation":"Graded potentials can summate to reach the threshold needed to trigger an action potential at the axon hillock.","kind":"integration","linkedModuleIds":["action-potential-genesis"],"origin":"ai"}],"goldman-rmp-regulation":[{"id":"goldman-rmp-regulation~ai-0","moduleId":"goldman-rmp-regulation","stem":"What primarily determines the resting membrane potential (RMP) in a typical neuron?","options":[{"id":"a","text":"Na⁺ concentration gradient"},{"id":"b","text":"K⁺ permeability"},{"id":"c","text":"Cl⁻ permeability"},{"id":"d","text":"Ca²⁺ concentration gradient"}],"answerId":"b","explanation":"The RMP is predominantly influenced by K⁺ permeability due to the high density of K⁺ leak channels.","kind":"recall","origin":"ai"},{"id":"goldman-rmp-regulation~ai-1","moduleId":"goldman-rmp-regulation","stem":"Which ion's permeability increase leads to the upstroke of the action potential?","options":[{"id":"a","text":"K⁺"},{"id":"b","text":"Cl⁻"},{"id":"c","text":"Ca²⁺"},{"id":"d","text":"Na⁺"}],"answerId":"d","explanation":"The upstroke of the action potential is caused by a rapid increase in Na⁺ permeability.","kind":"mechanism","origin":"ai"},{"id":"goldman-rmp-regulation~ai-2","moduleId":"goldman-rmp-regulation","stem":"What is the effect of hyperkalaemia on cardiac cells?","options":[{"id":"a","text":"Hyperpolarization"},{"id":"b","text":"Increased excitability"},{"id":"c","text":"Depolarization"},{"id":"d","text":"No effect"}],"answerId":"c","explanation":"Hyperkalaemia raises extracellular K⁺ concentration, leading to depolarization of cardiac cells.","kind":"recall","origin":"ai"},{"id":"goldman-rmp-regulation~ai-3","moduleId":"goldman-rmp-regulation","stem":"What happens to the resting membrane potential if the Na⁺/K⁺-ATPase is inhibited?","options":[{"id":"a","text":"It becomes more negative"},{"id":"b","text":"It becomes more positive"},{"id":"c","text":"It remains unchanged"},{"id":"d","text":"It oscillates"}],"answerId":"b","explanation":"Inhibition of the Na⁺/K⁺-ATPase leads to gradual depolarization due to the loss of ion gradients.","kind":"mechanism","origin":"ai"},{"id":"goldman-rmp-regulation~ai-4","moduleId":"goldman-rmp-regulation","stem":"Which statement correctly describes the mechanism of action potential generation?","options":[{"id":"a","text":"Ion concentration changes drive rapid Vm changes"},{"id":"b","text":"Permeability changes drive rapid Vm changes"},{"id":"c","text":"Only K⁺ channels are involved"},{"id":"d","text":"Na⁺/K⁺-ATPase is the primary driver"}],"answerId":"b","explanation":"Action potential generation is primarily driven by changes in ion permeability, not concentration.","kind":"trap","origin":"ai"},{"id":"goldman-rmp-regulation~ai-5","moduleId":"goldman-rmp-regulation","stem":"How does the Goldman equation differ from the Nernst equation?","options":[{"id":"a","text":"Goldman considers multiple ions; Nernst considers one"},{"id":"b","text":"Goldman is for resting potential; Nernst is for action potential"},{"id":"c","text":"Goldman is less accurate"},{"id":"d","text":"Nernst requires permeability data"}],"answerId":"a","explanation":"The Goldman equation calculates the resting potential based on the permeability of multiple ions, while the Nernst equation focuses on a single ion.","kind":"integration","linkedModuleIds":["resting-membrane-potential-nernst"],"origin":"ai"},{"id":"goldman-rmp-regulation~ai-6","moduleId":"goldman-rmp-regulation","stem":"What is the relationship between resting membrane potential and action potential generation?","options":[{"id":"a","text":"RMP is irrelevant to AP"},{"id":"b","text":"RMP determines threshold for AP"},{"id":"c","text":"AP is independent of RMP"},{"id":"d","text":"RMP only affects Na⁺ channels"}],"answerId":"b","explanation":"The resting membrane potential sets the baseline from which the threshold for action potential generation is determined.","kind":"integration","linkedModuleIds":["action-potential-genesis"],"origin":"ai"}],"neurotransmitter-systems-catalog":[{"id":"neurotransmitter-systems-catalog~ai-0","moduleId":"neurotransmitter-systems-catalog","stem":"What is the main excitatory neurotransmitter of the central nervous system?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"GABA"},{"id":"c","text":"Glutamate"},{"id":"d","text":"Serotonin"}],"answerId":"c","explanation":"Glutamate is recognized as the principal excitatory neurotransmitter in the CNS, acting primarily through AMPA and NMDA receptors.","kind":"recall","origin":"ai"},{"id":"neurotransmitter-systems-catalog~ai-1","moduleId":"neurotransmitter-systems-catalog","stem":"Which neurotransmitter is primarily responsible for inhibitory signaling in the brain?","options":[{"id":"a","text":"Glutamate"},{"id":"b","text":"Glycine"},{"id":"c","text":"Dopamine"},{"id":"d","text":"GABA"}],"answerId":"d","explanation":"GABA is the main inhibitory neurotransmitter in the brain, functioning by opening chloride channels to induce hyperpolarization.","kind":"recall","origin":"ai"},{"id":"neurotransmitter-systems-catalog~ai-2","moduleId":"neurotransmitter-systems-catalog","stem":"What mechanism underlies the excitatory effect of glutamate at synapses?","options":[{"id":"a","text":"Opening of K+ channels"},{"id":"b","text":"Opening of Cl- channels"},{"id":"c","text":"Opening of Na+ channels"},{"id":"d","text":"Inhibition of GABA receptors"}],"answerId":"c","explanation":"Glutamate excites neurons by opening cation channels, primarily allowing Na+ influx, leading to depolarization.","kind":"mechanism","origin":"ai"},{"id":"neurotransmitter-systems-catalog~ai-3","moduleId":"neurotransmitter-systems-catalog","stem":"A patient presents with tremors and rigidity. Which neurotransmitter deficiency is most likely responsible?","options":[{"id":"a","text":"Serotonin"},{"id":"b","text":"GABA"},{"id":"c","text":"Dopamine"},{"id":"d","text":"Acetylcholine"}],"answerId":"c","explanation":"Dopamine deficiency, particularly in the nigrostriatal pathway, is associated with Parkinson's disease, characterized by tremors and rigidity.","kind":"recall","origin":"ai"},{"id":"neurotransmitter-systems-catalog~ai-4","moduleId":"neurotransmitter-systems-catalog","stem":"Benzodiazepines enhance inhibition primarily through which mechanism?","options":[{"id":"a","text":"Blocking NMDA receptors"},{"id":"b","text":"Positive modulation of GABA-A receptors"},{"id":"c","text":"Increasing serotonin levels"},{"id":"d","text":"Inhibiting dopamine reuptake"}],"answerId":"b","explanation":"Benzodiazepines act as positive allosteric modulators of the GABA-A receptor, enhancing its inhibitory effects.","kind":"mechanism","origin":"ai"},{"id":"neurotransmitter-systems-catalog~ai-5","moduleId":"neurotransmitter-systems-catalog","stem":"Which neurotransmitter can have both excitatory and inhibitory effects depending on the receptor type?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"Acetylcholine"},{"id":"c","text":"GABA"},{"id":"d","text":"Serotonin"}],"answerId":"b","explanation":"Acetylcholine can be excitatory at nicotinic receptors and inhibitory at certain muscarinic receptors, demonstrating its dual role.","kind":"trap","origin":"ai"},{"id":"neurotransmitter-systems-catalog~ai-6","moduleId":"neurotransmitter-systems-catalog","stem":"How do broad-spectrum AEDs primarily exert their effects on neurotransmission?","options":[{"id":"a","text":"Inhibiting dopamine synthesis"},{"id":"b","text":"Enhancing GABAergic transmission"},{"id":"c","text":"Blocking serotonin receptors"},{"id":"d","text":"Increasing glutamate release"}],"answerId":"b","explanation":"Broad-spectrum AEDs primarily enhance GABAergic transmission to reduce neuronal excitability and prevent seizures.","kind":"integration","linkedModuleIds":["aeds-broad-spectrum"],"origin":"ai"},{"id":"neurotransmitter-systems-catalog~ai-7","moduleId":"neurotransmitter-systems-catalog","stem":"Which neurotransmitter system is most directly linked to the mechanisms of long-term depression in synaptic plasticity?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"Glutamate"},{"id":"c","text":"GABA"},{"id":"d","text":"Acetylcholine"}],"answerId":"b","explanation":"Glutamate is crucial in synaptic plasticity, including long-term depression (LTD), which is mediated through NMDA receptor activation.","kind":"integration","linkedModuleIds":["synaptic-plasticity-ltd-memory"],"origin":"ai"}],"second-messenger-systems":[{"id":"second-messenger-systems~ai-0","moduleId":"second-messenger-systems","stem":"What is the primary function of second messengers in signal transduction?","options":[{"id":"a","text":"Amplify signals inside the cell"},{"id":"b","text":"Activate surface receptors"},{"id":"c","text":"Transport first messengers"},{"id":"d","text":"Degrade signaling molecules"}],"answerId":"a","explanation":"Second messengers relay and amplify signals inside the cell after a first messenger binds to a surface receptor.","kind":"recall","origin":"ai"},{"id":"second-messenger-systems~ai-1","moduleId":"second-messenger-systems","stem":"Which pathway involves the release of Ca²⁺ from the endoplasmic reticulum?","options":[{"id":"a","text":"cAMP pathway"},{"id":"b","text":"IP₃/DAG pathway"},{"id":"c","text":"cGMP pathway"},{"id":"d","text":"Adenylyl cyclase pathway"}],"answerId":"b","explanation":"The IP₃/DAG pathway activates phospholipase C, leading to the release of Ca²⁺ from the endoplasmic reticulum.","kind":"mechanism","origin":"ai"},{"id":"second-messenger-systems~ai-2","moduleId":"second-messenger-systems","stem":"What is the effect of caffeine on cAMP levels?","options":[{"id":"a","text":"Increases degradation of cAMP"},{"id":"b","text":"Inhibits phosphodiesterase"},{"id":"c","text":"Activates adenylyl cyclase"},{"id":"d","text":"Decreases cAMP synthesis"}],"answerId":"b","explanation":"Caffeine inhibits phosphodiesterase, leading to prolonged effects of cAMP by preventing its degradation.","kind":"clinical","origin":"ai"},{"id":"second-messenger-systems~ai-3","moduleId":"second-messenger-systems","stem":"Which statement correctly describes the role of IP₃ and DAG?","options":[{"id":"a","text":"IP₃ activates PKC; DAG releases Ca²⁺"},{"id":"b","text":"DAG activates PKC; IP₃ releases Ca²⁺"},{"id":"c","text":"Both activate PKC"},{"id":"d","text":"Both release Ca²⁺"}],"answerId":"b","explanation":"IP₃ releases Ca²⁺ from the ER, while DAG activates protein kinase C (PKC) at the membrane.","kind":"trap","origin":"ai"},{"id":"second-messenger-systems~ai-4","moduleId":"second-messenger-systems","stem":"How does a G protein-coupled receptor (GPCR) signal through cAMP?","options":[{"id":"a","text":"By directly activating protein kinase A"},{"id":"b","text":"By activating adenylyl cyclase"},{"id":"c","text":"By releasing Ca²⁺"},{"id":"d","text":"By inhibiting phosphodiesterase"}],"answerId":"b","explanation":"A GPCR activates a G protein, which in turn activates adenylyl cyclase, leading to increased cAMP levels.","kind":"mechanism","origin":"ai"},{"id":"second-messenger-systems~ai-5","moduleId":"second-messenger-systems","stem":"How does glucagon signaling relate to second messenger systems?","options":[{"id":"a","text":"It activates phospholipase C"},{"id":"b","text":"It increases cAMP levels"},{"id":"c","text":"It decreases intracellular Ca²⁺"},{"id":"d","text":"It inhibits adenylyl cyclase"}],"answerId":"b","explanation":"Glucagon signaling primarily works through the cAMP pathway, increasing cAMP levels and activating protein kinase A.","kind":"integration","linkedModuleIds":["hen1-glucagon-fasting-metabolism"],"origin":"ai"},{"id":"second-messenger-systems~ai-6","moduleId":"second-messenger-systems","stem":"What is a common mechanism of signal transduction in auditory physiology?","options":[{"id":"a","text":"cAMP pathway"},{"id":"b","text":"IP₃/DAG pathway"},{"id":"c","text":"Calcium signaling"},{"id":"d","text":"G protein inhibition"}],"answerId":"c","explanation":"Calcium signaling plays a crucial role in auditory physiology, similar to its role as a universal second messenger in other pathways.","kind":"integration","linkedModuleIds":["auditory-physiology-hearing"],"origin":"ai"}],"neurotransmitters-types-lifecycle":[{"id":"neurotransmitters-types-lifecycle~ai-0","moduleId":"neurotransmitters-types-lifecycle","stem":"What is the first step in the neurotransmitter life cycle at a chemical synapse?","options":[{"id":"a","text":"Packaging into vesicles"},{"id":"b","text":"Synthesis"},{"id":"c","text":"Vesicle fusion"},{"id":"d","text":"Reuptake"}],"answerId":"b","explanation":"The life cycle begins with the synthesis of neurotransmitters before they are packaged into vesicles.","kind":"recall","origin":"ai"},{"id":"neurotransmitters-types-lifecycle~ai-1","moduleId":"neurotransmitters-types-lifecycle","stem":"Which neurotransmitter is primarily cleared by enzymatic degradation in the synaptic cleft?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"Serotonin"},{"id":"c","text":"Acetylcholine"},{"id":"d","text":"Glutamate"}],"answerId":"c","explanation":"Acetylcholine is broken down in the synaptic cleft by acetylcholinesterase.","kind":"recall","origin":"ai"},{"id":"neurotransmitters-types-lifecycle~ai-2","moduleId":"neurotransmitters-types-lifecycle","stem":"What effect does acetylcholine have on skeletal muscle?","options":[{"id":"a","text":"Inhibitory"},{"id":"b","text":"Excitatory"},{"id":"c","text":"No effect"},{"id":"d","text":"Variable effect"}],"answerId":"b","explanation":"Acetylcholine excites skeletal muscle through nicotinic receptors.","kind":"recall","origin":"ai"},{"id":"neurotransmitters-types-lifecycle~ai-3","moduleId":"neurotransmitters-types-lifecycle","stem":"What mechanism do SSRIs use to increase synaptic serotonin levels?","options":[{"id":"a","text":"Inhibition of serotonin synthesis"},{"id":"b","text":"Inhibition of serotonin reuptake"},{"id":"c","text":"Promotion of serotonin release"},{"id":"d","text":"Inhibition of serotonin degradation"}],"answerId":"b","explanation":"SSRIs block the serotonin reuptake transporter, increasing serotonin levels in the synaptic cleft.","kind":"mechanism","origin":"ai"},{"id":"neurotransmitters-types-lifecycle~ai-4","moduleId":"neurotransmitters-types-lifecycle","stem":"Which neurotransmitter is considered the main excitatory neurotransmitter in the CNS?","options":[{"id":"a","text":"GABA"},{"id":"b","text":"Glycine"},{"id":"c","text":"Glutamate"},{"id":"d","text":"Dopamine"}],"answerId":"c","explanation":"Glutamate is the primary excitatory neurotransmitter in the central nervous system.","kind":"recall","origin":"ai"},{"id":"neurotransmitters-types-lifecycle~ai-5","moduleId":"neurotransmitters-types-lifecycle","stem":"A patient presents with symptoms of depression. Which neurotransmitter system is most likely involved in the efficacy of SSRIs?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"Acetylcholine"},{"id":"c","text":"Serotonin"},{"id":"d","text":"Norepinephrine"}],"answerId":"c","explanation":"SSRIs primarily target the serotonin system to alleviate symptoms of depression.","kind":"integration","linkedModuleIds":["atypical-antipsychotic-agents"],"origin":"ai"},{"id":"neurotransmitters-types-lifecycle~ai-6","moduleId":"neurotransmitters-types-lifecycle","stem":"In which way can the effect of a neurotransmitter be altered?","options":[{"id":"a","text":"Changing the neurotransmitter molecule"},{"id":"b","text":"Changing the receptor type"},{"id":"c","text":"Increasing neurotransmitter concentration"},{"id":"d","text":"Decreasing synaptic cleft size"}],"answerId":"b","explanation":"The effect of a neurotransmitter depends on the receptor type it binds to, not the neurotransmitter itself.","kind":"trap","origin":"ai"},{"id":"neurotransmitters-types-lifecycle~ai-7","moduleId":"neurotransmitters-types-lifecycle","stem":"What is the primary mechanism by which GABA exerts its inhibitory effect in the CNS?","options":[{"id":"a","text":"Inhibition of neurotransmitter release"},{"id":"b","text":"Activation of excitatory receptors"},{"id":"c","text":"Opening of chloride channels"},{"id":"d","text":"Inhibition of calcium channels"}],"answerId":"c","explanation":"GABA primarily exerts its inhibitory effect by opening chloride channels, leading to hyperpolarization of the neuron.","kind":"mechanism","origin":"ai"},{"id":"neurotransmitters-types-lifecycle~ai-8","moduleId":"neurotransmitters-types-lifecycle","stem":"How do neuromodulators differ from classical neurotransmitters?","options":[{"id":"a","text":"They act faster"},{"id":"b","text":"They bind to ionotropic receptors"},{"id":"c","text":"They modulate synaptic transmission strength"},{"id":"d","text":"They are always excitatory"}],"answerId":"c","explanation":"Neuromodulators act more slowly and modulate the strength of synaptic transmission rather than directly opening ion channels.","kind":"mechanism","origin":"ai"}],"action-potential-propagation-refractory":[{"id":"action-potential-propagation-refractory~ai-0","moduleId":"action-potential-propagation-refractory","stem":"What is the primary mechanism that allows an action potential to propagate along an axon?","options":[{"id":"a","text":"Repolarization of the membrane"},{"id":"b","text":"Depolarization of adjacent membrane"},{"id":"c","text":"Hyperpolarization of the membrane"},{"id":"d","text":"Inactivation of potassium channels"}],"answerId":"b","explanation":"An action potential propagates by depolarizing adjacent membrane regions to threshold, allowing regeneration of the AP.","kind":"mechanism","origin":"ai"},{"id":"action-potential-propagation-refractory~ai-1","moduleId":"action-potential-propagation-refractory","stem":"Which of the following findings indicates that an action potential is non-decremental?","options":[{"id":"a","text":"AP amplitude decreases along the axon"},{"id":"b","text":"AP amplitude remains constant along the axon"},{"id":"c","text":"AP can be evoked by a weak stimulus"},{"id":"d","text":"AP duration increases with distance"}],"answerId":"b","explanation":"The amplitude of the action potential remains constant along the axon due to regenerative propagation.","kind":"recall","origin":"ai"},{"id":"action-potential-propagation-refractory~ai-2","moduleId":"action-potential-propagation-refractory","stem":"During which period is it impossible to generate a second action potential, regardless of stimulus strength?","options":[{"id":"a","text":"Relative refractory period"},{"id":"b","text":"Absolute refractory period"},{"id":"c","text":"Resting membrane potential"},{"id":"d","text":"Threshold potential"}],"answerId":"b","explanation":"During the absolute refractory period, voltage-gated Na⁺ channels are inactivated, preventing any new action potential.","kind":"recall","origin":"ai"},{"id":"action-potential-propagation-refractory~ai-3","moduleId":"action-potential-propagation-refractory","stem":"What physiological property allows myelinated axons to conduct action potentials faster than unmyelinated axons?","options":[{"id":"a","text":"Continuous conduction"},{"id":"b","text":"Saltatory conduction"},{"id":"c","text":"Increased ion channel density"},{"id":"d","text":"Higher resting membrane potential"}],"answerId":"b","explanation":"Myelinated axons utilize saltatory conduction, where action potentials jump between nodes of Ranvier, increasing conduction speed.","kind":"mechanism","origin":"ai"},{"id":"action-potential-propagation-refractory~ai-4","moduleId":"action-potential-propagation-refractory","stem":"Why does the action potential travel in one direction along an axon?","options":[{"id":"a","text":"The axon is wider at one end"},{"id":"b","text":"The membrane ahead is always depolarized"},{"id":"c","text":"The region behind the impulse is refractory"},{"id":"d","text":"The stimulus is always stronger in one direction"}],"answerId":"c","explanation":"The action potential travels one way because the area just behind it is refractory, preventing backward propagation.","kind":"trap","origin":"ai"},{"id":"action-potential-propagation-refractory~ai-5","moduleId":"action-potential-propagation-refractory","stem":"Which of the following conditions would most likely slow action potential conduction?","options":[{"id":"a","text":"Increased axon diameter"},{"id":"b","text":"Myelination of the axon"},{"id":"c","text":"Demyelination of the axon"},{"id":"d","text":"Increased extracellular potassium concentration"}],"answerId":"c","explanation":"Demyelination, as seen in conditions like multiple sclerosis, disrupts saltatory conduction and slows action potential propagation.","kind":"clinical","origin":"ai"},{"id":"action-potential-propagation-refractory~ai-6","moduleId":"action-potential-propagation-refractory","stem":"How does the mechanism of action potential propagation in neurons relate to cardiac action potentials?","options":[{"id":"a","text":"Both rely on calcium influx"},{"id":"b","text":"Both are initiated by neurotransmitter release"},{"id":"c","text":"Both involve sodium channel inactivation"},{"id":"d","text":"Both propagate through saltatory conduction"}],"answerId":"c","explanation":"Both neuronal and cardiac action potentials involve sodium channel inactivation during the refractory periods, affecting excitability.","kind":"integration","linkedModuleIds":["cardiac-action-potential"],"origin":"ai"},{"id":"action-potential-propagation-refractory~ai-7","moduleId":"action-potential-propagation-refractory","stem":"What is the relationship between action potentials in neurons and graded potentials?","options":[{"id":"a","text":"Graded potentials are always larger"},{"id":"b","text":"Action potentials can be graded"},{"id":"c","text":"Graded potentials can summate to trigger action potentials"},{"id":"d","text":"Action potentials do not involve ion channels"}],"answerId":"c","explanation":"Graded potentials can summate and reach threshold to trigger an action potential, while action potentials are all-or-nothing events.","kind":"integration","linkedModuleIds":["graded-potentials-cable-properties"],"origin":"ai"}],"cell-signaling-modes-receptors":[{"id":"cell-signaling-modes-receptors~ai-0","moduleId":"cell-signaling-modes-receptors","stem":"Which type of signaling involves hormones traveling through the bloodstream to distant target organs?","options":[{"id":"a","text":"Paracrine"},{"id":"b","text":"Autocrine"},{"id":"c","text":"Endocrine"},{"id":"d","text":"Synaptic"}],"answerId":"c","explanation":"Endocrine signaling is characterized by hormones being released into the bloodstream to act on distant organs.","kind":"recall","origin":"ai"},{"id":"cell-signaling-modes-receptors~ai-1","moduleId":"cell-signaling-modes-receptors","stem":"What is the primary mechanism of action for insulin when it binds to its receptor?","options":[{"id":"a","text":"Ligand-gated ion channel"},{"id":"b","text":"G-protein-coupled receptor"},{"id":"c","text":"Enzyme-linked receptor"},{"id":"d","text":"Intracellular receptor"}],"answerId":"c","explanation":"Insulin binds to an enzyme-linked receptor, triggering autophosphorylation and a kinase cascade.","kind":"mechanism","origin":"ai"},{"id":"cell-signaling-modes-receptors~ai-2","moduleId":"cell-signaling-modes-receptors","stem":"Which receptor type is primarily involved in the rapid opening of ion channels in response to neurotransmitters?","options":[{"id":"a","text":"G-protein-coupled receptor"},{"id":"b","text":"Enzyme-linked receptor"},{"id":"c","text":"Ligand-gated ion channel"},{"id":"d","text":"Intracellular receptor"}],"answerId":"c","explanation":"Ligand-gated ion channels open in response to the binding of a ligand, allowing for fast ion flux.","kind":"recall","origin":"ai"},{"id":"cell-signaling-modes-receptors~ai-3","moduleId":"cell-signaling-modes-receptors","stem":"Cortisol primarily acts through which mechanism to exert its effects?","options":[{"id":"a","text":"G-protein-coupled receptor"},{"id":"b","text":"Ligand-gated ion channel"},{"id":"c","text":"Intracellular/nuclear receptor"},{"id":"d","text":"Enzyme-linked receptor"}],"answerId":"c","explanation":"Cortisol is a lipophilic hormone that crosses the cell membrane and binds to intracellular receptors to alter gene transcription.","kind":"mechanism","origin":"ai"},{"id":"cell-signaling-modes-receptors~ai-4","moduleId":"cell-signaling-modes-receptors","stem":"Which of the following statements about steroid hormones is correct?","options":[{"id":"a","text":"They act on cell-surface receptors like peptide hormones."},{"id":"b","text":"They are water-soluble and act quickly."},{"id":"c","text":"They cross the membrane to bind intracellular receptors."},{"id":"d","text":"They have short-lived effects."}],"answerId":"c","explanation":"Steroid hormones are lipophilic and cross the membrane to bind to intracellular receptors, leading to genomic effects.","kind":"trap","origin":"ai"},{"id":"cell-signaling-modes-receptors~ai-5","moduleId":"cell-signaling-modes-receptors","stem":"How does adrenaline primarily exert its effects on target cells?","options":[{"id":"a","text":"By binding to intracellular receptors"},{"id":"b","text":"Through ligand-gated ion channels"},{"id":"c","text":"By activating G-protein-coupled receptors"},{"id":"d","text":"By acting as a paracrine signal"}],"answerId":"c","explanation":"Adrenaline acts through β-adrenergic G-protein-coupled receptors, leading to the activation of second messengers like cAMP.","kind":"mechanism","origin":"ai"},{"id":"cell-signaling-modes-receptors~ai-6","moduleId":"cell-signaling-modes-receptors","stem":"Which type of signaling is most similar to synaptic transmission in terms of proximity of action?","options":[{"id":"a","text":"Endocrine"},{"id":"b","text":"Autocrine"},{"id":"c","text":"Paracrine"},{"id":"d","text":"Juxtacrine"}],"answerId":"c","explanation":"Paracrine signaling involves local diffusion of signals to neighboring cells, similar to synaptic transmission.","kind":"integration","linkedModuleIds":["synaptic-transmission-epsp-ipsp"],"origin":"ai"},{"id":"cell-signaling-modes-receptors~ai-7","moduleId":"cell-signaling-modes-receptors","stem":"Which mechanism is common to both G-protein-coupled receptors and enzyme-linked receptors?","options":[{"id":"a","text":"Direct ion channel opening"},{"id":"b","text":"Activation of second messengers"},{"id":"c","text":"Autophosphorylation"},{"id":"d","text":"Gene transcription regulation"}],"answerId":"b","explanation":"Both G-protein-coupled receptors and enzyme-linked receptors can activate second messengers, although their mechanisms differ.","kind":"integration","linkedModuleIds":["drug-receptor-signal-transduction"],"origin":"ai"}],"synaptic-transmission-epsp-ipsp":[{"id":"synaptic-transmission-epsp-ipsp~ai-0","moduleId":"synaptic-transmission-epsp-ipsp","stem":"Which type of postsynaptic receptor mediates fast, brief responses?","options":[{"id":"a","text":"Ionotropic receptors"},{"id":"b","text":"Metabotropic receptors"},{"id":"c","text":"Nicotinic receptors"},{"id":"d","text":"Muscarinic receptors"}],"answerId":"a","explanation":"Ionotropic receptors are ligand-gated ion channels that open directly, resulting in fast and brief synaptic responses.","kind":"recall","origin":"ai"},{"id":"synaptic-transmission-epsp-ipsp~ai-1","moduleId":"synaptic-transmission-epsp-ipsp","stem":"What is the primary mechanism by which EPSPs are generated?","options":[{"id":"a","text":"Opening Na⁺ channels"},{"id":"b","text":"Opening K⁺ channels"},{"id":"c","text":"Closing Cl⁻ channels"},{"id":"d","text":"Inhibition of GABA receptors"}],"answerId":"a","explanation":"EPSPs are generated by the opening of Na⁺ channels, leading to depolarization of the postsynaptic neuron.","kind":"mechanism","origin":"ai"},{"id":"synaptic-transmission-epsp-ipsp~ai-2","moduleId":"synaptic-transmission-epsp-ipsp","stem":"Which statement correctly describes the nature of EPSPs and IPSPs?","options":[{"id":"a","text":"They are all-or-none potentials."},{"id":"b","text":"They are graded potentials that summate."},{"id":"c","text":"They always lead to action potentials."},{"id":"d","text":"They do not decay with distance."}],"answerId":"b","explanation":"EPSPs and IPSPs are graded potentials that can summate, unlike action potentials which are all-or-none events.","kind":"trap","origin":"ai"},{"id":"synaptic-transmission-epsp-ipsp~ai-3","moduleId":"synaptic-transmission-epsp-ipsp","stem":"What is the effect of benzodiazepines on GABA-A receptors?","options":[{"id":"a","text":"Decrease Cl⁻ influx"},{"id":"b","text":"Increase Cl⁻ influx"},{"id":"c","text":"Block GABA binding"},{"id":"d","text":"Inhibit IPSPs"}],"answerId":"b","explanation":"Benzodiazepines enhance the effect of GABA-A receptors, increasing Cl⁻ influx and leading to greater inhibitory postsynaptic potentials (IPSPs).","kind":"recall","origin":"ai"},{"id":"synaptic-transmission-epsp-ipsp~ai-4","moduleId":"synaptic-transmission-epsp-ipsp","stem":"In spatial summation, how do EPSPs contribute to action potential generation?","options":[{"id":"a","text":"They cancel each other out."},{"id":"b","text":"They add together from multiple synapses."},{"id":"c","text":"They occur at a single synapse."},{"id":"d","text":"They inhibit action potentials."}],"answerId":"b","explanation":"In spatial summation, multiple EPSPs from different synapses add together to potentially reach the threshold for an action potential.","kind":"clinical","origin":"ai"},{"id":"synaptic-transmission-epsp-ipsp~ai-5","moduleId":"synaptic-transmission-epsp-ipsp","stem":"How does the balance of EPSPs and IPSPs affect neuronal firing?","options":[{"id":"a","text":"EPSPs always dominate."},{"id":"b","text":"IPSPs can veto EPSPs."},{"id":"c","text":"They are independent of each other."},{"id":"d","text":"Only EPSPs can generate action potentials."}],"answerId":"b","explanation":"The balance of EPSPs and IPSPs determines whether the neuron fires; IPSPs can inhibit the effect of EPSPs.","kind":"clinical","origin":"ai"},{"id":"synaptic-transmission-epsp-ipsp~ai-6","moduleId":"synaptic-transmission-epsp-ipsp","stem":"What role do metabotropic receptors play in synaptic transmission?","options":[{"id":"a","text":"They mediate fast responses."},{"id":"b","text":"They activate second messengers."},{"id":"c","text":"They are always excitatory."},{"id":"d","text":"They only respond to glutamate."}],"answerId":"b","explanation":"Metabotropic receptors act via G proteins and second messengers, leading to slower and modulatory responses in synaptic transmission.","kind":"integration","linkedModuleIds":["cns-neurotransmission-systems"],"origin":"ai"},{"id":"synaptic-transmission-epsp-ipsp~ai-7","moduleId":"synaptic-transmission-epsp-ipsp","stem":"How does the concept of graded potentials relate to action potential generation?","options":[{"id":"a","text":"Graded potentials are always action potentials."},{"id":"b","text":"Graded potentials summate to reach threshold."},{"id":"c","text":"Graded potentials do not influence action potentials."},{"id":"d","text":"Graded potentials are fixed in amplitude."}],"answerId":"b","explanation":"Graded potentials, such as EPSPs and IPSPs, summate to reach the threshold needed for action potential generation.","kind":"integration","linkedModuleIds":["graded-potentials-cable-properties"],"origin":"ai"}],"resting-membrane-potential-nernst":[{"id":"resting-membrane-potential-nernst~ai-0","moduleId":"resting-membrane-potential-nernst","stem":"What is the typical resting membrane potential (RMP) in neurons?","options":[{"id":"a","text":"+60 mV"},{"id":"b","text":"-70 mV"},{"id":"c","text":"-90 mV"},{"id":"d","text":"-50 mV"}],"answerId":"b","explanation":"The typical resting membrane potential in neurons is approximately -70 mV.","kind":"recall","origin":"ai"},{"id":"resting-membrane-potential-nernst~ai-1","moduleId":"resting-membrane-potential-nernst","stem":"Which ion's concentration gradient primarily determines the resting membrane potential?","options":[{"id":"a","text":"Na⁺"},{"id":"b","text":"K⁺"},{"id":"c","text":"Cl⁻"},{"id":"d","text":"Ca²⁺"}],"answerId":"b","explanation":"The resting membrane potential is primarily determined by the concentration gradient of K⁺ due to its high permeability at rest.","kind":"recall","origin":"ai"},{"id":"resting-membrane-potential-nernst~ai-2","moduleId":"resting-membrane-potential-nernst","stem":"What happens to the resting membrane potential during hyperkalaemia?","options":[{"id":"a","text":"It becomes more negative"},{"id":"b","text":"It remains unchanged"},{"id":"c","text":"It depolarizes"},{"id":"d","text":"It hyperpolarizes"}],"answerId":"c","explanation":"Hyperkalaemia increases extracellular K⁺, making E_K less negative and thus depolarizing the resting membrane potential.","kind":"mechanism","origin":"ai"},{"id":"resting-membrane-potential-nernst~ai-3","moduleId":"resting-membrane-potential-nernst","stem":"Which of the following best describes the Nernst equation?","options":[{"id":"a","text":"Calculates the total membrane potential"},{"id":"b","text":"Calculates the equilibrium potential for an ion"},{"id":"c","text":"Determines the resting membrane potential"},{"id":"d","text":"Measures ion permeability"}],"answerId":"b","explanation":"The Nernst equation calculates the equilibrium potential for a specific ion based on its concentration gradient.","kind":"recall","origin":"ai"},{"id":"resting-membrane-potential-nernst~ai-4","moduleId":"resting-membrane-potential-nernst","stem":"In a resting neuron, which ion has the greatest driving force for movement across the membrane?","options":[{"id":"a","text":"K⁺"},{"id":"b","text":"Na⁺"},{"id":"c","text":"Cl⁻"},{"id":"d","text":"Ca²⁺"}],"answerId":"b","explanation":"At rest, Na⁺ has a strong inward driving force because the membrane potential (-70 mV) is far from its equilibrium potential (+60 mV).","kind":"clinical","origin":"ai"},{"id":"resting-membrane-potential-nernst~ai-5","moduleId":"resting-membrane-potential-nernst","stem":"How does the Na⁺/K⁺-ATPase contribute to the resting membrane potential?","options":[{"id":"a","text":"It generates a positive charge inside the cell"},{"id":"b","text":"It maintains ion concentration gradients"},{"id":"c","text":"It allows Na⁺ to flow freely into the cell"},{"id":"d","text":"It directly sets the RMP to +60 mV"}],"answerId":"b","explanation":"The Na⁺/K⁺-ATPase maintains ion concentration gradients, which are crucial for establishing the resting membrane potential.","kind":"mechanism","origin":"ai"},{"id":"resting-membrane-potential-nernst~ai-6","moduleId":"resting-membrane-potential-nernst","stem":"How does the resting membrane potential relate to the action potential generation?","options":[{"id":"a","text":"RMP is irrelevant to action potential"},{"id":"b","text":"RMP must be depolarized to threshold"},{"id":"c","text":"RMP is always positive before action potential"},{"id":"d","text":"RMP prevents action potential generation"}],"answerId":"b","explanation":"The resting membrane potential must be depolarized to reach the threshold for action potential generation, linking it to the module on action potential genesis.","kind":"integration","linkedModuleIds":["action-potential-genesis"],"origin":"ai"},{"id":"resting-membrane-potential-nernst~ai-7","moduleId":"resting-membrane-potential-nernst","stem":"What effect does a decrease in extracellular K⁺ have on the resting membrane potential?","options":[{"id":"a","text":"It depolarizes the cell"},{"id":"b","text":"It hyperpolarizes the cell"},{"id":"c","text":"It has no effect"},{"id":"d","text":"It increases Na⁺ permeability"}],"answerId":"b","explanation":"Decreasing extracellular K⁺ makes E_K more negative, leading to hyperpolarization of the resting membrane potential.","kind":"integration","linkedModuleIds":["body-fluid-compartments"],"origin":"ai"}],"neuromuscular-junction-transmission":[{"id":"neuromuscular-junction-transmission~ai-0","moduleId":"neuromuscular-junction-transmission","stem":"What is the primary neurotransmitter at the neuromuscular junction?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"Serotonin"},{"id":"c","text":"Acetylcholine"},{"id":"d","text":"Norepinephrine"}],"answerId":"c","explanation":"Acetylcholine is the neurotransmitter that mediates transmission at the neuromuscular junction.","kind":"recall","origin":"ai"},{"id":"neuromuscular-junction-transmission~ai-1","moduleId":"neuromuscular-junction-transmission","stem":"Which mechanism is responsible for the release of acetylcholine at the neuromuscular junction?","options":[{"id":"a","text":"Increased Na⁺ influx"},{"id":"b","text":"Increased K⁺ efflux"},{"id":"c","text":"Increased Ca²⁺ influx"},{"id":"d","text":"Increased Cl⁻ influx"}],"answerId":"c","explanation":"The influx of Ca²⁺ into the presynaptic terminal triggers the release of acetylcholine.","kind":"mechanism","origin":"ai"},{"id":"neuromuscular-junction-transmission~ai-2","moduleId":"neuromuscular-junction-transmission","stem":"A patient presents with fatigable weakness that improves with the administration of an anticholinesterase. What condition is most likely?","options":[{"id":"a","text":"Lambert-Eaton syndrome"},{"id":"b","text":"Myasthenia gravis"},{"id":"c","text":"Botulism"},{"id":"d","text":"Multiple sclerosis"}],"answerId":"b","explanation":"This presentation is characteristic of Myasthenia gravis, where autoantibodies target nicotinic acetylcholine receptors.","kind":"clinical","origin":"ai"},{"id":"neuromuscular-junction-transmission~ai-3","moduleId":"neuromuscular-junction-transmission","stem":"Which of the following best explains the high reliability of neuromuscular junction transmission?","options":[{"id":"a","text":"Summation of multiple inputs"},{"id":"b","text":"Large end-plate potential"},{"id":"c","text":"Inhibition of acetylcholinesterase"},{"id":"d","text":"Presence of myelin sheath"}],"answerId":"b","explanation":"The large end-plate potential at the NMJ ensures that a single nerve impulse reliably triggers a muscle action potential.","kind":"trap","origin":"ai"},{"id":"neuromuscular-junction-transmission~ai-4","moduleId":"neuromuscular-junction-transmission","stem":"What is the effect of botulinum toxin at the neuromuscular junction?","options":[{"id":"a","text":"Inhibition of acetylcholinesterase"},{"id":"b","text":"Blockade of nicotinic receptors"},{"id":"c","text":"Inhibition of ACh release"},{"id":"d","text":"Increased ACh release"}],"answerId":"c","explanation":"Botulinum toxin inhibits the release of acetylcholine, leading to flaccid paralysis.","kind":"mechanism","origin":"ai"},{"id":"neuromuscular-junction-transmission~ai-5","moduleId":"neuromuscular-junction-transmission","stem":"How does Lambert-Eaton syndrome differ from Myasthenia gravis in terms of muscle weakness?","options":[{"id":"a","text":"Weakness improves with rest"},{"id":"b","text":"Weakness improves with use"},{"id":"c","text":"Weakness is constant"},{"id":"d","text":"Weakness is associated with sensory loss"}],"answerId":"b","explanation":"In Lambert-Eaton syndrome, muscle weakness typically improves with repeated use, unlike Myasthenia gravis.","kind":"clinical","origin":"ai"},{"id":"neuromuscular-junction-transmission~ai-6","moduleId":"neuromuscular-junction-transmission","stem":"Which ion channel's dysfunction is primarily implicated in Lambert-Eaton syndrome?","options":[{"id":"a","text":"Voltage-gated sodium channels"},{"id":"b","text":"Voltage-gated potassium channels"},{"id":"c","text":"Voltage-gated calcium channels"},{"id":"d","text":"Ligand-gated ion channels"}],"answerId":"c","explanation":"Lambert-Eaton syndrome is associated with antibodies against presynaptic voltage-gated calcium channels, impairing acetylcholine release.","kind":"integration","linkedModuleIds":["metabolic-toxic-nmj-myopathy"],"origin":"ai"},{"id":"neuromuscular-junction-transmission~ai-7","moduleId":"neuromuscular-junction-transmission","stem":"What is the consequence of organophosphate exposure at the neuromuscular junction?","options":[{"id":"a","text":"Increased ACh release"},{"id":"b","text":"Decreased AChE activity"},{"id":"c","text":"Blockade of nicotinic receptors"},{"id":"d","text":"Increased calcium influx"}],"answerId":"b","explanation":"Organophosphates inhibit acetylcholinesterase, leading to an accumulation of acetylcholine at the neuromuscular junction.","kind":"clinical","origin":"ai"}],"synaptic-plasticity-ltp":[{"id":"synaptic-plasticity-ltp~ai-0","moduleId":"synaptic-plasticity-ltp","stem":"What is the primary function of the NMDA receptor in synaptic plasticity?","options":[{"id":"a","text":"It mediates long-term depression."},{"id":"b","text":"It serves as a coincidence detector."},{"id":"c","text":"It exclusively binds to GABA."},{"id":"d","text":"It directly triggers protein synthesis."}],"answerId":"b","explanation":"The NMDA receptor acts as a coincidence detector, requiring both glutamate binding and postsynaptic depolarization to function.","kind":"recall","origin":"ai"},{"id":"synaptic-plasticity-ltp~ai-1","moduleId":"synaptic-plasticity-ltp","stem":"Which ion influx is critical for the induction of long-term potentiation (LTP)?","options":[{"id":"a","text":"Na⁺"},{"id":"b","text":"K⁺"},{"id":"c","text":"Ca²⁺"},{"id":"d","text":"Cl⁻"}],"answerId":"c","explanation":"Calcium ions (Ca²⁺) enter the postsynaptic neuron through the NMDA receptor, triggering the signaling cascade necessary for LTP.","kind":"mechanism","origin":"ai"},{"id":"synaptic-plasticity-ltp~ai-2","moduleId":"synaptic-plasticity-ltp","stem":"What is the role of CaMKII in early LTP?","options":[{"id":"a","text":"It activates CREB for gene transcription."},{"id":"b","text":"It facilitates AMPA receptor insertion."},{"id":"c","text":"It blocks NMDA receptor activity."},{"id":"d","text":"It decreases synaptic strength."}],"answerId":"b","explanation":"CaMKII is activated by Ca²⁺ influx and promotes the insertion of AMPA receptors into the postsynaptic membrane, enhancing synaptic strength.","kind":"mechanism","origin":"ai"},{"id":"synaptic-plasticity-ltp~ai-3","moduleId":"synaptic-plasticity-ltp","stem":"Which of the following findings indicates a failure in LTP associated with Alzheimer's disease?","options":[{"id":"a","text":"Increased AMPA receptor density"},{"id":"b","text":"Enhanced CREB activation"},{"id":"c","text":"Accumulation of amyloid-β"},{"id":"d","text":"Elevated Ca²⁺ levels in the postsynaptic neuron"}],"answerId":"c","explanation":"Amyloid-β accumulation disrupts glutamate handling, impairing LTP and contributing to memory loss in Alzheimer's disease.","kind":"recall","origin":"ai"},{"id":"synaptic-plasticity-ltp~ai-4","moduleId":"synaptic-plasticity-ltp","stem":"Why does the NMDA receptor require both glutamate and depolarization to open?","options":[{"id":"a","text":"It opens immediately upon glutamate binding."},{"id":"b","text":"It is blocked by Mg²⁺ until depolarization occurs."},{"id":"c","text":"It is only activated by GABA."},{"id":"d","text":"It does not contribute to synaptic plasticity."}],"answerId":"b","explanation":"The NMDA receptor is blocked by Mg²⁺ at rest; depolarization is necessary to relieve this block, allowing Ca²⁺ to enter and trigger LTP.","kind":"trap","origin":"ai"},{"id":"synaptic-plasticity-ltp~ai-5","moduleId":"synaptic-plasticity-ltp","stem":"How does CREB contribute to late LTP?","options":[{"id":"a","text":"It enhances AMPA receptor conductance."},{"id":"b","text":"It initiates new protein synthesis."},{"id":"c","text":"It directly binds to NMDA receptors."},{"id":"d","text":"It decreases synaptic plasticity."}],"answerId":"b","explanation":"CREB activation leads to new gene transcription and protein synthesis, which are essential for maintaining long-term potentiation.","kind":"mechanism","origin":"ai"},{"id":"synaptic-plasticity-ltp~ai-6","moduleId":"synaptic-plasticity-ltp","stem":"How does synaptic plasticity relate to learning and memory?","options":[{"id":"a","text":"It decreases synaptic strength during learning."},{"id":"b","text":"It enhances synaptic strength through LTP."},{"id":"c","text":"It solely relies on short-term changes."},{"id":"d","text":"It is independent of neurotransmitter systems."}],"answerId":"b","explanation":"Synaptic plasticity, particularly through mechanisms like LTP, strengthens synapses, which is fundamental for learning and memory processes.","kind":"integration","linkedModuleIds":["synaptic-plasticity-learning"],"origin":"ai"},{"id":"synaptic-plasticity-ltp~ai-7","moduleId":"synaptic-plasticity-ltp","stem":"Which mechanism links synaptic plasticity to neurotransmitter systems?","options":[{"id":"a","text":"Increased GABA release during LTP."},{"id":"b","text":"Glutamate's role in activating NMDA receptors."},{"id":"c","text":"Dopamine's effect on AMPA receptor trafficking."},{"id":"d","text":"Serotonin's role in synaptic depression."}],"answerId":"b","explanation":"Glutamate is the primary neurotransmitter that activates NMDA receptors, which are crucial for the induction of synaptic plasticity.","kind":"integration","linkedModuleIds":["neurotransmitter-systems-catalog"],"origin":"ai"}],"ion-channels-structure-gating":[{"id":"ion-channels-structure-gating~ai-0","moduleId":"ion-channels-structure-gating","stem":"What is the primary reason for the absolute refractory period in neurons?","options":[{"id":"a","text":"The membrane potential is too high"},{"id":"b","text":"Voltage-gated Na⁺ channels are inactivated"},{"id":"c","text":"K⁺ channels are open"},{"id":"d","text":"The neuron is hyperpolarised"}],"answerId":"b","explanation":"The absolute refractory period occurs because voltage-gated Na⁺ channels are inactivated and cannot reopen until the membrane repolarises.","kind":"trap","origin":"ai"},{"id":"ion-channels-structure-gating~ai-1","moduleId":"ion-channels-structure-gating","stem":"Which type of ion channel is primarily responsible for the rapid depolarisation phase of the action potential?","options":[{"id":"a","text":"Voltage-gated K⁺ channels"},{"id":"b","text":"Ligand-gated Na⁺ channels"},{"id":"c","text":"Voltage-gated Na⁺ channels"},{"id":"d","text":"Leak channels"}],"answerId":"c","explanation":"Voltage-gated Na⁺ channels open rapidly during depolarisation, allowing Na⁺ influx and generating the action potential.","kind":"recall","origin":"ai"},{"id":"ion-channels-structure-gating~ai-2","moduleId":"ion-channels-structure-gating","stem":"What mechanism underlies the delayed repolarisation following the action potential?","options":[{"id":"a","text":"Inactivation of Na⁺ channels"},{"id":"b","text":"Delayed opening of K⁺ channels"},{"id":"c","text":"Closure of leak channels"},{"id":"d","text":"Increased Na⁺ permeability"}],"answerId":"b","explanation":"The delayed repolarisation is due to the slower opening of voltage-gated K⁺ channels, which allows K⁺ efflux.","kind":"mechanism","origin":"ai"},{"id":"ion-channels-structure-gating~ai-3","moduleId":"ion-channels-structure-gating","stem":"Which clinical finding indicates that a neuron cannot immediately re-fire after an action potential?","options":[{"id":"a","text":"Increased Na⁺ conductance"},{"id":"b","text":"Absolute refractory period"},{"id":"c","text":"Hyperpolarisation"},{"id":"d","text":"Increased K⁺ conductance"}],"answerId":"b","explanation":"The absolute refractory period signifies that the neuron cannot generate another action potential due to inactivated Na⁺ channels.","kind":"recall","origin":"ai"},{"id":"ion-channels-structure-gating~ai-4","moduleId":"ion-channels-structure-gating","stem":"A patient presents with inherited long-QT syndrome. Which underlying mechanism is likely responsible?","options":[{"id":"a","text":"Increased Na⁺ channel activity"},{"id":"b","text":"K⁺ channel dysfunction"},{"id":"c","text":"Increased Ca²⁺ influx"},{"id":"d","text":"Increased leak channel activity"}],"answerId":"b","explanation":"Inherited long-QT syndrome is often due to channelopathies affecting K⁺ channels, leading to prolonged repolarisation.","kind":"clinical","origin":"ai"},{"id":"ion-channels-structure-gating~ai-5","moduleId":"ion-channels-structure-gating","stem":"How does the mechanism of local anesthetics relate to ion channels?","options":[{"id":"a","text":"They block K⁺ channels"},{"id":"b","text":"They enhance Na⁺ channel activity"},{"id":"c","text":"They block Na⁺ channels"},{"id":"d","text":"They open ligand-gated channels"}],"answerId":"c","explanation":"Local anesthetics block voltage-gated Na⁺ channels, preventing action potential propagation and nerve conduction.","kind":"clinical","origin":"ai"},{"id":"ion-channels-structure-gating~ai-6","moduleId":"ion-channels-structure-gating","stem":"How does the action potential propagation relate to the resting membrane potential?","options":[{"id":"a","text":"Resting potential is irrelevant"},{"id":"b","text":"Resting potential sets the threshold"},{"id":"c","text":"Resting potential affects Na⁺ channel inactivation"},{"id":"d","text":"Resting potential determines K⁺ channel activation"}],"answerId":"b","explanation":"The resting membrane potential establishes the baseline for depolarisation, which is essential for reaching the action potential threshold.","kind":"integration","linkedModuleIds":["resting-membrane-potential-nernst"],"origin":"ai"},{"id":"ion-channels-structure-gating~ai-7","moduleId":"ion-channels-structure-gating","stem":"What is the relationship between action potential generation and graded potentials?","options":[{"id":"a","text":"Graded potentials are always action potentials"},{"id":"b","text":"Graded potentials can summate to trigger action potentials"},{"id":"c","text":"Action potentials inhibit graded potentials"},{"id":"d","text":"Graded potentials are irrelevant to action potentials"}],"answerId":"b","explanation":"Graded potentials can summate and, if they reach the threshold, trigger an action potential.","kind":"integration","linkedModuleIds":["graded-potentials-cable-properties"],"origin":"ai"}],"cellular-aging-theories":[{"id":"cellular-aging-theories~ai-0","moduleId":"cellular-aging-theories","stem":"What is the primary mechanism by which oxidative stress contributes to aging?","options":[{"id":"a","text":"Increased telomere length"},{"id":"b","text":"Accumulation of reactive oxygen species"},{"id":"c","text":"Enhanced cellular division"},{"id":"d","text":"Decreased mitochondrial function"}],"answerId":"b","explanation":"Oxidative stress leads to the accumulation of reactive oxygen species (ROS), which damage cellular components and contribute to aging.","kind":"mechanism","origin":"ai"},{"id":"cellular-aging-theories~ai-1","moduleId":"cellular-aging-theories","stem":"Which of the following findings is indicative of cellular senescence?","options":[{"id":"a","text":"Increased telomerase activity"},{"id":"b","text":"Irreversible growth arrest with active metabolism"},{"id":"c","text":"Enhanced cell division"},{"id":"d","text":"Decreased inflammatory factor secretion"}],"answerId":"b","explanation":"Cellular senescence is characterized by irreversible growth arrest while remaining metabolically active and secreting inflammatory factors.","kind":"recall","origin":"ai"},{"id":"cellular-aging-theories~ai-2","moduleId":"cellular-aging-theories","stem":"How does caloric restriction extend lifespan according to aging theories?","options":[{"id":"a","text":"Increases telomerase activity"},{"id":"b","text":"Reduces metabolic rate and oxidative stress"},{"id":"c","text":"Enhances cell division"},{"id":"d","text":"Decreases DNA repair mechanisms"}],"answerId":"b","explanation":"Caloric restriction is believed to extend lifespan by reducing metabolic rate and oxidative stress, thereby decreasing damage accumulation.","kind":"mechanism","origin":"ai"},{"id":"cellular-aging-theories~ai-3","moduleId":"cellular-aging-theories","stem":"What is the consequence of critically short telomeres in somatic cells?","options":[{"id":"a","text":"Increased cell division"},{"id":"b","text":"Cellular senescence"},{"id":"c","text":"Enhanced mitochondrial function"},{"id":"d","text":"Decreased oxidative stress"}],"answerId":"b","explanation":"Critically short telomeres trigger cellular senescence, preventing further cell division.","kind":"recall","origin":"ai"},{"id":"cellular-aging-theories~ai-4","moduleId":"cellular-aging-theories","stem":"Which of the following statements correctly distinguishes senescence from apoptosis?","options":[{"id":"a","text":"Senescent cells are dead"},{"id":"b","text":"Senescent cells can divide"},{"id":"c","text":"Apoptotic cells are metabolically active"},{"id":"d","text":"Senescent cells are alive but cannot divide"}],"answerId":"d","explanation":"Senescent cells are alive but permanently unable to divide, while apoptotic cells undergo programmed cell death.","kind":"trap","origin":"ai"},{"id":"cellular-aging-theories~ai-5","moduleId":"cellular-aging-theories","stem":"Which mechanism links cellular aging to free radical damage?","options":[{"id":"a","text":"Telomere shortening"},{"id":"b","text":"Increased apoptosis"},{"id":"c","text":"Accumulation of ROS"},{"id":"d","text":"Enhanced nutrient sensing"}],"answerId":"c","explanation":"The accumulation of reactive oxygen species (ROS) leads to cellular damage, which is a key factor in the aging process.","kind":"mechanism","origin":"ai"},{"id":"cellular-aging-theories~ai-6","moduleId":"cellular-aging-theories","stem":"How does telomere shortening relate to the process of cellular aging?","options":[{"id":"a","text":"It enhances cellular metabolism"},{"id":"b","text":"It limits the number of cell divisions"},{"id":"c","text":"It increases oxidative stress"},{"id":"d","text":"It activates apoptotic pathways"}],"answerId":"b","explanation":"Telomere shortening limits the number of cell divisions, contributing to cellular aging and senescence.","kind":"integration","linkedModuleIds":["eukaryotic-replication-telomeres"],"origin":"ai"},{"id":"cellular-aging-theories~ai-7","moduleId":"cellular-aging-theories","stem":"What role do reactive oxygen species play in the context of cellular aging?","options":[{"id":"a","text":"They promote telomerase activity"},{"id":"b","text":"They cause damage to cellular components"},{"id":"c","text":"They enhance cell proliferation"},{"id":"d","text":"They prevent senescence"}],"answerId":"b","explanation":"Reactive oxygen species cause damage to DNA, proteins, and lipids, contributing to the aging process.","kind":"integration","linkedModuleIds":["cell-injury-free-radicals"],"origin":"ai"}],"autonomic-neurotransmitters-receptors":[{"id":"autonomic-neurotransmitters-receptors~ai-0","moduleId":"autonomic-neurotransmitters-receptors","stem":"What neurotransmitter is released by all preganglionic autonomic fibers?","options":[{"id":"a","text":"Norepinephrine"},{"id":"b","text":"Acetylcholine"},{"id":"c","text":"Dopamine"},{"id":"d","text":"Serotonin"}],"answerId":"b","explanation":"All preganglionic autonomic fibers release acetylcholine onto nicotinic receptors in the ganglia.","kind":"recall","origin":"ai"},{"id":"autonomic-neurotransmitters-receptors~ai-1","moduleId":"autonomic-neurotransmitters-receptors","stem":"Which receptor type is activated by acetylcholine in the parasympathetic postganglionic pathway?","options":[{"id":"a","text":"Nicotinic"},{"id":"b","text":"Muscarinic"},{"id":"c","text":"Adrenergic"},{"id":"d","text":"Dopaminergic"}],"answerId":"b","explanation":"Parasympathetic postganglionic fibers release acetylcholine onto muscarinic receptors.","kind":"recall","origin":"ai"},{"id":"autonomic-neurotransmitters-receptors~ai-2","moduleId":"autonomic-neurotransmitters-receptors","stem":"What is the mechanism of action of β1-blockers?","options":[{"id":"a","text":"Inhibit muscarinic receptors"},{"id":"b","text":"Block adrenergic β1 receptors"},{"id":"c","text":"Stimulate adrenergic α1 receptors"},{"id":"d","text":"Enhance cAMP production"}],"answerId":"b","explanation":"β1-blockers specifically block adrenergic β1 receptors, reducing heart rate and force of contraction.","kind":"mechanism","origin":"ai"},{"id":"autonomic-neurotransmitters-receptors~ai-3","moduleId":"autonomic-neurotransmitters-receptors","stem":"What clinical finding would indicate the action of atropine?","options":[{"id":"a","text":"Increased sweating"},{"id":"b","text":"Decreased heart rate"},{"id":"c","text":"Increased heart rate"},{"id":"d","text":"Bronchoconstriction"}],"answerId":"c","explanation":"Atropine is a muscarinic antagonist that raises heart rate by blocking parasympathetic effects.","kind":"recall","origin":"ai"},{"id":"autonomic-neurotransmitters-receptors~ai-4","moduleId":"autonomic-neurotransmitters-receptors","stem":"Which of the following statements about sympathetic postganglionic fibers is true?","options":[{"id":"a","text":"All release norepinephrine"},{"id":"b","text":"Some release acetylcholine"},{"id":"c","text":"All are cholinergic"},{"id":"d","text":"None release dopamine"}],"answerId":"b","explanation":"Sympathetic fibers to sweat glands are an exception; they release acetylcholine onto muscarinic receptors.","kind":"trap","origin":"ai"},{"id":"autonomic-neurotransmitters-receptors~ai-5","moduleId":"autonomic-neurotransmitters-receptors","stem":"How does salbutamol exert its therapeutic effect?","options":[{"id":"a","text":"Inhibits β1 receptors"},{"id":"b","text":"Stimulates β2 receptors"},{"id":"c","text":"Blocks muscarinic receptors"},{"id":"d","text":"Increases norepinephrine release"}],"answerId":"b","explanation":"Salbutamol is a β2-agonist that dilates bronchi by relaxing bronchial smooth muscle.","kind":"mechanism","origin":"ai"},{"id":"autonomic-neurotransmitters-receptors~ai-6","moduleId":"autonomic-neurotransmitters-receptors","stem":"How does the enteric nervous system interact with the autonomic nervous system?","options":[{"id":"a","text":"Only sympathetic fibers innervate the GI tract"},{"id":"b","text":"It operates independently of the autonomic system"},{"id":"c","text":"It receives both sympathetic and parasympathetic input"},{"id":"d","text":"It only uses adrenergic signaling"}],"answerId":"c","explanation":"The enteric nervous system receives both sympathetic and parasympathetic input, coordinating GI reflexes.","kind":"integration","linkedModuleIds":["enteric-autonomic-reflex-control"],"origin":"ai"},{"id":"autonomic-neurotransmitters-receptors~ai-7","moduleId":"autonomic-neurotransmitters-receptors","stem":"What is the role of catecholamines released from the adrenal medulla in the autonomic response?","options":[{"id":"a","text":"Inhibit sympathetic activity"},{"id":"b","text":"Enhance parasympathetic activity"},{"id":"c","text":"Act as hormones to amplify sympathetic response"},{"id":"d","text":"Block adrenergic receptors"}],"answerId":"c","explanation":"Catecholamines like epinephrine enhance the sympathetic response as hormones, increasing heart rate and blood flow.","kind":"integration","linkedModuleIds":["hen1-adrenal-catecholamines"],"origin":"ai"}],"reflex-types-clinical-testing":[{"id":"reflex-types-clinical-testing~ai-0","moduleId":"reflex-types-clinical-testing","stem":"What type of reflex involves a single synapse and is exemplified by the knee-jerk response?","options":[{"id":"a","text":"Monosynaptic reflex"},{"id":"b","text":"Polysynaptic reflex"},{"id":"c","text":"Autonomic reflex"},{"id":"d","text":"Innate reflex"}],"answerId":"a","explanation":"Monosynaptic reflexes have a single synapse and include deep tendon reflexes like the knee-jerk.","kind":"recall","origin":"ai"},{"id":"reflex-types-clinical-testing~ai-1","moduleId":"reflex-types-clinical-testing","stem":"Which clinical finding is indicative of an upper motor neuron lesion?","options":[{"id":"a","text":"Absent reflexes"},{"id":"b","text":"Flaccid muscle tone"},{"id":"c","text":"Brisk reflexes with clonus"},{"id":"d","text":"Fasciculations"}],"answerId":"c","explanation":"Brisk reflexes with clonus indicate an upper motor neuron lesion, while absent reflexes and flaccid tone indicate lower motor neuron lesions.","kind":"recall","origin":"ai"},{"id":"reflex-types-clinical-testing~ai-2","moduleId":"reflex-types-clinical-testing","stem":"What is the primary mechanism behind the flexor withdrawal reflex?","options":[{"id":"a","text":"Monosynaptic reflex arc"},{"id":"b","text":"Polysynaptic reflex arc"},{"id":"c","text":"Corticospinal tract activation"},{"id":"d","text":"Autonomic nervous system response"}],"answerId":"b","explanation":"The flexor withdrawal reflex is a polysynaptic reflex involving interneurons that facilitate the withdrawal response.","kind":"mechanism","origin":"ai"},{"id":"reflex-types-clinical-testing~ai-3","moduleId":"reflex-types-clinical-testing","stem":"A patient presents with weakness and absent reflexes in the lower extremities. What is the most likely diagnosis?","options":[{"id":"a","text":"Upper motor neuron lesion"},{"id":"b","text":"Lower motor neuron lesion"},{"id":"c","text":"Peripheral neuropathy"},{"id":"d","text":"Spinal cord injury"}],"answerId":"b","explanation":"Absent reflexes with weakness and flaccidity indicate a lower motor neuron lesion.","kind":"clinical","origin":"ai"},{"id":"reflex-types-clinical-testing~ai-4","moduleId":"reflex-types-clinical-testing","stem":"What reflex finding would be expected in an adult with a pathological Babinski sign?","options":[{"id":"a","text":"Absent ankle jerk"},{"id":"b","text":"Up-going great toe"},{"id":"c","text":"Brisk reflexes"},{"id":"d","text":"Flaccid muscle tone"}],"answerId":"b","explanation":"An up-going great toe (Babinski sign) in an adult indicates a pathological upper motor neuron lesion.","kind":"recall","origin":"ai"},{"id":"reflex-types-clinical-testing~ai-5","moduleId":"reflex-types-clinical-testing","stem":"Which reflex pattern would indicate a lower motor neuron lesion?","options":[{"id":"a","text":"Increased tone and clonus"},{"id":"b","text":"Absent reflexes and flaccidity"},{"id":"c","text":"Withdrawal reflex with crossed extension"},{"id":"d","text":"Brisk reflexes with Babinski sign"}],"answerId":"b","explanation":"Absent reflexes and flaccidity indicate a lower motor neuron lesion, contrasting with increased tone and reflexes seen in upper motor neuron lesions.","kind":"trap","origin":"ai"},{"id":"reflex-types-clinical-testing~ai-6","moduleId":"reflex-types-clinical-testing","stem":"How do muscle spindles contribute to the stretch reflex?","options":[{"id":"a","text":"By detecting muscle tension"},{"id":"b","text":"By detecting muscle length changes"},{"id":"c","text":"By inhibiting motor neuron activity"},{"id":"d","text":"By facilitating polysynaptic reflexes"}],"answerId":"b","explanation":"Muscle spindles detect changes in muscle length, which is crucial for the stretch reflex mechanism.","kind":"integration","linkedModuleIds":["muscle-spindle-golgi-tendon-organ"],"origin":"ai"},{"id":"reflex-types-clinical-testing~ai-7","moduleId":"reflex-types-clinical-testing","stem":"In the context of reflex testing, how does the corticospinal tract influence reflex responses?","options":[{"id":"a","text":"It enhances monosynaptic reflexes"},{"id":"b","text":"It inhibits polysynaptic reflexes"},{"id":"c","text":"It modulates reflex thresholds"},{"id":"d","text":"It has no effect on reflexes"}],"answerId":"c","explanation":"The corticospinal tract modulates reflex thresholds, influencing the overall reflex response.","kind":"integration","linkedModuleIds":["motor-system-corticospinal-control"],"origin":"ai"}],"nmj-structure-transmission":[{"id":"nmj-structure-transmission~ai-0","moduleId":"nmj-structure-transmission","stem":"What type of receptor is found at the neuromuscular junction?","options":[{"id":"a","text":"Muscarinic"},{"id":"b","text":"Nicotinic"},{"id":"c","text":"Adrenergic"},{"id":"d","text":"Dopaminergic"}],"answerId":"b","explanation":"The neuromuscular junction utilizes nicotinic acetylcholine receptors, which are ligand-gated cation channels.","kind":"recall","origin":"ai"},{"id":"nmj-structure-transmission~ai-1","moduleId":"nmj-structure-transmission","stem":"What initiates the release of acetylcholine at the neuromuscular junction?","options":[{"id":"a","text":"Na⁺ influx"},{"id":"b","text":"K⁺ efflux"},{"id":"c","text":"Ca²⁺ influx"},{"id":"d","text":"Cl⁻ influx"}],"answerId":"c","explanation":"The influx of Ca²⁺ through voltage-gated channels triggers the fusion of vesicles containing acetylcholine.","kind":"mechanism","origin":"ai"},{"id":"nmj-structure-transmission~ai-2","moduleId":"nmj-structure-transmission","stem":"Which finding indicates successful transmission at the neuromuscular junction?","options":[{"id":"a","text":"Increased K⁺ levels"},{"id":"b","text":"End-plate potential (EPP)"},{"id":"c","text":"Decreased ACh levels"},{"id":"d","text":"Increased Cl⁻ levels"}],"answerId":"b","explanation":"The end-plate potential (EPP) is a direct indicator of successful transmission at the neuromuscular junction.","kind":"recall","origin":"ai"},{"id":"nmj-structure-transmission~ai-3","moduleId":"nmj-structure-transmission","stem":"In myasthenia gravis, which mechanism contributes to muscle weakness?","options":[{"id":"a","text":"Increased ACh release"},{"id":"b","text":"Decreased nicotinic receptors"},{"id":"c","text":"Increased Ca²⁺ influx"},{"id":"d","text":"Decreased AChE activity"}],"answerId":"b","explanation":"Myasthenia gravis leads to a decrease in nicotinic receptors, impairing neuromuscular transmission.","kind":"trap","origin":"ai"},{"id":"nmj-structure-transmission~ai-4","moduleId":"nmj-structure-transmission","stem":"What is the role of acetylcholinesterase at the neuromuscular junction?","options":[{"id":"a","text":"Facilitates ACh release"},{"id":"b","text":"Hydrolyzes ACh"},{"id":"c","text":"Increases EPP"},{"id":"d","text":"Inhibits Ca²⁺ influx"}],"answerId":"b","explanation":"Acetylcholinesterase hydrolyzes acetylcholine in the synaptic cleft, terminating the signal.","kind":"mechanism","origin":"ai"},{"id":"nmj-structure-transmission~ai-5","moduleId":"nmj-structure-transmission","stem":"How does the safety factor at the neuromuscular junction ensure reliable transmission?","options":[{"id":"a","text":"Excess Ca²⁺ influx"},{"id":"b","text":"Excess ACh release"},{"id":"c","text":"Increased receptor density"},{"id":"d","text":"Decreased AChE activity"}],"answerId":"b","explanation":"The safety factor is due to the release of more ACh than needed to exceed the threshold for muscle action potential.","kind":"clinical","origin":"ai"},{"id":"nmj-structure-transmission~ai-6","moduleId":"nmj-structure-transmission","stem":"How does excitation-contraction coupling relate to neuromuscular transmission?","options":[{"id":"a","text":"It involves ACh release"},{"id":"b","text":"It requires Ca²⁺ from the NMJ"},{"id":"c","text":"It triggers muscle fiber contraction"},{"id":"d","text":"It inhibits muscle action potential"}],"answerId":"c","explanation":"Excitation-contraction coupling is the process by which the muscle action potential leads to muscle contraction.","kind":"integration","linkedModuleIds":["excitation-contraction-coupling"],"origin":"ai"},{"id":"nmj-structure-transmission~ai-7","moduleId":"nmj-structure-transmission","stem":"What is a common consequence of impaired neuromuscular junction transmission in metabolic disorders?","options":[{"id":"a","text":"Increased muscle strength"},{"id":"b","text":"Fatigable muscle weakness"},{"id":"c","text":"Enhanced ACh release"},{"id":"d","text":"Decreased Ca²⁺ levels"}],"answerId":"b","explanation":"Metabolic disorders can lead to impaired transmission at the NMJ, resulting in fatigable muscle weakness.","kind":"integration","linkedModuleIds":["metabolic-toxic-nmj-myopathy"],"origin":"ai"}],"apoptosis-necrosis":[{"id":"apoptosis-necrosis~ai-0","moduleId":"apoptosis-necrosis","stem":"What is the primary mechanism by which apoptosis occurs?","options":[{"id":"a","text":"Caspase activation via mitochondrial release of cytochrome c"},{"id":"b","text":"Inflammatory cytokine release"},{"id":"c","text":"Cell membrane rupture"},{"id":"d","text":"Necrotic cell swelling"}],"answerId":"a","explanation":"Apoptosis primarily occurs through caspase activation, often initiated by the release of cytochrome c from mitochondria.","kind":"mechanism","origin":"ai"},{"id":"apoptosis-necrosis~ai-1","moduleId":"apoptosis-necrosis","stem":"Which of the following findings is characteristic of necrosis?","options":[{"id":"a","text":"Cell shrinkage and apoptotic bodies"},{"id":"b","text":"Cell swelling and membrane rupture"},{"id":"c","text":"Intact membrane with phagocytosis"},{"id":"d","text":"Condensed chromatin"}],"answerId":"b","explanation":"Necrosis is characterized by cell swelling and membrane rupture, leading to inflammation.","kind":"recall","origin":"ai"},{"id":"apoptosis-necrosis~ai-2","moduleId":"apoptosis-necrosis","stem":"What is a common consequence of excessive apoptosis?","options":[{"id":"a","text":"Cancer development"},{"id":"b","text":"Inflammation"},{"id":"c","text":"Cellular hypertrophy"},{"id":"d","text":"Tissue regeneration"}],"answerId":"a","explanation":"Excessive apoptosis can lead to cancer due to the loss of necessary cells that regulate growth.","kind":"trap","origin":"ai"},{"id":"apoptosis-necrosis~ai-3","moduleId":"apoptosis-necrosis","stem":"Which of the following is a physiological role of apoptosis?","options":[{"id":"a","text":"Removal of self-reactive lymphocytes"},{"id":"b","text":"Response to ischemic injury"},{"id":"c","text":"Cellular swelling"},{"id":"d","text":"Release of inflammatory mediators"}],"answerId":"a","explanation":"Apoptosis plays a physiological role in removing self-reactive lymphocytes to maintain immune tolerance.","kind":"recall","origin":"ai"},{"id":"apoptosis-necrosis~ai-4","moduleId":"apoptosis-necrosis","stem":"How does the extrinsic pathway of apoptosis primarily initiate cell death?","options":[{"id":"a","text":"By engaging death receptors like Fas"},{"id":"b","text":"Through mitochondrial damage"},{"id":"c","text":"By releasing free radicals"},{"id":"d","text":"Via autophagy mechanisms"}],"answerId":"a","explanation":"The extrinsic pathway of apoptosis is initiated by the engagement of death receptors such as Fas.","kind":"mechanism","origin":"ai"},{"id":"apoptosis-necrosis~ai-5","moduleId":"apoptosis-necrosis","stem":"In the context of cell death, which statement correctly describes apoptosis compared to necrosis?","options":[{"id":"a","text":"Apoptosis causes inflammation, necrosis does not"},{"id":"b","text":"Apoptosis is always pathological, necrosis is physiological"},{"id":"c","text":"Apoptosis is tidy and non-inflammatory, necrosis is messy and inflammatory"},{"id":"d","text":"Both processes involve cell swelling"}],"answerId":"c","explanation":"Apoptosis is characterized by a tidy process with no inflammation, while necrosis is messy and causes inflammation due to membrane rupture.","kind":"trap","origin":"ai"},{"id":"apoptosis-necrosis~ai-6","moduleId":"apoptosis-necrosis","stem":"How does apoptosis relate to the function of CD8 cytotoxic T cells?","options":[{"id":"a","text":"CD8 T cells induce apoptosis in infected cells"},{"id":"b","text":"CD8 T cells promote necrosis in tumors"},{"id":"c","text":"CD8 T cells prevent apoptosis in healthy cells"},{"id":"d","text":"CD8 T cells enhance inflammation during apoptosis"}],"answerId":"a","explanation":"CD8 cytotoxic T cells induce apoptosis in infected or cancerous cells as a mechanism of immune response.","kind":"integration","linkedModuleIds":["cd8-ctl-nk-effectors"],"origin":"ai"},{"id":"apoptosis-necrosis~ai-7","moduleId":"apoptosis-necrosis","stem":"What role does oxidative stress play in necrosis compared to apoptosis?","options":[{"id":"a","text":"It primarily triggers apoptosis"},{"id":"b","text":"It is a common cause of necrosis"},{"id":"c","text":"It has no effect on cell death"},{"id":"d","text":"It enhances apoptotic signaling pathways"}],"answerId":"b","explanation":"Oxidative stress is a common cause of necrosis, leading to cell injury and death through uncontrolled mechanisms.","kind":"integration","linkedModuleIds":["cell-injury-free-radicals"],"origin":"ai"}],"msk-embryo-somites":[{"id":"msk-embryo-somites~ai-0","moduleId":"msk-embryo-somites","stem":"Which part of the somite differentiates into vertebrae and ribs?","options":[{"id":"a","text":"Myotome"},{"id":"b","text":"Dermatome"},{"id":"c","text":"Sclerotome"},{"id":"d","text":"Hypomere"}],"answerId":"c","explanation":"The sclerotome is responsible for forming the vertebrae and ribs through endochondral ossification.","kind":"recall","origin":"ai"},{"id":"msk-embryo-somites~ai-1","moduleId":"msk-embryo-somites","stem":"What is the fate of the notochord in the adult spine?","options":[{"id":"a","text":"Forms the vertebrae"},{"id":"b","text":"Forms the nucleus pulposus"},{"id":"c","text":"Forms the spinal cord"},{"id":"d","text":"Forms the intervertebral discs"}],"answerId":"b","explanation":"The notochord persists as the nucleus pulposus of the intervertebral discs in adults.","kind":"recall","origin":"ai"},{"id":"msk-embryo-somites~ai-2","moduleId":"msk-embryo-somites","stem":"Which mechanism describes how each vertebra is formed?","options":[{"id":"a","text":"Myotome fusion"},{"id":"b","text":"Sclerotome resegmentation"},{"id":"c","text":"Dermatome differentiation"},{"id":"d","text":"Somite migration"}],"answerId":"b","explanation":"Each vertebra is formed from the resegmentation of adjacent sclerotomes, with the caudal half of one fusing with the cranial half of the next.","kind":"mechanism","origin":"ai"},{"id":"msk-embryo-somites~ai-3","moduleId":"msk-embryo-somites","stem":"What clinical finding is associated with hemivertebra?","options":[{"id":"a","text":"Congenital scoliosis"},{"id":"b","text":"Accessory ribs"},{"id":"c","text":"Spinal stenosis"},{"id":"d","text":"Nucleus pulposus herniation"}],"answerId":"a","explanation":"Hemivertebra is a defect in sclerotome formation that can lead to congenital scoliosis.","kind":"recall","origin":"ai"},{"id":"msk-embryo-somites~ai-4","moduleId":"msk-embryo-somites","stem":"Which statement correctly differentiates somite derivatives?","options":[{"id":"a","text":"Myotome forms vertebrae"},{"id":"b","text":"Sclerotome forms skeletal muscle"},{"id":"c","text":"Dermatome forms the dermis"},{"id":"d","text":"Myotome forms the dermis"}],"answerId":"c","explanation":"The dermatome specifically differentiates into the dermis of the back, while the sclerotome forms vertebrae and the myotome forms skeletal muscle.","kind":"trap","origin":"ai"},{"id":"msk-embryo-somites~ai-5","moduleId":"msk-embryo-somites","stem":"How does the myotome contribute to muscle formation?","options":[{"id":"a","text":"Directly forms muscle fibers"},{"id":"b","text":"Fuses to form myoblasts"},{"id":"c","text":"Fuses into myotubes"},{"id":"d","text":"Forms tendons"}],"answerId":"c","explanation":"Myotomes contribute to muscle formation by fusing into myotubes, which then develop into muscle fibers.","kind":"mechanism","origin":"ai"},{"id":"msk-embryo-somites~ai-6","moduleId":"msk-embryo-somites","stem":"Which embryological process is essential for the formation of limb muscles?","options":[{"id":"a","text":"Sclerotome differentiation"},{"id":"b","text":"Myotome migration"},{"id":"c","text":"Dermatome segmentation"},{"id":"d","text":"Endochondral ossification"}],"answerId":"b","explanation":"Myotome migration is crucial for the development of limb muscles, as it allows muscle precursors to reach their final locations.","kind":"integration","linkedModuleIds":["msk-embryo-limb-joints"],"origin":"ai"},{"id":"msk-embryo-somites~ai-7","moduleId":"msk-embryo-somites","stem":"What is the relationship between somite development and endochondral ossification?","options":[{"id":"a","text":"Somites directly ossify into bone"},{"id":"b","text":"Sclerotomes provide precursors for endochondral ossification"},{"id":"c","text":"Myotomes are involved in ossification"},{"id":"d","text":"Dermatomes influence ossification rates"}],"answerId":"b","explanation":"Sclerotomes, derived from somites, provide the precursors for endochondral ossification, forming the vertebrae and ribs.","kind":"integration","linkedModuleIds":["ossification"],"origin":"ai"}],"muscle-spindle-golgi-tendon-organ":[{"id":"muscle-spindle-golgi-tendon-organ~ai-0","moduleId":"muscle-spindle-golgi-tendon-organ","stem":"What type of reflex is elicited by a muscle spindle when it detects stretching?","options":[{"id":"a","text":"Monosynaptic stretch reflex"},{"id":"b","text":"Disynaptic reflex"},{"id":"c","text":"Inverse myotatic reflex"},{"id":"d","text":"Reciprocal inhibition"}],"answerId":"a","explanation":"The muscle spindle initiates a monosynaptic stretch reflex that results in muscle contraction in response to stretching.","kind":"recall","origin":"ai"},{"id":"muscle-spindle-golgi-tendon-organ~ai-1","moduleId":"muscle-spindle-golgi-tendon-organ","stem":"Which afferent fibers are primarily involved in signaling from the muscle spindle?","options":[{"id":"a","text":"Ib afferents"},{"id":"b","text":"Ia afferents"},{"id":"c","text":"Alpha motor neurons"},{"id":"d","text":"Gamma motor neurons"}],"answerId":"b","explanation":"Ia afferent fibers transmit information from the muscle spindle to the spinal cord.","kind":"recall","origin":"ai"},{"id":"muscle-spindle-golgi-tendon-organ~ai-2","moduleId":"muscle-spindle-golgi-tendon-organ","stem":"What is the primary function of the Golgi tendon organ?","options":[{"id":"a","text":"Detect muscle length"},{"id":"b","text":"Detect muscle tension"},{"id":"c","text":"Facilitate muscle contraction"},{"id":"d","text":"Enhance muscle spindle sensitivity"}],"answerId":"b","explanation":"The Golgi tendon organ senses muscle tension and triggers reflex relaxation to prevent muscle damage.","kind":"recall","origin":"ai"},{"id":"muscle-spindle-golgi-tendon-organ~ai-3","moduleId":"muscle-spindle-golgi-tendon-organ","stem":"During a deep tendon reflex test, what is the expected response when the tendon is tapped?","options":[{"id":"a","text":"Muscle relaxation"},{"id":"b","text":"Muscle contraction"},{"id":"c","text":"No response"},{"id":"d","text":"Pain sensation"}],"answerId":"b","explanation":"A tendon tap activates the muscle spindle, resulting in a reflex contraction of the muscle.","kind":"recall","origin":"ai"},{"id":"muscle-spindle-golgi-tendon-organ~ai-4","moduleId":"muscle-spindle-golgi-tendon-organ","stem":"Which mechanism allows the muscle spindle to remain sensitive during muscle shortening?","options":[{"id":"a","text":"Reciprocal inhibition"},{"id":"b","text":"Gamma motor neuron activation"},{"id":"c","text":"Ib afferent signaling"},{"id":"d","text":"Alpha motor neuron activation"}],"answerId":"b","explanation":"Gamma motor neurons contract the intrafusal fibers of the spindle, keeping it taut and sensitive during muscle shortening.","kind":"mechanism","origin":"ai"},{"id":"muscle-spindle-golgi-tendon-organ~ai-5","moduleId":"muscle-spindle-golgi-tendon-organ","stem":"What is the primary difference between the muscle spindle and the Golgi tendon organ?","options":[{"id":"a","text":"Both sense muscle activity"},{"id":"b","text":"Spindle senses length, GTO senses tension"},{"id":"c","text":"Both are monosynaptic"},{"id":"d","text":"Spindle inhibits muscle contraction, GTO excites it"}],"answerId":"b","explanation":"The muscle spindle senses length (stretch) and drives contraction, while the Golgi tendon organ senses tension and drives relaxation.","kind":"trap","origin":"ai"},{"id":"muscle-spindle-golgi-tendon-organ~ai-6","moduleId":"muscle-spindle-golgi-tendon-organ","stem":"How does the muscle spindle's function integrate with spinal reflexes?","options":[{"id":"a","text":"It inhibits spinal reflexes"},{"id":"b","text":"It enhances Golgi tendon organ activity"},{"id":"c","text":"It provides feedback for muscle contraction"},{"id":"d","text":"It prevents reciprocal inhibition"}],"answerId":"c","explanation":"The muscle spindle provides continuous feedback about muscle length, which is essential for coordinating spinal reflexes.","kind":"integration","linkedModuleIds":["proprioceptors-muscle-spindle-reflexes"],"origin":"ai"},{"id":"muscle-spindle-golgi-tendon-organ~ai-7","moduleId":"muscle-spindle-golgi-tendon-organ","stem":"Which reflex mechanism is primarily responsible for antagonist muscle relaxation during agonist contraction?","options":[{"id":"a","text":"Stretch reflex"},{"id":"b","text":"Inverse myotatic reflex"},{"id":"c","text":"Reciprocal innervation"},{"id":"d","text":"Gamma loop"}],"answerId":"c","explanation":"Reciprocal innervation allows the agonist to contract while the antagonist relaxes, facilitating smooth movement.","kind":"integration","linkedModuleIds":["reflex-arc-stretch-withdrawal"],"origin":"ai"}],"cell-injury-free-radicals":[{"id":"cell-injury-free-radicals~ai-0","moduleId":"cell-injury-free-radicals","stem":"What is the primary mechanism of cellular swelling in reversible cell injury?","options":[{"id":"a","text":"Increased ATP production"},{"id":"b","text":"Na⁺/K⁺ pump failure"},{"id":"c","text":"Calcium influx"},{"id":"d","text":"Mitochondrial dysfunction"}],"answerId":"b","explanation":"Cellular swelling occurs due to the failure of the ATP-dependent Na⁺/K⁺ pump, leading to Na⁺ and water accumulation inside the cell.","kind":"mechanism","origin":"ai"},{"id":"cell-injury-free-radicals~ai-1","moduleId":"cell-injury-free-radicals","stem":"Which of the following is a hallmark of irreversible cell injury?","options":[{"id":"a","text":"Cellular swelling"},{"id":"b","text":"Mitochondrial dysfunction"},{"id":"c","text":"Fatty change"},{"id":"d","text":"Ribosomal detachment"}],"answerId":"b","explanation":"Irreversible injury is characterized by severe mitochondrial dysfunction, which indicates the point of no return for the cell.","kind":"mechanism","origin":"ai"},{"id":"cell-injury-free-radicals~ai-2","moduleId":"cell-injury-free-radicals","stem":"What is the effect of reperfusion following ischemia?","options":[{"id":"a","text":"Prevents oxidative stress"},{"id":"b","text":"Causes cellular swelling"},{"id":"c","text":"Induces free radical burst"},{"id":"d","text":"Restores ATP levels immediately"}],"answerId":"c","explanation":"Reperfusion can paradoxically worsen cell damage due to a burst of free radicals generated upon restoration of blood flow.","kind":"clinical","origin":"ai"},{"id":"cell-injury-free-radicals~ai-3","moduleId":"cell-injury-free-radicals","stem":"Which antioxidant enzyme is primarily responsible for converting superoxide radicals into hydrogen peroxide?","options":[{"id":"a","text":"Catalase"},{"id":"b","text":"Glutathione peroxidase"},{"id":"c","text":"Superoxide dismutase"},{"id":"d","text":"Vitamin E"}],"answerId":"c","explanation":"Superoxide dismutase catalyzes the conversion of superoxide radicals into hydrogen peroxide, a key step in the antioxidant defense system.","kind":"recall","origin":"ai"},{"id":"cell-injury-free-radicals~ai-4","moduleId":"cell-injury-free-radicals","stem":"In the context of cell injury, what does massive calcium influx indicate?","options":[{"id":"a","text":"Reversible injury"},{"id":"b","text":"Cell death"},{"id":"c","text":"Oxidative stress"},{"id":"d","text":"Antioxidant activity"}],"answerId":"b","explanation":"Massive calcium influx is a critical sign of irreversible injury and indicates that the cell is likely to undergo necrosis or apoptosis.","kind":"trap","origin":"ai"},{"id":"cell-injury-free-radicals~ai-5","moduleId":"cell-injury-free-radicals","stem":"How does oxidative stress contribute to cellular aging?","options":[{"id":"a","text":"By enhancing ATP production"},{"id":"b","text":"Through lipid peroxidation"},{"id":"c","text":"By promoting apoptosis"},{"id":"d","text":"By increasing mitochondrial biogenesis"}],"answerId":"b","explanation":"Oxidative stress leads to lipid peroxidation, which damages cellular components and is a central mechanism in theories of cellular aging.","kind":"integration","origin":"ai"},{"id":"cell-injury-free-radicals~ai-6","moduleId":"cell-injury-free-radicals","stem":"Which of the following best explains the link between hypoxia and free radical production?","options":[{"id":"a","text":"Hypoxia increases ATP synthesis"},{"id":"b","text":"Hypoxia leads to anaerobic metabolism"},{"id":"c","text":"Hypoxia prevents calcium influx"},{"id":"d","text":"Hypoxia enhances antioxidant activity"}],"answerId":"b","explanation":"Hypoxia leads to anaerobic metabolism, resulting in the accumulation of reactive oxygen species when oxygen is restored, contributing to free radical production.","kind":"integration","linkedModuleIds":["metabolic-junction-points"],"origin":"ai"}],"synaptic-plasticity-ltd-memory":[{"id":"synaptic-plasticity-ltd-memory~ai-0","moduleId":"synaptic-plasticity-ltd-memory","stem":"What is the primary mechanism by which long-term depression (LTD) weakens synaptic strength?","options":[{"id":"a","text":"Increased AMPA receptor insertion"},{"id":"b","text":"Decreased AMPA receptor insertion"},{"id":"c","text":"Increased NMDA receptor activity"},{"id":"d","text":"Decreased calcium ion influx"}],"answerId":"b","explanation":"LTD is characterized by a small, sustained rise in Ca²⁺ that leads to the removal of AMPA receptors from the synapse.","kind":"mechanism","origin":"ai"},{"id":"synaptic-plasticity-ltd-memory~ai-1","moduleId":"synaptic-plasticity-ltd-memory","stem":"Which of the following findings is consistent with long-term potentiation (LTP)?","options":[{"id":"a","text":"Increased synaptic strength after low-frequency stimulation"},{"id":"b","text":"Decreased synaptic strength after high-frequency stimulation"},{"id":"c","text":"Increased AMPA receptor density at the postsynaptic membrane"},{"id":"d","text":"Decreased NMDA receptor activity"}],"answerId":"c","explanation":"LTP is associated with increased synaptic strength due to the insertion of more AMPA receptors following high-frequency stimulation.","kind":"recall","origin":"ai"},{"id":"synaptic-plasticity-ltd-memory~ai-2","moduleId":"synaptic-plasticity-ltd-memory","stem":"What role does the NMDA receptor play in synaptic plasticity?","options":[{"id":"a","text":"It solely mediates synaptic inhibition"},{"id":"b","text":"It acts as a coincidence detector for synaptic strengthening"},{"id":"c","text":"It exclusively promotes long-term depression"},{"id":"d","text":"It is involved in short-term memory only"}],"answerId":"b","explanation":"The NMDA receptor requires both glutamate binding and postsynaptic depolarization to relieve its Mg²⁺ block, thus acting as a coincidence detector.","kind":"mechanism","origin":"ai"},{"id":"synaptic-plasticity-ltd-memory~ai-3","moduleId":"synaptic-plasticity-ltd-memory","stem":"Which statement correctly distinguishes short-term memory from long-term memory?","options":[{"id":"a","text":"Both require new protein synthesis"},{"id":"b","text":"Short-term memory relies on existing proteins, long-term requires new synthesis"},{"id":"c","text":"Both depend equally on synaptic strengthening"},{"id":"d","text":"Short-term memory is permanent without protein synthesis"}],"answerId":"b","explanation":"Short-term memory relies on transient modifications of existing proteins, while long-term memory requires new gene transcription and protein synthesis.","kind":"trap","origin":"ai"},{"id":"synaptic-plasticity-ltd-memory~ai-4","moduleId":"synaptic-plasticity-ltd-memory","stem":"A patient with hippocampal damage is most likely to exhibit which of the following?","options":[{"id":"a","text":"Impaired short-term memory"},{"id":"b","text":"Impaired long-term memory formation"},{"id":"c","text":"Enhanced memory recall"},{"id":"d","text":"Normal memory consolidation"}],"answerId":"b","explanation":"The hippocampus is crucial for forming new declarative memories, so damage here impairs long-term memory formation.","kind":"clinical","origin":"ai"},{"id":"synaptic-plasticity-ltd-memory~ai-5","moduleId":"synaptic-plasticity-ltd-memory","stem":"How does long-term depression (LTD) relate to the processes of learning and memory?","options":[{"id":"a","text":"It exclusively enhances memory retention"},{"id":"b","text":"It is essential for the removal of outdated memories"},{"id":"c","text":"It strengthens all synaptic connections"},{"id":"d","text":"It has no impact on memory processes"}],"answerId":"b","explanation":"LTD weakens specific synaptic connections, allowing for the removal of outdated or less relevant memories, thus facilitating learning.","kind":"integration","linkedModuleIds":["synaptic-plasticity-learning"],"origin":"ai"},{"id":"synaptic-plasticity-ltd-memory~ai-6","moduleId":"synaptic-plasticity-ltd-memory","stem":"Which neurotransmitter system is primarily involved in mediating the effects of long-term potentiation and depression?","options":[{"id":"a","text":"Dopaminergic system"},{"id":"b","text":"Serotonergic system"},{"id":"c","text":"Glutamatergic system"},{"id":"d","text":"GABAergic system"}],"answerId":"c","explanation":"The glutamatergic system, particularly through NMDA and AMPA receptors, is crucial for mediating LTP and LTD.","kind":"integration","linkedModuleIds":["neurotransmitter-systems-catalog"],"origin":"ai"}],"autonomic-sympathetic-parasympathetic":[{"id":"autonomic-sympathetic-parasympathetic~ai-0","moduleId":"autonomic-sympathetic-parasympathetic","stem":"Which of the following accurately describes the sympathetic nervous system?","options":[{"id":"a","text":"It has long preganglionic and short postganglionic fibers."},{"id":"b","text":"It originates from cranial and sacral regions."},{"id":"c","text":"It prepares the body for 'rest and digest' activities."},{"id":"d","text":"It increases heart rate and blood pressure."}],"answerId":"d","explanation":"The sympathetic nervous system is responsible for the 'fight or flight' response, which includes increasing heart rate and blood pressure.","kind":"recall","origin":"ai"},{"id":"autonomic-sympathetic-parasympathetic~ai-1","moduleId":"autonomic-sympathetic-parasympathetic","stem":"What is the primary neurotransmitter released by postganglionic sympathetic neurons?","options":[{"id":"a","text":"Acetylcholine"},{"id":"b","text":"Dopamine"},{"id":"c","text":"Norepinephrine"},{"id":"d","text":"Serotonin"}],"answerId":"c","explanation":"Postganglionic sympathetic neurons primarily release norepinephrine to exert their effects on target organs.","kind":"recall","origin":"ai"},{"id":"autonomic-sympathetic-parasympathetic~ai-2","moduleId":"autonomic-sympathetic-parasympathetic","stem":"A patient presents with decreased heart rate and increased gastrointestinal motility. Which division of the autonomic nervous system is likely activated?","options":[{"id":"a","text":"Sympathetic"},{"id":"b","text":"Parasympathetic"},{"id":"c","text":"Somatic"},{"id":"d","text":"Enteric"}],"answerId":"b","explanation":"The parasympathetic nervous system is responsible for 'rest and digest' functions, including decreased heart rate and increased GI motility.","kind":"clinical","origin":"ai"},{"id":"autonomic-sympathetic-parasympathetic~ai-3","moduleId":"autonomic-sympathetic-parasympathetic","stem":"Which statement about the autonomic nervous system is true?","options":[{"id":"a","text":"Both divisions use a single neuron to reach the target organ."},{"id":"b","text":"The sympathetic division has ganglia located near the target organ."},{"id":"c","text":"The parasympathetic division has long preganglionic fibers."},{"id":"d","text":"The adrenal medulla is a typical autonomic ganglion."}],"answerId":"c","explanation":"The parasympathetic division has long preganglionic fibers that synapse close to or within the target organs.","kind":"trap","origin":"ai"},{"id":"autonomic-sympathetic-parasympathetic~ai-4","moduleId":"autonomic-sympathetic-parasympathetic","stem":"In response to stress, which mechanism allows for a systemic release of adrenaline?","options":[{"id":"a","text":"Direct release from sympathetic ganglia"},{"id":"b","text":"Activation of the adrenal cortex"},{"id":"c","text":"Stimulation of the adrenal medulla"},{"id":"d","text":"Release from postganglionic neurons"}],"answerId":"c","explanation":"The adrenal medulla releases adrenaline directly into the bloodstream in response to sympathetic activation.","kind":"mechanism","origin":"ai"},{"id":"autonomic-sympathetic-parasympathetic~ai-5","moduleId":"autonomic-sympathetic-parasympathetic","stem":"How does the sympathetic nervous system primarily affect the pupils during stress?","options":[{"id":"a","text":"Constricts the pupils"},{"id":"b","text":"Dilates the pupils"},{"id":"c","text":"No effect on pupils"},{"id":"d","text":"Causes uneven pupil size"}],"answerId":"b","explanation":"The sympathetic nervous system dilates the pupils to enhance vision during stressful situations.","kind":"clinical","origin":"ai"},{"id":"autonomic-sympathetic-parasympathetic~ai-6","moduleId":"autonomic-sympathetic-parasympathetic","stem":"Which of the following best illustrates the interaction between the autonomic nervous system and homeostasis?","options":[{"id":"a","text":"Sympathetic activation increases digestive enzyme secretion."},{"id":"b","text":"Parasympathetic activation decreases heart rate."},{"id":"c","text":"Sympathetic activation promotes glycogen synthesis."},{"id":"d","text":"Parasympathetic activation increases blood glucose levels."}],"answerId":"b","explanation":"Parasympathetic activation decreases heart rate, illustrating its role in maintaining homeostasis during rest.","kind":"integration","linkedModuleIds":["homeostasis-feedback-control"],"origin":"ai"},{"id":"autonomic-sympathetic-parasympathetic~ai-7","moduleId":"autonomic-sympathetic-parasympathetic","stem":"How do the mechanisms of the enteric nervous system relate to the autonomic nervous system?","options":[{"id":"a","text":"Enteric nervous system operates independently of autonomic control."},{"id":"b","text":"Enteric nervous system is solely sympathetic."},{"id":"c","text":"Enteric nervous system is influenced by both sympathetic and parasympathetic inputs."},{"id":"d","text":"Enteric nervous system only responds to somatic signals."}],"answerId":"c","explanation":"The enteric nervous system is influenced by both sympathetic and parasympathetic inputs, integrating autonomic control with GI function.","kind":"integration","linkedModuleIds":["enteric-autonomic-reflex-control"],"origin":"ai"}],"msk-embryo-limb-joints":[{"id":"msk-embryo-limb-joints~ai-0","moduleId":"msk-embryo-limb-joints","stem":"What is the primary role of the apical ectodermal ridge (AER) in limb development?","options":[{"id":"a","text":"Drives proximodistal outgrowth"},{"id":"b","text":"Sets the anteroposterior axis"},{"id":"c","text":"Induces joint formation"},{"id":"d","text":"Stimulates muscle differentiation"}],"answerId":"a","explanation":"The AER is crucial for driving proximodistal limb outgrowth through FGF signaling.","kind":"recall","origin":"ai"},{"id":"msk-embryo-limb-joints~ai-1","moduleId":"msk-embryo-limb-joints","stem":"Which signaling molecule is primarily involved in establishing the anteroposterior axis of limb development?","options":[{"id":"a","text":"Bone morphogenetic protein (BMP)"},{"id":"b","text":"Fibroblast growth factor (FGF)"},{"id":"c","text":"Sonic hedgehog (SHH)"},{"id":"d","text":"Wnt"}],"answerId":"c","explanation":"Sonic hedgehog (SHH) from the zone of polarizing activity (ZPA) sets the anteroposterior axis.","kind":"recall","origin":"ai"},{"id":"msk-embryo-limb-joints~ai-2","moduleId":"msk-embryo-limb-joints","stem":"What type of ossification primarily forms long bones?","options":[{"id":"a","text":"Intramembranous ossification"},{"id":"b","text":"Endochondral ossification"},{"id":"c","text":"Appositional ossification"},{"id":"d","text":"Perichondral ossification"}],"answerId":"b","explanation":"Long bones primarily form through endochondral ossification, where a cartilage model is replaced by bone.","kind":"recall","origin":"ai"},{"id":"msk-embryo-limb-joints~ai-3","moduleId":"msk-embryo-limb-joints","stem":"What is the consequence of failure of apoptosis between digital rays during limb development?","options":[{"id":"a","text":"Polydactyly"},{"id":"b","text":"Syndactyly"},{"id":"c","text":"Amelia"},{"id":"d","text":"Phocomelia"}],"answerId":"b","explanation":"Failure of apoptosis between digital rays results in syndactyly, or webbed fingers/toes.","kind":"trap","origin":"ai"},{"id":"msk-embryo-limb-joints~ai-4","moduleId":"msk-embryo-limb-joints","stem":"Which statement correctly describes the function of the zone of polarizing activity (ZPA)?","options":[{"id":"a","text":"Determines limb length"},{"id":"b","text":"Sets the anteroposterior axis"},{"id":"c","text":"Drives muscle differentiation"},{"id":"d","text":"Induces joint formation"}],"answerId":"b","explanation":"The ZPA, through SHH signaling, is responsible for setting the anteroposterior axis of limb development.","kind":"trap","origin":"ai"},{"id":"msk-embryo-limb-joints~ai-5","moduleId":"msk-embryo-limb-joints","stem":"How does the interzone contribute to joint formation?","options":[{"id":"a","text":"It promotes muscle attachment"},{"id":"b","text":"It cavitates to form the joint cavity"},{"id":"c","text":"It induces bone growth"},{"id":"d","text":"It signals for limb rotation"}],"answerId":"b","explanation":"The interzone cavitates to form the joint cavity, leading to the development of synovial joints.","kind":"mechanism","origin":"ai"},{"id":"msk-embryo-limb-joints~ai-6","moduleId":"msk-embryo-limb-joints","stem":"How does endochondral ossification relate to cartilage types?","options":[{"id":"a","text":"It forms hyaline cartilage only"},{"id":"b","text":"It is a process exclusive to elastic cartilage"},{"id":"c","text":"It involves hyaline cartilage as a precursor"},{"id":"d","text":"It does not involve cartilage"}],"answerId":"c","explanation":"Endochondral ossification involves hyaline cartilage as a precursor before being replaced by bone.","kind":"integration","linkedModuleIds":["cartilage-types"],"origin":"ai"},{"id":"msk-embryo-limb-joints~ai-7","moduleId":"msk-embryo-limb-joints","stem":"What is the relationship between limb development and joint classification?","options":[{"id":"a","text":"Limb length affects joint stability"},{"id":"b","text":"Joint type is determined by limb rotation"},{"id":"c","text":"Joint formation is influenced by limb ossification"},{"id":"d","text":"Different joint types arise from specific mesenchymal interzones"}],"answerId":"d","explanation":"Different joint types arise from specific mesenchymal interzones that form during limb development.","kind":"integration","linkedModuleIds":["fracture-classification"],"origin":"ai"}],"reflex-arc-stretch-withdrawal":[{"id":"reflex-arc-stretch-withdrawal~ai-0","moduleId":"reflex-arc-stretch-withdrawal","stem":"What is the primary function of the muscle spindle in the stretch reflex?","options":[{"id":"a","text":"Senses muscle tension"},{"id":"b","text":"Senses muscle length/stretch"},{"id":"c","text":"Inhibits muscle contraction"},{"id":"d","text":"Facilitates reciprocal inhibition"}],"answerId":"b","explanation":"The muscle spindle primarily senses muscle length and stretch, which is crucial for the monosynaptic stretch reflex.","kind":"recall","origin":"ai"},{"id":"reflex-arc-stretch-withdrawal~ai-1","moduleId":"reflex-arc-stretch-withdrawal","stem":"Which of the following best describes the pathway of a monosynaptic stretch reflex?","options":[{"id":"a","text":"Receptor → efferent neuron → integration center → afferent neuron → effector"},{"id":"b","text":"Receptor → afferent neuron → integration center → efferent neuron → effector"},{"id":"c","text":"Integration center → receptor → afferent neuron → effector → efferent neuron"},{"id":"d","text":"Efferent neuron → receptor → afferent neuron → integration center → effector"}],"answerId":"b","explanation":"The correct pathway for a monosynaptic stretch reflex is receptor → afferent neuron → integration center → efferent neuron → effector.","kind":"mechanism","origin":"ai"},{"id":"reflex-arc-stretch-withdrawal~ai-2","moduleId":"reflex-arc-stretch-withdrawal","stem":"A patient presents with hyperreflexia and a positive Babinski sign. What does this indicate?","options":[{"id":"a","text":"Lower motor neuron lesion"},{"id":"b","text":"Upper motor neuron lesion"},{"id":"c","text":"Normal reflex activity"},{"id":"d","text":"Peripheral nerve damage"}],"answerId":"b","explanation":"Hyperreflexia and a positive Babinski sign are indicative of an upper motor neuron lesion.","kind":"clinical","origin":"ai"},{"id":"reflex-arc-stretch-withdrawal~ai-3","moduleId":"reflex-arc-stretch-withdrawal","stem":"Which reflex involves interneurons between sensory and motor neurons?","options":[{"id":"a","text":"Monosynaptic reflex"},{"id":"b","text":"Polysynaptic reflex"},{"id":"c","text":"Stretch reflex"},{"id":"d","text":"Inverse stretch reflex"}],"answerId":"b","explanation":"The polysynaptic reflex involves interneurons, allowing for more complex responses to stimuli.","kind":"recall","origin":"ai"},{"id":"reflex-arc-stretch-withdrawal~ai-4","moduleId":"reflex-arc-stretch-withdrawal","stem":"What is the role of the Golgi tendon organ in muscle function?","options":[{"id":"a","text":"Senses muscle length"},{"id":"b","text":"Senses muscle tension"},{"id":"c","text":"Facilitates muscle contraction"},{"id":"d","text":"Inhibits muscle spindle activity"}],"answerId":"b","explanation":"The Golgi tendon organ senses muscle tension and inhibits muscle contraction to protect against excessive force.","kind":"recall","origin":"ai"},{"id":"reflex-arc-stretch-withdrawal~ai-5","moduleId":"reflex-arc-stretch-withdrawal","stem":"How does the withdrawal reflex protect the body from injury?","options":[{"id":"a","text":"By contracting the extensor muscles"},{"id":"b","text":"By inhibiting the flexor muscles"},{"id":"c","text":"By contracting flexor muscles and inhibiting extensors"},{"id":"d","text":"By activating the Golgi tendon organ"}],"answerId":"c","explanation":"The withdrawal reflex contracts flexor muscles to withdraw from a painful stimulus while inhibiting the antagonist extensor muscles.","kind":"mechanism","origin":"ai"},{"id":"reflex-arc-stretch-withdrawal~ai-6","moduleId":"reflex-arc-stretch-withdrawal","stem":"How does the stretch reflex relate to the management of Cushing's syndrome during steroid withdrawal?","options":[{"id":"a","text":"It helps assess muscle strength during recovery"},{"id":"b","text":"It indicates the need for increased steroid dosage"},{"id":"c","text":"It shows the effects of muscle atrophy"},{"id":"d","text":"It is unrelated to muscle function"}],"answerId":"a","explanation":"Assessing the stretch reflex can help evaluate muscle strength and function during recovery from steroid withdrawal in Cushing's syndrome.","kind":"integration","linkedModuleIds":["cushing-management-steroid-withdrawal"],"origin":"ai"},{"id":"reflex-arc-stretch-withdrawal~ai-7","moduleId":"reflex-arc-stretch-withdrawal","stem":"What is a key difference between muscle spindles and Golgi tendon organs in reflex actions?","options":[{"id":"a","text":"Muscle spindles sense tension, Golgi organs sense length"},{"id":"b","text":"Muscle spindles facilitate contraction, Golgi organs inhibit contraction"},{"id":"c","text":"Muscle spindles are involved in withdrawal reflex, Golgi organs are not"},{"id":"d","text":"Muscle spindles are located in tendons, Golgi organs are in muscles"}],"answerId":"b","explanation":"Muscle spindles facilitate contraction in response to stretch, while Golgi tendon organs inhibit contraction in response to excessive tension.","kind":"integration","linkedModuleIds":["muscle-spindle-golgi-tendon-organ"],"origin":"ai"}],"respiratory-development-stages":[{"id":"respiratory-development-stages~ai-0","moduleId":"respiratory-development-stages","stem":"At what stage of lung development does the fetus first achieve the capability for gas exchange?","options":[{"id":"a","text":"Embryonic"},{"id":"b","text":"Pseudoglandular"},{"id":"c","text":"Canalicular"},{"id":"d","text":"Saccular"}],"answerId":"c","explanation":"Gas exchange becomes possible during the Canalicular stage, around 24 weeks of gestation.","kind":"recall","origin":"ai"},{"id":"respiratory-development-stages~ai-1","moduleId":"respiratory-development-stages","stem":"What is the primary function of surfactant produced by type II pneumocytes?","options":[{"id":"a","text":"Increase airway resistance"},{"id":"b","text":"Enhance gas exchange"},{"id":"c","text":"Lower alveolar surface tension"},{"id":"d","text":"Promote mucus secretion"}],"answerId":"c","explanation":"Surfactant lowers alveolar surface tension, preventing collapse of the alveoli.","kind":"mechanism","origin":"ai"},{"id":"respiratory-development-stages~ai-2","moduleId":"respiratory-development-stages","stem":"A preterm neonate presents with respiratory distress. Which of the following is the most likely cause?","options":[{"id":"a","text":"Excess surfactant production"},{"id":"b","text":"Insufficient surfactant production"},{"id":"c","text":"Airway obstruction"},{"id":"d","text":"Congenital lung malformation"}],"answerId":"b","explanation":"Preterm neonates often have insufficient surfactant, leading to neonatal respiratory distress syndrome (RDS).","kind":"clinical","origin":"ai"},{"id":"respiratory-development-stages~ai-3","moduleId":"respiratory-development-stages","stem":"Which embryonic structure gives rise to the epithelial lining of the airways?","options":[{"id":"a","text":"Splanchnic mesoderm"},{"id":"b","text":"Endoderm"},{"id":"c","text":"Ectoderm"},{"id":"d","text":"Mesoderm"}],"answerId":"b","explanation":"The epithelial lining of the airways originates from the endoderm during lung development.","kind":"recall","origin":"ai"},{"id":"respiratory-development-stages~ai-4","moduleId":"respiratory-development-stages","stem":"When do most alveoli form in human development?","options":[{"id":"a","text":"At birth"},{"id":"b","text":"During the embryonic stage"},{"id":"c","text":"During the canalicular stage"},{"id":"d","text":"After birth"}],"answerId":"d","explanation":"Most alveoli form after birth, continuing until about 8 years of age.","kind":"trap","origin":"ai"},{"id":"respiratory-development-stages~ai-5","moduleId":"respiratory-development-stages","stem":"What is the viability threshold for a fetus in terms of lung development?","options":[{"id":"a","text":"20 weeks"},{"id":"b","text":"24 weeks"},{"id":"c","text":"28 weeks"},{"id":"d","text":"32 weeks"}],"answerId":"b","explanation":"The viability threshold is approximately 24 weeks, when gas exchange becomes possible.","kind":"recall","origin":"ai"},{"id":"respiratory-development-stages~ai-6","moduleId":"respiratory-development-stages","stem":"How does the development of type II pneumocytes relate to the respiratory membrane's function?","options":[{"id":"a","text":"They increase airway resistance"},{"id":"b","text":"They produce mucus for airway clearance"},{"id":"c","text":"They produce surfactant to reduce surface tension"},{"id":"d","text":"They form the structural framework of the alveoli"}],"answerId":"c","explanation":"Type II pneumocytes produce surfactant, which is crucial for reducing surface tension and facilitating gas exchange.","kind":"integration","linkedModuleIds":["alveoli-pneumocytes-respiratory-membrane"],"origin":"ai"},{"id":"respiratory-development-stages~ai-7","moduleId":"respiratory-development-stages","stem":"Which congenital anomaly is most likely to affect the development of the respiratory system?","options":[{"id":"a","text":"Tracheoesophageal fistula"},{"id":"b","text":"Cleft lip"},{"id":"c","text":"Congenital heart defect"},{"id":"d","text":"Diaphragmatic hernia"}],"answerId":"a","explanation":"Tracheoesophageal fistula directly affects the separation of the trachea and esophagus, impacting respiratory development.","kind":"integration","linkedModuleIds":["respiratory-congenital-anomalies"],"origin":"ai"}],"fracture-classification":[{"id":"fracture-classification~ai-0","moduleId":"fracture-classification","stem":"What type of fracture is characterized by the bone breaking through the skin?","options":[{"id":"a","text":"Closed fracture"},{"id":"b","text":"Open fracture"},{"id":"c","text":"Comminuted fracture"},{"id":"d","text":"Greenstick fracture"}],"answerId":"b","explanation":"An open fracture, also known as a compound fracture, involves the bone protruding through the skin, increasing the risk of infection.","kind":"recall","origin":"ai"},{"id":"fracture-classification~ai-1","moduleId":"fracture-classification","stem":"Which fracture type is typically seen in children due to the softness of their bones?","options":[{"id":"a","text":"Comminuted fracture"},{"id":"b","text":"Greenstick fracture"},{"id":"c","text":"Pathological fracture"},{"id":"d","text":"Stress fracture"}],"answerId":"b","explanation":"A greenstick fracture is an incomplete fracture common in children, where the bone bends and partially breaks.","kind":"recall","origin":"ai"},{"id":"fracture-classification~ai-2","moduleId":"fracture-classification","stem":"What is the key distinguishing feature of a dislocation compared to a subluxation?","options":[{"id":"a","text":"Partial contact between joint surfaces"},{"id":"b","text":"Complete loss of joint surface contact"},{"id":"c","text":"Presence of swelling"},{"id":"d","text":"Involvement of ligaments"}],"answerId":"b","explanation":"A dislocation is defined by the complete loss of contact between the articular surfaces of a joint, unlike a subluxation which is a partial displacement.","kind":"trap","origin":"ai"},{"id":"fracture-classification~ai-3","moduleId":"fracture-classification","stem":"Which type of fracture occurs through a lytic lesion after minor trauma?","options":[{"id":"a","text":"Comminuted fracture"},{"id":"b","text":"Pathological fracture"},{"id":"c","text":"Greenstick fracture"},{"id":"d","text":"Stress fracture"}],"answerId":"b","explanation":"A pathological fracture occurs through weakened bone, such as in cases of tumors or osteoporosis, often after minimal force.","kind":"recall","origin":"ai"},{"id":"fracture-classification~ai-4","moduleId":"fracture-classification","stem":"What is the mechanism of injury for a comminuted fracture?","options":[{"id":"a","text":"Twisting force"},{"id":"b","text":"Direct impact"},{"id":"c","text":"Repetitive loading"},{"id":"d","text":"Bending stress"}],"answerId":"b","explanation":"A comminuted fracture is characterized by the bone being broken into three or more fragments, often due to a high-energy impact.","kind":"mechanism","origin":"ai"},{"id":"fracture-classification~ai-5","moduleId":"fracture-classification","stem":"In a patient with a humeral fracture, which of the following complications should be monitored due to potential compartment syndrome?","options":[{"id":"a","text":"Infection"},{"id":"b","text":"Nerve injury"},{"id":"c","text":"Vascular compromise"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"Compartment syndrome can lead to infection, nerve injury, and vascular compromise, making all these complications relevant in humeral fractures.","kind":"integration","linkedModuleIds":["arm-compartments-humerus-fractures"],"origin":"ai"},{"id":"fracture-classification~ai-6","moduleId":"fracture-classification","stem":"Which joint injury involves a complete loss of contact between the articular surfaces?","options":[{"id":"a","text":"Subluxation"},{"id":"b","text":"Sprain"},{"id":"c","text":"Dislocation"},{"id":"d","text":"Strain"}],"answerId":"c","explanation":"A dislocation is defined by the complete loss of contact between the surfaces of the joint, distinguishing it from a subluxation.","kind":"recall","origin":"ai"},{"id":"fracture-classification~ai-7","moduleId":"fracture-classification","stem":"What is the primary healing mechanism involved in the initial phase of fracture healing?","options":[{"id":"a","text":"Callus formation"},{"id":"b","text":"Hemostasis and inflammation"},{"id":"c","text":"Bone remodeling"},{"id":"d","text":"Cartilage formation"}],"answerId":"b","explanation":"The initial phase of fracture healing involves hemostasis and inflammation, which set the stage for subsequent healing processes.","kind":"integration","linkedModuleIds":["fracture-healing"],"origin":"ai"}],"muscle-energy-systems":[{"id":"muscle-energy-systems~ai-0","moduleId":"muscle-energy-systems","stem":"Which energy system provides ATP for the first 10 seconds of maximal effort?","options":[{"id":"a","text":"Phosphocreatine system"},{"id":"b","text":"Anaerobic glycolysis"},{"id":"c","text":"Aerobic metabolism"},{"id":"d","text":"Lipid oxidation"}],"answerId":"a","explanation":"The phosphocreatine system is the primary source of ATP during the initial seconds of high-intensity exercise.","kind":"recall","origin":"ai"},{"id":"muscle-energy-systems~ai-1","moduleId":"muscle-energy-systems","stem":"What is the primary byproduct of anaerobic glycolysis?","options":[{"id":"a","text":"Carbon dioxide"},{"id":"b","text":"Lactate"},{"id":"c","text":"Creatine"},{"id":"d","text":"Acetyl-CoA"}],"answerId":"b","explanation":"Anaerobic glycolysis converts glucose to lactate while producing 2 ATP.","kind":"recall","origin":"ai"},{"id":"muscle-energy-systems~ai-2","moduleId":"muscle-energy-systems","stem":"Which statement correctly describes the ATP yield of anaerobic glycolysis compared to aerobic metabolism?","options":[{"id":"a","text":"Anaerobic glycolysis produces about the same amount of ATP as aerobic metabolism"},{"id":"b","text":"Anaerobic glycolysis yields only ~2 ATP per glucose"},{"id":"c","text":"Aerobic metabolism produces less ATP than anaerobic glycolysis"},{"id":"d","text":"Both systems yield equal ATP under maximal effort"}],"answerId":"b","explanation":"Anaerobic glycolysis yields only ~2 ATP per glucose, while aerobic metabolism yields ~30+ ATP.","kind":"trap","origin":"ai"},{"id":"muscle-energy-systems~ai-3","moduleId":"muscle-energy-systems","stem":"During prolonged endurance activities, which energy system is primarily utilized?","options":[{"id":"a","text":"Phosphocreatine system"},{"id":"b","text":"Anaerobic glycolysis"},{"id":"c","text":"Aerobic metabolism"},{"id":"d","text":"Lipid oxidation"}],"answerId":"c","explanation":"Aerobic metabolism is the dominant energy system during prolonged, low-intensity exercise.","kind":"recall","origin":"ai"},{"id":"muscle-energy-systems~ai-4","moduleId":"muscle-energy-systems","stem":"What physiological phenomenon explains continued heavy breathing after intense exercise?","options":[{"id":"a","text":"Oxygen debt (EPOC)"},{"id":"b","text":"Lactate threshold"},{"id":"c","text":"Anaerobic threshold"},{"id":"d","text":"Creatine depletion"}],"answerId":"a","explanation":"Oxygen debt (EPOC) refers to the elevated oxygen consumption post-exercise to restore ATP and clear lactate.","kind":"recall","origin":"ai"},{"id":"muscle-energy-systems~ai-5","moduleId":"muscle-energy-systems","stem":"How does the phosphocreatine system regenerate ATP?","options":[{"id":"a","text":"By converting lactate to glucose"},{"id":"b","text":"By transferring a phosphate from phosphocreatine to ADP"},{"id":"c","text":"By oxidizing fatty acids"},{"id":"d","text":"By glycolysis of glycogen"}],"answerId":"b","explanation":"The phosphocreatine system uses creatine kinase to transfer a phosphate from phosphocreatine to ADP, regenerating ATP instantly.","kind":"mechanism","origin":"ai"},{"id":"muscle-energy-systems~ai-6","moduleId":"muscle-energy-systems","stem":"How does anaerobic glycolysis relate to glucose transport and glycolysis?","options":[{"id":"a","text":"It requires oxygen for glucose transport"},{"id":"b","text":"It produces ATP without oxygen from glucose"},{"id":"c","text":"It only occurs in muscle cells"},{"id":"d","text":"It is the primary pathway for glucose transport"}],"answerId":"b","explanation":"Anaerobic glycolysis generates ATP from glucose without oxygen, making it crucial during high-intensity exercise.","kind":"integration","linkedModuleIds":["glucose-transport-glycolysis"],"origin":"ai"},{"id":"muscle-energy-systems~ai-7","moduleId":"muscle-energy-systems","stem":"In what way is the aerobic metabolism of glucose linked to muscle contraction?","options":[{"id":"a","text":"It directly powers the cross-bridge cycle"},{"id":"b","text":"It is the primary energy source for short bursts of activity"},{"id":"c","text":"It provides sustained ATP for prolonged muscle contraction"},{"id":"d","text":"It generates lactate for muscle energy"}],"answerId":"c","explanation":"Aerobic metabolism provides a high yield of ATP, sustaining prolonged muscle contraction during endurance activities.","kind":"integration","linkedModuleIds":["muscle-contraction-crossbridge"],"origin":"ai"}],"respiratory-congenital-anomalies":[{"id":"respiratory-congenital-anomalies~ai-0","moduleId":"respiratory-congenital-anomalies","stem":"What is the most common type of tracheo-oesophageal fistula?","options":[{"id":"a","text":"Oesophageal atresia with distal TEF"},{"id":"b","text":"Oesophageal atresia with proximal TEF"},{"id":"c","text":"Isolated TEF"},{"id":"d","text":"Oesophageal atresia without TEF"}],"answerId":"a","explanation":"The most common type is oesophageal atresia with a distal tracheo-oesophageal fistula.","kind":"recall","origin":"ai"},{"id":"respiratory-congenital-anomalies~ai-1","moduleId":"respiratory-congenital-anomalies","stem":"What is the primary mechanism leading to pulmonary hypoplasia in congenital diaphragmatic hernia?","options":[{"id":"a","text":"Inadequate surfactant production"},{"id":"b","text":"Compression of the lung by herniated abdominal contents"},{"id":"c","text":"Genetic mutations affecting lung development"},{"id":"d","text":"Infection during pregnancy"}],"answerId":"b","explanation":"Pulmonary hypoplasia occurs due to compression of the lung by herniated abdominal contents in congenital diaphragmatic hernia.","kind":"mechanism","origin":"ai"},{"id":"respiratory-congenital-anomalies~ai-2","moduleId":"respiratory-congenital-anomalies","stem":"A newborn presents with a scaphoid abdomen and bowel sounds in the chest. What is the most likely diagnosis?","options":[{"id":"a","text":"Oesophageal atresia"},{"id":"b","text":"Congenital diaphragmatic hernia"},{"id":"c","text":"Pulmonary hypoplasia"},{"id":"d","text":"Neonatal respiratory distress syndrome"}],"answerId":"b","explanation":"The presentation is characteristic of congenital diaphragmatic hernia, where abdominal contents herniate into the thorax.","kind":"clinical","origin":"ai"},{"id":"respiratory-congenital-anomalies~ai-3","moduleId":"respiratory-congenital-anomalies","stem":"Which of the following is a consequence of congenital diaphragmatic hernia?","options":[{"id":"a","text":"Increased lung volume"},{"id":"b","text":"Pulmonary hypoplasia"},{"id":"c","text":"Normal lung development"},{"id":"d","text":"Increased amniotic fluid"}],"answerId":"b","explanation":"The main consequence of congenital diaphragmatic hernia is pulmonary hypoplasia due to lung compression.","kind":"trap","origin":"ai"},{"id":"respiratory-congenital-anomalies~ai-4","moduleId":"respiratory-congenital-anomalies","stem":"What is the primary treatment for neonatal respiratory distress syndrome?","options":[{"id":"a","text":"Antibiotics"},{"id":"b","text":"Exogenous surfactant"},{"id":"c","text":"Surgical intervention"},{"id":"d","text":"High-flow oxygen therapy"}],"answerId":"b","explanation":"The primary treatment for neonatal respiratory distress syndrome is the administration of exogenous surfactant.","kind":"recall","origin":"ai"},{"id":"respiratory-congenital-anomalies~ai-5","moduleId":"respiratory-congenital-anomalies","stem":"How does oligohydramnios contribute to pulmonary hypoplasia?","options":[{"id":"a","text":"By reducing fetal movement"},{"id":"b","text":"By increasing lung fluid"},{"id":"c","text":"By compressing the thoracic cavity"},{"id":"d","text":"By promoting airway obstruction"}],"answerId":"a","explanation":"Oligohydramnios limits fetal movement, which is essential for normal lung development, leading to pulmonary hypoplasia.","kind":"mechanism","origin":"ai"},{"id":"respiratory-congenital-anomalies~ai-6","moduleId":"respiratory-congenital-anomalies","stem":"How do congenital respiratory anomalies relate to the classification of congenital anomalies?","options":[{"id":"a","text":"They are classified based on genetic factors"},{"id":"b","text":"They are primarily classified by their anatomical location"},{"id":"c","text":"They are classified by their developmental origin"},{"id":"d","text":"They have no relation to classification systems"}],"answerId":"c","explanation":"Congenital respiratory anomalies are classified by their developmental origin, which is essential for understanding their pathophysiology.","kind":"integration","linkedModuleIds":["congenital-anomaly-classification"],"origin":"ai"},{"id":"respiratory-congenital-anomalies~ai-7","moduleId":"respiratory-congenital-anomalies","stem":"Which developmental stage of the respiratory system is most affected by congenital respiratory anomalies?","options":[{"id":"a","text":"Embryonic stage"},{"id":"b","text":"Pseudoglandular stage"},{"id":"c","text":"Canalicular stage"},{"id":"d","text":"Saccular stage"}],"answerId":"a","explanation":"Congenital respiratory anomalies often arise from issues during the embryonic stage of lung development.","kind":"integration","linkedModuleIds":["respiratory-development-stages"],"origin":"ai"}],"motor-unit-recruitment":[{"id":"motor-unit-recruitment~ai-0","moduleId":"motor-unit-recruitment","stem":"What defines a motor unit?","options":[{"id":"a","text":"One motor neuron and all muscle fibers it innervates"},{"id":"b","text":"One muscle fiber and its associated blood supply"},{"id":"c","text":"All muscle fibers in a muscle group"},{"id":"d","text":"One motor neuron and its synaptic connections"}],"answerId":"a","explanation":"A motor unit consists of one motor neuron and all the muscle fibers it innervates, functioning as the basic unit of muscle contraction.","kind":"recall","origin":"ai"},{"id":"motor-unit-recruitment~ai-1","moduleId":"motor-unit-recruitment","stem":"Which motor units are recruited first according to the size principle?","options":[{"id":"a","text":"Type II fast-twitch units"},{"id":"b","text":"Type I slow-twitch units"},{"id":"c","text":"Type IIb fast-twitch units"},{"id":"d","text":"Type IIA intermediate units"}],"answerId":"b","explanation":"According to the size principle, Type I slow-twitch units are recruited first for low-force tasks.","kind":"recall","origin":"ai"},{"id":"motor-unit-recruitment~ai-2","moduleId":"motor-unit-recruitment","stem":"How does asynchronous recruitment of motor units affect muscle fatigue?","options":[{"id":"a","text":"Increases immediate fatigue"},{"id":"b","text":"Delays fatigue"},{"id":"c","text":"Has no effect on fatigue"},{"id":"d","text":"Causes muscle atrophy"}],"answerId":"b","explanation":"Asynchronous recruitment allows different motor units to take turns firing, which helps delay muscle fatigue during sustained efforts.","kind":"mechanism","origin":"ai"},{"id":"motor-unit-recruitment~ai-3","moduleId":"motor-unit-recruitment","stem":"A patient presents with muscle wasting after nerve injury. What is the underlying mechanism?","options":[{"id":"a","text":"Increased motor unit recruitment"},{"id":"b","text":"Loss of the motor unit"},{"id":"c","text":"Enhanced muscle fiber hypertrophy"},{"id":"d","text":"Increased type I fiber recruitment"}],"answerId":"b","explanation":"Muscle wasting occurs due to the loss of the motor unit following denervation, leading to atrophy of the affected muscle fibers.","kind":"clinical","origin":"ai"},{"id":"motor-unit-recruitment~ai-4","moduleId":"motor-unit-recruitment","stem":"Which statement about motor unit recruitment is FALSE?","options":[{"id":"a","text":"Small motor units are recruited first"},{"id":"b","text":"Large motor units are recruited last"},{"id":"c","text":"All motor units contract simultaneously"},{"id":"d","text":"Motor units are recruited based on force demand"}],"answerId":"c","explanation":"The statement that all motor units contract simultaneously is false; motor units contract in an all-or-none manner but not all at once.","kind":"trap","origin":"ai"},{"id":"motor-unit-recruitment~ai-5","moduleId":"motor-unit-recruitment","stem":"How does muscle fiber type influence fatigue during prolonged exercise?","options":[{"id":"a","text":"Type I fibers fatigue faster than Type II"},{"id":"b","text":"Type II fibers are more resistant to fatigue"},{"id":"c","text":"Type I fibers are more fatigue-resistant"},{"id":"d","text":"Type IIA fibers are the least fatigue-resistant"}],"answerId":"c","explanation":"Type I fibers are slow-twitch and more fatigue-resistant, making them better suited for prolonged, low-intensity activities.","kind":"integration","linkedModuleIds":["muscle-fiber-types-fatigue"],"origin":"ai"},{"id":"motor-unit-recruitment~ai-6","moduleId":"motor-unit-recruitment","stem":"What is the role of rate coding in muscle contraction?","options":[{"id":"a","text":"Increases the number of motor units recruited"},{"id":"b","text":"Increases the firing frequency of motor units"},{"id":"c","text":"Decreases muscle tone"},{"id":"d","text":"Reduces muscle fiber size"}],"answerId":"b","explanation":"Rate coding refers to the increase in firing frequency of already recruited motor units to enhance muscle contraction strength.","kind":"mechanism","origin":"ai"},{"id":"motor-unit-recruitment~ai-7","moduleId":"motor-unit-recruitment","stem":"What happens to muscle tone at rest?","options":[{"id":"a","text":"All motor units are inactive"},{"id":"b","text":"A small number of motor units fire asynchronously"},{"id":"c","text":"Only large motor units are active"},{"id":"d","text":"Muscle fibers undergo hypertrophy"}],"answerId":"b","explanation":"Muscle tone at rest is maintained by a small number of motor units firing in rotation, which helps prevent fatigue.","kind":"recall","origin":"ai"}],"airway-conducting-respiratory-zones":[{"id":"airway-conducting-respiratory-zones~ai-0","moduleId":"airway-conducting-respiratory-zones","stem":"What is the primary function of the conducting zone of the airways?","options":[{"id":"a","text":"Gas exchange"},{"id":"b","text":"Air conditioning"},{"id":"c","text":"Mucus secretion"},{"id":"d","text":"Ciliary movement"}],"answerId":"b","explanation":"The conducting zone's main role is to condition and transport air without participating in gas exchange.","kind":"recall","origin":"ai"},{"id":"airway-conducting-respiratory-zones~ai-1","moduleId":"airway-conducting-respiratory-zones","stem":"Which type of epithelium is found in the upper conducting airways?","options":[{"id":"a","text":"Simple cuboidal"},{"id":"b","text":"Simple columnar"},{"id":"c","text":"Pseudostratified ciliated columnar"},{"id":"d","text":"Stratified squamous"}],"answerId":"c","explanation":"The upper conducting airways are lined with pseudostratified ciliated columnar epithelium, which includes goblet cells.","kind":"recall","origin":"ai"},{"id":"airway-conducting-respiratory-zones~ai-2","moduleId":"airway-conducting-respiratory-zones","stem":"What is the last purely conducting airway in the respiratory tract?","options":[{"id":"a","text":"Respiratory bronchiole"},{"id":"b","text":"Alveolar duct"},{"id":"c","text":"Terminal bronchiole"},{"id":"d","text":"Tertiary bronchi"}],"answerId":"c","explanation":"The terminal bronchiole is the last structure that is purely conducting and does not participate in gas exchange.","kind":"recall","origin":"ai"},{"id":"airway-conducting-respiratory-zones~ai-3","moduleId":"airway-conducting-respiratory-zones","stem":"Why do bronchioles collapse during an asthma attack?","options":[{"id":"a","text":"Excess mucus production"},{"id":"b","text":"Increased cartilage support"},{"id":"c","text":"Decreased smooth muscle tone"},{"id":"d","text":"Lack of cartilage support"}],"answerId":"d","explanation":"Bronchioles lack cartilage, making them susceptible to collapse due to increased smooth muscle contraction in asthma.","kind":"mechanism","origin":"ai"},{"id":"airway-conducting-respiratory-zones~ai-4","moduleId":"airway-conducting-respiratory-zones","stem":"What is the anatomical dead space volume in the conducting airways?","options":[{"id":"a","text":"~50 mL"},{"id":"b","text":"~150 mL"},{"id":"c","text":"~250 mL"},{"id":"d","text":"~350 mL"}],"answerId":"b","explanation":"The anatomical dead space, which includes the conducting airways, is approximately 150 mL.","kind":"recall","origin":"ai"},{"id":"airway-conducting-respiratory-zones~ai-5","moduleId":"airway-conducting-respiratory-zones","stem":"Which cells in the bronchioles secrete a protective surfactant-like fluid?","options":[{"id":"a","text":"Goblet cells"},{"id":"b","text":"Ciliated cells"},{"id":"c","text":"Club (Clara) cells"},{"id":"d","text":"Alveolar macrophages"}],"answerId":"c","explanation":"Club (Clara) cells in the bronchioles secrete a protective fluid and have detoxifying functions.","kind":"recall","origin":"ai"},{"id":"airway-conducting-respiratory-zones~ai-6","moduleId":"airway-conducting-respiratory-zones","stem":"Gas exchange begins at which structure in the respiratory system?","options":[{"id":"a","text":"Terminal bronchiole"},{"id":"b","text":"Respiratory bronchiole"},{"id":"c","text":"Alveolar sac"},{"id":"d","text":"Primary bronchus"}],"answerId":"b","explanation":"Gas exchange begins at the respiratory bronchioles, which are the first structures containing alveoli.","kind":"trap","origin":"ai"},{"id":"airway-conducting-respiratory-zones~ai-7","moduleId":"airway-conducting-respiratory-zones","stem":"How does the anatomical dead space relate to physiological dead space?","options":[{"id":"a","text":"Anatomical dead space is larger than physiological dead space"},{"id":"b","text":"Physiological dead space only includes anatomical dead space"},{"id":"c","text":"Physiological dead space includes anatomical and alveolar dead space"},{"id":"d","text":"They are identical measurements"}],"answerId":"c","explanation":"Physiological dead space includes both anatomical dead space and any alveolar dead space where ventilation occurs but perfusion does not.","kind":"integration","linkedModuleIds":["lung-volumes-ventilation"],"origin":"ai"},{"id":"airway-conducting-respiratory-zones~ai-8","moduleId":"airway-conducting-respiratory-zones","stem":"Which structure is the first to participate in gas exchange?","options":[{"id":"a","text":"Terminal bronchiole"},{"id":"b","text":"Alveolar duct"},{"id":"c","text":"Respiratory bronchiole"},{"id":"d","text":"Secondary bronchus"}],"answerId":"c","explanation":"The respiratory bronchiole is the first structure in the airway tree that contains alveoli and participates in gas exchange.","kind":"integration","linkedModuleIds":["alveoli-pneumocytes-respiratory-membrane"],"origin":"ai"}],"nmj-drugs-disorders":[{"id":"nmj-drugs-disorders~ai-0","moduleId":"nmj-drugs-disorders","stem":"What is the mechanism of action of botulinum toxin?","options":[{"id":"a","text":"Inhibits acetylcholinesterase"},{"id":"b","text":"Cleaves SNARE proteins"},{"id":"c","text":"Blocks nicotinic receptors"},{"id":"d","text":"Increases presynaptic calcium influx"}],"answerId":"b","explanation":"Botulinum toxin cleaves SNARE proteins, preventing vesicle fusion and ACh release, leading to flaccid paralysis.","kind":"mechanism","origin":"ai"},{"id":"nmj-drugs-disorders~ai-1","moduleId":"nmj-drugs-disorders","stem":"Which clinical finding is characteristic of myasthenia gravis?","options":[{"id":"a","text":"Proximal weakness improving with use"},{"id":"b","text":"Fatigable ptosis"},{"id":"c","text":"Descending weakness after food"},{"id":"d","text":"Flaccid paralysis with no prior activity"}],"answerId":"b","explanation":"Myasthenia gravis is characterized by fatigable weakness, particularly ptosis and diplopia, which worsens with use.","kind":"recall","origin":"ai"},{"id":"nmj-drugs-disorders~ai-2","moduleId":"nmj-drugs-disorders","stem":"In Lambert-Eaton myasthenic syndrome, which of the following is true?","options":[{"id":"a","text":"Weakness improves with repeated use"},{"id":"b","text":"Weakness worsens with rest"},{"id":"c","text":"It is caused by antibodies against ACh receptors"},{"id":"d","text":"It presents with cholinergic crisis"}],"answerId":"a","explanation":"In LEMS, weakness improves with repeated use due to increased presynaptic calcium influx leading to more ACh release.","kind":"trap","origin":"ai"},{"id":"nmj-drugs-disorders~ai-3","moduleId":"nmj-drugs-disorders","stem":"What is the primary therapeutic use of neostigmine?","options":[{"id":"a","text":"To induce paralysis during surgery"},{"id":"b","text":"To treat myasthenia gravis"},{"id":"c","text":"To enhance ACh release in LEMS"},{"id":"d","text":"To reverse botulinum toxin effects"}],"answerId":"b","explanation":"Neostigmine is an acetylcholinesterase inhibitor used primarily to treat myasthenia gravis by increasing ACh levels at the neuromuscular junction.","kind":"recall","origin":"ai"},{"id":"nmj-drugs-disorders~ai-4","moduleId":"nmj-drugs-disorders","stem":"Which of the following is a feature of cholinergic crisis?","options":[{"id":"a","text":"Proximal muscle weakness"},{"id":"b","text":"Flaccid paralysis"},{"id":"c","text":"Fatigable weakness"},{"id":"d","text":"Improvement with repeated use"}],"answerId":"b","explanation":"Cholinergic crisis presents with flaccid paralysis due to excessive ACh at the neuromuscular junction.","kind":"recall","origin":"ai"},{"id":"nmj-drugs-disorders~ai-5","moduleId":"nmj-drugs-disorders","stem":"How does succinylcholine cause initial muscle fasciculations?","options":[{"id":"a","text":"By blocking ACh receptors"},{"id":"b","text":"By inhibiting AChE"},{"id":"c","text":"By acting as a nicotinic agonist"},{"id":"d","text":"By decreasing presynaptic calcium"}],"answerId":"c","explanation":"Succinylcholine is a nicotinic agonist that causes initial depolarization and fasciculations before leading to paralysis.","kind":"mechanism","origin":"ai"},{"id":"nmj-drugs-disorders~ai-6","moduleId":"nmj-drugs-disorders","stem":"How does myasthenia gravis differ from Lambert-Eaton syndrome in terms of muscle use?","options":[{"id":"a","text":"Both worsen with use"},{"id":"b","text":"MG worsens, LEMS improves"},{"id":"c","text":"Both improve with use"},{"id":"d","text":"LEMS worsens, MG improves"}],"answerId":"b","explanation":"In myasthenia gravis, muscle weakness worsens with use due to receptor loss, while in LEMS, weakness improves with use due to increased ACh release.","kind":"integration","linkedModuleIds":["nmj-structure-transmission"],"origin":"ai"},{"id":"nmj-drugs-disorders~ai-7","moduleId":"nmj-drugs-disorders","stem":"What is the effect of organophosphate poisoning on neuromuscular transmission?","options":[{"id":"a","text":"Increased ACh release"},{"id":"b","text":"Decreased ACh levels"},{"id":"c","text":"Inhibition of AChE"},{"id":"d","text":"Blockade of nicotinic receptors"}],"answerId":"c","explanation":"Organophosphate poisoning inhibits acetylcholinesterase, leading to increased levels of ACh at the neuromuscular junction.","kind":"integration","linkedModuleIds":["clostridia-anaerobic-pathogens"],"origin":"ai"}],"muscle-fiber-types-fatigue":[{"id":"muscle-fiber-types-fatigue~ai-0","moduleId":"muscle-fiber-types-fatigue","stem":"Which type of muscle fiber is characterized by high myoglobin content and resistance to fatigue?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type IIa"},{"id":"c","text":"Type IIx"},{"id":"d","text":"Type IIb"}],"answerId":"a","explanation":"Type I fibers are slow oxidative fibers that are rich in myoglobin and mitochondria, making them fatigue-resistant.","kind":"recall","origin":"ai"},{"id":"muscle-fiber-types-fatigue~ai-1","moduleId":"muscle-fiber-types-fatigue","stem":"What primarily causes peripheral muscle fatigue during sustained exercise?","options":[{"id":"a","text":"Depletion of ATP"},{"id":"b","text":"Accumulation of inorganic phosphate"},{"id":"c","text":"Increased calcium release"},{"id":"d","text":"Decreased blood flow"}],"answerId":"b","explanation":"Peripheral fatigue is mainly due to the accumulation of metabolic by-products such as inorganic phosphate and H⁺, not ATP depletion.","kind":"mechanism","origin":"ai"},{"id":"muscle-fiber-types-fatigue~ai-2","moduleId":"muscle-fiber-types-fatigue","stem":"Which muscle fiber type is predominantly recruited during high-intensity, short-duration activities?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type IIa"},{"id":"c","text":"Type IIx"},{"id":"d","text":"Type IIb"}],"answerId":"c","explanation":"Type IIx fibers are fast glycolytic and are primarily recruited for powerful, short bursts of activity.","kind":"recall","origin":"ai"},{"id":"muscle-fiber-types-fatigue~ai-3","moduleId":"muscle-fiber-types-fatigue","stem":"A marathon runner has a higher proportion of which muscle fiber type compared to a sprinter?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type IIa"},{"id":"c","text":"Type IIx"},{"id":"d","text":"Type IIb"}],"answerId":"a","explanation":"Marathon runners typically have a higher proportion of Type I fibers, which are suited for endurance activities.","kind":"recall","origin":"ai"},{"id":"muscle-fiber-types-fatigue~ai-4","moduleId":"muscle-fiber-types-fatigue","stem":"Which of the following best explains why sprinting muscles fatigue faster than postural muscles?","options":[{"id":"a","text":"Higher ATP consumption"},{"id":"b","text":"Greater reliance on anaerobic metabolism"},{"id":"c","text":"Increased myoglobin content"},{"id":"d","text":"More capillary density"}],"answerId":"b","explanation":"Sprinting muscles, which are predominantly Type II fibers, rely more on anaerobic metabolism, leading to quicker fatigue compared to the aerobic Type I fibers used in postural muscles.","kind":"mechanism","origin":"ai"},{"id":"muscle-fiber-types-fatigue~ai-5","moduleId":"muscle-fiber-types-fatigue","stem":"During a prolonged exercise session, a patient experiences muscle fatigue. Which of the following findings is most likely?","options":[{"id":"a","text":"Increased ATP levels"},{"id":"b","text":"Decreased pH due to lactate accumulation"},{"id":"c","text":"Increased calcium release"},{"id":"d","text":"Increased muscle temperature"}],"answerId":"b","explanation":"Prolonged exercise leads to lactate accumulation, which decreases pH and contributes to muscle fatigue.","kind":"clinical","origin":"ai"},{"id":"muscle-fiber-types-fatigue~ai-6","moduleId":"muscle-fiber-types-fatigue","stem":"How does endurance training affect muscle fiber characteristics?","options":[{"id":"a","text":"Increases Type IIx fibers"},{"id":"b","text":"Decreases mitochondrial density"},{"id":"c","text":"Increases capillary density"},{"id":"d","text":"Decreases oxidative enzymes"}],"answerId":"c","explanation":"Endurance training increases mitochondrial and capillary density, enhancing the oxidative capacity of muscle fibers.","kind":"mechanism","origin":"ai"},{"id":"muscle-fiber-types-fatigue~ai-7","moduleId":"muscle-fiber-types-fatigue","stem":"How does the size principle relate to muscle fiber recruitment during exercise?","options":[{"id":"a","text":"Smaller fibers are recruited for high-force tasks"},{"id":"b","text":"Larger fibers are recruited first"},{"id":"c","text":"Type I fibers are recruited last"},{"id":"d","text":"Recruitment is based on fiber fatigue resistance"}],"answerId":"a","explanation":"The size principle states that smaller motor units (Type I fibers) are recruited first for low-force tasks, with larger units recruited as force demands increase.","kind":"integration","linkedModuleIds":["motor-unit-recruitment"],"origin":"ai"},{"id":"muscle-fiber-types-fatigue~ai-8","moduleId":"muscle-fiber-types-fatigue","stem":"Which energy system is primarily utilized by Type IIx muscle fibers during maximal effort?","options":[{"id":"a","text":"Aerobic metabolism"},{"id":"b","text":"Anaerobic glycolysis"},{"id":"c","text":"Oxidative phosphorylation"},{"id":"d","text":"Beta-oxidation"}],"answerId":"b","explanation":"Type IIx fibers primarily rely on anaerobic glycolysis for energy during short, intense bursts of activity.","kind":"integration","linkedModuleIds":["muscle-energy-systems"],"origin":"ai"}],"muscle-twitch-tetanus-mechanics":[{"id":"muscle-twitch-tetanus-mechanics~ai-0","moduleId":"muscle-twitch-tetanus-mechanics","stem":"What is the primary mechanism by which a muscle generates greater tension with increased frequency of stimulation?","options":[{"id":"a","text":"Treppe"},{"id":"b","text":"Isometric contraction"},{"id":"c","text":"Temporal summation"},{"id":"d","text":"Length-tension relationship"}],"answerId":"c","explanation":"Temporal summation occurs when successive stimuli arrive before the muscle fully relaxes, increasing tension.","kind":"mechanism","origin":"ai"},{"id":"muscle-twitch-tetanus-mechanics~ai-1","moduleId":"muscle-twitch-tetanus-mechanics","stem":"During which type of contraction does the muscle generate tension without changing its length?","options":[{"id":"a","text":"Isometric contraction"},{"id":"b","text":"Isotonic contraction"},{"id":"c","text":"Eccentric contraction"},{"id":"d","text":"Concentric contraction"}],"answerId":"a","explanation":"Isometric contraction involves tension generation without any change in muscle length.","kind":"recall","origin":"ai"},{"id":"muscle-twitch-tetanus-mechanics~ai-2","moduleId":"muscle-twitch-tetanus-mechanics","stem":"What phenomenon describes the progressive increase in force during the first few contractions at the same stimulus strength?","options":[{"id":"a","text":"Tetanus"},{"id":"b","text":"Treppe"},{"id":"c","text":"Summation"},{"id":"d","text":"Eccentric contraction"}],"answerId":"b","explanation":"Treppe, or the staircase effect, describes the increase in force with repeated contractions at the same strength.","kind":"recall","origin":"ai"},{"id":"muscle-twitch-tetanus-mechanics~ai-3","moduleId":"muscle-twitch-tetanus-mechanics","stem":"What is the optimal condition for maximal active tension in a muscle?","options":[{"id":"a","text":"Maximal stretch of the muscle"},{"id":"b","text":"Minimal overlap of actin and myosin"},{"id":"c","text":"Ideal overlap of actin and myosin"},{"id":"d","text":"Complete relaxation of the muscle"}],"answerId":"c","explanation":"Maximal active tension occurs at an optimal sarcomere length where there is ideal overlap of actin and myosin filaments.","kind":"recall","origin":"ai"},{"id":"muscle-twitch-tetanus-mechanics~ai-4","moduleId":"muscle-twitch-tetanus-mechanics","stem":"Which of the following best describes the difference between treppe and frequency summation?","options":[{"id":"a","text":"Both require increasing stimulus frequency"},{"id":"b","text":"Treppe occurs at constant frequency, summation requires increasing frequency"},{"id":"c","text":"Treppe is a type of tetanus"},{"id":"d","text":"Both result in maximal muscle tension"}],"answerId":"b","explanation":"Treppe occurs with repeated contractions at the same frequency, while summation requires increasing frequency to add tension.","kind":"trap","origin":"ai"},{"id":"muscle-twitch-tetanus-mechanics~ai-5","moduleId":"muscle-twitch-tetanus-mechanics","stem":"What is the relationship between muscle length and tension generation according to the length-tension relationship?","options":[{"id":"a","text":"Tension increases with muscle length only"},{"id":"b","text":"Tension is maximal at extreme lengths"},{"id":"c","text":"Tension is maximal at an optimal length"},{"id":"d","text":"Tension is independent of muscle length"}],"answerId":"c","explanation":"The length-tension relationship states that tension is maximal at an optimal length where actin and myosin overlap is ideal.","kind":"mechanism","origin":"ai"},{"id":"muscle-twitch-tetanus-mechanics~ai-6","moduleId":"muscle-twitch-tetanus-mechanics","stem":"How does the Frank-Starling mechanism relate to muscle tension generation?","options":[{"id":"a","text":"It describes the relationship between muscle length and tension"},{"id":"b","text":"It explains the mechanism of tetanus"},{"id":"c","text":"It is unrelated to muscle mechanics"},{"id":"d","text":"It only applies to cardiac muscle"}],"answerId":"a","explanation":"The Frank-Starling mechanism explains how increased muscle length leads to increased tension, similar to skeletal muscle's length-tension relationship.","kind":"integration","linkedModuleIds":["frank-starling-cardiac-function"],"origin":"ai"},{"id":"muscle-twitch-tetanus-mechanics~ai-7","moduleId":"muscle-twitch-tetanus-mechanics","stem":"What is the effect of increased calcium levels during repeated muscle contractions?","options":[{"id":"a","text":"Decreased force generation"},{"id":"b","text":"Increased force generation"},{"id":"c","text":"No effect on force"},{"id":"d","text":"Increased muscle length"}],"answerId":"b","explanation":"Increased calcium levels during repeated contractions enhance force generation, contributing to phenomena like treppe.","kind":"integration","linkedModuleIds":["muscle-contraction-crossbridge"],"origin":"ai"}],"muscle-contraction-crossbridge":[{"id":"muscle-contraction-crossbridge~ai-0","moduleId":"muscle-contraction-crossbridge","stem":"What is the primary role of ATP in the cross-bridge cycle?","options":[{"id":"a","text":"To energize the power stroke"},{"id":"b","text":"To detach myosin from actin"},{"id":"c","text":"To bind to actin"},{"id":"d","text":"To release calcium from the sarcoplasmic reticulum"}],"answerId":"b","explanation":"ATP is crucial for detaching myosin from actin, allowing the cross-bridge cycle to continue.","kind":"recall","origin":"ai"},{"id":"muscle-contraction-crossbridge~ai-1","moduleId":"muscle-contraction-crossbridge","stem":"Which statement correctly describes the sliding filament theory?","options":[{"id":"a","text":"Thick filaments shorten during contraction"},{"id":"b","text":"I band and H zone shorten while A band remains constant"},{"id":"c","text":"Thin filaments pull thick filaments toward the Z line"},{"id":"d","text":"Myosin heads do not interact with actin during contraction"}],"answerId":"b","explanation":"During contraction, the I band and H zone shorten while the A band remains unchanged, as thick and thin filaments slide past each other.","kind":"recall","origin":"ai"},{"id":"muscle-contraction-crossbridge~ai-2","moduleId":"muscle-contraction-crossbridge","stem":"What occurs during the power stroke of the cross-bridge cycle?","options":[{"id":"a","text":"Myosin binds to actin"},{"id":"b","text":"Myosin releases ADP and Pi"},{"id":"c","text":"Myosin detaches from actin"},{"id":"d","text":"ATP binds to myosin"}],"answerId":"b","explanation":"During the power stroke, the myosin head pivots, pulling the actin filament and releasing ADP and Pi.","kind":"mechanism","origin":"ai"},{"id":"muscle-contraction-crossbridge~ai-3","moduleId":"muscle-contraction-crossbridge","stem":"A patient presents with muscle stiffness after death. What is the underlying mechanism?","options":[{"id":"a","text":"Excess calcium in the muscle"},{"id":"b","text":"ATP depletion preventing myosin detachment"},{"id":"c","text":"Increased lactic acid production"},{"id":"d","text":"Decreased actin availability"}],"answerId":"b","explanation":"Rigor mortis occurs due to ATP depletion, which prevents myosin from detaching from actin, locking the cross-bridges.","kind":"clinical","origin":"ai"},{"id":"muscle-contraction-crossbridge~ai-4","moduleId":"muscle-contraction-crossbridge","stem":"Which of the following best explains why rigor mortis occurs?","options":[{"id":"a","text":"ATP is needed for muscle contraction"},{"id":"b","text":"ATP is needed for muscle relaxation"},{"id":"c","text":"Calcium levels remain high"},{"id":"d","text":"Myosin heads cannot bind to actin"}],"answerId":"b","explanation":"Rigor mortis occurs because ATP is required to detach myosin from actin; without it, the muscle remains contracted.","kind":"trap","origin":"ai"},{"id":"muscle-contraction-crossbridge~ai-5","moduleId":"muscle-contraction-crossbridge","stem":"How does the role of calcium relate to the cross-bridge cycle?","options":[{"id":"a","text":"Calcium binds to myosin to initiate contraction"},{"id":"b","text":"Calcium binds to troponin, exposing actin binding sites"},{"id":"c","text":"Calcium is released during the power stroke"},{"id":"d","text":"Calcium is needed to detach myosin from actin"}],"answerId":"b","explanation":"Calcium binds to troponin, causing a conformational change that exposes binding sites on actin for myosin.","kind":"integration","linkedModuleIds":["excitation-contraction-coupling"],"origin":"ai"},{"id":"muscle-contraction-crossbridge~ai-6","moduleId":"muscle-contraction-crossbridge","stem":"In what way does the sliding filament theory integrate with muscle energy systems?","options":[{"id":"a","text":"Energy systems provide ATP for muscle contraction"},{"id":"b","text":"Energy systems are not involved in the sliding filament mechanism"},{"id":"c","text":"Sliding filament theory does not require ATP"},{"id":"d","text":"Energy systems only affect muscle relaxation"}],"answerId":"a","explanation":"The sliding filament theory relies on ATP generated by muscle energy systems to facilitate contraction and relaxation.","kind":"integration","linkedModuleIds":["muscle-energy-systems"],"origin":"ai"}],"fracture-healing":[{"id":"fracture-healing~ai-0","moduleId":"fracture-healing","stem":"What is the first stage of secondary fracture healing?","options":[{"id":"a","text":"Soft callus formation"},{"id":"b","text":"Haematoma and inflammation"},{"id":"c","text":"Woven bone formation"},{"id":"d","text":"Remodelling"}],"answerId":"b","explanation":"The first stage involves the formation of a haematoma and inflammation, which is crucial for initiating the healing process.","kind":"recall","origin":"ai"},{"id":"fracture-healing~ai-1","moduleId":"fracture-healing","stem":"Which type of fracture healing occurs without a visible callus?","options":[{"id":"a","text":"Secondary healing"},{"id":"b","text":"Primary healing"},{"id":"c","text":"Delayed union"},{"id":"d","text":"Malunion"}],"answerId":"b","explanation":"Primary healing occurs under rigid fixation and involves direct bone formation across the fracture gap, resulting in no visible callus.","kind":"recall","origin":"ai"},{"id":"fracture-healing~ai-2","moduleId":"fracture-healing","stem":"What is the mechanism of the transition from soft callus to hard callus?","options":[{"id":"a","text":"Intramembranous ossification"},{"id":"b","text":"Endochondral ossification"},{"id":"c","text":"Fibrocartilage formation"},{"id":"d","text":"Bone remodelling"}],"answerId":"b","explanation":"The transition from soft callus to hard callus involves endochondral ossification, where the fibrocartilaginous callus is replaced by woven bone.","kind":"mechanism","origin":"ai"},{"id":"fracture-healing~ai-3","moduleId":"fracture-healing","stem":"A patient presents with a fracture that has not healed after several months. What is the most likely complication?","options":[{"id":"a","text":"Malunion"},{"id":"b","text":"Non-union"},{"id":"c","text":"Delayed union"},{"id":"d","text":"Infection"}],"answerId":"b","explanation":"Non-union is characterized by the failure of the fracture to heal after an extended period, often due to factors like poor blood supply or excessive movement.","kind":"clinical","origin":"ai"},{"id":"fracture-healing~ai-4","moduleId":"fracture-healing","stem":"Which of the following factors is least likely to impair fracture healing?","options":[{"id":"a","text":"Smoking"},{"id":"b","text":"Adequate blood supply"},{"id":"c","text":"Diabetes"},{"id":"d","text":"Corticosteroids"}],"answerId":"b","explanation":"Adequate blood supply is essential for fracture healing and does not impair the process, unlike the other options.","kind":"trap","origin":"ai"},{"id":"fracture-healing~ai-5","moduleId":"fracture-healing","stem":"How does the process of endochondral ossification relate to fracture healing?","options":[{"id":"a","text":"It is the only method of bone healing"},{"id":"b","text":"It occurs during the remodelling phase"},{"id":"c","text":"It is involved in the formation of the hard callus"},{"id":"d","text":"It prevents malunion"}],"answerId":"c","explanation":"Endochondral ossification is crucial for the formation of the hard callus during secondary fracture healing.","kind":"integration","linkedModuleIds":["ossification"],"origin":"ai"},{"id":"fracture-healing~ai-6","moduleId":"fracture-healing","stem":"What is a common complication of fractures that can also be seen in myocardial infarction?","options":[{"id":"a","text":"Avascular necrosis"},{"id":"b","text":"Non-union"},{"id":"c","text":"Infection"},{"id":"d","text":"Delayed union"}],"answerId":"a","explanation":"Avascular necrosis can occur in both fractures and myocardial infarction due to compromised blood supply.","kind":"integration","linkedModuleIds":["mi-complications"],"origin":"ai"}],"excitation-contraction-coupling":[{"id":"excitation-contraction-coupling~ai-0","moduleId":"excitation-contraction-coupling","stem":"What is the primary function of the dihydropyridine receptor (DHPR) in excitation-contraction coupling?","options":[{"id":"a","text":"It releases Ca²⁺ from the sarcoplasmic reticulum"},{"id":"b","text":"It senses depolarization of the T-tubule"},{"id":"c","text":"It binds to troponin C"},{"id":"d","text":"It pumps Ca²⁺ back into the sarcoplasmic reticulum"}],"answerId":"b","explanation":"The DHPR acts as a voltage sensor that detects depolarization and triggers the opening of the ryanodine receptor, leading to Ca²⁺ release.","kind":"mechanism","origin":"ai"},{"id":"excitation-contraction-coupling~ai-1","moduleId":"excitation-contraction-coupling","stem":"What is the role of SERCA in muscle relaxation?","options":[{"id":"a","text":"It binds Ca²⁺ to troponin"},{"id":"b","text":"It pumps Ca²⁺ back into the sarcoplasmic reticulum"},{"id":"c","text":"It opens the ryanodine receptor"},{"id":"d","text":"It generates ATP for muscle contraction"}],"answerId":"b","explanation":"SERCA is an ATP-dependent pump that transports Ca²⁺ back into the sarcoplasmic reticulum, facilitating muscle relaxation.","kind":"recall","origin":"ai"},{"id":"excitation-contraction-coupling~ai-2","moduleId":"excitation-contraction-coupling","stem":"Which of the following statements about muscle contraction is true?","options":[{"id":"a","text":"Relaxation is a passive process requiring no energy"},{"id":"b","text":"Cytosolic Ca²⁺ binds to tropomyosin"},{"id":"c","text":"The troponin-tropomyosin complex shifts upon Ca²⁺ binding"},{"id":"d","text":"Myosin-binding sites on actin are always exposed"}],"answerId":"c","explanation":"Cytosolic Ca²⁺ binds to troponin C, causing a conformational change that moves tropomyosin and exposes myosin-binding sites on actin.","kind":"trap","origin":"ai"},{"id":"excitation-contraction-coupling~ai-3","moduleId":"excitation-contraction-coupling","stem":"What causes malignant hyperthermia?","options":[{"id":"a","text":"Increased ATP production"},{"id":"b","text":"Uncontrolled Ca²⁺ release from the sarcoplasmic reticulum"},{"id":"c","text":"Excessive troponin binding"},{"id":"d","text":"Inhibition of SERCA"}],"answerId":"b","explanation":"Malignant hyperthermia is caused by a mutation in the ryanodine receptor (RYR1), leading to uncontrolled Ca²⁺ release and a hypermetabolic state.","kind":"clinical","origin":"ai"},{"id":"excitation-contraction-coupling~ai-4","moduleId":"excitation-contraction-coupling","stem":"How does the T-tubule system contribute to muscle contraction?","options":[{"id":"a","text":"By storing Ca²⁺"},{"id":"b","text":"By synchronizing action potential propagation"},{"id":"c","text":"By directly binding to actin"},{"id":"d","text":"By inhibiting tropomyosin"}],"answerId":"b","explanation":"The T-tubule system carries the action potential deep into the muscle fiber, ensuring synchronized activation of the entire fiber.","kind":"recall","origin":"ai"},{"id":"excitation-contraction-coupling~ai-5","moduleId":"excitation-contraction-coupling","stem":"How does excitation-contraction coupling relate to the sliding filament theory?","options":[{"id":"a","text":"It explains the role of ATP in muscle contraction"},{"id":"b","text":"It describes how Ca²⁺ release leads to cross-bridge cycling"},{"id":"c","text":"It focuses on the structure of the sarcomere"},{"id":"d","text":"It details neurotransmitter release at the neuromuscular junction"}],"answerId":"b","explanation":"Excitation-contraction coupling describes the mechanism by which an action potential leads to Ca²⁺ release, initiating the cross-bridge cycling described in the sliding filament theory.","kind":"integration","linkedModuleIds":["muscle-contraction-crossbridge"],"origin":"ai"},{"id":"excitation-contraction-coupling~ai-6","moduleId":"excitation-contraction-coupling","stem":"What is the relationship between excitation-contraction coupling and the neuromuscular junction?","options":[{"id":"a","text":"E-C coupling occurs independently of the neuromuscular junction"},{"id":"b","text":"The neuromuscular junction is where Ca²⁺ is released"},{"id":"c","text":"E-C coupling begins with neurotransmitter release at the neuromuscular junction"},{"id":"d","text":"The neuromuscular junction regulates SERCA activity"}],"answerId":"c","explanation":"Excitation-contraction coupling is initiated by the release of neurotransmitters at the neuromuscular junction, leading to muscle action potential generation.","kind":"integration","linkedModuleIds":["nmj-structure-transmission"],"origin":"ai"}],"systemic-pulmonary-circulation":[{"id":"systemic-pulmonary-circulation~ai-0","moduleId":"systemic-pulmonary-circulation","stem":"Which vessel carries deoxygenated blood from the heart to the lungs?","options":[{"id":"a","text":"Pulmonary artery"},{"id":"b","text":"Pulmonary vein"},{"id":"c","text":"Aorta"},{"id":"d","text":"Superior vena cava"}],"answerId":"a","explanation":"The pulmonary artery carries deoxygenated blood from the right ventricle to the lungs for oxygenation.","kind":"recall","origin":"ai"},{"id":"systemic-pulmonary-circulation~ai-1","moduleId":"systemic-pulmonary-circulation","stem":"What is the primary function of arterioles in the circulatory system?","options":[{"id":"a","text":"Conduct blood at high pressure"},{"id":"b","text":"Exchange nutrients and gases"},{"id":"c","text":"Control blood flow and pressure"},{"id":"d","text":"Store blood volume"}],"answerId":"c","explanation":"Arterioles are the main resistance vessels that regulate blood flow and systemic vascular resistance.","kind":"mechanism","origin":"ai"},{"id":"systemic-pulmonary-circulation~ai-2","moduleId":"systemic-pulmonary-circulation","stem":"Which statement about the systemic and pulmonary circuits is true?","options":[{"id":"a","text":"The systemic circuit is low-pressure"},{"id":"b","text":"The pulmonary circuit delivers oxygenated blood"},{"id":"c","text":"Cardiac outputs of both circuits must be equal"},{"id":"d","text":"Veins carry oxygenated blood only"}],"answerId":"c","explanation":"The right and left cardiac outputs must be equal to prevent congestion in either circuit.","kind":"trap","origin":"ai"},{"id":"systemic-pulmonary-circulation~ai-3","moduleId":"systemic-pulmonary-circulation","stem":"What is the role of the hepatic portal system?","options":[{"id":"a","text":"Connects the heart to the lungs"},{"id":"b","text":"Transports oxygenated blood to the liver"},{"id":"c","text":"Links two capillary beds in series"},{"id":"d","text":"Returns blood directly to the heart"}],"answerId":"c","explanation":"The hepatic portal system connects the gut capillaries to the liver sinusoids via the portal vein.","kind":"recall","origin":"ai"},{"id":"systemic-pulmonary-circulation~ai-4","moduleId":"systemic-pulmonary-circulation","stem":"Which vessel type holds approximately 65% of the blood volume?","options":[{"id":"a","text":"Arteries"},{"id":"b","text":"Veins"},{"id":"c","text":"Capillaries"},{"id":"d","text":"Arterioles"}],"answerId":"b","explanation":"Veins are capacitance vessels that can hold a large volume of blood at low pressure.","kind":"recall","origin":"ai"},{"id":"systemic-pulmonary-circulation~ai-5","moduleId":"systemic-pulmonary-circulation","stem":"How does the Frank-Starling mechanism relate to cardiac output in the systemic and pulmonary circuits?","options":[{"id":"a","text":"It ensures equal output by adjusting heart rate"},{"id":"b","text":"It adjusts stroke volume based on venous return"},{"id":"c","text":"It regulates blood pressure in the pulmonary circuit"},{"id":"d","text":"It affects oxygenation of blood in the lungs"}],"answerId":"b","explanation":"The Frank-Starling mechanism states that increased venous return leads to increased stroke volume, ensuring equal outputs in both circuits.","kind":"integration","linkedModuleIds":["frank-starling-cardiac-function"],"origin":"ai"},{"id":"systemic-pulmonary-circulation~ai-6","moduleId":"systemic-pulmonary-circulation","stem":"Which aspect of blood vessel histology is crucial for the function of arterioles?","options":[{"id":"a","text":"Endothelium structure"},{"id":"b","text":"Smooth muscle layer"},{"id":"c","text":"Elastic lamina"},{"id":"d","text":"Adventitia composition"}],"answerId":"b","explanation":"The smooth muscle layer in arterioles allows for regulation of blood flow and pressure through contraction and relaxation.","kind":"integration","linkedModuleIds":["blood-vessel-histology"],"origin":"ai"}],"respiratory-mechanics-compliance":[{"id":"respiratory-mechanics-compliance~ai-0","moduleId":"respiratory-mechanics-compliance","stem":"What is the primary mechanism by which air enters the lungs during quiet inspiration?","options":[{"id":"a","text":"Contraction of the diaphragm and external intercostals"},{"id":"b","text":"Increased intrapleural pressure"},{"id":"c","text":"Active contraction of abdominal muscles"},{"id":"d","text":"Decreased alveolar pressure due to airway resistance"}],"answerId":"a","explanation":"Air enters the lungs during quiet inspiration primarily due to the contraction of the diaphragm and external intercostals, which expands the thoracic cavity and decreases intrapleural pressure.","kind":"mechanism","origin":"ai"},{"id":"respiratory-mechanics-compliance~ai-1","moduleId":"respiratory-mechanics-compliance","stem":"Which condition is characterized by increased lung compliance?","options":[{"id":"a","text":"Pulmonary fibrosis"},{"id":"b","text":"Asthma"},{"id":"c","text":"Emphysema"},{"id":"d","text":"Pneumonia"}],"answerId":"c","explanation":"Emphysema is characterized by increased lung compliance due to the destruction of elastic tissue, making it easier to inflate the lungs.","kind":"recall","origin":"ai"},{"id":"respiratory-mechanics-compliance~ai-2","moduleId":"respiratory-mechanics-compliance","stem":"What happens to intrapleural pressure during a pneumothorax?","options":[{"id":"a","text":"It becomes more negative"},{"id":"b","text":"It becomes positive"},{"id":"c","text":"It remains unchanged"},{"id":"d","text":"It increases slightly"}],"answerId":"b","explanation":"During a pneumothorax, air enters the pleural space, causing the intrapleural pressure to become positive, which leads to lung collapse.","kind":"recall","origin":"ai"},{"id":"respiratory-mechanics-compliance~ai-3","moduleId":"respiratory-mechanics-compliance","stem":"Which of the following correctly describes compliance in emphysema compared to pulmonary fibrosis?","options":[{"id":"a","text":"Emphysema decreases compliance; fibrosis increases compliance"},{"id":"b","text":"Both conditions decrease compliance"},{"id":"c","text":"Emphysema increases compliance; fibrosis decreases compliance"},{"id":"d","text":"Both conditions increase compliance"}],"answerId":"c","explanation":"Emphysema increases compliance due to loss of elastic tissue, while pulmonary fibrosis decreases compliance due to increased stiffness.","kind":"trap","origin":"ai"},{"id":"respiratory-mechanics-compliance~ai-4","moduleId":"respiratory-mechanics-compliance","stem":"What is the effect of surfactant on alveolar compliance?","options":[{"id":"a","text":"Decreases compliance"},{"id":"b","text":"Increases compliance"},{"id":"c","text":"Has no effect on compliance"},{"id":"d","text":"Causes alveolar collapse"}],"answerId":"b","explanation":"Surfactant lowers surface tension in the alveoli, which increases compliance and prevents alveolar collapse.","kind":"mechanism","origin":"ai"},{"id":"respiratory-mechanics-compliance~ai-5","moduleId":"respiratory-mechanics-compliance","stem":"How does bronchoconstriction affect airway resistance and work of breathing?","options":[{"id":"a","text":"Decreases resistance and work"},{"id":"b","text":"Increases resistance and work"},{"id":"c","text":"Has no effect on resistance"},{"id":"d","text":"Decreases work but increases resistance"}],"answerId":"b","explanation":"Bronchoconstriction increases airway resistance, which in turn increases the work of breathing.","kind":"clinical","origin":"ai"},{"id":"respiratory-mechanics-compliance~ai-6","moduleId":"respiratory-mechanics-compliance","stem":"How does the mechanism of gas exchange in the alveoli relate to surface tension management?","options":[{"id":"a","text":"Gas exchange is independent of surface tension"},{"id":"b","text":"Surfactant reduces surface tension, facilitating gas exchange"},{"id":"c","text":"High surface tension enhances gas exchange"},{"id":"d","text":"Surface tension only affects lung compliance, not gas exchange"}],"answerId":"b","explanation":"Surfactant reduces surface tension in the alveoli, which facilitates gas exchange by preventing alveolar collapse and maintaining surface area.","kind":"integration","linkedModuleIds":["alveoli-pneumocytes-respiratory-membrane"],"origin":"ai"},{"id":"respiratory-mechanics-compliance~ai-7","moduleId":"respiratory-mechanics-compliance","stem":"What role does compliance play in the relationship between lung volumes and ventilation?","options":[{"id":"a","text":"High compliance leads to decreased lung volumes"},{"id":"b","text":"Low compliance increases ventilation efficiency"},{"id":"c","text":"High compliance allows for greater lung volumes with less effort"},{"id":"d","text":"Compliance has no impact on ventilation"}],"answerId":"c","explanation":"High compliance allows for greater lung volumes with less effort, facilitating efficient ventilation.","kind":"integration","linkedModuleIds":["lung-volumes-ventilation"],"origin":"ai"}],"oxygen-transport-dissociation-curve":[{"id":"oxygen-transport-dissociation-curve~ai-0","moduleId":"oxygen-transport-dissociation-curve","stem":"What percentage of oxygen is carried in the blood bound to hemoglobin?","options":[{"id":"a","text":"98%"},{"id":"b","text":"50%"},{"id":"c","text":"2%"},{"id":"d","text":"100%"}],"answerId":"a","explanation":"Approximately 98% of oxygen in the blood is bound to hemoglobin, while about 2% is dissolved in plasma.","kind":"recall","origin":"ai"},{"id":"oxygen-transport-dissociation-curve~ai-1","moduleId":"oxygen-transport-dissociation-curve","stem":"Which factor causes a right shift in the oxyhemoglobin dissociation curve?","options":[{"id":"a","text":"Decreased temperature"},{"id":"b","text":"Increased pH"},{"id":"c","text":"Increased 2,3-BPG"},{"id":"d","text":"Decreased CO₂"}],"answerId":"c","explanation":"An increase in 2,3-BPG causes a right shift in the oxyhemoglobin dissociation curve, facilitating oxygen unloading to tissues.","kind":"mechanism","origin":"ai"},{"id":"oxygen-transport-dissociation-curve~ai-2","moduleId":"oxygen-transport-dissociation-curve","stem":"A patient presents with normal PaO₂ and SaO₂ but exhibits symptoms of fatigue. What is the most likely underlying cause?","options":[{"id":"a","text":"Carbon monoxide poisoning"},{"id":"b","text":"Anemia"},{"id":"c","text":"Hypercapnia"},{"id":"d","text":"Methemoglobinemia"}],"answerId":"b","explanation":"Anemia leads to reduced hemoglobin levels, resulting in low oxygen content despite normal PaO₂ and SaO₂.","kind":"clinical","origin":"ai"},{"id":"oxygen-transport-dissociation-curve~ai-3","moduleId":"oxygen-transport-dissociation-curve","stem":"In carbon monoxide poisoning, what is the primary reason for falsely normal pulse oximetry readings?","options":[{"id":"a","text":"Increased carboxyhemoglobin levels"},{"id":"b","text":"Decreased hemoglobin levels"},{"id":"c","text":"Increased oxygen affinity"},{"id":"d","text":"Decreased blood pH"}],"answerId":"a","explanation":"Carboxyhemoglobin binds to hemoglobin, leading to falsely normal pulse oximetry readings despite reduced oxygen delivery.","kind":"recall","origin":"ai"},{"id":"oxygen-transport-dissociation-curve~ai-4","moduleId":"oxygen-transport-dissociation-curve","stem":"What does a left shift in the oxyhemoglobin dissociation curve indicate?","options":[{"id":"a","text":"Increased oxygen unloading"},{"id":"b","text":"Decreased oxygen affinity"},{"id":"c","text":"Increased carbon dioxide levels"},{"id":"d","text":"Increased oxygen affinity"}],"answerId":"d","explanation":"A left shift indicates increased oxygen affinity, making it harder for hemoglobin to release oxygen to tissues.","kind":"trap","origin":"ai"},{"id":"oxygen-transport-dissociation-curve~ai-5","moduleId":"oxygen-transport-dissociation-curve","stem":"How does fetal hemoglobin (HbF) affect oxygen transport compared to adult hemoglobin?","options":[{"id":"a","text":"Decreases oxygen affinity"},{"id":"b","text":"Increases oxygen affinity"},{"id":"c","text":"Has no effect"},{"id":"d","text":"Decreases oxygen content"}],"answerId":"b","explanation":"Fetal hemoglobin has a higher affinity for oxygen than adult hemoglobin, facilitating oxygen transfer from mother to fetus.","kind":"mechanism","origin":"ai"},{"id":"oxygen-transport-dissociation-curve~ai-6","moduleId":"oxygen-transport-dissociation-curve","stem":"How does the oxyhemoglobin curve relate to CO₂ transport in blood (linked module)?","options":[{"id":"a","text":"Increased CO₂ shifts the curve left"},{"id":"b","text":"Decreased CO₂ shifts the curve right"},{"id":"c","text":"Increased CO₂ shifts the curve right"},{"id":"d","text":"CO₂ transport does not affect the curve"}],"answerId":"c","explanation":"Increased CO₂ levels cause a right shift in the oxyhemoglobin curve, promoting oxygen unloading to tissues.","kind":"integration","linkedModuleIds":["co2-transport-blood"],"origin":"ai"},{"id":"oxygen-transport-dissociation-curve~ai-7","moduleId":"oxygen-transport-dissociation-curve","stem":"What is the relationship between gas exchange and the oxyhemoglobin dissociation curve (linked module)?","options":[{"id":"a","text":"Gas exchange occurs at the steep portion of the curve"},{"id":"b","text":"Gas exchange is independent of the curve"},{"id":"c","text":"Gas exchange occurs at the flat portion of the curve"},{"id":"d","text":"Gas exchange is enhanced by a left shift"}],"answerId":"a","explanation":"Gas exchange is most effective at the steep portion of the oxyhemoglobin dissociation curve, where small changes in PO₂ lead to significant changes in oxygen unloading.","kind":"integration","linkedModuleIds":["gas-exchange-diffusion"],"origin":"ai"}],"control-of-breathing":[{"id":"control-of-breathing~ai-0","moduleId":"control-of-breathing","stem":"What is the primary stimulus for breathing under normal conditions?","options":[{"id":"a","text":"Low oxygen (PaO₂)"},{"id":"b","text":"High carbon dioxide (PaCO₂)"},{"id":"c","text":"High hydrogen ion concentration (H⁺)"},{"id":"d","text":"Low blood pH"}],"answerId":"b","explanation":"The primary stimulus for breathing is high PaCO₂, which increases H⁺ concentration in the CSF, stimulating central chemoreceptors.","kind":"recall","origin":"ai"},{"id":"control-of-breathing~ai-1","moduleId":"control-of-breathing","stem":"Which structure in the brainstem is primarily responsible for generating the rhythm of breathing?","options":[{"id":"a","text":"Pneumotaxic center"},{"id":"b","text":"Dorsal respiratory group"},{"id":"c","text":"Ventral respiratory group"},{"id":"d","text":"Apneustic center"}],"answerId":"b","explanation":"The dorsal respiratory group in the medulla is primarily responsible for generating the rhythm of breathing.","kind":"recall","origin":"ai"},{"id":"control-of-breathing~ai-2","moduleId":"control-of-breathing","stem":"What is the role of peripheral chemoreceptors in breathing regulation?","options":[{"id":"a","text":"Sense changes in CO₂ levels"},{"id":"b","text":"Sense changes in O₂ levels"},{"id":"c","text":"Regulate voluntary breathing"},{"id":"d","text":"Inhibit inspiration during lung over-inflation"}],"answerId":"b","explanation":"Peripheral chemoreceptors, located in the carotid and aortic bodies, are the only sensors that respond primarily to low PaO₂ levels.","kind":"recall","origin":"ai"},{"id":"control-of-breathing~ai-3","moduleId":"control-of-breathing","stem":"A patient with COPD has a blunted central chemoreceptor response. What drives their breathing primarily?","options":[{"id":"a","text":"Increased PaCO₂"},{"id":"b","text":"Decreased PaO₂"},{"id":"c","text":"Increased H⁺"},{"id":"d","text":"Decreased blood pH"}],"answerId":"b","explanation":"In patients with COPD, the hypoxic drive becomes the primary stimulus for breathing due to a blunted response to CO₂.","kind":"clinical","origin":"ai"},{"id":"control-of-breathing~ai-4","moduleId":"control-of-breathing","stem":"During a voluntary breath-hold, what physiological change will eventually trigger involuntary breathing?","options":[{"id":"a","text":"Decreased PaO₂"},{"id":"b","text":"Increased PaCO₂"},{"id":"c","text":"Decreased blood pH"},{"id":"d","text":"Increased H⁺ concentration"}],"answerId":"b","explanation":"Increased PaCO₂ during breath-holding will stimulate the medulla to resume involuntary breathing.","kind":"mechanism","origin":"ai"},{"id":"control-of-breathing~ai-5","moduleId":"control-of-breathing","stem":"Which reflex inhibits further inspiration when the lungs are over-inflated?","options":[{"id":"a","text":"Hering–Breuer reflex"},{"id":"b","text":"Cough reflex"},{"id":"c","text":"Gag reflex"},{"id":"d","text":"Stretch reflex"}],"answerId":"a","explanation":"The Hering–Breuer reflex involves pulmonary stretch receptors that inhibit further inspiration to prevent over-inflation.","kind":"mechanism","origin":"ai"},{"id":"control-of-breathing~ai-6","moduleId":"control-of-breathing","stem":"How does the central chemoreceptor mechanism relate to acid-base balance?","options":[{"id":"a","text":"It directly senses blood pH changes"},{"id":"b","text":"It responds to changes in PaCO₂"},{"id":"c","text":"It regulates bicarbonate levels"},{"id":"d","text":"It modulates oxygen delivery"}],"answerId":"b","explanation":"Central chemoreceptors respond to changes in PaCO₂, which indirectly reflects changes in blood pH, thus linking breathing to acid-base balance.","kind":"integration","linkedModuleIds":["abg-acid-base-interpretation"],"origin":"ai"},{"id":"control-of-breathing~ai-7","moduleId":"control-of-breathing","stem":"What is the relationship between CO₂ transport in blood and the control of breathing?","options":[{"id":"a","text":"CO₂ transport is independent of breathing control"},{"id":"b","text":"Increased CO₂ levels stimulate peripheral chemoreceptors"},{"id":"c","text":"CO₂ levels directly influence central chemoreceptor activity"},{"id":"d","text":"Oxygen transport regulates CO₂ levels"}],"answerId":"c","explanation":"Increased CO₂ levels in the blood influence central chemoreceptor activity, which is crucial for regulating the breathing rate.","kind":"integration","linkedModuleIds":["co2-transport-blood"],"origin":"ai"}],"alveoli-pneumocytes-respiratory-membrane":[{"id":"alveoli-pneumocytes-respiratory-membrane~ai-0","moduleId":"alveoli-pneumocytes-respiratory-membrane","stem":"What is the primary function of type II pneumocytes in the alveoli?","options":[{"id":"a","text":"Gas exchange"},{"id":"b","text":"Surfactant production"},{"id":"c","text":"Alveolar macrophage activity"},{"id":"d","text":"Structural support"}],"answerId":"b","explanation":"Type II pneumocytes primarily produce surfactant, which lowers surface tension in the alveoli.","kind":"recall","origin":"ai"},{"id":"alveoli-pneumocytes-respiratory-membrane~ai-1","moduleId":"alveoli-pneumocytes-respiratory-membrane","stem":"Which component of the respiratory membrane is responsible for gas exchange?","options":[{"id":"a","text":"Type II pneumocytes"},{"id":"b","text":"Capillary endothelium"},{"id":"c","text":"Alveolar epithelium"},{"id":"d","text":"Surfactant"}],"answerId":"c","explanation":"The alveolar epithelium, specifically type I pneumocytes, is primarily responsible for gas exchange.","kind":"recall","origin":"ai"},{"id":"alveoli-pneumocytes-respiratory-membrane~ai-2","moduleId":"alveoli-pneumocytes-respiratory-membrane","stem":"What is the effect of surfactant on alveolar stability?","options":[{"id":"a","text":"Increases surface tension"},{"id":"b","text":"Prevents collapse at end-expiration"},{"id":"c","text":"Decreases lung compliance"},{"id":"d","text":"Promotes thickening of the alveolar membrane"}],"answerId":"b","explanation":"Surfactant lowers surface tension, preventing alveolar collapse at end-expiration.","kind":"mechanism","origin":"ai"},{"id":"alveoli-pneumocytes-respiratory-membrane~ai-3","moduleId":"alveoli-pneumocytes-respiratory-membrane","stem":"A patient presents with pulmonary edema. What is the likely effect on gas exchange?","options":[{"id":"a","text":"Increased diffusion rate"},{"id":"b","text":"Decreased diffusion rate"},{"id":"c","text":"No effect on gas exchange"},{"id":"d","text":"Improved oxygenation"}],"answerId":"b","explanation":"Pulmonary edema thickens the respiratory membrane, decreasing the diffusion rate of gases.","kind":"clinical","origin":"ai"},{"id":"alveoli-pneumocytes-respiratory-membrane~ai-4","moduleId":"alveoli-pneumocytes-respiratory-membrane","stem":"Which cell type is responsible for repairing the alveolar epithelium after injury?","options":[{"id":"a","text":"Type I pneumocytes"},{"id":"b","text":"Type II pneumocytes"},{"id":"c","text":"Alveolar macrophages"},{"id":"d","text":"Capillary endothelial cells"}],"answerId":"b","explanation":"Type II pneumocytes act as stem cells, proliferating and differentiating into type I cells to repair the epithelium.","kind":"trap","origin":"ai"},{"id":"alveoli-pneumocytes-respiratory-membrane~ai-5","moduleId":"alveoli-pneumocytes-respiratory-membrane","stem":"How does surfactant affect lung compliance?","options":[{"id":"a","text":"Decreases compliance"},{"id":"b","text":"Increases compliance"},{"id":"c","text":"Has no effect on compliance"},{"id":"d","text":"Causes lung stiffness"}],"answerId":"b","explanation":"Surfactant increases lung compliance by reducing surface tension, making it easier to inflate the lungs.","kind":"mechanism","origin":"ai"},{"id":"alveoli-pneumocytes-respiratory-membrane~ai-6","moduleId":"alveoli-pneumocytes-respiratory-membrane","stem":"In a newborn with respiratory distress syndrome (RDS), what is the primary deficiency?","options":[{"id":"a","text":"Type I pneumocyte dysfunction"},{"id":"b","text":"Surfactant deficiency"},{"id":"c","text":"Capillary endothelial damage"},{"id":"d","text":"Alveolar macrophage dysfunction"}],"answerId":"b","explanation":"RDS is primarily caused by surfactant deficiency, leading to alveolar collapse and impaired gas exchange.","kind":"integration","linkedModuleIds":["respiratory-congenital-anomalies"],"origin":"ai"},{"id":"alveoli-pneumocytes-respiratory-membrane~ai-7","moduleId":"alveoli-pneumocytes-respiratory-membrane","stem":"What role does the respiratory membrane play in gas exchange?","options":[{"id":"a","text":"Facilitates diffusion of gases"},{"id":"b","text":"Increases surface area"},{"id":"c","text":"Decreases partial pressure gradients"},{"id":"d","text":"Acts as a barrier to pathogens"}],"answerId":"a","explanation":"The respiratory membrane facilitates the diffusion of gases (O₂ and CO₂) between the alveoli and capillaries.","kind":"integration","linkedModuleIds":["gas-exchange-diffusion"],"origin":"ai"}],"lung-volumes-ventilation":[{"id":"lung-volumes-ventilation~ai-0","moduleId":"lung-volumes-ventilation","stem":"What is the normal tidal volume (TV) in adults?","options":[{"id":"a","text":"250 mL"},{"id":"b","text":"500 mL"},{"id":"c","text":"750 mL"},{"id":"d","text":"1000 mL"}],"answerId":"b","explanation":"The normal tidal volume (TV) is approximately 500 mL, representing a typical breath.","kind":"recall","origin":"ai"},{"id":"lung-volumes-ventilation~ai-1","moduleId":"lung-volumes-ventilation","stem":"Which lung volume cannot be measured by spirometry?","options":[{"id":"a","text":"Tidal volume"},{"id":"b","text":"Inspiratory reserve volume"},{"id":"c","text":"Residual volume"},{"id":"d","text":"Expiratory reserve volume"}],"answerId":"c","explanation":"Residual volume cannot be measured by spirometry as it is the air remaining in the lungs after maximal expiration.","kind":"recall","origin":"ai"},{"id":"lung-volumes-ventilation~ai-2","moduleId":"lung-volumes-ventilation","stem":"In a patient with COPD, which spirometry finding is expected?","options":[{"id":"a","text":"FEV₁/FVC ratio > 0.7"},{"id":"b","text":"All lung volumes increased"},{"id":"c","text":"FEV₁/FVC ratio < 0.7"},{"id":"d","text":"Normal FEV₁ and FVC"}],"answerId":"c","explanation":"In COPD, the FEV₁/FVC ratio is typically less than 0.7 due to airflow limitation.","kind":"recall","origin":"ai"},{"id":"lung-volumes-ventilation~ai-3","moduleId":"lung-volumes-ventilation","stem":"What is the primary mechanism for reduced alveolar ventilation in rapid shallow breathing?","options":[{"id":"a","text":"Increased tidal volume"},{"id":"b","text":"Increased dead space fraction"},{"id":"c","text":"Decreased respiratory rate"},{"id":"d","text":"Increased functional residual capacity"}],"answerId":"b","explanation":"Rapid shallow breathing increases the dead space fraction, leading to less effective alveolar ventilation.","kind":"mechanism","origin":"ai"},{"id":"lung-volumes-ventilation~ai-4","moduleId":"lung-volumes-ventilation","stem":"Which of the following statements about lung volumes is true?","options":[{"id":"a","text":"Vital capacity includes residual volume."},{"id":"b","text":"Functional residual capacity is the sum of ERV and RV."},{"id":"c","text":"Inspiratory capacity is the sum of TV and RV."},{"id":"d","text":"Total lung capacity can be measured by spirometry."}],"answerId":"b","explanation":"Functional residual capacity (FRC) is indeed the sum of expiratory reserve volume (ERV) and residual volume (RV).","kind":"trap","origin":"ai"},{"id":"lung-volumes-ventilation~ai-5","moduleId":"lung-volumes-ventilation","stem":"How does restrictive lung disease affect lung volumes?","options":[{"id":"a","text":"All lung volumes are increased"},{"id":"b","text":"FEV₁/FVC ratio is decreased"},{"id":"c","text":"All lung volumes are decreased"},{"id":"d","text":"Only FEV₁ is decreased"}],"answerId":"c","explanation":"In restrictive lung disease, all lung volumes are decreased while the FEV₁/FVC ratio may be normal or high.","kind":"recall","origin":"ai"},{"id":"lung-volumes-ventilation~ai-6","moduleId":"lung-volumes-ventilation","stem":"How does alveolar ventilation differ from minute ventilation?","options":[{"id":"a","text":"Alveolar ventilation includes dead space"},{"id":"b","text":"Minute ventilation is always greater than alveolar ventilation"},{"id":"c","text":"Alveolar ventilation accounts for dead space"},{"id":"d","text":"Minute ventilation measures only tidal volume"}],"answerId":"c","explanation":"Alveolar ventilation accounts for dead space, making it a more accurate measure of effective ventilation for gas exchange.","kind":"mechanism","origin":"ai"},{"id":"lung-volumes-ventilation~ai-7","moduleId":"lung-volumes-ventilation","stem":"How does the thoracic wall structure relate to lung volumes?","options":[{"id":"a","text":"It limits tidal volume"},{"id":"b","text":"It affects compliance"},{"id":"c","text":"It increases residual volume"},{"id":"d","text":"It decreases functional residual capacity"}],"answerId":"b","explanation":"The structure of the thoracic wall affects lung compliance, which in turn influences lung volumes and capacities.","kind":"integration","linkedModuleIds":["thoracic-wall-intercostal-space"],"origin":"ai"},{"id":"lung-volumes-ventilation~ai-8","moduleId":"lung-volumes-ventilation","stem":"What role do conducting airways play in effective ventilation?","options":[{"id":"a","text":"They increase tidal volume"},{"id":"b","text":"They reduce dead space"},{"id":"c","text":"They facilitate gas exchange"},{"id":"d","text":"They condition inspired air"}],"answerId":"d","explanation":"Conducting airways condition inspired air, which is essential for efficient gas exchange in the alveoli.","kind":"integration","linkedModuleIds":["airway-conducting-respiratory-zones"],"origin":"ai"}],"heart-anatomy-chambers-valves":[{"id":"heart-anatomy-chambers-valves~ai-0","moduleId":"heart-anatomy-chambers-valves","stem":"Which chamber of the heart receives deoxygenated blood from the body?","options":[{"id":"a","text":"Left atrium"},{"id":"b","text":"Right atrium"},{"id":"c","text":"Left ventricle"},{"id":"d","text":"Right ventricle"}],"answerId":"b","explanation":"The right atrium receives deoxygenated blood from the superior and inferior vena cavae.","kind":"recall","origin":"ai"},{"id":"heart-anatomy-chambers-valves~ai-1","moduleId":"heart-anatomy-chambers-valves","stem":"What is the primary function of the chordae tendineae?","options":[{"id":"a","text":"Prevent backflow during diastole"},{"id":"b","text":"Support the myocardium"},{"id":"c","text":"Prevent valve prolapse during systole"},{"id":"d","text":"Facilitate coronary blood flow"}],"answerId":"c","explanation":"Chordae tendineae prevent valve prolapse by anchoring the AV valves during ventricular contraction.","kind":"mechanism","origin":"ai"},{"id":"heart-anatomy-chambers-valves~ai-2","moduleId":"heart-anatomy-chambers-valves","stem":"Which valve is correctly matched with its location?","options":[{"id":"a","text":"Tricuspid valve - between LA and LV"},{"id":"b","text":"Mitral valve - between RA and RV"},{"id":"c","text":"Pulmonary valve - between RV and pulmonary trunk"},{"id":"d","text":"Aortic valve - between LA and LV"}],"answerId":"c","explanation":"The pulmonary valve is located between the right ventricle and the pulmonary trunk.","kind":"trap","origin":"ai"},{"id":"heart-anatomy-chambers-valves~ai-3","moduleId":"heart-anatomy-chambers-valves","stem":"What is the primary reason for the thicker wall of the left ventricle compared to the right ventricle?","options":[{"id":"a","text":"Pumps against lower pressure"},{"id":"b","text":"Pumps against high systemic pressure"},{"id":"c","text":"Pumps deoxygenated blood"},{"id":"d","text":"Pumps oxygenated blood"}],"answerId":"b","explanation":"The left ventricle pumps blood into the systemic circulation, which requires higher pressure than the pulmonary circulation.","kind":"clinical","origin":"ai"},{"id":"heart-anatomy-chambers-valves~ai-4","moduleId":"heart-anatomy-chambers-valves","stem":"During which phase of the cardiac cycle does coronary blood flow primarily occur?","options":[{"id":"a","text":"Systole"},{"id":"b","text":"Diastole"},{"id":"c","text":"Atrial contraction"},{"id":"d","text":"Ventricular contraction"}],"answerId":"b","explanation":"Coronary blood flow occurs mainly during diastole when the heart muscle is relaxed.","kind":"mechanism","origin":"ai"},{"id":"heart-anatomy-chambers-valves~ai-5","moduleId":"heart-anatomy-chambers-valves","stem":"Which structure is NOT part of the heart wall?","options":[{"id":"a","text":"Endocardium"},{"id":"b","text":"Myocardium"},{"id":"c","text":"Epicardium"},{"id":"d","text":"Pericardium"}],"answerId":"d","explanation":"The pericardium is a protective sac surrounding the heart, not a layer of the heart wall.","kind":"trap","origin":"ai"},{"id":"heart-anatomy-chambers-valves~ai-6","moduleId":"heart-anatomy-chambers-valves","stem":"How does the structure of the mitral valve prevent backflow during ventricular contraction?","options":[{"id":"a","text":"It has no chordae tendineae"},{"id":"b","text":"It is located between the right atrium and right ventricle"},{"id":"c","text":"It is supported by chordae tendineae and papillary muscles"},{"id":"d","text":"It is a semilunar valve"}],"answerId":"c","explanation":"The mitral valve is supported by chordae tendineae and papillary muscles that prevent backflow during systole.","kind":"mechanism","origin":"ai"},{"id":"heart-anatomy-chambers-valves~ai-7","moduleId":"heart-anatomy-chambers-valves","stem":"Which of the following best describes the relationship between the heart's chambers and the pericardium?","options":[{"id":"a","text":"The pericardium is part of the right atrium"},{"id":"b","text":"The pericardium surrounds the heart chambers"},{"id":"c","text":"The pericardium is a valve"},{"id":"d","text":"The pericardium is only associated with the left ventricle"}],"answerId":"b","explanation":"The pericardium is a fibrous and serous sac that surrounds the heart chambers, providing protection and lubrication.","kind":"integration","linkedModuleIds":["heart-chambers-pericardium"],"origin":"ai"},{"id":"heart-anatomy-chambers-valves~ai-8","moduleId":"heart-anatomy-chambers-valves","stem":"How does the structure of the heart valves relate to their function in the cardiovascular system?","options":[{"id":"a","text":"Valves prevent backflow during systole"},{"id":"b","text":"Valves are located only in the left heart"},{"id":"c","text":"Valves facilitate coronary blood flow"},{"id":"d","text":"Valves ensure unidirectional blood flow"}],"answerId":"d","explanation":"Heart valves ensure unidirectional blood flow, preventing backflow during the cardiac cycle.","kind":"integration","linkedModuleIds":["heart-valves-coronary-supply"],"origin":"ai"}],"co2-transport-blood":[{"id":"co2-transport-blood~ai-0","moduleId":"co2-transport-blood","stem":"What is the primary form in which CO₂ is transported in the blood?","options":[{"id":"a","text":"Dissolved in plasma"},{"id":"b","text":"Bound to hemoglobin as carbaminohemoglobin"},{"id":"c","text":"As bicarbonate ions"},{"id":"d","text":"In the form of carbonic acid"}],"answerId":"c","explanation":"Approximately 70% of CO₂ is transported as bicarbonate ions (HCO₃⁻) in plasma.","kind":"recall","origin":"ai"},{"id":"co2-transport-blood~ai-1","moduleId":"co2-transport-blood","stem":"Which enzyme catalyzes the conversion of CO₂ and H₂O to bicarbonate?","options":[{"id":"a","text":"Carbonic anhydrase"},{"id":"b","text":"Lactate dehydrogenase"},{"id":"c","text":"Aldose reductase"},{"id":"d","text":"Phosphofructokinase"}],"answerId":"a","explanation":"Carbonic anhydrase is responsible for the rapid conversion of CO₂ and H₂O to bicarbonate and protons.","kind":"mechanism","origin":"ai"},{"id":"co2-transport-blood~ai-2","moduleId":"co2-transport-blood","stem":"What occurs during the Hamburger shift?","options":[{"id":"a","text":"O₂ binds to hemoglobin"},{"id":"b","text":"HCO₃⁻ exits the RBC and Cl⁻ enters"},{"id":"c","text":"CO₂ is converted to carbonic acid"},{"id":"d","text":"H⁺ is released into the plasma"}],"answerId":"b","explanation":"The Hamburger shift describes the exchange of HCO₃⁻ leaving the RBC while Cl⁻ enters to maintain electroneutrality.","kind":"mechanism","origin":"ai"},{"id":"co2-transport-blood~ai-3","moduleId":"co2-transport-blood","stem":"Which effect describes the increased capacity of deoxygenated hemoglobin to carry CO₂?","options":[{"id":"a","text":"Bohr effect"},{"id":"b","text":"Haldane effect"},{"id":"c","text":"Hamburger effect"},{"id":"d","text":"Chloride effect"}],"answerId":"b","explanation":"The Haldane effect states that deoxygenated hemoglobin can carry more CO₂, enhancing CO₂ loading in tissues.","kind":"mechanism","origin":"ai"},{"id":"co2-transport-blood~ai-4","moduleId":"co2-transport-blood","stem":"A patient presents with respiratory acidosis due to hypoventilation. What is the primary cause of this condition?","options":[{"id":"a","text":"Increased bicarbonate levels"},{"id":"b","text":"Decreased CO₂ levels"},{"id":"c","text":"Increased CO₂ retention"},{"id":"d","text":"Decreased O₂ levels"}],"answerId":"c","explanation":"Hypoventilation leads to CO₂ retention, resulting in respiratory acidosis due to increased dissolved CO₂.","kind":"clinical","origin":"ai"},{"id":"co2-transport-blood~ai-5","moduleId":"co2-transport-blood","stem":"Which of the following statements about CO₂ transport is FALSE?","options":[{"id":"a","text":"Most CO₂ is carried as bicarbonate"},{"id":"b","text":"Carbaminohemoglobin accounts for ~23% of CO₂ transport"},{"id":"c","text":"Dissolved CO₂ constitutes the majority of CO₂ transport"},{"id":"d","text":"The bicarbonate reaction is catalyzed by carbonic anhydrase"}],"answerId":"c","explanation":"Dissolved CO₂ accounts for only about 7% of CO₂ transport; the majority is carried as bicarbonate.","kind":"trap","origin":"ai"},{"id":"co2-transport-blood~ai-6","moduleId":"co2-transport-blood","stem":"How does CO₂ transport relate to acid-base balance in the blood?","options":[{"id":"a","text":"CO₂ is a base that neutralizes acids"},{"id":"b","text":"CO₂ is converted to bicarbonate, which acts as a buffer"},{"id":"c","text":"CO₂ levels have no effect on blood pH"},{"id":"d","text":"Bicarbonate decreases in response to increased CO₂"}],"answerId":"b","explanation":"The conversion of CO₂ to bicarbonate is crucial for maintaining acid-base balance, as bicarbonate acts as a major buffer.","kind":"integration","linkedModuleIds":["abg-acid-base-interpretation"],"origin":"ai"},{"id":"co2-transport-blood~ai-7","moduleId":"co2-transport-blood","stem":"In what way does the control of breathing affect CO₂ transport in the blood?","options":[{"id":"a","text":"Increased breathing decreases CO₂ levels"},{"id":"b","text":"Decreased breathing increases bicarbonate levels"},{"id":"c","text":"Breathing rate has no impact on CO₂ transport"},{"id":"d","text":"Breathing only affects O₂ transport"}],"answerId":"a","explanation":"Increased ventilation reduces CO₂ levels by enhancing its exhalation, thereby affecting CO₂ transport dynamics.","kind":"integration","linkedModuleIds":["control-of-breathing"],"origin":"ai"}],"abg-acid-base-interpretation":[{"id":"abg-acid-base-interpretation~ai-0","moduleId":"abg-acid-base-interpretation","stem":"A patient presents with a pH of 7.30, PaCO₂ of 50 mmHg, and HCO₃⁻ of 24 mEq/L. What is the primary acid-base disturbance?","options":[{"id":"a","text":"Respiratory acidosis"},{"id":"b","text":"Metabolic acidosis"},{"id":"c","text":"Respiratory alkalosis"},{"id":"d","text":"Metabolic alkalosis"}],"answerId":"a","explanation":"The low pH and elevated PaCO₂ indicate respiratory acidosis due to hypoventilation.","kind":"recall","origin":"ai"},{"id":"abg-acid-base-interpretation~ai-1","moduleId":"abg-acid-base-interpretation","stem":"In metabolic acidosis, which of the following compensatory mechanisms occurs?","options":[{"id":"a","text":"Increased HCO₃⁻ retention"},{"id":"b","text":"Increased PaCO₂"},{"id":"c","text":"Increased respiratory rate"},{"id":"d","text":"Decreased oxygen saturation"}],"answerId":"c","explanation":"The lungs compensate for metabolic acidosis by increasing the respiratory rate to blow off CO₂.","kind":"mechanism","origin":"ai"},{"id":"abg-acid-base-interpretation~ai-2","moduleId":"abg-acid-base-interpretation","stem":"A patient with chronic obstructive pulmonary disease (COPD) presents with a pH of 7.32 and PaCO₂ of 60 mmHg. What is the expected compensation by the kidneys?","options":[{"id":"a","text":"Decreased HCO₃⁻"},{"id":"b","text":"Increased HCO₃⁻"},{"id":"c","text":"Decreased PaCO₂"},{"id":"d","text":"Increased PaO₂"}],"answerId":"b","explanation":"The kidneys will retain HCO₃⁻ to compensate for the respiratory acidosis caused by elevated PaCO₂.","kind":"clinical","origin":"ai"},{"id":"abg-acid-base-interpretation~ai-3","moduleId":"abg-acid-base-interpretation","stem":"A patient presents with a pH of 7.50, PaCO₂ of 30 mmHg, and HCO₃⁻ of 22 mEq/L. What is the likely cause of this acid-base disturbance?","options":[{"id":"a","text":"Metabolic acidosis"},{"id":"b","text":"Respiratory alkalosis"},{"id":"c","text":"Metabolic alkalosis"},{"id":"d","text":"Respiratory acidosis"}],"answerId":"b","explanation":"The elevated pH and decreased PaCO₂ indicate respiratory alkalosis, likely due to hyperventilation.","kind":"recall","origin":"ai"},{"id":"abg-acid-base-interpretation~ai-4","moduleId":"abg-acid-base-interpretation","stem":"Which of the following findings would suggest a metabolic acidosis with an increased anion gap?","options":[{"id":"a","text":"Normal HCO₃⁻ levels"},{"id":"b","text":"Elevated HCO₃⁻ levels"},{"id":"c","text":"Elevated PaCO₂"},{"id":"d","text":"Decreased PaO₂"}],"answerId":"a","explanation":"In metabolic acidosis with an increased anion gap, HCO₃⁻ levels are typically decreased.","kind":"trap","origin":"ai"},{"id":"abg-acid-base-interpretation~ai-5","moduleId":"abg-acid-base-interpretation","stem":"A patient with pneumonia has a pH of 7.35, PaCO₂ of 55 mmHg, and HCO₃⁻ of 26 mEq/L. What is the primary disturbance?","options":[{"id":"a","text":"Respiratory acidosis"},{"id":"b","text":"Metabolic acidosis"},{"id":"c","text":"Respiratory alkalosis"},{"id":"d","text":"Metabolic alkalosis"}],"answerId":"a","explanation":"The low pH and high PaCO₂ indicate respiratory acidosis, likely due to hypoventilation from pneumonia.","kind":"clinical","origin":"ai"},{"id":"abg-acid-base-interpretation~ai-6","moduleId":"abg-acid-base-interpretation","stem":"How does the body compensate for metabolic alkalosis?","options":[{"id":"a","text":"Increased respiratory rate"},{"id":"b","text":"Decreased respiratory rate"},{"id":"c","text":"Increased HCO₃⁻ secretion"},{"id":"d","text":"Increased CO₂ production"}],"answerId":"b","explanation":"The body compensates for metabolic alkalosis by decreasing the respiratory rate to retain CO₂, which lowers pH.","kind":"mechanism","origin":"ai"},{"id":"abg-acid-base-interpretation~ai-7","moduleId":"abg-acid-base-interpretation","stem":"In a patient with metabolic acidosis, which of the following findings would indicate a normal anion gap?","options":[{"id":"a","text":"Elevated lactate"},{"id":"b","text":"Diarrhea"},{"id":"c","text":"Renal failure"},{"id":"d","text":"Ketoacidosis"}],"answerId":"b","explanation":"Diarrhea causes a loss of bicarbonate, leading to a normal anion gap metabolic acidosis.","kind":"trap","origin":"ai"},{"id":"abg-acid-base-interpretation~ai-8","moduleId":"abg-acid-base-interpretation","stem":"How does the Henderson-Hasselbalch equation relate to acid-base balance?","options":[{"id":"a","text":"pH is determined by the ratio of HCO₃⁻ to PaCO₂"},{"id":"b","text":"pH is determined by the ratio of PaCO₂ to HCO₃⁻"},{"id":"c","text":"pH is independent of HCO₃⁻"},{"id":"d","text":"pH is independent of PaCO₂"}],"answerId":"a","explanation":"The Henderson-Hasselbalch equation shows that pH is determined by the ratio of bicarbonate (base) to carbon dioxide (acid).","kind":"mechanism","origin":"ai"},{"id":"abg-acid-base-interpretation~ai-9","moduleId":"abg-acid-base-interpretation","stem":"How does hypoventilation affect CO₂ transport in blood?","options":[{"id":"a","text":"Increases CO₂ elimination"},{"id":"b","text":"Decreases CO₂ retention"},{"id":"c","text":"Increases CO₂ retention"},{"id":"d","text":"Decreases blood pH"}],"answerId":"c","explanation":"Hypoventilation leads to increased CO₂ retention, resulting in respiratory acidosis and decreased blood pH.","kind":"integration","linkedModuleIds":["co2-transport-blood"],"origin":"ai"},{"id":"abg-acid-base-interpretation~ai-10","moduleId":"abg-acid-base-interpretation","stem":"What is the relationship between V/Q mismatch and arterial blood gas findings?","options":[{"id":"a","text":"Increased PaO₂ and decreased PaCO₂"},{"id":"b","text":"Decreased PaO₂ and increased PaCO₂"},{"id":"c","text":"Increased PaCO₂ and normal PaO₂"},{"id":"d","text":"Normal PaO₂ and decreased PaCO₂"}],"answerId":"b","explanation":"V/Q mismatch typically results in decreased PaO₂ and increased PaCO₂ due to impaired gas exchange.","kind":"integration","linkedModuleIds":["ventilation-perfusion-matching"],"origin":"ai"}],"ventilation-perfusion-matching":[{"id":"ventilation-perfusion-matching~ai-0","moduleId":"ventilation-perfusion-matching","stem":"What is the ideal whole-lung V/Q ratio for efficient gas exchange?","options":[{"id":"a","text":"0.6"},{"id":"b","text":"0.8"},{"id":"c","text":"1.0"},{"id":"d","text":"3.0"}],"answerId":"b","explanation":"The ideal whole-lung V/Q ratio is approximately 0.8, which indicates a balance between ventilation and perfusion.","kind":"recall","origin":"ai"},{"id":"ventilation-perfusion-matching~ai-1","moduleId":"ventilation-perfusion-matching","stem":"In which condition does hypoxaemia fail to correct with 100% oxygen?","options":[{"id":"a","text":"V/Q mismatch"},{"id":"b","text":"High altitude"},{"id":"c","text":"True shunt"},{"id":"d","text":"Pulmonary embolism"}],"answerId":"c","explanation":"Hypoxaemia due to a true shunt does not correct with 100% oxygen because the shunted blood bypasses ventilated alveoli.","kind":"clinical","origin":"ai"},{"id":"ventilation-perfusion-matching~ai-2","moduleId":"ventilation-perfusion-matching","stem":"What happens to V/Q ratio in pulmonary embolism?","options":[{"id":"a","text":"Decreases to 0"},{"id":"b","text":"Increases to infinity"},{"id":"c","text":"Remains unchanged"},{"id":"d","text":"Decreases to 0.6"}],"answerId":"b","explanation":"In pulmonary embolism, the V/Q ratio approaches infinity as ventilation occurs without perfusion.","kind":"mechanism","origin":"ai"},{"id":"ventilation-perfusion-matching~ai-3","moduleId":"ventilation-perfusion-matching","stem":"Which area of the lung has the highest V/Q ratio?","options":[{"id":"a","text":"Base"},{"id":"b","text":"Middle"},{"id":"c","text":"Apex"},{"id":"d","text":"Lung hilum"}],"answerId":"c","explanation":"The apex of the lung has the highest V/Q ratio due to greater ventilation relative to perfusion.","kind":"recall","origin":"ai"},{"id":"ventilation-perfusion-matching~ai-4","moduleId":"ventilation-perfusion-matching","stem":"What is the physiological response to low V/Q regions in the lungs?","options":[{"id":"a","text":"Increased ventilation"},{"id":"b","text":"Decreased perfusion"},{"id":"c","text":"Hypoxic pulmonary vasoconstriction"},{"id":"d","text":"Increased shunting"}],"answerId":"c","explanation":"Hypoxic pulmonary vasoconstriction diverts blood away from poorly ventilated areas to optimize V/Q matching.","kind":"mechanism","origin":"ai"},{"id":"ventilation-perfusion-matching~ai-5","moduleId":"ventilation-perfusion-matching","stem":"How does a true shunt differ from V/Q mismatch in terms of oxygen therapy response?","options":[{"id":"a","text":"Both correct with oxygen"},{"id":"b","text":"Only shunt corrects"},{"id":"c","text":"Only V/Q mismatch corrects"},{"id":"d","text":"Neither corrects"}],"answerId":"c","explanation":"Only V/Q mismatch corrects with supplemental oxygen; a true shunt does not because the shunted blood bypasses ventilated areas.","kind":"trap","origin":"ai"},{"id":"ventilation-perfusion-matching~ai-6","moduleId":"ventilation-perfusion-matching","stem":"How might V/Q mismatch affect oxygen transport in a transplant recipient?","options":[{"id":"a","text":"Increased oxygen binding"},{"id":"b","text":"Decreased oxygen delivery"},{"id":"c","text":"Increased shunting"},{"id":"d","text":"Improved graft function"}],"answerId":"b","explanation":"V/Q mismatch can lead to decreased oxygen delivery to tissues, which is critical in transplant recipients.","kind":"integration","linkedModuleIds":["transplant-matching-immunosuppression"],"origin":"ai"},{"id":"ventilation-perfusion-matching~ai-7","moduleId":"ventilation-perfusion-matching","stem":"What is the effect of V/Q mismatch on arterial blood gas interpretation?","options":[{"id":"a","text":"Increased pH"},{"id":"b","text":"Decreased PaO2"},{"id":"c","text":"Increased PaCO2"},{"id":"d","text":"Normal oxygen saturation"}],"answerId":"b","explanation":"V/Q mismatch typically results in decreased PaO2, which is crucial for interpreting arterial blood gases.","kind":"integration","linkedModuleIds":["abg-acid-base-interpretation"],"origin":"ai"}],"gas-exchange-diffusion":[{"id":"gas-exchange-diffusion~ai-0","moduleId":"gas-exchange-diffusion","stem":"What is the primary driving force for gas exchange in the alveoli?","options":[{"id":"a","text":"Concentration gradient"},{"id":"b","text":"Partial-pressure gradient"},{"id":"c","text":"Temperature difference"},{"id":"d","text":"Surface area"}],"answerId":"b","explanation":"Gas exchange is driven by the partial-pressure gradient between alveolar gas and blood.","kind":"recall","origin":"ai"},{"id":"gas-exchange-diffusion~ai-1","moduleId":"gas-exchange-diffusion","stem":"Which condition is most likely to cause a decrease in the diffusing capacity (DLCO)?","options":[{"id":"a","text":"Pulmonary embolism"},{"id":"b","text":"Emphysema"},{"id":"c","text":"Asthma"},{"id":"d","text":"Bronchitis"}],"answerId":"b","explanation":"Emphysema reduces the surface area available for gas exchange, leading to decreased DLCO.","kind":"recall","origin":"ai"},{"id":"gas-exchange-diffusion~ai-2","moduleId":"gas-exchange-diffusion","stem":"In which scenario would oxygen transfer become diffusion-limited?","options":[{"id":"a","text":"Increased blood flow"},{"id":"b","text":"Thickened alveolar membrane"},{"id":"c","text":"High altitude"},{"id":"d","text":"Normal exercise"}],"answerId":"b","explanation":"A thickened alveolar membrane impairs diffusion, making oxygen transfer diffusion-limited.","kind":"mechanism","origin":"ai"},{"id":"gas-exchange-diffusion~ai-3","moduleId":"gas-exchange-diffusion","stem":"What is the expected arterial blood gas finding in a patient with a diffusion defect?","options":[{"id":"a","text":"Increased PaCO₂ and decreased PaO₂"},{"id":"b","text":"Decreased PaCO₂ and normal PaO₂"},{"id":"c","text":"Normal PaCO₂ and decreased PaO₂"},{"id":"d","text":"Increased PaO₂ and normal PaCO₂"}],"answerId":"a","explanation":"A diffusion defect primarily causes hypoxaemia (decreased PaO₂) and may lead to increased PaCO₂ later.","kind":"recall","origin":"ai"},{"id":"gas-exchange-diffusion~ai-4","moduleId":"gas-exchange-diffusion","stem":"Which gas is typically affected first in a diffusion defect?","options":[{"id":"a","text":"O₂"},{"id":"b","text":"CO₂"},{"id":"c","text":"N₂"},{"id":"d","text":"He"}],"answerId":"a","explanation":"Diffusion defects cause hypoxaemia first; CO₂ is usually still cleared due to its higher diffusibility.","kind":"trap","origin":"ai"},{"id":"gas-exchange-diffusion~ai-5","moduleId":"gas-exchange-diffusion","stem":"How does the solubility of CO₂ affect its diffusion compared to O₂?","options":[{"id":"a","text":"CO₂ diffuses slower than O₂"},{"id":"b","text":"CO₂ diffuses faster than O₂"},{"id":"c","text":"CO₂ and O₂ diffuse at the same rate"},{"id":"d","text":"CO₂ does not diffuse across membranes"}],"answerId":"b","explanation":"CO₂ diffuses approximately 20 times more readily than O₂ due to its higher solubility.","kind":"mechanism","origin":"ai"},{"id":"gas-exchange-diffusion~ai-6","moduleId":"gas-exchange-diffusion","stem":"How does impaired diffusion affect oxygen transport in relation to CO₂ transport?","options":[{"id":"a","text":"O₂ transport is unaffected while CO₂ transport decreases"},{"id":"b","text":"Both O₂ and CO₂ transport decrease equally"},{"id":"c","text":"O₂ transport decreases while CO₂ transport remains normal"},{"id":"d","text":"CO₂ transport decreases while O₂ transport remains normal"}],"answerId":"c","explanation":"Impaired diffusion primarily affects O₂ transport first; CO₂ is still cleared effectively due to its higher diffusibility.","kind":"integration","linkedModuleIds":["co2-transport-blood"],"origin":"ai"},{"id":"gas-exchange-diffusion~ai-7","moduleId":"gas-exchange-diffusion","stem":"What is the relationship between diffusion defects and the oxyhemoglobin dissociation curve?","options":[{"id":"a","text":"Shifts curve to the left"},{"id":"b","text":"Shifts curve to the right"},{"id":"c","text":"No effect on the curve"},{"id":"d","text":"Increases the slope of the curve"}],"answerId":"b","explanation":"Diffusion defects can lead to hypoxaemia, which may shift the oxyhemoglobin dissociation curve to the right, indicating reduced affinity for O₂.","kind":"integration","linkedModuleIds":["oxygen-transport-dissociation-curve"],"origin":"ai"}],"pulmonary-circulation-features":[{"id":"pulmonary-circulation-features~ai-0","moduleId":"pulmonary-circulation-features","stem":"What is the typical mean pulmonary artery pressure in a healthy adult at rest?","options":[{"id":"a","text":"25/8 mmHg"},{"id":"b","text":"120/80 mmHg"},{"id":"c","text":"15/5 mmHg"},{"id":"d","text":"30/10 mmHg"}],"answerId":"a","explanation":"The mean pulmonary artery pressure is approximately 15 mmHg, with systolic and diastolic pressures around 25/8 mmHg.","kind":"recall","origin":"ai"},{"id":"pulmonary-circulation-features~ai-1","moduleId":"pulmonary-circulation-features","stem":"What physiological response occurs in the pulmonary circulation when alveolar oxygen levels decrease?","options":[{"id":"a","text":"Vasodilation of pulmonary vessels"},{"id":"b","text":"Vasoconstriction of pulmonary vessels"},{"id":"c","text":"Increased pulmonary blood flow"},{"id":"d","text":"Decreased pulmonary vascular resistance"}],"answerId":"b","explanation":"Hypoxic pulmonary vasoconstriction occurs in response to low alveolar oxygen levels, diverting blood to better-ventilated areas.","kind":"mechanism","origin":"ai"},{"id":"pulmonary-circulation-features~ai-2","moduleId":"pulmonary-circulation-features","stem":"Which of the following conditions can lead to pulmonary edema due to increased pulmonary capillary hydrostatic pressure?","options":[{"id":"a","text":"Chronic obstructive pulmonary disease"},{"id":"b","text":"Left heart failure"},{"id":"c","text":"Pulmonary embolism"},{"id":"d","text":"Asthma"}],"answerId":"b","explanation":"Left heart failure increases pulmonary capillary hydrostatic pressure, leading to pulmonary edema.","kind":"clinical","origin":"ai"},{"id":"pulmonary-circulation-features~ai-3","moduleId":"pulmonary-circulation-features","stem":"During exercise, what happens to pulmonary vascular resistance (PVR)?","options":[{"id":"a","text":"It increases significantly"},{"id":"b","text":"It remains unchanged"},{"id":"c","text":"It decreases"},{"id":"d","text":"It fluctuates unpredictably"}],"answerId":"c","explanation":"PVR decreases during exercise due to capillary recruitment and distension, allowing for increased blood flow.","kind":"mechanism","origin":"ai"},{"id":"pulmonary-circulation-features~ai-4","moduleId":"pulmonary-circulation-features","stem":"Which statement correctly describes the effect of hypoxia on pulmonary versus systemic circulation?","options":[{"id":"a","text":"Hypoxia causes vasodilation in both systems"},{"id":"b","text":"Hypoxia causes vasoconstriction in the lungs"},{"id":"c","text":"Hypoxia has no effect on either system"},{"id":"d","text":"Hypoxia causes vasoconstriction in systemic circulation"}],"answerId":"b","explanation":"In the lungs, hypoxia causes vasoconstriction (hypoxic pulmonary vasoconstriction), which is the opposite of the systemic response.","kind":"trap","origin":"ai"},{"id":"pulmonary-circulation-features~ai-5","moduleId":"pulmonary-circulation-features","stem":"In chronic hypoxia, what is a potential consequence of widespread hypoxic pulmonary vasoconstriction?","options":[{"id":"a","text":"Decreased pulmonary artery pressure"},{"id":"b","text":"Cor pulmonale"},{"id":"c","text":"Increased lung compliance"},{"id":"d","text":"Improved V/Q matching"}],"answerId":"b","explanation":"Widespread hypoxic pulmonary vasoconstriction can lead to pulmonary hypertension and right heart failure (cor pulmonale).","kind":"clinical","origin":"ai"},{"id":"pulmonary-circulation-features~ai-6","moduleId":"pulmonary-circulation-features","stem":"How does pulmonary vascular resistance (PVR) change with lung volume?","options":[{"id":"a","text":"Lowest at high lung volumes"},{"id":"b","text":"Lowest at functional residual capacity"},{"id":"c","text":"Increases at all lung volumes"},{"id":"d","text":"Remains constant regardless of lung volume"}],"answerId":"b","explanation":"PVR is lowest at functional residual capacity (FRC) and increases at both high and low lung volumes due to vessel behavior.","kind":"mechanism","origin":"ai"},{"id":"pulmonary-circulation-features~ai-7","moduleId":"pulmonary-circulation-features","stem":"How does hypoxic pulmonary vasoconstriction improve ventilation-perfusion matching?","options":[{"id":"a","text":"By increasing blood flow to poorly ventilated areas"},{"id":"b","text":"By diverting blood flow away from poorly ventilated areas"},{"id":"c","text":"By increasing oxygen delivery to the lungs"},{"id":"d","text":"By decreasing pulmonary artery pressure"}],"answerId":"b","explanation":"Hypoxic pulmonary vasoconstriction diverts blood flow away from poorly ventilated areas, improving V/Q matching.","kind":"integration","linkedModuleIds":["ventilation-perfusion-matching"],"origin":"ai"},{"id":"pulmonary-circulation-features~ai-8","moduleId":"pulmonary-circulation-features","stem":"What role do lymphatics play in the pulmonary circulation?","options":[{"id":"a","text":"Increase pulmonary blood flow"},{"id":"b","text":"Drain excess fluid from the alveoli"},{"id":"c","text":"Enhance gas exchange"},{"id":"d","text":"Regulate pulmonary artery pressure"}],"answerId":"b","explanation":"Lymphatics help drain excess fluid from the alveoli, maintaining dry alveolar conditions for optimal gas exchange.","kind":"integration","linkedModuleIds":["alveoli-pneumocytes-respiratory-membrane"],"origin":"ai"}],"ecg-leads-axis":[{"id":"ecg-leads-axis~ai-0","moduleId":"ecg-leads-axis","stem":"What is the normal range for the mean QRS axis in degrees?","options":[{"id":"a","text":"-30° to +90°"},{"id":"b","text":"-60° to +60°"},{"id":"c","text":"0° to +180°"},{"id":"d","text":"-90° to +90°"}],"answerId":"a","explanation":"The normal mean QRS axis is approximately -30° to +90°.","kind":"recall","origin":"ai"},{"id":"ecg-leads-axis~ai-1","moduleId":"ecg-leads-axis","stem":"Which leads would indicate left axis deviation if lead I is positive and lead aVF is negative?","options":[{"id":"a","text":"Lead I and aVF"},{"id":"b","text":"Lead II and III"},{"id":"c","text":"Lead I and II"},{"id":"d","text":"Lead I and aVL"}],"answerId":"a","explanation":"Lead I positive with aVF negative indicates left axis deviation.","kind":"mechanism","origin":"ai"},{"id":"ecg-leads-axis~ai-2","moduleId":"ecg-leads-axis","stem":"What does ST segment elevation in leads II, III, and aVF suggest?","options":[{"id":"a","text":"Anterior MI"},{"id":"b","text":"Inferior MI"},{"id":"c","text":"Lateral MI"},{"id":"d","text":"Septal MI"}],"answerId":"b","explanation":"ST segment elevation in leads II, III, and aVF indicates an inferior myocardial infarction.","kind":"recall","origin":"ai"},{"id":"ecg-leads-axis~ai-3","moduleId":"ecg-leads-axis","stem":"In which condition would you expect to see right axis deviation?","options":[{"id":"a","text":"Left ventricular hypertrophy"},{"id":"b","text":"Pulmonary hypertension"},{"id":"c","text":"Inferior MI"},{"id":"d","text":"Aortic stenosis"}],"answerId":"b","explanation":"Right axis deviation is commonly associated with conditions like pulmonary hypertension.","kind":"clinical","origin":"ai"},{"id":"ecg-leads-axis~ai-4","moduleId":"ecg-leads-axis","stem":"If both lead I and aVF are negative, what does this indicate?","options":[{"id":"a","text":"Normal axis"},{"id":"b","text":"Left axis deviation"},{"id":"c","text":"Right axis deviation"},{"id":"d","text":"Extreme axis deviation"}],"answerId":"d","explanation":"Both lead I and aVF negative indicates extreme axis deviation.","kind":"trap","origin":"ai"},{"id":"ecg-leads-axis~ai-5","moduleId":"ecg-leads-axis","stem":"How does the cardiac electrical axis relate to the 12-lead ECG?","options":[{"id":"a","text":"It determines heart rate"},{"id":"b","text":"It shows the heart's electrical vector"},{"id":"c","text":"It measures blood pressure"},{"id":"d","text":"It indicates valve function"}],"answerId":"b","explanation":"The cardiac electrical axis shows the heart's electrical vector as viewed from different angles in the 12-lead ECG.","kind":"integration","linkedModuleIds":["cardiac-electrical-axis-vectors"],"origin":"ai"},{"id":"ecg-leads-axis~ai-6","moduleId":"ecg-leads-axis","stem":"Which leads are primarily used to assess the anterior territory of the heart?","options":[{"id":"a","text":"II, III, aVF"},{"id":"b","text":"I, aVL, V5–V6"},{"id":"c","text":"V1–V4"},{"id":"d","text":"aVR, aVL, aVF"}],"answerId":"c","explanation":"Leads V1–V4 are used to assess the anterior territory of the heart.","kind":"integration","linkedModuleIds":["stemi-localization"],"origin":"ai"}],"ecg-formation-waves":[{"id":"ecg-formation-waves~ai-0","moduleId":"ecg-formation-waves","stem":"What does the P wave on an ECG represent?","options":[{"id":"a","text":"Atrial depolarisation"},{"id":"b","text":"Ventricular depolarisation"},{"id":"c","text":"Ventricular repolarisation"},{"id":"d","text":"Atrial repolarisation"}],"answerId":"a","explanation":"The P wave specifically represents atrial depolarisation.","kind":"recall","origin":"ai"},{"id":"ecg-formation-waves~ai-1","moduleId":"ecg-formation-waves","stem":"What is indicated by a prolonged PR interval?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Slowed AV conduction"},{"id":"c","text":"Ventricular hypertrophy"},{"id":"d","text":"Atrial flutter"}],"answerId":"b","explanation":"A prolonged PR interval indicates slowed conduction through the AV node, often seen in first-degree heart block.","kind":"mechanism","origin":"ai"},{"id":"ecg-formation-waves~ai-2","moduleId":"ecg-formation-waves","stem":"Which of the following correctly describes the QRS complex?","options":[{"id":"a","text":"Atrial depolarisation"},{"id":"b","text":"Ventricular depolarisation"},{"id":"c","text":"Atrial repolarisation"},{"id":"d","text":"Ventricular repolarisation"}],"answerId":"b","explanation":"The QRS complex represents ventricular depolarisation, which is large due to the mass of the ventricles.","kind":"recall","origin":"ai"},{"id":"ecg-formation-waves~ai-3","moduleId":"ecg-formation-waves","stem":"A patient presents with a wide QRS complex (>0.12 s) on their ECG. What is the most likely cause?","options":[{"id":"a","text":"First-degree heart block"},{"id":"b","text":"Atrial fibrillation"},{"id":"c","text":"Bundle branch block"},{"id":"d","text":"Normal variant"}],"answerId":"c","explanation":"A wide QRS complex is typically indicative of a bundle branch block or a ventricular origin.","kind":"clinical","origin":"ai"},{"id":"ecg-formation-waves~ai-4","moduleId":"ecg-formation-waves","stem":"Which statement about the T wave is correct?","options":[{"id":"a","text":"It represents atrial repolarisation"},{"id":"b","text":"It represents ventricular repolarisation"},{"id":"c","text":"It is masked by the QRS complex"},{"id":"d","text":"It indicates AV node conduction time"}],"answerId":"b","explanation":"The T wave represents ventricular repolarisation; atrial repolarisation is hidden within the QRS complex.","kind":"trap","origin":"ai"},{"id":"ecg-formation-waves~ai-5","moduleId":"ecg-formation-waves","stem":"How is heart rate estimated from an ECG with a regular rhythm?","options":[{"id":"a","text":"Count the number of P waves"},{"id":"b","text":"Count the number of small boxes between R waves"},{"id":"c","text":"300 divided by the number of large boxes between R waves"},{"id":"d","text":"Count the number of T waves"}],"answerId":"c","explanation":"Heart rate can be estimated using the formula 300 divided by the number of large boxes between two R waves.","kind":"recall","origin":"ai"},{"id":"ecg-formation-waves~ai-6","moduleId":"ecg-formation-waves","stem":"How does the cardiac conduction system relate to the QRS complex?","options":[{"id":"a","text":"It initiates atrial depolarisation"},{"id":"b","text":"It influences the duration of the T wave"},{"id":"c","text":"It coordinates ventricular depolarisation"},{"id":"d","text":"It regulates heart rate variability"}],"answerId":"c","explanation":"The cardiac conduction system coordinates ventricular depolarisation, which is represented by the QRS complex.","kind":"integration","linkedModuleIds":["pacemaker-conduction-system"],"origin":"ai"},{"id":"ecg-formation-waves~ai-7","moduleId":"ecg-formation-waves","stem":"Which aspect of the ECG is crucial for understanding the cardiac action potential?","options":[{"id":"a","text":"P wave duration"},{"id":"b","text":"QRS complex morphology"},{"id":"c","text":"QT interval length"},{"id":"d","text":"T wave amplitude"}],"answerId":"c","explanation":"The QT interval reflects the total time for ventricular depolarisation and repolarisation, which is directly related to the cardiac action potential.","kind":"integration","linkedModuleIds":["cardiac-action-potential"],"origin":"ai"}],"cardiac-ion-currents-channels":[{"id":"cardiac-ion-currents-channels~ai-0","moduleId":"cardiac-ion-currents-channels","stem":"What ion current primarily contributes to the rapid depolarization phase (phase 0) of the ventricular action potential?","options":[{"id":"a","text":"Calcium influx"},{"id":"b","text":"Potassium efflux"},{"id":"c","text":"Sodium influx"},{"id":"d","text":"Chloride efflux"}],"answerId":"c","explanation":"Phase 0 of the ventricular action potential is characterized by a rapid influx of sodium ions through voltage-gated sodium channels.","kind":"recall","origin":"ai"},{"id":"cardiac-ion-currents-channels~ai-1","moduleId":"cardiac-ion-currents-channels","stem":"Which phase of the ventricular action potential is responsible for the long refractory period?","options":[{"id":"a","text":"Phase 0"},{"id":"b","text":"Phase 1"},{"id":"c","text":"Phase 2"},{"id":"d","text":"Phase 3"}],"answerId":"c","explanation":"Phase 2, the plateau phase, involves a balance of calcium influx and potassium efflux, contributing to the long refractory period.","kind":"recall","origin":"ai"},{"id":"cardiac-ion-currents-channels~ai-2","moduleId":"cardiac-ion-currents-channels","stem":"What is the mechanism by which ivabradine slows heart rate?","options":[{"id":"a","text":"Blocking sodium channels"},{"id":"b","text":"Blocking calcium channels"},{"id":"c","text":"Blocking the funny current"},{"id":"d","text":"Enhancing potassium efflux"}],"answerId":"c","explanation":"Ivabradine specifically blocks the funny current (I_f) in pacemaker cells, leading to a slower heart rate.","kind":"mechanism","origin":"ai"},{"id":"cardiac-ion-currents-channels~ai-3","moduleId":"cardiac-ion-currents-channels","stem":"A patient presents with QT prolongation after starting a new medication. Which class of drugs is most likely responsible?","options":[{"id":"a","text":"Class I antiarrhythmics"},{"id":"b","text":"Class II antiarrhythmics"},{"id":"c","text":"Class III antiarrhythmics"},{"id":"d","text":"Class IV antiarrhythmics"}],"answerId":"c","explanation":"Class III antiarrhythmics block potassium channels, which prolongs repolarization and can lead to QT interval prolongation.","kind":"clinical","origin":"ai"},{"id":"cardiac-ion-currents-channels~ai-4","moduleId":"cardiac-ion-currents-channels","stem":"Which statement about the pacemaker action potential is correct?","options":[{"id":"a","text":"It has a stable resting potential."},{"id":"b","text":"Phase 0 is driven by sodium influx."},{"id":"c","text":"Phase 4 is characterized by spontaneous depolarization."},{"id":"d","text":"It has a rapid upstroke like ventricular action potentials."}],"answerId":"c","explanation":"Pacemaker cells lack a stable resting potential and exhibit spontaneous phase-4 depolarization primarily through the funny current (I_f).","kind":"trap","origin":"ai"},{"id":"cardiac-ion-currents-channels~ai-5","moduleId":"cardiac-ion-currents-channels","stem":"How does calcium-induced calcium release contribute to cardiac contraction?","options":[{"id":"a","text":"It initiates the action potential."},{"id":"b","text":"It enhances sodium influx."},{"id":"c","text":"It triggers further calcium release from the sarcoplasmic reticulum."},{"id":"d","text":"It promotes potassium efflux."}],"answerId":"c","explanation":"Calcium-induced calcium release occurs when calcium entering during the plateau phase triggers additional calcium release from the sarcoplasmic reticulum, facilitating contraction.","kind":"mechanism","origin":"ai"},{"id":"cardiac-ion-currents-channels~ai-6","moduleId":"cardiac-ion-currents-channels","stem":"How does the cardiac action potential relate to hemodynamics, particularly cardiac output?","options":[{"id":"a","text":"It directly influences preload."},{"id":"b","text":"It determines afterload."},{"id":"c","text":"It affects heart rate and contractility."},{"id":"d","text":"It regulates blood volume."}],"answerId":"c","explanation":"The cardiac action potential influences heart rate and contractility, both of which are critical determinants of cardiac output.","kind":"integration","linkedModuleIds":["hemodynamics-preload-afterload-cardiac-output"],"origin":"ai"},{"id":"cardiac-ion-currents-channels~ai-7","moduleId":"cardiac-ion-currents-channels","stem":"Which mechanism links the cardiac action potential to the conduction system's function?","options":[{"id":"a","text":"Sodium influx in all cardiac cells"},{"id":"b","text":"Calcium influx in pacemaker cells"},{"id":"c","text":"Potassium efflux during repolarization"},{"id":"d","text":"Stable resting potential in nodal cells"}],"answerId":"b","explanation":"In pacemaker cells, the action potential is initiated by calcium influx, which is crucial for the conduction system's slower conduction velocity compared to ventricular cells.","kind":"integration","linkedModuleIds":["pacemaker-conduction-system"],"origin":"ai"}],"cardiac-action-potential":[{"id":"cardiac-action-potential~ai-0","moduleId":"cardiac-action-potential","stem":"What is the primary ion responsible for the rapid depolarization during phase 0 of the ventricular action potential?","options":[{"id":"a","text":"Ca²⁺"},{"id":"b","text":"K⁺"},{"id":"c","text":"Na⁺"},{"id":"d","text":"Cl⁻"}],"answerId":"c","explanation":"Phase 0 is characterized by a rapid influx of Na⁺ through fast Na⁺ channels, leading to depolarization.","kind":"recall","origin":"ai"},{"id":"cardiac-action-potential~ai-1","moduleId":"cardiac-action-potential","stem":"What mechanism sustains the plateau phase (phase 2) of the cardiac action potential?","options":[{"id":"a","text":"Increased Na⁺ influx"},{"id":"b","text":"Increased K⁺ efflux"},{"id":"c","text":"Balanced Ca²⁺ influx and K⁺ efflux"},{"id":"d","text":"Decreased Ca²⁺ influx"}],"answerId":"c","explanation":"The plateau phase is sustained by Ca²⁺ influx through L-type channels balancing K⁺ efflux.","kind":"mechanism","origin":"ai"},{"id":"cardiac-action-potential~ai-2","moduleId":"cardiac-action-potential","stem":"Which finding indicates that cardiac muscle cannot be tetanized?","options":[{"id":"a","text":"Short refractory period"},{"id":"b","text":"Long absolute refractory period"},{"id":"c","text":"Increased Ca²⁺ influx"},{"id":"d","text":"Rapid Na⁺ inactivation"}],"answerId":"b","explanation":"The long absolute refractory period prevents tetany by ensuring that a new action potential cannot be initiated until the muscle has nearly relaxed.","kind":"recall","origin":"ai"},{"id":"cardiac-action-potential~ai-3","moduleId":"cardiac-action-potential","stem":"What is the consequence of a prolonged QT interval?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Decreased contractility"},{"id":"c","text":"Risk of torsades de pointes"},{"id":"d","text":"Shortened refractory period"}],"answerId":"c","explanation":"A prolonged QT interval reflects a longer ventricular action potential, increasing the risk of torsades de pointes.","kind":"clinical","origin":"ai"},{"id":"cardiac-action-potential~ai-4","moduleId":"cardiac-action-potential","stem":"Which ion channel is primarily responsible for the automaticity of the SA node?","options":[{"id":"a","text":"Fast Na⁺ channels"},{"id":"b","text":"L-type Ca²⁺ channels"},{"id":"c","text":"Transient K⁺ channels"},{"id":"d","text":"Funny Na⁺ channels"}],"answerId":"d","explanation":"The funny Na⁺ channels contribute to the unstable phase 4 depolarization that leads to automaticity in the SA node.","kind":"recall","linkedModuleIds":["pacemaker-conduction-system"],"origin":"ai"},{"id":"cardiac-action-potential~ai-5","moduleId":"cardiac-action-potential","stem":"How does the cardiac action potential differ from that of skeletal muscle?","options":[{"id":"a","text":"Longer duration due to Na⁺ influx"},{"id":"b","text":"Presence of a plateau phase due to Ca²⁺ influx"},{"id":"c","text":"Faster repolarization due to K⁺ efflux"},{"id":"d","text":"No refractory period in cardiac muscle"}],"answerId":"b","explanation":"The cardiac action potential features a plateau phase due to Ca²⁺ influx, which is not present in skeletal muscle action potentials.","kind":"trap","origin":"ai"},{"id":"cardiac-action-potential~ai-6","moduleId":"cardiac-action-potential","stem":"What is the role of Ca²⁺ during the plateau phase of the cardiac action potential?","options":[{"id":"a","text":"Triggers Na⁺ channel inactivation"},{"id":"b","text":"Balances K⁺ efflux to sustain contraction"},{"id":"c","text":"Initiates repolarization"},{"id":"d","text":"Decreases heart rate"}],"answerId":"b","explanation":"Ca²⁺ influx during the plateau phase balances K⁺ efflux, sustaining contraction and preventing rapid repolarization.","kind":"mechanism","linkedModuleIds":["cardiac-ion-currents-channels"],"origin":"ai"}],"coronary-circulation":[{"id":"coronary-circulation~ai-0","moduleId":"coronary-circulation","stem":"Which artery primarily supplies the anterior wall of the left ventricle?","options":[{"id":"a","text":"Left coronary artery"},{"id":"b","text":"Right coronary artery"},{"id":"c","text":"Circumflex artery"},{"id":"d","text":"Posterior descending artery"}],"answerId":"a","explanation":"The left coronary artery branches into the left anterior descending artery, which supplies the anterior wall of the left ventricle.","kind":"recall","origin":"ai"},{"id":"coronary-circulation~ai-1","moduleId":"coronary-circulation","stem":"What is the primary reason for myocardial perfusion occurring during diastole?","options":[{"id":"a","text":"High systolic pressure"},{"id":"b","text":"Coronary artery compression during systole"},{"id":"c","text":"Increased heart rate"},{"id":"d","text":"Enhanced venous return"}],"answerId":"b","explanation":"During systole, the contraction of the heart compresses the intramural coronary vessels, limiting blood flow; thus, perfusion occurs mainly during diastole.","kind":"mechanism","origin":"ai"},{"id":"coronary-circulation~ai-2","moduleId":"coronary-circulation","stem":"A patient presents with inferior ST-segment elevation on an ECG and bradycardia. Which artery is most likely occluded?","options":[{"id":"a","text":"Left coronary artery"},{"id":"b","text":"Right coronary artery"},{"id":"c","text":"Circumflex artery"},{"id":"d","text":"Anterior descending artery"}],"answerId":"b","explanation":"The right coronary artery supplies the SA and AV nodes; occlusion can lead to inferior MI and associated bradycardia.","kind":"clinical","origin":"ai"},{"id":"coronary-circulation~ai-3","moduleId":"coronary-circulation","stem":"Which of the following findings would be expected in a patient with an anterior myocardial infarction?","options":[{"id":"a","text":"Bradycardia"},{"id":"b","text":"ST elevation in inferior leads"},{"id":"c","text":"ST elevation in anterior leads"},{"id":"d","text":"Coronary sinus drainage into the left atrium"}],"answerId":"c","explanation":"An anterior myocardial infarction is characterized by ST elevation in the anterior leads due to LAD occlusion.","kind":"recall","origin":"ai"},{"id":"coronary-circulation~ai-4","moduleId":"coronary-circulation","stem":"In a right-dominant coronary circulation, which artery gives rise to the posterior descending artery?","options":[{"id":"a","text":"Left coronary artery"},{"id":"b","text":"Right coronary artery"},{"id":"c","text":"Circumflex artery"},{"id":"d","text":"Left anterior descending artery"}],"answerId":"b","explanation":"In approximately 85% of individuals with right dominance, the posterior descending artery arises from the right coronary artery.","kind":"recall","origin":"ai"},{"id":"coronary-circulation~ai-5","moduleId":"coronary-circulation","stem":"How does tachycardia contribute to angina symptoms?","options":[{"id":"a","text":"Increases myocardial oxygen demand"},{"id":"b","text":"Decreases coronary perfusion time"},{"id":"c","text":"Increases diastolic pressure"},{"id":"d","text":"Enhances venous return"}],"answerId":"b","explanation":"Tachycardia shortens diastole, reducing the time available for coronary perfusion, which can lead to angina.","kind":"trap","origin":"ai"},{"id":"coronary-circulation~ai-6","moduleId":"coronary-circulation","stem":"How does the mechanism of coronary blood flow relate to shock states?","options":[{"id":"a","text":"Increased heart rate improves perfusion"},{"id":"b","text":"Diastolic pressure is critical for perfusion"},{"id":"c","text":"Systolic pressure drives coronary flow"},{"id":"d","text":"Coronary flow is independent of heart rate"}],"answerId":"b","explanation":"In shock states, maintaining adequate diastolic pressure is crucial for coronary perfusion, as the heart is primarily perfused during diastole.","kind":"integration","linkedModuleIds":["shock-mechanisms-types"],"origin":"ai"},{"id":"coronary-circulation~ai-7","moduleId":"coronary-circulation","stem":"Which cardiac cycle phase is most affected by coronary artery occlusion leading to ischemia?","options":[{"id":"a","text":"Systole"},{"id":"b","text":"Diastole"},{"id":"c","text":"Atrial contraction"},{"id":"d","text":"Isovolumetric relaxation"}],"answerId":"b","explanation":"Coronary artery occlusion primarily affects diastolic perfusion, leading to ischemia during the phase when the heart is normally perfused.","kind":"integration","linkedModuleIds":["cardiac-cycle-heart-sounds"],"origin":"ai"}],"ecg-intervals-segments":[{"id":"ecg-intervals-segments~ai-0","moduleId":"ecg-intervals-segments","stem":"What is the normal range for the PR interval on an ECG?","options":[{"id":"a","text":"0.04–0.12 s"},{"id":"b","text":"0.12–0.20 s"},{"id":"c","text":"0.20–0.30 s"},{"id":"d","text":"0.30–0.40 s"}],"answerId":"b","explanation":"The normal PR interval ranges from 0.12 to 0.20 seconds, indicating normal AV conduction.","kind":"recall","origin":"ai"},{"id":"ecg-intervals-segments~ai-1","moduleId":"ecg-intervals-segments","stem":"A patient presents with a wide QRS complex on their ECG. What does this indicate?","options":[{"id":"a","text":"Increased ventricular mass"},{"id":"b","text":"Slowed ventricular depolarization"},{"id":"c","text":"Strong ventricular contraction"},{"id":"d","text":"Normal conduction"}],"answerId":"b","explanation":"A wide QRS complex (>0.12 s) indicates slowed ventricular depolarization due to conduction delays.","kind":"mechanism","origin":"ai"},{"id":"ecg-intervals-segments~ai-2","moduleId":"ecg-intervals-segments","stem":"Which ECG finding is indicative of myocardial ischemia?","options":[{"id":"a","text":"Prolonged QT interval"},{"id":"b","text":"ST segment elevation"},{"id":"c","text":"Narrow QRS complex"},{"id":"d","text":"Short PR interval"}],"answerId":"b","explanation":"ST segment elevation is a classic sign of myocardial ischemia or injury.","kind":"recall","origin":"ai"},{"id":"ecg-intervals-segments~ai-3","moduleId":"ecg-intervals-segments","stem":"What does a prolonged QT interval on an ECG suggest?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Risk of torsades de pointes"},{"id":"c","text":"First-degree AV block"},{"id":"d","text":"Normal ventricular repolarization"}],"answerId":"b","explanation":"A prolonged QT interval increases the risk of torsades de pointes, a type of life-threatening arrhythmia.","kind":"trap","origin":"ai"},{"id":"ecg-intervals-segments~ai-4","moduleId":"ecg-intervals-segments","stem":"A patient shows a short PR interval with a delta wave on their ECG. What condition does this suggest?","options":[{"id":"a","text":"First-degree AV block"},{"id":"b","text":"Ventricular pre-excitation (WPW)"},{"id":"c","text":"Bundle branch block"},{"id":"d","text":"Myocardial infarction"}],"answerId":"b","explanation":"A short PR interval with a delta wave is characteristic of Wolff-Parkinson-White syndrome, indicating ventricular pre-excitation.","kind":"clinical","origin":"ai"},{"id":"ecg-intervals-segments~ai-5","moduleId":"ecg-intervals-segments","stem":"How is heart rate calculated from an ECG?","options":[{"id":"a","text":"Count P waves in 6 seconds"},{"id":"b","text":"Count QRS complexes in 6 seconds and multiply by 10"},{"id":"c","text":"Count T waves in 10 seconds"},{"id":"d","text":"Count large boxes between R waves and divide by 300"}],"answerId":"b","explanation":"Heart rate can be calculated by counting QRS complexes in a 6-second strip and multiplying by 10.","kind":"recall","origin":"ai"},{"id":"ecg-intervals-segments~ai-6","moduleId":"ecg-intervals-segments","stem":"How does the QT interval relate to the ST segment in terms of cardiac physiology?","options":[{"id":"a","text":"QT reflects depolarization only, ST reflects repolarization"},{"id":"b","text":"QT reflects total depolarization and repolarization, ST reflects injury"},{"id":"c","text":"QT is measured from P to T, ST from Q to T"},{"id":"d","text":"QT is unaffected by heart rate, ST is always isoelectric"}],"answerId":"b","explanation":"The QT interval reflects total ventricular depolarization and repolarization, while the ST segment indicates myocardial injury or ischemia.","kind":"integration","linkedModuleIds":["ecg-systematic-interpretation"],"origin":"ai"},{"id":"ecg-intervals-segments~ai-7","moduleId":"ecg-intervals-segments","stem":"Which ECG finding would most likely correlate with a diagnosis of left atrial enlargement?","options":[{"id":"a","text":"Prolonged PR interval"},{"id":"b","text":"Wide QRS complex"},{"id":"c","text":"Biphasic P wave in lead V1"},{"id":"d","text":"Short QT interval"}],"answerId":"c","explanation":"A biphasic P wave in lead V1 is often indicative of left atrial enlargement, reflecting changes in atrial conduction.","kind":"integration","linkedModuleIds":["ecg-chamber-enlargement"],"origin":"ai"}],"heart-wall-cardiac-histology":[{"id":"heart-wall-cardiac-histology~ai-0","moduleId":"heart-wall-cardiac-histology","stem":"Which layer of the heart wall is primarily composed of cardiac muscle?","options":[{"id":"a","text":"Endocardium"},{"id":"b","text":"Myocardium"},{"id":"c","text":"Epicardium"},{"id":"d","text":"Pericardium"}],"answerId":"b","explanation":"The myocardium is the thickest layer of the heart wall and is primarily composed of cardiac muscle.","kind":"recall","origin":"ai"},{"id":"heart-wall-cardiac-histology~ai-1","moduleId":"heart-wall-cardiac-histology","stem":"What is the histological hallmark of cardiac muscle?","options":[{"id":"a","text":"Peripheral nuclei"},{"id":"b","text":"Intercalated discs"},{"id":"c","text":"Striated fibers"},{"id":"d","text":"Multinucleated cells"}],"answerId":"b","explanation":"Intercalated discs are the histological hallmark of cardiac muscle, allowing for mechanical and electrical coupling.","kind":"recall","origin":"ai"},{"id":"heart-wall-cardiac-histology~ai-2","moduleId":"heart-wall-cardiac-histology","stem":"Which structure is responsible for the rapid conduction of impulses in the heart?","options":[{"id":"a","text":"SA node"},{"id":"b","text":"AV node"},{"id":"c","text":"Purkinje fibers"},{"id":"d","text":"Cardiac skeleton"}],"answerId":"c","explanation":"Purkinje fibers are specialized cells that facilitate rapid conduction of impulses in the heart.","kind":"recall","origin":"ai"},{"id":"heart-wall-cardiac-histology~ai-3","moduleId":"heart-wall-cardiac-histology","stem":"What is the primary reason cardiac muscle heals by fibrous scar after an infarct?","options":[{"id":"a","text":"High regenerative capacity"},{"id":"b","text":"Presence of satellite cells"},{"id":"c","text":"Inability to regenerate"},{"id":"d","text":"Presence of smooth muscle"}],"answerId":"c","explanation":"Cardiac muscle has a limited ability to regenerate, leading to healing by fibrous scar formation after an infarct.","kind":"trap","origin":"ai"},{"id":"heart-wall-cardiac-histology~ai-4","moduleId":"heart-wall-cardiac-histology","stem":"Which of the following best describes the conduction system of the heart?","options":[{"id":"a","text":"It is composed of nerve tissue."},{"id":"b","text":"It is modified cardiac muscle."},{"id":"c","text":"It originates from the brain."},{"id":"d","text":"It is purely electrical tissue."}],"answerId":"b","explanation":"The conduction system is made up of modified cardiac muscle cells, not nerve tissue.","kind":"trap","origin":"ai"},{"id":"heart-wall-cardiac-histology~ai-5","moduleId":"heart-wall-cardiac-histology","stem":"How does the cardiac skeleton function in the heart's conduction system?","options":[{"id":"a","text":"It generates electrical impulses."},{"id":"b","text":"It anchors the valves."},{"id":"c","text":"It insulates atria from ventricles."},{"id":"d","text":"It contains pacemaker cells."}],"answerId":"c","explanation":"The cardiac skeleton electrically insulates the atria from the ventricles, allowing impulses to pass only through the AV node.","kind":"mechanism","origin":"ai"},{"id":"heart-wall-cardiac-histology~ai-6","moduleId":"heart-wall-cardiac-histology","stem":"How does the structure of cardiac muscle differ from skeletal muscle?","options":[{"id":"a","text":"Cardiac muscle has peripheral nuclei."},{"id":"b","text":"Cardiac muscle is voluntary."},{"id":"c","text":"Cardiac muscle has intercalated discs."},{"id":"d","text":"Cardiac muscle is multinucleated."}],"answerId":"c","explanation":"Cardiac muscle has intercalated discs, which are not present in skeletal muscle, allowing for functional syncytium.","kind":"mechanism","origin":"ai"},{"id":"heart-wall-cardiac-histology~ai-7","moduleId":"heart-wall-cardiac-histology","stem":"In which module would you find detailed information about the conduction system's pacemaker activity?","options":[{"id":"a","text":"Histology of the Heart Wall"},{"id":"b","text":"Atrioventricular (AV) Block"},{"id":"c","text":"The Pacemaker & Cardiac Conduction System"},{"id":"d","text":"Heart Anatomy: Chambers, Valves & Wall"}],"answerId":"c","explanation":"The Pacemaker & Cardiac Conduction System module covers the details of pacemaker activity in the heart.","kind":"integration","linkedModuleIds":["pacemaker-conduction-system"],"origin":"ai"},{"id":"heart-wall-cardiac-histology~ai-8","moduleId":"heart-wall-cardiac-histology","stem":"What histological feature would you expect to find in both cardiac muscle and smooth muscle?","options":[{"id":"a","text":"Intercalated discs"},{"id":"b","text":"Striated fibers"},{"id":"c","text":"Central nuclei"},{"id":"d","text":"Involuntary contraction"}],"answerId":"d","explanation":"Both cardiac muscle and smooth muscle are involuntary, although their histological features differ.","kind":"integration","linkedModuleIds":["cardiac-smooth-muscle"],"origin":"ai"}],"blood-vessel-histology":[{"id":"blood-vessel-histology~ai-0","moduleId":"blood-vessel-histology","stem":"Which layer of the blood vessel wall is primarily responsible for regulating blood flow through vasoconstriction and vasodilation?","options":[{"id":"a","text":"Tunica intima"},{"id":"b","text":"Tunica media"},{"id":"c","text":"Tunica adventitia"},{"id":"d","text":"Endothelium"}],"answerId":"b","explanation":"The tunica media, composed mainly of smooth muscle, is responsible for regulating blood flow through vasoconstriction and vasodilation.","kind":"recall","origin":"ai"},{"id":"blood-vessel-histology~ai-1","moduleId":"blood-vessel-histology","stem":"What type of capillary is characterized by pores that facilitate filtration, particularly in the kidneys?","options":[{"id":"a","text":"Continuous capillary"},{"id":"b","text":"Fenestrated capillary"},{"id":"c","text":"Sinusoidal capillary"},{"id":"d","text":"Discontinuous capillary"}],"answerId":"b","explanation":"Fenestrated capillaries have pores that allow for increased permeability, particularly important in the renal glomerulus for filtration.","kind":"recall","origin":"ai"},{"id":"blood-vessel-histology~ai-2","moduleId":"blood-vessel-histology","stem":"Which vessel type has the thickest tunica media and is primarily involved in distributing blood to organs?","options":[{"id":"a","text":"Elastic artery"},{"id":"b","text":"Muscular artery"},{"id":"c","text":"Capillary"},{"id":"d","text":"Vein"}],"answerId":"b","explanation":"Muscular arteries have a thick tunica media composed of smooth muscle, allowing them to regulate blood distribution to various organs.","kind":"recall","origin":"ai"},{"id":"blood-vessel-histology~ai-3","moduleId":"blood-vessel-histology","stem":"What is the primary function of elastic arteries during the cardiac cycle?","options":[{"id":"a","text":"Store energy during diastole"},{"id":"b","text":"Regulate blood pressure"},{"id":"c","text":"Facilitate nutrient exchange"},{"id":"d","text":"Prevent backflow of blood"}],"answerId":"a","explanation":"Elastic arteries, like the aorta, store energy during systole and recoil during diastole, smoothing out the pulsatile flow of blood.","kind":"mechanism","origin":"ai"},{"id":"blood-vessel-histology~ai-4","moduleId":"blood-vessel-histology","stem":"A patient presents with a thin-walled vessel that contains valves. What type of vessel is this likely to be?","options":[{"id":"a","text":"Artery"},{"id":"b","text":"Capillary"},{"id":"c","text":"Vein"},{"id":"d","text":"Arteriole"}],"answerId":"c","explanation":"Veins are characterized by thin walls, large lumens, and often contain valves to prevent backflow of blood.","kind":"recall","origin":"ai"},{"id":"blood-vessel-histology~ai-5","moduleId":"blood-vessel-histology","stem":"Which of the following statements about the aorta is correct?","options":[{"id":"a","text":"It has a media dominated by smooth muscle."},{"id":"b","text":"It is a muscular artery."},{"id":"c","text":"It is an elastic artery."},{"id":"d","text":"It contains no elastic laminae."}],"answerId":"c","explanation":"The aorta is classified as an elastic artery, with a media dominated by elastic laminae that allow for recoil during diastole.","kind":"trap","origin":"ai"},{"id":"blood-vessel-histology~ai-6","moduleId":"blood-vessel-histology","stem":"How does the structure of veins relate to their function in the circulatory system?","options":[{"id":"a","text":"Thick walls for high pressure"},{"id":"b","text":"Valves to prevent backflow"},{"id":"c","text":"Small lumens for resistance"},{"id":"d","text":"Elastic fibers for recoil"}],"answerId":"b","explanation":"Veins have thin walls and large lumens, and many contain valves to prevent backflow, aiding in venous return.","kind":"clinical","origin":"ai"},{"id":"blood-vessel-histology~ai-8","moduleId":"blood-vessel-histology","stem":"What histological feature of the aorta contributes to its function in the systemic circulation?","options":[{"id":"a","text":"Thick smooth muscle"},{"id":"b","text":"Elastic laminae"},{"id":"c","text":"Fenestrated endothelium"},{"id":"d","text":"Valves"}],"answerId":"b","explanation":"The elastic laminae in the aorta allow it to stretch and recoil, which is essential for maintaining steady blood flow in the systemic circulation.","kind":"integration","linkedModuleIds":["systemic-pulmonary-circulation"],"origin":"ai"}],"heart-tube-looping-septation":[{"id":"heart-tube-looping-septation~ai-0","moduleId":"heart-tube-looping-septation","stem":"Which structure is formed first during heart development?","options":[{"id":"a","text":"Atrial septum"},{"id":"b","text":"Primary heart tube"},{"id":"c","text":"Ventricular septum"},{"id":"d","text":"Truncus arteriosus"}],"answerId":"b","explanation":"The primary heart tube forms from cardiogenic mesoderm and is the first structure in heart development.","kind":"recall","origin":"ai"},{"id":"heart-tube-looping-septation~ai-1","moduleId":"heart-tube-looping-septation","stem":"What is the consequence of abnormal leftward cardiac looping?","options":[{"id":"a","text":"Atrial septal defect"},{"id":"b","text":"Dextrocardia"},{"id":"c","text":"Tetralogy of Fallot"},{"id":"d","text":"Transposition of the great arteries"}],"answerId":"b","explanation":"Abnormal leftward looping results in dextrocardia, where the heart is positioned on the right side of the thorax.","kind":"mechanism","origin":"ai"},{"id":"heart-tube-looping-septation~ai-2","moduleId":"heart-tube-looping-septation","stem":"Which congenital heart defect results from failure of the aorticopulmonary septum to spiral?","options":[{"id":"a","text":"Ventricular septal defect"},{"id":"b","text":"Atrial septal defect"},{"id":"c","text":"Transposition of the great arteries"},{"id":"d","text":"Tetralogy of Fallot"}],"answerId":"c","explanation":"Transposition of the great arteries occurs when the aorticopulmonary septum fails to spiral correctly during development.","kind":"mechanism","origin":"ai"},{"id":"heart-tube-looping-septation~ai-3","moduleId":"heart-tube-looping-septation","stem":"What is the most common congenital heart defect?","options":[{"id":"a","text":"Atrial septal defect"},{"id":"b","text":"Ventricular septal defect"},{"id":"c","text":"Patent foramen ovale"},{"id":"d","text":"Tetralogy of Fallot"}],"answerId":"b","explanation":"The membranous ventricular septal defect (VSD) is the most common congenital heart defect, not the atrial septal defect.","kind":"trap","origin":"ai"},{"id":"heart-tube-looping-septation~ai-4","moduleId":"heart-tube-looping-septation","stem":"A patient presents with a heart murmur and signs of heart failure. An echocardiogram shows a defect in the ventricular septum. What is the most likely diagnosis?","options":[{"id":"a","text":"Atrial septal defect"},{"id":"b","text":"Ventricular septal defect"},{"id":"c","text":"Transposition of the great arteries"},{"id":"d","text":"Tetralogy of Fallot"}],"answerId":"b","explanation":"The presence of a ventricular septal defect is consistent with the diagnosis of a ventricular septal defect, which is common and can lead to heart failure.","kind":"clinical","origin":"ai"},{"id":"heart-tube-looping-septation~ai-5","moduleId":"heart-tube-looping-septation","stem":"How does the foramen ovale function in fetal circulation?","options":[{"id":"a","text":"Allows blood to flow from right to left atrium"},{"id":"b","text":"Allows blood to flow from left to right atrium"},{"id":"c","text":"Diverts blood to the lungs"},{"id":"d","text":"Prevents blood from entering the aorta"}],"answerId":"a","explanation":"The foramen ovale acts as a flap valve allowing blood to shunt from the right atrium to the left atrium in fetal circulation.","kind":"recall","origin":"ai"},{"id":"heart-tube-looping-septation~ai-6","moduleId":"heart-tube-looping-septation","stem":"How is the concept of atrial septal defect (ASD) related to the development of the heart?","options":[{"id":"a","text":"It results from failure of the septum primum to grow"},{"id":"b","text":"It is caused by abnormal looping of the heart"},{"id":"c","text":"It is due to improper formation of the aorticopulmonary septum"},{"id":"d","text":"It arises from failure of the interventricular septum to form"}],"answerId":"a","explanation":"Atrial septal defect occurs when the septum primum fails to fuse properly, allowing abnormal communication between the atria.","kind":"integration","linkedModuleIds":["asd"],"origin":"ai"},{"id":"heart-tube-looping-septation~ai-7","moduleId":"heart-tube-looping-septation","stem":"What is the relationship between Tetralogy of Fallot and the development of the heart?","options":[{"id":"a","text":"It is caused by failure of the atrial septum to form"},{"id":"b","text":"It results from unequal division of the aorticopulmonary septum"},{"id":"c","text":"It is due to abnormal looping of the heart"},{"id":"d","text":"It arises from failure of the ventricular septum to close"}],"answerId":"b","explanation":"Tetralogy of Fallot is caused by unequal division of the aorticopulmonary septum during heart development.","kind":"integration","linkedModuleIds":["tetralogy-of-fallot"],"origin":"ai"}],"fetal-circulation-shunts":[{"id":"fetal-circulation-shunts~ai-0","moduleId":"fetal-circulation-shunts","stem":"What is the remnant of the ductus venosus in adults?","options":[{"id":"a","text":"Fossa ovalis"},{"id":"b","text":"Ligamentum venosum"},{"id":"c","text":"Ligamentum arteriosum"},{"id":"d","text":"Medial umbilical ligaments"}],"answerId":"b","explanation":"The ductus venosus closes after birth and becomes the ligamentum venosum.","kind":"recall","origin":"ai"},{"id":"fetal-circulation-shunts~ai-1","moduleId":"fetal-circulation-shunts","stem":"Which shunt allows oxygenated blood to bypass the fetal liver?","options":[{"id":"a","text":"Foramen ovale"},{"id":"b","text":"Ductus arteriosus"},{"id":"c","text":"Ductus venosus"},{"id":"d","text":"Umbilical arteries"}],"answerId":"c","explanation":"The ductus venosus carries oxygenated blood from the umbilical vein to the inferior vena cava, bypassing the liver.","kind":"recall","origin":"ai"},{"id":"fetal-circulation-shunts~ai-2","moduleId":"fetal-circulation-shunts","stem":"What mechanism causes the foramen ovale to close after birth?","options":[{"id":"a","text":"Increased right atrial pressure"},{"id":"b","text":"Decreased left atrial pressure"},{"id":"c","text":"Increased left atrial pressure"},{"id":"d","text":"Decreased pulmonary resistance"}],"answerId":"c","explanation":"The foramen ovale closes as left atrial pressure rises after birth.","kind":"mechanism","origin":"ai"},{"id":"fetal-circulation-shunts~ai-3","moduleId":"fetal-circulation-shunts","stem":"Which statement about the ductus arteriosus is correct?","options":[{"id":"a","text":"NSAIDs keep it open"},{"id":"b","text":"Prostaglandins close it"},{"id":"c","text":"It connects the aorta to the pulmonary artery"},{"id":"d","text":"It closes immediately at birth"}],"answerId":"c","explanation":"The ductus arteriosus connects the pulmonary artery to the aorta and is kept open by prostaglandins in utero.","kind":"trap","origin":"ai"},{"id":"fetal-circulation-shunts~ai-4","moduleId":"fetal-circulation-shunts","stem":"A newborn presents with a machinery murmur. What is the likely diagnosis?","options":[{"id":"a","text":"Patent ductus arteriosus"},{"id":"b","text":"Atrial septal defect"},{"id":"c","text":"Ventricular septal defect"},{"id":"d","text":"Foramen ovale"}],"answerId":"a","explanation":"A machinery murmur is characteristic of a patent ductus arteriosus, indicating failure to close after birth.","kind":"clinical","origin":"ai"},{"id":"fetal-circulation-shunts~ai-5","moduleId":"fetal-circulation-shunts","stem":"How does the closure of the ductus arteriosus occur after birth?","options":[{"id":"a","text":"Increased prostaglandins"},{"id":"b","text":"Decreased oxygen levels"},{"id":"c","text":"Increased oxygen levels"},{"id":"d","text":"Decreased blood flow to the lungs"}],"answerId":"c","explanation":"The ductus arteriosus closes due to increased oxygen levels and decreased prostaglandins after birth.","kind":"mechanism","origin":"ai"},{"id":"fetal-circulation-shunts~ai-6","moduleId":"fetal-circulation-shunts","stem":"Which structure is responsible for carrying oxygenated blood from the placenta to the fetus?","options":[{"id":"a","text":"Umbilical arteries"},{"id":"b","text":"Ductus arteriosus"},{"id":"c","text":"Umbilical vein"},{"id":"d","text":"Ductus venosus"}],"answerId":"c","explanation":"The umbilical vein carries oxygenated blood from the placenta to the fetus.","kind":"recall","origin":"ai"},{"id":"fetal-circulation-shunts~ai-7","moduleId":"fetal-circulation-shunts","stem":"How does fetal circulation differ from adult circulation in terms of oxygenation?","options":[{"id":"a","text":"Lungs oxygenate blood"},{"id":"b","text":"Placenta oxygenates blood"},{"id":"c","text":"Liver oxygenates blood"},{"id":"d","text":"Kidneys oxygenate blood"}],"answerId":"b","explanation":"In fetal circulation, the placenta, not the lungs, is responsible for oxygenating blood.","kind":"integration","linkedModuleIds":["placenta-development-circulation"],"origin":"ai"},{"id":"fetal-circulation-shunts~ai-8","moduleId":"fetal-circulation-shunts","stem":"What is the fate of the foramen ovale if it fails to close after birth?","options":[{"id":"a","text":"It becomes the ductus arteriosus"},{"id":"b","text":"It remains a patent foramen ovale"},{"id":"c","text":"It becomes the ligamentum arteriosum"},{"id":"d","text":"It closes permanently"}],"answerId":"b","explanation":"If the foramen ovale does not close, it remains a patent foramen ovale.","kind":"integration","linkedModuleIds":["heart-tube-looping-septation"],"origin":"ai"}],"pacemaker-conduction-system":[{"id":"pacemaker-conduction-system~ai-0","moduleId":"pacemaker-conduction-system","stem":"What is the primary function of the AV node in the cardiac conduction system?","options":[{"id":"a","text":"To initiate the heartbeat"},{"id":"b","text":"To delay the impulse allowing ventricular filling"},{"id":"c","text":"To increase heart rate during exercise"},{"id":"d","text":"To conduct impulses directly to the ventricles"}],"answerId":"b","explanation":"The AV node delays the impulse to allow the atria to finish contracting and fill the ventricles before ventricular systole.","kind":"recall","origin":"ai"},{"id":"pacemaker-conduction-system~ai-1","moduleId":"pacemaker-conduction-system","stem":"Which ion primarily drives the upstroke of action potentials in pacemaker cells?","options":[{"id":"a","text":"Sodium (Na⁺)"},{"id":"b","text":"Calcium (Ca²⁺)"},{"id":"c","text":"Potassium (K⁺)"},{"id":"d","text":"Chloride (Cl⁻)"}],"answerId":"b","explanation":"In pacemaker cells, the phase-0 upstroke is primarily driven by calcium (Ca²⁺) influx.","kind":"mechanism","origin":"ai"},{"id":"pacemaker-conduction-system~ai-2","moduleId":"pacemaker-conduction-system","stem":"What is the intrinsic firing rate of the SA node?","options":[{"id":"a","text":"20–40 beats per minute"},{"id":"b","text":"40–60 beats per minute"},{"id":"c","text":"60–100 beats per minute"},{"id":"d","text":"100–120 beats per minute"}],"answerId":"c","explanation":"The SA node has an intrinsic firing rate of approximately 60–100 beats per minute.","kind":"recall","origin":"ai"},{"id":"pacemaker-conduction-system~ai-3","moduleId":"pacemaker-conduction-system","stem":"A patient presents with a complete heart block. What is the expected heart rate from the ventricular escape rhythm?","options":[{"id":"a","text":"60–100 beats per minute"},{"id":"b","text":"40–60 beats per minute"},{"id":"c","text":"30–40 beats per minute"},{"id":"d","text":"20–30 beats per minute"}],"answerId":"c","explanation":"In complete heart block, a slower distal pacemaker takes over, resulting in a ventricular escape rhythm of approximately 30–40 beats per minute.","kind":"clinical","origin":"ai"},{"id":"pacemaker-conduction-system~ai-4","moduleId":"pacemaker-conduction-system","stem":"Which mechanism explains the effect of vagal stimulation on heart rate?","options":[{"id":"a","text":"Increased calcium influx"},{"id":"b","text":"Decreased phase-4 slope and hyperpolarization"},{"id":"c","text":"Increased sodium influx"},{"id":"d","text":"Decreased potassium efflux"}],"answerId":"b","explanation":"Vagal stimulation decreases the phase-4 slope and causes hyperpolarization, leading to a slower heart rate.","kind":"mechanism","origin":"ai"},{"id":"pacemaker-conduction-system~ai-5","moduleId":"pacemaker-conduction-system","stem":"How does sympathetic stimulation affect the pacemaker cells in the heart?","options":[{"id":"a","text":"Decreases heart rate by increasing vagal tone"},{"id":"b","text":"Increases heart rate by increasing phase-4 slope"},{"id":"c","text":"Has no effect on heart rate"},{"id":"d","text":"Decreases conduction velocity through the AV node"}],"answerId":"b","explanation":"Sympathetic stimulation increases the phase-4 slope, leading to an increased heart rate.","kind":"mechanism","origin":"ai"},{"id":"pacemaker-conduction-system~ai-6","moduleId":"pacemaker-conduction-system","stem":"How does the cardiac conduction system relate to the function of myelinated nerve fibers?","options":[{"id":"a","text":"Both systems rely on sodium channels for action potential propagation"},{"id":"b","text":"Both systems utilize calcium channels for signal transmission"},{"id":"c","text":"Myelinated fibers enhance conduction speed in the heart"},{"id":"d","text":"Both systems involve synaptic transmission for impulse propagation"}],"answerId":"a","explanation":"Both the cardiac conduction system and myelinated nerve fibers rely on sodium channels for the rapid propagation of action potentials.","kind":"integration","linkedModuleIds":["nerve-fiber-myelin-synapse"],"origin":"ai"},{"id":"pacemaker-conduction-system~ai-7","moduleId":"pacemaker-conduction-system","stem":"What is the relationship between the AV node and bundle branch block?","options":[{"id":"a","text":"AV node block causes bundle branch block"},{"id":"b","text":"Bundle branch block affects AV node function"},{"id":"c","text":"Both conditions can lead to similar heart rates"},{"id":"d","text":"AV node delays impulse, while bundle branches conduct it"}],"answerId":"d","explanation":"The AV node delays the impulse to allow for proper ventricular filling, while bundle branches are responsible for conducting impulses to the ventricles.","kind":"integration","linkedModuleIds":["bundle-branch-block"],"origin":"ai"}],"cardiac-electrical-axis-vectors":[{"id":"cardiac-electrical-axis-vectors~ai-0","moduleId":"cardiac-electrical-axis-vectors","stem":"What does a downward QRS deflection in an ECG lead indicate?","options":[{"id":"a","text":"Depolarization moving toward the electrode"},{"id":"b","text":"Depolarization moving away from the electrode"},{"id":"c","text":"Weak electrical activity"},{"id":"d","text":"Normal electrical activity"}],"answerId":"b","explanation":"A downward QRS deflection indicates that depolarization is moving away from the positive electrode.","kind":"recall","origin":"ai"},{"id":"cardiac-electrical-axis-vectors~ai-1","moduleId":"cardiac-electrical-axis-vectors","stem":"Which condition is suggested by a left axis deviation on an ECG?","options":[{"id":"a","text":"Right ventricular hypertrophy"},{"id":"b","text":"Left ventricular hypertrophy"},{"id":"c","text":"Normal variant in tall individuals"},{"id":"d","text":"Atrial enlargement"}],"answerId":"b","explanation":"Left axis deviation typically suggests left ventricular hypertrophy or left anterior fascicular block.","kind":"recall","origin":"ai"},{"id":"cardiac-electrical-axis-vectors~ai-2","moduleId":"cardiac-electrical-axis-vectors","stem":"In which leads would you expect a normal mean electrical axis to be positive?","options":[{"id":"a","text":"Leads I and II"},{"id":"b","text":"Leads I and aVF"},{"id":"c","text":"Leads II and III"},{"id":"d","text":"Leads aVR and aVL"}],"answerId":"b","explanation":"A normal mean electrical axis is indicated by positive QRS complexes in both leads I and aVF.","kind":"recall","origin":"ai"},{"id":"cardiac-electrical-axis-vectors~ai-3","moduleId":"cardiac-electrical-axis-vectors","stem":"What does a biphasic QRS complex in a lead indicate?","options":[{"id":"a","text":"Depolarization moving toward the electrode"},{"id":"b","text":"Depolarization moving away from the electrode"},{"id":"c","text":"Vector perpendicular to that lead"},{"id":"d","text":"Normal electrical activity"}],"answerId":"c","explanation":"A biphasic QRS complex indicates that the electrical vector is perpendicular to the lead.","kind":"mechanism","origin":"ai"},{"id":"cardiac-electrical-axis-vectors~ai-4","moduleId":"cardiac-electrical-axis-vectors","stem":"A patient presents with a positive QRS complex in lead I and a negative QRS complex in lead aVF. What is the likely mean electrical axis?","options":[{"id":"a","text":"Normal"},{"id":"b","text":"Left axis deviation"},{"id":"c","text":"Right axis deviation"},{"id":"d","text":"Indeterminate"}],"answerId":"b","explanation":"Positive in lead I and negative in lead aVF indicates left axis deviation.","kind":"clinical","origin":"ai"},{"id":"cardiac-electrical-axis-vectors~ai-5","moduleId":"cardiac-electrical-axis-vectors","stem":"How does the mean electrical axis relate to ventricular hypertrophy?","options":[{"id":"a","text":"It indicates the size of the left ventricle"},{"id":"b","text":"It reflects the direction of the dominant electrical vector"},{"id":"c","text":"It measures the strength of the heart's contraction"},{"id":"d","text":"It is unrelated to ventricular size"}],"answerId":"b","explanation":"The mean electrical axis reflects the direction of the dominant electrical vector, which can be altered in conditions like ventricular hypertrophy.","kind":"integration","linkedModuleIds":["ecg-systematic-interpretation"],"origin":"ai"},{"id":"cardiac-electrical-axis-vectors~ai-6","moduleId":"cardiac-electrical-axis-vectors","stem":"Which of the following best explains the relationship between the electrical axis and the ECG leads?","options":[{"id":"a","text":"The axis is determined by the heart's size"},{"id":"b","text":"The axis reflects the average direction of electrical activity in the heart"},{"id":"c","text":"The axis is irrelevant to ECG interpretation"},{"id":"d","text":"The axis only applies to lead II"}],"answerId":"b","explanation":"The electrical axis reflects the average direction of electrical activity during ventricular depolarization as viewed from the limb leads.","kind":"integration","linkedModuleIds":["ecg-leads-axis"],"origin":"ai"}],"frank-starling-cardiac-function":[{"id":"frank-starling-cardiac-function~ai-0","moduleId":"frank-starling-cardiac-function","stem":"What does the Frank–Starling mechanism primarily describe?","options":[{"id":"a","text":"The effect of preload on stroke volume"},{"id":"b","text":"The role of sympathetic stimulation in heart rate"},{"id":"c","text":"The influence of afterload on cardiac output"},{"id":"d","text":"The relationship between heart rate and contractility"}],"answerId":"a","explanation":"The Frank–Starling mechanism states that increased preload leads to increased stroke volume due to enhanced myocardial stretch.","kind":"recall","origin":"ai"},{"id":"frank-starling-cardiac-function~ai-1","moduleId":"frank-starling-cardiac-function","stem":"In heart failure, what is the expected change in the Starling curve?","options":[{"id":"a","text":"It shifts up and left"},{"id":"b","text":"It shifts down and right"},{"id":"c","text":"It remains unchanged"},{"id":"d","text":"It becomes steeper"}],"answerId":"b","explanation":"In heart failure, the Starling curve shifts down and right, indicating reduced contractility and requiring higher preload for adequate stroke volume.","kind":"mechanism","origin":"ai"},{"id":"frank-starling-cardiac-function~ai-2","moduleId":"frank-starling-cardiac-function","stem":"How does increased venous return affect the left ventricle according to the Frank–Starling mechanism?","options":[{"id":"a","text":"It decreases contractility"},{"id":"b","text":"It increases stroke volume"},{"id":"c","text":"It reduces end-diastolic volume"},{"id":"d","text":"It causes pulmonary congestion"}],"answerId":"b","explanation":"Increased venous return stretches the left ventricle, leading to increased stroke volume due to the Frank–Starling mechanism.","kind":"clinical","origin":"ai"},{"id":"frank-starling-cardiac-function~ai-3","moduleId":"frank-starling-cardiac-function","stem":"Which statement correctly differentiates preload from contractility?","options":[{"id":"a","text":"Both increase stroke volume in the same manner"},{"id":"b","text":"Preload shifts the Starling curve, contractility does not"},{"id":"c","text":"Preload moves along the existing curve, contractility shifts the curve"},{"id":"d","text":"Contractility is independent of preload"}],"answerId":"c","explanation":"Increasing preload moves the heart along its existing Starling curve, while increasing contractility shifts the entire curve upward.","kind":"trap","origin":"ai"},{"id":"frank-starling-cardiac-function~ai-4","moduleId":"frank-starling-cardiac-function","stem":"What is the consequence of a poorly contractile ventricle in heart failure?","options":[{"id":"a","text":"Increased stroke volume with low preload"},{"id":"b","text":"Decreased venous return"},{"id":"c","text":"High filling pressure needed for adequate output"},{"id":"d","text":"Equal outputs from both ventricles"}],"answerId":"c","explanation":"A poorly contractile ventricle requires high filling pressure to achieve adequate output, leading to congestion.","kind":"clinical","origin":"ai"},{"id":"frank-starling-cardiac-function~ai-5","moduleId":"frank-starling-cardiac-function","stem":"How does the Frank–Starling mechanism relate to systemic and pulmonary circulation?","options":[{"id":"a","text":"It ensures equal outputs from both ventricles"},{"id":"b","text":"It increases systemic vascular resistance"},{"id":"c","text":"It decreases pulmonary capillary pressure"},{"id":"d","text":"It alters blood flow distribution"}],"answerId":"a","explanation":"The Frank–Starling mechanism maintains equal outputs from the right and left ventricles, crucial for balanced circulation.","kind":"integration","linkedModuleIds":["systemic-pulmonary-circulation"],"origin":"ai"},{"id":"frank-starling-cardiac-function~ai-6","moduleId":"frank-starling-cardiac-function","stem":"In the context of hemodynamics, how does preload affect cardiac output?","options":[{"id":"a","text":"It shifts the entire Starling curve"},{"id":"b","text":"It moves along the existing Starling curve"},{"id":"c","text":"It has no effect on stroke volume"},{"id":"d","text":"It decreases contractility"}],"answerId":"b","explanation":"Preload affects cardiac output by moving along the existing Starling curve, increasing stroke volume with greater filling.","kind":"integration","linkedModuleIds":["hemodynamics-preload-afterload-cardiac-output"],"origin":"ai"}],"blood-pressure-measurement-abpm":[{"id":"blood-pressure-measurement-abpm~ai-0","moduleId":"blood-pressure-measurement-abpm","stem":"What is the first Korotkoff sound indicative of during blood pressure measurement?","options":[{"id":"a","text":"Diastolic blood pressure"},{"id":"b","text":"Systolic blood pressure"},{"id":"c","text":"Mean arterial pressure"},{"id":"d","text":"Pulse pressure"}],"answerId":"b","explanation":"The first Korotkoff sound marks the systolic blood pressure as the cuff deflates.","kind":"recall","origin":"ai"},{"id":"blood-pressure-measurement-abpm~ai-1","moduleId":"blood-pressure-measurement-abpm","stem":"Which of the following is a characteristic of masked hypertension?","options":[{"id":"a","text":"High blood pressure in the clinic"},{"id":"b","text":"Normal blood pressure in the clinic"},{"id":"c","text":"Consistently high readings at home"},{"id":"d","text":"Nocturnal dipping of blood pressure"}],"answerId":"b","explanation":"Masked hypertension is characterized by normal blood pressure readings in the clinic but elevated readings outside.","kind":"recall","origin":"ai"},{"id":"blood-pressure-measurement-abpm~ai-2","moduleId":"blood-pressure-measurement-abpm","stem":"What is the primary risk associated with masked hypertension?","options":[{"id":"a","text":"Over-treatment due to false high readings"},{"id":"b","text":"Missed cardiovascular risk despite normal clinic readings"},{"id":"c","text":"Inaccurate home blood pressure measurements"},{"id":"d","text":"Increased nocturnal blood pressure dipping"}],"answerId":"b","explanation":"Masked hypertension carries real cardiovascular risk that is often missed due to normal clinic readings.","kind":"trap","origin":"ai"},{"id":"blood-pressure-measurement-abpm~ai-3","moduleId":"blood-pressure-measurement-abpm","stem":"Which factor can lead to a falsely high blood pressure reading?","options":[{"id":"a","text":"Cuff too large for arm circumference"},{"id":"b","text":"Patient seated with back unsupported"},{"id":"c","text":"Cuff too small for arm circumference"},{"id":"d","text":"Arm positioned below heart level"}],"answerId":"c","explanation":"Using a cuff that is too small for the arm circumference can result in a falsely elevated blood pressure reading.","kind":"mechanism","origin":"ai"},{"id":"blood-pressure-measurement-abpm~ai-4","moduleId":"blood-pressure-measurement-abpm","stem":"What is the significance of nocturnal blood pressure dipping in patients?","options":[{"id":"a","text":"Indicates normal blood pressure control"},{"id":"b","text":"Associated with lower cardiovascular risk"},{"id":"c","text":"Suggests non-dipper status and higher cardiovascular risk"},{"id":"d","text":"Confirms white-coat hypertension diagnosis"}],"answerId":"c","explanation":"Non-dippers, who have less than 10% nocturnal blood pressure fall, are at higher cardiovascular risk.","kind":"clinical","origin":"ai"},{"id":"blood-pressure-measurement-abpm~ai-5","moduleId":"blood-pressure-measurement-abpm","stem":"How does ambulatory blood pressure monitoring (ABPM) improve hypertension diagnosis?","options":[{"id":"a","text":"By averaging clinic readings"},{"id":"b","text":"By providing 24-hour blood pressure data"},{"id":"c","text":"By eliminating the need for home monitoring"},{"id":"d","text":"By confirming white-coat hypertension"}],"answerId":"b","explanation":"ABPM provides comprehensive 24-hour blood pressure data, capturing variations that clinic measurements may miss.","kind":"integration","linkedModuleIds":["htn-classification"],"origin":"ai"},{"id":"blood-pressure-measurement-abpm~ai-6","moduleId":"blood-pressure-measurement-abpm","stem":"Which mechanism is primarily responsible for blood pressure regulation during acute stress?","options":[{"id":"a","text":"Renin-angiotensin-aldosterone system"},{"id":"b","text":"Baroreceptor reflex"},{"id":"c","text":"Sympathetic nervous system activation"},{"id":"d","text":"Vasopressin release"}],"answerId":"b","explanation":"The baroreceptor reflex rapidly adjusts blood pressure in response to changes in blood volume and pressure.","kind":"integration","linkedModuleIds":["blood-pressure-baroreceptor-reflex"],"origin":"ai"}],"blood-pressure-baroreceptor-reflex":[{"id":"blood-pressure-baroreceptor-reflex~ai-0","moduleId":"blood-pressure-baroreceptor-reflex","stem":"What is the primary mechanism by which the baroreceptor reflex lowers blood pressure?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Decreased parasympathetic activity"},{"id":"c","text":"Increased vasodilation"},{"id":"d","text":"Decreased stroke volume"}],"answerId":"c","explanation":"The baroreceptor reflex responds to increased blood pressure by increasing parasympathetic activity and causing vasodilation, which lowers blood pressure.","kind":"mechanism","origin":"ai"},{"id":"blood-pressure-baroreceptor-reflex~ai-1","moduleId":"blood-pressure-baroreceptor-reflex","stem":"Which of the following conditions is most likely to cause a widened pulse pressure?","options":[{"id":"a","text":"Aortic stenosis"},{"id":"b","text":"Hypovolemic shock"},{"id":"c","text":"Aortic regurgitation"},{"id":"d","text":"Cardiac tamponade"}],"answerId":"c","explanation":"Aortic regurgitation leads to increased stroke volume and a widened pulse pressure due to the backflow of blood into the left ventricle.","kind":"clinical","origin":"ai"},{"id":"blood-pressure-baroreceptor-reflex~ai-2","moduleId":"blood-pressure-baroreceptor-reflex","stem":"What happens to baroreceptor firing when blood pressure decreases?","options":[{"id":"a","text":"Increased firing leads to decreased heart rate"},{"id":"b","text":"Decreased firing leads to increased sympathetic activity"},{"id":"c","text":"Increased firing leads to vasodilation"},{"id":"d","text":"Decreased firing leads to increased vagal tone"}],"answerId":"b","explanation":"A decrease in blood pressure results in decreased baroreceptor firing, which increases sympathetic activity to restore blood pressure.","kind":"trap","origin":"ai"},{"id":"blood-pressure-baroreceptor-reflex~ai-3","moduleId":"blood-pressure-baroreceptor-reflex","stem":"Which of the following best describes the relationship between cardiac output and total peripheral resistance in blood pressure regulation?","options":[{"id":"a","text":"Cardiac output is independent of total peripheral resistance"},{"id":"b","text":"Increased cardiac output always raises blood pressure"},{"id":"c","text":"Total peripheral resistance does not affect blood pressure"},{"id":"d","text":"Decreased total peripheral resistance lowers blood pressure"}],"answerId":"d","explanation":"Decreased total peripheral resistance leads to lower blood pressure, as blood pressure is determined by the product of cardiac output and total peripheral resistance.","kind":"recall","origin":"ai"},{"id":"blood-pressure-baroreceptor-reflex~ai-4","moduleId":"blood-pressure-baroreceptor-reflex","stem":"What is the expected cardiovascular response to standing up quickly?","options":[{"id":"a","text":"Increased baroreceptor firing and bradycardia"},{"id":"b","text":"Decreased sympathetic activity and vasodilation"},{"id":"c","text":"Decreased baroreceptor firing and tachycardia"},{"id":"d","text":"Increased vagal tone and hypotension"}],"answerId":"c","explanation":"Standing up quickly decreases baroreceptor firing, leading to increased sympathetic activity and tachycardia to counteract the drop in blood pressure.","kind":"clinical","origin":"ai"},{"id":"blood-pressure-baroreceptor-reflex~ai-5","moduleId":"blood-pressure-baroreceptor-reflex","stem":"How does the baroreceptor reflex interact with the RAAS system in long-term blood pressure control?","options":[{"id":"a","text":"Baroreceptors directly activate RAAS"},{"id":"b","text":"RAAS inhibits baroreceptor activity"},{"id":"c","text":"Baroreceptors provide short-term feedback to RAAS"},{"id":"d","text":"RAAS has no effect on baroreceptor function"}],"answerId":"c","explanation":"The baroreceptor reflex provides short-term feedback that can influence the RAAS system's long-term regulation of blood pressure.","kind":"integration","linkedModuleIds":["long-term-bp-raas"],"origin":"ai"},{"id":"blood-pressure-baroreceptor-reflex~ai-6","moduleId":"blood-pressure-baroreceptor-reflex","stem":"Which finding is associated with a Cushing reflex due to increased intracranial pressure?","options":[{"id":"a","text":"Tachycardia and hypertension"},{"id":"b","text":"Bradycardia and hypertension"},{"id":"c","text":"Hypotension and tachycardia"},{"id":"d","text":"Bradycardia and hypotension"}],"answerId":"b","explanation":"The Cushing reflex is characterized by hypertension and bradycardia as a response to critically low brain perfusion.","kind":"clinical","origin":"ai"}],"chest-xray-cardiac":[{"id":"chest-xray-cardiac~ai-0","moduleId":"chest-xray-cardiac","stem":"What is the normal range for the cardiothoracic ratio (CTR) on a PA chest X-ray?","options":[{"id":"a","text":"< 0.5"},{"id":"b","text":"< 0.6"},{"id":"c","text":"< 0.4"},{"id":"d","text":"< 0.7"}],"answerId":"a","explanation":"A normal CTR is defined as less than 0.5, indicating no cardiomegaly.","kind":"recall","origin":"ai"},{"id":"chest-xray-cardiac~ai-1","moduleId":"chest-xray-cardiac","stem":"Which finding on a chest X-ray indicates left atrial enlargement?","options":[{"id":"a","text":"Displaced apex"},{"id":"b","text":"Double density behind the heart"},{"id":"c","text":"Kerley B lines"},{"id":"d","text":"Boot-shaped heart"}],"answerId":"b","explanation":"A double density behind the heart suggests left atrial enlargement.","kind":"recall","origin":"ai"},{"id":"chest-xray-cardiac~ai-2","moduleId":"chest-xray-cardiac","stem":"What does a boot-shaped heart on a chest X-ray suggest?","options":[{"id":"a","text":"Cardiomegaly"},{"id":"b","text":"Pulmonary edema"},{"id":"c","text":"Tetralogy of Fallot"},{"id":"d","text":"Left atrial enlargement"}],"answerId":"c","explanation":"A boot-shaped heart is characteristic of Tetralogy of Fallot.","kind":"recall","origin":"ai"},{"id":"chest-xray-cardiac~ai-3","moduleId":"chest-xray-cardiac","stem":"Why is the cardiothoracic ratio (CTR) unreliable on an AP chest X-ray?","options":[{"id":"a","text":"It measures the heart size inaccurately"},{"id":"b","text":"It magnifies the heart"},{"id":"c","text":"It does not show the thoracic width"},{"id":"d","text":"It is not standardized"}],"answerId":"b","explanation":"An AP film magnifies the heart, leading to a falsely elevated CTR.","kind":"trap","origin":"ai"},{"id":"chest-xray-cardiac~ai-4","moduleId":"chest-xray-cardiac","stem":"In left heart failure, which chest X-ray finding is typically observed?","options":[{"id":"a","text":"Upper-lobe vessel diversion"},{"id":"b","text":"Boot-shaped heart"},{"id":"c","text":"Displaced apex"},{"id":"d","text":"Double density"}],"answerId":"a","explanation":"Upper-lobe vessel diversion is a sign of pulmonary venous congestion due to left heart failure.","kind":"recall","origin":"ai"},{"id":"chest-xray-cardiac~ai-5","moduleId":"chest-xray-cardiac","stem":"How does the examination of a chest X-ray integrate with echocardiography?","options":[{"id":"a","text":"Both assess electrical activity"},{"id":"b","text":"Both provide detailed anatomical structure"},{"id":"c","text":"CXR shows consequences while echo shows structure/function"},{"id":"d","text":"Both are equally detailed"}],"answerId":"c","explanation":"CXR provides an overview of consequences like cardiomegaly, while echo details structure and function.","kind":"integration","linkedModuleIds":["echocardiography-basics"],"origin":"ai"},{"id":"chest-xray-cardiac~ai-6","moduleId":"chest-xray-cardiac","stem":"Which chest X-ray finding would suggest a need for an ECG evaluation?","options":[{"id":"a","text":"Kerley B lines"},{"id":"b","text":"Double density"},{"id":"c","text":"Displaced apex"},{"id":"d","text":"Boot-shaped heart"}],"answerId":"c","explanation":"A displaced apex indicates possible left ventricular enlargement, which may require ECG for further evaluation.","kind":"integration","linkedModuleIds":["ecg-systematic-interpretation"],"origin":"ai"}],"cardiac-biomarkers-acs":[{"id":"cardiac-biomarkers-acs~ai-0","moduleId":"cardiac-biomarkers-acs","stem":"What is the primary cardiac biomarker used to diagnose myocardial infarction?","options":[{"id":"a","text":"Creatine kinase (CK-MB)"},{"id":"b","text":"Myoglobin"},{"id":"c","text":"Cardiac troponin"},{"id":"d","text":"B-type natriuretic peptide (BNP)"}],"answerId":"c","explanation":"Cardiac troponin is the gold standard for diagnosing myocardial infarction due to its high sensitivity and specificity.","kind":"recall","origin":"ai"},{"id":"cardiac-biomarkers-acs~ai-1","moduleId":"cardiac-biomarkers-acs","stem":"How long after myocardial injury does cardiac troponin typically begin to rise?","options":[{"id":"a","text":"1 hour"},{"id":"b","text":"3-4 hours"},{"id":"c","text":"12 hours"},{"id":"d","text":"24 hours"}],"answerId":"b","explanation":"Cardiac troponin levels typically rise 3-4 hours after myocardial injury.","kind":"recall","origin":"ai"},{"id":"cardiac-biomarkers-acs~ai-2","moduleId":"cardiac-biomarkers-acs","stem":"Which of the following findings indicates a re-infarction in a patient with previously elevated troponin?","options":[{"id":"a","text":"New rise in CK-MB"},{"id":"b","text":"Stable troponin levels"},{"id":"c","text":"Decreased troponin levels"},{"id":"d","text":"New rise in BNP"}],"answerId":"a","explanation":"A new rise in CK-MB after troponin is already elevated suggests re-infarction, as CK-MB clears faster than troponin.","kind":"recall","origin":"ai"},{"id":"cardiac-biomarkers-acs~ai-3","moduleId":"cardiac-biomarkers-acs","stem":"What does a rise and fall pattern of troponin levels indicate?","options":[{"id":"a","text":"Chronic myocardial injury"},{"id":"b","text":"Acute myocardial injury"},{"id":"c","text":"Stable angina"},{"id":"d","text":"Heart failure"}],"answerId":"b","explanation":"A rise and fall pattern of troponin levels indicates acute myocardial injury, distinguishing it from chronic elevation.","kind":"clinical","origin":"ai"},{"id":"cardiac-biomarkers-acs~ai-4","moduleId":"cardiac-biomarkers-acs","stem":"Which condition can cause elevated troponin levels but is not classified as acute coronary syndrome?","options":[{"id":"a","text":"Acute myocardial infarction"},{"id":"b","text":"Pulmonary embolism"},{"id":"c","text":"Stable angina"},{"id":"d","text":"Unstable angina"}],"answerId":"b","explanation":"Troponin can be elevated in pulmonary embolism, which is not classified as acute coronary syndrome.","kind":"trap","origin":"ai"},{"id":"cardiac-biomarkers-acs~ai-5","moduleId":"cardiac-biomarkers-acs","stem":"In which scenario would you expect elevated BNP levels?","options":[{"id":"a","text":"Acute myocardial infarction"},{"id":"b","text":"Heart failure"},{"id":"c","text":"Pulmonary embolism"},{"id":"d","text":"Stable angina"}],"answerId":"b","explanation":"BNP is released by stretched ventricles and serves as a marker for heart failure.","kind":"recall","origin":"ai"},{"id":"cardiac-biomarkers-acs~ai-6","moduleId":"cardiac-biomarkers-acs","stem":"How does the interpretation of troponin levels integrate with ECG findings in diagnosing myocardial infarction?","options":[{"id":"a","text":"Troponin is diagnostic alone"},{"id":"b","text":"ECG findings confirm troponin elevation"},{"id":"c","text":"Both must be considered together"},{"id":"d","text":"ECG is more important than troponin"}],"answerId":"c","explanation":"Both troponin levels and ECG findings must be considered together to diagnose myocardial infarction accurately.","kind":"integration","linkedModuleIds":["ecg-systematic-interpretation"],"origin":"ai"},{"id":"cardiac-biomarkers-acs~ai-7","moduleId":"cardiac-biomarkers-acs","stem":"What is the relationship between cardiac biomarkers and enzyme kinetics in the context of myocardial injury?","options":[{"id":"a","text":"All biomarkers rise at the same rate"},{"id":"b","text":"Troponin rises faster than CK-MB"},{"id":"c","text":"CK-MB clears faster than troponin"},{"id":"d","text":"Enzyme kinetics are unrelated to biomarkers"}],"answerId":"c","explanation":"CK-MB clears faster than troponin, which is important for understanding the timing of myocardial injury and re-infarction.","kind":"integration","linkedModuleIds":["enzyme-kinetics"],"origin":"ai"}],"jugular-venous-pressure-waveform":[{"id":"jugular-venous-pressure-waveform~ai-0","moduleId":"jugular-venous-pressure-waveform","stem":"What does a raised jugular venous pressure (JVP) typically indicate?","options":[{"id":"a","text":"Right heart failure"},{"id":"b","text":"Left heart failure"},{"id":"c","text":"Aortic stenosis"},{"id":"d","text":"Mitral regurgitation"}],"answerId":"a","explanation":"A raised JVP indicates elevated right atrial pressure, commonly seen in right heart failure.","kind":"recall","origin":"ai"},{"id":"jugular-venous-pressure-waveform~ai-1","moduleId":"jugular-venous-pressure-waveform","stem":"Which wave in the JVP waveform corresponds to atrial contraction?","options":[{"id":"a","text":"a wave"},{"id":"b","text":"c wave"},{"id":"c","text":"v wave"},{"id":"d","text":"y descent"}],"answerId":"a","explanation":"The a wave in the JVP waveform represents atrial contraction.","kind":"recall","origin":"ai"},{"id":"jugular-venous-pressure-waveform~ai-2","moduleId":"jugular-venous-pressure-waveform","stem":"In which condition would you expect to see giant 'cannon' a waves in the JVP?","options":[{"id":"a","text":"Atrial fibrillation"},{"id":"b","text":"Complete heart block"},{"id":"c","text":"Tricuspid regurgitation"},{"id":"d","text":"Pulmonary hypertension"}],"answerId":"b","explanation":"Giant 'cannon' a waves occur in complete heart block, where the atrium contracts against a closed tricuspid valve.","kind":"recall","origin":"ai"},{"id":"jugular-venous-pressure-waveform~ai-3","moduleId":"jugular-venous-pressure-waveform","stem":"What does the Kussmaul sign indicate when observed in a patient?","options":[{"id":"a","text":"Right heart failure"},{"id":"b","text":"Constrictive pericarditis"},{"id":"c","text":"Atrial fibrillation"},{"id":"d","text":"Tricuspid regurgitation"}],"answerId":"b","explanation":"The Kussmaul sign indicates impaired right-heart filling, often seen in constrictive pericarditis.","kind":"recall","origin":"ai"},{"id":"jugular-venous-pressure-waveform~ai-4","moduleId":"jugular-venous-pressure-waveform","stem":"How can you distinguish the jugular venous pulsation from the carotid pulse?","options":[{"id":"a","text":"JVP is palpable, carotid is not"},{"id":"b","text":"JVP is biphasic, carotid is not"},{"id":"c","text":"JVP is constant, carotid varies with position"},{"id":"d","text":"JVP is affected by abdominal pressure, carotid is not"}],"answerId":"b","explanation":"The JVP is a venous pulsation that is biphasic and varies with respiration and position, unlike the carotid pulse.","kind":"trap","origin":"ai"},{"id":"jugular-venous-pressure-waveform~ai-5","moduleId":"jugular-venous-pressure-waveform","stem":"Which of the following findings would suggest tricuspid regurgitation?","options":[{"id":"a","text":"Absent a wave"},{"id":"b","text":"Large v waves"},{"id":"c","text":"Giant a waves"},{"id":"d","text":"Kussmaul sign"}],"answerId":"b","explanation":"Large v waves in the JVP indicate tricuspid regurgitation due to systolic backflow into the atrium.","kind":"clinical","origin":"ai"},{"id":"jugular-venous-pressure-waveform~ai-6","moduleId":"jugular-venous-pressure-waveform","stem":"How does the JVP relate to the cardiac cycle?","options":[{"id":"a","text":"It reflects left atrial pressure"},{"id":"b","text":"It mirrors right-heart filling events"},{"id":"c","text":"It is independent of the cardiac cycle"},{"id":"d","text":"It indicates systemic vascular resistance"}],"answerId":"b","explanation":"The JVP reflects right atrial pressure and mirrors events in the cardiac cycle, such as atrial contraction and relaxation.","kind":"integration","linkedModuleIds":["cardiac-cycle-heart-sounds"],"origin":"ai"},{"id":"jugular-venous-pressure-waveform~ai-7","moduleId":"jugular-venous-pressure-waveform","stem":"What is the significance of measuring JVP in relation to preload?","options":[{"id":"a","text":"It indicates left ventricular preload"},{"id":"b","text":"It reflects right atrial pressure as a measure of right heart preload"},{"id":"c","text":"It is unrelated to preload assessment"},{"id":"d","text":"It measures systemic vascular resistance"}],"answerId":"b","explanation":"JVP reflects right atrial pressure, which is an important indicator of right heart preload.","kind":"integration","linkedModuleIds":["hemodynamics-preload-afterload-cardiac-output"],"origin":"ai"}],"echocardiography-basics":[{"id":"echocardiography-basics~ai-0","moduleId":"echocardiography-basics","stem":"What is the primary purpose of echocardiography in cardiac assessment?","options":[{"id":"a","text":"To measure blood pressure"},{"id":"b","text":"To image the heart in real time"},{"id":"c","text":"To perform cardiac catheterization"},{"id":"d","text":"To assess lung function"}],"answerId":"b","explanation":"Echocardiography uses ultrasound to provide real-time imaging of the heart, allowing assessment of structure and function.","kind":"recall","origin":"ai"},{"id":"echocardiography-basics~ai-1","moduleId":"echocardiography-basics","stem":"Which echocardiographic view is best for assessing the left atrium and mitral valve?","options":[{"id":"a","text":"Parasternal long-axis"},{"id":"b","text":"Apical 4-chamber"},{"id":"c","text":"Subcostal"},{"id":"d","text":"Parasternal short-axis"}],"answerId":"b","explanation":"The apical 4-chamber view provides a clear view of the left atrium and mitral valve.","kind":"recall","origin":"ai"},{"id":"echocardiography-basics~ai-2","moduleId":"echocardiography-basics","stem":"What does a high-velocity Doppler jet across a valve indicate?","options":[{"id":"a","text":"Normal valve function"},{"id":"b","text":"Valvular regurgitation"},{"id":"c","text":"Valvular stenosis"},{"id":"d","text":"Myocardial infarction"}],"answerId":"c","explanation":"A high-velocity jet across a valve suggests the presence of valvular stenosis due to increased pressure gradient.","kind":"mechanism","origin":"ai"},{"id":"echocardiography-basics~ai-3","moduleId":"echocardiography-basics","stem":"A patient presents with heart failure symptoms but has a normal ejection fraction. What type of heart failure is this likely to be?","options":[{"id":"a","text":"Systolic heart failure"},{"id":"b","text":"Diastolic heart failure"},{"id":"c","text":"Valvular heart disease"},{"id":"d","text":"Myocardial infarction"}],"answerId":"b","explanation":"This presentation is consistent with heart failure with preserved ejection fraction (HFpEF), indicating a diastolic filling problem.","kind":"clinical","origin":"ai"},{"id":"echocardiography-basics~ai-4","moduleId":"echocardiography-basics","stem":"Which of the following statements about ejection fraction is true?","options":[{"id":"a","text":"A normal ejection fraction rules out heart failure"},{"id":"b","text":"Ejection fraction measures diastolic function"},{"id":"c","text":"A reduced ejection fraction indicates systolic dysfunction"},{"id":"d","text":"Ejection fraction is only relevant in valvular disease"}],"answerId":"c","explanation":"A reduced ejection fraction (<40%) indicates systolic dysfunction (HFrEF), while a normal EF does not exclude heart failure.","kind":"trap","origin":"ai"},{"id":"echocardiography-basics~ai-5","moduleId":"echocardiography-basics","stem":"How does echocardiography relate to the assessment of cardiac output?","options":[{"id":"a","text":"It directly measures cardiac output"},{"id":"b","text":"It assesses heart structure and function affecting cardiac output"},{"id":"c","text":"It replaces the need for cardiac output measurements"},{"id":"d","text":"It is unrelated to cardiac output assessment"}],"answerId":"b","explanation":"Echocardiography evaluates heart structure and function, which are critical for understanding cardiac output dynamics.","kind":"integration","linkedModuleIds":["hemodynamics-preload-afterload-cardiac-output"],"origin":"ai"},{"id":"echocardiography-basics~ai-6","moduleId":"echocardiography-basics","stem":"In which scenario would transoesophageal echocardiography (TEE) be preferred over transthoracic echocardiography (TTE)?","options":[{"id":"a","text":"Assessing pericardial effusion"},{"id":"b","text":"Evaluating left atrial thrombus"},{"id":"c","text":"Measuring ejection fraction"},{"id":"d","text":"Examining right ventricle function"}],"answerId":"b","explanation":"TEE provides closer views of the left atrium, making it superior for evaluating potential thrombus.","kind":"clinical","origin":"ai"},{"id":"echocardiography-basics~ai-7","moduleId":"echocardiography-basics","stem":"Which echocardiographic finding is indicative of cardiac tamponade?","options":[{"id":"a","text":"Reduced ejection fraction"},{"id":"b","text":"Diastolic right ventricular collapse"},{"id":"c","text":"High-velocity Doppler jet"},{"id":"d","text":"Regional wall-motion abnormality"}],"answerId":"b","explanation":"Diastolic collapse of the right ventricle on echocardiography is a classic sign of cardiac tamponade.","kind":"recall","origin":"ai"}],"ecg-systematic-interpretation":[{"id":"ecg-systematic-interpretation~ai-0","moduleId":"ecg-systematic-interpretation","stem":"What is the normal heart rate range in adults?","options":[{"id":"a","text":"40-60 bpm"},{"id":"b","text":"60-100 bpm"},{"id":"c","text":"100-120 bpm"},{"id":"d","text":"120-140 bpm"}],"answerId":"b","explanation":"The normal resting heart rate for adults is typically between 60 and 100 beats per minute.","kind":"recall","origin":"ai"},{"id":"ecg-systematic-interpretation~ai-1","moduleId":"ecg-systematic-interpretation","stem":"Which ECG finding is indicative of acute myocardial infarction?","options":[{"id":"a","text":"Peaked T waves"},{"id":"b","text":"Pathological Q waves"},{"id":"c","text":"Long QT interval"},{"id":"d","text":"Narrow QRS complex"}],"answerId":"b","explanation":"Pathological Q waves are indicative of an old myocardial infarction, while ST-segment elevation indicates acute injury.","kind":"recall","origin":"ai"},{"id":"ecg-systematic-interpretation~ai-2","moduleId":"ecg-systematic-interpretation","stem":"What does a progressively lengthening PR interval followed by a dropped beat suggest?","options":[{"id":"a","text":"Mobitz I (Wenckebach) AV block"},{"id":"b","text":"Mobitz II AV block"},{"id":"c","text":"Complete heart block"},{"id":"d","text":"Normal variant"}],"answerId":"a","explanation":"A progressively lengthening PR interval followed by a dropped beat is characteristic of Mobitz I (Wenckebach) AV block.","kind":"mechanism","origin":"ai"},{"id":"ecg-systematic-interpretation~ai-3","moduleId":"ecg-systematic-interpretation","stem":"Which of the following ECG changes is associated with hyperkalaemia?","options":[{"id":"a","text":"Wide QRS complex"},{"id":"b","text":"Prolonged QT interval"},{"id":"c","text":"ST segment depression"},{"id":"d","text":"U waves"}],"answerId":"a","explanation":"Hyperkalaemia typically presents with peaked T waves and can progress to a wide QRS complex.","kind":"recall","origin":"ai"},{"id":"ecg-systematic-interpretation~ai-4","moduleId":"ecg-systematic-interpretation","stem":"In the context of ECG interpretation, why is clinical correlation important?","options":[{"id":"a","text":"ECGs are definitive without context"},{"id":"b","text":"ECGs can be misinterpreted without symptoms"},{"id":"c","text":"ECGs are always abnormal in disease"},{"id":"d","text":"ECGs are only relevant in young patients"}],"answerId":"b","explanation":"ECG findings must be interpreted in conjunction with clinical context to avoid misdiagnosis, as the same tracing can indicate different conditions.","kind":"trap","origin":"ai"},{"id":"ecg-systematic-interpretation~ai-5","moduleId":"ecg-systematic-interpretation","stem":"A patient presents with an irregularly irregular rhythm and no discernible P waves. What is the most likely diagnosis?","options":[{"id":"a","text":"Atrial flutter"},{"id":"b","text":"Atrial fibrillation"},{"id":"c","text":"Sinus tachycardia"},{"id":"d","text":"Ventricular tachycardia"}],"answerId":"b","explanation":"An irregularly irregular rhythm with no P waves is characteristic of atrial fibrillation.","kind":"clinical","origin":"ai"},{"id":"ecg-systematic-interpretation~ai-6","moduleId":"ecg-systematic-interpretation","stem":"How does the cardiac electrical axis relate to ECG interpretation?","options":[{"id":"a","text":"It determines heart rate"},{"id":"b","text":"It helps localize myocardial infarction"},{"id":"c","text":"It indicates the presence of arrhythmias"},{"id":"d","text":"It is irrelevant to ECG findings"}],"answerId":"b","explanation":"Understanding the cardiac electrical axis aids in localizing myocardial infarction on the ECG.","kind":"integration","linkedModuleIds":["ecg-leads-axis"],"origin":"ai"},{"id":"ecg-systematic-interpretation~ai-7","moduleId":"ecg-systematic-interpretation","stem":"What is the significance of troponin levels in relation to ECG findings?","options":[{"id":"a","text":"They are unrelated"},{"id":"b","text":"They confirm arrhythmias"},{"id":"c","text":"They correlate with myocardial injury"},{"id":"d","text":"They indicate heart rate"}],"answerId":"c","explanation":"Troponin levels correlate with myocardial injury and help confirm the diagnosis when interpreting ECG changes.","kind":"integration","linkedModuleIds":["cardiac-biomarkers-acs"],"origin":"ai"}],"cardiac-cycle-heart-sounds":[{"id":"cardiac-cycle-heart-sounds~ai-0","moduleId":"cardiac-cycle-heart-sounds","stem":"What does the S1 heart sound represent?","options":[{"id":"a","text":"Closure of the aortic valve"},{"id":"b","text":"Closure of the mitral and tricuspid valves"},{"id":"c","text":"Rapid ventricular filling"},{"id":"d","text":"Atrial contraction"}],"answerId":"b","explanation":"S1 is produced by the closure of the mitral and tricuspid (AV) valves at the start of systole.","kind":"recall","origin":"ai"},{"id":"cardiac-cycle-heart-sounds~ai-1","moduleId":"cardiac-cycle-heart-sounds","stem":"During which phase of the cardiac cycle does isovolumetric contraction occur?","options":[{"id":"a","text":"Atrial systole"},{"id":"b","text":"Ventricular systole"},{"id":"c","text":"Ventricular diastole"},{"id":"d","text":"Atrial diastole"}],"answerId":"b","explanation":"Isovolumetric contraction occurs during ventricular systole when all valves are closed and pressure is rising.","kind":"mechanism","origin":"ai"},{"id":"cardiac-cycle-heart-sounds~ai-2","moduleId":"cardiac-cycle-heart-sounds","stem":"Which heart sound is associated with rapid ventricular filling?","options":[{"id":"a","text":"S1"},{"id":"b","text":"S2"},{"id":"c","text":"S3"},{"id":"d","text":"S4"}],"answerId":"c","explanation":"S3 is associated with rapid ventricular filling and can indicate volume overload or heart failure.","kind":"recall","origin":"ai"},{"id":"cardiac-cycle-heart-sounds~ai-3","moduleId":"cardiac-cycle-heart-sounds","stem":"What is the physiological significance of S2 splitting during inspiration?","options":[{"id":"a","text":"Increased left ventricular pressure"},{"id":"b","text":"Decreased right ventricular pressure"},{"id":"c","text":"Delayed closure of the pulmonary valve"},{"id":"d","text":"Closure of the mitral valve"}],"answerId":"c","explanation":"S2 splitting during inspiration is due to delayed closure of the pulmonary valve as more blood returns to the right heart.","kind":"clinical","origin":"ai"},{"id":"cardiac-cycle-heart-sounds~ai-4","moduleId":"cardiac-cycle-heart-sounds","stem":"Which of the following statements about heart sounds is incorrect?","options":[{"id":"a","text":"S1 is the closure of the AV valves."},{"id":"b","text":"S2 occurs at the start of diastole."},{"id":"c","text":"S3 is always abnormal."},{"id":"d","text":"S2 is the closure of the semilunar valves."}],"answerId":"c","explanation":"S3 can be normal in youth or athletes; it is not always abnormal.","kind":"trap","origin":"ai"},{"id":"cardiac-cycle-heart-sounds~ai-5","moduleId":"cardiac-cycle-heart-sounds","stem":"How does increased preload affect cardiac output, according to the Frank-Starling mechanism?","options":[{"id":"a","text":"Decreases cardiac output"},{"id":"b","text":"Increases cardiac output"},{"id":"c","text":"Has no effect on cardiac output"},{"id":"d","text":"Causes arrhythmias"}],"answerId":"b","explanation":"Increased preload enhances myocardial stretch, leading to increased cardiac output as per the Frank-Starling mechanism.","kind":"integration","linkedModuleIds":["frank-starling-cardiac-function"],"origin":"ai"},{"id":"cardiac-cycle-heart-sounds~ai-6","moduleId":"cardiac-cycle-heart-sounds","stem":"What is the relationship between heart sounds and hemodynamics during the cardiac cycle?","options":[{"id":"a","text":"Heart sounds occur during diastole only"},{"id":"b","text":"S1 indicates increased ventricular pressure"},{"id":"c","text":"S2 is associated with atrial contraction"},{"id":"d","text":"S3 indicates decreased preload"}],"answerId":"b","explanation":"S1 indicates the start of systole when ventricular pressure exceeds atrial pressure, causing AV valve closure.","kind":"integration","linkedModuleIds":["hemodynamics-preload-afterload-cardiac-output"],"origin":"ai"}],"long-term-bp-raas":[{"id":"long-term-bp-raas~ai-0","moduleId":"long-term-bp-raas","stem":"What is the primary action of angiotensin II in the regulation of blood pressure?","options":[{"id":"a","text":"Increases renal blood flow"},{"id":"b","text":"Stimulates aldosterone secretion"},{"id":"c","text":"Promotes natriuresis"},{"id":"d","text":"Decreases heart rate"}],"answerId":"b","explanation":"Angiotensin II primarily stimulates aldosterone secretion, leading to increased sodium and water retention, which raises blood pressure.","kind":"recall","origin":"ai"},{"id":"long-term-bp-raas~ai-1","moduleId":"long-term-bp-raas","stem":"Which hormone is responsible for promoting water reabsorption in the kidneys?","options":[{"id":"a","text":"Aldosterone"},{"id":"b","text":"Natriuretic peptide"},{"id":"c","text":"Angiotensin II"},{"id":"d","text":"ADH"}],"answerId":"d","explanation":"ADH (vasopressin) promotes water reabsorption in the collecting ducts of the kidneys.","kind":"recall","origin":"ai"},{"id":"long-term-bp-raas~ai-2","moduleId":"long-term-bp-raas","stem":"What is the mechanism of action of ACE inhibitors in hypertension management?","options":[{"id":"a","text":"Block aldosterone secretion"},{"id":"b","text":"Inhibit angiotensin II formation"},{"id":"c","text":"Increase renal blood flow"},{"id":"d","text":"Enhance natriuresis"}],"answerId":"b","explanation":"ACE inhibitors work by inhibiting the conversion of angiotensin I to angiotensin II, thereby reducing blood pressure.","kind":"mechanism","origin":"ai"},{"id":"long-term-bp-raas~ai-3","moduleId":"long-term-bp-raas","stem":"A patient presents with low blood pressure and low sodium levels. Which hormone would you expect to be elevated?","options":[{"id":"a","text":"Aldosterone"},{"id":"b","text":"Natriuretic peptide"},{"id":"c","text":"ADH"},{"id":"d","text":"Angiotensin II"}],"answerId":"d","explanation":"Low blood pressure and low sodium levels stimulate the release of renin, leading to increased angiotensin II levels.","kind":"clinical","origin":"ai"},{"id":"long-term-bp-raas~ai-4","moduleId":"long-term-bp-raas","stem":"Which statement correctly describes the role of the baroreceptor reflex in blood pressure regulation?","options":[{"id":"a","text":"It regulates long-term blood pressure."},{"id":"b","text":"It adapts to sustained changes in blood pressure."},{"id":"c","text":"It is the primary mechanism for blood volume control."},{"id":"d","text":"It is responsible for immediate blood pressure changes."}],"answerId":"d","explanation":"The baroreceptor reflex is responsible for immediate changes in blood pressure but does not control long-term regulation.","kind":"trap","origin":"ai"},{"id":"long-term-bp-raas~ai-5","moduleId":"long-term-bp-raas","stem":"How does ANP counteract the effects of RAAS?","options":[{"id":"a","text":"Increases aldosterone secretion"},{"id":"b","text":"Promotes natriuresis and vasodilation"},{"id":"c","text":"Stimulates ADH release"},{"id":"d","text":"Enhances sodium reabsorption"}],"answerId":"b","explanation":"ANP promotes natriuresis and vasodilation, counteracting the effects of the RAAS, which increases blood volume and pressure.","kind":"mechanism","origin":"ai"},{"id":"long-term-bp-raas~ai-6","moduleId":"long-term-bp-raas","stem":"How does the RAAS system relate to glycogen metabolism during stress?","options":[{"id":"a","text":"RAAS increases glycogen synthesis"},{"id":"b","text":"RAAS enhances glycogen breakdown"},{"id":"c","text":"RAAS has no effect on glycogen metabolism"},{"id":"d","text":"RAAS promotes insulin release"}],"answerId":"b","explanation":"During stress, RAAS enhances glycogen breakdown to provide glucose for energy, linking blood pressure regulation to metabolic responses.","kind":"integration","linkedModuleIds":["glycogen-synthesis-breakdown"],"origin":"ai"},{"id":"long-term-bp-raas~ai-7","moduleId":"long-term-bp-raas","stem":"What is the relationship between the baroreceptor reflex and long-term blood pressure control?","options":[{"id":"a","text":"Baroreceptors are the main regulators of long-term BP."},{"id":"b","text":"Baroreceptors reset and do not influence long-term BP."},{"id":"c","text":"Baroreceptors directly affect renal function."},{"id":"d","text":"Baroreceptors stimulate aldosterone release."}],"answerId":"b","explanation":"The baroreceptor reflex is primarily a short-term regulator that resets over time, while long-term blood pressure control is managed by the kidneys and RAAS.","kind":"integration","linkedModuleIds":["blood-pressure-baroreceptor-reflex"],"origin":"ai"}],"ecg-chamber-enlargement":[{"id":"ecg-chamber-enlargement~ai-0","moduleId":"ecg-chamber-enlargement","stem":"What ECG finding is characteristic of right atrial enlargement?","options":[{"id":"a","text":"Tall, peaked P wave in lead II"},{"id":"b","text":"Broad, notched P wave in lead II"},{"id":"c","text":"Deep terminal negativity in V1"},{"id":"d","text":"Tall R wave in V5"}],"answerId":"a","explanation":"A tall, peaked P wave in lead II indicates right atrial enlargement, also known as P pulmonale.","kind":"recall","origin":"ai"},{"id":"ecg-chamber-enlargement~ai-1","moduleId":"ecg-chamber-enlargement","stem":"Which of the following is a common voltage criterion for left ventricular hypertrophy?","options":[{"id":"a","text":"R in V1 + S in V5 > 35 mm"},{"id":"b","text":"S in V1 + R in V5 > 35 mm"},{"id":"c","text":"R in V1 + R in V5 > 25 mm"},{"id":"d","text":"S in V1 + S in V5 > 30 mm"}],"answerId":"b","explanation":"The Sokolow–Lyon criterion states that S in V1 + R in V5/V6 > 35 mm indicates left ventricular hypertrophy.","kind":"recall","origin":"ai"},{"id":"ecg-chamber-enlargement~ai-2","moduleId":"ecg-chamber-enlargement","stem":"What is the mechanism behind the tall R waves seen in left ventricular hypertrophy?","options":[{"id":"a","text":"Increased muscle mass generates a larger vector"},{"id":"b","text":"Decreased conduction velocity in the ventricles"},{"id":"c","text":"Increased heart rate affects depolarization"},{"id":"d","text":"Altered electrical axis due to right ventricular strain"}],"answerId":"a","explanation":"Increased muscle mass in the ventricles generates a larger electrical vector, resulting in taller R waves.","kind":"mechanism","origin":"ai"},{"id":"ecg-chamber-enlargement~ai-3","moduleId":"ecg-chamber-enlargement","stem":"A patient presents with right axis deviation and a dominant R wave in V1. What condition is most likely?","options":[{"id":"a","text":"Left atrial enlargement"},{"id":"b","text":"Right ventricular hypertrophy"},{"id":"c","text":"Left ventricular hypertrophy"},{"id":"d","text":"Atrial fibrillation"}],"answerId":"b","explanation":"Right axis deviation and a dominant R wave in V1 are indicative of right ventricular hypertrophy.","kind":"clinical","origin":"ai"},{"id":"ecg-chamber-enlargement~ai-4","moduleId":"ecg-chamber-enlargement","stem":"Which of the following statements about ECG voltage criteria for hypertrophy is true?","options":[{"id":"a","text":"They are definitive for diagnosing hypertrophy"},{"id":"b","text":"They can be falsely positive or negative"},{"id":"c","text":"They are always reliable regardless of patient factors"},{"id":"d","text":"They should replace echocardiography for diagnosis"}],"answerId":"b","explanation":"ECG voltage criteria are supportive but not definitive and can be falsely positive or negative due to various factors.","kind":"trap","origin":"ai"},{"id":"ecg-chamber-enlargement~ai-5","moduleId":"ecg-chamber-enlargement","stem":"How does left atrial enlargement affect the P wave morphology on an ECG?","options":[{"id":"a","text":"Tall and peaked P wave"},{"id":"b","text":"Broad and notched P wave"},{"id":"c","text":"Deep terminal negative deflection in V1"},{"id":"d","text":"Shortened P wave duration"}],"answerId":"b","explanation":"Left atrial enlargement results in a broad, notched (bifid) P wave in lead II.","kind":"recall","origin":"ai"},{"id":"ecg-chamber-enlargement~ai-6","moduleId":"ecg-chamber-enlargement","stem":"How does understanding cardiac electrical axis vectors aid in interpreting ECG changes in hypertrophy?","options":[{"id":"a","text":"It shows the relationship between heart rate and hypertrophy"},{"id":"b","text":"It explains the direction of electrical activity in hypertrophy"},{"id":"c","text":"It provides a definitive diagnosis of hypertrophy"},{"id":"d","text":"It eliminates the need for echocardiography"}],"answerId":"b","explanation":"Understanding cardiac electrical axis vectors helps explain how hypertrophy alters the direction of electrical activity on the ECG.","kind":"integration","linkedModuleIds":["cardiac-electrical-axis-vectors"],"origin":"ai"},{"id":"ecg-chamber-enlargement~ai-7","moduleId":"ecg-chamber-enlargement","stem":"What cellular adaptation is primarily responsible for the changes seen in left ventricular hypertrophy?","options":[{"id":"a","text":"Hyperplasia"},{"id":"b","text":"Atrophy"},{"id":"c","text":"Hypertrophy"},{"id":"d","text":"Metaplasia"}],"answerId":"c","explanation":"Hypertrophy is the cellular adaptation that leads to increased muscle mass in the left ventricle, resulting in ECG changes.","kind":"integration","linkedModuleIds":["cellular-adaptations-growth"],"origin":"ai"}],"hemodynamics-preload-afterload-cardiac-output":[{"id":"hemodynamics-preload-afterload-cardiac-output~ai-0","moduleId":"hemodynamics-preload-afterload-cardiac-output","stem":"What is the primary determinant of preload in the heart?","options":[{"id":"a","text":"End-systolic volume"},{"id":"b","text":"End-diastolic volume"},{"id":"c","text":"Aortic pressure"},{"id":"d","text":"Ventricular contractility"}],"answerId":"b","explanation":"Preload is defined as the degree of ventricular stretch at end-diastole, which is closely related to end-diastolic volume.","kind":"recall","origin":"ai"},{"id":"hemodynamics-preload-afterload-cardiac-output~ai-1","moduleId":"hemodynamics-preload-afterload-cardiac-output","stem":"In a patient with aortic stenosis, what is the expected effect on stroke volume?","options":[{"id":"a","text":"Increased stroke volume"},{"id":"b","text":"Decreased stroke volume"},{"id":"c","text":"No change in stroke volume"},{"id":"d","text":"Increased heart rate"}],"answerId":"b","explanation":"Aortic stenosis increases afterload, making it harder for the ventricle to eject blood, thus reducing stroke volume.","kind":"clinical","origin":"ai"},{"id":"hemodynamics-preload-afterload-cardiac-output~ai-2","moduleId":"hemodynamics-preload-afterload-cardiac-output","stem":"Which mechanism explains the increase in stroke volume with increased venous return?","options":[{"id":"a","text":"Increased contractility"},{"id":"b","text":"Decreased afterload"},{"id":"c","text":"Frank-Starling mechanism"},{"id":"d","text":"Decreased heart rate"}],"answerId":"c","explanation":"The Frank-Starling mechanism states that increased preload (due to increased venous return) leads to a more forceful contraction and increased stroke volume.","kind":"mechanism","origin":"ai"},{"id":"hemodynamics-preload-afterload-cardiac-output~ai-3","moduleId":"hemodynamics-preload-afterload-cardiac-output","stem":"What is the relationship between vessel radius and resistance according to Poiseuille's law?","options":[{"id":"a","text":"Resistance is directly proportional to radius"},{"id":"b","text":"Resistance is inversely proportional to radius"},{"id":"c","text":"Resistance is proportional to radius squared"},{"id":"d","text":"Resistance is inversely proportional to radius to the fourth power"}],"answerId":"d","explanation":"According to Poiseuille's law, resistance is inversely proportional to the fourth power of the radius (1/r⁴).","kind":"recall","origin":"ai"},{"id":"hemodynamics-preload-afterload-cardiac-output~ai-4","moduleId":"hemodynamics-preload-afterload-cardiac-output","stem":"In which condition would you expect increased contractility due to sympathetic stimulation?","options":[{"id":"a","text":"Heart failure"},{"id":"b","text":"Hypoxia"},{"id":"c","text":"Digoxin administration"},{"id":"d","text":"Beta-blocker use"}],"answerId":"c","explanation":"Digoxin is a positive inotrope that increases contractility, while heart failure and beta-blockers decrease it.","kind":"trap","origin":"ai"},{"id":"hemodynamics-preload-afterload-cardiac-output~ai-5","moduleId":"hemodynamics-preload-afterload-cardiac-output","stem":"How does increased afterload affect cardiac output?","options":[{"id":"a","text":"Increases cardiac output"},{"id":"b","text":"Decreases cardiac output"},{"id":"c","text":"No effect on cardiac output"},{"id":"d","text":"Increases heart rate only"}],"answerId":"b","explanation":"Increased afterload makes it harder for the ventricle to eject blood, leading to decreased stroke volume and thus decreased cardiac output.","kind":"mechanism","origin":"ai"},{"id":"hemodynamics-preload-afterload-cardiac-output~ai-6","moduleId":"hemodynamics-preload-afterload-cardiac-output","stem":"How does the Frank-Starling mechanism relate to cardiac output in heart failure? (linked to frank-starling-cardiac-function)","options":[{"id":"a","text":"Increased preload compensates for decreased contractility"},{"id":"b","text":"Decreased preload leads to increased stroke volume"},{"id":"c","text":"Increased afterload improves cardiac output"},{"id":"d","text":"Contractility is unaffected by preload changes"}],"answerId":"a","explanation":"In heart failure, the Frank-Starling mechanism indicates that increased preload can help compensate for decreased contractility, improving cardiac output to some extent.","kind":"integration","linkedModuleIds":["frank-starling-cardiac-function"],"origin":"ai"},{"id":"hemodynamics-preload-afterload-cardiac-output~ai-7","moduleId":"hemodynamics-preload-afterload-cardiac-output","stem":"What is the expected effect of beta-blockers on cardiac output? (linked to beta-blockers-ccb-angina)","options":[{"id":"a","text":"Increase cardiac output by reducing heart rate"},{"id":"b","text":"Decrease cardiac output by reducing contractility"},{"id":"c","text":"No effect on cardiac output"},{"id":"d","text":"Increase stroke volume without affecting heart rate"}],"answerId":"b","explanation":"Beta-blockers decrease contractility and heart rate, which typically leads to a decrease in cardiac output.","kind":"integration","linkedModuleIds":["beta-blockers-ccb-angina"],"origin":"ai"}],"lower-urinary-tract-histology":[{"id":"lower-urinary-tract-histology~ai-0","moduleId":"lower-urinary-tract-histology","stem":"What type of epithelium lines the urinary passages?","options":[{"id":"a","text":"Simple squamous epithelium"},{"id":"b","text":"Transitional epithelium"},{"id":"c","text":"Stratified cuboidal epithelium"},{"id":"d","text":"Pseudostratified columnar epithelium"}],"answerId":"b","explanation":"The urinary passages are lined by transitional epithelium, which is specialized for stretching.","kind":"recall","origin":"ai"},{"id":"lower-urinary-tract-histology~ai-1","moduleId":"lower-urinary-tract-histology","stem":"What is the primary function of the umbrella cells in the urothelium?","options":[{"id":"a","text":"Facilitate gas exchange"},{"id":"b","text":"Provide a waterproof barrier"},{"id":"c","text":"Aid in nutrient absorption"},{"id":"d","text":"Support structural integrity"}],"answerId":"b","explanation":"Umbrella cells provide a waterproof barrier, preventing urine from penetrating the epithelium.","kind":"mechanism","origin":"ai"},{"id":"lower-urinary-tract-histology~ai-2","moduleId":"lower-urinary-tract-histology","stem":"Which muscle layer arrangement is characteristic of the ureter?","options":[{"id":"a","text":"Inner circular, outer longitudinal"},{"id":"b","text":"Inner longitudinal, outer circular"},{"id":"c","text":"Single layer of smooth muscle"},{"id":"d","text":"Three layers of smooth muscle"}],"answerId":"b","explanation":"The ureter has an inner longitudinal and outer circular muscle layer, which is the reverse of the gut.","kind":"recall","origin":"ai"},{"id":"lower-urinary-tract-histology~ai-3","moduleId":"lower-urinary-tract-histology","stem":"What finding is expected in the bladder trigone?","options":[{"id":"a","text":"Rugated surface"},{"id":"b","text":"Smooth-walled appearance"},{"id":"c","text":"Transitional epithelium"},{"id":"d","text":"Stratified squamous epithelium"}],"answerId":"b","explanation":"The bladder trigone has a smooth-walled appearance due to its distinct embryological origin.","kind":"recall","origin":"ai"},{"id":"lower-urinary-tract-histology~ai-4","moduleId":"lower-urinary-tract-histology","stem":"A patient presents with a distended bladder. What is the expected appearance of the urothelium?","options":[{"id":"a","text":"Thicker with rounded cells"},{"id":"b","text":"Thinner with flattened cells"},{"id":"c","text":"Uniform thickness throughout"},{"id":"d","text":"Atrophic with fewer than 2 layers"}],"answerId":"b","explanation":"When the bladder is distended, the urothelium appears thinner with flattened umbrella cells.","kind":"trap","origin":"ai"},{"id":"lower-urinary-tract-histology~ai-5","moduleId":"lower-urinary-tract-histology","stem":"How does the micturition reflex relate to the detrusor muscle?","options":[{"id":"a","text":"Inhibits detrusor contraction"},{"id":"b","text":"Stimulates detrusor contraction"},{"id":"c","text":"Relaxes detrusor muscle"},{"id":"d","text":"Has no effect on detrusor muscle"}],"answerId":"b","explanation":"The micturition reflex stimulates the detrusor muscle to contract, facilitating bladder emptying.","kind":"integration","linkedModuleIds":["micturition-reflex"],"origin":"ai"},{"id":"lower-urinary-tract-histology~ai-6","moduleId":"lower-urinary-tract-histology","stem":"Which structure's histology is essential for understanding bladder function?","options":[{"id":"a","text":"Proximal urethra"},{"id":"b","text":"Ureter"},{"id":"c","text":"Detrusor muscle"},{"id":"d","text":"Umbrella cells"}],"answerId":"c","explanation":"The detrusor muscle's histology is crucial for understanding bladder contraction and function.","kind":"integration","linkedModuleIds":["bladder-urethra"],"origin":"ai"}],"heart-sounds-murmurs-auscultation":[{"id":"heart-sounds-murmurs-auscultation~ai-0","moduleId":"heart-sounds-murmurs-auscultation","stem":"What heart sound is produced by the closure of the mitral and tricuspid valves?","options":[{"id":"a","text":"S1"},{"id":"b","text":"S2"},{"id":"c","text":"S3"},{"id":"d","text":"S4"}],"answerId":"a","explanation":"S1, or the 'lub' sound, is produced by the closure of the mitral and tricuspid valves at the beginning of systole.","kind":"recall","origin":"ai"},{"id":"heart-sounds-murmurs-auscultation~ai-1","moduleId":"heart-sounds-murmurs-auscultation","stem":"Which murmur is characterized by a pansystolic sound radiating to the axilla?","options":[{"id":"a","text":"Aortic stenosis"},{"id":"b","text":"Mitral regurgitation"},{"id":"c","text":"Aortic regurgitation"},{"id":"d","text":"Mitral stenosis"}],"answerId":"b","explanation":"Mitral regurgitation produces a pansystolic murmur that typically radiates to the axilla.","kind":"recall","origin":"ai"},{"id":"heart-sounds-murmurs-auscultation~ai-2","moduleId":"heart-sounds-murmurs-auscultation","stem":"What maneuver would make a murmur of hypertrophic obstructive cardiomyopathy (HOCM) louder?","options":[{"id":"a","text":"Squatting"},{"id":"b","text":"Standing"},{"id":"c","text":"Handgrip"},{"id":"d","text":"Valsalva"}],"answerId":"b","explanation":"Standing decreases preload, which makes the murmur of HOCM louder due to increased outflow obstruction.","kind":"trap","origin":"ai"},{"id":"heart-sounds-murmurs-auscultation~ai-3","moduleId":"heart-sounds-murmurs-auscultation","stem":"Which finding is associated with aortic regurgitation?","options":[{"id":"a","text":"Pansystolic murmur"},{"id":"b","text":"Early diastolic decrescendo murmur"},{"id":"c","text":"Systolic ejection murmur"},{"id":"d","text":"Atrial gallop"}],"answerId":"b","explanation":"Aortic regurgitation is characterized by an early diastolic decrescendo murmur, best heard when the patient sits forward.","kind":"recall","origin":"ai"},{"id":"heart-sounds-murmurs-auscultation~ai-4","moduleId":"heart-sounds-murmurs-auscultation","stem":"During inspiration, what happens to the splitting of S2?","options":[{"id":"a","text":"It becomes wider"},{"id":"b","text":"It becomes fixed"},{"id":"c","text":"It disappears"},{"id":"d","text":"It becomes paradoxical"}],"answerId":"a","explanation":"S2 normally splits wider on inspiration due to increased venous return delaying pulmonary valve closure.","kind":"recall","origin":"ai"},{"id":"heart-sounds-murmurs-auscultation~ai-5","moduleId":"heart-sounds-murmurs-auscultation","stem":"How does increased preload affect most heart murmurs?","options":[{"id":"a","text":"Makes them quieter"},{"id":"b","text":"Makes them louder"},{"id":"c","text":"Has no effect"},{"id":"d","text":"Makes them disappear"}],"answerId":"b","explanation":"Increasing preload generally makes most murmurs louder due to increased blood flow.","kind":"mechanism","origin":"ai"},{"id":"heart-sounds-murmurs-auscultation~ai-6","moduleId":"heart-sounds-murmurs-auscultation","stem":"In a patient with mitral valve prolapse, which maneuver would likely increase the intensity of the murmur?","options":[{"id":"a","text":"Squatting"},{"id":"b","text":"Standing"},{"id":"c","text":"Handgrip"},{"id":"d","text":"Expiration"}],"answerId":"b","explanation":"Standing decreases preload, which increases the intensity of the murmur associated with mitral valve prolapse.","kind":"integration","linkedModuleIds":["mitral-valve-prolapse"],"origin":"ai"},{"id":"heart-sounds-murmurs-auscultation~ai-7","moduleId":"heart-sounds-murmurs-auscultation","stem":"Which heart sound is typically associated with heart failure due to volume overload?","options":[{"id":"a","text":"S1"},{"id":"b","text":"S2"},{"id":"c","text":"S3"},{"id":"d","text":"S4"}],"answerId":"c","explanation":"S3 is often referred to as a 'ventricular gallop' and can indicate heart failure or volume overload in adults.","kind":"integration","linkedModuleIds":["hfpef-diastolic"],"origin":"ai"}],"glomerular-filtration-gfr":[{"id":"glomerular-filtration-gfr~ai-0","moduleId":"glomerular-filtration-gfr","stem":"What is the approximate normal glomerular filtration rate (GFR) in a healthy adult?","options":[{"id":"a","text":"125 mL/min"},{"id":"b","text":"180 mL/min"},{"id":"c","text":"90 mL/min"},{"id":"d","text":"150 mL/min"}],"answerId":"a","explanation":"The normal GFR is approximately 125 mL/min, which is the best index of overall kidney function.","kind":"recall","origin":"ai"},{"id":"glomerular-filtration-gfr~ai-1","moduleId":"glomerular-filtration-gfr","stem":"Which factor primarily drives glomerular filtration?","options":[{"id":"a","text":"Oncotic pressure"},{"id":"b","text":"Hydrostatic pressure"},{"id":"c","text":"Colloid osmotic pressure"},{"id":"d","text":"Interstitial fluid pressure"}],"answerId":"b","explanation":"Glomerular filtration is primarily driven by hydrostatic pressure in the glomerular capillaries.","kind":"mechanism","origin":"ai"},{"id":"glomerular-filtration-gfr~ai-2","moduleId":"glomerular-filtration-gfr","stem":"What effect does constriction of the efferent arteriole have on GFR?","options":[{"id":"a","text":"Decreases GFR"},{"id":"b","text":"Increases GFR"},{"id":"c","text":"No effect on GFR"},{"id":"d","text":"Increases renal plasma flow"}],"answerId":"b","explanation":"Constriction of the efferent arteriole raises glomerular capillary pressure, thereby increasing GFR.","kind":"trap","origin":"ai"},{"id":"glomerular-filtration-gfr~ai-3","moduleId":"glomerular-filtration-gfr","stem":"A patient presents with rising serum creatinine levels. What does this indicate about their GFR?","options":[{"id":"a","text":"GFR is increasing"},{"id":"b","text":"GFR is stable"},{"id":"c","text":"GFR is decreasing"},{"id":"d","text":"GFR is normal"}],"answerId":"c","explanation":"Rising serum creatinine levels indicate a decrease in GFR, as creatinine clearance approximates GFR.","kind":"clinical","origin":"ai"},{"id":"glomerular-filtration-gfr~ai-4","moduleId":"glomerular-filtration-gfr","stem":"What is the filtration fraction in a healthy individual?","options":[{"id":"a","text":"0.1"},{"id":"b","text":"0.2"},{"id":"c","text":"0.5"},{"id":"d","text":"0.3"}],"answerId":"b","explanation":"The filtration fraction is approximately 0.2, meaning about 20% of the plasma entering the glomerulus is filtered.","kind":"recall","origin":"ai"},{"id":"glomerular-filtration-gfr~ai-5","moduleId":"glomerular-filtration-gfr","stem":"How does renal blood flow regulation relate to GFR?","options":[{"id":"a","text":"Increased renal blood flow always increases GFR"},{"id":"b","text":"Decreased renal blood flow always decreases GFR"},{"id":"c","text":"GFR is independent of renal blood flow"},{"id":"d","text":"GFR can be maintained despite decreased renal blood flow"}],"answerId":"d","explanation":"GFR can be maintained despite decreased renal blood flow due to autoregulation mechanisms in the kidney.","kind":"integration","linkedModuleIds":["renal-blood-supply-vasculature"],"origin":"ai"},{"id":"glomerular-filtration-gfr~ai-6","moduleId":"glomerular-filtration-gfr","stem":"Which substance is considered the gold standard for measuring GFR?","options":[{"id":"a","text":"Creatinine"},{"id":"b","text":"Urea"},{"id":"c","text":"Inulin"},{"id":"d","text":"PAH"}],"answerId":"c","explanation":"Inulin clearance is the gold standard for measuring GFR as it is freely filtered and neither reabsorbed nor secreted.","kind":"recall","origin":"ai"},{"id":"glomerular-filtration-gfr~ai-7","moduleId":"glomerular-filtration-gfr","stem":"How does the mechanism of GFR relate to renal clearance principles?","options":[{"id":"a","text":"GFR is unrelated to clearance"},{"id":"b","text":"Clearance is a measure of renal blood flow"},{"id":"c","text":"Clearance can estimate GFR using substances like creatinine"},{"id":"d","text":"GFR is always higher than clearance values"}],"answerId":"c","explanation":"Clearance can estimate GFR using substances like creatinine, which is a practical clinical measure of kidney function.","kind":"integration","linkedModuleIds":["renal-clearance-principles"],"origin":"ai"}],"renal-clearance-principles":[{"id":"renal-clearance-principles~ai-0","moduleId":"renal-clearance-principles","stem":"What is the primary substance used to measure the glomerular filtration rate (GFR)?","options":[{"id":"a","text":"Creatinine"},{"id":"b","text":"Urea"},{"id":"c","text":"Inulin"},{"id":"d","text":"PAH"}],"answerId":"c","explanation":"Inulin is the gold standard for measuring GFR as it is freely filtered and neither reabsorbed nor secreted.","kind":"recall","origin":"ai"},{"id":"renal-clearance-principles~ai-1","moduleId":"renal-clearance-principles","stem":"What does a clearance value greater than GFR indicate?","options":[{"id":"a","text":"Net reabsorption"},{"id":"b","text":"Net secretion"},{"id":"c","text":"Complete reabsorption"},{"id":"d","text":"Normal filtration"}],"answerId":"b","explanation":"A clearance value greater than GFR indicates that the substance is being secreted in addition to being filtered.","kind":"mechanism","origin":"ai"},{"id":"renal-clearance-principles~ai-2","moduleId":"renal-clearance-principles","stem":"A patient has a creatinine clearance that slightly exceeds the true GFR. What is the most likely explanation?","options":[{"id":"a","text":"Increased tubular reabsorption"},{"id":"b","text":"Increased tubular secretion"},{"id":"c","text":"Decreased renal blood flow"},{"id":"d","text":"Normal filtration"}],"answerId":"b","explanation":"Creatinine clearance slightly overestimates GFR due to a small amount of creatinine being secreted by the renal tubules.","kind":"mechanism","origin":"ai"},{"id":"renal-clearance-principles~ai-3","moduleId":"renal-clearance-principles","stem":"Why might a normal serum creatinine level not indicate normal kidney function?","options":[{"id":"a","text":"Creatinine is always secreted"},{"id":"b","text":"GFR can be significantly reduced before creatinine rises"},{"id":"c","text":"Creatinine is only produced in the liver"},{"id":"d","text":"Normal creatinine indicates high GFR"}],"answerId":"b","explanation":"The hyperbolic relationship between creatinine and GFR means that significant reductions in GFR can occur without a rise in serum creatinine.","kind":"trap","origin":"ai"},{"id":"renal-clearance-principles~ai-4","moduleId":"renal-clearance-principles","stem":"A patient presents with a glucose clearance of zero. What does this indicate about glucose handling in the kidneys?","options":[{"id":"a","text":"Glucose is freely filtered and secreted"},{"id":"b","text":"Glucose is completely reabsorbed"},{"id":"c","text":"Glucose is not filtered"},{"id":"d","text":"Glucose clearance equals GFR"}],"answerId":"b","explanation":"A glucose clearance of zero indicates that glucose is completely reabsorbed in the renal tubules at normal plasma levels.","kind":"recall","origin":"ai"},{"id":"renal-clearance-principles~ai-5","moduleId":"renal-clearance-principles","stem":"How is renal plasma flow (RPF) estimated using PAH clearance?","options":[{"id":"a","text":"By measuring urine creatinine"},{"id":"b","text":"By measuring urine urea"},{"id":"c","text":"By measuring urine PAH"},{"id":"d","text":"By measuring serum creatinine"}],"answerId":"c","explanation":"PAH clearance approximates RPF because PAH is filtered and almost completely secreted by the renal tubules.","kind":"recall","origin":"ai"},{"id":"renal-clearance-principles~ai-6","moduleId":"renal-clearance-principles","stem":"How does understanding renal clearance principles apply to the management of chronic kidney disease (CKD)?","options":[{"id":"a","text":"It helps in estimating drug dosing"},{"id":"b","text":"It eliminates the need for imaging"},{"id":"c","text":"It guarantees normal serum creatinine"},{"id":"d","text":"It replaces the need for renal biopsy"}],"answerId":"a","explanation":"Understanding renal clearance is crucial for estimating GFR, which is essential for appropriate drug dosing in CKD management.","kind":"integration","linkedModuleIds":["chronic-kidney-disease-uremia"],"origin":"ai"},{"id":"renal-clearance-principles~ai-7","moduleId":"renal-clearance-principles","stem":"In assessing acute kidney injury, why is it important to measure renal clearance?","options":[{"id":"a","text":"To confirm the presence of diabetes"},{"id":"b","text":"To evaluate the effectiveness of diuretics"},{"id":"c","text":"To estimate the severity of kidney function decline"},{"id":"d","text":"To determine the need for dialysis"}],"answerId":"c","explanation":"Measuring renal clearance helps estimate the severity of kidney function decline, which is critical in managing acute kidney injury.","kind":"integration","linkedModuleIds":["acute-kidney-injury-azotemia"],"origin":"ai"}],"kidney-development-metanephros":[{"id":"kidney-development-metanephros~ai-0","moduleId":"kidney-development-metanephros","stem":"Which kidney structure arises from the ureteric bud?","options":[{"id":"a","text":"Nephrons"},{"id":"b","text":"Collecting ducts"},{"id":"c","text":"Glomerulus"},{"id":"d","text":"Proximal convoluted tubule"}],"answerId":"b","explanation":"The ureteric bud gives rise to the collecting system, including the collecting ducts.","kind":"recall","origin":"ai"},{"id":"kidney-development-metanephros~ai-1","moduleId":"kidney-development-metanephros","stem":"At what week does the metanephros begin producing urine?","options":[{"id":"a","text":"Week 4"},{"id":"b","text":"Week 5"},{"id":"c","text":"Week 10"},{"id":"d","text":"Week 12"}],"answerId":"c","explanation":"The metanephros starts producing urine around week 10 of development.","kind":"recall","origin":"ai"},{"id":"kidney-development-metanephros~ai-2","moduleId":"kidney-development-metanephros","stem":"What is the consequence of failure in the induction between the ureteric bud and metanephric blastema?","options":[{"id":"a","text":"Formation of accessory renal arteries"},{"id":"b","text":"Cystic or dysplastic kidneys"},{"id":"c","text":"Development of the bladder"},{"id":"d","text":"Absence of the ureter"}],"answerId":"b","explanation":"Failure of induction leads to conditions such as cystic or dysplastic kidneys due to improper formation of nephrons and collecting ducts.","kind":"mechanism","origin":"ai"},{"id":"kidney-development-metanephros~ai-3","moduleId":"kidney-development-metanephros","stem":"Which structure is derived from the metanephric blastema?","options":[{"id":"a","text":"Ureter"},{"id":"b","text":"Collecting ducts"},{"id":"c","text":"Nephrons"},{"id":"d","text":"Renal pelvis"}],"answerId":"c","explanation":"The metanephric blastema gives rise to the nephron structures, including the glomerulus and tubules.","kind":"recall","origin":"ai"},{"id":"kidney-development-metanephros~ai-4","moduleId":"kidney-development-metanephros","stem":"What is the final arterial supply to the kidneys during their ascent?","options":[{"id":"a","text":"L1-L2 renal arteries"},{"id":"b","text":"L3-L4 renal arteries"},{"id":"c","text":"Transitional arteries"},{"id":"d","text":"Iliac arteries"}],"answerId":"a","explanation":"The final renal arteries arise at the L1-L2 level as the kidneys ascend.","kind":"recall","origin":"ai"},{"id":"kidney-development-metanephros~ai-5","moduleId":"kidney-development-metanephros","stem":"How does the cloaca develop during embryogenesis?","options":[{"id":"a","text":"It forms solely from mesoderm"},{"id":"b","text":"It is partitioned by the urorectal septum"},{"id":"c","text":"It directly forms the bladder"},{"id":"d","text":"It regresses into the urachus"}],"answerId":"b","explanation":"The cloaca is partitioned by the urorectal septum into the anorectal canal and the urogenital sinus.","kind":"mechanism","origin":"ai"},{"id":"kidney-development-metanephros~ai-6","moduleId":"kidney-development-metanephros","stem":"Which of the following congenital anomalies is most directly related to improper development of the ureteric bud?","options":[{"id":"a","text":"Horseshoe kidney"},{"id":"b","text":"Multicystic dysplastic kidney"},{"id":"c","text":"Renal agenesis"},{"id":"d","text":"Polycystic kidney disease"}],"answerId":"b","explanation":"Multicystic dysplastic kidney results from improper induction between the ureteric bud and metanephric blastema.","kind":"integration","linkedModuleIds":["kub-congenital-anomalies"],"origin":"ai"},{"id":"kidney-development-metanephros~ai-7","moduleId":"kidney-development-metanephros","stem":"What embryological structure gives rise to the majority of the bladder?","options":[{"id":"a","text":"Ureteric bud"},{"id":"b","text":"Urogenital sinus"},{"id":"c","text":"Mesonephric duct"},{"id":"d","text":"Metanephric blastema"}],"answerId":"b","explanation":"The bladder primarily develops from the endodermal urogenital sinus, while the trigone derives from mesonephric ducts.","kind":"integration","linkedModuleIds":["nephron-kidney-histology"],"origin":"ai"}],"nephron-kidney-histology":[{"id":"nephron-kidney-histology~ai-0","moduleId":"nephron-kidney-histology","stem":"What is the primary function of the renal corpuscle?","options":[{"id":"a","text":"Filtration of blood"},{"id":"b","text":"Reabsorption of nutrients"},{"id":"c","text":"Secretion of hormones"},{"id":"d","text":"Concentration of urine"}],"answerId":"a","explanation":"The renal corpuscle is responsible for filtering blood to form the initial filtrate.","kind":"recall","origin":"ai"},{"id":"nephron-kidney-histology~ai-1","moduleId":"nephron-kidney-histology","stem":"Which structure is primarily responsible for the reabsorption of water and solutes in the nephron?","options":[{"id":"a","text":"Loop of Henle"},{"id":"b","text":"Proximal convoluted tubule"},{"id":"c","text":"Distal convoluted tubule"},{"id":"d","text":"Collecting duct"}],"answerId":"b","explanation":"The proximal convoluted tubule is specialized for bulk reabsorption of water and solutes.","kind":"recall","origin":"ai"},{"id":"nephron-kidney-histology~ai-2","moduleId":"nephron-kidney-histology","stem":"What histological feature distinguishes the proximal convoluted tubule from the distal convoluted tubule?","options":[{"id":"a","text":"Cuboidal cells"},{"id":"b","text":"Brush border"},{"id":"c","text":"Wide lumen"},{"id":"d","text":"More nuclei per cross-section"}],"answerId":"b","explanation":"The proximal convoluted tubule has a prominent brush border due to microvilli, which is absent in the distal convoluted tubule.","kind":"trap","origin":"ai"},{"id":"nephron-kidney-histology~ai-3","moduleId":"nephron-kidney-histology","stem":"Which component of the glomerular filtration barrier is responsible for repelling albumin?","options":[{"id":"a","text":"Fenestrated endothelium"},{"id":"b","text":"Podocyte foot processes"},{"id":"c","text":"Glomerular basement membrane"},{"id":"d","text":"Mesangial cells"}],"answerId":"c","explanation":"The glomerular basement membrane is negatively charged, which repels negatively charged proteins like albumin.","kind":"mechanism","origin":"ai"},{"id":"nephron-kidney-histology~ai-4","moduleId":"nephron-kidney-histology","stem":"What is the role of the macula densa in the juxtaglomerular apparatus?","options":[{"id":"a","text":"Regulates blood pressure"},{"id":"b","text":"Senses tubular NaCl concentration"},{"id":"c","text":"Filters blood"},{"id":"d","text":"Secretes erythropoietin"}],"answerId":"b","explanation":"The macula densa senses the NaCl concentration in the tubular fluid and helps regulate glomerular filtration rate.","kind":"mechanism","origin":"ai"},{"id":"nephron-kidney-histology~ai-5","moduleId":"nephron-kidney-histology","stem":"How does the structure of the collecting duct facilitate its function?","options":[{"id":"a","text":"Tall cells with microvilli"},{"id":"b","text":"Pale cells with distinct lateral borders"},{"id":"c","text":"Cuboidal cells with a narrow lumen"},{"id":"d","text":"Simple squamous epithelium"}],"answerId":"b","explanation":"The collecting duct has pale cells with distinct lateral borders, which help in the reabsorption of water and electrolytes.","kind":"mechanism","origin":"ai"},{"id":"nephron-kidney-histology~ai-6","moduleId":"nephron-kidney-histology","stem":"How does the nephron's structure relate to its function in glomerular filtration?","options":[{"id":"a","text":"The glomerulus filters blood, while the tubule reabsorbs nutrients"},{"id":"b","text":"The tubule secretes waste products, while the corpuscle collects urine"},{"id":"c","text":"The collecting duct concentrates urine, while the PCT filters blood"},{"id":"d","text":"The DCT regulates blood pressure, while the loop of Henle reabsorbs water"}],"answerId":"a","explanation":"The glomerulus filters blood to form filtrate, and the tubule processes this filtrate by reabsorbing nutrients and water.","kind":"integration","linkedModuleIds":["glomerular-filtration-gfr"],"origin":"ai"},{"id":"nephron-kidney-histology~ai-7","moduleId":"nephron-kidney-histology","stem":"What histological feature of the nephron is crucial for understanding its role in tubular reabsorption?","options":[{"id":"a","text":"Presence of podocytes"},{"id":"b","text":"Brush border of PCT"},{"id":"c","text":"Cuboidal cells of DCT"},{"id":"d","text":"Simple squamous epithelium of loop of Henle"}],"answerId":"b","explanation":"The brush border of the proximal convoluted tubule increases surface area for reabsorption, which is essential for its function.","kind":"integration","linkedModuleIds":["tubular-reabsorption-secretion"],"origin":"ai"}],"tubular-reabsorption-secretion":[{"id":"tubular-reabsorption-secretion~ai-0","moduleId":"tubular-reabsorption-secretion","stem":"What is the primary mechanism by which glucose is reabsorbed in the proximal convoluted tubule?","options":[{"id":"a","text":"Facilitated diffusion via GLUT transporters"},{"id":"b","text":"Secondary active transport via SGLT2"},{"id":"c","text":"Simple diffusion"},{"id":"d","text":"Paracellular transport"}],"answerId":"b","explanation":"Glucose reabsorption in the proximal convoluted tubule primarily occurs via secondary active transport through the SGLT2 transporter, which couples glucose uptake to sodium reabsorption.","kind":"mechanism","origin":"ai"},{"id":"tubular-reabsorption-secretion~ai-1","moduleId":"tubular-reabsorption-secretion","stem":"What happens to glucose excretion when plasma glucose levels exceed 200 mg/dL?","options":[{"id":"a","text":"Glucose reabsorption increases"},{"id":"b","text":"Glucose is secreted into the urine"},{"id":"c","text":"Glucosuria occurs"},{"id":"d","text":"Glucose is completely reabsorbed"}],"answerId":"c","explanation":"When plasma glucose exceeds the renal threshold (~180-200 mg/dL), the filtered glucose load surpasses the transport maximum (Tm) of SGLT2, leading to glucosuria.","kind":"recall","origin":"ai"},{"id":"tubular-reabsorption-secretion~ai-2","moduleId":"tubular-reabsorption-secretion","stem":"In a patient with Fanconi syndrome, which of the following findings is most likely?","options":[{"id":"a","text":"Increased bicarbonate reabsorption"},{"id":"b","text":"Aminoaciduria"},{"id":"c","text":"Increased calcium reabsorption"},{"id":"d","text":"Glucosuria due to renal damage"}],"answerId":"b","explanation":"Fanconi syndrome is characterized by generalized proximal tubular dysfunction, leading to aminoaciduria due to failure of proximal carriers.","kind":"recall","origin":"ai"},{"id":"tubular-reabsorption-secretion~ai-3","moduleId":"tubular-reabsorption-secretion","stem":"Which of the following best explains the mechanism of osmotic diuresis in uncontrolled diabetes?","options":[{"id":"a","text":"Increased renal blood flow"},{"id":"b","text":"Increased sodium reabsorption"},{"id":"c","text":"Unreabsorbed glucose in the lumen"},{"id":"d","text":"Decreased aquaporin expression"}],"answerId":"c","explanation":"Osmotic diuresis occurs in uncontrolled diabetes due to the presence of unreabsorbed glucose in the renal tubule, which retains water in the lumen.","kind":"mechanism","origin":"ai"},{"id":"tubular-reabsorption-secretion~ai-4","moduleId":"tubular-reabsorption-secretion","stem":"What is the effect of ouabain on renal tubular reabsorption?","options":[{"id":"a","text":"Increases sodium reabsorption"},{"id":"b","text":"Halts most reabsorption"},{"id":"c","text":"Enhances glucose reabsorption"},{"id":"d","text":"Increases bicarbonate secretion"}],"answerId":"b","explanation":"Ouabain inhibits the Na⁺/K⁺-ATPase, which is essential for powering Na⁺-coupled transport, thus halting most reabsorption processes.","kind":"trap","origin":"ai"},{"id":"tubular-reabsorption-secretion~ai-5","moduleId":"tubular-reabsorption-secretion","stem":"How does bicarbonate reabsorption in the proximal tubule relate to tubular reabsorption and secretion?","options":[{"id":"a","text":"It is independent of sodium reabsorption"},{"id":"b","text":"It is coupled with sodium reabsorption"},{"id":"c","text":"It occurs only in the collecting duct"},{"id":"d","text":"It is a passive process"}],"answerId":"b","explanation":"Bicarbonate reabsorption in the proximal tubule is coupled with sodium reabsorption, as bicarbonate is reabsorbed alongside sodium ions.","kind":"integration","linkedModuleIds":["renal-bicarbonate-reabsorption"],"origin":"ai"},{"id":"tubular-reabsorption-secretion~ai-6","moduleId":"tubular-reabsorption-secretion","stem":"Which of the following best describes the relationship between tubular reabsorption and glomerular filtration rate (GFR)?","options":[{"id":"a","text":"Increased GFR always leads to increased reabsorption"},{"id":"b","text":"Reabsorption is independent of GFR"},{"id":"c","text":"Decreased GFR leads to decreased reabsorption"},{"id":"d","text":"Reabsorption can occur regardless of GFR"}],"answerId":"c","explanation":"Decreased GFR can lead to decreased reabsorption due to reduced filtration of solutes, impacting the overall reabsorption capacity.","kind":"integration","linkedModuleIds":["glomerular-filtration-gfr"],"origin":"ai"}],"cardiovascular-examination":[{"id":"cardiovascular-examination~ai-0","moduleId":"cardiovascular-examination","stem":"What is the correct sequence for performing a cardiovascular examination?","options":[{"id":"a","text":"Auscultation → Inspection → Palpation"},{"id":"b","text":"Inspection → Palpation → Auscultation"},{"id":"c","text":"Palpation → Auscultation → Inspection"},{"id":"d","text":"Inspection → Auscultation → Palpation"}],"answerId":"b","explanation":"The correct sequence is inspection, palpation, and then auscultation.","kind":"recall","origin":"ai"},{"id":"cardiovascular-examination~ai-1","moduleId":"cardiovascular-examination","stem":"Where is the apex beat normally located?","options":[{"id":"a","text":"Right 2nd intercostal space"},{"id":"b","text":"Left 2nd intercostal space"},{"id":"c","text":"5th intercostal space, midclavicular line"},{"id":"d","text":"Left lower sternal border"}],"answerId":"c","explanation":"The apex beat is normally located at the 5th intercostal space, midclavicular line.","kind":"recall","origin":"ai"},{"id":"cardiovascular-examination~ai-2","moduleId":"cardiovascular-examination","stem":"A patient presents with a diastolic murmur. Which of the following conditions is most likely?","options":[{"id":"a","text":"Aortic stenosis"},{"id":"b","text":"Mitral regurgitation"},{"id":"c","text":"Aortic regurgitation"},{"id":"d","text":"Tricuspid regurgitation"}],"answerId":"c","explanation":"A diastolic murmur is characteristic of conditions like aortic regurgitation.","kind":"recall","origin":"ai"},{"id":"cardiovascular-examination~ai-3","moduleId":"cardiovascular-examination","stem":"During auscultation, a murmur is heard between S2 and the next S1. What type of murmur is this?","options":[{"id":"a","text":"Systolic murmur"},{"id":"b","text":"Diastolic murmur"},{"id":"c","text":"Continuous murmur"},{"id":"d","text":"Physiologic murmur"}],"answerId":"b","explanation":"A murmur heard between S2 and S1 is classified as a diastolic murmur.","kind":"trap","origin":"ai"},{"id":"cardiovascular-examination~ai-4","moduleId":"cardiovascular-examination","stem":"What finding is indicative of right heart failure during a cardiovascular examination?","options":[{"id":"a","text":"Displaced apex beat"},{"id":"b","text":"Systolic murmur"},{"id":"c","text":"Raised JVP + peripheral oedema"},{"id":"d","text":"Diastolic murmur"}],"answerId":"c","explanation":"Raised JVP and peripheral oedema are signs of right heart failure or volume overload.","kind":"clinical","origin":"ai"},{"id":"cardiovascular-examination~ai-5","moduleId":"cardiovascular-examination","stem":"How does the left-lateral position affect the auscultation of heart sounds?","options":[{"id":"a","text":"It accentuates aortic sounds"},{"id":"b","text":"It accentuates mitral sounds"},{"id":"c","text":"It diminishes all heart sounds"},{"id":"d","text":"It has no effect on heart sounds"}],"answerId":"b","explanation":"The left-lateral position accentuates the sounds of the mitral valve.","kind":"mechanism","origin":"ai"},{"id":"cardiovascular-examination~ai-6","moduleId":"cardiovascular-examination","stem":"How does the knowledge of heart anatomy (linkedModuleIds: heart-anatomy-chambers-valves) enhance the understanding of auscultation findings?","options":[{"id":"a","text":"It helps locate the apex beat"},{"id":"b","text":"It explains the timing of heart sounds"},{"id":"c","text":"It identifies valve locations for auscultation"},{"id":"d","text":"It clarifies the pathophysiology of murmurs"}],"answerId":"c","explanation":"Understanding heart anatomy helps in identifying the correct locations for auscultating different valves.","kind":"integration","linkedModuleIds":["heart-anatomy-chambers-valves"],"origin":"ai"},{"id":"cardiovascular-examination~ai-7","moduleId":"cardiovascular-examination","stem":"Why is it important to understand the cardiac cycle when interpreting heart sounds and murmurs (linkedModuleIds: heart-sounds-murmurs-auscultation)?","options":[{"id":"a","text":"To determine the patient's blood pressure"},{"id":"b","text":"To time murmurs accurately relative to S1 and S2"},{"id":"c","text":"To assess the heart rate"},{"id":"d","text":"To evaluate peripheral circulation"}],"answerId":"b","explanation":"Understanding the cardiac cycle is crucial for accurately timing murmurs relative to S1 and S2.","kind":"integration","linkedModuleIds":["heart-sounds-murmurs-auscultation"],"origin":"ai"}],"kub-congenital-anomalies":[{"id":"kub-congenital-anomalies~ai-0","moduleId":"kub-congenital-anomalies","stem":"What is the most common cause of antenatal hydronephrosis?","options":[{"id":"a","text":"Ureteropelvic junction obstruction"},{"id":"b","text":"Posterior urethral valves"},{"id":"c","text":"Renal agenesis"},{"id":"d","text":"Duplicated ureter"}],"answerId":"a","explanation":"Ureteropelvic junction obstruction is the most common cause of antenatal hydronephrosis, often detected via ultrasound.","kind":"recall","origin":"ai"},{"id":"kub-congenital-anomalies~ai-1","moduleId":"kub-congenital-anomalies","stem":"Which condition is characterized by urine leakage from the umbilicus?","options":[{"id":"a","text":"Horseshoe kidney"},{"id":"b","text":"Patent urachus"},{"id":"c","text":"Bilateral renal agenesis"},{"id":"d","text":"Multicystic dysplastic kidney"}],"answerId":"b","explanation":"Patent urachus results from failed regression of the allantois, leading to urine leakage from the umbilicus.","kind":"recall","origin":"ai"},{"id":"kub-congenital-anomalies~ai-2","moduleId":"kub-congenital-anomalies","stem":"What developmental failure leads to bilateral renal agenesis?","options":[{"id":"a","text":"Failure of ureteric bud formation"},{"id":"b","text":"Failure of renal ascent"},{"id":"c","text":"Failure of cloacal partition"},{"id":"d","text":"Failure of mesenchyme induction"}],"answerId":"a","explanation":"Bilateral renal agenesis occurs due to the failure of the ureteric bud to form or induce mesenchyme.","kind":"mechanism","origin":"ai"},{"id":"kub-congenital-anomalies~ai-3","moduleId":"kub-congenital-anomalies","stem":"A newborn presents with oligohydramnios and Potter facies. What is the underlying cause?","options":[{"id":"a","text":"Congenital lung disease"},{"id":"b","text":"Bilateral renal agenesis"},{"id":"c","text":"Ureteropelvic junction obstruction"},{"id":"d","text":"Posterior urethral valves"}],"answerId":"b","explanation":"Oligohydramnios leading to Potter facies is primarily caused by bilateral renal agenesis or severe obstruction.","kind":"trap","origin":"ai"},{"id":"kub-congenital-anomalies~ai-4","moduleId":"kub-congenital-anomalies","stem":"What sign is indicative of posterior urethral valves in a male infant?","options":[{"id":"a","text":"Bilateral hydronephrosis"},{"id":"b","text":"Urine leakage from the umbilicus"},{"id":"c","text":"Low-lying kidney"},{"id":"d","text":"Potter facies"}],"answerId":"a","explanation":"Posterior urethral valves cause outflow obstruction, leading to antenatal bilateral hydronephrosis.","kind":"recall","origin":"ai"},{"id":"kub-congenital-anomalies~ai-5","moduleId":"kub-congenital-anomalies","stem":"How does a duplicated ureter arise during kidney development?","options":[{"id":"a","text":"Premature splitting of the ureteric bud"},{"id":"b","text":"Failure of renal ascent"},{"id":"c","text":"Fusion of lower poles"},{"id":"d","text":"Obstruction at the ureteropelvic junction"}],"answerId":"a","explanation":"A duplicated ureter results from the premature splitting of the ureteric bud during development.","kind":"mechanism","origin":"ai"},{"id":"kub-congenital-anomalies~ai-6","moduleId":"kub-congenital-anomalies","stem":"Which congenital anomaly is most likely to lead to respiratory complications due to oligohydramnios?","options":[{"id":"a","text":"Multicystic dysplastic kidney"},{"id":"b","text":"Bilateral renal agenesis"},{"id":"c","text":"Horseshoe kidney"},{"id":"d","text":"Patent urachus"}],"answerId":"b","explanation":"Bilateral renal agenesis leads to oligohydramnios, which can cause respiratory complications due to lung hypoplasia.","kind":"integration","linkedModuleIds":["respiratory-congenital-anomalies"],"origin":"ai"},{"id":"kub-congenital-anomalies~ai-7","moduleId":"kub-congenital-anomalies","stem":"What is the relationship between kidney development and congenital anomalies of the urinary tract?","options":[{"id":"a","text":"Both involve genetic mutations"},{"id":"b","text":"Both are influenced by maternal health"},{"id":"c","text":"Anomalies arise from failures in developmental steps"},{"id":"d","text":"Anomalies are unrelated to kidney development"}],"answerId":"c","explanation":"Congenital anomalies of the urinary tract arise from failures in the developmental steps of the kidney and urinary tract.","kind":"integration","linkedModuleIds":["kidney-development-metanephros"],"origin":"ai"}],"renal-hemodynamics-autoregulation":[{"id":"renal-hemodynamics-autoregulation~ai-0","moduleId":"renal-hemodynamics-autoregulation","stem":"What percentage of cardiac output do the kidneys receive?","options":[{"id":"a","text":"5–10%"},{"id":"b","text":"10–15%"},{"id":"c","text":"20–25%"},{"id":"d","text":"30–35%"}],"answerId":"c","explanation":"The kidneys receive approximately 20–25% of cardiac output, which is significantly higher than their metabolic needs.","kind":"recall","origin":"ai"},{"id":"renal-hemodynamics-autoregulation~ai-1","moduleId":"renal-hemodynamics-autoregulation","stem":"Which mechanism primarily causes afferent arteriolar constriction in response to increased NaCl delivery at the macula densa?","options":[{"id":"a","text":"Myogenic response"},{"id":"b","text":"Tubuloglomerular feedback"},{"id":"c","text":"Renin release"},{"id":"d","text":"Sympathetic stimulation"}],"answerId":"b","explanation":"Tubuloglomerular feedback involves the release of adenosine in response to increased NaCl delivery, leading to afferent arteriolar constriction.","kind":"mechanism","origin":"ai"},{"id":"renal-hemodynamics-autoregulation~ai-2","moduleId":"renal-hemodynamics-autoregulation","stem":"What happens to GFR when mean arterial pressure falls below 80 mmHg?","options":[{"id":"a","text":"GFR increases"},{"id":"b","text":"GFR remains stable"},{"id":"c","text":"GFR falls"},{"id":"d","text":"GFR becomes variable"}],"answerId":"c","explanation":"Autoregulation fails below a mean arterial pressure of approximately 80 mmHg, leading to a decrease in GFR.","kind":"recall","origin":"ai"},{"id":"renal-hemodynamics-autoregulation~ai-3","moduleId":"renal-hemodynamics-autoregulation","stem":"Which of the following statements about renal autoregulation is true?","options":[{"id":"a","text":"It operates effectively below 80 mmHg"},{"id":"b","text":"It involves only the myogenic response"},{"id":"c","text":"It stabilizes GFR over a range of MAP"},{"id":"d","text":"It increases GFR during high blood pressure"}],"answerId":"c","explanation":"Renal autoregulation keeps GFR stable over a mean arterial pressure range of 80–180 mmHg.","kind":"trap","origin":"ai"},{"id":"renal-hemodynamics-autoregulation~ai-4","moduleId":"renal-hemodynamics-autoregulation","stem":"What is the primary effect of angiotensin II on the renal vasculature during low perfusion states?","options":[{"id":"a","text":"Dilates afferent arterioles"},{"id":"b","text":"Constricts efferent arterioles"},{"id":"c","text":"Dilates efferent arterioles"},{"id":"d","text":"Increases renal blood flow"}],"answerId":"b","explanation":"Angiotensin II preferentially constricts the efferent arteriole to help maintain GFR during low perfusion states.","kind":"mechanism","origin":"ai"},{"id":"renal-hemodynamics-autoregulation~ai-5","moduleId":"renal-hemodynamics-autoregulation","stem":"A patient with acute kidney injury after starting an NSAID was likely affected by the loss of which vasodilator?","options":[{"id":"a","text":"Nitric oxide"},{"id":"b","text":"Prostaglandins"},{"id":"c","text":"Adenosine"},{"id":"d","text":"Angiotensin II"}],"answerId":"b","explanation":"NSAIDs inhibit prostaglandins, which are important for maintaining afferent arteriolar dilation, leading to reduced renal blood flow.","kind":"recall","origin":"ai"},{"id":"renal-hemodynamics-autoregulation~ai-6","moduleId":"renal-hemodynamics-autoregulation","stem":"How does the renal blood flow relate to the nephron's structure and function?","options":[{"id":"a","text":"It is independent of nephron type"},{"id":"b","text":"It varies significantly with nephron location"},{"id":"c","text":"It is crucial for glomerular filtration"},{"id":"d","text":"It affects only the collecting ducts"}],"answerId":"c","explanation":"Renal blood flow is essential for glomerular filtration, which is a primary function of the nephron.","kind":"integration","linkedModuleIds":["nephron-kidney-histology"],"origin":"ai"},{"id":"renal-hemodynamics-autoregulation~ai-7","moduleId":"renal-hemodynamics-autoregulation","stem":"What is the consequence of efferent arteriole dilation in a patient with renal artery stenosis?","options":[{"id":"a","text":"Increased GFR"},{"id":"b","text":"Decreased GFR"},{"id":"c","text":"Stable GFR"},{"id":"d","text":"Increased renal blood flow"}],"answerId":"b","explanation":"Efferent dilation lowers glomerular capillary pressure (P_GC), which can significantly decrease GFR, especially in renal artery stenosis.","kind":"integration","linkedModuleIds":["acute-kidney-injury-azotemia"],"origin":"ai"}],"renal-blood-supply-vasculature":[{"id":"renal-blood-supply-vasculature~ai-0","moduleId":"renal-blood-supply-vasculature","stem":"What is the correct order of the renal arterial tree?","options":[{"id":"a","text":"Renal artery → segmental → interlobar → arcuate → interlobular → afferent arteriole → glomerulus"},{"id":"b","text":"Renal artery → interlobar → segmental → arcuate → interlobular → afferent arteriole → glomerulus"},{"id":"c","text":"Renal artery → arcuate → interlobar → segmental → interlobular → afferent arteriole → glomerulus"},{"id":"d","text":"Renal artery → interlobular → arcuate → segmental → interlobar → afferent arteriole → glomerulus"}],"answerId":"a","explanation":"The renal arterial tree follows a specific order essential for understanding renal blood supply.","kind":"recall","origin":"ai"},{"id":"renal-blood-supply-vasculature~ai-1","moduleId":"renal-blood-supply-vasculature","stem":"What is the primary function of juxtamedullary nephrons?","options":[{"id":"a","text":"Filtration of blood"},{"id":"b","text":"Regulation of blood pressure"},{"id":"c","text":"Concentration of urine"},{"id":"d","text":"Secretion of hormones"}],"answerId":"c","explanation":"Juxtamedullary nephrons have long loops of Henle that play a crucial role in urine concentration.","kind":"recall","origin":"ai"},{"id":"renal-blood-supply-vasculature~ai-2","moduleId":"renal-blood-supply-vasculature","stem":"What is the significance of the efferent arteriole in the kidney?","options":[{"id":"a","text":"It carries blood away from the kidney"},{"id":"b","text":"It drains into the renal vein"},{"id":"c","text":"It leads to a second capillary bed"},{"id":"d","text":"It is a venule that collects filtered blood"}],"answerId":"c","explanation":"The efferent arteriole exits the glomerulus and leads to a second capillary bed, which is essential for kidney function.","kind":"mechanism","origin":"ai"},{"id":"renal-blood-supply-vasculature~ai-3","moduleId":"renal-blood-supply-vasculature","stem":"Which structure is primarily responsible for the countercurrent exchange in the kidney?","options":[{"id":"a","text":"Cortical nephrons"},{"id":"b","text":"Peritubular capillaries"},{"id":"c","text":"Vasa recta"},{"id":"d","text":"Glomerulus"}],"answerId":"c","explanation":"The vasa recta are specialized capillaries that facilitate countercurrent exchange in juxtamedullary nephrons.","kind":"mechanism","origin":"ai"},{"id":"renal-blood-supply-vasculature~ai-4","moduleId":"renal-blood-supply-vasculature","stem":"A patient presents with a wedge-shaped renal infarct. What is the most likely cause?","options":[{"id":"a","text":"Occlusion of a renal vein"},{"id":"b","text":"Thrombosis of a segmental artery"},{"id":"c","text":"Ischemia due to low medullary blood flow"},{"id":"d","text":"Infarction of the glomerulus"}],"answerId":"b","explanation":"Wedge-shaped renal infarcts are typically caused by occlusion of the segmental arteries due to their end-arterial nature.","kind":"clinical","origin":"ai"},{"id":"renal-blood-supply-vasculature~ai-5","moduleId":"renal-blood-supply-vasculature","stem":"How does the kidney maintain a high glomerular filtration rate (GFR)?","options":[{"id":"a","text":"By increasing renal blood flow"},{"id":"b","text":"By constricting the efferent arteriole"},{"id":"c","text":"By dilating the afferent arteriole"},{"id":"d","text":"By decreasing peritubular capillary pressure"}],"answerId":"b","explanation":"Constriction of the efferent arteriole increases glomerular pressure, thereby maintaining a high GFR.","kind":"mechanism","origin":"ai"},{"id":"renal-blood-supply-vasculature~ai-6","moduleId":"renal-blood-supply-vasculature","stem":"How does the renal blood supply relate to glomerular filtration?","options":[{"id":"a","text":"High renal blood flow is for metabolic needs"},{"id":"b","text":"Efferent arterioles are venules"},{"id":"c","text":"Filtration occurs in the peritubular capillaries"},{"id":"d","text":"The kidney has a portal system with two capillary beds"}],"answerId":"d","explanation":"The kidney's unique portal system allows for independent regulation of filtration and reabsorption.","kind":"integration","linkedModuleIds":["glomerular-filtration-gfr"],"origin":"ai"},{"id":"renal-blood-supply-vasculature~ai-7","moduleId":"renal-blood-supply-vasculature","stem":"What is a key feature of the renal blood supply that supports nephron function?","options":[{"id":"a","text":"Cortex receives less blood than medulla"},{"id":"b","text":"Medulla is highly perfused"},{"id":"c","text":"Cortical nephrons have long loops of Henle"},{"id":"d","text":"Juxtamedullary nephrons utilize vasa recta for exchange"}],"answerId":"d","explanation":"Juxtamedullary nephrons use vasa recta to maintain the osmotic gradient necessary for urine concentration.","kind":"integration","linkedModuleIds":["renal-hemodynamics-autoregulation"],"origin":"ai"}],"urine-concentration-countercurrent":[{"id":"urine-concentration-countercurrent~ai-0","moduleId":"urine-concentration-countercurrent","stem":"What is the primary mechanism by which the loop of Henle concentrates urine?","options":[{"id":"a","text":"Active transport of urea"},{"id":"b","text":"Countercurrent multiplication"},{"id":"c","text":"Passive diffusion of water"},{"id":"d","text":"Filtration at the glomerulus"}],"answerId":"b","explanation":"The loop of Henle utilizes countercurrent multiplication to create a hypertonic medullary interstitium, allowing for urine concentration.","kind":"mechanism","origin":"ai"},{"id":"urine-concentration-countercurrent~ai-1","moduleId":"urine-concentration-countercurrent","stem":"Which segment of the nephron is responsible for diluting the tubular fluid?","options":[{"id":"a","text":"Thin descending limb"},{"id":"b","text":"Thick ascending limb"},{"id":"c","text":"Collecting duct"},{"id":"d","text":"Proximal convoluted tubule"}],"answerId":"b","explanation":"The thick ascending limb actively pumps NaCl out while being impermeable to water, resulting in hypotonic tubular fluid.","kind":"recall","origin":"ai"},{"id":"urine-concentration-countercurrent~ai-2","moduleId":"urine-concentration-countercurrent","stem":"What effect do loop diuretics have on urine concentration?","options":[{"id":"a","text":"Increase urea reabsorption"},{"id":"b","text":"Increase water reabsorption"},{"id":"c","text":"Block NKCC2 leading to diuresis"},{"id":"d","text":"Enhance medullary blood flow"}],"answerId":"c","explanation":"Loop diuretics block NKCC2 in the thick ascending limb, abolishing the medullary osmotic gradient and causing increased diuresis.","kind":"trap","origin":"ai"},{"id":"urine-concentration-countercurrent~ai-3","moduleId":"urine-concentration-countercurrent","stem":"In a patient with protein malnutrition, what is the expected effect on urine concentration ability?","options":[{"id":"a","text":"Increased concentrating ability"},{"id":"b","text":"No change in concentrating ability"},{"id":"c","text":"Reduced concentrating ability"},{"id":"d","text":"Variable concentrating ability"}],"answerId":"c","explanation":"Protein malnutrition leads to decreased urea availability, which diminishes the medullary osmotic gradient and reduces urine concentrating ability.","kind":"clinical","origin":"ai"},{"id":"urine-concentration-countercurrent~ai-4","moduleId":"urine-concentration-countercurrent","stem":"How does the vasa recta contribute to urine concentration?","options":[{"id":"a","text":"By reabsorbing urea"},{"id":"b","text":"By preventing washout of the osmotic gradient"},{"id":"c","text":"By secreting water"},{"id":"d","text":"By increasing blood flow to the medulla"}],"answerId":"b","explanation":"The vasa recta maintain the osmotic gradient through countercurrent exchange, preventing washout while supplying oxygen.","kind":"mechanism","origin":"ai"},{"id":"urine-concentration-countercurrent~ai-5","moduleId":"urine-concentration-countercurrent","stem":"How does ADH affect the collecting duct in relation to urine concentration?","options":[{"id":"a","text":"Increases NaCl reabsorption"},{"id":"b","text":"Increases water permeability"},{"id":"c","text":"Decreases urea permeability"},{"id":"d","text":"Decreases water reabsorption"}],"answerId":"b","explanation":"ADH increases the permeability of the inner-medullary collecting duct to water, allowing for greater water reabsorption and concentrated urine.","kind":"integration","linkedModuleIds":["adh-water-regulation"],"origin":"ai"},{"id":"urine-concentration-countercurrent~ai-6","moduleId":"urine-concentration-countercurrent","stem":"What is the consequence of excessive blood flow through the medulla?","options":[{"id":"a","text":"Increased urine concentration"},{"id":"b","text":"Decreased urine concentration"},{"id":"c","text":"No effect on urine concentration"},{"id":"d","text":"Increased urea recycling"}],"answerId":"b","explanation":"Excessive medullary blood flow can wash out the osmotic gradient, leading to decreased urine concentration ability.","kind":"trap","origin":"ai"},{"id":"urine-concentration-countercurrent~ai-7","moduleId":"urine-concentration-countercurrent","stem":"Which of the following best describes the osmolarity of fluid leaving the thick ascending limb?","options":[{"id":"a","text":"Isotonic (~300 mOsm/kg)"},{"id":"b","text":"Hypotonic (~100 mOsm/kg)"},{"id":"c","text":"Hypertonic (~1200 mOsm/kg)"},{"id":"d","text":"Variable depending on hydration status"}],"answerId":"b","explanation":"The thick ascending limb is the diluting segment and produces hypotonic fluid (~100 mOsm/kg) as it actively pumps out NaCl without water.","kind":"recall","origin":"ai"},{"id":"urine-concentration-countercurrent~ai-8","moduleId":"urine-concentration-countercurrent","stem":"What is the role of urea in the countercurrent mechanism?","options":[{"id":"a","text":"It is primarily reabsorbed in the proximal tubule"},{"id":"b","text":"It contributes to the osmotic gradient in the medulla"},{"id":"c","text":"It is secreted in the collecting duct"},{"id":"d","text":"It decreases urine osmolarity"}],"answerId":"b","explanation":"Urea recycling contributes significantly to the osmotic gradient in the medulla, enhancing urine concentration.","kind":"integration","linkedModuleIds":["urine-biochemical-composition"],"origin":"ai"}],"urine-biochemical-composition":[{"id":"urine-biochemical-composition~ai-0","moduleId":"urine-biochemical-composition","stem":"What is the primary nitrogenous waste product found in normal urine?","options":[{"id":"a","text":"Uric acid"},{"id":"b","text":"Creatinine"},{"id":"c","text":"Urea"},{"id":"d","text":"Ammonia"}],"answerId":"c","explanation":"Urea is the principal nitrogenous end-product of protein metabolism and is the largest solute by mass in urine.","kind":"recall","origin":"ai"},{"id":"urine-biochemical-composition~ai-1","moduleId":"urine-biochemical-composition","stem":"Which of the following substances is normally absent in urine?","options":[{"id":"a","text":"Urea"},{"id":"b","text":"Creatinine"},{"id":"c","text":"Glucose"},{"id":"d","text":"Sodium"}],"answerId":"c","explanation":"Glucose is not normally present in urine; its presence indicates glucosuria, which occurs when plasma glucose exceeds the renal threshold.","kind":"recall","origin":"ai"},{"id":"urine-biochemical-composition~ai-2","moduleId":"urine-biochemical-composition","stem":"Why is creatinine used to normalize spot urine tests?","options":[{"id":"a","text":"It is a toxic waste that must be tracked"},{"id":"b","text":"It is excreted at a fairly constant rate"},{"id":"c","text":"It is the main nitrogenous waste product"},{"id":"d","text":"It reflects hydration status"}],"answerId":"b","explanation":"Creatinine is used as a denominator because it is excreted at a fairly constant rate proportional to muscle mass, correcting for urine dilution.","kind":"trap","origin":"ai"},{"id":"urine-biochemical-composition~ai-3","moduleId":"urine-biochemical-composition","stem":"What does the presence of uric acid crystals in acidic urine indicate?","options":[{"id":"a","text":"Dehydration"},{"id":"b","text":"Biliary obstruction"},{"id":"c","text":"Purine catabolism"},{"id":"d","text":"Diabetes mellitus"}],"answerId":"c","explanation":"Uric acid crystals form due to supersaturation from purine catabolism, particularly in acidic urine.","kind":"recall","origin":"ai"},{"id":"urine-biochemical-composition~ai-4","moduleId":"urine-biochemical-composition","stem":"A patient presents with dark urine that tests positive for bilirubin. What is the most likely underlying condition?","options":[{"id":"a","text":"Diabetes mellitus"},{"id":"b","text":"Biliary obstruction"},{"id":"c","text":"Renal failure"},{"id":"d","text":"Dehydration"}],"answerId":"b","explanation":"Dark urine positive for bilirubin indicates conjugated hyperbilirubinaemia, typically due to biliary obstruction.","kind":"recall","origin":"ai"},{"id":"urine-biochemical-composition~ai-5","moduleId":"urine-biochemical-composition","stem":"How does the biochemistry of urine relate to urine microscopy findings?","options":[{"id":"a","text":"It does not relate at all"},{"id":"b","text":"Biochemistry predicts crystal formation"},{"id":"c","text":"Biochemistry only affects color"},{"id":"d","text":"Biochemistry is irrelevant to sediment analysis"}],"answerId":"b","explanation":"The biochemistry of urine, including solute supersaturation, directly predicts the types of crystals and casts seen under microscopy.","kind":"integration","linkedModuleIds":["urine-microscopy-sediment"],"origin":"ai"},{"id":"urine-biochemical-composition~ai-6","moduleId":"urine-biochemical-composition","stem":"Which urine finding would most likely correlate with a decreased GFR?","options":[{"id":"a","text":"Increased urea excretion"},{"id":"b","text":"Increased creatinine clearance"},{"id":"c","text":"Decreased creatinine excretion"},{"id":"d","text":"Increased proteinuria"}],"answerId":"d","explanation":"Increased proteinuria can indicate glomerular damage, which is often associated with decreased GFR.","kind":"integration","linkedModuleIds":["glomerular-filtration-gfr"],"origin":"ai"}],"renal-potassium-handling":[{"id":"renal-potassium-handling~ai-0","moduleId":"renal-potassium-handling","stem":"What is the primary mechanism by which aldosterone increases potassium secretion in the distal nephron?","options":[{"id":"a","text":"Increases Na⁺/K⁺-ATPase activity"},{"id":"b","text":"Increases ENaC activity"},{"id":"c","text":"Increases K⁺ reabsorption"},{"id":"d","text":"Decreases distal tubular flow"}],"answerId":"b","explanation":"Aldosterone primarily increases the activity of epithelial sodium channels (ENaC), leading to increased sodium reabsorption and subsequent potassium secretion.","kind":"mechanism","origin":"ai"},{"id":"renal-potassium-handling~ai-1","moduleId":"renal-potassium-handling","stem":"Which of the following conditions is most likely to cause hyperkalemia?","options":[{"id":"a","text":"Excessive diuretic use"},{"id":"b","text":"Primary hyperaldosteronism"},{"id":"c","text":"Acidosis"},{"id":"d","text":"Insulin administration"}],"answerId":"c","explanation":"Acidosis causes a transcellular shift of potassium out of cells, leading to hyperkalemia.","kind":"clinical","origin":"ai"},{"id":"renal-potassium-handling~ai-2","moduleId":"renal-potassium-handling","stem":"In a patient taking a loop diuretic, what would you expect to find in their serum potassium levels?","options":[{"id":"a","text":"Hyperkalemia"},{"id":"b","text":"Normokalemia"},{"id":"c","text":"Hypokalemia"},{"id":"d","text":"Variable potassium levels"}],"answerId":"c","explanation":"Loop diuretics increase distal flow and sodium delivery, leading to increased potassium secretion and hypokalemia.","kind":"recall","origin":"ai"},{"id":"renal-potassium-handling~ai-3","moduleId":"renal-potassium-handling","stem":"What determines potassium excretion in the kidney?","options":[{"id":"a","text":"Filtered load of potassium"},{"id":"b","text":"Reabsorption in the proximal tubule"},{"id":"c","text":"Secretion in the distal nephron"},{"id":"d","text":"Aldosterone levels only"}],"answerId":"c","explanation":"Potassium excretion is primarily determined by secretion in the distal nephron, not by the amount filtered or reabsorbed.","kind":"trap","origin":"ai"},{"id":"renal-potassium-handling~ai-4","moduleId":"renal-potassium-handling","stem":"How does alkalosis affect potassium levels in the serum?","options":[{"id":"a","text":"Increases serum potassium"},{"id":"b","text":"Decreases serum potassium"},{"id":"c","text":"No effect on serum potassium"},{"id":"d","text":"Increases potassium reabsorption"}],"answerId":"b","explanation":"Alkalosis drives potassium into cells, decreasing serum potassium levels.","kind":"mechanism","origin":"ai"},{"id":"renal-potassium-handling~ai-5","moduleId":"renal-potassium-handling","stem":"A patient with acute kidney injury presents with hyperkalemia. Which mechanism is most likely responsible for this finding?","options":[{"id":"a","text":"Increased potassium filtration"},{"id":"b","text":"Decreased potassium secretion"},{"id":"c","text":"Increased aldosterone secretion"},{"id":"d","text":"Increased distal flow"}],"answerId":"b","explanation":"Acute kidney injury can impair potassium secretion, leading to hyperkalemia due to reduced renal function.","kind":"clinical","linkedModuleIds":["acute-kidney-injury-azotemia"],"origin":"ai"},{"id":"renal-potassium-handling~ai-6","moduleId":"renal-potassium-handling","stem":"Which of the following treatments for hyperkalemia works by driving potassium into cells?","options":[{"id":"a","text":"Spironolactone"},{"id":"b","text":"Insulin"},{"id":"c","text":"Furosemide"},{"id":"d","text":"Amiloride"}],"answerId":"b","explanation":"Insulin drives potassium into cells, effectively lowering serum potassium levels.","kind":"integration","linkedModuleIds":["tubular-reabsorption-secretion"],"origin":"ai"}],"body-fluid-compartments-renal":[{"id":"body-fluid-compartments-renal~ai-0","moduleId":"body-fluid-compartments-renal","stem":"What is the approximate percentage of total body water (TBW) in an average adult?","options":[{"id":"a","text":"40%"},{"id":"b","text":"50%"},{"id":"c","text":"60%"},{"id":"d","text":"70%"}],"answerId":"c","explanation":"Total body water is approximately 60% of body weight in an average adult.","kind":"recall","origin":"ai"},{"id":"body-fluid-compartments-renal~ai-1","moduleId":"body-fluid-compartments-renal","stem":"Which compartment has the highest concentration of potassium?","options":[{"id":"a","text":"Intracellular fluid"},{"id":"b","text":"Extracellular fluid"},{"id":"c","text":"Plasma"},{"id":"d","text":"Interstitial fluid"}],"answerId":"a","explanation":"Intracellular fluid (ICF) is characterized by a high concentration of potassium.","kind":"recall","origin":"ai"},{"id":"body-fluid-compartments-renal~ai-2","moduleId":"body-fluid-compartments-renal","stem":"What primarily determines extracellular fluid (ECF) volume?","options":[{"id":"a","text":"Total body water"},{"id":"b","text":"Total body sodium"},{"id":"c","text":"Total body potassium"},{"id":"d","text":"Plasma protein concentration"}],"answerId":"b","explanation":"ECF volume is primarily determined by total body sodium, as sodium regulates water retention.","kind":"mechanism","origin":"ai"},{"id":"body-fluid-compartments-renal~ai-3","moduleId":"body-fluid-compartments-renal","stem":"In acute hyponatraemia, what happens to cells?","options":[{"id":"a","text":"Cells swell"},{"id":"b","text":"Cells shrink"},{"id":"c","text":"No change"},{"id":"d","text":"Cells burst"}],"answerId":"a","explanation":"In acute hyponatraemia, low ECF osmolality causes water to move into cells, leading to cell swelling.","kind":"recall","origin":"ai"},{"id":"body-fluid-compartments-renal~ai-4","moduleId":"body-fluid-compartments-renal","stem":"What is the main reason for the lower percentage of total body water in obese individuals?","options":[{"id":"a","text":"Higher muscle mass"},{"id":"b","text":"Higher fat content"},{"id":"c","text":"Lower sodium intake"},{"id":"d","text":"Higher fluid retention"}],"answerId":"b","explanation":"Adipose tissue is relatively water-poor, leading to a lower percentage of total body water in obese individuals.","kind":"trap","origin":"ai"},{"id":"body-fluid-compartments-renal~ai-5","moduleId":"body-fluid-compartments-renal","stem":"How does water intoxication affect osmolality and cell volume?","options":[{"id":"a","text":"Increases osmolality, cells shrink"},{"id":"b","text":"Decreases osmolality, cells swell"},{"id":"c","text":"No effect on osmolality, cells remain unchanged"},{"id":"d","text":"Increases osmolality, cells swell"}],"answerId":"b","explanation":"Water intoxication decreases osmolality, causing water to move into cells and leading to cell swelling.","kind":"mechanism","origin":"ai"},{"id":"body-fluid-compartments-renal~ai-6","moduleId":"body-fluid-compartments-renal","stem":"How does sodium balance relate to ECF volume regulation?","options":[{"id":"a","text":"Sodium concentration directly reflects ECF volume"},{"id":"b","text":"Sodium content is irrelevant to ECF volume"},{"id":"c","text":"Sodium regulates water retention, affecting ECF volume"},{"id":"d","text":"Sodium and water are independent of each other"}],"answerId":"c","explanation":"Sodium regulates water retention, which directly affects ECF volume.","kind":"integration","linkedModuleIds":["sodium-balance-ecf-volume"],"origin":"ai"},{"id":"body-fluid-compartments-renal~ai-7","moduleId":"body-fluid-compartments-renal","stem":"What is the role of ADH in body fluid compartments?","options":[{"id":"a","text":"Regulates sodium excretion"},{"id":"b","text":"Controls water reabsorption in kidneys"},{"id":"c","text":"Increases extracellular fluid volume"},{"id":"d","text":"Decreases intracellular fluid volume"}],"answerId":"b","explanation":"ADH controls water reabsorption in the kidneys, impacting body fluid compartments.","kind":"integration","linkedModuleIds":["adh-water-regulation"],"origin":"ai"}],"neurogenic-bladder-disorders":[{"id":"neurogenic-bladder-disorders~ai-0","moduleId":"neurogenic-bladder-disorders","stem":"What type of bladder dysfunction is expected in a patient with a suprasacral spinal cord lesion?","options":[{"id":"a","text":"Flaccid bladder"},{"id":"b","text":"Spastic bladder"},{"id":"c","text":"Normal bladder function"},{"id":"d","text":"Obstructive bladder"}],"answerId":"b","explanation":"A suprasacral lesion leads to a spastic bladder due to loss of cortical inhibition, resulting in overactive detrusor contractions.","kind":"recall","origin":"ai"},{"id":"neurogenic-bladder-disorders~ai-1","moduleId":"neurogenic-bladder-disorders","stem":"Which clinical finding is characteristic of a flaccid neurogenic bladder?","options":[{"id":"a","text":"High detrusor pressures"},{"id":"b","text":"Small bladder capacity"},{"id":"c","text":"Overflow incontinence"},{"id":"d","text":"Urgency to void"}],"answerId":"c","explanation":"A flaccid bladder is characterized by urinary retention and overflow incontinence due to the inability of the detrusor to contract.","kind":"recall","origin":"ai"},{"id":"neurogenic-bladder-disorders~ai-2","moduleId":"neurogenic-bladder-disorders","stem":"What is the primary management strategy for a patient with a spastic neurogenic bladder?","options":[{"id":"a","text":"Intermittent catheterization"},{"id":"b","text":"Antimuscarinics"},{"id":"c","text":"Cholinergics"},{"id":"d","text":"Surgical intervention"}],"answerId":"b","explanation":"Antimuscarinics are used to manage overactive bladder symptoms in patients with spastic neurogenic bladder.","kind":"recall","origin":"ai"},{"id":"neurogenic-bladder-disorders~ai-3","moduleId":"neurogenic-bladder-disorders","stem":"During spinal shock after an acute spinal cord injury, what type of bladder is observed?","options":[{"id":"a","text":"Spastic bladder"},{"id":"b","text":"Flaccid bladder"},{"id":"c","text":"Normal bladder function"},{"id":"d","text":"Obstructive bladder"}],"answerId":"b","explanation":"Immediately after spinal cord injury, the bladder is flaccid due to spinal shock before the spastic pattern develops.","kind":"trap","origin":"ai"},{"id":"neurogenic-bladder-disorders~ai-4","moduleId":"neurogenic-bladder-disorders","stem":"What is the mechanism behind detrusor-sphincter dyssynergia in spastic neurogenic bladder?","options":[{"id":"a","text":"Loss of detrusor contraction"},{"id":"b","text":"Involuntary detrusor contractions"},{"id":"c","text":"Increased bladder capacity"},{"id":"d","text":"Normal sphincter function"}],"answerId":"b","explanation":"Detrusor-sphincter dyssynergia occurs when the detrusor and sphincter contract simultaneously, leading to high bladder pressures.","kind":"mechanism","origin":"ai"},{"id":"neurogenic-bladder-disorders~ai-5","moduleId":"neurogenic-bladder-disorders","stem":"How does a sacral spinal cord lesion affect bladder function compared to a suprasacral lesion?","options":[{"id":"a","text":"Both cause spastic bladder"},{"id":"b","text":"Both cause flaccid bladder"},{"id":"c","text":"Suprasacral causes flaccid, sacral causes spastic"},{"id":"d","text":"Suprasacral causes spastic, sacral causes flaccid"}],"answerId":"d","explanation":"A suprasacral lesion results in a spastic bladder, while a sacral lesion leads to a flaccid bladder due to loss of reflex arc.","kind":"integration","linkedModuleIds":["micturition-reflex"],"origin":"ai"},{"id":"neurogenic-bladder-disorders~ai-6","moduleId":"neurogenic-bladder-disorders","stem":"What complication can arise from a spastic neurogenic bladder if not managed properly?","options":[{"id":"a","text":"Chronic kidney disease"},{"id":"b","text":"Urinary tract infection"},{"id":"c","text":"Bladder cancer"},{"id":"d","text":"Prostatic enlargement"}],"answerId":"a","explanation":"High pressures from a spastic bladder can lead to vesicoureteric reflux and chronic kidney disease if not managed to keep bladder pressures low.","kind":"clinical","origin":"ai"}],"urinalysis-physical-chemical":[{"id":"urinalysis-physical-chemical~ai-0","moduleId":"urinalysis-physical-chemical","stem":"What is the primary reason for performing a urinalysis using a first-morning sample?","options":[{"id":"a","text":"It is the most concentrated urine sample."},{"id":"b","text":"It is less likely to contain bacteria."},{"id":"c","text":"It has a higher pH."},{"id":"d","text":"It is easier to collect."}],"answerId":"a","explanation":"First-morning samples are more concentrated, providing a better assessment of kidney function and potential abnormalities.","kind":"recall","origin":"ai"},{"id":"urinalysis-physical-chemical~ai-1","moduleId":"urinalysis-physical-chemical","stem":"A patient presents with a positive nitrite and leukocyte esterase on urinalysis. What is the most likely diagnosis?","options":[{"id":"a","text":"Diabetes Mellitus"},{"id":"b","text":"Acute Kidney Injury"},{"id":"c","text":"Urinary Tract Infection"},{"id":"d","text":"Chronic Kidney Disease"}],"answerId":"c","explanation":"Positive nitrite and leukocyte esterase indicate the presence of Gram-negative bacteria, commonly associated with urinary tract infections.","kind":"clinical","origin":"ai"},{"id":"urinalysis-physical-chemical~ai-2","moduleId":"urinalysis-physical-chemical","stem":"What does a fixed specific gravity of ~1.010 indicate in a urinalysis?","options":[{"id":"a","text":"Dehydration"},{"id":"b","text":"Normal kidney function"},{"id":"c","text":"Loss of concentrating ability"},{"id":"d","text":"Urinary tract obstruction"}],"answerId":"c","explanation":"A fixed specific gravity of ~1.010 suggests the kidneys are unable to concentrate or dilute urine, indicative of chronic kidney disease.","kind":"mechanism","origin":"ai"},{"id":"urinalysis-physical-chemical~ai-3","moduleId":"urinalysis-physical-chemical","stem":"A dipstick shows positive blood but microscopy reveals no red blood cells. What does this indicate?","options":[{"id":"a","text":"True hematuria"},{"id":"b","text":"Hemoglobinuria or myoglobinuria"},{"id":"c","text":"Contamination"},{"id":"d","text":"Urinary tract infection"}],"answerId":"b","explanation":"A positive blood dipstick without red blood cells on microscopy indicates hemoglobinuria or myoglobinuria, not true hematuria.","kind":"trap","origin":"ai"},{"id":"urinalysis-physical-chemical~ai-4","moduleId":"urinalysis-physical-chemical","stem":"Which of the following urine pH levels is most likely to promote the formation of uric acid stones?","options":[{"id":"a","text":"4.0"},{"id":"b","text":"6.0"},{"id":"c","text":"7.5"},{"id":"d","text":"8.0"}],"answerId":"a","explanation":"An acidic urine pH (around 4.0) is associated with an increased risk of uric acid stone formation.","kind":"mechanism","origin":"ai"},{"id":"urinalysis-physical-chemical~ai-5","moduleId":"urinalysis-physical-chemical","stem":"How does the presence of ketones in urine relate to the body's metabolic state?","options":[{"id":"a","text":"Indicates renal failure"},{"id":"b","text":"Suggests diabetes or starvation"},{"id":"c","text":"Reflects dehydration"},{"id":"d","text":"Shows urinary tract infection"}],"answerId":"b","explanation":"Ketonuria typically indicates a state of ketosis, which can occur in diabetes or during starvation.","kind":"clinical","origin":"ai"},{"id":"urinalysis-physical-chemical~ai-6","moduleId":"urinalysis-physical-chemical","stem":"In a patient with chronic kidney disease, how might urinalysis findings differ from a healthy individual?","options":[{"id":"a","text":"Increased glucose levels"},{"id":"b","text":"Fixed specific gravity"},{"id":"c","text":"Positive nitrite"},{"id":"d","text":"Decreased protein levels"}],"answerId":"b","explanation":"Patients with chronic kidney disease often exhibit a fixed specific gravity due to impaired concentrating ability.","kind":"integration","linkedModuleIds":["proteinuria-evaluation"],"origin":"ai"},{"id":"urinalysis-physical-chemical~ai-7","moduleId":"urinalysis-physical-chemical","stem":"What is the relationship between urine concentration and ADH levels?","options":[{"id":"a","text":"High ADH leads to dilute urine"},{"id":"b","text":"Low ADH leads to concentrated urine"},{"id":"c","text":"High ADH leads to concentrated urine"},{"id":"d","text":"ADH has no effect on urine concentration"}],"answerId":"c","explanation":"High levels of ADH promote water reabsorption in the kidneys, leading to concentrated urine.","kind":"integration","linkedModuleIds":["adh-water-regulation"],"origin":"ai"}],"volume-water-balance-hormones":[{"id":"volume-water-balance-hormones~ai-0","moduleId":"volume-water-balance-hormones","stem":"What hormone is primarily responsible for sodium reabsorption in the collecting duct?","options":[{"id":"a","text":"Aldosterone"},{"id":"b","text":"Antidiuretic hormone"},{"id":"c","text":"Natriuretic peptide"},{"id":"d","text":"Renin"}],"answerId":"a","explanation":"Aldosterone acts on the collecting duct to promote sodium reabsorption via ENaC channels.","kind":"recall","origin":"ai"},{"id":"volume-water-balance-hormones~ai-1","moduleId":"volume-water-balance-hormones","stem":"Which condition is characterized by elevated levels of BNP?","options":[{"id":"a","text":"Dehydration"},{"id":"b","text":"Heart failure"},{"id":"c","text":"Hypotension"},{"id":"d","text":"Hyperaldosteronism"}],"answerId":"b","explanation":"Elevated BNP is a marker of ventricular stretch, commonly seen in heart failure.","kind":"recall","origin":"ai"},{"id":"volume-water-balance-hormones~ai-2","moduleId":"volume-water-balance-hormones","stem":"In response to low effective circulating volume, which mechanism is activated?","options":[{"id":"a","text":"Increased ANP secretion"},{"id":"b","text":"Increased renin release"},{"id":"c","text":"Decreased ADH secretion"},{"id":"d","text":"Decreased thirst sensation"}],"answerId":"b","explanation":"Low effective circulating volume activates the RAAS, leading to increased renin release.","kind":"mechanism","origin":"ai"},{"id":"volume-water-balance-hormones~ai-3","moduleId":"volume-water-balance-hormones","stem":"What is the primary action of atrial natriuretic peptide (ANP)?","options":[{"id":"a","text":"Increase sodium reabsorption"},{"id":"b","text":"Promote diuresis"},{"id":"c","text":"Stimulate thirst"},{"id":"d","text":"Enhance renin secretion"}],"answerId":"b","explanation":"ANP promotes diuresis and natriuresis to counteract volume overload.","kind":"recall","origin":"ai"},{"id":"volume-water-balance-hormones~ai-4","moduleId":"volume-water-balance-hormones","stem":"In severe hypovolemia, what happens to plasma sodium concentration despite water retention?","options":[{"id":"a","text":"It increases"},{"id":"b","text":"It decreases"},{"id":"c","text":"It remains unchanged"},{"id":"d","text":"It fluctuates"}],"answerId":"b","explanation":"In severe hypovolemia, ADH retains water, leading to dilutional hyponatremia.","kind":"trap","origin":"ai"},{"id":"volume-water-balance-hormones~ai-5","moduleId":"volume-water-balance-hormones","stem":"How does the body prioritize volume regulation over osmolality in severe dehydration?","options":[{"id":"a","text":"By inhibiting ADH release"},{"id":"b","text":"By activating thirst mechanisms"},{"id":"c","text":"By retaining water despite low sodium"},{"id":"d","text":"By increasing ANP secretion"}],"answerId":"c","explanation":"In severe dehydration, the body retains water via ADH to maintain blood pressure, even at the cost of hyponatremia.","kind":"trap","origin":"ai"},{"id":"volume-water-balance-hormones~ai-6","moduleId":"volume-water-balance-hormones","stem":"How does ADH affect renal water handling?","options":[{"id":"a","text":"Increases sodium excretion"},{"id":"b","text":"Promotes water reabsorption"},{"id":"c","text":"Inhibits thirst"},{"id":"d","text":"Decreases GFR"}],"answerId":"b","explanation":"ADH promotes water reabsorption in the collecting ducts, concentrating urine.","kind":"mechanism","origin":"ai"},{"id":"volume-water-balance-hormones~ai-7","moduleId":"volume-water-balance-hormones","stem":"Which hormone's action is primarily countered by ANP?","options":[{"id":"a","text":"Aldosterone"},{"id":"b","text":"ADH"},{"id":"c","text":"Renin"},{"id":"d","text":"Angiotensin II"}],"answerId":"a","explanation":"ANP opposes the actions of aldosterone, promoting natriuresis and diuresis.","kind":"integration","linkedModuleIds":["hen1-aldosterone-raas"],"origin":"ai"},{"id":"volume-water-balance-hormones~ai-8","moduleId":"volume-water-balance-hormones","stem":"What is the effect of volume overload on the renin-angiotensin-aldosterone system (RAAS)?","options":[{"id":"a","text":"Activation of RAAS"},{"id":"b","text":"Inhibition of RAAS"},{"id":"c","text":"No effect on RAAS"},{"id":"d","text":"Increased renin secretion"}],"answerId":"b","explanation":"Volume overload inhibits RAAS, promoting natriuresis and diuresis instead.","kind":"integration","linkedModuleIds":["htn-diuretics-raas"],"origin":"ai"}],"sodium-balance-ecf-volume":[{"id":"sodium-balance-ecf-volume~ai-0","moduleId":"sodium-balance-ecf-volume","stem":"What is the primary determinant of extracellular fluid (ECF) volume in the body?","options":[{"id":"a","text":"Total body potassium"},{"id":"b","text":"Total body sodium"},{"id":"c","text":"Total body water"},{"id":"d","text":"Total body chloride"}],"answerId":"b","explanation":"Total body sodium is the most important factor that determines ECF volume, as water follows sodium.","kind":"recall","origin":"ai"},{"id":"sodium-balance-ecf-volume~ai-1","moduleId":"sodium-balance-ecf-volume","stem":"Which hormone is primarily responsible for sodium retention during low effective circulating volume?","options":[{"id":"a","text":"Aldosterone"},{"id":"b","text":"Natriuretic peptide"},{"id":"c","text":"Antidiuretic hormone"},{"id":"d","text":"Renin"}],"answerId":"a","explanation":"Aldosterone promotes sodium reabsorption in the kidneys, particularly when effective circulating volume is low.","kind":"mechanism","origin":"ai"},{"id":"sodium-balance-ecf-volume~ai-2","moduleId":"sodium-balance-ecf-volume","stem":"A patient presents with peripheral edema and low urine sodium. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Increased ANP secretion"},{"id":"b","text":"RAAS activation"},{"id":"c","text":"Decreased aldosterone"},{"id":"d","text":"Increased diuretic use"}],"answerId":"b","explanation":"RAAS activation leads to sodium and water retention, resulting in low urine sodium and peripheral edema.","kind":"clinical","origin":"ai"},{"id":"sodium-balance-ecf-volume~ai-3","moduleId":"sodium-balance-ecf-volume","stem":"Which of the following findings would indicate a patient is experiencing volume expansion?","options":[{"id":"a","text":"High urine sodium"},{"id":"b","text":"Concentrated urine"},{"id":"c","text":"Low blood pressure"},{"id":"d","text":"Increased thirst"}],"answerId":"a","explanation":"High urine sodium indicates natriuresis, which occurs during volume expansion as the body excretes excess sodium.","kind":"recall","origin":"ai"},{"id":"sodium-balance-ecf-volume~ai-4","moduleId":"sodium-balance-ecf-volume","stem":"A patient with heart failure presents with hyponatremia. What is the most likely reason for their low plasma sodium concentration?","options":[{"id":"a","text":"Total body sodium depletion"},{"id":"b","text":"Excess total body sodium with water retention"},{"id":"c","text":"Decreased renal perfusion"},{"id":"d","text":"Increased sodium excretion"}],"answerId":"b","explanation":"In heart failure, patients often have excess total body sodium but retain water, leading to hyponatremia.","kind":"trap","origin":"ai"},{"id":"sodium-balance-ecf-volume~ai-5","moduleId":"sodium-balance-ecf-volume","stem":"How does the kidney respond to a decrease in effective circulating volume?","options":[{"id":"a","text":"Increases sodium excretion"},{"id":"b","text":"Activates the RAAS"},{"id":"c","text":"Increases natriuretic peptide secretion"},{"id":"d","text":"Decreases water reabsorption"}],"answerId":"b","explanation":"The kidney activates the RAAS to retain sodium and water in response to decreased effective circulating volume.","kind":"mechanism","origin":"ai"},{"id":"sodium-balance-ecf-volume~ai-6","moduleId":"sodium-balance-ecf-volume","stem":"In a patient with hypernatremia, which of the following is the most appropriate initial management?","options":[{"id":"a","text":"Administer isotonic saline"},{"id":"b","text":"Administer hypotonic fluids"},{"id":"c","text":"Administer diuretics"},{"id":"d","text":"Administer sodium bicarbonate"}],"answerId":"b","explanation":"Hypotonic fluids are used to correct hypernatremia by diluting the excess sodium in the body.","kind":"integration","linkedModuleIds":["sodium-water-disorders"],"origin":"ai"},{"id":"sodium-balance-ecf-volume~ai-7","moduleId":"sodium-balance-ecf-volume","stem":"Which hormone's action is directly opposed by natriuretic peptides?","options":[{"id":"a","text":"Aldosterone"},{"id":"b","text":"Antidiuretic hormone"},{"id":"c","text":"Renin"},{"id":"d","text":"Angiotensin II"}],"answerId":"a","explanation":"Natriuretic peptides promote sodium excretion, opposing the sodium-retaining effects of aldosterone.","kind":"integration","linkedModuleIds":["volume-water-balance-hormones"],"origin":"ai"}],"acute-kidney-injury-azotemia":[{"id":"acute-kidney-injury-azotemia~ai-0","moduleId":"acute-kidney-injury-azotemia","stem":"What is the most common cause of acute kidney injury (AKI)?","options":[{"id":"a","text":"Post-renal obstruction"},{"id":"b","text":"Intrinsic kidney damage"},{"id":"c","text":"Pre-renal perfusion deficit"},{"id":"d","text":"Acute glomerulonephritis"}],"answerId":"c","explanation":"Pre-renal AKI, caused by reduced perfusion, is the most common type, accounting for approximately 55% of cases.","kind":"recall","origin":"ai"},{"id":"acute-kidney-injury-azotemia~ai-1","moduleId":"acute-kidney-injury-azotemia","stem":"In a patient with acute tubular necrosis (ATN), which laboratory finding is expected?","options":[{"id":"a","text":"FENa <1%"},{"id":"b","text":"BUN:Cr >20"},{"id":"c","text":"FENa >2%"},{"id":"d","text":"Concentrated urine"}],"answerId":"c","explanation":"In ATN, the tubules fail to reabsorb sodium, leading to a FENa >2%.","kind":"recall","origin":"ai"},{"id":"acute-kidney-injury-azotemia~ai-2","moduleId":"acute-kidney-injury-azotemia","stem":"Which clinical finding is indicative of post-renal acute kidney injury?","options":[{"id":"a","text":"Muddy-brown casts"},{"id":"b","text":"Bilateral hydronephrosis on ultrasound"},{"id":"c","text":"FENa <1%"},{"id":"d","text":"Rising BUN:Cr ratio"}],"answerId":"b","explanation":"Bilateral hydronephrosis on ultrasound is a classic finding in post-renal AKI due to obstruction.","kind":"recall","origin":"ai"},{"id":"acute-kidney-injury-azotemia~ai-3","moduleId":"acute-kidney-injury-azotemia","stem":"What is the mechanism behind the low urine sodium in pre-renal AKI?","options":[{"id":"a","text":"Tubular damage"},{"id":"b","text":"Avid sodium reabsorption"},{"id":"c","text":"Obstruction"},{"id":"d","text":"Decreased GFR"}],"answerId":"b","explanation":"In pre-renal AKI, the kidneys respond to low perfusion by avidly reabsorbing sodium, resulting in low urine sodium levels.","kind":"mechanism","origin":"ai"},{"id":"acute-kidney-injury-azotemia~ai-4","moduleId":"acute-kidney-injury-azotemia","stem":"A patient presents with hyperkalaemia and peaked T waves on ECG. What is the most appropriate next step?","options":[{"id":"a","text":"Administer diuretics"},{"id":"b","text":"Initiate dialysis"},{"id":"c","text":"Provide intravenous fluids"},{"id":"d","text":"Perform a renal ultrasound"}],"answerId":"b","explanation":"Hyperkalaemia with ECG changes is a dialysis indication due to the risk of life-threatening arrhythmias.","kind":"clinical","origin":"ai"},{"id":"acute-kidney-injury-azotemia~ai-5","moduleId":"acute-kidney-injury-azotemia","stem":"Which finding would help differentiate pre-renal AKI from acute tubular necrosis?","options":[{"id":"a","text":"High urine sodium"},{"id":"b","text":"FENa <1%"},{"id":"c","text":"Muddy-brown casts"},{"id":"d","text":"BUN:Cr <10"}],"answerId":"b","explanation":"In pre-renal AKI, the FENa is <1% due to intact tubules, while in ATN, it is >2%.","kind":"trap","origin":"ai"},{"id":"acute-kidney-injury-azotemia~ai-6","moduleId":"acute-kidney-injury-azotemia","stem":"How does acute kidney injury (AKI) relate to chronic kidney disease (CKD)?","options":[{"id":"a","text":"AKI can progress to CKD"},{"id":"b","text":"CKD is a common cause of AKI"},{"id":"c","text":"AKI is always reversible"},{"id":"d","text":"CKD presents with oliguria"}],"answerId":"a","explanation":"Acute kidney injury can lead to chronic kidney disease if not resolved, as persistent damage can impair kidney function long-term.","kind":"integration","linkedModuleIds":["chronic-kidney-disease-uremia"],"origin":"ai"},{"id":"acute-kidney-injury-azotemia~ai-7","moduleId":"acute-kidney-injury-azotemia","stem":"Which urinalysis finding is most relevant when assessing for acute tubular necrosis (ATN)?","options":[{"id":"a","text":"Bacteria"},{"id":"b","text":"Muddy-brown casts"},{"id":"c","text":"Proteinuria"},{"id":"d","text":"Hematuria"}],"answerId":"b","explanation":"Muddy-brown casts are characteristic of ATN and help differentiate it from other types of AKI.","kind":"integration","linkedModuleIds":["urine-microscopy-sediment"],"origin":"ai"}],"adh-water-regulation":[{"id":"adh-water-regulation~ai-0","moduleId":"adh-water-regulation","stem":"What is the primary stimulus for the release of ADH?","options":[{"id":"a","text":"Increased blood volume"},{"id":"b","text":"Decreased plasma osmolality"},{"id":"c","text":"Increased plasma osmolality"},{"id":"d","text":"Decreased blood pressure"}],"answerId":"c","explanation":"ADH release is primarily stimulated by an increase in plasma osmolality detected by hypothalamic osmoreceptors.","kind":"recall","origin":"ai"},{"id":"adh-water-regulation~ai-1","moduleId":"adh-water-regulation","stem":"Which mechanism describes how ADH increases water reabsorption in the collecting duct?","options":[{"id":"a","text":"Inhibition of sodium reabsorption"},{"id":"b","text":"Activation of V1 receptors"},{"id":"c","text":"Insertion of aquaporin-2 channels"},{"id":"d","text":"Inhibition of aldosterone secretion"}],"answerId":"c","explanation":"ADH acts on V2 receptors to increase cAMP, leading to the insertion of aquaporin-2 channels into the apical membrane, enhancing water reabsorption.","kind":"mechanism","origin":"ai"},{"id":"adh-water-regulation~ai-2","moduleId":"adh-water-regulation","stem":"A patient presents with polyuria and polydipsia. A water deprivation test shows concentrated urine. What is the likely diagnosis?","options":[{"id":"a","text":"Nephrogenic diabetes insipidus"},{"id":"b","text":"Central diabetes insipidus"},{"id":"c","text":"Syndrome of inappropriate ADH secretion"},{"id":"d","text":"Diabetes mellitus"}],"answerId":"b","explanation":"The ability to concentrate urine after water deprivation indicates that the kidneys are responsive to ADH, suggesting central diabetes insipidus.","kind":"clinical","origin":"ai"},{"id":"adh-water-regulation~ai-3","moduleId":"adh-water-regulation","stem":"Which of the following findings would be expected in a patient with nephrogenic diabetes insipidus?","options":[{"id":"a","text":"Concentrated urine after desmopressin"},{"id":"b","text":"Dilute urine with high ADH levels"},{"id":"c","text":"Normal urine concentration after water deprivation"},{"id":"d","text":"Hyponatraemia with concentrated urine"}],"answerId":"b","explanation":"In nephrogenic diabetes insipidus, the kidneys are unresponsive to ADH, leading to dilute urine despite high ADH levels.","kind":"trap","origin":"ai"},{"id":"adh-water-regulation~ai-4","moduleId":"adh-water-regulation","stem":"In a patient with SIADH, what would you expect to find in their urine analysis?","options":[{"id":"a","text":"Dilute urine with low osmolality"},{"id":"b","text":"Concentrated urine with low sodium"},{"id":"c","text":"Concentrated urine with high sodium"},{"id":"d","text":"Dilute urine with high osmolality"}],"answerId":"c","explanation":"SIADH leads to excess ADH, causing water retention and concentrated urine, often with hyponatraemia.","kind":"clinical","origin":"ai"},{"id":"adh-water-regulation~ai-5","moduleId":"adh-water-regulation","stem":"How does lithium cause nephrogenic diabetes insipidus?","options":[{"id":"a","text":"Inhibits ADH production"},{"id":"b","text":"Blocks V2 receptor signaling"},{"id":"c","text":"Increases aquaporin-2 expression"},{"id":"d","text":"Enhances renal blood flow"}],"answerId":"b","explanation":"Lithium interferes with the action of ADH at the collecting duct by blocking V2 receptor signaling, leading to nephrogenic diabetes insipidus.","kind":"mechanism","origin":"ai"},{"id":"adh-water-regulation~ai-6","moduleId":"adh-water-regulation","stem":"How is the regulation of ADH linked to the hormonal control of volume and water balance?","options":[{"id":"a","text":"ADH directly stimulates aldosterone secretion"},{"id":"b","text":"ADH and aldosterone both increase urine output"},{"id":"c","text":"ADH regulates water reabsorption while aldosterone regulates sodium reabsorption"},{"id":"d","text":"ADH decreases thirst response"}],"answerId":"c","explanation":"ADH primarily regulates water reabsorption, while aldosterone regulates sodium reabsorption, both contributing to overall fluid balance.","kind":"integration","linkedModuleIds":["volume-water-balance-hormones"],"origin":"ai"},{"id":"adh-water-regulation~ai-7","moduleId":"adh-water-regulation","stem":"What is the relationship between ADH and the countercurrent mechanism in urine concentration?","options":[{"id":"a","text":"ADH enhances the countercurrent multiplier effect"},{"id":"b","text":"ADH decreases the osmotic gradient"},{"id":"c","text":"ADH has no effect on urine concentration"},{"id":"d","text":"ADH inhibits countercurrent exchange"}],"answerId":"a","explanation":"ADH enhances the countercurrent multiplier effect by promoting water reabsorption in the collecting duct, allowing for concentrated urine.","kind":"integration","linkedModuleIds":["urine-concentration-countercurrent"],"origin":"ai"}],"renal-calcium-phosphate-handling":[{"id":"renal-calcium-phosphate-handling~ai-0","moduleId":"renal-calcium-phosphate-handling","stem":"What is the primary mechanism by which thiazide diuretics decrease urinary calcium excretion?","options":[{"id":"a","text":"Inhibition of Na⁺-Ca²⁺ exchanger"},{"id":"b","text":"Increased distal Ca²⁺ reabsorption"},{"id":"c","text":"Inhibition of PTH secretion"},{"id":"d","text":"Increased renal blood flow"}],"answerId":"b","explanation":"Thiazides enhance distal calcium reabsorption, leading to decreased urinary calcium excretion, which is beneficial in preventing calcium stones.","kind":"mechanism","origin":"ai"},{"id":"renal-calcium-phosphate-handling~ai-1","moduleId":"renal-calcium-phosphate-handling","stem":"Which hormone is primarily responsible for increasing renal phosphate excretion?","options":[{"id":"a","text":"Calcitonin"},{"id":"b","text":"Parathyroid hormone (PTH)"},{"id":"c","text":"Aldosterone"},{"id":"d","text":"Antidiuretic hormone (ADH)"}],"answerId":"b","explanation":"Parathyroid hormone (PTH) inhibits phosphate reabsorption in the proximal tubule, leading to increased phosphate excretion.","kind":"recall","origin":"ai"},{"id":"renal-calcium-phosphate-handling~ai-2","moduleId":"renal-calcium-phosphate-handling","stem":"In chronic kidney disease, which of the following best explains the mechanism of hyperphosphatemia?","options":[{"id":"a","text":"Increased dietary phosphate intake"},{"id":"b","text":"Decreased renal phosphate excretion"},{"id":"c","text":"Increased PTH secretion"},{"id":"d","text":"Decreased intestinal phosphate absorption"}],"answerId":"b","explanation":"Chronic kidney disease leads to a reduced glomerular filtration rate (GFR), resulting in decreased renal phosphate excretion and subsequent hyperphosphatemia.","kind":"mechanism","origin":"ai"},{"id":"renal-calcium-phosphate-handling~ai-3","moduleId":"renal-calcium-phosphate-handling","stem":"A patient on loop diuretics presents with hypomagnesaemia. What is the underlying mechanism?","options":[{"id":"a","text":"Increased magnesium reabsorption in the DCT"},{"id":"b","text":"Decreased magnesium reabsorption in the thick ascending limb"},{"id":"c","text":"Increased renal magnesium secretion"},{"id":"d","text":"Decreased dietary magnesium absorption"}],"answerId":"b","explanation":"Loop diuretics impair magnesium reabsorption primarily in the thick ascending limb, leading to hypomagnesaemia.","kind":"mechanism","origin":"ai"},{"id":"renal-calcium-phosphate-handling~ai-4","moduleId":"renal-calcium-phosphate-handling","stem":"Which of the following findings would be expected in a patient with primary hyperparathyroidism?","options":[{"id":"a","text":"Hypophosphatemia"},{"id":"b","text":"Hypocalcemia"},{"id":"c","text":"Hyperphosphaturia"},{"id":"d","text":"Hypercalcemia"}],"answerId":"d","explanation":"Primary hyperparathyroidism typically results in hypercalcemia due to increased bone resorption and renal reabsorption of calcium.","kind":"recall","origin":"ai"},{"id":"renal-calcium-phosphate-handling~ai-5","moduleId":"renal-calcium-phosphate-handling","stem":"How does chronic kidney disease affect vitamin D metabolism?","options":[{"id":"a","text":"Increased activation of vitamin D"},{"id":"b","text":"Decreased activation of vitamin D"},{"id":"c","text":"Increased renal clearance of vitamin D"},{"id":"d","text":"No effect on vitamin D metabolism"}],"answerId":"b","explanation":"Chronic kidney disease impairs the activation of vitamin D, leading to decreased levels of active vitamin D (calcitriol).","kind":"mechanism","origin":"ai"},{"id":"renal-calcium-phosphate-handling~ai-6","moduleId":"renal-calcium-phosphate-handling","stem":"How does renal handling of calcium relate to the effects of thiazide diuretics?","options":[{"id":"a","text":"Thiazides increase calcium reabsorption in the PCT"},{"id":"b","text":"Thiazides decrease calcium reabsorption in the DCT"},{"id":"c","text":"Thiazides enhance calcium reabsorption in the DCT"},{"id":"d","text":"Thiazides have no effect on calcium handling"}],"answerId":"c","explanation":"Thiazide diuretics enhance calcium reabsorption in the distal convoluted tubule, leading to decreased urinary calcium excretion.","kind":"integration","linkedModuleIds":["chronic-kidney-disease-uremia"],"origin":"ai"},{"id":"renal-calcium-phosphate-handling~ai-7","moduleId":"renal-calcium-phosphate-handling","stem":"What is the relationship between PTH and phosphate handling in the kidneys?","options":[{"id":"a","text":"PTH increases phosphate reabsorption"},{"id":"b","text":"PTH decreases phosphate reabsorption"},{"id":"c","text":"PTH has no effect on phosphate handling"},{"id":"d","text":"PTH increases urinary phosphate excretion without affecting reabsorption"}],"answerId":"b","explanation":"PTH decreases phosphate reabsorption in the proximal tubule, leading to increased urinary phosphate excretion.","kind":"integration","linkedModuleIds":["renal-endocrine-functions"],"origin":"ai"}],"proteinuria-evaluation":[{"id":"proteinuria-evaluation~ai-0","moduleId":"proteinuria-evaluation","stem":"What is the primary mechanism behind glomerular proteinuria?","options":[{"id":"a","text":"Increased tubular reabsorption"},{"id":"b","text":"Leaky glomerular barrier"},{"id":"c","text":"Overflow of light chains"},{"id":"d","text":"Increased filtration pressure"}],"answerId":"b","explanation":"Glomerular proteinuria is primarily due to a leaky glomerular barrier, allowing albumin to pass into the urine.","kind":"mechanism","origin":"ai"},{"id":"proteinuria-evaluation~ai-1","moduleId":"proteinuria-evaluation","stem":"Which condition is indicated by a urine protein:creatinine ratio greater than 3.5 g/day?","options":[{"id":"a","text":"Acute kidney injury"},{"id":"b","text":"Nephrotic syndrome"},{"id":"c","text":"Tubular proteinuria"},{"id":"d","text":"Overflow proteinuria"}],"answerId":"b","explanation":"A urine protein:creatinine ratio greater than 3.5 g/day is characteristic of nephrotic syndrome, which includes hypoalbuminaemia and oedema.","kind":"recall","origin":"ai"},{"id":"proteinuria-evaluation~ai-2","moduleId":"proteinuria-evaluation","stem":"A patient presents with a negative urine dipstick but has clinical signs of multiple myeloma. What should be the next step?","options":[{"id":"a","text":"Repeat the dipstick test"},{"id":"b","text":"Order urine protein electrophoresis"},{"id":"c","text":"Perform a 24-hour urine collection"},{"id":"d","text":"Start treatment for myeloma"}],"answerId":"b","explanation":"Urine protein electrophoresis is necessary to detect light chains in cases of suspected multiple myeloma, as they may not be detected by a standard dipstick.","kind":"trap","origin":"ai"},{"id":"proteinuria-evaluation~ai-3","moduleId":"proteinuria-evaluation","stem":"What is the significance of microalbuminuria in a diabetic patient?","options":[{"id":"a","text":"Indicates acute kidney injury"},{"id":"b","text":"Early marker of diabetic nephropathy"},{"id":"c","text":"Sign of nephrotic syndrome"},{"id":"d","text":"Normal finding in diabetes"}],"answerId":"b","explanation":"Microalbuminuria is an early marker of diabetic nephropathy and cardiovascular risk in diabetic patients.","kind":"recall","origin":"ai"},{"id":"proteinuria-evaluation~ai-4","moduleId":"proteinuria-evaluation","stem":"Which of the following findings is most consistent with tubular proteinuria?","options":[{"id":"a","text":"Presence of RBC casts"},{"id":"b","text":"High levels of β2-microglobulin"},{"id":"c","text":"Significant albuminuria"},{"id":"d","text":"Negative urine light chains"}],"answerId":"b","explanation":"Tubular proteinuria is characterized by the presence of low-molecular-weight proteins, such as β2-microglobulin, due to failed reabsorption.","kind":"recall","origin":"ai"},{"id":"proteinuria-evaluation~ai-5","moduleId":"proteinuria-evaluation","stem":"How does nephrotic syndrome differ from nephritic syndrome in terms of proteinuria?","options":[{"id":"a","text":"Nephrotic syndrome has more hematuria"},{"id":"b","text":"Nephritic syndrome has higher proteinuria"},{"id":"c","text":"Nephrotic syndrome has >3.5 g/day protein"},{"id":"d","text":"Nephritic syndrome is characterized by hypoalbuminaemia"}],"answerId":"c","explanation":"Nephrotic syndrome is defined by heavy proteinuria (>3.5 g/day), while nephritic syndrome typically has milder proteinuria along with hematuria.","kind":"clinical","origin":"ai"},{"id":"proteinuria-evaluation~ai-6","moduleId":"proteinuria-evaluation","stem":"How does chronic kidney disease relate to proteinuria evaluation?","options":[{"id":"a","text":"It is unrelated to proteinuria"},{"id":"b","text":"Proteinuria is a marker of disease progression"},{"id":"c","text":"Chronic kidney disease always presents with nephrotic syndrome"},{"id":"d","text":"Proteinuria indicates acute kidney injury"}],"answerId":"b","explanation":"Proteinuria is a significant marker of disease progression in chronic kidney disease and can indicate worsening renal function.","kind":"integration","linkedModuleIds":["chronic-kidney-disease-uremia"],"origin":"ai"},{"id":"proteinuria-evaluation~ai-7","moduleId":"proteinuria-evaluation","stem":"What histological change is typically seen in glomerular disease associated with significant proteinuria?","options":[{"id":"a","text":"Tubular atrophy"},{"id":"b","text":"Podocyte injury"},{"id":"c","text":"Interstitial fibrosis"},{"id":"d","text":"Vascular sclerosis"}],"answerId":"b","explanation":"Podocyte injury is a common histological change in glomerular diseases that lead to significant proteinuria due to loss of charge and size selectivity.","kind":"integration","linkedModuleIds":["glomerular-disease-overview"],"origin":"ai"}],"micturition-reflex":[{"id":"micturition-reflex~ai-0","moduleId":"micturition-reflex","stem":"What is the primary nerve responsible for contracting the detrusor muscle during bladder voiding?","options":[{"id":"a","text":"Hypogastric nerve"},{"id":"b","text":"Pelvic nerve"},{"id":"c","text":"Pudendal nerve"},{"id":"d","text":"Vagus nerve"}],"answerId":"b","explanation":"The pelvic nerve (S2–4) is responsible for detrusor contraction during voiding via M3 receptors.","kind":"recall","origin":"ai"},{"id":"micturition-reflex~ai-1","moduleId":"micturition-reflex","stem":"Which of the following best describes the role of the sympathetic nervous system in bladder function?","options":[{"id":"a","text":"Contracts the detrusor muscle"},{"id":"b","text":"Relaxes the internal sphincter"},{"id":"c","text":"Promotes bladder storage"},{"id":"d","text":"Stimulates voiding reflex"}],"answerId":"c","explanation":"The sympathetic nervous system promotes bladder storage by relaxing the detrusor and contracting the internal sphincter.","kind":"mechanism","origin":"ai"},{"id":"micturition-reflex~ai-2","moduleId":"micturition-reflex","stem":"A patient presents with urinary retention and overflow incontinence. Which type of bladder dysfunction is most likely?","options":[{"id":"a","text":"Spastic bladder"},{"id":"b","text":"Atonic bladder"},{"id":"c","text":"Detrusor-sphincter dyssynergia"},{"id":"d","text":"Normal bladder"}],"answerId":"b","explanation":"Atonic bladder (flaccid) is characterized by urinary retention and overflow incontinence due to sacral nerve lesions.","kind":"clinical","origin":"ai"},{"id":"micturition-reflex~ai-3","moduleId":"micturition-reflex","stem":"Which finding is indicative of a suprasacral spinal cord injury affecting bladder function?","options":[{"id":"a","text":"Involuntary bladder contractions"},{"id":"b","text":"Voluntary control of external sphincter"},{"id":"c","text":"Large bladder capacity"},{"id":"d","text":"Complete urinary retention"}],"answerId":"a","explanation":"Involuntary bladder contractions and small capacity indicate a spastic bladder due to upper motor neuron lesions.","kind":"recall","origin":"ai"},{"id":"micturition-reflex~ai-4","moduleId":"micturition-reflex","stem":"What is the primary mechanism by which the external urethral sphincter is controlled?","options":[{"id":"a","text":"Sympathetic nervous system"},{"id":"b","text":"Parasympathetic nervous system"},{"id":"c","text":"Somatic nervous system"},{"id":"d","text":"Central nervous system"}],"answerId":"c","explanation":"The external urethral sphincter is under voluntary control via the somatic pudendal nerve (S2–4).","kind":"recall","origin":"ai"},{"id":"micturition-reflex~ai-5","moduleId":"micturition-reflex","stem":"In a patient with neurogenic bladder due to a spinal cord injury, which mechanism is disrupted leading to detrusor-sphincter dyssynergia?","options":[{"id":"a","text":"Loss of cortical control"},{"id":"b","text":"Increased sympathetic activity"},{"id":"c","text":"Increased parasympathetic activity"},{"id":"d","text":"Loss of pontine coordination"}],"answerId":"d","explanation":"Detrusor-sphincter dyssynergia occurs due to loss of coordination between the detrusor and sphincters, often from pontine lesions.","kind":"trap","origin":"ai"},{"id":"micturition-reflex~ai-6","moduleId":"micturition-reflex","stem":"How does a neurogenic bladder impact urinalysis results, particularly in terms of bladder capacity?","options":[{"id":"a","text":"Increased protein levels"},{"id":"b","text":"Decreased urine volume"},{"id":"c","text":"Increased urine pH"},{"id":"d","text":"Decreased specific gravity"}],"answerId":"b","explanation":"Neurogenic bladder can lead to urinary retention, resulting in decreased urine volume in urinalysis.","kind":"integration","linkedModuleIds":["neurogenic-bladder-disorders"],"origin":"ai"},{"id":"micturition-reflex~ai-7","moduleId":"micturition-reflex","stem":"What urinalysis finding would you expect in a patient with a spastic bladder due to a suprasacral spinal cord injury?","options":[{"id":"a","text":"High specific gravity"},{"id":"b","text":"Low pH"},{"id":"c","text":"Increased ketones"},{"id":"d","text":"Normal protein levels"}],"answerId":"a","explanation":"A spastic bladder may lead to concentrated urine, resulting in high specific gravity in urinalysis.","kind":"integration","linkedModuleIds":["urinalysis-physical-chemical"],"origin":"ai"}],"renal-metabolism-gluconeogenesis":[{"id":"renal-metabolism-gluconeogenesis~ai-0","moduleId":"renal-metabolism-gluconeogenesis","stem":"What is the primary substrate for renal gluconeogenesis in the proximal tubule?","options":[{"id":"a","text":"Glucose"},{"id":"b","text":"Lactate"},{"id":"c","text":"Glutamine"},{"id":"d","text":"Glycerol"}],"answerId":"c","explanation":"Glutamine is a key substrate for gluconeogenesis in the proximal tubule, linking it to ammoniagenesis.","kind":"recall","origin":"ai"},{"id":"renal-metabolism-gluconeogenesis~ai-1","moduleId":"renal-metabolism-gluconeogenesis","stem":"Why is the outer medulla particularly vulnerable to ischemia?","options":[{"id":"a","text":"It receives the most blood flow."},{"id":"b","text":"It has a low oxygen supply despite high oxygen demand."},{"id":"c","text":"It is metabolically inactive."},{"id":"d","text":"It has a high concentration of toxins."}],"answerId":"b","explanation":"The outer medulla has low blood flow to preserve the concentrating gradient, leading to a supply-demand mismatch for oxygen.","kind":"trap","origin":"ai"},{"id":"renal-metabolism-gluconeogenesis~ai-2","moduleId":"renal-metabolism-gluconeogenesis","stem":"During prolonged fasting, what percentage of the body's endogenous glucose can the kidney contribute?","options":[{"id":"a","text":"10%"},{"id":"b","text":"20%"},{"id":"c","text":"30%"},{"id":"d","text":"40%"}],"answerId":"d","explanation":"The kidney can contribute up to approximately 40% of the body's endogenous glucose during prolonged fasting through gluconeogenesis.","kind":"recall","origin":"ai"},{"id":"renal-metabolism-gluconeogenesis~ai-3","moduleId":"renal-metabolism-gluconeogenesis","stem":"What is the main energy cost associated with renal oxygen consumption?","options":[{"id":"a","text":"Gluconeogenesis"},{"id":"b","text":"Na⁺ reabsorption"},{"id":"c","text":"Urea synthesis"},{"id":"d","text":"Ammoniagenesis"}],"answerId":"b","explanation":"Renal oxygen consumption is primarily linked to the active transport of Na⁺ during reabsorption.","kind":"mechanism","origin":"ai"},{"id":"renal-metabolism-gluconeogenesis~ai-4","moduleId":"renal-metabolism-gluconeogenesis","stem":"How does renal metabolism relate to blood pressure regulation?","options":[{"id":"a","text":"It has no effect on blood pressure."},{"id":"b","text":"It alters Na⁺ handling and metabolism in hypertension."},{"id":"c","text":"It decreases renal blood flow."},{"id":"d","text":"It increases glucose production."}],"answerId":"b","explanation":"Renal metabolism is increasingly linked to blood pressure regulation through altered proximal metabolism and Na⁺ handling in hypertension.","kind":"integration","linkedModuleIds":["tubular-reabsorption-secretion"],"origin":"ai"},{"id":"renal-metabolism-gluconeogenesis~ai-5","moduleId":"renal-metabolism-gluconeogenesis","stem":"Which segment of the nephron primarily relies on anaerobic glycolysis due to its hypoxic environment?","options":[{"id":"a","text":"Proximal tubule"},{"id":"b","text":"Thick ascending limb"},{"id":"c","text":"Distal convoluted tubule"},{"id":"d","text":"Collecting duct"}],"answerId":"b","explanation":"The thick ascending limb relies more on anaerobic glycolysis due to the hypoxic conditions of the renal medulla.","kind":"recall","origin":"ai"},{"id":"renal-metabolism-gluconeogenesis~ai-6","moduleId":"renal-metabolism-gluconeogenesis","stem":"What is the relationship between glutamine use and acid excretion in the kidney?","options":[{"id":"a","text":"Glutamine increases glucose production only."},{"id":"b","text":"Glutamine is a substrate for both glucose and NH₄⁺ production."},{"id":"c","text":"Glutamine is not involved in acid-base balance."},{"id":"d","text":"Glutamine decreases ammoniagenesis."}],"answerId":"b","explanation":"Glutamine serves as a substrate for both gluconeogenesis and ammoniagenesis, linking glucose production to acid excretion.","kind":"integration","linkedModuleIds":["renal-acid-excretion"],"origin":"ai"}],"acid-base-disorders-compensation":[{"id":"acid-base-disorders-compensation~ai-0","moduleId":"acid-base-disorders-compensation","stem":"What is the primary disturbance in metabolic acidosis?","options":[{"id":"a","text":"Increased HCO₃⁻"},{"id":"b","text":"Decreased HCO₃⁻"},{"id":"c","text":"Increased PCO₂"},{"id":"d","text":"Decreased PCO₂"}],"answerId":"b","explanation":"Metabolic acidosis is characterized by a primary decrease in bicarbonate (HCO₃⁻).","kind":"recall","origin":"ai"},{"id":"acid-base-disorders-compensation~ai-1","moduleId":"acid-base-disorders-compensation","stem":"Which condition is associated with a high anion gap metabolic acidosis?","options":[{"id":"a","text":"Diarrhea"},{"id":"b","text":"Renal tubular acidosis"},{"id":"c","text":"Diabetic ketoacidosis"},{"id":"d","text":"Hyperchloremia"}],"answerId":"c","explanation":"Diabetic ketoacidosis is one of the conditions that causes a high anion gap metabolic acidosis.","kind":"recall","origin":"ai"},{"id":"acid-base-disorders-compensation~ai-2","moduleId":"acid-base-disorders-compensation","stem":"In a patient with respiratory acidosis, what compensatory change occurs in the kidneys?","options":[{"id":"a","text":"Increased HCO₃⁻ reabsorption"},{"id":"b","text":"Decreased HCO₃⁻ reabsorption"},{"id":"c","text":"Increased H⁺ secretion"},{"id":"d","text":"Decreased H⁺ secretion"}],"answerId":"a","explanation":"The kidneys compensate for respiratory acidosis by increasing bicarbonate (HCO₃⁻) reabsorption.","kind":"mechanism","origin":"ai"},{"id":"acid-base-disorders-compensation~ai-3","moduleId":"acid-base-disorders-compensation","stem":"A patient presents with a normal pH but abnormal PCO₂ and HCO₃⁻ levels. What does this indicate?","options":[{"id":"a","text":"Metabolic acidosis"},{"id":"b","text":"Respiratory alkalosis"},{"id":"c","text":"Mixed acid-base disorder"},{"id":"d","text":"Normal acid-base status"}],"answerId":"c","explanation":"A normal pH with abnormal PCO₂ and HCO₃⁻ suggests a mixed acid-base disorder, as compensation does not fully normalize pH.","kind":"trap","origin":"ai"},{"id":"acid-base-disorders-compensation~ai-4","moduleId":"acid-base-disorders-compensation","stem":"What is the primary mechanism of compensation for metabolic acidosis?","options":[{"id":"a","text":"Increased respiratory rate"},{"id":"b","text":"Decreased renal acid excretion"},{"id":"c","text":"Increased bicarbonate production"},{"id":"d","text":"Decreased carbon dioxide elimination"}],"answerId":"a","explanation":"The primary compensation for metabolic acidosis is an increased respiratory rate to decrease PCO₂.","kind":"mechanism","origin":"ai"},{"id":"acid-base-disorders-compensation~ai-5","moduleId":"acid-base-disorders-compensation","stem":"How does chronic kidney disease contribute to metabolic acidosis?","options":[{"id":"a","text":"Increased bicarbonate reabsorption"},{"id":"b","text":"Decreased acid excretion"},{"id":"c","text":"Increased PCO₂"},{"id":"d","text":"Decreased HCO₃⁻ production"}],"answerId":"b","explanation":"Chronic kidney disease leads to decreased acid excretion, contributing to metabolic acidosis.","kind":"integration","linkedModuleIds":["chronic-kidney-disease-uremia"],"origin":"ai"},{"id":"acid-base-disorders-compensation~ai-6","moduleId":"acid-base-disorders-compensation","stem":"What is the relationship between renal bicarbonate reabsorption and metabolic acidosis?","options":[{"id":"a","text":"Bicarbonate reabsorption decreases in metabolic acidosis"},{"id":"b","text":"Bicarbonate reabsorption increases to compensate"},{"id":"c","text":"Bicarbonate reabsorption is unaffected"},{"id":"d","text":"Bicarbonate reabsorption is the primary cause of metabolic acidosis"}],"answerId":"b","explanation":"In metabolic acidosis, the kidneys increase bicarbonate reabsorption as a compensatory mechanism.","kind":"integration","linkedModuleIds":["renal-bicarbonate-reabsorption"],"origin":"ai"}],"otitis-media-sinusitis-epiglottitis":[{"id":"otitis-media-sinusitis-epiglottitis~ai-0","moduleId":"otitis-media-sinusitis-epiglottitis","stem":"What is the most common bacterial pathogen associated with acute otitis media in children?","options":[{"id":"a","text":"Streptococcus pneumoniae"},{"id":"b","text":"Moraxella catarrhalis"},{"id":"c","text":"Haemophilus influenzae"},{"id":"d","text":"Staphylococcus aureus"}],"answerId":"a","explanation":"Streptococcus pneumoniae is the most frequently identified pathogen in cases of acute otitis media.","kind":"recall","origin":"ai"},{"id":"otitis-media-sinusitis-epiglottitis~ai-1","moduleId":"otitis-media-sinusitis-epiglottitis","stem":"Which clinical finding is characteristic of acute epiglottitis?","options":[{"id":"a","text":"Barking cough"},{"id":"b","text":"Tripod posture"},{"id":"c","text":"Fever without stridor"},{"id":"d","text":"Erythematous tympanic membrane"}],"answerId":"b","explanation":"Tripod posture is a classic sign of acute epiglottitis, indicating respiratory distress.","kind":"recall","origin":"ai"},{"id":"otitis-media-sinusitis-epiglottitis~ai-2","moduleId":"otitis-media-sinusitis-epiglottitis","stem":"What mechanism leads to bacterial rhinosinusitis following a viral upper respiratory infection?","options":[{"id":"a","text":"Viral replication"},{"id":"b","text":"Impaired mucociliary clearance"},{"id":"c","text":"Direct bacterial invasion"},{"id":"d","text":"Allergic inflammation"}],"answerId":"b","explanation":"Impaired mucociliary clearance due to viral infection allows bacteria to proliferate in the sinuses.","kind":"mechanism","origin":"ai"},{"id":"otitis-media-sinusitis-epiglottitis~ai-3","moduleId":"otitis-media-sinusitis-epiglottitis","stem":"Which of the following is a feared complication of acute bacterial rhinosinusitis?","options":[{"id":"a","text":"Mastoiditis"},{"id":"b","text":"Cavernous sinus thrombosis"},{"id":"c","text":"Otitis media"},{"id":"d","text":"Epiglottitis"}],"answerId":"b","explanation":"Cavernous sinus thrombosis is a serious complication that can arise from the spread of infection from the sinuses.","kind":"trap","origin":"ai"},{"id":"otitis-media-sinusitis-epiglottitis~ai-4","moduleId":"otitis-media-sinusitis-epiglottitis","stem":"In a child with suspected epiglottitis, what is the most appropriate initial management?","options":[{"id":"a","text":"Examine the throat with a tongue depressor"},{"id":"b","text":"Administer antibiotics"},{"id":"c","text":"Secure the airway"},{"id":"d","text":"Position the child supine"}],"answerId":"c","explanation":"Securing the airway is critical in suspected epiglottitis to prevent airway obstruction.","kind":"trap","origin":"ai"},{"id":"otitis-media-sinusitis-epiglottitis~ai-5","moduleId":"otitis-media-sinusitis-epiglottitis","stem":"Which bacterial pathogen is most likely responsible for epiglottitis in unvaccinated children?","options":[{"id":"a","text":"Streptococcus pneumoniae"},{"id":"b","text":"Haemophilus influenzae type b"},{"id":"c","text":"Moraxella catarrhalis"},{"id":"d","text":"Staphylococcus aureus"}],"answerId":"b","explanation":"Haemophilus influenzae type b is the classical cause of epiglottitis, especially in unvaccinated children.","kind":"recall","origin":"ai"},{"id":"otitis-media-sinusitis-epiglottitis~ai-6","moduleId":"otitis-media-sinusitis-epiglottitis","stem":"How does the presence of a viral upper respiratory infection contribute to acute otitis media?","options":[{"id":"a","text":"Increases bacterial virulence"},{"id":"b","text":"Causes direct damage to the tympanic membrane"},{"id":"c","text":"Leads to impaired drainage of the Eustachian tube"},{"id":"d","text":"Stimulates excessive mucus production"}],"answerId":"c","explanation":"A viral URI impairs drainage through the Eustachian tube, predisposing to bacterial infection.","kind":"integration","linkedModuleIds":["bacterial-physiology-growth-identification"],"origin":"ai"},{"id":"otitis-media-sinusitis-epiglottitis~ai-7","moduleId":"otitis-media-sinusitis-epiglottitis","stem":"What is the primary reason for the 'double sickening' phenomenon in acute bacterial rhinosinusitis?","options":[{"id":"a","text":"Viral reactivation"},{"id":"b","text":"Secondary bacterial infection"},{"id":"c","text":"Increased mucosal edema"},{"id":"d","text":"Allergic response"}],"answerId":"b","explanation":"Double sickening indicates a secondary bacterial infection following an initial viral illness.","kind":"integration","linkedModuleIds":["nasal-sinus-inflammatory-pathology"],"origin":"ai"}],"chronic-kidney-disease-uremia":[{"id":"chronic-kidney-disease-uremia~ai-0","moduleId":"chronic-kidney-disease-uremia","stem":"What is the primary cause of secondary hyperparathyroidism in chronic kidney disease?","options":[{"id":"a","text":"Hypocalcaemia"},{"id":"b","text":"Hyperphosphataemia"},{"id":"c","text":"Vitamin D deficiency"},{"id":"d","text":"Low erythropoietin levels"}],"answerId":"b","explanation":"In chronic kidney disease, the inability to excrete phosphate leads to hyperphosphataemia, which stimulates parathyroid hormone secretion.","kind":"recall","origin":"ai"},{"id":"chronic-kidney-disease-uremia~ai-1","moduleId":"chronic-kidney-disease-uremia","stem":"Which of the following findings is most indicative of chronic kidney disease?","options":[{"id":"a","text":"Elevated creatinine with normal-sized kidneys"},{"id":"b","text":"Sustained low eGFR for more than 3 months"},{"id":"c","text":"Acute rise in blood urea nitrogen"},{"id":"d","text":"Presence of nephrotic syndrome"}],"answerId":"b","explanation":"A sustained low eGFR for more than 3 months is a key diagnostic criterion for chronic kidney disease.","kind":"recall","origin":"ai"},{"id":"chronic-kidney-disease-uremia~ai-2","moduleId":"chronic-kidney-disease-uremia","stem":"What is the mechanism of anaemia in chronic kidney disease?","options":[{"id":"a","text":"Increased destruction of red blood cells"},{"id":"b","text":"Decreased erythropoietin production"},{"id":"c","text":"Iron deficiency due to blood loss"},{"id":"d","text":"Bone marrow suppression"}],"answerId":"b","explanation":"Chronic kidney disease leads to decreased production of erythropoietin, resulting in normocytic anaemia.","kind":"mechanism","origin":"ai"},{"id":"chronic-kidney-disease-uremia~ai-3","moduleId":"chronic-kidney-disease-uremia","stem":"A patient with chronic kidney disease presents with confusion and asterixis. What does this indicate?","options":[{"id":"a","text":"Acute kidney injury"},{"id":"b","text":"Uraemic encephalopathy"},{"id":"c","text":"Electrolyte imbalance"},{"id":"d","text":"Diabetic ketoacidosis"}],"answerId":"b","explanation":"Confusion and asterixis are signs of uraemic encephalopathy, which occurs in advanced chronic kidney disease.","kind":"clinical","origin":"ai"},{"id":"chronic-kidney-disease-uremia~ai-4","moduleId":"chronic-kidney-disease-uremia","stem":"Which of the following findings would help differentiate chronic kidney disease from acute kidney injury?","options":[{"id":"a","text":"Elevated creatinine"},{"id":"b","text":"Normocytic anaemia"},{"id":"c","text":"Acute onset of symptoms"},{"id":"d","text":"Enlarged kidneys on ultrasound"}],"answerId":"b","explanation":"Normocytic anaemia is a chronic finding that, along with small kidneys, suggests chronic kidney disease rather than acute kidney injury.","kind":"trap","origin":"ai"},{"id":"chronic-kidney-disease-uremia~ai-5","moduleId":"chronic-kidney-disease-uremia","stem":"How does chronic kidney disease lead to metabolic acidosis?","options":[{"id":"a","text":"Increased bicarbonate reabsorption"},{"id":"b","text":"Decreased acid excretion"},{"id":"c","text":"Increased lactic acid production"},{"id":"d","text":"Decreased carbon dioxide elimination"}],"answerId":"b","explanation":"In chronic kidney disease, the kidneys lose the ability to excrete acids, leading to metabolic acidosis.","kind":"mechanism","origin":"ai"},{"id":"chronic-kidney-disease-uremia~ai-6","moduleId":"chronic-kidney-disease-uremia","stem":"In chronic kidney disease, which laboratory finding is most likely to be present alongside hyperphosphataemia?","options":[{"id":"a","text":"Hypercalcaemia"},{"id":"b","text":"Increased erythropoietin"},{"id":"c","text":"Elevated parathyroid hormone"},{"id":"d","text":"Decreased creatinine"}],"answerId":"c","explanation":"Hyperphosphataemia in chronic kidney disease stimulates the secretion of parathyroid hormone, leading to secondary hyperparathyroidism.","kind":"integration","linkedModuleIds":["renal-endocrine-functions"],"origin":"ai"},{"id":"chronic-kidney-disease-uremia~ai-7","moduleId":"chronic-kidney-disease-uremia","stem":"Which complication of chronic kidney disease is most directly related to the loss of renal endocrine function?","options":[{"id":"a","text":"Uraemic frost"},{"id":"b","text":"Hyperkalaemia"},{"id":"c","text":"Normocytic anaemia"},{"id":"d","text":"Hypertension"}],"answerId":"c","explanation":"Normocytic anaemia results from decreased erythropoietin production due to the loss of renal endocrine function in chronic kidney disease.","kind":"integration","linkedModuleIds":["renal-endocrine-functions"],"origin":"ai"}],"renal-endocrine-functions":[{"id":"renal-endocrine-functions~ai-0","moduleId":"renal-endocrine-functions","stem":"What is the primary cause of normocytic anaemia in chronic kidney disease?","options":[{"id":"a","text":"Iron deficiency"},{"id":"b","text":"Blood loss"},{"id":"c","text":"Reduced erythropoietin production"},{"id":"d","text":"Vitamin B12 deficiency"}],"answerId":"c","explanation":"In chronic kidney disease, the primary cause of normocytic anaemia is reduced erythropoietin production by the failing kidney.","kind":"recall","origin":"ai"},{"id":"renal-endocrine-functions~ai-1","moduleId":"renal-endocrine-functions","stem":"Which hormone is primarily responsible for the activation of vitamin D in the kidneys?","options":[{"id":"a","text":"Calcitonin"},{"id":"b","text":"Parathyroid hormone"},{"id":"c","text":"1α-hydroxylase"},{"id":"d","text":"Renin"}],"answerId":"c","explanation":"1α-hydroxylase is the enzyme responsible for converting 25-OH-vitamin D to its active form, calcitriol, in the kidneys.","kind":"recall","origin":"ai"},{"id":"renal-endocrine-functions~ai-2","moduleId":"renal-endocrine-functions","stem":"In chronic kidney disease, what is the effect of decreased calcitriol on calcium levels?","options":[{"id":"a","text":"Hypercalcaemia"},{"id":"b","text":"Hypocalcaemia"},{"id":"c","text":"Normocalcaemia"},{"id":"d","text":"Increased bone resorption"}],"answerId":"b","explanation":"Decreased calcitriol leads to hypocalcaemia due to reduced intestinal absorption of calcium.","kind":"mechanism","origin":"ai"},{"id":"renal-endocrine-functions~ai-3","moduleId":"renal-endocrine-functions","stem":"What clinical finding is associated with renal artery stenosis?","options":[{"id":"a","text":"Hypotension"},{"id":"b","text":"Normocytic anaemia"},{"id":"c","text":"Hypertension"},{"id":"d","text":"Hypercalcaemia"}],"answerId":"c","explanation":"Renal artery stenosis activates the renin-angiotensin-aldosterone system, leading to hypertension.","kind":"recall","origin":"ai"},{"id":"renal-endocrine-functions~ai-4","moduleId":"renal-endocrine-functions","stem":"Why can NSAIDs precipitate acute kidney injury in volume-depleted patients?","options":[{"id":"a","text":"Inhibition of renin release"},{"id":"b","text":"Inhibition of prostaglandin synthesis"},{"id":"c","text":"Increased renal perfusion"},{"id":"d","text":"Decreased sodium reabsorption"}],"answerId":"b","explanation":"NSAIDs inhibit prostaglandin synthesis, which are vasodilators that help maintain renal blood flow, especially in volume-depleted states.","kind":"trap","origin":"ai"},{"id":"renal-endocrine-functions~ai-5","moduleId":"renal-endocrine-functions","stem":"How does chronic kidney disease lead to secondary hyperparathyroidism?","options":[{"id":"a","text":"Increased calcium absorption"},{"id":"b","text":"Decreased calcitriol production"},{"id":"c","text":"Increased phosphate excretion"},{"id":"d","text":"Decreased parathyroid hormone secretion"}],"answerId":"b","explanation":"Reduced calcitriol production in CKD leads to decreased calcium levels, stimulating secondary hyperparathyroidism.","kind":"mechanism","origin":"ai"},{"id":"renal-endocrine-functions~ai-6","moduleId":"renal-endocrine-functions","stem":"How does renal failure contribute to anaemia and bone disease?","options":[{"id":"a","text":"Increased erythropoietin and calcitriol"},{"id":"b","text":"Decreased erythropoietin and calcitriol"},{"id":"c","text":"Increased calcium and phosphate"},{"id":"d","text":"Decreased renin and aldosterone"}],"answerId":"b","explanation":"Renal failure leads to decreased erythropoietin production, causing anaemia, and decreased calcitriol, leading to bone disease.","kind":"integration","linkedModuleIds":["chronic-kidney-disease-uremia"],"origin":"ai"},{"id":"renal-endocrine-functions~ai-7","moduleId":"renal-endocrine-functions","stem":"What role does renin play in the context of kidney function and blood pressure regulation?","options":[{"id":"a","text":"Increases calcium reabsorption"},{"id":"b","text":"Stimulates erythropoietin production"},{"id":"c","text":"Activates the renin-angiotensin-aldosterone system"},{"id":"d","text":"Inhibits prostaglandin synthesis"}],"answerId":"c","explanation":"Renin initiates the renin-angiotensin-aldosterone system, which regulates blood pressure and fluid balance.","kind":"integration","linkedModuleIds":["volume-water-balance-hormones"],"origin":"ai"}],"nasal-sinus-inflammatory-pathology":[{"id":"nasal-sinus-inflammatory-pathology~ai-0","moduleId":"nasal-sinus-inflammatory-pathology","stem":"What is the most common cause of allergic rhinitis?","options":[{"id":"a","text":"Bacterial infection"},{"id":"b","text":"Viral infection"},{"id":"c","text":"IgE-mediated hypersensitivity"},{"id":"d","text":"Fungal infection"}],"answerId":"c","explanation":"Allergic rhinitis is primarily caused by an IgE-mediated hypersensitivity reaction to allergens.","kind":"recall","origin":"ai"},{"id":"nasal-sinus-inflammatory-pathology~ai-1","moduleId":"nasal-sinus-inflammatory-pathology","stem":"Which clinical finding is characteristic of Granulomatosis with polyangiitis (GPA)?","options":[{"id":"a","text":"Pale boggy nasal mucosa"},{"id":"b","text":"Saddle-nose deformity"},{"id":"c","text":"Recurrent epistaxis"},{"id":"d","text":"Black necrotic nasal turbinate"}],"answerId":"b","explanation":"GPA is associated with saddle-nose deformity and other systemic symptoms, distinguishing it from other conditions.","kind":"recall","origin":"ai"},{"id":"nasal-sinus-inflammatory-pathology~ai-2","moduleId":"nasal-sinus-inflammatory-pathology","stem":"What is the mechanism of nasal obstruction in allergic rhinitis?","options":[{"id":"a","text":"Vasodilation"},{"id":"b","text":"Mucosal edema"},{"id":"c","text":"Nasal polyp formation"},{"id":"d","text":"Infection"}],"answerId":"b","explanation":"In allergic rhinitis, mucosal edema due to inflammation causes nasal obstruction.","kind":"mechanism","origin":"ai"},{"id":"nasal-sinus-inflammatory-pathology~ai-3","moduleId":"nasal-sinus-inflammatory-pathology","stem":"Which statement about nasal polyps is true?","options":[{"id":"a","text":"They are benign neoplasms"},{"id":"b","text":"They arise from normal epithelium"},{"id":"c","text":"They are inflammatory protrusions"},{"id":"d","text":"They are always associated with malignancy"}],"answerId":"c","explanation":"Nasal polyps are inflammatory protrusions of oedematous mucosa, not true neoplasms.","kind":"trap","origin":"ai"},{"id":"nasal-sinus-inflammatory-pathology~ai-4","moduleId":"nasal-sinus-inflammatory-pathology","stem":"A 16-year-old male presents with recurrent epistaxis and nasal obstruction. What is the most likely diagnosis?","options":[{"id":"a","text":"Chronic sinusitis"},{"id":"b","text":"Nasal polyp"},{"id":"c","text":"Granulomatosis with polyangiitis"},{"id":"d","text":"Nasopharyngeal angiofibroma"}],"answerId":"d","explanation":"Nasopharyngeal angiofibroma is a common cause of recurrent epistaxis in adolescent males.","kind":"clinical","origin":"ai"},{"id":"nasal-sinus-inflammatory-pathology~ai-5","moduleId":"nasal-sinus-inflammatory-pathology","stem":"How does chronic sinusitis predispose to secondary bacterial infections?","options":[{"id":"a","text":"Increased mucosal blood flow"},{"id":"b","text":"Impaired drainage from the ostiomeatal complex"},{"id":"c","text":"Direct invasion of bacteria"},{"id":"d","text":"Allergic response"}],"answerId":"b","explanation":"Chronic sinusitis leads to impaired drainage, causing stasis and increasing the risk of bacterial infections.","kind":"mechanism","origin":"ai"},{"id":"nasal-sinus-inflammatory-pathology~ai-6","moduleId":"nasal-sinus-inflammatory-pathology","stem":"Which condition is most likely to cause black necrotic nasal turbinate in a diabetic patient?","options":[{"id":"a","text":"Chronic sinusitis"},{"id":"b","text":"Granulomatosis with polyangiitis"},{"id":"c","text":"Invasive mucormycosis"},{"id":"d","text":"Nasal polyp"}],"answerId":"c","explanation":"Invasive mucormycosis is characterized by black necrotic tissue and is common in immunocompromised patients.","kind":"clinical","origin":"ai"},{"id":"nasal-sinus-inflammatory-pathology~ai-7","moduleId":"nasal-sinus-inflammatory-pathology","stem":"A patient with asthma presents with nasal polyps and aspirin sensitivity. What is the most likely diagnosis?","options":[{"id":"a","text":"Chronic rhinosinusitis"},{"id":"b","text":"Granulomatosis with polyangiitis"},{"id":"c","text":"Samter triad"},{"id":"d","text":"Nasal angiofibroma"}],"answerId":"c","explanation":"The combination of asthma, nasal polyps, and aspirin sensitivity is known as Samter triad.","kind":"integration","linkedModuleIds":["asthma-bronchiectasis-pathology"],"origin":"ai"},{"id":"nasal-sinus-inflammatory-pathology~ai-8","moduleId":"nasal-sinus-inflammatory-pathology","stem":"What is the primary treatment for allergic rhinitis?","options":[{"id":"a","text":"Antibiotics"},{"id":"b","text":"Nasal corticosteroids"},{"id":"c","text":"Surgery"},{"id":"d","text":"Antihistamines"}],"answerId":"b","explanation":"Nasal corticosteroids are the first-line treatment for managing allergic rhinitis symptoms.","kind":"integration","linkedModuleIds":["cough-cold-allergy-drugs"],"origin":"ai"}],"urinary-crystals-and-stones":[{"id":"urinary-crystals-and-stones~ai-0","moduleId":"urinary-crystals-and-stones","stem":"What is the most common type of kidney stone?","options":[{"id":"a","text":"Calcium oxalate"},{"id":"b","text":"Uric acid"},{"id":"c","text":"Struvite"},{"id":"d","text":"Cystine"}],"answerId":"a","explanation":"Calcium oxalate stones account for approximately 80% of all kidney stones.","kind":"recall","origin":"ai"},{"id":"urinary-crystals-and-stones~ai-1","moduleId":"urinary-crystals-and-stones","stem":"Which type of urinary stone is associated with alkaline urine and urease-producing bacteria?","options":[{"id":"a","text":"Calcium oxalate"},{"id":"b","text":"Struvite"},{"id":"c","text":"Uric acid"},{"id":"d","text":"Cystine"}],"answerId":"b","explanation":"Struvite stones form in alkaline urine and are associated with infections from urease-producing bacteria.","kind":"recall","origin":"ai"},{"id":"urinary-crystals-and-stones~ai-2","moduleId":"urinary-crystals-and-stones","stem":"A patient presents with severe colicky loin-to-groin pain and hematuria. What is the likely diagnosis?","options":[{"id":"a","text":"Urinary tract infection"},{"id":"b","text":"Ureteric stone"},{"id":"c","text":"Appendicitis"},{"id":"d","text":"Pancreatitis"}],"answerId":"b","explanation":"Severe colicky pain and hematuria are classic symptoms of a ureteric stone.","kind":"clinical","origin":"ai"},{"id":"urinary-crystals-and-stones~ai-3","moduleId":"urinary-crystals-and-stones","stem":"What is the mechanism behind the formation of calcium oxalate stones?","options":[{"id":"a","text":"Increased uric acid production"},{"id":"b","text":"Supersaturation of calcium and oxalate"},{"id":"c","text":"Infection with urease-producing bacteria"},{"id":"d","text":"Genetic defect in cystine transport"}],"answerId":"b","explanation":"Calcium oxalate stones form due to the supersaturation of urine with calcium and oxalate.","kind":"mechanism","origin":"ai"},{"id":"urinary-crystals-and-stones~ai-4","moduleId":"urinary-crystals-and-stones","stem":"Which type of stone is typically radiolucent and may be missed on plain X-ray?","options":[{"id":"a","text":"Calcium oxalate"},{"id":"b","text":"Struvite"},{"id":"c","text":"Uric acid"},{"id":"d","text":"Cystine"}],"answerId":"c","explanation":"Uric acid stones are radiolucent and are not visible on plain X-ray, requiring CT for detection.","kind":"trap","origin":"ai"},{"id":"urinary-crystals-and-stones~ai-5","moduleId":"urinary-crystals-and-stones","stem":"In a patient with recurrent uric acid stones, which treatment strategy is most appropriate?","options":[{"id":"a","text":"Thiazide diuretics"},{"id":"b","text":"Urine alkalinization"},{"id":"c","text":"Increased calcium intake"},{"id":"d","text":"Surgery"}],"answerId":"b","explanation":"Urine alkalinization helps dissolve uric acid stones and prevent recurrence.","kind":"recall","origin":"ai"},{"id":"urinary-crystals-and-stones~ai-6","moduleId":"urinary-crystals-and-stones","stem":"A child presents with hexagonal crystals in urine. What is the most likely diagnosis?","options":[{"id":"a","text":"Calcium oxalate stones"},{"id":"b","text":"Struvite stones"},{"id":"c","text":"Uric acid stones"},{"id":"d","text":"Cystine stones"}],"answerId":"d","explanation":"Hexagonal crystals are characteristic of cystine stones, which occur in hereditary cystinuria.","kind":"recall","origin":"ai"},{"id":"urinary-crystals-and-stones~ai-7","moduleId":"urinary-crystals-and-stones","stem":"How does the anatomy of the ureter relate to the risk of stone obstruction?","options":[{"id":"a","text":"Narrowing at specific points increases obstruction risk"},{"id":"b","text":"Wider ureter reduces stone passage"},{"id":"c","text":"Ureter length has no effect on stones"},{"id":"d","text":"Ureter anatomy is irrelevant to stones"}],"answerId":"a","explanation":"The ureter has three narrowings where stones are more likely to lodge, increasing obstruction risk.","kind":"integration","linkedModuleIds":["kidney-ureter-anatomy"],"origin":"ai"},{"id":"urinary-crystals-and-stones~ai-8","moduleId":"urinary-crystals-and-stones","stem":"What is a potential complication of ureteric stones that relates to kidney function?","options":[{"id":"a","text":"Hydronephrosis leading to acute kidney injury"},{"id":"b","text":"Increased urine output"},{"id":"c","text":"Decreased blood pressure"},{"id":"d","text":"Infection without obstruction"}],"answerId":"a","explanation":"Ureteric stones can cause obstruction, leading to hydronephrosis and potential acute kidney injury.","kind":"integration","linkedModuleIds":["acute-kidney-injury-azotemia"],"origin":"ai"}],"urine-microscopy-sediment":[{"id":"urine-microscopy-sediment~ai-0","moduleId":"urine-microscopy-sediment","stem":"What type of cast is most indicative of glomerulonephritis?","options":[{"id":"a","text":"Red cell casts"},{"id":"b","text":"White cell casts"},{"id":"c","text":"Granular casts"},{"id":"d","text":"Hyaline casts"}],"answerId":"a","explanation":"Red cell casts are specifically associated with glomerular bleeding, making them a key indicator of glomerulonephritis.","kind":"recall","origin":"ai"},{"id":"urine-microscopy-sediment~ai-1","moduleId":"urine-microscopy-sediment","stem":"Which type of urinary cast is associated with acute tubular necrosis?","options":[{"id":"a","text":"Fatty casts"},{"id":"b","text":"Red cell casts"},{"id":"c","text":"Muddy-brown granular casts"},{"id":"d","text":"Waxy casts"}],"answerId":"c","explanation":"Muddy-brown granular casts are characteristic of acute tubular necrosis due to tubular cell injury.","kind":"recall","origin":"ai"},{"id":"urine-microscopy-sediment~ai-2","moduleId":"urine-microscopy-sediment","stem":"In which condition would you expect to see fatty casts in urine?","options":[{"id":"a","text":"Glomerulonephritis"},{"id":"b","text":"Nephrotic syndrome"},{"id":"c","text":"Pyelonephritis"},{"id":"d","text":"Acute tubular necrosis"}],"answerId":"b","explanation":"Fatty casts, also known as oval fat bodies, are indicative of nephrotic syndrome due to lipiduria.","kind":"recall","origin":"ai"},{"id":"urine-microscopy-sediment~ai-3","moduleId":"urine-microscopy-sediment","stem":"What is the significance of finding white cell casts in urine?","options":[{"id":"a","text":"Indicates dehydration"},{"id":"b","text":"Suggests glomerular bleeding"},{"id":"c","text":"Indicates pyelonephritis or interstitial nephritis"},{"id":"d","text":"Suggests urinary tract infection only"}],"answerId":"c","explanation":"White cell casts are indicative of pyelonephritis or interstitial nephritis, localizing the inflammation to the kidney.","kind":"clinical","origin":"ai"},{"id":"urine-microscopy-sediment~ai-4","moduleId":"urine-microscopy-sediment","stem":"Why are casts valuable in urinalysis?","options":[{"id":"a","text":"They can originate from any part of the urinary tract"},{"id":"b","text":"They localize disease to the kidney"},{"id":"c","text":"They indicate the presence of infection"},{"id":"d","text":"They are always present in dehydration"}],"answerId":"b","explanation":"Casts form only in the renal tubules, thus their presence localizes disease to the kidney, distinguishing it from lower urinary tract issues.","kind":"trap","origin":"ai"},{"id":"urine-microscopy-sediment~ai-5","moduleId":"urine-microscopy-sediment","stem":"What type of crystal would you expect to find in alkaline urine due to urease-producing bacteria?","options":[{"id":"a","text":"Calcium oxalate"},{"id":"b","text":"Struvite"},{"id":"c","text":"Uric acid"},{"id":"d","text":"Cystine"}],"answerId":"b","explanation":"Struvite crystals, often described as 'coffin-lid' crystals, are associated with alkaline urine and urease-producing bacteria.","kind":"recall","origin":"ai"},{"id":"urine-microscopy-sediment~ai-6","moduleId":"urine-microscopy-sediment","stem":"How does the presence of dysmorphic red blood cells in urine help differentiate the source of bleeding?","options":[{"id":"a","text":"Indicates lower urinary tract bleeding"},{"id":"b","text":"Indicates glomerular bleeding"},{"id":"c","text":"Indicates contamination"},{"id":"d","text":"Indicates dehydration"}],"answerId":"b","explanation":"Dysmorphic red blood cells suggest glomerular bleeding, whereas isomorphic cells indicate lower urinary tract sources.","kind":"clinical","origin":"ai"},{"id":"urine-microscopy-sediment~ai-7","moduleId":"urine-microscopy-sediment","stem":"Which of the following urine findings would best correlate with acute kidney injury?","options":[{"id":"a","text":"Fatty casts"},{"id":"b","text":"Muddy-brown granular casts"},{"id":"c","text":"Struvite crystals"},{"id":"d","text":"Dysmorphic red blood cells"}],"answerId":"b","explanation":"Muddy-brown granular casts are a hallmark of acute tubular necrosis, a common cause of acute kidney injury.","kind":"integration","linkedModuleIds":["acute-kidney-injury-azotemia"],"origin":"ai"},{"id":"urine-microscopy-sediment~ai-8","moduleId":"urine-microscopy-sediment","stem":"How do the findings of urine microscopy relate to the biochemical composition of urine?","options":[{"id":"a","text":"They provide information about urine pH only"},{"id":"b","text":"They confirm the presence of casts and crystals"},{"id":"c","text":"They indicate the presence of bacteria only"},{"id":"d","text":"They are unrelated to urine biochemistry"}],"answerId":"b","explanation":"Urine microscopy findings, such as casts and crystals, provide essential information that complements the biochemical composition of urine.","kind":"integration","linkedModuleIds":["urine-biochemical-composition"],"origin":"ai"}],"nasopharyngeal-laryngeal-tumors":[{"id":"nasopharyngeal-laryngeal-tumors~ai-0","moduleId":"nasopharyngeal-laryngeal-tumors","stem":"What is the most common viral association with nasopharyngeal carcinoma?","options":[{"id":"a","text":"Human Immunodeficiency Virus (HIV)"},{"id":"b","text":"Epstein–Barr Virus (EBV)"},{"id":"c","text":"Human Papillomavirus (HPV)"},{"id":"d","text":"Cytomegalovirus (CMV)"}],"answerId":"b","explanation":"Nasopharyngeal carcinoma is strongly linked to Epstein–Barr virus (EBV), particularly the undifferentiated type.","kind":"recall","origin":"ai"},{"id":"nasopharyngeal-laryngeal-tumors~ai-1","moduleId":"nasopharyngeal-laryngeal-tumors","stem":"Which histological feature is characteristic of undifferentiated nasopharyngeal carcinoma?","options":[{"id":"a","text":"Keratinizing squamous cells"},{"id":"b","text":"Syncytial tumor cells in a lymphocyte-rich background"},{"id":"c","text":"Mucin-producing adenocarcinoma cells"},{"id":"d","text":"Fibrovascular stroma with inflammatory cells"}],"answerId":"b","explanation":"The undifferentiated type of nasopharyngeal carcinoma shows syncytial tumor cells in a lymphocyte-rich background, also known as lymphoepithelioma.","kind":"mechanism","origin":"ai"},{"id":"nasopharyngeal-laryngeal-tumors~ai-2","moduleId":"nasopharyngeal-laryngeal-tumors","stem":"A 55-year-old smoker presents with persistent hoarseness for 3 weeks. What is the most appropriate next step?","options":[{"id":"a","text":"Voice rest and observation"},{"id":"b","text":"Laryngeal biopsy"},{"id":"c","text":"Referral to a speech therapist"},{"id":"d","text":"CT scan of the neck"}],"answerId":"b","explanation":"Persistent hoarseness in a smoker for more than 2-3 weeks warrants laryngoscopy and biopsy to rule out glottic squamous cell carcinoma.","kind":"clinical","origin":"ai"},{"id":"nasopharyngeal-laryngeal-tumors~ai-3","moduleId":"nasopharyngeal-laryngeal-tumors","stem":"A child presents with recurrent laryngeal papillomas. Which virus is most likely responsible?","options":[{"id":"a","text":"Epstein–Barr Virus (EBV)"},{"id":"b","text":"Human Papillomavirus (HPV) 6/11"},{"id":"c","text":"Cytomegalovirus (CMV)"},{"id":"d","text":"Adenovirus"}],"answerId":"b","explanation":"Recurrent laryngeal papillomas in children are typically caused by HPV types 6 and 11.","kind":"recall","origin":"ai"},{"id":"nasopharyngeal-laryngeal-tumors~ai-4","moduleId":"nasopharyngeal-laryngeal-tumors","stem":"Which of the following findings is most indicative of nasopharyngeal carcinoma?","options":[{"id":"a","text":"Bilateral vocal cord nodules"},{"id":"b","text":"Cervical node mass with nasal obstruction"},{"id":"c","text":"Unilateral vocal cord polyp"},{"id":"d","text":"Persistent cough with hemoptysis"}],"answerId":"b","explanation":"Cervical node mass with nasal obstruction is a classic presentation of nasopharyngeal carcinoma.","kind":"trap","origin":"ai"},{"id":"nasopharyngeal-laryngeal-tumors~ai-5","moduleId":"nasopharyngeal-laryngeal-tumors","stem":"How does smoking contribute to the development of laryngeal squamous cell carcinoma?","options":[{"id":"a","text":"Increases HPV infection risk"},{"id":"b","text":"Causes direct DNA damage"},{"id":"c","text":"Enhances EBV replication"},{"id":"d","text":"Promotes chronic inflammation"}],"answerId":"b","explanation":"Smoking is a known carcinogen that causes direct DNA damage, contributing to the development of laryngeal squamous cell carcinoma.","kind":"mechanism","origin":"ai"},{"id":"nasopharyngeal-laryngeal-tumors~ai-6","moduleId":"nasopharyngeal-laryngeal-tumors","stem":"A patient with nasopharyngeal carcinoma presents with a neck mass. Which linked condition should be considered for potential metastasis?","options":[{"id":"a","text":"Non-Small-Cell Lung Carcinoma"},{"id":"b","text":"Hepatocellular Carcinoma"},{"id":"c","text":"Rhinocerebral Mucormycosis"},{"id":"d","text":"Laryngeal Squamous Cell Carcinoma"}],"answerId":"a","explanation":"Metastasis from nasopharyngeal carcinoma may involve the lungs, thus considering non-small-cell lung carcinoma is relevant.","kind":"integration","linkedModuleIds":["non-small-cell-lung-carcinoma"],"origin":"ai"},{"id":"nasopharyngeal-laryngeal-tumors~ai-7","moduleId":"nasopharyngeal-laryngeal-tumors","stem":"Which symptom shared between nasopharyngeal carcinoma and sinonasal inflammation could lead to misdiagnosis?","options":[{"id":"a","text":"Nasal obstruction"},{"id":"b","text":"Cervical lymphadenopathy"},{"id":"c","text":"Unilateral serous otitis media"},{"id":"d","text":"Epistaxis"}],"answerId":"a","explanation":"Nasal obstruction is a common symptom in both conditions, which could lead to misdiagnosis if not evaluated properly.","kind":"integration","linkedModuleIds":["nasal-sinus-inflammatory-pathology"],"origin":"ai"}],"renal-acid-excretion":[{"id":"renal-acid-excretion~ai-0","moduleId":"renal-acid-excretion","stem":"What is the primary mechanism by which the kidney excretes fixed acid?","options":[{"id":"a","text":"Free H⁺ secretion"},{"id":"b","text":"Ammonium excretion"},{"id":"c","text":"Phosphate buffering"},{"id":"d","text":"Bicarbonate reabsorption"}],"answerId":"b","explanation":"The kidney primarily excretes fixed acid by increasing ammonium (NH₄⁺) excretion through upregulated glutamine ammoniagenesis.","kind":"mechanism","origin":"ai"},{"id":"renal-acid-excretion~ai-1","moduleId":"renal-acid-excretion","stem":"In renal tubular acidosis type 1, what is the expected urine pH?","options":[{"id":"a","text":"Acidic (< 5.5)"},{"id":"b","text":"Neutral (6.0)"},{"id":"c","text":"Alkaline (> 7.0)"},{"id":"d","text":"Variable"}],"answerId":"c","explanation":"In type 1 RTA, α-intercalated cells fail to secrete H⁺, leading to inappropriately alkaline urine.","kind":"recall","origin":"ai"},{"id":"renal-acid-excretion~ai-2","moduleId":"renal-acid-excretion","stem":"Which buffer is primarily responsible for the adjustable acid excretion in the kidney?","options":[{"id":"a","text":"Bicarbonate"},{"id":"b","text":"Phosphate"},{"id":"c","text":"Ammonium"},{"id":"d","text":"Lactate"}],"answerId":"c","explanation":"Ammonium (NH₄⁺) is the main adjustable buffer that allows the kidney to increase acid excretion in response to chronic acidosis.","kind":"recall","origin":"ai"},{"id":"renal-acid-excretion~ai-3","moduleId":"renal-acid-excretion","stem":"What is the effect of aldosterone on renal acid secretion?","options":[{"id":"a","text":"Inhibits H⁺ secretion"},{"id":"b","text":"Stimulates H⁺ secretion"},{"id":"c","text":"Reduces ammoniagenesis"},{"id":"d","text":"Increases bicarbonate reabsorption"}],"answerId":"b","explanation":"Aldosterone stimulates H⁺ secretion in the distal nephron, enhancing acid excretion.","kind":"mechanism","origin":"ai"},{"id":"renal-acid-excretion~ai-4","moduleId":"renal-acid-excretion","stem":"In chronic acidosis, which process is upregulated to enhance acid excretion?","options":[{"id":"a","text":"Bicarbonate reabsorption"},{"id":"b","text":"Ammoniagenesis"},{"id":"c","text":"Phosphate buffering"},{"id":"d","text":"Free H⁺ secretion"}],"answerId":"b","explanation":"Chronic acidosis leads to upregulation of ammoniagenesis, allowing for increased ammonium excretion.","kind":"mechanism","origin":"ai"},{"id":"renal-acid-excretion~ai-5","moduleId":"renal-acid-excretion","stem":"A patient presents with normal-anion-gap metabolic acidosis and hypokalemia. What is the likely diagnosis?","options":[{"id":"a","text":"Type 1 RTA"},{"id":"b","text":"Type 2 RTA"},{"id":"c","text":"Type 4 RTA"},{"id":"d","text":"Diabetic ketoacidosis"}],"answerId":"a","explanation":"Type 1 RTA is characterized by normal-anion-gap metabolic acidosis and hypokalemia due to impaired H⁺ secretion.","kind":"clinical","origin":"ai"},{"id":"renal-acid-excretion~ai-6","moduleId":"renal-acid-excretion","stem":"How does renal acid-base regulation relate to bicarbonate reabsorption?","options":[{"id":"a","text":"Both processes occur in the collecting duct"},{"id":"b","text":"Bicarbonate reabsorption is independent of acid excretion"},{"id":"c","text":"Acid excretion generates new bicarbonate"},{"id":"d","text":"Bicarbonate reabsorption decreases acid excretion"}],"answerId":"c","explanation":"The kidney generates new bicarbonate during acid excretion, linking these two processes closely.","kind":"integration","linkedModuleIds":["renal-bicarbonate-reabsorption"],"origin":"ai"},{"id":"renal-acid-excretion~ai-7","moduleId":"renal-acid-excretion","stem":"Which condition is associated with hyperkalemia and metabolic acidosis?","options":[{"id":"a","text":"Type 1 RTA"},{"id":"b","text":"Type 2 RTA"},{"id":"c","text":"Type 4 RTA"},{"id":"d","text":"Diarrhea"}],"answerId":"c","explanation":"Type 4 RTA is characterized by hypoaldosteronism, leading to hyperkalemia and reduced ammoniagenesis.","kind":"clinical","origin":"ai"},{"id":"renal-acid-excretion~ai-8","moduleId":"renal-acid-excretion","stem":"In the context of acid-base disorders, how does ammonium excretion relate to potassium handling?","options":[{"id":"a","text":"Ammonium excretion decreases potassium retention"},{"id":"b","text":"Increased ammonium excretion leads to hypokalemia"},{"id":"c","text":"Potassium levels do not affect ammonium excretion"},{"id":"d","text":"Ammonium excretion increases with potassium loss"}],"answerId":"d","explanation":"Increased ammonium excretion often occurs with potassium loss, particularly in conditions like type 4 RTA.","kind":"integration","linkedModuleIds":["renal-potassium-handling"],"origin":"ai"}],"pharyngitis-tonsillitis-diphtheria":[{"id":"pharyngitis-tonsillitis-diphtheria~ai-0","moduleId":"pharyngitis-tonsillitis-diphtheria","stem":"What is the primary reason for treating Group A β-haemolytic Streptococcus pharyngitis with penicillin?","options":[{"id":"a","text":"To shorten the duration of sore throat"},{"id":"b","text":"To prevent acute rheumatic fever"},{"id":"c","text":"To eliminate the risk of peritonsillar abscess"},{"id":"d","text":"To reduce the incidence of post-streptococcal glomerulonephritis"}],"answerId":"b","explanation":"The primary reason for treating GAS pharyngitis is to prevent acute rheumatic fever, not just to relieve symptoms.","kind":"trap","origin":"ai"},{"id":"pharyngitis-tonsillitis-diphtheria~ai-1","moduleId":"pharyngitis-tonsillitis-diphtheria","stem":"Which clinical finding is characteristic of diphtheria?","options":[{"id":"a","text":"Tonsillar exudate with tender anterior cervical nodes"},{"id":"b","text":"Grey adherent pseudomembrane over the tonsils"},{"id":"c","text":"Sandpaper rash with strawberry tongue"},{"id":"d","text":"Cough with pharyngeal erythema"}],"answerId":"b","explanation":"Diphtheria is characterized by a grey pseudomembrane that can bleed when scraped.","kind":"recall","origin":"ai"},{"id":"pharyngitis-tonsillitis-diphtheria~ai-2","moduleId":"pharyngitis-tonsillitis-diphtheria","stem":"What is the mechanism of action of the diphtheria exotoxin?","options":[{"id":"a","text":"Inhibition of DNA synthesis"},{"id":"b","text":"ADP-ribosylation of elongation factor EF-2"},{"id":"c","text":"Inhibition of RNA polymerase"},{"id":"d","text":"Disruption of cell membrane integrity"}],"answerId":"b","explanation":"The diphtheria exotoxin ADP-ribosylates elongation factor EF-2, halting protein synthesis.","kind":"mechanism","origin":"ai"},{"id":"pharyngitis-tonsillitis-diphtheria~ai-3","moduleId":"pharyngitis-tonsillitis-diphtheria","stem":"A 10-year-old presents with a sore throat, fever, and tender anterior cervical lymphadenopathy but no cough. What is the most likely diagnosis?","options":[{"id":"a","text":"Viral pharyngitis"},{"id":"b","text":"Group A streptococcal pharyngitis"},{"id":"c","text":"Diphtheria"},{"id":"d","text":"Infectious mononucleosis"}],"answerId":"b","explanation":"The presence of fever, tonsillar exudate, and tender anterior cervical nodes without cough suggests Group A streptococcal pharyngitis.","kind":"clinical","origin":"ai"},{"id":"pharyngitis-tonsillitis-diphtheria~ai-4","moduleId":"pharyngitis-tonsillitis-diphtheria","stem":"What complication is most likely to occur if Group A streptococcal pharyngitis is untreated?","options":[{"id":"a","text":"Peritonsillar abscess"},{"id":"b","text":"Acute rheumatic fever"},{"id":"c","text":"Chronic sinusitis"},{"id":"d","text":"Otitis media"}],"answerId":"b","explanation":"Acute rheumatic fever is a serious non-suppurative complication that can occur if GAS pharyngitis is untreated.","kind":"trap","origin":"ai"},{"id":"pharyngitis-tonsillitis-diphtheria~ai-5","moduleId":"pharyngitis-tonsillitis-diphtheria","stem":"Which of the following findings would suggest infectious mononucleosis rather than bacterial tonsillitis?","options":[{"id":"a","text":"Fever and cough"},{"id":"b","text":"Tonsillar exudate and anterior cervical nodes"},{"id":"c","text":"Posterior cervical lymphadenopathy and splenomegaly"},{"id":"d","text":"Erythematous pharynx with white patches"}],"answerId":"c","explanation":"Posterior cervical lymphadenopathy and splenomegaly are more indicative of infectious mononucleosis.","kind":"recall","origin":"ai"},{"id":"pharyngitis-tonsillitis-diphtheria~ai-6","moduleId":"pharyngitis-tonsillitis-diphtheria","stem":"How does the management of streptococcal pharyngitis relate to the prevention of rheumatic heart disease?","options":[{"id":"a","text":"By treating with antibiotics to reduce throat pain"},{"id":"b","text":"By preventing the development of acute rheumatic fever"},{"id":"c","text":"By eliminating the risk of peritonsillar abscess"},{"id":"d","text":"By reducing the incidence of viral infections"}],"answerId":"b","explanation":"Treating streptococcal pharyngitis prevents acute rheumatic fever, which can lead to rheumatic heart disease.","kind":"integration","linkedModuleIds":["rheumatic-heart-disease"],"origin":"ai"},{"id":"pharyngitis-tonsillitis-diphtheria~ai-7","moduleId":"pharyngitis-tonsillitis-diphtheria","stem":"Which of the following statements about the relationship between diphtheria and its vaccine is correct?","options":[{"id":"a","text":"Diphtheria is common in vaccinated populations"},{"id":"b","text":"The vaccine prevents the formation of the pseudomembrane"},{"id":"c","text":"Diphtheria vaccine is part of the DTP immunization schedule"},{"id":"d","text":"Vaccination has no effect on diphtheria-related myocarditis"}],"answerId":"c","explanation":"The diphtheria vaccine is part of the DTP immunization schedule and helps prevent the disease.","kind":"integration","linkedModuleIds":["corynebacterium-listeria"],"origin":"ai"}],"renal-bicarbonate-reabsorption":[{"id":"renal-bicarbonate-reabsorption~ai-0","moduleId":"renal-bicarbonate-reabsorption","stem":"What is the primary mechanism by which bicarbonate is reabsorbed in the proximal tubule?","options":[{"id":"a","text":"Direct transport across the apical membrane"},{"id":"b","text":"Secretion of H⁺ converting HCO₃⁻ to CO₂"},{"id":"c","text":"Endocytosis of HCO₃⁻"},{"id":"d","text":"Active transport of HCO₃⁻ via Na⁺/HCO₃⁻ cotransporter"}],"answerId":"b","explanation":"Bicarbonate is reabsorbed indirectly through the secretion of H⁺, which converts luminal HCO₃⁻ to CO₂, allowing it to diffuse into the cell.","kind":"mechanism","origin":"ai"},{"id":"renal-bicarbonate-reabsorption~ai-1","moduleId":"renal-bicarbonate-reabsorption","stem":"Which of the following conditions would lead to increased bicarbonate reabsorption in the kidney?","options":[{"id":"a","text":"Metabolic alkalosis"},{"id":"b","text":"Volume expansion"},{"id":"c","text":"Acidosis"},{"id":"d","text":"Hypercapnia"}],"answerId":"c","explanation":"Increased bicarbonate reabsorption occurs during acidosis as a compensatory mechanism to restore acid-base balance.","kind":"clinical","origin":"ai"},{"id":"renal-bicarbonate-reabsorption~ai-2","moduleId":"renal-bicarbonate-reabsorption","stem":"What is the effect of acetazolamide on bicarbonate reabsorption?","options":[{"id":"a","text":"Increases bicarbonate reabsorption"},{"id":"b","text":"Decreases bicarbonate reabsorption"},{"id":"c","text":"Has no effect on bicarbonate reabsorption"},{"id":"d","text":"Increases bicarbonate secretion"}],"answerId":"b","explanation":"Acetazolamide inhibits carbonic anhydrase, leading to decreased bicarbonate reabsorption and resulting in bicarbonate loss in urine.","kind":"trap","origin":"ai"},{"id":"renal-bicarbonate-reabsorption~ai-3","moduleId":"renal-bicarbonate-reabsorption","stem":"What is the consequence of impaired proximal bicarbonate reabsorption in type 2 renal tubular acidosis?","options":[{"id":"a","text":"Increased bicarbonate in urine"},{"id":"b","text":"Decreased bicarbonate in blood"},{"id":"c","text":"Increased acid excretion"},{"id":"d","text":"Decreased H⁺ secretion"}],"answerId":"a","explanation":"Impaired proximal bicarbonate reabsorption leads to bicarbonate wasting in urine, resulting in metabolic acidosis.","kind":"clinical","origin":"ai"},{"id":"renal-bicarbonate-reabsorption~ai-4","moduleId":"renal-bicarbonate-reabsorption","stem":"How does contraction alkalosis occur in volume depletion?","options":[{"id":"a","text":"Increased HCO₃⁻ excretion"},{"id":"b","text":"Increased HCO₃⁻ reabsorption"},{"id":"c","text":"Decreased H⁺ secretion"},{"id":"d","text":"Decreased Na⁺ reabsorption"}],"answerId":"b","explanation":"In volume depletion, angiotensin II stimulates Na⁺ reabsorption, which in turn increases bicarbonate reabsorption, leading to contraction alkalosis.","kind":"mechanism","origin":"ai"},{"id":"renal-bicarbonate-reabsorption~ai-5","moduleId":"renal-bicarbonate-reabsorption","stem":"Which of the following best describes the relationship between bicarbonate reabsorption and acid-base balance?","options":[{"id":"a","text":"Bicarbonate reabsorption is independent of acid-base status"},{"id":"b","text":"Bicarbonate reabsorption decreases during acidosis"},{"id":"c","text":"Bicarbonate reabsorption is increased during alkalosis"},{"id":"d","text":"Bicarbonate reabsorption is a compensatory mechanism for acidosis"}],"answerId":"d","explanation":"Bicarbonate reabsorption increases during acidosis as a compensatory mechanism to help restore acid-base balance.","kind":"integration","linkedModuleIds":["renal-acid-excretion"],"origin":"ai"},{"id":"renal-bicarbonate-reabsorption~ai-6","moduleId":"renal-bicarbonate-reabsorption","stem":"What is the primary role of the kidneys in acid-base balance before excreting fixed acids?","options":[{"id":"a","text":"Excrete bicarbonate"},{"id":"b","text":"Reabsorb filtered bicarbonate"},{"id":"c","text":"Secrete H⁺ ions"},{"id":"d","text":"Increase respiratory rate"}],"answerId":"b","explanation":"The kidneys first reabsorb nearly all filtered bicarbonate to maintain acid-base balance before excreting fixed acids.","kind":"integration","linkedModuleIds":["tubular-reabsorption-secretion"],"origin":"ai"}],"asthma-bronchiectasis-pathology":[{"id":"asthma-bronchiectasis-pathology~ai-0","moduleId":"asthma-bronchiectasis-pathology","stem":"What is the primary mechanism underlying asthma pathology?","options":[{"id":"a","text":"Th1-mediated inflammation"},{"id":"b","text":"Th2-mediated inflammation"},{"id":"c","text":"Neutrophilic inflammation"},{"id":"d","text":"Autoimmune destruction"}],"answerId":"b","explanation":"Asthma is primarily characterized by Th2-mediated inflammation, leading to eosinophilic infiltration and airway hyperresponsiveness.","kind":"recall","origin":"ai"},{"id":"asthma-bronchiectasis-pathology~ai-1","moduleId":"asthma-bronchiectasis-pathology","stem":"Which of the following findings is most characteristic of bronchiectasis?","options":[{"id":"a","text":"Curschmann spirals"},{"id":"b","text":"Clubbing"},{"id":"c","text":"Charcot-Leyden crystals"},{"id":"d","text":"Reversible airflow obstruction"}],"answerId":"b","explanation":"Clubbing is a classic finding in bronchiectasis due to chronic lung disease, while Curschmann spirals and Charcot-Leyden crystals are associated with asthma.","kind":"recall","origin":"ai"},{"id":"asthma-bronchiectasis-pathology~ai-2","moduleId":"asthma-bronchiectasis-pathology","stem":"What does a 'silent chest' indicate in a patient with asthma?","options":[{"id":"a","text":"Improvement of airflow"},{"id":"b","text":"Severe obstruction"},{"id":"c","text":"Normal lung function"},{"id":"d","text":"Effective bronchodilation"}],"answerId":"b","explanation":"A 'silent chest' indicates severe obstruction and is a sign of status asthmaticus, not improvement.","kind":"trap","origin":"ai"},{"id":"asthma-bronchiectasis-pathology~ai-3","moduleId":"asthma-bronchiectasis-pathology","stem":"Which of the following is a common trigger for asthma exacerbations?","options":[{"id":"a","text":"Cold air"},{"id":"b","text":"High humidity"},{"id":"c","text":"Warm air"},{"id":"d","text":"Low pollen counts"}],"answerId":"a","explanation":"Cold air is a well-known trigger for asthma exacerbations, leading to bronchoconstriction.","kind":"recall","origin":"ai"},{"id":"asthma-bronchiectasis-pathology~ai-4","moduleId":"asthma-bronchiectasis-pathology","stem":"In a patient with cystic fibrosis, which of the following findings is most likely to be present?","options":[{"id":"a","text":"Reversible airflow obstruction"},{"id":"b","text":"Clubbing"},{"id":"c","text":"Normal sputum production"},{"id":"d","text":"Curschmann spirals"}],"answerId":"b","explanation":"Clubbing is commonly seen in cystic fibrosis due to chronic lung disease and bronchiectasis.","kind":"integration","linkedModuleIds":["cystic-fibrosis"],"origin":"ai"},{"id":"asthma-bronchiectasis-pathology~ai-5","moduleId":"asthma-bronchiectasis-pathology","stem":"Which of the following findings would be expected in a patient with status asthmaticus?","options":[{"id":"a","text":"Increased wheezing"},{"id":"b","text":"Decreased FEV₁"},{"id":"c","text":"Normal chest X-ray"},{"id":"d","text":"Increased peak flow rate"}],"answerId":"b","explanation":"In status asthmaticus, FEV₁ is decreased due to severe airflow obstruction.","kind":"clinical","origin":"ai"},{"id":"asthma-bronchiectasis-pathology~ai-6","moduleId":"asthma-bronchiectasis-pathology","stem":"How does bronchiectasis differ from asthma in terms of underlying pathology?","options":[{"id":"a","text":"Bronchiectasis is caused by allergic reactions"},{"id":"b","text":"Asthma involves permanent airway damage"},{"id":"c","text":"Bronchiectasis results from chronic infection and inflammation"},{"id":"d","text":"Asthma is characterized by irreversible airflow obstruction"}],"answerId":"c","explanation":"Bronchiectasis is primarily caused by a cycle of chronic infection and inflammation leading to permanent airway damage, unlike asthma.","kind":"integration","linkedModuleIds":["copd-emphysema-chronic-bronchitis"],"origin":"ai"}],"hypersensitivity-eosinophilic-lung-disease":[{"id":"hypersensitivity-eosinophilic-lung-disease~ai-0","moduleId":"hypersensitivity-eosinophilic-lung-disease","stem":"What is the primary immune mechanism involved in hypersensitivity pneumonitis?","options":[{"id":"a","text":"Type I hypersensitivity"},{"id":"b","text":"Type II hypersensitivity"},{"id":"c","text":"Type III and IV hypersensitivity"},{"id":"d","text":"Type V hypersensitivity"}],"answerId":"c","explanation":"Hypersensitivity pneumonitis is primarily mediated by both type III and IV hypersensitivity reactions to inhaled organic antigens.","kind":"mechanism","origin":"ai"},{"id":"hypersensitivity-eosinophilic-lung-disease~ai-1","moduleId":"hypersensitivity-eosinophilic-lung-disease","stem":"A farmer presents with flu-like symptoms and cough hours after exposure to mouldy hay. What is the most likely diagnosis?","options":[{"id":"a","text":"Chronic bronchitis"},{"id":"b","text":"Hypersensitivity pneumonitis"},{"id":"c","text":"Asthma exacerbation"},{"id":"d","text":"Pneumoconiosis"}],"answerId":"b","explanation":"The acute onset of flu-like symptoms following exposure to mouldy hay is characteristic of hypersensitivity pneumonitis.","kind":"clinical","origin":"ai"},{"id":"hypersensitivity-eosinophilic-lung-disease~ai-2","moduleId":"hypersensitivity-eosinophilic-lung-disease","stem":"Which histological finding is most characteristic of hypersensitivity pneumonitis?","options":[{"id":"a","text":"Non-caseating granulomas"},{"id":"b","text":"Eosinophilic infiltrates"},{"id":"c","text":"Neutrophilic infiltration"},{"id":"d","text":"Fibrotic changes"}],"answerId":"a","explanation":"Hypersensitivity pneumonitis is characterized by bronchiolocentric lymphocytic inflammation and loose, poorly-formed non-caseating granulomas.","kind":"recall","origin":"ai"},{"id":"hypersensitivity-eosinophilic-lung-disease~ai-3","moduleId":"hypersensitivity-eosinophilic-lung-disease","stem":"What distinguishes hypersensitivity pneumonitis from pneumoconiosis?","options":[{"id":"a","text":"Both are caused by organic antigens"},{"id":"b","text":"HP is reversible with antigen avoidance"},{"id":"c","text":"Both involve eosinophilic inflammation"},{"id":"d","text":"HP is always chronic"}],"answerId":"b","explanation":"Hypersensitivity pneumonitis is an immune reaction to inhaled organic antigens and is often reversible with antigen avoidance, unlike pneumoconiosis which is caused by inorganic dusts and is irreversible.","kind":"trap","origin":"ai"},{"id":"hypersensitivity-eosinophilic-lung-disease~ai-4","moduleId":"hypersensitivity-eosinophilic-lung-disease","stem":"A patient with asthma presents with eosinophilia and central bronchiectasis. What is the most likely diagnosis?","options":[{"id":"a","text":"Churg–Strauss syndrome"},{"id":"b","text":"Hypersensitivity pneumonitis"},{"id":"c","text":"Allergic bronchopulmonary aspergillosis"},{"id":"d","text":"Eosinophilic granulomatosis"}],"answerId":"c","explanation":"The combination of asthma, eosinophilia, and central bronchiectasis is characteristic of allergic bronchopulmonary aspergillosis (ABPA).","kind":"clinical","origin":"ai"},{"id":"hypersensitivity-eosinophilic-lung-disease~ai-5","moduleId":"hypersensitivity-eosinophilic-lung-disease","stem":"Which pulmonary function test finding is expected in hypersensitivity pneumonitis?","options":[{"id":"a","text":"Increased FEV1/FVC ratio"},{"id":"b","text":"Decreased DLCO"},{"id":"c","text":"Increased total lung capacity"},{"id":"d","text":"Normal lung volumes"}],"answerId":"b","explanation":"Hypersensitivity pneumonitis typically presents as a restrictive lung disease with decreased DLCO due to impaired gas exchange.","kind":"integration","linkedModuleIds":["pulmonary-function-tests-interpretation"],"origin":"ai"},{"id":"hypersensitivity-eosinophilic-lung-disease~ai-6","moduleId":"hypersensitivity-eosinophilic-lung-disease","stem":"In a patient with Löffler syndrome, which of the following is the most likely underlying cause?","options":[{"id":"a","text":"Chronic bacterial infection"},{"id":"b","text":"Parasitic larval migration"},{"id":"c","text":"Allergic reaction to fungi"},{"id":"d","text":"Viral pneumonia"}],"answerId":"b","explanation":"Löffler syndrome is characterized by transient migratory infiltrates due to parasitic larval migration, leading to eosinophilia.","kind":"integration","linkedModuleIds":["parasitic-lung-infections"],"origin":"ai"}],"mucolytics-cough-pharmacology":[{"id":"mucolytics-cough-pharmacology~ai-0","moduleId":"mucolytics-cough-pharmacology","stem":"Which drug is indicated for a dry, distressing cough?","options":[{"id":"a","text":"Dextromethorphan"},{"id":"b","text":"Guaifenesin"},{"id":"c","text":"N-acetylcysteine"},{"id":"d","text":"Bromhexine"}],"answerId":"a","explanation":"Dextromethorphan is a central, non-opioid antitussive used to suppress a dry cough.","kind":"recall","origin":"ai"},{"id":"mucolytics-cough-pharmacology~ai-1","moduleId":"mucolytics-cough-pharmacology","stem":"What is the primary mechanism of action of N-acetylcysteine as a mucolytic?","options":[{"id":"a","text":"Inhibition of cough reflex"},{"id":"b","text":"Disulfide bond cleavage in mucus"},{"id":"c","text":"Increased mucus secretion"},{"id":"d","text":"Hydration of respiratory epithelium"}],"answerId":"b","explanation":"N-acetylcysteine cleaves disulfide bonds in mucus, reducing its viscosity and aiding clearance.","kind":"mechanism","origin":"ai"},{"id":"mucolytics-cough-pharmacology~ai-2","moduleId":"mucolytics-cough-pharmacology","stem":"A patient presents with a productive cough due to a respiratory infection. What is the best management?","options":[{"id":"a","text":"Administer dextromethorphan"},{"id":"b","text":"Provide guaifenesin"},{"id":"c","text":"Prescribe codeine"},{"id":"d","text":"Use an inhaled corticosteroid"}],"answerId":"b","explanation":"Guaifenesin is an expectorant that helps to loosen mucus and is appropriate for a productive cough.","kind":"clinical","origin":"ai"},{"id":"mucolytics-cough-pharmacology~ai-3","moduleId":"mucolytics-cough-pharmacology","stem":"Which of the following is a potential side effect of codeine when used as an antitussive?","options":[{"id":"a","text":"Increased mucus production"},{"id":"b","text":"Sedation"},{"id":"c","text":"Bronchospasm"},{"id":"d","text":"Increased cough reflex"}],"answerId":"b","explanation":"Codeine, being an opioid, can cause sedation as a side effect.","kind":"recall","origin":"ai"},{"id":"mucolytics-cough-pharmacology~ai-4","moduleId":"mucolytics-cough-pharmacology","stem":"Why should a productive cough not be suppressed?","options":[{"id":"a","text":"It can lead to increased coughing"},{"id":"b","text":"It may worsen infection by trapping secretions"},{"id":"c","text":"It causes excessive mucus production"},{"id":"d","text":"It is often associated with asthma"}],"answerId":"b","explanation":"Suppressing a productive cough can trap secretions, worsening infection and hindering clearance.","kind":"trap","origin":"ai"},{"id":"mucolytics-cough-pharmacology~ai-5","moduleId":"mucolytics-cough-pharmacology","stem":"N-acetylcysteine is also used as an antidote for which condition?","options":[{"id":"a","text":"Asthma exacerbation"},{"id":"b","text":"Cystic fibrosis"},{"id":"c","text":"Paracetamol overdose"},{"id":"d","text":"Chronic bronchitis"}],"answerId":"c","explanation":"N-acetylcysteine replenishes glutathione and is the antidote for paracetamol overdose.","kind":"recall","origin":"ai"},{"id":"mucolytics-cough-pharmacology~ai-6","moduleId":"mucolytics-cough-pharmacology","stem":"In cystic fibrosis, which drug class would be most beneficial for managing thick mucus?","options":[{"id":"a","text":"Antitussives"},{"id":"b","text":"Expectorants"},{"id":"c","text":"Mucolytics"},{"id":"d","text":"Bronchodilators"}],"answerId":"c","explanation":"Mucolytics like N-acetylcysteine are beneficial in cystic fibrosis for breaking down thick mucus.","kind":"integration","linkedModuleIds":["cystic-fibrosis"],"origin":"ai"},{"id":"mucolytics-cough-pharmacology~ai-7","moduleId":"mucolytics-cough-pharmacology","stem":"Which of the following drugs is commonly used in asthma management and may also help with cough?","options":[{"id":"a","text":"Dextromethorphan"},{"id":"b","text":"Guaifenesin"},{"id":"c","text":"Albuterol"},{"id":"d","text":"N-acetylcysteine"}],"answerId":"c","explanation":"Albuterol is a bronchodilator used in asthma that can also relieve cough associated with bronchospasm.","kind":"integration","linkedModuleIds":["asthma-copd-pharmacology"],"origin":"ai"}],"hospital-aspiration-pneumonia-abscess":[{"id":"hospital-aspiration-pneumonia-abscess~ai-0","moduleId":"hospital-aspiration-pneumonia-abscess","stem":"What is the most common organism associated with aspiration pneumonia?","options":[{"id":"a","text":"Staphylococcus aureus"},{"id":"b","text":"Klebsiella pneumoniae"},{"id":"c","text":"Anaerobes"},{"id":"d","text":"Pseudomonas aeruginosa"}],"answerId":"c","explanation":"Anaerobes are the most common organisms found in aspiration pneumonia due to their prevalence in oropharyngeal flora.","kind":"recall","origin":"ai"},{"id":"hospital-aspiration-pneumonia-abscess~ai-1","moduleId":"hospital-aspiration-pneumonia-abscess","stem":"Which lung segment is most commonly affected in aspiration pneumonia?","options":[{"id":"a","text":"Left upper lobe"},{"id":"b","text":"Right lower lobe"},{"id":"c","text":"Right upper lobe"},{"id":"d","text":"Left lower lobe"}],"answerId":"b","explanation":"The right lower lobe is most commonly affected due to the anatomy of the right main bronchus.","kind":"recall","origin":"ai"},{"id":"hospital-aspiration-pneumonia-abscess~ai-2","moduleId":"hospital-aspiration-pneumonia-abscess","stem":"A patient presents with a lung abscess and foul-smelling sputum. What is the likely cause?","options":[{"id":"a","text":"Klebsiella pneumoniae"},{"id":"b","text":"Staphylococcus aureus"},{"id":"c","text":"Anaerobic bacteria"},{"id":"d","text":"Pseudomonas aeruginosa"}],"answerId":"c","explanation":"Lung abscesses associated with foul-smelling sputum are typically caused by anaerobic bacteria from the oral cavity.","kind":"clinical","origin":"ai"},{"id":"hospital-aspiration-pneumonia-abscess~ai-3","moduleId":"hospital-aspiration-pneumonia-abscess","stem":"What pleural fluid characteristics are indicative of empyema?","options":[{"id":"a","text":"High glucose, low pH"},{"id":"b","text":"Low glucose, low pH"},{"id":"c","text":"High glucose, high LDH"},{"id":"d","text":"Low glucose, high pH"}],"answerId":"b","explanation":"Empyema is characterized by low glucose, low pH, and high LDH in the pleural fluid.","kind":"recall","origin":"ai"},{"id":"hospital-aspiration-pneumonia-abscess~ai-4","moduleId":"hospital-aspiration-pneumonia-abscess","stem":"A patient with poor dentition develops a lung abscess. What is the most likely organism involved?","options":[{"id":"a","text":"Klebsiella pneumoniae"},{"id":"b","text":"Staphylococcus aureus"},{"id":"c","text":"Fusobacterium"},{"id":"d","text":"Pseudomonas aeruginosa"}],"answerId":"c","explanation":"Fusobacterium and other anaerobes from the oral cavity are commonly associated with lung abscesses in patients with poor dental hygiene.","kind":"clinical","origin":"ai"},{"id":"hospital-aspiration-pneumonia-abscess~ai-5","moduleId":"hospital-aspiration-pneumonia-abscess","stem":"How does intubation contribute to hospital-acquired pneumonia?","options":[{"id":"a","text":"By increasing airway resistance"},{"id":"b","text":"By bypassing normal airway defenses"},{"id":"c","text":"By decreasing lung compliance"},{"id":"d","text":"By promoting anaerobic conditions"}],"answerId":"b","explanation":"Intubation bypasses normal airway defenses, allowing for the colonization of resistant organisms and leading to hospital-acquired pneumonia.","kind":"mechanism","origin":"ai"},{"id":"hospital-aspiration-pneumonia-abscess~ai-6","moduleId":"hospital-aspiration-pneumonia-abscess","stem":"In a patient with aspiration pneumonia, which finding would most likely be observed on a chest X-ray?","options":[{"id":"a","text":"Left upper lobe consolidation"},{"id":"b","text":"Right lower lobe infiltrate"},{"id":"c","text":"Bilateral pleural effusions"},{"id":"d","text":"Right upper lobe cavitation"}],"answerId":"b","explanation":"Aspiration pneumonia typically presents with right lower lobe infiltrates due to the anatomical predisposition of the right main bronchus.","kind":"integration","linkedModuleIds":["trachea-bronchi-lungs"],"origin":"ai"},{"id":"hospital-aspiration-pneumonia-abscess~ai-7","moduleId":"hospital-aspiration-pneumonia-abscess","stem":"Which antibiotic class is most appropriate for treating hospital-acquired pneumonia caused by resistant Gram-negative bacteria?","options":[{"id":"a","text":"Macrolides"},{"id":"b","text":"Cephalosporins"},{"id":"c","text":"Fluoroquinolones"},{"id":"d","text":"Penicillins"}],"answerId":"c","explanation":"Fluoroquinolones are effective against many resistant Gram-negative bacteria commonly found in hospital-acquired pneumonia.","kind":"integration","linkedModuleIds":["respiratory-tract-antibiotics"],"origin":"ai"}],"pulmonary-fibrosis-pneumoconioses":[{"id":"pulmonary-fibrosis-pneumoconioses~ai-0","moduleId":"pulmonary-fibrosis-pneumoconioses","stem":"What is the primary pathological change in idiopathic pulmonary fibrosis (IPF)?","options":[{"id":"a","text":"Alveolar wall scarring"},{"id":"b","text":"Bronchiolar inflammation"},{"id":"c","text":"Vascular congestion"},{"id":"d","text":"Pleural effusion"}],"answerId":"a","explanation":"IPF is characterized by scarring of the alveolar walls, leading to stiff lungs and restrictive lung disease.","kind":"recall","origin":"ai"},{"id":"pulmonary-fibrosis-pneumoconioses~ai-1","moduleId":"pulmonary-fibrosis-pneumoconioses","stem":"Which clinical finding is most characteristic of asbestosis?","options":[{"id":"a","text":"Upper-lobe nodules"},{"id":"b","text":"Pleural plaques"},{"id":"c","text":"Honeycomb fibrosis"},{"id":"d","text":"Eggshell calcification"}],"answerId":"c","explanation":"Asbestosis typically presents with basal, subpleural honeycomb fibrosis on imaging.","kind":"recall","origin":"ai"},{"id":"pulmonary-fibrosis-pneumoconioses~ai-2","moduleId":"pulmonary-fibrosis-pneumoconioses","stem":"What is the most common cancer associated with asbestos exposure?","options":[{"id":"a","text":"Mesothelioma"},{"id":"b","text":"Small-cell lung carcinoma"},{"id":"c","text":"Bronchogenic carcinoma"},{"id":"d","text":"Laryngeal carcinoma"}],"answerId":"c","explanation":"Bronchogenic carcinoma is more commonly associated with asbestos exposure than mesothelioma.","kind":"trap","origin":"ai"},{"id":"pulmonary-fibrosis-pneumoconioses~ai-3","moduleId":"pulmonary-fibrosis-pneumoconioses","stem":"In hypersensitivity pneumonitis, what type of inflammation is primarily observed?","options":[{"id":"a","text":"Neutrophilic"},{"id":"b","text":"Eosinophilic"},{"id":"c","text":"Lymphocytic"},{"id":"d","text":"Granulomatous"}],"answerId":"c","explanation":"Hypersensitivity pneumonitis is characterized by bronchiolocentric lymphocytic inflammation.","kind":"recall","origin":"ai"},{"id":"pulmonary-fibrosis-pneumoconioses~ai-4","moduleId":"pulmonary-fibrosis-pneumoconioses","stem":"Which pulmonary function test finding is typical in restrictive lung diseases?","options":[{"id":"a","text":"Increased FEV₁/FVC ratio"},{"id":"b","text":"Decreased FEV₁/FVC ratio"},{"id":"c","text":"Increased DLCO"},{"id":"d","text":"Normal FEV₁"}],"answerId":"a","explanation":"Restrictive lung diseases typically show a decreased FVC and TLC with a normal or increased FEV₁/FVC ratio.","kind":"mechanism","origin":"ai"},{"id":"pulmonary-fibrosis-pneumoconioses~ai-5","moduleId":"pulmonary-fibrosis-pneumoconioses","stem":"How does smoking influence the risk of lung cancer in asbestos-exposed individuals?","options":[{"id":"a","text":"Decreases risk"},{"id":"b","text":"No effect"},{"id":"c","text":"Multiplies risk"},{"id":"d","text":"Only affects mesothelioma risk"}],"answerId":"c","explanation":"Smoking multiplies the risk of bronchogenic carcinoma in individuals exposed to asbestos.","kind":"trap","origin":"ai"},{"id":"pulmonary-fibrosis-pneumoconioses~ai-6","moduleId":"pulmonary-fibrosis-pneumoconioses","stem":"What imaging finding is associated with silicosis?","options":[{"id":"a","text":"Lower lobe fibrosis"},{"id":"b","text":"Eggshell calcification of hilar nodes"},{"id":"c","text":"Pleural effusion"},{"id":"d","text":"Ground-glass opacities"}],"answerId":"b","explanation":"Silicosis is characterized by upper-lobe nodules and eggshell calcification of hilar nodes.","kind":"recall","origin":"ai"},{"id":"pulmonary-fibrosis-pneumoconioses~ai-7","moduleId":"pulmonary-fibrosis-pneumoconioses","stem":"How does the pathophysiology of hypersensitivity pneumonitis relate to pulmonary function tests?","options":[{"id":"a","text":"Increased FVC and DLCO"},{"id":"b","text":"Decreased FVC and DLCO"},{"id":"c","text":"Normal FEV₁/FVC ratio"},{"id":"d","text":"Increased TLC"}],"answerId":"b","explanation":"Chronic hypersensitivity pneumonitis leads to restrictive lung disease, resulting in decreased FVC and DLCO.","kind":"integration","linkedModuleIds":["hypersensitivity-eosinophilic-lung-disease"],"origin":"ai"},{"id":"pulmonary-fibrosis-pneumoconioses~ai-8","moduleId":"pulmonary-fibrosis-pneumoconioses","stem":"What pulmonary function test result would you expect in a patient with idiopathic pulmonary fibrosis?","options":[{"id":"a","text":"Increased FEV₁/FVC ratio"},{"id":"b","text":"Decreased DLCO"},{"id":"c","text":"Increased TLC"},{"id":"d","text":"Normal FEV₁"}],"answerId":"b","explanation":"Idiopathic pulmonary fibrosis typically results in a decreased DLCO due to impaired gas exchange.","kind":"integration","linkedModuleIds":["pulmonary-function-tests-interpretation"],"origin":"ai"}],"pulmonary-function-tests-interpretation":[{"id":"pulmonary-function-tests-interpretation~ai-0","moduleId":"pulmonary-function-tests-interpretation","stem":"What is the primary diagnostic criterion for distinguishing obstructive from restrictive lung disease in pulmonary function tests?","options":[{"id":"a","text":"FEV₁ alone"},{"id":"b","text":"FVC alone"},{"id":"c","text":"FEV₁/FVC ratio"},{"id":"d","text":"TLC alone"}],"answerId":"c","explanation":"The FEV₁/FVC ratio is crucial; a ratio <0.7 indicates obstructive disease, while a normal/high ratio with reduced FVC indicates restrictive disease.","kind":"recall","origin":"ai"},{"id":"pulmonary-function-tests-interpretation~ai-1","moduleId":"pulmonary-function-tests-interpretation","stem":"A patient shows a reduced FEV₁/FVC ratio and increased total lung capacity (TLC). Which condition is most likely?","options":[{"id":"a","text":"Asthma"},{"id":"b","text":"Pulmonary fibrosis"},{"id":"c","text":"Cystic fibrosis"},{"id":"d","text":"Obesity hypoventilation syndrome"}],"answerId":"c","explanation":"Cystic fibrosis typically presents with obstructive lung disease, characterized by a reduced FEV₁/FVC ratio and increased TLC due to air trapping.","kind":"clinical","origin":"ai"},{"id":"pulmonary-function-tests-interpretation~ai-2","moduleId":"pulmonary-function-tests-interpretation","stem":"In a patient with a restrictive pattern on pulmonary function tests, a low DLCO indicates which underlying pathology?","options":[{"id":"a","text":"Asthma"},{"id":"b","text":"Neuromuscular disease"},{"id":"c","text":"Interstitial lung disease"},{"id":"d","text":"Obesity"}],"answerId":"c","explanation":"A low DLCO in a restrictive pattern suggests damage to the alveolar-capillary membrane, commonly seen in interstitial lung disease.","kind":"mechanism","origin":"ai"},{"id":"pulmonary-function-tests-interpretation~ai-3","moduleId":"pulmonary-function-tests-interpretation","stem":"Which of the following findings on a flow-volume loop is characteristic of obstructive lung disease?","options":[{"id":"a","text":"Tall, narrow loop"},{"id":"b","text":"Concave expiratory limb"},{"id":"c","text":"Flat inspiratory limb"},{"id":"d","text":"Normal loop shape"}],"answerId":"b","explanation":"Obstructive lung disease presents with a concave shape on the expiratory limb of the flow-volume loop due to airflow limitation.","kind":"recall","origin":"ai"},{"id":"pulmonary-function-tests-interpretation~ai-4","moduleId":"pulmonary-function-tests-interpretation","stem":"A patient with asthma shows a ≥12% and 200 mL improvement in FEV₁ after bronchodilator therapy. What does this indicate?","options":[{"id":"a","text":"Fixed obstruction"},{"id":"b","text":"Reversible obstruction"},{"id":"c","text":"Restrictive lung disease"},{"id":"d","text":"Normal lung function"}],"answerId":"b","explanation":"This finding indicates reversible obstruction, which is characteristic of asthma.","kind":"clinical","origin":"ai"},{"id":"pulmonary-function-tests-interpretation~ai-5","moduleId":"pulmonary-function-tests-interpretation","stem":"Which of the following conditions would likely show a normal DLCO in a restrictive pattern?","options":[{"id":"a","text":"Interstitial lung disease"},{"id":"b","text":"Cystic fibrosis"},{"id":"c","text":"Obesity hypoventilation syndrome"},{"id":"d","text":"Pulmonary fibrosis"}],"answerId":"c","explanation":"Obesity hypoventilation syndrome typically presents with a restrictive pattern and a normal DLCO, as the alveolar-capillary membrane remains intact.","kind":"trap","origin":"ai"},{"id":"pulmonary-function-tests-interpretation~ai-6","moduleId":"pulmonary-function-tests-interpretation","stem":"How does the FEV₁/FVC ratio help differentiate between asthma and COPD?","options":[{"id":"a","text":"Asthma has a lower ratio than COPD"},{"id":"b","text":"COPD shows reversibility while asthma does not"},{"id":"c","text":"Asthma shows a higher ratio than COPD"},{"id":"d","text":"Both can have a low ratio but differ in reversibility"}],"answerId":"d","explanation":"Both asthma and COPD can present with a low FEV₁/FVC ratio, but asthma typically shows significant reversibility with bronchodilators, while COPD does not.","kind":"integration","linkedModuleIds":["asthma-bronchiectasis-pathology","copd-emphysema-chronic-bronchitis"],"origin":"ai"},{"id":"pulmonary-function-tests-interpretation~ai-7","moduleId":"pulmonary-function-tests-interpretation","stem":"In patients with COPD, which pulmonary function test result is most indicative of disease severity?","options":[{"id":"a","text":"FEV₁/FVC ratio"},{"id":"b","text":"Total lung capacity"},{"id":"c","text":"Diffusing capacity (DLCO)"},{"id":"d","text":"FVC alone"}],"answerId":"a","explanation":"The FEV₁/FVC ratio is the most critical measure in COPD, indicating the degree of airflow obstruction and disease severity.","kind":"integration","linkedModuleIds":["copd-emphysema-chronic-bronchitis"],"origin":"ai"}],"cystic-fibrosis":[{"id":"cystic-fibrosis~ai-0","moduleId":"cystic-fibrosis","stem":"What is the most common mutation associated with cystic fibrosis?","options":[{"id":"a","text":"G551D"},{"id":"b","text":"R117H"},{"id":"c","text":"ΔF508"},{"id":"d","text":"N1303K"}],"answerId":"c","explanation":"The ΔF508 mutation is the most prevalent mutation found in the CFTR gene associated with cystic fibrosis.","kind":"recall","origin":"ai"},{"id":"cystic-fibrosis~ai-1","moduleId":"cystic-fibrosis","stem":"Which organism is commonly associated with chronic lung infection in cystic fibrosis patients?","options":[{"id":"a","text":"Streptococcus pneumoniae"},{"id":"b","text":"Haemophilus influenzae"},{"id":"c","text":"Pseudomonas aeruginosa"},{"id":"d","text":"Mycobacterium tuberculosis"}],"answerId":"c","explanation":"Pseudomonas aeruginosa colonization is a hallmark of disease progression in cystic fibrosis.","kind":"recall","origin":"ai"},{"id":"cystic-fibrosis~ai-2","moduleId":"cystic-fibrosis","stem":"A 2-day-old neonate presents with bilious vomiting and abdominal distension. What is the most likely diagnosis?","options":[{"id":"a","text":"Hirschsprung disease"},{"id":"b","text":"Meconium ileus"},{"id":"c","text":"Intussusception"},{"id":"d","text":"Necrotizing enterocolitis"}],"answerId":"b","explanation":"Meconium ileus is often the first presentation of cystic fibrosis in neonates due to thick intestinal secretions.","kind":"clinical","origin":"ai"},{"id":"cystic-fibrosis~ai-3","moduleId":"cystic-fibrosis","stem":"What is the primary mechanism by which cystic fibrosis affects the pancreas?","options":[{"id":"a","text":"Increased insulin secretion"},{"id":"b","text":"Decreased bile production"},{"id":"c","text":"Obstruction of pancreatic ducts"},{"id":"d","text":"Increased pancreatic enzyme activity"}],"answerId":"c","explanation":"Thick secretions obstruct the pancreatic ducts, leading to exocrine pancreatic insufficiency.","kind":"mechanism","origin":"ai"},{"id":"cystic-fibrosis~ai-4","moduleId":"cystic-fibrosis","stem":"Which of the following findings is diagnostic for cystic fibrosis?","options":[{"id":"a","text":"Elevated serum trypsinogen"},{"id":"b","text":"Elevated sweat chloride"},{"id":"c","text":"Positive genetic test for G551D"},{"id":"d","text":"Presence of nasal polyps"}],"answerId":"b","explanation":"An elevated sweat chloride level is a key diagnostic criterion for cystic fibrosis.","kind":"recall","origin":"ai"},{"id":"cystic-fibrosis~ai-5","moduleId":"cystic-fibrosis","stem":"How does cystic fibrosis relate to fat-soluble vitamin deficiencies?","options":[{"id":"a","text":"Increased absorption of vitamins A, D, E, K"},{"id":"b","text":"Decreased bile acids in the intestine"},{"id":"c","text":"Pancreatic insufficiency leading to malabsorption"},{"id":"d","text":"Increased renal excretion of vitamins"}],"answerId":"c","explanation":"Pancreatic exocrine insufficiency in cystic fibrosis leads to malabsorption of fat-soluble vitamins A, D, E, and K.","kind":"integration","linkedModuleIds":["fat-soluble-vitamins"],"origin":"ai"},{"id":"cystic-fibrosis~ai-6","moduleId":"cystic-fibrosis","stem":"Which clinical feature of cystic fibrosis is most indicative of disease progression?","options":[{"id":"a","text":"Recurrent chest infections"},{"id":"b","text":"Salty skin"},{"id":"c","text":"Meconium ileus"},{"id":"d","text":"Pancreatic enzyme deficiency"}],"answerId":"a","explanation":"Recurrent chest infections, particularly with Pseudomonas aeruginosa, indicate worsening lung function and disease progression.","kind":"clinical","origin":"ai"},{"id":"cystic-fibrosis~ai-7","moduleId":"cystic-fibrosis","stem":"Cystic fibrosis is primarily characterized by dysfunction in which of the following systems?","options":[{"id":"a","text":"Endocrine"},{"id":"b","text":"Musculoskeletal"},{"id":"c","text":"Respiratory"},{"id":"d","text":"Nervous"}],"answerId":"c","explanation":"Cystic fibrosis is best known for its severe impact on the respiratory system, although it is a multisystem disease.","kind":"trap","origin":"ai"},{"id":"cystic-fibrosis~ai-8","moduleId":"cystic-fibrosis","stem":"How does cystic fibrosis connect with respiratory failure?","options":[{"id":"a","text":"Increased lung compliance"},{"id":"b","text":"Obstructive lung disease due to mucus"},{"id":"c","text":"Decreased pulmonary vascular resistance"},{"id":"d","text":"Increased oxygen diffusion capacity"}],"answerId":"b","explanation":"The thick mucus in cystic fibrosis leads to obstructive lung disease, which can result in respiratory failure.","kind":"integration","linkedModuleIds":["respiratory-failure-oxygen-therapy"],"origin":"ai"}],"cough-cold-allergy-drugs":[{"id":"cough-cold-allergy-drugs~ai-0","moduleId":"cough-cold-allergy-drugs","stem":"Which class of drug is primarily used to relieve nasal congestion in colds?","options":[{"id":"a","text":"Antihistamines"},{"id":"b","text":"Decongestants"},{"id":"c","text":"Expectorants"},{"id":"d","text":"Intranasal corticosteroids"}],"answerId":"b","explanation":"Decongestants are α-adrenergic agonists that reduce nasal mucosal swelling and relieve congestion.","kind":"recall","origin":"ai"},{"id":"cough-cold-allergy-drugs~ai-1","moduleId":"cough-cold-allergy-drugs","stem":"What is the primary mechanism of action of first-generation antihistamines?","options":[{"id":"a","text":"Vasoconstriction"},{"id":"b","text":"H1 receptor blockade"},{"id":"c","text":"Cough suppression"},{"id":"d","text":"Mucus thinning"}],"answerId":"b","explanation":"First-generation antihistamines block H1 receptors and can cross the blood-brain barrier, causing sedation.","kind":"mechanism","origin":"ai"},{"id":"cough-cold-allergy-drugs~ai-2","moduleId":"cough-cold-allergy-drugs","stem":"A patient develops worsening nasal congestion after using a topical decongestant for 5 days. What is the likely cause?","options":[{"id":"a","text":"Allergic rhinitis"},{"id":"b","text":"Rhinitis medicamentosa"},{"id":"c","text":"Viral infection"},{"id":"d","text":"Bacterial sinusitis"}],"answerId":"b","explanation":"Rhinitis medicamentosa occurs due to rebound congestion from prolonged use of topical decongestants.","kind":"recall","origin":"ai"},{"id":"cough-cold-allergy-drugs~ai-3","moduleId":"cough-cold-allergy-drugs","stem":"Which medication is most effective for controlling allergic rhinitis symptoms?","options":[{"id":"a","text":"Loratadine"},{"id":"b","text":"Pseudoephedrine"},{"id":"c","text":"Intranasal corticosteroids"},{"id":"d","text":"Dextromethorphan"}],"answerId":"c","explanation":"Intranasal corticosteroids are the most effective treatment for allergic rhinitis, targeting inflammation and congestion.","kind":"recall","origin":"ai"},{"id":"cough-cold-allergy-drugs~ai-4","moduleId":"cough-cold-allergy-drugs","stem":"What is the best course of action if a patient experiences rebound congestion from a nasal decongestant?","options":[{"id":"a","text":"Increase the dosage"},{"id":"b","text":"Switch to an oral antihistamine"},{"id":"c","text":"Stop the nasal spray"},{"id":"d","text":"Continue using the spray intermittently"}],"answerId":"c","explanation":"The correct approach is to stop the nasal spray to prevent worsening congestion, as continued use exacerbates the condition.","kind":"trap","origin":"ai"},{"id":"cough-cold-allergy-drugs~ai-5","moduleId":"cough-cold-allergy-drugs","stem":"Which drug class is used to thin mucus in patients with a productive cough?","options":[{"id":"a","text":"Antitussives"},{"id":"b","text":"Expectorants"},{"id":"c","text":"Antihistamines"},{"id":"d","text":"Decongestants"}],"answerId":"b","explanation":"Expectorants help to thin and clear mucus, making it easier to expel during a productive cough.","kind":"recall","origin":"ai"},{"id":"cough-cold-allergy-drugs~ai-6","moduleId":"cough-cold-allergy-drugs","stem":"How do intranasal corticosteroids help in managing allergic rhinitis?","options":[{"id":"a","text":"By blocking H1 receptors"},{"id":"b","text":"By causing vasoconstriction"},{"id":"c","text":"By reducing inflammation"},{"id":"d","text":"By suppressing cough reflex"}],"answerId":"c","explanation":"Intranasal corticosteroids reduce inflammation in the nasal mucosa, providing effective relief from allergic symptoms.","kind":"mechanism","origin":"ai"},{"id":"cough-cold-allergy-drugs~ai-7","moduleId":"cough-cold-allergy-drugs","stem":"A patient with asthma is prescribed an intranasal corticosteroid for allergic rhinitis. What is the primary reason for this choice?","options":[{"id":"a","text":"To suppress the cough reflex"},{"id":"b","text":"To reduce nasal inflammation"},{"id":"c","text":"To promote mucus clearance"},{"id":"d","text":"To alleviate throat irritation"}],"answerId":"b","explanation":"Intranasal corticosteroids are effective in reducing nasal inflammation associated with allergic rhinitis, which can benefit asthma management.","kind":"integration","linkedModuleIds":["asthma-copd-pharmacology"],"origin":"ai"},{"id":"cough-cold-allergy-drugs~ai-8","moduleId":"cough-cold-allergy-drugs","stem":"Which drug would be contraindicated in a patient with hypertension seeking relief from nasal congestion?","options":[{"id":"a","text":"Loratadine"},{"id":"b","text":"Oxymetazoline"},{"id":"c","text":"Guaifenesin"},{"id":"d","text":"N-acetylcysteine"}],"answerId":"b","explanation":"Oxymetazoline is a topical decongestant that can raise blood pressure, making it contraindicated in hypertensive patients.","kind":"trap","origin":"ai"}],"copd-emphysema-chronic-bronchitis":[{"id":"copd-emphysema-chronic-bronchitis~ai-0","moduleId":"copd-emphysema-chronic-bronchitis","stem":"What is the primary pathological change in emphysema?","options":[{"id":"a","text":"Mucous gland hyperplasia"},{"id":"b","text":"Destruction of alveolar walls"},{"id":"c","text":"Bronchial smooth muscle hypertrophy"},{"id":"d","text":"Increased airway resistance"}],"answerId":"b","explanation":"Emphysema is characterized by the permanent destruction of alveolar walls, leading to reduced elastic recoil and impaired gas exchange.","kind":"recall","origin":"ai"},{"id":"copd-emphysema-chronic-bronchitis~ai-1","moduleId":"copd-emphysema-chronic-bronchitis","stem":"Which clinical finding is most indicative of chronic bronchitis?","options":[{"id":"a","text":"Barrel chest"},{"id":"b","text":"Pursed-lip breathing"},{"id":"c","text":"Cyanosis"},{"id":"d","text":"Productive cough for ≥3 months"}],"answerId":"d","explanation":"Chronic bronchitis is defined clinically by a productive cough lasting for at least 3 months in 2 consecutive years.","kind":"clinical","origin":"ai"},{"id":"copd-emphysema-chronic-bronchitis~ai-2","moduleId":"copd-emphysema-chronic-bronchitis","stem":"In a patient with COPD, what finding would you expect on a pulmonary function test?","options":[{"id":"a","text":"FEV₁/FVC ratio > 0.7"},{"id":"b","text":"FEV₁/FVC ratio < 0.7"},{"id":"c","text":"Increased FVC"},{"id":"d","text":"Normal FEV₁"}],"answerId":"b","explanation":"COPD is characterized by a reduced FEV₁/FVC ratio (<0.7) due to fixed airflow obstruction.","kind":"recall","origin":"ai"},{"id":"copd-emphysema-chronic-bronchitis~ai-3","moduleId":"copd-emphysema-chronic-bronchitis","stem":"What is the mechanism by which smoking leads to emphysema?","options":[{"id":"a","text":"Increased mucus production"},{"id":"b","text":"Protease excess leading to alveolar destruction"},{"id":"c","text":"Bronchoconstriction"},{"id":"d","text":"Increased surfactant production"}],"answerId":"b","explanation":"Smoking causes an imbalance in the protease-antiprotease system, leading to excess protease activity and subsequent alveolar destruction.","kind":"mechanism","origin":"ai"},{"id":"copd-emphysema-chronic-bronchitis~ai-4","moduleId":"copd-emphysema-chronic-bronchitis","stem":"Which of the following is a common complication of COPD?","options":[{"id":"a","text":"Asthma exacerbation"},{"id":"b","text":"Pulmonary hypertension"},{"id":"c","text":"Bronchiectasis"},{"id":"d","text":"Pneumonia"}],"answerId":"b","explanation":"Pulmonary hypertension is a known complication of COPD due to chronic hypoxic pulmonary vasoconstriction.","kind":"recall","origin":"ai"},{"id":"copd-emphysema-chronic-bronchitis~ai-5","moduleId":"copd-emphysema-chronic-bronchitis","stem":"A young non-smoker presents with lower-lobe panacinar emphysema and liver disease. What is the likely underlying cause?","options":[{"id":"a","text":"Cystic fibrosis"},{"id":"b","text":"Alpha-1 antitrypsin deficiency"},{"id":"c","text":"Chronic bronchitis"},{"id":"d","text":"Asthma"}],"answerId":"b","explanation":"Lower-lobe panacinar emphysema in a young non-smoker is typically due to alpha-1 antitrypsin deficiency.","kind":"clinical","origin":"ai"},{"id":"copd-emphysema-chronic-bronchitis~ai-6","moduleId":"copd-emphysema-chronic-bronchitis","stem":"How does chronic hypoxia in COPD lead to cor pulmonale?","options":[{"id":"a","text":"Increased blood viscosity"},{"id":"b","text":"Pulmonary vasodilation"},{"id":"c","text":"Pulmonary vasoconstriction"},{"id":"d","text":"Decreased cardiac output"}],"answerId":"c","explanation":"Chronic hypoxia causes pulmonary vasoconstriction, leading to increased pulmonary artery pressure and cor pulmonale.","kind":"mechanism","origin":"ai"},{"id":"copd-emphysema-chronic-bronchitis~ai-7","moduleId":"copd-emphysema-chronic-bronchitis","stem":"How would you differentiate COPD from asthma using pulmonary function tests?","options":[{"id":"a","text":"COPD shows reversible obstruction"},{"id":"b","text":"Asthma shows fixed obstruction"},{"id":"c","text":"COPD shows fixed obstruction"},{"id":"d","text":"Asthma shows increased FVC"}],"answerId":"c","explanation":"COPD is characterized by fixed airflow obstruction that does not fully reverse with bronchodilators, unlike asthma.","kind":"integration","linkedModuleIds":["pulmonary-function-tests-interpretation"],"origin":"ai"},{"id":"copd-emphysema-chronic-bronchitis~ai-8","moduleId":"copd-emphysema-chronic-bronchitis","stem":"What is a key difference in the clinical presentation of COPD compared to asthma?","options":[{"id":"a","text":"COPD has a reversible component"},{"id":"b","text":"COPD presents with wheezing"},{"id":"c","text":"COPD is associated with productive cough"},{"id":"d","text":"COPD is primarily an allergic condition"}],"answerId":"c","explanation":"COPD is often associated with a productive cough, while asthma typically presents with wheezing and is more reversible.","kind":"integration","linkedModuleIds":["asthma-copd-pharmacology"],"origin":"ai"}],"fungal-lung-infections":[{"id":"fungal-lung-infections~ai-0","moduleId":"fungal-lung-infections","stem":"Which organism is primarily responsible for causing Pneumocystis jirovecii pneumonia (PCP) in HIV patients?","options":[{"id":"a","text":"Aspergillus fumigatus"},{"id":"b","text":"Pneumocystis jirovecii"},{"id":"c","text":"Cryptococcus neoformans"},{"id":"d","text":"Talaromyces marneffei"}],"answerId":"b","explanation":"Pneumocystis jirovecii is the causative agent of PCP, particularly in immunocompromised individuals such as those with HIV.","kind":"recall","origin":"ai"},{"id":"fungal-lung-infections~ai-1","moduleId":"fungal-lung-infections","stem":"What is the characteristic finding in the lungs of a patient with an aspergilloma?","options":[{"id":"a","text":"Ground-glass opacities"},{"id":"b","text":"Fungus ball in a cavity"},{"id":"c","text":"Nodular infiltrates"},{"id":"d","text":"Pleural effusion"}],"answerId":"b","explanation":"An aspergilloma is identified as a fungus ball that typically forms in a pre-existing lung cavity.","kind":"recall","origin":"ai"},{"id":"fungal-lung-infections~ai-2","moduleId":"fungal-lung-infections","stem":"What is the mechanism of action of co-trimoxazole in treating Pneumocystis jirovecii pneumonia?","options":[{"id":"a","text":"Inhibition of fungal cell wall synthesis"},{"id":"b","text":"Inhibition of folate synthesis"},{"id":"c","text":"Inhibition of protein synthesis"},{"id":"d","text":"Inhibition of nucleic acid synthesis"}],"answerId":"b","explanation":"Co-trimoxazole, a combination of trimethoprim and sulfamethoxazole, inhibits folate synthesis, which is crucial for the growth of Pneumocystis jirovecii.","kind":"mechanism","origin":"ai"},{"id":"fungal-lung-infections~ai-3","moduleId":"fungal-lung-infections","stem":"A patient with advanced HIV presents with dyspnea and ground-glass infiltrates on chest X-ray. What is the most likely diagnosis?","options":[{"id":"a","text":"Aspergillosis"},{"id":"b","text":"Cryptococcosis"},{"id":"c","text":"Pneumocystis jirovecii pneumonia"},{"id":"d","text":"Talaromyces marneffei infection"}],"answerId":"c","explanation":"The presentation is classic for Pneumocystis jirovecii pneumonia, especially in patients with CD4 counts below 200.","kind":"clinical","origin":"ai"},{"id":"fungal-lung-infections~ai-4","moduleId":"fungal-lung-infections","stem":"Which of the following is a distinguishing feature of invasive aspergillosis?","options":[{"id":"a","text":"Broad-based budding yeast"},{"id":"b","text":"Acute-angle septate hyphae"},{"id":"c","text":"Cystic lesions on imaging"},{"id":"d","text":"Thick capsule"}],"answerId":"b","explanation":"Invasive aspergillosis is characterized by the presence of acute-angle septate hyphae, which are indicative of this angioinvasive infection.","kind":"trap","origin":"ai"},{"id":"fungal-lung-infections~ai-5","moduleId":"fungal-lung-infections","stem":"How does Cryptococcus neoformans typically present in an HIV-infected patient?","options":[{"id":"a","text":"Pneumonia with pleural effusion"},{"id":"b","text":"Meningitis with a thick capsule"},{"id":"c","text":"Skin lesions with broad-based budding"},{"id":"d","text":"Cavitary lung disease"}],"answerId":"b","explanation":"Cryptococcus neoformans often causes meningitis in HIV patients, and it is identified by its thick capsule and narrow-based budding.","kind":"clinical","origin":"ai"},{"id":"fungal-lung-infections~ai-6","moduleId":"fungal-lung-infections","stem":"How does the presentation of Talaromyces marneffei infection differ from that of tuberculosis in an HIV patient?","options":[{"id":"a","text":"It causes a thick capsule"},{"id":"b","text":"It presents with broad-based budding"},{"id":"c","text":"It is associated with a CD4 count above 200"},{"id":"d","text":"It can cause disseminated disease with skin lesions"}],"answerId":"d","explanation":"Talaromyces marneffei can cause disseminated disease and skin lesions in HIV patients, which can be similar to tuberculosis but with distinct features.","kind":"integration","linkedModuleIds":["tuberculosis-clinical-latent-mdr"],"origin":"ai"},{"id":"fungal-lung-infections~ai-7","moduleId":"fungal-lung-infections","stem":"What common feature do Pneumocystis jirovecii pneumonia and Cryptococcus neoformans infections share in HIV patients?","options":[{"id":"a","text":"Both cause pneumonia with pleural effusion"},{"id":"b","text":"Both are opportunistic infections in immunocompromised hosts"},{"id":"c","text":"Both present with broad-based budding"},{"id":"d","text":"Both are treated with amphotericin B"}],"answerId":"b","explanation":"Both Pneumocystis jirovecii pneumonia and Cryptococcus neoformans infections are opportunistic infections that occur in immunocompromised individuals, particularly those with HIV.","kind":"integration","linkedModuleIds":["cryptococcus-malassezia"],"origin":"ai"}],"sarcoidosis-granulomatous-lung":[{"id":"sarcoidosis-granulomatous-lung~ai-0","moduleId":"sarcoidosis-granulomatous-lung","stem":"What is the characteristic histological finding in sarcoidosis?","options":[{"id":"a","text":"Caseating granulomas"},{"id":"b","text":"Non-caseating epithelioid granulomas"},{"id":"c","text":"Lymphocytic infiltration"},{"id":"d","text":"Fibrinous necrosis"}],"answerId":"b","explanation":"Sarcoidosis is defined by the presence of non-caseating epithelioid granulomas.","kind":"recall","origin":"ai"},{"id":"sarcoidosis-granulomatous-lung~ai-1","moduleId":"sarcoidosis-granulomatous-lung","stem":"Which of the following is a common extrapulmonary manifestation of sarcoidosis?","options":[{"id":"a","text":"Hemoptysis"},{"id":"b","text":"Erythema nodosum"},{"id":"c","text":"Cough"},{"id":"d","text":"Pleural effusion"}],"answerId":"b","explanation":"Erythema nodosum is a recognized extrapulmonary manifestation of sarcoidosis.","kind":"recall","origin":"ai"},{"id":"sarcoidosis-granulomatous-lung~ai-2","moduleId":"sarcoidosis-granulomatous-lung","stem":"What mechanism leads to hypercalcemia in sarcoidosis?","options":[{"id":"a","text":"Increased parathyroid hormone secretion"},{"id":"b","text":"Increased vitamin D production by granulomas"},{"id":"c","text":"Decreased renal calcium reabsorption"},{"id":"d","text":"Increased intestinal calcium absorption"}],"answerId":"b","explanation":"Granulomas in sarcoidosis produce 1α-hydroxylase, leading to increased calcitriol and hypercalcemia.","kind":"mechanism","origin":"ai"},{"id":"sarcoidosis-granulomatous-lung~ai-3","moduleId":"sarcoidosis-granulomatous-lung","stem":"A patient presents with bilateral hilar lymphadenopathy and elevated serum ACE levels. What is the most appropriate next step?","options":[{"id":"a","text":"Start corticosteroids"},{"id":"b","text":"Order a CT scan"},{"id":"c","text":"Perform a bronchoscopy with biopsy"},{"id":"d","text":"Initiate anti-tuberculosis therapy"}],"answerId":"c","explanation":"A bronchoscopy with biopsy is needed to confirm the diagnosis and exclude tuberculosis before treatment.","kind":"clinical","origin":"ai"},{"id":"sarcoidosis-granulomatous-lung~ai-4","moduleId":"sarcoidosis-granulomatous-lung","stem":"Which of the following findings would suggest a diagnosis of tuberculosis rather than sarcoidosis?","options":[{"id":"a","text":"Non-caseating granulomas"},{"id":"b","text":"Bilateral hilar lymphadenopathy"},{"id":"c","text":"Caseating granulomas"},{"id":"d","text":"Increased CD4:CD8 ratio in BAL"}],"answerId":"c","explanation":"Caseating granulomas are indicative of tuberculosis, while sarcoidosis features non-caseating granulomas.","kind":"trap","origin":"ai"},{"id":"sarcoidosis-granulomatous-lung~ai-5","moduleId":"sarcoidosis-granulomatous-lung","stem":"How does sarcoidosis affect calcium metabolism?","options":[{"id":"a","text":"Increased renal reabsorption of calcium"},{"id":"b","text":"Decreased intestinal absorption of calcium"},{"id":"c","text":"Increased production of calcitriol by macrophages"},{"id":"d","text":"Decreased secretion of parathyroid hormone"}],"answerId":"c","explanation":"Macrophages in sarcoidosis produce calcitriol, leading to increased calcium absorption and hypercalcemia.","kind":"mechanism","origin":"ai"},{"id":"sarcoidosis-granulomatous-lung~ai-6","moduleId":"sarcoidosis-granulomatous-lung","stem":"In a patient with sarcoidosis, what is the significance of an increased CD4:CD8 ratio in bronchoalveolar lavage?","options":[{"id":"a","text":"Indicates bacterial infection"},{"id":"b","text":"Suggests a Th1-driven immune response"},{"id":"c","text":"Confirms the diagnosis of tuberculosis"},{"id":"d","text":"Indicates a poor prognosis"}],"answerId":"b","explanation":"An increased CD4:CD8 ratio indicates a Th1-driven immune response typical of sarcoidosis.","kind":"recall","origin":"ai"},{"id":"sarcoidosis-granulomatous-lung~ai-7","moduleId":"sarcoidosis-granulomatous-lung","stem":"How does the management of sarcoidosis differ from that of tuberculosis?","options":[{"id":"a","text":"Both require immediate corticosteroid therapy"},{"id":"b","text":"Sarcoidosis requires immunosuppression, tuberculosis does not"},{"id":"c","text":"Tuberculosis requires antibiotics, sarcoidosis may require steroids"},{"id":"d","text":"Both conditions are treated with antibiotics"}],"answerId":"c","explanation":"Tuberculosis requires antibiotics, while sarcoidosis may require steroids only if there is organ involvement.","kind":"integration","linkedModuleIds":["anti-tuberculosis-drugs"],"origin":"ai"},{"id":"sarcoidosis-granulomatous-lung~ai-8","moduleId":"sarcoidosis-granulomatous-lung","stem":"Which of the following features would help differentiate sarcoidosis from chronic granulomatous inflammation?","options":[{"id":"a","text":"Presence of caseating granulomas"},{"id":"b","text":"Non-caseating granulomas"},{"id":"c","text":"Elevated serum calcium"},{"id":"d","text":"Löfgren syndrome"}],"answerId":"a","explanation":"The presence of caseating granulomas is a key differentiator for tuberculosis, while sarcoidosis has non-caseating granulomas.","kind":"integration","linkedModuleIds":["chronic-inflammation-granuloma"],"origin":"ai"}],"community-acquired-pneumonia":[{"id":"community-acquired-pneumonia~ai-0","moduleId":"community-acquired-pneumonia","stem":"Which organism is the most common cause of typical community-acquired pneumonia?","options":[{"id":"a","text":"Klebsiella pneumoniae"},{"id":"b","text":"Staphylococcus aureus"},{"id":"c","text":"Streptococcus pneumoniae"},{"id":"d","text":"Mycoplasma pneumoniae"}],"answerId":"c","explanation":"Streptococcus pneumoniae is the most common cause of typical community-acquired pneumonia, presenting with abrupt onset and lobar consolidation.","kind":"recall","origin":"ai"},{"id":"community-acquired-pneumonia~ai-1","moduleId":"community-acquired-pneumonia","stem":"What is the primary mechanism of action of macrolides in treating atypical pneumonia?","options":[{"id":"a","text":"Inhibition of cell wall synthesis"},{"id":"b","text":"Inhibition of protein synthesis"},{"id":"c","text":"Inhibition of nucleic acid synthesis"},{"id":"d","text":"Inhibition of folate synthesis"}],"answerId":"b","explanation":"Macrolides inhibit bacterial protein synthesis by binding to the 50S ribosomal subunit, making them effective against atypical organisms.","kind":"mechanism","origin":"ai"},{"id":"community-acquired-pneumonia~ai-2","moduleId":"community-acquired-pneumonia","stem":"A 25-year-old presents with a dry cough, malaise, and cold agglutinins. Which organism is most likely responsible?","options":[{"id":"a","text":"Legionella pneumophila"},{"id":"b","text":"Mycoplasma pneumoniae"},{"id":"c","text":"Streptococcus pneumoniae"},{"id":"d","text":"Chlamydophila pneumoniae"}],"answerId":"b","explanation":"These symptoms are characteristic of Mycoplasma pneumoniae, which often presents with atypical pneumonia in young adults.","kind":"clinical","origin":"ai"},{"id":"community-acquired-pneumonia~ai-3","moduleId":"community-acquired-pneumonia","stem":"What is a key clinical finding in pneumonia caused by Klebsiella pneumoniae?","options":[{"id":"a","text":"Rusty sputum"},{"id":"b","text":"Cavitating lesions"},{"id":"c","text":"Dry cough"},{"id":"d","text":"Pleuritic pain"}],"answerId":"b","explanation":"Klebsiella pneumoniae is associated with upper-lobe cavitating pneumonia and thick 'currant-jelly' sputum.","kind":"recall","origin":"ai"},{"id":"community-acquired-pneumonia~ai-4","moduleId":"community-acquired-pneumonia","stem":"Which of the following statements about empiric therapy for community-acquired pneumonia is true?","options":[{"id":"a","text":"A β-lactam alone is sufficient for all cases."},{"id":"b","text":"Atypical organisms are covered by β-lactams."},{"id":"c","text":"Combination therapy is often required for atypical coverage."},{"id":"d","text":"Macrolides are ineffective against typical organisms."}],"answerId":"c","explanation":"Empiric therapy for community-acquired pneumonia often requires combination therapy to cover atypical organisms, which are resistant to β-lactams.","kind":"trap","origin":"ai"},{"id":"community-acquired-pneumonia~ai-5","moduleId":"community-acquired-pneumonia","stem":"A patient with pneumonia presents with hyponatraemia and gastrointestinal symptoms. Which organism is most likely responsible?","options":[{"id":"a","text":"Streptococcus pneumoniae"},{"id":"b","text":"Mycoplasma pneumoniae"},{"id":"c","text":"Legionella pneumophila"},{"id":"d","text":"Klebsiella pneumoniae"}],"answerId":"c","explanation":"Legionella pneumophila is associated with pneumonia presenting with hyponatraemia and gastrointestinal symptoms.","kind":"clinical","origin":"ai"},{"id":"community-acquired-pneumonia~ai-6","moduleId":"community-acquired-pneumonia","stem":"How does the treatment of Mycoplasma pneumoniae relate to the treatment of community-acquired pneumonia?","options":[{"id":"a","text":"Both require β-lactams exclusively."},{"id":"b","text":"Both require macrolides for atypical coverage."},{"id":"c","text":"Both are treated with respiratory fluoroquinolones only."},{"id":"d","text":"Both require hospitalization for treatment."}],"answerId":"b","explanation":"Mycoplasma pneumoniae is an atypical organism, and its treatment overlaps with the atypical coverage required in community-acquired pneumonia.","kind":"integration","linkedModuleIds":["mycoplasma-ureaplasma"],"origin":"ai"},{"id":"community-acquired-pneumonia~ai-7","moduleId":"community-acquired-pneumonia","stem":"Which of the following best connects the management of community-acquired pneumonia with the management of COPD?","options":[{"id":"a","text":"Both require the same antibiotics."},{"id":"b","text":"Both conditions can present with similar symptoms."},{"id":"c","text":"Both require hospitalization for all patients."},{"id":"d","text":"Both involve the same pathogens."}],"answerId":"b","explanation":"Community-acquired pneumonia and COPD can present with overlapping respiratory symptoms, necessitating careful clinical evaluation.","kind":"integration","linkedModuleIds":["copd-emphysema-chronic-bronchitis"],"origin":"ai"}],"pulmonary-hypertension-cor-pulmonale":[{"id":"pulmonary-hypertension-cor-pulmonale~ai-0","moduleId":"pulmonary-hypertension-cor-pulmonale","stem":"What is the mean pulmonary arterial pressure that defines pulmonary hypertension?","options":[{"id":"a","text":"≥15 mmHg"},{"id":"b","text":"≥20 mmHg"},{"id":"c","text":"≥25 mmHg"},{"id":"d","text":"≥30 mmHg"}],"answerId":"b","explanation":"Pulmonary hypertension is defined as a mean pulmonary arterial pressure of ≥20–25 mmHg.","kind":"recall","origin":"ai"},{"id":"pulmonary-hypertension-cor-pulmonale~ai-1","moduleId":"pulmonary-hypertension-cor-pulmonale","stem":"Which of the following is a common cause of cor pulmonale?","options":[{"id":"a","text":"Left heart failure"},{"id":"b","text":"Pulmonary arterial hypertension"},{"id":"c","text":"Chronic obstructive pulmonary disease"},{"id":"d","text":"Acute respiratory distress syndrome"}],"answerId":"c","explanation":"Cor pulmonale is specifically right ventricular hypertrophy/failure caused by lung disease, with COPD being a common cause.","kind":"recall","origin":"ai"},{"id":"pulmonary-hypertension-cor-pulmonale~ai-2","moduleId":"pulmonary-hypertension-cor-pulmonale","stem":"What mechanism primarily leads to pulmonary hypertension in chronic lung disease?","options":[{"id":"a","text":"Increased left atrial pressure"},{"id":"b","text":"Hypoxic pulmonary vasoconstriction"},{"id":"c","text":"Increased blood volume"},{"id":"d","text":"Decreased lung compliance"}],"answerId":"b","explanation":"Hypoxic pulmonary vasoconstriction occurs in chronic lung diseases, leading to increased pulmonary vascular resistance and pulmonary hypertension.","kind":"mechanism","origin":"ai"},{"id":"pulmonary-hypertension-cor-pulmonale~ai-3","moduleId":"pulmonary-hypertension-cor-pulmonale","stem":"Which clinical finding is most indicative of cor pulmonale?","options":[{"id":"a","text":"Loud P2"},{"id":"b","text":"Bilateral crackles"},{"id":"c","text":"Cyanosis"},{"id":"d","text":"Wheezing"}],"answerId":"a","explanation":"A loud P2 is a classic sign of cor pulmonale due to increased pressure in the pulmonary artery.","kind":"recall","origin":"ai"},{"id":"pulmonary-hypertension-cor-pulmonale~ai-4","moduleId":"pulmonary-hypertension-cor-pulmonale","stem":"Cor pulmonale specifically excludes right heart failure due to which of the following?","options":[{"id":"a","text":"Pulmonary embolism"},{"id":"b","text":"Chronic bronchitis"},{"id":"c","text":"Left heart disease"},{"id":"d","text":"Interstitial lung disease"}],"answerId":"c","explanation":"Cor pulmonale is defined as right ventricular failure caused by lung disease, excluding right heart failure due to left heart disease.","kind":"trap","origin":"ai"},{"id":"pulmonary-hypertension-cor-pulmonale~ai-5","moduleId":"pulmonary-hypertension-cor-pulmonale","stem":"In patients with COPD, which mechanism contributes to the development of pulmonary hypertension?","options":[{"id":"a","text":"Increased pulmonary blood flow"},{"id":"b","text":"Hypoxic pulmonary vasoconstriction"},{"id":"c","text":"Decreased lung volume"},{"id":"d","text":"Increased left ventricular output"}],"answerId":"b","explanation":"In COPD, hypoxic pulmonary vasoconstriction leads to increased pulmonary vascular resistance and subsequent pulmonary hypertension.","kind":"integration","linkedModuleIds":["copd-emphysema-chronic-bronchitis"],"origin":"ai"},{"id":"pulmonary-hypertension-cor-pulmonale~ai-6","moduleId":"pulmonary-hypertension-cor-pulmonale","stem":"Which finding would you expect in a patient with pulmonary hypertension secondary to obstructive sleep apnea?","options":[{"id":"a","text":"Plexiform lesions on biopsy"},{"id":"b","text":"Loud P2 on auscultation"},{"id":"c","text":"Elevated left atrial pressure"},{"id":"d","text":"Decreased pulmonary vascular resistance"}],"answerId":"b","explanation":"Patients with pulmonary hypertension due to obstructive sleep apnea may present with a loud P2 due to increased right ventricular pressure.","kind":"integration","linkedModuleIds":["obstructive-sleep-apnoea"],"origin":"ai"}],"non-small-cell-lung-carcinoma":[{"id":"non-small-cell-lung-carcinoma~ai-0","moduleId":"non-small-cell-lung-carcinoma","stem":"Which type of lung cancer is most commonly associated with peripheral gland formation and driver mutations?","options":[{"id":"a","text":"Squamous cell carcinoma"},{"id":"b","text":"Large cell carcinoma"},{"id":"c","text":"Adenocarcinoma"},{"id":"d","text":"Small cell carcinoma"}],"answerId":"c","explanation":"Adenocarcinoma is the most common lung cancer, especially in non-smokers, and is characterized by peripheral gland formation and specific driver mutations.","kind":"recall","origin":"ai"},{"id":"non-small-cell-lung-carcinoma~ai-1","moduleId":"non-small-cell-lung-carcinoma","stem":"What is the primary mechanism by which squamous cell carcinoma of the lung causes hypercalcemia?","options":[{"id":"a","text":"Bone metastases"},{"id":"b","text":"Paraneoplastic secretion of PTHrP"},{"id":"c","text":"Vitamin D dysregulation"},{"id":"d","text":"Renal failure"}],"answerId":"b","explanation":"Squamous cell carcinoma classically causes hypercalcemia through the paraneoplastic secretion of PTH-related peptide (PTHrP), not through bone metastases.","kind":"mechanism","origin":"ai"},{"id":"non-small-cell-lung-carcinoma~ai-2","moduleId":"non-small-cell-lung-carcinoma","stem":"A patient presents with a central lung mass, hypercalcemia, and cavitation on imaging. What is the most likely diagnosis?","options":[{"id":"a","text":"Adenocarcinoma"},{"id":"b","text":"Squamous cell carcinoma"},{"id":"c","text":"Large cell carcinoma"},{"id":"d","text":"Small cell carcinoma"}],"answerId":"b","explanation":"The presentation of a central mass with hypercalcemia and cavitation is characteristic of squamous cell carcinoma.","kind":"clinical","origin":"ai"},{"id":"non-small-cell-lung-carcinoma~ai-3","moduleId":"non-small-cell-lung-carcinoma","stem":"A patient with a Pancoast tumor is experiencing Horner syndrome. Which of the following findings is most likely?","options":[{"id":"a","text":"Clubbing"},{"id":"b","text":"Facial plethora"},{"id":"c","text":"Arm pain"},{"id":"d","text":"Cough"}],"answerId":"c","explanation":"Pancoast tumors invade the apex of the lung and can cause Horner syndrome along with arm pain due to invasion of the sympathetic chain and brachial plexus.","kind":"recall","origin":"ai"},{"id":"non-small-cell-lung-carcinoma~ai-4","moduleId":"non-small-cell-lung-carcinoma","stem":"Which of the following is a common paraneoplastic syndrome associated with squamous cell carcinoma of the lung?","options":[{"id":"a","text":"Cushing syndrome"},{"id":"b","text":"Hypercalcemia"},{"id":"c","text":"Syndrome of inappropriate ADH secretion"},{"id":"d","text":"Anemia"}],"answerId":"b","explanation":"Hypercalcemia due to paraneoplastic PTHrP secretion is a well-known syndrome associated with squamous cell carcinoma.","kind":"trap","origin":"ai"},{"id":"non-small-cell-lung-carcinoma~ai-5","moduleId":"non-small-cell-lung-carcinoma","stem":"In a patient with EGFR-mutant lung adenocarcinoma, which treatment option is most appropriate?","options":[{"id":"a","text":"Chemotherapy"},{"id":"b","text":"Targeted therapy with EGFR inhibitors"},{"id":"c","text":"Radiation therapy"},{"id":"d","text":"Immunotherapy"}],"answerId":"b","explanation":"EGFR-mutant lung adenocarcinoma is treated with targeted therapy using EGFR inhibitors, which are effective for this specific mutation.","kind":"integration","linkedModuleIds":["egfr-mutant-lung-adenocarcinoma"],"origin":"ai"},{"id":"non-small-cell-lung-carcinoma~ai-6","moduleId":"non-small-cell-lung-carcinoma","stem":"What imaging finding is most characteristic of a solitary pulmonary nodule in a patient with suspected lung cancer?","options":[{"id":"a","text":"Consolidation"},{"id":"b","text":"Cavitation"},{"id":"c","text":"Ground-glass opacity"},{"id":"d","text":"Well-defined borders"}],"answerId":"d","explanation":"A solitary pulmonary nodule is typically well-defined, and its characteristics on imaging help differentiate benign from malignant lesions.","kind":"integration","linkedModuleIds":["solitary-pulmonary-nodule"],"origin":"ai"}],"ards-pulmonary-hypertension-atelectasis":[{"id":"ards-pulmonary-hypertension-atelectasis~ai-0","moduleId":"ards-pulmonary-hypertension-atelectasis","stem":"What is the primary pathological hallmark of Acute Respiratory Distress Syndrome (ARDS)?","options":[{"id":"a","text":"Hyaline membranes lining alveoli"},{"id":"b","text":"Bronchial inflammation"},{"id":"c","text":"Alveolar hyperplasia"},{"id":"d","text":"Interstitial fibrosis"}],"answerId":"a","explanation":"Hyaline membranes lining the alveoli are the key pathological feature of ARDS, indicating diffuse alveolar damage.","kind":"recall","origin":"ai"},{"id":"ards-pulmonary-hypertension-atelectasis~ai-1","moduleId":"ards-pulmonary-hypertension-atelectasis","stem":"In ARDS, what causes the refractory hypoxaemia observed in patients?","options":[{"id":"a","text":"Increased dead space ventilation"},{"id":"b","text":"Decreased tidal volume"},{"id":"c","text":"Increased alveolar-capillary permeability"},{"id":"d","text":"Decreased lung compliance"}],"answerId":"c","explanation":"Increased alveolar-capillary permeability leads to pulmonary edema and impaired gas exchange, causing refractory hypoxaemia.","kind":"mechanism","origin":"ai"},{"id":"ards-pulmonary-hypertension-atelectasis~ai-2","moduleId":"ards-pulmonary-hypertension-atelectasis","stem":"A patient presents with loud P2, raised JVP, and peripheral edema. What is the most likely underlying condition?","options":[{"id":"a","text":"Acute respiratory distress syndrome"},{"id":"b","text":"Pulmonary hypertension"},{"id":"c","text":"Atelectasis"},{"id":"d","text":"Pneumonia"}],"answerId":"b","explanation":"These findings are indicative of cor pulmonale, which is caused by pulmonary hypertension.","kind":"clinical","origin":"ai"},{"id":"ards-pulmonary-hypertension-atelectasis~ai-3","moduleId":"ards-pulmonary-hypertension-atelectasis","stem":"In obstructive atelectasis, which direction does the mediastinum shift?","options":[{"id":"a","text":"Away from the collapse"},{"id":"b","text":"Toward the collapse"},{"id":"c","text":"No shift"},{"id":"d","text":"Depends on the patient position"}],"answerId":"b","explanation":"In obstructive atelectasis, the mediastinum shifts toward the collapsed lung due to volume loss.","kind":"trap","origin":"ai"},{"id":"ards-pulmonary-hypertension-atelectasis~ai-4","moduleId":"ards-pulmonary-hypertension-atelectasis","stem":"What is the mean pulmonary arterial pressure threshold for diagnosing pulmonary hypertension?","options":[{"id":"a","text":">15 mmHg"},{"id":"b","text":"≥20 mmHg"},{"id":"c","text":"≥25 mmHg"},{"id":"d","text":"≥30 mmHg"}],"answerId":"b","explanation":"Pulmonary hypertension is defined as a mean pulmonary arterial pressure of ≥20 mmHg.","kind":"recall","origin":"ai"},{"id":"ards-pulmonary-hypertension-atelectasis~ai-5","moduleId":"ards-pulmonary-hypertension-atelectasis","stem":"How does chronic hypoxia contribute to pulmonary hypertension in COPD?","options":[{"id":"a","text":"Increased lung compliance"},{"id":"b","text":"Hypoxic pulmonary vasoconstriction"},{"id":"c","text":"Decreased pulmonary vascular resistance"},{"id":"d","text":"Increased surfactant production"}],"answerId":"b","explanation":"Chronic hypoxia leads to hypoxic pulmonary vasoconstriction, which increases pulmonary arterial pressure.","kind":"mechanism","origin":"ai"},{"id":"ards-pulmonary-hypertension-atelectasis~ai-6","moduleId":"ards-pulmonary-hypertension-atelectasis","stem":"A patient with COPD develops pulmonary hypertension. Which of the following findings would you expect on a chest radiograph?","options":[{"id":"a","text":"Hyperinflated lungs"},{"id":"b","text":"Bilateral infiltrates"},{"id":"c","text":"Mediastinal shift toward the left"},{"id":"d","text":"Pleural effusion"}],"answerId":"a","explanation":"COPD typically presents with hyperinflated lungs on chest radiograph due to air trapping.","kind":"integration","linkedModuleIds":["copd-emphysema-chronic-bronchitis"],"origin":"ai"},{"id":"ards-pulmonary-hypertension-atelectasis~ai-7","moduleId":"ards-pulmonary-hypertension-atelectasis","stem":"In a patient with pneumonia leading to ARDS, which finding is most likely to be observed on a chest radiograph?","options":[{"id":"a","text":"Hyaline membranes"},{"id":"b","text":"Consolidation"},{"id":"c","text":"Pleural effusion"},{"id":"d","text":"Atelectasis"}],"answerId":"b","explanation":"Pneumonia typically presents with consolidation on chest radiograph, which can progress to ARDS.","kind":"integration","linkedModuleIds":["pneumonia-pathology-patterns"],"origin":"ai"}],"pulmonary-embolism-edema":[{"id":"pulmonary-embolism-edema~ai-0","moduleId":"pulmonary-embolism-edema","stem":"What is the most common source of a pulmonary embolism?","options":[{"id":"a","text":"Fat from long bone fracture"},{"id":"b","text":"Air from a central line"},{"id":"c","text":"Thrombus from deep veins of the leg"},{"id":"d","text":"Amniotic fluid during childbirth"}],"answerId":"c","explanation":"Pulmonary embolism is most commonly caused by thrombi that originate from deep veins in the legs or pelvis.","kind":"recall","origin":"ai"},{"id":"pulmonary-embolism-edema~ai-1","moduleId":"pulmonary-embolism-edema","stem":"Which finding is characteristic of a massive pulmonary embolism?","options":[{"id":"a","text":"Bilateral basal crackles"},{"id":"b","text":"Wedge-shaped pleural-based infarct"},{"id":"c","text":"Sudden hypotension and acute right-heart strain"},{"id":"d","text":"Frothy pink sputum"}],"answerId":"c","explanation":"Massive pulmonary embolism can lead to obstructive shock, characterized by hypotension and acute right-heart strain.","kind":"recall","origin":"ai"},{"id":"pulmonary-embolism-edema~ai-2","moduleId":"pulmonary-embolism-edema","stem":"Why is pulmonary infarction uncommon in pulmonary embolism?","options":[{"id":"a","text":"The lung has a dual blood supply"},{"id":"b","text":"All emboli cause infarction"},{"id":"c","text":"Infarction is always silent"},{"id":"d","text":"Only large emboli cause infarction"}],"answerId":"a","explanation":"Only about 10% of pulmonary embolisms result in infarction due to the lung's dual blood supply, which protects it from ischaemia.","kind":"trap","origin":"ai"},{"id":"pulmonary-embolism-edema~ai-3","moduleId":"pulmonary-embolism-edema","stem":"What is the primary mechanism behind cardiogenic pulmonary edema?","options":[{"id":"a","text":"Increased pulmonary venous pressure"},{"id":"b","text":"Increased alveolar permeability"},{"id":"c","text":"Decreased lymphatic drainage"},{"id":"d","text":"Increased blood volume"}],"answerId":"a","explanation":"Cardiogenic pulmonary edema primarily results from increased pulmonary venous pressure due to left heart failure.","kind":"mechanism","origin":"ai"},{"id":"pulmonary-embolism-edema~ai-4","moduleId":"pulmonary-embolism-edema","stem":"In a patient with suspected pulmonary embolism, which test is most useful for ruling out the condition in low-risk patients?","options":[{"id":"a","text":"CT pulmonary angiography"},{"id":"b","text":"D-dimer"},{"id":"c","text":"Chest X-ray"},{"id":"d","text":"Ventilation-perfusion scan"}],"answerId":"b","explanation":"D-dimer is a sensitive test that can help rule out pulmonary embolism in patients assessed to be at low risk.","kind":"recall","origin":"ai"},{"id":"pulmonary-embolism-edema~ai-5","moduleId":"pulmonary-embolism-edema","stem":"How does pulmonary embolism relate to the mechanisms of hemostasis and thrombosis?","options":[{"id":"a","text":"It is caused by increased platelet activation"},{"id":"b","text":"It results from venous stasis and hypercoagulability"},{"id":"c","text":"It is a consequence of arterial thrombus formation"},{"id":"d","text":"It is unrelated to coagulation factors"}],"answerId":"b","explanation":"Pulmonary embolism often arises from venous thromboembolism, which is influenced by factors such as stasis and hypercoagulability.","kind":"integration","linkedModuleIds":["hemostasis-thrombosis-embolism"],"origin":"ai"},{"id":"pulmonary-embolism-edema~ai-6","moduleId":"pulmonary-embolism-edema","stem":"What is the role of sodium balance in the management of pulmonary edema?","options":[{"id":"a","text":"Increase sodium to reduce fluid retention"},{"id":"b","text":"Decrease sodium to manage fluid overload"},{"id":"c","text":"Sodium has no role in pulmonary edema"},{"id":"d","text":"Sodium balance is only relevant in respiratory failure"}],"answerId":"b","explanation":"Managing sodium intake is crucial in patients with pulmonary edema to help control fluid overload and reduce pulmonary congestion.","kind":"integration","origin":"ai"}],"solitary-pulmonary-nodule":[{"id":"solitary-pulmonary-nodule~ai-0","moduleId":"solitary-pulmonary-nodule","stem":"What is the maximum diameter for a solitary pulmonary nodule to be classified as a 'coin lesion'?","options":[{"id":"a","text":"1 cm"},{"id":"b","text":"2 cm"},{"id":"c","text":"3 cm"},{"id":"d","text":"4 cm"}],"answerId":"c","explanation":"A solitary pulmonary nodule is defined as a rounded lung opacity ≤3 cm.","kind":"recall","origin":"ai"},{"id":"solitary-pulmonary-nodule~ai-1","moduleId":"solitary-pulmonary-nodule","stem":"Which imaging feature is most suggestive of a benign solitary pulmonary nodule?","options":[{"id":"a","text":"Spiculated margins"},{"id":"b","text":"Growth on serial imaging"},{"id":"c","text":"Smooth well-defined margins"},{"id":"d","text":"Upper-lobe location"}],"answerId":"c","explanation":"Smooth well-defined margins are a feature favoring a benign nodule.","kind":"mechanism","origin":"ai"},{"id":"solitary-pulmonary-nodule~ai-2","moduleId":"solitary-pulmonary-nodule","stem":"A patient presents with a solitary pulmonary nodule that has been stable for 3 years. What is the most appropriate next step in management?","options":[{"id":"a","text":"Immediate biopsy"},{"id":"b","text":"CT surveillance"},{"id":"c","text":"PET-CT scan"},{"id":"d","text":"Surgical resection"}],"answerId":"b","explanation":"A stable nodule for ≥2 years is very likely benign and can be observed with CT surveillance.","kind":"clinical","origin":"ai"},{"id":"solitary-pulmonary-nodule~ai-3","moduleId":"solitary-pulmonary-nodule","stem":"Which of the following findings on a PET-CT scan indicates a higher probability of malignancy in a solitary pulmonary nodule?","options":[{"id":"a","text":"Non-FDG avidity"},{"id":"b","text":"FDG avidity"},{"id":"c","text":"Stable size"},{"id":"d","text":"Smooth margins"}],"answerId":"b","explanation":"FDG avidity indicates metabolic activity, which is associated with a higher probability of malignancy.","kind":"mechanism","origin":"ai"},{"id":"solitary-pulmonary-nodule~ai-4","moduleId":"solitary-pulmonary-nodule","stem":"A solitary pulmonary nodule shows popcorn calcification and has been stable for 5 years. What is the most likely diagnosis?","options":[{"id":"a","text":"Primary lung carcinoma"},{"id":"b","text":"Solitary metastasis"},{"id":"c","text":"Hamartoma"},{"id":"d","text":"Infectious granuloma"}],"answerId":"c","explanation":"Popcorn calcification is characteristic of a hamartoma, especially when stable over time.","kind":"trap","origin":"ai"},{"id":"solitary-pulmonary-nodule~ai-5","moduleId":"solitary-pulmonary-nodule","stem":"Which feature would most likely indicate a malignant solitary pulmonary nodule?","options":[{"id":"a","text":"Stable for 2 years"},{"id":"b","text":"Smooth margins"},{"id":"c","text":"Spiculated margins"},{"id":"d","text":"Popcorn calcification"}],"answerId":"c","explanation":"Spiculated margins are a feature that raises suspicion for malignancy.","kind":"mechanism","origin":"ai"},{"id":"solitary-pulmonary-nodule~ai-6","moduleId":"solitary-pulmonary-nodule","stem":"How does the assessment of a solitary pulmonary nodule relate to the principles of neoplasia differentiation?","options":[{"id":"a","text":"Both require immediate biopsy of all lesions"},{"id":"b","text":"Both rely on imaging characteristics to assess malignancy risk"},{"id":"c","text":"Both are unrelated to patient history"},{"id":"d","text":"Both focus solely on size of the lesion"}],"answerId":"b","explanation":"Both assessments utilize imaging characteristics to differentiate between benign and malignant lesions.","kind":"integration","linkedModuleIds":["neoplasia-differentiation-invasion"],"origin":"ai"},{"id":"solitary-pulmonary-nodule~ai-7","moduleId":"solitary-pulmonary-nodule","stem":"What is the significance of comparing a solitary pulmonary nodule with old imaging studies?","options":[{"id":"a","text":"It confirms the diagnosis of lung cancer"},{"id":"b","text":"It helps determine the growth rate and malignancy risk"},{"id":"c","text":"It is not necessary for benign nodules"},{"id":"d","text":"It only applies to nodules larger than 3 cm"}],"answerId":"b","explanation":"Comparing with old imaging helps assess growth rate, which is crucial for determining malignancy risk.","kind":"integration","linkedModuleIds":["chest-ct-imaging-patterns"],"origin":"ai"}],"small-cell-and-other-lung-tumors":[{"id":"small-cell-and-other-lung-tumors~ai-0","moduleId":"small-cell-and-other-lung-tumors","stem":"What is the most common paraneoplastic syndrome associated with small-cell lung carcinoma?","options":[{"id":"a","text":"Cushing syndrome"},{"id":"b","text":"Lambert-Eaton myasthenic syndrome"},{"id":"c","text":"Hypercalcemia"},{"id":"d","text":"SIADH"}],"answerId":"d","explanation":"Small-cell lung carcinoma is most commonly associated with ectopic ADH secretion leading to SIADH.","kind":"recall","origin":"ai"},{"id":"small-cell-and-other-lung-tumors~ai-1","moduleId":"small-cell-and-other-lung-tumors","stem":"Which histological feature is characteristic of carcinoid tumors?","options":[{"id":"a","text":"Pleomorphic cells"},{"id":"b","text":"Salt-and-pepper nuclei"},{"id":"c","text":"Keratin pearls"},{"id":"d","text":"Giant cells"}],"answerId":"b","explanation":"Carcinoid tumors are characterized by uniform 'salt-and-pepper' nuclei.","kind":"recall","origin":"ai"},{"id":"small-cell-and-other-lung-tumors~ai-2","moduleId":"small-cell-and-other-lung-tumors","stem":"A patient with small-cell lung carcinoma presents with proximal muscle weakness that improves with repeated effort. What is the underlying mechanism?","options":[{"id":"a","text":"Antibodies to acetylcholine receptors"},{"id":"b","text":"Antibodies to voltage-gated calcium channels"},{"id":"c","text":"Direct muscle invasion by tumor"},{"id":"d","text":"Neuropathic damage from chemotherapy"}],"answerId":"b","explanation":"The proximal weakness is due to Lambert-Eaton myasthenic syndrome, caused by antibodies to presynaptic voltage-gated calcium channels.","kind":"mechanism","origin":"ai"},{"id":"small-cell-and-other-lung-tumors~ai-3","moduleId":"small-cell-and-other-lung-tumors","stem":"Which finding is most indicative of metastatic lung disease?","options":[{"id":"a","text":"Solitary pulmonary nodule"},{"id":"b","text":"Multiple well-circumscribed cannonball nodules"},{"id":"c","text":"A central mass with cavitation"},{"id":"d","text":"A peripheral mass with calcification"}],"answerId":"b","explanation":"Multiple well-circumscribed cannonball nodules in the lungs are classic for hematogenous metastases.","kind":"recall","origin":"ai"},{"id":"small-cell-and-other-lung-tumors~ai-4","moduleId":"small-cell-and-other-lung-tumors","stem":"What is the primary treatment approach for small-cell lung carcinoma?","options":[{"id":"a","text":"Surgical resection"},{"id":"b","text":"Chemotherapy and radiotherapy"},{"id":"c","text":"Targeted therapy"},{"id":"d","text":"Immunotherapy"}],"answerId":"b","explanation":"Small-cell lung carcinoma is treated primarily with chemotherapy and radiotherapy due to its aggressive nature and early dissemination.","kind":"trap","origin":"ai"},{"id":"small-cell-and-other-lung-tumors~ai-5","moduleId":"small-cell-and-other-lung-tumors","stem":"A young non-smoker presents with a central bronchial mass. What is the most likely diagnosis?","options":[{"id":"a","text":"Small-cell lung carcinoma"},{"id":"b","text":"Non-small-cell lung carcinoma"},{"id":"c","text":"Carcinoid tumor"},{"id":"d","text":"Metastatic cancer"}],"answerId":"c","explanation":"A central bronchial mass in a young non-smoker is most consistent with a carcinoid tumor, which is a low-grade neuroendocrine tumor.","kind":"clinical","origin":"ai"},{"id":"small-cell-and-other-lung-tumors~ai-6","moduleId":"small-cell-and-other-lung-tumors","stem":"How does ectopic ADH secretion from small-cell lung carcinoma lead to hyponatremia?","options":[{"id":"a","text":"Increased renal water reabsorption"},{"id":"b","text":"Decreased renal sodium reabsorption"},{"id":"c","text":"Increased sodium excretion"},{"id":"d","text":"Decreased thirst response"}],"answerId":"a","explanation":"Ectopic ADH leads to increased renal water reabsorption, resulting in dilutional hyponatremia.","kind":"integration","linkedModuleIds":["adh-water-regulation"],"origin":"ai"},{"id":"small-cell-and-other-lung-tumors~ai-7","moduleId":"small-cell-and-other-lung-tumors","stem":"Which feature differentiates small-cell lung carcinoma from non-small-cell lung carcinoma?","options":[{"id":"a","text":"Presence of neuroendocrine markers"},{"id":"b","text":"Higher incidence in non-smokers"},{"id":"c","text":"Better prognosis"},{"id":"d","text":"Surgical resectability"}],"answerId":"a","explanation":"Small-cell lung carcinoma is characterized by neuroendocrine markers and is typically treated with chemotherapy rather than surgery.","kind":"integration","linkedModuleIds":["non-small-cell-lung-carcinoma"],"origin":"ai"}],"influenza-covid-pneumonia":[{"id":"influenza-covid-pneumonia~ai-0","moduleId":"influenza-covid-pneumonia","stem":"What is the primary mechanism by which influenza pandemics occur?","options":[{"id":"a","text":"Antigenic drift"},{"id":"b","text":"Antigenic shift"},{"id":"c","text":"Viral mutation"},{"id":"d","text":"Bacterial superinfection"}],"answerId":"b","explanation":"Influenza pandemics arise from antigenic shift, which involves reassortment of genome segments between strains, creating a novel H/N subtype.","kind":"mechanism","origin":"ai"},{"id":"influenza-covid-pneumonia~ai-1","moduleId":"influenza-covid-pneumonia","stem":"Which clinical finding is characteristic of secondary bacterial pneumonia following influenza?","options":[{"id":"a","text":"Bilateral ground-glass opacities"},{"id":"b","text":"Improvement followed by deterioration"},{"id":"c","text":"Anosmia"},{"id":"d","text":"Lobar consolidation without prior improvement"}],"answerId":"b","explanation":"Secondary bacterial pneumonia often presents as a patient improving and then deteriorating, typically due to organisms like Staphylococcus aureus.","kind":"clinical","origin":"ai"},{"id":"influenza-covid-pneumonia~ai-2","moduleId":"influenza-covid-pneumonia","stem":"What is the primary viral entry mechanism for SARS-CoV-2?","options":[{"id":"a","text":"Hemagglutinin binding"},{"id":"b","text":"Spike protein binding to ACE2"},{"id":"c","text":"Neuraminidase activity"},{"id":"d","text":"Direct cell lysis"}],"answerId":"b","explanation":"SARS-CoV-2 enters cells primarily through the spike protein binding to the ACE2 receptor.","kind":"mechanism","origin":"ai"},{"id":"influenza-covid-pneumonia~ai-3","moduleId":"influenza-covid-pneumonia","stem":"Which of the following is a risk associated with aspirin use in children with viral infections?","options":[{"id":"a","text":"Reye syndrome"},{"id":"b","text":"Gastrointestinal bleeding"},{"id":"c","text":"Increased viral replication"},{"id":"d","text":"Decreased immune response"}],"answerId":"a","explanation":"Aspirin use in children with viral infections, such as influenza, is associated with Reye syndrome, a serious condition.","kind":"trap","origin":"ai"},{"id":"influenza-covid-pneumonia~ai-4","moduleId":"influenza-covid-pneumonia","stem":"What imaging finding is typical in patients with severe COVID-19 pneumonia?","options":[{"id":"a","text":"Unilateral pleural effusion"},{"id":"b","text":"Bilateral peripheral ground-glass opacities"},{"id":"c","text":"Consolidation in the lower lobes"},{"id":"d","text":"Cavitary lesions"}],"answerId":"b","explanation":"Severe COVID-19 pneumonia is characterized by bilateral peripheral ground-glass opacities on imaging.","kind":"recall","origin":"ai"},{"id":"influenza-covid-pneumonia~ai-5","moduleId":"influenza-covid-pneumonia","stem":"How does the mechanism of action for neuraminidase inhibitors relate to influenza treatment?","options":[{"id":"a","text":"Inhibit viral entry"},{"id":"b","text":"Prevent viral replication"},{"id":"c","text":"Block viral release"},{"id":"d","text":"Enhance immune response"}],"answerId":"c","explanation":"Neuraminidase inhibitors prevent the release of newly formed virions from infected cells, thus limiting the spread of the virus.","kind":"mechanism","origin":"ai"},{"id":"influenza-covid-pneumonia~ai-6","moduleId":"influenza-covid-pneumonia","stem":"How does COVID-19 pneumonia differ from typical influenza pneumonia in terms of imaging findings?","options":[{"id":"a","text":"Presence of lobar consolidation"},{"id":"b","text":"Bilateral peripheral ground-glass opacities"},{"id":"c","text":"Cavitary lesions"},{"id":"d","text":"Unilateral infiltrates"}],"answerId":"b","explanation":"COVID-19 pneumonia typically presents with bilateral peripheral ground-glass opacities, unlike typical influenza pneumonia.","kind":"integration","linkedModuleIds":["ards-pulmonary-hypertension-atelectasis"],"origin":"ai"},{"id":"influenza-covid-pneumonia~ai-7","moduleId":"influenza-covid-pneumonia","stem":"Which viral characteristic is crucial for the development of seasonal influenza epidemics?","options":[{"id":"a","text":"Antigenic shift"},{"id":"b","text":"Antigenic drift"},{"id":"c","text":"Viral replication rate"},{"id":"d","text":"Host immune response"}],"answerId":"b","explanation":"Seasonal influenza epidemics are primarily due to antigenic drift, which involves small mutations in the virus's surface proteins.","kind":"integration","linkedModuleIds":["respiratory-antiviral-drugs"],"origin":"ai"}],"parasitic-lung-infections":[{"id":"parasitic-lung-infections~ai-0","moduleId":"parasitic-lung-infections","stem":"What is the most common cause of chronic cough with hemoptysis and lung cysts after eating raw crab?","options":[{"id":"a","text":"Tuberculosis"},{"id":"b","text":"Paragonimus westermani"},{"id":"c","text":"Strongyloides stercoralis"},{"id":"d","text":"Echinococcus granulosus"}],"answerId":"b","explanation":"Paragonimus westermani, the lung fluke, is acquired by consuming raw crab and presents with symptoms that mimic tuberculosis.","kind":"recall","origin":"ai"},{"id":"parasitic-lung-infections~ai-1","moduleId":"parasitic-lung-infections","stem":"Which mechanism leads to eosinophilia in Löffler syndrome?","options":[{"id":"a","text":"Direct infection of lung tissue"},{"id":"b","text":"Larval migration through alveoli"},{"id":"c","text":"Allergic reaction to parasites"},{"id":"d","text":"Bacterial superinfection"}],"answerId":"b","explanation":"Löffler syndrome is caused by the migration of larvae through the alveoli, leading to eosinophilic pneumonia.","kind":"mechanism","origin":"ai"},{"id":"parasitic-lung-infections~ai-2","moduleId":"parasitic-lung-infections","stem":"A patient presents with marked eosinophilia and migratory lung infiltrates. What is the likely diagnosis?","options":[{"id":"a","text":"Paragonimiasis"},{"id":"b","text":"Löffler syndrome"},{"id":"c","text":"Echinococcal disease"},{"id":"d","text":"Strongyloides hyperinfection"}],"answerId":"b","explanation":"Migratory lung infiltrates with eosinophilia are characteristic of Löffler syndrome due to larval migration.","kind":"clinical","origin":"ai"},{"id":"parasitic-lung-infections~ai-3","moduleId":"parasitic-lung-infections","stem":"What is the primary treatment for Paragonimus westermani infection?","options":[{"id":"a","text":"Albendazole"},{"id":"b","text":"Ivermectin"},{"id":"c","text":"Praziquantel"},{"id":"d","text":"Anti-TB drugs"}],"answerId":"c","explanation":"Praziquantel is the specific treatment for infections caused by flukes like Paragonimus westermani.","kind":"recall","origin":"ai"},{"id":"parasitic-lung-infections~ai-4","moduleId":"parasitic-lung-infections","stem":"In a patient with eosinophilia and a history of exposure to filarial infections, which finding is most suggestive of tropical pulmonary eosinophilia?","options":[{"id":"a","text":"Chronic cough with hemoptysis"},{"id":"b","text":"Well-defined lung cysts"},{"id":"c","text":"Very high IgE levels"},{"id":"d","text":"Migratory lung infiltrates"}],"answerId":"c","explanation":"Very high IgE levels are characteristic of tropical pulmonary eosinophilia, a hyperresponse to filarial infections.","kind":"clinical","origin":"ai"},{"id":"parasitic-lung-infections~ai-5","moduleId":"parasitic-lung-infections","stem":"A patient from Southeast Asia presents with a TB-like lung picture. What should be prioritized in the work-up?","options":[{"id":"a","text":"Sputum for AFB"},{"id":"b","text":"Sputum for ova and parasites"},{"id":"c","text":"Chest CT scan"},{"id":"d","text":"Bronchoscopy"}],"answerId":"b","explanation":"In endemic areas, a TB-like picture with eosinophilia should prompt a work-up for parasites, including sputum for ova and parasites.","kind":"trap","origin":"ai"},{"id":"parasitic-lung-infections~ai-6","moduleId":"parasitic-lung-infections","stem":"How does Ascaris lumbricoides contribute to eosinophilic lung disease?","options":[{"id":"a","text":"By causing direct lung infection"},{"id":"b","text":"Through larval migration causing Löffler syndrome"},{"id":"c","text":"By inducing hypersensitivity reactions"},{"id":"d","text":"By forming cysts in the lung"}],"answerId":"b","explanation":"Ascaris lumbricoides larvae migrate through the lungs, leading to Löffler syndrome characterized by eosinophilia.","kind":"integration","linkedModuleIds":["ascariasis-large-roundworm"],"origin":"ai"},{"id":"parasitic-lung-infections~ai-7","moduleId":"parasitic-lung-infections","stem":"What is a distinguishing feature of Echinococcus granulosus infection compared to other parasitic lung infections?","options":[{"id":"a","text":"Causes chronic cough"},{"id":"b","text":"Leads to well-defined lung cysts"},{"id":"c","text":"Results in eosinophilia"},{"id":"d","text":"Mimics tuberculosis"}],"answerId":"b","explanation":"Echinococcus granulosus forms well-defined lung cysts, which is a key distinguishing feature from other parasitic infections.","kind":"integration","linkedModuleIds":["trematodes-flukes-overview"],"origin":"ai"}],"other-respiratory-viruses":[{"id":"other-respiratory-viruses~ai-0","moduleId":"other-respiratory-viruses","stem":"What is the primary mechanism by which Respiratory Syncytial Virus (RSV) causes respiratory distress in infants?","options":[{"id":"a","text":"Infection of alveolar macrophages"},{"id":"b","text":"Formation of syncytia in respiratory epithelium"},{"id":"c","text":"Direct cytotoxicity to lung parenchyma"},{"id":"d","text":"Inhibition of surfactant production"}],"answerId":"b","explanation":"RSV causes respiratory distress primarily through the formation of syncytia in the respiratory epithelium, leading to airway obstruction.","kind":"mechanism","origin":"ai"},{"id":"other-respiratory-viruses~ai-1","moduleId":"other-respiratory-viruses","stem":"A 3-year-old presents with a barking cough and inspiratory stridor. What is the most likely diagnosis?","options":[{"id":"a","text":"Bacterial epiglottitis"},{"id":"b","text":"Croup due to parainfluenza virus"},{"id":"c","text":"RSV bronchiolitis"},{"id":"d","text":"Adenovirus infection"}],"answerId":"b","explanation":"The classic presentation of barking cough and inspiratory stridor is characteristic of croup caused by parainfluenza virus.","kind":"clinical","origin":"ai"},{"id":"other-respiratory-viruses~ai-2","moduleId":"other-respiratory-viruses","stem":"Which clinical finding is pathognomonic for measles infection?","options":[{"id":"a","text":"Barking cough"},{"id":"b","text":"Koplik spots"},{"id":"c","text":"Steeple sign"},{"id":"d","text":"Multinucleated giant cells"}],"answerId":"b","explanation":"Koplik spots are pathognomonic for measles and appear as small white lesions on the buccal mucosa.","kind":"recall","origin":"ai"},{"id":"other-respiratory-viruses~ai-3","moduleId":"other-respiratory-viruses","stem":"In a child with suspected croup, which finding would most likely differentiate it from bacterial epiglottitis?","options":[{"id":"a","text":"Presence of drooling"},{"id":"b","text":"Barking cough"},{"id":"c","text":"Toxic appearance"},{"id":"d","text":"Thumbprint sign on X-ray"}],"answerId":"b","explanation":"A barking cough is characteristic of croup, whereas drooling and a toxic appearance suggest bacterial epiglottitis.","kind":"trap","origin":"ai"},{"id":"other-respiratory-viruses~ai-4","moduleId":"other-respiratory-viruses","stem":"What is the primary treatment for mild croup in children?","options":[{"id":"a","text":"Antibiotics"},{"id":"b","text":"Corticosteroids"},{"id":"c","text":"Nebulized epinephrine"},{"id":"d","text":"Intubation"}],"answerId":"b","explanation":"Corticosteroids are the primary treatment for mild croup to reduce inflammation.","kind":"recall","origin":"ai"},{"id":"other-respiratory-viruses~ai-5","moduleId":"other-respiratory-viruses","stem":"A child with a recent history of fever, conjunctivitis, and pharyngitis presents during an outbreak. Which virus is most likely responsible?","options":[{"id":"a","text":"RSV"},{"id":"b","text":"Adenovirus"},{"id":"c","text":"Parainfluenza"},{"id":"d","text":"Measles"}],"answerId":"b","explanation":"Adenovirus is known to cause pharyngoconjunctival fever, especially in outbreak settings.","kind":"clinical","origin":"ai"},{"id":"other-respiratory-viruses~ai-6","moduleId":"other-respiratory-viruses","stem":"How does the pathophysiology of RSV bronchiolitis differ from that of influenza pneumonia?","options":[{"id":"a","text":"RSV causes syncytia formation; influenza causes direct cytotoxicity"},{"id":"b","text":"RSV primarily affects adults; influenza affects infants"},{"id":"c","text":"Influenza is a DNA virus; RSV is an RNA virus"},{"id":"d","text":"RSV causes upper respiratory symptoms; influenza does not"}],"answerId":"a","explanation":"RSV causes syncytia formation in respiratory epithelium, while influenza primarily causes direct cytotoxicity to lung cells.","kind":"integration","linkedModuleIds":["enveloped-rna-viruses-orthomyxo-paramyxo"],"origin":"ai"},{"id":"other-respiratory-viruses~ai-7","moduleId":"other-respiratory-viruses","stem":"Which of the following findings would suggest a diagnosis of epiglottitis rather than croup in a child presenting with stridor?","options":[{"id":"a","text":"Barking cough"},{"id":"b","text":"Drooling"},{"id":"c","text":"Steeple sign"},{"id":"d","text":"Coryza"}],"answerId":"b","explanation":"Drooling is a classic sign of epiglottitis and indicates a more severe airway obstruction compared to croup.","kind":"integration","linkedModuleIds":["otitis-media-sinusitis-epiglottitis"],"origin":"ai"}],"pneumonia-pathology-patterns":[{"id":"pneumonia-pathology-patterns~ai-0","moduleId":"pneumonia-pathology-patterns","stem":"What is the primary organism associated with lobar pneumonia?","options":[{"id":"a","text":"Staphylococcus aureus"},{"id":"b","text":"Klebsiella pneumoniae"},{"id":"c","text":"Streptococcus pneumoniae"},{"id":"d","text":"Pseudomonas aeruginosa"}],"answerId":"c","explanation":"Lobar pneumonia is classically associated with Streptococcus pneumoniae.","kind":"recall","origin":"ai"},{"id":"pneumonia-pathology-patterns~ai-1","moduleId":"pneumonia-pathology-patterns","stem":"Which stage of lobar pneumonia is characterized by the presence of RBCs and neutrophils?","options":[{"id":"a","text":"Congestion"},{"id":"b","text":"Red hepatisation"},{"id":"c","text":"Grey hepatisation"},{"id":"d","text":"Resolution"}],"answerId":"b","explanation":"Red hepatisation is marked by the presence of RBCs and neutrophils in the lung tissue.","kind":"mechanism","origin":"ai"},{"id":"pneumonia-pathology-patterns~ai-2","moduleId":"pneumonia-pathology-patterns","stem":"What is a common clinical finding in bronchopneumonia?","options":[{"id":"a","text":"Whole-lobe consolidation"},{"id":"b","text":"Patchy bilateral basal consolidation"},{"id":"c","text":"Mononuclear infiltrate"},{"id":"d","text":"Cavity formation"}],"answerId":"b","explanation":"Bronchopneumonia typically presents with patchy bilateral basal consolidation.","kind":"recall","origin":"ai"},{"id":"pneumonia-pathology-patterns~ai-3","moduleId":"pneumonia-pathology-patterns","stem":"Which complication is most likely associated with necrotising pneumonia?","options":[{"id":"a","text":"Empyema"},{"id":"b","text":"Abscess formation"},{"id":"c","text":"Fibrous scarring"},{"id":"d","text":"Bacteraemic dissemination"}],"answerId":"b","explanation":"Necrotising pneumonia often leads to abscess formation due to the virulence of the causative organisms.","kind":"clinical","origin":"ai"},{"id":"pneumonia-pathology-patterns~ai-4","moduleId":"pneumonia-pathology-patterns","stem":"What does the term 'hepatisation' refer to in the context of pneumonia?","options":[{"id":"a","text":"Liver infection"},{"id":"b","text":"Lung consolidation"},{"id":"c","text":"Abscess formation"},{"id":"d","text":"Pleural effusion"}],"answerId":"b","explanation":"Hepatisation describes the lung becoming as firm and solid as liver tissue during lobar pneumonia.","kind":"trap","origin":"ai"},{"id":"pneumonia-pathology-patterns~ai-5","moduleId":"pneumonia-pathology-patterns","stem":"In a patient with atypical pneumonia, which organism is most likely responsible?","options":[{"id":"a","text":"Klebsiella pneumoniae"},{"id":"b","text":"Mycoplasma pneumoniae"},{"id":"c","text":"Streptococcus pneumoniae"},{"id":"d","text":"Staphylococcus aureus"}],"answerId":"b","explanation":"Mycoplasma pneumoniae is a common cause of atypical pneumonia, characterized by interstitial inflammation.","kind":"recall","origin":"ai"},{"id":"pneumonia-pathology-patterns~ai-6","moduleId":"pneumonia-pathology-patterns","stem":"How does interstitial pneumonia differ from lobar pneumonia in terms of pathology?","options":[{"id":"a","text":"It fills airspaces with neutrophils"},{"id":"b","text":"It causes consolidation of an entire lobe"},{"id":"c","text":"It inflames the alveolar walls"},{"id":"d","text":"It leads to abscess formation"}],"answerId":"c","explanation":"Interstitial pneumonia primarily inflames the alveolar walls rather than filling airspaces.","kind":"mechanism","origin":"ai"},{"id":"pneumonia-pathology-patterns~ai-7","moduleId":"pneumonia-pathology-patterns","stem":"Which pneumonia pattern is most likely to be associated with empyema?","options":[{"id":"a","text":"Lobar pneumonia"},{"id":"b","text":"Bronchopneumonia"},{"id":"c","text":"Interstitial pneumonia"},{"id":"d","text":"Atypical pneumonia"}],"answerId":"a","explanation":"Lobar pneumonia can lead to empyema due to the accumulation of pus in the pleural space.","kind":"integration","linkedModuleIds":["hospital-aspiration-pneumonia-abscess"],"origin":"ai"},{"id":"pneumonia-pathology-patterns~ai-8","moduleId":"pneumonia-pathology-patterns","stem":"What radiographic finding is expected in a patient with interstitial pneumonia?","options":[{"id":"a","text":"Whole-lobe consolidation"},{"id":"b","text":"Patchy infiltrates"},{"id":"c","text":"Reticular pattern"},{"id":"d","text":"Cavitary lesions"}],"answerId":"c","explanation":"Interstitial pneumonia typically presents with a diffuse reticular pattern on chest radiographs.","kind":"integration","linkedModuleIds":["chest-radiograph-interpretation"],"origin":"ai"}],"tuberculosis-pathology":[{"id":"tuberculosis-pathology~ai-0","moduleId":"tuberculosis-pathology","stem":"What is the pathological hallmark of tuberculosis?","options":[{"id":"a","text":"Non-caseating granuloma"},{"id":"b","text":"Caseating granuloma"},{"id":"c","text":"Lymphocytic infiltration"},{"id":"d","text":"Fibrosis"}],"answerId":"b","explanation":"Tuberculosis is characterized by caseating granulomas, which contain necrotic tissue and are indicative of a type IV hypersensitivity reaction.","kind":"recall","origin":"ai"},{"id":"tuberculosis-pathology~ai-1","moduleId":"tuberculosis-pathology","stem":"Which of the following findings is characteristic of secondary (reactivation) tuberculosis?","options":[{"id":"a","text":"Ghon complex"},{"id":"b","text":"Apical cavitary lesions"},{"id":"c","text":"Miliary granulomas"},{"id":"d","text":"Hilar lymphadenopathy"}],"answerId":"b","explanation":"Secondary tuberculosis typically presents with apical cavitary lesions due to high oxygen tension in the lung apices.","kind":"clinical","origin":"ai"},{"id":"tuberculosis-pathology~ai-2","moduleId":"tuberculosis-pathology","stem":"What type of hypersensitivity reaction is involved in the pathogenesis of tuberculosis?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"d","explanation":"Tuberculosis causes disease through a type IV hypersensitivity reaction, leading to the formation of caseating granulomas.","kind":"mechanism","origin":"ai"},{"id":"tuberculosis-pathology~ai-3","moduleId":"tuberculosis-pathology","stem":"A patient presents with fever, night sweats, and a chronic cough. A chest X-ray shows apical cavitary lesions. What is the most likely diagnosis?","options":[{"id":"a","text":"Primary tuberculosis"},{"id":"b","text":"Secondary tuberculosis"},{"id":"c","text":"Miliary tuberculosis"},{"id":"d","text":"Sarcoidosis"}],"answerId":"b","explanation":"The symptoms and chest X-ray findings are consistent with secondary tuberculosis, which often presents with cavitary lesions in the apices.","kind":"clinical","origin":"ai"},{"id":"tuberculosis-pathology~ai-4","moduleId":"tuberculosis-pathology","stem":"What distinguishes primary tuberculosis from secondary tuberculosis in terms of lung location?","options":[{"id":"a","text":"Both affect the lung apices"},{"id":"b","text":"Primary affects mid/lower zones, secondary affects apices"},{"id":"c","text":"Both affect mid/lower zones"},{"id":"d","text":"Primary affects apices, secondary affects mid/lower zones"}],"answerId":"b","explanation":"Primary tuberculosis typically forms a Ghon complex in the mid/lower lung zones, while secondary tuberculosis localizes to the apices.","kind":"trap","origin":"ai"},{"id":"tuberculosis-pathology~ai-5","moduleId":"tuberculosis-pathology","stem":"Which of the following is a potential complication of miliary tuberculosis?","options":[{"id":"a","text":"Pott disease"},{"id":"b","text":"Ghon complex"},{"id":"c","text":"Cavitary lung disease"},{"id":"d","text":"Pleural effusion"}],"answerId":"a","explanation":"Miliary tuberculosis can lead to Pott disease, which is a form of spinal tuberculosis resulting from hematogenous spread.","kind":"clinical","origin":"ai"},{"id":"tuberculosis-pathology~ai-6","moduleId":"tuberculosis-pathology","stem":"How does the presence of acid-fast bacilli (AFB) in a granuloma help differentiate tuberculosis from sarcoidosis?","options":[{"id":"a","text":"AFB indicates a non-caseating granuloma"},{"id":"b","text":"AFB indicates a caseating granuloma"},{"id":"c","text":"AFB is present in both conditions"},{"id":"d","text":"AFB is absent in both conditions"}],"answerId":"b","explanation":"The presence of AFB in a caseating granuloma is a hallmark of tuberculosis, whereas sarcoidosis features non-caseating granulomas without AFB.","kind":"integration","linkedModuleIds":["sarcoidosis-granulomatous-lung"],"origin":"ai"},{"id":"tuberculosis-pathology~ai-7","moduleId":"tuberculosis-pathology","stem":"In a patient with latent tuberculosis, which test result would you expect to be positive?","options":[{"id":"a","text":"Chest X-ray showing cavitary lesions"},{"id":"b","text":"Positive tuberculin skin test"},{"id":"c","text":"Negative IGRA"},{"id":"d","text":"Negative sputum culture"}],"answerId":"b","explanation":"A positive tuberculin skin test indicates prior exposure to Mycobacterium tuberculosis, consistent with latent infection.","kind":"integration","linkedModuleIds":["tuberculosis-clinical-latent-mdr"],"origin":"ai"}],"obstructive-sleep-apnoea":[{"id":"obstructive-sleep-apnoea~ai-0","moduleId":"obstructive-sleep-apnoea","stem":"What is the primary risk factor for obstructive sleep apnoea (OSA)?","options":[{"id":"a","text":"Obesity"},{"id":"b","text":"Male sex"},{"id":"c","text":"Large neck circumference"},{"id":"d","text":"Retrognathia"}],"answerId":"a","explanation":"Obesity is the dominant risk factor for obstructive sleep apnoea, leading to upper airway obstruction during sleep.","kind":"recall","origin":"ai"},{"id":"obstructive-sleep-apnoea~ai-1","moduleId":"obstructive-sleep-apnoea","stem":"Which finding is characteristic of obstructive sleep apnoea?","options":[{"id":"a","text":"Absent respiratory effort during apnoeas"},{"id":"b","text":"Loud snoring with witnessed apnoeas"},{"id":"c","text":"Cyanosis during wakefulness"},{"id":"d","text":"Hypocapnia during sleep"}],"answerId":"b","explanation":"Loud snoring and witnessed apnoeas are classic clinical signs of obstructive sleep apnoea.","kind":"recall","origin":"ai"},{"id":"obstructive-sleep-apnoea~ai-2","moduleId":"obstructive-sleep-apnoea","stem":"What mechanism leads to systemic hypertension in patients with obstructive sleep apnoea?","options":[{"id":"a","text":"Increased respiratory drive"},{"id":"b","text":"Nocturnal hypoxia and sympathetic activation"},{"id":"c","text":"Decreased cardiac output"},{"id":"d","text":"Hypercapnia during wakefulness"}],"answerId":"b","explanation":"Nocturnal hypoxia and sympathetic activation contribute to systemic hypertension in obstructive sleep apnoea.","kind":"mechanism","origin":"ai"},{"id":"obstructive-sleep-apnoea~ai-3","moduleId":"obstructive-sleep-apnoea","stem":"In obstructive sleep apnoea, what distinguishes it from central sleep apnoea?","options":[{"id":"a","text":"Presence of respiratory effort against an obstructed airway"},{"id":"b","text":"Complete absence of respiratory effort"},{"id":"c","text":"Presence of daytime hypercapnia"},{"id":"d","text":"Lack of snoring"}],"answerId":"a","explanation":"In obstructive sleep apnoea, respiratory effort continues despite airway obstruction, unlike in central sleep apnoea where there is no effort.","kind":"trap","origin":"ai"},{"id":"obstructive-sleep-apnoea~ai-4","moduleId":"obstructive-sleep-apnoea","stem":"What is the first-line treatment for obstructive sleep apnoea?","options":[{"id":"a","text":"Mandibular advancement device"},{"id":"b","text":"Surgery"},{"id":"c","text":"Continuous positive airway pressure (CPAP)"},{"id":"d","text":"Weight loss alone"}],"answerId":"c","explanation":"Continuous positive airway pressure (CPAP) is the first-line treatment for obstructive sleep apnoea, as it helps to keep the airway open during sleep.","kind":"recall","origin":"ai"},{"id":"obstructive-sleep-apnoea~ai-5","moduleId":"obstructive-sleep-apnoea","stem":"How does obstructive sleep apnoea relate to obesity and metabolic syndrome?","options":[{"id":"a","text":"It causes increased insulin sensitivity"},{"id":"b","text":"It is a direct result of metabolic syndrome"},{"id":"c","text":"It exacerbates cardiovascular risks associated with obesity"},{"id":"d","text":"It prevents weight gain"}],"answerId":"c","explanation":"Obstructive sleep apnoea exacerbates cardiovascular risks associated with obesity, linking the two conditions.","kind":"integration","linkedModuleIds":["obesity-pathophysiology"],"origin":"ai"},{"id":"obstructive-sleep-apnoea~ai-6","moduleId":"obstructive-sleep-apnoea","stem":"Which physiological change during sleep contributes to the pathophysiology of obstructive sleep apnoea?","options":[{"id":"a","text":"Increased lung compliance"},{"id":"b","text":"Relaxation of pharyngeal muscles"},{"id":"c","text":"Decreased sympathetic tone"},{"id":"d","text":"Enhanced respiratory drive"}],"answerId":"b","explanation":"Relaxation of pharyngeal muscles during sleep leads to airway collapse, which is central to the pathophysiology of obstructive sleep apnoea.","kind":"mechanism","origin":"ai"},{"id":"obstructive-sleep-apnoea~ai-7","moduleId":"obstructive-sleep-apnoea","stem":"What is a common consequence of untreated obstructive sleep apnoea related to cardiovascular health?","options":[{"id":"a","text":"Decreased blood pressure"},{"id":"b","text":"Increased risk of stroke"},{"id":"c","text":"Improved cardiac output"},{"id":"d","text":"Lower cholesterol levels"}],"answerId":"b","explanation":"Untreated obstructive sleep apnoea increases the risk of cardiovascular events, including stroke, due to recurrent hypoxia and sympathetic activation.","kind":"clinical","origin":"ai"},{"id":"obstructive-sleep-apnoea~ai-8","moduleId":"obstructive-sleep-apnoea","stem":"How does obstructive sleep apnoea affect consciousness and alertness?","options":[{"id":"a","text":"It enhances cognitive function"},{"id":"b","text":"It leads to excessive daytime sleepiness"},{"id":"c","text":"It improves sleep quality"},{"id":"d","text":"It decreases the need for sleep"}],"answerId":"b","explanation":"Obstructive sleep apnoea leads to excessive daytime sleepiness due to fragmented sleep and recurrent arousals.","kind":"integration","linkedModuleIds":["reticular-activating-system-consciousness"],"origin":"ai"}],"respiratory-tract-antibiotics":[{"id":"respiratory-tract-antibiotics~ai-0","moduleId":"respiratory-tract-antibiotics","stem":"What is the first-line antibiotic for otitis media?","options":[{"id":"a","text":"Ceftriaxone"},{"id":"b","text":"Amoxicillin (± clavulanate)"},{"id":"c","text":"Azithromycin"},{"id":"d","text":"Vancomycin"}],"answerId":"b","explanation":"Amoxicillin (± clavulanate) is the first-line treatment for otitis media as it effectively covers the common pathogens.","kind":"recall","origin":"ai"},{"id":"respiratory-tract-antibiotics~ai-1","moduleId":"respiratory-tract-antibiotics","stem":"Which mechanism do β-lactam antibiotics utilize to exert their effect?","options":[{"id":"a","text":"Inhibit protein synthesis"},{"id":"b","text":"Inhibit DNA gyrase"},{"id":"c","text":"Inhibit cell wall synthesis"},{"id":"d","text":"Disrupt cell membrane integrity"}],"answerId":"c","explanation":"β-lactam antibiotics inhibit cell wall synthesis, leading to bacterial cell lysis.","kind":"mechanism","origin":"ai"},{"id":"respiratory-tract-antibiotics~ai-2","moduleId":"respiratory-tract-antibiotics","stem":"A patient presents with community-acquired pneumonia. Which combination of antibiotics is appropriate for empiric treatment?","options":[{"id":"a","text":"Amoxicillin alone"},{"id":"b","text":"Ceftriaxone + doxycycline"},{"id":"c","text":"Amoxicillin + azithromycin"},{"id":"d","text":"Levofloxacin alone"}],"answerId":"c","explanation":"Amoxicillin combined with azithromycin covers both typical and atypical organisms in community-acquired pneumonia.","kind":"clinical","origin":"ai"},{"id":"respiratory-tract-antibiotics~ai-3","moduleId":"respiratory-tract-antibiotics","stem":"What is a common adverse effect associated with fluoroquinolones?","options":[{"id":"a","text":"Nephrotoxicity"},{"id":"b","text":"Tendon rupture"},{"id":"c","text":"Hepatotoxicity"},{"id":"d","text":"QT prolongation"}],"answerId":"b","explanation":"Fluoroquinolones are known to cause tendon rupture, particularly in certain populations.","kind":"trap","origin":"ai"},{"id":"respiratory-tract-antibiotics~ai-4","moduleId":"respiratory-tract-antibiotics","stem":"In the treatment of community-acquired pneumonia, why is a macrolide added to a β-lactam?","options":[{"id":"a","text":"To cover anaerobes"},{"id":"b","text":"To cover atypical pathogens"},{"id":"c","text":"To prevent resistance"},{"id":"d","text":"To reduce side effects"}],"answerId":"b","explanation":"Macrolides are added to cover atypical pathogens that are resistant to β-lactams.","kind":"trap","origin":"ai"},{"id":"respiratory-tract-antibiotics~ai-5","moduleId":"respiratory-tract-antibiotics","stem":"Which antibiotic is indicated for a patient with suspected MRSA pneumonia?","options":[{"id":"a","text":"Amoxicillin"},{"id":"b","text":"Cefepime"},{"id":"c","text":"Vancomycin"},{"id":"d","text":"Doxycycline"}],"answerId":"c","explanation":"Vancomycin is used for suspected MRSA pneumonia due to its effectiveness against this organism.","kind":"recall","origin":"ai"},{"id":"respiratory-tract-antibiotics~ai-6","moduleId":"respiratory-tract-antibiotics","stem":"How do fluoroquinolones differ from β-lactams in their mechanism of action?","options":[{"id":"a","text":"They inhibit protein synthesis"},{"id":"b","text":"They inhibit cell wall synthesis"},{"id":"c","text":"They inhibit DNA gyrase"},{"id":"d","text":"They disrupt cell membrane integrity"}],"answerId":"c","explanation":"Fluoroquinolones inhibit DNA gyrase, while β-lactams inhibit cell wall synthesis.","kind":"integration","linkedModuleIds":["antibacterial-cell-wall-agents"],"origin":"ai"},{"id":"respiratory-tract-antibiotics~ai-7","moduleId":"respiratory-tract-antibiotics","stem":"In treating a patient with bacterial meningitis, which antibiotic class is crucial to consider for potential coverage of resistant organisms?","options":[{"id":"a","text":"Macrolides"},{"id":"b","text":"Fluoroquinolones"},{"id":"c","text":"β-lactams"},{"id":"d","text":"Glycopeptides"}],"answerId":"d","explanation":"Glycopeptides, such as vancomycin, are crucial for covering resistant organisms in bacterial meningitis.","kind":"integration","linkedModuleIds":["bacterial-meningitis"],"origin":"ai"}],"asthma-copd-pharmacology":[{"id":"asthma-copd-pharmacology~ai-0","moduleId":"asthma-copd-pharmacology","stem":"What is the primary mechanism of action of β2-agonists like salbutamol?","options":[{"id":"a","text":"Inhibition of phosphodiesterase"},{"id":"b","text":"Activation of M3 receptors"},{"id":"c","text":"Relaxation of airway smooth muscle via cAMP"},{"id":"d","text":"Reduction of airway inflammation"}],"answerId":"c","explanation":"β2-agonists relax airway smooth muscle by increasing intracellular cAMP levels.","kind":"mechanism","origin":"ai"},{"id":"asthma-copd-pharmacology~ai-1","moduleId":"asthma-copd-pharmacology","stem":"Which medication is contraindicated as monotherapy in asthma due to increased mortality risk?","options":[{"id":"a","text":"Inhaled corticosteroids"},{"id":"b","text":"Long-acting β2-agonists"},{"id":"c","text":"Leukotriene receptor antagonists"},{"id":"d","text":"Short-acting β2-agonists"}],"answerId":"b","explanation":"Long-acting β2-agonists must never be used alone in asthma as they can mask inflammation and increase mortality.","kind":"trap","origin":"ai"},{"id":"asthma-copd-pharmacology~ai-2","moduleId":"asthma-copd-pharmacology","stem":"A patient presents with tremors and tachycardia after using a reliever inhaler. What is the most likely cause?","options":[{"id":"a","text":"Inhaled corticosteroid side effects"},{"id":"b","text":"β2-agonist systemic effects"},{"id":"c","text":"Antimuscarinic overdose"},{"id":"d","text":"Theophylline toxicity"}],"answerId":"b","explanation":"Tremor and tachycardia are common systemic effects of β2-agonists like salbutamol.","kind":"recall","origin":"ai"},{"id":"asthma-copd-pharmacology~ai-3","moduleId":"asthma-copd-pharmacology","stem":"What is the primary role of inhaled corticosteroids in asthma management?","options":[{"id":"a","text":"Provide immediate bronchodilation"},{"id":"b","text":"Prevent airway inflammation"},{"id":"c","text":"Reduce mucus production"},{"id":"d","text":"Increase cAMP levels"}],"answerId":"b","explanation":"Inhaled corticosteroids are the cornerstone of asthma treatment as they prevent airway inflammation.","kind":"recall","origin":"ai"},{"id":"asthma-copd-pharmacology~ai-4","moduleId":"asthma-copd-pharmacology","stem":"Which drug is primarily used to manage severe eosinophilic asthma?","options":[{"id":"a","text":"Montelukast"},{"id":"b","text":"Omalizumab"},{"id":"c","text":"Salbutamol"},{"id":"d","text":"Tiotropium"}],"answerId":"b","explanation":"Omalizumab is a biologic that targets severe eosinophilic asthma by inhibiting IgE.","kind":"recall","origin":"ai"},{"id":"asthma-copd-pharmacology~ai-5","moduleId":"asthma-copd-pharmacology","stem":"In a patient with COPD, which medication is most effective for bronchodilation?","options":[{"id":"a","text":"Inhaled corticosteroids"},{"id":"b","text":"Short-acting β2-agonists"},{"id":"c","text":"Long-acting muscarinic antagonists"},{"id":"d","text":"Leukotriene receptor antagonists"}],"answerId":"c","explanation":"Long-acting muscarinic antagonists like tiotropium are effective bronchodilators in COPD management.","kind":"recall","origin":"ai"},{"id":"asthma-copd-pharmacology~ai-6","moduleId":"asthma-copd-pharmacology","stem":"How do leukotriene receptor antagonists like montelukast help in asthma management?","options":[{"id":"a","text":"Increase cAMP levels"},{"id":"b","text":"Block M3 receptors"},{"id":"c","text":"Reduce airway inflammation"},{"id":"d","text":"Enhance β2-agonist effects"}],"answerId":"c","explanation":"Leukotriene receptor antagonists reduce airway inflammation, particularly in aspirin-exacerbated asthma.","kind":"integration","linkedModuleIds":["asthma-bronchiectasis-pathology"],"origin":"ai"},{"id":"asthma-copd-pharmacology~ai-7","moduleId":"asthma-copd-pharmacology","stem":"What is the main therapeutic goal of using inhaled corticosteroids in asthma compared to bronchodilators?","options":[{"id":"a","text":"Immediate symptom relief"},{"id":"b","text":"Long-term control of inflammation"},{"id":"c","text":"Reduction of airway secretions"},{"id":"d","text":"Prevention of exercise-induced bronchospasm"}],"answerId":"b","explanation":"Inhaled corticosteroids focus on long-term control of airway inflammation, unlike bronchodilators that provide immediate relief.","kind":"integration","linkedModuleIds":["copd-emphysema-chronic-bronchitis"],"origin":"ai"}],"pleural-effusion-pneumothorax-mesothelioma":[{"id":"pleural-effusion-pneumothorax-mesothelioma~ai-0","moduleId":"pleural-effusion-pneumothorax-mesothelioma","stem":"What is the primary mechanism by which Light's criteria differentiate pleural effusions?","options":[{"id":"a","text":"Presence of infection"},{"id":"b","text":"Protein and LDH levels"},{"id":"c","text":"Cell count in pleural fluid"},{"id":"d","text":"Pleural fluid glucose levels"}],"answerId":"b","explanation":"Light's criteria use protein and LDH levels to classify pleural effusions as transudates or exudates.","kind":"mechanism","origin":"ai"},{"id":"pleural-effusion-pneumothorax-mesothelioma~ai-1","moduleId":"pleural-effusion-pneumothorax-mesothelioma","stem":"A patient presents with hypotension, tracheal deviation away from the midline, and absent breath sounds on the left side. What is the most likely diagnosis?","options":[{"id":"a","text":"Pleural effusion"},{"id":"b","text":"Tension pneumothorax"},{"id":"c","text":"Empyema"},{"id":"d","text":"Chylothorax"}],"answerId":"b","explanation":"These findings are classic for tension pneumothorax, which is a medical emergency.","kind":"recall","origin":"ai"},{"id":"pleural-effusion-pneumothorax-mesothelioma~ai-2","moduleId":"pleural-effusion-pneumothorax-mesothelioma","stem":"Which of the following is a characteristic finding in empyema?","options":[{"id":"a","text":"High glucose levels"},{"id":"b","text":"Low pH and high LDH"},{"id":"c","text":"Milky pleural fluid"},{"id":"d","text":"Transudative effusion"}],"answerId":"b","explanation":"Empyema is characterized by low glucose, low pH, and high LDH in the pleural fluid.","kind":"recall","origin":"ai"},{"id":"pleural-effusion-pneumothorax-mesothelioma~ai-3","moduleId":"pleural-effusion-pneumothorax-mesothelioma","stem":"What is the first step in managing a suspected tension pneumothorax?","options":[{"id":"a","text":"Obtain a chest X-ray"},{"id":"b","text":"Administer oxygen"},{"id":"c","text":"Perform needle decompression"},{"id":"d","text":"Start IV fluids"}],"answerId":"c","explanation":"Needle decompression is the immediate treatment for tension pneumothorax; waiting for imaging can be fatal.","kind":"trap","origin":"ai"},{"id":"pleural-effusion-pneumothorax-mesothelioma~ai-4","moduleId":"pleural-effusion-pneumothorax-mesothelioma","stem":"Which type of pleural effusion is most commonly associated with malignancy?","options":[{"id":"a","text":"Transudate"},{"id":"b","text":"Chylothorax"},{"id":"c","text":"Empyema"},{"id":"d","text":"Exudate"}],"answerId":"d","explanation":"Malignant effusions are typically exudates due to increased permeability associated with cancer.","kind":"recall","origin":"ai"},{"id":"pleural-effusion-pneumothorax-mesothelioma~ai-5","moduleId":"pleural-effusion-pneumothorax-mesothelioma","stem":"A patient with a history of asbestos exposure presents with recurrent pleural effusions and chest pain. What is the most likely diagnosis?","options":[{"id":"a","text":"Bronchogenic carcinoma"},{"id":"b","text":"Malignant mesothelioma"},{"id":"c","text":"Chylothorax"},{"id":"d","text":"Tuberculosis"}],"answerId":"b","explanation":"Malignant mesothelioma is strongly linked to asbestos exposure and presents with recurrent effusions.","kind":"clinical","origin":"ai"},{"id":"pleural-effusion-pneumothorax-mesothelioma~ai-6","moduleId":"pleural-effusion-pneumothorax-mesothelioma","stem":"How does the management of pleural effusion differ from that of tension pneumothorax?","options":[{"id":"a","text":"Both require immediate drainage"},{"id":"b","text":"Tension pneumothorax is treated without imaging"},{"id":"c","text":"Pleural effusion always requires surgery"},{"id":"d","text":"Tension pneumothorax is a chronic condition"}],"answerId":"b","explanation":"Tension pneumothorax is treated immediately without imaging, while pleural effusion management may involve imaging and analysis.","kind":"integration","linkedModuleIds":["chest-radiograph-interpretation"],"origin":"ai"},{"id":"pleural-effusion-pneumothorax-mesothelioma~ai-7","moduleId":"pleural-effusion-pneumothorax-mesothelioma","stem":"What is the relationship between malignant mesothelioma and pleural effusions?","options":[{"id":"a","text":"Mesothelioma causes transudative effusions"},{"id":"b","text":"Pleural effusions are a rare complication of mesothelioma"},{"id":"c","text":"Malignant mesothelioma often leads to recurrent exudative effusions"},{"id":"d","text":"Mesothelioma is unrelated to pleural effusions"}],"answerId":"c","explanation":"Malignant mesothelioma often leads to recurrent exudative pleural effusions due to tumor-related changes in the pleura.","kind":"integration","linkedModuleIds":["non-small-cell-lung-carcinoma"],"origin":"ai"}],"anti-tuberculosis-drugs":[{"id":"anti-tuberculosis-drugs~ai-0","moduleId":"anti-tuberculosis-drugs","stem":"Which of the following drugs is a potent CYP450 inducer and can cause orange-red discoloration of secretions?","options":[{"id":"a","text":"Rifampin"},{"id":"b","text":"Isoniazid"},{"id":"c","text":"Pyrazinamide"},{"id":"d","text":"Ethambutol"}],"answerId":"a","explanation":"Rifampin is known for its ability to induce CYP450 enzymes and causes orange-red discoloration of urine and tears.","kind":"recall","origin":"ai"},{"id":"anti-tuberculosis-drugs~ai-1","moduleId":"anti-tuberculosis-drugs","stem":"What is the primary mechanism of action of isoniazid?","options":[{"id":"a","text":"Inhibits DNA-dependent RNA polymerase"},{"id":"b","text":"Inhibits mycolic acid synthesis"},{"id":"c","text":"Inhibits arabinosyltransferase"},{"id":"d","text":"Inhibits protein synthesis"}],"answerId":"b","explanation":"Isoniazid works by inhibiting the synthesis of mycolic acids, which are essential components of the mycobacterial cell wall.","kind":"mechanism","origin":"ai"},{"id":"anti-tuberculosis-drugs~ai-2","moduleId":"anti-tuberculosis-drugs","stem":"A patient on anti-tuberculosis therapy presents with red-green color vision loss. Which drug is most likely responsible?","options":[{"id":"a","text":"Rifampin"},{"id":"b","text":"Isoniazid"},{"id":"c","text":"Ethambutol"},{"id":"d","text":"Pyrazinamide"}],"answerId":"c","explanation":"Ethambutol is associated with optic neuritis, which can lead to red-green color vision loss.","kind":"recall","origin":"ai"},{"id":"anti-tuberculosis-drugs~ai-3","moduleId":"anti-tuberculosis-drugs","stem":"Which of the following statements about isoniazid-induced peripheral neuropathy is correct?","options":[{"id":"a","text":"It requires immediate cessation of the drug."},{"id":"b","text":"It is caused by vitamin B6 deficiency."},{"id":"c","text":"It is irreversible once it occurs."},{"id":"d","text":"It is not preventable."}],"answerId":"b","explanation":"Isoniazid interferes with pyridoxine metabolism, and peripheral neuropathy can be prevented with vitamin B6 supplementation.","kind":"trap","origin":"ai"},{"id":"anti-tuberculosis-drugs~ai-4","moduleId":"anti-tuberculosis-drugs","stem":"What is the recommended treatment for latent tuberculosis infection?","options":[{"id":"a","text":"Rifampin alone"},{"id":"b","text":"Isoniazid alone"},{"id":"c","text":"Rifampin and isoniazid"},{"id":"d","text":"Ethambutol alone"}],"answerId":"b","explanation":"Isoniazid is the standard treatment for latent TB, often given alone or with rifapentine for a shorter duration.","kind":"recall","origin":"ai"},{"id":"anti-tuberculosis-drugs~ai-5","moduleId":"anti-tuberculosis-drugs","stem":"A patient with tuberculosis is started on a regimen including pyrazinamide. What is a common side effect of this drug?","options":[{"id":"a","text":"Hepatotoxicity"},{"id":"b","text":"Optic neuritis"},{"id":"c","text":"Peripheral neuropathy"},{"id":"d","text":"Gastrointestinal bleeding"}],"answerId":"a","explanation":"Pyrazinamide is known to cause hepatotoxicity as a common side effect.","kind":"recall","origin":"ai"},{"id":"anti-tuberculosis-drugs~ai-6","moduleId":"anti-tuberculosis-drugs","stem":"In treating a patient with multidrug-resistant tuberculosis (MDR-TB), which of the following drug classes is commonly used?","options":[{"id":"a","text":"Fluoroquinolones"},{"id":"b","text":"Beta-lactams"},{"id":"c","text":"Macrolides"},{"id":"d","text":"Tetracyclines"}],"answerId":"a","explanation":"Fluoroquinolones are part of the second-line treatment options for MDR-TB.","kind":"integration","linkedModuleIds":["tuberculosis-clinical-latent-mdr"],"origin":"ai"},{"id":"anti-tuberculosis-drugs~ai-7","moduleId":"anti-tuberculosis-drugs","stem":"Which of the following findings would suggest a diagnosis of active tuberculosis rather than latent tuberculosis?","options":[{"id":"a","text":"Positive tuberculin skin test"},{"id":"b","text":"Cough with hemoptysis"},{"id":"c","text":"History of BCG vaccination"},{"id":"d","text":"Positive IGRA test"}],"answerId":"b","explanation":"Cough with hemoptysis is a clinical sign indicative of active tuberculosis, while the other options may be associated with latent TB.","kind":"integration","linkedModuleIds":["tuberculosis-pathology"],"origin":"ai"}],"esophageal-disorders-pathology":[{"id":"esophageal-disorders-pathology~ai-0","moduleId":"esophageal-disorders-pathology","stem":"What is the primary mechanism underlying achalasia?","options":[{"id":"a","text":"Degeneration of myenteric plexus inhibitory neurons"},{"id":"b","text":"Increased lower esophageal sphincter tone"},{"id":"c","text":"Inflammation of the esophageal mucosa"},{"id":"d","text":"Obstruction by a mass lesion"}],"answerId":"a","explanation":"Achalasia is caused by degeneration of the myenteric plexus, leading to failure of the lower esophageal sphincter to relax.","kind":"mechanism","origin":"ai"},{"id":"esophageal-disorders-pathology~ai-1","moduleId":"esophageal-disorders-pathology","stem":"Which histological finding is characteristic of Barrett esophagus?","options":[{"id":"a","text":"Stratified squamous epithelium"},{"id":"b","text":"Intestinal metaplasia with goblet cells"},{"id":"c","text":"Dysplastic squamous cells"},{"id":"d","text":"Lymphocytic infiltration"}],"answerId":"b","explanation":"Barrett esophagus is defined by intestinal metaplasia, which includes the presence of goblet cells.","kind":"recall","origin":"ai"},{"id":"esophageal-disorders-pathology~ai-2","moduleId":"esophageal-disorders-pathology","stem":"A patient presents with dysphagia to both solids and liquids. What is the most likely diagnosis?","options":[{"id":"a","text":"Esophageal cancer"},{"id":"b","text":"Achalasia"},{"id":"c","text":"Esophageal stricture"},{"id":"d","text":"Gastroesophageal reflux disease"}],"answerId":"b","explanation":"Dysphagia to both solids and liquids from the outset suggests a motility disorder like achalasia, rather than a mechanical obstruction.","kind":"trap","origin":"ai"},{"id":"esophageal-disorders-pathology~ai-3","moduleId":"esophageal-disorders-pathology","stem":"What is the most common cause of esophageal varices?","options":[{"id":"a","text":"Portal hypertension due to cirrhosis"},{"id":"b","text":"Acute pancreatitis"},{"id":"c","text":"Esophageal cancer"},{"id":"d","text":"Chronic gastroesophageal reflux disease"}],"answerId":"a","explanation":"Esophageal varices are primarily caused by portal hypertension, often due to cirrhosis.","kind":"recall","origin":"ai"},{"id":"esophageal-disorders-pathology~ai-4","moduleId":"esophageal-disorders-pathology","stem":"A patient with a history of heavy alcohol use presents with hematemesis after forceful retching. What is the likely diagnosis?","options":[{"id":"a","text":"Boerhaave syndrome"},{"id":"b","text":"Mallory-Weiss tear"},{"id":"c","text":"Esophageal varices rupture"},{"id":"d","text":"Achalasia"}],"answerId":"b","explanation":"A Mallory-Weiss tear is a laceration at the gastroesophageal junction due to forceful vomiting, commonly seen in alcoholics.","kind":"clinical","origin":"ai"},{"id":"esophageal-disorders-pathology~ai-5","moduleId":"esophageal-disorders-pathology","stem":"How does Barrett esophagus increase the risk of adenocarcinoma?","options":[{"id":"a","text":"By causing dysphagia"},{"id":"b","text":"Through intestinal metaplasia"},{"id":"c","text":"By increasing acid reflux"},{"id":"d","text":"Through esophageal varices"}],"answerId":"b","explanation":"Barrett esophagus involves intestinal metaplasia, which is a key premalignant change leading to adenocarcinoma.","kind":"mechanism","origin":"ai"},{"id":"esophageal-disorders-pathology~ai-6","moduleId":"esophageal-disorders-pathology","stem":"How does portal hypertension lead to esophageal varices?","options":[{"id":"a","text":"Increased blood flow to the esophagus"},{"id":"b","text":"Increased pressure in the portal venous system"},{"id":"c","text":"Decreased blood flow to the liver"},{"id":"d","text":"Increased production of gastric acid"}],"answerId":"b","explanation":"Portal hypertension causes increased pressure in the portal venous system, leading to the dilation of submucosal veins in the esophagus.","kind":"integration","linkedModuleIds":["cirrhosis-fatty-liver-portal-hypertension"],"origin":"ai"},{"id":"esophageal-disorders-pathology~ai-7","moduleId":"esophageal-disorders-pathology","stem":"What is the relationship between gastroesophageal reflux disease (GERD) and Barrett esophagus?","options":[{"id":"a","text":"GERD causes squamous cell carcinoma"},{"id":"b","text":"Barrett esophagus is a complication of GERD"},{"id":"c","text":"Barrett esophagus prevents GERD"},{"id":"d","text":"GERD is unrelated to Barrett esophagus"}],"answerId":"b","explanation":"Barrett esophagus is a complication of chronic GERD, characterized by intestinal metaplasia in the esophagus.","kind":"integration","linkedModuleIds":["metaplasia-dysplasia"],"origin":"ai"}],"tuberculosis-clinical-latent-mdr":[{"id":"tuberculosis-clinical-latent-mdr~ai-0","moduleId":"tuberculosis-clinical-latent-mdr","stem":"What is the gold standard for diagnosing active pulmonary tuberculosis?","options":[{"id":"a","text":"Sputum culture"},{"id":"b","text":"Chest X-ray"},{"id":"c","text":"Tuberculin skin test"},{"id":"d","text":"Interferon-γ release assay"}],"answerId":"a","explanation":"Sputum culture is the gold standard for diagnosing active pulmonary tuberculosis as it confirms the presence of Mycobacterium tuberculosis.","kind":"recall","origin":"ai"},{"id":"tuberculosis-clinical-latent-mdr~ai-1","moduleId":"tuberculosis-clinical-latent-mdr","stem":"Which of the following findings is characteristic of latent tuberculosis infection?","options":[{"id":"a","text":"Chronic cough"},{"id":"b","text":"Positive IGRA with normal CXR"},{"id":"c","text":"Drenching night sweats"},{"id":"d","text":"Hemoptysis"}],"answerId":"b","explanation":"A positive IGRA with a normal chest X-ray indicates latent tuberculosis infection, as there are no active symptoms.","kind":"recall","origin":"ai"},{"id":"tuberculosis-clinical-latent-mdr~ai-2","moduleId":"tuberculosis-clinical-latent-mdr","stem":"What mechanism underlies the delayed hypersensitivity reaction in the tuberculin skin test?","options":[{"id":"a","text":"Type I hypersensitivity"},{"id":"b","text":"Type II hypersensitivity"},{"id":"c","text":"Type III hypersensitivity"},{"id":"d","text":"Type IV hypersensitivity"}],"answerId":"d","explanation":"The tuberculin skin test measures a type IV hypersensitivity reaction, which is mediated by T cells.","kind":"mechanism","origin":"ai"},{"id":"tuberculosis-clinical-latent-mdr~ai-3","moduleId":"tuberculosis-clinical-latent-mdr","stem":"A patient with a positive IGRA test presents with a normal chest X-ray and no symptoms. What is the most appropriate next step?","options":[{"id":"a","text":"Start anti-TB treatment"},{"id":"b","text":"Monitor without treatment"},{"id":"c","text":"Perform a sputum smear"},{"id":"d","text":"Refer for further imaging"}],"answerId":"b","explanation":"In the absence of active disease, the appropriate management is to monitor without treatment for latent TB.","kind":"clinical","origin":"ai"},{"id":"tuberculosis-clinical-latent-mdr~ai-4","moduleId":"tuberculosis-clinical-latent-mdr","stem":"Which of the following is a common complication of starting anti-TNF therapy in patients with latent TB?","options":[{"id":"a","text":"Reactivation of latent TB"},{"id":"b","text":"Development of drug-resistant TB"},{"id":"c","text":"Acute pulmonary embolism"},{"id":"d","text":"Worsening asthma"}],"answerId":"a","explanation":"Anti-TNF therapy can reactivate latent TB due to immunosuppression, leading to active disease.","kind":"trap","origin":"ai"},{"id":"tuberculosis-clinical-latent-mdr~ai-5","moduleId":"tuberculosis-clinical-latent-mdr","stem":"What is the mechanism of action of isoniazid in treating tuberculosis?","options":[{"id":"a","text":"Inhibits cell wall synthesis"},{"id":"b","text":"Inhibits RNA synthesis"},{"id":"c","text":"Inhibits protein synthesis"},{"id":"d","text":"Inhibits folate synthesis"}],"answerId":"a","explanation":"Isoniazid inhibits cell wall synthesis by targeting the mycolic acid component of the Mycobacterium tuberculosis cell wall.","kind":"mechanism","origin":"ai"},{"id":"tuberculosis-clinical-latent-mdr~ai-6","moduleId":"tuberculosis-clinical-latent-mdr","stem":"How does directly observed therapy (DOT) improve tuberculosis treatment outcomes?","options":[{"id":"a","text":"Reduces drug side effects"},{"id":"b","text":"Ensures adherence to the treatment regimen"},{"id":"c","text":"Increases drug potency"},{"id":"d","text":"Shortens treatment duration"}],"answerId":"b","explanation":"DOT improves treatment outcomes by ensuring adherence, which is crucial in preventing drug resistance.","kind":"clinical","origin":"ai"},{"id":"tuberculosis-clinical-latent-mdr~ai-7","moduleId":"tuberculosis-clinical-latent-mdr","stem":"A patient with MDR-TB is being treated. Which of the following drugs is most likely included in their regimen?","options":[{"id":"a","text":"Rifampin"},{"id":"b","text":"Isoniazid"},{"id":"c","text":"Bedaquiline"},{"id":"d","text":"Ethambutol"}],"answerId":"c","explanation":"Bedaquiline is a second-line agent used in the treatment of multidrug-resistant tuberculosis.","kind":"recall","origin":"ai"},{"id":"tuberculosis-clinical-latent-mdr~ai-8","moduleId":"tuberculosis-clinical-latent-mdr","stem":"How does the pathology of tuberculosis relate to its clinical presentation?","options":[{"id":"a","text":"Granuloma formation leads to chronic cough"},{"id":"b","text":"Acute inflammation causes hemoptysis"},{"id":"c","text":"Cavitary lesions prevent weight loss"},{"id":"d","text":"Fibrosis eliminates night sweats"}],"answerId":"a","explanation":"Granuloma formation in tuberculosis leads to chronic cough and other symptoms due to lung tissue damage.","kind":"integration","linkedModuleIds":["tuberculosis-pathology"],"origin":"ai"}],"respiratory-clinical-approach":[{"id":"respiratory-clinical-approach~ai-0","moduleId":"respiratory-clinical-approach","stem":"What is the most likely diagnosis for a patient presenting with dullness to percussion, bronchial breathing, increased vocal resonance, and crackles?","options":[{"id":"a","text":"Pleural effusion"},{"id":"b","text":"Pneumonia"},{"id":"c","text":"Pneumothorax"},{"id":"d","text":"Bronchiectasis"}],"answerId":"b","explanation":"These findings are characteristic of consolidation, which is typically seen in pneumonia.","kind":"clinical","origin":"ai"},{"id":"respiratory-clinical-approach~ai-1","moduleId":"respiratory-clinical-approach","stem":"Which of the following symptoms is most indicative of a pleural effusion?","options":[{"id":"a","text":"Cough with purulent sputum"},{"id":"b","text":"Stony dullness to percussion"},{"id":"c","text":"Wheezing on expiration"},{"id":"d","text":"Rusty sputum"}],"answerId":"b","explanation":"Stony dullness to percussion is a classic sign of pleural effusion.","kind":"recall","origin":"ai"},{"id":"respiratory-clinical-approach~ai-2","moduleId":"respiratory-clinical-approach","stem":"In a patient with suspected asthma, which finding would most likely indicate an exacerbation?","options":[{"id":"a","text":"Cyanosis"},{"id":"b","text":"Dullness to percussion"},{"id":"c","text":"Increased vocal resonance"},{"id":"d","text":"Fine crackles"}],"answerId":"a","explanation":"Cyanosis indicates hypoxemia, which can occur during an asthma exacerbation.","kind":"clinical","origin":"ai"},{"id":"respiratory-clinical-approach~ai-3","moduleId":"respiratory-clinical-approach","stem":"What is the mechanism behind increased vocal resonance in pneumonia?","options":[{"id":"a","text":"Fluid in the pleural space"},{"id":"b","text":"Consolidation of lung tissue"},{"id":"c","text":"Air trapping in the alveoli"},{"id":"d","text":"Bronchial obstruction"}],"answerId":"b","explanation":"Consolidation allows sound to be transmitted more effectively, resulting in increased vocal resonance.","kind":"mechanism","origin":"ai"},{"id":"respiratory-clinical-approach~ai-4","moduleId":"respiratory-clinical-approach","stem":"Which of the following is a key differentiating factor between pleural effusion and pneumonia on examination?","options":[{"id":"a","text":"Presence of wheezing"},{"id":"b","text":"Increased vocal resonance"},{"id":"c","text":"Dullness to percussion"},{"id":"d","text":"Cyanosis"}],"answerId":"b","explanation":"In pneumonia, dullness to percussion is accompanied by increased vocal resonance, while pleural effusion has absent or reduced breath sounds.","kind":"trap","origin":"ai"},{"id":"respiratory-clinical-approach~ai-5","moduleId":"respiratory-clinical-approach","stem":"A patient with a history of asthma presents with acute dyspnea and wheezing. Which diagnostic test would be most useful to assess their lung function?","options":[{"id":"a","text":"Chest X-ray"},{"id":"b","text":"ABG analysis"},{"id":"c","text":"Spirometry"},{"id":"d","text":"CT scan"}],"answerId":"c","explanation":"Spirometry is the primary test to evaluate lung function and assess the severity of asthma.","kind":"integration","linkedModuleIds":["pulmonary-function-tests-interpretation"],"origin":"ai"},{"id":"respiratory-clinical-approach~ai-6","moduleId":"respiratory-clinical-approach","stem":"In a patient with suspected bronchiectasis, which examination finding would you expect to see?","options":[{"id":"a","text":"Finger clubbing"},{"id":"b","text":"Stony dullness"},{"id":"c","text":"Hyper-resonance"},{"id":"d","text":"Cyanosis"}],"answerId":"a","explanation":"Finger clubbing is commonly associated with bronchiectasis due to chronic lung disease.","kind":"integration","linkedModuleIds":["asthma-bronchiectasis-pathology"],"origin":"ai"}],"chest-ct-imaging-patterns":[{"id":"chest-ct-imaging-patterns~ai-0","moduleId":"chest-ct-imaging-patterns","stem":"What is the characteristic imaging finding of pulmonary embolism on CT?","options":[{"id":"a","text":"Bilateral peripheral ground-glass opacities"},{"id":"b","text":"Filling defect in the pulmonary arteries"},{"id":"c","text":"Consolidation with air bronchograms"},{"id":"d","text":"Tree-in-bud nodularity"}],"answerId":"b","explanation":"A filling defect in the pulmonary arteries on CT pulmonary angiography (CTPA) indicates pulmonary embolism.","kind":"recall","origin":"ai"},{"id":"chest-ct-imaging-patterns~ai-1","moduleId":"chest-ct-imaging-patterns","stem":"Which CT pattern is associated with idiopathic pulmonary fibrosis?","options":[{"id":"a","text":"Ground-glass opacity"},{"id":"b","text":"Consolidation"},{"id":"c","text":"Honeycombing with traction bronchiectasis"},{"id":"d","text":"Tree-in-bud nodules"}],"answerId":"c","explanation":"Honeycombing with traction bronchiectasis is characteristic of the UIP pattern seen in idiopathic pulmonary fibrosis.","kind":"recall","origin":"ai"},{"id":"chest-ct-imaging-patterns~ai-2","moduleId":"chest-ct-imaging-patterns","stem":"What is the mechanism behind ground-glass opacities seen on CT?","options":[{"id":"a","text":"Airspace filling"},{"id":"b","text":"Vascular congestion"},{"id":"c","text":"Pleural effusion"},{"id":"d","text":"Bronchial obstruction"}],"answerId":"a","explanation":"Ground-glass opacities represent partial airspace filling due to various conditions like infection or edema.","kind":"mechanism","origin":"ai"},{"id":"chest-ct-imaging-patterns~ai-3","moduleId":"chest-ct-imaging-patterns","stem":"A patient presents with fever and cough. CT shows consolidation with air bronchograms. What is the most likely diagnosis?","options":[{"id":"a","text":"Pulmonary embolism"},{"id":"b","text":"Pneumonia"},{"id":"c","text":"Interstitial lung disease"},{"id":"d","text":"Lung cancer"}],"answerId":"b","explanation":"Consolidation with air bronchograms is indicative of pneumonia, where airspaces are filled with fluid or pus.","kind":"clinical","origin":"ai"},{"id":"chest-ct-imaging-patterns~ai-4","moduleId":"chest-ct-imaging-patterns","stem":"Which CT protocol is inappropriate for diagnosing pulmonary embolism?","options":[{"id":"a","text":"CT pulmonary angiography (CTPA)"},{"id":"b","text":"High-resolution CT (HRCT)"},{"id":"c","text":"Contrast-enhanced CT"},{"id":"d","text":"Standard CT scan"}],"answerId":"b","explanation":"High-resolution CT (HRCT) is not suitable for pulmonary embolism as it is designed for assessing interstitial lung disease.","kind":"trap","origin":"ai"},{"id":"chest-ct-imaging-patterns~ai-5","moduleId":"chest-ct-imaging-patterns","stem":"How does the imaging pattern of lung cancer differ from that of pneumonia on CT?","options":[{"id":"a","text":"Lung cancer shows ground-glass opacity; pneumonia shows consolidation"},{"id":"b","text":"Lung cancer shows consolidation; pneumonia shows ground-glass opacity"},{"id":"c","text":"Lung cancer shows nodules; pneumonia shows air bronchograms"},{"id":"d","text":"Lung cancer shows tree-in-bud nodules; pneumonia shows honeycombing"}],"answerId":"c","explanation":"Lung cancer typically presents as nodules, while pneumonia is characterized by consolidation with air bronchograms.","kind":"integration","linkedModuleIds":["non-small-cell-lung-carcinoma"],"origin":"ai"},{"id":"chest-ct-imaging-patterns~ai-6","moduleId":"chest-ct-imaging-patterns","stem":"In a patient with suspected pulmonary embolism, which imaging modality should be prioritized?","options":[{"id":"a","text":"High-resolution CT"},{"id":"b","text":"CT pulmonary angiography"},{"id":"c","text":"Chest X-ray"},{"id":"d","text":"MRI of the chest"}],"answerId":"b","explanation":"CT pulmonary angiography (CTPA) is the preferred imaging modality for diagnosing pulmonary embolism.","kind":"integration","linkedModuleIds":["pulmonary-embolism-edema"],"origin":"ai"}],"mediastinal-masses":[{"id":"mediastinal-masses~ai-0","moduleId":"mediastinal-masses","stem":"What is the most common anterior mediastinal mass associated with myasthenia gravis?","options":[{"id":"a","text":"Thyroid goitre"},{"id":"b","text":"Thymoma"},{"id":"c","text":"Lymphoma"},{"id":"d","text":"Teratoma"}],"answerId":"b","explanation":"Thymoma is the classic anterior mediastinal mass linked to myasthenia gravis.","kind":"recall","origin":"ai"},{"id":"mediastinal-masses~ai-1","moduleId":"mediastinal-masses","stem":"A 25-year-old man presents with an anterior mediastinal mass and elevated β-hCG. What is the most likely diagnosis?","options":[{"id":"a","text":"Thymoma"},{"id":"b","text":"Lymphoma"},{"id":"c","text":"Teratoma"},{"id":"d","text":"Neuroblastoma"}],"answerId":"c","explanation":"Elevated β-hCG in a young man with an anterior mediastinal mass suggests a germ-cell tumor, most commonly a teratoma.","kind":"clinical","origin":"ai"},{"id":"mediastinal-masses~ai-2","moduleId":"mediastinal-masses","stem":"Which of the following findings is most indicative of superior vena cava (SVC) obstruction due to a mediastinal mass?","options":[{"id":"a","text":"Unilateral pleural effusion"},{"id":"b","text":"Facial plethora and distended neck veins"},{"id":"c","text":"Cough and hemoptysis"},{"id":"d","text":"Dysphagia"}],"answerId":"b","explanation":"Facial plethora and distended neck veins are classic signs of SVC obstruction.","kind":"recall","origin":"ai"},{"id":"mediastinal-masses~ai-3","moduleId":"mediastinal-masses","stem":"A child presents with a posterior mediastinal mass and elevated catecholamines. What is the most likely diagnosis?","options":[{"id":"a","text":"Thymoma"},{"id":"b","text":"Neuroblastoma"},{"id":"c","text":"Lymphoma"},{"id":"d","text":"Teratoma"}],"answerId":"b","explanation":"Neuroblastoma is a neurogenic tumor commonly found in the posterior mediastinum in children and can secrete catecholamines.","kind":"clinical","origin":"ai"},{"id":"mediastinal-masses~ai-4","moduleId":"mediastinal-masses","stem":"Which of the following is a common trap in localizing mediastinal masses?","options":[{"id":"a","text":"Neurogenic tumors arise in the anterior mediastinum"},{"id":"b","text":"Thymoma is associated with myasthenia gravis"},{"id":"c","text":"Lymphoma can present with B symptoms"},{"id":"d","text":"Teratomas can elevate AFP levels"}],"answerId":"a","explanation":"Neurogenic tumors arise in the posterior mediastinum, not the anterior, which is a common localization trap.","kind":"trap","origin":"ai"},{"id":"mediastinal-masses~ai-5","moduleId":"mediastinal-masses","stem":"How does sarcoidosis typically present in the mediastinum?","options":[{"id":"a","text":"Anterior mediastinal mass"},{"id":"b","text":"Hilar lymphadenopathy"},{"id":"c","text":"Posterior mediastinal mass"},{"id":"d","text":"Mediastinal teratoma"}],"answerId":"b","explanation":"Sarcoidosis commonly presents with hilar lymphadenopathy in the middle mediastinum.","kind":"integration","linkedModuleIds":["sarcoidosis-granulomatous-lung"],"origin":"ai"},{"id":"mediastinal-masses~ai-6","moduleId":"mediastinal-masses","stem":"What is a common complication of a large anterior mediastinal mass?","options":[{"id":"a","text":"Pulmonary embolism"},{"id":"b","text":"SVC obstruction"},{"id":"c","text":"Pneumothorax"},{"id":"d","text":"Pleural effusion"}],"answerId":"b","explanation":"A large anterior mediastinal mass can compress the SVC, leading to obstruction.","kind":"integration","linkedModuleIds":["great-vessels-mediastinal-nerves"],"origin":"ai"}],"respiratory-antiviral-drugs":[{"id":"respiratory-antiviral-drugs~ai-0","moduleId":"respiratory-antiviral-drugs","stem":"What is the primary mechanism of action of oseltamivir in treating influenza?","options":[{"id":"a","text":"Inhibition of viral RNA polymerase"},{"id":"b","text":"Neuraminidase inhibition"},{"id":"c","text":"Blocking viral entry"},{"id":"d","text":"Inhibition of viral protein synthesis"}],"answerId":"b","explanation":"Oseltamivir acts by inhibiting neuraminidase, preventing the release of new virions from infected cells.","kind":"mechanism","origin":"ai"},{"id":"respiratory-antiviral-drugs~ai-1","moduleId":"respiratory-antiviral-drugs","stem":"Which antiviral is contraindicated in influenza due to resistance?","options":[{"id":"a","text":"Oseltamivir"},{"id":"b","text":"Amantadine"},{"id":"c","text":"Zanamivir"},{"id":"d","text":"Baloxavir"}],"answerId":"b","explanation":"Amantadine is no longer recommended for influenza due to widespread resistance, particularly in influenza A.","kind":"recall","origin":"ai"},{"id":"respiratory-antiviral-drugs~ai-2","moduleId":"respiratory-antiviral-drugs","stem":"What is a significant risk when using ritonavir with nirmatrelvir?","options":[{"id":"a","text":"Increased viral replication"},{"id":"b","text":"Decreased antiviral efficacy"},{"id":"c","text":"Multiple drug interactions"},{"id":"d","text":"Increased risk of respiratory failure"}],"answerId":"c","explanation":"Ritonavir is a CYP inhibitor that can cause multiple drug interactions, complicating treatment regimens.","kind":"recall","origin":"ai"},{"id":"respiratory-antiviral-drugs~ai-3","moduleId":"respiratory-antiviral-drugs","stem":"In which phase of COVID-19 should dexamethasone be administered for maximum benefit?","options":[{"id":"a","text":"Early viral replication phase"},{"id":"b","text":"Late hyperinflammatory phase"},{"id":"c","text":"Asymptomatic phase"},{"id":"d","text":"Prophylactic phase"}],"answerId":"b","explanation":"Dexamethasone is effective in the late hyperinflammatory phase of severe COVID-19, not in the early viral replication phase.","kind":"trap","origin":"ai"},{"id":"respiratory-antiviral-drugs~ai-4","moduleId":"respiratory-antiviral-drugs","stem":"What is the role of palivizumab in respiratory infections?","options":[{"id":"a","text":"Treatment of RSV in adults"},{"id":"b","text":"Prophylaxis in high-risk infants"},{"id":"c","text":"Treatment of influenza"},{"id":"d","text":"General antiviral for all respiratory viruses"}],"answerId":"b","explanation":"Palivizumab is a monoclonal antibody used for prophylaxis against RSV in high-risk infants.","kind":"recall","origin":"ai"},{"id":"respiratory-antiviral-drugs~ai-5","moduleId":"respiratory-antiviral-drugs","stem":"Which antiviral agent is primarily used for COVID-19 and acts as an RNA polymerase inhibitor?","options":[{"id":"a","text":"Baloxavir"},{"id":"b","text":"Remdesivir"},{"id":"c","text":"Oseltamivir"},{"id":"d","text":"Ribavirin"}],"answerId":"b","explanation":"Remdesivir is an IV RNA polymerase inhibitor used for treating COVID-19.","kind":"recall","origin":"ai"},{"id":"respiratory-antiviral-drugs~ai-6","moduleId":"respiratory-antiviral-drugs","stem":"How do antiviral treatments for influenza and COVID-19 differ in their timing for effectiveness?","options":[{"id":"a","text":"Both are effective at any stage of infection"},{"id":"b","text":"Both should be started within 48 hours of symptom onset"},{"id":"c","text":"Influenza antivirals are effective only in severe cases"},{"id":"d","text":"COVID-19 antivirals are effective only in asymptomatic patients"}],"answerId":"b","explanation":"Both influenza and COVID-19 antivirals work best when started early, ideally within 48 hours of symptom onset.","kind":"integration","linkedModuleIds":["influenza-covid-pneumonia"],"origin":"ai"},{"id":"respiratory-antiviral-drugs~ai-7","moduleId":"respiratory-antiviral-drugs","stem":"What is a common feature of both antiviral and antibiotic treatments in respiratory infections?","options":[{"id":"a","text":"Both target viral replication"},{"id":"b","text":"Both are effective against all respiratory pathogens"},{"id":"c","text":"Both require early administration for effectiveness"},{"id":"d","text":"Both can be used interchangeably"}],"answerId":"c","explanation":"Both antiviral and antibiotic treatments require early administration for maximum effectiveness, though they target different pathogens.","kind":"integration","linkedModuleIds":["respiratory-tract-antibiotics"],"origin":"ai"}],"chest-radiograph-interpretation":[{"id":"chest-radiograph-interpretation~ai-0","moduleId":"chest-radiograph-interpretation","stem":"What is the first step in evaluating a chest X-ray?","options":[{"id":"a","text":"Assess the cardiac silhouette"},{"id":"b","text":"Check for air bronchograms"},{"id":"c","text":"Evaluate the adequacy using RIPE"},{"id":"d","text":"Look for pleural effusions"}],"answerId":"c","explanation":"The RIPE method ensures that the film is adequate for interpretation, preventing misdiagnosis due to technical artifacts.","kind":"recall","origin":"ai"},{"id":"chest-radiograph-interpretation~ai-1","moduleId":"chest-radiograph-interpretation","stem":"Which finding on a chest X-ray indicates consolidation?","options":[{"id":"a","text":"Blunted costophrenic angle"},{"id":"b","text":"Visible lung edge with lucency"},{"id":"c","text":"Air bronchograms within an opacity"},{"id":"d","text":"Loss of the left heart border"}],"answerId":"c","explanation":"Air bronchograms are indicative of airspace filling, which is characteristic of consolidation.","kind":"recall","origin":"ai"},{"id":"chest-radiograph-interpretation~ai-2","moduleId":"chest-radiograph-interpretation","stem":"What does the silhouette sign indicate when the right heart border is obscured?","options":[{"id":"a","text":"Right lower lobe pneumonia"},{"id":"b","text":"Right middle lobe pneumonia"},{"id":"c","text":"Left lower lobe pneumonia"},{"id":"d","text":"Left upper lobe pneumonia"}],"answerId":"b","explanation":"Loss of the right heart border suggests consolidation or collapse of the right middle lobe due to the silhouette sign.","kind":"mechanism","origin":"ai"},{"id":"chest-radiograph-interpretation~ai-3","moduleId":"chest-radiograph-interpretation","stem":"A patient presents with a chest X-ray showing a blunted costophrenic angle. What is the most likely diagnosis?","options":[{"id":"a","text":"Pneumothorax"},{"id":"b","text":"Pleural effusion"},{"id":"c","text":"Atelectasis"},{"id":"d","text":"Lung mass"}],"answerId":"b","explanation":"A blunted costophrenic angle with a meniscus is characteristic of pleural effusion.","kind":"recall","origin":"ai"},{"id":"chest-radiograph-interpretation~ai-4","moduleId":"chest-radiograph-interpretation","stem":"What is a common pitfall when interpreting heart size on a chest X-ray?","options":[{"id":"a","text":"Assuming all enlargements indicate true cardiomegaly"},{"id":"b","text":"Not checking for air bronchograms"},{"id":"c","text":"Ignoring the silhouette sign"},{"id":"d","text":"Misinterpreting a normal variant as a mass"}],"answerId":"a","explanation":"Technical factors can distort heart size; it's crucial to assess adequacy before concluding cardiomegaly.","kind":"trap","origin":"ai"},{"id":"chest-radiograph-interpretation~ai-5","moduleId":"chest-radiograph-interpretation","stem":"In a patient with ARDS, what chest X-ray finding would you expect?","options":[{"id":"a","text":"Air bronchograms within an opacity"},{"id":"b","text":"Lucent hemithorax"},{"id":"c","text":"Blunted costophrenic angles"},{"id":"d","text":"Loss of the right heart border"}],"answerId":"a","explanation":"ARDS typically presents with bilateral opacities and air bronchograms due to alveolar filling.","kind":"integration","linkedModuleIds":["ards-pulmonary-hypertension-atelectasis"],"origin":"ai"},{"id":"chest-radiograph-interpretation~ai-6","moduleId":"chest-radiograph-interpretation","stem":"Which chest X-ray finding is most indicative of atelectasis?","options":[{"id":"a","text":"Mediastinal shift towards the affected side"},{"id":"b","text":"Air bronchograms"},{"id":"c","text":"Blunted costophrenic angle"},{"id":"d","text":"Loss of the left heart border"}],"answerId":"a","explanation":"Atelectasis causes volume loss and mediastinal shift towards the affected lung due to collapse.","kind":"integration","linkedModuleIds":["ards-pulmonary-hypertension-atelectasis"],"origin":"ai"},{"id":"chest-radiograph-interpretation~ai-7","moduleId":"chest-radiograph-interpretation","stem":"What is the appearance of a pneumothorax on a chest X-ray?","options":[{"id":"a","text":"Consolidation with air bronchograms"},{"id":"b","text":"Blunted costophrenic angle"},{"id":"c","text":"Lucency with a visible lung edge"},{"id":"d","text":"Loss of diaphragm definition"}],"answerId":"c","explanation":"A pneumothorax appears as lucency with a visible lung edge and no vascular markings beyond it.","kind":"recall","origin":"ai"}],"respiratory-failure-oxygen-therapy":[{"id":"respiratory-failure-oxygen-therapy~ai-0","moduleId":"respiratory-failure-oxygen-therapy","stem":"What characterizes Type 1 (hypoxaemic) respiratory failure?","options":[{"id":"a","text":"Low PaO₂ with normal PaCO₂"},{"id":"b","text":"Low PaO₂ with high PaCO₂"},{"id":"c","text":"Normal PaO₂ with low PaCO₂"},{"id":"d","text":"Normal PaO₂ with high PaCO₂"}],"answerId":"a","explanation":"Type 1 respiratory failure is defined by low arterial oxygen levels (PaO₂) with normal or low carbon dioxide levels (PaCO₂).","kind":"recall","origin":"ai"},{"id":"respiratory-failure-oxygen-therapy~ai-1","moduleId":"respiratory-failure-oxygen-therapy","stem":"In chronic obstructive pulmonary disease (COPD), what is the target oxygen saturation range during controlled oxygen therapy?","options":[{"id":"a","text":"94–98%"},{"id":"b","text":"88–92%"},{"id":"c","text":"80–85%"},{"id":"d","text":"100%"}],"answerId":"b","explanation":"In COPD patients, controlled oxygen therapy should aim for a saturation of 88–92% to avoid worsening hypercapnia.","kind":"recall","origin":"ai"},{"id":"respiratory-failure-oxygen-therapy~ai-2","moduleId":"respiratory-failure-oxygen-therapy","stem":"Which mechanism explains the worsening hypercapnia in COPD patients receiving uncontrolled high-flow oxygen?","options":[{"id":"a","text":"Increased V/Q mismatch"},{"id":"b","text":"Decreased respiratory drive"},{"id":"c","text":"Increased dead space ventilation"},{"id":"d","text":"Decreased lung compliance"}],"answerId":"a","explanation":"Uncontrolled high-flow oxygen can worsen V/Q mismatch, leading to increased carbon dioxide retention in COPD patients.","kind":"mechanism","origin":"ai"},{"id":"respiratory-failure-oxygen-therapy~ai-3","moduleId":"respiratory-failure-oxygen-therapy","stem":"A patient with respiratory acidosis and COPD is treated with BiPAP. What is the primary purpose of this intervention?","options":[{"id":"a","text":"To improve oxygenation"},{"id":"b","text":"To support ventilation"},{"id":"c","text":"To decrease dead space"},{"id":"d","text":"To increase lung compliance"}],"answerId":"b","explanation":"BiPAP provides non-invasive ventilatory support, which is crucial for patients with type 2 respiratory failure like COPD exacerbation.","kind":"clinical","origin":"ai"},{"id":"respiratory-failure-oxygen-therapy~ai-4","moduleId":"respiratory-failure-oxygen-therapy","stem":"What is a common clinical finding in Type 2 (hypercapnic) respiratory failure?","options":[{"id":"a","text":"Low PaO₂ with normal PaCO₂"},{"id":"b","text":"Low PaO₂ with high PaCO₂"},{"id":"c","text":"Normal PaO₂ with high PaCO₂"},{"id":"d","text":"Normal PaO₂ with normal PaCO₂"}],"answerId":"b","explanation":"Type 2 respiratory failure is characterized by low PaO₂ accompanied by high PaCO₂, indicating ventilatory failure.","kind":"recall","origin":"ai"},{"id":"respiratory-failure-oxygen-therapy~ai-5","moduleId":"respiratory-failure-oxygen-therapy","stem":"A patient with ARDS presents with low PaO₂ and normal PaCO₂. What is the most appropriate initial treatment?","options":[{"id":"a","text":"Controlled oxygen therapy"},{"id":"b","text":"High-flow oxygen therapy"},{"id":"c","text":"Non-invasive ventilation"},{"id":"d","text":"Invasive mechanical ventilation"}],"answerId":"a","explanation":"In ARDS, the initial treatment focuses on correcting hypoxaemia with controlled oxygen therapy to maintain adequate oxygen saturation.","kind":"integration","linkedModuleIds":["ards-pulmonary-hypertension-atelectasis"],"origin":"ai"},{"id":"respiratory-failure-oxygen-therapy~ai-6","moduleId":"respiratory-failure-oxygen-therapy","stem":"How does the management of oxygen therapy differ between COPD and ARDS patients?","options":[{"id":"a","text":"COPD patients require higher oxygen levels"},{"id":"b","text":"ARDS patients require lower oxygen levels"},{"id":"c","text":"COPD patients need controlled oxygen therapy"},{"id":"d","text":"Both require high-flow oxygen therapy"}],"answerId":"c","explanation":"COPD patients need controlled oxygen therapy to avoid worsening hypercapnia, while ARDS patients typically require higher oxygen levels to correct hypoxaemia.","kind":"integration","linkedModuleIds":["copd-emphysema-chronic-bronchitis"],"origin":"ai"}],"inflammatory-bowel-disease":[{"id":"inflammatory-bowel-disease~ai-0","moduleId":"inflammatory-bowel-disease","stem":"Which of the following is a hallmark feature of Crohn's disease?","options":[{"id":"a","text":"Continuous mucosal inflammation"},{"id":"b","text":"Crypt abscesses"},{"id":"c","text":"Non-caseating granulomas"},{"id":"d","text":"Lead-pipe colon"}],"answerId":"c","explanation":"Crohn's disease is characterized by non-caseating granulomas, which are not seen in ulcerative colitis.","kind":"recall","origin":"ai"},{"id":"inflammatory-bowel-disease~ai-1","moduleId":"inflammatory-bowel-disease","stem":"What is the primary mechanism by which smoking affects ulcerative colitis?","options":[{"id":"a","text":"Increases inflammation"},{"id":"b","text":"Decreases inflammation"},{"id":"c","text":"Causes transmural damage"},{"id":"d","text":"Promotes fistula formation"}],"answerId":"b","explanation":"Smoking is known to have a protective effect in ulcerative colitis, reducing the frequency of flare-ups.","kind":"mechanism","origin":"ai"},{"id":"inflammatory-bowel-disease~ai-2","moduleId":"inflammatory-bowel-disease","stem":"A patient presents with bloody diarrhea, abdominal pain, and tenesmus. Colonoscopy reveals continuous mucosal inflammation starting from the rectum. What is the most likely diagnosis?","options":[{"id":"a","text":"Crohn's disease"},{"id":"b","text":"Ulcerative colitis"},{"id":"c","text":"Irritable bowel syndrome"},{"id":"d","text":"Diverticulitis"}],"answerId":"b","explanation":"The symptoms and colonoscopy findings are characteristic of ulcerative colitis, which starts in the rectum and extends continuously.","kind":"clinical","origin":"ai"},{"id":"inflammatory-bowel-disease~ai-3","moduleId":"inflammatory-bowel-disease","stem":"Which complication is most associated with ulcerative colitis?","options":[{"id":"a","text":"Fistula formation"},{"id":"b","text":"Toxic megacolon"},{"id":"c","text":"Gallstones"},{"id":"d","text":"Non-caseating granulomas"}],"answerId":"b","explanation":"Toxic megacolon is a serious complication associated with ulcerative colitis due to its mucosal inflammation.","kind":"trap","origin":"ai"},{"id":"inflammatory-bowel-disease~ai-4","moduleId":"inflammatory-bowel-disease","stem":"Which of the following findings would you expect in a patient with Crohn's disease affecting the terminal ileum?","options":[{"id":"a","text":"Pseudopolyps"},{"id":"b","text":"Fistulae"},{"id":"c","text":"Lead-pipe colon"},{"id":"d","text":"Crypt abscesses"}],"answerId":"b","explanation":"Fistulae are a common complication of Crohn's disease due to transmural inflammation, particularly in the terminal ileum.","kind":"recall","origin":"ai"},{"id":"inflammatory-bowel-disease~ai-5","moduleId":"inflammatory-bowel-disease","stem":"How does Crohn's disease increase the risk of gallstones?","options":[{"id":"a","text":"By causing bile salt malabsorption"},{"id":"b","text":"By leading to excessive bile production"},{"id":"c","text":"By promoting bacterial overgrowth"},{"id":"d","text":"By inducing chronic diarrhea"}],"answerId":"a","explanation":"Crohn's disease affecting the terminal ileum leads to bile salt malabsorption, which can result in gallstone formation.","kind":"integration","linkedModuleIds":["nutrition-energy-protein-malnutrition"],"origin":"ai"},{"id":"inflammatory-bowel-disease~ai-6","moduleId":"inflammatory-bowel-disease","stem":"What is a common extraintestinal manifestation of both Crohn's disease and ulcerative colitis?","options":[{"id":"a","text":"Fistulae"},{"id":"b","text":"Pseudopolyps"},{"id":"c","text":"Arthritis"},{"id":"d","text":"Toxic megacolon"}],"answerId":"c","explanation":"Arthritis is an extraintestinal manifestation that can occur in both Crohn's disease and ulcerative colitis.","kind":"integration","linkedModuleIds":["colorectal-polyps-carcinoma"],"origin":"ai"}],"gastric-carcinoma-lymphoma":[{"id":"gastric-carcinoma-lymphoma~ai-0","moduleId":"gastric-carcinoma-lymphoma","stem":"What is the primary histological feature of diffuse gastric carcinoma?","options":[{"id":"a","text":"Glandular formation"},{"id":"b","text":"Signet-ring cells"},{"id":"c","text":"Mucinous adenocarcinoma"},{"id":"d","text":"Keratin pearls"}],"answerId":"b","explanation":"Diffuse gastric carcinoma is characterized by the presence of signet-ring cells that infiltrate the gastric wall.","kind":"recall","origin":"ai"},{"id":"gastric-carcinoma-lymphoma~ai-1","moduleId":"gastric-carcinoma-lymphoma","stem":"Which type of gastric cancer is associated with chronic Helicobacter pylori infection?","options":[{"id":"a","text":"Gastric adenocarcinoma"},{"id":"b","text":"Gastric MALT lymphoma"},{"id":"c","text":"GIST"},{"id":"d","text":"Esophageal adenocarcinoma"}],"answerId":"b","explanation":"Gastric MALT lymphoma is driven by chronic Helicobacter pylori infection and can regress with its eradication.","kind":"recall","origin":"ai"},{"id":"gastric-carcinoma-lymphoma~ai-2","moduleId":"gastric-carcinoma-lymphoma","stem":"What is the mechanism behind the regression of early gastric MALT lymphoma?","options":[{"id":"a","text":"Chemotherapy-induced apoptosis"},{"id":"b","text":"H. pylori eradication"},{"id":"c","text":"Radiation therapy"},{"id":"d","text":"Surgical resection"}],"answerId":"b","explanation":"Early gastric MALT lymphoma can regress with the eradication of H. pylori, as the lymphoma is driven by chronic antigenic stimulation.","kind":"mechanism","origin":"ai"},{"id":"gastric-carcinoma-lymphoma~ai-3","moduleId":"gastric-carcinoma-lymphoma","stem":"A patient presents with a left supraclavicular lymph node enlargement. Which condition should be suspected?","options":[{"id":"a","text":"Gastric adenocarcinoma"},{"id":"b","text":"Gastric MALT lymphoma"},{"id":"c","text":"GIST"},{"id":"d","text":"Peptic ulcer disease"}],"answerId":"a","explanation":"A Virchow node (left supraclavicular node) is a classic sign of metastatic gastric carcinoma.","kind":"clinical","origin":"ai"},{"id":"gastric-carcinoma-lymphoma~ai-4","moduleId":"gastric-carcinoma-lymphoma","stem":"Which statement about treating gastric MALT lymphoma is correct?","options":[{"id":"a","text":"Chemotherapy is the first-line treatment."},{"id":"b","text":"H. pylori eradication can lead to regression."},{"id":"c","text":"Radiotherapy is preferred over antibiotics."},{"id":"d","text":"Surgical resection is necessary."}],"answerId":"b","explanation":"Early gastric MALT lymphoma often regresses with H. pylori eradication, making it a unique case where antibiotics can treat the cancer.","kind":"trap","origin":"ai"},{"id":"gastric-carcinoma-lymphoma~ai-5","moduleId":"gastric-carcinoma-lymphoma","stem":"What is the primary mutation associated with GIST tumors?","options":[{"id":"a","text":"TP53 mutation"},{"id":"b","text":"KIT (CD117) mutation"},{"id":"c","text":"EGFR mutation"},{"id":"d","text":"BRAF mutation"}],"answerId":"b","explanation":"GISTs are characterized by gain-of-function mutations in the KIT gene (CD117).","kind":"recall","origin":"ai"},{"id":"gastric-carcinoma-lymphoma~ai-6","moduleId":"gastric-carcinoma-lymphoma","stem":"How does chronic gastritis relate to gastric MALT lymphoma?","options":[{"id":"a","text":"It increases gastric acid secretion."},{"id":"b","text":"It can lead to H. pylori infection."},{"id":"c","text":"It causes intestinal metaplasia."},{"id":"d","text":"It is a precursor to gastric adenocarcinoma."}],"answerId":"b","explanation":"Chronic gastritis, particularly due to H. pylori infection, can lead to the development of gastric MALT lymphoma.","kind":"integration","linkedModuleIds":["gastritis-and-gastropathy"],"origin":"ai"},{"id":"gastric-carcinoma-lymphoma~ai-7","moduleId":"gastric-carcinoma-lymphoma","stem":"Which condition can result from the chronic inflammation seen in peptic ulcer disease?","options":[{"id":"a","text":"Gastric adenocarcinoma"},{"id":"b","text":"GIST"},{"id":"c","text":"Gastric MALT lymphoma"},{"id":"d","text":"Esophageal cancer"}],"answerId":"c","explanation":"Chronic inflammation from peptic ulcers can lead to gastric MALT lymphoma due to persistent H. pylori infection.","kind":"integration","linkedModuleIds":["peptic-ulcer-disease"],"origin":"ai"}],"liver-function-tests-interpretation":[{"id":"liver-function-tests-interpretation~ai-0","moduleId":"liver-function-tests-interpretation","stem":"What does a predominantly raised AST and ALT indicate?","options":[{"id":"a","text":"Cholestatic pattern"},{"id":"b","text":"Hepatocellular injury"},{"id":"c","text":"Synthetic function impairment"},{"id":"d","text":"Non-hepatic ALP source"}],"answerId":"b","explanation":"A predominantly raised AST and ALT indicates hepatocellular injury, reflecting damage to liver cells.","kind":"recall","origin":"ai"},{"id":"liver-function-tests-interpretation~ai-1","moduleId":"liver-function-tests-interpretation","stem":"An AST:ALT ratio greater than 2 is suggestive of which condition?","options":[{"id":"a","text":"Viral hepatitis"},{"id":"b","text":"Alcoholic liver disease"},{"id":"c","text":"Non-alcoholic fatty liver disease"},{"id":"d","text":"Cholestasis"}],"answerId":"b","explanation":"An AST:ALT ratio greater than 2 is typically indicative of alcoholic liver disease.","kind":"recall","origin":"ai"},{"id":"liver-function-tests-interpretation~ai-2","moduleId":"liver-function-tests-interpretation","stem":"Which test result indicates impaired hepatic synthetic function?","options":[{"id":"a","text":"Low albumin"},{"id":"b","text":"High AST"},{"id":"c","text":"Normal GGT"},{"id":"d","text":"Low bilirubin"}],"answerId":"a","explanation":"Low albumin levels indicate impaired hepatic synthetic function, reflecting chronic liver disease.","kind":"recall","origin":"ai"},{"id":"liver-function-tests-interpretation~ai-3","moduleId":"liver-function-tests-interpretation","stem":"A patient presents with jaundice and elevated ALP and GGT. What does this indicate?","options":[{"id":"a","text":"Hepatocellular injury"},{"id":"b","text":"Cholestatic pattern"},{"id":"c","text":"Synthetic function impairment"},{"id":"d","text":"Non-hepatic ALP source"}],"answerId":"b","explanation":"Elevated ALP and GGT indicate a cholestatic pattern, suggesting biliary obstruction or cholestasis.","kind":"clinical","origin":"ai"},{"id":"liver-function-tests-interpretation~ai-4","moduleId":"liver-function-tests-interpretation","stem":"What is a common misconception regarding liver function tests?","options":[{"id":"a","text":"ALP indicates synthetic function"},{"id":"b","text":"AST/ALT reflect liver injury"},{"id":"c","text":"Low albumin signifies liver failure"},{"id":"d","text":"High transaminases mean liver is functioning well"}],"answerId":"d","explanation":"High transaminases indicate liver injury, not synthetic function; a liver can have high transaminases yet still function well.","kind":"trap","origin":"ai"},{"id":"liver-function-tests-interpretation~ai-5","moduleId":"liver-function-tests-interpretation","stem":"In a patient with cholestatic liver disease, which pattern would you expect in liver function tests?","options":[{"id":"a","text":"High AST and ALT"},{"id":"b","text":"High ALP and GGT"},{"id":"c","text":"Low albumin and prolonged PT"},{"id":"d","text":"Normal bilirubin"}],"answerId":"b","explanation":"In cholestatic liver disease, ALP and GGT are predominantly elevated due to impaired bile flow.","kind":"recall","origin":"ai"},{"id":"liver-function-tests-interpretation~ai-6","moduleId":"liver-function-tests-interpretation","stem":"How does impaired bilirubin handling relate to liver function tests?","options":[{"id":"a","text":"Indicates cholestasis"},{"id":"b","text":"Reflects hepatocyte injury"},{"id":"c","text":"Suggests synthetic function impairment"},{"id":"d","text":"Confirms non-hepatic source"}],"answerId":"c","explanation":"Impaired bilirubin handling suggests synthetic function impairment, which is assessed alongside albumin and PT/INR.","kind":"integration","linkedModuleIds":["bilirubin-metabolism-jaundice"],"origin":"ai"},{"id":"liver-function-tests-interpretation~ai-7","moduleId":"liver-function-tests-interpretation","stem":"Which liver function test result would be most indicative of acute liver failure?","options":[{"id":"a","text":"High ALP"},{"id":"b","text":"Prolonged PT/INR"},{"id":"c","text":"Low AST"},{"id":"d","text":"Normal GGT"}],"answerId":"b","explanation":"Prolonged PT/INR is a sensitive marker of impaired synthetic function, indicating acute liver failure.","kind":"integration","linkedModuleIds":["pharmacology-in-liver-disease"],"origin":"ai"}],"gastrointestinal-bleeding-approach":[{"id":"gastrointestinal-bleeding-approach~ai-0","moduleId":"gastrointestinal-bleeding-approach","stem":"A 55-year-old man presents with vomiting blood and black, tarry stools. What is the most likely source of his gastrointestinal bleeding?","options":[{"id":"a","text":"Lower GI tract"},{"id":"b","text":"Upper GI tract"},{"id":"c","text":"Rectum"},{"id":"d","text":"Colon"}],"answerId":"b","explanation":"Haematemesis and melaena indicate an upper gastrointestinal source, typically proximal to the ligament of Treitz.","kind":"recall","origin":"ai"},{"id":"gastrointestinal-bleeding-approach~ai-1","moduleId":"gastrointestinal-bleeding-approach","stem":"Which of the following findings is most suggestive of an upper gastrointestinal bleed?","options":[{"id":"a","text":"Fresh red blood per rectum"},{"id":"b","text":"Black, tarry stools"},{"id":"c","text":"Abdominal pain"},{"id":"d","text":"Diarrhea"}],"answerId":"b","explanation":"Melaena (black, tarry stools) indicates that blood has been digested, suggesting an upper GI source.","kind":"recall","origin":"ai"},{"id":"gastrointestinal-bleeding-approach~ai-2","moduleId":"gastrointestinal-bleeding-approach","stem":"A patient presents with fresh red blood per rectum. Which condition is most likely responsible?","options":[{"id":"a","text":"Peptic ulcer disease"},{"id":"b","text":"Diverticulosis"},{"id":"c","text":"Oesophageal varices"},{"id":"d","text":"Mallory-Weiss tear"}],"answerId":"b","explanation":"Fresh red blood per rectum (haematochezia) is typically associated with lower GI bleeding, with diverticulosis being a common cause.","kind":"clinical","origin":"ai"},{"id":"gastrointestinal-bleeding-approach~ai-3","moduleId":"gastrointestinal-bleeding-approach","stem":"What is the first step in managing a patient with suspected gastrointestinal bleeding?","options":[{"id":"a","text":"Endoscopy"},{"id":"b","text":"IV fluid resuscitation"},{"id":"c","text":"CT scan"},{"id":"d","text":"Blood transfusion"}],"answerId":"b","explanation":"Initial management involves resuscitation with IV fluids and blood products to stabilize the patient before further diagnostic procedures.","kind":"mechanism","origin":"ai"},{"id":"gastrointestinal-bleeding-approach~ai-4","moduleId":"gastrointestinal-bleeding-approach","stem":"A 60-year-old woman with a history of cirrhosis presents with haematemesis. What is the most likely cause of her bleeding?","options":[{"id":"a","text":"Peptic ulcer"},{"id":"b","text":"Oesophageal varices"},{"id":"c","text":"Diverticulosis"},{"id":"d","text":"Gastritis"}],"answerId":"b","explanation":"In patients with cirrhosis, haematemesis is most commonly due to bleeding from oesophageal varices secondary to portal hypertension.","kind":"clinical","origin":"ai"},{"id":"gastrointestinal-bleeding-approach~ai-5","moduleId":"gastrointestinal-bleeding-approach","stem":"Which of the following statements about melaena is FALSE?","options":[{"id":"a","text":"It indicates an upper GI source."},{"id":"b","text":"It can be caused by slow right-colon bleeding."},{"id":"c","text":"It is characterized by fresh red blood."},{"id":"d","text":"It suggests digested blood in the stool."}],"answerId":"c","explanation":"Melaena is characterized by black, tarry stools, indicating digested blood, not fresh red blood.","kind":"trap","origin":"ai"},{"id":"gastrointestinal-bleeding-approach~ai-6","moduleId":"gastrointestinal-bleeding-approach","stem":"A patient with diverticulosis presents with brisk lower gastrointestinal bleeding. Which linked condition should you consider in your differential diagnosis?","options":[{"id":"a","text":"Gastritis"},{"id":"b","text":"Colorectal cancer"},{"id":"c","text":"Peptic ulcer disease"},{"id":"d","text":"Oesophageal varices"}],"answerId":"b","explanation":"Colorectal cancer is a significant consideration in patients with diverticulosis, especially in the context of lower GI bleeding.","kind":"integration","linkedModuleIds":["colorectal-polyps-carcinoma"],"origin":"ai"},{"id":"gastrointestinal-bleeding-approach~ai-7","moduleId":"gastrointestinal-bleeding-approach","stem":"In a patient with upper gastrointestinal bleeding, which linked condition could also lead to similar symptoms?","options":[{"id":"a","text":"Diverticulitis"},{"id":"b","text":"Gastritis"},{"id":"c","text":"Appendicitis"},{"id":"d","text":"Ischaemic colitis"}],"answerId":"b","explanation":"Gastritis can cause upper GI bleeding, similar to peptic ulcers, and is relevant in the context of upper GI symptoms.","kind":"integration","linkedModuleIds":["gastritis-and-gastropathy"],"origin":"ai"}],"gastritis-and-gastropathy":[{"id":"gastritis-and-gastropathy~ai-0","moduleId":"gastritis-and-gastropathy","stem":"What is the most common cause of chronic gastritis?","options":[{"id":"a","text":"Autoimmune disease"},{"id":"b","text":"H. pylori infection"},{"id":"c","text":"NSAID use"},{"id":"d","text":"Alcohol consumption"}],"answerId":"b","explanation":"H. pylori infection is the leading cause of chronic gastritis, particularly affecting the antrum of the stomach.","kind":"recall","origin":"ai"},{"id":"gastritis-and-gastropathy~ai-1","moduleId":"gastritis-and-gastropathy","stem":"Which mechanism explains the gastric mucosal injury caused by NSAIDs?","options":[{"id":"a","text":"Increased gastric acid secretion"},{"id":"b","text":"Inhibition of prostaglandin synthesis"},{"id":"c","text":"Direct mucosal irritation"},{"id":"d","text":"Increased bile acid secretion"}],"answerId":"b","explanation":"NSAIDs inhibit prostaglandin synthesis, which reduces mucosal defense and leads to gastric injury.","kind":"mechanism","origin":"ai"},{"id":"gastritis-and-gastropathy~ai-2","moduleId":"gastritis-and-gastropathy","stem":"A patient presents with achlorhydria and vitamin B12 deficiency. Which type of gastritis is most likely responsible?","options":[{"id":"a","text":"H. pylori gastritis"},{"id":"b","text":"Autoimmune gastritis"},{"id":"c","text":"Erosive gastritis"},{"id":"d","text":"Chronic stress gastritis"}],"answerId":"b","explanation":"Autoimmune gastritis leads to destruction of parietal cells, causing achlorhydria and vitamin B12 deficiency.","kind":"clinical","origin":"ai"},{"id":"gastritis-and-gastropathy~ai-3","moduleId":"gastritis-and-gastropathy","stem":"Which finding is characteristic of H. pylori gastritis?","options":[{"id":"a","text":"Body/fundus atrophy"},{"id":"b","text":"Antral-predominant chronic active gastritis"},{"id":"c","text":"Intestinal metaplasia"},{"id":"d","text":"Achlorhydria"}],"answerId":"b","explanation":"H. pylori gastritis typically presents as antral-predominant chronic active gastritis.","kind":"recall","origin":"ai"},{"id":"gastritis-and-gastropathy~ai-4","moduleId":"gastritis-and-gastropathy","stem":"What is the primary risk associated with chronic H. pylori infection?","options":[{"id":"a","text":"Gastric perforation"},{"id":"b","text":"Gastric adenocarcinoma"},{"id":"c","text":"Pernicious anemia"},{"id":"d","text":"Gastric ulceration"}],"answerId":"b","explanation":"Chronic H. pylori infection can lead to chronic atrophic gastritis and is a significant risk factor for gastric adenocarcinoma.","kind":"trap","origin":"ai"},{"id":"gastritis-and-gastropathy~ai-5","moduleId":"gastritis-and-gastropathy","stem":"In a patient with a history of severe burns, which type of gastritis is most likely to develop?","options":[{"id":"a","text":"H. pylori gastritis"},{"id":"b","text":"Autoimmune gastritis"},{"id":"c","text":"Stress-related mucosal disease"},{"id":"d","text":"Chronic erosive gastritis"}],"answerId":"c","explanation":"Severe burns can lead to stress-related mucosal disease, which includes Curling ulcers.","kind":"clinical","origin":"ai"},{"id":"gastritis-and-gastropathy~ai-6","moduleId":"gastritis-and-gastropathy","stem":"How does chronic gastritis relate to gastric carcinoma development?","options":[{"id":"a","text":"Chronic inflammation leads to dysplasia"},{"id":"b","text":"Increased acid secretion promotes cancer"},{"id":"c","text":"Autoimmune gastritis directly causes cancer"},{"id":"d","text":"H. pylori eradication prevents all cancers"}],"answerId":"a","explanation":"Chronic gastritis, especially due to H. pylori, leads to intestinal metaplasia and dysplasia, increasing the risk of gastric carcinoma.","kind":"integration","linkedModuleIds":["gastric-carcinoma-lymphoma"],"origin":"ai"},{"id":"gastritis-and-gastropathy~ai-7","moduleId":"gastritis-and-gastropathy","stem":"Which treatment is essential for managing chronic gastritis due to H. pylori?","options":[{"id":"a","text":"Proton pump inhibitors"},{"id":"b","text":"Antibiotics"},{"id":"c","text":"Antacids"},{"id":"d","text":"Surgery"}],"answerId":"b","explanation":"Antibiotics are crucial for eradicating H. pylori, which is essential in the management of chronic gastritis.","kind":"integration","linkedModuleIds":["acid-suppression-h-pylori-therapy"],"origin":"ai"}],"hepatocellular-carcinoma-liver-tumors":[{"id":"hepatocellular-carcinoma-liver-tumors~ai-0","moduleId":"hepatocellular-carcinoma-liver-tumors","stem":"What is the most common risk factor for hepatocellular carcinoma (HCC)?","options":[{"id":"a","text":"Chronic hepatitis B infection"},{"id":"b","text":"Alcoholic liver disease"},{"id":"c","text":"Non-alcoholic steatohepatitis (NASH)"},{"id":"d","text":"Aflatoxin exposure"}],"answerId":"a","explanation":"Chronic hepatitis B infection is a major risk factor for HCC, particularly in the context of cirrhosis.","kind":"recall","origin":"ai"},{"id":"hepatocellular-carcinoma-liver-tumors~ai-1","moduleId":"hepatocellular-carcinoma-liver-tumors","stem":"A 55-year-old man with a history of cirrhosis presents with worsening abdominal pain and a rising alpha-fetoprotein level. What is the most likely diagnosis?","options":[{"id":"a","text":"Cholangiocarcinoma"},{"id":"b","text":"Hepatocellular carcinoma"},{"id":"c","text":"Hepatic adenoma"},{"id":"d","text":"Metastatic liver disease"}],"answerId":"b","explanation":"The combination of cirrhosis, rising AFP, and abdominal pain is characteristic of hepatocellular carcinoma.","kind":"clinical","origin":"ai"},{"id":"hepatocellular-carcinoma-liver-tumors~ai-2","moduleId":"hepatocellular-carcinoma-liver-tumors","stem":"Which of the following findings is most indicative of vascular invasion in hepatocellular carcinoma?","options":[{"id":"a","text":"Rising alpha-fetoprotein"},{"id":"b","text":"Portal vein tumor thrombus"},{"id":"c","text":"Multiple liver nodules"},{"id":"d","text":"Bile duct mass"}],"answerId":"b","explanation":"Portal vein tumor thrombus is a direct sign of vascular invasion associated with hepatocellular carcinoma.","kind":"recall","origin":"ai"},{"id":"hepatocellular-carcinoma-liver-tumors~ai-3","moduleId":"hepatocellular-carcinoma-liver-tumors","stem":"A patient presents with multiple liver masses but has no history of cirrhosis. What is the most likely diagnosis?","options":[{"id":"a","text":"Hepatocellular carcinoma"},{"id":"b","text":"Cholangiocarcinoma"},{"id":"c","text":"Metastatic disease"},{"id":"d","text":"Hepatic adenoma"}],"answerId":"c","explanation":"Multiple liver masses in a non-cirrhotic patient are most commonly due to metastatic disease rather than primary liver cancer.","kind":"trap","origin":"ai"},{"id":"hepatocellular-carcinoma-liver-tumors~ai-4","moduleId":"hepatocellular-carcinoma-liver-tumors","stem":"How does aflatoxin contribute to the development of hepatocellular carcinoma?","options":[{"id":"a","text":"By causing chronic hepatitis"},{"id":"b","text":"Through TP53 mutation"},{"id":"c","text":"By inducing cirrhosis"},{"id":"d","text":"By promoting bile duct obstruction"}],"answerId":"b","explanation":"Aflatoxin is known to cause mutations in the TP53 gene, which is a critical step in the carcinogenesis of hepatocellular carcinoma.","kind":"mechanism","origin":"ai"},{"id":"hepatocellular-carcinoma-liver-tumors~ai-5","moduleId":"hepatocellular-carcinoma-liver-tumors","stem":"Which of the following is a common presentation of cholangiocarcinoma?","options":[{"id":"a","text":"Rising AFP with cirrhosis"},{"id":"b","text":"Bile duct mass with a history of liver fluke infection"},{"id":"c","text":"Multiple liver nodules"},{"id":"d","text":"Hepatic adenoma in a young woman"}],"answerId":"b","explanation":"Cholangiocarcinoma often presents with a bile duct mass, especially in patients with a history of liver fluke infection.","kind":"clinical","origin":"ai"},{"id":"hepatocellular-carcinoma-liver-tumors~ai-6","moduleId":"hepatocellular-carcinoma-liver-tumors","stem":"How does chronic hepatitis B infection relate to hepatocellular carcinoma?","options":[{"id":"a","text":"It causes cirrhosis"},{"id":"b","text":"It directly mutates liver cells"},{"id":"c","text":"It leads to bile duct obstruction"},{"id":"d","text":"It is a risk factor even without cirrhosis"}],"answerId":"d","explanation":"Chronic hepatitis B can lead to hepatocellular carcinoma even in the absence of cirrhosis due to its ability to integrate into the host genome.","kind":"integration","linkedModuleIds":["hepatitis-b-c-d-chronic"],"origin":"ai"},{"id":"hepatocellular-carcinoma-liver-tumors~ai-7","moduleId":"hepatocellular-carcinoma-liver-tumors","stem":"What is the relationship between aflatoxin exposure and hepatocellular carcinoma?","options":[{"id":"a","text":"Aflatoxin causes cirrhosis"},{"id":"b","text":"Aflatoxin directly induces liver tumors"},{"id":"c","text":"Aflatoxin is a risk factor for cholangiocarcinoma"},{"id":"d","text":"Aflatoxin leads to hepatitis C infection"}],"answerId":"b","explanation":"Aflatoxin is a mycotoxin that directly induces liver tumors, particularly hepatocellular carcinoma, through genetic mutations.","kind":"integration","linkedModuleIds":["mycotoxins-aflatoxin"],"origin":"ai"}],"gallstones-cholecystitis-cholangitis":[{"id":"gallstones-cholecystitis-cholangitis~ai-0","moduleId":"gallstones-cholecystitis-cholangitis","stem":"What is the most common type of gallstone associated with obesity and female gender?","options":[{"id":"a","text":"Cholesterol stones"},{"id":"b","text":"Pigment stones"},{"id":"c","text":"Calcium stones"},{"id":"d","text":"Struvite stones"}],"answerId":"a","explanation":"Cholesterol stones are the most common type associated with the classic risk factors including obesity and female gender.","kind":"recall","origin":"ai"},{"id":"gallstones-cholecystitis-cholangitis~ai-1","moduleId":"gallstones-cholecystitis-cholangitis","stem":"A patient presents with episodic RUQ pain after fatty meals without fever. What is the likely diagnosis?","options":[{"id":"a","text":"Acute cholecystitis"},{"id":"b","text":"Biliary colic"},{"id":"c","text":"Ascending cholangitis"},{"id":"d","text":"Chronic pancreatitis"}],"answerId":"b","explanation":"The presentation of episodic RUQ pain after fatty meals without fever is characteristic of biliary colic due to transient cystic duct obstruction.","kind":"clinical","origin":"ai"},{"id":"gallstones-cholecystitis-cholangitis~ai-2","moduleId":"gallstones-cholecystitis-cholangitis","stem":"Which finding is most indicative of ascending cholangitis?","options":[{"id":"a","text":"Positive Murphy sign"},{"id":"b","text":"Episodic RUQ pain"},{"id":"c","text":"Charcot triad"},{"id":"d","text":"Pale stools"}],"answerId":"c","explanation":"The Charcot triad (fever, jaundice, RUQ pain) is a classic finding indicative of ascending cholangitis.","kind":"recall","origin":"ai"},{"id":"gallstones-cholecystitis-cholangitis~ai-3","moduleId":"gallstones-cholecystitis-cholangitis","stem":"What is the mechanism behind the constant RUQ pain in acute cholecystitis?","options":[{"id":"a","text":"Transient cystic duct obstruction"},{"id":"b","text":"Sustained cystic duct obstruction with inflammation"},{"id":"c","text":"Common bile duct obstruction"},{"id":"d","text":"Gallbladder carcinoma"}],"answerId":"b","explanation":"Acute cholecystitis is caused by sustained cystic duct obstruction leading to inflammation and constant RUQ pain.","kind":"mechanism","origin":"ai"},{"id":"gallstones-cholecystitis-cholangitis~ai-4","moduleId":"gallstones-cholecystitis-cholangitis","stem":"A patient with obstructive jaundice presents with pale stools and dark urine. What is the most likely cause?","options":[{"id":"a","text":"Cholecystitis"},{"id":"b","text":"Choledocholithiasis"},{"id":"c","text":"Cholangitis"},{"id":"d","text":"Pancreatitis"}],"answerId":"b","explanation":"Choledocholithiasis (common bile duct stone) causes obstructive jaundice, leading to pale stools and dark urine due to conjugated bilirubin accumulation.","kind":"clinical","origin":"ai"},{"id":"gallstones-cholecystitis-cholangitis~ai-5","moduleId":"gallstones-cholecystitis-cholangitis","stem":"In a patient with gallstones, which symptom escalation indicates a shift from biliary colic to cholangitis?","options":[{"id":"a","text":"Increased RUQ pain"},{"id":"b","text":"Development of fever"},{"id":"c","text":"Onset of nausea"},{"id":"d","text":"Change in stool color"}],"answerId":"b","explanation":"The development of fever in a patient with gallstones suggests a progression to cholangitis, which is a medical emergency.","kind":"trap","origin":"ai"},{"id":"gallstones-cholecystitis-cholangitis~ai-6","moduleId":"gallstones-cholecystitis-cholangitis","stem":"How does ascending cholangitis relate to fat-soluble vitamin absorption?","options":[{"id":"a","text":"It enhances absorption"},{"id":"b","text":"It causes vitamin K deficiency"},{"id":"c","text":"It has no effect"},{"id":"d","text":"It improves bile flow"}],"answerId":"b","explanation":"Ascending cholangitis can lead to bile flow obstruction, which may result in malabsorption of fat-soluble vitamins, particularly vitamin K.","kind":"integration","linkedModuleIds":["cholangitis-bile-vitamin-loss"],"origin":"ai"},{"id":"gallstones-cholecystitis-cholangitis~ai-7","moduleId":"gallstones-cholecystitis-cholangitis","stem":"What laboratory finding would you expect in a patient with obstructive jaundice due to choledocholithiasis?","options":[{"id":"a","text":"Elevated alkaline phosphatase"},{"id":"b","text":"Low bilirubin levels"},{"id":"c","text":"Normal liver enzymes"},{"id":"d","text":"Decreased conjugated bilirubin"}],"answerId":"a","explanation":"Elevated alkaline phosphatase is a common laboratory finding in obstructive jaundice due to choledocholithiasis.","kind":"integration","linkedModuleIds":["cholestatic-lab-pattern"],"origin":"ai"}],"appendicitis-diverticular-ischemic-bowel":[{"id":"appendicitis-diverticular-ischemic-bowel~ai-0","moduleId":"appendicitis-diverticular-ischemic-bowel","stem":"What is the most common cause of acute appendicitis in adults?","options":[{"id":"a","text":"Lymphoid hyperplasia"},{"id":"b","text":"Fecalith"},{"id":"c","text":"Tumor obstruction"},{"id":"d","text":"Foreign body"}],"answerId":"b","explanation":"Fecaliths are the most common obstruction leading to acute appendicitis in adults.","kind":"recall","origin":"ai"},{"id":"appendicitis-diverticular-ischemic-bowel~ai-1","moduleId":"appendicitis-diverticular-ischemic-bowel","stem":"Which clinical finding is most indicative of acute diverticulitis?","options":[{"id":"a","text":"Right lower quadrant pain"},{"id":"b","text":"Painless rectal bleeding"},{"id":"c","text":"Left lower quadrant pain with fever"},{"id":"d","text":"Severe abdominal pain out of proportion"}],"answerId":"c","explanation":"Left lower quadrant pain with fever is characteristic of acute diverticulitis.","kind":"recall","origin":"ai"},{"id":"appendicitis-diverticular-ischemic-bowel~ai-2","moduleId":"appendicitis-diverticular-ischemic-bowel","stem":"What mechanism primarily leads to diverticulosis?","options":[{"id":"a","text":"Infection"},{"id":"b","text":"Low-fiber diet"},{"id":"c","text":"Genetic predisposition"},{"id":"d","text":"Inflammation"}],"answerId":"b","explanation":"A low-fiber diet increases intraluminal pressure, leading to the formation of diverticula.","kind":"mechanism","origin":"ai"},{"id":"appendicitis-diverticular-ischemic-bowel~ai-3","moduleId":"appendicitis-diverticular-ischemic-bowel","stem":"In acute mesenteric ischaemia, what is the typical presentation of abdominal pain?","options":[{"id":"a","text":"Localized and mild"},{"id":"b","text":"Severe pain out of proportion to examination"},{"id":"c","text":"Intermittent cramping"},{"id":"d","text":"Constant dull ache"}],"answerId":"b","explanation":"Acute mesenteric ischaemia causes severe pain that is disproportionate to the physical exam findings.","kind":"clinical","origin":"ai"},{"id":"appendicitis-diverticular-ischemic-bowel~ai-4","moduleId":"appendicitis-diverticular-ischemic-bowel","stem":"Which of the following findings would most likely rule out diverticulosis as the cause of lower gastrointestinal bleeding?","options":[{"id":"a","text":"Painless bleeding"},{"id":"b","text":"Bright-red blood on toilet paper"},{"id":"c","text":"Left lower quadrant pain"},{"id":"d","text":"History of constipation"}],"answerId":"c","explanation":"Left lower quadrant pain suggests diverticulitis rather than diverticulosis, which is typically painless.","kind":"trap","origin":"ai"},{"id":"appendicitis-diverticular-ischemic-bowel~ai-5","moduleId":"appendicitis-diverticular-ischemic-bowel","stem":"A patient presents with severe abdominal pain and a soft abdomen. What condition should be suspected?","options":[{"id":"a","text":"Acute appendicitis"},{"id":"b","text":"Acute diverticulitis"},{"id":"c","text":"Acute mesenteric ischaemia"},{"id":"d","text":"Diverticulosis"}],"answerId":"c","explanation":"Acute mesenteric ischaemia can present with severe pain even when the abdomen is soft, highlighting the need for urgent evaluation.","kind":"trap","origin":"ai"},{"id":"appendicitis-diverticular-ischemic-bowel~ai-6","moduleId":"appendicitis-diverticular-ischemic-bowel","stem":"How does diverticulitis differ from colorectal carcinoma in terms of presentation?","options":[{"id":"a","text":"Diverticulitis presents with painless bleeding"},{"id":"b","text":"Colorectal carcinoma presents with left lower quadrant pain"},{"id":"c","text":"Diverticulitis presents with fever and inflammatory markers"},{"id":"d","text":"Colorectal carcinoma presents with acute abdominal pain"}],"answerId":"c","explanation":"Diverticulitis typically presents with fever and raised inflammatory markers, while colorectal carcinoma may present with more insidious symptoms.","kind":"integration","linkedModuleIds":["colorectal-polyps-carcinoma"],"origin":"ai"},{"id":"appendicitis-diverticular-ischemic-bowel~ai-7","moduleId":"appendicitis-diverticular-ischemic-bowel","stem":"What is a common complication of diverticulitis that can lead to gastrointestinal bleeding?","options":[{"id":"a","text":"Ischaemic colitis"},{"id":"b","text":"Colovesical fistula"},{"id":"c","text":"Angiodysplasia"},{"id":"d","text":"Appendiceal perforation"}],"answerId":"b","explanation":"A colovesical fistula can occur as a complication of diverticulitis, leading to urinary symptoms and potential bleeding.","kind":"integration","linkedModuleIds":["gastrointestinal-bleeding-approach"],"origin":"ai"}],"colorectal-polyps-carcinoma":[{"id":"colorectal-polyps-carcinoma~ai-0","moduleId":"colorectal-polyps-carcinoma","stem":"What is the most common pathway for the development of colorectal cancer from adenomatous polyps?","options":[{"id":"a","text":"APC → KRAS → TP53"},{"id":"b","text":"BRAF → MSI → TP53"},{"id":"c","text":"KRAS → APC → BRAF"},{"id":"d","text":"TP53 → APC → KRAS"}],"answerId":"a","explanation":"The adenoma-carcinoma sequence involves the stepwise accumulation of mutations starting with APC loss, followed by KRAS activation and TP53 loss.","kind":"recall","origin":"ai"},{"id":"colorectal-polyps-carcinoma~ai-1","moduleId":"colorectal-polyps-carcinoma","stem":"Which type of adenoma has the highest risk of malignant transformation?","options":[{"id":"a","text":"Tubular adenoma"},{"id":"b","text":"Villous adenoma"},{"id":"c","text":"Hyperplastic polyp"},{"id":"d","text":"Serrated adenoma"}],"answerId":"b","explanation":"Villous adenomas are larger and have a higher malignant potential compared to other types of adenomas.","kind":"recall","origin":"ai"},{"id":"colorectal-polyps-carcinoma~ai-2","moduleId":"colorectal-polyps-carcinoma","stem":"An older adult presents with unexplained iron-deficiency anemia. What is the most likely underlying cause?","options":[{"id":"a","text":"Dietary deficiency"},{"id":"b","text":"Right-sided colorectal carcinoma"},{"id":"c","text":"Left-sided colorectal carcinoma"},{"id":"d","text":"Hemorrhoids"}],"answerId":"b","explanation":"Unexplained iron-deficiency anemia in older adults should be assumed to be due to occult gastrointestinal bleeding, often from right-sided colorectal carcinoma.","kind":"clinical","origin":"ai"},{"id":"colorectal-polyps-carcinoma~ai-3","moduleId":"colorectal-polyps-carcinoma","stem":"A 25-year-old man has hundreds of colonic adenomas. What genetic condition is he most likely to have?","options":[{"id":"a","text":"Lynch syndrome"},{"id":"b","text":"Familial Adenomatous Polyposis"},{"id":"c","text":"Gardner syndrome"},{"id":"d","text":"Peutz-Jeghers syndrome"}],"answerId":"b","explanation":"Familial Adenomatous Polyposis (FAP) is characterized by hundreds to thousands of adenomas due to a germline mutation in the APC gene.","kind":"recall","origin":"ai"},{"id":"colorectal-polyps-carcinoma~ai-4","moduleId":"colorectal-polyps-carcinoma","stem":"What is the significance of a left-sided colorectal carcinoma presenting with a 'napkin-ring' appearance?","options":[{"id":"a","text":"It indicates a benign lesion"},{"id":"b","text":"It suggests obstruction and change in bowel habit"},{"id":"c","text":"It is a sign of metastasis"},{"id":"d","text":"It is associated with iron-deficiency anemia"}],"answerId":"b","explanation":"Left-sided colorectal carcinomas often present as annular lesions causing obstruction and changes in bowel habits.","kind":"clinical","origin":"ai"},{"id":"colorectal-polyps-carcinoma~ai-5","moduleId":"colorectal-polyps-carcinoma","stem":"In a patient with Lynch syndrome, what additional cancer risk is significantly increased?","options":[{"id":"a","text":"Breast cancer"},{"id":"b","text":"Endometrial cancer"},{"id":"c","text":"Pancreatic cancer"},{"id":"d","text":"Prostate cancer"}],"answerId":"b","explanation":"Lynch syndrome is associated with an increased risk of endometrial cancer in addition to colorectal cancer.","kind":"recall","origin":"ai"},{"id":"colorectal-polyps-carcinoma~ai-6","moduleId":"colorectal-polyps-carcinoma","stem":"How does the approach to gastrointestinal bleeding relate to colorectal cancer screening?","options":[{"id":"a","text":"Both focus on dietary changes"},{"id":"b","text":"Both involve imaging studies"},{"id":"c","text":"Both require endoscopic evaluation"},{"id":"d","text":"Both are unrelated"}],"answerId":"c","explanation":"The approach to gastrointestinal bleeding often includes endoscopic evaluation, which is also used in colorectal cancer screening to detect and remove adenomas.","kind":"integration","linkedModuleIds":["gastrointestinal-bleeding-approach"],"origin":"ai"},{"id":"colorectal-polyps-carcinoma~ai-7","moduleId":"colorectal-polyps-carcinoma","stem":"How does inflammatory bowel disease (IBD) increase the risk of colorectal cancer?","options":[{"id":"a","text":"By causing dietary deficiencies"},{"id":"b","text":"Through chronic inflammation and dysplasia"},{"id":"c","text":"By promoting benign polyp formation"},{"id":"d","text":"By increasing iron absorption"}],"answerId":"b","explanation":"Chronic inflammation in IBD can lead to dysplasia and increased risk of colorectal cancer over time.","kind":"integration","linkedModuleIds":["inflammatory-bowel-disease"],"origin":"ai"}],"hepatitis-liver-injury-patterns":[{"id":"hepatitis-liver-injury-patterns~ai-0","moduleId":"hepatitis-liver-injury-patterns","stem":"What is the primary laboratory finding in acute hepatitis?","options":[{"id":"a","text":"Raised alkaline phosphatase"},{"id":"b","text":"Increased bilirubin levels"},{"id":"c","text":"Elevated AST/ALT"},{"id":"d","text":"Decreased albumin levels"}],"answerId":"c","explanation":"Acute hepatitis is characterized by elevated levels of AST and ALT due to hepatocellular injury.","kind":"recall","origin":"ai"},{"id":"hepatitis-liver-injury-patterns~ai-1","moduleId":"hepatitis-liver-injury-patterns","stem":"Which type of jaundice is associated with hemolysis?","options":[{"id":"a","text":"Conjugated jaundice"},{"id":"b","text":"Unconjugated jaundice"},{"id":"c","text":"Obstructive jaundice"},{"id":"d","text":"Cholestatic jaundice"}],"answerId":"b","explanation":"Unconjugated jaundice occurs due to hemolysis or impaired conjugation, leading to elevated indirect bilirubin.","kind":"recall","origin":"ai"},{"id":"hepatitis-liver-injury-patterns~ai-2","moduleId":"hepatitis-liver-injury-patterns","stem":"What histological finding is characteristic of chronic hepatitis?","options":[{"id":"a","text":"Councilman bodies"},{"id":"b","text":"Spotty necrosis"},{"id":"c","text":"Interface hepatitis"},{"id":"d","text":"Massive necrosis"}],"answerId":"c","explanation":"Chronic hepatitis is defined by interface hepatitis, which shows inflammation spilling across the limiting plate.","kind":"recall","origin":"ai"},{"id":"hepatitis-liver-injury-patterns~ai-3","moduleId":"hepatitis-liver-injury-patterns","stem":"Which clinical finding indicates acute (fulminant) liver failure?","options":[{"id":"a","text":"Dark urine"},{"id":"b","text":"Pale stools"},{"id":"c","text":"Encephalopathy"},{"id":"d","text":"Jaundice"}],"answerId":"c","explanation":"Encephalopathy, along with coagulopathy, is a hallmark of acute liver failure occurring within weeks.","kind":"recall","origin":"ai"},{"id":"hepatitis-liver-injury-patterns~ai-4","moduleId":"hepatitis-liver-injury-patterns","stem":"In which condition would you expect to find ANA and anti-smooth muscle antibodies?","options":[{"id":"a","text":"Chronic viral hepatitis"},{"id":"b","text":"Autoimmune hepatitis"},{"id":"c","text":"Alcoholic liver disease"},{"id":"d","text":"Non-alcoholic fatty liver disease"}],"answerId":"b","explanation":"Autoimmune hepatitis is characterized by the presence of ANA and anti-smooth muscle antibodies.","kind":"recall","origin":"ai"},{"id":"hepatitis-liver-injury-patterns~ai-5","moduleId":"hepatitis-liver-injury-patterns","stem":"Which mechanism describes the progression from liver injury to fibrosis?","options":[{"id":"a","text":"Inflammation → regeneration → necrosis"},{"id":"b","text":"Injury → inflammation → fibrosis"},{"id":"c","text":"Necrosis → inflammation → regeneration"},{"id":"d","text":"Fibrosis → regeneration → injury"}],"answerId":"b","explanation":"The mechanism of liver injury involves inflammation leading to fibrosis as a response to ongoing hepatocyte damage.","kind":"mechanism","origin":"ai"},{"id":"hepatitis-liver-injury-patterns~ai-6","moduleId":"hepatitis-liver-injury-patterns","stem":"A patient presents with jaundice, dark urine, and pale stools. Which type of bilirubin is likely elevated?","options":[{"id":"a","text":"Unconjugated bilirubin"},{"id":"b","text":"Conjugated bilirubin"},{"id":"c","text":"Both types of bilirubin"},{"id":"d","text":"Neither type of bilirubin"}],"answerId":"b","explanation":"The presence of dark urine and pale stools indicates conjugated hyperbilirubinemia due to cholestasis or biliary obstruction.","kind":"trap","origin":"ai"},{"id":"hepatitis-liver-injury-patterns~ai-7","moduleId":"hepatitis-liver-injury-patterns","stem":"How does chronic hepatitis relate to cirrhosis?","options":[{"id":"a","text":"Chronic hepatitis leads to acute liver failure"},{"id":"b","text":"Chronic hepatitis can progress to cirrhosis"},{"id":"c","text":"Cirrhosis is always reversible"},{"id":"d","text":"Chronic hepatitis is unrelated to cirrhosis"}],"answerId":"b","explanation":"Chronic hepatitis, characterized by ongoing inflammation and fibrosis, is a major pathway leading to cirrhosis.","kind":"integration","linkedModuleIds":["cirrhosis-fatty-liver-portal-hypertension"],"origin":"ai"},{"id":"hepatitis-liver-injury-patterns~ai-8","moduleId":"hepatitis-liver-injury-patterns","stem":"What type of bilirubin metabolism issue is associated with Gilbert's syndrome?","options":[{"id":"a","text":"Conjugated hyperbilirubinemia"},{"id":"b","text":"Unconjugated hyperbilirubinemia"},{"id":"c","text":"Cholestatic jaundice"},{"id":"d","text":"Obstructive jaundice"}],"answerId":"b","explanation":"Gilbert's syndrome is characterized by unconjugated hyperbilirubinemia due to impaired conjugation of bilirubin.","kind":"integration","linkedModuleIds":["bilirubin-metabolism-jaundice"],"origin":"ai"}],"bilirubin-metabolism-jaundice":[{"id":"bilirubin-metabolism-jaundice~ai-0","moduleId":"bilirubin-metabolism-jaundice","stem":"What is the primary cause of unconjugated hyperbilirubinaemia in Gilbert syndrome?","options":[{"id":"a","text":"Increased bilirubin production"},{"id":"b","text":"Decreased hepatic uptake"},{"id":"c","text":"Reduced conjugation by UGT"},{"id":"d","text":"Impaired excretion into bile"}],"answerId":"c","explanation":"Gilbert syndrome is characterized by a benign reduction in the activity of UDP-glucuronosyltransferase (UGT), leading to decreased conjugation of bilirubin.","kind":"recall","origin":"ai"},{"id":"bilirubin-metabolism-jaundice~ai-1","moduleId":"bilirubin-metabolism-jaundice","stem":"Which finding is characteristic of post-hepatic jaundice?","options":[{"id":"a","text":"Dark urine"},{"id":"b","text":"Pale stools"},{"id":"c","text":"Elevated AST/ALT"},{"id":"d","text":"No bilirubin in urine"}],"answerId":"a","explanation":"In post-hepatic jaundice, conjugated bilirubin is water-soluble and spills into the urine, resulting in dark urine.","kind":"recall","origin":"ai"},{"id":"bilirubin-metabolism-jaundice~ai-2","moduleId":"bilirubin-metabolism-jaundice","stem":"In which type of jaundice would you expect both unconjugated and conjugated bilirubin to be elevated?","options":[{"id":"a","text":"Pre-hepatic"},{"id":"b","text":"Post-hepatic"},{"id":"c","text":"Hepatocellular"},{"id":"d","text":"Gilbert syndrome"}],"answerId":"c","explanation":"Hepatocellular jaundice results in the elevation of both fractions due to liver cell damage.","kind":"recall","origin":"ai"},{"id":"bilirubin-metabolism-jaundice~ai-3","moduleId":"bilirubin-metabolism-jaundice","stem":"A patient presents with jaundice, dark urine, and pale stools. What is the most likely underlying cause?","options":[{"id":"a","text":"Hemolysis"},{"id":"b","text":"Liver cirrhosis"},{"id":"c","text":"Bile duct obstruction"},{"id":"d","text":"Gilbert syndrome"}],"answerId":"c","explanation":"Dark urine and pale stools indicate the presence of conjugated bilirubin, which is typical of bile duct obstruction.","kind":"clinical","origin":"ai"},{"id":"bilirubin-metabolism-jaundice~ai-4","moduleId":"bilirubin-metabolism-jaundice","stem":"Which statement regarding bilirubinuria is correct?","options":[{"id":"a","text":"It occurs in all types of jaundice"},{"id":"b","text":"It indicates pre-hepatic jaundice"},{"id":"c","text":"It is absent in conjugated hyperbilirubinaemia"},{"id":"d","text":"It suggests hepatic or post-hepatic jaundice"}],"answerId":"d","explanation":"Bilirubinuria occurs only when conjugated bilirubin is elevated, indicating hepatic or post-hepatic causes.","kind":"trap","origin":"ai"},{"id":"bilirubin-metabolism-jaundice~ai-5","moduleId":"bilirubin-metabolism-jaundice","stem":"A newborn presents with severe unconjugated hyperbilirubinaemia. What is the primary risk associated with this condition?","options":[{"id":"a","text":"Kernicterus"},{"id":"b","text":"Cholecystitis"},{"id":"c","text":"Liver failure"},{"id":"d","text":"Hemolytic anemia"}],"answerId":"a","explanation":"Severe unconjugated hyperbilirubinaemia in newborns poses a risk of kernicterus due to bilirubin crossing the blood-brain barrier.","kind":"recall","origin":"ai"},{"id":"bilirubin-metabolism-jaundice~ai-6","moduleId":"bilirubin-metabolism-jaundice","stem":"How does obstructive jaundice relate to the interpretation of liver function tests?","options":[{"id":"a","text":"It shows elevated AST/ALT only"},{"id":"b","text":"It causes elevated alkaline phosphatase"},{"id":"c","text":"It indicates normal bilirubin levels"},{"id":"d","text":"It is characterized by low urobilinogen"}],"answerId":"b","explanation":"Obstructive jaundice typically results in elevated alkaline phosphatase levels due to cholestasis.","kind":"integration","linkedModuleIds":["liver-function-tests-interpretation"],"origin":"ai"},{"id":"bilirubin-metabolism-jaundice~ai-7","moduleId":"bilirubin-metabolism-jaundice","stem":"In a patient with hemolytic anemia, what would you expect in their bilirubin profile?","options":[{"id":"a","text":"High conjugated bilirubin"},{"id":"b","text":"High unconjugated bilirubin"},{"id":"c","text":"Normal bilirubin levels"},{"id":"d","text":"High direct bilirubin"}],"answerId":"b","explanation":"Hemolytic anemia leads to increased breakdown of red blood cells, resulting in elevated unconjugated bilirubin.","kind":"integration","linkedModuleIds":["hemolysis-workup-triggers"],"origin":"ai"}],"cirrhosis-fatty-liver-portal-hypertension":[{"id":"cirrhosis-fatty-liver-portal-hypertension~ai-0","moduleId":"cirrhosis-fatty-liver-portal-hypertension","stem":"Which of the following is a common cause of cirrhosis?","options":[{"id":"a","text":"Chronic viral hepatitis"},{"id":"b","text":"Acute pancreatitis"},{"id":"c","text":"Gallstones"},{"id":"d","text":"Peptic ulcer disease"}],"answerId":"a","explanation":"Chronic viral hepatitis is one of the leading causes of cirrhosis, alongside alcohol and NAFLD/NASH.","kind":"recall","origin":"ai"},{"id":"cirrhosis-fatty-liver-portal-hypertension~ai-1","moduleId":"cirrhosis-fatty-liver-portal-hypertension","stem":"What is the mechanism behind ascites in cirrhosis?","options":[{"id":"a","text":"Increased portal venous pressure"},{"id":"b","text":"Increased hepatic blood flow"},{"id":"c","text":"Decreased bile production"},{"id":"d","text":"Increased protein synthesis"}],"answerId":"a","explanation":"Ascites in cirrhosis is primarily due to increased portal venous pressure and hypoalbuminaemia, leading to fluid accumulation in the abdominal cavity.","kind":"mechanism","origin":"ai"},{"id":"cirrhosis-fatty-liver-portal-hypertension~ai-2","moduleId":"cirrhosis-fatty-liver-portal-hypertension","stem":"A patient presents with jaundice, ascites, and asterixis. What is the most likely underlying condition?","options":[{"id":"a","text":"Acute liver failure"},{"id":"b","text":"Cirrhosis"},{"id":"c","text":"Chronic hepatitis"},{"id":"d","text":"Cholecystitis"}],"answerId":"b","explanation":"The combination of jaundice, ascites, and asterixis suggests hepatic encephalopathy due to cirrhosis.","kind":"clinical","origin":"ai"},{"id":"cirrhosis-fatty-liver-portal-hypertension~ai-3","moduleId":"cirrhosis-fatty-liver-portal-hypertension","stem":"Which finding is characteristic of alcoholic hepatitis?","options":[{"id":"a","text":"Low ceruloplasmin"},{"id":"b","text":"AST:ALT ratio >2"},{"id":"c","text":"Iron overload"},{"id":"d","text":"Anti-mitochondrial antibodies"}],"answerId":"b","explanation":"An AST:ALT ratio greater than 2 is a classic finding in alcoholic hepatitis.","kind":"recall","origin":"ai"},{"id":"cirrhosis-fatty-liver-portal-hypertension~ai-4","moduleId":"cirrhosis-fatty-liver-portal-hypertension","stem":"Which of the following statements about fatty liver and cirrhosis is true?","options":[{"id":"a","text":"Both are equally reversible if the cause is removed"},{"id":"b","text":"Fatty liver is reversible, cirrhosis is generally irreversible"},{"id":"c","text":"Cirrhosis can be reversed with lifestyle changes"},{"id":"d","text":"Fatty liver always progresses to cirrhosis"}],"answerId":"b","explanation":"Fatty liver (steatosis) is reversible if the cause is addressed, while cirrhosis is generally considered irreversible due to architectural distortion.","kind":"trap","origin":"ai"},{"id":"cirrhosis-fatty-liver-portal-hypertension~ai-5","moduleId":"cirrhosis-fatty-liver-portal-hypertension","stem":"What is the most common cause of hyperoestrogenism in cirrhosis?","options":[{"id":"a","text":"Increased estrogen production"},{"id":"b","text":"Decreased estrogen metabolism"},{"id":"c","text":"Increased testosterone levels"},{"id":"d","text":"Decreased progesterone levels"}],"answerId":"b","explanation":"In cirrhosis, the liver's ability to metabolize estrogen is impaired, leading to hyperoestrogenism.","kind":"mechanism","origin":"ai"},{"id":"cirrhosis-fatty-liver-portal-hypertension~ai-6","moduleId":"cirrhosis-fatty-liver-portal-hypertension","stem":"How does portal hypertension lead to esophageal varices?","options":[{"id":"a","text":"Increased blood flow to the esophagus"},{"id":"b","text":"Increased pressure in the portal vein"},{"id":"c","text":"Decreased hepatic blood flow"},{"id":"d","text":"Increased venous return from the heart"}],"answerId":"b","explanation":"Portal hypertension increases pressure in the portal vein, leading to the development of collateral circulation, including esophageal varices.","kind":"mechanism","origin":"ai"},{"id":"cirrhosis-fatty-liver-portal-hypertension~ai-7","moduleId":"cirrhosis-fatty-liver-portal-hypertension","stem":"A patient with cirrhosis develops spontaneous bacterial peritonitis. Which linked module's knowledge is essential for understanding this complication?","options":[{"id":"a","text":"GI Blood Supply & Portal System"},{"id":"b","text":"Liver Function Tests Interpretation"},{"id":"c","text":"Hepatitis B, C & D (Blood-Borne, Chronic)"},{"id":"d","text":"Bilirubin Metabolism & Jaundice"}],"answerId":"a","explanation":"Understanding portal hypertension and its complications, including ascites and spontaneous bacterial peritonitis, is crucial and relates to the GI Blood Supply & Portal System module.","kind":"integration","linkedModuleIds":["gi-blood-supply-portal-system"],"origin":"ai"},{"id":"cirrhosis-fatty-liver-portal-hypertension~ai-8","moduleId":"cirrhosis-fatty-liver-portal-hypertension","stem":"In a patient with non-alcoholic fatty liver disease (NAFLD), which metabolic condition is most likely linked?","options":[{"id":"a","text":"Chronic hepatitis B"},{"id":"b","text":"Obesity"},{"id":"c","text":"Hemochromatosis"},{"id":"d","text":"Wilson's disease"}],"answerId":"b","explanation":"NAFLD is closely associated with metabolic syndrome, particularly obesity, which is a significant risk factor.","kind":"integration","linkedModuleIds":["obesity-pathophysiology"],"origin":"ai"}],"acute-chronic-pancreatitis":[{"id":"acute-chronic-pancreatitis~ai-0","moduleId":"acute-chronic-pancreatitis","stem":"What is the most common cause of acute pancreatitis?","options":[{"id":"a","text":"Gallstones"},{"id":"b","text":"Hypertriglyceridemia"},{"id":"c","text":"Medications"},{"id":"d","text":"Trauma"}],"answerId":"a","explanation":"Gallstones are the most common cause of acute pancreatitis, leading to inappropriate activation of digestive enzymes.","kind":"recall","origin":"ai"},{"id":"acute-chronic-pancreatitis~ai-1","moduleId":"acute-chronic-pancreatitis","stem":"Which of the following findings is characteristic of necrotizing pancreatitis?","options":[{"id":"a","text":"Steatorrhoea"},{"id":"b","text":"Hypocalcaemia"},{"id":"c","text":"Grey Turner sign"},{"id":"d","text":"Pancreatic calcifications"}],"answerId":"c","explanation":"Grey Turner sign indicates retroperitoneal hemorrhage, a complication of necrotizing pancreatitis.","kind":"recall","origin":"ai"},{"id":"acute-chronic-pancreatitis~ai-2","moduleId":"acute-chronic-pancreatitis","stem":"What mechanism underlies the development of fat necrosis in acute pancreatitis?","options":[{"id":"a","text":"Increased lipase activity"},{"id":"b","text":"Calcium soap formation"},{"id":"c","text":"Duct obstruction"},{"id":"d","text":"Vascular occlusion"}],"answerId":"b","explanation":"Fat necrosis occurs due to the formation of calcium soaps from the breakdown of triglycerides by lipases.","kind":"mechanism","origin":"ai"},{"id":"acute-chronic-pancreatitis~ai-3","moduleId":"acute-chronic-pancreatitis","stem":"Which of the following statements about pancreatic pseudocysts is true?","options":[{"id":"a","text":"They are true cysts lined by epithelium"},{"id":"b","text":"They are collections of enzyme-rich fluid with no epithelial lining"},{"id":"c","text":"They always require surgical intervention"},{"id":"d","text":"They form immediately after an acute attack"}],"answerId":"b","explanation":"Pancreatic pseudocysts are collections of enzyme-rich fluid walled off by granulation tissue without an epithelial lining.","kind":"trap","origin":"ai"},{"id":"acute-chronic-pancreatitis~ai-4","moduleId":"acute-chronic-pancreatitis","stem":"A patient with chronic pancreatitis presents with steatorrhoea and weight loss. What is the underlying cause?","options":[{"id":"a","text":"Exocrine pancreatic insufficiency"},{"id":"b","text":"Endocrine pancreatic insufficiency"},{"id":"c","text":"Biliary obstruction"},{"id":"d","text":"Pancreatic cancer"}],"answerId":"a","explanation":"Chronic pancreatitis leads to exocrine pancreatic insufficiency, resulting in malabsorption and steatorrhoea.","kind":"clinical","origin":"ai"},{"id":"acute-chronic-pancreatitis~ai-5","moduleId":"acute-chronic-pancreatitis","stem":"How does chronic pancreatitis increase the risk of pancreatic cancer?","options":[{"id":"a","text":"By causing ductal obstruction"},{"id":"b","text":"Through chronic inflammation and fibrosis"},{"id":"c","text":"By inducing diabetes"},{"id":"d","text":"By increasing triglycerides"}],"answerId":"b","explanation":"Chronic inflammation and fibrosis in chronic pancreatitis can lead to changes that predispose to pancreatic cancer.","kind":"integration","linkedModuleIds":["pancreatic-carcinoma"],"origin":"ai"},{"id":"acute-chronic-pancreatitis~ai-6","moduleId":"acute-chronic-pancreatitis","stem":"Which fat-soluble vitamin deficiency is most likely in a patient with chronic pancreatitis?","options":[{"id":"a","text":"Vitamin A"},{"id":"b","text":"Vitamin D"},{"id":"c","text":"Vitamin E"},{"id":"d","text":"Vitamin K"}],"answerId":"b","explanation":"Vitamin D deficiency is common in chronic pancreatitis due to malabsorption of fat-soluble vitamins.","kind":"integration","linkedModuleIds":["fat-soluble-vitamins"],"origin":"ai"}],"nutrition-energy-protein-malnutrition":[{"id":"nutrition-energy-protein-malnutrition~ai-0","moduleId":"nutrition-energy-protein-malnutrition","stem":"What is the primary distinguishing feature of kwashiorkor compared to marasmus?","options":[{"id":"a","text":"Severe muscle wasting"},{"id":"b","text":"Oedema"},{"id":"c","text":"Hypoalbuminaemia"},{"id":"d","text":"Normal weight"}],"answerId":"b","explanation":"Kwashiorkor is characterized by oedema due to hypoalbuminaemia, while marasmus presents with severe muscle wasting without oedema.","kind":"recall","origin":"ai"},{"id":"nutrition-energy-protein-malnutrition~ai-1","moduleId":"nutrition-energy-protein-malnutrition","stem":"Which macronutrient provides the highest caloric value per gram?","options":[{"id":"a","text":"Carbohydrate"},{"id":"b","text":"Protein"},{"id":"c","text":"Fat"},{"id":"d","text":"Alcohol"}],"answerId":"c","explanation":"Fat provides approximately 9 kcal/g, which is higher than carbohydrates and proteins, both providing about 4 kcal/g.","kind":"recall","origin":"ai"},{"id":"nutrition-energy-protein-malnutrition~ai-2","moduleId":"nutrition-energy-protein-malnutrition","stem":"What is the most significant risk associated with refeeding a severely malnourished patient too quickly?","options":[{"id":"a","text":"Hyperkalemia"},{"id":"b","text":"Hypophosphataemia"},{"id":"c","text":"Dehydration"},{"id":"d","text":"Hyperglycemia"}],"answerId":"b","explanation":"Refeeding syndrome can lead to hypophosphataemia due to insulin-mediated shifts of phosphate into cells.","kind":"mechanism","origin":"ai"},{"id":"nutrition-energy-protein-malnutrition~ai-3","moduleId":"nutrition-energy-protein-malnutrition","stem":"A child presents with severe muscle wasting, no oedema, and preserved albumin levels. What condition is most likely?","options":[{"id":"a","text":"Kwashiorkor"},{"id":"b","text":"Marasmus"},{"id":"c","text":"Refeeding syndrome"},{"id":"d","text":"Obesity"}],"answerId":"b","explanation":"The presentation is consistent with marasmus, which is characterized by total energy deficiency and preserved albumin.","kind":"clinical","origin":"ai"},{"id":"nutrition-energy-protein-malnutrition~ai-4","moduleId":"nutrition-energy-protein-malnutrition","stem":"Which anthropometric measurement is most indicative of malnutrition in children?","options":[{"id":"a","text":"BMI"},{"id":"b","text":"Weight-for-height"},{"id":"c","text":"Mid-upper-arm circumference"},{"id":"d","text":"Skinfold thickness"}],"answerId":"c","explanation":"Mid-upper-arm circumference is a key anthropometric marker for assessing malnutrition in children.","kind":"recall","origin":"ai"},{"id":"nutrition-energy-protein-malnutrition~ai-5","moduleId":"nutrition-energy-protein-malnutrition","stem":"In a patient with inflammatory bowel disease, which type of malnutrition is most likely to occur?","options":[{"id":"a","text":"Protein-energy malnutrition"},{"id":"b","text":"Obesity"},{"id":"c","text":"Hypervitaminosis"},{"id":"d","text":"Dehydration"}],"answerId":"a","explanation":"Patients with inflammatory bowel disease often experience protein-energy malnutrition due to malabsorption.","kind":"integration","linkedModuleIds":["inflammatory-bowel-disease"],"origin":"ai"},{"id":"nutrition-energy-protein-malnutrition~ai-6","moduleId":"nutrition-energy-protein-malnutrition","stem":"What complication should be monitored for when treating a malnourished patient with enteral feeding?","options":[{"id":"a","text":"Diarrhea"},{"id":"b","text":"Refeeding syndrome"},{"id":"c","text":"Constipation"},{"id":"d","text":"Dehydration"}],"answerId":"b","explanation":"Refeeding syndrome is a serious complication that can occur if enteral feeding is initiated too rapidly in malnourished patients.","kind":"trap","origin":"ai"},{"id":"nutrition-energy-protein-malnutrition~ai-7","moduleId":"nutrition-energy-protein-malnutrition","stem":"A patient with chronic pancreatitis is at risk for which type of malnutrition?","options":[{"id":"a","text":"Protein-energy malnutrition"},{"id":"b","text":"Vitamin A deficiency"},{"id":"c","text":"Iron deficiency"},{"id":"d","text":"Obesity"}],"answerId":"a","explanation":"Chronic pancreatitis can lead to malabsorption, resulting in protein-energy malnutrition.","kind":"integration","linkedModuleIds":["acute-chronic-pancreatitis"],"origin":"ai"}],"pancreatic-carcinoma":[{"id":"pancreatic-carcinoma~ai-0","moduleId":"pancreatic-carcinoma","stem":"What is the most common mutation associated with pancreatic ductal adenocarcinoma?","options":[{"id":"a","text":"TP53"},{"id":"b","text":"CDKN2A"},{"id":"c","text":"KRAS"},{"id":"d","text":"SMAD4"}],"answerId":"c","explanation":"KRAS mutations are the most prevalent in pancreatic ductal adenocarcinoma, occurring in approximately 90% of cases.","kind":"recall","origin":"ai"},{"id":"pancreatic-carcinoma~ai-1","moduleId":"pancreatic-carcinoma","stem":"A 65-year-old male presents with painless jaundice and weight loss. What is the likely cause of his symptoms?","options":[{"id":"a","text":"Cholecystitis"},{"id":"b","text":"Pancreatic head adenocarcinoma"},{"id":"c","text":"Chronic pancreatitis"},{"id":"d","text":"Hepatitis"}],"answerId":"b","explanation":"Painless obstructive jaundice in an older smoker is highly suggestive of pancreatic head adenocarcinoma.","kind":"clinical","origin":"ai"},{"id":"pancreatic-carcinoma~ai-2","moduleId":"pancreatic-carcinoma","stem":"What histological feature is characteristic of pancreatic ductal adenocarcinoma?","options":[{"id":"a","text":"Lymphocytic infiltration"},{"id":"b","text":"Perineural invasion"},{"id":"c","text":"Granulomatous inflammation"},{"id":"d","text":"Fibrosis"}],"answerId":"b","explanation":"Perineural invasion is a hallmark of the aggressive nature of pancreatic ductal adenocarcinoma.","kind":"mechanism","origin":"ai"},{"id":"pancreatic-carcinoma~ai-3","moduleId":"pancreatic-carcinoma","stem":"A patient has a palpable, non-tender gallbladder with jaundice. What does this finding suggest?","options":[{"id":"a","text":"Gallstones"},{"id":"b","text":"Cholecystitis"},{"id":"c","text":"Malignant biliary obstruction"},{"id":"d","text":"Acute pancreatitis"}],"answerId":"c","explanation":"Courvoisier's sign indicates malignant biliary obstruction, often due to pancreatic head cancer, rather than gallstones.","kind":"trap","origin":"ai"},{"id":"pancreatic-carcinoma~ai-4","moduleId":"pancreatic-carcinoma","stem":"A 70-year-old woman develops new-onset diabetes and weight loss. What should be suspected?","options":[{"id":"a","text":"Type 2 diabetes"},{"id":"b","text":"Pancreatic cancer"},{"id":"c","text":"Chronic pancreatitis"},{"id":"d","text":"Cushing's syndrome"}],"answerId":"b","explanation":"New-onset diabetes in an older adult can be a paraneoplastic syndrome associated with pancreatic cancer.","kind":"clinical","origin":"ai"},{"id":"pancreatic-carcinoma~ai-5","moduleId":"pancreatic-carcinoma","stem":"How does chronic pancreatitis increase the risk of pancreatic cancer?","options":[{"id":"a","text":"By causing bile duct obstruction"},{"id":"b","text":"Through chronic inflammation"},{"id":"c","text":"By inducing diabetes"},{"id":"d","text":"By increasing gallstone formation"}],"answerId":"b","explanation":"Chronic inflammation from pancreatitis can lead to cellular changes that predispose to pancreatic cancer.","kind":"integration","linkedModuleIds":["acute-chronic-pancreatitis"],"origin":"ai"},{"id":"pancreatic-carcinoma~ai-6","moduleId":"pancreatic-carcinoma","stem":"What is a common laboratory finding in patients with pancreatic cancer related to biliary obstruction?","options":[{"id":"a","text":"Elevated AST"},{"id":"b","text":"Elevated alkaline phosphatase"},{"id":"c","text":"Low albumin"},{"id":"d","text":"Elevated amylase"}],"answerId":"b","explanation":"Elevated alkaline phosphatase is often seen in cases of biliary obstruction due to pancreatic cancer.","kind":"integration","linkedModuleIds":["bilirubin-metabolism-jaundice"],"origin":"ai"}],"autoimmune-metabolic-liver-disease":[{"id":"autoimmune-metabolic-liver-disease~ai-0","moduleId":"autoimmune-metabolic-liver-disease","stem":"What is the most characteristic finding in hereditary hemochromatosis?","options":[{"id":"a","text":"Low ceruloplasmin"},{"id":"b","text":"Bronze diabetes"},{"id":"c","text":"Anti-mitochondrial antibodies"},{"id":"d","text":"Beaded bile ducts on MRCP"}],"answerId":"b","explanation":"Hereditary hemochromatosis is characterized by iron overload leading to bronze diabetes, which includes cirrhosis, diabetes, and skin pigmentation.","kind":"recall","origin":"ai"},{"id":"autoimmune-metabolic-liver-disease~ai-1","moduleId":"autoimmune-metabolic-liver-disease","stem":"Which of the following is a common clinical finding in Wilson's disease?","options":[{"id":"a","text":"Cirrhosis + diabetes"},{"id":"b","text":"Kayser–Fleischer rings"},{"id":"c","text":"Anti-smooth-muscle antibodies"},{"id":"d","text":"PAS-positive globules"}],"answerId":"b","explanation":"Kayser–Fleischer rings are a hallmark of Wilson's disease due to copper accumulation.","kind":"recall","origin":"ai"},{"id":"autoimmune-metabolic-liver-disease~ai-2","moduleId":"autoimmune-metabolic-liver-disease","stem":"What is the primary treatment for Wilson's disease?","options":[{"id":"a","text":"Venesection"},{"id":"b","text":"Copper chelation"},{"id":"c","text":"Steroids"},{"id":"d","text":"Liver transplantation"}],"answerId":"b","explanation":"Copper chelation therapy, typically with penicillamine, is the mainstay treatment for Wilson's disease.","kind":"mechanism","origin":"ai"},{"id":"autoimmune-metabolic-liver-disease~ai-3","moduleId":"autoimmune-metabolic-liver-disease","stem":"A 35-year-old woman presents with pruritus and fatigue. Laboratory tests reveal anti-mitochondrial antibodies. What is the most likely diagnosis?","options":[{"id":"a","text":"Primary sclerosing cholangitis"},{"id":"b","text":"Autoimmune hepatitis"},{"id":"c","text":"Primary biliary cholangitis"},{"id":"d","text":"Hereditary hemochromatosis"}],"answerId":"c","explanation":"The presence of anti-mitochondrial antibodies and pruritus is characteristic of primary biliary cholangitis.","kind":"clinical","origin":"ai"},{"id":"autoimmune-metabolic-liver-disease~ai-4","moduleId":"autoimmune-metabolic-liver-disease","stem":"Which condition is associated with 'beaded' bile ducts on MRCP?","options":[{"id":"a","text":"Autoimmune hepatitis"},{"id":"b","text":"Primary biliary cholangitis"},{"id":"c","text":"Primary sclerosing cholangitis"},{"id":"d","text":"Wilson's disease"}],"answerId":"c","explanation":"Primary sclerosing cholangitis is characterized by 'beaded' appearance of bile ducts on imaging.","kind":"recall","origin":"ai"},{"id":"autoimmune-metabolic-liver-disease~ai-5","moduleId":"autoimmune-metabolic-liver-disease","stem":"A patient with ulcerative colitis develops liver disease. Which test is most likely to be positive?","options":[{"id":"a","text":"Anti-mitochondrial antibodies"},{"id":"b","text":"HFE gene mutation"},{"id":"c","text":"Anti-smooth-muscle antibodies"},{"id":"d","text":"Beaded bile ducts on MRCP"}],"answerId":"d","explanation":"Patients with primary sclerosing cholangitis, which is associated with ulcerative colitis, often show 'beaded' bile ducts on MRCP.","kind":"integration","linkedModuleIds":["inflammatory-bowel-disease"],"origin":"ai"},{"id":"autoimmune-metabolic-liver-disease~ai-6","moduleId":"autoimmune-metabolic-liver-disease","stem":"A young man presents with liver disease and movement disorders. Which laboratory finding would you expect?","options":[{"id":"a","text":"High ferritin"},{"id":"b","text":"Low ceruloplasmin"},{"id":"c","text":"High IgG"},{"id":"d","text":"Anti-smooth-muscle antibodies"}],"answerId":"b","explanation":"Wilson's disease is characterized by low ceruloplasmin due to copper accumulation.","kind":"integration","linkedModuleIds":["hepatocellular-carcinoma-liver-tumors"],"origin":"ai"}],"obesity-management-bariatric-surgery":[{"id":"obesity-management-bariatric-surgery~ai-0","moduleId":"obesity-management-bariatric-surgery","stem":"What is the first-line treatment for obesity?","options":[{"id":"a","text":"Surgical intervention"},{"id":"b","text":"Pharmacotherapy"},{"id":"c","text":"Lifestyle modification"},{"id":"d","text":"Dietary supplements"}],"answerId":"c","explanation":"Lifestyle modification is the foundational approach for all obesity treatment, focusing on sustained energy deficit.","kind":"recall","origin":"ai"},{"id":"obesity-management-bariatric-surgery~ai-1","moduleId":"obesity-management-bariatric-surgery","stem":"At what BMI is bariatric surgery typically considered?","options":[{"id":"a","text":"BMI ≥30"},{"id":"b","text":"BMI ≥35 with comorbidity"},{"id":"c","text":"BMI ≥40"},{"id":"d","text":"BMI ≥25 with comorbidity"}],"answerId":"c","explanation":"Bariatric surgery is generally offered at a BMI of 40 or higher, or 35 with significant comorbidities.","kind":"recall","origin":"ai"},{"id":"obesity-management-bariatric-surgery~ai-2","moduleId":"obesity-management-bariatric-surgery","stem":"How does bariatric surgery improve type 2 diabetes?","options":[{"id":"a","text":"By restricting food intake"},{"id":"b","text":"By altering gut hormones"},{"id":"c","text":"By increasing insulin sensitivity"},{"id":"d","text":"By promoting weight loss alone"}],"answerId":"b","explanation":"Bariatric surgery improves type 2 diabetes rapidly by altering gut hormones, not merely by restricting food intake.","kind":"mechanism","origin":"ai"},{"id":"obesity-management-bariatric-surgery~ai-3","moduleId":"obesity-management-bariatric-surgery","stem":"Which vitamin deficiency is a common consequence of bariatric surgery?","options":[{"id":"a","text":"Vitamin C"},{"id":"b","text":"Vitamin B12"},{"id":"c","text":"Vitamin K"},{"id":"d","text":"Vitamin E"}],"answerId":"b","explanation":"Bariatric surgery can lead to lifelong deficiencies in micronutrients, including vitamin B12, due to reduced absorption.","kind":"recall","origin":"ai"},{"id":"obesity-management-bariatric-surgery~ai-4","moduleId":"obesity-management-bariatric-surgery","stem":"What is the role of pharmacotherapy in obesity management?","options":[{"id":"a","text":"First-line treatment"},{"id":"b","text":"Only for BMI <30"},{"id":"c","text":"Adjunct to lifestyle changes"},{"id":"d","text":"Replacement for lifestyle changes"}],"answerId":"c","explanation":"Pharmacotherapy is used as an adjunct to lifestyle changes when lifestyle alone fails, particularly at appropriate BMI thresholds.","kind":"trap","origin":"ai"},{"id":"obesity-management-bariatric-surgery~ai-5","moduleId":"obesity-management-bariatric-surgery","stem":"Which gut hormone is increased after bariatric surgery, contributing to satiety?","options":[{"id":"a","text":"Insulin"},{"id":"b","text":"Ghrelin"},{"id":"c","text":"GLP-1"},{"id":"d","text":"Cortisol"}],"answerId":"c","explanation":"Bariatric surgery increases GLP-1 levels, which enhances satiety signals and contributes to weight loss and metabolic improvements.","kind":"mechanism","origin":"ai"},{"id":"obesity-management-bariatric-surgery~ai-6","moduleId":"obesity-management-bariatric-surgery","stem":"How does the management of obesity relate to the pathophysiology of metabolic syndrome?","options":[{"id":"a","text":"Both focus solely on weight loss"},{"id":"b","text":"Both involve lifestyle changes and hormonal regulation"},{"id":"c","text":"Both are treated only with medications"},{"id":"d","text":"Both require surgical intervention"}],"answerId":"b","explanation":"Obesity management and metabolic syndrome pathophysiology both emphasize lifestyle changes and hormonal regulation as key components.","kind":"integration","linkedModuleIds":["obesity-pathophysiology"],"origin":"ai"},{"id":"obesity-management-bariatric-surgery~ai-7","moduleId":"obesity-management-bariatric-surgery","stem":"What is the connection between bariatric surgery and fat-soluble vitamin deficiencies?","options":[{"id":"a","text":"Surgery increases absorption of fat-soluble vitamins"},{"id":"b","text":"Surgery leads to malabsorption of fat-soluble vitamins"},{"id":"c","text":"Surgery has no effect on vitamin absorption"},{"id":"d","text":"Surgery only affects water-soluble vitamins"}],"answerId":"b","explanation":"Bariatric surgery can lead to malabsorption of fat-soluble vitamins, necessitating lifelong supplementation.","kind":"integration","linkedModuleIds":["fat-soluble-vitamins"],"origin":"ai"}],"laxatives-antidiarrheals-ors":[{"id":"laxatives-antidiarrheals-ors~ai-0","moduleId":"laxatives-antidiarrheals-ors","stem":"Which type of laxative is considered first-line for treating simple constipation?","options":[{"id":"a","text":"Osmotic laxatives"},{"id":"b","text":"Stimulant laxatives"},{"id":"c","text":"Bulk-forming laxatives"},{"id":"d","text":"Stool softeners"}],"answerId":"c","explanation":"Bulk-forming laxatives, such as fiber or psyllium, are the first-line treatment for simple constipation due to their ability to hold water and increase stool bulk.","kind":"recall","origin":"ai"},{"id":"laxatives-antidiarrheals-ors~ai-1","moduleId":"laxatives-antidiarrheals-ors","stem":"What is the primary mechanism by which oral rehydration solutions (ORS) promote water absorption in the intestines?","options":[{"id":"a","text":"Increased intestinal motility"},{"id":"b","text":"Sodium-glucose cotransport"},{"id":"c","text":"Direct water infusion"},{"id":"d","text":"Electrolyte replacement"}],"answerId":"b","explanation":"ORS promotes water absorption through the sodium-glucose cotransporter (SGLT1), which allows sodium and water to be absorbed even in the presence of secretory diarrhoea.","kind":"mechanism","origin":"ai"},{"id":"laxatives-antidiarrheals-ors~ai-2","moduleId":"laxatives-antidiarrheals-ors","stem":"A patient with bloody diarrhea is prescribed loperamide. What is the potential risk of this treatment?","options":[{"id":"a","text":"Increased stool frequency"},{"id":"b","text":"Toxic megacolon"},{"id":"c","text":"Dehydration"},{"id":"d","text":"Electrolyte imbalance"}],"answerId":"b","explanation":"Loperamide should be avoided in patients with bloody diarrhea as it can lead to toxic megacolon by slowing transit and prolonging pathogen contact.","kind":"trap","origin":"ai"},{"id":"laxatives-antidiarrheals-ors~ai-3","moduleId":"laxatives-antidiarrheals-ors","stem":"What is the role of lactulose in treating hepatic encephalopathy?","options":[{"id":"a","text":"It acts as a stimulant laxative"},{"id":"b","text":"It traps ammonia in the gut"},{"id":"c","text":"It promotes sodium absorption"},{"id":"d","text":"It increases intestinal motility"}],"answerId":"b","explanation":"Lactulose traps ammonia in the gut, helping to reduce its absorption and thereby treating hepatic encephalopathy.","kind":"mechanism","origin":"ai"},{"id":"laxatives-antidiarrheals-ors~ai-4","moduleId":"laxatives-antidiarrheals-ors","stem":"Which finding indicates the effectiveness of ORS in cholera?","options":[{"id":"a","text":"Increased stool frequency"},{"id":"b","text":"Decreased dehydration symptoms"},{"id":"c","text":"Absence of abdominal cramping"},{"id":"d","text":"ORS is effective even in profuse diarrhea"}],"answerId":"d","explanation":"ORS remains effective even in profuse cholera diarrhea due to the action of the sodium-glucose cotransporter, which continues to absorb sodium and water.","kind":"recall","origin":"ai"},{"id":"laxatives-antidiarrheals-ors~ai-5","moduleId":"laxatives-antidiarrheals-ors","stem":"In a patient with secretory diarrhea from cholera, which component of ORS is crucial for its effectiveness?","options":[{"id":"a","text":"Sodium"},{"id":"b","text":"Potassium"},{"id":"c","text":"Glucose"},{"id":"d","text":"Citrate"}],"answerId":"c","explanation":"Glucose is crucial in ORS as it enables the sodium-glucose cotransporter to absorb sodium and water, making it effective in secretory diarrhea.","kind":"integration","linkedModuleIds":["secretory-toxigenic-enteritis"],"origin":"ai"},{"id":"laxatives-antidiarrheals-ors~ai-6","moduleId":"laxatives-antidiarrheals-ors","stem":"How does the use of antispasmodics relate to the treatment of IBS?","options":[{"id":"a","text":"They increase motility"},{"id":"b","text":"They relieve cramping and colic"},{"id":"c","text":"They prevent dehydration"},{"id":"d","text":"They enhance absorption of nutrients"}],"answerId":"b","explanation":"Antispasmodics are used in IBS to relieve cramping and colic, addressing the symptoms associated with this functional GI disorder.","kind":"integration","linkedModuleIds":["ibs-functional-gi-disorders"],"origin":"ai"}],"peptic-ulcer-disease":[{"id":"peptic-ulcer-disease~ai-0","moduleId":"peptic-ulcer-disease","stem":"What is the most common cause of duodenal ulcers?","options":[{"id":"a","text":"NSAIDs"},{"id":"b","text":"Gastric cancer"},{"id":"c","text":"Helicobacter pylori"},{"id":"d","text":"Stress"}],"answerId":"c","explanation":"Duodenal ulcers are almost always associated with Helicobacter pylori infection, which increases acid secretion.","kind":"recall","origin":"ai"},{"id":"peptic-ulcer-disease~ai-1","moduleId":"peptic-ulcer-disease","stem":"Which symptom is classically associated with gastric ulcers?","options":[{"id":"a","text":"Epigastric pain relieved by food"},{"id":"b","text":"Weight gain"},{"id":"c","text":"Epigastric pain worse with food"},{"id":"d","text":"Nausea without vomiting"}],"answerId":"c","explanation":"Gastric ulcers typically present with epigastric pain that worsens with food intake, often leading to weight loss.","kind":"recall","origin":"ai"},{"id":"peptic-ulcer-disease~ai-2","moduleId":"peptic-ulcer-disease","stem":"A patient presents with sudden severe abdominal pain and free air under the diaphragm. What is the most likely diagnosis?","options":[{"id":"a","text":"Gastric ulcer"},{"id":"b","text":"Perforated duodenal ulcer"},{"id":"c","text":"Zollinger–Ellison syndrome"},{"id":"d","text":"Gastric cancer"}],"answerId":"b","explanation":"Free air under the diaphragm indicates perforation, which is commonly associated with anterior duodenal ulcers.","kind":"clinical","origin":"ai"},{"id":"peptic-ulcer-disease~ai-3","moduleId":"peptic-ulcer-disease","stem":"What is the mechanism by which NSAIDs contribute to peptic ulcer disease?","options":[{"id":"a","text":"Increased acid secretion"},{"id":"b","text":"Inhibition of mucosal defense"},{"id":"c","text":"Direct mucosal irritation"},{"id":"d","text":"Increased pepsinogen production"}],"answerId":"b","explanation":"NSAIDs inhibit prostaglandin synthesis, which diminishes the protective mucosal defense, leading to ulcer formation.","kind":"mechanism","origin":"ai"},{"id":"peptic-ulcer-disease~ai-4","moduleId":"peptic-ulcer-disease","stem":"Which of the following findings would necessitate a biopsy in a patient with a gastric ulcer?","options":[{"id":"a","text":"Epigastric pain"},{"id":"b","text":"Weight loss"},{"id":"c","text":"History of NSAID use"},{"id":"d","text":"No alarm features"}],"answerId":"b","explanation":"Weight loss is an alarm feature that requires biopsy to exclude malignancy in gastric ulcers.","kind":"trap","origin":"ai"},{"id":"peptic-ulcer-disease~ai-5","moduleId":"peptic-ulcer-disease","stem":"In Zollinger–Ellison syndrome, what laboratory finding is typically elevated?","options":[{"id":"a","text":"Fasting gastrin levels"},{"id":"b","text":"Serum amylase"},{"id":"c","text":"Hemoglobin"},{"id":"d","text":"Bicarbonate levels"}],"answerId":"a","explanation":"Patients with Zollinger–Ellison syndrome have elevated fasting gastrin levels due to gastrin-secreting tumors.","kind":"recall","origin":"ai"},{"id":"peptic-ulcer-disease~ai-6","moduleId":"peptic-ulcer-disease","stem":"How does the management of peptic ulcer disease relate to the treatment of gastritis?","options":[{"id":"a","text":"Both require surgical intervention"},{"id":"b","text":"Both involve acid suppression therapy"},{"id":"c","text":"Both are caused by H. pylori"},{"id":"d","text":"Both lead to weight gain"}],"answerId":"b","explanation":"Both peptic ulcer disease and gastritis often involve acid suppression therapy to reduce symptoms and promote healing.","kind":"integration","linkedModuleIds":["gastritis-and-gastropathy"],"origin":"ai"},{"id":"peptic-ulcer-disease~ai-7","moduleId":"peptic-ulcer-disease","stem":"What is a common complication of peptic ulcers that is also relevant in gastrointestinal bleeding?","options":[{"id":"a","text":"Gastric outlet obstruction"},{"id":"b","text":"Hemorrhage"},{"id":"c","text":"Diarrhea"},{"id":"d","text":"Constipation"}],"answerId":"b","explanation":"Hemorrhage is a common complication of peptic ulcers and is a significant concern in the context of gastrointestinal bleeding.","kind":"integration","linkedModuleIds":["gastrointestinal-bleeding-approach"],"origin":"ai"}],"nutritional-assessment-support":[{"id":"nutritional-assessment-support~ai-0","moduleId":"nutritional-assessment-support","stem":"What is the primary purpose of nutritional assessment in hospitalized patients?","options":[{"id":"a","text":"To diagnose chronic diseases"},{"id":"b","text":"To identify malnutrition or risk of malnutrition"},{"id":"c","text":"To prescribe medications"},{"id":"d","text":"To evaluate surgical outcomes"}],"answerId":"b","explanation":"Nutritional assessment aims to identify patients who are malnourished or at risk, allowing for timely support to prevent complications.","kind":"recall","origin":"ai"},{"id":"nutritional-assessment-support~ai-1","moduleId":"nutritional-assessment-support","stem":"Which BMI value indicates significant malnutrition requiring nutritional support?","options":[{"id":"a","text":"<20 kg/m²"},{"id":"b","text":"<18.5 kg/m²"},{"id":"c","text":"<25 kg/m²"},{"id":"d","text":"<22 kg/m²"}],"answerId":"b","explanation":"A BMI <18.5 kg/m² suggests significant malnutrition and the need for nutritional support.","kind":"recall","origin":"ai"},{"id":"nutritional-assessment-support~ai-2","moduleId":"nutritional-assessment-support","stem":"What is the mechanism behind refeeding syndrome?","options":[{"id":"a","text":"Increased insulin secretion causes electrolyte shifts"},{"id":"b","text":"Decreased gut motility leads to nutrient malabsorption"},{"id":"c","text":"Rapid weight gain causes fluid overload"},{"id":"d","text":"Increased appetite leads to overeating"}],"answerId":"a","explanation":"Refeeding syndrome occurs due to an insulin surge that drives phosphate, potassium, and magnesium into cells, leading to dangerous hypophosphatemia.","kind":"mechanism","origin":"ai"},{"id":"nutritional-assessment-support~ai-3","moduleId":"nutritional-assessment-support","stem":"Which of the following findings suggests a patient is at risk for refeeding syndrome?","options":[{"id":"a","text":"Increased appetite"},{"id":"b","text":"Low albumin levels"},{"id":"c","text":"BMI >25 kg/m²"},{"id":"d","text":"Severe malnutrition"}],"answerId":"d","explanation":"Severe malnutrition is a major risk factor for refeeding syndrome when feeding is restarted.","kind":"clinical","origin":"ai"},{"id":"nutritional-assessment-support~ai-4","moduleId":"nutritional-assessment-support","stem":"In which situation is parenteral nutrition preferred over enteral nutrition?","options":[{"id":"a","text":"Patient has a functioning gut"},{"id":"b","text":"Patient is unable to swallow"},{"id":"c","text":"Patient has intestinal obstruction"},{"id":"d","text":"Patient requires long-term feeding"}],"answerId":"c","explanation":"Parenteral nutrition is reserved for cases where the gut is non-functioning or inaccessible, such as intestinal obstruction.","kind":"trap","origin":"ai"},{"id":"nutritional-assessment-support~ai-5","moduleId":"nutritional-assessment-support","stem":"How does enteral nutrition benefit patients compared to parenteral nutrition?","options":[{"id":"a","text":"It is more expensive"},{"id":"b","text":"It carries a higher risk of infection"},{"id":"c","text":"It maintains gut integrity"},{"id":"d","text":"It is easier to administer"}],"answerId":"c","explanation":"Enteral nutrition is preferred because it maintains gut integrity and has fewer complications compared to parenteral nutrition.","kind":"trap","origin":"ai"},{"id":"nutritional-assessment-support~ai-6","moduleId":"nutritional-assessment-support","stem":"How does nutritional support relate to recovery in chronic GI disease?","options":[{"id":"a","text":"It is irrelevant to recovery"},{"id":"b","text":"It is only important post-surgery"},{"id":"c","text":"It underpins recovery across various conditions"},{"id":"d","text":"It only affects weight gain"}],"answerId":"c","explanation":"Nutritional support is crucial for recovery across various conditions, including chronic GI diseases, by providing necessary nutrients.","kind":"integration","linkedModuleIds":["physical-nutritional-injury"],"origin":"ai"},{"id":"nutritional-assessment-support~ai-7","moduleId":"nutritional-assessment-support","stem":"What is the recommended protein intake for a patient in a catabolic state?","options":[{"id":"a","text":"0.5 g/kg/day"},{"id":"b","text":"1.0 g/kg/day"},{"id":"c","text":"1.5 g/kg/day"},{"id":"d","text":"2.0 g/kg/day"}],"answerId":"c","explanation":"Patients in catabolic states typically require around 1.0–1.5 g of protein per kg of body weight per day.","kind":"recall","origin":"ai"}],"obesity-pathophysiology":[{"id":"obesity-pathophysiology~ai-0","moduleId":"obesity-pathophysiology","stem":"What is the primary mechanism by which central obesity contributes to insulin resistance?","options":[{"id":"a","text":"Increased leptin secretion"},{"id":"b","text":"Elevated free fatty acids"},{"id":"c","text":"Decreased adiponectin levels"},{"id":"d","text":"Increased ghrelin levels"}],"answerId":"b","explanation":"Central obesity leads to elevated free fatty acids and adipokines, which promote insulin resistance.","kind":"mechanism","origin":"ai"},{"id":"obesity-pathophysiology~ai-1","moduleId":"obesity-pathophysiology","stem":"Which of the following findings is most characteristic of metabolic syndrome?","options":[{"id":"a","text":"Low HDL cholesterol"},{"id":"b","text":"Increased physical activity"},{"id":"c","text":"Decreased waist circumference"},{"id":"d","text":"Low blood pressure"}],"answerId":"a","explanation":"Metabolic syndrome is characterized by low HDL cholesterol among other features.","kind":"recall","origin":"ai"},{"id":"obesity-pathophysiology~ai-2","moduleId":"obesity-pathophysiology","stem":"In obesity, why do patients often have high levels of leptin?","options":[{"id":"a","text":"Leptin is deficient in obesity"},{"id":"b","text":"Leptin levels are inversely related to fat mass"},{"id":"c","text":"Leptin resistance prevents normal signaling"},{"id":"d","text":"Leptin is only produced in lean individuals"}],"answerId":"c","explanation":"Obese individuals typically have high leptin levels but are resistant to its effects, leading to continued overeating.","kind":"trap","origin":"ai"},{"id":"obesity-pathophysiology~ai-3","moduleId":"obesity-pathophysiology","stem":"What is the most common cause of obstructive sleep apnoea in obese patients?","options":[{"id":"a","text":"Nasal obstruction"},{"id":"b","text":"Hypothyroidism"},{"id":"c","text":"Central nervous system disorders"},{"id":"d","text":"Excessive adipose tissue in the neck"}],"answerId":"d","explanation":"Excessive adipose tissue in the neck can obstruct the airway during sleep, leading to obstructive sleep apnoea.","kind":"clinical","origin":"ai"},{"id":"obesity-pathophysiology~ai-4","moduleId":"obesity-pathophysiology","stem":"Which hormone is primarily responsible for signaling satiety to the hypothalamus?","options":[{"id":"a","text":"Ghrelin"},{"id":"b","text":"Leptin"},{"id":"c","text":"Adiponectin"},{"id":"d","text":"Insulin"}],"answerId":"b","explanation":"Leptin signals satiety and energy stores to the hypothalamus, but in obesity, resistance to leptin occurs.","kind":"recall","origin":"ai"},{"id":"obesity-pathophysiology~ai-5","moduleId":"obesity-pathophysiology","stem":"How does obesity contribute to the development of non-alcoholic fatty liver disease (NAFLD)?","options":[{"id":"a","text":"Increased alcohol consumption"},{"id":"b","text":"Decreased liver fat storage"},{"id":"c","text":"Insulin resistance and increased free fatty acids"},{"id":"d","text":"Reduced dietary fat intake"}],"answerId":"c","explanation":"Obesity leads to insulin resistance and increased free fatty acids, contributing to the development of NAFLD.","kind":"mechanism","origin":"ai"},{"id":"obesity-pathophysiology~ai-6","moduleId":"obesity-pathophysiology","stem":"How does obesity influence the risk of developing type 2 diabetes?","options":[{"id":"a","text":"By decreasing insulin secretion"},{"id":"b","text":"By increasing physical activity"},{"id":"c","text":"Through visceral fat-driven insulin resistance"},{"id":"d","text":"By lowering blood glucose levels"}],"answerId":"c","explanation":"Visceral fat contributes to insulin resistance, which is a key factor in the development of type 2 diabetes.","kind":"integration","linkedModuleIds":["prediabetes-ogtt-hba1c"],"origin":"ai"},{"id":"obesity-pathophysiology~ai-7","moduleId":"obesity-pathophysiology","stem":"What is the relationship between obesity and cardiovascular disease?","options":[{"id":"a","text":"Obesity decreases cardiovascular risk"},{"id":"b","text":"Obesity has no impact on cardiovascular health"},{"id":"c","text":"Obesity increases risk through metabolic syndrome"},{"id":"d","text":"Obesity only affects the liver"}],"answerId":"c","explanation":"Obesity increases cardiovascular risk primarily through the components of metabolic syndrome.","kind":"integration","linkedModuleIds":["cirrhosis-fatty-liver-portal-hypertension"],"origin":"ai"}],"ibs-functional-gi-disorders":[{"id":"ibs-functional-gi-disorders~ai-0","moduleId":"ibs-functional-gi-disorders","stem":"What is the primary characteristic of irritable bowel syndrome (IBS)?","options":[{"id":"a","text":"Recurrent abdominal pain related to defecation"},{"id":"b","text":"Presence of structural abnormalities"},{"id":"c","text":"Acute onset of symptoms"},{"id":"d","text":"Diarrhea only without constipation"}],"answerId":"a","explanation":"IBS is defined by recurrent abdominal pain that is related to defecation, along with changes in stool frequency or form.","kind":"recall","origin":"ai"},{"id":"ibs-functional-gi-disorders~ai-1","moduleId":"ibs-functional-gi-disorders","stem":"Which of the following is an ALARM feature that requires further investigation in a patient suspected of having IBS?","options":[{"id":"a","text":"Recurrent abdominal pain"},{"id":"b","text":"Normal bowel habits"},{"id":"c","text":"Weight loss"},{"id":"d","text":"Mild abdominal discomfort"}],"answerId":"c","explanation":"Weight loss is an ALARM feature that necessitates investigation to rule out organic diseases such as cancer or inflammatory bowel disease.","kind":"trap","origin":"ai"},{"id":"ibs-functional-gi-disorders~ai-2","moduleId":"ibs-functional-gi-disorders","stem":"What mechanism is primarily involved in the pathophysiology of IBS?","options":[{"id":"a","text":"Visceral hypersensitivity"},{"id":"b","text":"Increased gastric acid secretion"},{"id":"c","text":"Structural bowel obstruction"},{"id":"d","text":"Intestinal ischemia"}],"answerId":"a","explanation":"Visceral hypersensitivity is a key mechanism in IBS, leading to abnormal gut sensations and pain.","kind":"mechanism","origin":"ai"},{"id":"ibs-functional-gi-disorders~ai-3","moduleId":"ibs-functional-gi-disorders","stem":"A patient presents with recurrent abdominal pain, altered bowel habits, and a recent history of gastroenteritis. What is the most likely diagnosis?","options":[{"id":"a","text":"Irritable bowel syndrome"},{"id":"b","text":"Inflammatory bowel disease"},{"id":"c","text":"Colorectal cancer"},{"id":"d","text":"Functional dyspepsia"}],"answerId":"a","explanation":"The symptoms and recent gastroenteritis suggest post-infectious IBS, a common presentation.","kind":"clinical","origin":"ai"},{"id":"ibs-functional-gi-disorders~ai-4","moduleId":"ibs-functional-gi-disorders","stem":"Which dietary intervention is most effective for managing symptoms in IBS?","options":[{"id":"a","text":"High-fiber diet"},{"id":"b","text":"Low-FODMAP diet"},{"id":"c","text":"Gluten-free diet"},{"id":"d","text":"Ketogenic diet"}],"answerId":"b","explanation":"The low-FODMAP diet is specifically designed to reduce symptoms in patients with IBS by limiting fermentable carbohydrates.","kind":"recall","origin":"ai"},{"id":"ibs-functional-gi-disorders~ai-5","moduleId":"ibs-functional-gi-disorders","stem":"How does IBS differ from organic gastrointestinal diseases?","options":[{"id":"a","text":"IBS has identifiable structural abnormalities"},{"id":"b","text":"IBS symptoms are chronic without structural disease"},{"id":"c","text":"IBS always presents with weight loss"},{"id":"d","text":"IBS requires surgical intervention"}],"answerId":"b","explanation":"IBS is characterized by chronic symptoms without any identifiable structural or biochemical abnormalities.","kind":"trap","origin":"ai"},{"id":"ibs-functional-gi-disorders~ai-6","moduleId":"ibs-functional-gi-disorders","stem":"In a patient with IBS, which of the following findings would prompt further investigation for organic disease?","options":[{"id":"a","text":"Normal colonoscopy results"},{"id":"b","text":"Diarrhea alternating with constipation"},{"id":"c","text":"Age over 50 with new symptoms"},{"id":"d","text":"Improvement with dietary changes"}],"answerId":"c","explanation":"New symptoms in a patient over 50 years old are considered an ALARM feature that requires further investigation.","kind":"integration","linkedModuleIds":["colorectal-polyps-carcinoma"],"origin":"ai"},{"id":"ibs-functional-gi-disorders~ai-7","moduleId":"ibs-functional-gi-disorders","stem":"A patient with IBS presents with rectal bleeding. What should be the next step in management?","options":[{"id":"a","text":"Start a low-FODMAP diet"},{"id":"b","text":"Perform a colonoscopy"},{"id":"c","text":"Prescribe antispasmodics"},{"id":"d","text":"Initiate psychological therapy"}],"answerId":"b","explanation":"Rectal bleeding is an ALARM feature that necessitates further investigation to rule out organic causes.","kind":"integration","linkedModuleIds":["inflammatory-bowel-disease"],"origin":"ai"}],"acid-suppression-h-pylori-therapy":[{"id":"acid-suppression-h-pylori-therapy~ai-0","moduleId":"acid-suppression-h-pylori-therapy","stem":"What is the primary mechanism of action of proton pump inhibitors (PPIs)?","options":[{"id":"a","text":"Inhibit H2 receptors"},{"id":"b","text":"Neutralize gastric acid"},{"id":"c","text":"Irreversibly inhibit H⁺/K⁺-ATPase"},{"id":"d","text":"Stimulate mucosal defense"}],"answerId":"c","explanation":"PPIs irreversibly inhibit the H⁺/K⁺-ATPase, which is the final step in gastric acid secretion.","kind":"mechanism","origin":"ai"},{"id":"acid-suppression-h-pylori-therapy~ai-1","moduleId":"acid-suppression-h-pylori-therapy","stem":"Which of the following is a common side effect of long-term PPI use?","options":[{"id":"a","text":"Increased gastric acid secretion"},{"id":"b","text":"C. difficile infection"},{"id":"c","text":"Decreased iron absorption"},{"id":"d","text":"Increased risk of NSAID ulcers"}],"answerId":"b","explanation":"Long-term PPI use can lead to decreased gastric acidity, which increases the risk of C. difficile infections.","kind":"recall","origin":"ai"},{"id":"acid-suppression-h-pylori-therapy~ai-2","moduleId":"acid-suppression-h-pylori-therapy","stem":"What is the standard therapy for H. pylori eradication?","options":[{"id":"a","text":"PPI + bismuth + metronidazole + tetracycline"},{"id":"b","text":"PPI + clarithromycin + amoxicillin"},{"id":"c","text":"H2-receptor antagonist + antibiotics"},{"id":"d","text":"Antacid + sucralfate"}],"answerId":"b","explanation":"The standard therapy for H. pylori eradication is a PPI combined with clarithromycin and amoxicillin.","kind":"recall","origin":"ai"},{"id":"acid-suppression-h-pylori-therapy~ai-3","moduleId":"acid-suppression-h-pylori-therapy","stem":"A patient with a peptic ulcer is treated with a PPI alone. What is the likely outcome?","options":[{"id":"a","text":"Complete healing of the ulcer"},{"id":"b","text":"Recurrence of the ulcer"},{"id":"c","text":"Eradication of H. pylori"},{"id":"d","text":"No change in symptoms"}],"answerId":"b","explanation":"Treating a peptic ulcer with a PPI alone does not eradicate H. pylori, leading to ulcer recurrence.","kind":"trap","origin":"ai"},{"id":"acid-suppression-h-pylori-therapy~ai-4","moduleId":"acid-suppression-h-pylori-therapy","stem":"Which of the following is a mucosal protectant used in ulcer therapy?","options":[{"id":"a","text":"Omeprazole"},{"id":"b","text":"Ranitidine"},{"id":"c","text":"Sucralfate"},{"id":"d","text":"Misoprostol"}],"answerId":"c","explanation":"Sucralfate is a mucosal protectant that coats the ulcer base and promotes healing.","kind":"recall","origin":"ai"},{"id":"acid-suppression-h-pylori-therapy~ai-5","moduleId":"acid-suppression-h-pylori-therapy","stem":"How does misoprostol prevent NSAID-induced ulcers?","options":[{"id":"a","text":"Inhibits gastric acid secretion"},{"id":"b","text":"Stimulates mucus and bicarbonate secretion"},{"id":"c","text":"Increases gastric motility"},{"id":"d","text":"Inhibits H. pylori growth"}],"answerId":"b","explanation":"Misoprostol is a prostaglandin analogue that stimulates mucus and bicarbonate secretion, protecting the gastric mucosa.","kind":"mechanism","origin":"ai"},{"id":"acid-suppression-h-pylori-therapy~ai-6","moduleId":"acid-suppression-h-pylori-therapy","stem":"In a patient with peptic ulcer disease, what is the link between H. pylori eradication and vitamin absorption?","options":[{"id":"a","text":"H. pylori increases B12 absorption"},{"id":"b","text":"PPI use decreases magnesium absorption"},{"id":"c","text":"Eradication improves iron absorption"},{"id":"d","text":"H. pylori does not affect vitamin absorption"}],"answerId":"b","explanation":"Long-term PPI use can lead to decreased absorption of magnesium and other nutrients due to reduced gastric acidity.","kind":"integration","linkedModuleIds":["water-soluble-vitamins-trace-elements"],"origin":"ai"},{"id":"acid-suppression-h-pylori-therapy~ai-7","moduleId":"acid-suppression-h-pylori-therapy","stem":"What is the relationship between gastric acid secretion and the treatment of peptic ulcers?","options":[{"id":"a","text":"Increased acid secretion heals ulcers"},{"id":"b","text":"Decreased acid secretion promotes ulcer healing"},{"id":"c","text":"Acid suppression has no effect on ulcers"},{"id":"d","text":"Acid secretion is unrelated to H. pylori"}],"answerId":"b","explanation":"Decreased gastric acid secretion through PPIs promotes healing of peptic ulcers, especially those caused by H. pylori.","kind":"integration","linkedModuleIds":["gastric-acid-mechanism-control"],"origin":"ai"}],"antiemetics-prokinetics":[{"id":"antiemetics-prokinetics~ai-0","moduleId":"antiemetics-prokinetics","stem":"Which antiemetic is primarily indicated for chemotherapy-induced nausea?","options":[{"id":"a","text":"Metoclopramide"},{"id":"b","text":"Ondansetron"},{"id":"c","text":"Domperidone"},{"id":"d","text":"Aprepitant"}],"answerId":"b","explanation":"Ondansetron is a 5-HT3 receptor antagonist, making it the first-line treatment for chemotherapy-induced nausea.","kind":"recall","origin":"ai"},{"id":"antiemetics-prokinetics~ai-1","moduleId":"antiemetics-prokinetics","stem":"What is the mechanism of action of metoclopramide as a prokinetic agent?","options":[{"id":"a","text":"Inhibition of gastric acid secretion"},{"id":"b","text":"Enhancement of acetylcholine release"},{"id":"c","text":"Stimulation of motilin receptors"},{"id":"d","text":"Blocking serotonin receptors"}],"answerId":"b","explanation":"Metoclopramide enhances acetylcholine release, which speeds gastric emptying.","kind":"mechanism","origin":"ai"},{"id":"antiemetics-prokinetics~ai-2","moduleId":"antiemetics-prokinetics","stem":"A patient develops acute dystonia after receiving metoclopramide. What is the likely cause?","options":[{"id":"a","text":"Peripheral D2 blockade"},{"id":"b","text":"Central D2 blockade"},{"id":"c","text":"Serotonin receptor antagonism"},{"id":"d","text":"Histamine receptor blockade"}],"answerId":"b","explanation":"Metoclopramide crosses the blood-brain barrier and causes acute dystonia due to central D2 blockade.","kind":"clinical","origin":"ai"},{"id":"antiemetics-prokinetics~ai-3","moduleId":"antiemetics-prokinetics","stem":"Which of the following antiemetics is least likely to cause extrapyramidal side effects?","options":[{"id":"a","text":"Metoclopramide"},{"id":"b","text":"Domperidone"},{"id":"c","text":"Prochlorperazine"},{"id":"d","text":"Ondansetron"}],"answerId":"b","explanation":"Domperidone does not readily cross the blood-brain barrier, resulting in fewer central side effects compared to metoclopramide.","kind":"trap","origin":"ai"},{"id":"antiemetics-prokinetics~ai-4","moduleId":"antiemetics-prokinetics","stem":"What is a common side effect of ondansetron that requires monitoring?","options":[{"id":"a","text":"Extrapyramidal symptoms"},{"id":"b","text":"QT prolongation"},{"id":"c","text":"Gastrointestinal bleeding"},{"id":"d","text":"Sedation"}],"answerId":"b","explanation":"Ondansetron can prolong the QT interval, which necessitates monitoring in at-risk patients.","kind":"recall","origin":"ai"},{"id":"antiemetics-prokinetics~ai-5","moduleId":"antiemetics-prokinetics","stem":"How does the mechanism of action of domperidone differ from that of metoclopramide?","options":[{"id":"a","text":"Domperidone enhances gastric motility, metoclopramide does not"},{"id":"b","text":"Domperidone does not cross the blood-brain barrier, metoclopramide does"},{"id":"c","text":"Domperidone is a 5-HT3 antagonist, metoclopramide is not"},{"id":"d","text":"Domperidone is only effective for motion sickness"}],"answerId":"b","explanation":"Domperidone does not cross the blood-brain barrier, while metoclopramide does, leading to different side effect profiles.","kind":"integration","linkedModuleIds":["acid-suppression-h-pylori-therapy"],"origin":"ai"},{"id":"antiemetics-prokinetics~ai-6","moduleId":"antiemetics-prokinetics","stem":"Which antiemetic would be most appropriate for a patient with gastroparesis?","options":[{"id":"a","text":"Ondansetron"},{"id":"b","text":"Metoclopramide"},{"id":"c","text":"Aprepitant"},{"id":"d","text":"Cyclizine"}],"answerId":"b","explanation":"Metoclopramide is a prokinetic agent that enhances gastric emptying, making it suitable for gastroparesis.","kind":"recall","origin":"ai"}],"obesity-pharmacotherapy":[{"id":"obesity-pharmacotherapy~ai-0","moduleId":"obesity-pharmacotherapy","stem":"Which of the following is the primary mechanism of action for GLP-1 receptor agonists like semaglutide?","options":[{"id":"a","text":"Increase appetite"},{"id":"b","text":"Enhance satiety"},{"id":"c","text":"Inhibit gastric acid secretion"},{"id":"d","text":"Block fat absorption"}],"answerId":"b","explanation":"GLP-1 receptor agonists enhance satiety by acting on hypothalamic appetite centers, leading to weight loss.","kind":"mechanism","origin":"ai"},{"id":"obesity-pharmacotherapy~ai-1","moduleId":"obesity-pharmacotherapy","stem":"What is the main side effect associated with orlistat?","options":[{"id":"a","text":"Increased heart rate"},{"id":"b","text":"Nausea"},{"id":"c","text":"Steatorrhea"},{"id":"d","text":"Hypoglycemia"}],"answerId":"c","explanation":"Orlistat inhibits lipase, leading to malabsorption of dietary fat and causing steatorrhea.","kind":"recall","origin":"ai"},{"id":"obesity-pharmacotherapy~ai-2","moduleId":"obesity-pharmacotherapy","stem":"Which of the following statements about anti-obesity medications is true?","options":[{"id":"a","text":"They replace the need for diet and exercise"},{"id":"b","text":"They are adjuncts to lifestyle changes"},{"id":"c","text":"They are effective without any lifestyle modification"},{"id":"d","text":"They are only indicated for patients with a BMI <27"}],"answerId":"b","explanation":"Anti-obesity drugs are adjuncts to lifestyle modification, used when lifestyle alone is insufficient.","kind":"trap","origin":"ai"},{"id":"obesity-pharmacotherapy~ai-3","moduleId":"obesity-pharmacotherapy","stem":"A patient on phentermine reports increased heart rate. What is the likely explanation?","options":[{"id":"a","text":"Increased gastric emptying"},{"id":"b","text":"Sympathomimetic effect"},{"id":"c","text":"Inhibition of lipase"},{"id":"d","text":"Decreased appetite"}],"answerId":"b","explanation":"Phentermine is a sympathomimetic that can raise heart rate and blood pressure.","kind":"clinical","origin":"ai"},{"id":"obesity-pharmacotherapy~ai-4","moduleId":"obesity-pharmacotherapy","stem":"Which vitamin deficiency is most likely to occur with the use of orlistat?","options":[{"id":"a","text":"Vitamin C"},{"id":"b","text":"Vitamin B12"},{"id":"c","text":"Vitamin D"},{"id":"d","text":"Vitamin A"}],"answerId":"c","explanation":"Orlistat can lead to malabsorption of fat-soluble vitamins, including vitamin D.","kind":"integration","linkedModuleIds":["fat-soluble-vitamins"],"origin":"ai"},{"id":"obesity-pharmacotherapy~ai-5","moduleId":"obesity-pharmacotherapy","stem":"How do GLP-1 receptor agonists contribute to improved glycemic control?","options":[{"id":"a","text":"Increase insulin secretion"},{"id":"b","text":"Decrease glucagon release"},{"id":"c","text":"Slow gastric emptying"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"GLP-1 receptor agonists enhance insulin secretion, decrease glucagon release, and slow gastric emptying, contributing to glycemic control.","kind":"integration","linkedModuleIds":["gut-hormones-appetite-regulation"],"origin":"ai"},{"id":"obesity-pharmacotherapy~ai-6","moduleId":"obesity-pharmacotherapy","stem":"Which of the following is a contraindication for GLP-1 receptor agonists?","options":[{"id":"a","text":"History of obesity"},{"id":"b","text":"Family history of medullary thyroid carcinoma"},{"id":"c","text":"Age over 65"},{"id":"d","text":"Hypertension"}],"answerId":"b","explanation":"GLP-1 receptor agonists have a boxed warning for use in patients with a family history of medullary thyroid carcinoma.","kind":"clinical","origin":"ai"}],"secretory-toxigenic-enteritis":[{"id":"secretory-toxigenic-enteritis~ai-0","moduleId":"secretory-toxigenic-enteritis","stem":"What is the primary mechanism by which cholera toxin induces watery diarrhea?","options":[{"id":"a","text":"Inhibition of sodium absorption"},{"id":"b","text":"Activation of adenylate cyclase"},{"id":"c","text":"Stimulation of mucus secretion"},{"id":"d","text":"Inhibition of chloride secretion"}],"answerId":"b","explanation":"Cholera toxin activates adenylate cyclase, increasing cAMP levels, which leads to massive chloride and water secretion.","kind":"mechanism","origin":"ai"},{"id":"secretory-toxigenic-enteritis~ai-1","moduleId":"secretory-toxigenic-enteritis","stem":"Which of the following findings is characteristic of secretory (toxigenic) diarrhea?","options":[{"id":"a","text":"Presence of fecal leukocytes"},{"id":"b","text":"High fever"},{"id":"c","text":"Watery, non-bloody stools"},{"id":"d","text":"Abdominal pain with blood in stool"}],"answerId":"c","explanation":"Secretory diarrhea is characterized by watery, non-bloody stools without fecal leukocytes or fever.","kind":"recall","origin":"ai"},{"id":"secretory-toxigenic-enteritis~ai-2","moduleId":"secretory-toxigenic-enteritis","stem":"What is the most effective treatment for cholera-induced diarrhea?","options":[{"id":"a","text":"Intravenous fluids only"},{"id":"b","text":"Antibiotics"},{"id":"c","text":"Oral rehydration solution"},{"id":"d","text":"Antidiarrheal medications"}],"answerId":"c","explanation":"Oral rehydration solution is effective because the Na⁺–glucose cotransporter remains functional, allowing for effective fluid replacement.","kind":"trap","origin":"ai"},{"id":"secretory-toxigenic-enteritis~ai-3","moduleId":"secretory-toxigenic-enteritis","stem":"A traveler presents with watery diarrhea and no fever. Which organism is most likely responsible?","options":[{"id":"a","text":"Salmonella"},{"id":"b","text":"Enterotoxigenic E. coli"},{"id":"c","text":"Shigella"},{"id":"d","text":"Clostridium difficile"}],"answerId":"b","explanation":"Enterotoxigenic E. coli is a common cause of traveler's diarrhea characterized by watery stools without fever.","kind":"clinical","origin":"ai"},{"id":"secretory-toxigenic-enteritis~ai-4","moduleId":"secretory-toxigenic-enteritis","stem":"Which of the following is a common source of Staphylococcus aureus preformed toxin?","options":[{"id":"a","text":"Reheated fried rice"},{"id":"b","text":"Dairy products"},{"id":"c","text":"Undercooked poultry"},{"id":"d","text":"Raw vegetables"}],"answerId":"b","explanation":"Staphylococcus aureus preformed toxin is commonly found in dairy products and mayonnaise, leading to rapid-onset vomiting.","kind":"recall","origin":"ai"},{"id":"secretory-toxigenic-enteritis~ai-5","moduleId":"secretory-toxigenic-enteritis","stem":"How does the mechanism of secretory diarrhea differ from that of inflammatory diarrhea?","options":[{"id":"a","text":"Secretory diarrhea involves toxin-induced secretion, while inflammatory diarrhea involves mucosal invasion."},{"id":"b","text":"Both types involve similar mechanisms."},{"id":"c","text":"Secretory diarrhea is always bloody, while inflammatory is not."},{"id":"d","text":"Inflammatory diarrhea is caused by viruses only."}],"answerId":"a","explanation":"Secretory diarrhea is driven by toxins causing fluid secretion without mucosal invasion, while inflammatory diarrhea involves mucosal damage and often presents with blood.","kind":"integration","linkedModuleIds":["inflammatory-invasive-enteritis"],"origin":"ai"},{"id":"secretory-toxigenic-enteritis~ai-6","moduleId":"secretory-toxigenic-enteritis","stem":"Which of the following is a key difference between cholera and viral gastroenteritis?","options":[{"id":"a","text":"Cholera causes bloody diarrhea, while viral gastroenteritis does not."},{"id":"b","text":"Cholera is treated with antibiotics, while viral gastroenteritis is not."},{"id":"c","text":"Cholera is characterized by massive fluid loss, while viral gastroenteritis typically has less severe fluid loss."},{"id":"d","text":"Cholera is caused by a virus."}],"answerId":"c","explanation":"Cholera causes massive fluid loss due to toxin-induced secretion, while viral gastroenteritis generally leads to milder fluid loss.","kind":"integration","linkedModuleIds":["viral-gastroenteritis"],"origin":"ai"}],"hepatitis-a-e-acute":[{"id":"hepatitis-a-e-acute~ai-0","moduleId":"hepatitis-a-e-acute","stem":"What is the primary mode of transmission for Hepatitis A?","options":[{"id":"a","text":"Blood transfusion"},{"id":"b","text":"Sexual contact"},{"id":"c","text":"Faecal-oral route"},{"id":"d","text":"Vertical transmission"}],"answerId":"c","explanation":"Hepatitis A is primarily transmitted through the faecal-oral route, often via contaminated food or water.","kind":"recall","origin":"ai"},{"id":"hepatitis-a-e-acute~ai-1","moduleId":"hepatitis-a-e-acute","stem":"Which of the following is a key characteristic of Hepatitis E in pregnant women?","options":[{"id":"a","text":"Low mortality rate"},{"id":"b","text":"Chronic infection"},{"id":"c","text":"Fulminant hepatitis"},{"id":"d","text":"Asymptomatic presentation"}],"answerId":"c","explanation":"Hepatitis E can cause fulminant hepatitis in pregnant women, leading to high mortality.","kind":"recall","origin":"ai"},{"id":"hepatitis-a-e-acute~ai-2","moduleId":"hepatitis-a-e-acute","stem":"What serological marker indicates acute Hepatitis A infection?","options":[{"id":"a","text":"Anti-HAV IgG"},{"id":"b","text":"Anti-HAV IgM"},{"id":"c","text":"Anti-HEV IgG"},{"id":"d","text":"Anti-HEV IgM"}],"answerId":"b","explanation":"The presence of anti-HAV IgM indicates an acute infection with Hepatitis A.","kind":"recall","origin":"ai"},{"id":"hepatitis-a-e-acute~ai-3","moduleId":"hepatitis-a-e-acute","stem":"Which statement about Hepatitis A and E is true?","options":[{"id":"a","text":"They can cause chronic liver disease"},{"id":"b","text":"They are transmitted via blood"},{"id":"c","text":"They are self-limited infections"},{"id":"d","text":"They always present with jaundice"}],"answerId":"c","explanation":"Hepatitis A and E are both self-limited infections that do not typically cause chronic liver disease.","kind":"trap","origin":"ai"},{"id":"hepatitis-a-e-acute~ai-4","moduleId":"hepatitis-a-e-acute","stem":"In which patient population is Hepatitis E most likely to cause chronic infection?","options":[{"id":"a","text":"Healthy adults"},{"id":"b","text":"Children"},{"id":"c","text":"Pregnant women"},{"id":"d","text":"Immunocompromised patients"}],"answerId":"d","explanation":"Hepatitis E can lead to chronic infection in immunocompromised patients, which is an exception to its usual self-limited nature.","kind":"recall","origin":"ai"},{"id":"hepatitis-a-e-acute~ai-5","moduleId":"hepatitis-a-e-acute","stem":"A traveler presents with jaundice and fever after eating shellfish. Which hepatitis virus is most likely responsible?","options":[{"id":"a","text":"Hepatitis A"},{"id":"b","text":"Hepatitis B"},{"id":"c","text":"Hepatitis C"},{"id":"d","text":"Hepatitis E"}],"answerId":"a","explanation":"Hepatitis A is commonly associated with consumption of contaminated shellfish and presents with acute symptoms.","kind":"clinical","origin":"ai"},{"id":"hepatitis-a-e-acute~ai-6","moduleId":"hepatitis-a-e-acute","stem":"How does the acute nature of Hepatitis A and E compare to Hepatitis B and C?","options":[{"id":"a","text":"All can cause chronic infections"},{"id":"b","text":"A and E are acute, B and C can become chronic"},{"id":"c","text":"A and E are chronic, B and C are acute"},{"id":"d","text":"All are self-limited"}],"answerId":"b","explanation":"Hepatitis A and E are acute and self-limited, while Hepatitis B and C can lead to chronic infections.","kind":"integration","linkedModuleIds":["hepatitis-b-c-d-chronic"],"origin":"ai"},{"id":"hepatitis-a-e-acute~ai-7","moduleId":"hepatitis-a-e-acute","stem":"What is the primary prevention strategy for Hepatitis A?","options":[{"id":"a","text":"Vaccination"},{"id":"b","text":"Antiviral therapy"},{"id":"c","text":"Liver transplant"},{"id":"d","text":"Regular screening"}],"answerId":"a","explanation":"Vaccination is the primary prevention strategy for Hepatitis A, alongside sanitation and safe food practices.","kind":"integration","linkedModuleIds":["viral-hepatitis-prevention-immunization"],"origin":"ai"}],"food-poisoning-post-infectious":[{"id":"food-poisoning-post-infectious~ai-0","moduleId":"food-poisoning-post-infectious","stem":"Which organism is most likely responsible for vomiting within 1-6 hours after eating dairy products?","options":[{"id":"a","text":"Clostridium perfringens"},{"id":"b","text":"Bacillus cereus"},{"id":"c","text":"Staphylococcus aureus"},{"id":"d","text":"Salmonella"}],"answerId":"c","explanation":"Staphylococcus aureus produces a preformed toxin that causes rapid vomiting within hours of ingestion.","kind":"recall","origin":"ai"},{"id":"food-poisoning-post-infectious~ai-1","moduleId":"food-poisoning-post-infectious","stem":"What is the primary mechanism of illness in Clostridium perfringens food poisoning?","options":[{"id":"a","text":"Preformed toxin"},{"id":"b","text":"In-vivo toxin"},{"id":"c","text":"Invasive infection"},{"id":"d","text":"Allergic reaction"}],"answerId":"b","explanation":"Clostridium perfringens causes illness through an in-vivo toxin that acts approximately 8-16 hours after ingestion.","kind":"mechanism","origin":"ai"},{"id":"food-poisoning-post-infectious~ai-2","moduleId":"food-poisoning-post-infectious","stem":"A patient presents with persistent diarrhea after returning from a trip abroad. Which organism should be suspected?","options":[{"id":"a","text":"Salmonella"},{"id":"b","text":"Enteroaggregative E. coli"},{"id":"c","text":"Clostridium difficile"},{"id":"d","text":"Bacillus cereus"}],"answerId":"b","explanation":"Enteroaggregative E. coli (EAEC) is known to cause persistent diarrhea, especially in travelers.","kind":"clinical","origin":"ai"},{"id":"food-poisoning-post-infectious~ai-3","moduleId":"food-poisoning-post-infectious","stem":"Which of the following is a post-infectious sequelae of Campylobacter infection?","options":[{"id":"a","text":"Reactive arthritis"},{"id":"b","text":"Guillain–Barré syndrome"},{"id":"c","text":"Irritable bowel syndrome"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"All listed conditions can occur as post-infectious sequelae following a Campylobacter infection.","kind":"integration","linkedModuleIds":["inflammatory-invasive-enteritis"],"origin":"ai"},{"id":"food-poisoning-post-infectious~ai-4","moduleId":"food-poisoning-post-infectious","stem":"What is the most common cause of relapsing colitis after antibiotic treatment?","options":[{"id":"a","text":"Enteroaggregative E. coli"},{"id":"b","text":"Clostridium difficile"},{"id":"c","text":"Bacillus cereus"},{"id":"d","text":"Salmonella"}],"answerId":"b","explanation":"Clostridium difficile is the primary cause of relapsing colitis, particularly after antibiotic use.","kind":"recall","origin":"ai"},{"id":"food-poisoning-post-infectious~ai-5","moduleId":"food-poisoning-post-infectious","stem":"Which statement correctly describes the use of incubation time in diagnosing food poisoning?","options":[{"id":"a","text":"The specific food eaten is the best clue"},{"id":"b","text":"Incubation time is irrelevant"},{"id":"c","text":"Short incubation indicates preformed toxins"},{"id":"d","text":"Long incubation indicates preformed toxins"}],"answerId":"c","explanation":"Short incubation times (1-6 hours) indicate preformed toxins, which is crucial for accurate diagnosis.","kind":"trap","origin":"ai"},{"id":"food-poisoning-post-infectious~ai-6","moduleId":"food-poisoning-post-infectious","stem":"A patient develops ascending paralysis weeks after a diarrheal illness. Which condition is most likely?","options":[{"id":"a","text":"Guillain–Barré syndrome"},{"id":"b","text":"Irritable bowel syndrome"},{"id":"c","text":"C. difficile infection"},{"id":"d","text":"Reactive arthritis"}],"answerId":"a","explanation":"Ascending paralysis following a diarrheal illness is characteristic of Guillain–Barré syndrome, often triggered by Campylobacter infection.","kind":"clinical","origin":"ai"},{"id":"food-poisoning-post-infectious~ai-7","moduleId":"food-poisoning-post-infectious","stem":"Which of the following is a key feature of secretory (toxigenic) bacterial diarrhea?","options":[{"id":"a","text":"Bloody stools"},{"id":"b","text":"High fever"},{"id":"c","text":"Watery diarrhea"},{"id":"d","text":"Severe abdominal pain"}],"answerId":"c","explanation":"Secretory bacterial diarrhea is characterized by watery diarrhea, often without blood or high fever.","kind":"integration","linkedModuleIds":["secretory-toxigenic-enteritis"],"origin":"ai"}],"gut-hormones-appetite-regulation":[{"id":"gut-hormones-appetite-regulation~ai-0","moduleId":"gut-hormones-appetite-regulation","stem":"Which hormone is primarily responsible for stimulating hunger before meals?","options":[{"id":"a","text":"Ghrelin"},{"id":"b","text":"GLP-1"},{"id":"c","text":"Insulin"},{"id":"d","text":"Leptin"}],"answerId":"a","explanation":"Ghrelin is the main orexigenic hormone released from the stomach that signals hunger.","kind":"recall","origin":"ai"},{"id":"gut-hormones-appetite-regulation~ai-1","moduleId":"gut-hormones-appetite-regulation","stem":"What is the primary action of Cholecystokinin (CCK)?","options":[{"id":"a","text":"Stimulates gastric acid secretion"},{"id":"b","text":"Triggers gallbladder contraction"},{"id":"c","text":"Increases insulin sensitivity"},{"id":"d","text":"Promotes gastric emptying"}],"answerId":"b","explanation":"CCK is released in response to fat and protein, triggering gallbladder contraction and pancreatic enzyme release.","kind":"mechanism","origin":"ai"},{"id":"gut-hormones-appetite-regulation~ai-2","moduleId":"gut-hormones-appetite-regulation","stem":"Which gut hormone is involved in the incretin effect?","options":[{"id":"a","text":"Ghrelin"},{"id":"b","text":"Gastrin"},{"id":"c","text":"GLP-1"},{"id":"d","text":"PYY"}],"answerId":"c","explanation":"GLP-1 is one of the incretins that enhances insulin secretion after oral glucose intake.","kind":"recall","origin":"ai"},{"id":"gut-hormones-appetite-regulation~ai-3","moduleId":"gut-hormones-appetite-regulation","stem":"A patient presents with increased gastric acid secretion. Which hormone is likely elevated?","options":[{"id":"a","text":"Ghrelin"},{"id":"b","text":"CCK"},{"id":"c","text":"Gastrin"},{"id":"d","text":"GLP-1"}],"answerId":"c","explanation":"Gastrin, released from G cells, stimulates gastric acid secretion.","kind":"recall","origin":"ai"},{"id":"gut-hormones-appetite-regulation~ai-4","moduleId":"gut-hormones-appetite-regulation","stem":"What effect does a GLP-1 analogue have on gastric emptying?","options":[{"id":"a","text":"Increases gastric emptying"},{"id":"b","text":"No effect"},{"id":"c","text":"Slows gastric emptying"},{"id":"d","text":"Stimulates gastric acid secretion"}],"answerId":"c","explanation":"GLP-1 analogues slow gastric emptying and promote satiety.","kind":"mechanism","origin":"ai"},{"id":"gut-hormones-appetite-regulation~ai-5","moduleId":"gut-hormones-appetite-regulation","stem":"Which of the following hormones signals satiety after a meal?","options":[{"id":"a","text":"Ghrelin"},{"id":"b","text":"Insulin"},{"id":"c","text":"Gastrin"},{"id":"d","text":"CCK"}],"answerId":"d","explanation":"CCK is released after eating and signals satiety, along with other hormones like GLP-1 and PYY.","kind":"trap","origin":"ai"},{"id":"gut-hormones-appetite-regulation~ai-6","moduleId":"gut-hormones-appetite-regulation","stem":"How does bariatric surgery affect gut hormone levels?","options":[{"id":"a","text":"Increases ghrelin"},{"id":"b","text":"Decreases GLP-1"},{"id":"c","text":"Increases PYY"},{"id":"d","text":"Decreases insulin"}],"answerId":"c","explanation":"Bariatric surgery increases satiety hormones like PYY and GLP-1 while decreasing ghrelin levels.","kind":"integration","linkedModuleIds":["obesity-management-bariatric-surgery"],"origin":"ai"},{"id":"gut-hormones-appetite-regulation~ai-7","moduleId":"gut-hormones-appetite-regulation","stem":"What is the role of incretins in diabetes management?","options":[{"id":"a","text":"Increase glucagon secretion"},{"id":"b","text":"Enhance insulin secretion"},{"id":"c","text":"Decrease appetite"},{"id":"d","text":"Stimulate gastric acid production"}],"answerId":"b","explanation":"Incretins like GLP-1 enhance insulin secretion in response to meals, which is crucial for managing diabetes.","kind":"integration","linkedModuleIds":["obesity-pharmacotherapy"],"origin":"ai"}],"aphasmid-nematodes":[{"id":"aphasmid-nematodes~ai-0","moduleId":"aphasmid-nematodes","stem":"What is the primary mode of transmission for Trichuris trichiura?","options":[{"id":"a","text":"Ingestion of undercooked pork"},{"id":"b","text":"Ingestion of eggs from contaminated soil"},{"id":"c","text":"Direct skin penetration"},{"id":"d","text":"Inhalation of eggs"}],"answerId":"b","explanation":"Trichuris trichiura is acquired by ingesting eggs from faecally contaminated soil.","kind":"recall","origin":"ai"},{"id":"aphasmid-nematodes~ai-1","moduleId":"aphasmid-nematodes","stem":"Which clinical finding is most characteristic of a heavy Trichuris trichiura infection in children?","options":[{"id":"a","text":"Eosinophilia"},{"id":"b","text":"Rectal prolapse"},{"id":"c","text":"Myalgia"},{"id":"d","text":"Periorbital edema"}],"answerId":"b","explanation":"Rectal prolapse is a distinctive finding associated with heavy infections of Trichuris trichiura in children.","kind":"recall","origin":"ai"},{"id":"aphasmid-nematodes~ai-2","moduleId":"aphasmid-nematodes","stem":"What is the mechanism of disease for Trichinella spiralis?","options":[{"id":"a","text":"Intestinal obstruction"},{"id":"b","text":"Muscle encystment"},{"id":"c","text":"Liver damage"},{"id":"d","text":"Nutritional deficiency"}],"answerId":"b","explanation":"Trichinella spiralis larvae migrate to and encyst in striated muscle, causing myalgia and other symptoms.","kind":"mechanism","origin":"ai"},{"id":"aphasmid-nematodes~ai-3","moduleId":"aphasmid-nematodes","stem":"Which of the following is a common complication of Capillaria philippinensis infection?","options":[{"id":"a","text":"Acute appendicitis"},{"id":"b","text":"Protein-losing enteropathy"},{"id":"c","text":"Chronic constipation"},{"id":"d","text":"Hemolytic anemia"}],"answerId":"b","explanation":"Capillaria philippinensis can lead to severe malabsorption and protein-losing enteropathy.","kind":"recall","origin":"ai"},{"id":"aphasmid-nematodes~ai-4","moduleId":"aphasmid-nematodes","stem":"A patient presents with fever, periorbital edema, myalgia, and eosinophilia after eating undercooked pork. What is the most likely diagnosis?","options":[{"id":"a","text":"Capillaria infection"},{"id":"b","text":"Trichuris infection"},{"id":"c","text":"Trichinellosis"},{"id":"d","text":"Ascaris infection"}],"answerId":"c","explanation":"These symptoms are classic for Trichinellosis caused by Trichinella spiralis.","kind":"clinical","origin":"ai"},{"id":"aphasmid-nematodes~ai-5","moduleId":"aphasmid-nematodes","stem":"Which of the following statements about Trichinella spiralis is true?","options":[{"id":"a","text":"It is transmitted through contaminated soil."},{"id":"b","text":"It causes rectal prolapse."},{"id":"c","text":"It is acquired by eating undercooked pork."},{"id":"d","text":"It primarily affects the liver."}],"answerId":"c","explanation":"Trichinella spiralis is acquired by eating undercooked pork containing encysted larvae.","kind":"trap","origin":"ai"},{"id":"aphasmid-nematodes~ai-6","moduleId":"aphasmid-nematodes","stem":"How does malabsorption from Capillaria philippinensis relate to protein-energy malnutrition?","options":[{"id":"a","text":"It causes increased appetite."},{"id":"b","text":"It leads to protein-losing enteropathy."},{"id":"c","text":"It is a result of vitamin deficiency."},{"id":"d","text":"It is unrelated to nutritional status."}],"answerId":"b","explanation":"Capillaria philippinensis infection can lead to protein-losing enteropathy, contributing to protein-energy malnutrition.","kind":"integration","linkedModuleIds":["nutrition-energy-protein-malnutrition"],"origin":"ai"},{"id":"aphasmid-nematodes~ai-7","moduleId":"aphasmid-nematodes","stem":"What is a key difference between Trichuris trichiura and soil-transmitted nematodes like Ascaris?","options":[{"id":"a","text":"Trichuris is not transmitted through soil."},{"id":"b","text":"Trichuris causes rectal prolapse, while Ascaris does not."},{"id":"c","text":"Trichuris is only found in Southeast Asia."},{"id":"d","text":"Ascaris causes eosinophilia, while Trichuris does not."}],"answerId":"b","explanation":"Trichuris trichiura is characterized by rectal prolapse in children, which is not a feature of Ascaris infection.","kind":"integration","linkedModuleIds":["intestinal-roundworms-phasmid"],"origin":"ai"}],"viral-gastroenteritis":[{"id":"viral-gastroenteritis~ai-0","moduleId":"viral-gastroenteritis","stem":"What is the primary mechanism by which rotavirus causes diarrhea?","options":[{"id":"a","text":"Destruction of gastric mucosa"},{"id":"b","text":"Inhibition of intestinal motility"},{"id":"c","text":"Villous enterocyte damage"},{"id":"d","text":"Increased intestinal permeability"}],"answerId":"c","explanation":"Rotavirus causes diarrhea primarily through villous enterocyte damage, leading to malabsorption and watery diarrhea.","kind":"mechanism","origin":"ai"},{"id":"viral-gastroenteritis~ai-1","moduleId":"viral-gastroenteritis","stem":"Which of the following is a key clinical finding in viral gastroenteritis?","options":[{"id":"a","text":"Bloody diarrhea"},{"id":"b","text":"Fever above 39°C"},{"id":"c","text":"Watery diarrhea without blood"},{"id":"d","text":"Presence of fecal leukocytes"}],"answerId":"c","explanation":"Viral gastroenteritis is characterized by watery diarrhea without blood or fecal leukocytes.","kind":"recall","origin":"ai"},{"id":"viral-gastroenteritis~ai-2","moduleId":"viral-gastroenteritis","stem":"What is the most effective management strategy for a child with rotavirus gastroenteritis?","options":[{"id":"a","text":"Antibiotics"},{"id":"b","text":"Intravenous fluids"},{"id":"c","text":"Oral rehydration solution"},{"id":"d","text":"Probiotics"}],"answerId":"c","explanation":"The primary management for rotavirus gastroenteritis is rehydration, typically with oral rehydration solutions.","kind":"clinical","origin":"ai"},{"id":"viral-gastroenteritis~ai-3","moduleId":"viral-gastroenteritis","stem":"Which of the following statements about norovirus is true?","options":[{"id":"a","text":"It is primarily transmitted through contaminated water."},{"id":"b","text":"It causes severe bloody diarrhea."},{"id":"c","text":"It is highly contagious with a low infectious dose."},{"id":"d","text":"It is more common in infants than adults."}],"answerId":"c","explanation":"Norovirus is known for its high contagion and low infectious dose, making it a common cause of outbreaks.","kind":"recall","origin":"ai"},{"id":"viral-gastroenteritis~ai-4","moduleId":"viral-gastroenteritis","stem":"What is a common misconception regarding the treatment of viral gastroenteritis?","options":[{"id":"a","text":"Rehydration is the primary treatment."},{"id":"b","text":"Antibiotics are effective against viral infections."},{"id":"c","text":"Symptoms are self-limiting."},{"id":"d","text":"Vaccination can prevent rotavirus infections."}],"answerId":"b","explanation":"A common misconception is that antibiotics are effective against viral gastroenteritis, but they are ineffective and unnecessary.","kind":"trap","origin":"ai"},{"id":"viral-gastroenteritis~ai-5","moduleId":"viral-gastroenteritis","stem":"A child presents with sudden onset watery diarrhea and vomiting during a winter outbreak. What is the most likely diagnosis?","options":[{"id":"a","text":"Bacterial gastroenteritis"},{"id":"b","text":"Norovirus infection"},{"id":"c","text":"Rotavirus infection"},{"id":"d","text":"Parasitic infection"}],"answerId":"c","explanation":"The presentation is consistent with rotavirus infection, especially in young children during the winter months.","kind":"clinical","origin":"ai"},{"id":"viral-gastroenteritis~ai-6","moduleId":"viral-gastroenteritis","stem":"How does the management of viral gastroenteritis differ from that of inflammatory bacterial diarrhea?","options":[{"id":"a","text":"Both require antibiotics."},{"id":"b","text":"Viral gastroenteritis requires rehydration, while bacterial diarrhea requires antibiotics."},{"id":"c","text":"Both require rehydration."},{"id":"d","text":"Inflammatory diarrhea is treated with probiotics."}],"answerId":"b","explanation":"Viral gastroenteritis is managed with rehydration, while inflammatory bacterial diarrhea often requires antibiotics.","kind":"integration","linkedModuleIds":["inflammatory-invasive-enteritis"],"origin":"ai"},{"id":"viral-gastroenteritis~ai-7","moduleId":"viral-gastroenteritis","stem":"Which of the following preventive measures is specifically effective against rotavirus?","options":[{"id":"a","text":"Handwashing"},{"id":"b","text":"Oral rehydration therapy"},{"id":"c","text":"Vaccination"},{"id":"d","text":"Antibiotic prophylaxis"}],"answerId":"c","explanation":"Vaccination is a specific preventive measure against rotavirus infections, significantly reducing incidence.","kind":"integration","linkedModuleIds":["laxatives-antidiarrheals-ors"],"origin":"ai"}],"viral-hepatitis-prevention-immunization":[{"id":"viral-hepatitis-prevention-immunization~ai-0","moduleId":"viral-hepatitis-prevention-immunization","stem":"What is the primary prevention method for hepatitis A?","options":[{"id":"a","text":"Vaccination"},{"id":"b","text":"Blood safety measures"},{"id":"c","text":"Sanitation and food hygiene"},{"id":"d","text":"Screening of blood donors"}],"answerId":"c","explanation":"Hepatitis A is primarily prevented through sanitation and food hygiene, as it is transmitted via the faecal-oral route.","kind":"recall","origin":"ai"},{"id":"viral-hepatitis-prevention-immunization~ai-1","moduleId":"viral-hepatitis-prevention-immunization","stem":"Which of the following indicates successful vaccination against hepatitis B?","options":[{"id":"a","text":"Anti-HBc positive with anti-HBs negative"},{"id":"b","text":"Anti-HBs positive with anti-HBc negative"},{"id":"c","text":"HBsAg positive"},{"id":"d","text":"Anti-HBs negative with anti-HBc positive"}],"answerId":"b","explanation":"Successful hepatitis B vaccination is indicated by the presence of anti-HBs and absence of anti-HBc.","kind":"recall","origin":"ai"},{"id":"viral-hepatitis-prevention-immunization~ai-2","moduleId":"viral-hepatitis-prevention-immunization","stem":"What is the mechanism by which hepatitis B vaccination prevents hepatitis D?","options":[{"id":"a","text":"Directly inhibits HDV replication"},{"id":"b","text":"Prevents HBV infection, which is required for HDV"},{"id":"c","text":"Stimulates immune response against HDV"},{"id":"d","text":"Provides antibodies against HDV"}],"answerId":"b","explanation":"Hepatitis D virus requires hepatitis B virus for replication; thus, preventing HBV infection also prevents HDV.","kind":"mechanism","origin":"ai"},{"id":"viral-hepatitis-prevention-immunization~ai-3","moduleId":"viral-hepatitis-prevention-immunization","stem":"What is the recommended post-exposure prophylaxis for a newborn of an HBsAg-positive mother?","options":[{"id":"a","text":"Only hepatitis B vaccine"},{"id":"b","text":"Only HBIG"},{"id":"c","text":"HBIG plus hepatitis B vaccine"},{"id":"d","text":"No intervention needed"}],"answerId":"c","explanation":"Newborns of HBsAg-positive mothers should receive both HBIG and the hepatitis B vaccine for effective post-exposure prophylaxis.","kind":"clinical","origin":"ai"},{"id":"viral-hepatitis-prevention-immunization~ai-4","moduleId":"viral-hepatitis-prevention-immunization","stem":"Which of the following statements about hepatitis D is true?","options":[{"id":"a","text":"It has a separate vaccine available"},{"id":"b","text":"It can replicate independently of HBV"},{"id":"c","text":"It requires HBsAg for replication"},{"id":"d","text":"It is transmitted via the faecal-oral route"}],"answerId":"c","explanation":"Hepatitis D requires HBsAg to replicate, which is why the hepatitis B vaccine also prevents hepatitis D.","kind":"trap","origin":"ai"},{"id":"viral-hepatitis-prevention-immunization~ai-5","moduleId":"viral-hepatitis-prevention-immunization","stem":"What is the primary prevention strategy for hepatitis C?","options":[{"id":"a","text":"Vaccination"},{"id":"b","text":"Sanitation"},{"id":"c","text":"Blood safety and harm reduction"},{"id":"d","text":"Screening of pregnant women"}],"answerId":"c","explanation":"There is no vaccine for hepatitis C; prevention relies on blood safety measures and harm reduction strategies.","kind":"recall","origin":"ai"},{"id":"viral-hepatitis-prevention-immunization~ai-6","moduleId":"viral-hepatitis-prevention-immunization","stem":"How does the hepatitis B vaccination relate to the prevention of hepatocellular carcinoma?","options":[{"id":"a","text":"It directly treats liver tumors"},{"id":"b","text":"It prevents HBV infection, reducing HCC risk"},{"id":"c","text":"It provides immunity against liver cancer"},{"id":"d","text":"It is unrelated to liver cancer prevention"}],"answerId":"b","explanation":"Vaccination against hepatitis B reduces the risk of chronic HBV infection, which is a major risk factor for hepatocellular carcinoma.","kind":"integration","linkedModuleIds":["hepatocellular-carcinoma-liver-tumors"],"origin":"ai"},{"id":"viral-hepatitis-prevention-immunization~ai-7","moduleId":"viral-hepatitis-prevention-immunization","stem":"What is the relationship between hepatitis A vaccination and travel?","options":[{"id":"a","text":"It is not recommended for travelers"},{"id":"b","text":"It is advised for travelers to endemic areas"},{"id":"c","text":"It is required for all international travel"},{"id":"d","text":"It has no relation to travel"}],"answerId":"b","explanation":"Hepatitis A vaccination is recommended for travelers to areas where the virus is endemic to prevent infection.","kind":"integration","linkedModuleIds":["hepatitis-a-e-acute"],"origin":"ai"}],"intestinal-roundworms-phasmid":[{"id":"intestinal-roundworms-phasmid~ai-0","moduleId":"intestinal-roundworms-phasmid","stem":"What is the primary mode of transmission for Ascaris lumbricoides?","options":[{"id":"a","text":"Ingestion of contaminated food or water"},{"id":"b","text":"Skin penetration"},{"id":"c","text":"Inhalation of larvae"},{"id":"d","text":"Vector-borne transmission"}],"answerId":"a","explanation":"Ascaris lumbricoides is transmitted through the ingestion of eggs present in contaminated food or water.","kind":"recall","origin":"ai"},{"id":"intestinal-roundworms-phasmid~ai-1","moduleId":"intestinal-roundworms-phasmid","stem":"Which clinical finding is most characteristic of hookworm infection?","options":[{"id":"a","text":"Perianal itching"},{"id":"b","text":"Eosinophilia with cough"},{"id":"c","text":"Chronic iron-deficiency anemia"},{"id":"d","text":"Intestinal obstruction"}],"answerId":"c","explanation":"Chronic iron-deficiency anemia is a hallmark of hookworm infection due to blood loss in the intestines.","kind":"recall","origin":"ai"},{"id":"intestinal-roundworms-phasmid~ai-2","moduleId":"intestinal-roundworms-phasmid","stem":"What is the mechanism of hyperinfection in Strongyloides stercoralis?","options":[{"id":"a","text":"Autoinfection leading to increased larval load"},{"id":"b","text":"Direct skin penetration"},{"id":"c","text":"Ingestion of contaminated food"},{"id":"d","text":"Migration through the bloodstream"}],"answerId":"a","explanation":"Strongyloides stercoralis can autoinfect, leading to a persistent and increased larval load, especially in immunocompromised individuals.","kind":"mechanism","origin":"ai"},{"id":"intestinal-roundworms-phasmid~ai-3","moduleId":"intestinal-roundworms-phasmid","stem":"A child presents with nocturnal perianal itching. What is the most appropriate diagnostic test?","options":[{"id":"a","text":"Stool microscopy"},{"id":"b","text":"Blood test for eosinophilia"},{"id":"c","text":"Scotch-tape test"},{"id":"d","text":"Serological test for parasites"}],"answerId":"c","explanation":"The Scotch-tape test is used to detect Enterobius vermicularis eggs on the perianal skin, as the eggs are not typically found in stool.","kind":"trap","origin":"ai"},{"id":"intestinal-roundworms-phasmid~ai-4","moduleId":"intestinal-roundworms-phasmid","stem":"Which of the following findings is associated with a heavy infection of Ascaris lumbricoides?","options":[{"id":"a","text":"Eosinophilia"},{"id":"b","text":"Intestinal obstruction"},{"id":"c","text":"Perianal itching"},{"id":"d","text":"Chronic cough"}],"answerId":"b","explanation":"Heavy infections of Ascaris lumbricoides can lead to intestinal or biliary obstruction due to a bolus of worms.","kind":"recall","origin":"ai"},{"id":"intestinal-roundworms-phasmid~ai-5","moduleId":"intestinal-roundworms-phasmid","stem":"How does the treatment of Strongyloides stercoralis differ from other soil-transmitted nematodes?","options":[{"id":"a","text":"Requires surgery"},{"id":"b","text":"Uses ivermectin instead of benzimidazoles"},{"id":"c","text":"Is ineffective in immunosuppressed patients"},{"id":"d","text":"Involves prolonged antibiotic therapy"}],"answerId":"b","explanation":"Strongyloides stercoralis is treated with ivermectin, while other soil-transmitted nematodes are typically treated with benzimidazoles.","kind":"mechanism","origin":"ai"},{"id":"intestinal-roundworms-phasmid~ai-6","moduleId":"intestinal-roundworms-phasmid","stem":"How do the clinical features of Enterobius vermicularis compare to those of Trichuris trichiura?","options":[{"id":"a","text":"Both cause eosinophilia"},{"id":"b","text":"Enterobius causes perianal itching, Trichuris causes diarrhea"},{"id":"c","text":"Both cause intestinal obstruction"},{"id":"d","text":"Enterobius is diagnosed by stool microscopy"}],"answerId":"b","explanation":"Enterobius vermicularis causes perianal itching, while Trichuris trichiura is associated with diarrhea; they have different clinical presentations.","kind":"integration","linkedModuleIds":["aphasmid-nematodes"],"origin":"ai"},{"id":"intestinal-roundworms-phasmid~ai-7","moduleId":"intestinal-roundworms-phasmid","stem":"What is a common feature of both Ascaris lumbricoides and hookworms in terms of their life cycle?","options":[{"id":"a","text":"Both require skin penetration"},{"id":"b","text":"Both have a lung migration phase"},{"id":"c","text":"Both cause perianal itching"},{"id":"d","text":"Both are diagnosed by stool microscopy"}],"answerId":"b","explanation":"Both Ascaris lumbricoides and hookworms have a lung migration phase before maturing in the intestines.","kind":"integration","linkedModuleIds":["ascariasis-large-roundworm"],"origin":"ai"}],"inflammatory-invasive-enteritis":[{"id":"inflammatory-invasive-enteritis~ai-0","moduleId":"inflammatory-invasive-enteritis","stem":"Which organism is most commonly associated with bloody diarrhoea and post-infectious Guillain–Barré syndrome?","options":[{"id":"a","text":"Shigella"},{"id":"b","text":"Salmonella"},{"id":"c","text":"Campylobacter jejuni"},{"id":"d","text":"Clostridioides difficile"}],"answerId":"c","explanation":"Campylobacter jejuni is known for causing bloody diarrhoea and is associated with post-infectious sequelae such as Guillain–Barré syndrome.","kind":"recall","origin":"ai"},{"id":"inflammatory-invasive-enteritis~ai-1","moduleId":"inflammatory-invasive-enteritis","stem":"What is the primary mechanism by which enterohaemorrhagic E. coli (EHEC) causes bloody diarrhoea?","options":[{"id":"a","text":"Mucosal invasion"},{"id":"b","text":"Shiga-like toxin production"},{"id":"c","text":"Increased intestinal motility"},{"id":"d","text":"Antibiotic resistance"}],"answerId":"b","explanation":"EHEC primarily causes bloody diarrhoea through the production of Shiga-like toxin, which damages the intestinal lining.","kind":"mechanism","origin":"ai"},{"id":"inflammatory-invasive-enteritis~ai-2","moduleId":"inflammatory-invasive-enteritis","stem":"A patient presents with bloody diarrhoea after consuming undercooked beef. What is the most appropriate management?","options":[{"id":"a","text":"Start antibiotics immediately"},{"id":"b","text":"Administer antimotility agents"},{"id":"c","text":"Provide supportive care"},{"id":"d","text":"Perform endoscopy"}],"answerId":"c","explanation":"In EHEC infections, antibiotics and antimotility agents are contraindicated; supportive care is the best approach.","kind":"clinical","origin":"ai"},{"id":"inflammatory-invasive-enteritis~ai-3","moduleId":"inflammatory-invasive-enteritis","stem":"Which of the following findings is characteristic of Clostridioides difficile infection?","options":[{"id":"a","text":"Bloody, mucoid diarrhoea"},{"id":"b","text":"Pseudomembranous colitis"},{"id":"c","text":"Guillain–Barré syndrome"},{"id":"d","text":"Rose spots"}],"answerId":"b","explanation":"Clostridioides difficile infection is characterized by pseudomembranous colitis, especially following antibiotic use.","kind":"recall","origin":"ai"},{"id":"inflammatory-invasive-enteritis~ai-4","moduleId":"inflammatory-invasive-enteritis","stem":"In the context of inflammatory (invasive) bacterial diarrhoea, which statement is true regarding the use of antibiotics?","options":[{"id":"a","text":"Antibiotics are always beneficial"},{"id":"b","text":"They are contraindicated in EHEC infections"},{"id":"c","text":"They should be used in all cases of dysentery"},{"id":"d","text":"They are effective against all bacterial causes"}],"answerId":"b","explanation":"Antibiotics are contraindicated in EHEC infections because they can increase the risk of hemolytic-uremic syndrome.","kind":"trap","origin":"ai"},{"id":"inflammatory-invasive-enteritis~ai-5","moduleId":"inflammatory-invasive-enteritis","stem":"A patient with enteric fever presents with relative bradycardia and rose spots. Which organism is most likely responsible?","options":[{"id":"a","text":"Shigella"},{"id":"b","text":"Salmonella Typhi"},{"id":"c","text":"Campylobacter jejuni"},{"id":"d","text":"Clostridioides difficile"}],"answerId":"b","explanation":"Salmonella Typhi is the causative agent of enteric fever, characterized by relative bradycardia and rose spots.","kind":"recall","origin":"ai"},{"id":"inflammatory-invasive-enteritis~ai-6","moduleId":"inflammatory-invasive-enteritis","stem":"How does the management of EHEC differ from that of other bacterial diarrhoea?","options":[{"id":"a","text":"EHEC requires immediate surgical intervention"},{"id":"b","text":"EHEC management avoids antibiotics"},{"id":"c","text":"EHEC is treated with broad-spectrum antibiotics"},{"id":"d","text":"EHEC requires hydration only"}],"answerId":"b","explanation":"EHEC management specifically avoids antibiotics to reduce the risk of complications like hemolytic-uremic syndrome.","kind":"integration","linkedModuleIds":["laxatives-antidiarrheals-ors"],"origin":"ai"},{"id":"inflammatory-invasive-enteritis~ai-7","moduleId":"inflammatory-invasive-enteritis","stem":"Which of the following is a potential post-infectious complication of Campylobacter jejuni infection?","options":[{"id":"a","text":"Pseudomembranous colitis"},{"id":"b","text":"Hemolytic-uremic syndrome"},{"id":"c","text":"Guillain–Barré syndrome"},{"id":"d","text":"Typhoid fever"}],"answerId":"c","explanation":"Guillain–Barré syndrome is a recognized post-infectious complication following Campylobacter jejuni infection.","kind":"integration","linkedModuleIds":["food-poisoning-post-infectious"],"origin":"ai"}],"hepatitis-b-c-d-chronic":[{"id":"hepatitis-b-c-d-chronic~ai-0","moduleId":"hepatitis-b-c-d-chronic","stem":"What is the primary mode of transmission for Hepatitis B virus (HBV)?","options":[{"id":"a","text":"Fecal-oral route"},{"id":"b","text":"Airborne droplets"},{"id":"c","text":"Blood and sexual contact"},{"id":"d","text":"Contaminated water"}],"answerId":"c","explanation":"Hepatitis B virus is primarily transmitted through blood and sexual contact.","kind":"recall","origin":"ai"},{"id":"hepatitis-b-c-d-chronic~ai-1","moduleId":"hepatitis-b-c-d-chronic","stem":"Which serological marker indicates active chronic Hepatitis B infection?","options":[{"id":"a","text":"Anti-HBs"},{"id":"b","text":"Anti-HBc IgM"},{"id":"c","text":"HBsAg"},{"id":"d","text":"HBeAg"}],"answerId":"c","explanation":"HBsAg positivity for more than 6 months indicates chronic Hepatitis B infection.","kind":"recall","origin":"ai"},{"id":"hepatitis-b-c-d-chronic~ai-2","moduleId":"hepatitis-b-c-d-chronic","stem":"How does Hepatitis C virus (HCV) primarily progress in infected individuals?","options":[{"id":"a","text":"Rapid acute liver failure"},{"id":"b","text":"Chronic infection leading to cirrhosis"},{"id":"c","text":"Immediate clearance"},{"id":"d","text":"Acute hepatitis followed by immunity"}],"answerId":"b","explanation":"HCV frequently progresses to chronic infection, which can lead to cirrhosis and hepatocellular carcinoma.","kind":"recall","origin":"ai"},{"id":"hepatitis-b-c-d-chronic~ai-3","moduleId":"hepatitis-b-c-d-chronic","stem":"A patient has positive anti-HBs and negative anti-HBc. What does this indicate?","options":[{"id":"a","text":"Acute Hepatitis B infection"},{"id":"b","text":"Chronic Hepatitis B infection"},{"id":"c","text":"Vaccine-induced immunity"},{"id":"d","text":"Natural immunity from past infection"}],"answerId":"c","explanation":"This serological profile indicates immunity due to vaccination, as there is no exposure to the core antigen.","kind":"trap","origin":"ai"},{"id":"hepatitis-b-c-d-chronic~ai-4","moduleId":"hepatitis-b-c-d-chronic","stem":"Which of the following statements about Hepatitis D virus (HDV) is correct?","options":[{"id":"a","text":"HDV can replicate independently"},{"id":"b","text":"HDV requires HBV for replication"},{"id":"c","text":"HDV is curable with direct-acting antivirals"},{"id":"d","text":"HDV is transmitted via fecal-oral route"}],"answerId":"b","explanation":"HDV is a defective virus that requires Hepatitis B virus (HBV) for its replication.","kind":"recall","origin":"ai"},{"id":"hepatitis-b-c-d-chronic~ai-5","moduleId":"hepatitis-b-c-d-chronic","stem":"Which of the following is a common complication of chronic Hepatitis B infection?","options":[{"id":"a","text":"Acute liver failure"},{"id":"b","text":"Hepatocellular carcinoma"},{"id":"c","text":"Hepatitis A superinfection"},{"id":"d","text":"Cholecystitis"}],"answerId":"b","explanation":"Chronic Hepatitis B infection can lead to hepatocellular carcinoma, even in the absence of cirrhosis.","kind":"recall","origin":"ai"},{"id":"hepatitis-b-c-d-chronic~ai-6","moduleId":"hepatitis-b-c-d-chronic","stem":"How does the chronicity risk of Hepatitis B infection change with age at infection?","options":[{"id":"a","text":"Increases with age"},{"id":"b","text":"Decreases with age"},{"id":"c","text":"Remains constant regardless of age"},{"id":"d","text":"Is unrelated to age"}],"answerId":"b","explanation":"The risk of chronic infection is inversely related to age, with nearly 90% of neonatal infections becoming chronic.","kind":"recall","origin":"ai"},{"id":"hepatitis-b-c-d-chronic~ai-7","moduleId":"hepatitis-b-c-d-chronic","stem":"A patient with chronic Hepatitis B is undergoing surveillance for hepatocellular carcinoma. Which linked module's knowledge is essential for understanding this complication?","options":[{"id":"a","text":"DNA Viruses II: Hepatitis B, HPV, Pox & Others"},{"id":"b","text":"Fatty Liver, Cirrhosis & Portal Hypertension"},{"id":"c","text":"Viral Hepatitis: Prevention & Immunisation"},{"id":"d","text":"Hepatitis A & E (Enterically Transmitted)"}],"answerId":"b","explanation":"Understanding the progression to cirrhosis and hepatocellular carcinoma is crucial, which is covered in the Fatty Liver, Cirrhosis & Portal Hypertension module.","kind":"integration","linkedModuleIds":["cirrhosis-fatty-liver-portal-hypertension"],"origin":"ai"},{"id":"hepatitis-b-c-d-chronic~ai-8","moduleId":"hepatitis-b-c-d-chronic","stem":"What is the primary prevention strategy for Hepatitis B and D infections?","options":[{"id":"a","text":"Vaccination against Hepatitis A"},{"id":"b","text":"Vaccination against Hepatitis B"},{"id":"c","text":"Antiviral therapy"},{"id":"d","text":"Screening for Hepatitis C"}],"answerId":"b","explanation":"Vaccination against Hepatitis B is the primary prevention strategy, as it also prevents Hepatitis D infection.","kind":"integration","linkedModuleIds":["viral-hepatitis-prevention-immunization"],"origin":"ai"}],"pharmacology-in-liver-disease":[{"id":"pharmacology-in-liver-disease~ai-0","moduleId":"pharmacology-in-liver-disease","stem":"What is the first-line treatment for ascites in a patient with cirrhosis?","options":[{"id":"a","text":"Furosemide"},{"id":"b","text":"Spironolactone"},{"id":"c","text":"Terlipressin"},{"id":"d","text":"Lactulose"}],"answerId":"b","explanation":"Spironolactone is the first-line diuretic for treating ascites due to its ability to counteract secondary hyperaldosteronism.","kind":"recall","origin":"ai"},{"id":"pharmacology-in-liver-disease~ai-1","moduleId":"pharmacology-in-liver-disease","stem":"Which medication is used to prevent variceal bleeding by reducing portal pressure?","options":[{"id":"a","text":"Propranolol"},{"id":"b","text":"Octreotide"},{"id":"c","text":"Rifaximin"},{"id":"d","text":"Ceftriaxone"}],"answerId":"a","explanation":"Non-selective beta-blockers like propranolol reduce portal pressure, thus preventing variceal bleeding.","kind":"recall","origin":"ai"},{"id":"pharmacology-in-liver-disease~ai-2","moduleId":"pharmacology-in-liver-disease","stem":"In acute variceal bleeding, which combination of treatments is appropriate?","options":[{"id":"a","text":"Spironolactone + Lactulose"},{"id":"b","text":"Terlipressin + Ceftriaxone + Band ligation"},{"id":"c","text":"Propranolol + Rifaximin"},{"id":"d","text":"Furosemide + Octreotide"}],"answerId":"b","explanation":"The correct treatment for acute variceal bleeding includes terlipressin for splanchnic vasoconstriction, ceftriaxone for SBP prophylaxis, and urgent band ligation.","kind":"clinical","origin":"ai"},{"id":"pharmacology-in-liver-disease~ai-3","moduleId":"pharmacology-in-liver-disease","stem":"What is the mechanism of action of lactulose in hepatic encephalopathy?","options":[{"id":"a","text":"Increases ammonia production"},{"id":"b","text":"Traps ammonia in the gut"},{"id":"c","text":"Inhibits gut bacteria"},{"id":"d","text":"Enhances liver function"}],"answerId":"b","explanation":"Lactulose traps ammonia in the gut as ammonium, facilitating its excretion and reducing hyperammonaemia.","kind":"mechanism","origin":"ai"},{"id":"pharmacology-in-liver-disease~ai-4","moduleId":"pharmacology-in-liver-disease","stem":"Why should benzodiazepines be avoided in patients with hepatic encephalopathy?","options":[{"id":"a","text":"They increase ammonia production"},{"id":"b","text":"They worsen CNS depression"},{"id":"c","text":"They are hepatotoxic"},{"id":"d","text":"They cause gastrointestinal bleeding"}],"answerId":"b","explanation":"Benzodiazepines can worsen CNS depression in hepatic encephalopathy due to impaired hepatic clearance, deepening the patient's coma.","kind":"trap","origin":"ai"},{"id":"pharmacology-in-liver-disease~ai-5","moduleId":"pharmacology-in-liver-disease","stem":"How does hypoalbuminaemia affect drug handling in patients with liver disease?","options":[{"id":"a","text":"Increases drug metabolism"},{"id":"b","text":"Decreases free drug levels"},{"id":"c","text":"Increases free drug levels"},{"id":"d","text":"Has no effect on drug handling"}],"answerId":"c","explanation":"Hypoalbuminaemia raises free drug levels because there is less albumin available to bind drugs, increasing the risk of toxicity.","kind":"mechanism","origin":"ai"},{"id":"pharmacology-in-liver-disease~ai-6","moduleId":"pharmacology-in-liver-disease","stem":"In managing cirrhosis, which complication is directly treated with rifaximin?","options":[{"id":"a","text":"Ascites"},{"id":"b","text":"Spontaneous bacterial peritonitis"},{"id":"c","text":"Hepatic encephalopathy"},{"id":"d","text":"Variceal bleeding"}],"answerId":"c","explanation":"Rifaximin is used to reduce ammonia-producing gut bacteria in the treatment of hepatic encephalopathy.","kind":"recall","origin":"ai"},{"id":"pharmacology-in-liver-disease~ai-7","moduleId":"pharmacology-in-liver-disease","stem":"How does the management of spontaneous bacterial peritonitis (SBP) relate to liver disease treatment?","options":[{"id":"a","text":"It is unrelated to liver function"},{"id":"b","text":"It requires liver transplantation"},{"id":"c","text":"It involves antibiotic prophylaxis after variceal bleeding"},{"id":"d","text":"It is treated with diuretics"}],"answerId":"c","explanation":"Antibiotic prophylaxis after variceal bleeding is crucial to prevent SBP in patients with liver disease.","kind":"integration","linkedModuleIds":["cirrhosis-fatty-liver-portal-hypertension"],"origin":"ai"},{"id":"pharmacology-in-liver-disease~ai-8","moduleId":"pharmacology-in-liver-disease","stem":"Which of the following best connects the management of ascites to the principles of liver function?","options":[{"id":"a","text":"Ascites is treated with antibiotics"},{"id":"b","text":"Diuretics are used to manage fluid retention due to liver failure"},{"id":"c","text":"Ascites management does not consider liver function"},{"id":"d","text":"Fluid restriction is the only treatment for ascites"}],"answerId":"b","explanation":"Diuretics like spironolactone are used to manage fluid retention in ascites, which is a direct consequence of liver failure and altered fluid balance.","kind":"integration","linkedModuleIds":["cirrhosis-fatty-liver-portal-hypertension"],"origin":"ai"}],"fat-soluble-vitamins":[{"id":"fat-soluble-vitamins~ai-0","moduleId":"fat-soluble-vitamins","stem":"What is the primary clinical manifestation of Vitamin A deficiency?","options":[{"id":"a","text":"Night blindness"},{"id":"b","text":"Rickets"},{"id":"c","text":"Bleeding diathesis"},{"id":"d","text":"Haemolytic anaemia"}],"answerId":"a","explanation":"Vitamin A deficiency primarily leads to night blindness, which can progress to more severe ocular conditions.","kind":"recall","origin":"ai"},{"id":"fat-soluble-vitamins~ai-1","moduleId":"fat-soluble-vitamins","stem":"Which vitamin is essential for the γ-carboxylation of clotting factors?","options":[{"id":"a","text":"Vitamin A"},{"id":"b","text":"Vitamin D"},{"id":"c","text":"Vitamin E"},{"id":"d","text":"Vitamin K"}],"answerId":"d","explanation":"Vitamin K is crucial for the γ-carboxylation of clotting factors II, VII, IX, and X.","kind":"recall","origin":"ai"},{"id":"fat-soluble-vitamins~ai-2","moduleId":"fat-soluble-vitamins","stem":"A patient presents with ataxia and peripheral neuropathy. Which vitamin deficiency is most likely?","options":[{"id":"a","text":"Vitamin A"},{"id":"b","text":"Vitamin D"},{"id":"c","text":"Vitamin E"},{"id":"d","text":"Vitamin K"}],"answerId":"c","explanation":"Vitamin E deficiency can cause ataxia and peripheral neuropathy due to its role as an antioxidant.","kind":"clinical","origin":"ai"},{"id":"fat-soluble-vitamins~ai-3","moduleId":"fat-soluble-vitamins","stem":"Which of the following conditions would most likely lead to deficiencies of all fat-soluble vitamins?","options":[{"id":"a","text":"Chronic pancreatitis"},{"id":"b","text":"Cirrhosis"},{"id":"c","text":"Hyperthyroidism"},{"id":"d","text":"Diabetes mellitus"}],"answerId":"a","explanation":"Chronic pancreatitis can impair fat absorption, leading to deficiencies in all fat-soluble vitamins (A, D, E, K).","kind":"trap","origin":"ai"},{"id":"fat-soluble-vitamins~ai-4","moduleId":"fat-soluble-vitamins","stem":"What is the mechanism of action of Vitamin D in the body?","options":[{"id":"a","text":"Increases blood glucose levels"},{"id":"b","text":"Promotes calcium and phosphate absorption"},{"id":"c","text":"Stimulates red blood cell production"},{"id":"d","text":"Enhances immune response"}],"answerId":"b","explanation":"Vitamin D promotes the absorption of calcium and phosphate, which are essential for bone health.","kind":"mechanism","origin":"ai"},{"id":"fat-soluble-vitamins~ai-5","moduleId":"fat-soluble-vitamins","stem":"A patient with cholestasis is at risk for which vitamin deficiency?","options":[{"id":"a","text":"Vitamin A"},{"id":"b","text":"Vitamin C"},{"id":"c","text":"Vitamin B12"},{"id":"d","text":"Vitamin K"}],"answerId":"d","explanation":"Cholestasis can impair the absorption of fat-soluble vitamins, leading to deficiencies, including Vitamin K.","kind":"integration","linkedModuleIds":["cholangitis-bile-vitamin-loss"],"origin":"ai"},{"id":"fat-soluble-vitamins~ai-6","moduleId":"fat-soluble-vitamins","stem":"In a patient with chronic pancreatitis, which vitamin deficiency is most likely to occur?","options":[{"id":"a","text":"Vitamin A"},{"id":"b","text":"Vitamin D"},{"id":"c","text":"Vitamin E"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"Chronic pancreatitis can lead to malabsorption of all fat-soluble vitamins (A, D, E, K).","kind":"integration","linkedModuleIds":["acute-chronic-pancreatitis"],"origin":"ai"}],"parasitology-host-relationships":[{"id":"parasitology-host-relationships~ai-0","moduleId":"parasitology-host-relationships","stem":"Which host type harbors the adult or sexual stage of a parasite?","options":[{"id":"a","text":"Intermediate host"},{"id":"b","text":"Definitive host"},{"id":"c","text":"Paratenic host"},{"id":"d","text":"Reservoir host"}],"answerId":"b","explanation":"The definitive host is defined as the host that harbors the adult or sexual stage of the parasite.","kind":"recall","origin":"ai"},{"id":"parasitology-host-relationships~ai-1","moduleId":"parasitology-host-relationships","stem":"In the life cycle of malaria, which organism is the definitive host?","options":[{"id":"a","text":"Human"},{"id":"b","text":"Anopheles mosquito"},{"id":"c","text":"Plasmodium"},{"id":"d","text":"Liver cells"}],"answerId":"b","explanation":"The Anopheles mosquito is the definitive host for malaria, where the sexual cycle of Plasmodium occurs.","kind":"recall","origin":"ai"},{"id":"parasitology-host-relationships~ai-2","moduleId":"parasitology-host-relationships","stem":"What is the role of a paratenic host in a parasite's life cycle?","options":[{"id":"a","text":"Harbors the adult stage"},{"id":"b","text":"Harbors the larval stage"},{"id":"c","text":"Carries the parasite with no development"},{"id":"d","text":"Maintains the parasite in nature"}],"answerId":"c","explanation":"A paratenic host carries the parasite without further development, acting as a transport host.","kind":"recall","origin":"ai"},{"id":"parasitology-host-relationships~ai-3","moduleId":"parasitology-host-relationships","stem":"A human infected with Plasmodium is considered which type of host?","options":[{"id":"a","text":"Definitive host"},{"id":"b","text":"Intermediate host"},{"id":"c","text":"Reservoir host"},{"id":"d","text":"Paratenic host"}],"answerId":"b","explanation":"Humans are the intermediate host for Plasmodium, where the asexual cycle occurs.","kind":"recall","origin":"ai"},{"id":"parasitology-host-relationships~ai-4","moduleId":"parasitology-host-relationships","stem":"Which of the following statements about definitive and intermediate hosts is true?","options":[{"id":"a","text":"Humans are always the definitive host."},{"id":"b","text":"The definitive host harbors the larval stage."},{"id":"c","text":"The intermediate host harbors the asexual stage."},{"id":"d","text":"The definitive host is always a vertebrate."}],"answerId":"c","explanation":"The intermediate host is defined by harboring the larval or asexual stages of a parasite.","kind":"trap","origin":"ai"},{"id":"parasitology-host-relationships~ai-5","moduleId":"parasitology-host-relationships","stem":"How does the role of the mosquito as a vector relate to its classification as a definitive host in malaria?","options":[{"id":"a","text":"It is a transport host."},{"id":"b","text":"It harbors the larval stage."},{"id":"c","text":"It allows for sexual reproduction of the parasite."},{"id":"d","text":"It maintains the parasite in nature."}],"answerId":"c","explanation":"The mosquito is classified as the definitive host because it allows for the sexual reproduction of Plasmodium.","kind":"integration","linkedModuleIds":["blood-apicomplexa-malaria-babesia"],"origin":"ai"},{"id":"parasitology-host-relationships~ai-6","moduleId":"parasitology-host-relationships","stem":"What is the significance of understanding host types in relation to urinary tract infections?","options":[{"id":"a","text":"It helps identify the definitive host of the infection."},{"id":"b","text":"It aids in recognizing the role of human hosts in zoonotic infections."},{"id":"c","text":"It informs the treatment of infections caused by ectoparasites."},{"id":"d","text":"It assists in understanding the defense mechanisms of the urinary tract."}],"answerId":"d","explanation":"Understanding host types is crucial for recognizing how the urinary tract's defense mechanisms interact with pathogens.","kind":"integration","linkedModuleIds":["urinary-tract-host-defenses"],"origin":"ai"}],"parasite-transmission-diagnosis":[{"id":"parasite-transmission-diagnosis~ai-0","moduleId":"parasite-transmission-diagnosis","stem":"What is the primary route of transmission for Toxoplasma gondii?","options":[{"id":"a","text":"Vector-borne"},{"id":"b","text":"Faecal-oral"},{"id":"c","text":"Congenital"},{"id":"d","text":"Ingestion of undercooked meat"}],"answerId":"d","explanation":"Toxoplasma gondii is primarily transmitted through ingestion of undercooked meat containing cysts.","kind":"recall","origin":"ai"},{"id":"parasite-transmission-diagnosis~ai-1","moduleId":"parasite-transmission-diagnosis","stem":"Which of the following is a characteristic of a biological vector?","options":[{"id":"a","text":"Carries the parasite externally"},{"id":"b","text":"Transmits without development"},{"id":"c","text":"Supports parasite multiplication"},{"id":"d","text":"Is always an insect"}],"answerId":"c","explanation":"A biological vector, such as Anopheles for malaria, supports the multiplication and development of the parasite.","kind":"mechanism","origin":"ai"},{"id":"parasite-transmission-diagnosis~ai-2","moduleId":"parasite-transmission-diagnosis","stem":"Which diagnostic method is most appropriate for identifying intestinal helminths?","options":[{"id":"a","text":"Blood film"},{"id":"b","text":"Stool ova-and-parasite examination"},{"id":"c","text":"Serology"},{"id":"d","text":"PCR"}],"answerId":"b","explanation":"Stool ova-and-parasite examination is the first-line diagnostic method for intestinal helminths.","kind":"recall","origin":"ai"},{"id":"parasite-transmission-diagnosis~ai-3","moduleId":"parasite-transmission-diagnosis","stem":"A patient presents with eosinophilia and gastrointestinal symptoms. What is the most likely cause?","options":[{"id":"a","text":"Bacterial infection"},{"id":"b","text":"Viral infection"},{"id":"c","text":"Tissue-invasive helminth"},{"id":"d","text":"Protozoan infection"}],"answerId":"c","explanation":"Eosinophilia is a common finding in tissue-invasive helminth infections.","kind":"clinical","origin":"ai"},{"id":"parasite-transmission-diagnosis~ai-4","moduleId":"parasite-transmission-diagnosis","stem":"Which statement about mechanical vectors is true?","options":[{"id":"a","text":"They are essential for the parasite's life cycle"},{"id":"b","text":"They carry the parasite without development"},{"id":"c","text":"They are always arthropods"},{"id":"d","text":"They are specific to one type of parasite"}],"answerId":"b","explanation":"Mechanical vectors carry the parasite externally without supporting its development.","kind":"trap","origin":"ai"},{"id":"parasite-transmission-diagnosis~ai-5","moduleId":"parasite-transmission-diagnosis","stem":"How does the transmission of Entamoeba histolytica primarily occur?","options":[{"id":"a","text":"Vector-borne"},{"id":"b","text":"Faecal-oral"},{"id":"c","text":"Ingestion of undercooked meat"},{"id":"d","text":"Congenital"}],"answerId":"b","explanation":"Entamoeba histolytica is primarily transmitted via the faecal-oral route.","kind":"integration","linkedModuleIds":["entamoeba-histolytica-amoebiasis"],"origin":"ai"},{"id":"parasite-transmission-diagnosis~ai-6","moduleId":"parasite-transmission-diagnosis","stem":"Which of the following is a common diagnostic method for Giardia lamblia?","options":[{"id":"a","text":"Blood film"},{"id":"b","text":"Stool examination"},{"id":"c","text":"Serology"},{"id":"d","text":"Tissue biopsy"}],"answerId":"b","explanation":"Stool examination is the primary diagnostic method for Giardia lamblia.","kind":"integration","linkedModuleIds":["giardia-intestinal-flagellates"],"origin":"ai"}],"water-soluble-vitamins-trace-elements":[{"id":"water-soluble-vitamins-trace-elements~ai-0","moduleId":"water-soluble-vitamins-trace-elements","stem":"Which vitamin deficiency is primarily responsible for subacute combined degeneration of the spinal cord?","options":[{"id":"a","text":"Vitamin B1"},{"id":"b","text":"Vitamin B3"},{"id":"c","text":"Vitamin B9"},{"id":"d","text":"Vitamin B12"}],"answerId":"d","explanation":"Vitamin B12 deficiency leads to neurological damage, specifically subacute combined degeneration of the spinal cord.","kind":"recall","origin":"ai"},{"id":"water-soluble-vitamins-trace-elements~ai-1","moduleId":"water-soluble-vitamins-trace-elements","stem":"What is the primary clinical manifestation of vitamin C deficiency?","options":[{"id":"a","text":"Megaloblastic anemia"},{"id":"b","text":"Dermatitis"},{"id":"c","text":"Scurvy"},{"id":"d","text":"Wernicke encephalopathy"}],"answerId":"c","explanation":"Vitamin C deficiency causes scurvy, characterized by bleeding gums and poor wound healing.","kind":"recall","origin":"ai"},{"id":"water-soluble-vitamins-trace-elements~ai-2","moduleId":"water-soluble-vitamins-trace-elements","stem":"A patient presents with confusion, ophthalmoplegia, and ataxia. Which vitamin deficiency is most likely responsible?","options":[{"id":"a","text":"Vitamin B1"},{"id":"b","text":"Vitamin B3"},{"id":"c","text":"Vitamin B6"},{"id":"d","text":"Vitamin B12"}],"answerId":"a","explanation":"These symptoms are classic for Wernicke encephalopathy, which is caused by thiamine (Vitamin B1) deficiency.","kind":"clinical","origin":"ai"},{"id":"water-soluble-vitamins-trace-elements~ai-3","moduleId":"water-soluble-vitamins-trace-elements","stem":"Which trace element deficiency is most commonly associated with microcytic anemia?","options":[{"id":"a","text":"Zinc"},{"id":"b","text":"Copper"},{"id":"c","text":"Iron"},{"id":"d","text":"Iodine"}],"answerId":"c","explanation":"Iron deficiency is the most common nutritional deficiency leading to microcytic anemia.","kind":"recall","origin":"ai"},{"id":"water-soluble-vitamins-trace-elements~ai-4","moduleId":"water-soluble-vitamins-trace-elements","stem":"What is the consequence of administering folate alone to a patient with vitamin B12 deficiency?","options":[{"id":"a","text":"Corrects anemia without complications"},{"id":"b","text":"Worsens neurological damage"},{"id":"c","text":"Improves neurological symptoms"},{"id":"d","text":"Causes iron overload"}],"answerId":"b","explanation":"Administering folate alone can mask the anemia while allowing neurological damage from B12 deficiency to progress.","kind":"trap","origin":"ai"},{"id":"water-soluble-vitamins-trace-elements~ai-5","moduleId":"water-soluble-vitamins-trace-elements","stem":"Which vitamin is crucial for collagen hydroxylation and acts as an antioxidant?","options":[{"id":"a","text":"Vitamin B1"},{"id":"b","text":"Vitamin B3"},{"id":"c","text":"Vitamin C"},{"id":"d","text":"Vitamin B12"}],"answerId":"c","explanation":"Vitamin C is essential for collagen synthesis and functions as an antioxidant.","kind":"recall","origin":"ai"},{"id":"water-soluble-vitamins-trace-elements~ai-6","moduleId":"water-soluble-vitamins-trace-elements","stem":"How does vitamin B12 absorption relate to intrinsic factor?","options":[{"id":"a","text":"Intrinsic factor enhances iron absorption"},{"id":"b","text":"Intrinsic factor is necessary for B12 absorption"},{"id":"c","text":"Intrinsic factor is produced in the liver"},{"id":"d","text":"Intrinsic factor is not related to vitamin absorption"}],"answerId":"b","explanation":"Intrinsic factor is essential for the absorption of vitamin B12 in the intestine.","kind":"mechanism","origin":"ai"},{"id":"water-soluble-vitamins-trace-elements~ai-7","moduleId":"water-soluble-vitamins-trace-elements","stem":"A patient with inflammatory bowel disease is found to have megaloblastic anemia. What should be prioritized in treatment?","options":[{"id":"a","text":"Administer folate alone"},{"id":"b","text":"Administer B12 alone"},{"id":"c","text":"Confirm B12 deficiency and treat accordingly"},{"id":"d","text":"Provide iron supplements"}],"answerId":"c","explanation":"In patients with megaloblastic anemia, it is crucial to confirm and treat B12 deficiency to prevent neurological damage.","kind":"integration","linkedModuleIds":["inflammatory-bowel-disease"],"origin":"ai"},{"id":"water-soluble-vitamins-trace-elements~ai-8","moduleId":"water-soluble-vitamins-trace-elements","stem":"In a patient with cholangitis, which vitamin deficiency might occur due to bile flow obstruction?","options":[{"id":"a","text":"Vitamin B12"},{"id":"b","text":"Vitamin C"},{"id":"c","text":"Fat-soluble vitamins"},{"id":"d","text":"Vitamin B3"}],"answerId":"c","explanation":"Bile flow obstruction can lead to malabsorption of fat-soluble vitamins, which are essential for various bodily functions.","kind":"integration","linkedModuleIds":["cholangitis-bile-vitamin-loss"],"origin":"ai"}],"trichomonas-balantidium":[{"id":"trichomonas-balantidium~ai-0","moduleId":"trichomonas-balantidium","stem":"What is the primary mode of transmission for Trichomonas vaginalis?","options":[{"id":"a","text":"Fecal-oral route"},{"id":"b","text":"Sexual contact"},{"id":"c","text":"Airborne transmission"},{"id":"d","text":"Vector-borne transmission"}],"answerId":"b","explanation":"Trichomonas vaginalis is a sexually transmitted protozoan that spreads directly as the trophozoite, not through fecal-oral transmission.","kind":"recall","origin":"ai"},{"id":"trichomonas-balantidium~ai-1","moduleId":"trichomonas-balantidium","stem":"Which of the following findings is characteristic of Trichomonas vaginalis infection?","options":[{"id":"a","text":"Bloody diarrhea"},{"id":"b","text":"Frothy yellow-green vaginal discharge"},{"id":"c","text":"Cyst formation"},{"id":"d","text":"Ciliated trophozoites"}],"answerId":"b","explanation":"Trichomonas vaginalis infection is characterized by a frothy yellow-green vaginal discharge and does not form cysts.","kind":"recall","origin":"ai"},{"id":"trichomonas-balantidium~ai-2","moduleId":"trichomonas-balantidium","stem":"What is the mechanism of action of metronidazole in treating Trichomonas vaginalis?","options":[{"id":"a","text":"Inhibition of protein synthesis"},{"id":"b","text":"Disruption of DNA synthesis"},{"id":"c","text":"Inhibition of folate synthesis"},{"id":"d","text":"Inhibition of cell wall synthesis"}],"answerId":"b","explanation":"Metronidazole disrupts DNA synthesis in anaerobic bacteria and protozoa, including Trichomonas vaginalis.","kind":"mechanism","origin":"ai"},{"id":"trichomonas-balantidium~ai-3","moduleId":"trichomonas-balantidium","stem":"What clinical finding is associated with Balantidium coli infection?","options":[{"id":"a","text":"Strawberry cervix"},{"id":"b","text":"Frothy discharge"},{"id":"c","text":"Large ciliated trophozoite"},{"id":"d","text":"Motile pear-shaped flagellate"}],"answerId":"c","explanation":"Balantidium coli is characterized by a large ciliated trophozoite and can cause dysentery.","kind":"recall","origin":"ai"},{"id":"trichomonas-balantidium~ai-4","moduleId":"trichomonas-balantidium","stem":"Which of the following statements about Trichomonas vaginalis is FALSE?","options":[{"id":"a","text":"It has a cyst stage."},{"id":"b","text":"It is sexually transmitted."},{"id":"c","text":"It can cause vaginitis."},{"id":"d","text":"Men may be asymptomatic carriers."}],"answerId":"a","explanation":"Trichomonas vaginalis does not have a cyst stage; it is transmitted as a trophozoite.","kind":"trap","origin":"ai"},{"id":"trichomonas-balantidium~ai-5","moduleId":"trichomonas-balantidium","stem":"How does the treatment of Trichomonas vaginalis differ from that of Entamoeba histolytica?","options":[{"id":"a","text":"Both require partner treatment."},{"id":"b","text":"Entamoeba is treated with metronidazole only."},{"id":"c","text":"Trichomonas has no cyst stage."},{"id":"d","text":"Entamoeba is transmitted sexually."}],"answerId":"c","explanation":"Trichomonas vaginalis has no cyst stage and is sexually transmitted, while Entamoeba histolytica can form cysts and is transmitted via fecal-oral route.","kind":"integration","linkedModuleIds":["entamoeba-histolytica-amoebiasis"],"origin":"ai"},{"id":"trichomonas-balantidium~ai-6","moduleId":"trichomonas-balantidium","stem":"Which organism is most likely to be found in a patient with dysentery who has had recent contact with pigs?","options":[{"id":"a","text":"Trichomonas vaginalis"},{"id":"b","text":"Giardia lamblia"},{"id":"c","text":"Balantidium coli"},{"id":"d","text":"Entamoeba histolytica"}],"answerId":"c","explanation":"Balantidium coli is the only pathogenic ciliate and is zoonotically transmitted from pigs, causing dysentery.","kind":"integration","linkedModuleIds":["giardia-intestinal-flagellates"],"origin":"ai"}],"entamoeba-histolytica-amoebiasis":[{"id":"entamoeba-histolytica-amoebiasis~ai-0","moduleId":"entamoeba-histolytica-amoebiasis","stem":"What is the primary mode of transmission for Entamoeba histolytica?","options":[{"id":"a","text":"Vector-borne transmission"},{"id":"b","text":"Airborne transmission"},{"id":"c","text":"Faecal-oral transmission"},{"id":"d","text":"Sexual transmission"}],"answerId":"c","explanation":"Entamoeba histolytica is primarily transmitted through the faecal-oral route by ingesting mature cysts.","kind":"recall","origin":"ai"},{"id":"entamoeba-histolytica-amoebiasis~ai-1","moduleId":"entamoeba-histolytica-amoebiasis","stem":"Which clinical finding is characteristic of invasive intestinal amoebiasis?","options":[{"id":"a","text":"Watery diarrhea"},{"id":"b","text":"Flask-shaped ulcers"},{"id":"c","text":"Abdominal pain without diarrhea"},{"id":"d","text":"Fever without gastrointestinal symptoms"}],"answerId":"b","explanation":"Flask-shaped ulcers are a hallmark of invasive intestinal amoebiasis caused by Entamoeba histolytica.","kind":"recall","origin":"ai"},{"id":"entamoeba-histolytica-amoebiasis~ai-2","moduleId":"entamoeba-histolytica-amoebiasis","stem":"What is the mechanism by which Entamoeba histolytica causes tissue damage in the colon?","options":[{"id":"a","text":"Toxin production"},{"id":"b","text":"Direct invasion of epithelial cells"},{"id":"c","text":"Immune-mediated damage"},{"id":"d","text":"Inhibition of peristalsis"}],"answerId":"b","explanation":"Entamoeba histolytica directly invades the epithelial cells of the colon, leading to tissue damage and ulcer formation.","kind":"mechanism","origin":"ai"},{"id":"entamoeba-histolytica-amoebiasis~ai-3","moduleId":"entamoeba-histolytica-amoebiasis","stem":"What is the most common extra-intestinal manifestation of Entamoeba histolytica infection?","options":[{"id":"a","text":"Pulmonary abscess"},{"id":"b","text":"Amoebic liver abscess"},{"id":"c","text":"Cerebral amoebiasis"},{"id":"d","text":"Skin ulceration"}],"answerId":"b","explanation":"Amoebic liver abscess is the most common extra-intestinal manifestation, typically occurring in the right lobe of the liver.","kind":"recall","origin":"ai"},{"id":"entamoeba-histolytica-amoebiasis~ai-4","moduleId":"entamoeba-histolytica-amoebiasis","stem":"Which of the following is a key diagnostic clue for invasive E. histolytica?","options":[{"id":"a","text":"Presence of cysts in stool"},{"id":"b","text":"Trophozoites containing ingested red blood cells"},{"id":"c","text":"Negative serology"},{"id":"d","text":"Normal liver function tests"}],"answerId":"b","explanation":"The presence of trophozoites containing ingested red blood cells indicates erythrophagocytosis, a marker of invasive E. histolytica.","kind":"recall","origin":"ai"},{"id":"entamoeba-histolytica-amoebiasis~ai-5","moduleId":"entamoeba-histolytica-amoebiasis","stem":"Which treatment regimen is necessary for complete management of amoebiasis?","options":[{"id":"a","text":"Metronidazole alone"},{"id":"b","text":"Paromomycin alone"},{"id":"c","text":"Metronidazole plus paromomycin"},{"id":"d","text":"Diloxanide alone"}],"answerId":"c","explanation":"Metronidazole treats the invasive trophozoites, but a luminal agent like paromomycin is needed to eradicate cysts and prevent relapse.","kind":"trap","origin":"ai"},{"id":"entamoeba-histolytica-amoebiasis~ai-6","moduleId":"entamoeba-histolytica-amoebiasis","stem":"How does the life cycle of Entamoeba histolytica relate to its pathogenicity?","options":[{"id":"a","text":"Cysts are non-infectious"},{"id":"b","text":"Trophozoites are resistant to immune response"},{"id":"c","text":"Cysts are the infective stage that excyst to form trophozoites"},{"id":"d","text":"Trophozoites can survive in the environment for long periods"}],"answerId":"c","explanation":"The cysts are the infective stage that excyst in the gut, releasing trophozoites that can invade the colonic mucosa.","kind":"integration","linkedModuleIds":["protozoa-classification-biology"],"origin":"ai"},{"id":"entamoeba-histolytica-amoebiasis~ai-7","moduleId":"entamoeba-histolytica-amoebiasis","stem":"Which of the following best describes the relationship between Entamoeba histolytica and E. dispar?","options":[{"id":"a","text":"Both are pathogenic"},{"id":"b","text":"E. dispar is more virulent"},{"id":"c","text":"E. dispar is non-pathogenic"},{"id":"d","text":"Both cause similar symptoms"}],"answerId":"c","explanation":"E. dispar is morphologically identical to E. histolytica but is non-pathogenic, requiring specific tests for differentiation.","kind":"integration","linkedModuleIds":["free-living-nonpathogenic-amoebae"],"origin":"ai"}],"protozoa-classification-biology":[{"id":"protozoa-classification-biology~ai-0","moduleId":"protozoa-classification-biology","stem":"Which of the following protozoa is classified as an apicomplexan?","options":[{"id":"a","text":"Entamoeba histolytica"},{"id":"b","text":"Giardia lamblia"},{"id":"c","text":"Plasmodium falciparum"},{"id":"d","text":"Balantidium coli"}],"answerId":"c","explanation":"Plasmodium falciparum is an apicomplexan, known for causing malaria, while the others belong to different groups.","kind":"recall","origin":"ai"},{"id":"protozoa-classification-biology~ai-1","moduleId":"protozoa-classification-biology","stem":"What is the primary mode of locomotion for flagellates?","options":[{"id":"a","text":"Cilia"},{"id":"b","text":"Pseudopods"},{"id":"c","text":"Flagella"},{"id":"d","text":"Apical complex"}],"answerId":"c","explanation":"Flagellates move using whip-like flagella, distinguishing them from amoebae and ciliates.","kind":"recall","origin":"ai"},{"id":"protozoa-classification-biology~ai-2","moduleId":"protozoa-classification-biology","stem":"Which stage of a protozoan is responsible for causing disease?","options":[{"id":"a","text":"Cyst"},{"id":"b","text":"Trophozoite"},{"id":"c","text":"Oocyst"},{"id":"d","text":"Sporozoite"}],"answerId":"b","explanation":"The trophozoite is the active, feeding, motile stage that causes disease, while cysts are the infective transmission stage.","kind":"recall","origin":"ai"},{"id":"protozoa-classification-biology~ai-3","moduleId":"protozoa-classification-biology","stem":"A patient presents with diarrhea and stool examination reveals cysts. What does this indicate?","options":[{"id":"a","text":"Active infection with trophozoites"},{"id":"b","text":"Recent infection with trophozoites"},{"id":"c","text":"Infective transmission stage"},{"id":"d","text":"Non-infective stage"}],"answerId":"c","explanation":"Cysts are the resistant, infective transmission stage, indicating potential for infection rather than active disease.","kind":"clinical","origin":"ai"},{"id":"protozoa-classification-biology~ai-4","moduleId":"protozoa-classification-biology","stem":"Which of the following is a common trap in understanding protozoan life cycles?","options":[{"id":"a","text":"Cysts cause disease"},{"id":"b","text":"Trophozoites are the infective stage"},{"id":"c","text":"Cysts are environmentally stable"},{"id":"d","text":"Trophozoites are resistant to environmental changes"}],"answerId":"c","explanation":"Cysts are indeed environmentally stable and the infective stage, while trophozoites are fragile and cause disease.","kind":"trap","origin":"ai"},{"id":"protozoa-classification-biology~ai-5","moduleId":"protozoa-classification-biology","stem":"How do apicomplexans reproduce compared to other protozoa?","options":[{"id":"a","text":"Only by binary fission"},{"id":"b","text":"Only by sexual reproduction"},{"id":"c","text":"By binary fission and sexual reproduction"},{"id":"d","text":"By budding"}],"answerId":"c","explanation":"Apicomplexans reproduce both asexually by binary fission and sexually through processes like sporogony.","kind":"mechanism","origin":"ai"},{"id":"protozoa-classification-biology~ai-6","moduleId":"protozoa-classification-biology","stem":"Which protozoan is most likely to be transmitted through contaminated water and is classified as a flagellate?","options":[{"id":"a","text":"Entamoeba histolytica"},{"id":"b","text":"Giardia lamblia"},{"id":"c","text":"Balantidium coli"},{"id":"d","text":"Plasmodium vivax"}],"answerId":"b","explanation":"Giardia lamblia is a flagellate commonly transmitted through contaminated water, causing gastrointestinal symptoms.","kind":"integration","linkedModuleIds":["giardia-intestinal-flagellates"],"origin":"ai"},{"id":"protozoa-classification-biology~ai-7","moduleId":"protozoa-classification-biology","stem":"What is the significance of identifying cysts versus trophozoites in stool samples?","options":[{"id":"a","text":"Cysts indicate active disease"},{"id":"b","text":"Trophozoites indicate infective transmission"},{"id":"c","text":"Cysts indicate potential for infection"},{"id":"d","text":"Trophozoites are more resistant than cysts"}],"answerId":"c","explanation":"Identifying cysts indicates potential for infection, while trophozoites suggest active disease, crucial for diagnosis.","kind":"integration","linkedModuleIds":["entamoeba-histolytica-amoebiasis"],"origin":"ai"}],"giardia-intestinal-flagellates":[{"id":"giardia-intestinal-flagellates~ai-0","moduleId":"giardia-intestinal-flagellates","stem":"What is the primary mode of transmission for Giardia lamblia?","options":[{"id":"a","text":"Airborne droplets"},{"id":"b","text":"Fecal-oral route"},{"id":"c","text":"Vector-borne transmission"},{"id":"d","text":"Sexual contact"}],"answerId":"b","explanation":"Giardia lamblia is primarily transmitted via the fecal-oral route, typically through contaminated water.","kind":"recall","origin":"ai"},{"id":"giardia-intestinal-flagellates~ai-1","moduleId":"giardia-intestinal-flagellates","stem":"Which of the following best describes the morphology of Giardia lamblia trophozoites?","options":[{"id":"a","text":"Round with a single nucleus"},{"id":"b","text":"Pear-shaped with two nuclei"},{"id":"c","text":"Cylindrical with multiple flagella"},{"id":"d","text":"Flat and oval with no flagella"}],"answerId":"b","explanation":"Giardia lamblia trophozoites are distinctive for their pear shape and two nuclei, resembling an 'owl face'.","kind":"recall","origin":"ai"},{"id":"giardia-intestinal-flagellates~ai-2","moduleId":"giardia-intestinal-flagellates","stem":"A patient presents with greasy, foul-smelling diarrhea after drinking untreated water. What is the most likely diagnosis?","options":[{"id":"a","text":"Amoebic dysentery"},{"id":"b","text":"Giardiasis"},{"id":"c","text":"Bacterial gastroenteritis"},{"id":"d","text":"Viral gastroenteritis"}],"answerId":"b","explanation":"The presentation of greasy, foul-smelling diarrhea after drinking untreated water is characteristic of giardiasis.","kind":"clinical","origin":"ai"},{"id":"giardia-intestinal-flagellates~ai-3","moduleId":"giardia-intestinal-flagellates","stem":"What is the mechanism by which Giardia lamblia causes malabsorption?","options":[{"id":"a","text":"Invasion of intestinal mucosa"},{"id":"b","text":"Toxin production"},{"id":"c","text":"Coating of the intestinal surface"},{"id":"d","text":"Disruption of gut flora"}],"answerId":"c","explanation":"Giardia lamblia attaches to the intestinal mucosa, coating the absorptive surface and leading to malabsorption.","kind":"mechanism","origin":"ai"},{"id":"giardia-intestinal-flagellates~ai-4","moduleId":"giardia-intestinal-flagellates","stem":"Why might a single negative stool test not exclude giardiasis in a symptomatic patient?","options":[{"id":"a","text":"Cysts are too small to detect"},{"id":"b","text":"Intermittent cyst shedding"},{"id":"c","text":"Presence of other pathogens"},{"id":"d","text":"Test is not specific for Giardia"}],"answerId":"b","explanation":"Giardia cysts are shed intermittently, so a single negative stool test does not rule out the infection.","kind":"trap","origin":"ai"},{"id":"giardia-intestinal-flagellates~ai-5","moduleId":"giardia-intestinal-flagellates","stem":"A patient with suspected giardiasis has a negative stool antigen test. What should be the next step?","options":[{"id":"a","text":"Start empirical treatment"},{"id":"b","text":"Repeat stool antigen test"},{"id":"c","text":"Perform a duodenal aspirate"},{"id":"d","text":"Refer for endoscopy"}],"answerId":"c","explanation":"If clinical suspicion remains high, a duodenal aspirate can be performed to obtain trophozoites directly.","kind":"clinical","origin":"ai"},{"id":"giardia-intestinal-flagellates~ai-6","moduleId":"giardia-intestinal-flagellates","stem":"How does giardiasis differ from amoebic dysentery caused by Entamoeba histolytica?","options":[{"id":"a","text":"Giardiasis is invasive, amoebic dysentery is not"},{"id":"b","text":"Amoebic dysentery causes non-bloody diarrhea"},{"id":"c","text":"Giardiasis is non-invasive with malabsorption"},{"id":"d","text":"Both cause bloody diarrhea"}],"answerId":"c","explanation":"Giardiasis is non-invasive and causes malabsorption, while amoebic dysentery is invasive and causes bloody diarrhea.","kind":"integration","linkedModuleIds":["entamoeba-histolytica-amoebiasis"],"origin":"ai"},{"id":"giardia-intestinal-flagellates~ai-7","moduleId":"giardia-intestinal-flagellates","stem":"Which of the following conditions shares a similar transmission route with giardiasis?","options":[{"id":"a","text":"Trichomoniasis"},{"id":"b","text":"Amoebic dysentery"},{"id":"c","text":"Bacterial gastroenteritis"},{"id":"d","text":"Dientamoeba fragilis infection"}],"answerId":"d","explanation":"Dientamoeba fragilis, like Giardia, is transmitted via the fecal-oral route and causes non-bloody diarrhea.","kind":"integration","linkedModuleIds":["trichomonas-balantidium"],"origin":"ai"}],"eating-disorders":[{"id":"eating-disorders~ai-0","moduleId":"eating-disorders","stem":"What is the primary characteristic of anorexia nervosa?","options":[{"id":"a","text":"Recurrent binge eating"},{"id":"b","text":"Compensatory purging"},{"id":"c","text":"Significantly low body weight"},{"id":"d","text":"Normal body weight"}],"answerId":"c","explanation":"Anorexia nervosa is defined by significantly low body weight, an intense fear of weight gain, and distorted body image.","kind":"recall","origin":"ai"},{"id":"eating-disorders~ai-1","moduleId":"eating-disorders","stem":"Which electrolyte disturbance is most commonly associated with purging in bulimia nervosa?","options":[{"id":"a","text":"Hyperkalemia"},{"id":"b","text":"Hypokalemia"},{"id":"c","text":"Hypercalcemia"},{"id":"d","text":"Hypocalcemia"}],"answerId":"b","explanation":"Hypokalemia is a significant risk in bulimia nervosa due to self-induced vomiting and laxative use.","kind":"recall","origin":"ai"},{"id":"eating-disorders~ai-2","moduleId":"eating-disorders","stem":"A patient presents with very low body weight, amenorrhea, and bradycardia. What is the most likely diagnosis?","options":[{"id":"a","text":"Binge-eating disorder"},{"id":"b","text":"Bulimia nervosa"},{"id":"c","text":"Anorexia nervosa"},{"id":"d","text":"Normal weight obesity"}],"answerId":"c","explanation":"These signs are characteristic of anorexia nervosa, which involves significant weight loss and physiological consequences.","kind":"clinical","origin":"ai"},{"id":"eating-disorders~ai-3","moduleId":"eating-disorders","stem":"What is a potential complication of rapid nutritional restoration in a malnourished patient?","options":[{"id":"a","text":"Hypokalemia"},{"id":"b","text":"Hypophosphatemia"},{"id":"c","text":"Hyperglycemia"},{"id":"d","text":"Dehydration"}],"answerId":"b","explanation":"Refeeding syndrome can lead to hypophosphatemia and other electrolyte disturbances when nutrition is restored too quickly.","kind":"mechanism","origin":"ai"},{"id":"eating-disorders~ai-4","moduleId":"eating-disorders","stem":"Which finding is indicative of bulimia nervosa?","options":[{"id":"a","text":"Very low body weight"},{"id":"b","text":"Normal weight with dental erosion"},{"id":"c","text":"Obesity without purging"},{"id":"d","text":"Severe bradycardia"}],"answerId":"b","explanation":"Normal weight combined with dental erosion and parotid swelling suggests bulimia nervosa due to purging behaviors.","kind":"recall","origin":"ai"},{"id":"eating-disorders~ai-5","moduleId":"eating-disorders","stem":"How does binge-eating disorder differ from bulimia nervosa?","options":[{"id":"a","text":"Presence of purging"},{"id":"b","text":"Significantly low body weight"},{"id":"c","text":"Absence of compensatory behaviors"},{"id":"d","text":"Higher mortality risk"}],"answerId":"c","explanation":"Binge-eating disorder is characterized by recurrent binge eating without compensatory purging, unlike bulimia nervosa.","kind":"trap","origin":"ai"},{"id":"eating-disorders~ai-6","moduleId":"eating-disorders","stem":"In managing a patient with anorexia nervosa, which aspect is crucial to monitor during refeeding?","options":[{"id":"a","text":"Weight gain"},{"id":"b","text":"Electrolyte levels"},{"id":"c","text":"Psychological therapy"},{"id":"d","text":"Caloric intake"}],"answerId":"b","explanation":"Monitoring electrolyte levels is critical during refeeding to prevent refeeding syndrome and associated complications.","kind":"mechanism","origin":"ai"},{"id":"eating-disorders~ai-7","moduleId":"eating-disorders","stem":"How does obesity relate to binge-eating disorder in terms of health risks?","options":[{"id":"a","text":"It decreases the risk of metabolic syndrome"},{"id":"b","text":"It is unrelated to mental health"},{"id":"c","text":"It increases the risk of obesity-related complications"},{"id":"d","text":"It is always associated with purging behaviors"}],"answerId":"c","explanation":"Binge-eating disorder is often associated with obesity, which increases the risk of obesity-related health complications.","kind":"integration","linkedModuleIds":["obesity-pathophysiology"],"origin":"ai"},{"id":"eating-disorders~ai-8","moduleId":"eating-disorders","stem":"What is a common consequence of both anorexia nervosa and rapid nutritional rehabilitation?","options":[{"id":"a","text":"Hypokalemia"},{"id":"b","text":"Hypophosphatemia"},{"id":"c","text":"Hyperglycemia"},{"id":"d","text":"Hypertension"}],"answerId":"b","explanation":"Hypophosphatemia is a common consequence of rapid nutritional rehabilitation, particularly in patients with a history of malnutrition like those with anorexia nervosa.","kind":"integration","linkedModuleIds":["nutrition-energy-protein-malnutrition"],"origin":"ai"}],"intestinal-flukes-tapeworms":[{"id":"intestinal-flukes-tapeworms~ai-0","moduleId":"intestinal-flukes-tapeworms","stem":"What is the primary route of transmission for neurocysticercosis caused by Taenia solium?","options":[{"id":"a","text":"Ingesting undercooked pork"},{"id":"b","text":"Ingesting eggs via fecal-oral route"},{"id":"c","text":"Contaminated water"},{"id":"d","text":"Direct contact with infected individuals"}],"answerId":"b","explanation":"Neurocysticercosis occurs when humans ingest Taenia solium eggs through the fecal-oral route, leading to larval cyst formation in tissues.","kind":"recall","origin":"ai"},{"id":"intestinal-flukes-tapeworms~ai-1","moduleId":"intestinal-flukes-tapeworms","stem":"Which tapeworm is associated with megaloblastic anemia due to vitamin B12 deficiency?","options":[{"id":"a","text":"Taenia saginata"},{"id":"b","text":"Taenia solium"},{"id":"c","text":"Diphyllobothrium latum"},{"id":"d","text":"Echinococcus granulosus"}],"answerId":"c","explanation":"Diphyllobothrium latum, the fish tapeworm, competes for vitamin B12, leading to megaloblastic anemia.","kind":"recall","origin":"ai"},{"id":"intestinal-flukes-tapeworms~ai-2","moduleId":"intestinal-flukes-tapeworms","stem":"A patient presents with abdominal pain and diarrhea after consuming water chestnuts. What is the likely causative organism?","options":[{"id":"a","text":"Taenia saginata"},{"id":"b","text":"Fasciolopsis buski"},{"id":"c","text":"Diphyllobothrium latum"},{"id":"d","text":"Echinococcus granulosus"}],"answerId":"b","explanation":"Fasciolopsis buski, the giant intestinal fluke, is acquired from aquatic plants and causes abdominal symptoms.","kind":"clinical","origin":"ai"},{"id":"intestinal-flukes-tapeworms~ai-3","moduleId":"intestinal-flukes-tapeworms","stem":"What is the mechanism by which Echinococcus granulosus causes hydatid disease?","options":[{"id":"a","text":"Direct ingestion of adult worms"},{"id":"b","text":"Ingestion of eggs leading to cyst formation"},{"id":"c","text":"Ingestion of larvae from undercooked meat"},{"id":"d","text":"Contaminated water exposure"}],"answerId":"b","explanation":"Humans become accidental intermediate hosts by ingesting Echinococcus granulosus eggs, leading to hydatid cyst formation.","kind":"mechanism","origin":"ai"},{"id":"intestinal-flukes-tapeworms~ai-4","moduleId":"intestinal-flukes-tapeworms","stem":"Which of the following is a potential complication of improperly aspirating a hydatid cyst?","options":[{"id":"a","text":"Megaloblastic anemia"},{"id":"b","text":"Neurocysticercosis"},{"id":"c","text":"Anaphylaxis"},{"id":"d","text":"Malabsorption syndrome"}],"answerId":"c","explanation":"Careless aspiration of a hydatid cyst can lead to spillage, causing anaphylaxis and dissemination of daughter cysts.","kind":"trap","origin":"ai"},{"id":"intestinal-flukes-tapeworms~ai-5","moduleId":"intestinal-flukes-tapeworms","stem":"A patient presents with adult-onset seizures and brain imaging reveals cystic lesions. Which organism is most likely responsible?","options":[{"id":"a","text":"Diphyllobothrium latum"},{"id":"b","text":"Taenia solium"},{"id":"c","text":"Fasciolopsis buski"},{"id":"d","text":"Echinococcus granulosus"}],"answerId":"b","explanation":"Taenia solium eggs can lead to neurocysticercosis, which is characterized by cystic lesions in the brain.","kind":"clinical","origin":"ai"},{"id":"intestinal-flukes-tapeworms~ai-6","moduleId":"intestinal-flukes-tapeworms","stem":"How does the consumption of raw freshwater fish relate to vitamin B12 deficiency?","options":[{"id":"a","text":"It directly causes malabsorption"},{"id":"b","text":"It introduces Diphyllobothrium latum"},{"id":"c","text":"It leads to intestinal fluke infections"},{"id":"d","text":"It causes hydatid disease"}],"answerId":"b","explanation":"Raw freshwater fish can introduce Diphyllobothrium latum, which competes for vitamin B12, leading to deficiency.","kind":"integration","linkedModuleIds":["water-soluble-vitamins-trace-elements"],"origin":"ai"},{"id":"intestinal-flukes-tapeworms~ai-7","moduleId":"intestinal-flukes-tapeworms","stem":"What is the relationship between Taenia solium and neurocysticercosis?","options":[{"id":"a","text":"Ingesting larvae causes brain cysts"},{"id":"b","text":"Ingesting eggs leads to tissue cysts"},{"id":"c","text":"Eating undercooked pork causes intestinal infection"},{"id":"d","text":"All of the above"}],"answerId":"b","explanation":"Neurocysticercosis arises from ingesting Taenia solium eggs, not from eating undercooked pork which leads to intestinal infection.","kind":"integration","linkedModuleIds":["cestodes-tapeworms-overview"],"origin":"ai"}],"free-living-nonpathogenic-amoebae":[{"id":"free-living-nonpathogenic-amoebae~ai-0","moduleId":"free-living-nonpathogenic-amoebae","stem":"What is the primary route of entry for Naegleria fowleri in humans?","options":[{"id":"a","text":"Ingestion of contaminated food"},{"id":"b","text":"Inhalation through the nose"},{"id":"c","text":"Skin contact with contaminated water"},{"id":"d","text":"Inoculation through insect bites"}],"answerId":"b","explanation":"Naegleria fowleri enters the body through the nose during swimming in warm freshwater, leading to primary amoebic meningoencephalitis.","kind":"recall","origin":"ai"},{"id":"free-living-nonpathogenic-amoebae~ai-1","moduleId":"free-living-nonpathogenic-amoebae","stem":"Which organism is primarily responsible for keratitis in contact lens wearers?","options":[{"id":"a","text":"Entamoeba histolytica"},{"id":"b","text":"Acanthamoeba"},{"id":"c","text":"Balamuthia mandrillaris"},{"id":"d","text":"Naegleria fowleri"}],"answerId":"b","explanation":"Acanthamoeba is known to cause keratitis, especially in individuals with poor contact lens hygiene.","kind":"recall","origin":"ai"},{"id":"free-living-nonpathogenic-amoebae~ai-2","moduleId":"free-living-nonpathogenic-amoebae","stem":"In a healthy young swimmer presenting with acute meningoencephalitis, which organism is most likely responsible?","options":[{"id":"a","text":"Acanthamoeba"},{"id":"b","text":"Balamuthia mandrillaris"},{"id":"c","text":"Entamoeba coli"},{"id":"d","text":"Naegleria fowleri"}],"answerId":"d","explanation":"Naegleria fowleri is the causative agent of primary amoebic meningoencephalitis in healthy individuals exposed to warm freshwater.","kind":"clinical","origin":"ai"},{"id":"free-living-nonpathogenic-amoebae~ai-3","moduleId":"free-living-nonpathogenic-amoebae","stem":"What is a distinguishing feature of non-pathogenic intestinal amoebae compared to Entamoeba histolytica?","options":[{"id":"a","text":"Presence of motile trophozoites"},{"id":"b","text":"Ingestion of red blood cells"},{"id":"c","text":"Formation of cysts"},{"id":"d","text":"Size of cysts and nuclear structure"}],"answerId":"d","explanation":"Non-pathogenic amoebae can be distinguished by their cyst size and nuclear structure, as well as the absence of ingested red blood cells.","kind":"trap","origin":"ai"},{"id":"free-living-nonpathogenic-amoebae~ai-4","moduleId":"free-living-nonpathogenic-amoebae","stem":"Which of the following findings is characteristic of Acanthamoeba infection in immunocompromised patients?","options":[{"id":"a","text":"Acute meningoencephalitis"},{"id":"b","text":"Chronic granulomatous encephalitis"},{"id":"c","text":"Keratitis"},{"id":"d","text":"Presence of motile trophozoites in CSF"}],"answerId":"b","explanation":"Acanthamoeba can cause chronic granulomatous encephalitis, particularly in immunocompromised individuals.","kind":"recall","origin":"ai"},{"id":"free-living-nonpathogenic-amoebae~ai-5","moduleId":"free-living-nonpathogenic-amoebae","stem":"How does the mechanism of Acanthamoeba differ from Naegleria fowleri in causing CNS infections?","options":[{"id":"a","text":"Acanthamoeba causes acute infections, Naegleria causes chronic"},{"id":"b","text":"Acanthamoeba is transmitted through the nose, Naegleria through the bloodstream"},{"id":"c","text":"Acanthamoeba primarily affects immunocompromised hosts, Naegleria affects healthy individuals"},{"id":"d","text":"Acanthamoeba causes keratitis, Naegleria does not"}],"answerId":"c","explanation":"Acanthamoeba typically causes chronic granulomatous encephalitis in immunocompromised patients, while Naegleria fowleri causes acute primary amoebic meningoencephalitis in healthy individuals.","kind":"integration","linkedModuleIds":["entamoeba-histolytica-amoebiasis"],"origin":"ai"},{"id":"free-living-nonpathogenic-amoebae~ai-6","moduleId":"free-living-nonpathogenic-amoebae","stem":"Which characteristic of Entamoeba coli helps differentiate it from Entamoeba histolytica?","options":[{"id":"a","text":"Presence of cysts"},{"id":"b","text":"Ingestion of red blood cells"},{"id":"c","text":"Size of cysts"},{"id":"d","text":"Motility of trophozoites"}],"answerId":"c","explanation":"Entamoeba coli can be differentiated from Entamoeba histolytica by the size of its cysts, which are larger and have a different nuclear structure.","kind":"integration","linkedModuleIds":["protozoa-classification-biology"],"origin":"ai"}],"liver-flukes-cholangiocarcinoma":[{"id":"liver-flukes-cholangiocarcinoma~ai-0","moduleId":"liver-flukes-cholangiocarcinoma","stem":"What is the primary mode of transmission for Opisthorchis viverrini?","options":[{"id":"a","text":"Consumption of undercooked freshwater fish"},{"id":"b","text":"Contact with contaminated water"},{"id":"c","text":"Ingestion of contaminated vegetables"},{"id":"d","text":"Inhalation of infected aerosols"}],"answerId":"a","explanation":"Opisthorchis viverrini is transmitted primarily through the consumption of undercooked freshwater fish containing the metacercariae.","kind":"recall","origin":"ai"},{"id":"liver-flukes-cholangiocarcinoma~ai-1","moduleId":"liver-flukes-cholangiocarcinoma","stem":"Which of the following findings is most indicative of cholangiocarcinoma in a patient with a history of raw fish consumption?","options":[{"id":"a","text":"Operculated fluke eggs on stool microscopy"},{"id":"b","text":"RUQ discomfort and hepatomegaly"},{"id":"c","text":"Elevated alkaline phosphatase levels"},{"id":"d","text":"Bile duct mass on imaging"}],"answerId":"d","explanation":"A bile duct mass on imaging is a strong indicator of cholangiocarcinoma, especially in the context of chronic Opisthorchis infection.","kind":"clinical","origin":"ai"},{"id":"liver-flukes-cholangiocarcinoma~ai-2","moduleId":"liver-flukes-cholangiocarcinoma","stem":"Which mechanism explains the carcinogenic effect of Opisthorchis viverrini?","options":[{"id":"a","text":"Direct invasion of bile duct epithelium"},{"id":"b","text":"Chronic inflammation leading to dysplasia"},{"id":"c","text":"Production of carcinogenic metabolites"},{"id":"d","text":"Immunosuppression of host defenses"}],"answerId":"b","explanation":"Chronic inflammation caused by Opisthorchis viverrini leads to dysplasia and subsequent development of cholangiocarcinoma.","kind":"mechanism","origin":"ai"},{"id":"liver-flukes-cholangiocarcinoma~ai-3","moduleId":"liver-flukes-cholangiocarcinoma","stem":"What is the most common diagnostic method for identifying Opisthorchis viverrini infection?","options":[{"id":"a","text":"Serological testing"},{"id":"b","text":"Stool microscopy for eggs"},{"id":"c","text":"Ultrasound imaging"},{"id":"d","text":"Liver biopsy"}],"answerId":"b","explanation":"Stool microscopy for operculated fluke eggs is the most common diagnostic method for identifying Opisthorchis viverrini infection.","kind":"recall","origin":"ai"},{"id":"liver-flukes-cholangiocarcinoma~ai-4","moduleId":"liver-flukes-cholangiocarcinoma","stem":"In endemic regions, what is a major preventable cause of cholangiocarcinoma?","options":[{"id":"a","text":"Chronic hepatitis B infection"},{"id":"b","text":"Alcohol consumption"},{"id":"c","text":"Chronic Opisthorchis viverrini infection"},{"id":"d","text":"Obesity"}],"answerId":"c","explanation":"Chronic Opisthorchis viverrini infection from eating raw freshwater fish is a major, preventable cause of cholangiocarcinoma in endemic regions.","kind":"trap","origin":"ai"},{"id":"liver-flukes-cholangiocarcinoma~ai-5","moduleId":"liver-flukes-cholangiocarcinoma","stem":"How does chronic biliary fluke infestation lead to recurrent cholangitis?","options":[{"id":"a","text":"By causing direct bile duct obstruction"},{"id":"b","text":"Through the formation of gallstones"},{"id":"c","text":"By inducing periductal inflammation"},{"id":"d","text":"By promoting bacterial overgrowth"}],"answerId":"c","explanation":"Chronic biliary fluke infestation induces periductal inflammation, which can lead to recurrent cholangitis.","kind":"mechanism","origin":"ai"},{"id":"liver-flukes-cholangiocarcinoma~ai-6","moduleId":"liver-flukes-cholangiocarcinoma","stem":"Which of the following is a common complication of chronic Opisthorchis viverrini infection?","options":[{"id":"a","text":"Hepatocellular carcinoma"},{"id":"b","text":"Cholecystitis"},{"id":"c","text":"Cholangitis"},{"id":"d","text":"Pancreatitis"}],"answerId":"c","explanation":"Cholangitis is a common complication of chronic Opisthorchis viverrini infection due to bile duct obstruction and inflammation.","kind":"clinical","origin":"ai"},{"id":"liver-flukes-cholangiocarcinoma~ai-7","moduleId":"liver-flukes-cholangiocarcinoma","stem":"How are liver flukes like Opisthorchis viverrini and Clonorchis sinensis similar in their pathology?","options":[{"id":"a","text":"Both cause hepatocellular carcinoma"},{"id":"b","text":"Both lead to cholangiocarcinoma through chronic inflammation"},{"id":"c","text":"Both are transmitted via contaminated water"},{"id":"d","text":"Both are treated with the same medication"}],"answerId":"b","explanation":"Both Opisthorchis viverrini and Clonorchis sinensis lead to cholangiocarcinoma through chronic inflammation of the bile ducts.","kind":"integration","linkedModuleIds":["hepatocellular-carcinoma-liver-tumors"],"origin":"ai"},{"id":"liver-flukes-cholangiocarcinoma~ai-8","moduleId":"liver-flukes-cholangiocarcinoma","stem":"What is a key difference between the transmission of Opisthorchis viverrini and Fasciola hepatica?","options":[{"id":"a","text":"One is transmitted via fish, the other via aquatic plants"},{"id":"b","text":"Both are transmitted through raw fish"},{"id":"c","text":"Both are transmitted through contaminated water"},{"id":"d","text":"One causes cholangiocarcinoma, the other does not"}],"answerId":"a","explanation":"Opisthorchis viverrini is transmitted via raw fish, while Fasciola hepatica is transmitted through aquatic plants like watercress.","kind":"integration","linkedModuleIds":["trematodes-flukes-overview"],"origin":"ai"}],"gnathostomiasis":[{"id":"gnathostomiasis~ai-0","moduleId":"gnathostomiasis","stem":"What is the primary mode of transmission for Gnathostoma spinigerum?","options":[{"id":"a","text":"Consumption of raw freshwater fish"},{"id":"b","text":"Inhalation of contaminated water"},{"id":"c","text":"Contact with infected soil"},{"id":"d","text":"Bite from an infected mosquito"}],"answerId":"a","explanation":"Gnathostoma spinigerum is primarily transmitted through the consumption of raw or undercooked freshwater fish.","kind":"recall","origin":"ai"},{"id":"gnathostomiasis~ai-1","moduleId":"gnathostomiasis","stem":"Which clinical finding is most characteristic of gnathostomiasis?","options":[{"id":"a","text":"Persistent fever"},{"id":"b","text":"Intermittent migratory subcutaneous swellings"},{"id":"c","text":"Cough with hemoptysis"},{"id":"d","text":"Abdominal pain with diarrhea"}],"answerId":"b","explanation":"Intermittent migratory subcutaneous swellings are a hallmark of gnathostomiasis due to the wandering larva.","kind":"recall","origin":"ai"},{"id":"gnathostomiasis~ai-2","moduleId":"gnathostomiasis","stem":"What laboratory finding is commonly associated with gnathostomiasis?","options":[{"id":"a","text":"Leukopenia"},{"id":"b","text":"Thrombocytopenia"},{"id":"c","text":"Eosinophilia"},{"id":"d","text":"Hyperglycemia"}],"answerId":"c","explanation":"Eosinophilia is a common laboratory finding in patients with gnathostomiasis due to the immune response to the migrating larvae.","kind":"recall","origin":"ai"},{"id":"gnathostomiasis~ai-3","moduleId":"gnathostomiasis","stem":"Why is stool microscopy not useful in diagnosing gnathostomiasis?","options":[{"id":"a","text":"Eggs are not produced in human hosts"},{"id":"b","text":"Stool samples are often contaminated"},{"id":"c","text":"The larvae are too small to detect"},{"id":"d","text":"The disease is too rare for stool testing"}],"answerId":"a","explanation":"Humans are a dead-end host for Gnathostoma spinigerum, so no eggs are produced, making stool microscopy ineffective for diagnosis.","kind":"trap","origin":"ai"},{"id":"gnathostomiasis~ai-4","moduleId":"gnathostomiasis","stem":"What is the treatment of choice for gnathostomiasis?","options":[{"id":"a","text":"Praziquantel"},{"id":"b","text":"Albendazole"},{"id":"c","text":"Ivermectin"},{"id":"d","text":"Metronidazole"}],"answerId":"b","explanation":"Albendazole is one of the primary treatments for gnathostomiasis, along with ivermectin in some cases.","kind":"recall","origin":"ai"},{"id":"gnathostomiasis~ai-5","moduleId":"gnathostomiasis","stem":"A patient presents with eosinophilic meningitis after consuming raw fish. Which other condition should be considered in the differential diagnosis?","options":[{"id":"a","text":"Toxocariasis"},{"id":"b","text":"Cysticercosis"},{"id":"c","text":"Schistosomiasis"},{"id":"d","text":"Giardiasis"}],"answerId":"a","explanation":"Toxocariasis can also present with eosinophilic meningitis, making it a relevant differential diagnosis in this context.","kind":"integration","linkedModuleIds":["toxocariasis-larva-migrans"],"origin":"ai"},{"id":"gnathostomiasis~ai-6","moduleId":"gnathostomiasis","stem":"Which symptom would differentiate CNS gnathostomiasis from other causes of eosinophilic meningitis?","options":[{"id":"a","text":"Ocular symptoms"},{"id":"b","text":"Severe headache"},{"id":"c","text":"Nausea and vomiting"},{"id":"d","text":"Fever"}],"answerId":"a","explanation":"Ocular symptoms can occur with CNS gnathostomiasis due to larval migration, distinguishing it from other causes of eosinophilic meningitis.","kind":"integration","linkedModuleIds":["angiostrongyliasis-eosinophilic-meningitis"],"origin":"ai"}],"anisakiasis":[{"id":"anisakiasis~ai-0","moduleId":"anisakiasis","stem":"What is the primary mode of transmission for Anisakis to humans?","options":[{"id":"a","text":"Raw freshwater fish"},{"id":"b","text":"Raw saltwater fish"},{"id":"c","text":"Contaminated water"},{"id":"d","text":"Insect bites"}],"answerId":"b","explanation":"Humans acquire Anisakis larvae by consuming raw or undercooked saltwater fish or squid.","kind":"recall","origin":"ai"},{"id":"anisakiasis~ai-1","moduleId":"anisakiasis","stem":"Which clinical finding is most characteristic of gastric anisakiasis?","options":[{"id":"a","text":"Lower abdominal pain"},{"id":"b","text":"Severe epigastric pain"},{"id":"c","text":"Urticaria"},{"id":"d","text":"Eosinophilia"}],"answerId":"b","explanation":"Gastric anisakiasis typically presents with acute severe epigastric pain after eating raw marine fish.","kind":"recall","origin":"ai"},{"id":"anisakiasis~ai-2","moduleId":"anisakiasis","stem":"What is the mechanism by which Anisakis causes an allergic reaction in some individuals?","options":[{"id":"a","text":"Direct tissue invasion"},{"id":"b","text":"IgE-mediated response"},{"id":"c","text":"Toxin release"},{"id":"d","text":"Bacterial infection"}],"answerId":"b","explanation":"Anisakis can provoke IgE-mediated allergic reactions, leading to symptoms like urticaria or anaphylaxis.","kind":"mechanism","origin":"ai"},{"id":"anisakiasis~ai-3","moduleId":"anisakiasis","stem":"Which of the following is a common diagnostic method for anisakiasis?","options":[{"id":"a","text":"Serum antibody testing"},{"id":"b","text":"Endoscopy"},{"id":"c","text":"Ultrasound"},{"id":"d","text":"CT scan"}],"answerId":"b","explanation":"Endoscopy allows for direct visualization and potential removal of the Anisakis larva from the gastric mucosa.","kind":"recall","origin":"ai"},{"id":"anisakiasis~ai-4","moduleId":"anisakiasis","stem":"A patient presents with lower abdominal pain after consuming sushi. What condition should be suspected?","options":[{"id":"a","text":"Appendicitis"},{"id":"b","text":"Intestinal anisakiasis"},{"id":"c","text":"Cholecystitis"},{"id":"d","text":"Pancreatitis"}],"answerId":"b","explanation":"Lower abdominal pain after eating sushi suggests intestinal anisakiasis, which can mimic appendicitis.","kind":"clinical","origin":"ai"},{"id":"anisakiasis~ai-5","moduleId":"anisakiasis","stem":"What is a key distinguishing feature of Anisakis compared to freshwater fish parasites?","options":[{"id":"a","text":"Acquired from raw freshwater fish"},{"id":"b","text":"Causes eosinophilia"},{"id":"c","text":"Associated with marine mammals"},{"id":"d","text":"Transmitted by insect bites"}],"answerId":"c","explanation":"Anisakis is specifically acquired from raw or undercooked saltwater fish, unlike freshwater parasites.","kind":"trap","origin":"ai"},{"id":"anisakiasis~ai-6","moduleId":"anisakiasis","stem":"How does the treatment of anisakiasis differ from that of gnathostomiasis?","options":[{"id":"a","text":"Endoscopic removal of larvae"},{"id":"b","text":"Antiparasitic medications"},{"id":"c","text":"Surgical intervention"},{"id":"d","text":"Supportive care only"}],"answerId":"a","explanation":"Anisakiasis is primarily treated through endoscopic removal of the larvae, while gnathostomiasis may require different management.","kind":"integration","linkedModuleIds":["gnathostomiasis"],"origin":"ai"},{"id":"anisakiasis~ai-7","moduleId":"anisakiasis","stem":"Which of the following findings would NOT be expected in a patient with anisakiasis?","options":[{"id":"a","text":"Eosinophilic granuloma"},{"id":"b","text":"Larva seen on endoscopy"},{"id":"c","text":"Chronic cough"},{"id":"d","text":"Severe epigastric pain"}],"answerId":"c","explanation":"Chronic cough is not a typical finding in anisakiasis, whereas the other options are associated with the condition.","kind":"trap","origin":"ai"}],"helminth-classification-overview":[{"id":"helminth-classification-overview~ai-0","moduleId":"helminth-classification-overview","stem":"Which of the following helminths is characterized by having separate sexes?","options":[{"id":"a","text":"Schistosoma"},{"id":"b","text":"Fasciola"},{"id":"c","text":"Ascaris"},{"id":"d","text":"Clonorchis"}],"answerId":"c","explanation":"Ascaris is a nematode, which is known for having separate sexes, unlike most trematodes which are hermaphroditic.","kind":"recall","origin":"ai"},{"id":"helminth-classification-overview~ai-1","moduleId":"helminth-classification-overview","stem":"What is the primary diagnostic method for identifying soil-transmitted helminths?","options":[{"id":"a","text":"Blood culture"},{"id":"b","text":"Stool examination for eggs"},{"id":"c","text":"Imaging studies"},{"id":"d","text":"Skin scraping"}],"answerId":"b","explanation":"Soil-transmitted helminths are primarily diagnosed by finding characteristic eggs in stool samples.","kind":"recall","origin":"ai"},{"id":"helminth-classification-overview~ai-2","moduleId":"helminth-classification-overview","stem":"Which helminth is known to require a snail as an intermediate host?","options":[{"id":"a","text":"Ascaris"},{"id":"b","text":"Schistosoma"},{"id":"c","text":"Taenia"},{"id":"d","text":"Enterobius"}],"answerId":"b","explanation":"Schistosoma is a trematode that requires a snail as its first intermediate host for its lifecycle.","kind":"recall","origin":"ai"},{"id":"helminth-classification-overview~ai-3","moduleId":"helminth-classification-overview","stem":"A patient presents with eosinophilia and a history of travel to areas with poor sanitation. Which type of helminth is likely responsible?","options":[{"id":"a","text":"Cestode"},{"id":"b","text":"Trematode"},{"id":"c","text":"Nematode"},{"id":"d","text":"Protozoan"}],"answerId":"c","explanation":"Eosinophilia is commonly associated with tissue-migrating nematodes, which are prevalent in areas with poor sanitation.","kind":"clinical","origin":"ai"},{"id":"helminth-classification-overview~ai-4","moduleId":"helminth-classification-overview","stem":"Which of the following statements is true regarding the reproductive characteristics of helminths?","options":[{"id":"a","text":"All helminths are hermaphroditic."},{"id":"b","text":"Nematodes have separate sexes."},{"id":"c","text":"Trematodes are always dioecious."},{"id":"d","text":"Cestodes reproduce asexually."}],"answerId":"b","explanation":"Nematodes are characterized by having separate sexes, while most trematodes are hermaphroditic, with the exception of Schistosoma.","kind":"trap","origin":"ai"},{"id":"helminth-classification-overview~ai-5","moduleId":"helminth-classification-overview","stem":"A patient is diagnosed with ascariasis. Which helminth is responsible for this condition?","options":[{"id":"a","text":"Enterobius vermicularis"},{"id":"b","text":"Ascaris lumbricoides"},{"id":"c","text":"Strongyloides stercoralis"},{"id":"d","text":"Trichuris trichiura"}],"answerId":"b","explanation":"Ascariasis is specifically caused by Ascaris lumbricoides, a type of soil-transmitted nematode.","kind":"integration","linkedModuleIds":["ascariasis-large-roundworm"],"origin":"ai"},{"id":"helminth-classification-overview~ai-6","moduleId":"helminth-classification-overview","stem":"Which helminth is most likely to cause intestinal obstruction due to its size?","options":[{"id":"a","text":"Hymenolepis nana"},{"id":"b","text":"Ascaris lumbricoides"},{"id":"c","text":"Fasciola hepatica"},{"id":"d","text":"Diphyllobothrium latum"}],"answerId":"b","explanation":"Ascaris lumbricoides can grow quite large and may lead to intestinal obstruction in infected individuals.","kind":"integration","linkedModuleIds":["intestinal-roundworms-phasmid"],"origin":"ai"}],"blood-apicomplexa-malaria-babesia":[{"id":"blood-apicomplexa-malaria-babesia~ai-0","moduleId":"blood-apicomplexa-malaria-babesia","stem":"What is the definitive host for Plasmodium species responsible for malaria?","options":[{"id":"a","text":"Culex mosquito"},{"id":"b","text":"Aedes mosquito"},{"id":"c","text":"Anopheles mosquito"},{"id":"d","text":"Tsetse fly"}],"answerId":"c","explanation":"The Anopheles mosquito is the definitive host and vector for Plasmodium species, which cause malaria.","kind":"recall","origin":"ai"},{"id":"blood-apicomplexa-malaria-babesia~ai-1","moduleId":"blood-apicomplexa-malaria-babesia","stem":"Which Plasmodium species is most associated with severe malaria complications?","options":[{"id":"a","text":"Plasmodium vivax"},{"id":"b","text":"Plasmodium ovale"},{"id":"c","text":"Plasmodium malariae"},{"id":"d","text":"Plasmodium falciparum"}],"answerId":"d","explanation":"Plasmodium falciparum is known for causing severe malaria, including cerebral malaria and high parasitaemia.","kind":"recall","origin":"ai"},{"id":"blood-apicomplexa-malaria-babesia~ai-2","moduleId":"blood-apicomplexa-malaria-babesia","stem":"What is the primary mechanism of action of primaquine in malaria treatment?","options":[{"id":"a","text":"Inhibits heme polymerization"},{"id":"b","text":"Clears blood-stage parasites"},{"id":"c","text":"Kills dormant liver hypnozoites"},{"id":"d","text":"Inhibits protein synthesis"}],"answerId":"c","explanation":"Primaquine specifically targets and kills the dormant liver hypnozoites of Plasmodium vivax and ovale to prevent relapse.","kind":"mechanism","origin":"ai"},{"id":"blood-apicomplexa-malaria-babesia~ai-3","moduleId":"blood-apicomplexa-malaria-babesia","stem":"A patient presents with cyclical fever, splenomegaly, and hemolytic anemia after traveling to a malaria-endemic region. Which diagnostic test is the gold standard?","options":[{"id":"a","text":"Rapid antigen test"},{"id":"b","text":"Blood film (thick and thin)"},{"id":"c","text":"Serology"},{"id":"d","text":"PCR"}],"answerId":"b","explanation":"The blood film (both thick and thin) is the gold standard for diagnosing malaria and determining species.","kind":"clinical","origin":"ai"},{"id":"blood-apicomplexa-malaria-babesia~ai-4","moduleId":"blood-apicomplexa-malaria-babesia","stem":"Which of the following findings is characteristic of Babesia infection?","options":[{"id":"a","text":"Crescentic gametocytes"},{"id":"b","text":"Maltese cross in red cells"},{"id":"c","text":"Cyclical fever every 48 hours"},{"id":"d","text":"Severe anemia with blackwater fever"}],"answerId":"b","explanation":"Babesia infection is characterized by the presence of Maltese cross formations in red blood cells.","kind":"recall","origin":"ai"},{"id":"blood-apicomplexa-malaria-babesia~ai-5","moduleId":"blood-apicomplexa-malaria-babesia","stem":"Which statement about malaria treatment is correct?","options":[{"id":"a","text":"ACTs cure all forms of malaria completely"},{"id":"b","text":"Primaquine is used for all malaria species"},{"id":"c","text":"G6PD status must be checked before primaquine"},{"id":"d","text":"Chloroquine is effective against hypnozoites"}],"answerId":"c","explanation":"G6PD status must be checked before administering primaquine, as it can cause hemolysis in G6PD-deficient patients.","kind":"trap","origin":"ai"},{"id":"blood-apicomplexa-malaria-babesia~ai-6","moduleId":"blood-apicomplexa-malaria-babesia","stem":"How does the transmission of Babesia differ from that of Plasmodium species?","options":[{"id":"a","text":"Babesia is transmitted by mosquitoes"},{"id":"b","text":"Plasmodium is transmitted by ticks"},{"id":"c","text":"Babesia is transmitted by ticks"},{"id":"d","text":"Plasmodium is transmitted by fleas"}],"answerId":"c","explanation":"Babesia is transmitted by ticks, while Plasmodium species are transmitted by Anopheles mosquitoes.","kind":"integration","linkedModuleIds":["medical-entomology-vectors"],"origin":"ai"},{"id":"blood-apicomplexa-malaria-babesia~ai-7","moduleId":"blood-apicomplexa-malaria-babesia","stem":"Which of the following is a shared characteristic of Plasmodium and Babesia infections?","options":[{"id":"a","text":"Both cause cyclical fever"},{"id":"b","text":"Both are transmitted by mosquitoes"},{"id":"c","text":"Both have dormant liver stages"},{"id":"d","text":"Both are treated with primaquine"}],"answerId":"a","explanation":"Both Plasmodium and Babesia infections can cause cyclical fever, although their transmission and treatment differ.","kind":"integration","linkedModuleIds":["mosquito-borne-diseases"],"origin":"ai"}],"angiostrongyliasis-eosinophilic-meningitis":[{"id":"angiostrongyliasis-eosinophilic-meningitis~ai-0","moduleId":"angiostrongyliasis-eosinophilic-meningitis","stem":"What is the primary host for Angiostrongylus cantonensis?","options":[{"id":"a","text":"Humans"},{"id":"b","text":"Rats"},{"id":"c","text":"Snails"},{"id":"d","text":"Frogs"}],"answerId":"b","explanation":"Rats are the definitive host for Angiostrongylus cantonensis, while humans are accidental hosts.","kind":"recall","origin":"ai"},{"id":"angiostrongyliasis-eosinophilic-meningitis~ai-1","moduleId":"angiostrongyliasis-eosinophilic-meningitis","stem":"Which of the following is a key diagnostic finding in eosinophilic meningitis caused by Angiostrongylus cantonensis?","options":[{"id":"a","text":"Lymphocytes in CSF"},{"id":"b","text":"Eosinophils in CSF"},{"id":"c","text":"Neutrophils in CSF"},{"id":"d","text":"Bacteria in CSF"}],"answerId":"b","explanation":"Eosinophils in the CSF are a hallmark of eosinophilic meningitis due to Angiostrongylus cantonensis.","kind":"recall","origin":"ai"},{"id":"angiostrongyliasis-eosinophilic-meningitis~ai-2","moduleId":"angiostrongyliasis-eosinophilic-meningitis","stem":"What is the mechanism by which Angiostrongylus cantonensis causes eosinophilic meningitis?","options":[{"id":"a","text":"Direct infection of neurons"},{"id":"b","text":"Larvae die in the brain"},{"id":"c","text":"Bacterial infection"},{"id":"d","text":"Immune response to eggs"}],"answerId":"b","explanation":"The larvae migrate to the brain, die there, and provoke an eosinophilic inflammatory response.","kind":"mechanism","origin":"ai"},{"id":"angiostrongyliasis-eosinophilic-meningitis~ai-3","moduleId":"angiostrongyliasis-eosinophilic-meningitis","stem":"A patient presents with headache, neck stiffness, and eosinophils in the CSF after consuming raw snails. What is the most appropriate management?","options":[{"id":"a","text":"Aggressive anti-helminthic therapy"},{"id":"b","text":"Supportive care"},{"id":"c","text":"Immediate surgery"},{"id":"d","text":"High-dose corticosteroids"}],"answerId":"b","explanation":"Management is largely supportive, as aggressive treatment can worsen inflammation.","kind":"trap","origin":"ai"},{"id":"angiostrongyliasis-eosinophilic-meningitis~ai-4","moduleId":"angiostrongyliasis-eosinophilic-meningitis","stem":"Which symptom is most characteristic of eosinophilic meningitis due to Angiostrongylus cantonensis?","options":[{"id":"a","text":"Fever"},{"id":"b","text":"Rash"},{"id":"c","text":"Prominent paraesthesiae"},{"id":"d","text":"Severe vomiting"}],"answerId":"c","explanation":"Prominent paraesthesiae or hyperaesthesia is a common symptom due to larval migration in the CNS.","kind":"recall","origin":"ai"},{"id":"angiostrongyliasis-eosinophilic-meningitis~ai-5","moduleId":"angiostrongyliasis-eosinophilic-meningitis","stem":"How does eosinophilic meningitis due to Angiostrongylus cantonensis differ from that caused by Gnathostoma?","options":[{"id":"a","text":"Different CSF findings"},{"id":"b","text":"Different exposure history"},{"id":"c","text":"Different treatment protocols"},{"id":"d","text":"Different definitive hosts"}],"answerId":"b","explanation":"The exposure history differs, as Angiostrongylus is linked to snails/slugs, while Gnathostoma is linked to raw freshwater fish.","kind":"integration","linkedModuleIds":["gnathostomiasis"],"origin":"ai"},{"id":"angiostrongyliasis-eosinophilic-meningitis~ai-6","moduleId":"angiostrongyliasis-eosinophilic-meningitis","stem":"In managing eosinophilic meningitis, what is a critical consideration when treating with corticosteroids?","options":[{"id":"a","text":"They should be used aggressively"},{"id":"b","text":"They can worsen larval death"},{"id":"c","text":"They help reduce inflammation"},{"id":"d","text":"They are contraindicated"}],"answerId":"c","explanation":"Corticosteroids can help reduce inflammation but must be used cautiously to avoid exacerbating the condition.","kind":"trap","origin":"ai"},{"id":"angiostrongyliasis-eosinophilic-meningitis~ai-7","moduleId":"angiostrongyliasis-eosinophilic-meningitis","stem":"What is the primary differential diagnosis for eosinophilic meningitis in Southeast Asia?","options":[{"id":"a","text":"Toxoplasmosis"},{"id":"b","text":"Cysticercosis"},{"id":"c","text":"Gnathostomiasis"},{"id":"d","text":"Neurosyphilis"}],"answerId":"c","explanation":"Gnathostomiasis is a key differential, as it also presents with eosinophilic pleocytosis in the CSF.","kind":"integration","linkedModuleIds":["toxocariasis-larva-migrans"],"origin":"ai"}],"toxoplasmosis":[{"id":"toxoplasmosis~ai-0","moduleId":"toxoplasmosis","stem":"What is the definitive host of Toxoplasma gondii?","options":[{"id":"a","text":"Dog"},{"id":"b","text":"Human"},{"id":"c","text":"Cat"},{"id":"d","text":"Pig"}],"answerId":"c","explanation":"The definitive host of Toxoplasma gondii is the cat, where the sexual cycle occurs.","kind":"recall","origin":"ai"},{"id":"toxoplasmosis~ai-1","moduleId":"toxoplasmosis","stem":"Which of the following is a classic triad of congenital toxoplasmosis?","options":[{"id":"a","text":"Chorioretinitis, hydrocephalus, intracranial calcifications"},{"id":"b","text":"Fever, rash, lymphadenopathy"},{"id":"c","text":"Hepatosplenomegaly, jaundice, anemia"},{"id":"d","text":"Seizures, ataxia, developmental delay"}],"answerId":"a","explanation":"The classic triad of congenital toxoplasmosis includes chorioretinitis, hydrocephalus, and intracranial calcifications.","kind":"recall","origin":"ai"},{"id":"toxoplasmosis~ai-2","moduleId":"toxoplasmosis","stem":"What is the mechanism of reactivation of Toxoplasma in immunocompromised patients?","options":[{"id":"a","text":"Ingestion of oocysts"},{"id":"b","text":"Ingestion of tissue cysts"},{"id":"c","text":"Failure of cell-mediated immunity"},{"id":"d","text":"Direct contact with cats"}],"answerId":"c","explanation":"Reactivation occurs when cell-mediated immunity fails, allowing latent bradyzoite cysts to reactivate.","kind":"mechanism","origin":"ai"},{"id":"toxoplasmosis~ai-3","moduleId":"toxoplasmosis","stem":"A patient presents with multiple ring-enhancing lesions in the brain. What is the most likely diagnosis?","options":[{"id":"a","text":"CNS lymphoma"},{"id":"b","text":"Toxoplasma encephalitis"},{"id":"c","text":"Tuberculoma"},{"id":"d","text":"Brain abscess"}],"answerId":"b","explanation":"Multiple ring-enhancing lesions in a patient with advanced HIV are characteristic of Toxoplasma encephalitis.","kind":"clinical","origin":"ai"},{"id":"toxoplasmosis~ai-4","moduleId":"toxoplasmosis","stem":"What is the primary mode of transmission of Toxoplasma gondii to humans?","options":[{"id":"a","text":"Ingestion of oocysts from cat feces"},{"id":"b","text":"Direct contact with infected cats"},{"id":"c","text":"Inhalation of oocysts"},{"id":"d","text":"Blood transfusion from infected donors"}],"answerId":"a","explanation":"Humans primarily acquire Toxoplasma through ingestion of oocysts from cat feces.","kind":"recall","origin":"ai"},{"id":"toxoplasmosis~ai-5","moduleId":"toxoplasmosis","stem":"Which of the following statements about Toxoplasma infection is true?","options":[{"id":"a","text":"It is only acquired from contact with cats"},{"id":"b","text":"It can be transmitted through undercooked meat"},{"id":"c","text":"It is always symptomatic"},{"id":"d","text":"It cannot cause congenital infection"}],"answerId":"b","explanation":"Toxoplasma can be transmitted to humans through ingestion of tissue cysts in undercooked meat, in addition to oocysts from cat feces.","kind":"trap","origin":"ai"},{"id":"toxoplasmosis~ai-6","moduleId":"toxoplasmosis","stem":"How does Toxoplasma gondii relate to the classification of protozoa?","options":[{"id":"a","text":"It is a helminth"},{"id":"b","text":"It is an apicomplexan"},{"id":"c","text":"It is a flagellate"},{"id":"d","text":"It is a ciliate"}],"answerId":"b","explanation":"Toxoplasma gondii is classified as an apicomplexan, a group of protozoa characterized by their complex life cycles.","kind":"integration","linkedModuleIds":["protozoa-classification-biology"],"origin":"ai"},{"id":"toxoplasmosis~ai-7","moduleId":"toxoplasmosis","stem":"What is the primary prevention method for congenital toxoplasmosis during pregnancy?","options":[{"id":"a","text":"Vaccination against Toxoplasma"},{"id":"b","text":"Avoiding cat litter and undercooked meat"},{"id":"c","text":"Regular screening for Toxoplasma antibodies"},{"id":"d","text":"Using gloves when gardening"}],"answerId":"b","explanation":"Pregnant women should avoid cat litter and undercooked meat to prevent primary infection with Toxoplasma gondii.","kind":"integration","linkedModuleIds":["protozoa-classification-biology"],"origin":"ai"}],"ascariasis-large-roundworm":[{"id":"ascariasis-large-roundworm~ai-0","moduleId":"ascariasis-large-roundworm","stem":"What is the primary mode of transmission for Ascaris lumbricoides?","options":[{"id":"a","text":"Inhalation of larvae"},{"id":"b","text":"Contact with infected soil"},{"id":"c","text":"Ingestion of embryonated eggs"},{"id":"d","text":"Consumption of undercooked meat"}],"answerId":"c","explanation":"Ascaris lumbricoides is transmitted via the fecal-oral route, specifically through the ingestion of embryonated eggs from contaminated sources.","kind":"recall","origin":"ai"},{"id":"ascariasis-large-roundworm~ai-1","moduleId":"ascariasis-large-roundworm","stem":"Which clinical finding is associated with the larval migration phase of Ascaris lumbricoides?","options":[{"id":"a","text":"Abdominal pain"},{"id":"b","text":"Biliary obstruction"},{"id":"c","text":"Transient cough and eosinophilia"},{"id":"d","text":"Visible adult worm in stool"}],"answerId":"c","explanation":"During the larval migration phase, Ascaris lumbricoides can cause Löffler syndrome, characterized by a transient cough and eosinophilia.","kind":"clinical","origin":"ai"},{"id":"ascariasis-large-roundworm~ai-2","moduleId":"ascariasis-large-roundworm","stem":"What is the mechanism behind intestinal obstruction in heavy Ascaris infections?","options":[{"id":"a","text":"Larvae penetrate the gut wall"},{"id":"b","text":"Adult worms form a bolus"},{"id":"c","text":"Biliary obstruction occurs"},{"id":"d","text":"Eosinophilic infiltration of the intestine"}],"answerId":"b","explanation":"Heavy burdens of adult Ascaris worms can lead to intestinal obstruction due to the formation of a bolus.","kind":"mechanism","origin":"ai"},{"id":"ascariasis-large-roundworm~ai-3","moduleId":"ascariasis-large-roundworm","stem":"What type of eggs are characteristic of Ascaris lumbricoides in stool samples?","options":[{"id":"a","text":"Bile-stained, mammillated eggs"},{"id":"b","text":"Oval, smooth eggs"},{"id":"c","text":"Spindle-shaped eggs"},{"id":"d","text":"Transparent, unembryonated eggs"}],"answerId":"a","explanation":"Ascaris lumbricoides eggs are bile-stained and have a mammillated surface, which is a key diagnostic feature.","kind":"recall","origin":"ai"},{"id":"ascariasis-large-roundworm~ai-4","moduleId":"ascariasis-large-roundworm","stem":"A child presents with a cough, eosinophilia, and migratory lung infiltrates. What is the likely cause?","options":[{"id":"a","text":"Bacterial pneumonia"},{"id":"b","text":"Ascaris lumbricoides infection"},{"id":"c","text":"Asthma exacerbation"},{"id":"d","text":"Viral bronchitis"}],"answerId":"b","explanation":"The symptoms are consistent with Löffler syndrome caused by the larval migration of Ascaris lumbricoides.","kind":"clinical","origin":"ai"},{"id":"ascariasis-large-roundworm~ai-5","moduleId":"ascariasis-large-roundworm","stem":"Which statement about the life cycle of Ascaris lumbricoides is correct?","options":[{"id":"a","text":"Larvae remain in the gut after ingestion"},{"id":"b","text":"Larvae migrate to the lungs before maturing"},{"id":"c","text":"Adult worms are formed in the liver"},{"id":"d","text":"Eggs hatch in the bile duct"}],"answerId":"b","explanation":"Ascaris larvae undergo a lung migration after penetrating the gut wall, which is crucial for understanding its clinical presentation.","kind":"trap","origin":"ai"},{"id":"ascariasis-large-roundworm~ai-6","moduleId":"ascariasis-large-roundworm","stem":"How does the pathology of Ascaris lumbricoides relate to parasitic lung infections?","options":[{"id":"a","text":"Both cause eosinophilia due to gut infection"},{"id":"b","text":"Both involve larval migration through the lungs"},{"id":"c","text":"Both are transmitted via contaminated water"},{"id":"d","text":"Both lead to intestinal obstruction"}],"answerId":"b","explanation":"Ascaris lumbricoides and other parasitic lung infections share a common mechanism of larval migration through the lungs, leading to similar respiratory symptoms.","kind":"integration","linkedModuleIds":["parasitic-lung-infections"],"origin":"ai"},{"id":"ascariasis-large-roundworm~ai-7","moduleId":"ascariasis-large-roundworm","stem":"Which aspect of Ascaris lumbricoides life cycle is critical for understanding its classification among soil-transmitted helminths?","options":[{"id":"a","text":"Adult worms are found in the liver"},{"id":"b","text":"Eggs are ingested from contaminated water"},{"id":"c","text":"Larvae migrate through the lungs before maturing"},{"id":"d","text":"Infection occurs primarily in adults"}],"answerId":"c","explanation":"The larval migration through the lungs is a key feature that distinguishes Ascaris from other soil-transmitted helminths and is essential for its classification.","kind":"integration","linkedModuleIds":["intestinal-roundworms-phasmid"],"origin":"ai"}],"medical-mites-acarology":[{"id":"medical-mites-acarology~ai-0","moduleId":"medical-mites-acarology","stem":"What is the primary treatment for scabies caused by Sarcoptes scabiei?","options":[{"id":"a","text":"Topical permethrin"},{"id":"b","text":"Oral ivermectin"},{"id":"c","text":"Benzyl benzoate"},{"id":"d","text":"Crotamiton"}],"answerId":"a","explanation":"Topical permethrin is the first-line treatment for scabies, effectively killing the mites.","kind":"recall","origin":"ai"},{"id":"medical-mites-acarology~ai-1","moduleId":"medical-mites-acarology","stem":"Which of the following findings is characteristic of crusted (Norwegian) scabies?","options":[{"id":"a","text":"Intense nocturnal itching"},{"id":"b","text":"Thick, crusted skin"},{"id":"c","text":"Papular rash with burrows"},{"id":"d","text":"Localized eschar formation"}],"answerId":"b","explanation":"Crusted (Norwegian) scabies presents with thick, crusted skin due to hyperinfestation, often with minimal itching.","kind":"recall","origin":"ai"},{"id":"medical-mites-acarology~ai-2","moduleId":"medical-mites-acarology","stem":"What is the mechanism by which house dust mites trigger allergic reactions?","options":[{"id":"a","text":"Direct skin invasion"},{"id":"b","text":"Release of fecal allergens"},{"id":"c","text":"Bite-induced inflammation"},{"id":"d","text":"Transmission of pathogens"}],"answerId":"b","explanation":"House dust mites release fecal particles that act as allergens, triggering allergic rhinitis and asthma.","kind":"mechanism","origin":"ai"},{"id":"medical-mites-acarology~ai-3","moduleId":"medical-mites-acarology","stem":"A patient presents with fever, an eschar at the bite site, and lymphadenopathy after visiting rural Asia. What is the likely cause?","options":[{"id":"a","text":"Scabies"},{"id":"b","text":"Scrub typhus"},{"id":"c","text":"Demodex infestation"},{"id":"d","text":"House dust mite allergy"}],"answerId":"b","explanation":"The symptoms are consistent with scrub typhus, which is transmitted by trombiculid mites (chiggers).","kind":"clinical","origin":"ai"},{"id":"medical-mites-acarology~ai-4","moduleId":"medical-mites-acarology","stem":"Which of the following statements about crusted (Norwegian) scabies is true?","options":[{"id":"a","text":"It is always intensely itchy."},{"id":"b","text":"It can be mildly itchy in immunocompromised patients."},{"id":"c","text":"It is not contagious."},{"id":"d","text":"It is caused by Demodex mites."}],"answerId":"b","explanation":"Crusted scabies can present with mild itching despite a high mite burden, making it highly contagious.","kind":"trap","origin":"ai"},{"id":"medical-mites-acarology~ai-5","moduleId":"medical-mites-acarology","stem":"How do chigger mites contribute to the transmission of scrub typhus?","options":[{"id":"a","text":"By burrowing into the skin"},{"id":"b","text":"By acting as a vector for Orientia tsutsugamushi"},{"id":"c","text":"By causing allergic reactions"},{"id":"d","text":"By living in hair follicles"}],"answerId":"b","explanation":"Chigger mites serve as vectors for Orientia tsutsugamushi, the causative agent of scrub typhus.","kind":"recall","origin":"ai"},{"id":"medical-mites-acarology~ai-6","moduleId":"medical-mites-acarology","stem":"How do mites relate to the study of medical entomology?","options":[{"id":"a","text":"They are all vectors of malaria."},{"id":"b","text":"They are important allergens and parasites."},{"id":"c","text":"They only cause skin infections."},{"id":"d","text":"They are not vectors for any diseases."}],"answerId":"b","explanation":"Mites are significant in medical entomology as they can be allergens, parasites, and vectors for diseases.","kind":"integration","linkedModuleIds":["medical-entomology-vectors"],"origin":"ai"},{"id":"medical-mites-acarology~ai-7","moduleId":"medical-mites-acarology","stem":"What is a common clinical manifestation of Demodex mite infestation?","options":[{"id":"a","text":"Eschar formation"},{"id":"b","text":"Blepharitis"},{"id":"c","text":"Crusted skin lesions"},{"id":"d","text":"Intense itching"}],"answerId":"b","explanation":"Demodex mites are associated with blepharitis and rosacea-like dermatitis, not eschar formation or intense itching.","kind":"recall","origin":"ai"},{"id":"medical-mites-acarology~ai-8","moduleId":"medical-mites-acarology","stem":"Which mite is primarily responsible for causing allergic rhinitis and asthma in indoor environments?","options":[{"id":"a","text":"Sarcoptes scabiei"},{"id":"b","text":"Demodex folliculorum"},{"id":"c","text":"Dermatophagoides (house dust mite)"},{"id":"d","text":"Trombiculid mites"}],"answerId":"c","explanation":"House dust mites (Dermatophagoides) are significant indoor allergens that trigger allergic rhinitis and asthma.","kind":"recall","origin":"ai"}],"toxocariasis-larva-migrans":[{"id":"toxocariasis-larva-migrans~ai-0","moduleId":"toxocariasis-larva-migrans","stem":"What is the primary cause of eosinophilia in Toxocariasis?","options":[{"id":"a","text":"Bacterial infection"},{"id":"b","text":"Tissue-migrating larvae"},{"id":"c","text":"Viral infection"},{"id":"d","text":"Fungal infection"}],"answerId":"b","explanation":"Eosinophilia in Toxocariasis is primarily due to the immune response against tissue-migrating larvae.","kind":"recall","origin":"ai"},{"id":"toxocariasis-larva-migrans~ai-1","moduleId":"toxocariasis-larva-migrans","stem":"Which of the following is a key clinical feature of visceral larva migrans (VLM)?","options":[{"id":"a","text":"Creeping eruption"},{"id":"b","text":"Retinal granuloma"},{"id":"c","text":"Hepatomegaly"},{"id":"d","text":"Erythema nodosum"}],"answerId":"c","explanation":"Hepatomegaly is a prominent feature of visceral larva migrans caused by Toxocara larvae migrating through the liver.","kind":"clinical","origin":"ai"},{"id":"toxocariasis-larva-migrans~ai-2","moduleId":"toxocariasis-larva-migrans","stem":"How is Toxocariasis primarily diagnosed in humans?","options":[{"id":"a","text":"Stool examination for eggs"},{"id":"b","text":"Serological testing"},{"id":"c","text":"Biopsy of affected tissue"},{"id":"d","text":"Clinical symptoms alone"}],"answerId":"b","explanation":"Toxocariasis is diagnosed serologically since the larvae do not mature into egg-laying adults in humans.","kind":"trap","origin":"ai"},{"id":"toxocariasis-larva-migrans~ai-3","moduleId":"toxocariasis-larva-migrans","stem":"A child presents with leukocoria and a retinal mass. What is the most likely differential diagnosis?","options":[{"id":"a","text":"Retinoblastoma"},{"id":"b","text":"Ocular larva migrans"},{"id":"c","text":"Congenital cataract"},{"id":"d","text":"Chorioretinitis"}],"answerId":"b","explanation":"Ocular larva migrans can mimic retinoblastoma in children, presenting as a retinal mass.","kind":"clinical","origin":"ai"},{"id":"toxocariasis-larva-migrans~ai-4","moduleId":"toxocariasis-larva-migrans","stem":"Which of the following is a characteristic finding in cutaneous larva migrans?","options":[{"id":"a","text":"Serpiginous skin track"},{"id":"b","text":"Erythematous papules"},{"id":"c","text":"Vesicular lesions"},{"id":"d","text":"Ulcerated nodules"}],"answerId":"a","explanation":"Cutaneous larva migrans is characterized by an intensely itchy, serpiginous skin track due to animal hookworm larvae.","kind":"recall","origin":"ai"},{"id":"toxocariasis-larva-migrans~ai-5","moduleId":"toxocariasis-larva-migrans","stem":"How does Toxocara canis differ from Angiostrongylus in terms of host response?","options":[{"id":"a","text":"Both cause eosinophilia"},{"id":"b","text":"Only Toxocara causes eosinophilia"},{"id":"c","text":"Only Angiostrongylus causes eosinophilia"},{"id":"d","text":"Neither causes eosinophilia"}],"answerId":"a","explanation":"Both Toxocara canis and Angiostrongylus can lead to eosinophilia due to tissue migration in humans.","kind":"integration","linkedModuleIds":["angiostrongyliasis-eosinophilic-meningitis"],"origin":"ai"},{"id":"toxocariasis-larva-migrans~ai-6","moduleId":"toxocariasis-larva-migrans","stem":"What is the mechanism by which Toxocara larvae cause damage in humans?","options":[{"id":"a","text":"Direct tissue invasion"},{"id":"b","text":"Toxin release"},{"id":"c","text":"Immune-mediated damage"},{"id":"d","text":"Nutrient competition"}],"answerId":"c","explanation":"Toxocara larvae cause damage through immune-mediated mechanisms as the body responds to the migrating larvae.","kind":"mechanism","origin":"ai"},{"id":"toxocariasis-larva-migrans~ai-7","moduleId":"toxocariasis-larva-migrans","stem":"In which scenario would you expect negative stool microscopy for Toxocara?","options":[{"id":"a","text":"Infected with adult worms"},{"id":"b","text":"Infected with larvae only"},{"id":"c","text":"Recent treatment with albendazole"},{"id":"d","text":"Infection with other helminths"}],"answerId":"b","explanation":"Humans are dead-end hosts for Toxocara, so larvae do not produce eggs, leading to negative stool microscopy.","kind":"trap","origin":"ai"},{"id":"toxocariasis-larva-migrans~ai-8","moduleId":"toxocariasis-larva-migrans","stem":"A child with pica presents with eosinophilia and wheezing. What is the most likely diagnosis?","options":[{"id":"a","text":"Ascariasis"},{"id":"b","text":"Toxocariasis"},{"id":"c","text":"Strongyloidiasis"},{"id":"d","text":"Giardiasis"}],"answerId":"b","explanation":"The combination of pica, eosinophilia, and wheezing is characteristic of Toxocariasis due to visceral larva migrans.","kind":"clinical","origin":"ai"}],"trematodes-flukes-overview":[{"id":"trematodes-flukes-overview~ai-0","moduleId":"trematodes-flukes-overview","stem":"What is the primary mode of transmission for Schistosoma species?","options":[{"id":"a","text":"Ingestion of contaminated food"},{"id":"b","text":"Ingestion of contaminated water"},{"id":"c","text":"Skin penetration by cercariae"},{"id":"d","text":"Inhalation of eggs"}],"answerId":"c","explanation":"Schistosoma species are acquired when cercariae penetrate the skin during freshwater contact, unlike other flukes that are food-borne.","kind":"recall","origin":"ai"},{"id":"trematodes-flukes-overview~ai-1","moduleId":"trematodes-flukes-overview","stem":"Which trematode is most commonly associated with cholangiocarcinoma?","options":[{"id":"a","text":"Fasciola hepatica"},{"id":"b","text":"Clonorchis sinensis"},{"id":"c","text":"Opisthorchis viverrini"},{"id":"d","text":"Paragonimus westermani"}],"answerId":"c","explanation":"Opisthorchis viverrini is linked to cholangiocarcinoma, particularly in Southeast Asia due to the consumption of raw freshwater fish.","kind":"recall","origin":"ai"},{"id":"trematodes-flukes-overview~ai-2","moduleId":"trematodes-flukes-overview","stem":"What is the characteristic finding in stool for trematode infections?","options":[{"id":"a","text":"Non-operculated eggs"},{"id":"b","text":"Operculated eggs"},{"id":"c","text":"Cysts"},{"id":"d","text":"Larvae"}],"answerId":"b","explanation":"Trematode infections are diagnosed by finding operculated eggs in stool or urine, depending on the species.","kind":"recall","origin":"ai"},{"id":"trematodes-flukes-overview~ai-3","moduleId":"trematodes-flukes-overview","stem":"Which of the following findings is associated with Schistosoma mansoni infection?","options":[{"id":"a","text":"Chronic cough and haemoptysis"},{"id":"b","text":"Terminal haematuria"},{"id":"c","text":"Periportal fibrosis"},{"id":"d","text":"Abdominal pain and malabsorption"}],"answerId":"c","explanation":"Schistosoma mansoni is associated with periportal fibrosis and portal hypertension due to egg deposition in the liver.","kind":"recall","origin":"ai"},{"id":"trematodes-flukes-overview~ai-4","moduleId":"trematodes-flukes-overview","stem":"Which mechanism explains the pathogenesis of cholangiocarcinoma in Opisthorchis viverrini infection?","options":[{"id":"a","text":"Direct invasion of liver tissue"},{"id":"b","text":"Chronic inflammation and bile duct obstruction"},{"id":"c","text":"Toxin production leading to cell death"},{"id":"d","text":"Immune evasion and persistence"}],"answerId":"b","explanation":"Chronic inflammation and bile duct obstruction from Opisthorchis viverrini lead to cholangiocarcinoma development.","kind":"mechanism","origin":"ai"},{"id":"trematodes-flukes-overview~ai-5","moduleId":"trematodes-flukes-overview","stem":"A patient presents with chronic cough and haemoptysis after consuming raw crab. What is the likely causative organism?","options":[{"id":"a","text":"Fasciolopsis buski"},{"id":"b","text":"Schistosoma haematobium"},{"id":"c","text":"Paragonimus westermani"},{"id":"d","text":"Clonorchis sinensis"}],"answerId":"c","explanation":"Paragonimus westermani is known to cause chronic cough and haemoptysis after ingestion of raw or undercooked freshwater crab.","kind":"clinical","origin":"ai"},{"id":"trematodes-flukes-overview~ai-6","moduleId":"trematodes-flukes-overview","stem":"How do the transmission routes of intestinal flukes differ from those of blood flukes?","options":[{"id":"a","text":"Both are transmitted via contaminated food"},{"id":"b","text":"Intestinal flukes are food-borne, blood flukes penetrate skin"},{"id":"c","text":"Both penetrate skin"},{"id":"d","text":"Intestinal flukes are transmitted via water"}],"answerId":"b","explanation":"Intestinal flukes are primarily food-borne, while blood flukes like Schistosoma are acquired through skin penetration by cercariae.","kind":"integration","linkedModuleIds":["intestinal-flukes-tapeworms"],"origin":"ai"},{"id":"trematodes-flukes-overview~ai-7","moduleId":"trematodes-flukes-overview","stem":"Which of the following best describes the treatment for Fasciola hepatica infection?","options":[{"id":"a","text":"Praziquantel"},{"id":"b","text":"Albendazole"},{"id":"c","text":"Triclabendazole"},{"id":"d","text":"Mebendazole"}],"answerId":"c","explanation":"Fasciola hepatica is treated with triclabendazole, unlike most other flukes which are treated with praziquantel.","kind":"trap","origin":"ai"},{"id":"trematodes-flukes-overview~ai-8","moduleId":"trematodes-flukes-overview","stem":"What is the primary risk factor for bladder squamous cell carcinoma in Schistosoma haematobium infection?","options":[{"id":"a","text":"Chronic hematuria"},{"id":"b","text":"Chronic inflammation"},{"id":"c","text":"Direct carcinogenic effects of eggs"},{"id":"d","text":"Exposure to contaminated water"}],"answerId":"b","explanation":"Chronic inflammation due to egg deposition in the bladder wall increases the risk of bladder squamous cell carcinoma in S. haematobium infection.","kind":"mechanism","origin":"ai"}],"intestinal-coccidia-cryptosporidium":[{"id":"intestinal-coccidia-cryptosporidium~ai-0","moduleId":"intestinal-coccidia-cryptosporidium","stem":"What is the primary mode of transmission for Cryptosporidium?","options":[{"id":"a","text":"Airborne droplets"},{"id":"b","text":"Vector-borne"},{"id":"c","text":"Faecal-oral"},{"id":"d","text":"Sexual contact"}],"answerId":"c","explanation":"Cryptosporidium is transmitted via the faecal-oral route, primarily through resistant oocysts in contaminated water or food.","kind":"recall","origin":"ai"},{"id":"intestinal-coccidia-cryptosporidium~ai-1","moduleId":"intestinal-coccidia-cryptosporidium","stem":"Which of the following is a key diagnostic feature of Cryptosporidium oocysts in stool?","options":[{"id":"a","text":"They are easily visible on routine O&P"},{"id":"b","text":"They autofluoresce under UV light"},{"id":"c","text":"They are non-acid-fast"},{"id":"d","text":"They are larger than typical bacteria"}],"answerId":"b","explanation":"Cryptosporidium oocysts autofluoresce under UV light, aiding in their identification.","kind":"recall","origin":"ai"},{"id":"intestinal-coccidia-cryptosporidium~ai-2","moduleId":"intestinal-coccidia-cryptosporidium","stem":"In an immunocompromised patient with chronic severe watery diarrhoea, which organism is most likely responsible?","options":[{"id":"a","text":"Cyclospora cayetanensis"},{"id":"b","text":"Cystoisospora belli"},{"id":"c","text":"Cryptosporidium"},{"id":"d","text":"Entamoeba histolytica"}],"answerId":"c","explanation":"Cryptosporidium causes severe chronic diarrhoea in immunocompromised individuals, especially those with HIV.","kind":"clinical","origin":"ai"},{"id":"intestinal-coccidia-cryptosporidium~ai-3","moduleId":"intestinal-coccidia-cryptosporidium","stem":"Which of the following statements about Cyclospora is true?","options":[{"id":"a","text":"It is resistant to co-trimoxazole"},{"id":"b","text":"It is linked to waterborne outbreaks"},{"id":"c","text":"It causes prolonged, relapsing watery diarrhoea"},{"id":"d","text":"It is primarily transmitted via sexual contact"}],"answerId":"c","explanation":"Cyclospora cayetanensis is associated with prolonged, relapsing watery diarrhoea, particularly linked to imported fresh produce.","kind":"recall","origin":"ai"},{"id":"intestinal-coccidia-cryptosporidium~ai-4","moduleId":"intestinal-coccidia-cryptosporidium","stem":"What is the mechanism by which Cryptosporidium causes diarrhoea?","options":[{"id":"a","text":"Invasion of the colon"},{"id":"b","text":"Destruction of gastric mucosa"},{"id":"c","text":"Infection of small-bowel enterocytes"},{"id":"d","text":"Toxin production in the gut"}],"answerId":"c","explanation":"Cryptosporidium infects small-bowel enterocytes, leading to watery diarrhoea.","kind":"mechanism","origin":"ai"},{"id":"intestinal-coccidia-cryptosporidium~ai-5","moduleId":"intestinal-coccidia-cryptosporidium","stem":"A patient presents with watery diarrhoea and a history of swimming in a chlorinated pool. What is the most likely causative agent?","options":[{"id":"a","text":"Cyclospora cayetanensis"},{"id":"b","text":"Cryptosporidium"},{"id":"c","text":"Cystoisospora belli"},{"id":"d","text":"Giardia lamblia"}],"answerId":"b","explanation":"Cryptosporidium is known for causing waterborne outbreaks, especially in chlorinated pools due to its chlorine resistance.","kind":"clinical","origin":"ai"},{"id":"intestinal-coccidia-cryptosporidium~ai-6","moduleId":"intestinal-coccidia-cryptosporidium","stem":"Which of the following is a common diagnostic method for identifying Cryptosporidium oocysts?","options":[{"id":"a","text":"Routine stool ova-and-parasite examination"},{"id":"b","text":"Modified acid-fast stain"},{"id":"c","text":"Blood smear"},{"id":"d","text":"Serology"}],"answerId":"b","explanation":"A modified acid-fast stain is required to visualize Cryptosporidium oocysts, as they are often missed on routine examinations.","kind":"trap","origin":"ai"},{"id":"intestinal-coccidia-cryptosporidium~ai-7","moduleId":"intestinal-coccidia-cryptosporidium","stem":"How does the treatment for Cyclospora differ from that of Cryptosporidium?","options":[{"id":"a","text":"Cyclospora requires nitazoxanide"},{"id":"b","text":"Cryptosporidium responds to co-trimoxazole"},{"id":"c","text":"Cyclospora is treated with supportive care only"},{"id":"d","text":"Cryptosporidium has no reliably effective drug"}],"answerId":"d","explanation":"Cryptosporidium lacks a reliably effective drug, while Cyclospora responds to co-trimoxazole.","kind":"integration","linkedModuleIds":["protozoa-classification-biology"],"origin":"ai"},{"id":"intestinal-coccidia-cryptosporidium~ai-8","moduleId":"intestinal-coccidia-cryptosporidium","stem":"Which protozoan is closely related to Cryptosporidium and is also an apicomplexan?","options":[{"id":"a","text":"Giardia lamblia"},{"id":"b","text":"Toxoplasma gondii"},{"id":"c","text":"Entamoeba histolytica"},{"id":"d","text":"Trichomonas vaginalis"}],"answerId":"b","explanation":"Toxoplasma gondii is an apicomplexan protozoan, like Cryptosporidium, and shares similar biological characteristics.","kind":"integration","linkedModuleIds":["blood-apicomplexa-malaria-babesia"],"origin":"ai"}],"cestodes-tapeworms-overview":[{"id":"cestodes-tapeworms-overview~ai-0","moduleId":"cestodes-tapeworms-overview","stem":"What is the primary mechanism by which Diphyllobothrium latum causes megaloblastic anemia?","options":[{"id":"a","text":"Competes for vitamin B12"},{"id":"b","text":"Causes intestinal obstruction"},{"id":"c","text":"Releases toxins into the bloodstream"},{"id":"d","text":"Infects the liver"}],"answerId":"a","explanation":"Diphyllobothrium latum competes for vitamin B12 in the intestines, leading to megaloblastic anemia.","kind":"mechanism","origin":"ai"},{"id":"cestodes-tapeworms-overview~ai-1","moduleId":"cestodes-tapeworms-overview","stem":"Which of the following findings is most indicative of neurocysticercosis?","options":[{"id":"a","text":"Passage of tapeworm segments in stool"},{"id":"b","text":"Well-defined liver cysts"},{"id":"c","text":"Adult-onset seizures with brain cysts"},{"id":"d","text":"Megaloblastic anemia"}],"answerId":"c","explanation":"Neurocysticercosis presents with adult-onset seizures due to the presence of larval cysts in the brain.","kind":"recall","origin":"ai"},{"id":"cestodes-tapeworms-overview~ai-2","moduleId":"cestodes-tapeworms-overview","stem":"What is the consequence of ingesting Taenia solium eggs?","options":[{"id":"a","text":"Intestinal tapeworm infection"},{"id":"b","text":"Cysticercosis"},{"id":"c","text":"Megaloblastic anemia"},{"id":"d","text":"Sparganosis"}],"answerId":"b","explanation":"Ingesting Taenia solium eggs leads to cysticercosis, where larval cysts form in tissues.","kind":"recall","origin":"ai"},{"id":"cestodes-tapeworms-overview~ai-3","moduleId":"cestodes-tapeworms-overview","stem":"Which statement correctly contrasts the diseases caused by Taenia solium and Taenia saginata?","options":[{"id":"a","text":"Both cause cysticercosis"},{"id":"b","text":"T. saginata causes neurocysticercosis"},{"id":"c","text":"T. solium causes intestinal tapeworm disease from undercooked pork"},{"id":"d","text":"T. saginata causes megaloblastic anemia"}],"answerId":"c","explanation":"T. solium can cause cysticercosis when eggs are ingested, while both species can cause intestinal tapeworm infections from undercooked meat.","kind":"trap","origin":"ai"},{"id":"cestodes-tapeworms-overview~ai-4","moduleId":"cestodes-tapeworms-overview","stem":"What is the treatment of choice for adult intestinal tapeworm infections?","options":[{"id":"a","text":"Albendazole"},{"id":"b","text":"Praziquantel"},{"id":"c","text":"Metronidazole"},{"id":"d","text":"Nitazoxanide"}],"answerId":"b","explanation":"Praziquantel is the treatment of choice for adult intestinal tapeworm infections.","kind":"recall","origin":"ai"},{"id":"cestodes-tapeworms-overview~ai-5","moduleId":"cestodes-tapeworms-overview","stem":"In a patient with a well-defined liver cyst and a history of dog exposure, which condition is most likely?","options":[{"id":"a","text":"Cysticercosis"},{"id":"b","text":"Echinococcal hydatid disease"},{"id":"c","text":"Sparganosis"},{"id":"d","text":"Diphyllobothrium infection"}],"answerId":"b","explanation":"A well-defined liver cyst in a patient with dog exposure suggests echinococcal hydatid disease.","kind":"recall","origin":"ai"},{"id":"cestodes-tapeworms-overview~ai-6","moduleId":"cestodes-tapeworms-overview","stem":"How does the mechanism of action of praziquantel differ from that of albendazole?","options":[{"id":"a","text":"Praziquantel causes paralysis of the worm"},{"id":"b","text":"Albendazole inhibits glucose uptake"},{"id":"c","text":"Praziquantel is effective against larval stages"},{"id":"d","text":"Albendazole is used for adult tapeworms"}],"answerId":"a","explanation":"Praziquantel causes paralysis of the worm, while albendazole primarily inhibits glucose uptake.","kind":"mechanism","origin":"ai"},{"id":"cestodes-tapeworms-overview~ai-7","moduleId":"cestodes-tapeworms-overview","stem":"How does neurocysticercosis relate to the understanding of intestinal tapeworms?","options":[{"id":"a","text":"Both are caused by T. saginata"},{"id":"b","text":"Both result from eating undercooked meat"},{"id":"c","text":"Neurocysticercosis is a consequence of T. solium egg ingestion"},{"id":"d","text":"Both cause megaloblastic anemia"}],"answerId":"c","explanation":"Neurocysticercosis results from ingesting T. solium eggs, while intestinal tapeworms result from eating undercooked meat.","kind":"integration","linkedModuleIds":["intestinal-flukes-tapeworms"],"origin":"ai"},{"id":"cestodes-tapeworms-overview~ai-8","moduleId":"cestodes-tapeworms-overview","stem":"What is the relationship between cysticercosis and the treatment of tapeworm infections?","options":[{"id":"a","text":"Cysticercosis requires praziquantel"},{"id":"b","text":"Cysticercosis is treated with surgery only"},{"id":"c","text":"Praziquantel is ineffective for cysticercosis"},{"id":"d","text":"Cysticercosis is caused by T. saginata"}],"answerId":"c","explanation":"Praziquantel is effective for adult tapeworms, but cysticercosis is treated with albendazole and may require surgery.","kind":"integration","linkedModuleIds":["echinococcosis-hydatid"],"origin":"ai"}],"echinococcosis-hydatid":[{"id":"echinococcosis-hydatid~ai-0","moduleId":"echinococcosis-hydatid","stem":"What is the definitive host of Echinococcus granulosus?","options":[{"id":"a","text":"Cats"},{"id":"b","text":"Sheep"},{"id":"c","text":"Dogs"},{"id":"d","text":"Humans"}],"answerId":"c","explanation":"Echinococcus granulosus has dogs as its definitive host, where the adult tapeworm resides.","kind":"recall","origin":"ai"},{"id":"echinococcosis-hydatid~ai-1","moduleId":"echinococcosis-hydatid","stem":"Which imaging finding is characteristic of a hydatid cyst?","options":[{"id":"a","text":"Solid mass with necrosis"},{"id":"b","text":"Well-defined fluid-filled cyst"},{"id":"c","text":"Calcified nodule"},{"id":"d","text":"Infiltrative liver lesion"}],"answerId":"b","explanation":"A hydatid cyst typically appears as a well-defined fluid-filled cyst on imaging, often with daughter cysts.","kind":"recall","origin":"ai"},{"id":"echinococcosis-hydatid~ai-2","moduleId":"echinococcosis-hydatid","stem":"What is the primary risk associated with the aspiration of a hydatid cyst?","options":[{"id":"a","text":"Infection"},{"id":"b","text":"Anaphylaxis"},{"id":"c","text":"Hemorrhage"},{"id":"d","text":"Misdiagnosis"}],"answerId":"b","explanation":"Aspiration of a hydatid cyst can lead to anaphylaxis due to the release of antigenic fluid.","kind":"trap","origin":"ai"},{"id":"echinococcosis-hydatid~ai-3","moduleId":"echinococcosis-hydatid","stem":"Which of the following is a common treatment for hydatid disease?","options":[{"id":"a","text":"Metronidazole"},{"id":"b","text":"Albendazole"},{"id":"c","text":"Praziquantel"},{"id":"d","text":"Ivermectin"}],"answerId":"b","explanation":"Albendazole is commonly used in the management of hydatid disease, often in conjunction with surgical techniques.","kind":"recall","origin":"ai"},{"id":"echinococcosis-hydatid~ai-4","moduleId":"echinococcosis-hydatid","stem":"What is the mechanism by which humans become infected with Echinococcus granulosus?","options":[{"id":"a","text":"Ingestion of contaminated meat"},{"id":"b","text":"Inhalation of eggs"},{"id":"c","text":"Ingestion of eggs from dog feces"},{"id":"d","text":"Direct contact with infected dogs"}],"answerId":"c","explanation":"Humans become accidental intermediate hosts by ingesting eggs from dog feces.","kind":"mechanism","origin":"ai"},{"id":"echinococcosis-hydatid~ai-5","moduleId":"echinococcosis-hydatid","stem":"A patient presents with a slowly growing liver cyst and has a history of dog exposure. What serological test result would support the diagnosis of hydatid disease?","options":[{"id":"a","text":"Positive echinococcal serology"},{"id":"b","text":"Negative echinococcal serology"},{"id":"c","text":"Positive liver function tests"},{"id":"d","text":"Negative liver function tests"}],"answerId":"a","explanation":"Positive echinococcal serology supports the diagnosis of hydatid disease in a patient with relevant exposure.","kind":"recall","origin":"ai"},{"id":"echinococcosis-hydatid~ai-6","moduleId":"echinococcosis-hydatid","stem":"How does Echinococcus multilocularis differ from Echinococcus granulosus in terms of clinical presentation?","options":[{"id":"a","text":"Causes cystic lesions"},{"id":"b","text":"Is less aggressive"},{"id":"c","text":"Causes infiltrative, tumor-like lesions"},{"id":"d","text":"Has no definitive host"}],"answerId":"c","explanation":"Echinococcus multilocularis causes infiltrative, tumor-like hepatic lesions, making it more aggressive than E. granulosus.","kind":"integration","linkedModuleIds":["cestodes-tapeworms-overview"],"origin":"ai"},{"id":"echinococcosis-hydatid~ai-7","moduleId":"echinococcosis-hydatid","stem":"Which of the following conditions is also a larval-cyst cestode zoonosis like hydatid disease?","options":[{"id":"a","text":"Sparganosis"},{"id":"b","text":"Amoebic dysentery"},{"id":"c","text":"Giardiasis"},{"id":"d","text":"Ascariasis"}],"answerId":"a","explanation":"Sparganosis is another larval-cyst cestode zoonosis, similar to hydatid disease caused by Echinococcus.","kind":"integration","linkedModuleIds":["sparganosis-spirometra"],"origin":"ai"}],"mosquito-borne-diseases":[{"id":"mosquito-borne-diseases~ai-0","moduleId":"mosquito-borne-diseases","stem":"Which mosquito genus is primarily responsible for transmitting malaria?","options":[{"id":"a","text":"Aedes"},{"id":"b","text":"Culex"},{"id":"c","text":"Anopheles"},{"id":"d","text":"Mansonia"}],"answerId":"c","explanation":"Anopheles mosquitoes are the definitive hosts for the malaria parasite, Plasmodium.","kind":"recall","origin":"ai"},{"id":"mosquito-borne-diseases~ai-1","moduleId":"mosquito-borne-diseases","stem":"What is the primary mechanism of action of diethylcarbamazine in treating lymphatic filariasis?","options":[{"id":"a","text":"Inhibits microfilariae motility"},{"id":"b","text":"Destroys adult worms"},{"id":"c","text":"Inhibits larval development"},{"id":"d","text":"Enhances immune response"}],"answerId":"a","explanation":"Diethylcarbamazine works by immobilizing microfilariae, making them more susceptible to the immune system.","kind":"mechanism","origin":"ai"},{"id":"mosquito-borne-diseases~ai-2","moduleId":"mosquito-borne-diseases","stem":"A patient presents with cyclical fever after traveling to a malarious area. What is the most likely diagnosis?","options":[{"id":"a","text":"Dengue fever"},{"id":"b","text":"Malaria"},{"id":"c","text":"Japanese encephalitis"},{"id":"d","text":"Lymphatic filariasis"}],"answerId":"b","explanation":"Cyclical fever is a classic sign of malaria, which is transmitted by Anopheles mosquitoes.","kind":"clinical","origin":"ai"},{"id":"mosquito-borne-diseases~ai-3","moduleId":"mosquito-borne-diseases","stem":"Which mosquito is the primary vector for dengue fever?","options":[{"id":"a","text":"Anopheles"},{"id":"b","text":"Culex"},{"id":"c","text":"Aedes"},{"id":"d","text":"Mansonia"}],"answerId":"c","explanation":"Aedes mosquitoes, particularly Aedes aegypti, are the main vectors for dengue fever.","kind":"recall","origin":"ai"},{"id":"mosquito-borne-diseases~ai-4","moduleId":"mosquito-borne-diseases","stem":"A patient from an urban area presents with symptoms consistent with dengue fever. What is the most likely mosquito breeding habitat contributing to this outbreak?","options":[{"id":"a","text":"Rice paddies"},{"id":"b","text":"Stagnant water in containers"},{"id":"c","text":"Forested areas"},{"id":"d","text":"Fast-flowing rivers"}],"answerId":"b","explanation":"Aedes mosquitoes breed in small collections of clean water, often found in containers around homes.","kind":"clinical","origin":"ai"},{"id":"mosquito-borne-diseases~ai-5","moduleId":"mosquito-borne-diseases","stem":"Which of the following statements about mosquito-borne diseases is true?","options":[{"id":"a","text":"All mosquitoes transmit malaria"},{"id":"b","text":"Aedes mosquitoes are night-biters"},{"id":"c","text":"Culex mosquitoes transmit Japanese encephalitis"},{"id":"d","text":"Anopheles mosquitoes are day-biters"}],"answerId":"c","explanation":"Culex mosquitoes are indeed responsible for transmitting Japanese encephalitis, while Anopheles mosquitoes are night-biters.","kind":"trap","origin":"ai"},{"id":"mosquito-borne-diseases~ai-6","moduleId":"mosquito-borne-diseases","stem":"How does the transmission of malaria relate to the life cycle of Plasmodium?","options":[{"id":"a","text":"Plasmodium develops in the human liver"},{"id":"b","text":"Plasmodium is transmitted through contaminated water"},{"id":"c","text":"Plasmodium undergoes sexual reproduction in mosquitoes"},{"id":"d","text":"Plasmodium is transmitted by male mosquitoes"}],"answerId":"c","explanation":"Plasmodium undergoes sexual reproduction in the Anopheles mosquito, which is essential for its life cycle.","kind":"integration","linkedModuleIds":["blood-apicomplexa-malaria-babesia"],"origin":"ai"},{"id":"mosquito-borne-diseases~ai-7","moduleId":"mosquito-borne-diseases","stem":"What is the relationship between Aedes mosquitoes and arboviruses?","options":[{"id":"a","text":"Aedes mosquitoes do not transmit arboviruses"},{"id":"b","text":"Aedes mosquitoes are primarily night-biters"},{"id":"c","text":"Aedes mosquitoes are responsible for transmitting multiple arboviruses"},{"id":"d","text":"Aedes mosquitoes breed in stagnant water"}],"answerId":"c","explanation":"Aedes mosquitoes are known vectors for several arboviruses, including dengue and Zika.","kind":"integration","linkedModuleIds":["arboviruses-mosquito-borne"],"origin":"ai"}],"brainstem-anatomy-organization":[{"id":"brainstem-anatomy-organization~ai-0","moduleId":"brainstem-anatomy-organization","stem":"Which cranial nerves are associated with the midbrain?","options":[{"id":"a","text":"CN I and II"},{"id":"b","text":"CN III and IV"},{"id":"c","text":"CN V and VI"},{"id":"d","text":"CN IX and X"}],"answerId":"b","explanation":"The midbrain houses cranial nerves III (oculomotor) and IV (trochlear).","kind":"recall","origin":"ai"},{"id":"brainstem-anatomy-organization~ai-1","moduleId":"brainstem-anatomy-organization","stem":"What is the primary function of the reticular formation in the brainstem?","options":[{"id":"a","text":"Regulating heart rate"},{"id":"b","text":"Controlling respiration"},{"id":"c","text":"Arousal and consciousness"},{"id":"d","text":"Processing visual information"}],"answerId":"c","explanation":"The reticular formation is crucial for maintaining arousal and consciousness.","kind":"mechanism","origin":"ai"},{"id":"brainstem-anatomy-organization~ai-2","moduleId":"brainstem-anatomy-organization","stem":"A patient presents with right-sided facial weakness and left-sided limb weakness. What does this suggest?","options":[{"id":"a","text":"A unilateral cortical lesion"},{"id":"b","text":"A bilateral brainstem lesion"},{"id":"c","text":"A unilateral brainstem lesion"},{"id":"d","text":"A cervical spinal cord lesion"}],"answerId":"c","explanation":"This pattern of weakness indicates a unilateral brainstem lesion causing crossed signs.","kind":"clinical","origin":"ai"},{"id":"brainstem-anatomy-organization~ai-3","moduleId":"brainstem-anatomy-organization","stem":"Which structure is NOT found in the pons?","options":[{"id":"a","text":"Corticopontine fibers"},{"id":"b","text":"Cerebellar peduncles"},{"id":"c","text":"Inferior colliculus"},{"id":"d","text":"Cranial nerve nuclei V-VIII"}],"answerId":"c","explanation":"The inferior colliculus is located in the midbrain, not the pons.","kind":"trap","origin":"ai"},{"id":"brainstem-anatomy-organization~ai-4","moduleId":"brainstem-anatomy-organization","stem":"A lesion in the medulla affects which cranial nerves?","options":[{"id":"a","text":"CN III and IV"},{"id":"b","text":"CN V and VI"},{"id":"c","text":"CN IX, X, XI, XII"},{"id":"d","text":"CN VII and VIII"}],"answerId":"c","explanation":"The medulla contains the nuclei for cranial nerves IX through XII.","kind":"recall","origin":"ai"},{"id":"brainstem-anatomy-organization~ai-5","moduleId":"brainstem-anatomy-organization","stem":"How does a brainstem lesion typically present with respect to cranial nerve function and limb strength?","options":[{"id":"a","text":"Ipsilateral cranial nerve palsy and ipsilateral limb weakness"},{"id":"b","text":"Contralateral cranial nerve palsy and contralateral limb weakness"},{"id":"c","text":"Ipsilateral cranial nerve palsy and contralateral limb weakness"},{"id":"d","text":"Contralateral cranial nerve palsy and ipsilateral limb weakness"}],"answerId":"c","explanation":"A brainstem lesion causes crossed signs: ipsilateral cranial nerve palsy and contralateral limb weakness.","kind":"mechanism","origin":"ai"},{"id":"brainstem-anatomy-organization~ai-6","moduleId":"brainstem-anatomy-organization","stem":"A patient with a brainstem stroke presents with left-sided hemiparesis and right-sided facial droop. What is the most likely level of the lesion?","options":[{"id":"a","text":"Midbrain"},{"id":"b","text":"Pons"},{"id":"c","text":"Medulla"},{"id":"d","text":"Cortex"}],"answerId":"b","explanation":"The combination of facial droop and hemiparesis suggests a pontine lesion affecting cranial nerve V and descending motor tracts.","kind":"integration","linkedModuleIds":["brainstem-syndromes"],"origin":"ai"},{"id":"brainstem-anatomy-organization~ai-7","moduleId":"brainstem-anatomy-organization","stem":"Which cranial nerve nuclei are located in the pons?","options":[{"id":"a","text":"CN III and IV"},{"id":"b","text":"CN V, VI, VII, VIII"},{"id":"c","text":"CN IX and X"},{"id":"d","text":"CN I and II"}],"answerId":"b","explanation":"The pons contains the nuclei for cranial nerves V through VIII.","kind":"recall","origin":"ai"},{"id":"brainstem-anatomy-organization~ai-8","moduleId":"brainstem-anatomy-organization","stem":"What is the role of the cerebellar peduncles in relation to the brainstem?","options":[{"id":"a","text":"Connect the brainstem to the cerebellum"},{"id":"b","text":"Transmit sensory information to the thalamus"},{"id":"c","text":"Control autonomic functions"},{"id":"d","text":"Regulate sleep-wake cycles"}],"answerId":"a","explanation":"Cerebellar peduncles connect the brainstem to the cerebellum, facilitating coordination.","kind":"mechanism","origin":"ai"}],"myiasis-and-fly-vectors":[{"id":"myiasis-and-fly-vectors~ai-0","moduleId":"myiasis-and-fly-vectors","stem":"What type of vector is the housefly (Musca domestica)?","options":[{"id":"a","text":"Mechanical vector"},{"id":"b","text":"Biological vector"},{"id":"c","text":"Obligate vector"},{"id":"d","text":"Facultative vector"}],"answerId":"a","explanation":"The housefly is classified as a mechanical vector because it carries pathogens on its body and mouthparts without any development of the pathogen inside it.","kind":"recall","origin":"ai"},{"id":"myiasis-and-fly-vectors~ai-1","moduleId":"myiasis-and-fly-vectors","stem":"Which type of myiasis requires living tissue for larval development?","options":[{"id":"a","text":"Facultative myiasis"},{"id":"b","text":"Obligate myiasis"},{"id":"c","text":"Cutaneous myiasis"},{"id":"d","text":"Cavity myiasis"}],"answerId":"b","explanation":"Obligate myiasis involves larvae that require living tissue to develop, such as those from the screwworm.","kind":"recall","origin":"ai"},{"id":"myiasis-and-fly-vectors~ai-2","moduleId":"myiasis-and-fly-vectors","stem":"A patient presents with a boil-like nodule containing a larva and a central pore. What is the most likely diagnosis?","options":[{"id":"a","text":"Wound myiasis"},{"id":"b","text":"Cutaneous myiasis"},{"id":"c","text":"Cavity myiasis"},{"id":"d","text":"Intestinal myiasis"}],"answerId":"b","explanation":"This presentation is characteristic of cutaneous (furuncular) myiasis, where the larva breathes through a central pore.","kind":"clinical","origin":"ai"},{"id":"myiasis-and-fly-vectors~ai-3","moduleId":"myiasis-and-fly-vectors","stem":"Which of the following best describes the mechanism of houseflies spreading diarrheal diseases?","options":[{"id":"a","text":"Biological vector transmission"},{"id":"b","text":"Mechanical vector transmission"},{"id":"c","text":"Direct infection"},{"id":"d","text":"Environmental contamination"}],"answerId":"b","explanation":"Houseflies act as mechanical vectors by carrying pathogens from feces to food, facilitating disease spread.","kind":"mechanism","origin":"ai"},{"id":"myiasis-and-fly-vectors~ai-4","moduleId":"myiasis-and-fly-vectors","stem":"What is a common clinical finding in wound myiasis?","options":[{"id":"a","text":"Boil-like nodule"},{"id":"b","text":"Maggots in a neglected wound"},{"id":"c","text":"Larvae in the nasal cavity"},{"id":"d","text":"Intestinal obstruction"}],"answerId":"b","explanation":"Wound myiasis is characterized by the presence of maggots colonizing neglected wounds.","kind":"recall","origin":"ai"},{"id":"myiasis-and-fly-vectors~ai-5","moduleId":"myiasis-and-fly-vectors","stem":"Which of the following statements about the housefly is incorrect?","options":[{"id":"a","text":"It spreads enteric pathogens."},{"id":"b","text":"It is a biological vector."},{"id":"c","text":"It can be controlled by sanitation."},{"id":"d","text":"It carries pathogens on its body."}],"answerId":"b","explanation":"The housefly is a mechanical vector, not a biological vector, as it does not develop pathogens inside its body.","kind":"trap","origin":"ai"},{"id":"myiasis-and-fly-vectors~ai-6","moduleId":"myiasis-and-fly-vectors","stem":"How does myiasis relate to the study of medical entomology?","options":[{"id":"a","text":"It is unrelated to vectors."},{"id":"b","text":"It involves only blood-sucking flies."},{"id":"c","text":"It is a key aspect of vector-borne diseases."},{"id":"d","text":"It focuses solely on hygiene practices."}],"answerId":"c","explanation":"Myiasis is a significant aspect of medical entomology as it involves the infestation of tissues by fly larvae, which are vectors of disease.","kind":"integration","linkedModuleIds":["medical-entomology-vectors"],"origin":"ai"},{"id":"myiasis-and-fly-vectors~ai-7","moduleId":"myiasis-and-fly-vectors","stem":"What is a key difference between obligate and facultative myiasis?","options":[{"id":"a","text":"Obligate myiasis occurs in healthy tissue, facultative in dead tissue."},{"id":"b","text":"Facultative myiasis requires living tissue, obligate does not."},{"id":"c","text":"Both types require dead tissue for larval development."},{"id":"d","text":"Obligate myiasis is always less severe than facultative."}],"answerId":"a","explanation":"Obligate myiasis involves larvae that require living tissue, while facultative myiasis typically involves larvae that feed on dead tissue but can invade wounds.","kind":"integration","linkedModuleIds":["bloodsucking-fly-vectors"],"origin":"ai"}],"medical-entomology-vectors":[{"id":"medical-entomology-vectors~ai-0","moduleId":"medical-entomology-vectors","stem":"Which of the following arthropods is a biological vector for malaria?","options":[{"id":"a","text":"Aedes mosquito"},{"id":"b","text":"Anopheles mosquito"},{"id":"c","text":"Culex mosquito"},{"id":"d","text":"Housefly"}],"answerId":"b","explanation":"The Anopheles mosquito is the biological vector for malaria, as the Plasmodium parasite develops within it.","kind":"recall","origin":"ai"},{"id":"medical-entomology-vectors~ai-1","moduleId":"medical-entomology-vectors","stem":"What is the primary mechanism of transmission for a housefly carrying pathogens?","options":[{"id":"a","text":"Biological vector"},{"id":"b","text":"Mechanical vector"},{"id":"c","text":"Direct transmission"},{"id":"d","text":"Environmental transmission"}],"answerId":"b","explanation":"A housefly serves as a mechanical vector, carrying pathogens on its body surface without the pathogen developing within it.","kind":"mechanism","origin":"ai"},{"id":"medical-entomology-vectors~ai-2","moduleId":"medical-entomology-vectors","stem":"A patient presents with fever and an eschar after a mite bite. What is the most likely diagnosis?","options":[{"id":"a","text":"Leishmaniasis"},{"id":"b","text":"Scrub typhus"},{"id":"c","text":"Lyme disease"},{"id":"d","text":"Malaria"}],"answerId":"b","explanation":"The symptoms are indicative of scrub typhus, which is transmitted by trombiculid mites.","kind":"recall","origin":"ai"},{"id":"medical-entomology-vectors~ai-3","moduleId":"medical-entomology-vectors","stem":"Which of the following statements about vector control is true?","options":[{"id":"a","text":"Insecticides are ineffective against biological vectors"},{"id":"b","text":"Bed nets reduce transmission of all arthropod-borne diseases"},{"id":"c","text":"Larval-source management targets the life cycle of vectors"},{"id":"d","text":"Repellents are only effective against mechanical vectors"}],"answerId":"c","explanation":"Larval-source management is a method that targets the life cycle of biological vectors to reduce disease transmission.","kind":"trap","origin":"ai"},{"id":"medical-entomology-vectors~ai-4","moduleId":"medical-entomology-vectors","stem":"Which of the following vectors is responsible for transmitting onchocerciasis?","options":[{"id":"a","text":"Sandfly"},{"id":"b","text":"Blackfly"},{"id":"c","text":"Tsetse fly"},{"id":"d","text":"Tick"}],"answerId":"b","explanation":"Blackflies are the vectors that transmit onchocerciasis (river blindness).","kind":"recall","origin":"ai"},{"id":"medical-entomology-vectors~ai-5","moduleId":"medical-entomology-vectors","stem":"How does the transmission of scrub typhus differ from that of malaria?","options":[{"id":"a","text":"Both are biological transmissions"},{"id":"b","text":"Scrub typhus is mechanical, malaria is biological"},{"id":"c","text":"Both are mechanical transmissions"},{"id":"d","text":"Scrub typhus is biological, malaria is mechanical"}],"answerId":"a","explanation":"Both scrub typhus and malaria involve biological transmission, but they use different vectors.","kind":"integration","linkedModuleIds":["medical-mites-acarology"],"origin":"ai"},{"id":"medical-entomology-vectors~ai-6","moduleId":"medical-entomology-vectors","stem":"Which vector is primarily responsible for the transmission of leishmaniasis?","options":[{"id":"a","text":"Tick"},{"id":"b","text":"Sandfly"},{"id":"c","text":"Blackfly"},{"id":"d","text":"Anopheles mosquito"}],"answerId":"b","explanation":"Sandflies are the primary vectors for leishmaniasis, transmitting the Leishmania parasite.","kind":"recall","origin":"ai"},{"id":"medical-entomology-vectors~ai-7","moduleId":"medical-entomology-vectors","stem":"What is the role of insecticide-treated bed nets in vector control?","options":[{"id":"a","text":"They kill all arthropods"},{"id":"b","text":"They prevent bites from biological vectors"},{"id":"c","text":"They are ineffective against mechanical vectors"},{"id":"d","text":"They only protect against mosquitoes"}],"answerId":"b","explanation":"Insecticide-treated bed nets are designed to prevent bites from biological vectors such as mosquitoes, thereby reducing disease transmission.","kind":"trap","origin":"ai"}],"bloodsucking-fly-vectors":[{"id":"bloodsucking-fly-vectors~ai-0","moduleId":"bloodsucking-fly-vectors","stem":"Which blood-sucking fly is the biological vector for leishmaniasis?","options":[{"id":"a","text":"Tsetse fly"},{"id":"b","text":"Sandfly"},{"id":"c","text":"Blackfly"},{"id":"d","text":"Deerfly"}],"answerId":"b","explanation":"The sandfly (Phlebotomus) is the biological vector for leishmaniasis, transmitting the Leishmania parasite.","kind":"recall","origin":"ai"},{"id":"bloodsucking-fly-vectors~ai-1","moduleId":"bloodsucking-fly-vectors","stem":"What is the primary clinical finding in visceral leishmaniasis?","options":[{"id":"a","text":"Chronic skin ulcer"},{"id":"b","text":"Fever and massive splenomegaly"},{"id":"c","text":"Itchy dermatitis"},{"id":"d","text":"Somnolence and coma"}],"answerId":"b","explanation":"Visceral leishmaniasis is characterized by fever, massive splenomegaly, and pancytopenia.","kind":"recall","origin":"ai"},{"id":"bloodsucking-fly-vectors~ai-2","moduleId":"bloodsucking-fly-vectors","stem":"Which of the following is a key feature of African trypanosomiasis?","options":[{"id":"a","text":"Chronic skin ulcer"},{"id":"b","text":"Fever + massive splenomegaly"},{"id":"c","text":"Chancre at the bite site"},{"id":"d","text":"Itchy dermatitis"}],"answerId":"c","explanation":"African trypanosomiasis presents with a chancre at the bite site followed by neurological symptoms.","kind":"recall","origin":"ai"},{"id":"bloodsucking-fly-vectors~ai-3","moduleId":"bloodsucking-fly-vectors","stem":"What is the mechanism of transmission for onchocerciasis?","options":[{"id":"a","text":"Mechanical transmission by houseflies"},{"id":"b","text":"Biological transmission by blackflies"},{"id":"c","text":"Direct contact with infected individuals"},{"id":"d","text":"Waterborne transmission"}],"answerId":"b","explanation":"Onchocerciasis is transmitted biologically by blackflies (Simulium).","kind":"mechanism","origin":"ai"},{"id":"bloodsucking-fly-vectors~ai-4","moduleId":"bloodsucking-fly-vectors","stem":"Which statement about blood-sucking flies is correct?","options":[{"id":"a","text":"All biting flies transmit the same kinds of infection"},{"id":"b","text":"Each blood-sucking fly is a specific biological vector"},{"id":"c","text":"Houseflies are biological vectors"},{"id":"d","text":"Only mosquitoes transmit parasitic diseases"}],"answerId":"b","explanation":"Each blood-sucking fly is a specific biological vector for its corresponding disease.","kind":"trap","origin":"ai"},{"id":"bloodsucking-fly-vectors~ai-5","moduleId":"bloodsucking-fly-vectors","stem":"A patient presents with a worm crossing the conjunctiva. Which fly is the likely vector?","options":[{"id":"a","text":"Sandfly"},{"id":"b","text":"Tsetse fly"},{"id":"c","text":"Blackfly"},{"id":"d","text":"Deerfly"}],"answerId":"d","explanation":"The deerfly (Chrysops) is the vector for Loa loa, which can cause a worm to cross the conjunctiva.","kind":"recall","origin":"ai"},{"id":"bloodsucking-fly-vectors~ai-6","moduleId":"bloodsucking-fly-vectors","stem":"How does the study of blood-sucking flies relate to mosquito-borne diseases?","options":[{"id":"a","text":"Both are mechanical vectors"},{"id":"b","text":"Both transmit parasitic infections"},{"id":"c","text":"Only mosquitoes are biological vectors"},{"id":"d","text":"Both are unrelated"}],"answerId":"b","explanation":"Both blood-sucking flies and mosquitoes transmit parasitic infections, highlighting the importance of vector control.","kind":"integration","linkedModuleIds":["mosquito-borne-diseases"],"origin":"ai"},{"id":"bloodsucking-fly-vectors~ai-7","moduleId":"bloodsucking-fly-vectors","stem":"What is a common feature of biological vectors like blood-sucking flies and mosquitoes?","options":[{"id":"a","text":"They all transmit the same pathogens"},{"id":"b","text":"They are essential hosts for pathogen development"},{"id":"c","text":"They do not require a host for pathogen transmission"},{"id":"d","text":"They are only involved in mechanical transmission"}],"answerId":"b","explanation":"Biological vectors are essential hosts in which the pathogen develops, unlike mechanical vectors.","kind":"integration","linkedModuleIds":["medical-entomology-vectors"],"origin":"ai"}],"spinal-cord-anatomy-organization":[{"id":"spinal-cord-anatomy-organization~ai-0","moduleId":"spinal-cord-anatomy-organization","stem":"Where does the spinal cord typically terminate in adults?","options":[{"id":"a","text":"At L1/L2"},{"id":"b","text":"At T12"},{"id":"c","text":"At S1"},{"id":"d","text":"At C1"}],"answerId":"a","explanation":"The spinal cord terminates at approximately L1/L2 in adults, tapering to the conus medullaris.","kind":"recall","origin":"ai"},{"id":"spinal-cord-anatomy-organization~ai-1","moduleId":"spinal-cord-anatomy-organization","stem":"What type of neurons are found in the ventral horn of the spinal cord?","options":[{"id":"a","text":"Sensory neurons"},{"id":"b","text":"Upper motor neurons"},{"id":"c","text":"Lower motor neurons"},{"id":"d","text":"Sympathetic neurons"}],"answerId":"c","explanation":"The ventral horn contains lower motor neurons, which are the final common pathway to muscles.","kind":"recall","origin":"ai"},{"id":"spinal-cord-anatomy-organization~ai-2","moduleId":"spinal-cord-anatomy-organization","stem":"A patient presents with early symmetric saddle anesthesia and bladder dysfunction. Which condition is most likely?","options":[{"id":"a","text":"Cauda equina syndrome"},{"id":"b","text":"Conus medullaris syndrome"},{"id":"c","text":"Herniated disc"},{"id":"d","text":"Syringomyelia"}],"answerId":"b","explanation":"These symptoms are characteristic of conus medullaris syndrome, which involves both upper and lower motor neuron signs.","kind":"clinical","origin":"ai"},{"id":"spinal-cord-anatomy-organization~ai-3","moduleId":"spinal-cord-anatomy-organization","stem":"Which of the following correctly describes the Bell-Magendie law?","options":[{"id":"a","text":"Dorsal roots carry motor fibers"},{"id":"b","text":"Ventral roots carry sensory fibers"},{"id":"c","text":"Dorsal roots carry sensory fibers"},{"id":"d","text":"Ventral roots carry autonomic fibers"}],"answerId":"c","explanation":"The Bell-Magendie law states that dorsal roots are sensory (afferent) and ventral roots are motor (efferent).","kind":"mechanism","origin":"ai"},{"id":"spinal-cord-anatomy-organization~ai-4","moduleId":"spinal-cord-anatomy-organization","stem":"A lesion at the conus medullaris would most likely present with which of the following?","options":[{"id":"a","text":"Asymmetric leg pain"},{"id":"b","text":"Saddle anesthesia"},{"id":"c","text":"Loss of proprioception"},{"id":"d","text":"Upper motor neuron signs only"}],"answerId":"b","explanation":"Conus medullaris syndrome presents with symmetric saddle anesthesia and bladder/bowel dysfunction due to mixed UMN and LMN involvement.","kind":"trap","origin":"ai"},{"id":"spinal-cord-anatomy-organization~ai-5","moduleId":"spinal-cord-anatomy-organization","stem":"Which structure supplies the anterior two-thirds of the spinal cord?","options":[{"id":"a","text":"Anterior spinal artery"},{"id":"b","text":"Posterior spinal arteries"},{"id":"c","text":"Radicular arteries"},{"id":"d","text":"Vertebral arteries"}],"answerId":"a","explanation":"The anterior spinal artery supplies the anterior two-thirds of the spinal cord.","kind":"recall","origin":"ai"},{"id":"spinal-cord-anatomy-organization~ai-6","moduleId":"spinal-cord-anatomy-organization","stem":"How does the conus medullaris syndrome differ from cauda equina syndrome?","options":[{"id":"a","text":"Conus medullaris is pure LMN"},{"id":"b","text":"Cauda equina has early bladder dysfunction"},{"id":"c","text":"Conus medullaris shows UMN signs"},{"id":"d","text":"Cauda equina has symmetric saddle anesthesia"}],"answerId":"c","explanation":"Conus medullaris syndrome presents with both UMN and LMN signs, while cauda equina syndrome is purely LMN.","kind":"integration","linkedModuleIds":["spinal-cord-syndromes"],"origin":"ai"},{"id":"spinal-cord-anatomy-organization~ai-7","moduleId":"spinal-cord-anatomy-organization","stem":"Which spinal nerve root level is responsible for sympathetic outflow?","options":[{"id":"a","text":"C1-C8"},{"id":"b","text":"T1-L2"},{"id":"c","text":"L3-S5"},{"id":"d","text":"S1-S5"}],"answerId":"b","explanation":"Sympathetic outflow originates from the lateral horn at the T1-L2 levels.","kind":"integration","linkedModuleIds":["axilla-brachial-plexus"],"origin":"ai"}],"cortical-areas-language":[{"id":"cortical-areas-language~ai-0","moduleId":"cortical-areas-language","stem":"Which area of the brain is primarily responsible for speech production?","options":[{"id":"a","text":"Wernicke's area"},{"id":"b","text":"Broca's area"},{"id":"c","text":"Arcuate fasciculus"},{"id":"d","text":"Angular gyrus"}],"answerId":"b","explanation":"Broca's area, located in the inferior frontal gyrus, is responsible for speech production.","kind":"recall","origin":"ai"},{"id":"cortical-areas-language~ai-1","moduleId":"cortical-areas-language","stem":"A patient presents with fluent but nonsensical speech and poor comprehension. Which type of aphasia do they likely have?","options":[{"id":"a","text":"Broca's aphasia"},{"id":"b","text":"Wernicke's aphasia"},{"id":"c","text":"Conduction aphasia"},{"id":"d","text":"Global aphasia"}],"answerId":"b","explanation":"This presentation is characteristic of Wernicke's aphasia, where speech is fluent but lacks meaningful content.","kind":"clinical","origin":"ai"},{"id":"cortical-areas-language~ai-2","moduleId":"cortical-areas-language","stem":"What is the primary mechanism of conduction aphasia?","options":[{"id":"a","text":"Damage to Broca's area"},{"id":"b","text":"Damage to Wernicke's area"},{"id":"c","text":"Damage to the arcuate fasciculus"},{"id":"d","text":"Global brain damage"}],"answerId":"c","explanation":"Conduction aphasia results from damage to the arcuate fasciculus, affecting repetition while preserving fluency and comprehension.","kind":"mechanism","origin":"ai"},{"id":"cortical-areas-language~ai-3","moduleId":"cortical-areas-language","stem":"A patient with a right-sided face and arm weakness has non-fluent speech but intact comprehension. What is the most likely diagnosis?","options":[{"id":"a","text":"Wernicke's aphasia"},{"id":"b","text":"Broca's aphasia"},{"id":"c","text":"Conduction aphasia"},{"id":"d","text":"Global aphasia"}],"answerId":"b","explanation":"This presentation is typical of Broca's aphasia, which is characterized by non-fluent speech and often accompanies motor weakness.","kind":"clinical","origin":"ai"},{"id":"cortical-areas-language~ai-4","moduleId":"cortical-areas-language","stem":"In Wernicke's aphasia, which of the following findings is most likely?","options":[{"id":"a","text":"Patient is aware of their speech deficits"},{"id":"b","text":"Speech is non-fluent and effortful"},{"id":"c","text":"Comprehension is intact"},{"id":"d","text":"Patient produces fluent but meaningless speech"}],"answerId":"d","explanation":"Patients with Wernicke's aphasia produce fluent but nonsensical speech and are typically unaware of their deficits.","kind":"trap","origin":"ai"},{"id":"cortical-areas-language~ai-5","moduleId":"cortical-areas-language","stem":"How does Broca's aphasia differ from Wernicke's aphasia in terms of speech production?","options":[{"id":"a","text":"Both are non-fluent"},{"id":"b","text":"Both are fluent"},{"id":"c","text":"Broca's is non-fluent, Wernicke's is fluent"},{"id":"d","text":"Broca's is fluent, Wernicke's is non-fluent"}],"answerId":"c","explanation":"Broca's aphasia is characterized by non-fluent speech, while Wernicke's aphasia is fluent but lacks meaning.","kind":"trap","origin":"ai"},{"id":"cortical-areas-language~ai-6","moduleId":"cortical-areas-language","stem":"How is the understanding of language affected in Wernicke's aphasia compared to Broca's aphasia?","options":[{"id":"a","text":"Both have impaired comprehension"},{"id":"b","text":"Wernicke's has intact comprehension"},{"id":"c","text":"Broca's has impaired comprehension"},{"id":"d","text":"Wernicke's has impaired comprehension"}],"answerId":"d","explanation":"Wernicke's aphasia is characterized by impaired comprehension, while Broca's aphasia has preserved comprehension.","kind":"integration","linkedModuleIds":["cortex-and-stroke"],"origin":"ai"},{"id":"cortical-areas-language~ai-7","moduleId":"cortical-areas-language","stem":"Which type of aphasia is most likely to occur due to a stroke affecting the middle cerebral artery?","options":[{"id":"a","text":"Broca's aphasia"},{"id":"b","text":"Wernicke's aphasia"},{"id":"c","text":"Conduction aphasia"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"A stroke in the territory of the middle cerebral artery can lead to various types of aphasia, including Broca's, Wernicke's, and conduction aphasia.","kind":"integration","linkedModuleIds":["cerebral-blood-supply"],"origin":"ai"}],"sparganosis-spirometra":[{"id":"sparganosis-spirometra~ai-0","moduleId":"sparganosis-spirometra","stem":"What is the primary mode of human infection with Sparganosis?","options":[{"id":"a","text":"Ingesting infected copepods in water"},{"id":"b","text":"Consuming undercooked pork"},{"id":"c","text":"Contact with infected soil"},{"id":"d","text":"Inhaling contaminated air"}],"answerId":"a","explanation":"Humans can become infected with Sparganosis primarily by drinking water containing infected copepods.","kind":"recall","origin":"ai"},{"id":"sparganosis-spirometra~ai-1","moduleId":"sparganosis-spirometra","stem":"Which of the following is a common clinical finding in Sparganosis?","options":[{"id":"a","text":"Eosinophilia"},{"id":"b","text":"Hematuria"},{"id":"c","text":"Jaundice"},{"id":"d","text":"Diarrhea"}],"answerId":"a","explanation":"Eosinophilia is commonly associated with tissue-migrating larvae such as those seen in Sparganosis.","kind":"recall","origin":"ai"},{"id":"sparganosis-spirometra~ai-2","moduleId":"sparganosis-spirometra","stem":"What is the mechanism by which Sparganum causes disease in humans?","options":[{"id":"a","text":"Maturation into adult tapeworms in the intestine"},{"id":"b","text":"Migration through tissues as a larval form"},{"id":"c","text":"Release of toxins into the bloodstream"},{"id":"d","text":"Direct invasion of the gastrointestinal tract"}],"answerId":"b","explanation":"Sparganum migrates through tissues as a larval form, causing inflammation and symptoms.","kind":"mechanism","origin":"ai"},{"id":"sparganosis-spirometra~ai-3","moduleId":"sparganosis-spirometra","stem":"What is the most effective treatment for Sparganosis?","options":[{"id":"a","text":"Praziquantel"},{"id":"b","text":"Surgical excision"},{"id":"c","text":"Albendazole"},{"id":"d","text":"Supportive care"}],"answerId":"b","explanation":"Surgical excision of the migrating larva is the most effective treatment for Sparganosis.","kind":"recall","origin":"ai"},{"id":"sparganosis-spirometra~ai-4","moduleId":"sparganosis-spirometra","stem":"Which of the following statements about Sparganosis is FALSE?","options":[{"id":"a","text":"Sparganosis can be diagnosed by finding eggs in stool."},{"id":"b","text":"The larva can persist in human tissues for years."},{"id":"c","text":"Surgical removal is both diagnostic and therapeutic."},{"id":"d","text":"Ocular sparganosis can occur from poultice application."}],"answerId":"a","explanation":"Sparganosis cannot be diagnosed by finding eggs in stool, as the larva never matures in humans.","kind":"trap","origin":"ai"},{"id":"sparganosis-spirometra~ai-5","moduleId":"sparganosis-spirometra","stem":"A patient presents with a migrating subcutaneous nodule after using a frog poultice. What is the most likely diagnosis?","options":[{"id":"a","text":"Gnathostomiasis"},{"id":"b","text":"Sparganosis"},{"id":"c","text":"Echinococcosis"},{"id":"d","text":"Cysticercosis"}],"answerId":"b","explanation":"The presentation is consistent with Sparganosis, particularly due to the history of using a frog poultice.","kind":"clinical","origin":"ai"},{"id":"sparganosis-spirometra~ai-6","moduleId":"sparganosis-spirometra","stem":"How does Sparganosis relate to Gnathostomiasis in terms of transmission routes?","options":[{"id":"a","text":"Both are transmitted via contaminated water."},{"id":"b","text":"Both can be contracted through undercooked fish."},{"id":"c","text":"Both involve tissue-migrating larvae."},{"id":"d","text":"Both are diagnosed by stool examination."}],"answerId":"c","explanation":"Both Sparganosis and Gnathostomiasis involve tissue-migrating larvae that cause disease in humans.","kind":"integration","linkedModuleIds":["gnathostomiasis"],"origin":"ai"},{"id":"sparganosis-spirometra~ai-7","moduleId":"sparganosis-spirometra","stem":"Which of the following best describes the relationship between Sparganosis and Echinococcosis?","options":[{"id":"a","text":"Both are caused by adult tapeworms."},{"id":"b","text":"Both involve larval forms that migrate through tissues."},{"id":"c","text":"Both are transmitted through insect vectors."},{"id":"d","text":"Both can be treated with the same medication."}],"answerId":"b","explanation":"Both Sparganosis and Echinococcosis involve larval forms that migrate through tissues, causing disease.","kind":"integration","linkedModuleIds":["echinococcosis-hydatid"],"origin":"ai"}],"dermatomes-spinal-nerves":[{"id":"dermatomes-spinal-nerves~ai-0","moduleId":"dermatomes-spinal-nerves","stem":"Which spinal nerve root is responsible for sensation in the thumb?","options":[{"id":"a","text":"C5"},{"id":"b","text":"C6"},{"id":"c","text":"C7"},{"id":"d","text":"C8"}],"answerId":"b","explanation":"The C6 spinal nerve root supplies the sensation to the thumb, as part of its corresponding dermatome.","kind":"recall","origin":"ai"},{"id":"dermatomes-spinal-nerves~ai-1","moduleId":"dermatomes-spinal-nerves","stem":"A patient presents with sensory loss in the lateral aspect of the foot and weakness in the plantar flexors. Which spinal nerve root is likely affected?","options":[{"id":"a","text":"L4"},{"id":"b","text":"L5"},{"id":"c","text":"S1"},{"id":"d","text":"S2"}],"answerId":"c","explanation":"The S1 nerve root is responsible for sensation in the lateral foot and weakness in the plantar flexors.","kind":"clinical","origin":"ai"},{"id":"dermatomes-spinal-nerves~ai-2","moduleId":"dermatomes-spinal-nerves","stem":"What is the primary mechanism by which a herniated disc causes radiculopathy?","options":[{"id":"a","text":"Compression of the spinal cord"},{"id":"b","text":"Compression of the dorsal root ganglion"},{"id":"c","text":"Compression of the ventral root"},{"id":"d","text":"Compression of a spinal nerve root"}],"answerId":"d","explanation":"A herniated disc typically compresses a spinal nerve root, leading to radiculopathy characterized by dermatomal pain and sensory loss.","kind":"mechanism","origin":"ai"},{"id":"dermatomes-spinal-nerves~ai-3","moduleId":"dermatomes-spinal-nerves","stem":"In which scenario would you expect to see saddle anesthesia?","options":[{"id":"a","text":"C6 radiculopathy"},{"id":"b","text":"L4 radiculopathy"},{"id":"c","text":"S1 radiculopathy"},{"id":"d","text":"S2-S4 radiculopathy"}],"answerId":"d","explanation":"Saddle anesthesia is associated with S2-S4 nerve root involvement, often indicating cauda equina syndrome.","kind":"recall","origin":"ai"},{"id":"dermatomes-spinal-nerves~ai-4","moduleId":"dermatomes-spinal-nerves","stem":"A patient has a sharply demarcated sensory deficit in the distribution of the median nerve. What type of lesion is this indicative of?","options":[{"id":"a","text":"Radiculopathy"},{"id":"b","text":"Peripheral neuropathy"},{"id":"c","text":"Myopathy"},{"id":"d","text":"Cervical myelopathy"}],"answerId":"b","explanation":"A sharply demarcated sensory deficit indicates a peripheral nerve lesion, as opposed to the overlapping deficits seen in radiculopathy.","kind":"trap","origin":"ai"},{"id":"dermatomes-spinal-nerves~ai-5","moduleId":"dermatomes-spinal-nerves","stem":"Which spinal nerve root is responsible for sensation at the umbilicus?","options":[{"id":"a","text":"T8"},{"id":"b","text":"T10"},{"id":"c","text":"L1"},{"id":"d","text":"L4"}],"answerId":"b","explanation":"The T10 spinal nerve root supplies sensation at the umbilicus, helping localize a potential spinal cord or root level.","kind":"recall","origin":"ai"},{"id":"dermatomes-spinal-nerves~ai-6","moduleId":"dermatomes-spinal-nerves","stem":"How does the concept of dermatomes help differentiate between radiculopathy and peripheral neuropathy?","options":[{"id":"a","text":"Dermatomes are always sharply defined"},{"id":"b","text":"Dermatomes overlap, leading to partial sensory loss"},{"id":"c","text":"Radiculopathy affects multiple dermatomes"},{"id":"d","text":"Peripheral neuropathy affects only one nerve root"}],"answerId":"b","explanation":"Dermatomes overlap, which means that a single-root lesion (radiculopathy) causes only partial sensory loss, unlike the sharply defined deficits seen in peripheral neuropathy.","kind":"trap","origin":"ai"},{"id":"dermatomes-spinal-nerves~ai-7","moduleId":"dermatomes-spinal-nerves","stem":"A patient with a herniated lumbar disc presents with weakness in the quadriceps and loss of sensation in the anterior thigh. Which spinal nerve root is likely affected?","options":[{"id":"a","text":"L2"},{"id":"b","text":"L3"},{"id":"c","text":"L4"},{"id":"d","text":"L5"}],"answerId":"c","explanation":"The L4 nerve root is responsible for the quadriceps muscle and sensation in the anterior thigh.","kind":"clinical","origin":"ai"},{"id":"dermatomes-spinal-nerves~ai-8","moduleId":"dermatomes-spinal-nerves","stem":"Which spinal nerve root is primarily involved in the sensation of the little finger?","options":[{"id":"a","text":"C7"},{"id":"b","text":"C8"},{"id":"c","text":"T1"},{"id":"d","text":"L5"}],"answerId":"b","explanation":"The C8 spinal nerve root supplies sensation to the little finger as part of its dermatome.","kind":"recall","origin":"ai"},{"id":"dermatomes-spinal-nerves~ai-9","moduleId":"dermatomes-spinal-nerves","stem":"How does the knowledge of dermatomes integrate with understanding spinal cord syndromes?","options":[{"id":"a","text":"Dermatomes help localize peripheral nerve injuries"},{"id":"b","text":"Dermatomes assist in identifying levels of spinal cord lesions"},{"id":"c","text":"Dermatomes are irrelevant to spinal cord syndromes"},{"id":"d","text":"Dermatomes only apply to upper limb injuries"}],"answerId":"b","explanation":"Understanding dermatomes is crucial for identifying the levels of spinal cord lesions, as they provide a map of sensory distribution.","kind":"integration","linkedModuleIds":["spinal-cord-syndromes"],"origin":"ai"}],"cerebral-cortex-organization":[{"id":"cerebral-cortex-organization~ai-0","moduleId":"cerebral-cortex-organization","stem":"Which layer of the neocortex primarily receives thalamic input?","options":[{"id":"a","text":"Layer I"},{"id":"b","text":"Layer II"},{"id":"c","text":"Layer IV"},{"id":"d","text":"Layer VI"}],"answerId":"c","explanation":"Layer IV of the neocortex is the main recipient of thalamic input, playing a crucial role in sensory processing.","kind":"recall","origin":"ai"},{"id":"cerebral-cortex-organization~ai-1","moduleId":"cerebral-cortex-organization","stem":"What is the primary neurotransmitter used by excitatory pyramidal cells in the neocortex?","options":[{"id":"a","text":"GABA"},{"id":"b","text":"Dopamine"},{"id":"c","text":"Glutamate"},{"id":"d","text":"Serotonin"}],"answerId":"c","explanation":"Excitatory pyramidal cells primarily use glutamate as their neurotransmitter.","kind":"recall","origin":"ai"},{"id":"cerebral-cortex-organization~ai-2","moduleId":"cerebral-cortex-organization","stem":"A patient presents with difficulty in voluntary movements of the right hand. Which area of the cortex is most likely affected?","options":[{"id":"a","text":"Primary somatosensory cortex"},{"id":"b","text":"Prefrontal cortex"},{"id":"c","text":"Primary motor cortex"},{"id":"d","text":"Temporal association cortex"}],"answerId":"c","explanation":"The primary motor cortex, located on the precentral gyrus, is responsible for voluntary movements, including those of the hand.","kind":"clinical","origin":"ai"},{"id":"cerebral-cortex-organization~ai-3","moduleId":"cerebral-cortex-organization","stem":"Which statement best explains the distortion of the homunculus in the primary motor cortex?","options":[{"id":"a","text":"It reflects the physical size of body parts."},{"id":"b","text":"It is proportional to the density of innervation."},{"id":"c","text":"It is based on the age of the individual."},{"id":"d","text":"It is determined by the individual's muscle strength."}],"answerId":"b","explanation":"The distortion of the homunculus reflects the density of innervation and the fineness of control, not the physical size of body parts.","kind":"trap","origin":"ai"},{"id":"cerebral-cortex-organization~ai-4","moduleId":"cerebral-cortex-organization","stem":"What type of cortical area is primarily responsible for integrating sensory information from multiple modalities?","options":[{"id":"a","text":"Primary sensory area"},{"id":"b","text":"Association area"},{"id":"c","text":"Motor area"},{"id":"d","text":"Limbic area"}],"answerId":"b","explanation":"Association areas are responsible for integrating sensory information from multiple modalities, facilitating complex processing.","kind":"recall","origin":"ai"},{"id":"cerebral-cortex-organization~ai-5","moduleId":"cerebral-cortex-organization","stem":"A lesion in the prefrontal cortex can lead to which of the following clinical findings?","options":[{"id":"a","text":"Loss of sensory perception"},{"id":"b","text":"Impaired voluntary movement"},{"id":"c","text":"Executive dysfunction"},{"id":"d","text":"Visual field deficits"}],"answerId":"c","explanation":"Lesions in the prefrontal cortex are associated with executive dysfunction, including issues with planning and personality changes.","kind":"clinical","origin":"ai"},{"id":"cerebral-cortex-organization~ai-6","moduleId":"cerebral-cortex-organization","stem":"How does the organization of the neocortex facilitate specialized processing in the brain?","options":[{"id":"a","text":"By having a single layer of neurons"},{"id":"b","text":"By using only inhibitory interneurons"},{"id":"c","text":"By forming vertical functional columns"},{"id":"d","text":"By connecting directly to the spinal cord"}],"answerId":"c","explanation":"The neocortex is organized into vertical functional columns, which are the basic processing units that allow for specialized processing.","kind":"mechanism","origin":"ai"},{"id":"cerebral-cortex-organization~ai-7","moduleId":"cerebral-cortex-organization","stem":"In a stroke affecting the left hemisphere, which area is most likely to be involved if the patient exhibits language deficits?","options":[{"id":"a","text":"Primary visual cortex"},{"id":"b","text":"Wernicke's area"},{"id":"c","text":"Primary motor cortex"},{"id":"d","text":"Parietal association cortex"}],"answerId":"b","explanation":"Wernicke's area, located in the left hemisphere, is crucial for language comprehension, and its involvement leads to language deficits.","kind":"integration","linkedModuleIds":["cortical-areas-language"],"origin":"ai"},{"id":"cerebral-cortex-organization~ai-8","moduleId":"cerebral-cortex-organization","stem":"Which vascular structure is essential for supplying blood to the primary motor cortex?","options":[{"id":"a","text":"Anterior cerebral artery"},{"id":"b","text":"Middle cerebral artery"},{"id":"c","text":"Posterior cerebral artery"},{"id":"d","text":"Basilar artery"}],"answerId":"b","explanation":"The middle cerebral artery supplies blood to the primary motor cortex, which is critical for motor function.","kind":"integration","linkedModuleIds":["cerebral-blood-supply"],"origin":"ai"}],"cranial-nerves-overview":[{"id":"cranial-nerves-overview~ai-0","moduleId":"cranial-nerves-overview","stem":"Which cranial nerve is responsible for the majority of eye movements?","options":[{"id":"a","text":"CN II"},{"id":"b","text":"CN III"},{"id":"c","text":"CN IV"},{"id":"d","text":"CN VI"}],"answerId":"b","explanation":"CN III (oculomotor) innervates most extraocular muscles, controlling eye movement.","kind":"recall","origin":"ai"},{"id":"cranial-nerves-overview~ai-1","moduleId":"cranial-nerves-overview","stem":"A patient presents with a drooping left eyelid, eye positioned 'down and out', and a dilated pupil. Which cranial nerve is likely affected?","options":[{"id":"a","text":"CN II"},{"id":"b","text":"CN III"},{"id":"c","text":"CN IV"},{"id":"d","text":"CN VI"}],"answerId":"b","explanation":"These symptoms indicate a CN III (oculomotor) palsy.","kind":"clinical","origin":"ai"},{"id":"cranial-nerves-overview~ai-2","moduleId":"cranial-nerves-overview","stem":"Which cranial nerve is purely sensory?","options":[{"id":"a","text":"CN V"},{"id":"b","text":"CN VII"},{"id":"c","text":"CN VIII"},{"id":"d","text":"CN IX"}],"answerId":"c","explanation":"CN VIII (vestibulocochlear) is purely sensory, responsible for hearing and balance.","kind":"recall","origin":"ai"},{"id":"cranial-nerves-overview~ai-3","moduleId":"cranial-nerves-overview","stem":"In a patient with Bell's palsy, which of the following findings would you expect?","options":[{"id":"a","text":"Forehead sparing"},{"id":"b","text":"Whole half-face weakness"},{"id":"c","text":"Contralateral lower-face droop"},{"id":"d","text":"Normal facial movements"}],"answerId":"b","explanation":"Bell's palsy (LMN lesion) results in weakness of the entire ipsilateral half of the face, including the forehead.","kind":"trap","origin":"ai"},{"id":"cranial-nerves-overview~ai-4","moduleId":"cranial-nerves-overview","stem":"Which cranial nerve carries parasympathetic fibers to the parotid gland?","options":[{"id":"a","text":"CN VII"},{"id":"b","text":"CN IX"},{"id":"c","text":"CN X"},{"id":"d","text":"CN III"}],"answerId":"b","explanation":"CN IX (glossopharyngeal) provides parasympathetic innervation to the parotid gland.","kind":"recall","origin":"ai"},{"id":"cranial-nerves-overview~ai-5","moduleId":"cranial-nerves-overview","stem":"A patient has difficulty swallowing and a deviated uvula. Which cranial nerves are likely involved?","options":[{"id":"a","text":"CN IX and X"},{"id":"b","text":"CN V and VII"},{"id":"c","text":"CN III and IV"},{"id":"d","text":"CN XI and XII"}],"answerId":"a","explanation":"CN IX (glossopharyngeal) and CN X (vagus) are involved in swallowing and uvula movement.","kind":"clinical","origin":"ai"},{"id":"cranial-nerves-overview~ai-6","moduleId":"cranial-nerves-overview","stem":"A patient with a stroke shows a contralateral lower-face droop but spares the forehead. Which type of lesion is this?","options":[{"id":"a","text":"LMN lesion"},{"id":"b","text":"UMN lesion"},{"id":"c","text":"Peripheral nerve injury"},{"id":"d","text":"Cranial nerve palsy"}],"answerId":"b","explanation":"This pattern indicates an upper motor neuron (UMN) lesion, as the forehead is spared.","kind":"trap","origin":"ai"},{"id":"cranial-nerves-overview~ai-7","moduleId":"cranial-nerves-overview","stem":"Which cranial nerve is responsible for taste sensation from the anterior two-thirds of the tongue?","options":[{"id":"a","text":"CN V"},{"id":"b","text":"CN VII"},{"id":"c","text":"CN IX"},{"id":"d","text":"CN X"}],"answerId":"b","explanation":"CN VII (facial) is responsible for taste from the anterior two-thirds of the tongue.","kind":"recall","origin":"ai"},{"id":"cranial-nerves-overview~ai-8","moduleId":"cranial-nerves-overview","stem":"A patient with a CN III palsy presents with ptosis and a dilated pupil. Which linked module's content is most relevant to understanding the mechanism?","options":[{"id":"a","text":"Face: Muscles, Innervation & Danger Triangle"},{"id":"b","text":"Extraocular Muscles & Actions"},{"id":"c","text":"Pupillary Reflexes & Horner"},{"id":"d","text":"Brainstem Anatomy & Organisation"}],"answerId":"b","explanation":"The Extraocular Muscles & Actions module provides insight into the functions of CN III and its palsy.","kind":"integration","linkedModuleIds":["extraocular-muscles"],"origin":"ai"},{"id":"cranial-nerves-overview~ai-9","moduleId":"cranial-nerves-overview","stem":"In assessing a patient with facial weakness, which finding would indicate an upper motor neuron lesion?","options":[{"id":"a","text":"Inability to wrinkle forehead"},{"id":"b","text":"Forehead sparing"},{"id":"c","text":"Complete facial droop"},{"id":"d","text":"Difficulty closing one eye"}],"answerId":"b","explanation":"Forehead sparing indicates an upper motor neuron lesion, as the forehead receives bilateral innervation.","kind":"integration","linkedModuleIds":["face-muscles-innervation"],"origin":"ai"}],"motor-system-corticospinal-control":[{"id":"motor-system-corticospinal-control~ai-0","moduleId":"motor-system-corticospinal-control","stem":"Which structure is primarily responsible for executing voluntary movement?","options":[{"id":"a","text":"Basal ganglia"},{"id":"b","text":"Cerebellum"},{"id":"c","text":"Motor cortex"},{"id":"d","text":"Brainstem"}],"answerId":"c","explanation":"The motor cortex is the primary area responsible for executing voluntary movements.","kind":"recall","origin":"ai"},{"id":"motor-system-corticospinal-control~ai-1","moduleId":"motor-system-corticospinal-control","stem":"What is the main pathway for fine, skilled voluntary movement?","options":[{"id":"a","text":"Corticobulbar tract"},{"id":"b","text":"Corticospinal tract"},{"id":"c","text":"Spinothalamic tract"},{"id":"d","text":"Dorsal column-medial lemniscal pathway"}],"answerId":"b","explanation":"The corticospinal tract is the main pathway for fine, skilled voluntary movement, especially of the distal limbs.","kind":"recall","origin":"ai"},{"id":"motor-system-corticospinal-control~ai-2","moduleId":"motor-system-corticospinal-control","stem":"A patient presents with spasticity and hyper-reflexia. What type of lesion is most likely present?","options":[{"id":"a","text":"Upper motor neuron lesion"},{"id":"b","text":"Lower motor neuron lesion"},{"id":"c","text":"Peripheral nerve injury"},{"id":"d","text":"Muscle disease"}],"answerId":"a","explanation":"Spasticity and hyper-reflexia are indicative of an upper motor neuron lesion.","kind":"clinical","origin":"ai"},{"id":"motor-system-corticospinal-control~ai-3","moduleId":"motor-system-corticospinal-control","stem":"Which of the following findings would indicate a lower motor neuron lesion?","options":[{"id":"a","text":"Clonus"},{"id":"b","text":"Babinski sign"},{"id":"c","text":"Muscle wasting"},{"id":"d","text":"Spasticity"}],"answerId":"c","explanation":"Muscle wasting is a characteristic finding of lower motor neuron lesions.","kind":"clinical","origin":"ai"},{"id":"motor-system-corticospinal-control~ai-4","moduleId":"motor-system-corticospinal-control","stem":"A lesion in the corticospinal tract above the medullary pyramids would result in weakness on which side of the body?","options":[{"id":"a","text":"Ipsilateral"},{"id":"b","text":"Contralateral"},{"id":"c","text":"Bilateral"},{"id":"d","text":"No weakness"}],"answerId":"b","explanation":"Lesions above the decussation in the medulla cause contralateral weakness due to the crossing of fibers.","kind":"mechanism","origin":"ai"},{"id":"motor-system-corticospinal-control~ai-5","moduleId":"motor-system-corticospinal-control","stem":"In a patient with amyotrophic lateral sclerosis (ALS), which combination of signs would you expect?","options":[{"id":"a","text":"Spasticity and fasciculations"},{"id":"b","text":"Flaccidity and hyper-reflexia"},{"id":"c","text":"Spasticity and muscle wasting"},{"id":"d","text":"Flaccidity and clonus"}],"answerId":"a","explanation":"ALS causes degeneration of both upper and lower motor neurons, leading to spasticity (UMN signs) and fasciculations (LMN signs).","kind":"trap","origin":"ai"},{"id":"motor-system-corticospinal-control~ai-6","moduleId":"motor-system-corticospinal-control","stem":"How do the basal ganglia influence voluntary movement?","options":[{"id":"a","text":"Execute movement"},{"id":"b","text":"Select and scale movement"},{"id":"c","text":"Coordinate timing"},{"id":"d","text":"Provide sensory feedback"}],"answerId":"b","explanation":"The basal ganglia are involved in selecting and scaling voluntary movements.","kind":"integration","linkedModuleIds":["basal-ganglia-circuitry"],"origin":"ai"},{"id":"motor-system-corticospinal-control~ai-7","moduleId":"motor-system-corticospinal-control","stem":"Which reflex type is primarily involved in the feedback mechanism for fine motor control?","options":[{"id":"a","text":"Stretch reflex"},{"id":"b","text":"Withdrawal reflex"},{"id":"c","text":"Crossed extensor reflex"},{"id":"d","text":"Golgi tendon reflex"}],"answerId":"a","explanation":"The stretch reflex is crucial for maintaining fine motor control and adjusting muscle tone during voluntary movements.","kind":"integration","linkedModuleIds":["proprioceptors-muscle-spindle-reflexes"],"origin":"ai"}],"cns-neurotransmission-systems":[{"id":"cns-neurotransmission-systems~ai-0","moduleId":"cns-neurotransmission-systems","stem":"What is the main excitatory neurotransmitter in the CNS?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"Serotonin"},{"id":"c","text":"Glutamate"},{"id":"d","text":"GABA"}],"answerId":"c","explanation":"Glutamate is recognized as the primary excitatory neurotransmitter in the central nervous system.","kind":"recall","origin":"ai"},{"id":"cns-neurotransmission-systems~ai-1","moduleId":"cns-neurotransmission-systems","stem":"Which neurotransmitter is primarily responsible for inhibitory signaling in the brain?","options":[{"id":"a","text":"Glycine"},{"id":"b","text":"Glutamate"},{"id":"c","text":"Dopamine"},{"id":"d","text":"GABA"}],"answerId":"d","explanation":"GABA is the main inhibitory neurotransmitter in the brain, opening Cl⁻ channels to hyperpolarize neurons.","kind":"recall","origin":"ai"},{"id":"cns-neurotransmission-systems~ai-2","moduleId":"cns-neurotransmission-systems","stem":"What mechanism do benzodiazepines use to enhance inhibition?","options":[{"id":"a","text":"Inhibition of neurotransmitter release"},{"id":"b","text":"Positive modulation of GABA-A receptors"},{"id":"c","text":"Inhibition of reuptake"},{"id":"d","text":"Activation of NMDA receptors"}],"answerId":"b","explanation":"Benzodiazepines enhance the inhibitory effect by positively modulating GABA-A receptors.","kind":"mechanism","origin":"ai"},{"id":"cns-neurotransmission-systems~ai-3","moduleId":"cns-neurotransmission-systems","stem":"Which of the following statements about neurotransmitters is true?","options":[{"id":"a","text":"A neurotransmitter is always excitatory."},{"id":"b","text":"The same neurotransmitter can have excitatory or inhibitory effects depending on the receptor."},{"id":"c","text":"All neurotransmitters act on ionotropic receptors."},{"id":"d","text":"Dopamine is the main inhibitory neurotransmitter."}],"answerId":"b","explanation":"The same neurotransmitter can indeed have different effects based on the type of receptor it binds to.","kind":"trap","origin":"ai"},{"id":"cns-neurotransmission-systems~ai-4","moduleId":"cns-neurotransmission-systems","stem":"Which neurotransmitter system is primarily involved in arousal and attention?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"Serotonin"},{"id":"c","text":"Acetylcholine"},{"id":"d","text":"Noradrenaline"}],"answerId":"d","explanation":"Noradrenaline, originating from the locus coeruleus, is key in modulating arousal and attention.","kind":"recall","origin":"ai"},{"id":"cns-neurotransmission-systems~ai-5","moduleId":"cns-neurotransmission-systems","stem":"How do ionotropic receptors differ from metabotropic receptors?","options":[{"id":"a","text":"Ionotropic receptors are slower than metabotropic receptors."},{"id":"b","text":"Metabotropic receptors are ligand-gated ion channels."},{"id":"c","text":"Ionotropic receptors mediate fast synaptic responses."},{"id":"d","text":"Metabotropic receptors directly open ion channels."}],"answerId":"c","explanation":"Ionotropic receptors mediate fast synaptic responses by acting as ligand-gated ion channels.","kind":"mechanism","origin":"ai"},{"id":"cns-neurotransmission-systems~ai-6","moduleId":"cns-neurotransmission-systems","stem":"Which neurotransmitter is primarily involved in the modulation of pain and nociception?","options":[{"id":"a","text":"Glutamate"},{"id":"b","text":"GABA"},{"id":"c","text":"Dopamine"},{"id":"d","text":"Serotonin"}],"answerId":"a","explanation":"Glutamate plays a significant role in the modulation of pain and nociception in the CNS.","kind":"integration","linkedModuleIds":["pain-nociception-modulation"],"origin":"ai"},{"id":"cns-neurotransmission-systems~ai-7","moduleId":"cns-neurotransmission-systems","stem":"What role does serotonin play in the CNS?","options":[{"id":"a","text":"It primarily mediates excitatory signals."},{"id":"b","text":"It is involved in mood and sleep regulation."},{"id":"c","text":"It enhances GABAergic inhibition."},{"id":"d","text":"It is the main neurotransmitter for motor control."}],"answerId":"b","explanation":"Serotonin is crucial for mood regulation and sleep, acting as a modulator in various CNS functions.","kind":"integration","linkedModuleIds":["neurotransmitter-systems-catalog"],"origin":"ai"}],"sensory-receptors-transduction":[{"id":"sensory-receptors-transduction~ai-0","moduleId":"sensory-receptors-transduction","stem":"What type of receptor is primarily responsible for detecting fine touch and has a slow adaptation rate?","options":[{"id":"a","text":"Pacinian corpuscle"},{"id":"b","text":"Meissner corpuscle"},{"id":"c","text":"Merkel disc"},{"id":"d","text":"Ruffini ending"}],"answerId":"c","explanation":"Merkel discs are slowly adapting receptors that respond to sustained pressure, making them essential for fine touch detection.","kind":"recall","origin":"ai"},{"id":"sensory-receptors-transduction~ai-1","moduleId":"sensory-receptors-transduction","stem":"Which mechanism describes how a stimulus is converted into a receptor potential?","options":[{"id":"a","text":"Labelled-line coding"},{"id":"b","text":"Lateral inhibition"},{"id":"c","text":"Transduction"},{"id":"d","text":"Adaptation"}],"answerId":"c","explanation":"Transduction is the process by which sensory receptors convert stimuli into electrical signals (receptor potentials).","kind":"mechanism","origin":"ai"},{"id":"sensory-receptors-transduction~ai-2","moduleId":"sensory-receptors-transduction","stem":"What is the primary characteristic of rapidly adapting receptors?","options":[{"id":"a","text":"They fire continuously during a stimulus."},{"id":"b","text":"They detect changes in stimulus intensity."},{"id":"c","text":"They have large receptive fields."},{"id":"d","text":"They are exclusively pain receptors."}],"answerId":"b","explanation":"Rapidly adapting receptors, such as Pacinian corpuscles, respond primarily to changes in stimulus intensity rather than sustained stimuli.","kind":"trap","origin":"ai"},{"id":"sensory-receptors-transduction~ai-3","moduleId":"sensory-receptors-transduction","stem":"What phenomenon enhances the ability to localize a stimulus by sharpening contrast?","options":[{"id":"a","text":"Labelled-line coding"},{"id":"b","text":"Adaptation"},{"id":"c","text":"Lateral inhibition"},{"id":"d","text":"Receptive field size"}],"answerId":"c","explanation":"Lateral inhibition enhances contrast and sharpens localization of sensory stimuli by inhibiting neighboring receptors.","kind":"recall","origin":"ai"},{"id":"sensory-receptors-transduction~ai-4","moduleId":"sensory-receptors-transduction","stem":"Which sensory receptor is primarily responsible for detecting temperature changes?","options":[{"id":"a","text":"Nociceptors"},{"id":"b","text":"Thermoreceptors"},{"id":"c","text":"Mechanoreceptors"},{"id":"d","text":"Photoreceptors"}],"answerId":"b","explanation":"Thermoreceptors are specialized sensory receptors that detect changes in temperature.","kind":"recall","origin":"ai"},{"id":"sensory-receptors-transduction~ai-5","moduleId":"sensory-receptors-transduction","stem":"How does the size of a receptive field affect two-point discrimination?","options":[{"id":"a","text":"Smaller fields improve discrimination."},{"id":"b","text":"Larger fields improve discrimination."},{"id":"c","text":"Field size has no effect."},{"id":"d","text":"Only receptor density matters."}],"answerId":"a","explanation":"Smaller receptive fields with higher receptor density allow for better two-point discrimination, as seen in areas like the fingertips.","kind":"clinical","origin":"ai"},{"id":"sensory-receptors-transduction~ai-6","moduleId":"sensory-receptors-transduction","stem":"How does the mechanism of transduction relate to pain perception in nociceptors?","options":[{"id":"a","text":"Nociceptors transduce mechanical stimuli only."},{"id":"b","text":"Transduction in nociceptors is independent of stimulus type."},{"id":"c","text":"Nociceptors transduce harmful stimuli into pain signals."},{"id":"d","text":"Pain perception does not involve transduction."}],"answerId":"c","explanation":"Nociceptors transduce harmful or potentially damaging stimuli into pain signals, which is crucial for pain perception.","kind":"integration","linkedModuleIds":["pain-nociception-modulation"],"origin":"ai"},{"id":"sensory-receptors-transduction~ai-7","moduleId":"sensory-receptors-transduction","stem":"What role does the resting membrane potential play in sensory receptor function?","options":[{"id":"a","text":"It determines the type of stimulus detected."},{"id":"b","text":"It influences the threshold for action potential generation."},{"id":"c","text":"It has no effect on sensory receptors."},{"id":"d","text":"It only affects nociceptors."}],"answerId":"b","explanation":"The resting membrane potential influences the excitability of sensory receptors and their ability to generate action potentials in response to stimuli.","kind":"integration","linkedModuleIds":["resting-membrane-potential-nernst"],"origin":"ai"}],"pain-nociception-modulation":[{"id":"pain-nociception-modulation~ai-0","moduleId":"pain-nociception-modulation","stem":"Which type of nociceptive fiber is responsible for transmitting sharp, well-localized 'first' pain?","options":[{"id":"a","text":"Aδ fibers"},{"id":"b","text":"C fibers"},{"id":"c","text":"Aα fibers"},{"id":"d","text":"B fibers"}],"answerId":"a","explanation":"Aδ fibers are myelinated and transmit sharp, well-localized pain quickly.","kind":"recall","origin":"ai"},{"id":"pain-nociception-modulation~ai-1","moduleId":"pain-nociception-modulation","stem":"What mechanism explains the relief of pain when rubbing the affected area?","options":[{"id":"a","text":"Inhibition of Aδ fibers"},{"id":"b","text":"Activation of C fibers"},{"id":"c","text":"Gate control theory"},{"id":"d","text":"Increased nociceptive input"}],"answerId":"c","explanation":"Gate control theory posits that non-painful input can inhibit pain transmission at the spinal cord level.","kind":"mechanism","origin":"ai"},{"id":"pain-nociception-modulation~ai-2","moduleId":"pain-nociception-modulation","stem":"A patient presents with pain in the left arm and jaw. What is the most likely explanation for this phenomenon?","options":[{"id":"a","text":"Direct nerve damage"},{"id":"b","text":"Referred pain"},{"id":"c","text":"Psychogenic pain"},{"id":"d","text":"Peripheral neuropathy"}],"answerId":"b","explanation":"This is an example of referred pain due to convergence of visceral and somatic afferents in the dorsal horn.","kind":"clinical","origin":"ai"},{"id":"pain-nociception-modulation~ai-3","moduleId":"pain-nociception-modulation","stem":"Which neurotransmitter is primarily involved in the descending analgesic pathway from the periaqueductal gray?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"Serotonin"},{"id":"c","text":"Acetylcholine"},{"id":"d","text":"GABA"}],"answerId":"b","explanation":"Serotonin is one of the key neurotransmitters used in the descending pain modulation pathway.","kind":"recall","origin":"ai"},{"id":"pain-nociception-modulation~ai-4","moduleId":"pain-nociception-modulation","stem":"In the context of pain modulation, what is the role of the PAG-raphe system?","options":[{"id":"a","text":"Facilitates pain transmission"},{"id":"b","text":"Inhibits nociceptive signals"},{"id":"c","text":"Transmits sensory information"},{"id":"d","text":"Increases pain perception"}],"answerId":"b","explanation":"The PAG-raphe system is involved in inhibiting nociceptive signals, thus modulating pain perception.","kind":"mechanism","origin":"ai"},{"id":"pain-nociception-modulation~ai-5","moduleId":"pain-nociception-modulation","stem":"Which statement about referred pain is FALSE?","options":[{"id":"a","text":"It results from convergence of visceral and somatic afferents."},{"id":"b","text":"It can be localized to a specific dermatome."},{"id":"c","text":"It indicates that pain has spread to another area."},{"id":"d","text":"It is often misattributed by the brain."}],"answerId":"c","explanation":"Referred pain does not indicate that pain has physically spread; it arises from central convergence of signals.","kind":"trap","origin":"ai"},{"id":"pain-nociception-modulation~ai-6","moduleId":"pain-nociception-modulation","stem":"How does the mechanism of pain modulation relate to the sensory receptors involved in nociception?","options":[{"id":"a","text":"Nociceptors are exclusively Aα fibers."},{"id":"b","text":"Pain modulation does not involve sensory receptors."},{"id":"c","text":"Nociceptors detect tissue damage and signal pain."},{"id":"d","text":"Sensory receptors only transmit non-painful stimuli."}],"answerId":"c","explanation":"Nociceptors are specialized sensory receptors that detect tissue damage and are crucial for signaling pain.","kind":"integration","linkedModuleIds":["sensory-receptors-transduction"],"origin":"ai"},{"id":"pain-nociception-modulation~ai-7","moduleId":"pain-nociception-modulation","stem":"What is the relationship between the descending analgesic system and the perception of pain in acute pyelonephritis?","options":[{"id":"a","text":"It enhances pain perception."},{"id":"b","text":"It has no effect on pain perception."},{"id":"c","text":"It inhibits pain transmission."},{"id":"d","text":"It only affects somatic pain."}],"answerId":"c","explanation":"The descending analgesic system can inhibit pain transmission, which is relevant in managing pain associated with conditions like acute pyelonephritis.","kind":"integration","linkedModuleIds":["acute-pyelonephritis-clinical"],"origin":"ai"}],"brainstem-descending-motor-tracts":[{"id":"brainstem-descending-motor-tracts~ai-0","moduleId":"brainstem-descending-motor-tracts","stem":"Which brainstem tract is primarily responsible for maintaining antigravity extensor tone?","options":[{"id":"a","text":"Rubrospinal tract"},{"id":"b","text":"Vestibulospinal tract"},{"id":"c","text":"Reticulospinal tract"},{"id":"d","text":"Tectospinal tract"}],"answerId":"b","explanation":"The vestibulospinal tract is responsible for maintaining antigravity extensor tone, crucial for balance.","kind":"recall","origin":"ai"},{"id":"brainstem-descending-motor-tracts~ai-1","moduleId":"brainstem-descending-motor-tracts","stem":"What type of posturing is characterized by arm flexion and indicates a lesion above the red nucleus?","options":[{"id":"a","text":"Decerebrate posturing"},{"id":"b","text":"Decorticate posturing"},{"id":"c","text":"Flaccid paralysis"},{"id":"d","text":"Spasticity"}],"answerId":"b","explanation":"Decorticate posturing (arm flexion) indicates a lesion above the red nucleus, where the rubrospinal tract is still functional.","kind":"recall","origin":"ai"},{"id":"brainstem-descending-motor-tracts~ai-2","moduleId":"brainstem-descending-motor-tracts","stem":"Which tract is involved in reflex head and eye turning toward visual stimuli?","options":[{"id":"a","text":"Vestibulospinal tract"},{"id":"b","text":"Reticulospinal tract"},{"id":"c","text":"Rubrospinal tract"},{"id":"d","text":"Tectospinal tract"}],"answerId":"d","explanation":"The tectospinal tract mediates reflex head and eye movements in response to visual stimuli.","kind":"recall","origin":"ai"},{"id":"brainstem-descending-motor-tracts~ai-3","moduleId":"brainstem-descending-motor-tracts","stem":"A patient exhibits decerebrate posturing. What does this indicate about the location of their brain lesion?","options":[{"id":"a","text":"Above the red nucleus"},{"id":"b","text":"At the level of the red nucleus"},{"id":"c","text":"Below the red nucleus"},{"id":"d","text":"In the cerebral cortex"}],"answerId":"c","explanation":"Decerebrate posturing indicates a lesion below the red nucleus, where extensor drive is unopposed.","kind":"clinical","origin":"ai"},{"id":"brainstem-descending-motor-tracts~ai-4","moduleId":"brainstem-descending-motor-tracts","stem":"What is the primary function of the reticulospinal tract?","options":[{"id":"a","text":"Fine voluntary movement"},{"id":"b","text":"Posture and locomotion"},{"id":"c","text":"Reflexive eye movements"},{"id":"d","text":"Flexor tone modulation"}],"answerId":"b","explanation":"The reticulospinal tract is involved in regulating posture and locomotion.","kind":"mechanism","origin":"ai"},{"id":"brainstem-descending-motor-tracts~ai-5","moduleId":"brainstem-descending-motor-tracts","stem":"A patient presents with decorticate posturing following a traumatic brain injury. What is the likely prognosis compared to decerebrate posturing?","options":[{"id":"a","text":"Better prognosis than decerebrate"},{"id":"b","text":"Worse prognosis than decerebrate"},{"id":"c","text":"Same prognosis as decerebrate"},{"id":"d","text":"Prognosis cannot be determined"}],"answerId":"a","explanation":"Decorticate posturing indicates a higher lesion and is generally associated with a better prognosis than decerebrate posturing.","kind":"trap","origin":"ai"},{"id":"brainstem-descending-motor-tracts~ai-6","moduleId":"brainstem-descending-motor-tracts","stem":"How does the vestibulospinal tract interact with the reticulospinal tract in maintaining posture?","options":[{"id":"a","text":"They act independently of each other"},{"id":"b","text":"Vestibulospinal tract inhibits reticulospinal activity"},{"id":"c","text":"Both work together to maintain extensor tone"},{"id":"d","text":"Reticulospinal tract inhibits vestibulospinal activity"}],"answerId":"c","explanation":"Both the vestibulospinal and reticulospinal tracts work together to maintain extensor tone and posture.","kind":"integration","linkedModuleIds":["motor-system-corticospinal-control"],"origin":"ai"},{"id":"brainstem-descending-motor-tracts~ai-7","moduleId":"brainstem-descending-motor-tracts","stem":"Which brainstem tract is primarily responsible for coordinating activity between spinal segments during locomotion?","options":[{"id":"a","text":"Vestibulospinal tract"},{"id":"b","text":"Reticulospinal tract"},{"id":"c","text":"Rubrospinal tract"},{"id":"d","text":"Propriospinal system"}],"answerId":"d","explanation":"The propriospinal system coordinates activity between spinal segments, essential for locomotion.","kind":"integration","linkedModuleIds":["brainstem-syndromes"],"origin":"ai"}],"somatosensory-ascending-pathways":[{"id":"somatosensory-ascending-pathways~ai-0","moduleId":"somatosensory-ascending-pathways","stem":"Which sensory modality is carried by the dorsal column-medial lemniscus pathway?","options":[{"id":"a","text":"Pain"},{"id":"b","text":"Temperature"},{"id":"c","text":"Fine touch"},{"id":"d","text":"Crude touch"}],"answerId":"c","explanation":"The dorsal column-medial lemniscus pathway is responsible for transmitting fine touch, vibration, and conscious proprioception.","kind":"recall","origin":"ai"},{"id":"somatosensory-ascending-pathways~ai-1","moduleId":"somatosensory-ascending-pathways","stem":"At which level does the spinothalamic tract decussate?","options":[{"id":"a","text":"Medulla"},{"id":"b","text":"Dorsal horn of the spinal cord"},{"id":"c","text":"Thalamus"},{"id":"d","text":"Postcentral gyrus"}],"answerId":"b","explanation":"The spinothalamic tract decussates within one or two segments in the spinal cord at the dorsal horn.","kind":"recall","origin":"ai"},{"id":"somatosensory-ascending-pathways~ai-2","moduleId":"somatosensory-ascending-pathways","stem":"A patient presents with loss of vibration and proprioception. Which pathway is likely affected?","options":[{"id":"a","text":"Spinothalamic tract"},{"id":"b","text":"Dorsal column-medial lemniscus"},{"id":"c","text":"Corticospinal tract"},{"id":"d","text":"Anterior corticospinal tract"}],"answerId":"b","explanation":"Loss of vibration and proprioception indicates a lesion in the dorsal column-medial lemniscus pathway.","kind":"clinical","origin":"ai"},{"id":"somatosensory-ascending-pathways~ai-3","moduleId":"somatosensory-ascending-pathways","stem":"In Brown-Séquard syndrome, which sensory loss occurs contralaterally?","options":[{"id":"a","text":"Fine touch"},{"id":"b","text":"Vibration"},{"id":"c","text":"Pain and temperature"},{"id":"d","text":"Proprioception"}],"answerId":"c","explanation":"In Brown-Séquard syndrome, pain and temperature sensation is lost contralaterally due to the early crossing of the spinothalamic tract.","kind":"clinical","origin":"ai"},{"id":"somatosensory-ascending-pathways~ai-4","moduleId":"somatosensory-ascending-pathways","stem":"Which statement correctly describes the decussation of sensory pathways?","options":[{"id":"a","text":"Both pathways cross at the same level"},{"id":"b","text":"DCML crosses in the spinal cord, spinothalamic in the medulla"},{"id":"c","text":"DCML crosses in the medulla, spinothalamic in the spinal cord"},{"id":"d","text":"Both pathways cross in the thalamus"}],"answerId":"c","explanation":"The dorsal column-medial lemniscus pathway crosses in the medulla, while the spinothalamic tract crosses at the spinal cord.","kind":"trap","origin":"ai"},{"id":"somatosensory-ascending-pathways~ai-5","moduleId":"somatosensory-ascending-pathways","stem":"How does the sensory homunculus represent the body in the primary sensory cortex?","options":[{"id":"a","text":"Proportional to body size"},{"id":"b","text":"Equal representation for all body parts"},{"id":"c","text":"Based on sensory modality"},{"id":"d","text":"Proportional to sensory innervation density"}],"answerId":"d","explanation":"The sensory homunculus is organized based on the density of sensory innervation, with more sensitive areas represented larger.","kind":"recall","origin":"ai"},{"id":"somatosensory-ascending-pathways~ai-6","moduleId":"somatosensory-ascending-pathways","stem":"Which sensory pathway is primarily involved in proprioception and how does it relate to spinal reflexes?","options":[{"id":"a","text":"Dorsal column-medial lemniscus; it integrates with reflex arcs"},{"id":"b","text":"Spinothalamic tract; it does not involve reflexes"},{"id":"c","text":"Corticospinal tract; it mediates voluntary movement"},{"id":"d","text":"Spinocerebellar tract; it carries unconscious proprioception"}],"answerId":"a","explanation":"The dorsal column-medial lemniscus pathway is involved in conscious proprioception and integrates with reflex arcs for motor responses.","kind":"integration","linkedModuleIds":["proprioceptors-muscle-spindle-reflexes"],"origin":"ai"},{"id":"somatosensory-ascending-pathways~ai-7","moduleId":"somatosensory-ascending-pathways","stem":"What is the role of the thalamus in sensory processing, and how does it relate to the sensory pathways discussed?","options":[{"id":"a","text":"It is the primary sensory cortex"},{"id":"b","text":"It relays sensory information to the cortex"},{"id":"c","text":"It generates sensory perception"},{"id":"d","text":"It is involved in pain modulation"}],"answerId":"b","explanation":"The thalamus serves as a relay station for sensory information from both the dorsal column-medial lemniscus and spinothalamic pathways to the primary sensory cortex.","kind":"integration","linkedModuleIds":["diencephalon-thalamus-hypothalamus"],"origin":"ai"}],"diencephalon-thalamus-hypothalamus":[{"id":"diencephalon-thalamus-hypothalamus~ai-0","moduleId":"diencephalon-thalamus-hypothalamus","stem":"Which thalamic nucleus is responsible for relaying visual information to the occipital cortex?","options":[{"id":"a","text":"VPL"},{"id":"b","text":"VPM"},{"id":"c","text":"LGN"},{"id":"d","text":"MGN"}],"answerId":"c","explanation":"The Lateral Geniculate Nucleus (LGN) is specifically responsible for visual relay to the occipital cortex.","kind":"recall","origin":"ai"},{"id":"diencephalon-thalamus-hypothalamus~ai-1","moduleId":"diencephalon-thalamus-hypothalamus","stem":"A patient presents with contralateral loss of all sensory modalities and spontaneous pain. Which condition is most likely?","options":[{"id":"a","text":"Hypothalamic dysfunction"},{"id":"b","text":"Déjerine-Roussy syndrome"},{"id":"c","text":"Olfactory bulb lesion"},{"id":"d","text":"Cerebellar ataxia"}],"answerId":"b","explanation":"This presentation is characteristic of Déjerine-Roussy syndrome, which results from a thalamic lesion.","kind":"clinical","origin":"ai"},{"id":"diencephalon-thalamus-hypothalamus~ai-2","moduleId":"diencephalon-thalamus-hypothalamus","stem":"What is the primary function of the hypothalamus?","options":[{"id":"a","text":"Sensory relay"},{"id":"b","text":"Homeostasis regulation"},{"id":"c","text":"Motor coordination"},{"id":"d","text":"Memory processing"}],"answerId":"b","explanation":"The hypothalamus is primarily responsible for regulating homeostasis, including temperature, thirst, and hunger.","kind":"recall","origin":"ai"},{"id":"diencephalon-thalamus-hypothalamus~ai-3","moduleId":"diencephalon-thalamus-hypothalamus","stem":"Which of the following sensory modalities bypasses the thalamus?","options":[{"id":"a","text":"Vision"},{"id":"b","text":"Hearing"},{"id":"c","text":"Smell"},{"id":"d","text":"Touch"}],"answerId":"c","explanation":"Smell (olfaction) is the only sensory modality that bypasses the thalamus and directly reaches the olfactory cortex.","kind":"trap","origin":"ai"},{"id":"diencephalon-thalamus-hypothalamus~ai-4","moduleId":"diencephalon-thalamus-hypothalamus","stem":"A patient with diabetes insipidus likely has dysfunction in which part of the brain?","options":[{"id":"a","text":"Thalamus"},{"id":"b","text":"Cerebellum"},{"id":"c","text":"Hypothalamus"},{"id":"d","text":"Brainstem"}],"answerId":"c","explanation":"Diabetes insipidus is associated with hypothalamic dysfunction, particularly affecting ADH production.","kind":"clinical","origin":"ai"},{"id":"diencephalon-thalamus-hypothalamus~ai-5","moduleId":"diencephalon-thalamus-hypothalamus","stem":"How does the hypothalamus influence the anterior pituitary?","options":[{"id":"a","text":"Direct neural connection"},{"id":"b","text":"Releasing hormones via portal circulation"},{"id":"c","text":"Inhibition of adrenal hormones"},{"id":"d","text":"Regulation of circadian rhythms"}],"answerId":"b","explanation":"The hypothalamus releases hormones into the portal circulation to control the anterior pituitary's function.","kind":"mechanism","origin":"ai"},{"id":"diencephalon-thalamus-hypothalamus~ai-6","moduleId":"diencephalon-thalamus-hypothalamus","stem":"Which hypothalamic nucleus is primarily responsible for regulating circadian rhythms?","options":[{"id":"a","text":"Suprachiasmatic nucleus"},{"id":"b","text":"Lateral hypothalamic area"},{"id":"c","text":"Ventromedial nucleus"},{"id":"d","text":"Paraventricular nucleus"}],"answerId":"a","explanation":"The Suprachiasmatic nucleus is the master clock that regulates circadian rhythms.","kind":"recall","origin":"ai"},{"id":"diencephalon-thalamus-hypothalamus~ai-7","moduleId":"diencephalon-thalamus-hypothalamus","stem":"How does the thalamus relate to the limbic system in terms of sensory processing?","options":[{"id":"a","text":"Thalamus relays all sensory information to limbic structures"},{"id":"b","text":"Limbic system bypasses thalamus for all sensory input"},{"id":"c","text":"Thalamus only relays emotional stimuli"},{"id":"d","text":"Thalamus integrates sensory and emotional information"}],"answerId":"d","explanation":"The thalamus integrates sensory information before it reaches the cortex, including emotional contexts processed by the limbic system.","kind":"integration","linkedModuleIds":["limbic-hypothalamus"],"origin":"ai"},{"id":"diencephalon-thalamus-hypothalamus~ai-8","moduleId":"diencephalon-thalamus-hypothalamus","stem":"What role does the hypothalamus play in the feedback control of homeostasis?","options":[{"id":"a","text":"It directly regulates blood pressure"},{"id":"b","text":"It integrates sensory information for homeostatic responses"},{"id":"c","text":"It solely controls the autonomic nervous system"},{"id":"d","text":"It only responds to hormonal signals"}],"answerId":"b","explanation":"The hypothalamus integrates sensory information to maintain homeostasis through various physiological responses.","kind":"integration","linkedModuleIds":["homeostasis-feedback-control"],"origin":"ai"}],"proprioceptors-muscle-spindle-reflexes":[{"id":"proprioceptors-muscle-spindle-reflexes~ai-0","moduleId":"proprioceptors-muscle-spindle-reflexes","stem":"What type of reflex is the knee-jerk reflex?","options":[{"id":"a","text":"Polysynaptic"},{"id":"b","text":"Monosynaptic"},{"id":"c","text":"Disynaptic"},{"id":"d","text":"Polymodal"}],"answerId":"b","explanation":"The knee-jerk reflex is a monosynaptic reflex arc involving a single synapse between the sensory and motor neurons.","kind":"recall","origin":"ai"},{"id":"proprioceptors-muscle-spindle-reflexes~ai-1","moduleId":"proprioceptors-muscle-spindle-reflexes","stem":"What is the primary function of the Golgi tendon organ?","options":[{"id":"a","text":"Senses muscle length"},{"id":"b","text":"Senses muscle tension"},{"id":"c","text":"Drives muscle contraction"},{"id":"d","text":"Facilitates muscle relaxation"}],"answerId":"b","explanation":"The Golgi tendon organ senses muscle tension and helps prevent muscle overload through autogenic inhibition.","kind":"recall","origin":"ai"},{"id":"proprioceptors-muscle-spindle-reflexes~ai-2","moduleId":"proprioceptors-muscle-spindle-reflexes","stem":"A patient exhibits hyper-reflexia. What does this indicate?","options":[{"id":"a","text":"LMN lesion"},{"id":"b","text":"UMN lesion"},{"id":"c","text":"Sensory nerve damage"},{"id":"d","text":"Normal reflex function"}],"answerId":"b","explanation":"Hyper-reflexia indicates an upper motor neuron (UMN) lesion due to loss of descending inhibition.","kind":"clinical","origin":"ai"},{"id":"proprioceptors-muscle-spindle-reflexes~ai-3","moduleId":"proprioceptors-muscle-spindle-reflexes","stem":"Which statement correctly describes the muscle spindle's role in reflexes?","options":[{"id":"a","text":"Inhibits muscle contraction"},{"id":"b","text":"Senses muscle length"},{"id":"c","text":"Facilitates autogenic inhibition"},{"id":"d","text":"Drives disynaptic reflexes"}],"answerId":"b","explanation":"The muscle spindle senses muscle length and contributes to the monosynaptic stretch reflex that causes contraction.","kind":"trap","origin":"ai"},{"id":"proprioceptors-muscle-spindle-reflexes~ai-4","moduleId":"proprioceptors-muscle-spindle-reflexes","stem":"During a muscle contraction, which mechanism ensures the antagonist muscle relaxes?","options":[{"id":"a","text":"Reciprocal inhibition"},{"id":"b","text":"Autogenic inhibition"},{"id":"c","text":"Monosynaptic reflex"},{"id":"d","text":"Gamma motor neuron activity"}],"answerId":"a","explanation":"Reciprocal inhibition is the mechanism that relaxes the antagonist muscle while the agonist contracts.","kind":"mechanism","origin":"ai"},{"id":"proprioceptors-muscle-spindle-reflexes~ai-5","moduleId":"proprioceptors-muscle-spindle-reflexes","stem":"How does the Golgi tendon organ prevent muscle overload?","options":[{"id":"a","text":"By exciting the alpha motor neuron"},{"id":"b","text":"By inhibiting the alpha motor neuron"},{"id":"c","text":"By stimulating the gamma motor neuron"},{"id":"d","text":"By enhancing muscle contraction"}],"answerId":"b","explanation":"The Golgi tendon organ inhibits the alpha motor neuron to prevent excessive muscle tension, a process known as autogenic inhibition.","kind":"mechanism","origin":"ai"},{"id":"proprioceptors-muscle-spindle-reflexes~ai-6","moduleId":"proprioceptors-muscle-spindle-reflexes","stem":"How are the muscle spindle and Golgi tendon organ functionally different?","options":[{"id":"a","text":"Both sense muscle length"},{"id":"b","text":"Spindle drives contraction, GTO inhibits"},{"id":"c","text":"Both are monosynaptic"},{"id":"d","text":"GTO drives contraction, spindle inhibits"}],"answerId":"b","explanation":"The muscle spindle drives contraction via a monosynaptic reflex, while the Golgi tendon organ inhibits contraction through a disynaptic reflex.","kind":"trap","origin":"ai"},{"id":"proprioceptors-muscle-spindle-reflexes~ai-7","moduleId":"proprioceptors-muscle-spindle-reflexes","stem":"How does the stretch reflex relate to the corticospinal tract?","options":[{"id":"a","text":"It is mediated by the same neurons"},{"id":"b","text":"It is independent of the corticospinal tract"},{"id":"c","text":"It provides feedback to the corticospinal tract"},{"id":"d","text":"It inhibits corticospinal output"}],"answerId":"c","explanation":"The stretch reflex provides feedback to the corticospinal tract, helping to adjust motor output based on muscle length changes.","kind":"integration","linkedModuleIds":["motor-system-corticospinal-control"],"origin":"ai"},{"id":"proprioceptors-muscle-spindle-reflexes~ai-8","moduleId":"proprioceptors-muscle-spindle-reflexes","stem":"What is the relationship between proprioceptors and sensory pathways?","options":[{"id":"a","text":"Proprioceptors are part of the sensory pathways"},{"id":"b","text":"Sensory pathways do not include proprioceptors"},{"id":"c","text":"Proprioceptors only sense pain"},{"id":"d","text":"Sensory pathways are exclusively visual"}],"answerId":"a","explanation":"Proprioceptors, such as muscle spindles and Golgi tendon organs, are integral components of sensory pathways that provide information about body position and movement.","kind":"integration","linkedModuleIds":["somatosensory-ascending-pathways"],"origin":"ai"}],"synaptic-plasticity-learning":[{"id":"synaptic-plasticity-learning~ai-0","moduleId":"synaptic-plasticity-learning","stem":"What is the primary mechanism underlying long-term potentiation (LTP)?","options":[{"id":"a","text":"Increased release of neurotransmitter from presynaptic neuron"},{"id":"b","text":"Insertion of AMPA receptors into the postsynaptic membrane"},{"id":"c","text":"Inhibition of NMDA receptors"},{"id":"d","text":"Decreased calcium influx through voltage-gated channels"}],"answerId":"b","explanation":"LTP is characterized by the insertion of AMPA receptors into the postsynaptic membrane, which strengthens synaptic transmission.","kind":"mechanism","origin":"ai"},{"id":"synaptic-plasticity-learning~ai-1","moduleId":"synaptic-plasticity-learning","stem":"Which receptor acts as a coincidence detector in synaptic plasticity?","options":[{"id":"a","text":"AMPA receptor"},{"id":"b","text":"NMDA receptor"},{"id":"c","text":"GABA receptor"},{"id":"d","text":"Dopamine receptor"}],"answerId":"b","explanation":"The NMDA receptor requires both glutamate binding and postsynaptic depolarization to open, making it a coincidence detector.","kind":"recall","origin":"ai"},{"id":"synaptic-plasticity-learning~ai-2","moduleId":"synaptic-plasticity-learning","stem":"What is the consequence of excessive calcium entry through NMDA receptors?","options":[{"id":"a","text":"Increased synaptic strength"},{"id":"b","text":"Neuronal death"},{"id":"c","text":"Enhanced memory formation"},{"id":"d","text":"Long-term depression"}],"answerId":"b","explanation":"Excessive calcium entry through NMDA receptors can lead to excitotoxicity and neuronal death.","kind":"clinical","origin":"ai"},{"id":"synaptic-plasticity-learning~ai-3","moduleId":"synaptic-plasticity-learning","stem":"Which of the following best describes the role of Ca²⁺ in long-term potentiation?","options":[{"id":"a","text":"Ca²⁺ inhibits AMPA receptor insertion"},{"id":"b","text":"Ca²⁺ activates phosphatases"},{"id":"c","text":"Large Ca²⁺ influx activates kinases leading to AMPA receptor insertion"},{"id":"d","text":"Ca²⁺ causes hyperpolarization of the postsynaptic neuron"}],"answerId":"c","explanation":"A large influx of Ca²⁺ activates kinases, which leads to the insertion of AMPA receptors and strengthens the synapse.","kind":"mechanism","origin":"ai"},{"id":"synaptic-plasticity-learning~ai-4","moduleId":"synaptic-plasticity-learning","stem":"Which statement correctly describes long-term depression (LTD)?","options":[{"id":"a","text":"It is induced by high-frequency stimulation"},{"id":"b","text":"It involves the removal of AMPA receptors"},{"id":"c","text":"It is solely dependent on presynaptic activity"},{"id":"d","text":"It enhances synaptic strength"}],"answerId":"b","explanation":"LTD is characterized by the removal of AMPA receptors from the postsynaptic membrane, resulting in decreased synaptic strength.","kind":"recall","origin":"ai"},{"id":"synaptic-plasticity-learning~ai-5","moduleId":"synaptic-plasticity-learning","stem":"How does neuroplasticity relate to recovery after brain injury?","options":[{"id":"a","text":"It prevents synaptic changes"},{"id":"b","text":"It allows for circuit reorganization"},{"id":"c","text":"It inhibits memory formation"},{"id":"d","text":"It decreases synaptic strength"}],"answerId":"b","explanation":"Neuroplasticity allows the brain to reorganize its circuits after injury, facilitating recovery and rehabilitation.","kind":"clinical","origin":"ai"},{"id":"synaptic-plasticity-learning~ai-6","moduleId":"synaptic-plasticity-learning","stem":"Which process is most directly linked to the concept of Hebbian learning?","options":[{"id":"a","text":"Long-term depression"},{"id":"b","text":"Coincidence detection by NMDA receptors"},{"id":"c","text":"Inhibition of synaptic transmission"},{"id":"d","text":"Increased neurotransmitter release"}],"answerId":"b","explanation":"Hebbian learning is based on the principle that simultaneous activation of pre- and postsynaptic neurons strengthens the synapse, which is mediated by NMDA receptor coincidence detection.","kind":"integration","linkedModuleIds":["synaptic-plasticity-ltd-memory"],"origin":"ai"},{"id":"synaptic-plasticity-learning~ai-7","moduleId":"synaptic-plasticity-learning","stem":"What is the relationship between synaptic plasticity and memory formation?","options":[{"id":"a","text":"Memory is solely dependent on neurotransmitter release"},{"id":"b","text":"Synaptic plasticity underlies the mechanisms of learning and memory"},{"id":"c","text":"Memory formation does not involve synaptic changes"},{"id":"d","text":"Only long-term depression is involved in memory"}],"answerId":"b","explanation":"Synaptic plasticity, through processes like LTP and LTD, is fundamental to the mechanisms of learning and memory.","kind":"integration","linkedModuleIds":["limbic-system-emotion-memory"],"origin":"ai"}],"ventricles-csf-circulation":[{"id":"ventricles-csf-circulation~ai-0","moduleId":"ventricles-csf-circulation","stem":"What structure produces cerebrospinal fluid (CSF)?","options":[{"id":"a","text":"Choroid plexus"},{"id":"b","text":"Arachnoid granulations"},{"id":"c","text":"Pia mater"},{"id":"d","text":"Dura mater"}],"answerId":"a","explanation":"The choroid plexus is responsible for the production of cerebrospinal fluid (CSF) in the ventricles.","kind":"recall","origin":"ai"},{"id":"ventricles-csf-circulation~ai-1","moduleId":"ventricles-csf-circulation","stem":"Which of the following correctly describes non-communicating hydrocephalus?","options":[{"id":"a","text":"Impaired absorption at arachnoid granulations"},{"id":"b","text":"Block within the ventricular system"},{"id":"c","text":"Normal CSF flow"},{"id":"d","text":"Enlarged ventricles after meningitis"}],"answerId":"b","explanation":"Non-communicating hydrocephalus is caused by a blockage within the ventricular system, preventing CSF from reaching the subarachnoid space.","kind":"trap","origin":"ai"},{"id":"ventricles-csf-circulation~ai-2","moduleId":"ventricles-csf-circulation","stem":"What is the most likely cause of a crescent-shaped hematoma in an elderly patient?","options":[{"id":"a","text":"Extradural hemorrhage"},{"id":"b","text":"Subdural hemorrhage"},{"id":"c","text":"Subarachnoid hemorrhage"},{"id":"d","text":"Intracerebral hemorrhage"}],"answerId":"b","explanation":"A crescent-shaped hematoma is characteristic of subdural hemorrhage, often seen in elderly patients due to bridging vein rupture.","kind":"recall","origin":"ai"},{"id":"ventricles-csf-circulation~ai-3","moduleId":"ventricles-csf-circulation","stem":"Which clinical finding is associated with communicating hydrocephalus?","options":[{"id":"a","text":"Dilated ventricles with normal subarachnoid space"},{"id":"b","text":"Enlarged ventricles after meningitis"},{"id":"c","text":"Lens-shaped hematoma"},{"id":"d","text":"Crescent-shaped hematoma"}],"answerId":"b","explanation":"Communicating hydrocephalus is characterized by enlarged ventricles due to impaired absorption of CSF, often following meningitis.","kind":"recall","origin":"ai"},{"id":"ventricles-csf-circulation~ai-4","moduleId":"ventricles-csf-circulation","stem":"What is the primary function of arachnoid granulations?","options":[{"id":"a","text":"Produce CSF"},{"id":"b","text":"Absorb CSF into venous blood"},{"id":"c","text":"Provide structural support"},{"id":"d","text":"Facilitate CSF circulation"}],"answerId":"b","explanation":"Arachnoid granulations are responsible for the absorption of cerebrospinal fluid (CSF) into the venous blood.","kind":"mechanism","origin":"ai"},{"id":"ventricles-csf-circulation~ai-5","moduleId":"ventricles-csf-circulation","stem":"How does obstructive hydrocephalus differ from communicating hydrocephalus?","options":[{"id":"a","text":"Obstructive has normal CSF absorption"},{"id":"b","text":"Communicating has a blockage within ventricles"},{"id":"c","text":"Obstructive has impaired absorption"},{"id":"d","text":"Communicating has no block within ventricles"}],"answerId":"d","explanation":"Obstructive hydrocephalus involves a blockage within the ventricular system, while communicating hydrocephalus involves impaired absorption but no blockage.","kind":"trap","origin":"ai"},{"id":"ventricles-csf-circulation~ai-6","moduleId":"ventricles-csf-circulation","stem":"Which of the following conditions could lead to raised intracranial pressure due to impaired CSF absorption?","options":[{"id":"a","text":"Aqueductal stenosis"},{"id":"b","text":"Meningitis"},{"id":"c","text":"Subdural hematoma"},{"id":"d","text":"Extradural hematoma"}],"answerId":"b","explanation":"Meningitis can lead to impaired absorption of CSF at the arachnoid granulations, resulting in raised intracranial pressure.","kind":"integration","linkedModuleIds":["raised-icp-herniation"],"origin":"ai"},{"id":"ventricles-csf-circulation~ai-7","moduleId":"ventricles-csf-circulation","stem":"In which scenario would you expect ventricular dilation with normal subarachnoid space?","options":[{"id":"a","text":"Obstructive hydrocephalus"},{"id":"b","text":"Communicating hydrocephalus"},{"id":"c","text":"Extradural hemorrhage"},{"id":"d","text":"Subdural hemorrhage"}],"answerId":"b","explanation":"Ventricular dilation with a normal subarachnoid space is indicative of communicating hydrocephalus, where absorption is impaired but flow is intact.","kind":"integration","linkedModuleIds":["raised-icp-herniation"],"origin":"ai"}],"cerebrum-lobes-white-matter":[{"id":"cerebrum-lobes-white-matter~ai-0","moduleId":"cerebrum-lobes-white-matter","stem":"Which lobe of the cerebrum is primarily responsible for executive functions and personality?","options":[{"id":"a","text":"Frontal"},{"id":"b","text":"Parietal"},{"id":"c","text":"Temporal"},{"id":"d","text":"Occipital"}],"answerId":"a","explanation":"The frontal lobe is associated with executive functions, personality, and motor control.","kind":"recall","origin":"ai"},{"id":"cerebrum-lobes-white-matter~ai-1","moduleId":"cerebrum-lobes-white-matter","stem":"What type of white matter tract connects areas within the same hemisphere?","options":[{"id":"a","text":"Commissural fibres"},{"id":"b","text":"Projection fibres"},{"id":"c","text":"Association fibres"},{"id":"d","text":"Transverse fibres"}],"answerId":"c","explanation":"Association fibres connect different areas within the same hemisphere.","kind":"recall","origin":"ai"},{"id":"cerebrum-lobes-white-matter~ai-2","moduleId":"cerebrum-lobes-white-matter","stem":"A patient presents with dense contralateral hemiparesis after a small stroke. Which structure is most likely affected?","options":[{"id":"a","text":"Frontal lobe"},{"id":"b","text":"Internal capsule"},{"id":"c","text":"Corpus callosum"},{"id":"d","text":"Parietal lobe"}],"answerId":"b","explanation":"The internal capsule contains concentrated projection fibres, making small lesions disproportionately disabling.","kind":"clinical","origin":"ai"},{"id":"cerebrum-lobes-white-matter~ai-3","moduleId":"cerebrum-lobes-white-matter","stem":"Which finding is most indicative of a parietal lobe lesion?","options":[{"id":"a","text":"Contralateral homonymous visual field loss"},{"id":"b","text":"Personality change"},{"id":"c","text":"Contralateral neglect"},{"id":"d","text":"Dense contralateral hemiparesis"}],"answerId":"c","explanation":"Contralateral neglect is a classic sign of a non-dominant parietal lobe lesion.","kind":"recall","origin":"ai"},{"id":"cerebrum-lobes-white-matter~ai-4","moduleId":"cerebrum-lobes-white-matter","stem":"What is the primary function of the corpus callosum?","options":[{"id":"a","text":"Connects the two hemispheres"},{"id":"b","text":"Connects cortex to lower structures"},{"id":"c","text":"Connects areas within the same hemisphere"},{"id":"d","text":"Facilitates motor control"}],"answerId":"a","explanation":"The corpus callosum is the largest commissural fibre, connecting the two cerebral hemispheres.","kind":"recall","origin":"ai"},{"id":"cerebrum-lobes-white-matter~ai-5","moduleId":"cerebrum-lobes-white-matter","stem":"A patient with a split-brain syndrome has had which structure affected?","options":[{"id":"a","text":"Frontal lobe"},{"id":"b","text":"Internal capsule"},{"id":"c","text":"Corpus callosum"},{"id":"d","text":"Temporal lobe"}],"answerId":"c","explanation":"Split-brain syndrome results from sectioning or agenesis of the corpus callosum.","kind":"clinical","origin":"ai"},{"id":"cerebrum-lobes-white-matter~ai-6","moduleId":"cerebrum-lobes-white-matter","stem":"How does a lacunar stroke in the internal capsule lead to severe motor deficits?","options":[{"id":"a","text":"It affects only the frontal lobe"},{"id":"b","text":"It interrupts multiple descending pathways"},{"id":"c","text":"It is located in the cortex"},{"id":"d","text":"It affects the corpus callosum"}],"answerId":"b","explanation":"The internal capsule contains concentrated motor and sensory pathways, so a small lesion can cause significant deficits.","kind":"trap","origin":"ai"},{"id":"cerebrum-lobes-white-matter~ai-7","moduleId":"cerebrum-lobes-white-matter","stem":"Which area of the brain is primarily involved in language comprehension?","options":[{"id":"a","text":"Broca's area"},{"id":"b","text":"Wernicke's area"},{"id":"c","text":"Motor cortex"},{"id":"d","text":"Visual cortex"}],"answerId":"b","explanation":"Wernicke's area, located in the temporal lobe, is responsible for language comprehension.","kind":"integration","linkedModuleIds":["cortical-areas-language"],"origin":"ai"},{"id":"cerebrum-lobes-white-matter~ai-8","moduleId":"cerebrum-lobes-white-matter","stem":"What is the relationship between the internal capsule and the basal ganglia?","options":[{"id":"a","text":"The internal capsule surrounds the basal ganglia"},{"id":"b","text":"The internal capsule is part of the basal ganglia"},{"id":"c","text":"The internal capsule connects the basal ganglia to the cortex"},{"id":"d","text":"The internal capsule is unrelated to the basal ganglia"}],"answerId":"a","explanation":"The internal capsule runs between the basal ganglia and the cortex, carrying important motor and sensory pathways.","kind":"integration","linkedModuleIds":["basal-ganglia-circuitry"],"origin":"ai"}],"cerebral-blood-supply":[{"id":"cerebral-blood-supply~ai-0","moduleId":"cerebral-blood-supply","stem":"Which artery primarily supplies the medial aspect of the cerebral hemisphere responsible for leg motor function?","options":[{"id":"a","text":"Anterior cerebral artery"},{"id":"b","text":"Middle cerebral artery"},{"id":"c","text":"Posterior cerebral artery"},{"id":"d","text":"Vertebral artery"}],"answerId":"a","explanation":"The anterior cerebral artery supplies the medial hemisphere, which includes the area responsible for leg movement.","kind":"recall","origin":"ai"},{"id":"cerebral-blood-supply~ai-1","moduleId":"cerebral-blood-supply","stem":"A patient presents with sudden onset of a 'thunderclap' headache. Which condition is most likely?","options":[{"id":"a","text":"Ischemic stroke"},{"id":"b","text":"Subarachnoid hemorrhage"},{"id":"c","text":"Intracerebral hemorrhage"},{"id":"d","text":"Transient ischemic attack"}],"answerId":"b","explanation":"A 'thunderclap' headache is characteristic of a ruptured berry aneurysm leading to subarachnoid hemorrhage.","kind":"clinical","origin":"ai"},{"id":"cerebral-blood-supply~ai-2","moduleId":"cerebral-blood-supply","stem":"What is the primary function of the Circle of Willis?","options":[{"id":"a","text":"Supply blood to the brain"},{"id":"b","text":"Provide collateral circulation"},{"id":"c","text":"Drain venous blood"},{"id":"d","text":"Regulate intracranial pressure"}],"answerId":"b","explanation":"The Circle of Willis provides collateral circulation between the anterior and posterior cerebral arteries.","kind":"mechanism","origin":"ai"},{"id":"cerebral-blood-supply~ai-3","moduleId":"cerebral-blood-supply","stem":"A patient exhibits contralateral face and arm weakness with aphasia. Which artery is most likely occluded?","options":[{"id":"a","text":"Anterior cerebral artery"},{"id":"b","text":"Middle cerebral artery"},{"id":"c","text":"Posterior cerebral artery"},{"id":"d","text":"Basilar artery"}],"answerId":"b","explanation":"The middle cerebral artery supplies the lateral hemisphere, affecting the face and arm areas and potentially causing aphasia if in the dominant hemisphere.","kind":"clinical","origin":"ai"},{"id":"cerebral-blood-supply~ai-4","moduleId":"cerebral-blood-supply","stem":"In a stroke affecting the anterior cerebral artery, which of the following deficits is expected?","options":[{"id":"a","text":"Contralateral leg weakness"},{"id":"b","text":"Contralateral arm weakness"},{"id":"c","text":"Contralateral homonymous hemianopia"},{"id":"d","text":"Aphasia"}],"answerId":"a","explanation":"The anterior cerebral artery supplies the medial aspect of the hemisphere, leading to contralateral leg weakness.","kind":"trap","origin":"ai"},{"id":"cerebral-blood-supply~ai-5","moduleId":"cerebral-blood-supply","stem":"How does the Circle of Willis contribute to stroke management?","options":[{"id":"a","text":"By preventing hemorrhagic strokes"},{"id":"b","text":"By facilitating collateral blood flow"},{"id":"c","text":"By enhancing venous drainage"},{"id":"d","text":"By reducing intracranial pressure"}],"answerId":"b","explanation":"The Circle of Willis allows for collateral blood flow if one of the major arteries is occluded, which can help mitigate the effects of a stroke.","kind":"mechanism","origin":"ai"},{"id":"cerebral-blood-supply~ai-6","moduleId":"cerebral-blood-supply","stem":"Which clinical finding would suggest a stroke in the territory of the posterior cerebral artery?","options":[{"id":"a","text":"Contralateral leg weakness"},{"id":"b","text":"Contralateral face weakness"},{"id":"c","text":"Contralateral homonymous hemianopia"},{"id":"d","text":"Aphasia"}],"answerId":"c","explanation":"The posterior cerebral artery supplies the occipital lobe, leading to contralateral homonymous hemianopia when occluded.","kind":"clinical","origin":"ai"},{"id":"cerebral-blood-supply~ai-7","moduleId":"cerebral-blood-supply","stem":"A patient has difficulty with language comprehension and production. Which area of the brain is most likely affected?","options":[{"id":"a","text":"Primary motor cortex"},{"id":"b","text":"Broca's area"},{"id":"c","text":"Wernicke's area"},{"id":"d","text":"Occipital lobe"}],"answerId":"c","explanation":"Wernicke's area, located in the dominant hemisphere, is responsible for language comprehension and production.","kind":"integration","linkedModuleIds":["cortex-and-stroke"],"origin":"ai"},{"id":"cerebral-blood-supply~ai-8","moduleId":"cerebral-blood-supply","stem":"In a patient with a lacunar stroke, which artery is most likely involved?","options":[{"id":"a","text":"Anterior cerebral artery"},{"id":"b","text":"Middle cerebral artery"},{"id":"c","text":"Lenticulostriate branches"},{"id":"d","text":"Posterior cerebral artery"}],"answerId":"c","explanation":"Lacunar strokes typically involve the lenticulostriate branches of the middle cerebral artery, affecting deep structures.","kind":"integration","linkedModuleIds":["cortex-and-stroke"],"origin":"ai"}],"inner-ear-hair-cell-histology":[{"id":"inner-ear-hair-cell-histology~ai-0","moduleId":"inner-ear-hair-cell-histology","stem":"What is the primary ion responsible for depolarization in hair cells during mechanotransduction?","options":[{"id":"a","text":"Na⁺"},{"id":"b","text":"Ca²⁺"},{"id":"c","text":"K⁺"},{"id":"d","text":"Cl⁻"}],"answerId":"c","explanation":"Hair cells depolarize primarily through the influx of K⁺ from the high-K⁺ endolymph during mechanotransduction.","kind":"recall","origin":"ai"},{"id":"inner-ear-hair-cell-histology~ai-1","moduleId":"inner-ear-hair-cell-histology","stem":"Which structure generates the high-K⁺ endolymph that is crucial for hair cell function?","options":[{"id":"a","text":"Stria vascularis"},{"id":"b","text":"Organ of Corti"},{"id":"c","text":"Cupula"},{"id":"d","text":"Otoliths"}],"answerId":"a","explanation":"The stria vascularis is responsible for producing the high-K⁺ endolymph that creates the endocochlear potential necessary for hair cell depolarization.","kind":"recall","origin":"ai"},{"id":"inner-ear-hair-cell-histology~ai-2","moduleId":"inner-ear-hair-cell-histology","stem":"What happens to hair cells when exposed to ototoxic aminoglycosides?","options":[{"id":"a","text":"They regenerate"},{"id":"b","text":"They hyperpolarize"},{"id":"c","text":"They undergo apoptosis"},{"id":"d","text":"They remain unaffected"}],"answerId":"c","explanation":"Ototoxic aminoglycosides lead to hair cell death, as these cells do not regenerate in mammals, resulting in permanent hearing loss.","kind":"clinical","origin":"ai"},{"id":"inner-ear-hair-cell-histology~ai-3","moduleId":"inner-ear-hair-cell-histology","stem":"Deflection of stereocilia toward the tallest stereocilium results in what physiological change?","options":[{"id":"a","text":"Hyperpolarization"},{"id":"b","text":"Depolarization"},{"id":"c","text":"Inhibition of glutamate release"},{"id":"d","text":"Closure of cation channels"}],"answerId":"b","explanation":"Deflection toward the tallest stereocilium opens mechanically-gated cation channels, leading to K⁺ influx and depolarization of the hair cell.","kind":"mechanism","origin":"ai"},{"id":"inner-ear-hair-cell-histology~ai-4","moduleId":"inner-ear-hair-cell-histology","stem":"Which of the following statements about hair cell transduction is FALSE?","options":[{"id":"a","text":"K⁺ influx occurs from endolymph"},{"id":"b","text":"Tip links open cation channels"},{"id":"c","text":"Hair cells primarily use Na⁺ for depolarization"},{"id":"d","text":"Endocochlear potential drives K⁺ entry"}],"answerId":"c","explanation":"Hair cells primarily use K⁺ for depolarization from endolymph, not Na⁺, which is a common misconception.","kind":"trap","origin":"ai"},{"id":"inner-ear-hair-cell-histology~ai-5","moduleId":"inner-ear-hair-cell-histology","stem":"How do hair cells in the vestibular system compare to those in the cochlea?","options":[{"id":"a","text":"They regenerate after damage"},{"id":"b","text":"They have different ion channels"},{"id":"c","text":"They share the same sensory cell type"},{"id":"d","text":"They are located in different anatomical structures"}],"answerId":"c","explanation":"Both cochlear and vestibular systems utilize hair cells as sensory receptors, despite their different anatomical locations and functions.","kind":"integration","linkedModuleIds":["vestibular-system-physiology"],"origin":"ai"},{"id":"inner-ear-hair-cell-histology~ai-6","moduleId":"inner-ear-hair-cell-histology","stem":"What is the role of the organ of Corti in hearing?","options":[{"id":"a","text":"It generates endolymph"},{"id":"b","text":"It houses the sensory hair cells"},{"id":"c","text":"It amplifies sound waves"},{"id":"d","text":"It connects to the auditory nerve"}],"answerId":"b","explanation":"The organ of Corti contains the inner and outer hair cells that transduce sound vibrations into neural signals.","kind":"integration","linkedModuleIds":["auditory-physiology-hearing"],"origin":"ai"}],"visual-phototransduction":[{"id":"visual-phototransduction~ai-0","moduleId":"visual-phototransduction","stem":"What is the primary visual pigment found in rods?","options":[{"id":"a","text":"Iodopsin"},{"id":"b","text":"Rhodopsin"},{"id":"c","text":"Photopsin"},{"id":"d","text":"Opsin"}],"answerId":"b","explanation":"Rhodopsin is the visual pigment in rods, consisting of opsin and 11-cis-retinal.","kind":"recall","origin":"ai"},{"id":"visual-phototransduction~ai-1","moduleId":"visual-phototransduction","stem":"What happens to photoreceptors when exposed to light?","options":[{"id":"a","text":"They depolarize and increase glutamate release"},{"id":"b","text":"They hyperpolarize and decrease glutamate release"},{"id":"c","text":"They remain unchanged"},{"id":"d","text":"They undergo apoptosis"}],"answerId":"b","explanation":"In response to light, photoreceptors hyperpolarize, leading to a decrease in glutamate release.","kind":"mechanism","origin":"ai"},{"id":"visual-phototransduction~ai-2","moduleId":"visual-phototransduction","stem":"A patient presents with night blindness. Which vitamin deficiency is most likely responsible?","options":[{"id":"a","text":"Vitamin B12"},{"id":"b","text":"Vitamin C"},{"id":"c","text":"Vitamin A"},{"id":"d","text":"Vitamin D"}],"answerId":"c","explanation":"Vitamin A deficiency impairs rhodopsin regeneration, leading to night blindness (nyctalopia).","kind":"recall","origin":"ai"},{"id":"visual-phototransduction~ai-3","moduleId":"visual-phototransduction","stem":"Which of the following statements about rods and cones is true?","options":[{"id":"a","text":"Rods provide high acuity color vision"},{"id":"b","text":"Cones are more sensitive in dim light"},{"id":"c","text":"Rods are concentrated in the fovea"},{"id":"d","text":"Cones are responsible for color vision in bright light"}],"answerId":"d","explanation":"Cones are responsible for color vision and are concentrated in the fovea, while rods are more sensitive in dim light and are found in the periphery.","kind":"trap","origin":"ai"},{"id":"visual-phototransduction~ai-4","moduleId":"visual-phototransduction","stem":"Which structure in the retina has no photoreceptors?","options":[{"id":"a","text":"Fovea"},{"id":"b","text":"Optic disc"},{"id":"c","text":"Macula"},{"id":"d","text":"Retinal pigment epithelium"}],"answerId":"b","explanation":"The optic disc is the blind spot in the retina where there are no photoreceptors.","kind":"recall","origin":"ai"},{"id":"visual-phototransduction~ai-5","moduleId":"visual-phototransduction","stem":"How does light affect cGMP levels in photoreceptors?","options":[{"id":"a","text":"Increases cGMP levels"},{"id":"b","text":"Decreases cGMP levels"},{"id":"c","text":"Has no effect on cGMP levels"},{"id":"d","text":"Causes cGMP to be converted to GMP"}],"answerId":"b","explanation":"Light causes a decrease in cGMP levels, leading to the closure of cGMP-gated cation channels.","kind":"mechanism","origin":"ai"},{"id":"visual-phototransduction~ai-6","moduleId":"visual-phototransduction","stem":"How does vitamin A deficiency affect phototransduction?","options":[{"id":"a","text":"It enhances rhodopsin regeneration"},{"id":"b","text":"It impairs rhodopsin regeneration"},{"id":"c","text":"It increases photoreceptor sensitivity"},{"id":"d","text":"It has no effect on phototransduction"}],"answerId":"b","explanation":"Vitamin A deficiency impairs rhodopsin regeneration, which is crucial for proper phototransduction.","kind":"integration","linkedModuleIds":["fat-soluble-vitamins"],"origin":"ai"},{"id":"visual-phototransduction~ai-7","moduleId":"visual-phototransduction","stem":"Which pathway carries visual information from the retina to the brain?","options":[{"id":"a","text":"Optic nerve"},{"id":"b","text":"Optic chiasm"},{"id":"c","text":"Lateral geniculate nucleus"},{"id":"d","text":"Superior colliculus"}],"answerId":"a","explanation":"The optic nerve carries visual information from the ganglion cells in the retina to the brain.","kind":"integration","linkedModuleIds":["visual-pathway-fields"],"origin":"ai"}],"reticular-activating-system-consciousness":[{"id":"reticular-activating-system-consciousness~ai-0","moduleId":"reticular-activating-system-consciousness","stem":"What is the primary function of the ascending reticular activating system (ARAS)?","options":[{"id":"a","text":"To regulate sleep cycles"},{"id":"b","text":"To maintain arousal and wakefulness"},{"id":"c","text":"To process sensory information"},{"id":"d","text":"To coordinate motor functions"}],"answerId":"b","explanation":"The ARAS is crucial for maintaining arousal and wakefulness by activating the cortex.","kind":"recall","origin":"ai"},{"id":"reticular-activating-system-consciousness~ai-1","moduleId":"reticular-activating-system-consciousness","stem":"Which neurotransmitter is NOT involved in the arousal mechanism of the ARAS?","options":[{"id":"a","text":"Acetylcholine"},{"id":"b","text":"Dopamine"},{"id":"c","text":"Histamine"},{"id":"d","text":"Orexin"}],"answerId":"b","explanation":"Dopamine is primarily involved in reward and motor control, not in the arousal mechanism of the ARAS.","kind":"mechanism","origin":"ai"},{"id":"reticular-activating-system-consciousness~ai-2","moduleId":"reticular-activating-system-consciousness","stem":"A patient presents with sleep-wake cycles but no purposeful response. What is the most likely diagnosis?","options":[{"id":"a","text":"Coma"},{"id":"b","text":"Minimally conscious state"},{"id":"c","text":"Vegetative state"},{"id":"d","text":"Brain death"}],"answerId":"c","explanation":"This presentation is characteristic of a vegetative state, where arousal is present without awareness.","kind":"clinical","origin":"ai"},{"id":"reticular-activating-system-consciousness~ai-3","moduleId":"reticular-activating-system-consciousness","stem":"Why can a small lesion in the upper brainstem lead to coma?","options":[{"id":"a","text":"It causes widespread cortical damage"},{"id":"b","text":"It disrupts the ascending reticular activating system"},{"id":"c","text":"It affects blood flow to the brain"},{"id":"d","text":"It damages the hypothalamus directly"}],"answerId":"b","explanation":"A small lesion can disrupt the ARAS, which is critical for maintaining arousal, leading to coma.","kind":"trap","origin":"ai"},{"id":"reticular-activating-system-consciousness~ai-4","moduleId":"reticular-activating-system-consciousness","stem":"Which finding is indicative of brain death?","options":[{"id":"a","text":"Presence of sleep-wake cycles"},{"id":"b","text":"Loss of all brainstem reflexes"},{"id":"c","text":"Ability to respond to stimuli"},{"id":"d","text":"Persistent vegetative state"}],"answerId":"b","explanation":"Brain death is characterized by the irreversible loss of all brainstem reflexes.","kind":"recall","origin":"ai"},{"id":"reticular-activating-system-consciousness~ai-5","moduleId":"reticular-activating-system-consciousness","stem":"How does the ARAS connect to the cortex?","options":[{"id":"a","text":"Through the spinal cord"},{"id":"b","text":"Via the thalamus and hypothalamus"},{"id":"c","text":"Directly from the brainstem"},{"id":"d","text":"Through the corpus callosum"}],"answerId":"b","explanation":"The ARAS projects from the brainstem to the thalamus and hypothalamus, which then activate the cortex.","kind":"mechanism","origin":"ai"},{"id":"reticular-activating-system-consciousness~ai-6","moduleId":"reticular-activating-system-consciousness","stem":"How does the understanding of ARAS relate to disorders of consciousness?","options":[{"id":"a","text":"It highlights the role of neurotransmitters in motor function"},{"id":"b","text":"It explains the spectrum from coma to vegetative state"},{"id":"c","text":"It emphasizes the importance of sensory input"},{"id":"d","text":"It connects arousal with emotional responses"}],"answerId":"b","explanation":"Understanding the ARAS is crucial for differentiating between various disorders of consciousness, from coma to vegetative states.","kind":"integration","linkedModuleIds":["disorders-of-consciousness"],"origin":"ai"},{"id":"reticular-activating-system-consciousness~ai-7","moduleId":"reticular-activating-system-consciousness","stem":"What role do neurotransmitters play in the ARAS's function?","options":[{"id":"a","text":"They inhibit cortical activity"},{"id":"b","text":"They promote arousal and wakefulness"},{"id":"c","text":"They are solely responsible for sensory processing"},{"id":"d","text":"They regulate motor output"}],"answerId":"b","explanation":"Neurotransmitters like acetylcholine and histamine promote arousal and wakefulness through the ARAS.","kind":"integration","linkedModuleIds":["cns-neurotransmission-systems"],"origin":"ai"}],"brain-energy-metabolism":[{"id":"brain-energy-metabolism~ai-0","moduleId":"brain-energy-metabolism","stem":"What is the primary energy substrate for the brain under normal conditions?","options":[{"id":"a","text":"Fatty acids"},{"id":"b","text":"Glucose"},{"id":"c","text":"Ketone bodies"},{"id":"d","text":"Lactate"}],"answerId":"b","explanation":"The brain relies almost entirely on glucose for energy under normal conditions.","kind":"recall","origin":"ai"},{"id":"brain-energy-metabolism~ai-1","moduleId":"brain-energy-metabolism","stem":"What mechanism primarily protects the brain from hypoxia?","options":[{"id":"a","text":"Increased glucose uptake"},{"id":"b","text":"Cerebral autoregulation"},{"id":"c","text":"Increased oxygen delivery"},{"id":"d","text":"Neurovascular coupling"}],"answerId":"b","explanation":"Cerebral autoregulation maintains constant blood flow despite fluctuations in blood pressure, protecting the brain from hypoxia.","kind":"mechanism","origin":"ai"},{"id":"brain-energy-metabolism~ai-2","moduleId":"brain-energy-metabolism","stem":"Which finding is indicative of hypoglycemia in a patient with altered consciousness?","options":[{"id":"a","text":"Focal neurological deficits"},{"id":"b","text":"Confusion, seizures, coma reversed by glucose"},{"id":"c","text":"Increased intracranial pressure"},{"id":"d","text":"Loss of consciousness with normal blood pressure"}],"answerId":"b","explanation":"Confusion, seizures, and coma that are reversed by glucose indicate neuroglycopenia due to hypoglycemia.","kind":"recall","origin":"ai"},{"id":"brain-energy-metabolism~ai-3","moduleId":"brain-energy-metabolism","stem":"What effect does hyperventilation have on cerebral blood flow?","options":[{"id":"a","text":"Increases cerebral blood flow"},{"id":"b","text":"Decreases cerebral blood flow"},{"id":"c","text":"No effect on cerebral blood flow"},{"id":"d","text":"Increases oxygen delivery to the brain"}],"answerId":"b","explanation":"Hyperventilation causes hypocapnia, leading to cerebral vasoconstriction and decreased blood flow.","kind":"trap","origin":"ai"},{"id":"brain-energy-metabolism~ai-4","moduleId":"brain-energy-metabolism","stem":"What is the consequence of glutamate excitotoxicity following ischemia?","options":[{"id":"a","text":"Increased ATP production"},{"id":"b","text":"Neuronal death"},{"id":"c","text":"Enhanced neurovascular coupling"},{"id":"d","text":"Improved cerebral blood flow"}],"answerId":"b","explanation":"Glutamate excitotoxicity leads to calcium influx and subsequent neuronal death after energy failure.","kind":"mechanism","origin":"ai"},{"id":"brain-energy-metabolism~ai-5","moduleId":"brain-energy-metabolism","stem":"How does the blood-brain barrier primarily protect the brain?","options":[{"id":"a","text":"By allowing all substances to pass freely"},{"id":"b","text":"By restricting entry of large molecules"},{"id":"c","text":"By permitting only lipid-soluble molecules"},{"id":"d","text":"By facilitating rapid glucose transport"}],"answerId":"c","explanation":"The blood-brain barrier restricts entry to small lipid-soluble molecules and carrier-mediated substrates, protecting the brain from toxins.","kind":"recall","origin":"ai"},{"id":"brain-energy-metabolism~ai-6","moduleId":"brain-energy-metabolism","stem":"How does hypoglycemia relate to blood-glucose homeostasis?","options":[{"id":"a","text":"It indicates excess insulin production"},{"id":"b","text":"It is a result of impaired renal function"},{"id":"c","text":"It reflects inadequate glucose supply to the brain"},{"id":"d","text":"It causes increased gluconeogenesis"}],"answerId":"c","explanation":"Hypoglycemia reflects inadequate glucose supply to the brain, which is critical for its function.","kind":"integration","linkedModuleIds":["blood-glucose-homeostasis"],"origin":"ai"},{"id":"brain-energy-metabolism~ai-7","moduleId":"brain-energy-metabolism","stem":"What is the relationship between cerebral blood supply and the blood-brain barrier during ischemia?","options":[{"id":"a","text":"Ischemia enhances blood-brain barrier integrity"},{"id":"b","text":"Ischemia leads to blood-brain barrier breakdown"},{"id":"c","text":"Cerebral blood supply is unaffected by the blood-brain barrier"},{"id":"d","text":"Blood-brain barrier breakdown prevents ischemic damage"}],"answerId":"b","explanation":"Ischemia can lead to breakdown of the blood-brain barrier, allowing for edema and further complications.","kind":"integration","linkedModuleIds":["cerebral-blood-supply"],"origin":"ai"}],"auditory-physiology-hearing":[{"id":"auditory-physiology-hearing~ai-0","moduleId":"auditory-physiology-hearing","stem":"Which structure in the ear is primarily responsible for amplifying sound waves before they reach the cochlea?","options":[{"id":"a","text":"Tympanic membrane"},{"id":"b","text":"Ossicles"},{"id":"c","text":"Pinna"},{"id":"d","text":"Cochlea"}],"answerId":"b","explanation":"The ossicles (malleus, incus, stapes) amplify sound waves and match impedance between air and fluid.","kind":"recall","origin":"ai"},{"id":"auditory-physiology-hearing~ai-1","moduleId":"auditory-physiology-hearing","stem":"What is the primary mechanism by which hair cells in the cochlea transduce sound?","options":[{"id":"a","text":"Chemical signaling"},{"id":"b","text":"Mechanical deformation"},{"id":"c","text":"Electrical stimulation"},{"id":"d","text":"Thermal changes"}],"answerId":"b","explanation":"Hair cells transduce sound through mechanical deformation of stereocilia, leading to depolarization.","kind":"mechanism","origin":"ai"},{"id":"auditory-physiology-hearing~ai-2","moduleId":"auditory-physiology-hearing","stem":"A patient presents with hearing loss and a Weber test that lateralizes to the affected ear. What type of hearing loss is most likely?","options":[{"id":"a","text":"Sensorineural"},{"id":"b","text":"Conductive"},{"id":"c","text":"Mixed"},{"id":"d","text":"Central"}],"answerId":"b","explanation":"Weber lateralizes to the affected ear in conductive hearing loss, indicating an outer or middle ear problem.","kind":"clinical","origin":"ai"},{"id":"auditory-physiology-hearing~ai-3","moduleId":"auditory-physiology-hearing","stem":"In which part of the cochlea would you expect to find damage in a patient with early high-frequency hearing loss due to noise exposure?","options":[{"id":"a","text":"Base"},{"id":"b","text":"Apex"},{"id":"c","text":"Middle"},{"id":"d","text":"Organ of Corti"}],"answerId":"a","explanation":"The base of the cochlea encodes high frequencies, making it susceptible to damage from noise exposure.","kind":"clinical","origin":"ai"},{"id":"auditory-physiology-hearing~ai-4","moduleId":"auditory-physiology-hearing","stem":"Which of the following statements about cochlear tonotopy is correct?","options":[{"id":"a","text":"Low-pitched sounds are detected at the base of the cochlea."},{"id":"b","text":"The apex encodes high frequencies."},{"id":"c","text":"The base is stiff and encodes high frequencies."},{"id":"d","text":"The cochlea has no tonotopic organization."}],"answerId":"c","explanation":"The cochlea is tonotopically organized such that the stiff base encodes high frequencies and the floppy apex encodes low frequencies.","kind":"trap","origin":"ai"},{"id":"auditory-physiology-hearing~ai-5","moduleId":"auditory-physiology-hearing","stem":"How does the function of outer hair cells differ from inner hair cells in the cochlea?","options":[{"id":"a","text":"Outer hair cells are sensory receptors, inner are amplifiers."},{"id":"b","text":"Inner hair cells amplify sound, outer do not."},{"id":"c","text":"Outer hair cells enhance sensitivity, inner are the true sensory receptors."},{"id":"d","text":"Both types have identical functions."}],"answerId":"c","explanation":"Outer hair cells act as amplifiers to enhance sensitivity, while inner hair cells are the primary sensory receptors.","kind":"mechanism","origin":"ai"},{"id":"auditory-physiology-hearing~ai-6","moduleId":"auditory-physiology-hearing","stem":"How does the auditory pathway relate to the understanding of hearing loss in patients with cochlear damage?","options":[{"id":"a","text":"It is unrelated to cochlear function."},{"id":"b","text":"It helps localize sound in space."},{"id":"c","text":"It explains the neural processing of sound."},{"id":"d","text":"It is only relevant for conductive hearing loss."}],"answerId":"c","explanation":"The auditory pathway is crucial for understanding how sound is processed and perceived, especially in cases of cochlear damage.","kind":"integration","origin":"ai"},{"id":"auditory-physiology-hearing~ai-7","moduleId":"auditory-physiology-hearing","stem":"What role does the tympanic membrane play in the hearing process?","options":[{"id":"a","text":"It amplifies sound waves."},{"id":"b","text":"It converts sound waves into neural signals."},{"id":"c","text":"It vibrates in response to sound waves."},{"id":"d","text":"It protects the inner ear from infection."}],"answerId":"c","explanation":"The tympanic membrane vibrates in response to sound waves, initiating the process of sound transmission to the ossicles.","kind":"recall","origin":"ai"}],"limbic-system-emotion-memory":[{"id":"limbic-system-emotion-memory~ai-0","moduleId":"limbic-system-emotion-memory","stem":"What is the primary function of the hippocampus in the limbic system?","options":[{"id":"a","text":"Regulating emotional responses"},{"id":"b","text":"Forming new declarative memories"},{"id":"c","text":"Processing olfactory information"},{"id":"d","text":"Controlling autonomic functions"}],"answerId":"b","explanation":"The hippocampus is essential for forming new declarative memories, consolidating short-term into long-term memory.","kind":"recall","origin":"ai"},{"id":"limbic-system-emotion-memory~ai-1","moduleId":"limbic-system-emotion-memory","stem":"A patient with bilateral damage to the amygdala is most likely to exhibit which of the following symptoms?","options":[{"id":"a","text":"Severe anxiety and fear responses"},{"id":"b","text":"Inability to form new memories"},{"id":"c","text":"Loss of emotional recognition and placidity"},{"id":"d","text":"Confabulation and confusion"}],"answerId":"c","explanation":"Bilateral amygdala damage leads to Klüver-Bucy syndrome, characterized by placidity, hyperorality, and loss of fear.","kind":"recall","origin":"ai"},{"id":"limbic-system-emotion-memory~ai-2","moduleId":"limbic-system-emotion-memory","stem":"Which of the following best describes the Papez circuit?","options":[{"id":"a","text":"A pathway for olfactory processing"},{"id":"b","text":"A loop connecting the hippocampus and amygdala"},{"id":"c","text":"A circuit linking memory and emotional responses"},{"id":"d","text":"A route for sensory information to the cortex"}],"answerId":"c","explanation":"The Papez circuit connects the hippocampus, mammillary bodies, thalamus, and cingulate gyrus, linking memory and emotion.","kind":"mechanism","origin":"ai"},{"id":"limbic-system-emotion-memory~ai-3","moduleId":"limbic-system-emotion-memory","stem":"In Wernicke-Korsakoff syndrome, which structure is primarily affected due to thiamine deficiency?","options":[{"id":"a","text":"Hippocampus"},{"id":"b","text":"Amygdala"},{"id":"c","text":"Mammillary bodies"},{"id":"d","text":"Cingulate gyrus"}],"answerId":"c","explanation":"Thiamine deficiency primarily damages the mammillary bodies, leading to confusion, ataxia, and amnesia with confabulation.","kind":"recall","origin":"ai"},{"id":"limbic-system-emotion-memory~ai-4","moduleId":"limbic-system-emotion-memory","stem":"A patient presents with an inability to form new memories but retains old memories. Which structure is likely damaged?","options":[{"id":"a","text":"Amygdala"},{"id":"b","text":"Cingulate gyrus"},{"id":"c","text":"Hippocampus"},{"id":"d","text":"Mammillary bodies"}],"answerId":"c","explanation":"Bilateral hippocampal damage leads to anterograde amnesia, preventing the formation of new declarative memories while preserving old ones.","kind":"trap","origin":"ai"},{"id":"limbic-system-emotion-memory~ai-5","moduleId":"limbic-system-emotion-memory","stem":"How does the limbic system interact with the hypothalamus?","options":[{"id":"a","text":"It regulates motor functions"},{"id":"b","text":"It processes sensory information"},{"id":"c","text":"It links emotional responses to autonomic functions"},{"id":"d","text":"It stores long-term memories"}],"answerId":"c","explanation":"The limbic system links emotional responses processed by the amygdala with autonomic functions regulated by the hypothalamus.","kind":"integration","linkedModuleIds":["diencephalon-thalamus-hypothalamus"],"origin":"ai"},{"id":"limbic-system-emotion-memory~ai-6","moduleId":"limbic-system-emotion-memory","stem":"Which of the following best explains the phenomenon of smell-evoked memories?","options":[{"id":"a","text":"Olfactory information bypasses the thalamus"},{"id":"b","text":"Smell is processed in the frontal cortex"},{"id":"c","text":"Olfactory signals are only linked to the amygdala"},{"id":"d","text":"Memory is solely a function of the hippocampus"}],"answerId":"a","explanation":"Olfactory input goes directly to the limbic system without thalamic relay, explaining its strong connection to memory and emotion.","kind":"integration","linkedModuleIds":["gustatory-olfactory-pathways"],"origin":"ai"}],"neurons-glia-neurohistology":[{"id":"neurons-glia-neurohistology~ai-0","moduleId":"neurons-glia-neurohistology","stem":"Which type of neuron is primarily found in the retina?","options":[{"id":"a","text":"Multipolar"},{"id":"b","text":"Bipolar"},{"id":"c","text":"Pseudounipolar"},{"id":"d","text":"Unipolar"}],"answerId":"b","explanation":"Bipolar neurons are primarily found in sensory structures such as the retina and olfactory epithelium.","kind":"recall","origin":"ai"},{"id":"neurons-glia-neurohistology~ai-1","moduleId":"neurons-glia-neurohistology","stem":"What is the primary function of oligodendrocytes in the CNS?","options":[{"id":"a","text":"Support neuronal metabolism"},{"id":"b","text":"Myelinate multiple axons"},{"id":"c","text":"Act as immune cells"},{"id":"d","text":"Produce cerebrospinal fluid"}],"answerId":"b","explanation":"Oligodendrocytes myelinate multiple axons in the CNS, enhancing the speed of electrical conduction.","kind":"mechanism","origin":"ai"},{"id":"neurons-glia-neurohistology~ai-2","moduleId":"neurons-glia-neurohistology","stem":"Which glial cell type is responsible for forming the blood-brain barrier?","options":[{"id":"a","text":"Astrocytes"},{"id":"b","text":"Oligodendrocytes"},{"id":"c","text":"Microglia"},{"id":"d","text":"Ependymal cells"}],"answerId":"a","explanation":"Astrocytes contribute to the formation of the blood-brain barrier through their end-feet that surround blood vessels.","kind":"recall","origin":"ai"},{"id":"neurons-glia-neurohistology~ai-3","moduleId":"neurons-glia-neurohistology","stem":"A patient presents with ascending muscle weakness and areflexia. Which type of demyelination is most likely involved?","options":[{"id":"a","text":"CNS demyelination"},{"id":"b","text":"PNS demyelination"},{"id":"c","text":"Both CNS and PNS demyelination"},{"id":"d","text":"Neither"}],"answerId":"b","explanation":"Ascending muscle weakness and areflexia are characteristic of Guillain-Barré syndrome, which involves PNS demyelination.","kind":"clinical","origin":"ai"},{"id":"neurons-glia-neurohistology~ai-4","moduleId":"neurons-glia-neurohistology","stem":"What distinguishes the myelination process of Schwann cells from that of oligodendrocytes?","options":[{"id":"a","text":"One Schwann cell myelinates many axons"},{"id":"b","text":"One oligodendrocyte myelinates one axon"},{"id":"c","text":"One Schwann cell myelinates one internode"},{"id":"d","text":"Oligodendrocytes regenerate axons better"}],"answerId":"c","explanation":"One Schwann cell myelinates a single internode of one PNS axon, while oligodendrocytes can myelinate segments of many CNS axons.","kind":"trap","origin":"ai"},{"id":"neurons-glia-neurohistology~ai-5","moduleId":"neurons-glia-neurohistology","stem":"Which cell type is the primary immune cell in the CNS?","options":[{"id":"a","text":"Astrocytes"},{"id":"b","text":"Oligodendrocytes"},{"id":"c","text":"Microglia"},{"id":"d","text":"Ependymal cells"}],"answerId":"c","explanation":"Microglia are the resident immune cells in the CNS, acting as phagocytes.","kind":"recall","origin":"ai"},{"id":"neurons-glia-neurohistology~ai-6","moduleId":"neurons-glia-neurohistology","stem":"How does the loss of myelin affect neuronal conduction?","options":[{"id":"a","text":"Increases conduction speed"},{"id":"b","text":"Decreases conduction speed"},{"id":"c","text":"Has no effect"},{"id":"d","text":"Only affects sensory neurons"}],"answerId":"b","explanation":"Loss of myelin decreases conduction speed due to the disruption of saltatory conduction.","kind":"mechanism","origin":"ai"},{"id":"neurons-glia-neurohistology~ai-7","moduleId":"neurons-glia-neurohistology","stem":"How do astrocytes contribute to brain energy metabolism?","options":[{"id":"a","text":"By myelinating axons"},{"id":"b","text":"By forming the blood-brain barrier"},{"id":"c","text":"By buffering potassium ions"},{"id":"d","text":"By producing neurotransmitters"}],"answerId":"c","explanation":"Astrocytes buffer potassium ions, which is crucial for maintaining the ionic environment for neuronal function.","kind":"integration","linkedModuleIds":["brain-energy-metabolism"],"origin":"ai"},{"id":"neurons-glia-neurohistology~ai-8","moduleId":"neurons-glia-neurohistology","stem":"Which condition is characterized by demyelination of the CNS?","options":[{"id":"a","text":"Guillain-Barré syndrome"},{"id":"b","text":"Multiple sclerosis"},{"id":"c","text":"Amyotrophic lateral sclerosis"},{"id":"d","text":"Myasthenia gravis"}],"answerId":"b","explanation":"Multiple sclerosis is characterized by CNS demyelination, primarily affecting oligodendrocytes.","kind":"integration","linkedModuleIds":["cns-cellular-reactions"],"origin":"ai"}],"gustatory-olfactory-pathways":[{"id":"gustatory-olfactory-pathways~ai-0","moduleId":"gustatory-olfactory-pathways","stem":"Which cranial nerve is responsible for taste sensation from the anterior two-thirds of the tongue?","options":[{"id":"a","text":"CN VII (facial)"},{"id":"b","text":"CN IX (glossopharyngeal)"},{"id":"c","text":"CN X (vagus)"},{"id":"d","text":"CN I (olfactory)"}],"answerId":"a","explanation":"The facial nerve (CN VII) via the chorda tympani carries taste from the anterior two-thirds of the tongue.","kind":"recall","origin":"ai"},{"id":"gustatory-olfactory-pathways~ai-1","moduleId":"gustatory-olfactory-pathways","stem":"What distinguishes the olfactory pathway from other sensory pathways?","options":[{"id":"a","text":"It involves the thalamus"},{"id":"b","text":"It bypasses the thalamus"},{"id":"c","text":"It uses multiple cranial nerves"},{"id":"d","text":"It does not involve the cortex"}],"answerId":"b","explanation":"The olfactory pathway is unique as it bypasses the thalamus and connects directly to the cortex.","kind":"mechanism","origin":"ai"},{"id":"gustatory-olfactory-pathways~ai-2","moduleId":"gustatory-olfactory-pathways","stem":"A patient presents with anosmia after a head injury. Which structure is most likely damaged?","options":[{"id":"a","text":"Olfactory bulb"},{"id":"b","text":"Cribriform plate"},{"id":"c","text":"Thalamus"},{"id":"d","text":"Solitary nucleus"}],"answerId":"b","explanation":"Anosmia following head trauma is often due to shearing of the olfactory fibers at the cribriform plate.","kind":"clinical","origin":"ai"},{"id":"gustatory-olfactory-pathways~ai-3","moduleId":"gustatory-olfactory-pathways","stem":"Which of the following is a common cause of anosmia?","options":[{"id":"a","text":"Viral infection"},{"id":"b","text":"Taste bud damage"},{"id":"c","text":"Thalamic stroke"},{"id":"d","text":"Optic nerve injury"}],"answerId":"a","explanation":"Viral infections can damage the olfactory neurons and lead to anosmia.","kind":"trap","origin":"ai"},{"id":"gustatory-olfactory-pathways~ai-4","moduleId":"gustatory-olfactory-pathways","stem":"How does the olfactory system's direct connection to the limbic system affect emotional responses?","options":[{"id":"a","text":"It enhances visual memory"},{"id":"b","text":"It allows for rapid emotional processing"},{"id":"c","text":"It inhibits taste perception"},{"id":"d","text":"It increases auditory processing speed"}],"answerId":"b","explanation":"The direct connection of the olfactory system to the limbic system facilitates rapid emotional responses to smells.","kind":"integration","linkedModuleIds":["limbic-system-emotion-memory"],"origin":"ai"},{"id":"gustatory-olfactory-pathways~ai-5","moduleId":"gustatory-olfactory-pathways","stem":"Which cranial nerve is responsible for taste sensation from the posterior third of the tongue?","options":[{"id":"a","text":"CN VII (facial)"},{"id":"b","text":"CN IX (glossopharyngeal)"},{"id":"c","text":"CN X (vagus)"},{"id":"d","text":"CN I (olfactory)"}],"answerId":"b","explanation":"The glossopharyngeal nerve (CN IX) is responsible for taste sensation from the posterior third of the tongue.","kind":"recall","origin":"ai"},{"id":"gustatory-olfactory-pathways~ai-6","moduleId":"gustatory-olfactory-pathways","stem":"Which statement about sensory pathways is FALSE?","options":[{"id":"a","text":"All sensory modalities pass through the thalamus"},{"id":"b","text":"Olfaction bypasses the thalamus"},{"id":"c","text":"Taste signals relay through the thalamus"},{"id":"d","text":"Smell is the only sense with a thalamic relay"}],"answerId":"d","explanation":"Smell is unique in that it bypasses the thalamus, while all other senses relay through it.","kind":"trap","origin":"ai"},{"id":"gustatory-olfactory-pathways~ai-7","moduleId":"gustatory-olfactory-pathways","stem":"What is the primary function of the solitary nucleus in the gustatory pathway?","options":[{"id":"a","text":"Regulate olfactory signals"},{"id":"b","text":"Process taste information"},{"id":"c","text":"Control visual reflexes"},{"id":"d","text":"Integrate auditory signals"}],"answerId":"b","explanation":"The solitary nucleus processes taste information from the cranial nerves before relaying it to the thalamus.","kind":"mechanism","origin":"ai"},{"id":"gustatory-olfactory-pathways~ai-8","moduleId":"gustatory-olfactory-pathways","stem":"How does the structure of taste receptors relate to their function?","options":[{"id":"a","text":"They are located in the olfactory bulb"},{"id":"b","text":"They regenerate from basal stem cells"},{"id":"c","text":"They are exclusively in the brain"},{"id":"d","text":"They bypass the thalamus"}],"answerId":"b","explanation":"Taste receptors can regenerate from basal stem cells, allowing for continuous function and turnover.","kind":"integration","linkedModuleIds":["taste-olfaction-receptors"],"origin":"ai"}],"auditory-pathway-anatomy":[{"id":"auditory-pathway-anatomy~ai-0","moduleId":"auditory-pathway-anatomy","stem":"What structure in the ear amplifies sound before it reaches the cochlea?","options":[{"id":"a","text":"Tympanic membrane"},{"id":"b","text":"Ossicles"},{"id":"c","text":"Oval window"},{"id":"d","text":"Organ of Corti"}],"answerId":"b","explanation":"The ossicles (malleus, incus, stapes) amplify sound and match impedance before transmitting vibrations to the cochlea.","kind":"recall","origin":"ai"},{"id":"auditory-pathway-anatomy~ai-1","moduleId":"auditory-pathway-anatomy","stem":"Which part of the cochlea responds to high-frequency sounds?","options":[{"id":"a","text":"Apex"},{"id":"b","text":"Base"},{"id":"c","text":"Organ of Corti"},{"id":"d","text":"Oval window"}],"answerId":"b","explanation":"The base of the cochlea is tonotopically organized to respond to high frequencies due to its stiff basilar membrane.","kind":"recall","origin":"ai"},{"id":"auditory-pathway-anatomy~ai-2","moduleId":"auditory-pathway-anatomy","stem":"A patient presents with unilateral hearing loss. Which of the following findings would suggest a peripheral cause?","options":[{"id":"a","text":"Impaired sound localization"},{"id":"b","text":"Normal Rinne test"},{"id":"c","text":"Normal Weber test"},{"id":"d","text":"Unilateral deafness"}],"answerId":"d","explanation":"Unilateral deafness localizes to the ear or CN VIII, indicating a peripheral issue rather than a central lesion.","kind":"clinical","origin":"ai"},{"id":"auditory-pathway-anatomy~ai-3","moduleId":"auditory-pathway-anatomy","stem":"What is the primary role of the superior olivary nuclei in the auditory pathway?","options":[{"id":"a","text":"Sound amplification"},{"id":"b","text":"Sound localization"},{"id":"c","text":"Auditory signal relay"},{"id":"d","text":"Frequency discrimination"}],"answerId":"b","explanation":"The superior olivary nuclei compute sound localization by comparing interaural time and intensity differences.","kind":"mechanism","origin":"ai"},{"id":"auditory-pathway-anatomy~ai-4","moduleId":"auditory-pathway-anatomy","stem":"Which of the following statements about unilateral central auditory lesions is true?","options":[{"id":"a","text":"They cause deafness in the opposite ear."},{"id":"b","text":"They spare hearing in both ears."},{"id":"c","text":"They only affect sound localization."},{"id":"d","text":"They cause bilateral hearing loss."}],"answerId":"b","explanation":"Unilateral central lesions do not cause deafness in one ear due to the bilateral nature of the central auditory pathway.","kind":"trap","origin":"ai"},{"id":"auditory-pathway-anatomy~ai-5","moduleId":"auditory-pathway-anatomy","stem":"How does the medial geniculate nucleus function in the auditory pathway?","options":[{"id":"a","text":"It amplifies sound signals."},{"id":"b","text":"It relays auditory information to the cortex."},{"id":"c","text":"It processes sound frequency."},{"id":"d","text":"It integrates auditory reflexes."}],"answerId":"b","explanation":"The medial geniculate nucleus serves as the thalamic relay for auditory information before it reaches the primary auditory cortex.","kind":"mechanism","origin":"ai"},{"id":"auditory-pathway-anatomy~ai-6","moduleId":"auditory-pathway-anatomy","stem":"How does the auditory pathway connect to the brainstem anatomy?","options":[{"id":"a","text":"Cochlear nuclei are located in the thalamus."},{"id":"b","text":"The inferior colliculus integrates auditory reflexes."},{"id":"c","text":"The medial geniculate nucleus is part of the cortex."},{"id":"d","text":"The superior olivary nuclei are not involved in sound localization."}],"answerId":"b","explanation":"The inferior colliculus, located in the midbrain, integrates auditory reflexes and is a key relay in the auditory pathway.","kind":"integration","linkedModuleIds":["brainstem-anatomy-organization"],"origin":"ai"},{"id":"auditory-pathway-anatomy~ai-7","moduleId":"auditory-pathway-anatomy","stem":"Which structure in the auditory pathway is responsible for processing sound frequency before reaching the cortex?","options":[{"id":"a","text":"Cochlear nuclei"},{"id":"b","text":"Inferior colliculus"},{"id":"c","text":"Medial geniculate nucleus"},{"id":"d","text":"Superior olivary nuclei"}],"answerId":"c","explanation":"The medial geniculate nucleus processes and relays frequency-specific auditory information to the primary auditory cortex.","kind":"integration","linkedModuleIds":["diencephalon-thalamus-hypothalamus"],"origin":"ai"}],"taste-olfaction-receptors":[{"id":"taste-olfaction-receptors~ai-0","moduleId":"taste-olfaction-receptors","stem":"What type of cells are found in taste buds?","options":[{"id":"a","text":"True bipolar neurons"},{"id":"b","text":"Modified epithelial cells"},{"id":"c","text":"Sensory neurons"},{"id":"d","text":"Basal stem cells"}],"answerId":"b","explanation":"Taste buds consist of modified epithelial cells that function as taste receptors.","kind":"recall","origin":"ai"},{"id":"taste-olfaction-receptors~ai-1","moduleId":"taste-olfaction-receptors","stem":"Which cranial nerve is primarily responsible for taste sensation from the anterior two-thirds of the tongue?","options":[{"id":"a","text":"Cranial Nerve I"},{"id":"b","text":"Cranial Nerve VII"},{"id":"c","text":"Cranial Nerve IX"},{"id":"d","text":"Cranial Nerve X"}],"answerId":"b","explanation":"Cranial Nerve VII (facial nerve) carries taste sensations from the anterior two-thirds of the tongue.","kind":"recall","origin":"ai"},{"id":"taste-olfaction-receptors~ai-2","moduleId":"taste-olfaction-receptors","stem":"What is the mechanism of action for sweet taste perception?","options":[{"id":"a","text":"Ion channels"},{"id":"b","text":"G-protein-coupled receptors"},{"id":"c","text":"Direct neuronal stimulation"},{"id":"d","text":"Mechanical deformation"}],"answerId":"b","explanation":"Sweet taste perception is mediated by G-protein-coupled receptors (T1R family).","kind":"mechanism","origin":"ai"},{"id":"taste-olfaction-receptors~ai-3","moduleId":"taste-olfaction-receptors","stem":"A patient presents with loss of smell after a head injury. Which anatomical structure is likely damaged?","options":[{"id":"a","text":"Taste buds"},{"id":"b","text":"Olfactory bulb"},{"id":"c","text":"Cribriform plate"},{"id":"d","text":"Tongue papillae"}],"answerId":"c","explanation":"A fracture of the cribriform plate can shear olfactory nerves, leading to anosmia.","kind":"clinical","origin":"ai"},{"id":"taste-olfaction-receptors~ai-4","moduleId":"taste-olfaction-receptors","stem":"Which of the following statements about olfactory receptors is true?","options":[{"id":"a","text":"They are modified epithelial cells."},{"id":"b","text":"They do not regenerate."},{"id":"c","text":"They are true bipolar neurons."},{"id":"d","text":"They synapse in the thalamus."}],"answerId":"c","explanation":"Olfactory receptors are true bipolar neurons that can regenerate throughout life.","kind":"trap","origin":"ai"},{"id":"taste-olfaction-receptors~ai-5","moduleId":"taste-olfaction-receptors","stem":"How does the olfactory pathway differ from the gustatory pathway?","options":[{"id":"a","text":"Olfactory bypasses the thalamus, gustatory does not."},{"id":"b","text":"Both pathways use the same cranial nerves."},{"id":"c","text":"Gustatory receptors are true bipolar neurons."},{"id":"d","text":"Olfactory receptors are not regenerative."}],"answerId":"a","explanation":"The olfactory pathway bypasses the thalamus, while the gustatory pathway involves thalamic relay.","kind":"integration","linkedModuleIds":["gustatory-olfactory-pathways"],"origin":"ai"},{"id":"taste-olfaction-receptors~ai-6","moduleId":"taste-olfaction-receptors","stem":"Which taste quality is detected via ion channels?","options":[{"id":"a","text":"Bitter"},{"id":"b","text":"Sweet"},{"id":"c","text":"Umami"},{"id":"d","text":"Salty"}],"answerId":"d","explanation":"Salty taste is detected through ion channels that allow sodium ions to enter taste receptor cells.","kind":"recall","origin":"ai"},{"id":"taste-olfaction-receptors~ai-7","moduleId":"taste-olfaction-receptors","stem":"What role do basal stem cells play in the olfactory epithelium?","options":[{"id":"a","text":"They form taste buds."},{"id":"b","text":"They regenerate olfactory neurons."},{"id":"c","text":"They transmit smell signals."},{"id":"d","text":"They are involved in taste sensation."}],"answerId":"b","explanation":"Basal stem cells in the olfactory epithelium are responsible for regenerating olfactory receptor neurons.","kind":"recall","origin":"ai"},{"id":"taste-olfaction-receptors~ai-8","moduleId":"taste-olfaction-receptors","stem":"Which cranial nerve is responsible for taste sensation from the posterior one-third of the tongue?","options":[{"id":"a","text":"Cranial Nerve I"},{"id":"b","text":"Cranial Nerve VII"},{"id":"c","text":"Cranial Nerve IX"},{"id":"d","text":"Cranial Nerve X"}],"answerId":"c","explanation":"Cranial Nerve IX (glossopharyngeal nerve) carries taste sensations from the posterior one-third of the tongue.","kind":"recall","origin":"ai"}],"cerebellum-anatomy-function":[{"id":"cerebellum-anatomy-function~ai-0","moduleId":"cerebellum-anatomy-function","stem":"Which of the following is a classic sign of a cerebrocerebellar lesion?","options":[{"id":"a","text":"Intention tremor"},{"id":"b","text":"Truncal ataxia"},{"id":"c","text":"Broad-based gait"},{"id":"d","text":"Dysdiadochokinesia"}],"answerId":"a","explanation":"Intention tremor is specifically associated with lesions in the cerebrocerebellum, affecting skilled limb movements.","kind":"recall","origin":"ai"},{"id":"cerebellum-anatomy-function~ai-1","moduleId":"cerebellum-anatomy-function","stem":"What is the primary function of the vestibulocerebellum?","options":[{"id":"a","text":"Coordination of skilled movements"},{"id":"b","text":"Regulation of balance and eye movements"},{"id":"c","text":"Initiation of movement"},{"id":"d","text":"Control of muscle tone"}],"answerId":"b","explanation":"The vestibulocerebellum is primarily responsible for balance and eye movement regulation.","kind":"recall","origin":"ai"},{"id":"cerebellum-anatomy-function~ai-2","moduleId":"cerebellum-anatomy-function","stem":"A patient presents with truncal ataxia and nystagmus. Which part of the cerebellum is likely affected?","options":[{"id":"a","text":"Cerebrocerebellum"},{"id":"b","text":"Spinocerebellum"},{"id":"c","text":"Vestibulocerebellum"},{"id":"d","text":"Corticospinal tract"}],"answerId":"c","explanation":"Truncal ataxia and nystagmus indicate a lesion in the vestibulocerebellum.","kind":"clinical","origin":"ai"},{"id":"cerebellum-anatomy-function~ai-3","moduleId":"cerebellum-anatomy-function","stem":"Which mechanism explains why cerebellar lesions produce ipsilateral signs?","options":[{"id":"a","text":"Corticospinal tract crosses twice"},{"id":"b","text":"Cerebellar output does not cross"},{"id":"c","text":"Cerebellar input is contralateral"},{"id":"d","text":"Cerebellar lesions affect both hemispheres"}],"answerId":"a","explanation":"Cerebellar output crosses to the contralateral cortex and then the corticospinal tract crosses again, resulting in ipsilateral signs.","kind":"mechanism","origin":"ai"},{"id":"cerebellum-anatomy-function~ai-4","moduleId":"cerebellum-anatomy-function","stem":"A patient exhibits dysdiadochokinesia and scanning speech. Which type of cerebellar lesion is most likely?","options":[{"id":"a","text":"Cerebrocerebellar"},{"id":"b","text":"Spinocerebellar"},{"id":"c","text":"Vestibulocerebellar"},{"id":"d","text":"Corticospinal"}],"answerId":"a","explanation":"Dysdiadochokinesia and scanning speech are indicative of cerebrocerebellar lesions.","kind":"clinical","origin":"ai"},{"id":"cerebellum-anatomy-function~ai-5","moduleId":"cerebellum-anatomy-function","stem":"How does the cerebellum contribute to motor learning?","options":[{"id":"a","text":"By initiating movements"},{"id":"b","text":"By timing and coordinating movements"},{"id":"c","text":"By regulating muscle tone"},{"id":"d","text":"By controlling reflexes"}],"answerId":"b","explanation":"The cerebellum coordinates and times movements, which is essential for motor learning.","kind":"mechanism","origin":"ai"},{"id":"cerebellum-anatomy-function~ai-6","moduleId":"cerebellum-anatomy-function","stem":"A patient with a history of alcohol use presents with gait ataxia. Which cerebellar region is likely affected?","options":[{"id":"a","text":"Cerebrocerebellum"},{"id":"b","text":"Spinocerebellum"},{"id":"c","text":"Vestibulocerebellum"},{"id":"d","text":"Corticospinal tract"}],"answerId":"b","explanation":"Alcohol primarily affects the spinocerebellum, leading to gait ataxia.","kind":"clinical","origin":"ai"},{"id":"cerebellum-anatomy-function~ai-7","moduleId":"cerebellum-anatomy-function","stem":"How do cerebellar lesions differ from cortical lesions in terms of symptom laterality?","options":[{"id":"a","text":"Cerebellar lesions cause contralateral symptoms"},{"id":"b","text":"Cerebellar lesions cause ipsilateral symptoms"},{"id":"c","text":"Cerebellar lesions have no lateralization"},{"id":"d","text":"Cortical lesions cause bilateral symptoms"}],"answerId":"b","explanation":"Cerebellar lesions produce ipsilateral symptoms due to the double crossing of outputs.","kind":"trap","origin":"ai"},{"id":"cerebellum-anatomy-function~ai-8","moduleId":"cerebellum-anatomy-function","stem":"Which of the following best describes the relationship between the cerebellum and the basal ganglia?","options":[{"id":"a","text":"They both initiate movement"},{"id":"b","text":"They both regulate muscle tone"},{"id":"c","text":"They coordinate different aspects of movement"},{"id":"d","text":"They have no functional relationship"}],"answerId":"c","explanation":"The cerebellum and basal ganglia coordinate different aspects of movement, with the cerebellum focusing on timing and coordination.","kind":"integration","linkedModuleIds":["basal-ganglia-cerebellum"],"origin":"ai"}],"basal-ganglia-circuitry":[{"id":"basal-ganglia-circuitry~ai-0","moduleId":"basal-ganglia-circuitry","stem":"Which structure in the basal ganglia is primarily responsible for tonically inhibiting the motor thalamus?","options":[{"id":"a","text":"Striatum"},{"id":"b","text":"Subthalamic nucleus"},{"id":"c","text":"Globus pallidus internus"},{"id":"d","text":"Substantia nigra pars compacta"}],"answerId":"c","explanation":"The globus pallidus internus (GPi) is the output nucleus that tonically inhibits the motor thalamus, acting as a brake on movement.","kind":"recall","origin":"ai"},{"id":"basal-ganglia-circuitry~ai-1","moduleId":"basal-ganglia-circuitry","stem":"In Parkinson's disease, which pathway is primarily underactive due to dopamine loss?","options":[{"id":"a","text":"Direct pathway"},{"id":"b","text":"Indirect pathway"},{"id":"c","text":"Corticospinal tract"},{"id":"d","text":"Subthalamic pathway"}],"answerId":"a","explanation":"Dopamine loss in Parkinson's disease leads to underactivity of the direct pathway, resulting in reduced movement.","kind":"mechanism","origin":"ai"},{"id":"basal-ganglia-circuitry~ai-2","moduleId":"basal-ganglia-circuitry","stem":"A patient presents with bradykinesia and rigidity. Which finding would you expect on examination?","options":[{"id":"a","text":"Chorea"},{"id":"b","text":"Resting tremor"},{"id":"c","text":"Hemiballismus"},{"id":"d","text":"Dystonia"}],"answerId":"b","explanation":"Bradykinesia and rigidity are classic signs of Parkinson's disease, which may also include a resting tremor.","kind":"recall","origin":"ai"},{"id":"basal-ganglia-circuitry~ai-3","moduleId":"basal-ganglia-circuitry","stem":"What is the primary effect of dopamine on the direct pathway of the basal ganglia?","options":[{"id":"a","text":"Inhibits the pathway"},{"id":"b","text":"Excites the pathway"},{"id":"c","text":"Has no effect"},{"id":"d","text":"Increases inhibition of thalamus"}],"answerId":"b","explanation":"Dopamine from the substantia nigra pars compacta excites the direct pathway, promoting movement.","kind":"mechanism","origin":"ai"},{"id":"basal-ganglia-circuitry~ai-4","moduleId":"basal-ganglia-circuitry","stem":"Which statement regarding the basal ganglia is true?","options":[{"id":"a","text":"They directly command muscle contraction."},{"id":"b","text":"They modulate a tonic inhibitory brake on the thalamus."},{"id":"c","text":"They are solely responsible for initiating movement."},{"id":"d","text":"They only inhibit unwanted movements."}],"answerId":"b","explanation":"The basal ganglia modulate movement by selecting and scaling it through a tonic inhibitory brake on the thalamus, rather than directly commanding muscle contraction.","kind":"trap","origin":"ai"},{"id":"basal-ganglia-circuitry~ai-5","moduleId":"basal-ganglia-circuitry","stem":"A patient with hemiballismus would most likely have a lesion in which structure?","options":[{"id":"a","text":"Striatum"},{"id":"b","text":"Globus pallidus"},{"id":"c","text":"Subthalamic nucleus"},{"id":"d","text":"Substantia nigra"}],"answerId":"c","explanation":"Hemiballismus is caused by a lesion in the subthalamic nucleus, leading to wild flinging movements of the contralateral limbs.","kind":"recall","origin":"ai"},{"id":"basal-ganglia-circuitry~ai-6","moduleId":"basal-ganglia-circuitry","stem":"How does the indirect pathway of the basal ganglia affect motor control?","options":[{"id":"a","text":"Facilitates movement"},{"id":"b","text":"Inhibits movement"},{"id":"c","text":"Has no effect on movement"},{"id":"d","text":"Enhances muscle contraction"}],"answerId":"b","explanation":"The indirect pathway inhibits movement by increasing the inhibition of the thalamus, thus tightening the brake on movement.","kind":"mechanism","origin":"ai"},{"id":"basal-ganglia-circuitry~ai-7","moduleId":"basal-ganglia-circuitry","stem":"Which condition is characterized by a loss of striatal neurons leading to chorea?","options":[{"id":"a","text":"Parkinson's disease"},{"id":"b","text":"Huntington's disease"},{"id":"c","text":"Hemiballismus"},{"id":"d","text":"Dystonia"}],"answerId":"b","explanation":"Huntington's disease is characterized by the degeneration of striatal neurons, resulting in chorea.","kind":"recall","origin":"ai"},{"id":"basal-ganglia-circuitry~ai-8","moduleId":"basal-ganglia-circuitry","stem":"In the context of basal ganglia function, how does dopamine relate to the corticospinal tract?","options":[{"id":"a","text":"Dopamine directly stimulates the corticospinal tract."},{"id":"b","text":"Dopamine modulates basal ganglia output, which influences the corticospinal tract."},{"id":"c","text":"Dopamine has no effect on the corticospinal tract."},{"id":"d","text":"Dopamine inhibits the corticospinal tract."}],"answerId":"b","explanation":"Dopamine modulates the output of the basal ganglia, which in turn influences the activity of the corticospinal tract, affecting voluntary movement.","kind":"integration","linkedModuleIds":["motor-system-corticospinal-control"],"origin":"ai"},{"id":"basal-ganglia-circuitry~ai-9","moduleId":"basal-ganglia-circuitry","stem":"How does the modulation of movement by the basal ganglia relate to the function of the cerebellum?","options":[{"id":"a","text":"Both structures initiate movement."},{"id":"b","text":"The basal ganglia select and scale movement, while the cerebellum coordinates it."},{"id":"c","text":"Both structures inhibit unwanted movements."},{"id":"d","text":"The cerebellum has no role in movement control."}],"answerId":"b","explanation":"The basal ganglia are involved in selecting and scaling movements, while the cerebellum coordinates and fine-tunes those movements for precision.","kind":"integration","linkedModuleIds":["basal-ganglia-cerebellum"],"origin":"ai"}],"pharmacokinetics-adme":[{"id":"pharmacokinetics-adme~ai-0","moduleId":"pharmacokinetics-adme","stem":"What is the primary reason for low oral bioavailability of a drug?","options":[{"id":"a","text":"Extensive first-pass metabolism"},{"id":"b","text":"High plasma protein binding"},{"id":"c","text":"Rapid renal clearance"},{"id":"d","text":"Low lipid solubility"}],"answerId":"a","explanation":"Low oral bioavailability is primarily due to extensive first-pass metabolism in the gut and liver.","kind":"recall","origin":"ai"},{"id":"pharmacokinetics-adme~ai-1","moduleId":"pharmacokinetics-adme","stem":"Which parameter is used to determine the loading dose of a drug?","options":[{"id":"a","text":"Clearance"},{"id":"b","text":"Volume of distribution"},{"id":"c","text":"Half-life"},{"id":"d","text":"Bioavailability"}],"answerId":"b","explanation":"The loading dose is calculated using the volume of distribution and the target concentration.","kind":"recall","origin":"ai"},{"id":"pharmacokinetics-adme~ai-2","moduleId":"pharmacokinetics-adme","stem":"A patient on phenytoin experiences toxicity after a small dose increase. What pharmacokinetic principle explains this?","options":[{"id":"a","text":"First-order kinetics"},{"id":"b","text":"Zero-order kinetics"},{"id":"c","text":"High bioavailability"},{"id":"d","text":"Increased clearance"}],"answerId":"b","explanation":"Phenytoin exhibits zero-order kinetics, where small dose increases can cause disproportionately large increases in drug concentration.","kind":"mechanism","origin":"ai"},{"id":"pharmacokinetics-adme~ai-3","moduleId":"pharmacokinetics-adme","stem":"What is the effect of renal impairment on drug clearance?","options":[{"id":"a","text":"Increased clearance of renally-excreted drugs"},{"id":"b","text":"Decreased clearance of renally-excreted drugs"},{"id":"c","text":"No effect on clearance"},{"id":"d","text":"Increased hepatic metabolism"}],"answerId":"b","explanation":"Renal impairment leads to decreased clearance of renally-excreted drugs, resulting in drug accumulation.","kind":"clinical","origin":"ai"},{"id":"pharmacokinetics-adme~ai-4","moduleId":"pharmacokinetics-adme","stem":"Which of the following drugs is most likely to exhibit zero-order kinetics?","options":[{"id":"a","text":"Aspirin at low doses"},{"id":"b","text":"Phenytoin"},{"id":"c","text":"Ibuprofen"},{"id":"d","text":"Acetaminophen"}],"answerId":"b","explanation":"Phenytoin is known to exhibit zero-order kinetics, especially at therapeutic concentrations.","kind":"trap","origin":"ai"},{"id":"pharmacokinetics-adme~ai-5","moduleId":"pharmacokinetics-adme","stem":"How does the volume of distribution (Vd) affect drug dosing in patients with kidney disease?","options":[{"id":"a","text":"It determines the maintenance dose only"},{"id":"b","text":"It is irrelevant to dosing"},{"id":"c","text":"It influences both loading and maintenance doses"},{"id":"d","text":"It only affects renal clearance"}],"answerId":"c","explanation":"The volume of distribution influences both loading and maintenance doses, especially in patients with altered pharmacokinetics due to kidney disease.","kind":"integration","linkedModuleIds":["drug-dosing-ckd"],"origin":"ai"},{"id":"pharmacokinetics-adme~ai-6","moduleId":"pharmacokinetics-adme","stem":"What is the relationship between drug metabolism and drug interactions?","options":[{"id":"a","text":"Metabolism does not affect interactions"},{"id":"b","text":"All drug interactions are due to renal clearance"},{"id":"c","text":"Cytochrome P450 metabolism can lead to interactions"},{"id":"d","text":"Only first-order drugs interact"}],"answerId":"c","explanation":"Cytochrome P450 metabolism is a major pathway for drug interactions, as many drugs are metabolized by the same enzymes.","kind":"integration","linkedModuleIds":["drug-interactions-mechanisms"],"origin":"ai"}],"higher-cortical-functions":[{"id":"higher-cortical-functions~ai-0","moduleId":"higher-cortical-functions","stem":"What is the primary function of the right parietal association cortex?","options":[{"id":"a","text":"Language processing"},{"id":"b","text":"Visuospatial processing"},{"id":"c","text":"Motor coordination"},{"id":"d","text":"Auditory processing"}],"answerId":"b","explanation":"The right parietal association cortex is primarily involved in visuospatial processing, which includes attention to the whole environment.","kind":"recall","origin":"ai"},{"id":"higher-cortical-functions~ai-1","moduleId":"higher-cortical-functions","stem":"A patient presents with an inability to recognize familiar faces despite having intact vision. What is the most likely diagnosis?","options":[{"id":"a","text":"Agnosia"},{"id":"b","text":"Apraxia"},{"id":"c","text":"Neglect"},{"id":"d","text":"Aphasia"}],"answerId":"a","explanation":"This condition is known as prosopagnosia, a type of agnosia where the patient cannot recognize faces despite normal visual function.","kind":"clinical","origin":"ai"},{"id":"higher-cortical-functions~ai-2","moduleId":"higher-cortical-functions","stem":"Which of the following symptoms is most indicative of a left parietal lesion?","options":[{"id":"a","text":"Inability to recognize objects"},{"id":"b","text":"Ignoring the left side of space"},{"id":"c","text":"Inability to perform learned movements"},{"id":"d","text":"Disinhibition and personality change"}],"answerId":"c","explanation":"Apraxia, the inability to perform learned skilled movements, is typically associated with lesions in the left parietal cortex.","kind":"recall","origin":"ai"},{"id":"higher-cortical-functions~ai-3","moduleId":"higher-cortical-functions","stem":"What is the primary role of the prefrontal cortex?","options":[{"id":"a","text":"Language processing"},{"id":"b","text":"Executive function"},{"id":"c","text":"Visuospatial awareness"},{"id":"d","text":"Sensory integration"}],"answerId":"b","explanation":"The prefrontal cortex is responsible for executive functions such as planning, working memory, and impulse control.","kind":"recall","origin":"ai"},{"id":"higher-cortical-functions~ai-4","moduleId":"higher-cortical-functions","stem":"A patient exhibits poor planning and personality changes after a head injury. Which area of the brain is likely affected?","options":[{"id":"a","text":"Right parietal cortex"},{"id":"b","text":"Left temporal cortex"},{"id":"c","text":"Prefrontal cortex"},{"id":"d","text":"Occipital cortex"}],"answerId":"c","explanation":"Damage to the prefrontal cortex can lead to executive dysfunction, including poor planning and personality changes.","kind":"clinical","origin":"ai"},{"id":"higher-cortical-functions~ai-5","moduleId":"higher-cortical-functions","stem":"How does a right parietal lesion typically present clinically?","options":[{"id":"a","text":"Aphasia with right-sided weakness"},{"id":"b","text":"Inability to recognize faces"},{"id":"c","text":"Ignoring the left half of space"},{"id":"d","text":"Disinhibition and poor planning"}],"answerId":"c","explanation":"A right parietal lesion often results in hemispatial neglect, where the patient ignores the left side of space.","kind":"recall","origin":"ai"},{"id":"higher-cortical-functions~ai-6","moduleId":"higher-cortical-functions","stem":"How does the dominant hemisphere contribute to language processing?","options":[{"id":"a","text":"It integrates visuospatial information"},{"id":"b","text":"It controls emotional expression"},{"id":"c","text":"It processes language and skilled praxis"},{"id":"d","text":"It manages sensory input"}],"answerId":"c","explanation":"The dominant hemisphere, usually the left, is responsible for language processing and skilled praxis.","kind":"integration","linkedModuleIds":["cortical-areas-language"],"origin":"ai"},{"id":"higher-cortical-functions~ai-7","moduleId":"higher-cortical-functions","stem":"What type of neglect is associated with a right parietal lesion?","options":[{"id":"a","text":"Right-sided neglect"},{"id":"b","text":"Left-sided neglect"},{"id":"c","text":"Bilateral neglect"},{"id":"d","text":"Visual neglect"}],"answerId":"b","explanation":"A right parietal lesion typically results in left-sided neglect, where the patient fails to attend to the left side of space.","kind":"integration","linkedModuleIds":["hrp1-neglect-emotional-abuse-safeguarding"],"origin":"ai"}],"sleep-circadian-rhythms":[{"id":"sleep-circadian-rhythms~ai-0","moduleId":"sleep-circadian-rhythms","stem":"What is the primary neurotransmitter involved in promoting wakefulness and inhibiting REM sleep?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"Serotonin"},{"id":"c","text":"Orexin"},{"id":"d","text":"Acetylcholine"}],"answerId":"c","explanation":"Orexin (hypocretin) is crucial for maintaining wakefulness and preventing REM sleep intrusions.","kind":"recall","origin":"ai"},{"id":"sleep-circadian-rhythms~ai-1","moduleId":"sleep-circadian-rhythms","stem":"Which EEG finding is characteristic of N2 NREM sleep?","options":[{"id":"a","text":"Delta waves"},{"id":"b","text":"Sleep spindles and K-complexes"},{"id":"c","text":"Alpha waves"},{"id":"d","text":"Theta waves"}],"answerId":"b","explanation":"N2 NREM sleep is defined by the presence of sleep spindles and K-complexes on EEG.","kind":"recall","origin":"ai"},{"id":"sleep-circadian-rhythms~ai-2","moduleId":"sleep-circadian-rhythms","stem":"A patient presents with excessive daytime sleepiness and episodes of sudden muscle weakness. What is the most likely diagnosis?","options":[{"id":"a","text":"Sleep apnea"},{"id":"b","text":"Narcolepsy"},{"id":"c","text":"Insomnia"},{"id":"d","text":"Restless legs syndrome"}],"answerId":"b","explanation":"Excessive daytime sleepiness with cataplexy is characteristic of narcolepsy due to loss of orexin neurons.","kind":"clinical","origin":"ai"},{"id":"sleep-circadian-rhythms~ai-3","moduleId":"sleep-circadian-rhythms","stem":"During which stage of sleep does the body experience muscle atonia?","options":[{"id":"a","text":"N1"},{"id":"b","text":"N2"},{"id":"c","text":"N3"},{"id":"d","text":"REM"}],"answerId":"d","explanation":"REM sleep is characterized by muscle atonia, preventing the acting out of dreams.","kind":"recall","origin":"ai"},{"id":"sleep-circadian-rhythms~ai-4","moduleId":"sleep-circadian-rhythms","stem":"Which of the following correctly describes the EEG pattern during REM sleep?","options":[{"id":"a","text":"High-voltage slow waves"},{"id":"b","text":"Low-voltage fast waves"},{"id":"c","text":"Mixed frequency waves"},{"id":"d","text":"Theta waves"}],"answerId":"b","explanation":"REM sleep shows a low-voltage, fast EEG pattern that resembles wakefulness, hence the term 'paradoxical sleep'.","kind":"trap","origin":"ai"},{"id":"sleep-circadian-rhythms~ai-5","moduleId":"sleep-circadian-rhythms","stem":"How does melatonin influence sleep onset?","options":[{"id":"a","text":"Increases heart rate"},{"id":"b","text":"Inhibits the SCN"},{"id":"c","text":"Promotes sleep in darkness"},{"id":"d","text":"Suppresses REM sleep"}],"answerId":"c","explanation":"Melatonin is released by the pineal gland in darkness, promoting sleep onset.","kind":"mechanism","origin":"ai"},{"id":"sleep-circadian-rhythms~ai-6","moduleId":"sleep-circadian-rhythms","stem":"How does the SCN influence the release of melatonin?","options":[{"id":"a","text":"By stimulating the adrenal cortex"},{"id":"b","text":"By inhibiting the pineal gland during light exposure"},{"id":"c","text":"By directly releasing melatonin"},{"id":"d","text":"By activating the reticular activating system"}],"answerId":"b","explanation":"The SCN signals the pineal gland to inhibit melatonin release in response to light, regulating circadian rhythms.","kind":"integration","linkedModuleIds":["reticular-activating-system-consciousness"],"origin":"ai"},{"id":"sleep-circadian-rhythms~ai-7","moduleId":"sleep-circadian-rhythms","stem":"What is the relationship between sleep architecture and cortisol levels?","options":[{"id":"a","text":"Cortisol promotes NREM sleep"},{"id":"b","text":"Cortisol levels peak during REM sleep"},{"id":"c","text":"Cortisol levels are lowest during N3 sleep"},{"id":"d","text":"Cortisol inhibits sleep onset"}],"answerId":"c","explanation":"Cortisol levels are typically lowest during deep N3 sleep, which is when restorative processes occur.","kind":"integration","linkedModuleIds":["hen1-cortisol-hpa-axis"],"origin":"ai"}],"vestibular-system-physiology":[{"id":"vestibular-system-physiology~ai-0","moduleId":"vestibular-system-physiology","stem":"Which part of the vestibular apparatus detects angular acceleration?","options":[{"id":"a","text":"Otolith organs"},{"id":"b","text":"Semicircular canals"},{"id":"c","text":"Cochlea"},{"id":"d","text":"Auditory nerve"}],"answerId":"b","explanation":"The semicircular canals are responsible for detecting angular (rotational) acceleration.","kind":"recall","origin":"ai"},{"id":"vestibular-system-physiology~ai-1","moduleId":"vestibular-system-physiology","stem":"What is the primary function of the vestibulo-ocular reflex (VOR)?","options":[{"id":"a","text":"To maintain balance during walking"},{"id":"b","text":"To stabilize gaze during head movement"},{"id":"c","text":"To detect sound frequency"},{"id":"d","text":"To sense linear acceleration"}],"answerId":"b","explanation":"The VOR stabilizes gaze by moving the eyes in the opposite direction of head movement.","kind":"mechanism","origin":"ai"},{"id":"vestibular-system-physiology~ai-2","moduleId":"vestibular-system-physiology","stem":"A patient experiences vertigo triggered by head position changes. Which condition is most likely?","options":[{"id":"a","text":"Vestibular neuritis"},{"id":"b","text":"Benign paroxysmal positional vertigo (BPPV)"},{"id":"c","text":"Meniere's disease"},{"id":"d","text":"Acoustic neuroma"}],"answerId":"b","explanation":"BPPV is characterized by brief episodes of vertigo triggered by specific head positions due to displaced otoliths.","kind":"clinical","origin":"ai"},{"id":"vestibular-system-physiology~ai-3","moduleId":"vestibular-system-physiology","stem":"In a caloric test, cold water is introduced into one ear. What is the expected response?","options":[{"id":"a","text":"Nystagmus towards the irrigated ear"},{"id":"b","text":"Nystagmus away from the irrigated ear"},{"id":"c","text":"No nystagmus"},{"id":"d","text":"Dizziness without nystagmus"}],"answerId":"b","explanation":"Cold water irrigation causes nystagmus towards the opposite ear due to the vestibulo-ocular reflex.","kind":"recall","origin":"ai"},{"id":"vestibular-system-physiology~ai-4","moduleId":"vestibular-system-physiology","stem":"A patient presents with nystagmus and vertigo. Which finding would suggest a peripheral vestibular disorder?","options":[{"id":"a","text":"Nystagmus that persists in a fixed position"},{"id":"b","text":"Nystagmus with a fast phase towards the affected side"},{"id":"c","text":"Nystagmus that fatigues with repeated testing"},{"id":"d","text":"Nystagmus with a central cause"}],"answerId":"c","explanation":"Peripheral vestibular disorders typically show nystagmus that fatigues with repeated testing.","kind":"trap","origin":"ai"},{"id":"vestibular-system-physiology~ai-5","moduleId":"vestibular-system-physiology","stem":"How do the semicircular canals and otolith organs differ in function?","options":[{"id":"a","text":"Both detect linear acceleration"},{"id":"b","text":"Both detect angular acceleration"},{"id":"c","text":"Semicircular canals detect angular acceleration; otoliths detect linear acceleration"},{"id":"d","text":"Otolith organs detect sound frequency"}],"answerId":"c","explanation":"Semicircular canals detect angular acceleration, while otolith organs detect linear acceleration and head tilt.","kind":"trap","origin":"ai"},{"id":"vestibular-system-physiology~ai-6","moduleId":"vestibular-system-physiology","stem":"How does the vestibular system integrate with the brainstem motor tracts during balance maintenance?","options":[{"id":"a","text":"It only sends signals to the cerebellum"},{"id":"b","text":"It coordinates eye movements with posture adjustments"},{"id":"c","text":"It has no connection with motor tracts"},{"id":"d","text":"It solely relies on visual input for balance"}],"answerId":"b","explanation":"The vestibular system integrates with brainstem motor tracts to coordinate eye movements and postural adjustments for balance.","kind":"integration","linkedModuleIds":["brainstem-descending-motor-tracts"],"origin":"ai"},{"id":"vestibular-system-physiology~ai-7","moduleId":"vestibular-system-physiology","stem":"What is the relationship between hair cell function and vestibular disorders?","options":[{"id":"a","text":"Hair cells are not involved in vestibular function"},{"id":"b","text":"Hair cells detect sound frequencies only"},{"id":"c","text":"Damage to hair cells can lead to vertigo and balance issues"},{"id":"d","text":"Hair cells only affect vision"}],"answerId":"c","explanation":"Damage to hair cells in the vestibular system can disrupt balance and lead to symptoms like vertigo.","kind":"integration","linkedModuleIds":["inner-ear-hair-cell-histology"],"origin":"ai"}],"consciousness-attention":[{"id":"consciousness-attention~ai-0","moduleId":"consciousness-attention","stem":"What is the primary function of the ascending reticular activating system (ARAS)?","options":[{"id":"a","text":"To process sensory information"},{"id":"b","text":"To regulate sleep cycles"},{"id":"c","text":"To maintain arousal and wakefulness"},{"id":"d","text":"To facilitate motor coordination"}],"answerId":"c","explanation":"The ARAS is crucial for maintaining arousal and wakefulness by projecting to the thalamus and cortex.","kind":"recall","origin":"ai"},{"id":"consciousness-attention~ai-1","moduleId":"consciousness-attention","stem":"Which of the following findings is characteristic of a vegetative state?","options":[{"id":"a","text":"Unresponsive to stimuli"},{"id":"b","text":"Eyes closed and unrousable"},{"id":"c","text":"Sleep-wake cycles with no awareness"},{"id":"d","text":"Consistent verbal responses"}],"answerId":"c","explanation":"A vegetative state is defined by the presence of sleep-wake cycles but absence of awareness.","kind":"recall","origin":"ai"},{"id":"consciousness-attention~ai-2","moduleId":"consciousness-attention","stem":"What is the Glasgow Coma Scale (GCS) used to assess?","options":[{"id":"a","text":"Cognitive function"},{"id":"b","text":"Depth of impaired consciousness"},{"id":"c","text":"Motor coordination"},{"id":"d","text":"Sensory perception"}],"answerId":"b","explanation":"The GCS assesses the depth of impaired consciousness based on eye, verbal, and motor responses.","kind":"recall","origin":"ai"},{"id":"consciousness-attention~ai-3","moduleId":"consciousness-attention","stem":"A patient presents with a small brainstem lesion and is in a coma. What is the most likely mechanism?","options":[{"id":"a","text":"Bilateral cortical damage"},{"id":"b","text":"Interruption of the ARAS"},{"id":"c","text":"Unilateral cortical stroke"},{"id":"d","text":"Severe metabolic derangement"}],"answerId":"b","explanation":"A small brainstem lesion can interrupt the ARAS, leading to coma due to loss of both arousal and awareness.","kind":"mechanism","origin":"ai"},{"id":"consciousness-attention~ai-4","moduleId":"consciousness-attention","stem":"Which of the following statements is true regarding coma?","options":[{"id":"a","text":"A single large unilateral stroke can cause coma"},{"id":"b","text":"Coma requires bilateral hemispheric dysfunction"},{"id":"c","text":"Coma is reversible in all cases"},{"id":"d","text":"Arousal is preserved in coma"}],"answerId":"b","explanation":"Coma requires either a brainstem lesion or diffuse bilateral hemispheric dysfunction; a single unilateral stroke does not cause coma.","kind":"trap","origin":"ai"},{"id":"consciousness-attention~ai-5","moduleId":"consciousness-attention","stem":"How does attention relate to consciousness as described in the module?","options":[{"id":"a","text":"It is independent of arousal"},{"id":"b","text":"It is regulated by the brainstem only"},{"id":"c","text":"It involves a frontoparietal network"},{"id":"d","text":"It requires bilateral cortical function"}],"answerId":"c","explanation":"Attention involves a frontoparietal network, with the right hemisphere dominant for spatial attention.","kind":"recall","origin":"ai"},{"id":"consciousness-attention~ai-6","moduleId":"consciousness-attention","stem":"How does the understanding of consciousness in this module integrate with the disorders of consciousness module?","options":[{"id":"a","text":"Both modules focus solely on arousal"},{"id":"b","text":"Disorders of consciousness are explained through the loss of arousal and awareness"},{"id":"c","text":"The GCS is irrelevant to disorders of consciousness"},{"id":"d","text":"Attention mechanisms are unrelated to consciousness"}],"answerId":"b","explanation":"The disorders of consciousness module builds on the understanding that consciousness involves both arousal and awareness.","kind":"integration","linkedModuleIds":["disorders-of-consciousness"],"origin":"ai"},{"id":"consciousness-attention~ai-7","moduleId":"consciousness-attention","stem":"Which aspect of consciousness is primarily assessed by the Glasgow Coma Scale?","options":[{"id":"a","text":"Arousal only"},{"id":"b","text":"Awareness only"},{"id":"c","text":"Both arousal and awareness"},{"id":"d","text":"Motor function only"}],"answerId":"c","explanation":"The Glasgow Coma Scale assesses both arousal and awareness through eye, verbal, and motor responses.","kind":"integration","linkedModuleIds":["disorders-of-consciousness"],"origin":"ai"}],"autonomic-nervous-system":[{"id":"autonomic-nervous-system~ai-0","moduleId":"autonomic-nervous-system","stem":"What neurotransmitter is released by all preganglionic neurons in the autonomic nervous system?","options":[{"id":"a","text":"Norepinephrine"},{"id":"b","text":"Acetylcholine"},{"id":"c","text":"Dopamine"},{"id":"d","text":"Serotonin"}],"answerId":"b","explanation":"All preganglionic neurons in both the sympathetic and parasympathetic divisions release acetylcholine onto nicotinic receptors.","kind":"recall","origin":"ai"},{"id":"autonomic-nervous-system~ai-1","moduleId":"autonomic-nervous-system","stem":"Which of the following is a characteristic effect of sympathetic nervous system activation?","options":[{"id":"a","text":"Increased gut motility"},{"id":"b","text":"Pupil constriction"},{"id":"c","text":"Bronchodilation"},{"id":"d","text":"Decreased heart rate"}],"answerId":"c","explanation":"Sympathetic activation leads to bronchodilation as part of the 'fight or flight' response.","kind":"recall","origin":"ai"},{"id":"autonomic-nervous-system~ai-2","moduleId":"autonomic-nervous-system","stem":"What is the primary neurotransmitter released by sympathetic postganglionic neurons?","options":[{"id":"a","text":"Acetylcholine"},{"id":"b","text":"Dopamine"},{"id":"c","text":"Norepinephrine"},{"id":"d","text":"Serotonin"}],"answerId":"c","explanation":"Sympathetic postganglionic neurons primarily release norepinephrine to act on adrenergic receptors.","kind":"recall","origin":"ai"},{"id":"autonomic-nervous-system~ai-3","moduleId":"autonomic-nervous-system","stem":"In a patient with Horner syndrome, which of the following findings would you expect?","options":[{"id":"a","text":"Mydriasis"},{"id":"b","text":"Anhidrosis"},{"id":"c","text":"Tachycardia"},{"id":"d","text":"Increased sweating"}],"answerId":"b","explanation":"Horner syndrome is characterized by ptosis, miosis, and anhidrosis due to sympathetic pathway disruption.","kind":"recall","origin":"ai"},{"id":"autonomic-nervous-system~ai-4","moduleId":"autonomic-nervous-system","stem":"Which statement about sweat gland innervation is true?","options":[{"id":"a","text":"Sweat glands use norepinephrine as a neurotransmitter."},{"id":"b","text":"Sweat glands are innervated by parasympathetic fibers."},{"id":"c","text":"Sweat glands are sympathetic but use acetylcholine."},{"id":"d","text":"Sweat glands are exclusively controlled by the adrenal medulla."}],"answerId":"c","explanation":"Sweat glands are an exception in the sympathetic system; they are innervated by sympathetic fibers but use acetylcholine acting on muscarinic receptors.","kind":"trap","origin":"ai"},{"id":"autonomic-nervous-system~ai-5","moduleId":"autonomic-nervous-system","stem":"Which cranial nerve carries the majority of parasympathetic fibers?","options":[{"id":"a","text":"CN III"},{"id":"b","text":"CN VII"},{"id":"c","text":"CN IX"},{"id":"d","text":"CN X"}],"answerId":"d","explanation":"The vagus nerve (CN X) carries approximately 75% of all parasympathetic fibers.","kind":"recall","origin":"ai"},{"id":"autonomic-nervous-system~ai-6","moduleId":"autonomic-nervous-system","stem":"How does the autonomic nervous system influence urinary incontinence treatment?","options":[{"id":"a","text":"By enhancing sympathetic activity"},{"id":"b","text":"By blocking parasympathetic activity"},{"id":"c","text":"By modulating neurotransmitter release"},{"id":"d","text":"By increasing bladder capacity"}],"answerId":"b","explanation":"Drugs for urinary incontinence often work by blocking parasympathetic activity to reduce bladder contractions.","kind":"integration","linkedModuleIds":["urinary-incontinence-drugs"],"origin":"ai"},{"id":"autonomic-nervous-system~ai-7","moduleId":"autonomic-nervous-system","stem":"What role does the hypothalamus play in the autonomic nervous system?","options":[{"id":"a","text":"It directly innervates organs."},{"id":"b","text":"It acts as the master controller of autonomic functions."},{"id":"c","text":"It releases neurotransmitters into the bloodstream."},{"id":"d","text":"It is solely responsible for sympathetic responses."}],"answerId":"b","explanation":"The hypothalamus is the master controller of autonomic functions, coordinating both sympathetic and parasympathetic responses.","kind":"integration","linkedModuleIds":["autonomic-sympathetic-parasympathetic"],"origin":"ai"}],"brain-vesicles-neural-crest":[{"id":"brain-vesicles-neural-crest~ai-0","moduleId":"brain-vesicles-neural-crest","stem":"Which of the following structures is derived from the telencephalon?","options":[{"id":"a","text":"Cerebellum"},{"id":"b","text":"Thalamus"},{"id":"c","text":"Cerebral cortex"},{"id":"d","text":"Medulla"}],"answerId":"c","explanation":"The telencephalon develops into the cerebral cortex and basal ganglia.","kind":"recall","origin":"ai"},{"id":"brain-vesicles-neural-crest~ai-1","moduleId":"brain-vesicles-neural-crest","stem":"What is the origin of the adrenal medulla?","options":[{"id":"a","text":"Mesoderm"},{"id":"b","text":"Neural crest"},{"id":"c","text":"Endoderm"},{"id":"d","text":"Ectoderm"}],"answerId":"b","explanation":"The adrenal medulla is derived from neural crest cells, while the adrenal cortex arises from mesoderm.","kind":"trap","origin":"ai"},{"id":"brain-vesicles-neural-crest~ai-2","moduleId":"brain-vesicles-neural-crest","stem":"Which plate of the neural tube gives rise to sensory neurons?","options":[{"id":"a","text":"Basal plate"},{"id":"b","text":"Alar plate"},{"id":"c","text":"Floor plate"},{"id":"d","text":"Roof plate"}],"answerId":"b","explanation":"The alar plate is responsible for developing sensory neurons in the neural tube.","kind":"recall","origin":"ai"},{"id":"brain-vesicles-neural-crest~ai-3","moduleId":"brain-vesicles-neural-crest","stem":"Which of the following is a derivative of neural crest cells?","options":[{"id":"a","text":"Cerebellum"},{"id":"b","text":"Dorsal root ganglia"},{"id":"c","text":"Thalamus"},{"id":"d","text":"Cortex"}],"answerId":"b","explanation":"Neural crest cells give rise to structures such as dorsal root ganglia and Schwann cells.","kind":"recall","origin":"ai"},{"id":"brain-vesicles-neural-crest~ai-4","moduleId":"brain-vesicles-neural-crest","stem":"The metencephalon develops into which of the following adult structures?","options":[{"id":"a","text":"Medulla"},{"id":"b","text":"Cerebellum"},{"id":"c","text":"Thalamus"},{"id":"d","text":"Cortex"}],"answerId":"b","explanation":"The metencephalon develops into the pons and cerebellum.","kind":"recall","origin":"ai"},{"id":"brain-vesicles-neural-crest~ai-5","moduleId":"brain-vesicles-neural-crest","stem":"How does the neural crest contribute to the peripheral nervous system?","options":[{"id":"a","text":"By forming the spinal cord"},{"id":"b","text":"By forming sensory neurons"},{"id":"c","text":"By forming Schwann cells"},{"id":"d","text":"By forming the brainstem"}],"answerId":"c","explanation":"Neural crest cells migrate to form Schwann cells and other components of the peripheral nervous system.","kind":"mechanism","origin":"ai"},{"id":"brain-vesicles-neural-crest~ai-6","moduleId":"brain-vesicles-neural-crest","stem":"Which structure is formed from the diencephalon?","options":[{"id":"a","text":"Cerebral cortex"},{"id":"b","text":"Thalamus"},{"id":"c","text":"Cerebellum"},{"id":"d","text":"Medulla"}],"answerId":"b","explanation":"The diencephalon develops into the thalamus and hypothalamus.","kind":"recall","origin":"ai"},{"id":"brain-vesicles-neural-crest~ai-7","moduleId":"brain-vesicles-neural-crest","stem":"Which of the following structures is NOT derived from the neural crest?","options":[{"id":"a","text":"Melanocytes"},{"id":"b","text":"Dorsal root ganglia"},{"id":"c","text":"Cerebral cortex"},{"id":"d","text":"Adrenal medulla"}],"answerId":"c","explanation":"The cerebral cortex is derived from the telencephalon, not from neural crest cells.","kind":"trap","origin":"ai"},{"id":"brain-vesicles-neural-crest~ai-8","moduleId":"brain-vesicles-neural-crest","stem":"How does the development of the neural tube relate to brainstem anatomy?","options":[{"id":"a","text":"Neural crest forms the brainstem"},{"id":"b","text":"Alar plate forms the brainstem"},{"id":"c","text":"Basal plate forms the brainstem"},{"id":"d","text":"Neural tube defects affect brainstem anatomy"}],"answerId":"c","explanation":"The basal plate of the neural tube develops into motor neurons that contribute to the brainstem.","kind":"integration","linkedModuleIds":["brainstem-anatomy-organization"],"origin":"ai"},{"id":"brain-vesicles-neural-crest~ai-9","moduleId":"brain-vesicles-neural-crest","stem":"Which brain structure's development is linked to neural tube defects?","options":[{"id":"a","text":"Cerebellum"},{"id":"b","text":"Thalamus"},{"id":"c","text":"Spinal cord"},{"id":"d","text":"Cortex"}],"answerId":"c","explanation":"Neural tube defects can lead to malformations in the spinal cord, which is derived from the caudal end of the neural tube.","kind":"integration","linkedModuleIds":["neural-tube-development-defects"],"origin":"ai"}],"neural-tube-development-defects":[{"id":"neural-tube-development-defects~ai-0","moduleId":"neural-tube-development-defects","stem":"What is the primary embryological origin of the nervous system?","options":[{"id":"a","text":"Mesoderm"},{"id":"b","text":"Ectoderm"},{"id":"c","text":"Endoderm"},{"id":"d","text":"Neural crest"}],"answerId":"b","explanation":"The nervous system develops from the ectoderm through the process of neurulation.","kind":"recall","origin":"ai"},{"id":"neural-tube-development-defects~ai-1","moduleId":"neural-tube-development-defects","stem":"Which neural tube defect results from failure of the anterior neuropore to close?","options":[{"id":"a","text":"Spina bifida occulta"},{"id":"b","text":"Meningocele"},{"id":"c","text":"Myelomeningocele"},{"id":"d","text":"Anencephaly"}],"answerId":"d","explanation":"Anencephaly occurs due to the failure of the anterior neuropore to close, leading to an absent forebrain and calvarium.","kind":"recall","origin":"ai"},{"id":"neural-tube-development-defects~ai-2","moduleId":"neural-tube-development-defects","stem":"What is the most severe form of spina bifida?","options":[{"id":"a","text":"Spina bifida occulta"},{"id":"b","text":"Meningocele"},{"id":"c","text":"Myelomeningocele"},{"id":"d","text":"Neural tube defect"}],"answerId":"c","explanation":"Myelomeningocele is the most severe form of spina bifida, involving herniation of both meninges and neural tissue.","kind":"recall","origin":"ai"},{"id":"neural-tube-development-defects~ai-3","moduleId":"neural-tube-development-defects","stem":"How does folate supplementation affect neural tube defects?","options":[{"id":"a","text":"Increases risk"},{"id":"b","text":"No effect"},{"id":"c","text":"Decreases risk"},{"id":"d","text":"Only affects posterior defects"}],"answerId":"c","explanation":"Folate supplementation decreases the risk of neural tube defects, particularly during the periconceptional period.","kind":"mechanism","origin":"ai"},{"id":"neural-tube-development-defects~ai-4","moduleId":"neural-tube-development-defects","stem":"A pregnant woman has elevated alpha-fetoprotein levels. What condition might this indicate?","options":[{"id":"a","text":"Anencephaly"},{"id":"b","text":"Spina bifida occulta"},{"id":"c","text":"Meningocele"},{"id":"d","text":"Open neural tube defect"}],"answerId":"d","explanation":"Elevated alpha-fetoprotein levels in maternal serum or amniotic fluid are indicative of an open neural tube defect.","kind":"clinical","origin":"ai"},{"id":"neural-tube-development-defects~ai-5","moduleId":"neural-tube-development-defects","stem":"Which of the following statements about spina bifida is true?","options":[{"id":"a","text":"All forms cause severe neurological disability"},{"id":"b","text":"Spina bifida occulta is always symptomatic"},{"id":"c","text":"Severity varies by type and level"},{"id":"d","text":"Meningocele is the mildest form"}],"answerId":"c","explanation":"Severity of spina bifida varies by type and level; spina bifida occulta is often asymptomatic.","kind":"trap","origin":"ai"},{"id":"neural-tube-development-defects~ai-6","moduleId":"neural-tube-development-defects","stem":"How does the development of the neural tube relate to spinal cord anatomy?","options":[{"id":"a","text":"Neural tube forms the peripheral nervous system"},{"id":"b","text":"Neural tube becomes the central nervous system"},{"id":"c","text":"Spinal cord develops from mesoderm"},{"id":"d","text":"Neural crest forms the neural tube"}],"answerId":"b","explanation":"The neural tube develops into the central nervous system, which includes the spinal cord.","kind":"integration","linkedModuleIds":["spinal-cord-anatomy-organization"],"origin":"ai"},{"id":"neural-tube-development-defects~ai-7","moduleId":"neural-tube-development-defects","stem":"What role does the notochord play in neural tube development?","options":[{"id":"a","text":"Forms the neural crest"},{"id":"b","text":"Induces the formation of the neural plate"},{"id":"c","text":"Becomes part of the spinal cord"},{"id":"d","text":"Closes the neuropores"}],"answerId":"b","explanation":"The notochord induces the overlying ectoderm to form the neural plate, which eventually folds to create the neural tube.","kind":"integration","linkedModuleIds":["notochord-neurulation-neural-crest"],"origin":"ai"}],"anthelmintic-agents":[{"id":"anthelmintic-agents~ai-0","moduleId":"anthelmintic-agents","stem":"Which anthelmintic agent is primarily used to treat intestinal roundworms?","options":[{"id":"a","text":"Praziquantel"},{"id":"b","text":"Ivermectin"},{"id":"c","text":"Albendazole"},{"id":"d","text":"Pyrantel Pamoate"}],"answerId":"c","explanation":"Albendazole is a benzimidazole that targets β-tubulin, making it effective against intestinal roundworms.","kind":"recall","origin":"ai"},{"id":"anthelmintic-agents~ai-1","moduleId":"anthelmintic-agents","stem":"What is the mechanism of action of praziquantel?","options":[{"id":"a","text":"Inhibits β-tubulin assembly"},{"id":"b","text":"Increases Ca²⁺ permeability"},{"id":"c","text":"Opens glutamate-gated Cl⁻ channels"},{"id":"d","text":"Blocks glucose uptake"}],"answerId":"b","explanation":"Praziquantel increases Ca²⁺ permeability, leading to paralysis and tegument damage in trematodes and cestodes.","kind":"mechanism","origin":"ai"},{"id":"anthelmintic-agents~ai-2","moduleId":"anthelmintic-agents","stem":"A patient presents with strongyloidiasis. Which drug is the most appropriate treatment?","options":[{"id":"a","text":"Albendazole"},{"id":"b","text":"Praziquantel"},{"id":"c","text":"Ivermectin"},{"id":"d","text":"Pyrantel Pamoate"}],"answerId":"c","explanation":"Ivermectin is the drug of choice for treating Strongyloides infections due to its action on glutamate-gated Cl⁻ channels.","kind":"clinical","origin":"ai"},{"id":"anthelmintic-agents~ai-3","moduleId":"anthelmintic-agents","stem":"Which of the following anthelmintics is avoided during the first trimester of pregnancy?","options":[{"id":"a","text":"Ivermectin"},{"id":"b","text":"Praziquantel"},{"id":"c","text":"Albendazole"},{"id":"d","text":"Pyrantel Pamoate"}],"answerId":"c","explanation":"Benzimidazoles like albendazole are teratogenic in animal studies and are avoided during the first trimester.","kind":"trap","origin":"ai"},{"id":"anthelmintic-agents~ai-4","moduleId":"anthelmintic-agents","stem":"What is the primary reason for co-administering corticosteroids with treatment for neurocysticercosis?","options":[{"id":"a","text":"To enhance drug absorption"},{"id":"b","text":"To prevent seizures"},{"id":"c","text":"To mitigate inflammatory reactions"},{"id":"d","text":"To improve drug efficacy"}],"answerId":"c","explanation":"Corticosteroids are given to reduce the inflammatory response triggered by dying larvae during treatment.","kind":"mechanism","origin":"ai"},{"id":"anthelmintic-agents~ai-5","moduleId":"anthelmintic-agents","stem":"Which class of anthelmintics is effective against both trematodes and cestodes?","options":[{"id":"a","text":"Benzimidazoles"},{"id":"b","text":"Ivermectin"},{"id":"c","text":"Praziquantel"},{"id":"d","text":"Pyrantel Pamoate"}],"answerId":"c","explanation":"Praziquantel is effective against both trematodes (flukes) and cestodes (tapeworms) due to its mechanism of increasing Ca²⁺ permeability.","kind":"recall","origin":"ai"},{"id":"anthelmintic-agents~ai-6","moduleId":"anthelmintic-agents","stem":"How does the mechanism of action of ivermectin differ from that of albendazole?","options":[{"id":"a","text":"Ivermectin inhibits glucose uptake"},{"id":"b","text":"Albendazole increases Ca²⁺ permeability"},{"id":"c","text":"Ivermectin opens glutamate-gated Cl⁻ channels"},{"id":"d","text":"Albendazole paralyzes the worm"}],"answerId":"c","explanation":"Ivermectin opens glutamate-gated Cl⁻ channels, causing paralysis, while albendazole inhibits β-tubulin assembly, leading to starvation.","kind":"integration","linkedModuleIds":["anthelmintic-drug-classes"],"origin":"ai"},{"id":"anthelmintic-agents~ai-7","moduleId":"anthelmintic-agents","stem":"Which anthelmintic is specifically indicated for the treatment of onchocerciasis?","options":[{"id":"a","text":"Albendazole"},{"id":"b","text":"Ivermectin"},{"id":"c","text":"Praziquantel"},{"id":"d","text":"Pyrantel Pamoate"}],"answerId":"b","explanation":"Ivermectin is the drug of choice for treating onchocerciasis (river blindness) due to its specific action on the parasite.","kind":"integration","linkedModuleIds":["scabies-pediculosis-clinical"],"origin":"ai"}],"drug-development-bioequivalence":[{"id":"drug-development-bioequivalence~ai-0","moduleId":"drug-development-bioequivalence","stem":"What is the primary purpose of Phase I clinical trials?","options":[{"id":"a","text":"To assess efficacy in patients"},{"id":"b","text":"To evaluate safety and pharmacokinetics in healthy volunteers"},{"id":"c","text":"To confirm efficacy in large populations"},{"id":"d","text":"To monitor long-term adverse effects post-marketing"}],"answerId":"b","explanation":"Phase I trials focus on safety and pharmacokinetics, typically involving healthy volunteers.","kind":"recall","origin":"ai"},{"id":"drug-development-bioequivalence~ai-1","moduleId":"drug-development-bioequivalence","stem":"Which parameter is NOT typically used to establish bioequivalence between a generic and innovator drug?","options":[{"id":"a","text":"AUC"},{"id":"b","text":"Cmax"},{"id":"c","text":"Half-life"},{"id":"d","text":"Rate of absorption"}],"answerId":"c","explanation":"Half-life is not a direct measure of bioequivalence; AUC and Cmax are the primary parameters.","kind":"trap","origin":"ai"},{"id":"drug-development-bioequivalence~ai-2","moduleId":"drug-development-bioequivalence","stem":"What distinguishes a biosimilar from a generic drug?","options":[{"id":"a","text":"Biosimilars are chemically identical to the reference drug"},{"id":"b","text":"Biosimilars require extensive clinical data for approval"},{"id":"c","text":"Generics are more complex than biosimilars"},{"id":"d","text":"Biosimilars are approved without any comparative studies"}],"answerId":"b","explanation":"Biosimilars require extensive comparative data due to their complexity, unlike generics which are identical to the reference drug.","kind":"trap","origin":"ai"},{"id":"drug-development-bioequivalence~ai-3","moduleId":"drug-development-bioequivalence","stem":"What is the main goal of Phase III clinical trials?","options":[{"id":"a","text":"To assess safety in healthy volunteers"},{"id":"b","text":"To confirm efficacy and detect common adverse drug reactions"},{"id":"c","text":"To monitor long-term effects of the drug"},{"id":"d","text":"To evaluate pharmacokinetics in patients"}],"answerId":"b","explanation":"Phase III trials are designed to confirm efficacy and detect common adverse drug reactions in a larger patient population.","kind":"recall","origin":"ai"},{"id":"drug-development-bioequivalence~ai-4","moduleId":"drug-development-bioequivalence","stem":"In which phase of drug development are rare serious adverse drug reactions typically identified?","options":[{"id":"a","text":"Phase I"},{"id":"b","text":"Phase II"},{"id":"c","text":"Phase III"},{"id":"d","text":"Phase IV"}],"answerId":"d","explanation":"Phase IV involves post-marketing surveillance, where rare but serious adverse drug reactions may be identified.","kind":"recall","origin":"ai"},{"id":"drug-development-bioequivalence~ai-5","moduleId":"drug-development-bioequivalence","stem":"How does the approval process for a biosimilar differ from that of a generic drug?","options":[{"id":"a","text":"Biosimilars require only pharmacokinetic studies"},{"id":"b","text":"Biosimilars must demonstrate similarity through extensive data"},{"id":"c","text":"Generics are approved based on clinical trials"},{"id":"d","text":"Biosimilars can be identical to the reference product"}],"answerId":"b","explanation":"Biosimilars must demonstrate similarity through extensive comparative analytical, pharmacokinetic, and often clinical data.","kind":"integration","linkedModuleIds":["pharmacokinetics-adme"],"origin":"ai"},{"id":"drug-development-bioequivalence~ai-6","moduleId":"drug-development-bioequivalence","stem":"Which clinical finding would indicate a successful bioequivalence study for a generic drug?","options":[{"id":"a","text":"AUC and Cmax ratios fall within 70-130%"},{"id":"b","text":"AUC and Cmax ratios fall within 80-125%"},{"id":"c","text":"No adverse reactions reported in Phase I"},{"id":"d","text":"Same half-life as the innovator drug"}],"answerId":"b","explanation":"Successful bioequivalence is established when the AUC and Cmax ratios fall within the 80-125% range.","kind":"recall","origin":"ai"},{"id":"drug-development-bioequivalence~ai-7","moduleId":"drug-development-bioequivalence","stem":"Which of the following statements about drug development is true?","options":[{"id":"a","text":"Phase II trials focus solely on safety"},{"id":"b","text":"Generics require full clinical trials for approval"},{"id":"c","text":"Biosimilars are identical to their reference products"},{"id":"d","text":"Phase I trials assess safety in healthy volunteers"}],"answerId":"d","explanation":"Phase I trials are designed to assess safety and pharmacokinetics in healthy volunteers.","kind":"recall","origin":"ai"},{"id":"drug-development-bioequivalence~ai-8","moduleId":"drug-development-bioequivalence","stem":"What is the significance of post-marketing surveillance in drug development?","options":[{"id":"a","text":"To establish initial safety data"},{"id":"b","text":"To confirm efficacy in large populations"},{"id":"c","text":"To detect rare and long-term adverse drug reactions"},{"id":"d","text":"To evaluate pharmacokinetics in patients"}],"answerId":"c","explanation":"Post-marketing surveillance is crucial for detecting rare and long-term adverse drug reactions that may not have been identified in earlier trials.","kind":"recall","origin":"ai"}],"antifungal-agents":[{"id":"antifungal-agents~ai-0","moduleId":"antifungal-agents","stem":"What is the primary mechanism of action of amphotericin B?","options":[{"id":"a","text":"Inhibition of squalene epoxidase"},{"id":"b","text":"Binding to ergosterol and forming pores"},{"id":"c","text":"Inhibition of 14-α-demethylase"},{"id":"d","text":"Inhibition of β-(1,3)-D-glucan synthesis"}],"answerId":"b","explanation":"Amphotericin B binds to ergosterol in fungal cell membranes, creating pores that lead to cell death.","kind":"mechanism","origin":"ai"},{"id":"antifungal-agents~ai-1","moduleId":"antifungal-agents","stem":"Which antifungal agent is the first-line treatment for invasive aspergillosis?","options":[{"id":"a","text":"Fluconazole"},{"id":"b","text":"Caspofungin"},{"id":"c","text":"Voriconazole"},{"id":"d","text":"Nystatin"}],"answerId":"c","explanation":"Voriconazole is the first-line agent for treating invasive aspergillosis due to its efficacy against Aspergillus species.","kind":"recall","origin":"ai"},{"id":"antifungal-agents~ai-2","moduleId":"antifungal-agents","stem":"A patient develops rising creatinine and hypokalemia after starting antifungal therapy. Which drug is most likely responsible?","options":[{"id":"a","text":"Fluconazole"},{"id":"b","text":"Amphotericin B"},{"id":"c","text":"Caspofungin"},{"id":"d","text":"Terbinafine"}],"answerId":"b","explanation":"Amphotericin B is known for its nephrotoxic effects, which can lead to elevated creatinine and hypokalemia.","kind":"recall","origin":"ai"},{"id":"antifungal-agents~ai-3","moduleId":"antifungal-agents","stem":"What is a significant side effect of azole antifungals?","options":[{"id":"a","text":"Nephrotoxicity"},{"id":"b","text":"Hepatotoxicity"},{"id":"c","text":"Bone marrow suppression"},{"id":"d","text":"Gastrointestinal bleeding"}],"answerId":"b","explanation":"Azole antifungals can cause hepatotoxicity due to their inhibition of human CYP450 enzymes.","kind":"trap","origin":"ai"},{"id":"antifungal-agents~ai-4","moduleId":"antifungal-agents","stem":"Which antifungal is specifically indicated for dermatophyte onychomycosis?","options":[{"id":"a","text":"Caspofungin"},{"id":"b","text":"Fluconazole"},{"id":"c","text":"Amphotericin B"},{"id":"d","text":"Terbinafine"}],"answerId":"d","explanation":"Terbinafine is the oral drug of choice for treating dermatophyte nail infections.","kind":"recall","origin":"ai"},{"id":"antifungal-agents~ai-5","moduleId":"antifungal-agents","stem":"How do azole antifungals affect the metabolism of statins?","options":[{"id":"a","text":"Increase statin metabolism"},{"id":"b","text":"No effect on statins"},{"id":"c","text":"Decrease statin metabolism"},{"id":"d","text":"Statins are contraindicated with azoles"}],"answerId":"c","explanation":"Azoles inhibit human CYP450 enzymes, leading to decreased metabolism and increased levels of statins, raising the risk of side effects.","kind":"integration","linkedModuleIds":["drug-interactions-mechanisms"],"origin":"ai"},{"id":"antifungal-agents~ai-6","moduleId":"antifungal-agents","stem":"What is the role of flucytosine in antifungal therapy?","options":[{"id":"a","text":"Inhibits ergosterol synthesis"},{"id":"b","text":"Forms pores in fungal membranes"},{"id":"c","text":"Inhibits DNA/RNA synthesis"},{"id":"d","text":"Inhibits β-(1,3)-D-glucan synthesis"}],"answerId":"c","explanation":"Flucytosine is converted to 5-FU in fungi, inhibiting DNA and RNA synthesis, and is often used in combination with amphotericin B.","kind":"mechanism","origin":"ai"},{"id":"antifungal-agents~ai-7","moduleId":"antifungal-agents","stem":"Which antifungal agent is well-tolerated for treating azole-resistant invasive candidiasis?","options":[{"id":"a","text":"Fluconazole"},{"id":"b","text":"Amphotericin B"},{"id":"c","text":"Caspofungin"},{"id":"d","text":"Voriconazole"}],"answerId":"c","explanation":"Caspofungin, an echinocandin, is effective against azole-resistant strains of Candida and is well-tolerated.","kind":"recall","origin":"ai"},{"id":"antifungal-agents~ai-8","moduleId":"antifungal-agents","stem":"Which of the following statements about superficial fungal infections is true?","options":[{"id":"a","text":"They are always treated with systemic antifungals."},{"id":"b","text":"Recurrence is common after treatment."},{"id":"c","text":"They do not require antifungal therapy."},{"id":"d","text":"They are exclusively caused by dermatophytes."}],"answerId":"b","explanation":"Superficial fungal infections often recur after treatment, necessitating careful management and follow-up.","kind":"integration","linkedModuleIds":["skin-infections-bacterial-fungal-viral"],"origin":"ai"}],"pharmacodynamics-receptors-dose-response":[{"id":"pharmacodynamics-receptors-dose-response~ai-0","moduleId":"pharmacodynamics-receptors-dose-response","stem":"What type of drug binds to a receptor but does not produce a response?","options":[{"id":"a","text":"Agonist"},{"id":"b","text":"Antagonist"},{"id":"c","text":"Partial agonist"},{"id":"d","text":"Inverse agonist"}],"answerId":"b","explanation":"An antagonist binds to a receptor without activating it, hence producing no response.","kind":"recall","origin":"ai"},{"id":"pharmacodynamics-receptors-dose-response~ai-1","moduleId":"pharmacodynamics-receptors-dose-response","stem":"Which of the following describes a drug that has a lower EC50?","options":[{"id":"a","text":"Higher efficacy"},{"id":"b","text":"Higher potency"},{"id":"c","text":"Lower therapeutic index"},{"id":"d","text":"Longer duration of action"}],"answerId":"b","explanation":"A lower EC50 indicates that the drug is more potent, requiring a smaller dose for effect.","kind":"recall","origin":"ai"},{"id":"pharmacodynamics-receptors-dose-response~ai-2","moduleId":"pharmacodynamics-receptors-dose-response","stem":"What is the effect of a competitive antagonist on an agonist dose-response curve?","options":[{"id":"a","text":"Shifts the curve left"},{"id":"b","text":"Shifts the curve right"},{"id":"c","text":"Lowers the maximum response"},{"id":"d","text":"Increases the efficacy of the agonist"}],"answerId":"b","explanation":"A competitive antagonist shifts the agonist curve to the right in parallel, indicating a decrease in potency but not efficacy.","kind":"mechanism","origin":"ai"},{"id":"pharmacodynamics-receptors-dose-response~ai-3","moduleId":"pharmacodynamics-receptors-dose-response","stem":"Which drug type produces a maximal response but is less effective than a full agonist in the presence of the latter?","options":[{"id":"a","text":"Full agonist"},{"id":"b","text":"Partial agonist"},{"id":"c","text":"Antagonist"},{"id":"d","text":"Inverse agonist"}],"answerId":"b","explanation":"A partial agonist can activate the receptor but does not achieve the maximal response that a full agonist does.","kind":"recall","origin":"ai"},{"id":"pharmacodynamics-receptors-dose-response~ai-4","moduleId":"pharmacodynamics-receptors-dose-response","stem":"What is the primary reason for monitoring plasma levels of drugs like warfarin?","options":[{"id":"a","text":"High potency"},{"id":"b","text":"Narrow therapeutic index"},{"id":"c","text":"High efficacy"},{"id":"d","text":"Long half-life"}],"answerId":"b","explanation":"Drugs with a narrow therapeutic index require careful monitoring to avoid toxicity.","kind":"recall","origin":"ai"},{"id":"pharmacodynamics-receptors-dose-response~ai-5","moduleId":"pharmacodynamics-receptors-dose-response","stem":"A drug that reduces the maximum response of an agonist and cannot be overcome by increasing the agonist concentration is classified as what?","options":[{"id":"a","text":"Competitive antagonist"},{"id":"b","text":"Non-competitive antagonist"},{"id":"c","text":"Partial agonist"},{"id":"d","text":"Full agonist"}],"answerId":"b","explanation":"Non-competitive antagonists lower the Emax of the agonist response and cannot be surmounted by increasing agonist concentration.","kind":"mechanism","origin":"ai"},{"id":"pharmacodynamics-receptors-dose-response~ai-6","moduleId":"pharmacodynamics-receptors-dose-response","stem":"How does a partial agonist function in the presence of a full agonist?","options":[{"id":"a","text":"Acts as a full agonist"},{"id":"b","text":"Acts as an antagonist"},{"id":"c","text":"Increases the efficacy of the full agonist"},{"id":"d","text":"Decreases the efficacy of the full agonist"}],"answerId":"d","explanation":"A partial agonist can act as a partial antagonist when a full agonist is present, reducing the overall effect.","kind":"trap","origin":"ai"},{"id":"pharmacodynamics-receptors-dose-response~ai-7","moduleId":"pharmacodynamics-receptors-dose-response","stem":"Which pharmacological principle is most important when considering drug interactions between agonists and antagonists?","options":[{"id":"a","text":"Affinity"},{"id":"b","text":"Efficacy"},{"id":"c","text":"Potency"},{"id":"d","text":"Therapeutic index"}],"answerId":"b","explanation":"Efficacy is crucial in determining the maximum effect achievable by a drug, especially in the presence of antagonists.","kind":"trap","origin":"ai"},{"id":"pharmacodynamics-receptors-dose-response~ai-8","moduleId":"pharmacodynamics-receptors-dose-response","stem":"How does the pharmacodynamics of a drug relate to its pharmacokinetics?","options":[{"id":"a","text":"Pharmacodynamics determines drug absorption"},{"id":"b","text":"Pharmacodynamics affects drug distribution"},{"id":"c","text":"Pharmacodynamics influences drug action"},{"id":"d","text":"Pharmacodynamics dictates drug elimination"}],"answerId":"c","explanation":"Pharmacodynamics focuses on how drugs affect the body, while pharmacokinetics deals with how the body affects drugs.","kind":"integration","linkedModuleIds":["pharmacokinetics-adme"],"origin":"ai"},{"id":"pharmacodynamics-receptors-dose-response~ai-9","moduleId":"pharmacodynamics-receptors-dose-response","stem":"In treating colon cancer, how might understanding receptor pharmacodynamics influence therapeutic choices?","options":[{"id":"a","text":"It helps predict drug absorption"},{"id":"b","text":"It determines the drug's half-life"},{"id":"c","text":"It informs the selection of agonists or antagonists"},{"id":"d","text":"It affects the drug's distribution in the body"}],"answerId":"c","explanation":"Understanding receptor pharmacodynamics is crucial for selecting the appropriate agonists or antagonists in cancer therapy.","kind":"integration","linkedModuleIds":["colon-molecular-workup-therapy"],"origin":"ai"}],"adrenergic-drugs":[{"id":"adrenergic-drugs~ai-0","moduleId":"adrenergic-drugs","stem":"What is the first-line drug for treating anaphylaxis?","options":[{"id":"a","text":"Adrenaline"},{"id":"b","text":"Salbutamol"},{"id":"c","text":"Clonidine"},{"id":"d","text":"Phenylephrine"}],"answerId":"a","explanation":"Adrenaline is the first-line treatment for anaphylaxis due to its α1 vasoconstriction and β2 bronchodilation effects.","kind":"recall","origin":"ai"},{"id":"adrenergic-drugs~ai-1","moduleId":"adrenergic-drugs","stem":"Which receptor does salbutamol primarily act on?","options":[{"id":"a","text":"α1"},{"id":"b","text":"α2"},{"id":"c","text":"β1"},{"id":"d","text":"β2"}],"answerId":"d","explanation":"Salbutamol is a selective β2-agonist used for bronchodilation in asthma.","kind":"recall","origin":"ai"},{"id":"adrenergic-drugs~ai-2","moduleId":"adrenergic-drugs","stem":"A patient with untreated pheochromocytoma presents with hypertension and tachycardia. What is the most appropriate initial treatment?","options":[{"id":"a","text":"β-blocker"},{"id":"b","text":"α-blocker"},{"id":"c","text":"Calcium channel blocker"},{"id":"d","text":"Diuretic"}],"answerId":"b","explanation":"An α-blocker must be given first to prevent unopposed α-adrenergic vasoconstriction before any β-blockade.","kind":"clinical","origin":"ai"},{"id":"adrenergic-drugs~ai-3","moduleId":"adrenergic-drugs","stem":"What adverse effect is most commonly associated with β-blockers?","options":[{"id":"a","text":"Tachycardia"},{"id":"b","text":"Bradycardia"},{"id":"c","text":"Hypertension"},{"id":"d","text":"Hyperglycemia"}],"answerId":"b","explanation":"Bradycardia is a common adverse effect of β-blockers due to their action on the heart.","kind":"trap","origin":"ai"},{"id":"adrenergic-drugs~ai-4","moduleId":"adrenergic-drugs","stem":"Which mechanism underlies the action of clonidine in hypertension?","options":[{"id":"a","text":"α1 agonism"},{"id":"b","text":"α2 agonism"},{"id":"c","text":"β1 antagonism"},{"id":"d","text":"β2 agonism"}],"answerId":"b","explanation":"Clonidine acts as an α2 agonist, reducing sympathetic outflow and lowering blood pressure.","kind":"mechanism","origin":"ai"},{"id":"adrenergic-drugs~ai-5","moduleId":"adrenergic-drugs","stem":"How do adrenergic drugs and cholinergic drugs interact in the autonomic nervous system?","options":[{"id":"a","text":"They have similar effects on heart rate"},{"id":"b","text":"They oppose each other in action"},{"id":"c","text":"They both increase blood pressure"},{"id":"d","text":"They both cause bronchoconstriction"}],"answerId":"b","explanation":"Adrenergic drugs generally stimulate sympathetic responses, while cholinergic drugs stimulate parasympathetic responses, thus opposing each other.","kind":"integration","linkedModuleIds":["cholinergic-drugs"],"origin":"ai"},{"id":"adrenergic-drugs~ai-6","moduleId":"adrenergic-drugs","stem":"In the context of the autonomic nervous system, what is the primary action of β2-adrenergic agonists?","options":[{"id":"a","text":"Vasoconstriction"},{"id":"b","text":"Bronchodilation"},{"id":"c","text":"Increased heart rate"},{"id":"d","text":"Decreased gastrointestinal motility"}],"answerId":"b","explanation":"β2-adrenergic agonists primarily cause bronchodilation, which is crucial in treating asthma.","kind":"integration","linkedModuleIds":["autonomic-nervous-system"],"origin":"ai"}],"antineoplastic-principles":[{"id":"antineoplastic-principles~ai-0","moduleId":"antineoplastic-principles","stem":"Which of the following chemotherapy agents is associated with nephrotoxicity?","options":[{"id":"a","text":"Cyclophosphamide"},{"id":"b","text":"Cisplatin"},{"id":"c","text":"Doxorubicin"},{"id":"d","text":"Vincristine"}],"answerId":"b","explanation":"Cisplatin is known for causing nephrotoxicity, which can be mitigated with hydration and diuretics.","kind":"recall","origin":"ai"},{"id":"antineoplastic-principles~ai-1","moduleId":"antineoplastic-principles","stem":"What is the mechanism of action of methotrexate?","options":[{"id":"a","text":"Inhibition of thymidylate synthase"},{"id":"b","text":"Inhibition of dihydrofolate reductase"},{"id":"c","text":"DNA cross-linking"},{"id":"d","text":"Microtubule stabilization"}],"answerId":"b","explanation":"Methotrexate inhibits dihydrofolate reductase, leading to decreased folate availability and impaired DNA synthesis.","kind":"mechanism","origin":"ai"},{"id":"antineoplastic-principles~ai-2","moduleId":"antineoplastic-principles","stem":"A patient receiving vincristine develops peripheral neuropathy. What is the underlying mechanism?","options":[{"id":"a","text":"Inhibition of DNA synthesis"},{"id":"b","text":"Inhibition of microtubule assembly"},{"id":"c","text":"Cross-linking of DNA"},{"id":"d","text":"Topoisomerase inhibition"}],"answerId":"b","explanation":"Vincristine inhibits microtubule assembly, which affects neuronal function and leads to peripheral neuropathy.","kind":"mechanism","origin":"ai"},{"id":"antineoplastic-principles~ai-3","moduleId":"antineoplastic-principles","stem":"Which of the following is a common shared toxicity of chemotherapy?","options":[{"id":"a","text":"Cardiotoxicity"},{"id":"b","text":"Nephrotoxicity"},{"id":"c","text":"Myelosuppression"},{"id":"d","text":"Pulmonary fibrosis"}],"answerId":"c","explanation":"Myelosuppression is a common shared toxicity due to the targeting of rapidly dividing cells, including bone marrow.","kind":"trap","origin":"ai"},{"id":"antineoplastic-principles~ai-4","moduleId":"antineoplastic-principles","stem":"A patient presents with hyperkalemia, hyperuricemia, and hyperphosphatemia after starting chemotherapy. What is the likely cause?","options":[{"id":"a","text":"Tumor lysis syndrome"},{"id":"b","text":"Nephrotoxicity"},{"id":"c","text":"Myelosuppression"},{"id":"d","text":"Peripheral neuropathy"}],"answerId":"a","explanation":"These electrolyte abnormalities are characteristic of tumor lysis syndrome, which occurs after rapid cell death.","kind":"clinical","origin":"ai"},{"id":"antineoplastic-principles~ai-5","moduleId":"antineoplastic-principles","stem":"How does the mechanism of action of 5-fluorouracil differ from that of cyclophosphamide?","options":[{"id":"a","text":"5-FU inhibits DNA synthesis, cyclophosphamide cross-links DNA"},{"id":"b","text":"5-FU cross-links DNA, cyclophosphamide inhibits DNA synthesis"},{"id":"c","text":"Both inhibit DNA synthesis"},{"id":"d","text":"Both cross-link DNA"}],"answerId":"a","explanation":"5-Fluorouracil inhibits thymidylate synthase, affecting DNA synthesis, while cyclophosphamide cross-links DNA, making it cell-cycle non-specific.","kind":"integration","linkedModuleIds":["nucleotide-drugs-disorders"],"origin":"ai"},{"id":"antineoplastic-principles~ai-6","moduleId":"antineoplastic-principles","stem":"Which targeted therapy is specifically used for BCR-ABL positive chronic myeloid leukemia?","options":[{"id":"a","text":"Trastuzumab"},{"id":"b","text":"Imatinib"},{"id":"c","text":"Rituximab"},{"id":"d","text":"Doxorubicin"}],"answerId":"b","explanation":"Imatinib is a tyrosine kinase inhibitor specifically targeting the BCR-ABL fusion protein in CML.","kind":"integration","linkedModuleIds":["targeted-cancer-therapy"],"origin":"ai"}],"pharmacogenomics":[{"id":"pharmacogenomics~ai-0","moduleId":"pharmacogenomics","stem":"What is the primary consequence of being a CYP2D6 ultrarapid metaboliser when prescribed codeine?","options":[{"id":"a","text":"Increased risk of respiratory depression"},{"id":"b","text":"Ineffective pain relief"},{"id":"c","text":"Increased risk of gastrointestinal bleeding"},{"id":"d","text":"Reduced drug clearance"}],"answerId":"a","explanation":"CYP2D6 ultrarapid metabolizers convert codeine to morphine rapidly, leading to increased risk of respiratory depression.","kind":"clinical","origin":"ai"},{"id":"pharmacogenomics~ai-1","moduleId":"pharmacogenomics","stem":"Which genetic variant is associated with severe myelosuppression when using azathioprine?","options":[{"id":"a","text":"CYP2C19"},{"id":"b","text":"TPMT"},{"id":"c","text":"HLA-B*15:02"},{"id":"d","text":"G6PD"}],"answerId":"b","explanation":"TPMT deficiency can lead to severe myelosuppression when azathioprine is used.","kind":"recall","origin":"ai"},{"id":"pharmacogenomics~ai-2","moduleId":"pharmacogenomics","stem":"What is the mechanism behind the reduced efficacy of clopidogrel in poor metabolizers?","options":[{"id":"a","text":"Increased drug clearance"},{"id":"b","text":"Under-activation of the prodrug"},{"id":"c","text":"Increased drug binding"},{"id":"d","text":"Altered drug transport"}],"answerId":"b","explanation":"Poor metabolizers have reduced activation of clopidogrel, leading to decreased antiplatelet effects.","kind":"mechanism","origin":"ai"},{"id":"pharmacogenomics~ai-3","moduleId":"pharmacogenomics","stem":"A Southeast Asian patient develops Stevens-Johnson syndrome after starting carbamazepine. What genetic test should be performed before prescribing this drug?","options":[{"id":"a","text":"CYP2C19 genotype"},{"id":"b","text":"HLA-B*15:02"},{"id":"c","text":"TPMT activity"},{"id":"d","text":"G6PD deficiency test"}],"answerId":"b","explanation":"Screening for HLA-B*15:02 is recommended to prevent severe hypersensitivity reactions to carbamazepine.","kind":"recall","origin":"ai"},{"id":"pharmacogenomics~ai-4","moduleId":"pharmacogenomics","stem":"Which statement correctly describes the risk associated with poor and ultrarapid metabolizers of prodrugs?","options":[{"id":"a","text":"Poor metabolizers are always at higher risk of toxicity"},{"id":"b","text":"Ultrarapid metabolizers always experience treatment failure"},{"id":"c","text":"Poor metabolizers may experience treatment failure"},{"id":"d","text":"Ultrarapid metabolizers have no risk of adverse effects"}],"answerId":"c","explanation":"Poor metabolizers under-activate prodrugs, leading to treatment failure, while ultrarapid metabolizers can experience toxicity.","kind":"trap","origin":"ai"},{"id":"pharmacogenomics~ai-5","moduleId":"pharmacogenomics","stem":"How does G6PD deficiency affect drug metabolism?","options":[{"id":"a","text":"Increased phase I metabolism"},{"id":"b","text":"Increased risk of oxidative stress"},{"id":"c","text":"Decreased drug clearance"},{"id":"d","text":"Altered drug binding"}],"answerId":"b","explanation":"G6PD deficiency leads to increased risk of oxidative stress, resulting in hemolysis with certain drugs.","kind":"mechanism","origin":"ai"},{"id":"pharmacogenomics~ai-6","moduleId":"pharmacogenomics","stem":"How does pharmacogenomics relate to the pharmacokinetics of drug dosing?","options":[{"id":"a","text":"It only affects drug interactions"},{"id":"b","text":"It alters drug efficacy and toxicity based on genetic variation"},{"id":"c","text":"It has no impact on drug metabolism"},{"id":"d","text":"It is unrelated to drug absorption"}],"answerId":"b","explanation":"Pharmacogenomics studies how genetic variations affect drug response, influencing both pharmacokinetics and pharmacodynamics.","kind":"integration","linkedModuleIds":["pharmacokinetics-adme"],"origin":"ai"},{"id":"pharmacogenomics~ai-7","moduleId":"pharmacogenomics","stem":"What is the significance of HLA-B*57:01 testing before prescribing abacavir?","options":[{"id":"a","text":"To assess drug metabolism"},{"id":"b","text":"To predict hypersensitivity reactions"},{"id":"c","text":"To determine drug efficacy"},{"id":"d","text":"To evaluate drug interactions"}],"answerId":"b","explanation":"HLA-B*57:01 testing is crucial to predict hypersensitivity reactions to abacavir, preventing severe adverse effects.","kind":"integration","linkedModuleIds":["adverse-drug-reactions-allergy"],"origin":"ai"}],"cholinergic-drugs":[{"id":"cholinergic-drugs~ai-0","moduleId":"cholinergic-drugs","stem":"Which of the following drugs is a direct muscarinic agonist used to treat glaucoma?","options":[{"id":"a","text":"Bethanechol"},{"id":"b","text":"Pilocarpine"},{"id":"c","text":"Neostigmine"},{"id":"d","text":"Atropine"}],"answerId":"b","explanation":"Pilocarpine is a direct muscarinic agonist that reduces intraocular pressure in glaucoma.","kind":"recall","origin":"ai"},{"id":"cholinergic-drugs~ai-1","moduleId":"cholinergic-drugs","stem":"What is the mechanism of action of neostigmine in myasthenia gravis?","options":[{"id":"a","text":"Direct agonist of nicotinic receptors"},{"id":"b","text":"Inhibition of acetylcholinesterase"},{"id":"c","text":"Stimulation of muscarinic receptors"},{"id":"d","text":"Inhibition of dopamine receptors"}],"answerId":"b","explanation":"Neostigmine inhibits acetylcholinesterase, increasing acetylcholine levels at the neuromuscular junction.","kind":"mechanism","origin":"ai"},{"id":"cholinergic-drugs~ai-2","moduleId":"cholinergic-drugs","stem":"A patient presents with SLUDGE symptoms and miosis after insecticide exposure. What is the most appropriate initial treatment?","options":[{"id":"a","text":"Pralidoxime"},{"id":"b","text":"Atropine"},{"id":"c","text":"Neostigmine"},{"id":"d","text":"Physostigmine"}],"answerId":"b","explanation":"Atropine is used to block muscarinic effects in organophosphate poisoning.","kind":"clinical","origin":"ai"},{"id":"cholinergic-drugs~ai-3","moduleId":"cholinergic-drugs","stem":"Which of the following statements about atropine in organophosphate poisoning is true?","options":[{"id":"a","text":"Atropine reverses all symptoms of poisoning"},{"id":"b","text":"Atropine is effective against nicotinic effects"},{"id":"c","text":"Atropine is used alone for treatment"},{"id":"d","text":"Atropine blocks muscarinic effects only"}],"answerId":"d","explanation":"Atropine only blocks muscarinic effects and does not address nicotinic symptoms, which require pralidoxime.","kind":"trap","origin":"ai"},{"id":"cholinergic-drugs~ai-4","moduleId":"cholinergic-drugs","stem":"Which of the following is a common side effect of antimuscarinic drugs?","options":[{"id":"a","text":"Increased salivation"},{"id":"b","text":"Diarrhea"},{"id":"c","text":"Mydriasis"},{"id":"d","text":"Bradycardia"}],"answerId":"c","explanation":"Antimuscarinic drugs commonly cause mydriasis due to their action of blocking muscarinic receptors.","kind":"recall","origin":"ai"},{"id":"cholinergic-drugs~ai-5","moduleId":"cholinergic-drugs","stem":"In a patient with urinary incontinence, which drug would be most appropriate to reduce bladder contractions?","options":[{"id":"a","text":"Bethanechol"},{"id":"b","text":"Oxybutynin"},{"id":"c","text":"Pilocarpine"},{"id":"d","text":"Neostigmine"}],"answerId":"b","explanation":"Oxybutynin is an antimuscarinic that reduces bladder contractions, helping with urinary incontinence.","kind":"integration","linkedModuleIds":["urinary-incontinence-drugs"],"origin":"ai"},{"id":"cholinergic-drugs~ai-6","moduleId":"cholinergic-drugs","stem":"How does the mechanism of action of adrenergic drugs differ from cholinergic drugs?","options":[{"id":"a","text":"Adrenergic drugs activate muscarinic receptors"},{"id":"b","text":"Cholinergic drugs inhibit norepinephrine"},{"id":"c","text":"Adrenergic drugs stimulate sympathetic responses"},{"id":"d","text":"Cholinergic drugs block adrenergic receptors"}],"answerId":"c","explanation":"Adrenergic drugs stimulate sympathetic responses, while cholinergic drugs enhance parasympathetic activity.","kind":"integration","linkedModuleIds":["adrenergic-drugs"],"origin":"ai"}],"drug-interactions-mechanisms":[{"id":"drug-interactions-mechanisms~ai-0","moduleId":"drug-interactions-mechanisms","stem":"What is the primary mechanism by which CYP inhibitors affect drug levels?","options":[{"id":"a","text":"Increase drug metabolism"},{"id":"b","text":"Decrease drug absorption"},{"id":"c","text":"Increase drug levels"},{"id":"d","text":"Decrease drug excretion"}],"answerId":"c","explanation":"CYP inhibitors block the metabolism of drugs, leading to increased drug levels and potential toxicity.","kind":"mechanism","origin":"ai"},{"id":"drug-interactions-mechanisms~ai-1","moduleId":"drug-interactions-mechanisms","stem":"Which of the following drug combinations is most likely to lead to serotonin syndrome?","options":[{"id":"a","text":"Warfarin + azole"},{"id":"b","text":"SSRI + tramadol"},{"id":"c","text":"Statin + CYP3A4 inhibitor"},{"id":"d","text":"ACE inhibitor + NSAID"}],"answerId":"b","explanation":"The combination of an SSRI and tramadol can lead to serotonin syndrome due to pharmacodynamic synergy.","kind":"clinical","origin":"ai"},{"id":"drug-interactions-mechanisms~ai-2","moduleId":"drug-interactions-mechanisms","stem":"What is a common consequence of combining warfarin with a CYP inhibitor?","options":[{"id":"a","text":"Increased risk of thrombosis"},{"id":"b","text":"Increased risk of bleeding"},{"id":"c","text":"Decreased INR"},{"id":"d","text":"No significant effect"}],"answerId":"b","explanation":"CYP inhibitors can raise warfarin levels, leading to an increased risk of bleeding.","kind":"recall","origin":"ai"},{"id":"drug-interactions-mechanisms~ai-3","moduleId":"drug-interactions-mechanisms","stem":"Which of the following statements about CYP inducers is true?","options":[{"id":"a","text":"They cause immediate changes in drug levels"},{"id":"b","text":"They require days to exert their full effect"},{"id":"c","text":"They increase drug absorption"},{"id":"d","text":"They are always reversible immediately"}],"answerId":"b","explanation":"CYP inducers require days to increase enzyme levels and thus lower drug levels, making their effects delayed.","kind":"trap","origin":"ai"},{"id":"drug-interactions-mechanisms~ai-4","moduleId":"drug-interactions-mechanisms","stem":"A patient on rifampin for tuberculosis presents with contraceptive failure. What is the underlying mechanism?","options":[{"id":"a","text":"CYP inhibition"},{"id":"b","text":"CYP induction"},{"id":"c","text":"Increased absorption"},{"id":"d","text":"Protein binding displacement"}],"answerId":"b","explanation":"Rifampin is a CYP inducer that lowers the levels of contraceptive drugs, leading to therapeutic failure.","kind":"mechanism","origin":"ai"},{"id":"drug-interactions-mechanisms~ai-5","moduleId":"drug-interactions-mechanisms","stem":"How does chronic alcohol consumption affect the metabolism of drugs like phenytoin?","options":[{"id":"a","text":"Inhibits CYP metabolism"},{"id":"b","text":"Induces CYP metabolism"},{"id":"c","text":"Increases absorption"},{"id":"d","text":"Decreases renal excretion"}],"answerId":"b","explanation":"Chronic alcohol consumption induces CYP enzymes, which can lead to decreased levels of drugs like phenytoin.","kind":"mechanism","origin":"ai"},{"id":"drug-interactions-mechanisms~ai-6","moduleId":"drug-interactions-mechanisms","stem":"A patient with CKD is prescribed digoxin and is also taking verapamil. What is the primary concern?","options":[{"id":"a","text":"Digoxin toxicity due to CYP inhibition"},{"id":"b","text":"Subtherapeutic digoxin levels"},{"id":"c","text":"Increased renal clearance of digoxin"},{"id":"d","text":"No significant interaction"}],"answerId":"a","explanation":"Verapamil is a CYP inhibitor that can raise digoxin levels, leading to potential toxicity, especially in CKD patients.","kind":"integration","linkedModuleIds":["drug-dosing-ckd"],"origin":"ai"},{"id":"drug-interactions-mechanisms~ai-7","moduleId":"drug-interactions-mechanisms","stem":"Which drug interaction mechanism is most relevant when considering the effects of azole antifungals on statins?","options":[{"id":"a","text":"CYP inhibition"},{"id":"b","text":"CYP induction"},{"id":"c","text":"Protein binding displacement"},{"id":"d","text":"Renal excretion alteration"}],"answerId":"a","explanation":"Azole antifungals are CYP inhibitors that can raise statin levels, increasing the risk of rhabdomyolysis.","kind":"integration","linkedModuleIds":["antifungal-agents"],"origin":"ai"}],"immunomodulating-agents":[{"id":"immunomodulating-agents~ai-0","moduleId":"immunomodulating-agents","stem":"What is the primary mechanism of action of glucocorticoids in immunosuppression?","options":[{"id":"a","text":"Inhibition of IL-2 production"},{"id":"b","text":"Inhibition of NF-κB"},{"id":"c","text":"Stimulation of T-cell proliferation"},{"id":"d","text":"Activation of macrophages"}],"answerId":"b","explanation":"Glucocorticoids inhibit NF-κB, leading to decreased cytokine production and immune suppression.","kind":"mechanism","origin":"ai"},{"id":"immunomodulating-agents~ai-1","moduleId":"immunomodulating-agents","stem":"Which of the following is a common side effect of calcineurin inhibitors like tacrolimus?","options":[{"id":"a","text":"Hirsutism"},{"id":"b","text":"Neutropenia"},{"id":"c","text":"Gum hypertrophy"},{"id":"d","text":"Osteoporosis"}],"answerId":"a","explanation":"Ciclosporin, a calcineurin inhibitor, can cause gum hypertrophy as a side effect.","kind":"recall","origin":"ai"},{"id":"immunomodulating-agents~ai-2","moduleId":"immunomodulating-agents","stem":"Which immunomodulating agent is most likely to cause severe myelosuppression in a patient with low TPMT activity?","options":[{"id":"a","text":"Methotrexate"},{"id":"b","text":"Mycophenolate"},{"id":"c","text":"Azathioprine"},{"id":"d","text":"Ciclosporin"}],"answerId":"c","explanation":"Azathioprine can cause severe myelosuppression in patients with low TPMT activity due to impaired metabolism.","kind":"clinical","origin":"ai"},{"id":"immunomodulating-agents~ai-3","moduleId":"immunomodulating-agents","stem":"What is the risk associated with anti-TNF-α therapy in patients with latent tuberculosis?","options":[{"id":"a","text":"Increased risk of renal failure"},{"id":"b","text":"Reactivation of latent TB"},{"id":"c","text":"Increased risk of hyperglycemia"},{"id":"d","text":"Decreased efficacy of vaccines"}],"answerId":"b","explanation":"Anti-TNF-α therapy can reactivate latent tuberculosis, necessitating screening before treatment.","kind":"trap","origin":"ai"},{"id":"immunomodulating-agents~ai-4","moduleId":"immunomodulating-agents","stem":"Which immunomodulator is primarily used to enhance recovery of neutrophils after chemotherapy?","options":[{"id":"a","text":"Interferon"},{"id":"b","text":"Filgrastim"},{"id":"c","text":"Azathioprine"},{"id":"d","text":"Ciclosporin"}],"answerId":"b","explanation":"Filgrastim, a colony-stimulating factor, is used to stimulate neutrophil recovery post-chemotherapy.","kind":"recall","origin":"ai"},{"id":"immunomodulating-agents~ai-5","moduleId":"immunomodulating-agents","stem":"A patient receiving immunotherapy with a checkpoint inhibitor develops autoimmune thyroiditis. What is the most likely mechanism?","options":[{"id":"a","text":"Inhibition of IL-2"},{"id":"b","text":"Release of immune checkpoints"},{"id":"c","text":"Stimulation of TNF-α"},{"id":"d","text":"Inhibition of NF-κB"}],"answerId":"b","explanation":"Checkpoint inhibitors release the brakes on T cells, leading to autoimmune adverse events like thyroiditis.","kind":"mechanism","origin":"ai"},{"id":"immunomodulating-agents~ai-6","moduleId":"immunomodulating-agents","stem":"How does azathioprine's mechanism relate to pharmacogenomics?","options":[{"id":"a","text":"It inhibits calcineurin"},{"id":"b","text":"TPMT genotype affects its toxicity"},{"id":"c","text":"It stimulates IL-2 production"},{"id":"d","text":"It enhances neutrophil recovery"}],"answerId":"b","explanation":"Azathioprine's toxicity is influenced by TPMT genotype, highlighting the importance of pharmacogenomics.","kind":"integration","linkedModuleIds":["pharmacogenomics"],"origin":"ai"},{"id":"immunomodulating-agents~ai-7","moduleId":"immunomodulating-agents","stem":"What is a critical consideration when using immunomodulating agents in cancer therapy?","options":[{"id":"a","text":"Increased risk of infection"},{"id":"b","text":"Decreased efficacy of vaccines"},{"id":"c","text":"Inhibition of IL-6"},{"id":"d","text":"Increased risk of hypertension"}],"answerId":"a","explanation":"Immunomodulating agents, especially immunosuppressants, significantly increase the risk of infections.","kind":"integration","linkedModuleIds":["antineoplastic-principles"],"origin":"ai"}],"antidotes-principles":[{"id":"antidotes-principles~ai-0","moduleId":"antidotes-principles","stem":"What is the primary mechanism of action of N-acetylcysteine in paracetamol overdose?","options":[{"id":"a","text":"Replenishes glutathione"},{"id":"b","text":"Blocks opioid receptors"},{"id":"c","text":"Chelates iron"},{"id":"d","text":"Inhibits alcohol dehydrogenase"}],"answerId":"a","explanation":"N-acetylcysteine replenishes glutathione, which is depleted in paracetamol overdose, thereby preventing liver damage.","kind":"mechanism","origin":"ai"},{"id":"antidotes-principles~ai-1","moduleId":"antidotes-principles","stem":"Which antidote is used to reverse opioid toxicity?","options":[{"id":"a","text":"Flumazenil"},{"id":"b","text":"Naloxone"},{"id":"c","text":"Atropine"},{"id":"d","text":"Deferoxamine"}],"answerId":"b","explanation":"Naloxone is an opioid receptor antagonist used to reverse the effects of opioid toxicity.","kind":"recall","origin":"ai"},{"id":"antidotes-principles~ai-2","moduleId":"antidotes-principles","stem":"What is the mainstay of treatment for most poisonings?","options":[{"id":"a","text":"Specific antidotes"},{"id":"b","text":"Supportive care"},{"id":"c","text":"Activated charcoal"},{"id":"d","text":"Hemodialysis"}],"answerId":"b","explanation":"Supportive care is the mainstay of treatment for most poisonings, as only a minority have specific antidotes.","kind":"trap","origin":"ai"},{"id":"antidotes-principles~ai-3","moduleId":"antidotes-principles","stem":"In methanol poisoning, which antidote blocks the enzyme responsible for methanol metabolism?","options":[{"id":"a","text":"N-acetylcysteine"},{"id":"b","text":"Fomepizole"},{"id":"c","text":"Atropine"},{"id":"d","text":"Flumazenil"}],"answerId":"b","explanation":"Fomepizole inhibits alcohol dehydrogenase, preventing the conversion of methanol to its toxic metabolites.","kind":"mechanism","origin":"ai"},{"id":"antidotes-principles~ai-4","moduleId":"antidotes-principles","stem":"A patient presents with respiratory depression, pinpoint pupils, and coma. What is the most appropriate immediate treatment?","options":[{"id":"a","text":"Flumazenil"},{"id":"b","text":"Naloxone"},{"id":"c","text":"Activated charcoal"},{"id":"d","text":"N-acetylcysteine"}],"answerId":"b","explanation":"Naloxone is the appropriate treatment to reverse opioid-induced respiratory depression and coma.","kind":"clinical","origin":"ai"},{"id":"antidotes-principles~ai-5","moduleId":"antidotes-principles","stem":"Which antidote is used for iron overdose?","options":[{"id":"a","text":"Deferoxamine"},{"id":"b","text":"Digoxin-specific Fab"},{"id":"c","text":"Vitamin K"},{"id":"d","text":"Pralidoxime"}],"answerId":"a","explanation":"Deferoxamine is a chelating agent used to treat iron overdose by binding excess iron.","kind":"recall","origin":"ai"},{"id":"antidotes-principles~ai-6","moduleId":"antidotes-principles","stem":"How does atropine function in organophosphate poisoning?","options":[{"id":"a","text":"Blocks acetylcholine receptors"},{"id":"b","text":"Replenishes acetylcholine"},{"id":"c","text":"Inhibits acetylcholinesterase"},{"id":"d","text":"Chelates organophosphate toxins"}],"answerId":"a","explanation":"Atropine blocks acetylcholine receptors, counteracting the effects of excess acetylcholine due to organophosphate poisoning.","kind":"mechanism","origin":"ai"},{"id":"antidotes-principles~ai-7","moduleId":"antidotes-principles","stem":"In the context of paracetamol overdose, how does the mechanism of N-acetylcysteine relate to the adverse effects of paracetamol?","options":[{"id":"a","text":"It inhibits the metabolism of paracetamol"},{"id":"b","text":"It replenishes glutathione to prevent hepatotoxicity"},{"id":"c","text":"It chelates paracetamol"},{"id":"d","text":"It enhances renal excretion of paracetamol"}],"answerId":"b","explanation":"N-acetylcysteine replenishes glutathione, which is necessary to neutralize the toxic metabolite of paracetamol, preventing liver damage.","kind":"integration","linkedModuleIds":["adverse-drug-reactions-allergy"],"origin":"ai"},{"id":"antidotes-principles~ai-8","moduleId":"antidotes-principles","stem":"What is the role of supportive care in the management of poisoning, particularly in relation to antidotes?","options":[{"id":"a","text":"It is secondary to antidotes"},{"id":"b","text":"It is the primary treatment for most poisonings"},{"id":"c","text":"It is only necessary when antidotes are unavailable"},{"id":"d","text":"It complicates the use of antidotes"}],"answerId":"b","explanation":"Supportive care is the primary treatment for most poisonings, as specific antidotes are only available for a minority of cases.","kind":"integration","linkedModuleIds":["toxidromes-poisoning-approach"],"origin":"ai"}],"adverse-drug-reactions-allergy":[{"id":"adverse-drug-reactions-allergy~ai-0","moduleId":"adverse-drug-reactions-allergy","stem":"What type of adverse drug reaction (ADR) is characterized by predictable, dose-dependent effects?","options":[{"id":"a","text":"Type A"},{"id":"b","text":"Type B"},{"id":"c","text":"Type I"},{"id":"d","text":"Type IV"}],"answerId":"a","explanation":"Type A ADRs are predictable and related to the pharmacological effects of the drug, making them dose-dependent.","kind":"recall","origin":"ai"},{"id":"adverse-drug-reactions-allergy~ai-1","moduleId":"adverse-drug-reactions-allergy","stem":"Which type of drug allergy is mediated by IgE and can lead to anaphylaxis?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"a","explanation":"Type I hypersensitivity reactions are mediated by IgE antibodies and can result in immediate allergic responses such as anaphylaxis.","kind":"recall","origin":"ai"},{"id":"adverse-drug-reactions-allergy~ai-2","moduleId":"adverse-drug-reactions-allergy","stem":"A patient develops urticaria and bronchospasm shortly after receiving penicillin. What is the most appropriate immediate treatment?","options":[{"id":"a","text":"Antihistamines"},{"id":"b","text":"Intravenous fluids"},{"id":"c","text":"Intramuscular adrenaline"},{"id":"d","text":"Corticosteroids"}],"answerId":"c","explanation":"Intramuscular adrenaline is the first-line treatment for anaphylaxis, which includes urticaria and bronchospasm.","kind":"clinical","origin":"ai"},{"id":"adverse-drug-reactions-allergy~ai-3","moduleId":"adverse-drug-reactions-allergy","stem":"Which of the following findings is characteristic of Stevens-Johnson syndrome (SJS)?","options":[{"id":"a","text":"Immediate urticaria after drug exposure"},{"id":"b","text":"Mucocutaneous blistering and skin detachment"},{"id":"c","text":"Eosinophilia and systemic symptoms"},{"id":"d","text":"Flushing without IgE mechanism"}],"answerId":"b","explanation":"SJS is characterized by mucocutaneous blistering and skin detachment, often occurring weeks after drug exposure.","kind":"recall","origin":"ai"},{"id":"adverse-drug-reactions-allergy~ai-4","moduleId":"adverse-drug-reactions-allergy","stem":"What distinguishes a pseudo-allergic reaction from a true drug allergy?","options":[{"id":"a","text":"IgE involvement"},{"id":"b","text":"Dose-dependence"},{"id":"c","text":"Predictability"},{"id":"d","text":"Mast cell degranulation"}],"answerId":"d","explanation":"Pseudo-allergic reactions involve direct mast cell degranulation and do not involve IgE, unlike true allergies.","kind":"trap","origin":"ai"},{"id":"adverse-drug-reactions-allergy~ai-5","moduleId":"adverse-drug-reactions-allergy","stem":"A patient presents with a rash, fever, and eosinophilia after starting a new anticonvulsant. What syndrome is most likely?","options":[{"id":"a","text":"Stevens-Johnson syndrome"},{"id":"b","text":"DRESS syndrome"},{"id":"c","text":"Anaphylaxis"},{"id":"d","text":"Type I hypersensitivity"}],"answerId":"b","explanation":"The combination of rash, fever, eosinophilia, and systemic symptoms is characteristic of DRESS syndrome.","kind":"clinical","origin":"ai"},{"id":"adverse-drug-reactions-allergy~ai-6","moduleId":"adverse-drug-reactions-allergy","stem":"How does pharmacogenomics relate to severe cutaneous adverse reactions (SCARs)?","options":[{"id":"a","text":"It identifies dose-dependent reactions"},{"id":"b","text":"It helps predict immune-mediated reactions"},{"id":"c","text":"It provides treatment options for anaphylaxis"},{"id":"d","text":"It explains pseudo-allergic reactions"}],"answerId":"b","explanation":"Pharmacogenomics can identify genetic predispositions that increase the risk of immune-mediated reactions leading to SCARs.","kind":"integration","linkedModuleIds":["pharmacogenomics-clinical-implementation"],"origin":"ai"},{"id":"adverse-drug-reactions-allergy~ai-7","moduleId":"adverse-drug-reactions-allergy","stem":"What is the primary mechanism behind the flushing reaction associated with vancomycin?","options":[{"id":"a","text":"IgE-mediated response"},{"id":"b","text":"Mast cell degranulation"},{"id":"c","text":"Dose-dependent toxicity"},{"id":"d","text":"Immune complex formation"}],"answerId":"b","explanation":"The flushing reaction from vancomycin is due to direct mast cell degranulation, not an IgE-mediated response.","kind":"clinical","origin":"ai"}],"preclinical-drug-discovery":[{"id":"preclinical-drug-discovery~ai-0","moduleId":"preclinical-drug-discovery","stem":"What is the primary purpose of preclinical toxicology studies?","options":[{"id":"a","text":"To demonstrate drug efficacy in humans"},{"id":"b","text":"To establish a safe starting dose for human trials"},{"id":"c","text":"To identify potential market competitors"},{"id":"d","text":"To optimize the drug's chemical structure"}],"answerId":"b","explanation":"Preclinical toxicology studies primarily aim to establish safety and determine a safe starting dose for first-in-human trials.","kind":"recall","origin":"ai"},{"id":"preclinical-drug-discovery~ai-1","moduleId":"preclinical-drug-discovery","stem":"Which of the following best describes the role of the Investigational New Drug (IND) application?","options":[{"id":"a","text":"It is a marketing authorization for a new drug"},{"id":"b","text":"It permits first-in-human trials based on preclinical data"},{"id":"c","text":"It outlines the drug's mechanism of action"},{"id":"d","text":"It is a requirement for animal testing"}],"answerId":"b","explanation":"The IND application is a regulatory step that allows researchers to begin human trials based on the safety and efficacy data gathered during preclinical studies.","kind":"recall","origin":"ai"},{"id":"preclinical-drug-discovery~ai-2","moduleId":"preclinical-drug-discovery","stem":"What is the significance of Lipinski's 'rule of five' in drug discovery?","options":[{"id":"a","text":"It predicts a drug's efficacy in humans"},{"id":"b","text":"It assesses a drug's safety profile"},{"id":"c","text":"It evaluates a compound's drug-like properties for oral absorption"},{"id":"d","text":"It determines the cost of drug production"}],"answerId":"c","explanation":"Lipinski's 'rule of five' helps in evaluating a compound's drug-like properties, particularly its potential for oral absorption.","kind":"recall","origin":"ai"},{"id":"preclinical-drug-discovery~ai-3","moduleId":"preclinical-drug-discovery","stem":"In preclinical development, what is the main focus of pharmacokinetics (PK) studies?","options":[{"id":"a","text":"To assess the drug's mechanism of action"},{"id":"b","text":"To evaluate the drug's safety in animal models"},{"id":"c","text":"To characterize absorption, distribution, metabolism, and excretion"},{"id":"d","text":"To determine the drug's market potential"}],"answerId":"c","explanation":"Pharmacokinetics studies focus on characterizing how a drug is absorbed, distributed, metabolized, and excreted in the body.","kind":"recall","origin":"ai"},{"id":"preclinical-drug-discovery~ai-4","moduleId":"preclinical-drug-discovery","stem":"Which statement about preclinical studies is true?","options":[{"id":"a","text":"They primarily prove that a drug works"},{"id":"b","text":"They establish safety and pharmacokinetics to justify first-in-human dosing"},{"id":"c","text":"They guarantee success in human trials"},{"id":"d","text":"They are not required for biologics"}],"answerId":"b","explanation":"Preclinical studies primarily establish safety and pharmacokinetics, which are critical for justifying first-in-human dosing.","kind":"trap","origin":"ai"},{"id":"preclinical-drug-discovery~ai-5","moduleId":"preclinical-drug-discovery","stem":"How do preclinical toxicology studies relate to post-marketing safety assessments?","options":[{"id":"a","text":"They are not related"},{"id":"b","text":"They provide initial safety data that informs post-marketing monitoring"},{"id":"c","text":"They replace the need for post-marketing studies"},{"id":"d","text":"They focus solely on drug efficacy"}],"answerId":"b","explanation":"Preclinical toxicology studies provide initial safety data that is crucial for post-marketing monitoring of adverse drug reactions.","kind":"integration","linkedModuleIds":["adverse-drug-reactions-allergy"],"origin":"ai"},{"id":"preclinical-drug-discovery~ai-6","moduleId":"preclinical-drug-discovery","stem":"What is the connection between pharmacokinetics studies and drug dosing in clinical trials?","options":[{"id":"a","text":"PK studies are irrelevant to dosing"},{"id":"b","text":"PK studies help determine the appropriate dosing regimen based on absorption and metabolism"},{"id":"c","text":"PK studies only focus on drug efficacy"},{"id":"d","text":"PK studies are conducted only after clinical trials"}],"answerId":"b","explanation":"Pharmacokinetics studies inform the appropriate dosing regimen by evaluating how the drug is absorbed and metabolized, which is crucial for clinical trial design.","kind":"integration","linkedModuleIds":["pharmacokinetics-adme"],"origin":"ai"}],"antiviral-antiretroviral-agents":[{"id":"antiviral-antiretroviral-agents~ai-0","moduleId":"antiviral-antiretroviral-agents","stem":"What is the mechanism of action of aciclovir?","options":[{"id":"a","text":"Inhibits viral RNA polymerase"},{"id":"b","text":"Inhibits viral DNA polymerase directly"},{"id":"c","text":"Activated by viral thymidine kinase to terminate viral DNA synthesis"},{"id":"d","text":"Blocks viral entry into host cells"}],"answerId":"c","explanation":"Aciclovir is a prodrug that is activated by viral thymidine kinase, leading to chain termination of viral DNA synthesis.","kind":"mechanism","origin":"ai"},{"id":"antiviral-antiretroviral-agents~ai-1","moduleId":"antiviral-antiretroviral-agents","stem":"Which drug is primarily used to treat influenza and must be administered within 48 hours of symptom onset?","options":[{"id":"a","text":"Oseltamivir"},{"id":"b","text":"Acyclovir"},{"id":"c","text":"Ganciclovir"},{"id":"d","text":"Ritonavir"}],"answerId":"a","explanation":"Oseltamivir is a neuraminidase inhibitor that is most effective when given early in the course of influenza infection.","kind":"recall","origin":"ai"},{"id":"antiviral-antiretroviral-agents~ai-2","moduleId":"antiviral-antiretroviral-agents","stem":"A patient develops a life-threatening hypersensitivity reaction after starting abacavir. What is the recommended action before initiating therapy with this drug?","options":[{"id":"a","text":"Monitor renal function"},{"id":"b","text":"Screen for HLA-B*57:01"},{"id":"c","text":"Perform a liver function test"},{"id":"d","text":"Assess for drug interactions"}],"answerId":"b","explanation":"Patients should be screened for the HLA-B*57:01 allele before starting abacavir to prevent hypersensitivity reactions.","kind":"clinical","origin":"ai"},{"id":"antiviral-antiretroviral-agents~ai-3","moduleId":"antiviral-antiretroviral-agents","stem":"Which of the following antiviral agents is associated with renal impairment if not adequately hydrated?","options":[{"id":"a","text":"Oseltamivir"},{"id":"b","text":"Acyclovir"},{"id":"c","text":"Ganciclovir"},{"id":"d","text":"Tenofovir"}],"answerId":"b","explanation":"Acyclovir can cause crystalluria and nephrotoxicity if the patient is not properly hydrated.","kind":"trap","origin":"ai"},{"id":"antiviral-antiretroviral-agents~ai-4","moduleId":"antiviral-antiretroviral-agents","stem":"What is the main reason for combining multiple antiretroviral drugs in HIV treatment?","options":[{"id":"a","text":"To enhance patient compliance"},{"id":"b","text":"To reduce drug costs"},{"id":"c","text":"To prevent the development of resistance"},{"id":"d","text":"To minimize side effects"}],"answerId":"c","explanation":"Combining multiple antiretroviral drugs helps to suppress the virus and prevent the development of resistance.","kind":"recall","origin":"ai"},{"id":"antiviral-antiretroviral-agents~ai-5","moduleId":"antiviral-antiretroviral-agents","stem":"Which class of drugs is primarily used to treat chronic Hepatitis C?","options":[{"id":"a","text":"NRTIs"},{"id":"b","text":"NNRTIs"},{"id":"c","text":"Direct-acting antivirals"},{"id":"d","text":"Protease inhibitors"}],"answerId":"c","explanation":"Direct-acting antivirals (DAAs) are the mainstay of treatment for chronic Hepatitis C, providing a cure.","kind":"recall","origin":"ai"},{"id":"antiviral-antiretroviral-agents~ai-6","moduleId":"antiviral-antiretroviral-agents","stem":"How does the mechanism of action of aciclovir differ from that of foscarnet?","options":[{"id":"a","text":"Aciclovir requires viral activation, while foscarnet does not"},{"id":"b","text":"Foscarnet is a prodrug, aciclovir is not"},{"id":"c","text":"Aciclovir targets RNA viruses, foscarnet targets DNA viruses"},{"id":"d","text":"Foscarnet is only effective against resistant strains"}],"answerId":"a","explanation":"Aciclovir requires activation by viral thymidine kinase, while foscarnet directly inhibits viral DNA polymerase without needing activation.","kind":"integration","linkedModuleIds":["herpesvirus-cmv-antivirals"],"origin":"ai"},{"id":"antiviral-antiretroviral-agents~ai-7","moduleId":"antiviral-antiretroviral-agents","stem":"Which of the following drugs is most effective for treating respiratory viral infections?","options":[{"id":"a","text":"Acyclovir"},{"id":"b","text":"Oseltamivir"},{"id":"c","text":"Tenofovir"},{"id":"d","text":"Ritonavir"}],"answerId":"b","explanation":"Oseltamivir is specifically indicated for the treatment of influenza, a respiratory viral infection.","kind":"integration","linkedModuleIds":["respiratory-antiviral-drugs"],"origin":"ai"}],"antibacterial-cell-wall-agents":[{"id":"antibacterial-cell-wall-agents~ai-0","moduleId":"antibacterial-cell-wall-agents","stem":"What is the primary mechanism of action of β-lactam antibiotics?","options":[{"id":"a","text":"Inhibit protein synthesis"},{"id":"b","text":"Block peptidoglycan cross-linking"},{"id":"c","text":"Disrupt cell membrane integrity"},{"id":"d","text":"Inhibit nucleic acid synthesis"}],"answerId":"b","explanation":"β-lactam antibiotics primarily inhibit the transpeptidation process in bacterial cell wall synthesis by binding to penicillin-binding proteins.","kind":"mechanism","origin":"ai"},{"id":"antibacterial-cell-wall-agents~ai-1","moduleId":"antibacterial-cell-wall-agents","stem":"Which of the following antibiotics is specifically indicated for treating MRSA infections?","options":[{"id":"a","text":"Ceftriaxone"},{"id":"b","text":"Vancomycin"},{"id":"c","text":"Amoxicillin"},{"id":"d","text":"Piperacillin"}],"answerId":"b","explanation":"Vancomycin is the drug of choice for treating serious MRSA infections due to its mechanism of inhibiting cell wall synthesis.","kind":"recall","origin":"ai"},{"id":"antibacterial-cell-wall-agents~ai-2","moduleId":"antibacterial-cell-wall-agents","stem":"A patient develops flushing and erythema of the upper body during an IV vancomycin infusion. What is the most appropriate management?","options":[{"id":"a","text":"Discontinue vancomycin"},{"id":"b","text":"Administer an antihistamine"},{"id":"c","text":"Slow the infusion rate"},{"id":"d","text":"Switch to a different antibiotic"}],"answerId":"c","explanation":"This reaction is known as red-man syndrome, which is a rate-related histamine release reaction; slowing the infusion rate is the appropriate management.","kind":"trap","origin":"ai"},{"id":"antibacterial-cell-wall-agents~ai-3","moduleId":"antibacterial-cell-wall-agents","stem":"Which bacterial resistance mechanism involves the alteration of penicillin-binding proteins?","options":[{"id":"a","text":"β-lactamase production"},{"id":"b","text":"Efflux pump activation"},{"id":"c","text":"Altered PBPs"},{"id":"d","text":"Decreased cell wall permeability"}],"answerId":"c","explanation":"Altered penicillin-binding proteins, such as PBP2a in MRSA, confer resistance to β-lactam antibiotics.","kind":"mechanism","origin":"ai"},{"id":"antibacterial-cell-wall-agents~ai-4","moduleId":"antibacterial-cell-wall-agents","stem":"Which cephalosporin is most appropriate for treating bacterial meningitis caused by Gram-negative bacteria?","options":[{"id":"a","text":"Cefazolin"},{"id":"b","text":"Ceftriaxone"},{"id":"c","text":"Cefepime"},{"id":"d","text":"Ceftazidime"}],"answerId":"b","explanation":"Ceftriaxone is a third-generation cephalosporin that penetrates the CNS and is effective against Gram-negative bacteria causing meningitis.","kind":"recall","origin":"ai"},{"id":"antibacterial-cell-wall-agents~ai-5","moduleId":"antibacterial-cell-wall-agents","stem":"A patient with a history of penicillin allergy is diagnosed with a Pseudomonas infection. Which antibiotic is safe to use?","options":[{"id":"a","text":"Cloxacillin"},{"id":"b","text":"Aztreonam"},{"id":"c","text":"Amoxicillin"},{"id":"d","text":"Meropenem"}],"answerId":"b","explanation":"Aztreonam is a monobactam antibiotic that is safe for patients with penicillin allergy and is effective against Gram-negative bacteria, including Pseudomonas.","kind":"recall","origin":"ai"},{"id":"antibacterial-cell-wall-agents~ai-6","moduleId":"antibacterial-cell-wall-agents","stem":"How do β-lactam antibiotics differ from glycopeptides in their mechanism of action?","options":[{"id":"a","text":"Both inhibit protein synthesis"},{"id":"b","text":"Only β-lactams bind to D-Ala-D-Ala"},{"id":"c","text":"Glycopeptides inhibit cell wall synthesis by binding to D-Ala-D-Ala"},{"id":"d","text":"Only glycopeptides are bactericidal"}],"answerId":"c","explanation":"Glycopeptides, such as vancomycin, inhibit cell wall synthesis by binding to the D-Ala-D-Ala terminus of peptidoglycan precursors, while β-lactams inhibit transpeptidation.","kind":"integration","linkedModuleIds":["bacterial-structure-cell-wall"],"origin":"ai"},{"id":"antibacterial-cell-wall-agents~ai-7","moduleId":"antibacterial-cell-wall-agents","stem":"Which of the following is a common mechanism of resistance to both β-lactams and glycopeptides?","options":[{"id":"a","text":"Altered PBPs"},{"id":"b","text":"Increased cell wall permeability"},{"id":"c","text":"Inhibition of efflux pumps"},{"id":"d","text":"Increased affinity for D-Ala-D-Ala"}],"answerId":"a","explanation":"Altered penicillin-binding proteins (PBPs) can confer resistance to β-lactams, and similar mechanisms can affect glycopeptide efficacy, particularly in MRSA.","kind":"integration","linkedModuleIds":["antibacterial-resistance-mechanisms"],"origin":"ai"}],"antibacterial-protein-synthesis-inhibitors":[{"id":"antibacterial-protein-synthesis-inhibitors~ai-0","moduleId":"antibacterial-protein-synthesis-inhibitors","stem":"Which antibiotic class inhibits the 30S ribosomal subunit?","options":[{"id":"a","text":"Macrolides"},{"id":"b","text":"Aminoglycosides"},{"id":"c","text":"Clindamycin"},{"id":"d","text":"Rifampin"}],"answerId":"b","explanation":"Aminoglycosides target the 30S ribosomal subunit, while macrolides and clindamycin target the 50S subunit, and rifampin inhibits RNA polymerase.","kind":"recall","origin":"ai"},{"id":"antibacterial-protein-synthesis-inhibitors~ai-1","moduleId":"antibacterial-protein-synthesis-inhibitors","stem":"What is the primary mechanism of action of fluoroquinolones?","options":[{"id":"a","text":"Inhibition of RNA polymerase"},{"id":"b","text":"Inhibition of DNA gyrase"},{"id":"c","text":"Inhibition of dihydrofolate reductase"},{"id":"d","text":"Inhibition of ribosomal protein synthesis"}],"answerId":"b","explanation":"Fluoroquinolones inhibit DNA gyrase, which is essential for bacterial DNA replication.","kind":"mechanism","origin":"ai"},{"id":"antibacterial-protein-synthesis-inhibitors~ai-2","moduleId":"antibacterial-protein-synthesis-inhibitors","stem":"A patient presents with tendon rupture after starting a new antibiotic. Which class of antibiotics is most likely responsible?","options":[{"id":"a","text":"Aminoglycosides"},{"id":"b","text":"Tetracyclines"},{"id":"c","text":"Fluoroquinolones"},{"id":"d","text":"Macrolides"}],"answerId":"c","explanation":"Fluoroquinolones are associated with tendon rupture due to their mechanism of action.","kind":"recall","origin":"ai"},{"id":"antibacterial-protein-synthesis-inhibitors~ai-3","moduleId":"antibacterial-protein-synthesis-inhibitors","stem":"Which of the following antibiotics is contraindicated in children due to the risk of tooth discoloration?","options":[{"id":"a","text":"Clindamycin"},{"id":"b","text":"Doxycycline"},{"id":"c","text":"Azithromycin"},{"id":"d","text":"Rifampin"}],"answerId":"b","explanation":"Doxycycline, a tetracycline, can cause tooth discoloration in children due to its chelation with calcium.","kind":"recall","origin":"ai"},{"id":"antibacterial-protein-synthesis-inhibitors~ai-4","moduleId":"antibacterial-protein-synthesis-inhibitors","stem":"What is the risk associated with co-administering rifampin with oral contraceptives?","options":[{"id":"a","text":"Increased contraceptive efficacy"},{"id":"b","text":"Decreased contraceptive efficacy"},{"id":"c","text":"Increased risk of thrombosis"},{"id":"d","text":"Decreased risk of thrombosis"}],"answerId":"b","explanation":"Rifampin is a potent CYP450 inducer, which can lower the levels of oral contraceptives, risking contraceptive failure.","kind":"trap","origin":"ai"},{"id":"antibacterial-protein-synthesis-inhibitors~ai-5","moduleId":"antibacterial-protein-synthesis-inhibitors","stem":"Which of the following antibiotics is primarily used for anaerobic infections?","options":[{"id":"a","text":"Ciprofloxacin"},{"id":"b","text":"Clindamycin"},{"id":"c","text":"Gentamicin"},{"id":"d","text":"Doxycycline"}],"answerId":"b","explanation":"Clindamycin is effective against anaerobes and is often used for anaerobic infections.","kind":"recall","origin":"ai"},{"id":"antibacterial-protein-synthesis-inhibitors~ai-6","moduleId":"antibacterial-protein-synthesis-inhibitors","stem":"How does co-trimoxazole exert its antibacterial effect?","options":[{"id":"a","text":"Inhibits DNA gyrase"},{"id":"b","text":"Inhibits dihydrofolate reductase and dihydropteroate synthase"},{"id":"c","text":"Inhibits RNA polymerase"},{"id":"d","text":"Inhibits ribosomal protein synthesis"}],"answerId":"b","explanation":"Co-trimoxazole combines trimethoprim and sulfamethoxazole to sequentially inhibit folate synthesis.","kind":"mechanism","origin":"ai"},{"id":"antibacterial-protein-synthesis-inhibitors~ai-7","moduleId":"antibacterial-protein-synthesis-inhibitors","stem":"Which mechanism of resistance is commonly associated with aminoglycosides?","options":[{"id":"a","text":"Efflux pumps"},{"id":"b","text":"Ribosomal methylation"},{"id":"c","text":"Enzymatic modification"},{"id":"d","text":"Target mutation"}],"answerId":"c","explanation":"Aminoglycosides are often inactivated by enzymatic modification, leading to resistance.","kind":"trap","origin":"ai"},{"id":"antibacterial-protein-synthesis-inhibitors~ai-8","moduleId":"antibacterial-protein-synthesis-inhibitors","stem":"How does the use of aminoglycosides relate to nephrotoxic drugs?","options":[{"id":"a","text":"They are safe to use together"},{"id":"b","text":"Aminoglycosides can exacerbate nephrotoxicity"},{"id":"c","text":"They have no interaction"},{"id":"d","text":"Aminoglycosides protect against nephrotoxicity"}],"answerId":"b","explanation":"Aminoglycosides are known to cause nephrotoxicity, which can be exacerbated when used with other nephrotoxic drugs.","kind":"integration","linkedModuleIds":["nephrotoxic-drugs"],"origin":"ai"},{"id":"antibacterial-protein-synthesis-inhibitors~ai-9","moduleId":"antibacterial-protein-synthesis-inhibitors","stem":"What is the significance of ribosomal subunit targeting in antibiotic therapy?","options":[{"id":"a","text":"It determines the spectrum of activity"},{"id":"b","text":"It affects the dosing schedule"},{"id":"c","text":"It influences the side effect profile"},{"id":"d","text":"It impacts drug interactions"}],"answerId":"a","explanation":"The ribosomal subunit targeted by an antibiotic determines its spectrum of activity against different bacteria.","kind":"integration","linkedModuleIds":["antibacterial-resistance-mechanisms"],"origin":"ai"}],"adrenergic-antagonists-blockers":[{"id":"adrenergic-antagonists-blockers~ai-0","moduleId":"adrenergic-antagonists-blockers","stem":"Which of the following is a common side effect of β-blockers?","options":[{"id":"a","text":"Bradycardia"},{"id":"b","text":"Hyperglycemia"},{"id":"c","text":"Tachycardia"},{"id":"d","text":"Hypertension"}],"answerId":"a","explanation":"Bradycardia is a well-known side effect of β-blockers due to their action on β1-adrenoceptors in the heart.","kind":"recall","origin":"ai"},{"id":"adrenergic-antagonists-blockers~ai-1","moduleId":"adrenergic-antagonists-blockers","stem":"What is the primary mechanism of action of α1-blockers in treating hypertension?","options":[{"id":"a","text":"Inhibition of renin release"},{"id":"b","text":"Vasodilation of vascular smooth muscle"},{"id":"c","text":"Decreased heart rate"},{"id":"d","text":"Increased cardiac output"}],"answerId":"b","explanation":"α1-blockers relax vascular smooth muscle, leading to vasodilation and reduced blood pressure.","kind":"mechanism","origin":"ai"},{"id":"adrenergic-antagonists-blockers~ai-2","moduleId":"adrenergic-antagonists-blockers","stem":"A patient with chronic heart failure is started on a β-blocker. What is the most important consideration in this scenario?","options":[{"id":"a","text":"Start at a high dose"},{"id":"b","text":"Avoid β-blockers altogether"},{"id":"c","text":"Monitor for acute decompensation"},{"id":"d","text":"Taper off immediately if symptoms worsen"}],"answerId":"c","explanation":"In chronic heart failure, β-blockers should be started at a low dose and titrated up, with careful monitoring for any signs of acute decompensation.","kind":"trap","origin":"ai"},{"id":"adrenergic-antagonists-blockers~ai-3","moduleId":"adrenergic-antagonists-blockers","stem":"What is the risk of administering a β-blocker without prior α-blockade in a patient with pheochromocytoma?","options":[{"id":"a","text":"Bradycardia"},{"id":"b","text":"Hypertensive crisis"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Orthostatic hypotension"}],"answerId":"b","explanation":"Administering a β-blocker alone can lead to unopposed α-adrenergic vasoconstriction, resulting in a hypertensive crisis.","kind":"clinical","origin":"ai"},{"id":"adrenergic-antagonists-blockers~ai-4","moduleId":"adrenergic-antagonists-blockers","stem":"Which β-blocker is considered cardioselective and preferred for patients with asthma?","options":[{"id":"a","text":"Propranolol"},{"id":"b","text":"Atenolol"},{"id":"c","text":"Carvedilol"},{"id":"d","text":"Labetalol"}],"answerId":"b","explanation":"Atenolol is a cardioselective β-blocker that is safer for patients with asthma compared to non-selective β-blockers.","kind":"recall","origin":"ai"},{"id":"adrenergic-antagonists-blockers~ai-5","moduleId":"adrenergic-antagonists-blockers","stem":"How does the mechanism of β-blockers relate to receptor signal transduction?","options":[{"id":"a","text":"They enhance cAMP signaling"},{"id":"b","text":"They block adrenergic receptor activation"},{"id":"c","text":"They increase intracellular calcium"},{"id":"d","text":"They promote vasoconstriction"}],"answerId":"b","explanation":"β-blockers inhibit adrenergic receptor activation, thus blocking the signaling pathways that would normally increase heart rate and contractility.","kind":"integration","linkedModuleIds":["drug-receptor-signal-transduction"],"origin":"ai"},{"id":"adrenergic-antagonists-blockers~ai-6","moduleId":"adrenergic-antagonists-blockers","stem":"In the context of the autonomic nervous system, what is the effect of α1-blockers on blood pressure?","options":[{"id":"a","text":"Increase blood pressure"},{"id":"b","text":"No effect on blood pressure"},{"id":"c","text":"Decrease blood pressure"},{"id":"d","text":"Variable effect depending on dosage"}],"answerId":"c","explanation":"α1-blockers decrease blood pressure by causing vasodilation of vascular smooth muscle.","kind":"integration","linkedModuleIds":["autonomic-nervous-system"],"origin":"ai"}],"drug-absorption-routes":[{"id":"drug-absorption-routes~ai-0","moduleId":"drug-absorption-routes","stem":"What is the primary mechanism by which most drugs are absorbed across cell membranes?","options":[{"id":"a","text":"Active transport"},{"id":"b","text":"Facilitated diffusion"},{"id":"c","text":"Passive diffusion of the un-ionised form"},{"id":"d","text":"Endocytosis"}],"answerId":"c","explanation":"Most drugs cross membranes primarily through passive diffusion of their un-ionised, lipid-soluble form.","kind":"mechanism","origin":"ai"},{"id":"drug-absorption-routes~ai-1","moduleId":"drug-absorption-routes","stem":"Which route of administration guarantees 100% bioavailability?","options":[{"id":"a","text":"Oral"},{"id":"b","text":"Intravenous"},{"id":"c","text":"Sublingual"},{"id":"d","text":"Intramuscular"}],"answerId":"b","explanation":"Intravenous administration provides 100% bioavailability as it bypasses absorption barriers.","kind":"recall","origin":"ai"},{"id":"drug-absorption-routes~ai-2","moduleId":"drug-absorption-routes","stem":"A patient is prescribed a medication that is well absorbed from the gut. What is a potential concern regarding its oral bioavailability?","options":[{"id":"a","text":"It will be 100% bioavailable"},{"id":"b","text":"It may have low bioavailability due to first-pass metabolism"},{"id":"c","text":"It will not be absorbed at all"},{"id":"d","text":"It will only be effective if taken with food"}],"answerId":"b","explanation":"Good gut absorption does not guarantee high bioavailability if the drug undergoes extensive first-pass metabolism.","kind":"trap","origin":"ai"},{"id":"drug-absorption-routes~ai-3","moduleId":"drug-absorption-routes","stem":"Why is aspirin effectively absorbed in the stomach?","options":[{"id":"a","text":"It is a strong base"},{"id":"b","text":"It is a weak acid that remains un-ionised in acidic pH"},{"id":"c","text":"It is administered intravenously"},{"id":"d","text":"It is rapidly metabolized in the liver"}],"answerId":"b","explanation":"Aspirin is a weak acid that remains un-ionised in the acidic gastric environment, facilitating absorption.","kind":"recall","origin":"ai"},{"id":"drug-absorption-routes~ai-4","moduleId":"drug-absorption-routes","stem":"What effect does taking tetracyclines with milk have on absorption?","options":[{"id":"a","text":"Increases absorption"},{"id":"b","text":"Decreases absorption due to chelation"},{"id":"c","text":"No effect on absorption"},{"id":"d","text":"Enhances first-pass metabolism"}],"answerId":"b","explanation":"Milk contains cations that chelate tetracyclines, decreasing their absorption.","kind":"recall","origin":"ai"},{"id":"drug-absorption-routes~ai-5","moduleId":"drug-absorption-routes","stem":"How does the bioavailability of a drug administered sublingually compare to that of the same drug taken orally?","options":[{"id":"a","text":"Higher due to bypassing first-pass metabolism"},{"id":"b","text":"Lower due to first-pass metabolism"},{"id":"c","text":"The same as oral"},{"id":"d","text":"Depends on the drug's formulation"}],"answerId":"a","explanation":"Sublingual administration bypasses hepatic first-pass metabolism, leading to higher bioavailability compared to oral administration.","kind":"integration","linkedModuleIds":["drug-development-bioequivalence"],"origin":"ai"},{"id":"drug-absorption-routes~ai-6","moduleId":"drug-absorption-routes","stem":"Which factor does NOT affect the bioavailability of a drug?","options":[{"id":"a","text":"Route of administration"},{"id":"b","text":"First-pass metabolism"},{"id":"c","text":"Drug formulation"},{"id":"d","text":"Patient's age"}],"answerId":"d","explanation":"While route, first-pass metabolism, and formulation affect bioavailability, a patient's age does not directly influence it.","kind":"trap","origin":"ai"},{"id":"drug-absorption-routes~ai-7","moduleId":"drug-absorption-routes","stem":"How does the pharmacokinetic profile of a drug influence its dosing regimen?","options":[{"id":"a","text":"Only the route of administration matters"},{"id":"b","text":"Bioavailability affects dose adjustments between routes"},{"id":"c","text":"Metabolism is irrelevant to dosing"},{"id":"d","text":"Absorption is constant across all patients"}],"answerId":"b","explanation":"Bioavailability impacts how doses are adjusted when switching between different routes of administration.","kind":"integration","linkedModuleIds":["pharmacokinetics-adme"],"origin":"ai"}],"drug-receptor-signal-transduction":[{"id":"drug-receptor-signal-transduction~ai-0","moduleId":"drug-receptor-signal-transduction","stem":"What is the primary mechanism by which β-agonists increase intracellular cAMP levels?","options":[{"id":"a","text":"Activation of phospholipase C"},{"id":"b","text":"Inhibition of adenylyl cyclase"},{"id":"c","text":"Stimulation of adenylyl cyclase"},{"id":"d","text":"Direct activation of protein kinase A"}],"answerId":"c","explanation":"β-agonists activate Gs-coupled GPCRs, which stimulate adenylyl cyclase to increase cAMP levels.","kind":"mechanism","origin":"ai"},{"id":"drug-receptor-signal-transduction~ai-1","moduleId":"drug-receptor-signal-transduction","stem":"Which of the following best describes the effect of chronic antagonist use on receptor sensitivity?","options":[{"id":"a","text":"Receptor down-regulation leads to increased sensitivity"},{"id":"b","text":"Receptor up-regulation leads to decreased sensitivity"},{"id":"c","text":"Chronic antagonist use has no effect on receptor sensitivity"},{"id":"d","text":"Receptor up-regulation leads to increased sensitivity upon withdrawal"}],"answerId":"d","explanation":"Chronic antagonist use causes receptor up-regulation, resulting in increased sensitivity (supersensitivity) upon withdrawal.","kind":"trap","origin":"ai"},{"id":"drug-receptor-signal-transduction~ai-2","moduleId":"drug-receptor-signal-transduction","stem":"What is the expected time frame for the action of glucocorticoids due to their mechanism of action?","options":[{"id":"a","text":"Milliseconds"},{"id":"b","text":"Seconds"},{"id":"c","text":"Minutes"},{"id":"d","text":"Hours"}],"answerId":"d","explanation":"Glucocorticoids act through nuclear receptors, which require time for gene transcription, typically resulting in effects that manifest over hours.","kind":"recall","origin":"ai"},{"id":"drug-receptor-signal-transduction~ai-3","moduleId":"drug-receptor-signal-transduction","stem":"What physiological response is associated with Gq-coupled GPCR activation?","options":[{"id":"a","text":"Increased cAMP levels"},{"id":"b","text":"Increased intracellular calcium"},{"id":"c","text":"Decreased cAMP levels"},{"id":"d","text":"Increased nitric oxide production"}],"answerId":"b","explanation":"Gq-coupled GPCRs activate phospholipase C, leading to increased intracellular calcium through IP3 signaling.","kind":"mechanism","origin":"ai"},{"id":"drug-receptor-signal-transduction~ai-4","moduleId":"drug-receptor-signal-transduction","stem":"A patient experiences rebound hypertension after discontinuing a β-blocker. What is the underlying mechanism?","options":[{"id":"a","text":"Receptor down-regulation"},{"id":"b","text":"Receptor desensitization"},{"id":"c","text":"Receptor up-regulation"},{"id":"d","text":"Increased sympathetic outflow"}],"answerId":"c","explanation":"Rebound hypertension occurs due to receptor up-regulation during chronic β-blocker therapy, leading to increased sensitivity upon abrupt withdrawal.","kind":"clinical","origin":"ai"},{"id":"drug-receptor-signal-transduction~ai-5","moduleId":"drug-receptor-signal-transduction","stem":"How does the mechanism of action of glucocorticoids differ from that of β-agonists?","options":[{"id":"a","text":"Both act via GPCRs"},{"id":"b","text":"Glucocorticoids act through nuclear receptors"},{"id":"c","text":"β-agonists act through ion channels"},{"id":"d","text":"Both have immediate effects"}],"answerId":"b","explanation":"Glucocorticoids act through nuclear receptors, leading to delayed effects, while β-agonists act via GPCRs for rapid responses.","kind":"integration","linkedModuleIds":["pharmacodynamics-receptors-dose-response"],"origin":"ai"},{"id":"drug-receptor-signal-transduction~ai-6","moduleId":"drug-receptor-signal-transduction","stem":"Which receptor type is primarily involved in the mechanism of action of α1-agonists?","options":[{"id":"a","text":"Ionotropic receptors"},{"id":"b","text":"Nuclear receptors"},{"id":"c","text":"Gq-coupled receptors"},{"id":"d","text":"Gi-coupled receptors"}],"answerId":"c","explanation":"α1-agonists primarily activate Gq-coupled receptors, leading to phospholipase C activation and increased intracellular calcium.","kind":"recall","origin":"ai"}],"agonists-antagonists-pharmacology":[{"id":"agonists-antagonists-pharmacology~ai-0","moduleId":"agonists-antagonists-pharmacology","stem":"What type of drug produces a maximal response at a receptor?","options":[{"id":"a","text":"Full agonist"},{"id":"b","text":"Partial agonist"},{"id":"c","text":"Inverse agonist"},{"id":"d","text":"Antagonist"}],"answerId":"a","explanation":"A full agonist has high efficacy and produces the maximal response at a receptor.","kind":"recall","origin":"ai"},{"id":"agonists-antagonists-pharmacology~ai-1","moduleId":"agonists-antagonists-pharmacology","stem":"Which type of antagonist reduces the maximal effect of an agonist and cannot be overcome by increasing agonist concentration?","options":[{"id":"a","text":"Competitive antagonist"},{"id":"b","text":"Non-competitive antagonist"},{"id":"c","text":"Partial agonist"},{"id":"d","text":"Inverse agonist"}],"answerId":"b","explanation":"Non-competitive antagonists lower the maximum effect (Emax) of the agonist and cannot be surmounted by additional agonist.","kind":"mechanism","origin":"ai"},{"id":"agonists-antagonists-pharmacology~ai-2","moduleId":"agonists-antagonists-pharmacology","stem":"A patient is taking a full agonist for pain relief. What effect would adding a partial agonist have?","options":[{"id":"a","text":"Increase pain relief"},{"id":"b","text":"No effect on pain relief"},{"id":"c","text":"Decrease pain relief"},{"id":"d","text":"Increase side effects"}],"answerId":"c","explanation":"A partial agonist competes with the full agonist and reduces the overall effect, acting as a partial antagonist.","kind":"trap","origin":"ai"},{"id":"agonists-antagonists-pharmacology~ai-3","moduleId":"agonists-antagonists-pharmacology","stem":"What is the mechanism of action of an inverse agonist?","options":[{"id":"a","text":"Increases receptor activity"},{"id":"b","text":"Decreases receptor activity below baseline"},{"id":"c","text":"Blocks receptor activity"},{"id":"d","text":"Has no effect on receptor activity"}],"answerId":"b","explanation":"An inverse agonist binds to a constitutively active receptor and reduces its activity below the baseline level.","kind":"mechanism","origin":"ai"},{"id":"agonists-antagonists-pharmacology~ai-4","moduleId":"agonists-antagonists-pharmacology","stem":"What clinical finding indicates tachyphylaxis?","options":[{"id":"a","text":"Increased receptor sensitivity"},{"id":"b","text":"Rapidly declining response with repeated dosing"},{"id":"c","text":"Enhanced drug efficacy over time"},{"id":"d","text":"Sustained maximal response"}],"answerId":"b","explanation":"Tachyphylaxis is characterized by a rapid decrease in response to a drug after repeated doses.","kind":"recall","origin":"ai"},{"id":"agonists-antagonists-pharmacology~ai-5","moduleId":"agonists-antagonists-pharmacology","stem":"How does a competitive antagonist affect the dose-response curve of an agonist?","options":[{"id":"a","text":"Shifts left with increased efficacy"},{"id":"b","text":"Shifts right with preserved efficacy"},{"id":"c","text":"Shifts down with decreased efficacy"},{"id":"d","text":"No shift in the curve"}],"answerId":"b","explanation":"A competitive antagonist shifts the agonist dose-response curve to the right, indicating that higher concentrations of agonist are needed to achieve the same effect.","kind":"mechanism","origin":"ai"},{"id":"agonists-antagonists-pharmacology~ai-6","moduleId":"agonists-antagonists-pharmacology","stem":"In the context of receptor pharmacology, how does the concept of spare receptors relate to partial agonists?","options":[{"id":"a","text":"Partial agonists always activate spare receptors"},{"id":"b","text":"Spare receptors allow partial agonists to achieve maximal effects"},{"id":"c","text":"Partial agonists can reduce the effect of full agonists due to spare receptors"},{"id":"d","text":"Spare receptors are irrelevant to partial agonists"}],"answerId":"c","explanation":"Spare receptors can allow partial agonists to exert effects, but when a full agonist is present, the partial agonist can reduce the overall response.","kind":"integration","linkedModuleIds":["pharmacodynamics-receptors-dose-response"],"origin":"ai"},{"id":"agonists-antagonists-pharmacology~ai-7","moduleId":"agonists-antagonists-pharmacology","stem":"How might the pharmacological effects of dopamine agonists relate to the mechanisms of agonists and antagonists?","options":[{"id":"a","text":"Dopamine agonists are always full agonists"},{"id":"b","text":"Dopamine agonists can act as partial agonists"},{"id":"c","text":"Dopamine agonists have no relation to antagonists"},{"id":"d","text":"Dopamine agonists only function in the absence of antagonists"}],"answerId":"b","explanation":"Dopamine agonists can exhibit partial agonist properties, influencing their efficacy in the presence of other drugs.","kind":"integration","linkedModuleIds":["dopamine-agonists-antimuscarinics"],"origin":"ai"}],"antimuscarinic-anticholinergic-drugs":[{"id":"antimuscarinic-anticholinergic-drugs~ai-0","moduleId":"antimuscarinic-anticholinergic-drugs","stem":"What is the primary mechanism of action of antimuscarinic drugs?","options":[{"id":"a","text":"Block adrenergic receptors"},{"id":"b","text":"Inhibit acetylcholinesterase"},{"id":"c","text":"Block muscarinic receptors"},{"id":"d","text":"Stimulate nicotinic receptors"}],"answerId":"c","explanation":"Antimuscarinic drugs primarily block muscarinic receptors, opposing parasympathetic effects.","kind":"mechanism","origin":"ai"},{"id":"antimuscarinic-anticholinergic-drugs~ai-1","moduleId":"antimuscarinic-anticholinergic-drugs","stem":"Which of the following is a classic sign of anticholinergic toxicity?","options":[{"id":"a","text":"Bradycardia"},{"id":"b","text":"Miosis"},{"id":"c","text":"Urinary retention"},{"id":"d","text":"Increased salivation"}],"answerId":"c","explanation":"Urinary retention is a classic sign of anticholinergic toxicity due to reduced detrusor activity.","kind":"recall","origin":"ai"},{"id":"antimuscarinic-anticholinergic-drugs~ai-2","moduleId":"antimuscarinic-anticholinergic-drugs","stem":"A 70-year-old man with BPH is prescribed an antimuscarinic for overactive bladder. What complication should be monitored?","options":[{"id":"a","text":"Hypotension"},{"id":"b","text":"Urinary retention"},{"id":"c","text":"Bradycardia"},{"id":"d","text":"Diarrhea"}],"answerId":"b","explanation":"Antimuscarinics can precipitate urinary retention, especially in patients with bladder outlet obstruction like BPH.","kind":"clinical","origin":"ai"},{"id":"antimuscarinic-anticholinergic-drugs~ai-3","moduleId":"antimuscarinic-anticholinergic-drugs","stem":"Which antimuscarinic is used as an antidote for organophosphate poisoning?","options":[{"id":"a","text":"Ipratropium"},{"id":"b","text":"Scopolamine"},{"id":"c","text":"Atropine"},{"id":"d","text":"Benztropine"}],"answerId":"c","explanation":"Atropine is used as an antidote for organophosphate poisoning due to its ability to block excessive acetylcholine.","kind":"recall","origin":"ai"},{"id":"antimuscarinic-anticholinergic-drugs~ai-4","moduleId":"antimuscarinic-anticholinergic-drugs","stem":"What is a significant risk of prescribing antimuscarinics to elderly patients?","options":[{"id":"a","text":"Increased sweating"},{"id":"b","text":"Acute angle-closure glaucoma"},{"id":"c","text":"Enhanced cognitive function"},{"id":"d","text":"Decreased heart rate"}],"answerId":"b","explanation":"Antimuscarinics can cause mydriasis, which may precipitate acute angle-closure glaucoma in elderly patients.","kind":"trap","origin":"ai"},{"id":"antimuscarinic-anticholinergic-drugs~ai-5","moduleId":"antimuscarinic-anticholinergic-drugs","stem":"A patient presents with the anticholinergic toxidrome. Which of the following findings would you expect?","options":[{"id":"a","text":"Bradycardia and miosis"},{"id":"b","text":"Hot, dry skin and mydriasis"},{"id":"c","text":"Diarrhea and salivation"},{"id":"d","text":"Hypotension and confusion"}],"answerId":"b","explanation":"The anticholinergic toxidrome is characterized by hot, dry skin and mydriasis, among other symptoms.","kind":"recall","origin":"ai"},{"id":"antimuscarinic-anticholinergic-drugs~ai-6","moduleId":"antimuscarinic-anticholinergic-drugs","stem":"How do antimuscarinics relate to the treatment of urinary incontinence?","options":[{"id":"a","text":"They increase detrusor activity"},{"id":"b","text":"They block muscarinic receptors to reduce bladder contractions"},{"id":"c","text":"They enhance cholinergic activity"},{"id":"d","text":"They are contraindicated in all urinary conditions"}],"answerId":"b","explanation":"Antimuscarinics block muscarinic receptors, thereby reducing involuntary bladder contractions and treating urinary incontinence.","kind":"integration","linkedModuleIds":["urinary-incontinence-drugs"],"origin":"ai"},{"id":"antimuscarinic-anticholinergic-drugs~ai-7","moduleId":"antimuscarinic-anticholinergic-drugs","stem":"Which of the following best describes the relationship between antimuscarinics and the autonomic nervous system?","options":[{"id":"a","text":"They stimulate parasympathetic activity"},{"id":"b","text":"They block sympathetic receptors"},{"id":"c","text":"They inhibit parasympathetic effects"},{"id":"d","text":"They enhance adrenergic signaling"}],"answerId":"c","explanation":"Antimuscarinics inhibit parasympathetic effects by blocking muscarinic receptors, thus opposing the autonomic nervous system's parasympathetic tone.","kind":"integration","linkedModuleIds":["autonomic-nervous-system"],"origin":"ai"}],"herpesvirus-cmv-antivirals":[{"id":"herpesvirus-cmv-antivirals~ai-0","moduleId":"herpesvirus-cmv-antivirals","stem":"What is the mechanism of action of aciclovir?","options":[{"id":"a","text":"Inhibition of viral RNA polymerase"},{"id":"b","text":"Chain termination of viral DNA polymerase"},{"id":"c","text":"Inhibition of viral protein synthesis"},{"id":"d","text":"Blocking viral entry into host cells"}],"answerId":"b","explanation":"Aciclovir is a guanosine analogue that acts as a chain terminator of viral DNA polymerase after being phosphorylated by viral thymidine kinase.","kind":"mechanism","origin":"ai"},{"id":"herpesvirus-cmv-antivirals~ai-1","moduleId":"herpesvirus-cmv-antivirals","stem":"Which antiviral is the first-line treatment for HSV encephalitis?","options":[{"id":"a","text":"Ganciclovir"},{"id":"b","text":"Foscarnet"},{"id":"c","text":"Aciclovir"},{"id":"d","text":"Cidofovir"}],"answerId":"c","explanation":"Aciclovir is the first-line treatment for HSV encephalitis and should be administered early as it is a neurological emergency.","kind":"recall","origin":"ai"},{"id":"herpesvirus-cmv-antivirals~ai-2","moduleId":"herpesvirus-cmv-antivirals","stem":"What is the dose-limiting toxicity of ganciclovir?","options":[{"id":"a","text":"Nephrotoxicity"},{"id":"b","text":"Neutropenia"},{"id":"c","text":"Hepatotoxicity"},{"id":"d","text":"Cardiotoxicity"}],"answerId":"b","explanation":"Ganciclovir is known to cause dose-limiting toxicity in the form of bone marrow suppression, leading to neutropenia.","kind":"recall","origin":"ai"},{"id":"herpesvirus-cmv-antivirals~ai-3","moduleId":"herpesvirus-cmv-antivirals","stem":"Which of the following is a direct DNA polymerase inhibitor used for resistant herpesvirus infections?","options":[{"id":"a","text":"Aciclovir"},{"id":"b","text":"Ganciclovir"},{"id":"c","text":"Foscarnet"},{"id":"d","text":"Valaciclovir"}],"answerId":"c","explanation":"Foscarnet is a direct DNA polymerase inhibitor used for resistant herpesvirus infections, bypassing the need for phosphorylation.","kind":"recall","origin":"ai"},{"id":"herpesvirus-cmv-antivirals~ai-4","moduleId":"herpesvirus-cmv-antivirals","stem":"A patient with CMV retinitis develops neutropenia during treatment. Which drug is most likely responsible?","options":[{"id":"a","text":"Aciclovir"},{"id":"b","text":"Foscarnet"},{"id":"c","text":"Ganciclovir"},{"id":"d","text":"Cidofovir"}],"answerId":"c","explanation":"Ganciclovir is associated with bone marrow suppression, leading to neutropenia during treatment for CMV retinitis.","kind":"clinical","origin":"ai"},{"id":"herpesvirus-cmv-antivirals~ai-5","moduleId":"herpesvirus-cmv-antivirals","stem":"What is the consequence of inadequate hydration during aciclovir administration?","options":[{"id":"a","text":"Neutropenia"},{"id":"b","text":"Crystalluria and acute kidney injury"},{"id":"c","text":"Electrolyte imbalance"},{"id":"d","text":"Viral resistance"}],"answerId":"b","explanation":"Inadequate hydration during aciclovir administration can lead to crystalluria and acute kidney injury due to nephrotoxicity.","kind":"trap","origin":"ai"},{"id":"herpesvirus-cmv-antivirals~ai-6","moduleId":"herpesvirus-cmv-antivirals","stem":"How does the mechanism of action of aciclovir relate to transcription processes in cells?","options":[{"id":"a","text":"It inhibits transcription factors"},{"id":"b","text":"It interferes with mRNA splicing"},{"id":"c","text":"It mimics nucleotides used in DNA synthesis"},{"id":"d","text":"It blocks RNA polymerase activity"}],"answerId":"c","explanation":"Aciclovir mimics guanosine, a nucleotide used in DNA synthesis, which is crucial for the transcription process in viral replication.","kind":"integration","linkedModuleIds":["transcription-mechanism"],"origin":"ai"},{"id":"herpesvirus-cmv-antivirals~ai-7","moduleId":"herpesvirus-cmv-antivirals","stem":"Which antiviral treatment is most appropriate for a patient with resistant HSV infection?","options":[{"id":"a","text":"Increase aciclovir dosage"},{"id":"b","text":"Switch to ganciclovir"},{"id":"c","text":"Use foscarnet"},{"id":"d","text":"Use valaciclovir"}],"answerId":"c","explanation":"For aciclovir-resistant HSV, foscarnet is the appropriate choice as it directly inhibits viral DNA polymerase without requiring activation.","kind":"integration","linkedModuleIds":["viral-skin-infections"],"origin":"ai"}],"antimycobacterial-drugs":[{"id":"antimycobacterial-drugs~ai-0","moduleId":"antimycobacterial-drugs","stem":"What is the primary mechanism of action of Isoniazid?","options":[{"id":"a","text":"Inhibits RNA polymerase"},{"id":"b","text":"Inhibits mycolic acid synthesis"},{"id":"c","text":"Inhibits protein synthesis"},{"id":"d","text":"Inhibits cell wall synthesis"}],"answerId":"b","explanation":"Isoniazid primarily inhibits the synthesis of mycolic acids, which are essential components of the mycobacterial cell wall.","kind":"mechanism","origin":"ai"},{"id":"antimycobacterial-drugs~ai-1","moduleId":"antimycobacterial-drugs","stem":"Which side effect is most commonly associated with Ethambutol?","options":[{"id":"a","text":"Hepatotoxicity"},{"id":"b","text":"Optic neuritis"},{"id":"c","text":"Peripheral neuropathy"},{"id":"d","text":"Hyperuricaemia"}],"answerId":"b","explanation":"Ethambutol is known to cause optic neuritis, which can lead to reduced color vision and acuity.","kind":"recall","origin":"ai"},{"id":"antimycobacterial-drugs~ai-2","moduleId":"antimycobacterial-drugs","stem":"Why is combination therapy essential in treating tuberculosis?","options":[{"id":"a","text":"To reduce cost of treatment"},{"id":"b","text":"To prevent drug interactions"},{"id":"c","text":"To prevent resistance development"},{"id":"d","text":"To shorten treatment duration"}],"answerId":"c","explanation":"Combination therapy is crucial to prevent the development of drug resistance due to the slow growth and intracellular hiding of M. tuberculosis.","kind":"trap","origin":"ai"},{"id":"antimycobacterial-drugs~ai-3","moduleId":"antimycobacterial-drugs","stem":"What is a common clinical finding in a patient taking Rifampin?","options":[{"id":"a","text":"Gout flare"},{"id":"b","text":"Orange urine"},{"id":"c","text":"Peripheral neuropathy"},{"id":"d","text":"Optic neuritis"}],"answerId":"b","explanation":"Rifampin is known to cause orange discoloration of urine and tears due to its effects on bodily secretions.","kind":"recall","origin":"ai"},{"id":"antimycobacterial-drugs~ai-4","moduleId":"antimycobacterial-drugs","stem":"Which drug is associated with hyperuricaemia during tuberculosis treatment?","options":[{"id":"a","text":"Isoniazid"},{"id":"b","text":"Rifampin"},{"id":"c","text":"Ethambutol"},{"id":"d","text":"Pyrazinamide"}],"answerId":"d","explanation":"Pyrazinamide can cause hyperuricaemia, leading to gout flares in susceptible individuals.","kind":"recall","origin":"ai"},{"id":"antimycobacterial-drugs~ai-5","moduleId":"antimycobacterial-drugs","stem":"What is the risk of starting anti-TNF therapy in a patient with latent tuberculosis?","options":[{"id":"a","text":"Increased hepatotoxicity"},{"id":"b","text":"Increased risk of optic neuritis"},{"id":"c","text":"Reactivation of latent TB"},{"id":"d","text":"Increased peripheral neuropathy"}],"answerId":"c","explanation":"Anti-TNF therapy can reactivate latent tuberculosis, necessitating screening and treatment before initiation.","kind":"integration","linkedModuleIds":["immunomodulating-agents"],"origin":"ai"},{"id":"antimycobacterial-drugs~ai-6","moduleId":"antimycobacterial-drugs","stem":"How does Rifampin interact with other medications?","options":[{"id":"a","text":"Inhibits CYP450 enzymes"},{"id":"b","text":"Induces CYP450 enzymes"},{"id":"c","text":"Inhibits renal excretion"},{"id":"d","text":"Increases absorption of other drugs"}],"answerId":"b","explanation":"Rifampin is a potent inducer of CYP450 enzymes, leading to increased metabolism of many drugs and potential therapeutic failures.","kind":"integration","linkedModuleIds":["drug-interactions-mechanisms"],"origin":"ai"}],"drug-metabolism-cyp450":[{"id":"drug-metabolism-cyp450~ai-0","moduleId":"drug-metabolism-cyp450","stem":"Which phase of drug metabolism primarily involves the cytochrome P450 enzymes?","options":[{"id":"a","text":"Phase I"},{"id":"b","text":"Phase II"},{"id":"c","text":"Phase III"},{"id":"d","text":"Phase IV"}],"answerId":"a","explanation":"Phase I metabolism primarily involves the cytochrome P450 enzymes, which perform oxidation, reduction, and hydrolysis.","kind":"recall","origin":"ai"},{"id":"drug-metabolism-cyp450~ai-1","moduleId":"drug-metabolism-cyp450","stem":"What is the consequence of a CYP450 inhibitor on a prodrug like codeine?","options":[{"id":"a","text":"Increased morphine levels"},{"id":"b","text":"Decreased morphine levels"},{"id":"c","text":"No effect on morphine levels"},{"id":"d","text":"Increased codeine levels"}],"answerId":"b","explanation":"A CYP450 inhibitor decreases the metabolism of codeine to morphine, leading to decreased morphine levels and effect.","kind":"trap","origin":"ai"},{"id":"drug-metabolism-cyp450~ai-2","moduleId":"drug-metabolism-cyp450","stem":"What is the primary mechanism by which paracetamol causes hepatotoxicity in overdose?","options":[{"id":"a","text":"Inhibition of CYP450"},{"id":"b","text":"Depletion of glutathione"},{"id":"c","text":"Phase II conjugation failure"},{"id":"d","text":"Increased renal excretion"}],"answerId":"b","explanation":"In paracetamol overdose, the toxic metabolite NAPQI accumulates after glutathione is depleted, leading to hepatotoxicity.","kind":"mechanism","origin":"ai"},{"id":"drug-metabolism-cyp450~ai-3","moduleId":"drug-metabolism-cyp450","stem":"A patient develops hepatotoxicity after taking paracetamol. What is the likely mechanism?","options":[{"id":"a","text":"Phase I metabolism"},{"id":"b","text":"Phase II conjugation"},{"id":"c","text":"Toxic metabolite accumulation"},{"id":"d","text":"CYP450 induction"}],"answerId":"c","explanation":"The hepatotoxicity is due to the accumulation of the toxic metabolite NAPQI, which occurs when glutathione is depleted.","kind":"clinical","origin":"ai"},{"id":"drug-metabolism-cyp450~ai-4","moduleId":"drug-metabolism-cyp450","stem":"What effect does rifampin have on drug metabolism over time?","options":[{"id":"a","text":"Immediate increase in drug levels"},{"id":"b","text":"Delayed decrease in drug levels"},{"id":"c","text":"No effect on drug levels"},{"id":"d","text":"Immediate decrease in drug levels"}],"answerId":"b","explanation":"Rifampin acts as a CYP450 inducer, leading to a delayed decrease in drug levels as enzyme synthesis increases over days.","kind":"recall","origin":"ai"},{"id":"drug-metabolism-cyp450~ai-5","moduleId":"drug-metabolism-cyp450","stem":"How does pharmacogenomics influence drug metabolism?","options":[{"id":"a","text":"By altering drug absorption"},{"id":"b","text":"By modifying enzyme activity"},{"id":"c","text":"By changing drug excretion"},{"id":"d","text":"By affecting drug distribution"}],"answerId":"b","explanation":"Pharmacogenomics can modify enzyme activity, affecting how individuals metabolize drugs based on genetic variations.","kind":"integration","linkedModuleIds":["pharmacogenomics"],"origin":"ai"},{"id":"drug-metabolism-cyp450~ai-6","moduleId":"drug-metabolism-cyp450","stem":"Which drug interaction mechanism is primarily influenced by CYP450 enzymes?","options":[{"id":"a","text":"Absorption variations"},{"id":"b","text":"Metabolic pathways"},{"id":"c","text":"Excretion rates"},{"id":"d","text":"Distribution changes"}],"answerId":"b","explanation":"CYP450 enzymes are crucial in metabolic pathways, affecting how drugs are processed in the body.","kind":"integration","linkedModuleIds":["drug-interactions-mechanisms"],"origin":"ai"}],"antibacterial-resistance-mechanisms":[{"id":"antibacterial-resistance-mechanisms~ai-0","moduleId":"antibacterial-resistance-mechanisms","stem":"What is the primary mechanism by which MRSA exhibits resistance to β-lactam antibiotics?","options":[{"id":"a","text":"Enzymatic inactivation by β-lactamase"},{"id":"b","text":"Altered PBP2a"},{"id":"c","text":"Reduced uptake"},{"id":"d","text":"Efflux pumps"}],"answerId":"b","explanation":"MRSA's resistance to β-lactams is primarily due to the alteration of penicillin-binding protein 2a (PBP2a), which prevents β-lactam binding.","kind":"recall","origin":"ai"},{"id":"antibacterial-resistance-mechanisms~ai-1","moduleId":"antibacterial-resistance-mechanisms","stem":"Which mechanism allows bacteria to rapidly share antibiotic resistance genes?","options":[{"id":"a","text":"Spontaneous mutation"},{"id":"b","text":"Horizontal gene transfer"},{"id":"c","text":"Natural selection"},{"id":"d","text":"Antimicrobial stewardship"}],"answerId":"b","explanation":"Horizontal gene transfer enables bacteria to share resistance genes through plasmids and transposons, facilitating rapid dissemination of resistance.","kind":"recall","origin":"ai"},{"id":"antibacterial-resistance-mechanisms~ai-2","moduleId":"antibacterial-resistance-mechanisms","stem":"A patient presents with a severe infection caused by a Gram-negative bacterium that produces ESBL. Which antibiotic class is most likely ineffective?","options":[{"id":"a","text":"Carbapenems"},{"id":"b","text":"Aminoglycosides"},{"id":"c","text":"Cephalosporins"},{"id":"d","text":"Tetracyclines"}],"answerId":"c","explanation":"Extended-spectrum β-lactamases (ESBLs) confer resistance primarily to cephalosporins, making them ineffective for treating infections caused by ESBL-producing organisms.","kind":"clinical","origin":"ai"},{"id":"antibacterial-resistance-mechanisms~ai-3","moduleId":"antibacterial-resistance-mechanisms","stem":"Which of the following strategies is NOT part of antimicrobial stewardship?","options":[{"id":"a","text":"Prescribing the narrowest effective agent"},{"id":"b","text":"De-escalating therapy once cultures return"},{"id":"c","text":"Using broad-spectrum antibiotics as first-line therapy"},{"id":"d","text":"Controlling infection through hygiene"}],"answerId":"c","explanation":"Using broad-spectrum antibiotics as first-line therapy is contrary to the principles of antimicrobial stewardship, which emphasizes targeted therapy.","kind":"trap","origin":"ai"},{"id":"antibacterial-resistance-mechanisms~ai-4","moduleId":"antibacterial-resistance-mechanisms","stem":"How do β-lactamases contribute to antibiotic resistance?","options":[{"id":"a","text":"By altering drug targets"},{"id":"b","text":"By hydrolyzing β-lactam antibiotics"},{"id":"c","text":"By reducing drug uptake"},{"id":"d","text":"By pumping out the drug"}],"answerId":"b","explanation":"β-lactamases are enzymes that hydrolyze β-lactam antibiotics, rendering them ineffective against bacteria that produce these enzymes.","kind":"mechanism","origin":"ai"},{"id":"antibacterial-resistance-mechanisms~ai-5","moduleId":"antibacterial-resistance-mechanisms","stem":"Which of the following best describes the role of antimicrobial stewardship in combating antibiotic resistance?","options":[{"id":"a","text":"It solely focuses on developing new antibiotics"},{"id":"b","text":"It aims to reduce the use of antibiotics in all patients"},{"id":"c","text":"It promotes the appropriate use of antibiotics to minimize resistance"},{"id":"d","text":"It encourages the use of broad-spectrum antibiotics"}],"answerId":"c","explanation":"Antimicrobial stewardship promotes the appropriate use of antibiotics, including prescribing only when necessary and selecting the narrowest effective agent to minimize resistance.","kind":"clinical","origin":"ai"},{"id":"antibacterial-resistance-mechanisms~ai-6","moduleId":"antibacterial-resistance-mechanisms","stem":"Which of the following antibiotics is most likely to be ineffective against a vancomycin-resistant Enterococcus (VRE) infection?","options":[{"id":"a","text":"Daptomycin"},{"id":"b","text":"Linezolid"},{"id":"c","text":"Ampicillin"},{"id":"d","text":"Vancomycin"}],"answerId":"d","explanation":"Vancomycin is ineffective against VRE due to the alteration of the target site, making it resistant to this antibiotic.","kind":"integration","linkedModuleIds":["antibacterial-cell-wall-agents"],"origin":"ai"},{"id":"antibacterial-resistance-mechanisms~ai-7","moduleId":"antibacterial-resistance-mechanisms","stem":"In the context of protein synthesis inhibitors, which mechanism of resistance is commonly seen in bacteria?","options":[{"id":"a","text":"Alteration of ribosomal RNA"},{"id":"b","text":"Inactivation by β-lactamase"},{"id":"c","text":"Efflux pumps"},{"id":"d","text":"Decreased permeability"}],"answerId":"a","explanation":"Bacteria can develop resistance to protein synthesis inhibitors by altering ribosomal RNA, which affects drug binding.","kind":"integration","linkedModuleIds":["antibacterial-protein-synthesis-inhibitors"],"origin":"ai"}],"superficial-antifungals-clinical":[{"id":"superficial-antifungals-clinical~ai-0","moduleId":"superficial-antifungals-clinical","stem":"What is the oral drug of choice for dermatophyte onychomycosis?","options":[{"id":"a","text":"Griseofulvin"},{"id":"b","text":"Fluconazole"},{"id":"c","text":"Terbinafine"},{"id":"d","text":"Itraconazole"}],"answerId":"c","explanation":"Terbinafine is the preferred oral agent for treating dermatophyte nail infections due to its efficacy and keratin affinity.","kind":"recall","origin":"ai"},{"id":"superficial-antifungals-clinical~ai-1","moduleId":"superficial-antifungals-clinical","stem":"Which mechanism does terbinafine use to inhibit fungal growth?","options":[{"id":"a","text":"Inhibits beta-glucan synthesis"},{"id":"b","text":"Disrupts microtubules"},{"id":"c","text":"Inhibits squalene epoxidase"},{"id":"d","text":"Inhibits ergosterol synthesis"}],"answerId":"c","explanation":"Terbinafine inhibits squalene epoxidase, leading to a decrease in ergosterol synthesis, which is essential for fungal cell membrane integrity.","kind":"mechanism","origin":"ai"},{"id":"superficial-antifungals-clinical~ai-2","moduleId":"superficial-antifungals-clinical","stem":"What is the recommended treatment for tinea capitis in children?","options":[{"id":"a","text":"Topical ketoconazole"},{"id":"b","text":"Oral griseofulvin"},{"id":"c","text":"Topical terbinafine"},{"id":"d","text":"Oral fluconazole"}],"answerId":"b","explanation":"Griseofulvin is the first-line oral treatment for tinea capitis, especially in pediatric patients.","kind":"recall","origin":"ai"},{"id":"superficial-antifungals-clinical~ai-3","moduleId":"superficial-antifungals-clinical","stem":"Which topical agent is used for cutaneous candidiasis?","options":[{"id":"a","text":"Clotrimazole"},{"id":"b","text":"Terbinafine"},{"id":"c","text":"Fluconazole"},{"id":"d","text":"Griseofulvin"}],"answerId":"a","explanation":"Clotrimazole is a topical azole effective against cutaneous candidiasis.","kind":"recall","origin":"ai"},{"id":"superficial-antifungals-clinical~ai-4","moduleId":"superficial-antifungals-clinical","stem":"What is a common side effect of prolonged oral antifungal therapy with terbinafine?","options":[{"id":"a","text":"Nephrotoxicity"},{"id":"b","text":"Hepatotoxicity"},{"id":"c","text":"Gastrointestinal bleeding"},{"id":"d","text":"Hypoglycemia"}],"answerId":"b","explanation":"Hepatotoxicity is a known risk associated with prolonged use of oral antifungals like terbinafine and azoles, necessitating monitoring.","kind":"recall","origin":"ai"},{"id":"superficial-antifungals-clinical~ai-5","moduleId":"superficial-antifungals-clinical","stem":"Which of the following statements is true regarding treatment of onychomycosis?","options":[{"id":"a","text":"Topical antifungals are effective for nail infections"},{"id":"b","text":"Oral terbinafine is ineffective for dermatophyte nails"},{"id":"c","text":"Nail infections require prolonged oral therapy"},{"id":"d","text":"Griseofulvin is the first choice for onychomycosis"}],"answerId":"c","explanation":"Nail infections like onychomycosis generally require prolonged oral therapy with terbinafine due to poor penetration of topical agents.","kind":"trap","origin":"ai"},{"id":"superficial-antifungals-clinical~ai-6","moduleId":"superficial-antifungals-clinical","stem":"Which of the following is a common clinical finding in pityriasis versicolor?","options":[{"id":"a","text":"Thickened nails"},{"id":"b","text":"Scaly dyspigmented macules"},{"id":"c","text":"Pustular lesions"},{"id":"d","text":"Erythematous plaques"}],"answerId":"b","explanation":"Pityriasis versicolor typically presents as scaly dyspigmented macules on the skin.","kind":"recall","origin":"ai"},{"id":"superficial-antifungals-clinical~ai-7","moduleId":"superficial-antifungals-clinical","stem":"How does the treatment of tinea capitis differ from that of localized tinea corporis?","options":[{"id":"a","text":"Both require oral antifungals"},{"id":"b","text":"Tinea capitis requires topical therapy"},{"id":"c","text":"Tinea corporis is treated with oral agents"},{"id":"d","text":"Tinea capitis requires oral therapy"}],"answerId":"d","explanation":"Tinea capitis requires oral therapy due to the involvement of hair follicles, while localized tinea corporis can often be treated topically.","kind":"integration","linkedModuleIds":["skin-infections-bacterial-fungal-viral"],"origin":"ai"},{"id":"superficial-antifungals-clinical~ai-8","moduleId":"superficial-antifungals-clinical","stem":"What is the primary mechanism of action for azole antifungals?","options":[{"id":"a","text":"Inhibit squalene epoxidase"},{"id":"b","text":"Inhibit ergosterol synthesis"},{"id":"c","text":"Disrupt microtubules"},{"id":"d","text":"Inhibit DNA synthesis"}],"answerId":"b","explanation":"Azole antifungals primarily inhibit ergosterol synthesis, which is crucial for fungal cell membrane integrity.","kind":"integration","linkedModuleIds":["antifungal-agents"],"origin":"ai"}],"anthelmintic-drug-classes":[{"id":"anthelmintic-drug-classes~ai-0","moduleId":"anthelmintic-drug-classes","stem":"Which anthelmintic drug acts by causing spastic paralysis in pinworms?","options":[{"id":"a","text":"Albendazole"},{"id":"b","text":"Ivermectin"},{"id":"c","text":"Pyrantel pamoate"},{"id":"d","text":"Praziquantel"}],"answerId":"c","explanation":"Pyrantel pamoate causes spastic paralysis through a depolarizing neuromuscular block.","kind":"recall","origin":"ai"},{"id":"anthelmintic-drug-classes~ai-1","moduleId":"anthelmintic-drug-classes","stem":"What is the mechanism of action of benzimidazoles like albendazole?","options":[{"id":"a","text":"Inhibit glucose uptake"},{"id":"b","text":"Block glutamate-gated Cl⁻ channels"},{"id":"c","text":"Increase intracellular calcium"},{"id":"d","text":"Induce spastic paralysis"}],"answerId":"a","explanation":"Benzimidazoles bind to β-tubulin, inhibiting glucose uptake and starving the worms.","kind":"mechanism","origin":"ai"},{"id":"anthelmintic-drug-classes~ai-2","moduleId":"anthelmintic-drug-classes","stem":"Which of the following is a key consideration when treating neurocysticercosis?","options":[{"id":"a","text":"Single dose of ivermectin"},{"id":"b","text":"Prolonged high-dose albendazole"},{"id":"c","text":"Avoid corticosteroids"},{"id":"d","text":"Use praziquantel only"}],"answerId":"b","explanation":"Neurocysticercosis requires prolonged high-dose albendazole, often with corticosteroids to manage inflammation.","kind":"clinical","origin":"ai"},{"id":"anthelmintic-drug-classes~ai-3","moduleId":"anthelmintic-drug-classes","stem":"What is the primary reason for using corticosteroids when treating neurocysticercosis?","options":[{"id":"a","text":"Enhance drug absorption"},{"id":"b","text":"Prevent inflammatory reactions"},{"id":"c","text":"Increase drug efficacy"},{"id":"d","text":"Reduce worm burden"}],"answerId":"b","explanation":"Corticosteroids are used to prevent inflammatory reactions to dying larvae during treatment.","kind":"mechanism","origin":"ai"},{"id":"anthelmintic-drug-classes~ai-4","moduleId":"anthelmintic-drug-classes","stem":"Which anthelmintic is contraindicated in the first trimester of pregnancy due to teratogenic effects?","options":[{"id":"a","text":"Ivermectin"},{"id":"b","text":"Praziquantel"},{"id":"c","text":"Albendazole"},{"id":"d","text":"Pyrantel pamoate"}],"answerId":"c","explanation":"Benzimidazoles like albendazole are teratogenic in animals and should be avoided in early pregnancy.","kind":"trap","origin":"ai"},{"id":"anthelmintic-drug-classes~ai-5","moduleId":"anthelmintic-drug-classes","stem":"In the context of helminth classification, which drug is primarily used for treating trematodes?","options":[{"id":"a","text":"Albendazole"},{"id":"b","text":"Ivermectin"},{"id":"c","text":"Praziquantel"},{"id":"d","text":"Pyrantel pamoate"}],"answerId":"c","explanation":"Praziquantel is the drug of choice for treating trematodes (flukes).","kind":"recall","linkedModuleIds":["helminth-classification-overview"],"origin":"ai"},{"id":"anthelmintic-drug-classes~ai-6","moduleId":"anthelmintic-drug-classes","stem":"Which of the following statements about dosing for intestinal versus tissue helminth infections is correct?","options":[{"id":"a","text":"A single dose of albendazole treats all infections"},{"id":"b","text":"Intestinal infections require prolonged therapy"},{"id":"c","text":"Tissue infections need higher doses and prolonged therapy"},{"id":"d","text":"All infections can be treated with short courses"}],"answerId":"c","explanation":"Tissue infections require prolonged, higher-dose therapy due to the need for systemic absorption.","kind":"trap","origin":"ai"},{"id":"anthelmintic-drug-classes~ai-7","moduleId":"anthelmintic-drug-classes","stem":"What is the primary mechanism of action of ivermectin?","options":[{"id":"a","text":"Inhibit glucose uptake"},{"id":"b","text":"Block glutamate-gated Cl⁻ channels"},{"id":"c","text":"Increase intracellular calcium"},{"id":"d","text":"Induce spastic paralysis"}],"answerId":"b","explanation":"Ivermectin acts by opening glutamate-gated Cl⁻ channels, leading to flaccid paralysis of the worms.","kind":"mechanism","origin":"ai"},{"id":"anthelmintic-drug-classes~ai-8","moduleId":"anthelmintic-drug-classes","stem":"Which anthelmintic is effective against Strongyloides stercoralis?","options":[{"id":"a","text":"Praziquantel"},{"id":"b","text":"Albendazole"},{"id":"c","text":"Ivermectin"},{"id":"d","text":"Pyrantel pamoate"}],"answerId":"c","explanation":"Ivermectin is specifically effective against Strongyloides stercoralis.","kind":"recall","linkedModuleIds":["helminth-classification-overview"],"origin":"ai"}],"hiv-antiretroviral-therapy":[{"id":"hiv-antiretroviral-therapy~ai-0","moduleId":"hiv-antiretroviral-therapy","stem":"What is the primary reason for using combination antiretroviral therapy (ART) in HIV treatment?","options":[{"id":"a","text":"To enhance patient adherence to medication"},{"id":"b","text":"To suppress viral replication and prevent resistance"},{"id":"c","text":"To reduce the cost of treatment"},{"id":"d","text":"To minimize side effects of medications"}],"answerId":"b","explanation":"Combination ART suppresses viral replication effectively and prevents the emergence of resistant HIV strains due to the virus's high mutation rate.","kind":"recall","origin":"ai"},{"id":"hiv-antiretroviral-therapy~ai-1","moduleId":"hiv-antiretroviral-therapy","stem":"Which of the following is a common side effect associated with protease inhibitors?","options":[{"id":"a","text":"Renal toxicity"},{"id":"b","text":"Hypersensitivity reactions"},{"id":"c","text":"CYP3A4 drug interactions"},{"id":"d","text":"Anemia"}],"answerId":"c","explanation":"Protease inhibitors are known for their significant CYP3A4 interactions, which can lead to numerous drug interactions.","kind":"recall","origin":"ai"},{"id":"hiv-antiretroviral-therapy~ai-2","moduleId":"hiv-antiretroviral-therapy","stem":"A patient on abacavir develops a life-threatening hypersensitivity reaction. What is the most appropriate action prior to initiating abacavir therapy?","options":[{"id":"a","text":"Perform a liver function test"},{"id":"b","text":"Screen for HLA-B*57:01 allele"},{"id":"c","text":"Administer a corticosteroid"},{"id":"d","text":"Discontinue all antiretroviral medications"}],"answerId":"b","explanation":"Screening for the HLA-B*57:01 allele is crucial before starting abacavir to prevent hypersensitivity reactions.","kind":"clinical","origin":"ai"},{"id":"hiv-antiretroviral-therapy~ai-3","moduleId":"hiv-antiretroviral-therapy","stem":"What does the term 'U=U' signify in the context of HIV treatment?","options":[{"id":"a","text":"Undetectable viral load equals untransmittable HIV"},{"id":"b","text":"Uncontrolled HIV leads to increased viral load"},{"id":"c","text":"Uninterrupted therapy results in undetectable viral load"},{"id":"d","text":"Universal precautions are required for all HIV patients"}],"answerId":"a","explanation":"'U=U' stands for 'Undetectable = Untransmittable', meaning that sustained viral suppression prevents HIV transmission.","kind":"recall","origin":"ai"},{"id":"hiv-antiretroviral-therapy~ai-4","moduleId":"hiv-antiretroviral-therapy","stem":"Which mechanism explains the rapid development of resistance in HIV when treated with a single antiretroviral drug?","options":[{"id":"a","text":"Inhibition of reverse transcriptase"},{"id":"b","text":"High mutation rate of HIV"},{"id":"c","text":"Increased viral load"},{"id":"d","text":"Decreased immune response"}],"answerId":"b","explanation":"HIV has a high mutation rate, leading to rapid selection of resistant strains under single-drug pressure.","kind":"mechanism","origin":"ai"},{"id":"hiv-antiretroviral-therapy~ai-5","moduleId":"hiv-antiretroviral-therapy","stem":"A patient is prescribed tenofovir/emtricitabine for pre-exposure prophylaxis (PrEP). What is the primary mechanism of action for this regimen?","options":[{"id":"a","text":"Inhibition of viral entry into host cells"},{"id":"b","text":"Inhibition of reverse transcription"},{"id":"c","text":"Inhibition of viral integration"},{"id":"d","text":"Inhibition of viral assembly"}],"answerId":"b","explanation":"Tenofovir/emtricitabine act as nucleoside reverse transcriptase inhibitors, preventing reverse transcription of viral RNA.","kind":"mechanism","origin":"ai"},{"id":"hiv-antiretroviral-therapy~ai-6","moduleId":"hiv-antiretroviral-therapy","stem":"How does the knowledge of HLA-B*57:01 screening integrate with pharmacogenomics in HIV treatment?","options":[{"id":"a","text":"It helps in determining the efficacy of protease inhibitors."},{"id":"b","text":"It identifies patients at risk for hypersensitivity to abacavir."},{"id":"c","text":"It predicts the likelihood of drug-drug interactions."},{"id":"d","text":"It assesses the overall viral load in patients."}],"answerId":"b","explanation":"HLA-B*57:01 screening is a pharmacogenomic test that identifies patients at risk for hypersensitivity reactions to abacavir.","kind":"integration","linkedModuleIds":["pharmacogenomics"],"origin":"ai"},{"id":"hiv-antiretroviral-therapy~ai-7","moduleId":"hiv-antiretroviral-therapy","stem":"Which aspect of drug interactions is particularly relevant for patients on protease inhibitors in the context of HIV treatment?","options":[{"id":"a","text":"Increased renal toxicity"},{"id":"b","text":"Enhanced metabolism of antiretrovirals"},{"id":"c","text":"CYP3A4-mediated drug interactions"},{"id":"d","text":"Inhibition of reverse transcriptase"}],"answerId":"c","explanation":"Protease inhibitors are known to interact with CYP3A4, affecting the metabolism of many other drugs.","kind":"integration","linkedModuleIds":["drug-interactions-mechanisms"],"origin":"ai"}],"dermatologic-diagnosis-morphology":[{"id":"dermatologic-diagnosis-morphology~ai-0","moduleId":"dermatologic-diagnosis-morphology","stem":"What is the primary lesion characterized by a flat, non-palpable color change less than 1 cm?","options":[{"id":"a","text":"Macule"},{"id":"b","text":"Patch"},{"id":"c","text":"Papule"},{"id":"d","text":"Plaque"}],"answerId":"a","explanation":"A macule is defined as a flat, non-palpable color change that is less than 1 cm in size.","kind":"recall","origin":"ai"},{"id":"dermatologic-diagnosis-morphology~ai-1","moduleId":"dermatologic-diagnosis-morphology","stem":"Which secondary change is characterized by the loss of epidermis that heals without scarring?","options":[{"id":"a","text":"Erosion"},{"id":"b","text":"Ulcer"},{"id":"c","text":"Excoriation"},{"id":"d","text":"Fissure"}],"answerId":"a","explanation":"An erosion is a loss of the epidermis that heals without scarring, unlike an ulcer which extends into the dermis.","kind":"recall","origin":"ai"},{"id":"dermatologic-diagnosis-morphology~ai-2","moduleId":"dermatologic-diagnosis-morphology","stem":"A patient presents with grouped vesicles on an erythematous base. What is the most likely diagnosis?","options":[{"id":"a","text":"Psoriasis"},{"id":"b","text":"Herpes Simplex Virus"},{"id":"c","text":"Eczema"},{"id":"d","text":"Contact Dermatitis"}],"answerId":"b","explanation":"Grouped vesicles on an erythematous base are characteristic of herpes simplex virus infections.","kind":"clinical","origin":"ai"},{"id":"dermatologic-diagnosis-morphology~ai-3","moduleId":"dermatologic-diagnosis-morphology","stem":"What is the primary lesion that is raised and flat-topped, measuring greater than 1 cm?","options":[{"id":"a","text":"Papule"},{"id":"b","text":"Plaque"},{"id":"c","text":"Nodule"},{"id":"d","text":"Macule"}],"answerId":"b","explanation":"A plaque is a raised, flat-topped lesion that is greater than 1 cm in size, commonly seen in conditions like psoriasis.","kind":"recall","origin":"ai"},{"id":"dermatologic-diagnosis-morphology~ai-4","moduleId":"dermatologic-diagnosis-morphology","stem":"Which of the following best describes lichenification?","options":[{"id":"a","text":"Thickened skin with accentuated markings"},{"id":"b","text":"Dried exudate on the skin"},{"id":"c","text":"Loss of epidermis"},{"id":"d","text":"Fluid-filled lesion"}],"answerId":"a","explanation":"Lichenification refers to thickened skin with accentuated markings due to chronic rubbing or irritation.","kind":"recall","origin":"ai"},{"id":"dermatologic-diagnosis-morphology~ai-5","moduleId":"dermatologic-diagnosis-morphology","stem":"In the context of skin lesions, how do erosion and ulcer differ?","options":[{"id":"a","text":"Erosion heals with a scar; ulcer does not"},{"id":"b","text":"Erosion is superficial; ulcer is deeper"},{"id":"c","text":"Both terms are interchangeable"},{"id":"d","text":"Erosion is a type of ulcer"}],"answerId":"b","explanation":"Erosion is a superficial loss of epidermis that heals without scarring, while an ulcer extends into the dermis and heals with a scar.","kind":"trap","origin":"ai"},{"id":"dermatologic-diagnosis-morphology~ai-6","moduleId":"dermatologic-diagnosis-morphology","stem":"A patient with psoriasis presents with a thickened, scaly plaque on the extensor surfaces. Which linked module would provide more information on this condition?","options":[{"id":"a","text":"Skin Anatomy & Histology"},{"id":"b","text":"Eczema & Dermatitis"},{"id":"c","text":"Papulosquamous Diseases"},{"id":"d","text":"Dermatological Investigations"}],"answerId":"c","explanation":"The module on Papulosquamous Diseases would provide further insights into psoriasis and similar conditions.","kind":"integration","linkedModuleIds":["papulosquamous-diseases"],"origin":"ai"},{"id":"dermatologic-diagnosis-morphology~ai-7","moduleId":"dermatologic-diagnosis-morphology","stem":"Which skin lesion morphology is most relevant when assessing a patient with a vesicular rash that follows a dermatomal distribution?","options":[{"id":"a","text":"Macule"},{"id":"b","text":"Bulla"},{"id":"c","text":"Plaque"},{"id":"d","text":"Wheal"}],"answerId":"b","explanation":"A bulla is a fluid-filled lesion greater than 1 cm and is relevant in conditions like herpes zoster, which follows a dermatomal distribution.","kind":"integration","linkedModuleIds":["skin-anatomy-histology"],"origin":"ai"}],"cytotoxic-chemotherapy-agents":[{"id":"cytotoxic-chemotherapy-agents~ai-0","moduleId":"cytotoxic-chemotherapy-agents","stem":"Which cytotoxic chemotherapy agent is associated with haemorrhagic cystitis?","options":[{"id":"a","text":"Cisplatin"},{"id":"b","text":"Vincristine"},{"id":"c","text":"Cyclophosphamide"},{"id":"d","text":"Doxorubicin"}],"answerId":"c","explanation":"Cyclophosphamide can cause haemorrhagic cystitis due to the metabolite acrolein, which can be prevented with mesna.","kind":"recall","origin":"ai"},{"id":"cytotoxic-chemotherapy-agents~ai-1","moduleId":"cytotoxic-chemotherapy-agents","stem":"What is the primary mechanism of action of methotrexate?","options":[{"id":"a","text":"Inhibition of topoisomerase"},{"id":"b","text":"Inhibition of dihydrofolate reductase"},{"id":"c","text":"Alkylation of DNA"},{"id":"d","text":"Stabilization of microtubules"}],"answerId":"b","explanation":"Methotrexate acts by inhibiting dihydrofolate reductase, which is crucial for DNA synthesis.","kind":"mechanism","origin":"ai"},{"id":"cytotoxic-chemotherapy-agents~ai-2","moduleId":"cytotoxic-chemotherapy-agents","stem":"A patient receiving vincristine develops peripheral neuropathy. What is the mechanism behind this toxicity?","options":[{"id":"a","text":"Inhibition of DNA synthesis"},{"id":"b","text":"Inhibition of microtubule assembly"},{"id":"c","text":"Cross-linking of DNA"},{"id":"d","text":"Inhibition of topoisomerase"}],"answerId":"b","explanation":"Vincristine inhibits microtubule assembly, leading to peripheral neuropathy as a side effect.","kind":"recall","origin":"ai"},{"id":"cytotoxic-chemotherapy-agents~ai-3","moduleId":"cytotoxic-chemotherapy-agents","stem":"Which of the following is a shared toxicity of cytotoxic chemotherapy agents?","options":[{"id":"a","text":"Pulmonary fibrosis"},{"id":"b","text":"Nephrotoxicity"},{"id":"c","text":"Myelosuppression"},{"id":"d","text":"Cumulative cardiomyopathy"}],"answerId":"c","explanation":"Myelosuppression is a common dose-limiting toxicity seen with many cytotoxic chemotherapy agents.","kind":"trap","origin":"ai"},{"id":"cytotoxic-chemotherapy-agents~ai-4","moduleId":"cytotoxic-chemotherapy-agents","stem":"Why is combination chemotherapy preferred over single-agent therapy?","options":[{"id":"a","text":"It reduces the need for supportive care"},{"id":"b","text":"It maximizes tumor cell kill and limits resistance"},{"id":"c","text":"It allows for higher doses of a single agent"},{"id":"d","text":"It minimizes the risk of side effects"}],"answerId":"b","explanation":"Combination chemotherapy maximizes tumor cell kill through different mechanisms and minimizes the emergence of resistance.","kind":"trap","origin":"ai"},{"id":"cytotoxic-chemotherapy-agents~ai-5","moduleId":"cytotoxic-chemotherapy-agents","stem":"Which cytotoxic agent is most likely to cause cumulative cardiotoxicity?","options":[{"id":"a","text":"Cyclophosphamide"},{"id":"b","text":"Doxorubicin"},{"id":"c","text":"Vincristine"},{"id":"d","text":"Cisplatin"}],"answerId":"b","explanation":"Doxorubicin is known for its cumulative dose-dependent cardiotoxicity.","kind":"recall","origin":"ai"},{"id":"cytotoxic-chemotherapy-agents~ai-6","moduleId":"cytotoxic-chemotherapy-agents","stem":"How does the mechanism of action of 5-fluorouracil relate to nucleotide metabolism?","options":[{"id":"a","text":"It inhibits dihydrofolate reductase"},{"id":"b","text":"It mimics uracil and inhibits thymidylate synthase"},{"id":"c","text":"It alkylates DNA"},{"id":"d","text":"It stabilizes microtubules"}],"answerId":"b","explanation":"5-Fluorouracil mimics uracil and inhibits thymidylate synthase, affecting nucleotide metabolism.","kind":"integration","linkedModuleIds":["nucleotide-drugs-disorders"],"origin":"ai"},{"id":"cytotoxic-chemotherapy-agents~ai-7","moduleId":"cytotoxic-chemotherapy-agents","stem":"What is the role of TPMT in the metabolism of 6-mercaptopurine?","options":[{"id":"a","text":"It activates the drug"},{"id":"b","text":"It inactivates the drug"},{"id":"c","text":"It enhances its efficacy"},{"id":"d","text":"It causes nephrotoxicity"}],"answerId":"b","explanation":"TPMT (thiopurine S-methyltransferase) inactivates 6-mercaptopurine, and variations in TPMT activity can affect drug toxicity.","kind":"integration","linkedModuleIds":["pharmacogenomics"],"origin":"ai"}],"pharmacogenomics-clinical-implementation":[{"id":"pharmacogenomics-clinical-implementation~ai-0","moduleId":"pharmacogenomics-clinical-implementation","stem":"What is the primary purpose of pharmacogenomic testing in clinical practice?","options":[{"id":"a","text":"To determine drug interactions"},{"id":"b","text":"To individualize therapy based on genotype"},{"id":"c","text":"To predict all side effects of medications"},{"id":"d","text":"To replace clinical judgment in prescribing"}],"answerId":"b","explanation":"Pharmacogenomic testing is used to tailor drug therapy based on a patient's genetic makeup, optimizing efficacy and minimizing adverse reactions.","kind":"recall","origin":"ai"},{"id":"pharmacogenomics-clinical-implementation~ai-1","moduleId":"pharmacogenomics-clinical-implementation","stem":"Which genetic marker is associated with an increased risk of Stevens-Johnson syndrome when prescribing carbamazepine?","options":[{"id":"a","text":"HLA-B*15:02"},{"id":"b","text":"HLA-B*57:01"},{"id":"c","text":"DPYD"},{"id":"d","text":"CYP2D6"}],"answerId":"a","explanation":"HLA-B*15:02 is a genetic marker that indicates a higher risk of Stevens-Johnson syndrome in patients taking carbamazepine, especially in Southeast Asian populations.","kind":"recall","origin":"ai"},{"id":"pharmacogenomics-clinical-implementation~ai-2","moduleId":"pharmacogenomics-clinical-implementation","stem":"What is the mechanism of action for clopidogrel in patients with CYP2C19 poor metaboliser status?","options":[{"id":"a","text":"Increased drug activation"},{"id":"b","text":"Decreased drug activation"},{"id":"c","text":"Enhanced drug elimination"},{"id":"d","text":"No effect on drug metabolism"}],"answerId":"b","explanation":"CYP2C19 poor metabolizers have reduced activation of clopidogrel, leading to inadequate antiplatelet effects.","kind":"mechanism","origin":"ai"},{"id":"pharmacogenomics-clinical-implementation~ai-3","moduleId":"pharmacogenomics-clinical-implementation","stem":"What is a significant implementation challenge of pharmacogenomic testing?","options":[{"id":"a","text":"It is always cost-effective"},{"id":"b","text":"Results can be obtained instantly"},{"id":"c","text":"Integrating results into prescribing systems"},{"id":"d","text":"It eliminates the need for clinical judgment"}],"answerId":"c","explanation":"Integrating pharmacogenomic results into clinical practice and prescribing systems is a significant challenge that can affect the implementation of personalized medicine.","kind":"trap","origin":"ai"},{"id":"pharmacogenomics-clinical-implementation~ai-4","moduleId":"pharmacogenomics-clinical-implementation","stem":"A patient with G6PD deficiency is prescribed primaquine. What is the potential risk?","options":[{"id":"a","text":"Increased efficacy of primaquine"},{"id":"b","text":"Severe hemolysis"},{"id":"c","text":"No risk associated"},{"id":"d","text":"Enhanced drug metabolism"}],"answerId":"b","explanation":"Patients with G6PD deficiency are at risk of hemolysis when exposed to oxidant drugs like primaquine.","kind":"clinical","origin":"ai"},{"id":"pharmacogenomics-clinical-implementation~ai-5","moduleId":"pharmacogenomics-clinical-implementation","stem":"Why is pre-emptive pharmacogenomic testing preferred over reactive testing for high-risk drugs?","options":[{"id":"a","text":"It is less expensive"},{"id":"b","text":"It avoids delays in urgent therapy"},{"id":"c","text":"It requires less patient consent"},{"id":"d","text":"It is more accurate"}],"answerId":"b","explanation":"Pre-emptive testing allows for immediate access to genotype information, preventing delays in therapy that can occur with reactive testing.","kind":"trap","origin":"ai"},{"id":"pharmacogenomics-clinical-implementation~ai-6","moduleId":"pharmacogenomics-clinical-implementation","stem":"How does pharmacogenomics relate to drug metabolism in the context of CYP450 enzymes?","options":[{"id":"a","text":"It focuses solely on drug efficacy"},{"id":"b","text":"It predicts drug interactions"},{"id":"c","text":"It informs dosing based on metabolizer status"},{"id":"d","text":"It eliminates the need for drug monitoring"}],"answerId":"c","explanation":"Pharmacogenomics provides insights into how genetic variations affect drug metabolism via CYP450 enzymes, guiding dosing and drug selection.","kind":"integration","linkedModuleIds":["drug-metabolism-cyp450"],"origin":"ai"},{"id":"pharmacogenomics-clinical-implementation~ai-7","moduleId":"pharmacogenomics-clinical-implementation","stem":"What role does pharmacogenomics play in understanding adverse drug reactions?","options":[{"id":"a","text":"It identifies all possible drug interactions"},{"id":"b","text":"It helps predict specific adverse reactions based on genotype"},{"id":"c","text":"It eliminates the risk of all drug allergies"},{"id":"d","text":"It is unrelated to drug safety"}],"answerId":"b","explanation":"Pharmacogenomics helps predict specific adverse drug reactions by correlating genetic markers with known drug sensitivities.","kind":"integration","linkedModuleIds":["adverse-drug-reactions-allergy"],"origin":"ai"}],"adr-classification-mechanisms":[{"id":"adr-classification-mechanisms~ai-0","moduleId":"adr-classification-mechanisms","stem":"What type of adverse drug reaction (ADR) is characterized as dose-dependent and predictable?","options":[{"id":"a","text":"Type A"},{"id":"b","text":"Type B"},{"id":"c","text":"Type C"},{"id":"d","text":"Type D"}],"answerId":"a","explanation":"Type A ADRs are predictable extensions of drug pharmacology and are dose-dependent.","kind":"recall","origin":"ai"},{"id":"adr-classification-mechanisms~ai-1","moduleId":"adr-classification-mechanisms","stem":"Which of the following is an example of a Type B adverse drug reaction?","options":[{"id":"a","text":"Bleeding on warfarin"},{"id":"b","text":"Anaphylaxis from penicillin"},{"id":"c","text":"Osteoporosis from corticosteroids"},{"id":"d","text":"Rebound hypertension after β-blocker withdrawal"}],"answerId":"b","explanation":"Anaphylaxis from penicillin is a Type B ADR, which is dose-independent and unpredictable.","kind":"recall","origin":"ai"},{"id":"adr-classification-mechanisms~ai-2","moduleId":"adr-classification-mechanisms","stem":"A patient develops bradycardia after starting a β-blocker. What type of ADR does this represent?","options":[{"id":"a","text":"Type A"},{"id":"b","text":"Type B"},{"id":"c","text":"Type C"},{"id":"d","text":"Type E"}],"answerId":"a","explanation":"This is a Type A ADR, as it is a predictable and dose-dependent effect of the drug.","kind":"clinical","origin":"ai"},{"id":"adr-classification-mechanisms~ai-3","moduleId":"adr-classification-mechanisms","stem":"What is the primary method of monitoring drug safety after a drug is marketed?","options":[{"id":"a","text":"Clinical trials"},{"id":"b","text":"Pharmacovigilance"},{"id":"c","text":"Preclinical studies"},{"id":"d","text":"Drug interactions assessment"}],"answerId":"b","explanation":"Pharmacovigilance involves monitoring drug safety through spontaneous reporting and causality assessment.","kind":"recall","origin":"ai"},{"id":"adr-classification-mechanisms~ai-4","moduleId":"adr-classification-mechanisms","stem":"Which of the following statements about adverse drug reactions is true?","options":[{"id":"a","text":"All ADRs are unpredictable idiosyncratic events"},{"id":"b","text":"Type A ADRs are common and manageable by dose adjustment"},{"id":"c","text":"Type B ADRs are the most common"},{"id":"d","text":"Chronic ADRs are always dose-dependent"}],"answerId":"b","explanation":"Type A ADRs are indeed common and can often be managed by adjusting the dose.","kind":"trap","origin":"ai"},{"id":"adr-classification-mechanisms~ai-5","moduleId":"adr-classification-mechanisms","stem":"A patient experiences rebound hypertension after stopping a β-blocker. This is classified as which type of ADR?","options":[{"id":"a","text":"Type A"},{"id":"b","text":"Type B"},{"id":"c","text":"Type E"},{"id":"d","text":"Type F"}],"answerId":"c","explanation":"This is a Type E ADR, which refers to adverse effects occurring after the withdrawal of a drug.","kind":"recall","origin":"ai"},{"id":"adr-classification-mechanisms~ai-6","moduleId":"adr-classification-mechanisms","stem":"How does pharmacovigilance relate to drug development?","options":[{"id":"a","text":"It is part of preclinical studies"},{"id":"b","text":"It assesses drug interactions"},{"id":"c","text":"It monitors safety post-marketing"},{"id":"d","text":"It ensures bioequivalence"}],"answerId":"c","explanation":"Pharmacovigilance is crucial for monitoring drug safety after a drug has been marketed.","kind":"integration","linkedModuleIds":["drug-development-bioequivalence"],"origin":"ai"},{"id":"adr-classification-mechanisms~ai-7","moduleId":"adr-classification-mechanisms","stem":"Which type of ADR is most likely to be detected through pharmacovigilance?","options":[{"id":"a","text":"Type A"},{"id":"b","text":"Type B"},{"id":"c","text":"Type C"},{"id":"d","text":"Type D"}],"answerId":"b","explanation":"Type B ADRs, being rare and unpredictable, are often detected through pharmacovigilance efforts.","kind":"integration","linkedModuleIds":["adverse-drug-reactions-allergy"],"origin":"ai"}],"skin-anatomy-histology":[{"id":"skin-anatomy-histology~ai-0","moduleId":"skin-anatomy-histology","stem":"Which layer of the epidermis is primarily responsible for the barrier function of the skin?","options":[{"id":"a","text":"Stratum corneum"},{"id":"b","text":"Stratum granulosum"},{"id":"c","text":"Stratum spinosum"},{"id":"d","text":"Stratum basale"}],"answerId":"a","explanation":"The stratum corneum is the outermost layer of the epidermis, consisting of dead, flattened keratinocytes that form a protective barrier.","kind":"recall","origin":"ai"},{"id":"skin-anatomy-histology~ai-1","moduleId":"skin-anatomy-histology","stem":"What is the primary function of melanocytes in the epidermis?","options":[{"id":"a","text":"Produce keratin"},{"id":"b","text":"Transfer melanin to keratinocytes"},{"id":"c","text":"Provide structural support"},{"id":"d","text":"Facilitate sensation"}],"answerId":"b","explanation":"Melanocytes are responsible for producing and transferring melanin to keratinocytes, which helps protect DNA from UV damage.","kind":"recall","origin":"ai"},{"id":"skin-anatomy-histology~ai-2","moduleId":"skin-anatomy-histology","stem":"A patient presents with tense bullae on the skin. Which condition is most likely?","options":[{"id":"a","text":"Pemphigus vulgaris"},{"id":"b","text":"Bullous pemphigoid"},{"id":"c","text":"Contact dermatitis"},{"id":"d","text":"Eczema"}],"answerId":"b","explanation":"Bullous pemphigoid is characterized by tense bullae due to subepidermal splits at the dermo-epidermal junction.","kind":"clinical","origin":"ai"},{"id":"skin-anatomy-histology~ai-3","moduleId":"skin-anatomy-histology","stem":"In which layer of the epidermis do keratinocytes primarily proliferate?","options":[{"id":"a","text":"Stratum corneum"},{"id":"b","text":"Stratum granulosum"},{"id":"c","text":"Stratum basale"},{"id":"d","text":"Stratum lucidum"}],"answerId":"c","explanation":"The stratum basale is the deepest layer of the epidermis where keratinocyte proliferation occurs.","kind":"recall","origin":"ai"},{"id":"skin-anatomy-histology~ai-4","moduleId":"skin-anatomy-histology","stem":"Which of the following statements correctly differentiates pemphigus from bullous pemphigoid?","options":[{"id":"a","text":"Both target the same layer of skin"},{"id":"b","text":"Pemphigus causes tense bullae"},{"id":"c","text":"Bullous pemphigoid targets hemidesmosomes"},{"id":"d","text":"Pemphigus has a positive Nikolsky sign"}],"answerId":"d","explanation":"Pemphigus is characterized by intra-epidermal splits and typically presents with flaccid bullae and a positive Nikolsky sign.","kind":"trap","origin":"ai"},{"id":"skin-anatomy-histology~ai-5","moduleId":"skin-anatomy-histology","stem":"How does the structure of the dermis contribute to its function?","options":[{"id":"a","text":"It provides a barrier against pathogens"},{"id":"b","text":"It contains sensory receptors and blood vessels"},{"id":"c","text":"It is avascular and relies on the epidermis"},{"id":"d","text":"It is primarily composed of adipose tissue"}],"answerId":"b","explanation":"The dermis contains blood vessels, nerves, and sensory receptors, which are essential for thermoregulation and sensation.","kind":"mechanism","origin":"ai"},{"id":"skin-anatomy-histology~ai-6","moduleId":"skin-anatomy-histology","stem":"Which layer of skin is absent in thin skin but present in thick skin such as the palms and soles?","options":[{"id":"a","text":"Stratum corneum"},{"id":"b","text":"Stratum lucidum"},{"id":"c","text":"Stratum granulosum"},{"id":"d","text":"Stratum basale"}],"answerId":"b","explanation":"The stratum lucidum is an additional layer found only in thick skin, providing extra protection.","kind":"recall","origin":"ai"},{"id":"skin-anatomy-histology~ai-7","moduleId":"skin-anatomy-histology","stem":"How does the epidermis relate to the physiology of skin thermoregulation?","options":[{"id":"a","text":"It regulates blood flow to the dermis"},{"id":"b","text":"It provides insulation through adipose tissue"},{"id":"c","text":"It acts as a barrier to prevent water loss"},{"id":"d","text":"It contains sweat glands for heat dissipation"}],"answerId":"c","explanation":"The epidermis acts as a barrier to prevent water loss, which is crucial for maintaining homeostasis during thermoregulation.","kind":"integration","linkedModuleIds":["skin-physiology-thermoregulation"],"origin":"ai"},{"id":"skin-anatomy-histology~ai-8","moduleId":"skin-anatomy-histology","stem":"What role do appendages of the skin play in overall skin function?","options":[{"id":"a","text":"They are primarily for structural support"},{"id":"b","text":"They assist in thermoregulation and sensation"},{"id":"c","text":"They are involved in immune response"},{"id":"d","text":"They produce melanin for pigmentation"}],"answerId":"b","explanation":"Skin appendages such as sweat glands and hair follicles play significant roles in thermoregulation and sensation.","kind":"integration","linkedModuleIds":["dermis-appendages-glands"],"origin":"ai"}],"immunostimulants-biologics":[{"id":"immunostimulants-biologics~ai-0","moduleId":"immunostimulants-biologics","stem":"What is the primary mechanism of action of G-CSF (filgrastim)?","options":[{"id":"a","text":"Stimulates T-cell proliferation"},{"id":"b","text":"Enhances neutrophil recovery"},{"id":"c","text":"Inhibits cytokine release"},{"id":"d","text":"Promotes antibody production"}],"answerId":"b","explanation":"G-CSF primarily enhances the recovery of neutrophils after chemotherapy by stimulating their production in the bone marrow.","kind":"mechanism","origin":"ai"},{"id":"immunostimulants-biologics~ai-1","moduleId":"immunostimulants-biologics","stem":"Which cytokine is used in the treatment of multiple sclerosis?","options":[{"id":"a","text":"IFN-α"},{"id":"b","text":"IFN-β"},{"id":"c","text":"IL-2"},{"id":"d","text":"G-CSF"}],"answerId":"b","explanation":"IFN-β is specifically indicated for the treatment of multiple sclerosis.","kind":"recall","origin":"ai"},{"id":"immunostimulants-biologics~ai-2","moduleId":"immunostimulants-biologics","stem":"A patient develops flu-like symptoms after starting treatment with an antiviral agent. Which class of drugs is most likely responsible?","options":[{"id":"a","text":"Interleukins"},{"id":"b","text":"Colony-stimulating factors"},{"id":"c","text":"Interferons"},{"id":"d","text":"Checkpoint inhibitors"}],"answerId":"c","explanation":"Interferons commonly cause flu-like symptoms as a side effect.","kind":"recall","origin":"ai"},{"id":"immunostimulants-biologics~ai-3","moduleId":"immunostimulants-biologics","stem":"What is a key difference between active and passive immunization?","options":[{"id":"a","text":"Active immunization provides immediate protection"},{"id":"b","text":"Passive immunization requires time to develop immunity"},{"id":"c","text":"Active immunization generates memory cells"},{"id":"d","text":"Passive immunization is long-lasting"}],"answerId":"c","explanation":"Active immunization generates memory cells and a long-lasting immune response, while passive immunization provides immediate but transient protection without memory.","kind":"trap","origin":"ai"},{"id":"immunostimulants-biologics~ai-4","moduleId":"immunostimulants-biologics","stem":"Which of the following vaccines is contraindicated in immunosuppressed patients?","options":[{"id":"a","text":"Inactivated polio vaccine"},{"id":"b","text":"MMR vaccine"},{"id":"c","text":"Tetanus toxoid vaccine"},{"id":"d","text":"Hepatitis B vaccine"}],"answerId":"b","explanation":"Live-attenuated vaccines like the MMR vaccine are contraindicated in immunosuppressed patients due to the risk of disseminated infection.","kind":"recall","origin":"ai"},{"id":"immunostimulants-biologics~ai-5","moduleId":"immunostimulants-biologics","stem":"A patient receives passive immunization for rabies exposure. What is the expected duration of protection?","options":[{"id":"a","text":"Days to weeks"},{"id":"b","text":"Months"},{"id":"c","text":"Years"},{"id":"d","text":"Lifetime"}],"answerId":"a","explanation":"Passive immunization provides immediate but temporary protection, typically lasting days to weeks.","kind":"recall","origin":"ai"},{"id":"immunostimulants-biologics~ai-6","moduleId":"immunostimulants-biologics","stem":"How do immune checkpoint inhibitors primarily function in cancer therapy?","options":[{"id":"a","text":"Stimulating T-cell activity"},{"id":"b","text":"Inhibiting tumor growth directly"},{"id":"c","text":"Blocking immune suppression"},{"id":"d","text":"Enhancing antibody production"}],"answerId":"a","explanation":"Immune checkpoint inhibitors stimulate T-cell activity by blocking the inhibitory signals that prevent T-cells from attacking tumors.","kind":"mechanism","origin":"ai"},{"id":"immunostimulants-biologics~ai-7","moduleId":"immunostimulants-biologics","stem":"Which immunostimulant is most likely to cause autoimmune side effects during cancer treatment?","options":[{"id":"a","text":"G-CSF"},{"id":"b","text":"Interferon"},{"id":"c","text":"IL-2"},{"id":"d","text":"Checkpoint inhibitors"}],"answerId":"d","explanation":"Checkpoint inhibitors are known to cause immune-related adverse events, including autoimmune side effects.","kind":"recall","origin":"ai"},{"id":"immunostimulants-biologics~ai-8","moduleId":"immunostimulants-biologics","stem":"How does the use of G-CSF relate to the management of chemotherapy-induced neutropenia?","options":[{"id":"a","text":"It directly kills cancer cells"},{"id":"b","text":"It enhances neutrophil recovery"},{"id":"c","text":"It prevents nausea and vomiting"},{"id":"d","text":"It reduces tumor size"}],"answerId":"b","explanation":"G-CSF enhances neutrophil recovery after chemotherapy, thereby reducing the risk of infection associated with neutropenia.","kind":"integration","linkedModuleIds":["targeted-cancer-therapy"],"origin":"ai"},{"id":"immunostimulants-biologics~ai-9","moduleId":"immunostimulants-biologics","stem":"What is the role of vaccines in the context of immunostimulants?","options":[{"id":"a","text":"Provide immediate protection"},{"id":"b","text":"Stimulate long-term immunity"},{"id":"c","text":"Require no immune response"},{"id":"d","text":"Are used only in cancer therapy"}],"answerId":"b","explanation":"Vaccines actively stimulate the immune system to generate long-term immunity, distinguishing them from passive immunization.","kind":"integration","linkedModuleIds":["history-germ-theory-modern-medicine"],"origin":"ai"}],"skin-aging":[{"id":"skin-aging~ai-0","moduleId":"skin-aging","stem":"What is the primary cause of extrinsic skin aging?","options":[{"id":"a","text":"Genetic factors"},{"id":"b","text":"Cumulative UV exposure"},{"id":"c","text":"Hormonal changes"},{"id":"d","text":"Smoking"}],"answerId":"b","explanation":"Cumulative UV exposure is the dominant preventable cause of extrinsic skin aging, leading to photoaging.","kind":"recall","origin":"ai"},{"id":"skin-aging~ai-1","moduleId":"skin-aging","stem":"Which of the following skin changes is characteristic of intrinsic aging?","options":[{"id":"a","text":"Coarse deep wrinkles"},{"id":"b","text":"Mottled pigmentation"},{"id":"c","text":"Thin, dry skin"},{"id":"d","text":"Actinic keratoses"}],"answerId":"c","explanation":"Thin, dry skin is a hallmark of intrinsic aging, while the others are associated with extrinsic aging.","kind":"recall","origin":"ai"},{"id":"skin-aging~ai-2","moduleId":"skin-aging","stem":"What is the mechanism by which UV exposure leads to skin cancer?","options":[{"id":"a","text":"Increased melanin production"},{"id":"b","text":"Pyrimidine dimer formation"},{"id":"c","text":"Collagen synthesis"},{"id":"d","text":"Decreased Langerhans cells"}],"answerId":"b","explanation":"UV exposure causes DNA damage through pyrimidine dimer formation, which can lead to skin cancer.","kind":"mechanism","origin":"ai"},{"id":"skin-aging~ai-3","moduleId":"skin-aging","stem":"A 60-year-old patient presents with coarse wrinkles and yellow leathery skin on the face. What is the most likely cause?","options":[{"id":"a","text":"Intrinsic aging"},{"id":"b","text":"Photoaging"},{"id":"c","text":"Hormonal changes"},{"id":"d","text":"Genetic predisposition"}],"answerId":"b","explanation":"Coarse wrinkles and yellow leathery skin are indicative of photoaging due to UV exposure.","kind":"clinical","origin":"ai"},{"id":"skin-aging~ai-4","moduleId":"skin-aging","stem":"Which of the following statements about skin aging is true?","options":[{"id":"a","text":"All skin wrinkling is unavoidable with age"},{"id":"b","text":"Intrinsic aging is preventable"},{"id":"c","text":"Extrinsic aging is primarily genetic"},{"id":"d","text":"Photoaging is largely preventable"}],"answerId":"d","explanation":"Photoaging is largely preventable through photoprotection, unlike intrinsic aging which is genetically programmed.","kind":"trap","origin":"ai"},{"id":"skin-aging~ai-5","moduleId":"skin-aging","stem":"How does tretinoin improve fine wrinkles in aging skin?","options":[{"id":"a","text":"Increases melanin production"},{"id":"b","text":"Stimulates collagen synthesis"},{"id":"c","text":"Decreases UV damage"},{"id":"d","text":"Inhibits matrix metalloproteinases"}],"answerId":"b","explanation":"Tretinoin improves fine wrinkles by stimulating collagen synthesis in the skin.","kind":"mechanism","origin":"ai"},{"id":"skin-aging~ai-6","moduleId":"skin-aging","stem":"Which skin finding is associated with actinic keratosis?","options":[{"id":"a","text":"Coarse deep wrinkles"},{"id":"b","text":"Scaly pre-malignant lesions"},{"id":"c","text":"Thin, dry skin"},{"id":"d","text":"Mottled pigmentation"}],"answerId":"b","explanation":"Actinic keratosis presents as scaly pre-malignant lesions on chronically sun-damaged skin.","kind":"recall","origin":"ai"},{"id":"skin-aging~ai-7","moduleId":"skin-aging","stem":"How does photoaging relate to skin neoplasms?","options":[{"id":"a","text":"It reduces the risk of skin cancer"},{"id":"b","text":"It is unrelated to skin neoplasms"},{"id":"c","text":"It increases the risk of actinic keratosis and SCC"},{"id":"d","text":"It only affects cosmetic appearance"}],"answerId":"c","explanation":"Photoaging increases the risk of actinic keratosis, which can progress to squamous cell carcinoma (SCC).","kind":"integration","linkedModuleIds":["skin-neoplasms"],"origin":"ai"},{"id":"skin-aging~ai-8","moduleId":"skin-aging","stem":"What preventive measure is most effective against photoaging?","options":[{"id":"a","text":"Topical antioxidants"},{"id":"b","text":"Retinoids"},{"id":"c","text":"Broad-spectrum sunscreen"},{"id":"d","text":"Smoking cessation"}],"answerId":"c","explanation":"Broad-spectrum sunscreen is the most effective measure to prevent photoaging and its associated skin damage.","kind":"integration","linkedModuleIds":["photoaging-photoprotection"],"origin":"ai"}],"targeted-cancer-therapy":[{"id":"targeted-cancer-therapy~ai-0","moduleId":"targeted-cancer-therapy","stem":"What is the primary mechanism of action of imatinib in treating chronic myeloid leukemia?","options":[{"id":"a","text":"Inhibition of BCR-ABL tyrosine kinase"},{"id":"b","text":"Inhibition of EGFR"},{"id":"c","text":"Inhibition of HER2"},{"id":"d","text":"Inhibition of VEGF"}],"answerId":"a","explanation":"Imatinib specifically inhibits the BCR-ABL tyrosine kinase, which is crucial for the proliferation of cells in chronic myeloid leukemia.","kind":"mechanism","origin":"ai"},{"id":"targeted-cancer-therapy~ai-1","moduleId":"targeted-cancer-therapy","stem":"Which of the following targeted therapies requires biomarker testing for effective use?","options":[{"id":"a","text":"Cytotoxic chemotherapy"},{"id":"b","text":"Imatinib"},{"id":"c","text":"Doxorubicin"},{"id":"d","text":"Cyclophosphamide"}],"answerId":"b","explanation":"Imatinib requires biomarker testing for BCR-ABL positivity to ensure its effectiveness in chronic myeloid leukemia.","kind":"trap","origin":"ai"},{"id":"targeted-cancer-therapy~ai-2","moduleId":"targeted-cancer-therapy","stem":"What adverse effect is most commonly associated with trastuzumab in breast cancer treatment?","options":[{"id":"a","text":"Nephrotoxicity"},{"id":"b","text":"Cardiotoxicity"},{"id":"c","text":"Hepatotoxicity"},{"id":"d","text":"Pulmonary toxicity"}],"answerId":"b","explanation":"Trastuzumab is known for its cardiotoxic effects, particularly in patients with pre-existing heart conditions.","kind":"recall","origin":"ai"},{"id":"targeted-cancer-therapy~ai-3","moduleId":"targeted-cancer-therapy","stem":"Which immune-related adverse event is most likely to occur with checkpoint inhibitors?","options":[{"id":"a","text":"Nausea"},{"id":"b","text":"Colitis"},{"id":"c","text":"Neutropenia"},{"id":"d","text":"Anemia"}],"answerId":"b","explanation":"Checkpoint inhibitors can cause autoimmune colitis as a significant immune-related adverse event.","kind":"recall","origin":"ai"},{"id":"targeted-cancer-therapy~ai-4","moduleId":"targeted-cancer-therapy","stem":"In the context of targeted therapy, what is the primary purpose of biomarker testing?","options":[{"id":"a","text":"To determine drug dosage"},{"id":"b","text":"To identify potential side effects"},{"id":"c","text":"To confirm the presence of a molecular target"},{"id":"d","text":"To assess overall patient health"}],"answerId":"c","explanation":"Biomarker testing is essential to confirm the presence of a molecular target that the targeted therapy can act upon.","kind":"recall","origin":"ai"},{"id":"targeted-cancer-therapy~ai-5","moduleId":"targeted-cancer-therapy","stem":"How do immune checkpoint inhibitors differ from traditional chemotherapy agents?","options":[{"id":"a","text":"They are cytotoxic"},{"id":"b","text":"They target specific cancer cell markers"},{"id":"c","text":"They enhance the immune response against tumors"},{"id":"d","text":"They are always less toxic"}],"answerId":"c","explanation":"Immune checkpoint inhibitors enhance the immune response against tumors, unlike traditional chemotherapy agents which are cytotoxic.","kind":"integration","linkedModuleIds":["immunostimulants-biologics"],"origin":"ai"},{"id":"targeted-cancer-therapy~ai-6","moduleId":"targeted-cancer-therapy","stem":"Which of the following is a common side effect of bevacizumab, an anti-VEGF therapy?","options":[{"id":"a","text":"Hyperglycemia"},{"id":"b","text":"Hypertension"},{"id":"c","text":"Neutropenia"},{"id":"d","text":"Thrombocytopenia"}],"answerId":"b","explanation":"Bevacizumab is associated with hypertension as a common side effect due to its anti-angiogenic properties.","kind":"recall","origin":"ai"},{"id":"targeted-cancer-therapy~ai-7","moduleId":"targeted-cancer-therapy","stem":"What is a key difference between targeted therapies and cytotoxic chemotherapy?","options":[{"id":"a","text":"Targeted therapies are less expensive"},{"id":"b","text":"Targeted therapies require biomarker testing"},{"id":"c","text":"Cytotoxic chemotherapy is more selective"},{"id":"d","text":"Targeted therapies are always more effective"}],"answerId":"b","explanation":"Targeted therapies require biomarker testing to ensure the presence of the target, which is not a requirement for cytotoxic chemotherapy.","kind":"integration","linkedModuleIds":["cytotoxic-chemotherapy-agents"],"origin":"ai"}],"toxidromes-poisoning-approach":[{"id":"toxidromes-poisoning-approach~ai-0","moduleId":"toxidromes-poisoning-approach","stem":"What is the primary treatment for a patient exhibiting miosis, salivation, and bradycardia after suspected organophosphate poisoning?","options":[{"id":"a","text":"Atropine"},{"id":"b","text":"Naloxone"},{"id":"c","text":"Activated charcoal"},{"id":"d","text":"Flumazenil"}],"answerId":"a","explanation":"Atropine is the first-line treatment for cholinergic toxidrome due to organophosphate poisoning.","kind":"recall","origin":"ai"},{"id":"toxidromes-poisoning-approach~ai-1","moduleId":"toxidromes-poisoning-approach","stem":"Which of the following findings is characteristic of anticholinergic toxidrome?","options":[{"id":"a","text":"Miosis and bradycardia"},{"id":"b","text":"Dry skin and mydriasis"},{"id":"c","text":"Diaphoresis and tachycardia"},{"id":"d","text":"Pinpoint pupils"}],"answerId":"b","explanation":"Anticholinergic toxidrome is characterized by dry skin, mydriasis, and other symptoms like flushed skin and delirium.","kind":"recall","origin":"ai"},{"id":"toxidromes-poisoning-approach~ai-2","moduleId":"toxidromes-poisoning-approach","stem":"A patient presents with agitation, hypertension, and sweating. Which toxidrome is most likely?","options":[{"id":"a","text":"Cholinergic"},{"id":"b","text":"Anticholinergic"},{"id":"c","text":"Sympathomimetic"},{"id":"d","text":"Opioid"}],"answerId":"c","explanation":"The presence of agitation, hypertension, and sweating indicates a sympathomimetic toxidrome.","kind":"clinical","origin":"ai"},{"id":"toxidromes-poisoning-approach~ai-3","moduleId":"toxidromes-poisoning-approach","stem":"Which of the following is NOT effective for decontamination in overdose cases?","options":[{"id":"a","text":"Activated charcoal for salicylate"},{"id":"b","text":"Activated charcoal for iron"},{"id":"c","text":"Whole-bowel irrigation for lithium"},{"id":"d","text":"Activated charcoal for cocaine"}],"answerId":"b","explanation":"Activated charcoal is ineffective for iron overdose, making it a poor choice for decontamination.","kind":"trap","origin":"ai"},{"id":"toxidromes-poisoning-approach~ai-4","moduleId":"toxidromes-poisoning-approach","stem":"Which antidote is used for opioid toxicity?","options":[{"id":"a","text":"Atropine"},{"id":"b","text":"Naloxone"},{"id":"c","text":"Pralidoxime"},{"id":"d","text":"Flumazenil"}],"answerId":"b","explanation":"Naloxone is the specific antidote for opioid overdose, reversing respiratory depression and sedation.","kind":"recall","origin":"ai"},{"id":"toxidromes-poisoning-approach~ai-5","moduleId":"toxidromes-poisoning-approach","stem":"A patient with suspected salicylate overdose is treated with urine alkalinization. What is the mechanism behind this treatment?","options":[{"id":"a","text":"Increases renal excretion of salicylate"},{"id":"b","text":"Decreases gastrointestinal absorption"},{"id":"c","text":"Enhances hepatic metabolism"},{"id":"d","text":"Inhibits central nervous system effects"}],"answerId":"a","explanation":"Urine alkalinization increases the renal excretion of salicylate by ion trapping in the urine.","kind":"mechanism","origin":"ai"},{"id":"toxidromes-poisoning-approach~ai-6","moduleId":"toxidromes-poisoning-approach","stem":"In a patient with cholinergic poisoning, which of the following findings would help differentiate it from anticholinergic poisoning?","options":[{"id":"a","text":"Dry skin"},{"id":"b","text":"Mydriasis"},{"id":"c","text":"Bradycardia"},{"id":"d","text":"Sweating"}],"answerId":"d","explanation":"Sweating is a key differentiator; cholinergic poisoning presents with wet skin, while anticholinergic poisoning presents with dry skin.","kind":"trap","origin":"ai"},{"id":"toxidromes-poisoning-approach~ai-7","moduleId":"toxidromes-poisoning-approach","stem":"How does the treatment for cholinergic toxidrome relate to antimuscarinic drugs?","options":[{"id":"a","text":"Both use atropine as an antidote"},{"id":"b","text":"Both cause miosis"},{"id":"c","text":"Both lead to increased salivation"},{"id":"d","text":"Both are treated with naloxone"}],"answerId":"a","explanation":"Atropine is used to counteract the effects of cholinergic toxicity, while antimuscarinic drugs can also have similar effects.","kind":"integration","linkedModuleIds":["antimuscarinic-anticholinergic-drugs"],"origin":"ai"},{"id":"toxidromes-poisoning-approach~ai-8","moduleId":"toxidromes-poisoning-approach","stem":"Which of the following is a common feature of both cholinergic and sympathomimetic toxidromes?","options":[{"id":"a","text":"Bradycardia"},{"id":"b","text":"Miosis"},{"id":"c","text":"Agitation"},{"id":"d","text":"Dry skin"}],"answerId":"c","explanation":"Agitation can occur in both cholinergic and sympathomimetic toxidromes, but the other options are more specific to one or the other.","kind":"integration","linkedModuleIds":["cholinergic-drugs"],"origin":"ai"}],"drug-hypersensitivity-scars":[{"id":"drug-hypersensitivity-scars~ai-0","moduleId":"drug-hypersensitivity-scars","stem":"What is the first-line treatment for anaphylaxis caused by a drug allergy?","options":[{"id":"a","text":"Intravenous fluids"},{"id":"b","text":"Oral antihistamines"},{"id":"c","text":"Intramuscular adrenaline"},{"id":"d","text":"Corticosteroids"}],"answerId":"c","explanation":"Intramuscular adrenaline is the first-line treatment for anaphylaxis, as it rapidly counteracts the severe allergic reaction.","kind":"recall","origin":"ai"},{"id":"drug-hypersensitivity-scars~ai-1","moduleId":"drug-hypersensitivity-scars","stem":"Which type of hypersensitivity reaction is characterized by drug-induced hemolytic anemia?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"b","explanation":"Type II hypersensitivity reactions involve IgG antibodies that lead to cytotoxic effects, such as hemolytic anemia.","kind":"recall","origin":"ai"},{"id":"drug-hypersensitivity-scars~ai-2","moduleId":"drug-hypersensitivity-scars","stem":"A patient develops fever, mucosal erosions, and skin detachment weeks after starting allopurinol. What is the most likely diagnosis?","options":[{"id":"a","text":"DRESS syndrome"},{"id":"b","text":"Stevens-Johnson syndrome"},{"id":"c","text":"Type I hypersensitivity"},{"id":"d","text":"Drug-induced vasculitis"}],"answerId":"b","explanation":"These symptoms are characteristic of Stevens-Johnson syndrome, a severe cutaneous adverse reaction associated with allopurinol.","kind":"clinical","origin":"ai"},{"id":"drug-hypersensitivity-scars~ai-3","moduleId":"drug-hypersensitivity-scars","stem":"What distinguishes pseudo-allergy from true IgE-mediated allergy?","options":[{"id":"a","text":"Presence of eosinophilia"},{"id":"b","text":"Immediate onset of symptoms"},{"id":"c","text":"IgE involvement"},{"id":"d","text":"Direct mast-cell degranulation"}],"answerId":"d","explanation":"Pseudo-allergy involves direct mast-cell degranulation without IgE involvement, unlike true allergies which are mediated by IgE.","kind":"mechanism","origin":"ai"},{"id":"drug-hypersensitivity-scars~ai-4","moduleId":"drug-hypersensitivity-scars","stem":"Which of the following is a red flag indicating a severe cutaneous adverse reaction (SCAR)?","options":[{"id":"a","text":"Mild rash"},{"id":"b","text":"Nausea"},{"id":"c","text":"Fever and mucosal involvement"},{"id":"d","text":"Itching without skin changes"}],"answerId":"c","explanation":"Fever and mucosal involvement are red flags that suggest a severe cutaneous adverse reaction, requiring immediate action.","kind":"trap","origin":"ai"},{"id":"drug-hypersensitivity-scars~ai-5","moduleId":"drug-hypersensitivity-scars","stem":"How can HLA screening prevent severe cutaneous adverse reactions in patients taking carbamazepine?","options":[{"id":"a","text":"By identifying patients at risk for anaphylaxis"},{"id":"b","text":"By preventing drug interactions"},{"id":"c","text":"By predicting hypersensitivity reactions"},{"id":"d","text":"By ensuring proper dosing"}],"answerId":"c","explanation":"HLA screening can identify patients at risk for hypersensitivity reactions, allowing for safer prescribing of carbamazepine.","kind":"integration","linkedModuleIds":["pharmacogenomics"],"origin":"ai"},{"id":"drug-hypersensitivity-scars~ai-6","moduleId":"drug-hypersensitivity-scars","stem":"In a patient with a documented penicillin allergy, which of the following strategies can help reduce over-labeling of drug allergies?","options":[{"id":"a","text":"Prescribing broad-spectrum antibiotics"},{"id":"b","text":"Performing skin testing for penicillin"},{"id":"c","text":"Avoiding all beta-lactams"},{"id":"d","text":"Documenting all adverse reactions as allergies"}],"answerId":"b","explanation":"Performing skin testing for penicillin can help confirm or rule out true allergy, reducing unnecessary over-labeling.","kind":"integration","linkedModuleIds":["adverse-drug-reactions-allergy"],"origin":"ai"}],"pharmacodynamic-drug-interactions":[{"id":"pharmacodynamic-drug-interactions~ai-0","moduleId":"pharmacodynamic-drug-interactions","stem":"What type of pharmacodynamic interaction occurs when two drugs have additive effects on sedation?","options":[{"id":"a","text":"Antagonistic"},{"id":"b","text":"Synergistic"},{"id":"c","text":"Inhibitory"},{"id":"d","text":"Competitive"}],"answerId":"b","explanation":"Synergistic interactions occur when two drugs enhance each other's effects, such as in the case of sedation from opioids and benzodiazepines.","kind":"mechanism","origin":"ai"},{"id":"pharmacodynamic-drug-interactions~ai-1","moduleId":"pharmacodynamic-drug-interactions","stem":"Which of the following combinations is most likely to cause serotonin syndrome?","options":[{"id":"a","text":"SSRI + beta-blocker"},{"id":"b","text":"SSRI + MAOI"},{"id":"c","text":"SNRI + NSAID"},{"id":"d","text":"SSRI + opioid"}],"answerId":"b","explanation":"The combination of an SSRI and an MAOI can lead to serotonin syndrome due to their synergistic serotonergic effects.","kind":"recall","origin":"ai"},{"id":"pharmacodynamic-drug-interactions~ai-2","moduleId":"pharmacodynamic-drug-interactions","stem":"A patient presents with respiratory depression after taking an opioid and a benzodiazepine. What is the mechanism of this interaction?","options":[{"id":"a","text":"Pharmacokinetic interaction"},{"id":"b","text":"Additive CNS depression"},{"id":"c","text":"Competitive inhibition"},{"id":"d","text":"Metabolic clearance alteration"}],"answerId":"b","explanation":"The respiratory depression is due to additive CNS depression from the pharmacodynamic interaction between the opioid and benzodiazepine.","kind":"mechanism","origin":"ai"},{"id":"pharmacodynamic-drug-interactions~ai-3","moduleId":"pharmacodynamic-drug-interactions","stem":"In a patient taking an ACE inhibitor, diuretic, and NSAID, what is the expected clinical finding?","options":[{"id":"a","text":"Increased blood pressure"},{"id":"b","text":"Acute kidney injury"},{"id":"c","text":"Decreased potassium levels"},{"id":"d","text":"Improved renal function"}],"answerId":"b","explanation":"This combination can lead to acute kidney injury due to the additive renal insult, known as the 'triple whammy'.","kind":"recall","origin":"ai"},{"id":"pharmacodynamic-drug-interactions~ai-4","moduleId":"pharmacodynamic-drug-interactions","stem":"Which of the following statements about pharmacodynamic interactions is true?","options":[{"id":"a","text":"They only occur with elevated drug levels."},{"id":"b","text":"They can be lethal even with normal drug levels."},{"id":"c","text":"They always require dose adjustments."},{"id":"d","text":"They are only relevant in elderly patients."}],"answerId":"b","explanation":"Pharmacodynamic interactions can occur at the site of action and can be dangerous even when drug levels are within the therapeutic range.","kind":"trap","origin":"ai"},{"id":"pharmacodynamic-drug-interactions~ai-5","moduleId":"pharmacodynamic-drug-interactions","stem":"A patient with chronic kidney disease is prescribed an ACE inhibitor and a potassium-sparing diuretic. What should be monitored to prevent hyperkalemia?","options":[{"id":"a","text":"Serum creatinine"},{"id":"b","text":"Potassium levels"},{"id":"c","text":"Blood pressure"},{"id":"d","text":"Urine output"}],"answerId":"b","explanation":"Monitoring potassium levels is crucial to prevent hyperkalemia when using these medications together.","kind":"clinical","linkedModuleIds":["drug-dosing-ckd"],"origin":"ai"},{"id":"pharmacodynamic-drug-interactions~ai-6","moduleId":"pharmacodynamic-drug-interactions","stem":"Which combination of medications could lead to torsades de pointes?","options":[{"id":"a","text":"SSRI + SNRI"},{"id":"b","text":"Beta-blocker + beta-agonist"},{"id":"c","text":"Two QT-prolonging drugs"},{"id":"d","text":"ACE inhibitor + diuretic"}],"answerId":"c","explanation":"Combining two QT-prolonging drugs can lead to torsades de pointes due to additive effects on cardiac repolarization.","kind":"integration","linkedModuleIds":["drug-interactions-mechanisms"],"origin":"ai"}],"immunosuppressant-drugs":[{"id":"immunosuppressant-drugs~ai-0","moduleId":"immunosuppressant-drugs","stem":"Which of the following is a common side effect of calcineurin inhibitors like tacrolimus?","options":[{"id":"a","text":"Nephrotoxicity"},{"id":"b","text":"Osteoporosis"},{"id":"c","text":"Hyperglycemia"},{"id":"d","text":"Gum hypertrophy"}],"answerId":"a","explanation":"Tacrolimus is known for causing nephrotoxicity as a dose-limiting side effect.","kind":"recall","origin":"ai"},{"id":"immunosuppressant-drugs~ai-1","moduleId":"immunosuppressant-drugs","stem":"What is the primary mechanism by which glucocorticoids exert their immunosuppressive effects?","options":[{"id":"a","text":"Inhibition of IL-2 production"},{"id":"b","text":"Inhibition of NF-κB"},{"id":"c","text":"Inhibition of T-cell proliferation"},{"id":"d","text":"Inhibition of B-cell activation"}],"answerId":"b","explanation":"Glucocorticoids inhibit NF-κB, leading to decreased cytokine production.","kind":"mechanism","origin":"ai"},{"id":"immunosuppressant-drugs~ai-2","moduleId":"immunosuppressant-drugs","stem":"A patient on azathioprine develops severe myelosuppression. Which genetic factor is most likely responsible?","options":[{"id":"a","text":"High TPMT activity"},{"id":"b","text":"Low TPMT activity"},{"id":"c","text":"CYP3A4 polymorphism"},{"id":"d","text":"MTHFR mutation"}],"answerId":"b","explanation":"Low TPMT activity can lead to increased toxicity from azathioprine due to impaired metabolism.","kind":"recall","origin":"ai"},{"id":"immunosuppressant-drugs~ai-3","moduleId":"immunosuppressant-drugs","stem":"Which of the following immunosuppressants requires therapeutic drug monitoring due to its narrow therapeutic index?","options":[{"id":"a","text":"Azathioprine"},{"id":"b","text":"Ciclosporin"},{"id":"c","text":"Mycophenolate"},{"id":"d","text":"Sirolimus"}],"answerId":"b","explanation":"Ciclosporin has a narrow therapeutic index and requires monitoring to avoid toxicity.","kind":"trap","origin":"ai"},{"id":"immunosuppressant-drugs~ai-4","moduleId":"immunosuppressant-drugs","stem":"What is a potential risk of anti-TNF-α therapy in immunosuppressed patients?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Latent TB reactivation"},{"id":"c","text":"Nephrotoxicity"},{"id":"d","text":"Gum hypertrophy"}],"answerId":"b","explanation":"Anti-TNF-α therapy can reactivate latent TB, necessitating screening before treatment.","kind":"recall","origin":"ai"},{"id":"immunosuppressant-drugs~ai-5","moduleId":"immunosuppressant-drugs","stem":"How does mycophenolate exert its immunosuppressive effects?","options":[{"id":"a","text":"Inhibits IL-2 production"},{"id":"b","text":"Inhibits inosine monophosphate dehydrogenase"},{"id":"c","text":"Inhibits NF-κB"},{"id":"d","text":"Inhibits T-cell activation"}],"answerId":"b","explanation":"Mycophenolate inhibits inosine monophosphate dehydrogenase, blocking lymphocyte purine synthesis.","kind":"mechanism","origin":"ai"},{"id":"immunosuppressant-drugs~ai-6","moduleId":"immunosuppressant-drugs","stem":"In a patient receiving tacrolimus, which drug interaction could increase tacrolimus levels significantly?","options":[{"id":"a","text":"Rifampin"},{"id":"b","text":"Grapefruit juice"},{"id":"c","text":"Azithromycin"},{"id":"d","text":"Omeprazole"}],"answerId":"b","explanation":"Grapefruit juice can inhibit CYP3A4, leading to increased levels of tacrolimus.","kind":"trap","origin":"ai"},{"id":"immunosuppressant-drugs~ai-7","moduleId":"immunosuppressant-drugs","stem":"A patient with a kidney transplant is receiving immunosuppressants. Which linked module's concept is crucial for understanding drug interactions in this context?","options":[{"id":"a","text":"Phototherapy & Systemic Dermatologic Therapy"},{"id":"b","text":"Renal & Urinary Tract Defense Mechanisms"},{"id":"c","text":"Pharmacogenomics"},{"id":"d","text":"Drug Interactions"}],"answerId":"d","explanation":"Understanding drug interactions is vital for managing immunosuppressants in transplant patients.","kind":"integration","linkedModuleIds":["drug-interactions-mechanisms"],"origin":"ai"},{"id":"immunosuppressant-drugs~ai-8","moduleId":"immunosuppressant-drugs","stem":"Which immunosuppressant's mechanism is most relevant for understanding its use in transplant matching?","options":[{"id":"a","text":"Mycophenolate"},{"id":"b","text":"Ciclosporin"},{"id":"c","text":"Azathioprine"},{"id":"d","text":"Sirolimus"}],"answerId":"b","explanation":"Ciclosporin's mechanism of inhibiting IL-2 production is critical for transplant matching and immunosuppression.","kind":"integration","linkedModuleIds":["transplant-matching-immunosuppression"],"origin":"ai"}],"wound-healing":[{"id":"wound-healing~ai-0","moduleId":"wound-healing","stem":"What is the primary mechanism of healing in a clean, sutured surgical wound?","options":[{"id":"a","text":"Granulation tissue formation"},{"id":"b","text":"Secondary intention"},{"id":"c","text":"Primary intention"},{"id":"d","text":"Remodelling phase"}],"answerId":"c","explanation":"Primary intention healing involves the direct apposition of wound edges, leading to faster healing with minimal scarring.","kind":"recall","origin":"ai"},{"id":"wound-healing~ai-1","moduleId":"wound-healing","stem":"Which type of scar is characterized by extending beyond the original wound margins and does not regress?","options":[{"id":"a","text":"Hypertrophic scar"},{"id":"b","text":"Keloid"},{"id":"c","text":"Atrophic scar"},{"id":"d","text":"Contracture"}],"answerId":"b","explanation":"A keloid scar grows beyond the original wound margins and is known for its tendency to recur after excision.","kind":"recall","origin":"ai"},{"id":"wound-healing~ai-2","moduleId":"wound-healing","stem":"What is the main cause of delayed wound healing?","options":[{"id":"a","text":"Poor nutrition"},{"id":"b","text":"Infection"},{"id":"c","text":"Old age"},{"id":"d","text":"Smoking"}],"answerId":"b","explanation":"Infection is the most common cause of delayed healing, often leading to prolonged inflammation and impaired healing processes.","kind":"recall","origin":"ai"},{"id":"wound-healing~ai-3","moduleId":"wound-healing","stem":"During which phase of wound healing do macrophages play a crucial role?","options":[{"id":"a","text":"Haemostasis"},{"id":"b","text":"Inflammation"},{"id":"c","text":"Proliferation"},{"id":"d","text":"Remodelling"}],"answerId":"b","explanation":"Macrophages are key players in the inflammation phase, clearing debris and orchestrating the healing process.","kind":"mechanism","origin":"ai"},{"id":"wound-healing~ai-4","moduleId":"wound-healing","stem":"A patient presents with a chronic non-healing wound on their foot. Which systemic factor is most likely contributing to their impaired healing?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Diabetes"},{"id":"c","text":"Asthma"},{"id":"d","text":"Hyperlipidemia"}],"answerId":"b","explanation":"Diabetes is a significant systemic factor that impairs wound healing due to neuropathy, ischaemia, and increased risk of infection.","kind":"clinical","origin":"ai"},{"id":"wound-healing~ai-5","moduleId":"wound-healing","stem":"What type of healing involves the wound healing from the base up, often seen in large or contaminated wounds?","options":[{"id":"a","text":"Primary intention"},{"id":"b","text":"Secondary intention"},{"id":"c","text":"Tertiary intention"},{"id":"d","text":"Granulation"}],"answerId":"b","explanation":"Secondary intention healing occurs when wounds are left open and heal from the base up through granulation and contraction.","kind":"recall","origin":"ai"},{"id":"wound-healing~ai-6","moduleId":"wound-healing","stem":"How does the healing process of chronic wounds relate to the phases of wound healing?","options":[{"id":"a","text":"They skip the inflammation phase"},{"id":"b","text":"They are stuck in the remodelling phase"},{"id":"c","text":"They are stuck in the inflammation phase"},{"id":"d","text":"They heal by primary intention"}],"answerId":"c","explanation":"Chronic wounds are often stuck in the inflammation phase, preventing progression to proliferation and remodelling.","kind":"integration","linkedModuleIds":["chronic-wounds-leg-ulcers"],"origin":"ai"},{"id":"wound-healing~ai-7","moduleId":"wound-healing","stem":"Which vitamin is essential for collagen cross-linking during the proliferation phase of wound healing?","options":[{"id":"a","text":"Vitamin A"},{"id":"b","text":"Vitamin B12"},{"id":"c","text":"Vitamin C"},{"id":"d","text":"Vitamin D"}],"answerId":"c","explanation":"Vitamin C is crucial for collagen synthesis and cross-linking, which is vital for proper wound healing.","kind":"integration","linkedModuleIds":["skin-anatomy-histology"],"origin":"ai"}],"infestations-helminthic-skin":[{"id":"infestations-helminthic-skin~ai-0","moduleId":"infestations-helminthic-skin","stem":"What is the primary causative agent of scabies?","options":[{"id":"a","text":"Sarcoptes scabiei"},{"id":"b","text":"Pediculus humanus"},{"id":"c","text":"Ancylostoma duodenale"},{"id":"d","text":"Toxocara canis"}],"answerId":"a","explanation":"Scabies is caused by the mite Sarcoptes scabiei, which leads to intense itching and burrows in the skin.","kind":"recall","origin":"ai"},{"id":"infestations-helminthic-skin~ai-1","moduleId":"infestations-helminthic-skin","stem":"Which of the following is a characteristic finding in crusted scabies?","options":[{"id":"a","text":"Burrows in web spaces"},{"id":"b","text":"Thick scaly crusts"},{"id":"c","text":"Nits on hair shafts"},{"id":"d","text":"Serpiginous tracks"}],"answerId":"b","explanation":"Crusted scabies presents with thick scaly crusts teeming with mites, particularly in immunocompromised individuals.","kind":"recall","origin":"ai"},{"id":"infestations-helminthic-skin~ai-2","moduleId":"infestations-helminthic-skin","stem":"What is the recommended treatment for cutaneous larva migrans?","options":[{"id":"a","text":"Permethrin"},{"id":"b","text":"Ivermectin"},{"id":"c","text":"Albendazole"},{"id":"d","text":"Benzyl benzoate"}],"answerId":"c","explanation":"Cutaneous larva migrans is typically treated with albendazole or ivermectin to eliminate the migrating hookworm larvae.","kind":"recall","origin":"ai"},{"id":"infestations-helminthic-skin~ai-3","moduleId":"infestations-helminthic-skin","stem":"Why must all close contacts of a scabies patient be treated simultaneously?","options":[{"id":"a","text":"To prevent secondary infections"},{"id":"b","text":"To avoid re-infestation"},{"id":"c","text":"To reduce itching"},{"id":"d","text":"To ensure quicker recovery"}],"answerId":"b","explanation":"Simultaneous treatment of all close contacts is essential to prevent re-infestation due to the delayed hypersensitivity reaction.","kind":"trap","origin":"ai"},{"id":"infestations-helminthic-skin~ai-4","moduleId":"infestations-helminthic-skin","stem":"A child presents with nits on hair shafts and intense itching. What is the most likely diagnosis?","options":[{"id":"a","text":"Scabies"},{"id":"b","text":"Head lice"},{"id":"c","text":"Crusted scabies"},{"id":"d","text":"Cutaneous larva migrans"}],"answerId":"b","explanation":"Nits on hair shafts are characteristic of head lice (pediculosis capitis), which commonly affects children.","kind":"recall","origin":"ai"},{"id":"infestations-helminthic-skin~ai-5","moduleId":"infestations-helminthic-skin","stem":"A patient presents with an itchy serpiginous track on the foot after beach exposure. What is the most likely cause?","options":[{"id":"a","text":"Scabies"},{"id":"b","text":"Head lice"},{"id":"c","text":"Cutaneous larva migrans"},{"id":"d","text":"Body lice"}],"answerId":"c","explanation":"The serpiginous track is indicative of cutaneous larva migrans caused by animal hookworm larvae.","kind":"recall","origin":"ai"},{"id":"infestations-helminthic-skin~ai-6","moduleId":"infestations-helminthic-skin","stem":"How do anthelmintic agents like ivermectin and albendazole function in treating helminthic infections?","options":[{"id":"a","text":"Inhibit cell wall synthesis"},{"id":"b","text":"Block neuromuscular transmission"},{"id":"c","text":"Disrupt protein synthesis"},{"id":"d","text":"Inhibit nucleic acid synthesis"}],"answerId":"b","explanation":"Ivermectin and albendazole act by blocking neuromuscular transmission in helminths, leading to paralysis and death of the parasites.","kind":"integration","linkedModuleIds":["anthelmintic-agents"],"origin":"ai"},{"id":"infestations-helminthic-skin~ai-7","moduleId":"infestations-helminthic-skin","stem":"Which type of skin infestation is most likely to present with intense nocturnal itching and burrows?","options":[{"id":"a","text":"Head lice"},{"id":"b","text":"Body lice"},{"id":"c","text":"Scabies"},{"id":"d","text":"Cutaneous larva migrans"}],"answerId":"c","explanation":"Scabies is characterized by intense nocturnal itching and the presence of burrows in the skin.","kind":"integration","linkedModuleIds":["scabies-pediculosis-clinical"],"origin":"ai"}],"panniculitis-vasculitis-skin":[{"id":"panniculitis-vasculitis-skin~ai-0","moduleId":"panniculitis-vasculitis-skin","stem":"What is the most common cause of erythema nodosum?","options":[{"id":"a","text":"Streptococcus infection"},{"id":"b","text":"Sarcoidosis"},{"id":"c","text":"Tuberculosis"},{"id":"d","text":"Drug reaction"}],"answerId":"a","explanation":"Erythema nodosum is most commonly associated with Streptococcus infection, among other causes.","kind":"recall","origin":"ai"},{"id":"panniculitis-vasculitis-skin~ai-1","moduleId":"panniculitis-vasculitis-skin","stem":"Which clinical finding is characteristic of cutaneous vasculitis?","options":[{"id":"a","text":"Tender red nodules on the shins"},{"id":"b","text":"Non-blanching raised purpuric papules"},{"id":"c","text":"Flat macular purpura"},{"id":"d","text":"Ulcerated lesions on the legs"}],"answerId":"b","explanation":"Non-blanching raised purpuric papules are indicative of cutaneous vasculitis, distinguishing it from other skin conditions.","kind":"recall","origin":"ai"},{"id":"panniculitis-vasculitis-skin~ai-2","moduleId":"panniculitis-vasculitis-skin","stem":"What mechanism underlies the formation of palpable purpura in cutaneous vasculitis?","options":[{"id":"a","text":"Type I hypersensitivity"},{"id":"b","text":"Type II hypersensitivity"},{"id":"c","text":"Type III hypersensitivity"},{"id":"d","text":"Type IV hypersensitivity"}],"answerId":"c","explanation":"Palpable purpura in cutaneous vasculitis is due to Type III hypersensitivity, involving immune complex deposition.","kind":"mechanism","origin":"ai"},{"id":"panniculitis-vasculitis-skin~ai-3","moduleId":"panniculitis-vasculitis-skin","stem":"A child presents with purpura, arthralgia, abdominal pain, and hematuria. What is the most likely diagnosis?","options":[{"id":"a","text":"Erythema nodosum"},{"id":"b","text":"IgA vasculitis"},{"id":"c","text":"Henoch-Schönlein purpura"},{"id":"d","text":"Cutaneous vasculitis"}],"answerId":"b","explanation":"The combination of symptoms in this child is characteristic of IgA vasculitis (Henoch-Schönlein purpura).","kind":"clinical","origin":"ai"},{"id":"panniculitis-vasculitis-skin~ai-4","moduleId":"panniculitis-vasculitis-skin","stem":"Which statement correctly distinguishes between palpable and non-palpable purpura?","options":[{"id":"a","text":"All purpura indicates a low platelet count"},{"id":"b","text":"Palpable purpura suggests a coagulation disorder"},{"id":"c","text":"Non-palpable purpura indicates vasculitis"},{"id":"d","text":"Palpable purpura implies vasculitis"}],"answerId":"d","explanation":"Palpable purpura indicates vasculitis, while non-palpable purpura suggests a platelet or coagulation disorder.","kind":"trap","origin":"ai"},{"id":"panniculitis-vasculitis-skin~ai-5","moduleId":"panniculitis-vasculitis-skin","stem":"In a patient with erythema nodosum, which investigation is most appropriate to identify the underlying cause?","options":[{"id":"a","text":"Skin biopsy"},{"id":"b","text":"Chest X-ray"},{"id":"c","text":"Complete blood count"},{"id":"d","text":"Urinalysis"}],"answerId":"b","explanation":"A chest X-ray is appropriate to check for sarcoidosis or tuberculosis, common triggers of erythema nodosum.","kind":"clinical","origin":"ai"},{"id":"panniculitis-vasculitis-skin~ai-6","moduleId":"panniculitis-vasculitis-skin","stem":"How does the mechanism of cutaneous vasculitis relate to hypersensitivity reactions?","options":[{"id":"a","text":"It is a Type I hypersensitivity reaction"},{"id":"b","text":"It involves immune complex deposition (Type III)"},{"id":"c","text":"It is a delayed-type hypersensitivity (Type IV)"},{"id":"d","text":"It is an autoimmune response (Type II)"}],"answerId":"b","explanation":"Cutaneous vasculitis is characterized by immune complex deposition, which is a hallmark of Type III hypersensitivity reactions.","kind":"integration","linkedModuleIds":["cutaneous-immunology-hypersensitivity"],"origin":"ai"},{"id":"panniculitis-vasculitis-skin~ai-7","moduleId":"panniculitis-vasculitis-skin","stem":"What anatomical structure is primarily affected in panniculitis?","options":[{"id":"a","text":"Epidermis"},{"id":"b","text":"Dermis"},{"id":"c","text":"Subcutaneous fat"},{"id":"d","text":"Blood vessels"}],"answerId":"c","explanation":"Panniculitis specifically involves inflammation of the subcutaneous fat layer.","kind":"integration","linkedModuleIds":["skin-anatomy-histology"],"origin":"ai"}],"cutaneous-drug-reactions":[{"id":"cutaneous-drug-reactions~ai-0","moduleId":"cutaneous-drug-reactions","stem":"What is the most common type of cutaneous drug reaction?","options":[{"id":"a","text":"Urticaria"},{"id":"b","text":"Morbilliform eruption"},{"id":"c","text":"Fixed drug eruption"},{"id":"d","text":"Stevens-Johnson syndrome"}],"answerId":"b","explanation":"The morbilliform eruption is the most common type of cutaneous drug reaction, typically appearing 4-14 days after drug initiation.","kind":"recall","origin":"ai"},{"id":"cutaneous-drug-reactions~ai-1","moduleId":"cutaneous-drug-reactions","stem":"Which of the following is a characteristic finding in Stevens-Johnson syndrome?","options":[{"id":"a","text":"Symmetric pink macules"},{"id":"b","text":"Facial edema"},{"id":"c","text":"Positive Nikolsky sign"},{"id":"d","text":"Eosinophilia"}],"answerId":"c","explanation":"A positive Nikolsky sign indicates epidermal detachment, which is a hallmark of Stevens-Johnson syndrome.","kind":"recall","origin":"ai"},{"id":"cutaneous-drug-reactions~ai-2","moduleId":"cutaneous-drug-reactions","stem":"What mechanism underlies the morbilliform drug eruption?","options":[{"id":"a","text":"Type I hypersensitivity"},{"id":"b","text":"Type II hypersensitivity"},{"id":"c","text":"Type IV hypersensitivity"},{"id":"d","text":"Autoimmune reaction"}],"answerId":"c","explanation":"Morbilliform eruptions are mediated by Type IV hypersensitivity reactions.","kind":"mechanism","origin":"ai"},{"id":"cutaneous-drug-reactions~ai-3","moduleId":"cutaneous-drug-reactions","stem":"A patient presents with a dusky patch that recurs at the same site after taking a medication. What is the likely diagnosis?","options":[{"id":"a","text":"Morbilliform eruption"},{"id":"b","text":"Fixed drug eruption"},{"id":"c","text":"DRESS syndrome"},{"id":"d","text":"Urticaria"}],"answerId":"b","explanation":"A fixed drug eruption is characterized by a round dusky patch that recurs at the same site with each exposure to the drug.","kind":"clinical","origin":"ai"},{"id":"cutaneous-drug-reactions~ai-4","moduleId":"cutaneous-drug-reactions","stem":"Which of the following findings would indicate a severe cutaneous adverse reaction (SCAR)?","options":[{"id":"a","text":"Morbilliform rash without systemic symptoms"},{"id":"b","text":"Fever and lymphadenopathy"},{"id":"c","text":"Mild pruritus"},{"id":"d","text":"Localized rash without mucosal involvement"}],"answerId":"b","explanation":"Fever and lymphadenopathy are red flags indicating a potential SCAR, necessitating immediate drug cessation.","kind":"trap","origin":"ai"},{"id":"cutaneous-drug-reactions~ai-5","moduleId":"cutaneous-drug-reactions","stem":"A patient develops a widespread rash, fever, and eosinophilia 4 weeks after starting a new anticonvulsant. What condition is most likely?","options":[{"id":"a","text":"Morbilliform eruption"},{"id":"b","text":"Fixed drug eruption"},{"id":"c","text":"DRESS syndrome"},{"id":"d","text":"Stevens-Johnson syndrome"}],"answerId":"c","explanation":"DRESS syndrome typically presents 2-8 weeks after drug exposure with a combination of rash, fever, eosinophilia, and systemic involvement.","kind":"clinical","origin":"ai"},{"id":"cutaneous-drug-reactions~ai-6","moduleId":"cutaneous-drug-reactions","stem":"How does the mechanism of DRESS syndrome differ from that of Stevens-Johnson syndrome?","options":[{"id":"a","text":"DRESS is Type I, SJS is Type IV"},{"id":"b","text":"DRESS has delayed onset, SJS is immediate"},{"id":"c","text":"DRESS involves mucosal surfaces, SJS does not"},{"id":"d","text":"DRESS is always fatal, SJS is not"}],"answerId":"b","explanation":"DRESS syndrome has a delayed onset (2-8 weeks) compared to the more immediate onset of Stevens-Johnson syndrome.","kind":"integration","linkedModuleIds":["drug-hypersensitivity-scars"],"origin":"ai"},{"id":"cutaneous-drug-reactions~ai-7","moduleId":"cutaneous-drug-reactions","stem":"Which of the following drug reactions is most likely to require HLA screening to prevent severe outcomes?","options":[{"id":"a","text":"Morbilliform eruption"},{"id":"b","text":"Urticaria"},{"id":"c","text":"Stevens-Johnson syndrome"},{"id":"d","text":"Fixed drug eruption"}],"answerId":"c","explanation":"Stevens-Johnson syndrome is associated with specific HLA alleles, and screening can help prevent severe reactions.","kind":"integration","linkedModuleIds":["adverse-drug-reactions-allergy"],"origin":"ai"}],"cutaneous-immunology-hypersensitivity":[{"id":"cutaneous-immunology-hypersensitivity~ai-0","moduleId":"cutaneous-immunology-hypersensitivity","stem":"What is the primary mechanism underlying Type I hypersensitivity reactions?","options":[{"id":"a","text":"IgG-mediated immune complexes"},{"id":"b","text":"T-cell activation"},{"id":"c","text":"IgE and mast cell degranulation"},{"id":"d","text":"Complement activation"}],"answerId":"c","explanation":"Type I hypersensitivity involves IgE antibodies binding to allergens, leading to mast cell degranulation and histamine release.","kind":"mechanism","origin":"ai"},{"id":"cutaneous-immunology-hypersensitivity~ai-1","moduleId":"cutaneous-immunology-hypersensitivity","stem":"A patient presents with itchy dermatitis at a nickel-contact site and a positive patch test. What is the most likely diagnosis?","options":[{"id":"a","text":"Irritant contact dermatitis"},{"id":"b","text":"Allergic contact dermatitis"},{"id":"c","text":"Atopic dermatitis"},{"id":"d","text":"Urticaria"}],"answerId":"b","explanation":"The positive patch test indicates a delayed-type hypersensitivity reaction, characteristic of allergic contact dermatitis.","kind":"clinical","origin":"ai"},{"id":"cutaneous-immunology-hypersensitivity~ai-2","moduleId":"cutaneous-immunology-hypersensitivity","stem":"Which finding is characteristic of leukocytoclastic vasculitis?","options":[{"id":"a","text":"Transient wheals"},{"id":"b","text":"Palpable purpura"},{"id":"c","text":"Blisters"},{"id":"d","text":"Erythema nodosum"}],"answerId":"b","explanation":"Leukocytoclastic vasculitis typically presents with palpable purpura due to immune complex deposition in small vessels.","kind":"recall","origin":"ai"},{"id":"cutaneous-immunology-hypersensitivity~ai-3","moduleId":"cutaneous-immunology-hypersensitivity","stem":"What distinguishes irritant contact dermatitis from allergic contact dermatitis?","options":[{"id":"a","text":"Requires prior sensitization"},{"id":"b","text":"Is mediated by IgE"},{"id":"c","text":"Is a non-immune reaction"},{"id":"d","text":"Always presents with wheals"}],"answerId":"c","explanation":"Irritant contact dermatitis is a non-immune reaction caused by direct damage, while allergic contact dermatitis requires prior sensitization.","kind":"trap","origin":"ai"},{"id":"cutaneous-immunology-hypersensitivity~ai-4","moduleId":"cutaneous-immunology-hypersensitivity","stem":"In a patient with pemphigus vulgaris, which immunological mechanism is primarily involved?","options":[{"id":"a","text":"IgE-mediated mast cell degranulation"},{"id":"b","text":"T-cell mediated cytotoxicity"},{"id":"c","text":"IgG antibodies against adhesion molecules"},{"id":"d","text":"Immune complex deposition"}],"answerId":"c","explanation":"Pemphigus vulgaris is characterized by IgG antibodies targeting desmosomal proteins, leading to blister formation.","kind":"mechanism","origin":"ai"},{"id":"cutaneous-immunology-hypersensitivity~ai-5","moduleId":"cutaneous-immunology-hypersensitivity","stem":"A patient develops a rash after starting a new medication. Which type of hypersensitivity reaction is most likely if the rash appears after 48 hours?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"d","explanation":"A rash appearing 48 hours after exposure suggests a Type IV hypersensitivity reaction, which is T-cell mediated.","kind":"clinical","origin":"ai"},{"id":"cutaneous-immunology-hypersensitivity~ai-6","moduleId":"cutaneous-immunology-hypersensitivity","stem":"How does allergic contact dermatitis differ from eczema in terms of pathophysiology?","options":[{"id":"a","text":"Both are IgE mediated"},{"id":"b","text":"Eczema is primarily a Type IV reaction"},{"id":"c","text":"Allergic contact dermatitis requires prior sensitization"},{"id":"d","text":"Eczema is always due to an external allergen"}],"answerId":"c","explanation":"Allergic contact dermatitis is a Type IV hypersensitivity that requires prior sensitization, while eczema can have various underlying causes.","kind":"integration","linkedModuleIds":["eczema-dermatitis"],"origin":"ai"},{"id":"cutaneous-immunology-hypersensitivity~ai-7","moduleId":"cutaneous-immunology-hypersensitivity","stem":"What is a common feature of both cutaneous drug reactions and allergic contact dermatitis?","options":[{"id":"a","text":"IgE involvement"},{"id":"b","text":"Delayed hypersensitivity"},{"id":"c","text":"Immediate hypersensitivity"},{"id":"d","text":"Direct cytotoxicity"}],"answerId":"b","explanation":"Both cutaneous drug reactions and allergic contact dermatitis can involve delayed-type hypersensitivity mechanisms.","kind":"integration","linkedModuleIds":["cutaneous-drug-reactions"],"origin":"ai"}],"papulosquamous-diseases":[{"id":"papulosquamous-diseases~ai-0","moduleId":"papulosquamous-diseases","stem":"Which of the following is a characteristic finding in psoriasis?","options":[{"id":"a","text":"Silvery-scaled plaques on extensor surfaces"},{"id":"b","text":"Greasy scale on the scalp"},{"id":"c","text":"Lacy white lines on papules"},{"id":"d","text":"Herald patch followed by oval plaques"}],"answerId":"a","explanation":"Psoriasis is characterized by silvery-scaled plaques primarily located on extensor surfaces.","kind":"recall","origin":"ai"},{"id":"papulosquamous-diseases~ai-1","moduleId":"papulosquamous-diseases","stem":"What is the mechanism behind the Auspitz sign in psoriasis?","options":[{"id":"a","text":"Increased keratinocyte turnover"},{"id":"b","text":"Vasodilation of dermal vessels"},{"id":"c","text":"Immune-mediated inflammation"},{"id":"d","text":"Fungal infection"}],"answerId":"a","explanation":"The Auspitz sign occurs due to increased keratinocyte turnover leading to pinpoint bleeding when scales are removed.","kind":"mechanism","origin":"ai"},{"id":"papulosquamous-diseases~ai-2","moduleId":"papulosquamous-diseases","stem":"A patient presents with violaceous flat-topped papules with lacy white lines on the wrists. What is the most likely diagnosis?","options":[{"id":"a","text":"Psoriasis"},{"id":"b","text":"Pityriasis rosea"},{"id":"c","text":"Lichen planus"},{"id":"d","text":"Seborrheic dermatitis"}],"answerId":"c","explanation":"The described features are characteristic of lichen planus, which presents with the '6 P's' and Wickham striae.","kind":"clinical","origin":"ai"},{"id":"papulosquamous-diseases~ai-3","moduleId":"papulosquamous-diseases","stem":"A 30-year-old male develops new psoriatic lesions at the site of a recent scratch. What phenomenon does this illustrate?","options":[{"id":"a","text":"Auspitz sign"},{"id":"b","text":"Koebner phenomenon"},{"id":"c","text":"Nail pitting"},{"id":"d","text":"Herald patch"}],"answerId":"b","explanation":"The development of new lesions at sites of trauma is known as the Koebner phenomenon.","kind":"clinical","origin":"ai"},{"id":"papulosquamous-diseases~ai-4","moduleId":"papulosquamous-diseases","stem":"Which of the following statements correctly distinguishes psoriasis from eczema?","options":[{"id":"a","text":"Psoriasis affects flexural surfaces"},{"id":"b","text":"Eczema has silvery scales"},{"id":"c","text":"Psoriasis presents with sharply demarcated plaques"},{"id":"d","text":"Eczema is associated with nail pitting"}],"answerId":"c","explanation":"Psoriasis is characterized by sharply demarcated plaques, while eczema typically affects flexural surfaces and presents with weepy lesions.","kind":"trap","origin":"ai"},{"id":"papulosquamous-diseases~ai-5","moduleId":"papulosquamous-diseases","stem":"A patient has a herald patch followed by a Christmas-tree pattern rash. What is the most likely diagnosis?","options":[{"id":"a","text":"Psoriasis"},{"id":"b","text":"Pityriasis rosea"},{"id":"c","text":"Lichen planus"},{"id":"d","text":"Seborrheic dermatitis"}],"answerId":"b","explanation":"The herald patch followed by a Christmas-tree pattern is classic for pityriasis rosea.","kind":"recall","origin":"ai"},{"id":"papulosquamous-diseases~ai-6","moduleId":"papulosquamous-diseases","stem":"How does psoriasis relate to cutaneous immunology and hypersensitivity?","options":[{"id":"a","text":"It is primarily a fungal infection"},{"id":"b","text":"It involves Th17-mediated immune response"},{"id":"c","text":"It is caused by viral agents"},{"id":"d","text":"It is an allergic reaction"}],"answerId":"b","explanation":"Psoriasis is an immune-mediated condition involving a Th17 response, linking it to cutaneous immunology.","kind":"integration","linkedModuleIds":["cutaneous-immunology-hypersensitivity"],"origin":"ai"},{"id":"papulosquamous-diseases~ai-7","moduleId":"papulosquamous-diseases","stem":"What is the first-line treatment for extensive psoriasis?","options":[{"id":"a","text":"Topical corticosteroids"},{"id":"b","text":"Phototherapy"},{"id":"c","text":"Systemic methotrexate"},{"id":"d","text":"Reassurance"}],"answerId":"b","explanation":"For extensive psoriasis, phototherapy is often the first-line treatment after topical agents.","kind":"integration","linkedModuleIds":["dermatologic-therapy"],"origin":"ai"}],"skin-physiology-thermoregulation":[{"id":"skin-physiology-thermoregulation~ai-0","moduleId":"skin-physiology-thermoregulation","stem":"What is the primary function of the stratum corneum in the skin?","options":[{"id":"a","text":"Thermoregulation"},{"id":"b","text":"Sensation"},{"id":"c","text":"Barrier against water loss"},{"id":"d","text":"Vitamin D synthesis"}],"answerId":"c","explanation":"The stratum corneum serves as the primary barrier against water loss and entry of pathogens.","kind":"recall","origin":"ai"},{"id":"skin-physiology-thermoregulation~ai-1","moduleId":"skin-physiology-thermoregulation","stem":"Which mechanism primarily regulates heat loss through the skin?","options":[{"id":"a","text":"Cutaneous vasoconstriction"},{"id":"b","text":"Eccrine sweating"},{"id":"c","text":"Piloerection"},{"id":"d","text":"Increased metabolic rate"}],"answerId":"b","explanation":"Eccrine sweating is the primary mechanism for heat loss through evaporative cooling.","kind":"mechanism","origin":"ai"},{"id":"skin-physiology-thermoregulation~ai-2","moduleId":"skin-physiology-thermoregulation","stem":"A patient presents with dry, itchy skin and increased transepidermal water loss. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Increased eccrine sweating"},{"id":"b","text":"Barrier dysfunction"},{"id":"c","text":"Vasoconstriction"},{"id":"d","text":"Vitamin D deficiency"}],"answerId":"b","explanation":"Dry, itchy skin with increased transepidermal water loss indicates a barrier dysfunction, often seen in conditions like eczema.","kind":"clinical","origin":"ai"},{"id":"skin-physiology-thermoregulation~ai-3","moduleId":"skin-physiology-thermoregulation","stem":"What is the effect of antimuscarinic drugs on eccrine sweat glands?","options":[{"id":"a","text":"Increase sweating"},{"id":"b","text":"Block sweating"},{"id":"c","text":"No effect on sweating"},{"id":"d","text":"Enhance vasodilation"}],"answerId":"b","explanation":"Antimuscarinic drugs block the action of acetylcholine on eccrine sweat glands, leading to reduced sweating.","kind":"trap","origin":"ai"},{"id":"skin-physiology-thermoregulation~ai-4","moduleId":"skin-physiology-thermoregulation","stem":"Which of the following is a consequence of cutaneous vasodilation?","options":[{"id":"a","text":"Increased blood pressure"},{"id":"b","text":"Heat conservation"},{"id":"c","text":"Increased heat loss"},{"id":"d","text":"Decreased skin temperature"}],"answerId":"c","explanation":"Cutaneous vasodilation increases blood flow to the skin, facilitating heat loss through radiation and evaporation.","kind":"mechanism","origin":"ai"},{"id":"skin-physiology-thermoregulation~ai-5","moduleId":"skin-physiology-thermoregulation","stem":"How does vitamin D synthesis in the skin primarily occur?","options":[{"id":"a","text":"Through dietary intake"},{"id":"b","text":"UVB exposure converting 7-dehydrocholesterol"},{"id":"c","text":"From sunlight exposure to cholecalciferol"},{"id":"d","text":"By hydroxylation in the liver"}],"answerId":"b","explanation":"Vitamin D synthesis in the skin occurs when UVB light converts 7-dehydrocholesterol into cholecalciferol.","kind":"recall","origin":"ai"},{"id":"skin-physiology-thermoregulation~ai-6","moduleId":"skin-physiology-thermoregulation","stem":"How does the autonomic nervous system influence eccrine sweating?","options":[{"id":"a","text":"Through adrenergic receptors"},{"id":"b","text":"Via sympathetic cholinergic pathways"},{"id":"c","text":"By parasympathetic stimulation"},{"id":"d","text":"Through somatic motor control"}],"answerId":"b","explanation":"Eccrine sweat glands are innervated by the sympathetic nervous system but utilize acetylcholine as the neurotransmitter, making it a sympathetic cholinergic pathway.","kind":"integration","linkedModuleIds":["autonomic-nervous-system"],"origin":"ai"},{"id":"skin-physiology-thermoregulation~ai-7","moduleId":"skin-physiology-thermoregulation","stem":"What is the relationship between skin barrier dysfunction and eczema?","options":[{"id":"a","text":"Eczema is caused by excessive sweating"},{"id":"b","text":"Eczema results from vitamin D deficiency"},{"id":"c","text":"Eczema is linked to barrier dysfunction in the stratum corneum"},{"id":"d","text":"Eczema is unrelated to skin physiology"}],"answerId":"c","explanation":"Eczema is characterized by barrier dysfunction in the stratum corneum, leading to increased transepidermal water loss and susceptibility to irritants.","kind":"integration","linkedModuleIds":["eczema-dermatitis"],"origin":"ai"}],"cutaneous-connective-tissue-diseases":[{"id":"cutaneous-connective-tissue-diseases~ai-0","moduleId":"cutaneous-connective-tissue-diseases","stem":"What skin finding is characteristic of acute cutaneous lupus erythematosus?","options":[{"id":"a","text":"Scarring disc plaques"},{"id":"b","text":"Heliotrope rash"},{"id":"c","text":"Malar rash sparing nasolabial folds"},{"id":"d","text":"Sclerotic skin with Raynaud"}],"answerId":"c","explanation":"The malar rash is a classic presentation of acute cutaneous lupus erythematosus, distinguishing it from other forms.","kind":"recall","origin":"ai"},{"id":"cutaneous-connective-tissue-diseases~ai-1","moduleId":"cutaneous-connective-tissue-diseases","stem":"Which autoantibody is commonly associated with systemic sclerosis (scleroderma)?","options":[{"id":"a","text":"Anti-Ro"},{"id":"b","text":"Anti-Scl-70"},{"id":"c","text":"Anti-dsDNA"},{"id":"d","text":"Anti-Jo-1"}],"answerId":"b","explanation":"Anti-Scl-70 is a marker for diffuse scleroderma, while anti-centromere is associated with limited scleroderma.","kind":"recall","origin":"ai"},{"id":"cutaneous-connective-tissue-diseases~ai-2","moduleId":"cutaneous-connective-tissue-diseases","stem":"In dermatomyositis, which skin manifestation is considered pathognomonic?","options":[{"id":"a","text":"Malar rash"},{"id":"b","text":"Gottron papules"},{"id":"c","text":"Sclerodactyly"},{"id":"d","text":"Telangiectasia"}],"answerId":"b","explanation":"Gottron papules are specific to dermatomyositis and indicate the presence of the disease.","kind":"recall","origin":"ai"},{"id":"cutaneous-connective-tissue-diseases~ai-3","moduleId":"cutaneous-connective-tissue-diseases","stem":"What is the primary mechanism behind the photosensitivity seen in lupus erythematosus?","options":[{"id":"a","text":"Immune complex deposition"},{"id":"b","text":"UV-induced apoptosis"},{"id":"c","text":"Fibroblast activation"},{"id":"d","text":"Vascular inflammation"}],"answerId":"b","explanation":"Photosensitivity in lupus is due to UV-induced apoptosis of keratinocytes, triggering an immune response.","kind":"mechanism","origin":"ai"},{"id":"cutaneous-connective-tissue-diseases~ai-4","moduleId":"cutaneous-connective-tissue-diseases","stem":"What is the first clinical sign often seen in systemic sclerosis?","options":[{"id":"a","text":"Heliotrope rash"},{"id":"b","text":"Raynaud phenomenon"},{"id":"c","text":"Malar rash"},{"id":"d","text":"Gottron papules"}],"answerId":"b","explanation":"Raynaud phenomenon is frequently the first sign of systemic sclerosis, indicating vascular involvement.","kind":"recall","origin":"ai"},{"id":"cutaneous-connective-tissue-diseases~ai-5","moduleId":"cutaneous-connective-tissue-diseases","stem":"Why is cancer screening crucial in adult dermatomyositis?","options":[{"id":"a","text":"It is primarily a skin disease"},{"id":"b","text":"It has a low association with malignancy"},{"id":"c","text":"It can be a paraneoplastic syndrome"},{"id":"d","text":"It only affects muscle function"}],"answerId":"c","explanation":"Adult dermatomyositis can indicate an underlying malignancy, necessitating thorough cancer screening.","kind":"trap","origin":"ai"},{"id":"cutaneous-connective-tissue-diseases~ai-6","moduleId":"cutaneous-connective-tissue-diseases","stem":"Which skin finding is indicative of morphea?","options":[{"id":"a","text":"Tight, sclerotic skin"},{"id":"b","text":"Photosensitive rash"},{"id":"c","text":"Localized sclerotic skin plaque"},{"id":"d","text":"Violaceous eyelid rash"}],"answerId":"c","explanation":"Morphea presents as localized sclerotic plaques without systemic involvement, differentiating it from other conditions.","kind":"recall","origin":"ai"},{"id":"cutaneous-connective-tissue-diseases~ai-7","moduleId":"cutaneous-connective-tissue-diseases","stem":"How does dermatomyositis relate to connective tissue diseases?","options":[{"id":"a","text":"It is a purely dermatological condition"},{"id":"b","text":"It has no systemic implications"},{"id":"c","text":"It can indicate underlying malignancy"},{"id":"d","text":"It is unrelated to autoimmune processes"}],"answerId":"c","explanation":"Dermatomyositis is associated with underlying malignancies, highlighting its systemic implications within connective tissue diseases.","kind":"integration","linkedModuleIds":["cutaneous-lupus-dermatomyositis"],"origin":"ai"},{"id":"cutaneous-connective-tissue-diseases~ai-8","moduleId":"cutaneous-connective-tissue-diseases","stem":"What is a common treatment approach for photosensitive lupus?","options":[{"id":"a","text":"Topical steroids"},{"id":"b","text":"Systemic immunosuppression"},{"id":"c","text":"Photoprotection"},{"id":"d","text":"Antibiotics"}],"answerId":"c","explanation":"Photoprotection is essential in managing photosensitive lupus to prevent exacerbation of skin lesions.","kind":"integration","linkedModuleIds":["dermatologic-therapy"],"origin":"ai"}],"pediatric-skin-diseases":[{"id":"pediatric-skin-diseases~ai-0","moduleId":"pediatric-skin-diseases","stem":"What is the most common childhood inflammatory skin disease characterized by itchy dermatitis in flexural areas?","options":[{"id":"a","text":"Seborrheic dermatitis"},{"id":"b","text":"Atopic dermatitis"},{"id":"c","text":"Impetigo"},{"id":"d","text":"Tinea capitis"}],"answerId":"b","explanation":"Atopic dermatitis is the most prevalent inflammatory skin condition in children, often presenting in flexural areas.","kind":"recall","origin":"ai"},{"id":"pediatric-skin-diseases~ai-1","moduleId":"pediatric-skin-diseases","stem":"Which viral exanthem presents with high fever followed by a rash as the fever resolves?","options":[{"id":"a","text":"Measles"},{"id":"b","text":"Rubella"},{"id":"c","text":"Roseola"},{"id":"d","text":"Erythema infectiosum"}],"answerId":"c","explanation":"Roseola, caused by HHV-6, is characterized by high fever followed by a rash once the fever subsides.","kind":"recall","origin":"ai"},{"id":"pediatric-skin-diseases~ai-2","moduleId":"pediatric-skin-diseases","stem":"A child presents with bright red, 'slapped cheek' erythema. Which condition is most likely?","options":[{"id":"a","text":"Chickenpox"},{"id":"b","text":"Erythema infectiosum"},{"id":"c","text":"Hand-foot-and-mouth disease"},{"id":"d","text":"Atopic dermatitis"}],"answerId":"b","explanation":"Bright red, 'slapped cheek' erythema is characteristic of erythema infectiosum caused by parvovirus B19.","kind":"clinical","origin":"ai"},{"id":"pediatric-skin-diseases~ai-3","moduleId":"pediatric-skin-diseases","stem":"What is the key distinguishing feature of an infantile hemangioma compared to a port-wine stain?","options":[{"id":"a","text":"Presence at birth"},{"id":"b","text":"Involutes over time"},{"id":"c","text":"Requires immediate treatment"},{"id":"d","text":"Flat appearance"}],"answerId":"b","explanation":"Infantile hemangiomas typically appear after birth and involute over time, unlike port-wine stains which are present at birth and persist.","kind":"trap","origin":"ai"},{"id":"pediatric-skin-diseases~ai-4","moduleId":"pediatric-skin-diseases","stem":"A 2-year-old child has a persistent flat port-wine stain on the face. What should be considered?","options":[{"id":"a","text":"Sturge-Weber syndrome"},{"id":"b","text":"Neurofibromatosis"},{"id":"c","text":"Eczema"},{"id":"d","text":"Impetigo"}],"answerId":"a","explanation":"A port-wine stain in the V1 trigeminal area warrants evaluation for Sturge-Weber syndrome.","kind":"clinical","origin":"ai"},{"id":"pediatric-skin-diseases~ai-5","moduleId":"pediatric-skin-diseases","stem":"Which condition requires oral antifungal treatment in children?","options":[{"id":"a","text":"Scabies"},{"id":"b","text":"Tinea capitis"},{"id":"c","text":"Impetigo"},{"id":"d","text":"Atopic dermatitis"}],"answerId":"b","explanation":"Tinea capitis, or scalp ringworm, necessitates oral antifungal therapy for effective treatment.","kind":"recall","origin":"ai"},{"id":"pediatric-skin-diseases~ai-6","moduleId":"pediatric-skin-diseases","stem":"How does atopic dermatitis relate to the atopic march?","options":[{"id":"a","text":"It is the first manifestation"},{"id":"b","text":"It only occurs in infants"},{"id":"c","text":"It is unrelated to asthma"},{"id":"d","text":"It resolves without treatment"}],"answerId":"a","explanation":"Atopic dermatitis is often the first manifestation in the atopic march, which may progress to asthma and allergic rhinitis.","kind":"integration","linkedModuleIds":["eczema-dermatitis"],"origin":"ai"},{"id":"pediatric-skin-diseases~ai-7","moduleId":"pediatric-skin-diseases","stem":"What is the mechanism of action of propranolol in treating problematic infantile hemangiomas?","options":[{"id":"a","text":"Inhibits viral replication"},{"id":"b","text":"Reduces vascular proliferation"},{"id":"c","text":"Enhances immune response"},{"id":"d","text":"Increases blood flow"}],"answerId":"b","explanation":"Propranolol reduces vascular proliferation, which helps in treating problematic infantile hemangiomas.","kind":"mechanism","origin":"ai"},{"id":"pediatric-skin-diseases~ai-8","moduleId":"pediatric-skin-diseases","stem":"Which condition is characterized by a honey crusted appearance on the skin?","options":[{"id":"a","text":"Impetigo"},{"id":"b","text":"Scabies"},{"id":"c","text":"Tinea capitis"},{"id":"d","text":"Erythema infectiosum"}],"answerId":"a","explanation":"Impetigo is characterized by honey-crusted lesions, typically due to bacterial infection.","kind":"recall","origin":"ai"}],"hair-diseases":[{"id":"hair-diseases~ai-0","moduleId":"hair-diseases","stem":"What is the primary mechanism behind androgenetic alopecia?","options":[{"id":"a","text":"Follicular destruction"},{"id":"b","text":"DHT-mediated follicular miniaturization"},{"id":"c","text":"T-cell mediated attack"},{"id":"d","text":"Stress-induced hair shedding"}],"answerId":"b","explanation":"Androgenetic alopecia is primarily caused by DHT-mediated follicular miniaturization, leading to hair thinning.","kind":"mechanism","origin":"ai"},{"id":"hair-diseases~ai-1","moduleId":"hair-diseases","stem":"Which finding is characteristic of alopecia areata?","options":[{"id":"a","text":"Bitemporal recession"},{"id":"b","text":"Smooth round bald patches with exclamation-mark hairs"},{"id":"c","text":"Diffuse hair shedding"},{"id":"d","text":"Scaly scalp patches with broken hairs"}],"answerId":"b","explanation":"Alopecia areata is characterized by smooth round bald patches and the presence of exclamation-mark hairs.","kind":"recall","origin":"ai"},{"id":"hair-diseases~ai-2","moduleId":"hair-diseases","stem":"Which type of alopecia is associated with permanent hair loss due to follicular destruction?","options":[{"id":"a","text":"Telogen effluvium"},{"id":"b","text":"Androgenetic alopecia"},{"id":"c","text":"Alopecia areata"},{"id":"d","text":"Cicatricial alopecia"}],"answerId":"d","explanation":"Cicatricial alopecia leads to permanent hair loss due to the destruction of hair follicles.","kind":"recall","origin":"ai"},{"id":"hair-diseases~ai-3","moduleId":"hair-diseases","stem":"A 30-year-old woman presents with diffuse hair shedding 2 months after childbirth. What is the most likely diagnosis?","options":[{"id":"a","text":"Alopecia areata"},{"id":"b","text":"Telogen effluvium"},{"id":"c","text":"Androgenetic alopecia"},{"id":"d","text":"Cicatricial alopecia"}],"answerId":"b","explanation":"Telogen effluvium is characterized by diffuse hair shedding following a stressor such as childbirth.","kind":"clinical","origin":"ai"},{"id":"hair-diseases~ai-4","moduleId":"hair-diseases","stem":"What is the primary treatment for tinea capitis?","options":[{"id":"a","text":"Topical antifungal"},{"id":"b","text":"Oral antifungal"},{"id":"c","text":"Minoxidil"},{"id":"d","text":"Finasteride"}],"answerId":"b","explanation":"Tinea capitis requires oral antifungal treatment due to its fungal nature and the need for systemic therapy.","kind":"recall","origin":"ai"},{"id":"hair-diseases~ai-5","moduleId":"hair-diseases","stem":"Which condition is characterized by loss of follicular openings and requires early biopsy for treatment?","options":[{"id":"a","text":"Androgenetic alopecia"},{"id":"b","text":"Alopecia areata"},{"id":"c","text":"Cicatricial alopecia"},{"id":"d","text":"Telogen effluvium"}],"answerId":"c","explanation":"Cicatricial alopecia is characterized by loss of follicular openings and necessitates early biopsy to preserve remaining follicles.","kind":"trap","origin":"ai"},{"id":"hair-diseases~ai-6","moduleId":"hair-diseases","stem":"How does cicatricial alopecia differ from non-scarring alopecia in terms of follicle preservation?","options":[{"id":"a","text":"Follicles are preserved in cicatricial alopecia"},{"id":"b","text":"Non-scarring alopecia destroys follicles"},{"id":"c","text":"Cicatricial alopecia leads to irreversible follicle loss"},{"id":"d","text":"Non-scarring alopecia is always permanent"}],"answerId":"c","explanation":"Cicatricial alopecia results in irreversible follicle loss, while non-scarring alopecia preserves follicles and can potentially regrow hair.","kind":"trap","origin":"ai"},{"id":"hair-diseases~ai-7","moduleId":"hair-diseases","stem":"A patient with discoid lupus erythematosus presents with hair loss. Which linked condition should be considered in diagnosis?","options":[{"id":"a","text":"Alopecia areata"},{"id":"b","text":"Cicatricial alopecia"},{"id":"c","text":"Tinea capitis"},{"id":"d","text":"Androgenetic alopecia"}],"answerId":"b","explanation":"Discoid lupus erythematosus is a type of cicatricial alopecia, which can cause permanent hair loss due to follicular destruction.","kind":"integration","linkedModuleIds":["cutaneous-connective-tissue-diseases"],"origin":"ai"},{"id":"hair-diseases~ai-8","moduleId":"hair-diseases","stem":"Which module's content is essential for understanding the histological basis of hair diseases?","options":[{"id":"a","text":"Skin Anatomy & Histology"},{"id":"b","text":"Clinical Approach to Alopecia"},{"id":"c","text":"Dermis, Appendages & Skin Glands"},{"id":"d","text":"Cutaneous Connective Tissue Diseases"}],"answerId":"a","explanation":"The Skin Anatomy & Histology module provides essential knowledge about the structure of hair follicles and their diseases.","kind":"integration","linkedModuleIds":["skin-anatomy-histology"],"origin":"ai"}],"skin-infections-bacterial-fungal-viral":[{"id":"skin-infections-bacterial-fungal-viral~ai-0","moduleId":"skin-infections-bacterial-fungal-viral","stem":"What is the most common causative organism of impetigo?","options":[{"id":"a","text":"Escherichia coli"},{"id":"b","text":"Staphylococcus aureus"},{"id":"c","text":"Pseudomonas aeruginosa"},{"id":"d","text":"Candida albicans"}],"answerId":"b","explanation":"Impetigo is primarily caused by Staphylococcus aureus and Streptococcus pyogenes.","kind":"recall","origin":"ai"},{"id":"skin-infections-bacterial-fungal-viral~ai-1","moduleId":"skin-infections-bacterial-fungal-viral","stem":"Which clinical finding is characteristic of erysipelas?","options":[{"id":"a","text":"Ill-defined borders"},{"id":"b","text":"Honey-colored crusts"},{"id":"c","text":"Sharply demarcated, raised, bright-red plaque"},{"id":"d","text":"Painful vesicles"}],"answerId":"c","explanation":"Erysipelas presents with sharply demarcated, raised, bright-red plaques, typically caused by Streptococcus.","kind":"recall","origin":"ai"},{"id":"skin-infections-bacterial-fungal-viral~ai-2","moduleId":"skin-infections-bacterial-fungal-viral","stem":"What is the mechanism of action of terbinafine?","options":[{"id":"a","text":"Inhibits bacterial cell wall synthesis"},{"id":"b","text":"Inhibits ergosterol synthesis"},{"id":"c","text":"Disrupts DNA synthesis"},{"id":"d","text":"Inhibits protein synthesis"}],"answerId":"b","explanation":"Terbinafine works by inhibiting ergosterol synthesis, which is crucial for fungal cell membranes.","kind":"mechanism","origin":"ai"},{"id":"skin-infections-bacterial-fungal-viral~ai-3","moduleId":"skin-infections-bacterial-fungal-viral","stem":"A patient presents with rapidly spreading pain and systemic toxicity. What is the most likely diagnosis?","options":[{"id":"a","text":"Cellulitis"},{"id":"b","text":"Necrotising fasciitis"},{"id":"c","text":"Impetigo"},{"id":"d","text":"Erysipelas"}],"answerId":"b","explanation":"The combination of rapidly spreading pain and systemic toxicity suggests necrotising fasciitis, a surgical emergency.","kind":"clinical","origin":"ai"},{"id":"skin-infections-bacterial-fungal-viral~ai-4","moduleId":"skin-infections-bacterial-fungal-viral","stem":"Which of the following findings would most likely indicate a diagnosis of tinea corporis?","options":[{"id":"a","text":"Grouped vesicles on an erythematous base"},{"id":"b","text":"Annular scaly plaque with central clearing"},{"id":"c","text":"Honey-colored crusts"},{"id":"d","text":"Sharply demarcated red plaque"}],"answerId":"b","explanation":"Tinea corporis is characterized by annular scaly plaques with central clearing, often diagnosed with KOH microscopy.","kind":"recall","origin":"ai"},{"id":"skin-infections-bacterial-fungal-viral~ai-5","moduleId":"skin-infections-bacterial-fungal-viral","stem":"A child presents with a painful dermatomal rash and vesicles. What is the most likely viral infection?","options":[{"id":"a","text":"Herpes simplex"},{"id":"b","text":"Varicella-zoster"},{"id":"c","text":"Coxsackievirus"},{"id":"d","text":"Molluscum contagiosum"}],"answerId":"b","explanation":"The presentation of painful dermatomal vesicles is characteristic of herpes zoster (shingles), caused by reactivation of varicella-zoster virus.","kind":"recall","origin":"ai"},{"id":"skin-infections-bacterial-fungal-viral~ai-6","moduleId":"skin-infections-bacterial-fungal-viral","stem":"Which treatment is appropriate for a patient with confirmed dermatophyte infection of the nails?","options":[{"id":"a","text":"Topical mupirocin"},{"id":"b","text":"Oral terbinafine"},{"id":"c","text":"Topical clotrimazole"},{"id":"d","text":"Oral acyclovir"}],"answerId":"b","explanation":"Oral terbinafine is required for treating dermatophyte infections of the nails, as topical treatments do not penetrate effectively.","kind":"recall","origin":"ai"},{"id":"skin-infections-bacterial-fungal-viral~ai-7","moduleId":"skin-infections-bacterial-fungal-viral","stem":"How does the treatment of necrotising fasciitis differ from that of cellulitis?","options":[{"id":"a","text":"Necrotising fasciitis requires only antibiotics"},{"id":"b","text":"Cellulitis requires surgical intervention"},{"id":"c","text":"Necrotising fasciitis requires urgent debridement"},{"id":"d","text":"Cellulitis is always caused by Staphylococcus"}],"answerId":"c","explanation":"Necrotising fasciitis is a surgical emergency that requires urgent debridement in addition to antibiotics, unlike cellulitis.","kind":"trap","origin":"ai"},{"id":"skin-infections-bacterial-fungal-viral~ai-8","moduleId":"skin-infections-bacterial-fungal-viral","stem":"How are antifungal agents relevant in the treatment of pediatric skin diseases?","options":[{"id":"a","text":"They are used for all skin infections"},{"id":"b","text":"They specifically target viral infections"},{"id":"c","text":"They are used for dermatophyte infections in children"},{"id":"d","text":"They are not relevant"}],"answerId":"c","explanation":"Antifungal agents are crucial for treating dermatophyte infections, which are common in pediatric skin diseases.","kind":"integration","linkedModuleIds":["pediatric-skin-diseases"],"origin":"ai"},{"id":"skin-infections-bacterial-fungal-viral~ai-9","moduleId":"skin-infections-bacterial-fungal-viral","stem":"What is the connection between bacterial skin infections and cell-wall agents?","options":[{"id":"a","text":"Cell-wall agents are ineffective for bacterial infections"},{"id":"b","text":"Bacterial infections require topical treatments only"},{"id":"c","text":"Cell-wall agents are used to treat bacterial skin infections"},{"id":"d","text":"Bacterial skin infections do not require antibiotics"}],"answerId":"c","explanation":"Cell-wall agents are a class of antibiotics that are effective in treating bacterial skin infections.","kind":"integration","linkedModuleIds":["antibacterial-cell-wall-agents"],"origin":"ai"}],"vesiculobullous-diseases":[{"id":"vesiculobullous-diseases~ai-0","moduleId":"vesiculobullous-diseases","stem":"What is the primary target of antibodies in pemphigus vulgaris?","options":[{"id":"a","text":"Desmoglein 1"},{"id":"b","text":"Desmoglein 3"},{"id":"c","text":"BP180"},{"id":"d","text":"BP230"}],"answerId":"b","explanation":"Pemphigus vulgaris is characterized by IgG antibodies against desmoglein 3, leading to loss of keratinocyte adhesion.","kind":"recall","origin":"ai"},{"id":"vesiculobullous-diseases~ai-1","moduleId":"vesiculobullous-diseases","stem":"Which finding is characteristic of bullous pemphigoid?","options":[{"id":"a","text":"Flaccid blisters"},{"id":"b","text":"Positive Nikolsky sign"},{"id":"c","text":"Tense blisters on an urticarial base"},{"id":"d","text":"Oral involvement"}],"answerId":"c","explanation":"Bullous pemphigoid presents with tense, intact blisters on an urticarial base and typically spares the oral mucosa.","kind":"recall","origin":"ai"},{"id":"vesiculobullous-diseases~ai-2","moduleId":"vesiculobullous-diseases","stem":"What histological finding is associated with pemphigus vulgaris on direct immunofluorescence?","options":[{"id":"a","text":"Granular IgA"},{"id":"b","text":"Linear IgG/C3"},{"id":"c","text":"Intercellular IgG"},{"id":"d","text":"IgM deposits"}],"answerId":"c","explanation":"Pemphigus vulgaris shows intercellular 'chicken-wire' IgG on direct immunofluorescence.","kind":"mechanism","origin":"ai"},{"id":"vesiculobullous-diseases~ai-3","moduleId":"vesiculobullous-diseases","stem":"Which statement about the Nikolsky sign is true?","options":[{"id":"a","text":"It is positive in bullous pemphigoid"},{"id":"b","text":"It indicates flaccid blister formation"},{"id":"c","text":"It is negative in pemphigus vulgaris"},{"id":"d","text":"It is a sign of less severe disease"}],"answerId":"b","explanation":"A positive Nikolsky sign indicates flaccid blister formation, characteristic of pemphigus vulgaris, which is more severe.","kind":"trap","origin":"ai"},{"id":"vesiculobullous-diseases~ai-4","moduleId":"vesiculobullous-diseases","stem":"What is the first-line treatment for dermatitis herpetiformis?","options":[{"id":"a","text":"Topical steroids"},{"id":"b","text":"Systemic immunosuppressants"},{"id":"c","text":"Gluten-free diet"},{"id":"d","text":"Dapsone only"}],"answerId":"c","explanation":"The primary treatment for dermatitis herpetiformis is a gluten-free diet, which addresses the underlying cause related to coeliac disease.","kind":"recall","origin":"ai"},{"id":"vesiculobullous-diseases~ai-5","moduleId":"vesiculobullous-diseases","stem":"How does the mechanism of action differ between pemphigus vulgaris and bullous pemphigoid?","options":[{"id":"a","text":"Pemphigus targets hemidesmosomes"},{"id":"b","text":"Bullous pemphigoid targets desmogleins"},{"id":"c","text":"Pemphigus causes intra-epidermal splits"},{"id":"d","text":"Bullous pemphigoid causes acantholysis"}],"answerId":"c","explanation":"Pemphigus vulgaris causes intra-epidermal splits due to loss of keratinocyte adhesion, while bullous pemphigoid affects the dermal-epidermal junction.","kind":"mechanism","origin":"ai"},{"id":"vesiculobullous-diseases~ai-6","moduleId":"vesiculobullous-diseases","stem":"Which condition is associated with granular IgA deposits in the dermal papillae?","options":[{"id":"a","text":"Pemphigus vulgaris"},{"id":"b","text":"Bullous pemphigoid"},{"id":"c","text":"Dermatitis herpetiformis"},{"id":"d","text":"Epidermolysis bullosa"}],"answerId":"c","explanation":"Dermatitis herpetiformis is characterized by granular IgA deposits at the dermal papillae.","kind":"recall","origin":"ai"},{"id":"vesiculobullous-diseases~ai-7","moduleId":"vesiculobullous-diseases","stem":"How does the management of pemphigus vulgaris differ from that of bullous pemphigoid?","options":[{"id":"a","text":"Pemphigus requires topical steroids"},{"id":"b","text":"Bullous pemphigoid is treated with immunosuppressants"},{"id":"c","text":"Pemphigus is treated with systemic steroids"},{"id":"d","text":"Bullous pemphigoid requires a gluten-free diet"}],"answerId":"c","explanation":"Pemphigus vulgaris is treated with systemic steroids due to its severity, while bullous pemphigoid may be managed with topical or systemic steroids.","kind":"integration","linkedModuleIds":["dermatologic-therapy"],"origin":"ai"},{"id":"vesiculobullous-diseases~ai-8","moduleId":"vesiculobullous-diseases","stem":"Which histological feature is critical for differentiating between pemphigus vulgaris and bullous pemphigoid?","options":[{"id":"a","text":"Presence of granular IgA"},{"id":"b","text":"Location of the split"},{"id":"c","text":"Type of antibody involved"},{"id":"d","text":"Presence of Nikolsky sign"}],"answerId":"b","explanation":"The location of the split (intra-epidermal in pemphigus vs. sub-epidermal in bullous pemphigoid) is critical for differentiation.","kind":"integration","linkedModuleIds":["skin-anatomy-histology"],"origin":"ai"}],"dermatologic-investigations":[{"id":"dermatologic-investigations~ai-0","moduleId":"dermatologic-investigations","stem":"What does KOH microscopy reveal in a dermatophyte infection?","options":[{"id":"a","text":"Multinucleate giant cells"},{"id":"b","text":"Fungal hyphae"},{"id":"c","text":"Coral-red fluorescence"},{"id":"d","text":"Eosinophils"}],"answerId":"b","explanation":"KOH microscopy dissolves keratin, allowing visualization of fungal hyphae characteristic of dermatophyte infections.","kind":"recall","origin":"ai"},{"id":"dermatologic-investigations~ai-1","moduleId":"dermatologic-investigations","stem":"Which biopsy type is preferred for suspected melanoma?","options":[{"id":"a","text":"Shave biopsy"},{"id":"b","text":"Punch biopsy"},{"id":"c","text":"Excisional biopsy"},{"id":"d","text":"Incisional biopsy"}],"answerId":"c","explanation":"An excisional biopsy is necessary to obtain full thickness for accurate Breslow depth measurement in melanoma.","kind":"trap","origin":"ai"},{"id":"dermatologic-investigations~ai-2","moduleId":"dermatologic-investigations","stem":"What is the mechanism of coral-red fluorescence under Wood's lamp?","options":[{"id":"a","text":"Fungal infection"},{"id":"b","text":"Bacterial infection"},{"id":"c","text":"Viral infection"},{"id":"d","text":"Autoimmune disease"}],"answerId":"b","explanation":"Coral-red fluorescence indicates erythrasma, a bacterial infection caused by Corynebacterium.","kind":"mechanism","origin":"ai"},{"id":"dermatologic-investigations~ai-3","moduleId":"dermatologic-investigations","stem":"What does a positive patch test at 72–96 hours indicate?","options":[{"id":"a","text":"Immediate hypersensitivity"},{"id":"b","text":"Allergic contact dermatitis"},{"id":"c","text":"Infectious dermatitis"},{"id":"d","text":"Autoimmune blistering disease"}],"answerId":"b","explanation":"A positive patch test indicates allergic contact dermatitis, which is a Type IV hypersensitivity reaction.","kind":"recall","origin":"ai"},{"id":"dermatologic-investigations~ai-4","moduleId":"dermatologic-investigations","stem":"What finding is characteristic of herpes simplex virus on a Tzanck smear?","options":[{"id":"a","text":"Fungal hyphae"},{"id":"b","text":"Multinucleate giant cells"},{"id":"c","text":"Eosinophils"},{"id":"d","text":"Bacterial colonies"}],"answerId":"b","explanation":"The Tzanck smear shows multinucleate giant cells, which are indicative of herpes simplex or varicella-zoster virus infections.","kind":"recall","origin":"ai"},{"id":"dermatologic-investigations~ai-5","moduleId":"dermatologic-investigations","stem":"How does the approach to dermatological examination relate to KOH microscopy?","options":[{"id":"a","text":"KOH microscopy is used to confirm systemic diseases"},{"id":"b","text":"KOH microscopy is a bedside test following examination"},{"id":"c","text":"KOH microscopy is irrelevant to dermatological examination"},{"id":"d","text":"KOH microscopy is used for immediate allergy testing"}],"answerId":"b","explanation":"KOH microscopy is a bedside test that follows the initial dermatological examination to confirm fungal infections.","kind":"integration","linkedModuleIds":["skin-examination-approach"],"origin":"ai"},{"id":"dermatologic-investigations~ai-6","moduleId":"dermatologic-investigations","stem":"What is the significance of Breslow depth in melanoma management?","options":[{"id":"a","text":"Determines the need for immediate surgery"},{"id":"b","text":"Indicates the type of chemotherapy"},{"id":"c","text":"Guides prognosis and treatment decisions"},{"id":"d","text":"Confirms the presence of metastasis"}],"answerId":"c","explanation":"Breslow depth is a key prognostic factor in melanoma that guides treatment decisions and management strategies.","kind":"integration","linkedModuleIds":["skin-neoplasms"],"origin":"ai"}],"skin-signs-systemic-disease":[{"id":"skin-signs-systemic-disease~ai-0","moduleId":"skin-signs-systemic-disease","stem":"What is the most likely underlying condition associated with sudden onset extensive acanthosis nigricans in an older patient?","options":[{"id":"a","text":"Obesity"},{"id":"b","text":"Type 2 diabetes"},{"id":"c","text":"Gastric adenocarcinoma"},{"id":"d","text":"Polycystic ovary syndrome"}],"answerId":"c","explanation":"Sudden onset extensive acanthosis nigricans can indicate a paraneoplastic syndrome, particularly gastric adenocarcinoma.","kind":"recall","origin":"ai"},{"id":"skin-signs-systemic-disease~ai-1","moduleId":"skin-signs-systemic-disease","stem":"Which skin sign is most indicative of dermatomyositis?","options":[{"id":"a","text":"Heliotrope rash"},{"id":"b","text":"Café-au-lait macules"},{"id":"c","text":"Erythema migrans"},{"id":"d","text":"Palpable purpura"}],"answerId":"a","explanation":"Heliotrope rash is a classic skin manifestation of dermatomyositis, often associated with underlying malignancy.","kind":"recall","origin":"ai"},{"id":"skin-signs-systemic-disease~ai-2","moduleId":"skin-signs-systemic-disease","stem":"A patient presents with tender nodules on the shins. Which systemic condition should be investigated?","options":[{"id":"a","text":"Diabetes mellitus"},{"id":"b","text":"Sarcoidosis"},{"id":"c","text":"Hyperlipidemia"},{"id":"d","text":"Thyroid disease"}],"answerId":"b","explanation":"Tender shin nodules are characteristic of erythema nodosum, which can be triggered by sarcoidosis among other conditions.","kind":"clinical","origin":"ai"},{"id":"skin-signs-systemic-disease~ai-3","moduleId":"skin-signs-systemic-disease","stem":"What mechanism underlies the skin manifestation of pellagra?","options":[{"id":"a","text":"Vitamin C deficiency"},{"id":"b","text":"Zinc deficiency"},{"id":"c","text":"Niacin deficiency"},{"id":"d","text":"Vitamin D deficiency"}],"answerId":"c","explanation":"Pellagra is caused by niacin (vitamin B3) deficiency, leading to the classic triad of dermatitis, diarrhea, and dementia.","kind":"mechanism","origin":"ai"},{"id":"skin-signs-systemic-disease~ai-4","moduleId":"skin-signs-systemic-disease","stem":"A patient presents with generalized pruritus without a rash. Which condition is least likely to be the cause?","options":[{"id":"a","text":"Lymphoma"},{"id":"b","text":"Cholestasis"},{"id":"c","text":"Uraemia"},{"id":"d","text":"Psoriasis"}],"answerId":"d","explanation":"Generalized pruritus without a rash is commonly associated with lymphoma, cholestasis, and uraemia, but psoriasis typically presents with a rash.","kind":"trap","origin":"ai"},{"id":"skin-signs-systemic-disease~ai-5","moduleId":"skin-signs-systemic-disease","stem":"Which skin finding is associated with systemic lupus erythematosus (SLE)?","options":[{"id":"a","text":"Heliotrope rash"},{"id":"b","text":"Malar rash"},{"id":"c","text":"Erythema migrans"},{"id":"d","text":"Café-au-lait macules"}],"answerId":"b","explanation":"The malar rash is a characteristic skin finding in systemic lupus erythematosus (SLE).","kind":"recall","origin":"ai"},{"id":"skin-signs-systemic-disease~ai-6","moduleId":"skin-signs-systemic-disease","stem":"How does the presence of erythema nodosum relate to systemic diseases?","options":[{"id":"a","text":"It indicates a benign skin condition"},{"id":"b","text":"It suggests a need for cancer screening"},{"id":"c","text":"It is solely due to infections"},{"id":"d","text":"It is a sign of nutritional deficiency"}],"answerId":"b","explanation":"Erythema nodosum can be associated with systemic diseases like sarcoidosis and IBD, warranting further investigation for underlying conditions, including cancer.","kind":"integration","linkedModuleIds":["cutaneous-connective-tissue-diseases"],"origin":"ai"},{"id":"skin-signs-systemic-disease~ai-7","moduleId":"skin-signs-systemic-disease","stem":"Which skin sign could indicate a need for evaluation of connective tissue diseases?","options":[{"id":"a","text":"Acanthosis nigricans"},{"id":"b","text":"Heliotrope rash"},{"id":"c","text":"Café-au-lait macules"},{"id":"d","text":"Erythema migrans"}],"answerId":"b","explanation":"Heliotrope rash is associated with dermatomyositis, a connective tissue disease, indicating the need for further evaluation.","kind":"integration","linkedModuleIds":["cutaneous-connective-tissue-diseases"],"origin":"ai"}],"eczema-dermatitis":[{"id":"eczema-dermatitis~ai-0","moduleId":"eczema-dermatitis","stem":"What is the primary defect in atopic dermatitis?","options":[{"id":"a","text":"Filaggrin mutation"},{"id":"b","text":"Keratinocyte hyperproliferation"},{"id":"c","text":"Sebaceous gland hypertrophy"},{"id":"d","text":"Decreased T cell activity"}],"answerId":"a","explanation":"Atopic dermatitis is characterized by a barrier defect primarily due to filaggrin mutations, leading to increased transepidermal water loss and susceptibility to allergens.","kind":"recall","origin":"ai"},{"id":"eczema-dermatitis~ai-1","moduleId":"eczema-dermatitis","stem":"Which clinical finding is most indicative of eczema herpeticum?","options":[{"id":"a","text":"Dry, scaly patches"},{"id":"b","text":"Greasy yellow scale"},{"id":"c","text":"Punched-out erosions with fever"},{"id":"d","text":"Itchy vesicles on palms"}],"answerId":"c","explanation":"Eczema herpeticum presents with rapidly worsening eczema characterized by painful, punched-out erosions and systemic symptoms such as fever.","kind":"recall","origin":"ai"},{"id":"eczema-dermatitis~ai-2","moduleId":"eczema-dermatitis","stem":"What is the mechanism of action of topical calcineurin inhibitors in eczema treatment?","options":[{"id":"a","text":"Inhibition of histamine release"},{"id":"b","text":"Blocking T cell activation"},{"id":"c","text":"Promoting keratinocyte proliferation"},{"id":"d","text":"Enhancing skin barrier function"}],"answerId":"b","explanation":"Topical calcineurin inhibitors work by blocking T cell activation, thereby reducing inflammation in conditions like eczema.","kind":"mechanism","origin":"ai"},{"id":"eczema-dermatitis~ai-3","moduleId":"eczema-dermatitis","stem":"A cleaner develops hand dermatitis after exposure to detergents without prior sensitization. What type of dermatitis is this?","options":[{"id":"a","text":"Allergic contact dermatitis"},{"id":"b","text":"Irritant contact dermatitis"},{"id":"c","text":"Atopic dermatitis"},{"id":"d","text":"Seborrhoeic dermatitis"}],"answerId":"b","explanation":"This scenario describes irritant contact dermatitis, which occurs due to direct damage from irritants rather than an immune response.","kind":"clinical","origin":"ai"},{"id":"eczema-dermatitis~ai-4","moduleId":"eczema-dermatitis","stem":"In a patient with atopic dermatitis, which area is most likely to show lichenification due to chronic scratching?","options":[{"id":"a","text":"Face"},{"id":"b","text":"Scalp"},{"id":"c","text":"Flexural areas"},{"id":"d","text":"Palms"}],"answerId":"c","explanation":"Chronic scratching in atopic dermatitis typically leads to lichenification in flexural areas such as the antecubital and popliteal fossae.","kind":"trap","origin":"ai"},{"id":"eczema-dermatitis~ai-5","moduleId":"eczema-dermatitis","stem":"How does eczema relate to the physiology of skin barrier function?","options":[{"id":"a","text":"Eczema is caused by excessive sebaceous gland activity"},{"id":"b","text":"Eczema results from impaired thermoregulation"},{"id":"c","text":"Eczema is linked to a defect in skin barrier integrity"},{"id":"d","text":"Eczema is due to increased keratinocyte turnover"}],"answerId":"c","explanation":"Eczema is associated with a defect in skin barrier integrity, leading to increased transepidermal water loss and susceptibility to irritants and allergens.","kind":"integration","linkedModuleIds":["skin-physiology-thermoregulation"],"origin":"ai"},{"id":"eczema-dermatitis~ai-6","moduleId":"eczema-dermatitis","stem":"What type of hypersensitivity reaction is involved in allergic contact dermatitis?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"d","explanation":"Allergic contact dermatitis is mediated by a Type IV delayed hypersensitivity reaction, involving T cell activation upon re-exposure to the allergen.","kind":"integration","linkedModuleIds":["cutaneous-immunology-hypersensitivity"],"origin":"ai"}],"dermis-appendages-glands":[{"id":"dermis-appendages-glands~ai-0","moduleId":"dermis-appendages-glands","stem":"What type of secretion do sebaceous glands utilize?","options":[{"id":"a","text":"Merocrine"},{"id":"b","text":"Apocrine"},{"id":"c","text":"Holocrine"},{"id":"d","text":"Endocrine"}],"answerId":"c","explanation":"Sebaceous glands use holocrine secretion, where the entire cell disintegrates to release sebum.","kind":"recall","origin":"ai"},{"id":"dermis-appendages-glands~ai-1","moduleId":"dermis-appendages-glands","stem":"Which layer of the dermis contains loose connective tissue and dermal papillae?","options":[{"id":"a","text":"Reticular layer"},{"id":"b","text":"Hypodermis"},{"id":"c","text":"Papillary layer"},{"id":"d","text":"Epidermis"}],"answerId":"c","explanation":"The papillary layer of the dermis is characterized by loose connective tissue and interdigitating dermal papillae.","kind":"recall","origin":"ai"},{"id":"dermis-appendages-glands~ai-2","moduleId":"dermis-appendages-glands","stem":"A patient presents with excessive sweating that is not relieved by anticholinergic medications. Which type of gland is primarily responsible for this symptom?","options":[{"id":"a","text":"Sebaceous glands"},{"id":"b","text":"Apocrine glands"},{"id":"c","text":"Eccrine glands"},{"id":"d","text":"Endocrine glands"}],"answerId":"c","explanation":"Eccrine glands are responsible for thermoregulatory sweating and are under sympathetic-cholinergic control.","kind":"clinical","origin":"ai"},{"id":"dermis-appendages-glands~ai-3","moduleId":"dermis-appendages-glands","stem":"Which of the following findings is most indicative of psoriasis affecting the nail matrix?","options":[{"id":"a","text":"Onycholysis"},{"id":"b","text":"Nail pitting"},{"id":"c","text":"Clubbing"},{"id":"d","text":"Hyperkeratosis"}],"answerId":"b","explanation":"Nail pitting is a classic diagnostic clue associated with psoriasis.","kind":"recall","origin":"ai"},{"id":"dermis-appendages-glands~ai-4","moduleId":"dermis-appendages-glands","stem":"What is the primary mechanism by which apocrine glands contribute to body odor?","options":[{"id":"a","text":"Direct secretion onto skin"},{"id":"b","text":"Bacterial breakdown of secretion"},{"id":"c","text":"Holocrine disintegration"},{"id":"d","text":"Sympathetic stimulation"}],"answerId":"b","explanation":"Apocrine glands secrete into hair follicles, and their secretion is broken down by bacteria, leading to body odor.","kind":"mechanism","origin":"ai"},{"id":"dermis-appendages-glands~ai-5","moduleId":"dermis-appendages-glands","stem":"A patient with hidradenitis suppurativa has occluded apocrine glands. Which area is most likely affected?","options":[{"id":"a","text":"Forehead"},{"id":"b","text":"Palm"},{"id":"c","text":"Axilla"},{"id":"d","text":"Sole of foot"}],"answerId":"c","explanation":"Hidradenitis suppurativa primarily affects areas with apocrine glands, such as the axilla and groin.","kind":"clinical","origin":"ai"},{"id":"dermis-appendages-glands~ai-6","moduleId":"dermis-appendages-glands","stem":"How do eccrine and apocrine glands differ in their secretion mechanisms?","options":[{"id":"a","text":"Eccrine are holocrine; apocrine are merocrine"},{"id":"b","text":"Eccrine are merocrine; apocrine are holocrine"},{"id":"c","text":"Eccrine are merocrine; apocrine are apocrine"},{"id":"d","text":"Both are holocrine"}],"answerId":"c","explanation":"Eccrine glands secrete via merocrine mechanisms, while apocrine glands have a different mode of secretion.","kind":"trap","origin":"ai"},{"id":"dermis-appendages-glands~ai-7","moduleId":"dermis-appendages-glands","stem":"Which of the following conditions is most directly related to the dysfunction of the pilosebaceous unit?","options":[{"id":"a","text":"Psoriasis"},{"id":"b","text":"Acne vulgaris"},{"id":"c","text":"Hidradenitis suppurativa"},{"id":"d","text":"Alopecia areata"}],"answerId":"b","explanation":"Acne vulgaris is directly related to the dysfunction of the pilosebaceous unit, particularly the sebaceous glands.","kind":"integration","linkedModuleIds":["acne-vulgaris"],"origin":"ai"},{"id":"dermis-appendages-glands~ai-8","moduleId":"dermis-appendages-glands","stem":"What is the primary role of eccrine glands in thermoregulation?","options":[{"id":"a","text":"Secretion of sebum"},{"id":"b","text":"Release of sweat directly onto the skin"},{"id":"c","text":"Activation by androgens"},{"id":"d","text":"Connection to hair follicles"}],"answerId":"b","explanation":"Eccrine glands release sweat directly onto the skin surface, playing a crucial role in thermoregulation.","kind":"integration","linkedModuleIds":["glands-exocrine-endocrine"],"origin":"ai"}],"skin-immune-system-cells":[{"id":"skin-immune-system-cells~ai-0","moduleId":"skin-immune-system-cells","stem":"What is the primary function of Langerhans cells in the skin?","options":[{"id":"a","text":"Barrier formation"},{"id":"b","text":"Antigen presentation"},{"id":"c","text":"Cytokine secretion"},{"id":"d","text":"Antimicrobial peptide production"}],"answerId":"b","explanation":"Langerhans cells are specialized dendritic cells that capture and present antigens to T cells, playing a crucial role in immune surveillance.","kind":"recall","origin":"ai"},{"id":"skin-immune-system-cells~ai-1","moduleId":"skin-immune-system-cells","stem":"Which cytokine is primarily involved in the Th2 response associated with atopic dermatitis?","options":[{"id":"a","text":"IL-1"},{"id":"b","text":"IL-4"},{"id":"c","text":"IL-17"},{"id":"d","text":"TNF-alpha"}],"answerId":"b","explanation":"IL-4 is a key cytokine in the Th2 immune response, contributing to the pathophysiology of atopic dermatitis.","kind":"recall","origin":"ai"},{"id":"skin-immune-system-cells~ai-2","moduleId":"skin-immune-system-cells","stem":"What is the role of antimicrobial peptides in skin immunity?","options":[{"id":"a","text":"Promoting T cell activation"},{"id":"b","text":"Enhancing barrier function"},{"id":"c","text":"Limiting skin infection"},{"id":"d","text":"Inducing inflammation"}],"answerId":"c","explanation":"Antimicrobial peptides, such as defensins and cathelicidin, play a critical role in the innate immune defense by limiting skin infections.","kind":"recall","origin":"ai"},{"id":"skin-immune-system-cells~ai-3","moduleId":"skin-immune-system-cells","stem":"In psoriasis, which immune pathway is primarily targeted by biologics?","options":[{"id":"a","text":"Th1 pathway"},{"id":"b","text":"Th2 pathway"},{"id":"c","text":"Th17 pathway"},{"id":"d","text":"Treg pathway"}],"answerId":"c","explanation":"Psoriasis is driven by Th17-mediated inflammation, making the Th17 pathway a primary target for biologic therapies.","kind":"recall","origin":"ai"},{"id":"skin-immune-system-cells~ai-4","moduleId":"skin-immune-system-cells","stem":"Keratinocytes are involved in skin immunity by releasing which of the following?","options":[{"id":"a","text":"Antigen-presenting cells"},{"id":"b","text":"Cytokines"},{"id":"c","text":"Antimicrobial peptides"},{"id":"d","text":"Both cytokines and antimicrobial peptides"}],"answerId":"d","explanation":"Keratinocytes actively participate in skin immunity by releasing both cytokines and antimicrobial peptides in response to pathogens.","kind":"trap","origin":"ai"},{"id":"skin-immune-system-cells~ai-5","moduleId":"skin-immune-system-cells","stem":"How do Toll-like receptors (TLRs) contribute to skin immunity?","options":[{"id":"a","text":"By forming a physical barrier"},{"id":"b","text":"By recognizing pathogens and triggering cytokine release"},{"id":"c","text":"By presenting antigens to T cells"},{"id":"d","text":"By producing antimicrobial peptides"}],"answerId":"b","explanation":"Toll-like receptors on keratinocytes recognize pathogens and trigger the release of cytokines, initiating an immune response.","kind":"mechanism","origin":"ai"},{"id":"skin-immune-system-cells~ai-6","moduleId":"skin-immune-system-cells","stem":"What is the relationship between skin barrier dysfunction and eczema?","options":[{"id":"a","text":"Barrier dysfunction leads to increased infection risk"},{"id":"b","text":"Barrier dysfunction causes allergic reactions"},{"id":"c","text":"Barrier dysfunction is unrelated to eczema"},{"id":"d","text":"Barrier dysfunction promotes T cell activation"}],"answerId":"a","explanation":"Skin barrier dysfunction can lead to increased susceptibility to infections and contribute to the development of eczema.","kind":"integration","linkedModuleIds":["skin-barrier-function"],"origin":"ai"},{"id":"skin-immune-system-cells~ai-7","moduleId":"skin-immune-system-cells","stem":"Which immune cells are primarily involved in the hypersensitivity reactions seen in contact dermatitis?","options":[{"id":"a","text":"B cells"},{"id":"b","text":"T cells"},{"id":"c","text":"Mast cells"},{"id":"d","text":"Macrophages"}],"answerId":"b","explanation":"T cells, particularly CD4+ T helper cells, play a central role in mediating the delayed-type hypersensitivity reactions seen in contact dermatitis.","kind":"integration","linkedModuleIds":["cutaneous-hypersensitivity-reactions"],"origin":"ai"}],"dermatologic-therapy":[{"id":"dermatologic-therapy~ai-0","moduleId":"dermatologic-therapy","stem":"What is the primary reason for using a greasy ointment for a dry, lichenified plaque?","options":[{"id":"a","text":"It provides a cooling effect"},{"id":"b","text":"It enhances absorption of the active ingredient"},{"id":"c","text":"It is less likely to cause irritation"},{"id":"d","text":"It is more potent and occlusive"}],"answerId":"d","explanation":"Greasy ointments are more occlusive, enhancing the potency and hydration for dry lesions.","kind":"mechanism","origin":"ai"},{"id":"dermatologic-therapy~ai-1","moduleId":"dermatologic-therapy","stem":"Which topical corticosteroid would be most appropriate for a child with eczema on the face?","options":[{"id":"a","text":"Clobetasol"},{"id":"b","text":"Hydrocortisone"},{"id":"c","text":"Betamethasone"},{"id":"d","text":"Triamcinolone"}],"answerId":"b","explanation":"Hydrocortisone is a mild steroid suitable for sensitive areas like the face and for use in children.","kind":"recall","origin":"ai"},{"id":"dermatologic-therapy~ai-2","moduleId":"dermatologic-therapy","stem":"What is a common side effect of prolonged use of potent topical corticosteroids on thin skin?","options":[{"id":"a","text":"Hyperpigmentation"},{"id":"b","text":"Skin atrophy"},{"id":"c","text":"Increased hair growth"},{"id":"d","text":"Acne formation"}],"answerId":"b","explanation":"Prolonged use of potent corticosteroids can lead to skin atrophy, especially on thin skin areas.","kind":"recall","origin":"ai"},{"id":"dermatologic-therapy~ai-3","moduleId":"dermatologic-therapy","stem":"Which statement about topical corticosteroid potency is true?","options":[{"id":"a","text":"Potent steroids can be used anywhere without concern"},{"id":"b","text":"Mild steroids are safe for all body areas"},{"id":"c","text":"Potency should match the site of application"},{"id":"d","text":"All steroids have the same absorption rate regardless of site"}],"answerId":"c","explanation":"Topical corticosteroid potency must be matched to the site due to varying absorption rates and risk of side effects.","kind":"trap","origin":"ai"},{"id":"dermatologic-therapy~ai-4","moduleId":"dermatologic-therapy","stem":"What is the mechanism of action for narrowband UVB therapy in psoriasis?","options":[{"id":"a","text":"Inhibition of keratinocyte proliferation"},{"id":"b","text":"Reduction of inflammatory cytokines"},{"id":"c","text":"Promotion of skin hydration"},{"id":"d","text":"Stimulation of melanocyte activity"}],"answerId":"b","explanation":"Narrowband UVB therapy reduces inflammatory cytokines, helping to manage psoriasis.","kind":"mechanism","origin":"ai"},{"id":"dermatologic-therapy~ai-5","moduleId":"dermatologic-therapy","stem":"Which systemic agent is commonly used for severe psoriasis that does not respond to topical therapies?","options":[{"id":"a","text":"Hydrocortisone"},{"id":"b","text":"Methotrexate"},{"id":"c","text":"Benzoyl peroxide"},{"id":"d","text":"Salicylic acid"}],"answerId":"b","explanation":"Methotrexate is a systemic agent used for severe psoriasis when topical treatments fail.","kind":"recall","origin":"ai"},{"id":"dermatologic-therapy~ai-6","moduleId":"dermatologic-therapy","stem":"How does the treatment of eczema relate to the management of psoriasis?","options":[{"id":"a","text":"Both primarily use systemic antibiotics"},{"id":"b","text":"Both can be treated with topical corticosteroids"},{"id":"c","text":"Both require surgical intervention"},{"id":"d","text":"Both are exclusively managed with phototherapy"}],"answerId":"b","explanation":"Eczema and psoriasis can both be treated with topical corticosteroids, highlighting the overlap in dermatologic therapies.","kind":"integration","linkedModuleIds":["eczema-dermatitis"],"origin":"ai"},{"id":"dermatologic-therapy~ai-7","moduleId":"dermatologic-therapy","stem":"In the context of systemic dermatologic therapy, how does the management of acne vulgaris differ from that of psoriasis?","options":[{"id":"a","text":"Acne is treated only with topical agents"},{"id":"b","text":"Psoriasis requires systemic agents more often"},{"id":"c","text":"Both conditions are treated with the same systemic agents"},{"id":"d","text":"Acne does not respond to phototherapy"}],"answerId":"b","explanation":"Psoriasis often requires systemic agents due to its severity, while acne is typically managed with topical treatments initially.","kind":"integration","linkedModuleIds":["acne-vulgaris"],"origin":"ai"}],"acne-vulgaris":[{"id":"acne-vulgaris~ai-0","moduleId":"acne-vulgaris","stem":"What is the primary mechanism by which isotretinoin treats severe acne?","options":[{"id":"a","text":"Inhibits sebum production"},{"id":"b","text":"Reduces inflammation"},{"id":"c","text":"Normalizes keratinization"},{"id":"d","text":"Antibacterial action against C. acnes"}],"answerId":"c","explanation":"Isotretinoin primarily normalizes keratinization, which helps to prevent the formation of comedones.","kind":"mechanism","origin":"ai"},{"id":"acne-vulgaris~ai-1","moduleId":"acne-vulgaris","stem":"Which of the following is a common side effect of isotretinoin?","options":[{"id":"a","text":"Increased hair growth"},{"id":"b","text":"Dry skin and lips"},{"id":"c","text":"Weight gain"},{"id":"d","text":"Increased appetite"}],"answerId":"b","explanation":"Dry skin and lips are well-known side effects of isotretinoin due to its effects on sebaceous glands.","kind":"recall","origin":"ai"},{"id":"acne-vulgaris~ai-2","moduleId":"acne-vulgaris","stem":"A 15-year-old male presents with multiple open and closed comedones on his face. What is the most likely underlying cause?","options":[{"id":"a","text":"Increased estrogen levels"},{"id":"b","text":"Decreased sebum production"},{"id":"c","text":"Increased androgen levels"},{"id":"d","text":"Infection with C. acnes"}],"answerId":"c","explanation":"Increased androgen levels lead to increased sebum production, which contributes to the formation of comedones.","kind":"clinical","origin":"ai"},{"id":"acne-vulgaris~ai-3","moduleId":"acne-vulgaris","stem":"What is the most significant risk associated with the use of isotretinoin in women of childbearing age?","options":[{"id":"a","text":"Development of acne resistance"},{"id":"b","text":"Severe teratogenic effects"},{"id":"c","text":"Increased risk of skin infections"},{"id":"d","text":"Allergic reactions"}],"answerId":"b","explanation":"Isotretinoin is a potent teratogen and can cause severe fetal malformations, necessitating strict pregnancy prevention measures.","kind":"trap","origin":"ai"},{"id":"acne-vulgaris~ai-4","moduleId":"acne-vulgaris","stem":"Which type of acne lesion is characterized by deep painful nodules that may scar?","options":[{"id":"a","text":"Open comedones"},{"id":"b","text":"Closed comedones"},{"id":"c","text":"Papules"},{"id":"d","text":"Nodulocystic lesions"}],"answerId":"d","explanation":"Nodulocystic lesions are severe forms of acne that can lead to scarring.","kind":"recall","origin":"ai"},{"id":"acne-vulgaris~ai-5","moduleId":"acne-vulgaris","stem":"A patient with acne presents with brown marks on their skin after lesions have resolved. What is this condition called?","options":[{"id":"a","text":"Post-inflammatory erythema"},{"id":"b","text":"Post-inflammatory hyperpigmentation"},{"id":"c","text":"Seborrheic dermatitis"},{"id":"d","text":"Acne scars"}],"answerId":"b","explanation":"Post-inflammatory hyperpigmentation is common after acne resolution, especially in individuals with darker skin.","kind":"recall","origin":"ai"},{"id":"acne-vulgaris~ai-6","moduleId":"acne-vulgaris","stem":"How does the treatment ladder for acne vulgaris relate to the management of skin conditions in dermatologic therapy?","options":[{"id":"a","text":"Both focus on surgical interventions"},{"id":"b","text":"Both prioritize topical treatments first"},{"id":"c","text":"Both require patient education on hygiene"},{"id":"d","text":"Both emphasize the importance of systemic antibiotics"}],"answerId":"b","explanation":"The treatment ladder for acne vulgaris begins with topical treatments, which is a common approach in dermatologic therapy.","kind":"integration","linkedModuleIds":["dermatologic-therapy"],"origin":"ai"},{"id":"acne-vulgaris~ai-7","moduleId":"acne-vulgaris","stem":"What is the relationship between acne vulgaris and skin anatomy as taught in skin anatomy & histology?","options":[{"id":"a","text":"Acne is unrelated to skin structure"},{"id":"b","text":"Acne primarily affects the epidermis only"},{"id":"c","text":"Acne involves the pilosebaceous unit"},{"id":"d","text":"Acne is a vascular condition"}],"answerId":"c","explanation":"Acne vulgaris is a disease of the pilosebaceous unit, which is a key concept in skin anatomy and histology.","kind":"integration","linkedModuleIds":["skin-anatomy-histology"],"origin":"ai"}],"photoaging-photoprotection":[{"id":"photoaging-photoprotection~ai-0","moduleId":"photoaging-photoprotection","stem":"What is the primary mechanism by which UVA contributes to skin aging?","options":[{"id":"a","text":"Causes sunburn"},{"id":"b","text":"Damages epidermal DNA"},{"id":"c","text":"Leads to collagen and elastin damage"},{"id":"d","text":"Increases melanin production"}],"answerId":"c","explanation":"UVA penetrates the dermis and causes damage to collagen and elastin, leading to skin aging.","kind":"mechanism","origin":"ai"},{"id":"photoaging-photoprotection~ai-1","moduleId":"photoaging-photoprotection","stem":"Which type of UV radiation is primarily responsible for causing sunburn?","options":[{"id":"a","text":"UVA"},{"id":"b","text":"UVB"},{"id":"c","text":"UVC"},{"id":"d","text":"Infrared"}],"answerId":"b","explanation":"UVB radiation is responsible for causing sunburn and is the main carcinogen affecting the epidermis.","kind":"recall","origin":"ai"},{"id":"photoaging-photoprotection~ai-2","moduleId":"photoaging-photoprotection","stem":"A patient with Fitzpatrick skin type I is at increased risk for which of the following?","options":[{"id":"a","text":"Melasma"},{"id":"b","text":"Actinic keratosis"},{"id":"c","text":"Sunburn and skin cancer"},{"id":"d","text":"Photoaging without sunburn"}],"answerId":"c","explanation":"Fitzpatrick type I patients always burn and have the highest risk for sunburn and skin cancer.","kind":"recall","origin":"ai"},{"id":"photoaging-photoprotection~ai-3","moduleId":"photoaging-photoprotection","stem":"Which treatment is most effective for reducing fine wrinkles and dyspigmentation due to photodamage?","options":[{"id":"a","text":"Topical retinoids"},{"id":"b","text":"Cryotherapy"},{"id":"c","text":"Broad-spectrum sunscreen"},{"id":"d","text":"Antioxidants"}],"answerId":"a","explanation":"Topical retinoids like tretinoin stimulate collagen production and improve fine wrinkles and dyspigmentation.","kind":"mechanism","origin":"ai"},{"id":"photoaging-photoprotection~ai-4","moduleId":"photoaging-photoprotection","stem":"What is a common misconception regarding SPF ratings of sunscreens?","options":[{"id":"a","text":"Higher SPF provides complete protection against all UV damage"},{"id":"b","text":"SPF only measures UVB protection"},{"id":"c","text":"SPF should be reapplied every hour"},{"id":"d","text":"SPF is irrelevant for skin types I and II"}],"answerId":"a","explanation":"A high SPF only measures UVB protection; it does not guarantee complete protection against UVA damage.","kind":"trap","origin":"ai"},{"id":"photoaging-photoprotection~ai-5","moduleId":"photoaging-photoprotection","stem":"A patient presents with scaly lesions on sun-exposed areas. Which treatment is most appropriate to prevent progression to SCC?","options":[{"id":"a","text":"Topical retinoids"},{"id":"b","text":"Cryotherapy"},{"id":"c","text":"Broad-spectrum sunscreen"},{"id":"d","text":"Chemical peels"}],"answerId":"b","explanation":"Cryotherapy is an effective treatment for actinic keratoses, which can progress to squamous cell carcinoma (SCC).","kind":"recall","origin":"ai"},{"id":"photoaging-photoprotection~ai-6","moduleId":"photoaging-photoprotection","stem":"How does photoprotection relate to the risk of keratinocyte carcinomas?","options":[{"id":"a","text":"Only UVA contributes to keratinocyte carcinomas"},{"id":"b","text":"Photoprotection is irrelevant for skin aging"},{"id":"c","text":"Broad-spectrum sunscreen reduces the risk of both photoaging and keratinocyte carcinomas"},{"id":"d","text":"Skin type does not influence cancer risk"}],"answerId":"c","explanation":"Broad-spectrum sunscreen protects against both UVA and UVB, reducing the risk of photoaging and keratinocyte carcinomas.","kind":"integration","linkedModuleIds":["keratinocyte-carcinomas"],"origin":"ai"},{"id":"photoaging-photoprotection~ai-7","moduleId":"photoaging-photoprotection","stem":"What is the relationship between Fitzpatrick skin types and skin aging?","options":[{"id":"a","text":"Higher types age faster"},{"id":"b","text":"Lower types have lower UV risk"},{"id":"c","text":"Lower types are more prone to photoaging"},{"id":"d","text":"Skin type does not affect aging"}],"answerId":"c","explanation":"Lower Fitzpatrick types (I–II) are more prone to sunburn and photoaging due to their inability to tan effectively.","kind":"integration","linkedModuleIds":["skin-aging"],"origin":"ai"}],"pigmentary-disorders":[{"id":"pigmentary-disorders~ai-0","moduleId":"pigmentary-disorders","stem":"What is the primary mechanism behind vitiligo?","options":[{"id":"a","text":"Autoimmune destruction of melanocytes"},{"id":"b","text":"Genetic defect in melanin synthesis"},{"id":"c","text":"UV-induced damage to melanocytes"},{"id":"d","text":"Hormonal stimulation of melanocyte activity"}],"answerId":"a","explanation":"Vitiligo is characterized by the autoimmune destruction of melanocytes, leading to depigmented patches on the skin.","kind":"mechanism","origin":"ai"},{"id":"pigmentary-disorders~ai-1","moduleId":"pigmentary-disorders","stem":"Which clinical finding is most characteristic of albinism?","options":[{"id":"a","text":"Sharply demarcated milky-white patches"},{"id":"b","text":"Generalized hypopigmentation with ocular involvement"},{"id":"c","text":"Symmetric brown patches on the face"},{"id":"d","text":"Brown discoloration at sites of resolved acne"}],"answerId":"b","explanation":"Albinism presents with generalized hypopigmentation and is associated with ocular abnormalities and increased risk of skin cancer.","kind":"recall","origin":"ai"},{"id":"pigmentary-disorders~ai-2","moduleId":"pigmentary-disorders","stem":"What is the main treatment strategy for melasma?","options":[{"id":"a","text":"Topical steroids"},{"id":"b","text":"Phototherapy"},{"id":"c","text":"Sun protection and topical lightening agents"},{"id":"d","text":"Oral corticosteroids"}],"answerId":"c","explanation":"Melasma management focuses on sun protection and the use of topical lightening agents to reduce pigmentation.","kind":"recall","origin":"ai"},{"id":"pigmentary-disorders~ai-3","moduleId":"pigmentary-disorders","stem":"Which statement correctly differentiates vitiligo from albinism?","options":[{"id":"a","text":"Both conditions are due to a lack of melanin"},{"id":"b","text":"Vitiligo involves a loss of melanocytes, while albinism involves a synthesis defect"},{"id":"c","text":"Albinism is acquired, while vitiligo is congenital"},{"id":"d","text":"Vitiligo presents with generalized hypopigmentation, while albinism is patchy"}],"answerId":"b","explanation":"Vitiligo is characterized by the autoimmune destruction of melanocytes, while albinism is due to a genetic defect in melanin synthesis.","kind":"trap","origin":"ai"},{"id":"pigmentary-disorders~ai-4","moduleId":"pigmentary-disorders","stem":"What is the most common cause of post-inflammatory hyperpigmentation?","options":[{"id":"a","text":"Genetic defect in melanin synthesis"},{"id":"b","text":"Autoimmune destruction of melanocytes"},{"id":"c","text":"Inflammation from acne or eczema"},{"id":"d","text":"UV exposure"}],"answerId":"c","explanation":"Post-inflammatory hyperpigmentation typically occurs following inflammation, such as from acne or eczema, especially in individuals with darker skin.","kind":"recall","origin":"ai"},{"id":"pigmentary-disorders~ai-5","moduleId":"pigmentary-disorders","stem":"Which of the following is a characteristic finding in pityriasis versicolor?","options":[{"id":"a","text":"Milky-white patches accentuated by Wood's lamp"},{"id":"b","text":"Finely scaly hypo/hyperpigmented macules, KOH positive"},{"id":"c","text":"Symmetric brown patches on the cheeks"},{"id":"d","text":"Generalized hypopigmentation with ocular involvement"}],"answerId":"b","explanation":"Pityriasis versicolor presents with finely scaly macules that can be hypo or hyperpigmented and are KOH positive.","kind":"recall","origin":"ai"},{"id":"pigmentary-disorders~ai-6","moduleId":"pigmentary-disorders","stem":"How does melasma relate to skin aging?","options":[{"id":"a","text":"It is a result of genetic aging"},{"id":"b","text":"It is primarily caused by UV exposure and hormonal changes"},{"id":"c","text":"It does not relate to skin aging"},{"id":"d","text":"It is a sign of skin cancer risk"}],"answerId":"b","explanation":"Melasma is influenced by UV exposure and hormonal changes, which are also factors in skin aging.","kind":"integration","linkedModuleIds":["skin-aging"],"origin":"ai"},{"id":"pigmentary-disorders~ai-7","moduleId":"pigmentary-disorders","stem":"Which condition's management overlaps with the principles of skin neoplasms?","options":[{"id":"a","text":"Vitiligo"},{"id":"b","text":"Albinism"},{"id":"c","text":"Melasma"},{"id":"d","text":"Pityriasis versicolor"}],"answerId":"b","explanation":"Management of albinism includes sun protection to reduce skin cancer risk, similar to strategies used in skin neoplasms.","kind":"integration","linkedModuleIds":["skin-neoplasms"],"origin":"ai"}],"skin-examination-approach":[{"id":"skin-examination-approach~ai-0","moduleId":"skin-examination-approach","stem":"What is the primary purpose of examining special sites such as the scalp and nails during a dermatological examination?","options":[{"id":"a","text":"To identify systemic diseases"},{"id":"b","text":"To assess skin hydration levels"},{"id":"c","text":"To find diagnostic clues that may not be visible on the main lesion"},{"id":"d","text":"To evaluate the effectiveness of previous treatments"}],"answerId":"c","explanation":"Special sites often harbor diagnostic clues like nail pitting in psoriasis or oral erosions in pemphigus, which may be missed if only the main lesion is examined.","kind":"recall","origin":"ai"},{"id":"skin-examination-approach~ai-1","moduleId":"skin-examination-approach","stem":"Which of the following findings is characteristic of atopic eczema?","options":[{"id":"a","text":"Nail pitting"},{"id":"b","text":"Flexural distribution of an itchy dermatitis"},{"id":"c","text":"Photo-distributed rash"},{"id":"d","text":"Oral mucosal erosions"}],"answerId":"b","explanation":"Atopic eczema typically presents with an itchy dermatitis that has a flexural distribution, particularly in the antecubital and popliteal fossae.","kind":"recall","origin":"ai"},{"id":"skin-examination-approach~ai-2","moduleId":"skin-examination-approach","stem":"A patient presents with a purpuric rash that does not blanch on diascopy. What does this finding indicate?","options":[{"id":"a","text":"Erythema"},{"id":"b","text":"Vasculitis"},{"id":"c","text":"Thrombocytopenia"},{"id":"d","text":"Infection"}],"answerId":"b","explanation":"Purpura that does not blanch indicates extravasated blood, commonly seen in vasculitis, rather than erythema which blanches.","kind":"mechanism","origin":"ai"},{"id":"skin-examination-approach~ai-3","moduleId":"skin-examination-approach","stem":"Which of the following is a common trap in dermatological examinations?","options":[{"id":"a","text":"Examining the entire skin surface"},{"id":"b","text":"Focusing only on the lesion the patient is concerned about"},{"id":"c","text":"Taking a detailed patient history"},{"id":"d","text":"Using diascopy to assess lesions"}],"answerId":"b","explanation":"Limiting the examination to the presenting complaint can miss important diagnostic clues found on the rest of the skin or special sites.","kind":"trap","origin":"ai"},{"id":"skin-examination-approach~ai-4","moduleId":"skin-examination-approach","stem":"A patient presents with a rash that is distributed symmetrically across the body. Which condition is most likely?","options":[{"id":"a","text":"Psoriasis"},{"id":"b","text":"Atopic eczema"},{"id":"c","text":"Lupus erythematosus"},{"id":"d","text":"Hand-foot-mouth disease"}],"answerId":"c","explanation":"Lupus erythematosus often presents with a symmetrical distribution of rashes, particularly on sun-exposed areas.","kind":"clinical","origin":"ai"},{"id":"skin-examination-approach~ai-5","moduleId":"skin-examination-approach","stem":"Which of the following findings would most likely indicate a diagnosis of pemphigus?","options":[{"id":"a","text":"Nail pitting"},{"id":"b","text":"Oral mucosal erosions"},{"id":"c","text":"Flexural dermatitis"},{"id":"d","text":"Purpura"}],"answerId":"b","explanation":"Oral mucosal erosions are a classic sign of pemphigus, indicating the presence of autoimmune blistering.","kind":"recall","origin":"ai"},{"id":"skin-examination-approach~ai-6","moduleId":"skin-examination-approach","stem":"How does a dermatological examination relate to identifying hand nerve lesions?","options":[{"id":"a","text":"Skin lesions can indicate nerve damage."},{"id":"b","text":"Dermatological signs can mask underlying nerve issues."},{"id":"c","text":"Skin type affects nerve conduction studies."},{"id":"d","text":"Nerve lesions can cause skin changes."}],"answerId":"d","explanation":"Nerve lesions, such as those affecting the median or ulnar nerves, can lead to skin changes like atrophy or altered sensation in the affected areas.","kind":"integration","linkedModuleIds":["hand-nerve-lesions"],"origin":"ai"},{"id":"skin-examination-approach~ai-7","moduleId":"skin-examination-approach","stem":"What is the significance of using diascopy in dermatological examinations?","options":[{"id":"a","text":"To assess skin hydration"},{"id":"b","text":"To differentiate between erythema and purpura"},{"id":"c","text":"To evaluate systemic diseases"},{"id":"d","text":"To measure lesion size"}],"answerId":"b","explanation":"Diascopy helps distinguish between erythema, which blanches, and purpura, which does not, aiding in diagnosis.","kind":"integration","linkedModuleIds":["dermatologic-investigations"],"origin":"ai"}],"skin-neoplasms":[{"id":"skin-neoplasms~ai-0","moduleId":"skin-neoplasms","stem":"What is the most common type of skin cancer?","options":[{"id":"a","text":"Melanoma"},{"id":"b","text":"Basal cell carcinoma"},{"id":"c","text":"Squamous cell carcinoma"},{"id":"d","text":"Keratoacanthoma"}],"answerId":"b","explanation":"Basal cell carcinoma (BCC) is the most common skin cancer, characterized by slow growth and a low risk of metastasis.","kind":"recall","origin":"ai"},{"id":"skin-neoplasms~ai-1","moduleId":"skin-neoplasms","stem":"Which feature is most indicative of melanoma according to the ABCDE rule?","options":[{"id":"a","text":"Diameter >6 mm"},{"id":"b","text":"Pearly papule"},{"id":"c","text":"Firm scaly nodule"},{"id":"d","text":"Central ulceration"}],"answerId":"a","explanation":"Diameter >6 mm is one of the key features of melanoma in the ABCDE rule for assessing pigmented lesions.","kind":"recall","origin":"ai"},{"id":"skin-neoplasms~ai-2","moduleId":"skin-neoplasms","stem":"What is the primary mechanism by which UV radiation contributes to skin cancer?","options":[{"id":"a","text":"Increased melanin production"},{"id":"b","text":"Direct DNA damage"},{"id":"c","text":"Inhibition of apoptosis"},{"id":"d","text":"Immune suppression"}],"answerId":"b","explanation":"UV radiation causes direct DNA damage, leading to mutations that can result in skin cancer.","kind":"mechanism","origin":"ai"},{"id":"skin-neoplasms~ai-3","moduleId":"skin-neoplasms","stem":"A patient presents with a firm, scaly nodule on their lip. What is the most likely diagnosis?","options":[{"id":"a","text":"Basal cell carcinoma"},{"id":"b","text":"Squamous cell carcinoma"},{"id":"c","text":"Melanoma"},{"id":"d","text":"Actinic keratosis"}],"answerId":"b","explanation":"A firm, scaly nodule on the lip is characteristic of squamous cell carcinoma, which can metastasize.","kind":"clinical","origin":"ai"},{"id":"skin-neoplasms~ai-4","moduleId":"skin-neoplasms","stem":"Which statement about basal cell carcinoma (BCC) is true?","options":[{"id":"a","text":"It commonly metastasizes"},{"id":"b","text":"It is the most common skin cancer"},{"id":"c","text":"It arises from actinic keratosis"},{"id":"d","text":"It presents as a flat scaly lesion"}],"answerId":"b","explanation":"BCC is indeed the most common skin cancer and is known for its low metastatic potential.","kind":"trap","origin":"ai"},{"id":"skin-neoplasms~ai-5","moduleId":"skin-neoplasms","stem":"How does Breslow thickness relate to melanoma prognosis?","options":[{"id":"a","text":"It indicates the presence of metastasis"},{"id":"b","text":"It correlates with the depth of invasion"},{"id":"c","text":"It determines the need for chemotherapy"},{"id":"d","text":"It is irrelevant to prognosis"}],"answerId":"b","explanation":"Breslow thickness measures the depth of invasion and is the single strongest prognostic factor in melanoma.","kind":"recall","origin":"ai"},{"id":"skin-neoplasms~ai-6","moduleId":"skin-neoplasms","stem":"A patient with a history of actinic keratosis presents with a new ulcerated lesion on sun-exposed skin. What is the most likely diagnosis?","options":[{"id":"a","text":"Basal cell carcinoma"},{"id":"b","text":"Squamous cell carcinoma"},{"id":"c","text":"Melanoma"},{"id":"d","text":"Keratoacanthoma"}],"answerId":"b","explanation":"The ulcerated lesion on sun-exposed skin in a patient with actinic keratosis suggests squamous cell carcinoma, which can arise from such lesions.","kind":"clinical","origin":"ai"},{"id":"skin-neoplasms~ai-7","moduleId":"skin-neoplasms","stem":"How does the risk of metastasis differ between basal cell carcinoma and melanoma?","options":[{"id":"a","text":"Both have similar risks"},{"id":"b","text":"BCC rarely metastasizes, melanoma frequently does"},{"id":"c","text":"BCC frequently metastasizes, melanoma rarely does"},{"id":"d","text":"Both are equally fatal"}],"answerId":"b","explanation":"Basal cell carcinoma is locally invasive but almost never metastasizes, while melanoma has a high risk of metastasis.","kind":"trap","origin":"ai"},{"id":"skin-neoplasms~ai-8","moduleId":"skin-neoplasms","stem":"Which skin cancer is most likely to be associated with immunosuppression?","options":[{"id":"a","text":"Basal cell carcinoma"},{"id":"b","text":"Squamous cell carcinoma"},{"id":"c","text":"Melanoma"},{"id":"d","text":"Keratoacanthoma"}],"answerId":"b","explanation":"Squamous cell carcinoma is more likely to metastasize and is associated with immunosuppression, particularly in high-risk areas.","kind":"integration","linkedModuleIds":["keratinocyte-carcinomas"],"origin":"ai"},{"id":"skin-neoplasms~ai-9","moduleId":"skin-neoplasms","stem":"What is the primary preventive measure against skin cancer related to UV exposure?","options":[{"id":"a","text":"Regular skin examinations"},{"id":"b","text":"Photoprotection"},{"id":"c","text":"Topical chemotherapy"},{"id":"d","text":"Surgical excision"}],"answerId":"b","explanation":"Photoprotection is the primary preventive measure against skin cancer caused by UV exposure.","kind":"integration","linkedModuleIds":["photoaging-photoprotection"],"origin":"ai"}],"epidermis-keratinocyte-biology":[{"id":"epidermis-keratinocyte-biology~ai-0","moduleId":"epidermis-keratinocyte-biology","stem":"What is the primary function of keratinocytes in the epidermis?","options":[{"id":"a","text":"Produce melanin"},{"id":"b","text":"Form a barrier against pathogens"},{"id":"c","text":"Synthesize collagen"},{"id":"d","text":"Regulate skin temperature"}],"answerId":"b","explanation":"Keratinocytes form a barrier against pathogens by undergoing keratinization and creating a protective outer layer.","kind":"recall","origin":"ai"},{"id":"epidermis-keratinocyte-biology~ai-1","moduleId":"epidermis-keratinocyte-biology","stem":"Which layer of the epidermis contains the most mature keratinocytes?","options":[{"id":"a","text":"Stratum basale"},{"id":"b","text":"Stratum spinosum"},{"id":"c","text":"Stratum granulosum"},{"id":"d","text":"Stratum corneum"}],"answerId":"d","explanation":"The stratum corneum contains the most mature keratinocytes, which are dead, flattened cells that provide a barrier.","kind":"recall","origin":"ai"},{"id":"epidermis-keratinocyte-biology~ai-2","moduleId":"epidermis-keratinocyte-biology","stem":"In psoriasis, what histological finding is typically observed in the stratum corneum?","options":[{"id":"a","text":"Absence of keratinocytes"},{"id":"b","text":"Retained nuclei"},{"id":"c","text":"Increased melanin"},{"id":"d","text":"Thickened hemidesmosomes"}],"answerId":"b","explanation":"Psoriasis is characterized by parakeratosis, which is the retention of nuclei in the stratum corneum due to accelerated keratinocyte turnover.","kind":"recall","origin":"ai"},{"id":"epidermis-keratinocyte-biology~ai-3","moduleId":"epidermis-keratinocyte-biology","stem":"What is the role of desmosomes in the epidermis?","options":[{"id":"a","text":"Anchor keratinocytes to the basement membrane"},{"id":"b","text":"Facilitate keratinocyte proliferation"},{"id":"c","text":"Link keratinocytes to each other"},{"id":"d","text":"Transfer melanin to keratinocytes"}],"answerId":"c","explanation":"Desmosomes link keratinocytes to each other, providing structural integrity to the epidermis.","kind":"mechanism","origin":"ai"},{"id":"epidermis-keratinocyte-biology~ai-4","moduleId":"epidermis-keratinocyte-biology","stem":"Which condition is characterized by intra-epidermal blistering due to loss of keratinocyte adhesion?","options":[{"id":"a","text":"Bullous pemphigoid"},{"id":"b","text":"Pemphigus vulgaris"},{"id":"c","text":"Ichthyosis"},{"id":"d","text":"Psoriasis"}],"answerId":"b","explanation":"Pemphigus vulgaris is characterized by intra-epidermal blistering due to the loss of adhesion between keratinocytes.","kind":"clinical","origin":"ai"},{"id":"epidermis-keratinocyte-biology~ai-5","moduleId":"epidermis-keratinocyte-biology","stem":"How does melanin protect keratinocyte DNA from UV damage?","options":[{"id":"a","text":"Absorbs UV light"},{"id":"b","text":"Reflects UV light"},{"id":"c","text":"Increases keratin production"},{"id":"d","text":"Promotes cell division"}],"answerId":"a","explanation":"Melanin absorbs UV light, thereby protecting keratinocyte DNA from damage that can lead to skin cancer.","kind":"mechanism","origin":"ai"},{"id":"epidermis-keratinocyte-biology~ai-6","moduleId":"epidermis-keratinocyte-biology","stem":"Which of the following best describes the relationship between keratinocytes and melanocytes?","options":[{"id":"a","text":"Melanocytes are more numerous than keratinocytes"},{"id":"b","text":"Keratinocytes produce melanin"},{"id":"c","text":"Melanocytes transfer melanin to keratinocytes"},{"id":"d","text":"Keratinocytes protect melanocytes from UV"}],"answerId":"c","explanation":"Melanocytes synthesize melanin and transfer it to keratinocytes, where it forms a protective cap over the nucleus.","kind":"trap","origin":"ai"},{"id":"epidermis-keratinocyte-biology~ai-7","moduleId":"epidermis-keratinocyte-biology","stem":"What is the primary defect in ichthyosis related to keratinocyte biology?","options":[{"id":"a","text":"Excessive melanin production"},{"id":"b","text":"Disordered keratinization"},{"id":"c","text":"Increased desmosome formation"},{"id":"d","text":"Decreased keratinocyte proliferation"}],"answerId":"b","explanation":"Ichthyosis is characterized by disordered keratinization, leading to scaling and thickened skin.","kind":"integration","linkedModuleIds":["vesiculobullous-diseases"],"origin":"ai"},{"id":"epidermis-keratinocyte-biology~ai-8","moduleId":"epidermis-keratinocyte-biology","stem":"How do hemidesmosomes differ from desmosomes in the epidermis?","options":[{"id":"a","text":"Hemidesmosomes link keratinocytes to each other"},{"id":"b","text":"Desmosomes anchor basal cells to the basement membrane"},{"id":"c","text":"Hemidesmosomes anchor basal cells to the basement membrane"},{"id":"d","text":"Desmosomes are involved in melanin transfer"}],"answerId":"c","explanation":"Hemidesmosomes anchor basal cells to the basement membrane, while desmosomes link keratinocytes to each other.","kind":"integration","linkedModuleIds":["membranes-and-epidermis"],"origin":"ai"}],"skin-barrier-function":[{"id":"skin-barrier-function~ai-0","moduleId":"skin-barrier-function","stem":"What is the primary structural component of the stratum corneum that contributes to the skin's permeability barrier?","options":[{"id":"a","text":"Ceramides"},{"id":"b","text":"Corneocytes"},{"id":"c","text":"Cholesterol"},{"id":"d","text":"Free fatty acids"}],"answerId":"b","explanation":"Corneocytes, which are rich in keratin and filaggrin, serve as the 'bricks' in the skin's permeability barrier.","kind":"recall","origin":"ai"},{"id":"skin-barrier-function~ai-1","moduleId":"skin-barrier-function","stem":"Which condition is most directly associated with loss-of-function mutations in filaggrin?","options":[{"id":"a","text":"Psoriasis"},{"id":"b","text":"Ichthyosis vulgaris"},{"id":"c","text":"Contact dermatitis"},{"id":"d","text":"Seborrheic dermatitis"}],"answerId":"b","explanation":"Loss-of-function mutations in filaggrin lead to ichthyosis vulgaris and predispose individuals to atopic dermatitis.","kind":"recall","origin":"ai"},{"id":"skin-barrier-function~ai-2","moduleId":"skin-barrier-function","stem":"A patient presents with dry skin and increased transepidermal water loss. What underlying mechanism is likely responsible?","options":[{"id":"a","text":"Increased ceramide production"},{"id":"b","text":"Barrier dysfunction"},{"id":"c","text":"Excessive hydration"},{"id":"d","text":"Increased lipid synthesis"}],"answerId":"b","explanation":"Increased transepidermal water loss is indicative of barrier dysfunction, particularly in the stratum corneum.","kind":"clinical","origin":"ai"},{"id":"skin-barrier-function~ai-3","moduleId":"skin-barrier-function","stem":"Which of the following best explains the role of emollients in managing atopic dermatitis?","options":[{"id":"a","text":"They reduce inflammation directly"},{"id":"b","text":"They repair the skin barrier"},{"id":"c","text":"They increase ceramide production"},{"id":"d","text":"They enhance immune response"}],"answerId":"b","explanation":"Emollients primarily function to repair the skin barrier, reducing transepidermal water loss and preventing flare-ups.","kind":"mechanism","origin":"ai"},{"id":"skin-barrier-function~ai-4","moduleId":"skin-barrier-function","stem":"What is a common misconception regarding the treatment of eczema?","options":[{"id":"a","text":"Only steroids are needed during flares"},{"id":"b","text":"Barrier defects are secondary to inflammation"},{"id":"c","text":"Emollients should be used continuously"},{"id":"d","text":"Dry skin is not related to eczema"}],"answerId":"b","explanation":"A barrier defect, such as filaggrin loss, is a primary driver of eczema, and treating it is essential for long-term management.","kind":"trap","origin":"ai"},{"id":"skin-barrier-function~ai-5","moduleId":"skin-barrier-function","stem":"How does the skin microbiome contribute to the skin barrier function?","options":[{"id":"a","text":"By producing ceramides"},{"id":"b","text":"By enhancing transepidermal water loss"},{"id":"c","text":"By competing with pathogens"},{"id":"d","text":"By increasing skin pH"}],"answerId":"c","explanation":"The skin microbiome helps maintain barrier function by competing with pathogens and supporting immune responses.","kind":"integration","linkedModuleIds":["skin-immune-system-cells"],"origin":"ai"},{"id":"skin-barrier-function~ai-6","moduleId":"skin-barrier-function","stem":"In patients with atopic dermatitis, what is the primary effect of using emollients regularly?","options":[{"id":"a","text":"Increase skin hydration"},{"id":"b","text":"Reduce inflammation"},{"id":"c","text":"Enhance immune response"},{"id":"d","text":"Prevent bacterial infections"}],"answerId":"a","explanation":"Regular use of emollients primarily increases skin hydration by repairing the barrier, which is foundational in managing atopic dermatitis.","kind":"integration","linkedModuleIds":["atopic-dermatitis-clinical"],"origin":"ai"}],"cutaneous-lupus-dermatomyositis":[{"id":"cutaneous-lupus-dermatomyositis~ai-0","moduleId":"cutaneous-lupus-dermatomyositis","stem":"Which of the following is a characteristic feature of acute cutaneous lupus erythematosus?","options":[{"id":"a","text":"Photosensitive malar rash sparing the nasolabial folds"},{"id":"b","text":"Scarring disc-shaped plaques"},{"id":"c","text":"Annular lesions with anti-Ro antibodies"},{"id":"d","text":"Heliotrope rash with proximal weakness"}],"answerId":"a","explanation":"Acute cutaneous lupus erythematosus is characterized by a photosensitive malar rash that spares the nasolabial folds.","kind":"recall","origin":"ai"},{"id":"cutaneous-lupus-dermatomyositis~ai-1","moduleId":"cutaneous-lupus-dermatomyositis","stem":"What is the primary mechanism behind the skin manifestations of dermatomyositis?","options":[{"id":"a","text":"Photosensitivity leading to rash"},{"id":"b","text":"Autoantibody-mediated damage"},{"id":"c","text":"Viral infection of skin cells"},{"id":"d","text":"Genetic predisposition to skin lesions"}],"answerId":"b","explanation":"Dermatomyositis skin manifestations are primarily due to autoantibody-mediated damage.","kind":"mechanism","origin":"ai"},{"id":"cutaneous-lupus-dermatomyositis~ai-2","moduleId":"cutaneous-lupus-dermatomyositis","stem":"A patient presents with a violaceous rash on the eyelids and knuckles, along with proximal muscle weakness. What is the most likely diagnosis?","options":[{"id":"a","text":"Acute cutaneous lupus"},{"id":"b","text":"Discoid lupus erythematosus"},{"id":"c","text":"Dermatomyositis"},{"id":"d","text":"Subacute cutaneous lupus"}],"answerId":"c","explanation":"The combination of heliotrope rash, Gottron papules, and proximal muscle weakness is characteristic of dermatomyositis.","kind":"clinical","origin":"ai"},{"id":"cutaneous-lupus-dermatomyositis~ai-3","moduleId":"cutaneous-lupus-dermatomyositis","stem":"Which of the following findings would most likely prompt cancer screening in an adult patient?","options":[{"id":"a","text":"Malar rash"},{"id":"b","text":"Gottron papules"},{"id":"c","text":"Discoid plaques"},{"id":"d","text":"Annular lesions"}],"answerId":"b","explanation":"Adult dermatomyositis is associated with an increased risk of malignancy, prompting cancer screening.","kind":"trap","origin":"ai"},{"id":"cutaneous-lupus-dermatomyositis~ai-4","moduleId":"cutaneous-lupus-dermatomyositis","stem":"What is the risk associated with subacute cutaneous lupus erythematosus?","options":[{"id":"a","text":"Systemic lupus erythematosus"},{"id":"b","text":"Neonatal lupus and congenital heart block"},{"id":"c","text":"Scarring alopecia"},{"id":"d","text":"Dermatomyositis"}],"answerId":"b","explanation":"Subacute cutaneous lupus erythematosus is associated with anti-Ro antibodies and carries a risk of neonatal lupus and congenital heart block.","kind":"recall","origin":"ai"},{"id":"cutaneous-lupus-dermatomyositis~ai-5","moduleId":"cutaneous-lupus-dermatomyositis","stem":"How does the photosensitivity in cutaneous lupus differ from that in dermatomyositis?","options":[{"id":"a","text":"Both conditions have similar photosensitivity mechanisms"},{"id":"b","text":"Cutaneous lupus is more severe"},{"id":"c","text":"Dermatomyositis does not involve photosensitivity"},{"id":"d","text":"Only cutaneous lupus requires photoprotection"}],"answerId":"a","explanation":"Both cutaneous lupus and dermatomyositis exhibit photosensitivity, but the specific manifestations differ.","kind":"integration","linkedModuleIds":["photoaging-photoprotection"],"origin":"ai"},{"id":"cutaneous-lupus-dermatomyositis~ai-6","moduleId":"cutaneous-lupus-dermatomyositis","stem":"Which skin manifestation is most likely to lead to scarring in patients with lupus?","options":[{"id":"a","text":"Malar rash"},{"id":"b","text":"Discoid plaques"},{"id":"c","text":"Heliotrope rash"},{"id":"d","text":"Gottron papules"}],"answerId":"b","explanation":"Discoid lupus erythematosus is characterized by scarring, atrophic plaques.","kind":"integration","linkedModuleIds":["alopecia-clinical-approach"],"origin":"ai"}],"scabies-pediculosis-clinical":[{"id":"scabies-pediculosis-clinical~ai-0","moduleId":"scabies-pediculosis-clinical","stem":"What is the primary causative agent of scabies?","options":[{"id":"a","text":"Sarcoptes scabiei"},{"id":"b","text":"Pediculus humanus"},{"id":"c","text":"Demodex folliculorum"},{"id":"d","text":"Ascaris lumbricoides"}],"answerId":"a","explanation":"Scabies is caused by the mite Sarcoptes scabiei.","kind":"recall","origin":"ai"},{"id":"scabies-pediculosis-clinical~ai-1","moduleId":"scabies-pediculosis-clinical","stem":"Which of the following is a pathognomonic sign of scabies?","options":[{"id":"a","text":"Nits on hair shafts"},{"id":"b","text":"Burrows in skin"},{"id":"c","text":"Thick crusts on skin"},{"id":"d","text":"Erythema nodosum"}],"answerId":"b","explanation":"Burrows in the skin, particularly in web spaces, are characteristic of scabies.","kind":"recall","origin":"ai"},{"id":"scabies-pediculosis-clinical~ai-2","moduleId":"scabies-pediculosis-clinical","stem":"What is the mechanism behind the persistent itch after successful scabies treatment?","options":[{"id":"a","text":"Reinfestation"},{"id":"b","text":"Delayed hypersensitivity"},{"id":"c","text":"Treatment failure"},{"id":"d","text":"Secondary bacterial infection"}],"answerId":"b","explanation":"The persistent itch is due to a delayed hypersensitivity reaction, not treatment failure.","kind":"mechanism","origin":"ai"},{"id":"scabies-pediculosis-clinical~ai-3","moduleId":"scabies-pediculosis-clinical","stem":"Which treatment is recommended for crusted scabies?","options":[{"id":"a","text":"Topical permethrin only"},{"id":"b","text":"Oral ivermectin only"},{"id":"c","text":"Topical and oral ivermectin"},{"id":"d","text":"No treatment is necessary"}],"answerId":"c","explanation":"Crusted scabies requires a combination of topical and repeated oral ivermectin due to the high mite load.","kind":"recall","origin":"ai"},{"id":"scabies-pediculosis-clinical~ai-4","moduleId":"scabies-pediculosis-clinical","stem":"A child presents with intense itching and nits in their hair. What is the most likely diagnosis?","options":[{"id":"a","text":"Scabies"},{"id":"b","text":"Head lice"},{"id":"c","text":"Body lice"},{"id":"d","text":"Crusted scabies"}],"answerId":"b","explanation":"Nits cemented to hair shafts are indicative of head lice (pediculosis capitis).","kind":"clinical","origin":"ai"},{"id":"scabies-pediculosis-clinical~ai-5","moduleId":"scabies-pediculosis-clinical","stem":"In the context of scabies, what is the importance of treating all close contacts simultaneously?","options":[{"id":"a","text":"To prevent secondary infections"},{"id":"b","text":"To avoid reinfestation"},{"id":"c","text":"To enhance treatment efficacy"},{"id":"d","text":"To reduce itching"}],"answerId":"b","explanation":"Treating all close contacts prevents reinfestation, commonly referred to as 'ping-pong' transmission.","kind":"trap","origin":"ai"},{"id":"scabies-pediculosis-clinical~ai-6","moduleId":"scabies-pediculosis-clinical","stem":"How do the treatment strategies for scabies and helminthic infections differ?","options":[{"id":"a","text":"Both use topical agents"},{"id":"b","text":"Scabies requires treating contacts, helminths do not"},{"id":"c","text":"Helminths are treated with emollients"},{"id":"d","text":"Scabies requires oral agents only"}],"answerId":"b","explanation":"Scabies treatment includes treating contacts to prevent reinfestation, which is not a standard practice for helminthic infections.","kind":"integration","linkedModuleIds":["anthelmintic-agents"],"origin":"ai"},{"id":"scabies-pediculosis-clinical~ai-7","moduleId":"scabies-pediculosis-clinical","stem":"Which of the following findings would suggest a diagnosis of crusted scabies rather than typical scabies?","options":[{"id":"a","text":"Burrows in finger web spaces"},{"id":"b","text":"Persistent itch after treatment"},{"id":"c","text":"Thick hyperkeratotic crusts"},{"id":"d","text":"Nits on hair shafts"}],"answerId":"c","explanation":"Thick hyperkeratotic crusts are characteristic of crusted scabies, especially in immunosuppressed individuals.","kind":"integration","linkedModuleIds":["medical-mites-acarology"],"origin":"ai"}],"cutaneous-hypersensitivity-reactions":[{"id":"cutaneous-hypersensitivity-reactions~ai-0","moduleId":"cutaneous-hypersensitivity-reactions","stem":"What is the primary immunological mechanism involved in Type I hypersensitivity reactions?","options":[{"id":"a","text":"IgG-mediated response"},{"id":"b","text":"IgE-mediated response"},{"id":"c","text":"T-cell mediated response"},{"id":"d","text":"Complement-mediated response"}],"answerId":"b","explanation":"Type I hypersensitivity reactions are primarily mediated by IgE antibodies that trigger mast cell degranulation.","kind":"recall","origin":"ai"},{"id":"cutaneous-hypersensitivity-reactions~ai-1","moduleId":"cutaneous-hypersensitivity-reactions","stem":"A patient presents with itchy wheals that resolve within 24 hours. What is the most likely diagnosis?","options":[{"id":"a","text":"Allergic contact dermatitis"},{"id":"b","text":"Type I urticaria"},{"id":"c","text":"Type IV hypersensitivity reaction"},{"id":"d","text":"Irritant contact dermatitis"}],"answerId":"b","explanation":"The transient itchy wheals that resolve within 24 hours are characteristic of Type I urticaria.","kind":"recall","origin":"ai"},{"id":"cutaneous-hypersensitivity-reactions~ai-2","moduleId":"cutaneous-hypersensitivity-reactions","stem":"Which type of hypersensitivity reaction is characterized by delayed onset and requires prior sensitization?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"d","explanation":"Type IV hypersensitivity reactions are delayed and require prior sensitization, as seen in allergic contact dermatitis.","kind":"recall","origin":"ai"},{"id":"cutaneous-hypersensitivity-reactions~ai-3","moduleId":"cutaneous-hypersensitivity-reactions","stem":"A patient develops a rash 48 hours after contact with poison ivy. What is the most appropriate test to confirm the diagnosis?","options":[{"id":"a","text":"Skin prick test"},{"id":"b","text":"Patch test"},{"id":"c","text":"Serum IgE levels"},{"id":"d","text":"Direct immunofluorescence"}],"answerId":"b","explanation":"A patch test is used to confirm allergic contact dermatitis, which is a Type IV hypersensitivity reaction.","kind":"mechanism","origin":"ai"},{"id":"cutaneous-hypersensitivity-reactions~ai-4","moduleId":"cutaneous-hypersensitivity-reactions","stem":"Which of the following findings is most indicative of Type III hypersensitivity?","options":[{"id":"a","text":"Transient wheals"},{"id":"b","text":"Itchy dermatitis at a patch test site"},{"id":"c","text":"Palpable purpura"},{"id":"d","text":"Blisters on the skin"}],"answerId":"c","explanation":"Palpable purpura is a classic finding associated with Type III hypersensitivity reactions, such as leukocytoclastic vasculitis.","kind":"recall","origin":"ai"},{"id":"cutaneous-hypersensitivity-reactions~ai-5","moduleId":"cutaneous-hypersensitivity-reactions","stem":"A cleaner develops hand dermatitis without prior sensitization. What is the most likely diagnosis?","options":[{"id":"a","text":"Allergic contact dermatitis"},{"id":"b","text":"Type I urticaria"},{"id":"c","text":"Type IV hypersensitivity"},{"id":"d","text":"Irritant contact dermatitis"}],"answerId":"d","explanation":"Irritant contact dermatitis occurs without prior sensitization and is common in occupational settings.","kind":"recall","origin":"ai"},{"id":"cutaneous-hypersensitivity-reactions~ai-6","moduleId":"cutaneous-hypersensitivity-reactions","stem":"In a patient with a drug allergy, which hypersensitivity type is most likely involved if they develop a rash within minutes of exposure?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"a","explanation":"Type I hypersensitivity reactions occur within minutes and are mediated by IgE and mast cells, often seen in drug allergies.","kind":"integration","linkedModuleIds":["adverse-drug-reactions-allergy"],"origin":"ai"},{"id":"cutaneous-hypersensitivity-reactions~ai-7","moduleId":"cutaneous-hypersensitivity-reactions","stem":"A patient presents with a blistering rash and a history of autoimmune disease. Which type of hypersensitivity is most likely responsible?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"b","explanation":"Type II hypersensitivity involves cytotoxic antibodies, which can lead to autoimmune blistering diseases.","kind":"integration","linkedModuleIds":["cutaneous-drug-reactions"],"origin":"ai"}],"bacterial-skin-infections":[{"id":"bacterial-skin-infections~ai-0","moduleId":"bacterial-skin-infections","stem":"What is the most common causative organism of impetigo?","options":[{"id":"a","text":"Staphylococcus aureus"},{"id":"b","text":"Streptococcus pneumoniae"},{"id":"c","text":"Escherichia coli"},{"id":"d","text":"Pseudomonas aeruginosa"}],"answerId":"a","explanation":"Impetigo is primarily caused by Staphylococcus aureus and Streptococcus pyogenes, with S. aureus being the most common.","kind":"recall","origin":"ai"},{"id":"bacterial-skin-infections~ai-1","moduleId":"bacterial-skin-infections","stem":"Which clinical finding is characteristic of erysipelas?","options":[{"id":"a","text":"Ill-defined erythema"},{"id":"b","text":"Honey-coloured crusts"},{"id":"c","text":"Sharply demarcated, raised, bright-red plaque"},{"id":"d","text":"Fluctuant abscess"}],"answerId":"c","explanation":"Erysipelas presents with a sharply demarcated, raised, bright-red plaque, often accompanied by fever.","kind":"recall","origin":"ai"},{"id":"bacterial-skin-infections~ai-2","moduleId":"bacterial-skin-infections","stem":"What distinguishes necrotising fasciitis from cellulitis?","options":[{"id":"a","text":"Presence of fever"},{"id":"b","text":"Ill-defined erythema"},{"id":"c","text":"Pain out of proportion to skin findings"},{"id":"d","text":"Fluctuant abscess"}],"answerId":"c","explanation":"Necrotising fasciitis is characterized by pain out of proportion to the modest skin findings, indicating a surgical emergency.","kind":"trap","origin":"ai"},{"id":"bacterial-skin-infections~ai-3","moduleId":"bacterial-skin-infections","stem":"What is the first-line treatment for a fluctuant abscess?","options":[{"id":"a","text":"Oral antibiotics"},{"id":"b","text":"Incision and drainage"},{"id":"c","text":"Topical antiseptics"},{"id":"d","text":"Warm compresses"}],"answerId":"b","explanation":"Fluctuant abscesses require incision and drainage for effective treatment, often in conjunction with antibiotics.","kind":"recall","origin":"ai"},{"id":"bacterial-skin-infections~ai-4","moduleId":"bacterial-skin-infections","stem":"Which of the following is a surgical emergency requiring urgent intervention?","options":[{"id":"a","text":"Folliculitis"},{"id":"b","text":"Cellulitis"},{"id":"c","text":"Necrotising fasciitis"},{"id":"d","text":"Impetigo"}],"answerId":"c","explanation":"Necrotising fasciitis is a surgical emergency that requires urgent debridement and broad-spectrum antibiotics.","kind":"recall","origin":"ai"},{"id":"bacterial-skin-infections~ai-5","moduleId":"bacterial-skin-infections","stem":"How does Staphylococcal Scalded Skin Syndrome (SSSS) primarily affect children?","options":[{"id":"a","text":"Causes deep tissue necrosis"},{"id":"b","text":"Leads to honey-crusted lesions"},{"id":"c","text":"Results in widespread skin peeling"},{"id":"d","text":"Induces abscess formation"}],"answerId":"c","explanation":"SSSS causes widespread skin peeling due to the action of exfoliative toxins produced by Staphylococcus aureus.","kind":"mechanism","origin":"ai"},{"id":"bacterial-skin-infections~ai-6","moduleId":"bacterial-skin-infections","stem":"How does the treatment of cellulitis differ from that of necrotising fasciitis?","options":[{"id":"a","text":"Cellulitis requires surgical intervention"},{"id":"b","text":"Necrotising fasciitis requires only antibiotics"},{"id":"c","text":"Cellulitis can be treated with oral antibiotics"},{"id":"d","text":"Necrotising fasciitis is treated with topical agents"}],"answerId":"c","explanation":"Cellulitis can often be treated with oral antibiotics, while necrotising fasciitis requires urgent surgical intervention.","kind":"integration","linkedModuleIds":["antibacterial-cell-wall-agents"],"origin":"ai"},{"id":"bacterial-skin-infections~ai-7","moduleId":"bacterial-skin-infections","stem":"Which bacterial skin infection is most likely to present with systemic toxicity and crepitus?","options":[{"id":"a","text":"Impetigo"},{"id":"b","text":"Erysipelas"},{"id":"c","text":"Cellulitis"},{"id":"d","text":"Necrotising fasciitis"}],"answerId":"d","explanation":"Necrotising fasciitis is characterized by systemic toxicity and crepitus due to gas formation in tissues.","kind":"integration","linkedModuleIds":["skin-infections-bacterial-fungal-viral"],"origin":"ai"}],"severe-cutaneous-drug-reactions":[{"id":"severe-cutaneous-drug-reactions~ai-0","moduleId":"severe-cutaneous-drug-reactions","stem":"What is the primary mechanism underlying Stevens-Johnson syndrome (SJS)?","options":[{"id":"a","text":"IgE-mediated hypersensitivity"},{"id":"b","text":"T-cell-mediated cytotoxicity"},{"id":"c","text":"Complement-mediated lysis"},{"id":"d","text":"Autoantibody formation"}],"answerId":"b","explanation":"SJS is primarily a delayed T-cell-mediated drug reaction leading to keratinocyte apoptosis.","kind":"mechanism","origin":"ai"},{"id":"severe-cutaneous-drug-reactions~ai-1","moduleId":"severe-cutaneous-drug-reactions","stem":"Which drug is most commonly associated with DRESS syndrome?","options":[{"id":"a","text":"Ibuprofen"},{"id":"b","text":"Allopurinol"},{"id":"c","text":"Amoxicillin"},{"id":"d","text":"Metformin"}],"answerId":"b","explanation":"Allopurinol is a well-known culprit of DRESS syndrome, characterized by eosinophilia and systemic symptoms.","kind":"recall","origin":"ai"},{"id":"severe-cutaneous-drug-reactions~ai-2","moduleId":"severe-cutaneous-drug-reactions","stem":"A patient presents with a painful rash, mucosal erosions, and epidermal detachment after starting carbamazepine. What is the most likely diagnosis?","options":[{"id":"a","text":"Drug-induced lupus"},{"id":"b","text":"Stevens-Johnson syndrome"},{"id":"c","text":"Acute generalized exanthematous pustulosis"},{"id":"d","text":"Erythema multiforme"}],"answerId":"b","explanation":"The symptoms are characteristic of Stevens-Johnson syndrome, especially with the history of carbamazepine use.","kind":"clinical","origin":"ai"},{"id":"severe-cutaneous-drug-reactions~ai-3","moduleId":"severe-cutaneous-drug-reactions","stem":"Which finding is a red flag indicating a severe cutaneous adverse reaction (SCAR)?","options":[{"id":"a","text":"Mild rash without fever"},{"id":"b","text":"Skin pain and blistering"},{"id":"c","text":"Localized itching"},{"id":"d","text":"Mild erythema"}],"answerId":"b","explanation":"Skin pain and blistering are red flags that suggest a potential SCAR, necessitating immediate drug cessation.","kind":"trap","origin":"ai"},{"id":"severe-cutaneous-drug-reactions~ai-4","moduleId":"severe-cutaneous-drug-reactions","stem":"What is the appropriate management step for a patient suspected of having SJS/TEN?","options":[{"id":"a","text":"Continue the drug and monitor"},{"id":"b","text":"Administer antihistamines"},{"id":"c","text":"Stop the offending drug immediately"},{"id":"d","text":"Prescribe topical steroids"}],"answerId":"c","explanation":"Immediate cessation of the offending drug is crucial in managing SJS/TEN to prevent further complications.","kind":"recall","origin":"ai"},{"id":"severe-cutaneous-drug-reactions~ai-5","moduleId":"severe-cutaneous-drug-reactions","stem":"A patient develops a widespread rash with fever and facial edema 3 weeks after starting an anticonvulsant. What is the most likely diagnosis?","options":[{"id":"a","text":"Stevens-Johnson syndrome"},{"id":"b","text":"Acute generalized exanthematous pustulosis"},{"id":"c","text":"DRESS syndrome"},{"id":"d","text":"Toxic epidermal necrolysis"}],"answerId":"c","explanation":"The timing and symptoms are consistent with DRESS syndrome, which includes fever and facial edema.","kind":"clinical","origin":"ai"},{"id":"severe-cutaneous-drug-reactions~ai-6","moduleId":"severe-cutaneous-drug-reactions","stem":"How does the mechanism of AGEP differ from that of SJS/TEN?","options":[{"id":"a","text":"AGEP is IgE-mediated"},{"id":"b","text":"AGEP involves eosinophilia"},{"id":"c","text":"AGEP presents with pustules"},{"id":"d","text":"AGEP is always life-threatening"}],"answerId":"c","explanation":"AGEP is characterized by the rapid onset of numerous sterile pustules, differentiating it from SJS/TEN.","kind":"mechanism","origin":"ai"},{"id":"severe-cutaneous-drug-reactions~ai-7","moduleId":"severe-cutaneous-drug-reactions","stem":"How can knowledge of HLA testing from drug hypersensitivity modules aid in managing SCARs?","options":[{"id":"a","text":"It helps in diagnosing all drug allergies"},{"id":"b","text":"It can predict risk for specific drug reactions"},{"id":"c","text":"It eliminates the need for drug cessation"},{"id":"d","text":"It provides a cure for SCARs"}],"answerId":"b","explanation":"HLA testing can identify individuals at risk for specific drug reactions, guiding safer prescribing practices.","kind":"integration","linkedModuleIds":["drug-hypersensitivity-scars"],"origin":"ai"},{"id":"severe-cutaneous-drug-reactions~ai-8","moduleId":"severe-cutaneous-drug-reactions","stem":"In what way does understanding SCARs enhance the management of cutaneous drug reactions?","options":[{"id":"a","text":"It allows for the continuation of all drug therapies"},{"id":"b","text":"It identifies benign rashes that require no intervention"},{"id":"c","text":"It emphasizes the importance of recognizing red flags for urgent action"},{"id":"d","text":"It reduces the need for patient education on drug side effects"}],"answerId":"c","explanation":"Recognizing red flags for SCARs is critical for timely intervention and preventing severe outcomes.","kind":"integration","linkedModuleIds":["cutaneous-drug-reactions"],"origin":"ai"}],"chronic-wounds-leg-ulcers":[{"id":"chronic-wounds-leg-ulcers~ai-0","moduleId":"chronic-wounds-leg-ulcers","stem":"What is the most common cause of chronic leg ulcers?","options":[{"id":"a","text":"Arterial insufficiency"},{"id":"b","text":"Venous hypertension"},{"id":"c","text":"Diabetes mellitus"},{"id":"d","text":"Pressure injury"}],"answerId":"b","explanation":"Venous hypertension is the most common cause of chronic leg ulcers, leading to venous ulcers in the gaiter area.","kind":"recall","origin":"ai"},{"id":"chronic-wounds-leg-ulcers~ai-1","moduleId":"chronic-wounds-leg-ulcers","stem":"Which characteristic finding is associated with arterial ulcers?","options":[{"id":"a","text":"Shallow ulcer with haemosiderin staining"},{"id":"b","text":"Painless ulcer under a callus"},{"id":"c","text":"Painful punched-out ulcer on the toes"},{"id":"d","text":"Ulcer over the sacrum"}],"answerId":"c","explanation":"Arterial ulcers are typically painful and present as punched-out lesions, often located on the toes.","kind":"recall","origin":"ai"},{"id":"chronic-wounds-leg-ulcers~ai-2","moduleId":"chronic-wounds-leg-ulcers","stem":"What is the primary treatment for venous ulcers?","options":[{"id":"a","text":"Debridement"},{"id":"b","text":"Compression therapy"},{"id":"c","text":"Revascularization"},{"id":"d","text":"Offloading"}],"answerId":"b","explanation":"Compression therapy is the primary treatment for venous ulcers to reduce venous hypertension.","kind":"recall","origin":"ai"},{"id":"chronic-wounds-leg-ulcers~ai-3","moduleId":"chronic-wounds-leg-ulcers","stem":"Why is compression therapy contraindicated in arterial ulcers?","options":[{"id":"a","text":"It causes pain"},{"id":"b","text":"It can worsen ischemia"},{"id":"c","text":"It leads to infection"},{"id":"d","text":"It promotes necrosis"}],"answerId":"b","explanation":"Compression can worsen ischemia in arterial ulcers, leading to potential tissue loss.","kind":"mechanism","origin":"ai"},{"id":"chronic-wounds-leg-ulcers~ai-4","moduleId":"chronic-wounds-leg-ulcers","stem":"A patient presents with a non-healing ulcer with a rolled edge. What is the most appropriate next step?","options":[{"id":"a","text":"Apply compression bandaging"},{"id":"b","text":"Perform a biopsy"},{"id":"c","text":"Start antibiotic therapy"},{"id":"d","text":"Increase dietary protein"}],"answerId":"b","explanation":"A non-healing ulcer with atypical features, such as a rolled edge, should be biopsied to rule out malignancy.","kind":"clinical","origin":"ai"},{"id":"chronic-wounds-leg-ulcers~ai-5","moduleId":"chronic-wounds-leg-ulcers","stem":"How does chronic inflammation contribute to the pathophysiology of chronic wounds?","options":[{"id":"a","text":"Increases blood flow"},{"id":"b","text":"Promotes epithelial migration"},{"id":"c","text":"Inhibits healing processes"},{"id":"d","text":"Enhances collagen deposition"}],"answerId":"c","explanation":"Chronic inflammation inhibits healing processes, keeping the wound in a prolonged inflammatory state.","kind":"mechanism","origin":"ai"},{"id":"chronic-wounds-leg-ulcers~ai-6","moduleId":"chronic-wounds-leg-ulcers","stem":"Which of the following is a common feature of diabetic foot ulcers?","options":[{"id":"a","text":"Cold, pulseless foot"},{"id":"b","text":"Shallow ulcer with haemosiderin staining"},{"id":"c","text":"Painless ulcer under a callus"},{"id":"d","text":"Ulcer over the sacrum"}],"answerId":"c","explanation":"Diabetic foot ulcers are often painless and typically occur under pressure points, such as metatarsal heads.","kind":"recall","origin":"ai"},{"id":"chronic-wounds-leg-ulcers~ai-7","moduleId":"chronic-wounds-leg-ulcers","stem":"How does venous ulcer management relate to wound healing mechanisms?","options":[{"id":"a","text":"It promotes angiogenesis"},{"id":"b","text":"It reduces inflammation"},{"id":"c","text":"It enhances epithelialization"},{"id":"d","text":"It improves venous return"}],"answerId":"d","explanation":"Managing venous ulcers primarily involves improving venous return through compression, which aids in healing.","kind":"integration","linkedModuleIds":["wound-healing"],"origin":"ai"},{"id":"chronic-wounds-leg-ulcers~ai-8","moduleId":"chronic-wounds-leg-ulcers","stem":"What systemic factor can exacerbate chronic wounds and is also linked to vascular health?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Hyperglycemia"},{"id":"c","text":"Hyperlipidemia"},{"id":"d","text":"Hypoxia"}],"answerId":"b","explanation":"Hyperglycemia is a systemic factor that can exacerbate chronic wounds and is closely linked to diabetic conditions affecting vascular health.","kind":"integration","linkedModuleIds":["retinal-vascular-occlusions"],"origin":"ai"}],"cutaneous-vasculitis":[{"id":"cutaneous-vasculitis~ai-0","moduleId":"cutaneous-vasculitis","stem":"What is the hallmark clinical finding of small-vessel vasculitis?","options":[{"id":"a","text":"Nodules on the trunk"},{"id":"b","text":"Palpable purpura on dependent areas"},{"id":"c","text":"Ulcers on the feet"},{"id":"d","text":"Livedo reticularis"}],"answerId":"b","explanation":"Palpable purpura on dependent areas, especially the lower legs, is the hallmark of small-vessel vasculitis.","kind":"recall","origin":"ai"},{"id":"cutaneous-vasculitis~ai-1","moduleId":"cutaneous-vasculitis","stem":"Which of the following is a common cause of cutaneous small-vessel vasculitis?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Diabetes mellitus"},{"id":"c","text":"Infection"},{"id":"d","text":"Hyperlipidemia"}],"answerId":"c","explanation":"Infection is one of the common causes of cutaneous small-vessel vasculitis.","kind":"recall","origin":"ai"},{"id":"cutaneous-vasculitis~ai-2","moduleId":"cutaneous-vasculitis","stem":"A child presents with palpable purpura, arthralgia, abdominal pain, and hematuria. What is the most likely diagnosis?","options":[{"id":"a","text":"Polyarteritis nodosa"},{"id":"b","text":"IgA vasculitis"},{"id":"c","text":"Granulomatosis with polyangiitis"},{"id":"d","text":"Cryoglobulinemic vasculitis"}],"answerId":"b","explanation":"These symptoms are characteristic of IgA vasculitis (Henoch-Schönlein purpura).","kind":"clinical","origin":"ai"},{"id":"cutaneous-vasculitis~ai-3","moduleId":"cutaneous-vasculitis","stem":"What histological finding is characteristic of leukocytoclastic vasculitis?","options":[{"id":"a","text":"Fibrin deposition"},{"id":"b","text":"Neutrophil fragments around vessels"},{"id":"c","text":"Granulomatous inflammation"},{"id":"d","text":"Lymphocytic infiltration"}],"answerId":"b","explanation":"The presence of neutrophil fragments, also known as 'nuclear dust', is characteristic of leukocytoclastic vasculitis.","kind":"mechanism","origin":"ai"},{"id":"cutaneous-vasculitis~ai-4","moduleId":"cutaneous-vasculitis","stem":"Why is urinalysis important in a patient with cutaneous vasculitis?","options":[{"id":"a","text":"To assess for skin infection"},{"id":"b","text":"To evaluate for renal involvement"},{"id":"c","text":"To check for liver function"},{"id":"d","text":"To rule out diabetes"}],"answerId":"b","explanation":"Urinalysis is crucial to assess for renal involvement, which can change the prognosis and management of the patient.","kind":"trap","origin":"ai"},{"id":"cutaneous-vasculitis~ai-5","moduleId":"cutaneous-vasculitis","stem":"In a patient with cutaneous vasculitis, which finding would indicate systemic involvement?","options":[{"id":"a","text":"Isolated palpable purpura"},{"id":"b","text":"Nephritis with hematuria"},{"id":"c","text":"Localized skin rash"},{"id":"d","text":"Mild arthralgia"}],"answerId":"b","explanation":"Nephritis with hematuria indicates systemic involvement and necessitates further evaluation.","kind":"clinical","origin":"ai"},{"id":"cutaneous-vasculitis~ai-6","moduleId":"cutaneous-vasculitis","stem":"How does cutaneous vasculitis relate to blood vessel histology?","options":[{"id":"a","text":"It involves only large vessels"},{"id":"b","text":"It is characterized by inflammation of vessel walls"},{"id":"c","text":"It shows no histological changes"},{"id":"d","text":"It is unrelated to blood vessel structure"}],"answerId":"b","explanation":"Cutaneous vasculitis involves inflammation of the walls of small blood vessels, which is a key aspect of its pathology.","kind":"integration","linkedModuleIds":["blood-vessel-histology"],"origin":"ai"},{"id":"cutaneous-vasculitis~ai-7","moduleId":"cutaneous-vasculitis","stem":"Which mechanism underlies the pathology of IgA vasculitis?","options":[{"id":"a","text":"Type I hypersensitivity"},{"id":"b","text":"Type II hypersensitivity"},{"id":"c","text":"Type III hypersensitivity"},{"id":"d","text":"Type IV hypersensitivity"}],"answerId":"c","explanation":"IgA vasculitis is primarily an immune-complex (Type III) hypersensitivity reaction.","kind":"integration","linkedModuleIds":["cutaneous-hypersensitivity-reactions"],"origin":"ai"}],"neonatal-skin-conditions":[{"id":"neonatal-skin-conditions~ai-0","moduleId":"neonatal-skin-conditions","stem":"What is the characteristic finding in erythema toxicum neonatorum?","options":[{"id":"a","text":"Grouped vesicles on an erythematous base"},{"id":"b","text":"Blotchy erythema with pustules"},{"id":"c","text":"Greasy yellow scales on the scalp"},{"id":"d","text":"Blue-grey sacral patches"}],"answerId":"b","explanation":"Erythema toxicum neonatorum presents as blotchy erythema with pustules in a well newborn during the first days of life.","kind":"recall","origin":"ai"},{"id":"neonatal-skin-conditions~ai-1","moduleId":"neonatal-skin-conditions","stem":"Which skin condition in infants is associated with greasy yellow scales on the scalp?","options":[{"id":"a","text":"Erythema toxicum"},{"id":"b","text":"Cradle cap (seborrhoeic dermatitis)"},{"id":"c","text":"Candida nappy dermatitis"},{"id":"d","text":"Atopic dermatitis"}],"answerId":"b","explanation":"Cradle cap, or seborrhoeic dermatitis, is characterized by greasy yellow scales on the scalp and sometimes the face or flexures.","kind":"recall","origin":"ai"},{"id":"neonatal-skin-conditions~ai-2","moduleId":"neonatal-skin-conditions","stem":"A neonate presents with a nappy rash that spares the skin folds. What is the most likely diagnosis?","options":[{"id":"a","text":"Candida nappy dermatitis"},{"id":"b","text":"Irritant nappy dermatitis"},{"id":"c","text":"Erythema toxicum"},{"id":"d","text":"Seborrhoeic dermatitis"}],"answerId":"b","explanation":"Irritant nappy dermatitis typically spares the skin folds and is caused by urine and feces occlusion.","kind":"clinical","origin":"ai"},{"id":"neonatal-skin-conditions~ai-3","moduleId":"neonatal-skin-conditions","stem":"What distinguishes candidal nappy dermatitis from irritant nappy dermatitis?","options":[{"id":"a","text":"Involvement of skin folds with satellite pustules"},{"id":"b","text":"Presence of greasy scales"},{"id":"c","text":"Blotchy erythema"},{"id":"d","text":"Presence of vesicles"}],"answerId":"a","explanation":"Candidal nappy dermatitis involves the skin folds and presents with satellite pustules, unlike irritant dermatitis which spares the folds.","kind":"trap","origin":"ai"},{"id":"neonatal-skin-conditions~ai-4","moduleId":"neonatal-skin-conditions","stem":"A newborn presents with grouped vesicles and erosions on the skin. What is the most critical next step?","options":[{"id":"a","text":"Apply a topical antifungal"},{"id":"b","text":"Perform a viral culture"},{"id":"c","text":"Reassure the parents"},{"id":"d","text":"Start barrier cream"}],"answerId":"b","explanation":"Grouped vesicles and erosions in a neonate suggest herpes simplex virus infection, which is an emergency requiring investigation.","kind":"clinical","origin":"ai"},{"id":"neonatal-skin-conditions~ai-5","moduleId":"neonatal-skin-conditions","stem":"How does atopic dermatitis typically present in infants?","options":[{"id":"a","text":"On the scalp and face"},{"id":"b","text":"On the trunk and limbs"},{"id":"c","text":"On the flexural surfaces"},{"id":"d","text":"On the face and extensor surfaces"}],"answerId":"d","explanation":"Atopic dermatitis in infants commonly affects the face and extensor surfaces before becoming flexural later in childhood.","kind":"recall","origin":"ai"},{"id":"neonatal-skin-conditions~ai-6","moduleId":"neonatal-skin-conditions","stem":"In a case of congenital cataracts due to galactokinase deficiency, which skin condition might be observed in the infant?","options":[{"id":"a","text":"Erythema toxicum"},{"id":"b","text":"Cradle cap"},{"id":"c","text":"Milia"},{"id":"d","text":"Atopic dermatitis"}],"answerId":"c","explanation":"Milia, which are tiny keratin cysts, can be observed in infants with various conditions, including metabolic disorders like galactokinase deficiency.","kind":"integration","linkedModuleIds":["galactokinase-cataracts"],"origin":"ai"},{"id":"neonatal-skin-conditions~ai-7","moduleId":"neonatal-skin-conditions","stem":"Which skin condition might be confused with irritant nappy dermatitis but requires a different treatment approach due to its distinct presentation?","options":[{"id":"a","text":"Erythema toxicum"},{"id":"b","text":"Candida nappy dermatitis"},{"id":"c","text":"Seborrhoeic dermatitis"},{"id":"d","text":"Milia"}],"answerId":"b","explanation":"Candida nappy dermatitis involves the folds with satellite pustules and requires topical antifungal treatment, unlike irritant dermatitis.","kind":"integration","linkedModuleIds":["pediatric-skin-diseases"],"origin":"ai"}],"psoriasis-clinical-management":[{"id":"psoriasis-clinical-management~ai-0","moduleId":"psoriasis-clinical-management","stem":"What is the most common clinical presentation of chronic plaque psoriasis?","options":[{"id":"a","text":"Small drop-like papules"},{"id":"b","text":"Well-demarcated erythematous plaques with silvery scale"},{"id":"c","text":"Erythema over 90% body surface"},{"id":"d","text":"Sterile pustules on palms"}],"answerId":"b","explanation":"Chronic plaque psoriasis typically presents as well-demarcated erythematous plaques with silvery scales, especially on extensor surfaces.","kind":"recall","origin":"ai"},{"id":"psoriasis-clinical-management~ai-1","moduleId":"psoriasis-clinical-management","stem":"Which mechanism is primarily responsible for the pathophysiology of psoriasis?","options":[{"id":"a","text":"Increased collagen synthesis"},{"id":"b","text":"Th17 cell-mediated inflammation"},{"id":"c","text":"Decreased keratinocyte turnover"},{"id":"d","text":"Inhibition of T-cell activation"}],"answerId":"b","explanation":"Psoriasis is characterized by Th17 cell-mediated inflammation leading to accelerated keratinocyte turnover.","kind":"mechanism","origin":"ai"},{"id":"psoriasis-clinical-management~ai-2","moduleId":"psoriasis-clinical-management","stem":"A patient presents with small drop-like papules after a recent sore throat. What type of psoriasis is this indicative of?","options":[{"id":"a","text":"Chronic plaque psoriasis"},{"id":"b","text":"Guttate psoriasis"},{"id":"c","text":"Inverse psoriasis"},{"id":"d","text":"Erythrodermic psoriasis"}],"answerId":"b","explanation":"Guttate psoriasis often follows streptococcal infections and presents as small drop-like papules.","kind":"clinical","origin":"ai"},{"id":"psoriasis-clinical-management~ai-3","moduleId":"psoriasis-clinical-management","stem":"What is the significance of the Auspitz sign in psoriasis?","options":[{"id":"a","text":"Indicates psoriatic arthritis"},{"id":"b","text":"Suggests a drug-induced flare"},{"id":"c","text":"Demonstrates pinpoint bleeding upon scale removal"},{"id":"d","text":"Confirms erythrodermic psoriasis"}],"answerId":"c","explanation":"The Auspitz sign refers to pinpoint bleeding that occurs when scales are removed from psoriatic plaques.","kind":"recall","origin":"ai"},{"id":"psoriasis-clinical-management~ai-4","moduleId":"psoriasis-clinical-management","stem":"Which of the following statements about psoriasis is FALSE?","options":[{"id":"a","text":"Psoriasis is a purely skin problem."},{"id":"b","text":"It can lead to psoriatic arthritis."},{"id":"c","text":"It is associated with increased cardiovascular risk."},{"id":"d","text":"It can be triggered by certain medications."}],"answerId":"a","explanation":"Psoriasis is not just a skin problem; it is a systemic inflammatory disease that can lead to joint issues and other comorbidities.","kind":"trap","origin":"ai"},{"id":"psoriasis-clinical-management~ai-5","moduleId":"psoriasis-clinical-management","stem":"What is the first-line treatment for mild localized psoriasis?","options":[{"id":"a","text":"Systemic biologics"},{"id":"b","text":"Phototherapy"},{"id":"c","text":"Topical corticosteroids and vitamin D analogues"},{"id":"d","text":"Oral methotrexate"}],"answerId":"c","explanation":"Mild localized psoriasis is typically treated with topical corticosteroids and vitamin D analogues.","kind":"recall","origin":"ai"},{"id":"psoriasis-clinical-management~ai-6","moduleId":"psoriasis-clinical-management","stem":"How does the treatment of psoriasis relate to the principles of systemic dermatologic therapy?","options":[{"id":"a","text":"Psoriasis is treated only with topical agents."},{"id":"b","text":"Systemic therapy is reserved for mild cases."},{"id":"c","text":"Moderate to severe psoriasis requires systemic or biologic therapy."},{"id":"d","text":"All psoriasis patients require phototherapy."}],"answerId":"c","explanation":"Moderate to severe psoriasis necessitates systemic or biologic therapy, aligning with principles of systemic dermatologic therapy.","kind":"integration","linkedModuleIds":["systemic-dermatologic-therapy"],"origin":"ai"},{"id":"psoriasis-clinical-management~ai-7","moduleId":"psoriasis-clinical-management","stem":"Which aspect of psoriasis management is crucial due to its systemic nature?","options":[{"id":"a","text":"Focus solely on skin lesions"},{"id":"b","text":"Screen for psoriatic arthritis and comorbidities"},{"id":"c","text":"Only use topical treatments"},{"id":"d","text":"Avoid discussing lifestyle factors"}],"answerId":"b","explanation":"Given that psoriasis is a systemic disease, screening for psoriatic arthritis and other comorbidities is essential in management.","kind":"integration","linkedModuleIds":["papulosquamous-diseases"],"origin":"ai"}],"viral-skin-infections":[{"id":"viral-skin-infections~ai-0","moduleId":"viral-skin-infections","stem":"What is the primary treatment for a patient diagnosed with eczema herpeticum?","options":[{"id":"a","text":"Topical steroids"},{"id":"b","text":"Systemic aciclovir"},{"id":"c","text":"Oral antibiotics"},{"id":"d","text":"Antihistamines"}],"answerId":"b","explanation":"Eczema herpeticum is a dermatological emergency requiring systemic aciclovir for effective treatment.","kind":"recall","origin":"ai"},{"id":"viral-skin-infections~ai-1","moduleId":"viral-skin-infections","stem":"Which of the following is a characteristic clinical finding of herpes zoster?","options":[{"id":"a","text":"Grouped vesicles on an erythematous base"},{"id":"b","text":"Painful dermatomal vesicles not crossing the midline"},{"id":"c","text":"Umbilicated pearly papules"},{"id":"d","text":"Verrucous papules on hands"}],"answerId":"b","explanation":"Herpes zoster presents with painful dermatomal vesicles that do not cross the midline.","kind":"recall","origin":"ai"},{"id":"viral-skin-infections~ai-2","moduleId":"viral-skin-infections","stem":"What is the mechanism of action of aciclovir?","options":[{"id":"a","text":"Inhibition of viral DNA polymerase"},{"id":"b","text":"Inhibition of viral protein synthesis"},{"id":"c","text":"Inhibition of viral entry into cells"},{"id":"d","text":"Inhibition of viral RNA polymerase"}],"answerId":"a","explanation":"Aciclovir inhibits viral DNA polymerase, preventing viral replication.","kind":"mechanism","origin":"ai"},{"id":"viral-skin-infections~ai-3","moduleId":"viral-skin-infections","stem":"A patient presents with painful punched-out erosions over eczematous skin and fever. What is the most likely diagnosis?","options":[{"id":"a","text":"Contact dermatitis"},{"id":"b","text":"Eczema herpeticum"},{"id":"c","text":"Impetigo"},{"id":"d","text":"Psoriasis"}],"answerId":"b","explanation":"The presentation is consistent with eczema herpeticum, a serious complication of eczema.","kind":"clinical","origin":"ai"},{"id":"viral-skin-infections~ai-4","moduleId":"viral-skin-infections","stem":"Which of the following statements about HPV is true?","options":[{"id":"a","text":"All types of HPV cause warts"},{"id":"b","text":"High-risk types are associated with cancer"},{"id":"c","text":"HPV warts are always painful"},{"id":"d","text":"HPV cannot be treated"}],"answerId":"b","explanation":"High-risk types of HPV, such as 16 and 18, are associated with cervical cancer and other malignancies.","kind":"trap","origin":"ai"},{"id":"viral-skin-infections~ai-5","moduleId":"viral-skin-infections","stem":"How does the presentation of molluscum contagiosum differ in immunocompromised patients compared to healthy individuals?","options":[{"id":"a","text":"It is less extensive"},{"id":"b","text":"It presents as flat lesions"},{"id":"c","text":"It can be extensive and persistent"},{"id":"d","text":"It is always asymptomatic"}],"answerId":"c","explanation":"In immunocompromised patients, molluscum contagiosum can present as extensive and persistent lesions.","kind":"trap","origin":"ai"},{"id":"viral-skin-infections~ai-6","moduleId":"viral-skin-infections","stem":"Which of the following viral infections is most likely to present with 'dew-drop' vesicles?","options":[{"id":"a","text":"Herpes simplex virus"},{"id":"b","text":"Varicella-zoster virus"},{"id":"c","text":"Human papillomavirus"},{"id":"d","text":"Molluscum contagiosum"}],"answerId":"b","explanation":"Varicella-zoster virus causes chickenpox, characterized by 'dew-drop' vesicles.","kind":"recall","origin":"ai"},{"id":"viral-skin-infections~ai-7","moduleId":"viral-skin-infections","stem":"How does the management of herpes simplex virus infections relate to the treatment of varicella-zoster virus infections?","options":[{"id":"a","text":"Both require topical steroids"},{"id":"b","text":"Both are treated with systemic aciclovir"},{"id":"c","text":"Both are self-limiting without treatment"},{"id":"d","text":"Both require surgical intervention"}],"answerId":"b","explanation":"Both herpes simplex and varicella-zoster virus infections are treated with systemic aciclovir.","kind":"integration","linkedModuleIds":["herpesvirus-cmv-antivirals"],"origin":"ai"},{"id":"viral-skin-infections~ai-8","moduleId":"viral-skin-infections","stem":"What is a common complication of untreated varicella-zoster virus infection in adults?","options":[{"id":"a","text":"Post-herpetic neuralgia"},{"id":"b","text":"Secondary bacterial infection"},{"id":"c","text":"Eczema herpeticum"},{"id":"d","text":"Molluscum contagiosum"}],"answerId":"a","explanation":"Post-herpetic neuralgia is a common complication following herpes zoster in adults.","kind":"integration","linkedModuleIds":["skin-infections-bacterial-fungal-viral"],"origin":"ai"}],"vascular-birthmarks-genodermatoses":[{"id":"vascular-birthmarks-genodermatoses~ai-0","moduleId":"vascular-birthmarks-genodermatoses","stem":"What is the typical clinical course of an infantile haemangioma?","options":[{"id":"a","text":"It is present at birth and persists indefinitely."},{"id":"b","text":"It appears after birth, proliferates, and then involutes."},{"id":"c","text":"It appears at birth and gradually fades without treatment."},{"id":"d","text":"It is always symptomatic and requires immediate intervention."}],"answerId":"b","explanation":"Infantile haemangiomas typically appear after birth, proliferate for several months, and then involute over the years.","kind":"recall","origin":"ai"},{"id":"vascular-birthmarks-genodermatoses~ai-1","moduleId":"vascular-birthmarks-genodermatoses","stem":"Which of the following birthmarks is associated with Sturge-Weber syndrome?","options":[{"id":"a","text":"Café-au-lait macules"},{"id":"b","text":"Infantile haemangioma"},{"id":"c","text":"Port-wine stain"},{"id":"d","text":"Mongolian spots"}],"answerId":"c","explanation":"A port-wine stain, particularly in the V1 distribution, is associated with Sturge-Weber syndrome.","kind":"recall","origin":"ai"},{"id":"vascular-birthmarks-genodermatoses~ai-2","moduleId":"vascular-birthmarks-genodermatoses","stem":"A 5-year-old presents with six café-au-lait macules and axillary freckling. What condition should be suspected?","options":[{"id":"a","text":"Tuberous sclerosis"},{"id":"b","text":"Neurofibromatosis type 1"},{"id":"c","text":"Epidermolysis bullosa"},{"id":"d","text":"Infantile haemangioma"}],"answerId":"b","explanation":"The presence of six or more café-au-lait macules along with axillary freckling is indicative of Neurofibromatosis type 1.","kind":"clinical","origin":"ai"},{"id":"vascular-birthmarks-genodermatoses~ai-3","moduleId":"vascular-birthmarks-genodermatoses","stem":"What is the primary treatment for a problematic infantile haemangioma?","options":[{"id":"a","text":"Laser therapy"},{"id":"b","text":"Topical steroids"},{"id":"c","text":"Propranolol"},{"id":"d","text":"Surgical excision"}],"answerId":"c","explanation":"Propranolol is the primary treatment for problematic infantile haemangiomas that threaten vision, airway, or feeding.","kind":"recall","origin":"ai"},{"id":"vascular-birthmarks-genodermatoses~ai-4","moduleId":"vascular-birthmarks-genodermatoses","stem":"Which of the following statements about vascular birthmarks is true?","options":[{"id":"a","text":"All vascular birthmarks require immediate treatment."},{"id":"b","text":"Infantile haemangiomas and port-wine stains behave similarly."},{"id":"c","text":"Infantile haemangiomas involute, while port-wine stains persist."},{"id":"d","text":"Port-wine stains can be treated with propranolol."}],"answerId":"c","explanation":"Infantile haemangiomas are vascular tumors that involute, while port-wine stains are malformations that persist.","kind":"trap","origin":"ai"},{"id":"vascular-birthmarks-genodermatoses~ai-5","moduleId":"vascular-birthmarks-genodermatoses","stem":"A patient presents with blistering of the skin from minor trauma since birth. What condition is most likely?","options":[{"id":"a","text":"Neurofibromatosis type 1"},{"id":"b","text":"Epidermolysis bullosa"},{"id":"c","text":"Tuberous sclerosis"},{"id":"d","text":"Infantile haemangioma"}],"answerId":"b","explanation":"Epidermolysis bullosa is characterized by blistering of the skin from minor trauma, often present from birth.","kind":"recall","origin":"ai"},{"id":"vascular-birthmarks-genodermatoses~ai-6","moduleId":"vascular-birthmarks-genodermatoses","stem":"How does the management of a port-wine stain differ from that of an infantile haemangioma?","options":[{"id":"a","text":"Both require immediate surgical intervention."},{"id":"b","text":"Port-wine stains are treated with propranolol, while haemangiomas are not."},{"id":"c","text":"Port-wine stains persist and may require laser treatment, while haemangiomas involute."},{"id":"d","text":"Both conditions are managed with observation only."}],"answerId":"c","explanation":"Port-wine stains persist and may require laser treatment, whereas infantile haemangiomas typically involute and are treated only if problematic.","kind":"trap","origin":"ai"},{"id":"vascular-birthmarks-genodermatoses~ai-7","moduleId":"vascular-birthmarks-genodermatoses","stem":"Which of the following findings is associated with tuberous sclerosis?","options":[{"id":"a","text":"Ash-leaf macules"},{"id":"b","text":"Café-au-lait macules"},{"id":"c","text":"Port-wine stain"},{"id":"d","text":"Blistering skin lesions"}],"answerId":"a","explanation":"Ash-leaf macules are a characteristic finding in tuberous sclerosis.","kind":"recall","origin":"ai"},{"id":"vascular-birthmarks-genodermatoses~ai-8","moduleId":"vascular-birthmarks-genodermatoses","stem":"How does Neurofibromatosis type 1 relate to congenital anomalies?","options":[{"id":"a","text":"It is classified as a vascular malformation."},{"id":"b","text":"It is a genetic disorder with skin manifestations that indicate systemic evaluation."},{"id":"c","text":"It is primarily a benign skin condition."},{"id":"d","text":"It does not require any further investigation."}],"answerId":"b","explanation":"Neurofibromatosis type 1 is a genetic disorder with skin manifestations that warrant systemic evaluation for associated anomalies.","kind":"integration","linkedModuleIds":["congenital-anomaly-classification"],"origin":"ai"},{"id":"vascular-birthmarks-genodermatoses~ai-9","moduleId":"vascular-birthmarks-genodermatoses","stem":"What is a key difference between the management of infantile haemangiomas and congenital melanocytic naevi?","options":[{"id":"a","text":"Both require immediate surgical intervention."},{"id":"b","text":"Infantile haemangiomas may require propranolol, while congenital naevi are typically observed."},{"id":"c","text":"Congenital naevi always require laser treatment."},{"id":"d","text":"Both conditions are treated with topical steroids."}],"answerId":"b","explanation":"Infantile haemangiomas may require propranolol if problematic, while congenital melanocytic naevi are typically observed unless they pose a risk for melanoma.","kind":"integration","linkedModuleIds":["pediatric-skin-diseases"],"origin":"ai"}],"melanoma-clinical":[{"id":"melanoma-clinical~ai-0","moduleId":"melanoma-clinical","stem":"What is the most important feature of melanoma according to the ABCDE criteria?","options":[{"id":"a","text":"Asymmetry"},{"id":"b","text":"Border irregularity"},{"id":"c","text":"Colour variation"},{"id":"d","text":"Evolution/change"}],"answerId":"d","explanation":"Evolution or change in a pigmented lesion is the most critical feature for suspecting melanoma.","kind":"recall","origin":"ai"},{"id":"melanoma-clinical~ai-1","moduleId":"melanoma-clinical","stem":"Which subtype of melanoma is characterized by aggressive early vertical growth?","options":[{"id":"a","text":"Superficial spreading melanoma"},{"id":"b","text":"Nodular melanoma"},{"id":"c","text":"Lentigo maligna"},{"id":"d","text":"Acral lentiginous melanoma"}],"answerId":"b","explanation":"Nodular melanoma is known for its aggressive nature and early vertical growth phase.","kind":"recall","origin":"ai"},{"id":"melanoma-clinical~ai-2","moduleId":"melanoma-clinical","stem":"What is the primary method for accurately staging a suspected melanoma?","options":[{"id":"a","text":"Shave biopsy"},{"id":"b","text":"Excisional biopsy"},{"id":"c","text":"Punch biopsy"},{"id":"d","text":"Fine needle aspiration"}],"answerId":"b","explanation":"Excisional biopsy allows for full thickness removal and accurate measurement of Breslow thickness.","kind":"recall","origin":"ai"},{"id":"melanoma-clinical~ai-3","moduleId":"melanoma-clinical","stem":"A patient presents with a pigmented streak under the nail. Which type of melanoma should be suspected?","options":[{"id":"a","text":"Superficial spreading melanoma"},{"id":"b","text":"Nodular melanoma"},{"id":"c","text":"Lentigo maligna"},{"id":"d","text":"Acral lentiginous melanoma"}],"answerId":"d","explanation":"Acral lentiginous melanoma is the most common type in darker-skinned individuals and can present as a nail streak.","kind":"clinical","origin":"ai"},{"id":"melanoma-clinical~ai-4","moduleId":"melanoma-clinical","stem":"What is the primary prognostic factor for melanoma?","options":[{"id":"a","text":"Ulceration"},{"id":"b","text":"Mitotic rate"},{"id":"c","text":"Breslow thickness"},{"id":"d","text":"Patient age"}],"answerId":"c","explanation":"Breslow thickness, or depth of invasion, is the principal prognostic factor in melanoma.","kind":"recall","origin":"ai"},{"id":"melanoma-clinical~ai-5","moduleId":"melanoma-clinical","stem":"Which statement regarding acral lentiginous melanoma is true?","options":[{"id":"a","text":"It is the least common subtype in darker-skinned individuals."},{"id":"b","text":"It is often diagnosed early."},{"id":"c","text":"It can occur on palms and soles."},{"id":"d","text":"It is primarily sun-related."}],"answerId":"c","explanation":"Acral lentiginous melanoma is the most common subtype in darker-skinned individuals and occurs on non-sun-exposed areas like palms and soles.","kind":"trap","origin":"ai"},{"id":"melanoma-clinical~ai-6","moduleId":"melanoma-clinical","stem":"How does photoaging relate to the risk of melanoma?","options":[{"id":"a","text":"It decreases the risk of melanoma."},{"id":"b","text":"It is unrelated to melanoma risk."},{"id":"c","text":"It increases the risk due to UV damage."},{"id":"d","text":"It only affects keratinocyte cancers."}],"answerId":"c","explanation":"Photoaging increases the risk of melanoma due to cumulative UV damage to the skin.","kind":"integration","linkedModuleIds":["photoaging-photoprotection"],"origin":"ai"},{"id":"melanoma-clinical~ai-7","moduleId":"melanoma-clinical","stem":"In patients with melanoma, what is the significance of Breslow thickness in relation to keratinocyte carcinomas?","options":[{"id":"a","text":"It is irrelevant to keratinocyte carcinomas."},{"id":"b","text":"It is a common staging method for both."},{"id":"c","text":"It indicates a higher risk of keratinocyte cancers."},{"id":"d","text":"It helps differentiate melanoma from keratinocyte cancers."}],"answerId":"d","explanation":"Breslow thickness helps differentiate melanoma from keratinocyte cancers, which have different staging criteria.","kind":"integration","linkedModuleIds":["keratinocyte-carcinomas"],"origin":"ai"}],"hyperpigmentation-melasma":[{"id":"hyperpigmentation-melasma~ai-0","moduleId":"hyperpigmentation-melasma","stem":"What is the primary driver of melasma?","options":[{"id":"a","text":"Hormonal changes"},{"id":"b","text":"Genetic predisposition"},{"id":"c","text":"UV exposure"},{"id":"d","text":"Inflammation"}],"answerId":"c","explanation":"Melasma is primarily driven by UV exposure and hormonal changes, but UV exposure is the key factor.","kind":"recall","origin":"ai"},{"id":"hyperpigmentation-melasma~ai-1","moduleId":"hyperpigmentation-melasma","stem":"Which treatment is essential for managing melasma effectively?","options":[{"id":"a","text":"Topical retinoids"},{"id":"b","text":"Photoprotection"},{"id":"c","text":"Chemical peels"},{"id":"d","text":"Hydroquinone"}],"answerId":"b","explanation":"Photoprotection is essential as UV exposure exacerbates melasma, making it a cornerstone of treatment.","kind":"trap","origin":"ai"},{"id":"hyperpigmentation-melasma~ai-2","moduleId":"hyperpigmentation-melasma","stem":"What type of pigmentation is characterized by brown discoloration accentuated under Wood's lamp?","options":[{"id":"a","text":"Dermal hyperpigmentation"},{"id":"b","text":"Epidermal hyperpigmentation"},{"id":"c","text":"Post-inflammatory hyperpigmentation"},{"id":"d","text":"Melasma"}],"answerId":"b","explanation":"Epidermal hyperpigmentation appears brown and is accentuated under Wood's lamp, indicating it is more treatable.","kind":"recall","origin":"ai"},{"id":"hyperpigmentation-melasma~ai-3","moduleId":"hyperpigmentation-melasma","stem":"A patient presents with slate-grey pigmentation after long-term antibiotic use. What is the likely cause?","options":[{"id":"a","text":"Addison disease"},{"id":"b","text":"Minocycline-induced pigmentation"},{"id":"c","text":"Melasma"},{"id":"d","text":"Post-inflammatory hyperpigmentation"}],"answerId":"b","explanation":"Slate-grey pigmentation is characteristic of minocycline-induced pigmentation, a known side effect of the drug.","kind":"recall","origin":"ai"},{"id":"hyperpigmentation-melasma~ai-4","moduleId":"hyperpigmentation-melasma","stem":"Which of the following conditions is associated with diffuse hyperpigmentation and fatigue?","options":[{"id":"a","text":"Café-au-lait spots"},{"id":"b","text":"Addison disease"},{"id":"c","text":"Acanthosis nigricans"},{"id":"d","text":"Melasma"}],"answerId":"b","explanation":"Diffuse hyperpigmentation with fatigue and hypotension is indicative of Addison disease, related to ACTH/MSH.","kind":"recall","origin":"ai"},{"id":"hyperpigmentation-melasma~ai-5","moduleId":"hyperpigmentation-melasma","stem":"How does post-inflammatory hyperpigmentation typically present?","options":[{"id":"a","text":"Symmetric brown patches on the face"},{"id":"b","text":"Brown discoloration at sites of resolved acne"},{"id":"c","text":"Diffuse hyperpigmentation"},{"id":"d","text":"Slate-grey pigmentation"}],"answerId":"b","explanation":"Post-inflammatory hyperpigmentation presents as brown discoloration at sites of resolved acne, especially in darker skin.","kind":"recall","origin":"ai"},{"id":"hyperpigmentation-melasma~ai-6","moduleId":"hyperpigmentation-melasma","stem":"How does hyperpigmentation relate to systemic diseases like Addison disease?","options":[{"id":"a","text":"It is always localized"},{"id":"b","text":"It can indicate hormonal imbalances"},{"id":"c","text":"It is unrelated to skin signs"},{"id":"d","text":"It is only cosmetic"}],"answerId":"b","explanation":"Hyperpigmentation can indicate systemic diseases like Addison disease, which involves hormonal imbalances affecting pigmentation.","kind":"integration","linkedModuleIds":["skin-signs-systemic-disease"],"origin":"ai"},{"id":"hyperpigmentation-melasma~ai-7","moduleId":"hyperpigmentation-melasma","stem":"Which treatment for melasma is ineffective without adequate sun protection?","options":[{"id":"a","text":"Hydroquinone"},{"id":"b","text":"Chemical peels"},{"id":"c","text":"Topical retinoids"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"All treatments for melasma are ineffective without adequate sun protection, as UV exposure exacerbates the condition.","kind":"integration","linkedModuleIds":["photoaging-photoprotection"],"origin":"ai"}],"topical-dermatologic-therapy":[{"id":"topical-dermatologic-therapy~ai-0","moduleId":"topical-dermatologic-therapy","stem":"What is the primary reason for using a mild topical corticosteroid on the face?","options":[{"id":"a","text":"High risk of systemic absorption"},{"id":"b","text":"Thin, highly absorptive skin"},{"id":"c","text":"Increased risk of atrophy"},{"id":"d","text":"Lower potency needed for efficacy"}],"answerId":"b","explanation":"The face has thin, highly absorptive skin, making it suitable for mild corticosteroids to minimize side effects.","kind":"recall","origin":"ai"},{"id":"topical-dermatologic-therapy~ai-1","moduleId":"topical-dermatologic-therapy","stem":"Which vehicle is most appropriate for treating a dry, lichenified plaque?","options":[{"id":"a","text":"Cream"},{"id":"b","text":"Gel"},{"id":"c","text":"Ointment"},{"id":"d","text":"Solution"}],"answerId":"c","explanation":"Ointments are greasy and occlusive, making them the most potent choice for dry, lichenified lesions.","kind":"mechanism","origin":"ai"},{"id":"topical-dermatologic-therapy~ai-2","moduleId":"topical-dermatologic-therapy","stem":"A patient presents with skin thinning and striae after prolonged use of a potent topical steroid on their face. What is the most likely cause?","options":[{"id":"a","text":"Inappropriate vehicle choice"},{"id":"b","text":"High absorption due to thin skin"},{"id":"c","text":"Incorrect application technique"},{"id":"d","text":"Insufficient treatment duration"}],"answerId":"b","explanation":"Thin facial skin leads to high absorption of potent steroids, resulting in atrophy and side effects.","kind":"clinical","origin":"ai"},{"id":"topical-dermatologic-therapy~ai-3","moduleId":"topical-dermatologic-therapy","stem":"Which of the following is a common side effect of prolonged use of potent topical corticosteroids?","options":[{"id":"a","text":"Hyperpigmentation"},{"id":"b","text":"Striae"},{"id":"c","text":"Acne"},{"id":"d","text":"Erythema"}],"answerId":"b","explanation":"Striae are a well-known side effect of prolonged use of potent topical corticosteroids, especially on thin skin.","kind":"trap","origin":"ai"},{"id":"topical-dermatologic-therapy~ai-4","moduleId":"topical-dermatologic-therapy","stem":"What is the mechanism by which calcineurin inhibitors spare the use of topical corticosteroids?","options":[{"id":"a","text":"Increased hydration"},{"id":"b","text":"Reduced inflammation"},{"id":"c","text":"Decreased absorption"},{"id":"d","text":"Lower potency"}],"answerId":"b","explanation":"Calcineurin inhibitors reduce inflammation without the side effects associated with corticosteroids, making them suitable for sensitive areas.","kind":"mechanism","origin":"ai"},{"id":"topical-dermatologic-therapy~ai-5","moduleId":"topical-dermatologic-therapy","stem":"In the management of acne, which topical agent is commonly used alongside topical corticosteroids?","options":[{"id":"a","text":"Benzoyl peroxide"},{"id":"b","text":"Salicylic acid"},{"id":"c","text":"Mupirocin"},{"id":"d","text":"Calcipotriol"}],"answerId":"a","explanation":"Benzoyl peroxide is frequently used in conjunction with topical corticosteroids for acne treatment.","kind":"integration","linkedModuleIds":["acne-management"],"origin":"ai"},{"id":"topical-dermatologic-therapy~ai-6","moduleId":"topical-dermatologic-therapy","stem":"How does the choice of vehicle impact the efficacy of topical treatments in dermatology?","options":[{"id":"a","text":"It determines the active ingredient's potency"},{"id":"b","text":"It affects the absorption and hydration of the skin"},{"id":"c","text":"It influences the duration of treatment"},{"id":"d","text":"It dictates the frequency of application"}],"answerId":"b","explanation":"The choice of vehicle affects how well the active ingredient is absorbed and how it hydrates the skin, impacting treatment efficacy.","kind":"integration","linkedModuleIds":["systemic-dermatologic-therapy"],"origin":"ai"}],"systemic-dermatologic-therapy":[{"id":"systemic-dermatologic-therapy~ai-0","moduleId":"systemic-dermatologic-therapy","stem":"What is the primary mechanism of action of narrowband UVB phototherapy in treating psoriasis?","options":[{"id":"a","text":"Inhibition of T-cell activation"},{"id":"b","text":"Reduction of epidermal proliferation"},{"id":"c","text":"Induction of apoptosis in keratinocytes"},{"id":"d","text":"Stimulation of melanocyte activity"}],"answerId":"b","explanation":"Narrowband UVB phototherapy primarily reduces epidermal proliferation, making it effective for psoriasis.","kind":"mechanism","origin":"ai"},{"id":"systemic-dermatologic-therapy~ai-1","moduleId":"systemic-dermatologic-therapy","stem":"Which systemic agent is contraindicated in pregnancy due to its teratogenic effects?","options":[{"id":"a","text":"Methotrexate"},{"id":"b","text":"Ciclosporin"},{"id":"c","text":"Acitretin"},{"id":"d","text":"Dupilumab"}],"answerId":"c","explanation":"Acitretin is an oral retinoid that is highly teratogenic and contraindicated in pregnancy.","kind":"recall","origin":"ai"},{"id":"systemic-dermatologic-therapy~ai-2","moduleId":"systemic-dermatologic-therapy","stem":"A patient with severe psoriasis is started on methotrexate. What monitoring is essential during treatment?","options":[{"id":"a","text":"Liver function tests and complete blood count"},{"id":"b","text":"Renal function tests and blood pressure"},{"id":"c","text":"Lipid profile and mood assessment"},{"id":"d","text":"Skin examination for malignancy"}],"answerId":"a","explanation":"Methotrexate requires monitoring of liver function tests and complete blood count due to its hepatotoxicity and myelosuppressive effects.","kind":"recall","origin":"ai"},{"id":"systemic-dermatologic-therapy~ai-3","moduleId":"systemic-dermatologic-therapy","stem":"What is a significant risk associated with starting biologic therapy in a patient with psoriasis?","options":[{"id":"a","text":"Increased risk of skin cancer"},{"id":"b","text":"Reactivation of latent tuberculosis"},{"id":"c","text":"Severe allergic reactions"},{"id":"d","text":"Worsening of psoriasis symptoms"}],"answerId":"b","explanation":"Biologics, particularly anti-TNF agents, can reactivate latent tuberculosis, necessitating screening before initiation.","kind":"clinical","origin":"ai"},{"id":"systemic-dermatologic-therapy~ai-4","moduleId":"systemic-dermatologic-therapy","stem":"Which of the following is a common trap regarding the use of systemic dermatologic drugs?","options":[{"id":"a","text":"They require no special screening before initiation"},{"id":"b","text":"They are safe to use in all patients regardless of comorbidities"},{"id":"c","text":"All systemic agents have the same monitoring requirements"},{"id":"d","text":"They can be used without considering potential drug interactions"}],"answerId":"a","explanation":"Each systemic agent has specific safety requirements and screening protocols that must be followed to prevent serious harm.","kind":"trap","origin":"ai"},{"id":"systemic-dermatologic-therapy~ai-5","moduleId":"systemic-dermatologic-therapy","stem":"A patient with severe eczema is treated with ciclosporin. What is a critical aspect of monitoring during treatment?","options":[{"id":"a","text":"Liver function tests"},{"id":"b","text":"Renal function and blood pressure"},{"id":"c","text":"Complete blood count"},{"id":"d","text":"Lipid levels"}],"answerId":"b","explanation":"Ciclosporin is nephrotoxic, so monitoring renal function and blood pressure is critical during treatment.","kind":"recall","origin":"ai"},{"id":"systemic-dermatologic-therapy~ai-6","moduleId":"systemic-dermatologic-therapy","stem":"How does the mechanism of action of dupilumab differ from traditional systemic immunosuppressants?","options":[{"id":"a","text":"It directly inhibits T-cell proliferation"},{"id":"b","text":"It blocks IL-4 and IL-13 signaling"},{"id":"c","text":"It induces apoptosis in immune cells"},{"id":"d","text":"It enhances the immune response"}],"answerId":"b","explanation":"Dupilumab is a monoclonal antibody that specifically blocks IL-4 and IL-13 signaling, which is a distinct mechanism compared to traditional immunosuppressants.","kind":"integration","linkedModuleIds":["immunosuppressant-drugs"],"origin":"ai"},{"id":"systemic-dermatologic-therapy~ai-7","moduleId":"systemic-dermatologic-therapy","stem":"Which systemic treatment for psoriasis requires screening for latent tuberculosis before initiation?","options":[{"id":"a","text":"Methotrexate"},{"id":"b","text":"Ciclosporin"},{"id":"c","text":"Biologics"},{"id":"d","text":"Acitretin"}],"answerId":"c","explanation":"Biologics, particularly anti-TNF agents, require screening for latent tuberculosis due to the risk of reactivation.","kind":"integration","linkedModuleIds":["psoriasis-clinical-management"],"origin":"ai"}],"acne-management":[{"id":"acne-management~ai-0","moduleId":"acne-management","stem":"What is the first-line topical agent for mild comedonal acne?","options":[{"id":"a","text":"Benzoyl peroxide"},{"id":"b","text":"Clindamycin"},{"id":"c","text":"Adapalene"},{"id":"d","text":"Isotretinoin"}],"answerId":"c","explanation":"Topical retinoids like adapalene are the first-line treatment for mild comedonal acne due to their comedolytic properties.","kind":"recall","origin":"ai"},{"id":"acne-management~ai-1","moduleId":"acne-management","stem":"Why is benzoyl peroxide combined with topical antibiotics in acne treatment?","options":[{"id":"a","text":"To enhance skin hydration"},{"id":"b","text":"To increase antibiotic resistance"},{"id":"c","text":"To limit C. acnes resistance"},{"id":"d","text":"To reduce inflammation"}],"answerId":"c","explanation":"Benzoyl peroxide is combined with topical antibiotics to limit the development of antibiotic resistance in Cutibacterium acnes.","kind":"mechanism","origin":"ai"},{"id":"acne-management~ai-2","moduleId":"acne-management","stem":"Which of the following is a common side effect of isotretinoin?","options":[{"id":"a","text":"Increased appetite"},{"id":"b","text":"Dry skin"},{"id":"c","text":"Weight gain"},{"id":"d","text":"Hyperglycemia"}],"answerId":"b","explanation":"Isotretinoin commonly causes dry skin and mucous membranes as a side effect.","kind":"recall","origin":"ai"},{"id":"acne-management~ai-3","moduleId":"acne-management","stem":"What is the primary reason for avoiding long-term antibiotic monotherapy in acne treatment?","options":[{"id":"a","text":"It is ineffective for all acne types"},{"id":"b","text":"It leads to antibiotic resistance"},{"id":"c","text":"It causes severe side effects"},{"id":"d","text":"It is too expensive"}],"answerId":"b","explanation":"Long-term antibiotic monotherapy can lead to resistance in C. acnes, making future treatments less effective.","kind":"trap","origin":"ai"},{"id":"acne-management~ai-4","moduleId":"acne-management","stem":"In women with moderate-severe acne, which treatment option is appropriate?","options":[{"id":"a","text":"Topical retinoids only"},{"id":"b","text":"Oral isotretinoin only"},{"id":"c","text":"Hormonal therapy"},{"id":"d","text":"Long-term antibiotics"}],"answerId":"c","explanation":"Hormonal therapy, such as combined oral contraceptives or spironolactone, is an appropriate treatment option for women with moderate-severe acne.","kind":"clinical","origin":"ai"},{"id":"acne-management~ai-5","moduleId":"acne-management","stem":"How does isotretinoin affect acne treatment in terms of severity?","options":[{"id":"a","text":"It is used for mild acne only"},{"id":"b","text":"It is a first-line treatment for all acne types"},{"id":"c","text":"It is reserved for severe or treatment-resistant cases"},{"id":"d","text":"It can be used without monitoring"}],"answerId":"c","explanation":"Isotretinoin is reserved for severe or treatment-resistant acne due to its potency and teratogenic effects.","kind":"recall","origin":"ai"},{"id":"acne-management~ai-6","moduleId":"acne-management","stem":"Which topical agent is commonly used in conjunction with oral antibiotics for acne management?","options":[{"id":"a","text":"Benzoyl peroxide"},{"id":"b","text":"Hydrocortisone"},{"id":"c","text":"Salicylic acid"},{"id":"d","text":"Clindamycin alone"}],"answerId":"a","explanation":"Benzoyl peroxide is often used with oral antibiotics to enhance efficacy and reduce resistance.","kind":"integration","linkedModuleIds":["topical-dermatologic-therapy"],"origin":"ai"},{"id":"acne-management~ai-7","moduleId":"acne-management","stem":"What is the primary pathogenic factor targeted by topical retinoids in acne treatment?","options":[{"id":"a","text":"Excess sebum production"},{"id":"b","text":"Follicular keratin plugging"},{"id":"c","text":"C. acnes proliferation"},{"id":"d","text":"Inflammation"}],"answerId":"b","explanation":"Topical retinoids primarily target follicular keratin plugging, helping to normalize keratinization.","kind":"integration","linkedModuleIds":["acne-vulgaris"],"origin":"ai"}],"atopic-dermatitis-clinical":[{"id":"atopic-dermatitis-clinical~ai-0","moduleId":"atopic-dermatitis-clinical","stem":"What is the primary underlying defect in atopic dermatitis?","options":[{"id":"a","text":"Filaggrin mutation"},{"id":"b","text":"Keratinocyte dysfunction"},{"id":"c","text":"Collagen deficiency"},{"id":"d","text":"Sebaceous gland hyperactivity"}],"answerId":"a","explanation":"Atopic dermatitis is primarily associated with a barrier defect due to filaggrin mutations.","kind":"recall","origin":"ai"},{"id":"atopic-dermatitis-clinical~ai-1","moduleId":"atopic-dermatitis-clinical","stem":"Which of the following is a common complication of atopic dermatitis?","options":[{"id":"a","text":"Bacterial superinfection"},{"id":"b","text":"Psoriasis"},{"id":"c","text":"Contact dermatitis"},{"id":"d","text":"Seborrheic dermatitis"}],"answerId":"a","explanation":"Bacterial superinfection, particularly with Staphylococcus aureus, is a common complication in patients with atopic dermatitis.","kind":"recall","origin":"ai"},{"id":"atopic-dermatitis-clinical~ai-2","moduleId":"atopic-dermatitis-clinical","stem":"A 5-year-old child presents with itchy, lichenified dermatitis in the flexural areas and has a history of asthma. What is the most likely diagnosis?","options":[{"id":"a","text":"Atopic dermatitis"},{"id":"b","text":"Contact dermatitis"},{"id":"c","text":"Psoriasis"},{"id":"d","text":"Seborrheic dermatitis"}],"answerId":"a","explanation":"The presentation is characteristic of atopic dermatitis, especially given the history of asthma.","kind":"clinical","origin":"ai"},{"id":"atopic-dermatitis-clinical~ai-3","moduleId":"atopic-dermatitis-clinical","stem":"What is the mechanism of action of dupilumab in treating severe atopic dermatitis?","options":[{"id":"a","text":"Inhibition of IL-1"},{"id":"b","text":"Inhibition of IL-4 and IL-13"},{"id":"c","text":"Inhibition of TNF-alpha"},{"id":"d","text":"Inhibition of IL-6"}],"answerId":"b","explanation":"Dupilumab is a monoclonal antibody that inhibits IL-4 and IL-13, key cytokines in the Th2 response associated with atopic dermatitis.","kind":"mechanism","origin":"ai"},{"id":"atopic-dermatitis-clinical~ai-4","moduleId":"atopic-dermatitis-clinical","stem":"Which of the following is a key feature of eczema herpeticum?","options":[{"id":"a","text":"Honey-crusted lesions"},{"id":"b","text":"Punched-out erosions"},{"id":"c","text":"Lichenification"},{"id":"d","text":"Scaly plaques"}],"answerId":"b","explanation":"Eczema herpeticum is characterized by painful punched-out erosions and can be a medical emergency.","kind":"recall","origin":"ai"},{"id":"atopic-dermatitis-clinical~ai-5","moduleId":"atopic-dermatitis-clinical","stem":"Why are emollients considered the foundation of atopic dermatitis management?","options":[{"id":"a","text":"They are only used during flares"},{"id":"b","text":"They repair the skin barrier continuously"},{"id":"c","text":"They are more effective than steroids"},{"id":"d","text":"They prevent all infections"}],"answerId":"b","explanation":"Emollients repair the skin barrier continuously, reducing flare frequency and steroid requirement.","kind":"trap","origin":"ai"},{"id":"atopic-dermatitis-clinical~ai-6","moduleId":"atopic-dermatitis-clinical","stem":"How does atopic dermatitis relate to the skin barrier function?","options":[{"id":"a","text":"It is caused by excessive sebum production"},{"id":"b","text":"It results from a defect in the skin barrier"},{"id":"c","text":"It is unrelated to skin barrier integrity"},{"id":"d","text":"It is a form of contact dermatitis"}],"answerId":"b","explanation":"Atopic dermatitis is directly related to a defect in the skin barrier, primarily due to filaggrin mutations.","kind":"integration","linkedModuleIds":["skin-barrier-function"],"origin":"ai"},{"id":"atopic-dermatitis-clinical~ai-7","moduleId":"atopic-dermatitis-clinical","stem":"Which condition is most likely to be confused with atopic dermatitis due to similar symptoms?","options":[{"id":"a","text":"Contact dermatitis"},{"id":"b","text":"Psoriasis"},{"id":"c","text":"Seborrheic dermatitis"},{"id":"d","text":"Nummular eczema"}],"answerId":"a","explanation":"Contact dermatitis can present with similar symptoms but is triggered by allergens or irritants, unlike atopic dermatitis.","kind":"integration","linkedModuleIds":["contact-dermatitis-clinical"],"origin":"ai"}],"urinalysis-urine-examination":[{"id":"urinalysis-urine-examination~ai-0","moduleId":"urinalysis-urine-examination","stem":"What is the primary purpose of performing a midstream clean-catch urine collection?","options":[{"id":"a","text":"To obtain the most concentrated sample"},{"id":"b","text":"To minimize contamination"},{"id":"c","text":"To increase urine volume"},{"id":"d","text":"To assess urine pH"}],"answerId":"b","explanation":"A midstream clean-catch urine collection minimizes contamination from the urethra, providing a more accurate sample for analysis.","kind":"recall","origin":"ai"},{"id":"urinalysis-urine-examination~ai-1","moduleId":"urinalysis-urine-examination","stem":"Which urine dipstick finding is most indicative of a urinary tract infection (UTI)?","options":[{"id":"a","text":"Positive leukocyte esterase"},{"id":"b","text":"Positive glucose"},{"id":"c","text":"Positive ketones"},{"id":"d","text":"Positive bilirubin"}],"answerId":"a","explanation":"A positive leukocyte esterase on a dipstick indicates the presence of white blood cells, which is suggestive of a urinary tract infection.","kind":"recall","origin":"ai"},{"id":"urinalysis-urine-examination~ai-2","moduleId":"urinalysis-urine-examination","stem":"What type of casts would you expect to find in a patient with acute tubular necrosis (ATN)?","options":[{"id":"a","text":"Red-cell casts"},{"id":"b","text":"White-cell casts"},{"id":"c","text":"Muddy-brown granular casts"},{"id":"d","text":"Fatty casts"}],"answerId":"c","explanation":"Muddy-brown granular casts are characteristic of acute tubular necrosis, indicating renal parenchymal damage.","kind":"recall","origin":"ai"},{"id":"urinalysis-urine-examination~ai-3","moduleId":"urinalysis-urine-examination","stem":"A patient presents with hematuria and dysmorphic red blood cells on urinalysis. What is the most likely underlying condition?","options":[{"id":"a","text":"Bladder cancer"},{"id":"b","text":"Glomerulonephritis"},{"id":"c","text":"Kidney stones"},{"id":"d","text":"Urinary tract infection"}],"answerId":"b","explanation":"Dysmorphic red blood cells suggest a glomerular source of bleeding, most commonly associated with glomerulonephritis.","kind":"clinical","origin":"ai"},{"id":"urinalysis-urine-examination~ai-4","moduleId":"urinalysis-urine-examination","stem":"Which of the following findings on urinalysis would indicate a lower-tract source of hematuria?","options":[{"id":"a","text":"Dysmorphic red cells"},{"id":"b","text":"Isomorphic red cells"},{"id":"c","text":"Red-cell casts"},{"id":"d","text":"White-cell casts"}],"answerId":"b","explanation":"Isomorphic red cells without casts suggest a lower-tract source of hematuria, such as stones or tumors.","kind":"clinical","origin":"ai"},{"id":"urinalysis-urine-examination~ai-5","moduleId":"urinalysis-urine-examination","stem":"In a patient with nephrotic syndrome, what would you expect to find on urine microscopy?","options":[{"id":"a","text":"Muddy-brown granular casts"},{"id":"b","text":"Fatty casts"},{"id":"c","text":"White-cell casts"},{"id":"d","text":"Red-cell casts"}],"answerId":"b","explanation":"Fatty casts and oval fat bodies are indicative of nephrotic syndrome due to significant proteinuria.","kind":"recall","origin":"ai"},{"id":"urinalysis-urine-examination~ai-6","moduleId":"urinalysis-urine-examination","stem":"How does the presence of muddy-brown granular casts relate to acute kidney injury (AKI)?","options":[{"id":"a","text":"Indicates glomerular disease"},{"id":"b","text":"Suggests acute tubular necrosis"},{"id":"c","text":"Points to interstitial nephritis"},{"id":"d","text":"Reflects urinary tract infection"}],"answerId":"b","explanation":"Muddy-brown granular casts are a hallmark of acute tubular necrosis, a common cause of acute kidney injury.","kind":"integration","linkedModuleIds":["acute-kidney-injury"],"origin":"ai"},{"id":"urinalysis-urine-examination~ai-7","moduleId":"urinalysis-urine-examination","stem":"Which urine dipstick finding is crucial for differentiating between glomerular and urologic sources of hematuria?","options":[{"id":"a","text":"Leukocyte esterase"},{"id":"b","text":"Red blood cells"},{"id":"c","text":"Protein"},{"id":"d","text":"Nitrite"}],"answerId":"c","explanation":"The presence of protein on the dipstick helps distinguish glomerular sources of hematuria from urologic sources.","kind":"integration","linkedModuleIds":["glomerular-disease-overview"],"origin":"ai"}],"renal-defense-mechanisms":[{"id":"renal-defense-mechanisms~ai-0","moduleId":"renal-defense-mechanisms","stem":"What is the principal defense mechanism that maintains urinary tract sterility?","options":[{"id":"a","text":"Antibody-mediated immunity"},{"id":"b","text":"Urine flow and complete bladder emptying"},{"id":"c","text":"Low urine pH"},{"id":"d","text":"Tamm-Horsfall protein"}],"answerId":"b","explanation":"The primary defense against urinary tract infections is the mechanical flushing action of urine flow combined with complete bladder emptying.","kind":"recall","origin":"ai"},{"id":"renal-defense-mechanisms~ai-1","moduleId":"renal-defense-mechanisms","stem":"Which factor is most likely to predispose a patient to urinary tract infections?","options":[{"id":"a","text":"Increased fluid intake"},{"id":"b","text":"Short urethra in females"},{"id":"c","text":"High urine osmolality"},{"id":"d","text":"Regular complete voiding"}],"answerId":"b","explanation":"The shorter urethra in females facilitates easier ascending colonization by pathogens, increasing UTI risk.","kind":"trap","origin":"ai"},{"id":"renal-defense-mechanisms~ai-2","moduleId":"renal-defense-mechanisms","stem":"What mechanism explains the increased risk of urinary tract infections during pregnancy?","options":[{"id":"a","text":"Increased urine acidity"},{"id":"b","text":"Ureteric dilatation and urinary stasis"},{"id":"c","text":"Enhanced immune response"},{"id":"d","text":"Decreased bladder capacity"}],"answerId":"b","explanation":"Pregnancy causes ureteric dilatation and urinary stasis, which can lead to an increased risk of urinary tract infections.","kind":"mechanism","origin":"ai"},{"id":"renal-defense-mechanisms~ai-3","moduleId":"renal-defense-mechanisms","stem":"A 5-year-old boy presents with recurrent urinary tract infections and renal scarring. What is the most likely underlying cause?","options":[{"id":"a","text":"Incomplete bladder emptying"},{"id":"b","text":"Vesicoureteric reflux"},{"id":"c","text":"Short urethra"},{"id":"d","text":"Catheter use"}],"answerId":"b","explanation":"Vesicoureteric reflux is a common cause of recurrent UTIs in children, leading to renal scarring.","kind":"clinical","origin":"ai"},{"id":"renal-defense-mechanisms~ai-4","moduleId":"renal-defense-mechanisms","stem":"How does Tamm-Horsfall protein contribute to urinary tract defense?","options":[{"id":"a","text":"Inhibits bacterial growth"},{"id":"b","text":"Promotes urine flow"},{"id":"c","text":"Binds and traps bacteria"},{"id":"d","text":"Enhances immune response"}],"answerId":"c","explanation":"Tamm-Horsfall protein binds and traps bacteria, contributing to the chemical defenses of the urinary tract.","kind":"mechanism","origin":"ai"},{"id":"renal-defense-mechanisms~ai-5","moduleId":"renal-defense-mechanisms","stem":"A patient with a neurogenic bladder presents with recurrent UTIs. What is the most likely mechanism for their increased infection risk?","options":[{"id":"a","text":"Increased urine pH"},{"id":"b","text":"Incomplete bladder emptying"},{"id":"c","text":"Longer urethra"},{"id":"d","text":"Increased immune function"}],"answerId":"b","explanation":"Incomplete bladder emptying due to neurogenic bladder leads to urinary stasis, which is a significant risk factor for UTIs.","kind":"mechanism","origin":"ai"},{"id":"renal-defense-mechanisms~ai-6","moduleId":"renal-defense-mechanisms","stem":"Which of the following mechanisms is primarily responsible for the flushing action that prevents urinary tract infections?","options":[{"id":"a","text":"Chemical inhibition by urea"},{"id":"b","text":"Mechanical flow of urine"},{"id":"c","text":"Antimicrobial peptides"},{"id":"d","text":"Glycosaminoglycan layer"}],"answerId":"b","explanation":"The mechanical flow of urine acts as the primary flushing action that helps prevent the adherence of pathogens and subsequent infections.","kind":"recall","origin":"ai"},{"id":"renal-defense-mechanisms~ai-7","moduleId":"renal-defense-mechanisms","stem":"How does the knowledge of urinary tract defense mechanisms integrate with the management of UTIs?","options":[{"id":"a","text":"Focus on antibiotic therapy only"},{"id":"b","text":"Prevent stasis by ensuring complete bladder emptying"},{"id":"c","text":"Prioritize surgical interventions"},{"id":"d","text":"Ignore anatomical variations"}],"answerId":"b","explanation":"Understanding urinary tract defense mechanisms emphasizes the importance of preventing stasis through complete bladder emptying to reduce UTI risk.","kind":"integration","linkedModuleIds":["uti-clinical-management"],"origin":"ai"},{"id":"renal-defense-mechanisms~ai-8","moduleId":"renal-defense-mechanisms","stem":"Which innate immune response component is most relevant in the context of urinary tract infections?","options":[{"id":"a","text":"B cells"},{"id":"b","text":"Tamm-Horsfall protein"},{"id":"c","text":"Neutrophil recruitment"},{"id":"d","text":"Cytokine release"}],"answerId":"c","explanation":"Neutrophil recruitment is a critical part of the innate immune response that helps clear pathogens from the urinary tract.","kind":"integration","linkedModuleIds":["innate-barriers-prr"],"origin":"ai"}],"alopecia-clinical-approach":[{"id":"alopecia-clinical-approach~ai-0","moduleId":"alopecia-clinical-approach","stem":"What is the primary distinguishing feature of scarring alopecia?","options":[{"id":"a","text":"Presence of follicular openings"},{"id":"b","text":"Smooth scarred patches"},{"id":"c","text":"Diffuse hair shedding"},{"id":"d","text":"Exclamation-mark hairs"}],"answerId":"b","explanation":"Scarring alopecia is characterized by smooth scarred patches with loss of follicular openings, indicating permanent hair loss.","kind":"recall","origin":"ai"},{"id":"alopecia-clinical-approach~ai-1","moduleId":"alopecia-clinical-approach","stem":"Which condition is characterized by round bald patches with exclamation-mark hairs?","options":[{"id":"a","text":"Androgenetic alopecia"},{"id":"b","text":"Telogen effluvium"},{"id":"c","text":"Alopecia areata"},{"id":"d","text":"Tinea capitis"}],"answerId":"c","explanation":"Alopecia areata is an autoimmune condition that presents with smooth, round bald patches and exclamation-mark hairs.","kind":"recall","origin":"ai"},{"id":"alopecia-clinical-approach~ai-2","moduleId":"alopecia-clinical-approach","stem":"What is the mechanism behind telogen effluvium?","options":[{"id":"a","text":"Permanent hair loss due to scarring"},{"id":"b","text":"Delayed shedding after a stressor"},{"id":"c","text":"Autoimmune destruction of hair follicles"},{"id":"d","text":"Infection leading to hair breakage"}],"answerId":"b","explanation":"Telogen effluvium is characterized by delayed diffuse shedding that occurs 2-3 months after a triggering stressor.","kind":"mechanism","origin":"ai"},{"id":"alopecia-clinical-approach~ai-3","moduleId":"alopecia-clinical-approach","stem":"A 30-year-old woman presents with diffuse hair shedding 3 months after childbirth. What is the most likely diagnosis?","options":[{"id":"a","text":"Alopecia areata"},{"id":"b","text":"Androgenetic alopecia"},{"id":"c","text":"Telogen effluvium"},{"id":"d","text":"Tinea capitis"}],"answerId":"c","explanation":"The timing of hair shedding following childbirth is consistent with telogen effluvium, which is reversible.","kind":"clinical","origin":"ai"},{"id":"alopecia-clinical-approach~ai-4","moduleId":"alopecia-clinical-approach","stem":"In a patient with suspected tinea capitis, which examination finding would be most indicative?","options":[{"id":"a","text":"Smooth scarred patches"},{"id":"b","text":"Exclamation-mark hairs"},{"id":"c","text":"Scaly patch with broken hairs"},{"id":"d","text":"Bitemporal recession"}],"answerId":"c","explanation":"Tinea capitis typically presents as a scaly patch with broken hairs, especially in children.","kind":"recall","origin":"ai"},{"id":"alopecia-clinical-approach~ai-5","moduleId":"alopecia-clinical-approach","stem":"Which of the following statements about telogen effluvium is true?","options":[{"id":"a","text":"It causes immediate hair shedding."},{"id":"b","text":"It is a permanent condition."},{"id":"c","text":"It typically occurs 2-3 months after a stressor."},{"id":"d","text":"It is characterized by scarring."}],"answerId":"c","explanation":"Telogen effluvium is characterized by a 2-3 month delay in hair shedding following a stressor, making it reversible.","kind":"trap","origin":"ai"},{"id":"alopecia-clinical-approach~ai-6","moduleId":"alopecia-clinical-approach","stem":"How does discoid lupus erythematosus relate to scarring alopecia?","options":[{"id":"a","text":"It is a type of non-scarring alopecia."},{"id":"b","text":"It requires oral antifungal treatment."},{"id":"c","text":"It leads to permanent hair loss and requires biopsy."},{"id":"d","text":"It is characterized by exclamation-mark hairs."}],"answerId":"c","explanation":"Discoid lupus is a form of scarring alopecia that leads to permanent hair loss and necessitates early biopsy and treatment.","kind":"integration","linkedModuleIds":["cutaneous-lupus-dermatomyositis"],"origin":"ai"},{"id":"alopecia-clinical-approach~ai-7","moduleId":"alopecia-clinical-approach","stem":"Which hair loss condition is most likely to present with a positive hair-pull test?","options":[{"id":"a","text":"Androgenetic alopecia"},{"id":"b","text":"Alopecia areata"},{"id":"c","text":"Telogen effluvium"},{"id":"d","text":"Tinea capitis"}],"answerId":"c","explanation":"A positive hair-pull test is indicative of telogen effluvium, where hair shedding is active.","kind":"integration","linkedModuleIds":["hair-diseases"],"origin":"ai"}],"uti-pathogenesis-microbiology":[{"id":"uti-pathogenesis-microbiology~ai-0","moduleId":"uti-pathogenesis-microbiology","stem":"What is the most common organism cultured from an uncomplicated UTI?","options":[{"id":"a","text":"Staphylococcus saprophyticus"},{"id":"b","text":"Klebsiella pneumoniae"},{"id":"c","text":"Uropathogenic E. coli"},{"id":"d","text":"Proteus mirabilis"}],"answerId":"c","explanation":"Uropathogenic E. coli is the most common organism responsible for uncomplicated urinary tract infections.","kind":"recall","origin":"ai"},{"id":"uti-pathogenesis-microbiology~ai-1","moduleId":"uti-pathogenesis-microbiology","stem":"Which mechanism allows Proteus to cause struvite staghorn stones?","options":[{"id":"a","text":"Urease production"},{"id":"b","text":"P-fimbriae adhesion"},{"id":"c","text":"Nitrite reduction"},{"id":"d","text":"Biofilm formation"}],"answerId":"a","explanation":"Proteus produces urease, which splits urea into ammonia, leading to alkaline urine and the formation of struvite stones.","kind":"mechanism","origin":"ai"},{"id":"uti-pathogenesis-microbiology~ai-2","moduleId":"uti-pathogenesis-microbiology","stem":"A young sexually active woman presents with a UTI. Which organism is most likely responsible?","options":[{"id":"a","text":"Uropathogenic E. coli"},{"id":"b","text":"Staphylococcus saprophyticus"},{"id":"c","text":"Klebsiella pneumoniae"},{"id":"d","text":"Enterococcus faecalis"}],"answerId":"b","explanation":"Staphylococcus saprophyticus is a common uropathogen in young sexually active women.","kind":"recall","origin":"ai"},{"id":"uti-pathogenesis-microbiology~ai-3","moduleId":"uti-pathogenesis-microbiology","stem":"What does sterile pyuria suggest in a patient with UTI symptoms?","options":[{"id":"a","text":"Bacterial UTI"},{"id":"b","text":"Viral infection"},{"id":"c","text":"Tuberculosis or chlamydia infection"},{"id":"d","text":"Normal urinalysis"}],"answerId":"c","explanation":"Sterile pyuria indicates the presence of white blood cells without ordinary bacterial growth, suggesting infections like tuberculosis or chlamydia.","kind":"clinical","origin":"ai"},{"id":"uti-pathogenesis-microbiology~ai-4","moduleId":"uti-pathogenesis-microbiology","stem":"Which of the following is a key exception for treating asymptomatic bacteriuria?","options":[{"id":"a","text":"In elderly patients"},{"id":"b","text":"In patients with diabetes"},{"id":"c","text":"In pregnant women"},{"id":"d","text":"In patients with urinary stones"}],"answerId":"c","explanation":"Asymptomatic bacteriuria is generally not treated except in pregnant women due to the risk of pyelonephritis and preterm birth.","kind":"trap","origin":"ai"},{"id":"uti-pathogenesis-microbiology~ai-5","moduleId":"uti-pathogenesis-microbiology","stem":"How does uropathogenic E. coli adhere to the uroepithelium?","options":[{"id":"a","text":"By producing urease"},{"id":"b","text":"Through P-fimbriae"},{"id":"c","text":"By forming biofilms"},{"id":"d","text":"By secreting toxins"}],"answerId":"b","explanation":"Uropathogenic E. coli uses P-fimbriae to adhere to the uroepithelium, facilitating infection.","kind":"mechanism","origin":"ai"},{"id":"uti-pathogenesis-microbiology~ai-6","moduleId":"uti-pathogenesis-microbiology","stem":"In a patient with recurrent UTIs, which factor is most likely contributing to their condition?","options":[{"id":"a","text":"Increased fluid intake"},{"id":"b","text":"Frequent urination"},{"id":"c","text":"Urinary stasis"},{"id":"d","text":"High protein diet"}],"answerId":"c","explanation":"Urinary stasis is a risk factor for recurrent UTIs as it allows bacteria to colonize and ascend the urinary tract.","kind":"clinical","origin":"ai"},{"id":"uti-pathogenesis-microbiology~ai-7","moduleId":"uti-pathogenesis-microbiology","stem":"How does the renal defense mechanism relate to UTI pathogenesis?","options":[{"id":"a","text":"It prevents bacterial adhesion"},{"id":"b","text":"It increases urine pH"},{"id":"c","text":"It enhances bacterial growth"},{"id":"d","text":"It decreases urine flow"}],"answerId":"a","explanation":"The renal defense mechanisms help prevent bacterial adhesion and colonization in the urinary tract, thereby reducing UTI risk.","kind":"integration","linkedModuleIds":["renal-defense-mechanisms"],"origin":"ai"},{"id":"uti-pathogenesis-microbiology~ai-8","moduleId":"uti-pathogenesis-microbiology","stem":"What is the relationship between uropathogenic E. coli virulence factors and UTI severity?","options":[{"id":"a","text":"Higher virulence leads to milder symptoms"},{"id":"b","text":"Virulence factors enhance bacterial clearance"},{"id":"c","text":"Increased virulence correlates with more severe UTIs"},{"id":"d","text":"Virulence factors are irrelevant to UTI severity"}],"answerId":"c","explanation":"Increased virulence factors in uropathogenic E. coli correlate with more severe urinary tract infections.","kind":"integration","linkedModuleIds":["uropathogenic-ecoli-virulence"],"origin":"ai"}],"keratinocyte-carcinomas":[{"id":"keratinocyte-carcinomas~ai-0","moduleId":"keratinocyte-carcinomas","stem":"What is the most common type of keratinocyte carcinoma?","options":[{"id":"a","text":"Squamous cell carcinoma"},{"id":"b","text":"Melanoma"},{"id":"c","text":"Basal cell carcinoma"},{"id":"d","text":"Actinic keratosis"}],"answerId":"c","explanation":"Basal cell carcinoma (BCC) is the most common human cancer, characterized by its slow growth and low metastatic potential.","kind":"recall","origin":"ai"},{"id":"keratinocyte-carcinomas~ai-1","moduleId":"keratinocyte-carcinomas","stem":"Which clinical finding is characteristic of basal cell carcinoma?","options":[{"id":"a","text":"Firm scaly nodule"},{"id":"b","text":"Pearly papule with rolled edges"},{"id":"c","text":"Ulcerated lesion on the lip"},{"id":"d","text":"Chronic non-healing wound"}],"answerId":"b","explanation":"A pearly papule with rolled edges is a classic presentation of basal cell carcinoma.","kind":"recall","origin":"ai"},{"id":"keratinocyte-carcinomas~ai-2","moduleId":"keratinocyte-carcinomas","stem":"What is the primary treatment for squamous cell carcinoma?","options":[{"id":"a","text":"Cryotherapy"},{"id":"b","text":"Topical 5-fluorouracil"},{"id":"c","text":"Excision with margins"},{"id":"d","text":"Radiotherapy"}],"answerId":"c","explanation":"Excision with margins is the standard treatment for squamous cell carcinoma to ensure complete removal and reduce recurrence.","kind":"recall","origin":"ai"},{"id":"keratinocyte-carcinomas~ai-3","moduleId":"keratinocyte-carcinomas","stem":"Which of the following statements about basal cell carcinoma (BCC) is true?","options":[{"id":"a","text":"BCC commonly metastasizes to lymph nodes."},{"id":"b","text":"BCC is locally invasive but rarely metastasizes."},{"id":"c","text":"BCC arises from actinic keratosis."},{"id":"d","text":"BCC has a high risk of recurrence."}],"answerId":"b","explanation":"Basal cell carcinoma is locally invasive but almost never metastasizes, leading to an excellent prognosis with excision.","kind":"trap","origin":"ai"},{"id":"keratinocyte-carcinomas~ai-4","moduleId":"keratinocyte-carcinomas","stem":"What is the risk factor for developing squamous cell carcinoma (SCC) in immunosuppressed patients?","options":[{"id":"a","text":"Increased UV exposure"},{"id":"b","text":"Genetic predisposition"},{"id":"c","text":"Chronic inflammation"},{"id":"d","text":"Field cancerization"}],"answerId":"a","explanation":"Increased UV exposure is a significant risk factor for SCC, especially in immunosuppressed individuals.","kind":"recall","origin":"ai"},{"id":"keratinocyte-carcinomas~ai-5","moduleId":"keratinocyte-carcinomas","stem":"A patient presents with multiple actinic keratoses. What is the best preventive measure to reduce the risk of squamous cell carcinoma?","options":[{"id":"a","text":"Regular skin checks"},{"id":"b","text":"Cryotherapy"},{"id":"c","text":"Topical imiquimod"},{"id":"d","text":"Photoprotection"}],"answerId":"d","explanation":"Photoprotection is essential to prevent further UV damage and reduce the risk of progression from actinic keratoses to squamous cell carcinoma.","kind":"integration","linkedModuleIds":["photoaging-photoprotection"],"origin":"ai"},{"id":"keratinocyte-carcinomas~ai-6","moduleId":"keratinocyte-carcinomas","stem":"Which of the following is a precursor lesion for squamous cell carcinoma?","options":[{"id":"a","text":"Basal cell carcinoma"},{"id":"b","text":"Actinic keratosis"},{"id":"c","text":"Seborrheic keratosis"},{"id":"d","text":"Melanoma"}],"answerId":"b","explanation":"Actinic keratosis is a precursor lesion that can progress to squamous cell carcinoma if left untreated.","kind":"recall","origin":"ai"},{"id":"keratinocyte-carcinomas~ai-7","moduleId":"keratinocyte-carcinomas","stem":"A patient with a history of organ transplantation presents with multiple aggressive squamous cell carcinomas. What is the most likely reason for this?","options":[{"id":"a","text":"Increased UV exposure"},{"id":"b","text":"Genetic predisposition"},{"id":"c","text":"Immunosuppression"},{"id":"d","text":"Chronic inflammation"}],"answerId":"c","explanation":"Immunosuppression increases the risk of developing multiple aggressive squamous cell carcinomas due to reduced immune surveillance.","kind":"clinical","origin":"ai"},{"id":"keratinocyte-carcinomas~ai-8","moduleId":"keratinocyte-carcinomas","stem":"How does the management of basal cell carcinoma differ from that of squamous cell carcinoma?","options":[{"id":"a","text":"BCC is treated with cryotherapy; SCC requires Mohs surgery."},{"id":"b","text":"BCC rarely metastasizes; SCC can metastasize."},{"id":"c","text":"BCC is more aggressive than SCC."},{"id":"d","text":"BCC is treated with topical agents; SCC requires excision."}],"answerId":"b","explanation":"Basal cell carcinoma is locally invasive but rarely metastasizes, while squamous cell carcinoma can metastasize, necessitating more aggressive treatment.","kind":"integration","linkedModuleIds":["skin-neoplasms"],"origin":"ai"}],"contact-dermatitis-clinical":[{"id":"contact-dermatitis-clinical~ai-0","moduleId":"contact-dermatitis-clinical","stem":"What is the primary mechanism of irritant contact dermatitis?","options":[{"id":"a","text":"Type IV hypersensitivity"},{"id":"b","text":"Direct chemical injury"},{"id":"c","text":"Autoimmune reaction"},{"id":"d","text":"Infection"}],"answerId":"b","explanation":"Irritant contact dermatitis is caused by direct chemical or physical injury to the skin, not an immune response.","kind":"mechanism","origin":"ai"},{"id":"contact-dermatitis-clinical~ai-1","moduleId":"contact-dermatitis-clinical","stem":"Which of the following is a common allergen associated with allergic contact dermatitis?","options":[{"id":"a","text":"Soaps"},{"id":"b","text":"Nickel"},{"id":"c","text":"Water"},{"id":"d","text":"Detergents"}],"answerId":"b","explanation":"Nickel is a well-known allergen that can cause allergic contact dermatitis, particularly in jewelry and belt buckles.","kind":"recall","origin":"ai"},{"id":"contact-dermatitis-clinical~ai-2","moduleId":"contact-dermatitis-clinical","stem":"A patient presents with itchy dermatitis under a belt buckle made of nickel. What is the most likely diagnosis?","options":[{"id":"a","text":"Irritant contact dermatitis"},{"id":"b","text":"Allergic contact dermatitis"},{"id":"c","text":"Atopic dermatitis"},{"id":"d","text":"Psoriasis"}],"answerId":"b","explanation":"The presentation and location suggest allergic contact dermatitis due to nickel exposure, confirmed by patch testing.","kind":"clinical","origin":"ai"},{"id":"contact-dermatitis-clinical~ai-3","moduleId":"contact-dermatitis-clinical","stem":"What is the typical time frame for the appearance of symptoms in allergic contact dermatitis after re-exposure?","options":[{"id":"a","text":"Immediate"},{"id":"b","text":"24 hours"},{"id":"c","text":"48-72 hours"},{"id":"d","text":"1 week"}],"answerId":"c","explanation":"Allergic contact dermatitis symptoms typically appear 48-72 hours after re-exposure due to the Type IV hypersensitivity reaction.","kind":"recall","origin":"ai"},{"id":"contact-dermatitis-clinical~ai-4","moduleId":"contact-dermatitis-clinical","stem":"Which finding is most indicative of allergic contact dermatitis?","options":[{"id":"a","text":"Cumulative exposure history"},{"id":"b","text":"Positive patch test"},{"id":"c","text":"Well-demarcated rash"},{"id":"d","text":"Location on the hands"}],"answerId":"b","explanation":"A positive patch test confirms allergic contact dermatitis, distinguishing it from irritant dermatitis.","kind":"recall","origin":"ai"},{"id":"contact-dermatitis-clinical~ai-5","moduleId":"contact-dermatitis-clinical","stem":"A gardener develops linear streaks of vesicular dermatitis after exposure to plants. What type of dermatitis is this?","options":[{"id":"a","text":"Irritant contact dermatitis"},{"id":"b","text":"Allergic contact dermatitis"},{"id":"c","text":"Atopic dermatitis"},{"id":"d","text":"Seborrheic dermatitis"}],"answerId":"b","explanation":"The linear streaks suggest allergic contact dermatitis, likely due to exposure to a plant allergen like poison ivy.","kind":"clinical","origin":"ai"},{"id":"contact-dermatitis-clinical~ai-6","moduleId":"contact-dermatitis-clinical","stem":"How does irritant contact dermatitis differ from allergic contact dermatitis in terms of sensitization?","options":[{"id":"a","text":"Requires prior sensitization"},{"id":"b","text":"Does not require prior sensitization"},{"id":"c","text":"Both require sensitization"},{"id":"d","text":"Only allergic requires sensitization"}],"answerId":"b","explanation":"Irritant contact dermatitis does not require prior sensitization, unlike allergic contact dermatitis, which is a Type IV hypersensitivity.","kind":"trap","origin":"ai"},{"id":"contact-dermatitis-clinical~ai-7","moduleId":"contact-dermatitis-clinical","stem":"Which of the following best describes the distribution of allergic contact dermatitis?","options":[{"id":"a","text":"Cumulative exposure on hands"},{"id":"b","text":"Localized to contact areas"},{"id":"c","text":"Generalized rash"},{"id":"d","text":"Widespread over the body"}],"answerId":"b","explanation":"Allergic contact dermatitis typically appears in areas where the allergen has contacted the skin, often well-defined.","kind":"clinical","origin":"ai"},{"id":"contact-dermatitis-clinical~ai-8","moduleId":"contact-dermatitis-clinical","stem":"How does allergic contact dermatitis relate to cutaneous hypersensitivity reactions?","options":[{"id":"a","text":"It is a Type I hypersensitivity reaction"},{"id":"b","text":"It is a Type IV hypersensitivity reaction"},{"id":"c","text":"It is not related"},{"id":"d","text":"It is an autoimmune reaction"}],"answerId":"b","explanation":"Allergic contact dermatitis is classified as a Type IV hypersensitivity reaction, which is a delayed immune response.","kind":"integration","linkedModuleIds":["cutaneous-hypersensitivity-reactions"],"origin":"ai"},{"id":"contact-dermatitis-clinical~ai-9","moduleId":"contact-dermatitis-clinical","stem":"What is a common management strategy for both irritant and allergic contact dermatitis?","options":[{"id":"a","text":"Antibiotics"},{"id":"b","text":"Avoidance of the irritant/allergen"},{"id":"c","text":"Systemic steroids only"},{"id":"d","text":"Moisturizers only"}],"answerId":"b","explanation":"The primary management for both types of contact dermatitis involves identifying and avoiding the causative agent.","kind":"integration","linkedModuleIds":["eczema-dermatitis"],"origin":"ai"}],"diuretics-pharmacology":[{"id":"diuretics-pharmacology~ai-0","moduleId":"diuretics-pharmacology","stem":"Which diuretic class is primarily used to treat hypertension?","options":[{"id":"a","text":"Loop diuretics"},{"id":"b","text":"Thiazides"},{"id":"c","text":"Potassium-sparing diuretics"},{"id":"d","text":"Carbonic anhydrase inhibitors"}],"answerId":"b","explanation":"Thiazides are the first-line diuretics for hypertension due to their mechanism of action at the distal convoluted tubule.","kind":"recall","origin":"ai"},{"id":"diuretics-pharmacology~ai-1","moduleId":"diuretics-pharmacology","stem":"What is the mechanism of action of furosemide?","options":[{"id":"a","text":"Inhibition of Na-Cl cotransporter"},{"id":"b","text":"Inhibition of Na-K-2Cl cotransporter"},{"id":"c","text":"Inhibition of ENaC"},{"id":"d","text":"Inhibition of carbonic anhydrase"}],"answerId":"b","explanation":"Furosemide is a loop diuretic that inhibits the Na-K-2Cl cotransporter in the thick ascending limb of the nephron.","kind":"mechanism","origin":"ai"},{"id":"diuretics-pharmacology~ai-2","moduleId":"diuretics-pharmacology","stem":"A patient on a loop diuretic presents with hypokalemia. What is the most likely reason?","options":[{"id":"a","text":"Increased distal Na delivery"},{"id":"b","text":"Decreased potassium intake"},{"id":"c","text":"Renal tubular acidosis"},{"id":"d","text":"Increased aldosterone secretion"}],"answerId":"a","explanation":"Loop diuretics increase distal sodium delivery, leading to increased potassium loss and hypokalemia.","kind":"clinical","origin":"ai"},{"id":"diuretics-pharmacology~ai-3","moduleId":"diuretics-pharmacology","stem":"Which diuretic is most likely to cause gynaecomastia?","options":[{"id":"a","text":"Hydrochlorothiazide"},{"id":"b","text":"Furosemide"},{"id":"c","text":"Spironolactone"},{"id":"d","text":"Mannitol"}],"answerId":"c","explanation":"Spironolactone, a potassium-sparing diuretic, has anti-androgen effects that can lead to gynaecomastia.","kind":"recall","origin":"ai"},{"id":"diuretics-pharmacology~ai-4","moduleId":"diuretics-pharmacology","stem":"Which of the following combinations poses the highest risk of hyperkalemia?","options":[{"id":"a","text":"Loop diuretic and thiazide"},{"id":"b","text":"Thiazide and potassium-sparing diuretic"},{"id":"c","text":"Loop diuretic and potassium-sparing diuretic"},{"id":"d","text":"Thiazide and ACE inhibitor"}],"answerId":"c","explanation":"Combining a loop diuretic with a potassium-sparing diuretic increases the risk of hyperkalemia due to opposing potassium effects.","kind":"trap","origin":"ai"},{"id":"diuretics-pharmacology~ai-5","moduleId":"diuretics-pharmacology","stem":"In a patient with chronic kidney disease, which diuretic class is least effective?","options":[{"id":"a","text":"Loop diuretics"},{"id":"b","text":"Thiazides"},{"id":"c","text":"Potassium-sparing diuretics"},{"id":"d","text":"Carbonic anhydrase inhibitors"}],"answerId":"b","explanation":"Thiazides are less effective at low GFR, making them the least effective diuretic class in chronic kidney disease.","kind":"integration","linkedModuleIds":["chronic-kidney-disease"],"origin":"ai"},{"id":"diuretics-pharmacology~ai-6","moduleId":"diuretics-pharmacology","stem":"Which diuretic class would be most appropriate for a patient with fluid overload and renal impairment?","options":[{"id":"a","text":"Thiazides"},{"id":"b","text":"Loop diuretics"},{"id":"c","text":"Potassium-sparing diuretics"},{"id":"d","text":"Carbonic anhydrase inhibitors"}],"answerId":"b","explanation":"Loop diuretics are the most powerful diuretics and can be effective even in renal impairment.","kind":"integration","linkedModuleIds":["drug-dosing-ckd"],"origin":"ai"}],"urinary-tract-pathology":[{"id":"urinary-tract-pathology~ai-0","moduleId":"urinary-tract-pathology","stem":"What is the most common type of urinary stone found in adults?","options":[{"id":"a","text":"Struvite stones"},{"id":"b","text":"Uric acid stones"},{"id":"c","text":"Cystine stones"},{"id":"d","text":"Calcium stones"}],"answerId":"d","explanation":"Calcium stones, including calcium oxalate and calcium phosphate, account for approximately 80% of urinary stones in adults.","kind":"recall","origin":"ai"},{"id":"urinary-tract-pathology~ai-1","moduleId":"urinary-tract-pathology","stem":"Which of the following is a characteristic finding in a patient with a ureteric stone?","options":[{"id":"a","text":"Constant dull flank pain"},{"id":"b","text":"Severe colicky loin-to-groin pain"},{"id":"c","text":"Painless hematuria"},{"id":"d","text":"Bilateral edema"}],"answerId":"b","explanation":"Severe colicky loin-to-groin pain is a classic presentation of renal colic due to a ureteric stone.","kind":"recall","origin":"ai"},{"id":"urinary-tract-pathology~ai-2","moduleId":"urinary-tract-pathology","stem":"A patient presents with fever, flank pain, and an obstructing kidney stone. What is the most critical immediate management step?","options":[{"id":"a","text":"Start broad-spectrum antibiotics"},{"id":"b","text":"Perform a CT scan"},{"id":"c","text":"Initiate hydration therapy"},{"id":"d","text":"Urgent drainage of the obstructed kidney"}],"answerId":"d","explanation":"An obstructed kidney with infection is a urological emergency requiring urgent drainage to prevent complications like pyonephrosis.","kind":"clinical","origin":"ai"},{"id":"urinary-tract-pathology~ai-3","moduleId":"urinary-tract-pathology","stem":"What mechanism leads to hydronephrosis in urinary obstruction?","options":[{"id":"a","text":"Increased urine production"},{"id":"b","text":"Back-pressure from obstruction"},{"id":"c","text":"Decreased renal blood flow"},{"id":"d","text":"Infection of the renal pelvis"}],"answerId":"b","explanation":"Obstruction causes back-pressure in the urinary tract, leading to hydronephrosis and potential renal atrophy.","kind":"mechanism","origin":"ai"},{"id":"urinary-tract-pathology~ai-4","moduleId":"urinary-tract-pathology","stem":"A patient with gout presents with a stone in acidic urine. What type of stone is most likely present?","options":[{"id":"a","text":"Calcium oxalate"},{"id":"b","text":"Struvite"},{"id":"c","text":"Uric acid"},{"id":"d","text":"Cystine"}],"answerId":"c","explanation":"Uric acid stones are radiolucent and typically form in acidic urine, often seen in patients with gout.","kind":"recall","origin":"ai"},{"id":"urinary-tract-pathology~ai-5","moduleId":"urinary-tract-pathology","stem":"Which type of urinary stone is associated with urease-producing organisms like Proteus?","options":[{"id":"a","text":"Calcium stones"},{"id":"b","text":"Uric acid stones"},{"id":"c","text":"Cystine stones"},{"id":"d","text":"Struvite stones"}],"answerId":"d","explanation":"Struvite stones form in alkaline urine due to urease-producing bacteria, leading to staghorn calculi.","kind":"recall","origin":"ai"},{"id":"urinary-tract-pathology~ai-6","moduleId":"urinary-tract-pathology","stem":"How does chronic irritation from stones increase the risk of malignancy in the urinary tract?","options":[{"id":"a","text":"By causing hydronephrosis"},{"id":"b","text":"By inducing chronic inflammation"},{"id":"c","text":"By obstructing urine flow"},{"id":"d","text":"By altering urine pH"}],"answerId":"b","explanation":"Chronic inflammation from irritation, such as from stones, can lead to cellular changes that increase the risk of urothelial malignancy.","kind":"integration","linkedModuleIds":["urinary-system-neoplasms"],"origin":"ai"},{"id":"urinary-tract-pathology~ai-7","moduleId":"urinary-tract-pathology","stem":"What is the relationship between urinary stones and urinary tract infections?","options":[{"id":"a","text":"Stones prevent infections"},{"id":"b","text":"Infections cause stones"},{"id":"c","text":"Stones can predispose to infections"},{"id":"d","text":"Infections dissolve stones"}],"answerId":"c","explanation":"Urinary stones can obstruct the flow of urine, creating a favorable environment for urinary tract infections.","kind":"integration","origin":"ai"}],"interstitial-nephritis-obstruction":[{"id":"interstitial-nephritis-obstruction~ai-0","moduleId":"interstitial-nephritis-obstruction","stem":"What is the classic triad of symptoms associated with acute interstitial nephritis?","options":[{"id":"a","text":"Fever, rash, eosinophilia"},{"id":"b","text":"Hematuria, flank pain, proteinuria"},{"id":"c","text":"Nausea, vomiting, diarrhea"},{"id":"d","text":"Dysuria, urgency, frequency"}],"answerId":"a","explanation":"Acute interstitial nephritis typically presents with fever, rash, and eosinophilia, although not all patients exhibit all three symptoms.","kind":"recall","origin":"ai"},{"id":"interstitial-nephritis-obstruction~ai-1","moduleId":"interstitial-nephritis-obstruction","stem":"Which of the following is a common cause of chronic tubulointerstitial nephritis?","options":[{"id":"a","text":"Acute pyelonephritis"},{"id":"b","text":"Chronic obstruction"},{"id":"c","text":"Post-streptococcal glomerulonephritis"},{"id":"d","text":"Diabetic ketoacidosis"}],"answerId":"b","explanation":"Chronic obstruction is a well-known cause of chronic tubulointerstitial nephritis, leading to progressive kidney damage.","kind":"recall","origin":"ai"},{"id":"interstitial-nephritis-obstruction~ai-2","moduleId":"interstitial-nephritis-obstruction","stem":"What is the mechanism behind post-obstructive diuresis?","options":[{"id":"a","text":"Increased renal perfusion"},{"id":"b","text":"Release of retained solutes"},{"id":"c","text":"Decreased renal tubular reabsorption"},{"id":"d","text":"Increased aldosterone secretion"}],"answerId":"b","explanation":"Post-obstructive diuresis occurs due to the release of retained solutes and urea after relieving an obstruction, leading to large urine output.","kind":"mechanism","origin":"ai"},{"id":"interstitial-nephritis-obstruction~ai-3","moduleId":"interstitial-nephritis-obstruction","stem":"A patient presents with acute kidney injury, fever, rash, and eosinophilia after starting a new medication. What is the most likely diagnosis?","options":[{"id":"a","text":"Acute tubular necrosis"},{"id":"b","text":"Acute interstitial nephritis"},{"id":"c","text":"Chronic kidney disease"},{"id":"d","text":"Post-renal obstruction"}],"answerId":"b","explanation":"The presentation is consistent with acute interstitial nephritis, which is often drug-induced.","kind":"clinical","origin":"ai"},{"id":"interstitial-nephritis-obstruction~ai-4","moduleId":"interstitial-nephritis-obstruction","stem":"In a patient with obstructive uropathy, which finding would most likely indicate significant bilateral obstruction?","options":[{"id":"a","text":"Unilateral flank pain"},{"id":"b","text":"Palpable bladder"},{"id":"c","text":"Elevated serum creatinine"},{"id":"d","text":"Hematuria"}],"answerId":"b","explanation":"A palpable bladder is a clinical sign indicating urinary retention, often due to significant bilateral obstruction.","kind":"recall","origin":"ai"},{"id":"interstitial-nephritis-obstruction~ai-5","moduleId":"interstitial-nephritis-obstruction","stem":"Which of the following drugs is most commonly associated with acute interstitial nephritis?","options":[{"id":"a","text":"Aspirin"},{"id":"b","text":"Ibuprofen"},{"id":"c","text":"Penicillin"},{"id":"d","text":"Acetaminophen"}],"answerId":"c","explanation":"Penicillin is a well-known culprit for causing acute interstitial nephritis due to hypersensitivity reactions.","kind":"trap","origin":"ai"},{"id":"interstitial-nephritis-obstruction~ai-6","moduleId":"interstitial-nephritis-obstruction","stem":"How does acute interstitial nephritis relate to the use of antibacterial cell-wall agents?","options":[{"id":"a","text":"It causes chronic kidney disease"},{"id":"b","text":"It can be triggered by these agents"},{"id":"c","text":"It is treated with these agents"},{"id":"d","text":"It leads to urinary obstruction"}],"answerId":"b","explanation":"Acute interstitial nephritis can be triggered by hypersensitivity to antibacterial cell-wall agents, such as penicillins.","kind":"integration","linkedModuleIds":["antibacterial-cell-wall-agents"],"origin":"ai"},{"id":"interstitial-nephritis-obstruction~ai-7","moduleId":"interstitial-nephritis-obstruction","stem":"In a patient with acute kidney injury due to obstructive uropathy, what is the most critical initial step in management?","options":[{"id":"a","text":"Start dialysis"},{"id":"b","text":"Administer diuretics"},{"id":"c","text":"Relieve the obstruction"},{"id":"d","text":"Monitor renal function"}],"answerId":"c","explanation":"Relieving the obstruction is crucial in obstructive uropathy to restore kidney function and prevent permanent damage.","kind":"integration","linkedModuleIds":["urinary-tract-pathology"],"origin":"ai"}],"nephrotic-syndrome":[{"id":"nephrotic-syndrome~ai-0","moduleId":"nephrotic-syndrome","stem":"What is the primary mechanism leading to nephrotic syndrome?","options":[{"id":"a","text":"Podocyte injury"},{"id":"b","text":"Endothelial damage"},{"id":"c","text":"Tubular dysfunction"},{"id":"d","text":"Interstitial fibrosis"}],"answerId":"a","explanation":"Nephrotic syndrome is primarily caused by injury to the podocytes, leading to significant proteinuria.","kind":"mechanism","origin":"ai"},{"id":"nephrotic-syndrome~ai-1","moduleId":"nephrotic-syndrome","stem":"Which clinical finding is characteristic of nephrotic syndrome?","options":[{"id":"a","text":"Hematuria"},{"id":"b","text":"Proteinuria >3.5 g/day"},{"id":"c","text":"Hypertension"},{"id":"d","text":"Red cell casts"}],"answerId":"b","explanation":"Nephrotic syndrome is defined by heavy proteinuria (>3.5 g/day) along with other features like hypoalbuminaemia and oedema.","kind":"recall","origin":"ai"},{"id":"nephrotic-syndrome~ai-2","moduleId":"nephrotic-syndrome","stem":"In a child presenting with nephrotic syndrome, which condition is most likely?","options":[{"id":"a","text":"Focal segmental glomerulosclerosis"},{"id":"b","text":"Minimal change disease"},{"id":"c","text":"Membranous nephropathy"},{"id":"d","text":"Diabetic nephropathy"}],"answerId":"b","explanation":"Minimal change disease is the most common cause of nephrotic syndrome in children and is typically steroid-responsive.","kind":"recall","origin":"ai"},{"id":"nephrotic-syndrome~ai-3","moduleId":"nephrotic-syndrome","stem":"What is a key complication of nephrotic syndrome due to urinary protein loss?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Hyperkalemia"},{"id":"c","text":"Thrombosis"},{"id":"d","text":"Hypercalcemia"}],"answerId":"c","explanation":"Loss of antithrombin III due to urinary protein loss leads to a hypercoagulable state, increasing the risk of thrombosis.","kind":"clinical","origin":"ai"},{"id":"nephrotic-syndrome~ai-4","moduleId":"nephrotic-syndrome","stem":"Which of the following differentiates nephrotic syndrome from nephritic syndrome?","options":[{"id":"a","text":"Presence of hematuria"},{"id":"b","text":"Heavy proteinuria"},{"id":"c","text":"Hypertension"},{"id":"d","text":"Red cell casts"}],"answerId":"b","explanation":"Nephrotic syndrome is characterized by heavy proteinuria (>3.5 g) and a relatively bland urine, unlike nephritic syndrome which presents with hematuria and red cell casts.","kind":"trap","origin":"ai"},{"id":"nephrotic-syndrome~ai-5","moduleId":"nephrotic-syndrome","stem":"In a patient with nephrotic syndrome and a renal biopsy showing subepithelial spikes, what is the likely diagnosis?","options":[{"id":"a","text":"Minimal change disease"},{"id":"b","text":"Focal segmental glomerulosclerosis"},{"id":"c","text":"Membranous nephropathy"},{"id":"d","text":"Diabetic nephropathy"}],"answerId":"c","explanation":"Subepithelial spikes on renal biopsy are characteristic of membranous nephropathy, often associated with anti-PLA2R antibodies.","kind":"recall","origin":"ai"},{"id":"nephrotic-syndrome~ai-6","moduleId":"nephrotic-syndrome","stem":"How does nephrotic syndrome relate to the evaluation of proteinuria?","options":[{"id":"a","text":"It requires renal biopsy for diagnosis"},{"id":"b","text":"It is characterized by low proteinuria levels"},{"id":"c","text":"It leads to significant protein loss in urine"},{"id":"d","text":"It is unrelated to proteinuria evaluation"}],"answerId":"c","explanation":"Nephrotic syndrome is defined by significant proteinuria (>3.5 g/day), making its evaluation critical in diagnosis.","kind":"integration","linkedModuleIds":["proteinuria-evaluation"],"origin":"ai"},{"id":"nephrotic-syndrome~ai-7","moduleId":"nephrotic-syndrome","stem":"Which of the following conditions is a common secondary cause of nephrotic syndrome?","options":[{"id":"a","text":"Minimal change disease"},{"id":"b","text":"Focal segmental glomerulosclerosis"},{"id":"c","text":"Diabetic nephropathy"},{"id":"d","text":"Membranous nephropathy"}],"answerId":"c","explanation":"Diabetic nephropathy is the most common secondary cause of nephrotic syndrome, characterized by Kimmelstiel-Wilson nodules.","kind":"integration","linkedModuleIds":["glomerular-disease-overview"],"origin":"ai"}],"acute-kidney-injury":[{"id":"acute-kidney-injury~ai-0","moduleId":"acute-kidney-injury","stem":"What is the most common cause of acute kidney injury (AKI)?","options":[{"id":"a","text":"Intrinsic renal damage"},{"id":"b","text":"Post-renal obstruction"},{"id":"c","text":"Pre-renal hypoperfusion"},{"id":"d","text":"Acute interstitial nephritis"}],"answerId":"c","explanation":"Pre-renal hypoperfusion is the most common cause of AKI, often due to factors like hypovolemia or hypotension.","kind":"recall","origin":"ai"},{"id":"acute-kidney-injury~ai-1","moduleId":"acute-kidney-injury","stem":"In a patient with acute tubular necrosis (ATN), what would you expect the urine sodium concentration to be?","options":[{"id":"a","text":"<20 mEq/L"},{"id":"b","text":">40 mEq/L"},{"id":"c","text":"20-40 mEq/L"},{"id":"d","text":"Variable"}],"answerId":"b","explanation":"In ATN, the damaged tubules cannot reabsorb sodium, resulting in a high urine sodium concentration (>40 mEq/L).","kind":"recall","origin":"ai"},{"id":"acute-kidney-injury~ai-2","moduleId":"acute-kidney-injury","stem":"Which of the following findings is characteristic of pre-renal acute kidney injury?","options":[{"id":"a","text":"Muddy-brown casts"},{"id":"b","text":"Urine Na >40 mEq/L"},{"id":"c","text":"BUN:creatinine ratio >20:1"},{"id":"d","text":"Isosthenuria"}],"answerId":"c","explanation":"A BUN:creatinine ratio >20:1 is indicative of pre-renal AKI due to hypoperfusion.","kind":"recall","origin":"ai"},{"id":"acute-kidney-injury~ai-3","moduleId":"acute-kidney-injury","stem":"What is the primary mechanism by which acute tubular necrosis (ATN) leads to elevated serum creatinine?","options":[{"id":"a","text":"Increased glomerular filtration"},{"id":"b","text":"Decreased tubular reabsorption"},{"id":"c","text":"Increased tubular secretion"},{"id":"d","text":"Decreased renal perfusion"}],"answerId":"b","explanation":"In ATN, tubular damage impairs sodium reabsorption, leading to elevated serum creatinine due to reduced GFR.","kind":"mechanism","origin":"ai"},{"id":"acute-kidney-injury~ai-4","moduleId":"acute-kidney-injury","stem":"A patient presents with acute kidney injury and muddy-brown casts in the urine. Which of the following is the most likely cause?","options":[{"id":"a","text":"Hypovolemia"},{"id":"b","text":"Nephrotoxic agents"},{"id":"c","text":"Urinary obstruction"},{"id":"d","text":"Acute interstitial nephritis"}],"answerId":"b","explanation":"Muddy-brown casts are indicative of acute tubular necrosis, often caused by nephrotoxic agents.","kind":"clinical","origin":"ai"},{"id":"acute-kidney-injury~ai-5","moduleId":"acute-kidney-injury","stem":"In the context of acute kidney injury, which of the following is a dialysis indication according to the \"AEIOU\" criteria?","options":[{"id":"a","text":"Severe hyperkalemia"},{"id":"b","text":"Mild metabolic acidosis"},{"id":"c","text":"Fluid overload without symptoms"},{"id":"d","text":"Stable chronic kidney disease"}],"answerId":"a","explanation":"Severe hyperkalemia is one of the indications for dialysis in acute kidney injury management.","kind":"trap","origin":"ai"},{"id":"acute-kidney-injury~ai-6","moduleId":"acute-kidney-injury","stem":"How does acute interstitial nephritis typically present in urinalysis findings?","options":[{"id":"a","text":"Bland urine sediment"},{"id":"b","text":"Muddy-brown casts"},{"id":"c","text":"Eosinophils in urine"},{"id":"d","text":"High urine sodium"}],"answerId":"c","explanation":"Acute interstitial nephritis often presents with eosinophils in the urine, distinguishing it from ATN.","kind":"integration","linkedModuleIds":["interstitial-nephritis-obstruction"],"origin":"ai"},{"id":"acute-kidney-injury~ai-7","moduleId":"acute-kidney-injury","stem":"What is the relationship between acute kidney injury and the need for renal replacement therapy?","options":[{"id":"a","text":"AKI always requires immediate dialysis"},{"id":"b","text":"Dialysis is indicated only for hyperkalemia"},{"id":"c","text":"Dialysis may be needed for fluid overload or uraemia"},{"id":"d","text":"AKI does not require dialysis"}],"answerId":"c","explanation":"Dialysis may be indicated in AKI for complications such as fluid overload or uraemia, not always required immediately.","kind":"integration","linkedModuleIds":["renal-replacement-therapy"],"origin":"ai"}],"urinary-system-neoplasms":[{"id":"urinary-system-neoplasms~ai-0","moduleId":"urinary-system-neoplasms","stem":"What is the most common type of kidney cancer in adults?","options":[{"id":"a","text":"Urothelial carcinoma"},{"id":"b","text":"Wilms tumor"},{"id":"c","text":"Renal cell carcinoma"},{"id":"d","text":"Neuroblastoma"}],"answerId":"c","explanation":"Renal cell carcinoma (RCC) is the most common adult kidney cancer, arising from the proximal tubular epithelium.","kind":"recall","origin":"ai"},{"id":"urinary-system-neoplasms~ai-1","moduleId":"urinary-system-neoplasms","stem":"Which paraneoplastic syndrome is associated with renal cell carcinoma?","options":[{"id":"a","text":"Hypercalcemia"},{"id":"b","text":"Cushing's syndrome"},{"id":"c","text":"Syndrome of inappropriate antidiuretic hormone secretion"},{"id":"d","text":"Carcinoid syndrome"}],"answerId":"a","explanation":"Renal cell carcinoma can cause paraneoplastic hypercalcemia through the production of parathyroid hormone-related peptide (PTHrP).","kind":"mechanism","origin":"ai"},{"id":"urinary-system-neoplasms~ai-2","moduleId":"urinary-system-neoplasms","stem":"A 65-year-old smoker presents with painless visible hematuria. What is the most likely diagnosis?","options":[{"id":"a","text":"Renal cell carcinoma"},{"id":"b","text":"Urothelial carcinoma"},{"id":"c","text":"Wilms tumor"},{"id":"d","text":"Bladder stones"}],"answerId":"b","explanation":"Painless visible hematuria in an adult, especially a smoker, is a red flag for urothelial carcinoma until proven otherwise.","kind":"clinical","origin":"ai"},{"id":"urinary-system-neoplasms~ai-3","moduleId":"urinary-system-neoplasms","stem":"What is the significance of painless hematuria in an adult?","options":[{"id":"a","text":"It is usually benign and can be observed"},{"id":"b","text":"It indicates a urinary tract infection"},{"id":"c","text":"It is a red flag for malignancy"},{"id":"d","text":"It is a sign of kidney stones"}],"answerId":"c","explanation":"Painless hematuria in an adult is a red flag for urinary tract malignancy and requires urgent evaluation.","kind":"trap","origin":"ai"},{"id":"urinary-system-neoplasms~ai-4","moduleId":"urinary-system-neoplasms","stem":"What is the most common presentation of urothelial carcinoma?","options":[{"id":"a","text":"Flank pain"},{"id":"b","text":"Painless visible hematuria"},{"id":"c","text":"Weight loss"},{"id":"d","text":"Abdominal mass"}],"answerId":"b","explanation":"Urothelial carcinoma typically presents with painless visible hematuria.","kind":"recall","origin":"ai"},{"id":"urinary-system-neoplasms~ai-5","moduleId":"urinary-system-neoplasms","stem":"A child presents with a large unilateral abdominal mass. Which tumor is most likely?","options":[{"id":"a","text":"Neuroblastoma"},{"id":"b","text":"Wilms tumor"},{"id":"c","text":"Renal cell carcinoma"},{"id":"d","text":"Hepatoblastoma"}],"answerId":"b","explanation":"Wilms tumor, or nephroblastoma, is the most common renal tumor in children and typically presents as a large abdominal mass.","kind":"recall","origin":"ai"},{"id":"urinary-system-neoplasms~ai-6","moduleId":"urinary-system-neoplasms","stem":"How does renal cell carcinoma typically spread?","options":[{"id":"a","text":"Lymphatic spread only"},{"id":"b","text":"Hematogenous spread to the lungs"},{"id":"c","text":"Direct invasion of surrounding organs"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"Renal cell carcinoma can spread through lymphatics, hematogenously (commonly to the lungs), and by direct invasion.","kind":"mechanism","origin":"ai"},{"id":"urinary-system-neoplasms~ai-7","moduleId":"urinary-system-neoplasms","stem":"In a patient with painless hematuria, which investigation is essential?","options":[{"id":"a","text":"Urinalysis"},{"id":"b","text":"CT scan"},{"id":"c","text":"Cystoscopy"},{"id":"d","text":"Ultrasound"}],"answerId":"c","explanation":"Cystoscopy is essential for evaluating painless hematuria in adults to rule out malignancy.","kind":"integration","linkedModuleIds":["urinalysis-urine-examination"],"origin":"ai"},{"id":"urinary-system-neoplasms~ai-8","moduleId":"urinary-system-neoplasms","stem":"What is the first-line treatment for localized renal cell carcinoma?","options":[{"id":"a","text":"Chemotherapy"},{"id":"b","text":"Radiation therapy"},{"id":"c","text":"Partial or radical nephrectomy"},{"id":"d","text":"Immunotherapy"}],"answerId":"c","explanation":"The first-line treatment for localized renal cell carcinoma is surgical intervention, either partial or radical nephrectomy.","kind":"integration","linkedModuleIds":["antineoplastic-principles"],"origin":"ai"}],"chronic-kidney-disease":[{"id":"chronic-kidney-disease~ai-0","moduleId":"chronic-kidney-disease","stem":"What is the definition of chronic kidney disease (CKD)?","options":[{"id":"a","text":"GFR <60 mL/min for ≥3 months"},{"id":"b","text":"GFR <30 mL/min for ≥6 months"},{"id":"c","text":"GFR <45 mL/min for ≥1 month"},{"id":"d","text":"GFR <60 mL/min for ≥1 month"}],"answerId":"a","explanation":"CKD is defined as kidney damage or a GFR <60 mL/min persisting for at least 3 months.","kind":"recall","origin":"ai"},{"id":"chronic-kidney-disease~ai-1","moduleId":"chronic-kidney-disease","stem":"Which of the following is a common cause of chronic kidney disease?","options":[{"id":"a","text":"Glomerulonephritis"},{"id":"b","text":"Diabetes mellitus"},{"id":"c","text":"Acute tubular necrosis"},{"id":"d","text":"Polycystic kidney disease"}],"answerId":"b","explanation":"Diabetes mellitus is one of the most common causes of chronic kidney disease.","kind":"recall","origin":"ai"},{"id":"chronic-kidney-disease~ai-2","moduleId":"chronic-kidney-disease","stem":"What is the primary hormonal deficiency in chronic kidney disease leading to anemia?","options":[{"id":"a","text":"Decreased erythropoietin production"},{"id":"b","text":"Increased erythropoietin production"},{"id":"c","text":"Decreased calcitriol production"},{"id":"d","text":"Increased calcitriol production"}],"answerId":"a","explanation":"In CKD, there is a decreased production of erythropoietin, leading to normocytic anemia.","kind":"mechanism","origin":"ai"},{"id":"chronic-kidney-disease~ai-3","moduleId":"chronic-kidney-disease","stem":"What is the expected laboratory finding in CKD-MBD?","options":[{"id":"a","text":"Hypercalcemia and hypophosphatemia"},{"id":"b","text":"Hypocalcemia and hyperphosphatemia"},{"id":"c","text":"Normal calcium and normal phosphate"},{"id":"d","text":"Hypocalcemia and normal phosphate"}],"answerId":"b","explanation":"In CKD-MBD, phosphate levels are elevated due to impaired excretion, while calcium levels are often low due to decreased calcitriol.","kind":"recall","origin":"ai"},{"id":"chronic-kidney-disease~ai-4","moduleId":"chronic-kidney-disease","stem":"Which of the following is a key management strategy for slowing progression of CKD?","options":[{"id":"a","text":"Increased protein intake"},{"id":"b","text":"Use of ACE inhibitors"},{"id":"c","text":"Increased fluid intake"},{"id":"d","text":"Use of diuretics"}],"answerId":"b","explanation":"ACE inhibitors are used to control blood pressure and proteinuria, which helps slow the progression of CKD.","kind":"trap","origin":"ai"},{"id":"chronic-kidney-disease~ai-5","moduleId":"chronic-kidney-disease","stem":"A patient with chronic kidney disease presents with fatigue and pallor. Which laboratory finding would you expect?","options":[{"id":"a","text":"Microcytic anemia"},{"id":"b","text":"Normocytic anemia"},{"id":"c","text":"Macrocytic anemia"},{"id":"d","text":"Hemolytic anemia"}],"answerId":"b","explanation":"Patients with CKD typically develop normocytic anemia due to decreased erythropoietin production.","kind":"clinical","origin":"ai"},{"id":"chronic-kidney-disease~ai-6","moduleId":"chronic-kidney-disease","stem":"How does chronic kidney disease affect vitamin D metabolism?","options":[{"id":"a","text":"Increases calcitriol production"},{"id":"b","text":"Decreases calcitriol production"},{"id":"c","text":"Increases vitamin D absorption"},{"id":"d","text":"Decreases vitamin D absorption"}],"answerId":"b","explanation":"In CKD, the kidneys are less able to convert vitamin D to its active form (calcitriol), leading to decreased levels.","kind":"mechanism","origin":"ai"},{"id":"chronic-kidney-disease~ai-7","moduleId":"chronic-kidney-disease","stem":"In chronic kidney disease, which of the following is the most likely finding on kidney ultrasound?","options":[{"id":"a","text":"Enlarged kidneys"},{"id":"b","text":"Normal-sized kidneys"},{"id":"c","text":"Small, shrunken kidneys"},{"id":"d","text":"Cysts in the kidneys"}],"answerId":"c","explanation":"Chronic kidney disease typically presents with small, shrunken kidneys on ultrasound due to nephron loss.","kind":"recall","origin":"ai"},{"id":"chronic-kidney-disease~ai-8","moduleId":"chronic-kidney-disease","stem":"A patient with CKD is being evaluated for renal replacement therapy. Which of the following findings would indicate the need for dialysis?","options":[{"id":"a","text":"GFR <30 mL/min"},{"id":"b","text":"Persistent hyperkalemia"},{"id":"c","text":"Proteinuria >1g/day"},{"id":"d","text":"Anemia unresponsive to treatment"}],"answerId":"b","explanation":"Persistent hyperkalemia is a clear indication for renal replacement therapy in CKD patients.","kind":"clinical","origin":"ai"},{"id":"chronic-kidney-disease~ai-9","moduleId":"chronic-kidney-disease","stem":"How does chronic kidney disease relate to renal artery stenosis?","options":[{"id":"a","text":"CKD can cause renal artery stenosis"},{"id":"b","text":"Renal artery stenosis can lead to CKD"},{"id":"c","text":"Both are unrelated conditions"},{"id":"d","text":"CKD is a type of renal artery stenosis"}],"answerId":"b","explanation":"Renal artery stenosis can lead to chronic kidney disease due to decreased renal perfusion and subsequent nephron damage.","kind":"integration","linkedModuleIds":["renal-artery-stenosis"],"origin":"ai"}],"nephritic-syndrome":[{"id":"nephritic-syndrome~ai-0","moduleId":"nephritic-syndrome","stem":"What is the most common cause of nephritic syndrome worldwide?","options":[{"id":"a","text":"Post-streptococcal glomerulonephritis"},{"id":"b","text":"IgA nephropathy"},{"id":"c","text":"Membranoproliferative glomerulonephritis"},{"id":"d","text":"Rapidly progressive glomerulonephritis"}],"answerId":"b","explanation":"IgA nephropathy, also known as Berger's disease, is the most common form of glomerulonephritis globally.","kind":"recall","origin":"ai"},{"id":"nephritic-syndrome~ai-1","moduleId":"nephritic-syndrome","stem":"A child presents with cola-colored urine and edema 2 weeks after a throat infection. What is the most likely diagnosis?","options":[{"id":"a","text":"IgA nephropathy"},{"id":"b","text":"Post-streptococcal glomerulonephritis"},{"id":"c","text":"Minimal change disease"},{"id":"d","text":"Membranous nephropathy"}],"answerId":"b","explanation":"The timing and symptoms suggest post-streptococcal glomerulonephritis, which typically occurs 1-3 weeks after a streptococcal infection.","kind":"clinical","origin":"ai"},{"id":"nephritic-syndrome~ai-2","moduleId":"nephritic-syndrome","stem":"Which finding is characteristic of rapidly progressive glomerulonephritis (RPGN)?","options":[{"id":"a","text":"Subepithelial humps"},{"id":"b","text":"Crescents on biopsy"},{"id":"c","text":"Dysmorphic red blood cells"},{"id":"d","text":"Low complement levels"}],"answerId":"b","explanation":"Crescents on biopsy are a hallmark of RPGN, indicating severe glomerular injury.","kind":"recall","origin":"ai"},{"id":"nephritic-syndrome~ai-3","moduleId":"nephritic-syndrome","stem":"In a patient with nephritic syndrome, which laboratory finding would most likely indicate post-streptococcal glomerulonephritis?","options":[{"id":"a","text":"Normal complement levels"},{"id":"b","text":"Elevated anti-DNase B titers"},{"id":"c","text":"Positive ANCA"},{"id":"d","text":"High serum creatinine"}],"answerId":"b","explanation":"Elevated anti-DNase B titers are indicative of a recent streptococcal infection, supporting a diagnosis of post-streptococcal glomerulonephritis.","kind":"mechanism","origin":"ai"},{"id":"nephritic-syndrome~ai-4","moduleId":"nephritic-syndrome","stem":"Which of the following is a distinguishing feature between IgA nephropathy and post-streptococcal glomerulonephritis?","options":[{"id":"a","text":"Presence of crescents on biopsy"},{"id":"b","text":"Timing of hematuria onset"},{"id":"c","text":"Complement levels"},{"id":"d","text":"Age of the patient"}],"answerId":"b","explanation":"The timing of hematuria onset is crucial: IgA nephropathy occurs concurrently or 1-2 days after infection, while post-streptococcal occurs 1-3 weeks later.","kind":"trap","origin":"ai"},{"id":"nephritic-syndrome~ai-5","moduleId":"nephritic-syndrome","stem":"A patient with rapidly progressive glomerulonephritis has linear staining of the glomerular basement membrane on immunofluorescence. What is the likely diagnosis?","options":[{"id":"a","text":"IgA nephropathy"},{"id":"b","text":"Goodpasture syndrome"},{"id":"c","text":"Lupus nephritis"},{"id":"d","text":"Membranoproliferative glomerulonephritis"}],"answerId":"b","explanation":"Linear staining of the glomerular basement membrane is characteristic of Goodpasture syndrome, which involves anti-GBM antibodies.","kind":"clinical","origin":"ai"},{"id":"nephritic-syndrome~ai-6","moduleId":"nephritic-syndrome","stem":"How does IgA nephropathy typically present after an upper respiratory infection?","options":[{"id":"a","text":"With low complement levels"},{"id":"b","text":"With visible hematuria 1-2 days later"},{"id":"c","text":"With rapid renal failure"},{"id":"d","text":"With nephrotic range proteinuria"}],"answerId":"b","explanation":"IgA nephropathy often presents with visible hematuria 1-2 days after an upper respiratory infection, distinguishing it from other types of glomerulonephritis.","kind":"recall","origin":"ai"},{"id":"nephritic-syndrome~ai-7","moduleId":"nephritic-syndrome","stem":"A patient with nephritic syndrome undergoes urinalysis. What finding would most strongly suggest IgA nephropathy?","options":[{"id":"a","text":"Red cell casts"},{"id":"b","text":"Low C3 levels"},{"id":"c","text":"Crescents"},{"id":"d","text":"Normal protein levels"}],"answerId":"a","explanation":"Red cell casts are indicative of glomerular inflammation and are commonly seen in IgA nephropathy.","kind":"integration","linkedModuleIds":["urinalysis-urine-examination"],"origin":"ai"},{"id":"nephritic-syndrome~ai-8","moduleId":"nephritic-syndrome","stem":"In a patient with nephritic syndrome, which mechanism is primarily involved in IgA nephropathy?","options":[{"id":"a","text":"Immune complex deposition"},{"id":"b","text":"Anti-GBM antibody formation"},{"id":"c","text":"Complement activation"},{"id":"d","text":"Vascular injury"}],"answerId":"a","explanation":"IgA nephropathy is characterized by immune complex deposition in the mesangium, leading to glomerular inflammation.","kind":"integration","linkedModuleIds":["glomerular-disease-immune-mechanisms"],"origin":"ai"}],"drug-dosing-ckd":[{"id":"drug-dosing-ckd~ai-0","moduleId":"drug-dosing-ckd","stem":"Which of the following drugs requires dose adjustment in patients with chronic kidney disease (CKD)?","options":[{"id":"a","text":"Ibuprofen"},{"id":"b","text":"Aminoglycosides"},{"id":"c","text":"Acetaminophen"},{"id":"d","text":"Metoprolol"}],"answerId":"b","explanation":"Aminoglycosides are renally cleared and require dose adjustment in CKD to prevent toxicity.","kind":"recall","origin":"ai"},{"id":"drug-dosing-ckd~ai-1","moduleId":"drug-dosing-ckd","stem":"What is the primary reason for reducing the maintenance dose of renally-cleared drugs in CKD?","options":[{"id":"a","text":"Increased volume of distribution"},{"id":"b","text":"Decreased renal clearance"},{"id":"c","text":"Increased hepatic metabolism"},{"id":"d","text":"Decreased protein binding"}],"answerId":"b","explanation":"Decreased renal clearance in CKD leads to accumulation of renally-cleared drugs, necessitating dose adjustment.","kind":"mechanism","origin":"ai"},{"id":"drug-dosing-ckd~ai-2","moduleId":"drug-dosing-ckd","stem":"A patient with CKD is started on digoxin. What monitoring is essential to avoid toxicity?","options":[{"id":"a","text":"Liver function tests"},{"id":"b","text":"Serum creatinine levels"},{"id":"c","text":"Serum digoxin levels"},{"id":"d","text":"Complete blood count"}],"answerId":"c","explanation":"Serum digoxin levels should be monitored to prevent toxicity due to accumulation in CKD.","kind":"clinical","origin":"ai"},{"id":"drug-dosing-ckd~ai-3","moduleId":"drug-dosing-ckd","stem":"In a patient with CKD, which of the following is a common nephrotoxic drug that should be avoided?","options":[{"id":"a","text":"Vancomycin"},{"id":"b","text":"Aminoglycosides"},{"id":"c","text":"Metformin"},{"id":"d","text":"Gabapentin"}],"answerId":"c","explanation":"Metformin should be avoided in CKD due to the risk of lactic acidosis.","kind":"trap","origin":"ai"},{"id":"drug-dosing-ckd~ai-4","moduleId":"drug-dosing-ckd","stem":"Which of the following statements about loading doses in CKD is true?","options":[{"id":"a","text":"Loading doses should always be reduced"},{"id":"b","text":"Loading doses are unchanged"},{"id":"c","text":"Loading doses depend on renal function"},{"id":"d","text":"Loading doses are not necessary"}],"answerId":"b","explanation":"Loading doses are typically unchanged in CKD as they depend on volume of distribution, not clearance.","kind":"trap","origin":"ai"},{"id":"drug-dosing-ckd~ai-5","moduleId":"drug-dosing-ckd","stem":"A patient with CKD is prescribed a medication that is primarily renally cleared. What is the most appropriate action regarding the dosing regimen?","options":[{"id":"a","text":"Increase the dose"},{"id":"b","text":"Extend the dosing interval"},{"id":"c","text":"Maintain the current dose"},{"id":"d","text":"Avoid the medication entirely"}],"answerId":"b","explanation":"In CKD, extending the dosing interval helps prevent drug accumulation and toxicity.","kind":"mechanism","origin":"ai"},{"id":"drug-dosing-ckd~ai-6","moduleId":"drug-dosing-ckd","stem":"How does chronic kidney disease (CKD) affect the pharmacokinetics of renally-cleared drugs?","options":[{"id":"a","text":"Increased absorption"},{"id":"b","text":"Decreased distribution"},{"id":"c","text":"Increased clearance"},{"id":"d","text":"Decreased elimination"}],"answerId":"d","explanation":"CKD leads to decreased elimination of renally-cleared drugs due to reduced renal function.","kind":"integration","linkedModuleIds":["chronic-kidney-disease"],"origin":"ai"},{"id":"drug-dosing-ckd~ai-7","moduleId":"drug-dosing-ckd","stem":"Which of the following drug interactions is particularly concerning in a patient with CKD?","options":[{"id":"a","text":"ACE inhibitor with diuretic"},{"id":"b","text":"Antibiotic with oral contraceptive"},{"id":"c","text":"Statin with grapefruit juice"},{"id":"d","text":"Beta-blocker with NSAID"}],"answerId":"a","explanation":"The combination of ACE inhibitors and diuretics can lead to significant renal impairment, especially in CKD patients.","kind":"integration","linkedModuleIds":["drug-interactions-mechanisms"],"origin":"ai"}],"cystic-kidney-diseases":[{"id":"cystic-kidney-diseases~ai-0","moduleId":"cystic-kidney-diseases","stem":"What is the most common genetic mutation associated with Autosomal Dominant Polycystic Kidney Disease (ADPKD)?","options":[{"id":"a","text":"PKD1"},{"id":"b","text":"PKD2"},{"id":"c","text":"PKD3"},{"id":"d","text":"PKD4"}],"answerId":"a","explanation":"PKD1 mutations on chromosome 16 are the most common cause of ADPKD, leading to more severe disease.","kind":"recall","origin":"ai"},{"id":"cystic-kidney-diseases~ai-1","moduleId":"cystic-kidney-diseases","stem":"Which imaging finding is characteristic of a simple renal cyst?","options":[{"id":"a","text":"Complex cyst with septa"},{"id":"b","text":"Thin-walled cyst without solid components"},{"id":"c","text":"Enhancing solid mass"},{"id":"d","text":"Multiple small cysts"}],"answerId":"b","explanation":"A simple renal cyst appears as a thin-walled cyst without solid components on imaging, indicating it is benign.","kind":"recall","origin":"ai"},{"id":"cystic-kidney-diseases~ai-2","moduleId":"cystic-kidney-diseases","stem":"A 30-year-old male with ADPKD presents with a sudden severe headache. What is the most likely cause?","options":[{"id":"a","text":"Intracranial hemorrhage from hypertension"},{"id":"b","text":"Ruptured berry aneurysm"},{"id":"c","text":"Migraine"},{"id":"d","text":"Tension headache"}],"answerId":"b","explanation":"Patients with ADPKD are at increased risk for ruptured berry aneurysms, which can cause sudden severe headaches.","kind":"clinical","origin":"ai"},{"id":"cystic-kidney-diseases~ai-3","moduleId":"cystic-kidney-diseases","stem":"Which of the following is a common extrarenal manifestation of ADPKD?","options":[{"id":"a","text":"Oligohydramnios"},{"id":"b","text":"Hepatic cysts"},{"id":"c","text":"Nephronophthisis"},{"id":"d","text":"Medullary sponge kidney"}],"answerId":"b","explanation":"Hepatic cysts are a common extrarenal manifestation of ADPKD, along with other complications.","kind":"trap","origin":"ai"},{"id":"cystic-kidney-diseases~ai-4","moduleId":"cystic-kidney-diseases","stem":"In a patient with ARPKD, which of the following findings is most likely?","options":[{"id":"a","text":"Bilateral enlarged kidneys with hepatic fibrosis"},{"id":"b","text":"Multiple renal stones"},{"id":"c","text":"Single renal cyst"},{"id":"d","text":"Bilateral renal masses"}],"answerId":"a","explanation":"ARPKD typically presents with bilateral enlarged kidneys and congenital hepatic fibrosis.","kind":"recall","origin":"ai"},{"id":"cystic-kidney-diseases~ai-5","moduleId":"cystic-kidney-diseases","stem":"How does tolvaptan help in managing ADPKD?","options":[{"id":"a","text":"Reduces hypertension"},{"id":"b","text":"Slows cyst growth"},{"id":"c","text":"Increases urine output"},{"id":"d","text":"Decreases renal blood flow"}],"answerId":"b","explanation":"Tolvaptan is a vasopressin V2 antagonist that can slow the progression of cyst growth in ADPKD.","kind":"mechanism","origin":"ai"},{"id":"cystic-kidney-diseases~ai-6","moduleId":"cystic-kidney-diseases","stem":"How is the risk of renal cell carcinoma (RCC) related to acquired cystic disease in dialysis patients?","options":[{"id":"a","text":"Increased risk due to cyst formation"},{"id":"b","text":"Decreased risk due to renal failure"},{"id":"c","text":"No relation"},{"id":"d","text":"Increased risk due to hypertension"}],"answerId":"a","explanation":"Acquired cystic disease in long-term dialysis patients is associated with an increased risk of renal cell carcinoma due to cyst formation.","kind":"integration","linkedModuleIds":["urinary-system-neoplasms"],"origin":"ai"},{"id":"cystic-kidney-diseases~ai-7","moduleId":"cystic-kidney-diseases","stem":"Which condition is most likely to present with congenital hepatic fibrosis in infancy?","options":[{"id":"a","text":"ADPKD"},{"id":"b","text":"ARPKD"},{"id":"c","text":"Simple renal cyst"},{"id":"d","text":"Medullary sponge kidney"}],"answerId":"b","explanation":"ARPKD is characterized by congenital hepatic fibrosis and presents in infancy.","kind":"integration","linkedModuleIds":["chronic-kidney-disease"],"origin":"ai"}],"renovascular-disorders":[{"id":"renovascular-disorders~ai-0","moduleId":"renovascular-disorders","stem":"What is the most common cause of renal artery stenosis in older patients?","options":[{"id":"a","text":"Fibromuscular dysplasia"},{"id":"b","text":"Atherosclerosis"},{"id":"c","text":"Thrombotic microangiopathy"},{"id":"d","text":"Hypertensive nephrosclerosis"}],"answerId":"b","explanation":"Atherosclerosis is the most common cause of renal artery stenosis in older patients, leading to renovascular hypertension.","kind":"recall","origin":"ai"},{"id":"renovascular-disorders~ai-1","moduleId":"renovascular-disorders","stem":"Which finding is characteristic of fibromuscular dysplasia in renal imaging?","options":[{"id":"a","text":"Resistant hypertension"},{"id":"b","text":"String of beads appearance"},{"id":"c","text":"Fibrinoid necrosis"},{"id":"d","text":"Schistocytes in blood smear"}],"answerId":"b","explanation":"The 'string of beads' appearance on imaging is a classic finding in fibromuscular dysplasia.","kind":"recall","origin":"ai"},{"id":"renovascular-disorders~ai-2","moduleId":"renovascular-disorders","stem":"What mechanism underlies the risk of acute kidney injury when starting an ACE inhibitor in bilateral renal artery stenosis?","options":[{"id":"a","text":"Increased renal perfusion"},{"id":"b","text":"Decreased efferent arteriolar constriction"},{"id":"c","text":"Increased angiotensin II levels"},{"id":"d","text":"Decreased glomerular filtration rate"}],"answerId":"b","explanation":"In bilateral renal artery stenosis, ACE inhibitors decrease efferent arteriolar constriction, leading to a drop in glomerular filtration rate and potential acute kidney injury.","kind":"mechanism","origin":"ai"},{"id":"renovascular-disorders~ai-3","moduleId":"renovascular-disorders","stem":"A 7-year-old presents with bloody diarrhea, thrombocytopenia, and acute kidney injury. What is the most likely diagnosis?","options":[{"id":"a","text":"Thrombotic thrombocytopenic purpura"},{"id":"b","text":"Hemolytic-uremic syndrome"},{"id":"c","text":"Renal artery stenosis"},{"id":"d","text":"Malignant hypertension"}],"answerId":"b","explanation":"The presentation is consistent with hemolytic-uremic syndrome, often caused by Shiga-toxin E. coli in children.","kind":"clinical","origin":"ai"},{"id":"renovascular-disorders~ai-4","moduleId":"renovascular-disorders","stem":"In the context of chronic kidney disease, what is a key consideration when prescribing ACE inhibitors?","options":[{"id":"a","text":"They are always renoprotective"},{"id":"b","text":"They should be avoided in all cases"},{"id":"c","text":"Monitor for creatinine rise in bilateral renal artery stenosis"},{"id":"d","text":"They improve renal perfusion in all patients"}],"answerId":"c","explanation":"In chronic kidney disease, particularly with bilateral renal artery stenosis, ACE inhibitors can lead to a significant rise in creatinine, necessitating careful monitoring.","kind":"trap","origin":"ai"},{"id":"renovascular-disorders~ai-5","moduleId":"renovascular-disorders","stem":"How does hypertensive nephrosclerosis lead to chronic kidney disease?","options":[{"id":"a","text":"By causing renal artery stenosis"},{"id":"b","text":"Through chronic damage to renal arterioles"},{"id":"c","text":"By increasing glomerular filtration rate"},{"id":"d","text":"Through acute tubular necrosis"}],"answerId":"b","explanation":"Hypertensive nephrosclerosis results from chronic hypertension damaging renal arterioles, leading to progressive chronic kidney disease.","kind":"mechanism","origin":"ai"},{"id":"renovascular-disorders~ai-6","moduleId":"renovascular-disorders","stem":"How is renal artery stenosis related to chronic kidney disease?","options":[{"id":"a","text":"It causes acute tubular necrosis"},{"id":"b","text":"It leads to secondary hypertension and renal damage"},{"id":"c","text":"It is a direct cause of glomerulonephritis"},{"id":"d","text":"It prevents the progression of chronic kidney disease"}],"answerId":"b","explanation":"Renal artery stenosis can lead to secondary hypertension, which ultimately contributes to renal damage and chronic kidney disease.","kind":"integration","linkedModuleIds":["chronic-kidney-disease"],"origin":"ai"},{"id":"renovascular-disorders~ai-7","moduleId":"renovascular-disorders","stem":"What is the relationship between thrombotic microangiopathy and renal artery stenosis?","options":[{"id":"a","text":"Both cause acute kidney injury"},{"id":"b","text":"Both are forms of chronic kidney disease"},{"id":"c","text":"Both are characterized by resistant hypertension"},{"id":"d","text":"Both are treated with ACE inhibitors"}],"answerId":"a","explanation":"Thrombotic microangiopathy and renal artery stenosis can both lead to acute kidney injury, but they have different underlying mechanisms.","kind":"integration","linkedModuleIds":["renal-artery-stenosis"],"origin":"ai"}],"uti-clinical-management":[{"id":"uti-clinical-management~ai-0","moduleId":"uti-clinical-management","stem":"A 28-year-old woman presents with dysuria, frequency, and urgency but no fever. What is the most likely diagnosis?","options":[{"id":"a","text":"Acute pyelonephritis"},{"id":"b","text":"Cystitis"},{"id":"c","text":"Urosepsis"},{"id":"d","text":"Prostatitis"}],"answerId":"b","explanation":"The symptoms of dysuria, frequency, and urgency without fever indicate cystitis, which is a lower urinary tract infection.","kind":"recall","origin":"ai"},{"id":"uti-clinical-management~ai-1","moduleId":"uti-clinical-management","stem":"Which of the following is a characteristic finding in acute pyelonephritis?","options":[{"id":"a","text":"Suprapubic pain"},{"id":"b","text":"Costovertebral-angle tenderness"},{"id":"c","text":"Cloudy urine"},{"id":"d","text":"Dysuria"}],"answerId":"b","explanation":"Costovertebral-angle tenderness is a key clinical finding in acute pyelonephritis, indicating upper urinary tract involvement.","kind":"recall","origin":"ai"},{"id":"uti-clinical-management~ai-2","moduleId":"uti-clinical-management","stem":"What is the recommended management for a complicated UTI in a pregnant woman?","options":[{"id":"a","text":"Short-course oral antibiotics"},{"id":"b","text":"Longer course with urine culture"},{"id":"c","text":"Immediate IV antibiotics only"},{"id":"d","text":"Symptomatic treatment only"}],"answerId":"b","explanation":"Complicated UTIs in pregnant women require a longer course of antibiotics and urine culture to guide treatment.","kind":"clinical","origin":"ai"},{"id":"uti-clinical-management~ai-3","moduleId":"uti-clinical-management","stem":"In which situation is a UTI considered complicated?","options":[{"id":"a","text":"A healthy non-pregnant woman"},{"id":"b","text":"A man with dysuria"},{"id":"c","text":"A woman with a history of recurrent UTIs"},{"id":"d","text":"A child with fever"}],"answerId":"b","explanation":"Any UTI in a man is classified as complicated due to the higher risk of underlying abnormalities.","kind":"trap","origin":"ai"},{"id":"uti-clinical-management~ai-4","moduleId":"uti-clinical-management","stem":"What is the primary mechanism of action for nitrofurantoin in treating UTIs?","options":[{"id":"a","text":"Inhibition of bacterial cell wall synthesis"},{"id":"b","text":"Inhibition of protein synthesis"},{"id":"c","text":"Inhibition of nucleic acid synthesis"},{"id":"d","text":"Disruption of bacterial metabolism"}],"answerId":"d","explanation":"Nitrofurantoin disrupts bacterial metabolism, making it effective against certain urinary pathogens.","kind":"mechanism","origin":"ai"},{"id":"uti-clinical-management~ai-5","moduleId":"uti-clinical-management","stem":"A patient with recurrent UTIs is found to have a kidney stone. Which management strategy is most appropriate?","options":[{"id":"a","text":"Short-course antibiotics"},{"id":"b","text":"Long-term prophylactic antibiotics"},{"id":"c","text":"Surgical intervention for the stone"},{"id":"d","text":"Increased fluid intake only"}],"answerId":"c","explanation":"Surgical intervention may be necessary to remove the stone, as it can be a source of recurrent infections.","kind":"clinical","origin":"ai"},{"id":"uti-clinical-management~ai-6","moduleId":"uti-clinical-management","stem":"How does urosepsis differ from pyelonephritis?","options":[{"id":"a","text":"Urosepsis is always asymptomatic"},{"id":"b","text":"Urosepsis indicates systemic infection from urinary source"},{"id":"c","text":"Pyelonephritis does not require antibiotics"},{"id":"d","text":"Urosepsis is treated with oral antibiotics only"}],"answerId":"b","explanation":"Urosepsis is a systemic inflammatory response due to a urinary source, requiring urgent management.","kind":"trap","origin":"ai"},{"id":"uti-clinical-management~ai-7","moduleId":"uti-clinical-management","stem":"Which organism is most commonly associated with uncomplicated cystitis?","options":[{"id":"a","text":"Staphylococcus saprophyticus"},{"id":"b","text":"Escherichia coli"},{"id":"c","text":"Klebsiella pneumoniae"},{"id":"d","text":"Enterococcus faecalis"}],"answerId":"b","explanation":"Escherichia coli is the most common pathogen responsible for uncomplicated cystitis.","kind":"recall","origin":"ai"},{"id":"uti-clinical-management~ai-8","moduleId":"uti-clinical-management","stem":"In a patient with acute pyelonephritis, which of the following findings would you expect on urinalysis?","options":[{"id":"a","text":"Presence of white-cell casts"},{"id":"b","text":"Negative urine culture"},{"id":"c","text":"High glucose levels"},{"id":"d","text":"Presence of red blood cells only"}],"answerId":"a","explanation":"White-cell casts are indicative of renal parenchymal infection, which is characteristic of acute pyelonephritis.","kind":"recall","origin":"ai"},{"id":"uti-clinical-management~ai-9","moduleId":"uti-clinical-management","stem":"What is the relationship between UTI management and the use of protein synthesis inhibitors?","options":[{"id":"a","text":"They are first-line for all UTIs"},{"id":"b","text":"They are contraindicated in pregnancy"},{"id":"c","text":"They can be used for complicated UTIs"},{"id":"d","text":"They are not effective against E. coli"}],"answerId":"c","explanation":"Protein synthesis inhibitors, such as certain fluoroquinolones, can be used for complicated UTIs, but their use must be carefully considered in specific populations.","kind":"integration","linkedModuleIds":["antibacterial-protein-synthesis-inhibitors"],"origin":"ai"}],"glomerular-disease-overview":[{"id":"glomerular-disease-overview~ai-0","moduleId":"glomerular-disease-overview","stem":"What is the primary mechanism leading to heavy proteinuria in nephrotic syndrome?","options":[{"id":"a","text":"Podocyte injury"},{"id":"b","text":"Glomerular inflammation"},{"id":"c","text":"Immune complex deposition"},{"id":"d","text":"Tubular dysfunction"}],"answerId":"a","explanation":"Heavy proteinuria in nephrotic syndrome is primarily due to podocyte injury, which disrupts the filtration barrier.","kind":"mechanism","origin":"ai"},{"id":"glomerular-disease-overview~ai-1","moduleId":"glomerular-disease-overview","stem":"Which finding is characteristic of nephritic syndrome?","options":[{"id":"a","text":"Heavy proteinuria"},{"id":"b","text":"Bland urine"},{"id":"c","text":"Haematuria with red-cell casts"},{"id":"d","text":"Oedema"}],"answerId":"c","explanation":"Nephritic syndrome is characterized by haematuria with red-cell casts due to glomerular inflammation.","kind":"recall","origin":"ai"},{"id":"glomerular-disease-overview~ai-2","moduleId":"glomerular-disease-overview","stem":"In which condition would you expect low serum complement levels?","options":[{"id":"a","text":"IgA nephropathy"},{"id":"b","text":"Post-streptococcal glomerulonephritis"},{"id":"c","text":"Anti-GBM disease"},{"id":"d","text":"ANCA vasculitis"}],"answerId":"b","explanation":"Low serum complement levels are typically seen in post-streptococcal glomerulonephritis due to immune complex consumption.","kind":"trap","origin":"ai"},{"id":"glomerular-disease-overview~ai-3","moduleId":"glomerular-disease-overview","stem":"What is the first step in the work-up of suspected glomerular disease?","options":[{"id":"a","text":"Renal biopsy"},{"id":"b","text":"Urinalysis"},{"id":"c","text":"Serum complement levels"},{"id":"d","text":"Blood pressure assessment"}],"answerId":"b","explanation":"The first step in the work-up of suspected glomerular disease is urinalysis to assess proteinuria and hematuria.","kind":"recall","origin":"ai"},{"id":"glomerular-disease-overview~ai-4","moduleId":"glomerular-disease-overview","stem":"A patient presents with nephritic syndrome and normal complement levels. Which condition is most likely?","options":[{"id":"a","text":"Lupus nephritis"},{"id":"b","text":"Post-streptococcal GN"},{"id":"c","text":"IgA nephropathy"},{"id":"d","text":"Membranoproliferative GN"}],"answerId":"c","explanation":"Normal complement levels in nephritic syndrome suggest conditions like IgA nephropathy, while low levels indicate other diseases.","kind":"integration","linkedModuleIds":["nephritic-syndrome"],"origin":"ai"},{"id":"glomerular-disease-overview~ai-5","moduleId":"glomerular-disease-overview","stem":"Which of the following findings would be expected in a renal biopsy of a patient with nephrotic syndrome?","options":[{"id":"a","text":"Crescent formation"},{"id":"b","text":"Subepithelial immune complex deposits"},{"id":"c","text":"Dysmorphic red blood cells"},{"id":"d","text":"Normal glomerular architecture"}],"answerId":"b","explanation":"Subepithelial immune complex deposits are characteristic of nephrotic syndrome, particularly in conditions like minimal change disease.","kind":"recall","origin":"ai"},{"id":"glomerular-disease-overview~ai-6","moduleId":"glomerular-disease-overview","stem":"How does the mechanism of injury differ between nephrotic and nephritic syndromes?","options":[{"id":"a","text":"Nephrotic involves inflammation; nephritic involves podocyte injury"},{"id":"b","text":"Nephrotic involves podocyte injury; nephritic involves inflammation"},{"id":"c","text":"Both involve podocyte injury"},{"id":"d","text":"Both involve inflammation"}],"answerId":"b","explanation":"Nephrotic syndrome is characterized by podocyte injury leading to proteinuria, while nephritic syndrome involves inflammation causing hematuria.","kind":"integration","linkedModuleIds":["nephrotic-syndrome"],"origin":"ai"}],"fluid-electrolyte-disorders":[{"id":"fluid-electrolyte-disorders~ai-0","moduleId":"fluid-electrolyte-disorders","stem":"A 65-year-old man presents with confusion and seizures. Laboratory tests reveal serum sodium of 120 mEq/L and low serum osmolality. What is the most likely cause of his hyponatraemia?","options":[{"id":"a","text":"Diuretic use"},{"id":"b","text":"Heart failure"},{"id":"c","text":"SIADH"},{"id":"d","text":"Cirrhosis"}],"answerId":"c","explanation":"The patient's euvolaemic status and low serum osmolality suggest SIADH as the cause of hyponatraemia.","kind":"clinical","origin":"ai"},{"id":"fluid-electrolyte-disorders~ai-1","moduleId":"fluid-electrolyte-disorders","stem":"Which of the following is a critical first step in managing a patient with hyperkalaemia?","options":[{"id":"a","text":"Administer insulin and glucose"},{"id":"b","text":"Start dialysis"},{"id":"c","text":"Administer calcium gluconate"},{"id":"d","text":"Increase dietary potassium"}],"answerId":"c","explanation":"Calcium gluconate is administered first to stabilize the myocardium in cases of hyperkalaemia.","kind":"mechanism","origin":"ai"},{"id":"fluid-electrolyte-disorders~ai-2","moduleId":"fluid-electrolyte-disorders","stem":"A patient with chronic hyponatraemia is admitted for seizures. What is the safest approach to correct his sodium levels?","options":[{"id":"a","text":"Rapid infusion of hypertonic saline"},{"id":"b","text":"Slow correction with isotonic saline"},{"id":"c","text":"No correction needed"},{"id":"d","text":"Rapid oral sodium intake"}],"answerId":"b","explanation":"Chronic hyponatraemia must be corrected slowly to prevent osmotic demyelination syndrome.","kind":"trap","origin":"ai"},{"id":"fluid-electrolyte-disorders~ai-3","moduleId":"fluid-electrolyte-disorders","stem":"A 45-year-old woman presents with muscle weakness and an ECG shows U waves. Which electrolyte disorder is most likely responsible?","options":[{"id":"a","text":"Hyperkalaemia"},{"id":"b","text":"Hypokalaemia"},{"id":"c","text":"Hypercalcaemia"},{"id":"d","text":"Hyponatraemia"}],"answerId":"b","explanation":"U waves on ECG are characteristic of hypokalaemia, which can cause muscle weakness.","kind":"recall","origin":"ai"},{"id":"fluid-electrolyte-disorders~ai-4","moduleId":"fluid-electrolyte-disorders","stem":"In a patient with hypernatremia, which of the following symptoms is most likely to be observed?","options":[{"id":"a","text":"Muscle cramps"},{"id":"b","text":"Seizures"},{"id":"c","text":"Tachycardia"},{"id":"d","text":"Confusion"}],"answerId":"d","explanation":"Confusion is a common CNS sign in hypernatremia due to water deficit.","kind":"clinical","origin":"ai"},{"id":"fluid-electrolyte-disorders~ai-5","moduleId":"fluid-electrolyte-disorders","stem":"How does chronic renal failure contribute to hyperkalaemia?","options":[{"id":"a","text":"Increased potassium intake"},{"id":"b","text":"Decreased potassium excretion"},{"id":"c","text":"Increased potassium secretion"},{"id":"d","text":"Decreased dietary sodium"}],"answerId":"b","explanation":"Chronic renal failure leads to decreased potassium excretion, causing hyperkalaemia.","kind":"mechanism","origin":"ai"},{"id":"fluid-electrolyte-disorders~ai-6","moduleId":"fluid-electrolyte-disorders","stem":"A patient with chronic heart failure presents with hyponatraemia. Which mechanism is likely responsible for this electrolyte disturbance?","options":[{"id":"a","text":"Increased water retention due to ADH"},{"id":"b","text":"Decreased sodium intake"},{"id":"c","text":"Increased renal sodium excretion"},{"id":"d","text":"Decreased thirst sensation"}],"answerId":"a","explanation":"In heart failure, increased water retention due to inappropriate ADH secretion leads to dilutional hyponatraemia.","kind":"integration","linkedModuleIds":["sodium-water-disorders"],"origin":"ai"},{"id":"fluid-electrolyte-disorders~ai-7","moduleId":"fluid-electrolyte-disorders","stem":"In the context of a patient with metabolic acidosis, how might electrolyte imbalances manifest?","options":[{"id":"a","text":"Hypokalaemia"},{"id":"b","text":"Hypercalcaemia"},{"id":"c","text":"Hyperkalaemia"},{"id":"d","text":"Hyponatraemia"}],"answerId":"c","explanation":"Metabolic acidosis can cause hyperkalaemia due to shifts of potassium from cells into the extracellular space.","kind":"integration","linkedModuleIds":["acid-base-disorders"],"origin":"ai"}],"urinary-tract-host-defenses":[{"id":"urinary-tract-host-defenses~ai-0","moduleId":"urinary-tract-host-defenses","stem":"What is the primary mechanism that maintains sterility in the urinary tract?","options":[{"id":"a","text":"Antibodies in urine"},{"id":"b","text":"Mechanical flushing"},{"id":"c","text":"Low urine pH"},{"id":"d","text":"Mucin secretion"}],"answerId":"b","explanation":"The dominant defense mechanism is mechanical flushing, which involves continuous urine flow and complete bladder emptying.","kind":"recall","origin":"ai"},{"id":"urinary-tract-host-defenses~ai-1","moduleId":"urinary-tract-host-defenses","stem":"Which protein in urine is primarily responsible for trapping bacteria?","options":[{"id":"a","text":"Albumin"},{"id":"b","text":"Tamm-Horsfall protein"},{"id":"c","text":"Immunoglobulin A"},{"id":"d","text":"Urokinase"}],"answerId":"b","explanation":"Tamm-Horsfall protein (uromodulin) is the most abundant urinary protein and plays a key role in trapping bacteria.","kind":"recall","origin":"ai"},{"id":"urinary-tract-host-defenses~ai-2","moduleId":"urinary-tract-host-defenses","stem":"A patient presents with recurrent UTIs and is found to have a bladder stone. What is the most likely mechanism contributing to their condition?","options":[{"id":"a","text":"Increased urine acidity"},{"id":"b","text":"Stasis and incomplete emptying"},{"id":"c","text":"Bacterial virulence factors"},{"id":"d","text":"Immune deficiency"}],"answerId":"b","explanation":"The presence of a bladder stone causes stasis and incomplete emptying, which defeats the flushing mechanism and predisposes to UTIs.","kind":"clinical","origin":"ai"},{"id":"urinary-tract-host-defenses~ai-3","moduleId":"urinary-tract-host-defenses","stem":"In a patient with vesicoureteric reflux, what anatomical feature is primarily compromised?","options":[{"id":"a","text":"Short urethra"},{"id":"b","text":"Competent vesicoureteric junction"},{"id":"c","text":"Bladder compliance"},{"id":"d","text":"Urethral sphincter function"}],"answerId":"b","explanation":"Vesicoureteric reflux occurs due to a defective valve at the vesicoureteric junction, allowing urine to reflux into the ureters.","kind":"mechanism","origin":"ai"},{"id":"urinary-tract-host-defenses~ai-4","moduleId":"urinary-tract-host-defenses","stem":"Which of the following is a key risk factor for urinary tract infections in women?","options":[{"id":"a","text":"Long urethra"},{"id":"b","text":"Frequent hydration"},{"id":"c","text":"Short urethra"},{"id":"d","text":"High urine osmolality"}],"answerId":"c","explanation":"Women have a shorter urethra compared to men, which is a significant risk factor for urinary tract infections.","kind":"trap","origin":"ai"},{"id":"urinary-tract-host-defenses~ai-5","moduleId":"urinary-tract-host-defenses","stem":"How does urinary catheterization increase the risk of UTIs?","options":[{"id":"a","text":"By increasing urine pH"},{"id":"b","text":"By bypassing flushing and mucin defenses"},{"id":"c","text":"By introducing bacteria from the skin"},{"id":"d","text":"By causing bladder overdistension"}],"answerId":"b","explanation":"Urinary catheterization bypasses the natural flushing and mucin defenses, increasing the risk of bacterial colonization.","kind":"clinical","origin":"ai"},{"id":"urinary-tract-host-defenses~ai-6","moduleId":"urinary-tract-host-defenses","stem":"How does understanding urinary tract defenses inform the management of catheter-associated UTIs?","options":[{"id":"a","text":"Emphasizing antibiotic use only"},{"id":"b","text":"Focusing on hydration and catheter removal"},{"id":"c","text":"Recommending longer catheterization"},{"id":"d","text":"Increasing urine acidity"}],"answerId":"b","explanation":"Management emphasizes hydration and timely catheter removal to restore the flushing mechanism and reduce infection risk.","kind":"integration","linkedModuleIds":["catheter-associated-uti"],"origin":"ai"},{"id":"urinary-tract-host-defenses~ai-7","moduleId":"urinary-tract-host-defenses","stem":"What role does uromodulin play in urinary tract defense mechanisms?","options":[{"id":"a","text":"It acts as an antibody"},{"id":"b","text":"It enhances urine flow"},{"id":"c","text":"It traps bacteria in urine"},{"id":"d","text":"It increases urine acidity"}],"answerId":"c","explanation":"Uromodulin (Tamm-Horsfall protein) traps bacteria in urine, helping to prevent urinary tract infections.","kind":"integration","linkedModuleIds":["uropathogenic-ecoli-virulence"],"origin":"ai"}],"uropathogenic-ecoli-virulence":[{"id":"uropathogenic-ecoli-virulence~ai-0","moduleId":"uropathogenic-ecoli-virulence","stem":"What is the primary virulence factor of Uropathogenic E. coli (UPEC) responsible for adhesion to the bladder?","options":[{"id":"a","text":"Type-1 fimbriae"},{"id":"b","text":"P fimbriae"},{"id":"c","text":"Capsule"},{"id":"d","text":"Flagella"}],"answerId":"a","explanation":"Type-1 fimbriae (FimH) specifically bind to mannosylated uroplakin on the bladder urothelium, facilitating adhesion.","kind":"recall","origin":"ai"},{"id":"uropathogenic-ecoli-virulence~ai-1","moduleId":"uropathogenic-ecoli-virulence","stem":"Which virulence factor of UPEC is primarily associated with pyelonephritis?","options":[{"id":"a","text":"Type-1 fimbriae"},{"id":"b","text":"P fimbriae"},{"id":"c","text":"Haemolysin"},{"id":"d","text":"Siderophores"}],"answerId":"b","explanation":"P fimbriae bind to Gal-Gal receptors on the renal epithelium, enabling ascent and infection of the kidney.","kind":"recall","origin":"ai"},{"id":"uropathogenic-ecoli-virulence~ai-2","moduleId":"uropathogenic-ecoli-virulence","stem":"A patient presents with recurrent UTIs caused by the same E. coli strain. What mechanism explains this recurrence?","options":[{"id":"a","text":"Type-1 fimbriae"},{"id":"b","text":"P fimbriae"},{"id":"c","text":"Biofilm formation"},{"id":"d","text":"Haemolysin production"}],"answerId":"c","explanation":"Intracellular bacterial communities and biofilms serve as reservoirs that contribute to recurrent infections.","kind":"mechanism","origin":"ai"},{"id":"uropathogenic-ecoli-virulence~ai-3","moduleId":"uropathogenic-ecoli-virulence","stem":"What finding would suggest that a patient with pyelonephritis has a UPEC infection?","options":[{"id":"a","text":"Gram-positive cocci in urine"},{"id":"b","text":"E. coli with P fimbriae isolated"},{"id":"c","text":"Negative urine culture"},{"id":"d","text":"Presence of leukocyte esterase only"}],"answerId":"b","explanation":"Isolation of E. coli with P fimbriae indicates a strain capable of ascending to the kidneys and causing pyelonephritis.","kind":"recall","origin":"ai"},{"id":"uropathogenic-ecoli-virulence~ai-4","moduleId":"uropathogenic-ecoli-virulence","stem":"Which statement correctly distinguishes the role of fimbriae in UPEC infections?","options":[{"id":"a","text":"All fimbriae cause the same type of infection"},{"id":"b","text":"Type-1 fimbriae are only found in the kidneys"},{"id":"c","text":"P fimbriae are associated with bladder infections"},{"id":"d","text":"Type-1 fimbriae cause cystitis, P fimbriae cause pyelonephritis"}],"answerId":"d","explanation":"Type-1 fimbriae are associated with cystitis, while P fimbriae are linked to pyelonephritis, highlighting their specific roles.","kind":"trap","origin":"ai"},{"id":"uropathogenic-ecoli-virulence~ai-5","moduleId":"uropathogenic-ecoli-virulence","stem":"How do siderophores contribute to UPEC virulence?","options":[{"id":"a","text":"By facilitating adhesion"},{"id":"b","text":"By promoting biofilm formation"},{"id":"c","text":"By scavenging iron"},{"id":"d","text":"By producing toxins"}],"answerId":"c","explanation":"Siderophores are iron-acquisition systems that scavenge scarce iron, which is essential for bacterial growth and virulence.","kind":"mechanism","origin":"ai"},{"id":"uropathogenic-ecoli-virulence~ai-6","moduleId":"uropathogenic-ecoli-virulence","stem":"Which of the following best integrates UPEC virulence mechanisms with host defenses of the urinary tract?","options":[{"id":"a","text":"UPEC's capsule enhances phagocytosis"},{"id":"b","text":"Type-1 fimbriae resist urinary flushing"},{"id":"c","text":"Haemolysin promotes immune response"},{"id":"d","text":"P fimbriae inhibit biofilm formation"}],"answerId":"b","explanation":"Type-1 fimbriae help UPEC resist urinary flushing, a key host defense mechanism, allowing for infection establishment.","kind":"integration","linkedModuleIds":["urinary-tract-host-defenses"],"origin":"ai"},{"id":"uropathogenic-ecoli-virulence~ai-7","moduleId":"uropathogenic-ecoli-virulence","stem":"In the context of UPEC infections, how does the presence of a biofilm relate to urinary tract management?","options":[{"id":"a","text":"Biofilms enhance antibiotic efficacy"},{"id":"b","text":"Biofilms are easily removed by urinary flushing"},{"id":"c","text":"Biofilms contribute to recurrent infections"},{"id":"d","text":"Biofilms prevent UPEC from adhering to urothelium"}],"answerId":"c","explanation":"Biofilms serve as reservoirs for UPEC, complicating treatment and leading to recurrent infections despite antibiotic therapy.","kind":"integration","linkedModuleIds":["uti-clinical-management"],"origin":"ai"}],"acute-pyelonephritis-clinical":[{"id":"acute-pyelonephritis-clinical~ai-0","moduleId":"acute-pyelonephritis-clinical","stem":"What is the most common causative organism of acute pyelonephritis?","options":[{"id":"a","text":"Staphylococcus aureus"},{"id":"b","text":"Escherichia coli"},{"id":"c","text":"Klebsiella pneumoniae"},{"id":"d","text":"Enterococcus faecalis"}],"answerId":"b","explanation":"Escherichia coli is the most common uropathogen responsible for acute pyelonephritis.","kind":"recall","origin":"ai"},{"id":"acute-pyelonephritis-clinical~ai-1","moduleId":"acute-pyelonephritis-clinical","stem":"Which laboratory finding is most indicative of acute pyelonephritis?","options":[{"id":"a","text":"Hematuria"},{"id":"b","text":"White-cell casts"},{"id":"c","text":"Proteinuria"},{"id":"d","text":"Glucosuria"}],"answerId":"b","explanation":"White-cell casts in the urine localize the infection to the renal parenchyma, indicating acute pyelonephritis.","kind":"recall","origin":"ai"},{"id":"acute-pyelonephritis-clinical~ai-2","moduleId":"acute-pyelonephritis-clinical","stem":"A patient presents with fever, flank pain, and costovertebral angle tenderness. What is the most appropriate next step in management if they are septic?","options":[{"id":"a","text":"Start oral antibiotics"},{"id":"b","text":"Obtain urine culture"},{"id":"c","text":"Initiate IV fluids and antibiotics"},{"id":"d","text":"Schedule for imaging immediately"}],"answerId":"c","explanation":"In a septic patient, initiating IV fluids and antibiotics is critical for managing acute pyelonephritis.","kind":"clinical","origin":"ai"},{"id":"acute-pyelonephritis-clinical~ai-3","moduleId":"acute-pyelonephritis-clinical","stem":"What complication should be suspected if a patient with acute pyelonephritis has persistent fever after 72 hours of appropriate antibiotics?","options":[{"id":"a","text":"Renal stone"},{"id":"b","text":"Urinary retention"},{"id":"c","text":"Renal abscess"},{"id":"d","text":"Acute cystitis"}],"answerId":"c","explanation":"Persistent fever after 72 hours of appropriate antibiotics suggests a renal abscess or obstruction that requires imaging.","kind":"clinical","origin":"ai"},{"id":"acute-pyelonephritis-clinical~ai-4","moduleId":"acute-pyelonephritis-clinical","stem":"In a patient with acute pyelonephritis, which of the following conditions would classify the infection as 'complicated'?","options":[{"id":"a","text":"Uncomplicated cystitis"},{"id":"b","text":"Pregnancy"},{"id":"c","text":"Mild dehydration"},{"id":"d","text":"Recent antibiotic use"}],"answerId":"b","explanation":"Pregnancy is considered a risk factor that complicates urinary tract infections, requiring longer therapy and management of the underlying condition.","kind":"trap","origin":"ai"},{"id":"acute-pyelonephritis-clinical~ai-5","moduleId":"acute-pyelonephritis-clinical","stem":"Which imaging study is most appropriate for a patient with acute pyelonephritis who is not improving after 48 hours of treatment?","options":[{"id":"a","text":"X-ray of the abdomen"},{"id":"b","text":"Ultrasound of the kidneys"},{"id":"c","text":"CT scan of the abdomen"},{"id":"d","text":"MRI of the abdomen"}],"answerId":"c","explanation":"A CT scan of the abdomen is the most appropriate imaging study to evaluate for complications such as abscess or obstruction.","kind":"clinical","origin":"ai"},{"id":"acute-pyelonephritis-clinical~ai-6","moduleId":"acute-pyelonephritis-clinical","stem":"How does the pathogenesis of acute pyelonephritis relate to the microbiological aspects of UTIs?","options":[{"id":"a","text":"It is caused by viral infections"},{"id":"b","text":"It results from ascending bacterial infections"},{"id":"c","text":"It is due to fungal infections"},{"id":"d","text":"It is primarily an autoimmune condition"}],"answerId":"b","explanation":"Acute pyelonephritis is primarily caused by ascending bacterial infections from the lower urinary tract, particularly by uropathogenic E. coli.","kind":"integration","linkedModuleIds":["uti-pathogenesis-microbiology"],"origin":"ai"},{"id":"acute-pyelonephritis-clinical~ai-7","moduleId":"acute-pyelonephritis-clinical","stem":"What is the relationship between obstructive uropathy and acute pyelonephritis?","options":[{"id":"a","text":"Obstructive uropathy is a benign condition"},{"id":"b","text":"Obstructive uropathy can lead to acute pyelonephritis"},{"id":"c","text":"Acute pyelonephritis prevents obstructive uropathy"},{"id":"d","text":"Obstructive uropathy is unrelated to UTIs"}],"answerId":"b","explanation":"Obstructive uropathy can lead to acute pyelonephritis by causing urinary stasis and increasing the risk of infection.","kind":"integration","linkedModuleIds":["obstructive-uropathy-hydronephrosis"],"origin":"ai"}],"urine-microscopy-casts-crystals":[{"id":"urine-microscopy-casts-crystals~ai-0","moduleId":"urine-microscopy-casts-crystals","stem":"What type of casts would you expect to find in a patient with glomerulonephritis?","options":[{"id":"a","text":"Red-cell casts"},{"id":"b","text":"White-cell casts"},{"id":"c","text":"Muddy-brown casts"},{"id":"d","text":"Fatty casts"}],"answerId":"a","explanation":"Red-cell casts indicate glomerular bleeding, which is characteristic of glomerulonephritis.","kind":"recall","origin":"ai"},{"id":"urine-microscopy-casts-crystals~ai-1","moduleId":"urine-microscopy-casts-crystals","stem":"Which crystal is associated with alkaline urine and urease-producing bacteria?","options":[{"id":"a","text":"Calcium oxalate"},{"id":"b","text":"Uric acid"},{"id":"c","text":"Struvite"},{"id":"d","text":"Cystine"}],"answerId":"c","explanation":"Struvite crystals, often described as 'coffin-lid' shaped, form in alkaline urine due to urease-producing bacteria.","kind":"recall","origin":"ai"},{"id":"urine-microscopy-casts-crystals~ai-2","moduleId":"urine-microscopy-casts-crystals","stem":"A patient presents with acute kidney injury and muddy-brown granular casts on microscopy. What is the most likely diagnosis?","options":[{"id":"a","text":"Acute glomerulonephritis"},{"id":"b","text":"Acute tubular necrosis"},{"id":"c","text":"Chronic kidney disease"},{"id":"d","text":"Interstitial nephritis"}],"answerId":"b","explanation":"Muddy-brown granular casts are indicative of acute tubular necrosis, especially in the context of acute kidney injury.","kind":"clinical","origin":"ai"},{"id":"urine-microscopy-casts-crystals~ai-3","moduleId":"urine-microscopy-casts-crystals","stem":"What is the significance of dysmorphic red blood cells in urine microscopy?","options":[{"id":"a","text":"Indicate lower urinary tract bleeding"},{"id":"b","text":"Suggest glomerular bleeding"},{"id":"c","text":"Point to acute tubular necrosis"},{"id":"d","text":"Indicate nephrotic syndrome"}],"answerId":"b","explanation":"Dysmorphic red blood cells suggest glomerular bleeding, which can help localize the source of hematuria.","kind":"trap","origin":"ai"},{"id":"urine-microscopy-casts-crystals~ai-4","moduleId":"urine-microscopy-casts-crystals","stem":"In a patient with nephrotic syndrome, which finding is expected on urine microscopy?","options":[{"id":"a","text":"Muddy-brown casts"},{"id":"b","text":"Fatty casts"},{"id":"c","text":"White-cell casts"},{"id":"d","text":"Broad waxy casts"}],"answerId":"b","explanation":"Fatty casts, often with oval fat bodies, are characteristic of nephrotic syndrome due to lipiduria.","kind":"recall","origin":"ai"},{"id":"urine-microscopy-casts-crystals~ai-5","moduleId":"urine-microscopy-casts-crystals","stem":"Which urine finding would most likely support a diagnosis of pyelonephritis?","options":[{"id":"a","text":"Red-cell casts"},{"id":"b","text":"White-cell casts"},{"id":"c","text":"Muddy-brown casts"},{"id":"d","text":"Fatty casts"}],"answerId":"b","explanation":"White-cell casts are indicative of pyelonephritis or acute interstitial nephritis.","kind":"clinical","origin":"ai"},{"id":"urine-microscopy-casts-crystals~ai-6","moduleId":"urine-microscopy-casts-crystals","stem":"How does the presence of red-cell casts change the interpretation of hematuria?","options":[{"id":"a","text":"Indicates a urological source"},{"id":"b","text":"Localizes to the kidney"},{"id":"c","text":"Suggests a benign process"},{"id":"d","text":"Indicates a need for imaging only"}],"answerId":"b","explanation":"Red-cell casts localize hematuria to the kidney, indicating a glomerular source rather than a urological one.","kind":"trap","origin":"ai"},{"id":"urine-microscopy-casts-crystals~ai-7","moduleId":"urine-microscopy-casts-crystals","stem":"A patient with acute kidney injury has muddy-brown casts and elevated creatinine. Which linked module's concepts are most relevant for further management?","options":[{"id":"a","text":"Urine Dipstick Chemistry"},{"id":"b","text":"AKI: Prerenal, Intrinsic & Postrenal"},{"id":"c","text":"Urinalysis II: Microscopy of the Urine Sediment"},{"id":"d","text":"Introduction to Glomerular Disease"}],"answerId":"b","explanation":"The concepts from the AKI module are crucial for understanding the underlying causes and management of acute kidney injury.","kind":"integration","linkedModuleIds":["aki-prerenal-intrinsic-postrenal"],"origin":"ai"},{"id":"urine-microscopy-casts-crystals~ai-8","moduleId":"urine-microscopy-casts-crystals","stem":"In evaluating a patient with suspected glomerular disease, which urine finding would provide the most direct evidence?","options":[{"id":"a","text":"Muddy-brown casts"},{"id":"b","text":"Red-cell casts"},{"id":"c","text":"Struvite crystals"},{"id":"d","text":"Fatty casts"}],"answerId":"b","explanation":"Red-cell casts provide direct evidence of glomerular disease, particularly glomerulonephritis.","kind":"integration","linkedModuleIds":["glomerular-disease-overview"],"origin":"ai"}],"blood-gas-anion-gap":[{"id":"blood-gas-anion-gap~ai-0","moduleId":"blood-gas-anion-gap","stem":"What is the primary disorder in a patient with pH 7.20, HCO₃⁻ 10, and low CO₂?","options":[{"id":"a","text":"Respiratory acidosis"},{"id":"b","text":"Metabolic acidosis"},{"id":"c","text":"Respiratory alkalosis"},{"id":"d","text":"Metabolic alkalosis"}],"answerId":"b","explanation":"The low pH and low bicarbonate indicate a primary metabolic acidosis, with appropriate respiratory compensation shown by low CO₂.","kind":"clinical","origin":"ai"},{"id":"blood-gas-anion-gap~ai-1","moduleId":"blood-gas-anion-gap","stem":"In metabolic acidosis, what does a high anion gap indicate?","options":[{"id":"a","text":"Bicarbonate loss"},{"id":"b","text":"Added acid"},{"id":"c","text":"Respiratory compensation"},{"id":"d","text":"Normal physiology"}],"answerId":"b","explanation":"A high anion gap in metabolic acidosis suggests the presence of added acids, commonly summarized by the MUDPILES mnemonic.","kind":"recall","origin":"ai"},{"id":"blood-gas-anion-gap~ai-2","moduleId":"blood-gas-anion-gap","stem":"A patient presents with pH 7.28 and high CO₂. What is the most likely diagnosis?","options":[{"id":"a","text":"Metabolic acidosis"},{"id":"b","text":"Respiratory acidosis"},{"id":"c","text":"Metabolic alkalosis"},{"id":"d","text":"Respiratory alkalosis"}],"answerId":"b","explanation":"The low pH with elevated CO₂ indicates respiratory acidosis, likely due to hypoventilation.","kind":"clinical","origin":"ai"},{"id":"blood-gas-anion-gap~ai-3","moduleId":"blood-gas-anion-gap","stem":"What is the first step in interpreting an arterial blood gas?","options":[{"id":"a","text":"Assess compensation"},{"id":"b","text":"Calculate the anion gap"},{"id":"c","text":"Determine pH status"},{"id":"d","text":"Identify oxygenation type"}],"answerId":"c","explanation":"The first step in blood gas interpretation is to assess the pH to determine if the patient is acidemic or alkalemic.","kind":"recall","origin":"ai"},{"id":"blood-gas-anion-gap~ai-4","moduleId":"blood-gas-anion-gap","stem":"In a patient with high anion gap metabolic acidosis, what does a mismatch in the delta-delta calculation suggest?","options":[{"id":"a","text":"Normal physiology"},{"id":"b","text":"Concurrent normal-gap acidosis"},{"id":"c","text":"Respiratory compensation"},{"id":"d","text":"Metabolic alkalosis"}],"answerId":"b","explanation":"A mismatch in the delta-delta calculation indicates the presence of a concurrent normal-gap acidosis or metabolic alkalosis.","kind":"clinical","origin":"ai"},{"id":"blood-gas-anion-gap~ai-5","moduleId":"blood-gas-anion-gap","stem":"How does the compensation mechanism work in metabolic acidosis?","options":[{"id":"a","text":"Increased HCO₃⁻ production"},{"id":"b","text":"Increased CO₂ retention"},{"id":"c","text":"Decreased CO₂ from hyperventilation"},{"id":"d","text":"Decreased HCO₃⁻ loss"}],"answerId":"c","explanation":"In metabolic acidosis, the body compensates by decreasing CO₂ through hyperventilation to help raise the pH.","kind":"mechanism","origin":"ai"},{"id":"blood-gas-anion-gap~ai-6","moduleId":"blood-gas-anion-gap","stem":"A patient with high anion gap metabolic acidosis presents with elevated lactate. What is the likely underlying cause?","options":[{"id":"a","text":"Respiratory failure"},{"id":"b","text":"Renal failure"},{"id":"c","text":"Tissue hypoperfusion"},{"id":"d","text":"Diarrhea"}],"answerId":"c","explanation":"Elevated lactate in the context of high anion gap metabolic acidosis indicates tissue hypoperfusion, leading to lactic acidosis.","kind":"clinical","origin":"ai"},{"id":"blood-gas-anion-gap~ai-7","moduleId":"blood-gas-anion-gap","stem":"How does metabolic acidosis relate to acid-base disorders?","options":[{"id":"a","text":"It is always compensated by respiratory alkalosis"},{"id":"b","text":"It can be caused by renal failure"},{"id":"c","text":"It is independent of anion gap calculations"},{"id":"d","text":"It is always associated with high CO₂"}],"answerId":"b","explanation":"Metabolic acidosis can be caused by renal failure, among other causes, and is assessed through anion gap calculations.","kind":"integration","linkedModuleIds":["acid-base-disorders"],"origin":"ai"},{"id":"blood-gas-anion-gap~ai-8","moduleId":"blood-gas-anion-gap","stem":"Which of the following findings would indicate type 2 respiratory failure?","options":[{"id":"a","text":"Normal CO₂ with hypoxemia"},{"id":"b","text":"High CO₂ with hypoxemia"},{"id":"c","text":"Low pH with high HCO₃⁻"},{"id":"d","text":"High pH with low CO₂"}],"answerId":"b","explanation":"Type 2 respiratory failure is characterized by hypoxemia with elevated CO₂ due to hypoventilation.","kind":"integration","linkedModuleIds":["abg-acid-base-interpretation"],"origin":"ai"}],"catheter-associated-uti":[{"id":"catheter-associated-uti~ai-0","moduleId":"catheter-associated-uti","stem":"What is the primary reason that indwelling urinary catheters lead to catheter-associated urinary tract infections (CAUTIs)?","options":[{"id":"a","text":"They are inserted without sterile technique"},{"id":"b","text":"They bypass host defenses and promote biofilm formation"},{"id":"c","text":"They are always contaminated during insertion"},{"id":"d","text":"They are left in place for too short a duration"}],"answerId":"b","explanation":"Indwelling catheters bypass the urethral barrier and promote biofilm formation, leading to a high risk of infection.","kind":"mechanism","origin":"ai"},{"id":"catheter-associated-uti~ai-1","moduleId":"catheter-associated-uti","stem":"Which organism is most commonly associated with struvite encrustation in catheterized patients?","options":[{"id":"a","text":"Escherichia coli"},{"id":"b","text":"Klebsiella pneumoniae"},{"id":"c","text":"Proteus mirabilis"},{"id":"d","text":"Pseudomonas aeruginosa"}],"answerId":"c","explanation":"Proteus mirabilis produces urease, which increases urine alkalinity and promotes struvite crystal formation.","kind":"recall","origin":"ai"},{"id":"catheter-associated-uti~ai-2","moduleId":"catheter-associated-uti","stem":"In a catheterized patient, which finding indicates symptomatic CAUTI requiring treatment?","options":[{"id":"a","text":"Positive urine culture without symptoms"},{"id":"b","text":"Fever and flank pain"},{"id":"c","text":"Asymptomatic bacteriuria"},{"id":"d","text":"New onset confusion without fever"}],"answerId":"b","explanation":"Fever and flank pain in a catheterized patient indicate symptomatic CAUTI that requires catheter change and treatment.","kind":"clinical","origin":"ai"},{"id":"catheter-associated-uti~ai-3","moduleId":"catheter-associated-uti","stem":"What is the recommended management for asymptomatic bacteriuria in a catheterized patient?","options":[{"id":"a","text":"Start broad-spectrum antibiotics"},{"id":"b","text":"Change the catheter and observe"},{"id":"c","text":"Treat only if symptoms develop"},{"id":"d","text":"Perform a urine culture"}],"answerId":"c","explanation":"Asymptomatic bacteriuria in catheterized patients should not be treated with antibiotics unless there are symptoms.","kind":"trap","origin":"ai"},{"id":"catheter-associated-uti~ai-4","moduleId":"catheter-associated-uti","stem":"Which of the following is a key preventive measure for catheter-associated urinary tract infections?","options":[{"id":"a","text":"Prolonged catheterization"},{"id":"b","text":"Routine antibiotic prophylaxis"},{"id":"c","text":"Aseptic insertion and early removal"},{"id":"d","text":"Frequent catheter exchanges"}],"answerId":"c","explanation":"Aseptic insertion and early removal of catheters are crucial in preventing CAUTIs.","kind":"recall","origin":"ai"},{"id":"catheter-associated-uti~ai-5","moduleId":"catheter-associated-uti","stem":"How does biofilm formation on catheters contribute to persistent infections?","options":[{"id":"a","text":"It enhances the immune response"},{"id":"b","text":"It protects bacteria from antibiotics and host defenses"},{"id":"c","text":"It prevents urine stasis"},{"id":"d","text":"It promotes rapid bacterial growth"}],"answerId":"b","explanation":"Biofilm protects bacteria from antibiotics and host defenses, allowing infections to persist until the catheter is removed.","kind":"mechanism","origin":"ai"},{"id":"catheter-associated-uti~ai-6","moduleId":"catheter-associated-uti","stem":"How is the pathogenesis of CAUTI linked to the host defenses of the urinary tract?","options":[{"id":"a","text":"Catheters enhance host defenses"},{"id":"b","text":"Host defenses are bypassed by catheters"},{"id":"c","text":"Host defenses are irrelevant in CAUTI"},{"id":"d","text":"Host defenses prevent catheter insertion"}],"answerId":"b","explanation":"Catheters bypass the natural host defenses of the urinary tract, leading to increased risk of infection.","kind":"integration","linkedModuleIds":["urinary-tract-host-defenses"],"origin":"ai"},{"id":"catheter-associated-uti~ai-7","moduleId":"catheter-associated-uti","stem":"Which factor is most relevant when considering the management of CAUTI in relation to its microbiological pathogenesis?","options":[{"id":"a","text":"Biofilm formation on catheters"},{"id":"b","text":"Antibiotic resistance patterns"},{"id":"c","text":"Host immune response"},{"id":"d","text":"Urethral flora"}],"answerId":"a","explanation":"Biofilm formation on catheters is central to the microbiological pathogenesis of CAUTI, as it protects bacteria from treatment.","kind":"integration","linkedModuleIds":["uti-pathogenesis-microbiology"],"origin":"ai"}],"acid-base-disorders":[{"id":"acid-base-disorders~ai-0","moduleId":"acid-base-disorders","stem":"What is the primary disturbance in a patient with low pH, low HCO₃⁻, and high anion gap?","options":[{"id":"a","text":"Metabolic acidosis"},{"id":"b","text":"Metabolic alkalosis"},{"id":"c","text":"Respiratory acidosis"},{"id":"d","text":"Respiratory alkalosis"}],"answerId":"a","explanation":"This presentation indicates a high-anion-gap metabolic acidosis, commonly seen in conditions like diabetic ketoacidosis.","kind":"recall","origin":"ai"},{"id":"acid-base-disorders~ai-1","moduleId":"acid-base-disorders","stem":"Which condition is most likely to cause metabolic alkalosis?","options":[{"id":"a","text":"Diarrhea"},{"id":"b","text":"Prolonged vomiting"},{"id":"c","text":"Diabetic ketoacidosis"},{"id":"d","text":"Acute renal failure"}],"answerId":"b","explanation":"Prolonged vomiting leads to loss of gastric acid, resulting in metabolic alkalosis.","kind":"recall","origin":"ai"},{"id":"acid-base-disorders~ai-2","moduleId":"acid-base-disorders","stem":"In respiratory acidosis, which of the following compensatory mechanisms occurs?","options":[{"id":"a","text":"Increased renal HCO₃⁻ reabsorption"},{"id":"b","text":"Decreased renal HCO₃⁻ reabsorption"},{"id":"c","text":"Increased respiratory rate"},{"id":"d","text":"Decreased CO₂ production"}],"answerId":"a","explanation":"The kidneys compensate for respiratory acidosis by increasing HCO₃⁻ reabsorption to counteract the acidosis.","kind":"mechanism","origin":"ai"},{"id":"acid-base-disorders~ai-3","moduleId":"acid-base-disorders","stem":"A patient presents with a pH of 7.35, HCO₃⁻ of 15 mEq/L, and a pCO₂ of 45 mmHg. What does this indicate?","options":[{"id":"a","text":"Metabolic acidosis with appropriate compensation"},{"id":"b","text":"Metabolic acidosis with mixed disorder"},{"id":"c","text":"Respiratory acidosis with metabolic compensation"},{"id":"d","text":"Respiratory alkalosis"}],"answerId":"a","explanation":"The low pH and low HCO₃⁻ indicate metabolic acidosis, and the pCO₂ is within the expected range for compensation.","kind":"clinical","origin":"ai"},{"id":"acid-base-disorders~ai-4","moduleId":"acid-base-disorders","stem":"A patient with chronic obstructive pulmonary disease (COPD) presents with confusion and lethargy. Arterial blood gas analysis shows low pH and high pCO₂. What is the primary disorder?","options":[{"id":"a","text":"Metabolic acidosis"},{"id":"b","text":"Respiratory acidosis"},{"id":"c","text":"Metabolic alkalosis"},{"id":"d","text":"Respiratory alkalosis"}],"answerId":"b","explanation":"The low pH and high pCO₂ indicate respiratory acidosis due to hypoventilation.","kind":"clinical","origin":"ai"},{"id":"acid-base-disorders~ai-5","moduleId":"acid-base-disorders","stem":"A patient has a pH of 7.38, HCO₃⁻ of 18 mEq/L, and a pCO₂ of 30 mmHg. What does this suggest?","options":[{"id":"a","text":"Metabolic acidosis with respiratory compensation"},{"id":"b","text":"Respiratory acidosis"},{"id":"c","text":"Metabolic alkalosis"},{"id":"d","text":"Normal acid-base status"}],"answerId":"a","explanation":"The low HCO₃⁻ and compensatory low pCO₂ suggest metabolic acidosis with respiratory compensation.","kind":"clinical","origin":"ai"},{"id":"acid-base-disorders~ai-6","moduleId":"acid-base-disorders","stem":"How does metabolic acidosis affect the expected pCO₂ according to Winter's formula?","options":[{"id":"a","text":"pCO₂ decreases by 1.5×HCO₃⁻"},{"id":"b","text":"pCO₂ increases by 1.5×HCO₃⁻"},{"id":"c","text":"pCO₂ remains unchanged"},{"id":"d","text":"pCO₂ decreases by HCO₃⁻"}],"answerId":"a","explanation":"According to Winter's formula, the expected pCO₂ decreases in metabolic acidosis as the body compensates.","kind":"mechanism","origin":"ai"},{"id":"acid-base-disorders~ai-7","moduleId":"acid-base-disorders","stem":"A patient presents with a pH of 7.40, HCO₃⁻ of 22 mEq/L, and pCO₂ of 50 mmHg. What does this indicate?","options":[{"id":"a","text":"Normal acid-base status"},{"id":"b","text":"Respiratory acidosis with compensation"},{"id":"c","text":"Metabolic acidosis"},{"id":"d","text":"Metabolic alkalosis"}],"answerId":"b","explanation":"The pH is normal, but the elevated pCO₂ indicates respiratory acidosis with renal compensation.","kind":"integration","linkedModuleIds":["abg-acid-base-interpretation"],"origin":"ai"},{"id":"acid-base-disorders~ai-8","moduleId":"acid-base-disorders","stem":"In a patient with high anion gap metabolic acidosis, which of the following conditions could be the cause?","options":[{"id":"a","text":"Diarrhea"},{"id":"b","text":"Diabetic ketoacidosis"},{"id":"c","text":"Vomiting"},{"id":"d","text":"Renal tubular acidosis"}],"answerId":"b","explanation":"Diabetic ketoacidosis is a classic example of high anion gap metabolic acidosis due to the accumulation of ketoacids.","kind":"integration","linkedModuleIds":["high-anion-gap-metabolic-acidosis"],"origin":"ai"}],"urinary-incontinence-drugs":[{"id":"urinary-incontinence-drugs~ai-0","moduleId":"urinary-incontinence-drugs","stem":"Which medication is primarily used to treat urge incontinence by relaxing the detrusor muscle?","options":[{"id":"a","text":"Oxybutynin"},{"id":"b","text":"Tamsulosin"},{"id":"c","text":"Finasteride"},{"id":"d","text":"Desmopressin"}],"answerId":"a","explanation":"Oxybutynin is an antimuscarinic that relaxes the detrusor muscle, making it effective for treating urge incontinence.","kind":"recall","origin":"ai"},{"id":"urinary-incontinence-drugs~ai-1","moduleId":"urinary-incontinence-drugs","stem":"What is the mechanism of action of mirabegron in the treatment of overactive bladder?","options":[{"id":"a","text":"M3 receptor antagonism"},{"id":"b","text":"β3 receptor agonism"},{"id":"c","text":"α1 receptor antagonism"},{"id":"d","text":"5α-reductase inhibition"}],"answerId":"b","explanation":"Mirabegron acts as a β3 receptor agonist, which relaxes the detrusor muscle and increases bladder capacity.","kind":"mechanism","origin":"ai"},{"id":"urinary-incontinence-drugs~ai-2","moduleId":"urinary-incontinence-drugs","stem":"A 70-year-old man presents with urinary retention after starting a new medication for his overactive bladder. Which class of drugs is most likely responsible?","options":[{"id":"a","text":"Antimuscarinics"},{"id":"b","text":"α1-blockers"},{"id":"c","text":"β3 agonists"},{"id":"d","text":"5α-reductase inhibitors"}],"answerId":"a","explanation":"Antimuscarinics can impair bladder emptying, leading to urinary retention, especially in older patients.","kind":"trap","origin":"ai"},{"id":"urinary-incontinence-drugs~ai-3","moduleId":"urinary-incontinence-drugs","stem":"Which finding is most indicative of benign prostatic hyperplasia (BPH) in a male patient?","options":[{"id":"a","text":"Urgency and frequency"},{"id":"b","text":"Postural hypotension"},{"id":"c","text":"Prostate shrinkage"},{"id":"d","text":"Weak urinary stream"}],"answerId":"d","explanation":"A weak urinary stream is a classic symptom of BPH due to obstruction of urine flow.","kind":"recall","origin":"ai"},{"id":"urinary-incontinence-drugs~ai-4","moduleId":"urinary-incontinence-drugs","stem":"What is the primary treatment for nocturnal enuresis in children?","options":[{"id":"a","text":"Antimuscarinics"},{"id":"b","text":"Desmopressin"},{"id":"c","text":"α1-blockers"},{"id":"d","text":"5α-reductase inhibitors"}],"answerId":"b","explanation":"Desmopressin is used to reduce overnight urine production in children with nocturnal enuresis.","kind":"recall","origin":"ai"},{"id":"urinary-incontinence-drugs~ai-5","moduleId":"urinary-incontinence-drugs","stem":"Which drug class should be avoided in patients with narrow-angle glaucoma?","options":[{"id":"a","text":"Antimuscarinics"},{"id":"b","text":"β3 agonists"},{"id":"c","text":"α1-blockers"},{"id":"d","text":"5α-reductase inhibitors"}],"answerId":"a","explanation":"Antimuscarinics can increase intraocular pressure and should be avoided in narrow-angle glaucoma patients.","kind":"trap","origin":"ai"},{"id":"urinary-incontinence-drugs~ai-6","moduleId":"urinary-incontinence-drugs","stem":"How does the autonomic nervous system regulate bladder function?","options":[{"id":"a","text":"Sympathetic relaxes detrusor, parasympathetic contracts"},{"id":"b","text":"Parasympathetic relaxes detrusor, sympathetic contracts"},{"id":"c","text":"Both systems contract detrusor"},{"id":"d","text":"Both systems relax detrusor"}],"answerId":"a","explanation":"The sympathetic nervous system relaxes the detrusor muscle to store urine, while the parasympathetic system contracts it to void.","kind":"integration","linkedModuleIds":["autonomic-nervous-system"],"origin":"ai"},{"id":"urinary-incontinence-drugs~ai-7","moduleId":"urinary-incontinence-drugs","stem":"Which drug class is primarily used to manage benign prostatic hyperplasia (BPH) symptoms?","options":[{"id":"a","text":"Antimuscarinics"},{"id":"b","text":"β3 agonists"},{"id":"c","text":"α1-blockers"},{"id":"d","text":"Desmopressin"}],"answerId":"c","explanation":"α1-blockers, such as tamsulosin, are used to relieve urinary symptoms associated with BPH by relaxing prostatic and bladder neck smooth muscle.","kind":"integration","linkedModuleIds":["adrenergic-drugs"],"origin":"ai"}],"urine-dipstick-chemistry":[{"id":"urine-dipstick-chemistry~ai-0","moduleId":"urine-dipstick-chemistry","stem":"What does a positive dipstick blood test with no red cells on microscopy indicate?","options":[{"id":"a","text":"Hematuria"},{"id":"b","text":"Hemoglobinuria"},{"id":"c","text":"Myoglobinuria"},{"id":"d","text":"Both Hemoglobinuria and Myoglobinuria"}],"answerId":"d","explanation":"A positive blood pad indicates hemoglobin or myoglobin presence, not necessarily hematuria, especially if microscopy shows no red cells.","kind":"clinical","origin":"ai"},{"id":"urine-dipstick-chemistry~ai-1","moduleId":"urine-dipstick-chemistry","stem":"Which condition is most likely if a urine dipstick shows positive glucose but normal blood glucose levels?","options":[{"id":"a","text":"Diabetes Mellitus"},{"id":"b","text":"Renal Glycosuria"},{"id":"c","text":"Fanconi Syndrome"},{"id":"d","text":"SGLT2 Inhibitor Use"}],"answerId":"d","explanation":"SGLT2 inhibitors lower the renal threshold for glucose, leading to glycosuria despite normal blood glucose levels.","kind":"mechanism","origin":"ai"},{"id":"urine-dipstick-chemistry~ai-2","moduleId":"urine-dipstick-chemistry","stem":"What does a positive leukocyte esterase and nitrite test suggest?","options":[{"id":"a","text":"Urinary Tract Infection"},{"id":"b","text":"Kidney Stones"},{"id":"c","text":"Dehydration"},{"id":"d","text":"Diabetes Mellitus"}],"answerId":"a","explanation":"Positive leukocyte esterase indicates pyuria, and nitrite indicates a nitrate-reducing organism, both supporting a UTI diagnosis.","kind":"clinical","origin":"ai"},{"id":"urine-dipstick-chemistry~ai-3","moduleId":"urine-dipstick-chemistry","stem":"What is the primary limitation of the urine protein dipstick test?","options":[{"id":"a","text":"It cannot detect hematuria"},{"id":"b","text":"It misses light chains in myeloma"},{"id":"c","text":"It is affected by urine pH"},{"id":"d","text":"It is not sensitive to glucose"}],"answerId":"b","explanation":"The protein pad primarily detects albumin and is insensitive to light chains, which can lead to missed diagnoses in myeloma.","kind":"trap","origin":"ai"},{"id":"urine-dipstick-chemistry~ai-4","moduleId":"urine-dipstick-chemistry","stem":"A patient presents with dysuria and a positive leukocyte esterase but negative nitrite test. What is the likely organism?","options":[{"id":"a","text":"E. coli"},{"id":"b","text":"Enterococcus"},{"id":"c","text":"Klebsiella"},{"id":"d","text":"Proteus"}],"answerId":"b","explanation":"Enterococcus does not reduce nitrate, leading to a false-negative nitrite test despite the presence of pyuria indicated by leukocyte esterase.","kind":"clinical","origin":"ai"},{"id":"urine-dipstick-chemistry~ai-5","moduleId":"urine-dipstick-chemistry","stem":"How does the urine dipstick test for blood differ from microscopy findings in rhabdomyolysis?","options":[{"id":"a","text":"Dipstick detects RBCs, microscopy does not"},{"id":"b","text":"Dipstick detects hemoglobin/myoglobin, microscopy detects RBCs"},{"id":"c","text":"Dipstick is always positive, microscopy is not"},{"id":"d","text":"Both tests are equally reliable"}],"answerId":"b","explanation":"The dipstick detects hemoglobin or myoglobin, which can be present without RBCs on microscopy in cases of rhabdomyolysis.","kind":"trap","origin":"ai"},{"id":"urine-dipstick-chemistry~ai-6","moduleId":"urine-dipstick-chemistry","stem":"In a patient with suspected myeloma, what would a normal protein dipstick result indicate?","options":[{"id":"a","text":"Exclusion of myeloma"},{"id":"b","text":"Presence of light chains"},{"id":"c","text":"Need for further testing"},{"id":"d","text":"Acute kidney injury"}],"answerId":"c","explanation":"A normal protein dipstick does not exclude myeloma as it misses light chains; further testing is required.","kind":"integration","linkedModuleIds":["urine-microscopy-casts-crystals"],"origin":"ai"},{"id":"urine-dipstick-chemistry~ai-7","moduleId":"urine-dipstick-chemistry","stem":"Which urine test result would correlate with a positive blood gas finding of metabolic acidosis?","options":[{"id":"a","text":"Positive glucose"},{"id":"b","text":"Positive ketones"},{"id":"c","text":"Positive nitrite"},{"id":"d","text":"Positive leukocyte esterase"}],"answerId":"b","explanation":"Positive ketones in urine indicate ketosis, which can occur in metabolic acidosis, such as in diabetic ketoacidosis.","kind":"integration","linkedModuleIds":["abg-acid-base-interpretation"],"origin":"ai"}],"nephrolithiasis-urolithiasis":[{"id":"nephrolithiasis-urolithiasis~ai-0","moduleId":"nephrolithiasis-urolithiasis","stem":"What is the most common type of urinary stone?","options":[{"id":"a","text":"Calcium oxalate"},{"id":"b","text":"Struvite"},{"id":"c","text":"Uric acid"},{"id":"d","text":"Cystine"}],"answerId":"a","explanation":"Calcium oxalate stones account for approximately 75-80% of urinary stones.","kind":"recall","origin":"ai"},{"id":"nephrolithiasis-urolithiasis~ai-1","moduleId":"nephrolithiasis-urolithiasis","stem":"Which urinary stone is associated with urease-producing organisms?","options":[{"id":"a","text":"Calcium oxalate"},{"id":"b","text":"Struvite"},{"id":"c","text":"Uric acid"},{"id":"d","text":"Cystine"}],"answerId":"b","explanation":"Struvite stones form in alkaline urine due to urease-producing bacteria like Proteus.","kind":"recall","origin":"ai"},{"id":"nephrolithiasis-urolithiasis~ai-2","moduleId":"nephrolithiasis-urolithiasis","stem":"A patient presents with severe colicky loin-to-groin pain and hematuria. What is the most likely diagnosis?","options":[{"id":"a","text":"Ureteric stone"},{"id":"b","text":"Renal tumor"},{"id":"c","text":"Appendicitis"},{"id":"d","text":"Pancreatitis"}],"answerId":"a","explanation":"Severe colicky pain with hematuria is characteristic of a ureteric stone.","kind":"clinical","origin":"ai"},{"id":"nephrolithiasis-urolithiasis~ai-3","moduleId":"nephrolithiasis-urolithiasis","stem":"What is the mechanism by which calcium oxalate stones form?","options":[{"id":"a","text":"Low urine volume"},{"id":"b","text":"High urine pH"},{"id":"c","text":"High citrate levels"},{"id":"d","text":"Low calcium excretion"}],"answerId":"a","explanation":"Calcium oxalate stones form due to supersaturation of urine, often linked to low urine volume.","kind":"mechanism","origin":"ai"},{"id":"nephrolithiasis-urolithiasis~ai-4","moduleId":"nephrolithiasis-urolithiasis","stem":"Which of the following is a urological emergency?","options":[{"id":"a","text":"Calcium oxalate stone"},{"id":"b","text":"Struvite stone with fever"},{"id":"c","text":"Uric acid stone"},{"id":"d","text":"Cystine stone"}],"answerId":"b","explanation":"An obstructed, infected stone with fever requires urgent decompression to prevent complications.","kind":"trap","origin":"ai"},{"id":"nephrolithiasis-urolithiasis~ai-5","moduleId":"nephrolithiasis-urolithiasis","stem":"A patient with gout presents with a radiolucent stone visible on CT. What type of stone is likely present?","options":[{"id":"a","text":"Calcium oxalate"},{"id":"b","text":"Struvite"},{"id":"c","text":"Uric acid"},{"id":"d","text":"Cystine"}],"answerId":"c","explanation":"Uric acid stones are radiolucent and commonly associated with gout.","kind":"clinical","origin":"ai"},{"id":"nephrolithiasis-urolithiasis~ai-6","moduleId":"nephrolithiasis-urolithiasis","stem":"In a patient with recurrent hexagonal crystals in urine, what is the likely underlying condition?","options":[{"id":"a","text":"Cystinuria"},{"id":"b","text":"Hypercalciuria"},{"id":"c","text":"Gout"},{"id":"d","text":"Struvite infection"}],"answerId":"a","explanation":"Hexagonal crystals are characteristic of cystine stones, which occur due to cystinuria.","kind":"recall","origin":"ai"},{"id":"nephrolithiasis-urolithiasis~ai-7","moduleId":"nephrolithiasis-urolithiasis","stem":"How does urine alkalinization help in managing uric acid stones?","options":[{"id":"a","text":"Increases calcium solubility"},{"id":"b","text":"Decreases uric acid concentration"},{"id":"c","text":"Promotes struvite formation"},{"id":"d","text":"Enhances cystine reabsorption"}],"answerId":"b","explanation":"Alkalinization of urine can dissolve uric acid stones by decreasing uric acid concentration.","kind":"mechanism","origin":"ai"},{"id":"nephrolithiasis-urolithiasis~ai-8","moduleId":"nephrolithiasis-urolithiasis","stem":"How does nephrolithiasis relate to obstructive uropathy?","options":[{"id":"a","text":"Both involve renal failure"},{"id":"b","text":"Both can cause hydronephrosis"},{"id":"c","text":"Both are treated with antibiotics"},{"id":"d","text":"Both are caused by infections"}],"answerId":"b","explanation":"Nephrolithiasis can lead to obstruction of the urinary tract, resulting in hydronephrosis.","kind":"integration","linkedModuleIds":["obstructive-uropathy-hydronephrosis"],"origin":"ai"},{"id":"nephrolithiasis-urolithiasis~ai-9","moduleId":"nephrolithiasis-urolithiasis","stem":"Which condition is most likely to present with staghorn calculi?","options":[{"id":"a","text":"Calcium oxalate stones"},{"id":"b","text":"Struvite stones"},{"id":"c","text":"Uric acid stones"},{"id":"d","text":"Cystine stones"}],"answerId":"b","explanation":"Staghorn calculi are typically associated with struvite stones due to infection.","kind":"integration","linkedModuleIds":["urinary-crystals-and-stones"],"origin":"ai"}],"bladder-urothelial-carcinoma":[{"id":"bladder-urothelial-carcinoma~ai-0","moduleId":"bladder-urothelial-carcinoma","stem":"What is the most common type of bladder cancer?","options":[{"id":"a","text":"Squamous cell carcinoma"},{"id":"b","text":"Adenocarcinoma"},{"id":"c","text":"Urothelial carcinoma"},{"id":"d","text":"Small cell carcinoma"}],"answerId":"c","explanation":"Urothelial carcinoma is the most common type of bladder cancer, arising from the urothelium lining the urinary tract.","kind":"recall","origin":"ai"},{"id":"bladder-urothelial-carcinoma~ai-1","moduleId":"bladder-urothelial-carcinoma","stem":"A 65-year-old man presents with painless visible hematuria. What is the most appropriate next step in management?","options":[{"id":"a","text":"Urine culture"},{"id":"b","text":"Cystoscopy"},{"id":"c","text":"CT scan of the abdomen"},{"id":"d","text":"Observation"}],"answerId":"b","explanation":"Painless visible hematuria in an older adult mandates prompt investigation with cystoscopy to rule out bladder cancer.","kind":"clinical","origin":"ai"},{"id":"bladder-urothelial-carcinoma~ai-2","moduleId":"bladder-urothelial-carcinoma","stem":"Which of the following is a significant risk factor for bladder cancer?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Smoking"},{"id":"c","text":"Diabetes"},{"id":"d","text":"Obesity"}],"answerId":"b","explanation":"Smoking is the biggest risk factor for bladder cancer, significantly increasing the likelihood of developing the disease.","kind":"recall","origin":"ai"},{"id":"bladder-urothelial-carcinoma~ai-3","moduleId":"bladder-urothelial-carcinoma","stem":"What mechanism explains the multifocal nature of urothelial carcinoma?","options":[{"id":"a","text":"Genetic mutation"},{"id":"b","text":"Field change phenomenon"},{"id":"c","text":"Viral infection"},{"id":"d","text":"Chronic inflammation"}],"answerId":"b","explanation":"The field change phenomenon explains the multifocal nature of urothelial carcinoma, where carcinogenic exposure affects multiple sites.","kind":"mechanism","origin":"ai"},{"id":"bladder-urothelial-carcinoma~ai-4","moduleId":"bladder-urothelial-carcinoma","stem":"A patient with chronic schistosomiasis presents with bladder cancer. What type of bladder cancer is most likely?","options":[{"id":"a","text":"Urothelial carcinoma"},{"id":"b","text":"Adenocarcinoma"},{"id":"c","text":"Squamous cell carcinoma"},{"id":"d","text":"Transitional cell carcinoma"}],"answerId":"c","explanation":"Chronic irritation from Schistosoma haematobium infection is classically associated with squamous cell carcinoma of the bladder.","kind":"recall","origin":"ai"},{"id":"bladder-urothelial-carcinoma~ai-5","moduleId":"bladder-urothelial-carcinoma","stem":"Which treatment is indicated for muscle-invasive bladder cancer?","options":[{"id":"a","text":"Intravesical BCG therapy"},{"id":"b","text":"Transurethral resection"},{"id":"c","text":"Radical cystectomy"},{"id":"d","text":"Observation"}],"answerId":"c","explanation":"Muscle-invasive bladder cancer requires radical cystectomy, potentially combined with neoadjuvant chemotherapy.","kind":"recall","origin":"ai"},{"id":"bladder-urothelial-carcinoma~ai-6","moduleId":"bladder-urothelial-carcinoma","stem":"How does bladder cancer differ from renal cell carcinoma in terms of presentation?","options":[{"id":"a","text":"Bladder cancer presents with flank pain"},{"id":"b","text":"Bladder cancer is multifocal"},{"id":"c","text":"Bladder cancer is associated with paraneoplastic syndromes"},{"id":"d","text":"Bladder cancer has a higher incidence in women"}],"answerId":"b","explanation":"Bladder cancer is typically multifocal, while renal cell carcinoma is more often a solitary mass.","kind":"integration","linkedModuleIds":["renal-cell-carcinoma"],"origin":"ai"},{"id":"bladder-urothelial-carcinoma~ai-7","moduleId":"bladder-urothelial-carcinoma","stem":"What is the primary imaging modality used to evaluate the upper urinary tract in patients with hematuria?","options":[{"id":"a","text":"Ultrasound"},{"id":"b","text":"CT urogram"},{"id":"c","text":"MRI"},{"id":"d","text":"X-ray"}],"answerId":"b","explanation":"CT urogram is the gold standard imaging modality to evaluate the upper urinary tract for synchronous urothelial tumors.","kind":"integration","linkedModuleIds":["urinary-system-neoplasms"],"origin":"ai"}],"acute-interstitial-nephritis":[{"id":"acute-interstitial-nephritis~ai-0","moduleId":"acute-interstitial-nephritis","stem":"What is the most common cause of acute interstitial nephritis (AIN)?","options":[{"id":"a","text":"Autoimmune disease"},{"id":"b","text":"Infections"},{"id":"c","text":"Drug-induced hypersensitivity"},{"id":"d","text":"Vascular disorders"}],"answerId":"c","explanation":"Most cases of AIN are drug-induced, particularly from antibiotics, NSAIDs, and proton-pump inhibitors.","kind":"recall","origin":"ai"},{"id":"acute-interstitial-nephritis~ai-1","moduleId":"acute-interstitial-nephritis","stem":"Which laboratory finding is most characteristic of acute interstitial nephritis?","options":[{"id":"a","text":"Hematuria"},{"id":"b","text":"Eosinophiluria"},{"id":"c","text":"Hyperkalemia"},{"id":"d","text":"Hypocalcemia"}],"answerId":"b","explanation":"Eosinophiluria is a classic finding in acute interstitial nephritis, indicating an allergic response.","kind":"recall","origin":"ai"},{"id":"acute-interstitial-nephritis~ai-2","moduleId":"acute-interstitial-nephritis","stem":"A patient develops acute kidney injury (AKI) 10 days after starting a new antibiotic. Which finding is most likely on urinalysis?","options":[{"id":"a","text":"Muddy-brown casts"},{"id":"b","text":"Red blood cell casts"},{"id":"c","text":"White cell casts"},{"id":"d","text":"Crystals"}],"answerId":"c","explanation":"White cell casts are indicative of interstitial inflammation, which is characteristic of acute interstitial nephritis.","kind":"clinical","origin":"ai"},{"id":"acute-interstitial-nephritis~ai-3","moduleId":"acute-interstitial-nephritis","stem":"What is the primary treatment for acute interstitial nephritis caused by drug hypersensitivity?","options":[{"id":"a","text":"Corticosteroids"},{"id":"b","text":"Renal replacement therapy"},{"id":"c","text":"Stop the offending drug"},{"id":"d","text":"Fluid resuscitation"}],"answerId":"c","explanation":"The cornerstone of treatment for AIN is to promptly stop the offending drug to prevent further kidney damage.","kind":"recall","origin":"ai"},{"id":"acute-interstitial-nephritis~ai-4","moduleId":"acute-interstitial-nephritis","stem":"In a patient with acute interstitial nephritis, which of the following findings would most likely be absent?","options":[{"id":"a","text":"Eosinophilia"},{"id":"b","text":"Sterile pyuria"},{"id":"c","text":"White cell casts"},{"id":"d","text":"Hematuria"}],"answerId":"d","explanation":"Hematuria is not a typical finding in acute interstitial nephritis, which usually presents with sterile pyuria and white cell casts.","kind":"trap","origin":"ai"},{"id":"acute-interstitial-nephritis~ai-5","moduleId":"acute-interstitial-nephritis","stem":"How does acute interstitial nephritis differ from acute tubular necrosis (ATN)?","options":[{"id":"a","text":"Presence of hematuria"},{"id":"b","text":"Eosinophiluria vs. muddy-brown casts"},{"id":"c","text":"Rapid onset vs. gradual onset"},{"id":"d","text":"Only drug-induced causes"}],"answerId":"b","explanation":"AIN is characterized by eosinophiluria and white cell casts, while ATN typically presents with muddy-brown casts.","kind":"mechanism","origin":"ai"},{"id":"acute-interstitial-nephritis~ai-6","moduleId":"acute-interstitial-nephritis","stem":"A patient with acute interstitial nephritis presents with a rash and fever. Which linked condition should be considered for potential overlap?","options":[{"id":"a","text":"Neonatal skin conditions"},{"id":"b","text":"Drug hypersensitivity reactions"},{"id":"c","text":"Obstructive uropathy"},{"id":"d","text":"Chronic kidney disease"}],"answerId":"b","explanation":"Drug hypersensitivity reactions can present with similar symptoms, including rash and fever, and are relevant to AIN.","kind":"integration","linkedModuleIds":["drug-hypersensitivity-scars"],"origin":"ai"},{"id":"acute-interstitial-nephritis~ai-7","moduleId":"acute-interstitial-nephritis","stem":"In a patient with acute interstitial nephritis, what is the most likely subsequent complication if the offending drug is not discontinued?","options":[{"id":"a","text":"Chronic interstitial fibrosis"},{"id":"b","text":"Acute tubular necrosis"},{"id":"c","text":"Nephrolithiasis"},{"id":"d","text":"Glomerulosclerosis"}],"answerId":"a","explanation":"Failure to stop the offending drug can lead to chronic interstitial fibrosis and chronic kidney disease.","kind":"integration","linkedModuleIds":["aki-prerenal-intrinsic-postrenal"],"origin":"ai"}],"obstructive-uropathy-hydronephrosis":[{"id":"obstructive-uropathy-hydronephrosis~ai-0","moduleId":"obstructive-uropathy-hydronephrosis","stem":"What is the primary mechanism by which obstructive uropathy leads to postrenal acute kidney injury (AKI)?","options":[{"id":"a","text":"Increased urine production"},{"id":"b","text":"Back-pressure causing hydronephrosis"},{"id":"c","text":"Decreased renal blood flow"},{"id":"d","text":"Direct nephron damage"}],"answerId":"b","explanation":"Obstruction leads to back-pressure which causes hydronephrosis, resulting in postrenal AKI if bilateral or if a single kidney is obstructed.","kind":"mechanism","origin":"ai"},{"id":"obstructive-uropathy-hydronephrosis~ai-1","moduleId":"obstructive-uropathy-hydronephrosis","stem":"Which imaging modality is first-line for diagnosing hydronephrosis?","options":[{"id":"a","text":"CT scan"},{"id":"b","text":"MRI"},{"id":"c","text":"X-ray"},{"id":"d","text":"Ultrasound"}],"answerId":"d","explanation":"Ultrasound is the first-line imaging modality for diagnosing hydronephrosis due to its ability to visualize dilated renal pelvis and calyces.","kind":"recall","origin":"ai"},{"id":"obstructive-uropathy-hydronephrosis~ai-2","moduleId":"obstructive-uropathy-hydronephrosis","stem":"A 65-year-old man with benign prostatic hyperplasia (BPH) presents with rising creatinine and a palpable bladder. What is the most likely diagnosis?","options":[{"id":"a","text":"Unilateral obstructing stone"},{"id":"b","text":"Bladder outlet obstruction"},{"id":"c","text":"Acute kidney injury from dehydration"},{"id":"d","text":"Acute interstitial nephritis"}],"answerId":"b","explanation":"The combination of rising creatinine and a palpable bladder indicates bladder outlet obstruction due to BPH, leading to postrenal AKI.","kind":"clinical","origin":"ai"},{"id":"obstructive-uropathy-hydronephrosis~ai-3","moduleId":"obstructive-uropathy-hydronephrosis","stem":"What is a common clinical finding after relieving a high-grade obstruction in the urinary tract?","options":[{"id":"a","text":"Decreased urine output"},{"id":"b","text":"Post-obstructive diuresis"},{"id":"c","text":"Increased creatinine levels"},{"id":"d","text":"Persistent hydronephrosis"}],"answerId":"b","explanation":"Post-obstructive diuresis is a common finding after relieving a high-grade obstruction, resulting from accumulated solute and tubular dysfunction.","kind":"recall","origin":"ai"},{"id":"obstructive-uropathy-hydronephrosis~ai-4","moduleId":"obstructive-uropathy-hydronephrosis","stem":"In a patient with unilateral ureteral obstruction, why might the serum creatinine remain normal?","options":[{"id":"a","text":"The patient is dehydrated"},{"id":"b","text":"The contralateral kidney compensates"},{"id":"c","text":"There is no obstruction"},{"id":"d","text":"The obstruction is acute"}],"answerId":"b","explanation":"The contralateral kidney can compensate for the obstructed kidney, maintaining normal serum creatinine levels despite the obstruction.","kind":"trap","origin":"ai"},{"id":"obstructive-uropathy-hydronephrosis~ai-5","moduleId":"obstructive-uropathy-hydronephrosis","stem":"How does hydronephrosis relate to nephrolithiasis?","options":[{"id":"a","text":"Hydronephrosis causes nephrolithiasis"},{"id":"b","text":"Nephrolithiasis can lead to hydronephrosis"},{"id":"c","text":"Both are unrelated conditions"},{"id":"d","text":"Hydronephrosis is a type of nephrolithiasis"}],"answerId":"b","explanation":"Nephrolithiasis can cause obstruction of the urinary tract, leading to hydronephrosis as a result of back-pressure.","kind":"integration","linkedModuleIds":["nephrolithiasis-urolithiasis"],"origin":"ai"},{"id":"obstructive-uropathy-hydronephrosis~ai-6","moduleId":"obstructive-uropathy-hydronephrosis","stem":"What is the relationship between obstructive uropathy and acute kidney injury (AKI)?","options":[{"id":"a","text":"Obstructive uropathy always causes intrinsic AKI"},{"id":"b","text":"Obstructive uropathy can lead to postrenal AKI"},{"id":"c","text":"Obstructive uropathy prevents AKI"},{"id":"d","text":"Obstructive uropathy is unrelated to AKI"}],"answerId":"b","explanation":"Obstructive uropathy can lead to postrenal AKI, especially if the obstruction is bilateral or affects a single functioning kidney.","kind":"integration","linkedModuleIds":["aki-prerenal-intrinsic-postrenal"],"origin":"ai"}],"membranous-membranoproliferative-gn":[{"id":"membranous-membranoproliferative-gn~ai-0","moduleId":"membranous-membranoproliferative-gn","stem":"What is the most common autoantibody associated with primary membranous nephropathy?","options":[{"id":"a","text":"Anti-PLA2R"},{"id":"b","text":"Anti-dsDNA"},{"id":"c","text":"Anti-Smith"},{"id":"d","text":"Anti-CCP"}],"answerId":"a","explanation":"Anti-PLA2R is the primary autoantibody found in approximately 70-80% of primary membranous nephropathy cases.","kind":"recall","origin":"ai"},{"id":"membranous-membranoproliferative-gn~ai-1","moduleId":"membranous-membranoproliferative-gn","stem":"Which histological finding is characteristic of membranoproliferative glomerulonephritis?","options":[{"id":"a","text":"Spike and dome appearance"},{"id":"b","text":"Tram-track appearance"},{"id":"c","text":"Hyaline arteriolosclerosis"},{"id":"d","text":"Fibrinoid necrosis"}],"answerId":"b","explanation":"The tram-track appearance is a hallmark of membranoproliferative glomerulonephritis due to double-contouring of the basement membrane.","kind":"recall","origin":"ai"},{"id":"membranous-membranoproliferative-gn~ai-2","moduleId":"membranous-membranoproliferative-gn","stem":"A patient with nephrotic syndrome presents with new flank pain. What is the most likely complication?","options":[{"id":"a","text":"Musculoskeletal strain"},{"id":"b","text":"Renal vein thrombosis"},{"id":"c","text":"Acute pyelonephritis"},{"id":"d","text":"Nephrolithiasis"}],"answerId":"b","explanation":"New flank pain in a nephrotic patient, especially with membranous nephropathy, raises suspicion for renal vein thrombosis due to the loss of anticoagulant proteins.","kind":"trap","origin":"ai"},{"id":"membranous-membranoproliferative-gn~ai-3","moduleId":"membranous-membranoproliferative-gn","stem":"Which of the following is a common secondary cause of membranous nephropathy?","options":[{"id":"a","text":"Minimal change disease"},{"id":"b","text":"Hepatitis B infection"},{"id":"c","text":"Focal segmental glomerulosclerosis"},{"id":"d","text":"IgA nephropathy"}],"answerId":"b","explanation":"Hepatitis B infection is a recognized secondary cause of membranous nephropathy.","kind":"recall","origin":"ai"},{"id":"membranous-membranoproliferative-gn~ai-4","moduleId":"membranous-membranoproliferative-gn","stem":"In a patient with mixed nephrotic-nephritic features and low serum complement levels, which condition is most likely?","options":[{"id":"a","text":"Minimal change disease"},{"id":"b","text":"Focal segmental glomerulosclerosis"},{"id":"c","text":"Membranous nephropathy"},{"id":"d","text":"Membranoproliferative glomerulonephritis"}],"answerId":"d","explanation":"Membranoproliferative glomerulonephritis typically presents with mixed features and low complement levels.","kind":"clinical","origin":"ai"},{"id":"membranous-membranoproliferative-gn~ai-5","moduleId":"membranous-membranoproliferative-gn","stem":"How does the mechanism of injury differ between membranous nephropathy and minimal change disease?","options":[{"id":"a","text":"Subepithelial deposits vs podocyte injury"},{"id":"b","text":"Mesangial proliferation vs subepithelial deposits"},{"id":"c","text":"Immune complex deposition vs T-cell mediated"},{"id":"d","text":"Low complement vs normal complement"}],"answerId":"a","explanation":"Membranous nephropathy involves subepithelial immune complex deposits, while minimal change disease is characterized by podocyte injury without deposits.","kind":"integration","linkedModuleIds":["minimal-change-fsgs"],"origin":"ai"},{"id":"membranous-membranoproliferative-gn~ai-6","moduleId":"membranous-membranoproliferative-gn","stem":"What is the primary pathophysiological mechanism in C3 glomerulopathy?","options":[{"id":"a","text":"Subepithelial immune complex deposition"},{"id":"b","text":"Dysregulation of the alternative complement pathway"},{"id":"c","text":"Podocyte foot process effacement"},{"id":"d","text":"Mesangial IgA deposition"}],"answerId":"b","explanation":"C3 glomerulopathy results from dysregulation of the alternative complement pathway, leading to complement-mediated injury.","kind":"integration","linkedModuleIds":["glomerular-disease-immune-mechanisms"],"origin":"ai"}],"renal-replacement-therapy":[{"id":"renal-replacement-therapy~ai-0","moduleId":"renal-replacement-therapy","stem":"What is the primary indication for initiating renal replacement therapy in a patient with acute kidney injury?","options":[{"id":"a","text":"Severe hyperkalemia"},{"id":"b","text":"Elevated creatinine"},{"id":"c","text":"Fluid overload"},{"id":"d","text":"Uremic symptoms"}],"answerId":"a","explanation":"Severe hyperkalemia is one of the urgent indications for dialysis in AKI, as per the 'AEIOU' criteria.","kind":"recall","origin":"ai"},{"id":"renal-replacement-therapy~ai-1","moduleId":"renal-replacement-therapy","stem":"Which mechanism primarily drives fluid removal in peritoneal dialysis?","options":[{"id":"a","text":"Diffusion"},{"id":"b","text":"Ultrafiltration"},{"id":"c","text":"Osmosis"},{"id":"d","text":"Convection"}],"answerId":"c","explanation":"Fluid removal in peritoneal dialysis is primarily driven by osmotic forces from the dialysate, typically containing glucose.","kind":"mechanism","origin":"ai"},{"id":"renal-replacement-therapy~ai-2","moduleId":"renal-replacement-therapy","stem":"A patient undergoing hemodialysis presents with a thrill and bruit over their arteriovenous fistula. What does this finding indicate?","options":[{"id":"a","text":"Dialysis access failure"},{"id":"b","text":"Functioning dialysis access"},{"id":"c","text":"Infection at the site"},{"id":"d","text":"Thrombosis of the fistula"}],"answerId":"b","explanation":"A thrill and bruit indicate that the arteriovenous fistula is functioning properly, allowing blood flow for dialysis.","kind":"recall","origin":"ai"},{"id":"renal-replacement-therapy~ai-3","moduleId":"renal-replacement-therapy","stem":"What is a common complication associated with peritoneal dialysis?","options":[{"id":"a","text":"Hyperkalemia"},{"id":"b","text":"Peritonitis"},{"id":"c","text":"Hypotension"},{"id":"d","text":"Thrombosis"}],"answerId":"b","explanation":"Peritonitis is a common complication of peritoneal dialysis, characterized by cloudy effluent and abdominal pain.","kind":"trap","origin":"ai"},{"id":"renal-replacement-therapy~ai-4","moduleId":"renal-replacement-therapy","stem":"In a kidney transplant patient, what clinical finding would most likely indicate acute rejection?","options":[{"id":"a","text":"Fever and graft tenderness"},{"id":"b","text":"Decreased urine output"},{"id":"c","text":"Elevated blood pressure"},{"id":"d","text":"Weight gain"}],"answerId":"a","explanation":"Fever and graft tenderness with rising creatinine levels are indicative of acute rejection in kidney transplant patients.","kind":"recall","origin":"ai"},{"id":"renal-replacement-therapy~ai-5","moduleId":"renal-replacement-therapy","stem":"When should renal replacement therapy be initiated in acute kidney injury according to the 'AEIOU' criteria?","options":[{"id":"a","text":"When creatinine exceeds 2 mg/dL"},{"id":"b","text":"When urea exceeds 100 mg/dL"},{"id":"c","text":"Based on clinical symptoms"},{"id":"d","text":"After 48 hours of oliguria"}],"answerId":"c","explanation":"Initiation of renal replacement therapy in AKI is based on clinical symptoms and indications rather than fixed lab values.","kind":"trap","origin":"ai"},{"id":"renal-replacement-therapy~ai-6","moduleId":"renal-replacement-therapy","stem":"How does hyperkalemia relate to renal replacement therapy in acute kidney injury?","options":[{"id":"a","text":"It is a contraindication for dialysis"},{"id":"b","text":"It is an indication for urgent dialysis"},{"id":"c","text":"It indicates the need for increased fluid intake"},{"id":"d","text":"It requires potassium supplementation"}],"answerId":"b","explanation":"Hyperkalemia is one of the urgent indications for initiating renal replacement therapy in acute kidney injury as per the 'AEIOU' criteria.","kind":"integration","linkedModuleIds":["potassium-disorders"],"origin":"ai"},{"id":"renal-replacement-therapy~ai-7","moduleId":"renal-replacement-therapy","stem":"What is the best long-term treatment option for patients with end-stage renal disease?","options":[{"id":"a","text":"Hemodialysis"},{"id":"b","text":"Peritoneal dialysis"},{"id":"c","text":"Kidney transplant"},{"id":"d","text":"Conservative management"}],"answerId":"c","explanation":"Kidney transplant is the best treatment for suitable end-stage renal disease patients, offering better survival and quality of life compared to dialysis.","kind":"integration","linkedModuleIds":["transplant-matching-immunosuppression"],"origin":"ai"}],"iga-nephropathy-postinfectious-gn":[{"id":"iga-nephropathy-postinfectious-gn~ai-0","moduleId":"iga-nephropathy-postinfectious-gn","stem":"What is the classic presentation of IgA nephropathy?","options":[{"id":"a","text":"Visible haematuria after a sore throat"},{"id":"b","text":"Recurrent visible haematuria with a recent upper respiratory infection"},{"id":"c","text":"Cola-colored urine 2 weeks after a skin infection"},{"id":"d","text":"Oedema and hypertension following a streptococcal infection"}],"answerId":"b","explanation":"IgA nephropathy typically presents with recurrent visible haematuria occurring with or shortly after a mucosal infection.","kind":"recall","origin":"ai"},{"id":"iga-nephropathy-postinfectious-gn~ai-1","moduleId":"iga-nephropathy-postinfectious-gn","stem":"Which immunofluorescence finding is characteristic of IgA nephropathy?","options":[{"id":"a","text":"Granular IgG and C3 deposits"},{"id":"b","text":"Mesangial IgA deposits"},{"id":"c","text":"Subepithelial immune humps"},{"id":"d","text":"Low C3 complement levels"}],"answerId":"b","explanation":"IgA nephropathy is characterized by mesangial IgA deposits on immunofluorescence.","kind":"recall","origin":"ai"},{"id":"iga-nephropathy-postinfectious-gn~ai-2","moduleId":"iga-nephropathy-postinfectious-gn","stem":"What is a key distinguishing feature of post-streptococcal glomerulonephritis compared to IgA nephropathy?","options":[{"id":"a","text":"Normal complement levels"},{"id":"b","text":"Presence of RBC casts"},{"id":"c","text":"Timing of symptoms after infection"},{"id":"d","text":"Mesangial IgA deposits"}],"answerId":"c","explanation":"Post-streptococcal glomerulonephritis occurs 1-3 weeks after infection, while IgA nephropathy presents with symptoms concurrently with the infection.","kind":"trap","origin":"ai"},{"id":"iga-nephropathy-postinfectious-gn~ai-3","moduleId":"iga-nephropathy-postinfectious-gn","stem":"In a child with purpura, abdominal pain, and nephritis, which condition should be considered?","options":[{"id":"a","text":"Post-streptococcal GN"},{"id":"b","text":"IgA nephropathy"},{"id":"c","text":"Henoch-Schönlein purpura"},{"id":"d","text":"Minimal change disease"}],"answerId":"c","explanation":"The combination of purpura, abdominal pain, and nephritis in a child is indicative of Henoch-Schönlein purpura, a systemic form of IgA vasculitis.","kind":"clinical","origin":"ai"},{"id":"iga-nephropathy-postinfectious-gn~ai-4","moduleId":"iga-nephropathy-postinfectious-gn","stem":"What laboratory finding is expected in post-streptococcal glomerulonephritis?","options":[{"id":"a","text":"Normal C3 levels"},{"id":"b","text":"Low C3 levels that normalize"},{"id":"c","text":"High IgA levels"},{"id":"d","text":"Mesangial IgA deposits"}],"answerId":"b","explanation":"Post-streptococcal glomerulonephritis is characterized by low C3 complement levels that normalize over 6-8 weeks.","kind":"recall","origin":"ai"},{"id":"iga-nephropathy-postinfectious-gn~ai-5","moduleId":"iga-nephropathy-postinfectious-gn","stem":"How does the timing of hematuria help differentiate IgA nephropathy from post-streptococcal GN?","options":[{"id":"a","text":"IgA nephropathy has a longer latent period"},{"id":"b","text":"Post-streptococcal GN presents with hematuria immediately"},{"id":"c","text":"IgA nephropathy presents with hematuria concurrently with infection"},{"id":"d","text":"Post-streptococcal GN has normal complement levels"}],"answerId":"c","explanation":"IgA nephropathy presents with hematuria at the same time as the upper respiratory infection, while post-streptococcal GN occurs after a latent period.","kind":"integration","linkedModuleIds":["streptococcus-pyogenes-agalactiae"],"origin":"ai"},{"id":"iga-nephropathy-postinfectious-gn~ai-6","moduleId":"iga-nephropathy-postinfectious-gn","stem":"Which immune mechanism is primarily involved in IgA nephropathy?","options":[{"id":"a","text":"Complement-mediated injury"},{"id":"b","text":"Mesangial deposition of IgA immune complexes"},{"id":"c","text":"Antibody-mediated glomerular injury"},{"id":"d","text":"T-cell mediated injury"}],"answerId":"b","explanation":"IgA nephropathy involves mesangial deposition of IgA immune complexes, leading to glomerular injury.","kind":"integration","linkedModuleIds":["glomerular-disease-immune-mechanisms"],"origin":"ai"}],"minimal-change-fsgs":[{"id":"minimal-change-fsgs~ai-0","moduleId":"minimal-change-fsgs","stem":"What is the most common cause of nephrotic syndrome in children?","options":[{"id":"a","text":"Focal Segmental Glomerulosclerosis"},{"id":"b","text":"Minimal Change Disease"},{"id":"c","text":"Membranous Nephropathy"},{"id":"d","text":"Diabetic Nephropathy"}],"answerId":"b","explanation":"Minimal Change Disease is the most common cause of nephrotic syndrome in children due to its high steroid responsiveness.","kind":"recall","origin":"ai"},{"id":"minimal-change-fsgs~ai-1","moduleId":"minimal-change-fsgs","stem":"Which microscopy finding is characteristic of Minimal Change Disease?","options":[{"id":"a","text":"Focal glomerulosclerosis"},{"id":"b","text":"Segmental sclerosis"},{"id":"c","text":"Normal light microscopy"},{"id":"d","text":"Diffuse glomerular hypercellularity"}],"answerId":"c","explanation":"Minimal Change Disease is characterized by normal light microscopy, with podocyte foot-process effacement seen only on electron microscopy.","kind":"recall","origin":"ai"},{"id":"minimal-change-fsgs~ai-2","moduleId":"minimal-change-fsgs","stem":"A 30-year-old man presents with nephrotic syndrome and is found to have focal segmental glomerulosclerosis. Which of the following is a common secondary cause?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Diabetes Mellitus"},{"id":"c","text":"Obesity"},{"id":"d","text":"Systemic Lupus Erythematosus"}],"answerId":"c","explanation":"Obesity is a recognized secondary cause of focal segmental glomerulosclerosis in adults.","kind":"recall","origin":"ai"},{"id":"minimal-change-fsgs~ai-3","moduleId":"minimal-change-fsgs","stem":"In a child with nephrotic syndrome, which finding would suggest a diagnosis of Focal Segmental Glomerulosclerosis rather than Minimal Change Disease?","options":[{"id":"a","text":"Normal light microscopy"},{"id":"b","text":"Steroid resistance"},{"id":"c","text":"Foot-process effacement"},{"id":"d","text":"Rapid response to corticosteroids"}],"answerId":"b","explanation":"Steroid resistance is a key feature that suggests Focal Segmental Glomerulosclerosis rather than Minimal Change Disease, which is steroid-responsive.","kind":"clinical","origin":"ai"},{"id":"minimal-change-fsgs~ai-4","moduleId":"minimal-change-fsgs","stem":"What is the primary mechanism leading to nephrotic syndrome in both Minimal Change Disease and Focal Segmental Glomerulosclerosis?","options":[{"id":"a","text":"Glomerular hyperfiltration"},{"id":"b","text":"Podocyte foot-process effacement"},{"id":"c","text":"Immune complex deposition"},{"id":"d","text":"Tubular injury"}],"answerId":"b","explanation":"Podocyte foot-process effacement is the primary mechanism leading to nephrotic syndrome in both conditions.","kind":"mechanism","origin":"ai"},{"id":"minimal-change-fsgs~ai-5","moduleId":"minimal-change-fsgs","stem":"Which of the following statements about the management of Minimal Change Disease is true?","options":[{"id":"a","text":"All children require a renal biopsy"},{"id":"b","text":"Corticosteroids are the first-line treatment"},{"id":"c","text":"It is commonly steroid-resistant"},{"id":"d","text":"Calcineurin inhibitors are first-line therapy"}],"answerId":"b","explanation":"Corticosteroids are the first-line treatment for Minimal Change Disease, which is typically steroid-responsive.","kind":"trap","origin":"ai"},{"id":"minimal-change-fsgs~ai-6","moduleId":"minimal-change-fsgs","stem":"A patient with nephrotic syndrome and a history of HIV presents with proteinuria. Which condition is most likely?","options":[{"id":"a","text":"Minimal Change Disease"},{"id":"b","text":"Focal Segmental Glomerulosclerosis"},{"id":"c","text":"Membranous Nephropathy"},{"id":"d","text":"Diabetic Nephropathy"}],"answerId":"b","explanation":"Focal Segmental Glomerulosclerosis is commonly associated with HIV and can present as nephrotic syndrome.","kind":"integration","linkedModuleIds":["nephrotic-syndrome"],"origin":"ai"},{"id":"minimal-change-fsgs~ai-7","moduleId":"minimal-change-fsgs","stem":"How does the immune mechanism of podocyte injury relate to the pathophysiology of Minimal Change Disease?","options":[{"id":"a","text":"It involves immune complex deposition"},{"id":"b","text":"It leads to direct podocyte injury"},{"id":"c","text":"It causes systemic inflammation"},{"id":"d","text":"It results in glomerular hyperfiltration"}],"answerId":"b","explanation":"In Minimal Change Disease, podocyte injury is often mediated by immune mechanisms, leading to foot-process effacement and nephrotic syndrome.","kind":"integration","linkedModuleIds":["glomerular-disease-immune-mechanisms"],"origin":"ai"}],"renal-cell-carcinoma":[{"id":"renal-cell-carcinoma~ai-0","moduleId":"renal-cell-carcinoma","stem":"What is the most common subtype of renal cell carcinoma (RCC)?","options":[{"id":"a","text":"Clear cell RCC"},{"id":"b","text":"Papillary RCC"},{"id":"c","text":"Chromophobe RCC"},{"id":"d","text":"Collecting duct carcinoma"}],"answerId":"a","explanation":"Clear cell RCC is the most common subtype, associated with VHL gene mutations.","kind":"recall","origin":"ai"},{"id":"renal-cell-carcinoma~ai-1","moduleId":"renal-cell-carcinoma","stem":"Which mechanism primarily drives the angiogenesis in clear cell renal cell carcinoma?","options":[{"id":"a","text":"Increased VEGF due to HIF stabilization"},{"id":"b","text":"Increased EPO secretion"},{"id":"c","text":"Increased PTHrP secretion"},{"id":"d","text":"Direct invasion of blood vessels"}],"answerId":"a","explanation":"Loss of the VHL tumor suppressor leads to HIF stabilization, which increases VEGF and drives angiogenesis.","kind":"mechanism","origin":"ai"},{"id":"renal-cell-carcinoma~ai-2","moduleId":"renal-cell-carcinoma","stem":"A 60-year-old male presents with incidental findings of a renal mass on CT. Which paraneoplastic syndrome is most likely associated with this condition?","options":[{"id":"a","text":"Cushing's syndrome"},{"id":"b","text":"Hypercalcemia"},{"id":"c","text":"Syndrome of inappropriate antidiuretic hormone secretion (SIADH)"},{"id":"d","text":"Hypoglycemia"}],"answerId":"b","explanation":"Renal cell carcinoma can cause hypercalcemia through PTHrP secretion.","kind":"clinical","origin":"ai"},{"id":"renal-cell-carcinoma~ai-3","moduleId":"renal-cell-carcinoma","stem":"Which of the following findings is most characteristic of renal cell carcinoma metastasis?","options":[{"id":"a","text":"Liver lesions"},{"id":"b","text":"Multiple round 'cannonball' lung lesions"},{"id":"c","text":"Bone pain"},{"id":"d","text":"Enlarged lymph nodes"}],"answerId":"b","explanation":"RCC often metastasizes to the lungs, presenting as multiple round 'cannonball' lesions.","kind":"recall","origin":"ai"},{"id":"renal-cell-carcinoma~ai-4","moduleId":"renal-cell-carcinoma","stem":"A patient presents with a new, non-reducing left-sided varicocele. What is the most likely underlying cause?","options":[{"id":"a","text":"Right renal vein obstruction"},{"id":"b","text":"Left renal vein obstruction by RCC"},{"id":"c","text":"Testicular tumor"},{"id":"d","text":"Inguinal hernia"}],"answerId":"b","explanation":"Left-sided varicocele can occur due to obstruction of the left renal vein by renal cell carcinoma.","kind":"clinical","origin":"ai"},{"id":"renal-cell-carcinoma~ai-5","moduleId":"renal-cell-carcinoma","stem":"Which statement about the classic triad of renal cell carcinoma is true?","options":[{"id":"a","text":"It is present in over 50% of cases."},{"id":"b","text":"It is often the first sign of the disease."},{"id":"c","text":"It is now uncommon, occurring in less than 10% of cases."},{"id":"d","text":"It guarantees a diagnosis of RCC."}],"answerId":"c","explanation":"The classic triad of flank pain, hematuria, and mass is now uncommon in RCC, occurring in less than 10% of cases.","kind":"trap","origin":"ai"},{"id":"renal-cell-carcinoma~ai-6","moduleId":"renal-cell-carcinoma","stem":"How does renal cell carcinoma relate to the concept of neoplasia differentiation and invasion?","options":[{"id":"a","text":"RCC is always well-differentiated and non-invasive."},{"id":"b","text":"RCC can demonstrate varying degrees of differentiation and invasive behavior."},{"id":"c","text":"RCC is benign and does not invade surrounding tissues."},{"id":"d","text":"RCC is exclusively a poorly differentiated tumor."}],"answerId":"b","explanation":"RCC can show different levels of differentiation and can invade surrounding tissues, highlighting its malignant nature.","kind":"integration","linkedModuleIds":["neoplasia-differentiation-invasion"],"origin":"ai"},{"id":"renal-cell-carcinoma~ai-7","moduleId":"renal-cell-carcinoma","stem":"What is the relationship between renal cell carcinoma and urinary system neoplasms?","options":[{"id":"a","text":"RCC is a benign tumor of the urinary system."},{"id":"b","text":"RCC is the most common malignant tumor of the urinary system."},{"id":"c","text":"RCC is unrelated to urinary system neoplasms."},{"id":"d","text":"RCC is a type of bladder cancer."}],"answerId":"b","explanation":"RCC is the most common malignant tumor arising from the urinary system, specifically from the proximal tubular epithelium.","kind":"integration","linkedModuleIds":["urinary-system-neoplasms"],"origin":"ai"}],"aki-prerenal-intrinsic-postrenal":[{"id":"aki-prerenal-intrinsic-postrenal~ai-0","moduleId":"aki-prerenal-intrinsic-postrenal","stem":"What is the most common cause of prerenal acute kidney injury?","options":[{"id":"a","text":"Acute tubular necrosis"},{"id":"b","text":"Hypovolaemia"},{"id":"c","text":"Obstruction"},{"id":"d","text":"Acute interstitial nephritis"}],"answerId":"b","explanation":"Hypovolaemia is the most common cause of prerenal acute kidney injury due to reduced renal perfusion.","kind":"recall","origin":"ai"},{"id":"aki-prerenal-intrinsic-postrenal~ai-1","moduleId":"aki-prerenal-intrinsic-postrenal","stem":"Which laboratory finding is most indicative of prerenal azotaemia?","options":[{"id":"a","text":"FENa >2%"},{"id":"b","text":"Urine Na >40 mEq/L"},{"id":"c","text":"BUN:creatinine ratio >20"},{"id":"d","text":"Muddy-brown casts"}],"answerId":"c","explanation":"A BUN:creatinine ratio >20 is indicative of prerenal azotaemia, reflecting increased urea reabsorption due to hypoperfusion.","kind":"recall","origin":"ai"},{"id":"aki-prerenal-intrinsic-postrenal~ai-2","moduleId":"aki-prerenal-intrinsic-postrenal","stem":"A patient presents with acute kidney injury and urine analysis shows muddy-brown granular casts. What is the most likely diagnosis?","options":[{"id":"a","text":"Prerenal azotaemia"},{"id":"b","text":"Acute tubular necrosis"},{"id":"c","text":"Postrenal obstruction"},{"id":"d","text":"Acute interstitial nephritis"}],"answerId":"b","explanation":"Muddy-brown granular casts are characteristic of acute tubular necrosis, indicating tubular injury.","kind":"clinical","origin":"ai"},{"id":"aki-prerenal-intrinsic-postrenal~ai-3","moduleId":"aki-prerenal-intrinsic-postrenal","stem":"Which mechanism explains the renal effects of NSAIDs in a patient with volume depletion?","options":[{"id":"a","text":"Increased renal perfusion"},{"id":"b","text":"Decreased afferent arteriolar tone"},{"id":"c","text":"Inhibition of prostaglandin synthesis"},{"id":"d","text":"Increased efferent arteriolar tone"}],"answerId":"c","explanation":"NSAIDs inhibit prostaglandin synthesis, leading to decreased afferent arteriolar dilation and reduced renal perfusion in volume-depleted patients.","kind":"mechanism","origin":"ai"},{"id":"aki-prerenal-intrinsic-postrenal~ai-4","moduleId":"aki-prerenal-intrinsic-postrenal","stem":"A patient with acute kidney injury shows hydronephrosis on ultrasound. What is the most likely cause?","options":[{"id":"a","text":"Acute tubular necrosis"},{"id":"b","text":"Prerenal azotaemia"},{"id":"c","text":"Postrenal obstruction"},{"id":"d","text":"Acute interstitial nephritis"}],"answerId":"c","explanation":"Hydronephrosis on ultrasound indicates postrenal obstruction, which can lead to acute kidney injury.","kind":"clinical","origin":"ai"},{"id":"aki-prerenal-intrinsic-postrenal~ai-5","moduleId":"aki-prerenal-intrinsic-postrenal","stem":"Which of the following findings would help differentiate prerenal AKI from acute tubular necrosis?","options":[{"id":"a","text":"Urine Na <20 mEq/L"},{"id":"b","text":"FENa >2%"},{"id":"c","text":"Muddy-brown casts"},{"id":"d","text":"Isosthenuric urine"}],"answerId":"a","explanation":"Urine Na <20 mEq/L is indicative of prerenal AKI, while FENa >2% and muddy-brown casts suggest acute tubular necrosis.","kind":"trap","origin":"ai"},{"id":"aki-prerenal-intrinsic-postrenal~ai-6","moduleId":"aki-prerenal-intrinsic-postrenal","stem":"In a patient with acute kidney injury and a history of urinary obstruction, which finding would suggest a postrenal cause?","options":[{"id":"a","text":"Muddy-brown casts"},{"id":"b","text":"FENa <1%"},{"id":"c","text":"Hydronephrosis on ultrasound"},{"id":"d","text":"BUN:creatinine ratio >20"}],"answerId":"c","explanation":"Hydronephrosis on ultrasound is a key indicator of postrenal obstruction leading to acute kidney injury.","kind":"integration","linkedModuleIds":["obstructive-uropathy-hydronephrosis"],"origin":"ai"},{"id":"aki-prerenal-intrinsic-postrenal~ai-7","moduleId":"aki-prerenal-intrinsic-postrenal","stem":"A patient with acute kidney injury presents with eosinophils in the urine. What is the likely diagnosis?","options":[{"id":"a","text":"Acute tubular necrosis"},{"id":"b","text":"Acute interstitial nephritis"},{"id":"c","text":"Postrenal obstruction"},{"id":"d","text":"Prerenal azotaemia"}],"answerId":"b","explanation":"Eosinophils in the urine suggest acute interstitial nephritis, often due to drug reactions.","kind":"integration","linkedModuleIds":["acute-interstitial-nephritis"],"origin":"ai"}],"polycystic-kidney-disease":[{"id":"polycystic-kidney-disease~ai-0","moduleId":"polycystic-kidney-disease","stem":"What is the most common genetic mutation associated with Autosomal Dominant Polycystic Kidney Disease (ADPKD)?","options":[{"id":"a","text":"PKD1"},{"id":"b","text":"PKD2"},{"id":"c","text":"PKHD1"},{"id":"d","text":"APOL1"}],"answerId":"a","explanation":"The majority of ADPKD cases are due to mutations in the PKD1 gene, located on chromosome 16.","kind":"recall","origin":"ai"},{"id":"polycystic-kidney-disease~ai-1","moduleId":"polycystic-kidney-disease","stem":"Which of the following is a classic extrarenal manifestation of ADPKD?","options":[{"id":"a","text":"Hepatic cysts"},{"id":"b","text":"Pancreatic insufficiency"},{"id":"c","text":"Cystic fibrosis"},{"id":"d","text":"Diabetes insipidus"}],"answerId":"a","explanation":"Hepatic cysts are a well-known extrarenal manifestation of ADPKD.","kind":"recall","origin":"ai"},{"id":"polycystic-kidney-disease~ai-2","moduleId":"polycystic-kidney-disease","stem":"A 45-year-old man with known ADPKD presents with a sudden, severe headache. What is the most likely cause?","options":[{"id":"a","text":"Intracranial hemorrhage"},{"id":"b","text":"Migraine"},{"id":"c","text":"Tension headache"},{"id":"d","text":"Subarachnoid hemorrhage from a ruptured berry aneurysm"}],"answerId":"d","explanation":"In patients with ADPKD, a sudden severe headache may indicate a ruptured berry aneurysm, leading to subarachnoid hemorrhage.","kind":"clinical","origin":"ai"},{"id":"polycystic-kidney-disease~ai-3","moduleId":"polycystic-kidney-disease","stem":"What is the primary mechanism by which tolvaptan slows the progression of ADPKD?","options":[{"id":"a","text":"Inhibition of cyst growth"},{"id":"b","text":"Reduction of blood pressure"},{"id":"c","text":"Decreased renal blood flow"},{"id":"d","text":"Inhibition of vasopressin V2 receptors"}],"answerId":"d","explanation":"Tolvaptan acts as a vasopressin V2-receptor antagonist, which helps to slow cyst growth in ADPKD.","kind":"mechanism","origin":"ai"},{"id":"polycystic-kidney-disease~ai-4","moduleId":"polycystic-kidney-disease","stem":"Which of the following findings would most likely indicate a diagnosis of Autosomal Recessive Polycystic Kidney Disease (ARPKD)?","options":[{"id":"a","text":"Bilateral flank masses in an adult"},{"id":"b","text":"Oligohydramnios and huge kidneys in a neonate"},{"id":"c","text":"Hypertension and hematuria"},{"id":"d","text":"Family history of berry aneurysms"}],"answerId":"b","explanation":"ARPKD typically presents in neonates with markedly enlarged kidneys and oligohydramnios.","kind":"trap","origin":"ai"},{"id":"polycystic-kidney-disease~ai-5","moduleId":"polycystic-kidney-disease","stem":"A patient with ADPKD is found to have hepatic cysts and mitral valve prolapse. What does this indicate about the disease?","options":[{"id":"a","text":"It is a purely renal disease"},{"id":"b","text":"It has systemic implications"},{"id":"c","text":"It is likely to progress to ESRD"},{"id":"d","text":"It is associated with ARPKD"}],"answerId":"b","explanation":"ADPKD is a systemic disease that can involve multiple organ systems, including the liver and heart.","kind":"trap","origin":"ai"},{"id":"polycystic-kidney-disease~ai-6","moduleId":"polycystic-kidney-disease","stem":"How does chronic kidney disease (CKD) relate to the management of ADPKD?","options":[{"id":"a","text":"CKD is a complication of ADPKD"},{"id":"b","text":"CKD is unrelated to ADPKD"},{"id":"c","text":"CKD can be cured by treating ADPKD"},{"id":"d","text":"CKD is only seen in ARPKD"}],"answerId":"a","explanation":"ADPKD often progresses to chronic kidney disease (CKD), making its management crucial.","kind":"integration","linkedModuleIds":["chronic-kidney-disease"],"origin":"ai"},{"id":"polycystic-kidney-disease~ai-7","moduleId":"polycystic-kidney-disease","stem":"In patients with ADPKD, how are renovascular disorders relevant to their management?","options":[{"id":"a","text":"They are a common cause of CKD"},{"id":"b","text":"They are unrelated to ADPKD"},{"id":"c","text":"They can complicate hypertension management"},{"id":"d","text":"They are only seen in ARPKD"}],"answerId":"c","explanation":"Renovascular disorders can complicate hypertension management in patients with ADPKD.","kind":"integration","linkedModuleIds":["renovascular-disorders"],"origin":"ai"}],"renal-artery-stenosis":[{"id":"renal-artery-stenosis~ai-0","moduleId":"renal-artery-stenosis","stem":"What is the most common cause of renal artery stenosis in older patients?","options":[{"id":"a","text":"Fibromuscular dysplasia"},{"id":"b","text":"Atherosclerosis"},{"id":"c","text":"Thromboembolism"},{"id":"d","text":"Renal vein thrombosis"}],"answerId":"b","explanation":"Atherosclerosis is the most common cause of renal artery stenosis in older patients, often associated with other vascular diseases.","kind":"recall","origin":"ai"},{"id":"renal-artery-stenosis~ai-1","moduleId":"renal-artery-stenosis","stem":"Which clinical finding is most indicative of renal artery stenosis?","options":[{"id":"a","text":"Bilateral leg edema"},{"id":"b","text":"Abdominal bruit"},{"id":"c","text":"Elevated liver enzymes"},{"id":"d","text":"Decreased urine output"}],"answerId":"b","explanation":"An abdominal bruit is a classic clinical finding that suggests renal artery stenosis due to renovascular hypertension.","kind":"clinical","origin":"ai"},{"id":"renal-artery-stenosis~ai-2","moduleId":"renal-artery-stenosis","stem":"What mechanism explains the sharp rise in creatinine after starting an ACE inhibitor in a patient with renal artery stenosis?","options":[{"id":"a","text":"Increased renal blood flow"},{"id":"b","text":"Decreased efferent arteriolar constriction"},{"id":"c","text":"Nephrotoxic effects of ACE inhibitors"},{"id":"d","text":"Increased glomerular filtration rate"}],"answerId":"b","explanation":"In renal artery stenosis, angiotensin II maintains GFR by constricting the efferent arteriole; blocking it with an ACE inhibitor can lead to a sharp rise in creatinine.","kind":"mechanism","origin":"ai"},{"id":"renal-artery-stenosis~ai-3","moduleId":"renal-artery-stenosis","stem":"Which imaging finding is characteristic of fibromuscular dysplasia in renal artery stenosis?","options":[{"id":"a","text":"String-of-beads appearance"},{"id":"b","text":"Stenosis at the ostium"},{"id":"c","text":"Renal vein thrombosis"},{"id":"d","text":"Bilateral kidney enlargement"}],"answerId":"a","explanation":"Fibromuscular dysplasia is characterized by a 'string-of-beads' appearance on angiography, typically affecting the mid to distal renal artery.","kind":"recall","origin":"ai"},{"id":"renal-artery-stenosis~ai-4","moduleId":"renal-artery-stenosis","stem":"Which statement about the management of renal artery stenosis is true?","options":[{"id":"a","text":"Revascularization is always the first-line treatment"},{"id":"b","text":"ACE inhibitors are contraindicated in all cases"},{"id":"c","text":"Medical management is the primary approach"},{"id":"d","text":"Statins are not recommended"}],"answerId":"c","explanation":"Medical management, including RAAS blockade and monitoring, is the primary approach for renal artery stenosis, with revascularization reserved for selected cases.","kind":"trap","origin":"ai"},{"id":"renal-artery-stenosis~ai-5","moduleId":"renal-artery-stenosis","stem":"How does renal artery stenosis relate to chronic kidney disease?","options":[{"id":"a","text":"It causes acute kidney injury"},{"id":"b","text":"It leads to hyperkalemia"},{"id":"c","text":"It can result in ischemic nephropathy"},{"id":"d","text":"It prevents the development of CKD"}],"answerId":"c","explanation":"Chronic bilateral renal artery stenosis can lead to ischemic nephropathy, which is a cause of chronic kidney disease.","kind":"integration","linkedModuleIds":["chronic-kidney-disease"],"origin":"ai"},{"id":"renal-artery-stenosis~ai-6","moduleId":"renal-artery-stenosis","stem":"What is the expected effect of RAAS activation in renal artery stenosis?","options":[{"id":"a","text":"Increased renal perfusion"},{"id":"b","text":"Decreased blood pressure"},{"id":"c","text":"Increased sodium retention"},{"id":"d","text":"Decreased creatinine levels"}],"answerId":"c","explanation":"RAAS activation in renal artery stenosis leads to increased sodium retention, contributing to renovascular hypertension.","kind":"mechanism","origin":"ai"},{"id":"renal-artery-stenosis~ai-7","moduleId":"renal-artery-stenosis","stem":"Which condition is most likely to present with flash pulmonary edema?","options":[{"id":"a","text":"Chronic kidney disease"},{"id":"b","text":"Bilateral renal artery stenosis"},{"id":"c","text":"Heart failure"},{"id":"d","text":"Diabetes mellitus"}],"answerId":"b","explanation":"Bilateral renal artery stenosis can lead to flash pulmonary edema due to sudden increases in blood pressure and fluid overload.","kind":"clinical","origin":"ai"},{"id":"renal-artery-stenosis~ai-8","moduleId":"renal-artery-stenosis","stem":"What is a common misconception regarding the rise in creatinine after ACE inhibitor therapy?","options":[{"id":"a","text":"It indicates the drug is always nephrotoxic"},{"id":"b","text":"A small rise is always harmful"},{"id":"c","text":"It is a sign of effective treatment"},{"id":"d","text":"It is unrelated to renal artery stenosis"}],"answerId":"a","explanation":"A common misconception is that any rise in creatinine after ACE inhibitor therapy indicates nephrotoxicity; however, a modest rise can be expected and may indicate renal artery stenosis.","kind":"trap","origin":"ai"}],"ckd-mineral-bone-disorder":[{"id":"ckd-mineral-bone-disorder~ai-0","moduleId":"ckd-mineral-bone-disorder","stem":"What is the primary cause of secondary hyperparathyroidism in chronic kidney disease?","options":[{"id":"a","text":"Increased calcium absorption"},{"id":"b","text":"Decreased phosphate excretion"},{"id":"c","text":"Increased calcitriol production"},{"id":"d","text":"Decreased parathyroid hormone secretion"}],"answerId":"b","explanation":"In chronic kidney disease, the kidneys cannot excrete phosphate effectively, leading to hyperphosphatemia, which stimulates parathyroid hormone secretion.","kind":"mechanism","origin":"ai"},{"id":"ckd-mineral-bone-disorder~ai-1","moduleId":"ckd-mineral-bone-disorder","stem":"Which laboratory finding is characteristic of CKD-Mineral and Bone Disorder?","options":[{"id":"a","text":"High calcium, low phosphate"},{"id":"b","text":"Low calcium, high phosphate"},{"id":"c","text":"Normal calcium, normal phosphate"},{"id":"d","text":"High calcium, high phosphate"}],"answerId":"b","explanation":"The classic biochemistry of CKD-MBD includes low calcium and high phosphate due to impaired renal function.","kind":"recall","origin":"ai"},{"id":"ckd-mineral-bone-disorder~ai-2","moduleId":"ckd-mineral-bone-disorder","stem":"A patient with CKD presents with bone pain and elevated PTH levels. What is the likely underlying condition?","options":[{"id":"a","text":"Primary hyperparathyroidism"},{"id":"b","text":"Osteitis fibrosa cystica"},{"id":"c","text":"Osteoporosis"},{"id":"d","text":"Paget's disease"}],"answerId":"b","explanation":"Elevated PTH levels in CKD lead to high-turnover bone disease known as osteitis fibrosa cystica.","kind":"clinical","origin":"ai"},{"id":"ckd-mineral-bone-disorder~ai-3","moduleId":"ckd-mineral-bone-disorder","stem":"In chronic kidney disease, which hormone is primarily deficient, contributing to anaemia?","options":[{"id":"a","text":"Erythropoietin"},{"id":"b","text":"Calcitriol"},{"id":"c","text":"Parathyroid hormone"},{"id":"d","text":"Renin"}],"answerId":"a","explanation":"The failing kidneys produce insufficient erythropoietin, leading to normocytic, normochromic anaemia.","kind":"recall","origin":"ai"},{"id":"ckd-mineral-bone-disorder~ai-4","moduleId":"ckd-mineral-bone-disorder","stem":"What is the mechanism of action of calcimimetics in treating secondary hyperparathyroidism?","options":[{"id":"a","text":"Inhibit calcium absorption"},{"id":"b","text":"Increase phosphate excretion"},{"id":"c","text":"Decrease PTH secretion"},{"id":"d","text":"Stimulate calcitriol production"}],"answerId":"c","explanation":"Calcimimetics act by increasing the sensitivity of calcium-sensing receptors on parathyroid cells, leading to decreased PTH secretion.","kind":"mechanism","origin":"ai"},{"id":"ckd-mineral-bone-disorder~ai-5","moduleId":"ckd-mineral-bone-disorder","stem":"A patient with CKD has persistent high PTH levels and develops hypercalcaemia after years. What condition has likely developed?","options":[{"id":"a","text":"Primary hyperparathyroidism"},{"id":"b","text":"Secondary hyperparathyroidism"},{"id":"c","text":"Tertiary hyperparathyroidism"},{"id":"d","text":"Osteitis fibrosa cystica"}],"answerId":"c","explanation":"Tertiary hyperparathyroidism occurs when parathyroid glands become autonomous after prolonged secondary hyperparathyroidism, leading to hypercalcaemia.","kind":"clinical","origin":"ai"},{"id":"ckd-mineral-bone-disorder~ai-6","moduleId":"ckd-mineral-bone-disorder","stem":"How does chronic kidney disease affect calcium homeostasis, particularly in relation to calcitriol?","options":[{"id":"a","text":"Increases calcitriol production"},{"id":"b","text":"Decreases calcitriol production"},{"id":"c","text":"Has no effect on calcitriol"},{"id":"d","text":"Increases calcium absorption from the gut"}],"answerId":"b","explanation":"In CKD, the kidneys fail to produce sufficient calcitriol, leading to decreased calcium absorption and contributing to hypocalcaemia.","kind":"trap","origin":"ai"},{"id":"ckd-mineral-bone-disorder~ai-7","moduleId":"ckd-mineral-bone-disorder","stem":"How does the management of CKD-MBD relate to calcium homeostasis hormones?","options":[{"id":"a","text":"Only dietary changes are needed"},{"id":"b","text":"Active vitamin D is used to increase calcium levels"},{"id":"c","text":"Phosphate binders are ineffective"},{"id":"d","text":"Calcitonin is the primary treatment"}],"answerId":"b","explanation":"Management of CKD-MBD includes active vitamin D to increase calcium absorption and counteract low calcitriol levels.","kind":"integration","linkedModuleIds":["calcium-homeostasis-hormones"],"origin":"ai"},{"id":"ckd-mineral-bone-disorder~ai-8","moduleId":"ckd-mineral-bone-disorder","stem":"What is the relationship between CKD and renal handling of phosphate?","options":[{"id":"a","text":"CKD increases phosphate reabsorption"},{"id":"b","text":"CKD decreases phosphate reabsorption"},{"id":"c","text":"CKD has no effect on phosphate handling"},{"id":"d","text":"CKD enhances phosphate secretion"}],"answerId":"b","explanation":"In CKD, the kidneys are unable to excrete phosphate effectively, leading to hyperphosphatemia.","kind":"integration","linkedModuleIds":["renal-calcium-phosphate-handling"],"origin":"ai"}],"glomerular-disease-immune-mechanisms":[{"id":"glomerular-disease-immune-mechanisms~ai-0","moduleId":"glomerular-disease-immune-mechanisms","stem":"What is the primary clinical feature of nephrotic syndrome?","options":[{"id":"a","text":"Hematuria with RBC casts"},{"id":"b","text":"Heavy proteinuria"},{"id":"c","text":"Hypertension"},{"id":"d","text":"Reduced GFR"}],"answerId":"b","explanation":"Nephrotic syndrome is characterized by heavy proteinuria (>3.5 g/day) due to podocyte injury.","kind":"recall","origin":"ai"},{"id":"glomerular-disease-immune-mechanisms~ai-1","moduleId":"glomerular-disease-immune-mechanisms","stem":"Which immunofluorescence pattern is associated with anti-GBM disease?","options":[{"id":"a","text":"Granular deposits"},{"id":"b","text":"Linear IgG"},{"id":"c","text":"Scant staining"},{"id":"d","text":"Crescent formation"}],"answerId":"b","explanation":"Anti-GBM disease shows a linear IgG pattern along the glomerular basement membrane.","kind":"recall","origin":"ai"},{"id":"glomerular-disease-immune-mechanisms~ai-2","moduleId":"glomerular-disease-immune-mechanisms","stem":"A patient presents with hematuria, RBC casts, and hypertension. What is the most likely diagnosis?","options":[{"id":"a","text":"Nephrotic syndrome"},{"id":"b","text":"Rapidly progressive glomerulonephritis"},{"id":"c","text":"Minimal change disease"},{"id":"d","text":"IgA nephropathy"}],"answerId":"b","explanation":"The combination of hematuria, RBC casts, and hypertension suggests a nephritic syndrome, likely rapidly progressive glomerulonephritis.","kind":"clinical","origin":"ai"},{"id":"glomerular-disease-immune-mechanisms~ai-3","moduleId":"glomerular-disease-immune-mechanisms","stem":"Which of the following findings would suggest a diagnosis of rapidly progressive glomerulonephritis?","options":[{"id":"a","text":"Bland urinary sediment"},{"id":"b","text":"Heavy proteinuria"},{"id":"c","text":"Crescents on biopsy"},{"id":"d","text":"Normal complement levels"}],"answerId":"c","explanation":"Crescents on biopsy are indicative of rapidly progressive glomerulonephritis, a nephrological emergency.","kind":"recall","origin":"ai"},{"id":"glomerular-disease-immune-mechanisms~ai-4","moduleId":"glomerular-disease-immune-mechanisms","stem":"In a patient with nephritic syndrome, which laboratory finding would indicate a post-streptococcal glomerulonephritis?","options":[{"id":"a","text":"Low complement levels"},{"id":"b","text":"High complement levels"},{"id":"c","text":"Positive ANCA"},{"id":"d","text":"Positive anti-GBM antibodies"}],"answerId":"a","explanation":"Low complement levels are associated with post-streptococcal glomerulonephritis among other conditions.","kind":"mechanism","origin":"ai"},{"id":"glomerular-disease-immune-mechanisms~ai-5","moduleId":"glomerular-disease-immune-mechanisms","stem":"A patient with nephrotic syndrome has a renal biopsy showing granular immunofluorescence. Which condition is most likely?","options":[{"id":"a","text":"IgA nephropathy"},{"id":"b","text":"Goodpasture syndrome"},{"id":"c","text":"Membranous nephropathy"},{"id":"d","text":"ANCA-associated vasculitis"}],"answerId":"c","explanation":"Granular immunofluorescence is characteristic of immune complex diseases, such as membranous nephropathy.","kind":"integration","linkedModuleIds":["membranous-membranoproliferative-gn"],"origin":"ai"},{"id":"glomerular-disease-immune-mechanisms~ai-6","moduleId":"glomerular-disease-immune-mechanisms","stem":"A patient is diagnosed with IgA nephropathy after presenting with hematuria and mild proteinuria. Which finding would be expected on biopsy?","options":[{"id":"a","text":"Linear IgG deposits"},{"id":"b","text":"Granular IgA deposits"},{"id":"c","text":"Crescents"},{"id":"d","text":"Normal findings"}],"answerId":"b","explanation":"IgA nephropathy typically shows granular IgA deposits on immunofluorescence microscopy.","kind":"integration","linkedModuleIds":["iga-nephropathy-postinfectious-gn"],"origin":"ai"}],"high-anion-gap-metabolic-acidosis":[{"id":"high-anion-gap-metabolic-acidosis~ai-0","moduleId":"high-anion-gap-metabolic-acidosis","stem":"What is the primary mechanism for high anion gap metabolic acidosis in a patient with septic shock?","options":[{"id":"a","text":"Increased bicarbonate loss"},{"id":"b","text":"Increased lactic acid production"},{"id":"c","text":"Decreased renal acid excretion"},{"id":"d","text":"Increased chloride retention"}],"answerId":"b","explanation":"Lactic acidosis is the most common cause of high anion gap metabolic acidosis in septic patients due to tissue hypoperfusion.","kind":"mechanism","origin":"ai"},{"id":"high-anion-gap-metabolic-acidosis~ai-1","moduleId":"high-anion-gap-metabolic-acidosis","stem":"Which of the following conditions is most likely to cause a normal anion gap metabolic acidosis?","options":[{"id":"a","text":"Diabetic ketoacidosis"},{"id":"b","text":"Renal tubular acidosis"},{"id":"c","text":"Methanol poisoning"},{"id":"d","text":"Lactic acidosis"}],"answerId":"b","explanation":"Renal tubular acidosis leads to bicarbonate loss without an increase in unmeasured anions, resulting in a normal anion gap.","kind":"recall","origin":"ai"},{"id":"high-anion-gap-metabolic-acidosis~ai-2","moduleId":"high-anion-gap-metabolic-acidosis","stem":"A patient presents with high anion gap metabolic acidosis and a positive urine anion gap. What is the likely diagnosis?","options":[{"id":"a","text":"Diarrhea"},{"id":"b","text":"Diabetic ketoacidosis"},{"id":"c","text":"Renal tubular acidosis"},{"id":"d","text":"Uremia"}],"answerId":"c","explanation":"A positive urine anion gap indicates renal tubular acidosis, where the kidneys fail to excrete hydrogen ions effectively.","kind":"clinical","origin":"ai"},{"id":"high-anion-gap-metabolic-acidosis~ai-3","moduleId":"high-anion-gap-metabolic-acidosis","stem":"Which of the following is a key distinguishing feature of high anion gap metabolic acidosis?","options":[{"id":"a","text":"Increased bicarbonate levels"},{"id":"b","text":"Increased chloride levels"},{"id":"c","text":"Presence of unmeasured acids"},{"id":"d","text":"Decreased pH"}],"answerId":"c","explanation":"High anion gap metabolic acidosis is characterized by the presence of unmeasured acids, which consume bicarbonate.","kind":"trap","origin":"ai"},{"id":"high-anion-gap-metabolic-acidosis~ai-4","moduleId":"high-anion-gap-metabolic-acidosis","stem":"In a patient with suspected methanol poisoning, which additional test would be most useful to confirm the diagnosis?","options":[{"id":"a","text":"Urine pH"},{"id":"b","text":"Osmolar gap"},{"id":"c","text":"Serum bicarbonate"},{"id":"d","text":"Liver function tests"}],"answerId":"b","explanation":"The osmolar gap is elevated in methanol poisoning, helping to confirm the diagnosis alongside clinical findings.","kind":"mechanism","origin":"ai"},{"id":"high-anion-gap-metabolic-acidosis~ai-5","moduleId":"high-anion-gap-metabolic-acidosis","stem":"How does the delta ratio assist in diagnosing metabolic acidosis?","options":[{"id":"a","text":"It measures respiratory compensation"},{"id":"b","text":"It differentiates between types of acidosis"},{"id":"c","text":"It indicates the severity of acidosis"},{"id":"d","text":"It assesses renal function"}],"answerId":"b","explanation":"The delta ratio compares the change in anion gap to the change in bicarbonate, helping to identify mixed acid-base disorders.","kind":"mechanism","origin":"ai"},{"id":"high-anion-gap-metabolic-acidosis~ai-6","moduleId":"high-anion-gap-metabolic-acidosis","stem":"A patient with chronic diarrhea presents with metabolic acidosis. What would you expect their urine anion gap to be?","options":[{"id":"a","text":"Positive"},{"id":"b","text":"Negative"},{"id":"c","text":"Zero"},{"id":"d","text":"Variable"}],"answerId":"b","explanation":"A negative urine anion gap suggests that bicarbonate loss is due to gastrointestinal causes, such as diarrhea.","kind":"integration","linkedModuleIds":["acid-base-disorders"],"origin":"ai"},{"id":"high-anion-gap-metabolic-acidosis~ai-7","moduleId":"high-anion-gap-metabolic-acidosis","stem":"In a patient with high anion gap metabolic acidosis due to diabetic ketoacidosis, what compensatory mechanism is expected?","options":[{"id":"a","text":"Increased respiratory rate"},{"id":"b","text":"Decreased heart rate"},{"id":"c","text":"Increased renal bicarbonate reabsorption"},{"id":"d","text":"Decreased urine output"}],"answerId":"a","explanation":"In response to metabolic acidosis, the respiratory system compensates by increasing the respiratory rate to lower pCO2.","kind":"integration","linkedModuleIds":["acid-base-disorders-compensation"],"origin":"ai"}],"nephrotoxic-drugs":[{"id":"nephrotoxic-drugs~ai-0","moduleId":"nephrotoxic-drugs","stem":"What is the mechanism by which NSAIDs can lead to acute kidney injury in a dehydrated patient?","options":[{"id":"a","text":"Inhibition of tubular secretion"},{"id":"b","text":"Afferent arteriolar constriction"},{"id":"c","text":"Efferent arteriolar dilation"},{"id":"d","text":"Direct tubular toxicity"}],"answerId":"b","explanation":"NSAIDs inhibit vasodilatory prostaglandins, leading to afferent arteriolar constriction and reduced glomerular filtration rate (GFR) during dehydration.","kind":"mechanism","origin":"ai"},{"id":"nephrotoxic-drugs~ai-1","moduleId":"nephrotoxic-drugs","stem":"Which drug is known to cause pseudo-acute kidney injury by inhibiting tubular secretion of creatinine?","options":[{"id":"a","text":"Aminoglycosides"},{"id":"b","text":"Trimethoprim"},{"id":"c","text":"Amphotericin B"},{"id":"d","text":"Cisplatin"}],"answerId":"b","explanation":"Trimethoprim inhibits tubular secretion of creatinine, leading to a rise in serum creatinine without a true decrease in GFR, termed pseudo-AKI.","kind":"recall","origin":"ai"},{"id":"nephrotoxic-drugs~ai-2","moduleId":"nephrotoxic-drugs","stem":"A patient develops acute kidney injury after receiving iodinated contrast for imaging. What is the most likely mechanism?","options":[{"id":"a","text":"Direct tubular toxicity"},{"id":"b","text":"Acute interstitial nephritis"},{"id":"c","text":"Contrast-associated nephropathy"},{"id":"d","text":"Afferent arteriolar constriction"}],"answerId":"c","explanation":"Iodinated contrast can cause acute kidney injury through contrast-associated nephropathy, typically occurring within 48 hours of exposure.","kind":"recall","origin":"ai"},{"id":"nephrotoxic-drugs~ai-3","moduleId":"nephrotoxic-drugs","stem":"Which of the following drugs should be avoided in patients with a low GFR due to the risk of lactic acidosis?","options":[{"id":"a","text":"Metformin"},{"id":"b","text":"Digoxin"},{"id":"c","text":"Vancomycin"},{"id":"d","text":"Aminoglycosides"}],"answerId":"a","explanation":"Metformin is contraindicated in patients with low GFR due to the risk of lactic acidosis, as it is renally excreted.","kind":"recall","origin":"ai"},{"id":"nephrotoxic-drugs~ai-4","moduleId":"nephrotoxic-drugs","stem":"What is the primary reason for dose adjustment of renally-cleared drugs in patients with chronic kidney disease?","options":[{"id":"a","text":"Increased drug metabolism"},{"id":"b","text":"Decreased renal clearance"},{"id":"c","text":"Increased drug absorption"},{"id":"d","text":"Altered drug distribution"}],"answerId":"b","explanation":"In chronic kidney disease, renal clearance is decreased, necessitating dose adjustments for renally-cleared drugs to avoid toxicity.","kind":"mechanism","origin":"ai"},{"id":"nephrotoxic-drugs~ai-5","moduleId":"nephrotoxic-drugs","stem":"A patient presents with a rise in creatinine after starting trimethoprim. What is the most appropriate next step?","options":[{"id":"a","text":"Stop trimethoprim immediately"},{"id":"b","text":"Monitor renal function"},{"id":"c","text":"Increase fluid intake"},{"id":"d","text":"Switch to a different antibiotic"}],"answerId":"b","explanation":"Since trimethoprim can cause a rise in creatinine without true kidney injury (pseudo-AKI), monitoring renal function is appropriate before making further decisions.","kind":"trap","origin":"ai"},{"id":"nephrotoxic-drugs~ai-6","moduleId":"nephrotoxic-drugs","stem":"How does acute interstitial nephritis relate to nephrotoxic drugs?","options":[{"id":"a","text":"It is caused by direct tubular injury"},{"id":"b","text":"It is a hypersensitivity reaction to certain medications"},{"id":"c","text":"It results from obstruction of renal tubules"},{"id":"d","text":"It is a consequence of volume depletion"}],"answerId":"b","explanation":"Acute interstitial nephritis is often a hypersensitivity reaction to medications such as antibiotics and NSAIDs, leading to kidney injury.","kind":"integration","linkedModuleIds":["acute-interstitial-nephritis"],"origin":"ai"},{"id":"nephrotoxic-drugs~ai-7","moduleId":"nephrotoxic-drugs","stem":"What is a common clinical finding in acute kidney injury due to the 'triple whammy' of NSAIDs, ACE inhibitors, and diuretics?","options":[{"id":"a","text":"Oliguria"},{"id":"b","text":"Non-oliguric AKI"},{"id":"c","text":"Hyperkalemia"},{"id":"d","text":"Metabolic acidosis"}],"answerId":"b","explanation":"The 'triple whammy' often results in non-oliguric acute kidney injury due to combined effects on renal hemodynamics.","kind":"integration","linkedModuleIds":["aki-prerenal-intrinsic-postrenal"],"origin":"ai"}],"enveloped-rna-viruses-orthomyxo-paramyxo":[{"id":"enveloped-rna-viruses-orthomyxo-paramyxo~ai-0","moduleId":"enveloped-rna-viruses-orthomyxo-paramyxo","stem":"What is the primary mechanism by which antigenic drift occurs in influenza viruses?","options":[{"id":"a","text":"Reassortment of genome segments"},{"id":"b","text":"Gradual accumulation of point mutations"},{"id":"c","text":"Inhibition of neuraminidase"},{"id":"d","text":"Mutation of viral envelope proteins"}],"answerId":"b","explanation":"Antigenic drift in influenza is caused by the gradual accumulation of point mutations in the hemagglutinin and neuraminidase proteins, leading to seasonal epidemics.","kind":"mechanism","origin":"ai"},{"id":"enveloped-rna-viruses-orthomyxo-paramyxo~ai-1","moduleId":"enveloped-rna-viruses-orthomyxo-paramyxo","stem":"Which of the following is a key feature of measles infection?","options":[{"id":"a","text":"Barking cough"},{"id":"b","text":"Koplik spots"},{"id":"c","text":"Syncytia formation"},{"id":"d","text":"Parotitis"}],"answerId":"b","explanation":"Koplik spots are pathognomonic for measles and appear before the characteristic maculopapular rash.","kind":"recall","origin":"ai"},{"id":"enveloped-rna-viruses-orthomyxo-paramyxo~ai-2","moduleId":"enveloped-rna-viruses-orthomyxo-paramyxo","stem":"A child presents with a barking cough and stridor. Which virus is most likely responsible?","options":[{"id":"a","text":"RSV"},{"id":"b","text":"Influenza"},{"id":"c","text":"Parainfluenza"},{"id":"d","text":"Measles"}],"answerId":"c","explanation":"Parainfluenza virus is the most common cause of croup, characterized by barking cough and stridor.","kind":"clinical","origin":"ai"},{"id":"enveloped-rna-viruses-orthomyxo-paramyxo~ai-3","moduleId":"enveloped-rna-viruses-orthomyxo-paramyxo","stem":"What complication is commonly associated with influenza infection?","options":[{"id":"a","text":"Subacute sclerosing panencephalitis"},{"id":"b","text":"Secondary bacterial pneumonia"},{"id":"c","text":"Bronchiolitis"},{"id":"d","text":"Croup"}],"answerId":"b","explanation":"Secondary bacterial pneumonia, often caused by S. aureus or pneumococcus, is a common complication following influenza infection.","kind":"trap","origin":"ai"},{"id":"enveloped-rna-viruses-orthomyxo-paramyxo~ai-4","moduleId":"enveloped-rna-viruses-orthomyxo-paramyxo","stem":"Which of the following statements correctly differentiates antigenic drift from antigenic shift in influenza viruses?","options":[{"id":"a","text":"Drift is caused by reassortment; shift is due to point mutations."},{"id":"b","text":"Drift leads to pandemics; shift causes seasonal epidemics."},{"id":"c","text":"Drift involves minor mutations; shift involves reassortment of genome segments."},{"id":"d","text":"Drift occurs in non-segmented viruses; shift occurs in segmented viruses."}],"answerId":"c","explanation":"Antigenic drift involves minor point mutations leading to seasonal epidemics, while antigenic shift involves reassortment of genome segments, leading to pandemics.","kind":"trap","origin":"ai"},{"id":"enveloped-rna-viruses-orthomyxo-paramyxo~ai-5","moduleId":"enveloped-rna-viruses-orthomyxo-paramyxo","stem":"A 2-year-old child with a history of wheezing presents with respiratory distress. Histological examination shows multinucleate syncytia. What is the most likely diagnosis?","options":[{"id":"a","text":"Croup"},{"id":"b","text":"Measles"},{"id":"c","text":"RSV infection"},{"id":"d","text":"Influenza"}],"answerId":"c","explanation":"The presence of multinucleate syncytia on histology is characteristic of respiratory syncytial virus (RSV) infection, which causes bronchiolitis.","kind":"recall","origin":"ai"},{"id":"enveloped-rna-viruses-orthomyxo-paramyxo~ai-6","moduleId":"enveloped-rna-viruses-orthomyxo-paramyxo","stem":"How does the mechanism of reassortment in influenza viruses contribute to the emergence of new pandemic strains?","options":[{"id":"a","text":"It allows for the gradual accumulation of mutations."},{"id":"b","text":"It leads to the exchange of entire genome segments between different strains."},{"id":"c","text":"It enhances the stability of the viral genome."},{"id":"d","text":"It increases the virulence of the virus."}],"answerId":"b","explanation":"Reassortment allows for the exchange of entire genome segments between different influenza strains, resulting in new HA/NA proteins that the population has no immunity against, leading to pandemics.","kind":"integration","linkedModuleIds":["influenza-covid-pneumonia"],"origin":"ai"},{"id":"enveloped-rna-viruses-orthomyxo-paramyxo~ai-7","moduleId":"enveloped-rna-viruses-orthomyxo-paramyxo","stem":"Which respiratory virus is primarily responsible for causing bronchiolitis in infants and is often treated with monoclonal antibodies for prevention?","options":[{"id":"a","text":"Influenza"},{"id":"b","text":"Parainfluenza"},{"id":"c","text":"RSV"},{"id":"d","text":"Measles"}],"answerId":"c","explanation":"Respiratory syncytial virus (RSV) is the leading cause of bronchiolitis in infants, and palivizumab is used for prophylaxis in high-risk infants.","kind":"integration","linkedModuleIds":["other-respiratory-viruses"],"origin":"ai"}],"potassium-disorders":[{"id":"potassium-disorders~ai-0","moduleId":"potassium-disorders","stem":"Which of the following is a common cause of hyperkalaemia?","options":[{"id":"a","text":"Renal failure"},{"id":"b","text":"Hypomagnesaemia"},{"id":"c","text":"Diuretic use"},{"id":"d","text":"Alkalosis"}],"answerId":"a","explanation":"Renal failure leads to reduced potassium excretion, which is a primary cause of hyperkalaemia.","kind":"recall","origin":"ai"},{"id":"potassium-disorders~ai-1","moduleId":"potassium-disorders","stem":"What is the first step in the emergency management of severe hyperkalaemia?","options":[{"id":"a","text":"Administer insulin"},{"id":"b","text":"Give IV calcium"},{"id":"c","text":"Initiate dialysis"},{"id":"d","text":"Administer sodium bicarbonate"}],"answerId":"b","explanation":"IV calcium is given first to stabilize the myocardium and prevent arrhythmias in severe hyperkalaemia.","kind":"mechanism","origin":"ai"},{"id":"potassium-disorders~ai-2","moduleId":"potassium-disorders","stem":"A patient with hypokalaemia presents with U waves on ECG. What is the most likely cause?","options":[{"id":"a","text":"Rhabdomyolysis"},{"id":"b","text":"Diuretic use"},{"id":"c","text":"Acidosis"},{"id":"d","text":"Insulin overdose"}],"answerId":"b","explanation":"Diuretic use is a common cause of hypokalaemia and can lead to U waves on ECG.","kind":"recall","origin":"ai"},{"id":"potassium-disorders~ai-3","moduleId":"potassium-disorders","stem":"Which of the following statements about IV calcium in hyperkalaemia is true?","options":[{"id":"a","text":"It lowers serum potassium levels"},{"id":"b","text":"It stabilizes cardiac membranes"},{"id":"c","text":"It is the only treatment needed"},{"id":"d","text":"It causes potassium to shift into cells"}],"answerId":"b","explanation":"IV calcium stabilizes cardiac membranes but does not lower serum potassium levels; it is a protective measure.","kind":"trap","origin":"ai"},{"id":"potassium-disorders~ai-4","moduleId":"potassium-disorders","stem":"A patient with chronic kidney disease is on an ACE inhibitor and spironolactone. What is the expected finding?","options":[{"id":"a","text":"Hypokalaemia"},{"id":"b","text":"Normal potassium levels"},{"id":"c","text":"Hyperkalaemia"},{"id":"d","text":"Hypomagnesaemia"}],"answerId":"c","explanation":"The combination of an ACE inhibitor and a potassium-sparing diuretic like spironolactone can lead to hyperkalaemia due to reduced renal excretion.","kind":"recall","origin":"ai"},{"id":"potassium-disorders~ai-5","moduleId":"potassium-disorders","stem":"In a patient with hypokalaemia that does not correct with potassium replacement, what should be checked?","options":[{"id":"a","text":"Calcium levels"},{"id":"b","text":"Sodium levels"},{"id":"c","text":"Magnesium levels"},{"id":"d","text":"Chloride levels"}],"answerId":"c","explanation":"Hypomagnesaemia can prevent the correction of hypokalaemia, so magnesium levels should be checked.","kind":"clinical","origin":"ai"},{"id":"potassium-disorders~ai-6","moduleId":"potassium-disorders","stem":"How does metabolic acidosis affect serum potassium levels?","options":[{"id":"a","text":"It decreases potassium levels"},{"id":"b","text":"It has no effect"},{"id":"c","text":"It increases potassium levels"},{"id":"d","text":"It causes potassium to shift into cells"}],"answerId":"c","explanation":"Metabolic acidosis causes potassium to shift out of cells, leading to increased serum potassium levels.","kind":"integration","linkedModuleIds":["high-anion-gap-metabolic-acidosis"],"origin":"ai"},{"id":"potassium-disorders~ai-7","moduleId":"potassium-disorders","stem":"Which diuretic class is most likely to cause hypokalaemia?","options":[{"id":"a","text":"Potassium-sparing diuretics"},{"id":"b","text":"Loop diuretics"},{"id":"c","text":"Osmotic diuretics"},{"id":"d","text":"Carbonic anhydrase inhibitors"}],"answerId":"b","explanation":"Loop diuretics are well-known for causing hypokalaemia due to increased renal potassium loss.","kind":"integration","linkedModuleIds":["loop-thiazide-diuretics"],"origin":"ai"}],"nonenveloped-rna-viruses":[{"id":"nonenveloped-rna-viruses~ai-0","moduleId":"nonenveloped-rna-viruses","stem":"Which of the following viruses is the leading cause of severe infantile diarrhea worldwide?","options":[{"id":"a","text":"Norovirus"},{"id":"b","text":"Hepatitis A"},{"id":"c","text":"Rotavirus"},{"id":"d","text":"Coxsackievirus"}],"answerId":"c","explanation":"Rotavirus is recognized as the leading cause of severe diarrhea in infants, and it is preventable by vaccination.","kind":"recall","origin":"ai"},{"id":"nonenveloped-rna-viruses~ai-1","moduleId":"nonenveloped-rna-viruses","stem":"What is the primary mode of transmission for non-enveloped RNA viruses?","options":[{"id":"a","text":"Airborne droplets"},{"id":"b","text":"Vector-borne"},{"id":"c","text":"Fecal-oral"},{"id":"d","text":"Direct contact"}],"answerId":"c","explanation":"Non-enveloped RNA viruses are hardy and primarily spread via the fecal-oral route.","kind":"mechanism","origin":"ai"},{"id":"nonenveloped-rna-viruses~ai-2","moduleId":"nonenveloped-rna-viruses","stem":"A child presents with acute flaccid paralysis. Which virus is most likely responsible?","options":[{"id":"a","text":"Coxsackievirus"},{"id":"b","text":"Poliovirus"},{"id":"c","text":"Norovirus"},{"id":"d","text":"Hepatitis A"}],"answerId":"b","explanation":"Poliovirus is known to cause acute flaccid paralysis, especially in unvaccinated individuals.","kind":"recall","origin":"ai"},{"id":"nonenveloped-rna-viruses~ai-3","moduleId":"nonenveloped-rna-viruses","stem":"Which of the following statements about hepatitis A and E is correct?","options":[{"id":"a","text":"Both can cause chronic infection"},{"id":"b","text":"Both are transmitted via blood"},{"id":"c","text":"Both cause acute self-limiting hepatitis"},{"id":"d","text":"Both are vaccine-preventable"}],"answerId":"c","explanation":"Hepatitis A and E are enterically transmitted and cause acute self-limiting hepatitis without chronic infection.","kind":"trap","origin":"ai"},{"id":"nonenveloped-rna-viruses~ai-4","moduleId":"nonenveloped-rna-viruses","stem":"A patient develops explosive vomiting and diarrhea after a cruise. Which virus is most likely responsible?","options":[{"id":"a","text":"Hepatitis E"},{"id":"b","text":"Norovirus"},{"id":"c","text":"Rotavirus"},{"id":"d","text":"Poliovirus"}],"answerId":"b","explanation":"Norovirus is the leading cause of gastroenteritis outbreaks, particularly in closed environments like cruise ships.","kind":"recall","origin":"ai"},{"id":"nonenveloped-rna-viruses~ai-5","moduleId":"nonenveloped-rna-viruses","stem":"Which of the following viruses is associated with high mortality in pregnant women?","options":[{"id":"a","text":"Hepatitis A"},{"id":"b","text":"Hepatitis E"},{"id":"c","text":"Rotavirus"},{"id":"d","text":"Coxsackievirus"}],"answerId":"b","explanation":"Hepatitis E is known to have high mortality rates in pregnant women, especially during waterborne outbreaks.","kind":"recall","origin":"ai"},{"id":"nonenveloped-rna-viruses~ai-6","moduleId":"nonenveloped-rna-viruses","stem":"How does the mechanism of transmission for rotavirus differ from that of rhinovirus?","options":[{"id":"a","text":"Rotavirus is airborne, rhinovirus is fecal-oral"},{"id":"b","text":"Both are fecal-oral, but rotavirus is more severe in infants"},{"id":"c","text":"Rhinovirus is vaccine-preventable, rotavirus is not"},{"id":"d","text":"Rotavirus is bloodborne, rhinovirus is fecal-oral"}],"answerId":"b","explanation":"Both viruses are transmitted via fecal-oral route, but rotavirus causes more severe disease in infants.","kind":"integration","linkedModuleIds":["viral-gastroenteritis"],"origin":"ai"},{"id":"nonenveloped-rna-viruses~ai-7","moduleId":"nonenveloped-rna-viruses","stem":"Which of the following best describes the relationship between non-enveloped RNA viruses and hygiene practices?","options":[{"id":"a","text":"They are easily killed by alcohol-based sanitizers"},{"id":"b","text":"They persist on surfaces and require soap and water for effective removal"},{"id":"c","text":"They are only transmitted through direct contact"},{"id":"d","text":"They are less infectious than enveloped viruses"}],"answerId":"b","explanation":"Non-enveloped RNA viruses are hardy and persist on surfaces, making soap and water more effective than alcohol-based sanitizers.","kind":"integration","linkedModuleIds":["virology-principles-classification"],"origin":"ai"}],"potassium-sparing-osmotic-diuretics":[{"id":"potassium-sparing-osmotic-diuretics~ai-0","moduleId":"potassium-sparing-osmotic-diuretics","stem":"What is the primary mechanism of action of spironolactone?","options":[{"id":"a","text":"Inhibition of carbonic anhydrase"},{"id":"b","text":"Blockade of epithelial sodium channels"},{"id":"c","text":"Aldosterone receptor antagonism"},{"id":"d","text":"Osmotic diuresis"}],"answerId":"c","explanation":"Spironolactone acts as an aldosterone antagonist, leading to potassium retention and sodium excretion.","kind":"mechanism","origin":"ai"},{"id":"potassium-sparing-osmotic-diuretics~ai-1","moduleId":"potassium-sparing-osmotic-diuretics","stem":"Which electrolyte disturbance is most commonly associated with potassium-sparing diuretics?","options":[{"id":"a","text":"Hypokalemia"},{"id":"b","text":"Hyperkalemia"},{"id":"c","text":"Hyponatremia"},{"id":"d","text":"Hypernatremia"}],"answerId":"b","explanation":"Potassium-sparing diuretics, such as spironolactone, retain potassium, leading to hyperkalemia.","kind":"recall","origin":"ai"},{"id":"potassium-sparing-osmotic-diuretics~ai-2","moduleId":"potassium-sparing-osmotic-diuretics","stem":"A patient develops gynecomastia while on a potassium-sparing diuretic. Which drug is most likely responsible?","options":[{"id":"a","text":"Amiloride"},{"id":"b","text":"Eplerenone"},{"id":"c","text":"Spironolactone"},{"id":"d","text":"Acetazolamide"}],"answerId":"c","explanation":"Spironolactone has anti-androgen effects that can lead to gynecomastia.","kind":"clinical","origin":"ai"},{"id":"potassium-sparing-osmotic-diuretics~ai-3","moduleId":"potassium-sparing-osmotic-diuretics","stem":"What is the clinical use of mannitol?","options":[{"id":"a","text":"To treat glaucoma"},{"id":"b","text":"To reduce intracranial pressure"},{"id":"c","text":"To prevent hypokalemia"},{"id":"d","text":"To induce metabolic acidosis"}],"answerId":"b","explanation":"Mannitol is used to reduce raised intracranial pressure through osmotic diuresis.","kind":"recall","origin":"ai"},{"id":"potassium-sparing-osmotic-diuretics~ai-4","moduleId":"potassium-sparing-osmotic-diuretics","stem":"Combining spironolactone with which of the following medications poses the greatest risk of hyperkalemia?","options":[{"id":"a","text":"Thiazide diuretics"},{"id":"b","text":"ACE inhibitors"},{"id":"c","text":"Loop diuretics"},{"id":"d","text":"Calcium channel blockers"}],"answerId":"b","explanation":"ACE inhibitors also increase potassium levels, leading to a significant risk of hyperkalemia when combined with spironolactone.","kind":"trap","origin":"ai"},{"id":"potassium-sparing-osmotic-diuretics~ai-5","moduleId":"potassium-sparing-osmotic-diuretics","stem":"Which diuretic class is primarily used to induce metabolic acidosis?","options":[{"id":"a","text":"Loop diuretics"},{"id":"b","text":"Thiazide diuretics"},{"id":"c","text":"Potassium-sparing diuretics"},{"id":"d","text":"Carbonic anhydrase inhibitors"}],"answerId":"d","explanation":"Carbonic anhydrase inhibitors like acetazolamide cause bicarbonate loss, leading to metabolic acidosis.","kind":"recall","origin":"ai"},{"id":"potassium-sparing-osmotic-diuretics~ai-6","moduleId":"potassium-sparing-osmotic-diuretics","stem":"How does the action of potassium-sparing diuretics relate to renal potassium handling?","options":[{"id":"a","text":"They increase potassium excretion"},{"id":"b","text":"They enhance potassium reabsorption"},{"id":"c","text":"They retain potassium"},{"id":"d","text":"They have no effect on potassium handling"}],"answerId":"c","explanation":"Potassium-sparing diuretics retain potassium by antagonizing aldosterone or blocking sodium channels in the collecting duct.","kind":"integration","linkedModuleIds":["renal-potassium-handling"],"origin":"ai"},{"id":"potassium-sparing-osmotic-diuretics~ai-7","moduleId":"potassium-sparing-osmotic-diuretics","stem":"Which diuretic class can be used in conjunction with potassium-sparing diuretics to enhance diuresis without causing hypokalemia?","options":[{"id":"a","text":"Loop diuretics"},{"id":"b","text":"Thiazide diuretics"},{"id":"c","text":"Osmotic diuretics"},{"id":"d","text":"Carbonic anhydrase inhibitors"}],"answerId":"b","explanation":"Thiazide diuretics can be combined with potassium-sparing diuretics to enhance diuresis while minimizing the risk of hypokalemia.","kind":"integration","linkedModuleIds":["loop-thiazide-diuretics"],"origin":"ai"}],"sodium-water-disorders":[{"id":"sodium-water-disorders~ai-0","moduleId":"sodium-water-disorders","stem":"What is the primary mechanism leading to hyponatraemia in SIADH?","options":[{"id":"a","text":"Excess sodium loss"},{"id":"b","text":"Excess water retention"},{"id":"c","text":"Inadequate sodium intake"},{"id":"d","text":"Increased renal sodium excretion"}],"answerId":"b","explanation":"In SIADH, there is excess water retention leading to dilutional hyponatraemia despite normal or increased sodium levels.","kind":"mechanism","origin":"ai"},{"id":"sodium-water-disorders~ai-1","moduleId":"sodium-water-disorders","stem":"A patient presents with euvolaemic hyponatraemia and urine sodium concentration >30 mEq/L. What is the most likely diagnosis?","options":[{"id":"a","text":"Heart failure"},{"id":"b","text":"Cirrhosis"},{"id":"c","text":"SIADH"},{"id":"d","text":"Adrenal insufficiency"}],"answerId":"c","explanation":"The combination of euvolaemia, low serum osmolality, and high urine sodium concentration is characteristic of SIADH.","kind":"clinical","origin":"ai"},{"id":"sodium-water-disorders~ai-2","moduleId":"sodium-water-disorders","stem":"Which of the following is a potential complication of rapid correction of chronic hyponatraemia?","options":[{"id":"a","text":"Cerebral edema"},{"id":"b","text":"Osmotic demyelination syndrome"},{"id":"c","text":"Pulmonary edema"},{"id":"d","text":"Cardiac arrhythmias"}],"answerId":"b","explanation":"Rapid correction of chronic hyponatraemia can lead to osmotic demyelination syndrome due to the rapid shift of water out of brain cells.","kind":"trap","origin":"ai"},{"id":"sodium-water-disorders~ai-3","moduleId":"sodium-water-disorders","stem":"What is the most common cause of hypernatraemia?","options":[{"id":"a","text":"Excess sodium intake"},{"id":"b","text":"Water deficit"},{"id":"c","text":"Increased renal sodium retention"},{"id":"d","text":"Hyperaldosteronism"}],"answerId":"b","explanation":"Hypernatraemia typically results from a water deficit, often due to inadequate access to water or excessive water loss.","kind":"recall","origin":"ai"},{"id":"sodium-water-disorders~ai-4","moduleId":"sodium-water-disorders","stem":"A patient with diabetes insipidus presents with hypernatraemia and large volumes of dilute urine. What is the underlying mechanism?","options":[{"id":"a","text":"Increased ADH secretion"},{"id":"b","text":"ADH resistance in the kidneys"},{"id":"c","text":"Excessive water intake"},{"id":"d","text":"Increased sodium retention"}],"answerId":"b","explanation":"In diabetes insipidus, there is either a deficiency of ADH (central) or resistance to its action (nephrogenic), leading to dilute urine and hypernatraemia.","kind":"mechanism","origin":"ai"},{"id":"sodium-water-disorders~ai-5","moduleId":"sodium-water-disorders","stem":"Which of the following findings would suggest hypervolaemic hyponatraemia?","options":[{"id":"a","text":"Low urine sodium"},{"id":"b","text":"Oedema"},{"id":"c","text":"Low serum osmolality"},{"id":"d","text":"High urine osmolality"}],"answerId":"b","explanation":"Oedema is a key finding in hypervolaemic hyponatraemia, often seen in conditions like heart failure or cirrhosis.","kind":"recall","origin":"ai"},{"id":"sodium-water-disorders~ai-6","moduleId":"sodium-water-disorders","stem":"How does the management of chronic hyponatraemia differ from acute symptomatic hyponatraemia?","options":[{"id":"a","text":"Both should be corrected rapidly"},{"id":"b","text":"Chronic should be corrected slowly, acute can be rapid"},{"id":"c","text":"Both should be corrected slowly"},{"id":"d","text":"Acute should be corrected with diuretics"}],"answerId":"b","explanation":"Chronic hyponatraemia must be corrected slowly to prevent osmotic demyelination, while acute symptomatic cases may require rapid correction.","kind":"trap","origin":"ai"},{"id":"sodium-water-disorders~ai-7","moduleId":"sodium-water-disorders","stem":"In a patient with hypernatraemia due to diabetes insipidus, which of the following treatments is appropriate?","options":[{"id":"a","text":"Fluid restriction"},{"id":"b","text":"Desmopressin"},{"id":"c","text":"Hypertonic saline"},{"id":"d","text":"Sodium supplementation"}],"answerId":"b","explanation":"Desmopressin is used to treat central diabetes insipidus by replacing the deficient ADH.","kind":"integration","linkedModuleIds":["posterior-pituitary-syndromes"],"origin":"ai"},{"id":"sodium-water-disorders~ai-8","moduleId":"sodium-water-disorders","stem":"How does the management of euvolaemic hyponatraemia due to SIADH differ from hypervolaemic hyponatraemia?","options":[{"id":"a","text":"Both require fluid restriction"},{"id":"b","text":"SIADH requires fluid restriction, hypervolaemia requires saline"},{"id":"c","text":"Both require saline"},{"id":"d","text":"Both require diuretics"}],"answerId":"b","explanation":"Management of SIADH involves fluid restriction, while hypervolaemic hyponatraemia often requires saline and treatment of the underlying cause.","kind":"integration","linkedModuleIds":["sodium-balance-ecf-volume"],"origin":"ai"}],"loop-thiazide-diuretics":[{"id":"loop-thiazide-diuretics~ai-0","moduleId":"loop-thiazide-diuretics","stem":"Which diuretic class primarily acts on the thick ascending limb of the loop of Henle?","options":[{"id":"a","text":"Thiazides"},{"id":"b","text":"Potassium-sparing diuretics"},{"id":"c","text":"Loop diuretics"},{"id":"d","text":"Carbonic anhydrase inhibitors"}],"answerId":"c","explanation":"Loop diuretics, such as furosemide, act on the NKCC2 cotransporter in the thick ascending limb.","kind":"recall","origin":"ai"},{"id":"loop-thiazide-diuretics~ai-1","moduleId":"loop-thiazide-diuretics","stem":"What is the primary mechanism by which thiazide diuretics lower blood pressure?","options":[{"id":"a","text":"Increased renal blood flow"},{"id":"b","text":"Decreased sodium reabsorption in the distal convoluted tubule"},{"id":"c","text":"Increased potassium retention"},{"id":"d","text":"Inhibition of aldosterone"}],"answerId":"b","explanation":"Thiazide diuretics decrease sodium reabsorption in the distal convoluted tubule, leading to reduced blood volume and lower blood pressure.","kind":"mechanism","origin":"ai"},{"id":"loop-thiazide-diuretics~ai-2","moduleId":"loop-thiazide-diuretics","stem":"A patient on loop diuretics presents with hypokalemia and metabolic alkalosis. What is the underlying mechanism?","options":[{"id":"a","text":"Increased renal potassium reabsorption"},{"id":"b","text":"Increased distal sodium delivery leading to potassium secretion"},{"id":"c","text":"Decreased hydrogen ion secretion"},{"id":"d","text":"Increased calcium reabsorption"}],"answerId":"b","explanation":"Loop diuretics increase distal sodium delivery, which drives potassium and hydrogen ion secretion, causing hypokalemia and metabolic alkalosis.","kind":"clinical","origin":"ai"},{"id":"loop-thiazide-diuretics~ai-3","moduleId":"loop-thiazide-diuretics","stem":"Which of the following is a common adverse effect of thiazide diuretics?","options":[{"id":"a","text":"Ototoxicity"},{"id":"b","text":"Hyperuricaemia"},{"id":"c","text":"Hypocalcaemia"},{"id":"d","text":"Metabolic acidosis"}],"answerId":"b","explanation":"Thiazide diuretics can cause hyperuricaemia, along with other side effects such as hyperglycaemia and hyponatraemia.","kind":"trap","origin":"ai"},{"id":"loop-thiazide-diuretics~ai-4","moduleId":"loop-thiazide-diuretics","stem":"In which condition would you choose a loop diuretic over a thiazide?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Mild edema"},{"id":"c","text":"Heart failure with fluid overload"},{"id":"d","text":"Calcium stone prevention"}],"answerId":"c","explanation":"Loop diuretics are preferred in cases of significant fluid overload, such as heart failure, due to their potency.","kind":"clinical","origin":"ai"},{"id":"loop-thiazide-diuretics~ai-5","moduleId":"loop-thiazide-diuretics","stem":"Which diuretic class is contraindicated in patients with low GFR due to loss of efficacy?","options":[{"id":"a","text":"Loop diuretics"},{"id":"b","text":"Thiazide diuretics"},{"id":"c","text":"Potassium-sparing diuretics"},{"id":"d","text":"Osmotic diuretics"}],"answerId":"b","explanation":"Thiazide diuretics lose efficacy at low GFR, while loop diuretics remain effective.","kind":"trap","origin":"ai"},{"id":"loop-thiazide-diuretics~ai-6","moduleId":"loop-thiazide-diuretics","stem":"How do loop diuretics affect calcium levels in the urine?","options":[{"id":"a","text":"Increase urinary calcium excretion"},{"id":"b","text":"Decrease urinary calcium excretion"},{"id":"c","text":"Have no effect on urinary calcium"},{"id":"d","text":"Increase serum calcium levels"}],"answerId":"a","explanation":"Loop diuretics increase urinary calcium excretion by abolishing the lumen-positive potential that drives calcium reabsorption.","kind":"integration","linkedModuleIds":["potassium-disorders"],"origin":"ai"},{"id":"loop-thiazide-diuretics~ai-7","moduleId":"loop-thiazide-diuretics","stem":"A patient with recurrent calcium stones is prescribed a diuretic. Which class should be used?","options":[{"id":"a","text":"Loop diuretics"},{"id":"b","text":"Thiazide diuretics"},{"id":"c","text":"Potassium-sparing diuretics"},{"id":"d","text":"Carbonic anhydrase inhibitors"}],"answerId":"b","explanation":"Thiazide diuretics decrease urinary calcium excretion, making them beneficial for preventing calcium stones.","kind":"integration","linkedModuleIds":["diuretics-pharmacology"],"origin":"ai"}],"retroviruses-hiv":[{"id":"retroviruses-hiv~ai-0","moduleId":"retroviruses-hiv","stem":"What is the primary mechanism by which HIV causes immunodeficiency?","options":[{"id":"a","text":"Inhibition of CD8+ T-cells"},{"id":"b","text":"Destruction of CD4+ T-cells"},{"id":"c","text":"Direct infection of B-cells"},{"id":"d","text":"Induction of autoimmunity"}],"answerId":"b","explanation":"HIV primarily infects and depletes CD4+ T-helper cells, leading to progressive immunodeficiency.","kind":"mechanism","origin":"ai"},{"id":"retroviruses-hiv~ai-1","moduleId":"retroviruses-hiv","stem":"Which of the following is a hallmark clinical finding in AIDS?","options":[{"id":"a","text":"Elevated CD4+ T-cell count"},{"id":"b","text":"Opportunistic infections"},{"id":"c","text":"Acute respiratory distress"},{"id":"d","text":"Chronic cough"}],"answerId":"b","explanation":"Opportunistic infections occur when CD4+ T-cell counts fall below 200 cells/mm³, indicating AIDS.","kind":"recall","origin":"ai"},{"id":"retroviruses-hiv~ai-2","moduleId":"retroviruses-hiv","stem":"What is the role of reverse transcriptase in HIV?","options":[{"id":"a","text":"Transcribes viral RNA into RNA"},{"id":"b","text":"Integrates viral DNA into host genome"},{"id":"c","text":"Transcribes viral RNA into DNA"},{"id":"d","text":"Replicates viral RNA"}],"answerId":"c","explanation":"Reverse transcriptase converts the viral RNA genome into DNA, which is then integrated into the host genome.","kind":"mechanism","origin":"ai"},{"id":"retroviruses-hiv~ai-3","moduleId":"retroviruses-hiv","stem":"Why does HIV persist in the body despite treatment?","options":[{"id":"a","text":"Strong immune response clears the virus"},{"id":"b","text":"Effective drugs eliminate all infected cells"},{"id":"c","text":"Integration into the host genome creates a latent reservoir"},{"id":"d","text":"Viral mutations allow escape from immune detection"}],"answerId":"c","explanation":"HIV integrates its RNA into the host genome as a latent provirus, creating a reservoir that is not eliminated by current therapies.","kind":"trap","origin":"ai"},{"id":"retroviruses-hiv~ai-4","moduleId":"retroviruses-hiv","stem":"Which test is most appropriate for diagnosing acute HIV infection?","options":[{"id":"a","text":"CD4 count"},{"id":"b","text":"Viral load"},{"id":"c","text":"Western blot"},{"id":"d","text":"4th-generation antibody/antigen test"}],"answerId":"d","explanation":"The 4th-generation test detects both antibodies and the p24 antigen, making it suitable for diagnosing acute HIV infection.","kind":"recall","origin":"ai"},{"id":"retroviruses-hiv~ai-5","moduleId":"retroviruses-hiv","stem":"A patient with HIV presents with a CD4 count of 150 cells/mm³ and develops pneumonia. Which organism is most likely responsible?","options":[{"id":"a","text":"Streptococcus pneumoniae"},{"id":"b","text":"Pneumocystis jirovecii"},{"id":"c","text":"Mycobacterium tuberculosis"},{"id":"d","text":"Cryptococcus neoformans"}],"answerId":"b","explanation":"Pneumocystis pneumonia is an opportunistic infection commonly seen in patients with CD4 counts below 200 cells/mm³.","kind":"clinical","origin":"ai"},{"id":"retroviruses-hiv~ai-6","moduleId":"retroviruses-hiv","stem":"How does the mechanism of HIV relate to the principles of virology?","options":[{"id":"a","text":"HIV is a DNA virus that integrates into host DNA"},{"id":"b","text":"HIV is a retrovirus that uses reverse transcription"},{"id":"c","text":"HIV replicates solely in B-cells"},{"id":"d","text":"HIV is transmitted only through blood"}],"answerId":"b","explanation":"HIV is a retrovirus that utilizes reverse transcription to convert its RNA genome into DNA, which is then integrated into the host genome.","kind":"integration","linkedModuleIds":["virology-principles-classification"],"origin":"ai"},{"id":"retroviruses-hiv~ai-7","moduleId":"retroviruses-hiv","stem":"What is the significance of combination antiretroviral therapy in HIV management?","options":[{"id":"a","text":"It cures HIV infection"},{"id":"b","text":"It prevents opportunistic infections"},{"id":"c","text":"It reduces viral load and prevents resistance"},{"id":"d","text":"It increases CD4+ T-cell counts"}],"answerId":"c","explanation":"Combination therapy reduces viral load and minimizes the risk of drug resistance, which is crucial for effective long-term management of HIV.","kind":"integration","linkedModuleIds":["hiv-antiretroviral-therapy"],"origin":"ai"}],"virology-principles-classification":[{"id":"virology-principles-classification~ai-0","moduleId":"virology-principles-classification","stem":"Which of the following statements about enveloped viruses is true?","options":[{"id":"a","text":"They are more stable in the environment than naked viruses."},{"id":"b","text":"They can survive in the gastrointestinal tract."},{"id":"c","text":"They are easily inactivated by detergents and alcohol."},{"id":"d","text":"They spread primarily via faecal-oral routes."}],"answerId":"c","explanation":"Enveloped viruses are fragile and easily inactivated by detergents and alcohol due to their lipid envelope.","kind":"trap","origin":"ai"},{"id":"virology-principles-classification~ai-1","moduleId":"virology-principles-classification","stem":"What is the primary reason that +ssRNA viruses can be translated directly into proteins?","options":[{"id":"a","text":"They carry their own polymerase."},{"id":"b","text":"They are immediately recognized as mRNA by the host ribosomes."},{"id":"c","text":"They replicate in the nucleus."},{"id":"d","text":"They have a helical capsid structure."}],"answerId":"b","explanation":"+ssRNA viruses can be directly translated into proteins because they are recognized as mRNA by the host's ribosomes.","kind":"mechanism","origin":"ai"},{"id":"virology-principles-classification~ai-2","moduleId":"virology-principles-classification","stem":"Which virus type is most likely to be transmitted via contaminated water?","options":[{"id":"a","text":"Enveloped viruses"},{"id":"b","text":"Naked viruses"},{"id":"c","text":"Retroviruses"},{"id":"d","text":"dsDNA viruses"}],"answerId":"b","explanation":"Naked viruses are hardy and can survive in the gastrointestinal tract, making them likely to be transmitted via contaminated water.","kind":"clinical","origin":"ai"},{"id":"virology-principles-classification~ai-3","moduleId":"virology-principles-classification","stem":"What is the Baltimore classification of a virus with a -ssRNA genome?","options":[{"id":"a","text":"dsDNA"},{"id":"b","text":"ssRNA-RT"},{"id":"c","text":"+ssRNA"},{"id":"d","text":"-ssRNA"}],"answerId":"d","explanation":"A virus with a -ssRNA genome is classified as -ssRNA in the Baltimore classification system.","kind":"recall","origin":"ai"},{"id":"virology-principles-classification~ai-4","moduleId":"virology-principles-classification","stem":"A patient presents with a viral infection characterized by high antigenic variability. Which mechanism is most likely responsible for this?","options":[{"id":"a","text":"Stable DNA replication"},{"id":"b","text":"Error-prone RNA replication"},{"id":"c","text":"Lipid envelope fragility"},{"id":"d","text":"Direct translation of viral proteins"}],"answerId":"b","explanation":"High antigenic variability in RNA viruses is primarily due to the error-prone nature of RNA replication.","kind":"mechanism","origin":"ai"},{"id":"virology-principles-classification~ai-5","moduleId":"virology-principles-classification","stem":"Which of the following viruses is most likely to be classified as a naked virus?","options":[{"id":"a","text":"HIV"},{"id":"b","text":"Influenza virus"},{"id":"c","text":"Norovirus"},{"id":"d","text":"Herpes simplex virus"}],"answerId":"c","explanation":"Norovirus is a naked virus, while the others are enveloped viruses.","kind":"recall","origin":"ai"},{"id":"virology-principles-classification~ai-6","moduleId":"virology-principles-classification","stem":"How do enveloped viruses primarily differ from naked viruses in terms of transmission routes?","options":[{"id":"a","text":"Enveloped viruses spread via fomites, naked viruses do not."},{"id":"b","text":"Naked viruses are transmitted via close contact, enveloped viruses are not."},{"id":"c","text":"Enveloped viruses are spread by close contact, naked viruses by faecal-oral routes."},{"id":"d","text":"Naked viruses require a vector for transmission, enveloped viruses do not."}],"answerId":"c","explanation":"Enveloped viruses are fragile and spread primarily through close contact, while naked viruses are hardy and often transmitted via faecal-oral routes.","kind":"integration","linkedModuleIds":["arboviruses-mosquito-borne"],"origin":"ai"},{"id":"virology-principles-classification~ai-7","moduleId":"virology-principles-classification","stem":"Which antiviral mechanism is most relevant when considering the treatment of a +ssRNA virus?","options":[{"id":"a","text":"Inhibition of reverse transcriptase"},{"id":"b","text":"Blocking RNA-dependent RNA polymerase"},{"id":"c","text":"Interference with capsid assembly"},{"id":"d","text":"Disruption of the lipid envelope"}],"answerId":"b","explanation":"Inhibiting RNA-dependent RNA polymerase is crucial for targeting +ssRNA viruses during antiviral treatment.","kind":"integration","linkedModuleIds":["antiviral-antiretroviral-agents"],"origin":"ai"}],"other-enveloped-rna-viruses":[{"id":"other-enveloped-rna-viruses~ai-0","moduleId":"other-enveloped-rna-viruses","stem":"What is the primary receptor that SARS-CoV-2 spike protein binds to for entry into human cells?","options":[{"id":"a","text":"CD4"},{"id":"b","text":"ACE2"},{"id":"c","text":"IL-6"},{"id":"d","text":"DPP-4"}],"answerId":"b","explanation":"SARS-CoV-2 utilizes the ACE2 receptor for cell entry, which is critical for its pathogenicity.","kind":"recall","origin":"ai"},{"id":"other-enveloped-rna-viruses~ai-1","moduleId":"other-enveloped-rna-viruses","stem":"Which of the following is a hallmark histological finding in rabies infection?","options":[{"id":"a","text":"Koplik spots"},{"id":"b","text":"Negri bodies"},{"id":"c","text":"Giant cells"},{"id":"d","text":"Councilman bodies"}],"answerId":"b","explanation":"Negri bodies are the characteristic histological finding in neurons infected with the rabies virus.","kind":"recall","origin":"ai"},{"id":"other-enveloped-rna-viruses~ai-2","moduleId":"other-enveloped-rna-viruses","stem":"A patient presents with hydrophobia and agitation after being bitten by a dog. What is the most appropriate immediate management?","options":[{"id":"a","text":"Administer antiviral medication"},{"id":"b","text":"Start rabies post-exposure prophylaxis"},{"id":"c","text":"Perform a lumbar puncture"},{"id":"d","text":"Observe the patient for symptoms"}],"answerId":"b","explanation":"Rabies post-exposure prophylaxis is critical after a bite, especially given the long incubation period.","kind":"clinical","origin":"ai"},{"id":"other-enveloped-rna-viruses~ai-3","moduleId":"other-enveloped-rna-viruses","stem":"Which mechanism explains the severe pneumonia associated with COVID-19?","options":[{"id":"a","text":"Direct viral cytotoxicity"},{"id":"b","text":"Immune-mediated damage"},{"id":"c","text":"Spike protein binding to ACE2"},{"id":"d","text":"Bacterial superinfection"}],"answerId":"c","explanation":"The spike protein of SARS-CoV-2 binds to ACE2, facilitating entry into cells and leading to pneumonia.","kind":"mechanism","origin":"ai"},{"id":"other-enveloped-rna-viruses~ai-4","moduleId":"other-enveloped-rna-viruses","stem":"What is the fatal outcome of rabies once symptomatic?","options":[{"id":"a","text":"Acute respiratory distress syndrome"},{"id":"b","text":"Severe dehydration"},{"id":"c","text":"Encephalitis"},{"id":"d","text":"Septic shock"}],"answerId":"c","explanation":"Rabies leads to fatal encephalitis once symptoms appear, making early intervention crucial.","kind":"recall","origin":"ai"},{"id":"other-enveloped-rna-viruses~ai-5","moduleId":"other-enveloped-rna-viruses","stem":"A neonate presents with cataracts, deafness, and cardiac defects. What viral infection is most likely responsible?","options":[{"id":"a","text":"Zika virus"},{"id":"b","text":"Cytomegalovirus"},{"id":"c","text":"Rubella virus"},{"id":"d","text":"Herpes simplex virus"}],"answerId":"c","explanation":"Congenital rubella syndrome is characterized by these specific defects in neonates.","kind":"recall","origin":"ai"},{"id":"other-enveloped-rna-viruses~ai-6","moduleId":"other-enveloped-rna-viruses","stem":"How does the rabies virus evade the immune system during its incubation period?","options":[{"id":"a","text":"Rapid replication"},{"id":"b","text":"Direct cytopathic effect"},{"id":"c","text":"Retrograde transport along nerves"},{"id":"d","text":"Induction of apoptosis"}],"answerId":"c","explanation":"Rabies virus travels retrograde along peripheral nerves to the CNS, allowing it to evade the immune response.","kind":"mechanism","origin":"ai"},{"id":"other-enveloped-rna-viruses~ai-7","moduleId":"other-enveloped-rna-viruses","stem":"Which type of virus is responsible for the high mortality associated with Ebola outbreaks?","options":[{"id":"a","text":"Arenavirus"},{"id":"b","text":"Filovirus"},{"id":"c","text":"Bunyavirus"},{"id":"d","text":"Paramyxovirus"}],"answerId":"b","explanation":"Ebola is caused by a filovirus, which is known for causing severe hemorrhagic fever with high mortality.","kind":"recall","origin":"ai"},{"id":"other-enveloped-rna-viruses~ai-8","moduleId":"other-enveloped-rna-viruses","stem":"Which of the following is a common feature shared by coronaviruses and arboviruses?","options":[{"id":"a","text":"Both are transmitted by respiratory droplets"},{"id":"b","text":"Both are enveloped RNA viruses"},{"id":"c","text":"Both cause hemorrhagic fever"},{"id":"d","text":"Both have a vaccine available"}],"answerId":"b","explanation":"Both coronaviruses and arboviruses are classified as enveloped RNA viruses.","kind":"integration","linkedModuleIds":["arboviruses-mosquito-borne"],"origin":"ai"},{"id":"other-enveloped-rna-viruses~ai-9","moduleId":"other-enveloped-rna-viruses","stem":"What is a key difference between rabies and influenza viruses in terms of transmission?","options":[{"id":"a","text":"Rabies is airborne, influenza is not"},{"id":"b","text":"Rabies is transmitted via bites, influenza via droplets"},{"id":"c","text":"Rabies is a DNA virus, influenza is RNA"},{"id":"d","text":"Rabies has a vaccine, influenza does not"}],"answerId":"b","explanation":"Rabies is primarily transmitted through bites, while influenza is transmitted through respiratory droplets.","kind":"integration","linkedModuleIds":["enveloped-rna-viruses-orthomyxo-paramyxo"],"origin":"ai"}],"bacterial-gene-transfer":[{"id":"bacterial-gene-transfer~ai-0","moduleId":"bacterial-gene-transfer","stem":"What is the primary mechanism by which antibiotic resistance genes are spread among Gram-negative bacteria?","options":[{"id":"a","text":"Transformation"},{"id":"b","text":"Transduction"},{"id":"c","text":"Conjugation"},{"id":"d","text":"Mutation"}],"answerId":"c","explanation":"Conjugation is the main route for spreading multidrug-resistance plasmids among Gram-negative bacteria through direct cell-to-cell contact.","kind":"recall","origin":"ai"},{"id":"bacterial-gene-transfer~ai-1","moduleId":"bacterial-gene-transfer","stem":"Which process involves the uptake of naked DNA from the environment by competent bacteria?","options":[{"id":"a","text":"Transduction"},{"id":"b","text":"Conjugation"},{"id":"c","text":"Transformation"},{"id":"d","text":"Mutation"}],"answerId":"c","explanation":"Transformation is the process where competent bacteria take up free DNA from their environment.","kind":"recall","origin":"ai"},{"id":"bacterial-gene-transfer~ai-2","moduleId":"bacterial-gene-transfer","stem":"A bacterium acquires a toxin gene from a bacteriophage. What mechanism does this represent?","options":[{"id":"a","text":"Conjugation"},{"id":"b","text":"Transformation"},{"id":"c","text":"Transduction"},{"id":"d","text":"Mutation"}],"answerId":"c","explanation":"Transduction is the mechanism where a bacteriophage transfers DNA, such as toxin genes, from one bacterium to another.","kind":"recall","origin":"ai"},{"id":"bacterial-gene-transfer~ai-3","moduleId":"bacterial-gene-transfer","stem":"Which of the following statements about horizontal gene transfer is true?","options":[{"id":"a","text":"All mechanisms are the same"},{"id":"b","text":"Conjugation requires cell contact"},{"id":"c","text":"Transformation requires a bacteriophage"},{"id":"d","text":"Transduction involves direct cell contact"}],"answerId":"b","explanation":"Conjugation specifically requires direct cell-to-cell contact for the transfer of plasmids.","kind":"trap","origin":"ai"},{"id":"bacterial-gene-transfer~ai-4","moduleId":"bacterial-gene-transfer","stem":"What type of genetic element can carry multiple antibiotic resistance genes and can jump between plasmids and chromosomes?","options":[{"id":"a","text":"Integrons"},{"id":"b","text":"Transposons"},{"id":"c","text":"Plasmids"},{"id":"d","text":"Bacteriophages"}],"answerId":"b","explanation":"Transposons are mobile genetic elements that can move between plasmids and chromosomes, carrying resistance genes.","kind":"recall","origin":"ai"},{"id":"bacterial-gene-transfer~ai-5","moduleId":"bacterial-gene-transfer","stem":"How does the structure of the bacterial cell wall relate to antibiotic resistance mechanisms?","options":[{"id":"a","text":"It affects plasmid transfer"},{"id":"b","text":"It influences transformation efficiency"},{"id":"c","text":"It determines susceptibility to phage"},{"id":"d","text":"It is a target for antibiotic action"}],"answerId":"d","explanation":"The bacterial cell wall structure is a key target for many antibiotics, and understanding it is crucial for addressing resistance mechanisms.","kind":"integration","linkedModuleIds":["bacterial-structure-cell-wall"],"origin":"ai"},{"id":"bacterial-gene-transfer~ai-6","moduleId":"bacterial-gene-transfer","stem":"Which mechanism of gene transfer is most likely to be involved in the rapid spread of antibiotic resistance in a hospital setting?","options":[{"id":"a","text":"Transformation"},{"id":"b","text":"Transduction"},{"id":"c","text":"Conjugation"},{"id":"d","text":"Mutation"}],"answerId":"c","explanation":"Conjugation is often the primary mechanism for the rapid spread of antibiotic resistance in clinical settings due to direct contact between bacteria.","kind":"integration","linkedModuleIds":["antibiotic-resistance-mechanisms"],"origin":"ai"}],"dna-viruses-herpesviruses":[{"id":"dna-viruses-herpesviruses~ai-0","moduleId":"dna-viruses-herpesviruses","stem":"What is the primary clinical manifestation of HSV-1 infection?","options":[{"id":"a","text":"Genital herpes"},{"id":"b","text":"Orolabial herpes"},{"id":"c","text":"Chickenpox"},{"id":"d","text":"Infectious mononucleosis"}],"answerId":"b","explanation":"HSV-1 primarily causes orolabial herpes, characterized by cold sores.","kind":"recall","origin":"ai"},{"id":"dna-viruses-herpesviruses~ai-1","moduleId":"dna-viruses-herpesviruses","stem":"Which herpesvirus is associated with congenital infection leading to deafness?","options":[{"id":"a","text":"HSV-2"},{"id":"b","text":"VZV"},{"id":"c","text":"CMV"},{"id":"d","text":"EBV"}],"answerId":"c","explanation":"CMV is the most common cause of congenital viral infection, often resulting in deafness.","kind":"recall","origin":"ai"},{"id":"dna-viruses-herpesviruses~ai-2","moduleId":"dna-viruses-herpesviruses","stem":"What is the mechanism of action of aciclovir?","options":[{"id":"a","text":"Inhibits viral DNA polymerase"},{"id":"b","text":"Inhibits viral RNA polymerase"},{"id":"c","text":"Inhibits protein synthesis"},{"id":"d","text":"Inhibits viral envelope fusion"}],"answerId":"a","explanation":"Aciclovir inhibits viral DNA polymerase, preventing viral replication.","kind":"mechanism","origin":"ai"},{"id":"dna-viruses-herpesviruses~ai-3","moduleId":"dna-viruses-herpesviruses","stem":"A patient presents with painful dermatomal vesicles not crossing the midline. What is the likely diagnosis?","options":[{"id":"a","text":"Herpes simplex encephalitis"},{"id":"b","text":"Chickenpox"},{"id":"c","text":"Herpes zoster"},{"id":"d","text":"Infectious mononucleosis"}],"answerId":"c","explanation":"The presentation is characteristic of herpes zoster (shingles), caused by VZV reactivation.","kind":"clinical","origin":"ai"},{"id":"dna-viruses-herpesviruses~ai-4","moduleId":"dna-viruses-herpesviruses","stem":"What is the hallmark of herpesvirus infections after primary infection?","options":[{"id":"a","text":"Complete clearance of the virus"},{"id":"b","text":"Lifelong latency"},{"id":"c","text":"Immediate reactivation"},{"id":"d","text":"Acute symptomatic phase"}],"answerId":"b","explanation":"Herpesviruses establish lifelong latency after primary infection, allowing for potential reactivation.","kind":"trap","origin":"ai"},{"id":"dna-viruses-herpesviruses~ai-5","moduleId":"dna-viruses-herpesviruses","stem":"Which of the following is a common complication of EBV infection?","options":[{"id":"a","text":"Retinitis"},{"id":"b","text":"Burkitt lymphoma"},{"id":"c","text":"Kaposi sarcoma"},{"id":"d","text":"Owl's eye inclusions"}],"answerId":"b","explanation":"EBV is associated with Burkitt lymphoma, especially in immunocompromised individuals.","kind":"recall","origin":"ai"},{"id":"dna-viruses-herpesviruses~ai-6","moduleId":"dna-viruses-herpesviruses","stem":"How does herpesvirus latency relate to the immune response during puberty?","options":[{"id":"a","text":"Latency is established in the liver"},{"id":"b","text":"Latency is established in the sensory ganglia"},{"id":"c","text":"Latency is cleared during puberty"},{"id":"d","text":"Latency does not occur in herpesviruses"}],"answerId":"b","explanation":"Herpesviruses establish latency in sensory ganglia, which can reactivate during periods of immune stress, such as puberty.","kind":"integration","linkedModuleIds":["hrp1-normal-puberty-tanner"],"origin":"ai"},{"id":"dna-viruses-herpesviruses~ai-7","moduleId":"dna-viruses-herpesviruses","stem":"Which antiviral is commonly used to treat CMV infections in immunocompromised patients?","options":[{"id":"a","text":"Acyclovir"},{"id":"b","text":"Ganciclovir"},{"id":"c","text":"Zidovudine"},{"id":"d","text":"Ribavirin"}],"answerId":"b","explanation":"Ganciclovir is the antiviral of choice for treating CMV infections, particularly in immunocompromised patients.","kind":"integration","linkedModuleIds":["herpesvirus-cmv-antivirals"],"origin":"ai"}],"streptococcus-pyogenes-agalactiae":[{"id":"streptococcus-pyogenes-agalactiae~ai-0","moduleId":"streptococcus-pyogenes-agalactiae","stem":"Which of the following is a characteristic of Streptococcus pyogenes?","options":[{"id":"a","text":"Catalase-positive"},{"id":"b","text":"Bacitracin-resistant"},{"id":"c","text":"Beta-hemolytic"},{"id":"d","text":"CAMP-positive"}],"answerId":"c","explanation":"Streptococcus pyogenes is a beta-hemolytic, bacitracin-sensitive, catalase-negative organism.","kind":"recall","origin":"ai"},{"id":"streptococcus-pyogenes-agalactiae~ai-1","moduleId":"streptococcus-pyogenes-agalactiae","stem":"What is the primary mechanism of action of the M protein in Streptococcus pyogenes?","options":[{"id":"a","text":"Inhibits DNA synthesis"},{"id":"b","text":"Prevents phagocytosis"},{"id":"c","text":"Disrupts cell wall synthesis"},{"id":"d","text":"Stimulates cytokine release"}],"answerId":"b","explanation":"The M protein of Streptococcus pyogenes prevents phagocytosis, contributing to its virulence.","kind":"mechanism","origin":"ai"},{"id":"streptococcus-pyogenes-agalactiae~ai-2","moduleId":"streptococcus-pyogenes-agalactiae","stem":"A 10-year-old presents with fever, sore throat, and a rash. Which finding would most likely indicate scarlet fever?","options":[{"id":"a","text":"Cervical lymphadenopathy"},{"id":"b","text":"Strawberry tongue"},{"id":"c","text":"Pustular rash"},{"id":"d","text":"Erythematous rash with peeling"}],"answerId":"b","explanation":"Scarlet fever is characterized by a strawberry tongue and a diffuse erythematous rash.","kind":"clinical","origin":"ai"},{"id":"streptococcus-pyogenes-agalactiae~ai-3","moduleId":"streptococcus-pyogenes-agalactiae","stem":"Which condition is prevented by treating streptococcal pharyngitis with antibiotics?","options":[{"id":"a","text":"Post-streptococcal glomerulonephritis"},{"id":"b","text":"Rheumatic fever"},{"id":"c","text":"Impetigo"},{"id":"d","text":"Necrotizing fasciitis"}],"answerId":"b","explanation":"Rheumatic fever can be prevented by treating streptococcal pharyngitis with antibiotics.","kind":"trap","origin":"ai"},{"id":"streptococcus-pyogenes-agalactiae~ai-4","moduleId":"streptococcus-pyogenes-agalactiae","stem":"A newborn presents with sepsis and is found to have a beta-hemolytic streptococcus that is CAMP-positive. What is the likely organism?","options":[{"id":"a","text":"Streptococcus pneumoniae"},{"id":"b","text":"Streptococcus agalactiae"},{"id":"c","text":"Streptococcus pyogenes"},{"id":"d","text":"Enterococcus faecalis"}],"answerId":"b","explanation":"Streptococcus agalactiae (Group B strep) is known for causing neonatal sepsis and is CAMP-positive.","kind":"recall","origin":"ai"},{"id":"streptococcus-pyogenes-agalactiae~ai-5","moduleId":"streptococcus-pyogenes-agalactiae","stem":"A patient develops nephritic syndrome after a skin infection. Which condition is most likely responsible?","options":[{"id":"a","text":"Rheumatic fever"},{"id":"b","text":"Post-streptococcal glomerulonephritis"},{"id":"c","text":"IgA nephropathy"},{"id":"d","text":"Chronic kidney disease"}],"answerId":"b","explanation":"Post-streptococcal glomerulonephritis can occur after either pharyngitis or skin infections like impetigo.","kind":"integration","linkedModuleIds":["iga-nephropathy-postinfectious-gn"],"origin":"ai"},{"id":"streptococcus-pyogenes-agalactiae~ai-6","moduleId":"streptococcus-pyogenes-agalactiae","stem":"Which of the following findings is indicative of rheumatic fever following streptococcal pharyngitis?","options":[{"id":"a","text":"Hematuria"},{"id":"b","text":"Migratory arthritis"},{"id":"c","text":"Skin rash"},{"id":"d","text":"Cough"}],"answerId":"b","explanation":"Migratory arthritis is a classic manifestation of rheumatic fever that can occur weeks after streptococcal pharyngitis.","kind":"integration","linkedModuleIds":["rheumatic-heart-disease"],"origin":"ai"}],"antibiotic-resistance-mechanisms":[{"id":"antibiotic-resistance-mechanisms~ai-0","moduleId":"antibiotic-resistance-mechanisms","stem":"What is the primary mechanism of resistance in MRSA?","options":[{"id":"a","text":"Enzymatic inactivation by β-lactamase"},{"id":"b","text":"Altered penicillin-binding protein PBP2a"},{"id":"c","text":"Efflux pump activity"},{"id":"d","text":"Reduced permeability via porin loss"}],"answerId":"b","explanation":"MRSA resistance is primarily due to the mecA gene, which encodes PBP2a, an altered target with low affinity for β-lactams.","kind":"recall","origin":"ai"},{"id":"antibiotic-resistance-mechanisms~ai-1","moduleId":"antibiotic-resistance-mechanisms","stem":"Which mechanism allows Gram-negative bacteria to resist most cephalosporins?","options":[{"id":"a","text":"Efflux pumps"},{"id":"b","text":"Target modification"},{"id":"c","text":"Extended-spectrum β-lactamases"},{"id":"d","text":"Reduced permeability"}],"answerId":"c","explanation":"Extended-spectrum β-lactamases (ESBLs) hydrolyze a wide range of cephalosporins, rendering them ineffective.","kind":"recall","origin":"ai"},{"id":"antibiotic-resistance-mechanisms~ai-2","moduleId":"antibiotic-resistance-mechanisms","stem":"How does VRE (vancomycin-resistant Enterococcus) develop resistance?","options":[{"id":"a","text":"Increased β-lactamase production"},{"id":"b","text":"Alteration of D-Ala-D-Ala to D-Ala-D-Lac"},{"id":"c","text":"Efflux pump overexpression"},{"id":"d","text":"Porin loss"}],"answerId":"b","explanation":"VRE alters the peptidoglycan structure by changing D-Ala-D-Ala to D-Ala-D-Lac, preventing vancomycin binding.","kind":"mechanism","origin":"ai"},{"id":"antibiotic-resistance-mechanisms~ai-3","moduleId":"antibiotic-resistance-mechanisms","stem":"A patient presents with a Gram-negative infection resistant to carbapenems. Which enzyme is likely responsible?","options":[{"id":"a","text":"Penicillinase"},{"id":"b","text":"Extended-spectrum β-lactamase"},{"id":"c","text":"Carbapenemase"},{"id":"d","text":"Aminoglycoside-modifying enzyme"}],"answerId":"c","explanation":"Carbapenemases, such as KPC or NDM, are responsible for resistance to carbapenems, the last-line agents.","kind":"recall","origin":"ai"},{"id":"antibiotic-resistance-mechanisms~ai-4","moduleId":"antibiotic-resistance-mechanisms","stem":"Which of the following statements about MRSA is false?","options":[{"id":"a","text":"MRSA is resistant to methicillin."},{"id":"b","text":"MRSA produces β-lactamase."},{"id":"c","text":"MRSA has altered penicillin-binding protein."},{"id":"d","text":"MRSA resistance is due to target modification."}],"answerId":"b","explanation":"MRSA resistance is primarily due to target modification (mecA/PBP2a) rather than β-lactamase production.","kind":"trap","origin":"ai"},{"id":"antibiotic-resistance-mechanisms~ai-5","moduleId":"antibiotic-resistance-mechanisms","stem":"How does the mechanism of resistance in Enterobacterales relate to antibiotic stewardship?","options":[{"id":"a","text":"Increased β-lactamase production leads to better treatment outcomes."},{"id":"b","text":"Efflux pumps enhance the effectiveness of antibiotics."},{"id":"c","text":"Understanding resistance mechanisms guides appropriate antibiotic use."},{"id":"d","text":"Resistance mechanisms are irrelevant to antibiotic selection."}],"answerId":"c","explanation":"Knowledge of resistance mechanisms, such as those in Enterobacterales, informs appropriate antibiotic selection and stewardship efforts.","kind":"integration","linkedModuleIds":["enterobacterales-ecoli-klebsiella"],"origin":"ai"},{"id":"antibiotic-resistance-mechanisms~ai-6","moduleId":"antibiotic-resistance-mechanisms","stem":"What is the role of β-lactamase inhibitors in treating resistant infections?","options":[{"id":"a","text":"They enhance the activity of β-lactams against all bacteria."},{"id":"b","text":"They are ineffective against MRSA."},{"id":"c","text":"They are only useful for Gram-positive bacteria."},{"id":"d","text":"They can restore activity of some β-lactams against ESBL-producing organisms."}],"answerId":"d","explanation":"β-lactamase inhibitors can restore the effectiveness of certain β-lactams against bacteria producing ESBLs, but not against MRSA.","kind":"mechanism","origin":"ai"}],"bacillus-anthracis-cereus":[{"id":"bacillus-anthracis-cereus~ai-0","moduleId":"bacillus-anthracis-cereus","stem":"What is the primary component of the capsule of Bacillus anthracis?","options":[{"id":"a","text":"Polysaccharide"},{"id":"b","text":"Protein"},{"id":"c","text":"Lipid"},{"id":"d","text":"Peptidoglycan"}],"answerId":"b","explanation":"Bacillus anthracis has a unique protein capsule made of poly-D-glutamate, distinguishing it from most other bacterial capsules.","kind":"recall","origin":"ai"},{"id":"bacillus-anthracis-cereus~ai-1","moduleId":"bacillus-anthracis-cereus","stem":"Which clinical finding is characteristic of cutaneous anthrax?","options":[{"id":"a","text":"Intensely painful ulcer"},{"id":"b","text":"Painless black necrotic eschar"},{"id":"c","text":"Purulent skin abscess"},{"id":"d","text":"Fever with rash"}],"answerId":"b","explanation":"The cutaneous anthrax lesion presents as a painless black necrotic eschar with surrounding edema, which is a key distinguishing feature.","kind":"recall","origin":"ai"},{"id":"bacillus-anthracis-cereus~ai-2","moduleId":"bacillus-anthracis-cereus","stem":"What mechanism underlies the emetic syndrome caused by Bacillus cereus?","options":[{"id":"a","text":"Heat-labile enterotoxin"},{"id":"b","text":"Heat-stable toxin"},{"id":"c","text":"Cytotoxin"},{"id":"d","text":"Neurotoxin"}],"answerId":"b","explanation":"The emetic form of Bacillus cereus food poisoning is due to a heat-stable toxin, commonly associated with reheated fried rice.","kind":"mechanism","origin":"ai"},{"id":"bacillus-anthracis-cereus~ai-3","moduleId":"bacillus-anthracis-cereus","stem":"Which of the following is a common presentation of inhalational anthrax?","options":[{"id":"a","text":"Pneumonia with productive cough"},{"id":"b","text":"Widened mediastinum and hemorrhagic mediastinitis"},{"id":"c","text":"Fever with generalized rash"},{"id":"d","text":"Severe abdominal pain"}],"answerId":"b","explanation":"Inhalational anthrax is characterized by widened mediastinum and hemorrhagic mediastinitis, often leading to high mortality.","kind":"recall","origin":"ai"},{"id":"bacillus-anthracis-cereus~ai-4","moduleId":"bacillus-anthracis-cereus","stem":"What is a critical distinguishing feature of Bacillus anthracis compared to Bacillus cereus?","options":[{"id":"a","text":"Causes food poisoning"},{"id":"b","text":"Has a protein capsule"},{"id":"c","text":"Is anaerobic"},{"id":"d","text":"Produces spores only in the presence of oxygen"}],"answerId":"b","explanation":"Bacillus anthracis has a unique protein capsule, while Bacillus cereus does not have this feature and is primarily associated with food poisoning.","kind":"trap","origin":"ai"},{"id":"bacillus-anthracis-cereus~ai-5","moduleId":"bacillus-anthracis-cereus","stem":"How does the mechanism of Bacillus cereus differ from that of Clostridia species in terms of food poisoning?","options":[{"id":"a","text":"Bacillus cereus uses pre-formed toxins, Clostridia use enterotoxins"},{"id":"b","text":"Bacillus cereus is anaerobic, Clostridia are aerobic"},{"id":"c","text":"Bacillus cereus causes symptoms after 24 hours, Clostridia within hours"},{"id":"d","text":"Bacillus cereus is associated with dairy, Clostridia with grains"}],"answerId":"a","explanation":"Bacillus cereus causes food poisoning via pre-formed toxins, while Clostridia species typically produce enterotoxins that act after ingestion.","kind":"integration","linkedModuleIds":["clostridia-anaerobic-pathogens"],"origin":"ai"},{"id":"bacillus-anthracis-cereus~ai-6","moduleId":"bacillus-anthracis-cereus","stem":"Which organism shares a similar aerobic spore-forming characteristic with Bacillus anthracis?","options":[{"id":"a","text":"Clostridium tetani"},{"id":"b","text":"Listeria monocytogenes"},{"id":"c","text":"Corynebacterium diphtheriae"},{"id":"d","text":"Bacillus cereus"}],"answerId":"d","explanation":"Bacillus cereus is also an aerobic spore-forming organism, unlike Clostridia, which are anaerobic.","kind":"integration","linkedModuleIds":["corynebacterium-listeria"],"origin":"ai"}],"arboviruses-mosquito-borne":[{"id":"arboviruses-mosquito-borne~ai-0","moduleId":"arboviruses-mosquito-borne","stem":"What is the primary mechanism by which a secondary dengue infection can lead to severe dengue?","options":[{"id":"a","text":"Viral mutation"},{"id":"b","text":"Antibody-dependent enhancement"},{"id":"c","text":"Increased viral load"},{"id":"d","text":"Cross-species transmission"}],"answerId":"b","explanation":"Antibody-dependent enhancement occurs when non-neutralizing antibodies from a previous dengue infection facilitate viral entry into cells during a secondary infection, leading to severe disease.","kind":"mechanism","origin":"ai"},{"id":"arboviruses-mosquito-borne~ai-1","moduleId":"arboviruses-mosquito-borne","stem":"Which clinical finding is most characteristic of chikungunya infection?","options":[{"id":"a","text":"High fever and rash"},{"id":"b","text":"Severe, prolonged arthralgia"},{"id":"c","text":"Microcephaly in neonates"},{"id":"d","text":"Encephalitis"}],"answerId":"b","explanation":"Chikungunya is known for causing severe and prolonged joint pain (arthralgia) following fever.","kind":"recall","origin":"ai"},{"id":"arboviruses-mosquito-borne~ai-2","moduleId":"arboviruses-mosquito-borne","stem":"A patient presents with high fever, severe myalgia, and thrombocytopenia. What is the most likely diagnosis?","options":[{"id":"a","text":"Zika virus infection"},{"id":"b","text":"Chikungunya"},{"id":"c","text":"Dengue fever"},{"id":"d","text":"Japanese encephalitis"}],"answerId":"c","explanation":"These symptoms are classic for dengue fever, especially in endemic regions.","kind":"clinical","origin":"ai"},{"id":"arboviruses-mosquito-borne~ai-3","moduleId":"arboviruses-mosquito-borne","stem":"What is the key preventive measure against arboviral diseases transmitted by Aedes mosquitoes?","options":[{"id":"a","text":"Vaccination only"},{"id":"b","text":"Vector control"},{"id":"c","text":"Antiviral medications"},{"id":"d","text":"Public awareness campaigns"}],"answerId":"b","explanation":"Vector control, including eliminating standing water and using repellents, is crucial for preventing arboviral diseases like dengue and Zika.","kind":"recall","origin":"ai"},{"id":"arboviruses-mosquito-borne~ai-4","moduleId":"arboviruses-mosquito-borne","stem":"Which of the following statements about dengue virus infections is true?","options":[{"id":"a","text":"Having had dengue once guarantees immunity to all serotypes"},{"id":"b","text":"Secondary infections with different serotypes can be more severe"},{"id":"c","text":"Dengue is primarily transmitted by Culex mosquitoes"},{"id":"d","text":"Dengue fever is always fatal"}],"answerId":"b","explanation":"Secondary infections with different dengue serotypes can lead to severe dengue due to antibody-dependent enhancement.","kind":"trap","origin":"ai"},{"id":"arboviruses-mosquito-borne~ai-5","moduleId":"arboviruses-mosquito-borne","stem":"A pregnant woman contracts Zika virus. What is the most concerning potential outcome for her fetus?","options":[{"id":"a","text":"Microcephaly"},{"id":"b","text":"Thrombocytopenia"},{"id":"c","text":"Encephalitis"},{"id":"d","text":"Hemorrhagic fever"}],"answerId":"a","explanation":"Congenital Zika infection is associated with microcephaly and other developmental issues in the fetus.","kind":"recall","origin":"ai"},{"id":"arboviruses-mosquito-borne~ai-6","moduleId":"arboviruses-mosquito-borne","stem":"How does the understanding of arboviral transmission relate to the principles of virology?","options":[{"id":"a","text":"It emphasizes the role of DNA viruses"},{"id":"b","text":"It highlights the importance of vector control in viral transmission"},{"id":"c","text":"It shows that all viruses are transmitted through direct contact"},{"id":"d","text":"It indicates that all arboviruses are RNA viruses"}],"answerId":"b","explanation":"Understanding arboviral transmission underscores the significance of vector control in preventing the spread of these viruses, which is a key concept in virology.","kind":"integration","linkedModuleIds":["virology-principles-classification"],"origin":"ai"},{"id":"arboviruses-mosquito-borne~ai-7","moduleId":"arboviruses-mosquito-borne","stem":"Which mosquito-borne disease is primarily associated with severe neurological complications?","options":[{"id":"a","text":"Dengue fever"},{"id":"b","text":"Zika virus"},{"id":"c","text":"Japanese encephalitis"},{"id":"d","text":"Chikungunya"}],"answerId":"c","explanation":"Japanese encephalitis, transmitted by Culex mosquitoes, is known for causing severe neurological complications.","kind":"integration","linkedModuleIds":["mosquito-borne-diseases"],"origin":"ai"}],"bacterial-physiology-growth-identification":[{"id":"bacterial-physiology-growth-identification~ai-0","moduleId":"bacterial-physiology-growth-identification","stem":"Which type of bacteria can grow in the presence or absence of oxygen?","options":[{"id":"a","text":"Obligate aerobes"},{"id":"b","text":"Obligate anaerobes"},{"id":"c","text":"Facultative anaerobes"},{"id":"d","text":"Microaerophiles"}],"answerId":"c","explanation":"Facultative anaerobes can utilize oxygen when present but can also grow in its absence.","kind":"recall","origin":"ai"},{"id":"bacterial-physiology-growth-identification~ai-1","moduleId":"bacterial-physiology-growth-identification","stem":"What is the primary mechanism by which E. coli generates ATP under aerobic conditions?","options":[{"id":"a","text":"Fermentation"},{"id":"b","text":"Glycolysis"},{"id":"c","text":"Respiration"},{"id":"d","text":"Binary fission"}],"answerId":"c","explanation":"E. coli generates ATP primarily through aerobic respiration, utilizing the electron transport chain.","kind":"mechanism","origin":"ai"},{"id":"bacterial-physiology-growth-identification~ai-2","moduleId":"bacterial-physiology-growth-identification","stem":"What does a pink colony on MacConkey agar indicate?","options":[{"id":"a","text":"Non-lactose fermenter"},{"id":"b","text":"Lactose fermenter"},{"id":"c","text":"Gram-positive organism"},{"id":"d","text":"Obligate anaerobe"}],"answerId":"b","explanation":"Pink colonies on MacConkey agar indicate lactose fermentation, typically by Gram-negative bacteria like E. coli.","kind":"recall","origin":"ai"},{"id":"bacterial-physiology-growth-identification~ai-3","moduleId":"bacterial-physiology-growth-identification","stem":"Which of the following statements about selective and differential media is true?","options":[{"id":"a","text":"They are the same"},{"id":"b","text":"Selective media allows for distinguishing organisms"},{"id":"c","text":"Differential media suppresses unwanted organisms"},{"id":"d","text":"MacConkey agar is both selective and differential"}],"answerId":"d","explanation":"MacConkey agar is both selective for Gram-negative bacteria and differential for lactose fermentation.","kind":"trap","origin":"ai"},{"id":"bacterial-physiology-growth-identification~ai-4","moduleId":"bacterial-physiology-growth-identification","stem":"A patient presents with a slow-growing organism that takes weeks to culture. Which organism is most likely responsible?","options":[{"id":"a","text":"E. coli"},{"id":"b","text":"M. tuberculosis"},{"id":"c","text":"Klebsiella"},{"id":"d","text":"Staphylococcus aureus"}],"answerId":"b","explanation":"M. tuberculosis has a long generation time, making it slow to culture compared to other bacteria.","kind":"clinical","origin":"ai"},{"id":"bacterial-physiology-growth-identification~ai-5","moduleId":"bacterial-physiology-growth-identification","stem":"How does the identification of bacteria using MALDI-TOF mass spectrometry differ from traditional methods?","options":[{"id":"a","text":"It uses genetic sequencing"},{"id":"b","text":"It identifies bacteria based on protein fingerprints"},{"id":"c","text":"It requires live cultures"},{"id":"d","text":"It is less rapid than biochemical tests"}],"answerId":"b","explanation":"MALDI-TOF mass spectrometry identifies bacteria based on their unique protein fingerprints, allowing for rapid identification.","kind":"mechanism","origin":"ai"},{"id":"bacterial-physiology-growth-identification~ai-6","moduleId":"bacterial-physiology-growth-identification","stem":"In the context of bacterial physiology, how does the oxygen transport mechanism relate to bacterial growth?","options":[{"id":"a","text":"It affects nutrient absorption"},{"id":"b","text":"It determines the type of culture media used"},{"id":"c","text":"It influences the bacteria's energy production method"},{"id":"d","text":"It has no relation to bacterial growth"}],"answerId":"c","explanation":"The oxygen transport mechanism influences whether bacteria use respiration or fermentation for energy production, affecting their growth.","kind":"integration","linkedModuleIds":["oxygen-transport-dissociation-curve"],"origin":"ai"},{"id":"bacterial-physiology-growth-identification~ai-7","moduleId":"bacterial-physiology-growth-identification","stem":"What dietary management strategy is crucial for patients with galactosemia when considering bacterial growth?","options":[{"id":"a","text":"Increased protein intake"},{"id":"b","text":"Avoidance of lactose"},{"id":"c","text":"Increased carbohydrate intake"},{"id":"d","text":"Supplementation with antibiotics"}],"answerId":"b","explanation":"Avoidance of lactose is essential in galactosemia, which can also affect the growth of lactose-fermenting bacteria.","kind":"integration","linkedModuleIds":["galactosemia-differential-diet"],"origin":"ai"}],"streptococcus-pneumoniae-enterococci":[{"id":"streptococcus-pneumoniae-enterococci~ai-0","moduleId":"streptococcus-pneumoniae-enterococci","stem":"What is the key virulence factor of Streptococcus pneumoniae?","options":[{"id":"a","text":"Polysaccharide capsule"},{"id":"b","text":"Lipopolysaccharide"},{"id":"c","text":"Flagella"},{"id":"d","text":"Exotoxins"}],"answerId":"a","explanation":"The polysaccharide capsule is crucial for the virulence of S. pneumoniae as it prevents phagocytosis.","kind":"recall","origin":"ai"},{"id":"streptococcus-pneumoniae-enterococci~ai-1","moduleId":"streptococcus-pneumoniae-enterococci","stem":"Which test differentiates Streptococcus pneumoniae from viridans streptococci?","options":[{"id":"a","text":"Bile solubility test"},{"id":"b","text":"Catalase test"},{"id":"c","text":"Coagulase test"},{"id":"d","text":"Oxidase test"}],"answerId":"a","explanation":"S. pneumoniae is bile-soluble, while viridans streptococci are bile-insoluble, making the bile solubility test essential for differentiation.","kind":"trap","origin":"ai"},{"id":"streptococcus-pneumoniae-enterococci~ai-2","moduleId":"streptococcus-pneumoniae-enterococci","stem":"What is the primary clinical manifestation of S. pneumoniae infection in adults?","options":[{"id":"a","text":"Bacterial meningitis"},{"id":"b","text":"Dental caries"},{"id":"c","text":"Subacute endocarditis"},{"id":"d","text":"Gastroenteritis"}],"answerId":"a","explanation":"Streptococcus pneumoniae is a leading cause of bacterial meningitis in adults.","kind":"clinical","origin":"ai"},{"id":"streptococcus-pneumoniae-enterococci~ai-3","moduleId":"streptococcus-pneumoniae-enterococci","stem":"What mechanism contributes to vancomycin resistance in Enterococcus faecium?","options":[{"id":"a","text":"Altered target site"},{"id":"b","text":"Efflux pump"},{"id":"c","text":"Beta-lactamase production"},{"id":"d","text":"D-Ala-D-Lac substitution"}],"answerId":"d","explanation":"Enterococcus faecium exhibits vancomycin resistance primarily through the substitution of D-Ala with D-Lac in its cell wall synthesis.","kind":"mechanism","origin":"ai"},{"id":"streptococcus-pneumoniae-enterococci~ai-4","moduleId":"streptococcus-pneumoniae-enterococci","stem":"A patient with a history of dental procedures presents with fever and a new heart murmur. Which organism is most likely responsible?","options":[{"id":"a","text":"Streptococcus pneumoniae"},{"id":"b","text":"Streptococcus mutans"},{"id":"c","text":"Enterococcus faecalis"},{"id":"d","text":"Staphylococcus aureus"}],"answerId":"b","explanation":"Streptococcus mutans is a viridans streptococcus commonly associated with subacute bacterial endocarditis following dental procedures.","kind":"clinical","origin":"ai"},{"id":"streptococcus-pneumoniae-enterococci~ai-5","moduleId":"streptococcus-pneumoniae-enterococci","stem":"In an asplenic patient, which organism poses the highest risk for fulminant sepsis?","options":[{"id":"a","text":"Streptococcus pneumoniae"},{"id":"b","text":"Enterococcus faecalis"},{"id":"c","text":"Staphylococcus epidermidis"},{"id":"d","text":"Escherichia coli"}],"answerId":"a","explanation":"Asplenic patients are particularly susceptible to infections from encapsulated organisms like Streptococcus pneumoniae, leading to fulminant sepsis.","kind":"clinical","origin":"ai"},{"id":"streptococcus-pneumoniae-enterococci~ai-6","moduleId":"streptococcus-pneumoniae-enterococci","stem":"How does the mechanism of antibiotic resistance in Enterococcus relate to its clinical implications in infective endocarditis?","options":[{"id":"a","text":"Increased virulence"},{"id":"b","text":"Reduced susceptibility to beta-lactams"},{"id":"c","text":"Enhanced biofilm formation"},{"id":"d","text":"Resistance to all antibiotics"}],"answerId":"b","explanation":"Enterococcus species, particularly VRE, exhibit reduced susceptibility to beta-lactams, complicating treatment in infective endocarditis cases.","kind":"integration","linkedModuleIds":["infective-endocarditis"],"origin":"ai"},{"id":"streptococcus-pneumoniae-enterococci~ai-7","moduleId":"streptococcus-pneumoniae-enterococci","stem":"Which characteristic of Streptococcus pneumoniae is crucial for its differentiation from viridans streptococci and relates to its pathogenicity?","options":[{"id":"a","text":"Optochin sensitivity"},{"id":"b","text":"Bile resistance"},{"id":"c","text":"Catalase positivity"},{"id":"d","text":"Gram-negative staining"}],"answerId":"a","explanation":"Optochin sensitivity is a key characteristic that helps differentiate S. pneumoniae from viridans streptococci, which is important for understanding its pathogenicity.","kind":"integration","linkedModuleIds":["streptococcus-pyogenes-agalactiae"],"origin":"ai"}],"staphylococcus-aureus":[{"id":"staphylococcus-aureus~ai-0","moduleId":"staphylococcus-aureus","stem":"What is the primary virulence factor of Staphylococcus aureus that prevents opsonization?","options":[{"id":"a","text":"Protein A"},{"id":"b","text":"Coagulase"},{"id":"c","text":"Enterotoxin"},{"id":"d","text":"Exfoliative toxin"}],"answerId":"a","explanation":"Protein A binds the Fc region of IgG, inhibiting opsonization and phagocytosis.","kind":"recall","origin":"ai"},{"id":"staphylococcus-aureus~ai-1","moduleId":"staphylococcus-aureus","stem":"A patient presents with fever, diffuse rash, and hypotension after using a tampon. What is the most likely diagnosis?","options":[{"id":"a","text":"Staphylococcal scalded skin syndrome"},{"id":"b","text":"Toxic shock syndrome"},{"id":"c","text":"Food poisoning"},{"id":"d","text":"Impetigo"}],"answerId":"b","explanation":"These symptoms are characteristic of toxic shock syndrome caused by TSST-1.","kind":"clinical","origin":"ai"},{"id":"staphylococcus-aureus~ai-2","moduleId":"staphylococcus-aureus","stem":"Which of the following is a distinguishing feature of Staphylococcus aureus compared to other staphylococci?","options":[{"id":"a","text":"Catalase-negative"},{"id":"b","text":"Coagulase-positive"},{"id":"c","text":"Non-fermentative"},{"id":"d","text":"Gram-negative"}],"answerId":"b","explanation":"Staphylococcus aureus is coagulase-positive, which differentiates it from coagulase-negative staphylococci.","kind":"recall","origin":"ai"},{"id":"staphylococcus-aureus~ai-3","moduleId":"staphylococcus-aureus","stem":"What mechanism leads to methicillin resistance in Staphylococcus aureus?","options":[{"id":"a","text":"Altered penicillin-binding proteins"},{"id":"b","text":"Efflux pumps"},{"id":"c","text":"Beta-lactamase production"},{"id":"d","text":"Cell wall synthesis inhibition"}],"answerId":"a","explanation":"The mecA gene encodes PBP2a, which has a low affinity for beta-lactams, leading to resistance.","kind":"mechanism","origin":"ai"},{"id":"staphylococcus-aureus~ai-4","moduleId":"staphylococcus-aureus","stem":"A child presents with superficial skin sloughing. Which toxin is responsible for this condition?","options":[{"id":"a","text":"TSST-1"},{"id":"b","text":"Exfoliative toxin"},{"id":"c","text":"Enterotoxin"},{"id":"d","text":"Coagulase"}],"answerId":"b","explanation":"Exfoliative toxin causes staphylococcal scalded skin syndrome, leading to skin sloughing.","kind":"clinical","origin":"ai"},{"id":"staphylococcus-aureus~ai-5","moduleId":"staphylococcus-aureus","stem":"Staphylococcal food poisoning is characterized by rapid onset of symptoms. What is the underlying reason for this?","options":[{"id":"a","text":"Bacterial colonization of the gut"},{"id":"b","text":"Pre-formed heat-stable enterotoxin"},{"id":"c","text":"Delayed immune response"},{"id":"d","text":"Invasive bacterial infection"}],"answerId":"b","explanation":"The symptoms arise from a pre-formed, heat-stable enterotoxin, causing rapid vomiting within hours.","kind":"trap","origin":"ai"},{"id":"staphylococcus-aureus~ai-6","moduleId":"staphylococcus-aureus","stem":"How does the presence of mecA in Staphylococcus aureus relate to antibiotic resistance mechanisms?","options":[{"id":"a","text":"It enhances biofilm formation"},{"id":"b","text":"It alters cell wall permeability"},{"id":"c","text":"It encodes a resistant penicillin-binding protein"},{"id":"d","text":"It increases efflux pump activity"}],"answerId":"c","explanation":"mecA encodes PBP2a, which is a penicillin-binding protein that confers resistance to beta-lactams.","kind":"integration","linkedModuleIds":["antibiotic-resistance-mechanisms"],"origin":"ai"},{"id":"staphylococcus-aureus~ai-7","moduleId":"staphylococcus-aureus","stem":"Which clinical feature would suggest a diagnosis of Staphylococcus aureus endocarditis in an IV drug user?","options":[{"id":"a","text":"Left-sided heart murmur"},{"id":"b","text":"Right-sided heart murmur"},{"id":"c","text":"Fever with abdominal pain"},{"id":"d","text":"Skin rash with joint pain"}],"answerId":"b","explanation":"Right-sided endocarditis is common in IV drug users due to direct inoculation of bacteria into the bloodstream.","kind":"integration","linkedModuleIds":["coagulase-negative-staphylococci"],"origin":"ai"}],"bacterial-structure-cell-wall":[{"id":"bacterial-structure-cell-wall~ai-0","moduleId":"bacterial-structure-cell-wall","stem":"What is the primary component of the Gram-positive bacterial cell wall?","options":[{"id":"a","text":"Lipopolysaccharide"},{"id":"b","text":"Teichoic acid"},{"id":"c","text":"Peptidoglycan"},{"id":"d","text":"Mycolic acid"}],"answerId":"c","explanation":"Gram-positive bacteria have a thick peptidoglycan layer that retains the crystal violet stain, distinguishing them from Gram-negative bacteria.","kind":"recall","origin":"ai"},{"id":"bacterial-structure-cell-wall~ai-1","moduleId":"bacterial-structure-cell-wall","stem":"Which of the following bacteria would NOT retain crystal violet during a Gram stain?","options":[{"id":"a","text":"Staphylococcus aureus"},{"id":"b","text":"Escherichia coli"},{"id":"c","text":"Streptococcus pneumoniae"},{"id":"d","text":"Bacillus anthracis"}],"answerId":"b","explanation":"Escherichia coli is a Gram-negative bacterium with a thin peptidoglycan layer and an outer membrane, causing it to lose the crystal violet stain.","kind":"clinical","origin":"ai"},{"id":"bacterial-structure-cell-wall~ai-2","moduleId":"bacterial-structure-cell-wall","stem":"What is the mechanism of action of β-lactam antibiotics?","options":[{"id":"a","text":"Inhibition of protein synthesis"},{"id":"b","text":"Disruption of cell membrane integrity"},{"id":"c","text":"Inhibition of peptidoglycan cross-linking"},{"id":"d","text":"Inhibition of nucleic acid synthesis"}],"answerId":"c","explanation":"β-lactam antibiotics inhibit the transpeptidation process in peptidoglycan synthesis, which is crucial for bacterial cell wall integrity.","kind":"mechanism","origin":"ai"},{"id":"bacterial-structure-cell-wall~ai-3","moduleId":"bacterial-structure-cell-wall","stem":"Which finding is characteristic of Gram-negative bacterial infection?","options":[{"id":"a","text":"Purple cocci in clusters"},{"id":"b","text":"Pink rods taking safranin"},{"id":"c","text":"Acid-fast bacilli"},{"id":"d","text":"Capsulated bacteria"}],"answerId":"b","explanation":"Gram-negative bacteria appear pink after Gram staining due to their thin peptidoglycan layer and outer membrane.","kind":"recall","origin":"ai"},{"id":"bacterial-structure-cell-wall~ai-4","moduleId":"bacterial-structure-cell-wall","stem":"Which of the following statements about Gram-negative bacteria is TRUE?","options":[{"id":"a","text":"They have a thick peptidoglycan layer."},{"id":"b","text":"They retain crystal violet after decolorization."},{"id":"c","text":"They possess an outer membrane containing LPS."},{"id":"d","text":"They are intrinsically resistant to all antibiotics."}],"answerId":"c","explanation":"Gram-negative bacteria have an outer membrane that contains lipopolysaccharide (LPS), which is a key feature distinguishing them from Gram-positive bacteria.","kind":"trap","origin":"ai"},{"id":"bacterial-structure-cell-wall~ai-5","moduleId":"bacterial-structure-cell-wall","stem":"Which organism is likely to be identified as acid-fast and will not Gram stain?","options":[{"id":"a","text":"Staphylococcus aureus"},{"id":"b","text":"Mycobacterium tuberculosis"},{"id":"c","text":"Escherichia coli"},{"id":"d","text":"Clostridium perfringens"}],"answerId":"b","explanation":"Mycobacterium tuberculosis has a waxy mycolic acid cell wall that makes it acid-fast and prevents it from being effectively stained by the Gram stain.","kind":"recall","origin":"ai"},{"id":"bacterial-structure-cell-wall~ai-6","moduleId":"bacterial-structure-cell-wall","stem":"How does the presence of a capsule affect the virulence of bacteria?","options":[{"id":"a","text":"It enhances motility."},{"id":"b","text":"It promotes adhesion."},{"id":"c","text":"It protects against phagocytosis."},{"id":"d","text":"It aids in nutrient absorption."}],"answerId":"c","explanation":"The capsule serves as a virulence factor by protecting bacteria from phagocytosis, enhancing their ability to cause disease.","kind":"mechanism","origin":"ai"},{"id":"bacterial-structure-cell-wall~ai-7","moduleId":"bacterial-structure-cell-wall","stem":"Which of the following statements best describes the relationship between the cell wall structure and antibiotic susceptibility?","options":[{"id":"a","text":"Gram-positive bacteria are resistant to β-lactams due to their thick wall."},{"id":"b","text":"Gram-negative bacteria are susceptible to β-lactams due to their outer membrane."},{"id":"c","text":"The presence of LPS in Gram-negative bacteria makes them susceptible to antibiotics."},{"id":"d","text":"The thick peptidoglycan layer in Gram-positive bacteria is a target for β-lactams."}],"answerId":"d","explanation":"The thick peptidoglycan layer in Gram-positive bacteria is the primary target for β-lactam antibiotics, which inhibit cell wall synthesis.","kind":"integration","linkedModuleIds":["antibacterial-cell-wall-agents"],"origin":"ai"},{"id":"bacterial-structure-cell-wall~ai-8","moduleId":"bacterial-structure-cell-wall","stem":"Which Gram-positive bacterium is known for producing a potent exotoxin that can lead to severe muscle paralysis?","options":[{"id":"a","text":"Clostridium perfringens"},{"id":"b","text":"Clostridium tetani"},{"id":"c","text":"Staphylococcus aureus"},{"id":"d","text":"Streptococcus pneumoniae"}],"answerId":"b","explanation":"Clostridium tetani produces tetanospasmin, an exotoxin that causes muscle paralysis, and is classified as a Gram-positive bacterium.","kind":"integration","linkedModuleIds":["clostridia-anaerobic-pathogens"],"origin":"ai"}],"dna-viruses-other":[{"id":"dna-viruses-other~ai-0","moduleId":"dna-viruses-other","stem":"What is the primary mechanism by which high-risk HPV types 16 and 18 contribute to cervical cancer?","options":[{"id":"a","text":"Inhibition of DNA repair mechanisms"},{"id":"b","text":"Integration into host DNA"},{"id":"c","text":"Inactivation of p53 and Rb proteins"},{"id":"d","text":"Induction of chronic inflammation"}],"answerId":"c","explanation":"High-risk HPV types 16 and 18 produce E6 and E7 oncoproteins, which inactivate the tumor suppressor proteins p53 and Rb, leading to uncontrolled cell proliferation.","kind":"mechanism","origin":"ai"},{"id":"dna-viruses-other~ai-1","moduleId":"dna-viruses-other","stem":"Which serological marker indicates a chronic Hepatitis B virus infection?","options":[{"id":"a","text":"Anti-HBs positive"},{"id":"b","text":"HBsAg positive"},{"id":"c","text":"Anti-HBc IgM positive"},{"id":"d","text":"HBeAg negative"}],"answerId":"b","explanation":"HBsAg positivity indicates active Hepatitis B virus infection, which can be chronic if present for more than six months.","kind":"recall","origin":"ai"},{"id":"dna-viruses-other~ai-2","moduleId":"dna-viruses-other","stem":"A patient presents with a 'slapped cheek' rash and is diagnosed with parvovirus B19. What is a potential complication in patients with sickle cell disease?","options":[{"id":"a","text":"Aplastic crisis"},{"id":"b","text":"Cirrhosis"},{"id":"c","text":"Cervical cancer"},{"id":"d","text":"Progressive multifocal leukoencephalopathy"}],"answerId":"a","explanation":"Parvovirus B19 can cause aplastic crisis in patients with sickle cell disease due to its effect on erythroid progenitor cells.","kind":"clinical","origin":"ai"},{"id":"dna-viruses-other~ai-3","moduleId":"dna-viruses-other","stem":"Which of the following statements about Hepatitis B serology is true?","options":[{"id":"a","text":"HBsAg positive indicates immunity"},{"id":"b","text":"Anti-HBs positive indicates active infection"},{"id":"c","text":"Anti-HBc IgG indicates past infection"},{"id":"d","text":"HBeAg positive indicates low infectivity"}],"answerId":"c","explanation":"Anti-HBc IgG indicates past infection with Hepatitis B virus, distinguishing it from active infection markers.","kind":"trap","origin":"ai"},{"id":"dna-viruses-other~ai-4","moduleId":"dna-viruses-other","stem":"What is the primary mode of transmission for Hepatitis B virus?","options":[{"id":"a","text":"Airborne"},{"id":"b","text":"Fecal-oral"},{"id":"c","text":"Bloodborne and sexual"},{"id":"d","text":"Vector-borne"}],"answerId":"c","explanation":"Hepatitis B virus is primarily transmitted through blood, sexual contact, and from mother to child during childbirth.","kind":"recall","origin":"ai"},{"id":"dna-viruses-other~ai-5","moduleId":"dna-viruses-other","stem":"Which virus is known for causing progressive multifocal leukoencephalopathy in immunocompromised patients?","options":[{"id":"a","text":"Hepatitis B virus"},{"id":"b","text":"JC polyomavirus"},{"id":"c","text":"Human papillomavirus"},{"id":"d","text":"Adenovirus"}],"answerId":"b","explanation":"JC polyomavirus is associated with progressive multifocal leukoencephalopathy, particularly in patients with weakened immune systems.","kind":"recall","origin":"ai"},{"id":"dna-viruses-other~ai-6","moduleId":"dna-viruses-other","stem":"How does the mechanism of action of antiviral agents for Hepatitis B differ from those used for herpesviruses?","options":[{"id":"a","text":"Hepatitis B antivirals inhibit reverse transcriptase"},{"id":"b","text":"Herpesvirus antivirals inhibit DNA polymerase"},{"id":"c","text":"Both target the same viral proteins"},{"id":"d","text":"Hepatitis B antivirals are not effective against herpesviruses"}],"answerId":"a","explanation":"Antivirals for Hepatitis B specifically inhibit reverse transcriptase, while those for herpesviruses typically inhibit viral DNA polymerase.","kind":"integration","linkedModuleIds":["antiviral-antiretroviral-agents"],"origin":"ai"},{"id":"dna-viruses-other~ai-7","moduleId":"dna-viruses-other","stem":"Which of the following is a characteristic of poxviruses compared to other DNA viruses?","options":[{"id":"a","text":"Replicate in the nucleus"},{"id":"b","text":"Are the largest viruses"},{"id":"c","text":"Cause respiratory infections"},{"id":"d","text":"Have a high mutation rate"}],"answerId":"b","explanation":"Poxviruses are the largest DNA viruses and uniquely replicate in the cytoplasm, unlike most other DNA viruses that replicate in the nucleus.","kind":"integration","linkedModuleIds":["virology-principles-classification"],"origin":"ai"}],"coagulase-negative-staphylococci":[{"id":"coagulase-negative-staphylococci~ai-0","moduleId":"coagulase-negative-staphylococci","stem":"Which coagulase-negative staphylococcus is known for causing device-related infections due to its biofilm production?","options":[{"id":"a","text":"Staphylococcus saprophyticus"},{"id":"b","text":"Staphylococcus epidermidis"},{"id":"c","text":"Staphylococcus aureus"},{"id":"d","text":"Staphylococcus hominis"}],"answerId":"b","explanation":"Staphylococcus epidermidis is known for its ability to form biofilms on prosthetic devices, leading to infections.","kind":"recall","origin":"ai"},{"id":"coagulase-negative-staphylococci~ai-1","moduleId":"coagulase-negative-staphylococci","stem":"What is the primary distinguishing test for differentiating Staphylococcus saprophyticus from Staphylococcus epidermidis?","options":[{"id":"a","text":"Catalase test"},{"id":"b","text":"Coagulase test"},{"id":"c","text":"Novobiocin sensitivity test"},{"id":"d","text":"Mannitol fermentation test"}],"answerId":"c","explanation":"The novobiocin sensitivity test distinguishes Staphylococcus saprophyticus (resistant) from Staphylococcus epidermidis (sensitive).","kind":"recall","origin":"ai"},{"id":"coagulase-negative-staphylococci~ai-2","moduleId":"coagulase-negative-staphylococci","stem":"A young woman presents with dysuria and frequent urination. A urine culture reveals a novobiocin-resistant coagulase-negative staphylococcus. What is the likely pathogen?","options":[{"id":"a","text":"Staphylococcus epidermidis"},{"id":"b","text":"Staphylococcus saprophyticus"},{"id":"c","text":"Staphylococcus aureus"},{"id":"d","text":"Staphylococcus lugdunensis"}],"answerId":"b","explanation":"Staphylococcus saprophyticus is a common cause of urinary tract infections in young women, especially when novobiocin-resistant.","kind":"clinical","origin":"ai"},{"id":"coagulase-negative-staphylococci~ai-3","moduleId":"coagulase-negative-staphylococci","stem":"What clinical finding suggests that a positive blood culture for Staphylococcus epidermidis is likely a contaminant?","options":[{"id":"a","text":"Multiple positive blood cultures"},{"id":"b","text":"Presence of prosthetic devices"},{"id":"c","text":"Single positive culture in a well patient"},{"id":"d","text":"Fever and hypotension"}],"answerId":"c","explanation":"A single positive blood culture for Staphylococcus epidermidis in a well patient is often a contaminant due to its presence as a skin commensal.","kind":"trap","origin":"ai"},{"id":"coagulase-negative-staphylococci~ai-4","moduleId":"coagulase-negative-staphylococci","stem":"In a patient with a CSF shunt infection caused by a coagulase-negative staphylococcus, which species is most likely responsible?","options":[{"id":"a","text":"Staphylococcus saprophyticus"},{"id":"b","text":"Staphylococcus epidermidis"},{"id":"c","text":"Staphylococcus aureus"},{"id":"d","text":"Staphylococcus hominis"}],"answerId":"b","explanation":"Staphylococcus epidermidis is known for causing infections related to indwelling devices such as CSF shunts due to biofilm formation.","kind":"clinical","origin":"ai"},{"id":"coagulase-negative-staphylococci~ai-5","moduleId":"coagulase-negative-staphylococci","stem":"How does the mechanism of Staphylococcus saprophyticus differ from that of Staphylococcus epidermidis in urinary tract infections?","options":[{"id":"a","text":"Biofilm formation"},{"id":"b","text":"Novobiocin resistance"},{"id":"c","text":"Catalase production"},{"id":"d","text":"Coagulase activity"}],"answerId":"b","explanation":"Staphylococcus saprophyticus is novobiocin-resistant, distinguishing it from Staphylococcus epidermidis, which is sensitive.","kind":"integration","linkedModuleIds":["uti-pathogenesis-microbiology"],"origin":"ai"},{"id":"coagulase-negative-staphylococci~ai-6","moduleId":"coagulase-negative-staphylococci","stem":"What is the primary reason for removing a prosthetic device in cases of Staphylococcus epidermidis infection?","options":[{"id":"a","text":"Antibiotic resistance"},{"id":"b","text":"Biofilm formation"},{"id":"c","text":"Patient age"},{"id":"d","text":"Presence of fever"}],"answerId":"b","explanation":"Biofilm formation by Staphylococcus epidermidis on prosthetic devices necessitates removal of the device to effectively treat the infection.","kind":"clinical","origin":"ai"},{"id":"coagulase-negative-staphylococci~ai-7","moduleId":"coagulase-negative-staphylococci","stem":"Which coagulase-negative staphylococcus is primarily associated with uncomplicated urinary tract infections in young women?","options":[{"id":"a","text":"Staphylococcus epidermidis"},{"id":"b","text":"Staphylococcus saprophyticus"},{"id":"c","text":"Staphylococcus aureus"},{"id":"d","text":"Staphylococcus lugdunensis"}],"answerId":"b","explanation":"Staphylococcus saprophyticus is a leading cause of uncomplicated urinary tract infections in young, sexually active women.","kind":"recall","origin":"ai"}],"mycobacterium-tuberculosis-leprae":[{"id":"mycobacterium-tuberculosis-leprae~ai-0","moduleId":"mycobacterium-tuberculosis-leprae","stem":"What is the primary mechanism by which Mycobacterium tuberculosis evades the immune response?","options":[{"id":"a","text":"Production of exotoxins"},{"id":"b","text":"Waxy mycolic acid-rich cell wall"},{"id":"c","text":"Formation of biofilms"},{"id":"d","text":"Rapid replication in host cells"}],"answerId":"b","explanation":"The waxy mycolic acid-rich cell wall of Mycobacterium tuberculosis prevents phagocytosis and contributes to its acid-fast nature.","kind":"mechanism","origin":"ai"},{"id":"mycobacterium-tuberculosis-leprae~ai-1","moduleId":"mycobacterium-tuberculosis-leprae","stem":"A patient presents with night sweats, weight loss, and a cough. A sputum smear shows acid-fast bacilli. What is the most likely diagnosis?","options":[{"id":"a","text":"Latent tuberculosis"},{"id":"b","text":"Primary tuberculosis"},{"id":"c","text":"Reactivation tuberculosis"},{"id":"d","text":"Tuberculous meningitis"}],"answerId":"c","explanation":"The presence of symptoms and acid-fast bacilli in the sputum indicates reactivation tuberculosis.","kind":"clinical","origin":"ai"},{"id":"mycobacterium-tuberculosis-leprae~ai-2","moduleId":"mycobacterium-tuberculosis-leprae","stem":"Which of the following findings is characteristic of tuberculoid leprosy?","options":[{"id":"a","text":"Numerous skin lesions with a high bacillary load"},{"id":"b","text":"Hypopigmented anaesthetic patches with thickened nerves"},{"id":"c","text":"Leonine facies"},{"id":"d","text":"Caseating granulomas"}],"answerId":"b","explanation":"Tuberculoid leprosy is characterized by hypopigmented anaesthetic patches and thickened nerves due to strong cell-mediated immunity.","kind":"recall","origin":"ai"},{"id":"mycobacterium-tuberculosis-leprae~ai-3","moduleId":"mycobacterium-tuberculosis-leprae","stem":"What does a positive tuberculin skin test indicate?","options":[{"id":"a","text":"Active tuberculosis infection"},{"id":"b","text":"Latent tuberculosis infection"},{"id":"c","text":"Recent exposure to tuberculosis"},{"id":"d","text":"None of the above"}],"answerId":"b","explanation":"A positive tuberculin skin test indicates latent tuberculosis infection, not necessarily active disease.","kind":"trap","origin":"ai"},{"id":"mycobacterium-tuberculosis-leprae~ai-4","moduleId":"mycobacterium-tuberculosis-leprae","stem":"In a patient with HIV, which finding would suggest reactivation of tuberculosis?","options":[{"id":"a","text":"Positive IGRA test"},{"id":"b","text":"Acid-fast bacilli in sputum"},{"id":"c","text":"Caseating granulomas on biopsy"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"All of these findings can indicate reactivation of tuberculosis, especially in an immunocompromised patient.","kind":"clinical","origin":"ai"},{"id":"mycobacterium-tuberculosis-leprae~ai-5","moduleId":"mycobacterium-tuberculosis-leprae","stem":"Which drug is NOT part of the RIPE regimen for treating active tuberculosis?","options":[{"id":"a","text":"Rifampicin"},{"id":"b","text":"Isoniazid"},{"id":"c","text":"Pyrazinamide"},{"id":"d","text":"Clofazimine"}],"answerId":"d","explanation":"Clofazimine is not part of the RIPE regimen; it is used for leprosy treatment.","kind":"recall","origin":"ai"},{"id":"mycobacterium-tuberculosis-leprae~ai-6","moduleId":"mycobacterium-tuberculosis-leprae","stem":"How does the structure of the mycobacterial cell wall relate to its pathogenicity?","options":[{"id":"a","text":"It allows rapid replication"},{"id":"b","text":"It prevents antibiotic penetration"},{"id":"c","text":"It enhances biofilm formation"},{"id":"d","text":"It promotes host cell invasion"}],"answerId":"b","explanation":"The mycobacterial cell wall's unique structure prevents antibiotic penetration, contributing to its pathogenicity.","kind":"integration","linkedModuleIds":["bacterial-structure-cell-wall"],"origin":"ai"},{"id":"mycobacterium-tuberculosis-leprae~ai-7","moduleId":"mycobacterium-tuberculosis-leprae","stem":"What is the primary immune response involved in the formation of caseating granulomas in tuberculosis?","options":[{"id":"a","text":"Th2 response"},{"id":"b","text":"Th1 response"},{"id":"c","text":"B-cell activation"},{"id":"d","text":"Cytotoxic T-cell response"}],"answerId":"b","explanation":"The Th1 immune response is primarily involved in the formation of caseating granulomas in tuberculosis.","kind":"integration","linkedModuleIds":["tuberculosis-pathology"],"origin":"ai"}],"rickettsia-orientia-coxiella":[{"id":"rickettsia-orientia-coxiella~ai-0","moduleId":"rickettsia-orientia-coxiella","stem":"What is the primary treatment for suspected scrub typhus in endemic regions?","options":[{"id":"a","text":"Ciprofloxacin"},{"id":"b","text":"Doxycycline"},{"id":"c","text":"Azithromycin"},{"id":"d","text":"Rifampin"}],"answerId":"b","explanation":"Doxycycline is the first-line treatment for scrub typhus and should be administered empirically in endemic areas.","kind":"recall","origin":"ai"},{"id":"rickettsia-orientia-coxiella~ai-1","moduleId":"rickettsia-orientia-coxiella","stem":"Which organism is primarily responsible for scrub typhus?","options":[{"id":"a","text":"Coxiella burnetii"},{"id":"b","text":"Orientia tsutsugamushi"},{"id":"c","text":"Rickettsia rickettsii"},{"id":"d","text":"Anaplasma phagocytophilum"}],"answerId":"b","explanation":"Orientia tsutsugamushi is the causative agent of scrub typhus.","kind":"recall","origin":"ai"},{"id":"rickettsia-orientia-coxiella~ai-2","moduleId":"rickettsia-orientia-coxiella","stem":"What is a classic clinical finding in scrub typhus?","options":[{"id":"a","text":"Centrifugal rash"},{"id":"b","text":"Inoculation eschar"},{"id":"c","text":"Pneumonia with rash"},{"id":"d","text":"Morulae in leukocytes"}],"answerId":"b","explanation":"An inoculation eschar is a hallmark sign of scrub typhus, often accompanied by fever and lymphadenopathy.","kind":"recall","origin":"ai"},{"id":"rickettsia-orientia-coxiella~ai-3","moduleId":"rickettsia-orientia-coxiella","stem":"What is the mechanism of action of doxycycline in treating rickettsial infections?","options":[{"id":"a","text":"Inhibition of cell wall synthesis"},{"id":"b","text":"Inhibition of protein synthesis"},{"id":"c","text":"Inhibition of nucleic acid synthesis"},{"id":"d","text":"Disruption of metabolic pathways"}],"answerId":"b","explanation":"Doxycycline inhibits protein synthesis by binding to the 30S ribosomal subunit, effective against rickettsial bacteria.","kind":"mechanism","origin":"ai"},{"id":"rickettsia-orientia-coxiella~ai-4","moduleId":"rickettsia-orientia-coxiella","stem":"Which of the following is a common complication of scrub typhus?","options":[{"id":"a","text":"Chronic endocarditis"},{"id":"b","text":"Meningoencephalitis"},{"id":"c","text":"Hemolytic anemia"},{"id":"d","text":"Septic arthritis"}],"answerId":"b","explanation":"Meningoencephalitis is a recognized complication of scrub typhus due to the infection's impact on the central nervous system.","kind":"trap","origin":"ai"},{"id":"rickettsia-orientia-coxiella~ai-5","moduleId":"rickettsia-orientia-coxiella","stem":"In a patient with scrub typhus, which finding would you expect to see on a blood smear?","options":[{"id":"a","text":"Morulae in leukocytes"},{"id":"b","text":"Gram-positive cocci"},{"id":"c","text":"Spore-forming bacilli"},{"id":"d","text":"No significant findings"}],"answerId":"d","explanation":"Scrub typhus does not typically show specific findings on a blood smear, unlike infections with Anaplasma or Ehrlichia.","kind":"trap","origin":"ai"},{"id":"rickettsia-orientia-coxiella~ai-6","moduleId":"rickettsia-orientia-coxiella","stem":"How does the transmission of Orientia tsutsugamushi differ from that of Coxiella burnetii?","options":[{"id":"a","text":"Both are transmitted by ticks"},{"id":"b","text":"Orientia is transmitted by mites, Coxiella by inhalation"},{"id":"c","text":"Both require direct contact with animals"},{"id":"d","text":"Coxiella is transmitted by mites"}],"answerId":"b","explanation":"Orientia tsutsugamushi is transmitted by mite bites, while Coxiella burnetii is primarily transmitted through inhalation of contaminated aerosols from livestock.","kind":"integration","linkedModuleIds":["medical-mites-acarology"],"origin":"ai"},{"id":"rickettsia-orientia-coxiella~ai-7","moduleId":"rickettsia-orientia-coxiella","stem":"Which of the following statements about rickettsial infections is true?","options":[{"id":"a","text":"They are primarily transmitted by mosquitoes"},{"id":"b","text":"They are obligate extracellular bacteria"},{"id":"c","text":"They cause fever, headache, and rash"},{"id":"d","text":"They are easily cultured in standard media"}],"answerId":"c","explanation":"Rickettsial infections, including scrub typhus, typically present with fever, headache, and rash due to their endothelial targeting.","kind":"integration","linkedModuleIds":["bacterial-physiology-growth-identification"],"origin":"ai"}],"enterobacterales-ecoli-klebsiella":[{"id":"enterobacterales-ecoli-klebsiella~ai-0","moduleId":"enterobacterales-ecoli-klebsiella","stem":"What is the primary mechanism of action of the Shiga toxin produced by EHEC O157:H7?","options":[{"id":"a","text":"Inhibition of protein synthesis"},{"id":"b","text":"Inhibition of DNA replication"},{"id":"c","text":"Activation of adenylate cyclase"},{"id":"d","text":"Disruption of cell membrane integrity"}],"answerId":"a","explanation":"Shiga toxin inhibits protein synthesis by cleaving the 28S rRNA of the ribosome, leading to cell death.","kind":"mechanism","origin":"ai"},{"id":"enterobacterales-ecoli-klebsiella~ai-1","moduleId":"enterobacterales-ecoli-klebsiella","stem":"Which of the following is a characteristic finding in a patient with Klebsiella pneumonia?","options":[{"id":"a","text":"Green sputum production"},{"id":"b","text":"Currant-jelly sputum"},{"id":"c","text":"Foul-smelling sputum"},{"id":"d","text":"Rusty sputum"}],"answerId":"b","explanation":"Klebsiella pneumonia is associated with currant-jelly sputum due to its mucoid capsule.","kind":"recall","origin":"ai"},{"id":"enterobacterales-ecoli-klebsiella~ai-2","moduleId":"enterobacterales-ecoli-klebsiella","stem":"What is the most appropriate management for a patient with EHEC O157:H7 infection presenting with bloody diarrhea?","options":[{"id":"a","text":"Immediate antibiotic therapy"},{"id":"b","text":"Supportive care only"},{"id":"c","text":"Intravenous fluids and antibiotics"},{"id":"d","text":"Antimotility agents"}],"answerId":"b","explanation":"In EHEC infections, antibiotics are avoided as they can increase the risk of hemolytic-uremic syndrome; supportive care is the correct approach.","kind":"trap","origin":"ai"},{"id":"enterobacterales-ecoli-klebsiella~ai-3","moduleId":"enterobacterales-ecoli-klebsiella","stem":"Which Enterobacterales species is most commonly associated with urinary tract infections?","options":[{"id":"a","text":"Klebsiella pneumoniae"},{"id":"b","text":"Enterobacter cloacae"},{"id":"c","text":"Escherichia coli"},{"id":"d","text":"Serratia marcescens"}],"answerId":"c","explanation":"Escherichia coli is the most common cause of urinary tract infections.","kind":"recall","origin":"ai"},{"id":"enterobacterales-ecoli-klebsiella~ai-4","moduleId":"enterobacterales-ecoli-klebsiella","stem":"A patient presents with watery diarrhea after traveling to a developing country. Which E. coli pathotype is most likely responsible?","options":[{"id":"a","text":"EHEC"},{"id":"b","text":"EPEC"},{"id":"c","text":"ETEC"},{"id":"d","text":"EIEC"}],"answerId":"c","explanation":"Enterotoxigenic E. coli (ETEC) is commonly associated with traveler's diarrhea due to its heat-labile and heat-stable toxins.","kind":"clinical","origin":"ai"},{"id":"enterobacterales-ecoli-klebsiella~ai-5","moduleId":"enterobacterales-ecoli-klebsiella","stem":"Which mechanism of resistance is primarily responsible for cephalosporin resistance in Klebsiella pneumoniae?","options":[{"id":"a","text":"Altered penicillin-binding proteins"},{"id":"b","text":"Extended-spectrum β-lactamases (ESBLs)"},{"id":"c","text":"Efflux pumps"},{"id":"d","text":"Decreased permeability"}],"answerId":"b","explanation":"Extended-spectrum β-lactamases (ESBLs) are enzymes that confer resistance to cephalosporins and are commonly found in Klebsiella pneumoniae.","kind":"mechanism","origin":"ai"},{"id":"enterobacterales-ecoli-klebsiella~ai-6","moduleId":"enterobacterales-ecoli-klebsiella","stem":"How does the virulence of uropathogenic E. coli (UPEC) contribute to urinary tract infections?","options":[{"id":"a","text":"By producing Shiga toxin"},{"id":"b","text":"By forming biofilms"},{"id":"c","text":"By having a polysaccharide capsule"},{"id":"d","text":"By expressing type 1 fimbriae"}],"answerId":"d","explanation":"Uropathogenic E. coli expresses type 1 fimbriae, which facilitate adherence to the uroepithelium, a key factor in the pathogenesis of urinary tract infections.","kind":"integration","linkedModuleIds":["uropathogenic-ecoli-virulence"],"origin":"ai"},{"id":"enterobacterales-ecoli-klebsiella~ai-7","moduleId":"enterobacterales-ecoli-klebsiella","stem":"What is a common feature shared between E. coli and Klebsiella in terms of laboratory identification?","options":[{"id":"a","text":"Both are oxidase-positive"},{"id":"b","text":"Both ferment lactose"},{"id":"c","text":"Both produce hydrogen sulfide"},{"id":"d","text":"Both are urease-positive"}],"answerId":"b","explanation":"Both E. coli and Klebsiella are lactose fermenters, which can be identified by pink colonies on MacConkey agar.","kind":"integration","linkedModuleIds":["uti-pathogenesis-microbiology"],"origin":"ai"}],"vibrio-campylobacter-helicobacter":[{"id":"vibrio-campylobacter-helicobacter~ai-0","moduleId":"vibrio-campylobacter-helicobacter","stem":"What is the primary mechanism by which cholera toxin causes diarrhea?","options":[{"id":"a","text":"Inhibition of protein synthesis"},{"id":"b","text":"ADP-ribosylation of Gs protein"},{"id":"c","text":"Activation of phospholipase C"},{"id":"d","text":"Inhibition of adenylate cyclase"}],"answerId":"b","explanation":"Cholera toxin ADP-ribosylates the Gs protein, leading to persistent activation of adenylate cyclase and increased cAMP, which drives chloride and water secretion into the intestinal lumen.","kind":"mechanism","origin":"ai"},{"id":"vibrio-campylobacter-helicobacter~ai-1","moduleId":"vibrio-campylobacter-helicobacter","stem":"Which of the following is a classic clinical finding in a patient with cholera?","options":[{"id":"a","text":"Bloody diarrhea"},{"id":"b","text":"Rice-water stools"},{"id":"c","text":"Foul-smelling stools"},{"id":"d","text":"Mucus in stools"}],"answerId":"b","explanation":"Cholera is characterized by profuse, painless 'rice-water' stools due to the massive secretion of water and electrolytes.","kind":"recall","origin":"ai"},{"id":"vibrio-campylobacter-helicobacter~ai-2","moduleId":"vibrio-campylobacter-helicobacter","stem":"What is the most critical initial treatment for a patient with cholera?","options":[{"id":"a","text":"Antibiotics"},{"id":"b","text":"Intravenous fluids"},{"id":"c","text":"Oral rehydration solution"},{"id":"d","text":"Electrolyte replacement"}],"answerId":"c","explanation":"The life-saving priority in cholera is aggressive rehydration, either through oral rehydration solutions or IV fluids, to replace fluid losses.","kind":"trap","origin":"ai"},{"id":"vibrio-campylobacter-helicobacter~ai-3","moduleId":"vibrio-campylobacter-helicobacter","stem":"Which organism is most commonly associated with Guillain-Barré syndrome?","options":[{"id":"a","text":"Helicobacter pylori"},{"id":"b","text":"Vibrio cholerae"},{"id":"c","text":"Campylobacter jejuni"},{"id":"d","text":"Escherichia coli"}],"answerId":"c","explanation":"Campylobacter jejuni is the most common antecedent infection associated with Guillain-Barré syndrome due to molecular mimicry.","kind":"recall","origin":"ai"},{"id":"vibrio-campylobacter-helicobacter~ai-4","moduleId":"vibrio-campylobacter-helicobacter","stem":"A patient presents with peptic ulcer disease and a positive urea breath test. What organism is most likely responsible?","options":[{"id":"a","text":"Vibrio cholerae"},{"id":"b","text":"Campylobacter jejuni"},{"id":"c","text":"Helicobacter pylori"},{"id":"d","text":"Escherichia coli"}],"answerId":"c","explanation":"Helicobacter pylori is known for causing peptic ulcers and is detected using the urea breath test due to its urease activity.","kind":"clinical","origin":"ai"},{"id":"vibrio-campylobacter-helicobacter~ai-5","moduleId":"vibrio-campylobacter-helicobacter","stem":"A patient with a history of cirrhosis develops wound sepsis after exposure to seawater. Which organism is most likely involved?","options":[{"id":"a","text":"Vibrio parahaemolyticus"},{"id":"b","text":"Vibrio vulnificus"},{"id":"c","text":"Campylobacter jejuni"},{"id":"d","text":"Helicobacter pylori"}],"answerId":"b","explanation":"Vibrio vulnificus is associated with wound infections in individuals with liver disease after exposure to seawater.","kind":"clinical","origin":"ai"},{"id":"vibrio-campylobacter-helicobacter~ai-6","moduleId":"vibrio-campylobacter-helicobacter","stem":"How does Helicobacter pylori contribute to gastric cancer risk?","options":[{"id":"a","text":"By increasing gastric acid secretion"},{"id":"b","text":"By causing chronic inflammation"},{"id":"c","text":"By producing cholera toxin"},{"id":"d","text":"By inhibiting gastric motility"}],"answerId":"b","explanation":"Helicobacter pylori causes chronic gastritis, leading to inflammation and an increased risk of gastric cancer over time.","kind":"integration","linkedModuleIds":["nucleotide-degradation-gout"],"origin":"ai"},{"id":"vibrio-campylobacter-helicobacter~ai-7","moduleId":"vibrio-campylobacter-helicobacter","stem":"Which of the following best explains the mechanism of action of the cholera toxin in relation to cAMP levels?","options":[{"id":"a","text":"Inhibition of cAMP degradation"},{"id":"b","text":"Inhibition of cAMP synthesis"},{"id":"c","text":"Activation of cAMP-dependent protein kinase"},{"id":"d","text":"Stimulation of cAMP synthesis"}],"answerId":"d","explanation":"Cholera toxin stimulates adenylate cyclase, leading to increased levels of cAMP, which causes massive fluid secretion.","kind":"integration","linkedModuleIds":["enterobacterales-ecoli-klebsiella"],"origin":"ai"}],"chlamydia-species":[{"id":"chlamydia-species~ai-0","moduleId":"chlamydia-species","stem":"What is the primary infectious form of Chlamydia trachomatis that enters host cells?","options":[{"id":"a","text":"Elementary Body"},{"id":"b","text":"Reticulate Body"},{"id":"c","text":"Cytoplasmic Inclusion"},{"id":"d","text":"Mature Body"}],"answerId":"a","explanation":"The Elementary Body (EB) is the small, infectious form that enters host cells, while the Reticulate Body (RB) is the replicating form.","kind":"recall","origin":"ai"},{"id":"chlamydia-species~ai-1","moduleId":"chlamydia-species","stem":"Which serovar of Chlamydia trachomatis is primarily associated with trachoma?","options":[{"id":"a","text":"D–K"},{"id":"b","text":"A–C"},{"id":"c","text":"L1–L3"},{"id":"d","text":"C. pneumoniae"}],"answerId":"b","explanation":"Serovars A–C of Chlamydia trachomatis are responsible for trachoma, which can lead to blindness.","kind":"recall","origin":"ai"},{"id":"chlamydia-species~ai-2","moduleId":"chlamydia-species","stem":"A patient presents with a painless genital ulcer and tender inguinal buboes. Which serovar of Chlamydia trachomatis is likely responsible?","options":[{"id":"a","text":"A–C"},{"id":"b","text":"D–K"},{"id":"c","text":"L1–L3"},{"id":"d","text":"C. pneumoniae"}],"answerId":"c","explanation":"Serovars L1–L3 of Chlamydia trachomatis cause Lymphogranuloma Venereum, characterized by painless genital ulcers and tender inguinal buboes.","kind":"clinical","origin":"ai"},{"id":"chlamydia-species~ai-3","moduleId":"chlamydia-species","stem":"Which of the following best describes the role of the reticulate body in the Chlamydia life cycle?","options":[{"id":"a","text":"Infectious form that spreads disease"},{"id":"b","text":"Metabolically active, replicating form"},{"id":"c","text":"Extracellular form that enters cells"},{"id":"d","text":"Form that causes scarring in trachoma"}],"answerId":"b","explanation":"The reticulate body (RB) is the metabolically active and replicating form of Chlamydia that is not infectious.","kind":"mechanism","origin":"ai"},{"id":"chlamydia-species~ai-4","moduleId":"chlamydia-species","stem":"A 2-month-old infant presents with afebrile staccato cough and conjunctivitis. What is the most likely causative agent?","options":[{"id":"a","text":"C. pneumoniae"},{"id":"b","text":"C. psittaci"},{"id":"c","text":"C. trachomatis"},{"id":"d","text":"Neisseria gonorrhoeae"}],"answerId":"c","explanation":"Neonatal conjunctivitis and pneumonia in infants can be caused by Chlamydia trachomatis, presenting with a staccato cough.","kind":"clinical","origin":"ai"},{"id":"chlamydia-species~ai-5","moduleId":"chlamydia-species","stem":"Which of the following treatments is appropriate for a Chlamydia trachomatis infection?","options":[{"id":"a","text":"Amoxicillin"},{"id":"b","text":"Doxycycline"},{"id":"c","text":"Ciprofloxacin"},{"id":"d","text":"Vancomycin"}],"answerId":"b","explanation":"Doxycycline and azithromycin are the recommended treatments for Chlamydia trachomatis infections, as β-lactams are ineffective.","kind":"trap","origin":"ai"},{"id":"chlamydia-species~ai-6","moduleId":"chlamydia-species","stem":"How does Chlamydia pneumoniae primarily spread and what condition does it cause?","options":[{"id":"a","text":"Aerosol transmission; atypical pneumonia"},{"id":"b","text":"Direct contact; trachoma"},{"id":"c","text":"Sexual transmission; LGV"},{"id":"d","text":"Fecal-oral; gastroenteritis"}],"answerId":"a","explanation":"Chlamydia pneumoniae spreads via aerosol transmission and is known to cause atypical pneumonia.","kind":"integration","linkedModuleIds":["community-acquired-pneumonia"],"origin":"ai"},{"id":"chlamydia-species~ai-7","moduleId":"chlamydia-species","stem":"What is the relationship between Chlamydia trachomatis and Neisseria gonorrhoeae infections?","options":[{"id":"a","text":"They are unrelated infections"},{"id":"b","text":"Chlamydia is a co-infection with gonorrhea"},{"id":"c","text":"Gonorrhea is a precursor to Chlamydia"},{"id":"d","text":"Both cause trachoma"}],"answerId":"b","explanation":"Chlamydia trachomatis is often co-infected with Neisseria gonorrhoeae in cases of sexually transmitted infections.","kind":"integration","linkedModuleIds":["neisseria-meningitidis-gonorrhoeae"],"origin":"ai"}],"salmonella-shigella-yersinia":[{"id":"salmonella-shigella-yersinia~ai-0","moduleId":"salmonella-shigella-yersinia","stem":"Which organism is known for causing enteric fever with stepwise fever and relative bradycardia?","options":[{"id":"a","text":"Shigella dysenteriae"},{"id":"b","text":"Salmonella Typhi"},{"id":"c","text":"Yersinia enterocolitica"},{"id":"d","text":"Escherichia coli"}],"answerId":"b","explanation":"Salmonella Typhi is the causative agent of enteric fever, characterized by stepwise fever and relative bradycardia.","kind":"recall","origin":"ai"},{"id":"salmonella-shigella-yersinia~ai-1","moduleId":"salmonella-shigella-yersinia","stem":"What is the mechanism of action of Shiga toxin produced by Shigella dysenteriae?","options":[{"id":"a","text":"Inhibits protein synthesis"},{"id":"b","text":"Disrupts cell membrane integrity"},{"id":"c","text":"Activates adenylate cyclase"},{"id":"d","text":"Inhibits DNA replication"}],"answerId":"a","explanation":"Shiga toxin inhibits protein synthesis by cleaving the 28S rRNA of the ribosome, leading to cell death.","kind":"mechanism","origin":"ai"},{"id":"salmonella-shigella-yersinia~ai-2","moduleId":"salmonella-shigella-yersinia","stem":"A patient presents with bloody diarrhea, tenesmus, and a recent history of travel. What is the most likely diagnosis?","options":[{"id":"a","text":"Non-typhoidal Salmonella gastroenteritis"},{"id":"b","text":"Shigella dysentery"},{"id":"c","text":"Yersinia enterocolitica infection"},{"id":"d","text":"Typhoid fever"}],"answerId":"b","explanation":"The symptoms and low infective dose suggest Shigella dysentery, which is characterized by bloody diarrhea and tenesmus.","kind":"clinical","origin":"ai"},{"id":"salmonella-shigella-yersinia~ai-3","moduleId":"salmonella-shigella-yersinia","stem":"Which of the following statements about antibiotic treatment for bacterial gastroenteritis is true?","options":[{"id":"a","text":"All cases should be treated with antibiotics"},{"id":"b","text":"Non-typhoidal Salmonella gastroenteritis always requires antibiotics"},{"id":"c","text":"Shigella dysentery is treated with antibiotics"},{"id":"d","text":"EHEC infections should be treated with antibiotics"}],"answerId":"c","explanation":"Shigella dysentery is treated with antibiotics due to its low infectious dose and invasive nature.","kind":"trap","origin":"ai"},{"id":"salmonella-shigella-yersinia~ai-4","moduleId":"salmonella-shigella-yersinia","stem":"Which organism is associated with osteomyelitis in sickle-cell disease patients?","options":[{"id":"a","text":"Escherichia coli"},{"id":"b","text":"Shigella flexneri"},{"id":"c","text":"Salmonella species"},{"id":"d","text":"Yersinia pestis"}],"answerId":"c","explanation":"Non-typhoidal Salmonella is known to cause osteomyelitis in patients with sickle-cell disease due to its predilection for bone.","kind":"recall","origin":"ai"},{"id":"salmonella-shigella-yersinia~ai-5","moduleId":"salmonella-shigella-yersinia","stem":"How does Yersinia enterocolitica mimic appendicitis?","options":[{"id":"a","text":"Causes mesenteric adenitis"},{"id":"b","text":"Produces Shiga toxin"},{"id":"c","text":"Inhibits protein synthesis"},{"id":"d","text":"Is a lactose fermenter"}],"answerId":"a","explanation":"Yersinia enterocolitica can cause mesenteric adenitis, leading to right lower quadrant pain that mimics appendicitis.","kind":"mechanism","origin":"ai"},{"id":"salmonella-shigella-yersinia~ai-6","moduleId":"salmonella-shigella-yersinia","stem":"How does the pathophysiology of Shigella dysentery differ from that of non-typhoidal Salmonella gastroenteritis?","options":[{"id":"a","text":"Shigella is non-motile and invasive"},{"id":"b","text":"Non-typhoidal Salmonella is always treated with antibiotics"},{"id":"c","text":"Shigella does not cause bloody diarrhea"},{"id":"d","text":"Non-typhoidal Salmonella is highly invasive"}],"answerId":"a","explanation":"Shigella is non-motile and highly invasive, leading to dysentery, while non-typhoidal Salmonella typically causes self-limiting gastroenteritis.","kind":"integration","linkedModuleIds":["inflammatory-invasive-enteritis"],"origin":"ai"},{"id":"salmonella-shigella-yersinia~ai-7","moduleId":"salmonella-shigella-yersinia","stem":"What dietary management is crucial for a patient with galactosemia who also presents with diarrhea?","options":[{"id":"a","text":"Avoidance of lactose"},{"id":"b","text":"Increased protein intake"},{"id":"c","text":"Increased fiber intake"},{"id":"d","text":"Avoidance of galactose"}],"answerId":"d","explanation":"Patients with galactosemia must avoid galactose to prevent complications, including diarrhea.","kind":"integration","linkedModuleIds":["galactosemia-differential-diet"],"origin":"ai"}],"haemophilus-bordetella-small-gram-negative-rods":[{"id":"haemophilus-bordetella-small-gram-negative-rods~ai-0","moduleId":"haemophilus-bordetella-small-gram-negative-rods","stem":"What growth factors are required for Haemophilus influenzae to grow on culture media?","options":[{"id":"a","text":"Factor V (NAD) and Factor X (haemin)"},{"id":"b","text":"Factor A (thiamine) and Factor B (riboflavin)"},{"id":"c","text":"Factor C (biotin) and Factor D (folate)"},{"id":"d","text":"Factor E (pantothenic acid) and Factor F (cobalamin)"}],"answerId":"a","explanation":"Haemophilus influenzae requires Factor V (NAD) and Factor X (haemin) for growth, which is why it is cultured on chocolate agar.","kind":"recall","origin":"ai"},{"id":"haemophilus-bordetella-small-gram-negative-rods~ai-1","moduleId":"haemophilus-bordetella-small-gram-negative-rods","stem":"Which clinical finding is most characteristic of Bordetella pertussis infection?","options":[{"id":"a","text":"Cherry-red epiglottis"},{"id":"b","text":"Paroxysmal cough with inspiratory whoop"},{"id":"c","text":"Undulant fever"},{"id":"d","text":"Cellulitis after a cat bite"}],"answerId":"b","explanation":"Bordetella pertussis is known for causing a paroxysmal cough with an inspiratory whoop, especially in children.","kind":"recall","origin":"ai"},{"id":"haemophilus-bordetella-small-gram-negative-rods~ai-2","moduleId":"haemophilus-bordetella-small-gram-negative-rods","stem":"What is the mechanism of action of the pertussis toxin produced by Bordetella pertussis?","options":[{"id":"a","text":"Inhibits protein synthesis"},{"id":"b","text":"ADP-ribosylates Gi protein, increasing cAMP"},{"id":"c","text":"Increases calcium influx"},{"id":"d","text":"Inhibits neurotransmitter release"}],"answerId":"b","explanation":"The pertussis toxin ADP-ribosylates Gi protein, leading to increased cAMP levels, which contributes to the symptoms of whooping cough.","kind":"mechanism","origin":"ai"},{"id":"haemophilus-bordetella-small-gram-negative-rods~ai-3","moduleId":"haemophilus-bordetella-small-gram-negative-rods","stem":"What is the most appropriate management step for a child suspected of having epiglottitis?","options":[{"id":"a","text":"Immediate throat examination with a tongue depressor"},{"id":"b","text":"Administer antibiotics and observe"},{"id":"c","text":"Secure the airway in a controlled setting"},{"id":"d","text":"Provide humidified oxygen"}],"answerId":"c","explanation":"In suspected epiglottitis, securing the airway in a controlled setting is critical to prevent airway obstruction.","kind":"trap","origin":"ai"},{"id":"haemophilus-bordetella-small-gram-negative-rods~ai-4","moduleId":"haemophilus-bordetella-small-gram-negative-rods","stem":"A patient presents with atypical pneumonia after exposure to air conditioning systems. Which organism is most likely responsible?","options":[{"id":"a","text":"Haemophilus influenzae"},{"id":"b","text":"Bordetella pertussis"},{"id":"c","text":"Legionella pneumophila"},{"id":"d","text":"Brucella spp."}],"answerId":"c","explanation":"Legionella pneumophila is associated with atypical pneumonia, particularly after exposure to contaminated water systems or air conditioning.","kind":"recall","origin":"ai"},{"id":"haemophilus-bordetella-small-gram-negative-rods~ai-5","moduleId":"haemophilus-bordetella-small-gram-negative-rods","stem":"Which of the following is a key feature of Brucella infection?","options":[{"id":"a","text":"Paroxysmal cough"},{"id":"b","text":"Undulant fever"},{"id":"c","text":"Cherry-red epiglottis"},{"id":"d","text":"Lymphocytosis"}],"answerId":"b","explanation":"Brucella infection is characterized by undulant fever and is often associated with unpasteurized dairy products.","kind":"recall","origin":"ai"},{"id":"haemophilus-bordetella-small-gram-negative-rods~ai-6","moduleId":"haemophilus-bordetella-small-gram-negative-rods","stem":"How does the Hib vaccine impact the incidence of epiglottitis in children?","options":[{"id":"a","text":"It eliminates all respiratory infections"},{"id":"b","text":"It specifically prevents Haemophilus influenzae type b infections"},{"id":"c","text":"It reduces the need for antibiotics"},{"id":"d","text":"It has no effect on epiglottitis incidence"}],"answerId":"b","explanation":"The Hib vaccine specifically prevents infections caused by Haemophilus influenzae type b, significantly reducing the incidence of epiglottitis.","kind":"integration","linkedModuleIds":["otitis-media-sinusitis-epiglottitis"],"origin":"ai"},{"id":"haemophilus-bordetella-small-gram-negative-rods~ai-7","moduleId":"haemophilus-bordetella-small-gram-negative-rods","stem":"What is a common complication of whooping cough in infants?","options":[{"id":"a","text":"Severe dehydration"},{"id":"b","text":"Apnea"},{"id":"c","text":"Sepsis"},{"id":"d","text":"Meningitis"}],"answerId":"b","explanation":"Apnea is a common and dangerous complication of whooping cough in infants due to the severity of the coughing fits.","kind":"integration","linkedModuleIds":["otitis-media-sinusitis-epiglottitis"],"origin":"ai"}],"pseudomonas-burkholderia-nonfermenters":[{"id":"pseudomonas-burkholderia-nonfermenters~ai-0","moduleId":"pseudomonas-burkholderia-nonfermenters","stem":"What is the primary mechanism of antibiotic resistance in Pseudomonas aeruginosa?","options":[{"id":"a","text":"Efflux pumps"},{"id":"b","text":"Altered target sites"},{"id":"c","text":"Enzymatic degradation"},{"id":"d","text":"Reduced permeability"}],"answerId":"a","explanation":"Pseudomonas aeruginosa utilizes efflux pumps as a primary mechanism to expel antibiotics, contributing to its multidrug resistance.","kind":"mechanism","origin":"ai"},{"id":"pseudomonas-burkholderia-nonfermenters~ai-1","moduleId":"pseudomonas-burkholderia-nonfermenters","stem":"Which clinical finding is most indicative of Burkholderia pseudomallei infection?","options":[{"id":"a","text":"Blue-green pigmented wound"},{"id":"b","text":"Chronic mucoid sputum"},{"id":"c","text":"Pneumonia with abscesses"},{"id":"d","text":"Osteomyelitis after a puncture wound"}],"answerId":"c","explanation":"Pneumonia with abscesses is characteristic of melioidosis caused by Burkholderia pseudomallei, especially in endemic regions.","kind":"recall","origin":"ai"},{"id":"pseudomonas-burkholderia-nonfermenters~ai-2","moduleId":"pseudomonas-burkholderia-nonfermenters","stem":"A patient presents with a blue-green pigmented, fruity-smelling Gram-negative rod from a burn wound. What is the likely organism?","options":[{"id":"a","text":"Burkholderia pseudomallei"},{"id":"b","text":"Acinetobacter baumannii"},{"id":"c","text":"Stenotrophomonas maltophilia"},{"id":"d","text":"Pseudomonas aeruginosa"}],"answerId":"d","explanation":"The blue-green pigment and fruity odor are characteristic of Pseudomonas aeruginosa.","kind":"clinical","origin":"ai"},{"id":"pseudomonas-burkholderia-nonfermenters~ai-3","moduleId":"pseudomonas-burkholderia-nonfermenters","stem":"In a diabetic rice farmer from Northeast Thailand presenting with pneumonia and multi-organ abscesses, what should be suspected?","options":[{"id":"a","text":"Ordinary bacterial sepsis"},{"id":"b","text":"Melioidosis"},{"id":"c","text":"Tuberculosis"},{"id":"d","text":"Viral pneumonia"}],"answerId":"b","explanation":"The presentation is highly suggestive of melioidosis, which is endemic in that region and requires specific treatment.","kind":"trap","origin":"ai"},{"id":"pseudomonas-burkholderia-nonfermenters~ai-4","moduleId":"pseudomonas-burkholderia-nonfermenters","stem":"What is the first-line treatment for melioidosis?","options":[{"id":"a","text":"Ciprofloxacin"},{"id":"b","text":"Ceftazidime"},{"id":"c","text":"Vancomycin"},{"id":"d","text":"Amoxicillin-clavulanate"}],"answerId":"b","explanation":"Ceftazidime or a carbapenem is the first-line treatment for the intensive phase of melioidosis.","kind":"recall","origin":"ai"},{"id":"pseudomonas-burkholderia-nonfermenters~ai-5","moduleId":"pseudomonas-burkholderia-nonfermenters","stem":"How does the antibiotic resistance mechanism of Pseudomonas aeruginosa relate to Acinetobacter baumannii?","options":[{"id":"a","text":"Both use efflux pumps"},{"id":"b","text":"Both produce β-lactamases"},{"id":"c","text":"Both have low permeability"},{"id":"d","text":"Both are oxidase-positive"}],"answerId":"a","explanation":"Both Pseudomonas aeruginosa and Acinetobacter baumannii utilize efflux pumps as a key mechanism of antibiotic resistance.","kind":"integration","linkedModuleIds":["antibiotic-resistance-mechanisms"],"origin":"ai"},{"id":"pseudomonas-burkholderia-nonfermenters~ai-6","moduleId":"pseudomonas-burkholderia-nonfermenters","stem":"Which organism is known for causing hot-tub folliculitis?","options":[{"id":"a","text":"Burkholderia pseudomallei"},{"id":"b","text":"Pseudomonas aeruginosa"},{"id":"c","text":"Acinetobacter baumannii"},{"id":"d","text":"Stenotrophomonas maltophilia"}],"answerId":"b","explanation":"Pseudomonas aeruginosa is commonly associated with hot-tub folliculitis due to its presence in warm, moist environments.","kind":"recall","origin":"ai"},{"id":"pseudomonas-burkholderia-nonfermenters~ai-7","moduleId":"pseudomonas-burkholderia-nonfermenters","stem":"What is a common clinical presentation of Stenotrophomonas maltophilia infection?","options":[{"id":"a","text":"Pneumonia in cystic fibrosis"},{"id":"b","text":"Burn wound infection"},{"id":"c","text":"Ventilator-associated pneumonia"},{"id":"d","text":"Skin abscesses in diabetics"}],"answerId":"a","explanation":"Stenotrophomonas maltophilia is often implicated in pneumonia, particularly in patients with cystic fibrosis.","kind":"clinical","origin":"ai"},{"id":"pseudomonas-burkholderia-nonfermenters~ai-8","moduleId":"pseudomonas-burkholderia-nonfermenters","stem":"What is the significance of the 'safety-pin' appearance in a Gram stain?","options":[{"id":"a","text":"Indicates Pseudomonas aeruginosa"},{"id":"b","text":"Suggests Burkholderia pseudomallei"},{"id":"c","text":"Denotes Acinetobacter baumannii"},{"id":"d","text":"Represents Stenotrophomonas maltophilia"}],"answerId":"b","explanation":"The 'safety-pin' appearance is characteristic of Burkholderia pseudomallei, aiding in its identification.","kind":"recall","origin":"ai"}],"neisseria-meningitidis-gonorrhoeae":[{"id":"neisseria-meningitidis-gonorrhoeae~ai-0","moduleId":"neisseria-meningitidis-gonorrhoeae","stem":"What is the primary biochemical test that differentiates Neisseria meningitidis from Neisseria gonorrhoeae?","options":[{"id":"a","text":"Maltose fermentation"},{"id":"b","text":"Lactose fermentation"},{"id":"c","text":"Oxidase test"},{"id":"d","text":"Catalase test"}],"answerId":"a","explanation":"Neisseria meningitidis ferments maltose while Neisseria gonorrhoeae does not, making maltose fermentation the key differentiator.","kind":"recall","origin":"ai"},{"id":"neisseria-meningitidis-gonorrhoeae~ai-1","moduleId":"neisseria-meningitidis-gonorrhoeae","stem":"Which clinical finding is most indicative of meningococcal sepsis?","options":[{"id":"a","text":"Purulent conjunctivitis"},{"id":"b","text":"Non-blanching petechial rash"},{"id":"c","text":"Urethritis"},{"id":"d","text":"Bilateral adrenal hemorrhage"}],"answerId":"b","explanation":"A non-blanching petechial rash is a classic sign of meningococcal sepsis, also known as meningococcemia.","kind":"recall","origin":"ai"},{"id":"neisseria-meningitidis-gonorrhoeae~ai-2","moduleId":"neisseria-meningitidis-gonorrhoeae","stem":"What is the mechanism by which Neisseria meningitidis causes Waterhouse-Friderichsen syndrome?","options":[{"id":"a","text":"Direct invasion of adrenal glands"},{"id":"b","text":"Septic shock leading to adrenal hemorrhage"},{"id":"c","text":"Toxin production"},{"id":"d","text":"Immune complex deposition"}],"answerId":"b","explanation":"Waterhouse-Friderichsen syndrome results from septic shock due to meningococcal infection, leading to bilateral adrenal hemorrhage.","kind":"mechanism","origin":"ai"},{"id":"neisseria-meningitidis-gonorrhoeae~ai-3","moduleId":"neisseria-meningitidis-gonorrhoeae","stem":"A patient presents with recurrent Neisseria infections. What condition should be evaluated?","options":[{"id":"a","text":"Asplenia"},{"id":"b","text":"HIV infection"},{"id":"c","text":"Diabetes mellitus"},{"id":"d","text":"Chronic kidney disease"}],"answerId":"a","explanation":"Recurrent Neisseria infections should prompt evaluation for terminal complement (C5–C9) deficiency, as this predisposes to such infections.","kind":"trap","origin":"ai"},{"id":"neisseria-meningitidis-gonorrhoeae~ai-4","moduleId":"neisseria-meningitidis-gonorrhoeae","stem":"Which of the following is a common complication of untreated Neisseria gonorrhoeae infection in women?","options":[{"id":"a","text":"Meningitis"},{"id":"b","text":"Pelvic inflammatory disease"},{"id":"c","text":"Septic arthritis"},{"id":"d","text":"Bacterial conjunctivitis"}],"answerId":"b","explanation":"Untreated Neisseria gonorrhoeae infections can lead to pelvic inflammatory disease (PID) in women, which can cause infertility.","kind":"clinical","origin":"ai"},{"id":"neisseria-meningitidis-gonorrhoeae~ai-5","moduleId":"neisseria-meningitidis-gonorrhoeae","stem":"What is the recommended treatment for gonococcal ophthalmia neonatorum?","options":[{"id":"a","text":"Topical antibiotics"},{"id":"b","text":"Oral antibiotics"},{"id":"c","text":"Intravenous antibiotics"},{"id":"d","text":"Prophylactic eye drops at birth"}],"answerId":"d","explanation":"Prophylactic eye drops (usually erythromycin) are recommended at birth to prevent gonococcal ophthalmia neonatorum.","kind":"recall","origin":"ai"},{"id":"neisseria-meningitidis-gonorrhoeae~ai-6","moduleId":"neisseria-meningitidis-gonorrhoeae","stem":"How does Neisseria gonorrhoeae evade the immune response?","options":[{"id":"a","text":"Capsule formation"},{"id":"b","text":"Antigenic variation"},{"id":"c","text":"Biofilm formation"},{"id":"d","text":"Toxin production"}],"answerId":"b","explanation":"Neisseria gonorrhoeae evades the immune response through antigenic variation, particularly of its pili and Opa proteins.","kind":"mechanism","origin":"ai"},{"id":"neisseria-meningitidis-gonorrhoeae~ai-7","moduleId":"neisseria-meningitidis-gonorrhoeae","stem":"In a patient with Neisseria meningitidis infection, which laboratory finding would support a diagnosis of Waterhouse-Friderichsen syndrome?","options":[{"id":"a","text":"Elevated blood glucose"},{"id":"b","text":"Bilateral adrenal hemorrhage on imaging"},{"id":"c","text":"Increased white blood cell count"},{"id":"d","text":"Positive blood cultures for Chlamydia"}],"answerId":"b","explanation":"Bilateral adrenal hemorrhage on imaging is a key finding in Waterhouse-Friderichsen syndrome associated with Neisseria meningitidis infection.","kind":"integration","linkedModuleIds":["chlamydia-species"],"origin":"ai"},{"id":"neisseria-meningitidis-gonorrhoeae~ai-8","moduleId":"neisseria-meningitidis-gonorrhoeae","stem":"What is the relationship between Neisseria gonorrhoeae and Chlamydia species in terms of treatment?","options":[{"id":"a","text":"Both require only topical treatment"},{"id":"b","text":"They are treated with the same antibiotic"},{"id":"c","text":"Co-infection is common, requiring dual therapy"},{"id":"d","text":"Chlamydia is a vaccine-preventable disease"}],"answerId":"c","explanation":"Co-infection with Chlamydia species is common in patients with gonorrhea, necessitating dual therapy to cover both infections.","kind":"integration","linkedModuleIds":["chlamydia-species"],"origin":"ai"}],"corynebacterium-listeria":[{"id":"corynebacterium-listeria~ai-0","moduleId":"corynebacterium-listeria","stem":"What is the primary mechanism of action of diphtheria toxin?","options":[{"id":"a","text":"ADP-ribosylation of EF-2"},{"id":"b","text":"Inhibition of DNA synthesis"},{"id":"c","text":"Disruption of cell membrane integrity"},{"id":"d","text":"Inhibition of protein folding"}],"answerId":"a","explanation":"Diphtheria toxin acts by ADP-ribosylating elongation factor EF-2, halting protein synthesis.","kind":"mechanism","origin":"ai"},{"id":"corynebacterium-listeria~ai-1","moduleId":"corynebacterium-listeria","stem":"Which clinical finding is characteristic of diphtheria?","options":[{"id":"a","text":"Tumbling motility"},{"id":"b","text":"Grey adherent pseudomembrane"},{"id":"c","text":"Fever with rash"},{"id":"d","text":"Severe abdominal pain"}],"answerId":"b","explanation":"Diphtheria is characterized by a grey adherent pseudomembrane in the throat that can bleed when scraped.","kind":"recall","origin":"ai"},{"id":"corynebacterium-listeria~ai-2","moduleId":"corynebacterium-listeria","stem":"What is the recommended treatment for suspected listeriosis in a pregnant woman?","options":[{"id":"a","text":"Ciprofloxacin"},{"id":"b","text":"Ampicillin"},{"id":"c","text":"Vancomycin"},{"id":"d","text":"Cephalexin"}],"answerId":"b","explanation":"Ampicillin is the drug of choice for treating listeriosis, especially in pregnant women.","kind":"recall","origin":"ai"},{"id":"corynebacterium-listeria~ai-3","moduleId":"corynebacterium-listeria","stem":"Which of the following statements about Listeria monocytogenes is true?","options":[{"id":"a","text":"It is a spore-forming bacterium."},{"id":"b","text":"It can grow at refrigerator temperatures."},{"id":"c","text":"It is exclusively extracellular."},{"id":"d","text":"It is primarily transmitted via respiratory droplets."}],"answerId":"b","explanation":"Listeria monocytogenes can grow at refrigerator temperatures, making it a unique pathogen in foodborne illnesses.","kind":"trap","origin":"ai"},{"id":"corynebacterium-listeria~ai-4","moduleId":"corynebacterium-listeria","stem":"A 3-week-old infant presents with fever and lethargy. A Gram stain shows Gram-positive rods. What is the most likely causative organism?","options":[{"id":"a","text":"Streptococcus pneumoniae"},{"id":"b","text":"Listeria monocytogenes"},{"id":"c","text":"Escherichia coli"},{"id":"d","text":"Neisseria meningitidis"}],"answerId":"b","explanation":"Listeria monocytogenes is a leading cause of meningitis in neonates, presenting with Gram-positive rods.","kind":"recall","origin":"ai"},{"id":"corynebacterium-listeria~ai-5","moduleId":"corynebacterium-listeria","stem":"What is the primary reason for adding ampicillin to empiric meningitis treatment in the elderly?","options":[{"id":"a","text":"To cover for viral infections"},{"id":"b","text":"To treat possible Listeria monocytogenes"},{"id":"c","text":"To enhance blood-brain barrier penetration"},{"id":"d","text":"To prevent fungal infections"}],"answerId":"b","explanation":"Ampicillin is added to cover for Listeria monocytogenes, which is not adequately covered by cephalosporins.","kind":"trap","origin":"ai"},{"id":"corynebacterium-listeria~ai-6","moduleId":"corynebacterium-listeria","stem":"A patient presents with a grey pseudomembrane in the throat and myocarditis. What is the most appropriate initial management?","options":[{"id":"a","text":"Immediate intubation"},{"id":"b","text":"Administration of antibiotics only"},{"id":"c","text":"Antitoxin administration"},{"id":"d","text":"Corticosteroids"}],"answerId":"c","explanation":"The initial management for diphtheria includes administering antitoxin to neutralize circulating toxin.","kind":"clinical","origin":"ai"},{"id":"corynebacterium-listeria~ai-7","moduleId":"corynebacterium-listeria","stem":"How does the clinical presentation of diphtheria relate to the mechanisms of action of its toxin?","options":[{"id":"a","text":"It causes respiratory distress due to airway obstruction and systemic effects from toxin."},{"id":"b","text":"It leads to gastrointestinal symptoms due to intestinal invasion."},{"id":"c","text":"It primarily affects the skin leading to rashes."},{"id":"d","text":"It causes joint pain due to immune complex deposition."}],"answerId":"a","explanation":"Diphtheria toxin causes respiratory distress through airway obstruction and systemic effects such as myocarditis.","kind":"integration","linkedModuleIds":["pharyngitis-tonsillitis-diphtheria"],"origin":"ai"},{"id":"corynebacterium-listeria~ai-8","moduleId":"corynebacterium-listeria","stem":"In the context of a patient with suspected diphtheria, which linked module concept is most relevant for understanding the systemic effects of the toxin?","options":[{"id":"a","text":"Neurotoxins affecting motor function"},{"id":"b","text":"Bacterial cell wall synthesis inhibition"},{"id":"c","text":"Viral replication mechanisms"},{"id":"d","text":"Antigen-antibody interactions"}],"answerId":"a","explanation":"Understanding neurotoxin effects helps in recognizing the systemic complications such as myocarditis and neuropathy caused by diphtheria toxin.","kind":"integration","linkedModuleIds":["neurotoxins-facial-palsy"],"origin":"ai"}],"bacteroides-gram-negative-anaerobes":[{"id":"bacteroides-gram-negative-anaerobes~ai-0","moduleId":"bacteroides-gram-negative-anaerobes","stem":"What is the primary pathogen responsible for intra-abdominal abscesses following bowel perforation?","options":[{"id":"a","text":"Clostridium perfringens"},{"id":"b","text":"Bacteroides fragilis"},{"id":"c","text":"Fusobacterium necrophorum"},{"id":"d","text":"Prevotella melaninogenica"}],"answerId":"b","explanation":"Bacteroides fragilis is the leading anaerobic pathogen associated with intra-abdominal infections due to its presence in colonic flora.","kind":"recall","origin":"ai"},{"id":"bacteroides-gram-negative-anaerobes~ai-1","moduleId":"bacteroides-gram-negative-anaerobes","stem":"Which of the following characteristics is true for Bacteroides fragilis?","options":[{"id":"a","text":"It is a spore-forming anaerobe"},{"id":"b","text":"It is bile-resistant"},{"id":"c","text":"It produces catalase"},{"id":"d","text":"It is strictly aerobic"}],"answerId":"b","explanation":"Bacteroides fragilis is a bile-resistant, non-spore-forming anaerobe that lacks catalase and is killed by oxygen.","kind":"mechanism","origin":"ai"},{"id":"bacteroides-gram-negative-anaerobes~ai-2","moduleId":"bacteroides-gram-negative-anaerobes","stem":"A patient presents with foul-smelling pus and gas from an intra-abdominal abscess. Which anaerobic organism is most likely responsible?","options":[{"id":"a","text":"Clostridium difficile"},{"id":"b","text":"Bacteroides fragilis"},{"id":"c","text":"Fusobacterium necrophorum"},{"id":"d","text":"Actinomyces israelii"}],"answerId":"b","explanation":"The foul-smelling pus and gas formation are indicative of an infection caused by Bacteroides fragilis, a common anaerobic pathogen in such scenarios.","kind":"clinical","origin":"ai"},{"id":"bacteroides-gram-negative-anaerobes~ai-3","moduleId":"bacteroides-gram-negative-anaerobes","stem":"Which of the following is a common clinical finding in Lemierre syndrome caused by Fusobacterium?","options":[{"id":"a","text":"Septic internal jugular thrombophlebitis"},{"id":"b","text":"Intra-abdominal abscess"},{"id":"c","text":"Aspiration pneumonia"},{"id":"d","text":"Skin abscess"}],"answerId":"a","explanation":"Lemierre syndrome is characterized by septic thrombophlebitis of the internal jugular vein, often following pharyngitis.","kind":"recall","origin":"ai"},{"id":"bacteroides-gram-negative-anaerobes~ai-4","moduleId":"bacteroides-gram-negative-anaerobes","stem":"What is the most important step in managing an anaerobic abscess?","options":[{"id":"a","text":"Start broad-spectrum antibiotics"},{"id":"b","text":"Perform surgical drainage"},{"id":"c","text":"Administer intravenous fluids"},{"id":"d","text":"Use topical antiseptics"}],"answerId":"b","explanation":"Surgical drainage is crucial for anaerobic abscesses as antibiotics alone do not penetrate well into the walled-off collection.","kind":"trap","origin":"ai"},{"id":"bacteroides-gram-negative-anaerobes~ai-5","moduleId":"bacteroides-gram-negative-anaerobes","stem":"How does the lack of catalase and superoxide dismutase affect anaerobic bacteria?","options":[{"id":"a","text":"They can survive in oxygen-rich environments"},{"id":"b","text":"They are killed by exposure to oxygen"},{"id":"c","text":"They produce toxins in the presence of oxygen"},{"id":"d","text":"They grow faster in aerobic conditions"}],"answerId":"b","explanation":"The absence of catalase and superoxide dismutase makes anaerobic bacteria susceptible to oxidative damage from oxygen.","kind":"mechanism","origin":"ai"},{"id":"bacteroides-gram-negative-anaerobes~ai-6","moduleId":"bacteroides-gram-negative-anaerobes","stem":"Which anaerobic organism is associated with aspiration pneumonia and lung abscesses?","options":[{"id":"a","text":"Bacteroides fragilis"},{"id":"b","text":"Fusobacterium necrophorum"},{"id":"c","text":"Prevotella melaninogenica"},{"id":"d","text":"Peptostreptococcus anaerobius"}],"answerId":"c","explanation":"Prevotella species are commonly implicated in aspiration pneumonia due to their presence in oral flora.","kind":"clinical","origin":"ai"},{"id":"bacteroides-gram-negative-anaerobes~ai-7","moduleId":"bacteroides-gram-negative-anaerobes","stem":"In what way does Bacteroides fragilis relate to the module on bacterial physiology?","options":[{"id":"a","text":"It is a spore-forming anaerobe"},{"id":"b","text":"It requires aerobic conditions for growth"},{"id":"c","text":"It is bile-resistant and part of gut flora"},{"id":"d","text":"It produces toxins that damage tissues"}],"answerId":"c","explanation":"Bacteroides fragilis is a bile-resistant, non-spore-forming anaerobe that is part of the normal gut flora, linking it to bacterial physiology.","kind":"integration","linkedModuleIds":["bacterial-physiology-growth-identification"],"origin":"ai"},{"id":"bacteroides-gram-negative-anaerobes~ai-8","moduleId":"bacteroides-gram-negative-anaerobes","stem":"How does the treatment of anaerobic infections relate to the management of Nocardia infections?","options":[{"id":"a","text":"Both require surgical intervention"},{"id":"b","text":"Both are treated with the same antibiotics"},{"id":"c","text":"Both are caused by spore-forming bacteria"},{"id":"d","text":"Both require aerobic culture for diagnosis"}],"answerId":"a","explanation":"Both anaerobic infections and Nocardia infections often require surgical intervention for effective management.","kind":"integration","linkedModuleIds":["nocardia-actinomyces"],"origin":"ai"}],"clostridia-anaerobic-pathogens":[{"id":"clostridia-anaerobic-pathogens~ai-0","moduleId":"clostridia-anaerobic-pathogens","stem":"What is the primary mechanism of action of tetanospasmin in tetanus?","options":[{"id":"a","text":"Inhibition of acetylcholine release"},{"id":"b","text":"Inhibition of GABA and glycine release"},{"id":"c","text":"Activation of excitatory neurotransmitters"},{"id":"d","text":"Stimulation of muscle contraction"}],"answerId":"b","explanation":"Tetanospasmin blocks the release of inhibitory neurotransmitters (GABA and glycine), leading to spastic paralysis.","kind":"mechanism","origin":"ai"},{"id":"clostridia-anaerobic-pathogens~ai-1","moduleId":"clostridia-anaerobic-pathogens","stem":"Which clinical finding is characteristic of botulism?","options":[{"id":"a","text":"Trismus and risus sardonicus"},{"id":"b","text":"Flaccid paralysis and diplopia"},{"id":"c","text":"Crepitant myonecrosis"},{"id":"d","text":"Pseudomembranous colitis"}],"answerId":"b","explanation":"Botulism presents with descending flaccid paralysis and may include symptoms like diplopia.","kind":"recall","origin":"ai"},{"id":"clostridia-anaerobic-pathogens~ai-2","moduleId":"clostridia-anaerobic-pathogens","stem":"A patient presents with rapid onset of crepitant myonecrosis after a traumatic injury. Which organism is most likely responsible?","options":[{"id":"a","text":"C. difficile"},{"id":"b","text":"C. botulinum"},{"id":"c","text":"C. tetani"},{"id":"d","text":"C. perfringens"}],"answerId":"d","explanation":"C. perfringens is known for causing gas gangrene, characterized by rapid myonecrosis and crepitus.","kind":"clinical","origin":"ai"},{"id":"clostridia-anaerobic-pathogens~ai-3","moduleId":"clostridia-anaerobic-pathogens","stem":"What is the primary treatment for antibiotic-associated colitis caused by C. difficile?","options":[{"id":"a","text":"Metronidazole"},{"id":"b","text":"Oral vancomycin"},{"id":"c","text":"Clindamycin"},{"id":"d","text":"Fidaxomicin"}],"answerId":"b","explanation":"Oral vancomycin is the first-line treatment for C. difficile infection.","kind":"recall","origin":"ai"},{"id":"clostridia-anaerobic-pathogens~ai-4","moduleId":"clostridia-anaerobic-pathogens","stem":"Which of the following statements about tetanus and botulism is true?","options":[{"id":"a","text":"Both cause spastic paralysis"},{"id":"b","text":"Both are caused by the same toxin"},{"id":"c","text":"Tetanus causes spastic paralysis, while botulism causes flaccid paralysis"},{"id":"d","text":"Both are treated with the same antitoxin"}],"answerId":"c","explanation":"Tetanus causes spastic paralysis due to inhibition of inhibitory neurotransmitters, whereas botulism causes flaccid paralysis by blocking acetylcholine release.","kind":"trap","origin":"ai"},{"id":"clostridia-anaerobic-pathogens~ai-5","moduleId":"clostridia-anaerobic-pathogens","stem":"How does the mechanism of action of C. perfringens alpha-toxin differ from that of C. tetani?","options":[{"id":"a","text":"Both inhibit neurotransmitter release"},{"id":"b","text":"Both cause muscle paralysis"},{"id":"c","text":"C. perfringens causes cell lysis while C. tetani inhibits inhibition"},{"id":"d","text":"C. perfringens causes spastic paralysis"}],"answerId":"c","explanation":"C. perfringens alpha-toxin causes cell lysis and myonecrosis, while C. tetani inhibits inhibitory neurotransmitter release, leading to spastic paralysis.","kind":"integration","linkedModuleIds":["bacterial-structure-cell-wall"],"origin":"ai"},{"id":"clostridia-anaerobic-pathogens~ai-6","moduleId":"clostridia-anaerobic-pathogens","stem":"Which type of paralysis is associated with the action of botulinum toxin?","options":[{"id":"a","text":"Spastic paralysis"},{"id":"b","text":"Flaccid paralysis"},{"id":"c","text":"Rigid paralysis"},{"id":"d","text":"Tetanic paralysis"}],"answerId":"b","explanation":"Botulinum toxin causes flaccid paralysis by blocking the release of acetylcholine at the neuromuscular junction.","kind":"integration","linkedModuleIds":["muscle-twitch-tetanus-mechanics"],"origin":"ai"}],"mycotoxins-aflatoxin":[{"id":"mycotoxins-aflatoxin~ai-0","moduleId":"mycotoxins-aflatoxin","stem":"What is the primary mechanism by which aflatoxin B1 contributes to hepatocellular carcinoma?","options":[{"id":"a","text":"Direct liver infection by Aspergillus"},{"id":"b","text":"Formation of a DNA-damaging epoxide"},{"id":"c","text":"Inhibition of liver enzymes"},{"id":"d","text":"Induction of hepatitis B virus replication"}],"answerId":"b","explanation":"Aflatoxin B1 is metabolized by liver CYP450 to a reactive epoxide that binds DNA, leading to mutations such as p53 codon 249, which is implicated in hepatocellular carcinoma.","kind":"mechanism","origin":"ai"},{"id":"mycotoxins-aflatoxin~ai-1","moduleId":"mycotoxins-aflatoxin","stem":"Which mycotoxin is primarily associated with nephrotoxicity?","options":[{"id":"a","text":"Aflatoxin"},{"id":"b","text":"Ochratoxin"},{"id":"c","text":"Fumonisin"},{"id":"d","text":"Ergot alkaloids"}],"answerId":"b","explanation":"Ochratoxin, produced by certain molds, is known for its nephrotoxic effects.","kind":"recall","origin":"ai"},{"id":"mycotoxins-aflatoxin~ai-2","moduleId":"mycotoxins-aflatoxin","stem":"A patient presents with liver cancer and a history of dietary aflatoxin exposure. What mutation is most likely associated with this condition?","options":[{"id":"a","text":"KRAS mutation"},{"id":"b","text":"p53 mutation at codon 249"},{"id":"c","text":"TP53 mutation at codon 175"},{"id":"d","text":"BRAF mutation"}],"answerId":"b","explanation":"The p53 mutation at codon 249 is classically associated with aflatoxin exposure and hepatocellular carcinoma.","kind":"recall","origin":"ai"},{"id":"mycotoxins-aflatoxin~ai-3","moduleId":"mycotoxins-aflatoxin","stem":"Which of the following is a key preventive measure against aflatoxin exposure?","options":[{"id":"a","text":"Vaccination against hepatitis C"},{"id":"b","text":"Keeping grains dry and cool"},{"id":"c","text":"Regular liver function tests"},{"id":"d","text":"Antifungal therapy"}],"answerId":"b","explanation":"Preventing mold growth by keeping grains dry and cool is crucial to reduce aflatoxin contamination.","kind":"trap","origin":"ai"},{"id":"mycotoxins-aflatoxin~ai-4","moduleId":"mycotoxins-aflatoxin","stem":"A 35-year-old man presents with convulsions and limb ischemia after consuming moldy rye. What is the likely cause?","options":[{"id":"a","text":"Aflatoxin exposure"},{"id":"b","text":"Ochratoxin poisoning"},{"id":"c","text":"Ergotism"},{"id":"d","text":"Fumonisin toxicity"}],"answerId":"c","explanation":"Ergotism, caused by ergot alkaloids from Claviceps purpurea, leads to symptoms such as convulsions and limb ischemia.","kind":"recall","origin":"ai"},{"id":"mycotoxins-aflatoxin~ai-5","moduleId":"mycotoxins-aflatoxin","stem":"How does chronic aflatoxin exposure synergize with hepatitis B in increasing liver cancer risk?","options":[{"id":"a","text":"By enhancing liver inflammation"},{"id":"b","text":"By increasing viral replication"},{"id":"c","text":"By causing direct DNA damage"},{"id":"d","text":"By promoting liver cirrhosis"}],"answerId":"c","explanation":"Chronic aflatoxin exposure leads to direct DNA damage, which, when combined with hepatitis B infection, significantly increases the risk of hepatocellular carcinoma.","kind":"integration","linkedModuleIds":["hepatocellular-carcinoma-liver-tumors"],"origin":"ai"},{"id":"mycotoxins-aflatoxin~ai-6","moduleId":"mycotoxins-aflatoxin","stem":"Which mycotoxin is linked to esophageal cancer and neural tube defects?","options":[{"id":"a","text":"Aflatoxin"},{"id":"b","text":"Ochratoxin"},{"id":"c","text":"Fumonisin"},{"id":"d","text":"Ergot alkaloids"}],"answerId":"c","explanation":"Fumonisin, produced by Fusarium species, is associated with esophageal cancer and neural tube defects.","kind":"recall","origin":"ai"}],"talaromyces-sporothrix":[{"id":"talaromyces-sporothrix~ai-0","moduleId":"talaromyces-sporothrix","stem":"What is the primary treatment for Talaromyces marneffei infection in an HIV patient?","options":[{"id":"a","text":"Amphotericin B followed by itraconazole"},{"id":"b","text":"Itraconazole alone"},{"id":"c","text":"Fluconazole"},{"id":"d","text":"Voriconazole"}],"answerId":"a","explanation":"The treatment for Talaromyces marneffei involves an initial induction with amphotericin B followed by maintenance therapy with itraconazole.","kind":"recall","origin":"ai"},{"id":"talaromyces-sporothrix~ai-1","moduleId":"talaromyces-sporothrix","stem":"Which clinical finding is characteristic of Talaromyces marneffei infection?","options":[{"id":"a","text":"Cigar-shaped yeasts in tissue"},{"id":"b","text":"Umbilicated papules"},{"id":"c","text":"Nodular lymphangitis"},{"id":"d","text":"Erythema nodosum"}],"answerId":"b","explanation":"Umbilicated, molluscum-like papules are a classic presentation of Talaromyces marneffei infection in HIV patients.","kind":"recall","origin":"ai"},{"id":"talaromyces-sporothrix~ai-2","moduleId":"talaromyces-sporothrix","stem":"What is the mechanism of action of amphotericin B?","options":[{"id":"a","text":"Inhibition of cell wall synthesis"},{"id":"b","text":"Binding to ergosterol in cell membranes"},{"id":"c","text":"Inhibition of nucleic acid synthesis"},{"id":"d","text":"Disruption of microtubule formation"}],"answerId":"b","explanation":"Amphotericin B binds to ergosterol in fungal cell membranes, leading to increased membrane permeability and cell death.","kind":"mechanism","origin":"ai"},{"id":"talaromyces-sporothrix~ai-3","moduleId":"talaromyces-sporothrix","stem":"In which geographical region is Talaromyces marneffei most commonly found?","options":[{"id":"a","text":"North America"},{"id":"b","text":"Southeast Asia"},{"id":"c","text":"Europe"},{"id":"d","text":"Australia"}],"answerId":"b","explanation":"Talaromyces marneffei is endemic to Southeast Asia, particularly in northern Thailand and southern China.","kind":"recall","origin":"ai"},{"id":"talaromyces-sporothrix~ai-4","moduleId":"talaromyces-sporothrix","stem":"A 35-year-old HIV-positive patient presents with fever, weight loss, and umbilicated papules. What is the most likely diagnosis?","options":[{"id":"a","text":"Sporotrichosis"},{"id":"b","text":"Talaromycosis"},{"id":"c","text":"Molluscum contagiosum"},{"id":"d","text":"Cryptococcosis"}],"answerId":"b","explanation":"The combination of fever, weight loss, and umbilicated papules in an HIV patient in Southeast Asia strongly suggests Talaromycosis.","kind":"clinical","origin":"ai"},{"id":"talaromyces-sporothrix~ai-5","moduleId":"talaromyces-sporothrix","stem":"How does Sporothrix schenckii typically enter the body?","options":[{"id":"a","text":"Inhalation of spores"},{"id":"b","text":"Traumatic implantation"},{"id":"c","text":"Contaminated water exposure"},{"id":"d","text":"Insect bites"}],"answerId":"b","explanation":"Sporothrix schenckii typically enters the body through traumatic implantation from soil or plant matter, such as rose thorns.","kind":"recall","origin":"ai"},{"id":"talaromyces-sporothrix~ai-6","moduleId":"talaromyces-sporothrix","stem":"Talaromyces marneffei and Cryptococcus neoformans are both opportunistic infections in HIV patients. What is a distinguishing feature of Talaromyces marneffei?","options":[{"id":"a","text":"Cigar-shaped yeasts"},{"id":"b","text":"Transverse septation in yeast"},{"id":"c","text":"Encapsulated yeast"},{"id":"d","text":"Pulmonary involvement"}],"answerId":"b","explanation":"Talaromyces marneffei is characterized by yeast that divides by transverse septation, while Cryptococcus neoformans is known for its encapsulated yeast.","kind":"integration","linkedModuleIds":["cryptococcus-malassezia"],"origin":"ai"},{"id":"talaromyces-sporothrix~ai-7","moduleId":"talaromyces-sporothrix","stem":"Which of the following findings would suggest a diagnosis of Talaromyces marneffei rather than Sporothrix schenckii in an HIV patient?","options":[{"id":"a","text":"Ascending lymphocutaneous nodules"},{"id":"b","text":"Fever and weight loss"},{"id":"c","text":"Cigar-shaped yeasts"},{"id":"d","text":"Papules at the site of trauma"}],"answerId":"b","explanation":"Fever and weight loss are more indicative of Talaromyces marneffei infection, whereas Sporothrix schenckii typically presents with localized lymphocutaneous nodules.","kind":"integration","linkedModuleIds":["chromoblastomycosis-subcutaneous-mycoses"],"origin":"ai"}],"spirochetes-treponema-borrelia-leptospira":[{"id":"spirochetes-treponema-borrelia-leptospira~ai-0","moduleId":"spirochetes-treponema-borrelia-leptospira","stem":"What is the primary method for diagnosing syphilis caused by Treponema pallidum?","options":[{"id":"a","text":"Gram stain"},{"id":"b","text":"Darkfield microscopy"},{"id":"c","text":"Culture"},{"id":"d","text":"PCR"}],"answerId":"b","explanation":"Treponema pallidum cannot be cultured and is best diagnosed using darkfield microscopy or serological tests.","kind":"recall","origin":"ai"},{"id":"spirochetes-treponema-borrelia-leptospira~ai-1","moduleId":"spirochetes-treponema-borrelia-leptospira","stem":"Which stage of syphilis is characterized by a painless genital ulcer?","options":[{"id":"a","text":"Primary"},{"id":"b","text":"Secondary"},{"id":"c","text":"Latent"},{"id":"d","text":"Tertiary"}],"answerId":"a","explanation":"The primary stage of syphilis is marked by a single, painless chancre.","kind":"recall","origin":"ai"},{"id":"spirochetes-treponema-borrelia-leptospira~ai-2","moduleId":"spirochetes-treponema-borrelia-leptospira","stem":"What is the characteristic rash associated with Lyme disease?","options":[{"id":"a","text":"Maculopapular rash"},{"id":"b","text":"Erythema migrans"},{"id":"c","text":"Vesicular rash"},{"id":"d","text":"Pustular rash"}],"answerId":"b","explanation":"Erythema migrans, often described as a 'bull's-eye' rash, is characteristic of Lyme disease.","kind":"recall","origin":"ai"},{"id":"spirochetes-treponema-borrelia-leptospira~ai-3","moduleId":"spirochetes-treponema-borrelia-leptospira","stem":"What is the mechanism of action of penicillin in treating syphilis?","options":[{"id":"a","text":"Inhibits protein synthesis"},{"id":"b","text":"Disrupts cell wall synthesis"},{"id":"c","text":"Inhibits nucleic acid synthesis"},{"id":"d","text":"Inhibits folate synthesis"}],"answerId":"b","explanation":"Penicillin disrupts bacterial cell wall synthesis, effectively treating syphilis.","kind":"mechanism","origin":"ai"},{"id":"spirochetes-treponema-borrelia-leptospira~ai-4","moduleId":"spirochetes-treponema-borrelia-leptospira","stem":"A patient presents with jaundice, renal failure, and hemorrhage after exposure to floodwater. What is the most likely diagnosis?","options":[{"id":"a","text":"Lyme disease"},{"id":"b","text":"Secondary syphilis"},{"id":"c","text":"Leptospirosis"},{"id":"d","text":"Chlamydia infection"}],"answerId":"c","explanation":"These symptoms are indicative of severe leptospirosis, also known as Weil disease.","kind":"clinical","origin":"ai"},{"id":"spirochetes-treponema-borrelia-leptospira~ai-5","moduleId":"spirochetes-treponema-borrelia-leptospira","stem":"Which of the following is a key distinguishing feature of the primary syphilitic chancre?","options":[{"id":"a","text":"It is painful"},{"id":"b","text":"It is multiple"},{"id":"c","text":"It is indurated"},{"id":"d","text":"It is vesicular"}],"answerId":"c","explanation":"The primary syphilitic chancre is a single, painless, indurated ulcer, distinguishing it from other genital ulcers.","kind":"trap","origin":"ai"},{"id":"spirochetes-treponema-borrelia-leptospira~ai-6","moduleId":"spirochetes-treponema-borrelia-leptospira","stem":"How does the treatment of syphilis compare to that of Chlamydia infections?","options":[{"id":"a","text":"Both require penicillin"},{"id":"b","text":"Both are treated with doxycycline"},{"id":"c","text":"Syphilis requires penicillin, Chlamydia requires azithromycin"},{"id":"d","text":"Syphilis is treated with azithromycin"}],"answerId":"c","explanation":"Syphilis is treated with penicillin, while Chlamydia infections are typically treated with azithromycin or doxycycline.","kind":"integration","linkedModuleIds":["chlamydia-species"],"origin":"ai"},{"id":"spirochetes-treponema-borrelia-leptospira~ai-7","moduleId":"spirochetes-treponema-borrelia-leptospira","stem":"Which spirochete is primarily transmitted through water contaminated with rodent urine?","options":[{"id":"a","text":"Treponema pallidum"},{"id":"b","text":"Borrelia burgdorferi"},{"id":"c","text":"Leptospira interrogans"},{"id":"d","text":"Mycoplasma pneumoniae"}],"answerId":"c","explanation":"Leptospira interrogans is transmitted through water contaminated with rodent urine, leading to leptospirosis.","kind":"integration","linkedModuleIds":["mycoplasma-ureaplasma"],"origin":"ai"}],"fungal-biology-classification":[{"id":"fungal-biology-classification~ai-0","moduleId":"fungal-biology-classification","stem":"What is the primary structural component of the fungal cell wall?","options":[{"id":"a","text":"Cellulose"},{"id":"b","text":"Chitin"},{"id":"c","text":"Peptidoglycan"},{"id":"d","text":"Lignin"}],"answerId":"b","explanation":"The fungal cell wall is primarily composed of chitin, which distinguishes it from bacterial cell walls that contain peptidoglycan.","kind":"recall","origin":"ai"},{"id":"fungal-biology-classification~ai-1","moduleId":"fungal-biology-classification","stem":"Which antifungal mechanism involves the disruption of ergosterol synthesis?","options":[{"id":"a","text":"Inhibition of chitin synthesis"},{"id":"b","text":"Binding to ergosterol"},{"id":"c","text":"Inhibition of glucan synthesis"},{"id":"d","text":"Inhibition of ergosterol synthesis"}],"answerId":"d","explanation":"Azoles inhibit the synthesis of ergosterol, which is crucial for maintaining fungal cell membrane integrity.","kind":"mechanism","origin":"ai"},{"id":"fungal-biology-classification~ai-2","moduleId":"fungal-biology-classification","stem":"A patient presents with a skin infection caused by a filamentous fungus. What is the most likely morphological form of this fungus?","options":[{"id":"a","text":"Yeast"},{"id":"b","text":"Mould"},{"id":"c","text":"Dimorphic"},{"id":"d","text":"Bacterial"}],"answerId":"b","explanation":"Filamentous fungi grow as moulds, characterized by hyphae, which are not seen in yeasts.","kind":"recall","origin":"ai"},{"id":"fungal-biology-classification~ai-3","moduleId":"fungal-biology-classification","stem":"Which of the following fungi is known for its thermal dimorphism?","options":[{"id":"a","text":"Candida"},{"id":"b","text":"Aspergillus"},{"id":"c","text":"Histoplasma"},{"id":"d","text":"Cryptococcus"}],"answerId":"c","explanation":"Histoplasma is a dimorphic fungus that exists as a mould at 25°C and as a yeast at 37°C.","kind":"recall","origin":"ai"},{"id":"fungal-biology-classification~ai-4","moduleId":"fungal-biology-classification","stem":"In a neutropenic patient, which fungal pathogen is most likely to cause an invasive infection?","options":[{"id":"a","text":"Candida"},{"id":"b","text":"Aspergillus"},{"id":"c","text":"Cryptococcus"},{"id":"d","text":"Mucor"}],"answerId":"b","explanation":"Aspergillus is a common cause of invasive fungal infections in neutropenic patients due to its airborne spores.","kind":"clinical","origin":"ai"},{"id":"fungal-biology-classification~ai-5","moduleId":"fungal-biology-classification","stem":"Why do antifungal agents differ from antibacterial agents?","options":[{"id":"a","text":"Both target the same microbial structures"},{"id":"b","text":"Fungi are prokaryotes like bacteria"},{"id":"c","text":"Fungi have unique eukaryotic structures not found in bacteria"},{"id":"d","text":"Antibacterial agents are effective against all microbes"}],"answerId":"c","explanation":"Fungi are eukaryotes with unique structures like ergosterol and chitin, which are not present in bacteria, making antifungal agents specifically target these structures.","kind":"trap","origin":"ai"},{"id":"fungal-biology-classification~ai-6","moduleId":"fungal-biology-classification","stem":"How does the diagnosis of a dimorphic fungal infection differ from that of a yeast infection?","options":[{"id":"a","text":"Both can be diagnosed with KOH prep"},{"id":"b","text":"Dimorphic fungi require culture at different temperatures"},{"id":"c","text":"Yeast infections are always superficial"},{"id":"d","text":"Dimorphic fungi do not form spores"}],"answerId":"b","explanation":"Dimorphic fungi require culture at different temperatures to identify their yeast or mould forms, unlike yeasts which do not have this requirement.","kind":"integration","linkedModuleIds":["systemic-dimorphic-fungi"],"origin":"ai"},{"id":"fungal-biology-classification~ai-7","moduleId":"fungal-biology-classification","stem":"Which laboratory method is most effective for identifying hyphae in a skin sample?","options":[{"id":"a","text":"Gram stain"},{"id":"b","text":"KOH preparation"},{"id":"c","text":"India ink preparation"},{"id":"d","text":"Culture on blood agar"}],"answerId":"b","explanation":"KOH preparation dissolves keratin, allowing for the visualization of fungal hyphae in skin samples.","kind":"recall","origin":"ai"}],"mycoplasma-ureaplasma":[{"id":"mycoplasma-ureaplasma~ai-0","moduleId":"mycoplasma-ureaplasma","stem":"What is the primary reason Mycoplasma pneumoniae is resistant to β-lactam antibiotics?","options":[{"id":"a","text":"It has a thick peptidoglycan layer."},{"id":"b","text":"It lacks a cell wall."},{"id":"c","text":"It produces β-lactamase."},{"id":"d","text":"It has a capsule."}],"answerId":"b","explanation":"Mycoplasma pneumoniae lacks a cell wall, which is the target of β-lactam antibiotics, making them ineffective.","kind":"mechanism","origin":"ai"},{"id":"mycoplasma-ureaplasma~ai-1","moduleId":"mycoplasma-ureaplasma","stem":"A 20-year-old presents with a dry cough and malaise. Chest X-ray shows infiltrates worse than clinical findings. What is the most likely diagnosis?","options":[{"id":"a","text":"Typical pneumonia"},{"id":"b","text":"Mycoplasma pneumoniae infection"},{"id":"c","text":"Viral pneumonia"},{"id":"d","text":"Tuberculosis"}],"answerId":"b","explanation":"The presentation is consistent with atypical pneumonia caused by Mycoplasma pneumoniae, which often has a worse X-ray appearance than clinical symptoms.","kind":"clinical","origin":"ai"},{"id":"mycoplasma-ureaplasma~ai-2","moduleId":"mycoplasma-ureaplasma","stem":"Which of the following is a characteristic finding in Mycoplasma pneumoniae infection?","options":[{"id":"a","text":"Gram-positive cocci in clusters"},{"id":"b","text":"Cold agglutinins (IgM)"},{"id":"c","text":"High fever and productive cough"},{"id":"d","text":"Lobar consolidation on chest X-ray"}],"answerId":"b","explanation":"Cold agglutinins (IgM) are associated with Mycoplasma pneumoniae infection and can lead to autoimmune hemolysis.","kind":"recall","origin":"ai"},{"id":"mycoplasma-ureaplasma~ai-3","moduleId":"mycoplasma-ureaplasma","stem":"What is the appropriate first-line treatment for Mycoplasma pneumoniae infection?","options":[{"id":"a","text":"Amoxicillin"},{"id":"b","text":"Ciprofloxacin"},{"id":"c","text":"Azithromycin"},{"id":"d","text":"Vancomycin"}],"answerId":"c","explanation":"Azithromycin is a macrolide antibiotic effective against Mycoplasma pneumoniae, which is resistant to β-lactams.","kind":"trap","origin":"ai"},{"id":"mycoplasma-ureaplasma~ai-4","moduleId":"mycoplasma-ureaplasma","stem":"A patient with pneumonia is not improving on amoxicillin. What should be considered next?","options":[{"id":"a","text":"Increase amoxicillin dosage"},{"id":"b","text":"Switch to a macrolide"},{"id":"c","text":"Add a fluoroquinolone"},{"id":"d","text":"Start corticosteroids"}],"answerId":"b","explanation":"Mycoplasma pneumoniae is resistant to β-lactams, so switching to a macrolide is appropriate for atypical pneumonia.","kind":"trap","origin":"ai"},{"id":"mycoplasma-ureaplasma~ai-5","moduleId":"mycoplasma-ureaplasma","stem":"How does the absence of a cell wall in Mycoplasma relate to its clinical presentation?","options":[{"id":"a","text":"It leads to severe inflammation."},{"id":"b","text":"It causes pleomorphism and atypical pneumonia."},{"id":"c","text":"It results in rapid growth."},{"id":"d","text":"It increases susceptibility to antibiotics."}],"answerId":"b","explanation":"The absence of a cell wall allows Mycoplasma to be pleomorphic and is a key factor in its atypical pneumonia presentation.","kind":"integration","linkedModuleIds":["bacterial-structure-cell-wall"],"origin":"ai"},{"id":"mycoplasma-ureaplasma~ai-6","moduleId":"mycoplasma-ureaplasma","stem":"Which of the following features links Mycoplasma pneumoniae to its treatment strategy?","options":[{"id":"a","text":"Presence of a cell wall"},{"id":"b","text":"Production of cold agglutinins"},{"id":"c","text":"Resistance to β-lactams"},{"id":"d","text":"High virulence"}],"answerId":"c","explanation":"Mycoplasma pneumoniae's resistance to β-lactams due to the absence of a cell wall necessitates the use of macrolides or tetracyclines.","kind":"integration","linkedModuleIds":["community-acquired-pneumonia"],"origin":"ai"}],"nocardia-actinomyces":[{"id":"nocardia-actinomyces~ai-0","moduleId":"nocardia-actinomyces","stem":"Which of the following is a characteristic feature of Nocardia species?","options":[{"id":"a","text":"Anaerobic growth"},{"id":"b","text":"Non-acid-fast"},{"id":"c","text":"Cavitary pneumonia in immunocompromised"},{"id":"d","text":"Presence of sulfur granules"}],"answerId":"c","explanation":"Nocardia is an aerobic, partially acid-fast organism that commonly causes cavitary pneumonia in immunocompromised patients.","kind":"recall","origin":"ai"},{"id":"nocardia-actinomyces~ai-1","moduleId":"nocardia-actinomyces","stem":"What is the primary treatment for Actinomyces infections?","options":[{"id":"a","text":"Co-trimoxazole"},{"id":"b","text":"Vancomycin"},{"id":"c","text":"Penicillin"},{"id":"d","text":"Ciprofloxacin"}],"answerId":"c","explanation":"Actinomyces is exquisitely sensitive to penicillin, making it the drug of choice for treatment.","kind":"recall","origin":"ai"},{"id":"nocardia-actinomyces~ai-2","moduleId":"nocardia-actinomyces","stem":"A patient presents with a chronic jaw mass and draining sinuses. Microscopic examination reveals yellow sulfur granules. What is the most likely organism?","options":[{"id":"a","text":"Nocardia"},{"id":"b","text":"Bacteroides"},{"id":"c","text":"Actinomyces"},{"id":"d","text":"Mycobacterium"}],"answerId":"c","explanation":"The presence of sulfur granules and the clinical presentation suggest a diagnosis of Actinomyces infection.","kind":"clinical","origin":"ai"},{"id":"nocardia-actinomyces~ai-3","moduleId":"nocardia-actinomyces","stem":"Which of the following findings would most likely indicate a Nocardia infection?","options":[{"id":"a","text":"Non-acid-fast branching filaments"},{"id":"b","text":"Cavitary lung lesions"},{"id":"c","text":"Sulfur granules"},{"id":"d","text":"Oral flora origin"}],"answerId":"b","explanation":"Cavitary lung lesions in an immunocompromised patient are characteristic of Nocardia infections.","kind":"recall","origin":"ai"},{"id":"nocardia-actinomyces~ai-4","moduleId":"nocardia-actinomyces","stem":"Nocardia and Actinomyces can both appear as branching filamentous organisms. Which statement correctly distinguishes them?","options":[{"id":"a","text":"Both are aerobic and acid-fast"},{"id":"b","text":"Nocardia is anaerobic and found in oral flora"},{"id":"c","text":"Nocardia is aerobic and partially acid-fast"},{"id":"d","text":"Actinomyces is aerobic and causes pulmonary disease"}],"answerId":"c","explanation":"Nocardia is aerobic and partially acid-fast, while Actinomyces is anaerobic and non-acid-fast.","kind":"trap","origin":"ai"},{"id":"nocardia-actinomyces~ai-5","moduleId":"nocardia-actinomyces","stem":"A patient with a long-standing IUD presents with pelvic pain and a mass. What organism is likely responsible for this infection?","options":[{"id":"a","text":"Nocardia"},{"id":"b","text":"Bacteroides"},{"id":"c","text":"Actinomyces"},{"id":"d","text":"Mycobacterium"}],"answerId":"c","explanation":"Actinomyces can cause pelvic infections associated with IUDs due to its endogenous nature.","kind":"clinical","origin":"ai"},{"id":"nocardia-actinomyces~ai-6","moduleId":"nocardia-actinomyces","stem":"How does the treatment of Nocardia differ from that of Bacteroides infections?","options":[{"id":"a","text":"Both are treated with penicillin"},{"id":"b","text":"Nocardia requires co-trimoxazole, Bacteroides requires metronidazole"},{"id":"c","text":"Both require metronidazole"},{"id":"d","text":"Nocardia is treated with vancomycin"}],"answerId":"b","explanation":"Nocardia is treated with co-trimoxazole, while Bacteroides infections are typically treated with metronidazole.","kind":"integration","linkedModuleIds":["bacteroides-gram-negative-anaerobes"],"origin":"ai"},{"id":"nocardia-actinomyces~ai-7","moduleId":"nocardia-actinomyces","stem":"Which of the following is a key difference between Nocardia and Mycobacterium tuberculosis?","options":[{"id":"a","text":"Both are aerobic and acid-fast"},{"id":"b","text":"Nocardia is found in soil, Mycobacterium is not"},{"id":"c","text":"Nocardia primarily causes skin infections"},{"id":"d","text":"Mycobacterium is treated with co-trimoxazole"}],"answerId":"b","explanation":"Nocardia is an environmental organism found in soil, while Mycobacterium tuberculosis is primarily a human pathogen.","kind":"integration","linkedModuleIds":["mycobacterium-tuberculosis-leprae"],"origin":"ai"}],"dermatophytes-tinea":[{"id":"dermatophytes-tinea~ai-0","moduleId":"dermatophytes-tinea","stem":"What is the primary method for diagnosing dermatophyte infections?","options":[{"id":"a","text":"Blood culture"},{"id":"b","text":"KOH microscopy"},{"id":"c","text":"Skin biopsy"},{"id":"d","text":"PCR testing"}],"answerId":"b","explanation":"KOH microscopy reveals septate branching hyphae, which is characteristic of dermatophyte infections.","kind":"recall","origin":"ai"},{"id":"dermatophytes-tinea~ai-1","moduleId":"dermatophytes-tinea","stem":"Which of the following dermatophyte genera primarily infects hair?","options":[{"id":"a","text":"Epidermophyton"},{"id":"b","text":"Microsporum"},{"id":"c","text":"Candida"},{"id":"d","text":"Aspergillus"}],"answerId":"b","explanation":"Microsporum is known to infect hair and skin, while Epidermophyton primarily infects skin and nails.","kind":"recall","origin":"ai"},{"id":"dermatophytes-tinea~ai-2","moduleId":"dermatophytes-tinea","stem":"A child presents with a scaly scalp and hair loss. What is the most likely diagnosis?","options":[{"id":"a","text":"Tinea corporis"},{"id":"b","text":"Tinea capitis"},{"id":"c","text":"Tinea pedis"},{"id":"d","text":"Onychomycosis"}],"answerId":"b","explanation":"Tinea capitis is characterized by scalp involvement and hair loss, often seen in children.","kind":"clinical","origin":"ai"},{"id":"dermatophytes-tinea~ai-3","moduleId":"dermatophytes-tinea","stem":"Which treatment is appropriate for tinea capitis?","options":[{"id":"a","text":"Topical clotrimazole"},{"id":"b","text":"Oral terbinafine"},{"id":"c","text":"Topical terbinafine"},{"id":"d","text":"Oral fluconazole"}],"answerId":"b","explanation":"Tinea capitis requires systemic treatment with oral antifungals like terbinafine because topical treatments cannot penetrate hair follicles.","kind":"trap","origin":"ai"},{"id":"dermatophytes-tinea~ai-4","moduleId":"dermatophytes-tinea","stem":"What is the expected finding on KOH microscopy for a dermatophyte infection?","options":[{"id":"a","text":"Yeast cells"},{"id":"b","text":"Pseudohyphae"},{"id":"c","text":"Septate branching hyphae"},{"id":"d","text":"Spherical spores"}],"answerId":"c","explanation":"KOH microscopy reveals septate branching hyphae, which are indicative of dermatophyte infections.","kind":"mechanism","origin":"ai"},{"id":"dermatophytes-tinea~ai-5","moduleId":"dermatophytes-tinea","stem":"Which of the following is NOT a dermatophyte infection?","options":[{"id":"a","text":"Tinea corporis"},{"id":"b","text":"Tinea capitis"},{"id":"c","text":"Tinea versicolor"},{"id":"d","text":"Tinea pedis"}],"answerId":"c","explanation":"Tinea versicolor is caused by Malassezia, not a dermatophyte.","kind":"trap","origin":"ai"},{"id":"dermatophytes-tinea~ai-6","moduleId":"dermatophytes-tinea","stem":"How do dermatophytes primarily cause disease?","options":[{"id":"a","text":"Invasion of living tissue"},{"id":"b","text":"Production of toxins"},{"id":"c","text":"Infection of keratinized tissues"},{"id":"d","text":"Systemic spread"}],"answerId":"c","explanation":"Dermatophytes are keratinophilic fungi that infect keratinized tissues such as skin, hair, and nails.","kind":"mechanism","origin":"ai"},{"id":"dermatophytes-tinea~ai-7","moduleId":"dermatophytes-tinea","stem":"A patient presents with a thick, discolored toenail. What is the most likely diagnosis?","options":[{"id":"a","text":"Tinea capitis"},{"id":"b","text":"Tinea corporis"},{"id":"c","text":"Onychomycosis"},{"id":"d","text":"Tinea pedis"}],"answerId":"c","explanation":"Thick, discolored, crumbling toenails are characteristic of onychomycosis, a dermatophyte infection of the nails.","kind":"clinical","origin":"ai"},{"id":"dermatophytes-tinea~ai-8","moduleId":"dermatophytes-tinea","stem":"How does tinea pedis typically present?","options":[{"id":"a","text":"Annular scaly plaque"},{"id":"b","text":"Boggy inflammatory mass"},{"id":"c","text":"Interdigital maceration"},{"id":"d","text":"Thickened nails"}],"answerId":"c","explanation":"Tinea pedis, or athlete's foot, commonly presents with interdigital maceration and itching.","kind":"clinical","origin":"ai"},{"id":"dermatophytes-tinea~ai-9","moduleId":"dermatophytes-tinea","stem":"Which of the following fungal infections is most likely to require systemic treatment?","options":[{"id":"a","text":"Tinea corporis"},{"id":"b","text":"Tinea cruris"},{"id":"c","text":"Tinea capitis"},{"id":"d","text":"Tinea pedis"}],"answerId":"c","explanation":"Tinea capitis requires systemic treatment due to its location in hair follicles, unlike the other tinea infections.","kind":"integration","linkedModuleIds":["skin-infections-bacterial-fungal-viral"],"origin":"ai"}],"systemic-dimorphic-fungi":[{"id":"systemic-dimorphic-fungi~ai-0","moduleId":"systemic-dimorphic-fungi","stem":"What is the characteristic tissue morphology of Histoplasma capsulatum?","options":[{"id":"a","text":"Broad-based budding yeast"},{"id":"b","text":"Spherules packed with endospores"},{"id":"c","text":"Intracellular yeasts within macrophages"},{"id":"d","text":"Captain's wheel yeast"}],"answerId":"c","explanation":"Histoplasma capsulatum is identified histologically by its intracellular yeast form within macrophages.","kind":"recall","origin":"ai"},{"id":"systemic-dimorphic-fungi~ai-1","moduleId":"systemic-dimorphic-fungi","stem":"Which systemic dimorphic fungus is associated with bat and bird droppings?","options":[{"id":"a","text":"Coccidioides"},{"id":"b","text":"Blastomyces"},{"id":"c","text":"Histoplasma"},{"id":"d","text":"Paracoccidioides"}],"answerId":"c","explanation":"Histoplasma capsulatum is commonly found in environments with bat and bird droppings.","kind":"recall","origin":"ai"},{"id":"systemic-dimorphic-fungi~ai-2","moduleId":"systemic-dimorphic-fungi","stem":"A patient presents with pneumonia and erythema nodosum after exposure to desert dust. Which fungus is most likely responsible?","options":[{"id":"a","text":"Histoplasma capsulatum"},{"id":"b","text":"Blastomyces dermatitidis"},{"id":"c","text":"Coccidioides immitis"},{"id":"d","text":"Paracoccidioides brasiliensis"}],"answerId":"c","explanation":"Coccidioides immitis is known to cause pneumonia with erythema nodosum, particularly after exposure to dust in endemic areas.","kind":"clinical","origin":"ai"},{"id":"systemic-dimorphic-fungi~ai-3","moduleId":"systemic-dimorphic-fungi","stem":"Which of the following statements about endemic dimorphic fungi is true?","options":[{"id":"a","text":"They always cause severe disease in all infected individuals."},{"id":"b","text":"They are primarily transmitted through direct contact with infected individuals."},{"id":"c","text":"In immunocompetent hosts, they often cause self-limited pulmonary illness."},{"id":"d","text":"They can be treated effectively with topical antifungals."}],"answerId":"c","explanation":"In immunocompetent individuals, these fungi typically cause a self-limited flu-like illness, while severe disease is more common in immunocompromised hosts.","kind":"trap","origin":"ai"},{"id":"systemic-dimorphic-fungi~ai-4","moduleId":"systemic-dimorphic-fungi","stem":"What is the primary mechanism of dissemination for systemic dimorphic fungi in immunocompromised patients?","options":[{"id":"a","text":"Direct contact with contaminated soil"},{"id":"b","text":"Inhalation of spores leading to systemic spread"},{"id":"c","text":"Ingestion of contaminated food"},{"id":"d","text":"Vector-borne transmission"}],"answerId":"b","explanation":"Systemic dimorphic fungi disseminate through inhalation of spores, especially in immunocompromised individuals.","kind":"mechanism","origin":"ai"},{"id":"systemic-dimorphic-fungi~ai-5","moduleId":"systemic-dimorphic-fungi","stem":"A patient from Latin America presents with chronic pulmonary and oral mucosal lesions. Which fungus is most likely responsible?","options":[{"id":"a","text":"Coccidioides immitis"},{"id":"b","text":"Blastomyces dermatitidis"},{"id":"c","text":"Histoplasma capsulatum"},{"id":"d","text":"Paracoccidioides brasiliensis"}],"answerId":"d","explanation":"Paracoccidioides brasiliensis is associated with chronic pulmonary and oral lesions, particularly in men from Latin America.","kind":"clinical","origin":"ai"},{"id":"systemic-dimorphic-fungi~ai-6","moduleId":"systemic-dimorphic-fungi","stem":"How do systemic dimorphic fungi relate to the immune response to fungi?","options":[{"id":"a","text":"They are always pathogenic regardless of host immunity."},{"id":"b","text":"They can cause disease only in immunocompetent individuals."},{"id":"c","text":"Their pathogenicity is enhanced in immunocompromised hosts."},{"id":"d","text":"They do not elicit any immune response."}],"answerId":"c","explanation":"The pathogenicity of systemic dimorphic fungi is significantly enhanced in immunocompromised hosts, leading to severe disease.","kind":"integration","linkedModuleIds":["immunity-viruses-fungi-parasites"],"origin":"ai"},{"id":"systemic-dimorphic-fungi~ai-7","moduleId":"systemic-dimorphic-fungi","stem":"Which antifungal treatment is appropriate for severe disseminated disease caused by systemic dimorphic fungi?","options":[{"id":"a","text":"Fluconazole"},{"id":"b","text":"Amphotericin B"},{"id":"c","text":"Itraconazole"},{"id":"d","text":"Topical clotrimazole"}],"answerId":"b","explanation":"Amphotericin B is the treatment of choice for severe or disseminated infections caused by systemic dimorphic fungi.","kind":"recall","origin":"ai"}],"mushroom-poisoning-syndromes":[{"id":"mushroom-poisoning-syndromes~ai-0","moduleId":"mushroom-poisoning-syndromes","stem":"What is the primary mechanism of action of amatoxin found in Amanita phalloides?","options":[{"id":"a","text":"Inhibition of RNA polymerase II"},{"id":"b","text":"Activation of muscarinic receptors"},{"id":"c","text":"Inhibition of acetylcholinesterase"},{"id":"d","text":"Blockade of NMDA receptors"}],"answerId":"a","explanation":"Amanita phalloides contains amatoxin, which inhibits RNA polymerase II, leading to decreased mRNA synthesis and cell death.","kind":"mechanism","origin":"ai"},{"id":"mushroom-poisoning-syndromes~ai-1","moduleId":"mushroom-poisoning-syndromes","stem":"Which symptom is characteristic of muscarine poisoning from mushrooms?","options":[{"id":"a","text":"Severe abdominal pain"},{"id":"b","text":"Hallucinations"},{"id":"c","text":"Salivation and lacrimation"},{"id":"d","text":"Fulminant hepatic failure"}],"answerId":"c","explanation":"Muscarine poisoning causes cholinergic symptoms, including salivation, lacrimation, urination, defecation, GI distress, and miosis.","kind":"recall","origin":"ai"},{"id":"mushroom-poisoning-syndromes~ai-2","moduleId":"mushroom-poisoning-syndromes","stem":"A patient presents with severe gastrointestinal symptoms 8 hours after consuming mushrooms. What is the most likely diagnosis?","options":[{"id":"a","text":"Muscarine poisoning"},{"id":"b","text":"Amanita phalloides poisoning"},{"id":"c","text":"Psilocybin intoxication"},{"id":"d","text":"Coprine reaction"}],"answerId":"b","explanation":"Symptoms starting after 6 hours suggest amatoxin poisoning, which can lead to severe liver failure.","kind":"clinical","origin":"ai"},{"id":"mushroom-poisoning-syndromes~ai-3","moduleId":"mushroom-poisoning-syndromes","stem":"Which of the following statements about the recovery phase in amatoxin poisoning is true?","options":[{"id":"a","text":"Patients can be safely discharged after improvement"},{"id":"b","text":"Improvement indicates the toxin was non-lethal"},{"id":"c","text":"Recovery is often deceptive and can precede liver failure"},{"id":"d","text":"Symptoms resolve within 24 hours"}],"answerId":"c","explanation":"In amatoxin poisoning, a deceptive recovery can occur before fulminant hepatic failure develops, requiring close monitoring.","kind":"trap","origin":"ai"},{"id":"mushroom-poisoning-syndromes~ai-4","moduleId":"mushroom-poisoning-syndromes","stem":"What is the recommended treatment for muscarine poisoning?","options":[{"id":"a","text":"Activated charcoal"},{"id":"b","text":"Silibinin"},{"id":"c","text":"Atropine"},{"id":"d","text":"N-acetylcysteine"}],"answerId":"c","explanation":"Atropine is the antidote for muscarine poisoning, counteracting the cholinergic effects.","kind":"recall","origin":"ai"},{"id":"mushroom-poisoning-syndromes~ai-5","moduleId":"mushroom-poisoning-syndromes","stem":"How does the management of amatoxin poisoning differ from that of food poisoning?","options":[{"id":"a","text":"Amatoxin requires liver transplant consideration"},{"id":"b","text":"Food poisoning is always more severe"},{"id":"c","text":"Amatoxin symptoms appear immediately"},{"id":"d","text":"Food poisoning has a biphasic course"}],"answerId":"a","explanation":"Amatoxin poisoning may necessitate liver transplant due to the risk of fulminant hepatic failure, unlike most food poisoning cases.","kind":"integration","linkedModuleIds":["food-poisoning-post-infectious"],"origin":"ai"},{"id":"mushroom-poisoning-syndromes~ai-6","moduleId":"mushroom-poisoning-syndromes","stem":"Which of the following mushrooms is most likely to cause hallucinations shortly after ingestion?","options":[{"id":"a","text":"Amanita phalloides"},{"id":"b","text":"Inocybe species"},{"id":"c","text":"Psilocybe species"},{"id":"d","text":"Coprinus species"}],"answerId":"c","explanation":"Psilocybe species contain psilocybin, which can cause hallucinations within an hour of ingestion.","kind":"recall","origin":"ai"},{"id":"mushroom-poisoning-syndromes~ai-7","moduleId":"mushroom-poisoning-syndromes","stem":"What is the primary concern when a patient shows improvement after initial GI symptoms from mushroom ingestion?","options":[{"id":"a","text":"They are cured and can be discharged"},{"id":"b","text":"They may still develop liver failure"},{"id":"c","text":"They are experiencing a placebo effect"},{"id":"d","text":"They require immediate surgery"}],"answerId":"b","explanation":"Improvement after GI symptoms can be misleading in amatoxin poisoning, as liver failure may still occur later.","kind":"trap","origin":"ai"},{"id":"mushroom-poisoning-syndromes~ai-8","moduleId":"mushroom-poisoning-syndromes","stem":"What type of reaction does coprine from Coprinus species cause when alcohol is consumed?","options":[{"id":"a","text":"Cholinergic crisis"},{"id":"b","text":"Disulfiram-like reaction"},{"id":"c","text":"Serotonin syndrome"},{"id":"d","text":"Neuroleptic malignant syndrome"}],"answerId":"b","explanation":"Coprine causes a disulfiram-like reaction with alcohol, leading to flushing, nausea, and vomiting.","kind":"recall","origin":"ai"}],"antifungal-agents-lab-diagnosis":[{"id":"antifungal-agents-lab-diagnosis~ai-0","moduleId":"antifungal-agents-lab-diagnosis","stem":"Which antifungal agent binds to ergosterol in fungal cell membranes?","options":[{"id":"a","text":"Amphotericin B"},{"id":"b","text":"Fluconazole"},{"id":"c","text":"Caspofungin"},{"id":"d","text":"Griseofulvin"}],"answerId":"a","explanation":"Amphotericin B is a polyene that binds ergosterol, leading to pore formation in the fungal membrane.","kind":"recall","origin":"ai"},{"id":"antifungal-agents-lab-diagnosis~ai-1","moduleId":"antifungal-agents-lab-diagnosis","stem":"What is the primary mechanism of action of azole antifungals?","options":[{"id":"a","text":"Inhibit β-1,3-glucan synthesis"},{"id":"b","text":"Bind ergosterol"},{"id":"c","text":"Inhibit ergosterol synthesis"},{"id":"d","text":"Inhibit nucleic acid synthesis"}],"answerId":"c","explanation":"Azoles inhibit ergosterol synthesis by blocking lanosterol 14-α-demethylase, a CYP enzyme.","kind":"mechanism","origin":"ai"},{"id":"antifungal-agents-lab-diagnosis~ai-2","moduleId":"antifungal-agents-lab-diagnosis","stem":"A patient presents with invasive candidiasis. Which antifungal agent is most appropriate?","options":[{"id":"a","text":"Amphotericin B"},{"id":"b","text":"Fluconazole"},{"id":"c","text":"Caspofungin"},{"id":"d","text":"Voriconazole"}],"answerId":"c","explanation":"Caspofungin, an echinocandin, is effective against invasive Candida infections.","kind":"clinical","origin":"ai"},{"id":"antifungal-agents-lab-diagnosis~ai-3","moduleId":"antifungal-agents-lab-diagnosis","stem":"Which of the following is a common side effect of amphotericin B?","options":[{"id":"a","text":"Hepatotoxicity"},{"id":"b","text":"Nephrotoxicity"},{"id":"c","text":"Cardiotoxicity"},{"id":"d","text":"Pulmonary toxicity"}],"answerId":"b","explanation":"Amphotericin B is known for its nephrotoxic effects, particularly with infusion.","kind":"recall","origin":"ai"},{"id":"antifungal-agents-lab-diagnosis~ai-4","moduleId":"antifungal-agents-lab-diagnosis","stem":"Which test is used to diagnose cryptococcal meningitis?","options":[{"id":"a","text":"KOH prep"},{"id":"b","text":"India ink preparation"},{"id":"c","text":"Galactomannan antigen"},{"id":"d","text":"β-D-glucan test"}],"answerId":"b","explanation":"India ink preparation is used to visualize the capsule of Cryptococcus in CSF.","kind":"recall","origin":"ai"},{"id":"antifungal-agents-lab-diagnosis~ai-5","moduleId":"antifungal-agents-lab-diagnosis","stem":"Echinocandins are effective against which of the following organisms?","options":[{"id":"a","text":"Cryptococcus"},{"id":"b","text":"Candida"},{"id":"c","text":"Aspergillus"},{"id":"d","text":"Mucor"}],"answerId":"b","explanation":"Echinocandins are effective against Candida but have no activity against Cryptococcus.","kind":"trap","origin":"ai"},{"id":"antifungal-agents-lab-diagnosis~ai-6","moduleId":"antifungal-agents-lab-diagnosis","stem":"In a patient with suspected cryptococcal meningitis, which antifungal regimen is preferred?","options":[{"id":"a","text":"Amphotericin B alone"},{"id":"b","text":"Fluconazole alone"},{"id":"c","text":"Amphotericin B plus flucytosine"},{"id":"d","text":"Caspofungin alone"}],"answerId":"c","explanation":"The preferred treatment for cryptococcal meningitis is Amphotericin B plus flucytosine.","kind":"clinical","origin":"ai"},{"id":"antifungal-agents-lab-diagnosis~ai-7","moduleId":"antifungal-agents-lab-diagnosis","stem":"Which antifungal agent would be inappropriate for treating a patient with cryptococcal meningitis?","options":[{"id":"a","text":"Amphotericin B"},{"id":"b","text":"Flucytosine"},{"id":"c","text":"Caspofungin"},{"id":"d","text":"Fluconazole"}],"answerId":"c","explanation":"Caspofungin is ineffective against Cryptococcus, making it an inappropriate choice.","kind":"trap","origin":"ai"},{"id":"antifungal-agents-lab-diagnosis~ai-8","moduleId":"antifungal-agents-lab-diagnosis","stem":"How does the mechanism of flucytosine differ from that of amphotericin B?","options":[{"id":"a","text":"Flucytosine binds ergosterol; amphotericin inhibits nucleic acid synthesis"},{"id":"b","text":"Flucytosine inhibits nucleic acid synthesis; amphotericin binds ergosterol"},{"id":"c","text":"Both inhibit ergosterol synthesis"},{"id":"d","text":"Both bind to cell wall components"}],"answerId":"b","explanation":"Flucytosine inhibits nucleic acid synthesis, while amphotericin B binds ergosterol in the cell membrane.","kind":"integration","linkedModuleIds":["cryptococcus-malassezia"],"origin":"ai"}],"candida-candidiasis":[{"id":"candida-candidiasis~ai-0","moduleId":"candida-candidiasis","stem":"What is the primary morphological feature of Candida albicans that aids in its identification?","options":[{"id":"a","text":"Budding yeasts"},{"id":"b","text":"Pseudohyphae"},{"id":"c","text":"Germ tubes"},{"id":"d","text":"Hyphae"}],"answerId":"c","explanation":"Candida albicans is identified by its ability to form germ tubes at 37°C, which is a rapid identification test.","kind":"recall","origin":"ai"},{"id":"candida-candidiasis~ai-1","moduleId":"candida-candidiasis","stem":"Which condition is characterized by white oral plaques that scrape off, especially in inhaled-steroid users?","options":[{"id":"a","text":"Vulvovaginal candidiasis"},{"id":"b","text":"Oesophageal candidiasis"},{"id":"c","text":"Oral candidiasis"},{"id":"d","text":"Intertrigo"}],"answerId":"c","explanation":"White oral plaques that scrape off are indicative of oral candidiasis (thrush).","kind":"recall","origin":"ai"},{"id":"candida-candidiasis~ai-2","moduleId":"candida-candidiasis","stem":"In a patient with candidaemia, what is the most critical step in management alongside antifungal therapy?","options":[{"id":"a","text":"Administer broad-spectrum antibiotics"},{"id":"b","text":"Remove the infected central venous catheter"},{"id":"c","text":"Increase fluid intake"},{"id":"d","text":"Perform a blood transfusion"}],"answerId":"b","explanation":"In catheter-associated candidaemia, removing the infected central venous catheter is crucial for effective treatment.","kind":"trap","origin":"ai"},{"id":"candida-candidiasis~ai-3","moduleId":"candida-candidiasis","stem":"What is the first-line treatment for invasive candidiasis?","options":[{"id":"a","text":"Fluconazole"},{"id":"b","text":"Amphotericin B"},{"id":"c","text":"Echinocandin"},{"id":"d","text":"Nystatin"}],"answerId":"c","explanation":"Echinocandins are the first-line treatment for invasive candidiasis due to their efficacy and tolerability.","kind":"recall","origin":"ai"},{"id":"candida-candidiasis~ai-4","moduleId":"candida-candidiasis","stem":"Which Candida species is known for its multidrug resistance and hospital spread?","options":[{"id":"a","text":"Candida glabrata"},{"id":"b","text":"Candida krusei"},{"id":"c","text":"Candida auris"},{"id":"d","text":"Candida tropicalis"}],"answerId":"c","explanation":"Candida auris is recognized for being multidrug-resistant and is a significant concern in hospital settings.","kind":"recall","origin":"ai"},{"id":"candida-candidiasis~ai-5","moduleId":"candida-candidiasis","stem":"A patient presents with dysphagia and oesophageal plaques. What is the most likely diagnosis?","options":[{"id":"a","text":"Oral candidiasis"},{"id":"b","text":"Oesophageal candidiasis"},{"id":"c","text":"Vulvovaginal candidiasis"},{"id":"d","text":"Candidaemia"}],"answerId":"b","explanation":"Dysphagia with oesophageal plaques is characteristic of oesophageal candidiasis, particularly in immunocompromised patients.","kind":"recall","origin":"ai"},{"id":"candida-candidiasis~ai-6","moduleId":"candida-candidiasis","stem":"How does the mechanism of action of echinocandins differ from azoles in treating Candida infections?","options":[{"id":"a","text":"Inhibits ergosterol synthesis"},{"id":"b","text":"Disrupts cell wall synthesis"},{"id":"c","text":"Inhibits nucleic acid synthesis"},{"id":"d","text":"Inhibits protein synthesis"}],"answerId":"b","explanation":"Echinocandins disrupt cell wall synthesis, while azoles inhibit ergosterol synthesis.","kind":"mechanism","origin":"ai"},{"id":"candida-candidiasis~ai-7","moduleId":"candida-candidiasis","stem":"How does Candida albicans relate to the diagnosis of inflammatory bacterial diarrhea?","options":[{"id":"a","text":"It causes diarrhea directly"},{"id":"b","text":"It complicates bacterial infections"},{"id":"c","text":"It is a differential diagnosis"},{"id":"d","text":"It has no relation"}],"answerId":"b","explanation":"Candida can complicate bacterial infections by causing superinfection in immunocompromised patients, thus linking it to inflammatory bacterial diarrhea.","kind":"integration","linkedModuleIds":["inflammatory-invasive-enteritis"],"origin":"ai"},{"id":"candida-candidiasis~ai-8","moduleId":"candida-candidiasis","stem":"What common risk factor for Candida infections also applies to renal defense mechanisms?","options":[{"id":"a","text":"Diabetes"},{"id":"b","text":"Antibiotic use"},{"id":"c","text":"Central venous catheters"},{"id":"d","text":"Inhaled steroids"}],"answerId":"b","explanation":"Antibiotic use disrupts normal flora, increasing susceptibility to Candida infections, similar to how it affects renal defense mechanisms.","kind":"integration","linkedModuleIds":["renal-defense-mechanisms"],"origin":"ai"}],"cryptococcus-malassezia":[{"id":"cryptococcus-malassezia~ai-0","moduleId":"cryptococcus-malassezia","stem":"What is the key virulence factor of Cryptococcus neoformans?","options":[{"id":"a","text":"Polysaccharide capsule"},{"id":"b","text":"Urease production"},{"id":"c","text":"Melanin production"},{"id":"d","text":"Invasive growth"}],"answerId":"a","explanation":"The polysaccharide capsule is the primary virulence factor of Cryptococcus neoformans, providing anti-phagocytic properties.","kind":"recall","origin":"ai"},{"id":"cryptococcus-malassezia~ai-1","moduleId":"cryptococcus-malassezia","stem":"Which test is most specific for diagnosing cryptococcal meningitis?","options":[{"id":"a","text":"India ink preparation"},{"id":"b","text":"Cryptococcal antigen (CrAg) test"},{"id":"c","text":"CSF culture"},{"id":"d","text":"Serum cryptococcal antibody test"}],"answerId":"b","explanation":"The Cryptococcal antigen (CrAg) test is sensitive and specific for diagnosing cryptococcal meningitis.","kind":"recall","origin":"ai"},{"id":"cryptococcus-malassezia~ai-2","moduleId":"cryptococcus-malassezia","stem":"A patient with advanced HIV presents with subacute headache and fever. Which finding is most indicative of cryptococcal meningitis?","options":[{"id":"a","text":"Clear halo on India ink preparation"},{"id":"b","text":"Positive CrAg test"},{"id":"c","text":"Hypo-/hyperpigmented macules on trunk"},{"id":"d","text":"Urease-positive culture"}],"answerId":"a","explanation":"A clear halo on India ink preparation indicates the presence of the encapsulated yeast, Cryptococcus neoformans, in the CSF.","kind":"recall","origin":"ai"},{"id":"cryptococcus-malassezia~ai-3","moduleId":"cryptococcus-malassezia","stem":"What is the recommended initial treatment for cryptococcal meningitis?","options":[{"id":"a","text":"Fluconazole alone"},{"id":"b","text":"Amphotericin B + Flucytosine"},{"id":"c","text":"Topical azoles"},{"id":"d","text":"Selenium sulfide"}],"answerId":"b","explanation":"The initial treatment for cryptococcal meningitis is induction therapy with Amphotericin B and Flucytosine.","kind":"recall","origin":"ai"},{"id":"cryptococcus-malassezia~ai-4","moduleId":"cryptococcus-malassezia","stem":"Which of the following is a common clinical presentation of Malassezia infection?","options":[{"id":"a","text":"Cryptococcal meningitis"},{"id":"b","text":"Tinea versicolor"},{"id":"c","text":"Pneumocystis pneumonia"},{"id":"d","text":"Seborrheic dermatitis"}],"answerId":"b","explanation":"Malassezia is known to cause tinea versicolor, characterized by hypo-/hyperpigmented macules on the skin.","kind":"clinical","origin":"ai"},{"id":"cryptococcus-malassezia~ai-5","moduleId":"cryptococcus-malassezia","stem":"In managing raised intracranial pressure in cryptococcal meningitis, what is a critical intervention?","options":[{"id":"a","text":"Antifungal therapy alone"},{"id":"b","text":"Serial therapeutic lumbar punctures"},{"id":"c","text":"Corticosteroids"},{"id":"d","text":"Immediate craniotomy"}],"answerId":"b","explanation":"Serial therapeutic lumbar punctures are essential to manage raised intracranial pressure in cryptococcal meningitis, in addition to antifungal therapy.","kind":"trap","origin":"ai"},{"id":"cryptococcus-malassezia~ai-6","moduleId":"cryptococcus-malassezia","stem":"How does Cryptococcus gattii differ from Cryptococcus neoformans in terms of host susceptibility?","options":[{"id":"a","text":"Affects immunocompromised hosts"},{"id":"b","text":"Affects immunocompetent hosts"},{"id":"c","text":"Causes more severe disease"},{"id":"d","text":"Is less virulent"}],"answerId":"b","explanation":"Cryptococcus gattii primarily affects immunocompetent hosts, unlike Cryptococcus neoformans, which typically affects immunocompromised individuals.","kind":"recall","origin":"ai"},{"id":"cryptococcus-malassezia~ai-7","moduleId":"cryptococcus-malassezia","stem":"A patient presents with tinea versicolor. Which organism is most likely responsible?","options":[{"id":"a","text":"Candida albicans"},{"id":"b","text":"Cryptococcus neoformans"},{"id":"c","text":"Malassezia furfur"},{"id":"d","text":"Aspergillus fumigatus"}],"answerId":"c","explanation":"Malassezia furfur is the yeast responsible for causing tinea versicolor, characterized by scaly macules on the skin.","kind":"recall","origin":"ai"},{"id":"cryptococcus-malassezia~ai-8","moduleId":"cryptococcus-malassezia","stem":"Which of the following conditions is most likely to be linked to the module on fungal lung infections?","options":[{"id":"a","text":"Cryptococcal meningitis"},{"id":"b","text":"Tinea versicolor"},{"id":"c","text":"Pneumocystis pneumonia"},{"id":"d","text":"Seborrheic dermatitis"}],"answerId":"c","explanation":"Pneumocystis pneumonia is a fungal lung infection that is often discussed in conjunction with cryptococcal infections in immunocompromised patients.","kind":"integration","linkedModuleIds":["fungal-lung-infections"],"origin":"ai"},{"id":"cryptococcus-malassezia~ai-9","moduleId":"cryptococcus-malassezia","stem":"Which skin condition caused by Malassezia is relevant to the study of bacterial and viral skin infections?","options":[{"id":"a","text":"Tinea corporis"},{"id":"b","text":"Tinea versicolor"},{"id":"c","text":"Impetigo"},{"id":"d","text":"Herpes simplex"}],"answerId":"b","explanation":"Tinea versicolor, caused by Malassezia, is a fungal skin condition that can be compared to bacterial and viral skin infections in terms of presentation and treatment.","kind":"integration","linkedModuleIds":["skin-infections-bacterial-fungal-viral"],"origin":"ai"}],"acute-inflammation":[{"id":"acute-inflammation~ai-0","moduleId":"acute-inflammation","stem":"What is the primary cellular component of acute inflammation?","options":[{"id":"a","text":"Eosinophils"},{"id":"b","text":"Lymphocytes"},{"id":"c","text":"Neutrophils"},{"id":"d","text":"Monocytes"}],"answerId":"c","explanation":"Neutrophils are the predominant leukocytes in acute inflammation, responding rapidly to infection or injury.","kind":"recall","origin":"ai"},{"id":"acute-inflammation~ai-1","moduleId":"acute-inflammation","stem":"Which mediator is primarily responsible for the vasodilation seen in acute inflammation?","options":[{"id":"a","text":"Histamine"},{"id":"b","text":"Prostaglandins"},{"id":"c","text":"Cytokines"},{"id":"d","text":"Leukotrienes"}],"answerId":"a","explanation":"Histamine is a key mediator that causes vasodilation during the acute inflammatory response.","kind":"mechanism","origin":"ai"},{"id":"acute-inflammation~ai-2","moduleId":"acute-inflammation","stem":"A patient presents with a swollen, red, and warm area on the skin after an insect bite. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Increased vascular permeability"},{"id":"b","text":"Decreased blood flow"},{"id":"c","text":"Increased hydrostatic pressure"},{"id":"d","text":"Decreased oncotic pressure"}],"answerId":"a","explanation":"Increased vascular permeability allows fluid and proteins to leak into the tissue, causing swelling and redness.","kind":"clinical","origin":"ai"},{"id":"acute-inflammation~ai-3","moduleId":"acute-inflammation","stem":"Which of the following findings would indicate an exudate rather than a transudate?","options":[{"id":"a","text":"Low protein content"},{"id":"b","text":"High specific gravity"},{"id":"c","text":"Clear appearance"},{"id":"d","text":"Low cell count"}],"answerId":"b","explanation":"Exudates are characterized by high protein content and specific gravity due to increased vascular permeability in inflammation.","kind":"trap","origin":"ai"},{"id":"acute-inflammation~ai-4","moduleId":"acute-inflammation","stem":"What is the outcome of acute inflammation if the inciting stimulus is not removed?","options":[{"id":"a","text":"Complete resolution"},{"id":"b","text":"Chronic inflammation"},{"id":"c","text":"Fibrosis"},{"id":"d","text":"Abscess formation"}],"answerId":"b","explanation":"If the stimulus persists, acute inflammation can progress to chronic inflammation.","kind":"mechanism","origin":"ai"},{"id":"acute-inflammation~ai-5","moduleId":"acute-inflammation","stem":"A patient with acute pericarditis presents with chest pain and a pericardial effusion. What type of fluid is most likely present in the effusion?","options":[{"id":"a","text":"Transudate"},{"id":"b","text":"Exudate"},{"id":"c","text":"Serous fluid"},{"id":"d","text":"Lymph"}],"answerId":"b","explanation":"Pericardial effusions in acute pericarditis are typically exudative due to inflammation.","kind":"integration","linkedModuleIds":["pericarditis"],"origin":"ai"},{"id":"acute-inflammation~ai-6","moduleId":"acute-inflammation","stem":"In a case of chronic inflammation, which of the following is a likely outcome if acute inflammation fails to resolve?","options":[{"id":"a","text":"Complete healing"},{"id":"b","text":"Granuloma formation"},{"id":"c","text":"Abscess formation"},{"id":"d","text":"Vasodilation"}],"answerId":"b","explanation":"Chronic inflammation can lead to granuloma formation as a response to persistent stimuli.","kind":"integration","linkedModuleIds":["chronic-inflammation-granuloma"],"origin":"ai"}],"cellular-adaptations-growth":[{"id":"cellular-adaptations-growth~ai-0","moduleId":"cellular-adaptations-growth","stem":"What is the primary mechanism by which cardiac myocytes respond to pressure overload in hypertension?","options":[{"id":"a","text":"Hyperplasia"},{"id":"b","text":"Hypertrophy"},{"id":"c","text":"Atrophy"},{"id":"d","text":"Metaplasia"}],"answerId":"b","explanation":"Cardiac myocytes are permanent, non-dividing cells that respond to pressure overload by hypertrophy, increasing cell size rather than number.","kind":"mechanism","origin":"ai"},{"id":"cellular-adaptations-growth~ai-1","moduleId":"cellular-adaptations-growth","stem":"Which of the following conditions is most likely to cause atrophy of skeletal muscle?","options":[{"id":"a","text":"Regular exercise"},{"id":"b","text":"Prolonged immobilization"},{"id":"c","text":"Increased hormonal stimulation"},{"id":"d","text":"Nutritional excess"}],"answerId":"b","explanation":"Prolonged immobilization leads to disuse atrophy of skeletal muscle due to decreased protein synthesis and increased degradation.","kind":"clinical","origin":"ai"},{"id":"cellular-adaptations-growth~ai-2","moduleId":"cellular-adaptations-growth","stem":"What is a common clinical finding in patients with endometrial hyperplasia due to unopposed estrogen?","options":[{"id":"a","text":"Thickened left ventricle"},{"id":"b","text":"Enlarged uterus"},{"id":"c","text":"Endometrial thickening"},{"id":"d","text":"Wasted muscle"}],"answerId":"c","explanation":"Endometrial hyperplasia presents as endometrial thickening due to increased cell number from hormonal stimulation.","kind":"recall","origin":"ai"},{"id":"cellular-adaptations-growth~ai-3","moduleId":"cellular-adaptations-growth","stem":"Which adaptation occurs in the liver following partial hepatectomy?","options":[{"id":"a","text":"Hypertrophy"},{"id":"b","text":"Hyperplasia"},{"id":"c","text":"Atrophy"},{"id":"d","text":"Metaplasia"}],"answerId":"b","explanation":"The liver undergoes compensatory hyperplasia to regenerate lost tissue after partial hepatectomy.","kind":"recall","origin":"ai"},{"id":"cellular-adaptations-growth~ai-4","moduleId":"cellular-adaptations-growth","stem":"Why does the heart undergo hypertrophy rather than hyperplasia in response to increased workload?","options":[{"id":"a","text":"Myocytes can divide"},{"id":"b","text":"Myocytes are permanent cells"},{"id":"c","text":"Hypertrophy is always pathological"},{"id":"d","text":"Hyperplasia is more efficient"}],"answerId":"b","explanation":"Cardiac myocytes are permanent, non-dividing cells, so they can only undergo hypertrophy in response to increased workload.","kind":"trap","origin":"ai"},{"id":"cellular-adaptations-growth~ai-5","moduleId":"cellular-adaptations-growth","stem":"How does chronic hypothyroidism lead to goiter formation?","options":[{"id":"a","text":"Increased cell size"},{"id":"b","text":"Increased cell number"},{"id":"c","text":"Decreased cell size"},{"id":"d","text":"Decreased cell number"}],"answerId":"b","explanation":"Chronic hypothyroidism causes hyperplasia of thyroid follicular cells due to increased TSH stimulation, leading to goiter formation.","kind":"integration","linkedModuleIds":["hypothyroidism-goiter"],"origin":"ai"},{"id":"cellular-adaptations-growth~ai-6","moduleId":"cellular-adaptations-growth","stem":"What type of cellular adaptation is primarily involved in the remodeling of the heart in response to chronic pressure overload?","options":[{"id":"a","text":"Hyperplasia"},{"id":"b","text":"Hypertrophy"},{"id":"c","text":"Atrophy"},{"id":"d","text":"Metaplasia"}],"answerId":"b","explanation":"Cardiac remodeling in response to chronic pressure overload primarily involves hypertrophy of cardiac myocytes.","kind":"integration","linkedModuleIds":["cardiac-hypertrophy-remodeling"],"origin":"ai"}],"apoptosis-cell-death":[{"id":"apoptosis-cell-death~ai-0","moduleId":"apoptosis-cell-death","stem":"Which of the following is a characteristic feature of apoptosis?","options":[{"id":"a","text":"Cell swelling"},{"id":"b","text":"Membrane rupture"},{"id":"c","text":"Cell shrinkage"},{"id":"d","text":"Inflammation"}],"answerId":"c","explanation":"Apoptosis is characterized by cell shrinkage and the formation of apoptotic bodies, while necrosis involves cell swelling and membrane rupture.","kind":"recall","origin":"ai"},{"id":"apoptosis-cell-death~ai-1","moduleId":"apoptosis-cell-death","stem":"What initiates the intrinsic pathway of apoptosis?","options":[{"id":"a","text":"Fas ligand binding to Fas receptor"},{"id":"b","text":"Release of cytochrome c from mitochondria"},{"id":"c","text":"Activation of caspase-8"},{"id":"d","text":"Granzyme B release from cytotoxic T cells"}],"answerId":"b","explanation":"The intrinsic pathway is initiated by cellular stress or DNA damage leading to the release of cytochrome c from mitochondria.","kind":"mechanism","origin":"ai"},{"id":"apoptosis-cell-death~ai-2","moduleId":"apoptosis-cell-death","stem":"A patient presents with a lymphoma characterized by BCL-2 overexpression. What is the most likely consequence of this alteration?","options":[{"id":"a","text":"Increased apoptosis"},{"id":"b","text":"Decreased apoptosis"},{"id":"c","text":"Increased necrosis"},{"id":"d","text":"Decreased necrosis"}],"answerId":"b","explanation":"BCL-2 overexpression inhibits apoptosis, leading to decreased programmed cell death, which can contribute to cancer progression.","kind":"clinical","origin":"ai"},{"id":"apoptosis-cell-death~ai-3","moduleId":"apoptosis-cell-death","stem":"Which of the following statements correctly differentiates apoptosis from necrosis?","options":[{"id":"a","text":"Both cause inflammation"},{"id":"b","text":"Apoptosis affects groups of cells"},{"id":"c","text":"Apoptosis is energy-dependent"},{"id":"d","text":"Necrosis is a regulated process"}],"answerId":"c","explanation":"Apoptosis is a regulated, energy-dependent process affecting single cells, while necrosis is unregulated and affects groups of cells.","kind":"trap","origin":"ai"},{"id":"apoptosis-cell-death~ai-4","moduleId":"apoptosis-cell-death","stem":"What is the role of granzyme B in apoptosis?","options":[{"id":"a","text":"Activates caspase-8"},{"id":"b","text":"Triggers mitochondrial cytochrome c release"},{"id":"c","text":"Degrades BCL-2 proteins"},{"id":"d","text":"Directly activates caspases"}],"answerId":"d","explanation":"Granzyme B directly activates caspases in target cells, leading to apoptosis, particularly in the context of cytotoxic T-cell activity.","kind":"mechanism","origin":"ai"},{"id":"apoptosis-cell-death~ai-5","moduleId":"apoptosis-cell-death","stem":"How does apoptosis relate to cancer development?","options":[{"id":"a","text":"Increased apoptosis promotes tumor growth"},{"id":"b","text":"Decreased apoptosis can lead to tumorigenesis"},{"id":"c","text":"Apoptosis has no role in cancer"},{"id":"d","text":"Necrosis is the primary mechanism in cancer"}],"answerId":"b","explanation":"Decreased apoptosis allows for the survival of damaged cells, which can contribute to tumorigenesis and cancer progression.","kind":"integration","linkedModuleIds":["carcinogenesis-molecular"],"origin":"ai"},{"id":"apoptosis-cell-death~ai-6","moduleId":"apoptosis-cell-death","stem":"Which of the following findings would most likely indicate apoptosis rather than necrosis in tissue samples?","options":[{"id":"a","text":"Swollen cells with ruptured membranes"},{"id":"b","text":"Condensed chromatin and apoptotic bodies"},{"id":"c","text":"Inflammatory cell infiltration"},{"id":"d","text":"Necrotic debris"}],"answerId":"b","explanation":"Condensed chromatin and the presence of apoptotic bodies are indicative of apoptosis, while swelling and inflammation are associated with necrosis.","kind":"integration","linkedModuleIds":["necrosis-patterns"],"origin":"ai"}],"cell-injury-mechanisms":[{"id":"cell-injury-mechanisms~ai-0","moduleId":"cell-injury-mechanisms","stem":"What is the most common cause of cell injury?","options":[{"id":"a","text":"Hypoxia"},{"id":"b","text":"Ischemia"},{"id":"c","text":"Chemical toxins"},{"id":"d","text":"Infections"}],"answerId":"b","explanation":"Ischemia is the most common cause of cell injury as it deprives cells of both oxygen and nutrients.","kind":"recall","origin":"ai"},{"id":"cell-injury-mechanisms~ai-1","moduleId":"cell-injury-mechanisms","stem":"Which mechanism primarily leads to cellular swelling in reversible injury?","options":[{"id":"a","text":"Increased cytosolic calcium"},{"id":"b","text":"ATP depletion"},{"id":"c","text":"Mitochondrial damage"},{"id":"d","text":"Reactive oxygen species"}],"answerId":"b","explanation":"Cellular swelling occurs due to ATP depletion, which impairs the function of the Na⁺/K⁺ pump.","kind":"mechanism","origin":"ai"},{"id":"cell-injury-mechanisms~ai-2","moduleId":"cell-injury-mechanisms","stem":"A patient presents with elevated serum troponin levels after a myocardial infarction. What does this indicate?","options":[{"id":"a","text":"Reversible injury"},{"id":"b","text":"Irreversible injury"},{"id":"c","text":"Adaptation"},{"id":"d","text":"Cellular swelling"}],"answerId":"b","explanation":"Elevated serum troponin levels indicate irreversible membrane damage and enzyme leakage.","kind":"clinical","origin":"ai"},{"id":"cell-injury-mechanisms~ai-3","moduleId":"cell-injury-mechanisms","stem":"What is a key feature of ischemia-reperfusion injury?","options":[{"id":"a","text":"Increased ATP production"},{"id":"b","text":"Decreased reactive oxygen species"},{"id":"c","text":"Worsening tissue damage after blood flow restoration"},{"id":"d","text":"Immediate recovery of function"}],"answerId":"c","explanation":"Ischemia-reperfusion injury is characterized by worsening damage due to a burst of reactive oxygen species and calcium overload upon restoring blood flow.","kind":"trap","origin":"ai"},{"id":"cell-injury-mechanisms~ai-4","moduleId":"cell-injury-mechanisms","stem":"Which of the following is a consequence of increased cytosolic calcium during cell injury?","options":[{"id":"a","text":"Inhibition of ATPases"},{"id":"b","text":"Activation of phospholipases"},{"id":"c","text":"Decreased mitochondrial function"},{"id":"d","text":"Increased ribosome attachment"}],"answerId":"b","explanation":"Increased cytosolic calcium activates phospholipases, leading to membrane damage.","kind":"mechanism","origin":"ai"},{"id":"cell-injury-mechanisms~ai-5","moduleId":"cell-injury-mechanisms","stem":"How does free radical injury primarily affect cells?","options":[{"id":"a","text":"By increasing ATP production"},{"id":"b","text":"By causing lipid peroxidation"},{"id":"c","text":"By enhancing mitochondrial function"},{"id":"d","text":"By promoting cellular adaptation"}],"answerId":"b","explanation":"Free radicals cause lipid peroxidation, leading to damage of cellular membranes and organelles.","kind":"mechanism","origin":"ai"},{"id":"cell-injury-mechanisms~ai-6","moduleId":"cell-injury-mechanisms","stem":"How do metabolic junction points relate to cell injury mechanisms?","options":[{"id":"a","text":"They provide energy during ischemia"},{"id":"b","text":"They are unaffected by oxidative stress"},{"id":"c","text":"They are involved in ATP depletion during injury"},{"id":"d","text":"They prevent cellular adaptation"}],"answerId":"c","explanation":"Metabolic junction points are crucial in ATP production, and their dysfunction contributes to ATP depletion during cell injury.","kind":"integration","linkedModuleIds":["metabolic-junction-points"],"origin":"ai"},{"id":"cell-injury-mechanisms~ai-7","moduleId":"cell-injury-mechanisms","stem":"What role do mutations play in cell injury mechanisms?","options":[{"id":"a","text":"They enhance cellular adaptation"},{"id":"b","text":"They increase ATP production"},{"id":"c","text":"They can lead to irreversible injury"},{"id":"d","text":"They prevent oxidative stress"}],"answerId":"c","explanation":"Mutations can disrupt normal cellular functions, leading to irreversible injury and cell death.","kind":"integration","linkedModuleIds":["mutations-dna-damage"],"origin":"ai"}],"intracellular-accumulations-calcification":[{"id":"intracellular-accumulations-calcification~ai-0","moduleId":"intracellular-accumulations-calcification","stem":"What is the primary cause of hepatic steatosis?","options":[{"id":"a","text":"Excessive alcohol consumption"},{"id":"b","text":"Viral hepatitis"},{"id":"c","text":"Chronic heart failure"},{"id":"d","text":"Bacterial infection"}],"answerId":"a","explanation":"Hepatic steatosis, or fatty liver, is primarily caused by excessive alcohol consumption, leading to triglyceride accumulation in hepatocytes.","kind":"recall","origin":"ai"},{"id":"intracellular-accumulations-calcification~ai-1","moduleId":"intracellular-accumulations-calcification","stem":"Which pigment is indicative of iron overload in tissues?","options":[{"id":"a","text":"Lipofuscin"},{"id":"b","text":"Bilirubin"},{"id":"c","text":"Haemosiderin"},{"id":"d","text":"Melanin"}],"answerId":"c","explanation":"Haemosiderin is the golden-brown pigment that indicates iron overload, particularly in conditions like hemochromatosis.","kind":"recall","origin":"ai"},{"id":"intracellular-accumulations-calcification~ai-2","moduleId":"intracellular-accumulations-calcification","stem":"What distinguishes dystrophic calcification from metastatic calcification?","options":[{"id":"a","text":"Presence of hypercalcemia"},{"id":"b","text":"Location of calcium deposits"},{"id":"c","text":"Type of tissue affected"},{"id":"d","text":"All of the above"}],"answerId":"a","explanation":"Dystrophic calcification occurs in damaged tissue with normal serum calcium, while metastatic calcification occurs in normal tissue due to hypercalcemia.","kind":"trap","origin":"ai"},{"id":"intracellular-accumulations-calcification~ai-3","moduleId":"intracellular-accumulations-calcification","stem":"A patient presents with a large, pale liver on imaging. What is the most likely underlying condition?","options":[{"id":"a","text":"Chronic hepatitis"},{"id":"b","text":"Fatty liver disease"},{"id":"c","text":"Cirrhosis"},{"id":"d","text":"Hepatic carcinoma"}],"answerId":"b","explanation":"A large, pale liver with fat vacuoles is characteristic of fatty liver disease, often due to steatosis.","kind":"clinical","origin":"ai"},{"id":"intracellular-accumulations-calcification~ai-4","moduleId":"intracellular-accumulations-calcification","stem":"What type of calcification is seen in damaged heart valves with normal serum calcium levels?","options":[{"id":"a","text":"Metastatic calcification"},{"id":"b","text":"Dystrophic calcification"},{"id":"c","text":"Physiologic calcification"},{"id":"d","text":"Pathologic calcification"}],"answerId":"b","explanation":"Dystrophic calcification occurs in damaged tissues, such as heart valves, with normal serum calcium levels.","kind":"recall","origin":"ai"},{"id":"intracellular-accumulations-calcification~ai-5","moduleId":"intracellular-accumulations-calcification","stem":"In a patient with hyperparathyroidism, which type of calcification is expected?","options":[{"id":"a","text":"Dystrophic calcification"},{"id":"b","text":"Metastatic calcification"},{"id":"c","text":"Physiologic calcification"},{"id":"d","text":"None of the above"}],"answerId":"b","explanation":"Metastatic calcification occurs in normal tissues due to hypercalcemia, which is seen in hyperparathyroidism.","kind":"recall","origin":"ai"},{"id":"intracellular-accumulations-calcification~ai-6","moduleId":"intracellular-accumulations-calcification","stem":"How can PAS staining be useful in diagnosing glycogen accumulation disorders?","options":[{"id":"a","text":"It stains proteins"},{"id":"b","text":"It highlights lipid deposits"},{"id":"c","text":"It identifies glycogen deposits"},{"id":"d","text":"It detects calcium deposits"}],"answerId":"c","explanation":"PAS staining specifically identifies glycogen deposits, which are accumulated in conditions like diabetes and glycogen storage diseases.","kind":"integration","linkedModuleIds":["diagnostic-pathology-methods"],"origin":"ai"},{"id":"intracellular-accumulations-calcification~ai-7","moduleId":"intracellular-accumulations-calcification","stem":"Which mechanism is primarily responsible for the accumulation of lipofuscin in aging cells?","options":[{"id":"a","text":"Increased production of lipids"},{"id":"b","text":"Defective degradation of cellular components"},{"id":"c","text":"Increased oxidative stress"},{"id":"d","text":"Decreased blood supply"}],"answerId":"c","explanation":"Lipofuscin accumulation is primarily due to increased oxidative stress and lipid peroxidation, leading to cellular damage.","kind":"integration","linkedModuleIds":["cell-injury-mechanisms"],"origin":"ai"}],"metaplasia-dysplasia":[{"id":"metaplasia-dysplasia~ai-0","moduleId":"metaplasia-dysplasia","stem":"What is the primary mechanism underlying metaplasia?","options":[{"id":"a","text":"Transformation of differentiated cells"},{"id":"b","text":"Stem-cell reprogramming"},{"id":"c","text":"Increased cell proliferation"},{"id":"d","text":"Genetic mutation"}],"answerId":"b","explanation":"Metaplasia involves stem-cell reprogramming where one differentiated cell type is replaced by another to better withstand stress.","kind":"mechanism","origin":"ai"},{"id":"metaplasia-dysplasia~ai-1","moduleId":"metaplasia-dysplasia","stem":"Which of the following findings is characteristic of dysplasia?","options":[{"id":"a","text":"Intact basement membrane"},{"id":"b","text":"Invasive growth"},{"id":"c","text":"Uniform cell architecture"},{"id":"d","text":"Loss of nuclear atypia"}],"answerId":"a","explanation":"Dysplasia is characterized by disordered growth with abnormal cells while maintaining an intact basement membrane.","kind":"recall","origin":"ai"},{"id":"metaplasia-dysplasia~ai-2","moduleId":"metaplasia-dysplasia","stem":"A patient presents with Barrett's esophagus. What type of cellular change has occurred?","options":[{"id":"a","text":"Dysplasia"},{"id":"b","text":"Metaplasia"},{"id":"c","text":"Invasive carcinoma"},{"id":"d","text":"Carcinoma in situ"}],"answerId":"b","explanation":"Barrett's esophagus is an example of metaplasia, where squamous epithelium is replaced by columnar epithelium due to chronic acid reflux.","kind":"recall","origin":"ai"},{"id":"metaplasia-dysplasia~ai-3","moduleId":"metaplasia-dysplasia","stem":"Which statement correctly differentiates dysplasia from invasive carcinoma?","options":[{"id":"a","text":"Dysplasia has breached the basement membrane"},{"id":"b","text":"Dysplasia is reversible, carcinoma is not"},{"id":"c","text":"Dysplasia is always malignant"},{"id":"d","text":"Dysplasia shows increased mitotic activity only"}],"answerId":"b","explanation":"Dysplasia is characterized as pre-malignant and potentially reversible, while invasive carcinoma has breached the basement membrane and is malignant.","kind":"trap","origin":"ai"},{"id":"metaplasia-dysplasia~ai-4","moduleId":"metaplasia-dysplasia","stem":"What is the clinical significance of monitoring Barrett's esophagus?","options":[{"id":"a","text":"It is always cancerous"},{"id":"b","text":"It can progress to dysplasia"},{"id":"c","text":"It indicates chronic inflammation"},{"id":"d","text":"It can progress to invasive cancer"}],"answerId":"d","explanation":"Barrett's esophagus can progress to invasive cancer through the stages of metaplasia and dysplasia.","kind":"clinical","origin":"ai"},{"id":"metaplasia-dysplasia~ai-5","moduleId":"metaplasia-dysplasia","stem":"Which of the following is a common example of squamous metaplasia?","options":[{"id":"a","text":"Bronchial epithelium in smokers"},{"id":"b","text":"Endocervical epithelium in HPV"},{"id":"c","text":"Intestinal epithelium in celiac disease"},{"id":"d","text":"Gastric epithelium in chronic gastritis"}],"answerId":"a","explanation":"Squamous metaplasia is commonly seen in the bronchial epithelium of smokers, where ciliated columnar cells are replaced by squamous cells.","kind":"recall","origin":"ai"},{"id":"metaplasia-dysplasia~ai-6","moduleId":"metaplasia-dysplasia","stem":"How does chronic injury lead to dysplasia?","options":[{"id":"a","text":"By causing irreversible cell damage"},{"id":"b","text":"By promoting stem-cell reprogramming"},{"id":"c","text":"By inducing metaplasia first"},{"id":"d","text":"By enhancing apoptosis"}],"answerId":"c","explanation":"Chronic injury can lead to metaplasia, which may progress to dysplasia if the injurious stimulus persists.","kind":"integration","linkedModuleIds":["cellular-adaptations-growth"],"origin":"ai"},{"id":"metaplasia-dysplasia~ai-7","moduleId":"metaplasia-dysplasia","stem":"What is the relationship between dysplasia and invasive carcinoma?","options":[{"id":"a","text":"Dysplasia is a type of invasive carcinoma"},{"id":"b","text":"Dysplasia can progress to invasive carcinoma"},{"id":"c","text":"Dysplasia is always reversible"},{"id":"d","text":"Dysplasia indicates metastatic potential"}],"answerId":"b","explanation":"Dysplasia is a pre-malignant condition that can progress to invasive carcinoma if not treated.","kind":"integration","linkedModuleIds":["neoplasia-differentiation-invasion"],"origin":"ai"}],"necrosis-patterns":[{"id":"necrosis-patterns~ai-0","moduleId":"necrosis-patterns","stem":"What type of necrosis is characterized by preserved tissue architecture and occurs in most solid organs due to ischemic infarction?","options":[{"id":"a","text":"Liquefactive necrosis"},{"id":"b","text":"Caseous necrosis"},{"id":"c","text":"Coagulative necrosis"},{"id":"d","text":"Fat necrosis"}],"answerId":"c","explanation":"Coagulative necrosis is the pattern seen in ischemic infarction of solid organs, preserving the architecture of the tissue.","kind":"recall","origin":"ai"},{"id":"necrosis-patterns~ai-1","moduleId":"necrosis-patterns","stem":"Which necrosis pattern is typically associated with tuberculosis?","options":[{"id":"a","text":"Fibrinoid necrosis"},{"id":"b","text":"Liquefactive necrosis"},{"id":"c","text":"Caseous necrosis"},{"id":"d","text":"Gangrenous necrosis"}],"answerId":"c","explanation":"Caseous necrosis is the hallmark of tuberculosis, presenting as cheese-like, soft, white friable debris.","kind":"recall","origin":"ai"},{"id":"necrosis-patterns~ai-2","moduleId":"necrosis-patterns","stem":"What is the primary mechanism behind liquefactive necrosis observed in the brain?","options":[{"id":"a","text":"Protein denaturation"},{"id":"b","text":"Enzymatic digestion"},{"id":"c","text":"Calcium saponification"},{"id":"d","text":"Fibrin deposition"}],"answerId":"b","explanation":"Liquefactive necrosis is characterized by enzymatic digestion of tissue, leading to a soft, liquid state, especially in the brain.","kind":"mechanism","origin":"ai"},{"id":"necrosis-patterns~ai-3","moduleId":"necrosis-patterns","stem":"A patient presents with a firm, pale wedge-shaped infarct in the kidney. What type of necrosis is this most likely to represent?","options":[{"id":"a","text":"Liquefactive necrosis"},{"id":"b","text":"Coagulative necrosis"},{"id":"c","text":"Caseous necrosis"},{"id":"d","text":"Fat necrosis"}],"answerId":"b","explanation":"This presentation is typical of coagulative necrosis due to ischemic infarction, where architecture is preserved.","kind":"recall","origin":"ai"},{"id":"necrosis-patterns~ai-4","moduleId":"necrosis-patterns","stem":"Which of the following is a common finding in fat necrosis?","options":[{"id":"a","text":"Cheese-like debris"},{"id":"b","text":"Chalky white saponification"},{"id":"c","text":"Bright pink fibrin deposits"},{"id":"d","text":"Soft liquefied pus"}],"answerId":"b","explanation":"Fat necrosis is characterized by chalky white saponification resulting from lipase action in conditions like acute pancreatitis.","kind":"recall","origin":"ai"},{"id":"necrosis-patterns~ai-5","moduleId":"necrosis-patterns","stem":"Which type of necrosis occurs in the brain following ischemic infarction, contrary to other solid organs?","options":[{"id":"a","text":"Coagulative necrosis"},{"id":"b","text":"Liquefactive necrosis"},{"id":"c","text":"Caseous necrosis"},{"id":"d","text":"Fibrinoid necrosis"}],"answerId":"b","explanation":"The brain undergoes liquefactive necrosis after ischemic infarction, unlike other solid organs that typically show coagulative necrosis.","kind":"trap","origin":"ai"},{"id":"necrosis-patterns~ai-6","moduleId":"necrosis-patterns","stem":"How does necrosis differ from apoptosis in terms of cellular response?","options":[{"id":"a","text":"Necrosis is a regulated process, apoptosis is not"},{"id":"b","text":"Necrosis leads to inflammation, apoptosis does not"},{"id":"c","text":"Necrosis involves cell shrinkage, apoptosis involves swelling"},{"id":"d","text":"Necrosis is always pathological, apoptosis is always physiological"}],"answerId":"b","explanation":"Necrosis results in inflammation due to cell death and leakage of contents, while apoptosis is a regulated process without inflammation.","kind":"integration","linkedModuleIds":["apoptosis-cell-death"],"origin":"ai"},{"id":"necrosis-patterns~ai-7","moduleId":"necrosis-patterns","stem":"Which mechanism of cell injury is primarily responsible for coagulative necrosis in myocardial infarction?","options":[{"id":"a","text":"Ischemia leading to hypoxia"},{"id":"b","text":"Toxic injury from drugs"},{"id":"c","text":"Infection by bacteria"},{"id":"d","text":"Autoimmune response"}],"answerId":"a","explanation":"Ischemia leading to hypoxia is the primary mechanism causing coagulative necrosis in myocardial infarction.","kind":"integration","linkedModuleIds":["myocardial-infarction-pathology"],"origin":"ai"}],"mycetoma-eumycetoma":[{"id":"mycetoma-eumycetoma~ai-0","moduleId":"mycetoma-eumycetoma","stem":"What is the clinical triad characteristic of mycetoma?","options":[{"id":"a","text":"Painless subcutaneous swelling, fever, and lymphadenopathy"},{"id":"b","text":"Painless subcutaneous swelling, multiple discharging sinus tracts, and extrusion of grains"},{"id":"c","text":"Painless ulceration, necrotic tissue, and systemic symptoms"},{"id":"d","text":"Painless swelling, erythema, and pruritus"}],"answerId":"b","explanation":"The classic triad of mycetoma includes painless subcutaneous swelling, multiple discharging sinus tracts, and the extrusion of grains.","kind":"recall","origin":"ai"},{"id":"mycetoma-eumycetoma~ai-1","moduleId":"mycetoma-eumycetoma","stem":"Which organism is primarily responsible for eumycetoma?","options":[{"id":"a","text":"Nocardia"},{"id":"b","text":"Actinomadura"},{"id":"c","text":"Madurella"},{"id":"d","text":"Streptomyces"}],"answerId":"c","explanation":"Eumycetoma is primarily caused by the fungus Madurella, which is characterized by black grains.","kind":"recall","origin":"ai"},{"id":"mycetoma-eumycetoma~ai-2","moduleId":"mycetoma-eumycetoma","stem":"A patient presents with a chronic foot swelling and discharging sinuses containing black grains. What is the most appropriate initial management?","options":[{"id":"a","text":"Immediate surgical excision"},{"id":"b","text":"Prolonged antifungal therapy"},{"id":"c","text":"Prolonged antibiotic therapy"},{"id":"d","text":"Observation and follow-up"}],"answerId":"b","explanation":"The presence of black grains indicates eumycetoma, which requires prolonged antifungal therapy as the initial management.","kind":"clinical","origin":"ai"},{"id":"mycetoma-eumycetoma~ai-3","moduleId":"mycetoma-eumycetoma","stem":"What is the key distinguishing feature between eumycetoma and actinomycetoma?","options":[{"id":"a","text":"Color of the grains"},{"id":"b","text":"Presence of systemic symptoms"},{"id":"c","text":"Location of the infection"},{"id":"d","text":"Age of the patient"}],"answerId":"a","explanation":"The color of the grains is the key distinguishing feature: eumycetoma has black grains, while actinomycetoma has pale or yellow grains.","kind":"trap","origin":"ai"},{"id":"mycetoma-eumycetoma~ai-4","moduleId":"mycetoma-eumycetoma","stem":"Which finding on imaging is most indicative of advanced mycetoma?","options":[{"id":"a","text":"Soft tissue swelling"},{"id":"b","text":"Bone destruction"},{"id":"c","text":"Lymphadenopathy"},{"id":"d","text":"Subcutaneous nodules"}],"answerId":"b","explanation":"Bone destruction on imaging is indicative of advanced mycetoma, reflecting its invasive nature.","kind":"recall","origin":"ai"},{"id":"mycetoma-eumycetoma~ai-5","moduleId":"mycetoma-eumycetoma","stem":"A patient with a grain-discharging lesion responds to co-trimoxazole. What type of mycetoma is most likely present?","options":[{"id":"a","text":"Eumycetoma"},{"id":"b","text":"Actinomycetoma"},{"id":"c","text":"Chromoblastomycosis"},{"id":"d","text":"Sporotrichosis"}],"answerId":"b","explanation":"The response to co-trimoxazole indicates actinomycetoma, which is caused by filamentous bacteria.","kind":"clinical","origin":"ai"},{"id":"mycetoma-eumycetoma~ai-6","moduleId":"mycetoma-eumycetoma","stem":"How does the treatment of eumycetoma differ from actinomycetoma?","options":[{"id":"a","text":"Eumycetoma requires surgery, actinomycetoma does not"},{"id":"b","text":"Eumycetoma is treated with antibiotics, actinomycetoma with antifungals"},{"id":"c","text":"Eumycetoma requires prolonged antifungals, actinomycetoma requires prolonged antibiotics"},{"id":"d","text":"Eumycetoma is self-limiting, actinomycetoma is not"}],"answerId":"c","explanation":"Eumycetoma requires prolonged antifungals and often surgery, while actinomycetoma is treated with prolonged antibiotics.","kind":"integration","linkedModuleIds":["nocardia-actinomyces"],"origin":"ai"},{"id":"mycetoma-eumycetoma~ai-7","moduleId":"mycetoma-eumycetoma","stem":"Which of the following conditions shares a similar clinical presentation with mycetoma?","options":[{"id":"a","text":"Tinea corporis"},{"id":"b","text":"Chromoblastomycosis"},{"id":"c","text":"Psoriasis"},{"id":"d","text":"Candidiasis"}],"answerId":"b","explanation":"Chromoblastomycosis is another subcutaneous mycosis that can present with similar chronic skin lesions as mycetoma.","kind":"integration","linkedModuleIds":["chromoblastomycosis-subcutaneous-mycoses"],"origin":"ai"}],"opportunistic-molds-aspergillus-mucorales":[{"id":"opportunistic-molds-aspergillus-mucorales~ai-0","moduleId":"opportunistic-molds-aspergillus-mucorales","stem":"What is the characteristic hyphal morphology of Aspergillus species?","options":[{"id":"a","text":"Aseptate hyphae branching at wide angles"},{"id":"b","text":"Septate hyphae branching at acute angles"},{"id":"c","text":"Aseptate hyphae branching at acute angles"},{"id":"d","text":"Septate hyphae branching at right angles"}],"answerId":"b","explanation":"Aspergillus species, particularly A. fumigatus, are characterized by septate hyphae that branch at acute angles (~45°).","kind":"recall","origin":"ai"},{"id":"opportunistic-molds-aspergillus-mucorales~ai-1","moduleId":"opportunistic-molds-aspergillus-mucorales","stem":"Which condition is primarily associated with allergic bronchopulmonary aspergillosis (ABPA)?","options":[{"id":"a","text":"Diabetes mellitus"},{"id":"b","text":"Asthma or cystic fibrosis"},{"id":"c","text":"Chronic obstructive pulmonary disease"},{"id":"d","text":"Pulmonary fibrosis"}],"answerId":"b","explanation":"ABPA is commonly seen in patients with asthma or cystic fibrosis, characterized by high IgE levels and eosinophilia.","kind":"recall","origin":"ai"},{"id":"opportunistic-molds-aspergillus-mucorales~ai-2","moduleId":"opportunistic-molds-aspergillus-mucorales","stem":"In a neutropenic patient, which finding is indicative of invasive aspergillosis?","options":[{"id":"a","text":"Black necrotic palate"},{"id":"b","text":"Fungus ball in lung cavity"},{"id":"c","text":"Pulmonary nodules with halo sign"},{"id":"d","text":"Aseptate hyphae"}],"answerId":"c","explanation":"Invasive aspergillosis is characterized by pulmonary nodules with a 'halo' sign in neutropenic patients.","kind":"recall","origin":"ai"},{"id":"opportunistic-molds-aspergillus-mucorales~ai-3","moduleId":"opportunistic-molds-aspergillus-mucorales","stem":"What is the first-line treatment for rhino-orbital-cerebral mucormycosis?","options":[{"id":"a","text":"Voriconazole"},{"id":"b","text":"Amphotericin B"},{"id":"c","text":"Fluconazole"},{"id":"d","text":"Echinocandins"}],"answerId":"b","explanation":"Mucormycosis requires urgent surgical debridement and treatment with amphotericin B due to its angioinvasive nature.","kind":"recall","origin":"ai"},{"id":"opportunistic-molds-aspergillus-mucorales~ai-4","moduleId":"opportunistic-molds-aspergillus-mucorales","stem":"Why is surgical debridement essential in the management of mucormycosis?","options":[{"id":"a","text":"Antifungals penetrate well into necrotic tissue"},{"id":"b","text":"Mucorales are easily treated with oral antifungals"},{"id":"c","text":"Mucormycosis causes ischemic necrosis that antifungals cannot reach"},{"id":"d","text":"Surgical intervention is not necessary for fungal infections"}],"answerId":"c","explanation":"Mucormycosis causes ischemic necrosis, making surgical debridement essential as antifungals do not penetrate devitalized areas effectively.","kind":"trap","origin":"ai"},{"id":"opportunistic-molds-aspergillus-mucorales~ai-5","moduleId":"opportunistic-molds-aspergillus-mucorales","stem":"Which of the following is a distinguishing feature of Mucorales compared to Aspergillus?","options":[{"id":"a","text":"Septate hyphae"},{"id":"b","text":"Acute angle branching"},{"id":"c","text":"Aseptate hyphae"},{"id":"d","text":"Halo sign"}],"answerId":"c","explanation":"Mucorales are characterized by aseptate hyphae that branch at wide angles (~90°), unlike Aspergillus which has septate hyphae.","kind":"recall","origin":"ai"},{"id":"opportunistic-molds-aspergillus-mucorales~ai-6","moduleId":"opportunistic-molds-aspergillus-mucorales","stem":"How does the treatment of invasive aspergillosis differ from that of mucormycosis?","options":[{"id":"a","text":"Both require amphotericin B"},{"id":"b","text":"Invasive aspergillosis is treated with voriconazole"},{"id":"c","text":"Both require surgical intervention"},{"id":"d","text":"Mucormycosis is treated with voriconazole"}],"answerId":"b","explanation":"Invasive aspergillosis is primarily treated with voriconazole, while mucormycosis requires amphotericin B and surgical debridement.","kind":"integration","linkedModuleIds":["antifungal-agents-lab-diagnosis"],"origin":"ai"},{"id":"opportunistic-molds-aspergillus-mucorales~ai-7","moduleId":"opportunistic-molds-aspergillus-mucorales","stem":"Which of the following fungal infections is most likely to present with black necrosis in a diabetic patient?","options":[{"id":"a","text":"Allergic bronchopulmonary aspergillosis"},{"id":"b","text":"Aspergilloma"},{"id":"c","text":"Invasive aspergillosis"},{"id":"d","text":"Rhino-orbital-cerebral mucormycosis"}],"answerId":"d","explanation":"Rhino-orbital-cerebral mucormycosis is associated with black necrosis in diabetic patients due to its angioinvasive nature.","kind":"integration","linkedModuleIds":["inflammatory-invasive-enteritis"],"origin":"ai"}],"chromoblastomycosis-subcutaneous-mycoses":[{"id":"chromoblastomycosis-subcutaneous-mycoses~ai-0","moduleId":"chromoblastomycosis-subcutaneous-mycoses","stem":"What is the primary causative agent of chromoblastomycosis?","options":[{"id":"a","text":"Candida albicans"},{"id":"b","text":"Aspergillus fumigatus"},{"id":"c","text":"Dematiaceous fungi"},{"id":"d","text":"Cryptococcus neoformans"}],"answerId":"c","explanation":"Chromoblastomycosis is caused by dematiaceous fungi such as Fonsecaea and Cladophialophora.","kind":"recall","origin":"ai"},{"id":"chromoblastomycosis-subcutaneous-mycoses~ai-1","moduleId":"chromoblastomycosis-subcutaneous-mycoses","stem":"Which of the following is a characteristic clinical finding in chromoblastomycosis?","options":[{"id":"a","text":"Cigar-shaped yeasts"},{"id":"b","text":"Brown, thick-walled muriform bodies"},{"id":"c","text":"Grains discharging from sinuses"},{"id":"d","text":"Pigmented hyphae in tissue"}],"answerId":"b","explanation":"The diagnostic hallmark of chromoblastomycosis is the presence of brown, thick-walled muriform (sclerotic) bodies in tissue.","kind":"recall","origin":"ai"},{"id":"chromoblastomycosis-subcutaneous-mycoses~ai-2","moduleId":"chromoblastomycosis-subcutaneous-mycoses","stem":"What is the mechanism of action of itraconazole in treating chromoblastomycosis?","options":[{"id":"a","text":"Inhibition of cell wall synthesis"},{"id":"b","text":"Inhibition of ergosterol synthesis"},{"id":"c","text":"Disruption of protein synthesis"},{"id":"d","text":"Inhibition of nucleic acid synthesis"}],"answerId":"b","explanation":"Itraconazole works by inhibiting ergosterol synthesis, which is essential for fungal cell membrane integrity.","kind":"mechanism","origin":"ai"},{"id":"chromoblastomycosis-subcutaneous-mycoses~ai-3","moduleId":"chromoblastomycosis-subcutaneous-mycoses","stem":"Which of the following statements correctly distinguishes chromoblastomycosis from mycetoma?","options":[{"id":"a","text":"Both show muriform bodies in tissue"},{"id":"b","text":"Mycetoma discharges grains, while chromoblastomycosis shows muriform bodies"},{"id":"c","text":"Chromoblastomycosis is caused by yeast, while mycetoma is caused by molds"},{"id":"d","text":"Both are treated with the same antifungal therapy"}],"answerId":"b","explanation":"Mycetoma is characterized by the discharge of grains through sinus tracts, whereas chromoblastomycosis shows muriform bodies in tissue.","kind":"trap","origin":"ai"},{"id":"chromoblastomycosis-subcutaneous-mycoses~ai-4","moduleId":"chromoblastomycosis-subcutaneous-mycoses","stem":"A patient presents with a chronic, verrucous plaque on the lower leg after working barefoot in the soil. What is the most likely diagnosis?","options":[{"id":"a","text":"Sporotrichosis"},{"id":"b","text":"Mycetoma"},{"id":"c","text":"Chromoblastomycosis"},{"id":"d","text":"Phaeohyphomycosis"}],"answerId":"c","explanation":"The clinical presentation of a chronic, verrucous plaque on the lower leg is characteristic of chromoblastomycosis.","kind":"clinical","origin":"ai"},{"id":"chromoblastomycosis-subcutaneous-mycoses~ai-5","moduleId":"chromoblastomycosis-subcutaneous-mycoses","stem":"Which treatment is most appropriate for localized chromoblastomycosis?","options":[{"id":"a","text":"Surgical excision only"},{"id":"b","text":"Oral antifungals only"},{"id":"c","text":"Prolonged antifungals ± surgery"},{"id":"d","text":"Topical antifungals only"}],"answerId":"c","explanation":"Localized chromoblastomycosis is treated with prolonged antifungals such as itraconazole or terbinafine, sometimes combined with surgery.","kind":"recall","origin":"ai"},{"id":"chromoblastomycosis-subcutaneous-mycoses~ai-6","moduleId":"chromoblastomycosis-subcutaneous-mycoses","stem":"How does chromoblastomycosis relate to sporotrichosis in terms of etiology?","options":[{"id":"a","text":"Both are caused by the same fungus"},{"id":"b","text":"Both are subcutaneous mycoses acquired through soil implantation"},{"id":"c","text":"Both present with pigmented hyphae"},{"id":"d","text":"Both are treated with the same antifungal"}],"answerId":"b","explanation":"Both chromoblastomycosis and sporotrichosis are subcutaneous mycoses acquired through traumatic implantation from soil or vegetation.","kind":"integration","linkedModuleIds":["talaromyces-sporothrix"],"origin":"ai"},{"id":"chromoblastomycosis-subcutaneous-mycoses~ai-7","moduleId":"chromoblastomycosis-subcutaneous-mycoses","stem":"What is a key distinguishing feature of mycetoma when compared to chromoblastomycosis?","options":[{"id":"a","text":"Presence of muriform bodies"},{"id":"b","text":"Discharge of grains through sinuses"},{"id":"c","text":"Verrucous plaques"},{"id":"d","text":"Pigmented hyphae in tissue"}],"answerId":"b","explanation":"Mycetoma is characterized by the discharge of grains through sinus tracts, whereas chromoblastomycosis shows muriform bodies.","kind":"integration","linkedModuleIds":["mycetoma-eumycetoma"],"origin":"ai"}],"intro-pathology-scope":[{"id":"intro-pathology-scope~ai-0","moduleId":"intro-pathology-scope","stem":"What is the primary focus of general pathology?","options":[{"id":"a","text":"Specific organ reactions to disease"},{"id":"b","text":"Universal cell/tissue reactions"},{"id":"c","text":"Clinical consequences of diseases"},{"id":"d","text":"Etiology of specific diseases"}],"answerId":"b","explanation":"General pathology studies the basic cell/tissue reactions that are common across all tissues, providing a foundation for understanding systemic pathology.","kind":"recall","origin":"ai"},{"id":"intro-pathology-scope~ai-1","moduleId":"intro-pathology-scope","stem":"Which of the following best describes etiology in pathology?","options":[{"id":"a","text":"The mechanism of disease development"},{"id":"b","text":"The structural changes in tissues"},{"id":"c","text":"The cause of a disease"},{"id":"d","text":"The clinical consequences of a disease"}],"answerId":"c","explanation":"Etiology refers to the cause of a disease, distinguishing it from pathogenesis, which describes the mechanism of disease development.","kind":"recall","origin":"ai"},{"id":"intro-pathology-scope~ai-2","moduleId":"intro-pathology-scope","stem":"In a cervical smear, what type of specimen is being examined?","options":[{"id":"a","text":"Biopsy"},{"id":"b","text":"Exfoliative cytology"},{"id":"c","text":"Frozen section"},{"id":"d","text":"Autopsy"}],"answerId":"b","explanation":"A cervical smear is an example of exfoliative cytology, where individual cells are examined for abnormalities.","kind":"recall","origin":"ai"},{"id":"intro-pathology-scope~ai-3","moduleId":"intro-pathology-scope","stem":"What is the primary purpose of a frozen section during surgery?","options":[{"id":"a","text":"To confirm a diagnosis post-mortem"},{"id":"b","text":"To provide rapid intra-operative diagnosis"},{"id":"c","text":"To analyze tissue for chronic changes"},{"id":"d","text":"To assess cellular morphology over time"}],"answerId":"b","explanation":"A frozen section is used for rapid tissue diagnosis during an operation, allowing for immediate decision-making.","kind":"recall","origin":"ai"},{"id":"intro-pathology-scope~ai-4","moduleId":"intro-pathology-scope","stem":"Which aspect of pathology describes the sequence of events leading to disease?","options":[{"id":"a","text":"Etiology"},{"id":"b","text":"Pathogenesis"},{"id":"c","text":"Morphologic changes"},{"id":"d","text":"Clinical consequences"}],"answerId":"b","explanation":"Pathogenesis refers to the mechanism and sequence of events that lead to the development of a disease.","kind":"recall","origin":"ai"},{"id":"intro-pathology-scope~ai-5","moduleId":"intro-pathology-scope","stem":"How does pathogenesis differ from etiology?","options":[{"id":"a","text":"Pathogenesis is the cause, etiology is the mechanism"},{"id":"b","text":"Pathogenesis is the mechanism, etiology is the cause"},{"id":"c","text":"Both are the same concept"},{"id":"d","text":"Pathogenesis refers to clinical outcomes"}],"answerId":"b","explanation":"Pathogenesis describes the mechanism of disease development, while etiology refers to the cause of the disease.","kind":"trap","origin":"ai"},{"id":"intro-pathology-scope~ai-6","moduleId":"intro-pathology-scope","stem":"Which of the following is a common mechanism of cell injury that may lead to disease?","options":[{"id":"a","text":"Genetic mutation"},{"id":"b","text":"Inflammation"},{"id":"c","text":"Neoplasia"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"Cell injury can result from various mechanisms, including genetic mutations, inflammation, and neoplasia, all of which can contribute to disease.","kind":"mechanism","origin":"ai"},{"id":"intro-pathology-scope~ai-7","moduleId":"intro-pathology-scope","stem":"In the context of diabetes, which aspect of pathology is primarily affected by insulin resistance in Type 2 diabetes?","options":[{"id":"a","text":"Etiology"},{"id":"b","text":"Pathogenesis"},{"id":"c","text":"Morphologic changes"},{"id":"d","text":"Clinical consequences"}],"answerId":"b","explanation":"The pathogenesis of Type 2 diabetes involves insulin resistance, leading to a sequence of metabolic changes that result in the disease.","kind":"integration","linkedModuleIds":["hen1-diabetes-types-pathogenesis"],"origin":"ai"},{"id":"intro-pathology-scope~ai-8","moduleId":"intro-pathology-scope","stem":"How does the study of urinary tract infections (UTIs) relate to general pathology?","options":[{"id":"a","text":"It focuses solely on clinical outcomes"},{"id":"b","text":"It examines the etiology and pathogenesis of infections"},{"id":"c","text":"It is unrelated to cellular mechanisms"},{"id":"d","text":"It only studies morphological changes"}],"answerId":"b","explanation":"The study of UTIs involves understanding both the etiology (causes) and pathogenesis (mechanisms) of the infections, linking it to general pathology.","kind":"integration","linkedModuleIds":["uti-pathogenesis-microbiology"],"origin":"ai"}],"diagnostic-pathology-methods":[{"id":"diagnostic-pathology-methods~ai-0","moduleId":"diagnostic-pathology-methods","stem":"What is the primary purpose of using immunohistochemistry (IHC) in pathology?","options":[{"id":"a","text":"To stain all cellular components"},{"id":"b","text":"To subclassify tumors and identify specific antigens"},{"id":"c","text":"To visualize the entire tissue architecture"},{"id":"d","text":"To perform rapid intra-operative assessments"}],"answerId":"b","explanation":"IHC is primarily used to subclassify tumors and identify specific antigens, which aids in diagnosis and treatment planning.","kind":"mechanism","origin":"ai"},{"id":"diagnostic-pathology-methods~ai-1","moduleId":"diagnostic-pathology-methods","stem":"Which stain is used to identify mycobacteria in tissue samples?","options":[{"id":"a","text":"Periodic acid-Schiff (PAS)"},{"id":"b","text":"Gomori methenamine silver (GMS)"},{"id":"c","text":"Ziehl-Neelsen stain"},{"id":"d","text":"Mucicarmine stain"}],"answerId":"c","explanation":"The Ziehl-Neelsen stain is specifically designed to identify acid-fast bacilli, such as mycobacteria, in tissue samples.","kind":"recall","origin":"ai"},{"id":"diagnostic-pathology-methods~ai-2","moduleId":"diagnostic-pathology-methods","stem":"In a Pap smear, what does the Papanicolaou stain primarily highlight?","options":[{"id":"a","text":"Nuclear detail and chromatin clarity"},{"id":"b","text":"Cytoplasmic proteins"},{"id":"c","text":"Fungal organisms"},{"id":"d","text":"Iron deposits"}],"answerId":"a","explanation":"The Papanicolaou stain is used to enhance nuclear detail and chromatin clarity in cytological samples.","kind":"recall","origin":"ai"},{"id":"diagnostic-pathology-methods~ai-3","moduleId":"diagnostic-pathology-methods","stem":"What finding would you expect in a tissue sample stained with Gomori methenamine silver (GMS)?","options":[{"id":"a","text":"Red acid-fast bacilli"},{"id":"b","text":"Black fungal hyphae"},{"id":"c","text":"Blue nuclei"},{"id":"d","text":"Pink cytoplasm"}],"answerId":"b","explanation":"Gomori methenamine silver (GMS) stain is used to visualize black fungal hyphae in tissue samples.","kind":"recall","origin":"ai"},{"id":"diagnostic-pathology-methods~ai-4","moduleId":"diagnostic-pathology-methods","stem":"What is the mechanism of action of hematoxylin in H&E staining?","options":[{"id":"a","text":"It stains acidic structures blue"},{"id":"b","text":"It stains basic structures pink"},{"id":"c","text":"It binds to lipids"},{"id":"d","text":"It highlights connective tissue"}],"answerId":"a","explanation":"Hematoxylin is a basic dye that binds to acidic structures, such as nucleic acids, staining them blue.","kind":"mechanism","origin":"ai"},{"id":"diagnostic-pathology-methods~ai-5","moduleId":"diagnostic-pathology-methods","stem":"A patient presents with a suspected hematologic malignancy. Which diagnostic method is most appropriate for immunophenotyping?","options":[{"id":"a","text":"Hematoxylin and eosin staining"},{"id":"b","text":"Immunohistochemistry"},{"id":"c","text":"Flow cytometry"},{"id":"d","text":"Molecular methods"}],"answerId":"c","explanation":"Flow cytometry is the preferred method for immunophenotyping hematologic malignancies by analyzing surface markers on cells.","kind":"clinical","origin":"ai"},{"id":"diagnostic-pathology-methods~ai-6","moduleId":"diagnostic-pathology-methods","stem":"How does the use of special stains enhance the diagnostic process in pathology?","options":[{"id":"a","text":"They replace the need for H&E staining"},{"id":"b","text":"They provide specific identification of organisms or substances"},{"id":"c","text":"They are used exclusively for tumors"},{"id":"d","text":"They are less sensitive than routine stains"}],"answerId":"b","explanation":"Special stains provide specific identification of organisms or substances that may not be clearly visible with H&E staining.","kind":"trap","origin":"ai"},{"id":"diagnostic-pathology-methods~ai-7","moduleId":"diagnostic-pathology-methods","stem":"In the evaluation of community-acquired pneumonia, which staining method would be most useful for identifying Pneumocystis jirovecii?","options":[{"id":"a","text":"Hematoxylin and eosin"},{"id":"b","text":"Gomori methenamine silver"},{"id":"c","text":"Periodic acid-Schiff"},{"id":"d","text":"Immunohistochemistry"}],"answerId":"b","explanation":"Gomori methenamine silver (GMS) stain is particularly useful for identifying Pneumocystis jirovecii in lung tissue.","kind":"integration","linkedModuleIds":["community-acquired-pneumonia"],"origin":"ai"},{"id":"diagnostic-pathology-methods~ai-8","moduleId":"diagnostic-pathology-methods","stem":"Which method would best confirm the presence of HER2 overexpression in breast cancer?","options":[{"id":"a","text":"Flow cytometry"},{"id":"b","text":"Immunohistochemistry"},{"id":"c","text":"Hematoxylin and eosin"},{"id":"d","text":"Molecular methods"}],"answerId":"b","explanation":"Immunohistochemistry is the method used to confirm HER2 overexpression in breast cancer tissues.","kind":"integration","linkedModuleIds":["immunoassays-techniques"],"origin":"ai"}],"neoplasia-differentiation-invasion":[{"id":"neoplasia-differentiation-invasion~ai-0","moduleId":"neoplasia-differentiation-invasion","stem":"Which feature is the most reliable indicator of malignancy?","options":[{"id":"a","text":"Local invasion"},{"id":"b","text":"Metastasis"},{"id":"c","text":"Anaplasia"},{"id":"d","text":"Growth rate"}],"answerId":"b","explanation":"Metastasis is the definitive sign of malignancy, indicating the tumor's ability to spread to distant sites.","kind":"recall","origin":"ai"},{"id":"neoplasia-differentiation-invasion~ai-1","moduleId":"neoplasia-differentiation-invasion","stem":"What does anaplastic tumor morphology typically exhibit?","options":[{"id":"a","text":"Well-differentiated cells"},{"id":"b","text":"Pleomorphism and hyperchromatic nuclei"},{"id":"c","text":"Encapsulation"},{"id":"d","text":"Slow growth"}],"answerId":"b","explanation":"Anaplastic tumors show pleomorphism and hyperchromatic nuclei, indicating a loss of differentiation.","kind":"recall","origin":"ai"},{"id":"neoplasia-differentiation-invasion~ai-2","moduleId":"neoplasia-differentiation-invasion","stem":"A biopsy shows a tumor with irregular margins infiltrating surrounding tissue. What does this indicate?","options":[{"id":"a","text":"Benign tumor"},{"id":"b","text":"Malignant tumor"},{"id":"c","text":"Carcinoma in situ"},{"id":"d","text":"Dysplasia"}],"answerId":"b","explanation":"Irregular margins and infiltration of surrounding tissue are characteristic of malignant tumors.","kind":"recall","origin":"ai"},{"id":"neoplasia-differentiation-invasion~ai-3","moduleId":"neoplasia-differentiation-invasion","stem":"Which of the following findings would most likely indicate a benign tumor?","options":[{"id":"a","text":"Marked pleomorphism"},{"id":"b","text":"Encapsulated mass"},{"id":"c","text":"Atypical mitoses"},{"id":"d","text":"Infiltration of surrounding tissues"}],"answerId":"b","explanation":"An encapsulated mass is a hallmark of benign tumors, indicating they are well-circumscribed and non-invasive.","kind":"recall","origin":"ai"},{"id":"neoplasia-differentiation-invasion~ai-4","moduleId":"neoplasia-differentiation-invasion","stem":"A patient presents with a well-differentiated tumor that has metastasized. What does this imply?","options":[{"id":"a","text":"The tumor is benign"},{"id":"b","text":"The tumor is malignant despite its appearance"},{"id":"c","text":"The tumor is in situ"},{"id":"d","text":"The tumor is dysplastic"}],"answerId":"b","explanation":"Even well-differentiated tumors can be malignant if they have the ability to metastasize.","kind":"trap","origin":"ai"},{"id":"neoplasia-differentiation-invasion~ai-5","moduleId":"neoplasia-differentiation-invasion","stem":"How does dysplasia differ from carcinoma in situ?","options":[{"id":"a","text":"Dysplasia is invasive"},{"id":"b","text":"Carcinoma in situ is confined by the basement membrane"},{"id":"c","text":"Dysplasia has no atypical cells"},{"id":"d","text":"Carcinoma in situ shows no cellular atypia"}],"answerId":"b","explanation":"Carcinoma in situ is characterized by full-thickness dysplasia that is still confined by the basement membrane.","kind":"integration","linkedModuleIds":["metaplasia-dysplasia"],"origin":"ai"},{"id":"neoplasia-differentiation-invasion~ai-6","moduleId":"neoplasia-differentiation-invasion","stem":"What is the relationship between local invasion and metastasis in tumor progression?","options":[{"id":"a","text":"Local invasion is a sign of benign tumors"},{"id":"b","text":"Metastasis occurs before local invasion"},{"id":"c","text":"Local invasion precedes metastasis"},{"id":"d","text":"Both are unrelated"}],"answerId":"c","explanation":"Local invasion, breaching the basement membrane, is a precursor to metastasis in tumor progression.","kind":"integration","linkedModuleIds":["cancer-spread-staging-clinical"],"origin":"ai"}],"tissue-repair-wound-healing":[{"id":"tissue-repair-wound-healing~ai-0","moduleId":"tissue-repair-wound-healing","stem":"What type of healing occurs when a clean, sutured incision results in minimal tissue loss?","options":[{"id":"a","text":"First intention"},{"id":"b","text":"Second intention"},{"id":"c","text":"Granulation tissue formation"},{"id":"d","text":"Keloid formation"}],"answerId":"a","explanation":"First intention healing occurs with clean, apposed edges, resulting in a fine scar and minimal tissue loss.","kind":"recall","origin":"ai"},{"id":"tissue-repair-wound-healing~ai-1","moduleId":"tissue-repair-wound-healing","stem":"Which cell type is primarily responsible for collagen deposition during wound healing?","options":[{"id":"a","text":"Macrophages"},{"id":"b","text":"Fibroblasts"},{"id":"c","text":"Endothelial cells"},{"id":"d","text":"Keratinocytes"}],"answerId":"b","explanation":"Fibroblasts are the main cells involved in collagen deposition during the healing process.","kind":"mechanism","origin":"ai"},{"id":"tissue-repair-wound-healing~ai-2","moduleId":"tissue-repair-wound-healing","stem":"A patient presents with a raised scar that extends beyond the original wound margins. What is the most likely diagnosis?","options":[{"id":"a","text":"Hypertrophic scar"},{"id":"b","text":"Keloid"},{"id":"c","text":"Granulation tissue"},{"id":"d","text":"Contracture"}],"answerId":"b","explanation":"A keloid is characterized by excessive collagen formation that extends beyond the original wound margins.","kind":"clinical","origin":"ai"},{"id":"tissue-repair-wound-healing~ai-3","moduleId":"tissue-repair-wound-healing","stem":"What is the primary mechanism by which glucocorticoids impair wound healing?","options":[{"id":"a","text":"Inhibition of angiogenesis"},{"id":"b","text":"Decreased fibroblast proliferation"},{"id":"c","text":"Increased collagen synthesis"},{"id":"d","text":"Enhanced inflammation"}],"answerId":"b","explanation":"Glucocorticoids decrease fibroblast proliferation, which is crucial for collagen deposition and wound healing.","kind":"mechanism","origin":"ai"},{"id":"tissue-repair-wound-healing~ai-4","moduleId":"tissue-repair-wound-healing","stem":"Which of the following factors is least likely to impair wound healing?","options":[{"id":"a","text":"Diabetes"},{"id":"b","text":"Vitamin C deficiency"},{"id":"c","text":"Infection"},{"id":"d","text":"Adequate nutrition"}],"answerId":"d","explanation":"Adequate nutrition supports wound healing, while the other factors listed can impair it.","kind":"trap","origin":"ai"},{"id":"tissue-repair-wound-healing~ai-5","moduleId":"tissue-repair-wound-healing","stem":"During which phase of wound healing does granulation tissue form?","options":[{"id":"a","text":"Hemostasis"},{"id":"b","text":"Inflammation"},{"id":"c","text":"Proliferation"},{"id":"d","text":"Remodeling"}],"answerId":"c","explanation":"Granulation tissue formation occurs during the proliferation phase of wound healing.","kind":"recall","origin":"ai"},{"id":"tissue-repair-wound-healing~ai-6","moduleId":"tissue-repair-wound-healing","stem":"How does chronic inflammation contribute to impaired wound healing?","options":[{"id":"a","text":"By promoting scar formation"},{"id":"b","text":"By enhancing angiogenesis"},{"id":"c","text":"By causing persistent tissue injury"},{"id":"d","text":"By increasing fibroblast activity"}],"answerId":"c","explanation":"Chronic inflammation leads to persistent tissue injury, which can impair the healing process.","kind":"integration","linkedModuleIds":["chronic-inflammation-granuloma"],"origin":"ai"},{"id":"tissue-repair-wound-healing~ai-7","moduleId":"tissue-repair-wound-healing","stem":"What is the role of angiogenesis in wound healing?","options":[{"id":"a","text":"To decrease inflammation"},{"id":"b","text":"To provide nutrients and oxygen"},{"id":"c","text":"To promote scar formation"},{"id":"d","text":"To inhibit fibroblast activity"}],"answerId":"b","explanation":"Angiogenesis provides essential nutrients and oxygen to the healing tissue, facilitating repair.","kind":"integration","linkedModuleIds":["acute-inflammation"],"origin":"ai"}],"neoplasia-nomenclature":[{"id":"neoplasia-nomenclature~ai-0","moduleId":"neoplasia-nomenclature","stem":"What is the defining characteristic of a neoplasm?","options":[{"id":"a","text":"It is a benign growth"},{"id":"b","text":"It is a clonal mass of tissue"},{"id":"c","text":"It is always malignant"},{"id":"d","text":"It serves a physiological purpose"}],"answerId":"b","explanation":"A neoplasm is defined as an abnormal, clonal mass of tissue that grows uncontrollably and serves no purpose.","kind":"recall","origin":"ai"},{"id":"neoplasia-nomenclature~ai-1","moduleId":"neoplasia-nomenclature","stem":"Which suffix is used to denote a benign epithelial tumor?","options":[{"id":"a","text":"-sarcoma"},{"id":"b","text":"-oma"},{"id":"c","text":"-blastoma"},{"id":"d","text":"-carcinoma"}],"answerId":"b","explanation":"Benign epithelial tumors are typically named with the suffix '-oma', such as adenoma or papilloma.","kind":"recall","origin":"ai"},{"id":"neoplasia-nomenclature~ai-2","moduleId":"neoplasia-nomenclature","stem":"What type of tumor is a liposarcoma?","options":[{"id":"a","text":"Benign mesenchymal tumor"},{"id":"b","text":"Malignant mesenchymal tumor"},{"id":"c","text":"Benign epithelial tumor"},{"id":"d","text":"Malignant epithelial tumor"}],"answerId":"b","explanation":"A liposarcoma is a malignant tumor of mesenchymal origin, specifically adipose tissue.","kind":"recall","origin":"ai"},{"id":"neoplasia-nomenclature~ai-3","moduleId":"neoplasia-nomenclature","stem":"Which of the following is a misnomer for a malignant tumor?","options":[{"id":"a","text":"Chondroma"},{"id":"b","text":"Lymphoma"},{"id":"c","text":"Fibroma"},{"id":"d","text":"Adenoma"}],"answerId":"b","explanation":"Lymphoma is a malignant tumor despite ending in '-oma', which typically suggests benignity.","kind":"trap","origin":"ai"},{"id":"neoplasia-nomenclature~ai-4","moduleId":"neoplasia-nomenclature","stem":"A patient presents with a tumor containing hair and teeth. What is the most likely diagnosis?","options":[{"id":"a","text":"Hamartoma"},{"id":"b","text":"Choristoma"},{"id":"c","text":"Teratoma"},{"id":"d","text":"Adenoma"}],"answerId":"c","explanation":"A teratoma is characterized by the presence of multiple tissue types, including hair and teeth, arising from more than one germ layer.","kind":"clinical","origin":"ai"},{"id":"neoplasia-nomenclature~ai-5","moduleId":"neoplasia-nomenclature","stem":"Which type of tumor classification is primarily concerned with the differentiation and invasion of neoplastic cells?","options":[{"id":"a","text":"Benign vs Malignant"},{"id":"b","text":"Histological grading"},{"id":"c","text":"Clinical staging"},{"id":"d","text":"Molecular classification"}],"answerId":"a","explanation":"The classification of tumors as benign or malignant is primarily based on their differentiation and invasive potential.","kind":"integration","linkedModuleIds":["neoplasia-differentiation-invasion"],"origin":"ai"},{"id":"neoplasia-nomenclature~ai-6","moduleId":"neoplasia-nomenclature","stem":"How does a choristoma differ from a hamartoma?","options":[{"id":"a","text":"Choristoma is benign; hamartoma is malignant"},{"id":"b","text":"Choristoma is disorganized; hamartoma is organized"},{"id":"c","text":"Choristoma is normal tissue in an abnormal location; hamartoma is disorganized native tissue"},{"id":"d","text":"Choristoma arises from multiple germ layers; hamartoma does not"}],"answerId":"c","explanation":"A choristoma consists of normal tissue in an abnormal location, while a hamartoma is a disorganized mass of tissue native to the site.","kind":"integration","linkedModuleIds":["tumor-classification-grading"],"origin":"ai"}],"cancer-spread-staging-clinical":[{"id":"cancer-spread-staging-clinical~ai-0","moduleId":"cancer-spread-staging-clinical","stem":"What is the primary route of spread for carcinomas?","options":[{"id":"a","text":"Haematogenous spread"},{"id":"b","text":"Lymphatic spread"},{"id":"c","text":"Transcoelomic spread"},{"id":"d","text":"Direct invasion"}],"answerId":"b","explanation":"Carcinomas typically spread via lymphatic routes, first to regional lymph nodes.","kind":"recall","origin":"ai"},{"id":"cancer-spread-staging-clinical~ai-1","moduleId":"cancer-spread-staging-clinical","stem":"Which tumor marker is primarily associated with prostate cancer?","options":[{"id":"a","text":"CA-125"},{"id":"b","text":"AFP"},{"id":"c","text":"PSA"},{"id":"d","text":"CEA"}],"answerId":"c","explanation":"PSA (Prostate-Specific Antigen) is the tumor marker used to monitor prostate cancer.","kind":"recall","origin":"ai"},{"id":"cancer-spread-staging-clinical~ai-2","moduleId":"cancer-spread-staging-clinical","stem":"In which type of cancer is hypercalcemia due to PTHrP most commonly seen?","options":[{"id":"a","text":"Breast cancer"},{"id":"b","text":"Lung cancer"},{"id":"c","text":"Renal cell carcinoma"},{"id":"d","text":"Colorectal cancer"}],"answerId":"b","explanation":"Hypercalcemia due to PTHrP is commonly associated with squamous cell lung cancer.","kind":"recall","origin":"ai"},{"id":"cancer-spread-staging-clinical~ai-3","moduleId":"cancer-spread-staging-clinical","stem":"What does the 'N' in the TNM staging system represent?","options":[{"id":"a","text":"Node involvement"},{"id":"b","text":"Neoplasm size"},{"id":"c","text":"Nuclear grade"},{"id":"d","text":"Necrosis presence"}],"answerId":"a","explanation":"In the TNM staging system, 'N' refers to regional lymph node involvement.","kind":"recall","origin":"ai"},{"id":"cancer-spread-staging-clinical~ai-4","moduleId":"cancer-spread-staging-clinical","stem":"A patient presents with unexplained weight loss and fatigue. Which systemic effect of cancer might this indicate?","options":[{"id":"a","text":"Cachexia"},{"id":"b","text":"Obstruction"},{"id":"c","text":"Ulceration"},{"id":"d","text":"Paraneoplastic syndrome"}],"answerId":"a","explanation":"Cachexia is a common systemic effect of advanced cancer characterized by weight loss and fatigue.","kind":"clinical","origin":"ai"},{"id":"cancer-spread-staging-clinical~ai-5","moduleId":"cancer-spread-staging-clinical","stem":"Which statement correctly differentiates tumor grade from stage?","options":[{"id":"a","text":"Grade measures the extent of spread, stage measures differentiation."},{"id":"b","text":"Grade is a microscopic assessment, stage is anatomical extent."},{"id":"c","text":"Both grade and stage assess the same factors."},{"id":"d","text":"Stage is less important than grade for prognosis."}],"answerId":"b","explanation":"Tumor grade assesses differentiation under the microscope, while stage describes the anatomical extent of spread.","kind":"trap","origin":"ai"},{"id":"cancer-spread-staging-clinical~ai-6","moduleId":"cancer-spread-staging-clinical","stem":"How does lymphatic spread of breast cancer relate to its staging?","options":[{"id":"a","text":"It indicates the tumor's size."},{"id":"b","text":"It determines the histological grade."},{"id":"c","text":"It reflects the extent of regional lymph node involvement."},{"id":"d","text":"It suggests a higher likelihood of haematogenous spread."}],"answerId":"c","explanation":"Lymphatic spread in breast cancer is crucial for determining the extent of regional lymph node involvement in staging.","kind":"integration","linkedModuleIds":["hrp1-breast-gross-lymphatic-anatomy"],"origin":"ai"},{"id":"cancer-spread-staging-clinical~ai-7","moduleId":"cancer-spread-staging-clinical","stem":"In colon cancer, which molecular marker is most relevant for monitoring treatment response?","options":[{"id":"a","text":"CA-125"},{"id":"b","text":"CEA"},{"id":"c","text":"PSA"},{"id":"d","text":"AFP"}],"answerId":"b","explanation":"CEA (Carcinoembryonic Antigen) is the primary tumor marker used to monitor colon cancer.","kind":"integration","linkedModuleIds":["colon-molecular-workup-therapy"],"origin":"ai"}],"environmental-chemical-tobacco-injury":[{"id":"environmental-chemical-tobacco-injury~ai-0","moduleId":"environmental-chemical-tobacco-injury","stem":"What is the primary mechanism by which carbon monoxide causes tissue hypoxia?","options":[{"id":"a","text":"Inhibition of cytochrome oxidase"},{"id":"b","text":"Displacement of oxygen from hemoglobin"},{"id":"c","text":"Formation of carboxyhemoglobin"},{"id":"d","text":"Direct cellular toxicity"}],"answerId":"c","explanation":"Carbon monoxide binds to hemoglobin to form carboxyhemoglobin, which reduces oxygen delivery to tissues.","kind":"mechanism","origin":"ai"},{"id":"environmental-chemical-tobacco-injury~ai-1","moduleId":"environmental-chemical-tobacco-injury","stem":"Which of the following findings is most consistent with chronic alcohol injury?","options":[{"id":"a","text":"Centrilobular hepatic necrosis"},{"id":"b","text":"Cherry-red skin"},{"id":"c","text":"Fatty liver progressing to cirrhosis"},{"id":"d","text":"Pleural mesothelioma"}],"answerId":"c","explanation":"Chronic alcohol consumption leads to fatty liver, which can progress to cirrhosis.","kind":"recall","origin":"ai"},{"id":"environmental-chemical-tobacco-injury~ai-2","moduleId":"environmental-chemical-tobacco-injury","stem":"A patient presents with confusion and headache after being exposed to smoke in a closed garage. What is the most likely finding on examination?","options":[{"id":"a","text":"Cyanosis of the lips"},{"id":"b","text":"Cherry-red skin"},{"id":"c","text":"Hypotension"},{"id":"d","text":"Bradycardia"}],"answerId":"b","explanation":"Carbon monoxide poisoning typically presents with cherry-red skin due to carboxyhemoglobin formation, not cyanosis.","kind":"clinical","origin":"ai"},{"id":"environmental-chemical-tobacco-injury~ai-3","moduleId":"environmental-chemical-tobacco-injury","stem":"What is the antidote for paracetamol overdose?","options":[{"id":"a","text":"Activated charcoal"},{"id":"b","text":"N-acetylcysteine"},{"id":"c","text":"Flumazenil"},{"id":"d","text":"Atropine"}],"answerId":"b","explanation":"N-acetylcysteine replenishes glutathione, which is depleted by the toxic metabolite NAPQI in paracetamol overdose.","kind":"recall","origin":"ai"},{"id":"environmental-chemical-tobacco-injury~ai-4","moduleId":"environmental-chemical-tobacco-injury","stem":"Which of the following is a classic complication of lead exposure?","options":[{"id":"a","text":"Mesothelioma"},{"id":"b","text":"Basophilic stippling of red blood cells"},{"id":"c","text":"Silicosis"},{"id":"d","text":"Cirrhosis"}],"answerId":"b","explanation":"Lead exposure is associated with neurotoxicity and basophilic stippling of red blood cells.","kind":"trap","origin":"ai"},{"id":"environmental-chemical-tobacco-injury~ai-5","moduleId":"environmental-chemical-tobacco-injury","stem":"How does tobacco smoke contribute to lung cancer development?","options":[{"id":"a","text":"Direct DNA damage by reactive metabolites"},{"id":"b","text":"Inhibition of apoptosis"},{"id":"c","text":"Increased oxidative stress"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"Tobacco smoke contains carcinogens that cause direct DNA damage, inhibit apoptosis, and increase oxidative stress, all contributing to cancer development.","kind":"integration","linkedModuleIds":["carcinogenesis-molecular"],"origin":"ai"},{"id":"environmental-chemical-tobacco-injury~ai-6","moduleId":"environmental-chemical-tobacco-injury","stem":"What is the relationship between NAPQI and glutathione in paracetamol toxicity?","options":[{"id":"a","text":"NAPQI directly causes liver fibrosis"},{"id":"b","text":"Glutathione depletion leads to NAPQI accumulation"},{"id":"c","text":"NAPQI enhances glutathione synthesis"},{"id":"d","text":"Glutathione protects against carbon monoxide toxicity"}],"answerId":"b","explanation":"In paracetamol overdose, NAPQI depletes glutathione, leading to hepatic necrosis.","kind":"integration","linkedModuleIds":["napqi-glutathione-nac"],"origin":"ai"}],"physical-nutritional-injury":[{"id":"physical-nutritional-injury~ai-0","moduleId":"physical-nutritional-injury","stem":"What is the primary mechanism of injury in thermal burns?","options":[{"id":"a","text":"Mechanical trauma"},{"id":"b","text":"Electrical current"},{"id":"c","text":"Heat energy"},{"id":"d","text":"Radiation exposure"}],"answerId":"c","explanation":"Thermal burns result from heat energy causing tissue damage.","kind":"mechanism","origin":"ai"},{"id":"physical-nutritional-injury~ai-1","moduleId":"physical-nutritional-injury","stem":"Which vitamin deficiency is characterized by bleeding gums and poor wound healing?","options":[{"id":"a","text":"Vitamin A"},{"id":"b","text":"Vitamin C"},{"id":"c","text":"Vitamin D"},{"id":"d","text":"Vitamin B12"}],"answerId":"b","explanation":"Vitamin C deficiency leads to scurvy, which presents with bleeding gums and impaired wound healing.","kind":"recall","origin":"ai"},{"id":"physical-nutritional-injury~ai-2","moduleId":"physical-nutritional-injury","stem":"A child presents with severe wasting and no edema. Which condition is most likely?","options":[{"id":"a","text":"Kwashiorkor"},{"id":"b","text":"Marasmus"},{"id":"c","text":"Anorexia nervosa"},{"id":"d","text":"Bulimia nervosa"}],"answerId":"b","explanation":"Marasmus is characterized by total calorie deficit leading to severe wasting without edema.","kind":"trap","origin":"ai"},{"id":"physical-nutritional-injury~ai-3","moduleId":"physical-nutritional-injury","stem":"What is a common long-term effect of ionizing radiation exposure?","options":[{"id":"a","text":"Acute radiation syndrome"},{"id":"b","text":"Leukemia"},{"id":"c","text":"Frostbite"},{"id":"d","text":"Kwashiorkor"}],"answerId":"b","explanation":"Ionizing radiation can cause DNA damage, leading to an increased risk of leukemia and other cancers over time.","kind":"recall","origin":"ai"},{"id":"physical-nutritional-injury~ai-4","moduleId":"physical-nutritional-injury","stem":"Which of the following is a sign of protein-energy malnutrition in children?","options":[{"id":"a","text":"Night blindness"},{"id":"b","text":"Oedema and fatty liver"},{"id":"c","text":"Dermatitis"},{"id":"d","text":"Megaloblastic anemia"}],"answerId":"b","explanation":"Oedema and fatty liver are indicative of kwashiorkor, a form of protein-energy malnutrition.","kind":"recall","origin":"ai"},{"id":"physical-nutritional-injury~ai-5","moduleId":"physical-nutritional-injury","stem":"How does obesity contribute to the development of type 2 diabetes?","options":[{"id":"a","text":"Increased insulin sensitivity"},{"id":"b","text":"Decreased inflammation"},{"id":"c","text":"Insulin resistance"},{"id":"d","text":"Enhanced glucose uptake"}],"answerId":"c","explanation":"Obesity leads to insulin resistance, which is a key factor in the development of type 2 diabetes.","kind":"mechanism","origin":"ai"},{"id":"physical-nutritional-injury~ai-6","moduleId":"physical-nutritional-injury","stem":"How does ionizing radiation relate to carcinogenesis?","options":[{"id":"a","text":"It causes direct DNA damage"},{"id":"b","text":"It increases vitamin D synthesis"},{"id":"c","text":"It promotes protein synthesis"},{"id":"d","text":"It reduces oxidative stress"}],"answerId":"a","explanation":"Ionizing radiation directly damages DNA, which can lead to mutations and carcinogenesis.","kind":"integration","linkedModuleIds":["carcinogenesis-molecular"],"origin":"ai"},{"id":"physical-nutritional-injury~ai-7","moduleId":"physical-nutritional-injury","stem":"What is the primary nutritional concern in a patient with kwashiorkor?","options":[{"id":"a","text":"Total calorie deficit"},{"id":"b","text":"Protein deficiency"},{"id":"c","text":"Vitamin A deficiency"},{"id":"d","text":"Iron deficiency"}],"answerId":"b","explanation":"Kwashiorkor is primarily due to protein deficiency, often with adequate calorie intake.","kind":"integration","linkedModuleIds":["nutritional-assessment-support"],"origin":"ai"}],"edema-hyperemia-congestion":[{"id":"edema-hyperemia-congestion~ai-0","moduleId":"edema-hyperemia-congestion","stem":"What is the primary mechanism behind edema in nephrotic syndrome?","options":[{"id":"a","text":"Increased hydrostatic pressure"},{"id":"b","text":"Decreased oncotic pressure"},{"id":"c","text":"Lymphatic obstruction"},{"id":"d","text":"Sodium retention"}],"answerId":"b","explanation":"Nephrotic syndrome causes protein loss in urine, leading to decreased plasma oncotic pressure and resulting in edema.","kind":"recall","origin":"ai"},{"id":"edema-hyperemia-congestion~ai-1","moduleId":"edema-hyperemia-congestion","stem":"Which of the following findings is characteristic of chronic pulmonary congestion?","options":[{"id":"a","text":"Pitting edema"},{"id":"b","text":"Haemosiderin-laden macrophages"},{"id":"c","text":"Nutmeg liver"},{"id":"d","text":"Generalized edema"}],"answerId":"b","explanation":"Chronic pulmonary congestion leads to the accumulation of haemosiderin-laden macrophages, also known as heart-failure cells, in the alveoli.","kind":"recall","origin":"ai"},{"id":"edema-hyperemia-congestion~ai-2","moduleId":"edema-hyperemia-congestion","stem":"What distinguishes hyperemia from congestion?","options":[{"id":"a","text":"Both are active processes"},{"id":"b","text":"Hyperemia is passive, congestion is active"},{"id":"c","text":"Hyperemia is associated with oxygenated blood, congestion with deoxygenated blood"},{"id":"d","text":"Congestion is a sign of inflammation"}],"answerId":"c","explanation":"Hyperemia is an active process with increased inflow of oxygenated blood, while congestion is passive with impaired outflow of deoxygenated blood.","kind":"trap","origin":"ai"},{"id":"edema-hyperemia-congestion~ai-3","moduleId":"edema-hyperemia-congestion","stem":"Which condition is most likely to cause generalized edema due to decreased oncotic pressure?","options":[{"id":"a","text":"Heart failure"},{"id":"b","text":"Cirrhosis"},{"id":"c","text":"Venous obstruction"},{"id":"d","text":"Lymphatic obstruction"}],"answerId":"b","explanation":"Cirrhosis leads to decreased albumin production, resulting in decreased oncotic pressure and generalized edema.","kind":"recall","origin":"ai"},{"id":"edema-hyperemia-congestion~ai-4","moduleId":"edema-hyperemia-congestion","stem":"What is the primary cause of lymphoedema following lymph-node dissection?","options":[{"id":"a","text":"Increased hydrostatic pressure"},{"id":"b","text":"Decreased oncotic pressure"},{"id":"c","text":"Lymphatic obstruction"},{"id":"d","text":"Sodium retention"}],"answerId":"c","explanation":"Lymph-node dissection can obstruct lymphatic drainage, leading to lymphoedema.","kind":"recall","origin":"ai"},{"id":"edema-hyperemia-congestion~ai-5","moduleId":"edema-hyperemia-congestion","stem":"In a patient with heart failure, which finding indicates chronic passive hepatic congestion?","options":[{"id":"a","text":"Pitting edema"},{"id":"b","text":"Nutmeg liver"},{"id":"c","text":"Haemosiderin-laden macrophages"},{"id":"d","text":"Generalized edema"}],"answerId":"b","explanation":"Nutmeg liver is a classic finding in chronic passive hepatic congestion due to right heart failure.","kind":"recall","origin":"ai"},{"id":"edema-hyperemia-congestion~ai-6","moduleId":"edema-hyperemia-congestion","stem":"How does nephrotic syndrome relate to edema in the context of renal function?","options":[{"id":"a","text":"Increased filtration of proteins"},{"id":"b","text":"Decreased glomerular filtration rate"},{"id":"c","text":"Increased sodium retention"},{"id":"d","text":"Decreased oncotic pressure due to protein loss"}],"answerId":"d","explanation":"Nephrotic syndrome causes protein loss in urine, leading to decreased oncotic pressure and resulting in edema.","kind":"integration","linkedModuleIds":["glomerular-filtration-gfr"],"origin":"ai"},{"id":"edema-hyperemia-congestion~ai-7","moduleId":"edema-hyperemia-congestion","stem":"What is the relationship between heart failure and the development of edema?","options":[{"id":"a","text":"Increased sodium retention leads to decreased hydrostatic pressure"},{"id":"b","text":"Decreased venous outflow increases hydrostatic pressure"},{"id":"c","text":"Increased oncotic pressure causes fluid retention"},{"id":"d","text":"Decreased lymphatic drainage leads to hyperemia"}],"answerId":"b","explanation":"Heart failure impairs venous outflow, leading to increased hydrostatic pressure and subsequent edema.","kind":"integration","linkedModuleIds":["hf-organ-pathology"],"origin":"ai"}],"chronic-inflammation-granuloma":[{"id":"chronic-inflammation-granuloma~ai-0","moduleId":"chronic-inflammation-granuloma","stem":"What type of cells predominantly infiltrate tissues during chronic inflammation?","options":[{"id":"a","text":"Neutrophils"},{"id":"b","text":"Eosinophils"},{"id":"c","text":"Mononuclear cells"},{"id":"d","text":"Basophils"}],"answerId":"c","explanation":"Chronic inflammation is characterized by a predominance of mononuclear cells, including macrophages, lymphocytes, and plasma cells.","kind":"recall","origin":"ai"},{"id":"chronic-inflammation-granuloma~ai-1","moduleId":"chronic-inflammation-granuloma","stem":"Which cytokine is primarily responsible for inducing fever during the acute-phase response?","options":[{"id":"a","text":"IL-1"},{"id":"b","text":"IL-6"},{"id":"c","text":"TNF-alpha"},{"id":"d","text":"Prostaglandin E2"}],"answerId":"a","explanation":"IL-1 is a key pyrogen that raises the hypothalamic set-point, leading to fever during the acute-phase response.","kind":"mechanism","origin":"ai"},{"id":"chronic-inflammation-granuloma~ai-2","moduleId":"chronic-inflammation-granuloma","stem":"A patient presents with a lung biopsy showing epithelioid macrophages and multinucleate giant cells. What is the most likely diagnosis?","options":[{"id":"a","text":"Non-caseating granuloma"},{"id":"b","text":"Caseating granuloma"},{"id":"c","text":"Acute pneumonia"},{"id":"d","text":"Lung cancer"}],"answerId":"b","explanation":"The presence of epithelioid macrophages and multinucleate giant cells with central caseous necrosis is characteristic of a caseating granuloma, commonly seen in tuberculosis.","kind":"recall","origin":"ai"},{"id":"chronic-inflammation-granuloma~ai-3","moduleId":"chronic-inflammation-granuloma","stem":"In chronic inflammation, what is the role of M2 macrophages?","options":[{"id":"a","text":"Microbicidal activity"},{"id":"b","text":"Tissue repair and fibrosis"},{"id":"c","text":"Neutrophil recruitment"},{"id":"d","text":"Cytokine production for acute inflammation"}],"answerId":"b","explanation":"M2 macrophages are involved in tissue repair and fibrosis, contrasting with M1 macrophages that are primarily microbicidal.","kind":"mechanism","origin":"ai"},{"id":"chronic-inflammation-granuloma~ai-4","moduleId":"chronic-inflammation-granuloma","stem":"A patient with a chronic cough and weight loss undergoes a lung biopsy. The biopsy reveals non-caseating granulomas. What is the most likely underlying condition?","options":[{"id":"a","text":"Tuberculosis"},{"id":"b","text":"Sarcoidosis"},{"id":"c","text":"Chronic bronchitis"},{"id":"d","text":"Lung cancer"}],"answerId":"b","explanation":"Non-caseating granulomas in the lung are most commonly associated with sarcoidosis.","kind":"recall","origin":"ai"},{"id":"chronic-inflammation-granuloma~ai-5","moduleId":"chronic-inflammation-granuloma","stem":"Which of the following is a crucial discriminator between caseating and non-caseating granulomas?","options":[{"id":"a","text":"Presence of lymphocytes"},{"id":"b","text":"Presence of central necrosis"},{"id":"c","text":"Size of the granuloma"},{"id":"d","text":"Location of the granuloma"}],"answerId":"b","explanation":"The presence of central caseous necrosis is critical in distinguishing caseating granulomas (e.g., tuberculosis) from non-caseating granulomas (e.g., sarcoidosis).","kind":"trap","origin":"ai"},{"id":"chronic-inflammation-granuloma~ai-6","moduleId":"chronic-inflammation-granuloma","stem":"How does chronic inflammation relate to tissue repair mechanisms?","options":[{"id":"a","text":"It inhibits tissue repair"},{"id":"b","text":"It promotes only necrosis"},{"id":"c","text":"It occurs simultaneously with repair processes"},{"id":"d","text":"It is unrelated to repair mechanisms"}],"answerId":"c","explanation":"Chronic inflammation involves simultaneous tissue injury and repair processes, including fibrosis.","kind":"integration","linkedModuleIds":["tissue-repair-wound-healing"],"origin":"ai"},{"id":"chronic-inflammation-granuloma~ai-7","moduleId":"chronic-inflammation-granuloma","stem":"Which systemic effect of chronic inflammation is characterized by elevated acute-phase proteins?","options":[{"id":"a","text":"Leukocytosis"},{"id":"b","text":"Fever"},{"id":"c","text":"Anemia of chronic disease"},{"id":"d","text":"Increased ESR"}],"answerId":"d","explanation":"In chronic inflammation, elevated acute-phase proteins lead to a high erythrocyte sedimentation rate (ESR), indicating systemic inflammation.","kind":"integration","linkedModuleIds":["inflammatory-mediators-leukocytes"],"origin":"ai"}],"infarction-shock":[{"id":"infarction-shock~ai-0","moduleId":"infarction-shock","stem":"What type of infarct is characterized by a pale, wedge-shaped appearance in the kidney?","options":[{"id":"a","text":"Red infarct"},{"id":"b","text":"White infarct"},{"id":"c","text":"Hemorrhagic infarct"},{"id":"d","text":"Ischemic infarct"}],"answerId":"b","explanation":"A pale, wedge-shaped infarct in the kidney indicates a white (anaemic) infarct due to end-arterial supply.","kind":"recall","origin":"ai"},{"id":"infarction-shock~ai-1","moduleId":"infarction-shock","stem":"Which type of shock is characterized by warm skin and high cardiac output?","options":[{"id":"a","text":"Hypovolemic shock"},{"id":"b","text":"Cardiogenic shock"},{"id":"c","text":"Septic shock"},{"id":"d","text":"Neurogenic shock"}],"answerId":"c","explanation":"Septic shock is often warm and presents with high cardiac output due to systemic vasodilation.","kind":"recall","origin":"ai"},{"id":"infarction-shock~ai-2","moduleId":"infarction-shock","stem":"In DIC, what is the primary mechanism leading to bleeding?","options":[{"id":"a","text":"Platelet overproduction"},{"id":"b","text":"Widespread coagulation activation"},{"id":"c","text":"Vascular obstruction"},{"id":"d","text":"Decreased fibrinogen synthesis"}],"answerId":"b","explanation":"DIC begins with widespread coagulation activation, forming microthrombi that consume platelets and clotting factors, leading to bleeding.","kind":"mechanism","origin":"ai"},{"id":"infarction-shock~ai-3","moduleId":"infarction-shock","stem":"A patient presents with hypotension, tachycardia, and cold clammy skin after significant blood loss. What type of shock is this?","options":[{"id":"a","text":"Cardiogenic shock"},{"id":"b","text":"Hypovolemic shock"},{"id":"c","text":"Septic shock"},{"id":"d","text":"Anaphylactic shock"}],"answerId":"b","explanation":"These signs are indicative of hypovolemic shock due to inadequate blood volume.","kind":"clinical","origin":"ai"},{"id":"infarction-shock~ai-4","moduleId":"infarction-shock","stem":"Which statement about DIC is true?","options":[{"id":"a","text":"It is purely a bleeding disorder."},{"id":"b","text":"It is always primary and not secondary."},{"id":"c","text":"It involves both thrombosis and bleeding."},{"id":"d","text":"It is caused solely by trauma."}],"answerId":"c","explanation":"DIC is paradoxical; it involves both thrombosis (microthrombi formation) and bleeding due to consumption of clotting factors.","kind":"trap","origin":"ai"},{"id":"infarction-shock~ai-5","moduleId":"infarction-shock","stem":"How does a red infarct typically occur?","options":[{"id":"a","text":"Due to end-arterial supply"},{"id":"b","text":"From venous occlusion or reperfusion"},{"id":"c","text":"In solid organs only"},{"id":"d","text":"With slow occlusion only"}],"answerId":"b","explanation":"Red infarcts occur in tissues with dual circulation or after venous occlusion or reperfusion.","kind":"mechanism","origin":"ai"},{"id":"infarction-shock~ai-6","moduleId":"infarction-shock","stem":"A patient with myocardial infarction develops complications leading to systemic hypoperfusion. Which module is most relevant for understanding this condition?","options":[{"id":"a","text":"Necrosis & Its Morphologic Patterns"},{"id":"b","text":"Complications of Myocardial Infarction"},{"id":"c","text":"Hemostasis, Thrombosis & Embolism"},{"id":"d","text":"Edema, Hyperemia & Congestion"}],"answerId":"b","explanation":"The module on Complications of Myocardial Infarction provides insights into systemic hypoperfusion following an MI.","kind":"integration","linkedModuleIds":["mi-complications"],"origin":"ai"},{"id":"infarction-shock~ai-7","moduleId":"infarction-shock","stem":"Which mechanism links DIC to myocardial infarction complications?","options":[{"id":"a","text":"Infarction leads to increased blood volume"},{"id":"b","text":"Microthrombi formation causing ischemia"},{"id":"c","text":"Direct cardiac muscle necrosis"},{"id":"d","text":"Increased oxygen delivery to tissues"}],"answerId":"b","explanation":"DIC can lead to microthrombi formation, which exacerbates ischemic damage in myocardial infarction.","kind":"integration","linkedModuleIds":["mi-complications"],"origin":"ai"}],"carcinogenesis-molecular":[{"id":"carcinogenesis-molecular~ai-0","moduleId":"carcinogenesis-molecular","stem":"What is the mechanism by which RAS mutations contribute to cancer development?","options":[{"id":"a","text":"Loss of function"},{"id":"b","text":"Gain of function"},{"id":"c","text":"Inhibition of apoptosis"},{"id":"d","text":"Increased DNA repair"}],"answerId":"b","explanation":"RAS mutations lead to a gain of function, resulting in constitutive signaling that promotes cell growth and proliferation.","kind":"mechanism","origin":"ai"},{"id":"carcinogenesis-molecular~ai-1","moduleId":"carcinogenesis-molecular","stem":"Which of the following is a characteristic of tumor suppressor genes?","options":[{"id":"a","text":"Require one mutation for activation"},{"id":"b","text":"Inhibit cell cycle progression"},{"id":"c","text":"Are dominant at the cell level"},{"id":"d","text":"Promote apoptosis"}],"answerId":"b","explanation":"Tumor suppressor genes inhibit cell cycle progression and require loss of both alleles to contribute to cancer.","kind":"recall","origin":"ai"},{"id":"carcinogenesis-molecular~ai-2","moduleId":"carcinogenesis-molecular","stem":"In retinoblastoma, what is the genetic basis of the disease?","options":[{"id":"a","text":"Activation of an oncogene"},{"id":"b","text":"Loss of both RB alleles"},{"id":"c","text":"Point mutation in p53"},{"id":"d","text":"Amplification of MYC"}],"answerId":"b","explanation":"Retinoblastoma is caused by the loss of both alleles of the RB tumor suppressor gene, following Knudson's two-hit hypothesis.","kind":"recall","origin":"ai"},{"id":"carcinogenesis-molecular~ai-3","moduleId":"carcinogenesis-molecular","stem":"Which of the following is a hallmark of cancer related to angiogenesis?","options":[{"id":"a","text":"Evasion of apoptosis"},{"id":"b","text":"Sustained angiogenesis"},{"id":"c","text":"Limitless replicative potential"},{"id":"d","text":"Self-sufficiency in growth signals"}],"answerId":"b","explanation":"Sustained angiogenesis is a hallmark of cancer that allows tumors to develop their own blood supply.","kind":"recall","origin":"ai"},{"id":"carcinogenesis-molecular~ai-4","moduleId":"carcinogenesis-molecular","stem":"Which of the following carcinogens is associated with hepatocellular carcinoma?","options":[{"id":"a","text":"UV radiation"},{"id":"b","text":"Aflatoxin"},{"id":"c","text":"Benzene"},{"id":"d","text":"Asbestos"}],"answerId":"b","explanation":"Aflatoxin is a chemical carcinogen known to cause hepatocellular carcinoma, especially in the context of liver disease.","kind":"recall","origin":"ai"},{"id":"carcinogenesis-molecular~ai-5","moduleId":"carcinogenesis-molecular","stem":"How does HPV contribute to cervical cancer?","options":[{"id":"a","text":"Inactivates p53 and RB"},{"id":"b","text":"Activates MYC"},{"id":"c","text":"Induces apoptosis"},{"id":"d","text":"Promotes DNA repair"}],"answerId":"a","explanation":"HPV E6 and E7 proteins inactivate p53 and RB, leading to unregulated cell cycle progression and cancer development.","kind":"mechanism","origin":"ai"},{"id":"carcinogenesis-molecular~ai-6","moduleId":"carcinogenesis-molecular","stem":"Which of the following best explains the difference between oncogenes and tumor suppressor genes?","options":[{"id":"a","text":"Both require loss of function"},{"id":"b","text":"Oncogenes require one mutation, tumor suppressors require two"},{"id":"c","text":"Both are activated by mutations"},{"id":"d","text":"Tumor suppressors are dominant at the cell level"}],"answerId":"b","explanation":"Oncogenes are activated by a single mutation (gain of function), while tumor suppressor genes require loss of both alleles (two-hit hypothesis).","kind":"trap","origin":"ai"},{"id":"carcinogenesis-molecular~ai-7","moduleId":"carcinogenesis-molecular","stem":"How does the mechanism of apoptosis relate to tumor suppression?","options":[{"id":"a","text":"Apoptosis promotes tumor growth"},{"id":"b","text":"Tumor suppressors enhance apoptosis"},{"id":"c","text":"Apoptosis is unrelated to cancer"},{"id":"d","text":"Tumor suppressors inhibit apoptosis"}],"answerId":"b","explanation":"Tumor suppressor genes like p53 promote apoptosis in response to DNA damage, preventing the survival of potentially cancerous cells.","kind":"integration","linkedModuleIds":["apoptosis-cell-death"],"origin":"ai"},{"id":"carcinogenesis-molecular~ai-8","moduleId":"carcinogenesis-molecular","stem":"Which environmental factor is linked to the activation of oncogenes in lung cancer?","options":[{"id":"a","text":"UV radiation"},{"id":"b","text":"Tobacco smoke"},{"id":"c","text":"Aflatoxin"},{"id":"d","text":"HPV infection"}],"answerId":"b","explanation":"Tobacco smoke contains carcinogens that can activate oncogenes, contributing to lung cancer development.","kind":"integration","linkedModuleIds":["environmental-chemical-tobacco-injury"],"origin":"ai"}],"hemostasis-thrombosis-embolism":[{"id":"hemostasis-thrombosis-embolism~ai-0","moduleId":"hemostasis-thrombosis-embolism","stem":"What is the primary mechanism by which von Willebrand factor facilitates hemostasis?","options":[{"id":"a","text":"It activates platelets directly."},{"id":"b","text":"It stabilizes fibrin clots."},{"id":"c","text":"It promotes platelet adhesion to collagen."},{"id":"d","text":"It induces vasoconstriction."}],"answerId":"c","explanation":"Von Willebrand factor is crucial for platelet adhesion to exposed collagen at the site of vascular injury.","kind":"mechanism","origin":"ai"},{"id":"hemostasis-thrombosis-embolism~ai-1","moduleId":"hemostasis-thrombosis-embolism","stem":"Which of the following conditions is most likely to lead to venous thromboembolism?","options":[{"id":"a","text":"Atrial fibrillation"},{"id":"b","text":"Long-haul flight"},{"id":"c","text":"Myocardial infarction"},{"id":"d","text":"Hypertension"}],"answerId":"b","explanation":"Prolonged immobility during long-haul flights can lead to venous stasis, increasing the risk of venous thromboembolism.","kind":"trap","origin":"ai"},{"id":"hemostasis-thrombosis-embolism~ai-2","moduleId":"hemostasis-thrombosis-embolism","stem":"A patient presents with sudden dyspnea and chest pain after being immobile for several days. What is the most likely diagnosis?","options":[{"id":"a","text":"Pneumonia"},{"id":"b","text":"Pulmonary embolism"},{"id":"c","text":"Myocardial infarction"},{"id":"d","text":"Pneumothorax"}],"answerId":"b","explanation":"Sudden dyspnea and chest pain in an immobile patient are classic signs of pulmonary embolism, often due to deep vein thrombosis.","kind":"clinical","origin":"ai"},{"id":"hemostasis-thrombosis-embolism~ai-3","moduleId":"hemostasis-thrombosis-embolism","stem":"Which of the following findings is characteristic of a true thrombus?","options":[{"id":"a","text":"Gelatinous consistency"},{"id":"b","text":"Lines of Zahn"},{"id":"c","text":"Separation into layers"},{"id":"d","text":"Lack of attachment to vessel wall"}],"answerId":"b","explanation":"Lines of Zahn indicate a thrombus formed in flowing blood, distinguishing it from a post-mortem clot.","kind":"recall","origin":"ai"},{"id":"hemostasis-thrombosis-embolism~ai-4","moduleId":"hemostasis-thrombosis-embolism","stem":"What is the fate of a thrombus that undergoes organization and recanalization?","options":[{"id":"a","text":"It dissolves completely."},{"id":"b","text":"It propagates further."},{"id":"c","text":"It forms new vascular channels."},{"id":"d","text":"It becomes an embolus."}],"answerId":"c","explanation":"Organization and recanalization involve the ingrowth of new vessels, restoring some blood flow through the thrombus.","kind":"mechanism","origin":"ai"},{"id":"hemostasis-thrombosis-embolism~ai-5","moduleId":"hemostasis-thrombosis-embolism","stem":"A patient with recurrent thrombosis is found to have factor V Leiden mutation. Which aspect of Virchow's triad does this represent?","options":[{"id":"a","text":"Endothelial injury"},{"id":"b","text":"Abnormal blood flow"},{"id":"c","text":"Hypercoagulability"},{"id":"d","text":"Stasis"}],"answerId":"c","explanation":"Factor V Leiden mutation leads to a hypercoagulable state, increasing the risk of thrombosis.","kind":"recall","origin":"ai"},{"id":"hemostasis-thrombosis-embolism~ai-6","moduleId":"hemostasis-thrombosis-embolism","stem":"How does the mechanism of pulmonary embolism relate to the concept of thrombus formation?","options":[{"id":"a","text":"It involves fat emboli from long-bone fractures."},{"id":"b","text":"It results from thrombus propagation from deep veins."},{"id":"c","text":"It is caused by air embolism during decompression."},{"id":"d","text":"It is a direct result of arterial thrombus formation."}],"answerId":"b","explanation":"Pulmonary embolism typically arises from thrombi that detach from deep veins, illustrating the connection between venous thrombus formation and embolism.","kind":"integration","linkedModuleIds":["pulmonary-embolism-edema"],"origin":"ai"},{"id":"hemostasis-thrombosis-embolism~ai-7","moduleId":"hemostasis-thrombosis-embolism","stem":"Which mechanism connects hemostasis and the development of thromboemboli in patients with atrial fibrillation?","options":[{"id":"a","text":"Vasoconstriction leading to stasis"},{"id":"b","text":"Platelet activation leading to embolization"},{"id":"c","text":"Endothelial injury leading to hypercoagulability"},{"id":"d","text":"Abnormal blood flow leading to thrombus formation"}],"answerId":"d","explanation":"Atrial fibrillation causes turbulent blood flow, increasing the risk of thrombus formation that can lead to embolization.","kind":"integration","linkedModuleIds":["anticoagulants"],"origin":"ai"}],"inflammatory-mediators-leukocytes":[{"id":"inflammatory-mediators-leukocytes~ai-0","moduleId":"inflammatory-mediators-leukocytes","stem":"What is the first step in leukocyte recruitment during acute inflammation?","options":[{"id":"a","text":"Margination"},{"id":"b","text":"Rolling"},{"id":"c","text":"Adhesion"},{"id":"d","text":"Transmigration"}],"answerId":"a","explanation":"Margination is the initial step where leukocytes are pushed to the vessel wall due to stasis.","kind":"recall","origin":"ai"},{"id":"inflammatory-mediators-leukocytes~ai-1","moduleId":"inflammatory-mediators-leukocytes","stem":"Which mediator primarily induces rolling of leukocytes along the endothelium?","options":[{"id":"a","text":"Integrins"},{"id":"b","text":"Selectins"},{"id":"c","text":"Cytokines"},{"id":"d","text":"Chemokines"}],"answerId":"b","explanation":"Selectins (E/P-selectin) mediate the weak, transient rolling of leukocytes.","kind":"mechanism","origin":"ai"},{"id":"inflammatory-mediators-leukocytes~ai-2","moduleId":"inflammatory-mediators-leukocytes","stem":"A patient presents with recurrent infections due to a defect in respiratory burst. What condition is likely?","options":[{"id":"a","text":"Leukocyte adhesion deficiency"},{"id":"b","text":"Chronic granulomatous disease"},{"id":"c","text":"Cystic fibrosis"},{"id":"d","text":"Severe combined immunodeficiency"}],"answerId":"b","explanation":"Chronic granulomatous disease is characterized by a defect in NADPH oxidase, impairing the respiratory burst.","kind":"recall","origin":"ai"},{"id":"inflammatory-mediators-leukocytes~ai-3","moduleId":"inflammatory-mediators-leukocytes","stem":"Which of the following statements about selectins and integrins is true?","options":[{"id":"a","text":"Both mediate leukocyte rolling"},{"id":"b","text":"Selectins mediate firm adhesion"},{"id":"c","text":"Integrins are involved in rolling"},{"id":"d","text":"Selectins mediate rolling, integrins mediate adhesion"}],"answerId":"d","explanation":"Selectins mediate rolling, while integrins are responsible for firm adhesion during leukocyte recruitment.","kind":"trap","origin":"ai"},{"id":"inflammatory-mediators-leukocytes~ai-4","moduleId":"inflammatory-mediators-leukocytes","stem":"What is the role of C5a in leukocyte recruitment?","options":[{"id":"a","text":"Induces vasodilation"},{"id":"b","text":"Acts as an opsonin"},{"id":"c","text":"Promotes chemotaxis"},{"id":"d","text":"Inhibits leukocyte rolling"}],"answerId":"c","explanation":"C5a is a potent chemotactic factor that directs leukocytes to the site of inflammation.","kind":"mechanism","origin":"ai"},{"id":"inflammatory-mediators-leukocytes~ai-5","moduleId":"inflammatory-mediators-leukocytes","stem":"How do NSAIDs reduce fever and pain during inflammation?","options":[{"id":"a","text":"By inhibiting leukocyte rolling"},{"id":"b","text":"By blocking prostaglandin synthesis"},{"id":"c","text":"By enhancing complement activation"},{"id":"d","text":"By promoting leukocyte adhesion"}],"answerId":"b","explanation":"NSAIDs inhibit cyclooxygenase (COX), reducing the synthesis of prostaglandins responsible for fever and pain.","kind":"clinical","origin":"ai"},{"id":"inflammatory-mediators-leukocytes~ai-6","moduleId":"inflammatory-mediators-leukocytes","stem":"How does leukocyte recruitment relate to tissue repair mechanisms?","options":[{"id":"a","text":"It is unrelated to tissue repair"},{"id":"b","text":"It enhances collagen synthesis"},{"id":"c","text":"It involves similar mediators as wound healing"},{"id":"d","text":"It inhibits inflammation during repair"}],"answerId":"c","explanation":"Leukocyte recruitment involves mediators that also play roles in tissue repair, highlighting the connection between inflammation and healing.","kind":"integration","linkedModuleIds":["tissue-repair-wound-healing"],"origin":"ai"},{"id":"inflammatory-mediators-leukocytes~ai-7","moduleId":"inflammatory-mediators-leukocytes","stem":"What is the relationship between leukocyte recruitment and chronic inflammation?","options":[{"id":"a","text":"Chronic inflammation has no leukocyte involvement"},{"id":"b","text":"Leukocyte recruitment is only acute"},{"id":"c","text":"Chronic inflammation involves persistent leukocyte recruitment"},{"id":"d","text":"Leukocyte recruitment is always harmful in chronic inflammation"}],"answerId":"c","explanation":"Chronic inflammation is characterized by ongoing leukocyte recruitment, leading to tissue damage and repair processes.","kind":"integration","linkedModuleIds":["chronic-inflammation-granuloma"],"origin":"ai"}],"ers-measures-frequency-association":[{"id":"ers-measures-frequency-association~ai-0","moduleId":"ers-measures-frequency-association","stem":"Which measure is used to describe the proportion of a population affected by a disease at a specific point in time?","options":[{"id":"a","text":"Prevalence"},{"id":"b","text":"Incidence"},{"id":"c","text":"Risk Ratio"},{"id":"d","text":"Odds Ratio"}],"answerId":"a","explanation":"Prevalence is the proportion of a population with a disease at a specific point in time.","kind":"recall","origin":"ai"},{"id":"ers-measures-frequency-association~ai-1","moduleId":"ers-measures-frequency-association","stem":"In a cohort study, the risk of developing a disease in the exposed group is 10%, while in the unexposed group it is 5%. What is the risk ratio?","options":[{"id":"a","text":"0.5"},{"id":"b","text":"1.0"},{"id":"c","text":"2.0"},{"id":"d","text":"5.0"}],"answerId":"c","explanation":"Risk Ratio (RR) is calculated as risk in exposed / risk in unexposed, which is 10%/5% = 2.0.","kind":"mechanism","origin":"ai"},{"id":"ers-measures-frequency-association~ai-2","moduleId":"ers-measures-frequency-association","stem":"A study finds that the odds ratio for a certain risk factor is 3.0 with a 95% confidence interval of 0.8 to 5.2. What can be concluded about the statistical significance?","options":[{"id":"a","text":"Statistically significant"},{"id":"b","text":"Not statistically significant"},{"id":"c","text":"Clinically significant"},{"id":"d","text":"Not clinically significant"}],"answerId":"b","explanation":"The 95% CI crosses 1, indicating the result is not statistically significant.","kind":"trap","origin":"ai"},{"id":"ers-measures-frequency-association~ai-3","moduleId":"ers-measures-frequency-association","stem":"Which of the following best explains why a high relative risk might not imply a large clinical impact?","options":[{"id":"a","text":"High baseline risk"},{"id":"b","text":"Low baseline risk"},{"id":"c","text":"Wide confidence interval"},{"id":"d","text":"Narrow confidence interval"}],"answerId":"b","explanation":"A high relative risk on a low baseline risk results in a small absolute risk difference.","kind":"trap","origin":"ai"},{"id":"ers-measures-frequency-association~ai-4","moduleId":"ers-measures-frequency-association","stem":"A chronic disease has a stable incidence but improved treatment prolongs survival. What happens to the prevalence?","options":[{"id":"a","text":"Increases"},{"id":"b","text":"Decreases"},{"id":"c","text":"Remains the same"},{"id":"d","text":"Fluctuates"}],"answerId":"a","explanation":"Improved survival increases duration, thus increasing prevalence.","kind":"mechanism","origin":"ai"},{"id":"ers-measures-frequency-association~ai-5","moduleId":"ers-measures-frequency-association","stem":"How does standardisation of rates help in comparing disease frequency across populations?","options":[{"id":"a","text":"Adjusts for age differences"},{"id":"b","text":"Increases sample size"},{"id":"c","text":"Reduces bias"},{"id":"d","text":"Improves precision"}],"answerId":"a","explanation":"Standardisation adjusts for confounding factors like age, allowing fair comparisons.","kind":"integration","linkedModuleIds":["ers-standardisation-rates"],"origin":"ai"},{"id":"ers-measures-frequency-association~ai-6","moduleId":"ers-measures-frequency-association","stem":"A study reports a crude incidence rate of a disease as 5 per 1000 person-years. After age standardisation, the rate is 3 per 1000 person-years. What does this indicate?","options":[{"id":"a","text":"Age confounding was present"},{"id":"b","text":"Age confounding was absent"},{"id":"c","text":"Incidence was overestimated"},{"id":"d","text":"Incidence was underestimated"}],"answerId":"a","explanation":"The difference between crude and standardised rates suggests age confounding.","kind":"integration","linkedModuleIds":["ers-standardisation-rates"],"origin":"ai"}],"ers-research-question-protocol":[{"id":"ers-research-question-protocol~ai-0","moduleId":"ers-research-question-protocol","stem":"Which of the following best describes a primary objective in a research study?","options":[{"id":"a","text":"It is the main goal that drives the sample-size calculation."},{"id":"b","text":"It is a secondary goal that explores additional outcomes."},{"id":"c","text":"It is a testable prediction about the study results."},{"id":"d","text":"It is a vague aim that guides the study direction."}],"answerId":"a","explanation":"The primary objective is singular and drives the sample-size calculation and the primary analysis.","kind":"recall","origin":"ai"},{"id":"ers-research-question-protocol~ai-1","moduleId":"ers-research-question-protocol","stem":"What is the role of the Institutional Review Board (IRB) in research?","options":[{"id":"a","text":"To approve the study after data collection begins."},{"id":"b","text":"To ensure the study's financial feasibility."},{"id":"c","text":"To review and approve the study before it starts."},{"id":"d","text":"To write the study's protocol."}],"answerId":"c","explanation":"IRB approval is required before enrolment to protect participants.","kind":"recall","origin":"ai"},{"id":"ers-research-question-protocol~ai-2","moduleId":"ers-research-question-protocol","stem":"Which statement correctly differentiates an objective from a hypothesis?","options":[{"id":"a","text":"The objective is a testable prediction; the hypothesis is what the study will do."},{"id":"b","text":"The objective is what the study will do; the hypothesis is a testable prediction."},{"id":"c","text":"Both are interchangeable and mean the same thing."},{"id":"d","text":"The hypothesis is broader than the objective."}],"answerId":"b","explanation":"The objective states what the study will do, while the hypothesis is the testable prediction.","kind":"trap","origin":"ai"},{"id":"ers-research-question-protocol~ai-3","moduleId":"ers-research-question-protocol","stem":"In the context of research ethics, which principle ensures that participants are treated fairly?","options":[{"id":"a","text":"Respect for autonomy"},{"id":"b","text":"Beneficence"},{"id":"c","text":"Non-maleficence"},{"id":"d","text":"Justice"}],"answerId":"d","explanation":"Justice ensures fair selection and treatment of participants.","kind":"recall","origin":"ai"},{"id":"ers-research-question-protocol~ai-4","moduleId":"ers-research-question-protocol","stem":"Which element of PICO(T) directly informs the choice of study design?","options":[{"id":"a","text":"Population"},{"id":"b","text":"Intervention"},{"id":"c","text":"Outcome"},{"id":"d","text":"Comparison"}],"answerId":"d","explanation":"The comparison element helps determine the type of study design needed.","kind":"mechanism","linkedModuleIds":["research-question-finer-pico"],"origin":"ai"},{"id":"ers-research-question-protocol~ai-5","moduleId":"ers-research-question-protocol","stem":"How does the Declaration of Helsinki influence research ethics?","options":[{"id":"a","text":"It mandates financial compensation for all participants."},{"id":"b","text":"It provides guidelines for ethical research conduct."},{"id":"c","text":"It requires all studies to be published in open access journals."},{"id":"d","text":"It allows for retrospective ethics approval."}],"answerId":"b","explanation":"The Declaration of Helsinki provides guidelines for ethical research conduct.","kind":"recall","origin":"ai"},{"id":"ers-research-question-protocol~ai-6","moduleId":"ers-research-question-protocol","stem":"When structuring a research question using PICO(T), what does the 'I' stand for?","options":[{"id":"a","text":"Intervention"},{"id":"b","text":"Interest"},{"id":"c","text":"Investigation"},{"id":"d","text":"Inclusion"}],"answerId":"a","explanation":"The 'I' in PICO(T) stands for Intervention or exposure.","kind":"recall","linkedModuleIds":["research-question-finer-pico"],"origin":"ai"},{"id":"ers-research-question-protocol~ai-7","moduleId":"ers-research-question-protocol","stem":"Which ethical principle is operationalized by obtaining informed consent?","options":[{"id":"a","text":"Justice"},{"id":"b","text":"Beneficence"},{"id":"c","text":"Respect for autonomy"},{"id":"d","text":"Non-maleficence"}],"answerId":"c","explanation":"Informed consent operationalizes respect for autonomy.","kind":"integration","linkedModuleIds":["ers-research-ethics"],"origin":"ai"}],"ers-causal-inference":[{"id":"ers-causal-inference~ai-0","moduleId":"ers-causal-inference","stem":"Which of the following is a necessary criterion for establishing causality according to the Bradford-Hill viewpoints?","options":[{"id":"a","text":"Temporality"},{"id":"b","text":"Strength"},{"id":"c","text":"Consistency"},{"id":"d","text":"Plausibility"}],"answerId":"a","explanation":"Temporality is the only near-essential criterion; the cause must precede the effect.","kind":"recall","origin":"ai"},{"id":"ers-causal-inference~ai-1","moduleId":"ers-causal-inference","stem":"In a study investigating the relationship between alcohol consumption and liver disease, smoking is identified as a factor that is associated with both alcohol consumption and liver disease but is not on the causal pathway. What is smoking in this context?","options":[{"id":"a","text":"Confounder"},{"id":"b","text":"Effect modifier"},{"id":"c","text":"Bias"},{"id":"d","text":"Outcome"}],"answerId":"a","explanation":"Smoking is a confounder because it is associated with both the exposure and the outcome but is not on the causal pathway.","kind":"mechanism","origin":"ai"},{"id":"ers-causal-inference~ai-2","moduleId":"ers-causal-inference","stem":"A researcher finds that the effect of a drug on blood pressure varies significantly between males and females. What is this an example of?","options":[{"id":"a","text":"Confounding"},{"id":"b","text":"Bias"},{"id":"c","text":"Effect modification"},{"id":"d","text":"Reverse causation"}],"answerId":"c","explanation":"Effect modification occurs when the effect of an exposure on an outcome differs across levels of another variable.","kind":"trap","origin":"ai"},{"id":"ers-causal-inference~ai-3","moduleId":"ers-causal-inference","stem":"Which method is unique in its ability to control for unknown confounders in a study design?","options":[{"id":"a","text":"Randomisation"},{"id":"b","text":"Stratification"},{"id":"c","text":"Matching"},{"id":"d","text":"Restriction"}],"answerId":"a","explanation":"Randomisation balances both known and unknown confounders by chance.","kind":"recall","origin":"ai"},{"id":"ers-causal-inference~ai-4","moduleId":"ers-causal-inference","stem":"In a case-control study, cases are more likely to remember their past exposures than controls. What type of bias does this describe?","options":[{"id":"a","text":"Recall bias"},{"id":"b","text":"Selection bias"},{"id":"c","text":"Confounding"},{"id":"d","text":"Reverse causation"}],"answerId":"a","explanation":"Recall bias occurs when cases remember exposures more thoroughly than controls, affecting retrospective studies.","kind":"recall","origin":"ai"},{"id":"ers-causal-inference~ai-5","moduleId":"ers-causal-inference","stem":"A study finds that the association between coffee consumption and lung cancer disappears after adjusting for smoking. What does this suggest about smoking?","options":[{"id":"a","text":"Smoking is a confounder"},{"id":"b","text":"Smoking is an effect modifier"},{"id":"c","text":"Smoking introduces bias"},{"id":"d","text":"Smoking is a reverse cause"}],"answerId":"a","explanation":"Smoking is a confounder as it is associated with both coffee consumption and lung cancer, distorting the observed association.","kind":"clinical","origin":"ai"},{"id":"ers-causal-inference~ai-6","moduleId":"ers-causal-inference","stem":"Which of the following scenarios best illustrates the concept of selection bias?","options":[{"id":"a","text":"Loss to follow-up in a cohort study"},{"id":"b","text":"Different recall of exposure between cases and controls"},{"id":"c","text":"A confounder not adjusted for in analysis"},{"id":"d","text":"Variation in treatment effect across subgroups"}],"answerId":"a","explanation":"Selection bias occurs when there is a systematic difference in who remains in the study, such as loss to follow-up.","kind":"recall","linkedModuleIds":["ers-bias-types"],"origin":"ai"},{"id":"ers-causal-inference~ai-7","moduleId":"ers-causal-inference","stem":"In a study on the effect of a new drug on reducing blood pressure, researchers find that the drug's efficacy is significantly different in patients with high baseline cholesterol compared to those with normal cholesterol. What is this an example of?","options":[{"id":"a","text":"Confounding"},{"id":"b","text":"Effect modification"},{"id":"c","text":"Selection bias"},{"id":"d","text":"Information bias"}],"answerId":"b","explanation":"This is an example of effect modification, where the effect of the drug varies based on cholesterol levels.","kind":"integration","linkedModuleIds":["variables-confounding-bias"],"origin":"ai"}],"ers-study-designs":[{"id":"ers-study-designs~ai-0","moduleId":"ers-study-designs","stem":"Which study design is most appropriate for investigating a rare disease?","options":[{"id":"a","text":"Case-control study"},{"id":"b","text":"Cohort study"},{"id":"c","text":"Randomized controlled trial"},{"id":"d","text":"Cross-sectional study"}],"answerId":"a","explanation":"Case-control studies are best for rare diseases because they start with the outcome and look back for exposure, making them efficient for rare conditions.","kind":"recall","origin":"ai"},{"id":"ers-study-designs~ai-1","moduleId":"ers-study-designs","stem":"A study investigates the association between smoking and lung cancer by enrolling patients with lung cancer and a matched group without. What measure of association will this study provide?","options":[{"id":"a","text":"Relative Risk"},{"id":"b","text":"Odds Ratio"},{"id":"c","text":"Incidence Rate"},{"id":"d","text":"Prevalence Ratio"}],"answerId":"b","explanation":"Case-control studies provide the Odds Ratio because they start with the outcome and do not have a denominator for incidence.","kind":"mechanism","origin":"ai"},{"id":"ers-study-designs~ai-2","moduleId":"ers-study-designs","stem":"Which type of bias is most likely if hospital controls are used in a case-control study?","options":[{"id":"a","text":"Selection bias"},{"id":"b","text":"Recall bias"},{"id":"c","text":"Information bias"},{"id":"d","text":"Confounding"}],"answerId":"a","explanation":"Using hospital controls can lead to selection bias if they do not represent the population that generated the cases.","kind":"trap","origin":"ai"},{"id":"ers-study-designs~ai-3","moduleId":"ers-study-designs","stem":"What is the main limitation of cross-sectional studies in establishing causality?","options":[{"id":"a","text":"Cannot establish temporality"},{"id":"b","text":"Prone to recall bias"},{"id":"c","text":"Expensive and time-consuming"},{"id":"d","text":"Limited to rare exposures"}],"answerId":"a","explanation":"Cross-sectional studies measure exposure and outcome at the same time, making it impossible to establish a temporal relationship.","kind":"mechanism","origin":"ai"},{"id":"ers-study-designs~ai-4","moduleId":"ers-study-designs","stem":"Which study design is most suitable for investigating the long-term effects of a rare exposure?","options":[{"id":"a","text":"Cohort study"},{"id":"b","text":"Case-control study"},{"id":"c","text":"Cross-sectional study"},{"id":"d","text":"Ecological study"}],"answerId":"a","explanation":"Cohort studies are ideal for rare exposures as they follow exposed and unexposed groups over time to observe outcomes.","kind":"recall","origin":"ai"},{"id":"ers-study-designs~ai-5","moduleId":"ers-study-designs","stem":"In a cohort study, what measure of association is typically calculated?","options":[{"id":"a","text":"Odds Ratio"},{"id":"b","text":"Relative Risk"},{"id":"c","text":"Prevalence Ratio"},{"id":"d","text":"Hazard Ratio"}],"answerId":"b","explanation":"Cohort studies provide the Relative Risk because they follow subjects over time, allowing for the calculation of incidence.","kind":"recall","origin":"ai"},{"id":"ers-study-designs~ai-6","moduleId":"ers-study-designs","stem":"How does the ecological fallacy affect the interpretation of study results?","options":[{"id":"a","text":"Associations at the group level may not hold at the individual level"},{"id":"b","text":"It leads to overestimation of risk"},{"id":"c","text":"It causes recall bias"},{"id":"d","text":"It results in selection bias"}],"answerId":"a","explanation":"The ecological fallacy occurs when group-level associations are incorrectly applied to individuals.","kind":"mechanism","origin":"ai"},{"id":"ers-study-designs~ai-7","moduleId":"ers-study-designs","stem":"Which study design provides the highest level of evidence for causation?","options":[{"id":"a","text":"Randomized controlled trial"},{"id":"b","text":"Cohort study"},{"id":"c","text":"Case-control study"},{"id":"d","text":"Cross-sectional study"}],"answerId":"a","explanation":"Randomized controlled trials provide the highest level of evidence for causation due to randomization and control over exposure.","kind":"integration","linkedModuleIds":["study-designs-hierarchy"],"origin":"ai"},{"id":"ers-study-designs~ai-8","moduleId":"ers-study-designs","stem":"In a study comparing the incidence of diabetes in smokers versus non-smokers, which study design is being used?","options":[{"id":"a","text":"Cohort study"},{"id":"b","text":"Case-control study"},{"id":"c","text":"Cross-sectional study"},{"id":"d","text":"Ecological study"}],"answerId":"a","explanation":"This is a cohort study as it follows smokers and non-smokers over time to compare the incidence of diabetes.","kind":"integration","linkedModuleIds":["ers-cohort-case-control"],"origin":"ai"}],"ers-biostatistics":[{"id":"ers-biostatistics~ai-0","moduleId":"ers-biostatistics","stem":"Which of the following is the most appropriate summary statistic for a dataset of blood pressure readings that are normally distributed?","options":[{"id":"a","text":"Mean ± SD"},{"id":"b","text":"Median (IQR)"},{"id":"c","text":"Mode"},{"id":"d","text":"Range"}],"answerId":"a","explanation":"For normally distributed data, the mean and standard deviation (SD) are the appropriate summary statistics.","kind":"recall","origin":"ai"},{"id":"ers-biostatistics~ai-1","moduleId":"ers-biostatistics","stem":"A dataset shows a right-skewed distribution. Which of the following is true about the mean and median?","options":[{"id":"a","text":"Mean > Median"},{"id":"b","text":"Mean < Median"},{"id":"c","text":"Mean = Median"},{"id":"d","text":"Mean is unrelated to Median"}],"answerId":"a","explanation":"In a right-skewed distribution, the mean is greater than the median due to the long tail on the right.","kind":"mechanism","origin":"ai"},{"id":"ers-biostatistics~ai-2","moduleId":"ers-biostatistics","stem":"A researcher reports the standard error (SE) of a sample mean. What does this indicate?","options":[{"id":"a","text":"The precision of the sample mean"},{"id":"b","text":"The spread of individual data points"},{"id":"c","text":"The median of the data"},{"id":"d","text":"The mode of the data"}],"answerId":"a","explanation":"SE indicates the precision of the sample mean and decreases as the sample size increases.","kind":"trap","origin":"ai"},{"id":"ers-biostatistics~ai-3","moduleId":"ers-biostatistics","stem":"When summarizing a dataset of ordinal data, which of the following is the most appropriate measure of central tendency?","options":[{"id":"a","text":"Median"},{"id":"b","text":"Mean"},{"id":"c","text":"Mode"},{"id":"d","text":"Standard Deviation"}],"answerId":"a","explanation":"For ordinal data, the median is the most appropriate measure of central tendency as it is not affected by outliers.","kind":"recall","origin":"ai"},{"id":"ers-biostatistics~ai-4","moduleId":"ers-biostatistics","stem":"A study reports that 95% of a normally distributed dataset falls within a certain range. What is this range?","options":[{"id":"a","text":"±2 SD"},{"id":"b","text":"±1 SD"},{"id":"c","text":"±3 SD"},{"id":"d","text":"±0.5 SD"}],"answerId":"a","explanation":"Approximately 95% of a normal distribution falls within ±2 standard deviations from the mean.","kind":"mechanism","origin":"ai"},{"id":"ers-biostatistics~ai-5","moduleId":"ers-biostatistics","stem":"In a clinical study, the sensitivity and specificity of a test are evaluated. How does this relate to the choice of statistical test for data analysis?","options":[{"id":"a","text":"Sensitivity and specificity do not affect the choice of statistical test"},{"id":"b","text":"They determine the type of distribution to use"},{"id":"c","text":"They dictate the use of parametric tests"},{"id":"d","text":"They influence the calculation of the mean"}],"answerId":"a","explanation":"Sensitivity and specificity are measures of test performance and do not directly affect the choice of statistical test for data analysis.","kind":"integration","linkedModuleIds":["add-biostatistics-sensitivity-specificity-ppv-and-npv"],"origin":"ai"},{"id":"ers-biostatistics~ai-6","moduleId":"ers-biostatistics","stem":"A dataset of heart rate measurements is analyzed. Which statistical measure would best describe the spread of individual heart rates?","options":[{"id":"a","text":"Standard Deviation"},{"id":"b","text":"Standard Error"},{"id":"c","text":"Mean"},{"id":"d","text":"Median"}],"answerId":"a","explanation":"Standard deviation describes the spread of individual data points in a dataset.","kind":"integration","linkedModuleIds":["cardiac-electrical-axis-vectors"],"origin":"ai"}],"ers-diagnostic-tests":[{"id":"ers-diagnostic-tests~ai-0","moduleId":"ers-diagnostic-tests","stem":"Which of the following statements about sensitivity is true?","options":[{"id":"a","text":"Sensitivity is the proportion of true positives among the diseased."},{"id":"b","text":"Sensitivity increases with disease prevalence."},{"id":"c","text":"Sensitivity is the proportion of true negatives among the non-diseased."},{"id":"d","text":"Sensitivity is the proportion of false positives among the non-diseased."}],"answerId":"a","explanation":"Sensitivity is calculated as a/(a+c), representing the proportion of true positives among those with the disease.","kind":"recall","origin":"ai"},{"id":"ers-diagnostic-tests~ai-1","moduleId":"ers-diagnostic-tests","stem":"A test with a sensitivity of 95% and specificity of 90% is used in a population with a low prevalence of disease. Which of the following is most likely true?","options":[{"id":"a","text":"The positive predictive value is high."},{"id":"b","text":"The negative predictive value is high."},{"id":"c","text":"The likelihood ratio for a positive test is less than 1."},{"id":"d","text":"The likelihood ratio for a negative test is greater than 1."}],"answerId":"b","explanation":"In a low prevalence setting, the negative predictive value is typically high due to fewer false negatives.","kind":"clinical","origin":"ai"},{"id":"ers-diagnostic-tests~ai-2","moduleId":"ers-diagnostic-tests","stem":"Which of the following indices is most affected by disease prevalence?","options":[{"id":"a","text":"Sensitivity"},{"id":"b","text":"Specificity"},{"id":"c","text":"Positive Predictive Value"},{"id":"d","text":"Likelihood Ratio"}],"answerId":"c","explanation":"Positive Predictive Value varies with prevalence, increasing as prevalence increases.","kind":"trap","origin":"ai"},{"id":"ers-diagnostic-tests~ai-3","moduleId":"ers-diagnostic-tests","stem":"A highly specific test is used to confirm a diagnosis. What is the primary advantage of using this test?","options":[{"id":"a","text":"It minimizes false negatives."},{"id":"b","text":"It minimizes false positives."},{"id":"c","text":"It increases the prevalence of the disease."},{"id":"d","text":"It decreases the prevalence of the disease."}],"answerId":"b","explanation":"A highly specific test minimizes false positives, making it useful for confirming a diagnosis (SPin).","kind":"mechanism","origin":"ai"},{"id":"ers-diagnostic-tests~ai-4","moduleId":"ers-diagnostic-tests","stem":"In a diagnostic test with a sensitivity of 80% and specificity of 70%, what is the likelihood ratio for a positive test?","options":[{"id":"a","text":"0.29"},{"id":"b","text":"1.14"},{"id":"c","text":"2.67"},{"id":"d","text":"4.00"}],"answerId":"c","explanation":"LR+ = Sens/(1−Spec) = 0.8/(1−0.7) = 2.67.","kind":"mechanism","origin":"ai"},{"id":"ers-diagnostic-tests~ai-5","moduleId":"ers-diagnostic-tests","stem":"How does moving the cutoff point of a continuous test to increase sensitivity affect specificity?","options":[{"id":"a","text":"Specificity increases."},{"id":"b","text":"Specificity decreases."},{"id":"c","text":"Specificity remains unchanged."},{"id":"d","text":"Specificity becomes irrelevant."}],"answerId":"b","explanation":"Increasing sensitivity by moving the cutoff typically decreases specificity due to more false positives.","kind":"mechanism","origin":"ai"},{"id":"ers-diagnostic-tests~ai-6","moduleId":"ers-diagnostic-tests","stem":"A test with a likelihood ratio of 5 is used in a population with a pre-test probability of 20%. What is the post-test probability of disease?","options":[{"id":"a","text":"20%"},{"id":"b","text":"33%"},{"id":"c","text":"50%"},{"id":"d","text":"67%"}],"answerId":"d","explanation":"Using the formula: post-test odds = pre-test odds × LR, then converting odds to probability, the post-test probability is approximately 67%.","kind":"integration","linkedModuleIds":["ers-pretest-posttest-probability"],"origin":"ai"},{"id":"ers-diagnostic-tests~ai-7","moduleId":"ers-diagnostic-tests","stem":"In a population with a disease prevalence of 10%, a test has a sensitivity of 90% and a specificity of 85%. What is the approximate positive predictive value?","options":[{"id":"a","text":"10%"},{"id":"b","text":"35%"},{"id":"c","text":"50%"},{"id":"d","text":"75%"}],"answerId":"b","explanation":"With low prevalence, even a good test will have a moderate PPV. Calculations show PPV is approximately 35%.","kind":"integration","linkedModuleIds":["ers-pretest-posttest-probability"],"origin":"ai"}],"ers-statistical-tests":[{"id":"ers-statistical-tests~ai-0","moduleId":"ers-statistical-tests","stem":"A study compares blood pressure levels before and after a new medication in the same group of patients. Which statistical test is appropriate?","options":[{"id":"a","text":"Independent t-test"},{"id":"b","text":"Paired t-test"},{"id":"c","text":"Chi-square test"},{"id":"d","text":"Mann-Whitney U test"}],"answerId":"b","explanation":"Paired data requires a paired t-test to account for the correlation within subjects.","kind":"mechanism","origin":"ai"},{"id":"ers-statistical-tests~ai-1","moduleId":"ers-statistical-tests","stem":"In a study with two independent groups, the outcome is a categorical variable with expected cell counts less than 5. Which test should be used?","options":[{"id":"a","text":"Chi-square test"},{"id":"b","text":"Fisher's exact test"},{"id":"c","text":"Independent t-test"},{"id":"d","text":"ANOVA"}],"answerId":"b","explanation":"Fisher's exact test is used when expected cell counts are less than 5.","kind":"recall","origin":"ai"},{"id":"ers-statistical-tests~ai-2","moduleId":"ers-statistical-tests","stem":"What does a p-value of 0.04 indicate in hypothesis testing?","options":[{"id":"a","text":"There is a 4% chance the null hypothesis is true"},{"id":"b","text":"The null hypothesis should be rejected at α = 0.05"},{"id":"c","text":"The effect size is large"},{"id":"d","text":"The null hypothesis is true"}],"answerId":"b","explanation":"A p-value less than α indicates that the null hypothesis should be rejected.","kind":"trap","origin":"ai"},{"id":"ers-statistical-tests~ai-3","moduleId":"ers-statistical-tests","stem":"Which test is appropriate for comparing the means of three independent groups with normally distributed data?","options":[{"id":"a","text":"ANOVA"},{"id":"b","text":"Kruskal-Wallis test"},{"id":"c","text":"Chi-square test"},{"id":"d","text":"Paired t-test"}],"answerId":"a","explanation":"ANOVA is used for comparing means across more than two groups with normal distribution.","kind":"mechanism","origin":"ai"},{"id":"ers-statistical-tests~ai-4","moduleId":"ers-statistical-tests","stem":"A researcher wants to detect a smaller effect size in a study. What should they consider regarding sample size?","options":[{"id":"a","text":"Decrease sample size"},{"id":"b","text":"Increase sample size"},{"id":"c","text":"Sample size does not matter"},{"id":"d","text":"Use a different statistical test"}],"answerId":"b","explanation":"Detecting smaller effects requires a larger sample size to achieve adequate power.","kind":"recall","origin":"ai"},{"id":"ers-statistical-tests~ai-5","moduleId":"ers-statistical-tests","stem":"A study aims to assess the correlation between two continuous variables with a non-normal distribution. Which test is appropriate?","options":[{"id":"a","text":"Pearson correlation"},{"id":"b","text":"Spearman correlation"},{"id":"c","text":"Chi-square test"},{"id":"d","text":"ANOVA"}],"answerId":"b","explanation":"Spearman correlation is used for non-normal distributions or ordinal data.","kind":"mechanism","origin":"ai"},{"id":"ers-statistical-tests~ai-6","moduleId":"ers-statistical-tests","stem":"How does increasing the variability (standard deviation) of a dataset affect the required sample size for a study?","options":[{"id":"a","text":"Decreases required sample size"},{"id":"b","text":"Increases required sample size"},{"id":"c","text":"Has no effect"},{"id":"d","text":"Allows for a smaller effect size to be detected"}],"answerId":"b","explanation":"Greater variability requires a larger sample size to detect the same effect size.","kind":"integration","linkedModuleIds":["ers-sample-size-power"],"origin":"ai"},{"id":"ers-statistical-tests~ai-7","moduleId":"ers-statistical-tests","stem":"Which statistical test is appropriate for comparing the means of two independent groups with non-normally distributed data?","options":[{"id":"a","text":"Independent t-test"},{"id":"b","text":"Mann-Whitney U test"},{"id":"c","text":"Paired t-test"},{"id":"d","text":"ANOVA"}],"answerId":"b","explanation":"Mann-Whitney U test is used for non-normally distributed data in two independent groups.","kind":"mechanism","origin":"ai"},{"id":"ers-statistical-tests~ai-8","moduleId":"ers-statistical-tests","stem":"A study is designed to have a power of 0.90. What does this imply about the study's ability to detect an effect?","options":[{"id":"a","text":"There is a 90% chance of a Type I error"},{"id":"b","text":"There is a 90% chance of detecting a true effect"},{"id":"c","text":"The study is underpowered"},{"id":"d","text":"The study will definitely detect an effect"}],"answerId":"b","explanation":"A power of 0.90 means there is a 90% probability of detecting a true effect if it exists.","kind":"integration","linkedModuleIds":["ers-sample-size-power"],"origin":"ai"}],"ers-rct":[{"id":"ers-rct~ai-0","moduleId":"ers-rct","stem":"Which of the following best describes the purpose of randomisation in a randomized controlled trial?","options":[{"id":"a","text":"To balance known and unknown confounders between groups"},{"id":"b","text":"To ensure blinding of participants and investigators"},{"id":"c","text":"To allow for per-protocol analysis"},{"id":"d","text":"To minimize the sample size required"}],"answerId":"a","explanation":"Randomisation balances both known and unknown confounders, making groups comparable at baseline.","kind":"recall","origin":"ai"},{"id":"ers-rct~ai-1","moduleId":"ers-rct","stem":"What is the primary reason for using intention-to-treat analysis in randomized controlled trials?","options":[{"id":"a","text":"To maintain the benefits of randomisation"},{"id":"b","text":"To exclude non-adherent participants"},{"id":"c","text":"To increase the statistical power of the study"},{"id":"d","text":"To ensure blinding of the study outcomes"}],"answerId":"a","explanation":"Intention-to-treat analysis preserves the benefits of randomisation by including all participants in the groups to which they were originally assigned.","kind":"mechanism","origin":"ai"},{"id":"ers-rct~ai-2","moduleId":"ers-rct","stem":"Which of the following is a common misconception about allocation concealment and blinding?","options":[{"id":"a","text":"They are the same process"},{"id":"b","text":"Allocation concealment prevents selection bias"},{"id":"c","text":"Blinding prevents performance bias"},{"id":"d","text":"Both are necessary for valid RCTs"}],"answerId":"a","explanation":"Allocation concealment and blinding are distinct processes that prevent different biases at different stages of a trial.","kind":"trap","origin":"ai"},{"id":"ers-rct~ai-3","moduleId":"ers-rct","stem":"In a randomized controlled trial, why is blinding particularly important for subjective outcomes?","options":[{"id":"a","text":"To prevent bias in symptom reporting and assessment"},{"id":"b","text":"To ensure randomisation of participants"},{"id":"c","text":"To balance known confounders"},{"id":"d","text":"To allow for per-protocol analysis"}],"answerId":"a","explanation":"Blinding is crucial for subjective outcomes to prevent expectation from influencing symptom reporting and assessment.","kind":"clinical","origin":"ai"},{"id":"ers-rct~ai-4","moduleId":"ers-rct","stem":"A study reports a higher efficacy of a drug in a per-protocol analysis compared to intention-to-treat. What is the most likely explanation?","options":[{"id":"a","text":"Per-protocol analysis excludes non-adherers, reintroducing confounding"},{"id":"b","text":"Intention-to-treat analysis overestimates the drug's effect"},{"id":"c","text":"Per-protocol analysis is more statistically powerful"},{"id":"d","text":"Intention-to-treat analysis is biased by non-compliance"}],"answerId":"a","explanation":"Per-protocol analysis excludes non-adherers, which can reintroduce confounding and exaggerate efficacy.","kind":"trap","origin":"ai"},{"id":"ers-rct~ai-5","moduleId":"ers-rct","stem":"How does allocation concealment differ from blinding in the context of a randomized controlled trial?","options":[{"id":"a","text":"Concealment prevents selection bias; blinding prevents performance bias"},{"id":"b","text":"Both prevent selection bias"},{"id":"c","text":"Concealment prevents performance bias; blinding prevents detection bias"},{"id":"d","text":"Both prevent detection bias"}],"answerId":"a","explanation":"Allocation concealment prevents selection bias by hiding the upcoming assignment, while blinding prevents performance and detection bias by hiding the received treatment.","kind":"recall","origin":"ai"},{"id":"ers-rct~ai-6","moduleId":"ers-rct","stem":"In the context of trial types and analysis, which analysis method is most aligned with preserving randomisation in a randomized controlled trial?","options":[{"id":"a","text":"Intention-to-treat analysis"},{"id":"b","text":"Per-protocol analysis"},{"id":"c","text":"Subgroup analysis"},{"id":"d","text":"Post-hoc analysis"}],"answerId":"a","explanation":"Intention-to-treat analysis maintains the benefits of randomisation by including all participants in their assigned groups.","kind":"integration","linkedModuleIds":["ers-trial-types-analysis"],"origin":"ai"},{"id":"ers-rct~ai-7","moduleId":"ers-rct","stem":"Which trial design aspect is crucial for minimizing bias in both subjective and objective outcomes in a randomized controlled trial?","options":[{"id":"a","text":"Blinding"},{"id":"b","text":"Allocation concealment"},{"id":"c","text":"Randomisation"},{"id":"d","text":"Sample size calculation"}],"answerId":"a","explanation":"Blinding is crucial for minimizing bias, especially in subjective outcomes, by preventing performance and detection bias.","kind":"integration","linkedModuleIds":["ers-trial-types-analysis"],"origin":"ai"}],"ers-cohort-case-control":[{"id":"ers-cohort-case-control~ai-0","moduleId":"ers-cohort-case-control","stem":"Which study design is most appropriate for investigating a rare disease with a long latency period?","options":[{"id":"a","text":"Case-control study"},{"id":"b","text":"Prospective cohort study"},{"id":"c","text":"Retrospective cohort study"},{"id":"d","text":"Cross-sectional study"}],"answerId":"a","explanation":"Case-control studies are efficient for rare diseases and long latency periods because they start with cases and controls, avoiding the need to follow large cohorts over time.","kind":"recall","origin":"ai"},{"id":"ers-cohort-case-control~ai-1","moduleId":"ers-cohort-case-control","stem":"A researcher uses old medical records to study the relationship between smoking and lung cancer. Which study design is this?","options":[{"id":"a","text":"Retrospective cohort study"},{"id":"b","text":"Prospective cohort study"},{"id":"c","text":"Case-control study"},{"id":"d","text":"Cross-sectional study"}],"answerId":"a","explanation":"A retrospective cohort study uses past records but still reasons from exposure to outcome, allowing for the calculation of incidence and relative risk.","kind":"trap","origin":"ai"},{"id":"ers-cohort-case-control~ai-2","moduleId":"ers-cohort-case-control","stem":"What is the main advantage of a nested case-control study within a cohort?","options":[{"id":"a","text":"Reduced recall bias"},{"id":"b","text":"Lower cost"},{"id":"c","text":"Higher incidence rate"},{"id":"d","text":"Elimination of selection bias"}],"answerId":"b","explanation":"Nested case-control studies are less expensive because they measure exposures only in a subset of the cohort, maintaining the cohort's rigor and temporality.","kind":"mechanism","origin":"ai"},{"id":"ers-cohort-case-control~ai-3","moduleId":"ers-cohort-case-control","stem":"In a case-control study, what is a common source of bias that can affect the results?","options":[{"id":"a","text":"Loss to follow-up"},{"id":"b","text":"Recall bias"},{"id":"c","text":"Measurement bias"},{"id":"d","text":"Confounding bias"}],"answerId":"b","explanation":"Recall bias occurs when cases remember past exposures differently than controls, affecting the accuracy of the exposure data in case-control studies.","kind":"clinical","origin":"ai"},{"id":"ers-cohort-case-control~ai-4","moduleId":"ers-cohort-case-control","stem":"Which of the following is a key disadvantage of cohort studies?","options":[{"id":"a","text":"Inability to calculate incidence"},{"id":"b","text":"High cost and time consumption"},{"id":"c","text":"Prone to recall bias"},{"id":"d","text":"Inefficient for common diseases"}],"answerId":"b","explanation":"Cohort studies are often expensive and time-consuming, especially when following participants over long periods.","kind":"recall","origin":"ai"},{"id":"ers-cohort-case-control~ai-5","moduleId":"ers-cohort-case-control","stem":"A study aims to determine the incidence of heart failure in smokers versus non-smokers. Which study design is most appropriate?","options":[{"id":"a","text":"Prospective cohort study"},{"id":"b","text":"Case-control study"},{"id":"c","text":"Cross-sectional study"},{"id":"d","text":"Ecological study"}],"answerId":"a","explanation":"A prospective cohort study is suitable for determining incidence and relative risk by following smokers and non-smokers over time.","kind":"integration","linkedModuleIds":["heart-failure-overview"],"origin":"ai"},{"id":"ers-cohort-case-control~ai-6","moduleId":"ers-cohort-case-control","stem":"Which study design is most appropriate for evaluating the association between a rare exposure and the development of heart failure?","options":[{"id":"a","text":"Prospective cohort study"},{"id":"b","text":"Case-control study"},{"id":"c","text":"Cross-sectional study"},{"id":"d","text":"Retrospective cohort study"}],"answerId":"a","explanation":"A prospective cohort study is ideal for rare exposures as it allows for the calculation of incidence and relative risk by following exposed and unexposed groups over time.","kind":"integration","linkedModuleIds":["hf-organ-pathology"],"origin":"ai"}],"ers-critical-appraisal":[{"id":"ers-critical-appraisal~ai-0","moduleId":"ers-critical-appraisal","stem":"Which of the following best describes internal validity in a clinical study?","options":[{"id":"a","text":"Freedom from bias, confounding, and chance within the study"},{"id":"b","text":"The ability to generalize findings to other settings"},{"id":"c","text":"The statistical significance of the study results"},{"id":"d","text":"The clinical importance of the study outcomes"}],"answerId":"a","explanation":"Internal validity refers to the extent to which the study is free from bias, confounding, and chance.","kind":"recall","origin":"ai"},{"id":"ers-critical-appraisal~ai-1","moduleId":"ers-critical-appraisal","stem":"A randomized controlled trial reports a p-value of 0.001 for its primary outcome. Which statement is correct?","options":[{"id":"a","text":"The treatment is clinically important"},{"id":"b","text":"The result is unlikely due to chance"},{"id":"c","text":"The study has high external validity"},{"id":"d","text":"The effect size is large"}],"answerId":"b","explanation":"A p-value of 0.001 indicates the result is unlikely due to chance, but does not imply clinical importance or effect size.","kind":"trap","origin":"ai"},{"id":"ers-critical-appraisal~ai-2","moduleId":"ers-critical-appraisal","stem":"In a cohort study, which factor is crucial for ensuring the comparability of groups?","options":[{"id":"a","text":"Randomization"},{"id":"b","text":"Blinded outcome assessment"},{"id":"c","text":"Matching or statistical adjustment for confounders"},{"id":"d","text":"Allocation concealment"}],"answerId":"c","explanation":"Matching or statistical adjustment for confounders is essential to ensure comparability in cohort studies.","kind":"mechanism","origin":"ai"},{"id":"ers-critical-appraisal~ai-3","moduleId":"ers-critical-appraisal","stem":"A study reports a statistically significant improvement in a surrogate endpoint. What should be considered next?","options":[{"id":"a","text":"The study's sample size"},{"id":"b","text":"The clinical importance of the surrogate endpoint"},{"id":"c","text":"The external validity of the study"},{"id":"d","text":"The study's funding source"}],"answerId":"b","explanation":"The clinical importance of the surrogate endpoint should be evaluated to determine its relevance to patient-important outcomes.","kind":"clinical","origin":"ai"},{"id":"ers-critical-appraisal~ai-4","moduleId":"ers-critical-appraisal","stem":"Which study design is generally considered the highest level of evidence in the evidence hierarchy?","options":[{"id":"a","text":"Randomized controlled trial"},{"id":"b","text":"Systematic review/meta-analysis"},{"id":"c","text":"Cohort study"},{"id":"d","text":"Case-control study"}],"answerId":"b","explanation":"Systematic reviews and meta-analyses are at the top of the evidence hierarchy.","kind":"recall","origin":"ai"},{"id":"ers-critical-appraisal~ai-5","moduleId":"ers-critical-appraisal","stem":"A well-conducted cohort study finds a strong association between a new drug and improved colonic motility. How should this finding be integrated into clinical practice?","options":[{"id":"a","text":"Immediately apply the findings to all patients"},{"id":"b","text":"Consider the study's external validity and applicability to your patient population"},{"id":"c","text":"Disregard the findings due to the study design"},{"id":"d","text":"Wait for a randomized controlled trial to confirm the results"}],"answerId":"b","explanation":"The external validity and applicability of the study findings to your specific patient population should be considered.","kind":"integration","linkedModuleIds":["colonic-motility-defecation"],"origin":"ai"},{"id":"ers-critical-appraisal~ai-6","moduleId":"ers-critical-appraisal","stem":"When appraising a diagnostic study, which element is essential for ensuring the study's internal validity?","options":[{"id":"a","text":"Randomization of participants"},{"id":"b","text":"Blinded assessment of outcomes"},{"id":"c","text":"Use of a surrogate endpoint"},{"id":"d","text":"Large sample size"}],"answerId":"b","explanation":"Blinded assessment of outcomes is crucial for internal validity in diagnostic studies.","kind":"mechanism","origin":"ai"},{"id":"ers-critical-appraisal~ai-7","moduleId":"ers-critical-appraisal","stem":"How does the concept of external validity relate to evidence-based practice?","options":[{"id":"a","text":"It ensures the study's results are statistically significant"},{"id":"b","text":"It determines if study findings are applicable to your patient population"},{"id":"c","text":"It focuses on the precision of the study's effect size"},{"id":"d","text":"It assesses the study's internal validity"}],"answerId":"b","explanation":"External validity assesses whether the findings are applicable to your patient population and setting.","kind":"integration","linkedModuleIds":["ers-evidence-based-medicine"],"origin":"ai"}],"ers-research-ethics":[{"id":"ers-research-ethics~ai-0","moduleId":"ers-research-ethics","stem":"Which principle of the Belmont Report is primarily concerned with ensuring that research participants are treated as autonomous agents?","options":[{"id":"a","text":"Respect for persons"},{"id":"b","text":"Beneficence"},{"id":"c","text":"Justice"},{"id":"d","text":"Non-maleficence"}],"answerId":"a","explanation":"The principle of respect for persons emphasizes the importance of informed consent and treating individuals as autonomous agents.","kind":"recall","origin":"ai"},{"id":"ers-research-ethics~ai-1","moduleId":"ers-research-ethics","stem":"A researcher is conducting a study involving prisoners. Which ethical principle requires extra protection for this population?","options":[{"id":"a","text":"Respect for persons"},{"id":"b","text":"Beneficence"},{"id":"c","text":"Justice"},{"id":"d","text":"Non-maleficence"}],"answerId":"c","explanation":"Justice requires fair selection of participants and extra protection for vulnerable populations like prisoners.","kind":"mechanism","origin":"ai"},{"id":"ers-research-ethics~ai-2","moduleId":"ers-research-ethics","stem":"Which of the following scenarios would invalidate informed consent obtained from a research participant?","options":[{"id":"a","text":"The participant was not informed of the study's risks"},{"id":"b","text":"The participant signed the consent form"},{"id":"c","text":"The participant was given adequate time to decide"},{"id":"d","text":"The participant voluntarily agreed to participate"}],"answerId":"a","explanation":"Informed consent is invalid if the participant is not informed of the study's risks, benefits, and procedures.","kind":"trap","origin":"ai"},{"id":"ers-research-ethics~ai-3","moduleId":"ers-research-ethics","stem":"In a clinical trial, which principle ensures that the benefits of the research outweigh the risks to the participants?","options":[{"id":"a","text":"Respect for persons"},{"id":"b","text":"Beneficence"},{"id":"c","text":"Justice"},{"id":"d","text":"Autonomy"}],"answerId":"b","explanation":"Beneficence involves maximizing benefits and minimizing harms to the research participants.","kind":"recall","origin":"ai"},{"id":"ers-research-ethics~ai-4","moduleId":"ers-research-ethics","stem":"A study involving children requires both assent and consent. What does this imply about the consent process?","options":[{"id":"a","text":"Children must fully understand the study"},{"id":"b","text":"Guardians provide consent, children provide assent"},{"id":"c","text":"Only children need to provide consent"},{"id":"d","text":"Only guardians need to provide consent"}],"answerId":"b","explanation":"Children provide assent while their guardians provide consent, acknowledging the limited capacity of minors to consent.","kind":"mechanism","origin":"ai"},{"id":"ers-research-ethics~ai-5","moduleId":"ers-research-ethics","stem":"Which of the following is a requirement for a valid informed consent process in a research study?","options":[{"id":"a","text":"The participant must be coerced into participating"},{"id":"b","text":"The participant must be informed about the study"},{"id":"c","text":"The participant must sign the consent form without reading it"},{"id":"d","text":"The participant must be a minor"}],"answerId":"b","explanation":"A valid informed consent process requires that the participant is fully informed about the study's purpose, risks, and benefits.","kind":"trap","origin":"ai"},{"id":"ers-research-ethics~ai-6","moduleId":"ers-research-ethics","stem":"How does the principle of justice relate to the selection of research participants?","options":[{"id":"a","text":"Ensures participants are treated with respect"},{"id":"b","text":"Ensures risks and benefits are fairly distributed"},{"id":"c","text":"Ensures participants are fully informed"},{"id":"d","text":"Ensures participants are not coerced"}],"answerId":"b","explanation":"Justice requires that the selection of research participants is fair and that the risks and benefits are equitably distributed.","kind":"mechanism","origin":"ai"},{"id":"ers-research-ethics~ai-7","moduleId":"ers-research-ethics","stem":"When developing a research question using the PICO(T) framework, which aspect is most directly related to ensuring ethical participant selection?","options":[{"id":"a","text":"Population"},{"id":"b","text":"Intervention"},{"id":"c","text":"Comparison"},{"id":"d","text":"Outcome"}],"answerId":"a","explanation":"The 'Population' component of PICO(T) is directly related to ensuring that the selection of participants is ethical and just.","kind":"integration","linkedModuleIds":["research-question-finer-pico"],"origin":"ai"},{"id":"ers-research-ethics~ai-8","moduleId":"ers-research-ethics","stem":"In the context of a study on child sexual abuse, why is it crucial to obtain both assent and consent?","options":[{"id":"a","text":"Children can provide full consent"},{"id":"b","text":"Guardians' consent is sufficient"},{"id":"c","text":"Assent respects the child's autonomy while guardians provide legal consent"},{"id":"d","text":"Only assent is needed"}],"answerId":"c","explanation":"Obtaining both assent and consent respects the child's autonomy and ensures legal consent from guardians.","kind":"integration","linkedModuleIds":["hrp1-child-sexual-abuse-response"],"origin":"ai"}],"ers-systematic-review-meta-analysis":[{"id":"ers-systematic-review-meta-analysis~ai-0","moduleId":"ers-systematic-review-meta-analysis","stem":"What is the primary purpose of a systematic review?","options":[{"id":"a","text":"To synthesize all relevant studies using explicit methods"},{"id":"b","text":"To statistically pool results from multiple studies"},{"id":"c","text":"To conduct new experimental research"},{"id":"d","text":"To develop clinical guidelines"}],"answerId":"a","explanation":"A systematic review uses explicit, reproducible methods to search, appraise, and synthesize all relevant studies.","kind":"recall","origin":"ai"},{"id":"ers-systematic-review-meta-analysis~ai-1","moduleId":"ers-systematic-review-meta-analysis","stem":"Which plot is used to assess publication bias in a meta-analysis?","options":[{"id":"a","text":"Forest plot"},{"id":"b","text":"Funnel plot"},{"id":"c","text":"Kaplan-Meier plot"},{"id":"d","text":"ROC curve"}],"answerId":"b","explanation":"The funnel plot screens for publication bias; asymmetry suggests missing small negative studies.","kind":"recall","origin":"ai"},{"id":"ers-systematic-review-meta-analysis~ai-2","moduleId":"ers-systematic-review-meta-analysis","stem":"A meta-analysis shows high heterogeneity with an I² of 80%. What model should be used?","options":[{"id":"a","text":"Fixed-effect model"},{"id":"b","text":"Random-effects model"},{"id":"c","text":"Bayesian model"},{"id":"d","text":"No model needed"}],"answerId":"b","explanation":"High heterogeneity (I² = 80%) suggests using a random-effects model, which accounts for a distribution of effects.","kind":"mechanism","origin":"ai"},{"id":"ers-systematic-review-meta-analysis~ai-3","moduleId":"ers-systematic-review-meta-analysis","stem":"In a meta-analysis, what does a forest plot diamond crossing the null line indicate?","options":[{"id":"a","text":"Significant pooled effect"},{"id":"b","text":"Non-significant pooled effect"},{"id":"c","text":"Publication bias"},{"id":"d","text":"High heterogeneity"}],"answerId":"b","explanation":"If the forest plot diamond crosses the null line, the pooled effect is non-significant.","kind":"recall","origin":"ai"},{"id":"ers-systematic-review-meta-analysis~ai-4","moduleId":"ers-systematic-review-meta-analysis","stem":"Which of the following best describes the 'garbage in, garbage out' concept in meta-analysis?","options":[{"id":"a","text":"Pooling biased studies yields a precise but invalid estimate"},{"id":"b","text":"All studies contribute equally to the pooled result"},{"id":"c","text":"Only high-quality studies are included in meta-analysis"},{"id":"d","text":"Meta-analysis results are always reliable"}],"answerId":"a","explanation":"Pooling biased studies produces a precise but potentially wrong estimate; appraise risk of bias first.","kind":"trap","origin":"ai"},{"id":"ers-systematic-review-meta-analysis~ai-5","moduleId":"ers-systematic-review-meta-analysis","stem":"How does the presence of publication bias affect the interpretation of a meta-analysis?","options":[{"id":"a","text":"It leads to overestimation of the treatment effect"},{"id":"b","text":"It has no effect on the results"},{"id":"c","text":"It underestimates the treatment effect"},{"id":"d","text":"It improves the precision of the estimate"}],"answerId":"a","explanation":"Publication bias, often due to missing small negative studies, can lead to an overestimation of the treatment effect.","kind":"mechanism","origin":"ai"},{"id":"ers-systematic-review-meta-analysis~ai-6","moduleId":"ers-systematic-review-meta-analysis","stem":"Which of the following is a key step in conducting a systematic review?","options":[{"id":"a","text":"Pre-registering the review protocol"},{"id":"b","text":"Conducting new experiments"},{"id":"c","text":"Developing clinical guidelines"},{"id":"d","text":"Performing a cost-benefit analysis"}],"answerId":"a","explanation":"Pre-registering the review protocol is crucial for transparency and reproducibility in systematic reviews.","kind":"recall","origin":"ai"},{"id":"ers-systematic-review-meta-analysis~ai-7","moduleId":"ers-systematic-review-meta-analysis","stem":"In the context of systematic reviews, what is the significance of using the PRISMA diagram?","options":[{"id":"a","text":"To report the flow of studies through the review process"},{"id":"b","text":"To calculate the pooled effect size"},{"id":"c","text":"To assess the quality of included studies"},{"id":"d","text":"To determine the level of heterogeneity"}],"answerId":"a","explanation":"The PRISMA diagram is used to report the flow of studies through the review process, including identification, screening, and inclusion.","kind":"recall","origin":"ai"},{"id":"ers-systematic-review-meta-analysis~ai-8","moduleId":"ers-systematic-review-meta-analysis","stem":"How might the concept of 'garbage in, garbage out' in meta-analysis relate to the interpretation of data in the 'One-Carbon Carriers' module?","options":[{"id":"a","text":"Poor-quality studies on vitamin B₁₂ can lead to incorrect conclusions"},{"id":"b","text":"All studies on THF are reliable"},{"id":"c","text":"SAM studies are not affected by study quality"},{"id":"d","text":"One-carbon carriers do not require meta-analysis"}],"answerId":"a","explanation":"Just as in meta-analysis, poor-quality studies on vitamin B₁₂ can lead to incorrect conclusions about its effects.","kind":"integration","linkedModuleIds":["one-carbon-carriers"],"origin":"ai"}],"ers-standardisation-rates":[{"id":"ers-standardisation-rates~ai-0","moduleId":"ers-standardisation-rates","stem":"What is the primary limitation of using crude rates for comparing mortality between two populations?","options":[{"id":"a","text":"They are confounded by population age structure."},{"id":"b","text":"They require age-specific data."},{"id":"c","text":"They are difficult to calculate."},{"id":"d","text":"They are not affected by population size."}],"answerId":"a","explanation":"Crude rates are influenced by the age distribution of the population, which can lead to misleading comparisons.","kind":"recall","origin":"ai"},{"id":"ers-standardisation-rates~ai-1","moduleId":"ers-standardisation-rates","stem":"A study finds that Population A has a higher crude death rate than Population B. What should be considered before concluding that Population A has a higher mortality risk?","options":[{"id":"a","text":"The age-standardised rates of both populations."},{"id":"b","text":"The total population size of both populations."},{"id":"c","text":"The gender distribution of both populations."},{"id":"d","text":"The economic status of both populations."}],"answerId":"a","explanation":"Age-standardised rates should be compared to account for differences in age distribution between populations.","kind":"clinical","origin":"ai"},{"id":"ers-standardisation-rates~ai-2","moduleId":"ers-standardisation-rates","stem":"Which method of standardisation involves applying a standard set of rates to each population's age structure?","options":[{"id":"a","text":"Indirect standardisation"},{"id":"b","text":"Direct standardisation"},{"id":"c","text":"Crude rate calculation"},{"id":"d","text":"Specific rate calculation"}],"answerId":"a","explanation":"Indirect standardisation applies a standard set of rates to the population's age structure to calculate expected events.","kind":"mechanism","origin":"ai"},{"id":"ers-standardisation-rates~ai-3","moduleId":"ers-standardisation-rates","stem":"If a population has an SMR of 120, what does this indicate?","options":[{"id":"a","text":"The population has 20% more observed events than expected."},{"id":"b","text":"The population has 20% fewer observed events than expected."},{"id":"c","text":"The population has the same number of observed events as expected."},{"id":"d","text":"The population data is insufficient for analysis."}],"answerId":"a","explanation":"An SMR of 120 indicates 20% more observed events than expected based on the standard population.","kind":"recall","origin":"ai"},{"id":"ers-standardisation-rates~ai-4","moduleId":"ers-standardisation-rates","stem":"Why might a population with a lower crude death rate have a higher age-standardised death rate compared to another population?","options":[{"id":"a","text":"The population is younger but has higher age-specific mortality rates."},{"id":"b","text":"The population is older but healthier."},{"id":"c","text":"The population has a larger size."},{"id":"d","text":"The population has a higher economic status."}],"answerId":"a","explanation":"A younger population with higher age-specific mortality rates can have a lower crude rate but a higher age-standardised rate.","kind":"trap","origin":"ai"},{"id":"ers-standardisation-rates~ai-5","moduleId":"ers-standardisation-rates","stem":"How does direct standardisation help in comparing mortality rates between two populations?","options":[{"id":"a","text":"It adjusts for age differences by applying each population's rates to a standard population."},{"id":"b","text":"It uses a standard set of rates to calculate expected events."},{"id":"c","text":"It calculates the crude rate for each population."},{"id":"d","text":"It focuses on gender-specific mortality rates."}],"answerId":"a","explanation":"Direct standardisation adjusts for age differences by applying each population's age-specific rates to a standard population.","kind":"mechanism","origin":"ai"},{"id":"ers-standardisation-rates~ai-6","moduleId":"ers-standardisation-rates","stem":"In a study comparing disease incidence, which measure would best account for differences in age distribution between populations?","options":[{"id":"a","text":"Age-standardised incidence rate"},{"id":"b","text":"Crude incidence rate"},{"id":"c","text":"Specific incidence rate"},{"id":"d","text":"Prevalence rate"}],"answerId":"a","explanation":"Age-standardised incidence rates account for differences in age distribution, allowing for fair comparisons.","kind":"integration","linkedModuleIds":["ers-measures-frequency-association"],"origin":"ai"},{"id":"ers-standardisation-rates~ai-7","moduleId":"ers-standardisation-rates","stem":"Which of the following is a potential pitfall when interpreting crude rates in epidemiological studies?","options":[{"id":"a","text":"Assuming they reflect true risk without considering age distribution."},{"id":"b","text":"Assuming they are unaffected by population size."},{"id":"c","text":"Assuming they are more accurate than age-specific rates."},{"id":"d","text":"Assuming they are easier to calculate than standardised rates."}],"answerId":"a","explanation":"Crude rates can be misleading if age distribution differences are not considered, as they do not reflect true risk.","kind":"trap","origin":"ai"}],"ers-pretest-posttest-probability":[{"id":"ers-pretest-posttest-probability~ai-0","moduleId":"ers-pretest-posttest-probability","stem":"A patient in a high-prevalence clinic tests positive for a disease with a likelihood ratio of 10. How does this affect the post-test probability compared to a low-prevalence setting?","options":[{"id":"a","text":"Post-test probability is higher in the high-prevalence setting"},{"id":"b","text":"Post-test probability is the same in both settings"},{"id":"c","text":"Post-test probability is lower in the high-prevalence setting"},{"id":"d","text":"Post-test probability is unaffected by prevalence"}],"answerId":"a","explanation":"Post-test probability depends on the pre-test probability, which is higher in a high-prevalence setting.","kind":"trap","origin":"ai"},{"id":"ers-pretest-posttest-probability~ai-1","moduleId":"ers-pretest-posttest-probability","stem":"Which of the following best describes the relationship between pre-test probability and post-test probability?","options":[{"id":"a","text":"Post-test probability is independent of pre-test probability"},{"id":"b","text":"Post-test probability decreases as pre-test probability increases"},{"id":"c","text":"Post-test probability increases as pre-test probability increases"},{"id":"d","text":"Post-test probability is always equal to pre-test probability"}],"answerId":"c","explanation":"Higher pre-test probability results in a higher post-test probability when the likelihood ratio is constant.","kind":"mechanism","origin":"ai"},{"id":"ers-pretest-posttest-probability~ai-2","moduleId":"ers-pretest-posttest-probability","stem":"In a screening setting, which cutoff should be chosen for a continuous test to minimize false negatives?","options":[{"id":"a","text":"A cutoff that maximizes sensitivity"},{"id":"b","text":"A cutoff that maximizes specificity"},{"id":"c","text":"A cutoff that balances sensitivity and specificity"},{"id":"d","text":"A cutoff that minimizes sensitivity"}],"answerId":"a","explanation":"In screening, minimizing false negatives is crucial, so a cutoff that maximizes sensitivity is preferred.","kind":"recall","origin":"ai"},{"id":"ers-pretest-posttest-probability~ai-3","moduleId":"ers-pretest-posttest-probability","stem":"A test with a likelihood ratio of 1 is performed. What is the expected change in post-test probability?","options":[{"id":"a","text":"Significant increase"},{"id":"b","text":"Significant decrease"},{"id":"c","text":"No change"},{"id":"d","text":"Moderate increase"}],"answerId":"c","explanation":"A likelihood ratio of 1 indicates no change in probability.","kind":"mechanism","origin":"ai"},{"id":"ers-pretest-posttest-probability~ai-4","moduleId":"ers-pretest-posttest-probability","stem":"A patient has a pre-test probability of 30% for a disease. After a test with a likelihood ratio of 5, what is the approximate post-test probability?","options":[{"id":"a","text":"15%"},{"id":"b","text":"50%"},{"id":"c","text":"70%"},{"id":"d","text":"90%"}],"answerId":"b","explanation":"The likelihood ratio of 5 significantly increases the probability from 30% to around 50%.","kind":"clinical","origin":"ai"},{"id":"ers-pretest-posttest-probability~ai-5","moduleId":"ers-pretest-posttest-probability","stem":"In the context of gestational diabetes screening, why is it important to consider pre-test probability?","options":[{"id":"a","text":"It determines the test's sensitivity"},{"id":"b","text":"It affects the interpretation of the test result"},{"id":"c","text":"It changes the test's specificity"},{"id":"d","text":"It is irrelevant to test interpretation"}],"answerId":"b","explanation":"Pre-test probability affects how a test result is interpreted, impacting clinical decisions.","kind":"integration","linkedModuleIds":["hen1-gestational-diabetes-diagnosis"],"origin":"ai"},{"id":"ers-pretest-posttest-probability~ai-6","moduleId":"ers-pretest-posttest-probability","stem":"How does the selection of a diagnostic test cutoff impact the ROC curve?","options":[{"id":"a","text":"It shifts the entire curve"},{"id":"b","text":"It determines a single point on the curve"},{"id":"c","text":"It changes the area under the curve"},{"id":"d","text":"It has no effect on the curve"}],"answerId":"b","explanation":"Each cutoff corresponds to a specific point on the ROC curve, representing a trade-off between sensitivity and specificity.","kind":"recall","origin":"ai"},{"id":"ers-pretest-posttest-probability~ai-7","moduleId":"ers-pretest-posttest-probability","stem":"In a study evaluating a new diabetes screening test, what role does pre-test probability play in interpreting the results?","options":[{"id":"a","text":"It is used to calculate the test's sensitivity"},{"id":"b","text":"It is irrelevant to the study's conclusions"},{"id":"c","text":"It helps determine the post-test probability"},{"id":"d","text":"It directly affects the test's specificity"}],"answerId":"c","explanation":"Pre-test probability is crucial for calculating the post-test probability, influencing clinical interpretation.","kind":"integration","linkedModuleIds":["diabetes-diagnostic-criteria-gdm"],"origin":"ai"}],"ers-distributions-confidence-intervals":[{"id":"ers-distributions-confidence-intervals~ai-0","moduleId":"ers-distributions-confidence-intervals","stem":"Which statement best describes the Central Limit Theorem?","options":[{"id":"a","text":"Sample means are normally distributed regardless of sample size."},{"id":"b","text":"The distribution of sample means is approximately normal for large sample sizes."},{"id":"c","text":"The sample mean is always equal to the population mean."},{"id":"d","text":"The Central Limit Theorem applies only to normally distributed populations."}],"answerId":"b","explanation":"The Central Limit Theorem states that the distribution of sample means approaches normality as the sample size increases, regardless of the population's distribution.","kind":"recall","origin":"ai"},{"id":"ers-distributions-confidence-intervals~ai-1","moduleId":"ers-distributions-confidence-intervals","stem":"What does a 95% confidence interval indicate?","options":[{"id":"a","text":"95% probability that the interval contains the true population parameter."},{"id":"b","text":"The interval will contain the true parameter in 95% of repeated samples."},{"id":"c","text":"The true parameter is within the interval 95% of the time."},{"id":"d","text":"The interval is 95% of the sample mean."}],"answerId":"b","explanation":"A 95% confidence interval means that if the study were repeated many times, approximately 95% of the calculated intervals would contain the true population parameter.","kind":"recall","origin":"ai"},{"id":"ers-distributions-confidence-intervals~ai-2","moduleId":"ers-distributions-confidence-intervals","stem":"A study reports a confidence interval for a mean difference as -0.5 to 1.2. What does this imply?","options":[{"id":"a","text":"The study found a significant difference."},{"id":"b","text":"The study was under-powered or imprecise."},{"id":"c","text":"The true mean difference is zero."},{"id":"d","text":"The sample size was too large."}],"answerId":"b","explanation":"A confidence interval crossing zero indicates a non-significant result, suggesting the study might be under-powered or imprecise.","kind":"trap","origin":"ai"},{"id":"ers-distributions-confidence-intervals~ai-3","moduleId":"ers-distributions-confidence-intervals","stem":"How does increasing the sample size affect the standard error and confidence interval?","options":[{"id":"a","text":"Increases standard error and narrows confidence interval."},{"id":"b","text":"Decreases standard error and narrows confidence interval."},{"id":"c","text":"Increases standard error and widens confidence interval."},{"id":"d","text":"Decreases standard error and widens confidence interval."}],"answerId":"b","explanation":"Increasing the sample size decreases the standard error, leading to a narrower confidence interval.","kind":"mechanism","origin":"ai"},{"id":"ers-distributions-confidence-intervals~ai-4","moduleId":"ers-distributions-confidence-intervals","stem":"A study's confidence interval for a risk ratio is 0.8 to 1.5. What can be concluded?","options":[{"id":"a","text":"The risk ratio is significantly different from 1."},{"id":"b","text":"The study is under-powered or imprecise."},{"id":"c","text":"The risk ratio is exactly 1."},{"id":"d","text":"The risk ratio is significantly less than 1."}],"answerId":"b","explanation":"A confidence interval crossing 1 for a risk ratio indicates a non-significant result, suggesting the study might be under-powered or imprecise.","kind":"trap","origin":"ai"},{"id":"ers-distributions-confidence-intervals~ai-5","moduleId":"ers-distributions-confidence-intervals","stem":"In the context of pharmacogenomics, why is it important to consider confidence intervals in drug efficacy studies?","options":[{"id":"a","text":"They determine the exact dose for all patients."},{"id":"b","text":"They show the variability and precision of drug effects across populations."},{"id":"c","text":"They confirm the drug's mechanism of action."},{"id":"d","text":"They indicate the drug's side effect profile."}],"answerId":"b","explanation":"Confidence intervals provide information on the variability and precision of drug effects, which is crucial in pharmacogenomics for understanding efficacy across different genetic profiles.","kind":"integration","linkedModuleIds":["pharmacogenomics"],"origin":"ai"},{"id":"ers-distributions-confidence-intervals~ai-6","moduleId":"ers-distributions-confidence-intervals","stem":"How does understanding confidence intervals benefit the interpretation of sensitivity and specificity in diagnostic tests?","options":[{"id":"a","text":"It confirms the test's accuracy."},{"id":"b","text":"It provides a range for the test's reliability."},{"id":"c","text":"It determines the test's cost-effectiveness."},{"id":"d","text":"It specifies the test's applicability to all populations."}],"answerId":"b","explanation":"Confidence intervals offer a range for sensitivity and specificity, indicating the reliability and precision of these measures in diagnostic tests.","kind":"integration","linkedModuleIds":["add-biostatistics-sensitivity-specificity-ppv-and-npv"],"origin":"ai"}],"ers-bias-types":[{"id":"ers-bias-types~ai-0","moduleId":"ers-bias-types","stem":"Which type of bias occurs when a study includes only hospital patients, potentially leading to non-representative samples?","options":[{"id":"a","text":"Berkson's bias"},{"id":"b","text":"Recall bias"},{"id":"c","text":"Lead-time bias"},{"id":"d","text":"Length-time bias"}],"answerId":"a","explanation":"Berkson's bias occurs when hospital-based samples are not representative of the general population.","kind":"recall","origin":"ai"},{"id":"ers-bias-types~ai-1","moduleId":"ers-bias-types","stem":"In a case-control study, cases are more likely to remember past exposures than controls. What type of bias does this describe?","options":[{"id":"a","text":"Recall bias"},{"id":"b","text":"Berkson's bias"},{"id":"c","text":"Lead-time bias"},{"id":"d","text":"Non-differential misclassification"}],"answerId":"a","explanation":"Recall bias occurs when cases recall past exposures differently than controls, affecting the study's results.","kind":"mechanism","origin":"ai"},{"id":"ers-bias-types~ai-2","moduleId":"ers-bias-types","stem":"A study on a new cancer screening test shows increased survival time without affecting overall mortality. Which bias might explain this?","options":[{"id":"a","text":"Lead-time bias"},{"id":"b","text":"Recall bias"},{"id":"c","text":"Berkson's bias"},{"id":"d","text":"Length-time bias"}],"answerId":"a","explanation":"Lead-time bias occurs when earlier diagnosis inflates apparent survival time without changing the actual time of death.","kind":"clinical","origin":"ai"},{"id":"ers-bias-types~ai-3","moduleId":"ers-bias-types","stem":"Which bias is most likely to occur if participants drop out of a study due to adverse effects of the treatment?","options":[{"id":"a","text":"Attrition bias"},{"id":"b","text":"Recall bias"},{"id":"c","text":"Lead-time bias"},{"id":"d","text":"Length-time bias"}],"answerId":"a","explanation":"Attrition bias, a form of selection bias, occurs when dropouts differ systematically from those who complete the study.","kind":"trap","origin":"ai"},{"id":"ers-bias-types~ai-4","moduleId":"ers-bias-types","stem":"In a cohort study, errors in measuring exposure are unrelated to the outcome group. What is the likely effect of this bias?","options":[{"id":"a","text":"Bias toward the null"},{"id":"b","text":"Exaggeration of effect"},{"id":"c","text":"Reversal of effect"},{"id":"d","text":"No bias"}],"answerId":"a","explanation":"Non-differential misclassification typically biases results toward the null, as errors are random and unrelated to group.","kind":"mechanism","origin":"ai"},{"id":"ers-bias-types~ai-5","moduleId":"ers-bias-types","stem":"A study uses a volunteer sample to assess the prevalence of a disease. Which type of bias is most likely affecting the study?","options":[{"id":"a","text":"Selection bias"},{"id":"b","text":"Recall bias"},{"id":"c","text":"Lead-time bias"},{"id":"d","text":"Length-time bias"}],"answerId":"a","explanation":"Selection bias occurs when the sample is not representative of the target population, such as when using volunteers.","kind":"recall","origin":"ai"},{"id":"ers-bias-types~ai-6","moduleId":"ers-bias-types","stem":"How does non-differential misclassification of exposure typically affect the results of a study?","options":[{"id":"a","text":"Biases toward the null"},{"id":"b","text":"Inflates effect size"},{"id":"c","text":"Deflates effect size"},{"id":"d","text":"No effect"}],"answerId":"a","explanation":"Non-differential misclassification usually biases results toward the null by introducing random noise.","kind":"trap","origin":"ai"},{"id":"ers-bias-types~ai-7","moduleId":"ers-bias-types","stem":"A study on smoking and lung cancer includes only participants who have survived for at least five years. Which bias might this introduce?","options":[{"id":"a","text":"Prevalence-incidence bias"},{"id":"b","text":"Recall bias"},{"id":"c","text":"Lead-time bias"},{"id":"d","text":"Length-time bias"}],"answerId":"a","explanation":"Prevalence-incidence bias (Neyman bias) occurs when only survivors are included, potentially skewing results.","kind":"integration","linkedModuleIds":["ers-causal-inference"],"origin":"ai"},{"id":"ers-bias-types~ai-8","moduleId":"ers-bias-types","stem":"A researcher uses a convenience sample to study dietary habits. What type of bias is most likely to occur?","options":[{"id":"a","text":"Selection bias"},{"id":"b","text":"Recall bias"},{"id":"c","text":"Lead-time bias"},{"id":"d","text":"Length-time bias"}],"answerId":"a","explanation":"Selection bias is likely because a convenience sample may not be representative of the general population.","kind":"integration","linkedModuleIds":["sampling-methods"],"origin":"ai"}],"ers-meta-analysis-interpretation":[{"id":"ers-meta-analysis-interpretation~ai-0","moduleId":"ers-meta-analysis-interpretation","stem":"In a forest plot, what does it indicate if the diamond representing the pooled estimate crosses the null line?","options":[{"id":"a","text":"The pooled effect is non-significant"},{"id":"b","text":"The pooled effect is significant"},{"id":"c","text":"There is high heterogeneity"},{"id":"d","text":"There is publication bias"}],"answerId":"a","explanation":"A diamond crossing the null line means the confidence interval includes the null effect, indicating a non-significant pooled effect.","kind":"recall","origin":"ai"},{"id":"ers-meta-analysis-interpretation~ai-1","moduleId":"ers-meta-analysis-interpretation","stem":"Which model should be preferred when a meta-analysis shows high I² values?","options":[{"id":"a","text":"Fixed-effects model"},{"id":"b","text":"Random-effects model"},{"id":"c","text":"Bayesian model"},{"id":"d","text":"No model is appropriate"}],"answerId":"b","explanation":"High I² indicates significant heterogeneity, suggesting a random-effects model is more appropriate as it accounts for variability between studies.","kind":"mechanism","origin":"ai"},{"id":"ers-meta-analysis-interpretation~ai-2","moduleId":"ers-meta-analysis-interpretation","stem":"What does asymmetry in a funnel plot suggest in the context of a meta-analysis?","options":[{"id":"a","text":"Publication bias"},{"id":"b","text":"High heterogeneity"},{"id":"c","text":"Significant pooled effect"},{"id":"d","text":"Equal study weights"}],"answerId":"a","explanation":"Asymmetry in a funnel plot suggests publication bias, often due to missing small negative studies.","kind":"recall","origin":"ai"},{"id":"ers-meta-analysis-interpretation~ai-3","moduleId":"ers-meta-analysis-interpretation","stem":"In a meta-analysis, why are larger studies given more weight in the pooled estimate?","options":[{"id":"a","text":"They have more participants"},{"id":"b","text":"They are more precise"},{"id":"c","text":"They are more recent"},{"id":"d","text":"They are more diverse"}],"answerId":"b","explanation":"Larger studies are more precise, and precision is used for weighting in meta-analyses.","kind":"trap","origin":"ai"},{"id":"ers-meta-analysis-interpretation~ai-4","moduleId":"ers-meta-analysis-interpretation","stem":"A meta-analysis shows a significant pooled effect, but the I² is 80%. What should be the next step?","options":[{"id":"a","text":"Use a fixed-effects model"},{"id":"b","text":"Investigate sources of heterogeneity"},{"id":"c","text":"Ignore the I² value"},{"id":"d","text":"Conclude the effect is consistent across studies"}],"answerId":"b","explanation":"An I² of 80% indicates high heterogeneity, so investigating the sources of heterogeneity is crucial.","kind":"clinical","origin":"ai"},{"id":"ers-meta-analysis-interpretation~ai-5","moduleId":"ers-meta-analysis-interpretation","stem":"How does the interpretation of a forest plot relate to the interpretation of liver function tests?","options":[{"id":"a","text":"Both require understanding variability and significance"},{"id":"b","text":"Both focus on precision and weight"},{"id":"c","text":"Both are used to assess organ function"},{"id":"d","text":"Both rely on visual symmetry"}],"answerId":"a","explanation":"Interpreting both forest plots and liver function tests involves understanding variability and significance of results.","kind":"integration","linkedModuleIds":["liver-function-tests-interpretation"],"origin":"ai"},{"id":"ers-meta-analysis-interpretation~ai-6","moduleId":"ers-meta-analysis-interpretation","stem":"How does the concept of heterogeneity in meta-analyses relate to the variability seen in pulmonary function tests?","options":[{"id":"a","text":"Both deal with variability in measurements"},{"id":"b","text":"Both use fixed-effects models"},{"id":"c","text":"Both rely on inverse-variance weighting"},{"id":"d","text":"Both are unaffected by sample size"}],"answerId":"a","explanation":"Both heterogeneity in meta-analyses and variability in pulmonary function tests deal with variability in measurements across different studies or tests.","kind":"integration","linkedModuleIds":["pulmonary-function-tests-interpretation"],"origin":"ai"}],"ers-sample-size-power":[{"id":"ers-sample-size-power~ai-0","moduleId":"ers-sample-size-power","stem":"What is the probability of detecting a true effect in a study with a power of 0.85?","options":[{"id":"a","text":"0.15"},{"id":"b","text":"0.85"},{"id":"c","text":"0.05"},{"id":"d","text":"0.20"}],"answerId":"b","explanation":"Power is defined as 1 minus the probability of a Type II error (β), so a power of 0.85 means there is an 85% chance of detecting a true effect.","kind":"recall","origin":"ai"},{"id":"ers-sample-size-power~ai-1","moduleId":"ers-sample-size-power","stem":"A study finds no significant difference between two treatments. Which of the following is a potential issue if the study had a small sample size?","options":[{"id":"a","text":"Type I error"},{"id":"b","text":"Type II error"},{"id":"c","text":"High power"},{"id":"d","text":"Large effect size"}],"answerId":"b","explanation":"A small sample size may lead to a Type II error, where a real effect is missed due to insufficient power.","kind":"trap","origin":"ai"},{"id":"ers-sample-size-power~ai-2","moduleId":"ers-sample-size-power","stem":"Which factor would increase the required sample size for a study?","options":[{"id":"a","text":"Larger effect size"},{"id":"b","text":"Lower variability"},{"id":"c","text":"Higher power"},{"id":"d","text":"Higher significance level"}],"answerId":"c","explanation":"Higher power requires a larger sample size to ensure the study can detect the specified true effect.","kind":"mechanism","origin":"ai"},{"id":"ers-sample-size-power~ai-3","moduleId":"ers-sample-size-power","stem":"In hypothesis testing, what is the consequence of setting a smaller significance level (α)?","options":[{"id":"a","text":"Increased Type I error"},{"id":"b","text":"Decreased sample size"},{"id":"c","text":"Increased sample size"},{"id":"d","text":"Decreased Type II error"}],"answerId":"c","explanation":"A smaller significance level requires a larger sample size to maintain the same power, reducing the risk of a Type I error.","kind":"mechanism","origin":"ai"},{"id":"ers-sample-size-power~ai-4","moduleId":"ers-sample-size-power","stem":"Which of the following best describes the relationship between sample size and effect size in study design?","options":[{"id":"a","text":"Larger effect size requires larger sample size"},{"id":"b","text":"Smaller effect size requires larger sample size"},{"id":"c","text":"Effect size does not affect sample size"},{"id":"d","text":"Sample size is only affected by power"}],"answerId":"b","explanation":"Detecting a smaller effect size requires a larger sample size to achieve the same power.","kind":"recall","origin":"ai"},{"id":"ers-sample-size-power~ai-5","moduleId":"ers-sample-size-power","stem":"A study on labor stages requires a sample size calculation. Which factor from the 'Labor Recognition, Stages & Cardinal Movements' module is most relevant?","options":[{"id":"a","text":"Duration of labor"},{"id":"b","text":"Type of delivery"},{"id":"c","text":"Maternal age"},{"id":"d","text":"Effect size of intervention"}],"answerId":"d","explanation":"Effect size of intervention is crucial in determining the sample size needed to detect a significant difference in labor outcomes.","kind":"integration","linkedModuleIds":["hrp1-labor-stages-mechanics"],"origin":"ai"},{"id":"ers-sample-size-power~ai-6","moduleId":"ers-sample-size-power","stem":"In a study analyzing amino-acid metabolism, which statistical consideration is crucial when determining sample size?","options":[{"id":"a","text":"Metabolic rate variability"},{"id":"b","text":"Type of amino acid"},{"id":"c","text":"Dietary intake"},{"id":"d","text":"Sample collection method"}],"answerId":"a","explanation":"Variability in metabolic rate affects the sample size needed to detect differences in amino-acid metabolism.","kind":"integration","linkedModuleIds":["amino-carbon-skeleton-disorders"],"origin":"ai"}],"ers-trial-types-analysis":[{"id":"ers-trial-types-analysis~ai-0","moduleId":"ers-trial-types-analysis","stem":"Which type of trial design is most appropriate for testing if a new drug is not worse than the standard treatment by a pre-set margin?","options":[{"id":"a","text":"Superiority trial"},{"id":"b","text":"Non-inferiority trial"},{"id":"c","text":"Equivalence trial"},{"id":"d","text":"Factorial trial"}],"answerId":"b","explanation":"A non-inferiority trial is designed to determine if a new treatment is not worse than the standard treatment by more than a pre-set margin.","kind":"recall","origin":"ai"},{"id":"ers-trial-types-analysis~ai-1","moduleId":"ers-trial-types-analysis","stem":"In a non-inferiority trial, what is the primary statistical measure used to determine non-inferiority?","options":[{"id":"a","text":"P-value"},{"id":"b","text":"Confidence interval vs zero"},{"id":"c","text":"Confidence interval vs the margin Δ"},{"id":"d","text":"Mean difference"}],"answerId":"c","explanation":"Non-inferiority is judged by whether the confidence interval for the difference stays on the acceptable side of the pre-set margin Δ.","kind":"mechanism","origin":"ai"},{"id":"ers-trial-types-analysis~ai-2","moduleId":"ers-trial-types-analysis","stem":"What is a potential issue with using intention-to-treat analysis in non-inferiority trials?","options":[{"id":"a","text":"It can underestimate the treatment effect"},{"id":"b","text":"It can bias towards showing non-inferiority"},{"id":"c","text":"It increases the risk of type I error"},{"id":"d","text":"It requires larger sample sizes"}],"answerId":"b","explanation":"Intention-to-treat analysis can bias towards showing non-inferiority because it includes all randomized participants, regardless of adherence.","kind":"trap","origin":"ai"},{"id":"ers-trial-types-analysis~ai-3","moduleId":"ers-trial-types-analysis","stem":"Which trial design requires accounting for within-cluster correlation during analysis?","options":[{"id":"a","text":"Crossover trial"},{"id":"b","text":"Parallel trial"},{"id":"c","text":"Cluster trial"},{"id":"d","text":"Factorial trial"}],"answerId":"c","explanation":"Cluster trials randomize groups rather than individuals, requiring analysis that accounts for within-cluster correlation.","kind":"mechanism","origin":"ai"},{"id":"ers-trial-types-analysis~ai-4","moduleId":"ers-trial-types-analysis","stem":"A trial is stopped early due to overwhelming benefit. What is a potential issue with this decision?","options":[{"id":"a","text":"Underestimation of effect size"},{"id":"b","text":"Overestimation of effect size"},{"id":"c","text":"Increased risk of type II error"},{"id":"d","text":"Increased sample size requirement"}],"answerId":"b","explanation":"Stopping a trial early for benefit tends to overestimate the effect size.","kind":"trap","origin":"ai"},{"id":"ers-trial-types-analysis~ai-5","moduleId":"ers-trial-types-analysis","stem":"In a crossover trial, why is a washout period necessary?","options":[{"id":"a","text":"To reduce sample size"},{"id":"b","text":"To prevent carry-over effects"},{"id":"c","text":"To ensure blinding"},{"id":"d","text":"To allow interim analysis"}],"answerId":"b","explanation":"A washout period is necessary in crossover trials to prevent carry-over effects from contaminating the second treatment period.","kind":"mechanism","origin":"ai"},{"id":"ers-trial-types-analysis~ai-6","moduleId":"ers-trial-types-analysis","stem":"How does a non-inferiority trial differ from a superiority trial in terms of hypothesis testing?","options":[{"id":"a","text":"Non-inferiority trials test for any difference"},{"id":"b","text":"Superiority trials test for equivalence"},{"id":"c","text":"Non-inferiority trials test against a margin Δ"},{"id":"d","text":"Superiority trials use non-significant p-values"}],"answerId":"c","explanation":"Non-inferiority trials test if the new treatment is not worse than the standard by more than a pre-set margin Δ, unlike superiority trials which test if one treatment is better than another.","kind":"integration","linkedModuleIds":["ers-rct"],"origin":"ai"},{"id":"ers-trial-types-analysis~ai-7","moduleId":"ers-trial-types-analysis","stem":"Which analysis is crucial for sensitivity checks in non-inferiority trials?","options":[{"id":"a","text":"Per-protocol analysis"},{"id":"b","text":"Intention-to-treat analysis"},{"id":"c","text":"Subgroup analysis"},{"id":"d","text":"Meta-analysis"}],"answerId":"a","explanation":"Per-protocol analysis is crucial in non-inferiority trials to ensure that the results are not biased towards non-inferiority.","kind":"integration","linkedModuleIds":["ers-rct"],"origin":"ai"}],"ers-evidence-based-medicine":[{"id":"ers-evidence-based-medicine~ai-0","moduleId":"ers-evidence-based-medicine","stem":"Which of the following study designs is most appropriate for answering a therapy-related question in evidence-based medicine?","options":[{"id":"a","text":"Randomized controlled trial"},{"id":"b","text":"Cohort study"},{"id":"c","text":"Case-control study"},{"id":"d","text":"Cross-sectional study"}],"answerId":"a","explanation":"Randomized controlled trials (RCTs) are the gold standard for therapy questions due to their ability to minimize bias.","kind":"recall","origin":"ai"},{"id":"ers-evidence-based-medicine~ai-1","moduleId":"ers-evidence-based-medicine","stem":"In the context of evidence-based medicine, what does the 'Appraise' step involve?","options":[{"id":"a","text":"Formulating a clinical question"},{"id":"b","text":"Evaluating the validity and applicability of evidence"},{"id":"c","text":"Implementing evidence into practice"},{"id":"d","text":"Assessing patient outcomes"}],"answerId":"b","explanation":"The 'Appraise' step involves critically evaluating the evidence for its validity, importance, and applicability.","kind":"mechanism","origin":"ai"},{"id":"ers-evidence-based-medicine~ai-2","moduleId":"ers-evidence-based-medicine","stem":"A strong clinical recommendation can be based on which level of evidence certainty according to GRADE?","options":[{"id":"a","text":"High certainty only"},{"id":"b","text":"Moderate certainty only"},{"id":"c","text":"Low certainty only"},{"id":"d","text":"Any level of certainty"}],"answerId":"d","explanation":"GRADE allows strong recommendations to be made even on low-certainty evidence if the benefits clearly outweigh the risks.","kind":"trap","origin":"ai"},{"id":"ers-evidence-based-medicine~ai-3","moduleId":"ers-evidence-based-medicine","stem":"Which of the following best describes evidence-based medicine?","options":[{"id":"a","text":"Following the highest-level study regardless of patient context"},{"id":"b","text":"Integrating best evidence with clinical expertise and patient values"},{"id":"c","text":"Using clinical expertise alone to guide treatment"},{"id":"d","text":"Basing decisions solely on patient preferences"}],"answerId":"b","explanation":"EBM integrates the best available evidence with clinical expertise and patient values/preferences.","kind":"trap","origin":"ai"},{"id":"ers-evidence-based-medicine~ai-4","moduleId":"ers-evidence-based-medicine","stem":"When considering the prognosis of a disease, which study design is most appropriate?","options":[{"id":"a","text":"Randomized controlled trial"},{"id":"b","text":"Cohort study"},{"id":"c","text":"Case-control study"},{"id":"d","text":"Cross-sectional study"}],"answerId":"b","explanation":"Cohort studies are best suited for prognosis questions as they follow groups over time to observe outcomes.","kind":"recall","origin":"ai"},{"id":"ers-evidence-based-medicine~ai-5","moduleId":"ers-evidence-based-medicine","stem":"How does the GRADE system handle the separation of evidence certainty and recommendation strength?","options":[{"id":"a","text":"It ties them directly together"},{"id":"b","text":"It separates them, allowing strong recommendations on low-certainty evidence"},{"id":"c","text":"It only allows strong recommendations on high-certainty evidence"},{"id":"d","text":"It does not consider recommendation strength"}],"answerId":"b","explanation":"GRADE separates evidence certainty from recommendation strength, allowing for strong recommendations even with low-certainty evidence.","kind":"mechanism","origin":"ai"},{"id":"ers-evidence-based-medicine~ai-6","moduleId":"ers-evidence-based-medicine","stem":"In the context of cancer staging, which study design is most appropriate for determining the frequency of a specific cancer stage in a population?","options":[{"id":"a","text":"Randomized controlled trial"},{"id":"b","text":"Cohort study"},{"id":"c","text":"Cross-sectional study"},{"id":"d","text":"Case-control study"}],"answerId":"c","explanation":"Cross-sectional studies are used to determine the frequency or prevalence of a condition at a specific point in time.","kind":"integration","linkedModuleIds":["cancer-spread-staging-clinical"],"origin":"ai"},{"id":"ers-evidence-based-medicine~ai-7","moduleId":"ers-evidence-based-medicine","stem":"When developing a research question using the PICO framework, which element is crucial for determining the intervention?","options":[{"id":"a","text":"Population"},{"id":"b","text":"Intervention"},{"id":"c","text":"Comparison"},{"id":"d","text":"Outcome"}],"answerId":"b","explanation":"The 'Intervention' component of PICO specifies the treatment or action being considered.","kind":"integration","linkedModuleIds":["research-question-finer-pico"],"origin":"ai"}],"add-systematic-error-and-bias-in-research":[{"id":"add-systematic-error-and-bias-in-research~ai-0","moduleId":"add-systematic-error-and-bias-in-research","stem":"Which type of bias is most likely to occur if the study participants are aware they are being observed and change their behavior as a result?","options":[{"id":"a","text":"Hawthorne effect"},{"id":"b","text":"Observer bias"},{"id":"c","text":"Detection bias"},{"id":"d","text":"Selection bias"}],"answerId":"a","explanation":"The Hawthorne effect describes changes in behavior when subjects know they are being observed.","kind":"recall","origin":"ai"},{"id":"add-systematic-error-and-bias-in-research~ai-1","moduleId":"add-systematic-error-and-bias-in-research","stem":"In a case-control study, cases are more likely to recall past exposures than controls. What type of bias does this represent?","options":[{"id":"a","text":"Selection bias"},{"id":"b","text":"Recall bias"},{"id":"c","text":"Observer bias"},{"id":"d","text":"Detection bias"}],"answerId":"b","explanation":"Recall bias occurs when there is a differential accuracy of recall between cases and controls.","kind":"mechanism","origin":"ai"},{"id":"add-systematic-error-and-bias-in-research~ai-2","moduleId":"add-systematic-error-and-bias-in-research","stem":"A study on the effects of a new drug fails to account for the fact that patients with more severe disease are more likely to receive the drug. What type of bias is this?","options":[{"id":"a","text":"Confounding"},{"id":"b","text":"Selection bias"},{"id":"c","text":"Information bias"},{"id":"d","text":"Detection bias"}],"answerId":"a","explanation":"Confounding occurs when an extraneous variable is associated with both the exposure and the outcome.","kind":"trap","origin":"ai"},{"id":"add-systematic-error-and-bias-in-research~ai-3","moduleId":"add-systematic-error-and-bias-in-research","stem":"In a clinical trial, the knowledge of which group a participant belongs to influences the outcome assessment. Which bias is this?","options":[{"id":"a","text":"Observer bias"},{"id":"b","text":"Detection bias"},{"id":"c","text":"Selection bias"},{"id":"d","text":"Publication bias"}],"answerId":"b","explanation":"Detection bias happens when knowledge of exposure status influences the assessment of the outcome.","kind":"clinical","origin":"ai"},{"id":"add-systematic-error-and-bias-in-research~ai-4","moduleId":"add-systematic-error-and-bias-in-research","stem":"A study on Down syndrome prevalence is conducted without considering maternal age. Which linked module could provide insights into this oversight?","options":[{"id":"a","text":"Numerical chromosome abnormalities"},{"id":"b","text":"Mosaicism & Chimerism"},{"id":"c","text":"Adaptive Clinical Trial Designs"},{"id":"d","text":"Advanced Regression Techniques"}],"answerId":"a","explanation":"Numerical chromosome abnormalities, such as those seen in Down syndrome, are influenced by maternal age.","kind":"integration","linkedModuleIds":["numerical-chromosome-abnormalities"],"origin":"ai"},{"id":"add-systematic-error-and-bias-in-research~ai-5","moduleId":"add-systematic-error-and-bias-in-research","stem":"In a study using adaptive clinical trial designs, how might systematic error be minimized?","options":[{"id":"a","text":"Blinding assessors to treatment allocation"},{"id":"b","text":"Increasing sample size"},{"id":"c","text":"Using historical controls"},{"id":"d","text":"Publishing only positive results"}],"answerId":"a","explanation":"Blinding assessors helps reduce observer and detection biases, minimizing systematic error.","kind":"integration","linkedModuleIds":["add-adaptive-clinical-trial-designs"],"origin":"ai"}],"add-data-management-and-quality-control":[{"id":"add-data-management-and-quality-control~ai-0","moduleId":"add-data-management-and-quality-control","stem":"What is the primary purpose of data cleaning in data management?","options":[{"id":"a","text":"To identify and correct errors in a dataset"},{"id":"b","text":"To encrypt data for security"},{"id":"c","text":"To perform statistical analysis"},{"id":"d","text":"To create data visualizations"}],"answerId":"a","explanation":"Data cleaning ensures the accuracy and reliability of the dataset by identifying and correcting errors.","kind":"recall","origin":"ai"},{"id":"add-data-management-and-quality-control~ai-1","moduleId":"add-data-management-and-quality-control","stem":"Which method is commonly used to handle missing data in datasets?","options":[{"id":"a","text":"Ignoring the missing data"},{"id":"b","text":"Imputation"},{"id":"c","text":"Increasing sample size"},{"id":"d","text":"Random deletion"}],"answerId":"b","explanation":"Imputation is a method used to estimate and fill in missing data, preserving dataset integrity.","kind":"mechanism","origin":"ai"},{"id":"add-data-management-and-quality-control~ai-2","moduleId":"add-data-management-and-quality-control","stem":"A dataset shows a high rate of missing data. What does this most likely indicate?","options":[{"id":"a","text":"Effective data security measures"},{"id":"b","text":"Poor data collection processes"},{"id":"c","text":"Successful data validation"},{"id":"d","text":"Comprehensive data cleaning"}],"answerId":"b","explanation":"A high rate of missing data often suggests issues in the data collection process.","kind":"clinical","origin":"ai"},{"id":"add-data-management-and-quality-control~ai-3","moduleId":"add-data-management-and-quality-control","stem":"In data management, what is the role of Standard Operating Procedures (SOPs)?","options":[{"id":"a","text":"To ensure consistency in data handling"},{"id":"b","text":"To encrypt data for security"},{"id":"c","text":"To analyze data trends"},{"id":"d","text":"To visualize data"}],"answerId":"a","explanation":"SOPs provide a standardized approach to data handling, ensuring consistency and reliability.","kind":"recall","origin":"ai"},{"id":"add-data-management-and-quality-control~ai-4","moduleId":"add-data-management-and-quality-control","stem":"Which of the following is a critical aspect of data security and confidentiality?","options":[{"id":"a","text":"Data visualization"},{"id":"b","text":"Access control measures"},{"id":"c","text":"Data imputation"},{"id":"d","text":"Data cleaning"}],"answerId":"b","explanation":"Access control measures are essential to protect data from unauthorized access and ensure confidentiality.","kind":"recall","origin":"ai"},{"id":"add-data-management-and-quality-control~ai-5","moduleId":"add-data-management-and-quality-control","stem":"Inconsistent data entries in a dataset suggest a lack of what?","options":[{"id":"a","text":"Data encryption"},{"id":"b","text":"Validation checks"},{"id":"c","text":"Data visualization"},{"id":"d","text":"Sample size"}],"answerId":"b","explanation":"Inconsistent entries indicate that validation checks are not effectively identifying errors.","kind":"mechanism","origin":"ai"},{"id":"add-data-management-and-quality-control~ai-6","moduleId":"add-data-management-and-quality-control","stem":"How does adaptive clinical trial design relate to data management?","options":[{"id":"a","text":"It requires real-time data analysis and management"},{"id":"b","text":"It focuses solely on data encryption"},{"id":"c","text":"It eliminates the need for data validation"},{"id":"d","text":"It avoids the use of SOPs"}],"answerId":"a","explanation":"Adaptive clinical trials rely on real-time data management to adjust trial parameters based on interim results.","kind":"integration","linkedModuleIds":["add-adaptive-clinical-trial-designs"],"origin":"ai"},{"id":"add-data-management-and-quality-control~ai-7","moduleId":"add-data-management-and-quality-control","stem":"Which advanced regression technique can be used to handle datasets with missing data?","options":[{"id":"a","text":"Linear regression"},{"id":"b","text":"Logistic regression"},{"id":"c","text":"Multiple imputation"},{"id":"d","text":"ANOVA"}],"answerId":"c","explanation":"Multiple imputation is an advanced technique used to handle missing data in regression analysis.","kind":"integration","linkedModuleIds":["add-advanced-regression-techniques"],"origin":"ai"}],"add-survival-analysis-techniques":[{"id":"add-survival-analysis-techniques~ai-0","moduleId":"add-survival-analysis-techniques","stem":"Which method is used to estimate survival probabilities over time and can handle censored data?","options":[{"id":"a","text":"Kaplan-Meier curves"},{"id":"b","text":"Cox proportional hazards model"},{"id":"c","text":"Log-rank test"},{"id":"d","text":"Schoenfeld residuals"}],"answerId":"a","explanation":"Kaplan-Meier curves are used to estimate survival probabilities and can handle censored data.","kind":"recall","origin":"ai"},{"id":"add-survival-analysis-techniques~ai-1","moduleId":"add-survival-analysis-techniques","stem":"What does a plateau in a Kaplan-Meier curve indicate?","options":[{"id":"a","text":"Increasing hazard"},{"id":"b","text":"No events occurring"},{"id":"c","text":"Decreasing survival probability"},{"id":"d","text":"Crossing survival curves"}],"answerId":"b","explanation":"A plateau in a Kaplan-Meier curve indicates no events occurring after a certain time point.","kind":"mechanism","origin":"ai"},{"id":"add-survival-analysis-techniques~ai-2","moduleId":"add-survival-analysis-techniques","stem":"In survival analysis, which test is used to compare survival distributions between two groups?","options":[{"id":"a","text":"Log-rank test"},{"id":"b","text":"Cox proportional hazards model"},{"id":"c","text":"Kaplan-Meier curves"},{"id":"d","text":"Schoenfeld residuals"}],"answerId":"a","explanation":"The log-rank test compares survival distributions between two groups.","kind":"recall","origin":"ai"},{"id":"add-survival-analysis-techniques~ai-3","moduleId":"add-survival-analysis-techniques","stem":"A researcher finds crossing survival curves in their study. What does this suggest?","options":[{"id":"a","text":"Proportional hazards assumption is valid"},{"id":"b","text":"Non-proportional hazards"},{"id":"c","text":"Censoring is not handled"},{"id":"d","text":"Median survival time is reached"}],"answerId":"b","explanation":"Crossing survival curves suggest non-proportional hazards.","kind":"clinical","origin":"ai"},{"id":"add-survival-analysis-techniques~ai-4","moduleId":"add-survival-analysis-techniques","stem":"Which statistical assumption is crucial for the Cox proportional hazards model?","options":[{"id":"a","text":"Normal distribution"},{"id":"b","text":"Proportional hazards"},{"id":"c","text":"Equal variance"},{"id":"d","text":"Linearity"}],"answerId":"b","explanation":"The Cox model assumes proportional hazards, which can be checked using Schoenfeld residuals.","kind":"trap","origin":"ai"},{"id":"add-survival-analysis-techniques~ai-5","moduleId":"add-survival-analysis-techniques","stem":"How can the assumption of proportional hazards in a Cox model be checked?","options":[{"id":"a","text":"Using Kaplan-Meier curves"},{"id":"b","text":"Using Schoenfeld residuals"},{"id":"c","text":"Using log-rank test"},{"id":"d","text":"Using median survival time"}],"answerId":"b","explanation":"Schoenfeld residuals are used to check the proportional hazards assumption in a Cox model.","kind":"mechanism","origin":"ai"},{"id":"add-survival-analysis-techniques~ai-6","moduleId":"add-survival-analysis-techniques","stem":"Which of the following is a key difference between survival analysis and qualitative research methods?","options":[{"id":"a","text":"Survival analysis handles time-to-event data"},{"id":"b","text":"Qualitative research uses Kaplan-Meier curves"},{"id":"c","text":"Survival analysis is subjective"},{"id":"d","text":"Qualitative research calculates hazard ratios"}],"answerId":"a","explanation":"Survival analysis models time-to-event data, unlike qualitative research methods.","kind":"integration","linkedModuleIds":["add-qualitative-research-methods-techniques-and-analysis"],"origin":"ai"},{"id":"add-survival-analysis-techniques~ai-7","moduleId":"add-survival-analysis-techniques","stem":"In adaptive clinical trial designs, how might survival analysis be integrated?","options":[{"id":"a","text":"By adjusting sample size based on interim results"},{"id":"b","text":"By using qualitative interviews"},{"id":"c","text":"By ignoring censored data"},{"id":"d","text":"By assuming non-proportional hazards"}],"answerId":"a","explanation":"Adaptive designs can use survival analysis to adjust sample size based on interim results.","kind":"integration","linkedModuleIds":["add-adaptive-clinical-trial-designs"],"origin":"ai"}],"add-advanced-regression-techniques":[{"id":"add-advanced-regression-techniques~ai-0","moduleId":"add-advanced-regression-techniques","stem":"Which regression technique is most appropriate for modeling a binary outcome variable?","options":[{"id":"a","text":"Linear regression"},{"id":"b","text":"Logistic regression"},{"id":"c","text":"Ridge regression"},{"id":"d","text":"Lasso regression"}],"answerId":"b","explanation":"Logistic regression is used for binary outcome variables, providing odds ratios for predictors.","kind":"recall","origin":"ai"},{"id":"add-advanced-regression-techniques~ai-1","moduleId":"add-advanced-regression-techniques","stem":"What does a high variance inflation factor (VIF) indicate in a regression model?","options":[{"id":"a","text":"Homoscedasticity"},{"id":"b","text":"Multicollinearity"},{"id":"c","text":"Non-linearity"},{"id":"d","text":"Model overfitting"}],"answerId":"b","explanation":"A high VIF indicates multicollinearity among predictors, affecting model stability.","kind":"mechanism","origin":"ai"},{"id":"add-advanced-regression-techniques~ai-2","moduleId":"add-advanced-regression-techniques","stem":"A researcher uses linear regression to predict a binary outcome. What is the main issue with this approach?","options":[{"id":"a","text":"Model overfitting"},{"id":"b","text":"Incorrect model choice"},{"id":"c","text":"Multicollinearity"},{"id":"d","text":"Non-linearity"}],"answerId":"b","explanation":"Using linear regression for binary outcomes is incorrect; logistic regression should be used.","kind":"trap","origin":"ai"},{"id":"add-advanced-regression-techniques~ai-3","moduleId":"add-advanced-regression-techniques","stem":"In a linear regression model, which analysis checks for homoscedasticity and normality of errors?","options":[{"id":"a","text":"Residual analysis"},{"id":"b","text":"Variance analysis"},{"id":"c","text":"Factor analysis"},{"id":"d","text":"Sensitivity analysis"}],"answerId":"a","explanation":"Residual analysis checks for homoscedasticity and normality of errors in linear regression.","kind":"recall","origin":"ai"},{"id":"add-advanced-regression-techniques~ai-4","moduleId":"add-advanced-regression-techniques","stem":"Which technique can be used to address multicollinearity by adding penalty terms to the regression model?","options":[{"id":"a","text":"Logistic regression"},{"id":"b","text":"Ridge regression"},{"id":"c","text":"Linear regression"},{"id":"d","text":"Polynomial regression"}],"answerId":"b","explanation":"Ridge regression adds penalty terms to address multicollinearity.","kind":"recall","origin":"ai"},{"id":"add-advanced-regression-techniques~ai-5","moduleId":"add-advanced-regression-techniques","stem":"How does the presence of interaction terms in a regression model affect the analysis?","options":[{"id":"a","text":"It increases the model's R-squared value"},{"id":"b","text":"It assesses if the effect of one variable depends on another"},{"id":"c","text":"It reduces multicollinearity"},{"id":"d","text":"It simplifies the model"}],"answerId":"b","explanation":"Interaction terms assess whether the effect of one variable depends on another.","kind":"mechanism","origin":"ai"},{"id":"add-advanced-regression-techniques~ai-6","moduleId":"add-advanced-regression-techniques","stem":"In the context of advanced regression techniques, how might Bayesian analysis be integrated to improve model predictions?","options":[{"id":"a","text":"By using prior distributions to inform parameter estimates"},{"id":"b","text":"By simplifying the model structure"},{"id":"c","text":"By eliminating multicollinearity"},{"id":"d","text":"By converting binary outcomes to continuous"}],"answerId":"a","explanation":"Bayesian analysis uses prior distributions to inform parameter estimates, potentially improving predictions.","kind":"integration","linkedModuleIds":["add-bayesian-analysis-in-medical-research"],"origin":"ai"},{"id":"add-advanced-regression-techniques~ai-7","moduleId":"add-advanced-regression-techniques","stem":"Which regression technique could be most beneficial in an adaptive clinical trial design to adjust for time-varying covariates?","options":[{"id":"a","text":"Logistic regression"},{"id":"b","text":"Ridge regression"},{"id":"c","text":"Lasso regression"},{"id":"d","text":"Linear regression"}],"answerId":"c","explanation":"Lasso regression can handle variable selection and adjust for time-varying covariates in adaptive designs.","kind":"integration","linkedModuleIds":["add-adaptive-clinical-trial-designs"],"origin":"ai"}],"add-ethical-considerations-in-genetic-research":[{"id":"add-ethical-considerations-in-genetic-research~ai-0","moduleId":"add-ethical-considerations-in-genetic-research","stem":"What is a primary ethical concern when conducting genetic research involving family members?","options":[{"id":"a","text":"Informed consent from all family members"},{"id":"b","text":"Potential for genetic enhancement"},{"id":"c","text":"Cost of genetic testing"},{"id":"d","text":"Speed of data analysis"}],"answerId":"a","explanation":"Informed consent is crucial due to the potential implications for family members who may be affected by the genetic information.","kind":"recall","origin":"ai"},{"id":"add-ethical-considerations-in-genetic-research~ai-1","moduleId":"add-ethical-considerations-in-genetic-research","stem":"Which act protects individuals in the United States from genetic discrimination in employment and insurance?","options":[{"id":"a","text":"Health Insurance Portability and Accountability Act (HIPAA)"},{"id":"b","text":"Genetic Information Nondiscrimination Act (GINA)"},{"id":"c","text":"Americans with Disabilities Act (ADA)"},{"id":"d","text":"Patient Protection and Affordable Care Act (ACA)"}],"answerId":"b","explanation":"The Genetic Information Nondiscrimination Act (GINA) protects individuals from genetic discrimination in employment and insurance.","kind":"recall","origin":"ai"},{"id":"add-ethical-considerations-in-genetic-research~ai-2","moduleId":"add-ethical-considerations-in-genetic-research","stem":"A participant expresses reluctance to join a genetic study due to privacy concerns. What is the most likely underlying reason?","options":[{"id":"a","text":"Fear of genetic enhancement"},{"id":"b","text":"Fear of genetic discrimination"},{"id":"c","text":"Lack of interest in research"},{"id":"d","text":"Concerns about study duration"}],"answerId":"b","explanation":"Participants often fear genetic discrimination and privacy breaches, leading to reluctance in joining genetic studies.","kind":"clinical","origin":"ai"},{"id":"add-ethical-considerations-in-genetic-research~ai-3","moduleId":"add-ethical-considerations-in-genetic-research","stem":"In genetic research, why is it important to manage incidental findings according to ethical guidelines?","options":[{"id":"a","text":"To ensure rapid publication of results"},{"id":"b","text":"To protect the privacy and autonomy of participants"},{"id":"c","text":"To increase the sample size"},{"id":"d","text":"To reduce research costs"}],"answerId":"b","explanation":"Managing incidental findings ethically protects participants' privacy and autonomy, ensuring they are informed about findings that may affect them.","kind":"mechanism","origin":"ai"},{"id":"add-ethical-considerations-in-genetic-research~ai-4","moduleId":"add-ethical-considerations-in-genetic-research","stem":"In the context of genetic research, why is specific consent required for each study?","options":[{"id":"a","text":"To comply with international law"},{"id":"b","text":"To prevent data loss"},{"id":"c","text":"To ensure ethical compliance"},{"id":"d","text":"To increase participant numbers"}],"answerId":"c","explanation":"Specific consent for each study is necessary to ensure ethical compliance, as consent must be relevant to the specific research being conducted.","kind":"trap","origin":"ai"},{"id":"add-ethical-considerations-in-genetic-research~ai-5","moduleId":"add-ethical-considerations-in-genetic-research","stem":"How does community engagement benefit genetic research involving specific populations?","options":[{"id":"a","text":"Increases the speed of data collection"},{"id":"b","text":"Ensures cultural sensitivity and relevance"},{"id":"c","text":"Reduces the need for informed consent"},{"id":"d","text":"Decreases research costs"}],"answerId":"b","explanation":"Community engagement ensures that research is culturally sensitive and relevant, fostering trust and cooperation.","kind":"mechanism","origin":"ai"},{"id":"add-ethical-considerations-in-genetic-research~ai-6","moduleId":"add-ethical-considerations-in-genetic-research","stem":"In the context of genetic research, how can adaptive clinical trial designs enhance ethical considerations?","options":[{"id":"a","text":"By reducing the need for informed consent"},{"id":"b","text":"By allowing for dynamic consent processes"},{"id":"c","text":"By eliminating incidental findings"},{"id":"d","text":"By ensuring all participants receive the same treatment"}],"answerId":"b","explanation":"Adaptive clinical trial designs can incorporate dynamic consent processes, allowing participants to update their consent as the study evolves.","kind":"integration","linkedModuleIds":["add-adaptive-clinical-trial-designs"],"origin":"ai"},{"id":"add-ethical-considerations-in-genetic-research~ai-7","moduleId":"add-ethical-considerations-in-genetic-research","stem":"How might advanced regression techniques be ethically applied in genetic research?","options":[{"id":"a","text":"To identify genetic predispositions without consent"},{"id":"b","text":"To enhance data privacy and security"},{"id":"c","text":"To manipulate study outcomes"},{"id":"d","text":"To reduce the need for participant recruitment"}],"answerId":"b","explanation":"Advanced regression techniques can be used to enhance data privacy and security, ensuring ethical handling of sensitive genetic information.","kind":"integration","linkedModuleIds":["add-advanced-regression-techniques"],"origin":"ai"}],"add-handling-missing-data-in-research":[{"id":"add-handling-missing-data-in-research~ai-0","moduleId":"add-handling-missing-data-in-research","stem":"What type of missing data occurs when the probability of missingness is unrelated to the observed or unobserved data?","options":[{"id":"a","text":"MCAR (Missing Completely at Random)"},{"id":"b","text":"MAR (Missing at Random)"},{"id":"c","text":"MNAR (Missing Not at Random)"},{"id":"d","text":"MNAR (Missing Not at Random)"}],"answerId":"a","explanation":"MCAR occurs when missingness is completely independent of any data.","kind":"recall","origin":"ai"},{"id":"add-handling-missing-data-in-research~ai-1","moduleId":"add-handling-missing-data-in-research","stem":"Which method involves creating several complete datasets to estimate missing values?","options":[{"id":"a","text":"Listwise deletion"},{"id":"b","text":"Mean imputation"},{"id":"c","text":"Multiple imputation"},{"id":"d","text":"Pairwise deletion"}],"answerId":"c","explanation":"Multiple imputation generates multiple datasets to account for uncertainty in missing data.","kind":"mechanism","origin":"ai"},{"id":"add-handling-missing-data-in-research~ai-2","moduleId":"add-handling-missing-data-in-research","stem":"What is a potential drawback of using listwise deletion to handle missing data?","options":[{"id":"a","text":"Increases sample size"},{"id":"b","text":"Introduces bias"},{"id":"c","text":"Reduces sample size"},{"id":"d","text":"Improves data accuracy"}],"answerId":"c","explanation":"Listwise deletion can significantly reduce the sample size by removing all data for cases with any missing values.","kind":"trap","origin":"ai"},{"id":"add-handling-missing-data-in-research~ai-3","moduleId":"add-handling-missing-data-in-research","stem":"Which test can be used to assess if data is missing completely at random?","options":[{"id":"a","text":"Little's MCAR test"},{"id":"b","text":"Chi-square test"},{"id":"c","text":"T-test"},{"id":"d","text":"ANOVA"}],"answerId":"a","explanation":"Little's MCAR test is specifically designed to test for MCAR.","kind":"recall","origin":"ai"},{"id":"add-handling-missing-data-in-research~ai-4","moduleId":"add-handling-missing-data-in-research","stem":"In a study using adaptive clinical trial designs, how might missing data affect the trial's flexibility?","options":[{"id":"a","text":"Increases flexibility"},{"id":"b","text":"Decreases flexibility"},{"id":"c","text":"Has no effect"},{"id":"d","text":"Improves accuracy"}],"answerId":"b","explanation":"Missing data can complicate the adaptation process, reducing the trial's flexibility.","kind":"integration","linkedModuleIds":["add-adaptive-clinical-trial-designs"],"origin":"ai"},{"id":"add-handling-missing-data-in-research~ai-5","moduleId":"add-handling-missing-data-in-research","stem":"How might NK cell activity be misinterpreted in a study with missing data on immune markers?","options":[{"id":"a","text":"Overestimated due to MCAR"},{"id":"b","text":"Underestimated due to MAR"},{"id":"c","text":"Accurately estimated"},{"id":"d","text":"Overestimated due to MNAR"}],"answerId":"b","explanation":"If missing data is MAR, it could lead to an underestimation of NK cell activity.","kind":"integration","linkedModuleIds":["innate-nk-interferon"],"origin":"ai"}],"add-bayesian-analysis-in-medical-research":[{"id":"add-bayesian-analysis-in-medical-research~ai-0","moduleId":"add-bayesian-analysis-in-medical-research","stem":"What is the primary purpose of incorporating prior probabilities in Bayesian analysis?","options":[{"id":"a","text":"To update the probability of a hypothesis with new data"},{"id":"b","text":"To calculate the mean of a dataset"},{"id":"c","text":"To eliminate bias in data collection"},{"id":"d","text":"To ensure data is normally distributed"}],"answerId":"a","explanation":"Bayesian analysis uses prior probabilities to update the probability of a hypothesis with new data.","kind":"recall","origin":"ai"},{"id":"add-bayesian-analysis-in-medical-research~ai-1","moduleId":"add-bayesian-analysis-in-medical-research","stem":"Which of the following best describes a Bayesian credible interval?","options":[{"id":"a","text":"A range where the parameter lies with a certain probability"},{"id":"b","text":"A range where the parameter lies 95% of the time"},{"id":"c","text":"A range that excludes outliers"},{"id":"d","text":"A range that maximizes the likelihood function"}],"answerId":"a","explanation":"Bayesian credible intervals provide a probability-based range, unlike frequentist confidence intervals.","kind":"trap","origin":"ai"},{"id":"add-bayesian-analysis-in-medical-research~ai-2","moduleId":"add-bayesian-analysis-in-medical-research","stem":"In Bayesian analysis, what does the posterior probability represent?","options":[{"id":"a","text":"The probability of data given the hypothesis"},{"id":"b","text":"The updated probability of the hypothesis after considering new data"},{"id":"c","text":"The initial probability before considering new data"},{"id":"d","text":"The probability of the hypothesis being false"}],"answerId":"b","explanation":"The posterior probability is the updated probability of the hypothesis after incorporating new data.","kind":"recall","origin":"ai"},{"id":"add-bayesian-analysis-in-medical-research~ai-3","moduleId":"add-bayesian-analysis-in-medical-research","stem":"Which method is commonly used in Bayesian analysis to approximate distributions?","options":[{"id":"a","text":"Maximum likelihood estimation"},{"id":"b","text":"Markov Chain Monte Carlo"},{"id":"c","text":"Linear regression"},{"id":"d","text":"ANOVA"}],"answerId":"b","explanation":"Markov Chain Monte Carlo (MCMC) methods are used to approximate distributions in Bayesian analysis.","kind":"recall","origin":"ai"},{"id":"add-bayesian-analysis-in-medical-research~ai-4","moduleId":"add-bayesian-analysis-in-medical-research","stem":"How does Bayesian analysis adjust pre-test probabilities in diagnostic testing?","options":[{"id":"a","text":"By using frequentist confidence intervals"},{"id":"b","text":"By incorporating test results to update probabilities"},{"id":"c","text":"By assuming equal probabilities for all outcomes"},{"id":"d","text":"By ignoring prior probabilities"}],"answerId":"b","explanation":"Bayesian analysis adjusts pre-test probabilities by incorporating test results to update the probability of a condition.","kind":"mechanism","origin":"ai"},{"id":"add-bayesian-analysis-in-medical-research~ai-5","moduleId":"add-bayesian-analysis-in-medical-research","stem":"In the context of adaptive clinical trial designs, how can Bayesian analysis be beneficial?","options":[{"id":"a","text":"It allows for fixed sample sizes"},{"id":"b","text":"It enables real-time updating of trial probabilities"},{"id":"c","text":"It ensures all trials have equal sample sizes"},{"id":"d","text":"It eliminates the need for control groups"}],"answerId":"b","explanation":"Bayesian analysis allows for real-time updating of trial probabilities, which is beneficial in adaptive clinical trial designs.","kind":"integration","linkedModuleIds":["add-adaptive-clinical-trial-designs"],"origin":"ai"},{"id":"add-bayesian-analysis-in-medical-research~ai-6","moduleId":"add-bayesian-analysis-in-medical-research","stem":"Which aspect of Bayesian analysis can be integrated with advanced regression techniques to improve model predictions?","options":[{"id":"a","text":"Using prior distributions to inform model parameters"},{"id":"b","text":"Assuming linearity in all relationships"},{"id":"c","text":"Ignoring prior data to avoid bias"},{"id":"d","text":"Focusing solely on p-values for significance"}],"answerId":"a","explanation":"Bayesian analysis can use prior distributions to inform model parameters, enhancing predictions in regression models.","kind":"integration","linkedModuleIds":["add-advanced-regression-techniques"],"origin":"ai"}],"add-machine-learning-in-medical-research":[{"id":"add-machine-learning-in-medical-research~ai-0","moduleId":"add-machine-learning-in-medical-research","stem":"Which type of machine learning algorithm is most appropriate for classifying medical images based on labeled data?","options":[{"id":"a","text":"Supervised learning"},{"id":"b","text":"Unsupervised learning"},{"id":"c","text":"Reinforcement learning"},{"id":"d","text":"Semi-supervised learning"}],"answerId":"a","explanation":"Supervised learning uses labeled data to train models, making it suitable for classification tasks like medical imaging.","kind":"recall","origin":"ai"},{"id":"add-machine-learning-in-medical-research~ai-1","moduleId":"add-machine-learning-in-medical-research","stem":"A model shows high accuracy on the training dataset but performs poorly on the test dataset. What is the most likely issue?","options":[{"id":"a","text":"Underfitting"},{"id":"b","text":"Overfitting"},{"id":"c","text":"Correct model complexity"},{"id":"d","text":"Insufficient data"}],"answerId":"b","explanation":"High training accuracy but low test accuracy indicates overfitting, where the model learns noise instead of the signal.","kind":"mechanism","origin":"ai"},{"id":"add-machine-learning-in-medical-research~ai-2","moduleId":"add-machine-learning-in-medical-research","stem":"What is the primary purpose of cross-validation in machine learning?","options":[{"id":"a","text":"To increase model complexity"},{"id":"b","text":"To assess model generalizability"},{"id":"c","text":"To reduce training time"},{"id":"d","text":"To eliminate noise from data"}],"answerId":"b","explanation":"Cross-validation is used to assess the predictive performance and generalizability of a model.","kind":"recall","origin":"ai"},{"id":"add-machine-learning-in-medical-research~ai-3","moduleId":"add-machine-learning-in-medical-research","stem":"In the context of machine learning, why is feature selection important?","options":[{"id":"a","text":"To increase the number of features"},{"id":"b","text":"To reduce overfitting"},{"id":"c","text":"To ensure model bias"},{"id":"d","text":"To enhance noise in data"}],"answerId":"b","explanation":"Feature selection reduces the dimensionality of the data, which helps in preventing overfitting.","kind":"mechanism","origin":"ai"},{"id":"add-machine-learning-in-medical-research~ai-4","moduleId":"add-machine-learning-in-medical-research","stem":"How does synaptic plasticity relate to machine learning algorithms?","options":[{"id":"a","text":"Both involve fixed pathways"},{"id":"b","text":"Both adapt based on experience"},{"id":"c","text":"Both are static processes"},{"id":"d","text":"Both require labeled data"}],"answerId":"b","explanation":"Synaptic plasticity and machine learning algorithms both adapt and improve based on experience.","kind":"integration","linkedModuleIds":["synaptic-plasticity-learning"],"origin":"ai"},{"id":"add-machine-learning-in-medical-research~ai-5","moduleId":"add-machine-learning-in-medical-research","stem":"What is a common pitfall when evaluating a machine learning model?","options":[{"id":"a","text":"Using only training data for evaluation"},{"id":"b","text":"Using both training and test data"},{"id":"c","text":"Using cross-validation"},{"id":"d","text":"Using a validation set"}],"answerId":"a","explanation":"Evaluating a model only on training data can lead to overfitting and does not assess generalizability.","kind":"trap","origin":"ai"},{"id":"add-machine-learning-in-medical-research~ai-6","moduleId":"add-machine-learning-in-medical-research","stem":"In adaptive clinical trial designs, how can machine learning be utilized?","options":[{"id":"a","text":"To fix trial endpoints"},{"id":"b","text":"To adaptively modify trial parameters"},{"id":"c","text":"To eliminate control groups"},{"id":"d","text":"To ensure static trial design"}],"answerId":"b","explanation":"Machine learning can be used to adaptively modify trial parameters based on interim data analysis.","kind":"integration","linkedModuleIds":["add-adaptive-clinical-trial-designs"],"origin":"ai"}],"add-data-visualization-in-medical-research":[{"id":"add-data-visualization-in-medical-research~ai-0","moduleId":"add-data-visualization-in-medical-research","stem":"Which type of data visualization is most appropriate for displaying the relationship between two continuous variables?","options":[{"id":"a","text":"Bar chart"},{"id":"b","text":"Histogram"},{"id":"c","text":"Scatter plot"},{"id":"d","text":"Pie chart"}],"answerId":"c","explanation":"A scatter plot is used to display the relationship between two continuous variables.","kind":"recall","origin":"ai"},{"id":"add-data-visualization-in-medical-research~ai-1","moduleId":"add-data-visualization-in-medical-research","stem":"What is a common pitfall when using pie charts in data visualization?","options":[{"id":"a","text":"They are difficult to create"},{"id":"b","text":"They can exaggerate differences"},{"id":"c","text":"They are not suitable for detailed comparisons"},{"id":"d","text":"They require complex data"}],"answerId":"c","explanation":"Pie charts are not suitable for detailed comparisons; bar charts are more effective for this purpose.","kind":"trap","origin":"ai"},{"id":"add-data-visualization-in-medical-research~ai-2","moduleId":"add-data-visualization-in-medical-research","stem":"A box plot is used to visualize which of the following aspects of a data set?","options":[{"id":"a","text":"Correlation between variables"},{"id":"b","text":"Frequency distribution"},{"id":"c","text":"Data distribution and outliers"},{"id":"d","text":"Time series trends"}],"answerId":"c","explanation":"A box plot provides a summary of a data set's distribution, highlighting the median, quartiles, and potential outliers.","kind":"recall","origin":"ai"},{"id":"add-data-visualization-in-medical-research~ai-3","moduleId":"add-data-visualization-in-medical-research","stem":"Which visualization would best highlight outliers in a data set?","options":[{"id":"a","text":"Line graph"},{"id":"b","text":"Box plot"},{"id":"c","text":"Scatter plot"},{"id":"d","text":"Histogram"}],"answerId":"b","explanation":"Box plots are effective at highlighting outliers in a data set.","kind":"clinical","origin":"ai"},{"id":"add-data-visualization-in-medical-research~ai-4","moduleId":"add-data-visualization-in-medical-research","stem":"In the context of adaptive clinical trial designs, which visualization would best illustrate the interim results over time?","options":[{"id":"a","text":"Box plot"},{"id":"b","text":"Line graph"},{"id":"c","text":"Scatter plot"},{"id":"d","text":"Pie chart"}],"answerId":"b","explanation":"Line graphs are ideal for showing changes over time, such as interim results in clinical trials.","kind":"integration","linkedModuleIds":["add-adaptive-clinical-trial-designs"],"origin":"ai"},{"id":"add-data-visualization-in-medical-research~ai-5","moduleId":"add-data-visualization-in-medical-research","stem":"When analyzing regression results, which visualization is most suitable for identifying the relationship between a predictor and response variable?","options":[{"id":"a","text":"Histogram"},{"id":"b","text":"Box plot"},{"id":"c","text":"Scatter plot"},{"id":"d","text":"Heat map"}],"answerId":"c","explanation":"A scatter plot is most suitable for identifying the relationship between a predictor and response variable in regression analysis.","kind":"integration","linkedModuleIds":["add-advanced-regression-techniques"],"origin":"ai"}],"add-ethical-considerations-in-clinical-trials":[{"id":"add-ethical-considerations-in-clinical-trials~ai-0","moduleId":"add-ethical-considerations-in-clinical-trials","stem":"What is the primary purpose of obtaining informed consent in clinical trials?","options":[{"id":"a","text":"To ensure participants understand the risks and benefits"},{"id":"b","text":"To comply with legal requirements"},{"id":"c","text":"To expedite the trial process"},{"id":"d","text":"To reduce the cost of the trial"}],"answerId":"a","explanation":"Informed consent ensures that participants are fully aware of the risks and benefits of the trial, allowing them to make an informed decision about their participation.","kind":"recall","origin":"ai"},{"id":"add-ethical-considerations-in-clinical-trials~ai-1","moduleId":"add-ethical-considerations-in-clinical-trials","stem":"Which document provides ethical guidelines for medical research involving human subjects?","options":[{"id":"a","text":"The Nuremberg Code"},{"id":"b","text":"The Declaration of Helsinki"},{"id":"c","text":"The Belmont Report"},{"id":"d","text":"The Universal Declaration of Human Rights"}],"answerId":"b","explanation":"The Declaration of Helsinki outlines ethical principles for conducting medical research involving human subjects.","kind":"recall","origin":"ai"},{"id":"add-ethical-considerations-in-clinical-trials~ai-2","moduleId":"add-ethical-considerations-in-clinical-trials","stem":"Why is it essential for clinical trials to undergo review by an Institutional Review Board (IRB)?","options":[{"id":"a","text":"To ensure scientific validity"},{"id":"b","text":"To confirm financial feasibility"},{"id":"c","text":"To provide ethical oversight"},{"id":"d","text":"To guarantee participant recruitment"}],"answerId":"c","explanation":"IRB review ensures that the trial is ethically sound and that participant rights and welfare are protected.","kind":"mechanism","origin":"ai"},{"id":"add-ethical-considerations-in-clinical-trials~ai-3","moduleId":"add-ethical-considerations-in-clinical-trials","stem":"In a clinical trial involving a vulnerable population, which additional measure is most important?","options":[{"id":"a","text":"Increased sample size"},{"id":"b","text":"Enhanced informed consent process"},{"id":"c","text":"Reduced trial duration"},{"id":"d","text":"Higher compensation for participants"}],"answerId":"b","explanation":"Vulnerable populations require additional protections, including an enhanced informed consent process to ensure understanding and voluntary participation.","kind":"clinical","origin":"ai"},{"id":"add-ethical-considerations-in-clinical-trials~ai-4","moduleId":"add-ethical-considerations-in-clinical-trials","stem":"Which principle requires that the potential benefits of a clinical trial outweigh the risks to participants?","options":[{"id":"a","text":"Autonomy"},{"id":"b","text":"Justice"},{"id":"c","text":"Beneficence"},{"id":"d","text":"Non-maleficence"}],"answerId":"c","explanation":"The principle of beneficence mandates that the benefits of the trial should outweigh any potential risks to the participants.","kind":"recall","origin":"ai"},{"id":"add-ethical-considerations-in-clinical-trials~ai-5","moduleId":"add-ethical-considerations-in-clinical-trials","stem":"In the context of genetic testing, why is informed consent particularly crucial?","options":[{"id":"a","text":"Genetic tests are always accurate"},{"id":"b","text":"Results can have significant implications for family members"},{"id":"c","text":"Genetic testing is inexpensive"},{"id":"d","text":"Results are always confidential"}],"answerId":"b","explanation":"Informed consent is crucial in genetic testing because results can affect not only the individual but also their family members, raising ethical considerations.","kind":"integration","linkedModuleIds":["add-genetic-testing-and-ethical-considerations"],"origin":"ai"},{"id":"add-ethical-considerations-in-clinical-trials~ai-6","moduleId":"add-ethical-considerations-in-clinical-trials","stem":"How does randomization in clinical trials contribute to ethical research conduct?","options":[{"id":"a","text":"It minimizes costs"},{"id":"b","text":"It ensures participant safety"},{"id":"c","text":"It reduces bias"},{"id":"d","text":"It guarantees positive outcomes"}],"answerId":"c","explanation":"Randomization reduces bias, ensuring that the trial results are scientifically valid and ethically sound.","kind":"mechanism","origin":"ai"},{"id":"add-ethical-considerations-in-clinical-trials~ai-7","moduleId":"add-ethical-considerations-in-clinical-trials","stem":"In adaptive clinical trial designs, what ethical consideration is most pertinent?","options":[{"id":"a","text":"Ensuring rapid participant recruitment"},{"id":"b","text":"Maintaining informed consent with protocol changes"},{"id":"c","text":"Maximizing sample size"},{"id":"d","text":"Guaranteeing placebo use"}],"answerId":"b","explanation":"In adaptive designs, maintaining informed consent is crucial as protocol changes may affect participant understanding and willingness to continue.","kind":"integration","linkedModuleIds":["add-adaptive-clinical-trial-designs"],"origin":"ai"}],"add-systematic-reviews-of-observational-studies":[{"id":"add-systematic-reviews-of-observational-studies~ai-0","moduleId":"add-systematic-reviews-of-observational-studies","stem":"Which guideline provides a framework for conducting systematic reviews of observational studies?","options":[{"id":"a","text":"MOOSE"},{"id":"b","text":"PRISMA"},{"id":"c","text":"CONSORT"},{"id":"d","text":"STROBE"}],"answerId":"a","explanation":"The MOOSE guidelines are specifically designed for systematic reviews of observational studies.","kind":"recall","origin":"ai"},{"id":"add-systematic-reviews-of-observational-studies~ai-1","moduleId":"add-systematic-reviews-of-observational-studies","stem":"In a systematic review of observational studies, what does an I² statistic greater than 50% indicate?","options":[{"id":"a","text":"Low heterogeneity"},{"id":"b","text":"High heterogeneity"},{"id":"c","text":"No heterogeneity"},{"id":"d","text":"Publication bias"}],"answerId":"b","explanation":"An I² statistic greater than 50% suggests high heterogeneity among the included studies.","kind":"mechanism","origin":"ai"},{"id":"add-systematic-reviews-of-observational-studies~ai-2","moduleId":"add-systematic-reviews-of-observational-studies","stem":"A funnel plot shows asymmetry in a systematic review of observational studies. What does this suggest?","options":[{"id":"a","text":"High heterogeneity"},{"id":"b","text":"Low study quality"},{"id":"c","text":"Publication bias"},{"id":"d","text":"Confounding"}],"answerId":"c","explanation":"Funnel plot asymmetry is indicative of publication bias, where studies with significant results are more likely to be published.","kind":"recall","origin":"ai"},{"id":"add-systematic-reviews-of-observational-studies~ai-3","moduleId":"add-systematic-reviews-of-observational-studies","stem":"Which tool is used to evaluate the risk of bias in observational studies included in a systematic review?","options":[{"id":"a","text":"Newcastle-Ottawa Scale"},{"id":"b","text":"Cochrane Risk of Bias Tool"},{"id":"c","text":"GRADE"},{"id":"d","text":"QUADAS"}],"answerId":"a","explanation":"The Newcastle-Ottawa Scale is specifically designed to assess the quality of observational studies.","kind":"recall","origin":"ai"},{"id":"add-systematic-reviews-of-observational-studies~ai-4","moduleId":"add-systematic-reviews-of-observational-studies","stem":"In systematic reviews, why might a large sample size not eliminate publication bias?","options":[{"id":"a","text":"Large samples increase heterogeneity"},{"id":"b","text":"Large samples reduce effect size"},{"id":"c","text":"Publication bias is unrelated to sample size"},{"id":"d","text":"Large samples increase confounding"}],"answerId":"c","explanation":"Publication bias is related to the tendency to publish significant results, not the sample size.","kind":"trap","origin":"ai"},{"id":"add-systematic-reviews-of-observational-studies~ai-5","moduleId":"add-systematic-reviews-of-observational-studies","stem":"How can systematic reviews of observational studies be integrated with advanced regression techniques to address confounding?","options":[{"id":"a","text":"By using meta-regression"},{"id":"b","text":"By excluding confounded studies"},{"id":"c","text":"By increasing sample size"},{"id":"d","text":"By using fixed-effects models"}],"answerId":"a","explanation":"Meta-regression can be used to explore and adjust for confounders in systematic reviews.","kind":"integration","linkedModuleIds":["add-advanced-regression-techniques"],"origin":"ai"},{"id":"add-systematic-reviews-of-observational-studies~ai-6","moduleId":"add-systematic-reviews-of-observational-studies","stem":"What is a common method to assess the robustness of findings in a systematic review of observational studies?","options":[{"id":"a","text":"Sensitivity analysis"},{"id":"b","text":"Randomization"},{"id":"c","text":"Blinding"},{"id":"d","text":"Cross-validation"}],"answerId":"a","explanation":"Sensitivity analyses are used to determine how results change with different assumptions or methods.","kind":"recall","origin":"ai"},{"id":"add-systematic-reviews-of-observational-studies~ai-7","moduleId":"add-systematic-reviews-of-observational-studies","stem":"How does the conduct of systematic reviews of observational studies relate to adaptive clinical trial designs?","options":[{"id":"a","text":"Both use randomization"},{"id":"b","text":"Both adjust for confounding"},{"id":"c","text":"Both can use interim analyses"},{"id":"d","text":"Both rely on observational data"}],"answerId":"c","explanation":"Adaptive clinical trial designs and systematic reviews can both incorporate interim analyses to modify study conduct.","kind":"integration","linkedModuleIds":["add-adaptive-clinical-trial-designs"],"origin":"ai"}],"add-qualitative-research-methods-in-medicine":[{"id":"add-qualitative-research-methods-in-medicine~ai-0","moduleId":"add-qualitative-research-methods-in-medicine","stem":"Which qualitative research methodology focuses on understanding the lived experiences of individuals?","options":[{"id":"a","text":"Phenomenology"},{"id":"b","text":"Grounded Theory"},{"id":"c","text":"Ethnography"},{"id":"d","text":"Narrative Research"}],"answerId":"a","explanation":"Phenomenology aims to explore and describe the lived experiences of individuals.","kind":"recall","origin":"ai"},{"id":"add-qualitative-research-methods-in-medicine~ai-1","moduleId":"add-qualitative-research-methods-in-medicine","stem":"What is the primary purpose of using triangulation in qualitative research?","options":[{"id":"a","text":"To increase sample size"},{"id":"b","text":"To enhance credibility"},{"id":"c","text":"To simplify data collection"},{"id":"d","text":"To ensure statistical significance"}],"answerId":"b","explanation":"Triangulation enhances the credibility of qualitative research by using multiple data sources, investigators, or methods.","kind":"mechanism","origin":"ai"},{"id":"add-qualitative-research-methods-in-medicine~ai-2","moduleId":"add-qualitative-research-methods-in-medicine","stem":"During thematic analysis, a researcher identifies a pattern that repeatedly appears in the data. What is this pattern called?","options":[{"id":"a","text":"Code"},{"id":"b","text":"Theme"},{"id":"c","text":"Variable"},{"id":"d","text":"Hypothesis"}],"answerId":"b","explanation":"In thematic analysis, a theme is a pattern that captures something significant about the data.","kind":"recall","origin":"ai"},{"id":"add-qualitative-research-methods-in-medicine~ai-3","moduleId":"add-qualitative-research-methods-in-medicine","stem":"Which of the following is a common trap when conducting qualitative research?","options":[{"id":"a","text":"Using thematic analysis"},{"id":"b","text":"Reaching data saturation"},{"id":"c","text":"Applying quantitative analysis"},{"id":"d","text":"Engaging in reflexivity"}],"answerId":"c","explanation":"Applying quantitative analysis is a trap as qualitative research focuses on themes, not numerical data.","kind":"trap","origin":"ai"},{"id":"add-qualitative-research-methods-in-medicine~ai-4","moduleId":"add-qualitative-research-methods-in-medicine","stem":"A researcher conducting a qualitative study on patient experiences in a hospital setting uses open-ended interviews. What exam finding is most likely to result from this method?","options":[{"id":"a","text":"Statistical significance"},{"id":"b","text":"Rich, detailed descriptions"},{"id":"c","text":"Numerical data"},{"id":"d","text":"Controlled variables"}],"answerId":"b","explanation":"Open-ended interviews in qualitative research typically yield rich, detailed descriptions.","kind":"clinical","origin":"ai"},{"id":"add-qualitative-research-methods-in-medicine~ai-5","moduleId":"add-qualitative-research-methods-in-medicine","stem":"How does the concept of saturation relate to data collection in qualitative research?","options":[{"id":"a","text":"It indicates the need for more data"},{"id":"b","text":"It marks the end of data collection"},{"id":"c","text":"It suggests a need for quantitative analysis"},{"id":"d","text":"It requires additional triangulation"}],"answerId":"b","explanation":"Saturation is reached when no new information or themes are observed, indicating sufficient data collection.","kind":"mechanism","origin":"ai"},{"id":"add-qualitative-research-methods-in-medicine~ai-6","moduleId":"add-qualitative-research-methods-in-medicine","stem":"In qualitative research, how does reflexivity contribute to the research process?","options":[{"id":"a","text":"By eliminating biases"},{"id":"b","text":"By reflecting on biases"},{"id":"c","text":"By increasing sample size"},{"id":"d","text":"By ensuring statistical analysis"}],"answerId":"b","explanation":"Reflexivity involves researchers reflecting on their own biases and how these might affect the research process.","kind":"mechanism","origin":"ai"},{"id":"add-qualitative-research-methods-in-medicine~ai-7","moduleId":"add-qualitative-research-methods-in-medicine","stem":"Which qualitative research method would be most appropriate for exploring the cultural practices of a specific community?","options":[{"id":"a","text":"Phenomenology"},{"id":"b","text":"Grounded Theory"},{"id":"c","text":"Ethnography"},{"id":"d","text":"Narrative Research"}],"answerId":"c","explanation":"Ethnography is used to study cultural practices and social interactions within specific communities.","kind":"recall","origin":"ai"},{"id":"add-qualitative-research-methods-in-medicine~ai-8","moduleId":"add-qualitative-research-methods-in-medicine","stem":"How might qualitative research methods enhance adaptive clinical trial designs?","options":[{"id":"a","text":"By providing statistical models"},{"id":"b","text":"By offering detailed patient perspectives"},{"id":"c","text":"By ensuring randomization"},{"id":"d","text":"By controlling variables"}],"answerId":"b","explanation":"Qualitative methods can provide detailed patient perspectives that inform adaptive trial designs.","kind":"integration","linkedModuleIds":["add-adaptive-clinical-trial-designs"],"origin":"ai"}],"add-cluster-randomized-trials":[{"id":"add-cluster-randomized-trials~ai-0","moduleId":"add-cluster-randomized-trials","stem":"What is a defining characteristic of cluster randomized trials (CRTs) compared to individually randomized trials?","options":[{"id":"a","text":"Randomization of groups or clusters"},{"id":"b","text":"Randomization of individual participants"},{"id":"c","text":"Use of placebo controls"},{"id":"d","text":"Blinding of participants"}],"answerId":"a","explanation":"CRTs randomize groups or clusters of individuals, not individual participants.","kind":"recall","origin":"ai"},{"id":"add-cluster-randomized-trials~ai-1","moduleId":"add-cluster-randomized-trials","stem":"Which statistical method is commonly used to analyze data from cluster randomized trials?","options":[{"id":"a","text":"T-tests"},{"id":"b","text":"ANOVA"},{"id":"c","text":"Mixed-effects models"},{"id":"d","text":"Chi-square tests"}],"answerId":"c","explanation":"Mixed-effects models account for the intra-cluster correlation present in CRTs.","kind":"mechanism","origin":"ai"},{"id":"add-cluster-randomized-trials~ai-2","moduleId":"add-cluster-randomized-trials","stem":"Why do cluster randomized trials require larger sample sizes compared to individually randomized trials?","options":[{"id":"a","text":"Higher dropout rates"},{"id":"b","text":"Increased design effect due to intra-cluster correlation"},{"id":"c","text":"More complex interventions"},{"id":"d","text":"Longer study duration"}],"answerId":"b","explanation":"The design effect increases with higher intra-cluster correlation, necessitating larger sample sizes.","kind":"mechanism","origin":"ai"},{"id":"add-cluster-randomized-trials~ai-3","moduleId":"add-cluster-randomized-trials","stem":"In a cluster randomized trial, what ethical consideration is unique compared to individually randomized trials?","options":[{"id":"a","text":"Informed consent from individual participants"},{"id":"b","text":"Informed consent from both individual and cluster levels"},{"id":"c","text":"Use of control groups"},{"id":"d","text":"Blinding of investigators"}],"answerId":"b","explanation":"CRTs require consent at both the individual and cluster level due to group-level interventions.","kind":"trap","origin":"ai"},{"id":"add-cluster-randomized-trials~ai-4","moduleId":"add-cluster-randomized-trials","stem":"Which phase of clinical trials is most likely to use cluster randomization?","options":[{"id":"a","text":"Phase I"},{"id":"b","text":"Phase II"},{"id":"c","text":"Phase III"},{"id":"d","text":"Phase IV"}],"answerId":"d","explanation":"Phase IV trials often involve public health interventions suitable for CRTs.","kind":"integration","linkedModuleIds":["add-clinical-trial-phases-design-and-purpose"],"origin":"ai"},{"id":"add-cluster-randomized-trials~ai-5","moduleId":"add-cluster-randomized-trials","stem":"How does intra-cluster correlation affect the analysis of cluster randomized trials?","options":[{"id":"a","text":"It increases the likelihood of Type I errors"},{"id":"b","text":"It requires adjustment in sample size calculations"},{"id":"c","text":"It simplifies the statistical analysis"},{"id":"d","text":"It has no effect"}],"answerId":"b","explanation":"Intra-cluster correlation affects sample size calculations and must be accounted for in analysis.","kind":"clinical","origin":"ai"},{"id":"add-cluster-randomized-trials~ai-6","moduleId":"add-cluster-randomized-trials","stem":"What is a common challenge when designing a cluster randomized trial?","options":[{"id":"a","text":"Ensuring individual randomization"},{"id":"b","text":"Accounting for intra-cluster correlation"},{"id":"c","text":"Blinding participants"},{"id":"d","text":"Using placebo controls"}],"answerId":"b","explanation":"Intra-cluster correlation must be accounted for in both design and analysis.","kind":"trap","origin":"ai"},{"id":"add-cluster-randomized-trials~ai-7","moduleId":"add-cluster-randomized-trials","stem":"In the context of advanced regression techniques, which method is suitable for handling intra-cluster correlation in CRTs?","options":[{"id":"a","text":"Simple linear regression"},{"id":"b","text":"Logistic regression"},{"id":"c","text":"Mixed-effects regression"},{"id":"d","text":"Poisson regression"}],"answerId":"c","explanation":"Mixed-effects regression can handle the intra-cluster correlation present in CRTs.","kind":"integration","linkedModuleIds":["add-advanced-regression-techniques"],"origin":"ai"}],"add-non-inferiority-and-equivalence-trials":[{"id":"add-non-inferiority-and-equivalence-trials~ai-0","moduleId":"add-non-inferiority-and-equivalence-trials","stem":"What is the primary objective of a non-inferiority trial?","options":[{"id":"a","text":"To show the new treatment is not worse than the control by more than a pre-specified margin"},{"id":"b","text":"To demonstrate the new treatment is superior to the control"},{"id":"c","text":"To establish the new treatment is equivalent to the control"},{"id":"d","text":"To confirm the new treatment is ineffective"}],"answerId":"a","explanation":"Non-inferiority trials aim to demonstrate that a new treatment is not worse than an active control by more than a pre-specified margin.","kind":"recall","origin":"ai"},{"id":"add-non-inferiority-and-equivalence-trials~ai-1","moduleId":"add-non-inferiority-and-equivalence-trials","stem":"Which of the following is a key consideration when designing a non-inferiority trial?","options":[{"id":"a","text":"Justifying the non-inferiority margin"},{"id":"b","text":"Ensuring the new treatment is superior"},{"id":"c","text":"Proving the new treatment is ineffective"},{"id":"d","text":"Demonstrating placebo effect"}],"answerId":"a","explanation":"The non-inferiority margin must be clinically justified and pre-specified.","kind":"mechanism","origin":"ai"},{"id":"add-non-inferiority-and-equivalence-trials~ai-2","moduleId":"add-non-inferiority-and-equivalence-trials","stem":"In a non-inferiority trial, what does a confidence interval that lies entirely within the non-inferiority margin indicate?","options":[{"id":"a","text":"Non-inferiority"},{"id":"b","text":"Superiority"},{"id":"c","text":"Inferiority"},{"id":"d","text":"Equivalence"}],"answerId":"a","explanation":"A confidence interval within the margin indicates non-inferiority.","kind":"recall","origin":"ai"},{"id":"add-non-inferiority-and-equivalence-trials~ai-3","moduleId":"add-non-inferiority-and-equivalence-trials","stem":"Why is a placebo control often considered unethical in non-inferiority trials?","options":[{"id":"a","text":"Because it may deprive patients of effective treatment in life-threatening conditions"},{"id":"b","text":"Because it always leads to inferior results"},{"id":"c","text":"Because it is more expensive"},{"id":"d","text":"Because it complicates the trial design"}],"answerId":"a","explanation":"Placebo control is unethical in life-threatening conditions as it may deprive patients of effective treatment.","kind":"trap","origin":"ai"},{"id":"add-non-inferiority-and-equivalence-trials~ai-4","moduleId":"add-non-inferiority-and-equivalence-trials","stem":"Which type of trial seeks to demonstrate that two treatments have no meaningful difference in efficacy?","options":[{"id":"a","text":"Equivalence trial"},{"id":"b","text":"Non-inferiority trial"},{"id":"c","text":"Superiority trial"},{"id":"d","text":"Observational study"}],"answerId":"a","explanation":"Equivalence trials seek to show that two treatments have no meaningful difference in efficacy.","kind":"recall","origin":"ai"},{"id":"add-non-inferiority-and-equivalence-trials~ai-5","moduleId":"add-non-inferiority-and-equivalence-trials","stem":"How does the concept of assay sensitivity apply to non-inferiority trials?","options":[{"id":"a","text":"It ensures the trial can distinguish between effective and ineffective treatments"},{"id":"b","text":"It ensures the new treatment is superior"},{"id":"c","text":"It guarantees equivalence"},{"id":"d","text":"It confirms the placebo effect"}],"answerId":"a","explanation":"Assay sensitivity ensures the trial can distinguish between effective and ineffective treatments.","kind":"mechanism","origin":"ai"},{"id":"add-non-inferiority-and-equivalence-trials~ai-6","moduleId":"add-non-inferiority-and-equivalence-trials","stem":"In the context of clinical trial phases, why is it important to define and justify the non-inferiority margin?","options":[{"id":"a","text":"To ensure the trial is ethically sound and scientifically valid"},{"id":"b","text":"To guarantee the new treatment is superior"},{"id":"c","text":"To confirm the placebo effect"},{"id":"d","text":"To reduce trial costs"}],"answerId":"a","explanation":"Defining and justifying the margin ensures the trial is ethically sound and scientifically valid.","kind":"integration","linkedModuleIds":["add-clinical-trial-phases-design-and-purpose"],"origin":"ai"},{"id":"add-non-inferiority-and-equivalence-trials~ai-7","moduleId":"add-non-inferiority-and-equivalence-trials","stem":"How might advanced regression techniques be utilized in the analysis of non-inferiority trials?","options":[{"id":"a","text":"To adjust for confounding variables and improve precision"},{"id":"b","text":"To prove superiority"},{"id":"c","text":"To establish equivalence"},{"id":"d","text":"To demonstrate placebo effects"}],"answerId":"a","explanation":"Advanced regression techniques can adjust for confounding variables and improve precision in trial analysis.","kind":"integration","linkedModuleIds":["add-advanced-regression-techniques"],"origin":"ai"}],"add-adaptive-clinical-trial-designs":[{"id":"add-adaptive-clinical-trial-designs~ai-0","moduleId":"add-adaptive-clinical-trial-designs","stem":"Which type of adaptive clinical trial design allows for early stopping due to efficacy or futility?","options":[{"id":"a","text":"Group sequential design"},{"id":"b","text":"Adaptive randomization"},{"id":"c","text":"Sample size re-estimation"},{"id":"d","text":"Bayesian adaptive design"}],"answerId":"a","explanation":"Group sequential designs include stopping rules that allow for early termination based on interim results.","kind":"recall","origin":"ai"},{"id":"add-adaptive-clinical-trial-designs~ai-1","moduleId":"add-adaptive-clinical-trial-designs","stem":"In adaptive clinical trials, why must modifications follow pre-specified rules?","options":[{"id":"a","text":"To allow flexibility in trial design"},{"id":"b","text":"To reduce the cost of the trial"},{"id":"c","text":"To avoid introducing bias and maintain study integrity"},{"id":"d","text":"To increase the likelihood of FDA approval"}],"answerId":"c","explanation":"Pre-specified rules ensure that modifications do not introduce bias, maintaining the validity and integrity of the trial.","kind":"trap","origin":"ai"},{"id":"add-adaptive-clinical-trial-designs~ai-2","moduleId":"add-adaptive-clinical-trial-designs","stem":"How does adaptive randomization in clinical trials benefit patients?","options":[{"id":"a","text":"By reducing the trial duration"},{"id":"b","text":"By increasing the probability of patient benefit"},{"id":"c","text":"By decreasing the sample size needed"},{"id":"d","text":"By simplifying the trial design"}],"answerId":"b","explanation":"Adaptive randomization adjusts assignment probabilities to favor treatments showing better interim results, potentially benefiting patients.","kind":"mechanism","origin":"ai"},{"id":"add-adaptive-clinical-trial-designs~ai-3","moduleId":"add-adaptive-clinical-trial-designs","stem":"What is a key requirement for implementing adaptive designs in clinical trials according to FDA and EMA guidelines?","options":[{"id":"a","text":"Real-time data analysis"},{"id":"b","text":"Pre-specified modification rules"},{"id":"c","text":"Unlimited sample size adjustments"},{"id":"d","text":"Flexible trial endpoints"}],"answerId":"b","explanation":"FDA and EMA guidelines require pre-specified rules for modifications to ensure trial integrity.","kind":"recall","origin":"ai"},{"id":"add-adaptive-clinical-trial-designs~ai-4","moduleId":"add-adaptive-clinical-trial-designs","stem":"Which of the following is a potential outcome of using group sequential designs in clinical trials?","options":[{"id":"a","text":"Increased trial complexity"},{"id":"b","text":"Early trial termination for efficacy"},{"id":"c","text":"Reduced need for control groups"},{"id":"d","text":"Increased recruitment rates"}],"answerId":"b","explanation":"Group sequential designs can lead to early termination if interim results show clear efficacy or futility.","kind":"clinical","origin":"ai"},{"id":"add-adaptive-clinical-trial-designs~ai-5","moduleId":"add-adaptive-clinical-trial-designs","stem":"How might Bayesian analysis be integrated into adaptive clinical trial designs?","options":[{"id":"a","text":"By determining sample size re-estimation"},{"id":"b","text":"By providing a framework for interim data analysis"},{"id":"c","text":"By setting flexible endpoints"},{"id":"d","text":"By allowing unlimited modifications"}],"answerId":"b","explanation":"Bayesian analysis can be used to analyze interim data, providing a probabilistic framework for decision-making in adaptive trials.","kind":"integration","linkedModuleIds":["add-bayesian-analysis-in-medical-research"],"origin":"ai"},{"id":"add-adaptive-clinical-trial-designs~ai-6","moduleId":"add-adaptive-clinical-trial-designs","stem":"In the context of adaptive clinical trials, what role does the immune system play in the design of trials for immunotherapies?","options":[{"id":"a","text":"Determining trial endpoints"},{"id":"b","text":"Guiding adaptive randomization"},{"id":"c","text":"Influencing sample size re-estimation"},{"id":"d","text":"Providing biomarkers for interim analysis"}],"answerId":"d","explanation":"Biomarkers from the immune system can be used in interim analyses to guide adaptive decisions in trials for immunotherapies.","kind":"integration","linkedModuleIds":["immune-system-overview-cells"],"origin":"ai"}],"add-propensity-score-matching-in-observational-studies":[{"id":"add-propensity-score-matching-in-observational-studies~ai-0","moduleId":"add-propensity-score-matching-in-observational-studies","stem":"What is the primary purpose of propensity score matching in observational studies?","options":[{"id":"a","text":"To reduce selection bias by equating groups based on covariates"},{"id":"b","text":"To eliminate all confounding variables"},{"id":"c","text":"To increase the sample size of the study"},{"id":"d","text":"To ensure randomization of participants"}],"answerId":"a","explanation":"Propensity score matching reduces selection bias by equating groups based on observed covariates.","kind":"recall","origin":"ai"},{"id":"add-propensity-score-matching-in-observational-studies~ai-1","moduleId":"add-propensity-score-matching-in-observational-studies","stem":"Which method is commonly used in propensity score matching to create matched samples?","options":[{"id":"a","text":"Random sampling"},{"id":"b","text":"Nearest neighbor matching"},{"id":"c","text":"Cluster sampling"},{"id":"d","text":"Cross-sectional matching"}],"answerId":"b","explanation":"Nearest neighbor matching is a common method used in propensity score matching to create matched samples.","kind":"recall","origin":"ai"},{"id":"add-propensity-score-matching-in-observational-studies~ai-2","moduleId":"add-propensity-score-matching-in-observational-studies","stem":"What is a limitation of propensity score matching compared to randomized controlled trials?","options":[{"id":"a","text":"It requires smaller sample sizes"},{"id":"b","text":"It controls for all confounders"},{"id":"c","text":"It only controls for measured confounders"},{"id":"d","text":"It increases the risk of type I error"}],"answerId":"c","explanation":"Propensity score matching only controls for measured confounders, unlike randomized controlled trials which can control for both measured and unmeasured confounders.","kind":"trap","origin":"ai"},{"id":"add-propensity-score-matching-in-observational-studies~ai-3","moduleId":"add-propensity-score-matching-in-observational-studies","stem":"In a study using propensity score matching, which diagnostic is used to assess the quality of matching?","options":[{"id":"a","text":"P-value"},{"id":"b","text":"Confidence interval"},{"id":"c","text":"Standardized mean difference"},{"id":"d","text":"Odds ratio"}],"answerId":"c","explanation":"Standardized mean differences are used as balance diagnostics to assess the quality of matching in propensity score matching.","kind":"recall","origin":"ai"},{"id":"add-propensity-score-matching-in-observational-studies~ai-4","moduleId":"add-propensity-score-matching-in-observational-studies","stem":"How does propensity score matching attempt to mimic randomization in observational studies?","options":[{"id":"a","text":"By randomly assigning participants to treatment groups"},{"id":"b","text":"By creating a matched sample with similar covariate distributions"},{"id":"c","text":"By increasing the sample size"},{"id":"d","text":"By using blinding techniques"}],"answerId":"b","explanation":"Propensity score matching mimics randomization by creating a matched sample where treatment and control groups have similar covariate distributions.","kind":"mechanism","origin":"ai"},{"id":"add-propensity-score-matching-in-observational-studies~ai-5","moduleId":"add-propensity-score-matching-in-observational-studies","stem":"Which of the following is a potential pitfall when interpreting results from a propensity score matched study?","options":[{"id":"a","text":"Assuming all confounders are controlled"},{"id":"b","text":"Assuming the study is a randomized controlled trial"},{"id":"c","text":"Assuming the sample size is too large"},{"id":"d","text":"Assuming the treatment effect is homogeneous"}],"answerId":"a","explanation":"A common pitfall is assuming that all confounders are controlled, while propensity score matching only controls for measured confounders.","kind":"trap","origin":"ai"},{"id":"add-propensity-score-matching-in-observational-studies~ai-6","moduleId":"add-propensity-score-matching-in-observational-studies","stem":"How might propensity score matching be integrated with advanced regression techniques to improve study outcomes?","options":[{"id":"a","text":"By using regression to adjust for unmeasured confounders"},{"id":"b","text":"By applying regression analysis post-matching to control for residual confounding"},{"id":"c","text":"By using regression to increase sample size"},{"id":"d","text":"By replacing matching with regression analysis"}],"answerId":"b","explanation":"Regression analysis can be applied post-matching to control for any residual confounding that may remain after propensity score matching.","kind":"integration","linkedModuleIds":["add-advanced-regression-techniques"],"origin":"ai"},{"id":"add-propensity-score-matching-in-observational-studies~ai-7","moduleId":"add-propensity-score-matching-in-observational-studies","stem":"In the context of ventilation-perfusion (V/Q) matching, how is the concept of 'matching' similar to propensity score matching in observational studies?","options":[{"id":"a","text":"Both involve random assignment to groups"},{"id":"b","text":"Both aim to balance certain characteristics between groups"},{"id":"c","text":"Both require large sample sizes to be effective"},{"id":"d","text":"Both control for unmeasured confounders"}],"answerId":"b","explanation":"Both V/Q matching and propensity score matching aim to balance specific characteristics between groups to improve outcomes.","kind":"integration","linkedModuleIds":["add-pulmonary-physiology-ventilation-perfusion-v-q-matching"],"origin":"ai"}],"add-confounding-and-effect-modification-in-research":[{"id":"add-confounding-and-effect-modification-in-research~ai-0","moduleId":"add-confounding-and-effect-modification-in-research","stem":"Which of the following is a method commonly used to control for confounding in observational studies?","options":[{"id":"a","text":"Randomization"},{"id":"b","text":"Stratification"},{"id":"c","text":"Blinding"},{"id":"d","text":"Cross-over design"}],"answerId":"b","explanation":"Stratification is a method used to control for confounding by analyzing subgroups of the data.","kind":"recall","origin":"ai"},{"id":"add-confounding-and-effect-modification-in-research~ai-1","moduleId":"add-confounding-and-effect-modification-in-research","stem":"In a study examining the relationship between alcohol consumption and liver disease, smoking is found to be associated with both alcohol consumption and liver disease. What role does smoking play in this study?","options":[{"id":"a","text":"Confounder"},{"id":"b","text":"Effect modifier"},{"id":"c","text":"Mediator"},{"id":"d","text":"Outcome"}],"answerId":"a","explanation":"Smoking is a confounder because it is associated with both the exposure (alcohol consumption) and the outcome (liver disease).","kind":"mechanism","origin":"ai"},{"id":"add-confounding-and-effect-modification-in-research~ai-2","moduleId":"add-confounding-and-effect-modification-in-research","stem":"A study finds that the effect of a new drug on blood pressure reduction is greater in women than in men. What is this an example of?","options":[{"id":"a","text":"Confounding"},{"id":"b","text":"Effect modification"},{"id":"c","text":"Bias"},{"id":"d","text":"Random error"}],"answerId":"b","explanation":"This is an example of effect modification, where the effect of the drug varies by gender.","kind":"recall","origin":"ai"},{"id":"add-confounding-and-effect-modification-in-research~ai-3","moduleId":"add-confounding-and-effect-modification-in-research","stem":"Which of the following scenarios best illustrates effect modification?","options":[{"id":"a","text":"A variable that influences both the exposure and the outcome"},{"id":"b","text":"A variable that changes the effect of the exposure on the outcome"},{"id":"c","text":"A variable that is a step in the causal pathway"},{"id":"d","text":"A variable that is unrelated to both the exposure and the outcome"}],"answerId":"b","explanation":"Effect modification occurs when a variable changes the effect of the exposure on the outcome.","kind":"trap","origin":"ai"},{"id":"add-confounding-and-effect-modification-in-research~ai-4","moduleId":"add-confounding-and-effect-modification-in-research","stem":"In a clinical trial, researchers adjust for age using multivariable regression. What is the primary purpose of this adjustment?","options":[{"id":"a","text":"To reduce bias"},{"id":"b","text":"To control for confounding"},{"id":"c","text":"To assess effect modification"},{"id":"d","text":"To increase sample size"}],"answerId":"b","explanation":"Multivariable regression is used to control for confounding by adjusting for variables like age.","kind":"recall","origin":"ai"},{"id":"add-confounding-and-effect-modification-in-research~ai-5","moduleId":"add-confounding-and-effect-modification-in-research","stem":"In a study on a new antihypertensive drug, researchers find that the drug's effect varies by baseline cholesterol levels. Which advanced regression technique could be used to explore this interaction?","options":[{"id":"a","text":"Logistic regression"},{"id":"b","text":"Cox proportional hazards model"},{"id":"c","text":"Generalized linear model"},{"id":"d","text":"Multilevel modeling"}],"answerId":"d","explanation":"Multilevel modeling can explore interactions and effect modifications by considering hierarchical data structures.","kind":"integration","linkedModuleIds":["add-advanced-regression-techniques"],"origin":"ai"},{"id":"add-confounding-and-effect-modification-in-research~ai-6","moduleId":"add-confounding-and-effect-modification-in-research","stem":"An adaptive clinical trial design is being considered for a study on a new cancer treatment. How might effect modification influence the trial's interim analysis?","options":[{"id":"a","text":"It could lead to stopping the trial early"},{"id":"b","text":"It could necessitate stratified randomization"},{"id":"c","text":"It could alter the sample size calculation"},{"id":"d","text":"It could require adjustment of the primary endpoint"}],"answerId":"c","explanation":"Effect modification might alter the sample size calculation if different subgroups show varying responses.","kind":"integration","linkedModuleIds":["add-adaptive-clinical-trial-designs"],"origin":"ai"}],"add-cross-sectional-study-design-and-analysis":[{"id":"add-cross-sectional-study-design-and-analysis~ai-0","moduleId":"add-cross-sectional-study-design-and-analysis","stem":"Which of the following best describes a cross-sectional study?","options":[{"id":"a","text":"A study that assesses the prevalence of a condition at a single point in time"},{"id":"b","text":"A study that follows a group of individuals over time to assess outcomes"},{"id":"c","text":"A study that compares outcomes before and after an intervention"},{"id":"d","text":"A study that randomly assigns participants to different treatment groups"}],"answerId":"a","explanation":"Cross-sectional studies provide a snapshot of the prevalence of a condition at a specific point in time.","kind":"recall","origin":"ai"},{"id":"add-cross-sectional-study-design-and-analysis~ai-1","moduleId":"add-cross-sectional-study-design-and-analysis","stem":"What is a major limitation of cross-sectional studies in determining causality?","options":[{"id":"a","text":"They cannot establish temporal relationships"},{"id":"b","text":"They require large sample sizes"},{"id":"c","text":"They are expensive to conduct"},{"id":"d","text":"They are prone to high dropout rates"}],"answerId":"a","explanation":"Cross-sectional studies assess data at one point in time, making it impossible to determine the sequence of events needed to establish causality.","kind":"mechanism","origin":"ai"},{"id":"add-cross-sectional-study-design-and-analysis~ai-2","moduleId":"add-cross-sectional-study-design-and-analysis","stem":"In a cross-sectional study, which statistical test is commonly used to analyze categorical data?","options":[{"id":"a","text":"Chi-square test"},{"id":"b","text":"T-test"},{"id":"c","text":"ANOVA"},{"id":"d","text":"Mann-Whitney U test"}],"answerId":"a","explanation":"The Chi-square test is used to analyze categorical data in cross-sectional studies.","kind":"recall","origin":"ai"},{"id":"add-cross-sectional-study-design-and-analysis~ai-3","moduleId":"add-cross-sectional-study-design-and-analysis","stem":"A researcher incorrectly identifies a cross-sectional study as a cohort study. What is the primary distinction between these two study designs?","options":[{"id":"a","text":"Cross-sectional studies assess prevalence at one point in time, while cohort studies follow subjects over time"},{"id":"b","text":"Cohort studies are always experimental, while cross-sectional studies are observational"},{"id":"c","text":"Cross-sectional studies require randomization, while cohort studies do not"},{"id":"d","text":"Cohort studies are used for rare diseases, while cross-sectional studies are not"}],"answerId":"a","explanation":"Cross-sectional studies provide a snapshot at one point in time, whereas cohort studies involve following subjects over a period of time.","kind":"trap","origin":"ai"},{"id":"add-cross-sectional-study-design-and-analysis~ai-4","moduleId":"add-cross-sectional-study-design-and-analysis","stem":"How is prevalence calculated in a cross-sectional study?","options":[{"id":"a","text":"Number of existing cases divided by the total population at a specific time"},{"id":"b","text":"Number of new cases divided by the total population at a specific time"},{"id":"c","text":"Number of existing cases divided by the number of new cases"},{"id":"d","text":"Number of new cases divided by the number of existing cases"}],"answerId":"a","explanation":"Prevalence is calculated as the number of existing cases divided by the total population at a specific time.","kind":"recall","origin":"ai"},{"id":"add-cross-sectional-study-design-and-analysis~ai-5","moduleId":"add-cross-sectional-study-design-and-analysis","stem":"A cross-sectional study finds a high prevalence of a condition. What does this indicate?","options":[{"id":"a","text":"The condition has a high incidence rate"},{"id":"b","text":"The condition is widespread at the time of the study"},{"id":"c","text":"The condition is decreasing over time"},{"id":"d","text":"The condition is rare at the time of the study"}],"answerId":"b","explanation":"A high prevalence indicates that the condition is widespread at the time of the study, reflecting the burden of disease.","kind":"clinical","origin":"ai"},{"id":"add-cross-sectional-study-design-and-analysis~ai-6","moduleId":"add-cross-sectional-study-design-and-analysis","stem":"In the context of antigen processing and presentation, how might a cross-sectional study be used to assess immune response in a population?","options":[{"id":"a","text":"By measuring the prevalence of antibodies against a specific antigen"},{"id":"b","text":"By tracking changes in antibody levels over time"},{"id":"c","text":"By assigning participants to receive different antigens"},{"id":"d","text":"By comparing immune responses before and after vaccination"}],"answerId":"a","explanation":"A cross-sectional study can measure the prevalence of antibodies, providing a snapshot of immune response in a population.","kind":"integration","linkedModuleIds":["antigen-processing-presentation"],"origin":"ai"},{"id":"add-cross-sectional-study-design-and-analysis~ai-7","moduleId":"add-cross-sectional-study-design-and-analysis","stem":"How might advanced regression techniques be applied in the analysis of cross-sectional study data?","options":[{"id":"a","text":"To adjust for confounders and better estimate associations"},{"id":"b","text":"To establish causality between exposure and outcome"},{"id":"c","text":"To randomize participants into different groups"},{"id":"d","text":"To measure changes in prevalence over time"}],"answerId":"a","explanation":"Advanced regression techniques can adjust for confounders, improving the estimation of associations in cross-sectional data.","kind":"integration","linkedModuleIds":["add-advanced-regression-techniques"],"origin":"ai"}],"hrp2-vulvovaginitis":[{"id":"hrp2-vulvovaginitis~ai-0","moduleId":"hrp2-vulvovaginitis","stem":"A 28-year-old woman presents with a thin grey homogeneous vaginal discharge and a fishy odor. What is the most likely diagnosis?","options":[{"id":"a","text":"Bacterial vaginosis"},{"id":"b","text":"Vulvovaginal candidiasis"},{"id":"c","text":"Trichomoniasis"},{"id":"d","text":"Physiological discharge"}],"answerId":"a","explanation":"The presence of a thin grey discharge with a fishy odor is characteristic of bacterial vaginosis.","kind":"recall","origin":"ai"},{"id":"hrp2-vulvovaginitis~ai-1","moduleId":"hrp2-vulvovaginitis","stem":"Which of the following findings is most indicative of vulvovaginal candidiasis?","options":[{"id":"a","text":"Clue cells on wet mount"},{"id":"b","text":"Motile trichomonads"},{"id":"c","text":"Pseudohyphae on KOH prep"},{"id":"d","text":"Strawberry cervix"}],"answerId":"c","explanation":"Pseudohyphae on KOH prep are indicative of Candida infection.","kind":"recall","origin":"ai"},{"id":"hrp2-vulvovaginitis~ai-2","moduleId":"hrp2-vulvovaginitis","stem":"A patient presents with frothy yellow-green vaginal discharge and a 'strawberry cervix'. What is the causative organism?","options":[{"id":"a","text":"Gardnerella vaginalis"},{"id":"b","text":"Candida albicans"},{"id":"c","text":"Trichomonas vaginalis"},{"id":"d","text":"Escherichia coli"}],"answerId":"c","explanation":"Trichomonas vaginalis is associated with frothy discharge and a 'strawberry cervix'.","kind":"recall","origin":"ai"},{"id":"hrp2-vulvovaginitis~ai-3","moduleId":"hrp2-vulvovaginitis","stem":"Which of the following conditions is associated with a normal vaginal pH?","options":[{"id":"a","text":"Bacterial vaginosis"},{"id":"b","text":"Trichomoniasis"},{"id":"c","text":"Vulvovaginal candidiasis"},{"id":"d","text":"Atrophic vaginitis"}],"answerId":"c","explanation":"Vulvovaginal candidiasis is associated with a normal vaginal pH.","kind":"trap","origin":"ai"},{"id":"hrp2-vulvovaginitis~ai-4","moduleId":"hrp2-vulvovaginitis","stem":"A 32-year-old woman with diabetes presents with thick white vaginal discharge and itching. Which treatment is most appropriate?","options":[{"id":"a","text":"Metronidazole"},{"id":"b","text":"Fluconazole"},{"id":"c","text":"Clindamycin"},{"id":"d","text":"Doxycycline"}],"answerId":"b","explanation":"Fluconazole is used to treat vulvovaginal candidiasis, which is common in diabetic patients.","kind":"clinical","origin":"ai"},{"id":"hrp2-vulvovaginitis~ai-5","moduleId":"hrp2-vulvovaginitis","stem":"A patient with bacterial vaginosis is concerned about the risk of preterm birth. Which linked module provides additional information on the anaerobes involved?","options":[{"id":"a","text":"Antifungal Agents"},{"id":"b","text":"Bacteroides & Non-Spore Anaerobes"},{"id":"c","text":"Non-neoplastic Vulvar & Vaginal Conditions"},{"id":"d","text":"None of the above"}],"answerId":"b","explanation":"The 'Bacteroides & Non-Spore Anaerobes' module provides information on anaerobes like Gardnerella involved in BV.","kind":"integration","linkedModuleIds":["bacteroides-gram-negative-anaerobes"],"origin":"ai"},{"id":"hrp2-vulvovaginitis~ai-6","moduleId":"hrp2-vulvovaginitis","stem":"Which antifungal agent is most commonly used to treat vulvovaginal candidiasis?","options":[{"id":"a","text":"Metronidazole"},{"id":"b","text":"Fluconazole"},{"id":"c","text":"Amphotericin B"},{"id":"d","text":"Itraconazole"}],"answerId":"b","explanation":"Fluconazole is the most commonly used antifungal agent for vulvovaginal candidiasis.","kind":"integration","linkedModuleIds":["antifungal-agents"],"origin":"ai"}],"hrp2-bacterial-sti-pid":[{"id":"hrp2-bacterial-sti-pid~ai-0","moduleId":"hrp2-bacterial-sti-pid","stem":"A 25-year-old woman presents with lower abdominal pain and cervical motion tenderness. Which organism is most likely responsible for her condition?","options":[{"id":"a","text":"Neisseria gonorrhoeae"},{"id":"b","text":"Treponema pallidum"},{"id":"c","text":"Haemophilus ducreyi"},{"id":"d","text":"Herpes simplex virus"}],"answerId":"a","explanation":"Cervical motion tenderness is a classic sign of PID, commonly caused by Neisseria gonorrhoeae or Chlamydia trachomatis.","kind":"clinical","origin":"ai"},{"id":"hrp2-bacterial-sti-pid~ai-1","moduleId":"hrp2-bacterial-sti-pid","stem":"Which test is used to confirm a diagnosis of syphilis after a positive RPR?","options":[{"id":"a","text":"VDRL"},{"id":"b","text":"TPHA"},{"id":"c","text":"NAAT"},{"id":"d","text":"Gram stain"}],"answerId":"b","explanation":"TPHA is a treponemal test used to confirm syphilis after a positive non-treponemal test like RPR.","kind":"trap","origin":"ai"},{"id":"hrp2-bacterial-sti-pid~ai-2","moduleId":"hrp2-bacterial-sti-pid","stem":"A patient presents with a painless genital ulcer. What is the most likely diagnosis?","options":[{"id":"a","text":"Chancroid"},{"id":"b","text":"Genital herpes"},{"id":"c","text":"Primary syphilis"},{"id":"d","text":"Chlamydia trachomatis infection"}],"answerId":"c","explanation":"A painless genital ulcer is characteristic of primary syphilis.","kind":"recall","origin":"ai"},{"id":"hrp2-bacterial-sti-pid~ai-3","moduleId":"hrp2-bacterial-sti-pid","stem":"Which of the following is a major complication of untreated Chlamydia trachomatis infection in women?","options":[{"id":"a","text":"Ectopic pregnancy"},{"id":"b","text":"Gummas"},{"id":"c","text":"Condylomata lata"},{"id":"d","text":"Aortitis"}],"answerId":"a","explanation":"Untreated Chlamydia trachomatis can lead to PID, increasing the risk of ectopic pregnancy.","kind":"mechanism","origin":"ai"},{"id":"hrp2-bacterial-sti-pid~ai-4","moduleId":"hrp2-bacterial-sti-pid","stem":"A 30-year-old man presents with a diffuse rash including palms and soles. Which stage of syphilis is this indicative of?","options":[{"id":"a","text":"Primary syphilis"},{"id":"b","text":"Secondary syphilis"},{"id":"c","text":"Tertiary syphilis"},{"id":"d","text":"Latent syphilis"}],"answerId":"b","explanation":"A rash on palms and soles is indicative of secondary syphilis.","kind":"recall","origin":"ai"},{"id":"hrp2-bacterial-sti-pid~ai-5","moduleId":"hrp2-bacterial-sti-pid","stem":"Which treatment is appropriate for a pregnant woman diagnosed with Chlamydia trachomatis infection?","options":[{"id":"a","text":"Doxycycline"},{"id":"b","text":"Azithromycin"},{"id":"c","text":"Ceftriaxone"},{"id":"d","text":"Penicillin"}],"answerId":"b","explanation":"Azithromycin is safe and effective for treating Chlamydia trachomatis in pregnancy.","kind":"trap","origin":"ai"},{"id":"hrp2-bacterial-sti-pid~ai-6","moduleId":"hrp2-bacterial-sti-pid","stem":"A patient with a history of PID is at increased risk for which condition?","options":[{"id":"a","text":"Alkaptonuria"},{"id":"b","text":"Ectopic pregnancy"},{"id":"c","text":"Condylomata lata"},{"id":"d","text":"Gummas"}],"answerId":"b","explanation":"PID can cause scarring and damage to the fallopian tubes, increasing the risk of ectopic pregnancy.","kind":"integration","linkedModuleIds":["hrp2-pid-tubo-ovarian"],"origin":"ai"},{"id":"hrp2-bacterial-sti-pid~ai-7","moduleId":"hrp2-bacterial-sti-pid","stem":"In a patient with suspected secondary syphilis, which test should be performed to confirm the diagnosis?","options":[{"id":"a","text":"VDRL"},{"id":"b","text":"RPR"},{"id":"c","text":"TPHA"},{"id":"d","text":"NAAT"}],"answerId":"c","explanation":"TPHA is a treponemal test used to confirm syphilis after a non-treponemal test suggests infection.","kind":"integration","linkedModuleIds":["hrp2-syphilis-stages"],"origin":"ai"}],"hrp2-perinatal-infections":[{"id":"hrp2-perinatal-infections~ai-0","moduleId":"hrp2-perinatal-infections","stem":"A newborn presents with cataracts, patent ductus arteriosus, and sensorineural deafness. Which congenital infection is most likely responsible?","options":[{"id":"a","text":"Congenital rubella"},{"id":"b","text":"Congenital CMV"},{"id":"c","text":"Congenital toxoplasmosis"},{"id":"d","text":"Congenital syphilis"}],"answerId":"a","explanation":"The classic triad of cataracts, PDA, and deafness is indicative of congenital rubella.","kind":"recall","origin":"ai"},{"id":"hrp2-perinatal-infections~ai-1","moduleId":"hrp2-perinatal-infections","stem":"A newborn is diagnosed with congenital CMV infection. Which of the following findings is most characteristic of this condition?","options":[{"id":"a","text":"Diffuse intracranial calcifications"},{"id":"b","text":"Periventricular calcifications"},{"id":"c","text":"Hutchinson teeth"},{"id":"d","text":"Hydrocephalus"}],"answerId":"b","explanation":"Periventricular calcifications are characteristic of congenital CMV infection.","kind":"recall","origin":"ai"},{"id":"hrp2-perinatal-infections~ai-2","moduleId":"hrp2-perinatal-infections","stem":"A pregnant woman is diagnosed with primary toxoplasmosis infection. What is the primary mechanism by which this infection affects the fetus?","options":[{"id":"a","text":"Direct fetal infection through the placenta"},{"id":"b","text":"Infection during delivery"},{"id":"c","text":"Postnatal infection through breastfeeding"},{"id":"d","text":"Maternal immune response affecting the fetus"}],"answerId":"a","explanation":"Toxoplasmosis affects the fetus through transplacental transmission.","kind":"mechanism","origin":"ai"},{"id":"hrp2-perinatal-infections~ai-3","moduleId":"hrp2-perinatal-infections","stem":"A newborn presents with a 'blueberry-muffin' rash. Which mechanism explains this finding in congenital infections?","options":[{"id":"a","text":"Dermal extramedullary haematopoiesis"},{"id":"b","text":"Immune complex deposition"},{"id":"c","text":"Viral exanthema"},{"id":"d","text":"Bacterial superinfection"}],"answerId":"a","explanation":"The 'blueberry-muffin' rash is due to dermal extramedullary haematopoiesis, commonly seen in rubella and CMV.","kind":"mechanism","origin":"ai"},{"id":"hrp2-perinatal-infections~ai-4","moduleId":"hrp2-perinatal-infections","stem":"A newborn with congenital toxoplasmosis is found to have diffuse intracranial calcifications. Which other finding is commonly associated with this condition?","options":[{"id":"a","text":"Hydrocephalus"},{"id":"b","text":"Periventricular calcifications"},{"id":"c","text":"Patent ductus arteriosus"},{"id":"d","text":"Hutchinson teeth"}],"answerId":"a","explanation":"Diffuse intracranial calcifications and hydrocephalus are associated with congenital toxoplasmosis.","kind":"recall","origin":"ai"},{"id":"hrp2-perinatal-infections~ai-5","moduleId":"hrp2-perinatal-infections","stem":"A newborn presents with cataracts. Which condition should be considered if galactokinase deficiency is suspected?","options":[{"id":"a","text":"Congenital rubella"},{"id":"b","text":"Congenital CMV"},{"id":"c","text":"Congenital toxoplasmosis"},{"id":"d","text":"Congenital syphilis"}],"answerId":"a","explanation":"Cataracts in a newborn can be due to congenital rubella or galactokinase deficiency.","kind":"integration","linkedModuleIds":["galactokinase-cataracts"],"origin":"ai"},{"id":"hrp2-perinatal-infections~ai-6","moduleId":"hrp2-perinatal-infections","stem":"A neonate is born with signs of sepsis and is suspected to have a congenital infection. Which pathogen is most likely if the mother had a positive Group B Streptococcus screen?","options":[{"id":"a","text":"Group B Streptococcus"},{"id":"b","text":"Congenital CMV"},{"id":"c","text":"Congenital rubella"},{"id":"d","text":"Congenital syphilis"}],"answerId":"a","explanation":"Group B Streptococcus is a common cause of neonatal sepsis and is screened for in pregnant women.","kind":"integration","linkedModuleIds":["hrp2-neonatal-sepsis-gbs"],"origin":"ai"}],"hrp2-viral-sti-antivirals":[{"id":"hrp2-viral-sti-antivirals~ai-0","moduleId":"hrp2-viral-sti-antivirals","stem":"Which HPV types are most commonly associated with cervical cancer?","options":[{"id":"a","text":"HPV 6 and 11"},{"id":"b","text":"HPV 16 and 18"},{"id":"c","text":"HPV 1 and 2"},{"id":"d","text":"HPV 31 and 33"}],"answerId":"b","explanation":"HPV types 16 and 18 are high-risk oncogenic types that can lead to cervical cancer.","kind":"recall","origin":"ai"},{"id":"hrp2-viral-sti-antivirals~ai-1","moduleId":"hrp2-viral-sti-antivirals","stem":"What is the mechanism by which aciclovir selectively targets HSV-infected cells?","options":[{"id":"a","text":"Inhibition of viral RNA polymerase"},{"id":"b","text":"Activation by viral thymidine kinase"},{"id":"c","text":"Binding to viral envelope proteins"},{"id":"d","text":"Inhibition of viral integrase"}],"answerId":"b","explanation":"Aciclovir is activated by viral thymidine kinase, which is present only in infected cells.","kind":"mechanism","origin":"ai"},{"id":"hrp2-viral-sti-antivirals~ai-2","moduleId":"hrp2-viral-sti-antivirals","stem":"A pregnant woman with a primary HSV outbreak is about to deliver. What is the recommended delivery method to reduce neonatal HSV transmission?","options":[{"id":"a","text":"Vaginal delivery"},{"id":"b","text":"Caesarean section"},{"id":"c","text":"Forceps delivery"},{"id":"d","text":"Vacuum extraction"}],"answerId":"b","explanation":"Caesarean section is recommended to prevent neonatal HSV transmission during a primary outbreak.","kind":"clinical","origin":"ai"},{"id":"hrp2-viral-sti-antivirals~ai-3","moduleId":"hrp2-viral-sti-antivirals","stem":"Which antiviral drug is a guanosine analogue used to treat HSV infections?","options":[{"id":"a","text":"Oseltamivir"},{"id":"b","text":"Aciclovir"},{"id":"c","text":"Zidovudine"},{"id":"d","text":"Ribavirin"}],"answerId":"b","explanation":"Aciclovir is a guanosine analogue specifically used for HSV infections.","kind":"recall","origin":"ai"},{"id":"hrp2-viral-sti-antivirals~ai-4","moduleId":"hrp2-viral-sti-antivirals","stem":"A patient presents with painful grouped vesicles on the genitalia. A Tzanck smear shows multinucleated giant cells. What is the most likely diagnosis?","options":[{"id":"a","text":"Syphilis"},{"id":"b","text":"Genital herpes"},{"id":"c","text":"Chancroid"},{"id":"d","text":"HPV infection"}],"answerId":"b","explanation":"The presence of painful vesicles and multinucleated giant cells on a Tzanck smear is indicative of genital herpes.","kind":"clinical","origin":"ai"},{"id":"hrp2-viral-sti-antivirals~ai-5","moduleId":"hrp2-viral-sti-antivirals","stem":"How does HPV contribute to cervical cancer development?","options":[{"id":"a","text":"Inhibiting viral replication"},{"id":"b","text":"Activating p53 and Rb"},{"id":"c","text":"Inactivating p53 and Rb"},{"id":"d","text":"Enhancing immune response"}],"answerId":"c","explanation":"HPV types 16 and 18 inactivate tumor suppressor proteins p53 and Rb, leading to cancer development.","kind":"mechanism","origin":"ai"},{"id":"hrp2-viral-sti-antivirals~ai-6","moduleId":"hrp2-viral-sti-antivirals","stem":"Which of the following is a key factor in the high chronicity of perinatal Hepatitis B infection?","options":[{"id":"a","text":"High viral load in the mother"},{"id":"b","text":"Immature neonatal immune system"},{"id":"c","text":"Lack of maternal antibodies"},{"id":"d","text":"Genetic predisposition"}],"answerId":"b","explanation":"The immature neonatal immune system contributes to the high chronicity of perinatal Hepatitis B infection.","kind":"mechanism","origin":"ai"},{"id":"hrp2-viral-sti-antivirals~ai-7","moduleId":"hrp2-viral-sti-antivirals","stem":"In the context of HIV and pregnancy, which intervention is crucial to reduce vertical transmission?","options":[{"id":"a","text":"Avoiding breastfeeding"},{"id":"b","text":"Cesarean delivery only"},{"id":"c","text":"Antiretroviral therapy alone"},{"id":"d","text":"Early weaning"}],"answerId":"a","explanation":"Avoiding breastfeeding, along with ART and appropriate delivery, significantly reduces vertical transmission of HIV.","kind":"integration","linkedModuleIds":["hrp2-genital-herpes-hiv-pregnancy"],"origin":"ai"},{"id":"hrp2-viral-sti-antivirals~ai-8","moduleId":"hrp2-viral-sti-antivirals","stem":"Which viral protein interaction is crucial in HPV-driven oncogenesis?","options":[{"id":"a","text":"E6 with p53"},{"id":"b","text":"E7 with integrase"},{"id":"c","text":"E6 with Rb"},{"id":"d","text":"E7 with CD4"}],"answerId":"a","explanation":"HPV E6 protein binds to p53, leading to its degradation and contributing to oncogenesis.","kind":"integration","linkedModuleIds":["add-genetic-basis-of-cancer-development"],"origin":"ai"}],"hrp2-ovary-pathology":[{"id":"hrp2-ovary-pathology~ai-0","moduleId":"hrp2-ovary-pathology","stem":"A 45-year-old woman presents with abdominal bloating and ascites. Imaging reveals a large multiloculated ovarian mass. What is the most likely diagnosis?","options":[{"id":"a","text":"Serous carcinoma"},{"id":"b","text":"Mucinous carcinoma"},{"id":"c","text":"Endometrioid carcinoma"},{"id":"d","text":"Brenner tumor"}],"answerId":"b","explanation":"Mucinous carcinomas are large, multiloculated masses often associated with ascites.","kind":"clinical","origin":"ai"},{"id":"hrp2-ovary-pathology~ai-1","moduleId":"hrp2-ovary-pathology","stem":"A 30-year-old woman presents with virilization. Imaging shows an ovarian mass. Which tumor is most likely responsible?","options":[{"id":"a","text":"Granulosa cell tumor"},{"id":"b","text":"Sertoli-Leydig cell tumor"},{"id":"c","text":"Mature cystic teratoma"},{"id":"d","text":"Dysgerminoma"}],"answerId":"b","explanation":"Sertoli-Leydig cell tumors secrete androgens, leading to virilization.","kind":"recall","origin":"ai"},{"id":"hrp2-ovary-pathology~ai-2","moduleId":"hrp2-ovary-pathology","stem":"Which marker is most commonly elevated in patients with serous epithelial ovarian carcinoma?","options":[{"id":"a","text":"AFP"},{"id":"b","text":"CA-125"},{"id":"c","text":"β-hCG"},{"id":"d","text":"Inhibin"}],"answerId":"b","explanation":"CA-125 is a marker commonly elevated in serous epithelial ovarian carcinoma.","kind":"recall","origin":"ai"},{"id":"hrp2-ovary-pathology~ai-3","moduleId":"hrp2-ovary-pathology","stem":"A 60-year-old woman presents with postmenopausal bleeding. Histology reveals Call-Exner bodies. What is the most likely tumor?","options":[{"id":"a","text":"Granulosa cell tumor"},{"id":"b","text":"Sertoli-Leydig cell tumor"},{"id":"c","text":"Fibroma"},{"id":"d","text":"Mature cystic teratoma"}],"answerId":"a","explanation":"Granulosa cell tumors produce estrogen, causing bleeding, and are characterized by Call-Exner bodies.","kind":"recall","origin":"ai"},{"id":"hrp2-ovary-pathology~ai-4","moduleId":"hrp2-ovary-pathology","stem":"A 25-year-old woman is diagnosed with a yolk sac tumor. Which tumor marker is most likely elevated?","options":[{"id":"a","text":"CA-125"},{"id":"b","text":"AFP"},{"id":"c","text":"β-hCG"},{"id":"d","text":"Inhibin"}],"answerId":"b","explanation":"Yolk sac tumors are associated with elevated AFP levels.","kind":"recall","linkedModuleIds":["hrp2-ovarian-germ-cell-tumors"],"origin":"ai"},{"id":"hrp2-ovary-pathology~ai-5","moduleId":"hrp2-ovary-pathology","stem":"A 50-year-old woman with a BRCA1 mutation is at increased risk for which type of ovarian tumor?","options":[{"id":"a","text":"Serous carcinoma"},{"id":"b","text":"Mucinous carcinoma"},{"id":"c","text":"Dysgerminoma"},{"id":"d","text":"Granulosa cell tumor"}],"answerId":"a","explanation":"BRCA1 mutation is associated with an increased risk of serous carcinoma of the ovary.","kind":"integration","linkedModuleIds":["hrp2-ovarian-sex-cord-stromal"],"origin":"ai"},{"id":"hrp2-ovary-pathology~ai-6","moduleId":"hrp2-ovary-pathology","stem":"A 35-year-old woman presents with abdominal pain and a unilateral ovarian mass. Histology shows signet-ring cells. What is the most likely diagnosis?","options":[{"id":"a","text":"Krukenberg tumor"},{"id":"b","text":"Mature cystic teratoma"},{"id":"c","text":"Endometrioid carcinoma"},{"id":"d","text":"Granulosa cell tumor"}],"answerId":"a","explanation":"Krukenberg tumors are characterized by signet-ring cells and are often metastatic from gastric cancer.","kind":"clinical","origin":"ai"}],"hrp2-gestational-trophoblastic-disease":[{"id":"hrp2-gestational-trophoblastic-disease~ai-0","moduleId":"hrp2-gestational-trophoblastic-disease","stem":"A 28-year-old woman presents with first-trimester bleeding and a uterus larger than expected for gestational age. Ultrasound shows a 'snowstorm' pattern. What is the most likely diagnosis?","options":[{"id":"a","text":"Complete hydatidiform mole"},{"id":"b","text":"Partial hydatidiform mole"},{"id":"c","text":"Choriocarcinoma"},{"id":"d","text":"Ectopic pregnancy"}],"answerId":"a","explanation":"The 'snowstorm' pattern on ultrasound and large-for-dates uterus are classic for a complete hydatidiform mole.","kind":"clinical","origin":"ai"},{"id":"hrp2-gestational-trophoblastic-disease~ai-1","moduleId":"hrp2-gestational-trophoblastic-disease","stem":"Which genetic abnormality is characteristic of a complete hydatidiform mole?","options":[{"id":"a","text":"46,XX (all paternal)"},{"id":"b","text":"Triploid 69,XXX"},{"id":"c","text":"46,XY (maternal and paternal)"},{"id":"d","text":"45,XO"}],"answerId":"a","explanation":"A complete mole is typically 46,XX with all genetic material derived from the father.","kind":"recall","origin":"ai"},{"id":"hrp2-gestational-trophoblastic-disease~ai-2","moduleId":"hrp2-gestational-trophoblastic-disease","stem":"What is the primary reason for monitoring β-hCG levels after treatment of a hydatidiform mole?","options":[{"id":"a","text":"To detect early pregnancy"},{"id":"b","text":"To monitor for persistent gestational trophoblastic disease"},{"id":"c","text":"To assess for ovarian cyst resolution"},{"id":"d","text":"To evaluate liver function"}],"answerId":"b","explanation":"Serial β-hCG monitoring is crucial to detect persistent GTD, which may require further treatment.","kind":"mechanism","origin":"ai"},{"id":"hrp2-gestational-trophoblastic-disease~ai-3","moduleId":"hrp2-gestational-trophoblastic-disease","stem":"A patient with a history of a complete mole presents with cough and hemoptysis. Chest X-ray shows multiple lung nodules. What is the most likely diagnosis?","options":[{"id":"a","text":"Pulmonary embolism"},{"id":"b","text":"Choriocarcinoma"},{"id":"c","text":"Tuberculosis"},{"id":"d","text":"Lung cancer"}],"answerId":"b","explanation":"Choriocarcinoma can metastasize early to the lungs, presenting as multiple nodules.","kind":"clinical","origin":"ai"},{"id":"hrp2-gestational-trophoblastic-disease~ai-4","moduleId":"hrp2-gestational-trophoblastic-disease","stem":"Which of the following is a key difference between a complete and partial hydatidiform mole?","options":[{"id":"a","text":"Complete mole has fetal parts"},{"id":"b","text":"Partial mole has higher β-hCG levels"},{"id":"c","text":"Complete mole has higher malignant potential"},{"id":"d","text":"Partial mole is more common"}],"answerId":"c","explanation":"Complete moles have a higher risk of progressing to choriocarcinoma compared to partial moles.","kind":"trap","origin":"ai"},{"id":"hrp2-gestational-trophoblastic-disease~ai-5","moduleId":"hrp2-gestational-trophoblastic-disease","stem":"A 32-year-old woman with a history of a partial mole is concerned about future pregnancies. What advice is most appropriate regarding conception?","options":[{"id":"a","text":"Avoid pregnancy for 6 months"},{"id":"b","text":"Avoid pregnancy for 1 year"},{"id":"c","text":"Conception is safe immediately"},{"id":"d","text":"Avoid pregnancy for 2 years"}],"answerId":"b","explanation":"It is recommended to avoid pregnancy for 1 year after treatment of a molar pregnancy to ensure complete resolution and monitoring.","kind":"clinical","origin":"ai"},{"id":"hrp2-gestational-trophoblastic-disease~ai-6","moduleId":"hrp2-gestational-trophoblastic-disease","stem":"In the context of gestational trophoblastic disease, which linked module provides additional information on the types and management of these conditions?","options":[{"id":"a","text":"Pre-embryonic Clinical Applications"},{"id":"b","text":"Gestational Trophoblastic Disease: Types and Management"},{"id":"c","text":"Choriocarcinoma & Persistent GTD"},{"id":"d","text":"Basic Embryology"}],"answerId":"b","explanation":"The linked module 'Gestational Trophoblastic Disease: Types and Management' covers these topics in detail.","kind":"integration","linkedModuleIds":["add-gestational-trophoblastic-disease-types-and-management"],"origin":"ai"},{"id":"hrp2-gestational-trophoblastic-disease~ai-7","moduleId":"hrp2-gestational-trophoblastic-disease","stem":"Which module would provide more detailed information on the management of choriocarcinoma?","options":[{"id":"a","text":"Pre-embryonic Clinical Applications"},{"id":"b","text":"Gestational Trophoblastic Disease: Types and Management"},{"id":"c","text":"Choriocarcinoma & Persistent GTD"},{"id":"d","text":"Basic Embryology"}],"answerId":"c","explanation":"The 'Choriocarcinoma & Persistent GTD' module focuses on the management of choriocarcinoma.","kind":"integration","linkedModuleIds":["hrp2-choriocarcinoma"],"origin":"ai"}],"hrp2-cervix-pathology":[{"id":"hrp2-cervix-pathology~ai-0","moduleId":"hrp2-cervix-pathology","stem":"Which of the following is the primary site for HPV infection leading to cervical dysplasia?","options":[{"id":"a","text":"Transformation zone"},{"id":"b","text":"Endocervical canal"},{"id":"c","text":"Ectocervical surface"},{"id":"d","text":"Vaginal fornix"}],"answerId":"a","explanation":"The transformation zone is where the squamocolumnar junction is located, making it the primary site for HPV infection and subsequent dysplasia.","kind":"recall","origin":"ai"},{"id":"hrp2-cervix-pathology~ai-1","moduleId":"hrp2-cervix-pathology","stem":"What histological finding is indicative of HPV infection on a Pap smear?","options":[{"id":"a","text":"Koilocytes"},{"id":"b","text":"Atypical glandular cells"},{"id":"c","text":"Hyperkeratosis"},{"id":"d","text":"Squamous pearls"}],"answerId":"a","explanation":"Koilocytes are squamous epithelial cells with perinuclear halos and nuclear atypia, characteristic of HPV infection.","kind":"recall","origin":"ai"},{"id":"hrp2-cervix-pathology~ai-2","moduleId":"hrp2-cervix-pathology","stem":"Which factor is most responsible for the decline in cervical cancer incidence?","options":[{"id":"a","text":"HPV vaccination"},{"id":"b","text":"Cervical cytology screening"},{"id":"c","text":"Increased condom use"},{"id":"d","text":"Smoking cessation"}],"answerId":"b","explanation":"Cervical cytology screening detects pre-invasive lesions (CIN), allowing for early intervention and reducing cancer incidence.","kind":"trap","origin":"ai"},{"id":"hrp2-cervix-pathology~ai-3","moduleId":"hrp2-cervix-pathology","stem":"A 65-year-old woman presents with vulvar pruritus and a white plaque. Biopsy shows thinning of the epidermis. What is the most likely diagnosis?","options":[{"id":"a","text":"Lichen sclerosus"},{"id":"b","text":"Vulvar intraepithelial neoplasia"},{"id":"c","text":"Psoriasis"},{"id":"d","text":"Condyloma acuminatum"}],"answerId":"a","explanation":"Lichen sclerosus is characterized by white plaques and epidermal thinning, commonly affecting older women.","kind":"clinical","origin":"ai"},{"id":"hrp2-cervix-pathology~ai-4","moduleId":"hrp2-cervix-pathology","stem":"In the context of cervical pathology, what is the significance of finding CIN3 on a biopsy?","options":[{"id":"a","text":"Low-grade lesion likely to regress"},{"id":"b","text":"High-grade lesion with high risk of progression to cancer"},{"id":"c","text":"Benign lesion with no risk of cancer"},{"id":"d","text":"Invasive cancer requiring immediate treatment"}],"answerId":"b","explanation":"CIN3 is a high-grade lesion with a significant risk of progression to invasive cancer if untreated.","kind":"mechanism","origin":"ai"},{"id":"hrp2-cervix-pathology~ai-5","moduleId":"hrp2-cervix-pathology","stem":"A 30-year-old woman with a history of multiple sexual partners presents for a routine Pap smear. Which linked module would provide foundational knowledge on the histological changes observed in her cervix?","options":[{"id":"a","text":"hrp1-cervix-vagina-histology"},{"id":"b","text":"liver-acinus-gallbladder"},{"id":"c","text":"hrp2-cervical-cancer-screening"},{"id":"d","text":"hrp2-vulvar-vaginal-neoplasia"}],"answerId":"a","explanation":"The histological changes in the cervix, particularly at the transformation zone, are covered in the 'Cervix, Transformation Zone & Vagina Histology' module.","kind":"integration","linkedModuleIds":["hrp1-cervix-vagina-histology"],"origin":"ai"},{"id":"hrp2-cervix-pathology~ai-6","moduleId":"hrp2-cervix-pathology","stem":"Which linked module would provide further information on the management and screening strategies for cervical cancer?","options":[{"id":"a","text":"hrp1-cervix-vagina-histology"},{"id":"b","text":"liver-acinus-gallbladder"},{"id":"c","text":"hrp2-cervical-cancer-screening"},{"id":"d","text":"hrp2-vulvar-vaginal-neoplasia"}],"answerId":"c","explanation":"The 'Cervical Cancer & Screening' module covers management and screening strategies for cervical cancer.","kind":"integration","linkedModuleIds":["hrp2-cervical-cancer-screening"],"origin":"ai"}],"hrp2-uterine-corpus-pathology":[{"id":"hrp2-uterine-corpus-pathology~ai-0","moduleId":"hrp2-uterine-corpus-pathology","stem":"Which of the following is the strongest predictor of progression from endometrial hyperplasia to carcinoma?","options":[{"id":"a","text":"Cytological atypia"},{"id":"b","text":"Amount of hyperplasia"},{"id":"c","text":"Architectural complexity"},{"id":"d","text":"Patient age"}],"answerId":"a","explanation":"Cytological atypia is the strongest predictor of progression to endometrial carcinoma.","kind":"trap","origin":"ai"},{"id":"hrp2-uterine-corpus-pathology~ai-1","moduleId":"hrp2-uterine-corpus-pathology","stem":"A 55-year-old postmenopausal woman presents with vaginal bleeding. What is the most appropriate next step in management?","options":[{"id":"a","text":"Endometrial biopsy"},{"id":"b","text":"Pap smear"},{"id":"c","text":"Hysteroscopy"},{"id":"d","text":"Pelvic MRI"}],"answerId":"a","explanation":"Postmenopausal bleeding is considered endometrial carcinoma until proven otherwise; an endometrial biopsy is indicated.","kind":"clinical","origin":"ai"},{"id":"hrp2-uterine-corpus-pathology~ai-2","moduleId":"hrp2-uterine-corpus-pathology","stem":"Which genetic mutation is commonly associated with Type II endometrial carcinoma?","options":[{"id":"a","text":"PTEN"},{"id":"b","text":"KRAS"},{"id":"c","text":"p53"},{"id":"d","text":"BRCA1"}],"answerId":"c","explanation":"Type II endometrial carcinoma is associated with p53 mutations.","kind":"recall","origin":"ai"},{"id":"hrp2-uterine-corpus-pathology~ai-3","moduleId":"hrp2-uterine-corpus-pathology","stem":"A 45-year-old woman with obesity and anovulation is at risk for which type of endometrial pathology?","options":[{"id":"a","text":"Type I endometrial carcinoma"},{"id":"b","text":"Type II endometrial carcinoma"},{"id":"c","text":"Leiomyosarcoma"},{"id":"d","text":"Endometrial polyp"}],"answerId":"a","explanation":"Obesity and anovulation lead to unopposed estrogen, increasing the risk for Type I endometrial carcinoma.","kind":"mechanism","origin":"ai"},{"id":"hrp2-uterine-corpus-pathology~ai-4","moduleId":"hrp2-uterine-corpus-pathology","stem":"A 30-year-old woman with a history of heavy menstrual bleeding is found to have a uterine mass on ultrasound. Which of the following is the most likely diagnosis?","options":[{"id":"a","text":"Leiomyoma"},{"id":"b","text":"Endometrial carcinoma"},{"id":"c","text":"Adenomyosis"},{"id":"d","text":"Endometrial hyperplasia"}],"answerId":"a","explanation":"Leiomyoma, or fibroid, is the most common uterine tumor and often presents with menorrhagia.","kind":"clinical","origin":"ai"},{"id":"hrp2-uterine-corpus-pathology~ai-5","moduleId":"hrp2-uterine-corpus-pathology","stem":"How does unopposed estrogen lead to endometrial hyperplasia?","options":[{"id":"a","text":"Stimulates glandular proliferation"},{"id":"b","text":"Inhibits stromal growth"},{"id":"c","text":"Decreases progesterone levels"},{"id":"d","text":"Increases androgen production"}],"answerId":"a","explanation":"Unopposed estrogen stimulates glandular proliferation, leading to endometrial hyperplasia.","kind":"mechanism","origin":"ai"},{"id":"hrp2-uterine-corpus-pathology~ai-6","moduleId":"hrp2-uterine-corpus-pathology","stem":"Which condition is characterized by estrogen-sensitive growth and may regress after menopause?","options":[{"id":"a","text":"Leiomyoma"},{"id":"b","text":"Endometrial carcinoma"},{"id":"c","text":"Adenomyosis"},{"id":"d","text":"Endometriosis"}],"answerId":"a","explanation":"Leiomyoma is estrogen-sensitive and often regresses after menopause.","kind":"recall","origin":"ai"},{"id":"hrp2-uterine-corpus-pathology~ai-7","moduleId":"hrp2-uterine-corpus-pathology","stem":"A 35-year-old woman with PCOS is concerned about her risk of endometrial cancer. Which module should she review to understand her risk factors better?","options":[{"id":"a","text":"Endometrial Hyperplasia and Its Risk of Progression to Cancer"},{"id":"b","text":"Uterine Cycle, Ovulation Signs & Hormonal Contraception"},{"id":"c","text":"Endometriosis"},{"id":"d","text":"Leiomyoma, Adenomyosis & Endometrial Polyps"}],"answerId":"a","explanation":"The module on endometrial hyperplasia discusses risk factors related to unopposed estrogen, relevant to PCOS.","kind":"integration","linkedModuleIds":["add-endometrial-hyperplasia-and-its-risk-of-progression-to-c"],"origin":"ai"},{"id":"hrp2-uterine-corpus-pathology~ai-8","moduleId":"hrp2-uterine-corpus-pathology","stem":"In the context of uterine pathology, how does the hormonal cycle influence the growth of leiomyomas?","options":[{"id":"a","text":"Increases during pregnancy"},{"id":"b","text":"Decreases during the luteal phase"},{"id":"c","text":"Unchanged by hormonal fluctuations"},{"id":"d","text":"Decreases with oral contraceptive use"}],"answerId":"a","explanation":"Leiomyomas are estrogen-sensitive, growing during pregnancy due to increased estrogen levels.","kind":"integration","linkedModuleIds":["hrp1-uterine-cycle-fertility-signs"],"origin":"ai"}],"hrp2-hpo-amenorrhea-puberty":[{"id":"hrp2-hpo-amenorrhea-puberty~ai-0","moduleId":"hrp2-hpo-amenorrhea-puberty","stem":"A 16-year-old girl presents with primary amenorrhoea and elevated FSH levels. What is the most likely diagnosis?","options":[{"id":"a","text":"Turner syndrome"},{"id":"b","text":"Kallmann syndrome"},{"id":"c","text":"Constitutional delay"},{"id":"d","text":"Androgen insensitivity syndrome"}],"answerId":"a","explanation":"High FSH levels indicate primary ovarian failure, which is characteristic of Turner syndrome.","kind":"clinical","origin":"ai"},{"id":"hrp2-hpo-amenorrhea-puberty~ai-1","moduleId":"hrp2-hpo-amenorrhea-puberty","stem":"Which hormone pattern is expected in a patient with hypothalamic amenorrhoea due to excessive exercise?","options":[{"id":"a","text":"High FSH, high LH"},{"id":"b","text":"Low FSH, low LH"},{"id":"c","text":"High FSH, low LH"},{"id":"d","text":"Normal FSH, high LH"}],"answerId":"b","explanation":"Hypothalamic amenorrhoea results in low GnRH, leading to low FSH and LH levels.","kind":"mechanism","origin":"ai"},{"id":"hrp2-hpo-amenorrhea-puberty~ai-2","moduleId":"hrp2-hpo-amenorrhea-puberty","stem":"A 14-year-old boy presents with delayed puberty and anosmia. What is the most likely diagnosis?","options":[{"id":"a","text":"Klinefelter syndrome"},{"id":"b","text":"Constitutional delay"},{"id":"c","text":"Kallmann syndrome"},{"id":"d","text":"Turner syndrome"}],"answerId":"c","explanation":"Anosmia and delayed puberty are indicative of Kallmann syndrome, a condition with low GnRH.","kind":"clinical","origin":"ai"},{"id":"hrp2-hpo-amenorrhea-puberty~ai-3","moduleId":"hrp2-hpo-amenorrhea-puberty","stem":"A 25-year-old woman with secondary amenorrhoea has a raised LH:FSH ratio and signs of hyperandrogenism. What is the most likely diagnosis?","options":[{"id":"a","text":"Hypothalamic amenorrhoea"},{"id":"b","text":"Premature ovarian insufficiency"},{"id":"c","text":"Polycystic ovary syndrome"},{"id":"d","text":"Hyperprolactinaemia"}],"answerId":"c","explanation":"PCOS is characterized by a raised LH:FSH ratio and hyperandrogenism.","kind":"clinical","origin":"ai"},{"id":"hrp2-hpo-amenorrhea-puberty~ai-4","moduleId":"hrp2-hpo-amenorrhea-puberty","stem":"Which condition is characterized by primary amenorrhoea, normal secondary sexual characteristics, and an absent uterus?","options":[{"id":"a","text":"Turner syndrome"},{"id":"b","text":"Müllerian agenesis"},{"id":"c","text":"Kallmann syndrome"},{"id":"d","text":"Constitutional delay"}],"answerId":"b","explanation":"Müllerian agenesis presents with primary amenorrhoea and normal secondary sexual characteristics due to the absence of the uterus.","kind":"recall","origin":"ai"},{"id":"hrp2-hpo-amenorrhea-puberty~ai-5","moduleId":"hrp2-hpo-amenorrhea-puberty","stem":"A 7-year-old girl presents with breast development and pubic hair. Her FSH and LH levels are elevated. What is the most likely cause?","options":[{"id":"a","text":"Peripheral precocious puberty"},{"id":"b","text":"Central precocious puberty"},{"id":"c","text":"Constitutional delay"},{"id":"d","text":"Androgen insensitivity syndrome"}],"answerId":"b","explanation":"Elevated FSH and LH suggest central precocious puberty due to early activation of the HPO axis.","kind":"integration","linkedModuleIds":["hrp1-central-precocious-puberty"],"origin":"ai"},{"id":"hrp2-hpo-amenorrhea-puberty~ai-6","moduleId":"hrp2-hpo-amenorrhea-puberty","stem":"A 15-year-old girl has not started menstruating and has no breast development. Her FSH and LH levels are low. What is the most likely diagnosis?","options":[{"id":"a","text":"Turner syndrome"},{"id":"b","text":"Kallmann syndrome"},{"id":"c","text":"Constitutional delay"},{"id":"d","text":"Androgen insensitivity syndrome"}],"answerId":"b","explanation":"Low FSH and LH with lack of secondary sexual characteristics suggest Kallmann syndrome.","kind":"integration","linkedModuleIds":["hrp1-delayed-puberty"],"origin":"ai"}],"hrp2-male-repro-pathology":[{"id":"hrp2-male-repro-pathology~ai-0","moduleId":"hrp2-male-repro-pathology","stem":"A 32-year-old man presents with a painless testicular mass. Serum markers show elevated AFP and β-hCG. What is the most likely diagnosis?","options":[{"id":"a","text":"Seminoma"},{"id":"b","text":"Non-seminomatous germ cell tumor"},{"id":"c","text":"Leydig cell tumor"},{"id":"d","text":"Sertoli cell tumor"}],"answerId":"b","explanation":"Elevated AFP and β-hCG suggest a non-seminomatous germ cell tumor, as seminomas do not raise AFP.","kind":"clinical","origin":"ai"},{"id":"hrp2-male-repro-pathology~ai-1","moduleId":"hrp2-male-repro-pathology","stem":"Which zone of the prostate is most commonly affected by benign prostatic hyperplasia (BPH)?","options":[{"id":"a","text":"Peripheral zone"},{"id":"b","text":"Central zone"},{"id":"c","text":"Transitional zone"},{"id":"d","text":"Anterior fibromuscular stroma"}],"answerId":"c","explanation":"BPH involves nodular hyperplasia of the transitional zone, leading to bladder outflow obstruction.","kind":"recall","origin":"ai"},{"id":"hrp2-male-repro-pathology~ai-2","moduleId":"hrp2-male-repro-pathology","stem":"A 68-year-old male is found to have osteoblastic lesions on a bone scan. Which condition is most likely responsible?","options":[{"id":"a","text":"Benign prostatic hyperplasia"},{"id":"b","text":"Prostate adenocarcinoma"},{"id":"c","text":"Testicular torsion"},{"id":"d","text":"Varicocele"}],"answerId":"b","explanation":"Prostate adenocarcinoma often metastasizes to bone, causing osteoblastic (sclerotic) lesions.","kind":"clinical","origin":"ai"},{"id":"hrp2-male-repro-pathology~ai-3","moduleId":"hrp2-male-repro-pathology","stem":"A patient with a history of cryptorchidism is at increased risk for which of the following?","options":[{"id":"a","text":"Prostate adenocarcinoma"},{"id":"b","text":"Benign prostatic hyperplasia"},{"id":"c","text":"Germ cell tumor"},{"id":"d","text":"Penile squamous cell carcinoma"}],"answerId":"c","explanation":"Cryptorchidism increases the risk of developing germ cell tumors.","kind":"recall","origin":"ai"},{"id":"hrp2-male-repro-pathology~ai-4","moduleId":"hrp2-male-repro-pathology","stem":"Which of the following markers is NOT elevated in pure seminoma?","options":[{"id":"a","text":"LDH"},{"id":"b","text":"Placental ALP"},{"id":"c","text":"AFP"},{"id":"d","text":"β-hCG"}],"answerId":"c","explanation":"AFP is not elevated in pure seminoma; its elevation suggests a non-seminomatous component.","kind":"trap","origin":"ai"},{"id":"hrp2-male-repro-pathology~ai-5","moduleId":"hrp2-male-repro-pathology","stem":"A 25-year-old male presents with a 'bag of worms' sensation in the scrotum. What is the most likely diagnosis?","options":[{"id":"a","text":"Testicular torsion"},{"id":"b","text":"Epididymitis"},{"id":"c","text":"Varicocele"},{"id":"d","text":"Hydrocele"}],"answerId":"c","explanation":"A 'bag of worms' sensation is characteristic of a varicocele, often left-sided.","kind":"clinical","origin":"ai"},{"id":"hrp2-male-repro-pathology~ai-6","moduleId":"hrp2-male-repro-pathology","stem":"Which structure is primarily responsible for the production of seminal fluid in the male reproductive system?","options":[{"id":"a","text":"Prostate gland"},{"id":"b","text":"Seminal vesicles"},{"id":"c","text":"Bulbourethral glands"},{"id":"d","text":"Epididymis"}],"answerId":"b","explanation":"The seminal vesicles produce the majority of the seminal fluid.","kind":"integration","linkedModuleIds":["hrp1-male-accessory-glands-anatomy"],"origin":"ai"},{"id":"hrp2-male-repro-pathology~ai-7","moduleId":"hrp2-male-repro-pathology","stem":"A young male presents with acute scrotal pain and absent cremasteric reflex. What is the most likely diagnosis?","options":[{"id":"a","text":"Epididymitis"},{"id":"b","text":"Testicular torsion"},{"id":"c","text":"Varicocele"},{"id":"d","text":"Hydrocele"}],"answerId":"b","explanation":"Acute scrotal pain with an absent cremasteric reflex suggests testicular torsion, a surgical emergency.","kind":"clinical","origin":"ai"},{"id":"hrp2-male-repro-pathology~ai-8","moduleId":"hrp2-male-repro-pathology","stem":"Which hormone is crucial for the initiation of spermatogenesis in the seminiferous tubules?","options":[{"id":"a","text":"Testosterone"},{"id":"b","text":"FSH"},{"id":"c","text":"LH"},{"id":"d","text":"Prolactin"}],"answerId":"b","explanation":"FSH is crucial for the initiation and maintenance of spermatogenesis in the seminiferous tubules.","kind":"integration","linkedModuleIds":["hrp1-seminiferous-epithelium-spermatogenesis"],"origin":"ai"}],"hrp2-breast-pathology":[{"id":"hrp2-breast-pathology~ai-0","moduleId":"hrp2-breast-pathology","stem":"A 25-year-old woman presents with a mobile, well-circumscribed breast lump. What is the most likely diagnosis?","options":[{"id":"a","text":"Fibroadenoma"},{"id":"b","text":"Intraductal papilloma"},{"id":"c","text":"Phyllodes tumor"},{"id":"d","text":"Invasive ductal carcinoma"}],"answerId":"a","explanation":"Fibroadenoma is common in young women and presents as a mobile, well-circumscribed lump.","kind":"recall","origin":"ai"},{"id":"hrp2-breast-pathology~ai-1","moduleId":"hrp2-breast-pathology","stem":"A mammogram shows microcalcifications in a 50-year-old woman. Biopsy reveals malignant cells confined by the basement membrane. What is the diagnosis?","options":[{"id":"a","text":"Invasive ductal carcinoma"},{"id":"b","text":"Invasive lobular carcinoma"},{"id":"c","text":"Ductal carcinoma in situ (DCIS)"},{"id":"d","text":"Lobular carcinoma in situ (LCIS)"}],"answerId":"c","explanation":"DCIS is characterized by malignant cells confined by the basement membrane, often presenting with microcalcifications.","kind":"recall","origin":"ai"},{"id":"hrp2-breast-pathology~ai-2","moduleId":"hrp2-breast-pathology","stem":"A breast biopsy shows single-file infiltration of cells with E-cadherin loss. What is the most likely diagnosis?","options":[{"id":"a","text":"Invasive ductal carcinoma"},{"id":"b","text":"Invasive lobular carcinoma"},{"id":"c","text":"Ductal carcinoma in situ"},{"id":"d","text":"Phyllodes tumor"}],"answerId":"b","explanation":"Invasive lobular carcinoma is characterized by single-file infiltration and E-cadherin loss.","kind":"mechanism","origin":"ai"},{"id":"hrp2-breast-pathology~ai-3","moduleId":"hrp2-breast-pathology","stem":"A patient with a history of breast cancer presents with an eczematous lesion on the nipple. What is the most likely underlying pathology?","options":[{"id":"a","text":"Invasive ductal carcinoma"},{"id":"b","text":"Paget disease of the nipple"},{"id":"c","text":"Intraductal papilloma"},{"id":"d","text":"Fibrocystic change"}],"answerId":"b","explanation":"Paget disease of the nipple is associated with DCIS extending to the nipple epidermis, presenting as an eczematous lesion.","kind":"clinical","origin":"ai"},{"id":"hrp2-breast-pathology~ai-4","moduleId":"hrp2-breast-pathology","stem":"Which molecular marker is targeted by trastuzumab in breast cancer therapy?","options":[{"id":"a","text":"ER"},{"id":"b","text":"PR"},{"id":"c","text":"HER2"},{"id":"d","text":"BRCA1"}],"answerId":"c","explanation":"Trastuzumab targets the HER2 receptor, which is overexpressed in some breast cancers.","kind":"recall","origin":"ai"},{"id":"hrp2-breast-pathology~ai-5","moduleId":"hrp2-breast-pathology","stem":"A 45-year-old woman presents with bloody nipple discharge. Which condition should be considered?","options":[{"id":"a","text":"Fibroadenoma"},{"id":"b","text":"Intraductal papilloma"},{"id":"c","text":"Fibrocystic change"},{"id":"d","text":"Phyllodes tumor"}],"answerId":"b","explanation":"Intraductal papilloma can cause bloody nipple discharge.","kind":"clinical","origin":"ai"},{"id":"hrp2-breast-pathology~ai-6","moduleId":"hrp2-breast-pathology","stem":"A breast biopsy shows cells growing in single-file lines. Which diagnostic method can confirm the loss of E-cadherin?","options":[{"id":"a","text":"Flow cytometry"},{"id":"b","text":"Immunohistochemistry"},{"id":"c","text":"Hematoxylin and eosin staining"},{"id":"d","text":"Electron microscopy"}],"answerId":"b","explanation":"Immunohistochemistry can be used to confirm the loss of E-cadherin in invasive lobular carcinoma.","kind":"integration","linkedModuleIds":["diagnostic-pathology-methods"],"origin":"ai"},{"id":"hrp2-breast-pathology~ai-7","moduleId":"hrp2-breast-pathology","stem":"A 30-year-old woman presents with a breast lump. Imaging shows a leaf-like stromal pattern. What is the most likely diagnosis?","options":[{"id":"a","text":"Fibroadenoma"},{"id":"b","text":"Phyllodes tumor"},{"id":"c","text":"Invasive ductal carcinoma"},{"id":"d","text":"Intraductal papilloma"}],"answerId":"b","explanation":"Phyllodes tumor is characterized by a leaf-like stromal pattern on imaging.","kind":"recall","origin":"ai"},{"id":"hrp2-breast-pathology~ai-8","moduleId":"hrp2-breast-pathology","stem":"A breast cancer patient is ER/PR-positive but HER2-negative. What is the most appropriate therapy?","options":[{"id":"a","text":"Trastuzumab"},{"id":"b","text":"Chemotherapy"},{"id":"c","text":"Endocrine therapy"},{"id":"d","text":"Radiation therapy"}],"answerId":"c","explanation":"ER/PR-positive breast cancers are treated with endocrine therapy such as tamoxifen or aromatase inhibitors.","kind":"integration","linkedModuleIds":["hrp2-breast-carcinoma-types"],"origin":"ai"}],"hrp2-abnormal-uterine-bleeding":[{"id":"hrp2-abnormal-uterine-bleeding~ai-0","moduleId":"hrp2-abnormal-uterine-bleeding","stem":"A 16-year-old girl presents with heavy menstrual bleeding since menarche. What is the most appropriate initial investigation?","options":[{"id":"a","text":"Coagulation profile"},{"id":"b","text":"Pelvic ultrasound"},{"id":"c","text":"Endometrial biopsy"},{"id":"d","text":"Hormonal profile"}],"answerId":"a","explanation":"In adolescents with heavy menstrual bleeding from menarche, screen for a coagulopathy such as von Willebrand disease.","kind":"recall","origin":"ai"},{"id":"hrp2-abnormal-uterine-bleeding~ai-1","moduleId":"hrp2-abnormal-uterine-bleeding","stem":"A 52-year-old woman presents with postmenopausal bleeding. What is the next best step in management?","options":[{"id":"a","text":"Start hormone replacement therapy"},{"id":"b","text":"Perform an endometrial biopsy"},{"id":"c","text":"Prescribe tranexamic acid"},{"id":"d","text":"Order a pelvic MRI"}],"answerId":"b","explanation":"Postmenopausal bleeding requires endometrial assessment to exclude hyperplasia or carcinoma.","kind":"trap","origin":"ai"},{"id":"hrp2-abnormal-uterine-bleeding~ai-2","moduleId":"hrp2-abnormal-uterine-bleeding","stem":"A 30-year-old woman with PCOS presents with irregular menstrual cycles. What is the underlying mechanism for her abnormal uterine bleeding?","options":[{"id":"a","text":"Unopposed estrogen"},{"id":"b","text":"Progesterone deficiency"},{"id":"c","text":"Endometrial hyperplasia"},{"id":"d","text":"Coagulopathy"}],"answerId":"a","explanation":"Irregular cycles in PCOS are due to anovulation, leading to unopposed estrogen and an unstable endometrium.","kind":"mechanism","origin":"ai"},{"id":"hrp2-abnormal-uterine-bleeding~ai-3","moduleId":"hrp2-abnormal-uterine-bleeding","stem":"A 45-year-old woman has heavy menstrual bleeding and an enlarged, irregular uterus on examination. What is the most likely diagnosis?","options":[{"id":"a","text":"Polyp"},{"id":"b","text":"Adenomyosis"},{"id":"c","text":"Leiomyoma"},{"id":"d","text":"Endometrial hyperplasia"}],"answerId":"c","explanation":"An enlarged, irregular uterus suggests a structural cause such as fibroids (leiomyoma).","kind":"clinical","origin":"ai"},{"id":"hrp2-abnormal-uterine-bleeding~ai-4","moduleId":"hrp2-abnormal-uterine-bleeding","stem":"A 28-year-old woman with heavy menstrual bleeding is found to have a normal coagulation profile. Which of the following is the most likely cause?","options":[{"id":"a","text":"Ovulatory dysfunction"},{"id":"b","text":"Endometrial polyp"},{"id":"c","text":"Iatrogenic cause"},{"id":"d","text":"Not-yet-classified"}],"answerId":"a","explanation":"Ovulatory dysfunction is a common cause of abnormal uterine bleeding in women of reproductive age.","kind":"clinical","origin":"ai"},{"id":"hrp2-abnormal-uterine-bleeding~ai-5","moduleId":"hrp2-abnormal-uterine-bleeding","stem":"A 35-year-old woman with dysmenorrhea and menorrhagia is suspected to have adenomyosis. Which linked module is relevant for further study?","options":[{"id":"a","text":"hrp2-dysmenorrhea-menorrhagia"},{"id":"b","text":"hrp2-ovarian-cysts"},{"id":"c","text":"hrp2-endometriosis"},{"id":"d","text":"hrp2-pelvic-inflammatory-disease"}],"answerId":"a","explanation":"The linked module 'Dysmenorrhoea & Heavy Menstrual Bleeding' is relevant for further study.","kind":"integration","linkedModuleIds":["hrp2-dysmenorrhea-menorrhagia"],"origin":"ai"},{"id":"hrp2-abnormal-uterine-bleeding~ai-6","moduleId":"hrp2-abnormal-uterine-bleeding","stem":"A 50-year-old woman presents with heavy menstrual bleeding and is found to have endometrial hyperplasia. Which of the following treatments is most appropriate?","options":[{"id":"a","text":"Tranexamic acid"},{"id":"b","text":"Combined oral contraceptives"},{"id":"c","text":"Progestin therapy"},{"id":"d","text":"Endometrial ablation"}],"answerId":"c","explanation":"Progestin therapy is used to regulate and thin the endometrium in cases of endometrial hyperplasia.","kind":"clinical","origin":"ai"},{"id":"hrp2-abnormal-uterine-bleeding~ai-7","moduleId":"hrp2-abnormal-uterine-bleeding","stem":"A 19-year-old woman with heavy menstrual bleeding is being evaluated for potential coagulopathy. Which linked module would provide additional insights into her condition?","options":[{"id":"a","text":"hrp2-dysmenorrhea-menorrhagia"},{"id":"b","text":"hrp2-ovarian-cysts"},{"id":"c","text":"hrp2-endometriosis"},{"id":"d","text":"hrp2-pelvic-inflammatory-disease"}],"answerId":"a","explanation":"The linked module 'Dysmenorrhoea & Heavy Menstrual Bleeding' provides additional insights into conditions like coagulopathy.","kind":"integration","linkedModuleIds":["hrp2-dysmenorrhea-menorrhagia"],"origin":"ai"}],"hrp2-pregnancy-disorders":[{"id":"hrp2-pregnancy-disorders~ai-0","moduleId":"hrp2-pregnancy-disorders","stem":"A 30-year-old woman at 32 weeks gestation presents with new-onset hypertension and proteinuria. What is the most likely underlying cause of her condition?","options":[{"id":"a","text":"Abnormal spiral-artery remodeling"},{"id":"b","text":"Increased insulin resistance"},{"id":"c","text":"Rh isoimmunisation"},{"id":"d","text":"Tubal implantation"}],"answerId":"a","explanation":"Pre-eclampsia is primarily due to abnormal spiral-artery remodeling leading to placental ischemia and endothelial dysfunction.","kind":"mechanism","origin":"ai"},{"id":"hrp2-pregnancy-disorders~ai-1","moduleId":"hrp2-pregnancy-disorders","stem":"A pregnant woman with a history of pelvic inflammatory disease presents with amenorrhea, pelvic pain, and vaginal bleeding. Her β-hCG levels are rising abnormally, and ultrasound shows an empty uterus. What is the most likely diagnosis?","options":[{"id":"a","text":"Ectopic pregnancy"},{"id":"b","text":"Gestational trophoblastic disease"},{"id":"c","text":"Placenta praevia"},{"id":"d","text":"Threatened miscarriage"}],"answerId":"a","explanation":"The presentation is classic for an ectopic pregnancy, especially with a history of PID and abnormal β-hCG rise.","kind":"clinical","origin":"ai"},{"id":"hrp2-pregnancy-disorders~ai-2","moduleId":"hrp2-pregnancy-disorders","stem":"A 28-year-old pregnant woman presents with painless vaginal bleeding at 34 weeks gestation. What is the most likely diagnosis?","options":[{"id":"a","text":"Placenta praevia"},{"id":"b","text":"Placental abruption"},{"id":"c","text":"Ectopic pregnancy"},{"id":"d","text":"Pre-eclampsia"}],"answerId":"a","explanation":"Painless bleeding in the third trimester is characteristic of placenta praevia.","kind":"recall","origin":"ai"},{"id":"hrp2-pregnancy-disorders~ai-3","moduleId":"hrp2-pregnancy-disorders","stem":"A 35-year-old woman at 36 weeks gestation presents with painful vaginal bleeding and a tense, tender uterus. Which condition is most likely?","options":[{"id":"a","text":"Placenta praevia"},{"id":"b","text":"Placental abruption"},{"id":"c","text":"Ectopic pregnancy"},{"id":"d","text":"Gestational diabetes"}],"answerId":"b","explanation":"Painful bleeding with a tense uterus suggests placental abruption.","kind":"trap","origin":"ai"},{"id":"hrp2-pregnancy-disorders~ai-4","moduleId":"hrp2-pregnancy-disorders","stem":"A pregnant woman is diagnosed with gestational diabetes. Which fetal complication is most commonly associated with this condition?","options":[{"id":"a","text":"Macrosomia"},{"id":"b","text":"Neural tube defects"},{"id":"c","text":"Oligohydramnios"},{"id":"d","text":"Preterm birth"}],"answerId":"a","explanation":"Gestational diabetes often leads to fetal macrosomia due to increased glucose transfer to the fetus.","kind":"recall","origin":"ai"},{"id":"hrp2-pregnancy-disorders~ai-5","moduleId":"hrp2-pregnancy-disorders","stem":"A 29-year-old Rh-negative woman is pregnant with an Rh-positive fetus. Which intervention can prevent hemolytic disease of the newborn?","options":[{"id":"a","text":"Anti-D immunoglobulin"},{"id":"b","text":"Magnesium sulfate"},{"id":"c","text":"Insulin therapy"},{"id":"d","text":"Corticosteroids"}],"answerId":"a","explanation":"Administering anti-D immunoglobulin prevents Rh isoimmunisation and subsequent hemolytic disease of the newborn.","kind":"recall","origin":"ai"},{"id":"hrp2-pregnancy-disorders~ai-6","moduleId":"hrp2-pregnancy-disorders","stem":"A 32-year-old woman at 28 weeks gestation is diagnosed with pre-eclampsia. Which linked module would provide additional information on the pathophysiology and management of her condition?","options":[{"id":"a","text":"Pre-eclampsia: Pathophysiology and Management"},{"id":"b","text":"Proteinuria: Evaluation & Significance"},{"id":"c","text":"Gestational Diabetes Mellitus"},{"id":"d","text":"Rh Isoimmunisation & Haemolytic Disease of the Newborn"}],"answerId":"a","explanation":"The linked module 'Pre-eclampsia: Pathophysiology and Management' provides detailed information on this condition.","kind":"integration","linkedModuleIds":["add-pre-eclampsia-pathophysiology-and-management"],"origin":"ai"},{"id":"hrp2-pregnancy-disorders~ai-7","moduleId":"hrp2-pregnancy-disorders","stem":"A pregnant woman is screened for gestational diabetes. Which linked module would provide more information on the management of this condition?","options":[{"id":"a","text":"Pre-eclampsia: Pathophysiology and Management"},{"id":"b","text":"Proteinuria: Evaluation & Significance"},{"id":"c","text":"Gestational Diabetes Mellitus"},{"id":"d","text":"Rh Isoimmunisation & Haemolytic Disease of the Newborn"}],"answerId":"c","explanation":"The linked module 'Gestational Diabetes Mellitus' offers comprehensive information on the management of gestational diabetes.","kind":"integration","linkedModuleIds":["hrp2-gestational-diabetes"],"origin":"ai"}],"hrp2-perinatal-jaundice":[{"id":"hrp2-perinatal-jaundice~ai-0","moduleId":"hrp2-perinatal-jaundice","stem":"A newborn presents with jaundice within the first 24 hours of life. What is the most likely cause?","options":[{"id":"a","text":"Rh incompatibility"},{"id":"b","text":"Breast-milk jaundice"},{"id":"c","text":"Physiological jaundice"},{"id":"d","text":"Biliary atresia"}],"answerId":"a","explanation":"Jaundice within the first 24 hours is usually due to haemolysis, commonly from Rh incompatibility.","kind":"recall","origin":"ai"},{"id":"hrp2-perinatal-jaundice~ai-1","moduleId":"hrp2-perinatal-jaundice","stem":"Which type of hyperbilirubinemia in a neonate is always considered pathological?","options":[{"id":"a","text":"Unconjugated hyperbilirubinemia"},{"id":"b","text":"Conjugated hyperbilirubinemia"},{"id":"c","text":"Physiological jaundice"},{"id":"d","text":"Breast-milk jaundice"}],"answerId":"b","explanation":"Conjugated hyperbilirubinemia is always pathological and can indicate conditions like biliary atresia.","kind":"trap","origin":"ai"},{"id":"hrp2-perinatal-jaundice~ai-2","moduleId":"hrp2-perinatal-jaundice","stem":"A 2-week-old infant presents with prolonged jaundice, pale stools, and dark urine. What is the most likely diagnosis?","options":[{"id":"a","text":"Breast-milk jaundice"},{"id":"b","text":"Physiological jaundice"},{"id":"c","text":"Biliary atresia"},{"id":"d","text":"G6PD deficiency"}],"answerId":"c","explanation":"The combination of prolonged jaundice, pale stools, and dark urine suggests biliary atresia.","kind":"clinical","origin":"ai"},{"id":"hrp2-perinatal-jaundice~ai-3","moduleId":"hrp2-perinatal-jaundice","stem":"What is the primary mechanism by which phototherapy treats neonatal jaundice?","options":[{"id":"a","text":"Enhances bilirubin conjugation"},{"id":"b","text":"Converts bilirubin to water-soluble isomers"},{"id":"c","text":"Increases red blood cell turnover"},{"id":"d","text":"Reduces bilirubin production"}],"answerId":"b","explanation":"Phototherapy converts bilirubin to water-soluble isomers that can be excreted without conjugation.","kind":"mechanism","origin":"ai"},{"id":"hrp2-perinatal-jaundice~ai-4","moduleId":"hrp2-perinatal-jaundice","stem":"A newborn with jaundice has a bilirubin level that rapidly rises despite phototherapy. What is the next step in management?","options":[{"id":"a","text":"Increase phototherapy intensity"},{"id":"b","text":"Start exchange transfusion"},{"id":"c","text":"Administer intravenous fluids"},{"id":"d","text":"Observe and reassess in 24 hours"}],"answerId":"b","explanation":"Rapidly rising bilirubin levels despite phototherapy may require exchange transfusion to prevent kernicterus.","kind":"clinical","origin":"ai"},{"id":"hrp2-perinatal-jaundice~ai-5","moduleId":"hrp2-perinatal-jaundice","stem":"A 5-day-old infant is exclusively breastfed and presents with jaundice. The infant is feeding well and gaining weight. What is the most likely cause of the jaundice?","options":[{"id":"a","text":"Breast-milk jaundice"},{"id":"b","text":"Breastfeeding failure jaundice"},{"id":"c","text":"Physiological jaundice"},{"id":"d","text":"Biliary atresia"}],"answerId":"a","explanation":"Breast-milk jaundice typically presents around the first week of life in well-feeding infants.","kind":"clinical","origin":"ai"},{"id":"hrp2-perinatal-jaundice~ai-6","moduleId":"hrp2-perinatal-jaundice","stem":"In the context of neonatal jaundice, which condition is characterized by pale stools and dark urine?","options":[{"id":"a","text":"Physiological jaundice"},{"id":"b","text":"Breast-milk jaundice"},{"id":"c","text":"Biliary atresia"},{"id":"d","text":"G6PD deficiency"}],"answerId":"c","explanation":"Biliary atresia is characterized by pale stools and dark urine due to obstructed bile flow.","kind":"recall","origin":"ai"},{"id":"hrp2-perinatal-jaundice~ai-7","moduleId":"hrp2-perinatal-jaundice","stem":"A newborn with jaundice is found to have a high level of unconjugated bilirubin. Which linked module would provide detailed information on bilirubin metabolism?","options":[{"id":"a","text":"Neonatal Jaundice: Management"},{"id":"b","text":"Bilirubin Metabolism & Jaundice"},{"id":"c","text":"Neonatal Resuscitation"},{"id":"d","text":"Pediatric Nutrition"}],"answerId":"b","explanation":"The 'Bilirubin Metabolism & Jaundice' module provides detailed information on bilirubin metabolism.","kind":"integration","linkedModuleIds":["bilirubin-metabolism-jaundice"],"origin":"ai"},{"id":"hrp2-perinatal-jaundice~ai-8","moduleId":"hrp2-perinatal-jaundice","stem":"Which management strategy is most appropriate for a neonate with jaundice due to Rh incompatibility?","options":[{"id":"a","text":"Immediate exchange transfusion"},{"id":"b","text":"Phototherapy"},{"id":"c","text":"Intravenous immunoglobulin"},{"id":"d","text":"Observation"}],"answerId":"a","explanation":"Severe jaundice due to Rh incompatibility often requires immediate exchange transfusion to prevent kernicterus.","kind":"integration","linkedModuleIds":["hrp2-jaundice-management"],"origin":"ai"}],"hrp2-androgen-drugs":[{"id":"hrp2-androgen-drugs~ai-0","moduleId":"hrp2-androgen-drugs","stem":"Which enzyme converts testosterone to dihydrotestosterone (DHT) in target tissues?","options":[{"id":"a","text":"5α-reductase"},{"id":"b","text":"Aromatase"},{"id":"c","text":"11β-hydroxylase"},{"id":"d","text":"17α-hydroxylase"}],"answerId":"a","explanation":"5α-reductase converts testosterone to the more potent androgen DHT in tissues like the prostate and skin.","kind":"recall","origin":"ai"},{"id":"hrp2-androgen-drugs~ai-1","moduleId":"hrp2-androgen-drugs","stem":"A patient on finasteride for BPH shows a PSA level of 2.5 ng/mL. What is the estimated true PSA level?","options":[{"id":"a","text":"1.25 ng/mL"},{"id":"b","text":"2.5 ng/mL"},{"id":"c","text":"5.0 ng/mL"},{"id":"d","text":"10.0 ng/mL"}],"answerId":"c","explanation":"Finasteride lowers PSA by approximately 50%, so the true PSA level is estimated by doubling the measured value.","kind":"mechanism","origin":"ai"},{"id":"hrp2-androgen-drugs~ai-2","moduleId":"hrp2-androgen-drugs","stem":"Which of the following is a potential side effect of anabolic steroid abuse?","options":[{"id":"a","text":"Increased spermatogenesis"},{"id":"b","text":"Testicular atrophy"},{"id":"c","text":"Decreased aggression"},{"id":"d","text":"Improved HDL levels"}],"answerId":"b","explanation":"Anabolic steroid abuse can lead to testicular atrophy due to suppression of endogenous testosterone production.","kind":"clinical","origin":"ai"},{"id":"hrp2-androgen-drugs~ai-3","moduleId":"hrp2-androgen-drugs","stem":"A man with prostate cancer is started on a GnRH agonist. What should be co-administered to prevent an initial testosterone flare?","options":[{"id":"a","text":"Aromatase inhibitor"},{"id":"b","text":"Androgen-receptor antagonist"},{"id":"c","text":"5α-reductase inhibitor"},{"id":"d","text":"Corticosteroid"}],"answerId":"b","explanation":"Androgen-receptor antagonists are used to prevent the effects of the initial testosterone surge caused by GnRH agonists.","kind":"mechanism","origin":"ai"},{"id":"hrp2-androgen-drugs~ai-4","moduleId":"hrp2-androgen-drugs","stem":"Why is exogenous testosterone not used as a fertility treatment in men?","options":[{"id":"a","text":"It increases estrogen levels"},{"id":"b","text":"It suppresses the HPG axis"},{"id":"c","text":"It causes testicular enlargement"},{"id":"d","text":"It enhances spermatogenesis"}],"answerId":"b","explanation":"Exogenous testosterone suppresses the HPG axis, reducing FSH and LH, which decreases spermatogenesis.","kind":"trap","origin":"ai"},{"id":"hrp2-androgen-drugs~ai-5","moduleId":"hrp2-androgen-drugs","stem":"Which drug is used to treat hirsutism in women by blocking androgen receptors?","options":[{"id":"a","text":"Finasteride"},{"id":"b","text":"Spironolactone"},{"id":"c","text":"Testosterone"},{"id":"d","text":"Flutamide"}],"answerId":"b","explanation":"Spironolactone acts as an androgen-receptor antagonist and is used to treat hirsutism in women.","kind":"clinical","origin":"ai"},{"id":"hrp2-androgen-drugs~ai-6","moduleId":"hrp2-androgen-drugs","stem":"How does the conversion of testosterone to estradiol occur?","options":[{"id":"a","text":"5α-reductase"},{"id":"b","text":"Aromatase"},{"id":"c","text":"11β-hydroxylase"},{"id":"d","text":"17α-hydroxylase"}],"answerId":"b","explanation":"Aromatase converts testosterone to estradiol, an important pathway in both men and women.","kind":"integration","linkedModuleIds":["cholesterol-bile-steroids"],"origin":"ai"},{"id":"hrp2-androgen-drugs~ai-7","moduleId":"hrp2-androgen-drugs","stem":"In the context of adrenal androgens, which enzyme deficiency might lead to excess androgen production?","options":[{"id":"a","text":"21-hydroxylase"},{"id":"b","text":"5α-reductase"},{"id":"c","text":"Aromatase"},{"id":"d","text":"11β-hydroxylase"}],"answerId":"a","explanation":"21-hydroxylase deficiency leads to excess adrenal androgen production due to shunting of precursors.","kind":"integration","linkedModuleIds":["hen1-adrenal-androgens"],"origin":"ai"}],"hrp2-female-hormones-drugs":[{"id":"hrp2-female-hormones-drugs~ai-0","moduleId":"hrp2-female-hormones-drugs","stem":"Which of the following is the primary mechanism by which combined oral contraceptives prevent pregnancy?","options":[{"id":"a","text":"Suppression of the hypothalamic-pituitary-ovarian axis"},{"id":"b","text":"Thickening of cervical mucus"},{"id":"c","text":"Thinning of the endometrium"},{"id":"d","text":"Inhibition of sperm motility"}],"answerId":"a","explanation":"Combined oral contraceptives primarily work by suppressing the HPO axis, preventing the LH surge and ovulation.","kind":"recall","origin":"ai"},{"id":"hrp2-female-hormones-drugs~ai-1","moduleId":"hrp2-female-hormones-drugs","stem":"A 45-year-old woman with a history of ER-positive breast cancer is prescribed tamoxifen. What is a potential risk associated with this treatment?","options":[{"id":"a","text":"Increased risk of osteoporosis"},{"id":"b","text":"Increased risk of endometrial cancer"},{"id":"c","text":"Increased risk of thromboembolism"},{"id":"d","text":"Increased risk of ovarian cancer"}],"answerId":"b","explanation":"Tamoxifen acts as an agonist on endometrial estrogen receptors, increasing the risk of endometrial cancer.","kind":"recall","origin":"ai"},{"id":"hrp2-female-hormones-drugs~ai-2","moduleId":"hrp2-female-hormones-drugs","stem":"Which drug is used for ovulation induction by acting as an anti-estrogen at the hypothalamus?","options":[{"id":"a","text":"Tamoxifen"},{"id":"b","text":"Clomiphene"},{"id":"c","text":"Anastrozole"},{"id":"d","text":"Mifepristone"}],"answerId":"b","explanation":"Clomiphene is an anti-estrogen at the hypothalamus, leading to increased FSH and LH and inducing ovulation.","kind":"recall","origin":"ai"},{"id":"hrp2-female-hormones-drugs~ai-3","moduleId":"hrp2-female-hormones-drugs","stem":"A postmenopausal woman with ER-positive breast cancer is experiencing bone loss. Which medication is likely causing this side effect?","options":[{"id":"a","text":"Tamoxifen"},{"id":"b","text":"Raloxifene"},{"id":"c","text":"Anastrozole"},{"id":"d","text":"Clomiphene"}],"answerId":"c","explanation":"Anastrozole, an aromatase inhibitor, reduces systemic estrogen levels, leading to bone loss.","kind":"mechanism","origin":"ai"},{"id":"hrp2-female-hormones-drugs~ai-4","moduleId":"hrp2-female-hormones-drugs","stem":"A 32-year-old woman is considering hormonal contraception. She smokes one pack per day. Which contraceptive method should be avoided?","options":[{"id":"a","text":"Copper IUD"},{"id":"b","text":"Progestin-only pill"},{"id":"c","text":"Combined oral contraceptive"},{"id":"d","text":"Condoms"}],"answerId":"c","explanation":"Combined oral contraceptives are contraindicated in smokers over 35 due to increased VTE risk.","kind":"trap","origin":"ai"},{"id":"hrp2-female-hormones-drugs~ai-5","moduleId":"hrp2-female-hormones-drugs","stem":"Which of the following drugs is used for medical abortion by antagonizing progesterone receptors?","options":[{"id":"a","text":"Mifepristone"},{"id":"b","text":"Letrozole"},{"id":"c","text":"Clomiphene"},{"id":"d","text":"Tamoxifen"}],"answerId":"a","explanation":"Mifepristone is a progesterone-receptor antagonist used in medical abortion.","kind":"recall","origin":"ai"},{"id":"hrp2-female-hormones-drugs~ai-6","moduleId":"hrp2-female-hormones-drugs","stem":"How does raloxifene differ from tamoxifen in terms of endometrial effects?","options":[{"id":"a","text":"Raloxifene is an endometrial ER antagonist"},{"id":"b","text":"Raloxifene increases endometrial cancer risk"},{"id":"c","text":"Raloxifene is an endometrial ER agonist"},{"id":"d","text":"Raloxifene has no effect on the endometrium"}],"answerId":"a","explanation":"Raloxifene acts as an antagonist on endometrial estrogen receptors, unlike tamoxifen.","kind":"mechanism","origin":"ai"},{"id":"hrp2-female-hormones-drugs~ai-7","moduleId":"hrp2-female-hormones-drugs","stem":"A patient on hormone replacement therapy presents with new vaginal bleeding. Which drug interaction should be considered?","options":[{"id":"a","text":"Tamoxifen increasing endometrial cancer risk"},{"id":"b","text":"Raloxifene causing endometrial hyperplasia"},{"id":"c","text":"Anastrozole causing endometrial atrophy"},{"id":"d","text":"Clomiphene causing endometrial thickening"}],"answerId":"a","explanation":"Tamoxifen can increase endometrial cancer risk due to its agonistic effect on endometrial estrogen receptors.","kind":"integration","linkedModuleIds":["hrp2-menopause-hrt-drugs"],"origin":"ai"},{"id":"hrp2-female-hormones-drugs~ai-8","moduleId":"hrp2-female-hormones-drugs","stem":"In the context of hormonal contraception, how does the mechanism of action of combined oral contraceptives relate to the uterine cycle?","options":[{"id":"a","text":"They mimic the luteal phase, preventing ovulation"},{"id":"b","text":"They extend the follicular phase, delaying ovulation"},{"id":"c","text":"They induce a constant proliferative phase, inhibiting ovulation"},{"id":"d","text":"They suppress the menstrual phase, preventing ovulation"}],"answerId":"a","explanation":"Combined oral contraceptives mimic the luteal phase by providing continuous hormone levels, preventing the LH surge and ovulation.","kind":"integration","linkedModuleIds":["hrp1-uterine-cycle-fertility-signs"],"origin":"ai"}],"add-ectopic-pregnancy":[{"id":"add-ectopic-pregnancy~ai-0","moduleId":"add-ectopic-pregnancy","stem":"A 28-year-old woman presents with lower abdominal pain, amenorrhea, and vaginal bleeding. Her serum beta-hCG level is 1500 mIU/mL and does not double in 48 hours. What is the most likely diagnosis?","options":[{"id":"a","text":"Ectopic pregnancy"},{"id":"b","text":"Molar pregnancy"},{"id":"c","text":"Normal intrauterine pregnancy"},{"id":"d","text":"Miscarriage"}],"answerId":"a","explanation":"The classic triad of symptoms and the abnormal rise in beta-hCG levels suggest ectopic pregnancy.","kind":"clinical","origin":"ai"},{"id":"add-ectopic-pregnancy~ai-1","moduleId":"add-ectopic-pregnancy","stem":"Which of the following is a risk factor for ectopic pregnancy?","options":[{"id":"a","text":"Previous cesarean section"},{"id":"b","text":"Endometriosis"},{"id":"c","text":"Smoking"},{"id":"d","text":"Multiple gestations"}],"answerId":"c","explanation":"Smoking is a known risk factor for ectopic pregnancy due to its effects on tubal motility.","kind":"recall","origin":"ai"},{"id":"add-ectopic-pregnancy~ai-2","moduleId":"add-ectopic-pregnancy","stem":"A patient with suspected ectopic pregnancy shows cervical motion tenderness on examination. What does this finding indicate?","options":[{"id":"a","text":"Pelvic inflammatory disease"},{"id":"b","text":"Peritoneal irritation from blood"},{"id":"c","text":"Normal pelvic exam"},{"id":"d","text":"Uterine fibroids"}],"answerId":"b","explanation":"Cervical motion tenderness suggests peritoneal irritation, often due to blood from a ruptured ectopic pregnancy.","kind":"mechanism","origin":"ai"},{"id":"add-ectopic-pregnancy~ai-3","moduleId":"add-ectopic-pregnancy","stem":"A 30-year-old woman with a confirmed ectopic pregnancy is hemodynamically stable. Which treatment option is most appropriate?","options":[{"id":"a","text":"Methotrexate"},{"id":"b","text":"Laparotomy"},{"id":"c","text":"Expectant management"},{"id":"d","text":"Hysterectomy"}],"answerId":"a","explanation":"Methotrexate is used for medical management in stable patients with unruptured ectopic pregnancies.","kind":"recall","origin":"ai"},{"id":"add-ectopic-pregnancy~ai-4","moduleId":"add-ectopic-pregnancy","stem":"In the context of ectopic pregnancy, why is it incorrect to rule out the condition based on normal doubling of serum beta-hCG levels?","options":[{"id":"a","text":"Ectopic pregnancies always have normal hCG levels"},{"id":"b","text":"hCG levels can vary widely in ectopic pregnancies"},{"id":"c","text":"Doubling time is irrelevant to ectopic pregnancies"},{"id":"d","text":"Normal doubling indicates miscarriage"}],"answerId":"b","explanation":"Ectopic pregnancies can have varying hCG patterns, and normal doubling does not rule them out.","kind":"trap","origin":"ai"},{"id":"add-ectopic-pregnancy~ai-5","moduleId":"add-ectopic-pregnancy","stem":"A 32-year-old woman presents with pelvic pain and an adnexal mass on ultrasound. Her beta-hCG level is 2000 mIU/mL. Which other condition should be considered in the differential diagnosis?","options":[{"id":"a","text":"Endometriosis"},{"id":"b","text":"Ovarian cyst"},{"id":"c","text":"Uterine fibroid"},{"id":"d","text":"Pelvic inflammatory disease"}],"answerId":"a","explanation":"Endometriosis can present with pelvic pain and adnexal masses, similar to ectopic pregnancy.","kind":"integration","linkedModuleIds":["add-endometriosis"],"origin":"ai"},{"id":"add-ectopic-pregnancy~ai-6","moduleId":"add-ectopic-pregnancy","stem":"A patient with a history of ectopic pregnancy is concerned about future pregnancies. Which pre-embryonic factor could increase the risk of another ectopic pregnancy?","options":[{"id":"a","text":"Intrauterine device use"},{"id":"b","text":"Tubal surgery"},{"id":"c","text":"Low progesterone levels"},{"id":"d","text":"High estrogen levels"}],"answerId":"b","explanation":"Tubal surgery can lead to scarring and increase the risk of ectopic pregnancy.","kind":"integration","linkedModuleIds":["preembryonic-clinical-applications"],"origin":"ai"}],"add-endometriosis":[{"id":"add-endometriosis~ai-0","moduleId":"add-endometriosis","stem":"Which of the following is the gold standard for diagnosing endometriosis?","options":[{"id":"a","text":"Laparoscopy"},{"id":"b","text":"Pelvic ultrasound"},{"id":"c","text":"MRI"},{"id":"d","text":"CT scan"}],"answerId":"a","explanation":"Laparoscopy allows direct visualization and biopsy of lesions, making it the gold standard.","kind":"recall","origin":"ai"},{"id":"add-endometriosis~ai-1","moduleId":"add-endometriosis","stem":"A 30-year-old woman presents with severe dysmenorrhea and infertility. Physical examination reveals a fixed, retroverted uterus. What is the most likely underlying cause of this finding?","options":[{"id":"a","text":"Adhesions from endometriosis"},{"id":"b","text":"Uterine fibroids"},{"id":"c","text":"Pelvic inflammatory disease"},{"id":"d","text":"Ovarian cysts"}],"answerId":"a","explanation":"Adhesions from endometriosis can pull on uterine ligaments, causing a fixed, retroverted uterus.","kind":"clinical","origin":"ai"},{"id":"add-endometriosis~ai-2","moduleId":"add-endometriosis","stem":"Which treatment is first-line for managing pain associated with endometriosis?","options":[{"id":"a","text":"NSAIDs and combined oral contraceptives"},{"id":"b","text":"GnRH agonists"},{"id":"c","text":"Danazol"},{"id":"d","text":"Surgical intervention"}],"answerId":"a","explanation":"NSAIDs and combined oral contraceptives are first-line treatments for pain management in endometriosis.","kind":"recall","origin":"ai"},{"id":"add-endometriosis~ai-3","moduleId":"add-endometriosis","stem":"A patient with endometriosis is being considered for treatment with leuprolide. What is the primary mechanism of action of this medication?","options":[{"id":"a","text":"GnRH agonist suppressing ovarian function"},{"id":"b","text":"Estrogen receptor antagonist"},{"id":"c","text":"Progesterone receptor modulator"},{"id":"d","text":"Aromatase inhibitor"}],"answerId":"a","explanation":"Leuprolide is a GnRH agonist that suppresses ovarian function, reducing lesion size.","kind":"mechanism","origin":"ai"},{"id":"add-endometriosis~ai-4","moduleId":"add-endometriosis","stem":"A 28-year-old woman with a history of endometriosis presents with acute pelvic pain and a positive pregnancy test. Which condition should be ruled out first?","options":[{"id":"a","text":"Ectopic pregnancy"},{"id":"b","text":"Ovarian torsion"},{"id":"c","text":"Pelvic inflammatory disease"},{"id":"d","text":"Appendicitis"}],"answerId":"a","explanation":"In a woman with endometriosis and a positive pregnancy test, ectopic pregnancy should be ruled out first.","kind":"integration","linkedModuleIds":["add-ectopic-pregnancy"],"origin":"ai"},{"id":"add-endometriosis~ai-5","moduleId":"add-endometriosis","stem":"A 32-year-old woman with known endometriosis presents with hirsutism and irregular menstrual cycles. Which condition should be considered in the differential diagnosis?","options":[{"id":"a","text":"Congenital adrenal hyperplasia"},{"id":"b","text":"Polycystic ovary syndrome"},{"id":"c","text":"Hyperprolactinemia"},{"id":"d","text":"Thyroid dysfunction"}],"answerId":"a","explanation":"Congenital adrenal hyperplasia can present with hirsutism and menstrual irregularities, and should be considered.","kind":"integration","linkedModuleIds":["add-congenital-adrenal-hyperplasia-cah-neonatal-presentation"],"origin":"ai"}],"hrp2-uterine-contraction-drugs":[{"id":"hrp2-uterine-contraction-drugs~ai-0","moduleId":"hrp2-uterine-contraction-drugs","stem":"Which drug is first-line for managing postpartum hemorrhage?","options":[{"id":"a","text":"Oxytocin"},{"id":"b","text":"Ergometrine"},{"id":"c","text":"Misoprostol"},{"id":"d","text":"Carboprost"}],"answerId":"a","explanation":"Oxytocin is the first-line treatment for postpartum hemorrhage due to its ability to induce rapid uterine contractions.","kind":"recall","origin":"ai"},{"id":"hrp2-uterine-contraction-drugs~ai-1","moduleId":"hrp2-uterine-contraction-drugs","stem":"A woman with pre-eclampsia is experiencing postpartum hemorrhage. Which uterotonic is contraindicated?","options":[{"id":"a","text":"Oxytocin"},{"id":"b","text":"Ergometrine"},{"id":"c","text":"Misoprostol"},{"id":"d","text":"Carboprost"}],"answerId":"b","explanation":"Ergometrine is contraindicated in hypertension and pre-eclampsia due to its vasoconstrictive properties.","kind":"trap","origin":"ai"},{"id":"hrp2-uterine-contraction-drugs~ai-2","moduleId":"hrp2-uterine-contraction-drugs","stem":"Which drug is used to delay preterm labor and also provides fetal neuroprotection?","options":[{"id":"a","text":"Nifedipine"},{"id":"b","text":"Atosiban"},{"id":"c","text":"Magnesium sulfate"},{"id":"d","text":"Indomethacin"}],"answerId":"c","explanation":"Magnesium sulfate is used for tocolysis and provides fetal neuroprotection.","kind":"mechanism","origin":"ai"},{"id":"hrp2-uterine-contraction-drugs~ai-3","moduleId":"hrp2-uterine-contraction-drugs","stem":"For a patient with asthma experiencing postpartum hemorrhage, which uterotonic should be avoided?","options":[{"id":"a","text":"Oxytocin"},{"id":"b","text":"Ergometrine"},{"id":"c","text":"Misoprostol"},{"id":"d","text":"Carboprost"}],"answerId":"d","explanation":"Carboprost should be avoided in asthma patients due to its potential to cause bronchospasm.","kind":"clinical","origin":"ai"},{"id":"hrp2-uterine-contraction-drugs~ai-4","moduleId":"hrp2-uterine-contraction-drugs","stem":"Which drug is used for cervical ripening and induction of labor?","options":[{"id":"a","text":"Oxytocin"},{"id":"b","text":"Ergometrine"},{"id":"c","text":"Misoprostol"},{"id":"d","text":"Nifedipine"}],"answerId":"c","explanation":"Misoprostol is a prostaglandin used for cervical ripening and labor induction.","kind":"recall","origin":"ai"},{"id":"hrp2-uterine-contraction-drugs~ai-5","moduleId":"hrp2-uterine-contraction-drugs","stem":"A patient in preterm labor requires tocolysis. Which drug should be avoided due to the risk of premature ductus arteriosus closure?","options":[{"id":"a","text":"Nifedipine"},{"id":"b","text":"Atosiban"},{"id":"c","text":"Indomethacin"},{"id":"d","text":"Magnesium sulfate"}],"answerId":"c","explanation":"Indomethacin, an NSAID, can cause premature closure of the ductus arteriosus and is avoided in later gestation.","kind":"trap","origin":"ai"},{"id":"hrp2-uterine-contraction-drugs~ai-6","moduleId":"hrp2-uterine-contraction-drugs","stem":"In the context of labor induction, which drug also serves as a uterotonic for postpartum hemorrhage?","options":[{"id":"a","text":"Oxytocin"},{"id":"b","text":"Ergometrine"},{"id":"c","text":"Misoprostol"},{"id":"d","text":"Atosiban"}],"answerId":"c","explanation":"Misoprostol is used for both labor induction and as a uterotonic for postpartum hemorrhage.","kind":"integration","linkedModuleIds":["hrp2-labour-induction-tocolysis"],"origin":"ai"},{"id":"hrp2-uterine-contraction-drugs~ai-7","moduleId":"hrp2-uterine-contraction-drugs","stem":"Which drug is a calcium channel blocker used to delay preterm labor?","options":[{"id":"a","text":"Nifedipine"},{"id":"b","text":"Atosiban"},{"id":"c","text":"Magnesium sulfate"},{"id":"d","text":"Terbutaline"}],"answerId":"a","explanation":"Nifedipine is a calcium channel blocker used as a tocolytic to delay preterm labor.","kind":"integration","linkedModuleIds":["hrp2-labour-induction-tocolysis"],"origin":"ai"}],"add-polycystic-ovary-syndrome-pcos":[{"id":"add-polycystic-ovary-syndrome-pcos~ai-0","moduleId":"add-polycystic-ovary-syndrome-pcos","stem":"Which of the following is a common hormonal finding in patients with PCOS?","options":[{"id":"a","text":"Increased LH:FSH ratio"},{"id":"b","text":"Decreased testosterone levels"},{"id":"c","text":"Increased FSH levels"},{"id":"d","text":"Decreased LH levels"}],"answerId":"a","explanation":"PCOS is often associated with an increased LH:FSH ratio due to increased LH secretion.","kind":"recall","origin":"ai"},{"id":"add-polycystic-ovary-syndrome-pcos~ai-1","moduleId":"add-polycystic-ovary-syndrome-pcos","stem":"A 25-year-old woman presents with irregular menstrual cycles and hirsutism. Ultrasound reveals polycystic ovaries. Which treatment is most appropriate for her menstrual irregularity?","options":[{"id":"a","text":"Metformin"},{"id":"b","text":"Spironolactone"},{"id":"c","text":"Clomiphene citrate"},{"id":"d","text":"Combined oral contraceptives"}],"answerId":"d","explanation":"Combined oral contraceptives are first-line treatment for menstrual irregularity in PCOS.","kind":"clinical","origin":"ai"},{"id":"add-polycystic-ovary-syndrome-pcos~ai-2","moduleId":"add-polycystic-ovary-syndrome-pcos","stem":"Which of the following is a diagnostic trap when evaluating a patient for PCOS?","options":[{"id":"a","text":"Requiring all three Rotterdam criteria"},{"id":"b","text":"Using ultrasound alone for diagnosis"},{"id":"c","text":"Relying on clinical signs of hyperandrogenism"},{"id":"d","text":"Considering insulin resistance as a criterion"}],"answerId":"a","explanation":"Only two out of the three Rotterdam criteria are needed for PCOS diagnosis.","kind":"trap","origin":"ai"},{"id":"add-polycystic-ovary-syndrome-pcos~ai-3","moduleId":"add-polycystic-ovary-syndrome-pcos","stem":"What is the primary mechanism behind the development of acanthosis nigricans in PCOS patients?","options":[{"id":"a","text":"Increased androgen levels"},{"id":"b","text":"Insulin resistance"},{"id":"c","text":"Elevated estrogen levels"},{"id":"d","text":"Increased LH secretion"}],"answerId":"b","explanation":"Insulin resistance leads to hyperpigmentation of skin folds, resulting in acanthosis nigricans.","kind":"mechanism","origin":"ai"},{"id":"add-polycystic-ovary-syndrome-pcos~ai-4","moduleId":"add-polycystic-ovary-syndrome-pcos","stem":"A 30-year-old woman with PCOS is concerned about her risk of developing type 2 diabetes. What underlying condition in PCOS contributes to this risk?","options":[{"id":"a","text":"Increased estrogen levels"},{"id":"b","text":"Insulin resistance"},{"id":"c","text":"Elevated FSH levels"},{"id":"d","text":"Decreased androgen levels"}],"answerId":"b","explanation":"Insulin resistance is common in PCOS and increases the risk of type 2 diabetes.","kind":"clinical","origin":"ai"},{"id":"add-polycystic-ovary-syndrome-pcos~ai-5","moduleId":"add-polycystic-ovary-syndrome-pcos","stem":"Which of the following features is NOT part of the Rotterdam criteria for diagnosing PCOS?","options":[{"id":"a","text":"Oligo/anovulation"},{"id":"b","text":"Clinical/biochemical signs of hyperandrogenism"},{"id":"c","text":"Polycystic ovaries on ultrasound"},{"id":"d","text":"Insulin resistance"}],"answerId":"d","explanation":"Insulin resistance is not part of the Rotterdam criteria for PCOS diagnosis.","kind":"trap","origin":"ai"},{"id":"add-polycystic-ovary-syndrome-pcos~ai-6","moduleId":"add-polycystic-ovary-syndrome-pcos","stem":"A patient with suspected PCOS also presents with ambiguous genitalia. Which condition should be considered as a differential diagnosis?","options":[{"id":"a","text":"Turner syndrome"},{"id":"b","text":"Congenital adrenal hyperplasia"},{"id":"c","text":"Androgen insensitivity syndrome"},{"id":"d","text":"Klinefelter syndrome"}],"answerId":"b","explanation":"Congenital adrenal hyperplasia can present with ambiguous genitalia and should be considered in the differential diagnosis.","kind":"integration","linkedModuleIds":["add-congenital-adrenal-hyperplasia-cah-neonatal-presentation"],"origin":"ai"},{"id":"add-polycystic-ovary-syndrome-pcos~ai-7","moduleId":"add-polycystic-ovary-syndrome-pcos","stem":"A woman with PCOS is experiencing infertility. Which medication is commonly used to induce ovulation in such patients?","options":[{"id":"a","text":"Metformin"},{"id":"b","text":"Spironolactone"},{"id":"c","text":"Clomiphene citrate"},{"id":"d","text":"Leuprolide"}],"answerId":"c","explanation":"Clomiphene citrate is commonly used to induce ovulation in women with PCOS experiencing infertility.","kind":"clinical","origin":"ai"},{"id":"add-polycystic-ovary-syndrome-pcos~ai-8","moduleId":"add-polycystic-ovary-syndrome-pcos","stem":"A 28-year-old woman with PCOS is found to have an ectopic pregnancy. What is a common risk factor for ectopic pregnancy in PCOS patients?","options":[{"id":"a","text":"Increased LH levels"},{"id":"b","text":"Chronic anovulation"},{"id":"c","text":"Insulin resistance"},{"id":"d","text":"Use of ovulation induction agents"}],"answerId":"d","explanation":"The use of ovulation induction agents in PCOS can increase the risk of ectopic pregnancy.","kind":"integration","linkedModuleIds":["add-ectopic-pregnancy"],"origin":"ai"}],"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen":[{"id":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen~ai-0","moduleId":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen","stem":"Which of the following is a defining feature of preeclampsia?","options":[{"id":"a","text":"New-onset hypertension and proteinuria after 20 weeks gestation"},{"id":"b","text":"Hypertension before 20 weeks gestation"},{"id":"c","text":"Seizures in a pregnant patient"},{"id":"d","text":"Elevated liver enzymes and low platelets"}],"answerId":"a","explanation":"Preeclampsia is characterized by new-onset hypertension and proteinuria after 20 weeks of gestation.","kind":"recall","origin":"ai"},{"id":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen~ai-1","moduleId":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen","stem":"What is the primary pathophysiological mechanism underlying preeclampsia?","options":[{"id":"a","text":"Abnormal placentation leading to endothelial dysfunction"},{"id":"b","text":"Increased cardiac output"},{"id":"c","text":"Decreased renal perfusion"},{"id":"d","text":"Hypercoagulability"}],"answerId":"a","explanation":"Abnormal placentation leads to endothelial dysfunction and vasospasm, which are central to the pathophysiology of preeclampsia.","kind":"mechanism","origin":"ai"},{"id":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen~ai-2","moduleId":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen","stem":"A 28-year-old pregnant woman at 32 weeks gestation presents with severe hypertension and seizures. What is the most appropriate immediate management?","options":[{"id":"a","text":"Magnesium sulfate"},{"id":"b","text":"Labetalol"},{"id":"c","text":"Nifedipine"},{"id":"d","text":"Hydralazine"}],"answerId":"a","explanation":"Magnesium sulfate is used for seizure prophylaxis and treatment in eclampsia.","kind":"clinical","origin":"ai"},{"id":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen~ai-3","moduleId":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen","stem":"Which of the following findings is most indicative of severe preeclampsia?","options":[{"id":"a","text":"Blood pressure of 140/90 mmHg"},{"id":"b","text":"Proteinuria of 200 mg/24 hours"},{"id":"c","text":"Blood pressure of 170/110 mmHg"},{"id":"d","text":"Mild facial edema"}],"answerId":"c","explanation":"Severe preeclampsia is indicated by a blood pressure greater than 160/110 mmHg.","kind":"recall","origin":"ai"},{"id":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen~ai-4","moduleId":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen","stem":"A patient with preeclampsia develops hemolysis, elevated liver enzymes, and low platelets. What is this condition called?","options":[{"id":"a","text":"HELLP syndrome"},{"id":"b","text":"Eclampsia"},{"id":"c","text":"Gestational hypertension"},{"id":"d","text":"Cholestasis of pregnancy"}],"answerId":"a","explanation":"HELLP syndrome is a severe form of preeclampsia characterized by hemolysis, elevated liver enzymes, and low platelets.","kind":"recall","origin":"ai"},{"id":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen~ai-5","moduleId":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen","stem":"Which medication is incorrectly considered first-line for seizure prevention in eclampsia?","options":[{"id":"a","text":"Magnesium sulfate"},{"id":"b","text":"Calcium channel blockers"},{"id":"c","text":"Diazepam"},{"id":"d","text":"Phenytoin"}],"answerId":"b","explanation":"Magnesium sulfate is the first-line treatment for seizure prevention in eclampsia, not calcium channel blockers.","kind":"trap","origin":"ai"},{"id":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen~ai-6","moduleId":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen","stem":"A patient with preeclampsia is being monitored for potential complications. Which of the following signs would suggest neuromuscular irritability due to CNS involvement?","options":[{"id":"a","text":"Hyperreflexia and clonus"},{"id":"b","text":"Bradycardia"},{"id":"c","text":"Hypotonia"},{"id":"d","text":"Absent reflexes"}],"answerId":"a","explanation":"Hyperreflexia and clonus are indicative of neuromuscular irritability due to CNS involvement in preeclampsia.","kind":"recall","origin":"ai"},{"id":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen~ai-7","moduleId":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen","stem":"In a patient with preeclampsia, which of the following linked conditions could exacerbate hypertension due to increased adrenal steroid production?","options":[{"id":"a","text":"Congenital adrenal hyperplasia"},{"id":"b","text":"Ectopic pregnancy"},{"id":"c","text":"Gestational diabetes"},{"id":"d","text":"Hyperemesis gravidarum"}],"answerId":"a","explanation":"Congenital adrenal hyperplasia can exacerbate hypertension in preeclampsia due to increased adrenal steroid production.","kind":"integration","linkedModuleIds":["add-congenital-adrenal-hyperplasia-cah-neonatal-presentation"],"origin":"ai"},{"id":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen~ai-8","moduleId":"add-preeclampsia-and-eclampsia-pathophysiology-and-managemen","stem":"How might the management of preeclampsia differ if the patient also has an ectopic pregnancy?","options":[{"id":"a","text":"Immediate surgical intervention is prioritized"},{"id":"b","text":"Magnesium sulfate is contraindicated"},{"id":"c","text":"Blood pressure management is not required"},{"id":"d","text":"Delivery is delayed until 37 weeks"}],"answerId":"a","explanation":"In the case of an ectopic pregnancy, immediate surgical intervention is prioritized over other treatments.","kind":"integration","linkedModuleIds":["add-ectopic-pregnancy"],"origin":"ai"}],"add-male-infertility-causes-and-management":[{"id":"add-male-infertility-causes-and-management~ai-0","moduleId":"add-male-infertility-causes-and-management","stem":"Which of the following is the most common correctable cause of male infertility?","options":[{"id":"a","text":"Varicocele"},{"id":"b","text":"Klinefelter syndrome"},{"id":"c","text":"Y chromosome microdeletions"},{"id":"d","text":"Obstructive azoospermia"}],"answerId":"a","explanation":"Varicocele is the most common correctable cause of male infertility due to its impact on testicular temperature and function.","kind":"recall","origin":"ai"},{"id":"add-male-infertility-causes-and-management~ai-1","moduleId":"add-male-infertility-causes-and-management","stem":"A 35-year-old male presents with infertility. Semen analysis shows azoospermia. Which investigation should be performed next to differentiate between obstructive and non-obstructive azoospermia?","options":[{"id":"a","text":"Testicular biopsy"},{"id":"b","text":"Scrotal ultrasound"},{"id":"c","text":"Hormonal profile"},{"id":"d","text":"Genetic testing"}],"answerId":"a","explanation":"Testicular biopsy helps differentiate between obstructive and non-obstructive azoospermia by assessing spermatogenesis.","kind":"mechanism","origin":"ai"},{"id":"add-male-infertility-causes-and-management~ai-2","moduleId":"add-male-infertility-causes-and-management","stem":"A patient with suspected Klinefelter syndrome presents with small, firm testes. What is the underlying mechanism for this finding?","options":[{"id":"a","text":"Fibrosis and hyalinization of seminiferous tubules"},{"id":"b","text":"Increased testicular temperature"},{"id":"c","text":"Y chromosome microdeletions"},{"id":"d","text":"Obstruction of the vas deferens"}],"answerId":"a","explanation":"In Klinefelter syndrome, small, firm testes result from fibrosis and hyalinization of seminiferous tubules.","kind":"mechanism","origin":"ai"},{"id":"add-male-infertility-causes-and-management~ai-3","moduleId":"add-male-infertility-causes-and-management","stem":"Which medication can be used to treat idiopathic oligospermia by increasing gonadotropin release?","options":[{"id":"a","text":"Clomiphene citrate"},{"id":"b","text":"Testosterone replacement"},{"id":"c","text":"Anastrozole"},{"id":"d","text":"Finasteride"}],"answerId":"a","explanation":"Clomiphene citrate is used to treat idiopathic oligospermia by increasing the release of gonadotropins.","kind":"recall","origin":"ai"},{"id":"add-male-infertility-causes-and-management~ai-4","moduleId":"add-male-infertility-causes-and-management","stem":"A 28-year-old male with a 'bag of worms' scrotal mass is diagnosed with varicocele. What is the pathophysiological mechanism behind this condition?","options":[{"id":"a","text":"Dilation of the pampiniform plexus"},{"id":"b","text":"Obstruction of the vas deferens"},{"id":"c","text":"Y chromosome microdeletions"},{"id":"d","text":"Testicular torsion"}],"answerId":"a","explanation":"Varicocele is caused by the dilation of veins in the pampiniform plexus, leading to increased scrotal temperature.","kind":"mechanism","origin":"ai"},{"id":"add-male-infertility-causes-and-management~ai-5","moduleId":"add-male-infertility-causes-and-management","stem":"A semen analysis shows a volume of 1.0 mL and sperm concentration of 10 million/mL. Which linked module would provide additional information on semen assessment?","options":[{"id":"a","text":"Macroscopic & Biochemical Semen Assessment"},{"id":"b","text":"Congenital Adrenal Hyperplasia (CAH): Neonatal Presentation"},{"id":"c","text":"Ectopic Pregnancy"},{"id":"d","text":"Male Infertility: Causes, Evaluation, and Management"}],"answerId":"a","explanation":"The 'Macroscopic & Biochemical Semen Assessment' module provides detailed information on semen analysis parameters.","kind":"integration","linkedModuleIds":["hrp1-semen-macroscopic-chemistry"],"origin":"ai"},{"id":"add-male-infertility-causes-and-management~ai-6","moduleId":"add-male-infertility-causes-and-management","stem":"In the context of male infertility, which genetic condition is characterized by a 47,XXY karyotype?","options":[{"id":"a","text":"Klinefelter syndrome"},{"id":"b","text":"Turner syndrome"},{"id":"c","text":"Androgen insensitivity syndrome"},{"id":"d","text":"Noonan syndrome"}],"answerId":"a","explanation":"Klinefelter syndrome is characterized by a 47,XXY karyotype and is a common genetic cause of male infertility.","kind":"recall","origin":"ai"},{"id":"add-male-infertility-causes-and-management~ai-7","moduleId":"add-male-infertility-causes-and-management","stem":"A male patient with infertility is found to have low testosterone levels. Which linked module could provide insights into hormonal evaluation and management?","options":[{"id":"a","text":"Male Infertility: Causes, Evaluation, and Management"},{"id":"b","text":"Congenital Adrenal Hyperplasia (CAH): Neonatal Presentation"},{"id":"c","text":"Ectopic Pregnancy"},{"id":"d","text":"Macroscopic & Biochemical Semen Assessment"}],"answerId":"a","explanation":"The 'Male Infertility: Causes, Evaluation, and Management' module covers hormonal evaluation and management strategies.","kind":"integration","linkedModuleIds":["add-male-infertility-causes-evaluation-and-management"],"origin":"ai"}],"add-gestational-diabetes-mellitus-gdm":[{"id":"add-gestational-diabetes-mellitus-gdm~ai-0","moduleId":"add-gestational-diabetes-mellitus-gdm","stem":"A 32-year-old pregnant woman with a BMI of 30 is at her 26-week prenatal visit. What is the most appropriate next step in screening for gestational diabetes mellitus?","options":[{"id":"a","text":"Perform a 1-hour OGTT"},{"id":"b","text":"Perform a fasting glucose test"},{"id":"c","text":"Screen for diabetes at the first prenatal visit"},{"id":"d","text":"Perform a hemoglobin A1c test"}],"answerId":"a","explanation":"The 1-hour OGTT is the standard screening test for GDM between 24-28 weeks gestation.","kind":"recall","origin":"ai"},{"id":"add-gestational-diabetes-mellitus-gdm~ai-1","moduleId":"add-gestational-diabetes-mellitus-gdm","stem":"Which of the following is a common complication for the neonate of a mother with untreated gestational diabetes mellitus?","options":[{"id":"a","text":"Neonatal hypoglycemia"},{"id":"b","text":"Neonatal polycythemia"},{"id":"c","text":"Neonatal jaundice"},{"id":"d","text":"Neonatal hypothyroidism"}],"answerId":"a","explanation":"Neonatal hypoglycemia is a common complication due to fetal hyperinsulinemia.","kind":"recall","origin":"ai"},{"id":"add-gestational-diabetes-mellitus-gdm~ai-2","moduleId":"add-gestational-diabetes-mellitus-gdm","stem":"A pregnant woman with gestational diabetes is found to have excessive fetal growth on ultrasound. What is the underlying mechanism?","options":[{"id":"a","text":"Maternal hyperglycemia causing fetal hyperinsulinemia"},{"id":"b","text":"Increased maternal insulin sensitivity"},{"id":"c","text":"Decreased placental blood flow"},{"id":"d","text":"Maternal ketoacidosis"}],"answerId":"a","explanation":"Maternal hyperglycemia leads to fetal hyperinsulinemia, which promotes excessive fetal growth.","kind":"mechanism","origin":"ai"},{"id":"add-gestational-diabetes-mellitus-gdm~ai-3","moduleId":"add-gestational-diabetes-mellitus-gdm","stem":"A 28-year-old woman with a history of gestational diabetes is concerned about her future health. Which condition is she at increased risk for?","options":[{"id":"a","text":"Type 2 diabetes mellitus"},{"id":"b","text":"Hypothyroidism"},{"id":"c","text":"Chronic kidney disease"},{"id":"d","text":"Rheumatoid arthritis"}],"answerId":"a","explanation":"Women with a history of GDM are at increased risk for developing type 2 diabetes later in life.","kind":"recall","origin":"ai"},{"id":"add-gestational-diabetes-mellitus-gdm~ai-4","moduleId":"add-gestational-diabetes-mellitus-gdm","stem":"A 30-year-old woman with gestational diabetes is being managed with dietary changes and exercise. Her blood glucose levels remain elevated. What is the next step in management?","options":[{"id":"a","text":"Start insulin therapy"},{"id":"b","text":"Increase exercise intensity"},{"id":"c","text":"Add metformin"},{"id":"d","text":"Perform a repeat OGTT"}],"answerId":"a","explanation":"Insulin is the preferred pharmacological treatment when lifestyle modifications are insufficient.","kind":"clinical","origin":"ai"},{"id":"add-gestational-diabetes-mellitus-gdm~ai-5","moduleId":"add-gestational-diabetes-mellitus-gdm","stem":"A 35-year-old woman with gestational diabetes is concerned about cardiovascular complications. Which linked module would provide relevant information?","options":[{"id":"a","text":"Cardiovascular Effects of Diabetes Mellitus"},{"id":"b","text":"Congenital Adrenal Hyperplasia: Neonatal Presentation"},{"id":"c","text":"Ectopic Pregnancy"},{"id":"d","text":"Gestational Diabetes Mellitus: Screening and Management"}],"answerId":"a","explanation":"The 'Cardiovascular Effects of Diabetes Mellitus' module provides information on cardiovascular risks associated with diabetes.","kind":"integration","linkedModuleIds":["add-cardiovascular-effects-of-diabetes-mellitus"],"origin":"ai"},{"id":"add-gestational-diabetes-mellitus-gdm~ai-6","moduleId":"add-gestational-diabetes-mellitus-gdm","stem":"In a patient with gestational diabetes, which of the following is a key component of the initial management plan?","options":[{"id":"a","text":"Dietary modification"},{"id":"b","text":"Immediate insulin therapy"},{"id":"c","text":"Oral hypoglycemic agents"},{"id":"d","text":"Early delivery"}],"answerId":"a","explanation":"Dietary modification is the first-line management for gestational diabetes.","kind":"recall","origin":"ai"},{"id":"add-gestational-diabetes-mellitus-gdm~ai-7","moduleId":"add-gestational-diabetes-mellitus-gdm","stem":"A patient with gestational diabetes is undergoing routine screening. At what gestational age should this screening ideally occur?","options":[{"id":"a","text":"24-28 weeks"},{"id":"b","text":"12-16 weeks"},{"id":"c","text":"32-36 weeks"},{"id":"d","text":"At the first prenatal visit"}],"answerId":"a","explanation":"Routine screening for gestational diabetes is recommended between 24-28 weeks of gestation.","kind":"trap","origin":"ai"},{"id":"add-gestational-diabetes-mellitus-gdm~ai-8","moduleId":"add-gestational-diabetes-mellitus-gdm","stem":"A pregnant woman with gestational diabetes is concerned about the potential for congenital adrenal hyperplasia in her newborn. Which module could provide information on this condition?","options":[{"id":"a","text":"Congenital Adrenal Hyperplasia: Neonatal Presentation"},{"id":"b","text":"Cardiovascular Effects of Diabetes Mellitus"},{"id":"c","text":"Ectopic Pregnancy"},{"id":"d","text":"Gestational Diabetes Mellitus: Screening and Management"}],"answerId":"a","explanation":"The 'Congenital Adrenal Hyperplasia: Neonatal Presentation' module provides information on CAH in newborns.","kind":"integration","linkedModuleIds":["add-congenital-adrenal-hyperplasia-cah-neonatal-presentation"],"origin":"ai"}],"add-placental-abruption-diagnosis-and-management":[{"id":"add-placental-abruption-diagnosis-and-management~ai-0","moduleId":"add-placental-abruption-diagnosis-and-management","stem":"A 32-year-old pregnant woman at 34 weeks gestation presents with sudden onset of severe abdominal pain and vaginal bleeding. On examination, her uterus is tender and rigid. What is the most likely diagnosis?","options":[{"id":"a","text":"Placental abruption"},{"id":"b","text":"Placenta previa"},{"id":"c","text":"Ectopic pregnancy"},{"id":"d","text":"Uterine rupture"}],"answerId":"a","explanation":"The combination of painful vaginal bleeding and a tender, rigid uterus is classic for placental abruption.","kind":"clinical","origin":"ai"},{"id":"add-placental-abruption-diagnosis-and-management~ai-1","moduleId":"add-placental-abruption-diagnosis-and-management","stem":"Which of the following is a known risk factor for placental abruption?","options":[{"id":"a","text":"Gestational diabetes"},{"id":"b","text":"Hypertension"},{"id":"c","text":"Hypothyroidism"},{"id":"d","text":"Hyperemesis gravidarum"}],"answerId":"b","explanation":"Hypertension is a well-established risk factor for placental abruption.","kind":"recall","origin":"ai"},{"id":"add-placental-abruption-diagnosis-and-management~ai-2","moduleId":"add-placental-abruption-diagnosis-and-management","stem":"A pregnant woman presents with vaginal bleeding. Ultrasound shows a retroplacental hematoma. What does this finding suggest?","options":[{"id":"a","text":"Placenta previa"},{"id":"b","text":"Placental abruption"},{"id":"c","text":"Ectopic pregnancy"},{"id":"d","text":"Molar pregnancy"}],"answerId":"b","explanation":"A retroplacental hematoma on ultrasound is suggestive of placental abruption.","kind":"mechanism","origin":"ai"},{"id":"add-placental-abruption-diagnosis-and-management~ai-3","moduleId":"add-placental-abruption-diagnosis-and-management","stem":"Which test can help assess the severity of placental abruption by detecting fetal blood in maternal circulation?","options":[{"id":"a","text":"Kleihauer-Betke test"},{"id":"b","text":"Coombs test"},{"id":"c","text":"Non-stress test"},{"id":"d","text":"Amniocentesis"}],"answerId":"a","explanation":"The Kleihauer-Betke test detects fetal blood cells in maternal circulation, indicating the severity of abruption.","kind":"recall","origin":"ai"},{"id":"add-placental-abruption-diagnosis-and-management~ai-4","moduleId":"add-placental-abruption-diagnosis-and-management","stem":"A 28-year-old pregnant woman with a history of cocaine use presents with painful vaginal bleeding and fetal distress. What is the most appropriate next step in management?","options":[{"id":"a","text":"Immediate delivery"},{"id":"b","text":"Observation"},{"id":"c","text":"Tocolysis"},{"id":"d","text":"Amniocentesis"}],"answerId":"a","explanation":"Immediate delivery is indicated in cases of placental abruption with maternal or fetal instability.","kind":"clinical","origin":"ai"},{"id":"add-placental-abruption-diagnosis-and-management~ai-5","moduleId":"add-placental-abruption-diagnosis-and-management","stem":"A pregnant woman presents with painless vaginal bleeding. Which condition is most likely?","options":[{"id":"a","text":"Placental abruption"},{"id":"b","text":"Placenta previa"},{"id":"c","text":"Ectopic pregnancy"},{"id":"d","text":"Uterine rupture"}],"answerId":"b","explanation":"Painless vaginal bleeding is characteristic of placenta previa, not placental abruption.","kind":"trap","origin":"ai"},{"id":"add-placental-abruption-diagnosis-and-management~ai-6","moduleId":"add-placental-abruption-diagnosis-and-management","stem":"A pregnant woman with suspected placental abruption shows fetal heart rate abnormalities. What is the underlying mechanism?","options":[{"id":"a","text":"Increased uterine contractions"},{"id":"b","text":"Reduced placental perfusion"},{"id":"c","text":"Maternal hypotension"},{"id":"d","text":"Fetal anemia"}],"answerId":"b","explanation":"Fetal heart rate abnormalities in placental abruption are due to reduced placental perfusion leading to fetal hypoxia.","kind":"mechanism","origin":"ai"},{"id":"add-placental-abruption-diagnosis-and-management~ai-7","moduleId":"add-placental-abruption-diagnosis-and-management","stem":"A newborn presents with ambiguous genitalia and hypotension. The mother had a history of placental abruption. Which linked condition should be considered?","options":[{"id":"a","text":"Congenital adrenal hyperplasia"},{"id":"b","text":"Ectopic pregnancy"},{"id":"c","text":"Placenta previa"},{"id":"d","text":"Gestational trophoblastic disease"}],"answerId":"a","explanation":"Ambiguous genitalia and hypotension in a newborn suggest congenital adrenal hyperplasia, which can be considered in the context of maternal complications like placental abruption.","kind":"integration","linkedModuleIds":["add-congenital-adrenal-hyperplasia-cah-neonatal-presentation"],"origin":"ai"},{"id":"add-placental-abruption-diagnosis-and-management~ai-8","moduleId":"add-placental-abruption-diagnosis-and-management","stem":"A woman with a history of ectopic pregnancy presents with painful vaginal bleeding at 36 weeks gestation. Which condition should be prioritized in the differential diagnosis?","options":[{"id":"a","text":"Placental abruption"},{"id":"b","text":"Placenta previa"},{"id":"c","text":"Uterine rupture"},{"id":"d","text":"Preterm labor"}],"answerId":"a","explanation":"Painful vaginal bleeding at 36 weeks is more indicative of placental abruption, especially with a history of ectopic pregnancy.","kind":"integration","linkedModuleIds":["add-ectopic-pregnancy"],"origin":"ai"}],"add-congenital-adrenal-hyperplasia-cah-neonatal-presentation":[{"id":"add-congenital-adrenal-hyperplasia-cah-neonatal-presentation~ai-0","moduleId":"add-congenital-adrenal-hyperplasia-cah-neonatal-presentation","stem":"Which enzyme deficiency is most commonly responsible for Congenital Adrenal Hyperplasia (CAH) in neonates?","options":[{"id":"a","text":"21-hydroxylase"},{"id":"b","text":"11-beta-hydroxylase"},{"id":"c","text":"17-alpha-hydroxylase"},{"id":"d","text":"3-beta-hydroxysteroid dehydrogenase"}],"answerId":"a","explanation":"21-hydroxylase deficiency accounts for over 90% of CAH cases.","kind":"recall","origin":"ai"},{"id":"add-congenital-adrenal-hyperplasia-cah-neonatal-presentation~ai-1","moduleId":"add-congenital-adrenal-hyperplasia-cah-neonatal-presentation","stem":"A newborn female presents with ambiguous genitalia. Which biochemical marker is most likely elevated in this condition?","options":[{"id":"a","text":"Cortisol"},{"id":"b","text":"Aldosterone"},{"id":"c","text":"17-hydroxyprogesterone"},{"id":"d","text":"ACTH"}],"answerId":"c","explanation":"In CAH due to 21-hydroxylase deficiency, 17-hydroxyprogesterone is elevated.","kind":"trap","origin":"ai"},{"id":"add-congenital-adrenal-hyperplasia-cah-neonatal-presentation~ai-2","moduleId":"add-congenital-adrenal-hyperplasia-cah-neonatal-presentation","stem":"What is the primary hormonal imbalance in Congenital Adrenal Hyperplasia due to 21-hydroxylase deficiency?","options":[{"id":"a","text":"Decreased androgens"},{"id":"b","text":"Increased cortisol"},{"id":"c","text":"Decreased aldosterone"},{"id":"d","text":"Increased aldosterone"}],"answerId":"c","explanation":"21-hydroxylase deficiency leads to decreased aldosterone and cortisol, with increased androgens.","kind":"mechanism","origin":"ai"},{"id":"add-congenital-adrenal-hyperplasia-cah-neonatal-presentation~ai-3","moduleId":"add-congenital-adrenal-hyperplasia-cah-neonatal-presentation","stem":"A newborn is diagnosed with CAH. Which treatment is essential to prevent salt-wasting crises?","options":[{"id":"a","text":"Androgen inhibitors"},{"id":"b","text":"Glucocorticoid replacement"},{"id":"c","text":"Mineralocorticoid replacement"},{"id":"d","text":"Estrogen therapy"}],"answerId":"c","explanation":"Mineralocorticoid replacement is necessary to prevent salt-wasting in CAH.","kind":"clinical","origin":"ai"},{"id":"add-congenital-adrenal-hyperplasia-cah-neonatal-presentation~ai-4","moduleId":"add-congenital-adrenal-hyperplasia-cah-neonatal-presentation","stem":"In CAH, which hormone's increased production is responsible for adrenal hyperplasia?","options":[{"id":"a","text":"ACTH"},{"id":"b","text":"Cortisol"},{"id":"c","text":"Aldosterone"},{"id":"d","text":"Androgens"}],"answerId":"a","explanation":"Increased ACTH due to low cortisol levels drives adrenal hyperplasia.","kind":"mechanism","origin":"ai"},{"id":"add-congenital-adrenal-hyperplasia-cah-neonatal-presentation~ai-5","moduleId":"add-congenital-adrenal-hyperplasia-cah-neonatal-presentation","stem":"How does CAH potentially impact reproductive development in affected individuals?","options":[{"id":"a","text":"Normal reproductive development"},{"id":"b","text":"Delayed puberty"},{"id":"c","text":"Precocious puberty"},{"id":"d","text":"Infertility"}],"answerId":"d","explanation":"Excess androgens in CAH can lead to infertility due to disrupted reproductive development.","kind":"integration","linkedModuleIds":["add-congenital-adrenal-hyperplasia-cah-and-its-impact-on-rep"],"origin":"ai"},{"id":"add-congenital-adrenal-hyperplasia-cah-neonatal-presentation~ai-6","moduleId":"add-congenital-adrenal-hyperplasia-cah-neonatal-presentation","stem":"A female patient with CAH is at risk for which of the following conditions due to chronic anovulation?","options":[{"id":"a","text":"Ectopic pregnancy"},{"id":"b","text":"Endometrial hyperplasia"},{"id":"c","text":"Ovarian hyperstimulation syndrome"},{"id":"d","text":"Pelvic inflammatory disease"}],"answerId":"b","explanation":"Chronic anovulation in CAH can lead to endometrial hyperplasia due to unopposed estrogen.","kind":"integration","linkedModuleIds":["add-endometrial-hyperplasia-and-its-risk-of-progression-to-c"],"origin":"ai"}],"add-molar-pregnancy-diagnosis-and-management":[{"id":"add-molar-pregnancy-diagnosis-and-management~ai-0","moduleId":"add-molar-pregnancy-diagnosis-and-management","stem":"Which karyotype is most commonly associated with a complete molar pregnancy?","options":[{"id":"a","text":"46,XX"},{"id":"b","text":"69,XXX"},{"id":"c","text":"69,XXY"},{"id":"d","text":"46,XY"}],"answerId":"a","explanation":"Complete moles typically have a 46,XX karyotype, usually of paternal origin.","kind":"recall","origin":"ai"},{"id":"add-molar-pregnancy-diagnosis-and-management~ai-1","moduleId":"add-molar-pregnancy-diagnosis-and-management","stem":"A 28-year-old woman presents with vaginal bleeding and a uterus larger than expected for gestational age. Ultrasound reveals a 'snowstorm' pattern. What is the most likely diagnosis?","options":[{"id":"a","text":"Complete molar pregnancy"},{"id":"b","text":"Partial molar pregnancy"},{"id":"c","text":"Ectopic pregnancy"},{"id":"d","text":"Normal intrauterine pregnancy"}],"answerId":"a","explanation":"The 'snowstorm' pattern on ultrasound is characteristic of a complete molar pregnancy.","kind":"clinical","origin":"ai"},{"id":"add-molar-pregnancy-diagnosis-and-management~ai-2","moduleId":"add-molar-pregnancy-diagnosis-and-management","stem":"What is the primary reason for serial beta-hCG monitoring after evacuation of a molar pregnancy?","options":[{"id":"a","text":"To confirm complete evacuation"},{"id":"b","text":"To detect persistent gestational trophoblastic disease"},{"id":"c","text":"To monitor for recurrence of molar pregnancy"},{"id":"d","text":"To assess for development of choriocarcinoma"}],"answerId":"b","explanation":"Serial beta-hCG monitoring is crucial to detect persistent gestational trophoblastic disease.","kind":"mechanism","origin":"ai"},{"id":"add-molar-pregnancy-diagnosis-and-management~ai-3","moduleId":"add-molar-pregnancy-diagnosis-and-management","stem":"Which of the following is a risk factor for developing a molar pregnancy?","options":[{"id":"a","text":"Advanced maternal age"},{"id":"b","text":"History of ectopic pregnancy"},{"id":"c","text":"Multiparity"},{"id":"d","text":"Use of oral contraceptives"}],"answerId":"a","explanation":"Extremes of maternal age, particularly advanced age, are risk factors for molar pregnancy.","kind":"recall","origin":"ai"},{"id":"add-molar-pregnancy-diagnosis-and-management~ai-4","moduleId":"add-molar-pregnancy-diagnosis-and-management","stem":"A patient with a suspected molar pregnancy has an ultrasound showing fetal tissue. What is the most likely diagnosis?","options":[{"id":"a","text":"Complete molar pregnancy"},{"id":"b","text":"Partial molar pregnancy"},{"id":"c","text":"Ectopic pregnancy"},{"id":"d","text":"Blighted ovum"}],"answerId":"b","explanation":"Partial moles may have some fetal tissue present, unlike complete moles.","kind":"trap","origin":"ai"},{"id":"add-molar-pregnancy-diagnosis-and-management~ai-5","moduleId":"add-molar-pregnancy-diagnosis-and-management","stem":"In the context of molar pregnancy, what does a 'snowstorm' appearance on ultrasound indicate?","options":[{"id":"a","text":"Presence of fetal tissue"},{"id":"b","text":"Hydropic swelling of chorionic villi"},{"id":"c","text":"Normal pregnancy"},{"id":"d","text":"Ectopic pregnancy"}],"answerId":"b","explanation":"The 'snowstorm' appearance is due to hydropic swelling of chorionic villi in molar pregnancy.","kind":"mechanism","origin":"ai"},{"id":"add-molar-pregnancy-diagnosis-and-management~ai-6","moduleId":"add-molar-pregnancy-diagnosis-and-management","stem":"How does the pathogenesis of a complete molar pregnancy differ from that of an ectopic pregnancy?","options":[{"id":"a","text":"Complete moles have abnormal trophoblastic proliferation; ectopic pregnancies occur outside the uterine cavity"},{"id":"b","text":"Complete moles occur outside the uterine cavity; ectopic pregnancies have abnormal trophoblastic proliferation"},{"id":"c","text":"Both involve abnormal trophoblastic proliferation"},{"id":"d","text":"Both occur outside the uterine cavity"}],"answerId":"a","explanation":"Complete moles are characterized by abnormal trophoblastic proliferation, whereas ectopic pregnancies involve implantation outside the uterine cavity.","kind":"integration","linkedModuleIds":["add-ectopic-pregnancy"],"origin":"ai"},{"id":"add-molar-pregnancy-diagnosis-and-management~ai-7","moduleId":"add-molar-pregnancy-diagnosis-and-management","stem":"A 35-year-old woman with a history of molar pregnancy is concerned about recurrence. Which pre-embryonic factor is most relevant to her risk?","options":[{"id":"a","text":"Paternal chromosomal contribution"},{"id":"b","text":"Maternal age"},{"id":"c","text":"Fetal tissue presence"},{"id":"d","text":"Previous ectopic pregnancy"}],"answerId":"b","explanation":"Maternal age is a significant risk factor for recurrence of molar pregnancy.","kind":"integration","linkedModuleIds":["preembryonic-clinical-applications"],"origin":"ai"}],"add-preterm-labor-risk-factors-and-management":[{"id":"add-preterm-labor-risk-factors-and-management~ai-0","moduleId":"add-preterm-labor-risk-factors-and-management","stem":"Which of the following is a major risk factor for preterm labor?","options":[{"id":"a","text":"Multiple gestation"},{"id":"b","text":"Advanced maternal age"},{"id":"c","text":"Gestational diabetes"},{"id":"d","text":"Preeclampsia"}],"answerId":"a","explanation":"Multiple gestation increases uterine stretch, which is a significant risk factor for preterm labor.","kind":"recall","origin":"ai"},{"id":"add-preterm-labor-risk-factors-and-management~ai-1","moduleId":"add-preterm-labor-risk-factors-and-management","stem":"A 30-year-old pregnant woman at 32 weeks gestation presents with regular uterine contractions. Which test would most likely predict the risk of preterm delivery?","options":[{"id":"a","text":"Cervical length measurement"},{"id":"b","text":"Amniotic fluid index"},{"id":"c","text":"Non-stress test"},{"id":"d","text":"Biophysical profile"}],"answerId":"a","explanation":"Cervical length measurement by transvaginal ultrasound is used to assess the risk of preterm labor.","kind":"clinical","origin":"ai"},{"id":"add-preterm-labor-risk-factors-and-management~ai-2","moduleId":"add-preterm-labor-risk-factors-and-management","stem":"What is the primary purpose of administering antenatal corticosteroids in the management of preterm labor?","options":[{"id":"a","text":"Enhance fetal lung maturity"},{"id":"b","text":"Delay labor onset"},{"id":"c","text":"Reduce maternal blood pressure"},{"id":"d","text":"Prevent infection"}],"answerId":"a","explanation":"Antenatal corticosteroids like betamethasone are given to enhance fetal lung maturity if preterm delivery is imminent.","kind":"mechanism","origin":"ai"},{"id":"add-preterm-labor-risk-factors-and-management~ai-3","moduleId":"add-preterm-labor-risk-factors-and-management","stem":"A negative fetal fibronectin test in a pregnant woman at 28 weeks suggests which of the following?","options":[{"id":"a","text":"Low risk of preterm delivery"},{"id":"b","text":"Imminent preterm delivery"},{"id":"c","text":"Increased risk of preterm delivery"},{"id":"d","text":"Need for immediate tocolytic therapy"}],"answerId":"a","explanation":"A negative fetal fibronectin test suggests a low risk of preterm delivery within the next 7-14 days.","kind":"trap","origin":"ai"},{"id":"add-preterm-labor-risk-factors-and-management~ai-4","moduleId":"add-preterm-labor-risk-factors-and-management","stem":"Which medication is used for neuroprotection in preterm births before 32 weeks gestation?","options":[{"id":"a","text":"Magnesium sulfate"},{"id":"b","text":"Nifedipine"},{"id":"c","text":"Indomethacin"},{"id":"d","text":"Betamethasone"}],"answerId":"a","explanation":"Magnesium sulfate is used for neuroprotection in preterm births before 32 weeks gestation.","kind":"recall","origin":"ai"},{"id":"add-preterm-labor-risk-factors-and-management~ai-5","moduleId":"add-preterm-labor-risk-factors-and-management","stem":"In the context of preterm labor, what does a cervical length of less than 25 mm indicate?","options":[{"id":"a","text":"Increased risk of preterm labor"},{"id":"b","text":"Normal cervical length"},{"id":"c","text":"Resolved risk of preterm labor"},{"id":"d","text":"Requirement for immediate delivery"}],"answerId":"a","explanation":"A cervical length of less than 25 mm is associated with an increased risk of preterm labor.","kind":"mechanism","origin":"ai"},{"id":"add-preterm-labor-risk-factors-and-management~ai-6","moduleId":"add-preterm-labor-risk-factors-and-management","stem":"How does progesterone influence the risk of preterm labor?","options":[{"id":"a","text":"Maintains uterine quiescence"},{"id":"b","text":"Induces uterine contractions"},{"id":"c","text":"Increases cervical dilation"},{"id":"d","text":"Stimulates fetal lung maturity"}],"answerId":"a","explanation":"Progesterone helps maintain uterine quiescence, reducing the risk of preterm labor.","kind":"integration","linkedModuleIds":["add-hormonal-regulation-of-parturition"],"origin":"ai"},{"id":"add-preterm-labor-risk-factors-and-management~ai-7","moduleId":"add-preterm-labor-risk-factors-and-management","stem":"A patient with a history of preterm labor is at increased risk for which of the following in a subsequent pregnancy?","options":[{"id":"a","text":"Preterm labor"},{"id":"b","text":"Ectopic pregnancy"},{"id":"c","text":"Gestational diabetes"},{"id":"d","text":"Placenta previa"}],"answerId":"a","explanation":"A history of preterm labor is a significant risk factor for recurrence in subsequent pregnancies.","kind":"integration","linkedModuleIds":["add-ectopic-pregnancy"],"origin":"ai"}],"add-testicular-torsion-diagnosis-and-management":[{"id":"add-testicular-torsion-diagnosis-and-management~ai-0","moduleId":"add-testicular-torsion-diagnosis-and-management","stem":"A 15-year-old male presents with sudden onset of severe left scrotal pain and nausea. On examination, the left testis is high-riding with an absent cremasteric reflex. What is the most likely diagnosis?","options":[{"id":"a","text":"Testicular torsion"},{"id":"b","text":"Epididymitis"},{"id":"c","text":"Inguinal hernia"},{"id":"d","text":"Hydrocele"}],"answerId":"a","explanation":"The presentation of sudden severe pain, high-riding testis, and absent cremasteric reflex is classic for testicular torsion.","kind":"clinical","origin":"ai"},{"id":"add-testicular-torsion-diagnosis-and-management~ai-1","moduleId":"add-testicular-torsion-diagnosis-and-management","stem":"Which of the following is the most critical factor in the management of testicular torsion?","options":[{"id":"a","text":"Patient age"},{"id":"b","text":"Time to intervention"},{"id":"c","text":"Severity of pain"},{"id":"d","text":"Presence of nausea"}],"answerId":"b","explanation":"Time to intervention is critical; detorsion within 6 hours is necessary to salvage the testis.","kind":"recall","origin":"ai"},{"id":"add-testicular-torsion-diagnosis-and-management~ai-2","moduleId":"add-testicular-torsion-diagnosis-and-management","stem":"A Doppler ultrasound is performed on a patient suspected of having testicular torsion. What finding would confirm the diagnosis?","options":[{"id":"a","text":"Increased blood flow to the affected testis"},{"id":"b","text":"Decreased blood flow to the affected testis"},{"id":"c","text":"Normal blood flow to both testes"},{"id":"d","text":"Increased blood flow to the contralateral testis"}],"answerId":"b","explanation":"Decreased blood flow to the affected testis on Doppler ultrasound confirms testicular torsion.","kind":"mechanism","origin":"ai"},{"id":"add-testicular-torsion-diagnosis-and-management~ai-3","moduleId":"add-testicular-torsion-diagnosis-and-management","stem":"Which anatomical abnormality predisposes an individual to testicular torsion?","options":[{"id":"a","text":"Bell clapper deformity"},{"id":"b","text":"Cryptorchidism"},{"id":"c","text":"Varicocele"},{"id":"d","text":"Hydrocele"}],"answerId":"a","explanation":"The bell clapper deformity allows increased testicular mobility, predisposing to torsion.","kind":"recall","origin":"ai"},{"id":"add-testicular-torsion-diagnosis-and-management~ai-4","moduleId":"add-testicular-torsion-diagnosis-and-management","stem":"A 17-year-old male presents with gradual onset of scrotal pain and swelling. The cremasteric reflex is present. What is the most likely diagnosis?","options":[{"id":"a","text":"Testicular torsion"},{"id":"b","text":"Epididymitis"},{"id":"c","text":"Testicular cancer"},{"id":"d","text":"Inguinal hernia"}],"answerId":"b","explanation":"Gradual onset of pain with a present cremasteric reflex suggests epididymitis, not torsion.","kind":"trap","origin":"ai"},{"id":"add-testicular-torsion-diagnosis-and-management~ai-5","moduleId":"add-testicular-torsion-diagnosis-and-management","stem":"How does the absence of the cremasteric reflex aid in differentiating testicular torsion from epididymitis?","options":[{"id":"a","text":"Indicates nerve involvement in torsion"},{"id":"b","text":"Suggests infection in epididymitis"},{"id":"c","text":"Confirms torsion due to ischemia"},{"id":"d","text":"Rules out torsion due to inflammation"}],"answerId":"c","explanation":"The absent cremasteric reflex in torsion is due to ischemia affecting the nerve reflex.","kind":"mechanism","origin":"ai"},{"id":"add-testicular-torsion-diagnosis-and-management~ai-6","moduleId":"add-testicular-torsion-diagnosis-and-management","stem":"A 14-year-old male with a history of congenital adrenal hyperplasia presents with acute scrotal pain. What is the most important initial step in management?","options":[{"id":"a","text":"Immediate surgical exploration"},{"id":"b","text":"Administration of corticosteroids"},{"id":"c","text":"Performing a scrotal ultrasound"},{"id":"d","text":"Observation and follow-up"}],"answerId":"a","explanation":"Testicular torsion requires immediate surgical exploration to prevent testicular loss.","kind":"integration","linkedModuleIds":["add-congenital-adrenal-hyperplasia-cah-neonatal-presentation"],"origin":"ai"},{"id":"add-testicular-torsion-diagnosis-and-management~ai-7","moduleId":"add-testicular-torsion-diagnosis-and-management","stem":"Which structure, if abnormally positioned, can lead to testicular torsion due to its role in supporting the testis?","options":[{"id":"a","text":"Epididymis"},{"id":"b","text":"Spermatic cord"},{"id":"c","text":"Vas deferens"},{"id":"d","text":"Tunica albuginea"}],"answerId":"b","explanation":"The spermatic cord, if twisted, leads to testicular torsion by cutting off blood supply.","kind":"integration","linkedModuleIds":["hrp1-testis-epididymis-vas-anatomy"],"origin":"ai"}],"add-ovarian-hyperstimulation-syndrome-ohss":[{"id":"add-ovarian-hyperstimulation-syndrome-ohss~ai-0","moduleId":"add-ovarian-hyperstimulation-syndrome-ohss","stem":"Which of the following is a primary risk factor for developing Ovarian Hyperstimulation Syndrome (OHSS)?","options":[{"id":"a","text":"High estradiol levels (>3000 pg/mL)"},{"id":"b","text":"Low body mass index"},{"id":"c","text":"History of endometriosis"},{"id":"d","text":"Use of oral contraceptives"}],"answerId":"a","explanation":"High estradiol levels are a significant risk factor for OHSS due to increased ovarian response.","kind":"recall","origin":"ai"},{"id":"add-ovarian-hyperstimulation-syndrome-ohss~ai-1","moduleId":"add-ovarian-hyperstimulation-syndrome-ohss","stem":"What is the primary mechanism leading to ascites in Ovarian Hyperstimulation Syndrome (OHSS)?","options":[{"id":"a","text":"Increased vascular permeability"},{"id":"b","text":"Decreased renal function"},{"id":"c","text":"Increased hepatic production of albumin"},{"id":"d","text":"Decreased lymphatic drainage"}],"answerId":"a","explanation":"OHSS causes increased vascular permeability, leading to fluid shifts and ascites.","kind":"mechanism","origin":"ai"},{"id":"add-ovarian-hyperstimulation-syndrome-ohss~ai-2","moduleId":"add-ovarian-hyperstimulation-syndrome-ohss","stem":"A patient undergoing fertility treatment presents with abdominal distention and rapid weight gain. Which condition should be suspected?","options":[{"id":"a","text":"Polycystic Ovary Syndrome"},{"id":"b","text":"Ovarian Hyperstimulation Syndrome"},{"id":"c","text":"Ectopic Pregnancy"},{"id":"d","text":"Congenital Adrenal Hyperplasia"}],"answerId":"b","explanation":"These symptoms are indicative of OHSS, especially in the context of fertility treatment.","kind":"clinical","origin":"ai"},{"id":"add-ovarian-hyperstimulation-syndrome-ohss~ai-3","moduleId":"add-ovarian-hyperstimulation-syndrome-ohss","stem":"Which of the following is a potential severe complication of untreated Ovarian Hyperstimulation Syndrome (OHSS)?","options":[{"id":"a","text":"Thromboembolism"},{"id":"b","text":"Hypoglycemia"},{"id":"c","text":"Hypercalcemia"},{"id":"d","text":"Hypotension"}],"answerId":"a","explanation":"Severe OHSS can lead to thromboembolism due to hemoconcentration and fluid shifts.","kind":"recall","origin":"ai"},{"id":"add-ovarian-hyperstimulation-syndrome-ohss~ai-4","moduleId":"add-ovarian-hyperstimulation-syndrome-ohss","stem":"A patient with suspected OHSS is found to have pleural effusion. What is the underlying cause of this finding?","options":[{"id":"a","text":"Fluid shift due to increased vascular permeability"},{"id":"b","text":"Increased intrathoracic pressure"},{"id":"c","text":"Decreased cardiac output"},{"id":"d","text":"Lymphatic obstruction"}],"answerId":"a","explanation":"Pleural effusion in OHSS is due to fluid shifts from increased vascular permeability.","kind":"mechanism","origin":"ai"},{"id":"add-ovarian-hyperstimulation-syndrome-ohss~ai-5","moduleId":"add-ovarian-hyperstimulation-syndrome-ohss","stem":"In the management of OHSS, which medication can be used to reduce the severity of symptoms?","options":[{"id":"a","text":"Cabergoline"},{"id":"b","text":"Metformin"},{"id":"c","text":"Clomiphene"},{"id":"d","text":"Spironolactone"}],"answerId":"a","explanation":"Cabergoline, a dopamine agonist, can reduce the severity of OHSS by decreasing vascular permeability.","kind":"recall","origin":"ai"},{"id":"add-ovarian-hyperstimulation-syndrome-ohss~ai-6","moduleId":"add-ovarian-hyperstimulation-syndrome-ohss","stem":"A patient with a history of OHSS presents with abdominal pain and vaginal bleeding. Which condition should be considered in the differential diagnosis?","options":[{"id":"a","text":"Ectopic Pregnancy"},{"id":"b","text":"Congenital Adrenal Hyperplasia"},{"id":"c","text":"Endometriosis"},{"id":"d","text":"Polycystic Ovary Syndrome"}],"answerId":"a","explanation":"Ectopic pregnancy should be considered, especially in patients with a history of fertility treatments.","kind":"integration","linkedModuleIds":["add-ectopic-pregnancy"],"origin":"ai"},{"id":"add-ovarian-hyperstimulation-syndrome-ohss~ai-7","moduleId":"add-ovarian-hyperstimulation-syndrome-ohss","stem":"A neonate presents with ambiguous genitalia and electrolyte imbalances. Which condition should be considered alongside OHSS in a differential diagnosis?","options":[{"id":"a","text":"Congenital Adrenal Hyperplasia"},{"id":"b","text":"Ectopic Pregnancy"},{"id":"c","text":"Turner Syndrome"},{"id":"d","text":"Klinefelter Syndrome"}],"answerId":"a","explanation":"Congenital Adrenal Hyperplasia can present with ambiguous genitalia and is a differential diagnosis in neonates.","kind":"integration","linkedModuleIds":["add-congenital-adrenal-hyperplasia-cah-neonatal-presentation"],"origin":"ai"}],"add-placenta-accreta-spectrum-pas":[{"id":"add-placenta-accreta-spectrum-pas~ai-0","moduleId":"add-placenta-accreta-spectrum-pas","stem":"Which of the following is a characteristic feature of placenta accreta?","options":[{"id":"a","text":"Attachment to the myometrium without invasion"},{"id":"b","text":"Invasion into the myometrium"},{"id":"c","text":"Invasion through the myometrium into serosa"},{"id":"d","text":"Positioning over the cervical os"}],"answerId":"a","explanation":"Placenta accreta involves attachment to the myometrium without invasion.","kind":"recall","origin":"ai"},{"id":"add-placenta-accreta-spectrum-pas~ai-1","moduleId":"add-placenta-accreta-spectrum-pas","stem":"A 32-year-old woman with a history of two previous cesarean sections presents with antepartum hemorrhage. Ultrasound shows an anterior placenta. What is the most likely diagnosis?","options":[{"id":"a","text":"Placenta previa"},{"id":"b","text":"Placenta accreta"},{"id":"c","text":"Placenta increta"},{"id":"d","text":"Placenta percreta"}],"answerId":"b","explanation":"Antepartum hemorrhage with a history of cesarean sections suggests placenta accreta spectrum.","kind":"clinical","origin":"ai"},{"id":"add-placenta-accreta-spectrum-pas~ai-2","moduleId":"add-placenta-accreta-spectrum-pas","stem":"Which mechanism explains the difficulty in placental separation in placenta accreta spectrum?","options":[{"id":"a","text":"Abnormal placental positioning"},{"id":"b","text":"Abnormal trophoblastic invasion"},{"id":"c","text":"Uterine atony"},{"id":"d","text":"Cervical incompetence"}],"answerId":"b","explanation":"Difficulty in placental separation is due to abnormal trophoblastic invasion into the myometrium.","kind":"mechanism","origin":"ai"},{"id":"add-placenta-accreta-spectrum-pas~ai-3","moduleId":"add-placenta-accreta-spectrum-pas","stem":"What is the primary management strategy for a confirmed case of placenta percreta?","options":[{"id":"a","text":"Expectant management"},{"id":"b","text":"Planned cesarean delivery with possible hysterectomy"},{"id":"c","text":"Vaginal delivery"},{"id":"d","text":"Uterine artery embolization"}],"answerId":"b","explanation":"Planned delivery and possible hysterectomy are necessary to control hemorrhage in placenta percreta.","kind":"recall","origin":"ai"},{"id":"add-placenta-accreta-spectrum-pas~ai-4","moduleId":"add-placenta-accreta-spectrum-pas","stem":"A patient with a history of placenta previa is at increased risk for which of the following conditions in subsequent pregnancies?","options":[{"id":"a","text":"Placenta accreta spectrum"},{"id":"b","text":"Ectopic pregnancy"},{"id":"c","text":"Gestational diabetes"},{"id":"d","text":"Preeclampsia"}],"answerId":"a","explanation":"Previous placenta previa increases the risk of placenta accreta spectrum in future pregnancies.","kind":"trap","origin":"ai"},{"id":"add-placenta-accreta-spectrum-pas~ai-5","moduleId":"add-placenta-accreta-spectrum-pas","stem":"In the context of placenta accreta spectrum, what is the main difference between placenta increta and placenta percreta?","options":[{"id":"a","text":"Increta invades into the myometrium; percreta invades through it"},{"id":"b","text":"Increta is limited to the endometrium; percreta invades the myometrium"},{"id":"c","text":"Increta involves the serosa; percreta does not"},{"id":"d","text":"Increta is a positional issue; percreta is not"}],"answerId":"a","explanation":"Placenta increta invades into the myometrium, whereas placenta percreta invades through the myometrium into serosa or adjacent organs.","kind":"recall","origin":"ai"},{"id":"add-placenta-accreta-spectrum-pas~ai-6","moduleId":"add-placenta-accreta-spectrum-pas","stem":"A newborn presents with ambiguous genitalia and salt-wasting crisis. Which maternal condition could potentially complicate the pregnancy with a similar pathophysiological mechanism?","options":[{"id":"a","text":"Placenta accreta spectrum"},{"id":"b","text":"Ectopic pregnancy"},{"id":"c","text":"Congenital adrenal hyperplasia"},{"id":"d","text":"Placenta previa"}],"answerId":"a","explanation":"Both placenta accreta spectrum and congenital adrenal hyperplasia involve abnormal tissue invasion, albeit in different contexts.","kind":"integration","linkedModuleIds":["add-congenital-adrenal-hyperplasia-cah-neonatal-presentation"],"origin":"ai"},{"id":"add-placenta-accreta-spectrum-pas~ai-7","moduleId":"add-placenta-accreta-spectrum-pas","stem":"Which placental abnormality is most likely to be associated with a history of multiple cesarean sections?","options":[{"id":"a","text":"Placenta previa"},{"id":"b","text":"Placenta accreta spectrum"},{"id":"c","text":"Ectopic pregnancy"},{"id":"d","text":"Placental abruption"}],"answerId":"b","explanation":"Multiple cesarean sections increase the risk of placenta accreta spectrum due to scarring and abnormal placental attachment.","kind":"integration","linkedModuleIds":["placenta-clinical-abnormalities"],"origin":"ai"}],"add-premature-ovarian-insufficiency-poi":[{"id":"add-premature-ovarian-insufficiency-poi~ai-0","moduleId":"add-premature-ovarian-insufficiency-poi","stem":"Which laboratory finding is characteristic of Premature Ovarian Insufficiency (POI)?","options":[{"id":"a","text":"Elevated FSH levels"},{"id":"b","text":"Low LH levels"},{"id":"c","text":"Elevated estradiol levels"},{"id":"d","text":"Low prolactin levels"}],"answerId":"a","explanation":"POI is characterized by elevated FSH levels due to decreased ovarian function.","kind":"recall","origin":"ai"},{"id":"add-premature-ovarian-insufficiency-poi~ai-1","moduleId":"add-premature-ovarian-insufficiency-poi","stem":"A 35-year-old woman presents with amenorrhea and hot flashes. Her FSH level is 45 IU/L. What is the most likely diagnosis?","options":[{"id":"a","text":"Polycystic Ovary Syndrome"},{"id":"b","text":"Premature Ovarian Insufficiency"},{"id":"c","text":"Hypothyroidism"},{"id":"d","text":"Hyperprolactinemia"}],"answerId":"b","explanation":"The elevated FSH level and symptoms are indicative of Premature Ovarian Insufficiency.","kind":"clinical","origin":"ai"},{"id":"add-premature-ovarian-insufficiency-poi~ai-2","moduleId":"add-premature-ovarian-insufficiency-poi","stem":"Which genetic condition is associated with Premature Ovarian Insufficiency?","options":[{"id":"a","text":"Turner syndrome"},{"id":"b","text":"Klinefelter syndrome"},{"id":"c","text":"Down syndrome"},{"id":"d","text":"Marfan syndrome"}],"answerId":"a","explanation":"Turner syndrome is a common genetic cause of POI.","kind":"recall","origin":"ai"},{"id":"add-premature-ovarian-insufficiency-poi~ai-3","moduleId":"add-premature-ovarian-insufficiency-poi","stem":"What is the primary reason for prescribing hormone replacement therapy (HRT) in patients with Premature Ovarian Insufficiency?","options":[{"id":"a","text":"To prevent osteoporosis"},{"id":"b","text":"To increase fertility"},{"id":"c","text":"To reduce the risk of breast cancer"},{"id":"d","text":"To treat hyperlipidemia"}],"answerId":"a","explanation":"HRT is used to prevent osteoporosis and alleviate symptoms of hypoestrogenism.","kind":"mechanism","origin":"ai"},{"id":"add-premature-ovarian-insufficiency-poi~ai-4","moduleId":"add-premature-ovarian-insufficiency-poi","stem":"A 28-year-old woman with a history of chemotherapy presents with amenorrhea. Her lab results show elevated FSH and low estradiol. What is the most likely cause of her condition?","options":[{"id":"a","text":"Autoimmune disorder"},{"id":"b","text":"Genetic mutation"},{"id":"c","text":"Iatrogenic factors"},{"id":"d","text":"Infectious disease"}],"answerId":"c","explanation":"Chemotherapy is an iatrogenic factor that can lead to POI.","kind":"clinical","origin":"ai"},{"id":"add-premature-ovarian-insufficiency-poi~ai-5","moduleId":"add-premature-ovarian-insufficiency-poi","stem":"In the context of Premature Ovarian Insufficiency, which of the following is a potential long-term complication due to hypoestrogenism?","options":[{"id":"a","text":"Increased risk of osteoporosis"},{"id":"b","text":"Increased risk of diabetes"},{"id":"c","text":"Increased risk of liver disease"},{"id":"d","text":"Increased risk of hyperthyroidism"}],"answerId":"a","explanation":"Hypoestrogenism in POI is associated with an increased risk of osteoporosis.","kind":"recall","origin":"ai"},{"id":"add-premature-ovarian-insufficiency-poi~ai-6","moduleId":"add-premature-ovarian-insufficiency-poi","stem":"A patient with Premature Ovarian Insufficiency is concerned about her fertility. Which linked condition should be considered when discussing fertility options?","options":[{"id":"a","text":"Cervical Insufficiency"},{"id":"b","text":"Congenital Adrenal Hyperplasia"},{"id":"c","text":"Ectopic Pregnancy"},{"id":"d","text":"Turner syndrome"}],"answerId":"a","explanation":"Cervical insufficiency can impact fertility and pregnancy outcomes.","kind":"integration","linkedModuleIds":["add-cervical-insufficiency-and-its-management"],"origin":"ai"},{"id":"add-premature-ovarian-insufficiency-poi~ai-7","moduleId":"add-premature-ovarian-insufficiency-poi","stem":"How does the pathogenesis of Premature Ovarian Insufficiency differ from that of Congenital Adrenal Hyperplasia?","options":[{"id":"a","text":"POI involves ovarian failure, while CAH involves adrenal enzyme deficiency"},{"id":"b","text":"POI involves adrenal hyperplasia, while CAH involves ovarian failure"},{"id":"c","text":"Both involve adrenal hyperplasia"},{"id":"d","text":"Both involve ovarian failure"}],"answerId":"a","explanation":"POI is due to ovarian failure, whereas CAH is due to adrenal enzyme deficiency.","kind":"integration","linkedModuleIds":["add-congenital-adrenal-hyperplasia-cah-neonatal-presentation"],"origin":"ai"}],"add-intrauterine-growth-restriction-iugr-diagnosis-and-manag":[{"id":"add-intrauterine-growth-restriction-iugr-diagnosis-and-manag~ai-0","moduleId":"add-intrauterine-growth-restriction-iugr-diagnosis-and-manag","stem":"Which of the following is a characteristic feature of asymmetrical IUGR?","options":[{"id":"a","text":"Head sparing"},{"id":"b","text":"Proportionate reduction in fetal size"},{"id":"c","text":"Macrosomia"},{"id":"d","text":"Increased amniotic fluid"}],"answerId":"a","explanation":"Asymmetrical IUGR is characterized by head sparing due to preferential blood flow to the brain.","kind":"recall","origin":"ai"},{"id":"add-intrauterine-growth-restriction-iugr-diagnosis-and-manag~ai-1","moduleId":"add-intrauterine-growth-restriction-iugr-diagnosis-and-manag","stem":"A 30-year-old pregnant woman with chronic hypertension is at risk for which fetal condition?","options":[{"id":"a","text":"Macrosomia"},{"id":"b","text":"Intrauterine Growth Restriction"},{"id":"c","text":"Polyhydramnios"},{"id":"d","text":"Neural tube defects"}],"answerId":"b","explanation":"Chronic hypertension is a risk factor for IUGR due to placental insufficiency.","kind":"clinical","origin":"ai"},{"id":"add-intrauterine-growth-restriction-iugr-diagnosis-and-manag~ai-2","moduleId":"add-intrauterine-growth-restriction-iugr-diagnosis-and-manag","stem":"Which diagnostic tool is most appropriate for assessing placental blood flow in suspected IUGR?","options":[{"id":"a","text":"Amniocentesis"},{"id":"b","text":"Doppler ultrasound of the umbilical artery"},{"id":"c","text":"MRI"},{"id":"d","text":"CT scan"}],"answerId":"b","explanation":"Doppler ultrasound of the umbilical artery is used to assess placental blood flow in IUGR.","kind":"mechanism","origin":"ai"},{"id":"add-intrauterine-growth-restriction-iugr-diagnosis-and-manag~ai-3","moduleId":"add-intrauterine-growth-restriction-iugr-diagnosis-and-manag","stem":"A fetus with symmetrical IUGR is most likely to have experienced which of the following?","options":[{"id":"a","text":"Early pregnancy insult"},{"id":"b","text":"Placental insufficiency"},{"id":"c","text":"Maternal diabetes"},{"id":"d","text":"Excessive maternal weight gain"}],"answerId":"a","explanation":"Symmetrical IUGR is often due to early pregnancy insults affecting all fetal growth parameters.","kind":"mechanism","origin":"ai"},{"id":"add-intrauterine-growth-restriction-iugr-diagnosis-and-manag~ai-4","moduleId":"add-intrauterine-growth-restriction-iugr-diagnosis-and-manag","stem":"In the context of IUGR, which of the following findings would be unexpected during a physical examination of a pregnant woman?","options":[{"id":"a","text":"Fundal height less than expected for gestational age"},{"id":"b","text":"Excessive fetal movements"},{"id":"c","text":"Decreased fetal movements"},{"id":"d","text":"Normal fundal height"}],"answerId":"b","explanation":"Excessive fetal movements are not typically associated with IUGR; decreased movements are more common.","kind":"trap","origin":"ai"},{"id":"add-intrauterine-growth-restriction-iugr-diagnosis-and-manag~ai-5","moduleId":"add-intrauterine-growth-restriction-iugr-diagnosis-and-manag","stem":"Which of the following is a shared risk factor for both IUGR and ectopic pregnancy?","options":[{"id":"a","text":"Smoking"},{"id":"b","text":"High maternal age"},{"id":"c","text":"Multiple gestation"},{"id":"d","text":"Previous cesarean section"}],"answerId":"a","explanation":"Smoking is a risk factor for both IUGR due to placental insufficiency and ectopic pregnancy due to tubal damage.","kind":"integration","linkedModuleIds":["add-ectopic-pregnancy"],"origin":"ai"},{"id":"add-intrauterine-growth-restriction-iugr-diagnosis-and-manag~ai-6","moduleId":"add-intrauterine-growth-restriction-iugr-diagnosis-and-manag","stem":"How does the pathophysiology of IUGR relate to potential complications in congenital adrenal hyperplasia (CAH)?","options":[{"id":"a","text":"Both involve placental insufficiency"},{"id":"b","text":"Both can lead to electrolyte imbalances"},{"id":"c","text":"Both involve genetic mutations"},{"id":"d","text":"Both can result in ambiguous genitalia"}],"answerId":"b","explanation":"IUGR can lead to stress and potential electrolyte imbalances, which is a concern in CAH due to adrenal insufficiency.","kind":"integration","linkedModuleIds":["add-congenital-adrenal-hyperplasia-cah-neonatal-presentation"],"origin":"ai"}],"add-hyperemesis-gravidarum-pathophysiology-and-management":[{"id":"add-hyperemesis-gravidarum-pathophysiology-and-management~ai-0","moduleId":"add-hyperemesis-gravidarum-pathophysiology-and-management","stem":"Which hormone is most strongly associated with the pathophysiology of hyperemesis gravidarum?","options":[{"id":"a","text":"Human chorionic gonadotropin (hCG)"},{"id":"b","text":"Progesterone"},{"id":"c","text":"Estrogen"},{"id":"d","text":"Prolactin"}],"answerId":"a","explanation":"Increased levels of hCG are associated with hyperemesis gravidarum.","kind":"recall","origin":"ai"},{"id":"add-hyperemesis-gravidarum-pathophysiology-and-management~ai-1","moduleId":"add-hyperemesis-gravidarum-pathophysiology-and-management","stem":"A pregnant woman presents with severe nausea, vomiting, and weight loss. Urinalysis shows ketosis. What is the most likely underlying mechanism for the ketosis?","options":[{"id":"a","text":"Prolonged vomiting and starvation"},{"id":"b","text":"Increased insulin resistance"},{"id":"c","text":"Excessive carbohydrate intake"},{"id":"d","text":"Hyperglycemia"}],"answerId":"a","explanation":"Ketosis results from prolonged vomiting and starvation due to inadequate nutritional intake.","kind":"mechanism","origin":"ai"},{"id":"add-hyperemesis-gravidarum-pathophysiology-and-management~ai-2","moduleId":"add-hyperemesis-gravidarum-pathophysiology-and-management","stem":"A 28-year-old woman in her first trimester presents with severe vomiting and dehydration. Which of the following is the first-line treatment?","options":[{"id":"a","text":"Ondansetron"},{"id":"b","text":"Metoclopramide"},{"id":"c","text":"Vitamin B6 with or without doxylamine"},{"id":"d","text":"Corticosteroids"}],"answerId":"c","explanation":"First-line treatment for hyperemesis gravidarum involves dietary modifications and vitamin B6 with or without doxylamine.","kind":"clinical","origin":"ai"},{"id":"add-hyperemesis-gravidarum-pathophysiology-and-management~ai-3","moduleId":"add-hyperemesis-gravidarum-pathophysiology-and-management","stem":"A patient with hyperemesis gravidarum is at risk for which neurological complication due to thiamine deficiency?","options":[{"id":"a","text":"Wernicke's encephalopathy"},{"id":"b","text":"Guillain-Barré syndrome"},{"id":"c","text":"Multiple sclerosis"},{"id":"d","text":"Parkinson's disease"}],"answerId":"a","explanation":"Thiamine deficiency in hyperemesis gravidarum can lead to Wernicke's encephalopathy.","kind":"recall","origin":"ai"},{"id":"add-hyperemesis-gravidarum-pathophysiology-and-management~ai-4","moduleId":"add-hyperemesis-gravidarum-pathophysiology-and-management","stem":"A pregnant woman with severe vomiting is suspected to have hyperemesis gravidarum. Which condition should be ruled out due to similar presenting symptoms?","options":[{"id":"a","text":"Gastroenteritis"},{"id":"b","text":"Peptic ulcer disease"},{"id":"c","text":"Thyroid disorder"},{"id":"d","text":"Ectopic pregnancy"}],"answerId":"d","explanation":"Ectopic pregnancy can present with similar symptoms and should be ruled out.","kind":"trap","origin":"ai"},{"id":"add-hyperemesis-gravidarum-pathophysiology-and-management~ai-5","moduleId":"add-hyperemesis-gravidarum-pathophysiology-and-management","stem":"A pregnant woman presents with severe vomiting and dehydration. She is found to have low blood pressure and tachycardia. What is the most likely cause of these findings?","options":[{"id":"a","text":"Electrolyte imbalance"},{"id":"b","text":"Dehydration"},{"id":"c","text":"Thyroid dysfunction"},{"id":"d","text":"Anemia"}],"answerId":"b","explanation":"Tachycardia and hypotension are secondary to dehydration in hyperemesis gravidarum.","kind":"mechanism","origin":"ai"},{"id":"add-hyperemesis-gravidarum-pathophysiology-and-management~ai-6","moduleId":"add-hyperemesis-gravidarum-pathophysiology-and-management","stem":"A 25-year-old woman with a history of hyperemesis gravidarum in a previous pregnancy is now pregnant again. Which condition related to adrenal function should be monitored due to its potential impact on pregnancy?","options":[{"id":"a","text":"Congenital adrenal hyperplasia"},{"id":"b","text":"Addison's disease"},{"id":"c","text":"Cushing's syndrome"},{"id":"d","text":"Pheochromocytoma"}],"answerId":"a","explanation":"Congenital adrenal hyperplasia can affect pregnancy and should be monitored.","kind":"integration","linkedModuleIds":["add-congenital-adrenal-hyperplasia-cah-neonatal-presentation"],"origin":"ai"},{"id":"add-hyperemesis-gravidarum-pathophysiology-and-management~ai-7","moduleId":"add-hyperemesis-gravidarum-pathophysiology-and-management","stem":"In a patient with hyperemesis gravidarum, which associated condition must be considered due to its potential to mimic the symptoms of severe nausea and vomiting?","options":[{"id":"a","text":"Ectopic pregnancy"},{"id":"b","text":"Gestational diabetes"},{"id":"c","text":"Pre-eclampsia"},{"id":"d","text":"Placenta previa"}],"answerId":"a","explanation":"Ectopic pregnancy can present with similar symptoms and should be considered.","kind":"integration","linkedModuleIds":["add-ectopic-pregnancy"],"origin":"ai"}],"add-premature-rupture-of-membranes-prom-diagnosis-and-manage":[{"id":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage~ai-0","moduleId":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage","stem":"A 28-year-old woman at 39 weeks of gestation presents with a sudden gush of fluid from the vagina. Which test would most likely confirm the diagnosis of PROM?","options":[{"id":"a","text":"Nitrazine test"},{"id":"b","text":"Vaginal pH test"},{"id":"c","text":"Urine dipstick"},{"id":"d","text":"Fetal fibronectin test"}],"answerId":"a","explanation":"The nitrazine test detects alkaline amniotic fluid, confirming PROM.","kind":"recall","origin":"ai"},{"id":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage~ai-1","moduleId":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage","stem":"A 32-year-old pregnant woman at 35 weeks presents with suspected PPROM. What is the most appropriate initial management?","options":[{"id":"a","text":"Immediate induction of labor"},{"id":"b","text":"Administration of corticosteroids"},{"id":"c","text":"Immediate cesarean section"},{"id":"d","text":"Observation without intervention"}],"answerId":"b","explanation":"Corticosteroids are given to enhance fetal lung maturity in PPROM.","kind":"mechanism","origin":"ai"},{"id":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage~ai-2","moduleId":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage","stem":"Which of the following is a common complication of preterm premature rupture of membranes (PPROM)?","options":[{"id":"a","text":"Chorioamnionitis"},{"id":"b","text":"Gestational diabetes"},{"id":"c","text":"Placenta previa"},{"id":"d","text":"Polyhydramnios"}],"answerId":"a","explanation":"Chorioamnionitis is a common infection-related complication of PPROM.","kind":"recall","origin":"ai"},{"id":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage~ai-3","moduleId":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage","stem":"A 30-year-old woman at 38 weeks of gestation presents with vaginal discharge. Which finding would differentiate PROM from normal discharge?","options":[{"id":"a","text":"White color"},{"id":"b","text":"Pooling of fluid in the vaginal fornix"},{"id":"c","text":"Absence of odor"},{"id":"d","text":"Presence of leukocytes"}],"answerId":"b","explanation":"Pooling of fluid in the vaginal fornix indicates amniotic fluid leakage, suggesting PROM.","kind":"trap","origin":"ai"},{"id":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage~ai-4","moduleId":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage","stem":"A 25-year-old woman with a history of smoking presents with PPROM at 34 weeks. Which of the following is a risk factor for her condition?","options":[{"id":"a","text":"Smoking"},{"id":"b","text":"High BMI"},{"id":"c","text":"Advanced maternal age"},{"id":"d","text":"Multiparity"}],"answerId":"a","explanation":"Smoking is a known risk factor for PPROM.","kind":"recall","origin":"ai"},{"id":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage~ai-5","moduleId":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage","stem":"A 29-year-old woman at 36 weeks of gestation presents with suspected PROM. Which examination finding supports this diagnosis?","options":[{"id":"a","text":"Negative nitrazine test"},{"id":"b","text":"Positive ferning pattern on microscopy"},{"id":"c","text":"Absence of pooling in the vaginal fornix"},{"id":"d","text":"Presence of cervical mucus plug"}],"answerId":"b","explanation":"A positive ferning pattern on microscopy indicates the presence of amniotic fluid.","kind":"recall","origin":"ai"},{"id":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage~ai-6","moduleId":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage","stem":"A 27-year-old woman presents with abdominal pain and vaginal bleeding at 8 weeks of gestation. Which condition should be considered in the differential diagnosis along with PROM?","options":[{"id":"a","text":"Ectopic pregnancy"},{"id":"b","text":"Placenta previa"},{"id":"c","text":"Gestational trophoblastic disease"},{"id":"d","text":"Uterine fibroids"}],"answerId":"a","explanation":"Ectopic pregnancy should be considered due to similar presenting symptoms.","kind":"integration","linkedModuleIds":["add-ectopic-pregnancy"],"origin":"ai"},{"id":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage~ai-7","moduleId":"add-premature-rupture-of-membranes-prom-diagnosis-and-manage","stem":"A 30-year-old woman with a history of premature ovarian insufficiency presents with PROM at 37 weeks. How might her history affect her current pregnancy management?","options":[{"id":"a","text":"No effect on management"},{"id":"b","text":"Increased risk of preterm labor"},{"id":"c","text":"Requirement for hormone replacement therapy"},{"id":"d","text":"Increased risk of gestational diabetes"}],"answerId":"b","explanation":"Premature ovarian insufficiency may increase the risk of preterm labor.","kind":"integration","linkedModuleIds":["add-premature-ovarian-insufficiency-diagnosis-and-management"],"origin":"ai"}],"add-testicular-cancer-diagnosis-and-management":[{"id":"add-testicular-cancer-diagnosis-and-management~ai-0","moduleId":"add-testicular-cancer-diagnosis-and-management","stem":"Which tumor marker is typically not elevated in seminoma?","options":[{"id":"a","text":"AFP"},{"id":"b","text":"β-hCG"},{"id":"c","text":"LDH"},{"id":"d","text":"CEA"}],"answerId":"a","explanation":"Seminomas typically do not elevate AFP, while β-hCG and LDH can be elevated.","kind":"recall","origin":"ai"},{"id":"add-testicular-cancer-diagnosis-and-management~ai-1","moduleId":"add-testicular-cancer-diagnosis-and-management","stem":"A 28-year-old male presents with a painless testicular mass. Which is the most appropriate initial management step?","options":[{"id":"a","text":"Radical inguinal orchiectomy"},{"id":"b","text":"Testicular ultrasound"},{"id":"c","text":"Serum tumor markers"},{"id":"d","text":"CT scan of the abdomen"}],"answerId":"b","explanation":"Testicular ultrasound is the first step to evaluate a testicular mass.","kind":"clinical","origin":"ai"},{"id":"add-testicular-cancer-diagnosis-and-management~ai-2","moduleId":"add-testicular-cancer-diagnosis-and-management","stem":"Which of the following is a risk factor for developing testicular cancer?","options":[{"id":"a","text":"Cryptorchidism"},{"id":"b","text":"Prostate hyperplasia"},{"id":"c","text":"Varicocele"},{"id":"d","text":"Hydrocele"}],"answerId":"a","explanation":"Cryptorchidism is a known risk factor for testicular cancer.","kind":"recall","origin":"ai"},{"id":"add-testicular-cancer-diagnosis-and-management~ai-3","moduleId":"add-testicular-cancer-diagnosis-and-management","stem":"A patient with a history of cryptorchidism presents with gynecomastia and elevated β-hCG. What is the most likely diagnosis?","options":[{"id":"a","text":"Seminoma"},{"id":"b","text":"Non-seminomatous germ cell tumor"},{"id":"c","text":"Leydig cell tumor"},{"id":"d","text":"Sertoli cell tumor"}],"answerId":"b","explanation":"NSGCTs can produce β-hCG, leading to gynecomastia.","kind":"mechanism","origin":"ai"},{"id":"add-testicular-cancer-diagnosis-and-management~ai-4","moduleId":"add-testicular-cancer-diagnosis-and-management","stem":"A 30-year-old male with a painless testicular mass is misdiagnosed with epididymitis. What key feature differentiates testicular cancer from epididymitis?","options":[{"id":"a","text":"Presence of fever"},{"id":"b","text":"Painful mass"},{"id":"c","text":"Painless mass"},{"id":"d","text":"Elevated WBC count"}],"answerId":"c","explanation":"Testicular cancer typically presents as a painless mass, unlike epididymitis which is painful.","kind":"trap","origin":"ai"},{"id":"add-testicular-cancer-diagnosis-and-management~ai-5","moduleId":"add-testicular-cancer-diagnosis-and-management","stem":"In a patient with congenital adrenal hyperplasia (CAH), which of the following testicular findings might be observed due to adrenal rest tumors?","options":[{"id":"a","text":"Painless testicular mass"},{"id":"b","text":"Painful testicular swelling"},{"id":"c","text":"Testicular atrophy"},{"id":"d","text":"Testicular torsion"}],"answerId":"a","explanation":"Adrenal rest tumors in CAH can present as painless testicular masses.","kind":"integration","linkedModuleIds":["add-congenital-adrenal-hyperplasia-cah-neonatal-presentation"],"origin":"ai"},{"id":"add-testicular-cancer-diagnosis-and-management~ai-6","moduleId":"add-testicular-cancer-diagnosis-and-management","stem":"A 32-year-old male presents with a testicular mass and elevated β-hCG. Which additional symptom might suggest an ectopic pregnancy in a female patient with similar β-hCG levels?","options":[{"id":"a","text":"Abdominal pain"},{"id":"b","text":"Gynecomastia"},{"id":"c","text":"Testicular pain"},{"id":"d","text":"Painless mass"}],"answerId":"a","explanation":"Abdominal pain is a common symptom in ectopic pregnancy, associated with elevated β-hCG.","kind":"integration","linkedModuleIds":["add-ectopic-pregnancy"],"origin":"ai"}],"hrp2-ovarian-germ-cell-tumors":[{"id":"hrp2-ovarian-germ-cell-tumors~ai-0","moduleId":"hrp2-ovarian-germ-cell-tumors","stem":"Which ovarian germ cell tumor is most likely to present with hyperthyroidism?","options":[{"id":"a","text":"Struma ovarii"},{"id":"b","text":"Dysgerminoma"},{"id":"c","text":"Yolk sac tumor"},{"id":"d","text":"Choriocarcinoma"}],"answerId":"a","explanation":"Struma ovarii is a teratoma composed of thyroid tissue, which can lead to hyperthyroidism.","kind":"recall","origin":"ai"},{"id":"hrp2-ovarian-germ-cell-tumors~ai-1","moduleId":"hrp2-ovarian-germ-cell-tumors","stem":"A 20-year-old woman presents with an ovarian mass and elevated alpha-fetoprotein (AFP). Which tumor is most likely?","options":[{"id":"a","text":"Yolk sac tumor"},{"id":"b","text":"Dysgerminoma"},{"id":"c","text":"Mature cystic teratoma"},{"id":"d","text":"Choriocarcinoma"}],"answerId":"a","explanation":"Yolk sac tumors are associated with elevated AFP levels.","kind":"clinical","origin":"ai"},{"id":"hrp2-ovarian-germ-cell-tumors~ai-2","moduleId":"hrp2-ovarian-germ-cell-tumors","stem":"What is the primary marker used to monitor dysgerminoma?","options":[{"id":"a","text":"LDH"},{"id":"b","text":"AFP"},{"id":"c","text":"β-hCG"},{"id":"d","text":"CA-125"}],"answerId":"a","explanation":"LDH is the primary marker for dysgerminoma, similar to seminoma in males.","kind":"recall","origin":"ai"},{"id":"hrp2-ovarian-germ-cell-tumors~ai-3","moduleId":"hrp2-ovarian-germ-cell-tumors","stem":"Which statement about mature and immature teratomas is correct?","options":[{"id":"a","text":"All teratomas are benign"},{"id":"b","text":"Immature teratomas contain malignant tissue"},{"id":"c","text":"Mature teratomas often metastasize"},{"id":"d","text":"Immature teratomas are always benign"}],"answerId":"b","explanation":"Immature teratomas contain immature neural tissue, which is malignant.","kind":"trap","origin":"ai"},{"id":"hrp2-ovarian-germ-cell-tumors~ai-4","moduleId":"hrp2-ovarian-germ-cell-tumors","stem":"A patient with a yolk sac tumor is likely to have which histological feature?","options":[{"id":"a","text":"Schiller-Duval bodies"},{"id":"b","text":"Call-Exner bodies"},{"id":"c","text":"Reinke crystals"},{"id":"d","text":"Psammoma bodies"}],"answerId":"a","explanation":"Schiller-Duval bodies are characteristic of yolk sac tumors.","kind":"recall","origin":"ai"},{"id":"hrp2-ovarian-germ-cell-tumors~ai-5","moduleId":"hrp2-ovarian-germ-cell-tumors","stem":"Which ovarian germ cell tumor is analogous to testicular seminoma?","options":[{"id":"a","text":"Dysgerminoma"},{"id":"b","text":"Yolk sac tumor"},{"id":"c","text":"Mature cystic teratoma"},{"id":"d","text":"Choriocarcinoma"}],"answerId":"a","explanation":"Dysgerminoma is the ovarian counterpart of testicular seminoma.","kind":"recall","origin":"ai"},{"id":"hrp2-ovarian-germ-cell-tumors~ai-6","moduleId":"hrp2-ovarian-germ-cell-tumors","stem":"How does the mechanism of germ cell differentiation relate to the presentation of ovarian germ cell tumors?","options":[{"id":"a","text":"Totipotent germ cells differentiate into various lineages"},{"id":"b","text":"Germ cells only form ectodermal tissues"},{"id":"c","text":"Germ cells are restricted to mesodermal differentiation"},{"id":"d","text":"Germ cells cannot differentiate into extra-embryonic tissues"}],"answerId":"a","explanation":"Totipotent germ cells can differentiate into embryonic and extra-embryonic tissues, leading to various tumor types.","kind":"mechanism","origin":"ai"},{"id":"hrp2-ovarian-germ-cell-tumors~ai-7","moduleId":"hrp2-ovarian-germ-cell-tumors","stem":"In the context of ovarian germ cell tumors, which linked module would provide foundational knowledge on cell differentiation?","options":[{"id":"a","text":"Gastrulation Defects & Stem-cell Potency"},{"id":"b","text":"Testicular Pathology"},{"id":"c","text":"Ovarian Sex Cord-Stromal & Metastatic Tumours"},{"id":"d","text":"Pathology of the Ovary"}],"answerId":"a","explanation":"The module on Gastrulation Defects & Stem-cell Potency covers cell differentiation, relevant to germ cell tumor development.","kind":"integration","linkedModuleIds":["gastrulation-clinical-stem-cells"],"origin":"ai"},{"id":"hrp2-ovarian-germ-cell-tumors~ai-8","moduleId":"hrp2-ovarian-germ-cell-tumors","stem":"Which other module would help understand the similarities between ovarian dysgerminoma and testicular seminoma?","options":[{"id":"a","text":"Testicular Pathology"},{"id":"b","text":"Gastrulation Defects & Stem-cell Potency"},{"id":"c","text":"Ovarian Sex Cord-Stromal & Metastatic Tumours"},{"id":"d","text":"Pathology of the Ovary"}],"answerId":"a","explanation":"The Testicular Pathology module covers seminoma, analogous to ovarian dysgerminoma.","kind":"integration","linkedModuleIds":["hrp2-testicular-pathology"],"origin":"ai"}],"hrp2-benign-breast-disease":[{"id":"hrp2-benign-breast-disease~ai-0","moduleId":"hrp2-benign-breast-disease","stem":"A 25-year-old woman presents with a mobile, firm, well-circumscribed breast lump. What is the most likely diagnosis?","options":[{"id":"a","text":"Fibroadenoma"},{"id":"b","text":"Fibrocystic change"},{"id":"c","text":"Intraductal papilloma"},{"id":"d","text":"Phyllodes tumor"}],"answerId":"a","explanation":"Fibroadenoma is common in young women and presents as a mobile, firm, well-circumscribed lump.","kind":"recall","origin":"ai"},{"id":"hrp2-benign-breast-disease~ai-1","moduleId":"hrp2-benign-breast-disease","stem":"A patient presents with bloody nipple discharge. Which condition is the most common cause?","options":[{"id":"a","text":"Intraductal papilloma"},{"id":"b","text":"Ductal carcinoma in situ"},{"id":"c","text":"Fibrocystic change"},{"id":"d","text":"Mastitis"}],"answerId":"a","explanation":"Intraductal papilloma is the most common cause of bloody nipple discharge.","kind":"recall","origin":"ai"},{"id":"hrp2-benign-breast-disease~ai-2","moduleId":"hrp2-benign-breast-disease","stem":"Which benign breast condition is associated with an increased risk of breast cancer?","options":[{"id":"a","text":"Fibroadenoma"},{"id":"b","text":"Fibrocystic change with atypia"},{"id":"c","text":"Simple cysts"},{"id":"d","text":"Fat necrosis"}],"answerId":"b","explanation":"Fibrocystic change with atypia increases breast cancer risk, unlike simple cysts or fibroadenoma.","kind":"trap","origin":"ai"},{"id":"hrp2-benign-breast-disease~ai-3","moduleId":"hrp2-benign-breast-disease","stem":"A 30-year-old woman reports cyclical breast pain and lumpy breasts. What is the most likely diagnosis?","options":[{"id":"a","text":"Fibroadenoma"},{"id":"b","text":"Fibrocystic change"},{"id":"c","text":"Intraductal papilloma"},{"id":"d","text":"Phyllodes tumor"}],"answerId":"b","explanation":"Fibrocystic change is characterized by cyclical breast pain and lumpy breasts.","kind":"clinical","origin":"ai"},{"id":"hrp2-benign-breast-disease~ai-4","moduleId":"hrp2-benign-breast-disease","stem":"A postmenopausal woman presents with a firm breast mass following trauma. What is the most likely diagnosis?","options":[{"id":"a","text":"Fat necrosis"},{"id":"b","text":"Breast carcinoma"},{"id":"c","text":"Fibroadenoma"},{"id":"d","text":"Mastitis"}],"answerId":"a","explanation":"Fat necrosis can occur after trauma and may mimic breast carcinoma.","kind":"clinical","origin":"ai"},{"id":"hrp2-benign-breast-disease~ai-5","moduleId":"hrp2-benign-breast-disease","stem":"Which of the following conditions is characterized by a leaf-like stromal pattern and can be borderline or malignant?","options":[{"id":"a","text":"Phyllodes tumor"},{"id":"b","text":"Fibroadenoma"},{"id":"c","text":"Intraductal papilloma"},{"id":"d","text":"Fat necrosis"}],"answerId":"a","explanation":"Phyllodes tumor is known for its leaf-like stromal pattern and potential malignancy.","kind":"recall","origin":"ai"},{"id":"hrp2-benign-breast-disease~ai-6","moduleId":"hrp2-benign-breast-disease","stem":"A 45-year-old woman with atypical ductal hyperplasia is concerned about her breast cancer risk. Which module would provide further information on cancer types and receptors?","options":[{"id":"a","text":"hrp2-breast-carcinoma-types"},{"id":"b","text":"hrp2-breast-pathology"},{"id":"c","text":"hrp2-benign-breast-disease"},{"id":"d","text":"hrp2-breast-imaging"}],"answerId":"a","explanation":"The 'Breast Carcinoma: Types & Receptors' module provides information on cancer types and receptors.","kind":"integration","linkedModuleIds":["hrp2-breast-carcinoma-types"],"origin":"ai"},{"id":"hrp2-benign-breast-disease~ai-7","moduleId":"hrp2-benign-breast-disease","stem":"Which module would complement learning about the pathology of benign breast diseases with a focus on malignant conditions?","options":[{"id":"a","text":"hrp2-breast-pathology"},{"id":"b","text":"hrp2-breast-carcinoma-types"},{"id":"c","text":"hrp2-benign-breast-disease"},{"id":"d","text":"hrp2-breast-imaging"}],"answerId":"b","explanation":"The 'Breast Carcinoma: Types & Receptors' module complements benign breast disease with malignant conditions.","kind":"integration","linkedModuleIds":["hrp2-breast-carcinoma-types"],"origin":"ai"}],"hrp2-ovarian-sex-cord-stromal":[{"id":"hrp2-ovarian-sex-cord-stromal~ai-0","moduleId":"hrp2-ovarian-sex-cord-stromal","stem":"A 55-year-old woman presents with postmenopausal bleeding. Histological examination of her ovarian mass reveals Call-Exner bodies. Which tumour is most likely?","options":[{"id":"a","text":"Granulosa cell tumour"},{"id":"b","text":"Sertoli-Leydig cell tumour"},{"id":"c","text":"Fibroma"},{"id":"d","text":"Krukenberg tumour"}],"answerId":"a","explanation":"Granulosa cell tumours secrete oestrogen, causing endometrial hyperplasia and bleeding; Call-Exner bodies are characteristic.","kind":"recall","origin":"ai"},{"id":"hrp2-ovarian-sex-cord-stromal~ai-1","moduleId":"hrp2-ovarian-sex-cord-stromal","stem":"A 30-year-old woman presents with hirsutism and deepening of the voice. Which ovarian tumour is most likely responsible?","options":[{"id":"a","text":"Granulosa cell tumour"},{"id":"b","text":"Sertoli-Leydig cell tumour"},{"id":"c","text":"Fibroma"},{"id":"d","text":"Thecoma"}],"answerId":"b","explanation":"Sertoli-Leydig cell tumours secrete androgens, leading to virilisation symptoms such as hirsutism and voice deepening.","kind":"recall","origin":"ai"},{"id":"hrp2-ovarian-sex-cord-stromal~ai-2","moduleId":"hrp2-ovarian-sex-cord-stromal","stem":"Which ovarian tumour is associated with Meigs syndrome, characterized by ascites and pleural effusion?","options":[{"id":"a","text":"Fibroma"},{"id":"b","text":"Granulosa cell tumour"},{"id":"c","text":"Sertoli-Leydig cell tumour"},{"id":"d","text":"Krukenberg tumour"}],"answerId":"a","explanation":"Meigs syndrome is associated with ovarian fibromas, which are benign stromal tumours.","kind":"recall","origin":"ai"},{"id":"hrp2-ovarian-sex-cord-stromal~ai-3","moduleId":"hrp2-ovarian-sex-cord-stromal","stem":"A 45-year-old woman with a history of gastric carcinoma presents with bilateral ovarian masses. Histology shows signet-ring cells. What is the most likely diagnosis?","options":[{"id":"a","text":"Krukenberg tumour"},{"id":"b","text":"Granulosa cell tumour"},{"id":"c","text":"Sertoli-Leydig cell tumour"},{"id":"d","text":"Fibroma"}],"answerId":"a","explanation":"Krukenberg tumours are metastatic ovarian tumours from gastric cancer, characterized by signet-ring cells.","kind":"recall","origin":"ai"},{"id":"hrp2-ovarian-sex-cord-stromal~ai-4","moduleId":"hrp2-ovarian-sex-cord-stromal","stem":"Which hormone is primarily responsible for the symptoms of precocious puberty in a child with an ovarian tumour?","options":[{"id":"a","text":"Oestrogen"},{"id":"b","text":"Androgen"},{"id":"c","text":"Progesterone"},{"id":"d","text":"Testosterone"}],"answerId":"a","explanation":"Oestrogen secretion by granulosa cell tumours can cause precocious puberty in children.","kind":"mechanism","origin":"ai"},{"id":"hrp2-ovarian-sex-cord-stromal~ai-5","moduleId":"hrp2-ovarian-sex-cord-stromal","stem":"A patient with a history of ovarian fibroma presents with calcification in the tumour. Which linked module provides information on pathologic calcification?","options":[{"id":"a","text":"Intracellular Accumulations & Pathologic Calcification"},{"id":"b","text":"Male HPG Axis, Leydig & Sertoli Regulation"},{"id":"c","text":"Ovarian Germ Cell Tumours"},{"id":"d","text":"Pathology of the Ovary"}],"answerId":"a","explanation":"The module 'Intracellular Accumulations & Pathologic Calcification' covers pathologic calcification.","kind":"integration","linkedModuleIds":["intracellular-accumulations-calcification"],"origin":"ai"},{"id":"hrp2-ovarian-sex-cord-stromal~ai-6","moduleId":"hrp2-ovarian-sex-cord-stromal","stem":"A 25-year-old woman presents with an ovarian mass and elevated serum inhibin levels. Which type of tumour is most likely?","options":[{"id":"a","text":"Granulosa cell tumour"},{"id":"b","text":"Sertoli-Leydig cell tumour"},{"id":"c","text":"Fibroma"},{"id":"d","text":"Krukenberg tumour"}],"answerId":"a","explanation":"Granulosa cell tumours often secrete inhibin, which can be used as a tumour marker.","kind":"recall","origin":"ai"},{"id":"hrp2-ovarian-sex-cord-stromal~ai-7","moduleId":"hrp2-ovarian-sex-cord-stromal","stem":"A woman with virilisation symptoms is found to have an ovarian tumour. Which linked module would provide additional information on androgen regulation?","options":[{"id":"a","text":"Intracellular Accumulations & Pathologic Calcification"},{"id":"b","text":"Male HPG Axis, Leydig & Sertoli Regulation"},{"id":"c","text":"Ovarian Germ Cell Tumours"},{"id":"d","text":"Pathology of the Ovary"}],"answerId":"b","explanation":"The 'Male HPG Axis, Leydig & Sertoli Regulation' module covers androgen regulation.","kind":"integration","linkedModuleIds":["hrp1-male-hpg-axis"],"origin":"ai"}],"hrp2-breast-carcinoma-types":[{"id":"hrp2-breast-carcinoma-types~ai-0","moduleId":"hrp2-breast-carcinoma-types","stem":"Which type of breast carcinoma is characterized by the loss of E-cadherin and often presents as bilateral and multifocal?","options":[{"id":"a","text":"Invasive lobular carcinoma"},{"id":"b","text":"Invasive ductal carcinoma"},{"id":"c","text":"Paget disease of the nipple"},{"id":"d","text":"Inflammatory carcinoma"}],"answerId":"a","explanation":"Invasive lobular carcinoma is characterized by the loss of E-cadherin, leading to its single-file growth pattern and tendency to be bilateral and multifocal.","kind":"recall","origin":"ai"},{"id":"hrp2-breast-carcinoma-types~ai-1","moduleId":"hrp2-breast-carcinoma-types","stem":"A mammogram shows microcalcifications. Which breast condition is most likely associated with this finding?","options":[{"id":"a","text":"Invasive lobular carcinoma"},{"id":"b","text":"Ductal carcinoma in situ"},{"id":"c","text":"Paget disease of the nipple"},{"id":"d","text":"Inflammatory carcinoma"}],"answerId":"b","explanation":"Microcalcifications on mammography are typically associated with ductal carcinoma in situ (DCIS) due to calcification of necrotic debris.","kind":"recall","origin":"ai"},{"id":"hrp2-breast-carcinoma-types~ai-2","moduleId":"hrp2-breast-carcinoma-types","stem":"What is the primary prognostic factor in breast carcinoma?","options":[{"id":"a","text":"Tumor size"},{"id":"b","text":"Histological grade"},{"id":"c","text":"Axillary lymph node status"},{"id":"d","text":"Presence of microcalcifications"}],"answerId":"c","explanation":"Axillary lymph node status is the main prognostic factor in breast carcinoma as it indicates the extent of spread.","kind":"recall","origin":"ai"},{"id":"hrp2-breast-carcinoma-types~ai-3","moduleId":"hrp2-breast-carcinoma-types","stem":"Which breast carcinoma subtype is most likely to respond to trastuzumab therapy?","options":[{"id":"a","text":"Luminal A"},{"id":"b","text":"HER2-enriched"},{"id":"c","text":"Triple-negative"},{"id":"d","text":"Invasive lobular carcinoma"}],"answerId":"b","explanation":"HER2-enriched breast carcinomas overexpress the HER2 protein and are treated with trastuzumab, a monoclonal antibody targeting HER2.","kind":"mechanism","origin":"ai"},{"id":"hrp2-breast-carcinoma-types~ai-4","moduleId":"hrp2-breast-carcinoma-types","stem":"A patient presents with an eczematous crusting nipple. Which underlying condition should be suspected?","options":[{"id":"a","text":"Invasive ductal carcinoma"},{"id":"b","text":"Paget disease of the nipple"},{"id":"c","text":"Inflammatory carcinoma"},{"id":"d","text":"Lobular carcinoma in situ"}],"answerId":"b","explanation":"Paget disease of the nipple presents with eczematous changes due to DCIS spreading into the nipple epidermis, often indicating an underlying carcinoma.","kind":"clinical","origin":"ai"},{"id":"hrp2-breast-carcinoma-types~ai-5","moduleId":"hrp2-breast-carcinoma-types","stem":"In the context of breast pathology, which diagnostic method is essential for determining receptor status?","options":[{"id":"a","text":"Flow cytometry"},{"id":"b","text":"Immunohistochemistry"},{"id":"c","text":"Hematoxylin and eosin staining"},{"id":"d","text":"Electron microscopy"}],"answerId":"b","explanation":"Immunohistochemistry is used to determine receptor status (ER, PR, HER2) in breast carcinoma, guiding treatment decisions.","kind":"integration","linkedModuleIds":["diagnostic-pathology-methods"],"origin":"ai"},{"id":"hrp2-breast-carcinoma-types~ai-6","moduleId":"hrp2-breast-carcinoma-types","stem":"A patient with a history of LCIS is concerned about developing breast cancer. What is the significance of LCIS in this context?","options":[{"id":"a","text":"LCIS is a direct precursor to invasive cancer requiring excision"},{"id":"b","text":"LCIS indicates a generalized increased risk for bilateral invasive cancer"},{"id":"c","text":"LCIS is a benign condition with no risk of progression"},{"id":"d","text":"LCIS requires immediate chemotherapy to prevent progression"}],"answerId":"b","explanation":"LCIS is a marker for increased risk of developing invasive cancer in either breast, not a direct precursor like DCIS.","kind":"trap","origin":"ai"},{"id":"hrp2-breast-carcinoma-types~ai-7","moduleId":"hrp2-breast-carcinoma-types","stem":"Which benign breast condition could mimic the presentation of invasive breast carcinoma on physical examination?","options":[{"id":"a","text":"Fibroadenoma"},{"id":"b","text":"Fat necrosis"},{"id":"c","text":"Fibrocystic changes"},{"id":"d","text":"Phyllodes tumor"}],"answerId":"d","explanation":"Phyllodes tumor, although benign, can present as a large, rapidly growing mass that mimics invasive carcinoma on physical examination.","kind":"integration","linkedModuleIds":["hrp2-benign-breast-disease"],"origin":"ai"}],"hrp2-prostate-penile-pathology":[{"id":"hrp2-prostate-penile-pathology~ai-0","moduleId":"hrp2-prostate-penile-pathology","stem":"Which zone of the prostate is most commonly associated with benign prostatic hyperplasia (BPH)?","options":[{"id":"a","text":"Transitional zone"},{"id":"b","text":"Peripheral zone"},{"id":"c","text":"Central zone"},{"id":"d","text":"Anterior fibromuscular stroma"}],"answerId":"a","explanation":"BPH arises in the transitional (periurethral) zone, leading to bladder outflow obstruction.","kind":"recall","origin":"ai"},{"id":"hrp2-prostate-penile-pathology~ai-1","moduleId":"hrp2-prostate-penile-pathology","stem":"A 70-year-old man presents with back pain and elevated alkaline phosphatase. Which prostate condition is most likely responsible?","options":[{"id":"a","text":"Benign prostatic hyperplasia"},{"id":"b","text":"Prostate adenocarcinoma"},{"id":"c","text":"Acute prostatitis"},{"id":"d","text":"Chronic prostatitis"}],"answerId":"b","explanation":"Prostate adenocarcinoma can metastasize to bone, causing osteoblastic lesions and elevated alkaline phosphatase.","kind":"clinical","origin":"ai"},{"id":"hrp2-prostate-penile-pathology~ai-2","moduleId":"hrp2-prostate-penile-pathology","stem":"Which of the following is a precursor to penile squamous cell carcinoma?","options":[{"id":"a","text":"Bowen disease"},{"id":"b","text":"Peyronie disease"},{"id":"c","text":"Balanitis"},{"id":"d","text":"Lichen sclerosus"}],"answerId":"a","explanation":"Bowen disease is a precursor lesion for penile squamous cell carcinoma.","kind":"recall","origin":"ai"},{"id":"hrp2-prostate-penile-pathology~ai-3","moduleId":"hrp2-prostate-penile-pathology","stem":"A patient with prostate cancer is started on a GnRH agonist. What is the primary purpose of this treatment?","options":[{"id":"a","text":"Reduce testosterone levels"},{"id":"b","text":"Increase PSA levels"},{"id":"c","text":"Enhance immune response"},{"id":"d","text":"Stimulate prostate growth"}],"answerId":"a","explanation":"GnRH agonists are used in androgen-deprivation therapy to reduce testosterone levels in prostate cancer treatment.","kind":"mechanism","origin":"ai"},{"id":"hrp2-prostate-penile-pathology~ai-4","moduleId":"hrp2-prostate-penile-pathology","stem":"Which finding on digital rectal examination is most suggestive of prostate adenocarcinoma?","options":[{"id":"a","text":"Smoothly enlarged prostate"},{"id":"b","text":"Hard irregular nodule"},{"id":"c","text":"Tender prostate"},{"id":"d","text":"Soft prostate"}],"answerId":"b","explanation":"A hard irregular nodule on DRE is suggestive of prostate adenocarcinoma.","kind":"recall","origin":"ai"},{"id":"hrp2-prostate-penile-pathology~ai-5","moduleId":"hrp2-prostate-penile-pathology","stem":"A 60-year-old uncircumcised man presents with a penile lesion. Which factor is most associated with penile squamous cell carcinoma?","options":[{"id":"a","text":"HPV infection"},{"id":"b","text":"Diabetes mellitus"},{"id":"c","text":"Chronic prostatitis"},{"id":"d","text":"BPH"}],"answerId":"a","explanation":"HPV infection is strongly associated with penile squamous cell carcinoma, especially in uncircumcised men.","kind":"trap","origin":"ai"},{"id":"hrp2-prostate-penile-pathology~ai-6","moduleId":"hrp2-prostate-penile-pathology","stem":"Which condition is characterized by fibrous plaques causing penile curvature?","options":[{"id":"a","text":"Peyronie disease"},{"id":"b","text":"Bowen disease"},{"id":"c","text":"Balanitis xerotica obliterans"},{"id":"d","text":"Lichen planus"}],"answerId":"a","explanation":"Peyronie disease is characterized by fibrous plaques in the penis leading to curvature.","kind":"recall","origin":"ai"},{"id":"hrp2-prostate-penile-pathology~ai-7","moduleId":"hrp2-prostate-penile-pathology","stem":"A patient with prostate adenocarcinoma is found to have sclerotic bone lesions. Which adrenal cortex hormone might influence this condition?","options":[{"id":"a","text":"Cortisol"},{"id":"b","text":"Aldosterone"},{"id":"c","text":"Androgens"},{"id":"d","text":"Epinephrine"}],"answerId":"c","explanation":"Androgens from the adrenal cortex can influence prostate cancer progression and metastasis.","kind":"integration","linkedModuleIds":["hen1-adrenal-cortex-histology-zones"],"origin":"ai"},{"id":"hrp2-prostate-penile-pathology~ai-8","moduleId":"hrp2-prostate-penile-pathology","stem":"In the context of prostate pathology, which testicular condition could be relevant for differential diagnosis?","options":[{"id":"a","text":"Testicular torsion"},{"id":"b","text":"Epididymitis"},{"id":"c","text":"Testicular cancer"},{"id":"d","text":"Varicocele"}],"answerId":"c","explanation":"Testicular cancer can present with symptoms that overlap with prostate pathology, such as back pain from metastasis.","kind":"integration","linkedModuleIds":["hrp2-testicular-pathology"],"origin":"ai"}],"hrp2-testicular-pathology":[{"id":"hrp2-testicular-pathology~ai-0","moduleId":"hrp2-testicular-pathology","stem":"A 32-year-old man presents with a painless, solid mass in his right testis. Serum markers show elevated β-hCG but normal AFP. What is the most likely diagnosis?","options":[{"id":"a","text":"Seminoma"},{"id":"b","text":"Yolk sac tumor"},{"id":"c","text":"Choriocarcinoma"},{"id":"d","text":"Embryonal carcinoma"}],"answerId":"a","explanation":"Seminoma is the most common testicular tumor in this age group and can raise β-hCG but not AFP.","kind":"clinical","origin":"ai"},{"id":"hrp2-testicular-pathology~ai-1","moduleId":"hrp2-testicular-pathology","stem":"A 25-year-old male presents with sudden severe scrotal pain. On examination, the testis is high-riding with an absent cremasteric reflex. What is the most appropriate next step?","options":[{"id":"a","text":"Perform Doppler ultrasound"},{"id":"b","text":"Administer antibiotics"},{"id":"c","text":"Immediate surgical exploration"},{"id":"d","text":"Apply ice packs"}],"answerId":"c","explanation":"Testicular torsion is a surgical emergency requiring immediate exploration to salvage the testis.","kind":"trap","origin":"ai"},{"id":"hrp2-testicular-pathology~ai-2","moduleId":"hrp2-testicular-pathology","stem":"Which tumor marker is most likely elevated in a pure yolk sac tumor?","options":[{"id":"a","text":"AFP"},{"id":"b","text":"β-hCG"},{"id":"c","text":"LDH"},{"id":"d","text":"CEA"}],"answerId":"a","explanation":"AFP is characteristically elevated in yolk sac tumors.","kind":"recall","origin":"ai"},{"id":"hrp2-testicular-pathology~ai-3","moduleId":"hrp2-testicular-pathology","stem":"A 40-year-old man presents with a left-sided 'bag of worms' in the scrotum. What is the most likely underlying cause?","options":[{"id":"a","text":"Varicocele"},{"id":"b","text":"Hydrocele"},{"id":"c","text":"Spermatocele"},{"id":"d","text":"Inguinal hernia"}],"answerId":"a","explanation":"A 'bag of worms' appearance is characteristic of a varicocele, often due to dilated veins in the pampiniform plexus.","kind":"recall","origin":"ai"},{"id":"hrp2-testicular-pathology~ai-4","moduleId":"hrp2-testicular-pathology","stem":"A 3-year-old boy with a history of cryptorchidism presents with a testicular mass. Which tumor type is he most at risk for?","options":[{"id":"a","text":"Seminoma"},{"id":"b","text":"Yolk sac tumor"},{"id":"c","text":"Choriocarcinoma"},{"id":"d","text":"Teratoma"}],"answerId":"b","explanation":"Cryptorchidism increases the risk of germ cell tumors, with yolk sac tumors being the most common in children.","kind":"clinical","origin":"ai"},{"id":"hrp2-testicular-pathology~ai-5","moduleId":"hrp2-testicular-pathology","stem":"A patient with a history of cryptorchidism undergoes orchidopexy. How does this procedure affect his risk of testicular cancer?","options":[{"id":"a","text":"Eliminates the risk"},{"id":"b","text":"Reduces the risk"},{"id":"c","text":"Increases the risk"},{"id":"d","text":"No effect on the risk"}],"answerId":"b","explanation":"Orchidopexy reduces but does not eliminate the risk of testicular cancer.","kind":"mechanism","linkedModuleIds":["hrp1-gonadal-descent"],"origin":"ai"},{"id":"hrp2-testicular-pathology~ai-6","moduleId":"hrp2-testicular-pathology","stem":"A 28-year-old male presents with a testicular mass and elevated AFP levels. Which of the following is least likely to be the diagnosis?","options":[{"id":"a","text":"Seminoma"},{"id":"b","text":"Yolk sac tumor"},{"id":"c","text":"Embryonal carcinoma"},{"id":"d","text":"Mixed germ cell tumor"}],"answerId":"a","explanation":"Seminomas do not elevate AFP, making it the least likely diagnosis in this scenario.","kind":"trap","origin":"ai"},{"id":"hrp2-testicular-pathology~ai-7","moduleId":"hrp2-testicular-pathology","stem":"In the context of testicular torsion, which anatomical structure is primarily responsible for the twisting of the spermatic cord?","options":[{"id":"a","text":"Gubernaculum"},{"id":"b","text":"Processus vaginalis"},{"id":"c","text":"Tunica albuginea"},{"id":"d","text":"Pampiniform plexus"}],"answerId":"b","explanation":"The processus vaginalis is involved in the descent of the testes and can contribute to the twisting of the spermatic cord.","kind":"integration","linkedModuleIds":["hrp1-testis-epididymis-vas-anatomy"],"origin":"ai"}],"hrp2-vulvar-vaginal-neoplasia":[{"id":"hrp2-vulvar-vaginal-neoplasia~ai-0","moduleId":"hrp2-vulvar-vaginal-neoplasia","stem":"A 65-year-old woman presents with intense pruritus and thin, white vulvar skin. What is the most likely diagnosis?","options":[{"id":"a","text":"Lichen sclerosus"},{"id":"b","text":"Lichen simplex chronicus"},{"id":"c","text":"Vulvar squamous carcinoma"},{"id":"d","text":"Extramammary Paget disease"}],"answerId":"a","explanation":"Lichen sclerosus presents with thin, white, atrophic vulvar skin and pruritus.","kind":"recall","origin":"ai"},{"id":"hrp2-vulvar-vaginal-neoplasia~ai-1","moduleId":"hrp2-vulvar-vaginal-neoplasia","stem":"Which of the following is a precursor lesion for HPV-related vulvar squamous cell carcinoma?","options":[{"id":"a","text":"Usual-type VIN"},{"id":"b","text":"Lichen sclerosus"},{"id":"c","text":"Differentiated VIN"},{"id":"d","text":"Extramammary Paget disease"}],"answerId":"a","explanation":"Usual-type VIN is associated with HPV infection and is a precursor for HPV-related vulvar squamous cell carcinoma.","kind":"mechanism","origin":"ai"},{"id":"hrp2-vulvar-vaginal-neoplasia~ai-2","moduleId":"hrp2-vulvar-vaginal-neoplasia","stem":"A 70-year-old woman with a history of lichen sclerosus presents with a new vulvar lesion. Which factor increases her risk for vulvar squamous cell carcinoma?","options":[{"id":"a","text":"HPV infection"},{"id":"b","text":"Chronic dermatosis"},{"id":"c","text":"In-utero DES exposure"},{"id":"d","text":"Smoking"}],"answerId":"b","explanation":"Chronic dermatosis like lichen sclerosus can lead to differentiated VIN and increase the risk of vulvar squamous cell carcinoma.","kind":"clinical","origin":"ai"},{"id":"hrp2-vulvar-vaginal-neoplasia~ai-3","moduleId":"hrp2-vulvar-vaginal-neoplasia","stem":"A 30-year-old woman presents with a red, crusted vulvar plaque. Biopsy shows PAS-positive cells. What is the most likely diagnosis?","options":[{"id":"a","text":"Vulvar squamous carcinoma"},{"id":"b","text":"Lichen sclerosus"},{"id":"c","text":"Extramammary Paget disease"},{"id":"d","text":"Vaginal adenosis"}],"answerId":"c","explanation":"Extramammary Paget disease presents with red, crusted plaques and PAS-positive cells on biopsy.","kind":"recall","origin":"ai"},{"id":"hrp2-vulvar-vaginal-neoplasia~ai-4","moduleId":"hrp2-vulvar-vaginal-neoplasia","stem":"Which condition is most commonly associated with vaginal clear cell adenocarcinoma?","options":[{"id":"a","text":"In-utero DES exposure"},{"id":"b","text":"HPV infection"},{"id":"c","text":"Chronic lichen sclerosus"},{"id":"d","text":"Smoking"}],"answerId":"a","explanation":"In-utero DES exposure is linked to the development of vaginal clear cell adenocarcinoma.","kind":"recall","origin":"ai"},{"id":"hrp2-vulvar-vaginal-neoplasia~ai-5","moduleId":"hrp2-vulvar-vaginal-neoplasia","stem":"A 55-year-old woman with a history of lichen sclerosus is concerned about cancer risk. What should she be informed about?","options":[{"id":"a","text":"Lichen sclerosus has no malignant potential"},{"id":"b","text":"Lichen sclerosus can lead to vulvar squamous carcinoma"},{"id":"c","text":"Lichen sclerosus is a form of VIN"},{"id":"d","text":"Lichen sclerosus is caused by HPV"}],"answerId":"b","explanation":"Lichen sclerosus is non-neoplastic but carries a small risk of developing vulvar squamous carcinoma.","kind":"trap","origin":"ai"},{"id":"hrp2-vulvar-vaginal-neoplasia~ai-6","moduleId":"hrp2-vulvar-vaginal-neoplasia","stem":"A 40-year-old woman with a history of HPV presents with vulvar lesions. Which molecular pathway is most likely involved?","options":[{"id":"a","text":"p53 mutation"},{"id":"b","text":"HPV-driven carcinogenesis"},{"id":"c","text":"DES-related changes"},{"id":"d","text":"Chronic inflammation"}],"answerId":"b","explanation":"HPV-driven carcinogenesis is the pathway involved in younger women with HPV-related vulvar lesions.","kind":"mechanism","origin":"ai"},{"id":"hrp2-vulvar-vaginal-neoplasia~ai-7","moduleId":"hrp2-vulvar-vaginal-neoplasia","stem":"A 25-year-old woman with a history of HPV infection is undergoing screening for cervical cancer. Which precursor lesion parallels VaIN in its pathogenesis?","options":[{"id":"a","text":"CIN"},{"id":"b","text":"Lichen sclerosus"},{"id":"c","text":"Differentiated VIN"},{"id":"d","text":"Extramammary Paget disease"}],"answerId":"a","explanation":"CIN (Cervical Intraepithelial Neoplasia) parallels VaIN (Vaginal Intraepithelial Neoplasia) as both are HPV-driven precursor lesions.","kind":"integration","linkedModuleIds":["hrp2-cervical-cancer-screening"],"origin":"ai"},{"id":"hrp2-vulvar-vaginal-neoplasia~ai-8","moduleId":"hrp2-vulvar-vaginal-neoplasia","stem":"A 60-year-old woman with a history of lichen sclerosus is evaluated for vulvar cancer risk. Which molecular pathway is most relevant?","options":[{"id":"a","text":"HPV-driven"},{"id":"b","text":"p53 mutation"},{"id":"c","text":"DES-related"},{"id":"d","text":"BRCA mutation"}],"answerId":"b","explanation":"The p53 mutation pathway is relevant in non-HPV related vulvar squamous cell carcinoma, often arising from lichen sclerosus.","kind":"integration","linkedModuleIds":["carcinogenesis-molecular"],"origin":"ai"}],"hrp2-leiomyoma-adenomyosis":[{"id":"hrp2-leiomyoma-adenomyosis~ai-0","moduleId":"hrp2-leiomyoma-adenomyosis","stem":"A 35-year-old woman presents with heavy menstrual bleeding and pelvic pain. On examination, her uterus is diffusely enlarged and tender. What is the most likely diagnosis?","options":[{"id":"a","text":"Adenomyosis"},{"id":"b","text":"Leiomyoma"},{"id":"c","text":"Endometrial polyp"},{"id":"d","text":"Endometritis"}],"answerId":"a","explanation":"Adenomyosis is characterized by a diffusely enlarged, tender uterus with menorrhagia and dysmenorrhea.","kind":"clinical","origin":"ai"},{"id":"hrp2-leiomyoma-adenomyosis~ai-1","moduleId":"hrp2-leiomyoma-adenomyosis","stem":"Which of the following is a characteristic feature of a leiomyoma?","options":[{"id":"a","text":"Necrosis and high mitotic count"},{"id":"b","text":"Whorled, well-circumscribed mass"},{"id":"c","text":"Diffuse myometrial infiltration"},{"id":"d","text":"Presence of plasma cells"}],"answerId":"b","explanation":"Leiomyomas are benign smooth muscle tumors that are well-circumscribed and have a whorled appearance.","kind":"recall","origin":"ai"},{"id":"hrp2-leiomyoma-adenomyosis~ai-2","moduleId":"hrp2-leiomyoma-adenomyosis","stem":"A postmenopausal woman presents with a rapidly enlarging uterine mass. Which feature would most suggest a leiomyosarcoma?","options":[{"id":"a","text":"Well-circumscribed mass"},{"id":"b","text":"High mitotic count"},{"id":"c","text":"Diffuse enlargement of the uterus"},{"id":"d","text":"Presence of endometrial glands in myometrium"}],"answerId":"b","explanation":"A high mitotic count is indicative of leiomyosarcoma, a malignant tumor.","kind":"trap","origin":"ai"},{"id":"hrp2-leiomyoma-adenomyosis~ai-3","moduleId":"hrp2-leiomyoma-adenomyosis","stem":"Which condition is most likely to cause intermenstrual bleeding and is associated with tamoxifen use?","options":[{"id":"a","text":"Adenomyosis"},{"id":"b","text":"Leiomyoma"},{"id":"c","text":"Endometrial polyp"},{"id":"d","text":"Endometritis"}],"answerId":"c","explanation":"Endometrial polyps are localized overgrowths that can cause intermenstrual bleeding and are associated with tamoxifen.","kind":"recall","origin":"ai"},{"id":"hrp2-leiomyoma-adenomyosis~ai-4","moduleId":"hrp2-leiomyoma-adenomyosis","stem":"A 40-year-old woman with a history of fibroids presents with acute pelvic pain during pregnancy. What is the most likely cause?","options":[{"id":"a","text":"Leiomyosarcoma"},{"id":"b","text":"Red degeneration"},{"id":"c","text":"Adenomyosis"},{"id":"d","text":"Endometrial polyp"}],"answerId":"b","explanation":"Red (carneous) degeneration occurs when a fibroid outgrows its blood supply, causing acute pain.","kind":"mechanism","origin":"ai"},{"id":"hrp2-leiomyoma-adenomyosis~ai-5","moduleId":"hrp2-leiomyoma-adenomyosis","stem":"A patient with a history of endometriosis presents with a diffusely enlarged, tender uterus. Which condition should be considered in the differential diagnosis?","options":[{"id":"a","text":"Leiomyoma"},{"id":"b","text":"Endometrial polyp"},{"id":"c","text":"Adenomyosis"},{"id":"d","text":"Endometritis"}],"answerId":"c","explanation":"Adenomyosis can present similarly to endometriosis with a diffusely enlarged, tender uterus.","kind":"integration","linkedModuleIds":["hrp2-endometriosis"],"origin":"ai"},{"id":"hrp2-leiomyoma-adenomyosis~ai-6","moduleId":"hrp2-leiomyoma-adenomyosis","stem":"In the context of uterine corpus pathology, which condition is characterized by the presence of endometrial glands and stroma within the myometrium?","options":[{"id":"a","text":"Leiomyoma"},{"id":"b","text":"Adenomyosis"},{"id":"c","text":"Endometrial polyp"},{"id":"d","text":"Leiomyosarcoma"}],"answerId":"b","explanation":"Adenomyosis involves the presence of endometrial tissue within the myometrium, causing uterine enlargement.","kind":"integration","linkedModuleIds":["hrp2-uterine-corpus-pathology"],"origin":"ai"}],"hrp2-cervical-cancer-screening":[{"id":"hrp2-cervical-cancer-screening~ai-0","moduleId":"hrp2-cervical-cancer-screening","stem":"What is the primary goal of cervical cancer screening programs?","options":[{"id":"a","text":"Detecting pre-invasive cervical intraepithelial neoplasia (CIN)"},{"id":"b","text":"Finding early invasive cervical cancers"},{"id":"c","text":"Identifying HPV infection"},{"id":"d","text":"Screening for other gynecological cancers"}],"answerId":"a","explanation":"The main benefit of cervical screening is detecting pre-invasive CIN so it can be treated before cancer develops.","kind":"trap","origin":"ai"},{"id":"hrp2-cervical-cancer-screening~ai-1","moduleId":"hrp2-cervical-cancer-screening","stem":"Which HPV types are most commonly associated with cervical cancer?","options":[{"id":"a","text":"HPV 6 and 11"},{"id":"b","text":"HPV 16 and 18"},{"id":"c","text":"HPV 31 and 33"},{"id":"d","text":"HPV 45 and 52"}],"answerId":"b","explanation":"HPV types 16 and 18 are high-risk types most commonly associated with cervical cancer.","kind":"recall","origin":"ai"},{"id":"hrp2-cervical-cancer-screening~ai-2","moduleId":"hrp2-cervical-cancer-screening","stem":"A 32-year-old woman presents with post-coital bleeding and a friable cervix on examination. What is the most likely diagnosis?","options":[{"id":"a","text":"Cervical polyp"},{"id":"b","text":"Cervical intraepithelial neoplasia (CIN)"},{"id":"c","text":"Invasive cervical carcinoma"},{"id":"d","text":"Endometrial hyperplasia"}],"answerId":"c","explanation":"Post-coital bleeding and a friable cervix are classic signs of invasive cervical carcinoma.","kind":"clinical","origin":"ai"},{"id":"hrp2-cervical-cancer-screening~ai-3","moduleId":"hrp2-cervical-cancer-screening","stem":"What is the most effective timing for HPV vaccination to prevent cervical cancer?","options":[{"id":"a","text":"After the first sexual encounter"},{"id":"b","text":"Before sexual debut"},{"id":"c","text":"During pregnancy"},{"id":"d","text":"After a positive HPV test"}],"answerId":"b","explanation":"Vaccination before sexual debut is most effective as it prevents primary infection.","kind":"mechanism","origin":"ai"},{"id":"hrp2-cervical-cancer-screening~ai-4","moduleId":"hrp2-cervical-cancer-screening","stem":"Which treatment is appropriate for a patient with cervical intraepithelial neoplasia (CIN) detected during screening?","options":[{"id":"a","text":"Hysterectomy"},{"id":"b","text":"Chemoradiation"},{"id":"c","text":"Excision or ablation (LEEP/cone biopsy)"},{"id":"d","text":"Observation only"}],"answerId":"c","explanation":"Pre-invasive disease like CIN is treated by excision or ablation to prevent progression to invasive cancer.","kind":"recall","origin":"ai"},{"id":"hrp2-cervical-cancer-screening~ai-5","moduleId":"hrp2-cervical-cancer-screening","stem":"How does HPV vaccination contribute to the prevention of cervical cancer?","options":[{"id":"a","text":"It treats existing HPV infections."},{"id":"b","text":"It prevents initial HPV infection."},{"id":"c","text":"It eliminates cervical dysplasia."},{"id":"d","text":"It reduces the need for regular screening."}],"answerId":"b","explanation":"HPV vaccination prevents primary infection, thereby reducing the risk of cervical cancer.","kind":"mechanism","origin":"ai"},{"id":"hrp2-cervical-cancer-screening~ai-6","moduleId":"hrp2-cervical-cancer-screening","stem":"Which of the following is a risk factor for cervical cancer that can be modified through vaccination?","options":[{"id":"a","text":"Smoking"},{"id":"b","text":"HPV infection"},{"id":"c","text":"Early sexual activity"},{"id":"d","text":"Immunosuppression"}],"answerId":"b","explanation":"HPV infection is a modifiable risk factor through vaccination.","kind":"integration","linkedModuleIds":["vaccines-immunization"],"origin":"ai"},{"id":"hrp2-cervical-cancer-screening~ai-7","moduleId":"hrp2-cervical-cancer-screening","stem":"In addition to cervical cancer, what other condition is prevented by the HPV vaccine?","options":[{"id":"a","text":"Ovarian cancer"},{"id":"b","text":"Endometrial cancer"},{"id":"c","text":"Genital warts"},{"id":"d","text":"Breast cancer"}],"answerId":"c","explanation":"The HPV vaccine also prevents genital warts caused by HPV types 6 and 11.","kind":"integration","linkedModuleIds":["immunostimulants-biologics"],"origin":"ai"}],"hrp2-choriocarcinoma":[{"id":"hrp2-choriocarcinoma~ai-0","moduleId":"hrp2-choriocarcinoma","stem":"A 28-year-old woman presents with persistent vaginal bleeding 8 weeks after a miscarriage. Her β-hCG levels are found to be rising. What is the most likely diagnosis?","options":[{"id":"a","text":"Ectopic pregnancy"},{"id":"b","text":"Incomplete miscarriage"},{"id":"c","text":"Gestational choriocarcinoma"},{"id":"d","text":"Endometrial hyperplasia"}],"answerId":"c","explanation":"Rising β-hCG after a pregnancy event suggests gestational choriocarcinoma.","kind":"clinical","origin":"ai"},{"id":"hrp2-choriocarcinoma~ai-1","moduleId":"hrp2-choriocarcinoma","stem":"Which of the following is a characteristic finding in gestational choriocarcinoma?","options":[{"id":"a","text":"Presence of chorionic villi"},{"id":"b","text":"Low β-hCG levels"},{"id":"c","text":"Cannonball pulmonary metastases"},{"id":"d","text":"Resistance to chemotherapy"}],"answerId":"c","explanation":"Gestational choriocarcinoma is associated with very high β-hCG and cannonball lung metastases.","kind":"recall","origin":"ai"},{"id":"hrp2-choriocarcinoma~ai-2","moduleId":"hrp2-choriocarcinoma","stem":"A patient with a history of a complete molar pregnancy presents with a plateauing β-hCG level. What is the most appropriate next step in management?","options":[{"id":"a","text":"Observation"},{"id":"b","text":"Hysterectomy"},{"id":"c","text":"Chemotherapy"},{"id":"d","text":"Radiation therapy"}],"answerId":"c","explanation":"Plateauing β-hCG after a molar pregnancy suggests persistent GTD, which is treated with chemotherapy.","kind":"clinical","origin":"ai"},{"id":"hrp2-choriocarcinoma~ai-3","moduleId":"hrp2-choriocarcinoma","stem":"What is the primary reason gestational choriocarcinoma has an excellent prognosis even when metastatic?","options":[{"id":"a","text":"Early detection"},{"id":"b","text":"Highly chemosensitive"},{"id":"c","text":"Slow progression"},{"id":"d","text":"Limited metastatic sites"}],"answerId":"b","explanation":"Gestational choriocarcinoma is highly chemosensitive, leading to excellent cure rates.","kind":"trap","origin":"ai"},{"id":"hrp2-choriocarcinoma~ai-4","moduleId":"hrp2-choriocarcinoma","stem":"A 30-year-old woman presents with a history of a recent normal pregnancy followed by abnormal uterine bleeding. Her β-hCG levels are significantly elevated. Which condition should be suspected?","options":[{"id":"a","text":"Placental site trophoblastic tumor"},{"id":"b","text":"Invasive mole"},{"id":"c","text":"Gestational choriocarcinoma"},{"id":"d","text":"Endometrial carcinoma"}],"answerId":"c","explanation":"Elevated β-hCG after a normal pregnancy with abnormal bleeding suggests gestational choriocarcinoma.","kind":"clinical","origin":"ai"},{"id":"hrp2-choriocarcinoma~ai-5","moduleId":"hrp2-choriocarcinoma","stem":"A patient is diagnosed with a placental site trophoblastic tumor (PSTT). What is a distinguishing feature of this condition compared to gestational choriocarcinoma?","options":[{"id":"a","text":"Higher β-hCG levels"},{"id":"b","text":"More chemoresistant"},{"id":"c","text":"Presence of chorionic villi"},{"id":"d","text":"Faster metastasis"}],"answerId":"b","explanation":"PSTT is relatively chemoresistant and secretes less hCG compared to gestational choriocarcinoma.","kind":"mechanism","origin":"ai"},{"id":"hrp2-choriocarcinoma~ai-6","moduleId":"hrp2-choriocarcinoma","stem":"A 32-year-old woman with a history of a complete molar pregnancy presents with vaginal bleeding and lung metastases. Which laboratory finding is most likely?","options":[{"id":"a","text":"Low β-hCG"},{"id":"b","text":"Normal β-hCG"},{"id":"c","text":"Very high β-hCG"},{"id":"d","text":"Undetectable β-hCG"}],"answerId":"c","explanation":"Very high β-hCG is characteristic of gestational choriocarcinoma with metastasis.","kind":"recall","origin":"ai"},{"id":"hrp2-choriocarcinoma~ai-7","moduleId":"hrp2-choriocarcinoma","stem":"How does gestational choriocarcinoma differ from non-gestational germ cell choriocarcinoma in terms of treatment response?","options":[{"id":"a","text":"Both are equally chemosensitive"},{"id":"b","text":"Gestational is more chemosensitive"},{"id":"c","text":"Non-gestational is more chemosensitive"},{"id":"d","text":"Neither responds to chemotherapy"}],"answerId":"b","explanation":"Gestational choriocarcinoma is highly chemosensitive, unlike non-gestational germ cell choriocarcinoma.","kind":"trap","origin":"ai"},{"id":"hrp2-choriocarcinoma~ai-8","moduleId":"hrp2-choriocarcinoma","stem":"In the context of gestational trophoblastic disease, which condition is most likely to present with low β-hCG levels and chemoresistance?","options":[{"id":"a","text":"Gestational choriocarcinoma"},{"id":"b","text":"Invasive mole"},{"id":"c","text":"Placental site trophoblastic tumor"},{"id":"d","text":"Non-gestational germ cell choriocarcinoma"}],"answerId":"c","explanation":"PSTT is characterized by low β-hCG levels and relative chemoresistance.","kind":"integration","linkedModuleIds":["hrp2-gestational-trophoblastic-disease"],"origin":"ai"}],"hrp2-endometriosis":[{"id":"hrp2-endometriosis~ai-0","moduleId":"hrp2-endometriosis","stem":"Which of the following is the gold standard for diagnosing endometriosis?","options":[{"id":"a","text":"Laparoscopy"},{"id":"b","text":"Pelvic ultrasound"},{"id":"c","text":"MRI"},{"id":"d","text":"CT scan"}],"answerId":"a","explanation":"Laparoscopy is the gold standard for diagnosing endometriosis as it allows direct visualization of lesions.","kind":"recall","origin":"ai"},{"id":"hrp2-endometriosis~ai-1","moduleId":"hrp2-endometriosis","stem":"A 30-year-old woman presents with severe dysmenorrhea and deep dyspareunia. On examination, nodularity of the uterosacral ligaments is noted. What is the most likely underlying mechanism for these findings?","options":[{"id":"a","text":"Cyclical bleeding of ectopic endometrial tissue"},{"id":"b","text":"Hormonal imbalance"},{"id":"c","text":"Infection"},{"id":"d","text":"Neoplastic growth"}],"answerId":"a","explanation":"Cyclical bleeding of ectopic endometrial tissue causes inflammation and scarring, leading to nodularity and pain.","kind":"mechanism","origin":"ai"},{"id":"hrp2-endometriosis~ai-2","moduleId":"hrp2-endometriosis","stem":"Which of the following statements about the relationship between the extent of endometriosis and symptom severity is true?","options":[{"id":"a","text":"The extent of endometriosis reliably predicts pain severity"},{"id":"b","text":"Minimal disease always causes minimal symptoms"},{"id":"c","text":"Severe disease always causes severe symptoms"},{"id":"d","text":"Symptom severity does not correlate well with disease extent"}],"answerId":"d","explanation":"Symptom severity does not correlate well with the extent of disease; minimal disease can cause severe symptoms and vice versa.","kind":"trap","origin":"ai"},{"id":"hrp2-endometriosis~ai-3","moduleId":"hrp2-endometriosis","stem":"A patient with endometriosis is found to have an ovarian mass described as a 'chocolate cyst.' What is the composition of this cyst?","options":[{"id":"a","text":"Accumulated old blood"},{"id":"b","text":"Serous fluid"},{"id":"c","text":"Mucinous fluid"},{"id":"d","text":"Fibrous tissue"}],"answerId":"a","explanation":"An ovarian endometrioma, or 'chocolate cyst,' is composed of accumulated old blood.","kind":"recall","origin":"ai"},{"id":"hrp2-endometriosis~ai-4","moduleId":"hrp2-endometriosis","stem":"A 28-year-old woman with a history of endometriosis presents with subfertility. What is the most likely cause of her subfertility?","options":[{"id":"a","text":"Adhesions and inflammatory environment"},{"id":"b","text":"Hormonal imbalance"},{"id":"c","text":"Genetic factors"},{"id":"d","text":"Tubal obstruction by fibroids"}],"answerId":"a","explanation":"Subfertility in endometriosis is often due to adhesions and an inflammatory environment affecting the reproductive organs.","kind":"clinical","origin":"ai"},{"id":"hrp2-endometriosis~ai-5","moduleId":"hrp2-endometriosis","stem":"Which of the following treatments is aimed at suppressing the cyclical stimulation of endometriotic tissue?","options":[{"id":"a","text":"NSAIDs"},{"id":"b","text":"Antibiotics"},{"id":"c","text":"Antifungals"},{"id":"d","text":"Antivirals"}],"answerId":"a","explanation":"NSAIDs help manage pain by reducing inflammation, and hormonal treatments like combined pills or GnRH agonists suppress cyclical stimulation.","kind":"recall","origin":"ai"},{"id":"hrp2-endometriosis~ai-6","moduleId":"hrp2-endometriosis","stem":"How does the presence of endometrial tissue in the myometrium, as seen in adenomyosis, differ from endometriosis?","options":[{"id":"a","text":"Endometriosis involves ectopic tissue outside the uterus"},{"id":"b","text":"Adenomyosis involves ectopic tissue outside the uterus"},{"id":"c","text":"Both conditions involve tissue outside the uterus"},{"id":"d","text":"Neither condition involves tissue outside the uterus"}],"answerId":"a","explanation":"Endometriosis involves endometrial tissue outside the uterus, while adenomyosis involves tissue within the myometrium.","kind":"integration","linkedModuleIds":["hrp2-leiomyoma-adenomyosis"],"origin":"ai"},{"id":"hrp2-endometriosis~ai-7","moduleId":"hrp2-endometriosis","stem":"In the context of the menstrual cycle, how does the histological appearance of endometriotic lesions compare to the normal endometrial lining?","options":[{"id":"a","text":"Similar cyclical changes"},{"id":"b","text":"No cyclical changes"},{"id":"c","text":"Constant proliferative phase"},{"id":"d","text":"Constant secretory phase"}],"answerId":"a","explanation":"Endometriotic lesions undergo similar cyclical changes as the normal endometrial lining, leading to symptoms.","kind":"integration","linkedModuleIds":["hrp1-oviduct-uterus-cycle-histology"],"origin":"ai"}],"hrp2-syphilis-stages":[{"id":"hrp2-syphilis-stages~ai-0","moduleId":"hrp2-syphilis-stages","stem":"A 30-year-old man presents with a painless ulcer on his penis. Dark-field microscopy reveals spirochaetes. What is the most likely diagnosis?","options":[{"id":"a","text":"Primary syphilis"},{"id":"b","text":"Secondary syphilis"},{"id":"c","text":"Tertiary syphilis"},{"id":"d","text":"Chancroid"}],"answerId":"a","explanation":"A painless, indurated chancre is characteristic of primary syphilis.","kind":"recall","origin":"ai"},{"id":"hrp2-syphilis-stages~ai-1","moduleId":"hrp2-syphilis-stages","stem":"A patient with a history of syphilis treatment shows a falling RPR titre. What does this indicate?","options":[{"id":"a","text":"Treatment failure"},{"id":"b","text":"Successful treatment"},{"id":"c","text":"Reinfection"},{"id":"d","text":"False positive result"}],"answerId":"b","explanation":"A falling RPR titre indicates a successful response to treatment.","kind":"mechanism","origin":"ai"},{"id":"hrp2-syphilis-stages~ai-2","moduleId":"hrp2-syphilis-stages","stem":"Which of the following findings is most indicative of secondary syphilis?","options":[{"id":"a","text":"Painless genital ulcer"},{"id":"b","text":"Maculopapular rash on palms and soles"},{"id":"c","text":"Gummas"},{"id":"d","text":"Argyll Robertson pupil"}],"answerId":"b","explanation":"A maculopapular rash on palms and soles is characteristic of secondary syphilis.","kind":"clinical","origin":"ai"},{"id":"hrp2-syphilis-stages~ai-3","moduleId":"hrp2-syphilis-stages","stem":"A pregnant woman tests positive for RPR. What is the next best step in management?","options":[{"id":"a","text":"Start penicillin treatment immediately"},{"id":"b","text":"Confirm with a treponemal test"},{"id":"c","text":"Repeat RPR in 1 month"},{"id":"d","text":"Perform a lumbar puncture"}],"answerId":"b","explanation":"A positive RPR should be confirmed with a treponemal test due to the possibility of false positives.","kind":"trap","origin":"ai"},{"id":"hrp2-syphilis-stages~ai-4","moduleId":"hrp2-syphilis-stages","stem":"A patient presents with signs of neurosyphilis. Which of the following findings is most likely present?","options":[{"id":"a","text":"Painless chancre"},{"id":"b","text":"Condylomata lata"},{"id":"c","text":"Argyll Robertson pupil"},{"id":"d","text":"Maculopapular rash"}],"answerId":"c","explanation":"Argyll Robertson pupil is a classic sign of neurosyphilis.","kind":"recall","origin":"ai"},{"id":"hrp2-syphilis-stages~ai-5","moduleId":"hrp2-syphilis-stages","stem":"Which condition is characterized by a positive VDRL test but requires confirmation with a treponemal test?","options":[{"id":"a","text":"Primary syphilis"},{"id":"b","text":"Secondary syphilis"},{"id":"c","text":"Latent syphilis"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"Non-treponemal tests like VDRL require confirmation with a treponemal test for all stages of syphilis.","kind":"trap","origin":"ai"},{"id":"hrp2-syphilis-stages~ai-6","moduleId":"hrp2-syphilis-stages","stem":"A 25-year-old woman presents with pelvic pain and a maculopapular rash on her palms and soles. Which linked condition should be considered?","options":[{"id":"a","text":"Chlamydia infection"},{"id":"b","text":"Gonorrhea"},{"id":"c","text":"Secondary syphilis"},{"id":"d","text":"Trichomoniasis"}],"answerId":"c","explanation":"The rash on palms and soles suggests secondary syphilis, which can be linked to pelvic inflammatory disease.","kind":"integration","linkedModuleIds":["hrp2-bacterial-sti-pid"],"origin":"ai"},{"id":"hrp2-syphilis-stages~ai-7","moduleId":"hrp2-syphilis-stages","stem":"A patient with a history of untreated syphilis presents with aortic regurgitation. What stage of syphilis is most likely responsible?","options":[{"id":"a","text":"Primary syphilis"},{"id":"b","text":"Secondary syphilis"},{"id":"c","text":"Tertiary syphilis"},{"id":"d","text":"Latent syphilis"}],"answerId":"c","explanation":"Cardiovascular complications such as aortic regurgitation are associated with tertiary syphilis.","kind":"integration","linkedModuleIds":["spirochetes-treponema-borrelia-leptospira"],"origin":"ai"}],"hrp2-pid-tubo-ovarian":[{"id":"hrp2-pid-tubo-ovarian~ai-0","moduleId":"hrp2-pid-tubo-ovarian","stem":"A 25-year-old woman presents with lower abdominal pain, fever, and cervical motion tenderness. What is the most appropriate initial management?","options":[{"id":"a","text":"Empirical broad-spectrum antibiotics"},{"id":"b","text":"Wait for culture results"},{"id":"c","text":"Immediate laparoscopy"},{"id":"d","text":"NSAIDs for pain relief"}],"answerId":"a","explanation":"PID should be treated empirically with broad-spectrum antibiotics to prevent complications.","kind":"clinical","origin":"ai"},{"id":"hrp2-pid-tubo-ovarian~ai-1","moduleId":"hrp2-pid-tubo-ovarian","stem":"Which of the following is a potential complication of untreated pelvic inflammatory disease?","options":[{"id":"a","text":"Tubo-ovarian abscess"},{"id":"b","text":"Uterine fibroids"},{"id":"c","text":"Endometrial hyperplasia"},{"id":"d","text":"Ovarian cyst rupture"}],"answerId":"a","explanation":"Untreated PID can lead to a tubo-ovarian abscess among other complications.","kind":"recall","origin":"ai"},{"id":"hrp2-pid-tubo-ovarian~ai-2","moduleId":"hrp2-pid-tubo-ovarian","stem":"A patient with PID is found to have RUQ pain and 'violin-string' adhesions during laparoscopy. What is the diagnosis?","options":[{"id":"a","text":"Fitz-Hugh–Curtis syndrome"},{"id":"b","text":"Cholecystitis"},{"id":"c","text":"Hepatic abscess"},{"id":"d","text":"Biliary colic"}],"answerId":"a","explanation":"Fitz-Hugh–Curtis syndrome is characterized by perihepatitis and 'violin-string' adhesions.","kind":"mechanism","origin":"ai"},{"id":"hrp2-pid-tubo-ovarian~ai-3","moduleId":"hrp2-pid-tubo-ovarian","stem":"In the context of PID, what is the significance of cervical motion tenderness?","options":[{"id":"a","text":"Indicates peritoneal irritation"},{"id":"b","text":"Suggests ovarian torsion"},{"id":"c","text":"Confirms endometriosis"},{"id":"d","text":"Rules out ectopic pregnancy"}],"answerId":"a","explanation":"Cervical motion tenderness is a sign of peritoneal irritation due to PID.","kind":"mechanism","origin":"ai"},{"id":"hrp2-pid-tubo-ovarian~ai-4","moduleId":"hrp2-pid-tubo-ovarian","stem":"A 30-year-old woman with a history of PID presents with infertility. What is the most likely cause?","options":[{"id":"a","text":"Tubal scarring"},{"id":"b","text":"Uterine fibroids"},{"id":"c","text":"Polycystic ovary syndrome"},{"id":"d","text":"Endometriosis"}],"answerId":"a","explanation":"PID can cause tubal scarring, leading to infertility.","kind":"clinical","origin":"ai"},{"id":"hrp2-pid-tubo-ovarian~ai-5","moduleId":"hrp2-pid-tubo-ovarian","stem":"A patient with a history of PID presents with right upper quadrant pain. Which linked module might provide additional insights into her condition?","options":[{"id":"a","text":"Entamoeba histolytica & Amoebiasis"},{"id":"b","text":"Bacterial STIs & Pelvic Inflammatory Disease"},{"id":"c","text":"Syphilis: Stages & Serology"},{"id":"d","text":"None of the above"}],"answerId":"b","explanation":"The 'Bacterial STIs & Pelvic Inflammatory Disease' module covers related infections that can lead to complications like Fitz-Hugh–Curtis syndrome.","kind":"integration","linkedModuleIds":["hrp2-bacterial-sti-pid"],"origin":"ai"},{"id":"hrp2-pid-tubo-ovarian~ai-6","moduleId":"hrp2-pid-tubo-ovarian","stem":"A woman with PID is also being evaluated for amoebic liver abscess. Which linked module would be relevant for understanding this condition?","options":[{"id":"a","text":"Entamoeba histolytica & Amoebiasis"},{"id":"b","text":"Bacterial STIs & Pelvic Inflammatory Disease"},{"id":"c","text":"Syphilis: Stages & Serology"},{"id":"d","text":"None of the above"}],"answerId":"a","explanation":"The 'Entamoeba histolytica & Amoebiasis' module would provide information on amoebic liver abscess.","kind":"integration","linkedModuleIds":["entamoeba-histolytica-amoebiasis"],"origin":"ai"}],"hrp2-vulvar-dermatoses":[{"id":"hrp2-vulvar-dermatoses~ai-0","moduleId":"hrp2-vulvar-dermatoses","stem":"A 65-year-old woman presents with vaginal dryness, dyspareunia, and a raised vaginal pH. What is the most likely diagnosis?","options":[{"id":"a","text":"Atrophic vaginitis"},{"id":"b","text":"Bacterial vaginosis"},{"id":"c","text":"Candidiasis"},{"id":"d","text":"Trichomoniasis"}],"answerId":"a","explanation":"Postmenopausal atrophic vaginitis is characterized by vaginal dryness, dyspareunia, and a raised pH due to oestrogen deficiency.","kind":"recall","origin":"ai"},{"id":"hrp2-vulvar-dermatoses~ai-1","moduleId":"hrp2-vulvar-dermatoses","stem":"A patient presents with a white, thin, atrophic vulvar skin that is intensely pruritic. What is the most likely condition?","options":[{"id":"a","text":"Lichen sclerosus"},{"id":"b","text":"Lichen simplex chronicus"},{"id":"c","text":"Psoriasis"},{"id":"d","text":"Contact dermatitis"}],"answerId":"a","explanation":"Lichen sclerosus presents with white, thin, atrophic skin and intense pruritus.","kind":"recall","origin":"ai"},{"id":"hrp2-vulvar-dermatoses~ai-2","moduleId":"hrp2-vulvar-dermatoses","stem":"Which of the following conditions carries a small risk of developing into vulvar squamous cell carcinoma?","options":[{"id":"a","text":"Lichen sclerosus"},{"id":"b","text":"Lichen simplex chronicus"},{"id":"c","text":"Bartholin cyst"},{"id":"d","text":"Atrophic vaginitis"}],"answerId":"a","explanation":"Lichen sclerosus is a non-neoplastic dermatosis that carries a small risk of vulvar SCC.","kind":"mechanism","origin":"ai"},{"id":"hrp2-vulvar-dermatoses~ai-3","moduleId":"hrp2-vulvar-dermatoses","stem":"A 30-year-old woman presents with a tender swelling on the posterolateral aspect of the labia. What is the most likely diagnosis?","options":[{"id":"a","text":"Bartholin abscess"},{"id":"b","text":"Lichen sclerosus"},{"id":"c","text":"Vulvar candidiasis"},{"id":"d","text":"Herpes simplex"}],"answerId":"a","explanation":"A tender posterolateral labial swelling is characteristic of a Bartholin abscess.","kind":"clinical","origin":"ai"},{"id":"hrp2-vulvar-dermatoses~ai-4","moduleId":"hrp2-vulvar-dermatoses","stem":"A postmenopausal woman presents with vaginal dryness and dyspareunia. Her vaginal pH is elevated. Which treatment is most appropriate?","options":[{"id":"a","text":"Topical oestrogen"},{"id":"b","text":"Oral antibiotics"},{"id":"c","text":"Antifungal cream"},{"id":"d","text":"Topical corticosteroid"}],"answerId":"a","explanation":"Topical oestrogen is used to treat atrophic vaginitis by addressing oestrogen deficiency.","kind":"trap","origin":"ai"},{"id":"hrp2-vulvar-dermatoses~ai-5","moduleId":"hrp2-vulvar-dermatoses","stem":"A patient with chronic vulvar itching presents with thickened, leathery skin. What is the most likely diagnosis?","options":[{"id":"a","text":"Lichen simplex chronicus"},{"id":"b","text":"Lichen sclerosus"},{"id":"c","text":"Psoriasis"},{"id":"d","text":"Contact dermatitis"}],"answerId":"a","explanation":"Lichen simplex chronicus results from chronic scratching, leading to thickened, leathery skin.","kind":"recall","origin":"ai"},{"id":"hrp2-vulvar-dermatoses~ai-6","moduleId":"hrp2-vulvar-dermatoses","stem":"A 40-year-old woman presents with vaginal discharge and pruritus. Examination reveals a frothy, yellow-green discharge. Which module would provide further information on this condition?","options":[{"id":"a","text":"hrp2-vulvovaginitis"},{"id":"b","text":"hrp2-vulvar-dermatoses"},{"id":"c","text":"neonatal-skin-conditions"},{"id":"d","text":"hrp2-vulvar-neoplasms"}],"answerId":"a","explanation":"The symptoms are indicative of trichomoniasis, which is covered in the vulvovaginitis module.","kind":"integration","linkedModuleIds":["hrp2-vulvovaginitis"],"origin":"ai"},{"id":"hrp2-vulvar-dermatoses~ai-7","moduleId":"hrp2-vulvar-dermatoses","stem":"A newborn presents with a vesicular rash on the skin. Which module would provide information on this condition?","options":[{"id":"a","text":"neonatal-skin-conditions"},{"id":"b","text":"hrp2-vulvar-dermatoses"},{"id":"c","text":"hrp2-vulvovaginitis"},{"id":"d","text":"hrp2-vulvar-neoplasms"}],"answerId":"a","explanation":"Neonatal vesicular rashes are covered in the neonatal skin conditions module.","kind":"integration","linkedModuleIds":["neonatal-skin-conditions"],"origin":"ai"}],"hrp2-genital-herpes-hiv-pregnancy":[{"id":"hrp2-genital-herpes-hiv-pregnancy~ai-0","moduleId":"hrp2-genital-herpes-hiv-pregnancy","stem":"A pregnant woman at 38 weeks presents with painful genital vesicles. What is the most appropriate management to prevent neonatal HSV transmission?","options":[{"id":"a","text":"Caesarean section"},{"id":"b","text":"Vaginal delivery with suppressive aciclovir"},{"id":"c","text":"Immediate induction of labor"},{"id":"d","text":"Observation and follow-up"}],"answerId":"a","explanation":"Active genital HSV lesions at delivery warrant a caesarean section to reduce neonatal HSV transmission.","kind":"clinical","origin":"ai"},{"id":"hrp2-genital-herpes-hiv-pregnancy~ai-1","moduleId":"hrp2-genital-herpes-hiv-pregnancy","stem":"Which of the following is a major risk factor for neonatal herpes transmission during delivery?","options":[{"id":"a","text":"Maternal HSV-1 infection"},{"id":"b","text":"Primary maternal HSV outbreak near term"},{"id":"c","text":"Recurrent maternal HSV outbreaks"},{"id":"d","text":"Maternal HSV latency in sacral ganglia"}],"answerId":"b","explanation":"A primary maternal HSV outbreak near term poses a high risk due to high viral shedding and lack of maternal antibodies.","kind":"mechanism","origin":"ai"},{"id":"hrp2-genital-herpes-hiv-pregnancy~ai-2","moduleId":"hrp2-genital-herpes-hiv-pregnancy","stem":"A pregnant woman with HIV has an undetectable viral load on ART. What is the recommended mode of delivery?","options":[{"id":"a","text":"Caesarean section at 38 weeks"},{"id":"b","text":"Vaginal delivery"},{"id":"c","text":"Induction of labor at 37 weeks"},{"id":"d","text":"Elective caesarean section at 39 weeks"}],"answerId":"b","explanation":"With an undetectable viral load on ART, vaginal delivery is appropriate as it minimizes vertical transmission.","kind":"clinical","origin":"ai"},{"id":"hrp2-genital-herpes-hiv-pregnancy~ai-3","moduleId":"hrp2-genital-herpes-hiv-pregnancy","stem":"Which antiviral is commonly used for suppressive therapy in pregnant women with recurrent genital herpes?","options":[{"id":"a","text":"Ganciclovir"},{"id":"b","text":"Valaciclovir"},{"id":"c","text":"Oseltamivir"},{"id":"d","text":"Ribavirin"}],"answerId":"b","explanation":"Valaciclovir is used for suppressive therapy to reduce the risk of HSV transmission during delivery.","kind":"recall","origin":"ai"},{"id":"hrp2-genital-herpes-hiv-pregnancy~ai-4","moduleId":"hrp2-genital-herpes-hiv-pregnancy","stem":"A woman with a history of genital herpes but no active lesions is in labor. What is the appropriate delivery method?","options":[{"id":"a","text":"Caesarean section"},{"id":"b","text":"Vaginal delivery"},{"id":"c","text":"Immediate induction"},{"id":"d","text":"Observation until active lesions develop"}],"answerId":"b","explanation":"Without active lesions, vaginal delivery is appropriate, especially if suppressive therapy is used.","kind":"trap","origin":"ai"},{"id":"hrp2-genital-herpes-hiv-pregnancy~ai-5","moduleId":"hrp2-genital-herpes-hiv-pregnancy","stem":"In the context of HIV, why is breastfeeding avoided where safe alternatives exist?","options":[{"id":"a","text":"To prevent maternal malnutrition"},{"id":"b","text":"To reduce postnatal vertical transmission"},{"id":"c","text":"To avoid medication transfer to the infant"},{"id":"d","text":"To prevent maternal-infant bonding issues"}],"answerId":"b","explanation":"Avoiding breastfeeding prevents postnatal vertical transmission of HIV.","kind":"mechanism","origin":"ai"},{"id":"hrp2-genital-herpes-hiv-pregnancy~ai-6","moduleId":"hrp2-genital-herpes-hiv-pregnancy","stem":"Which of the following conditions is most likely to require caesarean delivery to prevent neonatal infection?","options":[{"id":"a","text":"Maternal primary HSV outbreak"},{"id":"b","text":"Maternal CMV infection"},{"id":"c","text":"Maternal HIV with undetectable viral load"},{"id":"d","text":"Maternal recurrent HSV with no active lesions"}],"answerId":"a","explanation":"A primary HSV outbreak near term requires caesarean delivery to prevent neonatal infection.","kind":"integration","linkedModuleIds":["hrp2-perinatal-infections"],"origin":"ai"},{"id":"hrp2-genital-herpes-hiv-pregnancy~ai-7","moduleId":"hrp2-genital-herpes-hiv-pregnancy","stem":"Which antiviral is NOT typically used for treating genital herpes in pregnancy?","options":[{"id":"a","text":"Acyclovir"},{"id":"b","text":"Valaciclovir"},{"id":"c","text":"Ganciclovir"},{"id":"d","text":"Famciclovir"}],"answerId":"c","explanation":"Ganciclovir is not used for genital herpes; it is primarily for CMV infections.","kind":"integration","linkedModuleIds":["herpesvirus-cmv-antivirals"],"origin":"ai"}],"hrp2-dysmenorrhea-menorrhagia":[{"id":"hrp2-dysmenorrhea-menorrhagia~ai-0","moduleId":"hrp2-dysmenorrhea-menorrhagia","stem":"A 16-year-old girl presents with severe crampy abdominal pain during menstruation. She has no other symptoms and her pelvic exam is normal. What is the most likely diagnosis?","options":[{"id":"a","text":"Primary dysmenorrhoea"},{"id":"b","text":"Endometriosis"},{"id":"c","text":"Adenomyosis"},{"id":"d","text":"Pelvic inflammatory disease"}],"answerId":"a","explanation":"Primary dysmenorrhoea is characterized by crampy pain from menarche without pelvic pathology.","kind":"recall","origin":"ai"},{"id":"hrp2-dysmenorrhea-menorrhagia~ai-1","moduleId":"hrp2-dysmenorrhea-menorrhagia","stem":"Which of the following is the most effective medical management for heavy menstrual bleeding?","options":[{"id":"a","text":"Tranexamic acid"},{"id":"b","text":"NSAIDs"},{"id":"c","text":"Combined hormonal therapy"},{"id":"d","text":"Levonorgestrel intrauterine system (LNG-IUS)"}],"answerId":"d","explanation":"LNG-IUS is the most effective medical option for managing heavy menstrual bleeding.","kind":"recall","origin":"ai"},{"id":"hrp2-dysmenorrhea-menorrhagia~ai-2","moduleId":"hrp2-dysmenorrhea-menorrhagia","stem":"A 35-year-old woman presents with new-onset dysmenorrhoea and heavy menstrual bleeding. What is the most appropriate next step in management?","options":[{"id":"a","text":"Start NSAIDs"},{"id":"b","text":"Perform pelvic ultrasound"},{"id":"c","text":"Prescribe oral contraceptives"},{"id":"d","text":"Reassure and observe"}],"answerId":"b","explanation":"New-onset dysmenorrhoea in an older woman suggests a secondary cause; imaging is needed to identify pathology.","kind":"trap","origin":"ai"},{"id":"hrp2-dysmenorrhea-menorrhagia~ai-3","moduleId":"hrp2-dysmenorrhea-menorrhagia","stem":"A 28-year-old woman with menorrhagia since menarche is found to have iron-deficiency anaemia. Which condition should be screened for?","options":[{"id":"a","text":"Thyroid dysfunction"},{"id":"b","text":"Von Willebrand disease"},{"id":"c","text":"Endometriosis"},{"id":"d","text":"Polycystic ovary syndrome"}],"answerId":"b","explanation":"Heavy bleeding since menarche suggests a possible coagulopathy like von Willebrand disease.","kind":"clinical","origin":"ai"},{"id":"hrp2-dysmenorrhea-menorrhagia~ai-4","moduleId":"hrp2-dysmenorrhea-menorrhagia","stem":"Which mechanism is primarily responsible for the pain in primary dysmenorrhoea?","options":[{"id":"a","text":"Increased prostaglandins"},{"id":"b","text":"Endometrial hyperplasia"},{"id":"c","text":"Ovarian cysts"},{"id":"d","text":"Pelvic adhesions"}],"answerId":"a","explanation":"Prostaglandins cause myometrial contractions and ischemia, leading to pain in primary dysmenorrhoea.","kind":"mechanism","origin":"ai"},{"id":"hrp2-dysmenorrhea-menorrhagia~ai-5","moduleId":"hrp2-dysmenorrhea-menorrhagia","stem":"A 30-year-old woman with nephrotic syndrome presents with menorrhagia. Which of the following is a potential cause of her heavy menstrual bleeding?","options":[{"id":"a","text":"Hypoalbuminemia"},{"id":"b","text":"Hyperlipidemia"},{"id":"c","text":"Coagulopathy"},{"id":"d","text":"Hypertension"}],"answerId":"c","explanation":"Nephrotic syndrome can be associated with coagulopathy, which may contribute to menorrhagia.","kind":"integration","linkedModuleIds":["nephrotic-syndrome"],"origin":"ai"},{"id":"hrp2-dysmenorrhea-menorrhagia~ai-6","moduleId":"hrp2-dysmenorrhea-menorrhagia","stem":"A patient with abnormal uterine bleeding is found to have endometrial hyperplasia. Which linked condition could exacerbate her symptoms?","options":[{"id":"a","text":"Primary dysmenorrhoea"},{"id":"b","text":"Thyroid dysfunction"},{"id":"c","text":"Von Willebrand disease"},{"id":"d","text":"Endometriosis"}],"answerId":"c","explanation":"Von Willebrand disease can exacerbate bleeding disorders, worsening symptoms of endometrial hyperplasia.","kind":"integration","linkedModuleIds":["hrp2-abnormal-uterine-bleeding"],"origin":"ai"}],"hrp2-menopause-poi":[{"id":"hrp2-menopause-poi~ai-0","moduleId":"hrp2-menopause-poi","stem":"A 52-year-old woman presents with 12 months of amenorrhoea and hot flushes. What hormonal change is most likely responsible for her symptoms?","options":[{"id":"a","text":"Low oestrogen"},{"id":"b","text":"High progesterone"},{"id":"c","text":"Low FSH"},{"id":"d","text":"High testosterone"}],"answerId":"a","explanation":"Menopause is characterized by low oestrogen levels due to ovarian follicle depletion.","kind":"recall","origin":"ai"},{"id":"hrp2-menopause-poi~ai-1","moduleId":"hrp2-menopause-poi","stem":"Which of the following is a long-term consequence of menopause due to oestrogen deficiency?","options":[{"id":"a","text":"Increased risk of osteoporosis"},{"id":"b","text":"Improved cardiovascular health"},{"id":"c","text":"Decreased risk of breast cancer"},{"id":"d","text":"Increased fertility"}],"answerId":"a","explanation":"Oestrogen deficiency after menopause leads to accelerated bone loss, increasing the risk of osteoporosis.","kind":"recall","origin":"ai"},{"id":"hrp2-menopause-poi~ai-2","moduleId":"hrp2-menopause-poi","stem":"A 35-year-old woman is diagnosed with premature ovarian insufficiency. What is the recommended management to protect her bone and cardiovascular health?","options":[{"id":"a","text":"Avoid hormone replacement therapy"},{"id":"b","text":"Start hormone replacement therapy until natural menopausal age"},{"id":"c","text":"Use only non-hormonal treatments"},{"id":"d","text":"Delay treatment until symptoms worsen"}],"answerId":"b","explanation":"Hormone replacement therapy is recommended in POI to maintain physiological oestrogen levels and protect against bone and cardiovascular risks.","kind":"trap","origin":"ai"},{"id":"hrp2-menopause-poi~ai-3","moduleId":"hrp2-menopause-poi","stem":"A 45-year-old woman presents with vaginal dryness and dyspareunia. What is the underlying mechanism for these symptoms?","options":[{"id":"a","text":"Oestrogen deficiency"},{"id":"b","text":"Progesterone excess"},{"id":"c","text":"Testosterone deficiency"},{"id":"d","text":"Low prolactin levels"}],"answerId":"a","explanation":"Vaginal dryness and dyspareunia in menopause are due to oestrogen deficiency affecting the genitourinary tract.","kind":"mechanism","origin":"ai"},{"id":"hrp2-menopause-poi~ai-4","moduleId":"hrp2-menopause-poi","stem":"A 39-year-old woman with Turner syndrome is concerned about her risk of premature ovarian insufficiency. Which laboratory finding would support this diagnosis?","options":[{"id":"a","text":"High FSH levels"},{"id":"b","text":"Low LH levels"},{"id":"c","text":"Normal oestrogen levels"},{"id":"d","text":"High progesterone levels"}],"answerId":"a","explanation":"High FSH levels indicate ovarian failure, consistent with premature ovarian insufficiency.","kind":"clinical","origin":"ai"},{"id":"hrp2-menopause-poi~ai-5","moduleId":"hrp2-menopause-poi","stem":"A 28-year-old woman with a history of chemotherapy presents with amenorrhoea and hot flushes. Which condition should be considered?","options":[{"id":"a","text":"Polycystic ovary syndrome"},{"id":"b","text":"Premature ovarian insufficiency"},{"id":"c","text":"Hypothyroidism"},{"id":"d","text":"Hyperprolactinemia"}],"answerId":"b","explanation":"Chemotherapy can cause premature ovarian insufficiency, leading to amenorrhoea and hot flushes.","kind":"clinical","origin":"ai"},{"id":"hrp2-menopause-poi~ai-6","moduleId":"hrp2-menopause-poi","stem":"How does the hormonal profile in premature ovarian insufficiency differ from that in polycystic ovary syndrome?","options":[{"id":"a","text":"High FSH in POI, normal FSH in PCOS"},{"id":"b","text":"Low oestrogen in PCOS, high oestrogen in POI"},{"id":"c","text":"High testosterone in POI, low testosterone in PCOS"},{"id":"d","text":"Low LH in POI, high LH in PCOS"}],"answerId":"a","explanation":"POI is characterized by high FSH due to ovarian failure, while PCOS typically presents with normal FSH levels.","kind":"integration","linkedModuleIds":["hrp2-pcos"],"origin":"ai"},{"id":"hrp2-menopause-poi~ai-7","moduleId":"hrp2-menopause-poi","stem":"A 42-year-old woman with amenorrhoea and high FSH levels is suspected of having premature ovarian insufficiency. Which additional test would help confirm the diagnosis?","options":[{"id":"a","text":"Karyotype analysis"},{"id":"b","text":"Serum testosterone"},{"id":"c","text":"Thyroid function tests"},{"id":"d","text":"Prolactin levels"}],"answerId":"a","explanation":"Karyotype analysis can identify chromosomal abnormalities such as Turner syndrome, which is associated with POI.","kind":"integration","linkedModuleIds":["add-premature-ovarian-insufficiency-diagnosis-and-management"],"origin":"ai"}],"hrp2-pcos":[{"id":"hrp2-pcos~ai-0","moduleId":"hrp2-pcos","stem":"Which of the following is a diagnostic criterion for Polycystic Ovary Syndrome (PCOS) according to the Rotterdam criteria?","options":[{"id":"a","text":"Oligo/anovulation"},{"id":"b","text":"Increased body mass index"},{"id":"c","text":"Elevated prolactin levels"},{"id":"d","text":"Decreased LH:FSH ratio"}],"answerId":"a","explanation":"The Rotterdam criteria require two of the following: oligo/anovulation, clinical/biochemical hyperandrogenism, and polycystic ovaries on ultrasound.","kind":"recall","origin":"ai"},{"id":"hrp2-pcos~ai-1","moduleId":"hrp2-pcos","stem":"What is the primary mechanism by which insulin resistance contributes to the pathophysiology of PCOS?","options":[{"id":"a","text":"Increases ovarian androgen production"},{"id":"b","text":"Decreases LH secretion"},{"id":"c","text":"Increases SHBG levels"},{"id":"d","text":"Decreases adrenal androgen production"}],"answerId":"a","explanation":"Insulin resistance leads to hyperinsulinaemia, which increases ovarian androgen production and decreases SHBG, raising free testosterone levels.","kind":"mechanism","origin":"ai"},{"id":"hrp2-pcos~ai-2","moduleId":"hrp2-pcos","stem":"A 25-year-old woman with PCOS presents with irregular menstrual cycles and hirsutism. Which of the following treatments is most appropriate to regulate her menstrual cycles and reduce hyperandrogenism?","options":[{"id":"a","text":"Combined oral contraceptive pill"},{"id":"b","text":"Metformin"},{"id":"c","text":"Letrozole"},{"id":"d","text":"Spironolactone"}],"answerId":"a","explanation":"The combined oral contraceptive pill is used to regulate menstrual cycles and reduce symptoms of hyperandrogenism in PCOS.","kind":"clinical","origin":"ai"},{"id":"hrp2-pcos~ai-3","moduleId":"hrp2-pcos","stem":"Which of the following statements about the risk of endometrial cancer in PCOS is correct?","options":[{"id":"a","text":"PCOS mainly threatens fertility and has no cancer implications"},{"id":"b","text":"Chronic anovulation in PCOS increases endometrial cancer risk"},{"id":"c","text":"PCOS decreases the risk of endometrial cancer"},{"id":"d","text":"PCOS has no effect on the endometrium"}],"answerId":"b","explanation":"Chronic anovulation leads to unopposed oestrogen stimulation of the endometrium, increasing the risk of hyperplasia and cancer.","kind":"trap","origin":"ai"},{"id":"hrp2-pcos~ai-4","moduleId":"hrp2-pcos","stem":"A 30-year-old woman with PCOS is trying to conceive. Which medication is most appropriate to induce ovulation?","options":[{"id":"a","text":"Clomiphene citrate"},{"id":"b","text":"Metformin"},{"id":"c","text":"Spironolactone"},{"id":"d","text":"Combined oral contraceptive pill"}],"answerId":"a","explanation":"Clomiphene citrate is commonly used to induce ovulation in women with PCOS who are trying to conceive.","kind":"clinical","origin":"ai"},{"id":"hrp2-pcos~ai-5","moduleId":"hrp2-pcos","stem":"In the context of PCOS, what is the significance of a raised LH:FSH ratio?","options":[{"id":"a","text":"It indicates disordered gonadotropin secretion"},{"id":"b","text":"It confirms insulin resistance"},{"id":"c","text":"It suggests normal ovarian function"},{"id":"d","text":"It rules out hyperandrogenism"}],"answerId":"a","explanation":"A raised LH:FSH ratio is indicative of disordered gonadotropin secretion, which is common in PCOS.","kind":"mechanism","origin":"ai"},{"id":"hrp2-pcos~ai-6","moduleId":"hrp2-pcos","stem":"How does PCOS relate to the HPO axis and amenorrhea?","options":[{"id":"a","text":"PCOS leads to increased FSH and regular cycles"},{"id":"b","text":"PCOS causes decreased LH and increased SHBG"},{"id":"c","text":"PCOS results in anovulation and amenorrhea due to disrupted HPO axis"},{"id":"d","text":"PCOS is unrelated to the HPO axis"}],"answerId":"c","explanation":"PCOS disrupts the HPO axis, leading to anovulation and amenorrhea due to altered gonadotropin secretion.","kind":"integration","linkedModuleIds":["hrp2-hpo-amenorrhea-puberty"],"origin":"ai"},{"id":"hrp2-pcos~ai-7","moduleId":"hrp2-pcos","stem":"What is the relationship between PCOS and menopause?","options":[{"id":"a","text":"PCOS symptoms resolve after menopause"},{"id":"b","text":"PCOS increases the risk of premature ovarian insufficiency"},{"id":"c","text":"PCOS has no effect on menopause timing"},{"id":"d","text":"PCOS symptoms worsen after menopause"}],"answerId":"a","explanation":"PCOS symptoms often resolve after menopause due to the natural decline in ovarian androgen production.","kind":"integration","linkedModuleIds":["hrp2-menopause-poi"],"origin":"ai"}],"hrp2-neonatal-sepsis-gbs":[{"id":"hrp2-neonatal-sepsis-gbs~ai-0","moduleId":"hrp2-neonatal-sepsis-gbs","stem":"What is the most common cause of early-onset neonatal sepsis?","options":[{"id":"a","text":"Group B Streptococcus"},{"id":"b","text":"Listeria monocytogenes"},{"id":"c","text":"Staphylococcus aureus"},{"id":"d","text":"Klebsiella pneumoniae"}],"answerId":"a","explanation":"Group B Streptococcus is the leading cause of early-onset neonatal sepsis, typically acquired during birth.","kind":"recall","origin":"ai"},{"id":"hrp2-neonatal-sepsis-gbs~ai-1","moduleId":"hrp2-neonatal-sepsis-gbs","stem":"A neonate presents with respiratory distress and poor feeding within 48 hours of birth. The mother had a fever during labor. What is the most likely organism causing the sepsis?","options":[{"id":"a","text":"Escherichia coli"},{"id":"b","text":"Group B Streptococcus"},{"id":"c","text":"Listeria monocytogenes"},{"id":"d","text":"Staphylococcus epidermidis"}],"answerId":"b","explanation":"Group B Streptococcus is commonly associated with early-onset neonatal sepsis, especially with maternal fever during labor.","kind":"clinical","origin":"ai"},{"id":"hrp2-neonatal-sepsis-gbs~ai-2","moduleId":"hrp2-neonatal-sepsis-gbs","stem":"Which of the following is a key preventive measure for early-onset neonatal sepsis due to Group B Streptococcus?","options":[{"id":"a","text":"Oral antibiotics during pregnancy"},{"id":"b","text":"Intrapartum IV penicillin"},{"id":"c","text":"Postpartum IV antibiotics for the neonate"},{"id":"d","text":"Routine neonatal vaccination"}],"answerId":"b","explanation":"Intrapartum IV penicillin is given to GBS-positive mothers to prevent transmission during delivery.","kind":"trap","origin":"ai"},{"id":"hrp2-neonatal-sepsis-gbs~ai-3","moduleId":"hrp2-neonatal-sepsis-gbs","stem":"A mother is screened positive for Group B Streptococcus at 36 weeks of gestation. What is the recommended management?","options":[{"id":"a","text":"Administer oral antibiotics immediately"},{"id":"b","text":"Schedule a cesarean section"},{"id":"c","text":"Administer intrapartum IV penicillin"},{"id":"d","text":"Monitor and treat only if symptoms develop"}],"answerId":"c","explanation":"Intrapartum IV penicillin is administered to prevent neonatal transmission during delivery.","kind":"recall","origin":"ai"},{"id":"hrp2-neonatal-sepsis-gbs~ai-4","moduleId":"hrp2-neonatal-sepsis-gbs","stem":"Which maternal condition significantly increases the risk of early-onset neonatal sepsis?","options":[{"id":"a","text":"Maternal hypertension"},{"id":"b","text":"Chorioamnionitis"},{"id":"c","text":"Gestational diabetes"},{"id":"d","text":"Hyperemesis gravidarum"}],"answerId":"b","explanation":"Chorioamnionitis, characterized by maternal fever and uterine tenderness, increases the risk of neonatal sepsis.","kind":"mechanism","origin":"ai"},{"id":"hrp2-neonatal-sepsis-gbs~ai-5","moduleId":"hrp2-neonatal-sepsis-gbs","stem":"A neonate with signs of sepsis is found to have Listeria monocytogenes. What is the likely source of infection?","options":[{"id":"a","text":"Intrapartum transmission"},{"id":"b","text":"Transplacental transmission"},{"id":"c","text":"Nosocomial infection"},{"id":"d","text":"Community-acquired infection"}],"answerId":"b","explanation":"Listeria monocytogenes can be transmitted transplacentally, often associated with maternal consumption of unpasteurised dairy.","kind":"mechanism","origin":"ai"},{"id":"hrp2-neonatal-sepsis-gbs~ai-6","moduleId":"hrp2-neonatal-sepsis-gbs","stem":"A neonate develops sepsis 10 days after birth. Which organism is least likely to be the cause?","options":[{"id":"a","text":"Group B Streptococcus"},{"id":"b","text":"Escherichia coli"},{"id":"c","text":"Listeria monocytogenes"},{"id":"d","text":"Staphylococcus aureus"}],"answerId":"c","explanation":"Listeria monocytogenes is more commonly associated with early-onset sepsis rather than late-onset.","kind":"clinical","origin":"ai"},{"id":"hrp2-neonatal-sepsis-gbs~ai-7","moduleId":"hrp2-neonatal-sepsis-gbs","stem":"Which protein structure component is critical for the function of penicillin-binding proteins targeted by antibiotics in GBS prophylaxis?","options":[{"id":"a","text":"Primary structure"},{"id":"b","text":"Secondary structure"},{"id":"c","text":"Tertiary structure"},{"id":"d","text":"Quaternary structure"}],"answerId":"c","explanation":"The tertiary structure of penicillin-binding proteins is crucial for their function and binding with antibiotics.","kind":"integration","linkedModuleIds":["amino-acids-proteins-structure"],"origin":"ai"},{"id":"hrp2-neonatal-sepsis-gbs~ai-8","moduleId":"hrp2-neonatal-sepsis-gbs","stem":"In the context of perinatal infections, which organism is most commonly associated with granulomatosis infantiseptica?","options":[{"id":"a","text":"Group B Streptococcus"},{"id":"b","text":"Listeria monocytogenes"},{"id":"c","text":"Cytomegalovirus"},{"id":"d","text":"Toxoplasma gondii"}],"answerId":"b","explanation":"Listeria monocytogenes is associated with granulomatosis infantiseptica, a severe form of neonatal infection.","kind":"integration","linkedModuleIds":["hrp2-perinatal-infections"],"origin":"ai"}],"hrp2-hormonal-contraception":[{"id":"hrp2-hormonal-contraception~ai-0","moduleId":"hrp2-hormonal-contraception","stem":"Which of the following is a primary mechanism by which combined hormonal contraceptives prevent pregnancy?","options":[{"id":"a","text":"Suppression of ovulation"},{"id":"b","text":"Inhibition of sperm motility"},{"id":"c","text":"Destruction of sperm"},{"id":"d","text":"Promotion of endometrial proliferation"}],"answerId":"a","explanation":"Combined hormonal contraceptives primarily prevent pregnancy by suppressing ovulation through negative feedback on gonadotropins.","kind":"mechanism","origin":"ai"},{"id":"hrp2-hormonal-contraception~ai-1","moduleId":"hrp2-hormonal-contraception","stem":"A 38-year-old woman who smokes 15 cigarettes per day is seeking contraception. Which method is contraindicated?","options":[{"id":"a","text":"Combined oral contraceptive pill"},{"id":"b","text":"Progestin-only pill"},{"id":"c","text":"Copper IUD"},{"id":"d","text":"Levonorgestrel IUS"}],"answerId":"a","explanation":"The combined oral contraceptive pill is contraindicated in women over 35 who smoke due to increased risk of cardiovascular events.","kind":"trap","origin":"ai"},{"id":"hrp2-hormonal-contraception~ai-2","moduleId":"hrp2-hormonal-contraception","stem":"A patient is using a progestin-only contraceptive. Which of the following is a mechanism of action for this method?","options":[{"id":"a","text":"Thickening of cervical mucus"},{"id":"b","text":"Suppression of FSH release"},{"id":"c","text":"Inhibition of sperm capacitation"},{"id":"d","text":"Stimulation of endometrial growth"}],"answerId":"a","explanation":"Progestin-only contraceptives primarily work by thickening cervical mucus, which inhibits sperm penetration.","kind":"mechanism","origin":"ai"},{"id":"hrp2-hormonal-contraception~ai-3","moduleId":"hrp2-hormonal-contraception","stem":"Which of the following is a non-contraceptive benefit of combined hormonal contraceptives?","options":[{"id":"a","text":"Reduced risk of ovarian cancer"},{"id":"b","text":"Increased bone density"},{"id":"c","text":"Improved cardiovascular health"},{"id":"d","text":"Reduced risk of breast cancer"}],"answerId":"a","explanation":"Combined hormonal contraceptives reduce the risk of ovarian cancer due to fewer ovulations and the effect of progestin.","kind":"recall","origin":"ai"},{"id":"hrp2-hormonal-contraception~ai-4","moduleId":"hrp2-hormonal-contraception","stem":"A 25-year-old woman with a history of migraine with aura is seeking contraception. Which of the following is the most appropriate option?","options":[{"id":"a","text":"Combined oral contraceptive pill"},{"id":"b","text":"Progestin-only pill"},{"id":"c","text":"Estrogen patch"},{"id":"d","text":"Vaginal ring"}],"answerId":"b","explanation":"Progestin-only pills are appropriate for women with migraine with aura, as oestrogen-containing methods are contraindicated due to stroke risk.","kind":"trap","origin":"ai"},{"id":"hrp2-hormonal-contraception~ai-5","moduleId":"hrp2-hormonal-contraception","stem":"Which emergency contraception method is most effective and also prevents implantation?","options":[{"id":"a","text":"Levonorgestrel pill"},{"id":"b","text":"Ulipristal acetate"},{"id":"c","text":"Copper IUD"},{"id":"d","text":"Progestin-only pill"}],"answerId":"d","explanation":"The copper IUD is the most effective emergency contraception method and also prevents implantation.","kind":"recall","origin":"ai"},{"id":"hrp2-hormonal-contraception~ai-6","moduleId":"hrp2-hormonal-contraception","stem":"How does the use of combined hormonal contraceptives relate to the uterine cycle?","options":[{"id":"a","text":"They maintain a constant luteal phase"},{"id":"b","text":"They prevent the follicular phase"},{"id":"c","text":"They mimic the secretory phase"},{"id":"d","text":"They induce an anovulatory cycle"}],"answerId":"d","explanation":"Combined hormonal contraceptives induce an anovulatory cycle by suppressing the LH surge necessary for ovulation.","kind":"integration","linkedModuleIds":["hrp1-uterine-cycle-fertility-signs"],"origin":"ai"},{"id":"hrp2-hormonal-contraception~ai-7","moduleId":"hrp2-hormonal-contraception","stem":"What is the relationship between hormonal contraception and the corpus luteum?","options":[{"id":"a","text":"Contraceptives prevent corpus luteum formation"},{"id":"b","text":"Contraceptives enhance corpus luteum function"},{"id":"c","text":"Contraceptives prolong corpus luteum lifespan"},{"id":"d","text":"Contraceptives have no effect on the corpus luteum"}],"answerId":"a","explanation":"Hormonal contraceptives prevent ovulation, thereby preventing the formation of the corpus luteum.","kind":"integration","linkedModuleIds":["hrp1-ovulation-corpus-luteum-histology"],"origin":"ai"}],"hrp2-gestational-diabetes":[{"id":"hrp2-gestational-diabetes~ai-0","moduleId":"hrp2-gestational-diabetes","stem":"Which hormone is primarily responsible for the insulin resistance seen in gestational diabetes mellitus?","options":[{"id":"a","text":"Human placental lactogen"},{"id":"b","text":"Estrogen"},{"id":"c","text":"Progesterone"},{"id":"d","text":"Cortisol"}],"answerId":"a","explanation":"Human placental lactogen increases insulin resistance, contributing to gestational diabetes.","kind":"recall","origin":"ai"},{"id":"hrp2-gestational-diabetes~ai-1","moduleId":"hrp2-gestational-diabetes","stem":"A 28-year-old pregnant woman at 26 weeks gestation presents with a large-for-dates fetus. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Fetal hyperinsulinaemia"},{"id":"b","text":"Maternal hyperglycaemia"},{"id":"c","text":"Placental insufficiency"},{"id":"d","text":"Fetal hypothyroidism"}],"answerId":"a","explanation":"Fetal hyperinsulinaemia due to maternal glucose crossing the placenta leads to macrosomia.","kind":"mechanism","origin":"ai"},{"id":"hrp2-gestational-diabetes~ai-2","moduleId":"hrp2-gestational-diabetes","stem":"Which of the following is a common neonatal complication associated with gestational diabetes?","options":[{"id":"a","text":"Neonatal hyperglycaemia"},{"id":"b","text":"Neonatal hypoglycaemia"},{"id":"c","text":"Neonatal hypercalcaemia"},{"id":"d","text":"Neonatal hypothyroidism"}],"answerId":"b","explanation":"Neonatal hypoglycaemia occurs due to persistent fetal hyperinsulinaemia after birth.","kind":"trap","origin":"ai"},{"id":"hrp2-gestational-diabetes~ai-3","moduleId":"hrp2-gestational-diabetes","stem":"A pregnant woman with a history of polycystic ovary syndrome (PCOS) is at increased risk for which condition during pregnancy?","options":[{"id":"a","text":"Gestational diabetes mellitus"},{"id":"b","text":"Pre-eclampsia"},{"id":"c","text":"Placenta previa"},{"id":"d","text":"Ectopic pregnancy"}],"answerId":"a","explanation":"PCOS is a risk factor for gestational diabetes due to associated insulin resistance.","kind":"clinical","origin":"ai"},{"id":"hrp2-gestational-diabetes~ai-4","moduleId":"hrp2-gestational-diabetes","stem":"What is the first-line management approach for gestational diabetes mellitus?","options":[{"id":"a","text":"Diet and exercise"},{"id":"b","text":"Insulin therapy"},{"id":"c","text":"Metformin"},{"id":"d","text":"Sulfonylureas"}],"answerId":"a","explanation":"Diet and exercise are the initial management steps for gestational diabetes.","kind":"recall","origin":"ai"},{"id":"hrp2-gestational-diabetes~ai-5","moduleId":"hrp2-gestational-diabetes","stem":"A newborn of a mother with gestational diabetes is at risk for which condition immediately after birth?","options":[{"id":"a","text":"Hyperbilirubinemia"},{"id":"b","text":"Hypoglycaemia"},{"id":"c","text":"Hypercalcaemia"},{"id":"d","text":"Hyponatremia"}],"answerId":"b","explanation":"The newborn is at risk of hypoglycaemia due to high insulin levels after the maternal glucose supply is removed.","kind":"clinical","origin":"ai"},{"id":"hrp2-gestational-diabetes~ai-6","moduleId":"hrp2-gestational-diabetes","stem":"How does gestational diabetes mellitus increase the risk of shoulder dystocia during delivery?","options":[{"id":"a","text":"Increased fetal size due to hyperinsulinaemia"},{"id":"b","text":"Decreased amniotic fluid volume"},{"id":"c","text":"Maternal hypertension"},{"id":"d","text":"Placental abruption"}],"answerId":"a","explanation":"Macrosomia from fetal hyperinsulinaemia increases the risk of shoulder dystocia.","kind":"mechanism","origin":"ai"},{"id":"hrp2-gestational-diabetes~ai-7","moduleId":"hrp2-gestational-diabetes","stem":"Which screening test is used to diagnose gestational diabetes mellitus between 24-28 weeks of gestation?","options":[{"id":"a","text":"Oral glucose tolerance test"},{"id":"b","text":"Fasting blood glucose"},{"id":"c","text":"HbA1c"},{"id":"d","text":"Random blood glucose"}],"answerId":"a","explanation":"The oral glucose tolerance test is the standard screening test for gestational diabetes.","kind":"recall","origin":"ai"},{"id":"hrp2-gestational-diabetes~ai-8","moduleId":"hrp2-gestational-diabetes","stem":"In the context of gestational diabetes, how does fetal hyperinsulinaemia lead to polyhydramnios?","options":[{"id":"a","text":"Increased fetal urine output"},{"id":"b","text":"Decreased fetal swallowing"},{"id":"c","text":"Increased placental blood flow"},{"id":"d","text":"Decreased maternal blood glucose"}],"answerId":"a","explanation":"Fetal hyperinsulinaemia causes osmotic diuresis, leading to increased fetal urine output and polyhydramnios.","kind":"mechanism","origin":"ai"},{"id":"hrp2-gestational-diabetes~ai-9","moduleId":"hrp2-gestational-diabetes","stem":"A woman with gestational diabetes is concerned about her risk of developing type 2 diabetes post-pregnancy. What is the recommended follow-up?","options":[{"id":"a","text":"Annual HbA1c testing"},{"id":"b","text":"Postnatal glucose tolerance test"},{"id":"c","text":"Monthly fasting glucose checks"},{"id":"d","text":"No follow-up needed"}],"answerId":"b","explanation":"A postnatal glucose tolerance test is recommended to assess the risk of type 2 diabetes.","kind":"integration","linkedModuleIds":["add-gestational-diabetes-mellitus-screening-and-management"],"origin":"ai"},{"id":"hrp2-gestational-diabetes~ai-10","moduleId":"hrp2-gestational-diabetes","stem":"How does gestational diabetes mellitus relate to Rh isoimmunisation in terms of fetal outcomes?","options":[{"id":"a","text":"Both can lead to fetal macrosomia"},{"id":"b","text":"Both can cause neonatal jaundice"},{"id":"c","text":"Both result in fetal anemia"},{"id":"d","text":"Both increase the risk of preterm labor"}],"answerId":"b","explanation":"Both conditions can lead to neonatal jaundice, though through different mechanisms.","kind":"integration","linkedModuleIds":["hrp2-rh-isoimmunisation"],"origin":"ai"}],"hrp2-jaundice-management":[{"id":"hrp2-jaundice-management~ai-0","moduleId":"hrp2-jaundice-management","stem":"Which of the following is the primary mechanism by which phototherapy treats neonatal jaundice?","options":[{"id":"a","text":"Converts unconjugated bilirubin into water-soluble isomers"},{"id":"b","text":"Enhances hepatic conjugation of bilirubin"},{"id":"c","text":"Increases renal excretion of bilirubin"},{"id":"d","text":"Reduces bilirubin production in the liver"}],"answerId":"a","explanation":"Phototherapy converts unconjugated bilirubin in the skin into water-soluble isomers that can be excreted without conjugation.","kind":"mechanism","origin":"ai"},{"id":"hrp2-jaundice-management~ai-1","moduleId":"hrp2-jaundice-management","stem":"A 3-day-old term neonate presents with jaundice. Total serum bilirubin is 18 mg/dL. According to the nomogram, phototherapy is indicated. What is the primary reason for initiating phototherapy in this case?","options":[{"id":"a","text":"To prevent kernicterus"},{"id":"b","text":"To enhance feeding"},{"id":"c","text":"To stimulate liver function"},{"id":"d","text":"To reduce dehydration"}],"answerId":"a","explanation":"Phototherapy is initiated to prevent kernicterus by reducing bilirubin levels.","kind":"clinical","origin":"ai"},{"id":"hrp2-jaundice-management~ai-2","moduleId":"hrp2-jaundice-management","stem":"A 10-day-old breastfed infant presents with jaundice. The infant is feeding well and gaining weight. Total serum bilirubin is 12 mg/dL, primarily unconjugated. What is the most appropriate management?","options":[{"id":"a","text":"Reassurance and continue breastfeeding"},{"id":"b","text":"Initiate phototherapy"},{"id":"c","text":"Switch to formula feeding"},{"id":"d","text":"Perform exchange transfusion"}],"answerId":"a","explanation":"Breast-milk jaundice is benign and prolonged; reassurance is appropriate once pathology is excluded.","kind":"clinical","origin":"ai"},{"id":"hrp2-jaundice-management~ai-3","moduleId":"hrp2-jaundice-management","stem":"Which of the following scenarios would most likely require an exchange transfusion?","options":[{"id":"a","text":"A 2-day-old infant with bilirubin of 25 mg/dL and signs of acute bilirubin encephalopathy"},{"id":"b","text":"A 5-day-old infant with bilirubin of 15 mg/dL and no signs of encephalopathy"},{"id":"c","text":"A 3-day-old infant with bilirubin of 18 mg/dL, well-appearing"},{"id":"d","text":"A 7-day-old infant with bilirubin of 14 mg/dL, feeding well"}],"answerId":"a","explanation":"Exchange transfusion is indicated for very high bilirubin levels with signs of acute bilirubin encephalopathy to prevent kernicterus.","kind":"clinical","origin":"ai"},{"id":"hrp2-jaundice-management~ai-4","moduleId":"hrp2-jaundice-management","stem":"A neonate presents with jaundice within the first 24 hours of life. What is the most appropriate next step in management?","options":[{"id":"a","text":"Immediate investigation for underlying pathology"},{"id":"b","text":"Initiate phototherapy"},{"id":"c","text":"Start exchange transfusion"},{"id":"d","text":"Reassure and observe"}],"answerId":"a","explanation":"Jaundice within the first 24 hours is abnormal and requires urgent investigation for underlying pathology.","kind":"trap","origin":"ai"},{"id":"hrp2-jaundice-management~ai-5","moduleId":"hrp2-jaundice-management","stem":"In the context of neonatal jaundice, how does the mechanism of phototherapy differ from systemic dermatologic phototherapy?","options":[{"id":"a","text":"Neonatal phototherapy involves photoisomerisation, while dermatologic phototherapy induces DNA repair"},{"id":"b","text":"Neonatal phototherapy enhances bilirubin conjugation, while dermatologic phototherapy reduces inflammation"},{"id":"c","text":"Neonatal phototherapy converts bilirubin, while dermatologic phototherapy targets immune cells"},{"id":"d","text":"Neonatal phototherapy increases bilirubin excretion, while dermatologic phototherapy decreases cell proliferation"}],"answerId":"a","explanation":"Neonatal phototherapy converts bilirubin into water-soluble isomers, whereas dermatologic phototherapy typically involves DNA repair mechanisms.","kind":"integration","linkedModuleIds":["systemic-dermatologic-therapy"],"origin":"ai"},{"id":"hrp2-jaundice-management~ai-6","moduleId":"hrp2-jaundice-management","stem":"A 2-day-old infant with a bilirubin level of 20 mg/dL is undergoing phototherapy. What is the expected outcome of this treatment?","options":[{"id":"a","text":"Conversion of bilirubin to water-soluble isomers for excretion"},{"id":"b","text":"Direct conjugation of bilirubin in the liver"},{"id":"c","text":"Reduction of bilirubin production"},{"id":"d","text":"Enhanced renal clearance of bilirubin"}],"answerId":"a","explanation":"Phototherapy converts unconjugated bilirubin into water-soluble isomers that can be excreted without conjugation.","kind":"mechanism","origin":"ai"},{"id":"hrp2-jaundice-management~ai-7","moduleId":"hrp2-jaundice-management","stem":"How does the management of breast-feeding jaundice differ from breast-milk jaundice in neonates?","options":[{"id":"a","text":"Breast-feeding jaundice requires feeding support, while breast-milk jaundice requires reassurance"},{"id":"b","text":"Breast-feeding jaundice requires phototherapy, while breast-milk jaundice requires formula feeding"},{"id":"c","text":"Breast-feeding jaundice requires exchange transfusion, while breast-milk jaundice requires phototherapy"},{"id":"d","text":"Breast-feeding jaundice requires immediate investigation, while breast-milk jaundice requires cessation of breastfeeding"}],"answerId":"a","explanation":"Breast-feeding jaundice is due to inadequate intake and requires feeding support; breast-milk jaundice is benign and requires reassurance.","kind":"clinical","origin":"ai"},{"id":"hrp2-jaundice-management~ai-8","moduleId":"hrp2-jaundice-management","stem":"Which of the following is a key difference in the approach to neonatal jaundice management between the modules 'Neonatal Jaundice: Management' and 'Perinatal (Neonatal) Jaundice'?","options":[{"id":"a","text":"'Neonatal Jaundice: Management' focuses on treatment thresholds, while 'Perinatal Jaundice' emphasizes early detection"},{"id":"b","text":"'Neonatal Jaundice: Management' uses phototherapy, while 'Perinatal Jaundice' uses exchange transfusion"},{"id":"c","text":"'Neonatal Jaundice: Management' addresses only term infants, while 'Perinatal Jaundice' includes preterm infants"},{"id":"d","text":"'Neonatal Jaundice: Management' focuses on breast-milk jaundice, while 'Perinatal Jaundice' focuses on breast-feeding jaundice"}],"answerId":"a","explanation":"'Neonatal Jaundice: Management' focuses on treatment thresholds and interventions, while 'Perinatal Jaundice' emphasizes early detection and risk assessment.","kind":"integration","linkedModuleIds":["hrp2-perinatal-jaundice"],"origin":"ai"}],"hrp2-menopause-hrt-drugs":[{"id":"hrp2-menopause-hrt-drugs~ai-0","moduleId":"hrp2-menopause-hrt-drugs","stem":"Which of the following is a primary benefit of hormone replacement therapy (HRT) in postmenopausal women?","options":[{"id":"a","text":"Reduction in vasomotor symptoms"},{"id":"b","text":"Increased risk of breast cancer"},{"id":"c","text":"Prevention of cardiovascular disease"},{"id":"d","text":"Increased risk of endometrial cancer"}],"answerId":"a","explanation":"HRT is primarily used to relieve vasomotor symptoms such as hot flashes in postmenopausal women.","kind":"recall","origin":"ai"},{"id":"hrp2-menopause-hrt-drugs~ai-1","moduleId":"hrp2-menopause-hrt-drugs","stem":"A 52-year-old woman with an intact uterus is considering HRT for menopausal symptoms. Which regimen is appropriate?","options":[{"id":"a","text":"Oestrogen-only HRT"},{"id":"b","text":"Progestin-only HRT"},{"id":"c","text":"Combined oestrogen and progestin HRT"},{"id":"d","text":"Raloxifene"}],"answerId":"c","explanation":"A woman with a uterus requires combined HRT to prevent endometrial hyperplasia/cancer.","kind":"trap","origin":"ai"},{"id":"hrp2-menopause-hrt-drugs~ai-2","moduleId":"hrp2-menopause-hrt-drugs","stem":"What is the primary mechanism by which HRT reduces the risk of osteoporotic fractures?","options":[{"id":"a","text":"Inhibition of osteoclast activity"},{"id":"b","text":"Stimulation of osteoblast activity"},{"id":"c","text":"Increased calcium absorption"},{"id":"d","text":"Reduction of parathyroid hormone levels"}],"answerId":"b","explanation":"Oestrogen in HRT stimulates osteoblast activity, leading to increased bone formation.","kind":"mechanism","origin":"ai"},{"id":"hrp2-menopause-hrt-drugs~ai-3","moduleId":"hrp2-menopause-hrt-drugs","stem":"Which of the following is a risk associated with oral oestrogen HRT?","options":[{"id":"a","text":"Increased risk of venous thromboembolism"},{"id":"b","text":"Decreased risk of breast cancer"},{"id":"c","text":"Increased risk of ovarian cancer"},{"id":"d","text":"Decreased risk of endometrial cancer"}],"answerId":"a","explanation":"Oral oestrogen HRT is associated with an increased risk of venous thromboembolism.","kind":"recall","origin":"ai"},{"id":"hrp2-menopause-hrt-drugs~ai-4","moduleId":"hrp2-menopause-hrt-drugs","stem":"A woman with a history of venous thromboembolism is seeking treatment for menopausal symptoms. Which option is most appropriate?","options":[{"id":"a","text":"Oral oestrogen HRT"},{"id":"b","text":"Transdermal oestrogen HRT"},{"id":"c","text":"Combined oral contraceptives"},{"id":"d","text":"Raloxifene"}],"answerId":"d","explanation":"Raloxifene is a SERM that provides bone protection without increasing thrombotic risk.","kind":"clinical","origin":"ai"},{"id":"hrp2-menopause-hrt-drugs~ai-5","moduleId":"hrp2-menopause-hrt-drugs","stem":"How does raloxifene differ from oestrogen in its effect on the endometrium?","options":[{"id":"a","text":"Raloxifene stimulates the endometrium"},{"id":"b","text":"Raloxifene has no effect on the endometrium"},{"id":"c","text":"Raloxifene causes endometrial hyperplasia"},{"id":"d","text":"Raloxifene increases endometrial cancer risk"}],"answerId":"b","explanation":"Raloxifene does not stimulate the endometrium, unlike oestrogen, which can cause hyperplasia.","kind":"mechanism","origin":"ai"},{"id":"hrp2-menopause-hrt-drugs~ai-6","moduleId":"hrp2-menopause-hrt-drugs","stem":"A 55-year-old woman is on HRT and presents with new-onset breast tenderness. Which linked module could provide additional information on hormonal effects?","options":[{"id":"a","text":"Fabry Disease and Alpha-Galactosidase A Deficiency"},{"id":"b","text":"Impact of Growth Hormone on Metabolic Processes"},{"id":"c","text":"Female Sex Hormones & Inhibitors"},{"id":"d","text":"Hormonal Contraception"}],"answerId":"c","explanation":"The 'Female Sex Hormones & Inhibitors' module covers hormonal effects relevant to HRT.","kind":"integration","linkedModuleIds":["hrp2-female-hormones-drugs"],"origin":"ai"},{"id":"hrp2-menopause-hrt-drugs~ai-7","moduleId":"hrp2-menopause-hrt-drugs","stem":"Considering the prothrombotic effects of oestrogen, which linked module might help understand the metabolic impacts of hormones?","options":[{"id":"a","text":"Fabry Disease and Alpha-Galactosidase A Deficiency"},{"id":"b","text":"Impact of Growth Hormone on Metabolic Processes"},{"id":"c","text":"Female Sex Hormones & Inhibitors"},{"id":"d","text":"Hormonal Contraception"}],"answerId":"b","explanation":"The 'Impact of Growth Hormone on Metabolic Processes' module can provide insights into hormonal impacts on metabolism.","kind":"integration","linkedModuleIds":["add-impact-of-growth-hormone-on-metabolic-processes"],"origin":"ai"}],"hrp2-labour-induction-tocolysis":[{"id":"hrp2-labour-induction-tocolysis~ai-0","moduleId":"hrp2-labour-induction-tocolysis","stem":"Which medication is primarily used to ripen the cervix before induction of labor?","options":[{"id":"a","text":"Misoprostol"},{"id":"b","text":"Oxytocin"},{"id":"c","text":"Nifedipine"},{"id":"d","text":"Atosiban"}],"answerId":"a","explanation":"Misoprostol, a prostaglandin, is used for cervical ripening before labor induction.","kind":"recall","origin":"ai"},{"id":"hrp2-labour-induction-tocolysis~ai-1","moduleId":"hrp2-labour-induction-tocolysis","stem":"A 32-week pregnant woman presents with preterm labor. Which tocolytic is appropriate to delay labor for corticosteroid administration?","options":[{"id":"a","text":"Misoprostol"},{"id":"b","text":"Nifedipine"},{"id":"c","text":"Oxytocin"},{"id":"d","text":"Dinoprostone"}],"answerId":"b","explanation":"Nifedipine, a calcium channel blocker, is used to delay preterm labor and allow for corticosteroid administration.","kind":"clinical","origin":"ai"},{"id":"hrp2-labour-induction-tocolysis~ai-2","moduleId":"hrp2-labour-induction-tocolysis","stem":"What is the main risk associated with using indomethacin as a tocolytic in early gestation?","options":[{"id":"a","text":"Uterine hyperstimulation"},{"id":"b","text":"Premature ductus arteriosus closure"},{"id":"c","text":"Fetal tachycardia"},{"id":"d","text":"Maternal hypertension"}],"answerId":"b","explanation":"Indomethacin can cause premature closure of the ductus arteriosus due to its prostaglandin inhibition effects.","kind":"mechanism","origin":"ai"},{"id":"hrp2-labour-induction-tocolysis~ai-3","moduleId":"hrp2-labour-induction-tocolysis","stem":"In which scenario is tocolysis contraindicated?","options":[{"id":"a","text":"Preterm labor at 30 weeks"},{"id":"b","text":"Chorioamnionitis"},{"id":"c","text":"Twin pregnancy"},{"id":"d","text":"Mild pre-eclampsia"}],"answerId":"b","explanation":"Tocolysis is contraindicated in chorioamnionitis because continuing the pregnancy is dangerous.","kind":"trap","origin":"ai"},{"id":"hrp2-labour-induction-tocolysis~ai-4","moduleId":"hrp2-labour-induction-tocolysis","stem":"Which drug is used to establish uterine contractions after cervical ripening?","options":[{"id":"a","text":"Misoprostol"},{"id":"b","text":"Nifedipine"},{"id":"c","text":"Oxytocin"},{"id":"d","text":"Indomethacin"}],"answerId":"c","explanation":"Oxytocin is used to establish uterine contractions after cervical ripening.","kind":"recall","origin":"ai"},{"id":"hrp2-labour-induction-tocolysis~ai-5","moduleId":"hrp2-labour-induction-tocolysis","stem":"A woman with a previous cesarean section is undergoing labor induction. Which method increases the risk of uterine rupture?","options":[{"id":"a","text":"Balloon catheter"},{"id":"b","text":"Misoprostol"},{"id":"c","text":"Oxytocin"},{"id":"d","text":"Nifedipine"}],"answerId":"b","explanation":"Misoprostol increases the risk of uterine rupture, especially in women with a scarred uterus.","kind":"trap","origin":"ai"},{"id":"hrp2-labour-induction-tocolysis~ai-6","moduleId":"hrp2-labour-induction-tocolysis","stem":"How does tocolysis facilitate antenatal corticosteroid administration?","options":[{"id":"a","text":"By inducing labor"},{"id":"b","text":"By delaying labor"},{"id":"c","text":"By ripening the cervix"},{"id":"d","text":"By increasing uterine contractions"}],"answerId":"b","explanation":"Tocolysis delays labor, allowing time for antenatal corticosteroids to enhance fetal lung maturity.","kind":"mechanism","origin":"ai"},{"id":"hrp2-labour-induction-tocolysis~ai-7","moduleId":"hrp2-labour-induction-tocolysis","stem":"Which uterotonic is used to manage postpartum hemorrhage and is also discussed in the 'Drugs Affecting Uterine Contraction' module?","options":[{"id":"a","text":"Misoprostol"},{"id":"b","text":"Nifedipine"},{"id":"c","text":"Oxytocin"},{"id":"d","text":"Atosiban"}],"answerId":"c","explanation":"Oxytocin is used to manage postpartum hemorrhage and is covered in both modules.","kind":"integration","linkedModuleIds":["hrp2-uterine-contraction-drugs"],"origin":"ai"},{"id":"hrp2-labour-induction-tocolysis~ai-8","moduleId":"hrp2-labour-induction-tocolysis","stem":"Which drug is contraindicated in managing preterm labor due to its potential to cause uterine hyperstimulation?","options":[{"id":"a","text":"Misoprostol"},{"id":"b","text":"Nifedipine"},{"id":"c","text":"Oxytocin"},{"id":"d","text":"Atosiban"}],"answerId":"a","explanation":"Misoprostol can cause uterine hyperstimulation and is not used for managing preterm labor.","kind":"integration","linkedModuleIds":["hrp2-uterine-contraction-drugs"],"origin":"ai"}],"hhl-rbc-degradation-bilirubin":[{"id":"hhl-rbc-degradation-bilirubin~ai-0","moduleId":"hhl-rbc-degradation-bilirubin","stem":"A 25-year-old man presents with jaundice and splenomegaly. Laboratory tests show elevated indirect bilirubin. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Extravascular haemolysis"},{"id":"b","text":"Intravascular haemolysis"},{"id":"c","text":"Obstructive jaundice"},{"id":"d","text":"Gilbert's syndrome"}],"answerId":"a","explanation":"Extravascular haemolysis leads to increased indirect bilirubin due to macrophage breakdown of RBCs.","kind":"clinical","origin":"ai"},{"id":"hhl-rbc-degradation-bilirubin~ai-1","moduleId":"hhl-rbc-degradation-bilirubin","stem":"Which of the following is a characteristic finding in intravascular haemolysis?","options":[{"id":"a","text":"Splenomegaly"},{"id":"b","text":"Low haptoglobin"},{"id":"c","text":"Increased conjugated bilirubin"},{"id":"d","text":"Acholuric jaundice"}],"answerId":"b","explanation":"Low haptoglobin occurs as it binds free hemoglobin released during intravascular haemolysis.","kind":"recall","origin":"ai"},{"id":"hhl-rbc-degradation-bilirubin~ai-2","moduleId":"hhl-rbc-degradation-bilirubin","stem":"A patient with dark urine and pale stools is found to have elevated conjugated bilirubin. What is the most likely cause?","options":[{"id":"a","text":"Prehepatic jaundice"},{"id":"b","text":"Hepatic jaundice"},{"id":"c","text":"Posthepatic jaundice"},{"id":"d","text":"Gilbert's syndrome"}],"answerId":"c","explanation":"Posthepatic jaundice causes elevated conjugated bilirubin, dark urine, and pale stools due to bile duct obstruction.","kind":"clinical","origin":"ai"},{"id":"hhl-rbc-degradation-bilirubin~ai-3","moduleId":"hhl-rbc-degradation-bilirubin","stem":"In the context of RBC senescence, which enzyme is responsible for converting haem to biliverdin?","options":[{"id":"a","text":"Haem oxygenase"},{"id":"b","text":"UGT"},{"id":"c","text":"Biliverdin reductase"},{"id":"d","text":"Haptoglobin"}],"answerId":"a","explanation":"Haem oxygenase catalyzes the conversion of haem to biliverdin during RBC degradation.","kind":"recall","origin":"ai"},{"id":"hhl-rbc-degradation-bilirubin~ai-4","moduleId":"hhl-rbc-degradation-bilirubin","stem":"A newborn presents with jaundice and elevated unconjugated bilirubin. Which enzyme deficiency is most likely responsible?","options":[{"id":"a","text":"Haem oxygenase"},{"id":"b","text":"UGT"},{"id":"c","text":"Biliverdin reductase"},{"id":"d","text":"Haptoglobin"}],"answerId":"b","explanation":"Immature UGT enzyme activity in neonates leads to elevated unconjugated bilirubin.","kind":"clinical","origin":"ai"},{"id":"hhl-rbc-degradation-bilirubin~ai-5","moduleId":"hhl-rbc-degradation-bilirubin","stem":"A patient with hereditary spherocytosis is undergoing a hemolysis workup. Which of the following findings would you expect?","options":[{"id":"a","text":"Low haptoglobin"},{"id":"b","text":"Normal LDH"},{"id":"c","text":"Low unconjugated bilirubin"},{"id":"d","text":"Increased haptoglobin"}],"answerId":"a","explanation":"Hereditary spherocytosis causes extravascular haemolysis, leading to low haptoglobin.","kind":"integration","linkedModuleIds":["hemolysis-workup-triggers"],"origin":"ai"},{"id":"hhl-rbc-degradation-bilirubin~ai-6","moduleId":"hhl-rbc-degradation-bilirubin","stem":"A patient with a history of recurrent pneumonia presents with jaundice. Which organism is most likely to exacerbate hemolysis in this patient?","options":[{"id":"a","text":"Streptococcus pneumoniae"},{"id":"b","text":"Escherichia coli"},{"id":"c","text":"Mycoplasma pneumoniae"},{"id":"d","text":"Staphylococcus aureus"}],"answerId":"a","explanation":"Streptococcus pneumoniae can exacerbate hemolysis due to its association with hemolytic anemia.","kind":"integration","linkedModuleIds":["streptococcus-pneumoniae-enterococci"],"origin":"ai"}],"hhl-lymphatic-development":[{"id":"hhl-lymphatic-development~ai-0","moduleId":"hhl-lymphatic-development","stem":"At what embryonic week do the primary lymph sacs begin to develop?","options":[{"id":"a","text":"Week 3"},{"id":"b","text":"Week 5"},{"id":"c","text":"Week 7"},{"id":"d","text":"Week 9"}],"answerId":"b","explanation":"The lymphatic system begins to develop around week 5 with the formation of primary lymph sacs.","kind":"recall","origin":"ai"},{"id":"hhl-lymphatic-development~ai-1","moduleId":"hhl-lymphatic-development","stem":"A neonate presents with a large, transilluminating cystic mass on the posterolateral neck. Which condition is most likely?","options":[{"id":"a","text":"Branchial cleft cyst"},{"id":"b","text":"Thyroglossal duct cyst"},{"id":"c","text":"Cystic hygroma"},{"id":"d","text":"Dermoid cyst"}],"answerId":"c","explanation":"A cystic hygroma is a lymphatic malformation due to the failure of the jugular lymph sac to join the venous system.","kind":"clinical","origin":"ai"},{"id":"hhl-lymphatic-development~ai-2","moduleId":"hhl-lymphatic-development","stem":"Which embryological structure gives rise to the spleen?","options":[{"id":"a","text":"3rd pharyngeal pouch"},{"id":"b","text":"Dorsal mesogastrium"},{"id":"c","text":"Endoderm of the foregut"},{"id":"d","text":"Mesoderm of the midgut"}],"answerId":"b","explanation":"The spleen arises from the dorsal mesogastrium and is mesodermal in origin.","kind":"trap","origin":"ai"},{"id":"hhl-lymphatic-development~ai-3","moduleId":"hhl-lymphatic-development","stem":"A newborn is diagnosed with Milroy disease. What genetic mutation is associated with this condition?","options":[{"id":"a","text":"VEGFR2"},{"id":"b","text":"FLT4"},{"id":"c","text":"FGFR3"},{"id":"d","text":"VEGFR1"}],"answerId":"b","explanation":"Milroy disease is caused by mutations in the VEGFR3/FLT4 gene leading to congenital primary lymphoedema.","kind":"recall","origin":"ai"},{"id":"hhl-lymphatic-development~ai-4","moduleId":"hhl-lymphatic-development","stem":"A fetus is found to have a cystic hygroma on an antenatal scan. This finding is most strongly associated with which condition?","options":[{"id":"a","text":"Down syndrome"},{"id":"b","text":"Turner syndrome"},{"id":"c","text":"Klinefelter syndrome"},{"id":"d","text":"Patau syndrome"}],"answerId":"b","explanation":"Cystic hygroma is strongly associated with Turner syndrome (45,X) and fetal hydrops.","kind":"clinical","origin":"ai"},{"id":"hhl-lymphatic-development~ai-5","moduleId":"hhl-lymphatic-development","stem":"Which lymphatic structure drains into the left venous angle?","options":[{"id":"a","text":"Right lymphatic duct"},{"id":"b","text":"Thoracic duct"},{"id":"c","text":"Jugular lymph sac"},{"id":"d","text":"Cisterna chyli"}],"answerId":"b","explanation":"The thoracic duct drains into the left venous angle at the junction of the left subclavian and internal jugular veins.","kind":"recall","origin":"ai"},{"id":"hhl-lymphatic-development~ai-6","moduleId":"hhl-lymphatic-development","stem":"A patient with Turner syndrome is at increased risk for which lymphatic anomaly?","options":[{"id":"a","text":"Branchial cleft cyst"},{"id":"b","text":"Cystic hygroma"},{"id":"c","text":"Thyroglossal duct cyst"},{"id":"d","text":"Lymphangioma circumscriptum"}],"answerId":"b","explanation":"Turner syndrome is associated with cystic hygroma due to lymphatic malformation.","kind":"integration","linkedModuleIds":["cytogenetic-nomenclature-basics"],"origin":"ai"},{"id":"hhl-lymphatic-development~ai-7","moduleId":"hhl-lymphatic-development","stem":"Which embryological origin is shared by the thymus and a component of the adrenal gland?","options":[{"id":"a","text":"3rd pharyngeal pouch"},{"id":"b","text":"Neural crest cells"},{"id":"c","text":"Mesoderm"},{"id":"d","text":"Endoderm"}],"answerId":"c","explanation":"The adrenal cortex is mesodermal, similar to the spleen, while the thymus arises from the 3rd pharyngeal pouch.","kind":"integration","linkedModuleIds":["hen1-adrenal-gross-anatomy-vasculature"],"origin":"ai"}],"hhl-hematopoiesis-sites":[{"id":"hhl-hematopoiesis-sites~ai-0","moduleId":"hhl-hematopoiesis-sites","stem":"Which site is the first to initiate hematopoiesis during embryonic development?","options":[{"id":"a","text":"Yolk sac"},{"id":"b","text":"Liver"},{"id":"c","text":"Bone marrow"},{"id":"d","text":"Spleen"}],"answerId":"a","explanation":"The yolk sac is the first site of hematopoiesis, beginning around the third week of development.","kind":"recall","origin":"ai"},{"id":"hhl-hematopoiesis-sites~ai-1","moduleId":"hhl-hematopoiesis-sites","stem":"A 3-month-old fetus primarily produces blood cells in which organ?","options":[{"id":"a","text":"Bone marrow"},{"id":"b","text":"Liver"},{"id":"c","text":"Yolk sac"},{"id":"d","text":"Spleen"}],"answerId":"b","explanation":"During the second trimester, the liver is the main site of hematopoiesis.","kind":"recall","origin":"ai"},{"id":"hhl-hematopoiesis-sites~ai-2","moduleId":"hhl-hematopoiesis-sites","stem":"In an adult, which site is most likely to show active hematopoiesis?","options":[{"id":"a","text":"Tibia"},{"id":"b","text":"Femur shaft"},{"id":"c","text":"Sternum"},{"id":"d","text":"Radius"}],"answerId":"c","explanation":"Active red marrow in adults is primarily found in the axial skeleton, such as the sternum.","kind":"recall","origin":"ai"},{"id":"hhl-hematopoiesis-sites~ai-3","moduleId":"hhl-hematopoiesis-sites","stem":"A patient with β-thalassemia presents with hepatosplenomegaly. What is the underlying mechanism?","options":[{"id":"a","text":"Increased erythropoiesis in the bone marrow"},{"id":"b","text":"Extramedullary hematopoiesis"},{"id":"c","text":"Decreased erythropoietin production"},{"id":"d","text":"Increased platelet production"}],"answerId":"b","explanation":"In β-thalassemia, the liver and spleen resume blood formation due to marrow insufficiency.","kind":"mechanism","origin":"ai"},{"id":"hhl-hematopoiesis-sites~ai-4","moduleId":"hhl-hematopoiesis-sites","stem":"A 7-year-old child with chronic anemia and chipmunk facies is most likely experiencing which process?","options":[{"id":"a","text":"Marrow infiltration"},{"id":"b","text":"Extramedullary hematopoiesis"},{"id":"c","text":"Increased erythropoietin production"},{"id":"d","text":"Decreased bone marrow activity"}],"answerId":"b","explanation":"Chipmunk facies and hepatosplenomegaly in chronic anemia suggest extramedullary hematopoiesis.","kind":"clinical","origin":"ai"},{"id":"hhl-hematopoiesis-sites~ai-5","moduleId":"hhl-hematopoiesis-sites","stem":"Which statement about erythropoietin (EPO) and thrombopoietin (TPO) is correct?","options":[{"id":"a","text":"Both are produced in the liver"},{"id":"b","text":"EPO is produced in the kidney, TPO in the liver"},{"id":"c","text":"Both are produced in the kidney"},{"id":"d","text":"EPO is produced in the liver, TPO in the kidney"}],"answerId":"b","explanation":"EPO is produced in the kidney, while TPO is primarily produced in the liver.","kind":"trap","origin":"ai"},{"id":"hhl-hematopoiesis-sites~ai-6","moduleId":"hhl-hematopoiesis-sites","stem":"During which developmental stage does the yolk sac contribute to hematopoiesis?","options":[{"id":"a","text":"Pre-embryonic"},{"id":"b","text":"Embryonic"},{"id":"c","text":"Fetal"},{"id":"d","text":"Neonatal"}],"answerId":"b","explanation":"The yolk sac is active during the embryonic stage, around the third week.","kind":"integration","linkedModuleIds":["extraembryonic-membranes-cord"],"origin":"ai"},{"id":"hhl-hematopoiesis-sites~ai-7","moduleId":"hhl-hematopoiesis-sites","stem":"In a patient with lymphedema, which hematopoietic site might be involved in compensatory blood cell production?","options":[{"id":"a","text":"Bone marrow"},{"id":"b","text":"Liver"},{"id":"c","text":"Spleen"},{"id":"d","text":"Lymph nodes"}],"answerId":"c","explanation":"The spleen can resume hematopoiesis in cases of marrow insufficiency or stress.","kind":"integration","linkedModuleIds":["hhl-lymphatic-development"],"origin":"ai"}],"hhl-rbc-membrane-metabolism":[{"id":"hhl-rbc-membrane-metabolism~ai-0","moduleId":"hhl-rbc-membrane-metabolism","stem":"Which protein defect is most commonly associated with hereditary spherocytosis?","options":[{"id":"a","text":"Spectrin"},{"id":"b","text":"Globin"},{"id":"c","text":"Hemoglobin"},{"id":"d","text":"Myoglobin"}],"answerId":"a","explanation":"Hereditary spherocytosis is typically caused by defects in the spectrin-ankyrin-band 3 membrane skeleton.","kind":"recall","origin":"ai"},{"id":"hhl-rbc-membrane-metabolism~ai-1","moduleId":"hhl-rbc-membrane-metabolism","stem":"What is the primary method of ATP production in red blood cells?","options":[{"id":"a","text":"Oxidative phosphorylation"},{"id":"b","text":"Anaerobic glycolysis"},{"id":"c","text":"Beta-oxidation"},{"id":"d","text":"Pentose phosphate pathway"}],"answerId":"b","explanation":"Red blood cells lack mitochondria and rely on anaerobic glycolysis for ATP production.","kind":"recall","origin":"ai"},{"id":"hhl-rbc-membrane-metabolism~ai-2","moduleId":"hhl-rbc-membrane-metabolism","stem":"A patient presents with chocolate-brown blood and cyanosis unresponsive to oxygen. What is the most likely diagnosis?","options":[{"id":"a","text":"Carboxyhemoglobinemia"},{"id":"b","text":"Methaemoglobinaemia"},{"id":"c","text":"Metabolic acidosis"},{"id":"d","text":"Respiratory alkalosis"}],"answerId":"b","explanation":"Methaemoglobinaemia occurs when haem iron is oxidized to Fe³⁺, which cannot bind oxygen, causing cyanosis.","kind":"clinical","origin":"ai"},{"id":"hhl-rbc-membrane-metabolism~ai-3","moduleId":"hhl-rbc-membrane-metabolism","stem":"In which condition would you expect to find a right-shifted oxygen dissociation curve?","options":[{"id":"a","text":"Hypothermia"},{"id":"b","text":"Alkalosis"},{"id":"c","text":"Anaemia"},{"id":"d","text":"Carbon monoxide poisoning"}],"answerId":"c","explanation":"Anaemia increases 2,3-BPG, which right-shifts the curve, facilitating oxygen release to tissues.","kind":"mechanism","origin":"ai"},{"id":"hhl-rbc-membrane-metabolism~ai-4","moduleId":"hhl-rbc-membrane-metabolism","stem":"Why is methylene blue ineffective in treating methaemoglobinaemia in G6PD deficiency?","options":[{"id":"a","text":"It requires NADPH, which is deficient"},{"id":"b","text":"It causes oxidative stress"},{"id":"c","text":"It binds irreversibly to haemoglobin"},{"id":"d","text":"It is not absorbed in the gut"}],"answerId":"a","explanation":"Methylene blue relies on NADPH from the HMP shunt, which is deficient in G6PD deficiency.","kind":"trap","origin":"ai"},{"id":"hhl-rbc-membrane-metabolism~ai-5","moduleId":"hhl-rbc-membrane-metabolism","stem":"Which enzyme is crucial for maintaining reduced glutathione levels in red blood cells?","options":[{"id":"a","text":"G6PD"},{"id":"b","text":"Pyruvate kinase"},{"id":"c","text":"Carbonic anhydrase"},{"id":"d","text":"Lactate dehydrogenase"}],"answerId":"a","explanation":"G6PD is essential for producing NADPH, which maintains reduced glutathione levels.","kind":"recall","origin":"ai"},{"id":"hhl-rbc-membrane-metabolism~ai-6","moduleId":"hhl-rbc-membrane-metabolism","stem":"How does 2,3-BPG affect the oxygen dissociation curve?","options":[{"id":"a","text":"Left shift, increasing oxygen affinity"},{"id":"b","text":"Right shift, decreasing oxygen affinity"},{"id":"c","text":"No effect on the curve"},{"id":"d","text":"Increases carbon dioxide binding"}],"answerId":"b","explanation":"2,3-BPG binds to deoxyhaemoglobin, decreasing its oxygen affinity and causing a right shift.","kind":"mechanism","origin":"ai"},{"id":"hhl-rbc-membrane-metabolism~ai-7","moduleId":"hhl-rbc-membrane-metabolism","stem":"Which metabolic pathway is shared between RBC metabolism and glucose transport?","options":[{"id":"a","text":"Glycolysis"},{"id":"b","text":"Krebs cycle"},{"id":"c","text":"Electron transport chain"},{"id":"d","text":"Beta-oxidation"}],"answerId":"a","explanation":"Glycolysis is a common pathway for energy production in both RBCs and glucose transport.","kind":"integration","linkedModuleIds":["glucose-transport-glycolysis"],"origin":"ai"},{"id":"hhl-rbc-membrane-metabolism~ai-8","moduleId":"hhl-rbc-membrane-metabolism","stem":"What is the primary form in which carbon dioxide is transported in the blood?","options":[{"id":"a","text":"Dissolved CO₂"},{"id":"b","text":"Carbaminohaemoglobin"},{"id":"c","text":"Bicarbonate"},{"id":"d","text":"Carbonic acid"}],"answerId":"c","explanation":"Most carbon dioxide is transported as bicarbonate in the blood.","kind":"recall","origin":"ai"}],"hhl-wbc-morphologic-anomalies":[{"id":"hhl-wbc-morphologic-anomalies~ai-0","moduleId":"hhl-wbc-morphologic-anomalies","stem":"A 25-year-old woman presents with fever, sore throat, and lymphadenopathy. Her blood smear shows atypical lymphocytes. What is the most likely diagnosis?","options":[{"id":"a","text":"Infectious mononucleosis"},{"id":"b","text":"Acute lymphoblastic leukemia"},{"id":"c","text":"Cytomegalovirus infection"},{"id":"d","text":"Streptococcal pharyngitis"}],"answerId":"a","explanation":"Atypical lymphocytes in the context of sore throat and lymphadenopathy suggest EBV infectious mononucleosis.","kind":"clinical","origin":"ai"},{"id":"hhl-wbc-morphologic-anomalies~ai-1","moduleId":"hhl-wbc-morphologic-anomalies","stem":"Which of the following findings is most indicative of a congenital Pelger–Huët anomaly?","options":[{"id":"a","text":"Bilobed \"pince-nez\" neutrophils in a well patient"},{"id":"b","text":"Hypersegmented neutrophils"},{"id":"c","text":"Giant lysosomal granules"},{"id":"d","text":"Toxic granulation"}],"answerId":"a","explanation":"Bilobed \"pince-nez\" neutrophils in a well patient are characteristic of benign congenital Pelger–Huët anomaly.","kind":"recall","origin":"ai"},{"id":"hhl-wbc-morphologic-anomalies~ai-2","moduleId":"hhl-wbc-morphologic-anomalies","stem":"A blood smear shows hypersegmented neutrophils. Which deficiency is most likely responsible?","options":[{"id":"a","text":"Iron deficiency"},{"id":"b","text":"Vitamin B12 deficiency"},{"id":"c","text":"Vitamin C deficiency"},{"id":"d","text":"Vitamin D deficiency"}],"answerId":"b","explanation":"Hypersegmented neutrophils are indicative of megaloblastic anemia, commonly due to vitamin B12 or folate deficiency.","kind":"recall","origin":"ai"},{"id":"hhl-wbc-morphologic-anomalies~ai-3","moduleId":"hhl-wbc-morphologic-anomalies","stem":"Which of the following is a characteristic finding in Chédiak–Higashi syndrome?","options":[{"id":"a","text":"Partial albinism"},{"id":"b","text":"Toxic granulation"},{"id":"c","text":"Hypersegmented neutrophils"},{"id":"d","text":"Atypical lymphocytes"}],"answerId":"a","explanation":"Chédiak–Higashi syndrome is characterized by partial albinism, recurrent infections, and giant lysosomal granules.","kind":"recall","origin":"ai"},{"id":"hhl-wbc-morphologic-anomalies~ai-4","moduleId":"hhl-wbc-morphologic-anomalies","stem":"A patient with bacterial sepsis is likely to show which of the following changes in neutrophils?","options":[{"id":"a","text":"Toxic granulation, Döhle bodies, and vacuolation"},{"id":"b","text":"Hypersegmentation"},{"id":"c","text":"Bilobed \"pince-nez\" appearance"},{"id":"d","text":"Giant lysosomal granules"}],"answerId":"a","explanation":"Toxic granulation, Döhle bodies, and vacuolation are reactive changes in neutrophils seen in bacterial sepsis.","kind":"mechanism","origin":"ai"},{"id":"hhl-wbc-morphologic-anomalies~ai-5","moduleId":"hhl-wbc-morphologic-anomalies","stem":"In a patient with suspected acute inflammation, which cytoplasmic change in neutrophils would support this diagnosis?","options":[{"id":"a","text":"Toxic granulation"},{"id":"b","text":"Hypersegmentation"},{"id":"c","text":"Bilobed \"pince-nez\" appearance"},{"id":"d","text":"Atypical lymphocytes"}],"answerId":"a","explanation":"Toxic granulation in neutrophils is a cytoplasmic change associated with acute inflammation.","kind":"integration","linkedModuleIds":["add-histological-features-of-acute-inflammation"],"origin":"ai"},{"id":"hhl-wbc-morphologic-anomalies~ai-6","moduleId":"hhl-wbc-morphologic-anomalies","stem":"A blood smear from a patient shows Döhle bodies. Which cytoplasmic organelle is responsible for this appearance?","options":[{"id":"a","text":"Rough endoplasmic reticulum"},{"id":"b","text":"Mitochondria"},{"id":"c","text":"Golgi apparatus"},{"id":"d","text":"Lysosomes"}],"answerId":"a","explanation":"Döhle bodies are remnants of rough endoplasmic reticulum in neutrophils.","kind":"integration","linkedModuleIds":["cytoplasmic-organelles"],"origin":"ai"}],"hhl-rbc-inclusions-arrangement":[{"id":"hhl-rbc-inclusions-arrangement~ai-0","moduleId":"hhl-rbc-inclusions-arrangement","stem":"Which red blood cell inclusion is indicative of asplenia or hyposplenism?","options":[{"id":"a","text":"Howell–Jolly body"},{"id":"b","text":"Heinz body"},{"id":"c","text":"Pappenheimer body"},{"id":"d","text":"Basophilic stippling"}],"answerId":"a","explanation":"Howell–Jolly bodies are DNA remnants normally removed by the spleen; their presence indicates asplenia or hyposplenism.","kind":"recall","origin":"ai"},{"id":"hhl-rbc-inclusions-arrangement~ai-1","moduleId":"hhl-rbc-inclusions-arrangement","stem":"A blood smear shows red cells with irregular clumps. What is the most likely cause?","options":[{"id":"a","text":"High plasma paraprotein"},{"id":"b","text":"IgM cold agglutinins"},{"id":"c","text":"Iron overload"},{"id":"d","text":"DNA remnants"}],"answerId":"b","explanation":"Irregular clumps of red cells indicate autoagglutination due to IgM cold agglutinins.","kind":"clinical","origin":"ai"},{"id":"hhl-rbc-inclusions-arrangement~ai-2","moduleId":"hhl-rbc-inclusions-arrangement","stem":"Which red blood cell inclusion is seen in lead poisoning?","options":[{"id":"a","text":"Howell–Jolly body"},{"id":"b","text":"Heinz body"},{"id":"c","text":"Basophilic stippling"},{"id":"d","text":"Pappenheimer body"}],"answerId":"c","explanation":"Basophilic stippling is due to aggregated ribosomes and is seen in lead poisoning.","kind":"recall","origin":"ai"},{"id":"hhl-rbc-inclusions-arrangement~ai-3","moduleId":"hhl-rbc-inclusions-arrangement","stem":"A blood smear reveals orderly stacks of red cells. What condition is this finding associated with?","options":[{"id":"a","text":"Cold agglutinins"},{"id":"b","text":"High ESR"},{"id":"c","text":"Iron deficiency"},{"id":"d","text":"DNA remnants"}],"answerId":"b","explanation":"Orderly stacks, or rouleaux formation, are associated with high ESR and plasma paraprotein levels.","kind":"clinical","origin":"ai"},{"id":"hhl-rbc-inclusions-arrangement~ai-4","moduleId":"hhl-rbc-inclusions-arrangement","stem":"Which stain is used to differentiate Pappenheimer bodies from Howell–Jolly bodies?","options":[{"id":"a","text":"Wright stain"},{"id":"b","text":"Prussian blue stain"},{"id":"c","text":"Giemsa stain"},{"id":"d","text":"Supravital stain"}],"answerId":"b","explanation":"Prussian blue stain is used to identify iron-containing Pappenheimer bodies.","kind":"trap","origin":"ai"},{"id":"hhl-rbc-inclusions-arrangement~ai-5","moduleId":"hhl-rbc-inclusions-arrangement","stem":"A patient with G6PD deficiency is likely to have which red blood cell inclusion?","options":[{"id":"a","text":"Howell–Jolly body"},{"id":"b","text":"Heinz body"},{"id":"c","text":"Basophilic stippling"},{"id":"d","text":"Pappenheimer body"}],"answerId":"b","explanation":"Heinz bodies, which are denatured hemoglobin, are seen in G6PD deficiency.","kind":"recall","origin":"ai"},{"id":"hhl-rbc-inclusions-arrangement~ai-6","moduleId":"hhl-rbc-inclusions-arrangement","stem":"Which red blood cell inclusion is associated with iron and stains positive with Prussian blue?","options":[{"id":"a","text":"Howell–Jolly body"},{"id":"b","text":"Heinz body"},{"id":"c","text":"Basophilic stippling"},{"id":"d","text":"Pappenheimer body"}],"answerId":"d","explanation":"Pappenheimer bodies contain iron and stain positive with Prussian blue.","kind":"recall","origin":"ai"},{"id":"hhl-rbc-inclusions-arrangement~ai-7","moduleId":"hhl-rbc-inclusions-arrangement","stem":"In a patient with suspected myeloma, what red blood cell arrangement might you expect to find on a blood smear?","options":[{"id":"a","text":"Rouleaux formation"},{"id":"b","text":"Autoagglutination"},{"id":"c","text":"Target cells"},{"id":"d","text":"Schistocytes"}],"answerId":"a","explanation":"Rouleaux formation is associated with high plasma paraprotein levels, as seen in myeloma.","kind":"integration","linkedModuleIds":["hhl-rbc-morphology-shapes"],"origin":"ai"},{"id":"hhl-rbc-inclusions-arrangement~ai-8","moduleId":"hhl-rbc-inclusions-arrangement","stem":"Which organ's dysfunction is most directly indicated by the presence of Howell–Jolly bodies in a blood smear?","options":[{"id":"a","text":"Liver"},{"id":"b","text":"Spleen"},{"id":"c","text":"Bone marrow"},{"id":"d","text":"Kidney"}],"answerId":"b","explanation":"Howell–Jolly bodies indicate splenic dysfunction, as they are normally removed by the spleen.","kind":"integration","linkedModuleIds":["hhl-spleen-thymus-malt"],"origin":"ai"}],"hhl-rbc-morphology-shapes":[{"id":"hhl-rbc-morphology-shapes~ai-0","moduleId":"hhl-rbc-morphology-shapes","stem":"A 25-year-old Thai male presents with fatigue and pallor. Blood smear shows numerous target cells. What is the most likely diagnosis?","options":[{"id":"a","text":"Thalassemia"},{"id":"b","text":"Iron deficiency anemia"},{"id":"c","text":"Hereditary spherocytosis"},{"id":"d","text":"Warm autoimmune hemolytic anemia"}],"answerId":"a","explanation":"Target cells are commonly seen in thalassemia, especially in the Thai population.","kind":"clinical","origin":"ai"},{"id":"hhl-rbc-morphology-shapes~ai-1","moduleId":"hhl-rbc-morphology-shapes","stem":"A blood smear reveals spherocytes and a positive direct antiglobulin test. What is the most likely condition?","options":[{"id":"a","text":"Hereditary spherocytosis"},{"id":"b","text":"Warm autoimmune hemolytic anemia"},{"id":"c","text":"Cold agglutinin disease"},{"id":"d","text":"Iron deficiency anemia"}],"answerId":"b","explanation":"A positive DAT indicates warm autoimmune hemolytic anemia, distinguishing it from hereditary spherocytosis.","kind":"mechanism","origin":"ai"},{"id":"hhl-rbc-morphology-shapes~ai-2","moduleId":"hhl-rbc-morphology-shapes","stem":"A patient with a mechanical heart valve presents with anemia. Blood smear shows schistocytes. What is the underlying mechanism?","options":[{"id":"a","text":"Oxidative stress"},{"id":"b","text":"Mechanical shearing"},{"id":"c","text":"Membrane defect"},{"id":"d","text":"Immune destruction"}],"answerId":"b","explanation":"Schistocytes indicate mechanical shearing, common in patients with mechanical heart valves.","kind":"mechanism","origin":"ai"},{"id":"hhl-rbc-morphology-shapes~ai-3","moduleId":"hhl-rbc-morphology-shapes","stem":"A blood smear shows teardrop cells and a leukoerythroblastic film. What condition should be suspected?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Myelofibrosis"},{"id":"c","text":"Thalassemia"},{"id":"d","text":"G6PD deficiency"}],"answerId":"b","explanation":"Teardrop cells and a leukoerythroblastic film suggest myelofibrosis or marrow infiltration.","kind":"clinical","origin":"ai"},{"id":"hhl-rbc-morphology-shapes~ai-4","moduleId":"hhl-rbc-morphology-shapes","stem":"Which of the following RBC shapes is associated with G6PD deficiency?","options":[{"id":"a","text":"Spherocyte"},{"id":"b","text":"Bite cell"},{"id":"c","text":"Target cell"},{"id":"d","text":"Schistocyte"}],"answerId":"b","explanation":"Bite cells are characteristic of oxidative hemolysis seen in G6PD deficiency.","kind":"recall","origin":"ai"},{"id":"hhl-rbc-morphology-shapes~ai-5","moduleId":"hhl-rbc-morphology-shapes","stem":"A blood smear shows acanthocytes. Which condition is most likely?","options":[{"id":"a","text":"Uremia"},{"id":"b","text":"Liver disease"},{"id":"c","text":"Thalassemia"},{"id":"d","text":"G6PD deficiency"}],"answerId":"b","explanation":"Acanthocytes with irregular spikes are associated with liver disease.","kind":"trap","origin":"ai"},{"id":"hhl-rbc-morphology-shapes~ai-6","moduleId":"hhl-rbc-morphology-shapes","stem":"A patient presents with fatigue and jaundice. Blood smear shows spherocytes. The direct antiglobulin test is negative. What is the likely diagnosis?","options":[{"id":"a","text":"Warm autoimmune hemolytic anemia"},{"id":"b","text":"Hereditary spherocytosis"},{"id":"c","text":"Cold agglutinin disease"},{"id":"d","text":"Thalassemia"}],"answerId":"b","explanation":"Negative DAT with spherocytes suggests hereditary spherocytosis.","kind":"trap","origin":"ai"},{"id":"hhl-rbc-morphology-shapes~ai-7","moduleId":"hhl-rbc-morphology-shapes","stem":"A blood smear shows numerous target cells. Which epithelial classification is most likely to be affected in the same patient?","options":[{"id":"a","text":"Simple squamous epithelium"},{"id":"b","text":"Simple cuboidal epithelium"},{"id":"c","text":"Stratified squamous epithelium"},{"id":"d","text":"Simple columnar epithelium"}],"answerId":"a","explanation":"Target cells suggest thalassemia, which can cause extramedullary hematopoiesis affecting simple squamous epithelium in the bone marrow.","kind":"integration","linkedModuleIds":["epithelial-classification"],"origin":"ai"},{"id":"hhl-rbc-morphology-shapes~ai-8","moduleId":"hhl-rbc-morphology-shapes","stem":"A patient with thalassemia shows target cells on blood smear. Which RBC inclusion is also likely present?","options":[{"id":"a","text":"Heinz bodies"},{"id":"b","text":"Howell-Jolly bodies"},{"id":"c","text":"Basophilic stippling"},{"id":"d","text":"Pappenheimer bodies"}],"answerId":"c","explanation":"Basophilic stippling is commonly seen in thalassemia along with target cells.","kind":"integration","linkedModuleIds":["hhl-rbc-inclusions-arrangement"],"origin":"ai"}],"hhl-leukocyte-quantitative":[{"id":"hhl-leukocyte-quantitative~ai-0","moduleId":"hhl-leukocyte-quantitative","stem":"A 45-year-old male presents with a WBC count of 60 × 10⁹/L and a left shift. Leukocyte alkaline phosphatase (LAP) is high. What is the most likely diagnosis?","options":[{"id":"a","text":"Leukemoid reaction"},{"id":"b","text":"Chronic myeloid leukemia (CML)"},{"id":"c","text":"Acute myeloid leukemia (AML)"},{"id":"d","text":"Infectious mononucleosis"}],"answerId":"a","explanation":"A high LAP score with a very high WBC count and left shift suggests a leukemoid reaction, not CML.","kind":"trap","origin":"ai"},{"id":"hhl-leukocyte-quantitative~ai-1","moduleId":"hhl-leukocyte-quantitative","stem":"Which of the following conditions is most likely to cause neutrophilia due to demargination of neutrophils?","options":[{"id":"a","text":"Bacterial infection"},{"id":"b","text":"Corticosteroid use"},{"id":"c","text":"Viral infection"},{"id":"d","text":"Parasitic infection"}],"answerId":"b","explanation":"Corticosteroids cause demargination of neutrophils, leading to neutrophilia.","kind":"mechanism","origin":"ai"},{"id":"hhl-leukocyte-quantitative~ai-2","moduleId":"hhl-leukocyte-quantitative","stem":"A patient with fever and an absolute neutrophil count (ANC) of 0.4 × 10⁹/L should receive which of the following treatments first?","options":[{"id":"a","text":"Wait for culture results"},{"id":"b","text":"Empirical broad-spectrum antibiotics"},{"id":"c","text":"Antiviral therapy"},{"id":"d","text":"Corticosteroids"}],"answerId":"b","explanation":"Febrile neutropenia is a medical emergency requiring immediate empirical broad-spectrum antibiotics.","kind":"clinical","origin":"ai"},{"id":"hhl-leukocyte-quantitative~ai-3","moduleId":"hhl-leukocyte-quantitative","stem":"A 10-year-old child presents with a persistent cough and marked mature lymphocytosis. Which infection is most likely?","options":[{"id":"a","text":"Pertussis"},{"id":"b","text":"Influenza"},{"id":"c","text":"Tuberculosis"},{"id":"d","text":"Streptococcal pharyngitis"}],"answerId":"a","explanation":"Pertussis is associated with marked mature lymphocytosis in a coughing child.","kind":"recall","origin":"ai"},{"id":"hhl-leukocyte-quantitative~ai-4","moduleId":"hhl-leukocyte-quantitative","stem":"Which condition is characterized by low leukocyte alkaline phosphatase (LAP) and the presence of the Philadelphia chromosome?","options":[{"id":"a","text":"Chronic myeloid leukemia (CML)"},{"id":"b","text":"Leukemoid reaction"},{"id":"c","text":"Acute lymphoblastic leukemia (ALL)"},{"id":"d","text":"Infectious mononucleosis"}],"answerId":"a","explanation":"CML is characterized by low LAP and the presence of the Philadelphia chromosome.","kind":"recall","origin":"ai"},{"id":"hhl-leukocyte-quantitative~ai-5","moduleId":"hhl-leukocyte-quantitative","stem":"In the context of neutrophilia, which of the following findings would most strongly suggest a leukemoid reaction over CML?","options":[{"id":"a","text":"High LAP score"},{"id":"b","text":"Presence of basophilia"},{"id":"c","text":"Low LAP score"},{"id":"d","text":"Philadelphia chromosome"}],"answerId":"a","explanation":"A high LAP score is indicative of a leukemoid reaction, distinguishing it from CML.","kind":"trap","origin":"ai"},{"id":"hhl-leukocyte-quantitative~ai-6","moduleId":"hhl-leukocyte-quantitative","stem":"A patient with eosinophilia is being evaluated. Which of the following is NOT a typical cause of eosinophilia?","options":[{"id":"a","text":"Bacterial infection"},{"id":"b","text":"Allergy"},{"id":"c","text":"Parasitic infection"},{"id":"d","text":"Connective-tissue disease"}],"answerId":"a","explanation":"Bacterial infections do not typically cause eosinophilia.","kind":"recall","origin":"ai"},{"id":"hhl-leukocyte-quantitative~ai-7","moduleId":"hhl-leukocyte-quantitative","stem":"A patient with a high WBC count and left shift is found to have low LAP and basophilia. Which linked module would help further understand the morphologic anomalies present?","options":[{"id":"a","text":"hhl-wbc-normal-differential"},{"id":"b","text":"hhl-wbc-morphologic-anomalies"},{"id":"c","text":"hhl-leukocyte-quantitative"},{"id":"d","text":"hhl-lymphoid-malignancies"}],"answerId":"b","explanation":"The 'hhl-wbc-morphologic-anomalies' module would provide insights into the morphologic anomalies seen in CML.","kind":"integration","linkedModuleIds":["hhl-wbc-morphologic-anomalies"],"origin":"ai"},{"id":"hhl-leukocyte-quantitative~ai-8","moduleId":"hhl-leukocyte-quantitative","stem":"Which module would provide foundational knowledge on normal leukocyte counts and differentials, aiding in the interpretation of leukocyte anomalies?","options":[{"id":"a","text":"hhl-wbc-morphologic-anomalies"},{"id":"b","text":"hhl-wbc-normal-differential"},{"id":"c","text":"hhl-lymphoid-malignancies"},{"id":"d","text":"hhl-hematopoiesis"}],"answerId":"b","explanation":"The 'hhl-wbc-normal-differential' module covers normal leukocyte counts and differentials.","kind":"integration","linkedModuleIds":["hhl-wbc-normal-differential"],"origin":"ai"}],"hhl-wbc-normal-differential":[{"id":"hhl-wbc-normal-differential~ai-0","moduleId":"hhl-wbc-normal-differential","stem":"Which leukocyte is characterized by a bilobed nucleus and orange-red granules?","options":[{"id":"a","text":"Neutrophil"},{"id":"b","text":"Lymphocyte"},{"id":"c","text":"Eosinophil"},{"id":"d","text":"Basophil"}],"answerId":"c","explanation":"Eosinophils have a bilobed nucleus and orange-red granules, associated with parasitic infections and allergies.","kind":"recall","origin":"ai"},{"id":"hhl-wbc-normal-differential~ai-1","moduleId":"hhl-wbc-normal-differential","stem":"A 30-year-old male presents with a WBC count of 15,000/µL and 80% neutrophils. What is the absolute neutrophil count?","options":[{"id":"a","text":"12,000/µL"},{"id":"b","text":"8,000/µL"},{"id":"c","text":"15,000/µL"},{"id":"d","text":"3,000/µL"}],"answerId":"a","explanation":"Absolute neutrophil count is calculated as total WBC × % neutrophils/100. Here, 15,000 × 0.80 = 12,000/µL.","kind":"mechanism","origin":"ai"},{"id":"hhl-wbc-normal-differential~ai-2","moduleId":"hhl-wbc-normal-differential","stem":"In a peripheral blood smear, which finding is indicative of a 'left shift'?","options":[{"id":"a","text":"Increased lymphocytes"},{"id":"b","text":"Increased band forms"},{"id":"c","text":"Increased eosinophils"},{"id":"d","text":"Increased basophils"}],"answerId":"b","explanation":"A 'left shift' refers to an increase in immature neutrophils, such as band forms, indicating an acute bacterial infection.","kind":"mechanism","origin":"ai"},{"id":"hhl-wbc-normal-differential~ai-3","moduleId":"hhl-wbc-normal-differential","stem":"A 5-year-old child has a differential showing 60% lymphocytes. What is the most likely explanation?","options":[{"id":"a","text":"Viral infection"},{"id":"b","text":"Bacterial infection"},{"id":"c","text":"Physiological childhood differential"},{"id":"d","text":"Parasitic infection"}],"answerId":"c","explanation":"In young children, lymphocyte predominance is physiological and not indicative of infection.","kind":"clinical","origin":"ai"},{"id":"hhl-wbc-normal-differential~ai-4","moduleId":"hhl-wbc-normal-differential","stem":"Which leukocyte is primarily involved in the response to parasitic infections?","options":[{"id":"a","text":"Neutrophil"},{"id":"b","text":"Lymphocyte"},{"id":"c","text":"Monocyte"},{"id":"d","text":"Eosinophil"}],"answerId":"d","explanation":"Eosinophils are involved in the immune response to parasites and allergic reactions.","kind":"recall","origin":"ai"},{"id":"hhl-wbc-normal-differential~ai-5","moduleId":"hhl-wbc-normal-differential","stem":"A patient with a high WBC count and a low percentage of neutrophils might still have which condition?","options":[{"id":"a","text":"Neutropenia"},{"id":"b","text":"Normal absolute neutrophil count"},{"id":"c","text":"Lymphocytosis"},{"id":"d","text":"Eosinophilia"}],"answerId":"b","explanation":"A high WBC count can result in a normal or elevated absolute neutrophil count despite a low percentage.","kind":"trap","origin":"ai"},{"id":"hhl-wbc-normal-differential~ai-6","moduleId":"hhl-wbc-normal-differential","stem":"Which leukocyte type is responsible for histamine release and is characterized by dark granules obscuring the nucleus?","options":[{"id":"a","text":"Neutrophil"},{"id":"b","text":"Lymphocyte"},{"id":"c","text":"Basophil"},{"id":"d","text":"Monocyte"}],"answerId":"c","explanation":"Basophils contain dark granules that obscure the nucleus and release histamine.","kind":"recall","origin":"ai"},{"id":"hhl-wbc-normal-differential~ai-7","moduleId":"hhl-wbc-normal-differential","stem":"How does the heart's pericardium relate to leukocyte recruitment during inflammation?","options":[{"id":"a","text":"It produces leukocytes"},{"id":"b","text":"It releases inflammatory mediators"},{"id":"c","text":"It acts as a barrier to leukocyte migration"},{"id":"d","text":"It has no role in inflammation"}],"answerId":"b","explanation":"The pericardium can release inflammatory mediators that recruit leukocytes during inflammation.","kind":"integration","linkedModuleIds":["inflammatory-mediators-leukocytes"],"origin":"ai"},{"id":"hhl-wbc-normal-differential~ai-8","moduleId":"hhl-wbc-normal-differential","stem":"A 45-year-old male with chest pain shows elevated neutrophils. Which heart structure is most likely involved?","options":[{"id":"a","text":"Left atrium"},{"id":"b","text":"Right ventricle"},{"id":"c","text":"Pericardium"},{"id":"d","text":"Aortic valve"}],"answerId":"c","explanation":"Inflammation of the pericardium (pericarditis) can cause elevated neutrophils due to the inflammatory response.","kind":"integration","linkedModuleIds":["heart-chambers-pericardium"],"origin":"ai"}],"hhl-lymph-node-histology":[{"id":"hhl-lymph-node-histology~ai-0","moduleId":"hhl-lymph-node-histology","stem":"Which structure in the lymph node is primarily responsible for the entry of naïve lymphocytes from the bloodstream?","options":[{"id":"a","text":"High endothelial venules"},{"id":"b","text":"Afferent lymphatics"},{"id":"c","text":"Efferent lymphatics"},{"id":"d","text":"Subcapsular sinus"}],"answerId":"a","explanation":"Naïve lymphocytes enter the lymph node from the bloodstream via high endothelial venules in the paracortex.","kind":"recall","origin":"ai"},{"id":"hhl-lymph-node-histology~ai-1","moduleId":"hhl-lymph-node-histology","stem":"A biopsy of an enlarged lymph node shows numerous prominent follicles with a 'starry sky' appearance. What does this finding most likely indicate?","options":[{"id":"a","text":"Follicular hyperplasia"},{"id":"b","text":"Follicular lymphoma"},{"id":"c","text":"Paracortical hyperplasia"},{"id":"d","text":"Medullary hyperplasia"}],"answerId":"a","explanation":"The 'starry sky' appearance is due to tingible-body macrophages in reactive follicular hyperplasia.","kind":"recall","origin":"ai"},{"id":"hhl-lymph-node-histology~ai-2","moduleId":"hhl-lymph-node-histology","stem":"In the context of lymph node architecture, what is the primary function of the medullary cords?","options":[{"id":"a","text":"B-cell proliferation"},{"id":"b","text":"T-cell activation"},{"id":"c","text":"Antibody secretion"},{"id":"d","text":"Antigen presentation"}],"answerId":"c","explanation":"The medullary cords are rich in plasma cells, which are responsible for antibody secretion.","kind":"mechanism","origin":"ai"},{"id":"hhl-lymph-node-histology~ai-3","moduleId":"hhl-lymph-node-histology","stem":"Which condition is most likely associated with paracortical hyperplasia in a lymph node?","options":[{"id":"a","text":"Rheumatoid arthritis"},{"id":"b","text":"Epstein-Barr virus infection"},{"id":"c","text":"Toxoplasmosis"},{"id":"d","text":"Follicular lymphoma"}],"answerId":"b","explanation":"Paracortical hyperplasia is often due to a T-cell/viral reaction, such as Epstein-Barr virus infection.","kind":"clinical","origin":"ai"},{"id":"hhl-lymph-node-histology~ai-4","moduleId":"hhl-lymph-node-histology","stem":"A patient with early HIV infection is most likely to show which type of lymph node hyperplasia?","options":[{"id":"a","text":"Follicular hyperplasia"},{"id":"b","text":"Paracortical hyperplasia"},{"id":"c","text":"Medullary hyperplasia"},{"id":"d","text":"Sinus histiocytosis"}],"answerId":"a","explanation":"Early HIV infection is associated with follicular hyperplasia due to B-cell activation.","kind":"clinical","origin":"ai"},{"id":"hhl-lymph-node-histology~ai-5","moduleId":"hhl-lymph-node-histology","stem":"How does the lymph flow through a lymph node?","options":[{"id":"a","text":"Afferent lymphatics → subcapsular sinus → cortical/medullary sinuses → efferent lymphatic"},{"id":"b","text":"Efferent lymphatic → subcapsular sinus → cortical/medullary sinuses → afferent lymphatics"},{"id":"c","text":"Subcapsular sinus → afferent lymphatics → cortical/medullary sinuses → efferent lymphatic"},{"id":"d","text":"Cortical/medullary sinuses → subcapsular sinus → afferent lymphatics → efferent lymphatic"}],"answerId":"a","explanation":"Lymph flows from afferent lymphatics to the subcapsular sinus, then through cortical/medullary sinuses, and exits via the efferent lymphatic.","kind":"recall","origin":"ai"},{"id":"hhl-lymph-node-histology~ai-6","moduleId":"hhl-lymph-node-histology","stem":"Which histological feature differentiates reactive follicular hyperplasia from follicular lymphoma?","options":[{"id":"a","text":"Presence of tingible-body macrophages"},{"id":"b","text":"Monotonous follicle appearance"},{"id":"c","text":"Absence of germinal centers"},{"id":"d","text":"Expansion of the paracortex"}],"answerId":"a","explanation":"Reactive follicular hyperplasia is characterized by tingible-body macrophages, unlike follicular lymphoma.","kind":"trap","origin":"ai"},{"id":"hhl-lymph-node-histology~ai-7","moduleId":"hhl-lymph-node-histology","stem":"Which organ shares a similar zonation of immune cells as seen in the lymph node's cortex and paracortex?","options":[{"id":"a","text":"Spleen"},{"id":"b","text":"Liver"},{"id":"c","text":"Gallbladder"},{"id":"d","text":"Pancreas"}],"answerId":"a","explanation":"The spleen has similar zonation with B-cell and T-cell areas, akin to the lymph node's cortex and paracortex.","kind":"integration","linkedModuleIds":["hhl-spleen-thymus-malt"],"origin":"ai"},{"id":"hhl-lymph-node-histology~ai-8","moduleId":"hhl-lymph-node-histology","stem":"In which part of the lymph node would you expect to find the highest concentration of plasma cells?","options":[{"id":"a","text":"Cortex"},{"id":"b","text":"Paracortex"},{"id":"c","text":"Medullary cords"},{"id":"d","text":"Subcapsular sinus"}],"answerId":"c","explanation":"Plasma cells, responsible for antibody production, are concentrated in the medullary cords.","kind":"recall","origin":"ai"}],"hhl-spleen-thymus-malt":[{"id":"hhl-spleen-thymus-malt~ai-0","moduleId":"hhl-spleen-thymus-malt","stem":"Which structure in the spleen is primarily responsible for screening blood-borne encapsulated bacteria?","options":[{"id":"a","text":"Marginal zone"},{"id":"b","text":"Red pulp"},{"id":"c","text":"Hassall corpuscles"},{"id":"d","text":"PALS"}],"answerId":"a","explanation":"The marginal zone at the interface of white and red pulp screens blood-borne encapsulated bacteria.","kind":"recall","origin":"ai"},{"id":"hhl-spleen-thymus-malt~ai-1","moduleId":"hhl-spleen-thymus-malt","stem":"What is the primary function of the Hassall corpuscles found in the thymic medulla?","options":[{"id":"a","text":"Positive selection of T cells"},{"id":"b","text":"Negative selection of T cells"},{"id":"c","text":"Antigen sampling"},{"id":"d","text":"Blood filtration"}],"answerId":"b","explanation":"Hassall corpuscles are associated with the negative selection of T cells in the thymic medulla.","kind":"recall","origin":"ai"},{"id":"hhl-spleen-thymus-malt~ai-2","moduleId":"hhl-spleen-thymus-malt","stem":"A patient presents with Howell–Jolly bodies on a peripheral blood smear. What is the most likely underlying cause?","options":[{"id":"a","text":"Loss of splenic pitting"},{"id":"b","text":"Increased RBC production"},{"id":"c","text":"Infection with encapsulated bacteria"},{"id":"d","text":"Thymic hyperplasia"}],"answerId":"a","explanation":"Howell–Jolly bodies persist in circulation due to the loss of splenic pitting, often after splenectomy.","kind":"clinical","origin":"ai"},{"id":"hhl-spleen-thymus-malt~ai-3","moduleId":"hhl-spleen-thymus-malt","stem":"Which process occurs in the thymic cortex during T cell development?","options":[{"id":"a","text":"Positive selection"},{"id":"b","text":"Negative selection"},{"id":"c","text":"Antigen sampling"},{"id":"d","text":"Blood filtration"}],"answerId":"a","explanation":"Positive selection occurs in the thymic cortex, rescuing thymocytes that can bind self-MHC.","kind":"trap","origin":"ai"},{"id":"hhl-spleen-thymus-malt~ai-4","moduleId":"hhl-spleen-thymus-malt","stem":"In the context of MALT, what is the primary role of M cells overlying Peyer patches?","options":[{"id":"a","text":"Antigen sampling for gut mucosal immunity"},{"id":"b","text":"T cell positive selection"},{"id":"c","text":"Blood filtration"},{"id":"d","text":"Destruction of defective RBCs"}],"answerId":"a","explanation":"M cells sample antigens to drive gut mucosal immunity, particularly IgA production.","kind":"mechanism","origin":"ai"},{"id":"hhl-spleen-thymus-malt~ai-5","moduleId":"hhl-spleen-thymus-malt","stem":"A patient with a history of splenectomy is at increased risk for infections by which type of organism?","options":[{"id":"a","text":"Encapsulated bacteria"},{"id":"b","text":"Fungal pathogens"},{"id":"c","text":"Viral infections"},{"id":"d","text":"Parasitic infections"}],"answerId":"a","explanation":"The spleen plays a crucial role in filtering encapsulated bacteria, so its absence increases infection risk.","kind":"clinical","origin":"ai"},{"id":"hhl-spleen-thymus-malt~ai-6","moduleId":"hhl-spleen-thymus-malt","stem":"Which histological feature is a hallmark of the thymic medulla?","options":[{"id":"a","text":"PALS"},{"id":"b","text":"Hassall corpuscles"},{"id":"c","text":"Red pulp"},{"id":"d","text":"Marginal zone"}],"answerId":"b","explanation":"Hassall corpuscles are concentric epithelial whorls found in the thymic medulla.","kind":"recall","origin":"ai"},{"id":"hhl-spleen-thymus-malt~ai-7","moduleId":"hhl-spleen-thymus-malt","stem":"How does the spleen contribute to the removal of defective red blood cells?","options":[{"id":"a","text":"Culling"},{"id":"b","text":"Pitting"},{"id":"c","text":"Positive selection"},{"id":"d","text":"Antigen sampling"}],"answerId":"a","explanation":"Culling in the spleen destroys defective whole RBCs, while pitting removes inclusions.","kind":"trap","origin":"ai"},{"id":"hhl-spleen-thymus-malt~ai-8","moduleId":"hhl-spleen-thymus-malt","stem":"A patient with gastric carcinoma is found to have associated MALT lymphoma. Which module provides more information on this condition?","options":[{"id":"a","text":"hhl-rbc-inclusions-arrangement"},{"id":"b","text":"add-anatomy-of-the-spleen-and-its-clinical-correlations"},{"id":"c","text":"hhl-lymph-node-histology"},{"id":"d","text":"gastric-carcinoma-lymphoma"}],"answerId":"d","explanation":"The 'gastric-carcinoma-lymphoma' module covers MALT lymphoma associated with gastric carcinoma.","kind":"integration","linkedModuleIds":["gastric-carcinoma-lymphoma"],"origin":"ai"}],"hhl-anemia-approach-indices":[{"id":"hhl-anemia-approach-indices~ai-0","moduleId":"hhl-anemia-approach-indices","stem":"A 35-year-old woman presents with fatigue. Her hemoglobin is 10 g/dL, MCV is 75 fL, and RDW is elevated. What is the most likely cause of her anemia?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Thalassemia trait"},{"id":"c","text":"Vitamin B12 deficiency"},{"id":"d","text":"Anemia of chronic disease"}],"answerId":"a","explanation":"Microcytic anemia with high RDW suggests iron deficiency due to heterogeneous small cells.","kind":"clinical","origin":"ai"},{"id":"hhl-anemia-approach-indices~ai-1","moduleId":"hhl-anemia-approach-indices","stem":"A patient with anemia has an MCV of 85 fL and a reticulocyte production index (RPI) of 1.0. What does this indicate about the bone marrow response?","options":[{"id":"a","text":"Adequate response"},{"id":"b","text":"Inadequate response"},{"id":"c","text":"Excessive response"},{"id":"d","text":"Normal response"}],"answerId":"b","explanation":"An RPI <2 indicates an inadequate bone marrow response to anemia.","kind":"mechanism","origin":"ai"},{"id":"hhl-anemia-approach-indices~ai-2","moduleId":"hhl-anemia-approach-indices","stem":"Which of the following findings is most consistent with thalassemia trait?","options":[{"id":"a","text":"Microcytosis with high RDW"},{"id":"b","text":"Microcytosis with normal RDW"},{"id":"c","text":"Macrocytosis with high RDW"},{"id":"d","text":"Normocytosis with low RDW"}],"answerId":"b","explanation":"Thalassemia trait typically presents with microcytosis and a normal RDW due to uniform small cells.","kind":"recall","origin":"ai"},{"id":"hhl-anemia-approach-indices~ai-3","moduleId":"hhl-anemia-approach-indices","stem":"A 50-year-old man with anemia has a reticulocyte percentage of 3%. His hemoglobin is 8 g/dL. What is the corrected reticulocyte count indicating?","options":[{"id":"a","text":"Adequate marrow response"},{"id":"b","text":"Inadequate marrow response"},{"id":"c","text":"Normal marrow response"},{"id":"d","text":"Excessive marrow response"}],"answerId":"b","explanation":"The reticulocyte percentage must be corrected for low hematocrit; a raw percentage of 3% may still indicate inadequate response.","kind":"trap","origin":"ai"},{"id":"hhl-anemia-approach-indices~ai-4","moduleId":"hhl-anemia-approach-indices","stem":"A 28-year-old pregnant woman has a hemoglobin level of 10 g/dL. According to WHO criteria, how is her anemia classified?","options":[{"id":"a","text":"Not anemic"},{"id":"b","text":"Mild anemia"},{"id":"c","text":"Moderate anemia"},{"id":"d","text":"Severe anemia"}],"answerId":"c","explanation":"For pregnant women, a hemoglobin level below 11 g/dL is considered anemia; 10 g/dL is moderate.","kind":"recall","origin":"ai"},{"id":"hhl-anemia-approach-indices~ai-5","moduleId":"hhl-anemia-approach-indices","stem":"A patient with normocytic anemia and low reticulocyte count is suspected to have aplastic anemia. Which linked module should be consulted for further understanding?","options":[{"id":"a","text":"hhl-aplastic-anemia"},{"id":"b","text":"hhl-anemia-classification"},{"id":"c","text":"hhl-anemia-approach-indices"},{"id":"d","text":"hhl-anemia-diagnosis"}],"answerId":"a","explanation":"The 'hhl-aplastic-anemia' module provides detailed information on aplastic anemia.","kind":"integration","linkedModuleIds":["hhl-aplastic-anemia"],"origin":"ai"},{"id":"hhl-anemia-approach-indices~ai-6","moduleId":"hhl-anemia-approach-indices","stem":"A 40-year-old male presents with macrocytic anemia. Which module would help classify the type of anemia based on morphology?","options":[{"id":"a","text":"hhl-aplastic-anemia"},{"id":"b","text":"hhl-anemia-classification"},{"id":"c","text":"hhl-anemia-approach-indices"},{"id":"d","text":"hhl-anemia-diagnosis"}],"answerId":"b","explanation":"The 'hhl-anemia-classification' module focuses on classifying anemia based on morphologic and kinetic approaches.","kind":"integration","linkedModuleIds":["hhl-anemia-classification"],"origin":"ai"}],"hhl-anemia-classification":[{"id":"hhl-anemia-classification~ai-0","moduleId":"hhl-anemia-classification","stem":"A 45-year-old male presents with fatigue. His blood smear shows microcytic, hypochromic red cells with pencil cells. What is the most likely diagnosis?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Thalassemia"},{"id":"c","text":"Anemia of chronic disease"},{"id":"d","text":"Sideroblastic anemia"}],"answerId":"a","explanation":"Microcytic, hypochromic anemia with pencil cells is characteristic of iron deficiency.","kind":"recall","origin":"ai"},{"id":"hhl-anemia-classification~ai-1","moduleId":"hhl-anemia-classification","stem":"Which of the following is a common cause of macrocytic anemia with hypersegmented neutrophils?","options":[{"id":"a","text":"Iron deficiency"},{"id":"b","text":"Vitamin B12 deficiency"},{"id":"c","text":"Chronic kidney disease"},{"id":"d","text":"Acute blood loss"}],"answerId":"b","explanation":"Vitamin B12 deficiency leads to megaloblastic anemia, characterized by macrocytosis and hypersegmented neutrophils.","kind":"recall","origin":"ai"},{"id":"hhl-anemia-classification~ai-2","moduleId":"hhl-anemia-classification","stem":"A patient with normocytic anemia and high reticulocyte count is most likely experiencing which of the following?","options":[{"id":"a","text":"Iron deficiency"},{"id":"b","text":"Hemolysis"},{"id":"c","text":"Aplastic anemia"},{"id":"d","text":"Chronic kidney disease"}],"answerId":"b","explanation":"Normocytic anemia with high reticulocyte count suggests hemolysis or recent blood loss.","kind":"mechanism","origin":"ai"},{"id":"hhl-anemia-classification~ai-3","moduleId":"hhl-anemia-classification","stem":"Which laboratory finding helps differentiate anemia of chronic disease from iron deficiency anemia?","options":[{"id":"a","text":"MCV"},{"id":"b","text":"Serum ferritin"},{"id":"c","text":"Reticulocyte count"},{"id":"d","text":"Peripheral blood smear"}],"answerId":"b","explanation":"Serum ferritin is high or normal in anemia of chronic disease and low in iron deficiency anemia.","kind":"trap","origin":"ai"},{"id":"hhl-anemia-classification~ai-4","moduleId":"hhl-anemia-classification","stem":"A 60-year-old female with liver disease presents with macrocytic anemia. Her blood smear shows round macrocytes without hypersegmented neutrophils. What is the most likely cause of her anemia?","options":[{"id":"a","text":"Vitamin B12 deficiency"},{"id":"b","text":"Folate deficiency"},{"id":"c","text":"Liver disease"},{"id":"d","text":"Thalassemia"}],"answerId":"c","explanation":"Round macrocytes without hypersegmented neutrophils suggest non-megaloblastic anemia, often due to liver disease.","kind":"clinical","origin":"ai"},{"id":"hhl-anemia-classification~ai-5","moduleId":"hhl-anemia-classification","stem":"In the context of anemia, which of the following necrosis patterns might be observed in a patient with severe aplastic anemia?","options":[{"id":"a","text":"Coagulative necrosis"},{"id":"b","text":"Liquefactive necrosis"},{"id":"c","text":"Fat necrosis"},{"id":"d","text":"No specific necrosis pattern"}],"answerId":"d","explanation":"Aplastic anemia does not typically present with a specific necrosis pattern.","kind":"integration","linkedModuleIds":["necrosis-patterns"],"origin":"ai"},{"id":"hhl-anemia-classification~ai-6","moduleId":"hhl-anemia-classification","stem":"A patient with microcytic anemia has a normal serum iron level but low total iron binding capacity (TIBC). Which condition is most likely?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Thalassemia"},{"id":"c","text":"Anemia of chronic disease"},{"id":"d","text":"Sideroblastic anemia"}],"answerId":"c","explanation":"Anemia of chronic disease often presents with normal serum iron and low TIBC.","kind":"integration","linkedModuleIds":["hhl-anemia-approach-indices"],"origin":"ai"}],"hhl-alpha-beta-thalassemia":[{"id":"hhl-alpha-beta-thalassemia~ai-0","moduleId":"hhl-alpha-beta-thalassemia","stem":"A 3-year-old child presents with severe anemia, frontal bossing, and hepatosplenomegaly. Skull X-ray shows a 'hair-on-end' appearance. What is the most likely diagnosis?","options":[{"id":"a","text":"β-thalassemia major"},{"id":"b","text":"α-thalassemia trait"},{"id":"c","text":"Iron deficiency anemia"},{"id":"d","text":"Sickle cell anemia"}],"answerId":"a","explanation":"The clinical findings of severe anemia, frontal bossing, and 'hair-on-end' skull X-ray are indicative of β-thalassemia major.","kind":"clinical","origin":"ai"},{"id":"hhl-alpha-beta-thalassemia~ai-1","moduleId":"hhl-alpha-beta-thalassemia","stem":"Which laboratory finding is most consistent with α-thalassemia trait?","options":[{"id":"a","text":"Microcytosis with a high RBC count"},{"id":"b","text":"Increased HbA₂ >3.5%"},{"id":"c","text":"Low serum ferritin"},{"id":"d","text":"High Mentzer index"}],"answerId":"a","explanation":"α-thalassemia trait typically presents with microcytosis and a normal or high RBC count.","kind":"recall","origin":"ai"},{"id":"hhl-alpha-beta-thalassemia~ai-2","moduleId":"hhl-alpha-beta-thalassemia","stem":"A newborn is diagnosed with Hb Bart's hydrops fetalis. What is the underlying genetic cause?","options":[{"id":"a","text":"Deletion of all four α-globin genes"},{"id":"b","text":"Point mutation in β-globin gene"},{"id":"c","text":"Deletion of two α-globin genes"},{"id":"d","text":"Duplication of β-globin gene"}],"answerId":"a","explanation":"Hb Bart's hydrops fetalis is caused by the deletion of all four α-globin genes, leading to γ₄ tetramers.","kind":"mechanism","origin":"ai"},{"id":"hhl-alpha-beta-thalassemia~ai-3","moduleId":"hhl-alpha-beta-thalassemia","stem":"In a patient with suspected thalassemia trait, which test result would help differentiate it from iron deficiency anemia?","options":[{"id":"a","text":"Normal or high RBC count"},{"id":"b","text":"Low serum iron"},{"id":"c","text":"High RDW"},{"id":"d","text":"Low hemoglobin"}],"answerId":"a","explanation":"Thalassemia trait is characterized by a normal or high RBC count, unlike iron deficiency anemia.","kind":"trap","origin":"ai"},{"id":"hhl-alpha-beta-thalassemia~ai-4","moduleId":"hhl-alpha-beta-thalassemia","stem":"A patient presents with microcytic anemia. Lab results show a Mentzer index of 12. What is the most likely diagnosis?","options":[{"id":"a","text":"Thalassemia trait"},{"id":"b","text":"Iron deficiency anemia"},{"id":"c","text":"Sideroblastic anemia"},{"id":"d","text":"Anemia of chronic disease"}],"answerId":"a","explanation":"A Mentzer index less than 13 suggests thalassemia trait rather than iron deficiency anemia.","kind":"clinical","origin":"ai"},{"id":"hhl-alpha-beta-thalassemia~ai-5","moduleId":"hhl-alpha-beta-thalassemia","stem":"How does the presence of target cells and basophilic stippling on a blood smear relate to thalassemia?","options":[{"id":"a","text":"Abnormal membrane loading and precipitated globin"},{"id":"b","text":"Iron overload"},{"id":"c","text":"Vitamin B12 deficiency"},{"id":"d","text":"Folate deficiency"}],"answerId":"a","explanation":"Target cells and basophilic stippling are due to abnormal membrane loading and precipitated globin in thalassemia.","kind":"mechanism","origin":"ai"},{"id":"hhl-alpha-beta-thalassemia~ai-6","moduleId":"hhl-alpha-beta-thalassemia","stem":"Which condition is characterized by a deletion of all four α-globin genes, leading to a lethal outcome in utero?","options":[{"id":"a","text":"Hb Bart's hydrops fetalis"},{"id":"b","text":"β-thalassemia major"},{"id":"c","text":"Sickle cell disease"},{"id":"d","text":"Iron deficiency anemia"}],"answerId":"a","explanation":"Hb Bart's hydrops fetalis results from the deletion of all four α-globin genes, causing γ₄ tetramers and is lethal in utero.","kind":"recall","origin":"ai"},{"id":"hhl-alpha-beta-thalassemia~ai-7","moduleId":"hhl-alpha-beta-thalassemia","stem":"A 2-year-old child with β-thalassemia major requires regular blood transfusions. Which complication is most likely to develop without proper management?","options":[{"id":"a","text":"Iron overload"},{"id":"b","text":"Vitamin B12 deficiency"},{"id":"c","text":"Folate deficiency"},{"id":"d","text":"Hypocalcemia"}],"answerId":"a","explanation":"Regular blood transfusions in β-thalassemia major can lead to iron overload if not properly managed.","kind":"integration","linkedModuleIds":["hhl-iron-deficiency"],"origin":"ai"},{"id":"hhl-alpha-beta-thalassemia~ai-8","moduleId":"hhl-alpha-beta-thalassemia","stem":"Which genetic abnormality is associated with Hb Bart's hydrops fetalis?","options":[{"id":"a","text":"Deletion of all four α-globin genes"},{"id":"b","text":"Duplication of β-globin gene"},{"id":"c","text":"Point mutation in α-globin gene"},{"id":"d","text":"Translocation involving chromosome 11"}],"answerId":"a","explanation":"Hb Bart's hydrops fetalis is caused by the deletion of all four α-globin genes.","kind":"integration","linkedModuleIds":["chromosome-copy-structure-abnormalities"],"origin":"ai"}],"hhl-aplastic-anemia":[{"id":"hhl-aplastic-anemia~ai-0","moduleId":"hhl-aplastic-anemia","stem":"A 25-year-old male presents with fatigue, recurrent infections, and easy bruising. Laboratory tests reveal pancytopenia. Bone marrow biopsy shows a hypocellular marrow with fat spaces. What is the most likely diagnosis?","options":[{"id":"a","text":"Aplastic anemia"},{"id":"b","text":"Acute myeloid leukemia"},{"id":"c","text":"Myelofibrosis"},{"id":"d","text":"Megaloblastic anemia"}],"answerId":"a","explanation":"Aplastic anemia is characterized by pancytopenia and a hypocellular marrow with fat spaces.","kind":"clinical","origin":"ai"},{"id":"hhl-aplastic-anemia~ai-1","moduleId":"hhl-aplastic-anemia","stem":"Which of the following is a common cause of aplastic anemia?","options":[{"id":"a","text":"Chloramphenicol"},{"id":"b","text":"Vitamin B12 deficiency"},{"id":"c","text":"Chronic myeloid leukemia"},{"id":"d","text":"Iron deficiency"}],"answerId":"a","explanation":"Chloramphenicol is a drug known to cause aplastic anemia.","kind":"recall","origin":"ai"},{"id":"hhl-aplastic-anemia~ai-2","moduleId":"hhl-aplastic-anemia","stem":"A bone marrow biopsy shows fibrosis and teardrop-shaped red blood cells. Which condition does this finding suggest?","options":[{"id":"a","text":"Aplastic anemia"},{"id":"b","text":"Myelofibrosis"},{"id":"c","text":"Megaloblastic anemia"},{"id":"d","text":"Acute lymphoblastic leukemia"}],"answerId":"b","explanation":"Fibrosis and teardrop cells are indicative of myelofibrosis, not aplastic anemia.","kind":"trap","origin":"ai"},{"id":"hhl-aplastic-anemia~ai-3","moduleId":"hhl-aplastic-anemia","stem":"A patient with aplastic anemia has a neutrophil count of 0.1×10⁹/L. According to the Camitta criteria, how is the severity classified?","options":[{"id":"a","text":"Mild"},{"id":"b","text":"Moderate"},{"id":"c","text":"Severe"},{"id":"d","text":"Very severe"}],"answerId":"d","explanation":"A neutrophil count <0.2×10⁹/L classifies the aplastic anemia as very severe.","kind":"recall","origin":"ai"},{"id":"hhl-aplastic-anemia~ai-4","moduleId":"hhl-aplastic-anemia","stem":"A 30-year-old female with aplastic anemia is considered for treatment. She has a matched sibling donor. What is the recommended treatment?","options":[{"id":"a","text":"Immunosuppression with ATG and ciclosporin"},{"id":"b","text":"Eltrombopag"},{"id":"c","text":"Supportive transfusion"},{"id":"d","text":"Allogeneic hematopoietic stem cell transplantation"}],"answerId":"d","explanation":"Allogeneic HSCT is curative for young patients with a matched sibling donor.","kind":"clinical","origin":"ai"},{"id":"hhl-aplastic-anemia~ai-5","moduleId":"hhl-aplastic-anemia","stem":"Which of the following laboratory findings is most consistent with aplastic anemia?","options":[{"id":"a","text":"Hypercellular marrow with blasts"},{"id":"b","text":"Hypocellular marrow with fat spaces"},{"id":"c","text":"Hypercellular marrow with megaloblasts"},{"id":"d","text":"Fibrotic marrow with teardrop cells"}],"answerId":"b","explanation":"Aplastic anemia is characterized by a hypocellular marrow with fat spaces.","kind":"recall","origin":"ai"},{"id":"hhl-aplastic-anemia~ai-6","moduleId":"hhl-aplastic-anemia","stem":"A patient presents with macrocytic anemia and pancytopenia. Bone marrow biopsy reveals hypercellularity. Which condition is most likely?","options":[{"id":"a","text":"Aplastic anemia"},{"id":"b","text":"Megaloblastic anemia"},{"id":"c","text":"Myelofibrosis"},{"id":"d","text":"Acute myeloid leukemia"}],"answerId":"b","explanation":"Hypercellular marrow with macrocytic anemia suggests megaloblastic anemia.","kind":"integration","linkedModuleIds":["hhl-anemia-classification"],"origin":"ai"},{"id":"hhl-aplastic-anemia~ai-7","moduleId":"hhl-aplastic-anemia","stem":"A patient with pancytopenia has a bone marrow biopsy showing no fibrosis, no infiltrate, and no abnormal cells. Which test would help differentiate between aplastic anemia and other causes of pancytopenia?","options":[{"id":"a","text":"Reticulocyte count"},{"id":"b","text":"Serum ferritin"},{"id":"c","text":"Erythropoietin level"},{"id":"d","text":"Direct Coombs test"}],"answerId":"a","explanation":"A low reticulocyte count indicates hypoproliferative anemia, consistent with aplastic anemia.","kind":"integration","linkedModuleIds":["hhl-anemia-approach-indices"],"origin":"ai"}],"hhl-hemoglobin-switching":[{"id":"hhl-hemoglobin-switching~ai-0","moduleId":"hhl-hemoglobin-switching","stem":"Which hemoglobin variant is predominant in a healthy adult?","options":[{"id":"a","text":"HbA (α₂β₂)"},{"id":"b","text":"HbF (α₂γ₂)"},{"id":"c","text":"HbA₂ (α₂δ₂)"},{"id":"d","text":"Hb Portland"}],"answerId":"a","explanation":"In adults, HbA (α₂β₂) constitutes approximately 97% of hemoglobin.","kind":"recall","origin":"ai"},{"id":"hhl-hemoglobin-switching~ai-1","moduleId":"hhl-hemoglobin-switching","stem":"What is the primary reason fetal hemoglobin (HbF) has a higher oxygen affinity than adult hemoglobin?","options":[{"id":"a","text":"Better O₂ binding by γ-chains"},{"id":"b","text":"Poor 2,3-BPG binding"},{"id":"c","text":"Higher heme concentration"},{"id":"d","text":"Increased iron content"}],"answerId":"b","explanation":"HbF binds 2,3-BPG poorly, which results in a left-shifted oxygen dissociation curve and higher oxygen affinity.","kind":"trap","origin":"ai"},{"id":"hhl-hemoglobin-switching~ai-2","moduleId":"hhl-hemoglobin-switching","stem":"A newborn is found to have a high level of HbF. Which condition could explain this finding if it persists beyond infancy?","options":[{"id":"a","text":"α-thalassemia"},{"id":"b","text":"β-thalassemia"},{"id":"c","text":"Sickle cell disease"},{"id":"d","text":"Iron deficiency anemia"}],"answerId":"b","explanation":"Persistently high HbF beyond infancy is often due to impaired β-chain production, as seen in β-thalassemia.","kind":"clinical","origin":"ai"},{"id":"hhl-hemoglobin-switching~ai-3","moduleId":"hhl-hemoglobin-switching","stem":"During which developmental stage does the switch from fetal hemoglobin (HbF) to adult hemoglobin (HbA) primarily occur?","options":[{"id":"a","text":"First trimester"},{"id":"b","text":"Around birth"},{"id":"c","text":"Six months postnatal"},{"id":"d","text":"Puberty"}],"answerId":"b","explanation":"The γ to β switch occurs around birth, transitioning from HbF to HbA.","kind":"mechanism","origin":"ai"},{"id":"hhl-hemoglobin-switching~ai-4","moduleId":"hhl-hemoglobin-switching","stem":"In the context of hemoglobin switching, why does HbA₂ (α₂δ₂) increase in β-thalassemia trait?","options":[{"id":"a","text":"Compensatory increase due to β-chain deficiency"},{"id":"b","text":"Increased δ-chain synthesis"},{"id":"c","text":"Decreased α-chain synthesis"},{"id":"d","text":"Increased γ-chain synthesis"}],"answerId":"a","explanation":"In β-thalassemia trait, the reduced β-chain production leads to a compensatory increase in HbA₂.","kind":"mechanism","origin":"ai"},{"id":"hhl-hemoglobin-switching~ai-5","moduleId":"hhl-hemoglobin-switching","stem":"Which hemoglobin type is expected to be elevated in a patient with α-thalassemia?","options":[{"id":"a","text":"HbA"},{"id":"b","text":"HbA₂"},{"id":"c","text":"HbF"},{"id":"d","text":"Hb Bart's"}],"answerId":"d","explanation":"Hb Bart's (γ₄) can be elevated in α-thalassemia due to the lack of α-chains.","kind":"clinical","origin":"ai"},{"id":"hhl-hemoglobin-switching~ai-6","moduleId":"hhl-hemoglobin-switching","stem":"How does exercise affect the oxygen-hemoglobin dissociation curve?","options":[{"id":"a","text":"Left shift due to decreased CO₂"},{"id":"b","text":"Right shift due to increased 2,3-BPG"},{"id":"c","text":"No change in the curve"},{"id":"d","text":"Left shift due to increased pH"}],"answerId":"b","explanation":"Exercise increases 2,3-BPG production, causing a right shift in the oxygen-hemoglobin dissociation curve.","kind":"integration","linkedModuleIds":["add-hematology-oxygen-hemoglobin-dissociation-curve"],"origin":"ai"},{"id":"hhl-hemoglobin-switching~ai-7","moduleId":"hhl-hemoglobin-switching","stem":"Which metabolic change during exercise contributes to the right shift of the oxygen-hemoglobin dissociation curve?","options":[{"id":"a","text":"Increased lactic acid"},{"id":"b","text":"Decreased temperature"},{"id":"c","text":"Decreased CO₂ production"},{"id":"d","text":"Increased pH"}],"answerId":"a","explanation":"Increased lactic acid production during exercise lowers pH, contributing to a right shift in the curve.","kind":"integration","linkedModuleIds":["exercise-stress-fuel-integration"],"origin":"ai"}],"hhl-iron-deficiency":[{"id":"hhl-iron-deficiency~ai-0","moduleId":"hhl-iron-deficiency","stem":"Which of the following is the most specific laboratory marker for iron deficiency anemia?","options":[{"id":"a","text":"Low ferritin"},{"id":"b","text":"Low serum iron"},{"id":"c","text":"High TIBC"},{"id":"d","text":"Low transferrin saturation"}],"answerId":"a","explanation":"Low ferritin is the most specific marker for iron deficiency as it reflects depleted iron stores.","kind":"recall","origin":"ai"},{"id":"hhl-iron-deficiency~ai-1","moduleId":"hhl-iron-deficiency","stem":"A 45-year-old man presents with fatigue and is found to have microcytic hypochromic anemia. What is the next best step in management?","options":[{"id":"a","text":"Prescribe oral iron supplements"},{"id":"b","text":"Order a colonoscopy"},{"id":"c","text":"Check vitamin B12 levels"},{"id":"d","text":"Perform a bone marrow biopsy"}],"answerId":"b","explanation":"In an adult male, iron deficiency anemia should prompt investigation for occult GI bleeding, such as a colonoscopy.","kind":"trap","origin":"ai"},{"id":"hhl-iron-deficiency~ai-2","moduleId":"hhl-iron-deficiency","stem":"Which of the following findings is least likely to be associated with iron deficiency anemia?","options":[{"id":"a","text":"Koilonychia"},{"id":"b","text":"Glossitis"},{"id":"c","text":"High RBC count"},{"id":"d","text":"Pica"}],"answerId":"c","explanation":"A high RBC count is more typical of thalassemia trait, not iron deficiency anemia.","kind":"clinical","origin":"ai"},{"id":"hhl-iron-deficiency~ai-3","moduleId":"hhl-iron-deficiency","stem":"What is the primary mechanism behind the microcytic hypochromic appearance of red blood cells in iron deficiency anemia?","options":[{"id":"a","text":"Decreased hemoglobin synthesis"},{"id":"b","text":"Increased erythropoietin production"},{"id":"c","text":"Bone marrow suppression"},{"id":"d","text":"Hemolysis"}],"answerId":"a","explanation":"Decreased hemoglobin synthesis due to lack of iron leads to microcytic hypochromic red blood cells.","kind":"mechanism","origin":"ai"},{"id":"hhl-iron-deficiency~ai-4","moduleId":"hhl-iron-deficiency","stem":"A patient with iron deficiency anemia is found to have high RDW. What does this indicate?","options":[{"id":"a","text":"Uniform cell size"},{"id":"b","text":"Varied cell size"},{"id":"c","text":"Increased hemolysis"},{"id":"d","text":"Decreased erythropoiesis"}],"answerId":"b","explanation":"High RDW indicates anisocytosis, or varied cell size, common in iron deficiency anemia.","kind":"recall","origin":"ai"},{"id":"hhl-iron-deficiency~ai-5","moduleId":"hhl-iron-deficiency","stem":"A 30-year-old woman with iron deficiency anemia is being evaluated. Which condition should also be considered due to shared symptoms?","options":[{"id":"a","text":"Megaloblastic anemia"},{"id":"b","text":"Thalassemia trait"},{"id":"c","text":"Anemia of chronic disease"},{"id":"d","text":"Sickle cell anemia"}],"answerId":"b","explanation":"Thalassemia trait can present with microcytic anemia but typically has normal iron studies and a high RBC count.","kind":"integration","linkedModuleIds":["hhl-alpha-beta-thalassemia"],"origin":"ai"},{"id":"hhl-iron-deficiency~ai-6","moduleId":"hhl-iron-deficiency","stem":"In the context of iron deficiency anemia, which epithelial change is most likely observed?","options":[{"id":"a","text":"Squamous metaplasia"},{"id":"b","text":"Koilonychia"},{"id":"c","text":"Hyperkeratosis"},{"id":"d","text":"Acanthosis"}],"answerId":"b","explanation":"Koilonychia, or spoon-shaped nails, is a classic epithelial change associated with iron deficiency.","kind":"integration","linkedModuleIds":["epithelial-classification"],"origin":"ai"}],"hhl-hemoglobinopathies-diagnosis":[{"id":"hhl-hemoglobinopathies-diagnosis~ai-0","moduleId":"hhl-hemoglobinopathies-diagnosis","stem":"A 25-year-old Thai male presents with microcytosis and numerous target cells on a blood smear. Hemoglobin electrophoresis shows an HbE band. What is the most likely underlying genetic mutation?","options":[{"id":"a","text":"β-globin codon 26 Glu→Lys"},{"id":"b","text":"α-globin codon 142 Gln→Stop"},{"id":"c","text":"β-globin codon 6 Glu→Val"},{"id":"d","text":"α-globin codon 59 Gly→Asp"}],"answerId":"a","explanation":"HbE is caused by a β-globin codon 26 point mutation (Glu→Lys).","kind":"recall","origin":"ai"},{"id":"hhl-hemoglobinopathies-diagnosis~ai-1","moduleId":"hhl-hemoglobinopathies-diagnosis","stem":"A patient with known HbE presents with severe anemia. Which additional condition should be suspected?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"HbE/β-thalassemia compound state"},{"id":"c","text":"Sickle cell disease"},{"id":"d","text":"Vitamin B12 deficiency"}],"answerId":"b","explanation":"Severe anemia in an HbE patient suggests an HbE/β-thalassemia compound state.","kind":"clinical","origin":"ai"},{"id":"hhl-hemoglobinopathies-diagnosis~ai-2","moduleId":"hhl-hemoglobinopathies-diagnosis","stem":"Which test is used to detect unstable hemoglobins such as HbE?","options":[{"id":"a","text":"Osmotic fragility test"},{"id":"b","text":"DCIP test"},{"id":"c","text":"Coombs test"},{"id":"d","text":"Reticulocyte count"}],"answerId":"b","explanation":"The DCIP test detects unstable hemoglobins like HbE.","kind":"recall","origin":"ai"},{"id":"hhl-hemoglobinopathies-diagnosis~ai-3","moduleId":"hhl-hemoglobinopathies-diagnosis","stem":"A Thai couple is planning to have a child. Both have microcytosis and target cells on blood smear. What is the next best step in their evaluation?","options":[{"id":"a","text":"Start iron supplementation"},{"id":"b","text":"Perform Hb typing and DCIP test"},{"id":"c","text":"Order a bone marrow biopsy"},{"id":"d","text":"Measure serum ferritin levels"}],"answerId":"b","explanation":"Hb typing and DCIP test are crucial to identify carriers of hemoglobinopathies, common in SE Asia.","kind":"trap","origin":"ai"},{"id":"hhl-hemoglobinopathies-diagnosis~ai-4","moduleId":"hhl-hemoglobinopathies-diagnosis","stem":"In the context of Thailand's national thalassemia-prevention program, what is the primary purpose of screening couples with MCV/MCH and DCIP/OF tests?","options":[{"id":"a","text":"To diagnose anemia"},{"id":"b","text":"To identify carriers of hemoglobinopathies"},{"id":"c","text":"To assess iron status"},{"id":"d","text":"To evaluate bone marrow function"}],"answerId":"b","explanation":"Screening identifies carriers to offer prenatal diagnosis and prevent severe thalassemia.","kind":"mechanism","origin":"ai"},{"id":"hhl-hemoglobinopathies-diagnosis~ai-5","moduleId":"hhl-hemoglobinopathies-diagnosis","stem":"A 3-year-old child with HbE/β-thalassemia is being evaluated for potential bone marrow transplantation. Which linked module provides information on transplant matching?","options":[{"id":"a","text":"thalassemia-prevention-screening"},{"id":"b","text":"transplant-matching-immunosuppression"},{"id":"c","text":"hhl-alpha-beta-thalassemia"},{"id":"d","text":"hhl-hemoglobin-switching"}],"answerId":"b","explanation":"The 'transplant-matching-immunosuppression' module covers transplant matching.","kind":"integration","linkedModuleIds":["transplant-matching-immunosuppression"],"origin":"ai"},{"id":"hhl-hemoglobinopathies-diagnosis~ai-6","moduleId":"hhl-hemoglobinopathies-diagnosis","stem":"A newborn screening shows elevated Hb Bart's. Which linked module should be consulted for further understanding of α-thalassemia syndromes?","options":[{"id":"a","text":"thalassemia-prevention-screening"},{"id":"b","text":"transplant-matching-immunosuppression"},{"id":"c","text":"hhl-alpha-beta-thalassemia"},{"id":"d","text":"hhl-hemoglobin-switching"}],"answerId":"c","explanation":"The 'hhl-alpha-beta-thalassemia' module provides information on α-thalassemia syndromes.","kind":"integration","linkedModuleIds":["hhl-alpha-beta-thalassemia"],"origin":"ai"}],"hhl-iron-metabolism-studies":[{"id":"hhl-iron-metabolism-studies~ai-0","moduleId":"hhl-iron-metabolism-studies","stem":"Which protein is responsible for the transport of iron in the blood?","options":[{"id":"a","text":"Transferrin"},{"id":"b","text":"Ferritin"},{"id":"c","text":"Hepcidin"},{"id":"d","text":"Ferroportin"}],"answerId":"a","explanation":"Transferrin is the main protein that binds and transports iron in the bloodstream.","kind":"recall","origin":"ai"},{"id":"hhl-iron-metabolism-studies~ai-1","moduleId":"hhl-iron-metabolism-studies","stem":"A patient presents with anemia and lab results show low serum iron, low TIBC, and high ferritin. What is the most likely diagnosis?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Anemia of chronic disease"},{"id":"c","text":"Hemochromatosis"},{"id":"d","text":"Thalassemia"}],"answerId":"b","explanation":"These findings are indicative of anemia of chronic disease, where iron is sequestered due to high hepcidin levels.","kind":"clinical","origin":"ai"},{"id":"hhl-iron-metabolism-studies~ai-2","moduleId":"hhl-iron-metabolism-studies","stem":"Which of the following conditions is characterized by increased hepcidin levels?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Anemia of chronic disease"},{"id":"c","text":"Hemochromatosis"},{"id":"d","text":"Vitamin B12 deficiency"}],"answerId":"b","explanation":"Anemia of chronic disease is associated with increased hepcidin levels, leading to iron sequestration.","kind":"mechanism","origin":"ai"},{"id":"hhl-iron-metabolism-studies~ai-3","moduleId":"hhl-iron-metabolism-studies","stem":"A patient has high ferritin and high transferrin saturation. Which condition is most likely?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Anemia of chronic disease"},{"id":"c","text":"Hemochromatosis"},{"id":"d","text":"Vitamin B12 deficiency"}],"answerId":"c","explanation":"High ferritin and high transferrin saturation suggest iron overload, such as in hemochromatosis.","kind":"clinical","origin":"ai"},{"id":"hhl-iron-metabolism-studies~ai-4","moduleId":"hhl-iron-metabolism-studies","stem":"In the context of iron metabolism, what is the role of ferroportin?","options":[{"id":"a","text":"Iron storage"},{"id":"b","text":"Iron transport in blood"},{"id":"c","text":"Iron export from cells"},{"id":"d","text":"Iron absorption in the gut"}],"answerId":"c","explanation":"Ferroportin is responsible for exporting iron from enterocytes and macrophages into the bloodstream.","kind":"recall","origin":"ai"},{"id":"hhl-iron-metabolism-studies~ai-5","moduleId":"hhl-iron-metabolism-studies","stem":"A patient with fatigue and pallor has a low serum iron, high TIBC, and low ferritin. Which condition is most likely?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Anemia of chronic disease"},{"id":"c","text":"Hemochromatosis"},{"id":"d","text":"Thalassemia"}],"answerId":"a","explanation":"Low serum iron, high TIBC, and low ferritin are indicative of iron deficiency anemia.","kind":"clinical","origin":"ai"},{"id":"hhl-iron-metabolism-studies~ai-6","moduleId":"hhl-iron-metabolism-studies","stem":"How does inflammation affect iron metabolism?","options":[{"id":"a","text":"Decreases hepcidin production"},{"id":"b","text":"Increases iron absorption"},{"id":"c","text":"Increases hepcidin production"},{"id":"d","text":"Decreases ferritin levels"}],"answerId":"c","explanation":"Inflammation increases hepcidin production, leading to decreased iron export and sequestration.","kind":"mechanism","origin":"ai"},{"id":"hhl-iron-metabolism-studies~ai-7","moduleId":"hhl-iron-metabolism-studies","stem":"A patient with macrocytic anemia is found to have low serum iron and high ferritin. Which additional test would help differentiate between iron deficiency and anemia of chronic disease?","options":[{"id":"a","text":"Serum B12 level"},{"id":"b","text":"Soluble transferrin receptor"},{"id":"c","text":"Bone marrow biopsy"},{"id":"d","text":"Serum folate level"}],"answerId":"b","explanation":"Soluble transferrin receptor levels help differentiate between iron deficiency (high sTfR) and anemia of chronic disease (normal sTfR).","kind":"integration","linkedModuleIds":["hhl-b12-folate-megaloblastic"],"origin":"ai"},{"id":"hhl-iron-metabolism-studies~ai-8","moduleId":"hhl-iron-metabolism-studies","stem":"A patient with microcytic anemia has low serum iron, high TIBC, and low ferritin. Which linked module should be reviewed for further understanding?","options":[{"id":"a","text":"Megaloblastic Anemia (B12 & Folate)"},{"id":"b","text":"Iron Deficiency Anemia"},{"id":"c","text":"Hemochromatosis"},{"id":"d","text":"Thalassemia"}],"answerId":"b","explanation":"These findings are characteristic of iron deficiency anemia, which is covered in the linked module on Iron Deficiency Anemia.","kind":"integration","linkedModuleIds":["hhl-iron-deficiency"],"origin":"ai"}],"hhl-b12-folate-megaloblastic":[{"id":"hhl-b12-folate-megaloblastic~ai-0","moduleId":"hhl-b12-folate-megaloblastic","stem":"A 45-year-old vegan presents with fatigue and paresthesia. Blood tests reveal macrocytic anemia. Which deficiency is most likely responsible for the neurological symptoms?","options":[{"id":"a","text":"Vitamin B12 deficiency"},{"id":"b","text":"Folate deficiency"},{"id":"c","text":"Iron deficiency"},{"id":"d","text":"Vitamin D deficiency"}],"answerId":"a","explanation":"Vitamin B12 deficiency can cause neurological symptoms such as paresthesia due to subacute combined degeneration of the spinal cord.","kind":"clinical","origin":"ai"},{"id":"hhl-b12-folate-megaloblastic~ai-1","moduleId":"hhl-b12-folate-megaloblastic","stem":"Which laboratory finding is characteristic of megaloblastic anemia due to impaired DNA synthesis?","options":[{"id":"a","text":"Microcytic hypochromic red cells"},{"id":"b","text":"Hypersegmented neutrophils"},{"id":"c","text":"Normal reticulocyte count"},{"id":"d","text":"Decreased LDH levels"}],"answerId":"b","explanation":"Hypersegmented neutrophils are a hallmark of megaloblastic anemia due to impaired DNA synthesis.","kind":"recall","origin":"ai"},{"id":"hhl-b12-folate-megaloblastic~ai-2","moduleId":"hhl-b12-folate-megaloblastic","stem":"A patient with megaloblastic anemia is treated with folate alone. What potential complication should be monitored?","options":[{"id":"a","text":"Worsening anemia"},{"id":"b","text":"Neurological deterioration"},{"id":"c","text":"Iron overload"},{"id":"d","text":"Hypokalemia"}],"answerId":"b","explanation":"Treating with folate alone in B12 deficiency can worsen neurological damage due to subacute combined degeneration of the cord.","kind":"trap","origin":"ai"},{"id":"hhl-b12-folate-megaloblastic~ai-3","moduleId":"hhl-b12-folate-megaloblastic","stem":"Which of the following is a common cause of vitamin B12 deficiency?","options":[{"id":"a","text":"Excessive alcohol consumption"},{"id":"b","text":"Pernicious anemia"},{"id":"c","text":"Celiac disease"},{"id":"d","text":"Chronic kidney disease"}],"answerId":"b","explanation":"Pernicious anemia, an autoimmune condition, is a common cause of vitamin B12 deficiency.","kind":"recall","origin":"ai"},{"id":"hhl-b12-folate-megaloblastic~ai-4","moduleId":"hhl-b12-folate-megaloblastic","stem":"A 30-year-old pregnant woman presents with macrocytic anemia. Which deficiency is most likely given her condition?","options":[{"id":"a","text":"Vitamin B12 deficiency"},{"id":"b","text":"Folate deficiency"},{"id":"c","text":"Iron deficiency"},{"id":"d","text":"Vitamin C deficiency"}],"answerId":"b","explanation":"Folate deficiency is common in pregnancy due to increased demand and can lead to macrocytic anemia.","kind":"clinical","origin":"ai"},{"id":"hhl-b12-folate-megaloblastic~ai-5","moduleId":"hhl-b12-folate-megaloblastic","stem":"How does vitamin B12 deficiency lead to neurological symptoms?","options":[{"id":"a","text":"Impaired DNA synthesis in neurons"},{"id":"b","text":"Demyelination of nerve fibers"},{"id":"c","text":"Increased oxidative stress"},{"id":"d","text":"Reduced neurotransmitter synthesis"}],"answerId":"b","explanation":"Vitamin B12 deficiency leads to demyelination, particularly affecting the dorsal columns and corticospinal tracts.","kind":"mechanism","origin":"ai"},{"id":"hhl-b12-folate-megaloblastic~ai-6","moduleId":"hhl-b12-folate-megaloblastic","stem":"A patient with chronic alcoholism presents with macrocytic anemia. Which other deficiency should be considered due to their alcohol use?","options":[{"id":"a","text":"Thiamine deficiency"},{"id":"b","text":"Vitamin C deficiency"},{"id":"c","text":"Vitamin D deficiency"},{"id":"d","text":"Calcium deficiency"}],"answerId":"a","explanation":"Chronic alcoholism can lead to thiamine deficiency, which is associated with Wernicke's encephalopathy.","kind":"integration","linkedModuleIds":["thiamine-wernicke-recovery"],"origin":"ai"},{"id":"hhl-b12-folate-megaloblastic~ai-7","moduleId":"hhl-b12-folate-megaloblastic","stem":"A patient with megaloblastic anemia has elevated LDH and indirect bilirubin levels. What does this indicate about the erythropoiesis process?","options":[{"id":"a","text":"Effective erythropoiesis"},{"id":"b","text":"Ineffective erythropoiesis"},{"id":"c","text":"Hemolytic anemia"},{"id":"d","text":"Iron deficiency anemia"}],"answerId":"b","explanation":"Elevated LDH and indirect bilirubin indicate ineffective erythropoiesis due to intramedullary hemolysis.","kind":"mechanism","origin":"ai"},{"id":"hhl-b12-folate-megaloblastic~ai-8","moduleId":"hhl-b12-folate-megaloblastic","stem":"In a patient with macrocytic anemia, which test would help differentiate between iron deficiency anemia and megaloblastic anemia?","options":[{"id":"a","text":"Serum ferritin"},{"id":"b","text":"Serum folate"},{"id":"c","text":"Peripheral blood smear"},{"id":"d","text":"Serum iron"}],"answerId":"c","explanation":"A peripheral blood smear showing hypersegmented neutrophils indicates megaloblastic anemia, not iron deficiency.","kind":"integration","linkedModuleIds":["hhl-iron-deficiency"],"origin":"ai"}],"hhl-aiha":[{"id":"hhl-aiha~ai-0","moduleId":"hhl-aiha","stem":"A 35-year-old woman presents with fatigue and jaundice. Her laboratory tests show spherocytes and a positive direct Coombs test for IgG. What is the most appropriate initial treatment?","options":[{"id":"a","text":"Corticosteroids"},{"id":"b","text":"Rituximab"},{"id":"c","text":"Splenectomy"},{"id":"d","text":"IVIG"}],"answerId":"a","explanation":"Warm AIHA is treated first-line with corticosteroids.","kind":"clinical","origin":"ai"},{"id":"hhl-aiha~ai-1","moduleId":"hhl-aiha","stem":"A patient with a history of Mycoplasma pneumoniae infection presents with hemolytic anemia. The direct Coombs test is positive for C3d only. What is the most likely diagnosis?","options":[{"id":"a","text":"Warm AIHA"},{"id":"b","text":"Cold agglutinin disease"},{"id":"c","text":"Hereditary spherocytosis"},{"id":"d","text":"G6PD deficiency"}],"answerId":"b","explanation":"Cold agglutinin disease is associated with IgM antibodies and a positive Coombs test for C3d.","kind":"recall","origin":"ai"},{"id":"hhl-aiha~ai-2","moduleId":"hhl-aiha","stem":"Which laboratory finding differentiates warm autoimmune hemolytic anemia from hereditary spherocytosis?","options":[{"id":"a","text":"Presence of spherocytes"},{"id":"b","text":"Positive direct Coombs test"},{"id":"c","text":"Increased reticulocyte count"},{"id":"d","text":"Elevated indirect bilirubin"}],"answerId":"b","explanation":"Warm AIHA has a positive direct Coombs test, unlike hereditary spherocytosis.","kind":"trap","origin":"ai"},{"id":"hhl-aiha~ai-3","moduleId":"hhl-aiha","stem":"A patient with cold agglutinin disease experiences acrocyanosis in cold weather. What is the underlying mechanism?","options":[{"id":"a","text":"IgG-mediated hemolysis"},{"id":"b","text":"IgM-mediated agglutination"},{"id":"c","text":"Complement-mediated lysis"},{"id":"d","text":"Autoantibody-mediated phagocytosis"}],"answerId":"b","explanation":"IgM antibodies cause agglutination in cold temperatures, leading to acrocyanosis.","kind":"mechanism","origin":"ai"},{"id":"hhl-aiha~ai-4","moduleId":"hhl-aiha","stem":"A 45-year-old man with chronic lymphocytic leukemia develops hemolytic anemia. The direct Coombs test is positive for IgG. What is the most likely type of hemolytic anemia?","options":[{"id":"a","text":"Cold agglutinin disease"},{"id":"b","text":"Warm AIHA"},{"id":"c","text":"Microangiopathic hemolytic anemia"},{"id":"d","text":"Paroxysmal nocturnal hemoglobinuria"}],"answerId":"b","explanation":"Warm AIHA is associated with IgG antibodies and can occur secondary to CLL.","kind":"clinical","origin":"ai"},{"id":"hhl-aiha~ai-5","moduleId":"hhl-aiha","stem":"In a patient with G6PD deficiency, which laboratory test result would help differentiate it from warm AIHA?","options":[{"id":"a","text":"Positive direct Coombs test"},{"id":"b","text":"Presence of Heinz bodies"},{"id":"c","text":"Spherocytes on blood smear"},{"id":"d","text":"Elevated LDH"}],"answerId":"b","explanation":"Heinz bodies are indicative of G6PD deficiency and not seen in warm AIHA.","kind":"integration","linkedModuleIds":["g6pd-oxidative-hemolysis"],"origin":"ai"},{"id":"hhl-aiha~ai-6","moduleId":"hhl-aiha","stem":"A patient with hereditary spherocytosis presents with hemolysis. Which test would confirm a diagnosis of warm AIHA instead?","options":[{"id":"a","text":"Osmotic fragility test"},{"id":"b","text":"Direct Coombs test"},{"id":"c","text":"Peripheral blood smear"},{"id":"d","text":"Haptoglobin level"}],"answerId":"b","explanation":"A positive direct Coombs test confirms warm AIHA, distinguishing it from hereditary spherocytosis.","kind":"integration","linkedModuleIds":["hhl-g6pd-membrane-defects"],"origin":"ai"}],"hhl-hodgkin-lymphoma":[{"id":"hhl-hodgkin-lymphoma~ai-0","moduleId":"hhl-hodgkin-lymphoma","stem":"Which cell type is diagnostic for classical Hodgkin Lymphoma?","options":[{"id":"a","text":"Reed–Sternberg cell"},{"id":"b","text":"Lymphocyte"},{"id":"c","text":"Eosinophil"},{"id":"d","text":"Macrophage"}],"answerId":"a","explanation":"The Reed–Sternberg cell is the diagnostic cell for classical Hodgkin Lymphoma, characterized by its binucleate 'owl-eye' appearance.","kind":"recall","origin":"ai"},{"id":"hhl-hodgkin-lymphoma~ai-1","moduleId":"hhl-hodgkin-lymphoma","stem":"A 25-year-old woman presents with mediastinal mass and cervical lymphadenopathy. Biopsy reveals lacunar cells and broad collagen bands. Which subtype of Hodgkin Lymphoma is most likely?","options":[{"id":"a","text":"Nodular sclerosis"},{"id":"b","text":"Mixed cellularity"},{"id":"c","text":"Lymphocyte-rich"},{"id":"d","text":"Lymphocyte-depleted"}],"answerId":"a","explanation":"Nodular sclerosis is the most common subtype in young women and is characterized by lacunar cells and broad collagen bands.","kind":"clinical","origin":"ai"},{"id":"hhl-hodgkin-lymphoma~ai-2","moduleId":"hhl-hodgkin-lymphoma","stem":"What is the typical pattern of spread for Hodgkin Lymphoma?","options":[{"id":"a","text":"Contiguous node-to-node"},{"id":"b","text":"Non-contiguous extranodal"},{"id":"c","text":"Hematogenous"},{"id":"d","text":"Skip lesions"}],"answerId":"a","explanation":"Hodgkin Lymphoma spreads contiguously from node to node, which is distinct from the non-contiguous spread of Non-Hodgkin Lymphoma.","kind":"recall","origin":"ai"},{"id":"hhl-hodgkin-lymphoma~ai-3","moduleId":"hhl-hodgkin-lymphoma","stem":"A 45-year-old male with HIV presents with generalized lymphadenopathy. Biopsy shows numerous Reed–Sternberg cells. Which subtype of Hodgkin Lymphoma is likely?","options":[{"id":"a","text":"Mixed cellularity"},{"id":"b","text":"Nodular sclerosis"},{"id":"c","text":"Lymphocyte-rich"},{"id":"d","text":"Lymphocyte-depleted"}],"answerId":"a","explanation":"Mixed cellularity subtype is associated with HIV and older age, and shows numerous Reed–Sternberg cells.","kind":"clinical","origin":"ai"},{"id":"hhl-hodgkin-lymphoma~ai-4","moduleId":"hhl-hodgkin-lymphoma","stem":"In Hodgkin Lymphoma, which symptom is associated with cytokine-driven B symptoms?","options":[{"id":"a","text":"Pel–Ebstein fever"},{"id":"b","text":"Painless lymphadenopathy"},{"id":"c","text":"Nodal pain after alcohol"},{"id":"d","text":"Pruritus"}],"answerId":"a","explanation":"Pel–Ebstein fever is a classic B symptom in Hodgkin Lymphoma, driven by cytokine release.","kind":"mechanism","origin":"ai"},{"id":"hhl-hodgkin-lymphoma~ai-5","moduleId":"hhl-hodgkin-lymphoma","stem":"Which finding differentiates Hodgkin Lymphoma from Non-Hodgkin Lymphoma?","options":[{"id":"a","text":"Contiguous spread"},{"id":"b","text":"Extranodal involvement"},{"id":"c","text":"B symptoms"},{"id":"d","text":"Painless lymphadenopathy"}],"answerId":"a","explanation":"Hodgkin Lymphoma is characterized by contiguous spread, unlike Non-Hodgkin Lymphoma which often spreads non-contiguously.","kind":"trap","linkedModuleIds":["hhl-non-hodgkin-lymphoma"],"origin":"ai"},{"id":"hhl-hodgkin-lymphoma~ai-6","moduleId":"hhl-hodgkin-lymphoma","stem":"A biopsy shows a lymph node with reactive hyperplasia and no Reed–Sternberg cells. What is the most likely diagnosis?","options":[{"id":"a","text":"Reactive lymphadenitis"},{"id":"b","text":"Classical Hodgkin Lymphoma"},{"id":"c","text":"Non-Hodgkin Lymphoma"},{"id":"d","text":"Nodular lymphocyte-predominant Hodgkin Lymphoma"}],"answerId":"a","explanation":"Reactive lymphadenitis is characterized by reactive hyperplasia without Reed–Sternberg cells.","kind":"integration","linkedModuleIds":["hhl-lymphadenitis-reactive"],"origin":"ai"}],"hhl-g6pd-membrane-defects":[{"id":"hhl-g6pd-membrane-defects~ai-0","moduleId":"hhl-g6pd-membrane-defects","stem":"A 25-year-old male presents with jaundice and dark urine after eating fava beans. Blood film shows bite cells. What is the most likely diagnosis?","options":[{"id":"a","text":"G6PD deficiency"},{"id":"b","text":"Hereditary spherocytosis"},{"id":"c","text":"Autoimmune hemolytic anemia"},{"id":"d","text":"Sickle cell anemia"}],"answerId":"a","explanation":"G6PD deficiency is triggered by oxidant stress such as fava beans, leading to hemolysis and bite cells on the blood film.","kind":"recall","origin":"ai"},{"id":"hhl-g6pd-membrane-defects~ai-1","moduleId":"hhl-g6pd-membrane-defects","stem":"Which of the following is a common complication of hereditary spherocytosis?","options":[{"id":"a","text":"Aplastic crisis"},{"id":"b","text":"Hemolytic crisis"},{"id":"c","text":"Thrombosis"},{"id":"d","text":"Renal failure"}],"answerId":"a","explanation":"Hereditary spherocytosis can lead to an aplastic crisis, especially after a parvovirus B19 infection.","kind":"recall","origin":"ai"},{"id":"hhl-g6pd-membrane-defects~ai-2","moduleId":"hhl-g6pd-membrane-defects","stem":"A patient with hereditary spherocytosis is likely to have which of the following findings on a blood smear?","options":[{"id":"a","text":"Bite cells"},{"id":"b","text":"Spherocytes"},{"id":"c","text":"Target cells"},{"id":"d","text":"Schistocytes"}],"answerId":"b","explanation":"Spherocytes are characteristic of hereditary spherocytosis due to membrane loss.","kind":"recall","origin":"ai"},{"id":"hhl-g6pd-membrane-defects~ai-3","moduleId":"hhl-g6pd-membrane-defects","stem":"A 30-year-old male with G6PD deficiency is exposed to an oxidative drug. Which of the following would you expect to find on his blood smear?","options":[{"id":"a","text":"Spherocytes"},{"id":"b","text":"Heinz bodies"},{"id":"c","text":"Target cells"},{"id":"d","text":"Schistocytes"}],"answerId":"b","explanation":"Heinz bodies form in G6PD deficiency due to oxidative damage to hemoglobin.","kind":"mechanism","origin":"ai"},{"id":"hhl-g6pd-membrane-defects~ai-4","moduleId":"hhl-g6pd-membrane-defects","stem":"A patient presents with hemolytic anemia and a negative direct Coombs test. Spherocytes are seen on the blood film. What is the most likely diagnosis?","options":[{"id":"a","text":"Hereditary spherocytosis"},{"id":"b","text":"Autoimmune hemolytic anemia"},{"id":"c","text":"Microangiopathic hemolytic anemia"},{"id":"d","text":"Paroxysmal nocturnal hemoglobinuria"}],"answerId":"a","explanation":"Hereditary spherocytosis presents with spherocytes and a negative Coombs test, distinguishing it from autoimmune hemolytic anemia.","kind":"trap","origin":"ai"},{"id":"hhl-g6pd-membrane-defects~ai-5","moduleId":"hhl-g6pd-membrane-defects","stem":"Which test would confirm a diagnosis of hereditary spherocytosis?","options":[{"id":"a","text":"Osmotic fragility test"},{"id":"b","text":"Direct Coombs test"},{"id":"c","text":"G6PD enzyme assay"},{"id":"d","text":"Hemoglobin electrophoresis"}],"answerId":"a","explanation":"The osmotic fragility test is used to diagnose hereditary spherocytosis by demonstrating increased red cell fragility.","kind":"recall","origin":"ai"},{"id":"hhl-g6pd-membrane-defects~ai-6","moduleId":"hhl-g6pd-membrane-defects","stem":"A patient with hereditary spherocytosis is at increased risk for which type of gallstones?","options":[{"id":"a","text":"Cholesterol stones"},{"id":"b","text":"Pigment stones"},{"id":"c","text":"Mixed stones"},{"id":"d","text":"Calcium stones"}],"answerId":"b","explanation":"Chronic hemolysis in hereditary spherocytosis leads to pigment gallstones.","kind":"mechanism","origin":"ai"},{"id":"hhl-g6pd-membrane-defects~ai-7","moduleId":"hhl-g6pd-membrane-defects","stem":"A patient with G6PD deficiency is mistakenly given a sulfonamide antibiotic. Which linked module condition could also cause hemolysis in this patient?","options":[{"id":"a","text":"Lysosomal storage diseases"},{"id":"b","text":"Autoimmune hemolytic anemia"},{"id":"c","text":"Microangiopathic hemolytic anemia"},{"id":"d","text":"Paroxysmal nocturnal hemoglobinuria"}],"answerId":"c","explanation":"Microangiopathic hemolytic anemia can also cause hemolysis, similar to the oxidative stress seen in G6PD deficiency.","kind":"integration","linkedModuleIds":["hhl-maha-pnh"],"origin":"ai"},{"id":"hhl-g6pd-membrane-defects~ai-8","moduleId":"hhl-g6pd-membrane-defects","stem":"A patient with hereditary spherocytosis develops an aplastic crisis. Which linked module condition could exacerbate this crisis?","options":[{"id":"a","text":"Lysosomal storage diseases"},{"id":"b","text":"Autoimmune hemolytic anemia"},{"id":"c","text":"Microangiopathic hemolytic anemia"},{"id":"d","text":"Parvovirus B19 infection"}],"answerId":"d","explanation":"Parvovirus B19 infection can trigger an aplastic crisis in patients with hereditary spherocytosis.","kind":"integration","linkedModuleIds":["add-lysosomal-storage-diseases-pathogenesis-and-clinical-fea"],"origin":"ai"}],"hhl-maha-pnh":[{"id":"hhl-maha-pnh~ai-0","moduleId":"hhl-maha-pnh","stem":"A 35-year-old woman presents with fatigue, jaundice, and dark urine in the morning. Laboratory tests show hemoglobinuria and pancytopenia. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Complement-mediated intravascular hemolysis"},{"id":"b","text":"Mechanical red-cell fragmentation"},{"id":"c","text":"Autoimmune hemolysis"},{"id":"d","text":"Oxidative stress-induced hemolysis"}],"answerId":"a","explanation":"The symptoms and lab findings are characteristic of Paroxysmal Nocturnal Hemoglobinuria (PNH), which involves complement-mediated intravascular hemolysis.","kind":"mechanism","origin":"ai"},{"id":"hhl-maha-pnh~ai-1","moduleId":"hhl-maha-pnh","stem":"A 7-year-old boy develops acute kidney injury and thrombocytopenia after a bout of bloody diarrhea. Schistocytes are seen on blood smear. What is the most likely diagnosis?","options":[{"id":"a","text":"Thrombotic Thrombocytopenic Purpura (TTP)"},{"id":"b","text":"Hemolytic Uremic Syndrome (HUS)"},{"id":"c","text":"Disseminated Intravascular Coagulation (DIC)"},{"id":"d","text":"Paroxysmal Nocturnal Hemoglobinuria (PNH)"}],"answerId":"b","explanation":"The triad of MAHA, thrombocytopenia, and acute kidney injury following bloody diarrhea is indicative of Hemolytic Uremic Syndrome (HUS).","kind":"clinical","origin":"ai"},{"id":"hhl-maha-pnh~ai-2","moduleId":"hhl-maha-pnh","stem":"Which of the following is a key laboratory finding in Thrombotic Thrombocytopenic Purpura (TTP)?","options":[{"id":"a","text":"Increased ADAMTS13 activity"},{"id":"b","text":"Decreased ADAMTS13 activity"},{"id":"c","text":"Positive Coombs test"},{"id":"d","text":"Elevated fibrinogen levels"}],"answerId":"b","explanation":"TTP is characterized by decreased ADAMTS13 activity, leading to the accumulation of large vWF multimers and microthrombi formation.","kind":"recall","origin":"ai"},{"id":"hhl-maha-pnh~ai-3","moduleId":"hhl-maha-pnh","stem":"A patient with suspected Paroxysmal Nocturnal Hemoglobinuria (PNH) undergoes flow cytometry. Which result confirms the diagnosis?","options":[{"id":"a","text":"Presence of schistocytes"},{"id":"b","text":"Absence of CD55 and CD59"},{"id":"c","text":"Positive direct Coombs test"},{"id":"d","text":"Elevated ADAMTS13 levels"}],"answerId":"b","explanation":"PNH is confirmed by flow cytometry showing the absence of CD55 and CD59 on red blood cells due to a PIGA mutation.","kind":"recall","origin":"ai"},{"id":"hhl-maha-pnh~ai-4","moduleId":"hhl-maha-pnh","stem":"A 45-year-old man with a history of recurrent venous thrombosis presents with hemoglobinuria. Which of the following is the most appropriate treatment?","options":[{"id":"a","text":"Eculizumab"},{"id":"b","text":"Plasma exchange"},{"id":"c","text":"Platelet transfusion"},{"id":"d","text":"Corticosteroids"}],"answerId":"a","explanation":"Eculizumab, an anti-C5 antibody, is used to treat PNH by inhibiting complement-mediated hemolysis.","kind":"clinical","origin":"ai"},{"id":"hhl-maha-pnh~ai-5","moduleId":"hhl-maha-pnh","stem":"A 28-year-old woman with a history of autoimmune hemolytic anemia presents with new onset thrombocytopenia and fluctuating neurological symptoms. What is the most likely diagnosis?","options":[{"id":"a","text":"Thrombotic Thrombocytopenic Purpura (TTP)"},{"id":"b","text":"Hemolytic Uremic Syndrome (HUS)"},{"id":"c","text":"Paroxysmal Nocturnal Hemoglobinuria (PNH)"},{"id":"d","text":"Disseminated Intravascular Coagulation (DIC)"}],"answerId":"a","explanation":"The combination of thrombocytopenia and neurological symptoms suggests TTP, especially in the context of autoimmune conditions.","kind":"integration","linkedModuleIds":["hhl-aiha"],"origin":"ai"},{"id":"hhl-maha-pnh~ai-6","moduleId":"hhl-maha-pnh","stem":"A patient with G6PD deficiency presents with hemolysis after taking a new medication. How does this condition differ mechanistically from Paroxysmal Nocturnal Hemoglobinuria (PNH)?","options":[{"id":"a","text":"G6PD deficiency involves oxidative stress-induced hemolysis, whereas PNH involves complement-mediated hemolysis."},{"id":"b","text":"G6PD deficiency involves complement-mediated hemolysis, whereas PNH involves oxidative stress-induced hemolysis."},{"id":"c","text":"Both conditions involve complement-mediated hemolysis."},{"id":"d","text":"Both conditions involve oxidative stress-induced hemolysis."}],"answerId":"a","explanation":"G6PD deficiency leads to oxidative stress-induced hemolysis, while PNH results from complement-mediated hemolysis.","kind":"integration","linkedModuleIds":["g6pd-oxidative-hemolysis"],"origin":"ai"}],"hhl-lymphadenitis-reactive":[{"id":"hhl-lymphadenitis-reactive~ai-0","moduleId":"hhl-lymphadenitis-reactive","stem":"A 35-year-old woman presents with tender, acutely enlarged cervical lymph nodes. Which condition is most likely responsible?","options":[{"id":"a","text":"Acute nonspecific lymphadenitis"},{"id":"b","text":"Chronic nonspecific lymphadenitis"},{"id":"c","text":"Follicular lymphoma"},{"id":"d","text":"Sarcoidosis"}],"answerId":"a","explanation":"Tender, acutely enlarged nodes suggest acute nonspecific lymphadenitis, often due to a local infection.","kind":"clinical","origin":"ai"},{"id":"hhl-lymphadenitis-reactive~ai-1","moduleId":"hhl-lymphadenitis-reactive","stem":"A lymph node biopsy shows florid follicular hyperplasia with tingible-body macrophages and intact mantle zones. What is the most likely diagnosis?","options":[{"id":"a","text":"Reactive hyperplasia"},{"id":"b","text":"Follicular lymphoma"},{"id":"c","text":"Hodgkin lymphoma"},{"id":"d","text":"Non-Hodgkin lymphoma"}],"answerId":"a","explanation":"Reactive hyperplasia is indicated by preserved architecture, polymorphous cell population, and tingible-body macrophages.","kind":"recall","origin":"ai"},{"id":"hhl-lymphadenitis-reactive~ai-2","moduleId":"hhl-lymphadenitis-reactive","stem":"A patient on phenytoin presents with generalized lymphadenopathy. What is the most likely explanation?","options":[{"id":"a","text":"Follicular lymphoma"},{"id":"b","text":"Reactive hyperplasia"},{"id":"c","text":"Hodgkin lymphoma"},{"id":"d","text":"Non-Hodgkin lymphoma"}],"answerId":"b","explanation":"Phenytoin can cause paracortical reactive hyperplasia, mimicking lymphoma but reversible upon drug cessation.","kind":"trap","origin":"ai"},{"id":"hhl-lymphadenitis-reactive~ai-3","moduleId":"hhl-lymphadenitis-reactive","stem":"A lymph node biopsy reveals caseating granulomas. Which condition is most likely?","options":[{"id":"a","text":"Tuberculosis"},{"id":"b","text":"Sarcoidosis"},{"id":"c","text":"Cat-scratch disease"},{"id":"d","text":"Toxoplasmosis"}],"answerId":"a","explanation":"Caseating granulomas are characteristic of tuberculosis.","kind":"recall","origin":"ai"},{"id":"hhl-lymphadenitis-reactive~ai-4","moduleId":"hhl-lymphadenitis-reactive","stem":"A biopsy shows non-caseating granulomas. Which linked condition should be considered?","options":[{"id":"a","text":"Tuberculosis"},{"id":"b","text":"Sarcoidosis"},{"id":"c","text":"Cat-scratch disease"},{"id":"d","text":"Reactive hyperplasia"}],"answerId":"b","explanation":"Non-caseating granulomas are typical of sarcoidosis.","kind":"integration","linkedModuleIds":["add-sarcoidosis-clinical-presentation-and-diagnosis"],"origin":"ai"},{"id":"hhl-lymphadenitis-reactive~ai-5","moduleId":"hhl-lymphadenitis-reactive","stem":"A lymph node biopsy shows sinuses distended by histiocytes. What is the most likely underlying cause?","options":[{"id":"a","text":"Reactive hyperplasia"},{"id":"b","text":"Lymphoma"},{"id":"c","text":"Node draining carcinoma"},{"id":"d","text":"Viral infection"}],"answerId":"c","explanation":"Sinus histiocytosis is often seen in nodes draining a carcinoma.","kind":"mechanism","origin":"ai"},{"id":"hhl-lymphadenitis-reactive~ai-6","moduleId":"hhl-lymphadenitis-reactive","stem":"A 45-year-old male presents with generalized lymphadenopathy and a biopsy shows paracortical expansion with immunoblasts. Which drug is most likely involved?","options":[{"id":"a","text":"Phenytoin"},{"id":"b","text":"Methotrexate"},{"id":"c","text":"Aspirin"},{"id":"d","text":"Ibuprofen"}],"answerId":"a","explanation":"Phenytoin can cause paracortical hyperplasia, mimicking lymphoma.","kind":"trap","origin":"ai"},{"id":"hhl-lymphadenitis-reactive~ai-7","moduleId":"hhl-lymphadenitis-reactive","stem":"A patient with a history of sarcoidosis presents with new lymphadenopathy. Which finding would support a diagnosis of Hodgkin lymphoma?","options":[{"id":"a","text":"Reed-Sternberg cells"},{"id":"b","text":"Non-caseating granulomas"},{"id":"c","text":"Tingible-body macrophages"},{"id":"d","text":"Sinus histiocytosis"}],"answerId":"a","explanation":"Reed-Sternberg cells are characteristic of Hodgkin lymphoma.","kind":"integration","linkedModuleIds":["hhl-hodgkin-lymphoma"],"origin":"ai"}],"hhl-non-hodgkin-lymphoma":[{"id":"hhl-non-hodgkin-lymphoma~ai-0","moduleId":"hhl-non-hodgkin-lymphoma","stem":"Which translocation is associated with Burkitt lymphoma?","options":[{"id":"a","text":"t(8;14)"},{"id":"b","text":"t(14;18)"},{"id":"c","text":"t(11;14)"},{"id":"d","text":"t(9;22)"}],"answerId":"a","explanation":"Burkitt lymphoma is associated with the t(8;14) translocation, leading to MYC overexpression.","kind":"recall","origin":"ai"},{"id":"hhl-non-hodgkin-lymphoma~ai-1","moduleId":"hhl-non-hodgkin-lymphoma","stem":"A 60-year-old patient presents with painless lymphadenopathy and a biopsy shows effaced nodes with monotonous follicles. Which marker is most likely to be overexpressed?","options":[{"id":"a","text":"BCL2"},{"id":"b","text":"MYC"},{"id":"c","text":"Cyclin D1"},{"id":"d","text":"CD5"}],"answerId":"a","explanation":"Follicular lymphoma is characterized by BCL2 overexpression due to the t(14;18) translocation.","kind":"clinical","origin":"ai"},{"id":"hhl-non-hodgkin-lymphoma~ai-2","moduleId":"hhl-non-hodgkin-lymphoma","stem":"What is the primary mechanism by which BCL2 contributes to follicular lymphoma?","options":[{"id":"a","text":"Inhibition of apoptosis"},{"id":"b","text":"Promotion of cell proliferation"},{"id":"c","text":"Induction of angiogenesis"},{"id":"d","text":"Suppression of immune surveillance"}],"answerId":"a","explanation":"BCL2 overexpression inhibits apoptosis, allowing cells to accumulate and form indolent tumors.","kind":"mechanism","origin":"ai"},{"id":"hhl-non-hodgkin-lymphoma~ai-3","moduleId":"hhl-non-hodgkin-lymphoma","stem":"Which of the following lymphomas is most likely to present with a rapidly enlarging mass and is curable with R-CHOP therapy?","options":[{"id":"a","text":"Diffuse large B-cell lymphoma"},{"id":"b","text":"Follicular lymphoma"},{"id":"c","text":"Mantle cell lymphoma"},{"id":"d","text":"Small lymphocytic lymphoma"}],"answerId":"a","explanation":"Diffuse large B-cell lymphoma is aggressive and the most common NHL, often treated successfully with R-CHOP.","kind":"clinical","origin":"ai"},{"id":"hhl-non-hodgkin-lymphoma~ai-4","moduleId":"hhl-non-hodgkin-lymphoma","stem":"A patient with a history of H. pylori infection presents with gastric lymphoid infiltrate. Which type of lymphoma is most likely?","options":[{"id":"a","text":"MALT lymphoma"},{"id":"b","text":"Burkitt lymphoma"},{"id":"c","text":"Mantle cell lymphoma"},{"id":"d","text":"Diffuse large B-cell lymphoma"}],"answerId":"a","explanation":"MALT lymphoma is associated with H. pylori infection and can regress with its eradication.","kind":"clinical","origin":"ai"},{"id":"hhl-non-hodgkin-lymphoma~ai-5","moduleId":"hhl-non-hodgkin-lymphoma","stem":"Which feature distinguishes Non-Hodgkin Lymphoma from Hodgkin Lymphoma in terms of spread?","options":[{"id":"a","text":"Non-contiguous spread"},{"id":"b","text":"Contiguous spread"},{"id":"c","text":"Exclusively nodal involvement"},{"id":"d","text":"Presence of Reed-Sternberg cells"}],"answerId":"a","explanation":"Non-Hodgkin Lymphoma often spreads non-contiguously and can involve extranodal sites.","kind":"trap","origin":"ai"},{"id":"hhl-non-hodgkin-lymphoma~ai-6","moduleId":"hhl-non-hodgkin-lymphoma","stem":"A patient with Down syndrome has an increased risk of which type of lymphoma?","options":[{"id":"a","text":"Acute lymphoblastic leukemia"},{"id":"b","text":"Diffuse large B-cell lymphoma"},{"id":"c","text":"Follicular lymphoma"},{"id":"d","text":"Mantle cell lymphoma"}],"answerId":"a","explanation":"Patients with Down syndrome have an increased risk of acute lymphoblastic leukemia.","kind":"integration","linkedModuleIds":["autosomal-trisomies"],"origin":"ai"},{"id":"hhl-non-hodgkin-lymphoma~ai-7","moduleId":"hhl-non-hodgkin-lymphoma","stem":"Which genetic alteration is shared between Burkitt lymphoma and some cases of acute leukemia?","options":[{"id":"a","text":"MYC translocation"},{"id":"b","text":"BCR-ABL fusion"},{"id":"c","text":"BCL2 overexpression"},{"id":"d","text":"Cyclin D1 overexpression"}],"answerId":"a","explanation":"Both Burkitt lymphoma and some acute leukemias involve MYC translocations.","kind":"integration","linkedModuleIds":["hhl-acute-leukemia-approach"],"origin":"ai"}],"hhl-hematinics-esa":[{"id":"hhl-hematinics-esa~ai-0","moduleId":"hhl-hematinics-esa","stem":"A 45-year-old woman with iron deficiency anemia starts oral ferrous sulfate. What is the expected hematological response within one week?","options":[{"id":"a","text":"Reticulocytosis"},{"id":"b","text":"Normalization of hemoglobin"},{"id":"c","text":"Resolution of anemia symptoms"},{"id":"d","text":"Increase in serum ferritin"}],"answerId":"a","explanation":"Reticulocytosis is expected within 5-7 days as the bone marrow responds to iron supplementation.","kind":"recall","origin":"ai"},{"id":"hhl-hematinics-esa~ai-1","moduleId":"hhl-hematinics-esa","stem":"Which of the following is a potential adverse effect of erythropoiesis-stimulating agents (ESAs) if hemoglobin levels are normalized?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Hyperkalemia"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Hypotension"}],"answerId":"a","explanation":"Normalizing hemoglobin with ESAs can lead to hypertension and increased risk of thrombosis.","kind":"mechanism","origin":"ai"},{"id":"hhl-hematinics-esa~ai-2","moduleId":"hhl-hematinics-esa","stem":"A patient with macrocytic anemia is treated with folic acid alone. What complication might occur if vitamin B12 deficiency is present?","options":[{"id":"a","text":"Neurological deterioration"},{"id":"b","text":"Immediate anemia resolution"},{"id":"c","text":"Iron overload"},{"id":"d","text":"Hypokalemia"}],"answerId":"a","explanation":"Folic acid can correct the anemia but allows neurological damage from untreated B12 deficiency to progress.","kind":"trap","origin":"ai"},{"id":"hhl-hematinics-esa~ai-3","moduleId":"hhl-hematinics-esa","stem":"In the management of anemia of chronic kidney disease (CKD), why is it important not to fully normalize hemoglobin levels with ESAs?","options":[{"id":"a","text":"Increased risk of stroke"},{"id":"b","text":"Increased risk of infection"},{"id":"c","text":"Increased risk of gastrointestinal bleeding"},{"id":"d","text":"Increased risk of hypoglycemia"}],"answerId":"a","explanation":"Normalizing hemoglobin with ESAs in CKD increases the risk of stroke and thrombosis.","kind":"trap","origin":"ai"},{"id":"hhl-hematinics-esa~ai-4","moduleId":"hhl-hematinics-esa","stem":"A 30-year-old pregnant woman is advised to take folic acid. What is the primary reason for this recommendation?","options":[{"id":"a","text":"Prevention of neural tube defects"},{"id":"b","text":"Prevention of gestational diabetes"},{"id":"c","text":"Prevention of hypertension"},{"id":"d","text":"Prevention of anemia"}],"answerId":"a","explanation":"Folic acid supplementation in pregnancy is primarily to prevent neural tube defects in the fetus.","kind":"recall","origin":"ai"},{"id":"hhl-hematinics-esa~ai-5","moduleId":"hhl-hematinics-esa","stem":"A patient on oral iron therapy reports black stools. What is the most likely cause?","options":[{"id":"a","text":"Unabsorbed iron in the GI tract"},{"id":"b","text":"Gastrointestinal bleeding"},{"id":"c","text":"Biliary obstruction"},{"id":"d","text":"Liver dysfunction"}],"answerId":"a","explanation":"Black stools are a common side effect of oral iron due to unabsorbed iron in the gastrointestinal tract.","kind":"clinical","origin":"ai"},{"id":"hhl-hematinics-esa~ai-6","moduleId":"hhl-hematinics-esa","stem":"How does the administration of erythropoiesis-stimulating agents (ESAs) relate to iron stores in the body?","options":[{"id":"a","text":"ESAs require adequate iron stores to be effective"},{"id":"b","text":"ESAs deplete iron stores"},{"id":"c","text":"ESAs increase iron absorption"},{"id":"d","text":"ESAs function independently of iron levels"}],"answerId":"a","explanation":"ESAs stimulate erythropoiesis, which requires sufficient iron stores to produce new red blood cells.","kind":"integration","linkedModuleIds":["add-hematopoiesis-and-erythropoiesis"],"origin":"ai"},{"id":"hhl-hematinics-esa~ai-7","moduleId":"hhl-hematinics-esa","stem":"A patient with thalassemia is receiving iron chelation therapy. How might this affect the use of erythropoiesis-stimulating agents (ESAs)?","options":[{"id":"a","text":"Chelation reduces iron overload, allowing effective ESA use"},{"id":"b","text":"Chelation increases ESA side effects"},{"id":"c","text":"Chelation negates ESA effects"},{"id":"d","text":"Chelation is contraindicated with ESAs"}],"answerId":"a","explanation":"Iron chelation reduces iron overload, which can enhance the effectiveness of ESAs in managing anemia.","kind":"integration","linkedModuleIds":["hhl-iron-chelators"],"origin":"ai"}],"hhl-iron-chelators":[{"id":"hhl-iron-chelators~ai-0","moduleId":"hhl-iron-chelators","stem":"Which iron chelator is administered parenterally and is associated with retinal and auditory toxicity?","options":[{"id":"a","text":"Deferoxamine"},{"id":"b","text":"Deferiprone"},{"id":"c","text":"Deferasirox"},{"id":"d","text":"Ferriprox"}],"answerId":"a","explanation":"Deferoxamine is given parenterally and can cause retinal and auditory toxicity.","kind":"recall","origin":"ai"},{"id":"hhl-iron-chelators~ai-1","moduleId":"hhl-iron-chelators","stem":"A patient on deferiprone presents with fever and sore throat. What is the most appropriate next step?","options":[{"id":"a","text":"Continue deferiprone and monitor symptoms"},{"id":"b","text":"Switch to deferasirox"},{"id":"c","text":"Stop deferiprone immediately"},{"id":"d","text":"Reduce the dose of deferiprone"}],"answerId":"c","explanation":"Fever and sore throat in a patient on deferiprone may indicate agranulocytosis, necessitating immediate cessation of the drug.","kind":"clinical","origin":"ai"},{"id":"hhl-iron-chelators~ai-2","moduleId":"hhl-iron-chelators","stem":"Which test is most crucial to assess cardiac iron loading in patients with transfusion-dependent thalassemia?","options":[{"id":"a","text":"Serum ferritin"},{"id":"b","text":"Cardiac MRI T2*"},{"id":"c","text":"Liver biopsy"},{"id":"d","text":"Serum iron"}],"answerId":"b","explanation":"Cardiac MRI T2* is essential for assessing cardiac iron loading, as ferritin can be misleading.","kind":"trap","origin":"ai"},{"id":"hhl-iron-chelators~ai-3","moduleId":"hhl-iron-chelators","stem":"A patient on deferasirox shows rising creatinine levels. What is the likely cause?","options":[{"id":"a","text":"Hepatic toxicity"},{"id":"b","text":"Nephrotoxicity"},{"id":"c","text":"Cardiac iron overload"},{"id":"d","text":"Agranulocytosis"}],"answerId":"b","explanation":"Deferasirox can cause dose-related nephrotoxicity, indicated by rising creatinine levels.","kind":"mechanism","origin":"ai"},{"id":"hhl-iron-chelators~ai-4","moduleId":"hhl-iron-chelators","stem":"Which iron chelator is uniquely effective at removing cardiac iron?","options":[{"id":"a","text":"Deferoxamine"},{"id":"b","text":"Deferiprone"},{"id":"c","text":"Deferasirox"},{"id":"d","text":"Ferriprox"}],"answerId":"b","explanation":"Deferiprone is particularly effective at removing cardiac iron.","kind":"recall","origin":"ai"},{"id":"hhl-iron-chelators~ai-5","moduleId":"hhl-iron-chelators","stem":"In a patient with transfusion-dependent thalassemia, which parameter indicates the need to intensify iron chelation therapy?","options":[{"id":"a","text":"Serum ferritin < 500 ng/mL"},{"id":"b","text":"Cardiac MRI T2* > 20 ms"},{"id":"c","text":"Serum ferritin > 1000 ng/mL"},{"id":"d","text":"Normal liver function tests"}],"answerId":"c","explanation":"A serum ferritin > 1000 ng/mL suggests a high total-body iron burden, indicating the need for intensified chelation.","kind":"clinical","origin":"ai"},{"id":"hhl-iron-chelators~ai-6","moduleId":"hhl-iron-chelators","stem":"A patient with chronic kidney disease is on erythropoiesis-stimulating agents and requires iron chelation. Which agent is most suitable considering renal function?","options":[{"id":"a","text":"Deferoxamine"},{"id":"b","text":"Deferiprone"},{"id":"c","text":"Deferasirox"},{"id":"d","text":"Ferriprox"}],"answerId":"b","explanation":"Deferiprone is preferred as it does not have the nephrotoxic risk associated with deferasirox.","kind":"integration","linkedModuleIds":["hhl-hematinics-esa"],"origin":"ai"},{"id":"hhl-iron-chelators~ai-7","moduleId":"hhl-iron-chelators","stem":"Which iron chelator is most likely to cause agranulocytosis, requiring regular CBC monitoring?","options":[{"id":"a","text":"Deferoxamine"},{"id":"b","text":"Deferiprone"},{"id":"c","text":"Deferasirox"},{"id":"d","text":"Ferriprox"}],"answerId":"b","explanation":"Deferiprone can cause agranulocytosis, necessitating regular CBC monitoring.","kind":"recall","origin":"ai"},{"id":"hhl-iron-chelators~ai-8","moduleId":"hhl-iron-chelators","stem":"A patient with anemia of chronic disease is on erythropoiesis-stimulating agents and develops iron overload. Which chelator should be avoided due to potential renal toxicity?","options":[{"id":"a","text":"Deferoxamine"},{"id":"b","text":"Deferiprone"},{"id":"c","text":"Deferasirox"},{"id":"d","text":"Ferriprox"}],"answerId":"c","explanation":"Deferasirox is associated with renal toxicity and should be used cautiously in patients with renal issues.","kind":"integration","linkedModuleIds":["hhl-hematinics-esa"],"origin":"ai"}],"hhl-thrombolytics-antifibrinolytics":[{"id":"hhl-thrombolytics-antifibrinolytics~ai-0","moduleId":"hhl-thrombolytics-antifibrinolytics","stem":"Which enzyme is directly responsible for clot dissolution in fibrinolytic therapy?","options":[{"id":"a","text":"Plasmin"},{"id":"b","text":"Thrombin"},{"id":"c","text":"Fibrinogen"},{"id":"d","text":"Factor Xa"}],"answerId":"a","explanation":"Plasmin is the enzyme that lyses fibrin and dissolves clots.","kind":"recall","origin":"ai"},{"id":"hhl-thrombolytics-antifibrinolytics~ai-1","moduleId":"hhl-thrombolytics-antifibrinolytics","stem":"A patient develops a rash and hypotension after receiving streptokinase. What is the most likely cause?","options":[{"id":"a","text":"Antigenicity of streptokinase"},{"id":"b","text":"Excessive plasmin activity"},{"id":"c","text":"Allergic reaction to plasmin"},{"id":"d","text":"Fibrinogen depletion"}],"answerId":"a","explanation":"Streptokinase is antigenic and can cause allergic reactions due to its bacterial origin.","kind":"mechanism","origin":"ai"},{"id":"hhl-thrombolytics-antifibrinolytics~ai-2","moduleId":"hhl-thrombolytics-antifibrinolytics","stem":"Which of the following is a contraindication for thrombolytic therapy?","options":[{"id":"a","text":"Recent surgery"},{"id":"b","text":"Chronic hypertension"},{"id":"c","text":"Stable angina"},{"id":"d","text":"Controlled diabetes"}],"answerId":"a","explanation":"Recent surgery increases the risk of bleeding, making thrombolytic therapy contraindicated.","kind":"trap","origin":"ai"},{"id":"hhl-thrombolytics-antifibrinolytics~ai-3","moduleId":"hhl-thrombolytics-antifibrinolytics","stem":"A patient with acute ischemic stroke is given alteplase. What is a serious potential complication?","options":[{"id":"a","text":"Intracranial hemorrhage"},{"id":"b","text":"Myocardial infarction"},{"id":"c","text":"Pulmonary embolism"},{"id":"d","text":"Deep vein thrombosis"}],"answerId":"a","explanation":"Intracranial hemorrhage is a serious complication of thrombolytic therapy.","kind":"clinical","origin":"ai"},{"id":"hhl-thrombolytics-antifibrinolytics~ai-4","moduleId":"hhl-thrombolytics-antifibrinolytics","stem":"Tranexamic acid is used to reduce bleeding by which mechanism?","options":[{"id":"a","text":"Blocking plasminogen binding to fibrin"},{"id":"b","text":"Inhibiting thrombin"},{"id":"c","text":"Activating factor X"},{"id":"d","text":"Enhancing platelet aggregation"}],"answerId":"a","explanation":"Tranexamic acid blocks plasminogen binding to fibrin, stabilizing clots.","kind":"mechanism","origin":"ai"},{"id":"hhl-thrombolytics-antifibrinolytics~ai-5","moduleId":"hhl-thrombolytics-antifibrinolytics","stem":"A patient on warfarin therapy is experiencing excessive bleeding. Which antifibrinolytic could be considered to stabilize clots?","options":[{"id":"a","text":"Tranexamic acid"},{"id":"b","text":"Alteplase"},{"id":"c","text":"Streptokinase"},{"id":"d","text":"Aspirin"}],"answerId":"a","explanation":"Tranexamic acid is an antifibrinolytic that can stabilize clots by inhibiting plasminogen.","kind":"integration","linkedModuleIds":["hhl-anticoagulants"],"origin":"ai"},{"id":"hhl-thrombolytics-antifibrinolytics~ai-6","moduleId":"hhl-thrombolytics-antifibrinolytics","stem":"Which of the following drugs is least likely to cause an allergic reaction upon re-exposure?","options":[{"id":"a","text":"Alteplase"},{"id":"b","text":"Streptokinase"},{"id":"c","text":"Tranexamic acid"},{"id":"d","text":"Aminocaproic acid"}],"answerId":"a","explanation":"Alteplase is a recombinant protein and less likely to cause allergic reactions compared to streptokinase.","kind":"trap","origin":"ai"},{"id":"hhl-thrombolytics-antifibrinolytics~ai-7","moduleId":"hhl-thrombolytics-antifibrinolytics","stem":"In a patient with a history of myocardial infarction, which drug would be used to prevent clot formation by inhibiting platelet aggregation?","options":[{"id":"a","text":"Aspirin"},{"id":"b","text":"Tranexamic acid"},{"id":"c","text":"Alteplase"},{"id":"d","text":"Streptokinase"}],"answerId":"a","explanation":"Aspirin inhibits platelet aggregation and is used to prevent clot formation.","kind":"integration","linkedModuleIds":["hhl-antiplatelets"],"origin":"ai"}],"hhl-cll":[{"id":"hhl-cll~ai-0","moduleId":"hhl-cll","stem":"A 70-year-old man presents with fatigue and lymphadenopathy. Blood smear shows small mature lymphocytes and smudge cells. Flow cytometry reveals CD5+, CD23+, CD19/CD20+ B cells. What is the most likely diagnosis?","options":[{"id":"a","text":"Chronic Lymphocytic Leukemia"},{"id":"b","text":"Mantle Cell Lymphoma"},{"id":"c","text":"Acute Lymphoblastic Leukemia"},{"id":"d","text":"Hairy Cell Leukemia"}],"answerId":"a","explanation":"The immunophenotype CD5+, CD23+ is characteristic of CLL, distinguishing it from mantle cell lymphoma which is CD23−.","kind":"recall","origin":"ai"},{"id":"hhl-cll~ai-1","moduleId":"hhl-cll","stem":"Which of the following is a common complication of Chronic Lymphocytic Leukemia?","options":[{"id":"a","text":"Hypercalcemia"},{"id":"b","text":"Autoimmune hemolytic anemia"},{"id":"c","text":"Polycythemia"},{"id":"d","text":"Thrombocytosis"}],"answerId":"b","explanation":"Autoimmune hemolytic anemia is a known complication of CLL, often presenting with a positive direct antiglobulin test.","kind":"recall","origin":"ai"},{"id":"hhl-cll~ai-2","moduleId":"hhl-cll","stem":"A patient with CLL develops anemia. The direct antiglobulin test is positive. What is the most appropriate initial treatment?","options":[{"id":"a","text":"Chemotherapy"},{"id":"b","text":"Steroids"},{"id":"c","text":"Erythropoietin"},{"id":"d","text":"Iron supplements"}],"answerId":"b","explanation":"Steroids are used to treat autoimmune hemolytic anemia, which is a complication of CLL.","kind":"clinical","origin":"ai"},{"id":"hhl-cll~ai-3","moduleId":"hhl-cll","stem":"In CLL, which of the following findings on a blood smear is characteristic?","options":[{"id":"a","text":"Auer rods"},{"id":"b","text":"Smudge cells"},{"id":"c","text":"Reed-Sternberg cells"},{"id":"d","text":"Howell-Jolly bodies"}],"answerId":"b","explanation":"Smudge cells are fragile lymphocytes that appear crushed on the blood smear, typical in CLL.","kind":"recall","origin":"ai"},{"id":"hhl-cll~ai-4","moduleId":"hhl-cll","stem":"A 65-year-old woman with CLL presents with recurrent bacterial infections. What is the underlying cause?","options":[{"id":"a","text":"Neutropenia"},{"id":"b","text":"Hypogammaglobulinemia"},{"id":"c","text":"Splenomegaly"},{"id":"d","text":"Thrombocytopenia"}],"answerId":"b","explanation":"Hypogammaglobulinemia in CLL leads to recurrent infections due to decreased antibody production.","kind":"mechanism","origin":"ai"},{"id":"hhl-cll~ai-5","moduleId":"hhl-cll","stem":"A patient with CLL is found to have CD5+ B cells. Why is it important to also check for CD23?","options":[{"id":"a","text":"To differentiate from mantle cell lymphoma"},{"id":"b","text":"To confirm T-cell lineage"},{"id":"c","text":"To assess treatment response"},{"id":"d","text":"To evaluate for acute transformation"}],"answerId":"a","explanation":"CD23 helps differentiate CLL from mantle cell lymphoma, which is CD23−.","kind":"trap","origin":"ai"},{"id":"hhl-cll~ai-6","moduleId":"hhl-cll","stem":"A patient with CLL is being considered for targeted therapy. Which linked module provides information on targeted agents used in leukemia?","options":[{"id":"a","text":"Wilson's Disease: Genetic Basis and Clinical Manifestations"},{"id":"b","text":"Targeted Agents Across Leukemia"},{"id":"c","text":"Multiple Myeloma"},{"id":"d","text":"Myeloproliferative Neoplasms"}],"answerId":"b","explanation":"The linked module 'Targeted Agents Across Leukemia' provides information on targeted therapies applicable to CLL.","kind":"integration","linkedModuleIds":["hhl-targeted-therapy-classes"],"origin":"ai"},{"id":"hhl-cll~ai-7","moduleId":"hhl-cll","stem":"Which of the following conditions shares a similar pathophysiological mechanism of clonal cell accumulation with CLL?","options":[{"id":"a","text":"Wilson's Disease"},{"id":"b","text":"Multiple Myeloma"},{"id":"c","text":"Polycythemia Vera"},{"id":"d","text":"Acute Myeloid Leukemia"}],"answerId":"b","explanation":"Multiple Myeloma, like CLL, involves clonal proliferation of a specific cell line, though it is plasma cells instead of B lymphocytes.","kind":"integration","linkedModuleIds":["hhl-multiple-myeloma"],"origin":"ai"}],"hhl-anticoagulants":[{"id":"hhl-anticoagulants~ai-0","moduleId":"hhl-anticoagulants","stem":"Which anticoagulant is most appropriate for immediate anticoagulation in a patient with a new deep vein thrombosis?","options":[{"id":"a","text":"Unfractionated heparin"},{"id":"b","text":"Warfarin"},{"id":"c","text":"Aspirin"},{"id":"d","text":"Rivaroxaban"}],"answerId":"a","explanation":"Unfractionated heparin provides rapid anticoagulation and is suitable for initial management of venous thromboembolism.","kind":"clinical","origin":"ai"},{"id":"hhl-anticoagulants~ai-1","moduleId":"hhl-anticoagulants","stem":"A patient on warfarin presents with a rising INR. What is the most likely mechanism?","options":[{"id":"a","text":"Inhibition of factor Xa"},{"id":"b","text":"Inhibition of thrombin"},{"id":"c","text":"Inhibition of vitamin K epoxide reductase"},{"id":"d","text":"Direct inhibition of factor IIa"}],"answerId":"c","explanation":"Warfarin inhibits vitamin K epoxide reductase, leading to decreased synthesis of vitamin K-dependent clotting factors.","kind":"mechanism","origin":"ai"},{"id":"hhl-anticoagulants~ai-2","moduleId":"hhl-anticoagulants","stem":"A patient develops skin necrosis shortly after starting warfarin. What is the underlying cause?","options":[{"id":"a","text":"Excessive inhibition of thrombin"},{"id":"b","text":"Rapid drop in protein C levels"},{"id":"c","text":"Allergic reaction to warfarin"},{"id":"d","text":"Inhibition of factor Xa"}],"answerId":"b","explanation":"Warfarin causes an early drop in protein C, a natural anticoagulant, leading to a hypercoagulable state and skin necrosis.","kind":"trap","origin":"ai"},{"id":"hhl-anticoagulants~ai-3","moduleId":"hhl-anticoagulants","stem":"Which anticoagulant is contraindicated in patients with mechanical heart valves?","options":[{"id":"a","text":"Dabigatran"},{"id":"b","text":"Warfarin"},{"id":"c","text":"Unfractionated heparin"},{"id":"d","text":"Rivaroxaban"}],"answerId":"a","explanation":"Dabigatran is contraindicated in patients with mechanical heart valves due to increased risk of thromboembolic events.","kind":"recall","origin":"ai"},{"id":"hhl-anticoagulants~ai-4","moduleId":"hhl-anticoagulants","stem":"A patient on unfractionated heparin shows a significant drop in platelet count. What is the appropriate action?","options":[{"id":"a","text":"Continue heparin and monitor"},{"id":"b","text":"Transfuse platelets"},{"id":"c","text":"Stop heparin and start a non-heparin anticoagulant"},{"id":"d","text":"Switch to low molecular weight heparin"}],"answerId":"c","explanation":"This is likely heparin-induced thrombocytopenia (HIT), requiring cessation of heparin and initiation of a non-heparin anticoagulant.","kind":"trap","origin":"ai"},{"id":"hhl-anticoagulants~ai-5","moduleId":"hhl-anticoagulants","stem":"Which anticoagulant requires monitoring of aPTT to assess therapeutic levels?","options":[{"id":"a","text":"Rivaroxaban"},{"id":"b","text":"Warfarin"},{"id":"c","text":"Unfractionated heparin"},{"id":"d","text":"Apixaban"}],"answerId":"c","explanation":"Unfractionated heparin requires aPTT monitoring to ensure therapeutic anticoagulation.","kind":"recall","origin":"ai"},{"id":"hhl-anticoagulants~ai-6","moduleId":"hhl-anticoagulants","stem":"How does aspirin differ from anticoagulants in its mechanism of action?","options":[{"id":"a","text":"Inhibits thrombin"},{"id":"b","text":"Inhibits platelet aggregation"},{"id":"c","text":"Inhibits factor Xa"},{"id":"d","text":"Inhibits vitamin K"}],"answerId":"b","explanation":"Aspirin inhibits platelet aggregation, whereas anticoagulants target the coagulation cascade.","kind":"integration","linkedModuleIds":["hhl-antiplatelets"],"origin":"ai"},{"id":"hhl-anticoagulants~ai-7","moduleId":"hhl-anticoagulants","stem":"Which drug is used to reverse the effects of dabigatran in case of major bleeding?","options":[{"id":"a","text":"Protamine sulfate"},{"id":"b","text":"Vitamin K"},{"id":"c","text":"Idarucizumab"},{"id":"d","text":"Andexanet alfa"}],"answerId":"c","explanation":"Idarucizumab is a specific reversal agent for dabigatran, a direct thrombin inhibitor.","kind":"recall","origin":"ai"},{"id":"hhl-anticoagulants~ai-8","moduleId":"hhl-anticoagulants","stem":"In the context of anticoagulation, what is the primary therapeutic target of fibrinolytics?","options":[{"id":"a","text":"Platelet aggregation"},{"id":"b","text":"Fibrin clot breakdown"},{"id":"c","text":"Thrombin inhibition"},{"id":"d","text":"Factor Xa inhibition"}],"answerId":"b","explanation":"Fibrinolytics target fibrin clot breakdown, which is distinct from the anticoagulation cascade.","kind":"integration","linkedModuleIds":["hhl-thrombolytics-antifibrinolytics"],"origin":"ai"}],"hhl-antiplatelets":[{"id":"hhl-antiplatelets~ai-0","moduleId":"hhl-antiplatelets","stem":"Which antiplatelet drug irreversibly inhibits COX-1, reducing thromboxane A2 production?","options":[{"id":"a","text":"Aspirin"},{"id":"b","text":"Clopidogrel"},{"id":"c","text":"Ticagrelor"},{"id":"d","text":"Dipyridamole"}],"answerId":"a","explanation":"Aspirin irreversibly acetylates COX-1, leading to decreased thromboxane A2 production for the platelet lifespan.","kind":"recall","origin":"ai"},{"id":"hhl-antiplatelets~ai-1","moduleId":"hhl-antiplatelets","stem":"A patient on clopidogrel shows poor response. Which factor is most likely responsible?","options":[{"id":"a","text":"CYP2C19 loss-of-function"},{"id":"b","text":"Non-adherence"},{"id":"c","text":"Renal impairment"},{"id":"d","text":"Concurrent aspirin use"}],"answerId":"a","explanation":"Clopidogrel is a prodrug that requires activation by CYP2C19; loss-of-function alleles reduce its effectiveness.","kind":"mechanism","origin":"ai"},{"id":"hhl-antiplatelets~ai-2","moduleId":"hhl-antiplatelets","stem":"A patient develops dyspnea after starting an antiplatelet drug. Which drug is most likely responsible?","options":[{"id":"a","text":"Aspirin"},{"id":"b","text":"Clopidogrel"},{"id":"c","text":"Ticagrelor"},{"id":"d","text":"Prasugrel"}],"answerId":"c","explanation":"Ticagrelor can cause dyspnea due to adenosine-mediated effects from reversible P2Y12 blockade.","kind":"recall","origin":"ai"},{"id":"hhl-antiplatelets~ai-3","moduleId":"hhl-antiplatelets","stem":"Which antiplatelet drug is contraindicated in patients with a history of stroke or TIA?","options":[{"id":"a","text":"Aspirin"},{"id":"b","text":"Clopidogrel"},{"id":"c","text":"Prasugrel"},{"id":"d","text":"Ticagrelor"}],"answerId":"c","explanation":"Prasugrel is contraindicated in patients with a history of stroke or TIA due to increased bleeding risk.","kind":"recall","origin":"ai"},{"id":"hhl-antiplatelets~ai-4","moduleId":"hhl-antiplatelets","stem":"A patient on aspirin presents with prolonged bleeding time but normal PT and aPTT. What does this indicate?","options":[{"id":"a","text":"Aspirin overdose"},{"id":"b","text":"Qualitative platelet defect"},{"id":"c","text":"Coagulation factor deficiency"},{"id":"d","text":"Thrombocytopenia"}],"answerId":"b","explanation":"Aspirin causes a qualitative platelet defect, leading to prolonged bleeding time without affecting PT or aPTT.","kind":"trap","origin":"ai"},{"id":"hhl-antiplatelets~ai-5","moduleId":"hhl-antiplatelets","stem":"Which drug combination is used for dual antiplatelet therapy after ACS or stenting?","options":[{"id":"a","text":"Aspirin and clopidogrel"},{"id":"b","text":"Aspirin and warfarin"},{"id":"c","text":"Clopidogrel and heparin"},{"id":"d","text":"Ticagrelor and dabigatran"}],"answerId":"a","explanation":"Aspirin combined with a P2Y12 inhibitor like clopidogrel is standard for dual antiplatelet therapy after ACS or stenting.","kind":"recall","origin":"ai"},{"id":"hhl-antiplatelets~ai-6","moduleId":"hhl-antiplatelets","stem":"A patient with a history of venous thromboembolism is prescribed an antiplatelet drug. Which module's content should be reviewed for appropriate management?","options":[{"id":"a","text":"Anticoagulants"},{"id":"b","text":"Fibrinolytics & Antifibrinolytics"},{"id":"c","text":"Antiplatelet Drugs"},{"id":"d","text":"Lipid-lowering Agents"}],"answerId":"a","explanation":"Venous thromboembolism is managed with anticoagulants, not antiplatelet drugs, as they target different clot types.","kind":"integration","linkedModuleIds":["hhl-anticoagulants"],"origin":"ai"},{"id":"hhl-antiplatelets~ai-7","moduleId":"hhl-antiplatelets","stem":"In the context of a high-risk PCI, which class of antiplatelet drugs is administered intravenously?","options":[{"id":"a","text":"P2Y12 inhibitors"},{"id":"b","text":"GP IIb/IIIa inhibitors"},{"id":"c","text":"COX-1 inhibitors"},{"id":"d","text":"Adenosine reuptake inhibitors"}],"answerId":"b","explanation":"GP IIb/IIIa inhibitors are administered intravenously during high-risk PCI to block the final common aggregation step.","kind":"recall","origin":"ai"},{"id":"hhl-antiplatelets~ai-8","moduleId":"hhl-antiplatelets","stem":"A patient on anticoagulant therapy requires secondary stroke prevention. Which antiplatelet drug can be added?","options":[{"id":"a","text":"Aspirin"},{"id":"b","text":"Clopidogrel"},{"id":"c","text":"Dipyridamole"},{"id":"d","text":"Ticagrelor"}],"answerId":"c","explanation":"Dipyridamole can be used with aspirin for secondary stroke prevention, especially in patients on anticoagulants.","kind":"integration","linkedModuleIds":["hhl-anticoagulants"],"origin":"ai"}],"hhl-multiple-myeloma":[{"id":"hhl-multiple-myeloma~ai-0","moduleId":"hhl-multiple-myeloma","stem":"Which of the following is a characteristic finding in multiple myeloma but not in MGUS?","options":[{"id":"a","text":"M-protein in serum"},{"id":"b","text":"CRAB end-organ damage"},{"id":"c","text":"Less than 10% plasma cells in marrow"},{"id":"d","text":"Absence of lytic bone lesions"}],"answerId":"b","explanation":"CRAB end-organ damage is specific to multiple myeloma and distinguishes it from MGUS.","kind":"recall","origin":"ai"},{"id":"hhl-multiple-myeloma~ai-1","moduleId":"hhl-multiple-myeloma","stem":"A patient with multiple myeloma presents with severe back pain and neurological deficits. What is the most likely cause?","options":[{"id":"a","text":"Vertebral collapse and cord compression"},{"id":"b","text":"Osteoblastic bone lesions"},{"id":"c","text":"Renal failure"},{"id":"d","text":"Hypercalcemia"}],"answerId":"a","explanation":"Vertebral collapse and cord compression can occur due to lytic lesions in the spine, leading to neurological deficits.","kind":"clinical","origin":"ai"},{"id":"hhl-multiple-myeloma~ai-2","moduleId":"hhl-multiple-myeloma","stem":"Which laboratory finding is most indicative of multiple myeloma?","options":[{"id":"a","text":"Elevated alkaline phosphatase"},{"id":"b","text":"High ESR with rouleaux formation"},{"id":"c","text":"Decreased serum calcium"},{"id":"d","text":"Increased white blood cell count"}],"answerId":"b","explanation":"High ESR with rouleaux formation is indicative of multiple myeloma due to high paraprotein levels.","kind":"mechanism","origin":"ai"},{"id":"hhl-multiple-myeloma~ai-3","moduleId":"hhl-multiple-myeloma","stem":"A bone scan is performed on a patient suspected of having multiple myeloma. Which finding is expected?","options":[{"id":"a","text":"Osteoblastic lesions"},{"id":"b","text":"Negative bone scan"},{"id":"c","text":"Diffuse uptake"},{"id":"d","text":"Increased uptake in sclerotic areas"}],"answerId":"b","explanation":"Multiple myeloma causes lytic lesions that are often bone-scan negative.","kind":"trap","origin":"ai"},{"id":"hhl-multiple-myeloma~ai-4","moduleId":"hhl-multiple-myeloma","stem":"In the context of multiple myeloma, what is the primary cause of renal impairment?","options":[{"id":"a","text":"Hypercalcemia"},{"id":"b","text":"Light-chain cast nephropathy"},{"id":"c","text":"Hyperuricemia"},{"id":"d","text":"Dehydration"}],"answerId":"b","explanation":"Renal impairment in multiple myeloma is primarily due to light-chain cast nephropathy.","kind":"mechanism","origin":"ai"},{"id":"hhl-multiple-myeloma~ai-5","moduleId":"hhl-multiple-myeloma","stem":"A patient with chronic lymphocytic leukemia (CLL) presents with an M-protein spike. What additional finding would suggest progression to multiple myeloma?","options":[{"id":"a","text":"Lymphocytosis"},{"id":"b","text":"CRAB end-organ damage"},{"id":"c","text":"Splenomegaly"},{"id":"d","text":"Lymphadenopathy"}],"answerId":"b","explanation":"CRAB end-organ damage would suggest progression to multiple myeloma in a patient with CLL and an M-protein spike.","kind":"integration","linkedModuleIds":["hhl-cll"],"origin":"ai"},{"id":"hhl-multiple-myeloma~ai-6","moduleId":"hhl-multiple-myeloma","stem":"A patient with myeloproliferative neoplasm (MPN) develops bone pain and hypercalcemia. Which additional test would confirm multiple myeloma?","options":[{"id":"a","text":"Bone marrow biopsy showing >10% plasma cells"},{"id":"b","text":"Elevated leukocyte alkaline phosphatase"},{"id":"c","text":"Increased red cell mass"},{"id":"d","text":"Presence of JAK2 mutation"}],"answerId":"a","explanation":"Bone marrow biopsy showing >10% plasma cells confirms multiple myeloma.","kind":"integration","linkedModuleIds":["hhl-mpn"],"origin":"ai"}],"hhl-coagulation-disorders":[{"id":"hhl-coagulation-disorders~ai-0","moduleId":"hhl-coagulation-disorders","stem":"A 10-year-old boy presents with recurrent joint bleeding. Lab tests show an isolated increase in aPTT with normal PT, platelet count, and bleeding time. What is the most likely diagnosis?","options":[{"id":"a","text":"Hemophilia A"},{"id":"b","text":"Von Willebrand Disease"},{"id":"c","text":"Vitamin K deficiency"},{"id":"d","text":"Disseminated Intravascular Coagulation (DIC)"}],"answerId":"a","explanation":"The isolated increase in aPTT with normal PT and bleeding time suggests a deficiency in the intrinsic pathway, typical of Hemophilia A.","kind":"clinical","origin":"ai"},{"id":"hhl-coagulation-disorders~ai-1","moduleId":"hhl-coagulation-disorders","stem":"A patient with hemophilia A is found to have a prolonged aPTT that does not correct with a mixing study. What is the most likely explanation?","options":[{"id":"a","text":"Presence of a factor VIII inhibitor"},{"id":"b","text":"Factor VIII deficiency"},{"id":"c","text":"Vitamin K deficiency"},{"id":"d","text":"Liver disease"}],"answerId":"a","explanation":"A mixing study that fails to correct indicates the presence of an inhibitor, such as a factor VIII inhibitor.","kind":"mechanism","origin":"ai"},{"id":"hhl-coagulation-disorders~ai-2","moduleId":"hhl-coagulation-disorders","stem":"Which of the following laboratory findings is most consistent with vitamin K deficiency?","options":[{"id":"a","text":"Increased PT with normal aPTT"},{"id":"b","text":"Increased aPTT with normal PT"},{"id":"c","text":"Increased PT and aPTT"},{"id":"d","text":"Normal PT and aPTT"}],"answerId":"c","explanation":"Vitamin K deficiency affects factors II, VII, IX, and X, leading to increased PT initially, followed by increased aPTT.","kind":"recall","origin":"ai"},{"id":"hhl-coagulation-disorders~ai-3","moduleId":"hhl-coagulation-disorders","stem":"A 25-year-old male with a history of hemophilia B presents with spontaneous hemarthrosis. Which factor concentrate should be administered?","options":[{"id":"a","text":"Factor VIII concentrate"},{"id":"b","text":"Factor IX concentrate"},{"id":"c","text":"Factor VII concentrate"},{"id":"d","text":"Fresh frozen plasma"}],"answerId":"b","explanation":"Hemophilia B is due to factor IX deficiency, so factor IX concentrate is the appropriate treatment.","kind":"recall","origin":"ai"},{"id":"hhl-coagulation-disorders~ai-4","moduleId":"hhl-coagulation-disorders","stem":"A newborn presents with bleeding and laboratory tests show increased PT followed by increased aPTT. What is the most likely underlying cause?","options":[{"id":"a","text":"Vitamin K deficiency"},{"id":"b","text":"Hemophilia A"},{"id":"c","text":"Liver disease"},{"id":"d","text":"Von Willebrand Disease"}],"answerId":"a","explanation":"Vitamin K deficiency in newborns presents with increased PT initially due to factor VII deficiency, followed by increased aPTT.","kind":"clinical","origin":"ai"},{"id":"hhl-coagulation-disorders~ai-5","moduleId":"hhl-coagulation-disorders","stem":"A patient with a history of gastric surgery presents with bleeding and increased PT. Which linked module could provide insight into the underlying cause?","options":[{"id":"a","text":"Gastric Accommodation, Mixing & Retropulsion"},{"id":"b","text":"Molecular Basis of Hemostasis and Coagulation Disorders"},{"id":"c","text":"Primary Hemostatic Defects"},{"id":"d","text":"DIC & Bleeding-vs-Thrombosis Approach"}],"answerId":"a","explanation":"Gastric surgery can affect vitamin K absorption, leading to coagulation issues; the linked module on gastric function may provide insights.","kind":"integration","linkedModuleIds":["gastric-accommodation-mixing"],"origin":"ai"},{"id":"hhl-coagulation-disorders~ai-6","moduleId":"hhl-coagulation-disorders","stem":"A patient with a prolonged aPTT and normal PT is suspected to have a primary hemostatic defect. Which linked module should be consulted for further understanding?","options":[{"id":"a","text":"Gastric Accommodation, Mixing & Retropulsion"},{"id":"b","text":"Molecular Basis of Hemostasis and Coagulation Disorders"},{"id":"c","text":"Primary Hemostatic Defects"},{"id":"d","text":"DIC & Bleeding-vs-Thrombosis Approach"}],"answerId":"c","explanation":"Primary hemostatic defects are covered in the linked module on Primary Hemostatic Defects, which can help differentiate from coagulation factor disorders.","kind":"integration","linkedModuleIds":["hhl-primary-hemostasis-disorders"],"origin":"ai"}],"hhl-acute-leukemia-approach":[{"id":"hhl-acute-leukemia-approach~ai-0","moduleId":"hhl-acute-leukemia-approach","stem":"A 7-year-old boy presents with fever, pallor, and petechiae. Blood tests reveal anemia, neutropenia, and thrombocytopenia. What is the most likely diagnosis?","options":[{"id":"a","text":"Acute lymphoblastic leukemia"},{"id":"b","text":"Chronic myeloid leukemia"},{"id":"c","text":"Aplastic anemia"},{"id":"d","text":"Infectious mononucleosis"}],"answerId":"a","explanation":"The triad of anemia, neutropenia, and thrombocytopenia suggests marrow failure, typical of acute leukemia.","kind":"clinical","origin":"ai"},{"id":"hhl-acute-leukemia-approach~ai-1","moduleId":"hhl-acute-leukemia-approach","stem":"A patient with acute leukemia develops fever and a WBC count of 200 cells/µL. What is the immediate next step in management?","options":[{"id":"a","text":"Start broad-spectrum antibiotics"},{"id":"b","text":"Obtain blood cultures and wait for results"},{"id":"c","text":"Administer granulocyte colony-stimulating factor"},{"id":"d","text":"Perform a bone marrow biopsy"}],"answerId":"a","explanation":"Febrile neutropenia is an emergency requiring immediate empirical antibiotic treatment.","kind":"trap","origin":"ai"},{"id":"hhl-acute-leukemia-approach~ai-2","moduleId":"hhl-acute-leukemia-approach","stem":"Which of the following laboratory findings is characteristic of tumor lysis syndrome?","options":[{"id":"a","text":"Hypercalcemia"},{"id":"b","text":"Hypokalemia"},{"id":"c","text":"Hypophosphatemia"},{"id":"d","text":"Hyperuricemia"}],"answerId":"d","explanation":"Tumor lysis syndrome is characterized by hyperuricemia, hyperkalemia, hyperphosphatemia, and hypocalcemia.","kind":"mechanism","origin":"ai"},{"id":"hhl-acute-leukemia-approach~ai-3","moduleId":"hhl-acute-leukemia-approach","stem":"A patient with acute myeloid leukemia presents with dyspnea and confusion. His WBC count is 120,000/µL. What is the most likely cause of his symptoms?","options":[{"id":"a","text":"Tumor lysis syndrome"},{"id":"b","text":"Leukostasis"},{"id":"c","text":"Febrile neutropenia"},{"id":"d","text":"Disseminated intravascular coagulation"}],"answerId":"b","explanation":"Leukostasis due to hyperleukocytosis can cause respiratory and neurological symptoms.","kind":"recall","origin":"ai"},{"id":"hhl-acute-leukemia-approach~ai-4","moduleId":"hhl-acute-leukemia-approach","stem":"In diagnosing acute leukemia, which of the following is used to determine the lineage of the blasts?","options":[{"id":"a","text":"Peripheral blood smear"},{"id":"b","text":"Flow cytometry"},{"id":"c","text":"Cytogenetic analysis"},{"id":"d","text":"Bone marrow biopsy"}],"answerId":"b","explanation":"Flow cytometry is used to identify cell surface markers that determine the lineage of leukemia cells.","kind":"recall","origin":"ai"},{"id":"hhl-acute-leukemia-approach~ai-5","moduleId":"hhl-acute-leukemia-approach","stem":"A patient with suspected acute leukemia has blasts expressing MPO and CD33. Which type of leukemia is most likely?","options":[{"id":"a","text":"Acute lymphoblastic leukemia"},{"id":"b","text":"Acute myeloid leukemia"},{"id":"c","text":"Chronic lymphocytic leukemia"},{"id":"d","text":"Chronic myeloid leukemia"}],"answerId":"b","explanation":"MPO and CD33 are markers for myeloid lineage, indicating acute myeloid leukemia.","kind":"integration","linkedModuleIds":["hhl-aml"],"origin":"ai"},{"id":"hhl-acute-leukemia-approach~ai-6","moduleId":"hhl-acute-leukemia-approach","stem":"Which diagnostic method is essential for confirming the diagnosis of acute lymphoblastic leukemia?","options":[{"id":"a","text":"Bone marrow biopsy"},{"id":"b","text":"Peripheral blood smear"},{"id":"c","text":"Cytogenetic analysis"},{"id":"d","text":"Immunohistochemistry"}],"answerId":"a","explanation":"A bone marrow biopsy is necessary to confirm the presence of ≥20% blasts for the diagnosis of acute leukemia.","kind":"integration","linkedModuleIds":["diagnostic-pathology-methods"],"origin":"ai"}],"hhl-primary-hemostasis-disorders":[{"id":"hhl-primary-hemostasis-disorders~ai-0","moduleId":"hhl-primary-hemostasis-disorders","stem":"A 25-year-old woman presents with frequent nosebleeds and heavy menstrual bleeding. Laboratory tests show a normal platelet count, prolonged bleeding time, and increased aPTT. What is the most likely diagnosis?","options":[{"id":"a","text":"von Willebrand disease"},{"id":"b","text":"Hemophilia A"},{"id":"c","text":"Immune thrombocytopenic purpura"},{"id":"d","text":"Disseminated intravascular coagulation"}],"answerId":"a","explanation":"The combination of mucocutaneous bleeding, normal platelet count, prolonged bleeding time, and increased aPTT suggests von Willebrand disease.","kind":"clinical","origin":"ai"},{"id":"hhl-primary-hemostasis-disorders~ai-1","moduleId":"hhl-primary-hemostasis-disorders","stem":"Which of the following is a characteristic finding in immune thrombocytopenic purpura (ITP)?","options":[{"id":"a","text":"Isolated thrombocytopenia"},{"id":"b","text":"Prolonged PT"},{"id":"c","text":"Prolonged aPTT"},{"id":"d","text":"Decreased fibrinogen"}],"answerId":"a","explanation":"ITP is characterized by isolated thrombocytopenia with normal PT and aPTT.","kind":"recall","origin":"ai"},{"id":"hhl-primary-hemostasis-disorders~ai-2","moduleId":"hhl-primary-hemostasis-disorders","stem":"A patient with suspected primary hemostatic defect shows prolonged bleeding time with a normal platelet count. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Platelet production defect"},{"id":"b","text":"Qualitative platelet defect"},{"id":"c","text":"Coagulation factor deficiency"},{"id":"d","text":"Increased platelet destruction"}],"answerId":"b","explanation":"Prolonged bleeding time with a normal platelet count suggests a qualitative platelet defect or von Willebrand disease.","kind":"mechanism","origin":"ai"},{"id":"hhl-primary-hemostasis-disorders~ai-3","moduleId":"hhl-primary-hemostasis-disorders","stem":"Which treatment is appropriate for a patient with type 1 von Willebrand disease experiencing a bleeding episode?","options":[{"id":"a","text":"Desmopressin"},{"id":"b","text":"Platelet transfusion"},{"id":"c","text":"Fresh frozen plasma"},{"id":"d","text":"Vitamin K"}],"answerId":"a","explanation":"Desmopressin is used to treat bleeding episodes in type 1 von Willebrand disease by increasing vWF release.","kind":"recall","origin":"ai"},{"id":"hhl-primary-hemostasis-disorders~ai-4","moduleId":"hhl-primary-hemostasis-disorders","stem":"A 30-year-old male with hemophilia A presents with joint pain and swelling. Which laboratory finding is most likely?","options":[{"id":"a","text":"Prolonged aPTT"},{"id":"b","text":"Prolonged PT"},{"id":"c","text":"Decreased platelet count"},{"id":"d","text":"Increased bleeding time"}],"answerId":"a","explanation":"Hemophilia A is characterized by a prolonged aPTT due to factor VIII deficiency.","kind":"integration","linkedModuleIds":["hhl-coagulation-disorders"],"origin":"ai"},{"id":"hhl-primary-hemostasis-disorders~ai-5","moduleId":"hhl-primary-hemostasis-disorders","stem":"A patient presents with petechiae and purpura. Lab tests show low platelets, normal PT, and normal aPTT. What is the most likely diagnosis?","options":[{"id":"a","text":"Immune thrombocytopenic purpura"},{"id":"b","text":"von Willebrand disease"},{"id":"c","text":"Hemophilia B"},{"id":"d","text":"Vitamin K deficiency"}],"answerId":"a","explanation":"The presentation of petechiae, purpura, and isolated low platelets is consistent with ITP.","kind":"clinical","origin":"ai"},{"id":"hhl-primary-hemostasis-disorders~ai-6","moduleId":"hhl-primary-hemostasis-disorders","stem":"A 40-year-old female with a history of easy bruising and menorrhagia has a normal platelet count and prolonged bleeding time. What additional test would help confirm von Willebrand disease?","options":[{"id":"a","text":"Ristocetin cofactor activity"},{"id":"b","text":"Factor VIII level"},{"id":"c","text":"PT"},{"id":"d","text":"D-dimer"}],"answerId":"a","explanation":"Ristocetin cofactor activity is specifically used to diagnose von Willebrand disease.","kind":"trap","origin":"ai"},{"id":"hhl-primary-hemostasis-disorders~ai-7","moduleId":"hhl-primary-hemostasis-disorders","stem":"A patient with disseminated intravascular coagulation (DIC) presents with bleeding. Which of the following lab findings is expected?","options":[{"id":"a","text":"Decreased fibrinogen"},{"id":"b","text":"Normal PT"},{"id":"c","text":"Increased platelet count"},{"id":"d","text":"Decreased aPTT"}],"answerId":"a","explanation":"DIC is characterized by decreased fibrinogen due to consumption coagulopathy.","kind":"integration","linkedModuleIds":["hhl-dic-thrombosis"],"origin":"ai"}],"hhl-all":[{"id":"hhl-all~ai-0","moduleId":"hhl-all","stem":"A 4-year-old boy presents with bone pain, fever, and bruising. Blood smear shows TdT-positive, MPO-negative blasts. What is the most likely diagnosis?","options":[{"id":"a","text":"Acute Myeloid Leukemia"},{"id":"b","text":"Acute Lymphoblastic Leukemia"},{"id":"c","text":"Chronic Myeloid Leukemia"},{"id":"d","text":"Chronic Lymphocytic Leukemia"}],"answerId":"b","explanation":"TdT-positive, MPO-negative blasts are characteristic of lymphoblasts, indicating Acute Lymphoblastic Leukemia.","kind":"recall","origin":"ai"},{"id":"hhl-all~ai-1","moduleId":"hhl-all","stem":"Which cytogenetic abnormality in Acute Lymphoblastic Leukemia is associated with a good prognosis in children?","options":[{"id":"a","text":"t(9;22) BCR-ABL"},{"id":"b","text":"t(12;21) ETV6-RUNX1"},{"id":"c","text":"t(4;11) KMT2A/MLL"},{"id":"d","text":"t(8;21) RUNX1-RUNX1T1"}],"answerId":"b","explanation":"The t(12;21) ETV6-RUNX1 translocation is associated with a good prognosis in pediatric ALL.","kind":"recall","origin":"ai"},{"id":"hhl-all~ai-2","moduleId":"hhl-all","stem":"A 15-year-old male presents with respiratory distress and a large anterior mediastinal mass. What is the most likely diagnosis?","options":[{"id":"a","text":"T-Cell Acute Lymphoblastic Leukemia"},{"id":"b","text":"Hodgkin's Lymphoma"},{"id":"c","text":"Non-Hodgkin's Lymphoma"},{"id":"d","text":"Acute Myeloid Leukemia"}],"answerId":"a","explanation":"An anterior mediastinal mass in an adolescent male is classically associated with T-ALL.","kind":"clinical","origin":"ai"},{"id":"hhl-all~ai-3","moduleId":"hhl-all","stem":"Why is CNS-directed prophylaxis necessary in the treatment of Acute Lymphoblastic Leukemia?","options":[{"id":"a","text":"Systemic chemotherapy clears all disease"},{"id":"b","text":"CNS is a pharmacological sanctuary"},{"id":"c","text":"CNS involvement is rare"},{"id":"d","text":"CNS-directed therapy is ineffective"}],"answerId":"b","explanation":"The CNS is a sanctuary site where systemic chemotherapy penetrates poorly, necessitating dedicated prophylaxis.","kind":"trap","origin":"ai"},{"id":"hhl-all~ai-4","moduleId":"hhl-all","stem":"Which of the following is a sanctuary site for relapse in Acute Lymphoblastic Leukemia?","options":[{"id":"a","text":"Bone marrow"},{"id":"b","text":"Liver"},{"id":"c","text":"CNS"},{"id":"d","text":"Lung"}],"answerId":"c","explanation":"The CNS is a known sanctuary site for ALL, requiring specific prophylactic treatment.","kind":"recall","origin":"ai"},{"id":"hhl-all~ai-5","moduleId":"hhl-all","stem":"A child with ALL presents with cranial nerve palsy. What does this indicate?","options":[{"id":"a","text":"Bone marrow relapse"},{"id":"b","text":"CNS involvement"},{"id":"c","text":"Testicular relapse"},{"id":"d","text":"Hepatosplenomegaly"}],"answerId":"b","explanation":"Cranial nerve palsy in ALL suggests CNS involvement, a common site for relapse.","kind":"clinical","origin":"ai"},{"id":"hhl-all~ai-6","moduleId":"hhl-all","stem":"In the context of ALL, which diagnostic method is used to identify TdT positivity?","options":[{"id":"a","text":"Flow cytometry"},{"id":"b","text":"ELISA"},{"id":"c","text":"Western blot"},{"id":"d","text":"PCR"}],"answerId":"a","explanation":"Flow cytometry is used to identify TdT positivity in lymphoblasts.","kind":"integration","linkedModuleIds":["diagnostic-pathology-methods"],"origin":"ai"},{"id":"hhl-all~ai-7","moduleId":"hhl-all","stem":"Which targeted therapy is added to the treatment regimen for Philadelphia chromosome-positive ALL?","options":[{"id":"a","text":"Imatinib"},{"id":"b","text":"Rituximab"},{"id":"c","text":"Daratumumab"},{"id":"d","text":"Bortezomib"}],"answerId":"a","explanation":"Imatinib, a tyrosine kinase inhibitor, is used in Ph-positive ALL to target the BCR-ABL fusion protein.","kind":"integration","linkedModuleIds":["hhl-targeted-therapy-classes"],"origin":"ai"}],"hhl-aml":[{"id":"hhl-aml~ai-0","moduleId":"hhl-aml","stem":"A 67-year-old male presents with fatigue, recurrent infections, and bleeding gums. Bone marrow biopsy shows 25% blasts with Auer rods. What is the most likely diagnosis?","options":[{"id":"a","text":"Acute Myeloid Leukemia"},{"id":"b","text":"Chronic Myeloid Leukemia"},{"id":"c","text":"Acute Lymphoblastic Leukemia"},{"id":"d","text":"Chronic Lymphocytic Leukemia"}],"answerId":"a","explanation":"The presence of Auer rods and ≥20% blasts in the marrow is diagnostic of Acute Myeloid Leukemia.","kind":"recall","origin":"ai"},{"id":"hhl-aml~ai-1","moduleId":"hhl-aml","stem":"Which cytogenetic abnormality is associated with acute promyelocytic leukemia (APL) and requires immediate treatment with ATRA?","options":[{"id":"a","text":"t(15;17)"},{"id":"b","text":"t(9;22)"},{"id":"c","text":"t(8;21)"},{"id":"d","text":"inv(16)"}],"answerId":"a","explanation":"APL is characterized by the t(15;17) translocation and requires urgent treatment with ATRA due to the risk of DIC.","kind":"recall","origin":"ai"},{"id":"hhl-aml~ai-2","moduleId":"hhl-aml","stem":"A patient with suspected APL presents with severe bleeding. What is the most appropriate initial management step?","options":[{"id":"a","text":"Wait for cytogenetic confirmation"},{"id":"b","text":"Start ATRA immediately"},{"id":"c","text":"Administer broad-spectrum antibiotics"},{"id":"d","text":"Perform a bone marrow transplant"}],"answerId":"b","explanation":"Immediate initiation of ATRA is crucial in suspected APL to reverse the coagulopathy and prevent fatal bleeding.","kind":"trap","origin":"ai"},{"id":"hhl-aml~ai-3","moduleId":"hhl-aml","stem":"A 45-year-old female presents with gingival hypertrophy and skin nodules. Bone marrow biopsy reveals MPO-positive blasts. Which subtype of AML is most likely?","options":[{"id":"a","text":"Acute promyelocytic leukemia"},{"id":"b","text":"Monocytic AML"},{"id":"c","text":"Megakaryoblastic AML"},{"id":"d","text":"Erythroid AML"}],"answerId":"b","explanation":"Monocytic AML is associated with tissue infiltration, including gingival hypertrophy and skin involvement.","kind":"clinical","origin":"ai"},{"id":"hhl-aml~ai-4","moduleId":"hhl-aml","stem":"Which of the following findings is pathognomonic for Acute Myeloid Leukemia?","options":[{"id":"a","text":"Auer rods"},{"id":"b","text":"TdT positivity"},{"id":"c","text":"Philadelphia chromosome"},{"id":"d","text":"BCR-ABL fusion"}],"answerId":"a","explanation":"Auer rods are needle-like inclusions in blasts that are pathognomonic for AML.","kind":"recall","origin":"ai"},{"id":"hhl-aml~ai-5","moduleId":"hhl-aml","stem":"A 60-year-old male with AML presents with a greenish mass in the orbit. What is the most likely diagnosis?","options":[{"id":"a","text":"Chloroma"},{"id":"b","text":"Lymphoma"},{"id":"c","text":"Metastatic carcinoma"},{"id":"d","text":"Sarcoidosis"}],"answerId":"a","explanation":"A chloroma, or myeloid sarcoma, is an extramedullary manifestation of AML, often appearing as a greenish mass.","kind":"clinical","origin":"ai"},{"id":"hhl-aml~ai-6","moduleId":"hhl-aml","stem":"In the context of acute leukemia, which marker differentiates AML from ALL?","options":[{"id":"a","text":"MPO positivity"},{"id":"b","text":"CD19 positivity"},{"id":"c","text":"TdT positivity"},{"id":"d","text":"Philadelphia chromosome"}],"answerId":"a","explanation":"MPO positivity is indicative of myeloid lineage, distinguishing AML from ALL.","kind":"mechanism","linkedModuleIds":["hhl-all"],"origin":"ai"},{"id":"hhl-aml~ai-7","moduleId":"hhl-aml","stem":"A patient with APL is started on ATRA therapy. Which module would provide further information on the mechanism of action of ATRA?","options":[{"id":"a","text":"hhl-targeted-therapy-classes"},{"id":"b","text":"hhl-acute-leukemia-approach"},{"id":"c","text":"hhl-all"},{"id":"d","text":"hhl-aml"}],"answerId":"a","explanation":"The 'hhl-targeted-therapy-classes' module covers targeted agents like ATRA used in leukemia treatment.","kind":"integration","linkedModuleIds":["hhl-targeted-therapy-classes"],"origin":"ai"}],"hhl-abo-system":[{"id":"hhl-abo-system~ai-0","moduleId":"hhl-abo-system","stem":"Which blood group is considered the universal red-cell donor?","options":[{"id":"a","text":"Group O"},{"id":"b","text":"Group A"},{"id":"c","text":"Group B"},{"id":"d","text":"Group AB"}],"answerId":"a","explanation":"Group O red cells lack A and B antigens, making them compatible with all other blood groups.","kind":"recall","origin":"ai"},{"id":"hhl-abo-system~ai-1","moduleId":"hhl-abo-system","stem":"A patient experiences fever, loin pain, and red urine minutes after a transfusion. What is the most likely mechanism?","options":[{"id":"a","text":"Delayed hemolytic reaction"},{"id":"b","text":"Febrile non-hemolytic reaction"},{"id":"c","text":"IgM anti-A/anti-B mediated intravascular hemolysis"},{"id":"d","text":"Allergic reaction"}],"answerId":"c","explanation":"IgM anti-A/anti-B antibodies fix complement, leading to immediate intravascular hemolysis.","kind":"mechanism","origin":"ai"},{"id":"hhl-abo-system~ai-2","moduleId":"hhl-abo-system","stem":"What discrepancy might you find in a Bombay phenotype individual during blood typing?","options":[{"id":"a","text":"Forward and reverse groups agree"},{"id":"b","text":"Forward group shows AB, reverse group shows O"},{"id":"c","text":"Forward group shows O, reverse group agglutinates all O donor cells"},{"id":"d","text":"Forward group shows A, reverse group shows B"}],"answerId":"c","explanation":"Bombay phenotype individuals lack the H antigen and produce anti-H, causing agglutination with O donor cells.","kind":"recall","origin":"ai"},{"id":"hhl-abo-system~ai-3","moduleId":"hhl-abo-system","stem":"Which blood group is the universal plasma donor?","options":[{"id":"a","text":"Group O"},{"id":"b","text":"Group A"},{"id":"c","text":"Group B"},{"id":"d","text":"Group AB"}],"answerId":"d","explanation":"Group AB plasma lacks anti-A and anti-B antibodies, making it compatible with all other blood groups.","kind":"trap","origin":"ai"},{"id":"hhl-abo-system~ai-4","moduleId":"hhl-abo-system","stem":"In an ABO typing test, the forward and reverse groups disagree. What could be a possible cause?","options":[{"id":"a","text":"Correct blood type"},{"id":"b","text":"Presence of cold antibodies"},{"id":"c","text":"Technical error in typing"},{"id":"d","text":"Presence of Rh antibodies"}],"answerId":"b","explanation":"Cold antibodies can cause discrepancies in ABO typing by agglutinating at lower temperatures.","kind":"clinical","origin":"ai"},{"id":"hhl-abo-system~ai-5","moduleId":"hhl-abo-system","stem":"A patient with a known Bombay phenotype requires a blood transfusion. Which blood type is compatible?","options":[{"id":"a","text":"Group O"},{"id":"b","text":"Bombay phenotype"},{"id":"c","text":"Group A"},{"id":"d","text":"Group AB"}],"answerId":"b","explanation":"Bombay phenotype individuals can only receive blood from other Bombay phenotype donors due to anti-H antibodies.","kind":"recall","origin":"ai"},{"id":"hhl-abo-system~ai-6","moduleId":"hhl-abo-system","stem":"How does the ABO blood group system relate to hemolytic transfusion reactions?","options":[{"id":"a","text":"ABO incompatibility causes delayed hemolysis"},{"id":"b","text":"ABO incompatibility causes immediate intravascular hemolysis"},{"id":"c","text":"ABO compatibility prevents all transfusion reactions"},{"id":"d","text":"ABO incompatibility is irrelevant in transfusion reactions"}],"answerId":"b","explanation":"ABO incompatibility leads to immediate intravascular hemolysis due to IgM antibodies fixing complement.","kind":"integration","linkedModuleIds":["hhl-hemolytic-transfusion-reactions"],"origin":"ai"},{"id":"hhl-abo-system~ai-7","moduleId":"hhl-abo-system","stem":"What is the implication of ABO blood group system in hemolytic disease of the newborn (HDN)?","options":[{"id":"a","text":"ABO incompatibility never causes HDN"},{"id":"b","text":"ABO incompatibility causes severe HDN"},{"id":"c","text":"ABO incompatibility can cause mild HDN"},{"id":"d","text":"ABO incompatibility is the primary cause of HDN"}],"answerId":"c","explanation":"ABO incompatibility can cause mild HDN, but it is less severe compared to Rh incompatibility.","kind":"integration","linkedModuleIds":["hhl-hdn"],"origin":"ai"}],"hhl-targeted-therapy-classes":[{"id":"hhl-targeted-therapy-classes~ai-0","moduleId":"hhl-targeted-therapy-classes","stem":"Which targeted therapy is most appropriate for a patient with chronic myeloid leukemia (CML) with a BCR-ABL fusion gene?","options":[{"id":"a","text":"Imatinib"},{"id":"b","text":"Rituximab"},{"id":"c","text":"Venetoclax"},{"id":"d","text":"ATRA"}],"answerId":"a","explanation":"Imatinib is a BCR-ABL tyrosine kinase inhibitor used specifically for CML.","kind":"recall","origin":"ai"},{"id":"hhl-targeted-therapy-classes~ai-1","moduleId":"hhl-targeted-therapy-classes","stem":"A patient with acute promyelocytic leukemia (APL) develops fever, dyspnea, and weight gain after starting treatment. What is the most likely cause?","options":[{"id":"a","text":"Tumor lysis syndrome"},{"id":"b","text":"Differentiation syndrome"},{"id":"c","text":"Cytokine release syndrome"},{"id":"d","text":"Sepsis"}],"answerId":"b","explanation":"These symptoms are indicative of differentiation syndrome, a known complication of ATRA therapy in APL.","kind":"clinical","origin":"ai"},{"id":"hhl-targeted-therapy-classes~ai-2","moduleId":"hhl-targeted-therapy-classes","stem":"Which of the following is a potential side effect of venetoclax therapy in CLL?","options":[{"id":"a","text":"Neurotoxicity"},{"id":"b","text":"Tumor lysis syndrome"},{"id":"c","text":"Differentiation syndrome"},{"id":"d","text":"Cardiotoxicity"}],"answerId":"b","explanation":"Venetoclax can cause tumor lysis syndrome due to rapid apoptosis of leukemic cells.","kind":"mechanism","origin":"ai"},{"id":"hhl-targeted-therapy-classes~ai-3","moduleId":"hhl-targeted-therapy-classes","stem":"What is the primary target of rituximab in the treatment of B-cell non-Hodgkin lymphoma?","options":[{"id":"a","text":"CD19"},{"id":"b","text":"CD20"},{"id":"c","text":"CD33"},{"id":"d","text":"FLT3"}],"answerId":"b","explanation":"Rituximab targets CD20, a surface antigen on B-cells.","kind":"recall","origin":"ai"},{"id":"hhl-targeted-therapy-classes~ai-4","moduleId":"hhl-targeted-therapy-classes","stem":"A patient with AML has a FLT3-ITD mutation. Which targeted therapy is appropriate?","options":[{"id":"a","text":"Midostaurin"},{"id":"b","text":"Ibrutinib"},{"id":"c","text":"Blinatumomab"},{"id":"d","text":"Gemtuzumab ozogamicin"}],"answerId":"a","explanation":"Midostaurin is used to target FLT3 mutations in AML.","kind":"recall","linkedModuleIds":["hhl-aml"],"origin":"ai"},{"id":"hhl-targeted-therapy-classes~ai-5","moduleId":"hhl-targeted-therapy-classes","stem":"A patient develops high fever and hypotension days after receiving CAR-T therapy. What is the most appropriate initial management?","options":[{"id":"a","text":"Start broad-spectrum antibiotics"},{"id":"b","text":"Administer tocilizumab"},{"id":"c","text":"Initiate high-dose steroids"},{"id":"d","text":"Perform immediate intubation"}],"answerId":"b","explanation":"Tocilizumab is used to manage cytokine release syndrome, a common complication of CAR-T therapy.","kind":"trap","origin":"ai"},{"id":"hhl-targeted-therapy-classes~ai-6","moduleId":"hhl-targeted-therapy-classes","stem":"A patient with B-ALL is being considered for blinatumomab therapy. What is a significant risk associated with this treatment?","options":[{"id":"a","text":"Tumor lysis syndrome"},{"id":"b","text":"Cytokine release syndrome"},{"id":"c","text":"Differentiation syndrome"},{"id":"d","text":"Cardiotoxicity"}],"answerId":"b","explanation":"Blinatumomab can cause cytokine release syndrome due to its T-cell engaging mechanism.","kind":"mechanism","linkedModuleIds":["hhl-all"],"origin":"ai"}],"hhl-tki-cml":[{"id":"hhl-tki-cml~ai-0","moduleId":"hhl-tki-cml","stem":"What is the primary mechanism by which imatinib exerts its effect in chronic myeloid leukemia (CML)?","options":[{"id":"a","text":"Inhibition of the BCR-ABL ATP-binding pocket"},{"id":"b","text":"Induction of apoptosis in leukemic cells"},{"id":"c","text":"Inhibition of DNA synthesis"},{"id":"d","text":"Stimulation of the immune system"}],"answerId":"a","explanation":"Imatinib specifically inhibits the ATP-binding pocket of the BCR-ABL tyrosine kinase, blocking its oncogenic activity.","kind":"mechanism","origin":"ai"},{"id":"hhl-tki-cml~ai-1","moduleId":"hhl-tki-cml","stem":"Which laboratory test is most appropriate for monitoring the response of CML to tyrosine kinase inhibitor therapy?","options":[{"id":"a","text":"Complete blood count"},{"id":"b","text":"Bone marrow biopsy"},{"id":"c","text":"Quantitative BCR-ABL transcript by RT-PCR"},{"id":"d","text":"Serum lactate dehydrogenase"}],"answerId":"c","explanation":"The quantitative BCR-ABL transcript by RT-PCR is used to monitor molecular response and detect resistance.","kind":"trap","origin":"ai"},{"id":"hhl-tki-cml~ai-2","moduleId":"hhl-tki-cml","stem":"A patient on imatinib for CML presents with periorbital edema and muscle cramps. What is the most likely cause?","options":[{"id":"a","text":"Imatinib adverse effects"},{"id":"b","text":"Progression of CML"},{"id":"c","text":"Infection"},{"id":"d","text":"Renal failure"}],"answerId":"a","explanation":"Periorbital edema and muscle cramps are known adverse effects of imatinib.","kind":"clinical","origin":"ai"},{"id":"hhl-tki-cml~ai-3","moduleId":"hhl-tki-cml","stem":"A CML patient on dasatinib develops pleural effusion. What is the most appropriate next step?","options":[{"id":"a","text":"Continue dasatinib and monitor"},{"id":"b","text":"Switch to imatinib"},{"id":"c","text":"Switch to nilotinib"},{"id":"d","text":"Reduce dasatinib dose"}],"answerId":"d","explanation":"Pleural effusion is a known side effect of dasatinib; dose reduction is often the first step in management.","kind":"clinical","origin":"ai"},{"id":"hhl-tki-cml~ai-4","moduleId":"hhl-tki-cml","stem":"In a CML patient with a rising BCR-ABL transcript despite imatinib therapy, which mutation should be specifically tested for?","options":[{"id":"a","text":"T315I mutation"},{"id":"b","text":"JAK2 V617F mutation"},{"id":"c","text":"FLT3-ITD mutation"},{"id":"d","text":"NPM1 mutation"}],"answerId":"a","explanation":"The T315I mutation confers resistance to imatinib, dasatinib, and nilotinib, necessitating a switch to ponatinib.","kind":"trap","origin":"ai"},{"id":"hhl-tki-cml~ai-5","moduleId":"hhl-tki-cml","stem":"Which of the following is a key difference between tyrosine kinase inhibitors and traditional cytotoxic chemotherapy in treating CML?","options":[{"id":"a","text":"TKIs target specific molecular lesions"},{"id":"b","text":"TKIs cause more severe myelosuppression"},{"id":"c","text":"TKIs are less effective in chronic phase"},{"id":"d","text":"TKIs require higher doses for efficacy"}],"answerId":"a","explanation":"TKIs specifically target the BCR-ABL fusion protein, representing a precision oncology approach.","kind":"recall","origin":"ai"},{"id":"hhl-tki-cml~ai-6","moduleId":"hhl-tki-cml","stem":"How does the presence of the T315I mutation affect the choice of therapy in CML?","options":[{"id":"a","text":"Requires switching to ponatinib"},{"id":"b","text":"Continue with higher dose imatinib"},{"id":"c","text":"Switch to dasatinib"},{"id":"d","text":"Switch to nilotinib"}],"answerId":"a","explanation":"The T315I mutation is resistant to imatinib, dasatinib, and nilotinib, but ponatinib is effective.","kind":"mechanism","origin":"ai"},{"id":"hhl-tki-cml~ai-7","moduleId":"hhl-tki-cml","stem":"A patient with CML is being monitored for treatment response. Which finding would suggest the need for a change in therapy?","options":[{"id":"a","text":"Stable BCR-ABL transcript levels"},{"id":"b","text":"Rising BCR-ABL transcript levels"},{"id":"c","text":"Decreasing white blood cell count"},{"id":"d","text":"Stable platelet count"}],"answerId":"b","explanation":"Rising BCR-ABL transcript levels indicate resistance or non-adherence, necessitating a change in therapy.","kind":"clinical","origin":"ai"},{"id":"hhl-tki-cml~ai-8","moduleId":"hhl-tki-cml","stem":"In the context of CML, how does the management of a rising BCR-ABL transcript integrate with the principles of targeted therapy across leukemias?","options":[{"id":"a","text":"Switch to a different TKI based on mutation analysis"},{"id":"b","text":"Increase the dose of the current TKI"},{"id":"c","text":"Add cytotoxic chemotherapy"},{"id":"d","text":"Perform a bone marrow transplant immediately"}],"answerId":"a","explanation":"Targeted therapy principles involve switching to a different TKI based on specific mutation analysis, aligning with the precision approach in leukemias.","kind":"integration","linkedModuleIds":["hhl-targeted-therapy-classes"],"origin":"ai"}],"hhl-hdn":[{"id":"hhl-hdn~ai-0","moduleId":"hhl-hdn","stem":"Which maternal blood group is most likely to cause hemolytic disease of the newborn in the first pregnancy?","options":[{"id":"a","text":"Group O"},{"id":"b","text":"Group A"},{"id":"c","text":"Group B"},{"id":"d","text":"Group AB"}],"answerId":"a","explanation":"Group O mothers can have naturally occurring IgG anti-A,B antibodies, which can affect the first pregnancy.","kind":"trap","origin":"ai"},{"id":"hhl-hdn~ai-1","moduleId":"hhl-hdn","stem":"What is the primary mechanism by which RhD hemolytic disease of the newborn occurs?","options":[{"id":"a","text":"Maternal IgG anti-D antibodies cross the placenta"},{"id":"b","text":"Maternal IgM anti-D antibodies cross the placenta"},{"id":"c","text":"Maternal IgG anti-A,B antibodies cross the placenta"},{"id":"d","text":"Maternal IgM anti-A,B antibodies cross the placenta"}],"answerId":"a","explanation":"Maternal IgG anti-D antibodies cross the placenta and hemolyze fetal red cells in RhD incompatibility.","kind":"mechanism","origin":"ai"},{"id":"hhl-hdn~ai-2","moduleId":"hhl-hdn","stem":"A newborn presents with jaundice within the first 24 hours of life. Which finding would support a diagnosis of hemolytic disease of the newborn?","options":[{"id":"a","text":"Positive direct Coombs test"},{"id":"b","text":"Negative direct Coombs test"},{"id":"c","text":"Normal bilirubin levels"},{"id":"d","text":"Absence of nucleated RBCs"}],"answerId":"a","explanation":"A positive direct Coombs test indicates maternal antibodies are coating fetal red cells, consistent with HDN.","kind":"clinical","origin":"ai"},{"id":"hhl-hdn~ai-3","moduleId":"hhl-hdn","stem":"Why is anti-D immunoglobulin ineffective in a mother who already has anti-D antibodies?","options":[{"id":"a","text":"It cannot clear fetal D cells"},{"id":"b","text":"It is only effective against IgM antibodies"},{"id":"c","text":"It is only effective before sensitization"},{"id":"d","text":"It enhances the immune response"}],"answerId":"c","explanation":"Anti-D immunoglobulin is prophylactic and only effective before the mother is sensitized to D antigen.","kind":"trap","origin":"ai"},{"id":"hhl-hdn~ai-4","moduleId":"hhl-hdn","stem":"A newborn with severe anemia and hepatosplenomegaly is suspected to have hemolytic disease of the newborn. What is the most likely cause of these findings?","options":[{"id":"a","text":"Fetal anemia due to maternal IgG antibodies"},{"id":"b","text":"Fetal anemia due to maternal IgM antibodies"},{"id":"c","text":"Fetal anemia due to RhD antigen deficiency"},{"id":"d","text":"Fetal anemia due to ABO incompatibility"}],"answerId":"a","explanation":"Severe anemia and hepatosplenomegaly in HDN are due to maternal IgG antibodies causing hemolysis.","kind":"clinical","origin":"ai"},{"id":"hhl-hdn~ai-5","moduleId":"hhl-hdn","stem":"How does the Rh system contribute to hemolytic disease of the newborn?","options":[{"id":"a","text":"RhD-negative mother with RhD-positive fetus"},{"id":"b","text":"RhD-positive mother with RhD-negative fetus"},{"id":"c","text":"ABO-incompatible mother and fetus"},{"id":"d","text":"RhD-negative mother with RhD-negative fetus"}],"answerId":"a","explanation":"An RhD-negative mother with an RhD-positive fetus can develop anti-D antibodies, leading to HDN.","kind":"integration","linkedModuleIds":["hhl-rh-system"],"origin":"ai"},{"id":"hhl-hdn~ai-6","moduleId":"hhl-hdn","stem":"In the context of hemolytic disease of the newborn, what role does the ABO blood group system play?","options":[{"id":"a","text":"Group O mothers can have IgG anti-A,B affecting the first pregnancy"},{"id":"b","text":"Group A mothers can have IgG anti-B affecting the first pregnancy"},{"id":"c","text":"Group B mothers can have IgG anti-A affecting the first pregnancy"},{"id":"d","text":"Group AB mothers can have IgG anti-O affecting the first pregnancy"}],"answerId":"a","explanation":"Group O mothers naturally have IgG anti-A,B antibodies, which can affect the first pregnancy.","kind":"integration","linkedModuleIds":["hhl-abo-system"],"origin":"ai"}],"hhl-rh-system":[{"id":"hhl-rh-system~ai-0","moduleId":"hhl-rh-system","stem":"Which of the following antibodies is most likely to cause hemolytic disease of the newborn?","options":[{"id":"a","text":"Anti-D"},{"id":"b","text":"Anti-A"},{"id":"c","text":"Anti-B"},{"id":"d","text":"Anti-Lea"}],"answerId":"a","explanation":"Anti-D is an immune IgG antibody that crosses the placenta and can cause hemolytic disease of the newborn.","kind":"recall","origin":"ai"},{"id":"hhl-rh-system~ai-1","moduleId":"hhl-rh-system","stem":"A D-negative woman receives a D-positive blood transfusion. What type of antibody is most likely to develop?","options":[{"id":"a","text":"IgM anti-D"},{"id":"b","text":"IgG anti-D"},{"id":"c","text":"IgA anti-D"},{"id":"d","text":"IgE anti-D"}],"answerId":"b","explanation":"Exposure to D-positive blood can lead to the formation of IgG anti-D antibodies in a D-negative individual.","kind":"mechanism","origin":"ai"},{"id":"hhl-rh-system~ai-2","moduleId":"hhl-rh-system","stem":"A patient experiences a hemoglobin drop 10 days after a blood transfusion. Which antibody is most likely involved?","options":[{"id":"a","text":"Anti-D"},{"id":"b","text":"Anti-A"},{"id":"c","text":"Anti-B"},{"id":"d","text":"Anti-Jk"}],"answerId":"d","explanation":"Anti-Jk (Kidd) antibodies are notorious for causing delayed hemolytic reactions.","kind":"clinical","origin":"ai"},{"id":"hhl-rh-system~ai-3","moduleId":"hhl-rh-system","stem":"Which of the following is a common misconception about anti-D antibodies?","options":[{"id":"a","text":"They are naturally occurring"},{"id":"b","text":"They are immune IgG antibodies"},{"id":"c","text":"They cause delayed hemolytic reactions"},{"id":"d","text":"They cross the placenta"}],"answerId":"a","explanation":"Anti-D antibodies are not naturally occurring; they are formed after exposure to D-positive blood.","kind":"trap","origin":"ai"},{"id":"hhl-rh-system~ai-4","moduleId":"hhl-rh-system","stem":"A neonate has a positive direct antiglobulin test (DAT) and is born to a D-negative mother. What is the most likely cause?","options":[{"id":"a","text":"Maternal IgG anti-D"},{"id":"b","text":"Maternal IgM anti-D"},{"id":"c","text":"Maternal IgG anti-A"},{"id":"d","text":"Maternal IgM anti-B"}],"answerId":"a","explanation":"Maternal IgG anti-D antibodies cross the placenta and coat fetal red cells, causing a positive DAT.","kind":"clinical","origin":"ai"},{"id":"hhl-rh-system~ai-5","moduleId":"hhl-rh-system","stem":"Which blood group system is primarily associated with resistance to Plasmodium vivax infection?","options":[{"id":"a","text":"Duffy"},{"id":"b","text":"Kell"},{"id":"c","text":"Kidd"},{"id":"d","text":"Rh"}],"answerId":"a","explanation":"Duffy-null red cells (Fy(a-b-)) resist Plasmodium vivax invasion, common in individuals of West-African ancestry.","kind":"recall","origin":"ai"},{"id":"hhl-rh-system~ai-6","moduleId":"hhl-rh-system","stem":"In the context of hemolytic transfusion reactions, which antibody type is associated with immediate intravascular hemolysis?","options":[{"id":"a","text":"IgM anti-A"},{"id":"b","text":"IgG anti-D"},{"id":"c","text":"IgG anti-K"},{"id":"d","text":"IgG anti-Jk"}],"answerId":"a","explanation":"IgM anti-A antibodies can cause immediate intravascular hemolysis, unlike IgG antibodies which cause extravascular hemolysis.","kind":"integration","linkedModuleIds":["hhl-abo-system"],"origin":"ai"},{"id":"hhl-rh-system~ai-7","moduleId":"hhl-rh-system","stem":"Which hypersensitivity type is involved in the pathogenesis of hemolytic disease of the newborn?","options":[{"id":"a","text":"Type I"},{"id":"b","text":"Type II"},{"id":"c","text":"Type III"},{"id":"d","text":"Type IV"}],"answerId":"b","explanation":"Hemolytic disease of the newborn is a Type II hypersensitivity reaction involving IgG antibodies against fetal red cells.","kind":"integration","linkedModuleIds":["hypersensitivity-type-1-2"],"origin":"ai"}],"hhl-molecular-techniques":[{"id":"hhl-molecular-techniques~ai-0","moduleId":"hhl-molecular-techniques","stem":"Which molecular technique is most appropriate for detecting a BCR-ABL translocation in a newly diagnosed patient with chronic myeloid leukemia?","options":[{"id":"a","text":"FISH"},{"id":"b","text":"Quantitative RT-PCR"},{"id":"c","text":"Sanger sequencing"},{"id":"d","text":"Karyotyping"}],"answerId":"a","explanation":"FISH is used to detect large chromosomal rearrangements like BCR-ABL translocations.","kind":"recall","origin":"ai"},{"id":"hhl-molecular-techniques~ai-1","moduleId":"hhl-molecular-techniques","stem":"A patient with a known JAK2 V617F mutation is being monitored for minimal residual disease. Which technique should be used?","options":[{"id":"a","text":"FISH"},{"id":"b","text":"Karyotyping"},{"id":"c","text":"Quantitative RT-PCR"},{"id":"d","text":"Sanger sequencing"}],"answerId":"c","explanation":"Quantitative RT-PCR is the sensitive tool for monitoring minimal residual disease.","kind":"trap","origin":"ai"},{"id":"hhl-molecular-techniques~ai-2","moduleId":"hhl-molecular-techniques","stem":"In a patient with suspected multiple myeloma, which molecular technique would be most useful to detect chromosomal deletions?","options":[{"id":"a","text":"FISH"},{"id":"b","text":"Quantitative RT-PCR"},{"id":"c","text":"Sanger sequencing"},{"id":"d","text":"Karyotyping"}],"answerId":"a","explanation":"FISH can detect chromosomal deletions in multiple myeloma even in non-dividing cells.","kind":"mechanism","origin":"ai"},{"id":"hhl-molecular-techniques~ai-3","moduleId":"hhl-molecular-techniques","stem":"Which finding on gel electrophoresis would indicate a successful PCR amplification?","options":[{"id":"a","text":"No bands visible"},{"id":"b","text":"Multiple bands of varying sizes"},{"id":"c","text":"A single band of the expected size"},{"id":"d","text":"A smear across the gel"}],"answerId":"c","explanation":"A single band of the expected size indicates successful PCR amplification of the target sequence.","kind":"recall","origin":"ai"},{"id":"hhl-molecular-techniques~ai-4","moduleId":"hhl-molecular-techniques","stem":"A patient with chronic myeloid leukemia is undergoing treatment. Which technique is best for monitoring the effectiveness of therapy?","options":[{"id":"a","text":"FISH"},{"id":"b","text":"Karyotyping"},{"id":"c","text":"Quantitative RT-PCR"},{"id":"d","text":"Sanger sequencing"}],"answerId":"c","explanation":"Quantitative RT-PCR is used for sensitive monitoring of minimal residual disease.","kind":"clinical","origin":"ai"},{"id":"hhl-molecular-techniques~ai-5","moduleId":"hhl-molecular-techniques","stem":"Which molecular technique is most appropriate for detecting point mutations in a patient with suspected polycythemia vera?","options":[{"id":"a","text":"FISH"},{"id":"b","text":"Quantitative RT-PCR"},{"id":"c","text":"Sanger sequencing"},{"id":"d","text":"Karyotyping"}],"answerId":"c","explanation":"Sanger sequencing is used to detect point mutations such as JAK2 V617F in polycythemia vera.","kind":"recall","origin":"ai"},{"id":"hhl-molecular-techniques~ai-6","moduleId":"hhl-molecular-techniques","stem":"In the context of thyroid storm, which molecular technique could be used to assess the genetic predisposition of the patient?","options":[{"id":"a","text":"FISH"},{"id":"b","text":"Quantitative RT-PCR"},{"id":"c","text":"Sanger sequencing"},{"id":"d","text":"Karyotyping"}],"answerId":"c","explanation":"Sanger sequencing can be used to detect genetic mutations that may predispose to thyroid disorders.","kind":"integration","linkedModuleIds":["thyroid-storm-recognition-management"],"origin":"ai"},{"id":"hhl-molecular-techniques~ai-7","moduleId":"hhl-molecular-techniques","stem":"A patient is suspected to have a hematologic neoplasm with a specific fusion gene. Which technique is best for initial detection?","options":[{"id":"a","text":"FISH"},{"id":"b","text":"Quantitative RT-PCR"},{"id":"c","text":"Sanger sequencing"},{"id":"d","text":"Karyotyping"}],"answerId":"a","explanation":"FISH is ideal for detecting fusion genes in hematologic neoplasms at diagnosis.","kind":"integration","linkedModuleIds":["hhl-molecular-diagnostics-heme"],"origin":"ai"}],"hhl-molecular-diagnostics-heme":[{"id":"hhl-molecular-diagnostics-heme~ai-0","moduleId":"hhl-molecular-diagnostics-heme","stem":"Which genetic mutation is most commonly associated with chronic myeloid leukemia (CML)?","options":[{"id":"a","text":"BCR-ABL1"},{"id":"b","text":"JAK2 V617F"},{"id":"c","text":"PML-RARA"},{"id":"d","text":"NPM1"}],"answerId":"a","explanation":"The BCR-ABL1 fusion gene, resulting from t(9;22), is the hallmark of CML.","kind":"recall","origin":"ai"},{"id":"hhl-molecular-diagnostics-heme~ai-1","moduleId":"hhl-molecular-diagnostics-heme","stem":"A patient with acute promyelocytic leukemia (APL) is at risk for which of the following complications?","options":[{"id":"a","text":"Disseminated intravascular coagulation"},{"id":"b","text":"Hypercalcemia"},{"id":"c","text":"Tumor lysis syndrome"},{"id":"d","text":"Infection"}],"answerId":"a","explanation":"APL is associated with a high risk of DIC due to the PML-RARA fusion gene.","kind":"clinical","origin":"ai"},{"id":"hhl-molecular-diagnostics-heme~ai-2","moduleId":"hhl-molecular-diagnostics-heme","stem":"A patient presents with erythrocytosis and low erythropoietin levels. Which mutation is most likely present?","options":[{"id":"a","text":"JAK2 V617F"},{"id":"b","text":"BCR-ABL1"},{"id":"c","text":"PML-RARA"},{"id":"d","text":"FLT3-ITD"}],"answerId":"a","explanation":"Low erythropoietin with erythrocytosis suggests polycythemia vera, often due to JAK2 V617F mutation.","kind":"trap","origin":"ai"},{"id":"hhl-molecular-diagnostics-heme~ai-3","moduleId":"hhl-molecular-diagnostics-heme","stem":"Which molecular finding indicates a favorable prognosis in acute myeloid leukemia (AML)?","options":[{"id":"a","text":"NPM1 mutation"},{"id":"b","text":"FLT3-ITD"},{"id":"c","text":"BCR-ABL1"},{"id":"d","text":"PML-RARA"}],"answerId":"a","explanation":"NPM1 mutation in AML is associated with a favorable prognosis.","kind":"recall","origin":"ai"},{"id":"hhl-molecular-diagnostics-heme~ai-4","moduleId":"hhl-molecular-diagnostics-heme","stem":"A patient with suspected myeloproliferative neoplasm tests positive for JAK2 V617F. Which condition is least likely?","options":[{"id":"a","text":"Polycythemia vera"},{"id":"b","text":"Essential thrombocythemia"},{"id":"c","text":"Primary myelofibrosis"},{"id":"d","text":"Chronic myeloid leukemia"}],"answerId":"d","explanation":"JAK2 V617F is associated with BCR-ABL-negative myeloproliferative neoplasms, not CML.","kind":"trap","origin":"ai"},{"id":"hhl-molecular-diagnostics-heme~ai-5","moduleId":"hhl-molecular-diagnostics-heme","stem":"In a patient with suspected thalassemia, which molecular test is most useful for antenatal diagnosis?","options":[{"id":"a","text":"α-globin gene sequencing"},{"id":"b","text":"BCR-ABL1 RT-PCR"},{"id":"c","text":"JAK2 V617F mutation analysis"},{"id":"d","text":"NPM1 mutation analysis"}],"answerId":"a","explanation":"α-globin gene sequencing is crucial for identifying mutations that can lead to severe thalassemia syndromes.","kind":"recall","origin":"ai"},{"id":"hhl-molecular-diagnostics-heme~ai-6","moduleId":"hhl-molecular-diagnostics-heme","stem":"A patient with polycythemia vera presents with pruritus after a hot shower. Which linked module would provide more information on this symptom?","options":[{"id":"a","text":"Polycythemia Vera: Pathophysiology and Clinical Manifestations"},{"id":"b","text":"Molecular Techniques in Hematology"},{"id":"c","text":"Cutaneous Manifestations of Hematologic Disorders"},{"id":"d","text":"Molecular Diagnostics of Hematologic Neoplasms"}],"answerId":"c","explanation":"Pruritus in polycythemia vera is a cutaneous manifestation, covered in the linked module on cutaneous manifestations.","kind":"integration","linkedModuleIds":["add-cutaneous-manifestations-of-hematologic-disorders"],"origin":"ai"},{"id":"hhl-molecular-diagnostics-heme~ai-7","moduleId":"hhl-molecular-diagnostics-heme","stem":"Which molecular technique is used to track minimal residual disease in CML?","options":[{"id":"a","text":"Quantitative RT-PCR for BCR-ABL1"},{"id":"b","text":"JAK2 V617F allele-specific PCR"},{"id":"c","text":"FISH for PML-RARA"},{"id":"d","text":"NPM1 mutation analysis"}],"answerId":"a","explanation":"Quantitative RT-PCR for BCR-ABL1 is used to monitor minimal residual disease in CML.","kind":"integration","linkedModuleIds":["hhl-molecular-techniques"],"origin":"ai"}],"hhl-blood-components":[{"id":"hhl-blood-components~ai-0","moduleId":"hhl-blood-components","stem":"A 65-year-old male with liver cirrhosis presents with bleeding and prolonged PT/aPTT. Which blood component is most appropriate for his condition?","options":[{"id":"a","text":"Packed red cells"},{"id":"b","text":"Platelets"},{"id":"c","text":"Fresh frozen plasma"},{"id":"d","text":"Cryoprecipitate"}],"answerId":"c","explanation":"Fresh frozen plasma provides multiple clotting factors, which are deficient in liver disease.","kind":"clinical","origin":"ai"},{"id":"hhl-blood-components~ai-1","moduleId":"hhl-blood-components","stem":"A patient with DIC has a low fibrinogen level. Which blood component should be administered?","options":[{"id":"a","text":"Packed red cells"},{"id":"b","text":"Platelets"},{"id":"c","text":"Fresh frozen plasma"},{"id":"d","text":"Cryoprecipitate"}],"answerId":"d","explanation":"Cryoprecipitate is rich in fibrinogen and is used to treat hypofibrinogenemia.","kind":"clinical","origin":"ai"},{"id":"hhl-blood-components~ai-2","moduleId":"hhl-blood-components","stem":"Which blood component is indicated for a patient with symptomatic anemia and a hemoglobin of 7 g/dL?","options":[{"id":"a","text":"Packed red cells"},{"id":"b","text":"Platelets"},{"id":"c","text":"Fresh frozen plasma"},{"id":"d","text":"Cryoprecipitate"}],"answerId":"a","explanation":"Packed red cells are used to treat symptomatic anemia by increasing hemoglobin levels.","kind":"recall","origin":"ai"},{"id":"hhl-blood-components~ai-3","moduleId":"hhl-blood-components","stem":"A 30-year-old woman with thrombocytopenia is scheduled for surgery. Her platelet count is 20,000/µL. What is the most appropriate blood component to administer?","options":[{"id":"a","text":"Packed red cells"},{"id":"b","text":"Platelets"},{"id":"c","text":"Fresh frozen plasma"},{"id":"d","text":"Cryoprecipitate"}],"answerId":"b","explanation":"Platelets are administered to prevent bleeding in patients with thrombocytopenia undergoing surgery.","kind":"clinical","origin":"ai"},{"id":"hhl-blood-components~ai-4","moduleId":"hhl-blood-components","stem":"In the context of blood component therapy, why is cryoprecipitate preferred over FFP for isolated low fibrinogen levels?","options":[{"id":"a","text":"Cryoprecipitate contains more clotting factors"},{"id":"b","text":"FFP is more likely to cause allergic reactions"},{"id":"c","text":"Cryoprecipitate provides concentrated fibrinogen in less volume"},{"id":"d","text":"FFP is not available in emergency settings"}],"answerId":"c","explanation":"Cryoprecipitate delivers concentrated fibrinogen, avoiding the volume overload associated with FFP.","kind":"trap","origin":"ai"},{"id":"hhl-blood-components~ai-5","moduleId":"hhl-blood-components","stem":"A patient requires a massive transfusion after trauma. Which blood component is essential to manage potential coagulopathy?","options":[{"id":"a","text":"Packed red cells"},{"id":"b","text":"Platelets"},{"id":"c","text":"Fresh frozen plasma"},{"id":"d","text":"Cryoprecipitate"}],"answerId":"c","explanation":"Fresh frozen plasma is used to replace clotting factors in massive transfusion protocols.","kind":"clinical","origin":"ai"},{"id":"hhl-blood-components~ai-6","moduleId":"hhl-blood-components","stem":"What is the primary reason for separating whole blood into components like packed red cells, platelets, and plasma?","options":[{"id":"a","text":"To reduce the risk of infections"},{"id":"b","text":"To allow targeted therapy for specific deficiencies"},{"id":"c","text":"To increase the shelf life of blood products"},{"id":"d","text":"To decrease the cost of blood transfusions"}],"answerId":"b","explanation":"Separating blood into components allows for targeted therapy, ensuring patients receive only what they need.","kind":"mechanism","origin":"ai"},{"id":"hhl-blood-components~ai-7","moduleId":"hhl-blood-components","stem":"A donor's blood is processed into components. Which component is stored at room temperature with constant agitation?","options":[{"id":"a","text":"Packed red cells"},{"id":"b","text":"Platelets"},{"id":"c","text":"Fresh frozen plasma"},{"id":"d","text":"Cryoprecipitate"}],"answerId":"b","explanation":"Platelets are stored at room temperature with constant agitation to maintain their function.","kind":"integration","linkedModuleIds":["hhl-component-storage-processing"],"origin":"ai"},{"id":"hhl-blood-components~ai-8","moduleId":"hhl-blood-components","stem":"During blood donation, which component is most likely to be affected by improper storage conditions?","options":[{"id":"a","text":"Packed red cells"},{"id":"b","text":"Platelets"},{"id":"c","text":"Fresh frozen plasma"},{"id":"d","text":"Cryoprecipitate"}],"answerId":"b","explanation":"Platelets are sensitive to storage conditions and require specific temperature and agitation.","kind":"integration","linkedModuleIds":["hhl-component-storage-processing"],"origin":"ai"}],"hhl-blood-donation":[{"id":"hhl-blood-donation~ai-0","moduleId":"hhl-blood-donation","stem":"What is the primary reason for adding nucleic acid testing (NAT) to the blood donation screening process?","options":[{"id":"a","text":"To detect viral nucleic acid during the window period"},{"id":"b","text":"To confirm serology results"},{"id":"c","text":"To replace serology testing"},{"id":"d","text":"To reduce the cost of screening"}],"answerId":"a","explanation":"NAT detects viral nucleic acid before antibodies appear, reducing the window period.","kind":"mechanism","origin":"ai"},{"id":"hhl-blood-donation~ai-1","moduleId":"hhl-blood-donation","stem":"A blood donor experiences faintness, pallor, and bradycardia immediately after donating blood. What is the most likely cause?","options":[{"id":"a","text":"Vasovagal reaction"},{"id":"b","text":"Hypovolemic shock"},{"id":"c","text":"Allergic reaction"},{"id":"d","text":"Acute hemolytic reaction"}],"answerId":"a","explanation":"These symptoms are characteristic of a vasovagal reaction, the most common donor adverse event.","kind":"clinical","origin":"ai"},{"id":"hhl-blood-donation~ai-2","moduleId":"hhl-blood-donation","stem":"Which of the following is a deferral criterion for blood donation to ensure donor safety?","options":[{"id":"a","text":"Low hemoglobin levels"},{"id":"b","text":"History of hypertension"},{"id":"c","text":"Previous blood donation 6 months ago"},{"id":"d","text":"Age over 60 years"}],"answerId":"a","explanation":"Low hemoglobin levels prevent donation-induced anemia and are a deferral criterion.","kind":"recall","origin":"ai"},{"id":"hhl-blood-donation~ai-3","moduleId":"hhl-blood-donation","stem":"Why is autologous blood donation preferred in some cases?","options":[{"id":"a","text":"It avoids alloimmunization and transmission risks"},{"id":"b","text":"It is cheaper than allogeneic donation"},{"id":"c","text":"It requires less stringent screening"},{"id":"d","text":"It is faster to process"}],"answerId":"a","explanation":"Autologous donation uses the patient's own blood, avoiding alloimmunization and transmission risks.","kind":"recall","origin":"ai"},{"id":"hhl-blood-donation~ai-4","moduleId":"hhl-blood-donation","stem":"A donor's blood tests positive for HIV. What is the immediate next step?","options":[{"id":"a","text":"Discard the unit and counsel the donor"},{"id":"b","text":"Retest the blood sample"},{"id":"c","text":"Notify the recipient"},{"id":"d","text":"Proceed with donation"}],"answerId":"a","explanation":"A reactive screen leads to discarding the unit and counseling the donor.","kind":"clinical","origin":"ai"},{"id":"hhl-blood-donation~ai-5","moduleId":"hhl-blood-donation","stem":"Which infectious agent is NOT routinely screened for in blood donations?","options":[{"id":"a","text":"Zika virus"},{"id":"b","text":"HIV"},{"id":"c","text":"Hepatitis B"},{"id":"d","text":"Syphilis"}],"answerId":"a","explanation":"Zika virus is not routinely screened for, unlike HIV, HBV, and syphilis.","kind":"trap","origin":"ai"},{"id":"hhl-blood-donation~ai-6","moduleId":"hhl-blood-donation","stem":"How does the addition of NAT to blood screening impact the risk of transfusion-transmitted infections?","options":[{"id":"a","text":"It reduces the risk by shortening the window period"},{"id":"b","text":"It eliminates the risk entirely"},{"id":"c","text":"It increases the risk due to false positives"},{"id":"d","text":"It has no impact on the risk"}],"answerId":"a","explanation":"NAT reduces the risk by detecting infections earlier during the window period.","kind":"integration","linkedModuleIds":["hhl-trali-taco-infectious"],"origin":"ai"},{"id":"hhl-blood-donation~ai-7","moduleId":"hhl-blood-donation","stem":"What is the primary benefit of apheresis donation over whole blood donation?","options":[{"id":"a","text":"Selective collection of specific components"},{"id":"b","text":"Shorter donation time"},{"id":"c","text":"Higher volume of blood collected"},{"id":"d","text":"Reduced donor deferral rates"}],"answerId":"a","explanation":"Apheresis allows for the selective collection of specific components like platelets or plasma.","kind":"integration","linkedModuleIds":["hhl-blood-components"],"origin":"ai"}],"hhl-febrile-allergic-reactions":[{"id":"hhl-febrile-allergic-reactions~ai-0","moduleId":"hhl-febrile-allergic-reactions","stem":"A patient develops fever and chills during a blood transfusion but shows no signs of hypotension or hemoglobinuria. What is the most likely diagnosis?","options":[{"id":"a","text":"Febrile non-hemolytic transfusion reaction"},{"id":"b","text":"Acute hemolytic reaction"},{"id":"c","text":"Anaphylactic reaction"},{"id":"d","text":"Transfusion-related acute lung injury"}],"answerId":"a","explanation":"Isolated fever and chills without hypotension or hemoglobinuria suggest a febrile non-hemolytic transfusion reaction.","kind":"clinical","origin":"ai"},{"id":"hhl-febrile-allergic-reactions~ai-1","moduleId":"hhl-febrile-allergic-reactions","stem":"Which of the following is the most appropriate immediate action if a patient develops urticaria and itching during a blood transfusion without fever?","options":[{"id":"a","text":"Stop the transfusion and administer adrenaline"},{"id":"b","text":"Continue the transfusion and administer an antihistamine"},{"id":"c","text":"Stop the transfusion and administer corticosteroids"},{"id":"d","text":"Continue the transfusion and monitor closely"}],"answerId":"b","explanation":"Urticaria and itching without fever suggest a mild allergic reaction, which can be managed with antihistamines while continuing the transfusion.","kind":"clinical","origin":"ai"},{"id":"hhl-febrile-allergic-reactions~ai-2","moduleId":"hhl-febrile-allergic-reactions","stem":"A patient with known IgA deficiency receives a blood transfusion and develops hypotension, wheezing, and angioedema. What is the most likely cause?","options":[{"id":"a","text":"Allergic reaction to plasma proteins"},{"id":"b","text":"Febrile non-hemolytic transfusion reaction"},{"id":"c","text":"Anaphylaxis due to anti-IgA antibodies"},{"id":"d","text":"Acute hemolytic transfusion reaction"}],"answerId":"c","explanation":"Anaphylaxis in an IgA-deficient patient is often due to anti-IgA antibodies reacting to donor IgA.","kind":"mechanism","origin":"ai"},{"id":"hhl-febrile-allergic-reactions~ai-3","moduleId":"hhl-febrile-allergic-reactions","stem":"Which transfusion reaction is most likely if a patient experiences isolated fever during a transfusion, and what should be the immediate action?","options":[{"id":"a","text":"Febrile non-hemolytic transfusion reaction; continue transfusion"},{"id":"b","text":"Acute hemolytic reaction; stop transfusion and evaluate"},{"id":"c","text":"Anaphylactic reaction; administer adrenaline"},{"id":"d","text":"Allergic reaction; administer antihistamine"}],"answerId":"b","explanation":"Fever can be the first sign of an acute hemolytic reaction, so the transfusion should be stopped and evaluated.","kind":"trap","origin":"ai"},{"id":"hhl-febrile-allergic-reactions~ai-4","moduleId":"hhl-febrile-allergic-reactions","stem":"What is the primary mechanism behind febrile non-hemolytic transfusion reactions?","options":[{"id":"a","text":"Recipient IgE against donor plasma proteins"},{"id":"b","text":"Recipient anti-leukocyte antibodies or cytokines from stored blood"},{"id":"c","text":"IgA-deficient recipient reacting to donor IgA"},{"id":"d","text":"Bacterial contamination of blood products"}],"answerId":"b","explanation":"Febrile non-hemolytic transfusion reactions are caused by recipient anti-leukocyte antibodies or cytokines from stored blood.","kind":"mechanism","origin":"ai"},{"id":"hhl-febrile-allergic-reactions~ai-5","moduleId":"hhl-febrile-allergic-reactions","stem":"A patient with a history of severe allergic reactions to blood transfusions requires a transfusion. Which blood product modification is most appropriate?","options":[{"id":"a","text":"Leukoreduced blood products"},{"id":"b","text":"Washed or IgA-deficient blood products"},{"id":"c","text":"Irradiated blood products"},{"id":"d","text":"Fresh frozen plasma"}],"answerId":"b","explanation":"Washed or IgA-deficient blood products are used to prevent severe allergic reactions in susceptible patients.","kind":"recall","origin":"ai"},{"id":"hhl-febrile-allergic-reactions~ai-6","moduleId":"hhl-febrile-allergic-reactions","stem":"How does leukoreduction of blood products help prevent febrile non-hemolytic transfusion reactions?","options":[{"id":"a","text":"By removing donor plasma proteins"},{"id":"b","text":"By reducing anti-leukocyte antibodies"},{"id":"c","text":"By decreasing cytokine accumulation"},{"id":"d","text":"By eliminating IgA from the blood product"}],"answerId":"c","explanation":"Leukoreduction decreases cytokine accumulation, which helps prevent febrile non-hemolytic transfusion reactions.","kind":"integration","linkedModuleIds":["hhl-component-storage-processing"],"origin":"ai"},{"id":"hhl-febrile-allergic-reactions~ai-7","moduleId":"hhl-febrile-allergic-reactions","stem":"A patient develops fever and back pain during a transfusion. Which module should be consulted to differentiate between febrile non-hemolytic and hemolytic transfusion reactions?","options":[{"id":"a","text":"Component Preparation, Storage & Modifications"},{"id":"b","text":"Immunostimulants & Immunising Agents"},{"id":"c","text":"Hemolytic Transfusion Reactions"},{"id":"d","text":"TRALI, TACO & Transfusion-transmitted Infection"}],"answerId":"c","explanation":"The 'Hemolytic Transfusion Reactions' module provides information to differentiate between febrile non-hemolytic and hemolytic reactions.","kind":"integration","linkedModuleIds":["hhl-hemolytic-transfusion-reactions"],"origin":"ai"}],"hhl-hemolytic-transfusion-reactions":[{"id":"hhl-hemolytic-transfusion-reactions~ai-0","moduleId":"hhl-hemolytic-transfusion-reactions","stem":"A patient receiving a blood transfusion suddenly develops fever, flank pain, and hemoglobinuria. What is the most likely cause?","options":[{"id":"a","text":"ABO incompatibility"},{"id":"b","text":"Febrile non-hemolytic reaction"},{"id":"c","text":"Allergic reaction"},{"id":"d","text":"Transfusion-related acute lung injury (TRALI)"}],"answerId":"a","explanation":"These symptoms are indicative of an acute hemolytic transfusion reaction due to ABO incompatibility.","kind":"clinical","origin":"ai"},{"id":"hhl-hemolytic-transfusion-reactions~ai-1","moduleId":"hhl-hemolytic-transfusion-reactions","stem":"Which antibody is most commonly associated with delayed hemolytic transfusion reactions?","options":[{"id":"a","text":"Anti-Jk (Kidd)"},{"id":"b","text":"Anti-A"},{"id":"c","text":"Anti-B"},{"id":"d","text":"Anti-D (Rh)"}],"answerId":"a","explanation":"Anti-Jk (Kidd) antibodies are classic for delayed hemolytic transfusion reactions due to their ability to become undetectable and then rise upon re-exposure.","kind":"recall","origin":"ai"},{"id":"hhl-hemolytic-transfusion-reactions~ai-2","moduleId":"hhl-hemolytic-transfusion-reactions","stem":"A patient presents with jaundice and a falling hemoglobin level 10 days after a transfusion. What test would confirm a delayed hemolytic transfusion reaction?","options":[{"id":"a","text":"Direct antiglobulin test (DAT)"},{"id":"b","text":"Indirect Coombs test"},{"id":"c","text":"Blood culture"},{"id":"d","text":"Serum bilirubin level"}],"answerId":"a","explanation":"A positive direct antiglobulin test (DAT) indicates antibody-coated red blood cells, confirming a delayed hemolytic transfusion reaction.","kind":"clinical","origin":"ai"},{"id":"hhl-hemolytic-transfusion-reactions~ai-3","moduleId":"hhl-hemolytic-transfusion-reactions","stem":"What is the primary mechanism behind acute hemolytic transfusion reactions?","options":[{"id":"a","text":"Preformed IgM antibodies fixing complement"},{"id":"b","text":"IgG antibodies causing extravascular hemolysis"},{"id":"c","text":"Cytokine release from donor leukocytes"},{"id":"d","text":"IgE-mediated hypersensitivity"}],"answerId":"a","explanation":"Acute hemolytic transfusion reactions are caused by preformed IgM antibodies that fix complement, leading to intravascular hemolysis.","kind":"mechanism","origin":"ai"},{"id":"hhl-hemolytic-transfusion-reactions~ai-4","moduleId":"hhl-hemolytic-transfusion-reactions","stem":"A patient experiences hypotension and oozing from IV sites during a transfusion. Which complication is most likely occurring?","options":[{"id":"a","text":"Disseminated intravascular coagulation (DIC)"},{"id":"b","text":"Febrile non-hemolytic reaction"},{"id":"c","text":"Allergic reaction"},{"id":"d","text":"Transfusion-associated circulatory overload (TACO)"}],"answerId":"a","explanation":"Hypotension and oozing suggest DIC, which can be triggered by acute hemolytic transfusion reactions.","kind":"clinical","origin":"ai"},{"id":"hhl-hemolytic-transfusion-reactions~ai-5","moduleId":"hhl-hemolytic-transfusion-reactions","stem":"Which of the following is a common error leading to acute hemolytic transfusion reactions?","options":[{"id":"a","text":"Clerical/identification error"},{"id":"b","text":"Improper blood storage"},{"id":"c","text":"Delayed antibody response"},{"id":"d","text":"Leukocyte contamination"}],"answerId":"a","explanation":"Acute hemolytic transfusion reactions are almost always due to clerical or identification errors leading to ABO incompatibility.","kind":"trap","origin":"ai"},{"id":"hhl-hemolytic-transfusion-reactions~ai-6","moduleId":"hhl-hemolytic-transfusion-reactions","stem":"A patient with a history of multiple transfusions presents with jaundice and anemia 7 days post-transfusion. Which antigen is most likely involved?","options":[{"id":"a","text":"Kidd"},{"id":"b","text":"ABO"},{"id":"c","text":"Lea"},{"id":"d","text":"Kell"}],"answerId":"a","explanation":"Delayed hemolytic transfusion reactions are often due to Kidd antibodies, which can cause an anamnestic response.","kind":"integration","linkedModuleIds":["hhl-rh-system"],"origin":"ai"},{"id":"hhl-hemolytic-transfusion-reactions~ai-7","moduleId":"hhl-hemolytic-transfusion-reactions","stem":"What is the first step in managing an acute hemolytic transfusion reaction?","options":[{"id":"a","text":"Stop the transfusion"},{"id":"b","text":"Administer antihistamines"},{"id":"c","text":"Start antibiotics"},{"id":"d","text":"Perform a direct antiglobulin test"}],"answerId":"a","explanation":"The immediate action in an acute hemolytic transfusion reaction is to stop the transfusion to prevent further hemolysis.","kind":"recall","origin":"ai"},{"id":"hhl-hemolytic-transfusion-reactions~ai-8","moduleId":"hhl-hemolytic-transfusion-reactions","stem":"A patient develops fever and chills during a transfusion but no hemoglobinuria. What is the most likely diagnosis?","options":[{"id":"a","text":"Febrile non-hemolytic transfusion reaction"},{"id":"b","text":"Acute hemolytic transfusion reaction"},{"id":"c","text":"Allergic reaction"},{"id":"d","text":"Transfusion-related acute lung injury (TRALI)"}],"answerId":"a","explanation":"Fever and chills without hemoglobinuria suggest a febrile non-hemolytic transfusion reaction.","kind":"integration","linkedModuleIds":["hhl-febrile-allergic-reactions"],"origin":"ai"}],"hhl-trali-taco-infectious":[{"id":"hhl-trali-taco-infectious~ai-0","moduleId":"hhl-trali-taco-infectious","stem":"A patient develops hypoxia and bilateral infiltrates within 6 hours of a blood transfusion. The JVP is normal, and the patient is hypotensive. What is the most likely diagnosis?","options":[{"id":"a","text":"TRALI"},{"id":"b","text":"TACO"},{"id":"c","text":"Transfusion-associated GVHD"},{"id":"d","text":"Bacterial contamination"}],"answerId":"a","explanation":"TRALI is characterized by non-cardiogenic pulmonary edema with normal JVP and hypotension.","kind":"recall","origin":"ai"},{"id":"hhl-trali-taco-infectious~ai-1","moduleId":"hhl-trali-taco-infectious","stem":"Which of the following is a key distinguishing feature of TACO compared to TRALI?","options":[{"id":"a","text":"Normal JVP"},{"id":"b","text":"Hypotension"},{"id":"c","text":"Hypertension"},{"id":"d","text":"Bilateral infiltrates"}],"answerId":"c","explanation":"TACO is associated with hypertension and raised JVP, unlike TRALI.","kind":"mechanism","origin":"ai"},{"id":"hhl-trali-taco-infectious~ai-2","moduleId":"hhl-trali-taco-infectious","stem":"A patient experiences fever, rigors, and hypotension shortly after receiving a platelet transfusion. What is the most likely cause?","options":[{"id":"a","text":"TRALI"},{"id":"b","text":"TACO"},{"id":"c","text":"Bacterial contamination"},{"id":"d","text":"Transfusion-associated GVHD"}],"answerId":"c","explanation":"Bacterial contamination is common in platelet transfusions due to room-temperature storage.","kind":"clinical","origin":"ai"},{"id":"hhl-trali-taco-infectious~ai-3","moduleId":"hhl-trali-taco-infectious","stem":"Which transfusion reaction is prevented by irradiation of cellular components?","options":[{"id":"a","text":"TRALI"},{"id":"b","text":"TACO"},{"id":"c","text":"Transfusion-associated GVHD"},{"id":"d","text":"Bacterial contamination"}],"answerId":"c","explanation":"Transfusion-associated GVHD is prevented by irradiating cellular components to inactivate donor T cells.","kind":"recall","origin":"ai"},{"id":"hhl-trali-taco-infectious~ai-4","moduleId":"hhl-trali-taco-infectious","stem":"A 70-year-old patient with a history of heart failure develops dyspnea, raised JVP, and hypertension after a rapid blood transfusion. What is the appropriate management?","options":[{"id":"a","text":"Administer diuretics and slow/stop transfusion"},{"id":"b","text":"Provide respiratory support and continue transfusion"},{"id":"c","text":"Administer antihistamines"},{"id":"d","text":"Initiate broad-spectrum antibiotics"}],"answerId":"a","explanation":"The presentation is consistent with TACO, which requires diuretics and slowing/stopping the transfusion.","kind":"clinical","origin":"ai"},{"id":"hhl-trali-taco-infectious~ai-5","moduleId":"hhl-trali-taco-infectious","stem":"Which infectious agent is most likely to be transmitted via platelet transfusion due to storage conditions?","options":[{"id":"a","text":"HIV"},{"id":"b","text":"CMV"},{"id":"c","text":"Bacterial contamination"},{"id":"d","text":"HCV"}],"answerId":"c","explanation":"Platelets are stored at room temperature, increasing the risk of bacterial contamination.","kind":"recall","origin":"ai"},{"id":"hhl-trali-taco-infectious~ai-6","moduleId":"hhl-trali-taco-infectious","stem":"A patient develops a rash, diarrhea, pancytopenia, and deranged LFTs after a transfusion. Which module provides information on preventing this condition?","options":[{"id":"a","text":"hhl-component-storage-processing"},{"id":"b","text":"hhl-blood-donation"},{"id":"c","text":"hhl-febrile-allergic-reactions"},{"id":"d","text":"hhl-hemolytic-transfusion-reactions"}],"answerId":"a","explanation":"Transfusion-associated GVHD is prevented by irradiating blood components, covered in the component storage and processing module.","kind":"integration","linkedModuleIds":["hhl-component-storage-processing"],"origin":"ai"},{"id":"hhl-trali-taco-infectious~ai-7","moduleId":"hhl-trali-taco-infectious","stem":"A patient with a history of multiple transfusions presents with fever and chills. Which module would provide information on screening to prevent this reaction?","options":[{"id":"a","text":"hhl-component-storage-processing"},{"id":"b","text":"hhl-blood-donation"},{"id":"c","text":"hhl-febrile-allergic-reactions"},{"id":"d","text":"hhl-hemolytic-transfusion-reactions"}],"answerId":"b","explanation":"The blood donation module covers donor screening to prevent transfusion-transmitted infections.","kind":"integration","linkedModuleIds":["hhl-blood-donation"],"origin":"ai"}],"hhl-filariasis-clinical":[{"id":"hhl-filariasis-clinical~ai-0","moduleId":"hhl-filariasis-clinical","stem":"A 32-year-old man presents with non-pitting swelling of his left leg. He has a history of recurrent fevers and painful lymph nodes. What is the most likely cause of his current condition?","options":[{"id":"a","text":"Chronic lymphatic obstruction"},{"id":"b","text":"Acute inflammatory reaction"},{"id":"c","text":"Bacterial infection"},{"id":"d","text":"Venous insufficiency"}],"answerId":"a","explanation":"Chronic lymphatic obstruction due to filariasis leads to non-pitting lymphoedema and elephantiasis.","kind":"clinical","origin":"ai"},{"id":"hhl-filariasis-clinical~ai-1","moduleId":"hhl-filariasis-clinical","stem":"Which of the following is the primary treatment for lymphatic filariasis?","options":[{"id":"a","text":"Diethylcarbamazine (DEC)"},{"id":"b","text":"Albendazole"},{"id":"c","text":"Ivermectin"},{"id":"d","text":"Corticosteroids"}],"answerId":"a","explanation":"Diethylcarbamazine (DEC) is the primary antifilarial drug used to treat lymphatic filariasis.","kind":"recall","origin":"ai"},{"id":"hhl-filariasis-clinical~ai-2","moduleId":"hhl-filariasis-clinical","stem":"A patient with tropical pulmonary eosinophilia is likely to have which of the following laboratory findings?","options":[{"id":"a","text":"Normal eosinophil count"},{"id":"b","text":"Low IgE levels"},{"id":"c","text":"High eosinophil count and IgE levels"},{"id":"d","text":"Presence of microfilariae in blood"}],"answerId":"c","explanation":"Tropical pulmonary eosinophilia is characterized by high eosinophil count and elevated IgE levels.","kind":"mechanism","origin":"ai"},{"id":"hhl-filariasis-clinical~ai-3","moduleId":"hhl-filariasis-clinical","stem":"In the context of lymphatic filariasis, which statement about elephantiasis is correct?","options":[{"id":"a","text":"It can be reversed with DEC treatment"},{"id":"b","text":"It results from acute lymphatic obstruction"},{"id":"c","text":"It is a result of chronic lymphatic obstruction and fibrosis"},{"id":"d","text":"It is primarily caused by bacterial superinfection"}],"answerId":"c","explanation":"Elephantiasis results from chronic lymphatic obstruction and fibrosis, not reversible by DEC.","kind":"trap","origin":"ai"},{"id":"hhl-filariasis-clinical~ai-4","moduleId":"hhl-filariasis-clinical","stem":"A 45-year-old male from a tropical region presents with a hydrocele. Which filarial species is most commonly associated with this condition?","options":[{"id":"a","text":"Wuchereria bancrofti"},{"id":"b","text":"Brugia malayi"},{"id":"c","text":"Loa loa"},{"id":"d","text":"Onchocerca volvulus"}],"answerId":"a","explanation":"Wuchereria bancrofti is the most common cause of hydrocele in lymphatic filariasis.","kind":"recall","origin":"ai"},{"id":"hhl-filariasis-clinical~ai-5","moduleId":"hhl-filariasis-clinical","stem":"A patient with a history of filariasis presents with scrotal swelling. Which embryological structure is involved in the descent of the testes and might be affected in this condition?","options":[{"id":"a","text":"Gubernaculum"},{"id":"b","text":"Processus vaginalis"},{"id":"c","text":"Spermatic cord"},{"id":"d","text":"Tunica albuginea"}],"answerId":"b","explanation":"The processus vaginalis is involved in testicular descent and can be affected by lymphatic obstruction in filariasis.","kind":"integration","linkedModuleIds":["hrp1-gonadal-descent"],"origin":"ai"},{"id":"hhl-filariasis-clinical~ai-6","moduleId":"hhl-filariasis-clinical","stem":"Which diagnostic method is most appropriate for detecting microfilariae in a patient suspected of having lymphatic filariasis?","options":[{"id":"a","text":"Nocturnal thick blood film"},{"id":"b","text":"Daytime blood smear"},{"id":"c","text":"Urine antigen test"},{"id":"d","text":"Skin biopsy"}],"answerId":"a","explanation":"A nocturnal thick blood film is used to detect microfilariae in lymphatic filariasis.","kind":"recall","origin":"ai"},{"id":"hhl-filariasis-clinical~ai-7","moduleId":"hhl-filariasis-clinical","stem":"In the life cycle of lymphatic filariasis, what is the primary location of adult worms?","options":[{"id":"a","text":"Bloodstream"},{"id":"b","text":"Lymphatic vessels"},{"id":"c","text":"Subcutaneous tissue"},{"id":"d","text":"Liver"}],"answerId":"b","explanation":"Adult worms reside in the lymphatic vessels, causing obstruction and symptoms of filariasis.","kind":"integration","linkedModuleIds":["hhl-filariasis-parasitology"],"origin":"ai"}],"hhl-filariasis-parasitology":[{"id":"hhl-filariasis-parasitology~ai-0","moduleId":"hhl-filariasis-parasitology","stem":"Which mosquito genus is primarily responsible for transmitting Wuchereria bancrofti in urban areas?","options":[{"id":"a","text":"Culex"},{"id":"b","text":"Mansonia"},{"id":"c","text":"Anopheles"},{"id":"d","text":"Aedes"}],"answerId":"a","explanation":"Culex mosquitoes are the primary urban vectors for Wuchereria bancrofti.","kind":"recall","origin":"ai"},{"id":"hhl-filariasis-parasitology~ai-1","moduleId":"hhl-filariasis-parasitology","stem":"What is the main reason blood samples for diagnosing lymphatic filariasis must be collected at night?","options":[{"id":"a","text":"Mosquito activity is highest"},{"id":"b","text":"Microfilariae show nocturnal periodicity"},{"id":"c","text":"Patient symptoms are most severe"},{"id":"d","text":"Laboratory availability"}],"answerId":"b","explanation":"Microfilariae circulate in peripheral blood at night due to nocturnal periodicity.","kind":"mechanism","origin":"ai"},{"id":"hhl-filariasis-parasitology~ai-2","moduleId":"hhl-filariasis-parasitology","stem":"A blood film shows sheathed microfilariae with a tail tip free of nuclei. Which species is this likely to be?","options":[{"id":"a","text":"Brugia malayi"},{"id":"b","text":"Wuchereria bancrofti"},{"id":"c","text":"Loa loa"},{"id":"d","text":"Onchocerca volvulus"}],"answerId":"b","explanation":"Wuchereria bancrofti microfilariae have a tail tip free of nuclei.","kind":"recall","origin":"ai"},{"id":"hhl-filariasis-parasitology~ai-3","moduleId":"hhl-filariasis-parasitology","stem":"Which feature differentiates Brugia malayi microfilariae from Wuchereria bancrofti on a stained blood film?","options":[{"id":"a","text":"Presence of a sheath"},{"id":"b","text":"Two separate terminal tail nuclei"},{"id":"c","text":"Nocturnal periodicity"},{"id":"d","text":"Tail tip free of nuclei"}],"answerId":"b","explanation":"Brugia malayi microfilariae have two separate terminal tail nuclei.","kind":"recall","origin":"ai"},{"id":"hhl-filariasis-parasitology~ai-4","moduleId":"hhl-filariasis-parasitology","stem":"A daytime blood film is negative for microfilariae. What is the next best step?","options":[{"id":"a","text":"Repeat blood film at night"},{"id":"b","text":"Start empirical treatment"},{"id":"c","text":"Order a serological test"},{"id":"d","text":"Perform a lymph node biopsy"}],"answerId":"a","explanation":"Blood should be collected at night due to the nocturnal periodicity of microfilariae.","kind":"trap","origin":"ai"},{"id":"hhl-filariasis-parasitology~ai-5","moduleId":"hhl-filariasis-parasitology","stem":"How do adult filarial worms cause lymphatic obstruction?","options":[{"id":"a","text":"Directly invading lymph nodes"},{"id":"b","text":"Inducing inflammatory responses"},{"id":"c","text":"Secreting toxins"},{"id":"d","text":"Blocking blood vessels"}],"answerId":"b","explanation":"Adult worms induce inflammatory responses that lead to lymphatic obstruction.","kind":"mechanism","origin":"ai"},{"id":"hhl-filariasis-parasitology~ai-6","moduleId":"hhl-filariasis-parasitology","stem":"Which anatomical structure is primarily affected by lymphatic filariasis, leading to clinical symptoms?","options":[{"id":"a","text":"Blood vessels"},{"id":"b","text":"Lymphatics"},{"id":"c","text":"Nerves"},{"id":"d","text":"Muscles"}],"answerId":"b","explanation":"Lymphatic filariasis primarily affects the lymphatic system, causing obstruction and swelling.","kind":"integration","linkedModuleIds":["hrp1-breast-gross-lymphatic-anatomy"],"origin":"ai"},{"id":"hhl-filariasis-parasitology~ai-7","moduleId":"hhl-filariasis-parasitology","stem":"What immune response is primarily involved in controlling filarial infections?","options":[{"id":"a","text":"Cell-mediated immunity"},{"id":"b","text":"Humoral immunity"},{"id":"c","text":"Innate immunity"},{"id":"d","text":"Autoimmunity"}],"answerId":"b","explanation":"Humoral immunity, particularly the production of antibodies, plays a key role in controlling filarial infections.","kind":"integration","linkedModuleIds":["immunity-viruses-fungi-parasites"],"origin":"ai"}],"hhl-leishmania":[{"id":"hhl-leishmania~ai-0","moduleId":"hhl-leishmania","stem":"Which form of Leishmania is found inside human macrophages?","options":[{"id":"a","text":"Amastigote"},{"id":"b","text":"Promastigote"},{"id":"c","text":"Trypomastigote"},{"id":"d","text":"Epimastigote"}],"answerId":"a","explanation":"In humans, Leishmania exists as the non-flagellated amastigote inside macrophages.","kind":"recall","origin":"ai"},{"id":"hhl-leishmania~ai-1","moduleId":"hhl-leishmania","stem":"A patient presents with fever, massive hepatosplenomegaly, and pancytopenia. Which diagnostic test is most appropriate to confirm visceral leishmaniasis?","options":[{"id":"a","text":"Bone marrow aspirate for amastigotes"},{"id":"b","text":"Blood film for trypomastigotes"},{"id":"c","text":"Skin biopsy for promastigotes"},{"id":"d","text":"Serum IgG levels"}],"answerId":"a","explanation":"Amastigotes (Leishman–Donovan bodies) are found in bone marrow aspirates in visceral leishmaniasis.","kind":"clinical","origin":"ai"},{"id":"hhl-leishmania~ai-2","moduleId":"hhl-leishmania","stem":"What is the primary vector responsible for the transmission of Leishmania?","options":[{"id":"a","text":"Sandfly"},{"id":"b","text":"Tsetse fly"},{"id":"c","text":"Anopheles mosquito"},{"id":"d","text":"Culex mosquito"}],"answerId":"a","explanation":"Leishmania is transmitted by sandflies, specifically the Phlebotomus and Lutzomyia species.","kind":"recall","origin":"ai"},{"id":"hhl-leishmania~ai-3","moduleId":"hhl-leishmania","stem":"A patient with a chronic painless skin ulcer is suspected of having cutaneous leishmaniasis. What is the most likely finding on biopsy?","options":[{"id":"a","text":"Amastigotes inside macrophages"},{"id":"b","text":"Promastigotes in the dermis"},{"id":"c","text":"Trypomastigotes in blood vessels"},{"id":"d","text":"Epimastigotes in lymph nodes"}],"answerId":"a","explanation":"Cutaneous leishmaniasis is characterized by amastigotes inside macrophages in skin lesions.","kind":"clinical","origin":"ai"},{"id":"hhl-leishmania~ai-4","moduleId":"hhl-leishmania","stem":"Which of the following is a common laboratory finding in visceral leishmaniasis?","options":[{"id":"a","text":"Hypergammaglobulinaemia"},{"id":"b","text":"Hypoglycemia"},{"id":"c","text":"Hypercalcemia"},{"id":"d","text":"Hypernatremia"}],"answerId":"a","explanation":"Visceral leishmaniasis often presents with hypergammaglobulinaemia due to polyclonal B-cell activation.","kind":"mechanism","origin":"ai"},{"id":"hhl-leishmania~ai-5","moduleId":"hhl-leishmania","stem":"In the life cycle of Leishmania, which stage is found in the sandfly vector?","options":[{"id":"a","text":"Promastigote"},{"id":"b","text":"Amastigote"},{"id":"c","text":"Trypomastigote"},{"id":"d","text":"Epimastigote"}],"answerId":"a","explanation":"The promastigote stage of Leishmania is found in the gut of the sandfly vector.","kind":"recall","origin":"ai"},{"id":"hhl-leishmania~ai-6","moduleId":"hhl-leishmania","stem":"A patient with a history of travel to Africa presents with fever, lymphadenopathy, and a chancre at the site of a fly bite. Which other disease should be considered due to a similar vector?","options":[{"id":"a","text":"African trypanosomiasis"},{"id":"b","text":"Dengue fever"},{"id":"c","text":"Malaria"},{"id":"d","text":"Schistosomiasis"}],"answerId":"a","explanation":"African trypanosomiasis is transmitted by the tsetse fly, similar to the sandfly vector for Leishmania.","kind":"integration","linkedModuleIds":["hhl-trypanosoma"],"origin":"ai"},{"id":"hhl-leishmania~ai-7","moduleId":"hhl-leishmania","stem":"Which of the following organisms is transmitted by a blood-sucking fly vector and causes a disease similar to Leishmania?","options":[{"id":"a","text":"Trypanosoma"},{"id":"b","text":"Plasmodium"},{"id":"c","text":"Wuchereria"},{"id":"d","text":"Schistosoma"}],"answerId":"a","explanation":"Trypanosoma, like Leishmania, is transmitted by a blood-sucking fly vector.","kind":"integration","linkedModuleIds":["bloodsucking-fly-vectors"],"origin":"ai"}],"hhl-schistosomiasis-lifecycle":[{"id":"hhl-schistosomiasis-lifecycle~ai-0","moduleId":"hhl-schistosomiasis-lifecycle","stem":"Which species of Schistosoma is most likely responsible for urinary symptoms due to its egg morphology?","options":[{"id":"a","text":"S. haematobium"},{"id":"b","text":"S. mansoni"},{"id":"c","text":"S. japonicum"},{"id":"d","text":"S. mekongi"}],"answerId":"a","explanation":"S. haematobium eggs have a terminal spine and are associated with urinary disease.","kind":"recall","origin":"ai"},{"id":"hhl-schistosomiasis-lifecycle~ai-1","moduleId":"hhl-schistosomiasis-lifecycle","stem":"What is the primary route of human infection with Schistosoma species?","options":[{"id":"a","text":"Ingestion of contaminated water"},{"id":"b","text":"Inhalation of spores"},{"id":"c","text":"Skin penetration by cercariae"},{"id":"d","text":"Bite from an infected insect"}],"answerId":"c","explanation":"Schistosomiasis is acquired when cercariae penetrate intact skin during contact with contaminated water.","kind":"trap","origin":"ai"},{"id":"hhl-schistosomiasis-lifecycle~ai-2","moduleId":"hhl-schistosomiasis-lifecycle","stem":"A patient presents with intestinal symptoms and a stool examination reveals eggs with a lateral spine. Which Schistosoma species is most likely involved?","options":[{"id":"a","text":"S. mansoni"},{"id":"b","text":"S. haematobium"},{"id":"c","text":"S. japonicum"},{"id":"d","text":"S. mekongi"}],"answerId":"a","explanation":"S. mansoni eggs have a lateral spine and are associated with intestinal disease.","kind":"clinical","origin":"ai"},{"id":"hhl-schistosomiasis-lifecycle~ai-3","moduleId":"hhl-schistosomiasis-lifecycle","stem":"Which stage of the Schistosoma life cycle is responsible for penetrating human skin?","options":[{"id":"a","text":"Miracidium"},{"id":"b","text":"Cercaria"},{"id":"c","text":"Sporocyst"},{"id":"d","text":"Adult worm"}],"answerId":"b","explanation":"Cercariae are the larval form that penetrate human skin during water contact.","kind":"mechanism","origin":"ai"},{"id":"hhl-schistosomiasis-lifecycle~ai-4","moduleId":"hhl-schistosomiasis-lifecycle","stem":"A patient from the Mekong region presents with symptoms of schistosomiasis. Which egg morphology would you expect to find?","options":[{"id":"a","text":"Lateral spine"},{"id":"b","text":"Terminal spine"},{"id":"c","text":"Small lateral knob"},{"id":"d","text":"No spine"}],"answerId":"c","explanation":"S. mekongi, prevalent in the Mekong region, has eggs with a small lateral knob.","kind":"recall","origin":"ai"},{"id":"hhl-schistosomiasis-lifecycle~ai-5","moduleId":"hhl-schistosomiasis-lifecycle","stem":"In the context of Schistosomiasis, which vertebral column structure might be affected by chronic infection leading to spinal cord compression?","options":[{"id":"a","text":"Intervertebral disc"},{"id":"b","text":"Vertebral body"},{"id":"c","text":"Facet joint"},{"id":"d","text":"Spinal nerve root"}],"answerId":"b","explanation":"Chronic schistosomiasis can lead to granulomatous lesions affecting the vertebral body.","kind":"integration","linkedModuleIds":["vertebral-column-joints-discs"],"origin":"ai"},{"id":"hhl-schistosomiasis-lifecycle~ai-6","moduleId":"hhl-schistosomiasis-lifecycle","stem":"How does the pathology of Schistosomiasis primarily develop in the human host?","options":[{"id":"a","text":"Adult worms multiply in the bloodstream"},{"id":"b","text":"Eggs cause granulomatous reactions"},{"id":"c","text":"Larvae invade the central nervous system"},{"id":"d","text":"Snails release toxins into the water"}],"answerId":"b","explanation":"The pathology of schistosomiasis is primarily due to the host's immune response to the eggs.","kind":"mechanism","origin":"ai"},{"id":"hhl-schistosomiasis-lifecycle~ai-7","moduleId":"hhl-schistosomiasis-lifecycle","stem":"A patient with a history of swimming in freshwater lakes presents with hematuria. Which diagnostic test would confirm Schistosoma haematobium infection?","options":[{"id":"a","text":"Stool examination for eggs"},{"id":"b","text":"Urine examination for eggs"},{"id":"c","text":"Serum antibody test"},{"id":"d","text":"Skin biopsy"}],"answerId":"b","explanation":"S. haematobium infection is confirmed by finding eggs with a terminal spine in urine.","kind":"clinical","origin":"ai"},{"id":"hhl-schistosomiasis-lifecycle~ai-8","moduleId":"hhl-schistosomiasis-lifecycle","stem":"Which muscle group might be indirectly affected by the chronic inflammation caused by schistosomiasis in the vertebral column?","options":[{"id":"a","text":"Erector spinae"},{"id":"b","text":"Latissimus dorsi"},{"id":"c","text":"Trapezius"},{"id":"d","text":"Rectus abdominis"}],"answerId":"a","explanation":"Chronic inflammation in the vertebral column can affect the intrinsic back muscles like the erector spinae.","kind":"integration","linkedModuleIds":["intrinsic-back-muscles-suboccipital"],"origin":"ai"}],"hhl-malaria-lifecycle":[{"id":"hhl-malaria-lifecycle~ai-0","moduleId":"hhl-malaria-lifecycle","stem":"Which Plasmodium species is known for causing severe and potentially lethal malaria?","options":[{"id":"a","text":"Plasmodium falciparum"},{"id":"b","text":"Plasmodium vivax"},{"id":"c","text":"Plasmodium malariae"},{"id":"d","text":"Plasmodium ovale"}],"answerId":"a","explanation":"Plasmodium falciparum is responsible for the most severe and potentially lethal forms of malaria.","kind":"recall","origin":"ai"},{"id":"hhl-malaria-lifecycle~ai-1","moduleId":"hhl-malaria-lifecycle","stem":"A patient presents with fever every 72 hours. Which Plasmodium species is most likely responsible?","options":[{"id":"a","text":"Plasmodium falciparum"},{"id":"b","text":"Plasmodium vivax"},{"id":"c","text":"Plasmodium malariae"},{"id":"d","text":"Plasmodium ovale"}],"answerId":"c","explanation":"Plasmodium malariae is associated with quartan fever, occurring every 72 hours.","kind":"recall","origin":"ai"},{"id":"hhl-malaria-lifecycle~ai-2","moduleId":"hhl-malaria-lifecycle","stem":"What is the primary reason for malaria relapse in patients infected with Plasmodium vivax?","options":[{"id":"a","text":"Reactivation of hypnozoites"},{"id":"b","text":"Surviving blood-stage parasites"},{"id":"c","text":"New mosquito bite"},{"id":"d","text":"Drug resistance"}],"answerId":"a","explanation":"Plasmodium vivax can form hypnozoites, dormant liver stages that can reactivate and cause relapse.","kind":"mechanism","origin":"ai"},{"id":"hhl-malaria-lifecycle~ai-3","moduleId":"hhl-malaria-lifecycle","stem":"A patient treated for malaria returns with symptoms after 3 months. Which species could cause this relapse?","options":[{"id":"a","text":"Plasmodium falciparum"},{"id":"b","text":"Plasmodium vivax"},{"id":"c","text":"Plasmodium malariae"},{"id":"d","text":"Plasmodium knowlesi"}],"answerId":"b","explanation":"Only Plasmodium vivax and Plasmodium ovale have hypnozoites that can cause relapse.","kind":"trap","origin":"ai"},{"id":"hhl-malaria-lifecycle~ai-4","moduleId":"hhl-malaria-lifecycle","stem":"Which stage of the Plasmodium life cycle is responsible for transmission back to the mosquito vector?","options":[{"id":"a","text":"Sporozoite"},{"id":"b","text":"Merozoite"},{"id":"c","text":"Gametocyte"},{"id":"d","text":"Trophozoite"}],"answerId":"c","explanation":"Gametocytes are the sexual forms that are taken up by the mosquito during a blood meal.","kind":"mechanism","origin":"ai"},{"id":"hhl-malaria-lifecycle~ai-5","moduleId":"hhl-malaria-lifecycle","stem":"A patient with malaria has a tertian fever pattern. Which species could be responsible?","options":[{"id":"a","text":"Plasmodium malariae"},{"id":"b","text":"Plasmodium knowlesi"},{"id":"c","text":"Plasmodium ovale"},{"id":"d","text":"Plasmodium falciparum"}],"answerId":"d","explanation":"Plasmodium falciparum, vivax, and ovale can cause tertian fever, but malariae causes quartan fever.","kind":"recall","origin":"ai"},{"id":"hhl-malaria-lifecycle~ai-6","moduleId":"hhl-malaria-lifecycle","stem":"What is the role of the female Anopheles mosquito in the malaria life cycle?","options":[{"id":"a","text":"Only a host for hypnozoites"},{"id":"b","text":"Vector for sporozoites"},{"id":"c","text":"Reservoir for merozoites"},{"id":"d","text":"Carrier of trophozoites"}],"answerId":"b","explanation":"The female Anopheles mosquito is the vector that transmits sporozoites to humans.","kind":"mechanism","origin":"ai"},{"id":"hhl-malaria-lifecycle~ai-7","moduleId":"hhl-malaria-lifecycle","stem":"How does Plasmodium falciparum differ from Plasmodium vivax in terms of liver-stage forms?","options":[{"id":"a","text":"Falciparum forms hypnozoites, vivax does not"},{"id":"b","text":"Vivax forms hypnozoites, falciparum does not"},{"id":"c","text":"Both form hypnozoites"},{"id":"d","text":"Neither forms hypnozoites"}],"answerId":"b","explanation":"Plasmodium vivax forms hypnozoites, while Plasmodium falciparum does not.","kind":"trap","origin":"ai"},{"id":"hhl-malaria-lifecycle~ai-8","moduleId":"hhl-malaria-lifecycle","stem":"Which Plasmodium species is known for causing zoonotic infections?","options":[{"id":"a","text":"Plasmodium falciparum"},{"id":"b","text":"Plasmodium vivax"},{"id":"c","text":"Plasmodium malariae"},{"id":"d","text":"Plasmodium knowlesi"}],"answerId":"d","explanation":"Plasmodium knowlesi is a zoonotic species that can infect humans.","kind":"recall","origin":"ai"},{"id":"hhl-malaria-lifecycle~ai-9","moduleId":"hhl-malaria-lifecycle","stem":"In the context of malaria, what is the significance of synchronous rupture of schizonts?","options":[{"id":"a","text":"It leads to hypnozoite formation"},{"id":"b","text":"It causes periodic fever patterns"},{"id":"c","text":"It results in gametocyte formation"},{"id":"d","text":"It prevents mosquito transmission"}],"answerId":"b","explanation":"Synchronous rupture of schizonts leads to periodic fever patterns, such as tertian or quartan fevers.","kind":"mechanism","linkedModuleIds":["hhl-malaria-pathophysiology"],"origin":"ai"},{"id":"hhl-malaria-lifecycle~ai-10","moduleId":"hhl-malaria-lifecycle","stem":"Which antimalarial drug is specifically used to target hypnozoites in Plasmodium vivax infections?","options":[{"id":"a","text":"Chloroquine"},{"id":"b","text":"Artemisinin"},{"id":"c","text":"Primaquine"},{"id":"d","text":"Mefloquine"}],"answerId":"c","explanation":"Primaquine is used to eliminate hypnozoites in the liver, preventing relapse in Plasmodium vivax infections.","kind":"integration","linkedModuleIds":["blood-apicomplexa-malaria-babesia"],"origin":"ai"}],"hhl-trypanosoma":[{"id":"hhl-trypanosoma~ai-0","moduleId":"hhl-trypanosoma","stem":"Which vector is responsible for transmitting African trypanosomiasis?","options":[{"id":"a","text":"Tsetse fly"},{"id":"b","text":"Reduviid bug"},{"id":"c","text":"Anopheles mosquito"},{"id":"d","text":"Sandfly"}],"answerId":"a","explanation":"The tsetse fly (Glossina species) transmits African trypanosomiasis.","kind":"recall","origin":"ai"},{"id":"hhl-trypanosoma~ai-1","moduleId":"hhl-trypanosoma","stem":"What is the primary mechanism of transmission for Trypanosoma cruzi?","options":[{"id":"a","text":"Direct bite of the reduviid bug"},{"id":"b","text":"Inhalation of airborne particles"},{"id":"c","text":"Contaminated water"},{"id":"d","text":"Infected faeces rubbed into a bite or mucosa"}],"answerId":"d","explanation":"T. cruzi is transmitted when infected reduviid-bug faeces are rubbed into the bite wound or mucosa.","kind":"mechanism","origin":"ai"},{"id":"hhl-trypanosoma~ai-2","moduleId":"hhl-trypanosoma","stem":"A patient presents with unilateral periorbital swelling. Which disease is most likely?","options":[{"id":"a","text":"African trypanosomiasis"},{"id":"b","text":"American trypanosomiasis"},{"id":"c","text":"Leishmaniasis"},{"id":"d","text":"Malaria"}],"answerId":"b","explanation":"Unilateral periorbital swelling, known as Romaña sign, is indicative of acute Chagas disease (American trypanosomiasis).","kind":"clinical","origin":"ai"},{"id":"hhl-trypanosoma~ai-3","moduleId":"hhl-trypanosoma","stem":"Which of the following is a common chronic complication of Chagas disease?","options":[{"id":"a","text":"Mega-oesophagus"},{"id":"b","text":"Pulmonary fibrosis"},{"id":"c","text":"Renal failure"},{"id":"d","text":"Cirrhosis"}],"answerId":"a","explanation":"Chronic Chagas disease can lead to mega-oesophagus due to tissue damage by T. cruzi.","kind":"recall","origin":"ai"},{"id":"hhl-trypanosoma~ai-4","moduleId":"hhl-trypanosoma","stem":"A patient from Africa presents with fever and posterior cervical lymphadenopathy. What is the most likely diagnosis?","options":[{"id":"a","text":"Malaria"},{"id":"b","text":"African trypanosomiasis"},{"id":"c","text":"Dengue fever"},{"id":"d","text":"Tuberculosis"}],"answerId":"b","explanation":"Posterior cervical lymphadenopathy, known as Winterbottom sign, is associated with African trypanosomiasis.","kind":"clinical","origin":"ai"},{"id":"hhl-trypanosoma~ai-5","moduleId":"hhl-trypanosoma","stem":"Which of the following is a shared characteristic of both African and American trypanosomiasis?","options":[{"id":"a","text":"Transmission by tsetse fly"},{"id":"b","text":"Involvement of the central nervous system"},{"id":"c","text":"Presence of trypomastigotes in blood"},{"id":"d","text":"Development of mega-oesophagus"}],"answerId":"c","explanation":"Both diseases involve the presence of trypomastigotes in the blood during the acute phase.","kind":"integration","linkedModuleIds":["hhl-leishmania"],"origin":"ai"},{"id":"hhl-trypanosoma~ai-6","moduleId":"hhl-trypanosoma","stem":"Which blood-sucking vector is associated with the transmission of both Leishmania and Trypanosoma species?","options":[{"id":"a","text":"Tsetse fly"},{"id":"b","text":"Reduviid bug"},{"id":"c","text":"Sandfly"},{"id":"d","text":"Anopheles mosquito"}],"answerId":"c","explanation":"The sandfly is associated with the transmission of Leishmania, while the tsetse fly and reduviid bug are associated with Trypanosoma.","kind":"integration","linkedModuleIds":["bloodsucking-fly-vectors"],"origin":"ai"}],"hhl-malaria-microscopy":[{"id":"hhl-malaria-microscopy~ai-0","moduleId":"hhl-malaria-microscopy","stem":"Which staining method is considered the gold standard for malaria diagnosis via blood film microscopy?","options":[{"id":"a","text":"Giemsa stain"},{"id":"b","text":"Gram stain"},{"id":"c","text":"Wright's stain"},{"id":"d","text":"Hematoxylin and eosin stain"}],"answerId":"a","explanation":"Giemsa stain is the gold standard for malaria diagnosis because it allows for the identification of Plasmodium species and stages.","kind":"recall","origin":"ai"},{"id":"hhl-malaria-microscopy~ai-1","moduleId":"hhl-malaria-microscopy","stem":"A blood film shows small, delicate rings, often multiple per cell, and normal-sized RBCs. Which Plasmodium species is most likely present?","options":[{"id":"a","text":"P. falciparum"},{"id":"b","text":"P. vivax"},{"id":"c","text":"P. ovale"},{"id":"d","text":"P. malariae"}],"answerId":"a","explanation":"These features are characteristic of P. falciparum, which often presents with multiple rings per RBC and normal-sized RBCs.","kind":"recall","origin":"ai"},{"id":"hhl-malaria-microscopy~ai-2","moduleId":"hhl-malaria-microscopy","stem":"Why is it necessary to repeat malaria blood films every 12-24 hours up to three times before ruling out malaria?","options":[{"id":"a","text":"Parasitemia is constant"},{"id":"b","text":"P. vivax only appears at night"},{"id":"c","text":"Parasitemia fluctuates and mature forms sequester"},{"id":"d","text":"Thick films degrade quickly"}],"answerId":"c","explanation":"Parasitemia fluctuates with the Plasmodium life cycle, and P. falciparum sequesters mature forms, which can lead to false negatives.","kind":"trap","origin":"ai"},{"id":"hhl-malaria-microscopy~ai-3","moduleId":"hhl-malaria-microscopy","stem":"A patient presents with enlarged RBCs containing Schüffner dots and amoeboid trophozoites. Which Plasmodium species is indicated?","options":[{"id":"a","text":"P. falciparum"},{"id":"b","text":"P. vivax"},{"id":"c","text":"P. malariae"},{"id":"d","text":"P. knowlesi"}],"answerId":"b","explanation":"Enlarged RBCs with Schüffner dots and amoeboid trophozoites are indicative of P. vivax.","kind":"recall","origin":"ai"},{"id":"hhl-malaria-microscopy~ai-4","moduleId":"hhl-malaria-microscopy","stem":"Which Plasmodium species is associated with banana or crescent-shaped gametocytes?","options":[{"id":"a","text":"P. falciparum"},{"id":"b","text":"P. vivax"},{"id":"c","text":"P. ovale"},{"id":"d","text":"P. malariae"}],"answerId":"a","explanation":"Banana or crescent-shaped gametocytes are characteristic of P. falciparum.","kind":"recall","origin":"ai"},{"id":"hhl-malaria-microscopy~ai-5","moduleId":"hhl-malaria-microscopy","stem":"A blood film shows band-form trophozoites in normal-sized RBCs. Which Plasmodium species is most likely present?","options":[{"id":"a","text":"P. falciparum"},{"id":"b","text":"P. vivax"},{"id":"c","text":"P. malariae"},{"id":"d","text":"P. ovale"}],"answerId":"c","explanation":"Band-form trophozoites in normal-sized RBCs are characteristic of P. malariae.","kind":"recall","origin":"ai"},{"id":"hhl-malaria-microscopy~ai-6","moduleId":"hhl-malaria-microscopy","stem":"A patient with suspected malaria has a negative blood film. Which diagnostic method could be used to confirm the diagnosis?","options":[{"id":"a","text":"Gram stain"},{"id":"b","text":"PCR"},{"id":"c","text":"ELISA"},{"id":"d","text":"Western blot"}],"answerId":"b","explanation":"PCR is a molecular diagnostic method that can confirm malaria even when blood films are negative.","kind":"integration","linkedModuleIds":["hhl-malaria-rdt-molecular"],"origin":"ai"},{"id":"hhl-malaria-microscopy~ai-7","moduleId":"hhl-malaria-microscopy","stem":"Which of the following diseases is NOT caused by a spirochete, unlike Treponema, Borrelia, and Leptospira?","options":[{"id":"a","text":"Syphilis"},{"id":"b","text":"Lyme disease"},{"id":"c","text":"Malaria"},{"id":"d","text":"Leptospirosis"}],"answerId":"c","explanation":"Malaria is caused by Plasmodium species, which are protozoa, not spirochetes.","kind":"integration","linkedModuleIds":["spirochetes-treponema-borrelia-leptospira"],"origin":"ai"}],"hhl-severe-falciparum-malaria":[{"id":"hhl-severe-falciparum-malaria~ai-0","moduleId":"hhl-severe-falciparum-malaria","stem":"A 25-year-old male presents with impaired consciousness and seizures. He has a history of recent travel to a malaria-endemic region. What is the most likely underlying mechanism for his symptoms?","options":[{"id":"a","text":"Cerebral sequestration and microvascular obstruction"},{"id":"b","text":"Massive intravascular hemolysis"},{"id":"c","text":"Hyperinsulinism from quinine"},{"id":"d","text":"Hepatic dysfunction"}],"answerId":"a","explanation":"Cerebral malaria is caused by sequestration of infected red blood cells in cerebral microvasculature, leading to impaired consciousness and seizures.","kind":"mechanism","origin":"ai"},{"id":"hhl-severe-falciparum-malaria~ai-1","moduleId":"hhl-severe-falciparum-malaria","stem":"Which of the following is the first-line treatment for severe falciparum malaria?","options":[{"id":"a","text":"Oral artemether-lumefantrine"},{"id":"b","text":"IV quinine"},{"id":"c","text":"IV artesunate"},{"id":"d","text":"Oral chloroquine"}],"answerId":"c","explanation":"IV artesunate is the first-line treatment for severe malaria due to its superior efficacy and lower mortality compared to IV quinine.","kind":"recall","origin":"ai"},{"id":"hhl-severe-falciparum-malaria~ai-2","moduleId":"hhl-severe-falciparum-malaria","stem":"A patient with severe falciparum malaria develops dark urine. What is the most likely cause?","options":[{"id":"a","text":"Acute kidney injury"},{"id":"b","text":"Massive intravascular hemolysis"},{"id":"c","text":"Hepatic failure"},{"id":"d","text":"Rhabdomyolysis"}],"answerId":"b","explanation":"Dark urine in severe malaria is indicative of blackwater fever, caused by massive intravascular hemolysis.","kind":"clinical","origin":"ai"},{"id":"hhl-severe-falciparum-malaria~ai-3","moduleId":"hhl-severe-falciparum-malaria","stem":"A patient with severe malaria is found to have hypoglycemia. Which of the following statements is correct?","options":[{"id":"a","text":"Hypoglycemia indicates the drug is working"},{"id":"b","text":"Hypoglycemia is a danger sign and requires immediate correction"},{"id":"c","text":"Hypoglycemia is unrelated to malaria treatment"},{"id":"d","text":"Hypoglycemia only occurs with oral antimalarials"}],"answerId":"b","explanation":"Hypoglycemia is a danger sign in severe malaria and can be exacerbated by quinine; it requires monitoring and correction.","kind":"trap","origin":"ai"},{"id":"hhl-severe-falciparum-malaria~ai-4","moduleId":"hhl-severe-falciparum-malaria","stem":"Which of the following clinical signs in a patient with severe malaria is most directly related to lactic acidosis?","options":[{"id":"a","text":"Deep, rapid breathing"},{"id":"b","text":"Jaundice"},{"id":"c","text":"Petechiae"},{"id":"d","text":"Coma"}],"answerId":"a","explanation":"Deep, rapid (Kussmaul) breathing is a compensatory mechanism for metabolic acidosis, such as lactic acidosis in severe malaria.","kind":"recall","origin":"ai"},{"id":"hhl-severe-falciparum-malaria~ai-5","moduleId":"hhl-severe-falciparum-malaria","stem":"In the context of severe falciparum malaria, what is the primary reason for immediate initiation of IV artesunate?","options":[{"id":"a","text":"It prevents cerebral malaria"},{"id":"b","text":"It reduces mortality compared to IV quinine"},{"id":"c","text":"It is more cost-effective"},{"id":"d","text":"It is easier to administer"}],"answerId":"b","explanation":"IV artesunate is preferred because it significantly reduces mortality compared to IV quinine in severe malaria cases.","kind":"trap","origin":"ai"},{"id":"hhl-severe-falciparum-malaria~ai-6","moduleId":"hhl-severe-falciparum-malaria","stem":"A patient with severe malaria is treated with IV artesunate. Which linked module would provide information on the pharmacokinetics of artesunate?","options":[{"id":"a","text":"hhl-antimalarial-treatment"},{"id":"b","text":"hhl-malaria-pathophysiology"},{"id":"c","text":"hhl-malaria-lifecycle"},{"id":"d","text":"hhl-severe-falciparum-malaria"}],"answerId":"a","explanation":"The 'hhl-antimalarial-treatment' module covers the pharmacokinetics and treatment strategies for antimalarials, including artesunate.","kind":"integration","linkedModuleIds":["hhl-antimalarial-treatment"],"origin":"ai"},{"id":"hhl-severe-falciparum-malaria~ai-7","moduleId":"hhl-severe-falciparum-malaria","stem":"Which linked module would help understand the pathophysiological basis of sequestration in severe falciparum malaria?","options":[{"id":"a","text":"hhl-antimalarial-treatment"},{"id":"b","text":"hhl-malaria-pathophysiology"},{"id":"c","text":"hhl-malaria-lifecycle"},{"id":"d","text":"hhl-severe-falciparum-malaria"}],"answerId":"b","explanation":"The 'hhl-malaria-pathophysiology' module provides insights into the pathophysiological mechanisms, including sequestration in malaria.","kind":"integration","linkedModuleIds":["hhl-malaria-pathophysiology"],"origin":"ai"}],"hhl-malaria-rdt-molecular":[{"id":"hhl-malaria-rdt-molecular~ai-0","moduleId":"hhl-malaria-rdt-molecular","stem":"Which antigen does an HRP2-based rapid diagnostic test (RDT) specifically detect?","options":[{"id":"a","text":"P. falciparum"},{"id":"b","text":"P. vivax"},{"id":"c","text":"P. malariae"},{"id":"d","text":"P. ovale"}],"answerId":"a","explanation":"HRP2 is specific to P. falciparum, making it useful for detecting this species.","kind":"recall","origin":"ai"},{"id":"hhl-malaria-rdt-molecular~ai-1","moduleId":"hhl-malaria-rdt-molecular","stem":"A patient treated for malaria has a persistent positive HRP2 RDT but a negative blood film. What is the most likely explanation?","options":[{"id":"a","text":"Treatment failure"},{"id":"b","text":"HRP2 antigen persistence"},{"id":"c","text":"Reinfection"},{"id":"d","text":"New infection with a different species"}],"answerId":"b","explanation":"HRP2 antigens can persist for weeks after parasites are cleared, leading to false positives.","kind":"trap","origin":"ai"},{"id":"hhl-malaria-rdt-molecular~ai-2","moduleId":"hhl-malaria-rdt-molecular","stem":"Which test is best for confirming low-density parasitemia in malaria?","options":[{"id":"a","text":"HRP2 RDT"},{"id":"b","text":"pLDH RDT"},{"id":"c","text":"PCR"},{"id":"d","text":"Blood film microscopy"}],"answerId":"c","explanation":"PCR is the most sensitive and specific test for detecting low-density parasitemia.","kind":"mechanism","origin":"ai"},{"id":"hhl-malaria-rdt-molecular~ai-3","moduleId":"hhl-malaria-rdt-molecular","stem":"A patient with suspected malaria has a negative RDT but presents with classic symptoms. What should be the next step?","options":[{"id":"a","text":"Repeat the RDT"},{"id":"b","text":"Start empirical treatment"},{"id":"c","text":"Perform blood film microscopy"},{"id":"d","text":"Discharge the patient"}],"answerId":"c","explanation":"Microscopy should be performed to confirm malaria due to possible false-negative RDT results.","kind":"clinical","origin":"ai"},{"id":"hhl-malaria-rdt-molecular~ai-4","moduleId":"hhl-malaria-rdt-molecular","stem":"A patient shows a positive pLDH and aldolase RDT but negative HRP2. Which Plasmodium species is most likely?","options":[{"id":"a","text":"P. falciparum"},{"id":"b","text":"P. vivax"},{"id":"c","text":"P. malariae"},{"id":"d","text":"P. ovale"}],"answerId":"b","explanation":"pLDH and aldolase are pan-species antigens, and a negative HRP2 suggests a non-falciparum species like P. vivax.","kind":"recall","origin":"ai"},{"id":"hhl-malaria-rdt-molecular~ai-5","moduleId":"hhl-malaria-rdt-molecular","stem":"In a region with high pfhrp2/3 gene deletions, which diagnostic method is most reliable for malaria detection?","options":[{"id":"a","text":"HRP2 RDT"},{"id":"b","text":"pLDH RDT"},{"id":"c","text":"PCR"},{"id":"d","text":"Clinical diagnosis"}],"answerId":"c","explanation":"PCR is not affected by pfhrp2/3 deletions and provides reliable detection.","kind":"integration","linkedModuleIds":["blood-apicomplexa-malaria-babesia"],"origin":"ai"},{"id":"hhl-malaria-rdt-molecular~ai-6","moduleId":"hhl-malaria-rdt-molecular","stem":"How does the persistence of HRP2 antigen affect malaria diagnosis post-treatment?","options":[{"id":"a","text":"Indicates treatment failure"},{"id":"b","text":"Confirms cure"},{"id":"c","text":"Requires alternative testing for treatment response"},{"id":"d","text":"Suggests reinfection"}],"answerId":"c","explanation":"HRP2 persistence requires alternative testing like pLDH or microscopy to assess treatment response.","kind":"trap","origin":"ai"},{"id":"hhl-malaria-rdt-molecular~ai-7","moduleId":"hhl-malaria-rdt-molecular","stem":"Which diagnostic method is essential for species confirmation in mixed malaria infections?","options":[{"id":"a","text":"HRP2 RDT"},{"id":"b","text":"pLDH RDT"},{"id":"c","text":"PCR"},{"id":"d","text":"Blood film microscopy"}],"answerId":"d","explanation":"Blood film microscopy is essential for species confirmation in mixed infections.","kind":"integration","linkedModuleIds":["hhl-malaria-microscopy"],"origin":"ai"}],"hhl-antimalarials-mechanisms":[{"id":"hhl-antimalarials-mechanisms~ai-0","moduleId":"hhl-antimalarials-mechanisms","stem":"Which antimalarial drug is known for causing oxidative hemolysis in patients with G6PD deficiency?","options":[{"id":"a","text":"Primaquine"},{"id":"b","text":"Chloroquine"},{"id":"c","text":"Quinine"},{"id":"d","text":"Artemisinin"}],"answerId":"a","explanation":"Primaquine causes oxidative hemolysis in G6PD-deficient patients due to its oxidant properties.","kind":"recall","origin":"ai"},{"id":"hhl-antimalarials-mechanisms~ai-1","moduleId":"hhl-antimalarials-mechanisms","stem":"What is the primary mechanism of action of chloroquine in treating malaria?","options":[{"id":"a","text":"Inhibition of heme detoxification"},{"id":"b","text":"Cleavage of endoperoxide bridge"},{"id":"c","text":"Inhibition of DHFR enzyme"},{"id":"d","text":"Inhibition of protein synthesis"}],"answerId":"a","explanation":"Chloroquine inhibits the conversion of toxic heme to hemozoin, leading to parasite death.","kind":"mechanism","origin":"ai"},{"id":"hhl-antimalarials-mechanisms~ai-2","moduleId":"hhl-antimalarials-mechanisms","stem":"A patient on quinine therapy develops tinnitus, headache, and nausea. What is the likely cause?","options":[{"id":"a","text":"Cinchonism"},{"id":"b","text":"G6PD deficiency"},{"id":"c","text":"QT prolongation"},{"id":"d","text":"Neuropsychiatric symptoms"}],"answerId":"a","explanation":"These symptoms are indicative of cinchonism, a dose-related toxicity of quinine.","kind":"clinical","origin":"ai"},{"id":"hhl-antimalarials-mechanisms~ai-3","moduleId":"hhl-antimalarials-mechanisms","stem":"Which antimalarial drug requires G6PD testing before administration to prevent severe adverse effects?","options":[{"id":"a","text":"Primaquine"},{"id":"b","text":"Artemisinin"},{"id":"c","text":"Mefloquine"},{"id":"d","text":"Lumefantrine"}],"answerId":"a","explanation":"Primaquine can cause severe oxidative hemolysis in G6PD-deficient individuals, necessitating testing.","kind":"trap","origin":"ai"},{"id":"hhl-antimalarials-mechanisms~ai-4","moduleId":"hhl-antimalarials-mechanisms","stem":"Which stage of the malaria parasite life cycle is targeted by artemisinins?","options":[{"id":"a","text":"Erythrocytic stage"},{"id":"b","text":"Liver hypnozoites"},{"id":"c","text":"Gametocytes"},{"id":"d","text":"Sporozoites"}],"answerId":"a","explanation":"Artemisinins are blood schizonticides that target the erythrocytic stage of the malaria parasite.","kind":"recall","origin":"ai"},{"id":"hhl-antimalarials-mechanisms~ai-5","moduleId":"hhl-antimalarials-mechanisms","stem":"A patient with malaria is treated with chloroquine but shows no improvement. What is the most likely reason?","options":[{"id":"a","text":"PfCRT-mediated resistance"},{"id":"b","text":"G6PD deficiency"},{"id":"c","text":"Inadequate dosing"},{"id":"d","text":"Concurrent bacterial infection"}],"answerId":"a","explanation":"PfCRT-mediated resistance is common in P. falciparum, making chloroquine ineffective.","kind":"trap","origin":"ai"},{"id":"hhl-antimalarials-mechanisms~ai-6","moduleId":"hhl-antimalarials-mechanisms","stem":"How do artemisinins exert their antimalarial effect at the cellular level?","options":[{"id":"a","text":"Cleavage of endoperoxide bridge by heme"},{"id":"b","text":"Blocking folate synthesis"},{"id":"c","text":"Inhibiting protein synthesis"},{"id":"d","text":"Disrupting DNA replication"}],"answerId":"a","explanation":"Artemisinins' endoperoxide bridge is cleaved by heme, generating free radicals that kill the parasite.","kind":"mechanism","linkedModuleIds":["cell-injury-free-radicals"],"origin":"ai"},{"id":"hhl-antimalarials-mechanisms~ai-7","moduleId":"hhl-antimalarials-mechanisms","stem":"Which drug combination is used for radical cure of P. vivax malaria?","options":[{"id":"a","text":"Chloroquine and primaquine"},{"id":"b","text":"Artemisinin and mefloquine"},{"id":"c","text":"Quinine and doxycycline"},{"id":"d","text":"Lumefantrine and artemether"}],"answerId":"a","explanation":"Chloroquine treats the blood stage, while primaquine targets liver hypnozoites for radical cure.","kind":"integration","linkedModuleIds":["hhl-antimalarial-treatment"],"origin":"ai"}],"hhl-antimalarial-treatment":[{"id":"hhl-antimalarial-treatment~ai-0","moduleId":"hhl-antimalarial-treatment","stem":"What is the first-line treatment for uncomplicated P. falciparum malaria worldwide?","options":[{"id":"a","text":"Artemisinin-based combination therapy (ACT)"},{"id":"b","text":"Chloroquine"},{"id":"c","text":"Primaquine"},{"id":"d","text":"IV artesunate"}],"answerId":"a","explanation":"ACT is recommended as the first-line treatment for uncomplicated P. falciparum malaria globally.","kind":"recall","origin":"ai"},{"id":"hhl-antimalarial-treatment~ai-1","moduleId":"hhl-antimalarial-treatment","stem":"A patient with P. vivax malaria has a normal G6PD test result. What additional treatment should be given to prevent relapse?","options":[{"id":"a","text":"Chloroquine alone"},{"id":"b","text":"Primaquine"},{"id":"c","text":"IV artesunate"},{"id":"d","text":"Mefloquine"}],"answerId":"b","explanation":"Primaquine is added for radical cure to eliminate hypnozoites and prevent relapse.","kind":"clinical","origin":"ai"},{"id":"hhl-antimalarial-treatment~ai-2","moduleId":"hhl-antimalarial-treatment","stem":"A patient with severe malaria is unable to take oral medication. What is the appropriate initial treatment?","options":[{"id":"a","text":"Oral ACT"},{"id":"b","text":"IV artesunate"},{"id":"c","text":"Chloroquine"},{"id":"d","text":"Primaquine"}],"answerId":"b","explanation":"IV artesunate is necessary for severe malaria due to its rapid action and the patient's inability to absorb oral medication.","kind":"trap","origin":"ai"},{"id":"hhl-antimalarial-treatment~ai-3","moduleId":"hhl-antimalarial-treatment","stem":"Which of the following is a sign of artemisinin resistance in malaria treatment?","options":[{"id":"a","text":"Immediate parasite clearance"},{"id":"b","text":"Parasites present on day 3 of ACT"},{"id":"c","text":"Severe anemia"},{"id":"d","text":"Hypoglycemia"}],"answerId":"b","explanation":"Parasites still present on day 3 of ACT suggest delayed clearance and possible artemisinin resistance.","kind":"mechanism","origin":"ai"},{"id":"hhl-antimalarial-treatment~ai-4","moduleId":"hhl-antimalarial-treatment","stem":"A traveler to a malaria-endemic region is prescribed chemoprophylaxis. Which of the following is true regarding its effect on P. vivax hypnozoites?","options":[{"id":"a","text":"It clears hypnozoites"},{"id":"b","text":"It suppresses the blood stage only"},{"id":"c","text":"It prevents relapse without additional drugs"},{"id":"d","text":"It is unnecessary if G6PD is normal"}],"answerId":"b","explanation":"Chemoprophylaxis suppresses the blood stage but does not clear hypnozoites; primaquine is needed for that.","kind":"trap","origin":"ai"},{"id":"hhl-antimalarial-treatment~ai-5","moduleId":"hhl-antimalarial-treatment","stem":"In the context of severe falciparum malaria, what is the initial treatment step according to the linked module 'hhl-severe-falciparum-malaria'?","options":[{"id":"a","text":"Oral ACT"},{"id":"b","text":"IV artesunate"},{"id":"c","text":"Chloroquine"},{"id":"d","text":"Mefloquine"}],"answerId":"b","explanation":"The linked module specifies IV artesunate as the initial treatment for severe falciparum malaria.","kind":"integration","linkedModuleIds":["hhl-severe-falciparum-malaria"],"origin":"ai"},{"id":"hhl-antimalarial-treatment~ai-6","moduleId":"hhl-antimalarial-treatment","stem":"How does the presence of Kelch13 mutations in the Greater Mekong Subregion affect malaria treatment?","options":[{"id":"a","text":"Increases efficacy of chloroquine"},{"id":"b","text":"Requires higher doses of primaquine"},{"id":"c","text":"Indicates potential artemisinin resistance"},{"id":"d","text":"Negates the need for ACT"}],"answerId":"c","explanation":"Kelch13 mutations are associated with artemisinin resistance, necessitating careful treatment choices.","kind":"mechanism","origin":"ai"},{"id":"hhl-antimalarial-treatment~ai-7","moduleId":"hhl-antimalarial-treatment","stem":"What is the primary action of primaquine in the treatment of P. vivax malaria?","options":[{"id":"a","text":"Clears blood-stage parasites"},{"id":"b","text":"Prevents initial infection"},{"id":"c","text":"Eliminates liver hypnozoites"},{"id":"d","text":"Reduces fever"}],"answerId":"c","explanation":"Primaquine targets liver hypnozoites to prevent relapse in P. vivax malaria.","kind":"recall","origin":"ai"},{"id":"hhl-antimalarial-treatment~ai-8","moduleId":"hhl-antimalarial-treatment","stem":"Which of the following modules would provide detailed mechanisms of action for antimalarial drugs?","options":[{"id":"a","text":"hhl-severe-falciparum-malaria"},{"id":"b","text":"add-anatomy-of-the-greater-and-lesser-sciatic-foramina"},{"id":"c","text":"hhl-antimalarials-mechanisms"},{"id":"d","text":"hhl-antimalarial-treatment"}],"answerId":"c","explanation":"The 'hhl-antimalarials-mechanisms' module focuses on the mechanisms of antimalarial drugs.","kind":"integration","linkedModuleIds":["hhl-antimalarials-mechanisms"],"origin":"ai"}],"ifh-clinical-communication-skills":[{"id":"ifh-clinical-communication-skills~ai-0","moduleId":"ifh-clinical-communication-skills","stem":"Which of the following best describes the initial step in the Calgary–Cambridge guide to medical consultations?","options":[{"id":"a","text":"Initiate the session"},{"id":"b","text":"Gather information"},{"id":"c","text":"Explain and plan"},{"id":"d","text":"Close the session"}],"answerId":"a","explanation":"The first step is to initiate the session, setting the stage for effective communication.","kind":"recall","origin":"ai"},{"id":"ifh-clinical-communication-skills~ai-1","moduleId":"ifh-clinical-communication-skills","stem":"What is the primary purpose of using open questions at the start of a patient consultation?","options":[{"id":"a","text":"To gather specific details"},{"id":"b","text":"To elicit the patient's full story"},{"id":"c","text":"To confirm the diagnosis"},{"id":"d","text":"To provide structure"}],"answerId":"b","explanation":"Open questions are used initially to allow patients to share their complete narrative before narrowing down with closed questions.","kind":"mechanism","origin":"ai"},{"id":"ifh-clinical-communication-skills~ai-2","moduleId":"ifh-clinical-communication-skills","stem":"During a consultation, a doctor says, 'I can see this has been frightening for you.' What communication skill is being demonstrated?","options":[{"id":"a","text":"Providing structure"},{"id":"b","text":"Active listening"},{"id":"c","text":"Empathy"},{"id":"d","text":"Signposting"}],"answerId":"c","explanation":"This statement demonstrates empathy by acknowledging and validating the patient's emotions.","kind":"recall","origin":"ai"},{"id":"ifh-clinical-communication-skills~ai-3","moduleId":"ifh-clinical-communication-skills","stem":"Why is it important to avoid starting a consultation with closed questions?","options":[{"id":"a","text":"They are less efficient"},{"id":"b","text":"They may miss the patient's real concern"},{"id":"c","text":"They are too time-consuming"},{"id":"d","text":"They confuse the patient"}],"answerId":"b","explanation":"Starting with closed questions can prematurely narrow the consultation and miss important aspects of the patient's story.","kind":"trap","origin":"ai"},{"id":"ifh-clinical-communication-skills~ai-4","moduleId":"ifh-clinical-communication-skills","stem":"In the context of clinical communication, what does the acronym ICE stand for?","options":[{"id":"a","text":"Ideas, Concerns, Expectations"},{"id":"b","text":"Identify, Communicate, Empathize"},{"id":"c","text":"Initiate, Clarify, Explain"},{"id":"d","text":"Investigate, Confirm, Evaluate"}],"answerId":"a","explanation":"ICE stands for Ideas, Concerns, Expectations, which helps in understanding the patient's perspective.","kind":"recall","origin":"ai"},{"id":"ifh-clinical-communication-skills~ai-5","moduleId":"ifh-clinical-communication-skills","stem":"How does the Calgary–Cambridge guide facilitate the integration of motivational interviewing techniques?","options":[{"id":"a","text":"By focusing solely on the patient's concerns"},{"id":"b","text":"By emphasizing empathy and shared decision-making"},{"id":"c","text":"By prioritizing diagnosis over patient input"},{"id":"d","text":"By using closed questions to direct the conversation"}],"answerId":"b","explanation":"The guide's emphasis on empathy and shared decision-making aligns with the principles of motivational interviewing.","kind":"integration","linkedModuleIds":["ifh-motivational-interviewing"],"origin":"ai"},{"id":"ifh-clinical-communication-skills~ai-6","moduleId":"ifh-clinical-communication-skills","stem":"In a patient-centered clinical method, how does the use of open questions relate to understanding the difference between disease and illness?","options":[{"id":"a","text":"Open questions help identify the biological cause of disease"},{"id":"b","text":"Open questions reveal the patient's personal experience of illness"},{"id":"c","text":"Open questions are used to confirm clinical signs"},{"id":"d","text":"Open questions limit the scope of the consultation"}],"answerId":"b","explanation":"Open questions allow the patient to express their personal experience, which is crucial for distinguishing between disease and illness.","kind":"integration","linkedModuleIds":["ifh-disease-vs-illness"],"origin":"ai"}],"ifh-disease-vs-illness":[{"id":"ifh-disease-vs-illness~ai-0","moduleId":"ifh-disease-vs-illness","stem":"Which of the following best describes the difference between disease and illness?","options":[{"id":"a","text":"Disease is the objective pathology; illness is the subjective experience"},{"id":"b","text":"Disease is the subjective experience; illness is the objective pathology"},{"id":"c","text":"Disease and illness are both objective pathologies"},{"id":"d","text":"Disease and illness are both subjective experiences"}],"answerId":"a","explanation":"Disease refers to the biomedical pathology, while illness refers to the patient's subjective experience.","kind":"recall","origin":"ai"},{"id":"ifh-disease-vs-illness~ai-1","moduleId":"ifh-disease-vs-illness","stem":"A patient with asymptomatic hypertension is an example of which concept?","options":[{"id":"a","text":"Disease without illness"},{"id":"b","text":"Illness without disease"},{"id":"c","text":"Both disease and illness"},{"id":"d","text":"Neither disease nor illness"}],"answerId":"a","explanation":"Asymptomatic hypertension is a condition where the disease is present, but the patient does not experience illness.","kind":"mechanism","origin":"ai"},{"id":"ifh-disease-vs-illness~ai-2","moduleId":"ifh-disease-vs-illness","stem":"What is the primary purpose of using the FIFE framework in patient consultations?","options":[{"id":"a","text":"To diagnose the disease"},{"id":"b","text":"To explore the patient's illness experience"},{"id":"c","text":"To determine the treatment plan"},{"id":"d","text":"To assess the patient's physical health"}],"answerId":"b","explanation":"FIFE is used to explore the patient's feelings, ideas, function, and expectations regarding their illness.","kind":"recall","origin":"ai"},{"id":"ifh-disease-vs-illness~ai-3","moduleId":"ifh-disease-vs-illness","stem":"Why might a patient with well-controlled diabetes still feel unwell?","options":[{"id":"a","text":"The disease is not managed"},{"id":"b","text":"The illness experience is not addressed"},{"id":"c","text":"The treatment is ineffective"},{"id":"d","text":"The patient lacks understanding of the condition"}],"answerId":"b","explanation":"Even if the disease is controlled, the patient's subjective experience of illness may not be addressed, affecting their well-being.","kind":"trap","origin":"ai"},{"id":"ifh-disease-vs-illness~ai-4","moduleId":"ifh-disease-vs-illness","stem":"Which of the following is a key principle of patient-centered care?","options":[{"id":"a","text":"Focusing solely on disease management"},{"id":"b","text":"Integrating disease and illness perspectives"},{"id":"c","text":"Prioritizing physician's perspective"},{"id":"d","text":"Ignoring patient's expectations"}],"answerId":"b","explanation":"Patient-centered care involves integrating both the disease and the illness perspectives to address the patient's overall experience.","kind":"clinical","origin":"ai"},{"id":"ifh-disease-vs-illness~ai-5","moduleId":"ifh-disease-vs-illness","stem":"How does the biopsychosocial model relate to the concept of illness?","options":[{"id":"a","text":"It focuses solely on biological factors"},{"id":"b","text":"It integrates biological, psychological, and social factors"},{"id":"c","text":"It disregards psychological factors"},{"id":"d","text":"It only considers social factors"}],"answerId":"b","explanation":"The biopsychosocial model integrates biological, psychological, and social factors, aligning with the comprehensive understanding of illness.","kind":"integration","linkedModuleIds":["ifh-biopsychosocial-model"],"origin":"ai"},{"id":"ifh-disease-vs-illness~ai-6","moduleId":"ifh-disease-vs-illness","stem":"In the context of family medicine principles, why is it important to distinguish between disease and illness?","options":[{"id":"a","text":"To focus on disease management only"},{"id":"b","text":"To enhance patient-centered care"},{"id":"c","text":"To prioritize medication adherence"},{"id":"d","text":"To minimize patient interaction"}],"answerId":"b","explanation":"Distinguishing between disease and illness enhances patient-centered care, a core principle of family medicine.","kind":"integration","linkedModuleIds":["ifh-family-medicine-principles"],"origin":"ai"}],"ifh-family-medicine-principles":[{"id":"ifh-family-medicine-principles~ai-0","moduleId":"ifh-family-medicine-principles","stem":"Which of the following best describes the role of a family physician?","options":[{"id":"a","text":"Coordinator of comprehensive, continuous care across all ages"},{"id":"b","text":"Specialist in internal medicine with a focus on chronic diseases"},{"id":"c","text":"Provider of emergency care in acute settings"},{"id":"d","text":"Expert in surgical interventions for common conditions"}],"answerId":"a","explanation":"Family physicians provide comprehensive, continuous care across all ages, focusing on the whole person within their family and community context.","kind":"recall","origin":"ai"},{"id":"ifh-family-medicine-principles~ai-1","moduleId":"ifh-family-medicine-principles","stem":"A family physician is seeing a patient with new-onset hypertension. Which approach aligns with the biopsychosocial model?","options":[{"id":"a","text":"Prescribing antihypertensive medication immediately"},{"id":"b","text":"Referring the patient to a cardiologist for further evaluation"},{"id":"c","text":"Discussing the patient's lifestyle, stress levels, and family support"},{"id":"d","text":"Ordering a full panel of cardiac tests to rule out heart disease"}],"answerId":"c","explanation":"The biopsychosocial model considers biological, psychological, and social factors, so discussing lifestyle and stress is appropriate.","kind":"mechanism","linkedModuleIds":["ifh-biopsychosocial-model"],"origin":"ai"},{"id":"ifh-family-medicine-principles~ai-2","moduleId":"ifh-family-medicine-principles","stem":"What is a common misconception about family medicine?","options":[{"id":"a","text":"It is less expert than internal medicine"},{"id":"b","text":"It focuses on first-contact, continuous care"},{"id":"c","text":"It provides comprehensive care across all life stages"},{"id":"d","text":"It integrates care around the patient and family"}],"answerId":"a","explanation":"Family medicine is often misunderstood as less expert, but it is a distinct discipline focusing on breadth and continuity.","kind":"trap","origin":"ai"},{"id":"ifh-family-medicine-principles~ai-3","moduleId":"ifh-family-medicine-principles","stem":"A family physician is coordinating care for a patient with diabetes, hypertension, and depression. What principle of family medicine does this illustrate?","options":[{"id":"a","text":"First-contact care"},{"id":"b","text":"Continuity of care"},{"id":"c","text":"Comprehensiveness of care"},{"id":"d","text":"Community orientation"}],"answerId":"c","explanation":"Comprehensiveness involves managing multiple conditions across different domains of health.","kind":"clinical","origin":"ai"},{"id":"ifh-family-medicine-principles~ai-4","moduleId":"ifh-family-medicine-principles","stem":"In the context of family medicine, what does 'community-oriented primary care' entail?","options":[{"id":"a","text":"Focusing solely on individual patient needs"},{"id":"b","text":"Providing care only for acute conditions"},{"id":"c","text":"Considering the health of the entire practice population"},{"id":"d","text":"Specializing in community health outreach programs"}],"answerId":"c","explanation":"Community-oriented primary care involves considering the health of the entire practice population, not just individual patients.","kind":"recall","origin":"ai"},{"id":"ifh-family-medicine-principles~ai-5","moduleId":"ifh-family-medicine-principles","stem":"How does the family physician's role as a coordinator benefit the patient during the patient journey?","options":[{"id":"a","text":"By referring patients to specialists for every condition"},{"id":"b","text":"By integrating care from various specialists around the patient's needs"},{"id":"c","text":"By focusing solely on acute care needs"},{"id":"d","text":"By providing only preventive care services"}],"answerId":"b","explanation":"The family physician integrates care from various specialists to ensure it aligns with the patient's overall needs.","kind":"integration","linkedModuleIds":["ifh-patient-journey"],"origin":"ai"},{"id":"ifh-family-medicine-principles~ai-6","moduleId":"ifh-family-medicine-principles","stem":"Which aspect of family medicine is highlighted when a physician addresses a patient's health concerns in the context of their family dynamics?","options":[{"id":"a","text":"First-contact care"},{"id":"b","text":"Person-centred care"},{"id":"c","text":"Community orientation"},{"id":"d","text":"Acute care specialization"}],"answerId":"b","explanation":"Person-centred care involves understanding the patient's health in the context of their family and social environment.","kind":"integration","linkedModuleIds":["ifh-family-health-impact"],"origin":"ai"}],"ifh-patient-journey":[{"id":"ifh-patient-journey~ai-0","moduleId":"ifh-patient-journey","stem":"Which of the following best describes the concept of 'the symptom iceberg' in patient care?","options":[{"id":"a","text":"Most symptoms are managed at home and never reach a doctor."},{"id":"b","text":"Symptoms are always reported immediately to healthcare providers."},{"id":"c","text":"All symptoms are documented in medical records."},{"id":"d","text":"Symptoms are only significant if they lead to hospital admission."}],"answerId":"a","explanation":"The symptom iceberg refers to the phenomenon where most symptoms are self-managed and do not reach medical attention.","kind":"recall","origin":"ai"},{"id":"ifh-patient-journey~ai-1","moduleId":"ifh-patient-journey","stem":"What is the primary role of primary care in the patient journey?","options":[{"id":"a","text":"To provide specialized care and treatment."},{"id":"b","text":"To act as the first point of contact and coordinate care."},{"id":"c","text":"To manage only chronic diseases."},{"id":"d","text":"To perform surgical interventions."}],"answerId":"b","explanation":"Primary care acts as the first point of contact and coordinates further care, reducing fragmentation and duplication.","kind":"mechanism","origin":"ai"},{"id":"ifh-patient-journey~ai-2","moduleId":"ifh-patient-journey","stem":"Which type of continuity involves having a coherent care plan across multiple providers?","options":[{"id":"a","text":"Informational continuity"},{"id":"b","text":"Relational continuity"},{"id":"c","text":"Management continuity"},{"id":"d","text":"Geographic continuity"}],"answerId":"c","explanation":"Management continuity ensures that a coherent care plan is followed across different providers.","kind":"trap","origin":"ai"},{"id":"ifh-patient-journey~ai-3","moduleId":"ifh-patient-journey","stem":"A patient is discharged from the hospital but does not receive follow-up instructions. Which aspect of the patient journey is most at risk?","options":[{"id":"a","text":"First contact"},{"id":"b","text":"Diagnosis"},{"id":"c","text":"Coordination"},{"id":"d","text":"Symptom management"}],"answerId":"c","explanation":"Coordination is at risk as transitions of care, like discharge, are high-risk gaps where information can be lost.","kind":"clinical","origin":"ai"},{"id":"ifh-patient-journey~ai-4","moduleId":"ifh-patient-journey","stem":"In the context of the patient journey, what is the significance of 'follow the patient, not the disease'?","options":[{"id":"a","text":"Focus on treating diseases rather than symptoms."},{"id":"b","text":"Ensure continuity across episodes and settings."},{"id":"c","text":"Prioritize acute care over chronic care."},{"id":"d","text":"Emphasize disease prevention over treatment."}],"answerId":"b","explanation":"Following the patient ensures continuity across different episodes and settings, maintaining a comprehensive view of care.","kind":"mechanism","origin":"ai"},{"id":"ifh-patient-journey~ai-5","moduleId":"ifh-patient-journey","stem":"How does the concept of 'lay referral networks' influence the decision to seek medical help?","options":[{"id":"a","text":"They encourage immediate medical consultation for all symptoms."},{"id":"b","text":"They often delay help-seeking by providing alternative explanations."},{"id":"c","text":"They have no impact on medical decision-making."},{"id":"d","text":"They ensure that all symptoms are reported to healthcare providers."}],"answerId":"b","explanation":"Lay referral networks can delay help-seeking by offering alternative explanations or reassurance, impacting when and if medical help is sought.","kind":"integration","linkedModuleIds":["ifh-disease-vs-illness"],"origin":"ai"},{"id":"ifh-patient-journey~ai-6","moduleId":"ifh-patient-journey","stem":"Which of the following is a barrier to accessing primary care as the first point of contact?","options":[{"id":"a","text":"Availability of specialized care"},{"id":"b","text":"Financial, geographic, and cultural barriers"},{"id":"c","text":"Presence of chronic diseases"},{"id":"d","text":"Access to emergency services"}],"answerId":"b","explanation":"Financial, geographic, and cultural barriers can prevent patients from accessing primary care as the first point of contact.","kind":"integration","linkedModuleIds":["ifh-special-populations-approach"],"origin":"ai"}],"ifh-patient-centered-clinical-method":[{"id":"ifh-patient-centered-clinical-method~ai-0","moduleId":"ifh-patient-centered-clinical-method","stem":"Which component of the patient-centered clinical method involves understanding the patient's family, work, and cultural context?","options":[{"id":"a","text":"Explore disease and illness"},{"id":"b","text":"Understand the whole person"},{"id":"c","text":"Find common ground"},{"id":"d","text":"Enhance the relationship"}],"answerId":"b","explanation":"Understanding the whole person involves placing the problem in the context of family, work, culture, and life stage.","kind":"recall","origin":"ai"},{"id":"ifh-patient-centered-clinical-method~ai-1","moduleId":"ifh-patient-centered-clinical-method","stem":"In the patient-centered clinical method, what is the purpose of finding common ground?","options":[{"id":"a","text":"To agree on the treatment plan"},{"id":"b","text":"To ensure the patient leads the consultation"},{"id":"c","text":"To negotiate problems, goals, and roles"},{"id":"d","text":"To enhance the patient-doctor relationship"}],"answerId":"c","explanation":"Finding common ground involves negotiating agreement on the problems, goals, and roles between the doctor and patient.","kind":"mechanism","origin":"ai"},{"id":"ifh-patient-centered-clinical-method~ai-2","moduleId":"ifh-patient-centered-clinical-method","stem":"A patient demands antibiotics for a viral infection. How should a patient-centered approach address this?","options":[{"id":"a","text":"Prescribe the antibiotics as requested"},{"id":"b","text":"Explain why antibiotics are not needed and find a mutual plan"},{"id":"c","text":"Ignore the request and focus on the exam"},{"id":"d","text":"Refer the patient to a specialist"}],"answerId":"b","explanation":"A patient-centered approach involves negotiating a mutual plan that integrates both perspectives, not simply fulfilling demands.","kind":"trap","origin":"ai"},{"id":"ifh-patient-centered-clinical-method~ai-3","moduleId":"ifh-patient-centered-clinical-method","stem":"Which of the following best describes a therapeutic aspect of the patient-doctor relationship?","options":[{"id":"a","text":"Prescribing medication"},{"id":"b","text":"Providing continuous care"},{"id":"c","text":"Performing diagnostic tests"},{"id":"d","text":"Referring to specialists"}],"answerId":"b","explanation":"Continuity, trust, and empathy in the patient-doctor relationship can be therapeutic and improve outcomes.","kind":"clinical","origin":"ai"},{"id":"ifh-patient-centered-clinical-method~ai-4","moduleId":"ifh-patient-centered-clinical-method","stem":"How does the patient-centered clinical method integrate with the biopsychosocial model?","options":[{"id":"a","text":"By focusing solely on the biological aspects of disease"},{"id":"b","text":"By considering psychological and social factors in patient care"},{"id":"c","text":"By prioritizing medical interventions over patient preferences"},{"id":"d","text":"By emphasizing rapid diagnosis and treatment"}],"answerId":"b","explanation":"The patient-centered clinical method aligns with the biopsychosocial model by considering psychological and social factors in addition to biological ones.","kind":"integration","linkedModuleIds":["ifh-biopsychosocial-model"],"origin":"ai"},{"id":"ifh-patient-centered-clinical-method~ai-5","moduleId":"ifh-patient-centered-clinical-method","stem":"In family medicine, how does the patient-centered clinical method enhance the therapeutic relationship?","options":[{"id":"a","text":"By focusing on acute care only"},{"id":"b","text":"By ensuring the patient always leads the consultation"},{"id":"c","text":"By building trust and continuity over time"},{"id":"d","text":"By prioritizing specialist referrals"}],"answerId":"c","explanation":"In family medicine, the patient-centered method enhances the relationship through trust and continuity, which are key principles.","kind":"integration","linkedModuleIds":["ifh-family-medicine-principles"],"origin":"ai"}],"ifh-genogram":[{"id":"ifh-genogram~ai-0","moduleId":"ifh-genogram","stem":"What symbol is used to represent a male in a genogram?","options":[{"id":"a","text":"Square"},{"id":"b","text":"Circle"},{"id":"c","text":"Triangle"},{"id":"d","text":"Diamond"}],"answerId":"a","explanation":"In a genogram, a square represents a male, while a circle represents a female.","kind":"recall","origin":"ai"},{"id":"ifh-genogram~ai-1","moduleId":"ifh-genogram","stem":"Which line symbol in a genogram indicates a divorce?","options":[{"id":"a","text":"Solid line"},{"id":"b","text":"Dashed line"},{"id":"c","text":"Single slash (/)"},{"id":"d","text":"Double slash (//)"}],"answerId":"d","explanation":"A double slash (//) on the marriage line indicates a divorce in a genogram.","kind":"recall","origin":"ai"},{"id":"ifh-genogram~ai-2","moduleId":"ifh-genogram","stem":"What additional information does a genogram provide compared to a pedigree?","options":[{"id":"a","text":"Genetic inheritance"},{"id":"b","text":"Medical history"},{"id":"c","text":"Emotional bonds and psychosocial data"},{"id":"d","text":"Ancestral lineage"}],"answerId":"c","explanation":"A genogram includes emotional bonds and psychosocial data, unlike a pedigree which focuses on genetic inheritance.","kind":"trap","origin":"ai"},{"id":"ifh-genogram~ai-3","moduleId":"ifh-genogram","stem":"In a genogram, what does an X through a symbol signify?","options":[{"id":"a","text":"Birth"},{"id":"b","text":"Marriage"},{"id":"c","text":"Death"},{"id":"d","text":"Divorce"}],"answerId":"c","explanation":"An X through a symbol in a genogram indicates that the individual is deceased.","kind":"recall","origin":"ai"},{"id":"ifh-genogram~ai-4","moduleId":"ifh-genogram","stem":"When is it most appropriate to use a genogram in clinical practice?","options":[{"id":"a","text":"For genetic counseling only"},{"id":"b","text":"In high-risk families and chronic disease cases"},{"id":"c","text":"For documenting family trees"},{"id":"d","text":"In acute trauma cases"}],"answerId":"b","explanation":"Genograms are particularly useful in high-risk families, chronic disease cases, and when there is psychosocial complexity.","kind":"clinical","origin":"ai"},{"id":"ifh-genogram~ai-5","moduleId":"ifh-genogram","stem":"How does a genogram assist in identifying hereditary risks?","options":[{"id":"a","text":"By listing all family members"},{"id":"b","text":"By showing vertical disease clusters"},{"id":"c","text":"By recording only living relatives"},{"id":"d","text":"By focusing on immediate family only"}],"answerId":"b","explanation":"Vertical disease clusters in a genogram can indicate hereditary or genetic risks across generations.","kind":"mechanism","origin":"ai"},{"id":"ifh-genogram~ai-6","moduleId":"ifh-genogram","stem":"Which module is directly applied when using genograms to assess family health impacts?","options":[{"id":"a","text":"Bioinformatics: Tools and Applications"},{"id":"b","text":"Host Types & Parasite Relationships"},{"id":"c","text":"Family & Household: Definitions & Types"},{"id":"d","text":"How Families Shape Health"}],"answerId":"d","explanation":"The module 'How Families Shape Health' is directly applied when using genograms to assess family health impacts.","kind":"integration","linkedModuleIds":["ifh-family-health-impact"],"origin":"ai"},{"id":"ifh-genogram~ai-7","moduleId":"ifh-genogram","stem":"Which family assessment tool module is a peer to the genogram module?","options":[{"id":"a","text":"Bioinformatics: Tools and Applications"},{"id":"b","text":"Family Assessment Tools"},{"id":"c","text":"How Families Shape Health"},{"id":"d","text":"Host Types & Parasite Relationships"}],"answerId":"b","explanation":"The 'Family Assessment Tools' module is a peer to the genogram module.","kind":"integration","linkedModuleIds":["ifh-family-assessment-tools"],"origin":"ai"}],"ifh-family-definitions-types":[{"id":"ifh-family-definitions-types~ai-0","moduleId":"ifh-family-definitions-types","stem":"Which of the following best describes a household?","options":[{"id":"a","text":"A group of people linked by blood, marriage, or adoption"},{"id":"b","text":"A group of people who share a dwelling and resources"},{"id":"c","text":"A nuclear family living separately from extended relatives"},{"id":"d","text":"A family unit consisting of a single parent and children"}],"answerId":"b","explanation":"A household consists of people who share a dwelling and resources, which may include non-kin.","kind":"recall","origin":"ai"},{"id":"ifh-family-definitions-types~ai-1","moduleId":"ifh-family-definitions-types","stem":"In the context of family types, what characterizes a blended family?","options":[{"id":"a","text":"A family with grandparents raising grandchildren"},{"id":"b","text":"A family formed when remarriage merges children from prior unions"},{"id":"c","text":"A family consisting of a couple without children"},{"id":"d","text":"A family with same-sex parents"}],"answerId":"b","explanation":"A blended family forms when remarriage merges children from prior unions, creating new parental and sibling roles.","kind":"mechanism","origin":"ai"},{"id":"ifh-family-definitions-types~ai-2","moduleId":"ifh-family-definitions-types","stem":"Which demographic trend is currently observed in Thai households?","options":[{"id":"a","text":"Increase in extended family households"},{"id":"b","text":"Decrease in single-person households"},{"id":"c","text":"Shift from extended to nuclear and single-person households"},{"id":"d","text":"Increase in fertility rates"}],"answerId":"c","explanation":"Thailand is experiencing a shift from extended family households to more nuclear and single-person households.","kind":"recall","origin":"ai"},{"id":"ifh-family-definitions-types~ai-3","moduleId":"ifh-family-definitions-types","stem":"How does the concept of a 'skip-generation family' primarily arise in Thailand?","options":[{"id":"a","text":"Due to urbanization and increased fertility rates"},{"id":"b","text":"As a result of grandparents raising grandchildren due to parental migration"},{"id":"c","text":"From the merging of two nuclear families"},{"id":"d","text":"Through the increase in single-parent households"}],"answerId":"b","explanation":"Skip-generation families occur when grandparents raise grandchildren, often due to parental labour migration.","kind":"mechanism","origin":"ai"},{"id":"ifh-family-definitions-types~ai-4","moduleId":"ifh-family-definitions-types","stem":"Which family type is most likely to impact caregiving capacity and resources in a clinical setting?","options":[{"id":"a","text":"Nuclear family"},{"id":"b","text":"Extended family"},{"id":"c","text":"Single-person household"},{"id":"d","text":"Blended family"}],"answerId":"c","explanation":"Single-person households may have limited caregiving capacity and resources, impacting clinical care.","kind":"clinical","origin":"ai"},{"id":"ifh-family-definitions-types~ai-5","moduleId":"ifh-family-definitions-types","stem":"When assessing a patient's family structure, which tool is most appropriate to use?","options":[{"id":"a","text":"Genogram"},{"id":"b","text":"Thyroid function test"},{"id":"c","text":"Electrocardiogram"},{"id":"d","text":"Complete blood count"}],"answerId":"a","explanation":"A genogram is used to record and assess family structure and relationships.","kind":"integration","linkedModuleIds":["ifh-genogram"],"origin":"ai"},{"id":"ifh-family-definitions-types~ai-6","moduleId":"ifh-family-definitions-types","stem":"How might a shift towards nuclear and single-person households affect family health dynamics?","options":[{"id":"a","text":"Increase in shared caregiving responsibilities"},{"id":"b","text":"Decrease in social support networks"},{"id":"c","text":"Increase in family size"},{"id":"d","text":"Decrease in urban migration"}],"answerId":"b","explanation":"A shift towards nuclear and single-person households can lead to decreased social support networks, affecting family health dynamics.","kind":"integration","linkedModuleIds":["ifh-family-health-impact"],"origin":"ai"}],"ifh-family-assessment-tools":[{"id":"ifh-family-assessment-tools~ai-0","moduleId":"ifh-family-assessment-tools","stem":"What does a Family APGAR score of 3 indicate?","options":[{"id":"a","text":"Severe family dysfunction"},{"id":"b","text":"Moderate family dysfunction"},{"id":"c","text":"High family function"},{"id":"d","text":"Objective family health"}],"answerId":"a","explanation":"A score of 0-3 on the Family APGAR indicates severe perceived family dysfunction.","kind":"recall","origin":"ai"},{"id":"ifh-family-assessment-tools~ai-1","moduleId":"ifh-family-assessment-tools","stem":"Which family assessment tool is best for evaluating a family's coping resources?","options":[{"id":"a","text":"Family APGAR"},{"id":"b","text":"SCREEM"},{"id":"c","text":"Family life-cycle stage"},{"id":"d","text":"Family circle"}],"answerId":"b","explanation":"SCREEM inventories a family's Social, Cultural, Religious, Economic, Educational, and Medical resources.","kind":"recall","origin":"ai"},{"id":"ifh-family-assessment-tools~ai-2","moduleId":"ifh-family-assessment-tools","stem":"A patient draws a family circle with large circles for parents and small circles for siblings. What does this suggest?","options":[{"id":"a","text":"Parents have more power"},{"id":"b","text":"Siblings are closer emotionally"},{"id":"c","text":"Siblings have more power"},{"id":"d","text":"Parents are less important"}],"answerId":"a","explanation":"In the family circle, larger circles indicate more importance or power.","kind":"clinical","origin":"ai"},{"id":"ifh-family-assessment-tools~ai-3","moduleId":"ifh-family-assessment-tools","stem":"Which statement about the Family APGAR is correct?","options":[{"id":"a","text":"It objectively measures family health"},{"id":"b","text":"It diagnoses family dysfunction"},{"id":"c","text":"It captures subjective satisfaction"},{"id":"d","text":"It evaluates economic resources"}],"answerId":"c","explanation":"The Family APGAR captures a member's subjective satisfaction with family function.","kind":"trap","origin":"ai"},{"id":"ifh-family-assessment-tools~ai-4","moduleId":"ifh-family-assessment-tools","stem":"When is it most appropriate to conduct a family assessment?","options":[{"id":"a","text":"During routine check-ups"},{"id":"b","text":"When a relative is the caregiver"},{"id":"c","text":"In every clinical encounter"},{"id":"d","text":"Only in pediatric cases"}],"answerId":"b","explanation":"Family assessments are crucial when a relative is the caregiver, among other specific situations.","kind":"mechanism","origin":"ai"},{"id":"ifh-family-assessment-tools~ai-5","moduleId":"ifh-family-assessment-tools","stem":"How does the family life-cycle stage assist in family assessment?","options":[{"id":"a","text":"By diagnosing family dysfunction"},{"id":"b","text":"By predicting developmental tasks"},{"id":"c","text":"By measuring economic resources"},{"id":"d","text":"By evaluating medical history"}],"answerId":"b","explanation":"The family life-cycle stage helps anticipate developmental tasks and stressors.","kind":"mechanism","origin":"ai"},{"id":"ifh-family-assessment-tools~ai-6","moduleId":"ifh-family-assessment-tools","stem":"How might a genogram complement a family circle in assessment?","options":[{"id":"a","text":"By providing a subjective map of bonds"},{"id":"b","text":"By cataloging economic resources"},{"id":"c","text":"By offering a detailed family history"},{"id":"d","text":"By measuring satisfaction with family function"}],"answerId":"c","explanation":"A genogram provides a detailed family history, complementing the subjective map of bonds from a family circle.","kind":"integration","linkedModuleIds":["ifh-genogram"],"origin":"ai"},{"id":"ifh-family-assessment-tools~ai-7","moduleId":"ifh-family-assessment-tools","stem":"In what way can understanding the family life-cycle stage be applied to the module 'How Families Shape Health'?","options":[{"id":"a","text":"By diagnosing chronic illnesses"},{"id":"b","text":"By predicting family health impacts"},{"id":"c","text":"By evaluating medical resources"},{"id":"d","text":"By measuring family satisfaction"}],"answerId":"b","explanation":"Understanding the family life-cycle stage helps predict how families might impact health.","kind":"integration","linkedModuleIds":["ifh-family-health-impact"],"origin":"ai"}],"ifh-family-life-cycle":[{"id":"ifh-family-life-cycle~ai-0","moduleId":"ifh-family-life-cycle","stem":"Which stage of Duvall's family life cycle involves the task of renegotiating the adult-child relationship as children leave home?","options":[{"id":"a","text":"Childbearing"},{"id":"b","text":"Launching"},{"id":"c","text":"Middle-age / empty nest"},{"id":"d","text":"Ageing / retirement"}],"answerId":"b","explanation":"The launching stage involves children leaving home, requiring a renegotiation of the adult-child relationship.","kind":"recall","origin":"ai"},{"id":"ifh-family-life-cycle~ai-1","moduleId":"ifh-family-life-cycle","stem":"A family with a preschooler and a teenager is likely experiencing which challenge according to the family life cycle?","options":[{"id":"a","text":"Single developmental task"},{"id":"b","text":"Overlapping stages"},{"id":"c","text":"Empty nest syndrome"},{"id":"d","text":"Retirement planning"}],"answerId":"b","explanation":"Families can occupy overlapping stages, managing tasks for both a preschooler and a teenager simultaneously.","kind":"mechanism","origin":"ai"},{"id":"ifh-family-life-cycle~ai-2","moduleId":"ifh-family-life-cycle","stem":"Which of the following is a common stress point in the family life cycle?","options":[{"id":"a","text":"Middle of a stable stage"},{"id":"b","text":"During a child's school year"},{"id":"c","text":"At transition points between stages"},{"id":"d","text":"When children are adults"}],"answerId":"c","explanation":"Stress and crises cluster at transitions between stages due to role and boundary renegotiation.","kind":"trap","origin":"ai"},{"id":"ifh-family-life-cycle~ai-3","moduleId":"ifh-family-life-cycle","stem":"A couple is experiencing increased tension after the birth of their first child. This is an example of stress at which family life cycle stage?","options":[{"id":"a","text":"Married couple, no children"},{"id":"b","text":"Childbearing"},{"id":"c","text":"Preschool"},{"id":"d","text":"School-age"}],"answerId":"b","explanation":"The childbearing stage involves stress due to the addition of a new family member and role changes.","kind":"clinical","origin":"ai"},{"id":"ifh-family-life-cycle~ai-4","moduleId":"ifh-family-life-cycle","stem":"In the context of family life cycle, what is the primary task for a family in the ageing/retirement stage?","options":[{"id":"a","text":"Forming the marital system"},{"id":"b","text":"Launching children"},{"id":"c","text":"Coping with loss and dependency"},{"id":"d","text":"Managing preschool education"}],"answerId":"c","explanation":"The ageing/retirement stage involves coping with loss and dependency as primary tasks.","kind":"recall","origin":"ai"},{"id":"ifh-family-life-cycle~ai-5","moduleId":"ifh-family-life-cycle","stem":"How does the family life cycle concept integrate with family assessment tools?","options":[{"id":"a","text":"Family assessment tools ignore life cycle stages"},{"id":"b","text":"Assessment tools focus only on individual health"},{"id":"c","text":"Assessment tools help identify the family's current life cycle stage"},{"id":"d","text":"Life cycle stages are irrelevant to assessment"}],"answerId":"c","explanation":"Family assessment tools are used to identify the current stage of the family life cycle, aiding in anticipatory guidance.","kind":"integration","linkedModuleIds":["ifh-family-assessment-tools"],"origin":"ai"},{"id":"ifh-family-life-cycle~ai-6","moduleId":"ifh-family-life-cycle","stem":"What is the relationship between stress and life events in the family life cycle?","options":[{"id":"a","text":"Life events are unrelated to family stages"},{"id":"b","text":"Stress is constant across all stages"},{"id":"c","text":"Stress peaks during life cycle transitions"},{"id":"d","text":"Life events only affect individual members"}],"answerId":"c","explanation":"Stress peaks during transitions between family life cycle stages due to role and boundary changes.","kind":"integration","linkedModuleIds":["ifh-stress-life-events"],"origin":"ai"}],"ifh-social-support-health":[{"id":"ifh-social-support-health~ai-0","moduleId":"ifh-social-support-health","stem":"Which type of social support involves providing practical help such as money or transportation?","options":[{"id":"a","text":"Emotional support"},{"id":"b","text":"Instrumental support"},{"id":"c","text":"Informational support"},{"id":"d","text":"Appraisal support"}],"answerId":"b","explanation":"Instrumental support involves tangible, practical help like money or transportation.","kind":"recall","origin":"ai"},{"id":"ifh-social-support-health~ai-1","moduleId":"ifh-social-support-health","stem":"What is the primary difference between a social network and social support?","options":[{"id":"a","text":"Network is emotional; support is practical"},{"id":"b","text":"Network is structure; support is function"},{"id":"c","text":"Network is small; support is large"},{"id":"d","text":"Network is temporary; support is permanent"}],"answerId":"b","explanation":"A social network is the structure of ties, while social support is the function those ties deliver.","kind":"mechanism","origin":"ai"},{"id":"ifh-social-support-health~ai-2","moduleId":"ifh-social-support-health","stem":"Which hypothesis suggests that social support is especially protective under high stress?","options":[{"id":"a","text":"Direct effect hypothesis"},{"id":"b","text":"Stress-buffering hypothesis"},{"id":"c","text":"Social isolation hypothesis"},{"id":"d","text":"Biopsychosocial hypothesis"}],"answerId":"b","explanation":"The stress-buffering hypothesis posits that social support cushions the appraisal of threat and response under high stress.","kind":"recall","origin":"ai"},{"id":"ifh-social-support-health~ai-3","moduleId":"ifh-social-support-health","stem":"A patient reports feeling lonely despite having a large social network. What is the most likely explanation?","options":[{"id":"a","text":"Lack of instrumental support"},{"id":"b","text":"Lack of emotional support"},{"id":"c","text":"Lack of informational support"},{"id":"d","text":"Lack of appraisal support"}],"answerId":"b","explanation":"A large network does not guarantee emotional support, which is crucial for feeling connected.","kind":"clinical","origin":"ai"},{"id":"ifh-social-support-health~ai-4","moduleId":"ifh-social-support-health","stem":"Which type of social support is incorrectly matched with its example: providing feedback and affirmation?","options":[{"id":"a","text":"Emotional support"},{"id":"b","text":"Instrumental support"},{"id":"c","text":"Informational support"},{"id":"d","text":"Appraisal support"}],"answerId":"d","explanation":"Appraisal support involves providing feedback and affirmation for self-evaluation.","kind":"trap","origin":"ai"},{"id":"ifh-social-support-health~ai-5","moduleId":"ifh-social-support-health","stem":"How does social isolation compare to smoking in terms of health impact?","options":[{"id":"a","text":"Less harmful than smoking"},{"id":"b","text":"Equally harmful as smoking"},{"id":"c","text":"More harmful than smoking"},{"id":"d","text":"Not comparable to smoking"}],"answerId":"b","explanation":"Social isolation raises all-cause mortality by a magnitude comparable to smoking.","kind":"recall","origin":"ai"},{"id":"ifh-social-support-health~ai-6","moduleId":"ifh-social-support-health","stem":"In the context of the biopsychosocial model, how does social support influence health outcomes?","options":[{"id":"a","text":"By reducing biological risk factors"},{"id":"b","text":"By altering psychological stress responses"},{"id":"c","text":"By changing socioeconomic status"},{"id":"d","text":"By eliminating environmental hazards"}],"answerId":"b","explanation":"Social support influences health by altering psychological stress responses, fitting into the biopsychosocial model.","kind":"integration","linkedModuleIds":["ifh-biopsychosocial-model"],"origin":"ai"},{"id":"ifh-social-support-health~ai-7","moduleId":"ifh-social-support-health","stem":"Which family assessment tool can be used to screen for social support in a clinical setting?","options":[{"id":"a","text":"APGAR"},{"id":"b","text":"SCREEM"},{"id":"c","text":"FACES"},{"id":"d","text":"FAD"}],"answerId":"b","explanation":"SCREEM is a tool used to assess social support in family medicine.","kind":"integration","linkedModuleIds":["ifh-family-assessment-tools"],"origin":"ai"}],"ifh-family-health-impact":[{"id":"ifh-family-health-impact~ai-0","moduleId":"ifh-family-health-impact","stem":"Which of the following best describes the role of the family in managing chronic illness?","options":[{"id":"a","text":"The family is a unit of care that influences health behavior and adherence."},{"id":"b","text":"Family dynamics are irrelevant to chronic illness management."},{"id":"c","text":"Only the patient needs to be involved in their own care."},{"id":"d","text":"Family support is always detrimental to patient autonomy."}],"answerId":"a","explanation":"The family is the strongest everyday influence on health behavior and adherence.","kind":"recall","origin":"ai"},{"id":"ifh-family-health-impact~ai-1","moduleId":"ifh-family-health-impact","stem":"How does family conflict typically affect chronic disease outcomes?","options":[{"id":"a","text":"Improves adherence and monitoring"},{"id":"b","text":"Has no impact on disease outcomes"},{"id":"c","text":"Worsens adherence and monitoring"},{"id":"d","text":"Enhances patient autonomy"}],"answerId":"c","explanation":"Family conflict undermines adherence and monitoring, worsening disease outcomes.","kind":"mechanism","origin":"ai"},{"id":"ifh-family-health-impact~ai-2","moduleId":"ifh-family-health-impact","stem":"What is a common misconception about the caregiver's role in chronic illness?","options":[{"id":"a","text":"Caregivers are at risk of burnout and need assessment."},{"id":"b","text":"Caregivers do not experience significant stress."},{"id":"c","text":"Caregivers are only responsible for physical tasks."},{"id":"d","text":"Caregivers' health is not affected by their role."}],"answerId":"a","explanation":"Caregivers are 'hidden patients' at risk of burnout and illness, requiring assessment.","kind":"trap","origin":"ai"},{"id":"ifh-family-health-impact~ai-3","moduleId":"ifh-family-health-impact","stem":"Which of the following is an example of how family stress can impact health?","options":[{"id":"a","text":"Family stress has no effect on health."},{"id":"b","text":"Family stress can stabilize a symptom, such as a child's pain flaring with parental conflict."},{"id":"c","text":"Family stress always leads to immediate health improvement."},{"id":"d","text":"Family stress only affects mental health, not physical health."}],"answerId":"b","explanation":"Family stress can precipitate or aggravate illness, stabilizing symptoms like a child's pain.","kind":"clinical","origin":"ai"},{"id":"ifh-family-health-impact~ai-4","moduleId":"ifh-family-health-impact","stem":"In the context of the sick role, what obligation does illness impose on a person?","options":[{"id":"a","text":"To avoid seeking help and remain independent"},{"id":"b","text":"To seek help and try to recover"},{"id":"c","text":"To take on additional responsibilities"},{"id":"d","text":"To isolate from family support"}],"answerId":"b","explanation":"The sick role obliges the person to seek help and try to recover, legitimized by family.","kind":"recall","origin":"ai"},{"id":"ifh-family-health-impact~ai-5","moduleId":"ifh-family-health-impact","stem":"How might family assessment tools be used to improve chronic disease management?","options":[{"id":"a","text":"By identifying family dynamics that support adherence"},{"id":"b","text":"By focusing solely on the patient's medical history"},{"id":"c","text":"By excluding family members from the care plan"},{"id":"d","text":"By assessing only the financial status of the family"}],"answerId":"a","explanation":"Family assessment tools help identify dynamics that support or hinder adherence.","kind":"integration","linkedModuleIds":["ifh-family-assessment-tools"],"origin":"ai"},{"id":"ifh-family-health-impact~ai-6","moduleId":"ifh-family-health-impact","stem":"How does the family life cycle influence health behaviors?","options":[{"id":"a","text":"It has no impact on health behaviors."},{"id":"b","text":"Different stages can alter family roles and stressors, affecting health behaviors."},{"id":"c","text":"It only affects health behaviors in childhood."},{"id":"d","text":"It dictates health behaviors regardless of individual choice."}],"answerId":"b","explanation":"The family life cycle involves transitions that can alter roles and stressors, influencing health behaviors.","kind":"integration","linkedModuleIds":["ifh-family-life-cycle"],"origin":"ai"}],"ifh-biopsychosocial-model":[{"id":"ifh-biopsychosocial-model~ai-0","moduleId":"ifh-biopsychosocial-model","stem":"Which of the following best describes the biopsychosocial model proposed by George Engel?","options":[{"id":"a","text":"A systems model where biological, psychological, and social factors interact dynamically"},{"id":"b","text":"A model that primarily focuses on biological factors with some psychological considerations"},{"id":"c","text":"A model that treats psychological and social factors as separate from biological factors"},{"id":"d","text":"A model that emphasizes the psychological aspects of health over biological ones"}],"answerId":"a","explanation":"The biopsychosocial model integrates biological, psychological, and social factors, emphasizing their dynamic interactions.","kind":"recall","origin":"ai"},{"id":"ifh-biopsychosocial-model~ai-1","moduleId":"ifh-biopsychosocial-model","stem":"In the context of the biopsychosocial model, which of the following is considered a 'social determinant of health'?","options":[{"id":"a","text":"Genetic predisposition"},{"id":"b","text":"Coping mechanisms"},{"id":"c","text":"Socioeconomic status"},{"id":"d","text":"Immune response"}],"answerId":"c","explanation":"Socioeconomic status is a social determinant of health, influencing health outcomes through access to resources and exposure to risks.","kind":"recall","origin":"ai"},{"id":"ifh-biopsychosocial-model~ai-2","moduleId":"ifh-biopsychosocial-model","stem":"How does the biopsychosocial model explain the relationship between socioeconomic status and health outcomes?","options":[{"id":"a","text":"Higher socioeconomic status directly causes better health through genetic factors"},{"id":"b","text":"Socioeconomic status influences health outcomes through access to resources and exposure to risks"},{"id":"c","text":"Socioeconomic status has no significant impact on health outcomes"},{"id":"d","text":"Health outcomes determine socioeconomic status"}],"answerId":"b","explanation":"The model posits that socioeconomic status affects health by shaping access to resources and exposure to health risks.","kind":"mechanism","origin":"ai"},{"id":"ifh-biopsychosocial-model~ai-3","moduleId":"ifh-biopsychosocial-model","stem":"Which of the following scenarios best illustrates the principle of the biopsychosocial model?","options":[{"id":"a","text":"A patient with hypertension is treated solely with medication"},{"id":"b","text":"A patient with depression is assessed for biological, psychological, and social factors"},{"id":"c","text":"A patient with diabetes is managed by focusing only on dietary changes"},{"id":"d","text":"A patient with anxiety is prescribed medication without further assessment"}],"answerId":"b","explanation":"The biopsychosocial model involves assessing and integrating biological, psychological, and social factors in treatment.","kind":"clinical","origin":"ai"},{"id":"ifh-biopsychosocial-model~ai-4","moduleId":"ifh-biopsychosocial-model","stem":"Which of the following is a common misconception about the biopsychosocial model?","options":[{"id":"a","text":"It integrates biological, psychological, and social factors"},{"id":"b","text":"It treats psychological and social factors as add-ons to biological factors"},{"id":"c","text":"It views health as an interaction of multiple domains"},{"id":"d","text":"It considers social determinants as crucial in health outcomes"}],"answerId":"b","explanation":"A misconception is that the model treats psychological and social factors as separate add-ons, rather than integrated components.","kind":"trap","origin":"ai"},{"id":"ifh-biopsychosocial-model~ai-5","moduleId":"ifh-biopsychosocial-model","stem":"How does the biopsychosocial model relate to the principles of family medicine?","options":[{"id":"a","text":"Both focus solely on biological interventions"},{"id":"b","text":"Family medicine emphasizes individual care, while the biopsychosocial model focuses on population health"},{"id":"c","text":"Both consider the family and community as units of care"},{"id":"d","text":"Family medicine disregards social factors, unlike the biopsychosocial model"}],"answerId":"c","explanation":"Both the biopsychosocial model and family medicine principles consider the family and community as integral units of care.","kind":"integration","linkedModuleIds":["ifh-family-medicine-principles"],"origin":"ai"},{"id":"ifh-biopsychosocial-model~ai-6","moduleId":"ifh-biopsychosocial-model","stem":"In what way does the biopsychosocial model underpin the understanding of stress and life events?","options":[{"id":"a","text":"It views stress solely as a psychological phenomenon"},{"id":"b","text":"It considers stress as a result of biological factors only"},{"id":"c","text":"It integrates biological, psychological, and social factors in understanding stress"},{"id":"d","text":"It ignores the role of social factors in stress"}],"answerId":"c","explanation":"The biopsychosocial model integrates biological, psychological, and social factors to provide a comprehensive understanding of stress.","kind":"integration","linkedModuleIds":["ifh-stress-life-events"],"origin":"ai"}],"ifh-stress-life-events":[{"id":"ifh-stress-life-events~ai-0","moduleId":"ifh-stress-life-events","stem":"Which of the following best describes the primary appraisal in the stress response?","options":[{"id":"a","text":"Assessing if an event is a threat"},{"id":"b","text":"Evaluating coping resources"},{"id":"c","text":"Initiating the SAM axis"},{"id":"d","text":"Activating the HPA axis"}],"answerId":"a","explanation":"Primary appraisal involves assessing whether an event poses a threat.","kind":"recall","origin":"ai"},{"id":"ifh-stress-life-events~ai-1","moduleId":"ifh-stress-life-events","stem":"What is the main physiological difference between the SAM and HPA axes?","options":[{"id":"a","text":"SAM is slower and releases cortisol"},{"id":"b","text":"HPA is faster and releases adrenaline"},{"id":"c","text":"SAM is faster and releases adrenaline"},{"id":"d","text":"HPA is faster and releases cortisol"}],"answerId":"c","explanation":"The SAM axis is fast and releases adrenaline, while the HPA axis is slower and releases cortisol.","kind":"mechanism","origin":"ai"},{"id":"ifh-stress-life-events~ai-2","moduleId":"ifh-stress-life-events","stem":"Which of the following life events would add Life Change Units according to the SRRS?","options":[{"id":"a","text":"Divorce"},{"id":"b","text":"Winning a lottery"},{"id":"c","text":"Starting a new job"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"The SRRS includes both positive and negative life events, as all require readjustment.","kind":"trap","origin":"ai"},{"id":"ifh-stress-life-events~ai-3","moduleId":"ifh-stress-life-events","stem":"Chronic activation of which physiological axis is primarily responsible for allostatic load?","options":[{"id":"a","text":"SAM axis"},{"id":"b","text":"HPA axis"},{"id":"c","text":"Parasympathetic nervous system"},{"id":"d","text":"Central nervous system"}],"answerId":"b","explanation":"Chronic activation of the HPA axis leads to allostatic load due to sustained cortisol release.","kind":"mechanism","origin":"ai"},{"id":"ifh-stress-life-events~ai-4","moduleId":"ifh-stress-life-events","stem":"A patient with high allostatic load is at increased risk for which of the following conditions?","options":[{"id":"a","text":"Hypertension"},{"id":"b","text":"Acute inflammation"},{"id":"c","text":"Infectious diseases"},{"id":"d","text":"Hyperthyroidism"}],"answerId":"a","explanation":"High allostatic load is linked to hypertension due to chronic stress.","kind":"clinical","origin":"ai"},{"id":"ifh-stress-life-events~ai-5","moduleId":"ifh-stress-life-events","stem":"How does the concept of allostasis relate to the biopsychosocial model?","options":[{"id":"a","text":"It focuses solely on biological changes"},{"id":"b","text":"It integrates biological, psychological, and social factors"},{"id":"c","text":"It ignores psychological factors"},{"id":"d","text":"It only considers social support"}],"answerId":"b","explanation":"Allostasis involves achieving stability through change and integrates multiple factors, aligning with the biopsychosocial model.","kind":"integration","linkedModuleIds":["ifh-biopsychosocial-model"],"origin":"ai"},{"id":"ifh-stress-life-events~ai-6","moduleId":"ifh-stress-life-events","stem":"In the context of the family life cycle, which of the following is a likely stressor requiring adaptation?","options":[{"id":"a","text":"Marriage"},{"id":"b","text":"Job promotion"},{"id":"c","text":"Winning a lottery"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"All these events require adaptation and are considered stressors in the family life cycle.","kind":"integration","linkedModuleIds":["ifh-family-life-cycle"],"origin":"ai"}],"ifh-prevention-levels":[{"id":"ifh-prevention-levels~ai-0","moduleId":"ifh-prevention-levels","stem":"Which level of prevention involves immunization to prevent the onset of disease?","options":[{"id":"a","text":"Primordial prevention"},{"id":"b","text":"Primary prevention"},{"id":"c","text":"Secondary prevention"},{"id":"d","text":"Tertiary prevention"}],"answerId":"b","explanation":"Immunization is a form of primary prevention as it acts before the disease occurs, reducing its incidence.","kind":"recall","origin":"ai"},{"id":"ifh-prevention-levels~ai-1","moduleId":"ifh-prevention-levels","stem":"A 55-year-old woman undergoes a mammogram as part of a routine health check-up. What level of prevention does this represent?","options":[{"id":"a","text":"Primordial prevention"},{"id":"b","text":"Primary prevention"},{"id":"c","text":"Secondary prevention"},{"id":"d","text":"Tertiary prevention"}],"answerId":"c","explanation":"Screening through mammograms is secondary prevention, as it aims to detect disease in its latent stage.","kind":"clinical","origin":"ai"},{"id":"ifh-prevention-levels~ai-2","moduleId":"ifh-prevention-levels","stem":"Which of the following is an example of quaternary prevention?","options":[{"id":"a","text":"Vaccination programs"},{"id":"b","text":"Cholesterol screening"},{"id":"c","text":"De-prescribing unnecessary medications"},{"id":"d","text":"Smoking cessation programs"}],"answerId":"c","explanation":"Quaternary prevention involves protecting patients from unnecessary medical interventions, such as de-prescribing.","kind":"recall","origin":"ai"},{"id":"ifh-prevention-levels~ai-3","moduleId":"ifh-prevention-levels","stem":"What is the primary goal of primordial prevention?","options":[{"id":"a","text":"To prevent the onset of disease"},{"id":"b","text":"To detect disease early"},{"id":"c","text":"To prevent risk factors from developing"},{"id":"d","text":"To reduce disability from disease"}],"answerId":"c","explanation":"Primordial prevention aims to prevent the development of risk factors themselves.","kind":"mechanism","origin":"ai"},{"id":"ifh-prevention-levels~ai-4","moduleId":"ifh-prevention-levels","stem":"A patient is advised to use seat belts to prevent injury in case of an accident. This advice is an example of which level of prevention?","options":[{"id":"a","text":"Primordial prevention"},{"id":"b","text":"Primary prevention"},{"id":"c","text":"Secondary prevention"},{"id":"d","text":"Tertiary prevention"}],"answerId":"b","explanation":"Using seat belts is a form of primary prevention as it aims to prevent injury before it occurs.","kind":"recall","origin":"ai"},{"id":"ifh-prevention-levels~ai-5","moduleId":"ifh-prevention-levels","stem":"Which level of prevention is most closely associated with the concept of 'first, do no harm'?","options":[{"id":"a","text":"Primordial prevention"},{"id":"b","text":"Primary prevention"},{"id":"c","text":"Secondary prevention"},{"id":"d","text":"Quaternary prevention"}],"answerId":"d","explanation":"Quaternary prevention focuses on protecting patients from the harms of unnecessary medical interventions.","kind":"recall","origin":"ai"},{"id":"ifh-prevention-levels~ai-6","moduleId":"ifh-prevention-levels","stem":"In the context of health promotion, which level of prevention is most relevant to the 'Stages of Change' model?","options":[{"id":"a","text":"Primordial prevention"},{"id":"b","text":"Primary prevention"},{"id":"c","text":"Secondary prevention"},{"id":"d","text":"Tertiary prevention"}],"answerId":"b","explanation":"The 'Stages of Change' model is used in primary prevention to encourage behavior changes before disease onset.","kind":"integration","linkedModuleIds":["ifh-behavior-change-stages"],"origin":"ai"},{"id":"ifh-prevention-levels~ai-7","moduleId":"ifh-prevention-levels","stem":"A community health program focuses on reducing air pollution to prevent respiratory diseases. Which level of prevention does this represent?","options":[{"id":"a","text":"Primordial prevention"},{"id":"b","text":"Primary prevention"},{"id":"c","text":"Secondary prevention"},{"id":"d","text":"Tertiary prevention"}],"answerId":"a","explanation":"Reducing air pollution is primordial prevention as it addresses environmental risk factors before they lead to disease.","kind":"integration","linkedModuleIds":["ifh-brief-counselling-5a"],"origin":"ai"}],"ifh-screening-principles":[{"id":"ifh-screening-principles~ai-0","moduleId":"ifh-screening-principles","stem":"Which of the following is a key requirement for a condition to be suitable for screening?","options":[{"id":"a","text":"It has a detectable latent stage"},{"id":"b","text":"It is highly prevalent"},{"id":"c","text":"It is easily treatable"},{"id":"d","text":"It has a short natural history"}],"answerId":"a","explanation":"A detectable latent stage is essential for screening because it allows for early intervention.","kind":"recall","origin":"ai"},{"id":"ifh-screening-principles~ai-1","moduleId":"ifh-screening-principles","stem":"What is the primary purpose of a screening test?","options":[{"id":"a","text":"To diagnose disease"},{"id":"b","text":"To identify asymptomatic individuals at higher risk"},{"id":"c","text":"To confirm the presence of disease"},{"id":"d","text":"To provide definitive treatment"}],"answerId":"b","explanation":"Screening tests are used to identify individuals at higher risk, not to diagnose disease.","kind":"recall","origin":"ai"},{"id":"ifh-screening-principles~ai-2","moduleId":"ifh-screening-principles","stem":"Why must a positive screening test be followed by a diagnostic test?","options":[{"id":"a","text":"Screening tests are highly specific"},{"id":"b","text":"Screening tests are highly sensitive"},{"id":"c","text":"Screening tests are definitive"},{"id":"d","text":"Screening tests are cost-effective"}],"answerId":"b","explanation":"Screening tests are designed to be highly sensitive, meaning they may produce false positives that need confirmation.","kind":"mechanism","origin":"ai"},{"id":"ifh-screening-principles~ai-3","moduleId":"ifh-screening-principles","stem":"Which of the following best describes the potential harm of overdiagnosis in screening programs?","options":[{"id":"a","text":"Increased healthcare costs"},{"id":"b","text":"Unnecessary anxiety and treatment"},{"id":"c","text":"Delayed diagnosis"},{"id":"d","text":"Increased false negatives"}],"answerId":"b","explanation":"Overdiagnosis can lead to unnecessary anxiety and treatment for conditions that may never cause symptoms.","kind":"trap","origin":"ai"},{"id":"ifh-screening-principles~ai-4","moduleId":"ifh-screening-principles","stem":"In the context of screening, what is the significance of early treatment?","options":[{"id":"a","text":"It ensures a higher cure rate"},{"id":"b","text":"It reduces healthcare costs"},{"id":"c","text":"It must improve outcomes compared to later treatment"},{"id":"d","text":"It eliminates the need for further testing"}],"answerId":"c","explanation":"Early treatment must improve outcomes compared to treatment at usual presentation to justify screening.","kind":"mechanism","origin":"ai"},{"id":"ifh-screening-principles~ai-5","moduleId":"ifh-screening-principles","stem":"How does the concept of quaternary prevention relate to screening?","options":[{"id":"a","text":"It focuses on early detection"},{"id":"b","text":"It aims to prevent overdiagnosis and overtreatment"},{"id":"c","text":"It enhances the sensitivity of screening tests"},{"id":"d","text":"It reduces the cost of screening programs"}],"answerId":"b","explanation":"Quaternary prevention aims to prevent harm from overdiagnosis and overtreatment, which can be a consequence of screening.","kind":"integration","linkedModuleIds":["ifh-prevention-levels"],"origin":"ai"},{"id":"ifh-screening-principles~ai-6","moduleId":"ifh-screening-principles","stem":"Which principle is shared between screening for general health conditions and screening for substance use?","options":[{"id":"a","text":"Both require a diagnostic test to confirm a positive screen"},{"id":"b","text":"Both focus on symptomatic individuals"},{"id":"c","text":"Both prioritize cost over accuracy"},{"id":"d","text":"Both are definitive diagnostic tools"}],"answerId":"a","explanation":"In both general health and substance use screening, a positive screen must be confirmed by a diagnostic test.","kind":"integration","linkedModuleIds":["ifh-addiction-screening"],"origin":"ai"}],"ifh-screening-test-metrics":[{"id":"ifh-screening-test-metrics~ai-0","moduleId":"ifh-screening-test-metrics","stem":"Which of the following is true regarding the sensitivity of a screening test?","options":[{"id":"a","text":"It is the proportion of true positives correctly identified."},{"id":"b","text":"It is the proportion of true negatives correctly identified."},{"id":"c","text":"It changes with the prevalence of the disease."},{"id":"d","text":"It is the probability that a positive test result is a true positive."}],"answerId":"a","explanation":"Sensitivity is the proportion of true positives correctly identified by the test.","kind":"recall","origin":"ai"},{"id":"ifh-screening-test-metrics~ai-1","moduleId":"ifh-screening-test-metrics","stem":"A screening test for a rare disease has a specificity of 95%. What is a likely consequence when used in a low-prevalence population?","options":[{"id":"a","text":"High positive predictive value"},{"id":"b","text":"High negative predictive value"},{"id":"c","text":"Low positive predictive value"},{"id":"d","text":"Low negative predictive value"}],"answerId":"c","explanation":"In a low-prevalence population, even a highly specific test will have a low positive predictive value due to many false positives.","kind":"mechanism","origin":"ai"},{"id":"ifh-screening-test-metrics~ai-2","moduleId":"ifh-screening-test-metrics","stem":"Which bias is characterized by the detection of indolent disease that would not affect patient outcomes?","options":[{"id":"a","text":"Lead-time bias"},{"id":"b","text":"Length-time bias"},{"id":"c","text":"Overdiagnosis bias"},{"id":"d","text":"Selection bias"}],"answerId":"c","explanation":"Overdiagnosis bias occurs when screening detects disease that would not have impacted the patient's health, leading to unnecessary treatment.","kind":"recall","origin":"ai"},{"id":"ifh-screening-test-metrics~ai-3","moduleId":"ifh-screening-test-metrics","stem":"In a population with a high prevalence of a disease, how are the predictive values of a screening test affected?","options":[{"id":"a","text":"PPV increases, NPV decreases"},{"id":"b","text":"PPV decreases, NPV increases"},{"id":"c","text":"Both PPV and NPV increase"},{"id":"d","text":"Both PPV and NPV decrease"}],"answerId":"a","explanation":"In a high-prevalence population, the positive predictive value increases because there are more true positives relative to false positives.","kind":"mechanism","origin":"ai"},{"id":"ifh-screening-test-metrics~ai-4","moduleId":"ifh-screening-test-metrics","stem":"A patient tests positive in a highly sensitive screening test. What is the next best step?","options":[{"id":"a","text":"Start treatment immediately"},{"id":"b","text":"Perform a confirmatory test"},{"id":"c","text":"Repeat the screening test"},{"id":"d","text":"Ignore the result due to low specificity"}],"answerId":"b","explanation":"A confirmatory test is needed to rule out false positives, as highly sensitive tests can have low specificity.","kind":"clinical","origin":"ai"},{"id":"ifh-screening-test-metrics~ai-5","moduleId":"ifh-screening-test-metrics","stem":"How does lead-time bias affect the perceived effectiveness of a screening program?","options":[{"id":"a","text":"It shortens the apparent survival time"},{"id":"b","text":"It lengthens the apparent survival time without affecting actual survival"},{"id":"c","text":"It increases the actual survival time"},{"id":"d","text":"It decreases the incidence of the disease"}],"answerId":"b","explanation":"Lead-time bias makes survival appear longer by diagnosing the disease earlier without changing the actual time of death.","kind":"trap","origin":"ai"},{"id":"ifh-screening-test-metrics~ai-6","moduleId":"ifh-screening-test-metrics","stem":"Which level of prevention is primarily concerned with the implementation of screening tests?","options":[{"id":"a","text":"Primary prevention"},{"id":"b","text":"Secondary prevention"},{"id":"c","text":"Tertiary prevention"},{"id":"d","text":"Quaternary prevention"}],"answerId":"b","explanation":"Screening tests are a form of secondary prevention, aiming to detect disease early in asymptomatic individuals.","kind":"integration","linkedModuleIds":["ifh-prevention-levels"],"origin":"ai"},{"id":"ifh-screening-test-metrics~ai-7","moduleId":"ifh-screening-test-metrics","stem":"A new screening test for celiac disease has a sensitivity of 90% and a specificity of 85%. In a population with a prevalence of 1%, what is a likely outcome?","options":[{"id":"a","text":"High PPV"},{"id":"b","text":"Low PPV"},{"id":"c","text":"High NPV"},{"id":"d","text":"Low NPV"}],"answerId":"b","explanation":"With low prevalence, even a test with high sensitivity and specificity will have a low PPV due to the high number of false positives.","kind":"integration","linkedModuleIds":["add-celiac-disease-and-gluten-sensitivity"],"origin":"ai"}],"ifh-special-populations-approach":[{"id":"ifh-special-populations-approach~ai-0","moduleId":"ifh-special-populations-approach","stem":"Which of the following is NOT one of the 5 A's of access to healthcare?","options":[{"id":"a","text":"Availability"},{"id":"b","text":"Accessibility"},{"id":"c","text":"Adaptability"},{"id":"d","text":"Affordability"}],"answerId":"c","explanation":"The 5 A's are Availability, Accessibility, Accommodation, Affordability, and Acceptability.","kind":"recall","origin":"ai"},{"id":"ifh-special-populations-approach~ai-1","moduleId":"ifh-special-populations-approach","stem":"A 75-year-old housebound patient is having difficulty managing medications. What is the most appropriate next step?","options":[{"id":"a","text":"Increase clinic visits"},{"id":"b","text":"Conduct a home visit"},{"id":"c","text":"Refer to a specialist"},{"id":"d","text":"Prescribe new medications"}],"answerId":"b","explanation":"A home visit can reveal hidden barriers to medication adherence and management.","kind":"clinical","origin":"ai"},{"id":"ifh-special-populations-approach~ai-2","moduleId":"ifh-special-populations-approach","stem":"A patient from a marginalized community is struggling to access healthcare services. What is the first step a family doctor should take?","options":[{"id":"a","text":"Prescribe medication"},{"id":"b","text":"Refer to a specialist"},{"id":"c","text":"Identify barriers to access"},{"id":"d","text":"Schedule more frequent visits"}],"answerId":"c","explanation":"Identifying barriers is the first step in addressing access issues and advocating for the patient.","kind":"mechanism","origin":"ai"},{"id":"ifh-special-populations-approach~ai-3","moduleId":"ifh-special-populations-approach","stem":"In a multicultural clinic setting, why is it important to use a professional interpreter rather than a family member?","options":[{"id":"a","text":"Family members are less accurate"},{"id":"b","text":"Professional interpreters are faster"},{"id":"c","text":"Family members may breach confidentiality"},{"id":"d","text":"Professional interpreters are more empathetic"}],"answerId":"c","explanation":"Family members may filter information and breach confidentiality; professional interpreters ensure accuracy and privacy.","kind":"trap","origin":"ai"},{"id":"ifh-special-populations-approach~ai-4","moduleId":"ifh-special-populations-approach","stem":"How does continuity of care benefit marginalized patients?","options":[{"id":"a","text":"Increases medication adherence"},{"id":"b","text":"Reduces healthcare costs"},{"id":"c","text":"Lowers threshold to seek care"},{"id":"d","text":"Improves diagnostic accuracy"}],"answerId":"c","explanation":"Continuity of care with a trusted doctor lowers the threshold for marginalized patients to seek care.","kind":"mechanism","origin":"ai"},{"id":"ifh-special-populations-approach~ai-5","moduleId":"ifh-special-populations-approach","stem":"Which family assessment tool can help map a patient's available resources?","options":[{"id":"a","text":"SCREEM"},{"id":"b","text":"MMSE"},{"id":"c","text":"APGAR"},{"id":"d","text":"GAD-7"}],"answerId":"a","explanation":"SCREEM assesses Social, Cultural, Religious, Economic, Educational, and Medical resources.","kind":"recall","linkedModuleIds":["ifh-family-assessment-tools"],"origin":"ai"},{"id":"ifh-special-populations-approach~ai-6","moduleId":"ifh-special-populations-approach","stem":"A diabetic patient from a vulnerable population is struggling with insulin management. How can principles of family medicine assist?","options":[{"id":"a","text":"Prescribe a different insulin"},{"id":"b","text":"Increase clinic visits"},{"id":"c","text":"Coordinate care through a single trusted doctor"},{"id":"d","text":"Refer to an endocrinologist"}],"answerId":"c","explanation":"Coordinating care through a single trusted doctor aligns with family medicine principles, providing continuity and personalized care.","kind":"integration","linkedModuleIds":["ifh-family-medicine-principles"],"origin":"ai"}],"ifh-behavior-change-stages":[{"id":"ifh-behavior-change-stages~ai-0","moduleId":"ifh-behavior-change-stages","stem":"A patient states they are aware of the health risks of smoking but are not ready to quit. Which stage of the Transtheoretical Model does this represent?","options":[{"id":"a","text":"Precontemplation"},{"id":"b","text":"Contemplation"},{"id":"c","text":"Preparation"},{"id":"d","text":"Action"}],"answerId":"b","explanation":"The patient is in the contemplation stage, where they are aware of the problem but not yet ready to take action.","kind":"recall","origin":"ai"},{"id":"ifh-behavior-change-stages~ai-1","moduleId":"ifh-behavior-change-stages","stem":"What is the most appropriate intervention for a patient in the preparation stage of change?","options":[{"id":"a","text":"Raise awareness about health risks"},{"id":"b","text":"Explore ambivalence"},{"id":"c","text":"Set a quit date and develop a plan"},{"id":"d","text":"Reinforce behavior change"}],"answerId":"c","explanation":"In the preparation stage, the patient is ready to change and should set a specific plan and date for action.","kind":"mechanism","origin":"ai"},{"id":"ifh-behavior-change-stages~ai-2","moduleId":"ifh-behavior-change-stages","stem":"A patient who has stopped smoking for 6 months is experiencing cravings. What should be emphasized to them?","options":[{"id":"a","text":"Relapse is a failure"},{"id":"b","text":"Cravings mean they should quit trying"},{"id":"c","text":"Relapse is part of the cycle"},{"id":"d","text":"They should have never tried to quit"}],"answerId":"c","explanation":"Relapse is a normal part of the change cycle and should be used as a learning opportunity.","kind":"trap","origin":"ai"},{"id":"ifh-behavior-change-stages~ai-3","moduleId":"ifh-behavior-change-stages","stem":"Which factor is NOT part of the Health Belief Model influencing behavior change?","options":[{"id":"a","text":"Perceived susceptibility"},{"id":"b","text":"Perceived severity"},{"id":"c","text":"Perceived benefits"},{"id":"d","text":"Perceived enjoyment"}],"answerId":"d","explanation":"Perceived enjoyment is not a factor in the Health Belief Model; it focuses on susceptibility, severity, benefits, and barriers.","kind":"recall","origin":"ai"},{"id":"ifh-behavior-change-stages~ai-4","moduleId":"ifh-behavior-change-stages","stem":"A patient in the precontemplation stage is advised to quit smoking immediately. What is the likely outcome?","options":[{"id":"a","text":"Increased motivation to quit"},{"id":"b","text":"Resistance and disengagement"},{"id":"c","text":"Immediate cessation"},{"id":"d","text":"Successful long-term change"}],"answerId":"b","explanation":"Pushing a precontemplator to quit can provoke resistance and disengagement.","kind":"trap","origin":"ai"},{"id":"ifh-behavior-change-stages~ai-5","moduleId":"ifh-behavior-change-stages","stem":"How does social support influence the stages of change in smoking cessation?","options":[{"id":"a","text":"It has no effect"},{"id":"b","text":"It only helps in the action stage"},{"id":"c","text":"It enhances self-efficacy across all stages"},{"id":"d","text":"It is only crucial in the maintenance stage"}],"answerId":"c","explanation":"Social support enhances self-efficacy, which is important across all stages of change.","kind":"integration","linkedModuleIds":["ifh-social-support-health"],"origin":"ai"},{"id":"ifh-behavior-change-stages~ai-6","moduleId":"ifh-behavior-change-stages","stem":"In motivational interviewing, what is the primary goal when working with a patient in the contemplation stage?","options":[{"id":"a","text":"To set a quit date"},{"id":"b","text":"To explore ambivalence and build motivation"},{"id":"c","text":"To provide a nicotine patch"},{"id":"d","text":"To reinforce abstinence"}],"answerId":"b","explanation":"In the contemplation stage, motivational interviewing focuses on exploring ambivalence and building motivation.","kind":"integration","linkedModuleIds":["ifh-motivational-interviewing"],"origin":"ai"}],"ifh-motivational-interviewing":[{"id":"ifh-motivational-interviewing~ai-0","moduleId":"ifh-motivational-interviewing","stem":"What is the primary purpose of using reflective listening in motivational interviewing?","options":[{"id":"a","text":"To show empathy and keep the patient exploring"},{"id":"b","text":"To persuade the patient to change"},{"id":"c","text":"To provide solutions to the patient's problems"},{"id":"d","text":"To summarize the patient's statements"}],"answerId":"a","explanation":"Reflective listening shows empathy and encourages the patient to explore their thoughts and feelings further.","kind":"recall","origin":"ai"},{"id":"ifh-motivational-interviewing~ai-1","moduleId":"ifh-motivational-interviewing","stem":"Which of the following best describes the 'righting reflex' in motivational interviewing?","options":[{"id":"a","text":"The urge to fix the patient by listing reasons for change"},{"id":"b","text":"The ability to reflect the patient's feelings accurately"},{"id":"c","text":"The skill of summarizing the patient's goals"},{"id":"d","text":"The process of planning for change"}],"answerId":"a","explanation":"The righting reflex is the urge to fix the patient by listing reasons they should change, which can provoke sustain talk.","kind":"mechanism","origin":"ai"},{"id":"ifh-motivational-interviewing~ai-2","moduleId":"ifh-motivational-interviewing","stem":"In motivational interviewing, what is the clinician's role in developing discrepancy?","options":[{"id":"a","text":"To highlight the gap between the patient's behavior and their goals"},{"id":"b","text":"To provide a detailed plan for change"},{"id":"c","text":"To persuade the patient to adopt new behaviors"},{"id":"d","text":"To argue for the benefits of change"}],"answerId":"a","explanation":"Developing discrepancy involves highlighting the gap between the patient's current behavior and their personal goals or values.","kind":"mechanism","origin":"ai"},{"id":"ifh-motivational-interviewing~ai-3","moduleId":"ifh-motivational-interviewing","stem":"Which of the following is NOT a core skill in motivational interviewing?","options":[{"id":"a","text":"Open questions"},{"id":"b","text":"Affirmations"},{"id":"c","text":"Reflective listening"},{"id":"d","text":"Persuasion"}],"answerId":"d","explanation":"Persuasion is not a core skill in motivational interviewing; the core skills are OARS: Open questions, Affirmations, Reflective listening, and Summaries.","kind":"trap","origin":"ai"},{"id":"ifh-motivational-interviewing~ai-4","moduleId":"ifh-motivational-interviewing","stem":"During a motivational interviewing session, a patient expresses doubt about their ability to quit smoking. Which strategy should the clinician use to support self-efficacy?","options":[{"id":"a","text":"Affirm the patient's past successes"},{"id":"b","text":"List the health risks of smoking"},{"id":"c","text":"Provide a strict quit plan"},{"id":"d","text":"Argue against the patient's doubts"}],"answerId":"a","explanation":"Affirming the patient's past successes helps build their confidence and supports self-efficacy.","kind":"clinical","origin":"ai"},{"id":"ifh-motivational-interviewing~ai-5","moduleId":"ifh-motivational-interviewing","stem":"How does motivational interviewing integrate with the stages of change model?","options":[{"id":"a","text":"By aligning the conversation with the patient's readiness to change"},{"id":"b","text":"By providing a structured plan for each stage"},{"id":"c","text":"By focusing on the clinician's agenda"},{"id":"d","text":"By using the same techniques regardless of stage"}],"answerId":"a","explanation":"Motivational interviewing aligns with the patient's readiness to change, guiding them through the stages of change.","kind":"integration","linkedModuleIds":["ifh-behavior-change-stages"],"origin":"ai"},{"id":"ifh-motivational-interviewing~ai-6","moduleId":"ifh-motivational-interviewing","stem":"Which motivational interviewing skill is most directly related to effective clinical communication?","options":[{"id":"a","text":"Reflective listening"},{"id":"b","text":"Providing advice"},{"id":"c","text":"Offering solutions"},{"id":"d","text":"Directing the conversation"}],"answerId":"a","explanation":"Reflective listening is a key skill in both motivational interviewing and effective clinical communication.","kind":"integration","linkedModuleIds":["ifh-clinical-communication-skills"],"origin":"ai"}],"ifh-brief-counselling-5a":[{"id":"ifh-brief-counselling-5a~ai-0","moduleId":"ifh-brief-counselling-5a","stem":"Which of the following is the first step in the 5A’s model for brief counselling?","options":[{"id":"a","text":"Ask"},{"id":"b","text":"Advise"},{"id":"c","text":"Assess"},{"id":"d","text":"Arrange"}],"answerId":"a","explanation":"The first step in the 5A’s model is to 'Ask' to identify and record the behavior.","kind":"recall","origin":"ai"},{"id":"ifh-brief-counselling-5a~ai-1","moduleId":"ifh-brief-counselling-5a","stem":"In the FRAMES model of brief intervention, what does the 'R' stand for?","options":[{"id":"a","text":"Responsibility"},{"id":"b","text":"Referral"},{"id":"c","text":"Reassurance"},{"id":"d","text":"Reevaluation"}],"answerId":"a","explanation":"'R' in FRAMES stands for Responsibility, emphasizing that the patient is responsible for change.","kind":"recall","origin":"ai"},{"id":"ifh-brief-counselling-5a~ai-2","moduleId":"ifh-brief-counselling-5a","stem":"During a routine visit, a physician uses the 5A’s model to counsel a patient about smoking cessation. Which step involves evaluating the patient's readiness to quit?","options":[{"id":"a","text":"Ask"},{"id":"b","text":"Advise"},{"id":"c","text":"Assess"},{"id":"d","text":"Assist"}],"answerId":"c","explanation":"The 'Assess' step evaluates the patient's readiness to change behavior.","kind":"clinical","origin":"ai"},{"id":"ifh-brief-counselling-5a~ai-3","moduleId":"ifh-brief-counselling-5a","stem":"Which of the following best describes the difference between health education and health promotion?","options":[{"id":"a","text":"They are the same"},{"id":"b","text":"Health education is broader"},{"id":"c","text":"Health promotion includes policy change"},{"id":"d","text":"Health education includes policy change"}],"answerId":"c","explanation":"Health promotion includes policy and environmental changes, whereas health education focuses on individual knowledge and skills.","kind":"trap","origin":"ai"},{"id":"ifh-brief-counselling-5a~ai-4","moduleId":"ifh-brief-counselling-5a","stem":"A patient is in the 'contemplation' stage of change regarding alcohol use. Which step of the 5A’s model is most appropriate?","options":[{"id":"a","text":"Ask"},{"id":"b","text":"Advise"},{"id":"c","text":"Assess"},{"id":"d","text":"Assist"}],"answerId":"c","explanation":"In the 'contemplation' stage, 'Assess' is used to evaluate readiness and plan the next steps.","kind":"integration","linkedModuleIds":["ifh-behavior-change-stages"],"origin":"ai"},{"id":"ifh-brief-counselling-5a~ai-5","moduleId":"ifh-brief-counselling-5a","stem":"Which action area of the Ottawa Charter does brief counselling primarily address?","options":[{"id":"a","text":"Build healthy public policy"},{"id":"b","text":"Create supportive environments"},{"id":"c","text":"Develop personal skills"},{"id":"d","text":"Reorient health services"}],"answerId":"c","explanation":"Brief counselling primarily focuses on developing personal skills.","kind":"recall","origin":"ai"},{"id":"ifh-brief-counselling-5a~ai-6","moduleId":"ifh-brief-counselling-5a","stem":"A healthcare provider uses SBIRT during a routine check-up. What does SBIRT stand for?","options":[{"id":"a","text":"Screening, Brief Intervention, and Referral to Treatment"},{"id":"b","text":"Screening, Brief Interview, and Referral to Therapy"},{"id":"c","text":"Screening, Basic Intervention, and Referral to Treatment"},{"id":"d","text":"Screening, Brief Intervention, and Referral to Therapy"}],"answerId":"a","explanation":"SBIRT stands for Screening, Brief Intervention, and Referral to Treatment.","kind":"recall","origin":"ai"},{"id":"ifh-brief-counselling-5a~ai-7","moduleId":"ifh-brief-counselling-5a","stem":"How does the FRAMES model ensure the effectiveness of brief interventions in addiction management?","options":[{"id":"a","text":"By providing strict guidelines"},{"id":"b","text":"By emphasizing patient autonomy"},{"id":"c","text":"By focusing solely on medication"},{"id":"d","text":"By ignoring patient input"}],"answerId":"b","explanation":"FRAMES emphasizes patient autonomy and self-efficacy, making the advice more likely to stick.","kind":"integration","linkedModuleIds":["ifh-addiction-management"],"origin":"ai"}],"ifh-addiction-screening":[{"id":"ifh-addiction-screening~ai-0","moduleId":"ifh-addiction-screening","stem":"Which of the following is a key feature of the CAGE questionnaire?","options":[{"id":"a","text":"It diagnoses alcohol dependence"},{"id":"b","text":"It screens for problem drinking"},{"id":"c","text":"It assesses readiness to change"},{"id":"d","text":"It measures the severity of alcohol use"}],"answerId":"b","explanation":"The CAGE questionnaire is a screening tool for identifying potential problem drinking, not for diagnosing alcohol dependence.","kind":"recall","origin":"ai"},{"id":"ifh-addiction-screening~ai-1","moduleId":"ifh-addiction-screening","stem":"A 35-year-old man scores 9 on the AUDIT. What does this indicate?","options":[{"id":"a","text":"Low risk alcohol use"},{"id":"b","text":"Hazardous alcohol use"},{"id":"c","text":"Alcohol dependence"},{"id":"d","text":"No alcohol-related issues"}],"answerId":"b","explanation":"An AUDIT score of 8 or more indicates hazardous alcohol use, suggesting the need for further assessment.","kind":"recall","origin":"ai"},{"id":"ifh-addiction-screening~ai-2","moduleId":"ifh-addiction-screening","stem":"Which of the following is NOT true about the ASSIST tool?","options":[{"id":"a","text":"It screens for multiple substances"},{"id":"b","text":"It provides a risk score"},{"id":"c","text":"It diagnoses substance use disorders"},{"id":"d","text":"It includes tobacco in its assessment"}],"answerId":"c","explanation":"The ASSIST tool screens for substance use and provides a risk score but does not diagnose substance use disorders.","kind":"trap","origin":"ai"},{"id":"ifh-addiction-screening~ai-3","moduleId":"ifh-addiction-screening","stem":"What is the primary goal of using a non-judgmental approach in substance use screening?","options":[{"id":"a","text":"To expedite the screening process"},{"id":"b","text":"To reduce defensiveness and under-reporting"},{"id":"c","text":"To ensure compliance with legal requirements"},{"id":"d","text":"To diagnose substance use disorders"}],"answerId":"b","explanation":"A non-judgmental approach reduces defensiveness and under-reporting, leading to more honest responses from patients.","kind":"mechanism","origin":"ai"},{"id":"ifh-addiction-screening~ai-4","moduleId":"ifh-addiction-screening","stem":"How does the integration of motivational interviewing enhance substance use screening?","options":[{"id":"a","text":"It provides a definitive diagnosis"},{"id":"b","text":"It ensures immediate behavior change"},{"id":"c","text":"It helps assess readiness to change"},{"id":"d","text":"It replaces the need for screening tools"}],"answerId":"c","explanation":"Motivational interviewing helps assess a patient's readiness to change, complementing the screening process.","kind":"integration","linkedModuleIds":["ifh-motivational-interviewing"],"origin":"ai"},{"id":"ifh-addiction-screening~ai-5","moduleId":"ifh-addiction-screening","stem":"In the context of screening for substance use, why is it important to understand addiction neurobiology?","options":[{"id":"a","text":"To diagnose addiction based on brain imaging"},{"id":"b","text":"To tailor screening tools to specific neurobiological profiles"},{"id":"c","text":"To inform a compassionate and informed approach to screening"},{"id":"d","text":"To predict the outcome of addiction treatment"}],"answerId":"c","explanation":"Understanding addiction neurobiology informs a compassionate approach, reducing stigma and improving patient engagement during screening.","kind":"integration","linkedModuleIds":["ifh-addiction-neurobiology"],"origin":"ai"}],"ifh-addiction-management":[{"id":"ifh-addiction-management~ai-0","moduleId":"ifh-addiction-management","stem":"What is the primary goal of harm reduction strategies in addiction management?","options":[{"id":"a","text":"To reduce harm without requiring abstinence"},{"id":"b","text":"To enforce complete abstinence"},{"id":"c","text":"To replace one addiction with another"},{"id":"d","text":"To provide immediate detoxification"}],"answerId":"a","explanation":"Harm reduction aims to reduce the negative consequences of substance use without necessarily requiring abstinence.","kind":"recall","origin":"ai"},{"id":"ifh-addiction-management~ai-1","moduleId":"ifh-addiction-management","stem":"Which medication is commonly used for opioid agonist therapy in addiction management?","options":[{"id":"a","text":"Naltrexone"},{"id":"b","text":"Disulfiram"},{"id":"c","text":"Methadone"},{"id":"d","text":"Varenicline"}],"answerId":"c","explanation":"Methadone is an opioid agonist used to stabilize patients in opioid addiction treatment.","kind":"recall","origin":"ai"},{"id":"ifh-addiction-management~ai-2","moduleId":"ifh-addiction-management","stem":"In the SBIRT framework, what is the purpose of the 'Brief Intervention' step?","options":[{"id":"a","text":"To conduct a full detoxification"},{"id":"b","text":"To provide a structured conversation following a positive screen"},{"id":"c","text":"To immediately refer to specialist care"},{"id":"d","text":"To initiate pharmacotherapy"}],"answerId":"b","explanation":"The brief intervention is a short, structured conversation that follows a positive screen in the SBIRT framework.","kind":"mechanism","origin":"ai"},{"id":"ifh-addiction-management~ai-3","moduleId":"ifh-addiction-management","stem":"A patient relapses after a period of abstinence. What is the appropriate response according to addiction management principles?","options":[{"id":"a","text":"Discharge the patient from care"},{"id":"b","text":"Re-engage the patient and adjust the treatment plan"},{"id":"c","text":"Ignore the relapse and continue the current plan"},{"id":"d","text":"Refer the patient to a different facility"}],"answerId":"b","explanation":"Relapse is expected in addiction management, and the appropriate response is to re-engage and adjust the treatment plan.","kind":"trap","origin":"ai"},{"id":"ifh-addiction-management~ai-4","moduleId":"ifh-addiction-management","stem":"Which of the following is a key component of the FRAMES model used in brief interventions?","options":[{"id":"a","text":"Feedback"},{"id":"b","text":"Flexibility"},{"id":"c","text":"Forcefulness"},{"id":"d","text":"Finality"}],"answerId":"a","explanation":"Feedback is a key component of the FRAMES model used in brief interventions.","kind":"recall","origin":"ai"},{"id":"ifh-addiction-management~ai-5","moduleId":"ifh-addiction-management","stem":"How does motivational interviewing support addiction management?","options":[{"id":"a","text":"By enforcing strict abstinence"},{"id":"b","text":"By supporting patient autonomy and readiness for change"},{"id":"c","text":"By providing immediate pharmacotherapy"},{"id":"d","text":"By focusing solely on harm reduction"}],"answerId":"b","explanation":"Motivational interviewing supports addiction management by enhancing patient autonomy and readiness for change.","kind":"integration","linkedModuleIds":["ifh-motivational-interviewing"],"origin":"ai"},{"id":"ifh-addiction-management~ai-6","moduleId":"ifh-addiction-management","stem":"A patient with chronic kidney disease (CKD) is being considered for naltrexone therapy for alcohol dependence. What should be considered regarding drug dosing?","options":[{"id":"a","text":"Naltrexone is contraindicated in CKD"},{"id":"b","text":"Dose adjustment is required in CKD"},{"id":"c","text":"Naltrexone has no renal considerations"},{"id":"d","text":"Naltrexone should be replaced with methadone"}],"answerId":"b","explanation":"Dose adjustment of naltrexone may be required in patients with CKD due to altered drug clearance.","kind":"integration","linkedModuleIds":["drug-dosing-ckd"],"origin":"ai"}],"ifh-addiction-neurobiology":[{"id":"ifh-addiction-neurobiology~ai-0","moduleId":"ifh-addiction-neurobiology","stem":"Which of the following best describes the transition from substance use to substance use disorder (SUD) according to DSM-5?","options":[{"id":"a","text":"A graded spectrum based on criteria count"},{"id":"b","text":"A binary diagnosis of abuse or dependence"},{"id":"c","text":"A moral failing requiring intervention"},{"id":"d","text":"A condition defined solely by withdrawal symptoms"}],"answerId":"a","explanation":"DSM-5 defines SUD as a graded spectrum based on the number of criteria met over 12 months.","kind":"recall","origin":"ai"},{"id":"ifh-addiction-neurobiology~ai-1","moduleId":"ifh-addiction-neurobiology","stem":"Which brain pathway is primarily involved in the reinforcement of addictive behaviors?","options":[{"id":"a","text":"Mesolimbic dopamine pathway"},{"id":"b","text":"Corticospinal tract"},{"id":"c","text":"Nigrostriatal pathway"},{"id":"d","text":"Dorsal column-medial lemniscus pathway"}],"answerId":"a","explanation":"The mesolimbic dopamine pathway is crucial in reinforcing addictive behaviors through dopamine surges.","kind":"mechanism","origin":"ai"},{"id":"ifh-addiction-neurobiology~ai-2","moduleId":"ifh-addiction-neurobiology","stem":"A patient on long-term opioids for cancer pain exhibits tolerance and withdrawal symptoms. Which statement is correct?","options":[{"id":"a","text":"The patient is addicted to opioids"},{"id":"b","text":"The patient has physical dependence but not addiction"},{"id":"c","text":"The patient is misusing opioids"},{"id":"d","text":"The patient should be immediately weaned off opioids"}],"answerId":"b","explanation":"Physical dependence involves tolerance and withdrawal but does not imply addiction, which requires compulsive use despite harm.","kind":"trap","origin":"ai"},{"id":"ifh-addiction-neurobiology~ai-3","moduleId":"ifh-addiction-neurobiology","stem":"Which of the following withdrawal syndromes can be life-threatening?","options":[{"id":"a","text":"Cannabis withdrawal"},{"id":"b","text":"Alcohol withdrawal"},{"id":"c","text":"Nicotine withdrawal"},{"id":"d","text":"Caffeine withdrawal"}],"answerId":"b","explanation":"Alcohol withdrawal can lead to seizures and delirium tremens, which are life-threatening.","kind":"clinical","origin":"ai"},{"id":"ifh-addiction-neurobiology~ai-4","moduleId":"ifh-addiction-neurobiology","stem":"In the context of addiction, what role does the prefrontal cortex play?","options":[{"id":"a","text":"Reinforcement of addictive behaviors"},{"id":"b","text":"Regulation of judgment and control"},{"id":"c","text":"Initiation of withdrawal symptoms"},{"id":"d","text":"Production of dopamine"}],"answerId":"b","explanation":"The prefrontal cortex is involved in judgment and control, which are weakened in addiction.","kind":"mechanism","origin":"ai"},{"id":"ifh-addiction-neurobiology~ai-5","moduleId":"ifh-addiction-neurobiology","stem":"How does the understanding of addiction as a chronic brain condition align with the biopsychosocial model?","options":[{"id":"a","text":"It emphasizes the moral failing aspect of addiction"},{"id":"b","text":"It highlights the biological, psychological, and social factors involved"},{"id":"c","text":"It focuses solely on the biological changes in the brain"},{"id":"d","text":"It disregards the social context of substance use"}],"answerId":"b","explanation":"The biopsychosocial model considers the interplay of biological, psychological, and social factors in addiction.","kind":"integration","linkedModuleIds":["ifh-biopsychosocial-model"],"origin":"ai"},{"id":"ifh-addiction-neurobiology~ai-6","moduleId":"ifh-addiction-neurobiology","stem":"How does relapse in addiction relate to the stages of change model?","options":[{"id":"a","text":"Relapse is not considered in the stages of change model"},{"id":"b","text":"Relapse is a failure of the action stage"},{"id":"c","text":"Relapse is a normal part of the cycle and can lead to precontemplation"},{"id":"d","text":"Relapse indicates a permanent return to substance use"}],"answerId":"c","explanation":"Relapse is a normal part of the cycle in the stages of change model and can lead to re-evaluation and change.","kind":"integration","linkedModuleIds":["ifh-behavior-change-stages"],"origin":"ai"}],"ifh-special-populations-vulnerable":[{"id":"ifh-special-populations-vulnerable~ai-0","moduleId":"ifh-special-populations-vulnerable","stem":"Which of the following best describes a health inequity?","options":[{"id":"a","text":"A difference in disease prevalence due to genetic factors"},{"id":"b","text":"A higher mortality rate in a low-income community due to lack of access to healthcare"},{"id":"c","text":"A variation in life expectancy between genders"},{"id":"d","text":"A difference in cancer rates due to environmental exposure"}],"answerId":"b","explanation":"A health inequity is a difference that is unfair, avoidable, and unjust, often rooted in social disadvantage.","kind":"recall","origin":"ai"},{"id":"ifh-special-populations-vulnerable~ai-1","moduleId":"ifh-special-populations-vulnerable","stem":"A healthcare provider is working with a patient who is a migrant, female, and living in poverty. Which concept best explains the compounded risk this patient faces?","options":[{"id":"a","text":"Cultural competence"},{"id":"b","text":"Health inequality"},{"id":"c","text":"Intersectionality"},{"id":"d","text":"Biological determinism"}],"answerId":"c","explanation":"Intersectionality refers to the overlapping and interacting social identities that compound risk rather than simply adding to it.","kind":"mechanism","origin":"ai"},{"id":"ifh-special-populations-vulnerable~ai-2","moduleId":"ifh-special-populations-vulnerable","stem":"A physician notes that a patient from a minority ethnic group has poor health outcomes compared to the general population. What should the physician prioritize to address this issue?","options":[{"id":"a","text":"Focus on cultural competence training"},{"id":"b","text":"Implement cultural humility practices"},{"id":"c","text":"Increase genetic testing"},{"id":"d","text":"Promote biological research"}],"answerId":"b","explanation":"Cultural humility involves lifelong self-reflection and recognizing one's own biases, treating the patient as the expert on their context.","kind":"trap","origin":"ai"},{"id":"ifh-special-populations-vulnerable~ai-3","moduleId":"ifh-special-populations-vulnerable","stem":"Which of the following is NOT a characteristic of a vulnerable population?","options":[{"id":"a","text":"Increased risk due to social disadvantage"},{"id":"b","text":"Higher susceptibility due to biological factors"},{"id":"c","text":"Potential for compounded risk through intersectionality"},{"id":"d","text":"Often experiences health inequities"}],"answerId":"b","explanation":"Vulnerability is primarily driven by social determinants of health, not biological factors.","kind":"clinical","origin":"ai"},{"id":"ifh-special-populations-vulnerable~ai-4","moduleId":"ifh-special-populations-vulnerable","stem":"A family doctor is treating a homeless patient with multiple chronic conditions. Which principle of family medicine is most relevant to this scenario?","options":[{"id":"a","text":"Specialist care"},{"id":"b","text":"Whole-person care"},{"id":"c","text":"Acute care focus"},{"id":"d","text":"Biological treatment"}],"answerId":"b","explanation":"Whole-person care is a principle of family medicine that involves addressing all aspects of a patient's life, especially important for vulnerable populations.","kind":"integration","linkedModuleIds":["ifh-family-medicine-principles"],"origin":"ai"},{"id":"ifh-special-populations-vulnerable~ai-5","moduleId":"ifh-special-populations-vulnerable","stem":"How does the biopsychosocial model apply to understanding the health of vulnerable populations?","options":[{"id":"a","text":"It focuses solely on biological factors"},{"id":"b","text":"It emphasizes the role of social and psychological factors in health"},{"id":"c","text":"It disregards social determinants of health"},{"id":"d","text":"It is primarily concerned with genetic predispositions"}],"answerId":"b","explanation":"The biopsychosocial model considers social and psychological factors, which are crucial in understanding the health of vulnerable populations.","kind":"integration","linkedModuleIds":["ifh-biopsychosocial-model"],"origin":"ai"}],"ifh-health-data-governance":[{"id":"ifh-health-data-governance~ai-0","moduleId":"ifh-health-data-governance","stem":"Under Thailand's PDPA, which type of data requires explicit consent due to its classification?","options":[{"id":"a","text":"Health data"},{"id":"b","text":"Financial data"},{"id":"c","text":"Publicly available data"},{"id":"d","text":"Aggregated statistical data"}],"answerId":"a","explanation":"Health data is considered 'sensitive personal data' under the PDPA, requiring explicit consent and stricter protection.","kind":"recall","origin":"ai"},{"id":"ifh-health-data-governance~ai-1","moduleId":"ifh-health-data-governance","stem":"What is a lawful exception to breaching patient confidentiality under health data governance laws?","options":[{"id":"a","text":"Marketing purposes"},{"id":"b","text":"Public-health duties"},{"id":"c","text":"Insurance claims"},{"id":"d","text":"Research without consent"}],"answerId":"b","explanation":"Public-health duties are a lawful exception where patient confidentiality can be breached.","kind":"recall","origin":"ai"},{"id":"ifh-health-data-governance~ai-2","moduleId":"ifh-health-data-governance","stem":"Which of the following best describes the difference between anonymized and pseudonymized data?","options":[{"id":"a","text":"Anonymized data can be re-identified"},{"id":"b","text":"Pseudonymized data is not regulated"},{"id":"c","text":"Anonymized data is irreversible"},{"id":"d","text":"Pseudonymized data is irreversible"}],"answerId":"c","explanation":"Anonymized data is irreversible and falls outside the PDPA, while pseudonymized data can be re-identified and remains regulated.","kind":"trap","origin":"ai"},{"id":"ifh-health-data-governance~ai-3","moduleId":"ifh-health-data-governance","stem":"A hospital plans to use patient data for a quality improvement project. What is the first step under data governance principles?","options":[{"id":"a","text":"De-identify the data"},{"id":"b","text":"Obtain explicit consent"},{"id":"c","text":"Collect maximum data available"},{"id":"d","text":"Share data with third parties"}],"answerId":"b","explanation":"Obtaining explicit consent is the first step to ensure lawful use of sensitive personal data.","kind":"mechanism","origin":"ai"},{"id":"ifh-health-data-governance~ai-4","moduleId":"ifh-health-data-governance","stem":"Which principle is violated if a healthcare provider collects more patient data than necessary for a specific purpose?","options":[{"id":"a","text":"Data minimization"},{"id":"b","text":"Data accuracy"},{"id":"c","text":"Purpose limitation"},{"id":"d","text":"Data security"}],"answerId":"a","explanation":"Data minimization requires collecting only the data necessary for a specific purpose.","kind":"mechanism","origin":"ai"},{"id":"ifh-health-data-governance~ai-5","moduleId":"ifh-health-data-governance","stem":"In the context of health data governance, how does effective clinical communication enhance data protection?","options":[{"id":"a","text":"By reducing the need for data minimization"},{"id":"b","text":"By ensuring patients understand consent forms"},{"id":"c","text":"By allowing data sharing without consent"},{"id":"d","text":"By eliminating the need for data security measures"}],"answerId":"b","explanation":"Effective clinical communication ensures patients understand consent forms, supporting informed consent and data protection.","kind":"integration","linkedModuleIds":["ifh-clinical-communication-skills"],"origin":"ai"},{"id":"ifh-health-data-governance~ai-6","moduleId":"ifh-health-data-governance","stem":"How does the PDPA's requirement for explicit consent impact research ethics in health data?","options":[{"id":"a","text":"It allows data use without consent"},{"id":"b","text":"It simplifies the consent process"},{"id":"c","text":"It ensures ethical data use by requiring informed consent"},{"id":"d","text":"It removes the need for ethical review"}],"answerId":"c","explanation":"The PDPA's requirement for explicit consent ensures that data use in research is ethical by mandating informed consent.","kind":"integration","linkedModuleIds":["ers-research-ethics"],"origin":"ai"}],"ifh-tcm-clinical-approach":[{"id":"ifh-tcm-clinical-approach~ai-0","moduleId":"ifh-tcm-clinical-approach","stem":"What is a significant risk associated with the use of St John's Wort in patients taking warfarin?","options":[{"id":"a","text":"Increased bleeding risk"},{"id":"b","text":"Reduced effectiveness of warfarin"},{"id":"c","text":"Increased risk of hepatotoxicity"},{"id":"d","text":"Increased risk of hypertension"}],"answerId":"b","explanation":"St John's Wort is a potent CYP450 inducer, which can reduce the effectiveness of warfarin by increasing its metabolism.","kind":"mechanism","origin":"ai"},{"id":"ifh-tcm-clinical-approach~ai-1","moduleId":"ifh-tcm-clinical-approach","stem":"A patient using herbal supplements presents with deranged liver function tests. What should be a primary concern?","options":[{"id":"a","text":"Herbal supplements are harmless"},{"id":"b","text":"The supplements may be contaminated"},{"id":"c","text":"The patient is not taking enough supplements"},{"id":"d","text":"Herbal supplements cannot affect liver function"}],"answerId":"b","explanation":"Herbal supplements can be contaminated with substances like heavy metals, which can cause liver injury.","kind":"clinical","origin":"ai"},{"id":"ifh-tcm-clinical-approach~ai-2","moduleId":"ifh-tcm-clinical-approach","stem":"Why is it important to ask patients non-judgmentally about their use of traditional and complementary medicine (T&CM)?","options":[{"id":"a","text":"To discourage their use"},{"id":"b","text":"To ensure patients stop using them"},{"id":"c","text":"To uncover potential interactions"},{"id":"d","text":"To promote T&CM over conventional medicine"}],"answerId":"c","explanation":"Non-judgmental inquiry encourages patients to disclose T&CM use, helping to identify potential interactions with prescribed medications.","kind":"trap","origin":"ai"},{"id":"ifh-tcm-clinical-approach~ai-3","moduleId":"ifh-tcm-clinical-approach","stem":"Which of the following statements about herbal products is true?","options":[{"id":"a","text":"They are always safe because they are natural"},{"id":"b","text":"They can interact with conventional medications"},{"id":"c","text":"They are regulated and free from contaminants"},{"id":"d","text":"They have no pharmacological activity"}],"answerId":"b","explanation":"Herbal products can interact with conventional medications due to their pharmacological activity.","kind":"recall","origin":"ai"},{"id":"ifh-tcm-clinical-approach~ai-4","moduleId":"ifh-tcm-clinical-approach","stem":"A patient taking ginkgo biloba is scheduled for surgery. What is a potential concern?","options":[{"id":"a","text":"Increased risk of infection"},{"id":"b","text":"Increased bleeding risk"},{"id":"c","text":"Decreased anesthetic effect"},{"id":"d","text":"Increased risk of thrombosis"}],"answerId":"b","explanation":"Ginkgo biloba can increase bleeding risk, which is a concern during surgical procedures.","kind":"clinical","origin":"ai"},{"id":"ifh-tcm-clinical-approach~ai-5","moduleId":"ifh-tcm-clinical-approach","stem":"How does the use of motivational interviewing techniques help in managing patients using T&CM?","options":[{"id":"a","text":"It forces patients to stop using T&CM"},{"id":"b","text":"It helps patients understand the risks of T&CM"},{"id":"c","text":"It dismisses the patient's beliefs"},{"id":"d","text":"It integrates T&CM without considering safety"}],"answerId":"b","explanation":"Motivational interviewing helps patients understand the risks and benefits of T&CM, promoting informed decision-making.","kind":"integration","linkedModuleIds":["ifh-motivational-interviewing"],"origin":"ai"},{"id":"ifh-tcm-clinical-approach~ai-6","moduleId":"ifh-tcm-clinical-approach","stem":"In a patient with renovascular disorders, why is it crucial to assess the use of T&CM?","options":[{"id":"a","text":"T&CM always improves renal function"},{"id":"b","text":"Herbal products can worsen hypertension"},{"id":"c","text":"T&CM has no effect on renal function"},{"id":"d","text":"Herbal products are always nephroprotective"}],"answerId":"b","explanation":"Some herbal products can worsen hypertension, which is critical in patients with renovascular disorders.","kind":"integration","linkedModuleIds":["renovascular-disorders"],"origin":"ai"}],"ifh-health-data-quality":[{"id":"ifh-health-data-quality~ai-0","moduleId":"ifh-health-data-quality","stem":"Which type of data is typically structured and coded, making it easier for analysis in quality improvement projects?","options":[{"id":"a","text":"EHR/medical records"},{"id":"b","text":"Surveys"},{"id":"c","text":"Disease registries"},{"id":"d","text":"Vital statistics"}],"answerId":"a","explanation":"EHR/medical records are often structured and coded, facilitating easier analysis compared to unstructured data.","kind":"recall","origin":"ai"},{"id":"ifh-health-data-quality~ai-1","moduleId":"ifh-health-data-quality","stem":"In the Donabedian model, what type of indicator is represented by the percentage of patients screened for a condition?","options":[{"id":"a","text":"Structure"},{"id":"b","text":"Process"},{"id":"c","text":"Outcome"},{"id":"d","text":"Resource"}],"answerId":"b","explanation":"The percentage of patients screened is a process indicator, reflecting what is done in the healthcare setting.","kind":"mechanism","origin":"ai"},{"id":"ifh-health-data-quality~ai-2","moduleId":"ifh-health-data-quality","stem":"What is the primary aim of a PDSA cycle in quality improvement?","options":[{"id":"a","text":"To generate generalizable knowledge"},{"id":"b","text":"To achieve local improvement"},{"id":"c","text":"To validate a hypothesis"},{"id":"d","text":"To conduct a randomized trial"}],"answerId":"b","explanation":"PDSA cycles aim for local improvement through iterative testing and adaptation.","kind":"trap","origin":"ai"},{"id":"ifh-health-data-quality~ai-3","moduleId":"ifh-health-data-quality","stem":"Which of the following best describes the difference between quality improvement (QI) and research?","options":[{"id":"a","text":"QI requires ethical approval, research does not"},{"id":"b","text":"QI seeks local improvement, research seeks generalizable knowledge"},{"id":"c","text":"QI is hypothesis-driven, research is not"},{"id":"d","text":"QI uses large-scale trials, research uses small tests"}],"answerId":"b","explanation":"QI focuses on local improvement through iterative cycles, while research aims for generalizable knowledge.","kind":"trap","origin":"ai"},{"id":"ifh-health-data-quality~ai-4","moduleId":"ifh-health-data-quality","stem":"What is the first step in the PDSA cycle for quality improvement?","options":[{"id":"a","text":"Do"},{"id":"b","text":"Plan"},{"id":"c","text":"Study"},{"id":"d","text":"Act"}],"answerId":"b","explanation":"The first step in the PDSA cycle is Plan, where the objective and plan for the test are established.","kind":"recall","origin":"ai"},{"id":"ifh-health-data-quality~ai-5","moduleId":"ifh-health-data-quality","stem":"How does the Model for Improvement guide quality improvement projects?","options":[{"id":"a","text":"By providing a checklist of tasks"},{"id":"b","text":"By setting specific research hypotheses"},{"id":"c","text":"By framing improvement with key questions and PDSA cycles"},{"id":"d","text":"By mandating large-scale implementation"}],"answerId":"c","explanation":"The Model for Improvement uses key questions and PDSA cycles to guide data-driven decisions in QI.","kind":"mechanism","origin":"ai"},{"id":"ifh-health-data-quality~ai-6","moduleId":"ifh-health-data-quality","stem":"How does the principle of systems thinking in family medicine relate to quality improvement?","options":[{"id":"a","text":"Both emphasize individual patient care over system processes"},{"id":"b","text":"Both focus on iterative testing of changes"},{"id":"c","text":"Both require structured data for analysis"},{"id":"d","text":"Both aim to improve healthcare delivery through holistic approaches"}],"answerId":"d","explanation":"Systems thinking in family medicine and QI both aim to improve healthcare delivery through holistic approaches.","kind":"integration","linkedModuleIds":["ifh-family-medicine-principles"],"origin":"ai"},{"id":"ifh-health-data-quality~ai-7","moduleId":"ifh-health-data-quality","stem":"What is a key consideration in both health data governance and quality improvement?","options":[{"id":"a","text":"Ensuring data is unstructured"},{"id":"b","text":"Prioritizing rapid implementation"},{"id":"c","text":"Maintaining data privacy and security"},{"id":"d","text":"Focusing solely on outcome indicators"}],"answerId":"c","explanation":"Both health data governance and quality improvement emphasize the importance of maintaining data privacy and security.","kind":"integration","linkedModuleIds":["ifh-health-data-governance"],"origin":"ai"}],"ifh-tcm-overview":[{"id":"ifh-tcm-overview~ai-0","moduleId":"ifh-tcm-overview","stem":"What is the key difference between complementary and alternative medicine?","options":[{"id":"a","text":"Complementary is used alongside conventional medicine; alternative is used instead of it."},{"id":"b","text":"Complementary is used instead of conventional medicine; alternative is used alongside it."},{"id":"c","text":"Both are used instead of conventional medicine."},{"id":"d","text":"Both are used alongside conventional medicine."}],"answerId":"a","explanation":"Complementary medicine is used alongside conventional treatments, while alternative medicine replaces conventional treatments.","kind":"recall","origin":"ai"},{"id":"ifh-tcm-overview~ai-1","moduleId":"ifh-tcm-overview","stem":"Which of the following best describes integrative medicine?","options":[{"id":"a","text":"Combining conventional medicine with any complementary practice."},{"id":"b","text":"Using only evidence-based complementary practices alongside conventional medicine."},{"id":"c","text":"Using alternative medicine instead of conventional treatments."},{"id":"d","text":"Combining any traditional practices with conventional medicine."}],"answerId":"b","explanation":"Integrative medicine involves combining conventional medicine with evidence-based complementary practices in a coordinated way.","kind":"mechanism","origin":"ai"},{"id":"ifh-tcm-overview~ai-2","moduleId":"ifh-tcm-overview","stem":"Why might patients not disclose their use of traditional and complementary medicine (T&CM) to their healthcare providers?","options":[{"id":"a","text":"They are unaware of its relevance."},{"id":"b","text":"They fear ridicule or judgment."},{"id":"c","text":"They believe it is illegal."},{"id":"d","text":"They think it is more effective than conventional medicine."}],"answerId":"b","explanation":"Patients often do not disclose T&CM use due to fear of ridicule or judgment from healthcare providers.","kind":"clinical","origin":"ai"},{"id":"ifh-tcm-overview~ai-3","moduleId":"ifh-tcm-overview","stem":"In the context of Thai traditional medicine, which of the following statements is true?","options":[{"id":"a","text":"It is considered a fringe practice."},{"id":"b","text":"It is not integrated into the national health system."},{"id":"c","text":"It is licensed and has formal training programs."},{"id":"d","text":"It is only practiced in rural areas."}],"answerId":"c","explanation":"Thai traditional medicine is licensed and integrated into the national health system with formal training programs.","kind":"recall","origin":"ai"},{"id":"ifh-tcm-overview~ai-4","moduleId":"ifh-tcm-overview","stem":"A patient with chronic pain is using acupuncture alongside their prescribed medication. How should this be classified?","options":[{"id":"a","text":"Alternative medicine"},{"id":"b","text":"Complementary medicine"},{"id":"c","text":"Integrative medicine"},{"id":"d","text":"Fringe practice"}],"answerId":"b","explanation":"Using acupuncture alongside prescribed medication is an example of complementary medicine.","kind":"clinical","origin":"ai"},{"id":"ifh-tcm-overview~ai-5","moduleId":"ifh-tcm-overview","stem":"How does the use of T&CM relate to the biopsychosocial model of health?","options":[{"id":"a","text":"It focuses solely on biological factors."},{"id":"b","text":"It emphasizes the psychological aspect only."},{"id":"c","text":"It considers cultural and social factors in health."},{"id":"d","text":"It disregards the social context of illness."}],"answerId":"c","explanation":"T&CM use is driven by cultural beliefs and social factors, aligning with the biopsychosocial model that considers these aspects in health.","kind":"integration","linkedModuleIds":["ifh-biopsychosocial-model"],"origin":"ai"},{"id":"ifh-tcm-overview~ai-6","moduleId":"ifh-tcm-overview","stem":"A patient decides to use herbal supplements instead of chemotherapy for cancer treatment. What is this an example of?","options":[{"id":"a","text":"Complementary medicine"},{"id":"b","text":"Alternative medicine"},{"id":"c","text":"Integrative medicine"},{"id":"d","text":"Traditional medicine"}],"answerId":"b","explanation":"Using herbal supplements instead of chemotherapy is an example of alternative medicine, as it replaces conventional treatment.","kind":"trap","origin":"ai"},{"id":"ifh-tcm-overview~ai-7","moduleId":"ifh-tcm-overview","stem":"How might the concept of illness meaning influence a patient's decision to use T&CM?","options":[{"id":"a","text":"It has no influence."},{"id":"b","text":"It only affects their choice of conventional treatments."},{"id":"c","text":"It shapes their understanding and approach to managing their condition."},{"id":"d","text":"It leads them to avoid all forms of treatment."}],"answerId":"c","explanation":"The concept of illness meaning influences how patients perceive and manage their condition, often leading them to explore T&CM options.","kind":"integration","linkedModuleIds":["ifh-disease-vs-illness"],"origin":"ai"}],"ich-demographic-epidemiologic-transition":[{"id":"ich-demographic-epidemiologic-transition~ai-0","moduleId":"ich-demographic-epidemiologic-transition","stem":"Which stage of the Demographic Transition Model is characterized by high birth rates and rapidly falling death rates?","options":[{"id":"a","text":"Stage 1"},{"id":"b","text":"Stage 2"},{"id":"c","text":"Stage 3"},{"id":"d","text":"Stage 4"}],"answerId":"b","explanation":"Stage 2 is marked by a rapid decline in death rates while birth rates remain high, leading to rapid population growth.","kind":"recall","origin":"ai"},{"id":"ich-demographic-epidemiologic-transition~ai-1","moduleId":"ich-demographic-epidemiologic-transition","stem":"What primarily drives the rapid population growth observed in Stage 2 of the Demographic Transition Model?","options":[{"id":"a","text":"Increase in birth rates"},{"id":"b","text":"Decrease in death rates"},{"id":"c","text":"Increase in immigration"},{"id":"d","text":"Decrease in emigration"}],"answerId":"b","explanation":"The rapid population growth in Stage 2 is driven by a decrease in death rates while birth rates remain high.","kind":"trap","origin":"ai"},{"id":"ich-demographic-epidemiologic-transition~ai-2","moduleId":"ich-demographic-epidemiologic-transition","stem":"Which of the following best describes the shift in disease burden during the Epidemiologic Transition?","options":[{"id":"a","text":"From chronic diseases to infectious diseases"},{"id":"b","text":"From infectious diseases to chronic diseases"},{"id":"c","text":"From nutritional deficiencies to infectious diseases"},{"id":"d","text":"From chronic diseases to nutritional deficiencies"}],"answerId":"b","explanation":"The Epidemiologic Transition describes a shift from infectious diseases to chronic non-communicable diseases as the dominant health burden.","kind":"mechanism","origin":"ai"},{"id":"ich-demographic-epidemiologic-transition~ai-3","moduleId":"ich-demographic-epidemiologic-transition","stem":"Thailand is currently classified as an 'aged society.' What percentage of its population is aged 65 and older?","options":[{"id":"a","text":"10%"},{"id":"b","text":"14%"},{"id":"c","text":"20%"},{"id":"d","text":"25%"}],"answerId":"b","explanation":"An 'aged society' is defined as having more than 14% of its population aged 65 and older.","kind":"recall","origin":"ai"},{"id":"ich-demographic-epidemiologic-transition~ai-4","moduleId":"ich-demographic-epidemiologic-transition","stem":"How does population momentum affect a population after fertility rates reach replacement level?","options":[{"id":"a","text":"Population growth stops immediately"},{"id":"b","text":"Population continues to grow due to large cohorts"},{"id":"c","text":"Population declines immediately"},{"id":"d","text":"Population stabilizes immediately"}],"answerId":"b","explanation":"Population momentum causes continued growth due to large cohorts moving through the age structure, even after fertility rates reach replacement level.","kind":"mechanism","origin":"ai"},{"id":"ich-demographic-epidemiologic-transition~ai-5","moduleId":"ich-demographic-epidemiologic-transition","stem":"Which factor is most likely to contribute to a decline in fertility rates during Stage 3 of the Demographic Transition?","options":[{"id":"a","text":"Increased mortality rates"},{"id":"b","text":"Improved sanitation"},{"id":"c","text":"Urbanization and female education"},{"id":"d","text":"Increased agricultural productivity"}],"answerId":"c","explanation":"Urbanization and female education are key factors that contribute to the decline in fertility rates during Stage 3.","kind":"integration","linkedModuleIds":["ich-social-determinants-equity"],"origin":"ai"},{"id":"ich-demographic-epidemiologic-transition~ai-6","moduleId":"ich-demographic-epidemiologic-transition","stem":"How does the demographic transition relate to changes in health system demands?","options":[{"id":"a","text":"Increased need for infectious disease control"},{"id":"b","text":"Increased focus on maternal and child health"},{"id":"c","text":"Greater demand for chronic disease management"},{"id":"d","text":"Greater emphasis on emergency care"}],"answerId":"c","explanation":"As populations transition, there is a greater demand for managing chronic non-communicable diseases.","kind":"integration","linkedModuleIds":["ich-health-system-building-blocks"],"origin":"ai"}],"ich-demography-measures":[{"id":"ich-demography-measures~ai-0","moduleId":"ich-demography-measures","stem":"What is the primary source of data for calculating the Total Fertility Rate (TFR)?","options":[{"id":"a","text":"Census data"},{"id":"b","text":"Vital registration"},{"id":"c","text":"Sample surveys"},{"id":"d","text":"Hospital records"}],"answerId":"c","explanation":"Sample surveys provide detailed information on fertility patterns necessary for TFR calculation.","kind":"recall","origin":"ai"},{"id":"ich-demography-measures~ai-1","moduleId":"ich-demography-measures","stem":"A country with a constrictive population pyramid is likely experiencing which demographic trend?","options":[{"id":"a","text":"High fertility rate"},{"id":"b","text":"High infant mortality rate"},{"id":"c","text":"Population ageing"},{"id":"d","text":"Rapid population growth"}],"answerId":"c","explanation":"A constrictive pyramid indicates a narrowing base due to falling fertility and an ageing population.","kind":"mechanism","origin":"ai"},{"id":"ich-demography-measures~ai-2","moduleId":"ich-demography-measures","stem":"Which of the following is a correct calculation for the Infant Mortality Rate (IMR)?","options":[{"id":"a","text":"Infant deaths per 1,000 total population"},{"id":"b","text":"Infant deaths per 1,000 live births"},{"id":"c","text":"Infant deaths per 1,000 births"},{"id":"d","text":"Infant deaths per 1,000 mid-year population"}],"answerId":"b","explanation":"IMR is calculated as infant deaths per 1,000 live births, not total population.","kind":"trap","origin":"ai"},{"id":"ich-demography-measures~ai-3","moduleId":"ich-demography-measures","stem":"What does a high dependency ratio indicate about a population?","options":[{"id":"a","text":"High economic productivity"},{"id":"b","text":"Low birth rate"},{"id":"c","text":"Increased economic burden on the working-age population"},{"id":"d","text":"Stable population growth"}],"answerId":"c","explanation":"A high dependency ratio means more dependents (young and old) per working-age individual, increasing economic burden.","kind":"clinical","origin":"ai"},{"id":"ich-demography-measures~ai-4","moduleId":"ich-demography-measures","stem":"Which measure is most sensitive to changes in a population's health and development?","options":[{"id":"a","text":"Crude Birth Rate"},{"id":"b","text":"Crude Death Rate"},{"id":"c","text":"Total Fertility Rate"},{"id":"d","text":"Infant Mortality Rate"}],"answerId":"d","explanation":"IMR is sensitive to health and development as it reflects infant vulnerability to conditions like nutrition and sanitation.","kind":"recall","origin":"ai"},{"id":"ich-demography-measures~ai-5","moduleId":"ich-demography-measures","stem":"How does the demographic transition model relate to changes in population structure?","options":[{"id":"a","text":"It predicts immediate population decline"},{"id":"b","text":"It explains shifts from high to low birth and death rates"},{"id":"c","text":"It focuses solely on migration patterns"},{"id":"d","text":"It describes constant population growth"}],"answerId":"b","explanation":"The model explains transitions from high birth and death rates to lower rates, affecting population structure.","kind":"integration","linkedModuleIds":["ich-demographic-epidemiologic-transition"],"origin":"ai"},{"id":"ich-demography-measures~ai-6","moduleId":"ich-demography-measures","stem":"In conducting a literature review on demographic measures, which source is most likely to provide comprehensive data on birth and death rates?","options":[{"id":"a","text":"Newspaper articles"},{"id":"b","text":"Vital registration systems"},{"id":"c","text":"Social media"},{"id":"d","text":"Personal interviews"}],"answerId":"b","explanation":"Vital registration systems continuously record births and deaths, providing comprehensive data.","kind":"integration","linkedModuleIds":["literature-review-purpose-search"],"origin":"ai"}],"ich-disease-prevention-strategies":[{"id":"ich-disease-prevention-strategies~ai-0","moduleId":"ich-disease-prevention-strategies","stem":"Which of the following is an example of a primary prevention strategy?","options":[{"id":"a","text":"Vaccination programs"},{"id":"b","text":"Cancer screening"},{"id":"c","text":"Rehabilitation services"},{"id":"d","text":"Blood pressure monitoring"}],"answerId":"a","explanation":"Primary prevention aims to prevent disease before it occurs, such as through vaccination.","kind":"recall","origin":"ai"},{"id":"ich-disease-prevention-strategies~ai-1","moduleId":"ich-disease-prevention-strategies","stem":"What is the main goal of a population strategy in disease prevention?","options":[{"id":"a","text":"To treat individuals with the highest risk"},{"id":"b","text":"To shift the entire risk distribution"},{"id":"c","text":"To provide individualized treatment plans"},{"id":"d","text":"To focus on tertiary care"}],"answerId":"b","explanation":"A population strategy aims to shift the entire risk distribution to reduce the incidence of disease across the population.","kind":"mechanism","origin":"ai"},{"id":"ich-disease-prevention-strategies~ai-2","moduleId":"ich-disease-prevention-strategies","stem":"Which statement best describes the prevention paradox?","options":[{"id":"a","text":"High-risk strategies benefit the most individuals"},{"id":"b","text":"Population strategies provide large community benefit but little individual benefit"},{"id":"c","text":"Screening is a form of primary prevention"},{"id":"d","text":"Tertiary prevention is more cost-effective than primary prevention"}],"answerId":"b","explanation":"The prevention paradox describes how population strategies offer large community benefits but minimal individual benefits.","kind":"mechanism","origin":"ai"},{"id":"ich-disease-prevention-strategies~ai-3","moduleId":"ich-disease-prevention-strategies","stem":"Why might a high-risk strategy be insufficient to prevent the majority of cases in a population?","options":[{"id":"a","text":"It is too costly"},{"id":"b","text":"It targets only a small portion of the population"},{"id":"c","text":"It requires complex technology"},{"id":"d","text":"It is not evidence-based"}],"answerId":"b","explanation":"High-risk strategies target only individuals at the tail of the risk distribution, missing the majority at moderate risk.","kind":"trap","origin":"ai"},{"id":"ich-disease-prevention-strategies~ai-4","moduleId":"ich-disease-prevention-strategies","stem":"Which level of prevention does cancer screening fall under?","options":[{"id":"a","text":"Primordial prevention"},{"id":"b","text":"Primary prevention"},{"id":"c","text":"Secondary prevention"},{"id":"d","text":"Tertiary prevention"}],"answerId":"c","explanation":"Cancer screening is a form of secondary prevention as it aims to detect disease early in at-risk populations.","kind":"recall","origin":"ai"},{"id":"ich-disease-prevention-strategies~ai-5","moduleId":"ich-disease-prevention-strategies","stem":"How does the concept of the prevention paradox relate to health promotion strategies?","options":[{"id":"a","text":"Health promotion focuses solely on individual benefits"},{"id":"b","text":"Health promotion strategies often have large community benefits but small individual benefits"},{"id":"c","text":"Health promotion is unrelated to the prevention paradox"},{"id":"d","text":"Health promotion only targets high-risk individuals"}],"answerId":"b","explanation":"Health promotion strategies often align with the prevention paradox, offering large community benefits but small individual benefits.","kind":"integration","linkedModuleIds":["ich-health-promotion"],"origin":"ai"},{"id":"ich-disease-prevention-strategies~ai-6","moduleId":"ich-disease-prevention-strategies","stem":"In the context of disease prevention, how does descriptive epidemiology contribute to the selection of a prevention strategy?","options":[{"id":"a","text":"It provides data to identify high-risk individuals"},{"id":"b","text":"It determines the cost-effectiveness of tertiary prevention"},{"id":"c","text":"It helps to understand the distribution of risk factors in a population"},{"id":"d","text":"It focuses on the treatment of existing diseases"}],"answerId":"c","explanation":"Descriptive epidemiology helps to understand the distribution of risk factors, informing the choice between high-risk and population strategies.","kind":"integration","linkedModuleIds":["ich-descriptive-epi-surveillance"],"origin":"ai"}],"ich-health-promotion":[{"id":"ich-health-promotion~ai-0","moduleId":"ich-health-promotion","stem":"Which of the following is NOT one of the five action areas of the Ottawa Charter for Health Promotion?","options":[{"id":"a","text":"Develop personal skills"},{"id":"b","text":"Strengthen community action"},{"id":"c","text":"Increase hospital funding"},{"id":"d","text":"Create supportive environments"}],"answerId":"c","explanation":"Increasing hospital funding is not an action area; the Charter focuses on prevention and promotion, not curative services.","kind":"recall","origin":"ai"},{"id":"ich-health-promotion~ai-1","moduleId":"ich-health-promotion","stem":"What is the primary goal of health promotion according to the Ottawa Charter?","options":[{"id":"a","text":"To treat diseases"},{"id":"b","text":"To enable people to increase control over their health"},{"id":"c","text":"To provide health education"},{"id":"d","text":"To fund healthcare services"}],"answerId":"b","explanation":"The Ottawa Charter defines health promotion as enabling people to increase control over and improve their health.","kind":"recall","origin":"ai"},{"id":"ich-health-promotion~ai-2","moduleId":"ich-health-promotion","stem":"How does the Ottawa Charter's 'reorient health services' action area differ from traditional healthcare approaches?","options":[{"id":"a","text":"Focuses on curative care"},{"id":"b","text":"Emphasizes prevention and promotion"},{"id":"c","text":"Prioritizes hospital-based services"},{"id":"d","text":"Increases pharmaceutical interventions"}],"answerId":"b","explanation":"Reorienting health services shifts focus from curative care to prevention and health promotion.","kind":"mechanism","origin":"ai"},{"id":"ich-health-promotion~ai-3","moduleId":"ich-health-promotion","stem":"Which of the following best describes the difference between health promotion and health education?","options":[{"id":"a","text":"Health promotion is a subset of health education"},{"id":"b","text":"Health education is a subset of health promotion"},{"id":"c","text":"They are synonymous"},{"id":"d","text":"Health education focuses on policy changes"}],"answerId":"b","explanation":"Health education is one component of health promotion, which also includes policy, environment, and community actions.","kind":"trap","origin":"ai"},{"id":"ich-health-promotion~ai-4","moduleId":"ich-health-promotion","stem":"In the context of the Ottawa Charter, what role does 'Advocate' play in health promotion?","options":[{"id":"a","text":"Providing direct medical care"},{"id":"b","text":"Supporting policy changes for health"},{"id":"c","text":"Educating individuals about health"},{"id":"d","text":"Conducting medical research"}],"answerId":"b","explanation":"Advocacy in health promotion involves supporting policy changes that improve health determinants.","kind":"mechanism","origin":"ai"},{"id":"ich-health-promotion~ai-5","moduleId":"ich-health-promotion","stem":"How does the 'settings approach' in health promotion integrate with the concept of Healthy Cities?","options":[{"id":"a","text":"By focusing solely on individual behavior change"},{"id":"b","text":"By embedding health into daily environments where people live and work"},{"id":"c","text":"By increasing hospital-based interventions"},{"id":"d","text":"By isolating health promotion to clinical settings"}],"answerId":"b","explanation":"The settings approach integrates health into daily environments, such as cities, schools, and workplaces.","kind":"clinical","origin":"ai"},{"id":"ich-health-promotion~ai-6","moduleId":"ich-health-promotion","stem":"Which of the following is an example of how health promotion can address social determinants of health?","options":[{"id":"a","text":"Providing health education in schools"},{"id":"b","text":"Implementing policies to reduce poverty"},{"id":"c","text":"Increasing the number of hospitals"},{"id":"d","text":"Focusing on individual lifestyle changes"}],"answerId":"b","explanation":"Health promotion can address social determinants by implementing policies that tackle issues like poverty.","kind":"integration","linkedModuleIds":["ich-social-determinants-equity"],"origin":"ai"},{"id":"ich-health-promotion~ai-7","moduleId":"ich-health-promotion","stem":"How does the Ottawa Charter's approach to health promotion complement disease prevention strategies?","options":[{"id":"a","text":"By focusing solely on curative measures"},{"id":"b","text":"By emphasizing individual responsibility for health"},{"id":"c","text":"By addressing upstream determinants of health"},{"id":"d","text":"By increasing the number of healthcare providers"}],"answerId":"c","explanation":"The Charter complements disease prevention by addressing upstream determinants, not just individual behaviors.","kind":"integration","linkedModuleIds":["ich-disease-prevention-strategies"],"origin":"ai"}],"ich-health-system-building-blocks":[{"id":"ich-health-system-building-blocks~ai-0","moduleId":"ich-health-system-building-blocks","stem":"Which of the following is NOT one of the WHO health system building blocks?","options":[{"id":"a","text":"Health workforce"},{"id":"b","text":"Service delivery"},{"id":"c","text":"Health education"},{"id":"d","text":"Financing"}],"answerId":"c","explanation":"Health education is not one of the six WHO health system building blocks.","kind":"recall","origin":"ai"},{"id":"ich-health-system-building-blocks~ai-1","moduleId":"ich-health-system-building-blocks","stem":"A hospital experiences frequent stock-outs of essential medications. Which building block is most likely failing?","options":[{"id":"a","text":"Service delivery"},{"id":"b","text":"Health workforce"},{"id":"c","text":"Medical products, vaccines & technologies"},{"id":"d","text":"Leadership/governance"}],"answerId":"c","explanation":"Ongoing stock-outs indicate a failure in the 'medical products, vaccines & technologies' block, not service delivery.","kind":"trap","origin":"ai"},{"id":"ich-health-system-building-blocks~ai-2","moduleId":"ich-health-system-building-blocks","stem":"What is the primary role of the leadership/governance building block in the WHO framework?","options":[{"id":"a","text":"Providing direct patient care"},{"id":"b","text":"Setting policy and aligning other blocks"},{"id":"c","text":"Financing health services"},{"id":"d","text":"Delivering medical products"}],"answerId":"b","explanation":"Leadership/governance sets policy and aligns the other blocks to ensure cohesive functioning.","kind":"mechanism","origin":"ai"},{"id":"ich-health-system-building-blocks~ai-3","moduleId":"ich-health-system-building-blocks","stem":"Which of the following best describes the role of primary care in the health system?","options":[{"id":"a","text":"Provides specialized medical services"},{"id":"b","text":"Acts as the first-contact gatekeeper"},{"id":"c","text":"Supplies medical products"},{"id":"d","text":"Manages health financing"}],"answerId":"b","explanation":"Primary care acts as the first-contact gatekeeper, directing patients to appropriate levels of care.","kind":"clinical","origin":"ai"},{"id":"ich-health-system-building-blocks~ai-4","moduleId":"ich-health-system-building-blocks","stem":"In the context of the WHO building blocks, what is the ultimate goal of a health system?","options":[{"id":"a","text":"Maximizing service delivery"},{"id":"b","text":"Achieving better health outcomes"},{"id":"c","text":"Increasing the number of healthcare workers"},{"id":"d","text":"Expanding medical product availability"}],"answerId":"b","explanation":"The ultimate goal of a health system is to achieve better health outcomes, along with responsiveness, financial protection, and efficiency.","kind":"mechanism","origin":"ai"},{"id":"ich-health-system-building-blocks~ai-5","moduleId":"ich-health-system-building-blocks","stem":"How does the financing building block relate to the goal of financial risk protection in health systems?","options":[{"id":"a","text":"It directly provides medical services"},{"id":"b","text":"It ensures equitable access to health services"},{"id":"c","text":"It raises and pools funds to protect against financial hardship"},{"id":"d","text":"It manages the health workforce"}],"answerId":"c","explanation":"The financing block raises and pools funds to protect individuals from financial hardship due to healthcare costs.","kind":"integration","linkedModuleIds":["ich-health-financing-uhc"],"origin":"ai"},{"id":"ich-health-system-building-blocks~ai-6","moduleId":"ich-health-system-building-blocks","stem":"How does a strong primary care system contribute to the effectiveness of Thailand's Universal Coverage Scheme (UCS)?","options":[{"id":"a","text":"By reducing the need for secondary care"},{"id":"b","text":"By serving as the main provider of tertiary care"},{"id":"c","text":"By ensuring the availability of medical products"},{"id":"d","text":"By acting as a gatekeeper with two-way referral"}],"answerId":"d","explanation":"A strong primary care system acts as a gatekeeper with two-way referral, essential for the UCS's effectiveness.","kind":"integration","linkedModuleIds":["ich-thai-health-system-schemes"],"origin":"ai"}],"ich-health-financing-uhc":[{"id":"ich-health-financing-uhc~ai-0","moduleId":"ich-health-financing-uhc","stem":"Which of the following is the least equitable source of health financing?","options":[{"id":"a","text":"Out-of-pocket payment"},{"id":"b","text":"General taxation"},{"id":"c","text":"Social health insurance"},{"id":"d","text":"Private insurance"}],"answerId":"a","explanation":"Out-of-pocket payment requires individuals to pay at the point of use, offering no cross-subsidy or financial protection.","kind":"recall","origin":"ai"},{"id":"ich-health-financing-uhc~ai-1","moduleId":"ich-health-financing-uhc","stem":"What is the primary function of risk pooling in health financing?","options":[{"id":"a","text":"To increase individual contributions"},{"id":"b","text":"To separate payment from time of use"},{"id":"c","text":"To decrease government spending"},{"id":"d","text":"To eliminate private insurance"}],"answerId":"b","explanation":"Risk pooling separates payment from the time of use and allows for cross-subsidization, providing financial protection.","kind":"mechanism","origin":"ai"},{"id":"ich-health-financing-uhc~ai-2","moduleId":"ich-health-financing-uhc","stem":"In the context of Universal Health Coverage, what does the 'height' axis of the UHC cube represent?","options":[{"id":"a","text":"Population covered"},{"id":"b","text":"Services covered"},{"id":"c","text":"Proportion of direct costs covered"},{"id":"d","text":"Administrative efficiency"}],"answerId":"c","explanation":"The 'height' axis of the UHC cube represents the proportion of direct costs covered, aiming to reduce out-of-pocket expenses.","kind":"recall","origin":"ai"},{"id":"ich-health-financing-uhc~ai-3","moduleId":"ich-health-financing-uhc","stem":"Which of the following statements about strategic purchasing in health financing is true?","options":[{"id":"a","text":"It involves paying providers the same amount regardless of service quality"},{"id":"b","text":"It focuses on buying value and steering providers towards efficient care"},{"id":"c","text":"It primarily aims to reduce administrative costs"},{"id":"d","text":"It eliminates the need for risk pooling"}],"answerId":"b","explanation":"Strategic purchasing involves choosing what services to buy, from whom, and how to pay, focusing on value and efficiency.","kind":"mechanism","origin":"ai"},{"id":"ich-health-financing-uhc~ai-4","moduleId":"ich-health-financing-uhc","stem":"How does Thailand's Universal Coverage Scheme (UCS) exemplify the UHC cube?","options":[{"id":"a","text":"It maximizes all three axes simultaneously"},{"id":"b","text":"It focuses only on increasing service coverage"},{"id":"c","text":"It balances breadth, depth, and height within budget constraints"},{"id":"d","text":"It eliminates out-of-pocket payments entirely"}],"answerId":"c","explanation":"Thailand's UCS is a classic example of filling the UHC cube by balancing population, service, and cost coverage within finite resources.","kind":"clinical","linkedModuleIds":["ich-thai-health-system-schemes"],"origin":"ai"},{"id":"ich-health-financing-uhc~ai-5","moduleId":"ich-health-financing-uhc","stem":"Which health financing strategy is most likely to lead to catastrophic health expenditure?","options":[{"id":"a","text":"General taxation"},{"id":"b","text":"Social health insurance"},{"id":"c","text":"Out-of-pocket payment"},{"id":"d","text":"Prepayment and pooling"}],"answerId":"c","explanation":"Out-of-pocket payment at the point of use is the most regressive and can lead to catastrophic health expenditure.","kind":"trap","origin":"ai"},{"id":"ich-health-financing-uhc~ai-6","moduleId":"ich-health-financing-uhc","stem":"How does the concept of risk pooling in health financing relate to economic evaluation?","options":[{"id":"a","text":"It reduces the need for cost-effectiveness analysis"},{"id":"b","text":"It ensures all health interventions are equally funded"},{"id":"c","text":"It influences the allocation of resources in cost-effectiveness studies"},{"id":"d","text":"It eliminates the need for health technology assessment"}],"answerId":"c","explanation":"Risk pooling affects resource allocation decisions, which are crucial in economic evaluations and cost-effectiveness studies.","kind":"integration","linkedModuleIds":["ich-economic-evaluation-hta"],"origin":"ai"}],"ich-social-determinants-equity":[{"id":"ich-social-determinants-equity~ai-0","moduleId":"ich-social-determinants-equity","stem":"Which of the following best describes the concept of health equity?","options":[{"id":"a","text":"Distributing resources according to need to achieve fair health outcomes"},{"id":"b","text":"Providing the same resources to everyone regardless of need"},{"id":"c","text":"Ensuring everyone has access to basic healthcare services"},{"id":"d","text":"Focusing only on improving the health of the poorest populations"}],"answerId":"a","explanation":"Health equity involves distributing resources based on need to ensure fair health outcomes, not merely providing identical resources to all.","kind":"recall","origin":"ai"},{"id":"ich-social-determinants-equity~ai-1","moduleId":"ich-social-determinants-equity","stem":"The Whitehall studies demonstrated which key concept in health equity?","options":[{"id":"a","text":"Health outcomes improve only for the wealthiest individuals"},{"id":"b","text":"Mortality rates are uniform across all employment grades"},{"id":"c","text":"Health follows a social gradient, worsening with each step down the socioeconomic ladder"},{"id":"d","text":"Only the poorest populations experience significant health disparities"}],"answerId":"c","explanation":"The Whitehall studies showed that health worsens step-by-step down the socioeconomic ladder, not just among the poorest.","kind":"recall","origin":"ai"},{"id":"ich-social-determinants-equity~ai-2","moduleId":"ich-social-determinants-equity","stem":"What is the primary reason for implementing Health in All Policies (HiAP)?","options":[{"id":"a","text":"To centralize all health-related decision-making within the health sector"},{"id":"b","text":"To address social determinants of health that lie outside the health sector"},{"id":"c","text":"To increase funding for healthcare services"},{"id":"d","text":"To focus on individual lifestyle changes"}],"answerId":"b","explanation":"HiAP is implemented because most determinants of health lie outside the health sector, requiring a multi-sectoral approach.","kind":"mechanism","origin":"ai"},{"id":"ich-social-determinants-equity~ai-3","moduleId":"ich-social-determinants-equity","stem":"Which of the following is an example of a health inequity?","options":[{"id":"a","text":"A genetic condition affecting a specific ethnic group"},{"id":"b","text":"Higher rates of diabetes in low-income neighborhoods due to lack of access to healthy food"},{"id":"c","text":"Increased incidence of seasonal flu among the elderly"},{"id":"d","text":"Variation in skin cancer rates due to geographical differences"}],"answerId":"b","explanation":"A health inequity is an avoidable, unfair, and unjust difference, such as higher diabetes rates due to lack of access to healthy food.","kind":"clinical","origin":"ai"},{"id":"ich-social-determinants-equity~ai-4","moduleId":"ich-social-determinants-equity","stem":"How does the concept of 'the causes of the causes' relate to disease prevention strategies?","options":[{"id":"a","text":"It focuses solely on treating individual risk factors like smoking"},{"id":"b","text":"It addresses underlying social conditions that lead to risk factors"},{"id":"c","text":"It emphasizes genetic predispositions over environmental factors"},{"id":"d","text":"It prioritizes acute care over preventive measures"}],"answerId":"b","explanation":"Addressing 'the causes of the causes' involves targeting underlying social conditions that lead to risk factors, aligning with disease prevention strategies.","kind":"integration","linkedModuleIds":["ich-disease-prevention-strategies"],"origin":"ai"},{"id":"ich-social-determinants-equity~ai-5","moduleId":"ich-social-determinants-equity","stem":"In the context of health promotion, why is equity more important than equality?","options":[{"id":"a","text":"Equity ensures everyone receives the same amount of resources"},{"id":"b","text":"Equality results in better health outcomes for disadvantaged groups"},{"id":"c","text":"Equity addresses the specific needs of different populations to achieve fair health outcomes"},{"id":"d","text":"Equality is easier to implement across all populations"}],"answerId":"c","explanation":"Equity is crucial in health promotion as it addresses specific needs, ensuring fair health outcomes, unlike equality which may not account for varying needs.","kind":"integration","linkedModuleIds":["ich-health-promotion"],"origin":"ai"},{"id":"ich-social-determinants-equity~ai-6","moduleId":"ich-social-determinants-equity","stem":"Which statement about the social gradient in health is true?","options":[{"id":"a","text":"It only affects individuals living in poverty"},{"id":"b","text":"It shows that health improves with each step up the socioeconomic ladder"},{"id":"c","text":"It suggests that health disparities are random and unavoidable"},{"id":"d","text":"It indicates that only the richest benefit from better health outcomes"}],"answerId":"b","explanation":"The social gradient in health demonstrates that health improves with each step up the socioeconomic ladder, affecting all levels.","kind":"recall","origin":"ai"}],"ich-determinants-of-health":[{"id":"ich-determinants-of-health~ai-0","moduleId":"ich-determinants-of-health","stem":"Which of the following is considered a non-modifiable determinant of health according to the Dahlgren–Whitehead model?","options":[{"id":"a","text":"Genetic factors"},{"id":"b","text":"Dietary habits"},{"id":"c","text":"Employment status"},{"id":"d","text":"Housing conditions"}],"answerId":"a","explanation":"Genetic factors are part of the core layer and are non-modifiable.","kind":"recall","origin":"ai"},{"id":"ich-determinants-of-health~ai-1","moduleId":"ich-determinants-of-health","stem":"In the context of health determinants, what is an example of an upstream intervention?","options":[{"id":"a","text":"Smoking cessation programs"},{"id":"b","text":"Vaccination campaigns"},{"id":"c","text":"Implementing a living wage policy"},{"id":"d","text":"Cardiac rehabilitation"}],"answerId":"c","explanation":"Upstream interventions address structural causes like socioeconomic policies.","kind":"mechanism","origin":"ai"},{"id":"ich-determinants-of-health~ai-2","moduleId":"ich-determinants-of-health","stem":"Which statement best describes the contribution of medical care to population health outcomes?","options":[{"id":"a","text":"Medical care accounts for the majority of health outcomes"},{"id":"b","text":"Medical care contributes approximately 10-20% to health outcomes"},{"id":"c","text":"Medical care is the sole determinant of health outcomes"},{"id":"d","text":"Medical care has no impact on health outcomes"}],"answerId":"b","explanation":"Medical care contributes only about 10-20% to population health outcomes.","kind":"recall","origin":"ai"},{"id":"ich-determinants-of-health~ai-3","moduleId":"ich-determinants-of-health","stem":"A public health initiative focuses on improving education and income levels in a community. This approach is targeting which layer of the Dahlgren–Whitehead model?","options":[{"id":"a","text":"Individual lifestyle factors"},{"id":"b","text":"Social and community networks"},{"id":"c","text":"Living and working conditions"},{"id":"d","text":"General socioeconomic, cultural, and environmental conditions"}],"answerId":"d","explanation":"Education and income are part of the general socioeconomic conditions layer.","kind":"clinical","origin":"ai"},{"id":"ich-determinants-of-health~ai-4","moduleId":"ich-determinants-of-health","stem":"In the context of health promotion, which strategy aligns with addressing the 'causes of the causes' of health issues?","options":[{"id":"a","text":"Promoting physical activity"},{"id":"b","text":"Improving access to healthcare"},{"id":"c","text":"Enhancing educational opportunities"},{"id":"d","text":"Providing nutritional counseling"}],"answerId":"c","explanation":"Enhancing educational opportunities addresses upstream determinants.","kind":"integration","linkedModuleIds":["ich-health-promotion"],"origin":"ai"},{"id":"ich-determinants-of-health~ai-5","moduleId":"ich-determinants-of-health","stem":"How do socioeconomic conditions influence individual lifestyle choices according to the Dahlgren–Whitehead model?","options":[{"id":"a","text":"They have no influence"},{"id":"b","text":"They directly determine genetic factors"},{"id":"c","text":"They set limits on lifestyle choices"},{"id":"d","text":"They are irrelevant to lifestyle choices"}],"answerId":"c","explanation":"Socioeconomic conditions constrain the choices available to individuals.","kind":"mechanism","origin":"ai"},{"id":"ich-determinants-of-health~ai-6","moduleId":"ich-determinants-of-health","stem":"A patient with an atrial septal defect (ASD) is concerned about the impact of environmental factors on their health. Which determinant of health should be prioritized in their management plan?","options":[{"id":"a","text":"Genetic counseling"},{"id":"b","text":"Improving air quality"},{"id":"c","text":"Regular medical check-ups"},{"id":"d","text":"Nutritional support"}],"answerId":"c","explanation":"Regular medical check-ups are crucial for managing ASD, though environmental factors are also important.","kind":"integration","linkedModuleIds":["asd"],"origin":"ai"}],"ich-thai-health-system-schemes":[{"id":"ich-thai-health-system-schemes~ai-0","moduleId":"ich-thai-health-system-schemes","stem":"Which public health scheme in Thailand is funded through tripartite payroll contributions?","options":[{"id":"a","text":"UCS"},{"id":"b","text":"SSS"},{"id":"c","text":"CSMBS"},{"id":"d","text":"None of the above"}],"answerId":"b","explanation":"SSS is funded by contributions from the employee, employer, and government.","kind":"recall","origin":"ai"},{"id":"ich-thai-health-system-schemes~ai-1","moduleId":"ich-thai-health-system-schemes","stem":"A Thai government employee and their family are covered under which health scheme?","options":[{"id":"a","text":"UCS"},{"id":"b","text":"SSS"},{"id":"c","text":"CSMBS"},{"id":"d","text":"Private Insurance"}],"answerId":"c","explanation":"CSMBS covers government employees and their dependents.","kind":"recall","origin":"ai"},{"id":"ich-thai-health-system-schemes~ai-2","moduleId":"ich-thai-health-system-schemes","stem":"What is a significant financial risk associated with the CSMBS scheme?","options":[{"id":"a","text":"Capitation payment"},{"id":"b","text":"Fee-for-service payment"},{"id":"c","text":"Global budget payment"},{"id":"d","text":"Out-of-pocket payment"}],"answerId":"b","explanation":"CSMBS uses fee-for-service for outpatient care, which can lead to cost escalation.","kind":"mechanism","origin":"ai"},{"id":"ich-thai-health-system-schemes~ai-3","moduleId":"ich-thai-health-system-schemes","stem":"Which scheme primarily covers informal workers, children, and the elderly in Thailand?","options":[{"id":"a","text":"UCS"},{"id":"b","text":"SSS"},{"id":"c","text":"CSMBS"},{"id":"d","text":"Workmen’s Compensation Fund"}],"answerId":"a","explanation":"UCS covers those not in SSS or CSMBS, including informal workers and the elderly.","kind":"recall","origin":"ai"},{"id":"ich-thai-health-system-schemes~ai-4","moduleId":"ich-thai-health-system-schemes","stem":"Which scheme is most likely to incentivize preventive care due to its payment method?","options":[{"id":"a","text":"UCS"},{"id":"b","text":"SSS"},{"id":"c","text":"CSMBS"},{"id":"d","text":"None of the above"}],"answerId":"a","explanation":"UCS uses capitation, which encourages cost containment and preventive care.","kind":"mechanism","origin":"ai"},{"id":"ich-thai-health-system-schemes~ai-5","moduleId":"ich-thai-health-system-schemes","stem":"How does the payment method of SSS influence provider behavior compared to CSMBS?","options":[{"id":"a","text":"Encourages more procedures"},{"id":"b","text":"Encourages preventive care"},{"id":"c","text":"No influence"},{"id":"d","text":"Increases out-of-pocket costs"}],"answerId":"b","explanation":"SSS uses capitation, which promotes preventive care, unlike CSMBS's fee-for-service.","kind":"mechanism","origin":"ai"},{"id":"ich-thai-health-system-schemes~ai-6","moduleId":"ich-thai-health-system-schemes","stem":"In the context of Thailand's health system, which scheme is most relevant for economic evaluations of cost-effectiveness?","options":[{"id":"a","text":"UCS"},{"id":"b","text":"SSS"},{"id":"c","text":"CSMBS"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"All schemes can be evaluated for cost-effectiveness in economic evaluations.","kind":"integration","linkedModuleIds":["ich-economic-evaluation-hta"],"origin":"ai"},{"id":"ich-thai-health-system-schemes~ai-7","moduleId":"ich-thai-health-system-schemes","stem":"Which scheme's financing is most aligned with the principles of universal health coverage?","options":[{"id":"a","text":"UCS"},{"id":"b","text":"SSS"},{"id":"c","text":"CSMBS"},{"id":"d","text":"Private Insurance"}],"answerId":"a","explanation":"UCS is tax-funded and covers the majority of the population, aligning with UHC principles.","kind":"integration","linkedModuleIds":["ich-health-financing-uhc"],"origin":"ai"}],"ich-occupational-diseases-diagnosis":[{"id":"ich-occupational-diseases-diagnosis~ai-0","moduleId":"ich-occupational-diseases-diagnosis","stem":"A 55-year-old man presents with progressive shortness of breath and a history of working in construction for 30 years. Chest X-ray shows pleural plaques. Which exposure is most likely responsible for his condition?","options":[{"id":"a","text":"Asbestos"},{"id":"b","text":"Silica"},{"id":"c","text":"Coal dust"},{"id":"d","text":"Lead"}],"answerId":"a","explanation":"Pleural plaques are characteristic of asbestos exposure, common in construction workers.","kind":"recall","origin":"ai"},{"id":"ich-occupational-diseases-diagnosis~ai-1","moduleId":"ich-occupational-diseases-diagnosis","stem":"A factory worker complains of worsening asthma symptoms that improve on weekends. What is the most likely diagnosis?","options":[{"id":"a","text":"Allergic asthma"},{"id":"b","text":"Occupational asthma"},{"id":"c","text":"Exercise-induced asthma"},{"id":"d","text":"Viral-induced asthma"}],"answerId":"b","explanation":"Symptoms that improve away from work suggest occupational asthma.","kind":"clinical","origin":"ai"},{"id":"ich-occupational-diseases-diagnosis~ai-2","moduleId":"ich-occupational-diseases-diagnosis","stem":"Which of the following is a classic audiometric finding in noise-induced hearing loss?","options":[{"id":"a","text":"Conductive hearing loss"},{"id":"b","text":"Bilateral sensorineural loss with 4 kHz notch"},{"id":"c","text":"Unilateral sensorineural loss"},{"id":"d","text":"Mixed hearing loss"}],"answerId":"b","explanation":"Noise-induced hearing loss typically presents as bilateral sensorineural loss with a 4 kHz notch.","kind":"recall","origin":"ai"},{"id":"ich-occupational-diseases-diagnosis~ai-3","moduleId":"ich-occupational-diseases-diagnosis","stem":"A patient with a history of shipyard work 20 years ago presents with dyspnea and a chest X-ray showing interstitial fibrosis. What is the most likely diagnosis?","options":[{"id":"a","text":"Silicosis"},{"id":"b","text":"Asbestosis"},{"id":"c","text":"Coal worker's pneumoconiosis"},{"id":"d","text":"Sarcoidosis"}],"answerId":"b","explanation":"Asbestosis is associated with shipyard work and has a long latency period.","kind":"trap","origin":"ai"},{"id":"ich-occupational-diseases-diagnosis~ai-4","moduleId":"ich-occupational-diseases-diagnosis","stem":"Which step is crucial in establishing the work-relatedness of a disease?","options":[{"id":"a","text":"Confirming the disease"},{"id":"b","text":"Identifying non-occupational causes"},{"id":"c","text":"Documenting exposure at work"},{"id":"d","text":"Assessing family history"}],"answerId":"c","explanation":"Documenting exposure at work is essential to establish work-relatedness.","kind":"mechanism","origin":"ai"},{"id":"ich-occupational-diseases-diagnosis~ai-5","moduleId":"ich-occupational-diseases-diagnosis","stem":"A 60-year-old former miner presents with cough and dyspnea. Chest X-ray reveals nodular opacities in the upper lobes. Which occupational exposure is most likely responsible?","options":[{"id":"a","text":"Asbestos"},{"id":"b","text":"Silica"},{"id":"c","text":"Coal dust"},{"id":"d","text":"Lead"}],"answerId":"b","explanation":"Silica exposure in miners can lead to silicosis, characterized by nodular opacities in the upper lobes.","kind":"integration","linkedModuleIds":["pulmonary-fibrosis-pneumoconioses"],"origin":"ai"},{"id":"ich-occupational-diseases-diagnosis~ai-6","moduleId":"ich-occupational-diseases-diagnosis","stem":"A worker in a battery manufacturing plant presents with abdominal pain and anemia. Which occupational exposure should be considered?","options":[{"id":"a","text":"Asbestos"},{"id":"b","text":"Silica"},{"id":"c","text":"Lead"},{"id":"d","text":"Coal dust"}],"answerId":"c","explanation":"Lead exposure is common in battery manufacturing and can cause abdominal pain and anemia.","kind":"integration","linkedModuleIds":["ich-occupational-hazards"],"origin":"ai"}],"ich-environmental-health-overview":[{"id":"ich-environmental-health-overview~ai-0","moduleId":"ich-environmental-health-overview","stem":"Which of the following environmental factors is most directly associated with an increased risk of cardiovascular disease?","options":[{"id":"a","text":"PM2.5 air pollution"},{"id":"b","text":"Unsafe drinking water"},{"id":"c","text":"Noise pollution"},{"id":"d","text":"Lead exposure"}],"answerId":"a","explanation":"PM2.5 particles can penetrate deep into the lungs and enter the bloodstream, contributing to cardiovascular disease.","kind":"mechanism","origin":"ai"},{"id":"ich-environmental-health-overview~ai-1","moduleId":"ich-environmental-health-overview","stem":"What is the primary health impact of inadequate water, sanitation, and hygiene (WASH) in low-income settings?","options":[{"id":"a","text":"Increased cardiovascular disease"},{"id":"b","text":"Higher rates of diarrhoeal disease"},{"id":"c","text":"Elevated respiratory infections"},{"id":"d","text":"Greater incidence of skin cancer"}],"answerId":"b","explanation":"WASH failures primarily lead to diarrhoeal diseases due to the faecal-oral transmission route.","kind":"recall","origin":"ai"},{"id":"ich-environmental-health-overview~ai-2","moduleId":"ich-environmental-health-overview","stem":"In the context of environmental health, which group is most likely to experience higher exposure to environmental risks?","options":[{"id":"a","text":"Urban middle class"},{"id":"b","text":"Rural affluent"},{"id":"c","text":"Urban poor"},{"id":"d","text":"Rural middle class"}],"answerId":"c","explanation":"Environmental risks are inequitably distributed, with the urban poor facing higher exposure due to factors like housing and location.","kind":"clinical","origin":"ai"},{"id":"ich-environmental-health-overview~ai-3","moduleId":"ich-environmental-health-overview","stem":"Which of the following is a common misconception about particulate matter pollution?","options":[{"id":"a","text":"PM10 is more harmful than PM2.5"},{"id":"b","text":"PM2.5 can cause respiratory diseases"},{"id":"c","text":"PM2.5 can enter the bloodstream"},{"id":"d","text":"PM2.5 is a key metric for air quality"}],"answerId":"a","explanation":"A common trap is thinking PM10 is more harmful, but PM2.5 is more dangerous due to its ability to penetrate deeper into the lungs.","kind":"trap","origin":"ai"},{"id":"ich-environmental-health-overview~ai-4","moduleId":"ich-environmental-health-overview","stem":"Which environmental factor is primarily targeted to reduce under-5 mortality in low-income countries?","options":[{"id":"a","text":"Air pollution control"},{"id":"b","text":"Improved WASH"},{"id":"c","text":"Noise reduction"},{"id":"d","text":"Chemical safety"}],"answerId":"b","explanation":"Improving WASH is crucial in reducing under-5 mortality by preventing diarrhoeal diseases.","kind":"recall","origin":"ai"},{"id":"ich-environmental-health-overview~ai-5","moduleId":"ich-environmental-health-overview","stem":"How does the concept of environmental justice relate to the distribution of environmental health risks?","options":[{"id":"a","text":"It ensures equal exposure to risks"},{"id":"b","text":"It highlights unequal exposure among different socioeconomic groups"},{"id":"c","text":"It focuses on individual behavior changes"},{"id":"d","text":"It addresses genetic predispositions"}],"answerId":"b","explanation":"Environmental justice emphasizes that disadvantaged groups often face higher exposure to environmental risks.","kind":"mechanism","origin":"ai"},{"id":"ich-environmental-health-overview~ai-6","moduleId":"ich-environmental-health-overview","stem":"How does the environmental health burden relate to the determinants of health?","options":[{"id":"a","text":"It is solely determined by genetic factors"},{"id":"b","text":"It is influenced by modifiable environmental factors"},{"id":"c","text":"It is unaffected by socioeconomic status"},{"id":"d","text":"It is primarily a result of personal lifestyle choices"}],"answerId":"b","explanation":"Environmental health burden is influenced by modifiable factors, which are part of the broader determinants of health.","kind":"integration","linkedModuleIds":["ich-determinants-of-health"],"origin":"ai"},{"id":"ich-environmental-health-overview~ai-7","moduleId":"ich-environmental-health-overview","stem":"Which of the following interventions is most effective in preventing environmental risks at a population level?","options":[{"id":"a","text":"Individual behavior modification"},{"id":"b","text":"Policy and infrastructure changes"},{"id":"c","text":"Increased healthcare access"},{"id":"d","text":"Genetic screening programs"}],"answerId":"b","explanation":"Effective prevention of environmental risks is achieved through policy and infrastructure changes, not just individual behavior.","kind":"integration","linkedModuleIds":["ich-environmental-risk-prevention"],"origin":"ai"}],"ich-environmental-risk-prevention":[{"id":"ich-environmental-risk-prevention~ai-0","moduleId":"ich-environmental-risk-prevention","stem":"Which step in risk assessment involves determining the relationship between the dose of a substance and the incidence of health effects?","options":[{"id":"a","text":"Hazard identification"},{"id":"b","text":"Dose–response assessment"},{"id":"c","text":"Exposure assessment"},{"id":"d","text":"Risk characterization"}],"answerId":"b","explanation":"Dose–response assessment evaluates how the probability and severity of effects change with different levels of exposure.","kind":"recall","origin":"ai"},{"id":"ich-environmental-risk-prevention~ai-1","moduleId":"ich-environmental-risk-prevention","stem":"What is the most effective point of intervention in the exposure pathway to prevent harm?","options":[{"id":"a","text":"At the receptor"},{"id":"b","text":"At the source"},{"id":"c","text":"During the route"},{"id":"d","text":"In the environmental medium"}],"answerId":"b","explanation":"Controlling the hazard at the source is the most effective and reliable way to prevent exposure.","kind":"mechanism","origin":"ai"},{"id":"ich-environmental-risk-prevention~ai-2","moduleId":"ich-environmental-risk-prevention","stem":"Which of the following statements about carcinogens is typically assumed in risk assessment?","options":[{"id":"a","text":"They have a safe threshold"},{"id":"b","text":"They follow a linear no-threshold model"},{"id":"c","text":"They are harmless at low doses"},{"id":"d","text":"They require a specific medium to cause harm"}],"answerId":"b","explanation":"Carcinogens are usually assessed with a linear no-threshold model, implying any dose carries some risk.","kind":"trap","origin":"ai"},{"id":"ich-environmental-risk-prevention~ai-3","moduleId":"ich-environmental-risk-prevention","stem":"In the context of environmental risk, what does 'breaking the pathway' refer to?","options":[{"id":"a","text":"Eliminating the receptor"},{"id":"b","text":"Stopping the route of exposure"},{"id":"c","text":"Removing the environmental medium"},{"id":"d","text":"Controlling the hazard at the source"}],"answerId":"b","explanation":"Breaking the pathway means interrupting the route of exposure, preventing the receptor from being affected.","kind":"clinical","origin":"ai"},{"id":"ich-environmental-risk-prevention~ai-4","moduleId":"ich-environmental-risk-prevention","stem":"How does climate change act as a threat multiplier in environmental health?","options":[{"id":"a","text":"It reduces the effectiveness of PPE"},{"id":"b","text":"It increases the potency of toxins"},{"id":"c","text":"It exacerbates existing health threats"},{"id":"d","text":"It eliminates certain exposure pathways"}],"answerId":"c","explanation":"Climate change exacerbates existing health threats such as heat illness and vector-borne diseases.","kind":"mechanism","origin":"ai"},{"id":"ich-environmental-risk-prevention~ai-5","moduleId":"ich-environmental-risk-prevention","stem":"Which component of risk assessment is distinct from risk management?","options":[{"id":"a","text":"Hazard identification"},{"id":"b","text":"Risk characterization"},{"id":"c","text":"Exposure assessment"},{"id":"d","text":"Policy decision"}],"answerId":"d","explanation":"Risk management involves policy decisions, separate from the scientific process of risk assessment.","kind":"trap","origin":"ai"},{"id":"ich-environmental-risk-prevention~ai-6","moduleId":"ich-environmental-risk-prevention","stem":"How does the hierarchy of controls apply to environmental risk prevention?","options":[{"id":"a","text":"It prioritizes PPE over source control"},{"id":"b","text":"It emphasizes eliminating hazards at the source"},{"id":"c","text":"It focuses on behavioral changes first"},{"id":"d","text":"It suggests using engineering controls last"}],"answerId":"b","explanation":"The hierarchy of controls prioritizes eliminating or controlling hazards at the source as the most effective intervention.","kind":"integration","linkedModuleIds":["ich-occupational-prevention-controls"],"origin":"ai"},{"id":"ich-environmental-risk-prevention~ai-7","moduleId":"ich-environmental-risk-prevention","stem":"Which module concept is directly applicable when assessing the risk of tobacco exposure?","options":[{"id":"a","text":"Exposure pathway"},{"id":"b","text":"Risk management"},{"id":"c","text":"Dose–response relationship"},{"id":"d","text":"Environmental medium"}],"answerId":"c","explanation":"The dose–response relationship is crucial in assessing the risk of tobacco exposure, linking exposure levels to health outcomes.","kind":"integration","linkedModuleIds":["environmental-chemical-tobacco-injury"],"origin":"ai"}],"ich-economic-evaluation-hta":[{"id":"ich-economic-evaluation-hta~ai-0","moduleId":"ich-economic-evaluation-hta","stem":"Which type of economic evaluation uses QALYs as the outcome measure?","options":[{"id":"a","text":"Cost-Utility Analysis (CUA)"},{"id":"b","text":"Cost-Effectiveness Analysis (CEA)"},{"id":"c","text":"Cost-Minimization Analysis (CMA)"},{"id":"d","text":"Cost-Benefit Analysis (CBA)"}],"answerId":"a","explanation":"CUA uses QALYs to measure outcomes, allowing comparison across different interventions.","kind":"recall","origin":"ai"},{"id":"ich-economic-evaluation-hta~ai-1","moduleId":"ich-economic-evaluation-hta","stem":"What is the primary purpose of calculating the Incremental Cost-Effectiveness Ratio (ICER)?","options":[{"id":"a","text":"To determine the absolute cost of a treatment"},{"id":"b","text":"To compare the cost-effectiveness of two interventions"},{"id":"c","text":"To assess the affordability of a treatment"},{"id":"d","text":"To evaluate the clinical efficacy of a treatment"}],"answerId":"b","explanation":"ICER compares the additional cost per additional unit of outcome between two interventions.","kind":"mechanism","origin":"ai"},{"id":"ich-economic-evaluation-hta~ai-2","moduleId":"ich-economic-evaluation-hta","stem":"A study reports 'cost per QALY gained' for a new drug. What type of economic evaluation is this?","options":[{"id":"a","text":"Cost-Utility Analysis (CUA)"},{"id":"b","text":"Cost-Effectiveness Analysis (CEA)"},{"id":"c","text":"Cost-Minimization Analysis (CMA)"},{"id":"d","text":"Cost-Benefit Analysis (CBA)"}],"answerId":"a","explanation":"Outcomes measured in QALYs indicate a Cost-Utility Analysis.","kind":"trap","origin":"ai"},{"id":"ich-economic-evaluation-hta~ai-3","moduleId":"ich-economic-evaluation-hta","stem":"Which organization in Thailand is responsible for conducting Health Technology Assessments (HTA)?","options":[{"id":"a","text":"HITAP"},{"id":"b","text":"NLEM"},{"id":"c","text":"UCS"},{"id":"d","text":"MoPH"}],"answerId":"a","explanation":"HITAP conducts HTAs to inform coverage decisions in Thailand.","kind":"recall","origin":"ai"},{"id":"ich-economic-evaluation-hta~ai-4","moduleId":"ich-economic-evaluation-hta","stem":"In the context of economic evaluation, what does a cost-effectiveness threshold represent?","options":[{"id":"a","text":"The maximum budget for a health intervention"},{"id":"b","text":"The willingness-to-pay ceiling for an additional unit of outcome"},{"id":"c","text":"The minimum effectiveness required for a treatment"},{"id":"d","text":"The average cost of healthcare in a region"}],"answerId":"b","explanation":"The threshold is the maximum willingness-to-pay for an additional unit of outcome, such as a QALY.","kind":"mechanism","origin":"ai"},{"id":"ich-economic-evaluation-hta~ai-5","moduleId":"ich-economic-evaluation-hta","stem":"How does the Health Intervention and Technology Assessment Program (HITAP) influence the Universal Coverage Scheme (UCS) in Thailand?","options":[{"id":"a","text":"By setting the premium rates for UCS"},{"id":"b","text":"By conducting HTAs to inform the UCS benefit package"},{"id":"c","text":"By managing the financial operations of UCS"},{"id":"d","text":"By directly providing healthcare services"}],"answerId":"b","explanation":"HITAP conducts HTAs, which inform the UCS benefit package decisions.","kind":"integration","linkedModuleIds":["ich-thai-health-system-schemes"],"origin":"ai"},{"id":"ich-economic-evaluation-hta~ai-6","moduleId":"ich-economic-evaluation-hta","stem":"A new genetic therapy is evaluated for cost-effectiveness. Which economic evaluation type would be most appropriate if outcomes are measured in QALYs?","options":[{"id":"a","text":"Cost-Utility Analysis (CUA)"},{"id":"b","text":"Cost-Effectiveness Analysis (CEA)"},{"id":"c","text":"Cost-Minimization Analysis (CMA)"},{"id":"d","text":"Cost-Benefit Analysis (CBA)"}],"answerId":"a","explanation":"CUA is used when outcomes are measured in QALYs, suitable for comparing diverse interventions.","kind":"integration","linkedModuleIds":["add-genetic-engineering-and-crispr-technology"],"origin":"ai"}],"ich-occupational-prevention-controls":[{"id":"ich-occupational-prevention-controls~ai-0","moduleId":"ich-occupational-prevention-controls","stem":"Which control measure is considered the most effective in the hierarchy of controls?","options":[{"id":"a","text":"Elimination"},{"id":"b","text":"Engineering"},{"id":"c","text":"Administrative"},{"id":"d","text":"PPE"}],"answerId":"a","explanation":"Elimination is the most effective because it removes the hazard entirely.","kind":"recall","origin":"ai"},{"id":"ich-occupational-prevention-controls~ai-1","moduleId":"ich-occupational-prevention-controls","stem":"What is the primary reason PPE is considered the least effective control measure?","options":[{"id":"a","text":"It is expensive"},{"id":"b","text":"It requires constant correct use"},{"id":"c","text":"It is uncomfortable"},{"id":"d","text":"It is difficult to obtain"}],"answerId":"b","explanation":"PPE is least effective because it relies on being correctly fitted and worn consistently.","kind":"mechanism","origin":"ai"},{"id":"ich-occupational-prevention-controls~ai-2","moduleId":"ich-occupational-prevention-controls","stem":"A factory replaces a toxic solvent with a non-toxic one. Which level of control does this represent?","options":[{"id":"a","text":"Elimination"},{"id":"b","text":"Substitution"},{"id":"c","text":"Engineering"},{"id":"d","text":"Administrative"}],"answerId":"b","explanation":"Substitution involves replacing a hazardous material with a safer alternative.","kind":"recall","origin":"ai"},{"id":"ich-occupational-prevention-controls~ai-3","moduleId":"ich-occupational-prevention-controls","stem":"Which of the following is an example of an engineering control?","options":[{"id":"a","text":"Job rotation"},{"id":"b","text":"Local exhaust ventilation"},{"id":"c","text":"Training programs"},{"id":"d","text":"Ear plugs"}],"answerId":"b","explanation":"Engineering controls isolate people from hazards, such as using local exhaust ventilation.","kind":"recall","origin":"ai"},{"id":"ich-occupational-prevention-controls~ai-4","moduleId":"ich-occupational-prevention-controls","stem":"A workplace implements a job rotation system to reduce exposure time to a hazard. What type of control is this?","options":[{"id":"a","text":"Elimination"},{"id":"b","text":"Engineering"},{"id":"c","text":"Administrative"},{"id":"d","text":"PPE"}],"answerId":"c","explanation":"Administrative controls change how people work, such as through job rotation.","kind":"recall","origin":"ai"},{"id":"ich-occupational-prevention-controls~ai-5","moduleId":"ich-occupational-prevention-controls","stem":"How does the Occupational Safety, Health and Environment Act B.E. 2554 (2011) impact workplace safety in Thailand?","options":[{"id":"a","text":"It mandates PPE for all workers"},{"id":"b","text":"It requires employers to provide a safe workplace"},{"id":"c","text":"It allows workers to sue employers for injuries"},{"id":"d","text":"It eliminates the need for health surveillance"}],"answerId":"b","explanation":"The Act obliges employers to ensure a safe workplace environment.","kind":"recall","origin":"ai"},{"id":"ich-occupational-prevention-controls~ai-6","moduleId":"ich-occupational-prevention-controls","stem":"In the context of environmental risk prevention, why is elimination preferred over PPE?","options":[{"id":"a","text":"PPE is more expensive"},{"id":"b","text":"Elimination acts at the source"},{"id":"c","text":"PPE is more time-consuming"},{"id":"d","text":"Elimination is easier to implement"}],"answerId":"b","explanation":"Elimination removes the hazard at the source, protecting everyone by design.","kind":"integration","linkedModuleIds":["ich-environmental-risk-prevention"],"origin":"ai"},{"id":"ich-occupational-prevention-controls~ai-7","moduleId":"ich-occupational-prevention-controls","stem":"A sentinel case of occupational asthma prompts a review of workplace controls. Which module does this relate to?","options":[{"id":"a","text":"Environmental Risk & Prevention"},{"id":"b","text":"Occupational Disease & Diagnosis"},{"id":"c","text":"Occupational Hazards"},{"id":"d","text":"Hierarchy of Controls"}],"answerId":"b","explanation":"A sentinel case triggers a review, linking to occupational disease diagnosis.","kind":"integration","linkedModuleIds":["ich-occupational-diseases-diagnosis"],"origin":"ai"}],"ich-health-economics-concepts":[{"id":"ich-health-economics-concepts~ai-0","moduleId":"ich-health-economics-concepts","stem":"What is the true cost of implementing a new health program in economic terms?","options":[{"id":"a","text":"The opportunity cost of the program"},{"id":"b","text":"The total expenditure in baht"},{"id":"c","text":"The administrative costs involved"},{"id":"d","text":"The direct costs of medical supplies"}],"answerId":"a","explanation":"The true cost is the opportunity cost, which is the value of the best alternative forgone.","kind":"recall","origin":"ai"},{"id":"ich-health-economics-concepts~ai-1","moduleId":"ich-health-economics-concepts","stem":"Which of the following is an example of asymmetric information in healthcare?","options":[{"id":"a","text":"Patients choosing their own treatments"},{"id":"b","text":"Doctors knowing more about treatments than patients"},{"id":"c","text":"Patients having full access to their medical records"},{"id":"d","text":"Insurance companies setting fixed premiums"}],"answerId":"b","explanation":"Asymmetric information occurs when the doctor knows more than the patient, potentially leading to supplier-induced demand.","kind":"mechanism","origin":"ai"},{"id":"ich-health-economics-concepts~ai-2","moduleId":"ich-health-economics-concepts","stem":"Why might a technically efficient allocation of health resources still be considered unfair?","options":[{"id":"a","text":"It maximizes output but may not address needs equitably"},{"id":"b","text":"It focuses on cost reduction"},{"id":"c","text":"It ignores the role of public goods"},{"id":"d","text":"It prioritizes preventive care over treatment"}],"answerId":"a","explanation":"Technical efficiency maximizes output but does not consider equity, which involves fair distribution based on need.","kind":"trap","origin":"ai"},{"id":"ich-health-economics-concepts~ai-3","moduleId":"ich-health-economics-concepts","stem":"According to Grossman's model, why do individuals demand healthcare?","options":[{"id":"a","text":"To directly improve their wealth"},{"id":"b","text":"As a means to maintain or improve their health"},{"id":"c","text":"To reduce healthcare costs"},{"id":"d","text":"To fulfill insurance requirements"}],"answerId":"b","explanation":"Healthcare is a derived demand because it is an input into producing the health that individuals ultimately want.","kind":"mechanism","origin":"ai"},{"id":"ich-health-economics-concepts~ai-4","moduleId":"ich-health-economics-concepts","stem":"How does value-based care integrate efficiency and equity in health economics?","options":[{"id":"a","text":"By focusing solely on cost reduction"},{"id":"b","text":"By emphasizing health outcomes per baht spent"},{"id":"c","text":"By prioritizing high-income patients"},{"id":"d","text":"By eliminating all health disparities"}],"answerId":"b","explanation":"Value-based care seeks to optimize health outcomes relative to costs, integrating both efficiency and equity considerations.","kind":"integration","linkedModuleIds":["ich-economic-evaluation-hta"],"origin":"ai"},{"id":"ich-health-economics-concepts~ai-5","moduleId":"ich-health-economics-concepts","stem":"Which concept justifies government intervention in healthcare markets?","options":[{"id":"a","text":"Perfect competition"},{"id":"b","text":"Asymmetric information"},{"id":"c","text":"Unlimited resources"},{"id":"d","text":"Patient autonomy"}],"answerId":"b","explanation":"Asymmetric information is a market failure that justifies government intervention to prevent supplier-induced demand and ensure fair access.","kind":"recall","origin":"ai"},{"id":"ich-health-economics-concepts~ai-6","moduleId":"ich-health-economics-concepts","stem":"How does the concept of opportunity cost relate to health financing decisions?","options":[{"id":"a","text":"It determines the budget allocation for health programs"},{"id":"b","text":"It assesses the financial cost of insurance premiums"},{"id":"c","text":"It evaluates the health benefits forgone by choosing one program over another"},{"id":"d","text":"It calculates the administrative expenses of health services"}],"answerId":"c","explanation":"Opportunity cost in health financing involves evaluating the health benefits forgone when resources are allocated to one program over another.","kind":"integration","linkedModuleIds":["ich-health-financing-uhc"],"origin":"ai"}],"ich-occupational-hazards":[{"id":"ich-occupational-hazards~ai-0","moduleId":"ich-occupational-hazards","stem":"Which of the following is considered a physical occupational hazard?","options":[{"id":"a","text":"Noise"},{"id":"b","text":"Solvents"},{"id":"c","text":"Bacteria"},{"id":"d","text":"Repetitive motion"}],"answerId":"a","explanation":"Noise is a physical hazard, while solvents are chemical, bacteria are biological, and repetitive motion is ergonomic.","kind":"recall","origin":"ai"},{"id":"ich-occupational-hazards~ai-1","moduleId":"ich-occupational-hazards","stem":"What is the primary difference between a hazard and a risk in occupational health?","options":[{"id":"a","text":"Hazard is the likelihood of harm; risk is the potential to harm"},{"id":"b","text":"Hazard is the potential to harm; risk is the likelihood harm occurs given exposure"},{"id":"c","text":"Hazard and risk are interchangeable"},{"id":"d","text":"Hazard is the probability of exposure; risk is the severity of harm"}],"answerId":"b","explanation":"A hazard is the intrinsic potential to cause harm, while risk considers the likelihood and exposure.","kind":"trap","origin":"ai"},{"id":"ich-occupational-hazards~ai-2","moduleId":"ich-occupational-hazards","stem":"A factory worker is exposed to high levels of noise daily. What is the most likely occupational health outcome?","options":[{"id":"a","text":"Carpal tunnel syndrome"},{"id":"b","text":"Noise-induced hearing loss"},{"id":"c","text":"Heat stress"},{"id":"d","text":"Chemical burns"}],"answerId":"b","explanation":"Chronic exposure to high noise levels can lead to noise-induced hearing loss.","kind":"clinical","origin":"ai"},{"id":"ich-occupational-hazards~ai-3","moduleId":"ich-occupational-hazards","stem":"Which of the following best describes an ergonomic hazard?","options":[{"id":"a","text":"Exposure to ionising radiation"},{"id":"b","text":"Handling toxic chemicals"},{"id":"c","text":"Repetitive strain from typing"},{"id":"d","text":"Working night shifts"}],"answerId":"c","explanation":"Ergonomic hazards include repetitive strain injuries from activities like typing.","kind":"recall","origin":"ai"},{"id":"ich-occupational-hazards~ai-4","moduleId":"ich-occupational-hazards","stem":"In the context of occupational hazards, why is a high-hazard agent with no exposure considered low risk?","options":[{"id":"a","text":"Because the hazard is not severe"},{"id":"b","text":"Because risk is only determined by exposure"},{"id":"c","text":"Because without exposure, the probability of harm is negligible"},{"id":"d","text":"Because the hazard is not present in the workplace"}],"answerId":"c","explanation":"Without exposure, the probability of harm is negligible, making the risk low.","kind":"mechanism","origin":"ai"},{"id":"ich-occupational-hazards~ai-5","moduleId":"ich-occupational-hazards","stem":"How do psychosocial factors act as occupational hazards?","options":[{"id":"a","text":"By causing immediate physical injury"},{"id":"b","text":"By altering workplace morale only"},{"id":"c","text":"Through chronic stress physiology and fatigue/error pathways"},{"id":"d","text":"By increasing chemical exposure"}],"answerId":"c","explanation":"Psychosocial factors affect health through chronic stress and fatigue/error pathways.","kind":"mechanism","origin":"ai"},{"id":"ich-occupational-hazards~ai-6","moduleId":"ich-occupational-hazards","stem":"Which of the following is a shared principle between occupational hazards and environmental health?","options":[{"id":"a","text":"Both focus on chemical exposure only"},{"id":"b","text":"Both consider the hierarchy of controls for risk management"},{"id":"c","text":"Both are concerned only with physical hazards"},{"id":"d","text":"Both ignore psychosocial factors"}],"answerId":"b","explanation":"Both occupational hazards and environmental health use the hierarchy of controls to manage risks.","kind":"integration","linkedModuleIds":["ich-environmental-health-overview"],"origin":"ai"},{"id":"ich-occupational-hazards~ai-7","moduleId":"ich-occupational-hazards","stem":"Which occupational hazard class is most likely to contribute to work-related musculoskeletal disorders (WMSDs)?","options":[{"id":"a","text":"Chemical"},{"id":"b","text":"Biological"},{"id":"c","text":"Ergonomic"},{"id":"d","text":"Psychosocial"}],"answerId":"c","explanation":"Ergonomic hazards, such as repetitive motion and awkward posture, are primary contributors to WMSDs.","kind":"recall","origin":"ai"},{"id":"ich-occupational-hazards~ai-8","moduleId":"ich-occupational-hazards","stem":"How does the concept of 'Risk = Hazard × Exposure' apply to the management of occupational diseases?","options":[{"id":"a","text":"It emphasizes the need to eliminate all hazards"},{"id":"b","text":"It highlights the importance of exposure control to reduce risk"},{"id":"c","text":"It suggests that risk is independent of exposure"},{"id":"d","text":"It implies that all hazards have the same risk level"}],"answerId":"b","explanation":"Managing exposure is crucial to reducing risk, as risk is a function of both hazard and exposure.","kind":"integration","linkedModuleIds":["ich-occupational-diseases-diagnosis"],"origin":"ai"}],"ich-descriptive-epi-surveillance":[{"id":"ich-descriptive-epi-surveillance~ai-0","moduleId":"ich-descriptive-epi-surveillance","stem":"Which of the following best describes the primary purpose of descriptive epidemiology?","options":[{"id":"a","text":"To generate hypotheses"},{"id":"b","text":"To test hypotheses"},{"id":"c","text":"To implement interventions"},{"id":"d","text":"To confirm diagnoses"}],"answerId":"a","explanation":"Descriptive epidemiology organizes data by person, place, and time to generate hypotheses.","kind":"recall","origin":"ai"},{"id":"ich-descriptive-epi-surveillance~ai-1","moduleId":"ich-descriptive-epi-surveillance","stem":"What is the main difference between passive and active surveillance systems?","options":[{"id":"a","text":"Passive is more complete than active"},{"id":"b","text":"Active is cheaper than passive"},{"id":"c","text":"Passive relies on routine reporting by providers"},{"id":"d","text":"Active relies on providers to report cases"}],"answerId":"c","explanation":"Passive surveillance relies on routine reporting by providers, while active involves health authorities actively seeking cases.","kind":"trap","origin":"ai"},{"id":"ich-descriptive-epi-surveillance~ai-2","moduleId":"ich-descriptive-epi-surveillance","stem":"A sudden increase in reported cases of a disease may represent what in a surveillance system?","options":[{"id":"a","text":"A true outbreak"},{"id":"b","text":"An artefact of better reporting"},{"id":"c","text":"A seasonal trend"},{"id":"d","text":"A change in case definition"}],"answerId":"a","explanation":"A sudden increase can indicate a true outbreak or an artefact of better reporting.","kind":"clinical","origin":"ai"},{"id":"ich-descriptive-epi-surveillance~ai-3","moduleId":"ich-descriptive-epi-surveillance","stem":"Which of the following is a characteristic of a good surveillance system?","options":[{"id":"a","text":"Complex and detailed"},{"id":"b","text":"Timely and sensitive"},{"id":"c","text":"Expensive and comprehensive"},{"id":"d","text":"Slow and representative"}],"answerId":"b","explanation":"Good surveillance systems are simple, timely, sensitive, and representative.","kind":"mechanism","origin":"ai"},{"id":"ich-descriptive-epi-surveillance~ai-4","moduleId":"ich-descriptive-epi-surveillance","stem":"In the context of surveillance, what does the term 'signal' refer to?","options":[{"id":"a","text":"A new disease"},{"id":"b","text":"A rise above the expected baseline"},{"id":"c","text":"A false positive"},{"id":"d","text":"A decrease in disease incidence"}],"answerId":"b","explanation":"A signal is a rise above the expected or endemic baseline in surveillance data.","kind":"recall","origin":"ai"},{"id":"ich-descriptive-epi-surveillance~ai-5","moduleId":"ich-descriptive-epi-surveillance","stem":"How does descriptive epidemiology relate to study designs in outbreak investigations?","options":[{"id":"a","text":"It tests hypotheses generated by study designs"},{"id":"b","text":"It provides data for hypothesis generation"},{"id":"c","text":"It confirms the findings of study designs"},{"id":"d","text":"It replaces the need for study designs"}],"answerId":"b","explanation":"Descriptive epidemiology provides data that generates hypotheses, which are then tested by study designs.","kind":"integration","linkedModuleIds":["ich-epi-study-designs"],"origin":"ai"},{"id":"ich-descriptive-epi-surveillance~ai-6","moduleId":"ich-descriptive-epi-surveillance","stem":"Which of the following data types is most relevant to descriptive epidemiology?","options":[{"id":"a","text":"Nominal data"},{"id":"b","text":"Ordinal data"},{"id":"c","text":"Interval data"},{"id":"d","text":"Ratio data"}],"answerId":"a","explanation":"Nominal data, such as categories of person, place, and time, is crucial for organizing descriptive epidemiology data.","kind":"integration","linkedModuleIds":["data-types-descriptive-stats"],"origin":"ai"}],"ich-disease-occurrence-concepts":[{"id":"ich-disease-occurrence-concepts~ai-0","moduleId":"ich-disease-occurrence-concepts","stem":"Which stage of the natural history of disease is targeted by secondary prevention?","options":[{"id":"a","text":"Susceptibility"},{"id":"b","text":"Subclinical"},{"id":"c","text":"Clinical"},{"id":"d","text":"Outcome"}],"answerId":"b","explanation":"Secondary prevention aims to detect and treat diseases in their subclinical phase before symptoms appear.","kind":"recall","origin":"ai"},{"id":"ich-disease-occurrence-concepts~ai-1","moduleId":"ich-disease-occurrence-concepts","stem":"In the epidemiologic triad, which factor is NOT a component?","options":[{"id":"a","text":"Agent"},{"id":"b","text":"Host"},{"id":"c","text":"Environment"},{"id":"d","text":"Vector"}],"answerId":"d","explanation":"The epidemiologic triad consists of the agent, host, and environment; vectors are part of the environment.","kind":"recall","origin":"ai"},{"id":"ich-disease-occurrence-concepts~ai-2","moduleId":"ich-disease-occurrence-concepts","stem":"A sudden increase in measles cases in a community with a previously stable low incidence is best described as:","options":[{"id":"a","text":"Endemic"},{"id":"b","text":"Epidemic"},{"id":"c","text":"Pandemic"},{"id":"d","text":"Sporadic"}],"answerId":"b","explanation":"An epidemic is characterized by a sudden increase in cases above the expected level for a given area.","kind":"trap","origin":"ai"},{"id":"ich-disease-occurrence-concepts~ai-3","moduleId":"ich-disease-occurrence-concepts","stem":"What is the herd immunity threshold for a disease with an R₀ of 10?","options":[{"id":"a","text":"0.1"},{"id":"b","text":"0.5"},{"id":"c","text":"0.9"},{"id":"d","text":"0.95"}],"answerId":"c","explanation":"The herd immunity threshold is calculated as 1 - 1/R₀, which equals 0.9 for an R₀ of 10.","kind":"mechanism","origin":"ai"},{"id":"ich-disease-occurrence-concepts~ai-4","moduleId":"ich-disease-occurrence-concepts","stem":"Which level of prevention is exemplified by vaccination programs?","options":[{"id":"a","text":"Primordial"},{"id":"b","text":"Primary"},{"id":"c","text":"Secondary"},{"id":"d","text":"Tertiary"}],"answerId":"b","explanation":"Vaccination is a primary prevention strategy aimed at preventing the onset of disease.","kind":"recall","origin":"ai"},{"id":"ich-disease-occurrence-concepts~ai-5","moduleId":"ich-disease-occurrence-concepts","stem":"In the context of Hepatitis B, which prevention level is most relevant during the subclinical phase?","options":[{"id":"a","text":"Primordial"},{"id":"b","text":"Primary"},{"id":"c","text":"Secondary"},{"id":"d","text":"Tertiary"}],"answerId":"c","explanation":"Secondary prevention, such as screening, is crucial during the subclinical phase to detect and manage Hepatitis B early.","kind":"integration","linkedModuleIds":["add-hepatitis-b-virus-infection-natural-history-and-serology"],"origin":"ai"},{"id":"ich-disease-occurrence-concepts~ai-6","moduleId":"ich-disease-occurrence-concepts","stem":"How does the concept of herd immunity apply to the control of infectious diseases?","options":[{"id":"a","text":"It eliminates the need for individual vaccination"},{"id":"b","text":"It reduces the transmission rate"},{"id":"c","text":"It increases the R₀ value"},{"id":"d","text":"It is only effective for non-communicable diseases"}],"answerId":"b","explanation":"Herd immunity reduces the transmission rate by breaking chains of infection, indirectly protecting susceptible individuals.","kind":"mechanism","origin":"ai"},{"id":"ich-disease-occurrence-concepts~ai-7","moduleId":"ich-disease-occurrence-concepts","stem":"Which measure is most appropriate for evaluating the impact of a new antipsychotic agent on disease occurrence?","options":[{"id":"a","text":"Incidence rate"},{"id":"b","text":"Prevalence rate"},{"id":"c","text":"Case fatality rate"},{"id":"d","text":"Herd immunity threshold"}],"answerId":"a","explanation":"Incidence rate measures the occurrence of new cases and is suitable for evaluating the impact of interventions.","kind":"integration","linkedModuleIds":["atypical-antipsychotic-agents"],"origin":"ai"}],"ich-epi-study-designs":[{"id":"ich-epi-study-designs~ai-0","moduleId":"ich-epi-study-designs","stem":"Which study design is most appropriate for investigating a rare disease?","options":[{"id":"a","text":"Cohort study"},{"id":"b","text":"Case-control study"},{"id":"c","text":"Cross-sectional study"},{"id":"d","text":"Ecological study"}],"answerId":"b","explanation":"A case-control study is efficient for rare diseases as it starts with cases and looks back at exposures.","kind":"trap","origin":"ai"},{"id":"ich-epi-study-designs~ai-1","moduleId":"ich-epi-study-designs","stem":"In an outbreak investigation, what is the first step after verifying the outbreak?","options":[{"id":"a","text":"Set a case definition"},{"id":"b","text":"Find and count cases"},{"id":"c","text":"Describe the epidemic curve"},{"id":"d","text":"Implement control measures"}],"answerId":"a","explanation":"After verifying the outbreak, the next step is to set a case definition to identify cases consistently.","kind":"recall","origin":"ai"},{"id":"ich-epi-study-designs~ai-2","moduleId":"ich-epi-study-designs","stem":"What measure is used to compare the risk of disease in exposed vs. unexposed groups in a cohort study?","options":[{"id":"a","text":"Odds ratio"},{"id":"b","text":"Relative risk"},{"id":"c","text":"Prevalence ratio"},{"id":"d","text":"Incidence rate"}],"answerId":"b","explanation":"Cohort studies calculate relative risk to compare the incidence of disease in exposed versus unexposed groups.","kind":"mechanism","origin":"ai"},{"id":"ich-epi-study-designs~ai-3","moduleId":"ich-epi-study-designs","stem":"Which characteristic of an epidemic curve suggests a point source outbreak?","options":[{"id":"a","text":"Multiple peaks"},{"id":"b","text":"Single sharp peak"},{"id":"c","text":"Continuous rise"},{"id":"d","text":"Irregular pattern"}],"answerId":"b","explanation":"A single sharp peak in an epidemic curve indicates a point source outbreak, where exposure occurs at one point in time.","kind":"clinical","origin":"ai"},{"id":"ich-epi-study-designs~ai-4","moduleId":"ich-epi-study-designs","stem":"During an outbreak, a food-specific attack rate is calculated. What does a high attack rate for a particular food suggest?","options":[{"id":"a","text":"The food is not related to the outbreak"},{"id":"b","text":"The food is a potential vehicle of the outbreak"},{"id":"c","text":"The food has no association with the outbreak"},{"id":"d","text":"The food is consumed by a small population"}],"answerId":"b","explanation":"A high attack rate for a specific food suggests it may be the vehicle of the outbreak.","kind":"mechanism","origin":"ai"},{"id":"ich-epi-study-designs~ai-5","moduleId":"ich-epi-study-designs","stem":"Which study design is best for determining the prevalence of a health outcome in a population?","options":[{"id":"a","text":"Cohort study"},{"id":"b","text":"Case-control study"},{"id":"c","text":"Cross-sectional study"},{"id":"d","text":"Randomized controlled trial"}],"answerId":"c","explanation":"Cross-sectional studies measure both exposure and outcome at one point in time, making them ideal for determining prevalence.","kind":"recall","origin":"ai"},{"id":"ich-epi-study-designs~ai-6","moduleId":"ich-epi-study-designs","stem":"How does the shape of an epidemic curve assist in identifying the type of outbreak?","options":[{"id":"a","text":"It shows the number of cases over time"},{"id":"b","text":"It reveals the source of the outbreak"},{"id":"c","text":"It indicates the severity of the outbreak"},{"id":"d","text":"It determines the duration of the outbreak"}],"answerId":"b","explanation":"The shape of an epidemic curve can distinguish between point source and propagated outbreaks.","kind":"clinical","origin":"ai"},{"id":"ich-epi-study-designs~ai-7","moduleId":"ich-epi-study-designs","stem":"Which step in outbreak investigation involves forming hypotheses about the source and spread of the disease?","options":[{"id":"a","text":"Verify the outbreak"},{"id":"b","text":"Describe the epidemic curve"},{"id":"c","text":"Test hypotheses with an analytic study"},{"id":"d","text":"Implement control measures"}],"answerId":"c","explanation":"After describing the epidemic curve, hypotheses are formed and tested with an analytic study.","kind":"recall","origin":"ai"},{"id":"ich-epi-study-designs~ai-8","moduleId":"ich-epi-study-designs","stem":"In an outbreak investigation, what is the purpose of maintaining surveillance after implementing control measures?","options":[{"id":"a","text":"To verify the outbreak"},{"id":"b","text":"To ensure the outbreak has been controlled"},{"id":"c","text":"To describe the epidemic curve"},{"id":"d","text":"To find and count cases"}],"answerId":"b","explanation":"Maintaining surveillance ensures that control measures are effective and the outbreak is under control.","kind":"integration","linkedModuleIds":["outbreak-investigation"],"origin":"ai"}],"ich-epi-intro-uses":[{"id":"ich-epi-intro-uses~ai-0","moduleId":"ich-epi-intro-uses","stem":"Which of the following is a primary use of epidemiology?","options":[{"id":"a","text":"Community diagnosis"},{"id":"b","text":"Individual patient treatment"},{"id":"c","text":"Genetic counseling"},{"id":"d","text":"Pharmacological research"}],"answerId":"a","explanation":"Epidemiology is used for community diagnosis to measure health status and identify health problems.","kind":"recall","origin":"ai"},{"id":"ich-epi-intro-uses~ai-1","moduleId":"ich-epi-intro-uses","stem":"What is the first step in the epidemiologic approach?","options":[{"id":"a","text":"Compare groups"},{"id":"b","text":"Define population"},{"id":"c","text":"Count cases"},{"id":"d","text":"Act on findings"}],"answerId":"c","explanation":"The epidemiologic approach begins with counting cases to understand the extent of a health issue.","kind":"mechanism","origin":"ai"},{"id":"ich-epi-intro-uses~ai-2","moduleId":"ich-epi-intro-uses","stem":"In epidemiology, why is a denominator essential when calculating disease rates?","options":[{"id":"a","text":"To adjust for age differences"},{"id":"b","text":"To provide a reference for comparison"},{"id":"c","text":"To determine the severity of symptoms"},{"id":"d","text":"To identify genetic predispositions"}],"answerId":"b","explanation":"A denominator provides the population at risk, allowing for meaningful comparisons of disease rates.","kind":"mechanism","origin":"ai"},{"id":"ich-epi-intro-uses~ai-3","moduleId":"ich-epi-intro-uses","stem":"A city reports 100 cases of a disease. Another city reports 50 cases. What must be considered before concluding which city has a higher disease risk?","options":[{"id":"a","text":"The number of hospitals"},{"id":"b","text":"The population size of each city"},{"id":"c","text":"The average income of residents"},{"id":"d","text":"The climate of each city"}],"answerId":"b","explanation":"Without knowing the population size, raw case counts cannot determine risk; rates are needed.","kind":"trap","origin":"ai"},{"id":"ich-epi-intro-uses~ai-4","moduleId":"ich-epi-intro-uses","stem":"Which of the following best describes the role of descriptive epidemiology?","options":[{"id":"a","text":"Testing hypotheses"},{"id":"b","text":"Generating hypotheses"},{"id":"c","text":"Proving causation"},{"id":"d","text":"Providing treatment"}],"answerId":"b","explanation":"Descriptive epidemiology is used to generate hypotheses by describing the distribution of diseases.","kind":"recall","origin":"ai"},{"id":"ich-epi-intro-uses~ai-5","moduleId":"ich-epi-intro-uses","stem":"How does the concept of 'disease does not occur at random' guide epidemiological studies?","options":[{"id":"a","text":"It suggests genetic factors are irrelevant"},{"id":"b","text":"It implies diseases are equally distributed"},{"id":"c","text":"It indicates patterns can reveal causes"},{"id":"d","text":"It means individual behavior is the sole cause"}],"answerId":"c","explanation":"Recognizing that disease is not random helps identify patterns that point to underlying determinants.","kind":"mechanism","origin":"ai"},{"id":"ich-epi-intro-uses~ai-6","moduleId":"ich-epi-intro-uses","stem":"Which of the following is an example of applying epidemiology to control health problems?","options":[{"id":"a","text":"Developing new surgical techniques"},{"id":"b","text":"Implementing vaccination programs"},{"id":"c","text":"Conducting animal research"},{"id":"d","text":"Designing new medications"}],"answerId":"b","explanation":"Epidemiology applies its findings to control health problems through interventions like vaccination programs.","kind":"recall","origin":"ai"},{"id":"ich-epi-intro-uses~ai-7","moduleId":"ich-epi-intro-uses","stem":"How does understanding the distribution of adrenergic antagonist usage in a population help in epidemiology?","options":[{"id":"a","text":"It identifies individual patient preferences"},{"id":"b","text":"It helps in planning healthcare resources"},{"id":"c","text":"It determines the effectiveness of a single drug"},{"id":"d","text":"It reveals the genetic predisposition to hypertension"}],"answerId":"b","explanation":"Understanding drug usage patterns helps in planning healthcare resources and assessing population needs.","kind":"integration","linkedModuleIds":["adrenergic-antagonists-blockers"],"origin":"ai"},{"id":"ich-epi-intro-uses~ai-8","moduleId":"ich-epi-intro-uses","stem":"What is the relationship between descriptive epidemiology and the study of opioid toxicity?","options":[{"id":"a","text":"Descriptive epidemiology tests treatment efficacy"},{"id":"b","text":"It identifies individual cases of overdose"},{"id":"c","text":"It helps in identifying patterns of opioid misuse"},{"id":"d","text":"It provides genetic data for opioid response"}],"answerId":"c","explanation":"Descriptive epidemiology identifies patterns of opioid misuse, which can inform public health interventions.","kind":"integration","linkedModuleIds":["opioid-effects-toxicity"],"origin":"ai"}],"ich-ebm-critical-appraisal":[{"id":"ich-ebm-critical-appraisal~ai-0","moduleId":"ich-ebm-critical-appraisal","stem":"Which study design is typically considered the highest level of evidence for therapy?","options":[{"id":"a","text":"Systematic review of RCTs"},{"id":"b","text":"Cohort study"},{"id":"c","text":"Case-control study"},{"id":"d","text":"Expert opinion"}],"answerId":"a","explanation":"Systematic reviews of RCTs are at the top of the evidence hierarchy for therapy.","kind":"recall","origin":"ai"},{"id":"ich-ebm-critical-appraisal~ai-1","moduleId":"ich-ebm-critical-appraisal","stem":"In critical appraisal, what is the first aspect to assess in a study?","options":[{"id":"a","text":"Importance"},{"id":"b","text":"Applicability"},{"id":"c","text":"Validity"},{"id":"d","text":"Generalizability"}],"answerId":"c","explanation":"Validity is assessed first to ensure the results are true and free of bias.","kind":"recall","origin":"ai"},{"id":"ich-ebm-critical-appraisal~ai-2","moduleId":"ich-ebm-critical-appraisal","stem":"A study claims a large effect size but lacks randomization. What should be questioned first?","options":[{"id":"a","text":"Effect size"},{"id":"b","text":"Validity"},{"id":"c","text":"Applicability"},{"id":"d","text":"Publication bias"}],"answerId":"b","explanation":"Without randomization, the study's validity is questionable, affecting the trustworthiness of the effect size.","kind":"mechanism","origin":"ai"},{"id":"ich-ebm-critical-appraisal~ai-3","moduleId":"ich-ebm-critical-appraisal","stem":"Which bias is controlled by randomization in clinical trials?","options":[{"id":"a","text":"Selection bias"},{"id":"b","text":"Information bias"},{"id":"c","text":"Confounding"},{"id":"d","text":"Publication bias"}],"answerId":"c","explanation":"Randomization balances known and unknown confounders across study arms.","kind":"mechanism","origin":"ai"},{"id":"ich-ebm-critical-appraisal~ai-4","moduleId":"ich-ebm-critical-appraisal","stem":"A poorly conducted RCT is compared to a well-conducted cohort study. Which provides more reliable evidence?","options":[{"id":"a","text":"The RCT, due to its design"},{"id":"b","text":"The cohort study, due to its quality"},{"id":"c","text":"Both are equally reliable"},{"id":"d","text":"Neither is reliable"}],"answerId":"b","explanation":"Study quality can override design level; a well-conducted cohort study can be more reliable than a flawed RCT.","kind":"trap","origin":"ai"},{"id":"ich-ebm-critical-appraisal~ai-5","moduleId":"ich-ebm-critical-appraisal","stem":"How does GRADE differentiate between evidence certainty and recommendation strength?","options":[{"id":"a","text":"It does not differentiate"},{"id":"b","text":"Certainty is based on study design only"},{"id":"c","text":"Recommendation strength can be strong even with low-certainty evidence"},{"id":"d","text":"High-certainty evidence always leads to strong recommendations"}],"answerId":"c","explanation":"GRADE allows for strong recommendations even with low-certainty evidence, separating evidence certainty from recommendation strength.","kind":"mechanism","origin":"ai"},{"id":"ich-ebm-critical-appraisal~ai-6","moduleId":"ich-ebm-critical-appraisal","stem":"When applying evidence to a patient, which factor is crucial after assessing validity?","options":[{"id":"a","text":"Study design"},{"id":"b","text":"Effect size"},{"id":"c","text":"Applicability"},{"id":"d","text":"Sample size"}],"answerId":"c","explanation":"Applicability is crucial to determine if the evidence fits the patient and setting.","kind":"integration","linkedModuleIds":["ich-ebm-applying-evidence"],"origin":"ai"},{"id":"ich-ebm-critical-appraisal~ai-7","moduleId":"ich-ebm-critical-appraisal","stem":"Which study design is best suited for investigating the cause of an outbreak?","options":[{"id":"a","text":"Case series"},{"id":"b","text":"Cohort study"},{"id":"c","text":"Case-control study"},{"id":"d","text":"Randomized controlled trial"}],"answerId":"c","explanation":"Case-control studies are often used to investigate outbreaks by comparing exposures in affected vs. unaffected groups.","kind":"integration","linkedModuleIds":["ich-epi-study-designs"],"origin":"ai"}],"ich-measures-of-association":[{"id":"ich-measures-of-association~ai-0","moduleId":"ich-measures-of-association","stem":"Which measure of association is appropriate for a cohort study?","options":[{"id":"a","text":"Relative Risk"},{"id":"b","text":"Odds Ratio"},{"id":"c","text":"Attributable Risk"},{"id":"d","text":"Population Attributable Risk"}],"answerId":"a","explanation":"Cohort studies provide incidence data, allowing calculation of Relative Risk.","kind":"recall","origin":"ai"},{"id":"ich-measures-of-association~ai-1","moduleId":"ich-measures-of-association","stem":"In a case-control study, the odds ratio is calculated as 2.5. What does this imply about the exposure?","options":[{"id":"a","text":"The exposure is a risk factor"},{"id":"b","text":"The exposure is protective"},{"id":"c","text":"There is no association"},{"id":"d","text":"The exposure is common"}],"answerId":"a","explanation":"An odds ratio greater than 1 indicates that the exposure is a risk factor.","kind":"mechanism","origin":"ai"},{"id":"ich-measures-of-association~ai-2","moduleId":"ich-measures-of-association","stem":"A researcher mistakenly calculates a relative risk from a case-control study. What is the correct measure to use?","options":[{"id":"a","text":"Relative Risk"},{"id":"b","text":"Odds Ratio"},{"id":"c","text":"Attributable Risk"},{"id":"d","text":"Hazard Ratio"}],"answerId":"b","explanation":"Case-control studies do not provide incidence data, so odds ratio is the correct measure.","kind":"trap","origin":"ai"},{"id":"ich-measures-of-association~ai-3","moduleId":"ich-measures-of-association","stem":"Which statement is true regarding the population attributable risk (PAR)?","options":[{"id":"a","text":"PAR is independent of exposure prevalence"},{"id":"b","text":"PAR is a measure of association strength"},{"id":"c","text":"PAR depends on the prevalence of the exposure"},{"id":"d","text":"PAR is only applicable in case-control studies"}],"answerId":"c","explanation":"PAR depends on how common the exposure is in the population.","kind":"mechanism","origin":"ai"},{"id":"ich-measures-of-association~ai-4","moduleId":"ich-measures-of-association","stem":"If a disease is rare, how does the odds ratio compare to the relative risk?","options":[{"id":"a","text":"OR is much larger than RR"},{"id":"b","text":"OR approximates RR"},{"id":"c","text":"OR is much smaller than RR"},{"id":"d","text":"OR is unrelated to RR"}],"answerId":"b","explanation":"When the disease is rare, the odds ratio approximates the relative risk.","kind":"mechanism","origin":"ai"},{"id":"ich-measures-of-association~ai-5","moduleId":"ich-measures-of-association","stem":"In the context of public health, why might a weak relative risk on a common exposure be significant?","options":[{"id":"a","text":"It indicates a strong causal relationship"},{"id":"b","text":"It has a high population attributable risk"},{"id":"c","text":"It suggests the exposure is rare"},{"id":"d","text":"It is not significant"}],"answerId":"b","explanation":"A common exposure with even a weak RR can lead to a significant PAR, impacting public health.","kind":"clinical","origin":"ai"},{"id":"ich-measures-of-association~ai-6","moduleId":"ich-measures-of-association","stem":"How does the concept of population attributable risk (PAR) integrate with the principles of evidence-based medicine?","options":[{"id":"a","text":"PAR is irrelevant to evidence-based medicine"},{"id":"b","text":"PAR helps quantify the impact of interventions"},{"id":"c","text":"PAR contradicts evidence-based principles"},{"id":"d","text":"PAR is only used in theoretical models"}],"answerId":"b","explanation":"PAR quantifies the potential impact of removing an exposure, aligning with evidence-based decision-making.","kind":"integration","linkedModuleIds":["ich-ebm-applying-evidence"],"origin":"ai"},{"id":"ich-measures-of-association~ai-7","moduleId":"ich-measures-of-association","stem":"How does understanding measures of association enhance critical appraisal skills in epidemiological studies?","options":[{"id":"a","text":"It allows for subjective interpretation of data"},{"id":"b","text":"It provides a framework for assessing causality"},{"id":"c","text":"It simplifies complex data sets"},{"id":"d","text":"It eliminates the need for statistical analysis"}],"answerId":"b","explanation":"Measures of association help assess the strength and impact of relationships, crucial for critical appraisal.","kind":"integration","linkedModuleIds":["ich-ebm-critical-appraisal"],"origin":"ai"}],"ich-ebm-applying-evidence":[{"id":"ich-ebm-applying-evidence~ai-0","moduleId":"ich-ebm-applying-evidence","stem":"A study reports a 30% relative risk reduction in heart attacks with a new medication. The baseline risk of heart attacks in the population is 10%. What is the absolute risk reduction?","options":[{"id":"a","text":"3%"},{"id":"b","text":"7%"},{"id":"c","text":"10%"},{"id":"d","text":"30%"}],"answerId":"a","explanation":"Absolute Risk Reduction (ARR) is calculated as the baseline risk multiplied by the relative risk reduction: 10% * 30% = 3%.","kind":"recall","origin":"ai"},{"id":"ich-ebm-applying-evidence~ai-1","moduleId":"ich-ebm-applying-evidence","stem":"Which of the following best describes the concept of Number Needed to Treat (NNT)?","options":[{"id":"a","text":"The number of patients needed to treat to achieve a relative risk reduction"},{"id":"b","text":"The number of patients needed to treat to prevent one additional adverse event"},{"id":"c","text":"The number of patients needed to treat to prevent one additional beneficial outcome"},{"id":"d","text":"The number of patients needed to treat to achieve a 50% risk reduction"}],"answerId":"c","explanation":"NNT is the number of patients who need to be treated to prevent one additional adverse event, calculated as 1/ARR.","kind":"recall","origin":"ai"},{"id":"ich-ebm-applying-evidence~ai-2","moduleId":"ich-ebm-applying-evidence","stem":"In a clinical trial, a drug reduces the risk of stroke by 20% relative to placebo. If the baseline risk of stroke is 5%, what is the NNT?","options":[{"id":"a","text":"10"},{"id":"b","text":"20"},{"id":"c","text":"25"},{"id":"d","text":"50"}],"answerId":"b","explanation":"ARR is 1% (5% * 20%), so NNT = 1/0.01 = 100.","kind":"mechanism","origin":"ai"},{"id":"ich-ebm-applying-evidence~ai-3","moduleId":"ich-ebm-applying-evidence","stem":"A patient is concerned about the potential side effects of a new medication. Which of the following should be considered in shared decision-making?","options":[{"id":"a","text":"Only the relative risk reduction"},{"id":"b","text":"Only the absolute risk reduction"},{"id":"c","text":"Both NNT and NNH"},{"id":"d","text":"Only the patient's values"}],"answerId":"c","explanation":"Shared decision-making involves considering both the benefits (NNT) and harms (NNH) alongside patient values.","kind":"clinical","origin":"ai"},{"id":"ich-ebm-applying-evidence~ai-4","moduleId":"ich-ebm-applying-evidence","stem":"A treatment shows a 50% relative risk reduction in a disease with a 1% baseline risk. What is the NNT?","options":[{"id":"a","text":"2"},{"id":"b","text":"10"},{"id":"c","text":"50"},{"id":"d","text":"100"}],"answerId":"d","explanation":"ARR is 0.5% (1% * 50%), so NNT = 1/0.005 = 200.","kind":"trap","origin":"ai"},{"id":"ich-ebm-applying-evidence~ai-5","moduleId":"ich-ebm-applying-evidence","stem":"How does the baseline risk of a disease affect the Number Needed to Treat (NNT) when the relative risk reduction is constant?","options":[{"id":"a","text":"NNT decreases with higher baseline risk"},{"id":"b","text":"NNT increases with higher baseline risk"},{"id":"c","text":"NNT remains constant regardless of baseline risk"},{"id":"d","text":"NNT is unrelated to baseline risk"}],"answerId":"a","explanation":"A higher baseline risk results in a greater absolute risk reduction, thus decreasing the NNT.","kind":"mechanism","origin":"ai"},{"id":"ich-ebm-applying-evidence~ai-6","moduleId":"ich-ebm-applying-evidence","stem":"When applying evidence to a patient, which step involves integrating clinical expertise and patient values with the evidence?","options":[{"id":"a","text":"Critical appraisal"},{"id":"b","text":"Shared decision-making"},{"id":"c","text":"Calculating NNT"},{"id":"d","text":"Assessing relative risk"}],"answerId":"b","explanation":"Shared decision-making integrates clinical expertise, evidence, and patient values to guide treatment decisions.","kind":"integration","linkedModuleIds":["ich-ebm-five-steps"],"origin":"ai"},{"id":"ich-ebm-applying-evidence~ai-7","moduleId":"ich-ebm-applying-evidence","stem":"Which measure of association provides the most direct information about the impact of a treatment on a patient's risk?","options":[{"id":"a","text":"Relative Risk Reduction"},{"id":"b","text":"Absolute Risk Reduction"},{"id":"c","text":"Odds Ratio"},{"id":"d","text":"Hazard Ratio"}],"answerId":"b","explanation":"Absolute Risk Reduction directly reflects the change in risk attributable to the treatment, unlike relative measures.","kind":"integration","linkedModuleIds":["ich-measures-of-association"],"origin":"ai"}],"ich-mortality-morbidity-measures":[{"id":"ich-mortality-morbidity-measures~ai-0","moduleId":"ich-mortality-morbidity-measures","stem":"Which measure is most appropriate for evaluating the severity of a disease among diagnosed patients?","options":[{"id":"a","text":"Case-fatality rate"},{"id":"b","text":"Crude death rate"},{"id":"c","text":"Incidence rate"},{"id":"d","text":"Prevalence"}],"answerId":"a","explanation":"Case-fatality rate measures the severity of a disease by calculating the proportion of deaths among diagnosed cases.","kind":"recall","origin":"ai"},{"id":"ich-mortality-morbidity-measures~ai-1","moduleId":"ich-mortality-morbidity-measures","stem":"A country with a high crude death rate is compared to another with a lower rate. What is a likely explanation for this difference?","options":[{"id":"a","text":"Higher birth rate"},{"id":"b","text":"Older population structure"},{"id":"c","text":"More infectious diseases"},{"id":"d","text":"Better healthcare system"}],"answerId":"b","explanation":"An older population structure can increase the crude death rate due to more deaths regardless of the actual risk.","kind":"mechanism","origin":"ai"},{"id":"ich-mortality-morbidity-measures~ai-2","moduleId":"ich-mortality-morbidity-measures","stem":"What is the primary reason for using age-standardized rates in mortality comparisons between countries?","options":[{"id":"a","text":"To account for different healthcare systems"},{"id":"b","text":"To adjust for population size"},{"id":"c","text":"To correct for age structure differences"},{"id":"d","text":"To include only infectious diseases"}],"answerId":"c","explanation":"Age-standardized rates adjust for differences in age structure, allowing for fair comparisons of mortality between countries.","kind":"recall","origin":"ai"},{"id":"ich-mortality-morbidity-measures~ai-3","moduleId":"ich-mortality-morbidity-measures","stem":"In a steady-state population, if the incidence of a chronic disease remains constant but the duration of the disease increases, what happens to the prevalence?","options":[{"id":"a","text":"Prevalence decreases"},{"id":"b","text":"Prevalence remains constant"},{"id":"c","text":"Prevalence increases"},{"id":"d","text":"Prevalence equals incidence"}],"answerId":"c","explanation":"Prevalence increases because it is approximately equal to incidence multiplied by duration (P ≈ I × D).","kind":"mechanism","origin":"ai"},{"id":"ich-mortality-morbidity-measures~ai-4","moduleId":"ich-mortality-morbidity-measures","stem":"Which measure would you use to assess the resource needs for managing a chronic disease in a community?","options":[{"id":"a","text":"Incidence rate"},{"id":"b","text":"Prevalence"},{"id":"c","text":"Case-fatality rate"},{"id":"d","text":"Crude death rate"}],"answerId":"b","explanation":"Prevalence provides a snapshot of the disease burden, useful for planning and resource allocation.","kind":"clinical","origin":"ai"},{"id":"ich-mortality-morbidity-measures~ai-5","moduleId":"ich-mortality-morbidity-measures","stem":"A rare disease has a high case-fatality rate. What can be inferred about its impact on population mortality?","options":[{"id":"a","text":"It is a leading cause of death"},{"id":"b","text":"It has a low impact on population mortality"},{"id":"c","text":"It affects the entire population"},{"id":"d","text":"It requires age-standardization for comparison"}],"answerId":"b","explanation":"A high case-fatality rate in a rare disease means it kills most of the few it infects but contributes little to overall population mortality.","kind":"trap","origin":"ai"},{"id":"ich-mortality-morbidity-measures~ai-6","moduleId":"ich-mortality-morbidity-measures","stem":"How does the concept of 'population at risk' in incidence calculations relate to the denominator in prevalence calculations?","options":[{"id":"a","text":"Both use the total population"},{"id":"b","text":"Incidence uses the population at risk; prevalence uses the total population"},{"id":"c","text":"Both use the population at risk"},{"id":"d","text":"Prevalence uses the population at risk; incidence uses the total population"}],"answerId":"b","explanation":"Incidence calculations include only those who can newly develop the disease, while prevalence includes the total population.","kind":"mechanism","origin":"ai"},{"id":"ich-mortality-morbidity-measures~ai-7","moduleId":"ich-mortality-morbidity-measures","stem":"In the context of disease occurrence, how does a change in the duration of a disease affect measures of association?","options":[{"id":"a","text":"It alters the incidence rate"},{"id":"b","text":"It affects the prevalence but not the incidence"},{"id":"c","text":"It changes the case-fatality rate"},{"id":"d","text":"It impacts the crude death rate"}],"answerId":"b","explanation":"An increase in disease duration raises prevalence without affecting incidence, which can influence measures of association.","kind":"integration","linkedModuleIds":["ich-measures-of-association"],"origin":"ai"},{"id":"ich-mortality-morbidity-measures~ai-8","moduleId":"ich-mortality-morbidity-measures","stem":"How does an increase in the prevalence of a disease affect the interpretation of its impact on population health compared to incidence?","options":[{"id":"a","text":"It indicates a higher risk of developing the disease"},{"id":"b","text":"It suggests a longer duration or better survival"},{"id":"c","text":"It implies a higher case-fatality rate"},{"id":"d","text":"It reflects an increase in new cases"}],"answerId":"b","explanation":"An increase in prevalence may suggest a longer duration of the disease or improved survival, rather than an increase in new cases.","kind":"integration","linkedModuleIds":["ich-disease-occurrence-concepts"],"origin":"ai"}],"ich-ebm-five-steps":[{"id":"ich-ebm-five-steps~ai-0","moduleId":"ich-ebm-five-steps","stem":"What is the first step in the Evidence-Based Medicine (EBM) process?","options":[{"id":"a","text":"Ask"},{"id":"b","text":"Acquire"},{"id":"c","text":"Appraise"},{"id":"d","text":"Apply"}],"answerId":"a","explanation":"The EBM process begins with 'Ask', which involves formulating a focused clinical question.","kind":"recall","origin":"ai"},{"id":"ich-ebm-five-steps~ai-1","moduleId":"ich-ebm-five-steps","stem":"Which study design is most appropriate for answering a therapy-related PICO question?","options":[{"id":"a","text":"Randomized Controlled Trial"},{"id":"b","text":"Cohort Study"},{"id":"c","text":"Case-Control Study"},{"id":"d","text":"Cross-Sectional Study"}],"answerId":"a","explanation":"Randomized Controlled Trials (RCTs) are the gold standard for evaluating the effectiveness of interventions.","kind":"recall","origin":"ai"},{"id":"ich-ebm-five-steps~ai-2","moduleId":"ich-ebm-five-steps","stem":"In the EBM process, which step involves evaluating the validity and applicability of the evidence?","options":[{"id":"a","text":"Ask"},{"id":"b","text":"Acquire"},{"id":"c","text":"Appraise"},{"id":"d","text":"Apply"}],"answerId":"c","explanation":"The 'Appraise' step involves critically evaluating the evidence for its validity and relevance.","kind":"mechanism","origin":"ai"},{"id":"ich-ebm-five-steps~ai-3","moduleId":"ich-ebm-five-steps","stem":"A clinician is deciding on a treatment plan for a patient with a rare condition. Which type of question should they formulate?","options":[{"id":"a","text":"Background question"},{"id":"b","text":"Foreground question"},{"id":"c","text":"General knowledge question"},{"id":"d","text":"Textbook question"}],"answerId":"b","explanation":"Foreground questions are specific and structured, suitable for making clinical decisions about individual patients.","kind":"clinical","origin":"ai"},{"id":"ich-ebm-five-steps~ai-4","moduleId":"ich-ebm-five-steps","stem":"Which of the following best describes the role of the PICO format in EBM?","options":[{"id":"a","text":"It is used for all types of clinical questions"},{"id":"b","text":"It helps formulate background questions"},{"id":"c","text":"It structures specific patient-related questions"},{"id":"d","text":"It replaces the need for critical appraisal"}],"answerId":"c","explanation":"PICO is used to structure specific, patient-related questions to guide evidence search and appraisal.","kind":"trap","origin":"ai"},{"id":"ich-ebm-five-steps~ai-5","moduleId":"ich-ebm-five-steps","stem":"How does the 'Assess' step in EBM contribute to the process?","options":[{"id":"a","text":"It involves formulating the clinical question"},{"id":"b","text":"It evaluates the outcome of the applied evidence"},{"id":"c","text":"It gathers the best available evidence"},{"id":"d","text":"It applies the evidence to patient care"}],"answerId":"b","explanation":"The 'Assess' step involves evaluating the effectiveness of the applied evidence and reflecting on the process.","kind":"mechanism","origin":"ai"},{"id":"ich-ebm-five-steps~ai-6","moduleId":"ich-ebm-five-steps","stem":"When integrating evidence into patient care, which module provides guidance on applying evidence effectively?","options":[{"id":"a","text":"Taste & Olfactory Receptor Histology"},{"id":"b","text":"Applying Evidence to Patients"},{"id":"c","text":"Evidence-Based Medicine & Levels of Evidence"},{"id":"d","text":"The Five Steps of EBM"}],"answerId":"b","explanation":"The 'Applying Evidence to Patients' module focuses on how to effectively integrate evidence into clinical practice.","kind":"integration","linkedModuleIds":["ich-ebm-applying-evidence"],"origin":"ai"},{"id":"ich-ebm-five-steps~ai-7","moduleId":"ich-ebm-five-steps","stem":"Which module would provide foundational knowledge for understanding the hierarchy of evidence in EBM?","options":[{"id":"a","text":"Taste & Olfactory Receptor Histology"},{"id":"b","text":"Applying Evidence to Patients"},{"id":"c","text":"Evidence-Based Medicine & Levels of Evidence"},{"id":"d","text":"The Five Steps of EBM"}],"answerId":"c","explanation":"The 'Evidence-Based Medicine & Levels of Evidence' module provides detailed information on the hierarchy and levels of evidence.","kind":"integration","linkedModuleIds":["ers-evidence-based-medicine"],"origin":"ai"}],"beh-difficult-encounters":[{"id":"beh-difficult-encounters~ai-0","moduleId":"beh-difficult-encounters","stem":"Which of the following is the first step in the SPIKES protocol for breaking bad news?","options":[{"id":"a","text":"Setting up the interview"},{"id":"b","text":"Assessing perception"},{"id":"c","text":"Obtaining the invitation"},{"id":"d","text":"Giving knowledge"}],"answerId":"a","explanation":"The first step in SPIKES is setting up the interview to ensure privacy and comfort.","kind":"recall","origin":"ai"},{"id":"beh-difficult-encounters~ai-1","moduleId":"beh-difficult-encounters","stem":"A patient becomes visibly angry during a consultation. What is the most appropriate initial response?","options":[{"id":"a","text":"Defend your actions"},{"id":"b","text":"Acknowledge the anger"},{"id":"c","text":"Ignore the emotion"},{"id":"d","text":"Immediately end the consultation"}],"answerId":"b","explanation":"Acknowledging the patient's anger helps to validate their feelings and can de-escalate the situation.","kind":"clinical","origin":"ai"},{"id":"beh-difficult-encounters~ai-2","moduleId":"beh-difficult-encounters","stem":"In the context of a somatizing patient, what is the primary goal of scheduled visits?","options":[{"id":"a","text":"To cure the underlying condition"},{"id":"b","text":"To validate the patient's distress"},{"id":"c","text":"To perform more diagnostic tests"},{"id":"d","text":"To reduce healthcare costs"}],"answerId":"b","explanation":"Scheduled visits aim to validate the patient's distress and shift the focus from cure to care.","kind":"mechanism","origin":"ai"},{"id":"beh-difficult-encounters~ai-3","moduleId":"beh-difficult-encounters","stem":"Which of the following best describes shared decision-making?","options":[{"id":"a","text":"The doctor makes all decisions"},{"id":"b","text":"The patient makes all decisions"},{"id":"c","text":"The doctor and patient make decisions together"},{"id":"d","text":"The patient is given information and left to decide alone"}],"answerId":"c","explanation":"Shared decision-making involves both the doctor and patient collaborating to make healthcare decisions.","kind":"trap","origin":"ai"},{"id":"beh-difficult-encounters~ai-4","moduleId":"beh-difficult-encounters","stem":"A patient is silent and withdrawn during a consultation. What is the most appropriate approach?","options":[{"id":"a","text":"Confront the patient about their behavior"},{"id":"b","text":"Allow silence and wait for them to speak"},{"id":"c","text":"Encourage them to express their thoughts"},{"id":"d","text":"End the consultation early"}],"answerId":"c","explanation":"Encouraging the patient to express their thoughts can help them feel more comfortable and engaged.","kind":"clinical","origin":"ai"},{"id":"beh-difficult-encounters~ai-5","moduleId":"beh-difficult-encounters","stem":"During a difficult encounter, why is it important to reframe the situation as about the system rather than the patient?","options":[{"id":"a","text":"To avoid legal issues"},{"id":"b","text":"To depersonalize the tension"},{"id":"c","text":"To expedite the consultation"},{"id":"d","text":"To avoid addressing the patient's emotions"}],"answerId":"b","explanation":"Reframing helps depersonalize the tension and directs the clinician to use appropriate techniques.","kind":"mechanism","origin":"ai"},{"id":"beh-difficult-encounters~ai-6","moduleId":"beh-difficult-encounters","stem":"How does the SPIKES protocol integrate with clinical communication skills?","options":[{"id":"a","text":"It replaces the need for empathy"},{"id":"b","text":"It provides a structured approach to difficult conversations"},{"id":"c","text":"It focuses solely on delivering bad news"},{"id":"d","text":"It eliminates the need for patient feedback"}],"answerId":"b","explanation":"SPIKES provides a structured approach that enhances clinical communication skills by guiding difficult conversations.","kind":"integration","linkedModuleIds":["beh-communication-skills"],"origin":"ai"},{"id":"beh-difficult-encounters~ai-7","moduleId":"beh-difficult-encounters","stem":"How does managing an angry patient relate to techniques in aggression and de-escalation?","options":[{"id":"a","text":"It requires immediate physical restraint"},{"id":"b","text":"It involves acknowledging emotions and setting limits"},{"id":"c","text":"It is unrelated and uses different strategies"},{"id":"d","text":"It focuses on ignoring the patient's anger"}],"answerId":"b","explanation":"Managing an angry patient involves acknowledging emotions and setting limits, similar to de-escalation techniques.","kind":"integration","linkedModuleIds":["beh-aggression-violence"],"origin":"ai"}],"beh-intro-behavioral-science":[{"id":"beh-intro-behavioral-science~ai-0","moduleId":"beh-intro-behavioral-science","stem":"Which of the following disciplines focuses on the study of shared meanings, beliefs, and practices in different societies?","options":[{"id":"a","text":"Psychology"},{"id":"b","text":"Sociology"},{"id":"c","text":"Anthropology"},{"id":"d","text":"Biology"}],"answerId":"c","explanation":"Anthropology studies culture, including shared meanings, beliefs, and practices.","kind":"recall","origin":"ai"},{"id":"beh-intro-behavioral-science~ai-1","moduleId":"beh-intro-behavioral-science","stem":"What is the primary focus of sociology within behavioral science?","options":[{"id":"a","text":"Individual cognition and emotion"},{"id":"b","text":"Group roles and social structure"},{"id":"c","text":"Cultural beliefs and practices"},{"id":"d","text":"Biological predispositions"}],"answerId":"b","explanation":"Sociology studies groups, roles, institutions, and social structure.","kind":"recall","origin":"ai"},{"id":"beh-intro-behavioral-science~ai-2","moduleId":"beh-intro-behavioral-science","stem":"Which model reintegrated psychological schools into a comprehensive understanding of behavior in 1977?","options":[{"id":"a","text":"Biomedical model"},{"id":"b","text":"Biopsychosocial model"},{"id":"c","text":"Behaviorist model"},{"id":"d","text":"Humanistic model"}],"answerId":"b","explanation":"Engel's biopsychosocial model reintegrated psychological schools in 1977.","kind":"recall","origin":"ai"},{"id":"beh-intro-behavioral-science~ai-3","moduleId":"beh-intro-behavioral-science","stem":"A patient believes their health is entirely determined by their genetic makeup. Which concept would best address this misconception?","options":[{"id":"a","text":"Nature versus nurture"},{"id":"b","text":"Biopsychosocial model"},{"id":"c","text":"Behavioral genetics"},{"id":"d","text":"Classical conditioning"}],"answerId":"a","explanation":"Nature versus nurture is a false dichotomy; behavior arises from gene–environment interaction.","kind":"trap","origin":"ai"},{"id":"beh-intro-behavioral-science~ai-4","moduleId":"beh-intro-behavioral-science","stem":"Which of the following is a leading cause of premature mortality that is considered modifiable?","options":[{"id":"a","text":"Genetic disorders"},{"id":"b","text":"Smoking"},{"id":"c","text":"Age-related diseases"},{"id":"d","text":"Infectious diseases"}],"answerId":"b","explanation":"Smoking is a modifiable behavior contributing to premature mortality.","kind":"clinical","origin":"ai"},{"id":"beh-intro-behavioral-science~ai-5","moduleId":"beh-intro-behavioral-science","stem":"How does the biopsychosocial model differ from the traditional biomedical model?","options":[{"id":"a","text":"Focuses solely on biological factors"},{"id":"b","text":"Integrates psychological and social factors"},{"id":"c","text":"Excludes cultural influences"},{"id":"d","text":"Prioritizes genetic predispositions"}],"answerId":"b","explanation":"The biopsychosocial model integrates psychological and social factors with biological ones.","kind":"mechanism","origin":"ai"},{"id":"beh-intro-behavioral-science~ai-6","moduleId":"beh-intro-behavioral-science","stem":"In the context of behavioral science, which of the following best describes the diathesis-stress model?","options":[{"id":"a","text":"Behavior is solely determined by genetics"},{"id":"b","text":"Environmental stressors trigger predisposed vulnerabilities"},{"id":"c","text":"Cultural factors are the primary cause of disorders"},{"id":"d","text":"Social structures have no impact on individual behavior"}],"answerId":"b","explanation":"The diathesis-stress model suggests that environmental stressors can trigger disorders in individuals with certain vulnerabilities.","kind":"mechanism","origin":"ai"},{"id":"beh-intro-behavioral-science~ai-7","moduleId":"beh-intro-behavioral-science","stem":"Which aspect of behavioral science is most directly linked to understanding mortality and morbidity frequency measures?","options":[{"id":"a","text":"Psychological resilience"},{"id":"b","text":"Sociocultural determinants"},{"id":"c","text":"Modifiable behaviors"},{"id":"d","text":"Genetic predispositions"}],"answerId":"c","explanation":"Modifiable behaviors such as smoking and diet are key factors in understanding mortality and morbidity.","kind":"integration","linkedModuleIds":["ich-mortality-morbidity-measures"],"origin":"ai"},{"id":"beh-intro-behavioral-science~ai-8","moduleId":"beh-intro-behavioral-science","stem":"How does the biopsychosocial model apply to the study of pathology?","options":[{"id":"a","text":"Focuses only on pathological anatomy"},{"id":"b","text":"Considers psychological and social influences on disease"},{"id":"c","text":"Ignores environmental factors"},{"id":"d","text":"Emphasizes genetic mutations"}],"answerId":"b","explanation":"The biopsychosocial model considers psychological and social influences alongside biological factors in disease.","kind":"integration","linkedModuleIds":["intro-pathology-scope"],"origin":"ai"}],"beh-biopsychosocial-model":[{"id":"beh-biopsychosocial-model~ai-0","moduleId":"beh-biopsychosocial-model","stem":"Which of the following best describes the biopsychosocial model?","options":[{"id":"a","text":"An integrated approach considering biological, psychological, and social factors"},{"id":"b","text":"A model that focuses solely on psychological factors"},{"id":"c","text":"A model that emphasizes social factors over biological ones"},{"id":"d","text":"A purely biological approach to understanding health and illness"}],"answerId":"a","explanation":"The biopsychosocial model integrates biological, psychological, and social factors in understanding health and illness.","kind":"recall","origin":"ai"},{"id":"beh-biopsychosocial-model~ai-1","moduleId":"beh-biopsychosocial-model","stem":"What was the primary limitation of the biomedical model that the biopsychosocial model aimed to address?","options":[{"id":"a","text":"Its focus on psychological factors"},{"id":"b","text":"Its exclusion of biological factors"},{"id":"c","text":"Its reductionist and dualist nature"},{"id":"d","text":"Its emphasis on social factors"}],"answerId":"c","explanation":"The biomedical model is reductionist and dualist, focusing only on biological deviations, which the biopsychosocial model addresses by including psychological and social factors.","kind":"mechanism","origin":"ai"},{"id":"beh-biopsychosocial-model~ai-2","moduleId":"beh-biopsychosocial-model","stem":"A patient presents with chronic pain. Which aspect of the biopsychosocial model would be most relevant in understanding the patient's experience of illness?","options":[{"id":"a","text":"Biological factors such as genetic predisposition"},{"id":"b","text":"Psychological factors such as mood and coping strategies"},{"id":"c","text":"Social factors such as family support"},{"id":"d","text":"All of the above"}],"answerId":"d","explanation":"The biopsychosocial model considers biological, psychological, and social factors as interconnected in understanding health and illness.","kind":"clinical","origin":"ai"},{"id":"beh-biopsychosocial-model~ai-3","moduleId":"beh-biopsychosocial-model","stem":"In the context of the biopsychosocial model, how is 'sickness' best defined?","options":[{"id":"a","text":"The biological pathology of a disease"},{"id":"b","text":"The patient's subjective experience of feeling unwell"},{"id":"c","text":"The social role and its meaning related to being unwell"},{"id":"d","text":"A deviation from psychological norms"}],"answerId":"c","explanation":"Sickness refers to the social role and its meaning, distinct from disease and illness.","kind":"recall","origin":"ai"},{"id":"beh-biopsychosocial-model~ai-4","moduleId":"beh-biopsychosocial-model","stem":"How does the biopsychosocial model apply to family dynamics in illness?","options":[{"id":"a","text":"It considers only the biological impact of family history"},{"id":"b","text":"It focuses on the psychological impact of family relationships"},{"id":"c","text":"It integrates biological, psychological, and social influences of family on illness"},{"id":"d","text":"It emphasizes the social role of family without considering biological factors"}],"answerId":"c","explanation":"The biopsychosocial model integrates all three domains to understand the influence of family dynamics on illness.","kind":"integration","linkedModuleIds":["beh-family-dynamics"],"origin":"ai"},{"id":"beh-biopsychosocial-model~ai-5","moduleId":"beh-biopsychosocial-model","stem":"Which of the following statements is a common trap when comparing the biomedical and biopsychosocial models?","options":[{"id":"a","text":"The biopsychosocial model replaces biological factors with psychological ones"},{"id":"b","text":"The biopsychosocial model includes biological factors as one of three domains"},{"id":"c","text":"The biomedical model focuses solely on biological deviations"},{"id":"d","text":"The biopsychosocial model integrates psychological and social factors with biology"}],"answerId":"a","explanation":"A common trap is thinking the biopsychosocial model replaces biology, but it actually integrates it with psychological and social factors.","kind":"trap","origin":"ai"},{"id":"beh-biopsychosocial-model~ai-6","moduleId":"beh-biopsychosocial-model","stem":"In the biopsychosocial model, which domain would most likely address a patient's adherence to a treatment plan?","options":[{"id":"a","text":"Biological factors"},{"id":"b","text":"Psychological factors"},{"id":"c","text":"Social factors"},{"id":"d","text":"None of the above"}],"answerId":"b","explanation":"Psychological factors, such as beliefs and behavior, play a crucial role in a patient's adherence to treatment.","kind":"mechanism","origin":"ai"},{"id":"beh-biopsychosocial-model~ai-7","moduleId":"beh-biopsychosocial-model","stem":"How does the biopsychosocial model inform understanding of sexual response models?","options":[{"id":"a","text":"By emphasizing biological factors in sexual health"},{"id":"b","text":"By integrating psychological and social factors with biological aspects"},{"id":"c","text":"By focusing solely on psychological aspects of sexual response"},{"id":"d","text":"By disregarding social influences on sexual health"}],"answerId":"b","explanation":"The biopsychosocial model integrates biological, psychological, and social factors, which is crucial in understanding human sexual response.","kind":"integration","linkedModuleIds":["hrp1-sexual-response-models"],"origin":"ai"}],"beh-communication-skills":[{"id":"beh-communication-skills~ai-0","moduleId":"beh-communication-skills","stem":"Which of the following is the correct sequence of tasks in the Calgary–Cambridge consultation model?","options":[{"id":"a","text":"Initiating the session, gathering information, physical examination, explanation & planning, closing the session"},{"id":"b","text":"Gathering information, initiating the session, physical examination, explanation & planning, closing the session"},{"id":"c","text":"Initiating the session, physical examination, gathering information, explanation & planning, closing the session"},{"id":"d","text":"Initiating the session, explanation & planning, gathering information, physical examination, closing the session"}],"answerId":"a","explanation":"The Calgary–Cambridge model structures the consultation into five sequential tasks, starting with initiating the session.","kind":"recall","origin":"ai"},{"id":"beh-communication-skills~ai-1","moduleId":"beh-communication-skills","stem":"In the context of clinical communication, what does the acronym ICE stand for?","options":[{"id":"a","text":"Ideas, Concerns, Expectations"},{"id":"b","text":"Information, Communication, Empathy"},{"id":"c","text":"Initiate, Communicate, Evaluate"},{"id":"d","text":"Identify, Concerns, Empathy"}],"answerId":"a","explanation":"ICE stands for Ideas, Concerns, and Expectations, which are key components of patient-centred interviewing.","kind":"recall","origin":"ai"},{"id":"beh-communication-skills~ai-2","moduleId":"beh-communication-skills","stem":"Which of the following best describes the funnel technique in patient interviewing?","options":[{"id":"a","text":"Starting with open questions and moving to closed questions"},{"id":"b","text":"Beginning with closed questions and expanding to open questions"},{"id":"c","text":"Using only open questions throughout the interview"},{"id":"d","text":"Using only closed questions to gather specific information"}],"answerId":"a","explanation":"The funnel technique involves starting with open questions to gather the patient's story, then narrowing down with closed questions.","kind":"mechanism","origin":"ai"},{"id":"beh-communication-skills~ai-3","moduleId":"beh-communication-skills","stem":"A patient expresses fear about their diagnosis. Which response demonstrates empathy?","options":[{"id":"a","text":"\"That sounds frightening, can you tell me more about how you feel?\""},{"id":"b","text":"\"I feel so sorry for you.\""},{"id":"c","text":"\"Let's focus on the treatment options.\""},{"id":"d","text":"\"I understand, but we need to move on.\""}],"answerId":"a","explanation":"Empathy involves naming and reflecting the patient's emotion, which helps build trust.","kind":"trap","origin":"ai"},{"id":"beh-communication-skills~ai-4","moduleId":"beh-communication-skills","stem":"During a consultation, a doctor notices a patient is fidgeting and avoiding eye contact. What should the doctor consider?","options":[{"id":"a","text":"The patient may be anxious or uncomfortable"},{"id":"b","text":"The patient is not interested in the consultation"},{"id":"c","text":"The patient is hiding something"},{"id":"d","text":"The patient is naturally shy"}],"answerId":"a","explanation":"Non-verbal cues like fidgeting and avoiding eye contact can indicate anxiety or discomfort.","kind":"clinical","origin":"ai"},{"id":"beh-communication-skills~ai-5","moduleId":"beh-communication-skills","stem":"How does empathy differ from sympathy in a clinical setting?","options":[{"id":"a","text":"Empathy involves understanding the patient's feelings; sympathy involves feeling sorry for them"},{"id":"b","text":"Empathy is feeling sorry for the patient; sympathy is understanding their feelings"},{"id":"c","text":"Empathy and sympathy are interchangeable in clinical practice"},{"id":"d","text":"Empathy involves ignoring the patient's feelings; sympathy involves addressing them"}],"answerId":"a","explanation":"Empathy involves understanding and reflecting the patient's feelings, while sympathy is feeling sorry for them.","kind":"trap","origin":"ai"},{"id":"beh-communication-skills~ai-6","moduleId":"beh-communication-skills","stem":"A patient with a fractured arm is worried about the impact on their daily activities. How should the doctor address this concern using the Calgary–Cambridge model?","options":[{"id":"a","text":"Acknowledge the concern and discuss possible adaptations"},{"id":"b","text":"Ignore the concern and focus on the fracture treatment"},{"id":"c","text":"Reassure the patient that everything will be fine"},{"id":"d","text":"Refer the patient to a specialist without addressing the concern"}],"answerId":"a","explanation":"Acknowledging the patient's concern and discussing adaptations aligns with patient-centred care and the Calgary–Cambridge model.","kind":"integration","linkedModuleIds":["fracture-classification"],"origin":"ai"},{"id":"beh-communication-skills~ai-7","moduleId":"beh-communication-skills","stem":"In a consultation about end-of-life care, how can a doctor effectively use the NURSE framework?","options":[{"id":"a","text":"By naming, understanding, respecting, supporting, and exploring the patient's emotions"},{"id":"b","text":"By focusing solely on the medical aspects of care"},{"id":"c","text":"By providing sympathy and reassurance"},{"id":"d","text":"By avoiding emotional discussions"}],"answerId":"a","explanation":"The NURSE framework helps make empathy explicit by addressing the patient's emotions comprehensively.","kind":"integration","linkedModuleIds":["beh-death-dying"],"origin":"ai"}],"beh-doctor-patient-relationship":[{"id":"beh-doctor-patient-relationship~ai-0","moduleId":"beh-doctor-patient-relationship","stem":"Which model of the doctor-patient relationship is most appropriate during an emergency situation?","options":[{"id":"a","text":"Activity-passivity"},{"id":"b","text":"Guidance-cooperation"},{"id":"c","text":"Mutual participation"},{"id":"d","text":"Shared decision-making"}],"answerId":"a","explanation":"In emergencies, the doctor acts on an essentially passive patient, similar to a parent-infant relationship.","kind":"recall","origin":"ai"},{"id":"beh-doctor-patient-relationship~ai-1","moduleId":"beh-doctor-patient-relationship","stem":"In the context of chronic disease management, which model of the doctor-patient relationship is most effective?","options":[{"id":"a","text":"Activity-passivity"},{"id":"b","text":"Guidance-cooperation"},{"id":"c","text":"Mutual participation"},{"id":"d","text":"Directive counseling"}],"answerId":"c","explanation":"Mutual participation is ideal for chronic disease management as it involves shared power and decision-making.","kind":"mechanism","origin":"ai"},{"id":"beh-doctor-patient-relationship~ai-2","moduleId":"beh-doctor-patient-relationship","stem":"A patient redirects feelings from a past relationship onto their doctor. What is this an example of?","options":[{"id":"a","text":"Transference"},{"id":"b","text":"Countertransference"},{"id":"c","text":"Projection"},{"id":"d","text":"Displacement"}],"answerId":"a","explanation":"Transference involves the patient redirecting feelings from a past relationship onto the doctor.","kind":"recall","origin":"ai"},{"id":"beh-doctor-patient-relationship~ai-3","moduleId":"beh-doctor-patient-relationship","stem":"A doctor feels unusually frustrated with a patient, which is out of character. This is an example of what?","options":[{"id":"a","text":"Transference"},{"id":"b","text":"Countertransference"},{"id":"c","text":"Empathy"},{"id":"d","text":"Projection"}],"answerId":"b","explanation":"Countertransference is the doctor's emotional reaction to the patient, which may be influenced by the doctor's own past experiences.","kind":"trap","origin":"ai"},{"id":"beh-doctor-patient-relationship~ai-4","moduleId":"beh-doctor-patient-relationship","stem":"What is a key component of the therapeutic alliance that predicts treatment adherence?","options":[{"id":"a","text":"Emotional bond"},{"id":"b","text":"Patient's compliance"},{"id":"c","text":"Doctor's authority"},{"id":"d","text":"Patient's knowledge"}],"answerId":"a","explanation":"An emotional bond, along with agreed goals and tasks, forms the therapeutic alliance which predicts adherence.","kind":"clinical","origin":"ai"},{"id":"beh-doctor-patient-relationship~ai-5","moduleId":"beh-doctor-patient-relationship","stem":"A doctor notices they are feeling unusually sympathetic towards a patient who reminds them of a family member. How should this be interpreted?","options":[{"id":"a","text":"Transference"},{"id":"b","text":"Countertransference"},{"id":"c","text":"Empathy"},{"id":"d","text":"Projection"}],"answerId":"b","explanation":"This is countertransference, where the doctor's feelings towards the patient are influenced by their own past experiences.","kind":"trap","origin":"ai"},{"id":"beh-doctor-patient-relationship~ai-6","moduleId":"beh-doctor-patient-relationship","stem":"Which communication skill is essential for building rapport in the doctor-patient relationship?","options":[{"id":"a","text":"Active listening"},{"id":"b","text":"Providing advice"},{"id":"c","text":"Using medical jargon"},{"id":"d","text":"Maintaining authority"}],"answerId":"a","explanation":"Active listening helps build rapport by showing empathy and understanding.","kind":"integration","linkedModuleIds":["beh-communication-skills"],"origin":"ai"},{"id":"beh-doctor-patient-relationship~ai-7","moduleId":"beh-doctor-patient-relationship","stem":"How does the concept of transference relate to Freud's psychodynamic theory?","options":[{"id":"a","text":"It involves conscious feelings"},{"id":"b","text":"It is a defense mechanism"},{"id":"c","text":"It is an unconscious relational pattern"},{"id":"d","text":"It is a form of active listening"}],"answerId":"c","explanation":"Transference is an unconscious relational pattern where past feelings are redirected onto the doctor, aligning with psychodynamic theory.","kind":"integration","linkedModuleIds":["beh-freud-structural-topographic"],"origin":"ai"}],"beh-mental-status-exam":[{"id":"beh-mental-status-exam~ai-0","moduleId":"beh-mental-status-exam","stem":"Which of the following best describes the difference between mood and affect in the Mental Status Examination?","options":[{"id":"a","text":"Mood is the patient's subjective report; affect is the examiner's objective observation."},{"id":"b","text":"Mood is the examiner's objective observation; affect is the patient's subjective report."},{"id":"c","text":"Mood and affect are interchangeable terms for emotional state."},{"id":"d","text":"Mood is immediate and momentary; affect is sustained over time."}],"answerId":"a","explanation":"Mood is the subjective, sustained emotional state reported by the patient, while affect is the objective, moment-to-moment emotion observed by the examiner.","kind":"recall","origin":"ai"},{"id":"beh-mental-status-exam~ai-1","moduleId":"beh-mental-status-exam","stem":"During a Mental Status Examination, a patient exhibits a flight of ideas. What aspect of thought does this represent?","options":[{"id":"a","text":"Thought content"},{"id":"b","text":"Thought process"},{"id":"c","text":"Perception"},{"id":"d","text":"Cognition"}],"answerId":"b","explanation":"Flight of ideas is a disturbance in thought process, characterized by rapid and continuous speech with abrupt changes in topic.","kind":"mechanism","origin":"ai"},{"id":"beh-mental-status-exam~ai-2","moduleId":"beh-mental-status-exam","stem":"A patient reports feeling 'depressed' but displays a bright and cheerful demeanor during the interview. This is an example of:","options":[{"id":"a","text":"Congruent affect"},{"id":"b","text":"Incongruent affect"},{"id":"c","text":"Restricted affect"},{"id":"d","text":"Flat affect"}],"answerId":"b","explanation":"Incongruent affect occurs when the observed emotional expression does not match the reported mood.","kind":"clinical","origin":"ai"},{"id":"beh-mental-status-exam~ai-3","moduleId":"beh-mental-status-exam","stem":"Which of the following is a key component of the Mental Status Examination that requires direct questioning?","options":[{"id":"a","text":"Mood"},{"id":"b","text":"Affect"},{"id":"c","text":"Cognition"},{"id":"d","text":"Speech"}],"answerId":"c","explanation":"Cognition is assessed through direct questioning and testing, unlike other domains that are observed.","kind":"recall","origin":"ai"},{"id":"beh-mental-status-exam~ai-4","moduleId":"beh-mental-status-exam","stem":"A patient with schizophrenia is being evaluated. Which aspect of the Mental Status Examination is most likely to reveal delusions?","options":[{"id":"a","text":"Thought process"},{"id":"b","text":"Thought content"},{"id":"c","text":"Perception"},{"id":"d","text":"Insight"}],"answerId":"b","explanation":"Delusions are assessed under thought content, which involves what the patient is thinking about.","kind":"integration","linkedModuleIds":["beh-psychotic-disorders"],"origin":"ai"},{"id":"beh-mental-status-exam~ai-5","moduleId":"beh-mental-status-exam","stem":"In assessing a patient's risk of suicide, which component of the Mental Status Examination is most relevant?","options":[{"id":"a","text":"Appearance and behavior"},{"id":"b","text":"Insight and judgement"},{"id":"c","text":"Speech"},{"id":"d","text":"Perception"}],"answerId":"b","explanation":"Insight and judgement are crucial in assessing a patient's risk of suicide as they relate to awareness of illness and decision-making capacity.","kind":"integration","linkedModuleIds":["beh-suicide-assessment"],"origin":"ai"}],"beh-psychological-testing":[{"id":"beh-psychological-testing~ai-0","moduleId":"beh-psychological-testing","stem":"Which of the following is a projective personality test?","options":[{"id":"a","text":"MMPI"},{"id":"b","text":"WAIS"},{"id":"c","text":"Rorschach"},{"id":"d","text":"Stanford-Binet"}],"answerId":"c","explanation":"The Rorschach test uses ambiguous stimuli to elicit unconscious material, classifying it as a projective test.","kind":"recall","origin":"ai"},{"id":"beh-psychological-testing~ai-1","moduleId":"beh-psychological-testing","stem":"What is the primary purpose of the validity scales in the MMPI?","options":[{"id":"a","text":"To measure intelligence"},{"id":"b","text":"To detect response styles like faking-good or faking-bad"},{"id":"c","text":"To assess neuropsychological function"},{"id":"d","text":"To evaluate visuomotor skills"}],"answerId":"b","explanation":"The MMPI validity scales are designed to identify over- or under-reporting of symptoms.","kind":"mechanism","origin":"ai"},{"id":"beh-psychological-testing~ai-2","moduleId":"beh-psychological-testing","stem":"A patient scores 130 on an IQ test. What does this score indicate?","options":[{"id":"a","text":"Below average intelligence"},{"id":"b","text":"Average intelligence"},{"id":"c","text":"Above average intelligence"},{"id":"d","text":"Severe intellectual disability"}],"answerId":"c","explanation":"An IQ score of 130 is above average, as the mean is 100 with a standard deviation of 15.","kind":"recall","origin":"ai"},{"id":"beh-psychological-testing~ai-3","moduleId":"beh-psychological-testing","stem":"Which of the following statements is true regarding psychological testing?","options":[{"id":"a","text":"A test can be valid but not reliable"},{"id":"b","text":"Reliability ensures a test measures what it claims"},{"id":"c","text":"A test must be reliable to be valid"},{"id":"d","text":"Validity and reliability are interchangeable terms"}],"answerId":"c","explanation":"A test must first be reliable to be valid, as reliability refers to the consistency of the test results.","kind":"trap","origin":"ai"},{"id":"beh-psychological-testing~ai-4","moduleId":"beh-psychological-testing","stem":"Which test is most appropriate for assessing symptom severity in depression?","options":[{"id":"a","text":"Rorschach"},{"id":"b","text":"PHQ-9"},{"id":"c","text":"WAIS"},{"id":"d","text":"Stanford-Binet"}],"answerId":"b","explanation":"The PHQ-9 is a rating scale specifically designed to quantify and track the severity of depressive symptoms.","kind":"recall","origin":"ai"},{"id":"beh-psychological-testing~ai-5","moduleId":"beh-psychological-testing","stem":"A clinician uses the Bender-Gestalt test. What is the primary focus of this test?","options":[{"id":"a","text":"Intelligence assessment"},{"id":"b","text":"Personality evaluation"},{"id":"c","text":"Visuomotor integration"},{"id":"d","text":"Symptom severity tracking"}],"answerId":"c","explanation":"The Bender-Gestalt test is used to assess visuomotor integration, a key component of neuropsychological testing.","kind":"mechanism","origin":"ai"},{"id":"beh-psychological-testing~ai-6","moduleId":"beh-psychological-testing","stem":"In the context of PTSD treatment, which psychological test can help track symptom changes over time?","options":[{"id":"a","text":"Rorschach"},{"id":"b","text":"PHQ-9"},{"id":"c","text":"MMPI"},{"id":"d","text":"Stanford-Binet"}],"answerId":"b","explanation":"The PHQ-9 is useful for tracking changes in depressive symptoms, which can be relevant in PTSD treatment.","kind":"integration","linkedModuleIds":["hrp1-trauma-asd-ptsd-first-aid"],"origin":"ai"},{"id":"beh-psychological-testing~ai-7","moduleId":"beh-psychological-testing","stem":"How does the mental status examination complement psychological testing?","options":[{"id":"a","text":"It replaces the need for psychological tests"},{"id":"b","text":"It provides structured test scores"},{"id":"c","text":"It offers clinical context and qualitative data"},{"id":"d","text":"It is a type of projective test"}],"answerId":"c","explanation":"The mental status examination provides qualitative data and clinical context that complement the quantitative data from psychological tests.","kind":"integration","linkedModuleIds":["beh-mental-status-exam"],"origin":"ai"}],"beh-psychiatric-history":[{"id":"beh-psychiatric-history~ai-0","moduleId":"beh-psychiatric-history","stem":"Which component of the psychiatric history involves understanding the patient's baseline characteristics before the onset of illness?","options":[{"id":"a","text":"Premorbid personality"},{"id":"b","text":"Chief complaint"},{"id":"c","text":"Collateral history"},{"id":"d","text":"Mental status examination"}],"answerId":"a","explanation":"Premorbid personality refers to the patient's baseline characteristics before the onset of illness, helping differentiate between a disorder and a lifelong trait.","kind":"recall","origin":"ai"},{"id":"beh-psychiatric-history~ai-1","moduleId":"beh-psychiatric-history","stem":"During a psychiatric interview, a patient reports feeling withdrawn and isolated over the past month. What aspect of the psychiatric history does this information belong to?","options":[{"id":"a","text":"History of present illness"},{"id":"b","text":"Past psychiatric history"},{"id":"c","text":"Collateral history"},{"id":"d","text":"Premorbid personality"}],"answerId":"a","explanation":"The history of present illness includes the current episode's onset, course, and context, distinguishing it from past psychiatric history.","kind":"trap","origin":"ai"},{"id":"beh-psychiatric-history~ai-2","moduleId":"beh-psychiatric-history","stem":"In a psychiatric assessment, why is it important to obtain a collateral history?","options":[{"id":"a","text":"To confirm the patient's diagnosis"},{"id":"b","text":"To assess the patient's risk of harm"},{"id":"c","text":"To gather information the patient may not provide"},{"id":"d","text":"To establish rapport with the patient"}],"answerId":"c","explanation":"Collateral history provides information that the patient may not be able to report due to impaired insight or minimization.","kind":"mechanism","origin":"ai"},{"id":"beh-psychiatric-history~ai-3","moduleId":"beh-psychiatric-history","stem":"Which of the following is a key difference between the psychiatric history and the mental status examination (MSE)?","options":[{"id":"a","text":"The history is subjective; the MSE is objective"},{"id":"b","text":"The history is objective; the MSE is subjective"},{"id":"c","text":"The history focuses on current symptoms; the MSE focuses on past symptoms"},{"id":"d","text":"The history is a cross-sectional view; the MSE is longitudinal"}],"answerId":"a","explanation":"The psychiatric history is subjective and longitudinal, while the MSE is an objective assessment of the current mental state.","kind":"clinical","origin":"ai"},{"id":"beh-psychiatric-history~ai-4","moduleId":"beh-psychiatric-history","stem":"What is the primary goal of screening for suicidal ideation early in a psychiatric assessment?","options":[{"id":"a","text":"To determine the patient's diagnosis"},{"id":"b","text":"To build rapport with the patient"},{"id":"c","text":"To assess risk to self and others"},{"id":"d","text":"To gather collateral information"}],"answerId":"c","explanation":"Screening for suicidal ideation early helps assess the patient's risk to self and others, which is crucial for safety planning.","kind":"clinical","origin":"ai"},{"id":"beh-psychiatric-history~ai-5","moduleId":"beh-psychiatric-history","stem":"How does understanding a patient's developmental history aid in psychiatric assessment?","options":[{"id":"a","text":"It identifies current symptoms"},{"id":"b","text":"It reveals the patient's premorbid personality"},{"id":"c","text":"It provides insight into the longitudinal trajectory and onset of vulnerabilities"},{"id":"d","text":"It confirms the diagnosis"}],"answerId":"c","explanation":"Developmental history provides insight into the patient's life trajectory, revealing vulnerabilities and the onset of psychiatric issues.","kind":"mechanism","origin":"ai"},{"id":"beh-psychiatric-history~ai-6","moduleId":"beh-psychiatric-history","stem":"How does the psychiatric interview relate to the doctor-patient relationship?","options":[{"id":"a","text":"The interview is purely diagnostic, unrelated to the relationship"},{"id":"b","text":"The interview is a tool for building trust and rapport, essential for an effective doctor-patient relationship"},{"id":"c","text":"The interview replaces the need for a strong doctor-patient relationship"},{"id":"d","text":"The interview is only about gathering information, not about relationship dynamics"}],"answerId":"b","explanation":"The psychiatric interview is crucial for building trust and rapport, which are essential components of the doctor-patient relationship.","kind":"integration","linkedModuleIds":["beh-doctor-patient-relationship"],"origin":"ai"},{"id":"beh-psychiatric-history~ai-7","moduleId":"beh-psychiatric-history","stem":"What role does communication skills play in conducting an effective psychiatric interview?","options":[{"id":"a","text":"They are not important in psychiatric interviews"},{"id":"b","text":"They help in diagnosing the patient without the need for collateral history"},{"id":"c","text":"They facilitate rapport-building and accurate information gathering"},{"id":"d","text":"They are only necessary for explaining treatment plans"}],"answerId":"c","explanation":"Effective communication skills facilitate rapport-building and accurate information gathering during a psychiatric interview.","kind":"integration","linkedModuleIds":["beh-communication-skills"],"origin":"ai"}],"beh-psychotic-disorders":[{"id":"beh-psychotic-disorders~ai-0","moduleId":"beh-psychotic-disorders","stem":"A 25-year-old male presents with auditory hallucinations and disorganized speech for the past 3 weeks. What is the most likely diagnosis?","options":[{"id":"a","text":"Brief psychotic disorder"},{"id":"b","text":"Schizophreniform disorder"},{"id":"c","text":"Schizophrenia"},{"id":"d","text":"Schizoaffective disorder"}],"answerId":"a","explanation":"Brief psychotic disorder is diagnosed when symptoms last for at least 1 day but less than 1 month.","kind":"recall","origin":"ai"},{"id":"beh-psychotic-disorders~ai-1","moduleId":"beh-psychotic-disorders","stem":"Which symptom is considered a negative symptom of schizophrenia?","options":[{"id":"a","text":"Hallucinations"},{"id":"b","text":"Delusions"},{"id":"c","text":"Avolition"},{"id":"d","text":"Disorganized speech"}],"answerId":"c","explanation":"Avolition is a negative symptom characterized by a lack of motivation or ability to initiate and persist in goal-directed activities.","kind":"recall","origin":"ai"},{"id":"beh-psychotic-disorders~ai-2","moduleId":"beh-psychotic-disorders","stem":"A patient has experienced delusions and hallucinations for 5 months. Which diagnosis is most appropriate?","options":[{"id":"a","text":"Brief psychotic disorder"},{"id":"b","text":"Schizophreniform disorder"},{"id":"c","text":"Schizophrenia"},{"id":"d","text":"Schizoaffective disorder"}],"answerId":"b","explanation":"Schizophreniform disorder is diagnosed when symptoms last between 1 and 6 months.","kind":"trap","origin":"ai"},{"id":"beh-psychotic-disorders~ai-3","moduleId":"beh-psychotic-disorders","stem":"A patient with schizophrenia is experiencing positive symptoms. Which neurotransmitter pathway is primarily involved?","options":[{"id":"a","text":"Mesolimbic"},{"id":"b","text":"Mesocortical"},{"id":"c","text":"Nigrostriatal"},{"id":"d","text":"Tuberoinfundibular"}],"answerId":"a","explanation":"The mesolimbic pathway is associated with the positive symptoms of schizophrenia due to dopamine overactivity.","kind":"mechanism","origin":"ai"},{"id":"beh-psychotic-disorders~ai-4","moduleId":"beh-psychotic-disorders","stem":"A 30-year-old female has been diagnosed with schizoaffective disorder. What distinguishes this from a mood disorder with psychotic features?","options":[{"id":"a","text":"Presence of mood symptoms"},{"id":"b","text":"Duration of psychotic symptoms"},{"id":"c","text":"Psychosis without prominent mood symptoms for ≥2 weeks"},{"id":"d","text":"Response to antipsychotics"}],"answerId":"c","explanation":"Schizoaffective disorder requires ≥2 weeks of psychosis without prominent mood symptoms.","kind":"clinical","origin":"ai"},{"id":"beh-psychotic-disorders~ai-5","moduleId":"beh-psychotic-disorders","stem":"A patient with schizophrenia is being evaluated for antipsychotic treatment. Which symptom is most likely to improve with dopamine-blocking agents?","options":[{"id":"a","text":"Affective flattening"},{"id":"b","text":"Alogia"},{"id":"c","text":"Delusions"},{"id":"d","text":"Anhedonia"}],"answerId":"c","explanation":"Delusions are positive symptoms that typically respond well to dopamine-blocking antipsychotics.","kind":"integration","linkedModuleIds":["add-pharmacology-of-antipsychotic-agents"],"origin":"ai"},{"id":"beh-psychotic-disorders~ai-6","moduleId":"beh-psychotic-disorders","stem":"During a mental status examination, a patient exhibits disorganized speech. Which module provides foundational knowledge for assessing this symptom?","options":[{"id":"a","text":"Pharmacology of Antipsychotic Agents"},{"id":"b","text":"The Mental Status Examination"},{"id":"c","text":"Neurobiology of Behavior"},{"id":"d","text":"Aggression, Agitation & De-escalation"}],"answerId":"b","explanation":"The Mental Status Examination module provides the foundational knowledge for assessing disorganized speech.","kind":"integration","linkedModuleIds":["beh-mental-status-exam"],"origin":"ai"}],"beh-mood-anxiety-disorders":[{"id":"beh-mood-anxiety-disorders~ai-0","moduleId":"beh-mood-anxiety-disorders","stem":"A 30-year-old woman presents with a 3-week history of depressed mood, loss of interest in activities, insomnia, fatigue, and feelings of worthlessness. She denies any manic episodes. What is the most likely diagnosis?","options":[{"id":"a","text":"Major depressive disorder"},{"id":"b","text":"Bipolar I disorder"},{"id":"c","text":"Bipolar II disorder"},{"id":"d","text":"Cyclothymic disorder"}],"answerId":"a","explanation":"The patient meets the criteria for a major depressive episode with no history of manic or hypomanic episodes, indicating major depressive disorder.","kind":"clinical","origin":"ai"},{"id":"beh-mood-anxiety-disorders~ai-1","moduleId":"beh-mood-anxiety-disorders","stem":"Which of the following is a core criterion for diagnosing a manic episode according to DSM-5-TR?","options":[{"id":"a","text":"Elevated mood and increased energy/activity"},{"id":"b","text":"Depressed mood and anhedonia"},{"id":"c","text":"Excessive worry and anxiety"},{"id":"d","text":"Recurrent unexpected panic attacks"}],"answerId":"a","explanation":"A manic episode requires elevated/expansive or irritable mood plus increased energy/activity, along with other symptoms.","kind":"recall","origin":"ai"},{"id":"beh-mood-anxiety-disorders~ai-2","moduleId":"beh-mood-anxiety-disorders","stem":"A patient with a history of hypomanic episodes and major depressive episodes is diagnosed with Bipolar II disorder. Which event would change this diagnosis to Bipolar I disorder?","options":[{"id":"a","text":"A single full manic episode"},{"id":"b","text":"An increase in hypomanic episodes"},{"id":"c","text":"A single major depressive episode"},{"id":"d","text":"A single panic attack"}],"answerId":"a","explanation":"A single full manic episode reclassifies the patient as Bipolar I, regardless of any depressive episodes.","kind":"trap","origin":"ai"},{"id":"beh-mood-anxiety-disorders~ai-3","moduleId":"beh-mood-anxiety-disorders","stem":"A 25-year-old man experiences recurrent unexpected panic attacks and has been worried about having more attacks for the past 2 months. Which anxiety disorder is most likely?","options":[{"id":"a","text":"Panic disorder"},{"id":"b","text":"Generalized anxiety disorder"},{"id":"c","text":"Social anxiety disorder"},{"id":"d","text":"Agoraphobia"}],"answerId":"a","explanation":"Panic disorder is characterized by recurrent unexpected panic attacks and persistent concern about additional attacks.","kind":"clinical","origin":"ai"},{"id":"beh-mood-anxiety-disorders~ai-4","moduleId":"beh-mood-anxiety-disorders","stem":"Which of the following disorders was reclassified in DSM-5-TR and is no longer considered an anxiety disorder?","options":[{"id":"a","text":"Obsessive-compulsive disorder"},{"id":"b","text":"Panic disorder"},{"id":"c","text":"Generalized anxiety disorder"},{"id":"d","text":"Social anxiety disorder"}],"answerId":"a","explanation":"Obsessive-compulsive disorder was moved to its own chapter in DSM-5-TR and is no longer classified as an anxiety disorder.","kind":"recall","origin":"ai"},{"id":"beh-mood-anxiety-disorders~ai-5","moduleId":"beh-mood-anxiety-disorders","stem":"A patient with Bipolar I disorder is prescribed lithium. Which linked module would provide detailed information about this treatment?","options":[{"id":"a","text":"Mood Stabilizers & Bipolar Disorder"},{"id":"b","text":"Sedative-Hypnotics & Benzodiazepines"},{"id":"c","text":"Grief, Mourning & Bereavement"},{"id":"d","text":"Abuse & Neglect: Recognition & Reporting"}],"answerId":"a","explanation":"The 'Mood Stabilizers & Bipolar Disorder' module covers treatments like lithium for bipolar disorder.","kind":"integration","linkedModuleIds":["mood-stabilizers-bipolar"],"origin":"ai"},{"id":"beh-mood-anxiety-disorders~ai-6","moduleId":"beh-mood-anxiety-disorders","stem":"A 40-year-old woman is experiencing intense grief after the loss of her spouse. How can this be differentiated from a major depressive episode?","options":[{"id":"a","text":"Grief involves waves of sadness, while MDE involves persistent low mood"},{"id":"b","text":"Grief includes anhedonia, while MDE does not"},{"id":"c","text":"Grief lasts longer than MDE"},{"id":"d","text":"Grief is associated with suicidal ideation, while MDE is not"}],"answerId":"a","explanation":"Grief typically involves waves of sadness and longing, while a major depressive episode involves a persistent low mood.","kind":"integration","linkedModuleIds":["beh-grief-bereavement"],"origin":"ai"}],"beh-other-major-disorders":[{"id":"beh-other-major-disorders~ai-0","moduleId":"beh-other-major-disorders","stem":"Which of the following disorders is classified under the obsessive-compulsive and related disorders in DSM-5-TR?","options":[{"id":"a","text":"Body dysmorphic disorder"},{"id":"b","text":"Post-traumatic stress disorder"},{"id":"c","text":"Generalized anxiety disorder"},{"id":"d","text":"Major depressive disorder"}],"answerId":"a","explanation":"Body dysmorphic disorder is categorized under obsessive-compulsive and related disorders in DSM-5-TR.","kind":"recall","origin":"ai"},{"id":"beh-other-major-disorders~ai-1","moduleId":"beh-other-major-disorders","stem":"A patient presents with persistent intrusive thoughts about contamination and engages in excessive handwashing. Which characteristic best describes these obsessions?","options":[{"id":"a","text":"Ego-syntonic"},{"id":"b","text":"Ego-dystonic"},{"id":"c","text":"Ego-centric"},{"id":"d","text":"Ego-involved"}],"answerId":"b","explanation":"Obsessions in OCD are ego-dystonic, meaning they are intrusive and unwanted.","kind":"mechanism","origin":"ai"},{"id":"beh-other-major-disorders~ai-2","moduleId":"beh-other-major-disorders","stem":"In DSM-5-TR, which of the following is NOT a criterion for diagnosing a disorder?","options":[{"id":"a","text":"Presence of a syndrome"},{"id":"b","text":"Duration of symptoms"},{"id":"c","text":"Clinically significant distress or impairment"},{"id":"d","text":"Symptoms must be medically unexplained"}],"answerId":"d","explanation":"DSM-5-TR does not require symptoms to be medically unexplained for diagnosis.","kind":"trap","origin":"ai"},{"id":"beh-other-major-disorders~ai-3","moduleId":"beh-other-major-disorders","stem":"Which of the following changes in DSM-5-TR classification is correctly stated?","options":[{"id":"a","text":"OCD is now classified under anxiety disorders"},{"id":"b","text":"PTSD is now classified under mood disorders"},{"id":"c","text":"OCD is classified under obsessive-compulsive and related disorders"},{"id":"d","text":"PTSD is classified under somatic symptom disorders"}],"answerId":"c","explanation":"OCD is classified under obsessive-compulsive and related disorders in DSM-5-TR.","kind":"trap","origin":"ai"},{"id":"beh-other-major-disorders~ai-4","moduleId":"beh-other-major-disorders","stem":"A patient with PTSD is experiencing flashbacks and hypervigilance. Which cluster of PTSD symptoms do these belong to?","options":[{"id":"a","text":"Intrusion and arousal"},{"id":"b","text":"Avoidance and mood alteration"},{"id":"c","text":"Mood alteration and arousal"},{"id":"d","text":"Intrusion and avoidance"}],"answerId":"a","explanation":"Flashbacks are part of the intrusion cluster, and hypervigilance is part of the arousal cluster in PTSD.","kind":"clinical","origin":"ai"},{"id":"beh-other-major-disorders~ai-5","moduleId":"beh-other-major-disorders","stem":"How does the DSM-5-TR classification of substance-related disorders differ from previous editions?","options":[{"id":"a","text":"Substance abuse and dependence are separate disorders"},{"id":"b","text":"Substance use disorder is a single spectrum"},{"id":"c","text":"Only severe use is classified as a disorder"},{"id":"d","text":"Substance-related disorders are now under mood disorders"}],"answerId":"b","explanation":"DSM-5-TR combines substance abuse and dependence into a single spectrum of substance use disorder.","kind":"mechanism","origin":"ai"},{"id":"beh-other-major-disorders~ai-6","moduleId":"beh-other-major-disorders","stem":"Which of the following is a common feature of both PTSD and acute stress disorder?","options":[{"id":"a","text":"Symptoms last more than 6 months"},{"id":"b","text":"Exposure to a traumatic event"},{"id":"c","text":"Symptoms include compulsive behaviors"},{"id":"d","text":"Symptoms are ego-syntonic"}],"answerId":"b","explanation":"Both PTSD and acute stress disorder require exposure to a traumatic event.","kind":"integration","linkedModuleIds":["beh-abuse-neglect"],"origin":"ai"},{"id":"beh-other-major-disorders~ai-7","moduleId":"beh-other-major-disorders","stem":"A child diagnosed with ADHD is also being evaluated for autism spectrum disorder. Which module provides foundational knowledge for understanding these neurodevelopmental disorders?","options":[{"id":"a","text":"Endocrine Signaling & Major Endocrine Glands"},{"id":"b","text":"Abuse & Neglect: Recognition & Reporting"},{"id":"c","text":"Mood & Anxiety Disorders (DSM-5-TR)"},{"id":"d","text":"Development Principles"}],"answerId":"d","explanation":"The module on Development Principles provides foundational knowledge for neurodevelopmental disorders like ADHD and autism.","kind":"integration","origin":"ai"}],"beh-behavioral-genetics":[{"id":"beh-behavioral-genetics~ai-0","moduleId":"beh-behavioral-genetics","stem":"Which of the following best describes the concept of heritability in behavioral genetics?","options":[{"id":"a","text":"The proportion of a trait in an individual that is genetic"},{"id":"b","text":"The proportion of variance in a population trait explained by genetic variance"},{"id":"c","text":"The likelihood that a trait will be passed from parent to offspring"},{"id":"d","text":"The percentage of a trait that is determined by environmental factors"}],"answerId":"b","explanation":"Heritability measures the proportion of variance in a trait within a population that is due to genetic differences.","kind":"recall","origin":"ai"},{"id":"beh-behavioral-genetics~ai-1","moduleId":"beh-behavioral-genetics","stem":"In a study comparing monozygotic and dizygotic twins, a higher concordance rate for a specific trait in monozygotic twins suggests what?","options":[{"id":"a","text":"The trait is primarily influenced by environmental factors"},{"id":"b","text":"The trait has a significant genetic component"},{"id":"c","text":"The trait is not influenced by genetic factors"},{"id":"d","text":"The trait is equally influenced by genetics and environment"}],"answerId":"b","explanation":"Higher concordance in monozygotic twins indicates a genetic contribution because they share more genetic material than dizygotic twins.","kind":"mechanism","origin":"ai"},{"id":"beh-behavioral-genetics~ai-2","moduleId":"beh-behavioral-genetics","stem":"Which of the following scenarios best illustrates a gene-environment interaction?","options":[{"id":"a","text":"A person with a genetic predisposition to anxiety develops it after a stressful event"},{"id":"b","text":"A person with no family history of depression develops it after a traumatic event"},{"id":"c","text":"A person with a genetic predisposition to obesity remains healthy through diet and exercise"},{"id":"d","text":"A person with a genetic predisposition to diabetes develops it without any lifestyle changes"}],"answerId":"a","explanation":"Gene-environment interaction occurs when genetic predisposition and environmental factors together influence the development of a trait.","kind":"clinical","origin":"ai"},{"id":"beh-behavioral-genetics~ai-3","moduleId":"beh-behavioral-genetics","stem":"Which of the following best describes the role of epigenetics in behavioral genetics?","options":[{"id":"a","text":"Epigenetics changes the DNA sequence to alter gene expression"},{"id":"b","text":"Epigenetics involves permanent changes to the genetic code"},{"id":"c","text":"Epigenetics involves reversible changes in gene expression without altering the DNA sequence"},{"id":"d","text":"Epigenetics has no impact on gene expression"}],"answerId":"c","explanation":"Epigenetics involves reversible modifications, such as methylation, that affect gene expression without changing the DNA sequence.","kind":"mechanism","origin":"ai"},{"id":"beh-behavioral-genetics~ai-4","moduleId":"beh-behavioral-genetics","stem":"A patient with a family history of schizophrenia develops the disorder after experiencing a significant life stressor. Which model best explains this occurrence?","options":[{"id":"a","text":"Gene-environment correlation"},{"id":"b","text":"Diathesis-stress model"},{"id":"c","text":"Environmental determinism"},{"id":"d","text":"Genetic determinism"}],"answerId":"b","explanation":"The diathesis-stress model explains how genetic vulnerability combined with environmental stressors can lead to the development of a disorder.","kind":"clinical","origin":"ai"},{"id":"beh-behavioral-genetics~ai-5","moduleId":"beh-behavioral-genetics","stem":"How does the diathesis-stress model integrate with the understanding of mood disorders?","options":[{"id":"a","text":"It suggests mood disorders are solely caused by genetic factors"},{"id":"b","text":"It proposes that environmental factors alone trigger mood disorders"},{"id":"c","text":"It explains that genetic predisposition and environmental stressors together contribute to mood disorders"},{"id":"d","text":"It indicates that mood disorders are unrelated to genetic or environmental factors"}],"answerId":"c","explanation":"The diathesis-stress model integrates genetic predisposition with environmental stressors to explain the onset of mood disorders.","kind":"integration","linkedModuleIds":["beh-mood-anxiety-disorders"],"origin":"ai"},{"id":"beh-behavioral-genetics~ai-6","moduleId":"beh-behavioral-genetics","stem":"In the context of psychotic disorders, how does the diathesis-stress model apply?","options":[{"id":"a","text":"Psychotic disorders are purely genetic"},{"id":"b","text":"Environmental stressors alone cause psychotic disorders"},{"id":"c","text":"A genetic vulnerability combined with environmental stress leads to psychotic disorders"},{"id":"d","text":"Psychotic disorders are unrelated to genetic or environmental factors"}],"answerId":"c","explanation":"The diathesis-stress model applies to psychotic disorders by explaining how genetic vulnerability and environmental stressors interact to trigger the disorder.","kind":"integration","linkedModuleIds":["beh-psychotic-disorders"],"origin":"ai"}],"beh-erikson-psychosocial":[{"id":"beh-erikson-psychosocial~ai-0","moduleId":"beh-erikson-psychosocial","stem":"Which virtue is associated with successfully resolving the psychosocial crisis of 'initiative vs guilt'?","options":[{"id":"a","text":"Hope"},{"id":"b","text":"Will"},{"id":"c","text":"Purpose"},{"id":"d","text":"Competence"}],"answerId":"c","explanation":"The virtue associated with resolving 'initiative vs guilt' is purpose, which emerges during the preschool years.","kind":"recall","origin":"ai"},{"id":"beh-erikson-psychosocial~ai-1","moduleId":"beh-erikson-psychosocial","stem":"In Erikson's psychosocial stages, what is the primary crisis faced during adolescence?","options":[{"id":"a","text":"Trust vs mistrust"},{"id":"b","text":"Autonomy vs shame/doubt"},{"id":"c","text":"Identity vs role confusion"},{"id":"d","text":"Intimacy vs isolation"}],"answerId":"c","explanation":"Adolescence is characterized by the crisis of identity vs role confusion, where the individual seeks to form a stable identity.","kind":"recall","origin":"ai"},{"id":"beh-erikson-psychosocial~ai-2","moduleId":"beh-erikson-psychosocial","stem":"What is the main difference between Erikson's and Freud's developmental stages?","options":[{"id":"a","text":"Erikson's stages are psychosexual and end at puberty"},{"id":"b","text":"Freud's stages are psychosocial and span the entire lifespan"},{"id":"c","text":"Erikson's stages are psychosocial and span the entire lifespan"},{"id":"d","text":"Freud's stages are psychosocial and end at puberty"}],"answerId":"c","explanation":"Erikson's stages are psychosocial and continue across the entire lifespan, unlike Freud's psychosexual stages which end at puberty.","kind":"trap","origin":"ai"},{"id":"beh-erikson-psychosocial~ai-3","moduleId":"beh-erikson-psychosocial","stem":"Which psychosocial stage involves the crisis of 'integrity vs despair'?","options":[{"id":"a","text":"Young adulthood"},{"id":"b","text":"Middle adulthood"},{"id":"c","text":"Late adulthood"},{"id":"d","text":"Adolescence"}],"answerId":"c","explanation":"The crisis of 'integrity vs despair' occurs in late adulthood, focusing on life review and acceptance.","kind":"recall","origin":"ai"},{"id":"beh-erikson-psychosocial~ai-4","moduleId":"beh-erikson-psychosocial","stem":"How does Erikson's stage of 'identity vs role confusion' relate to Piaget's theory?","options":[{"id":"a","text":"Both focus on early childhood development"},{"id":"b","text":"Both emphasize the role of social relationships in adolescence"},{"id":"c","text":"Both theories end at puberty"},{"id":"d","text":"Both focus on cognitive development in adulthood"}],"answerId":"b","explanation":"Both Erikson and Piaget emphasize the importance of social relationships and identity formation during adolescence.","kind":"integration","linkedModuleIds":["beh-piaget-attachment"],"origin":"ai"},{"id":"beh-erikson-psychosocial~ai-5","moduleId":"beh-erikson-psychosocial","stem":"Which stage of Erikson's psychosocial development is most relevant to understanding the challenges of aging?","options":[{"id":"a","text":"Identity vs role confusion"},{"id":"b","text":"Intimacy vs isolation"},{"id":"c","text":"Generativity vs stagnation"},{"id":"d","text":"Integrity vs despair"}],"answerId":"d","explanation":"The stage 'integrity vs despair' is most relevant to aging, focusing on life review and acceptance.","kind":"integration","linkedModuleIds":["beh-aging-life-cycle"],"origin":"ai"},{"id":"beh-erikson-psychosocial~ai-6","moduleId":"beh-erikson-psychosocial","stem":"What is the virtue gained from successfully resolving the 'trust vs mistrust' stage?","options":[{"id":"a","text":"Hope"},{"id":"b","text":"Will"},{"id":"c","text":"Purpose"},{"id":"d","text":"Fidelity"}],"answerId":"a","explanation":"The virtue gained from resolving 'trust vs mistrust' is hope, which is developed during infancy.","kind":"recall","origin":"ai"}],"beh-neurobiology-behavior":[{"id":"beh-neurobiology-behavior~ai-0","moduleId":"beh-neurobiology-behavior","stem":"Which brain structure is primarily responsible for assigning emotional salience and driving fear conditioning?","options":[{"id":"a","text":"Amygdala"},{"id":"b","text":"Hippocampus"},{"id":"c","text":"Prefrontal cortex"},{"id":"d","text":"Hypothalamus"}],"answerId":"a","explanation":"The amygdala is central to fear and threat processing by assigning emotional salience.","kind":"recall","origin":"ai"},{"id":"beh-neurobiology-behavior~ai-1","moduleId":"beh-neurobiology-behavior","stem":"What is the primary role of the prefrontal cortex in behavior modulation?","options":[{"id":"a","text":"Enhancing limbic reactivity"},{"id":"b","text":"Top-down inhibition of limbic drives"},{"id":"c","text":"Consolidating memory"},{"id":"d","text":"Regulating primal drives"}],"answerId":"b","explanation":"The prefrontal cortex exerts top-down inhibition over limbic drives, affecting judgement and impulse control.","kind":"mechanism","origin":"ai"},{"id":"beh-neurobiology-behavior~ai-2","moduleId":"beh-neurobiology-behavior","stem":"A patient presents with impulsivity and poor judgement following a traumatic brain injury. Which brain region is most likely affected?","options":[{"id":"a","text":"Hippocampus"},{"id":"b","text":"Amygdala"},{"id":"c","text":"Prefrontal cortex"},{"id":"d","text":"Hypothalamus"}],"answerId":"c","explanation":"Damage to the prefrontal cortex can lead to disinhibition and poor judgement.","kind":"clinical","origin":"ai"},{"id":"beh-neurobiology-behavior~ai-3","moduleId":"beh-neurobiology-behavior","stem":"Which neurotransmitter is primarily associated with mood regulation and impulse control, and is often targeted in the treatment of depression?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"Serotonin"},{"id":"c","text":"Noradrenaline"},{"id":"d","text":"GABA"}],"answerId":"b","explanation":"Serotonin modulates mood and impulse control; low levels are linked to depression.","kind":"recall","origin":"ai"},{"id":"beh-neurobiology-behavior~ai-4","moduleId":"beh-neurobiology-behavior","stem":"In the context of psychotic disorders, why might antipsychotic medications lead to Parkinsonian side effects?","options":[{"id":"a","text":"They increase dopamine in the nigrostriatal pathway"},{"id":"b","text":"They decrease dopamine in the mesolimbic pathway"},{"id":"c","text":"They decrease dopamine in the nigrostriatal pathway"},{"id":"d","text":"They increase serotonin in the limbic system"}],"answerId":"c","explanation":"Antipsychotics can cause Parkinsonian side-effects by decreasing dopamine in the nigrostriatal pathway.","kind":"trap","origin":"ai"},{"id":"beh-neurobiology-behavior~ai-5","moduleId":"beh-neurobiology-behavior","stem":"Which neurotransmitter system is primarily involved in the fight-or-flight response?","options":[{"id":"a","text":"Dopamine"},{"id":"b","text":"Serotonin"},{"id":"c","text":"Noradrenaline"},{"id":"d","text":"GABA"}],"answerId":"c","explanation":"Noradrenaline is involved in arousal and alertness, key components of the fight-or-flight response.","kind":"recall","origin":"ai"},{"id":"beh-neurobiology-behavior~ai-6","moduleId":"beh-neurobiology-behavior","stem":"How does the limbic system interact with the hypothalamus to influence behavior?","options":[{"id":"a","text":"The limbic system inhibits hypothalamic activity"},{"id":"b","text":"The hypothalamus modulates limbic emotional responses"},{"id":"c","text":"The limbic system drives primal behaviors via the hypothalamus"},{"id":"d","text":"The hypothalamus consolidates memory with limbic input"}],"answerId":"c","explanation":"The limbic system influences primal drives such as hunger and stress via the hypothalamus.","kind":"integration","linkedModuleIds":["limbic-hypothalamus"],"origin":"ai"},{"id":"beh-neurobiology-behavior~ai-7","moduleId":"beh-neurobiology-behavior","stem":"In the context of the stress response, which brain structure is primarily responsible for initiating the HPA axis?","options":[{"id":"a","text":"Amygdala"},{"id":"b","text":"Hippocampus"},{"id":"c","text":"Prefrontal cortex"},{"id":"d","text":"Hypothalamus"}],"answerId":"d","explanation":"The hypothalamus initiates the HPA axis, a key component of the stress response.","kind":"integration","linkedModuleIds":["beh-stress-response"],"origin":"ai"}],"beh-development-principles":[{"id":"beh-development-principles~ai-0","moduleId":"beh-development-principles","stem":"Which of the following best describes the cephalocaudal pattern of development?","options":[{"id":"a","text":"Development proceeds from head to toe."},{"id":"b","text":"Development proceeds from the center to the periphery."},{"id":"c","text":"Development occurs in a random sequence."},{"id":"d","text":"Development is solely based on environmental factors."}],"answerId":"a","explanation":"Cephalocaudal development refers to the head-to-toe progression of growth and skill acquisition.","kind":"recall","origin":"ai"},{"id":"beh-development-principles~ai-1","moduleId":"beh-development-principles","stem":"A 2-year-old child can walk but has not yet started speaking single words. What should be the next step?","options":[{"id":"a","text":"Reassure the parents and wait for further development."},{"id":"b","text":"Refer for a developmental evaluation."},{"id":"c","text":"Start speech therapy immediately."},{"id":"d","text":"Check hearing and then reassess in 6 months."}],"answerId":"b","explanation":"A significant lag in language development, such as not speaking single words by 18-24 months, warrants a developmental evaluation.","kind":"clinical","origin":"ai"},{"id":"beh-development-principles~ai-2","moduleId":"beh-development-principles","stem":"Which of the following statements about growth and development is correct?","options":[{"id":"a","text":"Growth and development are interchangeable terms."},{"id":"b","text":"Growth is a qualitative increase in function."},{"id":"c","text":"Development is a quantitative increase in size."},{"id":"d","text":"Growth is quantitative, and development is qualitative."}],"answerId":"d","explanation":"Growth refers to the quantitative increase in size, while development refers to the qualitative acquisition of new functions and skills.","kind":"trap","origin":"ai"},{"id":"beh-development-principles~ai-3","moduleId":"beh-development-principles","stem":"A child with a 'difficult' temperament according to Thomas and Chess can thrive under which condition?","options":[{"id":"a","text":"Strict and unyielding parenting."},{"id":"b","text":"A well-matched caregiving environment."},{"id":"c","text":"Minimal parental interaction."},{"id":"d","text":"High-stress home environment."}],"answerId":"b","explanation":"A difficult temperament can thrive if there is a goodness of fit between the child's temperament and the caregiving environment.","kind":"mechanism","origin":"ai"},{"id":"beh-development-principles~ai-4","moduleId":"beh-development-principles","stem":"Which developmental milestone is typically achieved first in infants?","options":[{"id":"a","text":"Walking independently"},{"id":"b","text":"Sitting without support"},{"id":"c","text":"Fine pincer grasp"},{"id":"d","text":"Speaking in sentences"}],"answerId":"b","explanation":"Sitting without support is typically achieved before walking, fine pincer grasp, or speaking in sentences.","kind":"recall","origin":"ai"},{"id":"beh-development-principles~ai-5","moduleId":"beh-development-principles","stem":"How does Erikson’s psychosocial theory integrate with principles of development?","options":[{"id":"a","text":"It focuses solely on physical growth."},{"id":"b","text":"It describes stages of personality development influenced by social interactions."},{"id":"c","text":"It only applies to cognitive development."},{"id":"d","text":"It disregards the role of temperament."}],"answerId":"b","explanation":"Erikson's theory describes stages of personality development influenced by social interactions, integrating with developmental principles.","kind":"integration","linkedModuleIds":["beh-erikson-psychosocial"],"origin":"ai"},{"id":"beh-development-principles~ai-6","moduleId":"beh-development-principles","stem":"How might family dynamics influence a child's developmental trajectory?","options":[{"id":"a","text":"Family dynamics have no impact on development."},{"id":"b","text":"A supportive family environment can enhance developmental outcomes."},{"id":"c","text":"Family dynamics only affect physical growth."},{"id":"d","text":"Development is predetermined and unaffected by family."}],"answerId":"b","explanation":"A supportive family environment can enhance developmental outcomes, showing the influence of family dynamics on development.","kind":"integration","linkedModuleIds":["beh-family-dynamics"],"origin":"ai"}],"beh-piaget-attachment":[{"id":"beh-piaget-attachment~ai-0","moduleId":"beh-piaget-attachment","stem":"In which Piagetian stage does a child typically achieve object permanence?","options":[{"id":"a","text":"Sensorimotor"},{"id":"b","text":"Preoperational"},{"id":"c","text":"Concrete operational"},{"id":"d","text":"Formal operational"}],"answerId":"a","explanation":"Object permanence is a hallmark of the sensorimotor stage, where infants learn that objects continue to exist even when out of sight.","kind":"recall","origin":"ai"},{"id":"beh-piaget-attachment~ai-1","moduleId":"beh-piaget-attachment","stem":"Which attachment style is characterized by a child using the caregiver as a secure base and being comforted upon reunion?","options":[{"id":"a","text":"Secure"},{"id":"b","text":"Insecure-avoidant"},{"id":"c","text":"Insecure-ambivalent"},{"id":"d","text":"Disorganized"}],"answerId":"a","explanation":"In the secure attachment style, the child uses the caregiver as a secure base and is comforted when reunited.","kind":"recall","origin":"ai"},{"id":"beh-piaget-attachment~ai-2","moduleId":"beh-piaget-attachment","stem":"A child believes that the amount of liquid changes when poured into a differently shaped container. Which Piagetian stage does this child most likely belong to?","options":[{"id":"a","text":"Sensorimotor"},{"id":"b","text":"Preoperational"},{"id":"c","text":"Concrete operational"},{"id":"d","text":"Formal operational"}],"answerId":"b","explanation":"In the preoperational stage, children lack the concept of conservation, believing that quantity changes with shape.","kind":"mechanism","origin":"ai"},{"id":"beh-piaget-attachment~ai-3","moduleId":"beh-piaget-attachment","stem":"Which of the following is a common misunderstanding about Piaget’s stages?","options":[{"id":"a","text":"Object permanence and conservation are the same milestone"},{"id":"b","text":"Egocentrism is a feature of preoperational thought"},{"id":"c","text":"Formal operational stage involves abstract reasoning"},{"id":"d","text":"Concrete operational stage involves logical reversibility"}],"answerId":"a","explanation":"Object permanence and conservation are distinct milestones in different stages; object permanence is in the sensorimotor stage, while conservation is in the concrete operational stage.","kind":"trap","origin":"ai"},{"id":"beh-piaget-attachment~ai-4","moduleId":"beh-piaget-attachment","stem":"During which phase of Mahler's separation–individuation process does an infant develop a stable inner image of the caregiver?","options":[{"id":"a","text":"Symbiotic phase"},{"id":"b","text":"Practicing subphase"},{"id":"c","text":"Rapprochement subphase"},{"id":"d","text":"Object constancy phase"}],"answerId":"d","explanation":"The object constancy phase involves developing a stable inner image of the caregiver, allowing the child to maintain an emotional bond even when apart.","kind":"recall","origin":"ai"},{"id":"beh-piaget-attachment~ai-5","moduleId":"beh-piaget-attachment","stem":"How does the concept of object permanence relate to Erikson's stages of psychosocial development?","options":[{"id":"a","text":"Trust vs. Mistrust"},{"id":"b","text":"Autonomy vs. Shame"},{"id":"c","text":"Initiative vs. Guilt"},{"id":"d","text":"Industry vs. Inferiority"}],"answerId":"a","explanation":"Object permanence supports the development of trust in the Trust vs. Mistrust stage, as the infant learns that caregivers continue to exist even when not visible.","kind":"integration","linkedModuleIds":["beh-erikson-psychosocial"],"origin":"ai"},{"id":"beh-piaget-attachment~ai-6","moduleId":"beh-piaget-attachment","stem":"Which communication skill is crucial for assessing attachment styles in clinical settings?","options":[{"id":"a","text":"Active listening"},{"id":"b","text":"Open-ended questioning"},{"id":"c","text":"Reflective listening"},{"id":"d","text":"Empathy expression"}],"answerId":"b","explanation":"Open-ended questioning allows clinicians to gather detailed information about the child's behavior and attachment style.","kind":"integration","linkedModuleIds":["beh-communication-skills"],"origin":"ai"}],"beh-classical-operant-conditioning":[{"id":"beh-classical-operant-conditioning~ai-0","moduleId":"beh-classical-operant-conditioning","stem":"In classical conditioning, what is the term for the reappearance of a conditioned response after a period of rest following extinction?","options":[{"id":"a","text":"Spontaneous recovery"},{"id":"b","text":"Stimulus generalization"},{"id":"c","text":"Acquisition"},{"id":"d","text":"Discrimination"}],"answerId":"a","explanation":"Spontaneous recovery is the return of a conditioned response after a rest period following extinction.","kind":"recall","origin":"ai"},{"id":"beh-classical-operant-conditioning~ai-1","moduleId":"beh-classical-operant-conditioning","stem":"Which schedule of reinforcement is most resistant to extinction?","options":[{"id":"a","text":"Fixed interval"},{"id":"b","text":"Variable ratio"},{"id":"c","text":"Fixed ratio"},{"id":"d","text":"Variable interval"}],"answerId":"b","explanation":"Variable ratio schedules, like those used in gambling, are most resistant to extinction due to their unpredictability.","kind":"mechanism","origin":"ai"},{"id":"beh-classical-operant-conditioning~ai-2","moduleId":"beh-classical-operant-conditioning","stem":"A child receives a sticker for every five books they read. What type of reinforcement schedule is this?","options":[{"id":"a","text":"Fixed ratio"},{"id":"b","text":"Variable ratio"},{"id":"c","text":"Fixed interval"},{"id":"d","text":"Variable interval"}],"answerId":"a","explanation":"A fixed ratio schedule provides reinforcement after a set number of responses, in this case, every five books.","kind":"clinical","origin":"ai"},{"id":"beh-classical-operant-conditioning~ai-3","moduleId":"beh-classical-operant-conditioning","stem":"Which of the following best describes negative reinforcement?","options":[{"id":"a","text":"Adding a pleasant stimulus to increase behavior"},{"id":"b","text":"Removing an aversive stimulus to increase behavior"},{"id":"c","text":"Adding an aversive stimulus to decrease behavior"},{"id":"d","text":"Removing a pleasant stimulus to decrease behavior"}],"answerId":"b","explanation":"Negative reinforcement involves removing an aversive stimulus to increase the likelihood of a behavior.","kind":"trap","origin":"ai"},{"id":"beh-classical-operant-conditioning~ai-4","moduleId":"beh-classical-operant-conditioning","stem":"A patient with a phobia of dogs undergoes systematic desensitization. This treatment is based on principles from which type of conditioning?","options":[{"id":"a","text":"Classical conditioning"},{"id":"b","text":"Operant conditioning"},{"id":"c","text":"Observational learning"},{"id":"d","text":"Cognitive restructuring"}],"answerId":"a","explanation":"Systematic desensitization is based on classical conditioning, where the fear response is gradually extinguished.","kind":"integration","linkedModuleIds":["beh-mood-anxiety-disorders"],"origin":"ai"},{"id":"beh-classical-operant-conditioning~ai-5","moduleId":"beh-classical-operant-conditioning","stem":"Which concept explains why a person continues to play slot machines despite frequent losses?","options":[{"id":"a","text":"Fixed interval schedule"},{"id":"b","text":"Variable ratio schedule"},{"id":"c","text":"Fixed ratio schedule"},{"id":"d","text":"Variable interval schedule"}],"answerId":"b","explanation":"The variable ratio schedule, where rewards are given after an unpredictable number of responses, explains persistent gambling behavior.","kind":"integration","linkedModuleIds":["beh-neurobiology-behavior"],"origin":"ai"}],"beh-family-psychopathology":[{"id":"beh-family-psychopathology~ai-0","moduleId":"beh-family-psychopathology","stem":"Which family dynamic is characterized by diffuse boundaries and over-involvement, often seen in families with psychosomatic and eating disorders?","options":[{"id":"a","text":"Enmeshment"},{"id":"b","text":"Triangulation"},{"id":"c","text":"Scapegoating"},{"id":"d","text":"Expressed Emotion"}],"answerId":"a","explanation":"Enmeshment involves over-close relationships that suppress individuation, commonly seen in psychosomatic and eating disorder families.","kind":"recall","origin":"ai"},{"id":"beh-family-psychopathology~ai-1","moduleId":"beh-family-psychopathology","stem":"What is the primary role of Expressed Emotion (EE) in the context of schizophrenia?","options":[{"id":"a","text":"Causes schizophrenia"},{"id":"b","text":"Predicts relapse"},{"id":"c","text":"Cures schizophrenia"},{"id":"d","text":"Prevents onset"}],"answerId":"b","explanation":"High EE predicts relapse in schizophrenia by increasing stress arousal in vulnerable patients.","kind":"mechanism","origin":"ai"},{"id":"beh-family-psychopathology~ai-2","moduleId":"beh-family-psychopathology","stem":"A family with high Expressed Emotion is most likely to affect which aspect of a mental disorder?","options":[{"id":"a","text":"Onset"},{"id":"b","text":"Severity"},{"id":"c","text":"Relapse"},{"id":"d","text":"Diagnosis"}],"answerId":"c","explanation":"High EE strongly predicts relapse rather than onset or severity.","kind":"trap","origin":"ai"},{"id":"beh-family-psychopathology~ai-3","moduleId":"beh-family-psychopathology","stem":"In a family system, which dynamic involves a child being recruited to stabilize or defuse parental tension?","options":[{"id":"a","text":"Enmeshment"},{"id":"b","text":"Triangulation"},{"id":"c","text":"Scapegoating"},{"id":"d","text":"Expressed Emotion"}],"answerId":"b","explanation":"Triangulation involves a child being drawn into parental conflicts to stabilize or defuse tension.","kind":"recall","origin":"ai"},{"id":"beh-family-psychopathology~ai-4","moduleId":"beh-family-psychopathology","stem":"How does high Expressed Emotion (EE) interact with genetic vulnerability in mental disorders?","options":[{"id":"a","text":"EE causes genetic mutations"},{"id":"b","text":"EE triggers onset in genetically vulnerable individuals"},{"id":"c","text":"EE has no interaction with genetics"},{"id":"d","text":"EE predicts better outcomes in genetically vulnerable individuals"}],"answerId":"b","explanation":"High EE acts as an environmental trigger in a diathesis-stress model, affecting those with genetic vulnerability.","kind":"integration","linkedModuleIds":["beh-behavioral-genetics"],"origin":"ai"},{"id":"beh-family-psychopathology~ai-5","moduleId":"beh-family-psychopathology","stem":"Which family dynamic involves designating one member as the 'identified patient' who carries the blame for family issues?","options":[{"id":"a","text":"Enmeshment"},{"id":"b","text":"Triangulation"},{"id":"c","text":"Scapegoating"},{"id":"d","text":"Expressed Emotion"}],"answerId":"c","explanation":"Scapegoating designates one member as the 'identified patient', stabilizing the dysfunctional system.","kind":"recall","origin":"ai"},{"id":"beh-family-psychopathology~ai-6","moduleId":"beh-family-psychopathology","stem":"In the context of mood disorders, how might reducing Expressed Emotion in a family affect the patient?","options":[{"id":"a","text":"Increase symptom severity"},{"id":"b","text":"Reduce relapse rates"},{"id":"c","text":"Cause new symptoms"},{"id":"d","text":"Worsen prognosis"}],"answerId":"b","explanation":"Reducing EE can lower relapse rates in mood disorders by decreasing stress arousal.","kind":"integration","linkedModuleIds":["beh-mood-anxiety-disorders"],"origin":"ai"}],"beh-humanistic-theory":[{"id":"beh-humanistic-theory~ai-0","moduleId":"beh-humanistic-theory","stem":"According to Maslow's hierarchy of needs, which need must be addressed before esteem needs can be fully pursued?","options":[{"id":"a","text":"Safety"},{"id":"b","text":"Self-actualization"},{"id":"c","text":"Belonging"},{"id":"d","text":"Physiological"}],"answerId":"a","explanation":"Safety needs must be reasonably met before higher needs like esteem can strongly motivate.","kind":"recall","origin":"ai"},{"id":"beh-humanistic-theory~ai-1","moduleId":"beh-humanistic-theory","stem":"What is the primary focus of Rogers' person-centred therapy?","options":[{"id":"a","text":"Behavior modification"},{"id":"b","text":"Unconditional positive regard"},{"id":"c","text":"Cognitive restructuring"},{"id":"d","text":"Dream analysis"}],"answerId":"b","explanation":"Rogers emphasizes unconditional positive regard, empathy, and congruence to foster personal growth.","kind":"recall","origin":"ai"},{"id":"beh-humanistic-theory~ai-2","moduleId":"beh-humanistic-theory","stem":"A patient feels distressed because they are not living up to their own expectations. According to Rogers, what is this an example of?","options":[{"id":"a","text":"Self-actualization"},{"id":"b","text":"Incongruence"},{"id":"c","text":"Condition of worth"},{"id":"d","text":"Deficiency need"}],"answerId":"b","explanation":"Incongruence arises when there is a gap between the real self and the ideal self.","kind":"mechanism","origin":"ai"},{"id":"beh-humanistic-theory~ai-3","moduleId":"beh-humanistic-theory","stem":"Which of the following is NOT a core condition in Rogers' person-centred therapy?","options":[{"id":"a","text":"Unconditional positive regard"},{"id":"b","text":"Accurate empathy"},{"id":"c","text":"Congruence"},{"id":"d","text":"Behavioral reinforcement"}],"answerId":"d","explanation":"Behavioral reinforcement is not part of Rogers' core conditions; it is related to behaviorism.","kind":"trap","origin":"ai"},{"id":"beh-humanistic-theory~ai-4","moduleId":"beh-humanistic-theory","stem":"In a clinical setting, why is it important to address a patient's physiological needs before engaging in higher-order care?","options":[{"id":"a","text":"To ensure compliance with treatment"},{"id":"b","text":"To prevent legal issues"},{"id":"c","text":"Because unmet lower needs dominate motivation"},{"id":"d","text":"To build rapport"}],"answerId":"c","explanation":"Unmet physiological and safety needs dominate motivation, hindering engagement in higher-order care.","kind":"clinical","origin":"ai"},{"id":"beh-humanistic-theory~ai-5","moduleId":"beh-humanistic-theory","stem":"How does the concept of unconditional positive regard in Rogers' theory relate to the doctor-patient relationship?","options":[{"id":"a","text":"It requires doctors to agree with all patient decisions"},{"id":"b","text":"It involves accepting patients without judgment"},{"id":"c","text":"It focuses on modifying patient behavior"},{"id":"d","text":"It emphasizes the use of medical jargon"}],"answerId":"b","explanation":"Unconditional positive regard involves accepting patients without judgment, fostering a supportive relationship.","kind":"integration","linkedModuleIds":["beh-doctor-patient-relationship"],"origin":"ai"},{"id":"beh-humanistic-theory~ai-6","moduleId":"beh-humanistic-theory","stem":"Which of the following best describes the relationship between Maslow's hierarchy and motivational interviewing in clinical communication?","options":[{"id":"a","text":"Both prioritize self-actualization"},{"id":"b","text":"Both address physiological needs first"},{"id":"c","text":"Both emphasize meeting lower needs to enable higher-order change"},{"id":"d","text":"Both focus on cognitive restructuring"}],"answerId":"c","explanation":"Both approaches emphasize addressing lower needs first to enable higher-order changes and engagement.","kind":"integration","linkedModuleIds":["beh-communication-skills"],"origin":"ai"}],"beh-family-dynamics":[{"id":"beh-family-dynamics~ai-0","moduleId":"beh-family-dynamics","stem":"Which of the following best describes the concept of circular causality in family systems theory?","options":[{"id":"a","text":"A change in one family member affects the entire system."},{"id":"b","text":"Family issues are caused by one member's actions."},{"id":"c","text":"Problems in the family are linear and predictable."},{"id":"d","text":"Each family member operates independently."}],"answerId":"a","explanation":"Circular causality means that changes in one member affect the whole family system, emphasizing interdependence.","kind":"mechanism","origin":"ai"},{"id":"beh-family-dynamics~ai-1","moduleId":"beh-family-dynamics","stem":"In family systems theory, what is the effect of diffuse boundaries between family subsystems?","options":[{"id":"a","text":"Healthy autonomy and closeness"},{"id":"b","text":"Disengagement and isolation"},{"id":"c","text":"Enmeshment and lack of autonomy"},{"id":"d","text":"Clear roles and responsibilities"}],"answerId":"c","explanation":"Diffuse boundaries lead to enmeshment, where family members lack autonomy and personal boundaries.","kind":"mechanism","origin":"ai"},{"id":"beh-family-dynamics~ai-2","moduleId":"beh-family-dynamics","stem":"A family presents with a child exhibiting behavioral issues. According to family systems theory, what should be the primary focus of intervention?","options":[{"id":"a","text":"Addressing the child's behavior directly"},{"id":"b","text":"Exploring the family's communication patterns"},{"id":"c","text":"Isolating the child from family influences"},{"id":"d","text":"Focusing on the parents' relationship only"}],"answerId":"b","explanation":"Family systems theory suggests examining the family's communication and interaction patterns, as the child's behavior may reflect systemic issues.","kind":"trap","origin":"ai"},{"id":"beh-family-dynamics~ai-3","moduleId":"beh-family-dynamics","stem":"Which family subsystem is primarily responsible for providing emotional support and stability?","options":[{"id":"a","text":"Sibling subsystem"},{"id":"b","text":"Parental subsystem"},{"id":"c","text":"Spousal subsystem"},{"id":"d","text":"Extended family subsystem"}],"answerId":"c","explanation":"The spousal subsystem is primarily responsible for providing emotional support and stability within the family.","kind":"recall","origin":"ai"},{"id":"beh-family-dynamics~ai-4","moduleId":"beh-family-dynamics","stem":"During which stage of the family life cycle is a family most likely to experience stress related to role reorganization?","options":[{"id":"a","text":"Couple formation"},{"id":"b","text":"Families with adolescents"},{"id":"c","text":"Launching children"},{"id":"d","text":"Later life"}],"answerId":"c","explanation":"The launching children stage involves significant role reorganization as children leave home, which can be a major stress point.","kind":"clinical","origin":"ai"},{"id":"beh-family-dynamics~ai-5","moduleId":"beh-family-dynamics","stem":"How does the concept of attachment from the Piaget, Attachment & Separation–Individuation module relate to family dynamics?","options":[{"id":"a","text":"Attachment styles influence family subsystem boundaries."},{"id":"b","text":"Attachment is irrelevant to family dynamics."},{"id":"c","text":"Attachment only affects sibling relationships."},{"id":"d","text":"Attachment styles determine family roles."}],"answerId":"a","explanation":"Attachment styles can influence how boundaries are formed and maintained within family subsystems.","kind":"integration","linkedModuleIds":["beh-piaget-attachment"],"origin":"ai"},{"id":"beh-family-dynamics~ai-6","moduleId":"beh-family-dynamics","stem":"In the context of family dynamics, how might principles of growth and development impact family life-cycle transitions?","options":[{"id":"a","text":"They have no impact on family transitions."},{"id":"b","text":"They dictate the timing of transitions."},{"id":"c","text":"They provide a framework for understanding developmental challenges."},{"id":"d","text":"They only affect individual development, not family dynamics."}],"answerId":"c","explanation":"Principles of growth and development help understand the developmental challenges faced during family life-cycle transitions.","kind":"integration","linkedModuleIds":["beh-development-principles"],"origin":"ai"}],"beh-freud-structural-topographic":[{"id":"beh-freud-structural-topographic~ai-0","moduleId":"beh-freud-structural-topographic","stem":"According to Freud's structural model, which component is responsible for mediating between the id and the superego?","options":[{"id":"a","text":"Ego"},{"id":"b","text":"Id"},{"id":"c","text":"Superego"},{"id":"d","text":"Preconscious"}],"answerId":"a","explanation":"The ego mediates between the id's desires and the superego's moral constraints.","kind":"recall","origin":"ai"},{"id":"beh-freud-structural-topographic~ai-1","moduleId":"beh-freud-structural-topographic","stem":"Which of the following is a characteristic of the id according to Freud's structural model?","options":[{"id":"a","text":"Operates on the reality principle"},{"id":"b","text":"Is fully conscious"},{"id":"c","text":"Operates on the pleasure principle"},{"id":"d","text":"Develops around age 5-6"}],"answerId":"c","explanation":"The id operates on the pleasure principle, seeking immediate gratification.","kind":"recall","origin":"ai"},{"id":"beh-freud-structural-topographic~ai-2","moduleId":"beh-freud-structural-topographic","stem":"A patient unconsciously redirects feelings for a parent onto their therapist. This is an example of which psychoanalytic concept?","options":[{"id":"a","text":"Free association"},{"id":"b","text":"Transference"},{"id":"c","text":"Sublimation"},{"id":"d","text":"Projection"}],"answerId":"b","explanation":"Transference involves redirecting feelings from early relationships onto the therapist.","kind":"clinical","origin":"ai"},{"id":"beh-freud-structural-topographic~ai-3","moduleId":"beh-freud-structural-topographic","stem":"Which of the following best describes the preconscious mind in Freud's topographic model?","options":[{"id":"a","text":"Contains repressed wishes and drives"},{"id":"b","text":"Is fully accessible at all times"},{"id":"c","text":"Holds information not currently in awareness but retrievable"},{"id":"d","text":"Is synonymous with the unconscious"}],"answerId":"c","explanation":"The preconscious holds information that is not in current awareness but can be readily retrieved.","kind":"trap","origin":"ai"},{"id":"beh-freud-structural-topographic~ai-4","moduleId":"beh-freud-structural-topographic","stem":"In Freud's theory, which defense mechanism involves unconsciously blocking distressing thoughts from entering awareness?","options":[{"id":"a","text":"Repression"},{"id":"b","text":"Rationalization"},{"id":"c","text":"Displacement"},{"id":"d","text":"Sublimation"}],"answerId":"a","explanation":"Repression involves unconsciously blocking distressing thoughts from awareness.","kind":"mechanism","origin":"ai"},{"id":"beh-freud-structural-topographic~ai-5","moduleId":"beh-freud-structural-topographic","stem":"How does Freud's concept of the superego relate to Erikson's psychosocial stages?","options":[{"id":"a","text":"Superego development aligns with Erikson's trust vs. mistrust stage"},{"id":"b","text":"Superego development aligns with Erikson's initiative vs. guilt stage"},{"id":"c","text":"Superego development aligns with Erikson's industry vs. inferiority stage"},{"id":"d","text":"Superego development aligns with Erikson's identity vs. role confusion stage"}],"answerId":"b","explanation":"The superego forms around age 5-6, aligning with Erikson's initiative vs. guilt stage.","kind":"integration","linkedModuleIds":["beh-erikson-psychosocial"],"origin":"ai"},{"id":"beh-freud-structural-topographic~ai-6","moduleId":"beh-freud-structural-topographic","stem":"In the context of the doctor-patient relationship, how might a patient's unconscious conflicts manifest during therapy?","options":[{"id":"a","text":"Through conscious rationalizations"},{"id":"b","text":"By openly discussing their issues"},{"id":"c","text":"Via transference reactions"},{"id":"d","text":"Through direct communication"}],"answerId":"c","explanation":"Unconscious conflicts often manifest as transference reactions in therapy.","kind":"integration","linkedModuleIds":["beh-doctor-patient-relationship"],"origin":"ai"}],"beh-defense-mechanisms":[{"id":"beh-defense-mechanisms~ai-0","moduleId":"beh-defense-mechanisms","stem":"Which of the following defense mechanisms involves consciously deciding to delay thinking about a stressor until a more appropriate time?","options":[{"id":"a","text":"Suppression"},{"id":"b","text":"Repression"},{"id":"c","text":"Denial"},{"id":"d","text":"Projection"}],"answerId":"a","explanation":"Suppression is the only conscious defense mechanism, involving a deliberate decision to postpone a thought.","kind":"recall","origin":"ai"},{"id":"beh-defense-mechanisms~ai-1","moduleId":"beh-defense-mechanisms","stem":"A patient with borderline personality disorder is most likely to exhibit which defense mechanism?","options":[{"id":"a","text":"Sublimation"},{"id":"b","text":"Splitting"},{"id":"c","text":"Intellectualization"},{"id":"d","text":"Displacement"}],"answerId":"b","explanation":"Splitting, viewing people as all-good or all-bad, is characteristic of borderline personality disorder.","kind":"clinical","origin":"ai"},{"id":"beh-defense-mechanisms~ai-2","moduleId":"beh-defense-mechanisms","stem":"A person who channels aggressive impulses into a career as a professional boxer is using which defense mechanism?","options":[{"id":"a","text":"Reaction formation"},{"id":"b","text":"Sublimation"},{"id":"c","text":"Projection"},{"id":"d","text":"Regression"}],"answerId":"b","explanation":"Sublimation involves channeling unacceptable impulses into socially acceptable activities.","kind":"mechanism","origin":"ai"},{"id":"beh-defense-mechanisms~ai-3","moduleId":"beh-defense-mechanisms","stem":"Which defense mechanism involves attributing one's own unacceptable thoughts to others?","options":[{"id":"a","text":"Projection"},{"id":"b","text":"Displacement"},{"id":"c","text":"Rationalization"},{"id":"d","text":"Denial"}],"answerId":"a","explanation":"Projection involves attributing one's own unacceptable feelings to others, reducing internal conflict.","kind":"recall","origin":"ai"},{"id":"beh-defense-mechanisms~ai-4","moduleId":"beh-defense-mechanisms","stem":"A patient who unconsciously blocks a traumatic event from awareness is using which defense mechanism?","options":[{"id":"a","text":"Suppression"},{"id":"b","text":"Repression"},{"id":"c","text":"Denial"},{"id":"d","text":"Intellectualization"}],"answerId":"b","explanation":"Repression involves the unconscious blocking of distressing thoughts from awareness.","kind":"trap","origin":"ai"},{"id":"beh-defense-mechanisms~ai-5","moduleId":"beh-defense-mechanisms","stem":"How does the defense mechanism of denial differ from repression?","options":[{"id":"a","text":"Denial involves conscious awareness of reality"},{"id":"b","text":"Denial is a mature defense mechanism"},{"id":"c","text":"Denial involves refusal to accept external reality"},{"id":"d","text":"Denial is the same as suppression"}],"answerId":"c","explanation":"Denial involves a refusal to accept external reality, often seen in psychotic defenses.","kind":"trap","origin":"ai"},{"id":"beh-defense-mechanisms~ai-6","moduleId":"beh-defense-mechanisms","stem":"A mother who feels guilty about not breastfeeding might unconsciously believe that other mothers are judging her. Which defense mechanism is this?","options":[{"id":"a","text":"Projection"},{"id":"b","text":"Reaction formation"},{"id":"c","text":"Sublimation"},{"id":"d","text":"Displacement"}],"answerId":"a","explanation":"Projection involves attributing one's own feelings to others, often seen in guilt or anxiety.","kind":"integration","linkedModuleIds":["hrp1-human-milk-composition-benefits"],"origin":"ai"},{"id":"beh-defense-mechanisms~ai-7","moduleId":"beh-defense-mechanisms","stem":"In the context of stress response, which defense mechanism might be employed to manage anxiety by transforming it into a socially acceptable form?","options":[{"id":"a","text":"Regression"},{"id":"b","text":"Sublimation"},{"id":"c","text":"Denial"},{"id":"d","text":"Splitting"}],"answerId":"b","explanation":"Sublimation channels anxiety into productive activities, aligning with stress coping strategies.","kind":"integration","linkedModuleIds":["beh-stress-response"],"origin":"ai"}],"beh-social-cognitive-learning":[{"id":"beh-social-cognitive-learning~ai-0","moduleId":"beh-social-cognitive-learning","stem":"Which of the following is NOT a necessary process for observational learning according to Bandura's social learning theory?","options":[{"id":"a","text":"Attention"},{"id":"b","text":"Reinforcement"},{"id":"c","text":"Retention"},{"id":"d","text":"Motivation"}],"answerId":"b","explanation":"Reinforcement is not necessary for observational learning; the key processes are Attention, Retention, Reproduction, and Motivation.","kind":"recall","origin":"ai"},{"id":"beh-social-cognitive-learning~ai-1","moduleId":"beh-social-cognitive-learning","stem":"A child observes an adult being praised for helping others. The child then starts helping peers more often. Which concept does this illustrate?","options":[{"id":"a","text":"Direct reinforcement"},{"id":"b","text":"Vicarious reinforcement"},{"id":"c","text":"Latent learning"},{"id":"d","text":"Insight learning"}],"answerId":"b","explanation":"Vicarious reinforcement occurs when a learner observes a model being rewarded, increasing the likelihood of the learner imitating the behavior.","kind":"mechanism","origin":"ai"},{"id":"beh-social-cognitive-learning~ai-2","moduleId":"beh-social-cognitive-learning","stem":"In Bandura's Bobo doll experiment, children who observed aggressive behavior were more likely to exhibit aggression themselves. What does this experiment primarily demonstrate?","options":[{"id":"a","text":"Operant conditioning"},{"id":"b","text":"Classical conditioning"},{"id":"c","text":"Observational learning"},{"id":"d","text":"Latent learning"}],"answerId":"c","explanation":"The Bobo doll experiment demonstrates observational learning, where behavior is learned by watching others.","kind":"recall","origin":"ai"},{"id":"beh-social-cognitive-learning~ai-3","moduleId":"beh-social-cognitive-learning","stem":"A patient with high self-efficacy is more likely to:","options":[{"id":"a","text":"Avoid challenging tasks"},{"id":"b","text":"Give up easily"},{"id":"c","text":"Persist in the face of difficulties"},{"id":"d","text":"Doubt their abilities"}],"answerId":"c","explanation":"High self-efficacy is associated with persistence and resilience in challenging situations.","kind":"clinical","origin":"ai"},{"id":"beh-social-cognitive-learning~ai-4","moduleId":"beh-social-cognitive-learning","stem":"Which of the following best describes the relationship between learning and performance in Tolman's latent learning?","options":[{"id":"a","text":"Learning requires immediate performance"},{"id":"b","text":"Performance is necessary for learning"},{"id":"c","text":"Learning can occur without immediate performance"},{"id":"d","text":"Performance always indicates learning"}],"answerId":"c","explanation":"Latent learning suggests that knowledge can be acquired without being immediately demonstrated through performance.","kind":"mechanism","origin":"ai"},{"id":"beh-social-cognitive-learning~ai-5","moduleId":"beh-social-cognitive-learning","stem":"A therapist uses cognitive-behavioral techniques to help a patient with anxiety. Which learning principle is most directly applied here?","options":[{"id":"a","text":"Operant conditioning"},{"id":"b","text":"Insight learning"},{"id":"c","text":"Observational learning"},{"id":"d","text":"Latent learning"}],"answerId":"c","explanation":"Cognitive-behavioral techniques often involve observational learning principles, where patients learn by observing and modifying their thoughts and behaviors.","kind":"integration","linkedModuleIds":["beh-mood-anxiety-disorders"],"origin":"ai"},{"id":"beh-social-cognitive-learning~ai-6","moduleId":"beh-social-cognitive-learning","stem":"A model's characteristics influence whether they are imitated. Which model is most likely to be imitated?","options":[{"id":"a","text":"A low-status stranger"},{"id":"b","text":"A similar peer"},{"id":"c","text":"An unknown authority"},{"id":"d","text":"A distant celebrity"}],"answerId":"b","explanation":"Models who are similar to the observer are more likely to be imitated due to perceived relatability.","kind":"mechanism","origin":"ai"},{"id":"beh-social-cognitive-learning~ai-7","moduleId":"beh-social-cognitive-learning","stem":"How does social learning theory extend the principles of operant conditioning?","options":[{"id":"a","text":"By requiring direct reinforcement for learning"},{"id":"b","text":"By emphasizing the role of punishment"},{"id":"c","text":"By allowing learning through observation without direct reinforcement"},{"id":"d","text":"By focusing solely on internal cognitive processes"}],"answerId":"c","explanation":"Social learning theory extends operant conditioning by showing that learning can occur through observation without direct reinforcement.","kind":"integration","linkedModuleIds":["beh-classical-operant-conditioning"],"origin":"ai"}],"beh-psychosexual-stages":[{"id":"beh-psychosexual-stages~ai-0","moduleId":"beh-psychosexual-stages","stem":"During which of Freud's psychosexual stages does the Oedipus complex occur?","options":[{"id":"a","text":"Oral stage"},{"id":"b","text":"Anal stage"},{"id":"c","text":"Phallic stage"},{"id":"d","text":"Latency stage"}],"answerId":"c","explanation":"The Oedipus complex occurs during the phallic stage, where the focus is on the genitals and the child's desire for the opposite-sex parent.","kind":"recall","origin":"ai"},{"id":"beh-psychosexual-stages~ai-1","moduleId":"beh-psychosexual-stages","stem":"A 4-year-old child exhibits strong rivalry with the same-sex parent and shows a preference for the opposite-sex parent. According to Freud, which stage is this child likely experiencing?","options":[{"id":"a","text":"Oral stage"},{"id":"b","text":"Anal stage"},{"id":"c","text":"Phallic stage"},{"id":"d","text":"Latency stage"}],"answerId":"c","explanation":"The phallic stage involves the Oedipus complex, where rivalry with the same-sex parent and desire for the opposite-sex parent are prominent.","kind":"clinical","origin":"ai"},{"id":"beh-psychosexual-stages~ai-2","moduleId":"beh-psychosexual-stages","stem":"Which of the following traits is most likely to develop from fixation at the anal stage?","options":[{"id":"a","text":"Dependency"},{"id":"b","text":"Orderliness"},{"id":"c","text":"Sexual curiosity"},{"id":"d","text":"Social withdrawal"}],"answerId":"b","explanation":"Anal fixation can lead to traits such as orderliness, obstinacy, and parsimony, often described as anal-retentive traits.","kind":"mechanism","origin":"ai"},{"id":"beh-psychosexual-stages~ai-3","moduleId":"beh-psychosexual-stages","stem":"A patient presents with excessive smoking and overeating. Freud would most likely attribute these behaviors to fixation at which psychosexual stage?","options":[{"id":"a","text":"Oral stage"},{"id":"b","text":"Anal stage"},{"id":"c","text":"Phallic stage"},{"id":"d","text":"Genital stage"}],"answerId":"a","explanation":"Fixation at the oral stage can lead to behaviors such as smoking and overeating due to unresolved oral gratification needs.","kind":"clinical","origin":"ai"},{"id":"beh-psychosexual-stages~ai-4","moduleId":"beh-psychosexual-stages","stem":"How does the resolution of the Oedipus complex contribute to personality development according to Freud?","options":[{"id":"a","text":"By forming the id"},{"id":"b","text":"By forming the ego"},{"id":"c","text":"By forming the superego"},{"id":"d","text":"By forming the libido"}],"answerId":"c","explanation":"The resolution of the Oedipus complex leads to the formation of the superego through identification with the same-sex parent.","kind":"mechanism","origin":"ai"},{"id":"beh-psychosexual-stages~ai-5","moduleId":"beh-psychosexual-stages","stem":"Which of the following is a key difference between Freud's psychosexual stages and Erikson's psychosocial stages?","options":[{"id":"a","text":"Freud's stages are lifelong, Erikson's end in adolescence"},{"id":"b","text":"Freud's stages focus on social crises, Erikson's on libido"},{"id":"c","text":"Freud's stages are drive-based, Erikson's are social"},{"id":"d","text":"Freud's stages involve cognitive development, Erikson's do not"}],"answerId":"c","explanation":"Freud's psychosexual stages are drive-based and largely complete by adolescence, while Erikson's psychosocial stages are social and span the whole lifespan.","kind":"trap","linkedModuleIds":["beh-erikson-psychosocial"],"origin":"ai"},{"id":"beh-psychosexual-stages~ai-6","moduleId":"beh-psychosexual-stages","stem":"A teenager is struggling with identity and role confusion. Which of Erikson's stages does this correspond to, and how does it differ from Freud's view of adolescence?","options":[{"id":"a","text":"Intimacy vs. Isolation; Freud sees adolescence as latency"},{"id":"b","text":"Identity vs. Role Confusion; Freud sees adolescence as genital"},{"id":"c","text":"Generativity vs. Stagnation; Freud sees adolescence as phallic"},{"id":"d","text":"Trust vs. Mistrust; Freud sees adolescence as oral"}],"answerId":"b","explanation":"Erikson's stage of Identity vs. Role Confusion occurs during adolescence, contrasting with Freud's genital stage focused on mature sexuality.","kind":"integration","linkedModuleIds":["beh-erikson-psychosocial"],"origin":"ai"},{"id":"beh-psychosexual-stages~ai-7","moduleId":"beh-psychosexual-stages","stem":"Which stage of Freud's psychosexual development is characterized by a focus on skill development and peer relationships, rather than sexual urges?","options":[{"id":"a","text":"Oral stage"},{"id":"b","text":"Anal stage"},{"id":"c","text":"Phallic stage"},{"id":"d","text":"Latency stage"}],"answerId":"d","explanation":"The latency stage is characterized by a sublimation of sexual urges into learning and peer relationships.","kind":"recall","origin":"ai"}],"beh-successful-aging":[{"id":"beh-successful-aging~ai-0","moduleId":"beh-successful-aging","stem":"Which of the following is NOT a component of Rowe & Kahn's model of successful aging?","options":[{"id":"a","text":"Absence of chronic pain"},{"id":"b","text":"High cognitive and physical function"},{"id":"c","text":"Active engagement with life"},{"id":"d","text":"Low probability of disease and disability"}],"answerId":"a","explanation":"Rowe & Kahn's model includes low probability of disease, high function, and active engagement, but not specifically the absence of chronic pain.","kind":"recall","origin":"ai"},{"id":"beh-successful-aging~ai-1","moduleId":"beh-successful-aging","stem":"An 80-year-old man has no chronic diseases but lives alone and rarely socializes. According to Rowe & Kahn, what aspect of successful aging is he missing?","options":[{"id":"a","text":"Low probability of disease"},{"id":"b","text":"High cognitive function"},{"id":"c","text":"Active engagement with life"},{"id":"d","text":"High physical function"}],"answerId":"c","explanation":"Active engagement with life is crucial for successful aging, beyond just being disease-free.","kind":"clinical","origin":"ai"},{"id":"beh-successful-aging~ai-2","moduleId":"beh-successful-aging","stem":"Which of the following best describes the role of modifiable factors in successful aging?","options":[{"id":"a","text":"They have minimal impact compared to genetic factors"},{"id":"b","text":"They are crucial and can significantly enhance aging outcomes"},{"id":"c","text":"They are only relevant in early adulthood"},{"id":"d","text":"They primarily influence cognitive decline prevention"}],"answerId":"b","explanation":"Modifiable factors like physical activity and social connections significantly enhance aging outcomes.","kind":"mechanism","origin":"ai"},{"id":"beh-successful-aging~ai-3","moduleId":"beh-successful-aging","stem":"A clinician dismisses an elderly patient's low mood as a normal part of aging. Which concept does this misunderstanding contradict?","options":[{"id":"a","text":"Successful aging"},{"id":"b","text":"Biopsychosocial model"},{"id":"c","text":"Baltes’ SOC model"},{"id":"d","text":"Erikson’s psychosocial stages"}],"answerId":"b","explanation":"The biopsychosocial model emphasizes that depression is treatable and not a normal part of aging.","kind":"trap","linkedModuleIds":["beh-biopsychosocial-model"],"origin":"ai"},{"id":"beh-successful-aging~ai-4","moduleId":"beh-successful-aging","stem":"How does the Baltes’ SOC model relate to successful aging?","options":[{"id":"a","text":"It focuses solely on disease prevention"},{"id":"b","text":"It describes adaptation strategies for aging"},{"id":"c","text":"It emphasizes genetic factors over lifestyle"},{"id":"d","text":"It only applies to cognitive function"}],"answerId":"b","explanation":"Baltes’ SOC model describes how older adults adapt by selecting, optimizing, and compensating, aligning with successful aging.","kind":"integration","linkedModuleIds":["beh-resilience"],"origin":"ai"},{"id":"beh-successful-aging~ai-5","moduleId":"beh-successful-aging","stem":"Which of the following is a common misconception about successful aging?","options":[{"id":"a","text":"It requires high physical function"},{"id":"b","text":"It is solely about avoiding disease"},{"id":"c","text":"It includes active engagement with life"},{"id":"d","text":"It involves cognitive stimulation"}],"answerId":"b","explanation":"Successful aging is not solely about avoiding disease; it also requires function and engagement.","kind":"trap","origin":"ai"},{"id":"beh-successful-aging~ai-6","moduleId":"beh-successful-aging","stem":"In the context of successful aging, why is late-life depression particularly important to address?","options":[{"id":"a","text":"It is a normal part of aging"},{"id":"b","text":"It is under-detected but highly treatable"},{"id":"c","text":"It primarily affects physical function"},{"id":"d","text":"It is less common than in younger adults"}],"answerId":"b","explanation":"Late-life depression is under-detected yet highly treatable, making active screening essential.","kind":"integration","linkedModuleIds":["beh-mood-anxiety-disorders"],"origin":"ai"}],"beh-personality-trait-theory":[{"id":"beh-personality-trait-theory~ai-0","moduleId":"beh-personality-trait-theory","stem":"Which of the following is NOT one of the Big Five personality traits?","options":[{"id":"a","text":"Openness"},{"id":"b","text":"Conscientiousness"},{"id":"c","text":"Introversion"},{"id":"d","text":"Agreeableness"}],"answerId":"c","explanation":"Introversion is not a Big Five trait; Extraversion is, which is the opposite pole of Introversion.","kind":"recall","origin":"ai"},{"id":"beh-personality-trait-theory~ai-1","moduleId":"beh-personality-trait-theory","stem":"Which personality trait is most associated with poor health behaviors and outcomes?","options":[{"id":"a","text":"High openness"},{"id":"b","text":"High agreeableness"},{"id":"c","text":"High neuroticism"},{"id":"d","text":"High extraversion"}],"answerId":"c","explanation":"High neuroticism is linked to maladaptive coping and risk behaviors, leading to poorer health outcomes.","kind":"mechanism","origin":"ai"},{"id":"beh-personality-trait-theory~ai-2","moduleId":"beh-personality-trait-theory","stem":"A patient is described as having a biologically-based emotional style that appeared early in life. This refers to which aspect of personality?","options":[{"id":"a","text":"Character"},{"id":"b","text":"Temperament"},{"id":"c","text":"Conscientiousness"},{"id":"d","text":"Psychoticism"}],"answerId":"b","explanation":"Temperament is the biologically-based emotional style that appears early in life.","kind":"trap","origin":"ai"},{"id":"beh-personality-trait-theory~ai-3","moduleId":"beh-personality-trait-theory","stem":"Which assessment tool is most commonly used to measure the Big Five personality traits?","options":[{"id":"a","text":"MMPI"},{"id":"b","text":"16PF"},{"id":"c","text":"NEO-PI-R"},{"id":"d","text":"Rorschach Test"}],"answerId":"c","explanation":"The NEO-PI-R is specifically designed to assess the Big Five personality traits.","kind":"recall","origin":"ai"},{"id":"beh-personality-trait-theory~ai-4","moduleId":"beh-personality-trait-theory","stem":"Which of the following describes a key difference between temperament and character?","options":[{"id":"a","text":"Temperament is learned; character is biological"},{"id":"b","text":"Temperament is stable; character develops with experience"},{"id":"c","text":"Temperament is values-based; character is emotional"},{"id":"d","text":"Temperament is culturally determined; character is innate"}],"answerId":"b","explanation":"Temperament is biologically-based and stable, while character develops through experience and values.","kind":"trap","origin":"ai"},{"id":"beh-personality-trait-theory~ai-5","moduleId":"beh-personality-trait-theory","stem":"How does the Five-Factor Model of personality relate to the development of personality disorders?","options":[{"id":"a","text":"Personality disorders are unrelated to the Five-Factor Model"},{"id":"b","text":"High scores in any trait lead to personality disorders"},{"id":"c","text":"Extreme scores in traits can predispose to personality disorders"},{"id":"d","text":"Only low scores in traits are associated with personality disorders"}],"answerId":"c","explanation":"Extreme scores in the Big Five traits can predispose individuals to personality disorders.","kind":"integration","linkedModuleIds":["beh-personality-disorders"],"origin":"ai"},{"id":"beh-personality-trait-theory~ai-6","moduleId":"beh-personality-trait-theory","stem":"Which of the following statements best describes the heritability of personality traits?","options":[{"id":"a","text":"Personality traits are entirely learned"},{"id":"b","text":"Personality traits are entirely genetic"},{"id":"c","text":"Personality traits have a substantial heritable component"},{"id":"d","text":"Personality traits are not influenced by genetics"}],"answerId":"c","explanation":"Personality traits have a substantial heritable component, as shown in behavioral genetics studies.","kind":"integration","linkedModuleIds":["beh-behavioral-genetics"],"origin":"ai"}],"beh-aging-life-cycle":[{"id":"beh-aging-life-cycle~ai-0","moduleId":"beh-aging-life-cycle","stem":"Which of the following cognitive changes is considered a normal part of aging?","options":[{"id":"a","text":"Decline in processing speed"},{"id":"b","text":"Significant memory loss affecting daily life"},{"id":"c","text":"Loss of vocabulary"},{"id":"d","text":"Inability to learn new information"}],"answerId":"a","explanation":"Normal aging involves a decline in processing speed, while significant memory loss affecting daily life suggests dementia.","kind":"recall","origin":"ai"},{"id":"beh-aging-life-cycle~ai-1","moduleId":"beh-aging-life-cycle","stem":"In Erikson's 8th psychosocial stage, what virtue is achieved if an individual successfully resolves the conflict of ego integrity versus despair?","options":[{"id":"a","text":"Wisdom"},{"id":"b","text":"Hope"},{"id":"c","text":"Fidelity"},{"id":"d","text":"Care"}],"answerId":"a","explanation":"Successfully resolving the conflict of ego integrity versus despair results in the virtue of wisdom.","kind":"mechanism","origin":"ai"},{"id":"beh-aging-life-cycle~ai-2","moduleId":"beh-aging-life-cycle","stem":"A 75-year-old patient reports occasional forgetfulness but maintains independence in daily activities. What is the most appropriate clinical interpretation?","options":[{"id":"a","text":"Early dementia"},{"id":"b","text":"Normal age-related forgetfulness"},{"id":"c","text":"Mild cognitive impairment"},{"id":"d","text":"Late-life depression"}],"answerId":"b","explanation":"Benign age-related forgetfulness that does not impair daily function is considered normal aging.","kind":"clinical","origin":"ai"},{"id":"beh-aging-life-cycle~ai-3","moduleId":"beh-aging-life-cycle","stem":"Which of the following best describes ageism in healthcare?","options":[{"id":"a","text":"Providing additional resources to older patients"},{"id":"b","text":"Stereotyping older patients as frail and dependent"},{"id":"c","text":"Encouraging older patients to engage in physical activity"},{"id":"d","text":"Offering age-appropriate screenings and interventions"}],"answerId":"b","explanation":"Ageism involves stereotyping older patients, which can lead to under-treatment and dismissing symptoms.","kind":"trap","origin":"ai"},{"id":"beh-aging-life-cycle~ai-4","moduleId":"beh-aging-life-cycle","stem":"How does Erikson's 8th stage of psychosocial development integrate with the concept of successful aging?","options":[{"id":"a","text":"Successful aging involves achieving ego integrity and wisdom"},{"id":"b","text":"Successful aging requires avoiding despair entirely"},{"id":"c","text":"Successful aging focuses solely on physical health"},{"id":"d","text":"Successful aging is unrelated to psychosocial development"}],"answerId":"a","explanation":"Successful aging aligns with achieving ego integrity and wisdom, as proposed in Erikson's 8th stage.","kind":"integration","linkedModuleIds":["beh-erikson-psychosocial"],"origin":"ai"},{"id":"beh-aging-life-cycle~ai-5","moduleId":"beh-aging-life-cycle","stem":"A clinician dismisses an older patient's complaints as 'just old age.' What concept does this illustrate?","options":[{"id":"a","text":"Ageism"},{"id":"b","text":"Normal aging"},{"id":"c","text":"Dementia"},{"id":"d","text":"Successful aging"}],"answerId":"a","explanation":"Dismissing symptoms as 'just old age' is an example of ageism, which can lead to under-investigation and treatment.","kind":"trap","origin":"ai"},{"id":"beh-aging-life-cycle~ai-6","moduleId":"beh-aging-life-cycle","stem":"Which of the following is a key feature distinguishing normal aging from dementia?","options":[{"id":"a","text":"Impaired daily functioning"},{"id":"b","text":"Occasional forgetfulness"},{"id":"c","text":"Slower processing speed"},{"id":"d","text":"Preserved crystallized intelligence"}],"answerId":"a","explanation":"Impaired daily functioning is a key feature of dementia, whereas occasional forgetfulness is normal aging.","kind":"trap","origin":"ai"},{"id":"beh-aging-life-cycle~ai-7","moduleId":"beh-aging-life-cycle","stem":"How does the concept of ageism potentially impact data management and quality control in healthcare settings?","options":[{"id":"a","text":"Leads to biased data collection"},{"id":"b","text":"Ensures accurate age-related data"},{"id":"c","text":"Improves patient engagement"},{"id":"d","text":"Increases resource allocation"}],"answerId":"a","explanation":"Ageism can lead to biased data collection by under-representing older adults' health needs.","kind":"integration","linkedModuleIds":["add-data-management-and-quality-control"],"origin":"ai"}],"beh-personality-disorders":[{"id":"beh-personality-disorders~ai-0","moduleId":"beh-personality-disorders","stem":"Which personality disorder is characterized by a pervasive pattern of grandiosity, need for admiration, and lack of empathy?","options":[{"id":"a","text":"Narcissistic"},{"id":"b","text":"Histrionic"},{"id":"c","text":"Borderline"},{"id":"d","text":"Antisocial"}],"answerId":"a","explanation":"Narcissistic personality disorder involves grandiosity, a need for admiration, and a lack of empathy.","kind":"recall","origin":"ai"},{"id":"beh-personality-disorders~ai-1","moduleId":"beh-personality-disorders","stem":"A 25-year-old man has a history of violating the rights of others and was diagnosed with conduct disorder at age 14. What is the most likely diagnosis now?","options":[{"id":"a","text":"Antisocial Personality Disorder"},{"id":"b","text":"Borderline Personality Disorder"},{"id":"c","text":"Paranoid Personality Disorder"},{"id":"d","text":"Obsessive-Compulsive Personality Disorder"}],"answerId":"a","explanation":"Antisocial Personality Disorder requires a history of conduct disorder before age 15 and continuation of such behaviors into adulthood.","kind":"clinical","origin":"ai"},{"id":"beh-personality-disorders~ai-2","moduleId":"beh-personality-disorders","stem":"Which defense mechanism is most commonly associated with Borderline Personality Disorder?","options":[{"id":"a","text":"Splitting"},{"id":"b","text":"Projection"},{"id":"c","text":"Denial"},{"id":"d","text":"Rationalization"}],"answerId":"a","explanation":"Splitting, or seeing things in black and white terms, is a hallmark of Borderline Personality Disorder.","kind":"mechanism","linkedModuleIds":["beh-defense-mechanisms"],"origin":"ai"},{"id":"beh-personality-disorders~ai-3","moduleId":"beh-personality-disorders","stem":"A patient with a personality disorder views their perfectionism and need for control as reasonable. Which disorder does this suggest?","options":[{"id":"a","text":"Obsessive-Compulsive Personality Disorder"},{"id":"b","text":"Obsessive-Compulsive Disorder"},{"id":"c","text":"Avoidant Personality Disorder"},{"id":"d","text":"Dependent Personality Disorder"}],"answerId":"a","explanation":"Obsessive-Compulsive Personality Disorder is ego-syntonic, meaning patients see their traits as reasonable.","kind":"trap","origin":"ai"},{"id":"beh-personality-disorders~ai-4","moduleId":"beh-personality-disorders","stem":"A 30-year-old woman avoids social situations due to fear of rejection but desires relationships. Which personality disorder is most likely?","options":[{"id":"a","text":"Avoidant Personality Disorder"},{"id":"b","text":"Schizoid Personality Disorder"},{"id":"c","text":"Paranoid Personality Disorder"},{"id":"d","text":"Dependent Personality Disorder"}],"answerId":"a","explanation":"Avoidant Personality Disorder is characterized by social inhibition and fear of rejection despite a desire for relationships.","kind":"clinical","origin":"ai"},{"id":"beh-personality-disorders~ai-5","moduleId":"beh-personality-disorders","stem":"Which personality disorder is most likely to be associated with odd beliefs and magical thinking?","options":[{"id":"a","text":"Schizotypal Personality Disorder"},{"id":"b","text":"Paranoid Personality Disorder"},{"id":"c","text":"Schizoid Personality Disorder"},{"id":"d","text":"Histrionic Personality Disorder"}],"answerId":"a","explanation":"Schizotypal Personality Disorder includes features like odd beliefs and magical thinking.","kind":"recall","origin":"ai"},{"id":"beh-personality-disorders~ai-6","moduleId":"beh-personality-disorders","stem":"A patient with PTSD is also showing signs of a personality disorder characterized by instability in relationships and self-image. Which disorder is likely?","options":[{"id":"a","text":"Borderline Personality Disorder"},{"id":"b","text":"Antisocial Personality Disorder"},{"id":"c","text":"Narcissistic Personality Disorder"},{"id":"d","text":"Avoidant Personality Disorder"}],"answerId":"a","explanation":"Borderline Personality Disorder is marked by instability in relationships and self-image, often seen in patients with PTSD.","kind":"integration","linkedModuleIds":["hrp1-trauma-asd-ptsd-first-aid"],"origin":"ai"},{"id":"beh-personality-disorders~ai-7","moduleId":"beh-personality-disorders","stem":"How does Obsessive-Compulsive Personality Disorder differ from Obsessive-Compulsive Disorder?","options":[{"id":"a","text":"OCPD is ego-syntonic, OCD is ego-dystonic"},{"id":"b","text":"OCPD involves compulsions, OCD does not"},{"id":"c","text":"OCPD is treated with SSRIs, OCD is not"},{"id":"d","text":"OCPD has onset in childhood, OCD does not"}],"answerId":"a","explanation":"OCPD is ego-syntonic, meaning patients see their behaviors as reasonable, while OCD is ego-dystonic, causing distress.","kind":"trap","linkedModuleIds":["beh-other-major-disorders"],"origin":"ai"}],"beh-resilience":[{"id":"beh-resilience~ai-0","moduleId":"beh-resilience","stem":"Which of the following is the most consistent protective factor for resilience?","options":[{"id":"a","text":"At least one supportive relationship"},{"id":"b","text":"High intelligence"},{"id":"c","text":"Financial stability"},{"id":"d","text":"Physical fitness"}],"answerId":"a","explanation":"A supportive relationship provides safety, perspective, and practical help during adversity.","kind":"recall","origin":"ai"},{"id":"beh-resilience~ai-1","moduleId":"beh-resilience","stem":"What is the primary mechanism by which resilience is built?","options":[{"id":"a","text":"Genetic predisposition"},{"id":"b","text":"Strong relationships and coping skills"},{"id":"c","text":"High socioeconomic status"},{"id":"d","text":"Innate intelligence"}],"answerId":"b","explanation":"Resilience is built through relationships, goal-setting, self-care, and meaning-making.","kind":"mechanism","origin":"ai"},{"id":"beh-resilience~ai-2","moduleId":"beh-resilience","stem":"Which of the following is NOT a dimension of burnout according to Maslach?","options":[{"id":"a","text":"Emotional exhaustion"},{"id":"b","text":"Depersonalization"},{"id":"c","text":"Reduced personal accomplishment"},{"id":"d","text":"Increased empathy"}],"answerId":"d","explanation":"Increased empathy is not a dimension of burnout; it is often reduced in burnout.","kind":"recall","origin":"ai"},{"id":"beh-resilience~ai-3","moduleId":"beh-resilience","stem":"A physician experiencing burnout is most likely to benefit from which type of intervention?","options":[{"id":"a","text":"Individual resilience training"},{"id":"b","text":"Organizational workload adjustments"},{"id":"c","text":"Increased patient load"},{"id":"d","text":"Personal meditation practice"}],"answerId":"b","explanation":"Burnout is primarily driven by system and workload factors, so organizational changes are most effective.","kind":"trap","origin":"ai"},{"id":"beh-resilience~ai-4","moduleId":"beh-resilience","stem":"How does resilience relate to the stress response?","options":[{"id":"a","text":"Resilience prevents the activation of the HPA axis"},{"id":"b","text":"Resilience enhances the ability to cope with stress"},{"id":"c","text":"Resilience eliminates stress entirely"},{"id":"d","text":"Resilience is unrelated to stress"}],"answerId":"b","explanation":"Resilience involves coping skills that buffer the stress response.","kind":"integration","linkedModuleIds":["beh-stress-response"],"origin":"ai"},{"id":"beh-resilience~ai-5","moduleId":"beh-resilience","stem":"Which of the following statements about burnout is true?","options":[{"id":"a","text":"Burnout is a personal failure"},{"id":"b","text":"Burnout is best addressed by individual effort"},{"id":"c","text":"Burnout is mainly driven by system factors"},{"id":"d","text":"Burnout is unrelated to workload"}],"answerId":"c","explanation":"Burnout is driven largely by system and workload factors, not personal weakness.","kind":"trap","origin":"ai"},{"id":"beh-resilience~ai-6","moduleId":"beh-resilience","stem":"Which humanistic theory concept is most closely related to building resilience?","options":[{"id":"a","text":"Self-actualization"},{"id":"b","text":"Unconditional positive regard"},{"id":"c","text":"Peak experiences"},{"id":"d","text":"Deficiency needs"}],"answerId":"b","explanation":"Unconditional positive regard fosters supportive relationships, a key factor in resilience.","kind":"integration","linkedModuleIds":["beh-humanistic-theory"],"origin":"ai"}],"beh-stress-response":[{"id":"beh-stress-response~ai-0","moduleId":"beh-stress-response","stem":"Which hormone is primarily responsible for the sustained stress response in the HPA axis?","options":[{"id":"a","text":"Cortisol"},{"id":"b","text":"Adrenaline"},{"id":"c","text":"Noradrenaline"},{"id":"d","text":"Dopamine"}],"answerId":"a","explanation":"Cortisol is released by the adrenal cortex as part of the HPA axis, providing a sustained stress response.","kind":"recall","origin":"ai"},{"id":"beh-stress-response~ai-1","moduleId":"beh-stress-response","stem":"In Selye's General Adaptation Syndrome, what occurs during the exhaustion stage?","options":[{"id":"a","text":"Increased energy and alertness"},{"id":"b","text":"Adaptation and coping"},{"id":"c","text":"Depletion of resources leading to stress-related illness"},{"id":"d","text":"Initial fight-or-flight response"}],"answerId":"c","explanation":"The exhaustion stage is characterized by depleted reserves and the onset of stress-related illnesses.","kind":"mechanism","origin":"ai"},{"id":"beh-stress-response~ai-2","moduleId":"beh-stress-response","stem":"According to Lazarus & Folkman’s model, what is the primary determinant of the stress response?","options":[{"id":"a","text":"The severity of the stressor"},{"id":"b","text":"The individual's cognitive appraisal"},{"id":"c","text":"The duration of the stressor"},{"id":"d","text":"The type of stressor"}],"answerId":"b","explanation":"Lazarus & Folkman emphasize that cognitive appraisal, not the stressor itself, determines the stress response.","kind":"trap","origin":"ai"},{"id":"beh-stress-response~ai-3","moduleId":"beh-stress-response","stem":"Which of the following is an example of emotion-focused coping?","options":[{"id":"a","text":"Making a detailed plan"},{"id":"b","text":"Reframing the situation positively"},{"id":"c","text":"Seeking additional resources"},{"id":"d","text":"Avoiding the problem"}],"answerId":"b","explanation":"Reframing the situation positively is a way to manage emotional distress, typical of emotion-focused coping.","kind":"recall","origin":"ai"},{"id":"beh-stress-response~ai-4","moduleId":"beh-stress-response","stem":"How does chronic stress affect the immune system?","options":[{"id":"a","text":"Enhances immune function"},{"id":"b","text":"No effect on immune function"},{"id":"c","text":"Suppresses immune function"},{"id":"d","text":"Causes autoimmune diseases"}],"answerId":"c","explanation":"Chronic stress leads to persistently high cortisol levels, which suppress immune function.","kind":"mechanism","origin":"ai"},{"id":"beh-stress-response~ai-5","moduleId":"beh-stress-response","stem":"Which of the following best describes the role of resilience in managing chronic stress?","options":[{"id":"a","text":"Resilience has no impact on stress outcomes"},{"id":"b","text":"Resilience increases the severity of stress-related illnesses"},{"id":"c","text":"Resilience helps mitigate the negative effects of chronic stress"},{"id":"d","text":"Resilience causes stress to be perceived as more threatening"}],"answerId":"c","explanation":"Resilience helps individuals better manage and mitigate the negative effects of chronic stress.","kind":"integration","linkedModuleIds":["beh-resilience"],"origin":"ai"},{"id":"beh-stress-response~ai-6","moduleId":"beh-stress-response","stem":"Which axis is primarily responsible for the immediate fight-or-flight response?","options":[{"id":"a","text":"HPA axis"},{"id":"b","text":"SAM axis"},{"id":"c","text":"Thyroid axis"},{"id":"d","text":"Renin-angiotensin axis"}],"answerId":"b","explanation":"The SAM axis, involving adrenaline and noradrenaline, drives the immediate fight-or-flight response.","kind":"recall","origin":"ai"},{"id":"beh-stress-response~ai-7","moduleId":"beh-stress-response","stem":"How does the transactional model of stress relate to defense mechanisms?","options":[{"id":"a","text":"Defense mechanisms are irrelevant to stress appraisal"},{"id":"b","text":"Defense mechanisms can alter cognitive appraisal of stress"},{"id":"c","text":"Defense mechanisms increase stress severity"},{"id":"d","text":"Defense mechanisms are only used in pathological stress responses"}],"answerId":"b","explanation":"Defense mechanisms can influence how stressors are appraised, affecting the overall stress response.","kind":"integration","linkedModuleIds":["beh-defense-mechanisms"],"origin":"ai"}],"beh-death-dying":[{"id":"beh-death-dying~ai-0","moduleId":"beh-death-dying","stem":"Which of the following is NOT a stage in the Kübler-Ross model of dying?","options":[{"id":"a","text":"Denial"},{"id":"b","text":"Acceptance"},{"id":"c","text":"Regret"},{"id":"d","text":"Bargaining"}],"answerId":"c","explanation":"The five stages are Denial, Anger, Bargaining, Depression, and Acceptance. Regret is not one of them.","kind":"recall","origin":"ai"},{"id":"beh-death-dying~ai-1","moduleId":"beh-death-dying","stem":"A patient with terminal cancer expresses anger towards their family and healthcare providers. According to the Kübler-Ross model, which stage does this behavior represent?","options":[{"id":"a","text":"Denial"},{"id":"b","text":"Anger"},{"id":"c","text":"Bargaining"},{"id":"d","text":"Depression"}],"answerId":"b","explanation":"Anger is the second stage in the Kübler-Ross model, where patients may express frustration and resentment.","kind":"mechanism","origin":"ai"},{"id":"beh-death-dying~ai-2","moduleId":"beh-death-dying","stem":"A physician insists that a patient must experience all five stages of the Kübler-Ross model in order. What is the flaw in this approach?","options":[{"id":"a","text":"It ignores the patient's autonomy."},{"id":"b","text":"It misapplies the model as a fixed sequence."},{"id":"c","text":"It overlooks the need for palliative care."},{"id":"d","text":"It fails to address the patient's physical symptoms."}],"answerId":"b","explanation":"The Kübler-Ross stages are descriptive and not a mandatory sequence; patients may skip or reorder them.","kind":"trap","origin":"ai"},{"id":"beh-death-dying~ai-3","moduleId":"beh-death-dying","stem":"Which of the following best describes the primary goal of palliative care?","options":[{"id":"a","text":"To cure the underlying disease"},{"id":"b","text":"To provide psychological counseling"},{"id":"c","text":"To improve quality of life and relieve symptoms"},{"id":"d","text":"To hasten the dying process"}],"answerId":"c","explanation":"Palliative care focuses on quality of life and symptom relief, not curing the disease.","kind":"recall","origin":"ai"},{"id":"beh-death-dying~ai-4","moduleId":"beh-death-dying","stem":"A patient with a terminal illness is focused on making amends and seeking forgiveness. Which stage of the Kübler-Ross model does this represent?","options":[{"id":"a","text":"Denial"},{"id":"b","text":"Bargaining"},{"id":"c","text":"Depression"},{"id":"d","text":"Acceptance"}],"answerId":"b","explanation":"Bargaining often involves making deals or seeking forgiveness to delay or change the outcome.","kind":"mechanism","origin":"ai"},{"id":"beh-death-dying~ai-5","moduleId":"beh-death-dying","stem":"In the SPIKES protocol for breaking bad news, what does the 'P' stand for?","options":[{"id":"a","text":"Preparation"},{"id":"b","text":"Perception"},{"id":"c","text":"Pacing"},{"id":"d","text":"Permission"}],"answerId":"b","explanation":"In the SPIKES protocol, 'P' stands for Perception, assessing what the patient already knows.","kind":"recall","origin":"ai"},{"id":"beh-death-dying~ai-6","moduleId":"beh-death-dying","stem":"How does the Kübler-Ross model apply to a patient who has lost a limb due to an accident?","options":[{"id":"a","text":"The model is irrelevant as it only applies to terminal illness."},{"id":"b","text":"The patient may experience stages like denial and anger as part of their emotional response."},{"id":"c","text":"The patient must go through all stages to reach acceptance."},{"id":"d","text":"The model only applies if the patient is in palliative care."}],"answerId":"b","explanation":"The Kübler-Ross model applies to any major loss, including loss of a limb, where stages like denial and anger may be experienced.","kind":"integration","linkedModuleIds":["beh-grief-bereavement"],"origin":"ai"},{"id":"beh-death-dying~ai-7","moduleId":"beh-death-dying","stem":"When discussing advance care planning with an elderly patient, which linked module provides additional insights?","options":[{"id":"a","text":"Difficult Encounters & Breaking Bad News"},{"id":"b","text":"Clinical Communication Skills"},{"id":"c","text":"Grief, Mourning & Bereavement"},{"id":"d","text":"The Elderly Life Cycle & Ageism"}],"answerId":"d","explanation":"The module 'The Elderly Life Cycle & Ageism' provides insights into considerations specific to elderly patients.","kind":"integration","linkedModuleIds":["beh-aging-life-cycle"],"origin":"ai"}],"beh-grief-bereavement":[{"id":"beh-grief-bereavement~ai-0","moduleId":"beh-grief-bereavement","stem":"Which of the following best describes the term 'mourning'?","options":[{"id":"a","text":"The objective state of having lost someone"},{"id":"b","text":"The internal emotional response to loss"},{"id":"c","text":"The outward, culturally-shaped expression of grief"},{"id":"d","text":"A disorder characterized by intense, prolonged grief"}],"answerId":"c","explanation":"Mourning is the outward, culturally-shaped expression of grief, distinct from bereavement and grief.","kind":"recall","origin":"ai"},{"id":"beh-grief-bereavement~ai-1","moduleId":"beh-grief-bereavement","stem":"A patient reports experiencing brief moments where they feel their deceased spouse is present. What is the most appropriate interpretation of this symptom?","options":[{"id":"a","text":"Normal grief reaction"},{"id":"b","text":"Major depressive disorder"},{"id":"c","text":"Psychotic disorder"},{"id":"d","text":"Prolonged grief disorder"}],"answerId":"a","explanation":"Transient illusions or hallucinations of the deceased are normal in grief and not indicative of a psychiatric disorder.","kind":"clinical","origin":"ai"},{"id":"beh-grief-bereavement~ai-2","moduleId":"beh-grief-bereavement","stem":"What differentiates grief from major depression in the context of bereavement?","options":[{"id":"a","text":"Pervasive sadness and anhedonia"},{"id":"b","text":"Waves of sadness with preserved self-esteem"},{"id":"c","text":"Persistent worthlessness and guilt"},{"id":"d","text":"Global suicidal ideation"}],"answerId":"b","explanation":"Grief is characterized by waves of sadness and preserved self-esteem, unlike the pervasive symptoms of depression.","kind":"mechanism","origin":"ai"},{"id":"beh-grief-bereavement~ai-3","moduleId":"beh-grief-bereavement","stem":"Which of the following is a characteristic of Prolonged Grief Disorder?","options":[{"id":"a","text":"Grief that resolves within a few months"},{"id":"b","text":"Transient hallucinations of the deceased"},{"id":"c","text":"Intense, persistent yearning beyond 12 months"},{"id":"d","text":"Normal anniversary reactions"}],"answerId":"c","explanation":"Prolonged Grief Disorder involves intense, persistent yearning and preoccupation beyond 12 months.","kind":"recall","origin":"ai"},{"id":"beh-grief-bereavement~ai-4","moduleId":"beh-grief-bereavement","stem":"A patient experiencing anticipatory grief is most likely dealing with which situation?","options":[{"id":"a","text":"Loss of a pet"},{"id":"b","text":"Death of a spouse"},{"id":"c","text":"Terminal illness of a loved one"},{"id":"d","text":"Loss of a job"}],"answerId":"c","explanation":"Anticipatory grief occurs when grieving begins before an expected loss, such as during a terminal illness.","kind":"recall","origin":"ai"},{"id":"beh-grief-bereavement~ai-5","moduleId":"beh-grief-bereavement","stem":"In the context of grief, which approach is most appropriate when supporting a bereaved individual?","options":[{"id":"a","text":"Offering platitudes"},{"id":"b","text":"Encouraging them to move on quickly"},{"id":"c","text":"Listening and normalizing their feelings"},{"id":"d","text":"Avoiding discussions about the deceased"}],"answerId":"c","explanation":"Supporting the bereaved involves listening and normalizing their feelings, rather than offering platitudes.","kind":"clinical","origin":"ai"},{"id":"beh-grief-bereavement~ai-6","moduleId":"beh-grief-bereavement","stem":"How does anticipatory grief relate to the stages of dying described by Kübler-Ross?","options":[{"id":"a","text":"It is unrelated to the stages of dying"},{"id":"b","text":"It occurs after acceptance"},{"id":"c","text":"It parallels the stages of dying"},{"id":"d","text":"It replaces the stages of dying"}],"answerId":"c","explanation":"Anticipatory grief can parallel the stages of dying, as individuals may experience similar emotional responses.","kind":"integration","linkedModuleIds":["beh-death-dying"],"origin":"ai"},{"id":"beh-grief-bereavement~ai-7","moduleId":"beh-grief-bereavement","stem":"A patient presents with pervasive sadness, worthlessness, and anhedonia following the death of a loved one. Which module would best aid in differentiating this condition from normal grief?","options":[{"id":"a","text":"Clinical Communication Skills"},{"id":"b","text":"Mood & Anxiety Disorders (DSM-5-TR)"},{"id":"c","text":"Suicide Risk Assessment & Safety Planning"},{"id":"d","text":"Difficult Encounters & Breaking Bad News"}],"answerId":"b","explanation":"The Mood & Anxiety Disorders module provides criteria to differentiate major depression from normal grief.","kind":"integration","linkedModuleIds":["beh-mood-anxiety-disorders"],"origin":"ai"}],"beh-aggression-violence":[{"id":"beh-aggression-violence~ai-0","moduleId":"beh-aggression-violence","stem":"Which of the following is the strongest predictor of future violence in a patient?","options":[{"id":"a","text":"A past history of violence"},{"id":"b","text":"Substance intoxication"},{"id":"c","text":"Psychosis with paranoia"},{"id":"d","text":"Access to weapons"}],"answerId":"a","explanation":"A past history of violence is the single strongest predictor of future violence.","kind":"recall","origin":"ai"},{"id":"beh-aggression-violence~ai-1","moduleId":"beh-aggression-violence","stem":"A patient presents with agitation and confusion. What is the first step in management?","options":[{"id":"a","text":"Administer sedative medication"},{"id":"b","text":"Perform a medical work-up to exclude organic causes"},{"id":"c","text":"Apply physical restraints"},{"id":"d","text":"Initiate verbal de-escalation"}],"answerId":"b","explanation":"Agitation is treated as a medical emergency until organic causes are excluded.","kind":"trap","origin":"ai"},{"id":"beh-aggression-violence~ai-2","moduleId":"beh-aggression-violence","stem":"During a psychiatric evaluation, a patient begins pacing and clenching their fists. What should be your immediate action?","options":[{"id":"a","text":"Call for security assistance"},{"id":"b","text":"Attempt verbal de-escalation"},{"id":"c","text":"Leave the room immediately"},{"id":"d","text":"Administer a sedative"}],"answerId":"b","explanation":"Verbal de-escalation is first-line and resolves most agitation without force.","kind":"clinical","origin":"ai"},{"id":"beh-aggression-violence~ai-3","moduleId":"beh-aggression-violence","stem":"When is it appropriate to use physical restraints on an agitated patient?","options":[{"id":"a","text":"Immediately upon signs of agitation"},{"id":"b","text":"After verbal de-escalation and medical work-up fail"},{"id":"c","text":"As soon as the patient raises their voice"},{"id":"d","text":"When the patient has a history of violence"}],"answerId":"b","explanation":"Restraint and seclusion are last resorts, least-restrictive and closely monitored.","kind":"mechanism","origin":"ai"},{"id":"beh-aggression-violence~ai-4","moduleId":"beh-aggression-violence","stem":"A patient with schizophrenia is experiencing command hallucinations to harm others. What is the most appropriate initial management step?","options":[{"id":"a","text":"Administer antipsychotic medication"},{"id":"b","text":"Ensure safety and attempt verbal de-escalation"},{"id":"c","text":"Apply physical restraints"},{"id":"d","text":"Perform a full psychiatric assessment"}],"answerId":"b","explanation":"Safety and verbal de-escalation are prioritized to prevent escalation.","kind":"integration","linkedModuleIds":["beh-psychotic-disorders"],"origin":"ai"},{"id":"beh-aggression-violence~ai-5","moduleId":"beh-aggression-violence","stem":"In managing a difficult encounter with an agitated patient, which technique is most effective in de-escalation?","options":[{"id":"a","text":"Ignoring the patient's concerns"},{"id":"b","text":"Maintaining a calm demeanor and offering choices"},{"id":"c","text":"Using authoritative commands"},{"id":"d","text":"Physically restraining the patient immediately"}],"answerId":"b","explanation":"Calm engagement, validation, and offering choices reduce arousal before it escalates.","kind":"integration","linkedModuleIds":["beh-difficult-encounters"],"origin":"ai"}],"beh-suicide-assessment":[{"id":"beh-suicide-assessment~ai-0","moduleId":"beh-suicide-assessment","stem":"Which of the following is the strongest predictor of eventual suicide?","options":[{"id":"a","text":"A previous suicide attempt"},{"id":"b","text":"Substance use"},{"id":"c","text":"Social isolation"},{"id":"d","text":"Chronic pain"}],"answerId":"a","explanation":"A previous suicide attempt is the single strongest predictor of future suicide.","kind":"recall","origin":"ai"},{"id":"beh-suicide-assessment~ai-1","moduleId":"beh-suicide-assessment","stem":"What is the primary reason restricting access to lethal means is effective in suicide prevention?","options":[{"id":"a","text":"It reduces the desire to attempt suicide"},{"id":"b","text":"It buys time during impulsive crises"},{"id":"c","text":"It eliminates suicidal ideation"},{"id":"d","text":"It increases social support"}],"answerId":"b","explanation":"Restricting access to lethal means buys life-saving time during brief and impulsive suicidal crises.","kind":"mechanism","origin":"ai"},{"id":"beh-suicide-assessment~ai-2","moduleId":"beh-suicide-assessment","stem":"A clinician is assessing a patient with suicidal ideation. Which step should be taken first?","options":[{"id":"a","text":"Assess the patient's access to lethal means"},{"id":"b","text":"Formulate a safety plan"},{"id":"c","text":"Evaluate the patient's intent"},{"id":"d","text":"Inquire about the patient's specific plan"}],"answerId":"d","explanation":"The assessment should systematically progress from ideation to plan, intent, means, and safety.","kind":"clinical","origin":"ai"},{"id":"beh-suicide-assessment~ai-3","moduleId":"beh-suicide-assessment","stem":"A patient with depression suddenly appears calm and at peace after a period of distress. What should the clinician consider?","options":[{"id":"a","text":"The patient has recovered"},{"id":"b","text":"The patient is at high risk of suicide"},{"id":"c","text":"The patient no longer needs monitoring"},{"id":"d","text":"The patient is responding well to treatment"}],"answerId":"b","explanation":"A sudden calm after depression can indicate a decision to commit suicide, signaling high risk.","kind":"trap","origin":"ai"},{"id":"beh-suicide-assessment~ai-4","moduleId":"beh-suicide-assessment","stem":"Which of the following is a myth regarding suicide risk assessment?","options":[{"id":"a","text":"Asking about suicide increases risk"},{"id":"b","text":"Men die by suicide more often"},{"id":"c","text":"Women attempt suicide more often"},{"id":"d","text":"Restricting means is effective"}],"answerId":"a","explanation":"The myth is that asking about suicide increases risk; evidence shows it reduces distress and aids intervention.","kind":"trap","origin":"ai"},{"id":"beh-suicide-assessment~ai-5","moduleId":"beh-suicide-assessment","stem":"In the context of a psychiatric history, which factor is most critical to assess for suicide risk?","options":[{"id":"a","text":"Family history of mental illness"},{"id":"b","text":"Previous suicide attempts"},{"id":"c","text":"Current employment status"},{"id":"d","text":"Religious beliefs"}],"answerId":"b","explanation":"Previous suicide attempts are the strongest predictor of future suicide risk.","kind":"integration","linkedModuleIds":["beh-psychiatric-history"],"origin":"ai"},{"id":"beh-suicide-assessment~ai-6","moduleId":"beh-suicide-assessment","stem":"During a mental status examination, which finding would most likely indicate a high risk of suicide?","options":[{"id":"a","text":"Euphoric mood"},{"id":"b","text":"Concrete thinking"},{"id":"c","text":"Hopelessness"},{"id":"d","text":"Increased energy"}],"answerId":"c","explanation":"Hopelessness is a significant indicator of suicide risk during a mental status examination.","kind":"integration","linkedModuleIds":["beh-mental-status-exam"],"origin":"ai"}],"beh-abuse-neglect":[{"id":"beh-abuse-neglect~ai-0","moduleId":"beh-abuse-neglect","stem":"A 3-month-old infant presents with a femur fracture. The caregiver states the infant rolled off the bed. What is the most concerning aspect of this case?","options":[{"id":"a","text":"The infant's age and developmental stage"},{"id":"b","text":"The type of fracture"},{"id":"c","text":"The caregiver's explanation"},{"id":"d","text":"The infant's gender"}],"answerId":"a","explanation":"A 3-month-old infant is non-ambulatory and cannot roll off a bed independently, making the injury suspicious for abuse.","kind":"clinical","origin":"ai"},{"id":"beh-abuse-neglect~ai-1","moduleId":"beh-abuse-neglect","stem":"Which of the following is a mandatory reportable situation?","options":[{"id":"a","text":"A competent adult experiencing IPV who refuses to report"},{"id":"b","text":"A child with unexplained bruises"},{"id":"c","text":"An adult with a history of IPV but no current threat"},{"id":"d","text":"A competent adult with a self-inflicted injury"}],"answerId":"b","explanation":"Child abuse is a mandatory report, regardless of the circumstances, to protect the vulnerable child.","kind":"recall","origin":"ai"},{"id":"beh-abuse-neglect~ai-2","moduleId":"beh-abuse-neglect","stem":"During an examination, a patient’s partner insists on staying in the room and answers all questions. What should be your next step?","options":[{"id":"a","text":"Allow the partner to stay for support"},{"id":"b","text":"Ask the partner to leave the room"},{"id":"c","text":"Continue the examination without addressing the partner"},{"id":"d","text":"End the examination and reschedule"}],"answerId":"b","explanation":"The patient should be interviewed alone to ensure they can speak freely without coercion.","kind":"clinical","origin":"ai"},{"id":"beh-abuse-neglect~ai-3","moduleId":"beh-abuse-neglect","stem":"A 7-year-old child presents with multiple bruises of different ages. The caregiver claims they are from frequent falls. What is the most appropriate action?","options":[{"id":"a","text":"Accept the explanation and document the visit"},{"id":"b","text":"Report the suspicion of abuse to the authorities"},{"id":"c","text":"Advise the caregiver to supervise the child more closely"},{"id":"d","text":"Schedule a follow-up visit in one month"}],"answerId":"b","explanation":"Multiple bruises of different ages are suspicious for abuse and should be reported to protect the child.","kind":"trap","origin":"ai"},{"id":"beh-abuse-neglect~ai-4","moduleId":"beh-abuse-neglect","stem":"In cases of suspected elder abuse, what is the primary reason for mandatory reporting?","options":[{"id":"a","text":"To ensure the elder receives medical treatment"},{"id":"b","text":"To protect the elder from further harm"},{"id":"c","text":"To involve family members in the elder's care"},{"id":"d","text":"To provide legal consequences for the abuser"}],"answerId":"b","explanation":"Mandatory reporting aims to protect vulnerable individuals from further harm by ensuring intervention.","kind":"recall","origin":"ai"},{"id":"beh-abuse-neglect~ai-5","moduleId":"beh-abuse-neglect","stem":"A patient with a history of mood disorders presents with unexplained injuries. Which module should be considered for further assessment?","options":[{"id":"a","text":"Blood Donation & Donor Screening"},{"id":"b","text":"Aggression, Agitation & De-escalation"},{"id":"c","text":"Mood & Anxiety Disorders (DSM-5-TR)"},{"id":"d","text":"Other Major Disorders & the DSM-5-TR Map"}],"answerId":"c","explanation":"Mood disorders can be linked to self-harm or abuse, necessitating assessment through the Mood & Anxiety Disorders module.","kind":"integration","linkedModuleIds":["beh-mood-anxiety-disorders"],"origin":"ai"},{"id":"beh-abuse-neglect~ai-6","moduleId":"beh-abuse-neglect","stem":"A patient in a violent relationship is hesitant to leave due to fear of escalation. Which module provides strategies for managing such situations?","options":[{"id":"a","text":"Family & Psychopathology"},{"id":"b","text":"Aggression, Agitation & De-escalation"},{"id":"c","text":"Blood Donation & Donor Screening"},{"id":"d","text":"Other Major Disorders & the DSM-5-TR Map"}],"answerId":"b","explanation":"The Aggression, Agitation & De-escalation module offers strategies for managing and de-escalating violent situations.","kind":"integration","linkedModuleIds":["beh-aggression-violence"],"origin":"ai"}],"fcp1-pediatric-approach-communication":[{"id":"fcp1-pediatric-approach-communication~ai-0","moduleId":"fcp1-pediatric-approach-communication","stem":"During a pediatric consultation, what is the most appropriate way to begin the examination of a calm child?","options":[{"id":"a","text":"Start with the ears and throat"},{"id":"b","text":"Begin with a head-to-toe examination"},{"id":"c","text":"Examine opportunistically while the child is calm"},{"id":"d","text":"Focus on the parent's concerns first"}],"answerId":"c","explanation":"Examine opportunistically while the child is calm and leave distressing parts like ears and throat until last.","kind":"trap","origin":"ai"},{"id":"fcp1-pediatric-approach-communication~ai-1","moduleId":"fcp1-pediatric-approach-communication","stem":"What is a reassuring sign when observing a child during a consultation?","options":[{"id":"a","text":"Listlessness and poor response"},{"id":"b","text":"Playing and making eye contact"},{"id":"c","text":"Refusal to engage with the clinician"},{"id":"d","text":"Crying inconsolably"}],"answerId":"b","explanation":"A child who plays and makes eye contact is showing normal engagement, which is reassuring.","kind":"recall","origin":"ai"},{"id":"fcp1-pediatric-approach-communication~ai-2","moduleId":"fcp1-pediatric-approach-communication","stem":"Which statement about parental concern during a pediatric consultation is most accurate?","options":[{"id":"a","text":"Parental concern is often exaggerated"},{"id":"b","text":"Parental concern is a validated predictor of illness"},{"id":"c","text":"Parental concern should be ignored if the child appears well"},{"id":"d","text":"Parental concern is only relevant in infants"}],"answerId":"b","explanation":"Parental concern is a validated predictor of significant illness and should be taken seriously.","kind":"recall","origin":"ai"},{"id":"fcp1-pediatric-approach-communication~ai-3","moduleId":"fcp1-pediatric-approach-communication","stem":"How should a clinician approach a consultation with an adolescent patient?","options":[{"id":"a","text":"Focus solely on medical history"},{"id":"b","text":"Offer confidential time alone and screen with HEADSSS"},{"id":"c","text":"Ignore parental consent"},{"id":"d","text":"Avoid discussing psychosocial risks"}],"answerId":"b","explanation":"Adolescents need confidential time and psychosocial risk screening with HEADSSS, while working with consent and assent.","kind":"recall","origin":"ai"},{"id":"fcp1-pediatric-approach-communication~ai-4","moduleId":"fcp1-pediatric-approach-communication","stem":"Which of the following is an early sign of a seriously unwell child?","options":[{"id":"a","text":"Playing and interacting"},{"id":"b","text":"Listlessness and poor responsiveness"},{"id":"c","text":"Curiosity and engagement"},{"id":"d","text":"Consolability"}],"answerId":"b","explanation":"Listlessness and poor responsiveness indicate a seriously unwell child.","kind":"recall","origin":"ai"},{"id":"fcp1-pediatric-approach-communication~ai-5","moduleId":"fcp1-pediatric-approach-communication","stem":"In the context of pediatric consultations, how does the 'end-of-the-bed' assessment relate to developmental milestones?","options":[{"id":"a","text":"It is unrelated to developmental milestones"},{"id":"b","text":"It helps assess if the child's behavior is age-appropriate"},{"id":"c","text":"It focuses only on physical development"},{"id":"d","text":"It replaces the need for developmental milestone assessment"}],"answerId":"b","explanation":"The 'end-of-the-bed' assessment helps determine if a child's behavior is age-appropriate, complementing developmental milestone assessment.","kind":"integration","linkedModuleIds":["fcp1-development-milestones"],"origin":"ai"},{"id":"fcp1-pediatric-approach-communication~ai-6","moduleId":"fcp1-pediatric-approach-communication","stem":"How does offering confidential time to adolescents during consultations align with informed consent principles?","options":[{"id":"a","text":"It violates informed consent"},{"id":"b","text":"It is irrelevant to informed consent"},{"id":"c","text":"It supports informed consent by respecting autonomy"},{"id":"d","text":"It only applies to adult patients"}],"answerId":"c","explanation":"Offering confidential time supports informed consent by respecting the adolescent's autonomy and privacy.","kind":"integration","linkedModuleIds":["informed-consent-irb"],"origin":"ai"}],"fcp1-pediatric-history":[{"id":"fcp1-pediatric-history~ai-0","moduleId":"fcp1-pediatric-history","stem":"A 3-month-old infant presents with poor weight gain. The mother reports exclusive breastfeeding. Which aspect of the history is most crucial to explore next?","options":[{"id":"a","text":"Birth history"},{"id":"b","text":"Immunisation status"},{"id":"c","text":"Developmental milestones"},{"id":"d","text":"Family history"}],"answerId":"a","explanation":"Birth history, including birth weight and any perinatal complications, is crucial to assess potential causes of poor weight gain.","kind":"clinical","origin":"ai"},{"id":"fcp1-pediatric-history~ai-1","moduleId":"fcp1-pediatric-history","stem":"A 2-year-old child is brought in with a persistent cough. The mother mentions the child was born prematurely and required special-care admission. What is the most likely long-term complication related to this history?","options":[{"id":"a","text":"Developmental delay"},{"id":"b","text":"Chronic lung disease"},{"id":"c","text":"Congenital heart defect"},{"id":"d","text":"Recurrent ear infections"}],"answerId":"b","explanation":"Prematurity and special-care admission are risk factors for chronic lung disease.","kind":"mechanism","origin":"ai"},{"id":"fcp1-pediatric-history~ai-2","moduleId":"fcp1-pediatric-history","stem":"During a routine check-up, you find that a 6-month-old infant has not received any vaccinations. What is the most immediate risk for this child?","options":[{"id":"a","text":"Developmental delay"},{"id":"b","text":"Vaccine-preventable diseases"},{"id":"c","text":"Nutritional deficiencies"},{"id":"d","text":"Growth retardation"}],"answerId":"b","explanation":"Incomplete immunisation leaves the child exposed to vaccine-preventable diseases.","kind":"trap","origin":"ai"},{"id":"fcp1-pediatric-history~ai-3","moduleId":"fcp1-pediatric-history","stem":"A 4-year-old child presents with a history of recurrent infections. Which part of the paediatric history is most relevant to explore?","options":[{"id":"a","text":"Feeding history"},{"id":"b","text":"Immunisation record"},{"id":"c","text":"Birth order"},{"id":"d","text":"Developmental milestones"}],"answerId":"b","explanation":"An incomplete immunisation record could explain recurrent infections due to preventable diseases.","kind":"clinical","origin":"ai"},{"id":"fcp1-pediatric-history~ai-4","moduleId":"fcp1-pediatric-history","stem":"A mother reports that her 18-month-old child is not yet walking. Which module should be consulted to assess this developmental concern?","options":[{"id":"a","text":"Vaccines & Immunisation"},{"id":"b","text":"Developmental Milestones: The Four Domains & Red Flags"},{"id":"c","text":"Growth Assessment: Charts, Percentiles & Failure to Thrive"},{"id":"d","text":"Approaching the Child: Communication with Children & Families"}],"answerId":"b","explanation":"The module on developmental milestones provides guidance on expected milestones and red flags.","kind":"integration","linkedModuleIds":["fcp1-development-milestones"],"origin":"ai"},{"id":"fcp1-pediatric-history~ai-5","moduleId":"fcp1-pediatric-history","stem":"A 5-year-old child presents with jaundice. The child’s immunisation record is incomplete. Which linked module would provide information on potential vaccine-preventable causes of jaundice?","options":[{"id":"a","text":"Fetal Circulation and Transition at Birth"},{"id":"b","text":"Viral Hepatitis: Prevention & Immunisation"},{"id":"c","text":"Growth Assessment: Charts, Percentiles & Failure to Thrive"},{"id":"d","text":"Ancient → Renaissance Medicine: Hippocrates, Galen & the Birth of Observation"}],"answerId":"b","explanation":"The module on viral hepatitis and immunisation covers vaccine-preventable causes of jaundice.","kind":"integration","linkedModuleIds":["viral-hepatitis-prevention-immunization"],"origin":"ai"},{"id":"fcp1-pediatric-history~ai-6","moduleId":"fcp1-pediatric-history","stem":"Which of the following is a common trap when taking a paediatric history?","options":[{"id":"a","text":"Focusing only on the child's symptoms"},{"id":"b","text":"Including a detailed birth history"},{"id":"c","text":"Reviewing the immunisation record"},{"id":"d","text":"Assessing developmental milestones"}],"answerId":"a","explanation":"A common trap is focusing only on the child's symptoms and neglecting paediatric-specific history components.","kind":"trap","origin":"ai"}],"fcp1-history-taking-framework":[{"id":"fcp1-history-taking-framework~ai-0","moduleId":"fcp1-history-taking-framework","stem":"What is the primary purpose of the 'golden minute' in a clinical interview?","options":[{"id":"a","text":"To allow the patient to express their main concerns without interruption"},{"id":"b","text":"To quickly gather all necessary medical history"},{"id":"c","text":"To perform a rapid physical examination"},{"id":"d","text":"To immediately address the patient's expectations"}],"answerId":"a","explanation":"The 'golden minute' allows the patient to speak freely, often revealing their main concerns and the true agenda.","kind":"recall","origin":"ai"},{"id":"fcp1-history-taking-framework~ai-1","moduleId":"fcp1-history-taking-framework","stem":"Which of the following is a key component of the ICE framework in patient interviews?","options":[{"id":"a","text":"Ideas about the diagnosis"},{"id":"b","text":"Immediate treatment plan"},{"id":"c","text":"Insurance coverage"},{"id":"d","text":"Inpatient care requirements"}],"answerId":"a","explanation":"ICE stands for Ideas, Concerns, and Expectations, which helps uncover the patient's perspective and worries.","kind":"recall","origin":"ai"},{"id":"fcp1-history-taking-framework~ai-2","moduleId":"fcp1-history-taking-framework","stem":"During a history-taking session, a patient cannot provide a coherent account due to confusion. What is the best next step?","options":[{"id":"a","text":"Proceed with a physical examination"},{"id":"b","text":"Seek a collateral history from a relative or carer"},{"id":"c","text":"Order immediate diagnostic tests"},{"id":"d","text":"Conclude the interview and reschedule"}],"answerId":"b","explanation":"When a patient cannot provide a history due to confusion, obtaining a collateral history from a relative or carer is essential.","kind":"clinical","origin":"ai"},{"id":"fcp1-history-taking-framework~ai-3","moduleId":"fcp1-history-taking-framework","stem":"A medical student begins a patient interview with a checklist of closed yes/no questions. What is the primary risk of this approach?","options":[{"id":"a","text":"It may lead to a longer interview"},{"id":"b","text":"It suppresses the patient's narrative and misses the real agenda"},{"id":"c","text":"It is too time-consuming"},{"id":"d","text":"It may confuse the patient"}],"answerId":"b","explanation":"Starting with closed questions can suppress the patient's narrative, missing the real agenda and important information.","kind":"trap","origin":"ai"},{"id":"fcp1-history-taking-framework~ai-4","moduleId":"fcp1-history-taking-framework","stem":"Which of the following is a pertinent negative when taking a history for chest pain?","options":[{"id":"a","text":"Absence of fever"},{"id":"b","text":"Presence of cough"},{"id":"c","text":"History of smoking"},{"id":"d","text":"Family history of heart disease"}],"answerId":"a","explanation":"A pertinent negative, such as the absence of fever, helps narrow the differential diagnosis by ruling out certain conditions.","kind":"mechanism","origin":"ai"},{"id":"fcp1-history-taking-framework~ai-5","moduleId":"fcp1-history-taking-framework","stem":"In the context of history taking, how does the review of systems (ROS) contribute to the differential diagnosis?","options":[{"id":"a","text":"By confirming the patient's primary complaint"},{"id":"b","text":"By identifying symptoms the patient did not initially volunteer"},{"id":"c","text":"By providing a detailed family history"},{"id":"d","text":"By summarizing the patient's social history"}],"answerId":"b","explanation":"The ROS identifies additional symptoms that the patient did not initially mention, which can shape the differential diagnosis.","kind":"mechanism","origin":"ai"},{"id":"fcp1-history-taking-framework~ai-6","moduleId":"fcp1-history-taking-framework","stem":"In a pediatric history, what additional component is crucial compared to an adult history?","options":[{"id":"a","text":"Detailed occupational history"},{"id":"b","text":"Birth and developmental history"},{"id":"c","text":"Detailed travel history"},{"id":"d","text":"Comprehensive financial status"}],"answerId":"b","explanation":"In pediatric history-taking, birth and developmental history are crucial components that are not typically required in adult histories.","kind":"integration","linkedModuleIds":["fcp1-pediatric-history"],"origin":"ai"},{"id":"fcp1-history-taking-framework~ai-7","moduleId":"fcp1-history-taking-framework","stem":"When analyzing a symptom such as pain, which framework is most useful for detailed exploration?","options":[{"id":"a","text":"SOAP"},{"id":"b","text":"SOCRATES"},{"id":"c","text":"ABCDE"},{"id":"d","text":"OLDCARTS"}],"answerId":"b","explanation":"The SOCRATES framework is used for detailed symptom analysis, particularly for pain, covering aspects like site, onset, and character.","kind":"integration","linkedModuleIds":["fcp1-history-symptom-analysis"],"origin":"ai"}],"fcp1-history-symptom-analysis":[{"id":"fcp1-history-symptom-analysis~ai-0","moduleId":"fcp1-history-symptom-analysis","stem":"A 45-year-old man presents with sudden onset of severe chest pain described as 'tearing' and radiating to his back. Which of the following is the most likely diagnosis?","options":[{"id":"a","text":"Aortic dissection"},{"id":"b","text":"Myocardial infarction"},{"id":"c","text":"Pulmonary embolism"},{"id":"d","text":"Pneumothorax"}],"answerId":"a","explanation":"Tearing chest pain radiating to the back is characteristic of aortic dissection.","kind":"recall","origin":"ai"},{"id":"fcp1-history-symptom-analysis~ai-1","moduleId":"fcp1-history-symptom-analysis","stem":"A patient reports intermittent abdominal pain that comes in waves and is associated with nausea. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Peristalsis against obstruction"},{"id":"b","text":"Ischemic bowel"},{"id":"c","text":"Inflammatory bowel disease"},{"id":"d","text":"Peptic ulcer disease"}],"answerId":"a","explanation":"Colicky, waxing-and-waning pain suggests peristalsis against an obstructed hollow viscus.","kind":"mechanism","origin":"ai"},{"id":"fcp1-history-symptom-analysis~ai-2","moduleId":"fcp1-history-symptom-analysis","stem":"Which of the following symptom descriptions most strongly suggests a vascular or mechanical catastrophe?","options":[{"id":"a","text":"Gradual onset and progressive"},{"id":"b","text":"Sudden onset and maximal at onset"},{"id":"c","text":"Intermittent and variable intensity"},{"id":"d","text":"Persistent and dull"}],"answerId":"b","explanation":"A sudden, maximal-at-onset symptom suggests a vascular or mechanical event.","kind":"trap","origin":"ai"},{"id":"fcp1-history-symptom-analysis~ai-3","moduleId":"fcp1-history-symptom-analysis","stem":"A 60-year-old woman presents with a headache that started suddenly and is described as the 'worst ever'. Which of the following should be your primary concern?","options":[{"id":"a","text":"Migraine"},{"id":"b","text":"Tension headache"},{"id":"c","text":"Subarachnoid hemorrhage"},{"id":"d","text":"Cluster headache"}],"answerId":"c","explanation":"A sudden, severe headache described as 'worst ever' is indicative of a subarachnoid hemorrhage.","kind":"clinical","origin":"ai"},{"id":"fcp1-history-symptom-analysis~ai-4","moduleId":"fcp1-history-symptom-analysis","stem":"In the context of symptom analysis, what does the 'A' in SOCRATES stand for?","options":[{"id":"a","text":"Associations"},{"id":"b","text":"Aggravating factors"},{"id":"c","text":"Alleviating factors"},{"id":"d","text":"Anatomy"}],"answerId":"a","explanation":"In SOCRATES, 'A' stands for Associations, referring to associated symptoms.","kind":"recall","origin":"ai"},{"id":"fcp1-history-symptom-analysis~ai-5","moduleId":"fcp1-history-symptom-analysis","stem":"A patient presents with chest pain that is reproducible on palpation. Which of the following is the most likely source of the pain?","options":[{"id":"a","text":"Cardiac"},{"id":"b","text":"Musculoskeletal"},{"id":"c","text":"Pulmonary"},{"id":"d","text":"Gastrointestinal"}],"answerId":"b","explanation":"Pain reproduced by palpation suggests a musculoskeletal source.","kind":"mechanism","origin":"ai"},{"id":"fcp1-history-symptom-analysis~ai-6","moduleId":"fcp1-history-symptom-analysis","stem":"During a patient interview, you document pertinent negatives for chest pain. Which of the following is a pertinent negative that would argue against myocardial infarction?","options":[{"id":"a","text":"Absence of diaphoresis"},{"id":"b","text":"Absence of radiation to the arm"},{"id":"c","text":"Absence of nausea"},{"id":"d","text":"Absence of dyspnea"}],"answerId":"b","explanation":"Absence of radiation to the arm is a pertinent negative that argues against myocardial infarction.","kind":"clinical","origin":"ai"},{"id":"fcp1-history-symptom-analysis~ai-7","moduleId":"fcp1-history-symptom-analysis","stem":"When taking a patient's history, you use the SOCRATES framework. How does this integrate with the overall history-taking process?","options":[{"id":"a","text":"It replaces the need for a full history"},{"id":"b","text":"It provides a structured approach to symptom analysis"},{"id":"c","text":"It is only used for pain assessment"},{"id":"d","text":"It is not related to history-taking"}],"answerId":"b","explanation":"SOCRATES provides a structured approach to symptom analysis within the broader history-taking framework.","kind":"integration","linkedModuleIds":["fcp1-history-taking-framework"],"origin":"ai"},{"id":"fcp1-history-symptom-analysis~ai-8","moduleId":"fcp1-history-symptom-analysis","stem":"A patient describes their headache as gradual in onset and progressively worsening over days. Which of the following processes is most likely responsible?","options":[{"id":"a","text":"Vascular event"},{"id":"b","text":"Infective process"},{"id":"c","text":"Mechanical obstruction"},{"id":"d","text":"Neoplastic process"}],"answerId":"c","explanation":"A gradual onset and progressive worsening suggest a neoplastic or inflammatory process.","kind":"integration","linkedModuleIds":["fcp1-history-taking-framework"],"origin":"ai"}],"fcp1-growth-assessment":[{"id":"fcp1-growth-assessment~ai-0","moduleId":"fcp1-growth-assessment","stem":"A 2-year-old boy presents with weight crossing down two major centile lines over the past 6 months. His height and head circumference are relatively preserved. What is the most likely underlying issue?","options":[{"id":"a","text":"Inadequate caloric intake"},{"id":"b","text":"Growth hormone deficiency"},{"id":"c","text":"Familial short stature"},{"id":"d","text":"Constitutional growth delay"}],"answerId":"a","explanation":"Weight faltering with preserved height and head circumference suggests inadequate caloric intake.","kind":"clinical","origin":"ai"},{"id":"fcp1-growth-assessment~ai-1","moduleId":"fcp1-growth-assessment","stem":"Which of the following is a red flag in growth assessment?","options":[{"id":"a","text":"A child consistently tracking along the 3rd centile"},{"id":"b","text":"A child with head circumference dropping across centiles"},{"id":"c","text":"A child with height on the 10th centile and weight on the 25th centile"},{"id":"d","text":"A child with weight and height both on the 5th centile"}],"answerId":"b","explanation":"A falling head circumference raises concern for neurodevelopmental issues.","kind":"recall","origin":"ai"},{"id":"fcp1-growth-assessment~ai-2","moduleId":"fcp1-growth-assessment","stem":"A 5-year-old girl is symmetrically small and tracks steadily along the 5th centile for weight and height. Her mid-parental height is also low. What is the most likely diagnosis?","options":[{"id":"a","text":"Constitutional growth delay"},{"id":"b","text":"Familial short stature"},{"id":"c","text":"Growth hormone deficiency"},{"id":"d","text":"Failure to thrive"}],"answerId":"b","explanation":"Symmetrical growth along a low centile with low mid-parental height suggests familial short stature.","kind":"clinical","origin":"ai"},{"id":"fcp1-growth-assessment~ai-3","moduleId":"fcp1-growth-assessment","stem":"Which measurement pattern is most indicative of failure to thrive?","options":[{"id":"a","text":"Weight crossing down two major centile lines"},{"id":"b","text":"Height consistently on the 3rd centile"},{"id":"c","text":"Head circumference on the 50th centile"},{"id":"d","text":"Weight and height both on the 10th centile"}],"answerId":"a","explanation":"Failure to thrive is indicated by weight crossing down two or more major centile lines.","kind":"recall","origin":"ai"},{"id":"fcp1-growth-assessment~ai-4","moduleId":"fcp1-growth-assessment","stem":"A 3-year-old child presents with weight faltering. Which linked module would provide guidance on assessing dietary intake and nutritional status?","options":[{"id":"a","text":"obesity-insulin-resistance"},{"id":"b","text":"fcp1-nutritional-assessment"},{"id":"c","text":"fcp1-development-milestones"},{"id":"d","text":"fcp1-pediatric-history"}],"answerId":"b","explanation":"The 'fcp1-nutritional-assessment' module provides guidance on assessing dietary intake and nutritional status.","kind":"integration","linkedModuleIds":["fcp1-nutritional-assessment"],"origin":"ai"},{"id":"fcp1-growth-assessment~ai-5","moduleId":"fcp1-growth-assessment","stem":"A child with a falling head circumference should be evaluated for neurodevelopmental concerns. Which module would assist in assessing developmental milestones?","options":[{"id":"a","text":"fcp1-malnutrition-evaluation"},{"id":"b","text":"fcp1-development-milestones"},{"id":"c","text":"obesity-insulin-resistance"},{"id":"d","text":"fcp1-pediatric-history"}],"answerId":"b","explanation":"The 'fcp1-development-milestones' module assists in assessing developmental milestones.","kind":"integration","linkedModuleIds":["fcp1-development-milestones"],"origin":"ai"}],"fcp1-nutritional-assessment":[{"id":"fcp1-nutritional-assessment~ai-0","moduleId":"fcp1-nutritional-assessment","stem":"Which component of the ABCD nutritional assessment involves evaluating mid-upper-arm circumference (MUAC)?","options":[{"id":"a","text":"Anthropometry"},{"id":"b","text":"Biochemical"},{"id":"c","text":"Clinical"},{"id":"d","text":"Dietary"}],"answerId":"a","explanation":"MUAC is a measure of body composition and is part of the anthropometric assessment.","kind":"recall","origin":"ai"},{"id":"fcp1-nutritional-assessment~ai-1","moduleId":"fcp1-nutritional-assessment","stem":"A patient presents with angular cheilitis and glossitis. Which deficiency is most likely responsible for these findings?","options":[{"id":"a","text":"Vitamin C deficiency"},{"id":"b","text":"Vitamin B12 deficiency"},{"id":"c","text":"Iron deficiency"},{"id":"d","text":"Vitamin D deficiency"}],"answerId":"c","explanation":"Angular cheilitis and glossitis are clinical signs associated with iron deficiency.","kind":"clinical","origin":"ai"},{"id":"fcp1-nutritional-assessment~ai-2","moduleId":"fcp1-nutritional-assessment","stem":"Why is albumin not a reliable stand-alone marker of nutritional status?","options":[{"id":"a","text":"It is unaffected by inflammation"},{"id":"b","text":"It is a positive acute-phase reactant"},{"id":"c","text":"It is a negative acute-phase reactant"},{"id":"d","text":"It directly measures dietary intake"}],"answerId":"c","explanation":"Albumin is a negative acute-phase reactant and decreases with inflammation, making it unreliable for assessing nutrition alone.","kind":"trap","origin":"ai"},{"id":"fcp1-nutritional-assessment~ai-3","moduleId":"fcp1-nutritional-assessment","stem":"A child presents with a BMI below the 5th percentile for age. Which linked module would provide additional guidance on assessing growth concerns?","options":[{"id":"a","text":"fcp1-weight-loss-approach"},{"id":"b","text":"fcp1-anemia-microcytic"},{"id":"c","text":"fcp1-growth-assessment"},{"id":"d","text":"fcp1-malnutrition-evaluation"}],"answerId":"c","explanation":"The 'fcp1-growth-assessment' module provides guidance on interpreting growth charts and percentiles.","kind":"integration","linkedModuleIds":["fcp1-growth-assessment"],"origin":"ai"},{"id":"fcp1-nutritional-assessment~ai-4","moduleId":"fcp1-nutritional-assessment","stem":"In the ABCD approach, which component is primarily concerned with identifying social factors affecting nutrition?","options":[{"id":"a","text":"Anthropometry"},{"id":"b","text":"Biochemical"},{"id":"c","text":"Clinical"},{"id":"d","text":"Dietary"}],"answerId":"d","explanation":"The dietary component includes assessing social factors like poverty and isolation that affect nutrition.","kind":"recall","origin":"ai"},{"id":"fcp1-nutritional-assessment~ai-5","moduleId":"fcp1-nutritional-assessment","stem":"A patient with a history of chronic alcohol use is at risk for refeeding syndrome. Which linked module would provide further information on managing this risk?","options":[{"id":"a","text":"fcp1-growth-assessment"},{"id":"b","text":"fcp1-weight-loss-approach"},{"id":"c","text":"fcp1-malnutrition-evaluation"},{"id":"d","text":"fcp1-pediatric-history"}],"answerId":"c","explanation":"The 'fcp1-malnutrition-evaluation' module covers the management of refeeding syndrome.","kind":"integration","linkedModuleIds":["fcp1-malnutrition-evaluation"],"origin":"ai"},{"id":"fcp1-nutritional-assessment~ai-6","moduleId":"fcp1-nutritional-assessment","stem":"Which of the following findings is a quantified marker of a clinically significant nutritional problem?","options":[{"id":"a","text":"BMI of 20"},{"id":"b","text":"Unintentional weight loss of 3%"},{"id":"c","text":"Unintentional weight loss of 8%"},{"id":"d","text":"MUAC within normal range"}],"answerId":"c","explanation":"Unintentional weight loss exceeding 5–10% of body weight is significant.","kind":"clinical","origin":"ai"}],"fcp1-malnutrition-evaluation":[{"id":"fcp1-malnutrition-evaluation~ai-0","moduleId":"fcp1-malnutrition-evaluation","stem":"A 3-year-old child presents with severe wasting, an 'old-man' face, and no oedema. What is the most likely diagnosis?","options":[{"id":"a","text":"Marasmus"},{"id":"b","text":"Kwashiorkor"},{"id":"c","text":"Refeeding syndrome"},{"id":"d","text":"Vitamin A deficiency"}],"answerId":"a","explanation":"Marasmus is characterized by severe wasting, loss of muscle and fat, and no oedema.","kind":"recall","origin":"ai"},{"id":"fcp1-malnutrition-evaluation~ai-1","moduleId":"fcp1-malnutrition-evaluation","stem":"Which of the following is a classic sign of kwashiorkor?","options":[{"id":"a","text":"Bilateral pitting oedema"},{"id":"b","text":"Night blindness"},{"id":"c","text":"Severe wasting"},{"id":"d","text":"Bleeding gums"}],"answerId":"a","explanation":"Bilateral pitting oedema is a hallmark of kwashiorkor.","kind":"recall","origin":"ai"},{"id":"fcp1-malnutrition-evaluation~ai-2","moduleId":"fcp1-malnutrition-evaluation","stem":"A malnourished patient is started on a refeeding regimen. Which electrolyte imbalance is most critical to monitor?","options":[{"id":"a","text":"Hypophosphataemia"},{"id":"b","text":"Hypercalcaemia"},{"id":"c","text":"Hyponatraemia"},{"id":"d","text":"Hypermagnesaemia"}],"answerId":"a","explanation":"Hypophosphataemia is a critical concern in refeeding syndrome due to insulin-driven shifts.","kind":"mechanism","origin":"ai"},{"id":"fcp1-malnutrition-evaluation~ai-3","moduleId":"fcp1-malnutrition-evaluation","stem":"A child presents with bilateral pitting oedema and a 'flaky-paint' dermatosis. What nutritional deficiency is most likely?","options":[{"id":"a","text":"Protein deficiency"},{"id":"b","text":"Vitamin C deficiency"},{"id":"c","text":"Iron deficiency"},{"id":"d","text":"Zinc deficiency"}],"answerId":"a","explanation":"Kwashiorkor, characterized by oedema and skin changes, is due to protein deficiency.","kind":"clinical","origin":"ai"},{"id":"fcp1-malnutrition-evaluation~ai-4","moduleId":"fcp1-malnutrition-evaluation","stem":"In the context of malnutrition, which of the following is a misconception about refeeding?","options":[{"id":"a","text":"Start feeding low and slow"},{"id":"b","text":"Aggressive refeeding is necessary"},{"id":"c","text":"Monitor electrolytes closely"},{"id":"d","text":"Administer thiamine before refeeding"}],"answerId":"b","explanation":"Aggressive refeeding can trigger refeeding syndrome; a cautious approach is required.","kind":"trap","origin":"ai"},{"id":"fcp1-malnutrition-evaluation~ai-5","moduleId":"fcp1-malnutrition-evaluation","stem":"A 4-year-old with severe acute malnutrition is evaluated. Which measurement confirms this diagnosis according to WHO criteria?","options":[{"id":"a","text":"MUAC below 115 mm"},{"id":"b","text":"Weight-for-height Z-score above −2"},{"id":"c","text":"Height-for-age Z-score below −2"},{"id":"d","text":"Bilateral non-pitting oedema"}],"answerId":"a","explanation":"MUAC below 115 mm is one of the WHO criteria for severe acute malnutrition.","kind":"recall","origin":"ai"},{"id":"fcp1-malnutrition-evaluation~ai-6","moduleId":"fcp1-malnutrition-evaluation","stem":"A child with marasmus is at risk of developing which condition upon rapid refeeding?","options":[{"id":"a","text":"Refeeding syndrome"},{"id":"b","text":"Kwashiorkor"},{"id":"c","text":"Vitamin D deficiency"},{"id":"d","text":"Iron overload"}],"answerId":"a","explanation":"Rapid refeeding can lead to refeeding syndrome, characterized by electrolyte imbalances.","kind":"integration","linkedModuleIds":["nutrition-energy-protein-malnutrition"],"origin":"ai"},{"id":"fcp1-malnutrition-evaluation~ai-7","moduleId":"fcp1-malnutrition-evaluation","stem":"Which of the following conditions can present with bilateral pitting oedema, linking it to both malnutrition and another module?","options":[{"id":"a","text":"Kwashiorkor"},{"id":"b","text":"Pulmonary embolism"},{"id":"c","text":"Marasmus"},{"id":"d","text":"Vitamin C deficiency"}],"answerId":"a","explanation":"Kwashiorkor presents with oedema, which is also discussed in the context of oedema mechanisms.","kind":"integration","linkedModuleIds":["fcp1-edema-mechanisms"],"origin":"ai"}],"fcp1-development-milestones":[{"id":"fcp1-development-milestones~ai-0","moduleId":"fcp1-development-milestones","stem":"A 10-month-old infant has not yet started to sit unsupported. What is the most appropriate next step?","options":[{"id":"a","text":"Evaluate for developmental delay"},{"id":"b","text":"Reassure parents and schedule a follow-up"},{"id":"c","text":"Begin physical therapy immediately"},{"id":"d","text":"Assess for early hand preference"}],"answerId":"a","explanation":"Not sitting by 9 months is a red flag for developmental delay, warranting further evaluation.","kind":"clinical","origin":"ai"},{"id":"fcp1-development-milestones~ai-1","moduleId":"fcp1-development-milestones","stem":"Which of the following developmental milestones is expected to occur by 12 months of age?","options":[{"id":"a","text":"Social smile"},{"id":"b","text":"Sitting unsupported"},{"id":"c","text":"Walking independently"},{"id":"d","text":"First words"}],"answerId":"d","explanation":"First words typically occur around 12 months of age, making it a key milestone.","kind":"recall","origin":"ai"},{"id":"fcp1-development-milestones~ai-2","moduleId":"fcp1-development-milestones","stem":"A 15-month-old child has not yet spoken any words. What should be the initial investigation?","options":[{"id":"a","text":"Genetic testing"},{"id":"b","text":"Hearing test"},{"id":"c","text":"Neurological examination"},{"id":"d","text":"Speech therapy referral"}],"answerId":"b","explanation":"An isolated speech delay should first prompt a hearing test to rule out reversible causes.","kind":"trap","origin":"ai"},{"id":"fcp1-development-milestones~ai-3","moduleId":"fcp1-development-milestones","stem":"A 9-month-old infant shows a preference for using the left hand exclusively. What does this suggest?","options":[{"id":"a","text":"Normal development"},{"id":"b","text":"Possible hemiplegia"},{"id":"c","text":"Early language development"},{"id":"d","text":"Delayed motor skills"}],"answerId":"b","explanation":"Established hand preference before 12 months suggests possible hemiplegia due to relative weakness on the other side.","kind":"mechanism","origin":"ai"},{"id":"fcp1-development-milestones~ai-4","moduleId":"fcp1-development-milestones","stem":"A 2-year-old child uses two-word phrases. What does this indicate regarding their language development?","options":[{"id":"a","text":"Delayed language development"},{"id":"b","text":"Normal language development"},{"id":"c","text":"Advanced language development"},{"id":"d","text":"Possible hearing impairment"}],"answerId":"b","explanation":"Using two-word phrases by 2 years is considered normal language development.","kind":"recall","origin":"ai"},{"id":"fcp1-development-milestones~ai-5","moduleId":"fcp1-development-milestones","stem":"A 20-month-old child has not started walking independently. Which condition should be considered?","options":[{"id":"a","text":"Cerebral palsy"},{"id":"b","text":"Autism spectrum disorder"},{"id":"c","text":"Hearing impairment"},{"id":"d","text":"Speech delay"}],"answerId":"a","explanation":"Not walking by 18 months is a gross motor red flag, and cerebral palsy should be considered among other neuromuscular causes.","kind":"clinical","origin":"ai"},{"id":"fcp1-development-milestones~ai-6","moduleId":"fcp1-development-milestones","stem":"A 3-year-old child has lost previously acquired language skills. What is the most likely underlying process?","options":[{"id":"a","text":"Normal variation"},{"id":"b","text":"Neurodegenerative disorder"},{"id":"c","text":"Isolated speech delay"},{"id":"d","text":"Hearing loss"}],"answerId":"b","explanation":"Regression, such as loss of language skills, suggests a neurodegenerative or metabolic process.","kind":"mechanism","origin":"ai"},{"id":"fcp1-development-milestones~ai-7","moduleId":"fcp1-development-milestones","stem":"During a pediatric history, a parent reports their 18-month-old child has not yet spoken any words. Which linked module provides guidance on further history taking?","options":[{"id":"a","text":"fcp1-growth-assessment"},{"id":"b","text":"fcp1-pediatric-history"},{"id":"c","text":"fcp1-pediatric-approach-communication"},{"id":"d","text":"fcp1-development-milestones"}],"answerId":"b","explanation":"The 'fcp1-pediatric-history' module covers comprehensive history taking, including developmental concerns.","kind":"integration","linkedModuleIds":["fcp1-pediatric-history"],"origin":"ai"},{"id":"fcp1-development-milestones~ai-8","moduleId":"fcp1-development-milestones","stem":"A 6-month-old preterm infant, born at 32 weeks gestation, is being evaluated for developmental milestones. How should the milestones be assessed?","options":[{"id":"a","text":"Using chronological age"},{"id":"b","text":"Using corrected age"},{"id":"c","text":"Using adjusted growth charts"},{"id":"d","text":"Using parental reports"}],"answerId":"b","explanation":"For preterm infants, milestones should be assessed using corrected age until about two years to avoid mislabeling delays.","kind":"trap","origin":"ai"}],"fcp1-fever-of-unknown-origin":[{"id":"fcp1-fever-of-unknown-origin~ai-0","moduleId":"fcp1-fever-of-unknown-origin","stem":"A 70-year-old man presents with a 4-week history of fever, weight loss, and night sweats. Physical examination reveals temporal artery tenderness and jaw claudication. What is the most appropriate next step in management?","options":[{"id":"a","text":"Start high-dose corticosteroids"},{"id":"b","text":"Order blood cultures"},{"id":"c","text":"Perform a temporal artery biopsy"},{"id":"d","text":"Start empiric antibiotics"}],"answerId":"a","explanation":"In suspected giant-cell arteritis with visual symptoms, corticosteroids should be started promptly to prevent vision loss.","kind":"clinical","origin":"ai"},{"id":"fcp1-fever-of-unknown-origin~ai-1","moduleId":"fcp1-fever-of-unknown-origin","stem":"Which of the following is NOT a common cause of fever of unknown origin (FUO) in the elderly?","options":[{"id":"a","text":"Giant-cell arteritis"},{"id":"b","text":"Lymphoma"},{"id":"c","text":"Adult-onset Still disease"},{"id":"d","text":"Renal cell carcinoma"}],"answerId":"c","explanation":"Adult-onset Still disease is more common in younger patients, whereas giant-cell arteritis, lymphoma, and renal cell carcinoma are common FUO causes in the elderly.","kind":"recall","origin":"ai"},{"id":"fcp1-fever-of-unknown-origin~ai-2","moduleId":"fcp1-fever-of-unknown-origin","stem":"A patient with FUO has a new heart murmur. Which condition should be considered?","options":[{"id":"a","text":"Infective endocarditis"},{"id":"b","text":"Giant-cell arteritis"},{"id":"c","text":"Drug fever"},{"id":"d","text":"Lymphoma"}],"answerId":"a","explanation":"A new or changing heart murmur in the context of FUO suggests infective endocarditis.","kind":"mechanism","origin":"ai"},{"id":"fcp1-fever-of-unknown-origin~ai-3","moduleId":"fcp1-fever-of-unknown-origin","stem":"In the evaluation of FUO, why is it important to avoid empiric antibiotics before a diagnosis is made?","options":[{"id":"a","text":"They can cause drug fever"},{"id":"b","text":"They mask the symptoms of endocarditis"},{"id":"c","text":"They are ineffective against viral infections"},{"id":"d","text":"They increase the risk of antibiotic resistance"}],"answerId":"b","explanation":"Empiric antibiotics can mask the symptoms of conditions like endocarditis, delaying diagnosis and appropriate treatment.","kind":"trap","origin":"ai"},{"id":"fcp1-fever-of-unknown-origin~ai-4","moduleId":"fcp1-fever-of-unknown-origin","stem":"A 45-year-old woman with FUO has lymphadenopathy and hepatosplenomegaly. Which diagnostic test should be prioritized?","options":[{"id":"a","text":"FDG-PET scan"},{"id":"b","text":"Lymph node biopsy"},{"id":"c","text":"Bone marrow biopsy"},{"id":"d","text":"Serum electrophoresis"}],"answerId":"b","explanation":"Lymphadenopathy and hepatosplenomegaly raise suspicion for lymphoma, making a lymph node biopsy the most direct diagnostic approach.","kind":"clinical","origin":"ai"},{"id":"fcp1-fever-of-unknown-origin~ai-5","moduleId":"fcp1-fever-of-unknown-origin","stem":"A patient with FUO presents with hypercalcemia. Which linked module should be consulted for further evaluation?","options":[{"id":"a","text":"Parathyroid Hormone-Related Protein (PTHrP) and Hypercalcemia of Malignancy"},{"id":"b","text":"Approach to Lymphadenopathy"},{"id":"c","text":"Approach to Acute Fever"},{"id":"d","text":"Fever: Thermoregulation & Pathophysiology"}],"answerId":"a","explanation":"Hypercalcemia in the context of FUO may suggest malignancy, and the linked module on PTHrP and hypercalcemia can provide further insights.","kind":"integration","linkedModuleIds":["add-parathyroid-hormone-related-protein-pthrp-and-hypercalce"],"origin":"ai"},{"id":"fcp1-fever-of-unknown-origin~ai-6","moduleId":"fcp1-fever-of-unknown-origin","stem":"A 60-year-old patient with FUO reports significant weight loss. Which linked module should be reviewed to guide further investigation?","options":[{"id":"a","text":"Approach to Unintentional Weight Loss"},{"id":"b","text":"Approach to Lymphadenopathy"},{"id":"c","text":"Approach to Acute Fever"},{"id":"d","text":"Fever: Thermoregulation & Pathophysiology"}],"answerId":"a","explanation":"Weight loss in FUO can indicate malignancy or chronic infection, and the linked module on weight loss provides a structured approach.","kind":"integration","linkedModuleIds":["fcp1-weight-loss-approach"],"origin":"ai"}],"fcp1-obgyne-history":[{"id":"fcp1-obgyne-history~ai-0","moduleId":"fcp1-obgyne-history","stem":"A 28-year-old woman presents with lower abdominal pain and spotting. Her last menstrual period was 8 weeks ago. What is the most critical initial test?","options":[{"id":"a","text":"Urine β-hCG test"},{"id":"b","text":"Transvaginal ultrasound"},{"id":"c","text":"Complete blood count"},{"id":"d","text":"Pelvic examination"}],"answerId":"a","explanation":"In any reproductive-age woman with abdominal pain or abnormal bleeding, a pregnancy test is essential to exclude pregnancy and potential ectopic pregnancy.","kind":"trap","origin":"ai"},{"id":"fcp1-obgyne-history~ai-1","moduleId":"fcp1-obgyne-history","stem":"A 32-year-old woman reports postcoital bleeding. What is the most appropriate next step in management?","options":[{"id":"a","text":"Perform a cervical smear test"},{"id":"b","text":"Order a pelvic ultrasound"},{"id":"c","text":"Initiate antibiotic therapy"},{"id":"d","text":"Advise hormonal contraception"}],"answerId":"a","explanation":"Postcoital bleeding suggests cervical pathology, warranting a cervical smear test to screen for cervical abnormalities.","kind":"clinical","origin":"ai"},{"id":"fcp1-obgyne-history~ai-2","moduleId":"fcp1-obgyne-history","stem":"Which component of the OB-Gyne history is crucial for assessing the risk of pregnancy?","options":[{"id":"a","text":"Age at menarche"},{"id":"b","text":"Last menstrual period"},{"id":"c","text":"History of dysmenorrhea"},{"id":"d","text":"Previous contraceptive use"}],"answerId":"b","explanation":"The last menstrual period (LMP) is essential for assessing pregnancy risk and timing.","kind":"recall","origin":"ai"},{"id":"fcp1-obgyne-history~ai-3","moduleId":"fcp1-obgyne-history","stem":"A 25-year-old woman presents with heavy menstrual bleeding. Which part of her history is most relevant to determine the cause?","options":[{"id":"a","text":"Age at menarche"},{"id":"b","text":"Intermenstrual bleeding"},{"id":"c","text":"Sexual history"},{"id":"d","text":"Family history of bleeding disorders"}],"answerId":"b","explanation":"Intermenstrual bleeding can indicate structural or hormonal causes of abnormal uterine bleeding.","kind":"mechanism","origin":"ai"},{"id":"fcp1-obgyne-history~ai-4","moduleId":"fcp1-obgyne-history","stem":"A 30-year-old woman with a history of two pregnancies, one miscarriage, and one living child presents for a routine check-up. How would you summarize her obstetric history using GPAL notation?","options":[{"id":"a","text":"G2P1A1L1"},{"id":"b","text":"G3P1A1L1"},{"id":"c","text":"G3P2A0L1"},{"id":"d","text":"G2P2A0L1"}],"answerId":"b","explanation":"GPAL notation summarizes her history as 3 pregnancies (G3), 1 birth beyond viability (P1), 1 abortion/miscarriage (A1), and 1 living child (L1).","kind":"recall","origin":"ai"},{"id":"fcp1-obgyne-history~ai-5","moduleId":"fcp1-obgyne-history","stem":"A 29-year-old woman presents with severe dysmenorrhea and menorrhagia. Which linked module would provide the most relevant additional information?","options":[{"id":"a","text":"fcp1-abnormal-vaginal-bleeding"},{"id":"b","text":"hrp2-dysmenorrhea-menorrhagia"},{"id":"c","text":"fcp1-pelvic-pain-approach"},{"id":"d","text":"fcp1-obgyne-history"}],"answerId":"b","explanation":"The module 'hrp2-dysmenorrhea-menorrhagia' focuses on the clinical application of dysmenorrhea and heavy menstrual bleeding.","kind":"integration","linkedModuleIds":["hrp2-dysmenorrhea-menorrhagia"],"origin":"ai"},{"id":"fcp1-obgyne-history~ai-6","moduleId":"fcp1-obgyne-history","stem":"A 34-year-old woman presents with pelvic pain and a history of irregular menstrual cycles. Which linked module would help in further evaluating her condition?","options":[{"id":"a","text":"fcp1-abnormal-vaginal-bleeding"},{"id":"b","text":"hrp2-dysmenorrhea-menorrhagia"},{"id":"c","text":"fcp1-pelvic-pain-approach"},{"id":"d","text":"fcp1-obgyne-history"}],"answerId":"c","explanation":"The module 'fcp1-pelvic-pain-approach' provides a structured approach to evaluating pelvic pain, which is relevant to her symptoms.","kind":"integration","linkedModuleIds":["fcp1-pelvic-pain-approach"],"origin":"ai"}],"fcp1-fever-approach-differential":[{"id":"fcp1-fever-approach-differential~ai-0","moduleId":"fcp1-fever-approach-differential","stem":"A 25-year-old man presents with fever, neck stiffness, and a non-blanching petechial rash. What is the most likely diagnosis?","options":[{"id":"a","text":"Meningococcaemia"},{"id":"b","text":"Typhoid fever"},{"id":"c","text":"Viral meningitis"},{"id":"d","text":"Rocky Mountain spotted fever"}],"answerId":"a","explanation":"The combination of fever, neck stiffness, and a non-blanching petechial rash is classic for meningococcaemia.","kind":"clinical","origin":"ai"},{"id":"fcp1-fever-approach-differential~ai-1","moduleId":"fcp1-fever-approach-differential","stem":"Which of the following is a critical first step in the workup of a febrile patient before administering antibiotics?","options":[{"id":"a","text":"Administer broad-spectrum antibiotics"},{"id":"b","text":"Perform a lumbar puncture"},{"id":"c","text":"Draw blood cultures"},{"id":"d","text":"Order a CT scan"}],"answerId":"c","explanation":"Blood cultures should be drawn before antibiotics to avoid sterilizing the sample and losing the microbiological diagnosis.","kind":"trap","origin":"ai"},{"id":"fcp1-fever-approach-differential~ai-2","moduleId":"fcp1-fever-approach-differential","stem":"A patient with fever and relative bradycardia is most likely suffering from which condition?","options":[{"id":"a","text":"Meningococcal infection"},{"id":"b","text":"Typhoid fever"},{"id":"c","text":"Viral infection"},{"id":"d","text":"Bacterial pneumonia"}],"answerId":"b","explanation":"Relative bradycardia with fever is characteristic of typhoid fever or infections with intracellular organisms.","kind":"recall","origin":"ai"},{"id":"fcp1-fever-approach-differential~ai-3","moduleId":"fcp1-fever-approach-differential","stem":"A 30-year-old woman with a history of recent travel to Southeast Asia presents with fever and altered mentation. Which test is most appropriate to include in the initial workup?","options":[{"id":"a","text":"Malaria film"},{"id":"b","text":"Echocardiogram"},{"id":"c","text":"CT scan of the abdomen"},{"id":"d","text":"Skin biopsy"}],"answerId":"a","explanation":"A malaria film is crucial for any febrile patient with a history of travel to malaria-endemic regions.","kind":"recall","origin":"ai"},{"id":"fcp1-fever-approach-differential~ai-4","moduleId":"fcp1-fever-approach-differential","stem":"In the context of acute fever, what does the presence of atypical lymphocytes on a CBC suggest?","options":[{"id":"a","text":"Bacterial infection"},{"id":"b","text":"Viral infection"},{"id":"c","text":"Fungal infection"},{"id":"d","text":"Parasitic infection"}],"answerId":"b","explanation":"Atypical lymphocytes are commonly associated with viral infections.","kind":"mechanism","origin":"ai"},{"id":"fcp1-fever-approach-differential~ai-5","moduleId":"fcp1-fever-approach-differential","stem":"A 45-year-old man presents with fever, hypotension, and tachypnea. Which linked module should be consulted for management strategies?","options":[{"id":"a","text":"Salmonella, Shigella & Yersinia"},{"id":"b","text":"Recognition & Initial Management of Shock"},{"id":"c","text":"Nonbacterial Endocarditis"},{"id":"d","text":"Fever: Thermoregulation & Pathophysiology"}],"answerId":"b","explanation":"The 'Recognition & Initial Management of Shock' module provides strategies for managing septic shock, which is suggested by the symptoms.","kind":"integration","linkedModuleIds":["fcp1-shock-management"],"origin":"ai"},{"id":"fcp1-fever-approach-differential~ai-6","moduleId":"fcp1-fever-approach-differential","stem":"A patient with a history of prosthetic heart valve presents with fever and new-onset heart murmur. Which linked module is most relevant for further investigation?","options":[{"id":"a","text":"Infective Endocarditis"},{"id":"b","text":"Marantic & Libman-Sacks Endocarditis"},{"id":"c","text":"Salmonella, Shigella & Yersinia"},{"id":"d","text":"Fever of Unknown Origin"}],"answerId":"a","explanation":"The 'Infective Endocarditis' module is relevant for investigating fever and new heart murmurs in patients with prosthetic valves.","kind":"integration","linkedModuleIds":["infective-endocarditis"],"origin":"ai"}],"fcp1-abnormal-vaginal-bleeding":[{"id":"fcp1-abnormal-vaginal-bleeding~ai-0","moduleId":"fcp1-abnormal-vaginal-bleeding","stem":"A 32-year-old woman presents with heavy menstrual bleeding and a bulky, irregular, enlarged uterus on examination. What is the most likely diagnosis?","options":[{"id":"a","text":"Uterine fibroids"},{"id":"b","text":"Endometrial hyperplasia"},{"id":"c","text":"Adenomyosis"},{"id":"d","text":"Endometrial carcinoma"}],"answerId":"a","explanation":"A bulky, irregular, enlarged uterus is suggestive of uterine fibroids (leiomyoma).","kind":"clinical","origin":"ai"},{"id":"fcp1-abnormal-vaginal-bleeding~ai-1","moduleId":"fcp1-abnormal-vaginal-bleeding","stem":"A 68-year-old woman reports a single episode of vaginal bleeding after menopause. What is the most appropriate next step?","options":[{"id":"a","text":"Reassure the patient"},{"id":"b","text":"Prescribe hormonal therapy"},{"id":"c","text":"Perform a transvaginal ultrasound"},{"id":"d","text":"Schedule a follow-up in 6 months"}],"answerId":"c","explanation":"Postmenopausal bleeding is considered endometrial cancer until proven otherwise, necessitating a transvaginal ultrasound.","kind":"trap","origin":"ai"},{"id":"fcp1-abnormal-vaginal-bleeding~ai-2","moduleId":"fcp1-abnormal-vaginal-bleeding","stem":"Which of the following is a structural cause of abnormal uterine bleeding according to the PALM-COEIN classification?","options":[{"id":"a","text":"Coagulopathy"},{"id":"b","text":"Ovulatory dysfunction"},{"id":"c","text":"Endometrial hyperplasia"},{"id":"d","text":"Iatrogenic"}],"answerId":"c","explanation":"Endometrial hyperplasia is a structural cause under the PALM category.","kind":"recall","origin":"ai"},{"id":"fcp1-abnormal-vaginal-bleeding~ai-3","moduleId":"fcp1-abnormal-vaginal-bleeding","stem":"A 25-year-old woman presents with amenorrhea, severe abdominal pain, and adnexal tenderness. Her vital signs show hypotension and tachycardia. What is the most likely diagnosis?","options":[{"id":"a","text":"Ectopic pregnancy"},{"id":"b","text":"Ovarian torsion"},{"id":"c","text":"Pelvic inflammatory disease"},{"id":"d","text":"Endometriosis"}],"answerId":"a","explanation":"The presentation of amenorrhea, pain, and shock is indicative of a ruptured ectopic pregnancy.","kind":"clinical","origin":"ai"},{"id":"fcp1-abnormal-vaginal-bleeding~ai-4","moduleId":"fcp1-abnormal-vaginal-bleeding","stem":"A 45-year-old woman presents with chronic heavy menstrual bleeding and pallor. Which laboratory test is most appropriate to assess her condition?","options":[{"id":"a","text":"Serum iron"},{"id":"b","text":"Beta-hCG"},{"id":"c","text":"Liver function tests"},{"id":"d","text":"Thyroid function tests"}],"answerId":"a","explanation":"Chronic heavy menstrual bleeding can lead to iron-deficiency anemia, making serum iron assessment appropriate.","kind":"clinical","origin":"ai"},{"id":"fcp1-abnormal-vaginal-bleeding~ai-5","moduleId":"fcp1-abnormal-vaginal-bleeding","stem":"A 30-year-old woman with a history of irregular menstrual cycles presents with abnormal uterine bleeding. Which linked module would provide additional insights into her condition?","options":[{"id":"a","text":"hrp2-abnormal-uterine-bleeding"},{"id":"b","text":"hrp1-mammary-gland-histology"},{"id":"c","text":"fcp1-pelvic-mass-approach"},{"id":"d","text":"fcp1-pelvic-pain-approach"}],"answerId":"a","explanation":"The 'hrp2-abnormal-uterine-bleeding' module provides clinical application insights into abnormal uterine bleeding.","kind":"integration","linkedModuleIds":["hrp2-abnormal-uterine-bleeding"],"origin":"ai"},{"id":"fcp1-abnormal-vaginal-bleeding~ai-6","moduleId":"fcp1-abnormal-vaginal-bleeding","stem":"In evaluating a patient with a pelvic mass and abnormal vaginal bleeding, which linked module would be most relevant for further assessment?","options":[{"id":"a","text":"fcp1-obgyne-history"},{"id":"b","text":"fcp1-pelvic-mass-approach"},{"id":"c","text":"hrp1-mammary-gland-histology"},{"id":"d","text":"fcp1-pelvic-pain-approach"}],"answerId":"b","explanation":"The 'fcp1-pelvic-mass-approach' module is relevant for assessing a pelvic mass in the context of abnormal bleeding.","kind":"integration","linkedModuleIds":["fcp1-pelvic-mass-approach"],"origin":"ai"}],"fcp1-obesity-approach":[{"id":"fcp1-obesity-approach~ai-0","moduleId":"fcp1-obesity-approach","stem":"A 45-year-old Thai woman presents with a BMI of 28 and a waist circumference of 85 cm. What is the best classification of her weight status according to Asian cut-offs?","options":[{"id":"a","text":"Normal weight"},{"id":"b","text":"Overweight"},{"id":"c","text":"Obese"},{"id":"d","text":"Morbidly obese"}],"answerId":"c","explanation":"According to Asian cut-offs, a BMI of 25 or more is classified as obese.","kind":"recall","origin":"ai"},{"id":"fcp1-obesity-approach~ai-1","moduleId":"fcp1-obesity-approach","stem":"A patient with central obesity, purple striae, and proximal muscle weakness is suspected to have Cushing syndrome. What is the underlying mechanism of these symptoms?","options":[{"id":"a","text":"Insulin resistance"},{"id":"b","text":"Excess cortisol"},{"id":"c","text":"Thyroid hormone deficiency"},{"id":"d","text":"Excess growth hormone"}],"answerId":"b","explanation":"Cushing syndrome is characterized by excess cortisol, leading to symptoms such as central obesity and purple striae.","kind":"mechanism","origin":"ai"},{"id":"fcp1-obesity-approach~ai-2","moduleId":"fcp1-obesity-approach","stem":"A 50-year-old man with obesity presents with daytime somnolence and loud snoring. What condition should be suspected?","options":[{"id":"a","text":"Hypothyroidism"},{"id":"b","text":"Obstructive sleep apnoea"},{"id":"c","text":"Cushing syndrome"},{"id":"d","text":"Type 2 diabetes"}],"answerId":"b","explanation":"Obstructive sleep apnoea is characterized by symptoms such as daytime somnolence and loud snoring.","kind":"clinical","origin":"ai"},{"id":"fcp1-obesity-approach~ai-3","moduleId":"fcp1-obesity-approach","stem":"What is the most appropriate initial test to screen for hypothyroidism in a patient with obesity and dry skin?","options":[{"id":"a","text":"Serum cortisol"},{"id":"b","text":"Thyroid function tests"},{"id":"c","text":"Fasting glucose"},{"id":"d","text":"Liver function tests"}],"answerId":"b","explanation":"Thyroid function tests are used to screen for hypothyroidism, which can contribute to obesity.","kind":"trap","origin":"ai"},{"id":"fcp1-obesity-approach~ai-4","moduleId":"fcp1-obesity-approach","stem":"A 38-year-old woman with obesity and acanthosis nigricans is likely to have which underlying condition?","options":[{"id":"a","text":"Hypothyroidism"},{"id":"b","text":"Insulin resistance"},{"id":"c","text":"Cushing syndrome"},{"id":"d","text":"Polycystic ovary syndrome"}],"answerId":"b","explanation":"Acanthosis nigricans is often associated with insulin resistance.","kind":"clinical","origin":"ai"},{"id":"fcp1-obesity-approach~ai-5","moduleId":"fcp1-obesity-approach","stem":"In the context of obesity, which of the following is a primary cause rather than a secondary cause?","options":[{"id":"a","text":"Hypothyroidism"},{"id":"b","text":"Cushing syndrome"},{"id":"c","text":"Energy imbalance"},{"id":"d","text":"Drug-induced weight gain"}],"answerId":"c","explanation":"Primary obesity is commonly due to energy imbalance, whereas the others are secondary causes.","kind":"recall","origin":"ai"},{"id":"fcp1-obesity-approach~ai-6","moduleId":"fcp1-obesity-approach","stem":"A patient with obesity is being evaluated for bariatric surgery. Which module should be referred to for further management details?","options":[{"id":"a","text":"Antimicrobial Prophylaxis in Surgery"},{"id":"b","text":"Obesity Management & Bariatric Surgery"},{"id":"c","text":"Peripheral Arterial Disease (PAD)"},{"id":"d","text":"Approach to Thyroid Disease"}],"answerId":"b","explanation":"The 'Obesity Management & Bariatric Surgery' module provides details on surgical management of obesity.","kind":"integration","linkedModuleIds":["obesity-management-bariatric-surgery"],"origin":"ai"},{"id":"fcp1-obesity-approach~ai-7","moduleId":"fcp1-obesity-approach","stem":"A 55-year-old man with obesity and a history of smoking presents with claudication. Which module should be consulted for further evaluation?","options":[{"id":"a","text":"Approach to Unintentional Weight Loss"},{"id":"b","text":"Peripheral Arterial Disease (PAD)"},{"id":"c","text":"Hypothyroidism"},{"id":"d","text":"Evaluating Malnutrition"}],"answerId":"b","explanation":"The 'Peripheral Arterial Disease (PAD)' module is relevant for evaluating claudication in this context.","kind":"integration","linkedModuleIds":["add-peripheral-arterial-disease-pad"],"origin":"ai"}],"fcp1-weight-loss-approach":[{"id":"fcp1-weight-loss-approach~ai-0","moduleId":"fcp1-weight-loss-approach","stem":"A 65-year-old male with a 40-pack-year smoking history presents with a 7% weight loss over the past 8 months and reports decreased appetite. Which of the following is the most appropriate initial investigation?","options":[{"id":"a","text":"Chest X-ray"},{"id":"b","text":"Thyroid function tests"},{"id":"c","text":"HbA1c"},{"id":"d","text":"Abdominal ultrasound"}],"answerId":"a","explanation":"Given the smoking history and weight loss with decreased appetite, a chest X-ray is indicated to rule out lung malignancy.","kind":"clinical","origin":"ai"},{"id":"fcp1-weight-loss-approach~ai-1","moduleId":"fcp1-weight-loss-approach","stem":"A 45-year-old woman presents with unintentional weight loss of 6% over 6 months. She has a good appetite but experiences frequent diarrhea. Which condition is most likely?","options":[{"id":"a","text":"Hyperthyroidism"},{"id":"b","text":"Depression"},{"id":"c","text":"Chronic pancreatitis"},{"id":"d","text":"Cirrhosis"}],"answerId":"a","explanation":"Weight loss with a good appetite and diarrhea suggests hyperthyroidism, which increases metabolism and can cause diarrhea.","kind":"mechanism","origin":"ai"},{"id":"fcp1-weight-loss-approach~ai-2","moduleId":"fcp1-weight-loss-approach","stem":"A patient with unintentional weight loss reports night sweats and palpable lymphadenopathy. What is the most likely underlying condition?","options":[{"id":"a","text":"Lymphoma"},{"id":"b","text":"Hyperthyroidism"},{"id":"c","text":"Diabetes mellitus"},{"id":"d","text":"Celiac disease"}],"answerId":"a","explanation":"Night sweats and lymphadenopathy are classic signs of lymphoma, a type of malignancy.","kind":"recall","origin":"ai"},{"id":"fcp1-weight-loss-approach~ai-3","moduleId":"fcp1-weight-loss-approach","stem":"In the context of unintentional weight loss, which of the following findings would most strongly suggest an endocrine cause?","options":[{"id":"a","text":"Fine tremor and tachycardia"},{"id":"b","text":"Pallor and positive fecal occult blood"},{"id":"c","text":"Low mood and anhedonia"},{"id":"d","text":"Palpable abdominal mass"}],"answerId":"a","explanation":"Fine tremor and tachycardia are indicative of hyperthyroidism, an endocrine disorder.","kind":"trap","origin":"ai"},{"id":"fcp1-weight-loss-approach~ai-4","moduleId":"fcp1-weight-loss-approach","stem":"A 55-year-old man with unintentional weight loss and a history of alcohol use presents with abdominal pain and steatorrhea. Which condition is most likely?","options":[{"id":"a","text":"Chronic pancreatitis"},{"id":"b","text":"Hyperthyroidism"},{"id":"c","text":"Lung cancer"},{"id":"d","text":"Diabetes mellitus"}],"answerId":"a","explanation":"Chronic pancreatitis is associated with alcohol use, abdominal pain, weight loss, and steatorrhea due to malabsorption.","kind":"clinical","origin":"ai"},{"id":"fcp1-weight-loss-approach~ai-5","moduleId":"fcp1-weight-loss-approach","stem":"A 50-year-old woman with a history of hyperthyroidism presents with unintentional weight loss and increased appetite. Which additional symptom would support the diagnosis of hyperthyroidism?","options":[{"id":"a","text":"Heat intolerance"},{"id":"b","text":"Cold intolerance"},{"id":"c","text":"Constipation"},{"id":"d","text":"Bradycardia"}],"answerId":"a","explanation":"Heat intolerance is a common symptom of hyperthyroidism due to increased metabolic rate.","kind":"integration","linkedModuleIds":["fcp1-hyperthyroidism"],"origin":"ai"},{"id":"fcp1-weight-loss-approach~ai-6","moduleId":"fcp1-weight-loss-approach","stem":"A 70-year-old male with unintentional weight loss and a history of chronic kidney disease presents with fatigue and pallor. Which test would help confirm a suspected diagnosis of anemia?","options":[{"id":"a","text":"Complete blood count"},{"id":"b","text":"Thyroid function test"},{"id":"c","text":"Liver function test"},{"id":"d","text":"Chest X-ray"}],"answerId":"a","explanation":"A complete blood count is essential to evaluate for anemia, which is common in chronic kidney disease.","kind":"integration","origin":"ai"}],"fcp1-edema-approach":[{"id":"fcp1-edema-approach~ai-0","moduleId":"fcp1-edema-approach","stem":"A 65-year-old man presents with bilateral pitting edema, raised JVP, and bibasal crackles. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Increased hydrostatic pressure"},{"id":"b","text":"Decreased oncotic pressure"},{"id":"c","text":"Lymphatic obstruction"},{"id":"d","text":"Increased capillary permeability"}],"answerId":"a","explanation":"The findings suggest heart failure, where increased hydrostatic pressure leads to edema.","kind":"mechanism","origin":"ai"},{"id":"fcp1-edema-approach~ai-1","moduleId":"fcp1-edema-approach","stem":"A 40-year-old woman presents with unilateral leg swelling, redness, and tenderness. Which test should be prioritized to rule out a serious condition?","options":[{"id":"a","text":"Blood culture"},{"id":"b","text":"Compression ultrasound"},{"id":"c","text":"Venous blood gas"},{"id":"d","text":"Skin biopsy"}],"answerId":"b","explanation":"Compression ultrasound is used to confirm or exclude deep vein thrombosis, a serious condition.","kind":"trap","origin":"ai"},{"id":"fcp1-edema-approach~ai-2","moduleId":"fcp1-edema-approach","stem":"A patient with nephrotic syndrome is likely to present with which of the following findings?","options":[{"id":"a","text":"Periorbital edema and frothy urine"},{"id":"b","text":"Non-pitting edema and weight loss"},{"id":"c","text":"Unilateral leg swelling and erythema"},{"id":"d","text":"Ascites and jaundice"}],"answerId":"a","explanation":"Nephrotic syndrome is characterized by hypoalbuminemia leading to periorbital edema and proteinuria causing frothy urine.","kind":"recall","origin":"ai"},{"id":"fcp1-edema-approach~ai-3","moduleId":"fcp1-edema-approach","stem":"A 30-year-old pregnant woman presents with generalized edema and hypertension. Which condition should be considered?","options":[{"id":"a","text":"Pre-eclampsia"},{"id":"b","text":"Hypothyroidism"},{"id":"c","text":"Chronic venous insufficiency"},{"id":"d","text":"Lymphedema"}],"answerId":"a","explanation":"Generalized edema and hypertension in pregnancy are suggestive of pre-eclampsia.","kind":"clinical","origin":"ai"},{"id":"fcp1-edema-approach~ai-4","moduleId":"fcp1-edema-approach","stem":"A patient presents with non-pitting edema and signs of hypothyroidism. Which test is most appropriate to confirm the suspected diagnosis?","options":[{"id":"a","text":"Thyroid function tests"},{"id":"b","text":"Serum albumin"},{"id":"c","text":"BNP levels"},{"id":"d","text":"Urinalysis"}],"answerId":"a","explanation":"Non-pitting edema with hypothyroid signs suggests myxedema; thyroid function tests confirm hypothyroidism.","kind":"recall","origin":"ai"},{"id":"fcp1-edema-approach~ai-5","moduleId":"fcp1-edema-approach","stem":"A 55-year-old man with a history of coronary artery disease presents with bilateral leg edema. Which histological feature is most associated with his underlying condition?","options":[{"id":"a","text":"Foam cells in arterial walls"},{"id":"b","text":"Increased capillary permeability"},{"id":"c","text":"Lymphatic obstruction"},{"id":"d","text":"Decreased oncotic pressure"}],"answerId":"a","explanation":"Foam cells in arterial walls are characteristic of atherosclerosis, which is related to coronary artery disease.","kind":"integration","linkedModuleIds":["add-histological-features-of-atherosclerosis"],"origin":"ai"},{"id":"fcp1-edema-approach~ai-6","moduleId":"fcp1-edema-approach","stem":"A patient presents with bilateral pitting edema and elevated serum calcium. Which linked condition might explain this presentation?","options":[{"id":"a","text":"Hyperparathyroidism"},{"id":"b","text":"Nephrotic syndrome"},{"id":"c","text":"Chronic liver disease"},{"id":"d","text":"Hypothyroidism"}],"answerId":"a","explanation":"Hyperparathyroidism can cause hypercalcemia and may lead to edema through renal effects.","kind":"integration","linkedModuleIds":["hen1-calcium-phosphate-pools"],"origin":"ai"}],"fcp1-fever-pathophysiology":[{"id":"fcp1-fever-pathophysiology~ai-0","moduleId":"fcp1-fever-pathophysiology","stem":"Which cytokine is primarily responsible for raising the hypothalamic set-point during a fever?","options":[{"id":"a","text":"IL-1"},{"id":"b","text":"IL-10"},{"id":"c","text":"IL-4"},{"id":"d","text":"IL-8"}],"answerId":"a","explanation":"IL-1 is an endogenous pyrogen that stimulates the production of PGE2, raising the hypothalamic set-point.","kind":"recall","origin":"ai"},{"id":"fcp1-fever-pathophysiology~ai-1","moduleId":"fcp1-fever-pathophysiology","stem":"A patient presents with a temperature of 42°C, hot dry skin, and confusion. What is the most appropriate initial management?","options":[{"id":"a","text":"Administer paracetamol"},{"id":"b","text":"Initiate active cooling"},{"id":"c","text":"Start antibiotics"},{"id":"d","text":"Give IV fluids"}],"answerId":"b","explanation":"These symptoms suggest hyperthermia, which requires active cooling as the hypothalamic set-point is normal.","kind":"clinical","origin":"ai"},{"id":"fcp1-fever-pathophysiology~ai-2","moduleId":"fcp1-fever-pathophysiology","stem":"What is the role of PGE2 in the pathophysiology of fever?","options":[{"id":"a","text":"Increases hypothalamic set-point"},{"id":"b","text":"Decreases hypothalamic set-point"},{"id":"c","text":"Acts as an antipyretic"},{"id":"d","text":"Stimulates vasodilation"}],"answerId":"a","explanation":"PGE2 is produced in response to pyrogens and raises the hypothalamic set-point, causing fever.","kind":"mechanism","origin":"ai"},{"id":"fcp1-fever-pathophysiology~ai-3","moduleId":"fcp1-fever-pathophysiology","stem":"A patient with suspected typhoid fever presents with a temperature of 39°C and a pulse of 70 bpm. What is this finding called?","options":[{"id":"a","text":"Relative bradycardia"},{"id":"b","text":"Tachycardia"},{"id":"c","text":"Faget sign"},{"id":"d","text":"Pulse deficit"}],"answerId":"a","explanation":"Relative bradycardia, or Faget sign, is a pulse lower than expected for the temperature, seen in typhoid.","kind":"recall","origin":"ai"},{"id":"fcp1-fever-pathophysiology~ai-4","moduleId":"fcp1-fever-pathophysiology","stem":"Which fever pattern is characterized by febrile days separated by afebrile days, often seen in Hodgkin's lymphoma?","options":[{"id":"a","text":"Intermittent"},{"id":"b","text":"Remittent"},{"id":"c","text":"Sustained"},{"id":"d","text":"Relapsing"}],"answerId":"d","explanation":"Relapsing fever, or Pel-Ebstein pattern, is associated with Hodgkin's lymphoma and involves cyclical pyrogen release.","kind":"recall","origin":"ai"},{"id":"fcp1-fever-pathophysiology~ai-5","moduleId":"fcp1-fever-pathophysiology","stem":"In the context of fever, what is the primary mechanism by which antipyretics like paracetamol reduce temperature?","options":[{"id":"a","text":"Inhibition of COX enzymes"},{"id":"b","text":"Blocking IL-6"},{"id":"c","text":"Increasing peripheral vasodilation"},{"id":"d","text":"Enhancing heat dissipation"}],"answerId":"a","explanation":"Antipyretics inhibit COX enzymes, reducing PGE2 production and lowering the hypothalamic set-point.","kind":"mechanism","origin":"ai"},{"id":"fcp1-fever-pathophysiology~ai-6","moduleId":"fcp1-fever-pathophysiology","stem":"A patient with hyperthyroidism presents with fever and tachycardia. How does this relate to the pathophysiology of fever?","options":[{"id":"a","text":"Increased metabolic rate"},{"id":"b","text":"Decreased PGE2 production"},{"id":"c","text":"Inhibition of pyrogen release"},{"id":"d","text":"Reduced hypothalamic set-point"}],"answerId":"a","explanation":"Hyperthyroidism increases metabolic rate, which can lead to fever through increased heat production.","kind":"integration","linkedModuleIds":["fcp1-hyperthyroidism"],"origin":"ai"},{"id":"fcp1-fever-pathophysiology~ai-7","moduleId":"fcp1-fever-pathophysiology","stem":"How does the skin contribute to thermoregulation during fever?","options":[{"id":"a","text":"Vasoconstriction"},{"id":"b","text":"Vasodilation"},{"id":"c","text":"Sweating"},{"id":"d","text":"Heat production"}],"answerId":"b","explanation":"During fever, the skin undergoes vasodilation to dissipate heat once the set-point is reached.","kind":"integration","linkedModuleIds":["skin-physiology-thermoregulation"],"origin":"ai"}],"fcp1-edema-mechanisms":[{"id":"fcp1-edema-mechanisms~ai-0","moduleId":"fcp1-edema-mechanisms","stem":"A patient presents with generalized edema and a low serum albumin level. Which mechanism is most likely responsible for the edema?","options":[{"id":"a","text":"Increased capillary hydrostatic pressure"},{"id":"b","text":"Reduced plasma oncotic pressure"},{"id":"c","text":"Increased capillary permeability"},{"id":"d","text":"Lymphatic obstruction"}],"answerId":"b","explanation":"Low serum albumin reduces plasma oncotic pressure, leading to edema.","kind":"mechanism","origin":"ai"},{"id":"fcp1-edema-mechanisms~ai-1","moduleId":"fcp1-edema-mechanisms","stem":"A 60-year-old male with heart failure presents with pitting edema. Which of the following is the primary mechanism?","options":[{"id":"a","text":"Increased capillary hydrostatic pressure"},{"id":"b","text":"Reduced plasma oncotic pressure"},{"id":"c","text":"Increased capillary permeability"},{"id":"d","text":"Lymphatic obstruction"}],"answerId":"a","explanation":"Heart failure increases capillary hydrostatic pressure, causing pitting edema.","kind":"mechanism","origin":"ai"},{"id":"fcp1-edema-mechanisms~ai-2","moduleId":"fcp1-edema-mechanisms","stem":"Which physical exam finding would most likely indicate a lymphatic obstruction?","options":[{"id":"a","text":"Pitting edema"},{"id":"b","text":"Non-pitting edema with skin thickening"},{"id":"c","text":"Periorbital edema"},{"id":"d","text":"Raised JVP"}],"answerId":"b","explanation":"Non-pitting edema with skin thickening is characteristic of lymphatic obstruction.","kind":"recall","origin":"ai"},{"id":"fcp1-edema-mechanisms~ai-3","moduleId":"fcp1-edema-mechanisms","stem":"A patient with nephrotic syndrome presents with periorbital edema. What is the underlying mechanism?","options":[{"id":"a","text":"Increased capillary hydrostatic pressure"},{"id":"b","text":"Reduced plasma oncotic pressure"},{"id":"c","text":"Increased capillary permeability"},{"id":"d","text":"Lymphatic obstruction"}],"answerId":"b","explanation":"Nephrotic syndrome causes hypoalbuminemia, reducing plasma oncotic pressure and leading to edema.","kind":"mechanism","origin":"ai"},{"id":"fcp1-edema-mechanisms~ai-4","moduleId":"fcp1-edema-mechanisms","stem":"A patient with hypothyroidism presents with non-pitting edema. What is the most likely cause?","options":[{"id":"a","text":"Increased capillary hydrostatic pressure"},{"id":"b","text":"Reduced plasma oncotic pressure"},{"id":"c","text":"Increased capillary permeability"},{"id":"d","text":"Myxedema"}],"answerId":"d","explanation":"Hypothyroidism can cause myxedema, which is characterized by non-pitting edema.","kind":"integration","linkedModuleIds":["fcp1-hypothyroidism"],"origin":"ai"},{"id":"fcp1-edema-mechanisms~ai-5","moduleId":"fcp1-edema-mechanisms","stem":"A malnourished patient presents with generalized edema. Which of the following mechanisms is most likely involved?","options":[{"id":"a","text":"Increased capillary hydrostatic pressure"},{"id":"b","text":"Reduced plasma oncotic pressure"},{"id":"c","text":"Increased capillary permeability"},{"id":"d","text":"Lymphatic obstruction"}],"answerId":"b","explanation":"Malnutrition can lead to hypoalbuminemia, reducing plasma oncotic pressure and causing edema.","kind":"integration","linkedModuleIds":["fcp1-malnutrition-evaluation"],"origin":"ai"}],"fcp1-syncope-approach":[{"id":"fcp1-syncope-approach~ai-0","moduleId":"fcp1-syncope-approach","stem":"A 70-year-old man experiences syncope while climbing stairs. On examination, he has a loud ejection systolic murmur at the right second intercostal space. What is the most likely diagnosis?","options":[{"id":"a","text":"Aortic stenosis"},{"id":"b","text":"Vasovagal syncope"},{"id":"c","text":"Orthostatic hypotension"},{"id":"d","text":"Carotid sinus syndrome"}],"answerId":"a","explanation":"Exertional syncope with an ejection systolic murmur suggests aortic stenosis.","kind":"recall","origin":"ai"},{"id":"fcp1-syncope-approach~ai-1","moduleId":"fcp1-syncope-approach","stem":"A 25-year-old woman faints after standing in a hot room for a prolonged period. She reports feeling nauseous and warm before losing consciousness. What type of syncope is most likely?","options":[{"id":"a","text":"Cardiac syncope"},{"id":"b","text":"Orthostatic hypotension"},{"id":"c","text":"Vasovagal syncope"},{"id":"d","text":"Carotid sinus syndrome"}],"answerId":"c","explanation":"The prodrome of nausea and warmth suggests vasovagal (reflex) syncope.","kind":"mechanism","origin":"ai"},{"id":"fcp1-syncope-approach~ai-2","moduleId":"fcp1-syncope-approach","stem":"Which of the following is a red flag for cardiac syncope?","options":[{"id":"a","text":"Syncope with a prodrome of nausea"},{"id":"b","text":"Syncope while supine"},{"id":"c","text":"Syncope after micturition"},{"id":"d","text":"Syncope with tunnel vision"}],"answerId":"b","explanation":"Syncope while supine is a red flag for cardiac syncope.","kind":"trap","origin":"ai"},{"id":"fcp1-syncope-approach~ai-3","moduleId":"fcp1-syncope-approach","stem":"A patient presents with syncope and a fall in systolic BP of 25 mmHg upon standing. What is the most likely cause?","options":[{"id":"a","text":"Vasovagal syncope"},{"id":"b","text":"Orthostatic hypotension"},{"id":"c","text":"Cardiac syncope"},{"id":"d","text":"Carotid sinus syndrome"}],"answerId":"b","explanation":"A significant drop in BP upon standing indicates orthostatic hypotension.","kind":"recall","origin":"ai"},{"id":"fcp1-syncope-approach~ai-4","moduleId":"fcp1-syncope-approach","stem":"A 60-year-old man with a history of hypertension experiences syncope. His ECG shows a prolonged QT interval. What is the most appropriate next step?","options":[{"id":"a","text":"Reassure and discharge"},{"id":"b","text":"Start beta-blockers"},{"id":"c","text":"Admit for cardiac evaluation"},{"id":"d","text":"Perform tilt-table testing"}],"answerId":"c","explanation":"A prolonged QT interval is a red flag for cardiac syncope, warranting admission.","kind":"clinical","origin":"ai"},{"id":"fcp1-syncope-approach~ai-5","moduleId":"fcp1-syncope-approach","stem":"A 45-year-old man experiences syncope while exercising. Which investigation is crucial to rule out a structural cardiac cause?","options":[{"id":"a","text":"Tilt-table test"},{"id":"b","text":"Echocardiogram"},{"id":"c","text":"Holter monitor"},{"id":"d","text":"Carotid ultrasound"}],"answerId":"b","explanation":"An echocardiogram is essential to evaluate for structural cardiac causes like aortic stenosis.","kind":"integration","linkedModuleIds":["echocardiography-basics"],"origin":"ai"},{"id":"fcp1-syncope-approach~ai-6","moduleId":"fcp1-syncope-approach","stem":"A patient with syncope has an abnormal ECG showing delta waves. Which condition should be considered?","options":[{"id":"a","text":"Brugada syndrome"},{"id":"b","text":"Wolff-Parkinson-White syndrome"},{"id":"c","text":"Long QT syndrome"},{"id":"d","text":"Hypertrophic cardiomyopathy"}],"answerId":"b","explanation":"Delta waves on ECG are indicative of Wolff-Parkinson-White syndrome.","kind":"integration","linkedModuleIds":["fcp1-chest-pain-cardiac"],"origin":"ai"}],"fcp1-shock-management":[{"id":"fcp1-shock-management~ai-0","moduleId":"fcp1-shock-management","stem":"A 65-year-old male presents with cool mottled skin, capillary refill over 2 seconds, and oliguria. What is the most likely underlying mechanism for these findings?","options":[{"id":"a","text":"Peripheral hypoperfusion"},{"id":"b","text":"Central hypoperfusion"},{"id":"c","text":"Increased cardiac output"},{"id":"d","text":"Decreased systemic vascular resistance"}],"answerId":"a","explanation":"Cool mottled skin and delayed capillary refill indicate peripheral hypoperfusion, a hallmark of shock.","kind":"mechanism","origin":"ai"},{"id":"fcp1-shock-management~ai-1","moduleId":"fcp1-shock-management","stem":"Which of the following is the first-line vasopressor for septic shock?","options":[{"id":"a","text":"Adrenaline"},{"id":"b","text":"Noradrenaline"},{"id":"c","text":"Dopamine"},{"id":"d","text":"Phenylephrine"}],"answerId":"b","explanation":"Noradrenaline is the first-line vasopressor for septic shock to maintain mean arterial pressure.","kind":"recall","origin":"ai"},{"id":"fcp1-shock-management~ai-2","moduleId":"fcp1-shock-management","stem":"A patient in cardiogenic shock is hypotensive. Which of the following is the most appropriate initial management?","options":[{"id":"a","text":"Large volume crystalloid bolus"},{"id":"b","text":"Small cautious fluid bolus and inotropes"},{"id":"c","text":"Immediate vasopressor administration"},{"id":"d","text":"Intramuscular adrenaline"}],"answerId":"b","explanation":"In cardiogenic shock, the heart cannot tolerate large volumes; small boluses and inotropes are preferred.","kind":"trap","origin":"ai"},{"id":"fcp1-shock-management~ai-3","moduleId":"fcp1-shock-management","stem":"A 45-year-old female presents with hypotension, tachycardia, and altered mentation after a bee sting. What is the immediate treatment?","options":[{"id":"a","text":"Intravenous fluids"},{"id":"b","text":"Intramuscular adrenaline"},{"id":"c","text":"Antihistamines"},{"id":"d","text":"Corticosteroids"}],"answerId":"b","explanation":"Anaphylaxis requires immediate intramuscular adrenaline as the first-line treatment.","kind":"clinical","origin":"ai"},{"id":"fcp1-shock-management~ai-4","moduleId":"fcp1-shock-management","stem":"In the context of shock, which of the following findings is most indicative of early compensated shock?","options":[{"id":"a","text":"Hypotension"},{"id":"b","text":"Bradycardia"},{"id":"c","text":"Tachycardia with narrow pulse pressure"},{"id":"d","text":"Warm flushed skin"}],"answerId":"c","explanation":"Tachycardia with a narrow pulse pressure is an early sign of compensated shock.","kind":"recall","origin":"ai"},{"id":"fcp1-shock-management~ai-5","moduleId":"fcp1-shock-management","stem":"A patient with suspected septic shock is being managed. Which parameter is most useful for assessing response to treatment?","options":[{"id":"a","text":"Blood pressure"},{"id":"b","text":"Heart rate"},{"id":"c","text":"Lactate clearance"},{"id":"d","text":"Respiratory rate"}],"answerId":"c","explanation":"Lactate clearance is a key indicator of tissue perfusion and response to treatment in shock.","kind":"mechanism","origin":"ai"},{"id":"fcp1-shock-management~ai-6","moduleId":"fcp1-shock-management","stem":"A patient presents with fever and hypotension. After initial resuscitation, what is the next step in management to address the underlying cause?","options":[{"id":"a","text":"Administer broad-spectrum antibiotics"},{"id":"b","text":"Perform a CT scan"},{"id":"c","text":"Start vasopressors"},{"id":"d","text":"Administer antipyretics"}],"answerId":"a","explanation":"In septic shock, early administration of broad-spectrum antibiotics is crucial for source control.","kind":"integration","linkedModuleIds":["fcp1-fever-approach-differential"],"origin":"ai"},{"id":"fcp1-shock-management~ai-7","moduleId":"fcp1-shock-management","stem":"During the primary survey of a trauma patient, you suspect shock. What is the initial step in management?","options":[{"id":"a","text":"Administer high-flow oxygen"},{"id":"b","text":"Start intravenous antibiotics"},{"id":"c","text":"Perform an ECG"},{"id":"d","text":"Administer vasopressors"}],"answerId":"a","explanation":"In trauma, securing the airway and providing high-flow oxygen is the first step in the primary survey.","kind":"integration","linkedModuleIds":["fcp1-trauma-primary-survey"],"origin":"ai"}],"fcp1-shock-classification":[{"id":"fcp1-shock-classification~ai-0","moduleId":"fcp1-shock-classification","stem":"A patient presents with hypotension, distended neck veins, and muffled heart sounds. What type of shock is most likely?","options":[{"id":"a","text":"Obstructive"},{"id":"b","text":"Hypovolemic"},{"id":"c","text":"Cardiogenic"},{"id":"d","text":"Distributive"}],"answerId":"a","explanation":"The triad of hypotension, distended neck veins, and muffled heart sounds suggests cardiac tamponade, which causes obstructive shock.","kind":"clinical","origin":"ai"},{"id":"fcp1-shock-classification~ai-1","moduleId":"fcp1-shock-classification","stem":"Which of the following hemodynamic profiles is characteristic of hypovolemic shock?","options":[{"id":"a","text":"Low cardiac output, high SVR, low preload"},{"id":"b","text":"High cardiac output, low SVR, high preload"},{"id":"c","text":"Low cardiac output, low SVR, high preload"},{"id":"d","text":"High cardiac output, high SVR, low preload"}],"answerId":"a","explanation":"Hypovolemic shock is characterized by low cardiac output, high systemic vascular resistance (SVR), and low preload due to decreased blood volume.","kind":"recall","origin":"ai"},{"id":"fcp1-shock-classification~ai-2","moduleId":"fcp1-shock-classification","stem":"A patient with septic shock is most likely to present with which of the following hemodynamic changes?","options":[{"id":"a","text":"High cardiac output, low SVR"},{"id":"b","text":"Low cardiac output, high SVR"},{"id":"c","text":"Low cardiac output, low SVR"},{"id":"d","text":"High cardiac output, high SVR"}],"answerId":"a","explanation":"Septic shock, a form of distributive shock, typically presents with high cardiac output and low systemic vascular resistance due to vasodilation.","kind":"mechanism","origin":"ai"},{"id":"fcp1-shock-classification~ai-3","moduleId":"fcp1-shock-classification","stem":"A patient with a spinal cord injury presents with hypotension and bradycardia. What type of shock is this indicative of?","options":[{"id":"a","text":"Neurogenic"},{"id":"b","text":"Cardiogenic"},{"id":"c","text":"Hypovolemic"},{"id":"d","text":"Obstructive"}],"answerId":"a","explanation":"Neurogenic shock occurs after spinal cord injury and is characterized by hypotension and bradycardia due to loss of sympathetic tone.","kind":"clinical","origin":"ai"},{"id":"fcp1-shock-classification~ai-4","moduleId":"fcp1-shock-classification","stem":"A patient with a high fever, tachycardia, and warm, flushed skin is suspected to be in shock. Which linked module would help in further understanding the differential diagnosis?","options":[{"id":"a","text":"fcp1-fever-approach-differential"},{"id":"b","text":"atypical-antipsychotic-agents"},{"id":"c","text":"bacterial-meningitis"},{"id":"d","text":"fcp1-syncope-approach"}],"answerId":"a","explanation":"The 'fcp1-fever-approach-differential' module would help in understanding the differential diagnosis of fever, which is relevant in septic shock.","kind":"integration","linkedModuleIds":["fcp1-fever-approach-differential"],"origin":"ai"},{"id":"fcp1-shock-classification~ai-5","moduleId":"fcp1-shock-classification","stem":"Which of the following findings would most likely be seen in a patient with cardiogenic shock?","options":[{"id":"a","text":"Cold, clammy skin with distended neck veins"},{"id":"b","text":"Warm, flushed skin with bounding pulses"},{"id":"c","text":"Hypotension with bradycardia"},{"id":"d","text":"Low central venous pressure"}],"answerId":"a","explanation":"Cardiogenic shock is characterized by cold, clammy skin due to vasoconstriction and distended neck veins due to high filling pressures.","kind":"recall","origin":"ai"},{"id":"fcp1-shock-classification~ai-6","moduleId":"fcp1-shock-classification","stem":"A patient presents with sudden chest pain and shortness of breath. Which linked module would assist in evaluating the cause of obstructive shock?","options":[{"id":"a","text":"fcp1-chest-pain-differential"},{"id":"b","text":"fcp1-consciousness-coma-approach"},{"id":"c","text":"fcp1-syncope-approach"},{"id":"d","text":"bacterial-meningitis"}],"answerId":"a","explanation":"The 'fcp1-chest-pain-differential' module would assist in evaluating causes of chest pain that can lead to obstructive shock, such as pulmonary embolism or tension pneumothorax.","kind":"integration","linkedModuleIds":["fcp1-chest-pain-differential"],"origin":"ai"}],"fcp1-trauma-secondary-survey":[{"id":"fcp1-trauma-secondary-survey~ai-0","moduleId":"fcp1-trauma-secondary-survey","stem":"During the secondary survey, a patient presents with raccoon eyes and CSF rhinorrhoea. What is the most likely diagnosis?","options":[{"id":"a","text":"Base-of-skull fracture"},{"id":"b","text":"Orbital fracture"},{"id":"c","text":"Nasal fracture"},{"id":"d","text":"Maxillary fracture"}],"answerId":"a","explanation":"Raccoon eyes and CSF rhinorrhoea are indicative of a base-of-skull fracture.","kind":"recall","origin":"ai"},{"id":"fcp1-trauma-secondary-survey~ai-1","moduleId":"fcp1-trauma-secondary-survey","stem":"In the context of trauma, what does the 'P' in AMPLE history stand for?","options":[{"id":"a","text":"Past history/Pregnancy"},{"id":"b","text":"Pain"},{"id":"c","text":"Pulse"},{"id":"d","text":"Pupils"}],"answerId":"a","explanation":"The 'P' in AMPLE history stands for Past history/Pregnancy.","kind":"recall","origin":"ai"},{"id":"fcp1-trauma-secondary-survey~ai-2","moduleId":"fcp1-trauma-secondary-survey","stem":"A trauma patient has a positive FAST exam indicating free fluid in Morrison's pouch. What is the most likely cause?","options":[{"id":"a","text":"Intra-abdominal haemorrhage"},{"id":"b","text":"Pleural effusion"},{"id":"c","text":"Pericardial effusion"},{"id":"d","text":"Ascites"}],"answerId":"a","explanation":"Free fluid in Morrison's pouch on FAST exam suggests intra-abdominal haemorrhage.","kind":"recall","origin":"ai"},{"id":"fcp1-trauma-secondary-survey~ai-3","moduleId":"fcp1-trauma-secondary-survey","stem":"Which of the following actions is appropriate when assessing a patient with suspected pelvic fracture?","options":[{"id":"a","text":"Spring the pelvis once"},{"id":"b","text":"Spring the pelvis repeatedly"},{"id":"c","text":"Pass a urinary catheter immediately"},{"id":"d","text":"Ignore blood at the urethral meatus"}],"answerId":"a","explanation":"Springing the pelvis once is appropriate to avoid dislodging clots.","kind":"trap","origin":"ai"},{"id":"fcp1-trauma-secondary-survey~ai-4","moduleId":"fcp1-trauma-secondary-survey","stem":"A patient with a seatbelt sign and abdominal distension is most likely to have which type of injury?","options":[{"id":"a","text":"Intra-abdominal injury"},{"id":"b","text":"Rib fracture"},{"id":"c","text":"Clavicle fracture"},{"id":"d","text":"Spinal injury"}],"answerId":"a","explanation":"The seatbelt sign and abdominal distension suggest an intra-abdominal injury.","kind":"recall","origin":"ai"},{"id":"fcp1-trauma-secondary-survey~ai-5","moduleId":"fcp1-trauma-secondary-survey","stem":"After completing the primary survey (ABCDE), what is the next step in trauma assessment?","options":[{"id":"a","text":"Secondary survey"},{"id":"b","text":"Tertiary survey"},{"id":"c","text":"Immediate surgery"},{"id":"d","text":"Discharge planning"}],"answerId":"a","explanation":"The secondary survey follows the primary survey and involves a head-to-toe examination.","kind":"recall","linkedModuleIds":["fcp1-trauma-primary-survey"],"origin":"ai"},{"id":"fcp1-trauma-secondary-survey~ai-6","moduleId":"fcp1-trauma-secondary-survey","stem":"In a stable trauma patient, which imaging modality is appropriate for further assessment after the secondary survey?","options":[{"id":"a","text":"CT scan"},{"id":"b","text":"MRI"},{"id":"c","text":"Ultrasound"},{"id":"d","text":"Plain X-ray"}],"answerId":"a","explanation":"CT scan is appropriate for stable patients after the secondary survey for detailed assessment.","kind":"integration","linkedModuleIds":["fcp1-trauma-resuscitation"],"origin":"ai"}],"fcp1-trauma-primary-survey":[{"id":"fcp1-trauma-primary-survey~ai-0","moduleId":"fcp1-trauma-primary-survey","stem":"A patient presents with tracheal deviation, absent breath sounds on the right, and distended neck veins. What is the immediate next step in management?","options":[{"id":"a","text":"Needle thoracostomy"},{"id":"b","text":"Order a portable chest X-ray"},{"id":"c","text":"Administer high-flow oxygen"},{"id":"d","text":"Perform a pericardiocentesis"}],"answerId":"a","explanation":"These are signs of a tension pneumothorax, which requires immediate needle thoracostomy.","kind":"clinical","origin":"ai"},{"id":"fcp1-trauma-primary-survey~ai-1","moduleId":"fcp1-trauma-primary-survey","stem":"During a primary survey, a trauma patient is found to have a GCS of 7. What is the most appropriate immediate action?","options":[{"id":"a","text":"Administer IV fluids"},{"id":"b","text":"Perform endotracheal intubation"},{"id":"c","text":"Apply a cervical collar"},{"id":"d","text":"Start chest compressions"}],"answerId":"b","explanation":"A GCS ≤ 8 indicates the patient cannot protect their airway, necessitating intubation.","kind":"clinical","origin":"ai"},{"id":"fcp1-trauma-primary-survey~ai-2","moduleId":"fcp1-trauma-primary-survey","stem":"Which of the following is a clinical trap when managing a patient with suspected tension pneumothorax?","options":[{"id":"a","text":"Performing needle thoracostomy immediately"},{"id":"b","text":"Ordering a portable chest X-ray before intervention"},{"id":"c","text":"Administering high-flow oxygen"},{"id":"d","text":"Performing a finger thoracostomy"}],"answerId":"b","explanation":"Waiting for imaging in suspected tension pneumothorax can be fatal; decompress based on clinical signs.","kind":"trap","origin":"ai"},{"id":"fcp1-trauma-primary-survey~ai-3","moduleId":"fcp1-trauma-primary-survey","stem":"In the primary survey, which step involves assessing for hypovolaemic shock by evaluating skin color, heart rate, and pulse pressure?","options":[{"id":"a","text":"Airway"},{"id":"b","text":"Breathing"},{"id":"c","text":"Circulation"},{"id":"d","text":"Disability"}],"answerId":"c","explanation":"Circulation assessment involves checking for signs of shock, such as cool, pale skin, tachycardia, and narrow pulse pressure.","kind":"recall","origin":"ai"},{"id":"fcp1-trauma-primary-survey~ai-4","moduleId":"fcp1-trauma-primary-survey","stem":"A trauma patient is cool, pale, and tachycardic with a narrow pulse pressure. Which module provides detailed management strategies for this condition?","options":[{"id":"a","text":"fcp1-shock-management"},{"id":"b","text":"fcp1-trauma-secondary-survey"},{"id":"c","text":"gastrointestinal-bleeding-approach"},{"id":"d","text":"melanoma-clinical"}],"answerId":"a","explanation":"The fcp1-shock-management module covers the recognition and initial management of shock.","kind":"integration","linkedModuleIds":["fcp1-shock-management"],"origin":"ai"},{"id":"fcp1-trauma-primary-survey~ai-5","moduleId":"fcp1-trauma-primary-survey","stem":"A patient with a history of gastrointestinal bleeding presents with hypotension and tachycardia. Which module would help in understanding the potential causes of shock in this context?","options":[{"id":"a","text":"fcp1-shock-classification"},{"id":"b","text":"fcp1-consciousness-coma-approach"},{"id":"c","text":"fcp1-hemoptysis-massive"},{"id":"d","text":"melanoma-clinical"}],"answerId":"a","explanation":"The fcp1-shock-classification module helps classify and understand the hemodynamic profiles of shock, including hypovolaemic shock from bleeding.","kind":"integration","linkedModuleIds":["fcp1-shock-classification"],"origin":"ai"}],"fcp1-chest-pain-cardiac":[{"id":"fcp1-chest-pain-cardiac~ai-0","moduleId":"fcp1-chest-pain-cardiac","stem":"A 60-year-old male presents with retrosternal chest pain radiating to his left arm, associated with diaphoresis and nausea. Which feature most strongly suggests an acute coronary syndrome?","options":[{"id":"a","text":"Radiation to the left arm"},{"id":"b","text":"Diaphoresis"},{"id":"c","text":"Retrosternal chest pain"},{"id":"d","text":"Nausea"}],"answerId":"a","explanation":"Radiation to the left arm is a classic feature of ischaemic cardiac pain, strongly suggesting ACS.","kind":"clinical","origin":"ai"},{"id":"fcp1-chest-pain-cardiac~ai-1","moduleId":"fcp1-chest-pain-cardiac","stem":"Which of the following is the most appropriate initial management for a patient with ST-elevation myocardial infarction (STEMI)?","options":[{"id":"a","text":"Immediate reperfusion therapy"},{"id":"b","text":"Serial troponin measurements"},{"id":"c","text":"Beta-blocker administration"},{"id":"d","text":"Nitrate administration"}],"answerId":"a","explanation":"Immediate reperfusion therapy is critical for STEMI to restore blood flow and minimize myocardial damage.","kind":"recall","origin":"ai"},{"id":"fcp1-chest-pain-cardiac~ai-2","moduleId":"fcp1-chest-pain-cardiac","stem":"A 72-year-old diabetic woman presents with fatigue and epigastric discomfort. Her ECG shows ST depression. What is the most likely diagnosis?","options":[{"id":"a","text":"Gastroesophageal reflux disease"},{"id":"b","text":"Acute coronary syndrome"},{"id":"c","text":"Peptic ulcer disease"},{"id":"d","text":"Cholecystitis"}],"answerId":"b","explanation":"Atypical presentations of ACS in diabetics can include fatigue and epigastric discomfort, with ECG changes supporting the diagnosis.","kind":"clinical","origin":"ai"},{"id":"fcp1-chest-pain-cardiac~ai-3","moduleId":"fcp1-chest-pain-cardiac","stem":"In the context of ACS, why is a single normal troponin level at presentation not sufficient to rule out myocardial infarction?","options":[{"id":"a","text":"Troponin is not specific for cardiac injury"},{"id":"b","text":"Troponin levels may not rise immediately"},{"id":"c","text":"Troponin is not sensitive for myocardial infarction"},{"id":"d","text":"Troponin levels can be affected by renal function"}],"answerId":"b","explanation":"Troponin levels may take several hours to rise after myocardial injury, necessitating serial measurements.","kind":"trap","origin":"ai"},{"id":"fcp1-chest-pain-cardiac~ai-4","moduleId":"fcp1-chest-pain-cardiac","stem":"A patient with chest pain has a normal initial ECG and troponin. What is the next best step in management?","options":[{"id":"a","text":"Discharge the patient"},{"id":"b","text":"Perform a stress test"},{"id":"c","text":"Repeat ECG and troponin after a few hours"},{"id":"d","text":"Start anticoagulation therapy"}],"answerId":"c","explanation":"Serial ECG and troponin tests are required to monitor for changes indicative of ACS.","kind":"trap","origin":"ai"},{"id":"fcp1-chest-pain-cardiac~ai-5","moduleId":"fcp1-chest-pain-cardiac","stem":"A 65-year-old male presents with severe abdominal pain and a history of atrial fibrillation. Which linked module condition should be considered in the differential diagnosis?","options":[{"id":"a","text":"Appendicitis"},{"id":"b","text":"Diverticular disease"},{"id":"c","text":"Ischaemic bowel disease"},{"id":"d","text":"Cholecystitis"}],"answerId":"c","explanation":"Ischaemic bowel disease should be considered, especially with a history of atrial fibrillation, which can lead to embolic events.","kind":"integration","linkedModuleIds":["appendicitis-diverticular-ischemic-bowel"],"origin":"ai"},{"id":"fcp1-chest-pain-cardiac~ai-6","moduleId":"fcp1-chest-pain-cardiac","stem":"A 55-year-old female presents with chest pain and an ECG showing ST elevation. Which linked module treatment is indicated?","options":[{"id":"a","text":"Antibiotics"},{"id":"b","text":"Fibrinolytics"},{"id":"c","text":"Antihypertensives"},{"id":"d","text":"Antacids"}],"answerId":"b","explanation":"Fibrinolytics are indicated in the treatment of STEMI to dissolve the thrombus and restore blood flow.","kind":"integration","linkedModuleIds":["fibrinolytics"],"origin":"ai"}],"fcp1-trauma-resuscitation":[{"id":"fcp1-trauma-resuscitation~ai-0","moduleId":"fcp1-trauma-resuscitation","stem":"A 25-year-old male is brought to the emergency department after a motorcycle accident. He is hypotensive with a systolic blood pressure of 85 mmHg. What is the most appropriate initial management step?","options":[{"id":"a","text":"Administer 2 liters of crystalloid"},{"id":"b","text":"Apply direct pressure to bleeding sites"},{"id":"c","text":"Initiate massive transfusion protocol"},{"id":"d","text":"Perform a CT scan of the abdomen"}],"answerId":"b","explanation":"Direct pressure is the first step in controlling external hemorrhage, which is a priority in trauma resuscitation.","kind":"recall","origin":"ai"},{"id":"fcp1-trauma-resuscitation~ai-1","moduleId":"fcp1-trauma-resuscitation","stem":"During trauma resuscitation, a patient exhibits cold, mottled skin and a weak, thready pulse. What is the underlying mechanism?","options":[{"id":"a","text":"Neurogenic shock"},{"id":"b","text":"Cardiogenic shock"},{"id":"c","text":"Hypovolaemic shock"},{"id":"d","text":"Septic shock"}],"answerId":"c","explanation":"These signs are indicative of hypovolaemic shock, commonly due to hemorrhage.","kind":"mechanism","origin":"ai"},{"id":"fcp1-trauma-resuscitation~ai-2","moduleId":"fcp1-trauma-resuscitation","stem":"A trauma patient continues to bleed despite fluid resuscitation, and their lactate levels are rising. What should be the next step in management?","options":[{"id":"a","text":"Administer more crystalloids"},{"id":"b","text":"Initiate massive transfusion protocol"},{"id":"c","text":"Perform exploratory laparotomy"},{"id":"d","text":"Start vasopressors"}],"answerId":"b","explanation":"Rising lactate and continued bleeding indicate the need for massive transfusion to replace lost blood components.","kind":"clinical","origin":"ai"},{"id":"fcp1-trauma-resuscitation~ai-3","moduleId":"fcp1-trauma-resuscitation","stem":"In the context of trauma resuscitation, why is permissive hypotension preferred until surgical control of bleeding is achieved?","options":[{"id":"a","text":"It ensures adequate cerebral perfusion"},{"id":"b","text":"It prevents dilution of clotting factors"},{"id":"c","text":"It increases cardiac output"},{"id":"d","text":"It stabilizes blood glucose levels"}],"answerId":"b","explanation":"Permissive hypotension avoids dislodging clots and diluting clotting factors, which can exacerbate bleeding.","kind":"mechanism","origin":"ai"},{"id":"fcp1-trauma-resuscitation~ai-4","moduleId":"fcp1-trauma-resuscitation","stem":"A patient with a severe pelvic fracture is hypotensive and tachycardic. Which intervention is most appropriate to control hemorrhage?","options":[{"id":"a","text":"Pelvic binder application"},{"id":"b","text":"Intravenous crystalloid infusion"},{"id":"c","text":"Immediate laparotomy"},{"id":"d","text":"High-dose vasopressors"}],"answerId":"a","explanation":"A pelvic binder helps control hemorrhage from pelvic fractures by stabilizing the pelvis and reducing bleeding.","kind":"recall","origin":"ai"},{"id":"fcp1-trauma-resuscitation~ai-5","moduleId":"fcp1-trauma-resuscitation","stem":"A trauma patient is receiving damage-control resuscitation. Which of the following is a component of this approach?","options":[{"id":"a","text":"High-volume crystalloid infusion"},{"id":"b","text":"Balanced blood product transfusion"},{"id":"c","text":"Immediate definitive surgical repair"},{"id":"d","text":"Delayed administration of tranexamic acid"}],"answerId":"b","explanation":"Damage-control resuscitation includes balanced blood product transfusion to address coagulopathy and hemorrhage.","kind":"recall","origin":"ai"},{"id":"fcp1-trauma-resuscitation~ai-6","moduleId":"fcp1-trauma-resuscitation","stem":"A patient in hypovolaemic shock is being resuscitated. What is the primary goal of permissive hypotension in this scenario?","options":[{"id":"a","text":"Maintain cerebral perfusion"},{"id":"b","text":"Prevent clot dislodgement"},{"id":"c","text":"Increase renal perfusion"},{"id":"d","text":"Normalize blood pressure"}],"answerId":"b","explanation":"Permissive hypotension helps prevent clot dislodgement and further bleeding until surgical control is achieved.","kind":"trap","origin":"ai"},{"id":"fcp1-trauma-resuscitation~ai-7","moduleId":"fcp1-trauma-resuscitation","stem":"Following a trauma primary survey, a patient is found to have a distended, rigid abdomen. What is the most likely cause?","options":[{"id":"a","text":"Pneumothorax"},{"id":"b","text":"Abdominal compartment syndrome"},{"id":"c","text":"Pericardial tamponade"},{"id":"d","text":"Neurogenic shock"}],"answerId":"b","explanation":"A distended, rigid abdomen after resuscitation suggests abdominal compartment syndrome due to concealed hemorrhage.","kind":"clinical","linkedModuleIds":["fcp1-trauma-primary-survey"],"origin":"ai"},{"id":"fcp1-trauma-resuscitation~ai-8","moduleId":"fcp1-trauma-resuscitation","stem":"In the management of a trauma patient with hemorrhagic shock, how does the approach differ from septic shock management?","options":[{"id":"a","text":"Use of high-dose vasopressors"},{"id":"b","text":"Immediate broad-spectrum antibiotics"},{"id":"c","text":"Permissive hypotension strategy"},{"id":"d","text":"Aggressive fluid resuscitation"}],"answerId":"c","explanation":"Permissive hypotension is specific to hemorrhagic shock to avoid exacerbating bleeding, unlike septic shock where fluid resuscitation is more aggressive.","kind":"integration","linkedModuleIds":["fcp1-shock-management"],"origin":"ai"}],"fcp1-chest-pain-differential":[{"id":"fcp1-chest-pain-differential~ai-0","moduleId":"fcp1-chest-pain-differential","stem":"A 55-year-old man presents with sudden onset of severe chest pain radiating to his back. Blood pressure is 150/90 mmHg in the right arm and 110/80 mmHg in the left arm. What is the most likely diagnosis?","options":[{"id":"a","text":"Aortic dissection"},{"id":"b","text":"Acute coronary syndrome"},{"id":"c","text":"Pulmonary embolism"},{"id":"d","text":"Tension pneumothorax"}],"answerId":"a","explanation":"Unequal arm blood pressures and tearing pain radiating to the back are classic signs of aortic dissection.","kind":"clinical","origin":"ai"},{"id":"fcp1-chest-pain-differential~ai-1","moduleId":"fcp1-chest-pain-differential","stem":"A 40-year-old woman with a history of deep vein thrombosis presents with pleuritic chest pain and dyspnea. She is tachycardic and has a swollen left calf. What is the most likely diagnosis?","options":[{"id":"a","text":"Pulmonary embolism"},{"id":"b","text":"Acute coronary syndrome"},{"id":"c","text":"Pericarditis"},{"id":"d","text":"Aortic dissection"}],"answerId":"a","explanation":"Pleuritic pain, tachycardia, and a swollen unilateral calf suggest a pulmonary embolism.","kind":"clinical","origin":"ai"},{"id":"fcp1-chest-pain-differential~ai-2","moduleId":"fcp1-chest-pain-differential","stem":"A 60-year-old man presents with chest pain that is relieved by sitting forward. On examination, a pericardial friction rub is heard. What is the most likely diagnosis?","options":[{"id":"a","text":"Pericarditis"},{"id":"b","text":"Acute coronary syndrome"},{"id":"c","text":"Pulmonary embolism"},{"id":"d","text":"Aortic dissection"}],"answerId":"a","explanation":"Pain relieved by sitting forward and a pericardial friction rub are indicative of pericarditis.","kind":"clinical","origin":"ai"},{"id":"fcp1-chest-pain-differential~ai-3","moduleId":"fcp1-chest-pain-differential","stem":"A 45-year-old male presents with chest pain after a large meal. The pain is retrosternal and burning in nature. Which condition must be ruled out before diagnosing gastroesophageal reflux disease?","options":[{"id":"a","text":"Acute coronary syndrome"},{"id":"b","text":"Costochondritis"},{"id":"c","text":"Pulmonary embolism"},{"id":"d","text":"Pericarditis"}],"answerId":"a","explanation":"Acute coronary syndrome must be ruled out before diagnosing gastroesophageal reflux disease due to overlapping symptoms.","kind":"trap","origin":"ai"},{"id":"fcp1-chest-pain-differential~ai-4","moduleId":"fcp1-chest-pain-differential","stem":"A 50-year-old woman presents with sudden onset dyspnea and chest pain. Her ECG shows right heart strain. Which linked module would provide further insights into her condition?","options":[{"id":"a","text":"fcp1-dyspnea-differential"},{"id":"b","text":"fcp1-chest-pain-cardiac"},{"id":"c","text":"fcp1-abdominal-pain-approach"},{"id":"d","text":"fcp1-chest-pain-red-flags"}],"answerId":"a","explanation":"The 'fcp1-dyspnea-differential' module provides insights into conditions causing dyspnea, including pulmonary embolism.","kind":"integration","linkedModuleIds":["fcp1-dyspnea-differential"],"origin":"ai"},{"id":"fcp1-chest-pain-differential~ai-5","moduleId":"fcp1-chest-pain-differential","stem":"A patient with tearing chest pain radiating to the back and unequal arm blood pressures is suspected of having aortic dissection. Which linked module would be most relevant for further study?","options":[{"id":"a","text":"aortic-dissection"},{"id":"b","text":"fcp1-chest-pain-cardiac"},{"id":"c","text":"fcp1-abdominal-pain-approach"},{"id":"d","text":"fcp1-chest-pain-red-flags"}],"answerId":"a","explanation":"The 'aortic-dissection' module is directly relevant for further study of aortic dissection.","kind":"integration","linkedModuleIds":["aortic-dissection"],"origin":"ai"}],"fcp1-cyanosis":[{"id":"fcp1-cyanosis~ai-0","moduleId":"fcp1-cyanosis","stem":"A patient presents with bluish discoloration of the tongue and lips. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Arterial hypoxaemia"},{"id":"b","text":"Reduced peripheral blood flow"},{"id":"c","text":"Increased peripheral extraction"},{"id":"d","text":"Venous occlusion"}],"answerId":"a","explanation":"Central cyanosis involves the tongue and lips, indicating arterial hypoxaemia.","kind":"mechanism","origin":"ai"},{"id":"fcp1-cyanosis~ai-1","moduleId":"fcp1-cyanosis","stem":"A patient with severe anemia shows no cyanosis despite hypoxia. Why is cyanosis absent?","options":[{"id":"a","text":"Low arterial oxygen saturation"},{"id":"b","text":"Low total hemoglobin"},{"id":"c","text":"High peripheral extraction"},{"id":"d","text":"High arterial oxygen saturation"}],"answerId":"b","explanation":"In anemia, there may be insufficient hemoglobin to reach the 5 g/dL deoxyHb threshold for cyanosis.","kind":"trap","origin":"ai"},{"id":"fcp1-cyanosis~ai-2","moduleId":"fcp1-cyanosis","stem":"Which condition is suggested by cyanosis that does not improve with high-flow oxygen but shows normal PaO2?","options":[{"id":"a","text":"Arterial hypoxaemia"},{"id":"b","text":"Peripheral cyanosis"},{"id":"c","text":"Methaemoglobinaemia"},{"id":"d","text":"Polycythaemia"}],"answerId":"c","explanation":"Methaemoglobinaemia presents with a saturation gap and cyanosis unresponsive to oxygen.","kind":"clinical","origin":"ai"},{"id":"fcp1-cyanosis~ai-3","moduleId":"fcp1-cyanosis","stem":"A patient at high altitude develops cyanosis. Which type is most likely?","options":[{"id":"a","text":"Central cyanosis"},{"id":"b","text":"Peripheral cyanosis"},{"id":"c","text":"Methaemoglobinaemia"},{"id":"d","text":"Polycythaemia"}],"answerId":"a","explanation":"High altitude can cause central cyanosis due to arterial hypoxaemia.","kind":"recall","origin":"ai"},{"id":"fcp1-cyanosis~ai-4","moduleId":"fcp1-cyanosis","stem":"A patient with polycythaemia appears cyanotic. What is the explanation?","options":[{"id":"a","text":"Increased deoxyHb concentration"},{"id":"b","text":"Decreased arterial oxygen saturation"},{"id":"c","text":"Increased peripheral blood flow"},{"id":"d","text":"Decreased peripheral extraction"}],"answerId":"a","explanation":"Polycythaemia increases total hemoglobin, making cyanosis appear with less deoxygenation.","kind":"mechanism","origin":"ai"},{"id":"fcp1-cyanosis~ai-5","moduleId":"fcp1-cyanosis","stem":"A patient presents with blue fingers and toes but a pink tongue. What is the most likely cause?","options":[{"id":"a","text":"Arterial hypoxaemia"},{"id":"b","text":"Reduced peripheral blood flow"},{"id":"c","text":"Methaemoglobinaemia"},{"id":"d","text":"High altitude exposure"}],"answerId":"b","explanation":"Peripheral cyanosis affects extremities due to reduced blood flow, sparing the tongue.","kind":"clinical","origin":"ai"},{"id":"fcp1-cyanosis~ai-6","moduleId":"fcp1-cyanosis","stem":"A patient with dyspnea and cyanosis is evaluated. Which test would help differentiate between central and peripheral cyanosis?","options":[{"id":"a","text":"Arterial blood gas analysis"},{"id":"b","text":"Complete blood count"},{"id":"c","text":"Chest X-ray"},{"id":"d","text":"Electrocardiogram"}],"answerId":"a","explanation":"ABG can confirm arterial hypoxaemia, indicating central cyanosis.","kind":"integration","linkedModuleIds":["fcp1-dyspnea-approach"],"origin":"ai"},{"id":"fcp1-cyanosis~ai-7","moduleId":"fcp1-cyanosis","stem":"How does anemia affect the clinical presentation of cyanosis?","options":[{"id":"a","text":"Increases visibility of cyanosis"},{"id":"b","text":"Masks cyanosis"},{"id":"c","text":"Does not affect cyanosis"},{"id":"d","text":"Causes peripheral cyanosis"}],"answerId":"b","explanation":"Anemia can mask cyanosis due to insufficient hemoglobin to reach the 5 g/dL threshold.","kind":"integration","linkedModuleIds":["fcp1-anemia-classification"],"origin":"ai"}],"fcp1-dyspnea-approach":[{"id":"fcp1-dyspnea-approach~ai-0","moduleId":"fcp1-dyspnea-approach","stem":"A 65-year-old male presents with sudden onset dyspnea and pleuritic chest pain. On examination, there is unilateral absent breath sounds with hyperresonance. What is the most likely diagnosis?","options":[{"id":"a","text":"Pneumothorax"},{"id":"b","text":"Pulmonary embolism"},{"id":"c","text":"Pneumonia"},{"id":"d","text":"Asthma"}],"answerId":"a","explanation":"Unilateral absent breath sounds with hyperresonance is indicative of a pneumothorax.","kind":"clinical","origin":"ai"},{"id":"fcp1-dyspnea-approach~ai-1","moduleId":"fcp1-dyspnea-approach","stem":"A patient with a history of COPD presents with worsening dyspnea. On examination, there is a widespread wheeze with prolonged expiration. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Obstructive airway disease"},{"id":"b","text":"Restrictive lung disease"},{"id":"c","text":"Cardiac failure"},{"id":"d","text":"Pulmonary embolism"}],"answerId":"a","explanation":"Widespread wheeze with prolonged expiration is characteristic of obstructive airway disease such as COPD.","kind":"mechanism","origin":"ai"},{"id":"fcp1-dyspnea-approach~ai-2","moduleId":"fcp1-dyspnea-approach","stem":"In the assessment of dyspnea, which of the following is a late sign indicating severe respiratory compromise?","options":[{"id":"a","text":"Cyanosis"},{"id":"b","text":"Tachypnea"},{"id":"c","text":"Wheezing"},{"id":"d","text":"Orthopnea"}],"answerId":"a","explanation":"Cyanosis is a late sign of severe respiratory compromise.","kind":"recall","origin":"ai"},{"id":"fcp1-dyspnea-approach~ai-3","moduleId":"fcp1-dyspnea-approach","stem":"A 70-year-old female with a history of heart failure presents with acute dyspnea. Examination reveals raised JVP, orthopnea, and bibasal crackles. Which additional finding would most likely confirm the cardiac origin of her symptoms?","options":[{"id":"a","text":"S3 heart sound"},{"id":"b","text":"Wheezing"},{"id":"c","text":"Unilateral crackles"},{"id":"d","text":"Hyperresonance"}],"answerId":"a","explanation":"An S3 heart sound is associated with heart failure, confirming a cardiac cause of dyspnea.","kind":"clinical","origin":"ai"},{"id":"fcp1-dyspnea-approach~ai-4","moduleId":"fcp1-dyspnea-approach","stem":"A patient with acute asthma presents with a silent chest and exhaustion. What is the most appropriate next step in management?","options":[{"id":"a","text":"Administer high-flow oxygen and escalate care"},{"id":"b","text":"Reassure the patient and monitor"},{"id":"c","text":"Administer oral corticosteroids"},{"id":"d","text":"Perform a chest X-ray"}],"answerId":"a","explanation":"A silent chest indicates life-threatening asthma; immediate high-flow oxygen and escalation are critical.","kind":"trap","origin":"ai"},{"id":"fcp1-dyspnea-approach~ai-5","moduleId":"fcp1-dyspnea-approach","stem":"A 55-year-old male presents with acute chest pain and dyspnea. ECG shows ST elevation in leads II, III, and aVF. What is the most likely cause of his dyspnea?","options":[{"id":"a","text":"Acute myocardial infarction"},{"id":"b","text":"Pneumothorax"},{"id":"c","text":"Pulmonary embolism"},{"id":"d","text":"Asthma"}],"answerId":"a","explanation":"ST elevation in leads II, III, and aVF indicates an inferior myocardial infarction, which can cause dyspnea.","kind":"integration","linkedModuleIds":["fcp1-chest-pain-differential"],"origin":"ai"},{"id":"fcp1-dyspnea-approach~ai-6","moduleId":"fcp1-dyspnea-approach","stem":"A patient with chronic dyspnea presents with cyanosis. Which of the following tests would best differentiate between central and peripheral cyanosis?","options":[{"id":"a","text":"Arterial blood gas"},{"id":"b","text":"Chest X-ray"},{"id":"c","text":"Electrocardiogram"},{"id":"d","text":"Spirometry"}],"answerId":"a","explanation":"Arterial blood gas analysis can help differentiate between central and peripheral cyanosis by assessing oxygenation.","kind":"integration","linkedModuleIds":["fcp1-cyanosis"],"origin":"ai"}],"fcp1-chest-pain-red-flags":[{"id":"fcp1-chest-pain-red-flags~ai-0","moduleId":"fcp1-chest-pain-red-flags","stem":"A 55-year-old man presents with sudden onset chest pain radiating to his back. His blood pressure is 160/90 mmHg in the right arm and 110/70 mmHg in the left arm. What is the most likely diagnosis?","options":[{"id":"a","text":"Acute myocardial infarction"},{"id":"b","text":"Pulmonary embolism"},{"id":"c","text":"Aortic dissection"},{"id":"d","text":"Pneumothorax"}],"answerId":"c","explanation":"Unequal blood pressure in the arms is a classic sign of aortic dissection.","kind":"recall","origin":"ai"},{"id":"fcp1-chest-pain-red-flags~ai-1","moduleId":"fcp1-chest-pain-red-flags","stem":"A patient with chest pain has distended neck veins, muffled heart sounds, and hypotension. What is the most likely diagnosis?","options":[{"id":"a","text":"Pulmonary embolism"},{"id":"b","text":"Cardiac tamponade"},{"id":"c","text":"Tension pneumothorax"},{"id":"d","text":"Myocardial infarction"}],"answerId":"b","explanation":"Beck's triad (distended neck veins, muffled heart sounds, hypotension) is indicative of cardiac tamponade.","kind":"recall","origin":"ai"},{"id":"fcp1-chest-pain-red-flags~ai-2","moduleId":"fcp1-chest-pain-red-flags","stem":"A 45-year-old woman presents with chest pain and syncope. Her vital signs are stable now, but she had transient hypotension. What is the appropriate management?","options":[{"id":"a","text":"Discharge with follow-up"},{"id":"b","text":"Admit for observation"},{"id":"c","text":"Immediate CT angiography"},{"id":"d","text":"Administer nitroglycerin"}],"answerId":"b","explanation":"Syncope with chest pain and any unstable vital sign warrants admission for further work-up.","kind":"trap","origin":"ai"},{"id":"fcp1-chest-pain-red-flags~ai-3","moduleId":"fcp1-chest-pain-red-flags","stem":"Which of the following is a red flag feature in a patient presenting with chest pain?","options":[{"id":"a","text":"Pain reproducible by palpation"},{"id":"b","text":"Pain relieved by antacids"},{"id":"c","text":"Pain with exertion"},{"id":"d","text":"Pain lasting less than 5 minutes"}],"answerId":"c","explanation":"Exertional chest pain is a red flag indicating possible cardiac ischemia.","kind":"recall","origin":"ai"},{"id":"fcp1-chest-pain-red-flags~ai-4","moduleId":"fcp1-chest-pain-red-flags","stem":"A 60-year-old male presents with chest pain and dyspnea. His ECG shows ST elevation in leads II, III, and aVF. Which lethal cause is most likely?","options":[{"id":"a","text":"Aortic dissection"},{"id":"b","text":"Pulmonary embolism"},{"id":"c","text":"Inferior myocardial infarction"},{"id":"d","text":"Tension pneumothorax"}],"answerId":"c","explanation":"ST elevation in leads II, III, and aVF indicates an inferior myocardial infarction.","kind":"clinical","origin":"ai"},{"id":"fcp1-chest-pain-red-flags~ai-5","moduleId":"fcp1-chest-pain-red-flags","stem":"A patient with chest pain has a normal initial ECG and troponin. Which additional test is most appropriate to rule out a pulmonary embolism?","options":[{"id":"a","text":"Echocardiography"},{"id":"b","text":"CT angiography"},{"id":"c","text":"Chest X-ray"},{"id":"d","text":"D-dimer"}],"answerId":"b","explanation":"CT angiography is the preferred test to rule out pulmonary embolism.","kind":"mechanism","origin":"ai"},{"id":"fcp1-chest-pain-red-flags~ai-6","moduleId":"fcp1-chest-pain-red-flags","stem":"A 30-year-old male presents with sudden onset dyspnea and pleuritic chest pain. On examination, he has decreased breath sounds on the right side. Which condition should be considered?","options":[{"id":"a","text":"Pulmonary embolism"},{"id":"b","text":"Pneumothorax"},{"id":"c","text":"Myocardial infarction"},{"id":"d","text":"Aortic dissection"}],"answerId":"b","explanation":"Decreased breath sounds on one side with sudden dyspnea and pleuritic pain suggests pneumothorax.","kind":"integration","linkedModuleIds":["fcp1-dyspnea-approach"],"origin":"ai"},{"id":"fcp1-chest-pain-red-flags~ai-7","moduleId":"fcp1-chest-pain-red-flags","stem":"A 50-year-old female with a history of hypertension presents with chest pain radiating to her jaw and left arm. Which module should be reviewed for further understanding of this presentation?","options":[{"id":"a","text":"fcp1-dyspnea-approach"},{"id":"b","text":"fcp1-chest-pain-cardiac"},{"id":"c","text":"fcp1-chest-pain-differential"},{"id":"d","text":"fcp1-chest-pain-red-flags"}],"answerId":"b","explanation":"Chest pain radiating to the jaw and arm is often cardiac in nature, related to ischemic causes.","kind":"integration","linkedModuleIds":["fcp1-chest-pain-cardiac"],"origin":"ai"}],"fcp1-cough-approach":[{"id":"fcp1-cough-approach~ai-0","moduleId":"fcp1-cough-approach","stem":"A 45-year-old non-smoker presents with a chronic cough lasting 10 weeks. Chest X-ray is normal. Which condition is least likely to be the cause?","options":[{"id":"a","text":"Upper airway cough syndrome"},{"id":"b","text":"Asthma"},{"id":"c","text":"Gastro-oesophageal reflux disease"},{"id":"d","text":"Pulmonary embolism"}],"answerId":"d","explanation":"In a non-smoker with a normal CXR, chronic cough is usually due to UACS, asthma, or GERD, not pulmonary embolism.","kind":"recall","origin":"ai"},{"id":"fcp1-cough-approach~ai-1","moduleId":"fcp1-cough-approach","stem":"A patient presents with a cough that worsens after meals and when lying flat, accompanied by heartburn. What is the most likely diagnosis?","options":[{"id":"a","text":"Asthma"},{"id":"b","text":"Upper airway cough syndrome"},{"id":"c","text":"Gastro-oesophageal reflux disease"},{"id":"d","text":"Heart failure"}],"answerId":"c","explanation":"Cough associated with meals and lying flat, along with heartburn, suggests gastro-oesophageal reflux disease.","kind":"clinical","origin":"ai"},{"id":"fcp1-cough-approach~ai-2","moduleId":"fcp1-cough-approach","stem":"A 60-year-old smoker presents with a new cough, weight loss, and night sweats. What is the most appropriate next step in management?","options":[{"id":"a","text":"Start empirical antibiotics"},{"id":"b","text":"Order a chest X-ray"},{"id":"c","text":"Prescribe an ACE inhibitor"},{"id":"d","text":"Initiate GERD treatment"}],"answerId":"b","explanation":"Red flags such as weight loss and night sweats in a smoker necessitate a chest X-ray to rule out malignancy or tuberculosis.","kind":"trap","origin":"ai"},{"id":"fcp1-cough-approach~ai-3","moduleId":"fcp1-cough-approach","stem":"Which of the following is a common cause of chronic cough in a patient taking an ACE inhibitor?","options":[{"id":"a","text":"Asthma"},{"id":"b","text":"Upper airway cough syndrome"},{"id":"c","text":"Gastro-oesophageal reflux disease"},{"id":"d","text":"The ACE inhibitor itself"}],"answerId":"d","explanation":"ACE inhibitors can cause a chronic dry cough, which resolves upon discontinuation of the medication.","kind":"mechanism","origin":"ai"},{"id":"fcp1-cough-approach~ai-4","moduleId":"fcp1-cough-approach","stem":"A patient with a history of GERD presents with a chronic cough. Which linked module would provide additional relevant information for managing this patient?","options":[{"id":"a","text":"fcp1-chest-pain-differential"},{"id":"b","text":"fcp1-dyspnea-approach"},{"id":"c","text":"fcp1-dyspepsia-reflux"},{"id":"d","text":"hrp1-trauma-asd-ptsd-first-aid"}],"answerId":"c","explanation":"The fcp1-dyspepsia-reflux module covers GERD, which is relevant for managing cough associated with GERD.","kind":"integration","linkedModuleIds":["fcp1-dyspepsia-reflux"],"origin":"ai"},{"id":"fcp1-cough-approach~ai-5","moduleId":"fcp1-cough-approach","stem":"A 50-year-old presents with cough and progressive dyspnea. Which linked module should be consulted for a comprehensive approach to this symptom?","options":[{"id":"a","text":"fcp1-chest-pain-differential"},{"id":"b","text":"fcp1-dyspnea-approach"},{"id":"c","text":"hrp1-trauma-asd-ptsd-first-aid"},{"id":"d","text":"fcp1-hemoptysis-approach"}],"answerId":"b","explanation":"The fcp1-dyspnea-approach module provides guidance on assessing progressive dyspnea, which is relevant for this patient.","kind":"integration","linkedModuleIds":["fcp1-dyspnea-approach"],"origin":"ai"}],"fcp1-hemoptysis-approach":[{"id":"fcp1-hemoptysis-approach~ai-0","moduleId":"fcp1-hemoptysis-approach","stem":"A 55-year-old smoker presents with hemoptysis, weight loss, and a chronic cough. What is the most likely diagnosis?","options":[{"id":"a","text":"Bronchogenic carcinoma"},{"id":"b","text":"Tuberculosis"},{"id":"c","text":"Bronchiectasis"},{"id":"d","text":"Pulmonary embolism"}],"answerId":"a","explanation":"The combination of hemoptysis, weight loss, and smoking history is highly suggestive of bronchogenic carcinoma.","kind":"clinical","origin":"ai"},{"id":"fcp1-hemoptysis-approach~ai-1","moduleId":"fcp1-hemoptysis-approach","stem":"Which of the following findings is most indicative of hemoptysis rather than haematemesis?","options":[{"id":"a","text":"Dark blood with food particles"},{"id":"b","text":"Bright red, frothy blood mixed with sputum"},{"id":"c","text":"Acidic pH of the blood"},{"id":"d","text":"Presence of melena"}],"answerId":"b","explanation":"Bright red, frothy blood mixed with sputum is characteristic of hemoptysis, distinguishing it from haematemesis.","kind":"recall","origin":"ai"},{"id":"fcp1-hemoptysis-approach~ai-2","moduleId":"fcp1-hemoptysis-approach","stem":"A patient presents with massive hemoptysis. What is the immediate next step in management?","options":[{"id":"a","text":"Perform bronchoscopy"},{"id":"b","text":"Administer intravenous fluids"},{"id":"c","text":"Secure the airway"},{"id":"d","text":"Order a chest X-ray"}],"answerId":"c","explanation":"In massive hemoptysis, securing the airway is the priority to prevent asphyxiation.","kind":"trap","origin":"ai"},{"id":"fcp1-hemoptysis-approach~ai-3","moduleId":"fcp1-hemoptysis-approach","stem":"A 30-year-old man with a history of cystic fibrosis presents with chronic copious purulent sputum and clubbing. Which condition is most likely?","options":[{"id":"a","text":"Bronchiectasis"},{"id":"b","text":"Tuberculosis"},{"id":"c","text":"Asthma"},{"id":"d","text":"Pulmonary embolism"}],"answerId":"a","explanation":"Chronic copious purulent sputum with clubbing is characteristic of bronchiectasis, especially in cystic fibrosis.","kind":"clinical","origin":"ai"},{"id":"fcp1-hemoptysis-approach~ai-4","moduleId":"fcp1-hemoptysis-approach","stem":"In a patient with hemoptysis, which test is most useful for identifying a pulmonary embolism?","options":[{"id":"a","text":"Chest X-ray"},{"id":"b","text":"CT angiography"},{"id":"c","text":"Sputum culture"},{"id":"d","text":"Bronchoscopy"}],"answerId":"b","explanation":"CT angiography is the most useful test for identifying a pulmonary embolism in a patient with hemoptysis.","kind":"mechanism","origin":"ai"},{"id":"fcp1-hemoptysis-approach~ai-5","moduleId":"fcp1-hemoptysis-approach","stem":"A patient presents with hemoptysis and a history of mitral stenosis. Which linked module would provide additional relevant information?","options":[{"id":"a","text":"fcp1-chest-pain-differential"},{"id":"b","text":"asthma-bronchiectasis-pathology"},{"id":"c","text":"fcp1-gi-bleed-upper"},{"id":"d","text":"fcp1-nausea-vomiting"}],"answerId":"a","explanation":"Mitral stenosis can lead to pulmonary hypertension and hemoptysis, linking it to chest pain differentials.","kind":"integration","linkedModuleIds":["fcp1-chest-pain-differential"],"origin":"ai"},{"id":"fcp1-hemoptysis-approach~ai-6","moduleId":"fcp1-hemoptysis-approach","stem":"A 45-year-old male with a history of recurrent pneumonia presents with hemoptysis. Which condition should be considered that links to bronchiectasis?","options":[{"id":"a","text":"Asthma"},{"id":"b","text":"Tuberculosis"},{"id":"c","text":"Chronic obstructive pulmonary disease"},{"id":"d","text":"Bronchiectasis"}],"answerId":"d","explanation":"Recurrent pneumonia can lead to bronchiectasis, which is associated with hemoptysis.","kind":"integration","linkedModuleIds":["add-bronchiectasis-etiology-and-clinical-features"],"origin":"ai"}],"fcp1-hemoptysis-massive":[{"id":"fcp1-hemoptysis-massive~ai-0","moduleId":"fcp1-hemoptysis-massive","stem":"What is the primary immediate threat to life in a patient with massive hemoptysis?","options":[{"id":"a","text":"Asphyxiation"},{"id":"b","text":"Exsanguination"},{"id":"c","text":"Infection"},{"id":"d","text":"Pulmonary embolism"}],"answerId":"a","explanation":"In massive hemoptysis, the primary threat is asphyxiation due to blood flooding the airways.","kind":"recall","origin":"ai"},{"id":"fcp1-hemoptysis-massive~ai-1","moduleId":"fcp1-hemoptysis-massive","stem":"A patient presents with massive hemoptysis. After securing the airway, what is the next immediate step in management?","options":[{"id":"a","text":"Position the patient bleeding-side down"},{"id":"b","text":"Perform bronchoscopy"},{"id":"c","text":"Administer broad-spectrum antibiotics"},{"id":"d","text":"Initiate transfusion"}],"answerId":"a","explanation":"Positioning the patient bleeding-side down prevents blood from entering the healthy lung.","kind":"mechanism","origin":"ai"},{"id":"fcp1-hemoptysis-massive~ai-2","moduleId":"fcp1-hemoptysis-massive","stem":"Which of the following is the first-line definitive therapy for massive hemoptysis?","options":[{"id":"a","text":"Bronchial artery embolisation"},{"id":"b","text":"Surgical resection"},{"id":"c","text":"Systemic anticoagulation"},{"id":"d","text":"High-dose corticosteroids"}],"answerId":"a","explanation":"Bronchial artery embolisation is the first-line definitive therapy as most bleeding originates from the bronchial arteries.","kind":"recall","origin":"ai"},{"id":"fcp1-hemoptysis-massive~ai-3","moduleId":"fcp1-hemoptysis-massive","stem":"During the primary survey of a trauma patient with massive hemoptysis, which step should be prioritized?","options":[{"id":"a","text":"Airway protection"},{"id":"b","text":"Control of external bleeding"},{"id":"c","text":"Neurological assessment"},{"id":"d","text":"Splinting fractures"}],"answerId":"a","explanation":"Airway protection is prioritized to prevent asphyxiation from blood flooding the airways.","kind":"integration","linkedModuleIds":["fcp1-trauma-primary-survey"],"origin":"ai"},{"id":"fcp1-hemoptysis-massive~ai-4","moduleId":"fcp1-hemoptysis-massive","stem":"In a patient with massive hemoptysis, which clinical sign suggests impending asphyxiation?","options":[{"id":"a","text":"Falling oxygen saturation"},{"id":"b","text":"Hypertension"},{"id":"c","text":"Bradycardia"},{"id":"d","text":"Peripheral cyanosis"}],"answerId":"a","explanation":"Falling oxygen saturation indicates impaired gas exchange due to blood filling the alveoli.","kind":"clinical","origin":"ai"},{"id":"fcp1-hemoptysis-massive~ai-5","moduleId":"fcp1-hemoptysis-massive","stem":"A patient with massive hemoptysis is intubated. What is the rationale for using a large-bore endotracheal tube?","options":[{"id":"a","text":"Facilitates bronchial artery embolisation"},{"id":"b","text":"Allows for better ventilation of both lungs"},{"id":"c","text":"Prevents aspiration of gastric contents"},{"id":"d","text":"Enables suctioning of blood from the airways"}],"answerId":"d","explanation":"A large-bore tube allows for effective suctioning of blood from the airways to maintain airway patency.","kind":"mechanism","origin":"ai"},{"id":"fcp1-hemoptysis-massive~ai-6","moduleId":"fcp1-hemoptysis-massive","stem":"Which of the following conditions should be considered in the differential diagnosis of massive hemoptysis due to its potential to cause airway obstruction?","options":[{"id":"a","text":"Tracheoesophageal fistula"},{"id":"b","text":"Pulmonary embolism"},{"id":"c","text":"Aortic dissection"},{"id":"d","text":"Bronchogenic carcinoma"}],"answerId":"d","explanation":"Bronchogenic carcinoma can cause massive hemoptysis and potential airway obstruction.","kind":"integration","linkedModuleIds":["fcp1-hemoptysis-approach"],"origin":"ai"}],"fcp1-dyspnea-differential":[{"id":"fcp1-dyspnea-differential~ai-0","moduleId":"fcp1-dyspnea-differential","stem":"A 60-year-old man presents with sudden onset dyspnea and pleuritic chest pain. He has a history of recent long-haul flight. Examination reveals tachycardia and hypoxia with clear lung fields. What is the most likely diagnosis?","options":[{"id":"a","text":"Pulmonary embolism"},{"id":"b","text":"Pneumothorax"},{"id":"c","text":"Pneumonia"},{"id":"d","text":"Heart failure"}],"answerId":"a","explanation":"The clear lung fields with hypoxia and tachycardia in the context of risk factors suggest pulmonary embolism.","kind":"clinical","origin":"ai"},{"id":"fcp1-dyspnea-differential~ai-1","moduleId":"fcp1-dyspnea-differential","stem":"A patient presents with dyspnea, orthopnea, and paroxysmal nocturnal dyspnea. Examination shows raised JVP and bibasal crackles. What is the most likely underlying condition?","options":[{"id":"a","text":"Asthma"},{"id":"b","text":"Heart failure"},{"id":"c","text":"Pneumonia"},{"id":"d","text":"Pulmonary embolism"}],"answerId":"b","explanation":"Orthopnea, PND, raised JVP, and bibasal crackles are indicative of left heart failure.","kind":"recall","origin":"ai"},{"id":"fcp1-dyspnea-differential~ai-2","moduleId":"fcp1-dyspnea-differential","stem":"A 25-year-old woman presents with sudden onset of dyspnea and chest pain. Examination reveals unilateral absent breath sounds and hyperresonance on percussion. What is the most likely diagnosis?","options":[{"id":"a","text":"Pneumothorax"},{"id":"b","text":"Pulmonary embolism"},{"id":"c","text":"Asthma"},{"id":"d","text":"Heart failure"}],"answerId":"a","explanation":"Unilateral absent breath sounds with hyperresonance suggest a pneumothorax.","kind":"recall","origin":"ai"},{"id":"fcp1-dyspnea-differential~ai-3","moduleId":"fcp1-dyspnea-differential","stem":"A 35-year-old woman presents with dyspnea and pallor. Her respiratory examination is normal. What is the most likely cause of her symptoms?","options":[{"id":"a","text":"Anxiety"},{"id":"b","text":"Anemia"},{"id":"c","text":"Pulmonary embolism"},{"id":"d","text":"Asthma"}],"answerId":"b","explanation":"Pallor with a normal respiratory examination suggests anemia.","kind":"trap","origin":"ai"},{"id":"fcp1-dyspnea-differential~ai-4","moduleId":"fcp1-dyspnea-differential","stem":"A 50-year-old man with a history of COPD presents with worsening dyspnea and wheezing. What is the most likely mechanism of his symptoms?","options":[{"id":"a","text":"Airway obstruction"},{"id":"b","text":"Pulmonary embolism"},{"id":"c","text":"Heart failure"},{"id":"d","text":"Anemia"}],"answerId":"a","explanation":"Wheezing and dyspnea in a patient with COPD are due to airway obstruction.","kind":"mechanism","origin":"ai"},{"id":"fcp1-dyspnea-differential~ai-5","moduleId":"fcp1-dyspnea-differential","stem":"A patient presents with acute dyspnea, clear lung fields, and a swollen calf. Which condition should be ruled out first?","options":[{"id":"a","text":"Asthma"},{"id":"b","text":"Pulmonary embolism"},{"id":"c","text":"Pneumonia"},{"id":"d","text":"Heart failure"}],"answerId":"b","explanation":"Clear lungs with hypoxia and a swollen calf suggest pulmonary embolism.","kind":"clinical","origin":"ai"},{"id":"fcp1-dyspnea-differential~ai-6","moduleId":"fcp1-dyspnea-differential","stem":"A 40-year-old woman presents with dyspnea and chest pain. Her ECG shows ST-elevation. Which module should be consulted for further differential diagnosis?","options":[{"id":"a","text":"fcp1-chest-pain-differential"},{"id":"b","text":"fcp1-anemia-classification"},{"id":"c","text":"hhl-dic-thrombosis"},{"id":"d","text":"fcp1-edema-approach"}],"answerId":"a","explanation":"ST-elevation suggests a cardiac cause; the chest pain differential module is relevant.","kind":"integration","linkedModuleIds":["fcp1-chest-pain-differential"],"origin":"ai"},{"id":"fcp1-dyspnea-differential~ai-7","moduleId":"fcp1-dyspnea-differential","stem":"A 55-year-old male with dyspnea is found to have anemia. Which module would assist in classifying the type of anemia?","options":[{"id":"a","text":"fcp1-anemia-classification"},{"id":"b","text":"fcp1-dyspnea-approach"},{"id":"c","text":"fcp1-edema-approach"},{"id":"d","text":"hhl-dic-thrombosis"}],"answerId":"a","explanation":"The anemia classification module helps in determining the type of anemia.","kind":"integration","linkedModuleIds":["fcp1-anemia-classification"],"origin":"ai"}],"fcp1-dyspepsia-reflux":[{"id":"fcp1-dyspepsia-reflux~ai-0","moduleId":"fcp1-dyspepsia-reflux","stem":"A 45-year-old man presents with burning retrosternal pain after meals. Which condition is most likely responsible?","options":[{"id":"a","text":"Gastro-oesophageal reflux disease"},{"id":"b","text":"Peptic ulcer disease"},{"id":"c","text":"Gastric malignancy"},{"id":"d","text":"Functional dyspepsia"}],"answerId":"a","explanation":"Burning retrosternal pain after meals is characteristic of gastro-oesophageal reflux disease.","kind":"clinical","origin":"ai"},{"id":"fcp1-dyspepsia-reflux~ai-1","moduleId":"fcp1-dyspepsia-reflux","stem":"Which of the following is an alarm feature that mandates urgent endoscopy in a patient with dyspepsia?","options":[{"id":"a","text":"Postprandial fullness"},{"id":"b","text":"Early satiety"},{"id":"c","text":"Anaemia"},{"id":"d","text":"Burning sensation"}],"answerId":"c","explanation":"Anaemia is an alarm feature that requires urgent endoscopy to rule out serious conditions like gastric malignancy.","kind":"recall","origin":"ai"},{"id":"fcp1-dyspepsia-reflux~ai-2","moduleId":"fcp1-dyspepsia-reflux","stem":"A 60-year-old woman with new-onset dyspepsia and weight loss should undergo which of the following?","options":[{"id":"a","text":"PPI trial"},{"id":"b","text":"H. pylori test-and-treat"},{"id":"c","text":"Immediate endoscopy"},{"id":"d","text":"Lifestyle modification"}],"answerId":"c","explanation":"New-onset dyspepsia over age 55 with weight loss is an alarm feature, requiring immediate endoscopy.","kind":"trap","origin":"ai"},{"id":"fcp1-dyspepsia-reflux~ai-3","moduleId":"fcp1-dyspepsia-reflux","stem":"Which test is recommended in uncomplicated dyspepsia without alarm features?","options":[{"id":"a","text":"Immediate endoscopy"},{"id":"b","text":"H. pylori urea breath test"},{"id":"c","text":"Barium swallow"},{"id":"d","text":"CT scan of the abdomen"}],"answerId":"b","explanation":"In uncomplicated dyspepsia without alarm features, a test-and-treat strategy for H. pylori is recommended.","kind":"mechanism","origin":"ai"},{"id":"fcp1-dyspepsia-reflux~ai-4","moduleId":"fcp1-dyspepsia-reflux","stem":"A patient with GERD symptoms is at risk for which of the following complications if left untreated?","options":[{"id":"a","text":"Barrett oesophagus"},{"id":"b","text":"Gastric ulcer"},{"id":"c","text":"Duodenal ulcer"},{"id":"d","text":"Zollinger-Ellison syndrome"}],"answerId":"a","explanation":"Untreated GERD can progress to Barrett oesophagus, which is a risk factor for adenocarcinoma.","kind":"recall","origin":"ai"},{"id":"fcp1-dyspepsia-reflux~ai-5","moduleId":"fcp1-dyspepsia-reflux","stem":"A 50-year-old man presents with chest pain. Which of the following should be excluded first?","options":[{"id":"a","text":"Gastro-oesophageal reflux disease"},{"id":"b","text":"Peptic ulcer disease"},{"id":"c","text":"Cardiac cause"},{"id":"d","text":"Functional dyspepsia"}],"answerId":"c","explanation":"GERD can mimic cardiac pain, so a cardiac cause should be excluded first.","kind":"integration","linkedModuleIds":["fcp1-chest-pain-differential"],"origin":"ai"},{"id":"fcp1-dyspepsia-reflux~ai-6","moduleId":"fcp1-dyspepsia-reflux","stem":"A 70-year-old man with dysphagia and weight loss presents to the clinic. Which module should be consulted for further evaluation?","options":[{"id":"a","text":"Approach to Dysphagia"},{"id":"b","text":"Approach to Cough"},{"id":"c","text":"Swallowing Phases & Airway Protection"},{"id":"d","text":"Upper GI Bleeding"}],"answerId":"a","explanation":"Dysphagia with weight loss is an alarm feature, and the 'Approach to Dysphagia' module provides guidance on evaluation.","kind":"integration","linkedModuleIds":["fcp1-dysphagia"],"origin":"ai"}],"fcp1-abdominal-pain-acute-abdomen":[{"id":"fcp1-abdominal-pain-acute-abdomen~ai-0","moduleId":"fcp1-abdominal-pain-acute-abdomen","stem":"A 65-year-old man presents with sudden severe abdominal pain and a pulsatile abdominal mass. What is the most likely diagnosis?","options":[{"id":"a","text":"Ruptured abdominal aortic aneurysm"},{"id":"b","text":"Acute pancreatitis"},{"id":"c","text":"Mesenteric ischemia"},{"id":"d","text":"Perforated peptic ulcer"}],"answerId":"a","explanation":"A pulsatile abdominal mass with hypotension suggests a ruptured abdominal aortic aneurysm.","kind":"clinical","origin":"ai"},{"id":"fcp1-abdominal-pain-acute-abdomen~ai-1","moduleId":"fcp1-abdominal-pain-acute-abdomen","stem":"Which of the following findings is most indicative of bowel obstruction?","options":[{"id":"a","text":"Board-like rigidity"},{"id":"b","text":"Rebound tenderness"},{"id":"c","text":"High-pitched bowel sounds"},{"id":"d","text":"Pulsatile abdominal mass"}],"answerId":"c","explanation":"High-pitched bowel sounds with distension and vomiting suggest bowel obstruction.","kind":"recall","origin":"ai"},{"id":"fcp1-abdominal-pain-acute-abdomen~ai-2","moduleId":"fcp1-abdominal-pain-acute-abdomen","stem":"A patient presents with severe abdominal pain but a soft, non-tender abdomen. What condition should be suspected?","options":[{"id":"a","text":"Acute appendicitis"},{"id":"b","text":"Mesenteric ischemia"},{"id":"c","text":"Perforated peptic ulcer"},{"id":"d","text":"Ruptured ectopic pregnancy"}],"answerId":"b","explanation":"Severe pain with a soft abdomen is classic for early mesenteric ischemia.","kind":"trap","origin":"ai"},{"id":"fcp1-abdominal-pain-acute-abdomen~ai-3","moduleId":"fcp1-abdominal-pain-acute-abdomen","stem":"What is the initial management step for a patient with suspected perforated peptic ulcer?","options":[{"id":"a","text":"Administer oral antibiotics"},{"id":"b","text":"Perform emergency endoscopy"},{"id":"c","text":"Resuscitate with IV fluids"},{"id":"d","text":"Prescribe proton pump inhibitors"}],"answerId":"c","explanation":"Resuscitation with IV fluids is crucial in managing a suspected perforated peptic ulcer.","kind":"mechanism","origin":"ai"},{"id":"fcp1-abdominal-pain-acute-abdomen~ai-4","moduleId":"fcp1-abdominal-pain-acute-abdomen","stem":"A 30-year-old woman presents with acute lower abdominal pain and hypotension. A pregnancy test is positive. What is the most likely diagnosis?","options":[{"id":"a","text":"Acute appendicitis"},{"id":"b","text":"Ruptured ectopic pregnancy"},{"id":"c","text":"Ovarian torsion"},{"id":"d","text":"Pelvic inflammatory disease"}],"answerId":"b","explanation":"Acute abdominal pain with hypotension and a positive pregnancy test suggests a ruptured ectopic pregnancy.","kind":"clinical","origin":"ai"},{"id":"fcp1-abdominal-pain-acute-abdomen~ai-5","moduleId":"fcp1-abdominal-pain-acute-abdomen","stem":"Which laboratory test is most useful in confirming mesenteric ischemia?","options":[{"id":"a","text":"Serum amylase"},{"id":"b","text":"Serum lactate"},{"id":"c","text":"Complete blood count"},{"id":"d","text":"Serum lipase"}],"answerId":"b","explanation":"Elevated serum lactate is indicative of mesenteric ischemia due to tissue hypoperfusion.","kind":"recall","origin":"ai"},{"id":"fcp1-abdominal-pain-acute-abdomen~ai-6","moduleId":"fcp1-abdominal-pain-acute-abdomen","stem":"A patient with suspected shock presents with abdominal pain. Which linked module provides guidance on initial management?","options":[{"id":"a","text":"fcp1-pelvic-pain-approach"},{"id":"b","text":"fcp1-shock-management"},{"id":"c","text":"brain-energy-metabolism"},{"id":"d","text":"fcp1-nausea-vomiting"}],"answerId":"b","explanation":"The 'fcp1-shock-management' module covers the initial management of shock, which is relevant for this patient.","kind":"integration","linkedModuleIds":["fcp1-shock-management"],"origin":"ai"},{"id":"fcp1-abdominal-pain-acute-abdomen~ai-7","moduleId":"fcp1-abdominal-pain-acute-abdomen","stem":"In the context of acute abdomen, which module would help in differentiating causes of pelvic pain in females?","options":[{"id":"a","text":"fcp1-abdominal-pain-approach"},{"id":"b","text":"fcp1-pelvic-pain-approach"},{"id":"c","text":"fcp1-pediatric-abdominal-pain"},{"id":"d","text":"fcp1-nausea-vomiting"}],"answerId":"b","explanation":"The 'fcp1-pelvic-pain-approach' module is specifically designed to differentiate causes of pelvic pain.","kind":"integration","linkedModuleIds":["fcp1-pelvic-pain-approach"],"origin":"ai"}],"fcp1-nausea-vomiting":[{"id":"fcp1-nausea-vomiting~ai-0","moduleId":"fcp1-nausea-vomiting","stem":"A 25-year-old woman presents with nausea and vomiting for the past week. She denies abdominal pain, diarrhea, or fever. Her last menstrual period was 6 weeks ago. What is the most likely cause of her symptoms?","options":[{"id":"a","text":"Pregnancy"},{"id":"b","text":"Gastroenteritis"},{"id":"c","text":"Peptic ulcer disease"},{"id":"d","text":"Migraine"}],"answerId":"a","explanation":"In a woman of reproductive age with nausea and vomiting, pregnancy should always be considered.","kind":"recall","origin":"ai"},{"id":"fcp1-nausea-vomiting~ai-1","moduleId":"fcp1-nausea-vomiting","stem":"A patient presents with vomiting and headache that worsens in the morning and on straining. What is the most appropriate next step in management?","options":[{"id":"a","text":"Administer antiemetics"},{"id":"b","text":"Perform a CT scan of the head"},{"id":"c","text":"Prescribe proton pump inhibitors"},{"id":"d","text":"Order a stool culture"}],"answerId":"b","explanation":"Morning vomiting with headache suggests raised intracranial pressure, requiring neuro-imaging.","kind":"trap","origin":"ai"},{"id":"fcp1-nausea-vomiting~ai-2","moduleId":"fcp1-nausea-vomiting","stem":"Which of the following mechanisms is responsible for vomiting triggered by head movement?","options":[{"id":"a","text":"Chemoreceptor trigger zone activation"},{"id":"b","text":"Vestibular apparatus stimulation"},{"id":"c","text":"Gastrointestinal vagal afferent activation"},{"id":"d","text":"Higher cortical center involvement"}],"answerId":"b","explanation":"Vomiting triggered by head movement is due to vestibular apparatus stimulation.","kind":"mechanism","origin":"ai"},{"id":"fcp1-nausea-vomiting~ai-3","moduleId":"fcp1-nausea-vomiting","stem":"A 60-year-old man with a history of alcohol use presents with hematemesis. What complication of vomiting is most likely responsible?","options":[{"id":"a","text":"Mallory-Weiss tear"},{"id":"b","text":"Esophageal varices"},{"id":"c","text":"Peptic ulcer"},{"id":"d","text":"Gastric cancer"}],"answerId":"a","explanation":"Mallory-Weiss tears are mucosal lacerations at the gastroesophageal junction due to forceful vomiting.","kind":"clinical","origin":"ai"},{"id":"fcp1-nausea-vomiting~ai-4","moduleId":"fcp1-nausea-vomiting","stem":"A patient presents with bilious vomiting and abdominal distension. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Gastroenteritis"},{"id":"b","text":"Bowel obstruction"},{"id":"c","text":"Migraine"},{"id":"d","text":"Vestibular dysfunction"}],"answerId":"b","explanation":"Bilious vomiting with abdominal distension suggests bowel obstruction.","kind":"recall","origin":"ai"},{"id":"fcp1-nausea-vomiting~ai-5","moduleId":"fcp1-nausea-vomiting","stem":"A 30-year-old woman presents with nausea and vomiting. She is found to have dry mucous membranes and tachycardia. What electrolyte imbalance is she most likely to have?","options":[{"id":"a","text":"Hypokalemia"},{"id":"b","text":"Hyperkalemia"},{"id":"c","text":"Hyponatremia"},{"id":"d","text":"Hypernatremia"}],"answerId":"a","explanation":"Vomiting can lead to hypokalemia due to loss of gastric contents.","kind":"clinical","origin":"ai"},{"id":"fcp1-nausea-vomiting~ai-6","moduleId":"fcp1-nausea-vomiting","stem":"A patient with a history of motion sickness presents with nausea and vomiting. Which class of antiemetic is most appropriate for this patient?","options":[{"id":"a","text":"Antihistamines"},{"id":"b","text":"Dopamine antagonists"},{"id":"c","text":"Serotonin antagonists"},{"id":"d","text":"Corticosteroids"}],"answerId":"a","explanation":"Antihistamines are effective for nausea and vomiting due to vestibular causes like motion sickness.","kind":"integration","linkedModuleIds":["add-pharmacology-of-antiemetic-agents"],"origin":"ai"},{"id":"fcp1-nausea-vomiting~ai-7","moduleId":"fcp1-nausea-vomiting","stem":"A 45-year-old man presents with nausea, vomiting, and a severe headache. Which associated symptom would most strongly suggest raised intracranial pressure?","options":[{"id":"a","text":"Photophobia"},{"id":"b","text":"Neck stiffness"},{"id":"c","text":"Projectile vomiting"},{"id":"d","text":"Tinnitus"}],"answerId":"c","explanation":"Projectile vomiting with headache is a classic sign of raised intracranial pressure.","kind":"integration","linkedModuleIds":["raised-icp-herniation"],"origin":"ai"}],"fcp1-abdominal-pain-approach":[{"id":"fcp1-abdominal-pain-approach~ai-0","moduleId":"fcp1-abdominal-pain-approach","stem":"A 24-year-old female presents with sudden onset of severe right lower quadrant pain. She reports nausea and vomiting. What is the most likely diagnosis?","options":[{"id":"a","text":"Appendicitis"},{"id":"b","text":"Ectopic pregnancy"},{"id":"c","text":"Ovarian torsion"},{"id":"d","text":"Diverticulitis"}],"answerId":"a","explanation":"The classic presentation of appendicitis includes periumbilical pain migrating to the right iliac fossa, often accompanied by nausea and vomiting.","kind":"clinical","origin":"ai"},{"id":"fcp1-abdominal-pain-approach~ai-1","moduleId":"fcp1-abdominal-pain-approach","stem":"Which type of abdominal pain is characterized by being sharp, well-localized, and worsens with movement?","options":[{"id":"a","text":"Visceral pain"},{"id":"b","text":"Parietal pain"},{"id":"c","text":"Referred pain"},{"id":"d","text":"Neuropathic pain"}],"answerId":"b","explanation":"Parietal pain results from peritoneal irritation and is sharp, well-localized, and worsens with movement.","kind":"recall","origin":"ai"},{"id":"fcp1-abdominal-pain-approach~ai-2","moduleId":"fcp1-abdominal-pain-approach","stem":"A patient presents with epigastric pain radiating to the back. Which condition is most likely?","options":[{"id":"a","text":"Peptic ulcer disease"},{"id":"b","text":"Pancreatitis"},{"id":"c","text":"Cholecystitis"},{"id":"d","text":"Renal colic"}],"answerId":"b","explanation":"Pancreatitis often presents with epigastric pain that radiates to the back.","kind":"clinical","origin":"ai"},{"id":"fcp1-abdominal-pain-approach~ai-3","moduleId":"fcp1-abdominal-pain-approach","stem":"In a patient with suspected appendicitis, which finding would suggest progression to peritonitis?","options":[{"id":"a","text":"Periumbilical pain"},{"id":"b","text":"Rebound tenderness"},{"id":"c","text":"Colicky pain"},{"id":"d","text":"Flank pain"}],"answerId":"b","explanation":"Rebound tenderness indicates parietal peritoneal irritation, suggesting progression to peritonitis.","kind":"recall","origin":"ai"},{"id":"fcp1-abdominal-pain-approach~ai-4","moduleId":"fcp1-abdominal-pain-approach","stem":"A 45-year-old male presents with colicky flank pain radiating to the groin. What is the most likely diagnosis?","options":[{"id":"a","text":"Renal colic"},{"id":"b","text":"Appendicitis"},{"id":"c","text":"Diverticulitis"},{"id":"d","text":"Pancreatitis"}],"answerId":"a","explanation":"Colicky flank pain radiating to the groin is characteristic of ureteric colic.","kind":"clinical","origin":"ai"},{"id":"fcp1-abdominal-pain-approach~ai-5","moduleId":"fcp1-abdominal-pain-approach","stem":"A 30-year-old female presents with lower abdominal pain and missed periods. Which condition must be excluded first?","options":[{"id":"a","text":"Appendicitis"},{"id":"b","text":"Diverticulitis"},{"id":"c","text":"Ectopic pregnancy"},{"id":"d","text":"Ovarian cyst"}],"answerId":"c","explanation":"In women of reproductive age with abdominal pain and missed periods, ectopic pregnancy must be excluded first.","kind":"trap","origin":"ai"},{"id":"fcp1-abdominal-pain-approach~ai-6","moduleId":"fcp1-abdominal-pain-approach","stem":"A patient with jaundice and right upper quadrant pain should be evaluated for which condition, considering the linked module on obstructive jaundice?","options":[{"id":"a","text":"Cholecystitis"},{"id":"b","text":"Pancreatitis"},{"id":"c","text":"Appendicitis"},{"id":"d","text":"Renal colic"}],"answerId":"a","explanation":"Right upper quadrant pain with jaundice suggests a biliary cause such as cholecystitis or cholestasis.","kind":"integration","linkedModuleIds":["fcp1-jaundice-cholestasis"],"origin":"ai"},{"id":"fcp1-abdominal-pain-approach~ai-7","moduleId":"fcp1-abdominal-pain-approach","stem":"How does the embryological origin of the gut influence the localization of visceral pain in appendicitis?","options":[{"id":"a","text":"Foregut origin leads to epigastric pain"},{"id":"b","text":"Midgut origin leads to periumbilical pain"},{"id":"c","text":"Hindgut origin leads to suprapubic pain"},{"id":"d","text":"Foregut origin leads to shoulder pain"}],"answerId":"b","explanation":"Appendicitis initially causes periumbilical pain due to its midgut origin.","kind":"mechanism","origin":"ai"},{"id":"fcp1-abdominal-pain-approach~ai-8","moduleId":"fcp1-abdominal-pain-approach","stem":"A 50-year-old male presents with chest pain and epigastric discomfort. Which linked module should be considered to differentiate cardiac from abdominal causes?","options":[{"id":"a","text":"fcp1-chest-pain-differential"},{"id":"b","text":"fcp1-pelvic-pain-approach"},{"id":"c","text":"fcp1-nausea-vomiting"},{"id":"d","text":"fcp1-abdominal-pain-acute-abdomen"}],"answerId":"a","explanation":"The chest pain differential module helps differentiate cardiac causes from abdominal causes of epigastric pain.","kind":"integration","linkedModuleIds":["fcp1-chest-pain-differential"],"origin":"ai"}],"fcp1-gi-bleed-lower":[{"id":"fcp1-gi-bleed-lower~ai-0","moduleId":"fcp1-gi-bleed-lower","stem":"A 65-year-old male presents with painless, large-volume haematochezia. What is the most likely cause?","options":[{"id":"a","text":"Diverticular disease"},{"id":"b","text":"Colorectal cancer"},{"id":"c","text":"Haemorrhoids"},{"id":"d","text":"Ischaemic colitis"}],"answerId":"a","explanation":"Painless, large-volume haematochezia in an older adult is typically due to diverticular disease.","kind":"recall","origin":"ai"},{"id":"fcp1-gi-bleed-lower~ai-1","moduleId":"fcp1-gi-bleed-lower","stem":"A patient with haematochezia is hemodynamically unstable. What should be the initial step in management?","options":[{"id":"a","text":"Perform a colonoscopy"},{"id":"b","text":"Administer IV fluids"},{"id":"c","text":"Order a CT scan"},{"id":"d","text":"Perform an upper endoscopy"}],"answerId":"b","explanation":"In hemodynamically unstable patients, resuscitation with IV fluids is the priority.","kind":"mechanism","origin":"ai"},{"id":"fcp1-gi-bleed-lower~ai-2","moduleId":"fcp1-gi-bleed-lower","stem":"A 50-year-old presents with blood mixed in stool and tenesmus. Which condition is most likely?","options":[{"id":"a","text":"Diverticular disease"},{"id":"b","text":"Colorectal cancer"},{"id":"c","text":"Haemorrhoids"},{"id":"d","text":"Angiodysplasia"}],"answerId":"b","explanation":"Blood mixed with stool and tenesmus suggests colorectal cancer.","kind":"clinical","origin":"ai"},{"id":"fcp1-gi-bleed-lower~ai-3","moduleId":"fcp1-gi-bleed-lower","stem":"In a patient with fresh rectal bleeding and hemodynamic instability, why is it crucial to consider an upper GI source?","options":[{"id":"a","text":"Upper GI bleeds are more common"},{"id":"b","text":"Upper GI bleeds can present as haematochezia"},{"id":"c","text":"Lower GI bleeds never cause instability"},{"id":"d","text":"Upper GI bleeds are easier to treat"}],"answerId":"b","explanation":"A brisk upper GI bleed can transit quickly and present as fresh PR blood with shock.","kind":"trap","origin":"ai"},{"id":"fcp1-gi-bleed-lower~ai-4","moduleId":"fcp1-gi-bleed-lower","stem":"A 70-year-old male with known diverticular disease presents with iron-deficiency anemia. Which linked condition should be considered?","options":[{"id":"a","text":"Colorectal cancer"},{"id":"b","text":"Angiodysplasia"},{"id":"c","text":"Haemorrhoids"},{"id":"d","text":"Ischaemic colitis"}],"answerId":"a","explanation":"Occult bleeding from colorectal cancer can cause iron-deficiency anemia.","kind":"integration","linkedModuleIds":["fcp1-anemia-microcytic"],"origin":"ai"},{"id":"fcp1-gi-bleed-lower~ai-5","moduleId":"fcp1-gi-bleed-lower","stem":"A patient with a history of Crohn's disease presents with bloody diarrhea. Which investigation is most appropriate?","options":[{"id":"a","text":"Upper endoscopy"},{"id":"b","text":"Colonoscopy"},{"id":"c","text":"Abdominal ultrasound"},{"id":"d","text":"CT scan"}],"answerId":"b","explanation":"Colonoscopy is the key investigation for assessing lower GI bleeding in Crohn's disease.","kind":"integration","linkedModuleIds":["inflammatory-bowel-disease"],"origin":"ai"}],"fcp1-dysphagia":[{"id":"fcp1-dysphagia~ai-0","moduleId":"fcp1-dysphagia","stem":"A 70-year-old man presents with progressive dysphagia to solids and recent weight loss. What is the most likely diagnosis?","options":[{"id":"a","text":"Oesophageal cancer"},{"id":"b","text":"Achalasia"},{"id":"c","text":"Peptic stricture"},{"id":"d","text":"Myasthenia gravis"}],"answerId":"a","explanation":"Progressive dysphagia to solids with weight loss in an older patient is highly suggestive of oesophageal cancer.","kind":"clinical","origin":"ai"},{"id":"fcp1-dysphagia~ai-1","moduleId":"fcp1-dysphagia","stem":"Which of the following symptoms is most indicative of oropharyngeal dysphagia?","options":[{"id":"a","text":"Coughing during swallowing"},{"id":"b","text":"Food sticking behind the sternum"},{"id":"c","text":"Progressive difficulty with solids"},{"id":"d","text":"Odynophagia"}],"answerId":"a","explanation":"Coughing during swallowing suggests aspiration, which is characteristic of oropharyngeal dysphagia.","kind":"recall","origin":"ai"},{"id":"fcp1-dysphagia~ai-2","moduleId":"fcp1-dysphagia","stem":"A patient reports difficulty swallowing both solids and liquids from the onset. Which condition is most likely?","options":[{"id":"a","text":"Achalasia"},{"id":"b","text":"Peptic stricture"},{"id":"c","text":"Oesophageal cancer"},{"id":"d","text":"Zenker's diverticulum"}],"answerId":"a","explanation":"Dysphagia to both solids and liquids from the start is indicative of a motility disorder such as achalasia.","kind":"mechanism","origin":"ai"},{"id":"fcp1-dysphagia~ai-3","moduleId":"fcp1-dysphagia","stem":"In the context of dysphagia, what does odynophagia most commonly indicate?","options":[{"id":"a","text":"Infective oesophagitis"},{"id":"b","text":"Achalasia"},{"id":"c","text":"Oesophageal cancer"},{"id":"d","text":"Peptic stricture"}],"answerId":"a","explanation":"Odynophagia, or painful swallowing, is commonly associated with infective, pill-induced, or ulcerative oesophagitis.","kind":"recall","origin":"ai"},{"id":"fcp1-dysphagia~ai-4","moduleId":"fcp1-dysphagia","stem":"A patient with a history of GERD presents with progressive dysphagia to solids. Which condition should be considered?","options":[{"id":"a","text":"Peptic stricture"},{"id":"b","text":"Achalasia"},{"id":"c","text":"Oesophageal cancer"},{"id":"d","text":"Myasthenia gravis"}],"answerId":"a","explanation":"GERD can lead to peptic stricture, causing progressive dysphagia to solids.","kind":"integration","linkedModuleIds":["fcp1-dyspepsia-reflux"],"origin":"ai"},{"id":"fcp1-dysphagia~ai-5","moduleId":"fcp1-dysphagia","stem":"A 55-year-old woman presents with difficulty swallowing and weight loss. She also reports hoarseness. Which linked condition should be evaluated?","options":[{"id":"a","text":"Thyroid enlargement"},{"id":"b","text":"Achalasia"},{"id":"c","text":"Peptic stricture"},{"id":"d","text":"Myasthenia gravis"}],"answerId":"a","explanation":"Hoarseness and dysphagia with weight loss could indicate thyroid enlargement affecting the esophagus.","kind":"integration","linkedModuleIds":["fcp1-thyroid-approach"],"origin":"ai"},{"id":"fcp1-dysphagia~ai-6","moduleId":"fcp1-dysphagia","stem":"Which of the following is a red flag for urgent endoscopy in a patient with dysphagia?","options":[{"id":"a","text":"Progressive dysphagia with weight loss"},{"id":"b","text":"Intermittent dysphagia to solids"},{"id":"c","text":"Odynophagia without weight loss"},{"id":"d","text":"Dysphagia to liquids only"}],"answerId":"a","explanation":"Progressive dysphagia with weight loss is a red flag for oesophageal cancer, necessitating urgent endoscopy.","kind":"trap","origin":"ai"}],"fcp1-constipation-bowel-habit":[{"id":"fcp1-constipation-bowel-habit~ai-0","moduleId":"fcp1-constipation-bowel-habit","stem":"A 55-year-old patient presents with a new onset of constipation and rectal bleeding. What is the most appropriate next step?","options":[{"id":"a","text":"Reassure and advise dietary changes"},{"id":"b","text":"Prescribe a laxative"},{"id":"c","text":"Order a colonoscopy"},{"id":"d","text":"Perform a CT scan of the abdomen"}],"answerId":"c","explanation":"A new persistent change in bowel habit with rectal bleeding in a patient over 50 is a red flag for colorectal cancer, warranting a colonoscopy.","kind":"trap","origin":"ai"},{"id":"fcp1-constipation-bowel-habit~ai-1","moduleId":"fcp1-constipation-bowel-habit","stem":"Which of the following is a primary cause of constipation?","options":[{"id":"a","text":"Opioid use"},{"id":"b","text":"Hypothyroidism"},{"id":"c","text":"Normal-transit constipation"},{"id":"d","text":"Parkinson's disease"}],"answerId":"c","explanation":"Normal-transit constipation is a type of primary or functional constipation.","kind":"recall","origin":"ai"},{"id":"fcp1-constipation-bowel-habit~ai-2","moduleId":"fcp1-constipation-bowel-habit","stem":"A patient with constipation has dry skin, bradycardia, and delayed reflexes. What is the likely underlying cause?","options":[{"id":"a","text":"Hypercalcaemia"},{"id":"b","text":"Hypothyroidism"},{"id":"c","text":"Diabetes mellitus"},{"id":"d","text":"Parkinson's disease"}],"answerId":"b","explanation":"These symptoms suggest hypothyroidism, which can cause secondary constipation.","kind":"clinical","origin":"ai"},{"id":"fcp1-constipation-bowel-habit~ai-3","moduleId":"fcp1-constipation-bowel-habit","stem":"A 60-year-old presents with alternating constipation and diarrhea. Which feature would most strongly suggest colorectal cancer?","options":[{"id":"a","text":"Family history of IBS"},{"id":"b","text":"Nocturnal diarrhea"},{"id":"c","text":"Weight gain"},{"id":"d","text":"Normal colonoscopy 5 years ago"}],"answerId":"b","explanation":"Nocturnal diarrhea is an alarm feature that suggests an organic cause like colorectal cancer.","kind":"mechanism","origin":"ai"},{"id":"fcp1-constipation-bowel-habit~ai-4","moduleId":"fcp1-constipation-bowel-habit","stem":"In a patient with constipation, which examination finding would suggest a neurological cause?","options":[{"id":"a","text":"Hard faecal loading on PR exam"},{"id":"b","text":"Reduced sphincter tone"},{"id":"c","text":"Abdominal distension"},{"id":"d","text":"Rectal bleeding"}],"answerId":"b","explanation":"Reduced sphincter tone can indicate a neurological cause of constipation.","kind":"recall","origin":"ai"},{"id":"fcp1-constipation-bowel-habit~ai-5","moduleId":"fcp1-constipation-bowel-habit","stem":"A 45-year-old with a history of IBS presents with a palpable abdominal mass. Which module should be consulted for further differential diagnosis?","options":[{"id":"a","text":"fcp1-abdominal-mass-differential"},{"id":"b","text":"fcp1-gi-bleed-lower"},{"id":"c","text":"fcp1-diarrhea-approach"},{"id":"d","text":"fcp1-anemia-microcytic"}],"answerId":"a","explanation":"The presence of an abdominal mass requires consulting the 'Abdominal Mass: Differential by Region' module.","kind":"integration","linkedModuleIds":["fcp1-abdominal-mass-differential"],"origin":"ai"},{"id":"fcp1-constipation-bowel-habit~ai-6","moduleId":"fcp1-constipation-bowel-habit","stem":"A patient presents with a change in bowel habit and iron-deficiency anemia. Which module should be reviewed for potential causes?","options":[{"id":"a","text":"fcp1-abdominal-mass-differential"},{"id":"b","text":"fcp1-gi-bleed-lower"},{"id":"c","text":"fcp1-diarrhea-approach"},{"id":"d","text":"fcp1-anemia-microcytic"}],"answerId":"d","explanation":"Iron-deficiency anemia with a change in bowel habit suggests reviewing the 'Anemia: Microcytic' module for potential causes.","kind":"integration","origin":"ai"}],"fcp1-diarrhea-approach":[{"id":"fcp1-diarrhea-approach~ai-0","moduleId":"fcp1-diarrhea-approach","stem":"A 25-year-old male presents with acute diarrhea for 3 days. He reports watery stools but denies blood or mucus. What is the most likely mechanism?","options":[{"id":"a","text":"Osmotic"},{"id":"b","text":"Secretory"},{"id":"c","text":"Inflammatory"},{"id":"d","text":"Motility"}],"answerId":"b","explanation":"Acute watery diarrhea without blood or mucus is typically secretory, often due to infections like cholera.","kind":"mechanism","origin":"ai"},{"id":"fcp1-diarrhea-approach~ai-1","moduleId":"fcp1-diarrhea-approach","stem":"A 60-year-old female presents with chronic diarrhea and unintentional weight loss. Which initial investigation is most appropriate?","options":[{"id":"a","text":"Stool culture"},{"id":"b","text":"Coeliac serology"},{"id":"c","text":"Colonoscopy"},{"id":"d","text":"Abdominal ultrasound"}],"answerId":"c","explanation":"Chronic diarrhea with weight loss and age over 50 requires colonoscopy to rule out malignancy or IBD.","kind":"clinical","origin":"ai"},{"id":"fcp1-diarrhea-approach~ai-2","moduleId":"fcp1-diarrhea-approach","stem":"A 30-year-old patient with a history of lactose intolerance presents with diarrhea that resolves with fasting. What is the most likely mechanism?","options":[{"id":"a","text":"Osmotic"},{"id":"b","text":"Secretory"},{"id":"c","text":"Inflammatory"},{"id":"d","text":"Motility"}],"answerId":"a","explanation":"Osmotic diarrhea, such as from lactose intolerance, resolves with fasting.","kind":"mechanism","origin":"ai"},{"id":"fcp1-diarrhea-approach~ai-3","moduleId":"fcp1-diarrhea-approach","stem":"A 45-year-old male presents with bloody diarrhea and fever. What is the most appropriate management step?","options":[{"id":"a","text":"Administer loperamide"},{"id":"b","text":"Start oral rehydration therapy"},{"id":"c","text":"Prescribe antibiotics immediately"},{"id":"d","text":"Order a CT scan"}],"answerId":"b","explanation":"Oral rehydration is crucial in dysentery; antimotility agents like loperamide are contraindicated.","kind":"trap","origin":"ai"},{"id":"fcp1-diarrhea-approach~ai-4","moduleId":"fcp1-diarrhea-approach","stem":"A 50-year-old male with a history of hypertension presents with diarrhea after starting a new medication. Which class of drugs is most likely responsible?","options":[{"id":"a","text":"ACE inhibitors"},{"id":"b","text":"Beta-blockers"},{"id":"c","text":"Calcium channel blockers"},{"id":"d","text":"Thiazide diuretics"}],"answerId":"a","explanation":"ACE inhibitors can cause diarrhea as a side effect.","kind":"clinical","origin":"ai"},{"id":"fcp1-diarrhea-approach~ai-5","moduleId":"fcp1-diarrhea-approach","stem":"A 70-year-old patient presents with chronic diarrhea and a family history of colorectal cancer. Which symptom would most strongly suggest an organic cause?","options":[{"id":"a","text":"Diarrhea that resolves at night"},{"id":"b","text":"Diarrhea with mucus"},{"id":"c","text":"Nocturnal diarrhea"},{"id":"d","text":"Diarrhea after meals"}],"answerId":"c","explanation":"Nocturnal diarrhea is a red flag for organic causes, warranting further investigation.","kind":"clinical","origin":"ai"},{"id":"fcp1-diarrhea-approach~ai-6","moduleId":"fcp1-diarrhea-approach","stem":"A 5-year-old child presents with diarrhea and vomiting. Which module provides additional insights into pediatric cases?","options":[{"id":"a","text":"fcp1-weight-loss-approach"},{"id":"b","text":"fcp1-pediatric-vomiting-diarrhea"},{"id":"c","text":"galactokinase-cataracts"},{"id":"d","text":"fcp1-gi-bleed-lower"}],"answerId":"b","explanation":"The module 'fcp1-pediatric-vomiting-diarrhea' is relevant for pediatric diarrhea cases.","kind":"integration","linkedModuleIds":["fcp1-pediatric-vomiting-diarrhea"],"origin":"ai"},{"id":"fcp1-diarrhea-approach~ai-7","moduleId":"fcp1-diarrhea-approach","stem":"A patient presents with chronic diarrhea and significant weight loss. Which module would assist in further evaluation of weight loss?","options":[{"id":"a","text":"fcp1-weight-loss-approach"},{"id":"b","text":"potassium-sparing-osmotic-diuretics"},{"id":"c","text":"fcp1-constipation-bowel-habit"},{"id":"d","text":"galactokinase-cataracts"}],"answerId":"a","explanation":"The 'fcp1-weight-loss-approach' module provides guidance on evaluating unintentional weight loss.","kind":"integration","linkedModuleIds":["fcp1-weight-loss-approach"],"origin":"ai"}],"fcp1-gi-bleed-upper":[{"id":"fcp1-gi-bleed-upper~ai-0","moduleId":"fcp1-gi-bleed-upper","stem":"A 55-year-old male presents with haematemesis and melaena. Which of the following is the most likely cause of his symptoms?","options":[{"id":"a","text":"Peptic ulcer disease"},{"id":"b","text":"Diverticulosis"},{"id":"c","text":"Colorectal cancer"},{"id":"d","text":"Hemorrhoids"}],"answerId":"a","explanation":"Peptic ulcer disease is the most common cause of upper GI bleeding.","kind":"recall","origin":"ai"},{"id":"fcp1-gi-bleed-upper~ai-1","moduleId":"fcp1-gi-bleed-upper","stem":"A patient with suspected upper GI bleeding shows a raised urea-to-creatinine ratio. What does this suggest?","options":[{"id":"a","text":"Upper GI source"},{"id":"b","text":"Lower GI source"},{"id":"c","text":"Renal failure"},{"id":"d","text":"Liver failure"}],"answerId":"a","explanation":"A raised urea-to-creatinine ratio suggests an upper GI source due to digestion and absorption of blood as protein.","kind":"mechanism","origin":"ai"},{"id":"fcp1-gi-bleed-upper~ai-2","moduleId":"fcp1-gi-bleed-upper","stem":"In a patient with haematemesis and signs of shock, what is the immediate next step in management?","options":[{"id":"a","text":"Endoscopy"},{"id":"b","text":"Resuscitation"},{"id":"c","text":"Blood transfusion"},{"id":"d","text":"CT scan"}],"answerId":"b","explanation":"Resuscitation is prioritized in haemodynamic instability before proceeding to endoscopy.","kind":"clinical","origin":"ai"},{"id":"fcp1-gi-bleed-upper~ai-3","moduleId":"fcp1-gi-bleed-upper","stem":"A 60-year-old male with a history of alcohol abuse presents with haematemesis. Examination reveals spider naevi and ascites. What is the likely source of bleeding?","options":[{"id":"a","text":"Gastric varices"},{"id":"b","text":"Peptic ulcer"},{"id":"c","text":"Mallory-Weiss tear"},{"id":"d","text":"Erosive gastritis"}],"answerId":"a","explanation":"Stigmata of chronic liver disease suggest portal hypertension and variceal bleeding.","kind":"clinical","origin":"ai"},{"id":"fcp1-gi-bleed-upper~ai-4","moduleId":"fcp1-gi-bleed-upper","stem":"A patient presents with black, tarry stools and a normal haemoglobin level. What is the most appropriate interpretation?","options":[{"id":"a","text":"No significant bleeding"},{"id":"b","text":"Early stage of upper GI bleed"},{"id":"c","text":"Lower GI bleed"},{"id":"d","text":"Chronic blood loss"}],"answerId":"b","explanation":"Normal haemoglobin can occur early in an upper GI bleed before haemodilution.","kind":"trap","origin":"ai"},{"id":"fcp1-gi-bleed-upper~ai-5","moduleId":"fcp1-gi-bleed-upper","stem":"A patient with dyspepsia and a history of NSAID use presents with haematemesis. Which linked module provides insight into the underlying risk factors?","options":[{"id":"a","text":"fcp1-dyspepsia-reflux"},{"id":"b","text":"add-esophageal-varices"},{"id":"c","text":"fcp1-splenomegaly-approach"},{"id":"d","text":"add-renal-tubular-acidosis-type-2-proximal-rta"}],"answerId":"a","explanation":"The dyspepsia and reflux module covers risk factors like NSAID use for peptic ulcer disease.","kind":"integration","linkedModuleIds":["fcp1-dyspepsia-reflux"],"origin":"ai"},{"id":"fcp1-gi-bleed-upper~ai-6","moduleId":"fcp1-gi-bleed-upper","stem":"A 45-year-old female with known esophageal varices presents with massive haematemesis. Which linked module should be consulted for detailed management strategies?","options":[{"id":"a","text":"fcp1-gi-bleed-management"},{"id":"b","text":"fcp1-gi-bleed-lower"},{"id":"c","text":"add-renal-tubular-acidosis-type-2-proximal-rta"},{"id":"d","text":"fcp1-splenomegaly-approach"}],"answerId":"a","explanation":"The GI bleed management module provides detailed strategies for managing upper GI bleeds.","kind":"integration","linkedModuleIds":["fcp1-gi-bleed-management"],"origin":"ai"}],"fcp1-jaundice-bilirubin-metabolism":[{"id":"fcp1-jaundice-bilirubin-metabolism~ai-0","moduleId":"fcp1-jaundice-bilirubin-metabolism","stem":"What is the primary source of bilirubin in the body?","options":[{"id":"a","text":"Senescent red blood cells"},{"id":"b","text":"Dietary intake"},{"id":"c","text":"Hepatic synthesis"},{"id":"d","text":"Intestinal bacteria"}],"answerId":"a","explanation":"Bilirubin is primarily derived from the breakdown of hemoglobin in senescent red blood cells.","kind":"recall","origin":"ai"},{"id":"fcp1-jaundice-bilirubin-metabolism~ai-1","moduleId":"fcp1-jaundice-bilirubin-metabolism","stem":"A patient presents with scleral icterus but no skin jaundice. What does this suggest about the bilirubin level?","options":[{"id":"a","text":"Bilirubin is below 35 micromol/L"},{"id":"b","text":"Bilirubin is between 35-50 micromol/L"},{"id":"c","text":"Bilirubin is above 50 micromol/L"},{"id":"d","text":"Bilirubin is not elevated"}],"answerId":"b","explanation":"Scleral icterus appears before skin jaundice, indicating bilirubin levels between 35-50 micromol/L.","kind":"recall","origin":"ai"},{"id":"fcp1-jaundice-bilirubin-metabolism~ai-2","moduleId":"fcp1-jaundice-bilirubin-metabolism","stem":"Which condition is characterized by isolated unconjugated hyperbilirubinemia with normal liver function tests?","options":[{"id":"a","text":"Gilbert syndrome"},{"id":"b","text":"Crigler-Najjar syndrome"},{"id":"c","text":"Dubin-Johnson syndrome"},{"id":"d","text":"Rotor syndrome"}],"answerId":"a","explanation":"Gilbert syndrome presents with isolated unconjugated hyperbilirubinemia and normal liver function tests.","kind":"recall","origin":"ai"},{"id":"fcp1-jaundice-bilirubin-metabolism~ai-3","moduleId":"fcp1-jaundice-bilirubin-metabolism","stem":"A patient with dark urine and pale stools is likely experiencing which type of hyperbilirubinemia?","options":[{"id":"a","text":"Unconjugated hyperbilirubinemia"},{"id":"b","text":"Conjugated hyperbilirubinemia"},{"id":"c","text":"Mixed hyperbilirubinemia"},{"id":"d","text":"No hyperbilirubinemia"}],"answerId":"b","explanation":"Conjugated hyperbilirubinemia allows bilirubin to spill into urine and obstructed bile flow causes pale stools.","kind":"mechanism","origin":"ai"},{"id":"fcp1-jaundice-bilirubin-metabolism~ai-4","moduleId":"fcp1-jaundice-bilirubin-metabolism","stem":"A patient with jaundice has normal liver function tests and no evidence of hemolysis. What is the most appropriate management?","options":[{"id":"a","text":"Liver biopsy"},{"id":"b","text":"Reassurance"},{"id":"c","text":"Antiviral therapy"},{"id":"d","text":"Cholestyramine"}],"answerId":"b","explanation":"Isolated unconjugated hyperbilirubinemia with normal liver tests suggests Gilbert syndrome, which requires reassurance only.","kind":"trap","origin":"ai"},{"id":"fcp1-jaundice-bilirubin-metabolism~ai-5","moduleId":"fcp1-jaundice-bilirubin-metabolism","stem":"Which of the following is a common trigger for jaundice in patients with Gilbert syndrome?","options":[{"id":"a","text":"Fasting"},{"id":"b","text":"High-fat diet"},{"id":"c","text":"Alcohol consumption"},{"id":"d","text":"Viral hepatitis"}],"answerId":"a","explanation":"Fasting can trigger jaundice in patients with Gilbert syndrome due to reduced hepatic uptake of bilirubin.","kind":"recall","origin":"ai"},{"id":"fcp1-jaundice-bilirubin-metabolism~ai-6","moduleId":"fcp1-jaundice-bilirubin-metabolism","stem":"A patient with jaundice and elevated conjugated bilirubin is found to have an elevated alkaline phosphatase. Which linked module would provide further insights into this condition?","options":[{"id":"a","text":"cholestatic-lab-pattern"},{"id":"b","text":"asd"},{"id":"c","text":"bilirubin-metabolism-jaundice"},{"id":"d","text":"fcp1-anemia-classification"}],"answerId":"a","explanation":"The 'cholestatic-lab-pattern' module covers laboratory findings associated with obstructive jaundice.","kind":"integration","linkedModuleIds":["cholestatic-lab-pattern"],"origin":"ai"},{"id":"fcp1-jaundice-bilirubin-metabolism~ai-7","moduleId":"fcp1-jaundice-bilirubin-metabolism","stem":"In a patient with jaundice and anemia, which module would help classify the type of anemia present?","options":[{"id":"a","text":"fcp1-anemia-classification"},{"id":"b","text":"fcp1-jaundice-approach"},{"id":"c","text":"asd"},{"id":"d","text":"fcp1-jaundice-cholestasis"}],"answerId":"a","explanation":"The 'fcp1-anemia-classification' module helps classify anemia based on MCV and reticulocyte response.","kind":"integration","linkedModuleIds":["fcp1-anemia-classification"],"origin":"ai"}],"fcp1-gi-bleed-management":[{"id":"fcp1-gi-bleed-management~ai-0","moduleId":"fcp1-gi-bleed-management","stem":"A 60-year-old man presents with hematemesis and is hypotensive. What is the first step in management?","options":[{"id":"a","text":"Secure airway and initiate resuscitation"},{"id":"b","text":"Perform urgent endoscopy"},{"id":"c","text":"Administer IV PPI"},{"id":"d","text":"Transfuse red cells immediately"}],"answerId":"a","explanation":"Resuscitation, including securing the airway and managing circulation, is prioritized over diagnostic procedures in GI bleeding.","kind":"recall","origin":"ai"},{"id":"fcp1-gi-bleed-management~ai-1","moduleId":"fcp1-gi-bleed-management","stem":"Which of the following is a correct transfusion strategy for a patient with a GI bleed and a history of ischemic heart disease?","options":[{"id":"a","text":"Transfuse when Hb is below 70 g/L"},{"id":"b","text":"Transfuse when Hb is below 80 g/L"},{"id":"c","text":"Transfuse to maintain Hb above 90 g/L"},{"id":"d","text":"Transfuse to maintain Hb above 100 g/L"}],"answerId":"b","explanation":"For patients with active cardiac disease, a more conservative threshold of 80 g/L is used.","kind":"trap","origin":"ai"},{"id":"fcp1-gi-bleed-management~ai-2","moduleId":"fcp1-gi-bleed-management","stem":"A patient with suspected variceal bleeding is being managed. Which medication should be administered early?","options":[{"id":"a","text":"IV PPI"},{"id":"b","text":"Terlipressin"},{"id":"c","text":"Oral antibiotics"},{"id":"d","text":"IV fluids only"}],"answerId":"b","explanation":"Terlipressin is used early in suspected variceal bleeding to reduce portal pressure.","kind":"mechanism","origin":"ai"},{"id":"fcp1-gi-bleed-management~ai-3","moduleId":"fcp1-gi-bleed-management","stem":"A 45-year-old woman presents with melena and is found to have stigmata of chronic liver disease. What is the most likely source of bleeding?","options":[{"id":"a","text":"Peptic ulcer"},{"id":"b","text":"Diverticular bleed"},{"id":"c","text":"Variceal bleed"},{"id":"d","text":"Angiodysplasia"}],"answerId":"c","explanation":"Stigmata of chronic liver disease suggest variceal bleeding.","kind":"clinical","origin":"ai"},{"id":"fcp1-gi-bleed-management~ai-4","moduleId":"fcp1-gi-bleed-management","stem":"What is the recommended timing for endoscopy in a patient with a major non-variceal upper GI bleed?","options":[{"id":"a","text":"Within 6 hours"},{"id":"b","text":"Within 12 hours"},{"id":"c","text":"Within 24 hours"},{"id":"d","text":"Within 48 hours"}],"answerId":"c","explanation":"Endoscopy should be performed within 24 hours for major non-variceal bleeds.","kind":"recall","origin":"ai"},{"id":"fcp1-gi-bleed-management~ai-5","moduleId":"fcp1-gi-bleed-management","stem":"A patient with a GI bleed is in shock. Which module provides additional guidance on initial management?","options":[{"id":"a","text":"Epidural & Subdural Hematoma"},{"id":"b","text":"Recognition & Initial Management of Shock"},{"id":"c","text":"SAH, Aneurysm, AVM & Intraparenchymal Bleed"},{"id":"d","text":"Lower GI Bleeding"}],"answerId":"b","explanation":"The linked module 'Recognition & Initial Management of Shock' provides guidance on managing shock, which is crucial in GI bleed resuscitation.","kind":"integration","linkedModuleIds":["fcp1-shock-management"],"origin":"ai"},{"id":"fcp1-gi-bleed-management~ai-6","moduleId":"fcp1-gi-bleed-management","stem":"A patient presents with hematochezia and is hemodynamically stable. Which score helps determine the need for admission?","options":[{"id":"a","text":"Child-Pugh score"},{"id":"b","text":"Glasgow-Blatchford score"},{"id":"c","text":"MELD score"},{"id":"d","text":"Rockall score"}],"answerId":"b","explanation":"The Glasgow-Blatchford score is used to risk-stratify patients with GI bleeding and determine the need for admission.","kind":"integration","linkedModuleIds":["fcp1-gi-bleed-upper"],"origin":"ai"}],"fcp1-jaundice-approach":[{"id":"fcp1-jaundice-approach~ai-0","moduleId":"fcp1-jaundice-approach","stem":"A 45-year-old man presents with jaundice, dark urine, and pale stools. His liver function tests show elevated ALP and GGT with normal ALT and AST. What is the most likely underlying cause?","options":[{"id":"a","text":"Gallstones"},{"id":"b","text":"Viral hepatitis"},{"id":"c","text":"Alcoholic liver disease"},{"id":"d","text":"Hemolytic anemia"}],"answerId":"a","explanation":"The pattern of elevated ALP and GGT with normal transaminases suggests a cholestatic process, such as gallstones.","kind":"clinical","origin":"ai"},{"id":"fcp1-jaundice-approach~ai-1","moduleId":"fcp1-jaundice-approach","stem":"Which of the following is the most appropriate initial test to differentiate between prehepatic and hepatic causes of jaundice?","options":[{"id":"a","text":"Abdominal ultrasound"},{"id":"b","text":"Serum bilirubin split"},{"id":"c","text":"Liver biopsy"},{"id":"d","text":"CT scan of the abdomen"}],"answerId":"b","explanation":"A serum bilirubin split helps differentiate between unconjugated (prehepatic) and conjugated (hepatic) hyperbilirubinemia.","kind":"recall","origin":"ai"},{"id":"fcp1-jaundice-approach~ai-2","moduleId":"fcp1-jaundice-approach","stem":"A patient presents with fever, right upper quadrant pain, and jaundice. What is the most appropriate next step in management?","options":[{"id":"a","text":"Start antibiotics and arrange for biliary drainage"},{"id":"b","text":"Administer antipyretics and observe"},{"id":"c","text":"Schedule an elective cholecystectomy"},{"id":"d","text":"Perform a liver biopsy"}],"answerId":"a","explanation":"This presentation is consistent with ascending cholangitis, which requires urgent antibiotics and biliary drainage.","kind":"trap","origin":"ai"},{"id":"fcp1-jaundice-approach~ai-3","moduleId":"fcp1-jaundice-approach","stem":"A 60-year-old woman with painless jaundice and weight loss is found to have a palpable, non-tender gallbladder. What is the most likely diagnosis?","options":[{"id":"a","text":"Pancreatic carcinoma"},{"id":"b","text":"Acute cholecystitis"},{"id":"c","text":"Primary sclerosing cholangitis"},{"id":"d","text":"Viral hepatitis"}],"answerId":"a","explanation":"Painless jaundice with a palpable gallbladder (Courvoisier sign) suggests malignant biliary obstruction, commonly due to pancreatic carcinoma.","kind":"clinical","linkedModuleIds":["pancreatic-carcinoma"],"origin":"ai"},{"id":"fcp1-jaundice-approach~ai-4","moduleId":"fcp1-jaundice-approach","stem":"A patient with jaundice has an elevated unconjugated bilirubin level. Which condition is most likely responsible?","options":[{"id":"a","text":"Gilbert's syndrome"},{"id":"b","text":"Cholangiocarcinoma"},{"id":"c","text":"Primary biliary cholangitis"},{"id":"d","text":"Hepatitis B infection"}],"answerId":"a","explanation":"Elevated unconjugated bilirubin is characteristic of Gilbert's syndrome, a benign hereditary condition.","kind":"mechanism","origin":"ai"},{"id":"fcp1-jaundice-approach~ai-5","moduleId":"fcp1-jaundice-approach","stem":"A 50-year-old man presents with jaundice and pruritus. His liver function tests show elevated ALP and GGT. Which skin sign might you expect to find?","options":[{"id":"a","text":"Spider angiomas"},{"id":"b","text":"Xanthelasma"},{"id":"c","text":"Palmar erythema"},{"id":"d","text":"Scratch marks"}],"answerId":"d","explanation":"Scratch marks are common in cholestatic jaundice due to pruritus from retained bile salts.","kind":"integration","linkedModuleIds":["fcp1-skin-signs-systemic-disease"],"origin":"ai"},{"id":"fcp1-jaundice-approach~ai-6","moduleId":"fcp1-jaundice-approach","stem":"Which of the following liver function test patterns is most indicative of hepatocellular injury?","options":[{"id":"a","text":"Elevated ALT and AST with normal ALP"},{"id":"b","text":"Elevated ALP and GGT with normal ALT"},{"id":"c","text":"Normal ALT and AST with elevated ALP"},{"id":"d","text":"Elevated bilirubin with normal ALT and ALP"}],"answerId":"a","explanation":"Hepatocellular injury is characterized by elevated ALT and AST levels, often with normal ALP.","kind":"recall","origin":"ai"}],"fcp1-abdominal-mass-differential":[{"id":"fcp1-abdominal-mass-differential~ai-0","moduleId":"fcp1-abdominal-mass-differential","stem":"A patient presents with a mass in the right upper quadrant that moves with respiration and is dull to percussion. Which organ is most likely involved?","options":[{"id":"a","text":"Liver"},{"id":"b","text":"Kidney"},{"id":"c","text":"Spleen"},{"id":"d","text":"Gallbladder"}],"answerId":"a","explanation":"A mass in the right upper quadrant that moves with respiration and is dull to percussion is indicative of hepatomegaly.","kind":"recall","origin":"ai"},{"id":"fcp1-abdominal-mass-differential~ai-1","moduleId":"fcp1-abdominal-mass-differential","stem":"During an abdominal examination, you find a ballotable mass in the left flank that is resonant anteriorly. What is the most likely diagnosis?","options":[{"id":"a","text":"Splenomegaly"},{"id":"b","text":"Renal mass"},{"id":"c","text":"Pancreatic cyst"},{"id":"d","text":"Ovarian cyst"}],"answerId":"b","explanation":"A ballotable mass in the flank that is resonant anteriorly suggests a renal mass, as the kidney is ballotable and has bowel resonance in front.","kind":"mechanism","origin":"ai"},{"id":"fcp1-abdominal-mass-differential~ai-2","moduleId":"fcp1-abdominal-mass-differential","stem":"A 65-year-old male presents with a hard, irregular mass in the epigastrium and significant weight loss. What is the most likely diagnosis?","options":[{"id":"a","text":"Benign gastric polyp"},{"id":"b","text":"Pancreatic cancer"},{"id":"c","text":"Hepatic hemangioma"},{"id":"d","text":"Gastric ulcer"}],"answerId":"b","explanation":"A hard, irregular mass with weight loss in the epigastrium is suggestive of pancreatic cancer.","kind":"clinical","origin":"ai"},{"id":"fcp1-abdominal-mass-differential~ai-3","moduleId":"fcp1-abdominal-mass-differential","stem":"A patient with jaundice has a palpable gallbladder. Which condition should be considered?","options":[{"id":"a","text":"Cholecystitis"},{"id":"b","text":"Gallbladder cancer"},{"id":"c","text":"Pancreatitis"},{"id":"d","text":"Choledocholithiasis"}],"answerId":"b","explanation":"A palpable gallbladder in the presence of jaundice suggests gallbladder cancer, as per Courvoisier's sign.","kind":"integration","linkedModuleIds":["fcp1-jaundice-cholestasis"],"origin":"ai"},{"id":"fcp1-abdominal-mass-differential~ai-4","moduleId":"fcp1-abdominal-mass-differential","stem":"A patient presents with a left upper quadrant mass that is dull to percussion and moves towards the right iliac fossa. What is the most likely diagnosis?","options":[{"id":"a","text":"Renal cell carcinoma"},{"id":"b","text":"Splenomegaly"},{"id":"c","text":"Pancreatic pseudocyst"},{"id":"d","text":"Ovarian cyst"}],"answerId":"b","explanation":"A left upper quadrant mass that is dull to percussion and moves towards the right iliac fossa is indicative of splenomegaly.","kind":"trap","origin":"ai"},{"id":"fcp1-abdominal-mass-differential~ai-5","moduleId":"fcp1-abdominal-mass-differential","stem":"A 40-year-old woman presents with a left iliac fossa mass and a history of constipation. What is the next best step in management?","options":[{"id":"a","text":"Immediate colonoscopy"},{"id":"b","text":"Abdominal ultrasound"},{"id":"c","text":"Digital rectal examination after bowel clearance"},{"id":"d","text":"CT scan of the abdomen"}],"answerId":"c","explanation":"A left iliac fossa mass in the context of constipation may be faeces; a digital rectal examination after bowel clearance can confirm this.","kind":"integration","linkedModuleIds":["fcp1-constipation-bowel-habit"],"origin":"ai"}],"fcp1-abdominal-mass-approach":[{"id":"fcp1-abdominal-mass-approach~ai-0","moduleId":"fcp1-abdominal-mass-approach","stem":"A 65-year-old male presents with a pulsatile, expansile central abdominal mass. What is the most likely diagnosis?","options":[{"id":"a","text":"Abdominal aortic aneurysm"},{"id":"b","text":"Hepatomegaly"},{"id":"c","text":"Renal cell carcinoma"},{"id":"d","text":"Pancreatic pseudocyst"}],"answerId":"a","explanation":"A pulsatile, expansile central mass is characteristic of an abdominal aortic aneurysm.","kind":"recall","origin":"ai"},{"id":"fcp1-abdominal-mass-approach~ai-1","moduleId":"fcp1-abdominal-mass-approach","stem":"During an abdominal examination, a mass is found that moves down on inspiration. Which organ is most likely involved?","options":[{"id":"a","text":"Liver"},{"id":"b","text":"Pancreas"},{"id":"c","text":"Small intestine"},{"id":"d","text":"Bladder"}],"answerId":"a","explanation":"A mass that moves down on inspiration suggests involvement of the liver, spleen, or kidney, which descend with the diaphragm.","kind":"mechanism","origin":"ai"},{"id":"fcp1-abdominal-mass-approach~ai-2","moduleId":"fcp1-abdominal-mass-approach","stem":"A 45-year-old woman presents with a suprapubic mass that you cannot get below. It is dull to percussion. What is the most likely origin of this mass?","options":[{"id":"a","text":"Bladder"},{"id":"b","text":"Liver"},{"id":"c","text":"Spleen"},{"id":"d","text":"Pancreas"}],"answerId":"a","explanation":"A suprapubic mass that you cannot get below and is dull to percussion suggests a pelvic organ such as the bladder.","kind":"clinical","origin":"ai"},{"id":"fcp1-abdominal-mass-approach~ai-3","moduleId":"fcp1-abdominal-mass-approach","stem":"Which of the following is the most appropriate initial investigation for characterizing an abdominal mass?","options":[{"id":"a","text":"Ultrasound"},{"id":"b","text":"MRI"},{"id":"c","text":"X-ray"},{"id":"d","text":"Endoscopy"}],"answerId":"a","explanation":"Ultrasound is the first-line investigation for characterizing an abdominal mass.","kind":"recall","origin":"ai"},{"id":"fcp1-abdominal-mass-approach~ai-4","moduleId":"fcp1-abdominal-mass-approach","stem":"A patient has a ballotable flank mass with a resonant band anteriorly. What is the most likely origin of this mass?","options":[{"id":"a","text":"Kidney"},{"id":"b","text":"Liver"},{"id":"c","text":"Spleen"},{"id":"d","text":"Pancreas"}],"answerId":"a","explanation":"A ballotable flank mass with a resonant band anteriorly suggests a retroperitoneal renal origin.","kind":"mechanism","origin":"ai"},{"id":"fcp1-abdominal-mass-approach~ai-5","moduleId":"fcp1-abdominal-mass-approach","stem":"In the context of an abdominal mass, which finding would most strongly suggest malignancy?","options":[{"id":"a","text":"Hard, irregular, fixed mass with weight loss"},{"id":"b","text":"Soft, mobile mass with no systemic symptoms"},{"id":"c","text":"Tender, fluctuant mass with fever"},{"id":"d","text":"Smooth, firm mass with normal appetite"}],"answerId":"a","explanation":"A hard, irregular, fixed mass with weight loss suggests malignancy.","kind":"trap","origin":"ai"},{"id":"fcp1-abdominal-mass-approach~ai-6","moduleId":"fcp1-abdominal-mass-approach","stem":"A 50-year-old female presents with a pelvic mass that is dull to percussion and you cannot get below it. Which module should be referenced for further evaluation?","options":[{"id":"a","text":"Approach to a Pelvic Mass"},{"id":"b","text":"Abdominal Mass: Differential by Region"},{"id":"c","text":"Approach to a Headache"},{"id":"d","text":"Approach to Chest Pain"}],"answerId":"a","explanation":"A pelvic mass that is dull to percussion and cannot be palpated below suggests referencing the pelvic mass module.","kind":"integration","linkedModuleIds":["fcp1-pelvic-mass-approach"],"origin":"ai"},{"id":"fcp1-abdominal-mass-approach~ai-7","moduleId":"fcp1-abdominal-mass-approach","stem":"A patient presents with a central abdominal mass. Which module should be consulted to differentiate the mass by region?","options":[{"id":"a","text":"Abdominal Mass: Differential by Region"},{"id":"b","text":"Approach to a Pelvic Mass"},{"id":"c","text":"Approach to a Headache"},{"id":"d","text":"Approach to Chest Pain"}],"answerId":"a","explanation":"The module 'Abdominal Mass: Differential by Region' should be consulted to differentiate the mass by region.","kind":"integration","linkedModuleIds":["fcp1-abdominal-mass-differential"],"origin":"ai"}],"fcp1-jaundice-cholestasis":[{"id":"fcp1-jaundice-cholestasis~ai-0","moduleId":"fcp1-jaundice-cholestasis","stem":"A 55-year-old man presents with painless jaundice and a palpable, non-tender gallbladder. What is the most likely underlying cause?","options":[{"id":"a","text":"Pancreatic head cancer"},{"id":"b","text":"Gallstones"},{"id":"c","text":"Primary sclerosing cholangitis"},{"id":"d","text":"Hepatitis"}],"answerId":"a","explanation":"Painless jaundice with a palpable gallbladder suggests malignant distal obstruction, classically pancreatic head cancer.","kind":"clinical","origin":"ai"},{"id":"fcp1-jaundice-cholestasis~ai-1","moduleId":"fcp1-jaundice-cholestasis","stem":"Which laboratory pattern is most indicative of cholestatic jaundice?","options":[{"id":"a","text":"Elevated AST and ALT"},{"id":"b","text":"Elevated ALP and GGT"},{"id":"c","text":"Elevated unconjugated bilirubin"},{"id":"d","text":"Elevated amylase and lipase"}],"answerId":"b","explanation":"Cholestatic jaundice is characterized by elevated ALP and GGT due to bile duct obstruction.","kind":"recall","origin":"ai"},{"id":"fcp1-jaundice-cholestasis~ai-2","moduleId":"fcp1-jaundice-cholestasis","stem":"A patient with fever, right upper quadrant pain, and jaundice is diagnosed with ascending cholangitis. Which additional symptom would complete Reynolds pentad?","options":[{"id":"a","text":"Pruritus"},{"id":"b","text":"Hypotension"},{"id":"c","text":"Nausea"},{"id":"d","text":"Diarrhea"}],"answerId":"b","explanation":"Reynolds pentad includes fever, RUQ pain, jaundice, hypotension, and confusion.","kind":"recall","origin":"ai"},{"id":"fcp1-jaundice-cholestasis~ai-3","moduleId":"fcp1-jaundice-cholestasis","stem":"In a patient with suspected cholestasis, which imaging modality is typically performed first?","options":[{"id":"a","text":"CT scan"},{"id":"b","text":"Ultrasound"},{"id":"c","text":"ERCP"},{"id":"d","text":"MRI"}],"answerId":"b","explanation":"Ultrasound is the first imaging modality used to assess for dilated bile ducts or stones in cholestasis.","kind":"mechanism","origin":"ai"},{"id":"fcp1-jaundice-cholestasis~ai-4","moduleId":"fcp1-jaundice-cholestasis","stem":"A 60-year-old woman presents with pruritus and elevated ALP. She has a history of autoimmune disorders. Which condition is most likely?","options":[{"id":"a","text":"Primary biliary cholangitis"},{"id":"b","text":"Cholangiocarcinoma"},{"id":"c","text":"Pancreatic head cancer"},{"id":"d","text":"Common bile duct stones"}],"answerId":"a","explanation":"Primary biliary cholangitis is associated with pruritus, elevated ALP, and autoimmune disorders.","kind":"clinical","origin":"ai"},{"id":"fcp1-jaundice-cholestasis~ai-5","moduleId":"fcp1-jaundice-cholestasis","stem":"A patient with obstructive jaundice and a palpable abdominal mass is most likely to have which condition?","options":[{"id":"a","text":"Pancreatic head cancer"},{"id":"b","text":"Hepatocellular carcinoma"},{"id":"c","text":"Cholecystitis"},{"id":"d","text":"Hepatitis"}],"answerId":"a","explanation":"A palpable abdominal mass with obstructive jaundice suggests pancreatic head cancer.","kind":"integration","linkedModuleIds":["fcp1-abdominal-mass-differential"],"origin":"ai"},{"id":"fcp1-jaundice-cholestasis~ai-6","moduleId":"fcp1-jaundice-cholestasis","stem":"A 45-year-old man presents with right upper quadrant pain and jaundice. Ultrasound shows dilated bile ducts but no stones. Which test is most appropriate next?","options":[{"id":"a","text":"ERCP"},{"id":"b","text":"Liver biopsy"},{"id":"c","text":"CT scan"},{"id":"d","text":"HIDA scan"}],"answerId":"a","explanation":"ERCP is used to treat and further evaluate bile duct obstruction when stones are not visible on ultrasound.","kind":"trap","origin":"ai"},{"id":"fcp1-jaundice-cholestasis~ai-7","moduleId":"fcp1-jaundice-cholestasis","stem":"Which condition is most likely to present with pruritus, dark urine, and pale stools?","options":[{"id":"a","text":"Cholestatic jaundice"},{"id":"b","text":"Hemolytic anemia"},{"id":"c","text":"Gilbert's syndrome"},{"id":"d","text":"Acute viral hepatitis"}],"answerId":"a","explanation":"Cholestatic jaundice presents with pruritus, dark urine, and pale stools due to conjugated hyperbilirubinemia.","kind":"integration","linkedModuleIds":["fcp1-jaundice-bilirubin-metabolism"],"origin":"ai"}],"fcp1-pediatric-abdominal-pain":[{"id":"fcp1-pediatric-abdominal-pain~ai-0","moduleId":"fcp1-pediatric-abdominal-pain","stem":"A 4-year-old boy presents with episodic abdominal pain, drawing up of the legs, and vomiting. An abdominal ultrasound reveals a target sign. What is the most likely diagnosis?","options":[{"id":"a","text":"Intussusception"},{"id":"b","text":"Appendicitis"},{"id":"c","text":"Functional abdominal pain"},{"id":"d","text":"Incarcerated hernia"}],"answerId":"a","explanation":"The target sign on ultrasound is characteristic of intussusception.","kind":"recall","origin":"ai"},{"id":"fcp1-pediatric-abdominal-pain~ai-1","moduleId":"fcp1-pediatric-abdominal-pain","stem":"A 10-year-old girl presents with periumbilical pain that migrates to the right iliac fossa, anorexia, and vomiting. What is the most likely diagnosis?","options":[{"id":"a","text":"Intussusception"},{"id":"b","text":"Appendicitis"},{"id":"c","text":"Functional abdominal pain"},{"id":"d","text":"Testicular torsion"}],"answerId":"b","explanation":"The classic presentation of appendicitis includes periumbilical pain migrating to the right iliac fossa.","kind":"recall","origin":"ai"},{"id":"fcp1-pediatric-abdominal-pain~ai-2","moduleId":"fcp1-pediatric-abdominal-pain","stem":"Which of the following findings would be most concerning for a surgical cause of abdominal pain in a child?","options":[{"id":"a","text":"Soft abdomen, normal growth"},{"id":"b","text":"Periumbilical pain without fever"},{"id":"c","text":"Tender groin swelling"},{"id":"d","text":"Diffuse abdominal pain with normal labs"}],"answerId":"c","explanation":"A tender groin swelling could indicate an incarcerated hernia or testicular torsion, both surgical emergencies.","kind":"trap","origin":"ai"},{"id":"fcp1-pediatric-abdominal-pain~ai-3","moduleId":"fcp1-pediatric-abdominal-pain","stem":"A 7-year-old boy presents with abdominal pain and fever. Examination reveals right iliac fossa tenderness with guarding. What is the most likely diagnosis?","options":[{"id":"a","text":"Functional abdominal pain"},{"id":"b","text":"Appendicitis"},{"id":"c","text":"Intussusception"},{"id":"d","text":"Pneumonia"}],"answerId":"b","explanation":"Right iliac fossa tenderness with guarding is indicative of appendicitis.","kind":"recall","origin":"ai"},{"id":"fcp1-pediatric-abdominal-pain~ai-4","moduleId":"fcp1-pediatric-abdominal-pain","stem":"A 3-year-old girl presents with colicky abdominal pain and redcurrant-jelly stools. What is the most appropriate next step in management?","options":[{"id":"a","text":"CT scan of the abdomen"},{"id":"b","text":"Air enema reduction"},{"id":"c","text":"Intravenous antibiotics"},{"id":"d","text":"Surgical consultation"}],"answerId":"b","explanation":"Air enema reduction is both diagnostic and therapeutic for intussusception.","kind":"clinical","origin":"ai"},{"id":"fcp1-pediatric-abdominal-pain~ai-5","moduleId":"fcp1-pediatric-abdominal-pain","stem":"A 5-year-old boy presents with recurrent abdominal pain, normal growth, and no red flags. What is the most likely diagnosis?","options":[{"id":"a","text":"Appendicitis"},{"id":"b","text":"Functional abdominal pain"},{"id":"c","text":"Intussusception"},{"id":"d","text":"Incarcerated hernia"}],"answerId":"b","explanation":"Recurrent abdominal pain with normal growth and no red flags is characteristic of functional abdominal pain.","kind":"recall","origin":"ai"},{"id":"fcp1-pediatric-abdominal-pain~ai-6","moduleId":"fcp1-pediatric-abdominal-pain","stem":"A 6-year-old presents with abdominal pain and vomiting. The pain is severe and associated with bilious vomiting. Which condition must be ruled out urgently?","options":[{"id":"a","text":"Functional abdominal pain"},{"id":"b","text":"Malrotation with volvulus"},{"id":"c","text":"Appendicitis"},{"id":"d","text":"Intussusception"}],"answerId":"b","explanation":"Bilious vomiting in an infant or young child is a red flag for malrotation with volvulus, a surgical emergency.","kind":"trap","origin":"ai"},{"id":"fcp1-pediatric-abdominal-pain~ai-7","moduleId":"fcp1-pediatric-abdominal-pain","stem":"A 9-year-old boy presents with abdominal pain and a sore throat. Examination reveals pharyngeal erythema and exudates. Which condition should be considered as a cause of his abdominal pain?","options":[{"id":"a","text":"Appendicitis"},{"id":"b","text":"Streptococcal pharyngitis"},{"id":"c","text":"Intussusception"},{"id":"d","text":"Functional abdominal pain"}],"answerId":"b","explanation":"Streptococcal pharyngitis can present with abdominal pain due to associated mesenteric adenitis.","kind":"integration","linkedModuleIds":["fcp1-pediatric-vomiting-diarrhea"],"origin":"ai"},{"id":"fcp1-pediatric-abdominal-pain~ai-8","moduleId":"fcp1-pediatric-abdominal-pain","stem":"A 2-year-old presents with abdominal distension and bilious vomiting. What is the most likely diagnosis?","options":[{"id":"a","text":"Intussusception"},{"id":"b","text":"Appendicitis"},{"id":"c","text":"Malrotation with volvulus"},{"id":"d","text":"Functional abdominal pain"}],"answerId":"c","explanation":"Bilious vomiting and abdominal distension in an infant suggest malrotation with volvulus, a surgical emergency.","kind":"integration","linkedModuleIds":["fcp1-abdominal-pain-acute-abdomen"],"origin":"ai"}],"fcp1-anemia-classification":[{"id":"fcp1-anemia-classification~ai-0","moduleId":"fcp1-anemia-classification","stem":"A 45-year-old woman presents with fatigue and pallor. Her lab results show MCV of 72 fL and low serum ferritin. What is the most likely type of anemia?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Thalassemia"},{"id":"c","text":"Anemia of chronic disease"},{"id":"d","text":"Sideroblastic anemia"}],"answerId":"a","explanation":"Low MCV and low ferritin are indicative of iron deficiency anemia.","kind":"recall","origin":"ai"},{"id":"fcp1-anemia-classification~ai-1","moduleId":"fcp1-anemia-classification","stem":"A patient with normocytic anemia has a low reticulocyte count. Which condition is most likely?","options":[{"id":"a","text":"Acute blood loss"},{"id":"b","text":"Chronic kidney disease"},{"id":"c","text":"Hemolytic anemia"},{"id":"d","text":"Vitamin B12 deficiency"}],"answerId":"b","explanation":"Normocytic anemia with low reticulocyte count suggests hypoproliferative anemia, such as chronic kidney disease.","kind":"clinical","origin":"ai"},{"id":"fcp1-anemia-classification~ai-2","moduleId":"fcp1-anemia-classification","stem":"A 30-year-old male presents with jaundice and splenomegaly. Lab results show high reticulocyte count and normocytic anemia. What is the most likely diagnosis?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Hemolytic anemia"},{"id":"c","text":"Aplastic anemia"},{"id":"d","text":"Anemia of chronic disease"}],"answerId":"b","explanation":"The combination of jaundice, splenomegaly, and high reticulocyte count suggests hemolytic anemia.","kind":"clinical","origin":"ai"},{"id":"fcp1-anemia-classification~ai-3","moduleId":"fcp1-anemia-classification","stem":"A patient presents with macrocytic anemia and hypersegmented neutrophils. Which deficiency is most likely?","options":[{"id":"a","text":"Iron deficiency"},{"id":"b","text":"Vitamin B12 deficiency"},{"id":"c","text":"Thalassemia"},{"id":"d","text":"Chronic disease"}],"answerId":"b","explanation":"Macrocytic anemia with hypersegmented neutrophils is indicative of megaloblastic anemia, commonly due to Vitamin B12 deficiency.","kind":"recall","origin":"ai"},{"id":"fcp1-anemia-classification~ai-4","moduleId":"fcp1-anemia-classification","stem":"A 55-year-old male with fatigue has a normal MCV but high RDW. What should be the next step in evaluation?","options":[{"id":"a","text":"Check serum ferritin"},{"id":"b","text":"Perform bone marrow biopsy"},{"id":"c","text":"Start iron supplementation"},{"id":"d","text":"Check serum folate"}],"answerId":"a","explanation":"High RDW with normal MCV suggests early iron deficiency; checking serum ferritin is appropriate.","kind":"trap","origin":"ai"},{"id":"fcp1-anemia-classification~ai-5","moduleId":"fcp1-anemia-classification","stem":"A 60-year-old female with hypothyroidism presents with fatigue. Her lab results show macrocytic anemia. Which condition should be considered?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Vitamin B12 deficiency"},{"id":"c","text":"Thalassemia"},{"id":"d","text":"Chronic disease"}],"answerId":"b","explanation":"Hypothyroidism can cause macrocytic anemia, often associated with Vitamin B12 deficiency.","kind":"integration","linkedModuleIds":["fcp1-hypothyroidism"],"origin":"ai"},{"id":"fcp1-anemia-classification~ai-6","moduleId":"fcp1-anemia-classification","stem":"A 25-year-old female presents with fatigue. Her lab results show microcytic anemia with normal iron studies. What is the most likely diagnosis?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Thalassemia"},{"id":"c","text":"Anemia of chronic disease"},{"id":"d","text":"Sideroblastic anemia"}],"answerId":"b","explanation":"Microcytic anemia with normal iron studies suggests thalassemia.","kind":"integration","linkedModuleIds":["fcp1-anemia-microcytic"],"origin":"ai"}],"fcp1-anemia-approach-workup":[{"id":"fcp1-anemia-approach-workup~ai-0","moduleId":"fcp1-anemia-approach-workup","stem":"A 45-year-old woman presents with fatigue and pallor. Her CBC shows microcytic anemia. What is the next best step in the workup?","options":[{"id":"a","text":"Order iron studies"},{"id":"b","text":"Perform a peripheral smear"},{"id":"c","text":"Check reticulocyte count"},{"id":"d","text":"Start iron supplementation"}],"answerId":"a","explanation":"Iron studies are indicated to confirm iron deficiency as the cause of microcytic anemia.","kind":"clinical","origin":"ai"},{"id":"fcp1-anemia-approach-workup~ai-1","moduleId":"fcp1-anemia-approach-workup","stem":"Which of the following signs is most indicative of hemolytic anemia?","options":[{"id":"a","text":"Koilonychia"},{"id":"b","text":"Jaundice with splenomegaly"},{"id":"c","text":"Conjunctival pallor"},{"id":"d","text":"Angular cheilitis"}],"answerId":"b","explanation":"Jaundice with splenomegaly suggests increased red cell destruction, characteristic of hemolytic anemia.","kind":"recall","origin":"ai"},{"id":"fcp1-anemia-approach-workup~ai-2","moduleId":"fcp1-anemia-approach-workup","stem":"A patient with anemia presents with weight loss and lymphadenopathy. What should be the immediate concern?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Vitamin B12 deficiency"},{"id":"c","text":"Malignancy"},{"id":"d","text":"Chronic disease anemia"}],"answerId":"c","explanation":"Weight loss and lymphadenopathy are red flags for a potential malignancy.","kind":"trap","origin":"ai"},{"id":"fcp1-anemia-approach-workup~ai-3","moduleId":"fcp1-anemia-approach-workup","stem":"A 30-year-old male presents with fatigue. His CBC shows macrocytic anemia. Which additional symptom would suggest a B12 deficiency?","options":[{"id":"a","text":"Koilonychia"},{"id":"b","text":"Splenomegaly"},{"id":"c","text":"Neuropathy"},{"id":"d","text":"Tachycardia"}],"answerId":"c","explanation":"Neuropathy, along with macrocytic anemia, suggests B12 deficiency.","kind":"integration","linkedModuleIds":["hhl-b12-folate-megaloblastic"],"origin":"ai"},{"id":"fcp1-anemia-approach-workup~ai-4","moduleId":"fcp1-anemia-approach-workup","stem":"What is the primary reason for obtaining a reticulocyte count in the initial workup of anemia?","options":[{"id":"a","text":"To confirm iron deficiency"},{"id":"b","text":"To assess bone marrow response"},{"id":"c","text":"To diagnose hemolysis"},{"id":"d","text":"To evaluate vitamin B12 levels"}],"answerId":"b","explanation":"The reticulocyte count helps assess the bone marrow's response to anemia, guiding further workup.","kind":"mechanism","origin":"ai"},{"id":"fcp1-anemia-approach-workup~ai-5","moduleId":"fcp1-anemia-approach-workup","stem":"In a patient with anemia and splenomegaly, which linked module would help further categorize the splenomegaly?","options":[{"id":"a","text":"hhl-anemia-approach-indices"},{"id":"b","text":"fcp1-splenomegaly-approach"},{"id":"c","text":"fcp1-lymphadenopathy-approach"},{"id":"d","text":"fcp1-syncope-approach"}],"answerId":"b","explanation":"The 'Approach to Splenomegaly' module assists in categorizing the cause of splenomegaly.","kind":"integration","linkedModuleIds":["fcp1-splenomegaly-approach"],"origin":"ai"},{"id":"fcp1-anemia-approach-workup~ai-6","moduleId":"fcp1-anemia-approach-workup","stem":"Which of the following is a red flag in the workup of anemia that necessitates urgent evaluation?","options":[{"id":"a","text":"Conjunctival pallor"},{"id":"b","text":"Tachycardia"},{"id":"c","text":"Pancytopenia"},{"id":"d","text":"Microcytosis"}],"answerId":"c","explanation":"Pancytopenia suggests bone marrow failure and requires urgent evaluation.","kind":"trap","origin":"ai"}],"fcp1-anemia-microcytic":[{"id":"fcp1-anemia-microcytic~ai-0","moduleId":"fcp1-anemia-microcytic","stem":"A 35-year-old woman presents with fatigue and pallor. Her lab results show low hemoglobin, low MCV, low ferritin, and high TIBC. What is the most likely diagnosis?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Thalassemia trait"},{"id":"c","text":"Anemia of chronic disease"},{"id":"d","text":"Sideroblastic anemia"}],"answerId":"a","explanation":"Low ferritin and high TIBC are indicative of iron deficiency anemia.","kind":"recall","origin":"ai"},{"id":"fcp1-anemia-microcytic~ai-1","moduleId":"fcp1-anemia-microcytic","stem":"A patient with microcytic anemia has a normal ferritin level but low transferrin saturation. Which mechanism is most likely responsible for their anemia?","options":[{"id":"a","text":"Iron deficiency"},{"id":"b","text":"Thalassemia trait"},{"id":"c","text":"Anemia of chronic disease"},{"id":"d","text":"Sideroblastic anemia"}],"answerId":"c","explanation":"Anemia of chronic disease is characterized by normal or high ferritin and low transferrin saturation due to hepcidin-mediated iron sequestration.","kind":"mechanism","origin":"ai"},{"id":"fcp1-anemia-microcytic~ai-2","moduleId":"fcp1-anemia-microcytic","stem":"A 28-year-old man with microcytic anemia has a Mentzer index of 12. What is the most likely diagnosis?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Thalassemia trait"},{"id":"c","text":"Anemia of chronic disease"},{"id":"d","text":"Lead poisoning"}],"answerId":"b","explanation":"A Mentzer index less than 13 suggests thalassemia trait.","kind":"clinical","linkedModuleIds":["hhl-anemia-approach-indices"],"origin":"ai"},{"id":"fcp1-anemia-microcytic~ai-3","moduleId":"fcp1-anemia-microcytic","stem":"A 40-year-old woman presents with fatigue. Her labs show low hemoglobin, low MCV, and high RBC count. Which additional finding would most likely confirm thalassemia trait?","options":[{"id":"a","text":"Low ferritin"},{"id":"b","text":"High RDW"},{"id":"c","text":"Target cells on blood smear"},{"id":"d","text":"Low reticulocyte count"}],"answerId":"c","explanation":"Target cells on a blood smear are indicative of thalassemia.","kind":"clinical","origin":"ai"},{"id":"fcp1-anemia-microcytic~ai-4","moduleId":"fcp1-anemia-microcytic","stem":"A patient with microcytic anemia is mistakenly treated with iron supplements without confirming iron deficiency. What potential harm could result if the patient actually has thalassemia trait?","options":[{"id":"a","text":"Iron overload"},{"id":"b","text":"Increased anemia"},{"id":"c","text":"No effect"},{"id":"d","text":"Improvement in symptoms"}],"answerId":"a","explanation":"Iron supplementation in thalassemia trait can lead to iron overload, as these patients do not have iron deficiency.","kind":"trap","origin":"ai"},{"id":"fcp1-anemia-microcytic~ai-5","moduleId":"fcp1-anemia-microcytic","stem":"In a patient with microcytic anemia and abnormal vaginal bleeding, which test should be prioritized to determine the cause of anemia?","options":[{"id":"a","text":"Ferritin level"},{"id":"b","text":"Serum iron"},{"id":"c","text":"Hemoglobin electrophoresis"},{"id":"d","text":"Reticulocyte count"}],"answerId":"a","explanation":"Ferritin level is the pivotal test to confirm iron deficiency anemia, especially in the context of potential blood loss.","kind":"integration","linkedModuleIds":["fcp1-abnormal-vaginal-bleeding"],"origin":"ai"},{"id":"fcp1-anemia-microcytic~ai-6","moduleId":"fcp1-anemia-microcytic","stem":"A 50-year-old man with chronic kidney disease presents with microcytic anemia. His lab results show normal ferritin and low TIBC. What is the most likely diagnosis?","options":[{"id":"a","text":"Iron deficiency anemia"},{"id":"b","text":"Thalassemia trait"},{"id":"c","text":"Anemia of chronic disease"},{"id":"d","text":"Sideroblastic anemia"}],"answerId":"c","explanation":"Anemia of chronic disease is common in chronic kidney disease and is characterized by normal ferritin and low TIBC.","kind":"clinical","origin":"ai"}],"fcp1-pediatric-vomiting-diarrhea":[{"id":"fcp1-pediatric-vomiting-diarrhea~ai-0","moduleId":"fcp1-pediatric-vomiting-diarrhea","stem":"A 4-week-old infant presents with projectile non-bilious vomiting after feeds and is still hungry. What is the most likely diagnosis?","options":[{"id":"a","text":"Pyloric stenosis"},{"id":"b","text":"Intussusception"},{"id":"c","text":"Gastroesophageal reflux"},{"id":"d","text":"Malrotation with volvulus"}],"answerId":"a","explanation":"Projectile non-bilious vomiting in a 3-6 week old infant suggests pyloric stenosis.","kind":"recall","origin":"ai"},{"id":"fcp1-pediatric-vomiting-diarrhea~ai-1","moduleId":"fcp1-pediatric-vomiting-diarrhea","stem":"A 2-year-old child presents with intermittent abdominal pain and redcurrant-jelly stools. What physical exam finding is most likely?","options":[{"id":"a","text":"Olive mass in the abdomen"},{"id":"b","text":"Sausage-shaped mass in the right abdomen"},{"id":"c","text":"Visible gastric peristalsis"},{"id":"d","text":"Sunken eyes and dry mucosa"}],"answerId":"b","explanation":"Intussusception presents with a sausage-shaped mass in the abdomen.","kind":"recall","origin":"ai"},{"id":"fcp1-pediatric-vomiting-diarrhea~ai-2","moduleId":"fcp1-pediatric-vomiting-diarrhea","stem":"Which of the following is a red flag symptom in a vomiting infant that requires urgent surgical evaluation?","options":[{"id":"a","text":"Non-bilious vomiting"},{"id":"b","text":"Bilious vomiting"},{"id":"c","text":"Mild dehydration"},{"id":"d","text":"Fever without dehydration"}],"answerId":"b","explanation":"Bilious vomiting in an infant suggests malrotation with midgut volvulus, a surgical emergency.","kind":"trap","origin":"ai"},{"id":"fcp1-pediatric-vomiting-diarrhea~ai-3","moduleId":"fcp1-pediatric-vomiting-diarrhea","stem":"A 3-month-old infant presents with lethargy, cool peripheries, and weak pulses. What is the most likely underlying condition?","options":[{"id":"a","text":"Hypovolaemic shock from fluid loss"},{"id":"b","text":"Cardiogenic shock"},{"id":"c","text":"Septic shock"},{"id":"d","text":"Neurogenic shock"}],"answerId":"a","explanation":"These signs indicate hypovolaemic shock, often due to severe dehydration in infants.","kind":"clinical","origin":"ai"},{"id":"fcp1-pediatric-vomiting-diarrhea~ai-4","moduleId":"fcp1-pediatric-vomiting-diarrhea","stem":"In the management of acute gastroenteritis in children, what is the first-line treatment for rehydration?","options":[{"id":"a","text":"Intravenous fluids"},{"id":"b","text":"Oral rehydration solution"},{"id":"c","text":"Antibiotics"},{"id":"d","text":"Antiemetics"}],"answerId":"b","explanation":"Oral rehydration solution is the first-line treatment for rehydration in acute gastroenteritis.","kind":"recall","origin":"ai"},{"id":"fcp1-pediatric-vomiting-diarrhea~ai-5","moduleId":"fcp1-pediatric-vomiting-diarrhea","stem":"A 5-year-old child with diarrhea is suspected to have a condition affecting the enterohepatic circulation of bile salts. Which symptom might be present?","options":[{"id":"a","text":"Steatorrhea"},{"id":"b","text":"Projectile vomiting"},{"id":"c","text":"Redcurrant-jelly stools"},{"id":"d","text":"Non-bilious vomiting"}],"answerId":"a","explanation":"Disruption in enterohepatic circulation can lead to steatorrhea due to malabsorption of fats.","kind":"integration","linkedModuleIds":["enterohepatic-bile-circulation"],"origin":"ai"},{"id":"fcp1-pediatric-vomiting-diarrhea~ai-6","moduleId":"fcp1-pediatric-vomiting-diarrhea","stem":"A 6-month-old infant presents with bilious vomiting and abdominal distension. Which linked module should be consulted for further understanding of the surgical implications?","options":[{"id":"a","text":"fcp1-diarrhea-approach"},{"id":"b","text":"fcp1-nausea-vomiting"},{"id":"c","text":"fcp1-pediatric-abdominal-pain"},{"id":"d","text":"gastric-emptying-feedback"}],"answerId":"c","explanation":"The module on pediatric abdominal pain will provide insights into surgical emergencies like malrotation with volvulus.","kind":"integration","linkedModuleIds":["fcp1-pediatric-abdominal-pain"],"origin":"ai"}],"fcp1-splenomegaly-approach":[{"id":"fcp1-splenomegaly-approach~ai-0","moduleId":"fcp1-splenomegaly-approach","stem":"A 35-year-old man presents with a left upper quadrant mass. On examination, the mass has a notch, moves with respiration, is dull to percussion, and you cannot get above it. What is the most likely diagnosis?","options":[{"id":"a","text":"Splenomegaly"},{"id":"b","text":"Renal mass"},{"id":"c","text":"Pancreatic cyst"},{"id":"d","text":"Gastric tumor"}],"answerId":"a","explanation":"The described features confirm the mass as the spleen, indicating splenomegaly.","kind":"recall","origin":"ai"},{"id":"fcp1-splenomegaly-approach~ai-1","moduleId":"fcp1-splenomegaly-approach","stem":"Which of the following conditions is least likely to cause massive splenomegaly?","options":[{"id":"a","text":"Chronic myeloid leukemia"},{"id":"b","text":"Myelofibrosis"},{"id":"c","text":"Acute viral hepatitis"},{"id":"d","text":"Visceral leishmaniasis"}],"answerId":"c","explanation":"Acute viral hepatitis typically does not cause massive splenomegaly.","kind":"trap","origin":"ai"},{"id":"fcp1-splenomegaly-approach~ai-2","moduleId":"fcp1-splenomegaly-approach","stem":"A patient with splenomegaly presents with generalized lymphadenopathy and B symptoms. Which condition is most likely?","options":[{"id":"a","text":"Lymphoma"},{"id":"b","text":"Portal hypertension"},{"id":"c","text":"Thalassemia"},{"id":"d","text":"Gaucher disease"}],"answerId":"a","explanation":"The combination of splenomegaly, lymphadenopathy, and B symptoms suggests lymphoma.","kind":"clinical","origin":"ai"},{"id":"fcp1-splenomegaly-approach~ai-3","moduleId":"fcp1-splenomegaly-approach","stem":"A 50-year-old woman with cirrhosis presents with splenomegaly. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Infective"},{"id":"b","text":"Congestive"},{"id":"c","text":"Haematologic"},{"id":"d","text":"Infiltrative"}],"answerId":"b","explanation":"Cirrhosis leads to portal hypertension, causing congestive splenomegaly.","kind":"mechanism","origin":"ai"},{"id":"fcp1-splenomegaly-approach~ai-4","moduleId":"fcp1-splenomegaly-approach","stem":"A patient with splenomegaly is found to have hemolytic anemia. Which linked module would provide further insight into this condition?","options":[{"id":"a","text":"fcp1-anemia-approach-workup"},{"id":"b","text":"hhl-non-hodgkin-lymphoma"},{"id":"c","text":"fcp1-lymphadenopathy-approach"},{"id":"d","text":"fcp1-abdominal-mass-differential"}],"answerId":"a","explanation":"The 'fcp1-anemia-approach-workup' module provides insights into the workup of anemia, including hemolytic types.","kind":"integration","linkedModuleIds":["fcp1-anemia-approach-workup"],"origin":"ai"},{"id":"fcp1-splenomegaly-approach~ai-5","moduleId":"fcp1-splenomegaly-approach","stem":"A patient with massive splenomegaly and a history of chronic malaria presents. What is the most likely cause of the splenomegaly?","options":[{"id":"a","text":"Chronic myeloid leukemia"},{"id":"b","text":"Myelofibrosis"},{"id":"c","text":"Chronic malaria"},{"id":"d","text":"Thalassemia major"}],"answerId":"c","explanation":"Chronic malaria is a known cause of massive splenomegaly.","kind":"clinical","origin":"ai"},{"id":"fcp1-splenomegaly-approach~ai-6","moduleId":"fcp1-splenomegaly-approach","stem":"In a patient with splenomegaly and signs of autoimmune hemolytic anemia, which linked module would be most relevant for further study?","options":[{"id":"a","text":"hhl-aiha"},{"id":"b","text":"fcp1-lymphadenopathy-approach"},{"id":"c","text":"hhl-non-hodgkin-lymphoma"},{"id":"d","text":"fcp1-abdominal-mass-differential"}],"answerId":"a","explanation":"The 'hhl-aiha' module is relevant for autoimmune hemolytic anemia.","kind":"integration","linkedModuleIds":["hhl-aiha"],"origin":"ai"}],"fcp1-lymphadenopathy-approach":[{"id":"fcp1-lymphadenopathy-approach~ai-0","moduleId":"fcp1-lymphadenopathy-approach","stem":"A 35-year-old patient presents with a 3 cm, hard, non-tender, fixed lymph node in the left supraclavicular region. What is the most appropriate next step in management?","options":[{"id":"a","text":"Excisional biopsy"},{"id":"b","text":"Fine-needle aspiration"},{"id":"c","text":"Antibiotic therapy"},{"id":"d","text":"Observation for 2 weeks"}],"answerId":"a","explanation":"A left supraclavicular node is high-risk for malignancy and warrants an excisional biopsy.","kind":"clinical","origin":"ai"},{"id":"fcp1-lymphadenopathy-approach~ai-1","moduleId":"fcp1-lymphadenopathy-approach","stem":"Which feature is most indicative of a benign/reactive lymphadenopathy?","options":[{"id":"a","text":"Node >2 cm"},{"id":"b","text":"Hard and fixed node"},{"id":"c","text":"Tender and mobile node"},{"id":"d","text":"Presence of B symptoms"}],"answerId":"c","explanation":"Tender and mobile nodes are typically reactive and benign, often associated with local infections.","kind":"recall","origin":"ai"},{"id":"fcp1-lymphadenopathy-approach~ai-2","moduleId":"fcp1-lymphadenopathy-approach","stem":"A patient with generalized lymphadenopathy and hepatosplenomegaly is likely to have which condition?","options":[{"id":"a","text":"Localized infection"},{"id":"b","text":"Lymphoma"},{"id":"c","text":"Benign reactive lymphadenopathy"},{"id":"d","text":"Thyroid disease"}],"answerId":"b","explanation":"Generalized lymphadenopathy with hepatosplenomegaly suggests lymphoma or leukemia.","kind":"mechanism","origin":"ai"},{"id":"fcp1-lymphadenopathy-approach~ai-3","moduleId":"fcp1-lymphadenopathy-approach","stem":"Why is excisional biopsy preferred over fine-needle aspiration for diagnosing suspected lymphoma?","options":[{"id":"a","text":"FNA is more painful"},{"id":"b","text":"Excisional biopsy is less invasive"},{"id":"c","text":"FNA lacks nodal architecture"},{"id":"d","text":"Excisional biopsy is faster"}],"answerId":"c","explanation":"Excisional biopsy is preferred because it preserves nodal architecture, which is crucial for diagnosing lymphoma.","kind":"trap","origin":"ai"},{"id":"fcp1-lymphadenopathy-approach~ai-4","moduleId":"fcp1-lymphadenopathy-approach","stem":"A 22-year-old presents with a sore throat, fever, and cervical lymphadenopathy. Which linked module is most relevant for further understanding this condition?","options":[{"id":"a","text":"hhl-ebv-mononucleosis"},{"id":"b","text":"fcp1-thyroid-approach"},{"id":"c","text":"fcp1-abdominal-mass-differential"},{"id":"d","text":"history-ancient-to-renaissance"}],"answerId":"a","explanation":"The symptoms suggest infectious mononucleosis, commonly caused by EBV.","kind":"integration","linkedModuleIds":["hhl-ebv-mononucleosis"],"origin":"ai"},{"id":"fcp1-lymphadenopathy-approach~ai-5","moduleId":"fcp1-lymphadenopathy-approach","stem":"A patient with a 1 cm, soft, tender, mobile lymph node in the cervical region and a recent upper respiratory infection is most likely to have which type of lymphadenopathy?","options":[{"id":"a","text":"Malignant"},{"id":"b","text":"Reactive"},{"id":"c","text":"Metastatic"},{"id":"d","text":"Lymphoma"}],"answerId":"b","explanation":"Soft, tender, and mobile nodes associated with recent infection are typically reactive.","kind":"clinical","origin":"ai"},{"id":"fcp1-lymphadenopathy-approach~ai-6","moduleId":"fcp1-lymphadenopathy-approach","stem":"In the context of lymphadenopathy, which historical medical figure emphasized the importance of observation in diagnosis?","options":[{"id":"a","text":"Hippocrates"},{"id":"b","text":"Galen"},{"id":"c","text":"Avicenna"},{"id":"d","text":"Paracelsus"}],"answerId":"a","explanation":"Hippocrates is known for emphasizing observation in medical diagnosis.","kind":"integration","linkedModuleIds":["history-ancient-to-renaissance"],"origin":"ai"}],"fcp1-bleeding-assessment-tool":[{"id":"fcp1-bleeding-assessment-tool~ai-0","moduleId":"fcp1-bleeding-assessment-tool","stem":"A 25-year-old woman presents with heavy menstrual bleeding and frequent nosebleeds since childhood. Her father has a similar history. Which of the following is the most likely diagnosis?","options":[{"id":"a","text":"von Willebrand disease"},{"id":"b","text":"Hemophilia A"},{"id":"c","text":"Thrombocytopenia"},{"id":"d","text":"Vitamin K deficiency"}],"answerId":"a","explanation":"The family history and lifelong pattern suggest an inherited disorder, with von Willebrand disease being the most common inherited bleeding disorder.","kind":"clinical","origin":"ai"},{"id":"fcp1-bleeding-assessment-tool~ai-1","moduleId":"fcp1-bleeding-assessment-tool","stem":"A patient with a history of easy bruising and prolonged bleeding after dental procedures has normal PT, aPTT, and platelet counts. What is the next best step in management?","options":[{"id":"a","text":"Reassure the patient"},{"id":"b","text":"Perform von Willebrand factor assay"},{"id":"c","text":"Start vitamin K supplementation"},{"id":"d","text":"Order a liver function test"}],"answerId":"b","explanation":"A convincing bleeding history warrants specific testing for von Willebrand disease even when screening tests are normal.","kind":"trap","origin":"ai"},{"id":"fcp1-bleeding-assessment-tool~ai-2","moduleId":"fcp1-bleeding-assessment-tool","stem":"Which of the following is a characteristic finding in a patient with an acquired bleeding disorder?","options":[{"id":"a","text":"Lifelong bleeding tendency"},{"id":"b","text":"Positive family history"},{"id":"c","text":"New-onset bleeding with drug use"},{"id":"d","text":"Bleeding out of proportion to minor injuries"}],"answerId":"c","explanation":"New-onset bleeding with a relevant drug list or systemic illness suggests an acquired cause.","kind":"mechanism","origin":"ai"},{"id":"fcp1-bleeding-assessment-tool~ai-3","moduleId":"fcp1-bleeding-assessment-tool","stem":"A 30-year-old man with a history of hemophilia A undergoes a successful appendectomy without excessive bleeding. What does this suggest about his bleeding disorder?","options":[{"id":"a","text":"Severe hemophilia A"},{"id":"b","text":"Mild hemophilia A"},{"id":"c","text":"Acquired hemophilia"},{"id":"d","text":"No bleeding disorder"}],"answerId":"b","explanation":"Uneventful major surgery suggests a mild form of hemophilia A.","kind":"clinical","linkedModuleIds":["hhl-coagulation-disorders"],"origin":"ai"},{"id":"fcp1-bleeding-assessment-tool~ai-4","moduleId":"fcp1-bleeding-assessment-tool","stem":"A 3-year-old child presents with bruising and bleeding gums. Coagulation tests show low levels of vitamin K-dependent factors. How should these results be interpreted?","options":[{"id":"a","text":"Normal for age"},{"id":"b","text":"Suggestive of hemophilia"},{"id":"c","text":"Indicative of liver disease"},{"id":"d","text":"Consistent with vitamin K deficiency"}],"answerId":"a","explanation":"Neonates and infants have physiologically lower vitamin K-dependent factor levels, so these results are normal for age.","kind":"integration","linkedModuleIds":["hhl-coagulation-disorders"],"origin":"ai"},{"id":"fcp1-bleeding-assessment-tool~ai-5","moduleId":"fcp1-bleeding-assessment-tool","stem":"A 40-year-old woman reports heavy menstrual bleeding and easy bruising. She has a normal bleeding score on the ISTH-BAT. What is the most appropriate next step?","options":[{"id":"a","text":"Perform a platelet function test"},{"id":"b","text":"Reassure the patient"},{"id":"c","text":"Start iron supplementation"},{"id":"d","text":"Check for liver disease"}],"answerId":"b","explanation":"A normal bleeding score on the ISTH-BAT has good negative predictive value, suggesting no significant bleeding disorder.","kind":"recall","origin":"ai"},{"id":"fcp1-bleeding-assessment-tool~ai-6","moduleId":"fcp1-bleeding-assessment-tool","stem":"Which of the following scenarios would most strongly suggest a primary hemostatic defect?","options":[{"id":"a","text":"Prolonged bleeding after a tooth extraction"},{"id":"b","text":"Bleeding into joints"},{"id":"c","text":"Delayed bleeding after surgery"},{"id":"d","text":"Bleeding with normal platelet count"}],"answerId":"a","explanation":"Prolonged bleeding after mucosal injury, such as a tooth extraction, suggests a primary hemostatic defect.","kind":"integration","linkedModuleIds":["hhl-primary-hemostasis-disorders"],"origin":"ai"}],"fcp1-bleeding-coagulation-tests":[{"id":"fcp1-bleeding-coagulation-tests~ai-0","moduleId":"fcp1-bleeding-coagulation-tests","stem":"A patient presents with a prolonged aPTT that corrects upon mixing with normal plasma. What is the most likely underlying condition?","options":[{"id":"a","text":"Hemophilia"},{"id":"b","text":"Lupus anticoagulant"},{"id":"c","text":"Factor VIII inhibitor"},{"id":"d","text":"Vitamin K deficiency"}],"answerId":"a","explanation":"Correction of a prolonged aPTT with mixing indicates a factor deficiency, such as hemophilia.","kind":"mechanism","origin":"ai"},{"id":"fcp1-bleeding-coagulation-tests~ai-1","moduleId":"fcp1-bleeding-coagulation-tests","stem":"Which of the following conditions is most likely if both PT and aPTT are prolonged?","options":[{"id":"a","text":"Factor VII deficiency"},{"id":"b","text":"Hemophilia A"},{"id":"c","text":"Disseminated Intravascular Coagulation (DIC)"},{"id":"d","text":"Von Willebrand Disease"}],"answerId":"c","explanation":"Prolongation of both PT and aPTT suggests a common pathway problem, severe liver disease, DIC, or warfarin excess.","kind":"clinical","origin":"ai"},{"id":"fcp1-bleeding-coagulation-tests~ai-2","moduleId":"fcp1-bleeding-coagulation-tests","stem":"A patient on warfarin therapy has an isolated prolonged PT. What is the most likely explanation?","options":[{"id":"a","text":"Factor VIII deficiency"},{"id":"b","text":"Factor VII deficiency"},{"id":"c","text":"Heparin administration"},{"id":"d","text":"Lupus anticoagulant"}],"answerId":"b","explanation":"An isolated prolonged PT in a patient on warfarin suggests a factor VII deficiency or early warfarin effect.","kind":"recall","origin":"ai"},{"id":"fcp1-bleeding-coagulation-tests~ai-3","moduleId":"fcp1-bleeding-coagulation-tests","stem":"A patient with a normal PT and aPTT presents with bleeding. Which condition should be considered?","options":[{"id":"a","text":"Factor XIII deficiency"},{"id":"b","text":"Severe liver disease"},{"id":"c","text":"DIC"},{"id":"d","text":"Hemophilia"}],"answerId":"a","explanation":"Normal PT and aPTT with bleeding suggests a condition like factor XIII deficiency, which affects clot stability.","kind":"trap","origin":"ai"},{"id":"fcp1-bleeding-coagulation-tests~ai-4","moduleId":"fcp1-bleeding-coagulation-tests","stem":"A patient has a prolonged aPTT that does not correct with a mixing study. What is the most likely cause?","options":[{"id":"a","text":"Factor IX deficiency"},{"id":"b","text":"Lupus anticoagulant"},{"id":"c","text":"Factor VII deficiency"},{"id":"d","text":"Vitamin K deficiency"}],"answerId":"b","explanation":"Failure to correct with mixing suggests an inhibitor, such as a lupus anticoagulant.","kind":"mechanism","origin":"ai"},{"id":"fcp1-bleeding-coagulation-tests~ai-5","moduleId":"fcp1-bleeding-coagulation-tests","stem":"In a patient with DIC, which of the following lab findings is expected?","options":[{"id":"a","text":"Normal fibrinogen"},{"id":"b","text":"Low D-dimer"},{"id":"c","text":"Low platelets"},{"id":"d","text":"Normal PT"}],"answerId":"c","explanation":"DIC is characterized by low platelets, high PT, high aPTT, low fibrinogen, and high D-dimer.","kind":"clinical","origin":"ai"},{"id":"fcp1-bleeding-coagulation-tests~ai-6","moduleId":"fcp1-bleeding-coagulation-tests","stem":"A patient with a history of easy bruising and epistaxis has a normal PT and aPTT. Which test should be considered next?","options":[{"id":"a","text":"Platelet function assay"},{"id":"b","text":"Factor VIII level"},{"id":"c","text":"Liver function test"},{"id":"d","text":"D-dimer"}],"answerId":"a","explanation":"Normal PT and aPTT with bleeding symptoms suggest a platelet function defect, warranting a platelet function assay.","kind":"trap","origin":"ai"},{"id":"fcp1-bleeding-coagulation-tests~ai-7","moduleId":"fcp1-bleeding-coagulation-tests","stem":"How does apoptosis relate to coagulation disorders in terms of cellular regulation?","options":[{"id":"a","text":"Apoptosis directly causes coagulation disorders"},{"id":"b","text":"Coagulation factors regulate apoptosis"},{"id":"c","text":"Both involve tightly regulated proteolytic cascades"},{"id":"d","text":"Apoptosis is unrelated to coagulation"}],"answerId":"c","explanation":"Both apoptosis and coagulation involve tightly regulated proteolytic cascades for controlled cellular processes.","kind":"integration","linkedModuleIds":["apoptosis-cell-death"],"origin":"ai"},{"id":"fcp1-bleeding-coagulation-tests~ai-8","moduleId":"fcp1-bleeding-coagulation-tests","stem":"A patient with hemophilia presents with joint bleeding. Which coagulation test is most likely prolonged?","options":[{"id":"a","text":"PT"},{"id":"b","text":"aPTT"},{"id":"c","text":"Platelet count"},{"id":"d","text":"Fibrinogen level"}],"answerId":"b","explanation":"Hemophilia affects intrinsic pathway factors, leading to a prolonged aPTT.","kind":"integration","linkedModuleIds":["hhl-coagulation-disorders"],"origin":"ai"}],"fcp1-bleeding-primary-vs-secondary":[{"id":"fcp1-bleeding-primary-vs-secondary~ai-0","moduleId":"fcp1-bleeding-primary-vs-secondary","stem":"A 25-year-old male presents with recurrent nosebleeds, easy bruising, and petechiae. Laboratory tests show normal PT and aPTT. What is the most likely underlying defect?","options":[{"id":"a","text":"Platelet dysfunction"},{"id":"b","text":"Coagulation factor deficiency"},{"id":"c","text":"Vitamin K deficiency"},{"id":"d","text":"Liver disease"}],"answerId":"a","explanation":"The mucocutaneous bleeding pattern and normal coagulation tests suggest a primary haemostatic defect, such as platelet dysfunction.","kind":"clinical","origin":"ai"},{"id":"fcp1-bleeding-primary-vs-secondary~ai-1","moduleId":"fcp1-bleeding-primary-vs-secondary","stem":"A 10-year-old boy presents with hemarthrosis after a minor injury. His PT is normal, but aPTT is prolonged. What is the most likely diagnosis?","options":[{"id":"a","text":"Hemophilia A"},{"id":"b","text":"Von Willebrand disease"},{"id":"c","text":"Thrombocytopenia"},{"id":"d","text":"Vitamin K deficiency"}],"answerId":"a","explanation":"The deep bleeding and isolated prolonged aPTT suggest a secondary haemostatic defect, such as Hemophilia A.","kind":"clinical","origin":"ai"},{"id":"fcp1-bleeding-primary-vs-secondary~ai-2","moduleId":"fcp1-bleeding-primary-vs-secondary","stem":"Which of the following is a characteristic finding in a primary haemostatic defect?","options":[{"id":"a","text":"Petechiae"},{"id":"b","text":"Hemarthrosis"},{"id":"c","text":"Deep muscle hematoma"},{"id":"d","text":"Retroperitoneal hematoma"}],"answerId":"a","explanation":"Petechiae are indicative of a primary haemostatic defect involving platelets or vessel walls.","kind":"recall","origin":"ai"},{"id":"fcp1-bleeding-primary-vs-secondary~ai-3","moduleId":"fcp1-bleeding-primary-vs-secondary","stem":"A patient with von Willebrand disease is most likely to present with which type of bleeding pattern?","options":[{"id":"a","text":"Mucocutaneous bleeding"},{"id":"b","text":"Deep muscle hematomas"},{"id":"c","text":"Hemarthrosis"},{"id":"d","text":"Retroperitoneal bleeding"}],"answerId":"a","explanation":"Von Willebrand disease primarily presents with mucocutaneous bleeding due to its role in platelet function.","kind":"recall","origin":"ai"},{"id":"fcp1-bleeding-primary-vs-secondary~ai-4","moduleId":"fcp1-bleeding-primary-vs-secondary","stem":"A 45-year-old woman with liver cirrhosis presents with oozing from venepuncture sites and widespread bruising. Which linked module would help interpret her coagulation test results?","options":[{"id":"a","text":"hhl-coagulation-disorders"},{"id":"b","text":"fcp1-bleeding-coagulation-tests"},{"id":"c","text":"fcp1-ent-common-symptoms"},{"id":"d","text":"fcp1-skin-lesion-morphology"}],"answerId":"b","explanation":"The module 'fcp1-bleeding-coagulation-tests' provides guidance on interpreting coagulation test results in bleeding disorders.","kind":"integration","linkedModuleIds":["fcp1-bleeding-coagulation-tests"],"origin":"ai"},{"id":"fcp1-bleeding-primary-vs-secondary~ai-5","moduleId":"fcp1-bleeding-primary-vs-secondary","stem":"A 30-year-old male with a history of hemophilia B presents with a swollen knee after a minor fall. Which module would provide additional information on his condition?","options":[{"id":"a","text":"hhl-coagulation-disorders"},{"id":"b","text":"fcp1-bleeding-assessment-tool"},{"id":"c","text":"fcp1-ent-common-symptoms"},{"id":"d","text":"fcp1-skin-lesion-morphology"}],"answerId":"a","explanation":"The module 'hhl-coagulation-disorders' covers hemophilia and related coagulation factor disorders.","kind":"integration","linkedModuleIds":["hhl-coagulation-disorders"],"origin":"ai"}],"fcp1-headache-red-flags":[{"id":"fcp1-headache-red-flags~ai-0","moduleId":"fcp1-headache-red-flags","stem":"A 55-year-old woman presents with a new onset headache, jaw claudication, and scalp tenderness. Which laboratory test is most indicative of the suspected diagnosis?","options":[{"id":"a","text":"C-reactive protein"},{"id":"b","text":"Erythrocyte sedimentation rate"},{"id":"c","text":"Complete blood count"},{"id":"d","text":"Serum calcium"}],"answerId":"b","explanation":"A raised erythrocyte sedimentation rate (ESR) is indicative of giant cell arteritis.","kind":"recall","origin":"ai"},{"id":"fcp1-headache-red-flags~ai-1","moduleId":"fcp1-headache-red-flags","stem":"A patient presents with a sudden, severe headache described as the 'worst of their life'. What is the most appropriate initial investigation?","options":[{"id":"a","text":"MRI of the brain"},{"id":"b","text":"Non-contrast CT of the brain"},{"id":"c","text":"Lumbar puncture"},{"id":"d","text":"EEG"}],"answerId":"b","explanation":"A non-contrast CT of the brain is the initial investigation for suspected subarachnoid hemorrhage.","kind":"mechanism","origin":"ai"},{"id":"fcp1-headache-red-flags~ai-2","moduleId":"fcp1-headache-red-flags","stem":"A 30-year-old man presents with fever, headache, and neck stiffness. What is the most critical step in management?","options":[{"id":"a","text":"Perform lumbar puncture"},{"id":"b","text":"Administer empirical antibiotics"},{"id":"c","text":"Order a CT scan"},{"id":"d","text":"Monitor vital signs"}],"answerId":"b","explanation":"Empirical antibiotics should be administered immediately in suspected bacterial meningitis.","kind":"trap","origin":"ai"},{"id":"fcp1-headache-red-flags~ai-3","moduleId":"fcp1-headache-red-flags","stem":"A 60-year-old man with a history of hypertension presents with a headache that worsens when lying down and is associated with vomiting. What is the most likely underlying condition?","options":[{"id":"a","text":"Migraine"},{"id":"b","text":"Tension-type headache"},{"id":"c","text":"Cluster headache"},{"id":"d","text":"Raised intracranial pressure"}],"answerId":"d","explanation":"Headache worsening when lying down with vomiting suggests raised intracranial pressure.","kind":"clinical","origin":"ai"},{"id":"fcp1-headache-red-flags~ai-4","moduleId":"fcp1-headache-red-flags","stem":"A 45-year-old woman presents with a headache and transient visual obscurations. Fundoscopy reveals papilloedema. What is the most likely cause?","options":[{"id":"a","text":"Migraine"},{"id":"b","text":"Tension-type headache"},{"id":"c","text":"Cluster headache"},{"id":"d","text":"Space-occupying lesion"}],"answerId":"d","explanation":"Papilloedema with transient visual obscurations suggests raised intracranial pressure, often due to a space-occupying lesion.","kind":"clinical","origin":"ai"},{"id":"fcp1-headache-red-flags~ai-5","moduleId":"fcp1-headache-red-flags","stem":"A 70-year-old woman presents with sudden vision loss in one eye and a new headache. What condition should be urgently considered?","options":[{"id":"a","text":"Migraine with aura"},{"id":"b","text":"Retinal detachment"},{"id":"c","text":"Giant cell arteritis"},{"id":"d","text":"Acute glaucoma"}],"answerId":"c","explanation":"Giant cell arteritis can cause sudden vision loss and requires urgent treatment to prevent permanent blindness.","kind":"integration","linkedModuleIds":["fcp1-eye-vision-loss"],"origin":"ai"},{"id":"fcp1-headache-red-flags~ai-6","moduleId":"fcp1-headache-red-flags","stem":"A 25-year-old woman presents with a headache that worsens with Valsalva maneuver and is associated with nausea. What is the most likely diagnosis?","options":[{"id":"a","text":"Migraine"},{"id":"b","text":"Tension-type headache"},{"id":"c","text":"Cluster headache"},{"id":"d","text":"Raised intracranial pressure"}],"answerId":"d","explanation":"A headache that worsens with Valsalva maneuver suggests raised intracranial pressure.","kind":"integration","linkedModuleIds":["fcp1-nausea-vomiting"],"origin":"ai"}],"fcp1-dizziness-vertigo":[{"id":"fcp1-dizziness-vertigo~ai-0","moduleId":"fcp1-dizziness-vertigo","stem":"A 65-year-old man presents with sudden onset of vertigo, diplopia, and ataxia. Examination reveals vertical nystagmus and inability to walk unaided. What is the most likely diagnosis?","options":[{"id":"a","text":"Benign Paroxysmal Positional Vertigo (BPPV)"},{"id":"b","text":"Vestibular Neuritis"},{"id":"c","text":"Ménière's Disease"},{"id":"d","text":"Posterior Circulation Stroke"}],"answerId":"d","explanation":"Vertical nystagmus and inability to walk unaided suggest a central cause, such as a posterior circulation stroke.","kind":"clinical","origin":"ai"},{"id":"fcp1-dizziness-vertigo~ai-1","moduleId":"fcp1-dizziness-vertigo","stem":"Which of the following findings in the HINTS exam would suggest a central cause of vertigo?","options":[{"id":"a","text":"Unidirectional horizontal nystagmus"},{"id":"b","text":"Normal head-impulse test"},{"id":"c","text":"Fatigable up-beating torsional nystagmus"},{"id":"d","text":"Abnormal head-impulse test"}],"answerId":"b","explanation":"A normal head-impulse test in the context of acute continuous vertigo suggests a central cause.","kind":"mechanism","origin":"ai"},{"id":"fcp1-dizziness-vertigo~ai-2","moduleId":"fcp1-dizziness-vertigo","stem":"A patient presents with episodic vertigo, fluctuating hearing loss, and tinnitus. What is the most likely diagnosis?","options":[{"id":"a","text":"Benign Paroxysmal Positional Vertigo (BPPV)"},{"id":"b","text":"Vestibular Neuritis"},{"id":"c","text":"Ménière's Disease"},{"id":"d","text":"Acoustic Neuroma"}],"answerId":"c","explanation":"Ménière's disease is characterized by episodic vertigo, fluctuating hearing loss, and tinnitus.","kind":"recall","origin":"ai"},{"id":"fcp1-dizziness-vertigo~ai-3","moduleId":"fcp1-dizziness-vertigo","stem":"During a Dix-Hallpike maneuver, a patient exhibits transient fatigable up-beating torsional nystagmus. What does this indicate?","options":[{"id":"a","text":"Central vertigo"},{"id":"b","text":"Peripheral vertigo due to BPPV"},{"id":"c","text":"Ménière's Disease"},{"id":"d","text":"Vestibular Migraine"}],"answerId":"b","explanation":"This finding is characteristic of BPPV, indicating a peripheral cause.","kind":"recall","origin":"ai"},{"id":"fcp1-dizziness-vertigo~ai-4","moduleId":"fcp1-dizziness-vertigo","stem":"A patient with acute vertigo has a positive head-impulse test and unidirectional horizontal nystagmus. What is the most likely diagnosis?","options":[{"id":"a","text":"Central vertigo"},{"id":"b","text":"Vestibular Neuritis"},{"id":"c","text":"Ménière's Disease"},{"id":"d","text":"Labyrinthitis"}],"answerId":"b","explanation":"A positive head-impulse test and unidirectional horizontal nystagmus suggest a peripheral lesion, such as vestibular neuritis.","kind":"trap","origin":"ai"},{"id":"fcp1-dizziness-vertigo~ai-5","moduleId":"fcp1-dizziness-vertigo","stem":"A 50-year-old woman presents with dizziness described as light-headedness and near-fainting episodes. Which linked module should be reviewed for further evaluation?","options":[{"id":"a","text":"Inner Ear Disorders & Temporal Bone"},{"id":"b","text":"Approach to Syncope"},{"id":"c","text":"Optic Nerve Disorders & Disc Edema"},{"id":"d","text":"Common ENT Symptoms"}],"answerId":"b","explanation":"The symptoms described are more consistent with presyncope, which is covered in the 'Approach to Syncope' module.","kind":"integration","linkedModuleIds":["fcp1-syncope-approach"],"origin":"ai"},{"id":"fcp1-dizziness-vertigo~ai-6","moduleId":"fcp1-dizziness-vertigo","stem":"A patient with vertigo also reports severe headache and neck stiffness. Which linked module might provide additional diagnostic insights?","options":[{"id":"a","text":"Headache Red Flags"},{"id":"b","text":"Inner Ear Disorders & Temporal Bone"},{"id":"c","text":"Weakness — UMN vs LMN"},{"id":"d","text":"Common ENT Symptoms"}],"answerId":"a","explanation":"Severe headache and neck stiffness are red flags that may indicate a serious condition, as discussed in the 'Headache Red Flags' module.","kind":"integration","linkedModuleIds":["fcp1-headache-red-flags"],"origin":"ai"}],"fcp1-headache-primary-secondary":[{"id":"fcp1-headache-primary-secondary~ai-0","moduleId":"fcp1-headache-primary-secondary","stem":"A 30-year-old woman presents with recurrent unilateral headaches that are pulsating and associated with nausea and photophobia. What is the most likely diagnosis?","options":[{"id":"a","text":"Migraine"},{"id":"b","text":"Tension-type headache"},{"id":"c","text":"Cluster headache"},{"id":"d","text":"Sinus headache"}],"answerId":"a","explanation":"The presentation of unilateral pulsating pain with nausea and photophobia is characteristic of a migraine.","kind":"recall","origin":"ai"},{"id":"fcp1-headache-primary-secondary~ai-1","moduleId":"fcp1-headache-primary-secondary","stem":"Which of the following headache types is characterized by severe unilateral orbital pain with ipsilateral autonomic features?","options":[{"id":"a","text":"Migraine"},{"id":"b","text":"Tension-type headache"},{"id":"c","text":"Cluster headache"},{"id":"d","text":"Sinus headache"}],"answerId":"c","explanation":"Cluster headaches are known for severe unilateral orbital pain with autonomic features like tearing and ptosis.","kind":"recall","origin":"ai"},{"id":"fcp1-headache-primary-secondary~ai-2","moduleId":"fcp1-headache-primary-secondary","stem":"A patient presents with a new type of headache that is different from their usual pattern. What is the most appropriate next step?","options":[{"id":"a","text":"Start migraine prophylaxis"},{"id":"b","text":"Perform a detailed neurological exam"},{"id":"c","text":"Prescribe NSAIDs"},{"id":"d","text":"Reassure and discharge"}],"answerId":"b","explanation":"A new headache phenotype requires exclusion of secondary causes, warranting a detailed neurological exam.","kind":"clinical","origin":"ai"},{"id":"fcp1-headache-primary-secondary~ai-3","moduleId":"fcp1-headache-primary-secondary","stem":"A 45-year-old man experiences bilateral band-like pressure headaches without nausea. What is the most likely diagnosis?","options":[{"id":"a","text":"Migraine"},{"id":"b","text":"Tension-type headache"},{"id":"c","text":"Cluster headache"},{"id":"d","text":"Sinus headache"}],"answerId":"b","explanation":"Bilateral band-like pressure without nausea is typical of tension-type headaches.","kind":"recall","origin":"ai"},{"id":"fcp1-headache-primary-secondary~ai-4","moduleId":"fcp1-headache-primary-secondary","stem":"A patient reports a sudden onset of severe headache with a peak intensity within one minute. What is the most concerning potential diagnosis?","options":[{"id":"a","text":"Migraine"},{"id":"b","text":"Tension-type headache"},{"id":"c","text":"Cluster headache"},{"id":"d","text":"Subarachnoid hemorrhage"}],"answerId":"d","explanation":"A thunderclap headache with sudden onset and peak intensity within one minute is concerning for subarachnoid hemorrhage.","kind":"trap","origin":"ai"},{"id":"fcp1-headache-primary-secondary~ai-5","moduleId":"fcp1-headache-primary-secondary","stem":"A 50-year-old woman with a history of migraines presents with dizziness and a headache that differs from her usual migraines. Which module should be consulted to further evaluate her symptoms?","options":[{"id":"a","text":"Migraine Pathophysiology & Acute Treatment"},{"id":"b","text":"Migraine Prophylaxis"},{"id":"c","text":"Headache Red Flags"},{"id":"d","text":"Dizziness & Vertigo"}],"answerId":"d","explanation":"Dizziness often overlaps with headaches, and the 'Dizziness & Vertigo' module can provide further insights.","kind":"integration","linkedModuleIds":["fcp1-dizziness-vertigo"],"origin":"ai"},{"id":"fcp1-headache-primary-secondary~ai-6","moduleId":"fcp1-headache-primary-secondary","stem":"A patient with a history of migraines presents with a headache that has new red flag features. Which module should be referenced to assess these red flags?","options":[{"id":"a","text":"Migraine Pathophysiology & Acute Treatment"},{"id":"b","text":"Migraine Prophylaxis"},{"id":"c","text":"Headache Red Flags"},{"id":"d","text":"Dizziness & Vertigo"}],"answerId":"c","explanation":"The 'Headache Red Flags' module is essential for evaluating new concerning features in a headache.","kind":"integration","linkedModuleIds":["fcp1-headache-red-flags"],"origin":"ai"}],"fcp1-weakness-umn-lmn":[{"id":"fcp1-weakness-umn-lmn~ai-0","moduleId":"fcp1-weakness-umn-lmn","stem":"A 65-year-old man presents with weakness in his right arm. Examination reveals increased tone, brisk reflexes, and an extensor plantar response. What type of lesion is most likely?","options":[{"id":"a","text":"Upper motor neurone lesion"},{"id":"b","text":"Lower motor neurone lesion"},{"id":"c","text":"Neuromuscular junction disorder"},{"id":"d","text":"Peripheral neuropathy"}],"answerId":"a","explanation":"The findings of increased tone, brisk reflexes, and an extensor plantar response are characteristic of an upper motor neurone lesion.","kind":"recall","origin":"ai"},{"id":"fcp1-weakness-umn-lmn~ai-1","moduleId":"fcp1-weakness-umn-lmn","stem":"A patient presents with muscle wasting, fasciculations, and absent reflexes in the lower limbs. What is the most likely cause?","options":[{"id":"a","text":"Upper motor neurone lesion"},{"id":"b","text":"Lower motor neurone lesion"},{"id":"c","text":"Central nervous system infection"},{"id":"d","text":"Myopathy"}],"answerId":"b","explanation":"Muscle wasting, fasciculations, and absent reflexes are indicative of a lower motor neurone lesion.","kind":"recall","origin":"ai"},{"id":"fcp1-weakness-umn-lmn~ai-2","moduleId":"fcp1-weakness-umn-lmn","stem":"A 45-year-old woman presents with acute ascending weakness and areflexia. What is the most critical parameter to monitor?","options":[{"id":"a","text":"Oxygen saturation"},{"id":"b","text":"Blood pressure"},{"id":"c","text":"Forced vital capacity"},{"id":"d","text":"Heart rate"}],"answerId":"c","explanation":"In Guillain-Barré syndrome, monitoring forced vital capacity is crucial as it indicates impending respiratory failure before oxygen saturation drops.","kind":"trap","origin":"ai"},{"id":"fcp1-weakness-umn-lmn~ai-3","moduleId":"fcp1-weakness-umn-lmn","stem":"A patient with a history of dizziness and vertigo presents with sudden onset of left-sided weakness. What is the most likely diagnosis?","options":[{"id":"a","text":"Peripheral neuropathy"},{"id":"b","text":"Stroke"},{"id":"c","text":"Multiple sclerosis"},{"id":"d","text":"Myasthenia gravis"}],"answerId":"b","explanation":"Sudden onset of focal weakness with a history of dizziness and vertigo suggests a posterior circulation stroke.","kind":"integration","linkedModuleIds":["fcp1-dizziness-vertigo"],"origin":"ai"},{"id":"fcp1-weakness-umn-lmn~ai-4","moduleId":"fcp1-weakness-umn-lmn","stem":"Which of the following findings is most consistent with spinal cord compression?","options":[{"id":"a","text":"Symmetrical ascending weakness"},{"id":"b","text":"A sensory level with brisk legs and lax anal tone"},{"id":"c","text":"Muscle wasting and fasciculations"},{"id":"d","text":"Fatigable weakness with normal reflexes"}],"answerId":"b","explanation":"A sensory level with brisk legs and lax anal tone is indicative of spinal cord compression.","kind":"clinical","origin":"ai"},{"id":"fcp1-weakness-umn-lmn~ai-5","moduleId":"fcp1-weakness-umn-lmn","stem":"A patient presents with mixed upper and lower motor neurone signs but no sensory loss. Which condition is most likely?","options":[{"id":"a","text":"Guillain-Barré syndrome"},{"id":"b","text":"Motor neurone disease"},{"id":"c","text":"Multiple sclerosis"},{"id":"d","text":"Peripheral neuropathy"}],"answerId":"b","explanation":"Mixed UMN and LMN signs without sensory loss suggest motor neurone disease.","kind":"clinical","origin":"ai"},{"id":"fcp1-weakness-umn-lmn~ai-6","moduleId":"fcp1-weakness-umn-lmn","stem":"A 50-year-old male presents with progressive weakness and fasciculations. Reflexes are brisk in the arms and absent in the legs. Which condition should be considered?","options":[{"id":"a","text":"Cervical spondylotic myelopathy"},{"id":"b","text":"Motor neurone disease"},{"id":"c","text":"Guillain-Barré syndrome"},{"id":"d","text":"Myasthenia gravis"}],"answerId":"a","explanation":"Brisk reflexes in the arms and absent in the legs suggest cervical spondylotic myelopathy, which can present with mixed UMN and LMN signs.","kind":"integration","linkedModuleIds":["fcp1-weakness-localization"],"origin":"ai"}],"fcp1-weakness-localization":[{"id":"fcp1-weakness-localization~ai-0","moduleId":"fcp1-weakness-localization","stem":"A patient presents with weakness of the right arm and leg, lower facial droop, and aphasia. Where is the lesion most likely located?","options":[{"id":"a","text":"Left cortical/hemispheric region"},{"id":"b","text":"Right brainstem"},{"id":"c","text":"Left spinal cord"},{"id":"d","text":"Right peripheral nerve"}],"answerId":"a","explanation":"Contralateral cortical/hemispheric lesions cause weakness in the opposite side of the body along with cortical signs like aphasia.","kind":"recall","origin":"ai"},{"id":"fcp1-weakness-localization~ai-1","moduleId":"fcp1-weakness-localization","stem":"A patient exhibits bilateral leg weakness, a sensory level at T10, and urinary incontinence. What is the most likely diagnosis?","options":[{"id":"a","text":"Peripheral neuropathy"},{"id":"b","text":"Spinal cord compression"},{"id":"c","text":"Myopathy"},{"id":"d","text":"Cerebral stroke"}],"answerId":"b","explanation":"A sensory level and sphincter involvement suggest a spinal cord lesion, which requires urgent evaluation for compression.","kind":"clinical","origin":"ai"},{"id":"fcp1-weakness-localization~ai-2","moduleId":"fcp1-weakness-localization","stem":"A patient has distal weakness and loss of ankle reflexes. Which condition is most consistent with these findings?","options":[{"id":"a","text":"Myopathy"},{"id":"b","text":"Polyneuropathy"},{"id":"c","text":"Cerebral palsy"},{"id":"d","text":"Myasthenia gravis"}],"answerId":"b","explanation":"Distal weakness with loss of reflexes is characteristic of polyneuropathy.","kind":"mechanism","origin":"ai"},{"id":"fcp1-weakness-localization~ai-3","moduleId":"fcp1-weakness-localization","stem":"A patient reports worsening ptosis and diplopia throughout the day. Which condition is most likely?","options":[{"id":"a","text":"Multiple sclerosis"},{"id":"b","text":"Myasthenia gravis"},{"id":"c","text":"Guillain-Barré syndrome"},{"id":"d","text":"Parkinson's disease"}],"answerId":"b","explanation":"Fatigable ptosis and diplopia are classic signs of myasthenia gravis, a neuromuscular junction disorder.","kind":"recall","origin":"ai"},{"id":"fcp1-weakness-localization~ai-4","moduleId":"fcp1-weakness-localization","stem":"A patient presents with symmetrical proximal muscle weakness. Which of the following is the most likely cause?","options":[{"id":"a","text":"Myopathy"},{"id":"b","text":"Peripheral neuropathy"},{"id":"c","text":"Cerebral stroke"},{"id":"d","text":"Brainstem lesion"}],"answerId":"a","explanation":"Symmetrical proximal weakness is indicative of a myopathy.","kind":"recall","origin":"ai"},{"id":"fcp1-weakness-localization~ai-5","moduleId":"fcp1-weakness-localization","stem":"A patient has bilateral leg weakness with a sensory level and bladder involvement. Which module should you reference for further understanding of sensory patterns?","options":[{"id":"a","text":"fcp1-numbness-sensory"},{"id":"b","text":"fcp1-weakness-umn-lmn"},{"id":"c","text":"fcp1-weakness-localization"},{"id":"d","text":"fcp1-neuromuscular-junction"}],"answerId":"a","explanation":"The 'Numbness & Sensory Patterns' module provides insights into sensory levels and patterns.","kind":"integration","linkedModuleIds":["fcp1-numbness-sensory"],"origin":"ai"},{"id":"fcp1-weakness-localization~ai-6","moduleId":"fcp1-weakness-localization","stem":"A patient has weakness in the left arm and leg with increased tone and brisk reflexes. Which module would help differentiate between UMN and LMN lesions?","options":[{"id":"a","text":"fcp1-numbness-sensory"},{"id":"b","text":"fcp1-weakness-umn-lmn"},{"id":"c","text":"fcp1-weakness-localization"},{"id":"d","text":"fcp1-neuromuscular-junction"}],"answerId":"b","explanation":"The 'Weakness — UMN vs LMN' module helps differentiate between upper and lower motor neuron lesions.","kind":"integration","linkedModuleIds":["fcp1-weakness-umn-lmn"],"origin":"ai"}],"fcp1-numbness-sensory":[{"id":"fcp1-numbness-sensory~ai-0","moduleId":"fcp1-numbness-sensory","stem":"A patient presents with symmetrical numbness and tingling in the hands and feet, with loss of sensation up to the mid-calf. What is the most likely diagnosis?","options":[{"id":"a","text":"Polyneuropathy"},{"id":"b","text":"Radiculopathy"},{"id":"c","text":"Mononeuropathy"},{"id":"d","text":"Cerebral cortex lesion"}],"answerId":"a","explanation":"Symmetrical distal sensory loss suggests a length-dependent polyneuropathy.","kind":"recall","origin":"ai"},{"id":"fcp1-numbness-sensory~ai-1","moduleId":"fcp1-numbness-sensory","stem":"Which sensory pattern is indicative of a spinal cord lesion?","options":[{"id":"a","text":"Glove-and-stocking"},{"id":"b","text":"Dermatomal"},{"id":"c","text":"Single-nerve territory"},{"id":"d","text":"Sensory level on the trunk"}],"answerId":"d","explanation":"A sensory level on the trunk indicates a spinal cord lesion.","kind":"mechanism","origin":"ai"},{"id":"fcp1-numbness-sensory~ai-2","moduleId":"fcp1-numbness-sensory","stem":"A patient with bilateral sciatica and new urinary incontinence should be evaluated for which condition?","options":[{"id":"a","text":"Lumbar radiculopathy"},{"id":"b","text":"Cauda equina syndrome"},{"id":"c","text":"Peripheral neuropathy"},{"id":"d","text":"Cerebral infarction"}],"answerId":"b","explanation":"New urinary incontinence with bilateral sciatica suggests cauda equina syndrome, a surgical emergency.","kind":"trap","origin":"ai"},{"id":"fcp1-numbness-sensory~ai-3","moduleId":"fcp1-numbness-sensory","stem":"A patient presents with loss of pain and temperature sensation but preserved proprioception. Which condition is most likely?","options":[{"id":"a","text":"Brown-Séquard syndrome"},{"id":"b","text":"Polyneuropathy"},{"id":"c","text":"Thalamic stroke"},{"id":"d","text":"Mononeuropathy"}],"answerId":"a","explanation":"Dissociated sensory loss with preserved proprioception is characteristic of Brown-Séquard syndrome.","kind":"clinical","origin":"ai"},{"id":"fcp1-numbness-sensory~ai-4","moduleId":"fcp1-numbness-sensory","stem":"A patient has hemisensory loss affecting the right side of the body. Where is the most likely location of the lesion?","options":[{"id":"a","text":"Left thalamus"},{"id":"b","text":"Right thalamus"},{"id":"c","text":"Left cerebellum"},{"id":"d","text":"Right cerebellum"}],"answerId":"a","explanation":"Hemisensory loss on one side of the body suggests a lesion in the contralateral thalamus.","kind":"clinical","origin":"ai"},{"id":"fcp1-numbness-sensory~ai-5","moduleId":"fcp1-numbness-sensory","stem":"A patient presents with saddle anesthesia and urinary retention. What is the most appropriate next step?","options":[{"id":"a","text":"Schedule outpatient MRI"},{"id":"b","text":"Administer corticosteroids"},{"id":"c","text":"Immediate MRI and surgical consultation"},{"id":"d","text":"Physical therapy referral"}],"answerId":"c","explanation":"Saddle anesthesia with urinary retention indicates cauda equina syndrome, requiring immediate MRI and surgical consultation.","kind":"trap","origin":"ai"},{"id":"fcp1-numbness-sensory~ai-6","moduleId":"fcp1-numbness-sensory","stem":"A patient with a spinal cord lesion at T10 presents with a sensory level at the umbilicus. Which dermatome is affected?","options":[{"id":"a","text":"T8"},{"id":"b","text":"T10"},{"id":"c","text":"T12"},{"id":"d","text":"L1"}],"answerId":"b","explanation":"The umbilicus corresponds to the T10 dermatome.","kind":"integration","linkedModuleIds":["dermatomes-spinal-nerves"],"origin":"ai"},{"id":"fcp1-numbness-sensory~ai-7","moduleId":"fcp1-numbness-sensory","stem":"A patient presents with weakness and sensory loss in a glove-and-stocking distribution. Which condition should be considered first?","options":[{"id":"a","text":"Multiple sclerosis"},{"id":"b","text":"Diabetes mellitus"},{"id":"c","text":"Cerebral infarction"},{"id":"d","text":"Myasthenia gravis"}],"answerId":"b","explanation":"Diabetes mellitus is a common cause of polyneuropathy, presenting with a glove-and-stocking distribution.","kind":"integration","linkedModuleIds":["fcp1-weakness-localization"],"origin":"ai"}],"fcp1-pediatric-seizures":[{"id":"fcp1-pediatric-seizures~ai-0","moduleId":"fcp1-pediatric-seizures","stem":"A 3-year-old child presents with a generalized seizure lasting 10 minutes during a fever of 39°C. The child returns to baseline after the seizure. What is the most appropriate management?","options":[{"id":"a","text":"Reassure the parents and discharge"},{"id":"b","text":"Order an EEG"},{"id":"c","text":"Perform a lumbar puncture"},{"id":"d","text":"Start antiepileptic medication"}],"answerId":"a","explanation":"This is a simple febrile seizure, which is benign and requires reassurance and discharge without further investigations.","kind":"clinical","origin":"ai"},{"id":"fcp1-pediatric-seizures~ai-1","moduleId":"fcp1-pediatric-seizures","stem":"Which of the following features would suggest a complex febrile seizure rather than a simple febrile seizure?","options":[{"id":"a","text":"Seizure lasting 10 minutes"},{"id":"b","text":"Generalized tonic-clonic movements"},{"id":"c","text":"Recurrent seizures within 24 hours"},{"id":"d","text":"Seizure occurring with fever in a 4-year-old"}],"answerId":"c","explanation":"Complex febrile seizures are characterized by focal features, duration ≥15 minutes, or recurrence within 24 hours.","kind":"recall","origin":"ai"},{"id":"fcp1-pediatric-seizures~ai-2","moduleId":"fcp1-pediatric-seizures","stem":"A 9-month-old infant presents with fever, irritability, and a bulging fontanelle. What is the most appropriate next step?","options":[{"id":"a","text":"Administer antipyretics and observe"},{"id":"b","text":"Perform a lumbar puncture"},{"id":"c","text":"Order a CT scan of the head"},{"id":"d","text":"Discharge with reassurance"}],"answerId":"b","explanation":"The presence of a bulging fontanelle and fever suggests possible meningitis, warranting a lumbar puncture.","kind":"clinical","origin":"ai"},{"id":"fcp1-pediatric-seizures~ai-3","moduleId":"fcp1-pediatric-seizures","stem":"Parents of a child with a history of febrile seizures ask if regular antipyretics will prevent future seizures. What should you tell them?","options":[{"id":"a","text":"Regular antipyretics will prevent seizures"},{"id":"b","text":"Antipyretics reduce fever but do not prevent seizures"},{"id":"c","text":"Antipyretics should be avoided"},{"id":"d","text":"Antipyretics are only for children over 5 years"}],"answerId":"b","explanation":"Antipyretics improve comfort but do not prevent febrile seizure recurrence.","kind":"trap","origin":"ai"},{"id":"fcp1-pediatric-seizures~ai-4","moduleId":"fcp1-pediatric-seizures","stem":"A 7-month-old presents with clusters of flexor spasms and developmental regression. Which condition is most likely?","options":[{"id":"a","text":"Benign rolandic epilepsy"},{"id":"b","text":"Infantile spasms (West syndrome)"},{"id":"c","text":"Childhood absence epilepsy"},{"id":"d","text":"Juvenile myoclonic epilepsy"}],"answerId":"b","explanation":"Infantile spasms (West syndrome) present with clusters of spasms and developmental regression, requiring urgent referral.","kind":"recall","origin":"ai"},{"id":"fcp1-pediatric-seizures~ai-5","moduleId":"fcp1-pediatric-seizures","stem":"A child with fever and seizure is evaluated. Which finding would most strongly suggest a need to evaluate for meningitis?","options":[{"id":"a","text":"Fever of 38.5°C"},{"id":"b","text":"Seizure lasting 5 minutes"},{"id":"c","text":"Petechial rash"},{"id":"d","text":"Return to baseline after seizure"}],"answerId":"c","explanation":"A petechial rash is a red flag for meningitis, necessitating further investigation.","kind":"clinical","origin":"ai"},{"id":"fcp1-pediatric-seizures~ai-6","moduleId":"fcp1-pediatric-seizures","stem":"A 2-year-old with fever and seizure is found to have neutrophilia on a CBC. Which linked module could help understand this finding?","options":[{"id":"a","text":"fcp1-fever-approach-differential"},{"id":"b","text":"history-ancient-to-renaissance"},{"id":"c","text":"hhl-leukocyte-quantitative"},{"id":"d","text":"fcp1-seizure-classification"}],"answerId":"c","explanation":"The 'hhl-leukocyte-quantitative' module covers neutrophilia, which can occur in response to infection.","kind":"integration","linkedModuleIds":["hhl-leukocyte-quantitative"],"origin":"ai"},{"id":"fcp1-pediatric-seizures~ai-7","moduleId":"fcp1-pediatric-seizures","stem":"In a child with fever and seizures, which linked module would assist in differentiating between seizure and its mimics?","options":[{"id":"a","text":"fcp1-seizure-vs-mimics"},{"id":"b","text":"hhl-febrile-allergic-reactions"},{"id":"c","text":"fcp1-seizure-classification"},{"id":"d","text":"fcp1-fever-approach-differential"}],"answerId":"a","explanation":"The 'fcp1-seizure-vs-mimics' module helps differentiate between seizures and conditions that mimic seizures.","kind":"integration","linkedModuleIds":["fcp1-seizure-vs-mimics"],"origin":"ai"}],"fcp1-movement-hypokinetic-parkinsonism":[{"id":"fcp1-movement-hypokinetic-parkinsonism~ai-0","moduleId":"fcp1-movement-hypokinetic-parkinsonism","stem":"A 65-year-old man presents with bradykinesia, rigidity, and a 4–6 Hz rest tremor. Which feature most strongly suggests idiopathic Parkinson disease?","options":[{"id":"a","text":"Asymmetric onset"},{"id":"b","text":"Symmetric onset"},{"id":"c","text":"Early autonomic failure"},{"id":"d","text":"Rapid progression"}],"answerId":"a","explanation":"Asymmetric onset is characteristic of idiopathic Parkinson disease, while symmetric onset suggests a secondary cause.","kind":"recall","origin":"ai"},{"id":"fcp1-movement-hypokinetic-parkinsonism~ai-1","moduleId":"fcp1-movement-hypokinetic-parkinsonism","stem":"Which bedside sign is most indicative of parkinsonism?","options":[{"id":"a","text":"Masked facies"},{"id":"b","text":"Positive glabellar tap"},{"id":"c","text":"Micrographia"},{"id":"d","text":"Finger-tapping that gets slower and smaller"}],"answerId":"d","explanation":"Finger-tapping that gets slower and smaller demonstrates bradykinesia with decrement, the defining feature of parkinsonism.","kind":"recall","origin":"ai"},{"id":"fcp1-movement-hypokinetic-parkinsonism~ai-2","moduleId":"fcp1-movement-hypokinetic-parkinsonism","stem":"A patient on metoclopramide develops symmetric parkinsonism. What is the most appropriate next step?","options":[{"id":"a","text":"Start levodopa"},{"id":"b","text":"Discontinue metoclopramide"},{"id":"c","text":"Order a DaT scan"},{"id":"d","text":"Refer for deep brain stimulation"}],"answerId":"b","explanation":"Discontinuing metoclopramide can reverse drug-induced parkinsonism, which is often symmetric.","kind":"trap","origin":"ai"},{"id":"fcp1-movement-hypokinetic-parkinsonism~ai-3","moduleId":"fcp1-movement-hypokinetic-parkinsonism","stem":"Which condition is suggested by early recurrent falls and impaired vertical gaze?","options":[{"id":"a","text":"Idiopathic Parkinson disease"},{"id":"b","text":"Progressive supranuclear palsy"},{"id":"c","text":"Multiple system atrophy"},{"id":"d","text":"Dementia with Lewy bodies"}],"answerId":"b","explanation":"Early falls with impaired vertical gaze suggest progressive supranuclear palsy, not idiopathic Parkinson disease.","kind":"clinical","origin":"ai"},{"id":"fcp1-movement-hypokinetic-parkinsonism~ai-4","moduleId":"fcp1-movement-hypokinetic-parkinsonism","stem":"A 70-year-old woman presents with bradykinesia and a rest tremor. She also has early dementia with visual hallucinations. What is the likely diagnosis?","options":[{"id":"a","text":"Idiopathic Parkinson disease"},{"id":"b","text":"Dementia with Lewy bodies"},{"id":"c","text":"Multiple system atrophy"},{"id":"d","text":"Vascular parkinsonism"}],"answerId":"b","explanation":"Early dementia with visual hallucinations and fluctuations suggests dementia with Lewy bodies.","kind":"clinical","linkedModuleIds":["fcp1-delirium-vs-dementia"],"origin":"ai"},{"id":"fcp1-movement-hypokinetic-parkinsonism~ai-5","moduleId":"fcp1-movement-hypokinetic-parkinsonism","stem":"Which of the following is a common reversible cause of parkinsonism?","options":[{"id":"a","text":"Idiopathic Parkinson disease"},{"id":"b","text":"Drug-induced parkinsonism"},{"id":"c","text":"Progressive supranuclear palsy"},{"id":"d","text":"Multiple system atrophy"}],"answerId":"b","explanation":"Drug-induced parkinsonism is the most common reversible cause, often due to dopamine antagonists.","kind":"recall","origin":"ai"},{"id":"fcp1-movement-hypokinetic-parkinsonism~ai-6","moduleId":"fcp1-movement-hypokinetic-parkinsonism","stem":"A patient with parkinsonism has a DaT scan showing normal dopamine transporter activity. Which condition is least likely?","options":[{"id":"a","text":"Idiopathic Parkinson disease"},{"id":"b","text":"Drug-induced parkinsonism"},{"id":"c","text":"Vascular parkinsonism"},{"id":"d","text":"Multiple system atrophy"}],"answerId":"a","explanation":"Normal dopamine transporter activity on a DaT scan suggests against idiopathic Parkinson disease.","kind":"mechanism","origin":"ai"},{"id":"fcp1-movement-hypokinetic-parkinsonism~ai-7","moduleId":"fcp1-movement-hypokinetic-parkinsonism","stem":"A 68-year-old man with Parkinson disease is experiencing worsening symptoms. Which medication class could be considered to enhance his therapy?","options":[{"id":"a","text":"Dopamine antagonists"},{"id":"b","text":"Dopamine agonists"},{"id":"c","text":"Antipsychotics"},{"id":"d","text":"Anticholinergics"}],"answerId":"b","explanation":"Dopamine agonists can be used to enhance therapy in Parkinson disease by stimulating dopamine receptors.","kind":"integration","linkedModuleIds":["dopamine-agonists-antimuscarinics"],"origin":"ai"}],"fcp1-seizure-classification":[{"id":"fcp1-seizure-classification~ai-0","moduleId":"fcp1-seizure-classification","stem":"A 25-year-old woman experiences a sudden sensation of a rising epigastric feeling followed by lip-smacking and fumbling. She is confused post-event. What type of seizure is most likely?","options":[{"id":"a","text":"Focal impaired-awareness seizure"},{"id":"b","text":"Generalised tonic-clonic seizure"},{"id":"c","text":"Absence seizure"},{"id":"d","text":"Myoclonic seizure"}],"answerId":"a","explanation":"The rising epigastric aura and automatisms suggest a focal impaired-awareness seizure, often originating from the temporal lobe.","kind":"clinical","origin":"ai"},{"id":"fcp1-seizure-classification~ai-1","moduleId":"fcp1-seizure-classification","stem":"Which of the following is a key feature distinguishing a true seizure from its mimics?","options":[{"id":"a","text":"Lateral tongue-biting"},{"id":"b","text":"Immediate full recovery"},{"id":"c","text":"No post-ictal confusion"},{"id":"d","text":"Bilateral limb movement"}],"answerId":"a","explanation":"Lateral tongue-biting is a discriminator favoring a true seizure.","kind":"recall","origin":"ai"},{"id":"fcp1-seizure-classification~ai-2","moduleId":"fcp1-seizure-classification","stem":"A patient presents with a single seizure after heavy alcohol consumption. What is the appropriate management?","options":[{"id":"a","text":"Start long-term antiepileptic drugs"},{"id":"b","text":"Treat with benzodiazepines and monitor"},{"id":"c","text":"Correct the underlying cause"},{"id":"d","text":"Diagnose epilepsy"}],"answerId":"c","explanation":"This is a provoked seizure due to alcohol withdrawal, so the underlying cause should be corrected.","kind":"trap","origin":"ai"},{"id":"fcp1-seizure-classification~ai-3","moduleId":"fcp1-seizure-classification","stem":"A 10-year-old boy has episodes of brief staring spells with no post-ictal confusion. What type of seizure is this?","options":[{"id":"a","text":"Focal aware seizure"},{"id":"b","text":"Generalised tonic-clonic seizure"},{"id":"c","text":"Absence seizure"},{"id":"d","text":"Atonic seizure"}],"answerId":"c","explanation":"The brief staring spells without post-ictal confusion are characteristic of absence seizures.","kind":"recall","origin":"ai"},{"id":"fcp1-seizure-classification~ai-4","moduleId":"fcp1-seizure-classification","stem":"A patient with a history of epilepsy presents with a seizure lasting over 5 minutes. What is the immediate management priority?","options":[{"id":"a","text":"Administer benzodiazepines"},{"id":"b","text":"Perform a CT scan"},{"id":"c","text":"Start long-term antiepileptic drugs"},{"id":"d","text":"Monitor vital signs only"}],"answerId":"a","explanation":"Status epilepticus requires immediate administration of benzodiazepines.","kind":"clinical","origin":"ai"},{"id":"fcp1-seizure-classification~ai-5","moduleId":"fcp1-seizure-classification","stem":"Which mechanism explains Todd paresis following a seizure?","options":[{"id":"a","text":"Post-ictal exhaustion of the seizing cortex"},{"id":"b","text":"Increased intracranial pressure"},{"id":"c","text":"Transient ischemic attack"},{"id":"d","text":"Peripheral nerve injury"}],"answerId":"a","explanation":"Todd paresis is due to post-ictal exhaustion of the seizing cortex.","kind":"mechanism","origin":"ai"},{"id":"fcp1-seizure-classification~ai-6","moduleId":"fcp1-seizure-classification","stem":"A 3-year-old child presents with a febrile seizure. Which linked module provides additional information on this condition?","options":[{"id":"a","text":"AEDs — Sodium Channel Blockers"},{"id":"b","text":"Altered Consciousness & Coma: Approach"},{"id":"c","text":"Paediatric Seizures & Febrile Seizures"},{"id":"d","text":"Seizure vs Its Mimics"}],"answerId":"c","explanation":"The 'Paediatric Seizures & Febrile Seizures' module provides information on febrile seizures.","kind":"integration","linkedModuleIds":["fcp1-pediatric-seizures"],"origin":"ai"},{"id":"fcp1-seizure-classification~ai-7","moduleId":"fcp1-seizure-classification","stem":"A patient is being evaluated for altered consciousness post-seizure. Which linked module should be consulted for further assessment?","options":[{"id":"a","text":"AEDs — Sodium Channel Blockers"},{"id":"b","text":"Altered Consciousness & Coma: Approach"},{"id":"c","text":"Paediatric Seizures & Febrile Seizures"},{"id":"d","text":"Seizure vs Its Mimics"}],"answerId":"b","explanation":"The 'Altered Consciousness & Coma: Approach' module is relevant for assessing post-seizure altered consciousness.","kind":"integration","linkedModuleIds":["fcp1-consciousness-coma-approach"],"origin":"ai"}],"fcp1-movement-hyperkinetic":[{"id":"fcp1-movement-hyperkinetic~ai-0","moduleId":"fcp1-movement-hyperkinetic","stem":"A 45-year-old woman presents with a bilateral action tremor that improves with alcohol consumption. Her father had a similar condition. What is the most likely diagnosis?","options":[{"id":"a","text":"Essential tremor"},{"id":"b","text":"Parkinson's disease"},{"id":"c","text":"Cerebellar tremor"},{"id":"d","text":"Physiological tremor"}],"answerId":"a","explanation":"Essential tremor is characterized by a bilateral action tremor that often improves with alcohol and has a familial pattern.","kind":"recall","origin":"ai"},{"id":"fcp1-movement-hyperkinetic~ai-1","moduleId":"fcp1-movement-hyperkinetic","stem":"A patient presents with sudden, brief, shock-like muscle jerks. Which of the following is the most likely diagnosis?","options":[{"id":"a","text":"Chorea"},{"id":"b","text":"Dystonia"},{"id":"c","text":"Myoclonus"},{"id":"d","text":"Tics"}],"answerId":"c","explanation":"Myoclonus is characterized by sudden, brief, shock-like muscle jerks.","kind":"recall","origin":"ai"},{"id":"fcp1-movement-hyperkinetic~ai-2","moduleId":"fcp1-movement-hyperkinetic","stem":"A 20-year-old male has repetitive, stereotyped movements and vocalizations that he can suppress temporarily. What is the most likely diagnosis?","options":[{"id":"a","text":"Tourette syndrome"},{"id":"b","text":"Huntington's disease"},{"id":"c","text":"Wilson's disease"},{"id":"d","text":"Parkinson's disease"}],"answerId":"a","explanation":"Tourette syndrome is characterized by motor and vocal tics that are suppressible and often preceded by an urge.","kind":"clinical","origin":"ai"},{"id":"fcp1-movement-hyperkinetic~ai-3","moduleId":"fcp1-movement-hyperkinetic","stem":"A patient develops neck arching and eye rolling after taking metoclopramide. What is the appropriate management?","options":[{"id":"a","text":"Administer an anticholinergic"},{"id":"b","text":"Administer a benzodiazepine"},{"id":"c","text":"Administer a beta-blocker"},{"id":"d","text":"Administer a dopamine agonist"}],"answerId":"a","explanation":"This is an acute dystonic reaction to a dopamine antagonist, best treated with an anticholinergic.","kind":"trap","origin":"ai"},{"id":"fcp1-movement-hyperkinetic~ai-4","moduleId":"fcp1-movement-hyperkinetic","stem":"A 35-year-old woman presents with brief, irregular, unpredictable movements that flit between her limbs and face. What is the most likely underlying mechanism?","options":[{"id":"a","text":"Altered basal-ganglia output"},{"id":"b","text":"Cerebellar dysfunction"},{"id":"c","text":"Peripheral nerve hyperactivity"},{"id":"d","text":"Spinal cord lesion"}],"answerId":"a","explanation":"Chorea is caused by altered basal-ganglia output, leading to brief, irregular movements.","kind":"mechanism","origin":"ai"},{"id":"fcp1-movement-hyperkinetic~ai-5","moduleId":"fcp1-movement-hyperkinetic","stem":"A patient with hyperthyroidism presents with a tremor. Which type of tremor is most likely associated with this condition?","options":[{"id":"a","text":"Rest tremor"},{"id":"b","text":"Postural/action tremor"},{"id":"c","text":"Intention tremor"},{"id":"d","text":"Chorea"}],"answerId":"b","explanation":"Hyperthyroidism is commonly associated with a postural/action tremor.","kind":"integration","linkedModuleIds":["fcp1-hyperthyroidism"],"origin":"ai"},{"id":"fcp1-movement-hyperkinetic~ai-6","moduleId":"fcp1-movement-hyperkinetic","stem":"A 60-year-old man presents with bradykinesia and a resting tremor. Which hyperkinetic movement disorder should be considered in the differential diagnosis?","options":[{"id":"a","text":"Essential tremor"},{"id":"b","text":"Chorea"},{"id":"c","text":"Dystonia"},{"id":"d","text":"Tics"}],"answerId":"b","explanation":"Chorea should be considered as it can present with overlapping features with hypokinetic disorders like Parkinsonism.","kind":"integration","linkedModuleIds":["fcp1-movement-hypokinetic-parkinsonism"],"origin":"ai"}],"fcp1-seizure-vs-mimics":[{"id":"fcp1-seizure-vs-mimics~ai-0","moduleId":"fcp1-seizure-vs-mimics","stem":"A 25-year-old woman experiences a sudden loss of consciousness while standing in a crowded train. She reports feeling light-headed and sweaty before collapsing. Witnesses describe brief jerking movements during the event. What is the most likely diagnosis?","options":[{"id":"a","text":"Epileptic seizure"},{"id":"b","text":"Reflex syncope"},{"id":"c","text":"Psychogenic non-epileptic seizure"},{"id":"d","text":"Cardiac syncope"}],"answerId":"b","explanation":"The autonomic prodrome and rapid recovery suggest reflex syncope, despite brief jerking.","kind":"clinical","origin":"ai"},{"id":"fcp1-seizure-vs-mimics~ai-1","moduleId":"fcp1-seizure-vs-mimics","stem":"Which of the following findings is most suggestive of a psychogenic non-epileptic seizure?","options":[{"id":"a","text":"Lateral tongue-biting"},{"id":"b","text":"Prolonged post-ictal confusion"},{"id":"c","text":"Resisted eye-opening"},{"id":"d","text":"Cyanosis during the event"}],"answerId":"c","explanation":"Resisted eye-opening is a common sign of a psychogenic non-epileptic event.","kind":"recall","origin":"ai"},{"id":"fcp1-seizure-vs-mimics~ai-2","moduleId":"fcp1-seizure-vs-mimics","stem":"A 30-year-old man collapses while jogging and has no prodromal symptoms. What is the most appropriate next step in management?","options":[{"id":"a","text":"EEG"},{"id":"b","text":"Tilt-table test"},{"id":"c","text":"ECG"},{"id":"d","text":"Video-EEG monitoring"}],"answerId":"c","explanation":"Syncope during exertion without prodrome suggests cardiac syncope; an ECG is essential.","kind":"trap","origin":"ai"},{"id":"fcp1-seizure-vs-mimics~ai-3","moduleId":"fcp1-seizure-vs-mimics","stem":"A patient presents with a history of transient loss of consciousness. Which feature would most strongly suggest an epileptic seizure?","options":[{"id":"a","text":"Brief collapse with rapid recovery"},{"id":"b","text":"Aura before the event"},{"id":"c","text":"Eyes closed during the event"},{"id":"d","text":"Ictal weeping"}],"answerId":"b","explanation":"An aura is a common precursor to an epileptic seizure.","kind":"recall","origin":"ai"},{"id":"fcp1-seizure-vs-mimics~ai-4","moduleId":"fcp1-seizure-vs-mimics","stem":"A 40-year-old woman has episodes of loss of consciousness with side-to-side head movements and preserved awareness. What is the most likely diagnosis?","options":[{"id":"a","text":"Epileptic seizure"},{"id":"b","text":"Reflex syncope"},{"id":"c","text":"Psychogenic non-epileptic seizure"},{"id":"d","text":"Cardiac syncope"}],"answerId":"c","explanation":"Preserved awareness and side-to-side head movements suggest a psychogenic non-epileptic seizure.","kind":"clinical","origin":"ai"},{"id":"fcp1-seizure-vs-mimics~ai-5","moduleId":"fcp1-seizure-vs-mimics","stem":"A 50-year-old man experiences transient loss of consciousness while urinating. What is the most likely diagnosis?","options":[{"id":"a","text":"Epileptic seizure"},{"id":"b","text":"Reflex syncope"},{"id":"c","text":"Psychogenic non-epileptic seizure"},{"id":"d","text":"Cardiac syncope"}],"answerId":"b","explanation":"Micturition syncope is a type of reflex syncope triggered by urination.","kind":"integration","linkedModuleIds":["fcp1-syncope-approach"],"origin":"ai"},{"id":"fcp1-seizure-vs-mimics~ai-6","moduleId":"fcp1-seizure-vs-mimics","stem":"In a patient with suspected epilepsy, which feature would be least likely to occur in a true epileptic seizure?","options":[{"id":"a","text":"Lateral tongue-biting"},{"id":"b","text":"Prolonged post-ictal confusion"},{"id":"c","text":"Asynchronous limb movements"},{"id":"d","text":"Cyanosis during the event"}],"answerId":"c","explanation":"Asynchronous limb movements are more characteristic of psychogenic non-epileptic seizures.","kind":"trap","origin":"ai"},{"id":"fcp1-seizure-vs-mimics~ai-7","moduleId":"fcp1-seizure-vs-mimics","stem":"A 10-year-old child presents with a history of febrile seizures. Which of the following is most likely to differentiate these from other seizure types?","options":[{"id":"a","text":"Aura before the seizure"},{"id":"b","text":"Prolonged post-ictal confusion"},{"id":"c","text":"Seizure duration less than 15 minutes"},{"id":"d","text":"Lateral tongue-biting"}],"answerId":"c","explanation":"Febrile seizures are typically brief and last less than 15 minutes.","kind":"integration","linkedModuleIds":["fcp1-pediatric-seizures"],"origin":"ai"}],"fcp1-delirium-vs-dementia":[{"id":"fcp1-delirium-vs-dementia~ai-0","moduleId":"fcp1-delirium-vs-dementia","stem":"A 75-year-old woman is brought to the emergency department with confusion and agitation that started suddenly. She has difficulty focusing and her symptoms fluctuate throughout the day. What is the most likely diagnosis?","options":[{"id":"a","text":"Delirium"},{"id":"b","text":"Dementia"},{"id":"c","text":"Depression"},{"id":"d","text":"Schizophrenia"}],"answerId":"a","explanation":"The acute onset and fluctuating course with inattention are characteristic of delirium.","kind":"clinical","origin":"ai"},{"id":"fcp1-delirium-vs-dementia~ai-1","moduleId":"fcp1-delirium-vs-dementia","stem":"Which of the following is a common reversible cause of delirium in hospitalized patients?","options":[{"id":"a","text":"Anticholinergic medications"},{"id":"b","text":"Genetic predisposition"},{"id":"c","text":"Chronic hypertension"},{"id":"d","text":"Long-standing diabetes"}],"answerId":"a","explanation":"Drugs, particularly anticholinergics, are a common reversible cause of delirium.","kind":"recall","origin":"ai"},{"id":"fcp1-delirium-vs-dementia~ai-2","moduleId":"fcp1-delirium-vs-dementia","stem":"A patient with known dementia presents with new onset confusion and fluctuating alertness. What should be the next step in management?","options":[{"id":"a","text":"Start antipsychotic medication"},{"id":"b","text":"Investigate for reversible causes"},{"id":"c","text":"Increase dementia medication dosage"},{"id":"d","text":"Refer to psychiatry"}],"answerId":"b","explanation":"New onset confusion in a dementia patient suggests superimposed delirium; search for reversible causes.","kind":"clinical","origin":"ai"},{"id":"fcp1-delirium-vs-dementia~ai-3","moduleId":"fcp1-delirium-vs-dementia","stem":"A 68-year-old man is quiet, withdrawn, and disoriented. He is known to have depression. What is the most appropriate action?","options":[{"id":"a","text":"Increase antidepressant dosage"},{"id":"b","text":"Screen for delirium"},{"id":"c","text":"Start antipsychotic medication"},{"id":"d","text":"Discharge with follow-up"}],"answerId":"b","explanation":"Hypoactive delirium can mimic depression; screening for delirium is essential.","kind":"trap","origin":"ai"},{"id":"fcp1-delirium-vs-dementia~ai-4","moduleId":"fcp1-delirium-vs-dementia","stem":"Which of the following findings is most indicative of dementia rather than delirium?","options":[{"id":"a","text":"Acute onset of symptoms"},{"id":"b","text":"Fluctuating level of consciousness"},{"id":"c","text":"Progressive memory loss with clear consciousness"},{"id":"d","text":"Inattention and disorganized thinking"}],"answerId":"c","explanation":"Progressive memory loss with clear consciousness is characteristic of dementia.","kind":"mechanism","origin":"ai"},{"id":"fcp1-delirium-vs-dementia~ai-5","moduleId":"fcp1-delirium-vs-dementia","stem":"A patient presents with confusion, tremors, and sweating. Thyroid function tests reveal elevated T3 and T4 levels. Which condition is likely contributing to the patient's delirium?","options":[{"id":"a","text":"Hypothyroidism"},{"id":"b","text":"Hyperthyroidism"},{"id":"c","text":"Dementia"},{"id":"d","text":"Depression"}],"answerId":"b","explanation":"Hyperthyroidism can cause delirium due to increased metabolic activity and sympathetic overactivity.","kind":"integration","linkedModuleIds":["fcp1-hyperthyroidism"],"origin":"ai"},{"id":"fcp1-delirium-vs-dementia~ai-6","moduleId":"fcp1-delirium-vs-dementia","stem":"A 70-year-old male with a history of hypothyroidism presents with confusion and lethargy. His TSH level is elevated. What is the most likely cause of his delirium?","options":[{"id":"a","text":"Hyperthyroidism"},{"id":"b","text":"Hypothyroidism"},{"id":"c","text":"Dementia"},{"id":"d","text":"Depression"}],"answerId":"b","explanation":"Hypothyroidism can lead to metabolic disturbances contributing to delirium.","kind":"integration","linkedModuleIds":["fcp1-hypothyroidism"],"origin":"ai"}],"fcp1-consciousness-coma-approach":[{"id":"fcp1-consciousness-coma-approach~ai-0","moduleId":"fcp1-consciousness-coma-approach","stem":"A 45-year-old man is found unresponsive. His pupils are pinpoint but reactive. What is the most likely cause of his condition?","options":[{"id":"a","text":"Uncal herniation"},{"id":"b","text":"Pontine lesion"},{"id":"c","text":"Hypoglycemia"},{"id":"d","text":"Midbrain lesion"}],"answerId":"b","explanation":"Pinpoint but reactive pupils suggest a pontine lesion or opioid effect.","kind":"recall","origin":"ai"},{"id":"fcp1-consciousness-coma-approach~ai-1","moduleId":"fcp1-consciousness-coma-approach","stem":"Which of the following is the first step in managing an unresponsive patient in the emergency department?","options":[{"id":"a","text":"Perform a CT scan"},{"id":"b","text":"Administer naloxone"},{"id":"c","text":"Check capillary glucose"},{"id":"d","text":"Intubate the patient"}],"answerId":"c","explanation":"Checking capillary glucose is crucial as hypoglycemia can mimic a structural coma and is reversible.","kind":"trap","origin":"ai"},{"id":"fcp1-consciousness-coma-approach~ai-2","moduleId":"fcp1-consciousness-coma-approach","stem":"A patient presents with hypertension, bradycardia, and irregular respiration. What is the most likely underlying issue?","options":[{"id":"a","text":"Hypoglycemia"},{"id":"b","text":"Raised intracranial pressure"},{"id":"c","text":"Opioid overdose"},{"id":"d","text":"Pontine hemorrhage"}],"answerId":"b","explanation":"These findings are indicative of the Cushing response, suggesting raised intracranial pressure.","kind":"recall","origin":"ai"},{"id":"fcp1-consciousness-coma-approach~ai-3","moduleId":"fcp1-consciousness-coma-approach","stem":"A 60-year-old woman is brought to the hospital with altered mental status. She exhibits asterixis and has symmetric findings on examination. What is the most likely cause?","options":[{"id":"a","text":"Uncal herniation"},{"id":"b","text":"Metabolic encephalopathy"},{"id":"c","text":"Midbrain lesion"},{"id":"d","text":"Pontine lesion"}],"answerId":"b","explanation":"Asterixis with symmetric findings and reactive pupils suggests a metabolic or toxic encephalopathy.","kind":"mechanism","origin":"ai"},{"id":"fcp1-consciousness-coma-approach~ai-4","moduleId":"fcp1-consciousness-coma-approach","stem":"Which of the following is a red flag for neurosurgical emergency in a patient with altered consciousness?","options":[{"id":"a","text":"Bilateral pinpoint pupils"},{"id":"b","text":"Unilateral fixed, dilated pupil"},{"id":"c","text":"Symmetric reactive pupils"},{"id":"d","text":"Asterixis"}],"answerId":"b","explanation":"A unilateral fixed, dilated pupil indicates uncal herniation, a neurosurgical emergency.","kind":"recall","origin":"ai"},{"id":"fcp1-consciousness-coma-approach~ai-5","moduleId":"fcp1-consciousness-coma-approach","stem":"A patient with altered consciousness is suspected to have non-convulsive status epilepticus. Which linked module would provide further classification of this condition?","options":[{"id":"a","text":"fcp1-seizure-classification"},{"id":"b","text":"fcp1-shock-classification"},{"id":"c","text":"fcp1-hypothyroidism"},{"id":"d","text":"fcp1-delirium-vs-dementia"}],"answerId":"a","explanation":"The 'fcp1-seizure-classification' module provides details on seizure types, including non-convulsive status.","kind":"integration","linkedModuleIds":["fcp1-seizure-classification"],"origin":"ai"},{"id":"fcp1-consciousness-coma-approach~ai-6","moduleId":"fcp1-consciousness-coma-approach","stem":"In a patient with altered mental status, which module would assist in differentiating between delirium and dementia?","options":[{"id":"a","text":"fcp1-seizure-classification"},{"id":"b","text":"fcp1-delirium-vs-dementia"},{"id":"c","text":"fcp1-shock-classification"},{"id":"d","text":"fcp1-hypothyroidism"}],"answerId":"b","explanation":"The 'fcp1-delirium-vs-dementia' module helps differentiate between these two conditions.","kind":"integration","linkedModuleIds":["fcp1-delirium-vs-dementia"],"origin":"ai"}],"fcp1-cognitive-assessment":[{"id":"fcp1-cognitive-assessment~ai-0","moduleId":"fcp1-cognitive-assessment","stem":"A 75-year-old patient presents with insidious onset of memory loss and preserved social manners. Which type of dementia is most likely?","options":[{"id":"a","text":"Alzheimer disease"},{"id":"b","text":"Vascular dementia"},{"id":"c","text":"Dementia with Lewy bodies"},{"id":"d","text":"Frontotemporal dementia"}],"answerId":"a","explanation":"Early loss of episodic memory with preserved social manner is typical of Alzheimer disease.","kind":"recall","origin":"ai"},{"id":"fcp1-cognitive-assessment~ai-1","moduleId":"fcp1-cognitive-assessment","stem":"Which cognitive assessment tool is more sensitive to mild cognitive impairment and executive/visuospatial deficits?","options":[{"id":"a","text":"MMSE"},{"id":"b","text":"MoCA"},{"id":"c","text":"Mini-Cog"},{"id":"d","text":"AMT"}],"answerId":"b","explanation":"The MoCA is more sensitive to mild cognitive impairment and captures executive/visuospatial deficits better than the MMSE.","kind":"recall","origin":"ai"},{"id":"fcp1-cognitive-assessment~ai-2","moduleId":"fcp1-cognitive-assessment","stem":"A patient with fluctuating cognition, visual hallucinations, and parkinsonism is most likely suffering from which condition?","options":[{"id":"a","text":"Alzheimer disease"},{"id":"b","text":"Vascular dementia"},{"id":"c","text":"Dementia with Lewy bodies"},{"id":"d","text":"Frontotemporal dementia"}],"answerId":"c","explanation":"Fluctuating cognition with visual hallucinations and parkinsonism suggests dementia with Lewy bodies.","kind":"recall","origin":"ai"},{"id":"fcp1-cognitive-assessment~ai-3","moduleId":"fcp1-cognitive-assessment","stem":"A 68-year-old patient presents with early gait disturbance, urinary incontinence, and cognitive decline. What is the most likely diagnosis?","options":[{"id":"a","text":"Alzheimer disease"},{"id":"b","text":"Normal-pressure hydrocephalus"},{"id":"c","text":"Vascular dementia"},{"id":"d","text":"Frontotemporal dementia"}],"answerId":"b","explanation":"Early gait disturbance and urinary incontinence with cognitive decline suggest normal-pressure hydrocephalus, a potentially reversible cause.","kind":"recall","origin":"ai"},{"id":"fcp1-cognitive-assessment~ai-4","moduleId":"fcp1-cognitive-assessment","stem":"In a patient with low mood and poor cognitive test scores, what should be considered before diagnosing dementia?","options":[{"id":"a","text":"Confirm irreversible dementia"},{"id":"b","text":"Screen for depression"},{"id":"c","text":"Start dementia medication"},{"id":"d","text":"Order a brain biopsy"}],"answerId":"b","explanation":"Depression can mimic dementia (pseudodementia), and cognition may recover with treatment.","kind":"trap","origin":"ai"},{"id":"fcp1-cognitive-assessment~ai-5","moduleId":"fcp1-cognitive-assessment","stem":"Which laboratory test is NOT typically part of the initial workup for reversible causes of dementia?","options":[{"id":"a","text":"TSH"},{"id":"b","text":"B12"},{"id":"c","text":"Calcium"},{"id":"d","text":"Troponin"}],"answerId":"d","explanation":"Troponin is not part of the standard workup for reversible causes of dementia.","kind":"recall","origin":"ai"},{"id":"fcp1-cognitive-assessment~ai-6","moduleId":"fcp1-cognitive-assessment","stem":"A patient with Parkinsonism and cognitive decline is suspected of having dementia with Lewy bodies. Which symptom would support this diagnosis?","options":[{"id":"a","text":"Episodic memory loss"},{"id":"b","text":"Visual hallucinations"},{"id":"c","text":"Early personality change"},{"id":"d","text":"Stepwise cognitive decline"}],"answerId":"b","explanation":"Visual hallucinations are characteristic of dementia with Lewy bodies.","kind":"integration","linkedModuleIds":["fcp1-movement-hypokinetic-parkinsonism"],"origin":"ai"},{"id":"fcp1-cognitive-assessment~ai-7","moduleId":"fcp1-cognitive-assessment","stem":"A patient presents with cognitive decline and is found to have a stepwise deterioration in function. Which type of dementia is most likely?","options":[{"id":"a","text":"Alzheimer disease"},{"id":"b","text":"Vascular dementia"},{"id":"c","text":"Dementia with Lewy bodies"},{"id":"d","text":"Frontotemporal dementia"}],"answerId":"b","explanation":"Stepwise cognitive decline is characteristic of vascular dementia.","kind":"integration","linkedModuleIds":["alzheimer-and-dementias"],"origin":"ai"}],"fcp1-hyperthyroidism":[{"id":"fcp1-hyperthyroidism~ai-0","moduleId":"fcp1-hyperthyroidism","stem":"A 35-year-old woman presents with weight loss, palpitations, and heat intolerance. Examination reveals a diffuse goitre with a bruit and proptosis. What is the most likely diagnosis?","options":[{"id":"a","text":"Graves disease"},{"id":"b","text":"Toxic multinodular goitre"},{"id":"c","text":"Subacute thyroiditis"},{"id":"d","text":"Toxic adenoma"}],"answerId":"a","explanation":"The presence of a diffuse goitre with a bruit and proptosis is characteristic of Graves disease.","kind":"clinical","origin":"ai"},{"id":"fcp1-hyperthyroidism~ai-1","moduleId":"fcp1-hyperthyroidism","stem":"Which of the following is a specific sign of Graves disease not seen in toxic multinodular goitre?","options":[{"id":"a","text":"Proptosis"},{"id":"b","text":"Weight loss"},{"id":"c","text":"Tachycardia"},{"id":"d","text":"Heat intolerance"}],"answerId":"a","explanation":"Proptosis is specific to Graves disease and is not seen in toxic multinodular goitre.","kind":"recall","origin":"ai"},{"id":"fcp1-hyperthyroidism~ai-2","moduleId":"fcp1-hyperthyroidism","stem":"A patient with hyperthyroidism is found to have a low radioiodine uptake. Which condition is most likely?","options":[{"id":"a","text":"Graves disease"},{"id":"b","text":"Toxic adenoma"},{"id":"c","text":"Subacute thyroiditis"},{"id":"d","text":"Toxic multinodular goitre"}],"answerId":"c","explanation":"Subacute thyroiditis shows low radioiodine uptake due to hormone leakage rather than overproduction.","kind":"trap","origin":"ai"},{"id":"fcp1-hyperthyroidism~ai-3","moduleId":"fcp1-hyperthyroidism","stem":"An elderly patient presents with new-onset atrial fibrillation and weight loss but no other symptoms of hyperthyroidism. What condition should be considered?","options":[{"id":"a","text":"Apathetic hyperthyroidism"},{"id":"b","text":"Subacute thyroiditis"},{"id":"c","text":"Graves disease"},{"id":"d","text":"Toxic adenoma"}],"answerId":"a","explanation":"Apathetic hyperthyroidism in the elderly can present with atypical symptoms such as isolated weight loss and atrial fibrillation.","kind":"clinical","origin":"ai"},{"id":"fcp1-hyperthyroidism~ai-4","moduleId":"fcp1-hyperthyroidism","stem":"A 45-year-old woman with hyperthyroidism is treated with methimazole. Her symptoms improve, but she develops a sore throat and fever. What is the most appropriate next step?","options":[{"id":"a","text":"Continue methimazole"},{"id":"b","text":"Discontinue methimazole and check WBC count"},{"id":"c","text":"Increase methimazole dose"},{"id":"d","text":"Add a beta-blocker"}],"answerId":"b","explanation":"Sore throat and fever in a patient on methimazole may indicate agranulocytosis, requiring discontinuation and WBC count check.","kind":"trap","origin":"ai"},{"id":"fcp1-hyperthyroidism~ai-5","moduleId":"fcp1-hyperthyroidism","stem":"A patient with hyperthyroidism is experiencing severe agitation, fever, and tachycardia. Which condition is most likely?","options":[{"id":"a","text":"Thyroid storm"},{"id":"b","text":"Graves disease"},{"id":"c","text":"Toxic adenoma"},{"id":"d","text":"Subacute thyroiditis"}],"answerId":"a","explanation":"Thyroid storm is a life-threatening exacerbation of hyperthyroidism characterized by severe symptoms such as agitation, fever, and tachycardia.","kind":"clinical","origin":"ai"},{"id":"fcp1-hyperthyroidism~ai-6","moduleId":"fcp1-hyperthyroidism","stem":"A 30-year-old woman presents with weight loss and palpitations. Her TSH is suppressed, and she has high radioiodine uptake. Which linked module would help further understand her condition?","options":[{"id":"a","text":"fcp1-weight-loss-approach"},{"id":"b","text":"fcp1-fever-approach-differential"},{"id":"c","text":"fcp1-thyroid-approach"},{"id":"d","text":"fcp1-hypothyroidism"}],"answerId":"c","explanation":"The 'Approach to Thyroid Disease' module provides comprehensive information on thyroid conditions, including hyperthyroidism.","kind":"integration","linkedModuleIds":["fcp1-thyroid-approach"],"origin":"ai"},{"id":"fcp1-hyperthyroidism~ai-7","moduleId":"fcp1-hyperthyroidism","stem":"Which linked module would provide additional insights into the management of a patient with hyperthyroidism and concurrent atrial fibrillation?","options":[{"id":"a","text":"fcp1-weight-loss-approach"},{"id":"b","text":"iodide-radioiodine-thyrotoxicosis"},{"id":"c","text":"hyperthyroidism-graves"},{"id":"d","text":"fcp1-hypothyroidism"}],"answerId":"b","explanation":"The 'Iodide, Radioiodine & Thyrotoxicosis Adjuncts' module discusses management strategies for hyperthyroidism, including those with atrial fibrillation.","kind":"integration","linkedModuleIds":["iodide-radioiodine-thyrotoxicosis"],"origin":"ai"}],"fcp1-arthritis-approach":[{"id":"fcp1-arthritis-approach~ai-0","moduleId":"fcp1-arthritis-approach","stem":"A 55-year-old woman presents with joint pain and stiffness in the morning that lasts over an hour and improves with activity. What is the most likely type of arthritis?","options":[{"id":"a","text":"Inflammatory arthritis"},{"id":"b","text":"Mechanical arthritis"},{"id":"c","text":"Periarticular pain"},{"id":"d","text":"Septic arthritis"}],"answerId":"a","explanation":"Prolonged morning stiffness that improves with use is characteristic of inflammatory arthritis.","kind":"recall","origin":"ai"},{"id":"fcp1-arthritis-approach~ai-1","moduleId":"fcp1-arthritis-approach","stem":"A patient with a history of gout presents with an acutely swollen, red, and painful big toe. What is the most appropriate next step in management?","options":[{"id":"a","text":"Start NSAIDs"},{"id":"b","text":"Initiate colchicine"},{"id":"c","text":"Perform joint aspiration"},{"id":"d","text":"Administer corticosteroids"}],"answerId":"c","explanation":"Septic and crystal arthritis can coexist; joint aspiration is necessary to rule out infection.","kind":"trap","origin":"ai"},{"id":"fcp1-arthritis-approach~ai-2","moduleId":"fcp1-arthritis-approach","stem":"A 60-year-old man has joint pain that worsens with activity and is associated with bony enlargement and crepitus. What is the most likely diagnosis?","options":[{"id":"a","text":"Rheumatoid arthritis"},{"id":"b","text":"Osteoarthritis"},{"id":"c","text":"Gout"},{"id":"d","text":"Septic arthritis"}],"answerId":"b","explanation":"Osteoarthritis is characterized by pain worsening with use, bony enlargement, and crepitus.","kind":"clinical","origin":"ai"},{"id":"fcp1-arthritis-approach~ai-3","moduleId":"fcp1-arthritis-approach","stem":"A 30-year-old man presents with a hot, swollen knee and fever. What is the most urgent investigation?","options":[{"id":"a","text":"Blood cultures"},{"id":"b","text":"Joint aspiration"},{"id":"c","text":"X-ray of the knee"},{"id":"d","text":"CRP and ESR"}],"answerId":"b","explanation":"Joint aspiration is urgent to rule out septic arthritis in the presence of fever and a swollen joint.","kind":"clinical","linkedModuleIds":["fcp1-fever-approach-differential"],"origin":"ai"},{"id":"fcp1-arthritis-approach~ai-4","moduleId":"fcp1-arthritis-approach","stem":"A 45-year-old woman has joint pain with point tenderness and full passive range of motion. What is the most likely diagnosis?","options":[{"id":"a","text":"Rheumatoid arthritis"},{"id":"b","text":"Osteoarthritis"},{"id":"c","text":"Bursitis"},{"id":"d","text":"Septic arthritis"}],"answerId":"c","explanation":"Point tenderness with full passive range suggests a periarticular condition like bursitis.","kind":"recall","origin":"ai"},{"id":"fcp1-arthritis-approach~ai-5","moduleId":"fcp1-arthritis-approach","stem":"A 50-year-old man with psoriasis presents with joint pain and swelling. Which type of arthritis is most likely?","options":[{"id":"a","text":"Rheumatoid arthritis"},{"id":"b","text":"Psoriatic arthritis"},{"id":"c","text":"Osteoarthritis"},{"id":"d","text":"Reactive arthritis"}],"answerId":"b","explanation":"Psoriatic arthritis is associated with psoriasis and can cause joint pain and swelling.","kind":"integration","linkedModuleIds":["fcp1-skin-signs-systemic-disease"],"origin":"ai"},{"id":"fcp1-arthritis-approach~ai-6","moduleId":"fcp1-arthritis-approach","stem":"A 35-year-old woman presents with joint pain, fever, and a rash. Which condition should be considered?","options":[{"id":"a","text":"Rheumatoid arthritis"},{"id":"b","text":"Systemic lupus erythematosus"},{"id":"c","text":"Osteoarthritis"},{"id":"d","text":"Gout"}],"answerId":"b","explanation":"Systemic lupus erythematosus can present with joint pain, fever, and a rash.","kind":"integration","linkedModuleIds":["fcp1-skin-signs-systemic-disease"],"origin":"ai"}],"fcp1-thyroid-approach":[{"id":"fcp1-thyroid-approach~ai-0","moduleId":"fcp1-thyroid-approach","stem":"A 45-year-old woman presents with weight gain, cold intolerance, and constipation. Her TSH is elevated. What is the next best step in management?","options":[{"id":"a","text":"Measure free T4"},{"id":"b","text":"Start levothyroxine"},{"id":"c","text":"Perform thyroid ultrasound"},{"id":"d","text":"Check thyroid antibodies"}],"answerId":"a","explanation":"An elevated TSH suggests hypothyroidism, and measuring free T4 helps confirm the diagnosis and assess severity.","kind":"recall","origin":"ai"},{"id":"fcp1-thyroid-approach~ai-1","moduleId":"fcp1-thyroid-approach","stem":"A patient with a history of thyroid disease presents with a solitary hard fixed thyroid nodule and cervical lymphadenopathy. What is the most appropriate next step?","options":[{"id":"a","text":"Reassure and observe"},{"id":"b","text":"Start levothyroxine therapy"},{"id":"c","text":"Perform fine-needle aspiration cytology"},{"id":"d","text":"Order a thyroid scan"}],"answerId":"c","explanation":"A hard fixed nodule with cervical lymphadenopathy raises concern for malignancy, warranting fine-needle aspiration cytology.","kind":"clinical","origin":"ai"},{"id":"fcp1-thyroid-approach~ai-2","moduleId":"fcp1-thyroid-approach","stem":"A 60-year-old man presents with fatigue and a dry coarse skin. His TSH is normal, but free T4 is low. What is the likely diagnosis?","options":[{"id":"a","text":"Primary hypothyroidism"},{"id":"b","text":"Central hypothyroidism"},{"id":"c","text":"Euthyroid sick syndrome"},{"id":"d","text":"Subclinical hypothyroidism"}],"answerId":"b","explanation":"Normal TSH with low free T4 suggests central hypothyroidism, where the pituitary fails to produce adequate TSH.","kind":"trap","origin":"ai"},{"id":"fcp1-thyroid-approach~ai-3","moduleId":"fcp1-thyroid-approach","stem":"Which of the following exam findings is most indicative of Graves disease?","options":[{"id":"a","text":"Diffuse smooth goitre with an audible bruit"},{"id":"b","text":"Solitary hard fixed nodule"},{"id":"c","text":"Dry coarse skin"},{"id":"d","text":"Bradycardia"}],"answerId":"a","explanation":"A diffuse smooth goitre with an audible bruit is characteristic of the hypervascular gland seen in Graves disease.","kind":"mechanism","origin":"ai"},{"id":"fcp1-thyroid-approach~ai-4","moduleId":"fcp1-thyroid-approach","stem":"A 35-year-old woman with a history of obesity presents with weight gain and fatigue. Her TSH is elevated. Which linked module would provide additional relevant information?","options":[{"id":"a","text":"fcp1-obesity-approach"},{"id":"b","text":"fcp1-dysphagia"},{"id":"c","text":"solitary-pulmonary-nodule"},{"id":"d","text":"fcp1-skin-signs-systemic-disease"}],"answerId":"a","explanation":"The 'Approach to Obesity' module would provide additional insights into weight management in the context of thyroid dysfunction.","kind":"integration","linkedModuleIds":["fcp1-obesity-approach"],"origin":"ai"},{"id":"fcp1-thyroid-approach~ai-5","moduleId":"fcp1-thyroid-approach","stem":"A patient presents with dysphagia and a large thyroid goitre. Which linked module would assist in further evaluation of this symptom?","options":[{"id":"a","text":"fcp1-dysphagia"},{"id":"b","text":"fcp1-hyperthyroidism"},{"id":"c","text":"fcp1-hypothyroidism"},{"id":"d","text":"solitary-pulmonary-nodule"}],"answerId":"a","explanation":"The 'Approach to Dysphagia' module would help evaluate the swallowing difficulties associated with thyroid enlargement.","kind":"integration","linkedModuleIds":["fcp1-dysphagia"],"origin":"ai"},{"id":"fcp1-thyroid-approach~ai-6","moduleId":"fcp1-thyroid-approach","stem":"A 50-year-old man presents with palpitations, weight loss, and heat intolerance. His TSH is low. What is the most likely diagnosis?","options":[{"id":"a","text":"Hypothyroidism"},{"id":"b","text":"Hyperthyroidism"},{"id":"c","text":"Euthyroid sick syndrome"},{"id":"d","text":"Thyroiditis"}],"answerId":"b","explanation":"Low TSH with symptoms of palpitations, weight loss, and heat intolerance is indicative of hyperthyroidism.","kind":"recall","origin":"ai"}],"fcp1-inflammatory-vs-mechanical":[{"id":"fcp1-inflammatory-vs-mechanical~ai-0","moduleId":"fcp1-inflammatory-vs-mechanical","stem":"A 55-year-old woman presents with joint pain in her hands. She reports stiffness in the morning that lasts about 10 minutes and worsens with activity. What is the most likely diagnosis?","options":[{"id":"a","text":"Rheumatoid arthritis"},{"id":"b","text":"Osteoarthritis"},{"id":"c","text":"Gout"},{"id":"d","text":"Psoriatic arthritis"}],"answerId":"b","explanation":"Brief morning stiffness that worsens with activity is characteristic of osteoarthritis.","kind":"clinical","origin":"ai"},{"id":"fcp1-inflammatory-vs-mechanical~ai-1","moduleId":"fcp1-inflammatory-vs-mechanical","stem":"Which of the following findings is most indicative of inflammatory joint disease?","options":[{"id":"a","text":"Hard bony enlargement"},{"id":"b","text":"Crepitus without warmth"},{"id":"c","text":"Prolonged morning stiffness"},{"id":"d","text":"Pain relieved by rest"}],"answerId":"c","explanation":"Prolonged morning stiffness is a hallmark of inflammatory joint disease.","kind":"recall","origin":"ai"},{"id":"fcp1-inflammatory-vs-mechanical~ai-2","moduleId":"fcp1-inflammatory-vs-mechanical","stem":"A patient with joint pain has normal CRP and ESR levels. Which condition is least likely?","options":[{"id":"a","text":"Rheumatoid arthritis"},{"id":"b","text":"Osteoarthritis"},{"id":"c","text":"Gout"},{"id":"d","text":"Spondyloarthritis"}],"answerId":"a","explanation":"Normal CRP and ESR are less common in rheumatoid arthritis compared to other conditions.","kind":"trap","origin":"ai"},{"id":"fcp1-inflammatory-vs-mechanical~ai-3","moduleId":"fcp1-inflammatory-vs-mechanical","stem":"A 60-year-old man reports knee pain that is worse with activity and relieved by rest. Examination reveals crepitus and hard bony enlargement. What is the most likely diagnosis?","options":[{"id":"a","text":"Rheumatoid arthritis"},{"id":"b","text":"Osteoarthritis"},{"id":"c","text":"Gout"},{"id":"d","text":"Spondyloarthritis"}],"answerId":"b","explanation":"The combination of pain with activity, relief by rest, and hard bony enlargement suggests osteoarthritis.","kind":"clinical","origin":"ai"},{"id":"fcp1-inflammatory-vs-mechanical~ai-4","moduleId":"fcp1-inflammatory-vs-mechanical","stem":"Which feature distinguishes mechanical joint pain from inflammatory joint pain?","options":[{"id":"a","text":"Night pain"},{"id":"b","text":"Prolonged morning stiffness"},{"id":"c","text":"Gel phenomenon"},{"id":"d","text":"Systemic features"}],"answerId":"c","explanation":"The gel phenomenon, or transient post-rest stiffness, is characteristic of mechanical joint pain.","kind":"mechanism","origin":"ai"},{"id":"fcp1-inflammatory-vs-mechanical~ai-5","moduleId":"fcp1-inflammatory-vs-mechanical","stem":"A 45-year-old woman presents with joint pain and morning stiffness lasting over an hour. Which additional symptom would most strongly suggest an inflammatory etiology?","options":[{"id":"a","text":"Pain relieved by rest"},{"id":"b","text":"Hard bony enlargement"},{"id":"c","text":"Systemic features"},{"id":"d","text":"Crepitus"}],"answerId":"c","explanation":"Systemic features such as fever or fatigue are more associated with inflammatory joint diseases.","kind":"clinical","origin":"ai"},{"id":"fcp1-inflammatory-vs-mechanical~ai-6","moduleId":"fcp1-inflammatory-vs-mechanical","stem":"A patient presents with acute monoarthritis and fever. Which linked module should be consulted to rule out a critical condition?","options":[{"id":"a","text":"Approach to Acute Fever"},{"id":"b","text":"Male Hypogonadism Diagnosis & Treatment Logic"},{"id":"c","text":"Osteoarthritis & Rheumatoid Arthritis"},{"id":"d","text":"Monoarthritis vs Polyarthritis"}],"answerId":"a","explanation":"The 'Approach to Acute Fever' module is relevant for evaluating fever in the context of monoarthritis to rule out septic arthritis.","kind":"integration","linkedModuleIds":["fcp1-fever-approach-differential"],"origin":"ai"},{"id":"fcp1-inflammatory-vs-mechanical~ai-7","moduleId":"fcp1-inflammatory-vs-mechanical","stem":"In the context of joint pain, which linked module provides a comprehensive approach to distinguishing between different types of arthritis?","options":[{"id":"a","text":"Approach to Acute Fever"},{"id":"b","text":"Approach to Arthritis"},{"id":"c","text":"Male Hypogonadism Diagnosis & Treatment Logic"},{"id":"d","text":"Monoarthritis vs Polyarthritis"}],"answerId":"b","explanation":"The 'Approach to Arthritis' module offers a detailed framework for differentiating types of arthritis.","kind":"integration","linkedModuleIds":["fcp1-arthritis-approach"],"origin":"ai"}],"fcp1-hypothyroidism":[{"id":"fcp1-hypothyroidism~ai-0","moduleId":"fcp1-hypothyroidism","stem":"A 45-year-old woman presents with fatigue, weight gain, and cold intolerance. Her TSH is elevated, and free T4 is low. What is the most likely diagnosis?","options":[{"id":"a","text":"Hypothyroidism"},{"id":"b","text":"Hyperthyroidism"},{"id":"c","text":"Subclinical hypothyroidism"},{"id":"d","text":"Euthyroid sick syndrome"}],"answerId":"a","explanation":"Elevated TSH with low free T4 is diagnostic of primary hypothyroidism.","kind":"recall","origin":"ai"},{"id":"fcp1-hypothyroidism~ai-1","moduleId":"fcp1-hypothyroidism","stem":"Which of the following is a common physical exam finding in hypothyroidism?","options":[{"id":"a","text":"Exophthalmos"},{"id":"b","text":"Delayed relaxation of the ankle reflex"},{"id":"c","text":"Pretibial myxedema"},{"id":"d","text":"Tachycardia"}],"answerId":"b","explanation":"Delayed relaxation phase of the ankle reflex is a classic sign of hypothyroidism.","kind":"recall","origin":"ai"},{"id":"fcp1-hypothyroidism~ai-2","moduleId":"fcp1-hypothyroidism","stem":"A patient with hypothyroidism is started on levothyroxine. What is the recommended follow-up interval to recheck TSH levels?","options":[{"id":"a","text":"2 weeks"},{"id":"b","text":"6 weeks"},{"id":"c","text":"3 months"},{"id":"d","text":"6 months"}],"answerId":"b","explanation":"TSH should be rechecked about 6 weeks after starting or adjusting levothyroxine.","kind":"recall","origin":"ai"},{"id":"fcp1-hypothyroidism~ai-3","moduleId":"fcp1-hypothyroidism","stem":"A 60-year-old man with a history of ischemic heart disease is diagnosed with hypothyroidism. How should levothyroxine be initiated?","options":[{"id":"a","text":"Full replacement dose immediately"},{"id":"b","text":"Start low and titrate up slowly"},{"id":"c","text":"No treatment needed"},{"id":"d","text":"Start with antithyroid drugs"}],"answerId":"b","explanation":"In patients with ischemic heart disease, levothyroxine should be started at a low dose and titrated up to prevent cardiac complications.","kind":"trap","origin":"ai"},{"id":"fcp1-hypothyroidism~ai-4","moduleId":"fcp1-hypothyroidism","stem":"Which of the following mechanisms explains the non-pitting edema seen in hypothyroidism?","options":[{"id":"a","text":"Increased capillary permeability"},{"id":"b","text":"Glycosaminoglycan deposition"},{"id":"c","text":"Lymphatic obstruction"},{"id":"d","text":"Sodium retention"}],"answerId":"b","explanation":"Non-pitting edema in hypothyroidism is due to glycosaminoglycan deposition.","kind":"mechanism","origin":"ai"},{"id":"fcp1-hypothyroidism~ai-5","moduleId":"fcp1-hypothyroidism","stem":"A patient presents with fatigue, weight gain, and constipation. Lab tests show elevated TSH and normal free T4. Which condition is this most consistent with?","options":[{"id":"a","text":"Primary hypothyroidism"},{"id":"b","text":"Subclinical hypothyroidism"},{"id":"c","text":"Central hypothyroidism"},{"id":"d","text":"Euthyroid sick syndrome"}],"answerId":"b","explanation":"Elevated TSH with normal free T4 is indicative of subclinical hypothyroidism.","kind":"clinical","origin":"ai"},{"id":"fcp1-hypothyroidism~ai-6","moduleId":"fcp1-hypothyroidism","stem":"A patient with hypothyroidism is found to have macrocytic anemia. Which linked module provides a classification of this type of anemia?","options":[{"id":"a","text":"fcp1-obesity-approach"},{"id":"b","text":"fcp1-edema-approach"},{"id":"c","text":"fcp1-anemia-classification"},{"id":"d","text":"fcp1-thyroid-approach"}],"answerId":"c","explanation":"The 'fcp1-anemia-classification' module provides information on macrocytic anemia.","kind":"integration","origin":"ai"},{"id":"fcp1-hypothyroidism~ai-7","moduleId":"fcp1-hypothyroidism","stem":"A patient with hypothyroidism is experiencing cognitive slowing. Which linked module can provide additional information on cognitive changes?","options":[{"id":"a","text":"fcp1-delirium-vs-dementia"},{"id":"b","text":"fcp1-hyperthyroidism"},{"id":"c","text":"fcp1-edema-approach"},{"id":"d","text":"gastric-accommodation-mixing"}],"answerId":"a","explanation":"The 'fcp1-delirium-vs-dementia' module discusses cognitive changes and can provide additional context.","kind":"integration","origin":"ai"}],"fcp1-monoarthritis-vs-polyarthritis":[{"id":"fcp1-monoarthritis-vs-polyarthritis~ai-0","moduleId":"fcp1-monoarthritis-vs-polyarthritis","stem":"A 55-year-old male presents with sudden onset of severe pain and swelling in his right knee. Synovial fluid analysis shows needle-shaped crystals with negative birefringence. What is the most likely diagnosis?","options":[{"id":"a","text":"Gout"},{"id":"b","text":"Pseudogout"},{"id":"c","text":"Septic arthritis"},{"id":"d","text":"Rheumatoid arthritis"}],"answerId":"a","explanation":"Needle-shaped crystals with negative birefringence in synovial fluid are characteristic of gout.","kind":"recall","origin":"ai"},{"id":"fcp1-monoarthritis-vs-polyarthritis~ai-1","moduleId":"fcp1-monoarthritis-vs-polyarthritis","stem":"A 30-year-old female presents with migratory joint pain, tenosynovitis, and pustular skin lesions. Which of the following is the most likely diagnosis?","options":[{"id":"a","text":"Reactive arthritis"},{"id":"b","text":"Viral arthritis"},{"id":"c","text":"Gonococcal arthritis"},{"id":"d","text":"Psoriatic arthritis"}],"answerId":"c","explanation":"The combination of migratory arthritis, tenosynovitis, and pustular skin lesions suggests disseminated gonococcal infection.","kind":"trap","origin":"ai"},{"id":"fcp1-monoarthritis-vs-polyarthritis~ai-2","moduleId":"fcp1-monoarthritis-vs-polyarthritis","stem":"A patient presents with symmetric swelling of the MCP, PIP, and wrist joints. Which condition is most consistent with this presentation?","options":[{"id":"a","text":"Rheumatoid arthritis"},{"id":"b","text":"Osteoarthritis"},{"id":"c","text":"Gout"},{"id":"d","text":"Pseudogout"}],"answerId":"a","explanation":"Symmetric swelling of the MCP, PIP, and wrist joints is characteristic of rheumatoid arthritis.","kind":"clinical","origin":"ai"},{"id":"fcp1-monoarthritis-vs-polyarthritis~ai-3","moduleId":"fcp1-monoarthritis-vs-polyarthritis","stem":"A 45-year-old male presents with acute monoarthritis of the left knee and fever. What is the most appropriate next step in management?","options":[{"id":"a","text":"Start antibiotics immediately"},{"id":"b","text":"Perform joint aspiration"},{"id":"c","text":"Order a CT scan of the knee"},{"id":"d","text":"Prescribe NSAIDs"}],"answerId":"b","explanation":"Acute monoarthritis with fever should be considered septic until proven otherwise; joint aspiration is necessary for diagnosis.","kind":"mechanism","origin":"ai"},{"id":"fcp1-monoarthritis-vs-polyarthritis~ai-4","moduleId":"fcp1-monoarthritis-vs-polyarthritis","stem":"A 60-year-old female presents with asymmetric oligoarthritis involving the knees and ankles. She also has a history of psoriasis. What is the most likely diagnosis?","options":[{"id":"a","text":"Rheumatoid arthritis"},{"id":"b","text":"Psoriatic arthritis"},{"id":"c","text":"Gout"},{"id":"d","text":"Septic arthritis"}],"answerId":"b","explanation":"Asymmetric oligoarthritis with a history of psoriasis suggests psoriatic arthritis.","kind":"clinical","origin":"ai"},{"id":"fcp1-monoarthritis-vs-polyarthritis~ai-5","moduleId":"fcp1-monoarthritis-vs-polyarthritis","stem":"A 50-year-old male with a history of gout presents with fever and a swollen, painful right knee. Synovial fluid analysis shows elevated white blood cells but no crystals. Which module should be consulted for further differential diagnosis?","options":[{"id":"a","text":"fcp1-fever-approach-differential"},{"id":"b","text":"osteoarthritis-rheumatoid"},{"id":"c","text":"rheumatoid-arthritis-drugs"},{"id":"d","text":"fcp1-skin-signs-systemic-disease"}],"answerId":"a","explanation":"The presence of fever and joint swelling without crystals suggests an infectious cause; the fever approach module can aid in differential diagnosis.","kind":"integration","linkedModuleIds":["fcp1-fever-approach-differential"],"origin":"ai"},{"id":"fcp1-monoarthritis-vs-polyarthritis~ai-6","moduleId":"fcp1-monoarthritis-vs-polyarthritis","stem":"A 28-year-old male presents with urethritis, conjunctivitis, and asymmetric arthritis of the lower limbs. Which module provides additional information on the likely diagnosis?","options":[{"id":"a","text":"fcp1-arthritis-approach"},{"id":"b","text":"osteoarthritis-rheumatoid"},{"id":"c","text":"rheumatoid-arthritis-drugs"},{"id":"d","text":"fcp1-skin-signs-systemic-disease"}],"answerId":"a","explanation":"The combination of urethritis, conjunctivitis, and arthritis suggests reactive arthritis; the arthritis approach module provides further details.","kind":"integration","linkedModuleIds":["fcp1-arthritis-approach"],"origin":"ai"}],"fcp1-skin-signs-systemic-disease":[{"id":"fcp1-skin-signs-systemic-disease~ai-0","moduleId":"fcp1-skin-signs-systemic-disease","stem":"A 45-year-old man presents with a velvety, hyperpigmented rash on the back of his neck. Which systemic condition is most commonly associated with this skin finding?","options":[{"id":"a","text":"Insulin resistance"},{"id":"b","text":"Liver cirrhosis"},{"id":"c","text":"Systemic lupus erythematosus"},{"id":"d","text":"Chronic kidney disease"}],"answerId":"a","explanation":"Acanthosis nigricans is commonly associated with insulin resistance and can also be a marker for malignancy.","kind":"recall","origin":"ai"},{"id":"fcp1-skin-signs-systemic-disease~ai-1","moduleId":"fcp1-skin-signs-systemic-disease","stem":"A patient presents with a painful, blistering rash and mucosal erosions. The Nikolsky sign is positive. What is the most likely diagnosis?","options":[{"id":"a","text":"Stevens-Johnson syndrome"},{"id":"b","text":"Erythema multiforme"},{"id":"c","text":"Psoriasis"},{"id":"d","text":"Lichen planus"}],"answerId":"a","explanation":"The presence of painful skin, mucosal erosions, and a positive Nikolsky sign suggests Stevens-Johnson syndrome or toxic epidermal necrolysis.","kind":"mechanism","origin":"ai"},{"id":"fcp1-skin-signs-systemic-disease~ai-2","moduleId":"fcp1-skin-signs-systemic-disease","stem":"A 7-year-old child presents with fever and a non-blanching purpuric rash. What is the most appropriate next step in management?","options":[{"id":"a","text":"Administer intravenous antibiotics"},{"id":"b","text":"Observe and reassess in 24 hours"},{"id":"c","text":"Prescribe oral antihistamines"},{"id":"d","text":"Order a viral serology panel"}],"answerId":"a","explanation":"A febrile child with a non-blanching purpuric rash should be treated as meningococcaemia, which requires immediate antibiotic therapy.","kind":"trap","origin":"ai"},{"id":"fcp1-skin-signs-systemic-disease~ai-3","moduleId":"fcp1-skin-signs-systemic-disease","stem":"A 30-year-old woman presents with a malar rash that spares the nasolabial folds. Which systemic disease is this most indicative of?","options":[{"id":"a","text":"Systemic lupus erythematosus"},{"id":"b","text":"Dermatomyositis"},{"id":"c","text":"Rosacea"},{"id":"d","text":"Seborrheic dermatitis"}],"answerId":"a","explanation":"A malar rash sparing the nasolabial folds is characteristic of systemic lupus erythematosus.","kind":"clinical","origin":"ai"},{"id":"fcp1-skin-signs-systemic-disease~ai-4","moduleId":"fcp1-skin-signs-systemic-disease","stem":"A patient with a history of inflammatory bowel disease presents with a painful, ulcerative skin lesion on the leg. Which skin condition is most likely?","options":[{"id":"a","text":"Pyoderma gangrenosum"},{"id":"b","text":"Erythema nodosum"},{"id":"c","text":"Psoriasis"},{"id":"d","text":"Lichen planus"}],"answerId":"a","explanation":"Pyoderma gangrenosum is associated with inflammatory bowel disease and presents as painful ulcerative lesions.","kind":"integration","linkedModuleIds":["fcp1-arthritis-approach"],"origin":"ai"},{"id":"fcp1-skin-signs-systemic-disease~ai-5","moduleId":"fcp1-skin-signs-systemic-disease","stem":"A 5-year-old child presents with a 'slapped cheek' rash and mild fever. Which viral infection is most likely responsible?","options":[{"id":"a","text":"Parvovirus B19"},{"id":"b","text":"Measles"},{"id":"c","text":"Rubella"},{"id":"d","text":"Varicella"}],"answerId":"a","explanation":"Erythema infectiosum, characterized by a 'slapped cheek' appearance, is caused by Parvovirus B19.","kind":"recall","origin":"ai"},{"id":"fcp1-skin-signs-systemic-disease~ai-6","moduleId":"fcp1-skin-signs-systemic-disease","stem":"A patient presents with jaundice and spider naevi. Which organ system is most likely affected?","options":[{"id":"a","text":"Liver"},{"id":"b","text":"Kidney"},{"id":"c","text":"Heart"},{"id":"d","text":"Lungs"}],"answerId":"a","explanation":"Jaundice and spider naevi are indicative of liver disease.","kind":"integration","origin":"ai"}],"fcp1-skin-lesion-morphology":[{"id":"fcp1-skin-lesion-morphology~ai-0","moduleId":"fcp1-skin-lesion-morphology","stem":"A 5-year-old child presents with a rash characterized by small, flat, non-blanching red spots. What is the most appropriate term for these lesions?","options":[{"id":"a","text":"Macules"},{"id":"b","text":"Petechiae"},{"id":"c","text":"Papules"},{"id":"d","text":"Vesicles"}],"answerId":"b","explanation":"Petechiae are small, non-blanching red spots indicating bleeding into the skin.","kind":"recall","origin":"ai"},{"id":"fcp1-skin-lesion-morphology~ai-1","moduleId":"fcp1-skin-lesion-morphology","stem":"A patient presents with a 2 cm raised, flat-topped lesion on the elbow. Which term best describes this lesion?","options":[{"id":"a","text":"Macule"},{"id":"b","text":"Plaque"},{"id":"c","text":"Nodule"},{"id":"d","text":"Papule"}],"answerId":"b","explanation":"A plaque is a raised, flat-topped lesion over 1 cm in diameter.","kind":"recall","origin":"ai"},{"id":"fcp1-skin-lesion-morphology~ai-2","moduleId":"fcp1-skin-lesion-morphology","stem":"Which of the following is a primary skin lesion that is fluid-filled and less than 1 cm in diameter?","options":[{"id":"a","text":"Bulla"},{"id":"b","text":"Vesicle"},{"id":"c","text":"Pustule"},{"id":"d","text":"Nodule"}],"answerId":"b","explanation":"A vesicle is a fluid-filled lesion under 1 cm in diameter.","kind":"recall","origin":"ai"},{"id":"fcp1-skin-lesion-morphology~ai-3","moduleId":"fcp1-skin-lesion-morphology","stem":"A 30-year-old presents with grouped vesicles on an erythematous base along a single dermatome. What is the most likely diagnosis?","options":[{"id":"a","text":"Psoriasis"},{"id":"b","text":"Herpes zoster"},{"id":"c","text":"Impetigo"},{"id":"d","text":"Eczema herpeticum"}],"answerId":"b","explanation":"Grouped vesicles along a dermatome suggest herpes zoster (shingles).","kind":"clinical","origin":"ai"},{"id":"fcp1-skin-lesion-morphology~ai-4","moduleId":"fcp1-skin-lesion-morphology","stem":"A patient with a history of recurrent urticaria presents with transient wheals. What is the underlying mechanism of these lesions?","options":[{"id":"a","text":"Epidermal necrosis"},{"id":"b","text":"Dermal oedema"},{"id":"c","text":"Subcutaneous fat necrosis"},{"id":"d","text":"Vascular proliferation"}],"answerId":"b","explanation":"Urticaria is characterized by transient wheals due to dermal oedema.","kind":"mechanism","origin":"ai"},{"id":"fcp1-skin-lesion-morphology~ai-5","moduleId":"fcp1-skin-lesion-morphology","stem":"A patient presents with a rash that does not blanch on pressure and has a fever. Which linked module should be considered for further evaluation?","options":[{"id":"a","text":"fcp1-bleeding-primary-vs-secondary"},{"id":"b","text":"dermatologic-diagnosis-morphology"},{"id":"c","text":"fcp1-skin-signs-systemic-disease"},{"id":"d","text":"fcp1-skin-lesion-morphology"}],"answerId":"a","explanation":"Non-blanching purpura with fever may indicate a bleeding disorder, requiring evaluation of primary vs secondary haemostatic defects.","kind":"integration","linkedModuleIds":["fcp1-bleeding-primary-vs-secondary"],"origin":"ai"},{"id":"fcp1-skin-lesion-morphology~ai-6","moduleId":"fcp1-skin-lesion-morphology","stem":"A patient presents with erythematous plaques with silvery scales on extensor surfaces. Which systemic disease should be considered in the differential diagnosis?","options":[{"id":"a","text":"Diabetes mellitus"},{"id":"b","text":"Psoriasis"},{"id":"c","text":"Lupus erythematosus"},{"id":"d","text":"Dermatomyositis"}],"answerId":"b","explanation":"Psoriasis is characterized by erythematous plaques with silvery scales, often on extensor surfaces.","kind":"integration","linkedModuleIds":["fcp1-skin-signs-systemic-disease"],"origin":"ai"}],"fcp1-ent-common-symptoms":[{"id":"fcp1-ent-common-symptoms~ai-0","moduleId":"fcp1-ent-common-symptoms","stem":"A 45-year-old man presents with unilateral nasal obstruction and recurrent epistaxis. What is the most appropriate next step?","options":[{"id":"a","text":"Perform a nasal endoscopy"},{"id":"b","text":"Prescribe nasal decongestants"},{"id":"c","text":"Reassure and observe"},{"id":"d","text":"Start antibiotics for sinusitis"}],"answerId":"a","explanation":"Unilateral nasal obstruction and recurrent epistaxis raise suspicion for a nasal mass, warranting further investigation with nasal endoscopy.","kind":"clinical","origin":"ai"},{"id":"fcp1-ent-common-symptoms~ai-1","moduleId":"fcp1-ent-common-symptoms","stem":"A patient presents with sudden unilateral sensorineural hearing loss. Which of the following is the most urgent step in management?","options":[{"id":"a","text":"Oral corticosteroids"},{"id":"b","text":"Audiometry"},{"id":"c","text":"MRI of the brain"},{"id":"d","text":"Reassurance and follow-up"}],"answerId":"a","explanation":"Sudden unilateral sensorineural hearing loss is an emergency and should be treated promptly with oral corticosteroids to improve the chance of recovery.","kind":"recall","origin":"ai"},{"id":"fcp1-ent-common-symptoms~ai-2","moduleId":"fcp1-ent-common-symptoms","stem":"A 60-year-old woman has otalgia but normal otoscopy findings. What should be examined next?","options":[{"id":"a","text":"Nasal cavity"},{"id":"b","text":"Throat and larynx"},{"id":"c","text":"Cervical spine"},{"id":"d","text":"Temporal bone CT"}],"answerId":"b","explanation":"Otalgia with a normal ear suggests referred pain, often from the throat or larynx, which should be examined to rule out serious conditions.","kind":"trap","origin":"ai"},{"id":"fcp1-ent-common-symptoms~ai-3","moduleId":"fcp1-ent-common-symptoms","stem":"Which of the following findings is most consistent with conductive hearing loss?","options":[{"id":"a","text":"Rinne positive bilaterally"},{"id":"b","text":"Weber lateralizes to the affected ear"},{"id":"c","text":"Rinne negative bilaterally"},{"id":"d","text":"Weber lateralizes to the unaffected ear"}],"answerId":"b","explanation":"In conductive hearing loss, Weber test lateralizes to the affected ear, and Rinne test is negative on that side.","kind":"mechanism","origin":"ai"},{"id":"fcp1-ent-common-symptoms~ai-4","moduleId":"fcp1-ent-common-symptoms","stem":"A patient with persistent hoarseness for 4 weeks should be evaluated for which condition?","options":[{"id":"a","text":"Vocal cord nodules"},{"id":"b","text":"Laryngitis"},{"id":"c","text":"Head-and-neck cancer"},{"id":"d","text":"Reflux laryngitis"}],"answerId":"c","explanation":"Persistent hoarseness beyond 3 weeks is a red flag for head-and-neck cancer and warrants further investigation.","kind":"clinical","linkedModuleIds":["fcp1-ent-red-flags"],"origin":"ai"},{"id":"fcp1-ent-common-symptoms~ai-5","moduleId":"fcp1-ent-common-symptoms","stem":"A 55-year-old man presents with dysphagia and a neck mass. Which of the following is the most likely diagnosis?","options":[{"id":"a","text":"Thyroid goiter"},{"id":"b","text":"Lymphoma"},{"id":"c","text":"Esophageal carcinoma"},{"id":"d","text":"Head-and-neck cancer"}],"answerId":"d","explanation":"Dysphagia with a neck mass and ENT symptoms suggests head-and-neck malignancy.","kind":"integration","linkedModuleIds":["fcp1-dysphagia"],"origin":"ai"},{"id":"fcp1-ent-common-symptoms~ai-6","moduleId":"fcp1-ent-common-symptoms","stem":"A 30-year-old woman presents with dizziness and hearing loss. Which condition is most likely?","options":[{"id":"a","text":"BPPV"},{"id":"b","text":"Vestibular neuritis"},{"id":"c","text":"Ménière's disease"},{"id":"d","text":"Acoustic neuroma"}],"answerId":"c","explanation":"Ménière's disease is characterized by episodes of vertigo, hearing loss, and tinnitus.","kind":"clinical","origin":"ai"},{"id":"fcp1-ent-common-symptoms~ai-7","moduleId":"fcp1-ent-common-symptoms","stem":"In a patient with persistent unilateral ear pain and a normal ear exam, what is the most concerning potential diagnosis?","options":[{"id":"a","text":"Otitis media"},{"id":"b","text":"TMJ dysfunction"},{"id":"c","text":"Pharyngeal cancer"},{"id":"d","text":"Cerumen impaction"}],"answerId":"c","explanation":"Referred otalgia with a normal ear exam can indicate pharyngeal or laryngeal cancer.","kind":"trap","linkedModuleIds":["fcp1-ent-red-flags"],"origin":"ai"}],"fcp1-hematuria-approach":[{"id":"fcp1-hematuria-approach~ai-0","moduleId":"fcp1-hematuria-approach","stem":"A 55-year-old male presents with painless visible hematuria. He has a 30-pack-year smoking history and recent unexplained weight loss. What is the most appropriate next step in management?","options":[{"id":"a","text":"Urinalysis and culture"},{"id":"b","text":"Cystoscopy and CT urography"},{"id":"c","text":"Renal ultrasound"},{"id":"d","text":"Empirical antibiotics"}],"answerId":"b","explanation":"Painless visible hematuria in an adult, especially with risk factors like smoking and weight loss, suggests urothelial cancer, warranting cystoscopy and CT urography.","kind":"clinical","origin":"ai"},{"id":"fcp1-hematuria-approach~ai-1","moduleId":"fcp1-hematuria-approach","stem":"A 40-year-old woman presents with cola-colored urine and no clots. Urinalysis shows dysmorphic red cells and red-cell casts. What is the most likely diagnosis?","options":[{"id":"a","text":"Bladder cancer"},{"id":"b","text":"IgA nephropathy"},{"id":"c","text":"Ureteric stone"},{"id":"d","text":"Benign prostatic hyperplasia"}],"answerId":"b","explanation":"Cola-colored urine with dysmorphic red cells and red-cell casts indicates glomerular bleeding, consistent with IgA nephropathy.","kind":"recall","origin":"ai"},{"id":"fcp1-hematuria-approach~ai-2","moduleId":"fcp1-hematuria-approach","stem":"A patient on warfarin presents with visible hematuria. What is the most appropriate action?","options":[{"id":"a","text":"Reassure the patient"},{"id":"b","text":"Decrease the warfarin dose"},{"id":"c","text":"Investigate for a urological source"},{"id":"d","text":"Prescribe vitamin K"}],"answerId":"c","explanation":"Visible hematuria on anticoagulation suggests an underlying lesion, often a tumor, and should be investigated.","kind":"trap","origin":"ai"},{"id":"fcp1-hematuria-approach~ai-3","moduleId":"fcp1-hematuria-approach","stem":"Which finding is most indicative of a non-glomerular source of hematuria?","options":[{"id":"a","text":"Brown urine without clots"},{"id":"b","text":"Bright-red urine with clots"},{"id":"c","text":"Dysmorphic red cells in urine"},{"id":"d","text":"Red-cell casts in urine"}],"answerId":"b","explanation":"Bright-red urine with clots suggests a non-glomerular source, such as a lower urinary tract issue.","kind":"mechanism","origin":"ai"},{"id":"fcp1-hematuria-approach~ai-4","moduleId":"fcp1-hematuria-approach","stem":"A 60-year-old male with a history of hypertension presents with hematuria and edema. Urinalysis shows proteinuria and red-cell casts. Which linked module provides additional insights into his condition?","options":[{"id":"a","text":"fcp1-weight-loss-approach"},{"id":"b","text":"fcp1-edema-approach"},{"id":"c","text":"bladder-urothelial-carcinoma"},{"id":"d","text":"urinary-system-neoplasms"}],"answerId":"b","explanation":"The presence of edema and proteinuria with red-cell casts suggests a glomerular cause, linking to the edema approach module.","kind":"integration","linkedModuleIds":["fcp1-edema-approach"],"origin":"ai"},{"id":"fcp1-hematuria-approach~ai-5","moduleId":"fcp1-hematuria-approach","stem":"A 45-year-old male presents with lower urinary tract symptoms and visible hematuria. Which linked module should be consulted for further evaluation?","options":[{"id":"a","text":"fcp1-weight-loss-approach"},{"id":"b","text":"fcp1-edema-approach"},{"id":"c","text":"fcp1-urinary-symptoms-luts"},{"id":"d","text":"urinary-system-neoplasms"}],"answerId":"c","explanation":"Lower urinary tract symptoms with hematuria should be evaluated in conjunction with the urinary symptoms and LUTS module.","kind":"integration","linkedModuleIds":["fcp1-urinary-symptoms-luts"],"origin":"ai"}],"fcp1-eye-red-eye":[{"id":"fcp1-eye-red-eye~ai-0","moduleId":"fcp1-eye-red-eye","stem":"A 25-year-old patient presents with a painful red eye, photophobia, and a small irregular pupil. Which condition is most likely?","options":[{"id":"a","text":"Conjunctivitis"},{"id":"b","text":"Acute angle-closure glaucoma"},{"id":"c","text":"Anterior uveitis"},{"id":"d","text":"Keratitis"}],"answerId":"c","explanation":"Anterior uveitis presents with pain, photophobia, and a small irregular pupil.","kind":"recall","origin":"ai"},{"id":"fcp1-eye-red-eye~ai-1","moduleId":"fcp1-eye-red-eye","stem":"A patient with a red eye reports seeing haloes around lights and has a fixed mid-dilated pupil. What is the most likely diagnosis?","options":[{"id":"a","text":"Conjunctivitis"},{"id":"b","text":"Acute angle-closure glaucoma"},{"id":"c","text":"Keratitis"},{"id":"d","text":"Anterior uveitis"}],"answerId":"b","explanation":"Acute angle-closure glaucoma is characterized by haloes, a fixed mid-dilated pupil, and a hard globe.","kind":"recall","origin":"ai"},{"id":"fcp1-eye-red-eye~ai-2","moduleId":"fcp1-eye-red-eye","stem":"A 30-year-old contact lens wearer presents with a painful red eye and a fluorescein-staining corneal defect. What is the most appropriate next step?","options":[{"id":"a","text":"Prescribe steroid eye drops"},{"id":"b","text":"Refer urgently to ophthalmology"},{"id":"c","text":"Prescribe antibiotic eye drops"},{"id":"d","text":"Advise cold compresses"}],"answerId":"b","explanation":"Keratitis with a corneal defect requires urgent ophthalmology referral; steroids are contraindicated.","kind":"trap","origin":"ai"},{"id":"fcp1-eye-red-eye~ai-3","moduleId":"fcp1-eye-red-eye","stem":"Which of the following symptoms would most likely indicate a sight-threatening cause of red eye?","options":[{"id":"a","text":"Itchiness"},{"id":"b","text":"Gritty sensation"},{"id":"c","text":"Photophobia"},{"id":"d","text":"Mild discharge"}],"answerId":"c","explanation":"Photophobia suggests a sight-threatening condition such as uveitis or keratitis.","kind":"mechanism","origin":"ai"},{"id":"fcp1-eye-red-eye~ai-4","moduleId":"fcp1-eye-red-eye","stem":"A patient presents with bilateral red eyes, watery discharge, and normal vision. What is the most likely diagnosis?","options":[{"id":"a","text":"Bacterial conjunctivitis"},{"id":"b","text":"Viral conjunctivitis"},{"id":"c","text":"Acute angle-closure glaucoma"},{"id":"d","text":"Anterior uveitis"}],"answerId":"b","explanation":"Viral conjunctivitis often presents bilaterally with watery discharge and normal vision.","kind":"recall","origin":"ai"},{"id":"fcp1-eye-red-eye~ai-5","moduleId":"fcp1-eye-red-eye","stem":"A patient with a history of HLA-B27 presents with a painful red eye and ciliary flush. Which systemic condition is most likely associated?","options":[{"id":"a","text":"Rheumatoid arthritis"},{"id":"b","text":"Ankylosing spondylitis"},{"id":"c","text":"Diabetes mellitus"},{"id":"d","text":"Hypertension"}],"answerId":"b","explanation":"Anterior uveitis is often associated with HLA-B27 and conditions like ankylosing spondylitis.","kind":"integration","linkedModuleIds":["fcp1-eye-vision-loss"],"origin":"ai"},{"id":"fcp1-eye-red-eye~ai-6","moduleId":"fcp1-eye-red-eye","stem":"A 40-year-old patient presents with sudden vision loss and a red eye. Which of the following should be considered first?","options":[{"id":"a","text":"Conjunctivitis"},{"id":"b","text":"Retinal detachment"},{"id":"c","text":"Acute angle-closure glaucoma"},{"id":"d","text":"Optic neuritis"}],"answerId":"c","explanation":"Acute angle-closure glaucoma can cause sudden vision loss and is an emergency.","kind":"integration","linkedModuleIds":["optic-nerve-disc-edema"],"origin":"ai"}],"fcp1-eye-vision-loss":[{"id":"fcp1-eye-vision-loss~ai-0","moduleId":"fcp1-eye-vision-loss","stem":"A 65-year-old man presents with sudden, painless loss of vision in his left eye. Fundoscopic examination reveals a pale retina with a cherry-red spot. What is the most likely diagnosis?","options":[{"id":"a","text":"Central retinal artery occlusion"},{"id":"b","text":"Central retinal vein occlusion"},{"id":"c","text":"Retinal detachment"},{"id":"d","text":"Vitreous haemorrhage"}],"answerId":"a","explanation":"The pale retina with a cherry-red spot is characteristic of central retinal artery occlusion.","kind":"recall","origin":"ai"},{"id":"fcp1-eye-vision-loss~ai-1","moduleId":"fcp1-eye-vision-loss","stem":"A 30-year-old woman experiences sudden vision loss in her right eye accompanied by pain on eye movement. She also reports reduced color vision. What is the most likely diagnosis?","options":[{"id":"a","text":"Optic neuritis"},{"id":"b","text":"Acute angle-closure glaucoma"},{"id":"c","text":"Retinal detachment"},{"id":"d","text":"Vitreous haemorrhage"}],"answerId":"a","explanation":"Pain on eye movement with reduced color vision suggests optic neuritis, often associated with demyelination.","kind":"clinical","origin":"ai"},{"id":"fcp1-eye-vision-loss~ai-2","moduleId":"fcp1-eye-vision-loss","stem":"Which of the following findings is most indicative of central retinal vein occlusion?","options":[{"id":"a","text":"Pale retina with a cherry-red spot"},{"id":"b","text":"Widespread retinal haemorrhages with dilated tortuous veins"},{"id":"c","text":"Flashes and floaters with a curtain over the field"},{"id":"d","text":"Pain on eye movement with reduced color vision"}],"answerId":"b","explanation":"Widespread retinal haemorrhages with dilated tortuous veins are characteristic of central retinal vein occlusion.","kind":"recall","origin":"ai"},{"id":"fcp1-eye-vision-loss~ai-3","moduleId":"fcp1-eye-vision-loss","stem":"A patient reports a transient 'curtain coming down' over their vision lasting a few minutes. What is the most appropriate next step?","options":[{"id":"a","text":"Reassure and discharge"},{"id":"b","text":"Urgent carotid and cardiovascular workup"},{"id":"c","text":"Prescribe topical antibiotics"},{"id":"d","text":"Schedule routine follow-up"}],"answerId":"b","explanation":"Transient monocular vision loss, or amaurosis fugax, is a retinal TIA and requires urgent stroke/carotid workup.","kind":"trap","origin":"ai"},{"id":"fcp1-eye-vision-loss~ai-4","moduleId":"fcp1-eye-vision-loss","stem":"A 70-year-old woman presents with sudden, painless vision loss in one eye. Fundoscopy shows a 'blood-and-thunder' appearance. What is the most likely underlying cause?","options":[{"id":"a","text":"Embolic event"},{"id":"b","text":"Venous occlusion"},{"id":"c","text":"Retinal tear"},{"id":"d","text":"Optic nerve inflammation"}],"answerId":"b","explanation":"The 'blood-and-thunder' appearance is indicative of central retinal vein occlusion, which is due to venous occlusion.","kind":"mechanism","origin":"ai"},{"id":"fcp1-eye-vision-loss~ai-5","moduleId":"fcp1-eye-vision-loss","stem":"In a patient with acute vision loss and a pale retina with a cherry-red spot, which linked condition should be urgently considered?","options":[{"id":"a","text":"Giant cell arteritis"},{"id":"b","text":"Migraine with aura"},{"id":"c","text":"Diabetic retinopathy"},{"id":"d","text":"Keratitis"}],"answerId":"a","explanation":"In older patients with central retinal artery occlusion, giant cell arteritis should be excluded.","kind":"integration","linkedModuleIds":["fcp1-headache-red-flags"],"origin":"ai"},{"id":"fcp1-eye-vision-loss~ai-6","moduleId":"fcp1-eye-vision-loss","stem":"A 55-year-old man with a history of hypertension presents with sudden, painless vision loss. Fundoscopy reveals widespread retinal hemorrhages. Which linked module provides further information on this condition?","options":[{"id":"a","text":"fcp1-headache-red-flags"},{"id":"b","text":"retinal-vascular-occlusions"},{"id":"c","text":"visual-phototransduction"},{"id":"d","text":"fcp1-eye-red-eye"}],"answerId":"b","explanation":"The 'blood-and-thunder' appearance is characteristic of central retinal vein occlusion, covered in the retinal vascular occlusions module.","kind":"integration","linkedModuleIds":["retinal-vascular-occlusions"],"origin":"ai"}],"fcp1-ent-red-flags":[{"id":"fcp1-ent-red-flags~ai-0","moduleId":"fcp1-ent-red-flags","stem":"A 55-year-old smoker presents with persistent hoarseness for 4 weeks. What is the most appropriate next step?","options":[{"id":"a","text":"Urgent laryngoscopy"},{"id":"b","text":"Empirical antibiotics"},{"id":"c","text":"Voice rest and follow-up in 2 weeks"},{"id":"d","text":"CT scan of the neck"}],"answerId":"a","explanation":"Persistent hoarseness in a smoker is a red flag for head-and-neck cancer, requiring urgent laryngoscopy.","kind":"clinical","origin":"ai"},{"id":"fcp1-ent-red-flags~ai-1","moduleId":"fcp1-ent-red-flags","stem":"A 60-year-old man presents with a unilateral tonsillar enlargement. What should be the primary concern?","options":[{"id":"a","text":"Tonsillitis"},{"id":"b","text":"Peritonsillar abscess"},{"id":"c","text":"Malignancy"},{"id":"d","text":"Benign hyperplasia"}],"answerId":"c","explanation":"Unilateral tonsillar enlargement is a red flag for malignancy until proven otherwise.","kind":"recall","origin":"ai"},{"id":"fcp1-ent-red-flags~ai-2","moduleId":"fcp1-ent-red-flags","stem":"Which of the following is a red flag symptom that suggests nasopharyngeal cancer?","options":[{"id":"a","text":"Bilateral nasal obstruction"},{"id":"b","text":"Unilateral nasal obstruction"},{"id":"c","text":"Intermittent epistaxis"},{"id":"d","text":"Chronic sinusitis"}],"answerId":"b","explanation":"Unilateral nasal obstruction is a red flag for a sinonasal or nasopharyngeal tumour.","kind":"recall","origin":"ai"},{"id":"fcp1-ent-red-flags~ai-3","moduleId":"fcp1-ent-red-flags","stem":"A 45-year-old man with a history of smoking presents with a persistent level II neck node. What is the recommended initial diagnostic approach?","options":[{"id":"a","text":"Excisional biopsy"},{"id":"b","text":"Fine-needle aspiration"},{"id":"c","text":"Empirical antibiotics"},{"id":"d","text":"Observation for 2 weeks"}],"answerId":"b","explanation":"Fine-needle aspiration is recommended to avoid seeding and compromising further treatment.","kind":"trap","origin":"ai"},{"id":"fcp1-ent-red-flags~ai-4","moduleId":"fcp1-ent-red-flags","stem":"A 30-year-old patient presents with sudden sensorineural hearing loss. What is the urgency of treatment?","options":[{"id":"a","text":"Treat within days"},{"id":"b","text":"Treat within weeks"},{"id":"c","text":"No urgent treatment needed"},{"id":"d","text":"Treat within months"}],"answerId":"a","explanation":"Sudden sensorineural hearing loss requires treatment within days to prevent permanent loss.","kind":"recall","origin":"ai"},{"id":"fcp1-ent-red-flags~ai-5","moduleId":"fcp1-ent-red-flags","stem":"A 50-year-old male with dysphagia and a neck mass is suspected of having a malignancy. Which linked module provides the approach to work up dysphagia?","options":[{"id":"a","text":"fcp1-dysphagia"},{"id":"b","text":"fcp1-ent-common-symptoms"},{"id":"c","text":"swallowing-phases-reflex"},{"id":"d","text":"fcp1-fever-approach-differential"}],"answerId":"a","explanation":"The 'Approach to Dysphagia' module provides guidance on working up dysphagia.","kind":"integration","linkedModuleIds":["fcp1-dysphagia"],"origin":"ai"},{"id":"fcp1-ent-red-flags~ai-6","moduleId":"fcp1-ent-red-flags","stem":"Which symptom would prompt an urgent referral due to the risk of intracranial complications?","options":[{"id":"a","text":"Proptosis"},{"id":"b","text":"Bilateral nasal obstruction"},{"id":"c","text":"Chronic cough"},{"id":"d","text":"Intermittent tinnitus"}],"answerId":"a","explanation":"Proptosis can indicate orbital or intracranial spread of a sinus infection, requiring urgent referral.","kind":"clinical","origin":"ai"},{"id":"fcp1-ent-red-flags~ai-7","moduleId":"fcp1-ent-red-flags","stem":"A patient presents with fever and lymphadenopathy. Which linked module should be consulted for a differential diagnosis approach?","options":[{"id":"a","text":"fcp1-dysphagia"},{"id":"b","text":"fcp1-ent-common-symptoms"},{"id":"c","text":"fcp1-fever-approach-differential"},{"id":"d","text":"swallowing-phases-reflex"}],"answerId":"c","explanation":"The 'Approach to Acute Fever' module provides guidance on differential diagnosis for fever with lymphadenopathy.","kind":"integration","linkedModuleIds":["fcp1-fever-approach-differential"],"origin":"ai"}],"fcp1-pelvic-pain-approach":[{"id":"fcp1-pelvic-pain-approach~ai-0","moduleId":"fcp1-pelvic-pain-approach","stem":"A 30-year-old woman presents with sudden severe right lower quadrant pain and vomiting. On examination, there is a tender adnexal mass. What is the most appropriate next step?","options":[{"id":"a","text":"Doppler ultrasound"},{"id":"b","text":"CT scan of the abdomen"},{"id":"c","text":"MRI of the pelvis"},{"id":"d","text":"Immediate surgical exploration"}],"answerId":"a","explanation":"Doppler ultrasound is used to assess blood flow and is the first step in evaluating suspected ovarian torsion.","kind":"clinical","origin":"ai"},{"id":"fcp1-pelvic-pain-approach~ai-1","moduleId":"fcp1-pelvic-pain-approach","stem":"A 25-year-old woman presents with bilateral lower abdominal pain, fever, and cervical motion tenderness. What is the most likely diagnosis?","options":[{"id":"a","text":"Ectopic pregnancy"},{"id":"b","text":"Ovarian torsion"},{"id":"c","text":"Pelvic inflammatory disease"},{"id":"d","text":"Ruptured ovarian cyst"}],"answerId":"c","explanation":"The presence of bilateral pain, fever, and cervical motion tenderness is indicative of pelvic inflammatory disease.","kind":"recall","origin":"ai"},{"id":"fcp1-pelvic-pain-approach~ai-2","moduleId":"fcp1-pelvic-pain-approach","stem":"A patient with a positive β-hCG test presents with adnexal tenderness. Which condition must be ruled out first?","options":[{"id":"a","text":"Ovarian torsion"},{"id":"b","text":"Pelvic inflammatory disease"},{"id":"c","text":"Ectopic pregnancy"},{"id":"d","text":"Endometriosis"}],"answerId":"c","explanation":"A positive β-hCG with adnexal tenderness suggests ectopic pregnancy, which is a life-threatening condition that must be excluded.","kind":"trap","origin":"ai"},{"id":"fcp1-pelvic-pain-approach~ai-3","moduleId":"fcp1-pelvic-pain-approach","stem":"A 28-year-old woman has chronic pelvic pain, dysmenorrhea, and dyspareunia. On examination, there is tender nodularity in the pelvis. What is the most likely diagnosis?","options":[{"id":"a","text":"Adenomyosis"},{"id":"b","text":"Endometriosis"},{"id":"c","text":"Interstitial cystitis"},{"id":"d","text":"Irritable bowel syndrome"}],"answerId":"b","explanation":"The combination of chronic pelvic pain, dysmenorrhea, dyspareunia, and tender nodularity is characteristic of endometriosis.","kind":"recall","origin":"ai"},{"id":"fcp1-pelvic-pain-approach~ai-4","moduleId":"fcp1-pelvic-pain-approach","stem":"A 32-year-old woman with a history of endometriosis presents with abnormal uterine bleeding. Which module should be consulted for further evaluation?","options":[{"id":"a","text":"The Acute Abdomen"},{"id":"b","text":"The OB-Gyne History"},{"id":"c","text":"Abnormal Uterine Bleeding"},{"id":"d","text":"Approach to Abdominal Pain"}],"answerId":"c","explanation":"The 'Abnormal Uterine Bleeding' module provides guidance on evaluating and managing abnormal bleeding.","kind":"integration","linkedModuleIds":["hrp2-abnormal-uterine-bleeding"],"origin":"ai"},{"id":"fcp1-pelvic-pain-approach~ai-5","moduleId":"fcp1-pelvic-pain-approach","stem":"A 35-year-old woman presents with acute pelvic pain and a palpable pelvic mass. Which module would assist in further evaluation of the mass?","options":[{"id":"a","text":"The Acute Abdomen"},{"id":"b","text":"Approach to a Pelvic Mass"},{"id":"c","text":"The OB-Gyne History"},{"id":"d","text":"Approach to Abdominal Pain"}],"answerId":"b","explanation":"The 'Approach to a Pelvic Mass' module is relevant for evaluating a palpable pelvic mass.","kind":"integration","linkedModuleIds":["fcp1-pelvic-mass-approach"],"origin":"ai"}],"fcp1-pelvic-mass-approach":[{"id":"fcp1-pelvic-mass-approach~ai-0","moduleId":"fcp1-pelvic-mass-approach","stem":"A 45-year-old woman presents with a pelvic mass. Ultrasound shows a firm, irregular mass that moves with the cervix and uterus. What is the most likely diagnosis?","options":[{"id":"a","text":"Uterine fibroid (leiomyoma)"},{"id":"b","text":"Ovarian cyst"},{"id":"c","text":"Ovarian malignancy"},{"id":"d","text":"Full bladder"}],"answerId":"a","explanation":"A firm, irregular mass that moves with the cervix and uterus is characteristic of a uterine fibroid.","kind":"recall","origin":"ai"},{"id":"fcp1-pelvic-mass-approach~ai-1","moduleId":"fcp1-pelvic-mass-approach","stem":"A 60-year-old postmenopausal woman presents with a pelvic mass. Ultrasound reveals a solid, fixed mass with ascites. What is the most appropriate next step?","options":[{"id":"a","text":"Observation and follow-up ultrasound"},{"id":"b","text":"CA-125 measurement and referral to gynae-oncology"},{"id":"c","text":"Immediate surgical removal"},{"id":"d","text":"Hormonal therapy"}],"answerId":"b","explanation":"A solid, fixed mass with ascites in a postmenopausal woman raises suspicion for malignancy; CA-125 and referral are warranted.","kind":"trap","origin":"ai"},{"id":"fcp1-pelvic-mass-approach~ai-2","moduleId":"fcp1-pelvic-mass-approach","stem":"A 25-year-old woman presents with a mobile, smooth, unilateral adnexal mass on ultrasound. What is the most likely diagnosis?","options":[{"id":"a","text":"Benign ovarian cyst"},{"id":"b","text":"Ovarian malignancy"},{"id":"c","text":"Uterine fibroid"},{"id":"d","text":"Full bladder"}],"answerId":"a","explanation":"A mobile, smooth, unilateral adnexal mass is typical of a benign ovarian cyst.","kind":"recall","origin":"ai"},{"id":"fcp1-pelvic-mass-approach~ai-3","moduleId":"fcp1-pelvic-mass-approach","stem":"Which of the following features is most indicative of a malignant ovarian tumor?","options":[{"id":"a","text":"Unilateral, cystic, mobile mass"},{"id":"b","text":"Solid or complex, bilateral, fixed mass"},{"id":"c","text":"Smooth, premenopausal mass"},{"id":"d","text":"Mobile, smooth, unilateral mass"}],"answerId":"b","explanation":"A solid or complex, bilateral, fixed mass is indicative of a malignant ovarian tumor.","kind":"mechanism","origin":"ai"},{"id":"fcp1-pelvic-mass-approach~ai-4","moduleId":"fcp1-pelvic-mass-approach","stem":"A 30-year-old woman with a history of heavy menstrual bleeding presents with a pelvic mass. Which linked module would help in further evaluating her condition?","options":[{"id":"a","text":"fcp1-abnormal-vaginal-bleeding"},{"id":"b","text":"fcp1-abdominal-mass-differential"},{"id":"c","text":"hrp2-abnormal-uterine-bleeding"},{"id":"d","text":"fcp1-pelvic-pain-approach"}],"answerId":"a","explanation":"The module 'Approach to Abnormal Vaginal Bleeding' is relevant for evaluating heavy menstrual bleeding.","kind":"integration","linkedModuleIds":["fcp1-abnormal-vaginal-bleeding"],"origin":"ai"},{"id":"fcp1-pelvic-mass-approach~ai-5","moduleId":"fcp1-pelvic-mass-approach","stem":"A 50-year-old woman presents with a pelvic mass and weight loss. Which initial imaging modality is most appropriate?","options":[{"id":"a","text":"CT scan"},{"id":"b","text":"MRI"},{"id":"c","text":"Transvaginal ultrasound"},{"id":"d","text":"X-ray"}],"answerId":"c","explanation":"Transvaginal ultrasound is the first-line imaging for evaluating a pelvic mass.","kind":"recall","origin":"ai"},{"id":"fcp1-pelvic-mass-approach~ai-6","moduleId":"fcp1-pelvic-mass-approach","stem":"A 35-year-old woman presents with pelvic pain and a mass. Which linked module would assist in differentiating the cause of her symptoms?","options":[{"id":"a","text":"fcp1-abdominal-mass-differential"},{"id":"b","text":"fcp1-abdominal-mass-approach"},{"id":"c","text":"fcp1-pelvic-pain-approach"},{"id":"d","text":"hrp2-abnormal-uterine-bleeding"}],"answerId":"c","explanation":"The module 'Approach to Pelvic Pain' helps differentiate causes of pelvic pain with a mass.","kind":"integration","linkedModuleIds":["fcp1-pelvic-pain-approach"],"origin":"ai"}],"fcp1-urinary-symptoms-luts":[{"id":"fcp1-urinary-symptoms-luts~ai-0","moduleId":"fcp1-urinary-symptoms-luts","stem":"A 65-year-old man presents with difficulty initiating urination, a weak stream, and nocturia. Digital rectal examination reveals a smooth, symmetrically enlarged prostate. What is the most likely diagnosis?","options":[{"id":"a","text":"Benign prostatic hyperplasia"},{"id":"b","text":"Prostate cancer"},{"id":"c","text":"Urethral stricture"},{"id":"d","text":"Bladder stone"}],"answerId":"a","explanation":"The symptoms and examination findings are classic for benign prostatic hyperplasia.","kind":"clinical","origin":"ai"},{"id":"fcp1-urinary-symptoms-luts~ai-1","moduleId":"fcp1-urinary-symptoms-luts","stem":"A patient presents with dysuria, frequency, and urgency. Urinalysis shows pyuria and bacteriuria. What is the most likely diagnosis?","options":[{"id":"a","text":"Cystitis"},{"id":"b","text":"Urethritis"},{"id":"c","text":"Prostatitis"},{"id":"d","text":"Pyelonephritis"}],"answerId":"a","explanation":"The presence of dysuria, frequency, urgency, and urinalysis findings suggest cystitis.","kind":"recall","origin":"ai"},{"id":"fcp1-urinary-symptoms-luts~ai-2","moduleId":"fcp1-urinary-symptoms-luts","stem":"A 70-year-old man with a history of BPH presents with acute urinary retention. Which of the following is the most appropriate immediate management?","options":[{"id":"a","text":"Oral alpha-blocker"},{"id":"b","text":"Immediate catheterization"},{"id":"c","text":"Surgical intervention"},{"id":"d","text":"Watchful waiting"}],"answerId":"b","explanation":"Acute urinary retention requires immediate catheterization to relieve the obstruction.","kind":"clinical","origin":"ai"},{"id":"fcp1-urinary-symptoms-luts~ai-3","moduleId":"fcp1-urinary-symptoms-luts","stem":"A 55-year-old male presents with painless hematuria. Which of the following should be included in the initial workup?","options":[{"id":"a","text":"Urine culture"},{"id":"b","text":"Cystoscopy"},{"id":"c","text":"Prostate-specific antigen (PSA) test"},{"id":"d","text":"Renal ultrasound"}],"answerId":"b","explanation":"Painless hematuria warrants cystoscopy to rule out bladder cancer.","kind":"trap","linkedModuleIds":["fcp1-hematuria-approach"],"origin":"ai"},{"id":"fcp1-urinary-symptoms-luts~ai-4","moduleId":"fcp1-urinary-symptoms-luts","stem":"A patient with a neurogenic bladder presents with overflow incontinence. Which of the following mechanisms is most likely involved?","options":[{"id":"a","text":"Detrusor overactivity"},{"id":"b","text":"Detrusor underactivity"},{"id":"c","text":"Urethral hypertonicity"},{"id":"d","text":"Bladder outlet obstruction"}],"answerId":"b","explanation":"Detrusor underactivity in neurogenic bladder can lead to overflow incontinence.","kind":"integration","linkedModuleIds":["neurogenic-bladder-disorders"],"origin":"ai"},{"id":"fcp1-urinary-symptoms-luts~ai-5","moduleId":"fcp1-urinary-symptoms-luts","stem":"Which of the following findings on digital rectal examination is most suggestive of prostate cancer?","options":[{"id":"a","text":"Smooth, symmetrically enlarged prostate"},{"id":"b","text":"Hard, irregular, nodular prostate"},{"id":"c","text":"Tender, boggy prostate"},{"id":"d","text":"Normal prostate"}],"answerId":"b","explanation":"A hard, irregular, nodular prostate is suspicious for prostate cancer.","kind":"recall","origin":"ai"},{"id":"fcp1-urinary-symptoms-luts~ai-6","moduleId":"fcp1-urinary-symptoms-luts","stem":"A 60-year-old male with a history of diabetes presents with urinary frequency and urgency. Which condition might be contributing to his symptoms?","options":[{"id":"a","text":"Benign prostatic hyperplasia"},{"id":"b","text":"Overactive bladder"},{"id":"c","text":"Urethral stricture"},{"id":"d","text":"Neurogenic bladder"}],"answerId":"d","explanation":"Diabetes can lead to neurogenic bladder, causing frequency and urgency.","kind":"integration","linkedModuleIds":["micturition-reflex"],"origin":"ai"}],"fcp1-sexual-assault-forensic":[{"id":"fcp1-sexual-assault-forensic~ai-0","moduleId":"fcp1-sexual-assault-forensic","stem":"What is the primary role of a physician during a forensic examination following a sexual assault?","options":[{"id":"a","text":"Therapeutic care of the survivor"},{"id":"b","text":"Collection of forensic evidence"},{"id":"c","text":"Providing legal conclusions"},{"id":"d","text":"Ensuring conviction of the perpetrator"}],"answerId":"a","explanation":"The physician's primary role is the therapeutic care of the survivor, although they also collect forensic evidence.","kind":"recall","origin":"ai"},{"id":"fcp1-sexual-assault-forensic~ai-1","moduleId":"fcp1-sexual-assault-forensic","stem":"Which of the following is required for the forensic examination and release of evidence in a sexual assault case?","options":[{"id":"a","text":"General consent"},{"id":"b","text":"Specific informed consent"},{"id":"c","text":"Verbal agreement"},{"id":"d","text":"Implied consent"}],"answerId":"b","explanation":"Specific informed consent is needed for each element of the forensic examination and release of evidence.","kind":"recall","origin":"ai"},{"id":"fcp1-sexual-assault-forensic~ai-2","moduleId":"fcp1-sexual-assault-forensic","stem":"What could render forensic evidence inadmissible in court?","options":[{"id":"a","text":"A well-documented injury"},{"id":"b","text":"An unexplained break in the chain of custody"},{"id":"c","text":"A toxicology report"},{"id":"d","text":"A signed consent form"}],"answerId":"b","explanation":"An unexplained break in the chain of custody can make the evidence inadmissible.","kind":"trap","origin":"ai"},{"id":"fcp1-sexual-assault-forensic~ai-3","moduleId":"fcp1-sexual-assault-forensic","stem":"Why is it important to record the survivor's account in their own words during a forensic examination?","options":[{"id":"a","text":"To avoid misinterpretation"},{"id":"b","text":"To simplify documentation"},{"id":"c","text":"To expedite the legal process"},{"id":"d","text":"To provide a legal conclusion"}],"answerId":"a","explanation":"Recording the survivor's account in their own words preserves accuracy and avoids interpretation.","kind":"mechanism","origin":"ai"},{"id":"fcp1-sexual-assault-forensic~ai-4","moduleId":"fcp1-sexual-assault-forensic","stem":"In the context of a forensic examination, what is the purpose of using tamper-evident seals on specimens?","options":[{"id":"a","text":"To prevent contamination"},{"id":"b","text":"To maintain the chain of custody"},{"id":"c","text":"To simplify storage"},{"id":"d","text":"To ensure faster processing"}],"answerId":"b","explanation":"Tamper-evident seals help maintain the chain of custody by proving the sample was not tampered with.","kind":"mechanism","origin":"ai"},{"id":"fcp1-sexual-assault-forensic~ai-5","moduleId":"fcp1-sexual-assault-forensic","stem":"How does the documentation of injuries on a body map aid in the forensic examination process?","options":[{"id":"a","text":"It provides a subjective record"},{"id":"b","text":"It creates an objective record"},{"id":"c","text":"It offers a legal opinion"},{"id":"d","text":"It simplifies the examination"}],"answerId":"b","explanation":"Documenting injuries on a body map creates an objective record that is admissible in court.","kind":"mechanism","origin":"ai"},{"id":"fcp1-sexual-assault-forensic~ai-6","moduleId":"fcp1-sexual-assault-forensic","stem":"Which legal consideration must be taken into account when dealing with minors in a forensic examination for sexual assault?","options":[{"id":"a","text":"Confidentiality without exception"},{"id":"b","text":"Mandatory reporting"},{"id":"c","text":"Parental consent only"},{"id":"d","text":"No documentation required"}],"answerId":"b","explanation":"Mandatory reporting applies to minors and vulnerable adults in cases of sexual assault.","kind":"integration","linkedModuleIds":["fcp1-medical-law-thailand"],"origin":"ai"},{"id":"fcp1-sexual-assault-forensic~ai-7","moduleId":"fcp1-sexual-assault-forensic","stem":"In cases of suspected drug-facilitated sexual assault, why is timely toxicology sampling crucial?","options":[{"id":"a","text":"To confirm the identity of the perpetrator"},{"id":"b","text":"To detect sedating agents with short detection windows"},{"id":"c","text":"To provide immediate medical treatment"},{"id":"d","text":"To expedite legal proceedings"}],"answerId":"b","explanation":"Timely toxicology sampling is crucial to detect sedating agents, which may have short detection windows.","kind":"clinical","origin":"ai"},{"id":"fcp1-sexual-assault-forensic~ai-8","moduleId":"fcp1-sexual-assault-forensic","stem":"How does the requirement for specific informed consent in forensic examinations relate to broader medical consent practices?","options":[{"id":"a","text":"It is less stringent than general medical consent"},{"id":"b","text":"It requires more detailed explanation and documentation"},{"id":"c","text":"It allows for implied consent in emergencies"},{"id":"d","text":"It is identical to general medical consent"}],"answerId":"b","explanation":"Specific informed consent in forensic examinations requires more detailed explanation and documentation compared to general medical consent.","kind":"integration","origin":"ai"}],"fcp1-medical-ethics-principles":[{"id":"fcp1-medical-ethics-principles~ai-0","moduleId":"fcp1-medical-ethics-principles","stem":"A 45-year-old competent patient with a severe infection refuses antibiotic treatment despite understanding the risks. Which ethical principle is primarily being respected by honoring this refusal?","options":[{"id":"a","text":"Autonomy"},{"id":"b","text":"Beneficence"},{"id":"c","text":"Non-maleficence"},{"id":"d","text":"Justice"}],"answerId":"a","explanation":"Autonomy respects the patient's right to make informed decisions about their own care.","kind":"recall","origin":"ai"},{"id":"fcp1-medical-ethics-principles~ai-1","moduleId":"fcp1-medical-ethics-principles","stem":"In a situation where a new, expensive medication is available but resources are limited, which principle should guide the decision to allocate this medication?","options":[{"id":"a","text":"Autonomy"},{"id":"b","text":"Beneficence"},{"id":"c","text":"Non-maleficence"},{"id":"d","text":"Justice"}],"answerId":"d","explanation":"Justice involves fair resource allocation based on clinical need rather than social status.","kind":"mechanism","origin":"ai"},{"id":"fcp1-medical-ethics-principles~ai-2","moduleId":"fcp1-medical-ethics-principles","stem":"A physician decides not to disclose a terminal diagnosis to a patient because they believe it will cause harm. Which principle is being compromised?","options":[{"id":"a","text":"Autonomy"},{"id":"b","text":"Beneficence"},{"id":"c","text":"Non-maleficence"},{"id":"d","text":"Justice"}],"answerId":"a","explanation":"Withholding information breaches the principle of autonomy, which includes truth-telling.","kind":"trap","origin":"ai"},{"id":"fcp1-medical-ethics-principles~ai-3","moduleId":"fcp1-medical-ethics-principles","stem":"A patient refuses a blood transfusion due to religious beliefs. The medical team respects this decision despite the potential for harm. Which two principles are in conflict here?","options":[{"id":"a","text":"Autonomy and Beneficence"},{"id":"b","text":"Beneficence and Justice"},{"id":"c","text":"Non-maleficence and Justice"},{"id":"d","text":"Autonomy and Non-maleficence"}],"answerId":"a","explanation":"Autonomy (respecting the patient's decision) conflicts with beneficence (acting in the patient's best interest).","kind":"clinical","origin":"ai"},{"id":"fcp1-medical-ethics-principles~ai-4","moduleId":"fcp1-medical-ethics-principles","stem":"A doctor is considering whether to breach confidentiality to warn a third party about a patient's contagious disease. Which linked module provides guidance on the legal limits of confidentiality?","options":[{"id":"a","text":"fcp1-medical-negligence-confidentiality"},{"id":"b","text":"fcp1-medical-law-thailand"},{"id":"c","text":"fcp1-professionalism-consent"},{"id":"d","text":"fcp1-sexual-assault-medical"}],"answerId":"a","explanation":"The module on medical negligence and confidentiality discusses the legal limits of confidentiality.","kind":"integration","linkedModuleIds":["fcp1-medical-negligence-confidentiality"],"origin":"ai"},{"id":"fcp1-medical-ethics-principles~ai-5","moduleId":"fcp1-medical-ethics-principles","stem":"A patient provides informed consent for a procedure after a thorough discussion with their physician. Which linked module focuses on the process of obtaining informed consent?","options":[{"id":"a","text":"fcp1-medical-negligence-confidentiality"},{"id":"b","text":"fcp1-medical-law-thailand"},{"id":"c","text":"fcp1-professionalism-consent"},{"id":"d","text":"fcp1-sexual-assault-medical"}],"answerId":"c","explanation":"The module on professionalism and informed consent covers the process of obtaining informed consent.","kind":"integration","linkedModuleIds":["fcp1-professionalism-consent"],"origin":"ai"}],"fcp1-professionalism-consent":[{"id":"fcp1-professionalism-consent~ai-0","moduleId":"fcp1-professionalism-consent","stem":"Which of the following is NOT a requirement for valid informed consent?","options":[{"id":"a","text":"Capacity"},{"id":"b","text":"Disclosure"},{"id":"c","text":"Voluntariness"},{"id":"d","text":"Signature"}],"answerId":"d","explanation":"A signature is not a requirement for valid informed consent; it is only evidence that consent was given.","kind":"trap","origin":"ai"},{"id":"fcp1-professionalism-consent~ai-1","moduleId":"fcp1-professionalism-consent","stem":"A patient is pressured by their family to undergo a procedure they are hesitant about. Which element of informed consent is compromised?","options":[{"id":"a","text":"Capacity"},{"id":"b","text":"Disclosure"},{"id":"c","text":"Voluntariness"},{"id":"d","text":"Agreement"}],"answerId":"c","explanation":"Voluntariness is compromised when a decision is influenced by external pressure.","kind":"clinical","origin":"ai"},{"id":"fcp1-professionalism-consent~ai-2","moduleId":"fcp1-professionalism-consent","stem":"In an emergency situation where a patient is unconscious, what should a physician do regarding consent?","options":[{"id":"a","text":"Wait for the patient to regain consciousness"},{"id":"b","text":"Obtain consent from a family member"},{"id":"c","text":"Act in the patient's best interests"},{"id":"d","text":"Proceed without any consideration of consent"}],"answerId":"c","explanation":"In emergencies, treatment should proceed in the patient's best interests under the principle of necessity.","kind":"recall","origin":"ai"},{"id":"fcp1-professionalism-consent~ai-3","moduleId":"fcp1-professionalism-consent","stem":"Which of the following scenarios would invalidate informed consent due to inadequate disclosure?","options":[{"id":"a","text":"Patient is informed of all material risks"},{"id":"b","text":"Patient is informed of only common risks"},{"id":"c","text":"Patient is informed of alternative treatments"},{"id":"d","text":"Patient is informed of the procedure's benefits"}],"answerId":"b","explanation":"Inadequate disclosure occurs when only common risks are disclosed and material risks are omitted.","kind":"mechanism","origin":"ai"},{"id":"fcp1-professionalism-consent~ai-4","moduleId":"fcp1-professionalism-consent","stem":"A 16-year-old patient is deemed mature enough to understand the implications of a medical procedure. Which concept allows them to consent?","options":[{"id":"a","text":"Parental consent"},{"id":"b","text":"Mature minor doctrine"},{"id":"c","text":"Best interests"},{"id":"d","text":"Voluntariness"}],"answerId":"b","explanation":"The mature minor doctrine allows minors who demonstrate sufficient understanding to consent to medical treatment.","kind":"recall","origin":"ai"},{"id":"fcp1-professionalism-consent~ai-5","moduleId":"fcp1-professionalism-consent","stem":"How does the principle of 'duty of candour' relate to informed consent?","options":[{"id":"a","text":"It requires full disclosure of all medical errors"},{"id":"b","text":"It mandates obtaining consent from all family members"},{"id":"c","text":"It ensures confidentiality is maintained"},{"id":"d","text":"It allows for treatment without consent in emergencies"}],"answerId":"a","explanation":"The duty of candour requires healthcare professionals to be honest with patients, including full disclosure of medical errors.","kind":"integration","linkedModuleIds":["fcp1-medical-negligence-confidentiality"],"origin":"ai"},{"id":"fcp1-professionalism-consent~ai-6","moduleId":"fcp1-professionalism-consent","stem":"A patient with a history of trauma is undergoing a forensic examination after an assault. How should informed consent be approached?","options":[{"id":"a","text":"Obtain consent only from legal authorities"},{"id":"b","text":"Ensure the patient understands and agrees to each step"},{"id":"c","text":"Proceed without consent due to legal requirements"},{"id":"d","text":"Rely on previous consent forms for similar procedures"}],"answerId":"b","explanation":"Informed consent in a forensic examination should ensure the patient understands and agrees to each step, respecting their autonomy and trauma history.","kind":"integration","linkedModuleIds":["fcp1-sexual-assault-forensic"],"origin":"ai"}],"fcp1-sexual-assault-medical":[{"id":"fcp1-sexual-assault-medical~ai-0","moduleId":"fcp1-sexual-assault-medical","stem":"What is the primary consideration when providing medical care to a sexual assault survivor?","options":[{"id":"a","text":"Treat life-threatening injuries first"},{"id":"b","text":"Collect forensic evidence"},{"id":"c","text":"Obtain a detailed history"},{"id":"d","text":"Perform a complete physical examination"}],"answerId":"a","explanation":"Life-threatening injuries must be addressed before any other considerations, including forensic needs.","kind":"recall","origin":"ai"},{"id":"fcp1-sexual-assault-medical~ai-1","moduleId":"fcp1-sexual-assault-medical","stem":"Which of the following is true regarding genital injuries in sexual assault survivors?","options":[{"id":"a","text":"Genital injuries confirm an assault occurred"},{"id":"b","text":"Absence of genital injuries refutes an assault"},{"id":"c","text":"Most survivors have no visible genital injuries"},{"id":"d","text":"Genital injuries are necessary for legal proceedings"}],"answerId":"c","explanation":"Most survivors have no visible genital injuries, and their absence neither confirms nor refutes an assault.","kind":"trap","origin":"ai"},{"id":"fcp1-sexual-assault-medical~ai-2","moduleId":"fcp1-sexual-assault-medical","stem":"What is the time frame for initiating HIV post-exposure prophylaxis after a sexual assault?","options":[{"id":"a","text":"Within 24 hours"},{"id":"b","text":"Within 48 hours"},{"id":"c","text":"Within 72 hours"},{"id":"d","text":"Within one week"}],"answerId":"c","explanation":"HIV post-exposure prophylaxis should be started as soon as possible, ideally within 72 hours.","kind":"recall","origin":"ai"},{"id":"fcp1-sexual-assault-medical~ai-3","moduleId":"fcp1-sexual-assault-medical","stem":"Which of the following is a key component of trauma-informed care for sexual assault survivors?","options":[{"id":"a","text":"Prioritize forensic evidence collection"},{"id":"b","text":"Ensure privacy and offer a support person"},{"id":"c","text":"Avoid discussing the assault to prevent distress"},{"id":"d","text":"Focus solely on physical injuries"}],"answerId":"b","explanation":"Trauma-informed care involves ensuring privacy and offering a support person, among other considerations.","kind":"mechanism","origin":"ai"},{"id":"fcp1-sexual-assault-medical~ai-4","moduleId":"fcp1-sexual-assault-medical","stem":"In the context of a sexual assault examination, what is the importance of obtaining explicit consent for each step?","options":[{"id":"a","text":"To expedite the examination process"},{"id":"b","text":"To ensure the survivor's autonomy is respected"},{"id":"c","text":"To comply with legal requirements"},{"id":"d","text":"To avoid unnecessary procedures"}],"answerId":"b","explanation":"Explicit consent for each step respects the survivor's autonomy and is a key aspect of trauma-informed care.","kind":"recall","origin":"ai"},{"id":"fcp1-sexual-assault-medical~ai-5","moduleId":"fcp1-sexual-assault-medical","stem":"How does the absence of visible injuries impact the credibility of a sexual assault survivor's account?","options":[{"id":"a","text":"It significantly undermines credibility"},{"id":"b","text":"It has no impact on credibility"},{"id":"c","text":"It confirms the account is false"},{"id":"d","text":"It requires further investigation"}],"answerId":"b","explanation":"The absence of visible injuries does not impact the credibility of a survivor's account.","kind":"trap","origin":"ai"},{"id":"fcp1-sexual-assault-medical~ai-6","moduleId":"fcp1-sexual-assault-medical","stem":"Which of the following actions should be taken first in a sexual assault case involving a minor?","options":[{"id":"a","text":"Begin forensic evidence collection"},{"id":"b","text":"Assess ongoing safety and trigger mandatory reporting"},{"id":"c","text":"Perform a detailed physical examination"},{"id":"d","text":"Start STI prophylaxis"}],"answerId":"b","explanation":"For minors, assessing safety and triggering mandatory reporting is crucial and should be prioritized.","kind":"integration","linkedModuleIds":["hrp1-child-sexual-abuse-response"],"origin":"ai"},{"id":"fcp1-sexual-assault-medical~ai-7","moduleId":"fcp1-sexual-assault-medical","stem":"How does the principle of autonomy apply to the medical care of sexual assault survivors?","options":[{"id":"a","text":"Autonomy is secondary to forensic needs"},{"id":"b","text":"Survivors should make informed decisions about their care"},{"id":"c","text":"Autonomy is not applicable in emergency situations"},{"id":"d","text":"The healthcare provider decides the best course of action"}],"answerId":"b","explanation":"Respecting autonomy means survivors make informed decisions about their care, including consenting to each step.","kind":"integration","linkedModuleIds":["fcp1-medical-ethics-principles"],"origin":"ai"}],"fcp1-medical-law-thailand":[{"id":"fcp1-medical-law-thailand~ai-0","moduleId":"fcp1-medical-law-thailand","stem":"What is the primary function of the Medical Council of Thailand under the Medical Profession Act B.E. 2525 (1982)?","options":[{"id":"a","text":"Licensing physicians"},{"id":"b","text":"Issuing medical certificates"},{"id":"c","text":"Providing healthcare services"},{"id":"d","text":"Conducting medical research"}],"answerId":"a","explanation":"The Medical Council of Thailand is responsible for licensing physicians, setting ethical standards, and exercising discipline.","kind":"recall","origin":"ai"},{"id":"fcp1-medical-law-thailand~ai-1","moduleId":"fcp1-medical-law-thailand","stem":"Under the National Health Act B.E. 2550 (2007), what is required before disclosing a patient's health information?","options":[{"id":"a","text":"Patient's consent or a legal basis"},{"id":"b","text":"Approval from the Medical Council"},{"id":"c","text":"A court order"},{"id":"d","text":"Written request from a family member"}],"answerId":"a","explanation":"The National Health Act requires patient consent or a legal basis for disclosing health information.","kind":"recall","origin":"ai"},{"id":"fcp1-medical-law-thailand~ai-2","moduleId":"fcp1-medical-law-thailand","stem":"A physician is summoned to court to provide a medico-legal report. What is the physician's legal duty in this scenario?","options":[{"id":"a","text":"Ignore the summons"},{"id":"b","text":"Provide the report only if paid"},{"id":"c","text":"Assist as required by law"},{"id":"d","text":"Consult the Medical Council first"}],"answerId":"c","explanation":"Physicians have a legal duty to assist when lawfully summoned to provide medico-legal reports.","kind":"mechanism","origin":"ai"},{"id":"fcp1-medical-law-thailand~ai-3","moduleId":"fcp1-medical-law-thailand","stem":"Which of the following scenarios could lead to a physician's license suspension by the Medical Council?","options":[{"id":"a","text":"Practising without a valid license"},{"id":"b","text":"Disclosing information with patient consent"},{"id":"c","text":"Issuing a medical certificate"},{"id":"d","text":"Treating a patient without charge"}],"answerId":"a","explanation":"Practising without a valid license is an offence under the Medical Profession Act and can lead to suspension.","kind":"recall","origin":"ai"},{"id":"fcp1-medical-law-thailand~ai-4","moduleId":"fcp1-medical-law-thailand","stem":"A physician is found not guilty by the Medical Council for an ethical breach. Can the physician still face civil or criminal proceedings?","options":[{"id":"a","text":"Yes, they are independent processes"},{"id":"b","text":"No, the Council's decision is final"},{"id":"c","text":"Only civil proceedings are possible"},{"id":"d","text":"Only criminal proceedings are possible"}],"answerId":"a","explanation":"Professional, civil, and criminal liabilities are independent; one can proceed without the others.","kind":"trap","origin":"ai"},{"id":"fcp1-medical-law-thailand~ai-5","moduleId":"fcp1-medical-law-thailand","stem":"How does the Medical Council's disciplinary action differ from civil liability in medical negligence cases?","options":[{"id":"a","text":"Disciplinary action is ethical; civil is compensatory"},{"id":"b","text":"Both are compensatory"},{"id":"c","text":"Both are ethical"},{"id":"d","text":"Disciplinary action is criminal; civil is ethical"}],"answerId":"a","explanation":"Disciplinary action addresses ethical breaches, whereas civil liability involves compensation for negligence.","kind":"mechanism","origin":"ai"},{"id":"fcp1-medical-law-thailand~ai-6","moduleId":"fcp1-medical-law-thailand","stem":"In the context of forensic examination in sexual assault cases, what is a physician's primary legal responsibility?","options":[{"id":"a","text":"Preserve evidence and report findings"},{"id":"b","text":"Provide psychological counseling"},{"id":"c","text":"Ensure patient confidentiality only"},{"id":"d","text":"Refer the case to the Medical Council"}],"answerId":"a","explanation":"Physicians must preserve evidence and report findings in forensic examinations for sexual assault cases.","kind":"integration","linkedModuleIds":["fcp1-sexual-assault-forensic"],"origin":"ai"},{"id":"fcp1-medical-law-thailand~ai-7","moduleId":"fcp1-medical-law-thailand","stem":"Which principle of medical ethics is most directly related to the requirement for informed consent?","options":[{"id":"a","text":"Autonomy"},{"id":"b","text":"Beneficence"},{"id":"c","text":"Non-maleficence"},{"id":"d","text":"Justice"}],"answerId":"a","explanation":"Informed consent is primarily related to the principle of autonomy, respecting the patient's right to make decisions.","kind":"integration","linkedModuleIds":["fcp1-medical-ethics-principles"],"origin":"ai"}],"fcp1-medical-negligence-confidentiality":[{"id":"fcp1-medical-negligence-confidentiality~ai-0","moduleId":"fcp1-medical-negligence-confidentiality","stem":"Which of the following is NOT a valid exception to the duty of confidentiality in medical practice?","options":[{"id":"a","text":"A patient's request for disclosure"},{"id":"b","text":"A court order"},{"id":"c","text":"A serious risk of harm to others"},{"id":"d","text":"A colleague's informal inquiry"}],"answerId":"d","explanation":"Confidentiality can be breached with patient consent, legal/statutory requirements, or public interest, but not for informal inquiries.","kind":"recall","origin":"ai"},{"id":"fcp1-medical-negligence-confidentiality~ai-1","moduleId":"fcp1-medical-negligence-confidentiality","stem":"A physician fails to diagnose a condition, but the patient suffers no harm as a result. Which element of negligence is missing?","options":[{"id":"a","text":"Duty of care"},{"id":"b","text":"Breach of duty"},{"id":"c","text":"Causation"},{"id":"d","text":"Damage"}],"answerId":"d","explanation":"Without actual damage, a negligence claim cannot succeed, even if there is a breach of duty.","kind":"mechanism","origin":"ai"},{"id":"fcp1-medical-negligence-confidentiality~ai-2","moduleId":"fcp1-medical-negligence-confidentiality","stem":"A doctor discloses a patient's HIV status to a public health authority. What justifies this action?","options":[{"id":"a","text":"Patient consent"},{"id":"b","text":"Public interest"},{"id":"c","text":"Statutory requirement"},{"id":"d","text":"Court order"}],"answerId":"c","explanation":"Disclosure of notifiable diseases is a statutory requirement, which is a lawful exception to confidentiality.","kind":"clinical","origin":"ai"},{"id":"fcp1-medical-negligence-confidentiality~ai-3","moduleId":"fcp1-medical-negligence-confidentiality","stem":"In a negligence claim, which test is used to establish causation?","options":[{"id":"a","text":"Bolam test"},{"id":"b","text":"But-for test"},{"id":"c","text":"Bolitho test"},{"id":"d","text":"Reasonable person test"}],"answerId":"b","explanation":"The but-for test determines if the harm would not have occurred but for the breach.","kind":"recall","origin":"ai"},{"id":"fcp1-medical-negligence-confidentiality~ai-4","moduleId":"fcp1-medical-negligence-confidentiality","stem":"A physician is sued for negligence after a patient develops complications post-surgery. The court finds that the care provided was consistent with a competent practitioner. What is the likely outcome?","options":[{"id":"a","text":"The physician is liable for negligence"},{"id":"b","text":"The claim fails due to lack of breach"},{"id":"c","text":"The claim succeeds due to causation"},{"id":"d","text":"The physician is liable due to patient harm"}],"answerId":"b","explanation":"If the care met the standard of a competent practitioner, there is no breach, and the negligence claim fails.","kind":"trap","origin":"ai"},{"id":"fcp1-medical-negligence-confidentiality~ai-5","moduleId":"fcp1-medical-negligence-confidentiality","stem":"A patient consents to a procedure after being informed of its risks and benefits. Which ethical principle does this scenario primarily involve?","options":[{"id":"a","text":"Autonomy"},{"id":"b","text":"Beneficence"},{"id":"c","text":"Non-maleficence"},{"id":"d","text":"Justice"}],"answerId":"a","explanation":"Informed consent is primarily based on the principle of autonomy, respecting the patient's right to make decisions.","kind":"integration","linkedModuleIds":["fcp1-professionalism-consent"],"origin":"ai"},{"id":"fcp1-medical-negligence-confidentiality~ai-6","moduleId":"fcp1-medical-negligence-confidentiality","stem":"A physician is aware of a colleague's error that did not harm a patient. What should the physician consider before disclosing this information?","options":[{"id":"a","text":"The Bolam test"},{"id":"b","text":"The patient's right to confidentiality"},{"id":"c","text":"The public interest"},{"id":"d","text":"The Bolitho test"}],"answerId":"c","explanation":"Disclosure may be justified if it serves the public interest, such as preventing future harm.","kind":"integration","linkedModuleIds":["fcp1-medical-law-thailand"],"origin":"ai"}]};
